insert into public.ayahs (id, riwayah, surah_number, ayah_number, text, simple_text, juz, page, source) values
  ('warsh-1-1', 'warsh', 1, 1, 'ࡴ۬لْحَمْدُ لِلهِ رَبِّ ࡴ۬لْعَٰلَمِينَ', 'ࡴلحمد لله رب ࡴلعلمين', NULL, 1, 'local:warsh-text.json'),
  ('warsh-1-2', 'warsh', 1, 2, 'ࡰ۬لرَّحْمَٰنِ ࡴ۬لرَّحِيمِ', 'ࡰلرحمن ࡴلرحيم', NULL, 1, 'local:warsh-text.json'),
  ('warsh-1-3', 'warsh', 1, 3, 'مَلِكِ يَوْمِ ࡴ۬لدِّينِ࣌', 'ملك يوم ࡴلدين࣌', NULL, 1, 'local:warsh-text.json'),
  ('warsh-1-4', 'warsh', 1, 4, 'إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ࣌', 'إياك نعبد وإياك نستعين࣌', NULL, 1, 'local:warsh-text.json'),
  ('warsh-1-5', 'warsh', 1, 5, 'ࡲٜهْدِنَا ࡰ۬لصِّرَٰطَ ࡰ۬لْمُسْتَقِيمَ', 'ࡲهدنا ࡰلصرط ࡰلمستقيم', NULL, 1, 'local:warsh-text.json'),
  ('warsh-1-6', 'warsh', 1, 6, 'صِرَٰطَ ࡰ۬لذِينَ أَنْعَمْتَ عَلَيْهِمْ', 'صرط ࡰلذين أنعمت عليهم', NULL, 1, 'local:warsh-text.json'),
  ('warsh-1-7', 'warsh', 1, 7, 'غَيْرِ ࡴ۬لْمَغْضُوبِ عَلَيْهِمْ وَلَا ࡰ۬لضَّآلِّينَ࣌', 'غير ࡴلمغضوب عليهم ولا ࡰلضالين࣌', NULL, 1, 'local:warsh-text.json'),
  ('warsh-2-1', 'warsh', 2, 1, 'أَلَٓمِّٓ࣌ ذَٰلِكَ ࡰ۬لْكِتَٰبُ لَا رَيْبَ࣌ فِيهِ هُدىࣰ لِّلْمُتَّقِينَ', 'ألم࣌ ذلك ࡰلكتب لا ريب࣌ فيه هدى للمتقين', NULL, 2, 'local:warsh-text.json'),
  ('warsh-2-2', 'warsh', 2, 2, 'ࡰ۬لذِينَ يُومِنُونَ بِالْغَيْبِ وَيُقِيمُونَ ࡰ۬لصَّلَوٰةَ وَمِمَّا رَزَقْنَٰهُمْ يُنفِقُونَ࣌', 'ࡰلذين يومنون بالغيب ويقيمون ࡰلصلوة ومما رزقنهم ينفقون࣌', NULL, 2, 'local:warsh-text.json'),
  ('warsh-2-3', 'warsh', 2, 3, 'وَالذِينَ يُومِنُونَ بِمَآ أُنزِلَ إِلَيْكَ وَمَآ أُنزِلَ مِن قَبْلِكَ وَبِالَاخِرَةِ هُمْ يُوقِنُونَ', 'والذين يومنون بما أنزل إليك وما أنزل من قبلك وبالاخرة هم يوقنون', NULL, 2, 'local:warsh-text.json'),
  ('warsh-2-4', 'warsh', 2, 4, 'أُوْلَٰٓئِكَ عَلَىٰ هُدىࣰ مِّن رَّبِّهِمْ࣌ وَأُوْلَٰٓئِكَ هُمُ ࡲ۬لْمُفْلِحُونَ࣌', 'أولئك على هدى من ربهم࣌ وأولئك هم ࡲلمفلحون࣌', NULL, 2, 'local:warsh-text.json'),
  ('warsh-2-5', 'warsh', 2, 5, 'إِنَّ ࡰ۬لذِينَ كَفَرُواْ سَوَآءٌ عَلَيْهِمُۥٓ ءَآنذَرْتَهُمُۥٓ أَمْ لَمْ تُنذِرْهُمْ لَا يُومِنُونَ࣌', 'إن ࡰلذين كفروا سواء عليهم ءانذرتهم أم لم تنذرهم لا يومنون࣌', NULL, 3, 'local:warsh-text.json'),
  ('warsh-2-6', 'warsh', 2, 6, 'خَتَمَ ࡰ۬للَّهُ عَلَىٰ قُلُوبِهِمْ وَعَلَىٰ سَمْعِهِمْ࣌ وَعَلَىٰٓ أَبْصٜـٰرِهِمْ غِشَٰوَةࣱ࣌ وَلَهُمْ عَذَابٌ عَظِيمࣱ࣌', 'ختم ࡰلله على قلوبهم وعلى سمعهم࣌ وعلى أبصرهم غشوة࣌ ولهم عذاب عظيم࣌', NULL, 3, 'local:warsh-text.json'),
  ('warsh-2-7', 'warsh', 2, 7, 'وَمِنَ ࡰ۬لنَّاسِ مَنْ يَّقُولُ ءَامَنَّا بِاللَّهِ وَبِالْيَوْمِ ࡴ۬لَاخِرِ وَمَا هُم بِمُومِنِينَ࣌', 'ومن ࡰلناس من يقول ءامنا بالله وباليوم ࡴلاخر وما هم بمومنين࣌', NULL, 3, 'local:warsh-text.json'),
  ('warsh-2-8', 'warsh', 2, 8, 'يُخَٰدِعُونَ ࡰ۬للَّهَ وَالذِينَ ءَامَنُواْ࣌ وَمَا يُخَٰدِعُونَ إِلَّآ أَنفُسَهُمْ وَمَا يَشْعُرُونَ࣌', 'يخدعون ࡰلله والذين ءامنوا࣌ وما يخدعون إلا أنفسهم وما يشعرون࣌', NULL, 3, 'local:warsh-text.json'),
  ('warsh-2-9', 'warsh', 2, 9, 'فِے قُلُوبِهِم مَّرَضࣱ࣌ فَزَادَهُمُ ࡲ۬للَّهُ مَرَضاࣰ࣌ وَلَهُمْ عَذَابٌ ࡰلِيمُۢ بِمَا كَانُواْ يُكَذِّبُونَ࣌', 'فے قلوبهم مرض࣌ فزادهم ࡲلله مرضا࣌ ولهم عذاب ࡰليم بما كانوا يكذبون࣌', NULL, 3, 'local:warsh-text.json'),
  ('warsh-2-10', 'warsh', 2, 10, 'وَإِذَا قِيلَ لَهُمْ لَا تُفْسِدُواْ فِے ࡴ۬لَارْضِ قَالُوٓاْ إِنَّمَا نَحْنُ مُصْلِحُونَ࣌', 'وإذا قيل لهم لا تفسدوا فے ࡴلارض قالوا إنما نحن مصلحون࣌', NULL, 3, 'local:warsh-text.json'),
  ('warsh-2-11', 'warsh', 2, 11, 'أَلَآ إِنَّهُمْ هُمُ ࡲ۬لْمُفْسِدُونَ وَلَٰكِن لَّا يَشْعُرُونَ࣌', 'ألا إنهم هم ࡲلمفسدون ولكن لا يشعرون࣌', NULL, 3, 'local:warsh-text.json'),
  ('warsh-2-12', 'warsh', 2, 12, 'وَإِذَا قِيلَ لَهُمُۥٓ ءَامِنُواْ كَمَآ ءَامَنَ ࡰ۬لنَّاسُ قَالُوٓاْ أَنُومِنُ كَمَآ ءَامَنَ ࡰ۬لسُّفَهَآءُ࣌ ࡶَلَآ إِنَّهُمْ هُمُ ࡲ۬لسُّفَهَآءُ وَلَٰكِن لَّا يَعْلَمُونَ࣌', 'وإذا قيل لهم ءامنوا كما ءامن ࡰلناس قالوا أنومن كما ءامن ࡰلسفهاء࣌ ࡶلا إنهم هم ࡲلسفهاء ولكن لا يعلمون࣌', NULL, 3, 'local:warsh-text.json'),
  ('warsh-2-13', 'warsh', 2, 13, 'وَإِذَا لَقُواْ ࡲ۬لذِينَ ءَامَنُواْ قَالُوٓاْ ءَامَنَّا࣌ وَإِذَا خَلَوِاْ ࡴلَىٰ شَيَٰطِينِهِمْ قَالُوٓاْ إِنَّا مَعَكُمُۥٓ إِنَّمَا نَحْنُ مُسْتَهْزِءُونَ࣌', 'وإذا لقوا ࡲلذين ءامنوا قالوا ءامنا࣌ وإذا خلوا ࡴلى شيطينهم قالوا إنا معكم إنما نحن مستهزءون࣌', NULL, 3, 'local:warsh-text.json'),
  ('warsh-2-14', 'warsh', 2, 14, 'ࡰ۬للَّهُ يَسْتَهْزِۓُ بِهِمْ وَيَمُدُّهُمْ فِے طُغْيَٰنِهِمْ يَعْمَهُونَ࣌', 'ࡰلله يستهزے بهم ويمدهم فے طغينهم يعمهون࣌', NULL, 3, 'local:warsh-text.json'),
  ('warsh-2-15', 'warsh', 2, 15, 'أُوْلَٰٓئِكَ ࡰ۬لذِينَ ࡰٜشْتَرَوُاْ ࡲ۬لضَّلَٰلَةَ بِالْهُدٜىٰ فَمَا رَبِحَت تِّجَٰرَتُهُمْ وَمَا كَانُواْ مُهْتَدِينَ࣌', 'أولئك ࡰلذين ࡰشتروا ࡲلضللة بالهدى فما ربحت تجرتهم وما كانوا مهتدين࣌', NULL, 3, 'local:warsh-text.json'),
  ('warsh-2-16', 'warsh', 2, 16, '۞ مَثَلُهُمْ كَمَثَلِ ࡴ۬لذِے ࡴٜسْتَوْقَدَ نَاراࣰ فَلَمَّآ أَضَآءَتْ مَا حَوْلَهُۥ࣌ ذَهَبَ ࡰ۬للَّهُ بِنُورِهِمْ وَتَرَكَهُمْ فِے ظُلُمَٰتࣲ لَّا يُبْصِرُونَ࣌', 'مثلهم كمثل ࡴلذے ࡴستوقد نارا فلما أضاءت ما حوله࣌ ذهب ࡰلله بنورهم وتركهم فے ظلمت لا يبصرون࣌', NULL, 4, 'local:warsh-text.json'),
  ('warsh-2-17', 'warsh', 2, 17, 'صُمُّۢ بُكْمٌ عُمْيࣱ فَهُمْ لَا يَرْجِعُونَ࣌', 'صم بكم عمي فهم لا يرجعون࣌', NULL, 4, 'local:warsh-text.json'),
  ('warsh-2-18', 'warsh', 2, 18, 'أَوْ كَصَيِّبࣲ مِّنَ ࡰ۬لسَّمَآءِ فِيهِ ظُلُمَٰتࣱ وَرَعْدࣱ وَبَرْقࣱ࣌ يَجْعَلُونَ أَصَٰبِعَهُمْ فِےٓ ءَاذَانِهِم مِّنَ ࡰ۬لصَّوَٰعِقِ حَذَرَ ࡰ۬لْمَوْتِ࣌ وَاللَّهُ مُحِيطُۢ بِالْكٜـٰفِرِينَ࣌', 'أو كصيب من ࡰلسماء فيه ظلمت ورعد وبرق࣌ يجعلون أصبعهم فے ءاذانهم من ࡰلصوعق حذر ࡰلموت࣌ والله محيط بالكفرين࣌', NULL, 4, 'local:warsh-text.json'),
  ('warsh-2-19', 'warsh', 2, 19, 'يَكَادُ ࡲ۬لْبَرْقُ يَخْطَفُ أَبْصَٰرَهُمْ࣌ كُلَّمَآ أَضَآءَ لَهُم مَّشَوْاْ فِيهِ࣌ وَإِذَآ أَظْلَمَ عَلَيْهِمْ قَامُواْ࣌ وَلَوْ شَآءَ ࡰ۬للَّهُ لَذَهَبَ بِسَمْعِهِمْ وَأَبْصٜـٰرِهِمُۥٓ࣌ إِنَّ ࡰ۬للَّهَ عَلَىٰ كُلِّ شَےْءࣲ قَدِيرࣱ࣌', 'يكاد ࡲلبرق يخطف أبصرهم࣌ كلما أضاء لهم مشوا فيه࣌ وإذا أظلم عليهم قاموا࣌ ولو شاء ࡰلله لذهب بسمعهم وأبصرهم࣌ إن ࡰلله على كل شےء قدير࣌', NULL, 4, 'local:warsh-text.json'),
  ('warsh-2-20', 'warsh', 2, 20, 'يَٰٓأَيُّهَا ࡰ۬لنَّاسُ ࡲ࢈عْبُدُواْ رَبَّكُمُ ࡲ۬لذِے خَلَقَكُمْ وَالذِينَ مِن قَبْلِكُمْ لَعَلَّكُمْ تَتَّقُونَ࣌', 'يأيها ࡰلناس ࡲ࢈عبدوا ربكم ࡲلذے خلقكم والذين من قبلكم لعلكم تتقون࣌', NULL, 4, 'local:warsh-text.json'),
  ('warsh-2-21', 'warsh', 2, 21, 'ࡰ۬لذِے جَعَلَ لَكُمُ ࡲ۬لَارْضَ فِرَٰشاࣰ وَالسَّمَآءَ بِنَآءࣰ وَأَنزَلَ مِنَ ࡰ۬لسَّمَآءِ مَآءࣰ فَأَخْرَجَ بِهِۦ مِنَ ࡰ۬لثَّمَرَٰتِ رِزْقاࣰ لَّكُمْ࣌ فَلَا تَجْعَلُواْ لِلهِ أَندَاداࣰ وَأَنتُمْ تَعْلَمُونَ࣌', 'ࡰلذے جعل لكم ࡲلارض فرشا والسماء بناء وأنزل من ࡰلسماء ماء فأخرج به من ࡰلثمرت رزقا لكم࣌ فلا تجعلوا لله أندادا وأنتم تعلمون࣌', NULL, 4, 'local:warsh-text.json'),
  ('warsh-2-22', 'warsh', 2, 22, 'وَإِن كُنتُمْ فِے رَيْبࣲ مِّمَّا نَزَّلْنَا عَلَىٰ عَبْدِنَا فَاتُواْ بِسُورَةࣲ مِّن مِّثْلِهِۦ࣌ وَادْعُواْ شُهَدَآءَكُم مِّن دُونِ ࡴ۬للَّهِ إِن كُنتُمْ صَٰدِقِينَ࣌', 'وإن كنتم فے ريب مما نزلنا على عبدنا فاتوا بسورة من مثله࣌ وادعوا شهداءكم من دون ࡴلله إن كنتم صدقين࣌', NULL, 4, 'local:warsh-text.json'),
  ('warsh-2-23', 'warsh', 2, 23, 'فَإِن لَّمْ تَفْعَلُواْ وَلَن تَفْعَلُواْ فَاتَّقُواْ ࡲ۬لنَّارَ ࡰ۬لتِے وَقُودُهَا ࡰ۬لنَّاسُ وَالْحِجَارَةُ࣌ أُعِدَّتْ لِلْكٜـٰفِرِينَ࣌', 'فإن لم تفعلوا ولن تفعلوا فاتقوا ࡲلنار ࡰلتے وقودها ࡰلناس والحجارة࣌ أعدت للكفرين࣌', NULL, 4, 'local:warsh-text.json'),
  ('warsh-2-24', 'warsh', 2, 24, 'وَبَشِّرِ ࡴ۬لذِينَ ءَامَنُواْ وَعَمِلُواْ ࡲ۬لصَّٰلِحَٰتِ أَنَّ لَهُمْ جَنَّٰتࣲ تَجْرِے مِن تَحْتِهَا ࡰ۬لَانْهَٰرُ࣌ كُلَّمَا رُزِقُواْ مِنْهَا مِن ثَمَرَةࣲ رِّزْقاࣰ قَالُواْ هَٰذَا ࡰ۬لذِے رُزِقْنَا مِن قَبْلُ࣌ وَأُتُواْ بِهِۦ مُتَشَٰبِهاࣰ࣌ وَلَهُمْ فِيهَآ أَزْوَٰجࣱ مُّطَهَّرَةࣱ࣌ وَهُمْ فِيهَا خَٰلِدُونَ࣌', 'وبشر ࡴلذين ءامنوا وعملوا ࡲلصلحت أن لهم جنت تجرے من تحتها ࡰلانهر࣌ كلما رزقوا منها من ثمرة رزقا قالوا هذا ࡰلذے رزقنا من قبل࣌ وأتوا به متشبها࣌ ولهم فيها أزوج مطهرة࣌ وهم فيها خلدون࣌', NULL, 5, 'local:warsh-text.json'),
  ('warsh-2-25', 'warsh', 2, 25, '۞ إِنَّ ࡰ۬للَّهَ لَا يَسْتَحْيِۦٓ أَنْ يَّضْرِبَ مَثَلاࣰ مَّا بَعُوضَةࣰ فَمَا فَوْقَهَا࣌ فَأَمَّا ࡰ۬لذِينَ ءَامَنُواْ فَيَعْلَمُونَ أَنَّهُ ࡲ۬لْحَقُّ مِن رَّبِّهِمْ࣌ وَأَمَّا ࡰ۬لذِينَ كَفَرُواْ فَيَقُولُونَ مَاذَآ أَرَادَ ࡰ۬للَّهُ بِهَٰذَا مَثَلاࣰ࣌ يُضِلُّ بِهِۦ كَثِيراࣰ وَيَهْدِے بِهِۦ كَثِيراࣰ࣌ وَمَا يُضِلُّ بِهِۦٓ إِلَّا ࡰ۬لْفَٰسِقِينَ', 'إن ࡰلله لا يستحي أن يضرب مثلا ما بعوضة فما فوقها࣌ فأما ࡰلذين ءامنوا فيعلمون أنه ࡲلحق من ربهم࣌ وأما ࡰلذين كفروا فيقولون ماذا أراد ࡰلله بهذا مثلا࣌ يضل به كثيرا ويهدے به كثيرا࣌ وما يضل به إلا ࡰلفسقين', NULL, 5, 'local:warsh-text.json'),
  ('warsh-2-26', 'warsh', 2, 26, 'ࡰ۬لذِينَ يَنقُضُونَ عَهْدَ ࡰ۬للَّهِ مِنۢ بَعْدِ مِيثَٰقِهِۦ وَيَقْطَعُونَ مَآ أَمَرَ ࡰ۬للَّهُ بِهِۦٓ أَنْ يُّوصَلَ وَيُفْسِدُونَ فِے ࡴ۬لَارْضِ࣌ أُوْلَٰٓئِكَ هُمُ ࡲ۬لْخَٰسِرُونَ࣌', 'ࡰلذين ينقضون عهد ࡰلله من بعد ميثقه ويقطعون ما أمر ࡰلله به أن يوصل ويفسدون فے ࡴلارض࣌ أولئك هم ࡲلخسرون࣌', NULL, 5, 'local:warsh-text.json'),
  ('warsh-2-27', 'warsh', 2, 27, 'كَيْفَ تَكْفُرُونَ بِاللَّهِ وَكُنتُمُۥٓ أَمْوَٰتاࣰ فَأَحْيٜاكُمْ ثُمَّ يُمِيتُكُمْ࣌ ثُمَّ يُحْيِيكُمْ ثُمَّ إِلَيْهِ تُرْجَعُونَ࣌', 'كيف تكفرون بالله وكنتم أموتا فأحياكم ثم يميتكم࣌ ثم يحييكم ثم إليه ترجعون࣌', NULL, 5, 'local:warsh-text.json'),
  ('warsh-2-28', 'warsh', 2, 28, 'هُوَ ࡰ۬لذِے خَلَقَ لَكُم مَّا فِے ࡴ۬لَارْضِ جَمِيعاࣰ࣌ ثُمَّ ࡰٜسْتَوٜىٰٓ إِلَى ࡰ۬لسَّمَآءِ فَسَوّٜيٰهُنَّ سَبْعَ سَمَٰوَٰتࣲ࣌ وَهُوَ بِكُلِّ شَےْءٍ عَلِيمࣱ࣌', 'هو ࡰلذے خلق لكم ما فے ࡴلارض جميعا࣌ ثم ࡰستوى إلى ࡰلسماء فسويهن سبع سموت࣌ وهو بكل شےء عليم࣌', NULL, 5, 'local:warsh-text.json'),
  ('warsh-2-29', 'warsh', 2, 29, 'وَإِذْ قَالَ رَبُّكَ لِلْمَلَٰٓئِكَةِ إِنِّے جَاعِلࣱ فِے ࡴ۬لَارْضِ خَلِيفَةࣰ࣌ قَالُوٓاْ أَتَجْعَلُ فِيهَا مَنْ يُّفْسِدُ فِيهَا وَيَسْفِكُ ࡲ۬لدِّمَآءَ وَنَحْنُ نُسَبِّحُ بِحَمْدِكَ وَنُقَدِّسُ لَكَ࣌ قَالَ إِنِّيَ أَعْلَمُ مَا لَا تَعْلَمُونَ࣌', 'وإذ قال ربك للملئكة إنے جاعل فے ࡴلارض خليفة࣌ قالوا أتجعل فيها من يفسد فيها ويسفك ࡲلدماء ونحن نسبح بحمدك ونقدس لك࣌ قال إني أعلم ما لا تعلمون࣌', NULL, 6, 'local:warsh-text.json'),
  ('warsh-2-30', 'warsh', 2, 30, 'وَعَلَّمَ ءَادَمَ ࡰ۬لَاسْمَآءَ كُلَّهَا ثُمَّ عَرَضَهُمْ عَلَى ࡰ۬لْمَلَٰٓئِكَةِ فَقَالَ أَنۢبِـُٔونِے بِأَسْمَآءِ هَٰٓؤُلَآءِ ان كُنتُمْ صَٰدِقِينَ࣌', 'وعلم ءادم ࡰلاسماء كلها ثم عرضهم على ࡰلملئكة فقال أنبونے بأسماء هؤلاء ان كنتم صدقين࣌', NULL, 6, 'local:warsh-text.json'),
  ('warsh-2-31', 'warsh', 2, 31, 'قَالُواْ سُبْحَٰنَكَ لَا عِلْمَ لَنَآ إِلَّا مَا عَلَّمْتَنَآ إِنَّكَ أَنتَ ࡰ۬لْعَلِيمُ ࡲ۬لْحَكِيمُ࣌', 'قالوا سبحنك لا علم لنا إلا ما علمتنا إنك أنت ࡰلعليم ࡲلحكيم࣌', NULL, 6, 'local:warsh-text.json'),
  ('warsh-2-32', 'warsh', 2, 32, 'قَالَ يَٰٓـَٔادَمُ أَنۢبِئْهُم بِأَسْمَآئِهِمْ࣌ فَلَمَّآ أَنۢبَأَهُم بِأَسْمَآئِهِمْ قَالَ أَلَمَ ࡰقُل لَّكُمُۥٓ إِنِّيَ أَعْلَمُ غَيْبَ ࡰ۬لسَّمَٰوَٰتِ وَالَارْضِ وَأَعْلَمُ مَا تُبْدُونَ وَمَا كُنتُمْ تَكْتُمُونَ࣌', 'قال يادم أنبئهم بأسمائهم࣌ فلما أنبأهم بأسمائهم قال ألم ࡰقل لكم إني أعلم غيب ࡰلسموت والارض وأعلم ما تبدون وما كنتم تكتمون࣌', NULL, 6, 'local:warsh-text.json'),
  ('warsh-2-33', 'warsh', 2, 33, '۞ وَإِذْ قُلْنَا لِلْمَلَٰٓئِكَةِ ࡴ࢈سْجُدُواْ لِأٓدَمَ فَسَجَدُوٓاْ࣌ إِلَّآ إِبْلِيسَ أَبٜىٰ وَاسْتَكْبَرَ وَكَانَ مِنَ ࡰ۬لْكٜـٰفِرِينَ࣌', 'وإذ قلنا للملئكة ࡴ࢈سجدوا لأدم فسجدوا࣌ إلا إبليس أبى واستكبر وكان من ࡰلكفرين࣌', NULL, 6, 'local:warsh-text.json'),
  ('warsh-2-34', 'warsh', 2, 34, 'وَقُلْنَا يَٰٓـَٔادَمُ ࡲ࢈سْكُنَ ࡰنتَ وَزَوْجُكَ ࡰ۬لْجَنَّةَ وَكُلَا مِنْهَا رَغَداً حَيْثُ شِئْتُمَا࣌ وَلَا تَقْرَبَا هَٰذِهِ ࡴ۬لشَّجَرَةَ فَتَكُونَا مِنَ ࡰ۬لظَّٰلِمِينَ࣌', 'وقلنا يادم ࡲ࢈سكن ࡰنت وزوجك ࡰلجنة وكلا منها رغدا حيث شئتما࣌ ولا تقربا هذه ࡴلشجرة فتكونا من ࡰلظلمين࣌', NULL, 6, 'local:warsh-text.json'),
  ('warsh-2-35', 'warsh', 2, 35, 'فَأَزَلَّهُمَا ࡰ۬لشَّيْطَٰنُ عَنْهَا فَأَخْرَجَهُمَا مِمَّا كَانَا فِيهِ࣌ وَقُلْنَا ࡰٜهْبِطُواْ࣌ بَعْضُكُمْ لِبَعْضٍ عَدُوࣱّ࣌ وَلَكُمْ فِے ࡴ۬لَارْضِ مُسْتَقَرࣱّ وَمَتَٰعٌ ࡴلَىٰ حِينࣲ࣌', 'فأزلهما ࡰلشيطن عنها فأخرجهما مما كانا فيه࣌ وقلنا ࡰهبطوا࣌ بعضكم لبعض عدو࣌ ولكم فے ࡴلارض مستقر ومتع ࡴلى حين࣌', NULL, 6, 'local:warsh-text.json'),
  ('warsh-2-36', 'warsh', 2, 36, 'فَتَلَقّٜىٰٓ ءَادَمُ مِن رَّبِّهِۦ كَلِمَٰتࣲ فَتَابَ عَلَيْهِ࣌ إِنَّهُۥ هُوَ ࡰ۬لتَّوَّابُ ࡲ۬لرَّحِيمُ࣌', 'فتلقى ءادم من ربه كلمت فتاب عليه࣌ إنه هو ࡰلتواب ࡲلرحيم࣌', NULL, 6, 'local:warsh-text.json'),
  ('warsh-2-37', 'warsh', 2, 37, 'قُلْنَا ࡰٜهْبِطُواْ مِنْهَا جَمِيعاࣰ࣌ فَإِمَّا يَاتِيَنَّكُم مِّنِّے هُدىࣰ فَمَن تَبِعَ هُدٜايَ فَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ࣌', 'قلنا ࡰهبطوا منها جميعا࣌ فإما ياتينكم منے هدى فمن تبع هداي فلا خوف عليهم ولا هم يحزنون࣌', NULL, 7, 'local:warsh-text.json'),
  ('warsh-2-38', 'warsh', 2, 38, 'وَالذِينَ كَفَرُواْ وَكَذَّبُواْ بِـَٔايَٰتِنَآ أُوْلَٰٓئِكَ أَصْحَٰبُ ࡲ۬لنّٜارِ هُمْ فِيهَا خَٰلِدُونَ࣌', 'والذين كفروا وكذبوا بايتنا أولئك أصحب ࡲلنار هم فيها خلدون࣌', NULL, 7, 'local:warsh-text.json'),
  ('warsh-2-39', 'warsh', 2, 39, 'يَٰبَنِےٓ إِسْرَآءِيلَ ࡸَذْكُرُواْ نِعْمَتِيَ ࡰ۬لتِےٓ أَنْعَمْتُ عَلَيْكُمْ وَأَوْفُواْ بِعَهْدِےٓ أُوفِ بِعَهْدِكُمْ وَإِيَّٰيَ فَارْهَبُونِ࣌', 'يبنے إسراءيل ࡸذكروا نعمتي ࡰلتے أنعمت عليكم وأوفوا بعهدے أوف بعهدكم وإيي فارهبون࣌', NULL, 7, 'local:warsh-text.json'),
  ('warsh-2-40', 'warsh', 2, 40, 'وَءَامِنُواْ بِمَآ أَنزَلْتُ مُصَدِّقاࣰ لِّمَا مَعَكُمْ وَلَا تَكُونُوٓاْ أَوَّلَ كَافِرِۢ بِهِۦ࣌ وَلَا تَشْتَرُواْ بِـَٔايَٰتِے ثَمَناࣰ قَلِيلاࣰ وَإِيَّٰيَ فَاتَّقُونِ࣌', 'وءامنوا بما أنزلت مصدقا لما معكم ولا تكونوا أول كافر به࣌ ولا تشتروا بايتے ثمنا قليلا وإيي فاتقون࣌', NULL, 7, 'local:warsh-text.json'),
  ('warsh-2-41', 'warsh', 2, 41, '۞ وَلَا تَلْبِسُواْ ࡲ۬لْحَقَّ بِالْبَٰطِلِ وَتَكْتُمُواْ ࡲ۬لْحَقَّ وَأَنتُمْ تَعْلَمُونَ࣌', 'ولا تلبسوا ࡲلحق بالبطل وتكتموا ࡲلحق وأنتم تعلمون࣌', NULL, 7, 'local:warsh-text.json'),
  ('warsh-2-42', 'warsh', 2, 42, 'وَأَقِيمُواْ ࡲ۬لصَّلَوٰةَ وَءَاتُواْ ࡲ۬لزَّكَوٰةَ࣌ وَارْكَعُواْ مَعَ ࡰ۬لرَّٰكِعِينَ࣌', 'وأقيموا ࡲلصلوة وءاتوا ࡲلزكوة࣌ واركعوا مع ࡰلركعين࣌', NULL, 7, 'local:warsh-text.json'),
  ('warsh-2-43', 'warsh', 2, 43, 'أَتَامُرُونَ ࡰ۬لنَّاسَ بِالْبِرِّ وَتَنسَوْنَ أَنفُسَكُمْ وَأَنتُمْ تَتْلُونَ ࡰ۬لْكِتَٰبَ࣌ أَفَلَا تَعْقِلُونَ࣌', 'أتامرون ࡰلناس بالبر وتنسون أنفسكم وأنتم تتلون ࡰلكتب࣌ أفلا تعقلون࣌', NULL, 7, 'local:warsh-text.json'),
  ('warsh-2-44', 'warsh', 2, 44, 'وَاسْتَعِينُواْ بِالصَّبْرِ وَالصَّلَوٰةِ࣌ وَإِنَّهَا لَكَبِيرَةٌ ࡴلَّا عَلَى ࡰ۬لْخَٰشِعِينَ', 'واستعينوا بالصبر والصلوة࣌ وإنها لكبيرة ࡴلا على ࡰلخشعين', NULL, 7, 'local:warsh-text.json'),
  ('warsh-2-45', 'warsh', 2, 45, 'ࡰ۬لذِينَ يَظُنُّونَ أَنَّهُم مُّلَٰقُواْ رَبِّهِمْ وَأَنَّهُمُۥٓ إِلَيْهِ رَٰجِعُونَ࣌', 'ࡰلذين يظنون أنهم ملقوا ربهم وأنهم إليه رجعون࣌', NULL, 7, 'local:warsh-text.json'),
  ('warsh-2-46', 'warsh', 2, 46, 'يَٰبَنِےٓ إِسْرَآءِيلَ ࡸَذْكُرُواْ نِعْمَتِيَ ࡰ۬لتِےٓ أَنْعَمْتُ عَلَيْكُمْ وَأَنِّے فَضَّلْتُكُمْ عَلَى ࡰ۬لْعَٰلَمِينَ࣌', 'يبنے إسراءيل ࡸذكروا نعمتي ࡰلتے أنعمت عليكم وأنے فضلتكم على ࡰلعلمين࣌', NULL, 7, 'local:warsh-text.json'),
  ('warsh-2-47', 'warsh', 2, 47, 'وَاتَّقُواْ يَوْماࣰ لَّا تَجْزِے نَفْسٌ عَن نَّفْسࣲ شَيْـٔاࣰ وَلَا يُقْبَلُ مِنْهَا شَفَٰعَةࣱ وَلَا يُوخَذُ مِنْهَا عَدْلࣱ وَلَا هُمْ يُنصَرُونَ࣌', 'واتقوا يوما لا تجزے نفس عن نفس شيا ولا يقبل منها شفعة ولا يوخذ منها عدل ولا هم ينصرون࣌', NULL, 7, 'local:warsh-text.json'),
  ('warsh-2-48', 'warsh', 2, 48, 'وَإِذْ نَجَّيْنَٰكُم مِّنَ اٰلِ فِرْعَوْنَ يَسُومُونَكُمْ سُوٓءَ ࡰ۬لْعَذَابِ يُذَبِّحُونَ أَبْنَآءَكُمْ وَيَسْتَحْيُونَ نِسَآءَكُمْ࣌ وَفِے ذَٰلِكُم بَلَآءࣱ مِّن رَّبِّكُمْ عَظِيمࣱ࣌', 'وإذ نجينكم من ال فرعون يسومونكم سوء ࡰلعذاب يذبحون أبناءكم ويستحيون نساءكم࣌ وفے ذلكم بلاء من ربكم عظيم࣌', NULL, 8, 'local:warsh-text.json'),
  ('warsh-2-49', 'warsh', 2, 49, 'وَإِذْ فَرَقْنَا بِكُمُ ࡲ۬لْبَحْرَ فَأَنجَيْنَٰكُمْ وَأَغْرَقْنَآ ءَالَ فِرْعَوْنَ وَأَنتُمْ تَنظُرُونَ࣌', 'وإذ فرقنا بكم ࡲلبحر فأنجينكم وأغرقنا ءال فرعون وأنتم تنظرون࣌', NULL, 8, 'local:warsh-text.json'),
  ('warsh-2-50', 'warsh', 2, 50, 'وَإِذْ وَٰعَدْنَا مُوسٜىٰٓ أَرْبَعِينَ لَيْلَةࣰ ثُمَّ ࡰٜتَّخَذتُّمُ ࡲ۬لْعِجْلَ مِنۢ بَعْدِهِۦ وَأَنتُمْ ظَٰلِمُونَ࣌', 'وإذ وعدنا موسى أربعين ليلة ثم ࡰتخذتم ࡲلعجل من بعده وأنتم ظلمون࣌', NULL, 8, 'local:warsh-text.json'),
  ('warsh-2-51', 'warsh', 2, 51, 'ثُمَّ عَفَوْنَا عَنكُم مِّنۢ بَعْدِ ذَٰلِكَ لَعَلَّكُمْ تَشْكُرُونَ࣌', 'ثم عفونا عنكم من بعد ذلك لعلكم تشكرون࣌', NULL, 8, 'local:warsh-text.json'),
  ('warsh-2-52', 'warsh', 2, 52, 'وَإِذَ اٰتَيْنَا مُوسَى ࡰ۬لْكِتَٰبَ࣌ وَالْفُرْقَانَ لَعَلَّكُمْ تَهْتَدُونَ࣌', 'وإذ اتينا موسى ࡰلكتب࣌ والفرقان لعلكم تهتدون࣌', NULL, 8, 'local:warsh-text.json'),
  ('warsh-2-53', 'warsh', 2, 53, '۞ وَإِذْ قَالَ مُوسٜىٰ لِقَوْمِهِۦ يَٰقَوْمِ إِنَّكُمْ ظَلَمْتُمُۥٓ أَنفُسَكُم بِاتِّخَاذِكُمُ ࡲ۬لْعِجْلَ فَتُوبُوٓاْ إِلَىٰ بَارِئِكُمْ فَاقْتُلُوٓاْ أَنفُسَكُمْ࣌ ذَٰلِكُمْ خَيْرࣱ لَّكُمْ عِندَ بَارِئِكُمْ࣌ فَتَابَ عَلَيْكُمُۥٓ࣌ إِنَّهُۥ هُوَ ࡰ۬لتَّوَّابُ ࡲ۬لرَّحِيمُ࣌', 'وإذ قال موسى لقومه يقوم إنكم ظلمتم أنفسكم باتخاذكم ࡲلعجل فتوبوا إلى بارئكم فاقتلوا أنفسكم࣌ ذلكم خير لكم عند بارئكم࣌ فتاب عليكم࣌ إنه هو ࡰلتواب ࡲلرحيم࣌', NULL, 8, 'local:warsh-text.json'),
  ('warsh-2-54', 'warsh', 2, 54, 'وَإِذْ قُلْتُمْ يَٰمُوسٜىٰ لَن نُّومِنَ لَكَ حَتَّىٰ نَرَى ࡰ۬للَّهَ جَهْرَةࣰ فَأَخَذَتْكُمُ ࡲ۬لصَّٰعِقَةُ وَأَنتُمْ تَنظُرُونَ࣌', 'وإذ قلتم يموسى لن نومن لك حتى نرى ࡰلله جهرة فأخذتكم ࡲلصعقة وأنتم تنظرون࣌', NULL, 8, 'local:warsh-text.json'),
  ('warsh-2-55', 'warsh', 2, 55, 'ثُمَّ بَعَثْنَٰكُم مِّنۢ بَعْدِ مَوْتِكُمْ لَعَلَّكُمْ تَشْكُرُونَ࣌', 'ثم بعثنكم من بعد موتكم لعلكم تشكرون࣌', NULL, 8, 'local:warsh-text.json'),
  ('warsh-2-56', 'warsh', 2, 56, 'وَظَلَّلْنَا عَلَيْكُمُ ࡲ۬لْغَمَٰمَ وَأَنزَلْنَا عَلَيْكُمُ ࡲ۬لْمَنَّ وَالسَّلْوٜىٰ࣌ كُلُواْ مِن طَيِّبَٰتِ مَا رَزَقْنَٰكُمْ࣌ وَمَا ظَلَمُونَا࣌ وَلَٰكِن كَانُوٓاْ أَنفُسَهُمْ يَظْلِمُونَ࣌', 'وظللنا عليكم ࡲلغمم وأنزلنا عليكم ࡲلمن والسلوى࣌ كلوا من طيبت ما رزقنكم࣌ وما ظلمونا࣌ ولكن كانوا أنفسهم يظلمون࣌', NULL, 8, 'local:warsh-text.json'),
  ('warsh-2-57', 'warsh', 2, 57, 'وَإِذْ قُلْنَا ࡸَدْخُلُواْ هَٰذِهِ ࡴ۬لْقَرْيَةَ فَكُلُواْ مِنْهَا حَيْثُ شِئْتُمْ رَغَداࣰ وَادْخُلُواْ ࡲ۬لْبَابَ سُجَّداࣰ وَقُولُواْ حِطَّةࣱ يُغْفَرْ لَكُمْ خَطَٰيٜـٰكُمْ࣌ وَسَنَزِيدُ ࡲ۬لْمُحْسِنِينَ࣌', 'وإذ قلنا ࡸدخلوا هذه ࡴلقرية فكلوا منها حيث شئتم رغدا وادخلوا ࡲلباب سجدا وقولوا حطة يغفر لكم خطيكم࣌ وسنزيد ࡲلمحسنين࣌', NULL, 9, 'local:warsh-text.json'),
  ('warsh-2-58', 'warsh', 2, 58, 'فَبَدَّلَ ࡰ۬لذِينَ ظَلَمُواْ قَوْلاً غَيْرَ ࡰ۬لذِے قِيلَ لَهُمْ فَأَنزَلْنَا عَلَى ࡰ۬لذِينَ ظَلَمُواْ رِجْزاࣰ مِّنَ ࡰ۬لسَّمَآءِ بِمَا كَانُواْ يَفْسُقُونَ࣌', 'فبدل ࡰلذين ظلموا قولا غير ࡰلذے قيل لهم فأنزلنا على ࡰلذين ظلموا رجزا من ࡰلسماء بما كانوا يفسقون࣌', NULL, 9, 'local:warsh-text.json'),
  ('warsh-2-59', 'warsh', 2, 59, '۞ وَإِذِ ࡴٜسْتَسْقٜىٰ مُوسٜىٰ لِقَوْمِهِۦ فَقُلْنَا ࡰٜضْرِب بِّعَصَاكَ ࡰ۬لْحَجَرَ࣌ فَانفَجَرَتْ مِنْهُ ࡲٜثْنَتَا عَشْرَةَ عَيْناࣰ࣌ قَدْ عَلِمَ كُلُّ أُنَاسࣲ مَّشْرَبَهُمْ࣌ كُلُواْ وَاشْرَبُواْ مِن رِّزْقِ ࡴ۬للَّهِ࣌ وَلَا تَعْثَوْاْ فِے ࡴ۬لَارْضِ مُفْسِدِينَ࣌', 'وإذ ࡴستسقى موسى لقومه فقلنا ࡰضرب بعصاك ࡰلحجر࣌ فانفجرت منه ࡲثنتا عشرة عينا࣌ قد علم كل أناس مشربهم࣌ كلوا واشربوا من رزق ࡴلله࣌ ولا تعثوا فے ࡴلارض مفسدين࣌', NULL, 9, 'local:warsh-text.json'),
  ('warsh-2-60', 'warsh', 2, 60, 'وَإِذْ قُلْتُمْ يَٰمُوسٜىٰ لَن نَّصْبِرَ عَلَىٰ طَعَامࣲ وَٰحِدࣲ فَادْعُ لَنَا رَبَّكَ يُخْرِجْ لَنَا مِمَّا تُنۢبِتُ ࡲ۬لَارْضُ مِنۢ بَقْلِهَا وَقِثَّآئِهَا وَفُومِهَا وَعَدَسِهَا وَبَصَلِهَا࣌ قَالَ أَتَسْتَبْدِلُونَ ࡰ۬لذِے هُوَ أَدْنٜىٰ بِالذِے هُوَ خَيْرٌ࣌ ࡴٜهْبِطُواْ مِصْراࣰ فَإِنَّ لَكُم مَّا سَأَلْتُمْ࣌ وَضُرِبَتْ عَلَيْهِمُ ࡲ۬لذِّلَّةُ وَالْمَسْكَنَةُ وَبَآءُو بِغَضَبࣲ مِّنَ ࡰ۬للَّهِ࣌ ذَٰلِكَ بِأَنَّهُمْ كَانُواْ يَكْفُرُونَ بِـَٔايَٰتِ ࡴ۬للَّهِ وَيَقْتُلُونَ ࡰ۬لنَّبِيٓـِٕۑنَ بِغَيْرِ ࡴ۬لْحَقِّ࣌ ذَٰلِكَ بِمَا عَصَواْ وَّكَانُواْ يَعْتَدُونَ࣌', 'وإذ قلتم يموسى لن نصبر على طعام وحد فادع لنا ربك يخرج لنا مما تنبت ࡲلارض من بقلها وقثائها وفومها وعدسها وبصلها࣌ قال أتستبدلون ࡰلذے هو أدنى بالذے هو خير࣌ ࡴهبطوا مصرا فإن لكم ما سألتم࣌ وضربت عليهم ࡲلذلة والمسكنة وباءو بغضب من ࡰلله࣌ ذلك بأنهم كانوا يكفرون بايت ࡴلله ويقتلون ࡰلنبيۑن بغير ࡴلحق࣌ ذلك بما عصوا وكانوا يعتدون࣌', NULL, 9, 'local:warsh-text.json'),
  ('warsh-2-61', 'warsh', 2, 61, 'إِنَّ ࡰ۬لذِينَ ءَامَنُواْ وَالذِينَ هَادُواْ وَالنَّصَٰرٜىٰ وَالصَّٰبِينَ مَنَ اٰمَنَ بِاللَّهِ وَالْيَوْمِ ࡴ۬لَاخِرِ وَعَمِلَ صَٰلِحاࣰ فَلَهُمُۥٓ أَجْرُهُمْ عِندَ رَبِّهِمْ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ࣌', 'إن ࡰلذين ءامنوا والذين هادوا والنصرى والصبين من امن بالله واليوم ࡴلاخر وعمل صلحا فلهم أجرهم عند ربهم ولا خوف عليهم ولا هم يحزنون࣌', NULL, 10, 'local:warsh-text.json'),
  ('warsh-2-62', 'warsh', 2, 62, 'وَإِذَ ࡰخَذْنَا مِيثَٰقَكُمْ وَرَفَعْنَا فَوْقَكُمُ ࡲ۬لطُّورَ࣌ خُذُواْ مَآ ءَاتَيْنَٰكُم بِقُوَّةࣲ وَاذْكُرُواْ مَا فِيهِ لَعَلَّكُمْ تَتَّقُونَ࣌', 'وإذ ࡰخذنا ميثقكم ورفعنا فوقكم ࡲلطور࣌ خذوا ما ءاتينكم بقوة واذكروا ما فيه لعلكم تتقون࣌', NULL, 10, 'local:warsh-text.json'),
  ('warsh-2-63', 'warsh', 2, 63, 'ثُمَّ تَوَلَّيْتُم مِّنۢ بَعْدِ ذَٰلِكَ࣌ فَلَوْلَا فَضْلُ ࡲ۬للَّهِ عَلَيْكُمْ وَرَحْمَتُهُۥ لَكُنتُم مِّنَ ࡰ۬لْخَٰسِرِينَ࣌', 'ثم توليتم من بعد ذلك࣌ فلولا فضل ࡲلله عليكم ورحمته لكنتم من ࡰلخسرين࣌', NULL, 10, 'local:warsh-text.json'),
  ('warsh-2-64', 'warsh', 2, 64, 'وَلَقَدْ عَلِمْتُمُ ࡲ۬لذِينَ ࡰٜعْتَدَوْاْ مِنكُمْ فِے ࡴ۬لسَّبْتِ فَقُلْنَا لَهُمْ كُونُواْ قِرَدَةً خَٰسِـِٕينَ࣌', 'ولقد علمتم ࡲلذين ࡰعتدوا منكم فے ࡴلسبت فقلنا لهم كونوا قردة خسين࣌', NULL, 10, 'local:warsh-text.json'),
  ('warsh-2-65', 'warsh', 2, 65, 'فَجَعَلْنَٰهَا نَكَٰلاࣰ لِّمَا بَيْنَ يَدَيْهَا وَمَا خَلْفَهَا وَمَوْعِظَةࣰ لِّلْمُتَّقِينَ࣌', 'فجعلنها نكلا لما بين يديها وما خلفها وموعظة للمتقين࣌', NULL, 10, 'local:warsh-text.json'),
  ('warsh-2-66', 'warsh', 2, 66, '۞ وَإِذْ قَالَ مُوسٜىٰ لِقَوْمِهِۦٓ إِنَّ ࡰ۬للَّهَ يَامُرُكُمُۥٓ أَن تَذْبَحُواْ بَقَرَةࣰ࣌ قَالُوٓاْ أَتَتَّخِذُنَا هُزُؤاࣰ࣌ قَالَ أَعُوذُ بِاللَّهِ أَنَ ࡰكُونَ مِنَ ࡰ۬لْجَٰهِلِينَ࣌', 'وإذ قال موسى لقومه إن ࡰلله يامركم أن تذبحوا بقرة࣌ قالوا أتتخذنا هزؤا࣌ قال أعوذ بالله أن ࡰكون من ࡰلجهلين࣌', NULL, 10, 'local:warsh-text.json'),
  ('warsh-2-67', 'warsh', 2, 67, 'قَالُواْ ࡲ࢈دْعُ لَنَا رَبَّكَ يُبَيِّن لَّنَا مَا هِيَ࣌ قَالَ إِنَّهُۥ يَقُولُ إِنَّهَا بَقَرَةࣱ لَّا فَارِضࣱ وَلَا بِكْرٌ࣌ عَوَانُۢ بَيْنَ ذَٰلِكَ࣌ فَافْعَلُواْ مَا تُومَرُونَ࣌', 'قالوا ࡲ࢈دع لنا ربك يبين لنا ما هي࣌ قال إنه يقول إنها بقرة لا فارض ولا بكر࣌ عوان بين ذلك࣌ فافعلوا ما تومرون࣌', NULL, 10, 'local:warsh-text.json'),
  ('warsh-2-68', 'warsh', 2, 68, 'قَالُواْ ࡲ࢈دْعُ لَنَا رَبَّكَ يُبَيِّن لَّنَا مَا لَوْنُهَا࣌ قَالَ إِنَّهُۥ يَقُولُ إِنَّهَا بَقَرَةࣱ صَفْرَآءُ فَاقِعࣱ لَّوْنُهَا࣌ تَسُرُّ ࡲ۬لنَّٰظِرِينَ࣌', 'قالوا ࡲ࢈دع لنا ربك يبين لنا ما لونها࣌ قال إنه يقول إنها بقرة صفراء فاقع لونها࣌ تسر ࡲلنظرين࣌', NULL, 10, 'local:warsh-text.json'),
  ('warsh-2-69', 'warsh', 2, 69, 'قَالُواْ ࡲ࢈دْعُ لَنَا رَبَّكَ يُبَيِّن لَّنَا مَا هِيَ إِنَّ ࡰ۬لْبَقَرَ تَشَٰبَهَ عَلَيْنَا وَإِنَّآ إِن شَآءَ ࡰ۬للَّهُ لَمُهْتَدُونَ࣌', 'قالوا ࡲ࢈دع لنا ربك يبين لنا ما هي إن ࡰلبقر تشبه علينا وإنا إن شاء ࡰلله لمهتدون࣌', NULL, 11, 'local:warsh-text.json'),
  ('warsh-2-70', 'warsh', 2, 70, 'قَالَ إِنَّهُۥ يَقُولُ إِنَّهَا بَقَرَةࣱ لَّا ذَلُولࣱ تُثِيرُ ࡲ۬لَارْضَ وَلَا تَسْقِے ࡴ۬لْحَرْثَ࣌ مُسَلَّمَةࣱ لَّا شِيَةَ فِيهَا࣌ قَالُواْ ࡲ۬لَٰنَ جِئْتَ بِالْحَقِّ࣌ فَذَبَحُوهَا وَمَا كَادُواْ يَفْعَلُونَ࣌', 'قال إنه يقول إنها بقرة لا ذلول تثير ࡲلارض ولا تسقے ࡴلحرث࣌ مسلمة لا شية فيها࣌ قالوا ࡲلن جئت بالحق࣌ فذبحوها وما كادوا يفعلون࣌', NULL, 11, 'local:warsh-text.json'),
  ('warsh-2-71', 'warsh', 2, 71, 'وَإِذْ قَتَلْتُمْ نَفْساࣰ فَادَّٰرْٔتُمْ فِيهَا࣌ وَاللَّهُ مُخْرِجࣱ مَّا كُنتُمْ تَكْتُمُونَ࣌', 'وإذ قتلتم نفسا فادرتم فيها࣌ والله مخرج ما كنتم تكتمون࣌', NULL, 11, 'local:warsh-text.json'),
  ('warsh-2-72', 'warsh', 2, 72, 'فَقُلْنَا ࡰٜضْرِبُوهُ بِبَعْضِهَا࣌ كَذَٰلِكَ يُحْيِ ࡴ۬للَّهُ ࡲ۬لْمَوْتٜىٰ وَيُرِيكُمُۥٓ ءَايَٰتِهِۦ لَعَلَّكُمْ تَعْقِلُونَ࣌', 'فقلنا ࡰضربوه ببعضها࣌ كذلك يحي ࡴلله ࡲلموتى ويريكم ءايته لعلكم تعقلون࣌', NULL, 11, 'local:warsh-text.json'),
  ('warsh-2-73', 'warsh', 2, 73, 'ثُمَّ قَسَتْ قُلُوبُكُم مِّنۢ بَعْدِ ذَٰلِكَ فَهِيَ كَالْحِجَارَةِ أَوَ ࡰشَدُّ قَسْوَةࣰ࣌ وَإِنَّ مِنَ ࡰ۬لْحِجَارَةِ لَمَا يَتَفَجَّرُ مِنْهُ ࡲ۬لَانْهَٰرُ࣌ وَإِنَّ مِنْهَا لَمَا يَشَّقَّقُ فَيَخْرُجُ مِنْهُ ࡲ۬لْمَآءُ࣌ وَإِنَّ مِنْهَا لَمَا يَهْبِطُ مِنْ خَشْيَةِ ࡴ۬للَّهِ࣌ وَمَا ࡰ۬للَّهُ بِغَٰفِلٍ عَمَّا تَعْمَلُونَ࣌', 'ثم قست قلوبكم من بعد ذلك فهي كالحجارة أو ࡰشد قسوة࣌ وإن من ࡰلحجارة لما يتفجر منه ࡲلانهر࣌ وإن منها لما يشقق فيخرج منه ࡲلماء࣌ وإن منها لما يهبط من خشية ࡴلله࣌ وما ࡰلله بغفل عما تعملون࣌', NULL, 11, 'local:warsh-text.json'),
  ('warsh-2-74', 'warsh', 2, 74, 'أَفَتَطْمَعُونَ أَنْ يُّومِنُواْ لَكُمْ وَقَدْ كَانَ فَرِيقࣱ مِّنْهُمْ يَسْمَعُونَ كَلَٰمَ ࡰ۬للَّهِ ثُمَّ يُحَرِّفُونَهُۥ مِنۢ بَعْدِ مَا عَقَلُوهُ وَهُمْ يَعْلَمُونَ࣌', 'أفتطمعون أن يومنوا لكم وقد كان فريق منهم يسمعون كلم ࡰلله ثم يحرفونه من بعد ما عقلوه وهم يعلمون࣌', NULL, 11, 'local:warsh-text.json'),
  ('warsh-2-75', 'warsh', 2, 75, '۞ وَإِذَا لَقُواْ ࡲ۬لذِينَ ءَامَنُواْ قَالُوٓاْ ءَامَنَّا࣌ وَإِذَا خَلَا بَعْضُهُمُۥٓ إِلَىٰ بَعْضࣲ قَالُوٓاْ أَتُحَدِّثُونَهُم بِمَا فَتَحَ ࡰ۬للَّهُ عَلَيْكُمْ لِيُحَآجُّوكُم بِهِۦ عِندَ رَبِّكُمُۥٓ࣌ أَفَلَا تَعْقِلُونَ࣌', 'وإذا لقوا ࡲلذين ءامنوا قالوا ءامنا࣌ وإذا خلا بعضهم إلى بعض قالوا أتحدثونهم بما فتح ࡰلله عليكم ليحاجوكم به عند ربكم࣌ أفلا تعقلون࣌', NULL, 11, 'local:warsh-text.json'),
  ('warsh-2-76', 'warsh', 2, 76, 'أَوَلَا يَعْلَمُونَ أَنَّ ࡰ۬للَّهَ يَعْلَمُ مَا يُسِرُّونَ وَمَا يُعْلِنُونَ࣌', 'أولا يعلمون أن ࡰلله يعلم ما يسرون وما يعلنون࣌', NULL, 12, 'local:warsh-text.json'),
  ('warsh-2-77', 'warsh', 2, 77, 'وَمِنْهُمُۥٓ أُمِّيُّونَ لَا يَعْلَمُونَ ࡰ۬لْكِتَٰبَ إِلَّآ أَمَانِيَّ࣌ وَإِنْ هُمُۥٓ إِلَّا يَظُنُّونَ࣌', 'ومنهم أميون لا يعلمون ࡰلكتب إلا أماني࣌ وإن هم إلا يظنون࣌', NULL, 12, 'local:warsh-text.json'),
  ('warsh-2-78', 'warsh', 2, 78, 'فَوَيْلࣱ لِّلذِينَ يَكْتُبُونَ ࡰ۬لْكِتَٰبَ بِأَيْدِيهِمْ ثُمَّ يَقُولُونَ هَٰذَا مِنْ عِندِ ࡴ۬للَّهِ لِيَشْتَرُواْ بِهِۦ ثَمَناࣰ قَلِيلاࣰ࣌ فَوَيْلࣱ لَّهُم مِّمَّا كَتَبَتَ ࡰيْدِيهِمْ࣌ وَوَيْلࣱ لَّهُم مِّمَّا يَكْسِبُونَ࣌', 'فويل للذين يكتبون ࡰلكتب بأيديهم ثم يقولون هذا من عند ࡴلله ليشتروا به ثمنا قليلا࣌ فويل لهم مما كتبت ࡰيديهم࣌ وويل لهم مما يكسبون࣌', NULL, 12, 'local:warsh-text.json'),
  ('warsh-2-79', 'warsh', 2, 79, 'وَقَالُواْ لَن تَمَسَّنَا ࡰ۬لنَّارُ إِلَّآ أَيَّاماࣰ مَّعْدُودَةࣰ࣌ قُلَ ࡰتَّخَذتُّمْ عِندَ ࡰ۬للَّهِ عَهْداࣰ فَلَنْ يُّخْلِفَ ࡰ۬للَّهُ عَهْدَهُۥٓ࣌ أَمْ تَقُولُونَ عَلَى ࡰ۬للَّهِ مَا لَا تَعْلَمُونَ࣌', 'وقالوا لن تمسنا ࡰلنار إلا أياما معدودة࣌ قل ࡰتخذتم عند ࡰلله عهدا فلن يخلف ࡰلله عهده࣌ أم تقولون على ࡰلله ما لا تعلمون࣌', NULL, 12, 'local:warsh-text.json'),
  ('warsh-2-80', 'warsh', 2, 80, 'بَلٜىٰ مَن كَسَبَ سَيِّئَةࣰ وَأَحَٰطَتْ بِهِۦ خَطِيٓـَٰٔتُهُۥ فَأُوْلَٰٓئِكَ أَصْحَٰبُ ࡲ۬لنّٜارِ هُمْ فِيهَا خَٰلِدُونَ࣌', 'بلى من كسب سيئة وأحطت به خطيته فأولئك أصحب ࡲلنار هم فيها خلدون࣌', NULL, 12, 'local:warsh-text.json'),
  ('warsh-2-81', 'warsh', 2, 81, 'وَالذِينَ ءَامَنُواْ وَعَمِلُواْ ࡲ۬لصَّٰلِحَٰتِ أُوْلَٰٓئِكَ أَصْحَٰبُ ࡲ۬لْجَنَّةِ هُمْ فِيهَا خَٰلِدُونَ࣌', 'والذين ءامنوا وعملوا ࡲلصلحت أولئك أصحب ࡲلجنة هم فيها خلدون࣌', NULL, 12, 'local:warsh-text.json'),
  ('warsh-2-82', 'warsh', 2, 82, 'وَإِذَ ࡰخَذْنَا مِيثَٰقَ بَنِےٓ إِسْرَآءِيلَ لَا تَعْبُدُونَ إِلَّا ࡰ۬للَّهَ࣌ وَبِالْوَٰلِدَيْنِ إِحْسَٰناࣰ وَذِے ࡴ۬لْقُرْبٜىٰ وَالْيَتَٰمٜىٰ وَالْمَسَٰكِينِ࣌ وَقُولُواْ لِلنَّاسِ حُسْناࣰ࣌ وَأَقِيمُواْ ࡲ۬لصَّلَوٰةَ وَءَاتُواْ ࡲ۬لزَّكَوٰةَ࣌ ثُمَّ تَوَلَّيْتُمُۥٓ إِلَّا قَلِيلاࣰ مِّنكُمْ وَأَنتُم مُّعْرِضُونَ࣌', 'وإذ ࡰخذنا ميثق بنے إسراءيل لا تعبدون إلا ࡰلله࣌ وبالولدين إحسنا وذے ࡴلقربى واليتمى والمسكين࣌ وقولوا للناس حسنا࣌ وأقيموا ࡲلصلوة وءاتوا ࡲلزكوة࣌ ثم توليتم إلا قليلا منكم وأنتم معرضون࣌', NULL, 12, 'local:warsh-text.json'),
  ('warsh-2-83', 'warsh', 2, 83, 'وَإِذَ ࡰخَذْنَا مِيثَٰقَكُمْ لَا تَسْفِكُونَ دِمَآءَكُمْ وَلَا تُخْرِجُونَ أَنفُسَكُم مِّن دِيٜـٰرِكُمْ ثُمَّ أَقْرَرْتُمْ وَأَنتُمْ تَشْهَدُونَ࣌', 'وإذ ࡰخذنا ميثقكم لا تسفكون دماءكم ولا تخرجون أنفسكم من ديركم ثم أقررتم وأنتم تشهدون࣌', NULL, 13, 'local:warsh-text.json'),
  ('warsh-2-84', 'warsh', 2, 84, 'ثُمَّ أَنتُمْ هَٰٓؤُلَآءِ تَقْتُلُونَ أَنفُسَكُمْ وَتُخْرِجُونَ فَرِيقاࣰ مِّنكُم مِّن دِيٜـٰرِهِمْ تَظَّٰهَرُونَ عَلَيْهِم بِالِاثْمِ وَالْعُدْوَٰنِ࣌ ۞ وَإِنْ يَّاتُوكُمُۥٓ أُسَٰرٜىٰ تُفَٰدُوهُمْ وَهُوَ مُحَرَّمٌ عَلَيْكُمُۥٓ إِخْرَاجُهُمُۥٓ࣌ أَفَتُومِنُونَ بِبَعْضِ ࡴ۬لْكِتَٰبِ وَتَكْفُرُونَ بِبَعْضࣲ࣌ فَمَا جَزَآءُ مَنْ يَّفْعَلُ ذَٰلِكَ مِنكُمُۥٓ إِلَّا خِزْيࣱ فِے ࡴ۬لْحَيَوٰةِ ࡴ۬لدُّنْيٜا࣌ وَيَوْمَ ࡰ۬لْقِيَٰمَةِ يُرَدُّونَ إِلَىٰٓ أَشَدِّ ࡴ۬لْعَذَابِ࣌ وَمَا ࡰ۬للَّهُ بِغَٰفِلٍ عَمَّا يَعْمَلُونَ࣌', 'ثم أنتم هؤلاء تقتلون أنفسكم وتخرجون فريقا منكم من ديرهم تظهرون عليهم بالاثم والعدون࣌  وإن ياتوكم أسرى تفدوهم وهو محرم عليكم إخراجهم࣌ أفتومنون ببعض ࡴلكتب وتكفرون ببعض࣌ فما جزاء من يفعل ذلك منكم إلا خزي فے ࡴلحيوة ࡴلدنيا࣌ ويوم ࡰلقيمة يردون إلى أشد ࡴلعذاب࣌ وما ࡰلله بغفل عما يعملون࣌', NULL, 13, 'local:warsh-text.json'),
  ('warsh-2-85', 'warsh', 2, 85, 'أُوْلَٰٓئِكَ ࡰ۬لذِينَ ࡰٜشْتَرَوُاْ ࡲ۬لْحَيَوٰةَ ࡰ۬لدُّنْيٜا بِالَاخِرَةِ فَلَا يُخَفَّفُ عَنْهُمُ ࡲ۬لْعَذَابُ وَلَا هُمْ يُنصَرُونَ࣌', 'أولئك ࡰلذين ࡰشتروا ࡲلحيوة ࡰلدنيا بالاخرة فلا يخفف عنهم ࡲلعذاب ولا هم ينصرون࣌', NULL, 13, 'local:warsh-text.json'),
  ('warsh-2-86', 'warsh', 2, 86, 'وَلَقَدَ اٰتَيْنَا مُوسَى ࡰ۬لْكِتَٰبَ وَقَفَّيْنَا مِنۢ بَعْدِهِۦ بِالرُّسُلِ࣌ وَءَاتَيْنَا عِيسَى ࡰٜبْنَ مَرْيَمَ ࡰ۬لْبَيِّنَٰتِ وَأَيَّدْنَٰهُ بِرُوحِ ࡴ۬لْقُدُسِ࣌ أَفَكُلَّمَا جَآءَكُمْ رَسُولُۢ بِمَا لَا تَهْوٜىٰٓ أَنفُسُكُمُ ࡲٜسْتَكْبَرْتُمْ࣌ فَفَرِيقاࣰ كَذَّبْتُمْ࣌ وَفَرِيقاࣰ تَقْتُلُونَ࣌', 'ولقد اتينا موسى ࡰلكتب وقفينا من بعده بالرسل࣌ وءاتينا عيسى ࡰبن مريم ࡰلبينت وأيدنه بروح ࡴلقدس࣌ أفكلما جاءكم رسول بما لا تهوى أنفسكم ࡲستكبرتم࣌ ففريقا كذبتم࣌ وفريقا تقتلون࣌', NULL, 13, 'local:warsh-text.json'),
  ('warsh-2-87', 'warsh', 2, 87, 'وَقَالُواْ قُلُوبُنَا غُلْفُۢ࣌ بَل لَّعَنَهُمُ ࡲ۬للَّهُ بِكُفْرِهِمْ فَقَلِيلاࣰ مَّا يُومِنُونَ࣌', 'وقالوا قلوبنا غلف࣌ بل لعنهم ࡲلله بكفرهم فقليلا ما يومنون࣌', NULL, 13, 'local:warsh-text.json'),
  ('warsh-2-88', 'warsh', 2, 88, 'وَلَمَّا جَآءَهُمْ كِتَٰبࣱ مِّنْ عِندِ ࡴ۬للَّهِ مُصَدِّقࣱ لِّمَا مَعَهُمْ وَكَانُواْ مِن قَبْلُ يَسْتَفْتِحُونَ عَلَى ࡰ۬لذِينَ كَفَرُواْ࣌ فَلَمَّا جَآءَهُم مَّا عَرَفُواْ كَفَرُواْ بِهِۦ࣌ فَلَعْنَةُ ࡲ۬للَّهِ عَلَى ࡰ۬لْكٜـٰفِرِينَ࣌', 'ولما جاءهم كتب من عند ࡴلله مصدق لما معهم وكانوا من قبل يستفتحون على ࡰلذين كفروا࣌ فلما جاءهم ما عرفوا كفروا به࣌ فلعنة ࡲلله على ࡰلكفرين࣌', NULL, 14, 'local:warsh-text.json'),
  ('warsh-2-89', 'warsh', 2, 89, 'بِيسَمَا ࡰٜشْتَرَوْاْ بِهِۦٓ أَنفُسَهُمُۥٓ أَنْ يَّكْفُرُواْ بِمَآ أَنزَلَ ࡰ۬للَّهُ بَغْياً ࡰنْ يُّنَزِّلَ ࡰ۬للَّهُ مِن فَضْلِهِۦ عَلَىٰ مَنْ يَّشَآءُ مِنْ عِبَادِهِۦ࣌ فَبَآءُو بِغَضَبٍ عَلَىٰ غَضَبࣲ࣌ وَلِلْكٜـٰفِرِينَ عَذَابࣱ مُّهِينࣱ࣌', 'بيسما ࡰشتروا به أنفسهم أن يكفروا بما أنزل ࡰلله بغيا ࡰن ينزل ࡰلله من فضله على من يشاء من عباده࣌ فباءو بغضب على غضب࣌ وللكفرين عذاب مهين࣌', NULL, 14, 'local:warsh-text.json'),
  ('warsh-2-90', 'warsh', 2, 90, 'وَإِذَا قِيلَ لَهُمُۥٓ ءَامِنُواْ بِمَآ أَنزَلَ ࡰ۬للَّهُ قَالُواْ نُومِنُ بِمَآ أُنزِلَ عَلَيْنَا وَيَكْفُرُونَ بِمَا وَرَآءَهُۥ࣌ وَهُوَ ࡰ۬لْحَقُّ مُصَدِّقاࣰ لِّمَا مَعَهُمْ࣌ قُلْ فَلِمَ تَقْتُلُونَ أَنۢبِئَآءَ ࡰ۬للَّهِ مِن قَبْلُ إِن كُنتُم مُّومِنِينَ࣌', 'وإذا قيل لهم ءامنوا بما أنزل ࡰلله قالوا نومن بما أنزل علينا ويكفرون بما وراءه࣌ وهو ࡰلحق مصدقا لما معهم࣌ قل فلم تقتلون أنبئاء ࡰلله من قبل إن كنتم مومنين࣌', NULL, 14, 'local:warsh-text.json'),
  ('warsh-2-91', 'warsh', 2, 91, '۞ وَلَقَدْ جَآءَكُم مُّوسٜىٰ بِالْبَيِّنَٰتِ ثُمَّ ࡰٜتَّخَذتُّمُ ࡲ۬لْعِجْلَ مِنۢ بَعْدِهِۦ وَأَنتُمْ ظَٰلِمُونَ࣌', 'ولقد جاءكم موسى بالبينت ثم ࡰتخذتم ࡲلعجل من بعده وأنتم ظلمون࣌', NULL, 14, 'local:warsh-text.json'),
  ('warsh-2-92', 'warsh', 2, 92, 'وَإِذَ ࡰخَذْنَا مِيثَٰقَكُمْ وَرَفَعْنَا فَوْقَكُمُ ࡲ۬لطُّورَ࣌ خُذُواْ مَآ ءَاتَيْنَٰكُم بِقُوَّةࣲ وَاسْمَعُواْ࣌ قَالُواْ سَمِعْنَا وَعَصَيْنَا࣌ وَأُشْرِبُواْ فِے قُلُوبِهِمُ ࡲ۬لْعِجْلَ بِكُفْرِهِمْ࣌ قُلْ بِيسَمَا يَامُرُكُم بِهِۦٓ إِيمَٰنُكُمُۥٓ إِن كُنتُم مُّومِنِينَ࣌', 'وإذ ࡰخذنا ميثقكم ورفعنا فوقكم ࡲلطور࣌ خذوا ما ءاتينكم بقوة واسمعوا࣌ قالوا سمعنا وعصينا࣌ وأشربوا فے قلوبهم ࡲلعجل بكفرهم࣌ قل بيسما يامركم به إيمنكم إن كنتم مومنين࣌', NULL, 14, 'local:warsh-text.json'),
  ('warsh-2-93', 'warsh', 2, 93, 'قُلِ ࡴن كَانَتْ لَكُمُ ࡲ۬لدَّارُ ࡲ۬لَاخِرَةُ عِندَ ࡰ۬للَّهِ خَالِصَةࣰ مِّن دُونِ ࡴ۬لنَّاسِ فَتَمَنَّوُاْ ࡲ۬لْمَوْتَ إِن كُنتُمْ صَٰدِقِينَ࣌', 'قل ࡴن كانت لكم ࡲلدار ࡲلاخرة عند ࡰلله خالصة من دون ࡴلناس فتمنوا ࡲلموت إن كنتم صدقين࣌', NULL, 15, 'local:warsh-text.json'),
  ('warsh-2-94', 'warsh', 2, 94, 'وَلَنْ يَّتَمَنَّوْهُ أَبَداَۢ بِمَا قَدَّمَتَ ࡰيْدِيهِمْ࣌ وَاللَّهُ عَلِيمُۢ بِالظَّٰلِمِينَ࣌', 'ولن يتمنوه أبدا بما قدمت ࡰيديهم࣌ والله عليم بالظلمين࣌', NULL, 15, 'local:warsh-text.json'),
  ('warsh-2-95', 'warsh', 2, 95, 'وَلَتَجِدَنَّهُمُۥٓ أَحْرَصَ ࡰ۬لنَّاسِ عَلَىٰ حَيَوٰةࣲ࣌ وَمِنَ ࡰ۬لذِينَ أَشْرَكُواْ يَوَدُّ أَحَدُهُمْ لَوْ يُعَمَّرُ أَلْفَ سَنَةࣲ࣌ وَمَا هُوَ بِمُزَحْزِحِهِۦ مِنَ ࡰ۬لْعَذَابِ أَنْ يُّعَمَّرَ࣌ وَاللَّهُ بَصِيرُۢ بِمَا يَعْمَلُونَ࣌', 'ولتجدنهم أحرص ࡰلناس على حيوة࣌ ومن ࡰلذين أشركوا يود أحدهم لو يعمر ألف سنة࣌ وما هو بمزحزحه من ࡰلعذاب أن يعمر࣌ والله بصير بما يعملون࣌', NULL, 15, 'local:warsh-text.json'),
  ('warsh-2-96', 'warsh', 2, 96, 'قُلْ مَن كَانَ عَدُوّاࣰ لِّـجِبْرِيلَ فَإِنَّهُۥ نَزَّلَهُۥ عَلَىٰ قَلْبِكَ بِإِذْنِ ࡴ۬للَّهِ مُصَدِّقاࣰ لِّمَا بَيْنَ يَدَيْهِ وَهُدىࣰ وَبُشْرٜىٰ لِلْمُومِنِينَ࣌', 'قل من كان عدوا لجبريل فإنه نزله على قلبك بإذن ࡴلله مصدقا لما بين يديه وهدى وبشرى للمومنين࣌', NULL, 15, 'local:warsh-text.json'),
  ('warsh-2-97', 'warsh', 2, 97, 'مَن كَانَ عَدُوّاࣰ لِّلهِ وَمَلَٰٓئِكَتِهِۦ وَرُسُلِهِۦ وَجِبْرِيلَ وَمِيكَٰٓئِلَ فَإِنَّ ࡰ۬للَّهَ عَدُوࣱّ لِّلْكٜـٰفِرِينَ࣌', 'من كان عدوا لله وملئكته ورسله وجبريل وميكئل فإن ࡰلله عدو للكفرين࣌', NULL, 15, 'local:warsh-text.json'),
  ('warsh-2-98', 'warsh', 2, 98, 'وَلَقَدَ ࡰنزَلْنَآ إِلَيْكَ ءَايَٰتِۢ بَيِّنَٰتࣲ࣌ وَمَا يَكْفُرُ بِهَآ إِلَّا ࡰ۬لْفَٰسِقُونَ࣌', 'ولقد ࡰنزلنا إليك ءايت بينت࣌ وما يكفر بها إلا ࡰلفسقون࣌', NULL, 15, 'local:warsh-text.json'),
  ('warsh-2-99', 'warsh', 2, 99, 'أَوَكُلَّمَا عَٰهَدُواْ عَهْداࣰ نَّبَذَهُۥ فَرِيقࣱ مِّنْهُم࣌ بَلَ ࡰكْثَرُهُمْ لَا يُومِنُونَ࣌', 'أوكلما عهدوا عهدا نبذه فريق منهم࣌ بل ࡰكثرهم لا يومنون࣌', NULL, 15, 'local:warsh-text.json'),
  ('warsh-2-100', 'warsh', 2, 100, '۞ وَلَمَّا جَآءَهُمْ رَسُولࣱ مِّنْ عِندِ ࡴ۬للَّهِ مُصَدِّقࣱ لِّمَا مَعَهُمْ نَبَذَ فَرِيقࣱ مِّنَ ࡰ۬لذِينَ أُوتُواْ ࡲ۬لْكِتَٰبَ كِتَٰبَ ࡰ۬للَّهِ وَرَآءَ ظُهُورِهِمْ كَأَنَّهُمْ لَا يَعْلَمُونَ࣌', 'ولما جاءهم رسول من عند ࡴلله مصدق لما معهم نبذ فريق من ࡰلذين أوتوا ࡲلكتب كتب ࡰلله وراء ظهورهم كأنهم لا يعلمون࣌', NULL, 15, 'local:warsh-text.json'),
  ('warsh-2-101', 'warsh', 2, 101, 'وَاتَّبَعُواْ مَا تَتْلُواْ ࡲ۬لشَّيَٰطِينُ عَلَىٰ مُلْكِ سُلَيْمَٰنَ࣌ وَمَا كَفَرَ سُلَيْمَٰنُ࣌ وَلَٰكِنَّ ࡰ۬لشَّيَٰطِينَ كَفَرُواْ يُعَلِّمُونَ ࡰ۬لنَّاسَ ࡰ۬لسِّحْرَ وَمَآ أُنزِلَ عَلَى ࡰ۬لْمَلَكَيْنِ بِبَابِلَ هَارُوتَ وَمَارُوتَ࣌ وَمَا يُعَلِّمَٰنِ مِنَ ࡰحَدٍ حَتَّىٰ يَقُولَآ إِنَّمَا نَحْنُ فِتْنَةࣱ فَلَا تَكْفُرْ࣌ فَيَتَعَلَّمُونَ مِنْهُمَا مَا يُفَرِّقُونَ بِهِۦ بَيْنَ ࡰ۬لْمَرْءِ وَزَوْجِهِۦ࣌ وَمَا هُم بِضَآرِّينَ بِهِۦ مِنَ ࡰحَدٍ ࡴلَّا بِإِذْنِ ࡴ۬للَّهِ࣌ وَيَتَعَلَّمُونَ مَا يَضُرُّهُمْ وَلَا يَنفَعُهُمْ࣌ وَلَقَدْ عَلِمُواْ لَمَنِ ࡴٜشْتَرٜيٰهُ مَا لَهُۥ فِے ࡴ۬لَاخِرَةِ مِنْ خَلَٰقࣲ࣌ وَلَبِيسَ مَا شَرَوْاْ بِهِۦٓ أَنفُسَهُمْ لَوْ كَانُواْ يَعْلَمُونَ࣌', 'واتبعوا ما تتلوا ࡲلشيطين على ملك سليمن࣌ وما كفر سليمن࣌ ولكن ࡰلشيطين كفروا يعلمون ࡰلناس ࡰلسحر وما أنزل على ࡰلملكين ببابل هاروت وماروت࣌ وما يعلمن من ࡰحد حتى يقولا إنما نحن فتنة فلا تكفر࣌ فيتعلمون منهما ما يفرقون به بين ࡰلمرء وزوجه࣌ وما هم بضارين به من ࡰحد ࡴلا بإذن ࡴلله࣌ ويتعلمون ما يضرهم ولا ينفعهم࣌ ولقد علموا لمن ࡴشتريه ما له فے ࡴلاخرة من خلق࣌ ولبيس ما شروا به أنفسهم لو كانوا يعلمون࣌', NULL, 16, 'local:warsh-text.json'),
  ('warsh-2-102', 'warsh', 2, 102, 'وَلَوَ ࡰنَّهُمُۥٓ ءَامَنُواْ وَاتَّقَوْاْ لَمَثُوبَةࣱ مِّنْ عِندِ ࡴ۬للَّهِ خَيْرࣱ لَّوْ كَانُواْ يَعْلَمُونَ࣌', 'ولو ࡰنهم ءامنوا واتقوا لمثوبة من عند ࡴلله خير لو كانوا يعلمون࣌', NULL, 16, 'local:warsh-text.json'),
  ('warsh-2-103', 'warsh', 2, 103, 'يَٰٓأَيُّهَا ࡰ۬لذِينَ ءَامَنُواْ لَا تَقُولُواْ رَٰعِنَا وَقُولُواْ ࡲ࢈نظُرْنَا وَاسْمَعُواْ࣌ وَلِلْكٜـٰفِرِينَ عَذَابٌ ࡰلِيمࣱ࣌', 'يأيها ࡰلذين ءامنوا لا تقولوا رعنا وقولوا ࡲ࢈نظرنا واسمعوا࣌ وللكفرين عذاب ࡰليم࣌', NULL, 16, 'local:warsh-text.json'),
  ('warsh-2-104', 'warsh', 2, 104, 'مَّا يَوَدُّ ࡲ۬لذِينَ كَفَرُواْ مِنَ ࡰهْلِ ࡴ۬لْكِتَٰبِ وَلَا ࡰ۬لْمُشْرِكِينَ أَنْ يُّنَزَّلَ عَلَيْكُم مِّنْ خَيْرࣲ مِّن رَّبِّكُمْ࣌ وَاللَّهُ يَخْتَصُّ بِرَحْمَتِهِۦ مَنْ يَّشَآءُ࣌ وَاللَّهُ ذُو ࡲ۬لْفَضْلِ ࡴ۬لْعَظِيمِ࣌', 'ما يود ࡲلذين كفروا من ࡰهل ࡴلكتب ولا ࡰلمشركين أن ينزل عليكم من خير من ربكم࣌ والله يختص برحمته من يشاء࣌ والله ذو ࡲلفضل ࡴلعظيم࣌', NULL, 16, 'local:warsh-text.json'),
  ('warsh-2-105', 'warsh', 2, 105, '۞ مَا نَنسَخْ مِنَ اٰيَةٍ ࡰوْ نُنسِهَا نَاتِ بِخَيْرࣲ مِّنْهَآ أَوْ مِثْلِهَآ࣌ أَلَمْ تَعْلَمَ ࡰنَّ ࡰ۬للَّهَ عَلَىٰ كُلِّ شَےْءࣲ قَدِيرٌ࣌', 'ما ننسخ من اية ࡰو ننسها نات بخير منها أو مثلها࣌ ألم تعلم ࡰن ࡰلله على كل شےء قدير࣌', NULL, 17, 'local:warsh-text.json'),
  ('warsh-2-106', 'warsh', 2, 106, 'ࡰلَمْ تَعْلَمَ ࡰنَّ ࡰ۬للَّهَ لَهُۥ مُلْكُ ࡲ۬لسَّمَٰوَٰتِ وَالَارْضِ وَمَا لَكُم مِّن دُونِ ࡴ۬للَّهِ مِنْ وَّلِيࣲّ وَلَا نَصِيرٍ࣌', 'ࡰلم تعلم ࡰن ࡰلله له ملك ࡲلسموت والارض وما لكم من دون ࡴلله من ولي ولا نصير࣌', NULL, 17, 'local:warsh-text.json'),
  ('warsh-2-107', 'warsh', 2, 107, 'ࡰمْ تُرِيدُونَ أَن تَسْـَٔلُواْ رَسُولَكُمْ كَمَا سُئِلَ مُوسٜىٰ مِن قَبْلُ࣌ وَمَنْ يَّتَبَدَّلِ ࡴ۬لْكُفْرَ بِالِايمَٰنِ فَقَد ضَّلَّ سَوَآءَ ࡰ۬لسَّبِيلِ࣌', 'ࡰم تريدون أن تسلوا رسولكم كما سئل موسى من قبل࣌ ومن يتبدل ࡴلكفر بالايمن فقد ضل سواء ࡰلسبيل࣌', NULL, 17, 'local:warsh-text.json'),
  ('warsh-2-108', 'warsh', 2, 108, 'وَدَّ كَثِيرࣱ مِّنَ ࡰهْلِ ࡴ۬لْكِتَٰبِ لَوْ يَرُدُّونَكُم مِّنۢ بَعْدِ إِيمَٰنِكُمْ كُفَّاراً࣌ حَسَداࣰ مِّنْ عِندِ أَنفُسِهِم مِّنۢ بَعْدِ مَا تَبَيَّنَ لَهُمُ ࡲ۬لْحَقُّ࣌ فَاعْفُواْ وَاصْفَحُواْ حَتَّىٰ يَاتِيَ ࡰ۬للَّهُ بِأَمْرِهِۦٓ࣌ إِنَّ ࡰ۬للَّهَ عَلَىٰ كُلِّ شَےْءࣲ قَدِيرࣱ࣌', 'ود كثير من ࡰهل ࡴلكتب لو يردونكم من بعد إيمنكم كفارا࣌ حسدا من عند أنفسهم من بعد ما تبين لهم ࡲلحق࣌ فاعفوا واصفحوا حتى ياتي ࡰلله بأمره࣌ إن ࡰلله على كل شےء قدير࣌', NULL, 17, 'local:warsh-text.json'),
  ('warsh-2-109', 'warsh', 2, 109, 'وَأَقِيمُواْ ࡲ۬لصَّلَوٰةَ وَءَاتُواْ ࡲ۬لزَّكَوٰةَ࣌ وَمَا تُقَدِّمُواْ لِأَنفُسِكُم مِّنْ خَيْرࣲ تَجِدُوهُ عِندَ ࡰ۬للَّهِ࣌ إِنَّ ࡰ۬للَّهَ بِمَا تَعْمَلُونَ بَصِيرࣱ࣌', 'وأقيموا ࡲلصلوة وءاتوا ࡲلزكوة࣌ وما تقدموا لأنفسكم من خير تجدوه عند ࡰلله࣌ إن ࡰلله بما تعملون بصير࣌', NULL, 17, 'local:warsh-text.json'),
  ('warsh-2-110', 'warsh', 2, 110, 'وَقَالُواْ لَنْ يَّدْخُلَ ࡰ۬لْجَنَّةَ إِلَّا مَن كَانَ هُوداً ࡰوْ نَصَٰرٜىٰ࣌ تِلْكَ أَمَانِيُّهُمْ࣌ قُلْ هَاتُواْ بُرْهَٰنَكُمُۥٓ إِن كُنتُمْ صَٰدِقِينَ࣌', 'وقالوا لن يدخل ࡰلجنة إلا من كان هودا ࡰو نصرى࣌ تلك أمانيهم࣌ قل هاتوا برهنكم إن كنتم صدقين࣌', NULL, 17, 'local:warsh-text.json'),
  ('warsh-2-111', 'warsh', 2, 111, 'بَلٜىٰ مَنَ ࡰسْلَمَ وَجْهَهُۥ لِلهِ وَهُوَ مُحْسِنࣱ فَلَهُۥٓ أَجْرُهُۥ عِندَ رَبِّهِۦ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ࣌', 'بلى من ࡰسلم وجهه لله وهو محسن فله أجره عند ربه ولا خوف عليهم ولا هم يحزنون࣌', NULL, 17, 'local:warsh-text.json'),
  ('warsh-2-112', 'warsh', 2, 112, 'وَقَالَتِ ࡴ۬لْيَهُودُ لَيْسَتِ ࡴ۬لنَّصَٰرٜىٰ عَلَىٰ شَےْءࣲ وَقَالَتِ ࡴ۬لنَّصَٰرٜىٰ لَيْسَتِ ࡴ۬لْيَهُودُ عَلَىٰ شَےْءࣲ وَهُمْ يَتْلُونَ ࡰ۬لْكِتَٰبَ࣌ كَذَٰلِكَ قَالَ ࡰ۬لذِينَ لَا يَعْلَمُونَ مِثْلَ قَوْلِهِمْ࣌ فَاللَّهُ يَحْكُمُ بَيْنَهُمْ يَوْمَ ࡰ۬لْقِيَٰمَةِ فِيمَا كَانُواْ فِيهِ يَخْتَلِفُونَ࣌', 'وقالت ࡴليهود ليست ࡴلنصرى على شےء وقالت ࡴلنصرى ليست ࡴليهود على شےء وهم يتلون ࡰلكتب࣌ كذلك قال ࡰلذين لا يعلمون مثل قولهم࣌ فالله يحكم بينهم يوم ࡰلقيمة فيما كانوا فيه يختلفون࣌', NULL, 18, 'local:warsh-text.json'),
  ('warsh-2-113', 'warsh', 2, 113, '۞ وَمَنَ ࡰظْلَمُ مِمَّن مَّنَعَ مَسَٰجِدَ ࡰ۬للَّهِ أَنْ يُّذْكَرَ فِيهَا ࡰٜسْمُهُۥ وَسَعٜىٰ فِے خَرَابِهَآ࣌ أُوْلَٰٓئِكَ مَا كَانَ لَهُمُۥٓ أَنْ يَّدْخُلُوهَآ إِلَّا خَآئِفِينَ࣌ لَهُمْ فِے ࡴ۬لدُّنْيٜا خِزْيࣱ࣌ وَلَهُمْ فِے ࡴ۬لَاخِرَةِ عَذَابٌ عَظِيمࣱ࣌', 'ومن ࡰظلم ممن منع مسجد ࡰلله أن يذكر فيها ࡰسمه وسعى فے خرابها࣌ أولئك ما كان لهم أن يدخلوها إلا خائفين࣌ لهم فے ࡴلدنيا خزي࣌ ولهم فے ࡴلاخرة عذاب عظيم࣌', NULL, 18, 'local:warsh-text.json'),
  ('warsh-2-114', 'warsh', 2, 114, 'وَلِلهِ ࡴ۬لْمَشْرِقُ وَالْمَغْرِبُ࣌ فَأَيْنَمَا تُوَلُّواْ فَثَمَّ وَجْهُ ࡲ۬للَّهِ࣌ إِنَّ ࡰ۬للَّهَ وَٰسِعٌ عَلِيمࣱ࣌', 'ولله ࡴلمشرق والمغرب࣌ فأينما تولوا فثم وجه ࡲلله࣌ إن ࡰلله وسع عليم࣌', NULL, 18, 'local:warsh-text.json'),
  ('warsh-2-115', 'warsh', 2, 115, 'وَقَالُواْ ࡲٜتَّخَذَ ࡰ۬للَّهُ وَلَداࣰ࣌ سُبْحَٰنَهُۥ࣌ بَل لَّهُۥ مَا فِے ࡴ۬لسَّمَٰوَٰتِ وَالَارْضِ࣌ كُلࣱّ لَّهُۥ قَٰنِتُونَ࣌', 'وقالوا ࡲتخذ ࡰلله ولدا࣌ سبحنه࣌ بل له ما فے ࡴلسموت والارض࣌ كل له قنتون࣌', NULL, 18, 'local:warsh-text.json'),
  ('warsh-2-116', 'warsh', 2, 116, 'بَدِيعُ ࡲ۬لسَّمَٰوَٰتِ وَالَارْضِ࣌ وَإِذَا قَضٜىٰٓ أَمْراࣰ فَإِنَّمَا يَقُولُ لَهُۥ كُن࣌ فَيَكُونُ࣌', 'بديع ࡲلسموت والارض࣌ وإذا قضى أمرا فإنما يقول له كن࣌ فيكون࣌', NULL, 18, 'local:warsh-text.json'),
  ('warsh-2-117', 'warsh', 2, 117, 'وَقَالَ ࡰ۬لذِينَ لَا يَعْلَمُونَ لَوْلَا يُكَلِّمُنَا ࡰ۬للَّهُ أَوْ تَاتِينَآ ءَايَةࣱ࣌ كَذَٰلِكَ قَالَ ࡰ۬لذِينَ مِن قَبْلِهِم مِّثْلَ قَوْلِهِمْ࣌ تَشَٰبَهَتْ قُلُوبُهُمْ࣌ قَدْ بَيَّنَّا ࡰ۬لَايَٰتِ لِقَوْمࣲ يُوقِنُونَ࣌', 'وقال ࡰلذين لا يعلمون لولا يكلمنا ࡰلله أو تاتينا ءاية࣌ كذلك قال ࡰلذين من قبلهم مثل قولهم࣌ تشبهت قلوبهم࣌ قد بينا ࡰلايت لقوم يوقنون࣌', NULL, 18, 'local:warsh-text.json'),
  ('warsh-2-118', 'warsh', 2, 118, 'إِنَّآ أَرْسَلْنَٰكَ بِالْحَقِّ بَشِيراࣰ وَنَذِيراࣰ࣌ وَلَا تَسْـَٔلْ عَنَ ࡰصْحَٰبِ ࡴ۬لْجَحِيمِ࣌', 'إنا أرسلنك بالحق بشيرا ونذيرا࣌ ولا تسل عن ࡰصحب ࡴلجحيم࣌', NULL, 18, 'local:warsh-text.json'),
  ('warsh-2-119', 'warsh', 2, 119, 'وَلَن تَرْضٜىٰ عَنكَ ࡰ۬لْيَهُودُ وَلَا ࡰ۬لنَّصَٰرٜىٰ حَتَّىٰ تَتَّبِعَ مِلَّتَهُمْ࣌ قُلِ ࡴنَّ هُدَى ࡰ۬للَّهِ هُوَ ࡰ۬لْهُدٜىٰ࣌ وَلَئِنِ ࡴٜتَّبَعْتَ أَهْوَآءَهُم بَعْدَ ࡰ۬لذِے جَآءَكَ مِنَ ࡰ۬لْعِلْمِ مَا لَكَ مِنَ ࡰ۬للَّهِ مِنْ وَّلِيࣲّ وَلَا نَصِيرٍ࣌', 'ولن ترضى عنك ࡰليهود ولا ࡰلنصرى حتى تتبع ملتهم࣌ قل ࡴن هدى ࡰلله هو ࡰلهدى࣌ ولئن ࡴتبعت أهواءهم بعد ࡰلذے جاءك من ࡰلعلم ما لك من ࡰلله من ولي ولا نصير࣌', NULL, 19, 'local:warsh-text.json'),
  ('warsh-2-120', 'warsh', 2, 120, 'ࡴ۬لذِينَ ءَاتَيْنَٰهُمُ ࡲ۬لْكِتَٰبَ يَتْلُونَهُۥ حَقَّ تِلَٰوَتِهِۦٓ أُوْلَٰٓئِكَ يُومِنُونَ بِهِۦ࣌ وَمَنْ يَّكْفُرْ بِهِۦ فَأُوْلَٰٓئِكَ هُمُ ࡲ۬لْخَٰسِرُونَ࣌', 'ࡴلذين ءاتينهم ࡲلكتب يتلونه حق تلوته أولئك يومنون به࣌ ومن يكفر به فأولئك هم ࡲلخسرون࣌', NULL, 19, 'local:warsh-text.json'),
  ('warsh-2-121', 'warsh', 2, 121, 'يَٰبَنِےٓ إِسْرَآءِيلَ ࡸَذْكُرُواْ نِعْمَتِيَ ࡰ۬لتِےٓ أَنْعَمْتُ عَلَيْكُمْ وَأَنِّے فَضَّلْتُكُمْ عَلَى ࡰ۬لْعَٰلَمِينَ࣌', 'يبنے إسراءيل ࡸذكروا نعمتي ࡰلتے أنعمت عليكم وأنے فضلتكم على ࡰلعلمين࣌', NULL, 19, 'local:warsh-text.json'),
  ('warsh-2-122', 'warsh', 2, 122, 'وَاتَّقُواْ يَوْماࣰ لَّا تَجْزِے نَفْسٌ عَن نَّفْسࣲ شَيْـٔاࣰ وَلَا يُقْبَلُ مِنْهَا عَدْلࣱ وَلَا تَنفَعُهَا شَفَٰعَةࣱ وَلَا هُمْ يُنصَرُونَ࣌', 'واتقوا يوما لا تجزے نفس عن نفس شيا ولا يقبل منها عدل ولا تنفعها شفعة ولا هم ينصرون࣌', NULL, 19, 'local:warsh-text.json'),
  ('warsh-2-123', 'warsh', 2, 123, '۞ وَإِذِ ࡴٜبْتَلٜىٰٓ إِبْرَٰهِـيمَ رَبُّهُۥ بِكَلِمَٰتࣲ فَأَتَمَّهُنَّ࣌ قَالَ إِنِّے جَاعِلُكَ لِلنَّاسِ إِمَاماࣰ࣌ قَالَ وَمِن ذُرِّيَّتِے࣌ قَالَ لَا يَنَالُ عَهْدِيَ ࡰ۬لظَّٰلِمِينَ࣌', 'وإذ ࡴبتلى إبرهيم ربه بكلمت فأتمهن࣌ قال إنے جاعلك للناس إماما࣌ قال ومن ذريتے࣌ قال لا ينال عهدي ࡰلظلمين࣌', NULL, 19, 'local:warsh-text.json'),
  ('warsh-2-124', 'warsh', 2, 124, 'وَإِذْ جَعَلْنَا ࡰ۬لْبَيْتَ مَثَابَةࣰ لِّلنَّاسِ وَأَمْناࣰ وَاتَّخَذُواْ مِن مَّقَامِ إِبْرَٰهِيمَ مُصَلّىࣰ࣌ وَعَهِدْنَآ إِلَىٰٓ إِبْرَٰهِيمَ وَإِسْمَٰعِيلَ أَن طَهِّرَا بَيْتِيَ لِلطَّآئِفِينَ وَالْعَٰكِفِينَ وَالرُّكَّعِ ࡴ۬لسُّجُودِ࣌', 'وإذ جعلنا ࡰلبيت مثابة للناس وأمنا واتخذوا من مقام إبرهيم مصلى࣌ وعهدنا إلى إبرهيم وإسمعيل أن طهرا بيتي للطائفين والعكفين والركع ࡴلسجود࣌', NULL, 19, 'local:warsh-text.json'),
  ('warsh-2-125', 'warsh', 2, 125, 'وَإِذْ قَالَ إِبْرَٰهِيمُ رَبِّ ࡴٜجْعَلْ هَٰذَا بَلَداً اٰمِناࣰ وَارْزُقَ ࡰهْلَهُۥ مِنَ ࡰ۬لثَّمَرَٰتِ مَنَ اٰمَنَ مِنْهُم بِاللَّهِ وَالْيَوْمِ ࡴ۬لَاخِرِ࣌ قَالَ وَمَن كَفَرَ فَأُمَتِّعُهُۥ قَلِيلاࣰ ثُمَّ أَضْطَرُّهُۥٓ إِلَىٰ عَذَابِ ࡴ۬لنّٜارِ࣌ وَبِيسَ ࡰ۬لْمَصِيرُ࣌', 'وإذ قال إبرهيم رب ࡴجعل هذا بلدا امنا وارزق ࡰهله من ࡰلثمرت من امن منهم بالله واليوم ࡴلاخر࣌ قال ومن كفر فأمتعه قليلا ثم أضطره إلى عذاب ࡴلنار࣌ وبيس ࡰلمصير࣌', NULL, 19, 'local:warsh-text.json'),
  ('warsh-2-126', 'warsh', 2, 126, 'وَإِذْ يَرْفَعُ إِبْرَٰهِيمُ ࡲ۬لْقَوَاعِدَ مِنَ ࡰ۬لْبَيْتِ وَإِسْمَٰعِيلُ࣌ رَبَّنَا تَقَبَّلْ مِنَّآ إِنَّكَ أَنتَ ࡰ۬لسَّمِيعُ ࡲ۬لْعَلِيمُ࣌', 'وإذ يرفع إبرهيم ࡲلقواعد من ࡰلبيت وإسمعيل࣌ ربنا تقبل منا إنك أنت ࡰلسميع ࡲلعليم࣌', NULL, 20, 'local:warsh-text.json'),
  ('warsh-2-127', 'warsh', 2, 127, 'رَبَّنَا وَاجْعَلْنَا مُسْلِمَيْنِ لَكَ وَمِن ذُرِّيَّتِنَآ أُمَّةࣰ مُّسْلِمَةࣰ لَّكَ࣌ وَأَرِنَا مَنَاسِكَنَا࣌ وَتُبْ عَلَيْنَآ࣌ إِنَّكَ أَنتَ ࡰ۬لتَّوَّابُ ࡲ۬لرَّحِيمُ࣌', 'ربنا واجعلنا مسلمين لك ومن ذريتنا أمة مسلمة لك࣌ وأرنا مناسكنا࣌ وتب علينا࣌ إنك أنت ࡰلتواب ࡲلرحيم࣌', NULL, 20, 'local:warsh-text.json'),
  ('warsh-2-128', 'warsh', 2, 128, 'رَبَّنَا وَابْعَثْ فِيهِمْ رَسُولاࣰ مِّنْهُمْ يَتْلُواْ عَلَيْهِمُۥٓ ءَايَٰتِكَ وَيُعَلِّمُهُمُ ࡲ۬لْكِتَٰبَ وَالْحِكْمَةَ وَيُزَكِّيهِمُۥٓ࣌ إِنَّكَ أَنتَ ࡰ۬لْعَزِيزُ ࡲ۬لْحَكِيمُ࣌', 'ربنا وابعث فيهم رسولا منهم يتلوا عليهم ءايتك ويعلمهم ࡲلكتب والحكمة ويزكيهم࣌ إنك أنت ࡰلعزيز ࡲلحكيم࣌', NULL, 20, 'local:warsh-text.json'),
  ('warsh-2-129', 'warsh', 2, 129, 'وَمَنْ يَّرْغَبُ عَن مِّلَّةِ إِبْرَٰهِيمَ إِلَّا مَن سَفِهَ نَفْسَهُۥ࣌ وَلَقَدِ ࡴٜصْطَفَيْنَٰهُ فِے ࡴ۬لدُّنْيٜا࣌ وَإِنَّهُۥ فِے ࡴ۬لَاخِرَةِ لَمِنَ ࡰ۬لصَّٰلِحِينَ࣌', 'ومن يرغب عن ملة إبرهيم إلا من سفه نفسه࣌ ولقد ࡴصطفينه فے ࡴلدنيا࣌ وإنه فے ࡴلاخرة لمن ࡰلصلحين࣌', NULL, 20, 'local:warsh-text.json'),
  ('warsh-2-130', 'warsh', 2, 130, 'إِذْ قَالَ لَهُۥ رَبُّهُۥٓ أَسْلِمْ࣌ قَالَ أَسْلَمْتُ لِرَبِّ ࡴ۬لْعَٰلَمِينَ࣌', 'إذ قال له ربه أسلم࣌ قال أسلمت لرب ࡴلعلمين࣌', NULL, 20, 'local:warsh-text.json'),
  ('warsh-2-131', 'warsh', 2, 131, 'وَأَوْصٜىٰ بِهَآ إِبْرَٰهِيمُ بَنِيهِ࣌ وَيَعْقُوبُ يَٰبَنِيَّ إِنَّ ࡰ۬للَّهَ ࡰٜصْطَفٜىٰ لَكُمُ ࡲ۬لدِّينَ فَلَا تَمُوتُنَّ إِلَّا وَأَنتُم مُّسْلِمُونَ࣌', 'وأوصى بها إبرهيم بنيه࣌ ويعقوب يبني إن ࡰلله ࡰصطفى لكم ࡲلدين فلا تموتن إلا وأنتم مسلمون࣌', NULL, 20, 'local:warsh-text.json'),
  ('warsh-2-132', 'warsh', 2, 132, '۞ أَمْ كُنتُمْ شُهَدَآءَ ࡹذْ حَضَرَ يَعْقُوبَ ࡰ۬لْمَوْتُ إِذْ قَالَ لِبَنِيهِ مَا تَعْبُدُونَ مِنۢ بَعْدِے࣌ قَالُواْ نَعْبُدُ إِلَٰهَكَ وَإِلَٰهَ ءَابَآئِكَ إِبْرَٰهِيمَ وَإِسْمَٰعِيلَ وَإِسْحَٰقَ إِلَٰهاࣰ وَٰحِداࣰ وَنَحْنُ لَهُۥ مُسْلِمُونَ࣌', 'أم كنتم شهداء ࡹذ حضر يعقوب ࡰلموت إذ قال لبنيه ما تعبدون من بعدے࣌ قالوا نعبد إلهك وإله ءابائك إبرهيم وإسمعيل وإسحق إلها وحدا ونحن له مسلمون࣌', NULL, 20, 'local:warsh-text.json'),
  ('warsh-2-133', 'warsh', 2, 133, 'تِلْكَ أُمَّةࣱ قَدْ خَلَتْ࣌ لَهَا مَا كَسَبَتْ࣌ وَلَكُم مَّا كَسَبْتُمْ࣌ وَلَا تُسْـَٔلُونَ عَمَّا كَانُواْ يَعْمَلُونَ࣌', 'تلك أمة قد خلت࣌ لها ما كسبت࣌ ولكم ما كسبتم࣌ ولا تسلون عما كانوا يعملون࣌', NULL, 20, 'local:warsh-text.json'),
  ('warsh-2-134', 'warsh', 2, 134, 'وَقَالُواْ كُونُواْ هُوداً ࡰوْ نَصَٰرٜىٰ تَهْتَدُواْ࣌ قُلْ بَلْ مِلَّةَ إِبْرَٰهِيمَ حَنِيفاࣰ࣌ وَمَا كَانَ مِنَ ࡰ۬لْمُشْرِكِينَ࣌', 'وقالوا كونوا هودا ࡰو نصرى تهتدوا࣌ قل بل ملة إبرهيم حنيفا࣌ وما كان من ࡰلمشركين࣌', NULL, 21, 'local:warsh-text.json'),
  ('warsh-2-135', 'warsh', 2, 135, 'قُولُوٓاْ ءَامَنَّا بِاللَّهِ وَمَآ أُنزِلَ إِلَيْنَا وَمَآ أُنزِلَ إِلَىٰٓ إِبْرَٰهِيمَ وَإِسْمَٰعِيلَ وَإِسْحَٰقَ وَيَعْقُوبَ وَالَاسْبَاطِ وَمَآ أُوتِيَ مُوسٜىٰ وَعِيسٜىٰ وَمَآ أُوتِيَ ࡰ۬لنَّبِيٓـُٔونَ مِن رَّبِّهِمْ لَا نُفَرِّقُ بَيْنَ أَحَدࣲ مِّنْهُمْ وَنَحْنُ لَهُۥ مُسْلِمُونَ࣌', 'قولوا ءامنا بالله وما أنزل إلينا وما أنزل إلى إبرهيم وإسمعيل وإسحق ويعقوب والاسباط وما أوتي موسى وعيسى وما أوتي ࡰلنبيون من ربهم لا نفرق بين أحد منهم ونحن له مسلمون࣌', NULL, 21, 'local:warsh-text.json'),
  ('warsh-2-136', 'warsh', 2, 136, 'فَإِنَ اٰمَنُواْ بِمِثْلِ مَآ ءَامَنتُم بِهِۦ فَقَدِ ࡴٜهْتَدَواْ࣌ وَّإِن تَوَلَّوْاْ فَإِنَّمَا هُمْ فِے شِقَاقࣲ࣌ فَسَيَكْفِيكَهُمُ ࡲ۬للَّهُ࣌ وَهُوَ ࡰ۬لسَّمِيعُ ࡲ۬لْعَلِيمُ࣌', 'فإن امنوا بمثل ما ءامنتم به فقد ࡴهتدوا࣌ وإن تولوا فإنما هم فے شقاق࣌ فسيكفيكهم ࡲلله࣌ وهو ࡰلسميع ࡲلعليم࣌', NULL, 21, 'local:warsh-text.json'),
  ('warsh-2-137', 'warsh', 2, 137, 'صِبْغَةَ ࡰ۬للَّهِ࣌ وَمَنَ ࡰحْسَنُ مِنَ ࡰ۬للَّهِ صِبْغَةࣰ࣌ وَنَحْنُ لَهُۥ عَٰبِدُونَ࣌', 'صبغة ࡰلله࣌ ومن ࡰحسن من ࡰلله صبغة࣌ ونحن له عبدون࣌', NULL, 21, 'local:warsh-text.json'),
  ('warsh-2-138', 'warsh', 2, 138, 'قُلَ ࡰتُحَآجُّونَنَا فِے ࡴ۬للَّهِ وَهُوَ رَبُّنَا وَرَبُّكُمْ وَلَنَآ أَعْمَٰلُنَا وَلَكُمُۥٓ أَعْمَٰلُكُمْ࣌ وَنَحْنُ لَهُۥ مُخْلِصُونَ࣌', 'قل ࡰتحاجوننا فے ࡴلله وهو ربنا وربكم ولنا أعملنا ولكم أعملكم࣌ ونحن له مخلصون࣌', NULL, 21, 'local:warsh-text.json'),
  ('warsh-2-139', 'warsh', 2, 139, 'أَمْ يَقُولُونَ إِنَّ إِبْرَٰهِيمَ وَإِسْمَٰعِيلَ وَإِسْحَٰقَ وَيَعْقُوبَ وَالَاسْبَاطَ كَانُواْ هُوداً ࡰوْ نَصَٰرٜىٰ࣌ قُلَ آٓنتُمُۥٓ أَعْلَمُ أَمِ ࡴ۬للَّهُ࣌ وَمَنَ ࡰظْلَمُ مِمَّن كَتَمَ شَهَٰدَةً عِندَهُۥ مِنَ ࡰ۬للَّهِ࣌ وَمَا ࡰ۬للَّهُ بِغَٰفِلٍ عَمَّا تَعْمَلُونَ࣌', 'أم يقولون إن إبرهيم وإسمعيل وإسحق ويعقوب والاسباط كانوا هودا ࡰو نصرى࣌ قل آنتم أعلم أم ࡴلله࣌ ومن ࡰظلم ممن كتم شهدة عنده من ࡰلله࣌ وما ࡰلله بغفل عما تعملون࣌', NULL, 21, 'local:warsh-text.json'),
  ('warsh-2-140', 'warsh', 2, 140, 'تِلْكَ أُمَّةࣱ قَدْ خَلَتْ࣌ لَهَا مَا كَسَبَتْ࣌ وَلَكُم مَّا كَسَبْتُمْ࣌ وَلَا تُسْـَٔلُونَ عَمَّا كَانُواْ يَعْمَلُونَ࣌', 'تلك أمة قد خلت࣌ لها ما كسبت࣌ ولكم ما كسبتم࣌ ولا تسلون عما كانوا يعملون࣌', NULL, 21, 'local:warsh-text.json'),
  ('warsh-2-141', 'warsh', 2, 141, '۞ سَيَقُولُ ࡲ۬لسُّفَهَآءُ مِنَ ࡰ۬لنَّاسِ مَا وَلّٜيٰهُمْ عَن قِبْلَتِهِمُ ࡲ۬لتِے كَانُواْ عَلَيْهَا࣌ قُل لِّلهِ ࡴ۬لْمَشْرِقُ وَالْمَغْرِبُ࣌ يَهْدِے مَنْ يَّشَآءُ ࡹِلَىٰ صِرَٰطࣲ مُّسْتَقِيمࣲ࣌', 'سيقول ࡲلسفهاء من ࡰلناس ما وليهم عن قبلتهم ࡲلتے كانوا عليها࣌ قل لله ࡴلمشرق والمغرب࣌ يهدے من يشاء ࡹلى صرط مستقيم࣌', NULL, 22, 'local:warsh-text.json'),
  ('warsh-2-142', 'warsh', 2, 142, 'وَكَذَٰلِكَ جَعَلْنَٰكُمُۥٓ أُمَّةࣰ وَسَطاࣰ࣌ لِّتَكُونُواْ شُهَدَآءَ عَلَى ࡰ۬لنَّاسِ وَيَكُونَ ࡰ۬لرَّسُولُ عَلَيْكُمْ شَهِيداࣰ࣌ وَمَا جَعَلْنَا ࡰ۬لْقِبْلَةَ ࡰ۬لتِے كُنتَ عَلَيْهَآ إِلَّا لِنَعْلَمَ مَنْ يَّتَّبِعُ ࡲ۬لرَّسُولَ مِمَّنْ يَّنقَلِبُ عَلَىٰ عَقِبَيْهِ࣌ وَإِن كَانَتْ لَكَبِيرَةً ࡴلَّا عَلَى ࡰ۬لذِينَ هَدَى ࡰ۬للَّهُ࣌ وَمَا كَانَ ࡰ۬للَّهُ لِيُضِيعَ إِيمَٰنَكُمُۥٓ࣌ إِنَّ ࡰ۬للَّهَ بِالنَّاسِ لَرَءُوفࣱ رَّحِيمࣱ࣌', 'وكذلك جعلنكم أمة وسطا࣌ لتكونوا شهداء على ࡰلناس ويكون ࡰلرسول عليكم شهيدا࣌ وما جعلنا ࡰلقبلة ࡰلتے كنت عليها إلا لنعلم من يتبع ࡲلرسول ممن ينقلب على عقبيه࣌ وإن كانت لكبيرة ࡴلا على ࡰلذين هدى ࡰلله࣌ وما كان ࡰلله ليضيع إيمنكم࣌ إن ࡰلله بالناس لرءوف رحيم࣌', NULL, 22, 'local:warsh-text.json'),
  ('warsh-2-143', 'warsh', 2, 143, 'قَدْ نَرٜىٰ تَقَلُّبَ وَجْهِكَ فِے ࡴ۬لسَّمَآءِ فَلَنُوَلِّيَنَّكَ قِبْلَةࣰ تَرْضٜيٰهَا࣌ فَوَلِّ وَجْهَكَ شَطْرَ ࡰ۬لْمَسْجِدِ ࡴ۬لْحَرَامِ࣌ وَحَيْثُ مَا كُنتُمْ فَوَلُّواْ وُجُوهَكُمْ شَطْرَهُۥ࣌ وَإِنَّ ࡰ۬لذِينَ أُوتُواْ ࡲ۬لْكِتَٰبَ لَيَعْلَمُونَ أَنَّهُ ࡲ۬لْحَقُّ مِن رَّبِّهِمْ࣌ وَمَا ࡰ۬للَّهُ بِغَٰفِلٍ عَمَّا يَعْمَلُونَ࣌', 'قد نرى تقلب وجهك فے ࡴلسماء فلنولينك قبلة ترضيها࣌ فول وجهك شطر ࡰلمسجد ࡴلحرام࣌ وحيث ما كنتم فولوا وجوهكم شطره࣌ وإن ࡰلذين أوتوا ࡲلكتب ليعلمون أنه ࡲلحق من ربهم࣌ وما ࡰلله بغفل عما يعملون࣌', NULL, 22, 'local:warsh-text.json'),
  ('warsh-2-144', 'warsh', 2, 144, 'وَلَئِنَ ࡰتَيْتَ ࡰ۬لذِينَ أُوتُواْ ࡲ۬لْكِتَٰبَ بِكُلِّ ءَايَةࣲ مَّا تَبِعُواْ قِبْلَتَكَ࣌ وَمَآ أَنتَ بِتَابِعࣲ قِبْلَتَهُمْ࣌ وَمَا بَعْضُهُم بِتَابِعࣲ قِبْلَةَ بَعْضࣲ࣌ وَلَئِنِ ࡴٜتَّبَعْتَ أَهْوَآءَهُم مِّنۢ بَعْدِ مَا جَآءَكَ مِنَ ࡰ۬لْعِلْمِ إِنَّكَ إِذاࣰ لَّمِنَ ࡰ۬لظَّٰلِمِينَ࣌', 'ولئن ࡰتيت ࡰلذين أوتوا ࡲلكتب بكل ءاية ما تبعوا قبلتك࣌ وما أنت بتابع قبلتهم࣌ وما بعضهم بتابع قبلة بعض࣌ ولئن ࡴتبعت أهواءهم من بعد ما جاءك من ࡰلعلم إنك إذا لمن ࡰلظلمين࣌', NULL, 22, 'local:warsh-text.json'),
  ('warsh-2-145', 'warsh', 2, 145, 'ࡰ۬لذِينَ ءَاتَيْنَٰهُمُ ࡲ۬لْكِتَٰبَ يَعْرِفُونَهُۥ كَمَا يَعْرِفُونَ أَبْنَآءَهُمْ࣌ وَإِنَّ فَرِيقاࣰ مِّنْهُمْ لَيَكْتُمُونَ ࡰ۬لْحَقَّ وَهُمْ يَعْلَمُونَ࣌', 'ࡰلذين ءاتينهم ࡲلكتب يعرفونه كما يعرفون أبناءهم࣌ وإن فريقا منهم ليكتمون ࡰلحق وهم يعلمون࣌', NULL, 23, 'local:warsh-text.json'),
  ('warsh-2-146', 'warsh', 2, 146, 'ࡰ۬لْحَقُّ مِن رَّبِّكَ࣌ فَلَا تَكُونَنَّ مِنَ ࡰ۬لْمُمْتَرِينَ࣌', 'ࡰلحق من ربك࣌ فلا تكونن من ࡰلممترين࣌', NULL, 23, 'local:warsh-text.json'),
  ('warsh-2-147', 'warsh', 2, 147, '۞ وَلِكُلࣲّ وِجْهَةٌ هُوَ مُوَلِّيهَا فَاسْتَبِقُواْ ࡲ۬لْخَيْرَٰتِ࣌ أَيْنَ مَا تَكُونُواْ يَاتِ بِكُمُ ࡲ۬للَّهُ جَمِيعاً࣌ ࡴنَّ ࡰ۬للَّهَ عَلَىٰ كُلِّ شَےْءࣲ قَدِيرࣱ࣌', 'ولكل وجهة هو موليها فاستبقوا ࡲلخيرت࣌ أين ما تكونوا يات بكم ࡲلله جميعا࣌ ࡴن ࡰلله على كل شےء قدير࣌', NULL, 23, 'local:warsh-text.json'),
  ('warsh-2-148', 'warsh', 2, 148, 'وَمِنْ حَيْثُ خَرَجْتَ فَوَلِّ وَجْهَكَ شَطْرَ ࡰ۬لْمَسْجِدِ ࡴ۬لْحَرَامِ࣌ وَإِنَّهُۥ لَلْحَقُّ مِن رَّبِّكَ࣌ وَمَا ࡰ۬للَّهُ بِغَٰفِلٍ عَمَّا تَعْمَلُونَ࣌', 'ومن حيث خرجت فول وجهك شطر ࡰلمسجد ࡴلحرام࣌ وإنه للحق من ربك࣌ وما ࡰلله بغفل عما تعملون࣌', NULL, 23, 'local:warsh-text.json'),
  ('warsh-2-149', 'warsh', 2, 149, 'وَمِنْ حَيْثُ خَرَجْتَ فَوَلِّ وَجْهَكَ شَطْرَ ࡰ۬لْمَسْجِدِ ࡴ۬لْحَرَامِ࣌ وَحَيْثُ مَا كُنتُمْ فَوَلُّواْ وُجُوهَكُمْ شَطْرَهُۥ لِيَ۬لَّا يَكُونَ لِلنَّاسِ عَلَيْكُمْ حُجَّةٌ ࡴلَّا ࡰ۬لذِينَ ظَلَمُواْ مِنْهُمْ فَلَا تَخْشَوْهُمْ وَاخْشَوْنِے࣌ وَلِأُتِمَّ نِعْمَتِے عَلَيْكُمْ وَلَعَلَّكُمْ تَهْتَدُونَ࣌', 'ومن حيث خرجت فول وجهك شطر ࡰلمسجد ࡴلحرام࣌ وحيث ما كنتم فولوا وجوهكم شطره ليلا يكون للناس عليكم حجة ࡴلا ࡰلذين ظلموا منهم فلا تخشوهم واخشونے࣌ ولأتم نعمتے عليكم ولعلكم تهتدون࣌', NULL, 23, 'local:warsh-text.json'),
  ('warsh-2-150', 'warsh', 2, 150, 'كَمَآ أَرْسَلْنَا فِيكُمْ رَسُولاࣰ مِّنكُمْ يَتْلُواْ عَلَيْكُمُۥٓ ءَايَٰتِنَا وَيُزَكِّيكُمْ وَيُعَلِّمُكُمُ ࡲ۬لْكِتَٰبَ وَالْحِكْمَةَ وَيُعَلِّمُكُم مَّا لَمْ تَكُونُواْ تَعْلَمُونَ', 'كما أرسلنا فيكم رسولا منكم يتلوا عليكم ءايتنا ويزكيكم ويعلمكم ࡲلكتب والحكمة ويعلمكم ما لم تكونوا تعلمون', NULL, 23, 'local:warsh-text.json'),
  ('warsh-2-151', 'warsh', 2, 151, 'فَاذْكُرُونِےٓ أَذْكُرْكُمْ وَاشْكُرُواْ لِے وَلَا تَكْفُرُونِ࣌', 'فاذكرونے أذكركم واشكروا لے ولا تكفرون࣌', NULL, 23, 'local:warsh-text.json'),
  ('warsh-2-152', 'warsh', 2, 152, 'يَٰٓأَيُّهَا ࡰ۬لذِينَ ءَامَنُواْ ࡲٜسْتَعِينُواْ بِالصَّبْرِ وَالصَّلَوٰةِ࣌ إِنَّ ࡰ۬للَّهَ مَعَ ࡰ۬لصَّٰبِرِينَ࣌', 'يأيها ࡰلذين ءامنوا ࡲستعينوا بالصبر والصلوة࣌ إن ࡰلله مع ࡰلصبرين࣌', NULL, 23, 'local:warsh-text.json'),
  ('warsh-2-153', 'warsh', 2, 153, 'وَلَا تَقُولُواْ لِمَنْ يُّقْتَلُ فِے سَبِيلِ ࡴ۬للَّهِ أَمْوَٰتُۢ࣌ بَلَ ࡰحْيَآءࣱ࣌ وَلَٰكِن لَّا تَشْعُرُونَ࣌', 'ولا تقولوا لمن يقتل فے سبيل ࡴلله أموت࣌ بل ࡰحياء࣌ ولكن لا تشعرون࣌', NULL, 24, 'local:warsh-text.json'),
  ('warsh-2-154', 'warsh', 2, 154, 'وَلَنَبْلُوَنَّكُم بِشَےْءࣲ مِّنَ ࡰ۬لْخَوْفِ وَالْجُوعِ وَنَقْصࣲ مِّنَ ࡰ۬لَامْوَٰلِ وَالَانفُسِ وَالثَّمَرَٰتِ࣌ وَبَشِّرِ ࡴ۬لصَّٰبِرِينَ', 'ولنبلونكم بشےء من ࡰلخوف والجوع ونقص من ࡰلامول والانفس والثمرت࣌ وبشر ࡴلصبرين', NULL, 24, 'local:warsh-text.json'),
  ('warsh-2-155', 'warsh', 2, 155, 'ࡰ۬لذِينَ إِذَآ أَصَٰبَتْهُم مُّصِيبَةࣱ قَالُوٓاْ إِنَّا لِلهِ وَإِنَّآ إِلَيْهِ رَٰجِعُونَ࣌', 'ࡰلذين إذا أصبتهم مصيبة قالوا إنا لله وإنا إليه رجعون࣌', NULL, 24, 'local:warsh-text.json'),
  ('warsh-2-156', 'warsh', 2, 156, 'أُوْلَٰٓئِكَ عَلَيْهِمْ صَلَوَٰتࣱ مِّن رَّبِّهِمْ وَرَحْمَةࣱ࣌ وَأُوْلَٰٓئِكَ هُمُ ࡲ۬لْمُهْتَدُونَ࣌', 'أولئك عليهم صلوت من ربهم ورحمة࣌ وأولئك هم ࡲلمهتدون࣌', NULL, 24, 'local:warsh-text.json'),
  ('warsh-2-157', 'warsh', 2, 157, '۞ إِنَّ ࡰ۬لصَّفَا وَالْمَرْوَةَ مِن شَعَٰٓئِرِ ࡴ۬للَّهِ࣌ فَمَنْ حَجَّ ࡰ۬لْبَيْتَ أَوِ ࡴٜعْتَمَرَ فَلَا جُنَاحَ عَلَيْهِ أَنْ يَّطَّوَّفَ بِهِمَا࣌ وَمَن تَطَوَّعَ خَيْراࣰ فَإِنَّ ࡰ۬للَّهَ شَاكِرٌ عَلِيمٌ࣌', 'إن ࡰلصفا والمروة من شعئر ࡴلله࣌ فمن حج ࡰلبيت أو ࡴعتمر فلا جناح عليه أن يطوف بهما࣌ ومن تطوع خيرا فإن ࡰلله شاكر عليم࣌', NULL, 24, 'local:warsh-text.json'),
  ('warsh-2-158', 'warsh', 2, 158, 'ࡴنَّ ࡰ۬لذِينَ يَكْتُمُونَ مَآ أَنزَلْنَا مِنَ ࡰ۬لْبَيِّنَٰتِ وَالْهُدٜىٰ مِنۢ بَعْدِ مَا بَيَّنَّٰهُ لِلنَّاسِ فِے ࡴ۬لْكِتَٰبِ أُوْلَٰٓئِكَ يَلْعَنُهُمُ ࡲ۬للَّهُ وَيَلْعَنُهُمُ ࡲ۬للَّٰعِنُونَ', 'ࡴن ࡰلذين يكتمون ما أنزلنا من ࡰلبينت والهدى من بعد ما بينه للناس فے ࡴلكتب أولئك يلعنهم ࡲلله ويلعنهم ࡲللعنون', NULL, 24, 'local:warsh-text.json'),
  ('warsh-2-159', 'warsh', 2, 159, 'إِلَّا ࡰ۬لذِينَ تَابُواْ وَأَصْلَحُواْ وَبَيَّنُواْ فَأُوْلَٰٓئِكَ أَتُوبُ عَلَيْهِمْ وَأَنَا ࡰ۬لتَّوَّابُ ࡲ۬لرَّحِيمُ࣌', 'إلا ࡰلذين تابوا وأصلحوا وبينوا فأولئك أتوب عليهم وأنا ࡰلتواب ࡲلرحيم࣌', NULL, 24, 'local:warsh-text.json'),
  ('warsh-2-160', 'warsh', 2, 160, 'إِنَّ ࡰ۬لذِينَ كَفَرُواْ وَمَاتُواْ وَهُمْ كُفَّارٌ ࡳوْلَٰٓئِكَ عَلَيْهِمْ لَعْنَةُ ࡲ۬للَّهِ وَالْمَلَٰٓئِكَةِ وَالنَّاسِ أَجْمَعِينَ', 'إن ࡰلذين كفروا وماتوا وهم كفار ࡳولئك عليهم لعنة ࡲلله والملئكة والناس أجمعين', NULL, 24, 'local:warsh-text.json'),
  ('warsh-2-161', 'warsh', 2, 161, 'خَٰلِدِينَ فِيهَا࣌ لَا يُخَفَّفُ عَنْهُمُ ࡲ۬لْعَذَابُ وَلَا هُمْ يُنظَرُونَ࣌', 'خلدين فيها࣌ لا يخفف عنهم ࡲلعذاب ولا هم ينظرون࣌', NULL, 24, 'local:warsh-text.json'),
  ('warsh-2-162', 'warsh', 2, 162, 'وَإِلَٰهُكُمُۥٓ إِلَٰهࣱ وَٰحِدࣱ࣌ لَّآ إِلَٰهَ إِلَّا هُوَ࣌ ࡰ۬لرَّحْمَٰنُ ࡲ۬لرَّحِيمُ࣌', 'وإلهكم إله وحد࣌ لا إله إلا هو࣌ ࡰلرحمن ࡲلرحيم࣌', NULL, 24, 'local:warsh-text.json'),
  ('warsh-2-163', 'warsh', 2, 163, 'إِنَّ فِے خَلْقِ ࡴ۬لسَّمَٰوَٰتِ وَالَارْضِ وَاخْتِلَٰفِ ࡴ۬ليْلِ وَالنَّهٜارِ وَالْفُلْكِ ࡴ۬لتِے تَجْرِے فِے ࡴ۬لْبَحْرِ بِمَا يَنفَعُ ࡲ۬لنَّاسَ وَمَآ أَنزَلَ ࡰ۬للَّهُ مِنَ ࡰ۬لسَّمَآءِ مِن مَّآءࣲ فَأَحْيٜا بِهِ ࡴ۬لَارْضَ بَعْدَ مَوْتِهَا وَبَثَّ فِيهَا مِن كُلِّ دَآبَّةࣲ وَتَصْرِيفِ ࡴ۬لرِّيَٰحِ وَالسَّحَابِ ࡴ۬لْمُسَخَّرِ بَيْنَ ࡰ۬لسَّمَآءِ وَالَارْضِ لَأٓيَٰتࣲ لِّقَوْمࣲ يَعْقِلُونَ࣌', 'إن فے خلق ࡴلسموت والارض واختلف ࡴليل والنهار والفلك ࡴلتے تجرے فے ࡴلبحر بما ينفع ࡲلناس وما أنزل ࡰلله من ࡰلسماء من ماء فأحيا به ࡴلارض بعد موتها وبث فيها من كل دابة وتصريف ࡴلريح والسحاب ࡴلمسخر بين ࡰلسماء والارض لأيت لقوم يعقلون࣌', NULL, 25, 'local:warsh-text.json'),
  ('warsh-2-164', 'warsh', 2, 164, 'وَمِنَ ࡰ۬لنَّاسِ مَنْ يَّتَّخِذُ مِن دُونِ ࡴ۬للَّهِ أَندَاداࣰ يُحِبُّونَهُمْ كَحُبِّ ࡴ۬للَّهِ࣌ وَالذِينَ ءَامَنُوٓاْ أَشَدُّ حُبّاࣰ لِّلهِ࣌ وَلَوْ تَرَى ࡰ۬لذِينَ ظَلَمُوٓاْ إِذْ يَرَوْنَ ࡰ۬لْعَذَابَ أَنَّ ࡰ۬لْقُوَّةَ لِلهِ جَمِيعاࣰ وَأَنَّ ࡰ۬للَّهَ شَدِيدُ ࡲ۬لْعَذَابِ࣌', 'ومن ࡰلناس من يتخذ من دون ࡴلله أندادا يحبونهم كحب ࡴلله࣌ والذين ءامنوا أشد حبا لله࣌ ولو ترى ࡰلذين ظلموا إذ يرون ࡰلعذاب أن ࡰلقوة لله جميعا وأن ࡰلله شديد ࡲلعذاب࣌', NULL, 25, 'local:warsh-text.json'),
  ('warsh-2-165', 'warsh', 2, 165, '۞ إِذْ تَبَرَّأَ ࡰ۬لذِينَ ࡸَتُّبِعُواْ مِنَ ࡰ۬لذِينَ ࡰٜتَّبَعُواْ وَرَأَوُاْ ࡲ۬لْعَذَابَ وَتَقَطَّعَتْ بِهِمُ ࡲ۬لَاسْبَٰبُ࣌', 'إذ تبرأ ࡰلذين ࡸتبعوا من ࡰلذين ࡰتبعوا ورأوا ࡲلعذاب وتقطعت بهم ࡲلاسبب࣌', NULL, 25, 'local:warsh-text.json'),
  ('warsh-2-166', 'warsh', 2, 166, 'وَقَالَ ࡰ۬لذِينَ ࡰٜتَّبَعُواْ لَوَ ࡰنَّ لَنَا كَرَّةࣰ فَنَتَبَرَّأَ مِنْهُمْ كَمَا تَبَرَّءُواْ مِنَّا࣌ كَذَٰلِكَ يُرِيهِمُ ࡲ۬للَّهُ أَعْمَٰلَهُمْ حَسَرَٰتٍ عَلَيْهِمْ࣌ وَمَا هُم بِخَٰرِجِينَ مِنَ ࡰ۬لنّٜارِ࣌', 'وقال ࡰلذين ࡰتبعوا لو ࡰن لنا كرة فنتبرأ منهم كما تبرءوا منا࣌ كذلك يريهم ࡲلله أعملهم حسرت عليهم࣌ وما هم بخرجين من ࡰلنار࣌', NULL, 25, 'local:warsh-text.json'),
  ('warsh-2-167', 'warsh', 2, 167, 'يَٰٓأَيُّهَا ࡰ۬لنَّاسُ كُلُواْ مِمَّا فِے ࡴ۬لَارْضِ حَلَٰلاࣰ طَيِّباࣰ࣌ وَلَا تَتَّبِعُواْ خُطْوَٰتِ ࡴ۬لشَّيْطَٰنِ࣌ إِنَّهُۥ لَكُمْ عَدُوࣱّ مُّبِينٌ࣌', 'يأيها ࡰلناس كلوا مما فے ࡴلارض حللا طيبا࣌ ولا تتبعوا خطوت ࡴلشيطن࣌ إنه لكم عدو مبين࣌', NULL, 25, 'local:warsh-text.json'),
  ('warsh-2-168', 'warsh', 2, 168, 'ࡴنَّمَا يَامُرُكُم بِالسُّوٓءِ وَالْفَحْشَآءِ وَأَن تَقُولُواْ عَلَى ࡰ۬للَّهِ مَا لَا تَعْلَمُونَ࣌', 'ࡴنما يامركم بالسوء والفحشاء وأن تقولوا على ࡰلله ما لا تعلمون࣌', NULL, 25, 'local:warsh-text.json'),
  ('warsh-2-169', 'warsh', 2, 169, 'وَإِذَا قِيلَ لَهُمُ ࡲٜتَّبِعُواْ مَآ أَنزَلَ ࡰ۬للَّهُ قَالُواْ بَلْ نَتَّبِعُ مَآ أَلْفَيْنَا عَلَيْهِ ءَابَآءَنَآ࣌ أَوَلَوْ كَانَ ءَابَآؤُهُمْ لَا يَعْقِلُونَ شَيْـٔاࣰ وَلَا يَهْتَدُونَ࣌', 'وإذا قيل لهم ࡲتبعوا ما أنزل ࡰلله قالوا بل نتبع ما ألفينا عليه ءاباءنا࣌ أولو كان ءاباؤهم لا يعقلون شيا ولا يهتدون࣌', NULL, 26, 'local:warsh-text.json'),
  ('warsh-2-170', 'warsh', 2, 170, 'وَمَثَلُ ࡲ۬لذِينَ كَفَرُواْ كَمَثَلِ ࡴ۬لذِے يَنْعِقُ بِمَا لَا يَسْمَعُ إِلَّا دُعَآءࣰ وَنِدَآءࣰ࣌ صُمُّۢ بُكْمٌ عُمْيࣱ فَهُمْ لَا يَعْقِلُونَ࣌', 'ومثل ࡲلذين كفروا كمثل ࡴلذے ينعق بما لا يسمع إلا دعاء ونداء࣌ صم بكم عمي فهم لا يعقلون࣌', NULL, 26, 'local:warsh-text.json'),
  ('warsh-2-171', 'warsh', 2, 171, 'يَٰٓأَيُّهَا ࡰ۬لذِينَ ءَامَنُواْ كُلُواْ مِن طَيِّبَٰتِ مَا رَزَقْنَٰكُمْ وَاشْكُرُواْ لِلهِ إِن كُنتُمُۥٓ إِيَّاهُ تَعْبُدُونَ࣌', 'يأيها ࡰلذين ءامنوا كلوا من طيبت ما رزقنكم واشكروا لله إن كنتم إياه تعبدون࣌', NULL, 26, 'local:warsh-text.json'),
  ('warsh-2-172', 'warsh', 2, 172, 'إِنَّمَا حَرَّمَ عَلَيْكُمُ ࡲ۬لْمَيْتَةَ وَالدَّمَ وَلَحْمَ ࡰ۬لْخِنزِيرِ وَمَآ أُهِلَّ بِهِۦ لِغَيْرِ ࡴ۬للَّهِ࣌ فَمَنُ ࡲ࢈ضْطُرَّ غَيْرَ بَاغࣲ وَلَا عَادࣲ فَلَآ إِثْمَ عَلَيْهِ࣌ إِنَّ ࡰ۬للَّهَ غَفُورࣱ رَّحِيمٌ࣌', 'إنما حرم عليكم ࡲلميتة والدم ولحم ࡰلخنزير وما أهل به لغير ࡴلله࣌ فمن ࡲ࢈ضطر غير باغ ولا عاد فلا إثم عليه࣌ إن ࡰلله غفور رحيم࣌', NULL, 26, 'local:warsh-text.json'),
  ('warsh-2-173', 'warsh', 2, 173, 'ࡴنَّ ࡰ۬لذِينَ يَكْتُمُونَ مَآ أَنزَلَ ࡰ۬للَّهُ مِنَ ࡰ۬لْكِتَٰبِ وَيَشْتَرُونَ بِهِۦ ثَمَناࣰ قَلِيلاً ࡳوْلَٰٓئِكَ مَا يَاكُلُونَ فِے بُطُونِهِمُۥٓ إِلَّا ࡰ۬لنَّارَ وَلَا يُكَلِّمُهُمُ ࡲ۬للَّهُ يَوْمَ ࡰ۬لْقِيَٰمَةِ وَلَا يُزَكِّيهِمْ࣌ وَلَهُمْ عَذَابٌ ࡰلِيمٌ࣌', 'ࡴن ࡰلذين يكتمون ما أنزل ࡰلله من ࡰلكتب ويشترون به ثمنا قليلا ࡳولئك ما ياكلون فے بطونهم إلا ࡰلنار ولا يكلمهم ࡲلله يوم ࡰلقيمة ولا يزكيهم࣌ ولهم عذاب ࡰليم࣌', NULL, 26, 'local:warsh-text.json'),
  ('warsh-2-174', 'warsh', 2, 174, 'ࡳوْلَٰٓئِكَ ࡰ۬لذِينَ ࡰٜشْتَرَوُاْ ࡲ۬لضَّلَٰلَةَ بِالْهُدٜىٰ وَالْعَذَابَ بِالْمَغْفِرَةِ فَمَآ أَصْبَرَهُمْ عَلَى ࡰ۬لنّٜارِ࣌', 'ࡳولئك ࡰلذين ࡰشتروا ࡲلضللة بالهدى والعذاب بالمغفرة فما أصبرهم على ࡰلنار࣌', NULL, 26, 'local:warsh-text.json'),
  ('warsh-2-175', 'warsh', 2, 175, 'ذَٰلِكَ بِأَنَّ ࡰ۬للَّهَ نَزَّلَ ࡰ۬لْكِتَٰبَ بِالْحَقِّ࣌ وَإِنَّ ࡰ۬لذِينَ ࡰٜخْتَلَفُواْ فِے ࡴ۬لْكِتَٰبِ لَفِے شِقَاقِۢ بَعِيدࣲ࣌', 'ذلك بأن ࡰلله نزل ࡰلكتب بالحق࣌ وإن ࡰلذين ࡰختلفوا فے ࡴلكتب لفے شقاق بعيد࣌', NULL, 26, 'local:warsh-text.json'),
  ('warsh-2-176', 'warsh', 2, 176, '۞ لَّيْسَ ࡰ۬لْبِرُّ أَن تُوَلُّواْ وُجُوهَكُمْ قِبَلَ ࡰ۬لْمَشْرِقِ وَالْمَغْرِبِ࣌ وَلَٰكِنِ ࡴ۬لْبِرُّ مَنَ اٰمَنَ بِاللَّهِ وَالْيَوْمِ ࡴ۬لَاخِرِ وَالْمَلَٰٓئِكَةِ وَالْكِتَٰبِ وَالنَّبِيٓـِٕۑنَ وَءَاتَى ࡰ۬لْمَالَ عَلَىٰ حُبِّهِۦ ذَوِے ࡴ۬لْقُرْبٜىٰ وَالْيَتَٰمٜىٰ وَالْمَسَٰكِينَ وَابْنَ ࡰ۬لسَّبِيلِ وَالسَّآئِلِينَ وَفِے ࡴ۬لرِّقَابِ وَأَقَامَ ࡰ۬لصَّلَوٰةَ وَءَاتَى ࡰ۬لزَّكَوٰةَ࣌ وَالْمُوفُونَ بِعَهْدِهِمُۥٓ إِذَا عَٰهَدُواْ࣌ وَالصَّٰبِرِينَ فِے ࡴ۬لْبَأْسَآءِ وَالضَّرَّآءِ وَحِينَ ࡰ۬لْبَأْسِ࣌ أُوْلَٰٓئِكَ ࡰ۬لذِينَ صَدَقُواْ࣌ وَأُوْلَٰٓئِكَ هُمُ ࡲ۬لْمُتَّقُونَ࣌', 'ليس ࡰلبر أن تولوا وجوهكم قبل ࡰلمشرق والمغرب࣌ ولكن ࡴلبر من امن بالله واليوم ࡴلاخر والملئكة والكتب والنبيۑن وءاتى ࡰلمال على حبه ذوے ࡴلقربى واليتمى والمسكين وابن ࡰلسبيل والسائلين وفے ࡴلرقاب وأقام ࡰلصلوة وءاتى ࡰلزكوة࣌ والموفون بعهدهم إذا عهدوا࣌ والصبرين فے ࡴلبأساء والضراء وحين ࡰلبأس࣌ أولئك ࡰلذين صدقوا࣌ وأولئك هم ࡲلمتقون࣌', NULL, 27, 'local:warsh-text.json'),
  ('warsh-2-177', 'warsh', 2, 177, 'يَٰٓأَيُّهَا ࡰ۬لذِينَ ءَامَنُواْ كُتِبَ عَلَيْكُمُ ࡲ۬لْقِصَاصُ فِے ࡴ۬لْقَتْلَى࣌ ࡰ۬لْحُرُّ بِالْحُرِّ وَالْعَبْدُ بِالْعَبْدِ وَالُانثٜىٰ بِالُانثٜىٰ࣌ فَمَنْ عُفِيَ لَهُۥ مِنَ ࡰخِيهِ شَےْءࣱ فَاتِّبَاعُۢ بِالْمَعْرُوفِ وَأَدَآءٌ ࡴلَيْهِ بِإِحْسَٰنࣲ࣌ ذَٰلِكَ تَخْفِيفࣱ مِّن رَّبِّكُمْ وَرَحْمَةࣱ࣌ فَمَنِ ࡴٜعْتَدٜىٰ بَعْدَ ذَٰلِكَ فَلَهُۥ عَذَابٌ ࡰلِيمࣱ࣌', 'يأيها ࡰلذين ءامنوا كتب عليكم ࡲلقصاص فے ࡴلقتلى࣌ ࡰلحر بالحر والعبد بالعبد والانثى بالانثى࣌ فمن عفي له من ࡰخيه شےء فاتباع بالمعروف وأداء ࡴليه بإحسن࣌ ذلك تخفيف من ربكم ورحمة࣌ فمن ࡴعتدى بعد ذلك فله عذاب ࡰليم࣌', NULL, 27, 'local:warsh-text.json'),
  ('warsh-2-178', 'warsh', 2, 178, 'وَلَكُمْ فِے ࡴ۬لْقِصَاصِ حَيَوٰةࣱ يَٰٓأُوْلِے ࡴ۬لَالْبَٰبِ لَعَلَّكُمْ تَتَّقُونَ࣌', 'ولكم فے ࡴلقصاص حيوة يأولے ࡴلالبب لعلكم تتقون࣌', NULL, 27, 'local:warsh-text.json'),
  ('warsh-2-179', 'warsh', 2, 179, 'كُتِبَ عَلَيْكُمُۥٓ إِذَا حَضَرَ أَحَدَكُمُ ࡲ۬لْمَوْتُ إِن تَرَكَ خَيْراً࣌ ࡴ۬لْوَصِيَّةُ لِلْوَٰلِدَيْنِ وَالَاقْرَبِينَ بِالْمَعْرُوفِ࣌ حَقّاً عَلَى ࡰ۬لْمُتَّقِينَ࣌', 'كتب عليكم إذا حضر أحدكم ࡲلموت إن ترك خيرا࣌ ࡴلوصية للولدين والاقربين بالمعروف࣌ حقا على ࡰلمتقين࣌', NULL, 27, 'local:warsh-text.json'),
  ('warsh-2-180', 'warsh', 2, 180, 'فَمَنۢ بَدَّلَهُۥ بَعْدَ مَا سَمِعَهُۥ فَإِنَّمَآ إِثْمُهُۥ عَلَى ࡰ۬لذِينَ يُبَدِّلُونَهُۥٓ࣌ إِنَّ ࡰ۬للَّهَ سَمِيعٌ عَلِيمࣱ࣌', 'فمن بدله بعد ما سمعه فإنما إثمه على ࡰلذين يبدلونه࣌ إن ࡰلله سميع عليم࣌', NULL, 27, 'local:warsh-text.json'),
  ('warsh-2-181', 'warsh', 2, 181, 'فَمَنْ خَافَ مِن مُّوصࣲ جَنَفاً ࡰوِ ࡴثْماࣰ فَأَصْلَحَ بَيْنَهُمْ فَلَآ إِثْمَ عَلَيْهِ࣌ إِنَّ ࡰ۬للَّهَ غَفُورࣱ رَّحِيمࣱ࣌', 'فمن خاف من موص جنفا ࡰو ࡴثما فأصلح بينهم فلا إثم عليه࣌ إن ࡰلله غفور رحيم࣌', NULL, 28, 'local:warsh-text.json'),
  ('warsh-2-182', 'warsh', 2, 182, 'يَٰٓأَيُّهَا ࡰ۬لذِينَ ءَامَنُواْ كُتِبَ عَلَيْكُمُ ࡲ۬لصِّيَامُ كَمَا كُتِبَ عَلَى ࡰ۬لذِينَ مِن قَبْلِكُمْ لَعَلَّكُمْ تَتَّقُونَ', 'يأيها ࡰلذين ءامنوا كتب عليكم ࡲلصيام كما كتب على ࡰلذين من قبلكم لعلكم تتقون', NULL, 28, 'local:warsh-text.json'),
  ('warsh-2-183', 'warsh', 2, 183, 'أَيَّاماࣰ مَّعْدُودَٰتࣲ࣌ فَمَن كَانَ مِنكُم مَّرِيضاً ࡰوْ عَلَىٰ سَفَرࣲ فَعِدَّةࣱ مِّنَ ࡰيَّامٍ ࡳخَرَ࣌ وَعَلَى ࡰ۬لذِينَ يُطِيقُونَهُۥ فِدْيَةُ طَعَامِ مَسَٰكِينَ࣌ فَمَن تَطَوَّعَ خَيْراࣰ فَهُوَ خَيْرࣱ لَّهُۥ࣌ وَأَن تَصُومُواْ خَيْرࣱ لَّكُمُۥٓ إِن كُنتُمْ تَعْلَمُونَ࣌', 'أياما معدودت࣌ فمن كان منكم مريضا ࡰو على سفر فعدة من ࡰيام ࡳخر࣌ وعلى ࡰلذين يطيقونه فدية طعام مسكين࣌ فمن تطوع خيرا فهو خير له࣌ وأن تصوموا خير لكم إن كنتم تعلمون࣌', NULL, 28, 'local:warsh-text.json'),
  ('warsh-2-184', 'warsh', 2, 184, '۞ شَهْرُ رَمَضَانَ ࡰ۬لذِےٓ أُنزِلَ فِيهِ ࡴ۬لْقُرْءَانُ هُدىࣰ لِّلنَّاسِ وَبَيِّنَٰتࣲ مِّنَ ࡰ۬لْهُدٜىٰ وَالْفُرْقَانِ࣌ فَمَن شَهِدَ مِنكُمُ ࡲ۬لشَّهْرَ فَلْيَصُمْهُ࣌ وَمَن كَانَ مَرِيضاً ࡰوْ عَلَىٰ سَفَرࣲ فَعِدَّةࣱ مِّنَ ࡰيَّامٍ ࡳخَرَ࣌ يُرِيدُ ࡲ۬للَّهُ بِكُمُ ࡲ۬لْيُسْرَ وَلَا يُرِيدُ بِكُمُ ࡲ۬لْعُسْرَ࣌ وَلِتُكْمِلُواْ ࡲ۬لْعِدَّةَ وَلِتُكَبِّرُواْ ࡲ۬للَّهَ عَلَىٰ مَا هَدٜيٰكُمْ وَلَعَلَّكُمْ تَشْكُرُونَ࣌', 'شهر رمضان ࡰلذے أنزل فيه ࡴلقرءان هدى للناس وبينت من ࡰلهدى والفرقان࣌ فمن شهد منكم ࡲلشهر فليصمه࣌ ومن كان مريضا ࡰو على سفر فعدة من ࡰيام ࡳخر࣌ يريد ࡲلله بكم ࡲليسر ولا يريد بكم ࡲلعسر࣌ ولتكملوا ࡲلعدة ولتكبروا ࡲلله على ما هديكم ولعلكم تشكرون࣌', NULL, 28, 'local:warsh-text.json'),
  ('warsh-2-185', 'warsh', 2, 185, 'وَإِذَا سَأَلَكَ عِبَادِے عَنِّے فَإِنِّے قَرِيبٌ࣌ ࡳجِيبُ دَعْوَةَ ࡰ۬لدَّاعِۦٓ إِذَا دَعَانِۦ࣌ فَلْيَسْتَجِيبُواْ لِے وَلْيُومِنُواْ بِيَ لَعَلَّهُمْ يَرْشُدُونَ࣌', 'وإذا سألك عبادے عنے فإنے قريب࣌ ࡳجيب دعوة ࡰلداع إذا دعان࣌ فليستجيبوا لے وليومنوا بي لعلهم يرشدون࣌', NULL, 28, 'local:warsh-text.json'),
  ('warsh-2-186', 'warsh', 2, 186, 'أُحِلَّ لَكُمْ لَيْلَةَ ࡰ۬لصِّيَامِ ࡴ۬لرَّفَثُ إِلَىٰ نِسَآئِكُمْ࣌ هُنَّ لِبَاسࣱ لَّكُمْ وَأَنتُمْ لِبَاسࣱ لَّهُنَّ࣌ عَلِمَ ࡰ۬للَّهُ أَنَّكُمْ كُنتُمْ تَخْتَانُونَ أَنفُسَكُمْ فَتَابَ عَلَيْكُمْ وَعَفَا عَنكُمْ࣌ فَالَٰنَ بَٰشِرُوهُنَّ࣌ وَابْتَغُواْ مَا كَتَبَ ࡰ۬للَّهُ لَكُمْ࣌ وَكُلُواْ وَاشْرَبُواْ حَتَّىٰ يَتَبَيَّنَ لَكُمُ ࡲ۬لْخَيْطُ ࡲ۬لَابْيَضُ مِنَ ࡰ۬لْخَيْطِ ࡴ۬لَاسْوَدِ مِنَ ࡰ۬لْفَجْرِ࣌ ثُمَّ أَتِمُّواْ ࡲ۬لصِّيَامَ إِلَى ࡰ۬ليْلِ࣌ وَلَا تُبَٰشِرُوهُنَّ وَأَنتُمْ عَٰكِفُونَ فِے ࡴ۬لْمَسَٰجِدِ࣌ تِلْكَ حُدُودُ ࡲ۬للَّهِ࣌ فَلَا تَقْرَبُوهَا࣌ كَذَٰلِكَ يُبَيِّنُ ࡲ۬للَّهُ ءَايَٰتِهِۦ لِلنَّاسِ لَعَلَّهُمْ يَتَّقُونَ࣌', 'أحل لكم ليلة ࡰلصيام ࡴلرفث إلى نسائكم࣌ هن لباس لكم وأنتم لباس لهن࣌ علم ࡰلله أنكم كنتم تختانون أنفسكم فتاب عليكم وعفا عنكم࣌ فالن بشروهن࣌ وابتغوا ما كتب ࡰلله لكم࣌ وكلوا واشربوا حتى يتبين لكم ࡲلخيط ࡲلابيض من ࡰلخيط ࡴلاسود من ࡰلفجر࣌ ثم أتموا ࡲلصيام إلى ࡰليل࣌ ولا تبشروهن وأنتم عكفون فے ࡴلمسجد࣌ تلك حدود ࡲلله࣌ فلا تقربوها࣌ كذلك يبين ࡲلله ءايته للناس لعلهم يتقون࣌', NULL, 29, 'local:warsh-text.json'),
  ('warsh-2-187', 'warsh', 2, 187, 'وَلَا تَاكُلُوٓاْ أَمْوَٰلَكُم بَيْنَكُم بِالْبَٰطِلِ وَتُدْلُواْ بِهَآ إِلَى ࡰ۬لْحُكَّامِ لِتَاكُلُواْ فَرِيقاࣰ مِّنَ ࡰمْوَٰلِ ࡴ۬لنَّاسِ بِالِاثْمِ وَأَنتُمْ تَعْلَمُونَ࣌', 'ولا تاكلوا أمولكم بينكم بالبطل وتدلوا بها إلى ࡰلحكام لتاكلوا فريقا من ࡰمول ࡴلناس بالاثم وأنتم تعلمون࣌', NULL, 29, 'local:warsh-text.json'),
  ('warsh-2-188', 'warsh', 2, 188, '۞ يَسْـَٔلُونَكَ عَنِ ࡴ۬لَاهِلَّةِ࣌ قُلْ هِيَ مَوَٰقِيتُ لِلنَّاسِ وَالْحَجِّ࣌ وَلَيْسَ ࡰ۬لْبِرُّ بِأَن تَاتُواْ ࡲ۬لْبُيُوتَ مِن ظُهُورِهَا࣌ وَلَٰكِنِ ࡴ۬لْبِرُّ مَنِ ࡴٜتَّقٜىٰ࣌ وَاتُواْ ࡲ۬لْبُيُوتَ مِنَ ࡰبْوَٰبِهَا࣌ وَاتَّقُواْ ࡲ۬للَّهَ لَعَلَّكُمْ تُفْلِحُونَ࣌', 'يسلونك عن ࡴلاهلة࣌ قل هي موقيت للناس والحج࣌ وليس ࡰلبر بأن تاتوا ࡲلبيوت من ظهورها࣌ ولكن ࡴلبر من ࡴتقى࣌ واتوا ࡲلبيوت من ࡰبوبها࣌ واتقوا ࡲلله لعلكم تفلحون࣌', NULL, 29, 'local:warsh-text.json'),
  ('warsh-2-189', 'warsh', 2, 189, 'وَقَٰتِلُواْ فِے سَبِيلِ ࡴ۬للَّهِ ࡴ۬لذِينَ يُقَٰتِلُونَكُمْ وَلَا تَعْتَدُوٓاْ࣌ إِنَّ ࡰ۬للَّهَ لَا يُحِبُّ ࡲ۬لْمُعْتَدِينَ࣌', 'وقتلوا فے سبيل ࡴلله ࡴلذين يقتلونكم ولا تعتدوا࣌ إن ࡰلله لا يحب ࡲلمعتدين࣌', NULL, 29, 'local:warsh-text.json'),
  ('warsh-2-190', 'warsh', 2, 190, 'وَاقْتُلُوهُمْ حَيْثُ ثَقِفْتُمُوهُمْ وَأَخْرِجُوهُم مِّنْ حَيْثُ أَخْرَجُوكُمْ࣌ وَالْفِتْنَةُ أَشَدُّ مِنَ ࡰ۬لْقَتْلِ࣌ وَلَا تُقَٰتِلُوهُمْ عِندَ ࡰ۬لْمَسْجِدِ ࡴ۬لْحَرَامِ حَتَّىٰ يُقَٰتِلُوكُمْ فِيهِ࣌ فَإِن قَٰتَلُوكُمْ فَاقْتُلُوهُمْ࣌ كَذَٰلِكَ جَزَآءُ ࡲ۬لْكٜـٰفِرِينَ࣌', 'واقتلوهم حيث ثقفتموهم وأخرجوهم من حيث أخرجوكم࣌ والفتنة أشد من ࡰلقتل࣌ ولا تقتلوهم عند ࡰلمسجد ࡴلحرام حتى يقتلوكم فيه࣌ فإن قتلوكم فاقتلوهم࣌ كذلك جزاء ࡲلكفرين࣌', NULL, 30, 'local:warsh-text.json'),
  ('warsh-2-191', 'warsh', 2, 191, 'فَإِنِ ࡴٜنتَهَوْاْ فَإِنَّ ࡰ۬للَّهَ غَفُورࣱ رَّحِيمࣱ࣌', 'فإن ࡴنتهوا فإن ࡰلله غفور رحيم࣌', NULL, 30, 'local:warsh-text.json'),
  ('warsh-2-192', 'warsh', 2, 192, 'وَقَٰتِلُوهُمْ حَتَّىٰ لَا تَكُونَ فِتْنَةࣱ وَيَكُونَ ࡰ۬لدِّينُ لِلهِ࣌ فَإِنِ ࡴٜنتَهَوْاْ فَلَا عُدْوَٰنَ إِلَّا عَلَى ࡰ۬لظَّٰلِمِينَ࣌', 'وقتلوهم حتى لا تكون فتنة ويكون ࡰلدين لله࣌ فإن ࡴنتهوا فلا عدون إلا على ࡰلظلمين࣌', NULL, 30, 'local:warsh-text.json'),
  ('warsh-2-193', 'warsh', 2, 193, 'ࡰ۬لشَّهْرُ ࡲ۬لْحَرَامُ بِالشَّهْرِ ࡴ۬لْحَرَامِ وَالْحُرُمَٰتُ قِصَاصࣱ࣌ فَمَنِ ࡴٜعْتَدٜىٰ عَلَيْكُمْ فَاعْتَدُواْ عَلَيْهِ بِمِثْلِ مَا ࡰٜعْتَدٜىٰ عَلَيْكُمْ࣌ وَاتَّقُواْ ࡲ۬للَّهَ وَاعْلَمُوٓاْ أَنَّ ࡰ۬للَّهَ مَعَ ࡰ۬لْمُتَّقِينَ࣌', 'ࡰلشهر ࡲلحرام بالشهر ࡴلحرام والحرمت قصاص࣌ فمن ࡴعتدى عليكم فاعتدوا عليه بمثل ما ࡰعتدى عليكم࣌ واتقوا ࡲلله واعلموا أن ࡰلله مع ࡰلمتقين࣌', NULL, 30, 'local:warsh-text.json'),
  ('warsh-2-194', 'warsh', 2, 194, 'وَأَنفِقُواْ فِے سَبِيلِ ࡴ۬للَّهِ وَلَا تُلْقُواْ بِأَيْدِيكُمُۥٓ إِلَى ࡰ۬لتَّهْلُكَةِ وَأَحْسِنُوٓاْ࣌ إِنَّ ࡰ۬للَّهَ يُحِبُّ ࡲ۬لْمُحْسِنِينَ࣌', 'وأنفقوا فے سبيل ࡴلله ولا تلقوا بأيديكم إلى ࡰلتهلكة وأحسنوا࣌ إن ࡰلله يحب ࡲلمحسنين࣌', NULL, 30, 'local:warsh-text.json'),
  ('warsh-2-195', 'warsh', 2, 195, 'وَأَتِمُّواْ ࡲ۬لْحَجَّ وَالْعُمْرَةَ لِلهِ࣌ فَإِنُ ࡳحْصِرْتُمْ فَمَا ࡰٜسْتَيْسَرَ مِنَ ࡰ۬لْهَدْيِ࣌ وَلَا تَحْلِقُواْ رُءُوسَكُمْ حَتَّىٰ يَبْلُغَ ࡰ۬لْهَدْيُ مَحِلَّهُۥ࣌ فَمَن كَانَ مِنكُم مَّرِيضاً ࡰوْ بِهِۦٓ أَذىࣰ مِّن رَّأْسِهِۦ فَفِدْيَةࣱ مِّن صِيَامٍ ࡰوْ صَدَقَةٍ ࡰوْ نُسُكࣲ࣌ فَإِذَآ أَمِنتُمْ فَمَن تَمَتَّعَ بِالْعُمْرَةِ إِلَى ࡰ۬لْحَجِّ فَمَا ࡰٜسْتَيْسَرَ مِنَ ࡰ۬لْهَدْيِ࣌ ۞ فَمَن لَّمْ يَجِدْ فَصِيَامُ ثَلَٰثَةِ أَيَّامࣲ فِے ࡴ۬لْحَجِّ وَسَبْعَةٍ ࡴذَا رَجَعْتُمْ تِلْكَ عَشَرَةࣱ كَامِلَةࣱ࣌ ذَٰلِكَ لِمَن لَّمْ يَكُنَ ࡰهْلُهُۥ حَاضِرِے ࡴ۬لْمَسْجِدِ ࡴ۬لْحَرَامِ࣌ وَاتَّقُواْ ࡲ۬للَّهَ وَاعْلَمُوٓاْ أَنَّ ࡰ۬للَّهَ شَدِيدُ ࡲ۬لْعِقَابِ࣌', 'وأتموا ࡲلحج والعمرة لله࣌ فإن ࡳحصرتم فما ࡰستيسر من ࡰلهدي࣌ ولا تحلقوا رءوسكم حتى يبلغ ࡰلهدي محله࣌ فمن كان منكم مريضا ࡰو به أذى من رأسه ففدية من صيام ࡰو صدقة ࡰو نسك࣌ فإذا أمنتم فمن تمتع بالعمرة إلى ࡰلحج فما ࡰستيسر من ࡰلهدي࣌  فمن لم يجد فصيام ثلثة أيام فے ࡴلحج وسبعة ࡴذا رجعتم تلك عشرة كاملة࣌ ذلك لمن لم يكن ࡰهله حاضرے ࡴلمسجد ࡴلحرام࣌ واتقوا ࡲلله واعلموا أن ࡰلله شديد ࡲلعقاب࣌', NULL, 30, 'local:warsh-text.json'),
  ('warsh-2-196', 'warsh', 2, 196, 'ࡴ۬لْحَجُّ أَشْهُرࣱ مَّعْلُومَٰتࣱ࣌ فَمَن فَرَضَ فِيهِنَّ ࡰ۬لْحَجَّ فَلَا رَفَثَ وَلَا فُسُوقَ وَلَا جِدَالَ فِے ࡴ۬لْحَجِّ࣌ وَمَا تَفْعَلُواْ مِنْ خَيْرࣲ يَعْلَمْهُ ࡲ۬للَّهُ࣌ وَتَزَوَّدُواْ࣌ فَإِنَّ خَيْرَ ࡰ۬لزَّادِ ࡴ۬لتَّقْوٜىٰ࣌ وَاتَّقُونِ يَٰٓأُوْلِے ࡴ۬لَالْبَٰبِ࣌', 'ࡴلحج أشهر معلومت࣌ فمن فرض فيهن ࡰلحج فلا رفث ولا فسوق ولا جدال فے ࡴلحج࣌ وما تفعلوا من خير يعلمه ࡲلله࣌ وتزودوا࣌ فإن خير ࡰلزاد ࡴلتقوى࣌ واتقون يأولے ࡴلالبب࣌', NULL, 31, 'local:warsh-text.json'),
  ('warsh-2-197', 'warsh', 2, 197, 'لَيْسَ عَلَيْكُمْ جُنَاحٌ ࡰن تَبْتَغُواْ فَضْلاࣰ مِّن رَّبِّكُمْ࣌ فَإِذَآ أَفَضْتُم مِّنْ عَرَفَٰتࣲ فَاذْكُرُواْ ࡲ۬للَّهَ عِندَ ࡰ۬لْمَشْعَرِ ࡴ۬لْحَرَامِ࣌ وَاذْكُرُوهُ كَمَا هَدٜيٰكُمْ وَإِن كُنتُم مِّن قَبْلِهِۦ لَمِنَ ࡰ۬لضَّآلِّينَ࣌', 'ليس عليكم جناح ࡰن تبتغوا فضلا من ربكم࣌ فإذا أفضتم من عرفت فاذكروا ࡲلله عند ࡰلمشعر ࡴلحرام࣌ واذكروه كما هديكم وإن كنتم من قبله لمن ࡰلضالين࣌', NULL, 31, 'local:warsh-text.json'),
  ('warsh-2-198', 'warsh', 2, 198, 'ثُمَّ أَفِيضُواْ مِنْ حَيْثُ أَفَاضَ ࡰ۬لنَّاسُ࣌ وَاسْتَغْفِرُواْ ࡲ۬للَّهَ࣌ إِنَّ ࡰ۬للَّهَ غَفُورࣱ رَّحِيمࣱ࣌', 'ثم أفيضوا من حيث أفاض ࡰلناس࣌ واستغفروا ࡲلله࣌ إن ࡰلله غفور رحيم࣌', NULL, 31, 'local:warsh-text.json'),
  ('warsh-2-199', 'warsh', 2, 199, 'فَإِذَا قَضَيْتُم مَّنَٰسِكَكُمْ فَاذْكُرُواْ ࡲ۬للَّهَ كَذِكْرِكُمُۥٓ ءَابَآءَكُمُۥٓ أَوَ ࡰشَدَّ ذِكْراࣰ࣌ فَمِنَ ࡰ۬لنَّاسِ مَنْ يَّقُولُ رَبَّنَآ ءَاتِنَا فِے ࡴ۬لدُّنْيٜا وَمَا لَهُۥ فِے ࡴ۬لَاخِرَةِ مِنْ خَلَٰقࣲ࣌ وَمِنْهُم مَّنْ يَّقُولُ رَبَّنَآ ءَاتِنَا فِے ࡴ۬لدُّنْيٜا حَسَنَةࣰ وَفِے ࡴ۬لَاخِرَةِ حَسَنَةࣰ وَقِنَا عَذَابَ ࡰ۬لنّٜارِ࣌', 'فإذا قضيتم منسككم فاذكروا ࡲلله كذكركم ءاباءكم أو ࡰشد ذكرا࣌ فمن ࡰلناس من يقول ربنا ءاتنا فے ࡴلدنيا وما له فے ࡴلاخرة من خلق࣌ ومنهم من يقول ربنا ءاتنا فے ࡴلدنيا حسنة وفے ࡴلاخرة حسنة وقنا عذاب ࡰلنار࣌', NULL, 31, 'local:warsh-text.json'),
  ('warsh-2-200', 'warsh', 2, 200, 'أُوْلَٰٓئِكَ لَهُمْ نَصِيبࣱ مِّمَّا كَسَبُواْ࣌ وَاللَّهُ سَرِيعُ ࡲ۬لْحِسَابِ࣌', 'أولئك لهم نصيب مما كسبوا࣌ والله سريع ࡲلحساب࣌', NULL, 31, 'local:warsh-text.json'),
  ('warsh-2-201', 'warsh', 2, 201, '۞ وَاذْكُرُواْ ࡲ۬للَّهَ فِےٓ أَيَّامࣲ مَّعْدُودَٰتࣲ࣌ فَمَن تَعَجَّلَ فِے يَوْمَيْنِ فَلَآ إِثْمَ عَلَيْهِ࣌ وَمَن تَأَخَّرَ فَلَآ إِثْمَ عَلَيْهِ لِمَنِ ࡴٜتَّقٜىٰ࣌ وَاتَّقُواْ ࡲ۬للَّهَ وَاعْلَمُوٓاْ أَنَّكُمُۥٓ إِلَيْهِ تُحْشَرُونَ࣌', 'واذكروا ࡲلله فے أيام معدودت࣌ فمن تعجل فے يومين فلا إثم عليه࣌ ومن تأخر فلا إثم عليه لمن ࡴتقى࣌ واتقوا ࡲلله واعلموا أنكم إليه تحشرون࣌', NULL, 32, 'local:warsh-text.json'),
  ('warsh-2-202', 'warsh', 2, 202, 'وَمِنَ ࡰ۬لنَّاسِ مَنْ يُّعْجِبُكَ قَوْلُهُۥ فِے ࡴ۬لْحَيَوٰةِ ࡴ۬لدُّنْيٜا وَيُشْهِدُ ࡲ۬للَّهَ عَلَىٰ مَا فِے قَلْبِهِۦ وَهُوَ أَلَدُّ ࡲ۬لْخِصَامِ࣌', 'ومن ࡰلناس من يعجبك قوله فے ࡴلحيوة ࡴلدنيا ويشهد ࡲلله على ما فے قلبه وهو ألد ࡲلخصام࣌', NULL, 32, 'local:warsh-text.json'),
  ('warsh-2-203', 'warsh', 2, 203, 'وَإِذَا تَوَلّٜىٰ سَعٜىٰ فِے ࡴ۬لَارْضِ لِيُفْسِدَ فِيهَا وَيُهْلِكَ ࡰ۬لْحَرْثَ وَالنَّسْلَ࣌ وَاللَّهُ لَا يُحِبُّ ࡲ۬لْفَسَادَ࣌', 'وإذا تولى سعى فے ࡴلارض ليفسد فيها ويهلك ࡰلحرث والنسل࣌ والله لا يحب ࡲلفساد࣌', NULL, 32, 'local:warsh-text.json'),
  ('warsh-2-204', 'warsh', 2, 204, 'وَإِذَا قِيلَ لَهُ ࡲٜتَّقِ ࡴ۬للَّهَ أَخَذَتْهُ ࡲ۬لْعِزَّةُ بِالِاثْمِ فَحَسْبُهُۥ جَهَنَّمُ࣌ وَلَبِيسَ ࡰ۬لْمِهَادُ࣌', 'وإذا قيل له ࡲتق ࡴلله أخذته ࡲلعزة بالاثم فحسبه جهنم࣌ ولبيس ࡰلمهاد࣌', NULL, 32, 'local:warsh-text.json'),
  ('warsh-2-205', 'warsh', 2, 205, 'وَمِنَ ࡰ۬لنَّاسِ مَنْ يَّشْرِے نَفْسَهُ ࡲٜبْتِغَآءَ مَرْضَاتِ ࡴ۬للَّهِ࣌ وَاللَّهُ رَءُوفُۢ بِالْعِبَادِ࣌', 'ومن ࡰلناس من يشرے نفسه ࡲبتغاء مرضات ࡴلله࣌ والله رءوف بالعباد࣌', NULL, 32, 'local:warsh-text.json'),
  ('warsh-2-206', 'warsh', 2, 206, 'يَٰٓأَيُّهَا ࡰ۬لذِينَ ءَامَنُواْ ࡲ࢈دْخُلُواْ فِے ࡴ۬لسَّلْمِ كَآفَّةࣰ࣌ وَلَا تَتَّبِعُواْ خُطْوَٰتِ ࡴ۬لشَّيْطَٰنِ࣌ إِنَّهُۥ لَكُمْ عَدُوࣱّ مُّبِينࣱ࣌', 'يأيها ࡰلذين ءامنوا ࡲ࢈دخلوا فے ࡴلسلم كافة࣌ ولا تتبعوا خطوت ࡴلشيطن࣌ إنه لكم عدو مبين࣌', NULL, 32, 'local:warsh-text.json'),
  ('warsh-2-207', 'warsh', 2, 207, 'فَإِن زَلَلْتُم مِّنۢ بَعْدِ مَا جَآءَتْكُمُ ࡲ۬لْبَيِّنَٰتُ فَاعْلَمُوٓاْ أَنَّ ࡰ۬للَّهَ عَزِيزٌ حَكِيمٌ࣌', 'فإن زللتم من بعد ما جاءتكم ࡲلبينت فاعلموا أن ࡰلله عزيز حكيم࣌', NULL, 32, 'local:warsh-text.json'),
  ('warsh-2-208', 'warsh', 2, 208, 'هَلْ يَنظُرُونَ إِلَّآ أَنْ يَّاتِيَهُمُ ࡲ۬للَّهُ فِے ظُلَلࣲ مِّنَ ࡰ۬لْغَمَٰمِ࣌ وَالْمَلَٰٓئِكَةُ وَقُضِيَ ࡰ۬لَامْرُ࣌ وَإِلَى ࡰ۬للَّهِ تُرْجَعُ ࡲ۬لُامُورُ࣌', 'هل ينظرون إلا أن ياتيهم ࡲلله فے ظلل من ࡰلغمم࣌ والملئكة وقضي ࡰلامر࣌ وإلى ࡰلله ترجع ࡲلامور࣌', NULL, 32, 'local:warsh-text.json'),
  ('warsh-2-209', 'warsh', 2, 209, 'سَلْ بَنِےٓ إِسْرَآءِيلَ كَمَ اٰتَيْنَٰهُم مِّنَ اٰيَةِۢ بَيِّنَةࣲ࣌ وَمَنْ يُّبَدِّلْ نِعْمَةَ ࡰ۬للَّهِ مِنۢ بَعْدِ مَا جَآءَتْهُ فَإِنَّ ࡰ۬للَّهَ شَدِيدُ ࡲ۬لْعِقَابِ࣌', 'سل بنے إسراءيل كم اتينهم من اية بينة࣌ ومن يبدل نعمة ࡰلله من بعد ما جاءته فإن ࡰلله شديد ࡲلعقاب࣌', NULL, 33, 'local:warsh-text.json'),
  ('warsh-2-210', 'warsh', 2, 210, 'زُيِّنَ لِلذِينَ كَفَرُواْ ࡲ۬لْحَيَوٰةُ ࡲ۬لدُّنْيٜا وَيَسْخَرُونَ مِنَ ࡰ۬لذِينَ ءَامَنُواْ࣌ وَالذِينَ ࡰٜتَّقَوْاْ فَوْقَهُمْ يَوْمَ ࡰ۬لْقِيَٰمَةِ࣌ وَاللَّهُ يَرْزُقُ مَنْ يَّشَآءُ بِغَيْرِ حِسَابࣲ࣌', 'زين للذين كفروا ࡲلحيوة ࡲلدنيا ويسخرون من ࡰلذين ءامنوا࣌ والذين ࡰتقوا فوقهم يوم ࡰلقيمة࣌ والله يرزق من يشاء بغير حساب࣌', NULL, 33, 'local:warsh-text.json'),
  ('warsh-2-211', 'warsh', 2, 211, '۞ كَانَ ࡰ۬لنَّاسُ أُمَّةࣰ وَٰحِدَةࣰ فَبَعَثَ ࡰ۬للَّهُ ࡲ۬لنَّبِيٓـِٕۑنَ مُبَشِّرِينَ وَمُنذِرِينَ وَأَنزَلَ مَعَهُمُ ࡲ۬لْكِتَٰبَ بِالْحَقِّ لِيَحْكُمَ بَيْنَ ࡰ۬لنَّاسِ فِيمَا ࡰٜخْتَلَفُواْ فِيهِ࣌ وَمَا ࡰٜخْتَلَفَ فِيهِ إِلَّا ࡰ۬لذِينَ أُوتُوهُ࣌ مِنۢ بَعْدِ مَا جَآءَتْهُمُ ࡲ۬لْبَيِّنَٰتُ بَغْياَۢ بَيْنَهُمْ࣌ فَهَدَى ࡰ۬للَّهُ ࡲ۬لذِينَ ءَامَنُواْ لِمَا ࡰٜخْتَلَفُواْ فِيهِ مِنَ ࡰ۬لْحَقِّ بِإِذْنِهِۦ࣌ وَاللَّهُ يَهْدِے مَنْ يَّشَآءُ ࡹِلَىٰ صِرَٰطࣲ مُّسْتَقِيمٍ࣌', 'كان ࡰلناس أمة وحدة فبعث ࡰلله ࡲلنبيۑن مبشرين ومنذرين وأنزل معهم ࡲلكتب بالحق ليحكم بين ࡰلناس فيما ࡰختلفوا فيه࣌ وما ࡰختلف فيه إلا ࡰلذين أوتوه࣌ من بعد ما جاءتهم ࡲلبينت بغيا بينهم࣌ فهدى ࡰلله ࡲلذين ءامنوا لما ࡰختلفوا فيه من ࡰلحق بإذنه࣌ والله يهدے من يشاء ࡹلى صرط مستقيم࣌', NULL, 33, 'local:warsh-text.json'),
  ('warsh-2-212', 'warsh', 2, 212, 'ࡰمْ حَسِبْتُمُۥٓ أَن تَدْخُلُواْ ࡲ۬لْجَنَّةَ وَلَمَّا يَاتِكُم مَّثَلُ ࡲ۬لذِينَ خَلَوْاْ مِن قَبْلِكُم مَّسَّتْهُمُ ࡲ۬لْبَأْسَآءُ وَالضَّرَّآءُ وَزُلْزِلُواْ حَتَّىٰ يَقُولُ ࡲ۬لرَّسُولُ وَالذِينَ ءَامَنُواْ مَعَهُۥ مَتٜىٰ نَصْرُ ࡲ۬للَّهِ࣌ أَلَآ إِنَّ نَصْرَ ࡰ۬للَّهِ قَرِيبࣱ࣌', 'ࡰم حسبتم أن تدخلوا ࡲلجنة ولما ياتكم مثل ࡲلذين خلوا من قبلكم مستهم ࡲلبأساء والضراء وزلزلوا حتى يقول ࡲلرسول والذين ءامنوا معه متى نصر ࡲلله࣌ ألا إن نصر ࡰلله قريب࣌', NULL, 33, 'local:warsh-text.json'),
  ('warsh-2-213', 'warsh', 2, 213, 'يَسْـَٔلُونَكَ مَاذَا يُنفِقُونَ࣌ قُلْ مَآ أَنفَقْتُم مِّنْ خَيْرࣲ فَلِلْوَٰلِدَيْنِ وَالَاقْرَبِينَ وَالْيَتَٰمٜىٰ وَالْمَسَٰكِينِ وَابْنِ ࡴ۬لسَّبِيلِ࣌ وَمَا تَفْعَلُواْ مِنْ خَيْرࣲ فَإِنَّ ࡰ۬للَّهَ بِهِۦ عَلِيمࣱ࣌', 'يسلونك ماذا ينفقون࣌ قل ما أنفقتم من خير فللولدين والاقربين واليتمى والمسكين وابن ࡴلسبيل࣌ وما تفعلوا من خير فإن ࡰلله به عليم࣌', NULL, 33, 'local:warsh-text.json'),
  ('warsh-2-214', 'warsh', 2, 214, 'كُتِبَ عَلَيْكُمُ ࡲ۬لْقِتَالُ وَهُوَ كُرْهࣱ لَّكُمْ࣌ وَعَسٜىٰٓ أَن تَكْرَهُواْ شَيْـٔاࣰ وَهُوَ خَيْرࣱ لَّكُمْ࣌ وَعَسٜىٰٓ أَن تُحِبُّواْ شَيْـٔاࣰ وَهُوَ شَرࣱّ لَّكُمْ࣌ وَاللَّهُ يَعْلَمُ࣌ وَأَنتُمْ لَا تَعْلَمُونَ࣌', 'كتب عليكم ࡲلقتال وهو كره لكم࣌ وعسى أن تكرهوا شيا وهو خير لكم࣌ وعسى أن تحبوا شيا وهو شر لكم࣌ والله يعلم࣌ وأنتم لا تعلمون࣌', NULL, 34, 'local:warsh-text.json'),
  ('warsh-2-215', 'warsh', 2, 215, 'يَسْـَٔلُونَكَ عَنِ ࡴ۬لشَّهْرِ ࡴ۬لْحَرَامِ قِتَالࣲ فِيهِ࣌ قُلْ قِتَالࣱ فِيهِ كَبِيرࣱ࣌ وَصَدٌّ عَن سَبِيلِ ࡴ۬للَّهِ وَكُفْرُۢ بِهِۦ وَالْمَسْجِدِ ࡴ۬لْحَرَامِ وَإِخْرَاجُ أَهْلِهِۦ مِنْهُ أَكْبَرُ عِندَ ࡰ۬للَّهِ࣌ وَالْفِتْنَةُ أَكْبَرُ مِنَ ࡰ۬لْقَتْلِ࣌ وَلَا يَزَالُونَ يُقَٰتِلُونَكُمْ حَتَّىٰ يَرُدُّوكُمْ عَن دِينِكُمُۥٓ إِنِ ࡴٜسْتَطَٰعُواْ࣌ وَمَنْ يَّرْتَدِدْ مِنكُمْ عَن دِينِهِۦ فَيَمُتْ وَهُوَ كَافِرࣱ فَأُوْلَٰٓئِكَ حَبِطَتَ ࡰعْمَٰلُهُمْ فِے ࡴ۬لدُّنْيٜا وَالَاخِرَةِ࣌ وَأُوْلَٰٓئِكَ أَصْحَٰبُ ࡲ۬لنّٜارِ هُمْ فِيهَا خَٰلِدُونَ࣌', 'يسلونك عن ࡴلشهر ࡴلحرام قتال فيه࣌ قل قتال فيه كبير࣌ وصد عن سبيل ࡴلله وكفر به والمسجد ࡴلحرام وإخراج أهله منه أكبر عند ࡰلله࣌ والفتنة أكبر من ࡰلقتل࣌ ولا يزالون يقتلونكم حتى يردوكم عن دينكم إن ࡴستطعوا࣌ ومن يرتدد منكم عن دينه فيمت وهو كافر فأولئك حبطت ࡰعملهم فے ࡴلدنيا والاخرة࣌ وأولئك أصحب ࡲلنار هم فيها خلدون࣌', NULL, 34, 'local:warsh-text.json'),
  ('warsh-2-216', 'warsh', 2, 216, 'إِنَّ ࡰ۬لذِينَ ءَامَنُواْ وَالذِينَ هَاجَرُواْ وَجَٰهَدُواْ فِے سَبِيلِ ࡴ۬للَّهِ أُوْلَٰٓئِكَ يَرْجُونَ رَحْمَتَ ࡰ۬للَّهِ࣌ وَاللَّهُ غَفُورࣱ رَّحِيمࣱ࣌', 'إن ࡰلذين ءامنوا والذين هاجروا وجهدوا فے سبيل ࡴلله أولئك يرجون رحمت ࡰلله࣌ والله غفور رحيم࣌', NULL, 34, 'local:warsh-text.json'),
  ('warsh-2-217', 'warsh', 2, 217, '۞ يَسْـَٔلُونَكَ عَنِ ࡴ۬لْخَمْرِ وَالْمَيْسِرِ࣌ قُلْ فِيهِمَآ إِثْمࣱ كَبِيرࣱ وَمَنَٰفِعُ لِلنَّاسِ࣌ وَإِثْمُهُمَآ أَكْبَرُ مِن نَّفْعِهِمَا࣌ وَيَسْـَٔلُونَكَ مَاذَا يُنفِقُونَ قُلِ ࡴ۬لْعَفْوَ࣌ كَذَٰلِكَ يُبَيِّنُ ࡲ۬للَّهُ لَكُمُ ࡲ۬لَايَٰتِ لَعَلَّكُمْ تَتَفَكَّرُونَ', 'يسلونك عن ࡴلخمر والميسر࣌ قل فيهما إثم كبير ومنفع للناس࣌ وإثمهما أكبر من نفعهما࣌ ويسلونك ماذا ينفقون قل ࡴلعفو࣌ كذلك يبين ࡲلله لكم ࡲلايت لعلكم تتفكرون', NULL, 34, 'local:warsh-text.json'),
  ('warsh-2-218', 'warsh', 2, 218, 'فِے ࡴ۬لدُّنْيٜا وَالَاخِرَةِ࣌ وَيَسْـَٔلُونَكَ عَنِ ࡴ۬لْيَتَٰمٜىٰ قُلِ ࡴصْلَٰحࣱ لَّهُمْ خَيْرࣱ࣌ وَإِن تُخَالِطُوهُمْ فَإِخْوَٰنُكُمْ࣌ وَاللَّهُ يَعْلَمُ ࡲ۬لْمُفْسِدَ مِنَ ࡰ۬لْمُصْلِحِ࣌ وَلَوْ شَآءَ ࡰ۬للَّهُ لَأَعْنَتَكُمُۥٓ࣌ إِنَّ ࡰ۬للَّهَ عَزِيزٌ حَكِيمࣱ࣌', 'فے ࡴلدنيا والاخرة࣌ ويسلونك عن ࡴليتمى قل ࡴصلح لهم خير࣌ وإن تخالطوهم فإخونكم࣌ والله يعلم ࡲلمفسد من ࡰلمصلح࣌ ولو شاء ࡰلله لأعنتكم࣌ إن ࡰلله عزيز حكيم࣌', NULL, 35, 'local:warsh-text.json'),
  ('warsh-2-219', 'warsh', 2, 219, 'وَلَا تَنكِحُواْ ࡲ۬لْمُشْرِكَٰتِ حَتَّىٰ يُومِنَّ࣌ وَلَأَمَةࣱ مُّومِنَةٌ خَيْرࣱ مِّن مُّشْرِكَةࣲ وَلَوَ ࡰعْجَبَتْكُمْ࣌ وَلَا تُنكِحُواْ ࡲ۬لْمُشْرِكِينَ حَتَّىٰ يُومِنُواْ࣌ وَلَعَبْدࣱ مُّومِنٌ خَيْرࣱ مِّن مُّشْرِكࣲ وَلَوَ ࡰعْجَبَكُمُۥٓ࣌ أُوْلَٰٓئِكَ يَدْعُونَ إِلَى ࡰ۬لنّٜارِ࣌ وَاللَّهُ يَدْعُوٓاْ إِلَى ࡰ۬لْجَنَّةِ وَالْمَغْفِرَةِ بِإِذْنِهِۦ࣌ وَيُبَيِّنُ ءَايَٰتِهِۦ لِلنَّاسِ لَعَلَّهُمْ يَتَذَكَّرُونَ࣌', 'ولا تنكحوا ࡲلمشركت حتى يومن࣌ ولأمة مومنة خير من مشركة ولو ࡰعجبتكم࣌ ولا تنكحوا ࡲلمشركين حتى يومنوا࣌ ولعبد مومن خير من مشرك ولو ࡰعجبكم࣌ أولئك يدعون إلى ࡰلنار࣌ والله يدعوا إلى ࡰلجنة والمغفرة بإذنه࣌ ويبين ءايته للناس لعلهم يتذكرون࣌', NULL, 35, 'local:warsh-text.json'),
  ('warsh-2-220', 'warsh', 2, 220, 'وَيَسْـَٔلُونَكَ عَنِ ࡴ۬لْمَحِيضِ قُلْ هُوَ أَذىࣰ࣌ فَاعْتَزِلُواْ ࡲ۬لنِّسَآءَ فِے ࡴ۬لْمَحِيضِ࣌ وَلَا تَقْرَبُوهُنَّ حَتَّىٰ يَطْهُرْنَ࣌ فَإِذَا تَطَهَّرْنَ فَاتُوهُنَّ مِنْ حَيْثُ أَمَرَكُمُ ࡲ۬للَّهُ࣌ إِنَّ ࡰ۬للَّهَ يُحِبُّ ࡲ۬لتَّوَّٰبِينَ وَيُحِبُّ ࡲ۬لْمُتَطَهِّرِينَ࣌', 'ويسلونك عن ࡴلمحيض قل هو أذى࣌ فاعتزلوا ࡲلنساء فے ࡴلمحيض࣌ ولا تقربوهن حتى يطهرن࣌ فإذا تطهرن فاتوهن من حيث أمركم ࡲلله࣌ إن ࡰلله يحب ࡲلتوبين ويحب ࡲلمتطهرين࣌', NULL, 35, 'local:warsh-text.json'),
  ('warsh-2-221', 'warsh', 2, 221, 'نِسَآؤُكُمْ حَرْثࣱ لَّكُمْ فَاتُواْ حَرْثَكُمُۥٓ أَنّٜىٰ شِئْتُمْ࣌ وَقَدِّمُواْ لِأَنفُسِكُمْ࣌ وَاتَّقُواْ ࡲ۬للَّهَ࣌ وَاعْلَمُوٓاْ أَنَّكُم مُّلَٰقُوهُ࣌ وَبَشِّرِ ࡴ۬لْمُومِنِينَ࣌', 'نساؤكم حرث لكم فاتوا حرثكم أنى شئتم࣌ وقدموا لأنفسكم࣌ واتقوا ࡲلله࣌ واعلموا أنكم ملقوه࣌ وبشر ࡴلمومنين࣌', NULL, 35, 'local:warsh-text.json'),
  ('warsh-2-222', 'warsh', 2, 222, 'وَلَا تَجْعَلُواْ ࡲ۬للَّهَ عُرْضَةࣰ لِّأَيْمَٰنِكُمُۥٓ࣌ أَن تَبَرُّواْ وَتَتَّقُواْ وَتُصْلِحُواْ بَيْنَ ࡰ۬لنَّاسِ࣌ وَاللَّهُ سَمِيعٌ عَلِيمࣱ࣌', 'ولا تجعلوا ࡲلله عرضة لأيمنكم࣌ أن تبروا وتتقوا وتصلحوا بين ࡰلناس࣌ والله سميع عليم࣌', NULL, 35, 'local:warsh-text.json'),
  ('warsh-2-223', 'warsh', 2, 223, 'لَّا يُوَ۬اخِذُكُمُ ࡲ۬للَّهُ بِاللَّغْوِ فِےٓ أَيْمَٰنِكُمْ࣌ وَلَٰكِنْ يُّوَ۬اخِذُكُم بِمَا كَسَبَتْ قُلُوبُكُمْ࣌ وَاللَّهُ غَفُورٌ حَلِيمࣱ࣌', 'لا يواخذكم ࡲلله باللغو فے أيمنكم࣌ ولكن يواخذكم بما كسبت قلوبكم࣌ والله غفور حليم࣌', NULL, 36, 'local:warsh-text.json'),
  ('warsh-2-224', 'warsh', 2, 224, 'لِّلذِينَ يُولُونَ مِن نِّسَآئِهِمْ تَرَبُّصُ أَرْبَعَةِ أَشْهُرࣲ࣌ فَإِن فَآءُو فَإِنَّ ࡰ۬للَّهَ غَفُورࣱ رَّحِيمࣱ࣌', 'للذين يولون من نسائهم تربص أربعة أشهر࣌ فإن فاءو فإن ࡰلله غفور رحيم࣌', NULL, 36, 'local:warsh-text.json'),
  ('warsh-2-225', 'warsh', 2, 225, 'وَإِنْ عَزَمُواْ ࡲ۬لطَّلَٰقَ فَإِنَّ ࡰ۬للَّهَ سَمِيعٌ عَلِيمࣱ࣌', 'وإن عزموا ࡲلطلق فإن ࡰلله سميع عليم࣌', NULL, 36, 'local:warsh-text.json'),
  ('warsh-2-226', 'warsh', 2, 226, '۞ وَالْمُطَلَّقَٰتُ يَتَرَبَّصْنَ بِأَنفُسِهِنَّ ثَلَٰثَةَ قُرُوٓءࣲ࣌ وَلَا يَحِلُّ لَهُنَّ أَنْ يَّكْتُمْنَ مَا خَلَقَ ࡰ۬للَّهُ فِےٓ أَرْحَامِهِنَّ إِن كُنَّ يُومِنَّ بِاللَّهِ وَالْيَوْمِ ࡴ۬لَاخِرِ࣌ وَبُعُولَتُهُنَّ أَحَقُّ بِرَدِّهِنَّ فِے ذَٰلِكَ إِنَ ࡰرَادُوٓاْ إِصْلَٰحاࣰ࣌ وَلَهُنَّ مِثْلُ ࡲ۬لذِے عَلَيْهِنَّ بِالْمَعْرُوفِ࣌ وَلِلرِّجَالِ عَلَيْهِنَّ دَرَجَةࣱ࣌ وَاللَّهُ عَزِيزٌ حَكِيمٌ࣌', 'والمطلقت يتربصن بأنفسهن ثلثة قروء࣌ ولا يحل لهن أن يكتمن ما خلق ࡰلله فے أرحامهن إن كن يومن بالله واليوم ࡴلاخر࣌ وبعولتهن أحق بردهن فے ذلك إن ࡰرادوا إصلحا࣌ ولهن مثل ࡲلذے عليهن بالمعروف࣌ وللرجال عليهن درجة࣌ والله عزيز حكيم࣌', NULL, 36, 'local:warsh-text.json'),
  ('warsh-2-227', 'warsh', 2, 227, 'ࡴ۬لطَّلَٰقُ مَرَّتَٰنِ࣌ فَإِمْسَاكُۢ بِمَعْرُوفٍ ࡰوْ تَسْرِيحُۢ بِإِحْسَٰنࣲ࣌ وَلَا يَحِلُّ لَكُمُۥٓ أَن تَاخُذُواْ مِمَّآ ءَاتَيْتُمُوهُنَّ شَيْـٔاً ࡴلَّآ أَنْ يَّخَافَآ أَلَّا يُقِيمَا حُدُودَ ࡰ۬للَّهِ࣌ فَإِنْ خِفْتُمُۥٓ أَلَّا يُقِيمَا حُدُودَ ࡰ۬للَّهِ فَلَا جُنَاحَ عَلَيْهِمَا فِيمَا ࡰٜفْتَدَتْ بِهِۦ࣌ تِلْكَ حُدُودُ ࡲ۬للَّهِ࣌ فَلَا تَعْتَدُوهَا࣌ وَمَنْ يَّتَعَدَّ حُدُودَ ࡰ۬للَّهِ فَأُوْلَٰٓئِكَ هُمُ ࡲ۬لظَّٰلِمُونَ࣌', 'ࡴلطلق مرتن࣌ فإمساك بمعروف ࡰو تسريح بإحسن࣌ ولا يحل لكم أن تاخذوا مما ءاتيتموهن شيا ࡴلا أن يخافا ألا يقيما حدود ࡰلله࣌ فإن خفتم ألا يقيما حدود ࡰلله فلا جناح عليهما فيما ࡰفتدت به࣌ تلك حدود ࡲلله࣌ فلا تعتدوها࣌ ومن يتعد حدود ࡰلله فأولئك هم ࡲلظلمون࣌', NULL, 36, 'local:warsh-text.json'),
  ('warsh-2-228', 'warsh', 2, 228, 'فَإِن طَلَّقَهَا فَلَا تَحِلُّ لَهُۥ مِنۢ بَعْدُ حَتَّىٰ تَنكِحَ زَوْجاً غَيْرَهُۥ࣌ فَإِن طَلَّقَهَا فَلَا جُنَاحَ عَلَيْهِمَآ أَنْ يَّتَرَاجَعَآ إِن ظَنَّآ أَنْ يُّقِيمَا حُدُودَ ࡰ۬للَّهِ࣌ وَتِلْكَ حُدُودُ ࡲ۬للَّهِ يُبَيِّنُهَا لِقَوْمࣲ يَعْلَمُونَ࣌', 'فإن طلقها فلا تحل له من بعد حتى تنكح زوجا غيره࣌ فإن طلقها فلا جناح عليهما أن يتراجعا إن ظنا أن يقيما حدود ࡰلله࣌ وتلك حدود ࡲلله يبينها لقوم يعلمون࣌', NULL, 36, 'local:warsh-text.json'),
  ('warsh-2-229', 'warsh', 2, 229, 'وَإِذَا طَلَّقْتُمُ ࡲ۬لنِّسَآءَ فَبَلَغْنَ أَجَلَهُنَّ فَأَمْسِكُوهُنَّ بِمَعْرُوفٍ ࡰوْ سَرِّحُوهُنَّ بِمَعْرُوفࣲ࣌ وَلَا تُمْسِكُوهُنَّ ضِرَاراࣰ لِّتَعْتَدُواْ࣌ وَمَنْ يَّفْعَلْ ذَٰلِكَ فَقَد ظَّلَمَ نَفْسَهُۥ࣌ وَلَا تَتَّخِذُوٓاْ ءَايَٰتِ ࡴ۬للَّهِ هُزُؤاࣰ࣌ وَاذْكُرُواْ نِعْمَتَ ࡰ۬للَّهِ عَلَيْكُمْ وَمَآ أَنزَلَ عَلَيْكُم مِّنَ ࡰ۬لْكِتَٰبِ وَالْحِكْمَةِ يَعِظُكُم بِهِۦ࣌ وَاتَّقُواْ ࡲ۬للَّهَ࣌ وَاعْلَمُوٓاْ أَنَّ ࡰ۬للَّهَ بِكُلِّ شَےْءٍ عَلِيمࣱ࣌', 'وإذا طلقتم ࡲلنساء فبلغن أجلهن فأمسكوهن بمعروف ࡰو سرحوهن بمعروف࣌ ولا تمسكوهن ضرارا لتعتدوا࣌ ومن يفعل ذلك فقد ظلم نفسه࣌ ولا تتخذوا ءايت ࡴلله هزؤا࣌ واذكروا نعمت ࡰلله عليكم وما أنزل عليكم من ࡰلكتب والحكمة يعظكم به࣌ واتقوا ࡲلله࣌ واعلموا أن ࡰلله بكل شےء عليم࣌', NULL, 37, 'local:warsh-text.json'),
  ('warsh-2-230', 'warsh', 2, 230, 'وَإِذَا طَلَّقْتُمُ ࡲ۬لنِّسَآءَ فَبَلَغْنَ أَجَلَهُنَّ فَلَا تَعْضُلُوهُنَّ أَنْ يَّنكِحْنَ أَزْوَٰجَهُنَّ إِذَا تَرَٰضَوْاْ بَيْنَهُم بِالْمَعْرُوفِ࣌ ذَٰلِكَ يُوعَظُ بِهِۦ مَن كَانَ مِنكُمْ يُومِنُ بِاللَّهِ وَالْيَوْمِ ࡴ۬لَاخِرِ࣌ ذَٰلِكُمُۥٓ أَزْكٜىٰ لَكُمْ وَأَطْهَرُ࣌ وَاللَّهُ يَعْلَمُ࣌ وَأَنتُمْ لَا تَعْلَمُونَ࣌', 'وإذا طلقتم ࡲلنساء فبلغن أجلهن فلا تعضلوهن أن ينكحن أزوجهن إذا ترضوا بينهم بالمعروف࣌ ذلك يوعظ به من كان منكم يومن بالله واليوم ࡴلاخر࣌ ذلكم أزكى لكم وأطهر࣌ والله يعلم࣌ وأنتم لا تعلمون࣌', NULL, 37, 'local:warsh-text.json'),
  ('warsh-2-231', 'warsh', 2, 231, '۞ وَالْوَٰلِدَٰتُ يُرْضِعْنَ أَوْلَٰدَهُنَّ حَوْلَيْنِ كَامِلَيْنِ࣌ لِمَنَ ࡰرَادَ أَنْ يُّتِمَّ ࡰ۬لرَّضَٰعَةَ࣌ وَعَلَى ࡰ۬لْمَوْلُودِ لَهُۥ رِزْقُهُنَّ وَكِسْوَتُهُنَّ بِالْمَعْرُوفِ࣌ لَا تُكَلَّفُ نَفْسٌ ࡴلَّا وُسْعَهَا࣌ لَا تُضَآرَّ وَٰلِدَةُۢ بِوَلَدِهَا وَلَا مَوْلُودࣱ لَّهُۥ بِوَلَدِهِۦ࣌ وَعَلَى ࡰ۬لْوَارِثِ مِثْلُ ذَٰلِكَ࣌ فَإِنَ ࡰرَادَا فِصَالاً عَن تَرَاضࣲ مِّنْهُمَا وَتَشَاوُرࣲ فَلَا جُنَاحَ عَلَيْهِمَا࣌ وَإِنَ ࡰرَدتُّمُۥٓ أَن تَسْتَرْضِعُوٓاْ أَوْلَٰدَكُمْ فَلَا جُنَاحَ عَلَيْكُمُۥٓ إِذَا سَلَّمْتُم مَّآ ءَاتَيْتُم بِالْمَعْرُوفِ࣌ وَاتَّقُواْ ࡲ۬للَّهَ࣌ وَاعْلَمُوٓاْ أَنَّ ࡰ۬للَّهَ بِمَا تَعْمَلُونَ بَصِيرࣱ࣌', 'والولدت يرضعن أولدهن حولين كاملين࣌ لمن ࡰراد أن يتم ࡰلرضعة࣌ وعلى ࡰلمولود له رزقهن وكسوتهن بالمعروف࣌ لا تكلف نفس ࡴلا وسعها࣌ لا تضار ولدة بولدها ولا مولود له بولده࣌ وعلى ࡰلوارث مثل ذلك࣌ فإن ࡰرادا فصالا عن تراض منهما وتشاور فلا جناح عليهما࣌ وإن ࡰردتم أن تسترضعوا أولدكم فلا جناح عليكم إذا سلمتم ما ءاتيتم بالمعروف࣌ واتقوا ࡲلله࣌ واعلموا أن ࡰلله بما تعملون بصير࣌', NULL, 37, 'local:warsh-text.json'),
  ('warsh-2-232', 'warsh', 2, 232, 'وَالذِينَ يُتَوَفَّوْنَ مِنكُمْ وَيَذَرُونَ أَزْوَٰجاࣰ يَتَرَبَّصْنَ بِأَنفُسِهِنَّ أَرْبَعَةَ أَشْهُرࣲ وَعَشْراࣰ࣌ فَإِذَا بَلَغْنَ أَجَلَهُنَّ فَلَا جُنَاحَ عَلَيْكُمْ فِيمَا فَعَلْنَ فِےٓ أَنفُسِهِنَّ بِالْمَعْرُوفِ࣌ وَاللَّهُ بِمَا تَعْمَلُونَ خَبِيرࣱ࣌', 'والذين يتوفون منكم ويذرون أزوجا يتربصن بأنفسهن أربعة أشهر وعشرا࣌ فإذا بلغن أجلهن فلا جناح عليكم فيما فعلن فے أنفسهن بالمعروف࣌ والله بما تعملون خبير࣌', NULL, 38, 'local:warsh-text.json'),
  ('warsh-2-233', 'warsh', 2, 233, 'وَلَا جُنَاحَ عَلَيْكُمْ فِيمَا عَرَّضْتُم بِهِۦ مِنْ خِطْبَةِ ࡴ۬لنِّسَآءِ ࡶَوَ ࡰكْنَنتُمْ فِےٓ أَنفُسِكُمْ࣌ عَلِمَ ࡰ۬للَّهُ أَنَّكُمْ سَتَذْكُرُونَهُنَّ وَلَٰكِن لَّا تُوَاعِدُوهُنَّ سِرّاً࣌ ࡴلَّآ أَن تَقُولُواْ قَوْلاࣰ مَّعْرُوفاࣰ࣌ ۞ وَلَا تَعْزِمُواْ عُقْدَةَ ࡰ۬لنِّكَاحِ حَتَّىٰ يَبْلُغَ ࡰ۬لْكِتَٰبُ أَجَلَهُۥ࣌ وَاعْلَمُوٓاْ أَنَّ ࡰ۬للَّهَ يَعْلَمُ مَا فِےٓ أَنفُسِكُمْ فَاحْذَرُوهُ࣌ وَاعْلَمُوٓاْ أَنَّ ࡰ۬للَّهَ غَفُورٌ حَلِيمࣱ࣌', 'ولا جناح عليكم فيما عرضتم به من خطبة ࡴلنساء ࡶو ࡰكننتم فے أنفسكم࣌ علم ࡰلله أنكم ستذكرونهن ولكن لا تواعدوهن سرا࣌ ࡴلا أن تقولوا قولا معروفا࣌  ولا تعزموا عقدة ࡰلنكاح حتى يبلغ ࡰلكتب أجله࣌ واعلموا أن ࡰلله يعلم ما فے أنفسكم فاحذروه࣌ واعلموا أن ࡰلله غفور حليم࣌', NULL, 38, 'local:warsh-text.json'),
  ('warsh-2-234', 'warsh', 2, 234, 'لَّا جُنَاحَ عَلَيْكُمُۥٓ إِن طَلَّقْتُمُ ࡲ۬لنِّسَآءَ مَا لَمْ تَمَسُّوهُنَّ أَوْ تَفْرِضُواْ لَهُنَّ فَرِيضَةࣰ࣌ وَمَتِّعُوهُنَّ عَلَى ࡰ۬لْمُوسِعِ قَدْرُهُۥ وَعَلَى ࡰ۬لْمُقْتِرِ قَدْرُهُۥ مَتَٰعاَۢ بِالْمَعْرُوفِ࣌ حَقّاً عَلَى ࡰ۬لْمُحْسِنِينَ࣌', 'لا جناح عليكم إن طلقتم ࡲلنساء ما لم تمسوهن أو تفرضوا لهن فريضة࣌ ومتعوهن على ࡰلموسع قدره وعلى ࡰلمقتر قدره متعا بالمعروف࣌ حقا على ࡰلمحسنين࣌', NULL, 38, 'local:warsh-text.json'),
  ('warsh-2-235', 'warsh', 2, 235, 'وَإِن طَلَّقْتُمُوهُنَّ مِن قَبْلِ أَن تَمَسُّوهُنَّ وَقَدْ فَرَضْتُمْ لَهُنَّ فَرِيضَةࣰ فَنِصْفُ مَا فَرَضْتُمُۥٓ إِلَّآ أَنْ يَّعْفُونَ أَوْ يَعْفُوَاْ ࡰ۬لذِے بِيَدِهِۦ عُقْدَةُ ࡲ۬لنِّكَاحِ࣌ وَأَن تَعْفُوٓاْ أَقْرَبُ لِلتَّقْوٜىٰ࣌ وَلَا تَنسَوُاْ ࡲ۬لْفَضْلَ بَيْنَكُمُۥٓ࣌ إِنَّ ࡰ۬للَّهَ بِمَا تَعْمَلُونَ بَصِيرٌ࣌', 'وإن طلقتموهن من قبل أن تمسوهن وقد فرضتم لهن فريضة فنصف ما فرضتم إلا أن يعفون أو يعفوا ࡰلذے بيده عقدة ࡲلنكاح࣌ وأن تعفوا أقرب للتقوى࣌ ولا تنسوا ࡲلفضل بينكم࣌ إن ࡰلله بما تعملون بصير࣌', NULL, 38, 'local:warsh-text.json'),
  ('warsh-2-236', 'warsh', 2, 236, 'حَٰفِظُواْ عَلَى ࡰ۬لصَّلَوَٰتِ وَالصَّلَوٰةِ ࡴ۬لْوُسْطٜىٰ وَقُومُواْ لِلهِ قَٰنِتِينَ࣌', 'حفظوا على ࡰلصلوت والصلوة ࡴلوسطى وقوموا لله قنتين࣌', NULL, 39, 'local:warsh-text.json'),
  ('warsh-2-237', 'warsh', 2, 237, 'فَإِنْ خِفْتُمْ فَرِجَالاً ࡰوْ رُكْبَاناࣰ࣌ فَإِذَآ أَمِنتُمْ فَاذْكُرُواْ ࡲ۬للَّهَ كَمَا عَلَّمَكُم مَّا لَمْ تَكُونُواْ تَعْلَمُونَ࣌', 'فإن خفتم فرجالا ࡰو ركبانا࣌ فإذا أمنتم فاذكروا ࡲلله كما علمكم ما لم تكونوا تعلمون࣌', NULL, 39, 'local:warsh-text.json'),
  ('warsh-2-238', 'warsh', 2, 238, 'وَالذِينَ يُتَوَفَّوْنَ مِنكُمْ وَيَذَرُونَ أَزْوَٰجاࣰ وَصِيَّةࣱ لِّأَزْوَٰجِهِم مَّتَٰعاً ࡴلَى ࡰ۬لْحَوْلِ غَيْرَ إِخْرَاجࣲ࣌ فَإِنْ خَرَجْنَ فَلَا جُنَاحَ عَلَيْكُمْ فِے مَا فَعَلْنَ فِےٓ أَنفُسِهِنَّ مِن مَّعْرُوفࣲ࣌ وَاللَّهُ عَزِيزٌ حَكِيمࣱ࣌', 'والذين يتوفون منكم ويذرون أزوجا وصية لأزوجهم متعا ࡴلى ࡰلحول غير إخراج࣌ فإن خرجن فلا جناح عليكم فے ما فعلن فے أنفسهن من معروف࣌ والله عزيز حكيم࣌', NULL, 39, 'local:warsh-text.json'),
  ('warsh-2-239', 'warsh', 2, 239, 'وَلِلْمُطَلَّقَٰتِ مَتَٰعُۢ بِالْمَعْرُوفِ࣌ حَقّاً عَلَى ࡰ۬لْمُتَّقِينَ࣌', 'وللمطلقت متع بالمعروف࣌ حقا على ࡰلمتقين࣌', NULL, 39, 'local:warsh-text.json'),
  ('warsh-2-240', 'warsh', 2, 240, 'كَذَٰلِكَ يُبَيِّنُ ࡲ۬للَّهُ لَكُمُۥٓ ءَايَٰتِهِۦ لَعَلَّكُمْ تَعْقِلُونَ࣌', 'كذلك يبين ࡲلله لكم ءايته لعلكم تعقلون࣌', NULL, 39, 'local:warsh-text.json'),
  ('warsh-2-241', 'warsh', 2, 241, '۞ أَلَمْ تَرَ إِلَى ࡰ۬لذِينَ خَرَجُواْ مِن دِيٜـٰرِهِمْ وَهُمُۥٓ أُلُوفٌ حَذَرَ ࡰ۬لْمَوْتِ فَقَالَ لَهُمُ ࡲ۬للَّهُ مُوتُواْ ثُمَّ أَحْيٜاهُمُۥٓ࣌ إِنَّ ࡰ۬للَّهَ لَذُو فَضْلٍ عَلَى ࡰ۬لنَّاسِ࣌ وَلَٰكِنَّ أَكْثَرَ ࡰ۬لنَّاسِ لَا يَشْكُرُونَ࣌', 'ألم تر إلى ࡰلذين خرجوا من ديرهم وهم ألوف حذر ࡰلموت فقال لهم ࡲلله موتوا ثم أحياهم࣌ إن ࡰلله لذو فضل على ࡰلناس࣌ ولكن أكثر ࡰلناس لا يشكرون࣌', NULL, 39, 'local:warsh-text.json'),
  ('warsh-2-242', 'warsh', 2, 242, 'وَقَٰتِلُواْ فِے سَبِيلِ ࡴ۬للَّهِ وَاعْلَمُوٓاْ أَنَّ ࡰ۬للَّهَ سَمِيعٌ عَلِيمࣱ࣌', 'وقتلوا فے سبيل ࡴلله واعلموا أن ࡰلله سميع عليم࣌', NULL, 39, 'local:warsh-text.json'),
  ('warsh-2-243', 'warsh', 2, 243, 'مَّن ذَا ࡰ۬لذِے يُقْرِضُ ࡲ۬للَّهَ قَرْضاً حَسَناࣰ فَيُضَٰعِفُهُۥ لَهُۥٓ أَضْعَافاࣰ كَثِيرَةࣰ࣌ وَاللَّهُ يَقْبِضُ وَيَبْصُطُ࣌ وَإِلَيْهِ تُرْجَعُونَ࣌', 'من ذا ࡰلذے يقرض ࡲلله قرضا حسنا فيضعفه له أضعافا كثيرة࣌ والله يقبض ويبصط࣌ وإليه ترجعون࣌', NULL, 39, 'local:warsh-text.json'),
  ('warsh-2-244', 'warsh', 2, 244, 'أَلَمْ تَرَ إِلَى ࡰ۬لْمَلَإِ مِنۢ بَنِےٓ إِسْرَآءِيلَ مِنۢ بَعْدِ مُوسٜىٰٓ إِذْ قَالُواْ لِنَبِےٓءࣲ لَّهُمُ ࡲٜبْعَثْ لَنَا مَلِكاࣰ نُّقَٰتِلْ فِے سَبِيلِ ࡴ۬للَّهِ࣌ قَالَ هَلْ عَسِيتُمُۥٓ إِن كُتِبَ عَلَيْكُمُ ࡲ۬لْقِتَالُ أَلَّا تُقَٰتِلُواْ࣌ قَالُواْ وَمَا لَنَآ أَلَّا نُقَٰتِلَ فِے سَبِيلِ ࡴ۬للَّهِ وَقَدُ ࡳخْرِجْنَا مِن دِيٜـٰرِنَا وَأَبْنَآئِنَا࣌ فَلَمَّا كُتِبَ عَلَيْهِمُ ࡲ۬لْقِتَالُ تَوَلَّوِاْ ࡴلَّا قَلِيلاࣰ مِّنْهُمْ࣌ وَاللَّهُ عَلِيمُۢ بِالظَّٰلِمِينَ࣌', 'ألم تر إلى ࡰلملإ من بنے إسراءيل من بعد موسى إذ قالوا لنبےء لهم ࡲبعث لنا ملكا نقتل فے سبيل ࡴلله࣌ قال هل عسيتم إن كتب عليكم ࡲلقتال ألا تقتلوا࣌ قالوا وما لنا ألا نقتل فے سبيل ࡴلله وقد ࡳخرجنا من ديرنا وأبنائنا࣌ فلما كتب عليهم ࡲلقتال تولوا ࡴلا قليلا منهم࣌ والله عليم بالظلمين࣌', NULL, 40, 'local:warsh-text.json'),
  ('warsh-2-245', 'warsh', 2, 245, 'وَقَالَ لَهُمْ نَبِيٓـُٔهُمُۥٓ إِنَّ ࡰ۬للَّهَ قَدْ بَعَثَ لَكُمْ طَالُوتَ مَلِكاࣰ࣌ قَالُوٓاْ أَنّٜىٰ يَكُونُ لَهُ ࡲ۬لْمُلْكُ عَلَيْنَا وَنَحْنُ أَحَقُّ بِالْمُلْكِ مِنْهُ وَلَمْ يُوتَ سَعَةࣰ مِّنَ ࡰ۬لْمَالِ࣌ قَالَ إِنَّ ࡰ۬للَّهَ ࡰٜصْطَفٜيٰهُ عَلَيْكُمْ وَزَادَهُۥ بَسْطَةࣰ فِے ࡴ۬لْعِلْمِ وَالْجِسْمِ࣌ وَاللَّهُ يُوتِے مُلْكَهُۥ مَنْ يَّشَآءُ࣌ وَاللَّهُ وَٰسِعٌ عَلِيمࣱ࣌', 'وقال لهم نبيهم إن ࡰلله قد بعث لكم طالوت ملكا࣌ قالوا أنى يكون له ࡲلملك علينا ونحن أحق بالملك منه ولم يوت سعة من ࡰلمال࣌ قال إن ࡰلله ࡰصطفيه عليكم وزاده بسطة فے ࡴلعلم والجسم࣌ والله يوتے ملكه من يشاء࣌ والله وسع عليم࣌', NULL, 40, 'local:warsh-text.json'),
  ('warsh-2-246', 'warsh', 2, 246, '۞ وَقَالَ لَهُمْ نَبِيٓـُٔهُمُۥٓ إِنَّ ءَايَةَ مُلْكِهِۦٓ أَنْ يَّاتِيَكُمُ ࡲ۬لتَّابُوتُ فِيهِ سَكِينَةࣱ مِّن رَّبِّكُمْ وَبَقِيَّةࣱ مِّمَّا تَرَكَ ءَالُ مُوسٜىٰ وَءَالُ هَٰرُونَ تَحْمِلُهُ ࡲ۬لْمَلَٰٓئِكَةُ࣌ إِنَّ فِے ذَٰلِكَ لَأٓيَةࣰ لَّكُمُۥٓ إِن كُنتُم مُّومِنِينَ࣌', 'وقال لهم نبيهم إن ءاية ملكه أن ياتيكم ࡲلتابوت فيه سكينة من ربكم وبقية مما ترك ءال موسى وءال هرون تحمله ࡲلملئكة࣌ إن فے ذلك لأية لكم إن كنتم مومنين࣌', NULL, 40, 'local:warsh-text.json'),
  ('warsh-2-247', 'warsh', 2, 247, 'فَلَمَّا فَصَلَ طَالُوتُ بِالْجُنُودِ قَالَ إِنَّ ࡰ۬للَّهَ مُبْتَلِيكُم بِنَهَرࣲ فَمَن شَرِبَ مِنْهُ فَلَيْسَ مِنِّے وَمَن لَّمْ يَطْعَمْهُ فَإِنَّهُۥ مِنِّيَ إِلَّا مَنِ ࡴٜغْتَرَفَ غَرْفَةَۢ بِيَدِهِۦ࣌ فَشَرِبُواْ مِنْهُ إِلَّا قَلِيلاࣰ مِّنْهُمْ࣌ فَلَمَّا جَاوَزَهُۥ هُوَ وَالذِينَ ءَامَنُواْ مَعَهُۥ قَالُواْ لَا طَاقَةَ لَنَا ࡰ۬لْيَوْمَ بِجَالُوتَ وَجُنُودِهِۦ࣌ قَالَ ࡰ۬لذِينَ يَظُنُّونَ أَنَّهُم مُّلَٰقُواْ ࡲ۬للَّهِ كَم مِّن فِئَةࣲ قَلِيلَةٍ غَلَبَتْ فِئَةࣰ كَثِيرَةَۢ بِإِذْنِ ࡴ۬للَّهِ࣌ وَاللَّهُ مَعَ ࡰ۬لصَّٰبِرِينَ࣌', 'فلما فصل طالوت بالجنود قال إن ࡰلله مبتليكم بنهر فمن شرب منه فليس منے ومن لم يطعمه فإنه مني إلا من ࡴغترف غرفة بيده࣌ فشربوا منه إلا قليلا منهم࣌ فلما جاوزه هو والذين ءامنوا معه قالوا لا طاقة لنا ࡰليوم بجالوت وجنوده࣌ قال ࡰلذين يظنون أنهم ملقوا ࡲلله كم من فئة قليلة غلبت فئة كثيرة بإذن ࡴلله࣌ والله مع ࡰلصبرين࣌', NULL, 41, 'local:warsh-text.json'),
  ('warsh-2-248', 'warsh', 2, 248, 'وَلَمَّا بَرَزُواْ لِجَالُوتَ وَجُنُودِهِۦ قَالُواْ رَبَّنَآ أَفْرِغْ عَلَيْنَا صَبْراࣰ وَثَبِّتَ ࡰقْدَامَنَا وَانصُرْنَا عَلَى ࡰ۬لْقَوْمِ ࡴ۬لْكٜـٰفِرِينَ', 'ولما برزوا لجالوت وجنوده قالوا ربنا أفرغ علينا صبرا وثبت ࡰقدامنا وانصرنا على ࡰلقوم ࡴلكفرين', NULL, 41, 'local:warsh-text.json'),
  ('warsh-2-249', 'warsh', 2, 249, 'فَهَزَمُوهُم بِإِذْنِ ࡴ۬للَّهِ࣌ وَقَتَلَ دَاوُۥدُ جَالُوتَ وَءَاتٜيٰهُ ࡲ۬للَّهُ ࡲ۬لْمُلْكَ وَالْحِكْمَةَ وَعَلَّمَهُۥ مِمَّا يَشَآءُ࣌ وَلَوْلَا دِفَٰعُ ࡲ۬للَّهِ ࡴ۬لنَّاسَ بَعْضَهُم بِبَعْضࣲ لَّفَسَدَتِ ࡴ۬لَارْضُ࣌ وَلَٰكِنَّ ࡰ۬للَّهَ ذُو فَضْلٍ عَلَى ࡰ۬لْعَٰلَمِينَ࣌', 'فهزموهم بإذن ࡴلله࣌ وقتل داود جالوت وءاتيه ࡲلله ࡲلملك والحكمة وعلمه مما يشاء࣌ ولولا دفع ࡲلله ࡴلناس بعضهم ببعض لفسدت ࡴلارض࣌ ولكن ࡰلله ذو فضل على ࡰلعلمين࣌', NULL, 41, 'local:warsh-text.json'),
  ('warsh-2-250', 'warsh', 2, 250, 'تِلْكَ ءَايَٰتُ ࡲ۬للَّهِ نَتْلُوهَا عَلَيْكَ بِالْحَقِّ࣌ وَإِنَّكَ لَمِنَ ࡰ۬لْمُرْسَلِينَ࣌', 'تلك ءايت ࡲلله نتلوها عليك بالحق࣌ وإنك لمن ࡰلمرسلين࣌', NULL, 41, 'local:warsh-text.json'),
  ('warsh-2-251', 'warsh', 2, 251, '۞ تِلْكَ ࡰ۬لرُّسُلُ࣌ فَضَّلْنَا بَعْضَهُمْ عَلَىٰ بَعْضࣲ࣌ مِّنْهُم مَّن كَلَّمَ ࡰ۬للَّهُ࣌ وَرَفَعَ بَعْضَهُمْ دَرَجَٰتࣲ࣌ وَءَاتَيْنَا عِيسَى ࡰٜبْنَ مَرْيَمَ ࡰ۬لْبَيِّنَٰتِ وَأَيَّدْنَٰهُ بِرُوحِ ࡴ۬لْقُدُسِ࣌ وَلَوْ شَآءَ ࡰ۬للَّهُ مَا ࡰٜقْتَتَلَ ࡰ۬لذِينَ مِنۢ بَعْدِهِم مِّنۢ بَعْدِ مَا جَآءَتْهُمُ ࡲ۬لْبَيِّنَٰتُ࣌ وَلَٰكِنِ ࡴٜخْتَلَفُواْ࣌ فَمِنْهُم مَّنَ اٰمَنَ وَمِنْهُم مَّن كَفَرَ࣌ وَلَوْ شَآءَ ࡰ۬للَّهُ مَا ࡰٜقْتَتَلُواْ࣌ وَلَٰكِنَّ ࡰ۬للَّهَ يَفْعَلُ مَا يُرِيدُ࣌', 'تلك ࡰلرسل࣌ فضلنا بعضهم على بعض࣌ منهم من كلم ࡰلله࣌ ورفع بعضهم درجت࣌ وءاتينا عيسى ࡰبن مريم ࡰلبينت وأيدنه بروح ࡴلقدس࣌ ولو شاء ࡰلله ما ࡰقتتل ࡰلذين من بعدهم من بعد ما جاءتهم ࡲلبينت࣌ ولكن ࡴختلفوا࣌ فمنهم من امن ومنهم من كفر࣌ ولو شاء ࡰلله ما ࡰقتتلوا࣌ ولكن ࡰلله يفعل ما يريد࣌', NULL, 42, 'local:warsh-text.json'),
  ('warsh-2-252', 'warsh', 2, 252, 'يَٰٓأَيُّهَا ࡰ۬لذِينَ ءَامَنُوٓاْ أَنفِقُواْ مِمَّا رَزَقْنَٰكُم مِّن قَبْلِ أَنْ يَّاتِيَ يَوْمࣱ لَّا بَيْعࣱ فِيهِ وَلَا خُلَّةࣱ وَلَا شَفَٰعَةࣱ࣌ وَالْكَٰفِرُونَ هُمُ ࡲ۬لظَّٰلِمُونَ࣌', 'يأيها ࡰلذين ءامنوا أنفقوا مما رزقنكم من قبل أن ياتي يوم لا بيع فيه ولا خلة ولا شفعة࣌ والكفرون هم ࡲلظلمون࣌', NULL, 42, 'local:warsh-text.json'),
  ('warsh-2-253', 'warsh', 2, 253, 'ࡰ۬للَّهُ لَآ إِلَٰهَ إِلَّا هُوَ࣌ ࡰ۬لْحَيُّ ࡲ۬لْقَيُّومُ࣌', 'ࡰلله لا إله إلا هو࣌ ࡰلحي ࡲلقيوم࣌', NULL, 42, 'local:warsh-text.json'),
  ('warsh-2-254', 'warsh', 2, 254, 'لَا تَاخُذُهُۥ سِنَةࣱ وَلَا نَوْمࣱ࣌ لَّهُۥ مَا فِے ࡴ۬لسَّمَٰوَٰتِ وَمَا فِے ࡴ۬لَارْضِ࣌ مَن ذَا ࡰ۬لذِے يَشْفَعُ عِندَهُۥٓ إِلَّا بِإِذْنِهِۦ࣌ يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ࣌ وَلَا يُحِيطُونَ بِشَےْءࣲ مِّنْ عِلْمِهِۦٓ إِلَّا بِمَا شَآءَ࣌ وَسِعَ كُرْسِيُّهُ ࡲ۬لسَّمَٰوَٰتِ وَالَارْضَ࣌ وَلَا يَـُٔودُهُۥ حِفْظُهُمَا࣌ وَهُوَ ࡰ۬لْعَلِيُّ ࡲ۬لْعَظِيمُ࣌', 'لا تاخذه سنة ولا نوم࣌ له ما فے ࡴلسموت وما فے ࡴلارض࣌ من ذا ࡰلذے يشفع عنده إلا بإذنه࣌ يعلم ما بين أيديهم وما خلفهم࣌ ولا يحيطون بشےء من علمه إلا بما شاء࣌ وسع كرسيه ࡲلسموت والارض࣌ ولا يوده حفظهما࣌ وهو ࡰلعلي ࡲلعظيم࣌', NULL, 42, 'local:warsh-text.json'),
  ('warsh-2-255', 'warsh', 2, 255, 'لَآ إِكْرَاهَ فِے ࡴ۬لدِّينِ࣌ قَد تَّبَيَّنَ ࡰ۬لرُّشْدُ مِنَ ࡰ۬لْغَيِّ࣌ فَمَنْ يَّكْفُرْ بِالطَّٰغُوتِ وَيُومِنۢ بِاللَّهِ فَقَدِ ࡴٜسْتَمْسَكَ بِالْعُرْوَةِ ࡴ۬لْوُثْقٜىٰ لَا ࡰٜنفِصَامَ لَهَا࣌ وَاللَّهُ سَمِيعٌ عَلِيمٌ࣌', 'لا إكراه فے ࡴلدين࣌ قد تبين ࡰلرشد من ࡰلغي࣌ فمن يكفر بالطغوت ويومن بالله فقد ࡴستمسك بالعروة ࡴلوثقى لا ࡰنفصام لها࣌ والله سميع عليم࣌', NULL, 42, 'local:warsh-text.json'),
  ('warsh-2-256', 'warsh', 2, 256, 'ࡴ۬للَّهُ وَلِيُّ ࡲ۬لذِينَ ءَامَنُواْ يُخْرِجُهُم مِّنَ ࡰ۬لظُّلُمَٰتِ إِلَى ࡰ۬لنُّورِ࣌ وَالذِينَ كَفَرُوٓاْ أَوْلِيَآؤُهُمُ ࡲ۬لطَّٰغُوتُ يُخْرِجُونَهُم مِّنَ ࡰ۬لنُّورِ إِلَى ࡰ۬لظُّلُمَٰتِ࣌ أُوْلَٰٓئِكَ أَصْحَٰبُ ࡲ۬لنّٜارِ هُمْ فِيهَا خَٰلِدُونَ࣌', 'ࡴلله ولي ࡲلذين ءامنوا يخرجهم من ࡰلظلمت إلى ࡰلنور࣌ والذين كفروا أولياؤهم ࡲلطغوت يخرجونهم من ࡰلنور إلى ࡰلظلمت࣌ أولئك أصحب ࡲلنار هم فيها خلدون࣌', NULL, 43, 'local:warsh-text.json'),
  ('warsh-2-257', 'warsh', 2, 257, '۞ أَلَمْ تَرَ إِلَى ࡰ۬لذِے حَآجَّ إِبْرَٰهِيمَ فِے رَبِّهِۦٓ أَنَ اٰتٜيٰهُ ࡲ۬للَّهُ ࡲ۬لْمُلْكَ إِذْ قَالَ إِبْرَٰهِيمُ رَبِّيَ ࡰ۬لذِے يُحْيِۦ وَيُمِيتُ࣌ قَالَ أَنَآ أُحْيِۦ وَأُمِيتُ࣌ قَالَ إِبْرَٰهِيمُ فَإِنَّ ࡰ۬للَّهَ يَاتِے بِالشَّمْسِ مِنَ ࡰ۬لْمَشْرِقِ فَاتِ بِهَا مِنَ ࡰ۬لْمَغْرِبِ فَبُهِتَ ࡰ۬لذِے كَفَرَ࣌ وَاللَّهُ لَا يَهْدِے ࡴ۬لْقَوْمَ ࡰ۬لظَّٰلِمِينَ࣌', 'ألم تر إلى ࡰلذے حاج إبرهيم فے ربه أن اتيه ࡲلله ࡲلملك إذ قال إبرهيم ربي ࡰلذے يحي ويميت࣌ قال أنا أحي وأميت࣌ قال إبرهيم فإن ࡰلله ياتے بالشمس من ࡰلمشرق فات بها من ࡰلمغرب فبهت ࡰلذے كفر࣌ والله لا يهدے ࡴلقوم ࡰلظلمين࣌', NULL, 43, 'local:warsh-text.json'),
  ('warsh-2-258', 'warsh', 2, 258, 'أَوْ كَالذِے مَرَّ عَلَىٰ قَرْيَةࣲ وَهِيَ خَاوِيَةٌ عَلَىٰ عُرُوشِهَا࣌ قَالَ أَنّٜىٰ يُحْيِۦ هَٰذِهِ ࡴ۬للَّهُ بَعْدَ مَوْتِهَا فَأَمَاتَهُ ࡲ۬للَّهُ مِاْئَةَ عَامࣲ ثُمَّ بَعَثَهُۥ࣌ قَالَ كَمْ لَبِثْتَ࣌ قَالَ لَبِثْتُ يَوْماً ࡰوْ بَعْضَ يَوْمࣲ࣌ قَالَ بَل لَّبِثْتَ مِاْئَةَ عَامࣲ࣌ فَانظُرِ ࡴلَىٰ طَعَامِكَ وَشَرَابِكَ لَمْ يَتَسَنَّهْ࣌ وَانظُرِ ࡴلَىٰ حِمٜارِكَ࣌ وَلِنَجْعَلَكَ ءَايَةࣰ لِّلنَّاسِ࣌ وَانظُرِ ࡴلَى ࡰ۬لْعِظَٰمِ كَيْفَ نُنشِرُهَا ثُمَّ نَكْسُوهَا لَحْماࣰ࣌ فَلَمَّا تَبَيَّنَ لَهُۥ قَالَ أَعْلَمُ أَنَّ ࡰ۬للَّهَ عَلَىٰ كُلِّ شَےْءࣲ قَدِيرࣱ࣌', 'أو كالذے مر على قرية وهي خاوية على عروشها࣌ قال أنى يحي هذه ࡴلله بعد موتها فأماته ࡲلله مائة عام ثم بعثه࣌ قال كم لبثت࣌ قال لبثت يوما ࡰو بعض يوم࣌ قال بل لبثت مائة عام࣌ فانظر ࡴلى طعامك وشرابك لم يتسنه࣌ وانظر ࡴلى حمارك࣌ ولنجعلك ءاية للناس࣌ وانظر ࡴلى ࡰلعظم كيف ننشرها ثم نكسوها لحما࣌ فلما تبين له قال أعلم أن ࡰلله على كل شےء قدير࣌', NULL, 43, 'local:warsh-text.json'),
  ('warsh-2-259', 'warsh', 2, 259, 'وَإِذْ قَالَ إِبْرَٰهِيمُ رَبِّ أَرِنِے كَيْفَ تُحْيِ ࡴ۬لْمَوْتٜىٰ࣌ قَالَ أَوَلَمْ تُومِن࣌ قَالَ بَلٜىٰ وَلَٰكِن لِّيَطْمَئِنَّ قَلْبِے࣌ قَالَ فَخُذَ ࡰرْبَعَةࣰ مِّنَ ࡰ۬لطَّيْرِ فَصُرْهُنَّ إِلَيْكَ ثُمَّ ࡰٜجْعَلْ عَلَىٰ كُلِّ جَبَلࣲ مِّنْهُنَّ جُزْءاࣰ ثُمَّ ࡸَدْعُهُنَّ يَاتِينَكَ سَعْياࣰ࣌ وَاعْلَمَ ࡰنَّ ࡰ۬للَّهَ عَزِيزٌ حَكِيمࣱ࣌', 'وإذ قال إبرهيم رب أرنے كيف تحي ࡴلموتى࣌ قال أولم تومن࣌ قال بلى ولكن ليطمئن قلبے࣌ قال فخذ ࡰربعة من ࡰلطير فصرهن إليك ثم ࡰجعل على كل جبل منهن جزءا ثم ࡸدعهن ياتينك سعيا࣌ واعلم ࡰن ࡰلله عزيز حكيم࣌', NULL, 44, 'local:warsh-text.json'),
  ('warsh-2-260', 'warsh', 2, 260, 'مَّثَلُ ࡲ۬لذِينَ يُنفِقُونَ أَمْوَٰلَهُمْ فِے سَبِيلِ ࡴ۬للَّهِ كَمَثَلِ حَبَّةٍ ࡰنۢبَتَتْ سَبْعَ سَنَابِلَ࣌ فِے كُلِّ سُنۢبُلَةࣲ مِّاْئَةُ حَبَّةࣲ࣌ وَاللَّهُ يُضَٰعِفُ لِمَنْ يَّشَآءُ࣌ وَاللَّهُ وَٰسِعٌ عَلِيمٌ࣌', 'مثل ࡲلذين ينفقون أمولهم فے سبيل ࡴلله كمثل حبة ࡰنبتت سبع سنابل࣌ فے كل سنبلة مائة حبة࣌ والله يضعف لمن يشاء࣌ والله وسع عليم࣌', NULL, 44, 'local:warsh-text.json'),
  ('warsh-2-261', 'warsh', 2, 261, 'ࡴ۬لذِينَ يُنفِقُونَ أَمْوَٰلَهُمْ فِے سَبِيلِ ࡴ۬للَّهِ ثُمَّ لَا يُتْبِعُونَ مَآ أَنفَقُواْ مَنّاࣰ وَلَآ أَذىࣰ لَّهُمُۥٓ أَجْرُهُمْ عِندَ رَبِّهِمْ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ࣌', 'ࡴلذين ينفقون أمولهم فے سبيل ࡴلله ثم لا يتبعون ما أنفقوا منا ولا أذى لهم أجرهم عند ربهم ولا خوف عليهم ولا هم يحزنون࣌', NULL, 44, 'local:warsh-text.json'),
  ('warsh-2-262', 'warsh', 2, 262, '۞ قَوْلࣱ مَّعْرُوفࣱ وَمَغْفِرَةٌ خَيْرࣱ مِّن صَدَقَةࣲ يَتْبَعُهَآ أَذىࣰ࣌ وَاللَّهُ غَنِيٌّ حَلِيمࣱ࣌', 'قول معروف ومغفرة خير من صدقة يتبعها أذى࣌ والله غني حليم࣌', NULL, 44, 'local:warsh-text.json'),
  ('warsh-2-263', 'warsh', 2, 263, 'يَٰٓأَيُّهَا ࡰ۬لذِينَ ءَامَنُواْ لَا تُبْطِلُواْ صَدَقَٰتِكُم بِالْمَنِّ وَالَاذٜىٰ كَالذِے يُنفِقُ مَالَهُۥ رِئَآءَ ࡰ۬لنَّاسِ وَلَا يُومِنُ بِاللَّهِ وَالْيَوْمِ ࡴ۬لَاخِرِ࣌ فَمَثَلُهُۥ كَمَثَلِ صَفْوَانٍ عَلَيْهِ تُرَابࣱ فَأَصَابَهُۥ وَابِلࣱ فَتَرَكَهُۥ صَلْداࣰ࣌ لَّا يَقْدِرُونَ عَلَىٰ شَےْءࣲ مِّمَّا كَسَبُواْ࣌ وَاللَّهُ لَا يَهْدِے ࡴ۬لْقَوْمَ ࡰ۬لْكٜـٰفِرِينَ࣌', 'يأيها ࡰلذين ءامنوا لا تبطلوا صدقتكم بالمن والاذى كالذے ينفق ماله رئاء ࡰلناس ولا يومن بالله واليوم ࡴلاخر࣌ فمثله كمثل صفوان عليه تراب فأصابه وابل فتركه صلدا࣌ لا يقدرون على شےء مما كسبوا࣌ والله لا يهدے ࡴلقوم ࡰلكفرين࣌', NULL, 44, 'local:warsh-text.json'),
  ('warsh-2-264', 'warsh', 2, 264, 'وَمَثَلُ ࡲ۬لذِينَ يُنفِقُونَ أَمْوَٰلَهُمُ ࡲٜبْتِغَآءَ مَرْضَاتِ ࡴ۬للَّهِ وَتَثْبِيتاࣰ مِّنَ ࡰنفُسِهِمْ كَمَثَلِ جَنَّةِۢ بِرُبْوَةٍ ࡰصَابَهَا وَابِلࣱ فَـَٔاتَتُ ࡳكْلَهَا ضِعْفَيْنِ فَإِن لَّمْ يُصِبْهَا وَابِلࣱ فَطَلࣱّ࣌ وَاللَّهُ بِمَا تَعْمَلُونَ بَصِيرٌ࣌', 'ومثل ࡲلذين ينفقون أمولهم ࡲبتغاء مرضات ࡴلله وتثبيتا من ࡰنفسهم كمثل جنة بربوة ࡰصابها وابل فاتت ࡳكلها ضعفين فإن لم يصبها وابل فطل࣌ والله بما تعملون بصير࣌', NULL, 45, 'local:warsh-text.json'),
  ('warsh-2-265', 'warsh', 2, 265, 'ࡰيَوَدُّ أَحَدُكُمُۥٓ أَن تَكُونَ لَهُۥ جَنَّةࣱ مِّن نَّخِيلࣲ وَأَعْنَٰبࣲ تَجْرِے مِن تَحْتِهَا ࡰ۬لَانْهَٰرُ لَهُۥ فِيهَا مِن كُلِّ ࡴ۬لثَّمَرَٰتِ وَأَصَابَهُ ࡲ۬لْكِبَرُ وَلَهُۥ ذُرِّيَّةࣱ ضُعَفَآءُ فَأَصَابَهَآ إِعْصَارࣱ فِيهِ نَارࣱ فَاحْتَرَقَتْ࣌ كَذَٰلِكَ يُبَيِّنُ ࡲ۬للَّهُ لَكُمُ ࡲ۬لَايَٰتِ لَعَلَّكُمْ تَتَفَكَّرُونَ࣌', 'ࡰيود أحدكم أن تكون له جنة من نخيل وأعنب تجرے من تحتها ࡰلانهر له فيها من كل ࡴلثمرت وأصابه ࡲلكبر وله ذرية ضعفاء فأصابها إعصار فيه نار فاحترقت࣌ كذلك يبين ࡲلله لكم ࡲلايت لعلكم تتفكرون࣌', NULL, 45, 'local:warsh-text.json'),
  ('warsh-2-266', 'warsh', 2, 266, '۞ يَٰٓأَيُّهَا ࡰ۬لذِينَ ءَامَنُوٓاْ أَنفِقُواْ مِن طَيِّبَٰتِ مَا كَسَبْتُمْ وَمِمَّآ أَخْرَجْنَا لَكُم مِّنَ ࡰ۬لَارْضِ࣌ وَلَا تَيَمَّمُواْ ࡲ۬لْخَبِيثَ مِنْهُ تُنفِقُونَ وَلَسْتُم بِـَٔاخِذِيهِ إِلَّآ أَن تُغْمِضُواْ فِيهِ࣌ وَاعْلَمُوٓاْ أَنَّ ࡰ۬للَّهَ غَنِيٌّ حَمِيدٌ࣌', 'يأيها ࡰلذين ءامنوا أنفقوا من طيبت ما كسبتم ومما أخرجنا لكم من ࡰلارض࣌ ولا تيمموا ࡲلخبيث منه تنفقون ولستم باخذيه إلا أن تغمضوا فيه࣌ واعلموا أن ࡰلله غني حميد࣌', NULL, 45, 'local:warsh-text.json'),
  ('warsh-2-267', 'warsh', 2, 267, 'ࡴ۬لشَّيْطَٰنُ يَعِدُكُمُ ࡲ۬لْفَقْرَ وَيَامُرُكُم بِالْفَحْشَآءِ࣌ وَاللَّهُ يَعِدُكُم مَّغْفِرَةࣰ مِّنْهُ وَفَضْلاࣰ࣌ وَاللَّهُ وَٰسِعٌ عَلِيمࣱ࣌', 'ࡴلشيطن يعدكم ࡲلفقر ويامركم بالفحشاء࣌ والله يعدكم مغفرة منه وفضلا࣌ والله وسع عليم࣌', NULL, 45, 'local:warsh-text.json'),
  ('warsh-2-268', 'warsh', 2, 268, 'يُوتِے ࡴ۬لْحِكْمَةَ مَنْ يَّشَآءُ࣌ وَمَنْ يُّوتَ ࡰ۬لْحِكْمَةَ فَقَدُ ࡳوتِيَ خَيْراࣰ كَثِيراࣰ࣌ وَمَا يَذَّكَّرُ إِلَّآ أُوْلُواْ ࡲ۬لَالْبَٰبِ࣌', 'يوتے ࡴلحكمة من يشاء࣌ ومن يوت ࡰلحكمة فقد ࡳوتي خيرا كثيرا࣌ وما يذكر إلا أولوا ࡲلالبب࣌', NULL, 45, 'local:warsh-text.json'),
  ('warsh-2-269', 'warsh', 2, 269, 'وَمَآ أَنفَقْتُم مِّن نَّفَقَةٍ ࡰوْ نَذَرْتُم مِّن نَّذْرࣲ فَإِنَّ ࡰ۬للَّهَ يَعْلَمُهُۥ࣌ وَمَا لِلظَّٰلِمِينَ مِنَ ࡰنصٜارٍ࣌', 'وما أنفقتم من نفقة ࡰو نذرتم من نذر فإن ࡰلله يعلمه࣌ وما للظلمين من ࡰنصار࣌', NULL, 46, 'local:warsh-text.json'),
  ('warsh-2-270', 'warsh', 2, 270, 'ࡴن تُبْدُواْ ࡲ۬لصَّدَقَٰتِ فَنِعِمَّا هِيَ࣌ وَإِن تُخْفُوهَا وَتُوتُوهَا ࡰ۬لْفُقَرَآءَ فَهُوَ خَيْرࣱ لَّكُمْ وَنُكَفِّرْ عَنكُم مِّن سَيِّـَٔاتِكُمْ࣌ وَاللَّهُ بِمَا تَعْمَلُونَ خَبِيرࣱ࣌', 'ࡴن تبدوا ࡲلصدقت فنعما هي࣌ وإن تخفوها وتوتوها ࡰلفقراء فهو خير لكم ونكفر عنكم من سياتكم࣌ والله بما تعملون خبير࣌', NULL, 46, 'local:warsh-text.json'),
  ('warsh-2-271', 'warsh', 2, 271, '۞ لَّيْسَ عَلَيْكَ هُدٜيٰهُمْ࣌ وَلَٰكِنَّ ࡰ۬للَّهَ يَهْدِے مَنْ يَّشَآءُ࣌ وَمَا تُنفِقُواْ مِنْ خَيْرࣲ فَلِأَنفُسِكُمْ࣌ وَمَا تُنفِقُونَ إِلَّا ࡰٜبْتِغَآءَ وَجْهِ ࡴ۬للَّهِ࣌ وَمَا تُنفِقُواْ مِنْ خَيْرࣲ يُوَفَّ إِلَيْكُمْ وَأَنتُمْ لَا تُظْلَمُونَ࣌', 'ليس عليك هديهم࣌ ولكن ࡰلله يهدے من يشاء࣌ وما تنفقوا من خير فلأنفسكم࣌ وما تنفقون إلا ࡰبتغاء وجه ࡴلله࣌ وما تنفقوا من خير يوف إليكم وأنتم لا تظلمون࣌', NULL, 46, 'local:warsh-text.json'),
  ('warsh-2-272', 'warsh', 2, 272, 'لِلْفُقَرَآءِ ࡴ۬لذِينَ أُحْصِرُواْ فِے سَبِيلِ ࡴ۬للَّهِ لَا يَسْتَطِيعُونَ ضَرْباࣰ فِے ࡴ۬لَارْضِ يَحْسِبُهُمُ ࡲ۬لْجَاهِلُ أَغْنِيَآءَ مِنَ ࡰ۬لتَّعَفُّفِ࣌ تَعْرِفُهُم بِسِيمٜـٰهُمْ لَا يَسْـَٔلُونَ ࡰ۬لنَّاسَ إِلْحَافاࣰ࣌ وَمَا تُنفِقُواْ مِنْ خَيْرࣲ فَإِنَّ ࡰ۬للَّهَ بِهِۦ عَلِيمٌ࣌', 'للفقراء ࡴلذين أحصروا فے سبيل ࡴلله لا يستطيعون ضربا فے ࡴلارض يحسبهم ࡲلجاهل أغنياء من ࡰلتعفف࣌ تعرفهم بسيمهم لا يسلون ࡰلناس إلحافا࣌ وما تنفقوا من خير فإن ࡰلله به عليم࣌', NULL, 46, 'local:warsh-text.json'),
  ('warsh-2-273', 'warsh', 2, 273, 'ࡴ۬لذِينَ يُنفِقُونَ أَمْوَٰلَهُم بِاليْلِ وَالنَّهٜارِ سِرّاࣰ وَعَلَٰنِيَةࣰ فَلَهُمُۥٓ أَجْرُهُمْ عِندَ رَبِّهِمْ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ࣌', 'ࡴلذين ينفقون أمولهم باليل والنهار سرا وعلنية فلهم أجرهم عند ربهم ولا خوف عليهم ولا هم يحزنون࣌', NULL, 46, 'local:warsh-text.json'),
  ('warsh-2-274', 'warsh', 2, 274, 'ࡰ۬لذِينَ يَاكُلُونَ ࡰ۬لرِّبَوٰاْ لَا يَقُومُونَ إِلَّا كَمَا يَقُومُ ࡲ۬لذِے يَتَخَبَّطُهُ ࡲ۬لشَّيْطَٰنُ مِنَ ࡰ۬لْمَسِّ࣌ ذَٰلِكَ بِأَنَّهُمْ قَالُوٓاْ إِنَّمَا ࡰ۬لْبَيْعُ مِثْلُ ࡲ۬لرِّبَوٰاْ࣌ وَأَحَلَّ ࡰ۬للَّهُ ࡲ۬لْبَيْعَ وَحَرَّمَ ࡰ۬لرِّبَوٰاْ࣌ فَمَن جَآءَهُۥ مَوْعِظَةࣱ مِّن رَّبِّهِۦ فَانتَهٜىٰ فَلَهُۥ مَا سَلَفَ࣌ وَأَمْرُهُۥٓ إِلَى ࡰ۬للَّهِ࣌ وَمَنْ عَادَ فَأُوْلَٰٓئِكَ أَصْحَٰبُ ࡲ۬لنّٜارِ هُمْ فِيهَا خَٰلِدُونَ࣌', 'ࡰلذين ياكلون ࡰلربوا لا يقومون إلا كما يقوم ࡲلذے يتخبطه ࡲلشيطن من ࡰلمس࣌ ذلك بأنهم قالوا إنما ࡰلبيع مثل ࡲلربوا࣌ وأحل ࡰلله ࡲلبيع وحرم ࡰلربوا࣌ فمن جاءه موعظة من ربه فانتهى فله ما سلف࣌ وأمره إلى ࡰلله࣌ ومن عاد فأولئك أصحب ࡲلنار هم فيها خلدون࣌', NULL, 47, 'local:warsh-text.json'),
  ('warsh-2-275', 'warsh', 2, 275, 'يَمْحَقُ ࡲ۬للَّهُ ࡲ۬لرِّبَوٰاْ وَيُرْبِے ࡴ۬لصَّدَقَٰتِ࣌ وَاللَّهُ لَا يُحِبُّ كُلَّ كَفّٜارٍ ࡰثِيمٍ࣌', 'يمحق ࡲلله ࡲلربوا ويربے ࡴلصدقت࣌ والله لا يحب كل كفار ࡰثيم࣌', NULL, 47, 'local:warsh-text.json'),
  ('warsh-2-276', 'warsh', 2, 276, 'ࡴنَّ ࡰ۬لذِينَ ءَامَنُواْ وَعَمِلُواْ ࡲ۬لصَّٰلِحَٰتِ وَأَقَامُواْ ࡲ۬لصَّلَوٰةَ وَءَاتَوُاْ ࡲ۬لزَّكَوٰةَ لَهُمُۥٓ أَجْرُهُمْ عِندَ رَبِّهِمْ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ࣌', 'ࡴن ࡰلذين ءامنوا وعملوا ࡲلصلحت وأقاموا ࡲلصلوة وءاتوا ࡲلزكوة لهم أجرهم عند ربهم ولا خوف عليهم ولا هم يحزنون࣌', NULL, 47, 'local:warsh-text.json'),
  ('warsh-2-277', 'warsh', 2, 277, 'يَٰٓأَيُّهَا ࡰ۬لذِينَ ءَامَنُواْ ࡲٜتَّقُواْ ࡲ۬للَّهَ وَذَرُواْ مَا بَقِيَ مِنَ ࡰ۬لرِّبَوٰٓاْ إِن كُنتُم مُّومِنِينَ࣌', 'يأيها ࡰلذين ءامنوا ࡲتقوا ࡲلله وذروا ما بقي من ࡰلربوا إن كنتم مومنين࣌', NULL, 47, 'local:warsh-text.json'),
  ('warsh-2-278', 'warsh', 2, 278, 'فَإِن لَّمْ تَفْعَلُواْ فَاذَنُواْ بِحَرْبࣲ مِّنَ ࡰ۬للَّهِ وَرَسُولِهِۦ࣌ وَإِن تُبْتُمْ فَلَكُمْ رُءُوسُ أَمْوَٰلِكُمْ لَا تَظْلِمُونَ وَلَا تُظْلَمُونَ࣌', 'فإن لم تفعلوا فاذنوا بحرب من ࡰلله ورسوله࣌ وإن تبتم فلكم رءوس أمولكم لا تظلمون ولا تظلمون࣌', NULL, 47, 'local:warsh-text.json'),
  ('warsh-2-279', 'warsh', 2, 279, '۞ وَإِن كَانَ ذُو عُسْرَةࣲ فَنَظِرَةٌ ࡴلَىٰ مَيْسُرَةࣲ࣌ وَأَن تَصَّدَّقُواْ خَيْرࣱ لَّكُمُۥٓ إِن كُنتُمْ تَعْلَمُونَ࣌', 'وإن كان ذو عسرة فنظرة ࡴلى ميسرة࣌ وأن تصدقوا خير لكم إن كنتم تعلمون࣌', NULL, 47, 'local:warsh-text.json'),
  ('warsh-2-280', 'warsh', 2, 280, 'وَاتَّقُواْ يَوْماࣰ تُرْجَعُونَ فِيهِ إِلَى ࡰ۬للَّهِ࣌ ثُمَّ تُوَفّٜىٰ كُلُّ نَفْسࣲ مَّا كَسَبَتْ وَهُمْ لَا يُظْلَمُونَ࣌', 'واتقوا يوما ترجعون فيه إلى ࡰلله࣌ ثم توفى كل نفس ما كسبت وهم لا يظلمون࣌', NULL, 47, 'local:warsh-text.json'),
  ('warsh-2-281', 'warsh', 2, 281, 'يَٰٓأَيُّهَا ࡰ۬لذِينَ ءَامَنُوٓاْ إِذَا تَدَايَنتُم بِدَيْنٍ ࡴلَىٰٓ أَجَلࣲ مُّسَمّىࣰ فَاكْتُبُوهُ࣌ وَلْيَكْتُب بَّيْنَكُمْ كَاتِبُۢ بِالْعَدْلِ࣌ وَلَا يَابَ كَاتِبٌ ࡰنْ يَّكْتُبَ࣌ كَمَا عَلَّمَهُ ࡲ۬للَّهُ فَلْيَكْتُبْ࣌ وَلْيُمْلِلِ ࡴ۬لذِے عَلَيْهِ ࡴ۬لْحَقُّ وَلْيَتَّقِ ࡴ۬للَّهَ رَبَّهُۥ وَلَا يَبْخَسْ مِنْهُ شَيْـٔاࣰ࣌ فَإِن كَانَ ࡰ۬لذِے عَلَيْهِ ࡴ۬لْحَقُّ سَفِيهاً ࡰوْ ضَعِيفاً ࡰوْ لَا يَسْتَطِيعُ أَنْ يُّمِلَّ هُوَ فَلْيُمْلِلْ وَلِيُّهُۥ بِالْعَدْلِ࣌ وَاسْتَشْهِدُواْ شَهِيدَيْنِ مِن رِّجَالِكُمْ࣌ فَإِن لَّمْ يَكُونَا رَجُلَيْنِ فَرَجُلࣱ وَامْرَأَتَٰنِ مِمَّن تَرْضَوْنَ مِنَ ࡰ۬لشُّهَدَآءِ ࡶَن تَضِلَّ إِحْدٜيٰهُمَا فَتُذَكِّرَ إِحْدٜيٰهُمَا ࡰ۬لُاخْرٜىٰ࣌ وَلَا يَابَ ࡰ۬لشُّهَدَآءُ ࡹِذَا مَا دُعُواْ࣌ وَلَا تَسْـَٔمُوٓاْ أَن تَكْتُبُوهُ صَغِيراً ࡰوْ كَبِيراً ࡴلَىٰٓ أَجَلِهِۦ࣌ ذَٰلِكُمُۥٓ أَقْسَطُ عِندَ ࡰ۬للَّهِ وَأَقْوَمُ لِلشَّهَٰدَةِ وَأَدْنٜىٰٓ أَلَّا تَرْتَابُوٓاْ إِلَّآ أَن تَكُونَ تِجَٰرَةٌ حَاضِرَةࣱ تُدِيرُونَهَا بَيْنَكُمْ فَلَيْسَ عَلَيْكُمْ جُنَاحٌ ࡰلَّا تَكْتُبُوهَا࣌ وَأَشْهِدُوٓاْ إِذَا تَبَايَعْتُمْ࣌ وَلَا يُضَآرَّ كَاتِبࣱ وَلَا شَهِيدࣱ࣌ وَإِن تَفْعَلُواْ فَإِنَّهُۥ فُسُوقُۢ بِكُمْ࣌ وَاتَّقُواْ ࡲ۬للَّهَ࣌ وَيُعَلِّمُكُمُ ࡲ۬للَّهُ࣌ وَاللَّهُ بِكُلِّ شَےْءٍ عَلِيمࣱ࣌', 'يأيها ࡰلذين ءامنوا إذا تداينتم بدين ࡴلى أجل مسمى فاكتبوه࣌ وليكتب بينكم كاتب بالعدل࣌ ولا ياب كاتب ࡰن يكتب࣌ كما علمه ࡲلله فليكتب࣌ وليملل ࡴلذے عليه ࡴلحق وليتق ࡴلله ربه ولا يبخس منه شيا࣌ فإن كان ࡰلذے عليه ࡴلحق سفيها ࡰو ضعيفا ࡰو لا يستطيع أن يمل هو فليملل وليه بالعدل࣌ واستشهدوا شهيدين من رجالكم࣌ فإن لم يكونا رجلين فرجل وامرأتن ممن ترضون من ࡰلشهداء ࡶن تضل إحديهما فتذكر إحديهما ࡰلاخرى࣌ ولا ياب ࡰلشهداء ࡹذا ما دعوا࣌ ولا تسموا أن تكتبوه صغيرا ࡰو كبيرا ࡴلى أجله࣌ ذلكم أقسط عند ࡰلله وأقوم للشهدة وأدنى ألا ترتابوا إلا أن تكون تجرة حاضرة تديرونها بينكم فليس عليكم جناح ࡰلا تكتبوها࣌ وأشهدوا إذا تبايعتم࣌ ولا يضار كاتب ولا شهيد࣌ وإن تفعلوا فإنه فسوق بكم࣌ واتقوا ࡲلله࣌ ويعلمكم ࡲلله࣌ والله بكل شےء عليم࣌', NULL, 48, 'local:warsh-text.json'),
  ('warsh-2-282', 'warsh', 2, 282, '۞ وَإِن كُنتُمْ عَلَىٰ سَفَرࣲ وَلَمْ تَجِدُواْ كَاتِباࣰ فَرِهَٰنࣱ مَّقْبُوضَةࣱ࣌ فَإِنَ ࡰمِنَ بَعْضُكُم بَعْضاࣰ فَلْيُوَ۬دِّ ࡴ۬لذِے ࡴ࢈وتُمِنَ أَمَٰنَتَهُۥ࣌ وَلْيَتَّقِ ࡴ۬للَّهَ رَبَّهُۥ࣌ وَلَا تَكْتُمُواْ ࡲ۬لشَّهَٰدَةَ࣌ وَمَنْ يَّكْتُمْهَا فَإِنَّهُۥٓ ءَاثِمࣱ قَلْبُهُۥ࣌ وَاللَّهُ بِمَا تَعْمَلُونَ عَلِيمࣱ࣌', 'وإن كنتم على سفر ولم تجدوا كاتبا فرهن مقبوضة࣌ فإن ࡰمن بعضكم بعضا فليود ࡴلذے ࡴ࢈وتمن أمنته࣌ وليتق ࡴلله ربه࣌ ولا تكتموا ࡲلشهدة࣌ ومن يكتمها فإنه ءاثم قلبه࣌ والله بما تعملون عليم࣌', NULL, 49, 'local:warsh-text.json'),
  ('warsh-2-283', 'warsh', 2, 283, 'لِّلهِ مَا فِے ࡴ۬لسَّمَٰوَٰتِ وَمَا فِے ࡴ۬لَارْضِ࣌ وَإِن تُبْدُواْ مَا فِےٓ أَنفُسِكُمُۥٓ أَوْ تُخْفُوهُ يُحَاسِبْكُم بِهِ ࡴ۬للَّهُ فَيَغْفِرْ لِمَنْ يَّشَآءُ وَيُعَذِّبْ مَنْ يَّشَآءُ࣌ وَاللَّهُ عَلَىٰ كُلِّ شَےْءࣲ قَدِيرٌ࣌', 'لله ما فے ࡴلسموت وما فے ࡴلارض࣌ وإن تبدوا ما فے أنفسكم أو تخفوه يحاسبكم به ࡴلله فيغفر لمن يشاء ويعذب من يشاء࣌ والله على كل شےء قدير࣌', NULL, 49, 'local:warsh-text.json'),
  ('warsh-2-284', 'warsh', 2, 284, 'اٰمَنَ ࡰ۬لرَّسُولُ بِمَآ أُنزِلَ إِلَيْهِ مِن رَّبِّهِۦ وَالْمُومِنُونَ࣌ كُلٌّ اٰمَنَ بِاللَّهِ وَمَلَٰٓئِكَتِهِۦ وَكُتُبِهِۦ وَرُسُلِهِۦ࣌ لَا نُفَرِّقُ بَيْنَ أَحَدࣲ مِّن رُّسُلِهِۦ࣌ وَقَالُواْ سَمِعْنَا وَأَطَعْنَا࣌ غُفْرَانَكَ رَبَّنَا࣌ وَإِلَيْكَ ࡰ۬لْمَصِيرُ࣌', 'امن ࡰلرسول بما أنزل إليه من ربه والمومنون࣌ كل امن بالله وملئكته وكتبه ورسله࣌ لا نفرق بين أحد من رسله࣌ وقالوا سمعنا وأطعنا࣌ غفرانك ربنا࣌ وإليك ࡰلمصير࣌', NULL, 49, 'local:warsh-text.json'),
  ('warsh-2-285', 'warsh', 2, 285, 'لَا يُكَلِّفُ ࡲ۬للَّهُ نَفْساً ࡴلَّا وُسْعَهَا࣌ لَهَا مَا كَسَبَتْ࣌ وَعَلَيْهَا مَا ࡰٜكْتَسَبَتْ࣌ رَبَّنَا لَا تُوَ۬اخِذْنَآ إِن نَّسِينَآ أَوَ ࡰخْطَأْنَا࣌ رَبَّنَا وَلَا تَحْمِلْ عَلَيْنَآ إِصْراࣰ كَمَا حَمَلْتَهُۥ عَلَى ࡰ۬لذِينَ مِن قَبْلِنَا࣌ رَبَّنَا وَلَا تُحَمِّلْنَا مَا لَا طَاقَةَ لَنَا بِهِۦ࣌ وَاعْفُ عَنَّا࣌ وَاغْفِرْ لَنَا࣌ وَارْحَمْنَآ࣌ أَنتَ مَوْلٜيٰنَا فَانصُرْنَا عَلَى ࡰ۬لْقَوْمِ ࡴ۬لْكٜـٰفِرِينَ࣌', 'لا يكلف ࡲلله نفسا ࡴلا وسعها࣌ لها ما كسبت࣌ وعليها ما ࡰكتسبت࣌ ربنا لا تواخذنا إن نسينا أو ࡰخطأنا࣌ ربنا ولا تحمل علينا إصرا كما حملته على ࡰلذين من قبلنا࣌ ربنا ولا تحملنا ما لا طاقة لنا به࣌ واعف عنا࣌ واغفر لنا࣌ وارحمنا࣌ أنت مولينا فانصرنا على ࡰلقوم ࡴلكفرين࣌', NULL, 49, 'local:warsh-text.json'),
  ('warsh-3-1', 'warsh', 3, 1, 'أَلَٓمِّٓ࣌ ࡰ۬للَّهُ لَآ إِلَٰهَ إِلَّا هُوَ࣌ ࡰ۬لْحَيُّ ࡲ۬لْقَيُّومُ', 'ألم࣌ ࡰلله لا إله إلا هو࣌ ࡰلحي ࡲلقيوم', NULL, 50, 'local:warsh-text.json'),
  ('warsh-3-2', 'warsh', 3, 2, 'نَزَّلَ عَلَيْكَ ࡰ۬لْكِتَٰبَ بِالْحَقِّ مُصَدِّقاࣰ لِّمَا بَيْنَ يَدَيْهِ࣌ وَأَنزَلَ ࡰ۬لتَّوْرٜيٰةَ وَالِانجِيلَ', 'نزل عليك ࡰلكتب بالحق مصدقا لما بين يديه࣌ وأنزل ࡰلتورية والانجيل', NULL, 50, 'local:warsh-text.json'),
  ('warsh-3-3', 'warsh', 3, 3, 'مِن قَبْلُ هُدىࣰ لِّلنَّاسِ وَأَنزَلَ ࡰ۬لْفُرْقَانَ࣌', 'من قبل هدى للناس وأنزل ࡰلفرقان࣌', NULL, 50, 'local:warsh-text.json'),
  ('warsh-3-4', 'warsh', 3, 4, 'إِنَّ ࡰ۬لذِينَ كَفَرُواْ بِـَٔايَٰتِ ࡴ۬للَّهِ لَهُمْ عَذَابࣱ شَدِيدࣱ࣌ وَاللَّهُ عَزِيزࣱ ذُو ࡲٜنتِقَامٍ࣌', 'إن ࡰلذين كفروا بايت ࡴلله لهم عذاب شديد࣌ والله عزيز ذو ࡲنتقام࣌', NULL, 50, 'local:warsh-text.json'),
  ('warsh-3-5', 'warsh', 3, 5, '۞ ࡴنَّ ࡰ۬للَّهَ لَا يَخْفٜىٰ عَلَيْهِ شَےْءࣱ فِے ࡴ۬لَارْضِ وَلَا فِے ࡴ۬لسَّمَآءِ࣌', 'ࡴن ࡰلله لا يخفى عليه شےء فے ࡴلارض ولا فے ࡴلسماء࣌', NULL, 50, 'local:warsh-text.json'),
  ('warsh-3-6', 'warsh', 3, 6, 'هُوَ ࡰ۬لذِے يُصَوِّرُكُمْ فِے ࡴ۬لَارْحَامِ كَيْفَ يَشَآءُ࣌ لَآ إِلَٰهَ إِلَّا هُوَ࣌ ࡰ۬لْعَزِيزُ ࡲ۬لْحَكِيمُ࣌', 'هو ࡰلذے يصوركم فے ࡴلارحام كيف يشاء࣌ لا إله إلا هو࣌ ࡰلعزيز ࡲلحكيم࣌', NULL, 50, 'local:warsh-text.json'),
  ('warsh-3-7', 'warsh', 3, 7, 'هُوَ ࡰ۬لذِےٓ أَنزَلَ عَلَيْكَ ࡰ۬لْكِتَٰبَ مِنْهُ࣌ ءَايَٰتࣱ مُّحْكَمَٰتٌ هُنَّ أُمُّ ࡲ۬لْكِتَٰبِ وَأُخَرُ مُتَشَٰبِهَٰتࣱ࣌ فَأَمَّا ࡰ۬لذِينَ فِے قُلُوبِهِمْ زَيْغࣱ فَيَتَّبِعُونَ مَا تَشَٰبَهَ مِنْهُ ࡲٜبْتِغَآءَ ࡰ۬لْفِتْنَةِ وَابْتِغَآءَ تَاوِيلِهِۦ࣌ وَمَا يَعْلَمُ تَاوِيلَهُۥٓ إِلَّا ࡰ۬للَّهُ࣌ وَالرَّٰسِخُونَ فِے ࡴ۬لْعِلْمِ يَقُولُونَ ءَامَنَّا بِهِۦ كُلࣱّ مِّنْ عِندِ رَبِّنَا࣌ وَمَا يَذَّكَّرُ إِلَّآ أُوْلُواْ ࡲ۬لَالْبَٰبِ࣌', 'هو ࡰلذے أنزل عليك ࡰلكتب منه࣌ ءايت محكمت هن أم ࡲلكتب وأخر متشبهت࣌ فأما ࡰلذين فے قلوبهم زيغ فيتبعون ما تشبه منه ࡲبتغاء ࡰلفتنة وابتغاء تاويله࣌ وما يعلم تاويله إلا ࡰلله࣌ والرسخون فے ࡴلعلم يقولون ءامنا به كل من عند ربنا࣌ وما يذكر إلا أولوا ࡲلالبب࣌', NULL, 50, 'local:warsh-text.json'),
  ('warsh-3-8', 'warsh', 3, 8, 'رَبَّنَا لَا تُزِغْ قُلُوبَنَا بَعْدَ إِذْ هَدَيْتَنَا وَهَبْ لَنَا مِن لَّدُنكَ رَحْمَةً࣌ ࡴنَّكَ أَنتَ ࡰ۬لْوَهَّابُ࣌', 'ربنا لا تزغ قلوبنا بعد إذ هديتنا وهب لنا من لدنك رحمة࣌ ࡴنك أنت ࡰلوهاب࣌', NULL, 50, 'local:warsh-text.json'),
  ('warsh-3-9', 'warsh', 3, 9, 'رَبَّنَآ إِنَّكَ جَامِعُ ࡲ۬لنَّاسِ لِيَوْمࣲ لَّا رَيْبَ فِيهِ࣌ إِنَّ ࡰ۬للَّهَ لَا يُخْلِفُ ࡲ۬لْمِيعَادَ࣌', 'ربنا إنك جامع ࡲلناس ليوم لا ريب فيه࣌ إن ࡰلله لا يخلف ࡲلميعاد࣌', NULL, 50, 'local:warsh-text.json'),
  ('warsh-3-10', 'warsh', 3, 10, 'إِنَّ ࡰ۬لذِينَ كَفَرُواْ لَن تُغْنِيَ عَنْهُمُۥٓ أَمْوَٰلُهُمْ وَلَآ أَوْلَٰدُهُم مِّنَ ࡰ۬للَّهِ شَيْـٔاࣰ࣌ وَأُوْلَٰٓئِكَ هُمْ وَقُودُ ࡲ۬لنّٜارِ', 'إن ࡰلذين كفروا لن تغني عنهم أمولهم ولا أولدهم من ࡰلله شيا࣌ وأولئك هم وقود ࡲلنار', NULL, 51, 'local:warsh-text.json'),
  ('warsh-3-11', 'warsh', 3, 11, 'كَدَأْبِ ءَالِ فِرْعَوْنَ࣌ وَالذِينَ مِن قَبْلِهِمْ كَذَّبُواْ بِـَٔايَٰتِنَا فَأَخَذَهُمُ ࡲ۬للَّهُ بِذُنُوبِهِمْ࣌ وَاللَّهُ شَدِيدُ ࡲ۬لْعِقَابِ࣌', 'كدأب ءال فرعون࣌ والذين من قبلهم كذبوا بايتنا فأخذهم ࡲلله بذنوبهم࣌ والله شديد ࡲلعقاب࣌', NULL, 51, 'local:warsh-text.json'),
  ('warsh-3-12', 'warsh', 3, 12, 'قُل لِّلذِينَ كَفَرُواْ سَتُغْلَبُونَ وَتُحْشَرُونَ إِلَىٰ جَهَنَّمَ࣌ وَبِيسَ ࡰ۬لْمِهَادُ࣌', 'قل للذين كفروا ستغلبون وتحشرون إلى جهنم࣌ وبيس ࡰلمهاد࣌', NULL, 51, 'local:warsh-text.json'),
  ('warsh-3-13', 'warsh', 3, 13, 'قَدْ كَانَ لَكُمُۥٓ ءَايَةࣱ فِے فِئَتَيْنِ ࡴٜلْتَقَتَا࣌ فِئَةࣱ تُقَٰتِلُ فِے سَبِيلِ ࡴ۬للَّهِ وَأُخْرٜىٰ كَافِرَةࣱ تَرَوْنَهُم مِّثْلَيْهِمْ رَأْيَ ࡰ۬لْعَيْنِ࣌ وَاللَّهُ يُوَ۬يِّدُ بِنَصْرِهِۦ مَنْ يَّشَآءُ࣌ ࡹِنَّ فِے ذَٰلِكَ لَعِبْرَةࣰ لِّأُوْلِے ࡴ۬لَابْصٜـٰرِ࣌', 'قد كان لكم ءاية فے فئتين ࡴلتقتا࣌ فئة تقتل فے سبيل ࡴلله وأخرى كافرة ترونهم مثليهم رأي ࡰلعين࣌ والله يويد بنصره من يشاء࣌ ࡹن فے ذلك لعبرة لأولے ࡴلابصر࣌', NULL, 51, 'local:warsh-text.json'),
  ('warsh-3-14', 'warsh', 3, 14, 'زُيِّنَ لِلنَّاسِ حُبُّ ࡲ۬لشَّهَوَٰتِ مِنَ ࡰ۬لنِّسَآءِ وَالْبَنِينَ وَالْقَنَٰطِيرِ ࡴ۬لْمُقَنطَرَةِ مِنَ ࡰ۬لذَّهَبِ وَالْفِضَّةِ وَالْخَيْلِ ࡴ۬لْمُسَوَّمَةِ وَالَانْعَٰمِ وَالْحَرْثِ࣌ ذَٰلِكَ مَتَٰعُ ࡲ۬لْحَيَوٰةِ ࡴ۬لدُّنْيٜا࣌ وَاللَّهُ عِندَهُۥ حُسْنُ ࡲ۬لْمَـَٔابِ࣌', 'زين للناس حب ࡲلشهوت من ࡰلنساء والبنين والقنطير ࡴلمقنطرة من ࡰلذهب والفضة والخيل ࡴلمسومة والانعم والحرث࣌ ذلك متع ࡲلحيوة ࡴلدنيا࣌ والله عنده حسن ࡲلماب࣌', NULL, 51, 'local:warsh-text.json'),
  ('warsh-3-15', 'warsh', 3, 15, '۞ قُلَ ࡰوْࢇنَبِّئُكُم بِخَيْرࣲ مِّن ذَٰلِكُمْ࣌ لِلذِينَ ࡰٜتَّقَوْاْ عِندَ رَبِّهِمْ جَنَّٰتࣱ تَجْرِے مِن تَحْتِهَا ࡰ۬لَانْهَٰرُ خَٰلِدِينَ فِيهَا وَأَزْوَٰجࣱ مُّطَهَّرَةࣱ وَرِضْوَٰنࣱ مِّنَ ࡰ۬للَّهِ࣌ وَاللَّهُ بَصِيرُۢ بِالْعِبَادِ࣌', 'قل ࡰوࢇنبئكم بخير من ذلكم࣌ للذين ࡰتقوا عند ربهم جنت تجرے من تحتها ࡰلانهر خلدين فيها وأزوج مطهرة ورضون من ࡰلله࣌ والله بصير بالعباد࣌', NULL, 51, 'local:warsh-text.json'),
  ('warsh-3-16', 'warsh', 3, 16, 'ࡴ۬لذِينَ يَقُولُونَ رَبَّنَآ إِنَّنَآ ءَامَنَّا فَاغْفِرْ لَنَا ذُنُوبَنَا وَقِنَا عَذَابَ ࡰ۬لنّٜارِ࣌', 'ࡴلذين يقولون ربنا إننا ءامنا فاغفر لنا ذنوبنا وقنا عذاب ࡰلنار࣌', NULL, 52, 'local:warsh-text.json'),
  ('warsh-3-17', 'warsh', 3, 17, 'ࡴ۬لصَّٰبِرِينَ وَالصَّٰدِقِينَ وَالْقَٰنِتِينَ وَالْمُنفِقِينَ وَالْمُسْتَغْفِرِينَ بِالَاسْحٜارِ࣌', 'ࡴلصبرين والصدقين والقنتين والمنفقين والمستغفرين بالاسحار࣌', NULL, 52, 'local:warsh-text.json'),
  ('warsh-3-18', 'warsh', 3, 18, 'شَهِدَ ࡰ۬للَّهُ أَنَّهُۥ لَآ إِلَٰهَ إِلَّا هُوَ وَالْمَلَٰٓئِكَةُ وَأُوْلُواْ ࡲ۬لْعِلْمِ قَآئِماَۢ بِالْقِسْطِ࣌ لَآ إِلَٰهَ إِلَّا هُوَ࣌ ࡰ۬لْعَزِيزُ ࡲ۬لْحَكِيمُ࣌', 'شهد ࡰلله أنه لا إله إلا هو والملئكة وأولوا ࡲلعلم قائما بالقسط࣌ لا إله إلا هو࣌ ࡰلعزيز ࡲلحكيم࣌', NULL, 52, 'local:warsh-text.json'),
  ('warsh-3-19', 'warsh', 3, 19, 'إِنَّ ࡰ۬لدِّينَ عِندَ ࡰ۬للَّهِ ࡴ۬لِاسْلَٰمُ࣌ وَمَا ࡰٜخْتَلَفَ ࡰ۬لذِينَ أُوتُواْ ࡲ۬لْكِتَٰبَ إِلَّا مِنۢ بَعْدِ مَا جَآءَهُمُ ࡲ۬لْعِلْمُ࣌ بَغْياَۢ بَيْنَهُمْ࣌ وَمَنْ يَّكْفُرْ بِـَٔايَٰتِ ࡴ۬للَّهِ فَإِنَّ ࡰ۬للَّهَ سَرِيعُ ࡲ۬لْحِسَابِ࣌', 'إن ࡰلدين عند ࡰلله ࡴلاسلم࣌ وما ࡰختلف ࡰلذين أوتوا ࡲلكتب إلا من بعد ما جاءهم ࡲلعلم࣌ بغيا بينهم࣌ ومن يكفر بايت ࡴلله فإن ࡰلله سريع ࡲلحساب࣌', NULL, 52, 'local:warsh-text.json'),
  ('warsh-3-20', 'warsh', 3, 20, 'فَإِنْ حَآجُّوكَ فَقُلَ ࡰسْلَمْتُ وَجْهِيَ لِلهِ وَمَنِ ࡴٜتَّبَعَنِۦ࣌ وَقُل لِّلذِينَ أُوتُواْ ࡲ۬لْكِتَٰبَ وَالُامِّيِّۑنَ ءَآسْلَمْتُمْ࣌ فَإِنَ ࡰسْلَمُواْ فَقَدِ ࡴٜهْتَدَواْ࣌ وَّإِن تَوَلَّوْاْ فَإِنَّمَا عَلَيْكَ ࡰ۬لْبَلَٰغُ࣌ وَاللَّهُ بَصِيرُۢ بِالْعِبَادِ࣌', 'فإن حاجوك فقل ࡰسلمت وجهي لله ومن ࡴتبعن࣌ وقل للذين أوتوا ࡲلكتب والاميۑن ءاسلمتم࣌ فإن ࡰسلموا فقد ࡴهتدوا࣌ وإن تولوا فإنما عليك ࡰلبلغ࣌ والله بصير بالعباد࣌', NULL, 52, 'local:warsh-text.json'),
  ('warsh-3-21', 'warsh', 3, 21, 'إِنَّ ࡰ۬لذِينَ يَكْفُرُونَ بِـَٔايَٰتِ ࡴ۬للَّهِ وَيَقْتُلُونَ ࡰ۬لنَّبِيٓـِٕۑنَ بِغَيْرِ حَقࣲّ وَيَقْتُلُونَ ࡰ۬لذِينَ يَامُرُونَ بِالْقِسْطِ مِنَ ࡰ۬لنَّاسِ فَبَشِّرْهُم بِعَذَابٍ ࡰلِيمٍ࣌', 'إن ࡰلذين يكفرون بايت ࡴلله ويقتلون ࡰلنبيۑن بغير حق ويقتلون ࡰلذين يامرون بالقسط من ࡰلناس فبشرهم بعذاب ࡰليم࣌', NULL, 52, 'local:warsh-text.json'),
  ('warsh-3-22', 'warsh', 3, 22, 'ࡳوْلَٰٓئِكَ ࡰ۬لذِينَ حَبِطَتَ ࡰعْمَٰلُهُمْ فِے ࡴ۬لدُّنْيٜا وَالَاخِرَةِ࣌ وَمَا لَهُم مِّن نَّٰصِرِينَ࣌', 'ࡳولئك ࡰلذين حبطت ࡰعملهم فے ࡴلدنيا والاخرة࣌ وما لهم من نصرين࣌', NULL, 52, 'local:warsh-text.json'),
  ('warsh-3-23', 'warsh', 3, 23, '۞ أَلَمْ تَرَ إِلَى ࡰ۬لذِينَ أُوتُواْ نَصِيباࣰ مِّنَ ࡰ۬لْكِتَٰبِ يُدْعَوْنَ إِلَىٰ كِتَٰبِ ࡴ۬للَّهِ لِيَحْكُمَ بَيْنَهُمْ ثُمَّ يَتَوَلّٜىٰ فَرِيقࣱ مِّنْهُمْ وَهُم مُّعْرِضُونَ࣌', 'ألم تر إلى ࡰلذين أوتوا نصيبا من ࡰلكتب يدعون إلى كتب ࡴلله ليحكم بينهم ثم يتولى فريق منهم وهم معرضون࣌', NULL, 53, 'local:warsh-text.json'),
  ('warsh-3-24', 'warsh', 3, 24, 'ذَٰلِكَ بِأَنَّهُمْ قَالُواْ لَن تَمَسَّنَا ࡰ۬لنَّارُ إِلَّآ أَيَّاماࣰ مَّعْدُودَٰتࣲ وَغَرَّهُمْ فِے دِينِهِم مَّا كَانُواْ يَفْتَرُونَ࣌', 'ذلك بأنهم قالوا لن تمسنا ࡰلنار إلا أياما معدودت وغرهم فے دينهم ما كانوا يفترون࣌', NULL, 53, 'local:warsh-text.json'),
  ('warsh-3-25', 'warsh', 3, 25, 'فَكَيْفَ إِذَا جَمَعْنَٰهُمْ لِيَوْمࣲ لَّا رَيْبَ فِيهِ وَوُفِّيَتْ كُلُّ نَفْسࣲ مَّا كَسَبَتْ وَهُمْ لَا يُظْلَمُونَ࣌', 'فكيف إذا جمعنهم ليوم لا ريب فيه ووفيت كل نفس ما كسبت وهم لا يظلمون࣌', NULL, 53, 'local:warsh-text.json'),
  ('warsh-3-26', 'warsh', 3, 26, 'قُلِ ࡴ۬للَّهُمَّ مَٰلِكَ ࡰ۬لْمُلْكِ تُوتِے ࡴ۬لْمُلْكَ مَن تَشَآءُ وَتَنزِعُ ࡲ۬لْمُلْكَ مِمَّن تَشَآءُ وَتُعِزُّ مَن تَشَآءُ وَتُذِلُّ مَن تَشَآءُ بِيَدِكَ ࡰ۬لْخَيْرُ࣌ إِنَّكَ عَلَىٰ كُلِّ شَےْءࣲ قَدِيرࣱ࣌', 'قل ࡴللهم ملك ࡰلملك توتے ࡴلملك من تشاء وتنزع ࡲلملك ممن تشاء وتعز من تشاء وتذل من تشاء بيدك ࡰلخير࣌ إنك على كل شےء قدير࣌', NULL, 53, 'local:warsh-text.json'),
  ('warsh-3-27', 'warsh', 3, 27, 'تُولِجُ ࡲ۬ليْلَ فِے ࡴ۬لنَّهٜارِ وَتُولِجُ ࡲ۬لنَّهَارَ فِے ࡴ۬ليْلِ وَتُخْرِجُ ࡲ۬لْحَيَّ مِنَ ࡰ۬لْمَيِّتِ وَتُخْرِجُ ࡲ۬لْمَيِّتَ مِنَ ࡰ۬لْحَيِّ وَتَرْزُقُ مَن تَشَآءُ بِغَيْرِ حِسَابࣲ࣌', 'تولج ࡲليل فے ࡴلنهار وتولج ࡲلنهار فے ࡴليل وتخرج ࡲلحي من ࡰلميت وتخرج ࡲلميت من ࡰلحي وترزق من تشاء بغير حساب࣌', NULL, 53, 'local:warsh-text.json'),
  ('warsh-3-28', 'warsh', 3, 28, 'لَّا يَتَّخِذِ ࡴ۬لْمُومِنُونَ ࡰ۬لْكٜـٰفِرِينَ أَوْلِيَآءَ مِن دُونِ ࡴ۬لْمُومِنِينَ࣌ وَمَنْ يَّفْعَلْ ذَٰلِكَ فَلَيْسَ مِنَ ࡰ۬للَّهِ فِے شَےْءٍ ࡴلَّآ أَن تَتَّقُواْ مِنْهُمْ تُقٜيٰةࣰ࣌ وَيُحَذِّرُكُمُ ࡲ۬للَّهُ نَفْسَهُۥ࣌ وَإِلَى ࡰ۬للَّهِ ࡴ۬لْمَصِيرُ࣌', 'لا يتخذ ࡴلمومنون ࡰلكفرين أولياء من دون ࡴلمومنين࣌ ومن يفعل ذلك فليس من ࡰلله فے شےء ࡴلا أن تتقوا منهم تقية࣌ ويحذركم ࡲلله نفسه࣌ وإلى ࡰلله ࡴلمصير࣌', NULL, 53, 'local:warsh-text.json'),
  ('warsh-3-29', 'warsh', 3, 29, 'قُلِ ࡴن تُخْفُواْ مَا فِے صُدُورِكُمُۥٓ أَوْ تُبْدُوهُ يَعْلَمْهُ ࡲ۬للَّهُ࣌ وَيَعْلَمُ مَا فِے ࡴ۬لسَّمَٰوَٰتِ وَمَا فِے ࡴ۬لَارْضِ࣌ وَاللَّهُ عَلَىٰ كُلِّ شَےْءࣲ قَدِيرࣱ࣌', 'قل ࡴن تخفوا ما فے صدوركم أو تبدوه يعلمه ࡲلله࣌ ويعلم ما فے ࡴلسموت وما فے ࡴلارض࣌ والله على كل شےء قدير࣌', NULL, 53, 'local:warsh-text.json'),
  ('warsh-3-30', 'warsh', 3, 30, 'يَوْمَ تَجِدُ كُلُّ نَفْسࣲ مَّا عَمِلَتْ مِنْ خَيْرࣲ مُّحْضَراࣰ࣌ وَمَا عَمِلَتْ مِن سُوٓءࣲ تَوَدُّ لَوَ ࡰنَّ بَيْنَهَا وَبَيْنَهُۥٓ أَمَداَۢ بَعِيداࣰ࣌ وَيُحَذِّرُكُمُ ࡲ۬للَّهُ نَفْسَهُۥ࣌ وَاللَّهُ رَءُوفُۢ بِالْعِبَادِ࣌', 'يوم تجد كل نفس ما عملت من خير محضرا࣌ وما عملت من سوء تود لو ࡰن بينها وبينه أمدا بعيدا࣌ ويحذركم ࡲلله نفسه࣌ والله رءوف بالعباد࣌', NULL, 54, 'local:warsh-text.json'),
  ('warsh-3-31', 'warsh', 3, 31, 'قُلِ ࡴن كُنتُمْ تُحِبُّونَ ࡰ۬للَّهَ فَاتَّبِعُونِے يُحْبِبْكُمُ ࡲ۬للَّهُ وَيَغْفِرْ لَكُمْ ذُنُوبَكُمْ࣌ وَاللَّهُ غَفُورࣱ رَّحِيمࣱ࣌', 'قل ࡴن كنتم تحبون ࡰلله فاتبعونے يحببكم ࡲلله ويغفر لكم ذنوبكم࣌ والله غفور رحيم࣌', NULL, 54, 'local:warsh-text.json'),
  ('warsh-3-32', 'warsh', 3, 32, 'قُلَ ࡰطِيعُواْ ࡲ۬للَّهَ وَالرَّسُولَ࣌ فَإِن تَوَلَّوْاْ فَإِنَّ ࡰ۬للَّهَ لَا يُحِبُّ ࡲ۬لْكٜـٰفِرِينَ࣌', 'قل ࡰطيعوا ࡲلله والرسول࣌ فإن تولوا فإن ࡰلله لا يحب ࡲلكفرين࣌', NULL, 54, 'local:warsh-text.json'),
  ('warsh-3-33', 'warsh', 3, 33, '۞ إِنَّ ࡰ۬للَّهَ ࡰٜصْطَفٜىٰٓ ءَادَمَ وَنُوحاࣰ وَءَالَ إِبْرَٰهِيمَ وَءَالَ عِمْرَٰنَ عَلَى ࡰ۬لْعَٰلَمِينَ', 'إن ࡰلله ࡰصطفى ءادم ونوحا وءال إبرهيم وءال عمرن على ࡰلعلمين', NULL, 54, 'local:warsh-text.json'),
  ('warsh-3-34', 'warsh', 3, 34, 'ذُرِّيَّةَۢ بَعْضُهَا مِنۢ بَعْضࣲ࣌ وَاللَّهُ سَمِيعٌ عَلِيمٌ࣌', 'ذرية بعضها من بعض࣌ والله سميع عليم࣌', NULL, 54, 'local:warsh-text.json'),
  ('warsh-3-35', 'warsh', 3, 35, 'ࡴذْ قَالَتِ ࡴٜمْرَأَتُ عِمْرَٰنَ رَبِّ إِنِّے نَذَرْتُ لَكَ مَا فِے بَطْنِے مُحَرَّراࣰ فَتَقَبَّلْ مِنِّيَ࣌ إِنَّكَ أَنتَ ࡰ۬لسَّمِيعُ ࡲ۬لْعَلِيمُ࣌', 'ࡴذ قالت ࡴمرأت عمرن رب إنے نذرت لك ما فے بطنے محررا فتقبل مني࣌ إنك أنت ࡰلسميع ࡲلعليم࣌', NULL, 54, 'local:warsh-text.json'),
  ('warsh-3-36', 'warsh', 3, 36, 'فَلَمَّا وَضَعَتْهَا قَالَتْ رَبِّ إِنِّے وَضَعْتُهَآ أُنثٜىٰ وَاللَّهُ أَعْلَمُ بِمَا وَضَعَتْ࣌ وَلَيْسَ ࡰ۬لذَّكَرُ كَالُانثٜىٰ࣌ وَإِنِّے سَمَّيْتُهَا مَرْيَمَ࣌ وَإِنِّيَ أُعِيذُهَا بِكَ وَذُرِّيَّتَهَا مِنَ ࡰ۬لشَّيْطَٰنِ ࡴ۬لرَّجِيمِ࣌', 'فلما وضعتها قالت رب إنے وضعتها أنثى والله أعلم بما وضعت࣌ وليس ࡰلذكر كالانثى࣌ وإنے سميتها مريم࣌ وإني أعيذها بك وذريتها من ࡰلشيطن ࡴلرجيم࣌', NULL, 54, 'local:warsh-text.json'),
  ('warsh-3-37', 'warsh', 3, 37, 'فَتَقَبَّلَهَا رَبُّهَا بِقَبُولٍ حَسَنࣲ وَأَنۢبَتَهَا نَبَاتاً حَسَناࣰ࣌ وَكَفَلَهَا زَكَرِيَّآءُ࣌ كُلَّمَا دَخَلَ عَلَيْهَا زَكَرِيَّآءُ ࡲ۬لْمِحْرَابَ وَجَدَ عِندَهَا رِزْقاࣰ࣌ قَالَ يَٰمَرْيَمُ أَنّٜىٰ لَكِ هَٰذَا࣌ قَالَتْ هُوَ مِنْ عِندِ ࡴ۬للَّهِ࣌ إِنَّ ࡰ۬للَّهَ يَرْزُقُ مَنْ يَّشَآءُ بِغَيْرِ حِسَابٍ࣌', 'فتقبلها ربها بقبول حسن وأنبتها نباتا حسنا࣌ وكفلها زكرياء࣌ كلما دخل عليها زكرياء ࡲلمحراب وجد عندها رزقا࣌ قال يمريم أنى لك هذا࣌ قالت هو من عند ࡴلله࣌ إن ࡰلله يرزق من يشاء بغير حساب࣌', NULL, 54, 'local:warsh-text.json'),
  ('warsh-3-38', 'warsh', 3, 38, 'هُنَالِكَ دَعَا زَكَرِيَّآءُ رَبَّهُۥ࣌ قَالَ رَبِّ هَبْ لِے مِن لَّدُنكَ ذُرِّيَّةࣰ طَيِّبَةً ࡴنَّكَ سَمِيعُ ࡲ۬لدُّعَآءِ࣌', 'هنالك دعا زكرياء ربه࣌ قال رب هب لے من لدنك ذرية طيبة ࡴنك سميع ࡲلدعاء࣌', NULL, 55, 'local:warsh-text.json'),
  ('warsh-3-39', 'warsh', 3, 39, 'فَنَادَتْهُ ࡲ۬لْمَلَٰٓئِكَةُ وَهُوَ قَآئِمࣱ يُصَلِّے فِے ࡴ۬لْمِحْرَابِ أَنَّ ࡰ۬للَّهَ يُبَشِّرُكَ بِيَحْيٜىٰ مُصَدِّقاَۢ بِكَلِمَةࣲ مِّنَ ࡰ۬للَّهِ وَسَيِّداࣰ وَحَصُوراࣰ وَنَبِيٓـٔاࣰ مِّنَ ࡰ۬لصَّٰلِحِينَ࣌', 'فنادته ࡲلملئكة وهو قائم يصلے فے ࡴلمحراب أن ࡰلله يبشرك بيحيى مصدقا بكلمة من ࡰلله وسيدا وحصورا ونبيا من ࡰلصلحين࣌', NULL, 55, 'local:warsh-text.json'),
  ('warsh-3-40', 'warsh', 3, 40, 'قَالَ رَبِّ أَنّٜىٰ يَكُونُ لِے غُلَٰمࣱ وَقَدْ بَلَغَنِيَ ࡰ۬لْكِبَرُ وَامْرَأَتِے عَاقِرࣱ࣌ قَالَ كَذَٰلِكَ࣌ ࡰ۬للَّهُ يَفْعَلُ مَا يَشَآءُ࣌', 'قال رب أنى يكون لے غلم وقد بلغني ࡰلكبر وامرأتے عاقر࣌ قال كذلك࣌ ࡰلله يفعل ما يشاء࣌', NULL, 55, 'local:warsh-text.json'),
  ('warsh-3-41', 'warsh', 3, 41, 'قَالَ رَبِّ ࡴٜجْعَل لِّيَ ءَايَةࣰ࣌ قَالَ ءَايَتُكَ أَلَّا تُكَلِّمَ ࡰ۬لنَّاسَ ثَلَٰثَةَ أَيَّامٍ ࡴلَّا رَمْزاࣰ࣌ وَاذْكُر رَّبَّكَ كَثِيراࣰ وَسَبِّحْ بِالْعَشِيِّ وَالِابْكٜـٰرِ࣌', 'قال رب ࡴجعل لي ءاية࣌ قال ءايتك ألا تكلم ࡰلناس ثلثة أيام ࡴلا رمزا࣌ واذكر ربك كثيرا وسبح بالعشي والابكر࣌', NULL, 55, 'local:warsh-text.json'),
  ('warsh-3-42', 'warsh', 3, 42, '۞ وَإِذْ قَالَتِ ࡴ۬لْمَلَٰٓئِكَةُ يَٰمَرْيَمُ إِنَّ ࡰ۬للَّهَ ࡰٜصْطَفٜيٰكِ وَطَهَّرَكِ وَاصْطَفٜيٰكِ عَلَىٰ نِسَآءِ ࡴ۬لْعَٰلَمِينَ࣌', 'وإذ قالت ࡴلملئكة يمريم إن ࡰلله ࡰصطفيك وطهرك واصطفيك على نساء ࡴلعلمين࣌', NULL, 55, 'local:warsh-text.json'),
  ('warsh-3-43', 'warsh', 3, 43, 'يَٰمَرْيَمُ ࡲ࢈قْنُتِے لِرَبِّكِ وَاسْجُدِے وَارْكَعِے مَعَ ࡰ۬لرَّٰكِعِينَ࣌', 'يمريم ࡲ࢈قنتے لربك واسجدے واركعے مع ࡰلركعين࣌', NULL, 55, 'local:warsh-text.json'),
  ('warsh-3-44', 'warsh', 3, 44, 'ذَٰلِكَ مِنَ ࡰنۢبَآءِ ࡴ۬لْغَيْبِ نُوحِيهِ إِلَيْكَ࣌ وَمَا كُنتَ لَدَيْهِمُۥٓ إِذْ يُلْقُونَ أَقْلَٰمَهُمُۥٓ أَيُّهُمْ يَكْفُلُ مَرْيَمَ࣌ وَمَا كُنتَ لَدَيْهِمُۥٓ إِذْ يَخْتَصِمُونَ', 'ذلك من ࡰنباء ࡴلغيب نوحيه إليك࣌ وما كنت لديهم إذ يلقون أقلمهم أيهم يكفل مريم࣌ وما كنت لديهم إذ يختصمون', NULL, 55, 'local:warsh-text.json'),
  ('warsh-3-45', 'warsh', 3, 45, 'إِذْ قَالَتِ ࡴ۬لْمَلَٰٓئِكَةُ يَٰمَرْيَمُ إِنَّ ࡰ۬للَّهَ يُبَشِّرُكِ بِكَلِمَةࣲ مِّنْهُ࣌ ࡲٜسْمُهُ ࡲ۬لْمَسِيحُ عِيسَى ࡰٜبْنُ مَرْيَمَ وَجِيهاࣰ فِے ࡴ۬لدُّنْيٜا وَالَاخِرَةِ وَمِنَ ࡰ۬لْمُقَرَّبِينَ࣌', 'إذ قالت ࡴلملئكة يمريم إن ࡰلله يبشرك بكلمة منه࣌ ࡲسمه ࡲلمسيح عيسى ࡰبن مريم وجيها فے ࡴلدنيا والاخرة ومن ࡰلمقربين࣌', NULL, 55, 'local:warsh-text.json'),
  ('warsh-3-46', 'warsh', 3, 46, 'وَيُكَلِّمُ ࡲ۬لنَّاسَ فِے ࡴ۬لْمَهْدِ وَكَهْلاࣰ࣌ وَمِنَ ࡰ۬لصَّٰلِحِينَ࣌', 'ويكلم ࡲلناس فے ࡴلمهد وكهلا࣌ ومن ࡰلصلحين࣌', NULL, 56, 'local:warsh-text.json'),
  ('warsh-3-47', 'warsh', 3, 47, 'قَالَتْ رَبِّ أَنّٜىٰ يَكُونُ لِے وَلَدࣱ وَلَمْ يَمْسَسْنِے بَشَرࣱ࣌ قَالَ كَذَٰلِكِ࣌ ࡴ۬للَّهُ يَخْلُقُ مَا يَشَآءُ࣌ ࡹِذَا قَضٜىٰٓ أَمْراࣰ فَإِنَّمَا يَقُولُ لَهُۥ كُن࣌ فَيَكُونُ࣌', 'قالت رب أنى يكون لے ولد ولم يمسسنے بشر࣌ قال كذلك࣌ ࡴلله يخلق ما يشاء࣌ ࡹذا قضى أمرا فإنما يقول له كن࣌ فيكون࣌', NULL, 56, 'local:warsh-text.json'),
  ('warsh-3-48', 'warsh', 3, 48, 'وَيُعَلِّمُهُ ࡲ۬لْكِتَٰبَ وَالْحِكْمَةَ وَالتَّوْرٜيٰةَ وَالِانجِيلَ وَرَسُولاً ࡴلَىٰ بَنِےٓ إِسْرَآءِيلَ أَنِّے قَدْ جِئْتُكُم بِـَٔايَةࣲ مِّن رَّبِّكُمُۥٓ࣌ إِنِّيَ أَخْلُقُ لَكُم مِّنَ ࡰ۬لطِّينِ كَهَيْـَٔةِ ࡴ۬لطَّيْرِ فَأَنفُخُ فِيهِ فَيَكُونُ طَٰٓئِراَۢ بِإِذْنِ ࡴ۬للَّهِ࣌ وَأُبْرِۓُ ࡲ۬لَاكْمَهَ وَالَابْرَصَ وَأُحْيِ ࡴ۬لْمَوْتٜىٰ بِإِذْنِ ࡴ۬للَّهِ࣌ وَأُنَبِّئُكُم بِمَا تَاكُلُونَ وَمَا تَدَّخِرُونَ فِے بُيُوتِكُمُۥٓ࣌ إِنَّ فِے ذَٰلِكَ لَأٓيَةࣰ لَّكُمُۥٓ إِن كُنتُم مُّومِنِينَ࣌', 'ويعلمه ࡲلكتب والحكمة والتورية والانجيل ورسولا ࡴلى بنے إسراءيل أنے قد جئتكم باية من ربكم࣌ إني أخلق لكم من ࡰلطين كهية ࡴلطير فأنفخ فيه فيكون طئرا بإذن ࡴلله࣌ وأبرے ࡲلاكمه والابرص وأحي ࡴلموتى بإذن ࡴلله࣌ وأنبئكم بما تاكلون وما تدخرون فے بيوتكم࣌ إن فے ذلك لأية لكم إن كنتم مومنين࣌', NULL, 56, 'local:warsh-text.json'),
  ('warsh-3-49', 'warsh', 3, 49, 'وَمُصَدِّقاࣰ لِّمَا بَيْنَ يَدَيَّ مِنَ ࡰ۬لتَّوْرٜيٰةِ وَلِأُحِلَّ لَكُم بَعْضَ ࡰ۬لذِے حُرِّمَ عَلَيْكُمْ࣌ وَجِئْتُكُم بِـَٔايَةࣲ مِّن رَّبِّكُمْ࣌ فَاتَّقُواْ ࡲ۬للَّهَ وَأَطِيعُونِ࣌', 'ومصدقا لما بين يدي من ࡰلتورية ولأحل لكم بعض ࡰلذے حرم عليكم࣌ وجئتكم باية من ربكم࣌ فاتقوا ࡲلله وأطيعون࣌', NULL, 56, 'local:warsh-text.json'),
  ('warsh-3-50', 'warsh', 3, 50, 'إِنَّ ࡰ۬للَّهَ رَبِّے وَرَبُّكُمْ فَاعْبُدُوهُ࣌ هَٰذَا صِرَٰطࣱ مُّسْتَقِيمࣱ࣌', 'إن ࡰلله ربے وربكم فاعبدوه࣌ هذا صرط مستقيم࣌', NULL, 56, 'local:warsh-text.json'),
  ('warsh-3-51', 'warsh', 3, 51, '۞ فَلَمَّآ أَحَسَّ عِيسٜىٰ مِنْهُمُ ࡲ۬لْكُفْرَ قَالَ مَنَ ࡰنصَارِيَ إِلَى ࡰ۬للَّهِ࣌ قَالَ ࡰ۬لْحَوَارِيُّونَ نَحْنُ أَنصَارُ ࡲ۬للَّهِ࣌ ءَامَنَّا بِاللَّهِ وَاشْهَدْ بِأَنَّا مُسْلِمُونَ࣌', 'فلما أحس عيسى منهم ࡲلكفر قال من ࡰنصاري إلى ࡰلله࣌ قال ࡰلحواريون نحن أنصار ࡲلله࣌ ءامنا بالله واشهد بأنا مسلمون࣌', NULL, 56, 'local:warsh-text.json'),
  ('warsh-3-52', 'warsh', 3, 52, 'رَبَّنَآ ءَامَنَّا بِمَآ أَنزَلْتَ وَاتَّبَعْنَا ࡰ۬لرَّسُولَ فَاكْتُبْنَا مَعَ ࡰ۬لشَّٰهِدِينَ࣌', 'ربنا ءامنا بما أنزلت واتبعنا ࡰلرسول فاكتبنا مع ࡰلشهدين࣌', NULL, 57, 'local:warsh-text.json'),
  ('warsh-3-53', 'warsh', 3, 53, 'وَمَكَرُواْ وَمَكَرَ ࡰ۬للَّهُ࣌ وَاللَّهُ خَيْرُ ࡲ۬لْمَٰكِرِينَ࣌', 'ومكروا ومكر ࡰلله࣌ والله خير ࡲلمكرين࣌', NULL, 57, 'local:warsh-text.json'),
  ('warsh-3-54', 'warsh', 3, 54, 'إِذْ قَالَ ࡰ۬للَّهُ يَٰعِيسٜىٰٓ إِنِّے مُتَوَفِّيكَ وَرَافِعُكَ إِلَيَّ وَمُطَهِّرُكَ مِنَ ࡰ۬لذِينَ كَفَرُواْ࣌ وَجَاعِلُ ࡲ۬لذِينَ ࡰٜتَّبَعُوكَ فَوْقَ ࡰ۬لذِينَ كَفَرُوٓاْ إِلَىٰ يَوْمِ ࡴ۬لْقِيَٰمَةِ࣌ ثُمَّ إِلَيَّ مَرْجِعُكُمْ فَأَحْكُمُ بَيْنَكُمْ فِيمَا كُنتُمْ فِيهِ تَخْتَلِفُونَ࣌', 'إذ قال ࡰلله يعيسى إنے متوفيك ورافعك إلي ومطهرك من ࡰلذين كفروا࣌ وجاعل ࡲلذين ࡰتبعوك فوق ࡰلذين كفروا إلى يوم ࡴلقيمة࣌ ثم إلي مرجعكم فأحكم بينكم فيما كنتم فيه تختلفون࣌', NULL, 57, 'local:warsh-text.json'),
  ('warsh-3-55', 'warsh', 3, 55, 'فَأَمَّا ࡰ۬لذِينَ كَفَرُواْ فَأُعَذِّبُهُمْ عَذَاباࣰ شَدِيداࣰ فِے ࡴ۬لدُّنْيٜا وَالَاخِرَةِ࣌ وَمَا لَهُم مِّن نَّٰصِرِينَ࣌', 'فأما ࡰلذين كفروا فأعذبهم عذابا شديدا فے ࡴلدنيا والاخرة࣌ وما لهم من نصرين࣌', NULL, 57, 'local:warsh-text.json'),
  ('warsh-3-56', 'warsh', 3, 56, 'وَأَمَّا ࡰ۬لذِينَ ءَامَنُواْ وَعَمِلُواْ ࡲ۬لصَّٰلِحَٰتِ فَنُوَفِّيهِمُۥٓ أُجُورَهُمْ࣌ وَاللَّهُ لَا يُحِبُّ ࡲ۬لظَّٰلِمِينَ࣌', 'وأما ࡰلذين ءامنوا وعملوا ࡲلصلحت فنوفيهم أجورهم࣌ والله لا يحب ࡲلظلمين࣌', NULL, 57, 'local:warsh-text.json'),
  ('warsh-3-57', 'warsh', 3, 57, 'ذَٰلِكَ نَتْلُوهُ عَلَيْكَ مِنَ ࡰ۬لَايَٰتِ وَالذِّكْرِ ࡴ۬لْحَكِيمِ࣌', 'ذلك نتلوه عليك من ࡰلايت والذكر ࡴلحكيم࣌', NULL, 57, 'local:warsh-text.json'),
  ('warsh-3-58', 'warsh', 3, 58, 'إِنَّ مَثَلَ عِيسٜىٰ عِندَ ࡰ۬للَّهِ كَمَثَلِ ءَادَمَ࣌ خَلَقَهُۥ مِن تُرَابࣲ ثُمَّ قَالَ لَهُۥ كُن࣌ فَيَكُونُ࣌', 'إن مثل عيسى عند ࡰلله كمثل ءادم࣌ خلقه من تراب ثم قال له كن࣌ فيكون࣌', NULL, 57, 'local:warsh-text.json'),
  ('warsh-3-59', 'warsh', 3, 59, 'ࡲ۬لْحَقُّ مِن رَّبِّكَ࣌ فَلَا تَكُن مِّنَ ࡰ۬لْمُمْتَرِينَ࣌', 'ࡲلحق من ربك࣌ فلا تكن من ࡰلممترين࣌', NULL, 57, 'local:warsh-text.json'),
  ('warsh-3-60', 'warsh', 3, 60, 'فَمَنْ حَآجَّكَ فِيهِ مِنۢ بَعْدِ مَا جَآءَكَ مِنَ ࡰ۬لْعِلْمِ فَقُلْ تَعَالَوْاْ نَدْعُ أَبْنَآءَنَا وَأَبْنَآءَكُمْ وَنِسَآءَنَا وَنِسَآءَكُمْ وَأَنفُسَنَا وَأَنفُسَكُمْ ثُمَّ نَبْتَهِلْ فَنَجْعَل لَّعْنَتَ ࡰ۬للَّهِ عَلَى ࡰ۬لْكَٰذِبِينَ࣌', 'فمن حاجك فيه من بعد ما جاءك من ࡰلعلم فقل تعالوا ندع أبناءنا وأبناءكم ونساءنا ونساءكم وأنفسنا وأنفسكم ثم نبتهل فنجعل لعنت ࡰلله على ࡰلكذبين࣌', NULL, 57, 'local:warsh-text.json'),
  ('warsh-3-61', 'warsh', 3, 61, 'إِنَّ هَٰذَا لَهُوَ ࡰ۬لْقَصَصُ ࡲ۬لْحَقُّ࣌ وَمَا مِنِ ࡴلَٰهٍ ࡴلَّا ࡰ۬للَّهُ࣌ وَإِنَّ ࡰ۬للَّهَ لَهُوَ ࡰ۬لْعَزِيزُ ࡲ۬لْحَكِيمُ࣌', 'إن هذا لهو ࡰلقصص ࡲلحق࣌ وما من ࡴله ࡴلا ࡰلله࣌ وإن ࡰلله لهو ࡰلعزيز ࡲلحكيم࣌', NULL, 58, 'local:warsh-text.json'),
  ('warsh-3-62', 'warsh', 3, 62, 'فَإِن تَوَلَّوْاْ فَإِنَّ ࡰ۬للَّهَ عَلِيمُۢ بِالْمُفْسِدِينَ࣌', 'فإن تولوا فإن ࡰلله عليم بالمفسدين࣌', NULL, 58, 'local:warsh-text.json'),
  ('warsh-3-63', 'warsh', 3, 63, '۞ قُلْ يَٰٓأَهْلَ ࡰ۬لْكِتَٰبِ تَعَالَوِاْ ࡴلَىٰ كَلِمَةࣲ سَوَآءِۢ بَيْنَنَا وَبَيْنَكُمُۥٓ أَلَّا نَعْبُدَ إِلَّا ࡰ۬للَّهَ وَلَا نُشْرِكَ بِهِۦ شَيْـٔاࣰ وَلَا يَتَّخِذَ بَعْضُنَا بَعْضاً ࡰرْبَاباࣰ مِّن دُونِ ࡴ۬للَّهِ࣌ فَإِن تَوَلَّوْاْ فَقُولُواْ ࡲٜشْهَدُواْ بِأَنَّا مُسْلِمُونَ࣌', 'قل يأهل ࡰلكتب تعالوا ࡴلى كلمة سواء بيننا وبينكم ألا نعبد إلا ࡰلله ولا نشرك به شيا ولا يتخذ بعضنا بعضا ࡰربابا من دون ࡴلله࣌ فإن تولوا فقولوا ࡲشهدوا بأنا مسلمون࣌', NULL, 58, 'local:warsh-text.json'),
  ('warsh-3-64', 'warsh', 3, 64, 'يَٰٓأَهْلَ ࡰ۬لْكِتَٰبِ لِمَ تُحَآجُّونَ فِےٓ إِبْرَٰهِيمَ࣌ وَمَآ أُنزِلَتِ ࡴ۬لتَّوْرٜيٰةُ وَالِانجِيلُ إِلَّا مِنۢ بَعْدِهِۦٓ࣌ أَفَلَا تَعْقِلُونَ࣌', 'يأهل ࡰلكتب لم تحاجون فے إبرهيم࣌ وما أنزلت ࡴلتورية والانجيل إلا من بعده࣌ أفلا تعقلون࣌', NULL, 58, 'local:warsh-text.json'),
  ('warsh-3-65', 'warsh', 3, 65, 'هَآنتُمْ هَٰٓؤُلَآءِ حَٰجَجْتُمْ فِيمَا لَكُم بِهِۦ عِلْمࣱ فَلِمَ تُحَآجُّونَ فِيمَا لَيْسَ لَكُم بِهِۦ عِلْمࣱ࣌ وَاللَّهُ يَعْلَمُ࣌ وَأَنتُمْ لَا تَعْلَمُونَ࣌', 'هانتم هؤلاء حججتم فيما لكم به علم فلم تحاجون فيما ليس لكم به علم࣌ والله يعلم࣌ وأنتم لا تعلمون࣌', NULL, 58, 'local:warsh-text.json'),
  ('warsh-3-66', 'warsh', 3, 66, 'مَا كَانَ إِبْرَٰهِيمُ يَهُودِيّاࣰ وَلَا نَصْرَانِيّاࣰ وَلَٰكِن كَانَ حَنِيفاࣰ مُّسْلِماࣰ࣌ وَمَا كَانَ مِنَ ࡰ۬لْمُشْرِكِينَ࣌', 'ما كان إبرهيم يهوديا ولا نصرانيا ولكن كان حنيفا مسلما࣌ وما كان من ࡰلمشركين࣌', NULL, 58, 'local:warsh-text.json'),
  ('warsh-3-67', 'warsh', 3, 67, 'إِنَّ أَوْلَى ࡰ۬لنَّاسِ بِإِبْرَٰهِيمَ لَلذِينَ ࡰٜتَّبَعُوهُ وَهَٰذَا ࡰ۬لنَّبِےٓءُ وَالذِينَ ءَامَنُواْ࣌ وَاللَّهُ وَلِيُّ ࡲ۬لْمُومِنِينَ࣌', 'إن أولى ࡰلناس بإبرهيم للذين ࡰتبعوه وهذا ࡰلنبےء والذين ءامنوا࣌ والله ولي ࡲلمومنين࣌', NULL, 58, 'local:warsh-text.json'),
  ('warsh-3-68', 'warsh', 3, 68, 'وَدَّت طَّآئِفَةࣱ مِّنَ ࡰهْلِ ࡴ۬لْكِتَٰبِ لَوْ يُضِلُّونَكُمْ࣌ وَمَا يُضِلُّونَ إِلَّآ أَنفُسَهُمْ وَمَا يَشْعُرُونَ࣌', 'ودت طائفة من ࡰهل ࡴلكتب لو يضلونكم࣌ وما يضلون إلا أنفسهم وما يشعرون࣌', NULL, 58, 'local:warsh-text.json'),
  ('warsh-3-69', 'warsh', 3, 69, 'يَٰٓأَهْلَ ࡰ۬لْكِتَٰبِ لِمَ تَكْفُرُونَ بِـَٔايَٰتِ ࡴ۬للَّهِ وَأَنتُمْ تَشْهَدُونَ࣌', 'يأهل ࡰلكتب لم تكفرون بايت ࡴلله وأنتم تشهدون࣌', NULL, 58, 'local:warsh-text.json'),
  ('warsh-3-70', 'warsh', 3, 70, 'يَٰٓأَهْلَ ࡰ۬لْكِتَٰبِ لِمَ تَلْبِسُونَ ࡰ۬لْحَقَّ بِالْبَٰطِلِ وَتَكْتُمُونَ ࡰ۬لْحَقَّ وَأَنتُمْ تَعْلَمُونَ࣌', 'يأهل ࡰلكتب لم تلبسون ࡰلحق بالبطل وتكتمون ࡰلحق وأنتم تعلمون࣌', NULL, 59, 'local:warsh-text.json'),
  ('warsh-3-71', 'warsh', 3, 71, 'وَقَالَت طَّآئِفَةࣱ مِّنَ ࡰهْلِ ࡴ۬لْكِتَٰبِ ءَامِنُواْ بِالذِےٓ أُنزِلَ عَلَى ࡰ۬لذِينَ ءَامَنُواْ وَجْهَ ࡰ۬لنَّهٜارِ وَاكْفُرُوٓاْ ءَاخِرَهُۥ لَعَلَّهُمْ يَرْجِعُونَ࣌', 'وقالت طائفة من ࡰهل ࡴلكتب ءامنوا بالذے أنزل على ࡰلذين ءامنوا وجه ࡰلنهار واكفروا ءاخره لعلهم يرجعون࣌', NULL, 59, 'local:warsh-text.json'),
  ('warsh-3-72', 'warsh', 3, 72, 'وَلَا تُومِنُوٓاْ إِلَّا لِمَن تَبِعَ دِينَكُمْ࣌ قُلِ ࡴنَّ ࡰ۬لْهُدٜىٰ هُدَى ࡰ۬للَّهِ أَنْ يُّوتٜىٰٓ أَحَدࣱ مِّثْلَ مَآ أُوتِيتُمُۥٓ أَوْ يُحَآجُّوكُمْ عِندَ رَبِّكُمْ࣌ قُلِ ࡴنَّ ࡰ۬لْفَضْلَ بِيَدِ ࡴ۬للَّهِ࣌ يُوتِيهِ مَنْ يَّشَآءُ࣌ وَاللَّهُ وَٰسِعٌ عَلِيمࣱ࣌', 'ولا تومنوا إلا لمن تبع دينكم࣌ قل ࡴن ࡰلهدى هدى ࡰلله أن يوتى أحد مثل ما أوتيتم أو يحاجوكم عند ربكم࣌ قل ࡴن ࡰلفضل بيد ࡴلله࣌ يوتيه من يشاء࣌ والله وسع عليم࣌', NULL, 59, 'local:warsh-text.json'),
  ('warsh-3-73', 'warsh', 3, 73, 'يَخْتَصُّ بِرَحْمَتِهِۦ مَنْ يَّشَآءُ࣌ وَاللَّهُ ذُو ࡲ۬لْفَضْلِ ࡴ۬لْعَظِيمِ࣌', 'يختص برحمته من يشاء࣌ والله ذو ࡲلفضل ࡴلعظيم࣌', NULL, 59, 'local:warsh-text.json'),
  ('warsh-3-74', 'warsh', 3, 74, '۞ وَمِنَ ࡰهْلِ ࡴ۬لْكِتَٰبِ مَنِ ࡴن تَامَنْهُ بِقِنطٜارࣲ يُوَ۬دِّهِۦٓ إِلَيْكَ࣌ وَمِنْهُم مَّنِ ࡴن تَامَنْهُ بِدِينٜارࣲ لَّا يُوَ۬دِّهِۦٓ إِلَيْكَ إِلَّا مَا دُمْتَ عَلَيْهِ قَآئِماࣰ࣌ ذَٰلِكَ بِأَنَّهُمْ قَالُواْ لَيْسَ عَلَيْنَا فِے ࡴ۬لُامِّيِّۑنَ سَبِيلࣱ࣌ وَيَقُولُونَ عَلَى ࡰ۬للَّهِ ࡴ۬لْكَذِبَ وَهُمْ يَعْلَمُونَ࣌', 'ومن ࡰهل ࡴلكتب من ࡴن تامنه بقنطار يوده إليك࣌ ومنهم من ࡴن تامنه بدينار لا يوده إليك إلا ما دمت عليه قائما࣌ ذلك بأنهم قالوا ليس علينا فے ࡴلاميۑن سبيل࣌ ويقولون على ࡰلله ࡴلكذب وهم يعلمون࣌', NULL, 59, 'local:warsh-text.json'),
  ('warsh-3-75', 'warsh', 3, 75, 'بَلٜىٰ مَنَ ࡰوْفٜىٰ بِعَهْدِهِۦ وَاتَّقٜىٰ فَإِنَّ ࡰ۬للَّهَ يُحِبُّ ࡲ۬لْمُتَّقِينَ࣌', 'بلى من ࡰوفى بعهده واتقى فإن ࡰلله يحب ࡲلمتقين࣌', NULL, 59, 'local:warsh-text.json'),
  ('warsh-3-76', 'warsh', 3, 76, 'إِنَّ ࡰ۬لذِينَ يَشْتَرُونَ بِعَهْدِ ࡴ۬للَّهِ وَأَيْمَٰنِهِمْ ثَمَناࣰ قَلِيلاً ࡳوْلَٰٓئِكَ لَا خَلَٰقَ لَهُمْ فِے ࡴ۬لَاخِرَةِ وَلَا يُكَلِّمُهُمُ ࡲ۬للَّهُ وَلَا يَنظُرُ إِلَيْهِمْ يَوْمَ ࡰ۬لْقِيَٰمَةِ وَلَا يُزَكِّيهِمْ࣌ وَلَهُمْ عَذَابٌ ࡰلِيمࣱ࣌', 'إن ࡰلذين يشترون بعهد ࡴلله وأيمنهم ثمنا قليلا ࡳولئك لا خلق لهم فے ࡴلاخرة ولا يكلمهم ࡲلله ولا ينظر إليهم يوم ࡰلقيمة ولا يزكيهم࣌ ولهم عذاب ࡰليم࣌', NULL, 59, 'local:warsh-text.json'),
  ('warsh-3-77', 'warsh', 3, 77, 'وَإِنَّ مِنْهُمْ لَفَرِيقاࣰ يَلْوُۥنَ أَلْسِنَتَهُم بِالْكِتَٰبِ لِتَحْسِبُوهُ مِنَ ࡰ۬لْكِتَٰبِ وَمَا هُوَ مِنَ ࡰ۬لْكِتَٰبِ࣌ وَيَقُولُونَ هُوَ مِنْ عِندِ ࡴ۬للَّهِ࣌ وَمَا هُوَ مِنْ عِندِ ࡴ۬للَّهِ࣌ وَيَقُولُونَ عَلَى ࡰ۬للَّهِ ࡴ۬لْكَذِبَ وَهُمْ يَعْلَمُونَ࣌', 'وإن منهم لفريقا يلون ألسنتهم بالكتب لتحسبوه من ࡰلكتب وما هو من ࡰلكتب࣌ ويقولون هو من عند ࡴلله࣌ وما هو من عند ࡴلله࣌ ويقولون على ࡰلله ࡴلكذب وهم يعلمون࣌', NULL, 60, 'local:warsh-text.json'),
  ('warsh-3-78', 'warsh', 3, 78, 'مَا كَانَ لِبَشَرٍ ࡰنْ يُّوتِيَهُ ࡲ۬للَّهُ ࡲ۬لْكِتَٰبَ وَالْحُكْمَ وَالنُّبُوٓءَةَ ثُمَّ يَقُولَ لِلنَّاسِ كُونُواْ عِبَاداࣰ لِّے مِن دُونِ ࡴ۬للَّهِ وَلَٰكِن كُونُواْ رَبَّٰنِيِّۑنَ بِمَا كُنتُمْ تَعْلَمُونَ ࡰ۬لْكِتَٰبَ وَبِمَا كُنتُمْ تَدْرُسُونَ࣌', 'ما كان لبشر ࡰن يوتيه ࡲلله ࡲلكتب والحكم والنبوءة ثم يقول للناس كونوا عبادا لے من دون ࡴلله ولكن كونوا ربنيۑن بما كنتم تعلمون ࡰلكتب وبما كنتم تدرسون࣌', NULL, 60, 'local:warsh-text.json'),
  ('warsh-3-79', 'warsh', 3, 79, 'وَلَا يَامُرُكُمُۥٓ أَن تَتَّخِذُواْ ࡲ۬لْمَلَٰٓئِكَةَ وَالنَّبِيٓـِٕۑنَ أَرْبَاباً࣌ ࡰيَامُرُكُم بِالْكُفْرِ بَعْدَ إِذَ ࡰنتُم مُّسْلِمُونَ࣌', 'ولا يامركم أن تتخذوا ࡲلملئكة والنبيۑن أربابا࣌ ࡰيامركم بالكفر بعد إذ ࡰنتم مسلمون࣌', NULL, 60, 'local:warsh-text.json'),
  ('warsh-3-80', 'warsh', 3, 80, 'وَإِذَ ࡰخَذَ ࡰ۬للَّهُ مِيثَٰقَ ࡰ۬لنَّبِيٓـِٕۑنَ لَمَآ ءَاتَيْنَٰكُم مِّن كِتَٰبࣲ وَحِكْمَةࣲ ثُمَّ جَآءَكُمْ رَسُولࣱ مُّصَدِّقࣱ لِّمَا مَعَكُمْ لَتُومِنُنَّ بِهِۦ وَلَتَنصُرُنَّهُۥ࣌ ۞ قَالَ ءَآقْرَرْتُمْ وَأَخَذتُّمْ عَلَىٰ ذَٰلِكُمُۥٓ إِصْرِے࣌ قَالُوٓاْ أَقْرَرْنَا࣌ قَالَ فَاشْهَدُواْ وَأَنَا مَعَكُم مِّنَ ࡰ۬لشَّٰهِدِينَ࣌', 'وإذ ࡰخذ ࡰلله ميثق ࡰلنبيۑن لما ءاتينكم من كتب وحكمة ثم جاءكم رسول مصدق لما معكم لتومنن به ولتنصرنه࣌  قال ءاقررتم وأخذتم على ذلكم إصرے࣌ قالوا أقررنا࣌ قال فاشهدوا وأنا معكم من ࡰلشهدين࣌', NULL, 60, 'local:warsh-text.json'),
  ('warsh-3-81', 'warsh', 3, 81, 'فَمَن تَوَلّٜىٰ بَعْدَ ذَٰلِكَ فَأُوْلَٰٓئِكَ هُمُ ࡲ۬لْفَٰسِقُونَ࣌', 'فمن تولى بعد ذلك فأولئك هم ࡲلفسقون࣌', NULL, 60, 'local:warsh-text.json'),
  ('warsh-3-82', 'warsh', 3, 82, 'أَفَغَيْرَ دِينِ ࡴ۬للَّهِ تَبْغُونَ وَلَهُۥٓ أَسْلَمَ مَن فِے ࡴ۬لسَّمَٰوَٰتِ وَالَارْضِ طَوْعاࣰ وَكَرْهاࣰ࣌ وَإِلَيْهِ تُرْجَعُونَ࣌', 'أفغير دين ࡴلله تبغون وله أسلم من فے ࡴلسموت والارض طوعا وكرها࣌ وإليه ترجعون࣌', NULL, 60, 'local:warsh-text.json'),
  ('warsh-3-83', 'warsh', 3, 83, 'قُلَ اٰمَنَّا بِاللَّهِ وَمَآ أُنزِلَ عَلَيْنَا وَمَآ أُنزِلَ عَلَىٰٓ إِبْرَٰهِيمَ وَإِسْمَٰعِيلَ وَإِسْحَٰقَ وَيَعْقُوبَ وَالَاسْبَاطِ وَمَآ أُوتِيَ مُوسٜىٰ وَعِيسٜىٰ وَالنَّبِيٓـُٔونَ مِن رَّبِّهِمْ لَا نُفَرِّقُ بَيْنَ أَحَدࣲ مِّنْهُمْ وَنَحْنُ لَهُۥ مُسْلِمُونَ࣌', 'قل امنا بالله وما أنزل علينا وما أنزل على إبرهيم وإسمعيل وإسحق ويعقوب والاسباط وما أوتي موسى وعيسى والنبيون من ربهم لا نفرق بين أحد منهم ونحن له مسلمون࣌', NULL, 61, 'local:warsh-text.json'),
  ('warsh-3-84', 'warsh', 3, 84, 'وَمَنْ يَّبْتَغِ غَيْرَ ࡰ۬لِاسْلَٰمِ دِيناࣰ فَلَنْ يُّقْبَلَ مِنْهُ࣌ وَهُوَ فِے ࡴ۬لَاخِرَةِ مِنَ ࡰ۬لْخَٰسِرِينَ࣌', 'ومن يبتغ غير ࡰلاسلم دينا فلن يقبل منه࣌ وهو فے ࡴلاخرة من ࡰلخسرين࣌', NULL, 61, 'local:warsh-text.json'),
  ('warsh-3-85', 'warsh', 3, 85, 'كَيْفَ يَهْدِے ࡴ۬للَّهُ قَوْماࣰ كَفَرُواْ بَعْدَ إِيمَٰنِهِمْ وَشَهِدُوٓاْ أَنَّ ࡰ۬لرَّسُولَ حَقࣱّ وَجَآءَهُمُ ࡲ۬لْبَيِّنَٰتُ࣌ وَاللَّهُ لَا يَهْدِے ࡴ۬لْقَوْمَ ࡰ۬لظَّٰلِمِينَ࣌', 'كيف يهدے ࡴلله قوما كفروا بعد إيمنهم وشهدوا أن ࡰلرسول حق وجاءهم ࡲلبينت࣌ والله لا يهدے ࡴلقوم ࡰلظلمين࣌', NULL, 61, 'local:warsh-text.json'),
  ('warsh-3-86', 'warsh', 3, 86, 'أُوْلَٰٓئِكَ جَزَآؤُهُمُۥٓ أَنَّ عَلَيْهِمْ لَعْنَةَ ࡰ۬للَّهِ وَالْمَلَٰٓئِكَةِ وَالنَّاسِ أَجْمَعِينَ', 'أولئك جزاؤهم أن عليهم لعنة ࡰلله والملئكة والناس أجمعين', NULL, 61, 'local:warsh-text.json'),
  ('warsh-3-87', 'warsh', 3, 87, 'خَٰلِدِينَ فِيهَا لَا يُخَفَّفُ عَنْهُمُ ࡲ۬لْعَذَابُ وَلَا هُمْ يُنظَرُونَ', 'خلدين فيها لا يخفف عنهم ࡲلعذاب ولا هم ينظرون', NULL, 61, 'local:warsh-text.json'),
  ('warsh-3-88', 'warsh', 3, 88, 'إِلَّا ࡰ۬لذِينَ تَابُواْ مِنۢ بَعْدِ ذَٰلِكَ وَأَصْلَحُواْ فَإِنَّ ࡰ۬للَّهَ غَفُورࣱ رَّحِيمٌ࣌', 'إلا ࡰلذين تابوا من بعد ذلك وأصلحوا فإن ࡰلله غفور رحيم࣌', NULL, 61, 'local:warsh-text.json'),
  ('warsh-3-89', 'warsh', 3, 89, 'ࡴنَّ ࡰ۬لذِينَ كَفَرُواْ بَعْدَ إِيمَٰنِهِمْ ثُمَّ ࡰٜزْدَادُواْ كُفْراࣰ لَّن تُقْبَلَ تَوْبَتُهُمْ࣌ وَأُوْلَٰٓئِكَ هُمُ ࡲ۬لضَّآلُّونَ࣌', 'ࡴن ࡰلذين كفروا بعد إيمنهم ثم ࡰزدادوا كفرا لن تقبل توبتهم࣌ وأولئك هم ࡲلضالون࣌', NULL, 61, 'local:warsh-text.json'),
  ('warsh-3-90', 'warsh', 3, 90, 'إِنَّ ࡰ۬لذِينَ كَفَرُواْ وَمَاتُواْ وَهُمْ كُفَّارࣱ فَلَنْ يُّقْبَلَ مِنَ ࡰحَدِهِم مِّلْءُ ࡲ۬لَارْضِ ذَهَباࣰ وَلَوِ ࡴٜفْتَدٜىٰ بِهِۦٓ࣌ أُوْلَٰٓئِكَ لَهُمْ عَذَابٌ ࡰلِيمࣱ࣌ وَمَا لَهُم مِّن نَّٰصِرِينَ࣌', 'إن ࡰلذين كفروا وماتوا وهم كفار فلن يقبل من ࡰحدهم ملء ࡲلارض ذهبا ولو ࡴفتدى به࣌ أولئك لهم عذاب ࡰليم࣌ وما لهم من نصرين࣌', NULL, 61, 'local:warsh-text.json'),
  ('warsh-3-91', 'warsh', 3, 91, '۞ لَن تَنَالُواْ ࡲ۬لْبِرَّ حَتَّىٰ تُنفِقُواْ مِمَّا تُحِبُّونَ࣌', 'لن تنالوا ࡲلبر حتى تنفقوا مما تحبون࣌', NULL, 62, 'local:warsh-text.json'),
  ('warsh-3-92', 'warsh', 3, 92, 'وَمَا تُنفِقُواْ مِن شَےْءࣲ فَإِنَّ ࡰ۬للَّهَ بِهِۦ عَلِيمࣱ࣌', 'وما تنفقوا من شےء فإن ࡰلله به عليم࣌', NULL, 62, 'local:warsh-text.json'),
  ('warsh-3-93', 'warsh', 3, 93, 'كُلُّ ࡲ۬لطَّعَامِ كَانَ حِلّاࣰ لِّبَنِےٓ إِسْرَآءِيلَ إِلَّا مَا حَرَّمَ إِسْرَآءِيلُ عَلَىٰ نَفْسِهِۦ مِن قَبْلِ أَن تُنَزَّلَ ࡰ۬لتَّوْرٜيٰةُ࣌ قُلْ فَاتُواْ بِالتَّوْرٜيٰةِ فَاتْلُوهَآ إِن كُنتُمْ صَٰدِقِينَ࣌', 'كل ࡲلطعام كان حلا لبنے إسراءيل إلا ما حرم إسراءيل على نفسه من قبل أن تنزل ࡰلتورية࣌ قل فاتوا بالتورية فاتلوها إن كنتم صدقين࣌', NULL, 62, 'local:warsh-text.json'),
  ('warsh-3-94', 'warsh', 3, 94, 'فَمَنِ ࡴٜفْتَرٜىٰ عَلَى ࡰ۬للَّهِ ࡴ۬لْكَذِبَ مِنۢ بَعْدِ ذَٰلِكَ فَأُوْلَٰٓئِكَ هُمُ ࡲ۬لظَّٰلِمُونَ࣌', 'فمن ࡴفترى على ࡰلله ࡴلكذب من بعد ذلك فأولئك هم ࡲلظلمون࣌', NULL, 62, 'local:warsh-text.json'),
  ('warsh-3-95', 'warsh', 3, 95, 'قُلْ صَدَقَ ࡰ۬للَّهُ࣌ فَاتَّبِعُواْ مِلَّةَ إِبْرَٰهِيمَ حَنِيفاࣰ࣌ وَمَا كَانَ مِنَ ࡰ۬لْمُشْرِكِينَ࣌', 'قل صدق ࡰلله࣌ فاتبعوا ملة إبرهيم حنيفا࣌ وما كان من ࡰلمشركين࣌', NULL, 62, 'local:warsh-text.json'),
  ('warsh-3-96', 'warsh', 3, 96, 'إِنَّ أَوَّلَ بَيْتࣲ وُضِعَ لِلنَّاسِ لَلذِے بِبَكَّةَ مُبَٰرَكاࣰ وَهُدىࣰ لِّلْعَٰلَمِينَ', 'إن أول بيت وضع للناس للذے ببكة مبركا وهدى للعلمين', NULL, 62, 'local:warsh-text.json'),
  ('warsh-3-97', 'warsh', 3, 97, 'فِيهِ ءَايَٰتُۢ بَيِّنَٰتࣱ࣌ مَّقَامُ إِبْرَٰهِيمَ࣌ وَمَن دَخَلَهُۥ كَانَ ءَامِناࣰ࣌ وَلِلهِ عَلَى ࡰ۬لنَّاسِ حَجُّ ࡲ۬لْبَيْتِ مَنِ ࡴٜسْتَطَاعَ إِلَيْهِ سَبِيلاࣰ࣌ وَمَن كَفَرَ فَإِنَّ ࡰ۬للَّهَ غَنِيٌّ عَنِ ࡴ۬لْعَٰلَمِينَ࣌', 'فيه ءايت بينت࣌ مقام إبرهيم࣌ ومن دخله كان ءامنا࣌ ولله على ࡰلناس حج ࡲلبيت من ࡴستطاع إليه سبيلا࣌ ومن كفر فإن ࡰلله غني عن ࡴلعلمين࣌', NULL, 62, 'local:warsh-text.json'),
  ('warsh-3-98', 'warsh', 3, 98, 'قُلْ يَٰٓأَهْلَ ࡰ۬لْكِتَٰبِ لِمَ تَكْفُرُونَ بِـَٔايَٰتِ ࡴ۬للَّهِ وَاللَّهُ شَهِيدٌ عَلَىٰ مَا تَعْمَلُونَ࣌', 'قل يأهل ࡰلكتب لم تكفرون بايت ࡴلله والله شهيد على ما تعملون࣌', NULL, 62, 'local:warsh-text.json'),
  ('warsh-3-99', 'warsh', 3, 99, 'قُلْ يَٰٓأَهْلَ ࡰ۬لْكِتَٰبِ لِمَ تَصُدُّونَ عَن سَبِيلِ ࡴ۬للَّهِ مَنَ اٰمَنَ تَبْغُونَهَا عِوَجاࣰ وَأَنتُمْ شُهَدَآءُ࣌ وَمَا ࡰ۬للَّهُ بِغَٰفِلٍ عَمَّا تَعْمَلُونَ࣌', 'قل يأهل ࡰلكتب لم تصدون عن سبيل ࡴلله من امن تبغونها عوجا وأنتم شهداء࣌ وما ࡰلله بغفل عما تعملون࣌', NULL, 62, 'local:warsh-text.json'),
  ('warsh-3-100', 'warsh', 3, 100, 'يَٰٓأَيُّهَا ࡰ۬لذِينَ ءَامَنُوٓاْ إِن تُطِيعُواْ فَرِيقاࣰ مِّنَ ࡰ۬لذِينَ أُوتُواْ ࡲ۬لْكِتَٰبَ يَرُدُّوكُم بَعْدَ إِيمَٰنِكُمْ كٜـٰفِرِينَ࣌', 'يأيها ࡰلذين ءامنوا إن تطيعوا فريقا من ࡰلذين أوتوا ࡲلكتب يردوكم بعد إيمنكم كفرين࣌', NULL, 62, 'local:warsh-text.json'),
  ('warsh-3-101', 'warsh', 3, 101, 'وَكَيْفَ تَكْفُرُونَ وَأَنتُمْ تُتْلٜىٰ عَلَيْكُمُۥٓ ءَايَٰتُ ࡲ۬للَّهِ وَفِيكُمْ رَسُولُهُۥ࣌ وَمَنْ يَّعْتَصِم بِاللَّهِ فَقَدْ هُدِيَ إِلَىٰ صِرَٰطࣲ مُّسْتَقِيمࣲ࣌', 'وكيف تكفرون وأنتم تتلى عليكم ءايت ࡲلله وفيكم رسوله࣌ ومن يعتصم بالله فقد هدي إلى صرط مستقيم࣌', NULL, 63, 'local:warsh-text.json'),
  ('warsh-3-102', 'warsh', 3, 102, 'يَٰٓأَيُّهَا ࡰ۬لذِينَ ءَامَنُواْ ࡲٜتَّقُواْ ࡲ۬للَّهَ حَقَّ تُقٜاتِهِۦ࣌ وَلَا تَمُوتُنَّ إِلَّا وَأَنتُم مُّسْلِمُونَ࣌', 'يأيها ࡰلذين ءامنوا ࡲتقوا ࡲلله حق تقاته࣌ ولا تموتن إلا وأنتم مسلمون࣌', NULL, 63, 'local:warsh-text.json'),
  ('warsh-3-103', 'warsh', 3, 103, '۞ وَاعْتَصِمُواْ بِحَبْلِ ࡴ۬للَّهِ جَمِيعاࣰ࣌ وَلَا تَفَرَّقُواْ࣌ وَاذْكُرُواْ نِعْمَتَ ࡰ۬للَّهِ عَلَيْكُمُۥٓ إِذْ كُنتُمُۥٓ أَعْدَآءࣰ فَأَلَّفَ بَيْنَ قُلُوبِكُمْ فَأَصْبَحْتُم بِنِعْمَتِهِۦٓ إِخْوَٰناࣰ࣌ وَكُنتُمْ عَلَىٰ شَفَا حُفْرَةࣲ مِّنَ ࡰ۬لنّٜارِ فَأَنقَذَكُم مِّنْهَا࣌ كَذَٰلِكَ يُبَيِّنُ ࡲ۬للَّهُ لَكُمُۥٓ ءَايَٰتِهِۦ لَعَلَّكُمْ تَهْتَدُونَ࣌', 'واعتصموا بحبل ࡴلله جميعا࣌ ولا تفرقوا࣌ واذكروا نعمت ࡰلله عليكم إذ كنتم أعداء فألف بين قلوبكم فأصبحتم بنعمته إخونا࣌ وكنتم على شفا حفرة من ࡰلنار فأنقذكم منها࣌ كذلك يبين ࡲلله لكم ءايته لعلكم تهتدون࣌', NULL, 63, 'local:warsh-text.json'),
  ('warsh-3-104', 'warsh', 3, 104, 'وَلْتَكُن مِّنكُمُۥٓ أُمَّةࣱ يَدْعُونَ إِلَى ࡰ۬لْخَيْرِ وَيَامُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ ࡴ۬لْمُنكَرِ࣌ وَأُوْلَٰٓئِكَ هُمُ ࡲ۬لْمُفْلِحُونَ࣌', 'ولتكن منكم أمة يدعون إلى ࡰلخير ويامرون بالمعروف وينهون عن ࡴلمنكر࣌ وأولئك هم ࡲلمفلحون࣌', NULL, 63, 'local:warsh-text.json'),
  ('warsh-3-105', 'warsh', 3, 105, 'وَلَا تَكُونُواْ كَالذِينَ تَفَرَّقُواْ وَاخْتَلَفُواْ مِنۢ بَعْدِ مَا جَآءَهُمُ ࡲ۬لْبَيِّنَٰتُ࣌ وَأُوْلَٰٓئِكَ لَهُمْ عَذَابٌ عَظِيمࣱ', 'ولا تكونوا كالذين تفرقوا واختلفوا من بعد ما جاءهم ࡲلبينت࣌ وأولئك لهم عذاب عظيم', NULL, 63, 'local:warsh-text.json'),
  ('warsh-3-106', 'warsh', 3, 106, 'يَوْمَ تَبْيَضُّ وُجُوهࣱ وَتَسْوَدُّ وُجُوهࣱ࣌ فَأَمَّا ࡰ۬لذِينَ ࡰٜسْوَدَّتْ وُجُوهُهُمُۥٓ أَكَفَرْتُم بَعْدَ إِيمَٰنِكُمْ فَذُوقُواْ ࡲ۬لْعَذَابَ بِمَا كُنتُمْ تَكْفُرُونَ࣌', 'يوم تبيض وجوه وتسود وجوه࣌ فأما ࡰلذين ࡰسودت وجوههم أكفرتم بعد إيمنكم فذوقوا ࡲلعذاب بما كنتم تكفرون࣌', NULL, 63, 'local:warsh-text.json'),
  ('warsh-3-107', 'warsh', 3, 107, 'وَأَمَّا ࡰ۬لذِينَ ࡰٜبْيَضَّتْ وُجُوهُهُمْ فَفِے رَحْمَةِ ࡴ۬للَّهِ࣌ هُمْ فِيهَا خَٰلِدُونَ࣌', 'وأما ࡰلذين ࡰبيضت وجوههم ففے رحمة ࡴلله࣌ هم فيها خلدون࣌', NULL, 63, 'local:warsh-text.json'),
  ('warsh-3-108', 'warsh', 3, 108, 'تِلْكَ ءَايَٰتُ ࡲ۬للَّهِ نَتْلُوهَا عَلَيْكَ بِالْحَقِّ࣌ وَمَا ࡰ۬للَّهُ يُرِيدُ ظُلْماࣰ لِّلْعَٰلَمِينَ࣌', 'تلك ءايت ࡲلله نتلوها عليك بالحق࣌ وما ࡰلله يريد ظلما للعلمين࣌', NULL, 63, 'local:warsh-text.json')
insert into public.ayahs (id, riwayah, surah_number, ayah_number, text, simple_text, juz, page, source) values
  ('warsh-3-109', 'warsh', 3, 109, 'وَلِلهِ مَا فِے ࡴ۬لسَّمَٰوَٰتِ وَمَا فِے ࡴ۬لَارْضِ࣌ وَإِلَى ࡰ۬للَّهِ تُرْجَعُ ࡲ۬لُامُورُ࣌', 'ولله ما فے ࡴلسموت وما فے ࡴلارض࣌ وإلى ࡰلله ترجع ࡲلامور࣌', NULL, 64, 'local:warsh-text.json'),
  ('warsh-3-110', 'warsh', 3, 110, 'كُنتُمْ خَيْرَ أُمَّةٍ ࡳخْرِجَتْ لِلنَّاسِ تَامُرُونَ بِالْمَعْرُوفِ وَتَنْهَوْنَ عَنِ ࡴ۬لْمُنكَرِ وَتُومِنُونَ بِاللَّهِ࣌ وَلَوَ اٰمَنَ أَهْلُ ࡲ۬لْكِتَٰبِ لَكَانَ خَيْراࣰ لَّهُم࣌ مِّنْهُمُ ࡲ۬لْمُومِنُونَ࣌ وَأَكْثَرُهُمُ ࡲ۬لْفَٰسِقُونَ࣌', 'كنتم خير أمة ࡳخرجت للناس تامرون بالمعروف وتنهون عن ࡴلمنكر وتومنون بالله࣌ ولو امن أهل ࡲلكتب لكان خيرا لهم࣌ منهم ࡲلمومنون࣌ وأكثرهم ࡲلفسقون࣌', NULL, 64, 'local:warsh-text.json'),
  ('warsh-3-111', 'warsh', 3, 111, 'لَنْ يَّضُرُّوكُمُۥٓ࣌ إِلَّآ أَذىࣰ࣌ وَإِنْ يُّقَٰتِلُوكُمْ يُوَلُّوكُمُ ࡲ۬لَادْبَٰرَ࣌ ثُمَّ لَا يُنصَرُونَ࣌', 'لن يضروكم࣌ إلا أذى࣌ وإن يقتلوكم يولوكم ࡲلادبر࣌ ثم لا ينصرون࣌', NULL, 64, 'local:warsh-text.json'),
  ('warsh-3-112', 'warsh', 3, 112, 'ضُرِبَتْ عَلَيْهِمُ ࡲ۬لذِّلَّةُ أَيْنَ مَا ثُقِفُوٓاْ࣌ إِلَّا بِحَبْلࣲ مِّنَ ࡰ۬للَّهِ وَحَبْلࣲ مِّنَ ࡰ۬لنَّاسِ وَبَآءُو بِغَضَبࣲ مِّنَ ࡰ۬للَّهِ࣌ وَضُرِبَتْ عَلَيْهِمُ ࡲ۬لْمَسْكَنَةُ࣌ ذَٰلِكَ بِأَنَّهُمْ كَانُواْ يَكْفُرُونَ بِـَٔايَٰتِ ࡴ۬للَّهِ وَيَقْتُلُونَ ࡰ۬لَانۢبِئَآءَ بِغَيْرِ حَقࣲّ࣌ ذَٰلِكَ بِمَا عَصَواْ وَّكَانُواْ يَعْتَدُونَ࣌', 'ضربت عليهم ࡲلذلة أين ما ثقفوا࣌ إلا بحبل من ࡰلله وحبل من ࡰلناس وباءو بغضب من ࡰلله࣌ وضربت عليهم ࡲلمسكنة࣌ ذلك بأنهم كانوا يكفرون بايت ࡴلله ويقتلون ࡰلانبئاء بغير حق࣌ ذلك بما عصوا وكانوا يعتدون࣌', NULL, 64, 'local:warsh-text.json'),
  ('warsh-3-113', 'warsh', 3, 113, '۞ لَيْسُواْ سَوَآءࣰ࣌ مِّنَ ࡰهْلِ ࡴ۬لْكِتَٰبِ أُمَّةࣱ قَآئِمَةࣱ يَتْلُونَ ءَايَٰتِ ࡴ۬للَّهِ ءَانَآءَ ࡰ۬ليْلِ وَهُمْ يَسْجُدُونَ࣌', 'ليسوا سواء࣌ من ࡰهل ࡴلكتب أمة قائمة يتلون ءايت ࡴلله ءاناء ࡰليل وهم يسجدون࣌', NULL, 64, 'local:warsh-text.json'),
  ('warsh-3-114', 'warsh', 3, 114, 'يُومِنُونَ بِاللَّهِ وَالْيَوْمِ ࡴ۬لَاخِرِ وَيَامُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ ࡴ۬لْمُنكَرِ وَيُسَٰرِعُونَ فِے ࡴ۬لْخَيْرَٰتِ࣌ وَأُوْلَٰٓئِكَ مِنَ ࡰ۬لصَّٰلِحِينَ࣌', 'يومنون بالله واليوم ࡴلاخر ويامرون بالمعروف وينهون عن ࡴلمنكر ويسرعون فے ࡴلخيرت࣌ وأولئك من ࡰلصلحين࣌', NULL, 64, 'local:warsh-text.json'),
  ('warsh-3-115', 'warsh', 3, 115, 'وَمَا تَفْعَلُواْ مِنْ خَيْرࣲ فَلَن تُكْفَرُوهُ࣌ وَاللَّهُ عَلِيمُۢ بِالْمُتَّقِينَ࣌', 'وما تفعلوا من خير فلن تكفروه࣌ والله عليم بالمتقين࣌', NULL, 64, 'local:warsh-text.json'),
  ('warsh-3-116', 'warsh', 3, 116, 'إِنَّ ࡰ۬لذِينَ كَفَرُواْ لَن تُغْنِيَ عَنْهُمُۥٓ أَمْوَٰلُهُمْ وَلَآ أَوْلَٰدُهُم مِّنَ ࡰ۬للَّهِ شَيْـٔاࣰ࣌ وَأُوْلَٰٓئِكَ أَصْحَٰبُ ࡲ۬لنّٜارِ هُمْ فِيهَا خَٰلِدُونَ࣌', 'إن ࡰلذين كفروا لن تغني عنهم أمولهم ولا أولدهم من ࡰلله شيا࣌ وأولئك أصحب ࡲلنار هم فيها خلدون࣌', NULL, 65, 'local:warsh-text.json'),
  ('warsh-3-117', 'warsh', 3, 117, 'مَثَلُ مَا يُنفِقُونَ فِے هَٰذِهِ ࡴ۬لْحَيَوٰةِ ࡴ۬لدُّنْيٜا كَمَثَلِ رِيحࣲ فِيهَا صِرٌّ ࡰصَابَتْ حَرْثَ قَوْمࣲ ظَلَمُوٓاْ أَنفُسَهُمْ فَأَهْلَكَتْهُ࣌ وَمَا ظَلَمَهُمُ ࡲ۬للَّهُ࣌ وَلَٰكِنَ ࡰنفُسَهُمْ يَظْلِمُونَ࣌', 'مثل ما ينفقون فے هذه ࡴلحيوة ࡴلدنيا كمثل ريح فيها صر ࡰصابت حرث قوم ظلموا أنفسهم فأهلكته࣌ وما ظلمهم ࡲلله࣌ ولكن ࡰنفسهم يظلمون࣌', NULL, 65, 'local:warsh-text.json'),
  ('warsh-3-118', 'warsh', 3, 118, 'يَٰٓأَيُّهَا ࡰ۬لذِينَ ءَامَنُواْ لَا تَتَّخِذُواْ بِطَانَةࣰ مِّن دُونِكُمْ لَا يَالُونَكُمْ خَبَالاࣰ وَدُّواْ مَا عَنِتُّمْ࣌ قَدْ بَدَتِ ࡴ۬لْبَغْضَآءُ مِنَ ࡰفْوَٰهِهِمْ وَمَا تُخْفِے صُدُورُهُمُۥٓ أَكْبَرُ࣌ قَدْ بَيَّنَّا لَكُمُ ࡲ۬لَايَٰتِ إِن كُنتُمْ تَعْقِلُونَ࣌', 'يأيها ࡰلذين ءامنوا لا تتخذوا بطانة من دونكم لا يالونكم خبالا ودوا ما عنتم࣌ قد بدت ࡴلبغضاء من ࡰفوههم وما تخفے صدورهم أكبر࣌ قد بينا لكم ࡲلايت إن كنتم تعقلون࣌', NULL, 65, 'local:warsh-text.json'),
  ('warsh-3-119', 'warsh', 3, 119, 'هَآنتُمُۥٓ أُوْلَآءِ تُحِبُّونَهُمْ وَلَا يُحِبُّونَكُمْ وَتُومِنُونَ بِالْكِتَٰبِ كُلِّهِۦ࣌ وَإِذَا لَقُوكُمْ قَالُوٓاْ ءَامَنَّا࣌ وَإِذَا خَلَوْاْ عَضُّواْ عَلَيْكُمُ ࡲ۬لَانَامِلَ مِنَ ࡰ۬لْغَيْظِ࣌ قُلْ مُوتُواْ بِغَيْظِكُمُۥٓ࣌ إِنَّ ࡰ۬للَّهَ عَلِيمُۢ بِذَاتِ ࡴ۬لصُّدُورِ࣌', 'هانتم أولاء تحبونهم ولا يحبونكم وتومنون بالكتب كله࣌ وإذا لقوكم قالوا ءامنا࣌ وإذا خلوا عضوا عليكم ࡲلانامل من ࡰلغيظ࣌ قل موتوا بغيظكم࣌ إن ࡰلله عليم بذات ࡴلصدور࣌', NULL, 65, 'local:warsh-text.json'),
  ('warsh-3-120', 'warsh', 3, 120, 'إِن تَمْسَسْكُمْ حَسَنَةࣱ تَسُؤْهُمْ࣌ وَإِن تُصِبْكُمْ سَيِّئَةࣱ يَفْرَحُواْ بِهَا࣌ وَإِن تَصْبِرُواْ وَتَتَّقُواْ لَا يَضِرْكُمْ كَيْدُهُمْ شَيْـٔاً࣌ ࡴنَّ ࡰ۬للَّهَ بِمَا يَعْمَلُونَ مُحِيطࣱ࣌', 'إن تمسسكم حسنة تسؤهم࣌ وإن تصبكم سيئة يفرحوا بها࣌ وإن تصبروا وتتقوا لا يضركم كيدهم شيا࣌ ࡴن ࡰلله بما يعملون محيط࣌', NULL, 65, 'local:warsh-text.json'),
  ('warsh-3-121', 'warsh', 3, 121, '۞ وَإِذْ غَدَوْتَ مِنَ ࡰهْلِكَ تُبَوِّۓُ ࡲ۬لْمُومِنِينَ مَقَٰعِدَ لِلْقِتَالِ࣌ وَاللَّهُ سَمِيعٌ عَلِيمٌ࣌', 'وإذ غدوت من ࡰهلك تبوے ࡲلمومنين مقعد للقتال࣌ والله سميع عليم࣌', NULL, 65, 'local:warsh-text.json'),
  ('warsh-3-122', 'warsh', 3, 122, 'ࡴذْ هَمَّت طَّآئِفَتَٰنِ مِنكُمُۥٓ أَن تَفْشَلَا وَاللَّهُ وَلِيُّهُمَا࣌ وَعَلَى ࡰ۬للَّهِ فَلْيَتَوَكَّلِ ࡴ۬لْمُومِنُونَ࣌', 'ࡴذ همت طائفتن منكم أن تفشلا والله وليهما࣌ وعلى ࡰلله فليتوكل ࡴلمومنون࣌', NULL, 66, 'local:warsh-text.json'),
  ('warsh-3-123', 'warsh', 3, 123, 'وَلَقَدْ نَصَرَكُمُ ࡲ۬للَّهُ بِبَدْرࣲ وَأَنتُمُۥٓ أَذِلَّةࣱ࣌ فَاتَّقُواْ ࡲ۬للَّهَ لَعَلَّكُمْ تَشْكُرُونَ࣌', 'ولقد نصركم ࡲلله ببدر وأنتم أذلة࣌ فاتقوا ࡲلله لعلكم تشكرون࣌', NULL, 66, 'local:warsh-text.json'),
  ('warsh-3-124', 'warsh', 3, 124, 'إِذْ تَقُولُ لِلْمُومِنِينَ أَلَنْ يَّكْفِيَكُمُۥٓ أَنْ يُّمِدَّكُمْ رَبُّكُم بِثَلَٰثَةِ ءَالَٰفࣲ مِّنَ ࡰ۬لْمَلَٰٓئِكَةِ مُنزَلِينَ࣌', 'إذ تقول للمومنين ألن يكفيكم أن يمدكم ربكم بثلثة ءالف من ࡰلملئكة منزلين࣌', NULL, 66, 'local:warsh-text.json'),
  ('warsh-3-125', 'warsh', 3, 125, 'بَلٜىٰٓ إِن تَصْبِرُواْ وَتَتَّقُواْ وَيَاتُوكُم مِّن فَوْرِهِمْ هَٰذَا يُمْدِدْكُمْ رَبُّكُم بِخَمْسَةِ ءَالَٰفࣲ مِّنَ ࡰ۬لْمَلَٰٓئِكَةِ مُسَوَّمِينَ࣌', 'بلى إن تصبروا وتتقوا وياتوكم من فورهم هذا يمددكم ربكم بخمسة ءالف من ࡰلملئكة مسومين࣌', NULL, 66, 'local:warsh-text.json'),
  ('warsh-3-126', 'warsh', 3, 126, 'وَمَا جَعَلَهُ ࡲ۬للَّهُ إِلَّا بُشْرٜىٰ لَكُمْ وَلِتَطْمَئِنَّ قُلُوبُكُم بِهِۦ࣌ وَمَا ࡰ۬لنَّصْرُ إِلَّا مِنْ عِندِ ࡴ۬للَّهِ ࡴ۬لْعَزِيزِ ࡴ۬لْحَكِيمِ', 'وما جعله ࡲلله إلا بشرى لكم ولتطمئن قلوبكم به࣌ وما ࡰلنصر إلا من عند ࡴلله ࡴلعزيز ࡴلحكيم', NULL, 66, 'local:warsh-text.json'),
  ('warsh-3-127', 'warsh', 3, 127, 'لِيَقْطَعَ طَرَفاࣰ مِّنَ ࡰ۬لذِينَ كَفَرُوٓاْ أَوْ يَكْبِتَهُمْ فَيَنقَلِبُواْ خَآئِبِينَ', 'ليقطع طرفا من ࡰلذين كفروا أو يكبتهم فينقلبوا خائبين', NULL, 66, 'local:warsh-text.json'),
  ('warsh-3-128', 'warsh', 3, 128, 'لَيْسَ لَكَ مِنَ ࡰ۬لَامْرِ شَےْءٌ ࡰوْ يَتُوبَ عَلَيْهِمُۥٓ أَوْ يُعَذِّبَهُمْ فَإِنَّهُمْ ظَٰلِمُونَ࣌', 'ليس لك من ࡰلامر شےء ࡰو يتوب عليهم أو يعذبهم فإنهم ظلمون࣌', NULL, 66, 'local:warsh-text.json'),
  ('warsh-3-129', 'warsh', 3, 129, 'وَلِلهِ مَا فِے ࡴ۬لسَّمَٰوَٰتِ وَمَا فِے ࡴ۬لَارْضِ࣌ يَغْفِرُ لِمَنْ يَّشَآءُ وَيُعَذِّبُ مَنْ يَّشَآءُ࣌ وَاللَّهُ غَفُورࣱ رَّحِيمࣱ࣌', 'ولله ما فے ࡴلسموت وما فے ࡴلارض࣌ يغفر لمن يشاء ويعذب من يشاء࣌ والله غفور رحيم࣌', NULL, 66, 'local:warsh-text.json'),
  ('warsh-3-130', 'warsh', 3, 130, 'يَٰٓأَيُّهَا ࡰ۬لذِينَ ءَامَنُواْ لَا تَاكُلُواْ ࡲ۬لرِّبَوٰٓاْ أَضْعَٰفاࣰ مُّضَٰعَفَةࣰ࣌ وَاتَّقُواْ ࡲ۬للَّهَ لَعَلَّكُمْ تُفْلِحُونَ࣌', 'يأيها ࡰلذين ءامنوا لا تاكلوا ࡲلربوا أضعفا مضعفة࣌ واتقوا ࡲلله لعلكم تفلحون࣌', NULL, 66, 'local:warsh-text.json'),
  ('warsh-3-131', 'warsh', 3, 131, 'وَاتَّقُواْ ࡲ۬لنَّارَ ࡰ۬لتِےٓ أُعِدَّتْ لِلْكٜـٰفِرِينَ࣌', 'واتقوا ࡲلنار ࡰلتے أعدت للكفرين࣌', NULL, 66, 'local:warsh-text.json'),
  ('warsh-3-132', 'warsh', 3, 132, 'وَأَطِيعُواْ ࡲ۬للَّهَ وَالرَّسُولَ لَعَلَّكُمْ تُرْحَمُونَ࣌', 'وأطيعوا ࡲلله والرسول لعلكم ترحمون࣌', NULL, 66, 'local:warsh-text.json'),
  ('warsh-3-133', 'warsh', 3, 133, '۞ سَارِعُوٓاْ إِلَىٰ مَغْفِرَةࣲ مِّن رَّبِّكُمْ وَجَنَّةٍ عَرْضُهَا ࡰ۬لسَّمَٰوَٰتُ وَالَارْضُ أُعِدَّتْ لِلْمُتَّقِينَ', 'سارعوا إلى مغفرة من ربكم وجنة عرضها ࡰلسموت والارض أعدت للمتقين', NULL, 67, 'local:warsh-text.json'),
  ('warsh-3-134', 'warsh', 3, 134, 'ࡰ۬لذِينَ يُنفِقُونَ فِے ࡴ۬لسَّرَّآءِ وَالضَّرَّآءِ وَالْكَٰظِمِينَ ࡰ۬لْغَيْظَ وَالْعَافِينَ عَنِ ࡴ۬لنَّاسِ࣌ وَاللَّهُ يُحِبُّ ࡲ۬لْمُحْسِنِينَ࣌', 'ࡰلذين ينفقون فے ࡴلسراء والضراء والكظمين ࡰلغيظ والعافين عن ࡴلناس࣌ والله يحب ࡲلمحسنين࣌', NULL, 67, 'local:warsh-text.json'),
  ('warsh-3-135', 'warsh', 3, 135, 'وَالذِينَ إِذَا فَعَلُواْ فَٰحِشَةً ࡰوْ ظَلَمُوٓاْ أَنفُسَهُمْ ذَكَرُواْ ࡲ۬للَّهَ فَاسْتَغْفَرُواْ لِذُنُوبِهِمْ࣌ وَمَنْ يَّغْفِرُ ࡲ۬لذُّنُوبَ إِلَّا ࡰ۬للَّهُ࣌ وَلَمْ يُصِرُّواْ عَلَىٰ مَا فَعَلُواْ وَهُمْ يَعْلَمُونَ࣌', 'والذين إذا فعلوا فحشة ࡰو ظلموا أنفسهم ذكروا ࡲلله فاستغفروا لذنوبهم࣌ ومن يغفر ࡲلذنوب إلا ࡰلله࣌ ولم يصروا على ما فعلوا وهم يعلمون࣌', NULL, 67, 'local:warsh-text.json'),
  ('warsh-3-136', 'warsh', 3, 136, 'أُوْلَٰٓئِكَ جَزَآؤُهُم مَّغْفِرَةࣱ مِّن رَّبِّهِمْ وَجَنَّٰتࣱ تَجْرِے مِن تَحْتِهَا ࡰ۬لَانْهَٰرُ خَٰلِدِينَ فِيهَا࣌ وَنِعْمَ أَجْرُ ࡲ۬لْعَٰمِلِينَ࣌', 'أولئك جزاؤهم مغفرة من ربهم وجنت تجرے من تحتها ࡰلانهر خلدين فيها࣌ ونعم أجر ࡲلعملين࣌', NULL, 67, 'local:warsh-text.json'),
  ('warsh-3-137', 'warsh', 3, 137, 'قَدْ خَلَتْ مِن قَبْلِكُمْ سُنَنࣱ࣌ فَسِيرُواْ فِے ࡴ۬لَارْضِ فَانظُرُواْ كَيْفَ كَانَ عَٰقِبَةُ ࡲ۬لْمُكَذِّبِينَ࣌', 'قد خلت من قبلكم سنن࣌ فسيروا فے ࡴلارض فانظروا كيف كان عقبة ࡲلمكذبين࣌', NULL, 67, 'local:warsh-text.json'),
  ('warsh-3-138', 'warsh', 3, 138, 'هَٰذَا بَيَانࣱ لِّلنَّاسِ وَهُدىࣰ وَمَوْعِظَةࣱ لِّلْمُتَّقِينَ࣌', 'هذا بيان للناس وهدى وموعظة للمتقين࣌', NULL, 67, 'local:warsh-text.json'),
  ('warsh-3-139', 'warsh', 3, 139, 'وَلَا تَهِنُواْ وَلَا تَحْزَنُواْ وَأَنتُمُ ࡲ۬لَاعْلَوْنَ إِن كُنتُم مُّومِنِينَ࣌', 'ولا تهنوا ولا تحزنوا وأنتم ࡲلاعلون إن كنتم مومنين࣌', NULL, 67, 'local:warsh-text.json'),
  ('warsh-3-140', 'warsh', 3, 140, 'إِنْ يَّمْسَسْكُمْ قَرْحࣱ فَقَدْ مَسَّ ࡰ۬لْقَوْمَ قَرْحࣱ مِّثْلُهُۥ࣌ وَتِلْكَ ࡰ۬لَايَّامُ نُدَاوِلُهَا بَيْنَ ࡰ۬لنَّاسِ࣌ وَلِيَعْلَمَ ࡰ۬للَّهُ ࡲ۬لذِينَ ءَامَنُواْ وَيَتَّخِذَ مِنكُمْ شُهَدَآءَ࣌ وَاللَّهُ لَا يُحِبُّ ࡲ۬لظَّٰلِمِينَ࣌', 'إن يمسسكم قرح فقد مس ࡰلقوم قرح مثله࣌ وتلك ࡰلايام نداولها بين ࡰلناس࣌ وليعلم ࡰلله ࡲلذين ءامنوا ويتخذ منكم شهداء࣌ والله لا يحب ࡲلظلمين࣌', NULL, 67, 'local:warsh-text.json'),
  ('warsh-3-141', 'warsh', 3, 141, 'وَلِيُمَحِّصَ ࡰ۬للَّهُ ࡲ۬لذِينَ ءَامَنُواْ وَيَمْحَقَ ࡰ۬لْكٜـٰفِرِينَ࣌', 'وليمحص ࡰلله ࡲلذين ءامنوا ويمحق ࡰلكفرين࣌', NULL, 68, 'local:warsh-text.json'),
  ('warsh-3-142', 'warsh', 3, 142, 'أَمْ حَسِبْتُمُۥٓ أَن تَدْخُلُواْ ࡲ۬لْجَنَّةَ وَلَمَّا يَعْلَمِ ࡴ۬للَّهُ ࡲ۬لذِينَ جَٰهَدُواْ مِنكُمْ وَيَعْلَمَ ࡰ۬لصَّٰبِرِينَ࣌', 'أم حسبتم أن تدخلوا ࡲلجنة ولما يعلم ࡴلله ࡲلذين جهدوا منكم ويعلم ࡰلصبرين࣌', NULL, 68, 'local:warsh-text.json'),
  ('warsh-3-143', 'warsh', 3, 143, 'وَلَقَدْ كُنتُمْ تَمَنَّوْنَ ࡰ۬لْمَوْتَ مِن قَبْلِ أَن تَلْقَوْهُ فَقَدْ رَأَيْتُمُوهُ وَأَنتُمْ تَنظُرُونَ࣌', 'ولقد كنتم تمنون ࡰلموت من قبل أن تلقوه فقد رأيتموه وأنتم تنظرون࣌', NULL, 68, 'local:warsh-text.json'),
  ('warsh-3-144', 'warsh', 3, 144, '۞ وَمَا مُحَمَّدٌ ࡴلَّا رَسُولࣱ قَدْ خَلَتْ مِن قَبْلِهِ ࡴ۬لرُّسُلُ࣌ أَفَإِيْن مَّاتَ أَوْ قُتِلَ ࡰٜنقَلَبْتُمْ عَلَىٰٓ أَعْقَٰبِكُمْ࣌ وَمَنْ يَّنقَلِبْ عَلَىٰ عَقِبَيْهِ فَلَنْ يَّضُرَّ ࡰ۬للَّهَ شَيْـٔاࣰ࣌ وَسَيَجْزِے ࡴ۬للَّهُ ࡲ۬لشَّٰكِرِينَ࣌', 'وما محمد ࡴلا رسول قد خلت من قبله ࡴلرسل࣌ أفإين مات أو قتل ࡰنقلبتم على أعقبكم࣌ ومن ينقلب على عقبيه فلن يضر ࡰلله شيا࣌ وسيجزے ࡴلله ࡲلشكرين࣌', NULL, 68, 'local:warsh-text.json'),
  ('warsh-3-145', 'warsh', 3, 145, 'وَمَا كَانَ لِنَفْسٍ ࡰن تَمُوتَ إِلَّا بِإِذْنِ ࡴ۬للَّهِ࣌ كِتَٰباࣰ مُّوَ۬جَّلاࣰ࣌ وَمَنْ يُّرِدْ ثَوَابَ ࡰ۬لدُّنْيٜا نُوتِهِۦ مِنْهَا࣌ وَمَنْ يُّرِدْ ثَوَابَ ࡰ۬لَاخِرَةِ نُوتِهِۦ مِنْهَا࣌ وَسَنَجْزِے ࡴ۬لشَّٰكِرِينَ࣌', 'وما كان لنفس ࡰن تموت إلا بإذن ࡴلله࣌ كتبا موجلا࣌ ومن يرد ثواب ࡰلدنيا نوته منها࣌ ومن يرد ثواب ࡰلاخرة نوته منها࣌ وسنجزے ࡴلشكرين࣌', NULL, 68, 'local:warsh-text.json'),
  ('warsh-3-146', 'warsh', 3, 146, 'وَكَأَيِّن مِّن نَّبِےٓءࣲ قُتِلَ࣌ مَعَهُۥ رِبِّيُّونَ كَثِيرࣱ࣌ فَمَا وَهَنُواْ لِمَآ أَصَابَهُمْ فِے سَبِيلِ ࡴ۬للَّهِ وَمَا ضَعُفُواْ وَمَا ࡰٜسْتَكَانُواْ࣌ وَاللَّهُ يُحِبُّ ࡲ۬لصَّٰبِرِينَ࣌', 'وكأين من نبےء قتل࣌ معه ربيون كثير࣌ فما وهنوا لما أصابهم فے سبيل ࡴلله وما ضعفوا وما ࡰستكانوا࣌ والله يحب ࡲلصبرين࣌', NULL, 68, 'local:warsh-text.json'),
  ('warsh-3-147', 'warsh', 3, 147, 'وَمَا كَانَ قَوْلَهُمُۥٓ إِلَّآ أَن قَالُواْ رَبَّنَا ࡰٜغْفِرْ لَنَا ذُنُوبَنَا وَإِسْرَافَنَا فِےٓ أَمْرِنَا وَثَبِّتَ ࡰقْدَامَنَا وَانصُرْنَا عَلَى ࡰ۬لْقَوْمِ ࡴ۬لْكٜـٰفِرِينَ࣌', 'وما كان قولهم إلا أن قالوا ربنا ࡰغفر لنا ذنوبنا وإسرافنا فے أمرنا وثبت ࡰقدامنا وانصرنا على ࡰلقوم ࡴلكفرين࣌', NULL, 68, 'local:warsh-text.json'),
  ('warsh-3-148', 'warsh', 3, 148, 'فَـَٔاتٜيٰهُمُ ࡲ۬للَّهُ ثَوَابَ ࡰ۬لدُّنْيٜا وَحُسْنَ ثَوَابِ ࡴ۬لَاخِرَةِ࣌ وَاللَّهُ يُحِبُّ ࡲ۬لْمُحْسِنِينَ࣌', 'فاتيهم ࡲلله ثواب ࡰلدنيا وحسن ثواب ࡴلاخرة࣌ والله يحب ࡲلمحسنين࣌', NULL, 68, 'local:warsh-text.json'),
  ('warsh-3-149', 'warsh', 3, 149, 'يَٰٓأَيُّهَا ࡰ۬لذِينَ ءَامَنُوٓاْ إِن تُطِيعُواْ ࡲ۬لذِينَ كَفَرُواْ يَرُدُّوكُمْ عَلَىٰٓ أَعْقَٰبِكُمْ فَتَنقَلِبُواْ خَٰسِرِينَ࣌', 'يأيها ࡰلذين ءامنوا إن تطيعوا ࡲلذين كفروا يردوكم على أعقبكم فتنقلبوا خسرين࣌', NULL, 69, 'local:warsh-text.json'),
  ('warsh-3-150', 'warsh', 3, 150, 'بَلِ ࡴ۬للَّهُ مَوْلٜيٰكُمْ࣌ وَهُوَ خَيْرُ ࡲ۬لنَّٰصِرِينَ࣌', 'بل ࡴلله موليكم࣌ وهو خير ࡲلنصرين࣌', NULL, 69, 'local:warsh-text.json'),
  ('warsh-3-151', 'warsh', 3, 151, 'سَنُلْقِے فِے قُلُوبِ ࡴ۬لذِينَ كَفَرُواْ ࡲ۬لرُّعْبَ بِمَآ أَشْرَكُواْ بِاللَّهِ مَا لَمْ يُنَزِّلْ بِهِۦ سُلْطَٰناࣰ࣌ وَمَأْوٜيٰهُمُ ࡲ۬لنَّارُ࣌ وَبِيسَ مَثْوَى ࡰ۬لظَّٰلِمِينَ࣌', 'سنلقے فے قلوب ࡴلذين كفروا ࡲلرعب بما أشركوا بالله ما لم ينزل به سلطنا࣌ ومأويهم ࡲلنار࣌ وبيس مثوى ࡰلظلمين࣌', NULL, 69, 'local:warsh-text.json'),
  ('warsh-3-152', 'warsh', 3, 152, 'وَلَقَدْ صَدَقَكُمُ ࡲ۬للَّهُ وَعْدَهُۥٓ إِذْ تَحُسُّونَهُم بِإِذْنِهِۦ࣌ حَتَّىٰٓ إِذَا فَشِلْتُمْ وَتَنَٰزَعْتُمْ فِے ࡴ۬لَامْرِ وَعَصَيْتُم مِّنۢ بَعْدِ مَآ أَرٜيٰكُم مَّا تُحِبُّونَ࣌ مِنكُم مَّنْ يُّرِيدُ ࡲ۬لدُّنْيٜا وَمِنكُم مَّنْ يُّرِيدُ ࡲ۬لَاخِرَةَ࣌ ثُمَّ صَرَفَكُمْ عَنْهُمْ لِيَبْتَلِيَكُمْ࣌ وَلَقَدْ عَفَا عَنكُمْ࣌ وَاللَّهُ ذُو فَضْلٍ عَلَى ࡰ۬لْمُومِنِينَ࣌', 'ولقد صدقكم ࡲلله وعده إذ تحسونهم بإذنه࣌ حتى إذا فشلتم وتنزعتم فے ࡴلامر وعصيتم من بعد ما أريكم ما تحبون࣌ منكم من يريد ࡲلدنيا ومنكم من يريد ࡲلاخرة࣌ ثم صرفكم عنهم ليبتليكم࣌ ولقد عفا عنكم࣌ والله ذو فضل على ࡰلمومنين࣌', NULL, 69, 'local:warsh-text.json'),
  ('warsh-3-153', 'warsh', 3, 153, '۞ إِذْ تُصْعِدُونَ وَلَا تَلْوُۥنَ عَلَىٰٓ أَحَدࣲ وَالرَّسُولُ يَدْعُوكُمْ فِےٓ أُخْرٜيٰكُمْ فَأَثَٰبَكُمْ غَمّاَۢ بِغَمࣲّ لِّكَيْلَا تَحْزَنُواْ عَلَىٰ مَا فَاتَكُمْ وَلَا مَآ أَصَٰبَكُمْ࣌ وَاللَّهُ خَبِيرُۢ بِمَا تَعْمَلُونَ࣌', 'إذ تصعدون ولا تلون على أحد والرسول يدعوكم فے أخريكم فأثبكم غما بغم لكيلا تحزنوا على ما فاتكم ولا ما أصبكم࣌ والله خبير بما تعملون࣌', NULL, 69, 'local:warsh-text.json'),
  ('warsh-3-154', 'warsh', 3, 154, 'ثُمَّ أَنزَلَ عَلَيْكُم مِّنۢ بَعْدِ ࡴ۬لْغَمِّ أَمَنَةࣰ نُّعَاساࣰ يَغْشٜىٰ طَآئِفَةࣰ مِّنكُمْ࣌ وَطَآئِفَةࣱ قَدَ ࡰهَمَّتْهُمُۥٓ أَنفُسُهُمْ يَظُنُّونَ بِاللَّهِ غَيْرَ ࡰ۬لْحَقِّ ظَنَّ ࡰ۬لْجَٰهِلِيَّةِ࣌ يَقُولُونَ هَل لَّنَا مِنَ ࡰ۬لَامْرِ مِن شَےْءࣲ࣌ قُلِ ࡴنَّ ࡰ۬لَامْرَ كُلَّهُۥ لِلهِ࣌ يُخْفُونَ فِےٓ أَنفُسِهِم مَّا لَا يُبْدُونَ لَكَ࣌ يَقُولُونَ لَوْ كَانَ لَنَا مِنَ ࡰ۬لَامْرِ شَےْءࣱ مَّا قُتِلْنَا هَٰهُنَا࣌ قُل لَّوْ كُنتُمْ فِے بُيُوتِكُمْ لَبَرَزَ ࡰ۬لذِينَ كُتِبَ عَلَيْهِمُ ࡲ۬لْقَتْلُ إِلَىٰ مَضَاجِعِهِمْ وَلِيَبْتَلِيَ ࡰ۬للَّهُ مَا فِے صُدُورِكُمْ وَلِيُمَحِّصَ مَا فِے قُلُوبِكُمْ࣌ وَاللَّهُ عَلِيمُۢ بِذَاتِ ࡴ۬لصُّدُورِ࣌', 'ثم أنزل عليكم من بعد ࡴلغم أمنة نعاسا يغشى طائفة منكم࣌ وطائفة قد ࡰهمتهم أنفسهم يظنون بالله غير ࡰلحق ظن ࡰلجهلية࣌ يقولون هل لنا من ࡰلامر من شےء࣌ قل ࡴن ࡰلامر كله لله࣌ يخفون فے أنفسهم ما لا يبدون لك࣌ يقولون لو كان لنا من ࡰلامر شےء ما قتلنا ههنا࣌ قل لو كنتم فے بيوتكم لبرز ࡰلذين كتب عليهم ࡲلقتل إلى مضاجعهم وليبتلي ࡰلله ما فے صدوركم وليمحص ما فے قلوبكم࣌ والله عليم بذات ࡴلصدور࣌', NULL, 70, 'local:warsh-text.json'),
  ('warsh-3-155', 'warsh', 3, 155, 'إِنَّ ࡰ۬لذِينَ تَوَلَّوْاْ مِنكُمْ يَوْمَ ࡰٜلْتَقَى ࡰ۬لْجَمْعَٰنِ إِنَّمَا ࡰٜسْتَزَلَّهُمُ ࡲ۬لشَّيْطَٰنُ بِبَعْضِ مَا كَسَبُواْ࣌ وَلَقَدْ عَفَا ࡰ۬للَّهُ عَنْهُمُۥٓ࣌ إِنَّ ࡰ۬للَّهَ غَفُورٌ حَلِيمࣱ࣌', 'إن ࡰلذين تولوا منكم يوم ࡰلتقى ࡰلجمعن إنما ࡰستزلهم ࡲلشيطن ببعض ما كسبوا࣌ ولقد عفا ࡰلله عنهم࣌ إن ࡰلله غفور حليم࣌', NULL, 70, 'local:warsh-text.json'),
  ('warsh-3-156', 'warsh', 3, 156, 'يَٰٓأَيُّهَا ࡰ۬لذِينَ ءَامَنُواْ لَا تَكُونُواْ كَالذِينَ كَفَرُواْ وَقَالُواْ لِإِخْوَٰنِهِمُۥٓ إِذَا ضَرَبُواْ فِے ࡴ۬لَارْضِ أَوْ كَانُواْ غُزّىࣰ لَّوْ كَانُواْ عِندَنَا مَا مَاتُواْ وَمَا قُتِلُواْ لِيَجْعَلَ ࡰ۬للَّهُ ذَٰلِكَ حَسْرَةࣰ فِے قُلُوبِهِمْ࣌ وَاللَّهُ يُحْيِۦ وَيُمِيتُ࣌ وَاللَّهُ بِمَا تَعْمَلُونَ بَصِيرࣱ࣌', 'يأيها ࡰلذين ءامنوا لا تكونوا كالذين كفروا وقالوا لإخونهم إذا ضربوا فے ࡴلارض أو كانوا غزى لو كانوا عندنا ما ماتوا وما قتلوا ليجعل ࡰلله ذلك حسرة فے قلوبهم࣌ والله يحي ويميت࣌ والله بما تعملون بصير࣌', NULL, 70, 'local:warsh-text.json'),
  ('warsh-3-157', 'warsh', 3, 157, 'وَلَئِن قُتِلْتُمْ فِے سَبِيلِ ࡴ۬للَّهِ أَوْ مِتُّمْ لَمَغْفِرَةࣱ مِّنَ ࡰ۬للَّهِ وَرَحْمَةٌ خَيْرࣱ مِّمَّا تَجْمَعُونَ࣌', 'ولئن قتلتم فے سبيل ࡴلله أو متم لمغفرة من ࡰلله ورحمة خير مما تجمعون࣌', NULL, 70, 'local:warsh-text.json'),
  ('warsh-3-158', 'warsh', 3, 158, 'وَلَئِن مِّتُّمُۥٓ أَوْ قُتِلْتُمْ لَإِلَى ࡰ۬للَّهِ تُحْشَرُونَ࣌', 'ولئن متم أو قتلتم لإلى ࡰلله تحشرون࣌', NULL, 71, 'local:warsh-text.json'),
  ('warsh-3-159', 'warsh', 3, 159, 'فَبِمَا رَحْمَةࣲ مِّنَ ࡰ۬للَّهِ لِنتَ لَهُمْ࣌ وَلَوْ كُنتَ فَظّاً غَلِيظَ ࡰ۬لْقَلْبِ لَانفَضُّواْ مِنْ حَوْلِكَ࣌ فَاعْفُ عَنْهُمْ وَاسْتَغْفِرْ لَهُمْ وَشَاوِرْهُمْ فِے ࡴ۬لَامْرِ࣌ فَإِذَا عَزَمْتَ فَتَوَكَّلْ عَلَى ࡰ۬للَّهِ࣌ إِنَّ ࡰ۬للَّهَ يُحِبُّ ࡲ۬لْمُتَوَكِّلِينَ࣌', 'فبما رحمة من ࡰلله لنت لهم࣌ ولو كنت فظا غليظ ࡰلقلب لانفضوا من حولك࣌ فاعف عنهم واستغفر لهم وشاورهم فے ࡴلامر࣌ فإذا عزمت فتوكل على ࡰلله࣌ إن ࡰلله يحب ࡲلمتوكلين࣌', NULL, 71, 'local:warsh-text.json'),
  ('warsh-3-160', 'warsh', 3, 160, '۞ إِنْ يَّنصُرْكُمُ ࡲ۬للَّهُ فَلَا غَالِبَ لَكُمْ࣌ وَإِنْ يَّخْذُلْكُمْ فَمَن ذَا ࡰ۬لذِے يَنصُرُكُم مِّنۢ بَعْدِهِۦ࣌ وَعَلَى ࡰ۬للَّهِ فَلْيَتَوَكَّلِ ࡴ۬لْمُومِنُونَ࣌', 'إن ينصركم ࡲلله فلا غالب لكم࣌ وإن يخذلكم فمن ذا ࡰلذے ينصركم من بعده࣌ وعلى ࡰلله فليتوكل ࡴلمومنون࣌', NULL, 71, 'local:warsh-text.json'),
  ('warsh-3-161', 'warsh', 3, 161, 'وَمَا كَانَ لِنَبِےٓءٍ ࡰنْ يُّغَلَّ࣌ وَمَنْ يَّغْلُلْ يَاتِ بِمَا غَلَّ يَوْمَ ࡰ۬لْقِيَٰمَةِ࣌ ثُمَّ تُوَفّٜىٰ كُلُّ نَفْسࣲ مَّا كَسَبَتْ وَهُمْ لَا يُظْلَمُونَ࣌', 'وما كان لنبےء ࡰن يغل࣌ ومن يغلل يات بما غل يوم ࡰلقيمة࣌ ثم توفى كل نفس ما كسبت وهم لا يظلمون࣌', NULL, 71, 'local:warsh-text.json'),
  ('warsh-3-162', 'warsh', 3, 162, 'أَفَمَنِ ࡴٜتَّبَعَ رِضْوَٰنَ ࡰ۬للَّهِ كَمَنۢ بَآءَ بِسَخَطࣲ مِّنَ ࡰ۬للَّهِ وَمَأْوٜيٰهُ جَهَنَّمُ࣌ وَبِيسَ ࡰ۬لْمَصِيرُ࣌', 'أفمن ࡴتبع رضون ࡰلله كمن باء بسخط من ࡰلله ومأويه جهنم࣌ وبيس ࡰلمصير࣌', NULL, 71, 'local:warsh-text.json'),
  ('warsh-3-163', 'warsh', 3, 163, 'هُمْ دَرَجَٰتٌ عِندَ ࡰ۬للَّهِ࣌ وَاللَّهُ بَصِيرُۢ بِمَا يَعْمَلُونَ࣌', 'هم درجت عند ࡰلله࣌ والله بصير بما يعملون࣌', NULL, 71, 'local:warsh-text.json'),
  ('warsh-3-164', 'warsh', 3, 164, 'لَقَدْ مَنَّ ࡰ۬للَّهُ عَلَى ࡰ۬لْمُومِنِينَ إِذْ بَعَثَ فِيهِمْ رَسُولاࣰ مِّنَ ࡰنفُسِهِمْ يَتْلُواْ عَلَيْهِمُۥٓ ءَايَٰتِهِۦ وَيُزَكِّيهِمْ وَيُعَلِّمُهُمُ ࡲ۬لْكِتَٰبَ وَالْحِكْمَةَ وَإِن كَانُواْ مِن قَبْلُ لَفِے ضَلَٰلࣲ مُّبِينٍ࣌', 'لقد من ࡰلله على ࡰلمومنين إذ بعث فيهم رسولا من ࡰنفسهم يتلوا عليهم ءايته ويزكيهم ويعلمهم ࡲلكتب والحكمة وإن كانوا من قبل لفے ضلل مبين࣌', NULL, 71, 'local:warsh-text.json'),
  ('warsh-3-165', 'warsh', 3, 165, 'ࡰوَلَمَّآ أَصَٰبَتْكُم مُّصِيبَةࣱ قَدَ ࡰصَبْتُم مِّثْلَيْهَا قُلْتُمُۥٓ أَنّٜىٰ هَٰذَا࣌ قُلْ هُوَ مِنْ عِندِ أَنفُسِكُمُۥٓ࣌ إِنَّ ࡰ۬للَّهَ عَلَىٰ كُلِّ شَےْءࣲ قَدِيرࣱ࣌', 'ࡰولما أصبتكم مصيبة قد ࡰصبتم مثليها قلتم أنى هذا࣌ قل هو من عند أنفسكم࣌ إن ࡰلله على كل شےء قدير࣌', NULL, 71, 'local:warsh-text.json'),
  ('warsh-3-166', 'warsh', 3, 166, 'وَمَآ أَصَٰبَكُمْ يَوْمَ ࡰٜلْتَقَى ࡰ۬لْجَمْعَٰنِ فَبِإِذْنِ ࡴ۬للَّهِ وَلِيَعْلَمَ ࡰ۬لْمُومِنِينَ', 'وما أصبكم يوم ࡰلتقى ࡰلجمعن فبإذن ࡴلله وليعلم ࡰلمومنين', NULL, 72, 'local:warsh-text.json'),
  ('warsh-3-167', 'warsh', 3, 167, 'وَلِيَعْلَمَ ࡰ۬لذِينَ نَافَقُواْ࣌ وَقِيلَ لَهُمْ تَعَالَوْاْ قَٰتِلُواْ فِے سَبِيلِ ࡴ۬للَّهِ أَوِ ࡴٜدْفَعُواْ࣌ قَالُواْ لَوْ نَعْلَمُ قِتَالاࣰ لَّاتَّبَعْنَٰكُمْ࣌ هُمْ لِلْكُفْرِ يَوْمَئِذٍ ࡰقْرَبُ مِنْهُمْ لِلِايمَٰنِ࣌ يَقُولُونَ بِأَفْوَٰهِهِم مَّا لَيْسَ فِے قُلُوبِهِمْ࣌ وَاللَّهُ أَعْلَمُ بِمَا يَكْتُمُونَ࣌', 'وليعلم ࡰلذين نافقوا࣌ وقيل لهم تعالوا قتلوا فے سبيل ࡴلله أو ࡴدفعوا࣌ قالوا لو نعلم قتالا لاتبعنكم࣌ هم للكفر يومئذ ࡰقرب منهم للايمن࣌ يقولون بأفوههم ما ليس فے قلوبهم࣌ والله أعلم بما يكتمون࣌', NULL, 72, 'local:warsh-text.json'),
  ('warsh-3-168', 'warsh', 3, 168, 'ࡰ۬لذِينَ قَالُواْ لِإِخْوَٰنِهِمْ وَقَعَدُواْ لَوَ ࡰطَاعُونَا مَا قُتِلُواْ࣌ قُلْ فَادْرَءُواْ عَنَ ࡰنفُسِكُمُ ࡲ۬لْمَوْتَ إِن كُنتُمْ صَٰدِقِينَ࣌', 'ࡰلذين قالوا لإخونهم وقعدوا لو ࡰطاعونا ما قتلوا࣌ قل فادرءوا عن ࡰنفسكم ࡲلموت إن كنتم صدقين࣌', NULL, 72, 'local:warsh-text.json'),
  ('warsh-3-169', 'warsh', 3, 169, 'وَلَا تَحْسِبَنَّ ࡰ۬لذِينَ قُتِلُواْ فِے سَبِيلِ ࡴ۬للَّهِ أَمْوَٰتاَۢ࣌ بَلَ ࡰحْيَآءٌ࣌ عِندَ رَبِّهِمْ يُرْزَقُونَ', 'ولا تحسبن ࡰلذين قتلوا فے سبيل ࡴلله أموتا࣌ بل ࡰحياء࣌ عند ربهم يرزقون', NULL, 72, 'local:warsh-text.json'),
  ('warsh-3-170', 'warsh', 3, 170, 'فَرِحِينَ بِمَآ ءَاتٜيٰهُمُ ࡲ۬للَّهُ مِن فَضْلِهِۦ وَيَسْتَبْشِرُونَ بِالذِينَ لَمْ يَلْحَقُواْ بِهِم مِّنْ خَلْفِهِمُۥٓ أَلَّا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ࣌', 'فرحين بما ءاتيهم ࡲلله من فضله ويستبشرون بالذين لم يلحقوا بهم من خلفهم ألا خوف عليهم ولا هم يحزنون࣌', NULL, 72, 'local:warsh-text.json'),
  ('warsh-3-171', 'warsh', 3, 171, '۞ يَسْتَبْشِرُونَ بِنِعْمَةࣲ مِّنَ ࡰ۬للَّهِ وَفَضْلࣲ وَأَنَّ ࡰ۬للَّهَ لَا يُضِيعُ أَجْرَ ࡰ۬لْمُومِنِينَ', 'يستبشرون بنعمة من ࡰلله وفضل وأن ࡰلله لا يضيع أجر ࡰلمومنين', NULL, 72, 'local:warsh-text.json'),
  ('warsh-3-172', 'warsh', 3, 172, 'ࡰ۬لذِينَ ࡰٜسْتَجَابُواْ لِلهِ وَالرَّسُولِ مِنۢ بَعْدِ مَآ أَصَابَهُمُ ࡲ۬لْقَرْحُ࣌ لِلذِينَ أَحْسَنُواْ مِنْهُمْ وَاتَّقَوَاْ ࡰجْرٌ عَظِيمٌ࣌', 'ࡰلذين ࡰستجابوا لله والرسول من بعد ما أصابهم ࡲلقرح࣌ للذين أحسنوا منهم واتقوا ࡰجر عظيم࣌', NULL, 72, 'local:warsh-text.json'),
  ('warsh-3-173', 'warsh', 3, 173, 'ࡴ۬لذِينَ قَالَ لَهُمُ ࡲ۬لنَّاسُ إِنَّ ࡰ۬لنَّاسَ قَدْ جَمَعُواْ لَكُمْ فَاخْشَوْهُمْ فَزَادَهُمُۥٓ إِيمَٰناࣰ࣌ وَقَالُواْ حَسْبُنَا ࡰ۬للَّهُ وَنِعْمَ ࡰ۬لْوَكِيلُ࣌', 'ࡴلذين قال لهم ࡲلناس إن ࡰلناس قد جمعوا لكم فاخشوهم فزادهم إيمنا࣌ وقالوا حسبنا ࡰلله ونعم ࡰلوكيل࣌', NULL, 72, 'local:warsh-text.json'),
  ('warsh-3-174', 'warsh', 3, 174, 'فَانقَلَبُواْ بِنِعْمَةࣲ مِّنَ ࡰ۬للَّهِ وَفَضْلࣲ لَّمْ يَمْسَسْهُمْ سُوٓءࣱ وَاتَّبَعُواْ رِضْوَٰنَ ࡰ۬للَّهِ࣌ وَاللَّهُ ذُو فَضْلٍ عَظِيمٍ࣌', 'فانقلبوا بنعمة من ࡰلله وفضل لم يمسسهم سوء واتبعوا رضون ࡰلله࣌ والله ذو فضل عظيم࣌', NULL, 73, 'local:warsh-text.json'),
  ('warsh-3-175', 'warsh', 3, 175, 'ࡴنَّمَا ذَٰلِكُمُ ࡲ۬لشَّيْطَٰنُ يُخَوِّفُ أَوْلِيَآءَهُۥ فَلَا تَخَافُوهُمْ࣌ وَخَافُونِ إِن كُنتُم مُّومِنِينَ࣌', 'ࡴنما ذلكم ࡲلشيطن يخوف أولياءه فلا تخافوهم࣌ وخافون إن كنتم مومنين࣌', NULL, 73, 'local:warsh-text.json'),
  ('warsh-3-176', 'warsh', 3, 176, 'وَلَا يُحْزِنكَ ࡰ۬لذِينَ يُسَٰرِعُونَ فِے ࡴ۬لْكُفْرِ࣌ إِنَّهُمْ لَنْ يَّضُرُّواْ ࡲ۬للَّهَ شَيْـٔاࣰ࣌ يُرِيدُ ࡲ۬للَّهُ أَلَّا يَجْعَلَ لَهُمْ حَظّاࣰ فِے ࡴ۬لَاخِرَةِ࣌ وَلَهُمْ عَذَابٌ عَظِيمٌ࣌', 'ولا يحزنك ࡰلذين يسرعون فے ࡴلكفر࣌ إنهم لن يضروا ࡲلله شيا࣌ يريد ࡲلله ألا يجعل لهم حظا فے ࡴلاخرة࣌ ولهم عذاب عظيم࣌', NULL, 73, 'local:warsh-text.json'),
  ('warsh-3-177', 'warsh', 3, 177, 'ࡴنَّ ࡰ۬لذِينَ ࡰٜشْتَرَوُاْ ࡲ۬لْكُفْرَ بِالِايمَٰنِ لَنْ يَّضُرُّواْ ࡲ۬للَّهَ شَيْـٔاࣰ࣌ وَلَهُمْ عَذَابٌ ࡰلِيمࣱ࣌', 'ࡴن ࡰلذين ࡰشتروا ࡲلكفر بالايمن لن يضروا ࡲلله شيا࣌ ولهم عذاب ࡰليم࣌', NULL, 73, 'local:warsh-text.json'),
  ('warsh-3-178', 'warsh', 3, 178, 'وَلَا يَحْسِبَنَّ ࡰ۬لذِينَ كَفَرُوٓاْ أَنَّمَا نُمْلِے لَهُمْ خَيْرࣱ لِّأَنفُسِهِمُۥٓ࣌ إِنَّمَا نُمْلِے لَهُمْ لِيَزْدَادُوٓاْ إِثْماࣰ࣌ وَلَهُمْ عَذَابࣱ مُّهِينࣱ࣌', 'ولا يحسبن ࡰلذين كفروا أنما نملے لهم خير لأنفسهم࣌ إنما نملے لهم ليزدادوا إثما࣌ ولهم عذاب مهين࣌', NULL, 73, 'local:warsh-text.json'),
  ('warsh-3-179', 'warsh', 3, 179, 'مَّا كَانَ ࡰ۬للَّهُ لِيَذَرَ ࡰ۬لْمُومِنِينَ عَلَىٰ مَآ أَنتُمْ عَلَيْهِ حَتَّىٰ يَمِيزَ ࡰ۬لْخَبِيثَ مِنَ ࡰ۬لطَّيِّبِ࣌ وَمَا كَانَ ࡰ۬للَّهُ لِيُطْلِعَكُمْ عَلَى ࡰ۬لْغَيْبِ࣌ وَلَٰكِنَّ ࡰ۬للَّهَ يَجْتَبِے مِن رُّسُلِهِۦ مَنْ يَّشَآءُ࣌ فَـَٔامِنُواْ بِاللَّهِ وَرُسُلِهِۦ࣌ وَإِن تُومِنُواْ وَتَتَّقُواْ فَلَكُمُۥٓ أَجْرٌ عَظِيمࣱ࣌', 'ما كان ࡰلله ليذر ࡰلمومنين على ما أنتم عليه حتى يميز ࡰلخبيث من ࡰلطيب࣌ وما كان ࡰلله ليطلعكم على ࡰلغيب࣌ ولكن ࡰلله يجتبے من رسله من يشاء࣌ فامنوا بالله ورسله࣌ وإن تومنوا وتتقوا فلكم أجر عظيم࣌', NULL, 73, 'local:warsh-text.json'),
  ('warsh-3-180', 'warsh', 3, 180, 'وَلَا يَحْسِبَنَّ ࡰ۬لذِينَ يَبْخَلُونَ بِمَآ ءَاتٜيٰهُمُ ࡲ۬للَّهُ مِن فَضْلِهِۦ هُوَ خَيْراࣰ لَّهُم࣌ بَلْ هُوَ شَرࣱّ لَّهُمْ࣌ سَيُطَوَّقُونَ مَا بَخِلُواْ بِهِۦ يَوْمَ ࡰ۬لْقِيَٰمَةِ࣌ وَلِلهِ مِيرَٰثُ ࡲ۬لسَّمَٰوَٰتِ وَالَارْضِ࣌ وَاللَّهُ بِمَا تَعْمَلُونَ خَبِيرࣱ࣌', 'ولا يحسبن ࡰلذين يبخلون بما ءاتيهم ࡲلله من فضله هو خيرا لهم࣌ بل هو شر لهم࣌ سيطوقون ما بخلوا به يوم ࡰلقيمة࣌ ولله ميرث ࡲلسموت والارض࣌ والله بما تعملون خبير࣌', NULL, 73, 'local:warsh-text.json'),
  ('warsh-3-181', 'warsh', 3, 181, '۞ لَّقَدْ سَمِعَ ࡰ۬للَّهُ قَوْلَ ࡰ۬لذِينَ قَالُوٓاْ إِنَّ ࡰ۬للَّهَ فَقِيرࣱ وَنَحْنُ أَغْنِيَآءُ࣌ سَنَكْتُبُ مَا قَالُواْ وَقَتْلَهُمُ ࡲ۬لَانۢبِئَآءَ بِغَيْرِ حَقࣲّ وَنَقُولُ ذُوقُواْ عَذَابَ ࡰ۬لْحَرِيقِ࣌', 'لقد سمع ࡰلله قول ࡰلذين قالوا إن ࡰلله فقير ونحن أغنياء࣌ سنكتب ما قالوا وقتلهم ࡲلانبئاء بغير حق ونقول ذوقوا عذاب ࡰلحريق࣌', NULL, 74, 'local:warsh-text.json'),
  ('warsh-3-182', 'warsh', 3, 182, 'ذَٰلِكَ بِمَا قَدَّمَتَ ࡰيْدِيكُمْ وَأَنَّ ࡰ۬للَّهَ لَيْسَ بِظَلَّٰمࣲ لِّلْعَبِيدِ࣌', 'ذلك بما قدمت ࡰيديكم وأن ࡰلله ليس بظلم للعبيد࣌', NULL, 74, 'local:warsh-text.json'),
  ('warsh-3-183', 'warsh', 3, 183, 'ࡴ۬لذِينَ قَالُوٓاْ إِنَّ ࡰ۬للَّهَ عَهِدَ إِلَيْنَآ أَلَّا نُومِنَ لِرَسُولٍ حَتَّىٰ يَاتِيَنَا بِقُرْبَانࣲ تَاكُلُهُ ࡲ۬لنَّارُ࣌ قُلْ قَدْ جَآءَكُمْ رُسُلࣱ مِّن قَبْلِے بِالْبَيِّنَٰتِ وَبِالذِے قُلْتُمْ فَلِمَ قَتَلْتُمُوهُمُۥٓ إِن كُنتُمْ صَٰدِقِينَ࣌', 'ࡴلذين قالوا إن ࡰلله عهد إلينا ألا نومن لرسول حتى ياتينا بقربان تاكله ࡲلنار࣌ قل قد جاءكم رسل من قبلے بالبينت وبالذے قلتم فلم قتلتموهم إن كنتم صدقين࣌', NULL, 74, 'local:warsh-text.json'),
  ('warsh-3-184', 'warsh', 3, 184, 'فَإِن كَذَّبُوكَ فَقَدْ كُذِّبَ رُسُلࣱ مِّن قَبْلِكَ جَآءُو بِالْبَيِّنَٰتِ وَالزُّبُرِ وَالْكِتَٰبِ ࡴ۬لْمُنِيرِ࣌', 'فإن كذبوك فقد كذب رسل من قبلك جاءو بالبينت والزبر والكتب ࡴلمنير࣌', NULL, 74, 'local:warsh-text.json'),
  ('warsh-3-185', 'warsh', 3, 185, 'كُلُّ نَفْسࣲ ذَآئِقَةُ ࡲ۬لْمَوْتِ࣌ وَإِنَّمَا تُوَفَّوْنَ أُجُورَكُمْ يَوْمَ ࡰ۬لْقِيَٰمَةِ࣌ فَمَن زُحْزِحَ عَنِ ࡴ۬لنّٜارِ وَأُدْخِلَ ࡰ۬لْجَنَّةَ فَقَدْ فَازَ࣌ وَمَا ࡰ۬لْحَيَوٰةُ ࡲ۬لدُّنْيٜآ إِلَّا مَتَٰعُ ࡲ۬لْغُرُورِ࣌', 'كل نفس ذائقة ࡲلموت࣌ وإنما توفون أجوركم يوم ࡰلقيمة࣌ فمن زحزح عن ࡴلنار وأدخل ࡰلجنة فقد فاز࣌ وما ࡰلحيوة ࡲلدنيا إلا متع ࡲلغرور࣌', NULL, 74, 'local:warsh-text.json'),
  ('warsh-3-186', 'warsh', 3, 186, '۞ لَتُبْلَوُنَّ فِےٓ أَمْوَٰلِكُمْ وَأَنفُسِكُمْ وَلَتَسْمَعُنَّ مِنَ ࡰ۬لذِينَ أُوتُواْ ࡲ۬لْكِتَٰبَ مِن قَبْلِكُمْ وَمِنَ ࡰ۬لذِينَ أَشْرَكُوٓاْ أَذىࣰ كَثِيراࣰ࣌ وَإِن تَصْبِرُواْ وَتَتَّقُواْ فَإِنَّ ذَٰلِكَ مِنْ عَزْمِ ࡴ۬لُامُورِ࣌', 'لتبلون فے أمولكم وأنفسكم ولتسمعن من ࡰلذين أوتوا ࡲلكتب من قبلكم ومن ࡰلذين أشركوا أذى كثيرا࣌ وإن تصبروا وتتقوا فإن ذلك من عزم ࡴلامور࣌', NULL, 74, 'local:warsh-text.json'),
  ('warsh-3-187', 'warsh', 3, 187, 'وَإِذَ ࡰخَذَ ࡰ۬للَّهُ مِيثَٰقَ ࡰ۬لذِينَ أُوتُواْ ࡲ۬لْكِتَٰبَ لَتُبَيِّنُنَّهُۥ لِلنَّاسِ وَلَا تَكْتُمُونَهُۥ فَنَبَذُوهُ وَرَآءَ ظُهُورِهِمْ وَاشْتَرَوْاْ بِهِۦ ثَمَناࣰ قَلِيلاࣰ࣌ فَبِيسَ مَا يَشْتَرُونَ࣌', 'وإذ ࡰخذ ࡰلله ميثق ࡰلذين أوتوا ࡲلكتب لتبيننه للناس ولا تكتمونه فنبذوه وراء ظهورهم واشتروا به ثمنا قليلا࣌ فبيس ما يشترون࣌', NULL, 75, 'local:warsh-text.json'),
  ('warsh-3-188', 'warsh', 3, 188, 'لَا يَحْسِبَنَّ ࡰ۬لذِينَ يَفْرَحُونَ بِمَآ أَتَواْ وَّيُحِبُّونَ أَنْ يُّحْمَدُواْ بِمَا لَمْ يَفْعَلُواْ فَلَا تَحْسِبَنَّهُم بِمَفَازَةࣲ مِّنَ ࡰ۬لْعَذَابِ࣌ وَلَهُمْ عَذَابٌ ࡰلِيمࣱ࣌', 'لا يحسبن ࡰلذين يفرحون بما أتوا ويحبون أن يحمدوا بما لم يفعلوا فلا تحسبنهم بمفازة من ࡰلعذاب࣌ ولهم عذاب ࡰليم࣌', NULL, 75, 'local:warsh-text.json'),
  ('warsh-3-189', 'warsh', 3, 189, 'وَلِلهِ مُلْكُ ࡲ۬لسَّمَٰوَٰتِ وَالَارْضِ࣌ وَاللَّهُ عَلَىٰ كُلِّ شَےْءࣲ قَدِيرٌ࣌', 'ولله ملك ࡲلسموت والارض࣌ والله على كل شےء قدير࣌', NULL, 75, 'local:warsh-text.json'),
  ('warsh-3-190', 'warsh', 3, 190, 'ࡴنَّ فِے خَلْقِ ࡴ۬لسَّمَٰوَٰتِ وَالَارْضِ وَاخْتِلَٰفِ ࡴ۬ليْلِ وَالنَّهٜارِ لَأٓيَٰتࣲ لِّأُوْلِے ࡴ۬لَالْبَٰبِ', 'ࡴن فے خلق ࡴلسموت والارض واختلف ࡴليل والنهار لأيت لأولے ࡴلالبب', NULL, 75, 'local:warsh-text.json'),
  ('warsh-3-191', 'warsh', 3, 191, 'ࡴ۬لذِينَ يَذْكُرُونَ ࡰ۬للَّهَ قِيَٰماࣰ وَقُعُوداࣰ وَعَلَىٰ جُنُوبِهِمْ وَيَتَفَكَّرُونَ فِے خَلْقِ ࡴ۬لسَّمَٰوَٰتِ وَالَارْضِ࣌ رَبَّنَا مَا خَلَقْتَ هَٰذَا بَٰطِلاࣰ سُبْحَٰنَكَ࣌ فَقِنَا عَذَابَ ࡰ۬لنّٜارِ࣌', 'ࡴلذين يذكرون ࡰلله قيما وقعودا وعلى جنوبهم ويتفكرون فے خلق ࡴلسموت والارض࣌ ربنا ما خلقت هذا بطلا سبحنك࣌ فقنا عذاب ࡰلنار࣌', NULL, 75, 'local:warsh-text.json'),
  ('warsh-3-192', 'warsh', 3, 192, 'رَبَّنَآ إِنَّكَ مَن تُدْخِلِ ࡴ۬لنَّارَ فَقَدَ ࡰخْزَيْتَهُۥ࣌ وَمَا لِلظَّٰلِمِينَ مِنَ ࡰنصٜارࣲ࣌', 'ربنا إنك من تدخل ࡴلنار فقد ࡰخزيته࣌ وما للظلمين من ࡰنصار࣌', NULL, 75, 'local:warsh-text.json'),
  ('warsh-3-193', 'warsh', 3, 193, 'رَّبَّنَآ إِنَّنَا سَمِعْنَا مُنَادِياࣰ يُنَادِے لِلِايمَٰنِ أَنَ اٰمِنُواْ بِرَبِّكُمْ فَـَٔامَنَّا࣌ رَبَّنَا فَاغْفِرْ لَنَا ذُنُوبَنَا وَكَفِّرْ عَنَّا سَيِّـَٔاتِنَا وَتَوَفَّنَا مَعَ ࡰ۬لَابْرٜارِ࣌', 'ربنا إننا سمعنا مناديا ينادے للايمن أن امنوا بربكم فامنا࣌ ربنا فاغفر لنا ذنوبنا وكفر عنا سياتنا وتوفنا مع ࡰلابرار࣌', NULL, 75, 'local:warsh-text.json'),
  ('warsh-3-194', 'warsh', 3, 194, 'رَبَّنَا وَءَاتِنَا مَا وَعَدتَّنَا عَلَىٰ رُسُلِكَ وَلَا تُخْزِنَا يَوْمَ ࡰ۬لْقِيَٰمَةِ࣌ إِنَّكَ لَا تُخْلِفُ ࡲ۬لْمِيعَادَ࣌', 'ربنا وءاتنا ما وعدتنا على رسلك ولا تخزنا يوم ࡰلقيمة࣌ إنك لا تخلف ࡲلميعاد࣌', NULL, 75, 'local:warsh-text.json'),
  ('warsh-3-195', 'warsh', 3, 195, 'فَاسْتَجَابَ لَهُمْ رَبُّهُمُۥٓ أَنِّے لَآ أُضِيعُ عَمَلَ عَٰمِلࣲ مِّنكُم مِّن ذَكَرٍ ࡰوُ ࡳنثٜىٰ࣌ بَعْضُكُم مِّنۢ بَعْضࣲ࣌ فَالذِينَ هَاجَرُواْ وَأُخْرِجُواْ مِن دِيٜـٰرِهِمْ وَأُوذُواْ فِے سَبِيلِے وَقَٰتَلُواْ وَقُتِلُواْ لَأُكَفِّرَنَّ عَنْهُمْ سَيِّـَٔاتِهِمْ وَلَأُدْخِلَنَّهُمْ جَنَّٰتࣲ تَجْرِے مِن تَحْتِهَا ࡰ۬لَانْهَٰرُ ثَوَاباࣰ مِّنْ عِندِ ࡴ۬للَّهِ࣌ وَاللَّهُ عِندَهُۥ حُسْنُ ࡲ۬لثَّوَابِ࣌', 'فاستجاب لهم ربهم أنے لا أضيع عمل عمل منكم من ذكر ࡰو ࡳنثى࣌ بعضكم من بعض࣌ فالذين هاجروا وأخرجوا من ديرهم وأوذوا فے سبيلے وقتلوا وقتلوا لأكفرن عنهم سياتهم ولأدخلنهم جنت تجرے من تحتها ࡰلانهر ثوابا من عند ࡴلله࣌ والله عنده حسن ࡲلثواب࣌', NULL, 76, 'local:warsh-text.json'),
  ('warsh-3-196', 'warsh', 3, 196, '۞ لَا يَغُرَّنَّكَ تَقَلُّبُ ࡲ۬لذِينَ كَفَرُواْ فِے ࡴ۬لْبِلَٰدِ࣌', 'لا يغرنك تقلب ࡲلذين كفروا فے ࡴلبلد࣌', NULL, 76, 'local:warsh-text.json'),
  ('warsh-3-197', 'warsh', 3, 197, 'مَتَٰعࣱ قَلِيلࣱ࣌ ثُمَّ مَأْوٜيٰهُمْ جَهَنَّمُ࣌ وَبِيسَ ࡰ۬لْمِهَادُ࣌', 'متع قليل࣌ ثم مأويهم جهنم࣌ وبيس ࡰلمهاد࣌', NULL, 76, 'local:warsh-text.json'),
  ('warsh-3-198', 'warsh', 3, 198, 'لَٰكِنِ ࡴ۬لذِينَ ࡰٜتَّقَوْاْ رَبَّهُمْ لَهُمْ جَنَّٰتࣱ تَجْرِے مِن تَحْتِهَا ࡰ۬لَانْهَٰرُ خَٰلِدِينَ فِيهَا نُزُلاࣰ مِّنْ عِندِ ࡴ۬للَّهِ࣌ وَمَا عِندَ ࡰ۬للَّهِ خَيْرࣱ لِّلَابْرٜارِ࣌', 'لكن ࡴلذين ࡰتقوا ربهم لهم جنت تجرے من تحتها ࡰلانهر خلدين فيها نزلا من عند ࡴلله࣌ وما عند ࡰلله خير للابرار࣌', NULL, 76, 'local:warsh-text.json'),
  ('warsh-3-199', 'warsh', 3, 199, 'وَإِنَّ مِنَ ࡰهْلِ ࡴ۬لْكِتَٰبِ لَمَنْ يُّومِنُ بِاللَّهِ وَمَآ أُنزِلَ إِلَيْكُمْ وَمَآ أُنزِلَ إِلَيْهِمْ خَٰشِعِينَ لِلهِ࣌ لَا يَشْتَرُونَ بِـَٔايَٰتِ ࡴ۬للَّهِ ثَمَناࣰ قَلِيلاً࣌ ࡳوْلَٰٓئِكَ لَهُمُۥٓ أَجْرُهُمْ عِندَ رَبِّهِمُۥٓ࣌ إِنَّ ࡰ۬للَّهَ سَرِيعُ ࡲ۬لْحِسَابِ࣌', 'وإن من ࡰهل ࡴلكتب لمن يومن بالله وما أنزل إليكم وما أنزل إليهم خشعين لله࣌ لا يشترون بايت ࡴلله ثمنا قليلا࣌ ࡳولئك لهم أجرهم عند ربهم࣌ إن ࡰلله سريع ࡲلحساب࣌', NULL, 76, 'local:warsh-text.json'),
  ('warsh-3-200', 'warsh', 3, 200, 'يَٰٓأَيُّهَا ࡰ۬لذِينَ ءَامَنُواْ ࡲٜصْبِرُواْ وَصَابِرُواْ وَرَابِطُواْ وَاتَّقُواْ ࡲ۬للَّهَ لَعَلَّكُمْ تُفْلِحُونَ࣌', 'يأيها ࡰلذين ءامنوا ࡲصبروا وصابروا ورابطوا واتقوا ࡲلله لعلكم تفلحون࣌', NULL, 76, 'local:warsh-text.json'),
  ('warsh-4-1', 'warsh', 4, 1, 'يَٰٓأَيُّهَا ࡰ۬لنَّاسُ ࡲٜتَّقُواْ رَبَّكُمُ ࡲ۬لذِے خَلَقَكُم مِّن نَّفْسࣲ وَٰحِدَةࣲ وَخَلَقَ مِنْهَا زَوْجَهَا وَبَثَّ مِنْهُمَا رِجَالاࣰ كَثِيراࣰ وَنِسَآءࣰ࣌ وَاتَّقُواْ ࡲ۬للَّهَ ࡰ۬لذِے تَسَّآءَلُونَ بِهِۦ وَالَارْحَامَ࣌ إِنَّ ࡰ۬للَّهَ كَانَ عَلَيْكُمْ رَقِيباࣰ࣌', 'يأيها ࡰلناس ࡲتقوا ربكم ࡲلذے خلقكم من نفس وحدة وخلق منها زوجها وبث منهما رجالا كثيرا ونساء࣌ واتقوا ࡲلله ࡰلذے تساءلون به والارحام࣌ إن ࡰلله كان عليكم رقيبا࣌', NULL, 77, 'local:warsh-text.json'),
  ('warsh-4-2', 'warsh', 4, 2, 'وَءَاتُواْ ࡲ۬لْيَتَٰمٜىٰٓ أَمْوَٰلَهُمْ࣌ وَلَا تَتَبَدَّلُواْ ࡲ۬لْخَبِيثَ بِالطَّيِّبِ࣌ وَلَا تَاكُلُوٓاْ أَمْوَٰلَهُمُۥٓ إِلَىٰٓ أَمْوَٰلِكُمُۥٓ࣌ إِنَّهُۥ كَانَ حُوباࣰ كَبِيراࣰ࣌', 'وءاتوا ࡲليتمى أمولهم࣌ ولا تتبدلوا ࡲلخبيث بالطيب࣌ ولا تاكلوا أمولهم إلى أمولكم࣌ إنه كان حوبا كبيرا࣌', NULL, 77, 'local:warsh-text.json'),
  ('warsh-4-3', 'warsh', 4, 3, 'وَإِنْ خِفْتُمُۥٓ أَلَّا تُقْسِطُواْ فِے ࡴ۬لْيَتَٰمٜىٰ فَانكِحُواْ مَا طَابَ لَكُم مِّنَ ࡰ۬لنِّسَآءِ مَثْنٜىٰ وَثُلَٰثَ وَرُبَٰعَ࣌ فَإِنْ خِفْتُمُۥٓ أَلَّا تَعْدِلُواْ فَوَٰحِدَةً ࡰوْ مَا مَلَكَتَ ࡰيْمَٰنُكُمْ࣌ ذَٰلِكَ أَدْنٜىٰٓ أَلَّا تَعُولُواْ࣌', 'وإن خفتم ألا تقسطوا فے ࡴليتمى فانكحوا ما طاب لكم من ࡰلنساء مثنى وثلث وربع࣌ فإن خفتم ألا تعدلوا فوحدة ࡰو ما ملكت ࡰيمنكم࣌ ذلك أدنى ألا تعولوا࣌', NULL, 77, 'local:warsh-text.json'),
  ('warsh-4-4', 'warsh', 4, 4, 'وَءَاتُواْ ࡲ۬لنِّسَآءَ صَدُقَٰتِهِنَّ نِحْلَةࣰ࣌ فَإِن طِبْنَ لَكُمْ عَن شَےْءࣲ مِّنْهُ نَفْساࣰ فَكُلُوهُ࣌ هَنِيٓـٔاࣰ مَّرِيٓـٔاࣰ࣌', 'وءاتوا ࡲلنساء صدقتهن نحلة࣌ فإن طبن لكم عن شےء منه نفسا فكلوه࣌ هنيا مريا࣌', NULL, 77, 'local:warsh-text.json'),
  ('warsh-4-5', 'warsh', 4, 5, 'وَلَا تُوتُواْ ࡲ۬لسُّفَهَآءَ امْوَٰلَكُمُ ࡲ۬لتِے جَعَلَ ࡰ۬للَّهُ لَكُمْ قِيَماࣰ࣌ وَارْزُقُوهُمْ فِيهَا وَاكْسُوهُمْ وَقُولُواْ لَهُمْ قَوْلاࣰ مَّعْرُوفاࣰ࣌', 'ولا توتوا ࡲلسفهاء امولكم ࡲلتے جعل ࡰلله لكم قيما࣌ وارزقوهم فيها واكسوهم وقولوا لهم قولا معروفا࣌', NULL, 77, 'local:warsh-text.json'),
  ('warsh-4-6', 'warsh', 4, 6, '۞ وَابْتَلُواْ ࡲ۬لْيَتَٰمٜىٰ حَتَّىٰٓ إِذَا بَلَغُواْ ࡲ۬لنِّكَاحَ فَإِنَ اٰنَسْتُم مِّنْهُمْ رُشْداࣰ فَادْفَعُوٓاْ إِلَيْهِمُۥٓ أَمْوَٰلَهُمْ وَلَا تَاكُلُوهَآ إِسْرَافاࣰ وَبِدَاراً ࡰنْ يَّكْبَرُواْ࣌ وَمَن كَانَ غَنِيّاࣰ فَلْيَسْتَعْفِفْ࣌ وَمَن كَانَ فَقِيراࣰ فَلْيَاكُلْ بِالْمَعْرُوفِ࣌ فَإِذَا دَفَعْتُمُۥٓ إِلَيْهِمُۥٓ أَمْوَٰلَهُمْ فَأَشْهِدُواْ عَلَيْهِمْ࣌ وَكَفٜىٰ بِاللَّهِ حَسِيباࣰ࣌', 'وابتلوا ࡲليتمى حتى إذا بلغوا ࡲلنكاح فإن انستم منهم رشدا فادفعوا إليهم أمولهم ولا تاكلوها إسرافا وبدارا ࡰن يكبروا࣌ ومن كان غنيا فليستعفف࣌ ومن كان فقيرا فلياكل بالمعروف࣌ فإذا دفعتم إليهم أمولهم فأشهدوا عليهم࣌ وكفى بالله حسيبا࣌', NULL, 77, 'local:warsh-text.json'),
  ('warsh-4-7', 'warsh', 4, 7, 'لِّلرِّجَالِ نَصِيبࣱ مِّمَّا تَرَكَ ࡰ۬لْوَٰلِدَٰنِ وَالَاقْرَبُونَ وَلِلنِّسَآءِ نَصِيبࣱ مِّمَّا تَرَكَ ࡰ۬لْوَٰلِدَٰنِ وَالَاقْرَبُونَ مِمَّا قَلَّ مِنْهُ أَوْ كَثُرَ࣌ نَصِيباࣰ مَّفْرُوضاࣰ࣌', 'للرجال نصيب مما ترك ࡰلولدن والاقربون وللنساء نصيب مما ترك ࡰلولدن والاقربون مما قل منه أو كثر࣌ نصيبا مفروضا࣌', NULL, 78, 'local:warsh-text.json'),
  ('warsh-4-8', 'warsh', 4, 8, 'وَإِذَا حَضَرَ ࡰ۬لْقِسْمَةَ أُوْلُواْ ࡲ۬لْقُرْبٜىٰ وَالْيَتَٰمٜىٰ وَالْمَسَٰكِينُ فَارْزُقُوهُم مِّنْهُ࣌ وَقُولُواْ لَهُمْ قَوْلاࣰ مَّعْرُوفاࣰ࣌', 'وإذا حضر ࡰلقسمة أولوا ࡲلقربى واليتمى والمسكين فارزقوهم منه࣌ وقولوا لهم قولا معروفا࣌', NULL, 78, 'local:warsh-text.json'),
  ('warsh-4-9', 'warsh', 4, 9, 'وَلْيَخْشَ ࡰ۬لذِينَ لَوْ تَرَكُواْ مِنْ خَلْفِهِمْ ذُرِّيَّةࣰ ضِعَٰفاً خَافُواْ عَلَيْهِمْ࣌ فَلْيَتَّقُواْ ࡲ۬للَّهَ وَلْيَقُولُواْ قَوْلاࣰ سَدِيداً࣌', 'وليخش ࡰلذين لو تركوا من خلفهم ذرية ضعفا خافوا عليهم࣌ فليتقوا ࡲلله وليقولوا قولا سديدا࣌', NULL, 78, 'local:warsh-text.json'),
  ('warsh-4-10', 'warsh', 4, 10, 'ࡴنَّ ࡰ۬لذِينَ يَاكُلُونَ أَمْوَٰلَ ࡰ۬لْيَتَٰمٜىٰ ظُلْماً ࡴنَّمَا يَاكُلُونَ فِے بُطُونِهِمْ نَاراࣰ࣌ وَسَيَصْلَوْنَ سَعِيراࣰ࣌', 'ࡴن ࡰلذين ياكلون أمول ࡰليتمى ظلما ࡴنما ياكلون فے بطونهم نارا࣌ وسيصلون سعيرا࣌', NULL, 78, 'local:warsh-text.json'),
  ('warsh-4-11', 'warsh', 4, 11, '۞ يُوصِيكُمُ ࡲ۬للَّهُ فِےٓ أَوْلَٰدِكُمْ࣌ لِلذَّكَرِ مِثْلُ حَظِّ ࡴ۬لُانثَيَيْنِ࣌ فَإِن كُنَّ نِسَآءࣰ فَوْقَ ࡰٜثْنَتَيْنِ فَلَهُنَّ ثُلُثَا مَا تَرَكَ࣌ وَإِن كَانَتْ وَٰحِدَةࣱ فَلَهَا ࡰ۬لنِّصْفُ࣌ وَلِأَبَوَيْهِ لِكُلِّ وَٰحِدࣲ مِّنْهُمَا ࡰ۬لسُّدُسُ مِمَّا تَرَكَ إِن كَانَ لَهُۥ وَلَدࣱ࣌ فَإِن لَّمْ يَكُن لَّهُۥ وَلَدࣱ وَوَرِثَهُۥٓ أَبَوَٰهُ فَلِأُمِّهِ ࡴ۬لثُّلُثُ࣌ فَإِن كَانَ لَهُۥٓ إِخْوَةࣱ فَلِأُمِّهِ ࡴ۬لسُّدُسُ࣌ مِنۢ بَعْدِ وَصِيَّةࣲ يُوصِے بِهَآ أَوْ دَيْنٍ࣌ اٰبَآؤُكُمْ وَأَبْنَآؤُكُمْ لَا تَدْرُونَ أَيُّهُمُۥٓ أَقْرَبُ لَكُمْ نَفْعاࣰ࣌ فَرِيضَةࣰ مِّنَ ࡰ۬للَّهِ࣌ إِنَّ ࡰ۬للَّهَ كَانَ عَلِيماً حَكِيماࣰ࣌', 'يوصيكم ࡲلله فے أولدكم࣌ للذكر مثل حظ ࡴلانثيين࣌ فإن كن نساء فوق ࡰثنتين فلهن ثلثا ما ترك࣌ وإن كانت وحدة فلها ࡰلنصف࣌ ولأبويه لكل وحد منهما ࡰلسدس مما ترك إن كان له ولد࣌ فإن لم يكن له ولد وورثه أبوه فلأمه ࡴلثلث࣌ فإن كان له إخوة فلأمه ࡴلسدس࣌ من بعد وصية يوصے بها أو دين࣌ اباؤكم وأبناؤكم لا تدرون أيهم أقرب لكم نفعا࣌ فريضة من ࡰلله࣌ إن ࡰلله كان عليما حكيما࣌', NULL, 78, 'local:warsh-text.json'),
  ('warsh-4-12', 'warsh', 4, 12, 'وَلَكُمْ نِصْفُ مَا تَرَكَ أَزْوَٰجُكُمُۥٓ إِن لَّمْ يَكُن لَّهُنَّ وَلَدࣱ࣌ فَإِن كَانَ لَهُنَّ وَلَدࣱ فَلَكُمُ ࡲ۬لرُّبُعُ مِمَّا تَرَكْنَ مِنۢ بَعْدِ وَصِيَّةࣲ يُوصِينَ بِهَآ أَوْ دَيْنࣲ࣌ وَلَهُنَّ ࡰ۬لرُّبُعُ مِمَّا تَرَكْتُمُۥٓ إِن لَّمْ يَكُن لَّكُمْ وَلَدࣱ࣌ فَإِن كَانَ لَكُمْ وَلَدࣱ فَلَهُنَّ ࡰ۬لثُّمُنُ مِمَّا تَرَكْتُم مِّنۢ بَعْدِ وَصِيَّةࣲ تُوصُونَ بِهَآ أَوْ دَيْنࣲ࣌ وَإِن كَانَ رَجُلࣱ يُورَثُ كَلَٰلَةً ࡰوِ ࡴٜمْرَأَةࣱ وَلَهُۥٓ أَخٌ ࡰوُ ࡳخْتࣱ فَلِكُلِّ وَٰحِدࣲ مِّنْهُمَا ࡰ۬لسُّدُسُ࣌ فَإِن كَانُوٓاْ أَكْثَرَ مِن ذَٰلِكَ فَهُمْ شُرَكَآءُ فِے ࡴ۬لثُّلُثِ مِنۢ بَعْدِ وَصِيَّةࣲ يُوصِے بِهَآ أَوْ دَيْنٍ غَيْرَ مُضَآرࣲّ࣌ وَصِيَّةࣰ مِّنَ ࡰ۬للَّهِ࣌ وَاللَّهُ عَلِيمٌ حَلِيمࣱ࣌', 'ولكم نصف ما ترك أزوجكم إن لم يكن لهن ولد࣌ فإن كان لهن ولد فلكم ࡲلربع مما تركن من بعد وصية يوصين بها أو دين࣌ ولهن ࡰلربع مما تركتم إن لم يكن لكم ولد࣌ فإن كان لكم ولد فلهن ࡰلثمن مما تركتم من بعد وصية توصون بها أو دين࣌ وإن كان رجل يورث كللة ࡰو ࡴمرأة وله أخ ࡰو ࡳخت فلكل وحد منهما ࡰلسدس࣌ فإن كانوا أكثر من ذلك فهم شركاء فے ࡴلثلث من بعد وصية يوصے بها أو دين غير مضار࣌ وصية من ࡰلله࣌ والله عليم حليم࣌', NULL, 79, 'local:warsh-text.json'),
  ('warsh-4-13', 'warsh', 4, 13, '۞ تِلْكَ حُدُودُ ࡲ۬للَّهِ࣌ وَمَنْ يُّطِعِ ࡴ۬للَّهَ وَرَسُولَهُۥ نُدْخِلْهُ جَنَّٰتࣲ تَجْرِے مِن تَحْتِهَا ࡰ۬لَانْهَٰرُ خَٰلِدِينَ فِيهَا࣌ وَذَٰلِكَ ࡰ۬لْفَوْزُ ࡲ۬لْعَظِيمُ࣌', 'تلك حدود ࡲلله࣌ ومن يطع ࡴلله ورسوله ندخله جنت تجرے من تحتها ࡰلانهر خلدين فيها࣌ وذلك ࡰلفوز ࡲلعظيم࣌', NULL, 79, 'local:warsh-text.json'),
  ('warsh-4-14', 'warsh', 4, 14, 'وَمَنْ يَّعْصِ ࡴ۬للَّهَ وَرَسُولَهُۥ وَيَتَعَدَّ حُدُودَهُۥ نُدْخِلْهُ نَاراً خَٰلِداࣰ فِيهَا࣌ وَلَهُۥ عَذَابࣱ مُّهِينࣱ࣌', 'ومن يعص ࡴلله ورسوله ويتعد حدوده ندخله نارا خلدا فيها࣌ وله عذاب مهين࣌', NULL, 79, 'local:warsh-text.json'),
  ('warsh-4-15', 'warsh', 4, 15, 'وَالتِے يَاتِينَ ࡰ۬لْفَٰحِشَةَ مِن نِّسَآئِكُمْ فَاسْتَشْهِدُواْ عَلَيْهِنَّ أَرْبَعَةࣰ مِّنكُمْ࣌ فَإِن شَهِدُواْ فَأَمْسِكُوهُنَّ فِے ࡴ۬لْبُيُوتِ حَتَّىٰ يَتَوَفّٜيٰهُنَّ ࡰ۬لْمَوْتُ أَوْ يَجْعَلَ ࡰ۬للَّهُ لَهُنَّ سَبِيلاࣰ࣌', 'والتے ياتين ࡰلفحشة من نسائكم فاستشهدوا عليهن أربعة منكم࣌ فإن شهدوا فأمسكوهن فے ࡴلبيوت حتى يتوفيهن ࡰلموت أو يجعل ࡰلله لهن سبيلا࣌', NULL, 80, 'local:warsh-text.json'),
  ('warsh-4-16', 'warsh', 4, 16, 'وَالذَٰنِ يَاتِيَٰنِهَا مِنكُمْ فَـَٔاذُوهُمَا࣌ فَإِن تَابَا وَأَصْلَحَا فَأَعْرِضُواْ عَنْهُمَآ࣌ إِنَّ ࡰ۬للَّهَ كَانَ تَوَّاباࣰ رَّحِيماً࣌', 'والذن ياتينها منكم فاذوهما࣌ فإن تابا وأصلحا فأعرضوا عنهما࣌ إن ࡰلله كان توابا رحيما࣌', NULL, 80, 'local:warsh-text.json'),
  ('warsh-4-17', 'warsh', 4, 17, 'ࡴنَّمَا ࡰ۬لتَّوْبَةُ عَلَى ࡰ۬للَّهِ لِلذِينَ يَعْمَلُونَ ࡰ۬لسُّوٓءَ بِجَهَٰلَةࣲ ثُمَّ يَتُوبُونَ مِن قَرِيبࣲ࣌ فَأُوْلَٰٓئِكَ يَتُوبُ ࡲ۬للَّهُ عَلَيْهِمْ࣌ وَكَانَ ࡰ۬للَّهُ عَلِيماً حَكِيماࣰ࣌', 'ࡴنما ࡰلتوبة على ࡰلله للذين يعملون ࡰلسوء بجهلة ثم يتوبون من قريب࣌ فأولئك يتوب ࡲلله عليهم࣌ وكان ࡰلله عليما حكيما࣌', NULL, 80, 'local:warsh-text.json'),
  ('warsh-4-18', 'warsh', 4, 18, 'وَلَيْسَتِ ࡴ۬لتَّوْبَةُ لِلذِينَ يَعْمَلُونَ ࡰ۬لسَّيِّـَٔاتِ حَتَّىٰٓ إِذَا حَضَرَ أَحَدَهُمُ ࡲ۬لْمَوْتُ قَالَ إِنِّے تُبْتُ ࡲ۬لَٰـنَ وَلَا ࡰ۬لذِينَ يَمُوتُونَ وَهُمْ كُفَّارٌ࣌ ࡳوْلَٰٓئِكَ أَعْتَدْنَا لَهُمْ عَذَاباً ࡰلِيماࣰ࣌', 'وليست ࡴلتوبة للذين يعملون ࡰلسيات حتى إذا حضر أحدهم ࡲلموت قال إنے تبت ࡲلن ولا ࡰلذين يموتون وهم كفار࣌ ࡳولئك أعتدنا لهم عذابا ࡰليما࣌', NULL, 80, 'local:warsh-text.json'),
  ('warsh-4-19', 'warsh', 4, 19, 'يَٰٓأَيُّهَا ࡰ۬لذِينَ ءَامَنُواْ لَا يَحِلُّ لَكُمُۥٓ أَن تَرِثُواْ ࡲ۬لنِّسَآءَ كَرْهاࣰ࣌ وَلَا تَعْضُلُوهُنَّ لِتَذْهَبُواْ بِبَعْضِ مَآ ءَاتَيْتُمُوهُنَّ إِلَّآ أَنْ يَّاتِينَ بِفَٰحِشَةࣲ مُّبَيِّنَةࣲ࣌ ۞ وَعَاشِرُوهُنَّ بِالْمَعْرُوفِ࣌ فَإِن كَرِهْتُمُوهُنَّ فَعَسٜىٰٓ أَن تَكْرَهُواْ شَيْـٔاࣰ وَيَجْعَلَ ࡰ۬للَّهُ فِيهِ خَيْراࣰ كَثِيراࣰ࣌', 'يأيها ࡰلذين ءامنوا لا يحل لكم أن ترثوا ࡲلنساء كرها࣌ ولا تعضلوهن لتذهبوا ببعض ما ءاتيتموهن إلا أن ياتين بفحشة مبينة࣌  وعاشروهن بالمعروف࣌ فإن كرهتموهن فعسى أن تكرهوا شيا ويجعل ࡰلله فيه خيرا كثيرا࣌', NULL, 80, 'local:warsh-text.json'),
  ('warsh-4-20', 'warsh', 4, 20, 'وَإِنَ ࡰرَدتُّمُ ࡲٜسْتِبْدَالَ زَوْجࣲ مَّكَانَ زَوْجࣲ وَءَاتَيْتُمُۥٓ إِحْدٜيٰهُنَّ قِنطَاراࣰ فَلَا تَاخُذُواْ مِنْهُ شَيْـٔاً࣌ ࡰتَاخُذُونَهُۥ بُهْتَٰناࣰ وَإِثْماࣰ مُّبِيناࣰ࣌', 'وإن ࡰردتم ࡲستبدال زوج مكان زوج وءاتيتم إحديهن قنطارا فلا تاخذوا منه شيا࣌ ࡰتاخذونه بهتنا وإثما مبينا࣌', NULL, 81, 'local:warsh-text.json'),
  ('warsh-4-21', 'warsh', 4, 21, 'وَكَيْفَ تَاخُذُونَهُۥ وَقَدَ ࡰفْضٜىٰ بَعْضُكُمُۥٓ إِلَىٰ بَعْضࣲ وَأَخَذْنَ مِنكُم مِّيثَٰقاً غَلِيظاࣰ࣌', 'وكيف تاخذونه وقد ࡰفضى بعضكم إلى بعض وأخذن منكم ميثقا غليظا࣌', NULL, 81, 'local:warsh-text.json'),
  ('warsh-4-22', 'warsh', 4, 22, 'وَلَا تَنكِحُواْ مَا نَكَحَ ءَابَآؤُكُم مِّنَ ࡰ۬لنِّسَآءِ الَّا مَا قَدْ سَلَفَ࣌ إِنَّهُۥ كَانَ فَٰحِشَةࣰ وَمَقْتاࣰ࣌ وَسَآءَ سَبِيلاً࣌', 'ولا تنكحوا ما نكح ءاباؤكم من ࡰلنساء الا ما قد سلف࣌ إنه كان فحشة ومقتا࣌ وساء سبيلا࣌', NULL, 81, 'local:warsh-text.json'),
  ('warsh-4-23', 'warsh', 4, 23, 'حُرِّمَتْ عَلَيْكُمُۥٓ أُمَّهَٰتُكُمْ وَبَنَاتُكُمْ وَأَخَوَٰتُكُمْ وَعَمَّٰتُكُمْ وَخَٰلَٰتُكُمْ وَبَنَاتُ ࡲ۬لَاخِ وَبَنَاتُ ࡲ۬لُاخْتِ࣌ وَأُمَّهَٰتُكُمُ ࡲ۬لتِےٓ أَرْضَعْنَكُمْ وَأَخَوَٰتُكُم مِّنَ ࡰ۬لرَّضَٰعَةِ࣌ وَأُمَّهَٰتُ نِسَآئِكُمْ وَرَبَٰٓئِبُكُمُ ࡲ۬لتِے فِے حُجُورِكُم مِّن نِّسَآئِكُمُ ࡲ۬لتِے دَخَلْتُم بِهِنَّ࣌ فَإِن لَّمْ تَكُونُواْ دَخَلْتُم بِهِنَّ فَلَا جُنَاحَ عَلَيْكُمْ࣌ وَحَلَٰٓئِلُ أَبْنَآئِكُمُ ࡲ۬لذِينَ مِنَ ࡰصْلَٰبِكُمْ࣌ وَأَن تَجْمَعُواْ بَيْنَ ࡰ۬لُاخْتَيْنِ إِلَّا مَا قَدْ سَلَفَ࣌ إِنَّ ࡰ۬للَّهَ كَانَ غَفُوراࣰ رَّحِيماࣰ࣌', 'حرمت عليكم أمهتكم وبناتكم وأخوتكم وعمتكم وخلتكم وبنات ࡲلاخ وبنات ࡲلاخت࣌ وأمهتكم ࡲلتے أرضعنكم وأخوتكم من ࡰلرضعة࣌ وأمهت نسائكم وربئبكم ࡲلتے فے حجوركم من نسائكم ࡲلتے دخلتم بهن࣌ فإن لم تكونوا دخلتم بهن فلا جناح عليكم࣌ وحلئل أبنائكم ࡲلذين من ࡰصلبكم࣌ وأن تجمعوا بين ࡰلاختين إلا ما قد سلف࣌ إن ࡰلله كان غفورا رحيما࣌', NULL, 81, 'local:warsh-text.json'),
  ('warsh-4-24', 'warsh', 4, 24, '۞ وَالْمُحْصَنَٰتُ مِنَ ࡰ۬لنِّسَآءِ الَّا مَا مَلَكَتَ ࡰيْمَٰنُكُمْ࣌ كِتَٰبَ ࡰ۬للَّهِ عَلَيْكُمْ࣌ وَأَحَلَّ لَكُم مَّا وَرَآءَ ذَٰلِكُمُۥٓ أَن تَبْتَغُواْ بِأَمْوَٰلِكُم مُّحْصِنِينَ غَيْرَ مُسَٰفِحِينَ࣌ فَمَا ࡰٜسْتَمْتَعْتُم بِهِۦ مِنْهُنَّ فَـَٔاتُوهُنَّ أُجُورَهُنَّ فَرِيضَةࣰ࣌ وَلَا جُنَاحَ عَلَيْكُمْ فِيمَا تَرَٰضَيْتُم بِهِۦ مِنۢ بَعْدِ ࡴ۬لْفَرِيضَةِ࣌ إِنَّ ࡰ۬للَّهَ كَانَ عَلِيماً حَكِيماࣰ࣌', 'والمحصنت من ࡰلنساء الا ما ملكت ࡰيمنكم࣌ كتب ࡰلله عليكم࣌ وأحل لكم ما وراء ذلكم أن تبتغوا بأمولكم محصنين غير مسفحين࣌ فما ࡰستمتعتم به منهن فاتوهن أجورهن فريضة࣌ ولا جناح عليكم فيما ترضيتم به من بعد ࡴلفريضة࣌ إن ࡰلله كان عليما حكيما࣌', NULL, 82, 'local:warsh-text.json'),
  ('warsh-4-25', 'warsh', 4, 25, 'وَمَن لَّمْ يَسْتَطِعْ مِنكُمْ طَوْلاً ࡰنْ يَّنكِحَ ࡰ۬لْمُحْصَنَٰتِ ࡴ۬لْمُومِنَٰتِ فَمِن مَّا مَلَكَتَ ࡰيْمَٰنُكُم مِّن فَتَيَٰتِكُمُ ࡲ۬لْمُومِنَٰتِ࣌ وَاللَّهُ أَعْلَمُ بِإِيمَٰنِكُم࣌ بَعْضُكُم مِّنۢ بَعْضࣲ࣌ فَانكِحُوهُنَّ بِإِذْنِ أَهْلِهِنَّ࣌ وَءَاتُوهُنَّ أُجُورَهُنَّ بِالْمَعْرُوفِ مُحْصَنَٰتٍ غَيْرَ مُسَٰفِحَٰتࣲ وَلَا مُتَّخِذَٰتِ أَخْدَانࣲ࣌ فَإِذَآ أُحْصِنَّ فَإِنَ ࡰتَيْنَ بِفَٰحِشَةࣲ فَعَلَيْهِنَّ نِصْفُ مَا عَلَى ࡰ۬لْمُحْصَنَٰتِ مِنَ ࡰ۬لْعَذَابِ࣌ ذَٰلِكَ لِمَنْ خَشِيَ ࡰ۬لْعَنَتَ مِنكُمْ࣌ وَأَن تَصْبِرُواْ خَيْرࣱ لَّكُمْ࣌ وَاللَّهُ غَفُورࣱ رَّحِيمࣱ࣌', 'ومن لم يستطع منكم طولا ࡰن ينكح ࡰلمحصنت ࡴلمومنت فمن ما ملكت ࡰيمنكم من فتيتكم ࡲلمومنت࣌ والله أعلم بإيمنكم࣌ بعضكم من بعض࣌ فانكحوهن بإذن أهلهن࣌ وءاتوهن أجورهن بالمعروف محصنت غير مسفحت ولا متخذت أخدان࣌ فإذا أحصن فإن ࡰتين بفحشة فعليهن نصف ما على ࡰلمحصنت من ࡰلعذاب࣌ ذلك لمن خشي ࡰلعنت منكم࣌ وأن تصبروا خير لكم࣌ والله غفور رحيم࣌', NULL, 82, 'local:warsh-text.json'),
  ('warsh-4-26', 'warsh', 4, 26, 'يُرِيدُ ࡲ۬للَّهُ لِيُبَيِّنَ لَكُمْ وَيَهْدِيَكُمْ سُنَنَ ࡰ۬لذِينَ مِن قَبْلِكُمْ وَيَتُوبَ عَلَيْكُمْ࣌ وَاللَّهُ عَلِيمٌ حَكِيمࣱ࣌', 'يريد ࡲلله ليبين لكم ويهديكم سنن ࡰلذين من قبلكم ويتوب عليكم࣌ والله عليم حكيم࣌', NULL, 82, 'local:warsh-text.json'),
  ('warsh-4-27', 'warsh', 4, 27, 'وَاللَّهُ يُرِيدُ أَنْ يَّتُوبَ عَلَيْكُمْ࣌ وَيُرِيدُ ࡲ۬لذِينَ يَتَّبِعُونَ ࡰ۬لشَّهَوَٰتِ أَن تَمِيلُواْ مَيْلاً عَظِيماࣰ࣌', 'والله يريد أن يتوب عليكم࣌ ويريد ࡲلذين يتبعون ࡰلشهوت أن تميلوا ميلا عظيما࣌', NULL, 83, 'local:warsh-text.json'),
  ('warsh-4-28', 'warsh', 4, 28, 'يُرِيدُ ࡲ۬للَّهُ أَنْ يُّخَفِّفَ عَنكُمْ࣌ وَخُلِقَ ࡰ۬لِانسَٰنُ ضَعِيفاࣰ࣌', 'يريد ࡲلله أن يخفف عنكم࣌ وخلق ࡰلانسن ضعيفا࣌', NULL, 83, 'local:warsh-text.json'),
  ('warsh-4-29', 'warsh', 4, 29, '۞ يَٰٓأَيُّهَا ࡰ۬لذِينَ ءَامَنُواْ لَا تَاكُلُوٓاْ أَمْوَٰلَكُم بَيْنَكُم بِالْبَٰطِلِ࣌ إِلَّآ أَن تَكُونَ تِجَٰرَةٌ عَن تَرَاضࣲ مِّنكُمْ࣌ وَلَا تَقْتُلُوٓاْ أَنفُسَكُمُۥٓ࣌ إِنَّ ࡰ۬للَّهَ كَانَ بِكُمْ رَحِيماࣰ࣌', 'يأيها ࡰلذين ءامنوا لا تاكلوا أمولكم بينكم بالبطل࣌ إلا أن تكون تجرة عن تراض منكم࣌ ولا تقتلوا أنفسكم࣌ إن ࡰلله كان بكم رحيما࣌', NULL, 83, 'local:warsh-text.json'),
  ('warsh-4-30', 'warsh', 4, 30, 'وَمَنْ يَّفْعَلْ ذَٰلِكَ عُدْوَٰناࣰ وَظُلْماࣰ فَسَوْفَ نُصْلِيهِ نَاراࣰ࣌ وَكَانَ ذَٰلِكَ عَلَى ࡰ۬للَّهِ يَسِيراً࣌', 'ومن يفعل ذلك عدونا وظلما فسوف نصليه نارا࣌ وكان ذلك على ࡰلله يسيرا࣌', NULL, 83, 'local:warsh-text.json'),
  ('warsh-4-31', 'warsh', 4, 31, 'ࡴن تَجْتَنِبُواْ كَبَآئِرَ مَا تُنْهَوْنَ عَنْهُ نُكَفِّرْ عَنكُمْ سَيِّـَٔاتِكُمْ وَنُدْخِلْكُم مَّدْخَلاࣰ كَرِيماࣰ࣌', 'ࡴن تجتنبوا كبائر ما تنهون عنه نكفر عنكم سياتكم وندخلكم مدخلا كريما࣌', NULL, 83, 'local:warsh-text.json'),
  ('warsh-4-32', 'warsh', 4, 32, 'وَلَا تَتَمَنَّوْاْ مَا فَضَّلَ ࡰ۬للَّهُ بِهِۦ بَعْضَكُمْ عَلَىٰ بَعْضࣲ࣌ لِّلرِّجَالِ نَصِيبࣱ مِّمَّا ࡰٜكْتَسَبُواْ࣌ وَلِلنِّسَآءِ نَصِيبࣱ مِّمَّا ࡰٜكْتَسَبْنَ࣌ وَسْـَٔلُواْ ࡲ۬للَّهَ مِن فَضْلِهِۦٓ࣌ إِنَّ ࡰ۬للَّهَ كَانَ بِكُلِّ شَےْءٍ عَلِيماࣰ࣌', 'ولا تتمنوا ما فضل ࡰلله به بعضكم على بعض࣌ للرجال نصيب مما ࡰكتسبوا࣌ وللنساء نصيب مما ࡰكتسبن࣌ وسلوا ࡲلله من فضله࣌ إن ࡰلله كان بكل شےء عليما࣌', NULL, 83, 'local:warsh-text.json'),
  ('warsh-4-33', 'warsh', 4, 33, 'وَلِكُلࣲّ جَعَلْنَا مَوَٰلِيَ مِمَّا تَرَكَ࣌ ࡰ۬لْوَٰلِدَٰنِ وَالَاقْرَبُونَ࣌ وَالذِينَ عَٰقَدَتَ ࡰيْمَٰنُكُمْ فَـَٔاتُوهُمْ نَصِيبَهُمُۥٓ࣌ إِنَّ ࡰ۬للَّهَ كَانَ عَلَىٰ كُلِّ شَےْءࣲ شَهِيداً࣌', 'ولكل جعلنا مولي مما ترك࣌ ࡰلولدن والاقربون࣌ والذين عقدت ࡰيمنكم فاتوهم نصيبهم࣌ إن ࡰلله كان على كل شےء شهيدا࣌', NULL, 83, 'local:warsh-text.json'),
  ('warsh-4-34', 'warsh', 4, 34, 'ࡴ۬لرِّجَالُ قَوَّٰمُونَ عَلَى ࡰ۬لنِّسَآءِ بِمَا فَضَّلَ ࡰ۬للَّهُ بَعْضَهُمْ عَلَىٰ بَعْضࣲ وَبِمَآ أَنفَقُواْ مِنَ ࡰمْوَٰلِهِمْ࣌ فَالصَّٰلِحَٰتُ قَٰنِتَٰتٌ حَٰفِظَٰتࣱ لِّلْغَيْبِ بِمَا حَفِظَ ࡰ۬للَّهُ࣌ وَالتِے تَخَافُونَ نُشُوزَهُنَّ فَعِظُوهُنَّ وَاهْجُرُوهُنَّ فِے ࡴ۬لْمَضَاجِعِ وَاضْرِبُوهُنَّ࣌ فَإِنَ ࡰطَعْنَكُمْ فَلَا تَبْغُواْ عَلَيْهِنَّ سَبِيلاً࣌ ࡴنَّ ࡰ۬للَّهَ كَانَ عَلِيّاࣰ كَبِيراࣰ࣌', 'ࡴلرجال قومون على ࡰلنساء بما فضل ࡰلله بعضهم على بعض وبما أنفقوا من ࡰمولهم࣌ فالصلحت قنتت حفظت للغيب بما حفظ ࡰلله࣌ والتے تخافون نشوزهن فعظوهن واهجروهن فے ࡴلمضاجع واضربوهن࣌ فإن ࡰطعنكم فلا تبغوا عليهن سبيلا࣌ ࡴن ࡰلله كان عليا كبيرا࣌', NULL, 84, 'local:warsh-text.json'),
  ('warsh-4-35', 'warsh', 4, 35, 'وَإِنْ خِفْتُمْ شِقَاقَ بَيْنِهِمَا فَابْعَثُواْ حَكَماࣰ مِّنَ ࡰهْلِهِۦ وَحَكَماࣰ مِّنَ ࡰهْلِهَآ إِنْ يُّرِيدَآ إِصْلَٰحاࣰ يُوَفِّقِ ࡴ۬للَّهُ بَيْنَهُمَآ࣌ إِنَّ ࡰ۬للَّهَ كَانَ عَلِيماً خَبِيراࣰ࣌', 'وإن خفتم شقاق بينهما فابعثوا حكما من ࡰهله وحكما من ࡰهلها إن يريدا إصلحا يوفق ࡴلله بينهما࣌ إن ࡰلله كان عليما خبيرا࣌', NULL, 84, 'local:warsh-text.json'),
  ('warsh-4-36', 'warsh', 4, 36, '۞ وَاعْبُدُواْ ࡲ۬للَّهَ࣌ وَلَا تُشْرِكُواْ بِهِۦ شَيْـٔاࣰ࣌ وَبِالْوَٰلِدَيْنِ إِحْسَٰناࣰ وَبِذِے ࡴ۬لْقُرْبٜىٰ وَالْيَتَٰمٜىٰ وَالْمَسَٰكِينِ وَالْجٜارِ ذِے ࡴ۬لْقُرْبٜىٰ وَالْجٜارِ ࡴ۬لْجُنُبِ وَالصَّٰحِبِ بِالْجَنۢبِ وَابْنِ ࡴ۬لسَّبِيلِ وَمَا مَلَكَتَ ࡰيْمَٰنُكُمُۥٓ࣌ إِنَّ ࡰ۬للَّهَ لَا يُحِبُّ مَن كَانَ مُخْتَالاࣰ فَخُوراً࣌', 'واعبدوا ࡲلله࣌ ولا تشركوا به شيا࣌ وبالولدين إحسنا وبذے ࡴلقربى واليتمى والمسكين والجار ذے ࡴلقربى والجار ࡴلجنب والصحب بالجنب وابن ࡴلسبيل وما ملكت ࡰيمنكم࣌ إن ࡰلله لا يحب من كان مختالا فخورا࣌', NULL, 84, 'local:warsh-text.json'),
  ('warsh-4-37', 'warsh', 4, 37, 'ࡴ۬لذِينَ يَبْخَلُونَ وَيَامُرُونَ ࡰ۬لنَّاسَ بِالْبُخْلِ وَيَكْتُمُونَ مَآ ءَاتٜيٰهُمُ ࡲ۬للَّهُ مِن فَضْلِهِۦ࣌ وَأَعْتَدْنَا لِلْكٜـٰفِرِينَ عَذَاباࣰ مُّهِيناࣰ࣌', 'ࡴلذين يبخلون ويامرون ࡰلناس بالبخل ويكتمون ما ءاتيهم ࡲلله من فضله࣌ وأعتدنا للكفرين عذابا مهينا࣌', NULL, 84, 'local:warsh-text.json'),
  ('warsh-4-38', 'warsh', 4, 38, 'وَالذِينَ يُنفِقُونَ أَمْوَٰلَهُمْ رِئَآءَ ࡰ۬لنَّاسِ وَلَا يُومِنُونَ بِاللَّهِ وَلَا بِالْيَوْمِ ࡴ۬لَاخِرِ࣌ وَمَنْ يَّكُنِ ࡴ۬لشَّيْطَٰنُ لَهُۥ قَرِيناࣰ فَسَآءَ قَرِيناࣰ࣌', 'والذين ينفقون أمولهم رئاء ࡰلناس ولا يومنون بالله ولا باليوم ࡴلاخر࣌ ومن يكن ࡴلشيطن له قرينا فساء قرينا࣌', NULL, 85, 'local:warsh-text.json'),
  ('warsh-4-39', 'warsh', 4, 39, 'وَمَاذَا عَلَيْهِمْ لَوَ اٰمَنُواْ بِاللَّهِ وَالْيَوْمِ ࡴ۬لَاخِرِ وَأَنفَقُواْ مِمَّا رَزَقَهُمُ ࡲ۬للَّهُ࣌ وَكَانَ ࡰ۬للَّهُ بِهِمْ عَلِيماً࣌', 'وماذا عليهم لو امنوا بالله واليوم ࡴلاخر وأنفقوا مما رزقهم ࡲلله࣌ وكان ࡰلله بهم عليما࣌', NULL, 85, 'local:warsh-text.json'),
  ('warsh-4-40', 'warsh', 4, 40, 'ࡴنَّ ࡰ۬للَّهَ لَا يَظْلِمُ مِثْقَالَ ذَرَّةࣲ࣌ وَإِن تَكُ حَسَنَةࣱ يُضَٰعِفْهَا وَيُوتِ مِن لَّدُنْهُ أَجْراً عَظِيماࣰ࣌', 'ࡴن ࡰلله لا يظلم مثقال ذرة࣌ وإن تك حسنة يضعفها ويوت من لدنه أجرا عظيما࣌', NULL, 85, 'local:warsh-text.json'),
  ('warsh-4-41', 'warsh', 4, 41, 'فَكَيْفَ إِذَا جِئْنَا مِن كُلِّ أُمَّةِۢ بِشَهِيدࣲ وَجِئْنَا بِكَ عَلَىٰ هَٰٓؤُلَآءِ شَهِيداࣰ࣌', 'فكيف إذا جئنا من كل أمة بشهيد وجئنا بك على هؤلاء شهيدا࣌', NULL, 85, 'local:warsh-text.json'),
  ('warsh-4-42', 'warsh', 4, 42, 'يَوْمَئِذࣲ يَوَدُّ ࡲ۬لذِينَ كَفَرُواْ وَعَصَوُاْ ࡲ۬لرَّسُولَ لَوْ تَسَّوّٜىٰ بِهِمُ ࡲ۬لَارْضُ وَلَا يَكْتُمُونَ ࡰ۬للَّهَ حَدِيثاࣰ࣌', 'يومئذ يود ࡲلذين كفروا وعصوا ࡲلرسول لو تسوى بهم ࡲلارض ولا يكتمون ࡰلله حديثا࣌', NULL, 85, 'local:warsh-text.json'),
  ('warsh-4-43', 'warsh', 4, 43, 'يَٰٓأَيُّهَا ࡰ۬لذِينَ ءَامَنُواْ لَا تَقْرَبُواْ ࡲ۬لصَّلَوٰةَ وَأَنتُمْ سُكَٰرٜىٰ حَتَّىٰ تَعْلَمُواْ مَا تَقُولُونَ وَلَا جُنُباً ࡴلَّا عَابِرِے سَبِيلٍ حَتَّىٰ تَغْتَسِلُواْ࣌ وَإِن كُنتُم مَّرْضٜىٰٓ أَوْ عَلَىٰ سَفَرٍ ࡰوْ جَآءَ احَدࣱ مِّنكُم مِّنَ ࡰ۬لْغَآئِطِ أَوْ لَٰمَسْتُمُ ࡲ۬لنِّسَآءَ فَلَمْ تَجِدُواْ مَآءࣰ فَتَيَمَّمُواْ صَعِيداࣰ طَيِّباࣰ فَامْسَحُواْ بِوُجُوهِكُمْ وَأَيْدِيكُمُۥٓ࣌ إِنَّ ࡰ۬للَّهَ كَانَ عَفُوّاً غَفُوراً࣌', 'يأيها ࡰلذين ءامنوا لا تقربوا ࡲلصلوة وأنتم سكرى حتى تعلموا ما تقولون ولا جنبا ࡴلا عابرے سبيل حتى تغتسلوا࣌ وإن كنتم مرضى أو على سفر ࡰو جاء احد منكم من ࡰلغائط أو لمستم ࡲلنساء فلم تجدوا ماء فتيمموا صعيدا طيبا فامسحوا بوجوهكم وأيديكم࣌ إن ࡰلله كان عفوا غفورا࣌', NULL, 85, 'local:warsh-text.json'),
  ('warsh-4-44', 'warsh', 4, 44, 'ࡰلَمْ تَرَ إِلَى ࡰ۬لذِينَ أُوتُواْ نَصِيباࣰ مِّنَ ࡰ۬لْكِتَٰبِ يَشْتَرُونَ ࡰ۬لضَّلَٰلَةَ وَيُرِيدُونَ أَن تَضِلُّواْ ࡲ۬لسَّبِيلَ࣌ وَاللَّهُ أَعْلَمُ بِأَعْدَآئِكُمْ࣌ وَكَفٜىٰ بِاللَّهِ وَلِيّاࣰ وَكَفٜىٰ بِاللَّهِ نَصِيراࣰ࣌', 'ࡰلم تر إلى ࡰلذين أوتوا نصيبا من ࡰلكتب يشترون ࡰلضللة ويريدون أن تضلوا ࡲلسبيل࣌ والله أعلم بأعدائكم࣌ وكفى بالله وليا وكفى بالله نصيرا࣌', NULL, 85, 'local:warsh-text.json'),
  ('warsh-4-45', 'warsh', 4, 45, '۞ مِّنَ ࡰ۬لذِينَ هَادُواْ يُحَرِّفُونَ ࡰ۬لْكَلِمَ عَن مَّوَاضِعِهِۦ وَيَقُولُونَ سَمِعْنَا وَعَصَيْنَا وَاسْمَعْ غَيْرَ مُسْمَعࣲ وَرَٰعِنَا لَيّاَۢ بِأَلْسِنَتِهِمْ وَطَعْناࣰ فِے ࡴ۬لدِّينِ࣌ وَلَوَ ࡰنَّهُمْ قَالُواْ سَمِعْنَا وَأَطَعْنَا وَاسْمَعْ وَانظُرْنَا لَكَانَ خَيْراࣰ لَّهُمْ وَأَقْوَمَ࣌ وَلَٰكِن لَّعَنَهُمُ ࡲ۬للَّهُ بِكُفْرِهِمْ فَلَا يُومِنُونَ إِلَّا قَلِيلاࣰ࣌', 'من ࡰلذين هادوا يحرفون ࡰلكلم عن مواضعه ويقولون سمعنا وعصينا واسمع غير مسمع ورعنا ليا بألسنتهم وطعنا فے ࡴلدين࣌ ولو ࡰنهم قالوا سمعنا وأطعنا واسمع وانظرنا لكان خيرا لهم وأقوم࣌ ولكن لعنهم ࡲلله بكفرهم فلا يومنون إلا قليلا࣌', NULL, 86, 'local:warsh-text.json'),
  ('warsh-4-46', 'warsh', 4, 46, 'يَٰٓأَيُّهَا ࡰ۬لذِينَ أُوتُواْ ࡲ۬لْكِتَٰبَ ءَامِنُواْ بِمَا نَزَّلْنَا مُصَدِّقاࣰ لِّمَا مَعَكُم مِّن قَبْلِ أَن نَّطْمِسَ وُجُوهاࣰ فَنَرُدَّهَا عَلَىٰٓ أَدْبٜـٰرِهَآ أَوْ نَلْعَنَهُمْ كَمَا لَعَنَّآ أَصْحَٰبَ ࡰ۬لسَّبْتِ࣌ وَكَانَ أَمْرُ ࡲ۬للَّهِ مَفْعُولاً࣌', 'يأيها ࡰلذين أوتوا ࡲلكتب ءامنوا بما نزلنا مصدقا لما معكم من قبل أن نطمس وجوها فنردها على أدبرها أو نلعنهم كما لعنا أصحب ࡰلسبت࣌ وكان أمر ࡲلله مفعولا࣌', NULL, 86, 'local:warsh-text.json'),
  ('warsh-4-47', 'warsh', 4, 47, 'ࡴنَّ ࡰ۬للَّهَ لَا يَغْفِرُ أَنْ يُّشْرَكَ بِهِۦ࣌ وَيَغْفِرُ مَا دُونَ ذَٰلِكَ لِمَنْ يَّشَآءُ࣌ وَمَنْ يُّشْرِكْ بِاللَّهِ فَقَدِ ࡴٜفْتَرٜىٰٓ إِثْماً عَظِيماً࣌', 'ࡴن ࡰلله لا يغفر أن يشرك به࣌ ويغفر ما دون ذلك لمن يشاء࣌ ومن يشرك بالله فقد ࡴفترى إثما عظيما࣌', NULL, 86, 'local:warsh-text.json'),
  ('warsh-4-48', 'warsh', 4, 48, 'ࡰلَمْ تَرَ إِلَى ࡰ۬لذِينَ يُزَكُّونَ أَنفُسَهُم࣌ بَلِ ࡴ۬للَّهُ يُزَكِّے مَنْ يَّشَآءُ࣌ وَلَا يُظْلَمُونَ فَتِيلاً࣌', 'ࡰلم تر إلى ࡰلذين يزكون أنفسهم࣌ بل ࡴلله يزكے من يشاء࣌ ولا يظلمون فتيلا࣌', NULL, 86, 'local:warsh-text.json'),
  ('warsh-4-49', 'warsh', 4, 49, 'ࡲ࢈نظُرْ كَيْفَ يَفْتَرُونَ عَلَى ࡰ۬للَّهِ ࡴ۬لْكَذِبَ وَكَفٜىٰ بِهِۦٓ إِثْماࣰ مُّبِيناً࣌', 'ࡲ࢈نظر كيف يفترون على ࡰلله ࡴلكذب وكفى به إثما مبينا࣌', NULL, 86, 'local:warsh-text.json'),
  ('warsh-4-50', 'warsh', 4, 50, 'ࡰلَمْ تَرَ إِلَى ࡰ۬لذِينَ أُوتُواْ نَصِيباࣰ مِّنَ ࡰ۬لْكِتَٰبِ يُومِنُونَ بِالْجِبْتِ وَالطَّٰغُوتِ وَيَقُولُونَ لِلذِينَ كَفَرُواْ هَٰٓؤُلَآءِ ࡶَهْدٜىٰ مِنَ ࡰ۬لذِينَ ءَامَنُواْ سَبِيلاً࣌', 'ࡰلم تر إلى ࡰلذين أوتوا نصيبا من ࡰلكتب يومنون بالجبت والطغوت ويقولون للذين كفروا هؤلاء ࡶهدى من ࡰلذين ءامنوا سبيلا࣌', NULL, 86, 'local:warsh-text.json'),
  ('warsh-4-51', 'warsh', 4, 51, 'ࡳوْلَٰٓئِكَ ࡰ۬لذِينَ لَعَنَهُمُ ࡲ۬للَّهُ࣌ وَمَنْ يَّلْعَنِ ࡴ۬للَّهُ فَلَن تَجِدَ لَهُۥ نَصِيراً࣌', 'ࡳولئك ࡰلذين لعنهم ࡲلله࣌ ومن يلعن ࡴلله فلن تجد له نصيرا࣌', NULL, 87, 'local:warsh-text.json'),
  ('warsh-4-52', 'warsh', 4, 52, 'ࡰمْ لَهُمْ نَصِيبࣱ مِّنَ ࡰ۬لْمُلْكِ فَإِذاࣰ لَّا يُوتُونَ ࡰ۬لنَّاسَ نَقِيراً࣌', 'ࡰم لهم نصيب من ࡰلملك فإذا لا يوتون ࡰلناس نقيرا࣌', NULL, 87, 'local:warsh-text.json'),
  ('warsh-4-53', 'warsh', 4, 53, 'ࡰمْ يَحْسُدُونَ ࡰ۬لنَّاسَ عَلَىٰ مَآ ءَاتٜيٰهُمُ ࡲ۬للَّهُ مِن فَضْلِهِۦ࣌ فَقَدَ اٰتَيْنَآ ءَالَ إِبْرَٰهِيمَ ࡰ۬لْكِتَٰبَ وَالْحِكْمَةَ وَءَاتَيْنَٰهُم مُّلْكاً عَظِيماࣰ࣌', 'ࡰم يحسدون ࡰلناس على ما ءاتيهم ࡲلله من فضله࣌ فقد اتينا ءال إبرهيم ࡰلكتب والحكمة وءاتينهم ملكا عظيما࣌', NULL, 87, 'local:warsh-text.json'),
  ('warsh-4-54', 'warsh', 4, 54, 'فَمِنْهُم مَّنَ اٰمَنَ بِهِۦ وَمِنْهُم مَّن صَدَّ عَنْهُ࣌ وَكَفٜىٰ بِجَهَنَّمَ سَعِيراً࣌', 'فمنهم من امن به ومنهم من صد عنه࣌ وكفى بجهنم سعيرا࣌', NULL, 87, 'local:warsh-text.json'),
  ('warsh-4-55', 'warsh', 4, 55, 'ࡴنَّ ࡰ۬لذِينَ كَفَرُواْ بِـَٔايَٰتِنَا سَوْفَ نُصْلِيهِمْ نَاراࣰ࣌ كُلَّمَا نَضِجَتْ جُلُودُهُم بَدَّلْنَٰهُمْ جُلُوداً غَيْرَهَا لِيَذُوقُواْ ࡲ۬لْعَذَابَ࣌ إِنَّ ࡰ۬للَّهَ كَانَ عَزِيزاً حَكِيماࣰ࣌', 'ࡴن ࡰلذين كفروا بايتنا سوف نصليهم نارا࣌ كلما نضجت جلودهم بدلنهم جلودا غيرها ليذوقوا ࡲلعذاب࣌ إن ࡰلله كان عزيزا حكيما࣌', NULL, 87, 'local:warsh-text.json'),
  ('warsh-4-56', 'warsh', 4, 56, 'وَالذِينَ ءَامَنُواْ وَعَمِلُواْ ࡲ۬لصَّٰلِحَٰتِ سَنُدْخِلُهُمْ جَنَّٰتࣲ تَجْرِے مِن تَحْتِهَا ࡰ۬لَانْهَٰرُ خَٰلِدِينَ فِيهَآ أَبَداࣰ࣌ لَّهُمْ فِيهَآ أَزْوَٰجࣱ مُّطَهَّرَةࣱ࣌ وَنُدْخِلُهُمْ ظِلّاࣰ ظَلِيلاً࣌', 'والذين ءامنوا وعملوا ࡲلصلحت سندخلهم جنت تجرے من تحتها ࡰلانهر خلدين فيها أبدا࣌ لهم فيها أزوج مطهرة࣌ وندخلهم ظلا ظليلا࣌', NULL, 87, 'local:warsh-text.json'),
  ('warsh-4-57', 'warsh', 4, 57, '۞ ࡴنَّ ࡰ۬للَّهَ يَامُرُكُمُۥٓ أَن تُوَ۬دُّواْ ࡲ۬لَامَٰنَٰتِ إِلَىٰٓ أَهْلِهَا وَإِذَا حَكَمْتُم بَيْنَ ࡰ۬لنَّاسِ أَن تَحْكُمُواْ بِالْعَدْلِ࣌ إِنَّ ࡰ۬للَّهَ نِعِمَّا يَعِظُكُم بِهِۦٓ࣌ إِنَّ ࡰ۬للَّهَ كَانَ سَمِيعاَۢ بَصِيراࣰ࣌', 'ࡴن ࡰلله يامركم أن تودوا ࡲلامنت إلى أهلها وإذا حكمتم بين ࡰلناس أن تحكموا بالعدل࣌ إن ࡰلله نعما يعظكم به࣌ إن ࡰلله كان سميعا بصيرا࣌', NULL, 87, 'local:warsh-text.json'),
  ('warsh-4-58', 'warsh', 4, 58, 'يَٰٓأَيُّهَا ࡰ۬لذِينَ ءَامَنُوٓاْ أَطِيعُواْ ࡲ۬للَّهَ وَأَطِيعُواْ ࡲ۬لرَّسُولَ وَأُوْلِے ࡴ۬لَامْرِ مِنكُمْ࣌ فَإِن تَنَٰزَعْتُمْ فِے شَےْءࣲ فَرُدُّوهُ إِلَى ࡰ۬للَّهِ وَالرَّسُولِ إِن كُنتُمْ تُومِنُونَ بِاللَّهِ وَالْيَوْمِ ࡴ۬لَاخِرِ࣌ ذَٰلِكَ خَيْرࣱ وَأَحْسَنُ تَاوِيلاً࣌', 'يأيها ࡰلذين ءامنوا أطيعوا ࡲلله وأطيعوا ࡲلرسول وأولے ࡴلامر منكم࣌ فإن تنزعتم فے شےء فردوه إلى ࡰلله والرسول إن كنتم تومنون بالله واليوم ࡴلاخر࣌ ذلك خير وأحسن تاويلا࣌', NULL, 87, 'local:warsh-text.json'),
  ('warsh-4-59', 'warsh', 4, 59, 'ࡰلَمْ تَرَ إِلَى ࡰ۬لذِينَ يَزْعُمُونَ أَنَّهُمُۥٓ ءَامَنُواْ بِمَآ أُنزِلَ إِلَيْكَ وَمَآ أُنزِلَ مِن قَبْلِكَ يُرِيدُونَ أَنْ يَّتَحَاكَمُوٓاْ إِلَى ࡰ۬لطَّٰغُوتِ وَقَدُ ࡳمِرُوٓاْ أَنْ يَّكْفُرُواْ بِهِۦ࣌ وَيُرِيدُ ࡲ۬لشَّيْطَٰنُ أَنْ يُّضِلَّهُمْ ضَلَٰلاَۢ بَعِيداࣰ࣌', 'ࡰلم تر إلى ࡰلذين يزعمون أنهم ءامنوا بما أنزل إليك وما أنزل من قبلك يريدون أن يتحاكموا إلى ࡰلطغوت وقد ࡳمروا أن يكفروا به࣌ ويريد ࡲلشيطن أن يضلهم ضللا بعيدا࣌', NULL, 88, 'local:warsh-text.json'),
  ('warsh-4-60', 'warsh', 4, 60, 'وَإِذَا قِيلَ لَهُمْ تَعَالَوِاْ ࡴلَىٰ مَآ أَنزَلَ ࡰ۬للَّهُ وَإِلَى ࡰ۬لرَّسُولِ رَأَيْتَ ࡰ۬لْمُنَٰفِقِينَ يَصُدُّونَ عَنكَ صُدُوداࣰ࣌', 'وإذا قيل لهم تعالوا ࡴلى ما أنزل ࡰلله وإلى ࡰلرسول رأيت ࡰلمنفقين يصدون عنك صدودا࣌', NULL, 88, 'local:warsh-text.json'),
  ('warsh-4-61', 'warsh', 4, 61, 'فَكَيْفَ إِذَآ أَصَٰبَتْهُم مُّصِيبَةُۢ بِمَا قَدَّمَتَ ࡰيْدِيهِمْ ثُمَّ جَآءُوكَ يَحْلِفُونَ بِاللَّهِ إِنَ ࡰرَدْنَآ إِلَّآ إِحْسَٰناࣰ وَتَوْفِيقاً࣌', 'فكيف إذا أصبتهم مصيبة بما قدمت ࡰيديهم ثم جاءوك يحلفون بالله إن ࡰردنا إلا إحسنا وتوفيقا࣌', NULL, 88, 'local:warsh-text.json'),
  ('warsh-4-62', 'warsh', 4, 62, 'ࡳوْلَٰٓئِكَ ࡰ۬لذِينَ يَعْلَمُ ࡲ۬للَّهُ مَا فِے قُلُوبِهِمْ فَأَعْرِضْ عَنْهُمْ وَعِظْهُمْ وَقُل لَّهُمْ فِےٓ أَنفُسِهِمْ قَوْلاَۢ بَلِيغاࣰ࣌', 'ࡳولئك ࡰلذين يعلم ࡲلله ما فے قلوبهم فأعرض عنهم وعظهم وقل لهم فے أنفسهم قولا بليغا࣌', NULL, 88, 'local:warsh-text.json'),
  ('warsh-4-63', 'warsh', 4, 63, 'وَمَآ أَرْسَلْنَا مِن رَّسُولٍ ࡴلَّا لِيُطَاعَ بِإِذْنِ ࡴ۬للَّهِ࣌ وَلَوَ ࡰنَّهُمُۥٓ إِذ ظَّلَمُوٓاْ أَنفُسَهُمْ جَآءُوكَ فَاسْتَغْفَرُواْ ࡲ۬للَّهَ وَاسْتَغْفَرَ لَهُمُ ࡲ۬لرَّسُولُ لَوَجَدُواْ ࡲ۬للَّهَ تَوَّاباࣰ رَّحِيماࣰ࣌', 'وما أرسلنا من رسول ࡴلا ليطاع بإذن ࡴلله࣌ ولو ࡰنهم إذ ظلموا أنفسهم جاءوك فاستغفروا ࡲلله واستغفر لهم ࡲلرسول لوجدوا ࡲلله توابا رحيما࣌', NULL, 88, 'local:warsh-text.json'),
  ('warsh-4-64', 'warsh', 4, 64, '۞ فَلَا وَرَبِّكَ لَا يُومِنُونَ حَتَّىٰ يُحَكِّمُوكَ فِيمَا شَجَرَ بَيْنَهُمْ ثُمَّ لَا يَجِدُواْ فِےٓ أَنفُسِهِمْ حَرَجاࣰ مِّمَّا قَضَيْتَ وَيُسَلِّمُواْ تَسْلِيماࣰ࣌', 'فلا وربك لا يومنون حتى يحكموك فيما شجر بينهم ثم لا يجدوا فے أنفسهم حرجا مما قضيت ويسلموا تسليما࣌', NULL, 88, 'local:warsh-text.json'),
  ('warsh-4-65', 'warsh', 4, 65, 'وَلَوَ ࡰنَّا كَتَبْنَا عَلَيْهِمُۥٓ أَنُ ࡲ࢈قْتُلُوٓاْ أَنفُسَكُمُۥٓ أَوُ ࡲ࢈خْرُجُواْ مِن دِيٜـٰرِكُم مَّا فَعَلُوهُ إِلَّا قَلِيلࣱ مِّنْهُمْ࣌ وَلَوَ ࡰنَّهُمْ فَعَلُواْ مَا يُوعَظُونَ بِهِۦ لَكَانَ خَيْراࣰ لَّهُمْ وَأَشَدَّ تَثْبِيتاࣰ࣌', 'ولو ࡰنا كتبنا عليهم أن ࡲ࢈قتلوا أنفسكم أو ࡲ࢈خرجوا من ديركم ما فعلوه إلا قليل منهم࣌ ولو ࡰنهم فعلوا ما يوعظون به لكان خيرا لهم وأشد تثبيتا࣌', NULL, 89, 'local:warsh-text.json'),
  ('warsh-4-66', 'warsh', 4, 66, 'وَإِذاࣰ لَّأٓتَيْنَٰهُم مِّن لَّدُنَّآ أَجْراً عَظِيماࣰ', 'وإذا لأتينهم من لدنا أجرا عظيما', NULL, 89, 'local:warsh-text.json'),
  ('warsh-4-67', 'warsh', 4, 67, 'وَلَهَدَيْنَٰهُمْ صِرَٰطاࣰ مُّسْتَقِيماࣰ࣌', 'ولهدينهم صرطا مستقيما࣌', NULL, 89, 'local:warsh-text.json'),
  ('warsh-4-68', 'warsh', 4, 68, 'وَمَنْ يُّطِعِ ࡴ۬للَّهَ وَالرَّسُولَ فَأُوْلَٰٓئِكَ مَعَ ࡰ۬لذِينَ أَنْعَمَ ࡰ۬للَّهُ عَلَيْهِم مِّنَ ࡰ۬لنَّبِيٓـِٕۑنَ وَالصِّدِّيقِينَ وَالشُّهَدَآءِ وَالصَّٰلِحِينَ࣌ وَحَسُنَ أُوْلَٰٓئِكَ رَفِيقاࣰ࣌', 'ومن يطع ࡴلله والرسول فأولئك مع ࡰلذين أنعم ࡰلله عليهم من ࡰلنبيۑن والصديقين والشهداء والصلحين࣌ وحسن أولئك رفيقا࣌', NULL, 89, 'local:warsh-text.json'),
  ('warsh-4-69', 'warsh', 4, 69, 'ذَٰلِكَ ࡰ۬لْفَضْلُ مِنَ ࡰ۬للَّهِ࣌ وَكَفٜىٰ بِاللَّهِ عَلِيماࣰ࣌', 'ذلك ࡰلفضل من ࡰلله࣌ وكفى بالله عليما࣌', NULL, 89, 'local:warsh-text.json'),
  ('warsh-4-70', 'warsh', 4, 70, 'يَٰٓأَيُّهَا ࡰ۬لذِينَ ءَامَنُواْ خُذُواْ حِذْرَكُمْ فَانفِرُواْ ثُبَاتٍ ࡰوِ ࡴٜنفِرُواْ جَمِيعاࣰ࣌', 'يأيها ࡰلذين ءامنوا خذوا حذركم فانفروا ثبات ࡰو ࡴنفروا جميعا࣌', NULL, 89, 'local:warsh-text.json'),
  ('warsh-4-71', 'warsh', 4, 71, 'وَإِنَّ مِنكُمْ لَمَن لَّيُبَطِّئَنَّ࣌ فَإِنَ ࡰصَٰبَتْكُم مُّصِيبَةࣱ قَالَ قَدَ ࡰنْعَمَ ࡰ۬للَّهُ عَلَيَّ إِذْ لَمَ ࡰكُن مَّعَهُمْ شَهِيداࣰ࣌', 'وإن منكم لمن ليبطئن࣌ فإن ࡰصبتكم مصيبة قال قد ࡰنعم ࡰلله علي إذ لم ࡰكن معهم شهيدا࣌', NULL, 89, 'local:warsh-text.json'),
  ('warsh-4-72', 'warsh', 4, 72, 'وَلَئِنَ ࡰصَٰبَكُمْ فَضْلࣱ مِّنَ ࡰ۬للَّهِ لَيَقُولَنَّ كَأَن لَّمْ يَكُنۢ بَيْنَكُمْ وَبَيْنَهُۥ مَوَدَّةࣱ يَٰلَيْتَنِے كُنتُ مَعَهُمْ فَأَفُوزَ فَوْزاً عَظِيماࣰ࣌', 'ولئن ࡰصبكم فضل من ࡰلله ليقولن كأن لم يكن بينكم وبينه مودة يليتنے كنت معهم فأفوز فوزا عظيما࣌', NULL, 89, 'local:warsh-text.json'),
  ('warsh-4-73', 'warsh', 4, 73, '۞ فَلْيُقَٰتِلْ فِے سَبِيلِ ࡴ۬للَّهِ ࡴ۬لذِينَ يَشْرُونَ ࡰ۬لْحَيَوٰةَ ࡰ۬لدُّنْيٜا بِالَاخِرَةِ࣌ وَمَنْ يُّقَٰتِلْ فِے سَبِيلِ ࡴ۬للَّهِ فَيُقْتَلَ ࡰوْ يَغْلِبْ فَسَوْفَ نُوتِيهِ أَجْراً عَظِيماࣰ࣌', 'فليقتل فے سبيل ࡴلله ࡴلذين يشرون ࡰلحيوة ࡰلدنيا بالاخرة࣌ ومن يقتل فے سبيل ࡴلله فيقتل ࡰو يغلب فسوف نوتيه أجرا عظيما࣌', NULL, 89, 'local:warsh-text.json'),
  ('warsh-4-74', 'warsh', 4, 74, 'وَمَا لَكُمْ لَا تُقَٰتِلُونَ فِے سَبِيلِ ࡴ۬للَّهِ وَالْمُسْتَضْعَفِينَ مِنَ ࡰ۬لرِّجَالِ وَالنِّسَآءِ وَالْوِلْدَٰنِ ࡴ۬لذِينَ يَقُولُونَ رَبَّنَآ أَخْرِجْنَا مِنْ هَٰذِهِ ࡴ۬لْقَرْيَةِ ࡴ۬لظَّالِمِ أَهْلُهَا وَاجْعَل لَّنَا مِن لَّدُنكَ وَلِيّاࣰ وَاجْعَل لَّنَا مِن لَّدُنكَ نَصِيراً࣌', 'وما لكم لا تقتلون فے سبيل ࡴلله والمستضعفين من ࡰلرجال والنساء والولدن ࡴلذين يقولون ربنا أخرجنا من هذه ࡴلقرية ࡴلظالم أهلها واجعل لنا من لدنك وليا واجعل لنا من لدنك نصيرا࣌', NULL, 90, 'local:warsh-text.json'),
  ('warsh-4-75', 'warsh', 4, 75, 'ࡴ۬لذِينَ ءَامَنُواْ يُقَٰتِلُونَ فِے سَبِيلِ ࡴ۬للَّهِ࣌ وَالذِينَ كَفَرُواْ يُقَٰتِلُونَ فِے سَبِيلِ ࡴ۬لطَّٰغُوتِ࣌ فَقَٰتِلُوٓاْ أَوْلِيَآءَ ࡰ۬لشَّيْطَٰنِ࣌ إِنَّ كَيْدَ ࡰ۬لشَّيْطَٰنِ كَانَ ضَعِيفاً࣌', 'ࡴلذين ءامنوا يقتلون فے سبيل ࡴلله࣌ والذين كفروا يقتلون فے سبيل ࡴلطغوت࣌ فقتلوا أولياء ࡰلشيطن࣌ إن كيد ࡰلشيطن كان ضعيفا࣌', NULL, 90, 'local:warsh-text.json'),
  ('warsh-4-76', 'warsh', 4, 76, 'ࡰلَمْ تَرَ إِلَى ࡰ۬لذِينَ قِيلَ لَهُمْ كُفُّوٓاْ أَيْدِيَكُمْ وَأَقِيمُواْ ࡲ۬لصَّلَوٰةَ وَءَاتُواْ ࡲ۬لزَّكَوٰةَ࣌ فَلَمَّا كُتِبَ عَلَيْهِمُ ࡲ۬لْقِتَالُ إِذَا فَرِيقࣱ مِّنْهُمْ يَخْشَوْنَ ࡰ۬لنَّاسَ كَخَشْيَةِ ࡴ۬للَّهِ أَوَ ࡰشَدَّ خَشْيَةࣰ࣌ وَقَالُواْ رَبَّنَا لِمَ كَتَبْتَ عَلَيْنَا ࡰ۬لْقِتَالَ لَوْلَآ أَخَّرْتَنَآ إِلَىٰٓ أَجَلࣲ قَرِيبࣲ࣌ قُلْ مَتَٰعُ ࡲ۬لدُّنْيٜا قَلِيلࣱ࣌ وَالَاخِرَةُ خَيْرࣱ لِّمَنِ ࡴٜتَّقٜىٰ࣌ وَلَا تُظْلَمُونَ فَتِيلاً࣌', 'ࡰلم تر إلى ࡰلذين قيل لهم كفوا أيديكم وأقيموا ࡲلصلوة وءاتوا ࡲلزكوة࣌ فلما كتب عليهم ࡲلقتال إذا فريق منهم يخشون ࡰلناس كخشية ࡴلله أو ࡰشد خشية࣌ وقالوا ربنا لم كتبت علينا ࡰلقتال لولا أخرتنا إلى أجل قريب࣌ قل متع ࡲلدنيا قليل࣌ والاخرة خير لمن ࡴتقى࣌ ولا تظلمون فتيلا࣌', NULL, 90, 'local:warsh-text.json'),
  ('warsh-4-77', 'warsh', 4, 77, 'ࡰيْنَمَا تَكُونُواْ يُدْرِككُّمُ ࡲ۬لْمَوْتُ وَلَوْ كُنتُمْ فِے بُرُوجࣲ مُّشَيَّدَةࣲ࣌ وَإِن تُصِبْهُمْ حَسَنَةࣱ يَقُولُواْ هَٰذِهِۦ مِنْ عِندِ ࡴ۬للَّهِ࣌ وَإِن تُصِبْهُمْ سَيِّئَةࣱ يَقُولُواْ هَٰذِهِۦ مِنْ عِندِكَ࣌ قُلْ كُلࣱّ مِّنْ عِندِ ࡴ۬للَّهِ࣌ فَمَالِ هَٰٓؤُلَآءِ ࡴ۬لْقَوْمِ لَا يَكَادُونَ يَفْقَهُونَ حَدِيثاࣰ࣌', 'ࡰينما تكونوا يدرككم ࡲلموت ولو كنتم فے بروج مشيدة࣌ وإن تصبهم حسنة يقولوا هذه من عند ࡴلله࣌ وإن تصبهم سيئة يقولوا هذه من عندك࣌ قل كل من عند ࡴلله࣌ فمال هؤلاء ࡴلقوم لا يكادون يفقهون حديثا࣌', NULL, 90, 'local:warsh-text.json'),
  ('warsh-4-78', 'warsh', 4, 78, '۞ مَّآ أَصَابَكَ مِنْ حَسَنَةࣲ فَمِنَ ࡰ۬للَّهِ࣌ وَمَآ أَصَابَكَ مِن سَيِّئَةࣲ فَمِن نَّفْسِكَ࣌ وَأَرْسَلْنَٰكَ لِلنَّاسِ رَسُولاࣰ࣌ وَكَفٜىٰ بِاللَّهِ شَهِيداࣰ࣌', 'ما أصابك من حسنة فمن ࡰلله࣌ وما أصابك من سيئة فمن نفسك࣌ وأرسلنك للناس رسولا࣌ وكفى بالله شهيدا࣌', NULL, 90, 'local:warsh-text.json'),
  ('warsh-4-79', 'warsh', 4, 79, 'مَّنْ يُّطِعِ ࡴ۬لرَّسُولَ فَقَدَ ࡰطَاعَ ࡰ۬للَّهَ࣌ وَمَن تَوَلّٜىٰ فَمَآ أَرْسَلْنَٰكَ عَلَيْهِمْ حَفِيظاࣰ࣌', 'من يطع ࡴلرسول فقد ࡰطاع ࡰلله࣌ ومن تولى فما أرسلنك عليهم حفيظا࣌', NULL, 91, 'local:warsh-text.json'),
  ('warsh-4-80', 'warsh', 4, 80, 'وَيَقُولُونَ طَاعَةࣱ࣌ فَإِذَا بَرَزُواْ مِنْ عِندِكَ بَيَّتَ طَآئِفَةࣱ مِّنْهُمْ غَيْرَ ࡰ۬لذِے تَقُولُ࣌ وَاللَّهُ يَكْتُبُ مَا يُبَيِّتُونَ࣌ فَأَعْرِضْ عَنْهُمْ وَتَوَكَّلْ عَلَى ࡰ۬للَّهِ࣌ وَكَفٜىٰ بِاللَّهِ وَكِيلاً࣌', 'ويقولون طاعة࣌ فإذا برزوا من عندك بيت طائفة منهم غير ࡰلذے تقول࣌ والله يكتب ما يبيتون࣌ فأعرض عنهم وتوكل على ࡰلله࣌ وكفى بالله وكيلا࣌', NULL, 91, 'local:warsh-text.json'),
  ('warsh-4-81', 'warsh', 4, 81, 'ࡰفَلَا يَتَدَبَّرُونَ ࡰ۬لْقُرْءَانَ࣌ وَلَوْ كَانَ مِنْ عِندِ غَيْرِ ࡴ۬للَّهِ لَوَجَدُواْ فِيهِ ࡴٜخْتِلَٰفاࣰ كَثِيراࣰ࣌', 'ࡰفلا يتدبرون ࡰلقرءان࣌ ولو كان من عند غير ࡴلله لوجدوا فيه ࡴختلفا كثيرا࣌', NULL, 91, 'local:warsh-text.json'),
  ('warsh-4-82', 'warsh', 4, 82, 'وَإِذَا جَآءَهُمُۥٓ أَمْرࣱ مِّنَ ࡰ۬لَامْنِ أَوِ ࡴ۬لْخَوْفِ أَذَاعُواْ بِهِۦ࣌ وَلَوْ رَدُّوهُ إِلَى ࡰ۬لرَّسُولِ وَإِلَىٰٓ أُوْلِے ࡴ۬لَامْرِ مِنْهُمْ لَعَلِمَهُ ࡲ۬لذِينَ يَسْتَنۢبِطُونَهُۥ مِنْهُمْ࣌ وَلَوْلَا فَضْلُ ࡲ۬للَّهِ عَلَيْكُمْ وَرَحْمَتُهُۥ لَاتَّبَعْتُمُ ࡲ۬لشَّيْطَٰنَ إِلَّا قَلِيلاࣰ࣌', 'وإذا جاءهم أمر من ࡰلامن أو ࡴلخوف أذاعوا به࣌ ولو ردوه إلى ࡰلرسول وإلى أولے ࡴلامر منهم لعلمه ࡲلذين يستنبطونه منهم࣌ ولولا فضل ࡲلله عليكم ورحمته لاتبعتم ࡲلشيطن إلا قليلا࣌', NULL, 91, 'local:warsh-text.json'),
  ('warsh-4-83', 'warsh', 4, 83, 'فَقَٰتِلْ فِے سَبِيلِ ࡴ۬للَّهِ࣌ لَا تُكَلَّفُ إِلَّا نَفْسَكَ࣌ وَحَرِّضِ ࡴ۬لْمُومِنِينَ࣌ عَسَى ࡰ۬للَّهُ أَنْ يَّكُفَّ بَأْسَ ࡰ۬لذِينَ كَفَرُواْ࣌ وَاللَّهُ أَشَدُّ بَأْساࣰ وَأَشَدُّ تَنكِيلاࣰ࣌', 'فقتل فے سبيل ࡴلله࣌ لا تكلف إلا نفسك࣌ وحرض ࡴلمومنين࣌ عسى ࡰلله أن يكف بأس ࡰلذين كفروا࣌ والله أشد بأسا وأشد تنكيلا࣌', NULL, 91, 'local:warsh-text.json'),
  ('warsh-4-84', 'warsh', 4, 84, 'مَّنْ يَّشْفَعْ شَفَٰعَةً حَسَنَةࣰ يَكُن لَّهُۥ نَصِيبࣱ مِّنْهَا࣌ وَمَنْ يَّشْفَعْ شَفَٰعَةࣰ سَيِّئَةࣰ يَكُن لَّهُۥ كِفْلࣱ مِّنْهَا࣌ وَكَانَ ࡰ۬للَّهُ عَلَىٰ كُلِّ شَےْءࣲ مُّقِيتاࣰ࣌', 'من يشفع شفعة حسنة يكن له نصيب منها࣌ ومن يشفع شفعة سيئة يكن له كفل منها࣌ وكان ࡰلله على كل شےء مقيتا࣌', NULL, 91, 'local:warsh-text.json'),
  ('warsh-4-85', 'warsh', 4, 85, 'وَإِذَا حُيِّيتُم بِتَحِيَّةࣲ فَحَيُّواْ بِأَحْسَنَ مِنْهَآ أَوْ رُدُّوهَآ࣌ إِنَّ ࡰ۬للَّهَ كَانَ عَلَىٰ كُلِّ شَےْءٍ حَسِيباً࣌', 'وإذا حييتم بتحية فحيوا بأحسن منها أو ردوها࣌ إن ࡰلله كان على كل شےء حسيبا࣌', NULL, 91, 'local:warsh-text.json'),
  ('warsh-4-86', 'warsh', 4, 86, '۞ ࡴ۬للَّهُ لَآ إِلَٰهَ إِلَّا هُوَ࣌ لَيَجْمَعَنَّكُمُۥٓ إِلَىٰ يَوْمِ ࡴ۬لْقِيَٰمَةِ لَا رَيْبَ فِيهِ࣌ وَمَنَ ࡰصْدَقُ مِنَ ࡰ۬للَّهِ حَدِيثاࣰ࣌', 'ࡴلله لا إله إلا هو࣌ ليجمعنكم إلى يوم ࡴلقيمة لا ريب فيه࣌ ومن ࡰصدق من ࡰلله حديثا࣌', NULL, 92, 'local:warsh-text.json'),
  ('warsh-4-87', 'warsh', 4, 87, 'فَمَا لَكُمْ فِے ࡴ۬لْمُنَٰفِقِينَ فِئَتَيْنِ وَاللَّهُ أَرْكَسَهُم بِمَا كَسَبُوٓاْ࣌ أَتُرِيدُونَ أَن تَهْدُواْ مَنَ ࡰضَلَّ ࡰ۬للَّهُ࣌ وَمَنْ يُّضْلِلِ ࡴ۬للَّهُ فَلَن تَجِدَ لَهُۥ سَبِيلاࣰ࣌', 'فما لكم فے ࡴلمنفقين فئتين والله أركسهم بما كسبوا࣌ أتريدون أن تهدوا من ࡰضل ࡰلله࣌ ومن يضلل ࡴلله فلن تجد له سبيلا࣌', NULL, 92, 'local:warsh-text.json'),
  ('warsh-4-88', 'warsh', 4, 88, 'وَدُّواْ لَوْ تَكْفُرُونَ كَمَا كَفَرُواْ فَتَكُونُونَ سَوَآءࣰ࣌ فَلَا تَتَّخِذُواْ مِنْهُمُۥٓ أَوْلِيَآءَ حَتَّىٰ يُهَاجِرُواْ فِے سَبِيلِ ࡴ۬للَّهِ࣌ فَإِن تَوَلَّوْاْ فَخُذُوهُمْ وَاقْتُلُوهُمْ حَيْثُ وَجَدتُّمُوهُمْ وَلَا تَتَّخِذُواْ مِنْهُمْ وَلِيّاࣰ وَلَا نَصِيراً', 'ودوا لو تكفرون كما كفروا فتكونون سواء࣌ فلا تتخذوا منهم أولياء حتى يهاجروا فے سبيل ࡴلله࣌ فإن تولوا فخذوهم واقتلوهم حيث وجدتموهم ولا تتخذوا منهم وليا ولا نصيرا', NULL, 92, 'local:warsh-text.json'),
  ('warsh-4-89', 'warsh', 4, 89, 'ࡴلَّا ࡰ۬لذِينَ يَصِلُونَ إِلَىٰ قَوْمِۢ بَيْنَكُمْ وَبَيْنَهُم مِّيثَٰقٌ ࡰوْ جَآءُوكُمْ࣌ حَصِرَتْ صُدُورُهُمُۥٓ أَنْ يُّقَٰتِلُوكُمُۥٓ أَوْ يُقَٰتِلُواْ قَوْمَهُمْ࣌ وَلَوْ شَآءَ ࡰ۬للَّهُ لَسَلَّطَهُمْ عَلَيْكُمْ فَلَقَٰتَلُوكُمْ࣌ فَإِنِ ࡴٜعْتَزَلُوكُمْ فَلَمْ يُقَٰتِلُوكُمْ وَأَلْقَوِاْ ࡴلَيْكُمُ ࡲ۬لسَّلَمَ فَمَا جَعَلَ ࡰ۬للَّهُ لَكُمْ عَلَيْهِمْ سَبِيلاࣰ࣌', 'ࡴلا ࡰلذين يصلون إلى قوم بينكم وبينهم ميثق ࡰو جاءوكم࣌ حصرت صدورهم أن يقتلوكم أو يقتلوا قومهم࣌ ولو شاء ࡰلله لسلطهم عليكم فلقتلوكم࣌ فإن ࡴعتزلوكم فلم يقتلوكم وألقوا ࡴليكم ࡲلسلم فما جعل ࡰلله لكم عليهم سبيلا࣌', NULL, 92, 'local:warsh-text.json'),
  ('warsh-4-90', 'warsh', 4, 90, 'سَتَجِدُونَ ءَاخَرِينَ يُرِيدُونَ أَنْ يَّامَنُوكُمْ وَيَامَنُواْ قَوْمَهُمْ كُلَّ مَا رُدُّوٓاْ إِلَى ࡰ۬لْفِتْنَةِ أُرْكِسُواْ فِيهَا࣌ فَإِن لَّمْ يَعْتَزِلُوكُمْ وَيُلْقُوٓاْ إِلَيْكُمُ ࡲ۬لسَّلَمَ وَيَكُفُّوٓاْ أَيْدِيَهُمْ فَخُذُوهُمْ وَاقْتُلُوهُمْ حَيْثُ ثَقِفْتُمُوهُمْ࣌ وَأُوْلَٰٓئِكُمْ جَعَلْنَا لَكُمْ عَلَيْهِمْ سُلْطَٰناࣰ مُّبِيناࣰ࣌', 'ستجدون ءاخرين يريدون أن يامنوكم ويامنوا قومهم كل ما ردوا إلى ࡰلفتنة أركسوا فيها࣌ فإن لم يعتزلوكم ويلقوا إليكم ࡲلسلم ويكفوا أيديهم فخذوهم واقتلوهم حيث ثقفتموهم࣌ وأولئكم جعلنا لكم عليهم سلطنا مبينا࣌', NULL, 92, 'local:warsh-text.json'),
  ('warsh-4-91', 'warsh', 4, 91, 'وَمَا كَانَ لِمُومِنٍ ࡰنْ يَّقْتُلَ مُومِناً࣌ ࡴلَّا خَطَـٔاࣰ࣌ وَمَن قَتَلَ مُومِناً خَطَـٔاࣰ فَتَحْرِيرُ رَقَبَةࣲ مُّومِنَةࣲ وَدِيَةࣱ مُّسَلَّمَةٌ ࡴلَىٰٓ أَهْلِهِۦٓ إِلَّآ أَنْ يَّصَّدَّقُواْ࣌ فَإِن كَانَ مِن قَوْمٍ عَدُوࣲّ لَّكُمْ وَهُوَ مُومِنࣱ فَتَحْرِيرُ رَقَبَةࣲ مُّومِنَةࣲ࣌ وَإِن كَانَ مِن قَوْمِۢ بَيْنَكُمْ وَبَيْنَهُم مِّيثَٰقࣱ فَدِيَةࣱ مُّسَلَّمَةٌ ࡴلَىٰٓ أَهْلِهِۦ وَتَحْرِيرُ رَقَبَةࣲ مُّومِنَةࣲ࣌ ۞ فَمَن لَّمْ يَجِدْ فَصِيَامُ شَهْرَيْنِ مُتَتَابِعَيْنِ تَوْبَةࣰ مِّنَ ࡰ۬للَّهِ࣌ وَكَانَ ࡰ۬للَّهُ عَلِيماً حَكِيماࣰ࣌', 'وما كان لمومن ࡰن يقتل مومنا࣌ ࡴلا خطا࣌ ومن قتل مومنا خطا فتحرير رقبة مومنة ودية مسلمة ࡴلى أهله إلا أن يصدقوا࣌ فإن كان من قوم عدو لكم وهو مومن فتحرير رقبة مومنة࣌ وإن كان من قوم بينكم وبينهم ميثق فدية مسلمة ࡴلى أهله وتحرير رقبة مومنة࣌  فمن لم يجد فصيام شهرين متتابعين توبة من ࡰلله࣌ وكان ࡰلله عليما حكيما࣌', NULL, 93, 'local:warsh-text.json'),
  ('warsh-4-92', 'warsh', 4, 92, 'وَمَنْ يَّقْتُلْ مُومِناࣰ مُّتَعَمِّداࣰ فَجَزَآؤُهُۥ جَهَنَّمُ خَٰلِداࣰ فِيهَا وَغَضِبَ ࡰ۬للَّهُ عَلَيْهِ وَلَعَنَهُۥ وَأَعَدَّ لَهُۥ عَذَاباً عَظِيماࣰ࣌', 'ومن يقتل مومنا متعمدا فجزاؤه جهنم خلدا فيها وغضب ࡰلله عليه ولعنه وأعد له عذابا عظيما࣌', NULL, 93, 'local:warsh-text.json'),
  ('warsh-4-93', 'warsh', 4, 93, 'يَٰٓأَيُّهَا ࡰ۬لذِينَ ءَامَنُوٓاْ إِذَا ضَرَبْتُمْ فِے سَبِيلِ ࡴ۬للَّهِ فَتَبَيَّنُواْ࣌ وَلَا تَقُولُواْ لِمَنَ ࡰلْقٜىٰٓ إِلَيْكُمُ ࡲ۬لسَّلَمَ لَسْتَ مُومِناࣰ تَبْتَغُونَ عَرَضَ ࡰ۬لْحَيَوٰةِ ࡴ۬لدُّنْيٜا فَعِندَ ࡰ۬للَّهِ مَغَانِمُ كَثِيرَةࣱ࣌ كَذَٰلِكَ كُنتُم مِّن قَبْلُ فَمَنَّ ࡰ۬للَّهُ عَلَيْكُمْ࣌ فَتَبَيَّنُوٓاْ࣌ إِنَّ ࡰ۬للَّهَ كَانَ بِمَا تَعْمَلُونَ خَبِيراࣰ࣌', 'يأيها ࡰلذين ءامنوا إذا ضربتم فے سبيل ࡴلله فتبينوا࣌ ولا تقولوا لمن ࡰلقى إليكم ࡲلسلم لست مومنا تبتغون عرض ࡰلحيوة ࡴلدنيا فعند ࡰلله مغانم كثيرة࣌ كذلك كنتم من قبل فمن ࡰلله عليكم࣌ فتبينوا࣌ إن ࡰلله كان بما تعملون خبيرا࣌', NULL, 93, 'local:warsh-text.json'),
  ('warsh-4-94', 'warsh', 4, 94, 'لَّا يَسْتَوِے ࡴ۬لْقَٰعِدُونَ مِنَ ࡰ۬لْمُومِنِينَ غَيْرَ أُوْلِے ࡴ۬لضَّرَرِ وَالْمُجَٰهِدُونَ فِے سَبِيلِ ࡴ۬للَّهِ بِأَمْوَٰلِهِمْ وَأَنفُسِهِمْ࣌ فَضَّلَ ࡰ۬للَّهُ ࡲ۬لْمُجَٰهِدِينَ بِأَمْوَٰلِهِمْ وَأَنفُسِهِمْ عَلَى ࡰ۬لْقَٰعِدِينَ دَرَجَةࣰ࣌ وَكُلّاࣰ وَعَدَ ࡰ۬للَّهُ ࡲ۬لْحُسْنٜىٰ࣌ وَفَضَّلَ ࡰ۬للَّهُ ࡲ۬لْمُجَٰهِدِينَ عَلَى ࡰ۬لْقَٰعِدِينَ أَجْراً عَظِيماࣰ', 'لا يستوے ࡴلقعدون من ࡰلمومنين غير أولے ࡴلضرر والمجهدون فے سبيل ࡴلله بأمولهم وأنفسهم࣌ فضل ࡰلله ࡲلمجهدين بأمولهم وأنفسهم على ࡰلقعدين درجة࣌ وكلا وعد ࡰلله ࡲلحسنى࣌ وفضل ࡰلله ࡲلمجهدين على ࡰلقعدين أجرا عظيما', NULL, 94, 'local:warsh-text.json'),
  ('warsh-4-95', 'warsh', 4, 95, 'دَرَجَٰتࣲ مِّنْهُ وَمَغْفِرَةࣰ وَرَحْمَةࣰ࣌ وَكَانَ ࡰ۬للَّهُ غَفُوراࣰ رَّحِيماً࣌', 'درجت منه ومغفرة ورحمة࣌ وكان ࡰلله غفورا رحيما࣌', NULL, 94, 'local:warsh-text.json'),
  ('warsh-4-96', 'warsh', 4, 96, 'ࡴنَّ ࡰ۬لذِينَ تَوَفّٜيٰهُمُ ࡲ۬لْمَلَٰٓئِكَةُ ظَالِمِےٓ أَنفُسِهِمْ قَالُواْ فِيمَ كُنتُمْ࣌ قَالُواْ كُنَّا مُسْتَضْعَفِينَ فِے ࡴ۬لَارْضِ࣌ قَالُوٓاْ أَلَمْ تَكُنَ ࡰرْضُ ࡲ۬للَّهِ وَٰسِعَةࣰ فَتُهَاجِرُواْ فِيهَا࣌ فَأُوْلَٰٓئِكَ مَأْوٜيٰهُمْ جَهَنَّمُ وَسَآءَتْ مَصِيراً', 'ࡴن ࡰلذين توفيهم ࡲلملئكة ظالمے أنفسهم قالوا فيم كنتم࣌ قالوا كنا مستضعفين فے ࡴلارض࣌ قالوا ألم تكن ࡰرض ࡲلله وسعة فتهاجروا فيها࣌ فأولئك مأويهم جهنم وساءت مصيرا', NULL, 94, 'local:warsh-text.json'),
  ('warsh-4-97', 'warsh', 4, 97, 'ࡴلَّا ࡰ۬لْمُسْتَضْعَفِينَ مِنَ ࡰ۬لرِّجَالِ وَالنِّسَآءِ وَالْوِلْدَٰنِ لَا يَسْتَطِيعُونَ حِيلَةࣰ وَلَا يَهْتَدُونَ سَبِيلاࣰ࣌', 'ࡴلا ࡰلمستضعفين من ࡰلرجال والنساء والولدن لا يستطيعون حيلة ولا يهتدون سبيلا࣌', NULL, 94, 'local:warsh-text.json'),
  ('warsh-4-98', 'warsh', 4, 98, 'فَأُوْلَٰٓئِكَ عَسَى ࡰ۬للَّهُ أَنْ يَّعْفُوَ عَنْهُمْ࣌ وَكَانَ ࡰ۬للَّهُ عَفُوّاً غَفُوراࣰ࣌', 'فأولئك عسى ࡰلله أن يعفو عنهم࣌ وكان ࡰلله عفوا غفورا࣌', NULL, 94, 'local:warsh-text.json'),
  ('warsh-4-99', 'warsh', 4, 99, '۞ وَمَنْ يُّهَاجِرْ فِے سَبِيلِ ࡴ۬للَّهِ يَجِدْ فِے ࡴ۬لَارْضِ مُرَٰغَماࣰ كَثِيراࣰ وَسَعَةࣰ࣌ وَمَنْ يَّخْرُجْ مِنۢ بَيْتِهِۦ مُهَاجِراً ࡴلَى ࡰ۬للَّهِ وَرَسُولِهِۦ ثُمَّ يُدْرِكْهُ ࡲ۬لْمَوْتُ فَقَدْ وَقَعَ أَجْرُهُۥ عَلَى ࡰ۬للَّهِ࣌ وَكَانَ ࡰ۬للَّهُ غَفُوراࣰ رَّحِيماࣰ࣌', 'ومن يهاجر فے سبيل ࡴلله يجد فے ࡴلارض مرغما كثيرا وسعة࣌ ومن يخرج من بيته مهاجرا ࡴلى ࡰلله ورسوله ثم يدركه ࡲلموت فقد وقع أجره على ࡰلله࣌ وكان ࡰلله غفورا رحيما࣌', NULL, 94, 'local:warsh-text.json'),
  ('warsh-4-100', 'warsh', 4, 100, 'وَإِذَا ضَرَبْتُمْ فِے ࡴ۬لَارْضِ فَلَيْسَ عَلَيْكُمْ جُنَاحٌ ࡰن تَقْصُرُواْ مِنَ ࡰ۬لصَّلَوٰةِ إِنْ خِفْتُمُۥٓ أَنْ يَّفْتِنَكُمُ ࡲ۬لذِينَ كَفَرُوٓاْ࣌ إِنَّ ࡰ۬لْكٜـٰفِرِينَ كَانُواْ لَكُمْ عَدُوّاࣰ مُّبِيناࣰ࣌', 'وإذا ضربتم فے ࡴلارض فليس عليكم جناح ࡰن تقصروا من ࡰلصلوة إن خفتم أن يفتنكم ࡲلذين كفروا࣌ إن ࡰلكفرين كانوا لكم عدوا مبينا࣌', NULL, 94, 'local:warsh-text.json'),
  ('warsh-4-101', 'warsh', 4, 101, 'وَإِذَا كُنتَ فِيهِمْ فَأَقَمْتَ لَهُمُ ࡲ۬لصَّلَوٰةَ فَلْتَقُمْ طَآئِفَةࣱ مِّنْهُم مَّعَكَ وَلْيَاخُذُوٓاْ أَسْلِحَتَهُمْ࣌ فَإِذَا سَجَدُواْ فَلْيَكُونُواْ مِنْ وَّرَآئِكُمْ࣌ وَلْتَاتِ طَآئِفَةٌ ࡳخْرٜىٰ لَمْ يُصَلُّواْ فَلْيُصَلُّواْ مَعَكَ وَلْيَاخُذُواْ حِذْرَهُمْ وَأَسْلِحَتَهُمْ࣌ وَدَّ ࡰ۬لذِينَ كَفَرُواْ لَوْ تَغْفُلُونَ عَنَ ࡰسْلِحَتِكُمْ وَأَمْتِعَتِكُمْ فَيَمِيلُونَ عَلَيْكُم مَّيْلَةࣰ وَٰحِدَةࣰ࣌ وَلَا جُنَاحَ عَلَيْكُمُۥٓ إِن كَانَ بِكُمُۥٓ أَذىࣰ مِّن مَّطَرٍ ࡰوْ كُنتُم مَّرْضٜىٰٓ أَن تَضَعُوٓاْ أَسْلِحَتَكُمْ࣌ وَخُذُواْ حِذْرَكُمُۥٓ࣌ إِنَّ ࡰ۬للَّهَ أَعَدَّ لِلْكٜـٰفِرِينَ عَذَاباࣰ مُّهِيناࣰ࣌', 'وإذا كنت فيهم فأقمت لهم ࡲلصلوة فلتقم طائفة منهم معك ولياخذوا أسلحتهم࣌ فإذا سجدوا فليكونوا من ورائكم࣌ ولتات طائفة ࡳخرى لم يصلوا فليصلوا معك ولياخذوا حذرهم وأسلحتهم࣌ ود ࡰلذين كفروا لو تغفلون عن ࡰسلحتكم وأمتعتكم فيميلون عليكم ميلة وحدة࣌ ولا جناح عليكم إن كان بكم أذى من مطر ࡰو كنتم مرضى أن تضعوا أسلحتكم࣌ وخذوا حذركم࣌ إن ࡰلله أعد للكفرين عذابا مهينا࣌', NULL, 95, 'local:warsh-text.json'),
  ('warsh-4-102', 'warsh', 4, 102, 'فَإِذَا قَضَيْتُمُ ࡲ۬لصَّلَوٰةَ فَاذْكُرُواْ ࡲ۬للَّهَ قِيَٰماࣰ وَقُعُوداࣰ وَعَلَىٰ جُنُوبِكُمْ࣌ فَإِذَا ࡰٜطْمَأْنَنتُمْ فَأَقِيمُواْ ࡲ۬لصَّلَوٰةَ࣌ إِنَّ ࡰ۬لصَّلَوٰةَ كَانَتْ عَلَى ࡰ۬لْمُومِنِينَ كِتَٰباࣰ مَّوْقُوتاࣰ࣌', 'فإذا قضيتم ࡲلصلوة فاذكروا ࡲلله قيما وقعودا وعلى جنوبكم࣌ فإذا ࡰطمأننتم فأقيموا ࡲلصلوة࣌ إن ࡰلصلوة كانت على ࡰلمومنين كتبا موقوتا࣌', NULL, 95, 'local:warsh-text.json'),
  ('warsh-4-103', 'warsh', 4, 103, 'وَلَا تَهِنُواْ فِے ࡴٜبْتِغَآءِ ࡴ۬لْقَوْمِ࣌ إِن تَكُونُواْ تَالَمُونَ فَإِنَّهُمْ يَالَمُونَ كَمَا تَالَمُونَ وَتَرْجُونَ مِنَ ࡰ۬للَّهِ مَا لَا يَرْجُونَ࣌ وَكَانَ ࡰ۬للَّهُ عَلِيماً حَكِيماً࣌', 'ولا تهنوا فے ࡴبتغاء ࡴلقوم࣌ إن تكونوا تالمون فإنهم يالمون كما تالمون وترجون من ࡰلله ما لا يرجون࣌ وكان ࡰلله عليما حكيما࣌', NULL, 95, 'local:warsh-text.json'),
  ('warsh-4-104', 'warsh', 4, 104, '۞ ࡴنَّآ أَنزَلْنَآ إِلَيْكَ ࡰ۬لْكِتَٰبَ بِالْحَقِّ لِتَحْكُمَ بَيْنَ ࡰ۬لنَّاسِ بِمَآ أَرٜيٰكَ ࡰ۬للَّهُ࣌ وَلَا تَكُن لِّلْخَآئِنِينَ خَصِيماࣰ࣌', 'ࡴنا أنزلنا إليك ࡰلكتب بالحق لتحكم بين ࡰلناس بما أريك ࡰلله࣌ ولا تكن للخائنين خصيما࣌', NULL, 95, 'local:warsh-text.json'),
  ('warsh-4-105', 'warsh', 4, 105, 'وَاسْتَغْفِرِ ࡴ۬للَّهَ࣌ إِنَّ ࡰ۬للَّهَ كَانَ غَفُوراࣰ رَّحِيماࣰ࣌', 'واستغفر ࡴلله࣌ إن ࡰلله كان غفورا رحيما࣌', NULL, 96, 'local:warsh-text.json'),
  ('warsh-4-106', 'warsh', 4, 106, 'وَلَا تُجَٰدِلْ عَنِ ࡴ۬لذِينَ يَخْتَانُونَ أَنفُسَهُمُۥٓ࣌ إِنَّ ࡰ۬للَّهَ لَا يُحِبُّ مَن كَانَ خَوَّاناً ࡰثِيماࣰ࣌', 'ولا تجدل عن ࡴلذين يختانون أنفسهم࣌ إن ࡰلله لا يحب من كان خوانا ࡰثيما࣌', NULL, 96, 'local:warsh-text.json'),
  ('warsh-4-107', 'warsh', 4, 107, 'يَسْتَخْفُونَ مِنَ ࡰ۬لنَّاسِ وَلَا يَسْتَخْفُونَ مِنَ ࡰ۬للَّهِ وَهُوَ مَعَهُمُۥٓ إِذْ يُبَيِّتُونَ مَا لَا يَرْضٜىٰ مِنَ ࡰ۬لْقَوْلِ࣌ وَكَانَ ࡰ۬للَّهُ بِمَا يَعْمَلُونَ مُحِيطاً࣌', 'يستخفون من ࡰلناس ولا يستخفون من ࡰلله وهو معهم إذ يبيتون ما لا يرضى من ࡰلقول࣌ وكان ࡰلله بما يعملون محيطا࣌', NULL, 96, 'local:warsh-text.json'),
  ('warsh-4-108', 'warsh', 4, 108, 'هَآنتُمْ هَٰٓؤُلَآءِ جَٰدَلْتُمْ عَنْهُمْ فِے ࡴ۬لْحَيَوٰةِ ࡴ۬لدُّنْيٜا فَمَنْ يُّجَٰدِلُ ࡲ۬للَّهَ عَنْهُمْ يَوْمَ ࡰ۬لْقِيَٰمَةِ أَم مَّنْ يَّكُونُ عَلَيْهِمْ وَكِيلاࣰ࣌', 'هانتم هؤلاء جدلتم عنهم فے ࡴلحيوة ࡴلدنيا فمن يجدل ࡲلله عنهم يوم ࡰلقيمة أم من يكون عليهم وكيلا࣌', NULL, 96, 'local:warsh-text.json'),
  ('warsh-4-109', 'warsh', 4, 109, 'وَمَنْ يَّعْمَلْ سُوٓءاً ࡰوْ يَظْلِمْ نَفْسَهُۥ ثُمَّ يَسْتَغْفِرِ ࡴ۬للَّهَ يَجِدِ ࡴ۬للَّهَ غَفُوراࣰ رَّحِيماࣰ࣌', 'ومن يعمل سوءا ࡰو يظلم نفسه ثم يستغفر ࡴلله يجد ࡴلله غفورا رحيما࣌', NULL, 96, 'local:warsh-text.json'),
  ('warsh-4-110', 'warsh', 4, 110, 'وَمَنْ يَّكْسِبِ ࡴثْماࣰ فَإِنَّمَا يَكْسِبُهُۥ عَلَىٰ نَفْسِهِۦ࣌ وَكَانَ ࡰ۬للَّهُ عَلِيماً حَكِيماࣰ࣌', 'ومن يكسب ࡴثما فإنما يكسبه على نفسه࣌ وكان ࡰلله عليما حكيما࣌', NULL, 96, 'local:warsh-text.json'),
  ('warsh-4-111', 'warsh', 4, 111, 'وَمَنْ يَّكْسِبْ خَطِيٓـَٔةً ࡰوِ ࡴثْماࣰ ثُمَّ يَرْمِ بِهِۦ بَرِيٓـٔاࣰ فَقَدِ ࡴٜحْتَمَلَ بُهْتَٰناࣰ وَإِثْماࣰ مُّبِيناࣰ࣌', 'ومن يكسب خطية ࡰو ࡴثما ثم يرم به بريا فقد ࡴحتمل بهتنا وإثما مبينا࣌', NULL, 96, 'local:warsh-text.json'),
  ('warsh-4-112', 'warsh', 4, 112, 'وَلَوْلَا فَضْلُ ࡲ۬للَّهِ عَلَيْكَ وَرَحْمَتُهُۥ لَهَمَّت طَّآئِفَةࣱ مِّنْهُمُۥٓ أَنْ يُّضِلُّوكَ࣌ وَمَا يُضِلُّونَ إِلَّآ أَنفُسَهُمْ وَمَا يَضُرُّونَكَ مِن شَےْءࣲ࣌ وَأَنزَلَ ࡰ۬للَّهُ عَلَيْكَ ࡰ۬لْكِتَٰبَ وَالْحِكْمَةَ وَعَلَّمَكَ مَا لَمْ تَكُن تَعْلَمُ࣌ وَكَانَ فَضْلُ ࡲ۬للَّهِ عَلَيْكَ عَظِيماࣰ࣌', 'ولولا فضل ࡲلله عليك ورحمته لهمت طائفة منهم أن يضلوك࣌ وما يضلون إلا أنفسهم وما يضرونك من شےء࣌ وأنزل ࡰلله عليك ࡰلكتب والحكمة وعلمك ما لم تكن تعلم࣌ وكان فضل ࡲلله عليك عظيما࣌', NULL, 96, 'local:warsh-text.json'),
  ('warsh-4-113', 'warsh', 4, 113, '۞ لَّا خَيْرَ فِے كَثِيرࣲ مِّن نَّجْوٜيٰهُمُۥٓ إِلَّا مَنَ ࡰمَرَ بِصَدَقَةٍ ࡰوْ مَعْرُوفٍ ࡰوِ ࡴصْلَٰحِۢ بَيْنَ ࡰ۬لنَّاسِ࣌ وَمَنْ يَّفْعَلْ ذَٰلِكَ ࡰٜبْتِغَآءَ مَرْضَاتِ ࡴ۬للَّهِ فَسَوْفَ نُوتِيهِ أَجْراً عَظِيماࣰ࣌', 'لا خير فے كثير من نجويهم إلا من ࡰمر بصدقة ࡰو معروف ࡰو ࡴصلح بين ࡰلناس࣌ ومن يفعل ذلك ࡰبتغاء مرضات ࡴلله فسوف نوتيه أجرا عظيما࣌', NULL, 97, 'local:warsh-text.json'),
  ('warsh-4-114', 'warsh', 4, 114, 'وَمَنْ يُّشَاقِقِ ࡴ۬لرَّسُولَ مِنۢ بَعْدِ مَا تَبَيَّنَ لَهُ ࡲ۬لْهُدٜىٰ وَيَتَّبِعْ غَيْرَ سَبِيلِ ࡴ۬لْمُومِنِينَ نُوَلِّهِۦ مَا تَوَلّٜىٰ وَنُصْلِهِۦ جَهَنَّمَ࣌ وَسَآءَتْ مَصِيراً࣌', 'ومن يشاقق ࡴلرسول من بعد ما تبين له ࡲلهدى ويتبع غير سبيل ࡴلمومنين نوله ما تولى ونصله جهنم࣌ وساءت مصيرا࣌', NULL, 97, 'local:warsh-text.json'),
  ('warsh-4-115', 'warsh', 4, 115, 'ࡴنَّ ࡰ۬للَّهَ لَا يَغْفِرُ أَنْ يُّشْرَكَ بِهِۦ࣌ وَيَغْفِرُ مَا دُونَ ذَٰلِكَ لِمَنْ يَّشَآءُ࣌ وَمَنْ يُّشْرِكْ بِاللَّهِ فَقَد ضَّلَّ ضَلَٰلاَۢ بَعِيداً࣌', 'ࡴن ࡰلله لا يغفر أن يشرك به࣌ ويغفر ما دون ذلك لمن يشاء࣌ ومن يشرك بالله فقد ضل ضللا بعيدا࣌', NULL, 97, 'local:warsh-text.json'),
  ('warsh-4-116', 'warsh', 4, 116, 'ࡴنْ يَّدْعُونَ مِن دُونِهِۦٓ إِلَّآ إِنَٰثاࣰ وَإِنْ يَّدْعُونَ إِلَّا شَيْطَٰناࣰ مَّرِيداࣰ', 'ࡴن يدعون من دونه إلا إنثا وإن يدعون إلا شيطنا مريدا', NULL, 97, 'local:warsh-text.json'),
  ('warsh-4-117', 'warsh', 4, 117, 'لَّعَنَهُ ࡲ۬للَّهُ࣌ وَقَالَ لَأَتَّخِذَنَّ مِنْ عِبَادِكَ نَصِيباࣰ مَّفْرُوضاࣰ', 'لعنه ࡲلله࣌ وقال لأتخذن من عبادك نصيبا مفروضا', NULL, 97, 'local:warsh-text.json'),
  ('warsh-4-118', 'warsh', 4, 118, 'وَلَأُضِلَّنَّهُمْ وَلَأُمَنِّيَنَّهُمْ وَلَأٓمُرَنَّهُمْ فَلَيُبَتِّكُنَّ ءَاذَانَ ࡰ۬لَانْعَٰمِ وَلَأٓمُرَنَّهُمْ فَلَيُغَيِّرُنَّ خَلْقَ ࡰ۬للَّهِ࣌ وَمَنْ يَّتَّخِذِ ࡴ۬لشَّيْطَٰنَ وَلِيّاࣰ مِّن دُونِ ࡴ۬للَّهِ فَقَدْ خَسِرَ خُسْرَاناࣰ مُّبِيناࣰ࣌', 'ولأضلنهم ولأمنينهم ولأمرنهم فليبتكن ءاذان ࡰلانعم ولأمرنهم فليغيرن خلق ࡰلله࣌ ومن يتخذ ࡴلشيطن وليا من دون ࡴلله فقد خسر خسرانا مبينا࣌', NULL, 97, 'local:warsh-text.json'),
  ('warsh-4-119', 'warsh', 4, 119, 'يَعِدُهُمْ وَيُمَنِّيهِمْ࣌ وَمَا يَعِدُهُمُ ࡲ۬لشَّيْطَٰنُ إِلَّا غُرُوراً࣌', 'يعدهم ويمنيهم࣌ وما يعدهم ࡲلشيطن إلا غرورا࣌', NULL, 97, 'local:warsh-text.json'),
  ('warsh-4-120', 'warsh', 4, 120, 'ࡳوْلَٰٓئِكَ مَأْوٜيٰهُمْ جَهَنَّمُ࣌ وَلَا يَجِدُونَ عَنْهَا مَحِيصاࣰ࣌', 'ࡳولئك مأويهم جهنم࣌ ولا يجدون عنها محيصا࣌', NULL, 97, 'local:warsh-text.json'),
  ('warsh-4-121', 'warsh', 4, 121, 'وَالذِينَ ءَامَنُواْ وَعَمِلُواْ ࡲ۬لصَّٰلِحَٰتِ سَنُدْخِلُهُمْ جَنَّٰتࣲ تَجْرِے مِن تَحْتِهَا ࡰ۬لَانْهَٰرُ خَٰلِدِينَ فِيهَآ أَبَداࣰ࣌ وَعْدَ ࡰ۬للَّهِ حَقّاࣰ࣌ وَمَنَ ࡰصْدَقُ مِنَ ࡰ۬للَّهِ قِيلاࣰ࣌', 'والذين ءامنوا وعملوا ࡲلصلحت سندخلهم جنت تجرے من تحتها ࡰلانهر خلدين فيها أبدا࣌ وعد ࡰلله حقا࣌ ومن ࡰصدق من ࡰلله قيلا࣌', NULL, 98, 'local:warsh-text.json'),
  ('warsh-4-122', 'warsh', 4, 122, 'لَّيْسَ بِأَمَانِيِّكُمْ وَلَآ أَمَانِيِّ أَهْلِ ࡴ۬لْكِتَٰبِ࣌ مَنْ يَّعْمَلْ سُوٓءاࣰ يُجْزَ بِهِۦ وَلَا يَجِدْ لَهُۥ مِن دُونِ ࡴ۬للَّهِ وَلِيّاࣰ وَلَا نَصِيراࣰ࣌', 'ليس بأمانيكم ولا أماني أهل ࡴلكتب࣌ من يعمل سوءا يجز به ولا يجد له من دون ࡴلله وليا ولا نصيرا࣌', NULL, 98, 'local:warsh-text.json'),
  ('warsh-4-123', 'warsh', 4, 123, '۞ وَمَنْ يَّعْمَلْ مِنَ ࡰ۬لصَّٰلِحَٰتِ مِن ذَكَرٍ ࡰوُ ࡳنثٜىٰ وَهُوَ مُومِنࣱ فَأُوْلَٰٓئِكَ يَدْخُلُونَ ࡰ۬لْجَنَّةَ وَلَا يُظْلَمُونَ نَقِيراࣰ࣌', 'ومن يعمل من ࡰلصلحت من ذكر ࡰو ࡳنثى وهو مومن فأولئك يدخلون ࡰلجنة ولا يظلمون نقيرا࣌', NULL, 98, 'local:warsh-text.json'),
  ('warsh-4-124', 'warsh', 4, 124, 'وَمَنَ ࡰحْسَنُ دِيناࣰ مِّمَّنَ ࡰسْلَمَ وَجْهَهُۥ لِلهِ وَهُوَ مُحْسِنࣱ وَاتَّبَعَ مِلَّةَ إِبْرَٰهِيمَ حَنِيفاࣰ࣌ وَاتَّخَذَ ࡰ۬للَّهُ إِبْرَٰهِيمَ خَلِيلاࣰ࣌', 'ومن ࡰحسن دينا ممن ࡰسلم وجهه لله وهو محسن واتبع ملة إبرهيم حنيفا࣌ واتخذ ࡰلله إبرهيم خليلا࣌', NULL, 98, 'local:warsh-text.json'),
  ('warsh-4-125', 'warsh', 4, 125, 'وَلِلهِ مَا فِے ࡴ۬لسَّمَٰوَٰتِ وَمَا فِے ࡴ۬لَارْضِ࣌ وَكَانَ ࡰ۬للَّهُ بِكُلِّ شَےْءࣲ مُّحِيطاࣰ࣌', 'ولله ما فے ࡴلسموت وما فے ࡴلارض࣌ وكان ࡰلله بكل شےء محيطا࣌', NULL, 98, 'local:warsh-text.json'),
  ('warsh-4-126', 'warsh', 4, 126, 'وَيَسْتَفْتُونَكَ فِے ࡴ۬لنِّسَآءِ࣌ قُلِ ࡴ۬للَّهُ يُفْتِيكُمْ فِيهِنَّ وَمَا يُتْلٜىٰ عَلَيْكُمْ فِے ࡴ۬لْكِتَٰبِ فِے يَتَٰمَى ࡰ۬لنِّسَآءِ ࡴ۬لتِے لَا تُوتُونَهُنَّ مَا كُتِبَ لَهُنَّ وَتَرْغَبُونَ أَن تَنكِحُوهُنَّ وَالْمُسْتَضْعَفِينَ مِنَ ࡰ۬لْوِلْدَٰنِ وَأَن تَقُومُواْ لِلْيَتَٰمٜىٰ بِالْقِسْطِ࣌ وَمَا تَفْعَلُواْ مِنْ خَيْرࣲ فَإِنَّ ࡰ۬للَّهَ كَانَ بِهِۦ عَلِيماࣰ࣌', 'ويستفتونك فے ࡴلنساء࣌ قل ࡴلله يفتيكم فيهن وما يتلى عليكم فے ࡴلكتب فے يتمى ࡰلنساء ࡴلتے لا توتونهن ما كتب لهن وترغبون أن تنكحوهن والمستضعفين من ࡰلولدن وأن تقوموا لليتمى بالقسط࣌ وما تفعلوا من خير فإن ࡰلله كان به عليما࣌', NULL, 98, 'local:warsh-text.json'),
  ('warsh-4-127', 'warsh', 4, 127, 'وَإِنِ ࡴٜمْرَأَةٌ خَافَتْ مِنۢ بَعْلِهَا نُشُوزاً ࡰوِ ࡴعْرَاضاࣰ فَلَا جُنَاحَ عَلَيْهِمَآ أَنْ يَّصَّٰلَحَا بَيْنَهُمَا صُلْحاࣰ࣌ وَالصُّلْحُ خَيْرࣱ࣌ وَأُحْضِرَتِ ࡴ۬لَانفُسُ ࡲ۬لشُّحَّ࣌ وَإِن تُحْسِنُواْ وَتَتَّقُواْ فَإِنَّ ࡰ۬للَّهَ كَانَ بِمَا تَعْمَلُونَ خَبِيراࣰ࣌', 'وإن ࡴمرأة خافت من بعلها نشوزا ࡰو ࡴعراضا فلا جناح عليهما أن يصلحا بينهما صلحا࣌ والصلح خير࣌ وأحضرت ࡴلانفس ࡲلشح࣌ وإن تحسنوا وتتقوا فإن ࡰلله كان بما تعملون خبيرا࣌', NULL, 99, 'local:warsh-text.json'),
  ('warsh-4-128', 'warsh', 4, 128, 'وَلَن تَسْتَطِيعُوٓاْ أَن تَعْدِلُواْ بَيْنَ ࡰ۬لنِّسَآءِ وَلَوْ حَرَصْتُمْ࣌ فَلَا تَمِيلُواْ كُلَّ ࡰ۬لْمَيْلِ فَتَذَرُوهَا كَالْمُعَلَّقَةِ࣌ وَإِن تُصْلِحُواْ وَتَتَّقُواْ فَإِنَّ ࡰ۬للَّهَ كَانَ غَفُوراࣰ رَّحِيماࣰ࣌', 'ولن تستطيعوا أن تعدلوا بين ࡰلنساء ولو حرصتم࣌ فلا تميلوا كل ࡰلميل فتذروها كالمعلقة࣌ وإن تصلحوا وتتقوا فإن ࡰلله كان غفورا رحيما࣌', NULL, 99, 'local:warsh-text.json'),
  ('warsh-4-129', 'warsh', 4, 129, '۞ وَإِنْ يَّتَفَرَّقَا يُغْنِ ࡴ۬للَّهُ كُلّاࣰ مِّن سَعَتِهِۦ࣌ وَكَانَ ࡰ۬للَّهُ وَٰسِعاً حَكِيماࣰ࣌', 'وإن يتفرقا يغن ࡴلله كلا من سعته࣌ وكان ࡰلله وسعا حكيما࣌', NULL, 99, 'local:warsh-text.json'),
  ('warsh-4-130', 'warsh', 4, 130, 'وَلِلهِ مَا فِے ࡴ۬لسَّمَٰوَٰتِ وَمَا فِے ࡴ۬لَارْضِ࣌ وَلَقَدْ وَصَّيْنَا ࡰ۬لذِينَ أُوتُواْ ࡲ۬لْكِتَٰبَ مِن قَبْلِكُمْ وَإِيَّاكُمُۥٓ أَنِ ࡴٜتَّقُواْ ࡲ۬للَّهَ࣌ وَإِن تَكْفُرُواْ فَإِنَّ لِلهِ مَا فِے ࡴ۬لسَّمَٰوَٰتِ وَمَا فِے ࡴ۬لَارْضِ࣌ وَكَانَ ࡰ۬للَّهُ غَنِيّاً حَمِيداࣰ࣌', 'ولله ما فے ࡴلسموت وما فے ࡴلارض࣌ ولقد وصينا ࡰلذين أوتوا ࡲلكتب من قبلكم وإياكم أن ࡴتقوا ࡲلله࣌ وإن تكفروا فإن لله ما فے ࡴلسموت وما فے ࡴلارض࣌ وكان ࡰلله غنيا حميدا࣌', NULL, 99, 'local:warsh-text.json'),
  ('warsh-4-131', 'warsh', 4, 131, 'وَلِلهِ مَا فِے ࡴ۬لسَّمَٰوَٰتِ وَمَا فِے ࡴ۬لَارْضِ࣌ وَكَفٜىٰ بِاللَّهِ وَكِيلاً࣌', 'ولله ما فے ࡴلسموت وما فے ࡴلارض࣌ وكفى بالله وكيلا࣌', NULL, 99, 'local:warsh-text.json'),
  ('warsh-4-132', 'warsh', 4, 132, 'ࡴنْ يَّشَأْ يُذْهِبْكُمُۥٓ أَيُّهَا ࡰ۬لنَّاسُ وَيَاتِ بِـَٔاخَرِينَ࣌ وَكَانَ ࡰ۬للَّهُ عَلَىٰ ذَٰلِكَ قَدِيراࣰ࣌', 'ࡴن يشأ يذهبكم أيها ࡰلناس ويات باخرين࣌ وكان ࡰلله على ذلك قديرا࣌', NULL, 99, 'local:warsh-text.json'),
  ('warsh-4-133', 'warsh', 4, 133, 'مَّن كَانَ يُرِيدُ ثَوَابَ ࡰ۬لدُّنْيٜا فَعِندَ ࡰ۬للَّهِ ثَوَابُ ࡲ۬لدُّنْيٜا وَالَاخِرَةِ࣌ وَكَانَ ࡰ۬للَّهُ سَمِيعاَۢ بَصِيراࣰ࣌', 'من كان يريد ثواب ࡰلدنيا فعند ࡰلله ثواب ࡲلدنيا والاخرة࣌ وكان ࡰلله سميعا بصيرا࣌', NULL, 99, 'local:warsh-text.json'),
  ('warsh-4-134', 'warsh', 4, 134, 'يَٰٓأَيُّهَا ࡰ۬لذِينَ ءَامَنُواْ كُونُواْ قَوَّٰمِينَ بِالْقِسْطِ شُهَدَآءَ لِلهِ وَلَوْ عَلَىٰٓ أَنفُسِكُمُۥٓ أَوِ ࡴ۬لْوَٰلِدَيْنِ وَالَاقْرَبِينَ࣌ إِنْ يَّكُنْ غَنِيّاً ࡰوْ فَقِيراࣰ فَاللَّهُ أَوْلٜىٰ بِهِمَا فَلَا تَتَّبِعُواْ ࡲ۬لْهَوٜىٰٓ أَن تَعْدِلُواْ࣌ وَإِن تَلْوُۥٓاْ أَوْ تُعْرِضُواْ فَإِنَّ ࡰ۬للَّهَ كَانَ بِمَا تَعْمَلُونَ خَبِيراࣰ࣌', 'يأيها ࡰلذين ءامنوا كونوا قومين بالقسط شهداء لله ولو على أنفسكم أو ࡴلولدين والاقربين࣌ إن يكن غنيا ࡰو فقيرا فالله أولى بهما فلا تتبعوا ࡲلهوى أن تعدلوا࣌ وإن تلوا أو تعرضوا فإن ࡰلله كان بما تعملون خبيرا࣌', NULL, 100, 'local:warsh-text.json'),
  ('warsh-4-135', 'warsh', 4, 135, 'يَٰٓأَيُّهَا ࡰ۬لذِينَ ءَامَنُوٓاْ ءَامِنُواْ بِاللَّهِ وَرَسُولِهِۦ وَالْكِتَٰبِ ࡴ۬لذِے نَزَّلَ عَلَىٰ رَسُولِهِۦ وَالْكِتَٰبِ ࡴ۬لذِےٓ أَنزَلَ مِن قَبْلُ࣌ وَمَنْ يَّكْفُرْ بِاللَّهِ وَمَلَٰٓئِكَتِهِۦ وَكُتُبِهِۦ وَرُسُلِهِۦ وَالْيَوْمِ ࡴ۬لَاخِرِ فَقَد ضَّلَّ ضَلَٰلاَۢ بَعِيداً࣌', 'يأيها ࡰلذين ءامنوا ءامنوا بالله ورسوله والكتب ࡴلذے نزل على رسوله والكتب ࡴلذے أنزل من قبل࣌ ومن يكفر بالله وملئكته وكتبه ورسله واليوم ࡴلاخر فقد ضل ضللا بعيدا࣌', NULL, 100, 'local:warsh-text.json'),
  ('warsh-4-136', 'warsh', 4, 136, 'ࡴنَّ ࡰ۬لذِينَ ءَامَنُواْ ثُمَّ كَفَرُواْ ثُمَّ ءَامَنُواْ ثُمَّ كَفَرُواْ ثُمَّ ࡰٜزْدَادُواْ كُفْراࣰ لَّمْ يَكُنِ ࡴ۬للَّهُ لِيَغْفِرَ لَهُمْ وَلَا لِيَهْدِيَهُمْ سَبِيلاَۢ࣌', 'ࡴن ࡰلذين ءامنوا ثم كفروا ثم ءامنوا ثم كفروا ثم ࡰزدادوا كفرا لم يكن ࡴلله ليغفر لهم ولا ليهديهم سبيلا࣌', NULL, 100, 'local:warsh-text.json'),
  ('warsh-4-137', 'warsh', 4, 137, 'بَشِّرِ ࡴ۬لْمُنَٰفِقِينَ بِأَنَّ لَهُمْ عَذَاباً ࡰلِيماً', 'بشر ࡴلمنفقين بأن لهم عذابا ࡰليما', NULL, 100, 'local:warsh-text.json'),
  ('warsh-4-138', 'warsh', 4, 138, 'ࡴ۬لذِينَ يَتَّخِذُونَ ࡰ۬لْكٜـٰفِرِينَ أَوْلِيَآءَ مِن دُونِ ࡴ۬لْمُومِنِينَ࣌ أَيَبْتَغُونَ عِندَهُمُ ࡲ۬لْعِزَّةَ فَإِنَّ ࡰ۬لْعِزَّةَ لِلهِ جَمِيعاࣰ࣌', 'ࡴلذين يتخذون ࡰلكفرين أولياء من دون ࡴلمومنين࣌ أيبتغون عندهم ࡲلعزة فإن ࡰلعزة لله جميعا࣌', NULL, 100, 'local:warsh-text.json'),
  ('warsh-4-139', 'warsh', 4, 139, '۞ وَقَدْ نُزِّلَ عَلَيْكُمْ فِے ࡴ۬لْكِتَٰبِ أَنِ ࡴذَا سَمِعْتُمُۥٓ ءَايَٰتِ ࡴ۬للَّهِ يُكْفَرُ بِهَا وَيُسْتَهْزَأُ بِهَا فَلَا تَقْعُدُواْ مَعَهُمْ حَتَّىٰ يَخُوضُواْ فِے حَدِيثٍ غَيْرِهِۦٓ࣌ إِنَّكُمُۥٓ إِذاࣰ مِّثْلُهُمُۥٓ࣌ إِنَّ ࡰ۬للَّهَ جَامِعُ ࡲ۬لْمُنَٰفِقِينَ وَالْكٜـٰفِرِينَ فِے جَهَنَّمَ جَمِيعاً', 'وقد نزل عليكم فے ࡴلكتب أن ࡴذا سمعتم ءايت ࡴلله يكفر بها ويستهزأ بها فلا تقعدوا معهم حتى يخوضوا فے حديث غيره࣌ إنكم إذا مثلهم࣌ إن ࡰلله جامع ࡲلمنفقين والكفرين فے جهنم جميعا', NULL, 100, 'local:warsh-text.json'),
  ('warsh-4-140', 'warsh', 4, 140, 'ࡴ۬لذِينَ يَتَرَبَّصُونَ بِكُمْ فَإِن كَانَ لَكُمْ فَتْحࣱ مِّنَ ࡰ۬للَّهِ قَالُوٓاْ أَلَمْ نَكُن مَّعَكُمْ وَإِن كَانَ لِلْكٜـٰفِرِينَ نَصِيبࣱ قَالُوٓاْ أَلَمْ نَسْتَحْوِذْ عَلَيْكُمْ وَنَمْنَعْكُم مِّنَ ࡰ۬لْمُومِنِينَ࣌ فَاللَّهُ يَحْكُمُ بَيْنَكُمْ يَوْمَ ࡰ۬لْقِيَٰمَةِ࣌ وَلَنْ يَّجْعَلَ ࡰ۬للَّهُ لِلْكٜـٰفِرِينَ عَلَى ࡰ۬لْمُومِنِينَ سَبِيلاً࣌', 'ࡴلذين يتربصون بكم فإن كان لكم فتح من ࡰلله قالوا ألم نكن معكم وإن كان للكفرين نصيب قالوا ألم نستحوذ عليكم ونمنعكم من ࡰلمومنين࣌ فالله يحكم بينكم يوم ࡰلقيمة࣌ ولن يجعل ࡰلله للكفرين على ࡰلمومنين سبيلا࣌', NULL, 101, 'local:warsh-text.json'),
  ('warsh-4-141', 'warsh', 4, 141, 'ࡴنَّ ࡰ۬لْمُنَٰفِقِينَ يُخَٰدِعُونَ ࡰ۬للَّهَ وَهُوَ خَٰدِعُهُمْ࣌ وَإِذَا قَامُوٓاْ إِلَى ࡰ۬لصَّلَوٰةِ قَامُواْ كُسَالٜىٰ يُرَآءُونَ ࡰ۬لنَّاسَ وَلَا يَذْكُرُونَ ࡰ۬للَّهَ إِلَّا قَلِيلاࣰ', 'ࡴن ࡰلمنفقين يخدعون ࡰلله وهو خدعهم࣌ وإذا قاموا إلى ࡰلصلوة قاموا كسالى يراءون ࡰلناس ولا يذكرون ࡰلله إلا قليلا', NULL, 101, 'local:warsh-text.json'),
  ('warsh-4-142', 'warsh', 4, 142, 'مُّذَبْذَبِينَ بَيْنَ ذَٰلِكَ لَآ إِلَىٰ هَٰٓؤُلَآءِ وَلَآ إِلَىٰ هَٰٓؤُلَآءِ࣌ وَمَنْ يُّضْلِلِ ࡴ۬للَّهُ فَلَن تَجِدَ لَهُۥ سَبِيلاࣰ࣌', 'مذبذبين بين ذلك لا إلى هؤلاء ولا إلى هؤلاء࣌ ومن يضلل ࡴلله فلن تجد له سبيلا࣌', NULL, 101, 'local:warsh-text.json'),
  ('warsh-4-143', 'warsh', 4, 143, 'يَٰٓأَيُّهَا ࡰ۬لذِينَ ءَامَنُواْ لَا تَتَّخِذُواْ ࡲ۬لْكٜـٰفِرِينَ أَوْلِيَآءَ مِن دُونِ ࡴ۬لْمُومِنِينَ࣌ أَتُرِيدُونَ أَن تَجْعَلُواْ لِلهِ عَلَيْكُمْ سُلْطَٰناࣰ مُّبِيناً࣌', 'يأيها ࡰلذين ءامنوا لا تتخذوا ࡲلكفرين أولياء من دون ࡴلمومنين࣌ أتريدون أن تجعلوا لله عليكم سلطنا مبينا࣌', NULL, 101, 'local:warsh-text.json'),
  ('warsh-4-144', 'warsh', 4, 144, 'ࡴنَّ ࡰ۬لْمُنَٰفِقِينَ فِے ࡴ۬لدَّرَكِ ࡴ۬لَاسْفَلِ مِنَ ࡰ۬لنّٜارِ وَلَن تَجِدَ لَهُمْ نَصِيراً࣌', 'ࡴن ࡰلمنفقين فے ࡴلدرك ࡴلاسفل من ࡰلنار ولن تجد لهم نصيرا࣌', NULL, 101, 'local:warsh-text.json'),
  ('warsh-4-145', 'warsh', 4, 145, 'ࡴلَّا ࡰ۬لذِينَ تَابُواْ وَأَصْلَحُواْ وَاعْتَصَمُواْ بِاللَّهِ وَأَخْلَصُواْ دِينَهُمْ لِلهِ فَأُوْلَٰٓئِكَ مَعَ ࡰ۬لْمُومِنِينَ࣌ وَسَوْفَ يُوتِ ࡴ۬للَّهُ ࡲ۬لْمُومِنِينَ أَجْراً عَظِيماࣰ࣌', 'ࡴلا ࡰلذين تابوا وأصلحوا واعتصموا بالله وأخلصوا دينهم لله فأولئك مع ࡰلمومنين࣌ وسوف يوت ࡴلله ࡲلمومنين أجرا عظيما࣌', NULL, 101, 'local:warsh-text.json'),
  ('warsh-4-146', 'warsh', 4, 146, 'مَّا يَفْعَلُ ࡲ۬للَّهُ بِعَذَابِكُمُۥٓ إِن شَكَرْتُمْ وَءَامَنتُمْ࣌ وَكَانَ ࡰ۬للَّهُ شَاكِراً عَلِيماࣰ࣌', 'ما يفعل ࡲلله بعذابكم إن شكرتم وءامنتم࣌ وكان ࡰلله شاكرا عليما࣌', NULL, 101, 'local:warsh-text.json'),
  ('warsh-4-147', 'warsh', 4, 147, '۞ لَّا يُحِبُّ ࡲ۬للَّهُ ࡲ۬لْجَهْرَ بِالسُّوٓءِ مِنَ ࡰ۬لْقَوْلِ إِلَّا مَن ظُلِمَ࣌ وَكَانَ ࡰ۬للَّهُ سَمِيعاً عَلِيماً࣌', 'لا يحب ࡲلله ࡲلجهر بالسوء من ࡰلقول إلا من ظلم࣌ وكان ࡰلله سميعا عليما࣌', NULL, 102, 'local:warsh-text.json'),
  ('warsh-4-148', 'warsh', 4, 148, 'ࡴن تُبْدُواْ خَيْراً ࡰوْ تُخْفُوهُ أَوْ تَعْفُواْ عَن سُوٓءࣲ فَإِنَّ ࡰ۬للَّهَ كَانَ عَفُوّاࣰ قَدِيراً࣌', 'ࡴن تبدوا خيرا ࡰو تخفوه أو تعفوا عن سوء فإن ࡰلله كان عفوا قديرا࣌', NULL, 102, 'local:warsh-text.json'),
  ('warsh-4-149', 'warsh', 4, 149, 'ࡴنَّ ࡰ۬لذِينَ يَكْفُرُونَ بِاللَّهِ وَرُسُلِهِۦ وَيُرِيدُونَ أَنْ يُّفَرِّقُواْ بَيْنَ ࡰ۬للَّهِ وَرُسُلِهِۦ وَيَقُولُونَ نُومِنُ بِبَعْضࣲ وَنَكْفُرُ بِبَعْضࣲ وَيُرِيدُونَ أَنْ يَّتَّخِذُواْ بَيْنَ ذَٰلِكَ سَبِيلاً', 'ࡴن ࡰلذين يكفرون بالله ورسله ويريدون أن يفرقوا بين ࡰلله ورسله ويقولون نومن ببعض ونكفر ببعض ويريدون أن يتخذوا بين ذلك سبيلا', NULL, 102, 'local:warsh-text.json'),
  ('warsh-4-150', 'warsh', 4, 150, 'ࡳوْلَٰٓئِكَ هُمُ ࡲ۬لْكَٰفِرُونَ حَقّاࣰ࣌ وَأَعْتَدْنَا لِلْكٜـٰفِرِينَ عَذَاباࣰ مُّهِيناࣰ࣌', 'ࡳولئك هم ࡲلكفرون حقا࣌ وأعتدنا للكفرين عذابا مهينا࣌', NULL, 102, 'local:warsh-text.json'),
  ('warsh-4-151', 'warsh', 4, 151, 'وَالذِينَ ءَامَنُواْ بِاللَّهِ وَرُسُلِهِۦ وَلَمْ يُفَرِّقُواْ بَيْنَ أَحَدࣲ مِّنْهُمُۥٓ أُوْلَٰٓئِكَ سَوْفَ نُوتِيهِمُۥٓ أُجُورَهُمْ࣌ وَكَانَ ࡰ۬للَّهُ غَفُوراࣰ رَّحِيماࣰ࣌', 'والذين ءامنوا بالله ورسله ولم يفرقوا بين أحد منهم أولئك سوف نوتيهم أجورهم࣌ وكان ࡰلله غفورا رحيما࣌', NULL, 102, 'local:warsh-text.json'),
  ('warsh-4-152', 'warsh', 4, 152, 'يَسْـَٔلُكَ أَهْلُ ࡲ۬لْكِتَٰبِ أَن تُنَزِّلَ عَلَيْهِمْ كِتَٰباࣰ مِّنَ ࡰ۬لسَّمَآءِ࣌ فَقَدْ سَأَلُواْ مُوسٜىٰٓ أَكْبَرَ مِن ذَٰلِكَ فَقَالُوٓاْ أَرِنَا ࡰ۬للَّهَ جَهْرَةࣰ فَأَخَذَتْهُمُ ࡲ۬لصَّٰعِقَةُ بِظُلْمِهِمْ࣌ ثُمَّ ࡰٜتَّخَذُواْ ࡲ۬لْعِجْلَ مِنۢ بَعْدِ مَا جَآءَتْهُمُ ࡲ۬لْبَيِّنَٰتُ فَعَفَوْنَا عَن ذَٰلِكَ࣌ وَءَاتَيْنَا مُوسٜىٰ سُلْطَٰناࣰ مُّبِيناࣰ࣌', 'يسلك أهل ࡲلكتب أن تنزل عليهم كتبا من ࡰلسماء࣌ فقد سألوا موسى أكبر من ذلك فقالوا أرنا ࡰلله جهرة فأخذتهم ࡲلصعقة بظلمهم࣌ ثم ࡰتخذوا ࡲلعجل من بعد ما جاءتهم ࡲلبينت فعفونا عن ذلك࣌ وءاتينا موسى سلطنا مبينا࣌', NULL, 102, 'local:warsh-text.json'),
  ('warsh-4-153', 'warsh', 4, 153, 'وَرَفَعْنَا فَوْقَهُمُ ࡲ۬لطُّورَ بِمِيثَٰقِهِمْ࣌ وَقُلْنَا لَهُمُ ࡲ࢈دْخُلُواْ ࡲ۬لْبَابَ سُجَّداࣰ࣌ وَقُلْنَا لَهُمْ لَا تَعَدُّواْ فِے ࡴ۬لسَّبْتِ࣌ وَأَخَذْنَا مِنْهُم مِّيثَٰقاً غَلِيظاࣰ࣌', 'ورفعنا فوقهم ࡲلطور بميثقهم࣌ وقلنا لهم ࡲ࢈دخلوا ࡲلباب سجدا࣌ وقلنا لهم لا تعدوا فے ࡴلسبت࣌ وأخذنا منهم ميثقا غليظا࣌', NULL, 102, 'local:warsh-text.json'),
  ('warsh-4-154', 'warsh', 4, 154, 'فَبِمَا نَقْضِهِم مِّيثَٰقَهُمْ وَكُفْرِهِم بِـَٔايَٰتِ ࡴ۬للَّهِ وَقَتْلِهِمُ ࡲ۬لَانۢبِئَآءَ بِغَيْرِ حَقࣲّ وَقَوْلِهِمْ قُلُوبُنَا غُلْفُۢ بَلْ طَبَعَ ࡰ۬للَّهُ عَلَيْهَا بِكُفْرِهِمْ فَلَا يُومِنُونَ إِلَّا قَلِيلاࣰ', 'فبما نقضهم ميثقهم وكفرهم بايت ࡴلله وقتلهم ࡲلانبئاء بغير حق وقولهم قلوبنا غلف بل طبع ࡰلله عليها بكفرهم فلا يومنون إلا قليلا', NULL, 103, 'local:warsh-text.json'),
  ('warsh-4-155', 'warsh', 4, 155, 'وَبِكُفْرِهِمْ وَقَوْلِهِمْ عَلَىٰ مَرْيَمَ بُهْتَٰناً عَظِيماࣰ', 'وبكفرهم وقولهم على مريم بهتنا عظيما', NULL, 103, 'local:warsh-text.json'),
  ('warsh-4-156', 'warsh', 4, 156, 'وَقَوْلِهِمُۥٓ إِنَّا قَتَلْنَا ࡰ۬لْمَسِيحَ عِيسَى ࡰٜبْنَ مَرْيَمَ رَسُولَ ࡰ۬للَّهِ࣌ ۞ وَمَا قَتَلُوهُ وَمَا صَلَبُوهُ وَلَٰكِن شُبِّهَ لَهُمْ࣌ وَإِنَّ ࡰ۬لذِينَ ࡰٜخْتَلَفُواْ فِيهِ لَفِے شَكࣲّ مِّنْهُ࣌ مَا لَهُم بِهِۦ مِنْ عِلْمٍ࣌ ࡴلَّا ࡰٜتِّبَاعَ ࡰ۬لظَّنِّ࣌ وَمَا قَتَلُوهُ يَقِيناَۢ࣌', 'وقولهم إنا قتلنا ࡰلمسيح عيسى ࡰبن مريم رسول ࡰلله࣌  وما قتلوه وما صلبوه ولكن شبه لهم࣌ وإن ࡰلذين ࡰختلفوا فيه لفے شك منه࣌ ما لهم به من علم࣌ ࡴلا ࡰتباع ࡰلظن࣌ وما قتلوه يقينا࣌', NULL, 103, 'local:warsh-text.json'),
  ('warsh-4-157', 'warsh', 4, 157, 'بَل رَّفَعَهُ ࡲ۬للَّهُ إِلَيْهِ࣌ وَكَانَ ࡰ۬للَّهُ عَزِيزاً حَكِيماࣰ࣌', 'بل رفعه ࡲلله إليه࣌ وكان ࡰلله عزيزا حكيما࣌', NULL, 103, 'local:warsh-text.json'),
  ('warsh-4-158', 'warsh', 4, 158, 'وَإِن مِّنَ ࡰهْلِ ࡴ۬لْكِتَٰبِ إِلَّا لَيُومِنَنَّ بِهِۦ قَبْلَ مَوْتِهِۦ وَيَوْمَ ࡰ۬لْقِيَٰمَةِ يَكُونُ عَلَيْهِمْ شَهِيداࣰ࣌', 'وإن من ࡰهل ࡴلكتب إلا ليومنن به قبل موته ويوم ࡰلقيمة يكون عليهم شهيدا࣌', NULL, 103, 'local:warsh-text.json'),
  ('warsh-4-159', 'warsh', 4, 159, 'فَبِظُلْمࣲ مِّنَ ࡰ۬لذِينَ هَادُواْ حَرَّمْنَا عَلَيْهِمْ طَيِّبَٰتٍ ࡳحِلَّتْ لَهُمْ وَبِصَدِّهِمْ عَن سَبِيلِ ࡴ۬للَّهِ كَثِيراࣰ', 'فبظلم من ࡰلذين هادوا حرمنا عليهم طيبت ࡳحلت لهم وبصدهم عن سبيل ࡴلله كثيرا', NULL, 103, 'local:warsh-text.json'),
  ('warsh-4-160', 'warsh', 4, 160, 'وَأَخْذِهِمُ ࡲ۬لرِّبَوٰاْ وَقَدْ نُهُواْ عَنْهُ وَأَكْلِهِمُۥٓ أَمْوَٰلَ ࡰ۬لنَّاسِ بِالْبَٰطِلِ࣌ وَأَعْتَدْنَا لِلْكٜـٰفِرِينَ مِنْهُمْ عَذَاباً ࡰلِيماࣰ࣌', 'وأخذهم ࡲلربوا وقد نهوا عنه وأكلهم أمول ࡰلناس بالبطل࣌ وأعتدنا للكفرين منهم عذابا ࡰليما࣌', NULL, 103, 'local:warsh-text.json'),
  ('warsh-4-161', 'warsh', 4, 161, 'لَّٰكِنِ ࡴ۬لرَّٰسِخُونَ فِے ࡴ۬لْعِلْمِ مِنْهُمْ وَالْمُومِنُونَ يُومِنُونَ بِمَآ أُنزِلَ إِلَيْكَ وَمَآ أُنزِلَ مِن قَبْلِكَ وَالْمُقِيمِينَ ࡰ۬لصَّلَوٰةَ࣌ وَالْمُوتُونَ ࡰ۬لزَّكَوٰةَ وَالْمُومِنُونَ بِاللَّهِ وَالْيَوْمِ ࡴ۬لَاخِرِ أُوْلَٰٓئِكَ سَنُوتِيهِمُۥٓ أَجْراً عَظِيماً࣌', 'لكن ࡴلرسخون فے ࡴلعلم منهم والمومنون يومنون بما أنزل إليك وما أنزل من قبلك والمقيمين ࡰلصلوة࣌ والموتون ࡰلزكوة والمومنون بالله واليوم ࡴلاخر أولئك سنوتيهم أجرا عظيما࣌', NULL, 103, 'local:warsh-text.json'),
  ('warsh-4-162', 'warsh', 4, 162, 'ࡴنَّآ أَوْحَيْنَآ إِلَيْكَ كَمَآ أَوْحَيْنَآ إِلَىٰ نُوحࣲ وَالنَّبِيٓـِٕۑنَ مِنۢ بَعْدِهِۦ࣌ وَأَوْحَيْنَآ إِلَىٰٓ إِبْرَٰهِيمَ وَإِسْمَٰعِيلَ وَإِسْحَٰقَ وَيَعْقُوبَ وَالَاسْبَاطِ وَعِيسٜىٰ وَأَيُّوبَ وَيُونُسَ وَهَٰرُونَ وَسُلَيْمَٰنَ࣌ وَءَاتَيْنَا دَاوُۥدَ زَبُوراࣰ࣌', 'ࡴنا أوحينا إليك كما أوحينا إلى نوح والنبيۑن من بعده࣌ وأوحينا إلى إبرهيم وإسمعيل وإسحق ويعقوب والاسباط وعيسى وأيوب ويونس وهرون وسليمن࣌ وءاتينا داود زبورا࣌', NULL, 104, 'local:warsh-text.json'),
  ('warsh-4-163', 'warsh', 4, 163, 'وَرُسُلاࣰ قَدْ قَصَصْنَٰهُمْ عَلَيْكَ مِن قَبْلُ وَرُسُلاࣰ لَّمْ نَقْصُصْهُمْ عَلَيْكَ࣌ وَكَلَّمَ ࡰ۬للَّهُ مُوسٜىٰ تَكْلِيماࣰ࣌', 'ورسلا قد قصصنهم عليك من قبل ورسلا لم نقصصهم عليك࣌ وكلم ࡰلله موسى تكليما࣌', NULL, 104, 'local:warsh-text.json'),
  ('warsh-4-164', 'warsh', 4, 164, 'رُّسُلاࣰ مُّبَشِّرِينَ وَمُنذِرِينَ لِيَ۬لَّا يَكُونَ لِلنَّاسِ عَلَى ࡰ۬للَّهِ حُجَّةُۢ بَعْدَ ࡰ۬لرُّسُلِ࣌ وَكَانَ ࡰ۬للَّهُ عَزِيزاً حَكِيماࣰ࣌', 'رسلا مبشرين ومنذرين ليلا يكون للناس على ࡰلله حجة بعد ࡰلرسل࣌ وكان ࡰلله عزيزا حكيما࣌', NULL, 104, 'local:warsh-text.json'),
  ('warsh-4-165', 'warsh', 4, 165, '۞ لَّٰكِنِ ࡴ۬للَّهُ يَشْهَدُ بِمَآ أَنزَلَ إِلَيْكَ࣌ أَنزَلَهُۥ بِعِلْمِهِۦ وَالْمَلَٰٓئِكَةُ يَشْهَدُونَ࣌ وَكَفٜىٰ بِاللَّهِ شَهِيداً࣌', 'لكن ࡴلله يشهد بما أنزل إليك࣌ أنزله بعلمه والملئكة يشهدون࣌ وكفى بالله شهيدا࣌', NULL, 104, 'local:warsh-text.json'),
  ('warsh-4-166', 'warsh', 4, 166, 'ࡴنَّ ࡰ۬لذِينَ كَفَرُواْ وَصَدُّواْ عَن سَبِيلِ ࡴ۬للَّهِ قَد ضَّلُّواْ ضَلَٰلاَۢ بَعِيداً࣌', 'ࡴن ࡰلذين كفروا وصدوا عن سبيل ࡴلله قد ضلوا ضللا بعيدا࣌', NULL, 104, 'local:warsh-text.json'),
  ('warsh-4-167', 'warsh', 4, 167, 'ࡴنَّ ࡰ۬لذِينَ كَفَرُواْ وَظَلَمُواْ لَمْ يَكُنِ ࡴ۬للَّهُ لِيَغْفِرَ لَهُمْ وَلَا لِيَهْدِيَهُمْ طَرِيقاً', 'ࡴن ࡰلذين كفروا وظلموا لم يكن ࡴلله ليغفر لهم ولا ليهديهم طريقا', NULL, 104, 'local:warsh-text.json'),
  ('warsh-4-168', 'warsh', 4, 168, 'ࡴلَّا طَرِيقَ جَهَنَّمَ خَٰلِدِينَ فِيهَآ أَبَداࣰ࣌ وَكَانَ ذَٰلِكَ عَلَى ࡰ۬للَّهِ يَسِيراࣰ࣌', 'ࡴلا طريق جهنم خلدين فيها أبدا࣌ وكان ذلك على ࡰلله يسيرا࣌', NULL, 104, 'local:warsh-text.json'),
  ('warsh-4-169', 'warsh', 4, 169, 'يَٰٓأَيُّهَا ࡰ۬لنَّاسُ قَدْ جَآءَكُمُ ࡲ۬لرَّسُولُ بِالْحَقِّ مِن رَّبِّكُمْ فَـَٔامِنُواْ خَيْراࣰ لَّكُمْ࣌ وَإِن تَكْفُرُواْ فَإِنَّ لِلهِ مَا فِے ࡴ۬لسَّمَٰوَٰتِ وَالَارْضِ࣌ وَكَانَ ࡰ۬للَّهُ عَلِيماً حَكِيماࣰ࣌', 'يأيها ࡰلناس قد جاءكم ࡲلرسول بالحق من ربكم فامنوا خيرا لكم࣌ وإن تكفروا فإن لله ما فے ࡴلسموت والارض࣌ وكان ࡰلله عليما حكيما࣌', NULL, 104, 'local:warsh-text.json'),
  ('warsh-4-170', 'warsh', 4, 170, 'يَٰٓأَهْلَ ࡰ۬لْكِتَٰبِ لَا تَغْلُواْ فِے دِينِكُمْ وَلَا تَقُولُواْ عَلَى ࡰ۬للَّهِ إِلَّا ࡰ۬لْحَقَّ࣌ إِنَّمَا ࡰ۬لْمَسِيحُ عِيسَى ࡰٜبْنُ مَرْيَمَ رَسُولُ ࡲ۬للَّهِ وَكَلِمَتُهُۥٓ࣌ أَلْقٜيٰهَآ إِلَىٰ مَرْيَمَ وَرُوحࣱ مِّنْهُ࣌ فَـَٔامِنُواْ بِاللَّهِ وَرُسُلِهِۦ࣌ وَلَا تَقُولُواْ ثَلَٰثَةٌ࣌ ࡴٜنتَهُواْ خَيْراࣰ لَّكُمُۥٓ࣌ إِنَّمَا ࡰ۬للَّهُ إِلَٰهࣱ وَٰحِدࣱ࣌ سُبْحَٰنَهُۥٓ أَنْ يَّكُونَ لَهُۥ وَلَدࣱ࣌ لَّهُۥ مَا فِے ࡴ۬لسَّمَٰوَٰتِ وَمَا فِے ࡴ۬لَارْضِ࣌ وَكَفٜىٰ بِاللَّهِ وَكِيلاࣰ࣌', 'يأهل ࡰلكتب لا تغلوا فے دينكم ولا تقولوا على ࡰلله إلا ࡰلحق࣌ إنما ࡰلمسيح عيسى ࡰبن مريم رسول ࡲلله وكلمته࣌ ألقيها إلى مريم وروح منه࣌ فامنوا بالله ورسله࣌ ولا تقولوا ثلثة࣌ ࡴنتهوا خيرا لكم࣌ إنما ࡰلله إله وحد࣌ سبحنه أن يكون له ولد࣌ له ما فے ࡴلسموت وما فے ࡴلارض࣌ وكفى بالله وكيلا࣌', NULL, 105, 'local:warsh-text.json'),
  ('warsh-4-171', 'warsh', 4, 171, 'لَّنْ يَّسْتَنكِفَ ࡰ۬لْمَسِيحُ أَنْ يَّكُونَ عَبْداࣰ لِّلهِ وَلَا ࡰ۬لْمَلَٰٓئِكَةُ ࡲ۬لْمُقَرَّبُونَ࣌ وَمَنْ يَّسْتَنكِفْ عَنْ عِبَادَتِهِۦ وَيَسْتَكْبِرْ فَسَيَحْشُرُهُمُۥٓ إِلَيْهِ جَمِيعاࣰ࣌', 'لن يستنكف ࡰلمسيح أن يكون عبدا لله ولا ࡰلملئكة ࡲلمقربون࣌ ومن يستنكف عن عبادته ويستكبر فسيحشرهم إليه جميعا࣌', NULL, 105, 'local:warsh-text.json'),
  ('warsh-4-172', 'warsh', 4, 172, 'فَأَمَّا ࡰ۬لذِينَ ءَامَنُواْ وَعَمِلُواْ ࡲ۬لصَّٰلِحَٰتِ فَيُوَفِّيهِمُۥٓ أُجُورَهُمْ وَيَزِيدُهُم مِّن فَضْلِهِۦ࣌ وَأَمَّا ࡰ۬لذِينَ ࡰٜسْتَنكَفُواْ وَاسْتَكْبَرُواْ فَيُعَذِّبُهُمْ عَذَاباً ࡰلِيماࣰ وَلَا يَجِدُونَ لَهُم مِّن دُونِ ࡴ۬للَّهِ وَلِيّاࣰ وَلَا نَصِيراࣰ࣌', 'فأما ࡰلذين ءامنوا وعملوا ࡲلصلحت فيوفيهم أجورهم ويزيدهم من فضله࣌ وأما ࡰلذين ࡰستنكفوا واستكبروا فيعذبهم عذابا ࡰليما ولا يجدون لهم من دون ࡴلله وليا ولا نصيرا࣌', NULL, 105, 'local:warsh-text.json'),
  ('warsh-4-173', 'warsh', 4, 173, '۞ يَٰٓأَيُّهَا ࡰ۬لنَّاسُ قَدْ جَآءَكُم بُرْهَٰنࣱ مِّن رَّبِّكُمْ وَأَنزَلْنَآ إِلَيْكُمْ نُوراࣰ مُّبِيناࣰ࣌', 'يأيها ࡰلناس قد جاءكم برهن من ربكم وأنزلنا إليكم نورا مبينا࣌', NULL, 105, 'local:warsh-text.json'),
  ('warsh-4-174', 'warsh', 4, 174, 'فَأَمَّا ࡰ۬لذِينَ ءَامَنُواْ بِاللَّهِ وَاعْتَصَمُواْ بِهِۦ فَسَيُدْخِلُهُمْ فِے رَحْمَةࣲ مِّنْهُ وَفَضْلࣲ وَيَهْدِيهِمُۥٓ إِلَيْهِ صِرَٰطاࣰ مُّسْتَقِيماࣰ࣌', 'فأما ࡰلذين ءامنوا بالله واعتصموا به فسيدخلهم فے رحمة منه وفضل ويهديهم إليه صرطا مستقيما࣌', NULL, 105, 'local:warsh-text.json'),
  ('warsh-4-175', 'warsh', 4, 175, 'يَسْتَفْتُونَكَ࣌ قُلِ ࡴ۬للَّهُ يُفْتِيكُمْ فِے ࡴ۬لْكَلَٰلَةِ࣌ إِنِ ࡴٜمْرُؤٌاْ هَلَكَ لَيْسَ لَهُۥ وَلَدࣱ وَلَهُۥٓ أُخْتࣱ فَلَهَا نِصْفُ مَا تَرَكَ࣌ وَهُوَ يَرِثُهَآ إِن لَّمْ يَكُن لَّهَا وَلَدࣱ࣌ فَإِن كَانَتَا ࡰٜثْنَتَيْنِ فَلَهُمَا ࡰ۬لثُّلُثَٰنِ مِمَّا تَرَكَ࣌ وَإِن كَانُوٓاْ إِخْوَةࣰ رِّجَالاࣰ وَنِسَآءࣰ فَلِلذَّكَرِ مِثْلُ حَظِّ ࡴ۬لُانثَيَيْنِ࣌ يُبَيِّنُ ࡲ۬للَّهُ لَكُمُۥٓ أَن تَضِلُّواْ࣌ وَاللَّهُ بِكُلِّ شَےْءٍ عَلِيمࣱ࣌', 'يستفتونك࣌ قل ࡴلله يفتيكم فے ࡴلكللة࣌ إن ࡴمرؤا هلك ليس له ولد وله أخت فلها نصف ما ترك࣌ وهو يرثها إن لم يكن لها ولد࣌ فإن كانتا ࡰثنتين فلهما ࡰلثلثن مما ترك࣌ وإن كانوا إخوة رجالا ونساء فللذكر مثل حظ ࡴلانثيين࣌ يبين ࡲلله لكم أن تضلوا࣌ والله بكل شےء عليم࣌', NULL, 106, 'local:warsh-text.json'),
  ('warsh-5-1', 'warsh', 5, 1, 'يَٰٓأَيُّهَا ࡰ۬لذِينَ ءَامَنُوٓاْ أَوْفُواْ بِالْعُقُودِ࣌', 'يأيها ࡰلذين ءامنوا أوفوا بالعقود࣌', NULL, 106, 'local:warsh-text.json'),
  ('warsh-5-2', 'warsh', 5, 2, 'أُحِلَّتْ لَكُم بَهِيمَةُ ࡲ۬لَانْعَٰمِ إِلَّا مَا يُتْلٜىٰ عَلَيْكُمْ غَيْرَ مُحِلِّے ࡴ۬لصَّيْدِ وَأَنتُمْ حُرُمٌ࣌ ࡴنَّ ࡰ۬للَّهَ يَحْكُمُ مَا يُرِيدُ࣌', 'أحلت لكم بهيمة ࡲلانعم إلا ما يتلى عليكم غير محلے ࡴلصيد وأنتم حرم࣌ ࡴن ࡰلله يحكم ما يريد࣌', NULL, 106, 'local:warsh-text.json'),
  ('warsh-5-3', 'warsh', 5, 3, 'يَٰٓأَيُّهَا ࡰ۬لذِينَ ءَامَنُواْ لَا تُحِلُّواْ شَعَٰٓئِرَ ࡰ۬للَّهِ وَلَا ࡰ۬لشَّهْرَ ࡰ۬لْحَرَامَ وَلَا ࡰ۬لْهَدْيَ وَلَا ࡰ۬لْقَلَٰٓئِدَ وَلَآ ءَآمِّينَ ࡰ۬لْبَيْتَ ࡰ۬لْحَرَامَ يَبْتَغُونَ فَضْلاࣰ مِّن رَّبِّهِمْ وَرِضْوَٰناࣰ࣌ وَإِذَا حَلَلْتُمْ فَاصْطَادُواْ࣌ وَلَا يَجْرِمَنَّكُمْ شَنَـَٔانُ قَوْمٍ ࡰن صَدُّوكُمْ عَنِ ࡴ۬لْمَسْجِدِ ࡴ۬لْحَرَامِ أَن تَعْتَدُواْ࣌ وَتَعَاوَنُواْ عَلَى ࡰ۬لْبِرِّ وَالتَّقْوٜىٰ࣌ وَلَا تَعَاوَنُواْ عَلَى ࡰ۬لِاثْمِ وَالْعُدْوَٰنِ࣌ وَاتَّقُواْ ࡲ۬للَّهَ࣌ إِنَّ ࡰ۬للَّهَ شَدِيدُ ࡲ۬لْعِقَابِ࣌', 'يأيها ࡰلذين ءامنوا لا تحلوا شعئر ࡰلله ولا ࡰلشهر ࡰلحرام ولا ࡰلهدي ولا ࡰلقلئد ولا ءامين ࡰلبيت ࡰلحرام يبتغون فضلا من ربهم ورضونا࣌ وإذا حللتم فاصطادوا࣌ ولا يجرمنكم شنان قوم ࡰن صدوكم عن ࡴلمسجد ࡴلحرام أن تعتدوا࣌ وتعاونوا على ࡰلبر والتقوى࣌ ولا تعاونوا على ࡰلاثم والعدون࣌ واتقوا ࡲلله࣌ إن ࡰلله شديد ࡲلعقاب࣌', NULL, 106, 'local:warsh-text.json'),
  ('warsh-5-4', 'warsh', 5, 4, '۞ حُرِّمَتْ عَلَيْكُمُ ࡲ۬لْمَيْتَةُ وَالدَّمُ وَلَحْمُ ࡲ۬لْخِنزِيرِ وَمَآ أُهِلَّ لِغَيْرِ ࡴ۬للَّهِ بِهِۦ وَالْمُنْخَنِقَةُ وَالْمَوْقُوذَةُ وَالْمُتَرَدِّيَةُ وَالنَّطِيحَةُ وَمَآ أَكَلَ ࡰ۬لسَّبُعُ إِلَّا مَا ذَكَّيْتُمْ وَمَا ذُبِحَ عَلَى ࡰ۬لنُّصُبِ وَأَن تَسْتَقْسِمُواْ بِالَازْلَٰمِ࣌ ذَٰلِكُمْ فِسْقٌ࣌ ࡴ۬لْيَوْمَ يَئِسَ ࡰ۬لذِينَ كَفَرُواْ مِن دِينِكُمْ࣌ فَلَا تَخْشَوْهُمْ وَاخْشَوْنِ࣌ ࡴ۬لْيَوْمَ أَكْمَلْتُ لَكُمْ دِينَكُمْ وَأَتْمَمْتُ عَلَيْكُمْ نِعْمَتِے وَرَضِيتُ لَكُمُ ࡲ۬لِاسْلَٰمَ دِيناࣰ࣌ فَمَنُ ࡲ࢈ضْطُرَّ فِے مَخْمَصَةٍ غَيْرَ مُتَجَانِفࣲ لِّإِثْمࣲ فَإِنَّ ࡰ۬للَّهَ غَفُورࣱ رَّحِيمࣱ࣌', 'حرمت عليكم ࡲلميتة والدم ولحم ࡲلخنزير وما أهل لغير ࡴلله به والمنخنقة والموقوذة والمتردية والنطيحة وما أكل ࡰلسبع إلا ما ذكيتم وما ذبح على ࡰلنصب وأن تستقسموا بالازلم࣌ ذلكم فسق࣌ ࡴليوم يئس ࡰلذين كفروا من دينكم࣌ فلا تخشوهم واخشون࣌ ࡴليوم أكملت لكم دينكم وأتممت عليكم نعمتے ورضيت لكم ࡲلاسلم دينا࣌ فمن ࡲ࢈ضطر فے مخمصة غير متجانف لإثم فإن ࡰلله غفور رحيم࣌', NULL, 107, 'local:warsh-text.json'),
  ('warsh-5-5', 'warsh', 5, 5, 'يَسْـَٔلُونَكَ مَاذَآ أُحِلَّ لَهُمْ࣌ قُلُ ࡳحِلَّ لَكُمُ ࡲ۬لطَّيِّبَٰتُ وَمَا عَلَّمْتُم مِّنَ ࡰ۬لْجَوَارِحِ مُكَلِّبِينَ تُعَلِّمُونَهُنَّ مِمَّا عَلَّمَكُمُ ࡲ۬للَّهُ࣌ فَكُلُواْ مِمَّآ أَمْسَكْنَ عَلَيْكُمْ وَاذْكُرُواْ ࡲٜسْمَ ࡰ۬للَّهِ عَلَيْهِ࣌ وَاتَّقُواْ ࡲ۬للَّهَ࣌ إِنَّ ࡰ۬للَّهَ سَرِيعُ ࡲ۬لْحِسَابِ࣌', 'يسلونك ماذا أحل لهم࣌ قل ࡳحل لكم ࡲلطيبت وما علمتم من ࡰلجوارح مكلبين تعلمونهن مما علمكم ࡲلله࣌ فكلوا مما أمسكن عليكم واذكروا ࡲسم ࡰلله عليه࣌ واتقوا ࡲلله࣌ إن ࡰلله سريع ࡲلحساب࣌', NULL, 107, 'local:warsh-text.json'),
  ('warsh-5-6', 'warsh', 5, 6, 'ࡴ۬لْيَوْمَ أُحِلَّ لَكُمُ ࡲ۬لطَّيِّبَٰتُ وَطَعَامُ ࡲ۬لذِينَ أُوتُواْ ࡲ۬لْكِتَٰبَ حِلࣱّ لَّكُمْ وَطَعَامُكُمْ حِلࣱّ لَّهُمْ وَالْمُحْصَنَٰتُ مِنَ ࡰ۬لْمُومِنَٰتِ وَالْمُحْصَنَٰتُ مِنَ ࡰ۬لذِينَ أُوتُواْ ࡲ۬لْكِتَٰبَ مِن قَبْلِكُمُۥٓ إِذَآ ءَاتَيْتُمُوهُنَّ أُجُورَهُنَّ مُحْصِنِينَ غَيْرَ مُسَٰفِحِينَ وَلَا مُتَّخِذِےٓ أَخْدَانࣲ࣌ وَمَنْ يَّكْفُرْ بِالِايمَٰنِ فَقَدْ حَبِطَ عَمَلُهُۥ وَهُوَ فِے ࡴ۬لَاخِرَةِ مِنَ ࡰ۬لْخَٰسِرِينَ࣌', 'ࡴليوم أحل لكم ࡲلطيبت وطعام ࡲلذين أوتوا ࡲلكتب حل لكم وطعامكم حل لهم والمحصنت من ࡰلمومنت والمحصنت من ࡰلذين أوتوا ࡲلكتب من قبلكم إذا ءاتيتموهن أجورهن محصنين غير مسفحين ولا متخذے أخدان࣌ ومن يكفر بالايمن فقد حبط عمله وهو فے ࡴلاخرة من ࡰلخسرين࣌', NULL, 107, 'local:warsh-text.json'),
  ('warsh-5-7', 'warsh', 5, 7, '۞ يَٰٓأَيُّهَا ࡰ۬لذِينَ ءَامَنُوٓاْ إِذَا قُمْتُمُۥٓ إِلَى ࡰ۬لصَّلَوٰةِ فَاغْسِلُواْ وُجُوهَكُمْ وَأَيْدِيَكُمُۥٓ إِلَى ࡰ۬لْمَرَافِقِ وَامْسَحُواْ بِرُءُوسِكُمْ࣌ وَأَرْجُلَكُمُۥٓ إِلَى ࡰ۬لْكَعْبَيْنِ࣌ وَإِن كُنتُمْ جُنُباࣰ فَاطَّهَّرُواْ࣌ وَإِن كُنتُم مَّرْضٜىٰٓ أَوْ عَلَىٰ سَفَرٍ ࡰوْ جَآءَ احَدࣱ مِّنكُم مِّنَ ࡰ۬لْغَآئِطِ أَوْ لَٰمَسْتُمُ ࡲ۬لنِّسَآءَ فَلَمْ تَجِدُواْ مَآءࣰ فَتَيَمَّمُواْ صَعِيداࣰ طَيِّباࣰ فَامْسَحُواْ بِوُجُوهِكُمْ وَأَيْدِيكُم مِّنْهُ࣌ مَا يُرِيدُ ࡲ۬للَّهُ لِيَجْعَلَ عَلَيْكُم مِّنْ حَرَجࣲ࣌ وَلَٰكِنْ يُّرِيدُ لِيُطَهِّرَكُمْ وَلِيُتِمَّ نِعْمَتَهُۥ عَلَيْكُمْ لَعَلَّكُمْ تَشْكُرُونَ࣌', 'يأيها ࡰلذين ءامنوا إذا قمتم إلى ࡰلصلوة فاغسلوا وجوهكم وأيديكم إلى ࡰلمرافق وامسحوا برءوسكم࣌ وأرجلكم إلى ࡰلكعبين࣌ وإن كنتم جنبا فاطهروا࣌ وإن كنتم مرضى أو على سفر ࡰو جاء احد منكم من ࡰلغائط أو لمستم ࡲلنساء فلم تجدوا ماء فتيمموا صعيدا طيبا فامسحوا بوجوهكم وأيديكم منه࣌ ما يريد ࡲلله ليجعل عليكم من حرج࣌ ولكن يريد ليطهركم وليتم نعمته عليكم لعلكم تشكرون࣌', NULL, 108, 'local:warsh-text.json'),
  ('warsh-5-8', 'warsh', 5, 8, 'وَاذْكُرُواْ نِعْمَةَ ࡰ۬للَّهِ عَلَيْكُمْ وَمِيثَٰقَهُ ࡲ۬لذِے وَاثَقَكُم بِهِۦٓ إِذْ قُلْتُمْ سَمِعْنَا وَأَطَعْنَا࣌ وَاتَّقُواْ ࡲ۬للَّهَ࣌ إِنَّ ࡰ۬للَّهَ عَلِيمُۢ بِذَاتِ ࡴ۬لصُّدُورِ࣌', 'واذكروا نعمة ࡰلله عليكم وميثقه ࡲلذے واثقكم به إذ قلتم سمعنا وأطعنا࣌ واتقوا ࡲلله࣌ إن ࡰلله عليم بذات ࡴلصدور࣌', NULL, 108, 'local:warsh-text.json'),
  ('warsh-5-9', 'warsh', 5, 9, 'يَٰٓأَيُّهَا ࡰ۬لذِينَ ءَامَنُواْ كُونُواْ قَوَّٰمِينَ لِلهِ شُهَدَآءَ بِالْقِسْطِ࣌ وَلَا يَجْرِمَنَّكُمْ شَنَـَٔانُ قَوْمٍ عَلَىٰٓ أَلَّا تَعْدِلُواْ࣌ ࡲٜعْدِلُواْ هُوَ أَقْرَبُ لِلتَّقْوٜىٰ࣌ وَاتَّقُواْ ࡲ۬للَّهَ࣌ إِنَّ ࡰ۬للَّهَ خَبِيرُۢ بِمَا تَعْمَلُونَ࣌', 'يأيها ࡰلذين ءامنوا كونوا قومين لله شهداء بالقسط࣌ ولا يجرمنكم شنان قوم على ألا تعدلوا࣌ ࡲعدلوا هو أقرب للتقوى࣌ واتقوا ࡲلله࣌ إن ࡰلله خبير بما تعملون࣌', NULL, 108, 'local:warsh-text.json'),
  ('warsh-5-10', 'warsh', 5, 10, 'وَعَدَ ࡰ۬للَّهُ ࡲ۬لذِينَ ءَامَنُواْ وَعَمِلُواْ ࡲ۬لصَّٰلِحَٰتِ لَهُم مَّغْفِرَةࣱ وَأَجْرٌ عَظِيمࣱ࣌', 'وعد ࡰلله ࡲلذين ءامنوا وعملوا ࡲلصلحت لهم مغفرة وأجر عظيم࣌', NULL, 108, 'local:warsh-text.json'),
  ('warsh-5-11', 'warsh', 5, 11, 'وَالذِينَ كَفَرُواْ وَكَذَّبُواْ بِـَٔايَٰتِنَآ أُوْلَٰٓئِكَ أَصْحَٰبُ ࡲ۬لْجَحِيمِ࣌', 'والذين كفروا وكذبوا بايتنا أولئك أصحب ࡲلجحيم࣌', NULL, 109, 'local:warsh-text.json'),
  ('warsh-5-12', 'warsh', 5, 12, 'يَٰٓأَيُّهَا ࡰ۬لذِينَ ءَامَنُواْ ࡲ࢈ذْكُرُواْ نِعْمَتَ ࡰ۬للَّهِ عَلَيْكُمُۥٓ إِذْ هَمَّ قَوْمٌ ࡰنْ يَّبْسُطُوٓاْ إِلَيْكُمُۥٓ أَيْدِيَهُمْ فَكَفَّ أَيْدِيَهُمْ عَنكُمْ࣌ وَاتَّقُواْ ࡲ۬للَّهَ࣌ وَعَلَى ࡰ۬للَّهِ فَلْيَتَوَكَّلِ ࡴ۬لْمُومِنُونَ࣌', 'يأيها ࡰلذين ءامنوا ࡲ࢈ذكروا نعمت ࡰلله عليكم إذ هم قوم ࡰن يبسطوا إليكم أيديهم فكف أيديهم عنكم࣌ واتقوا ࡲلله࣌ وعلى ࡰلله فليتوكل ࡴلمومنون࣌', NULL, 109, 'local:warsh-text.json'),
  ('warsh-5-13', 'warsh', 5, 13, '۞ وَلَقَدَ ࡰخَذَ ࡰ۬للَّهُ مِيثَٰقَ بَنِےٓ إِسْرَآءِيلَ وَبَعَثْنَا مِنْهُمُ ࡲٜثْنَےْ عَشَرَ نَقِيباࣰ࣌ وَقَالَ ࡰ۬للَّهُ إِنِّے مَعَكُمْ࣌ لَئِنَ ࡰقَمْتُمُ ࡲ۬لصَّلَوٰةَ وَءَاتَيْتُمُ ࡲ۬لزَّكَوٰةَ وَءَامَنتُم بِرُسُلِے وَعَزَّرْتُمُوهُمْ وَأَقْرَضْتُمُ ࡲ۬للَّهَ قَرْضاً حَسَناࣰ لَّأُكَفِّرَنَّ عَنكُمْ سَيِّـَٔاتِكُمْ وَلَأُدْخِلَنَّكُمْ جَنَّٰتࣲ تَجْرِے مِن تَحْتِهَا ࡰ۬لَانْهَٰرُ࣌ فَمَن كَفَرَ بَعْدَ ذَٰلِكَ مِنكُمْ فَقَد ضَّلَّ سَوَآءَ ࡰ۬لسَّبِيلِ࣌', 'ولقد ࡰخذ ࡰلله ميثق بنے إسراءيل وبعثنا منهم ࡲثنے عشر نقيبا࣌ وقال ࡰلله إنے معكم࣌ لئن ࡰقمتم ࡲلصلوة وءاتيتم ࡲلزكوة وءامنتم برسلے وعزرتموهم وأقرضتم ࡲلله قرضا حسنا لأكفرن عنكم سياتكم ولأدخلنكم جنت تجرے من تحتها ࡰلانهر࣌ فمن كفر بعد ذلك منكم فقد ضل سواء ࡰلسبيل࣌', NULL, 109, 'local:warsh-text.json'),
  ('warsh-5-14', 'warsh', 5, 14, 'فَبِمَا نَقْضِهِم مِّيثَٰقَهُمْ لَعَنَّٰهُمْ وَجَعَلْنَا قُلُوبَهُمْ قَٰسِيَةࣰ يُحَرِّفُونَ ࡰ۬لْكَلِمَ عَن مَّوَاضِعِهِۦ وَنَسُواْ حَظّاࣰ مِّمَّا ذُكِّرُواْ بِهِۦ࣌ وَلَا تَزَالُ تَطَّلِعُ عَلَىٰ خَآئِنَةࣲ مِّنْهُمُۥٓ إِلَّا قَلِيلاࣰ مِّنْهُمْ࣌ فَاعْفُ عَنْهُمْ وَاصْفَحِ࣌ ࡴنَّ ࡰ۬للَّهَ يُحِبُّ ࡲ۬لْمُحْسِنِينَ࣌', 'فبما نقضهم ميثقهم لعنهم وجعلنا قلوبهم قسية يحرفون ࡰلكلم عن مواضعه ونسوا حظا مما ذكروا به࣌ ولا تزال تطلع على خائنة منهم إلا قليلا منهم࣌ فاعف عنهم واصفح࣌ ࡴن ࡰلله يحب ࡲلمحسنين࣌', NULL, 109, 'local:warsh-text.json'),
  ('warsh-5-15', 'warsh', 5, 15, 'وَمِنَ ࡰ۬لذِينَ قَالُوٓاْ إِنَّا نَصَٰرٜىٰٓ أَخَذْنَا مِيثَٰقَهُمْ فَنَسُواْ حَظّاࣰ مِّمَّا ذُكِّرُواْ بِهِۦ فَأَغْرَيْنَا بَيْنَهُمُ ࡲ۬لْعَدَٰوَةَ وَالْبَغْضَآءَ ࡹلَىٰ يَوْمِ ࡴ۬لْقِيَٰمَةِ࣌ وَسَوْفَ يُنَبِّئُهُمُ ࡲ۬للَّهُ بِمَا كَانُواْ يَصْنَعُونَ࣌', 'ومن ࡰلذين قالوا إنا نصرى أخذنا ميثقهم فنسوا حظا مما ذكروا به فأغرينا بينهم ࡲلعدوة والبغضاء ࡹلى يوم ࡴلقيمة࣌ وسوف ينبئهم ࡲلله بما كانوا يصنعون࣌', NULL, 110, 'local:warsh-text.json'),
  ('warsh-5-16', 'warsh', 5, 16, 'يَٰٓأَهْلَ ࡰ۬لْكِتَٰبِ قَدْ جَآءَكُمْ رَسُولُنَا يُبَيِّنُ لَكُمْ كَثِيراࣰ مِّمَّا كُنتُمْ تُخْفُونَ مِنَ ࡰ۬لْكِتَٰبِ وَيَعْفُواْ عَن كَثِيرࣲ࣌', 'يأهل ࡰلكتب قد جاءكم رسولنا يبين لكم كثيرا مما كنتم تخفون من ࡰلكتب ويعفوا عن كثير࣌', NULL, 110, 'local:warsh-text.json'),
  ('warsh-5-17', 'warsh', 5, 17, 'قَدْ جَآءَكُم مِّنَ ࡰ۬للَّهِ نُورࣱ وَكِتَٰبࣱ مُّبِينࣱ', 'قد جاءكم من ࡰلله نور وكتب مبين', NULL, 110, 'local:warsh-text.json'),
  ('warsh-5-18', 'warsh', 5, 18, 'يَهْدِے بِهِ ࡴ۬للَّهُ مَنِ ࡴٜتَّبَعَ رِضْوَٰنَهُۥ سُبُلَ ࡰ۬لسَّلَٰمِ࣌ وَيُخْرِجُهُم مِّنَ ࡰ۬لظُّلُمَٰتِ إِلَى ࡰ۬لنُّورِ بِإِذْنِهِۦ࣌ وَيَهْدِيهِمُۥٓ إِلَىٰ صِرَٰطࣲ مُّسْتَقِيمࣲ࣌', 'يهدے به ࡴلله من ࡴتبع رضونه سبل ࡰلسلم࣌ ويخرجهم من ࡰلظلمت إلى ࡰلنور بإذنه࣌ ويهديهم إلى صرط مستقيم࣌', NULL, 110, 'local:warsh-text.json'),
  ('warsh-5-19', 'warsh', 5, 19, '۞ لَّقَدْ كَفَرَ ࡰ۬لذِينَ قَالُوٓاْ إِنَّ ࡰ۬للَّهَ هُوَ ࡰ۬لْمَسِيحُ ࡲٜبْنُ مَرْيَمَ࣌ قُلْ فَمَنْ يَّمْلِكُ مِنَ ࡰ۬للَّهِ شَيْـٔاً ࡴنَ ࡰرَادَ أَنْ يُّهْلِكَ ࡰ۬لْمَسِيحَ ࡰٜبْنَ مَرْيَمَ وَأُمَّهُۥ وَمَن فِے ࡴ۬لَارْضِ جَمِيعاࣰ࣌ وَلِلهِ مُلْكُ ࡲ۬لسَّمَٰوَٰتِ وَالَارْضِ وَمَا بَيْنَهُمَا࣌ يَخْلُقُ مَا يَشَآءُ࣌ وَاللَّهُ عَلَىٰ كُلِّ شَےْءࣲ قَدِيرࣱ࣌', 'لقد كفر ࡰلذين قالوا إن ࡰلله هو ࡰلمسيح ࡲبن مريم࣌ قل فمن يملك من ࡰلله شيا ࡴن ࡰراد أن يهلك ࡰلمسيح ࡰبن مريم وأمه ومن فے ࡴلارض جميعا࣌ ولله ملك ࡲلسموت والارض وما بينهما࣌ يخلق ما يشاء࣌ والله على كل شےء قدير࣌', NULL, 110, 'local:warsh-text.json'),
  ('warsh-5-20', 'warsh', 5, 20, 'وَقَالَتِ ࡴ۬لْيَهُودُ وَالنَّصَٰرٜىٰ نَحْنُ أَبْنَٰٓؤُاْ ࡲ۬للَّهِ وَأَحِبَّٰٓؤُهُۥ࣌ قُلْ فَلِمَ يُعَذِّبُكُم بِذُنُوبِكُم࣌ بَلَ ࡰنتُم بَشَرࣱ مِّمَّنْ خَلَقَ࣌ يَغْفِرُ لِمَنْ يَّشَآءُ وَيُعَذِّبُ مَنْ يَّشَآءُ࣌ وَلِلهِ مُلْكُ ࡲ۬لسَّمَٰوَٰتِ وَالَارْضِ وَمَا بَيْنَهُمَا࣌ وَإِلَيْهِ ࡴ۬لْمَصِيرُ࣌', 'وقالت ࡴليهود والنصرى نحن أبنؤا ࡲلله وأحبؤه࣌ قل فلم يعذبكم بذنوبكم࣌ بل ࡰنتم بشر ممن خلق࣌ يغفر لمن يشاء ويعذب من يشاء࣌ ولله ملك ࡲلسموت والارض وما بينهما࣌ وإليه ࡴلمصير࣌', NULL, 111, 'local:warsh-text.json'),
  ('warsh-5-21', 'warsh', 5, 21, 'يَٰٓأَهْلَ ࡰ۬لْكِتَٰبِ قَدْ جَآءَكُمْ رَسُولُنَا يُبَيِّنُ لَكُمْ عَلَىٰ فَتْرَةࣲ مِّنَ ࡰ۬لرُّسُلِ أَن تَقُولُواْ مَا جَآءَنَا مِنۢ بَشِيرࣲ وَلَا نَذِيرࣲ فَقَدْ جَآءَكُم بَشِيرࣱ وَنَذِيرࣱ࣌ وَاللَّهُ عَلَىٰ كُلِّ شَےْءࣲ قَدِيرࣱ࣌', 'يأهل ࡰلكتب قد جاءكم رسولنا يبين لكم على فترة من ࡰلرسل أن تقولوا ما جاءنا من بشير ولا نذير فقد جاءكم بشير ونذير࣌ والله على كل شےء قدير࣌', NULL, 111, 'local:warsh-text.json'),
  ('warsh-5-22', 'warsh', 5, 22, 'وَإِذْ قَالَ مُوسٜىٰ لِقَوْمِهِۦ يَٰقَوْمِ ࡴ࢈ذْكُرُواْ نِعْمَةَ ࡰ۬للَّهِ عَلَيْكُمُۥٓ إِذْ جَعَلَ فِيكُمُۥٓ أَنۢبِئَآءَ وَجَعَلَكُم مُّلُوكاࣰ࣌ وَءَاتٜيٰكُم مَّا لَمْ يُوتِ أَحَداࣰ مِّنَ ࡰ۬لْعَٰلَمِينَ࣌', 'وإذ قال موسى لقومه يقوم ࡴ࢈ذكروا نعمة ࡰلله عليكم إذ جعل فيكم أنبئاء وجعلكم ملوكا࣌ وءاتيكم ما لم يوت أحدا من ࡰلعلمين࣌', NULL, 111, 'local:warsh-text.json'),
  ('warsh-5-23', 'warsh', 5, 23, 'يَٰقَوْمِ ࡴ࢈دْخُلُواْ ࡲ۬لَارْضَ ࡰ۬لْمُقَدَّسَةَ ࡰ۬لتِے كَتَبَ ࡰ۬للَّهُ لَكُمْ࣌ وَلَا تَرْتَدُّواْ عَلَىٰٓ أَدْبٜـٰرِكُمْ فَتَنقَلِبُواْ خَٰسِرِينَ࣌', 'يقوم ࡴ࢈دخلوا ࡲلارض ࡰلمقدسة ࡰلتے كتب ࡰلله لكم࣌ ولا ترتدوا على أدبركم فتنقلبوا خسرين࣌', NULL, 111, 'local:warsh-text.json'),
  ('warsh-5-24', 'warsh', 5, 24, 'قَالُواْ يَٰمُوسٜىٰٓ إِنَّ فِيهَا قَوْماࣰ جَبّٜارِينَ࣌ وَإِنَّا لَن نَّدْخُلَهَا حَتَّىٰ يَخْرُجُواْ مِنْهَا࣌ فَإِنْ يَّخْرُجُواْ مِنْهَا فَإِنَّا دَٰخِلُونَ࣌', 'قالوا يموسى إن فيها قوما جبارين࣌ وإنا لن ندخلها حتى يخرجوا منها࣌ فإن يخرجوا منها فإنا دخلون࣌', NULL, 111, 'local:warsh-text.json'),
  ('warsh-5-25', 'warsh', 5, 25, '۞ قَالَ رَجُلَٰنِ مِنَ ࡰ۬لذِينَ يَخَافُونَ أَنْعَمَ ࡰ۬للَّهُ عَلَيْهِمَا ࡸَدْخُلُواْ عَلَيْهِمُ ࡲ۬لْبَابَ࣌ فَإِذَا دَخَلْتُمُوهُ فَإِنَّكُمْ غَٰلِبُونَ࣌ وَعَلَى ࡰ۬للَّهِ فَتَوَكَّلُوٓاْ إِن كُنتُم مُّومِنِينَ࣌', 'قال رجلن من ࡰلذين يخافون أنعم ࡰلله عليهما ࡸدخلوا عليهم ࡲلباب࣌ فإذا دخلتموه فإنكم غلبون࣌ وعلى ࡰلله فتوكلوا إن كنتم مومنين࣌', NULL, 111, 'local:warsh-text.json'),
  ('warsh-5-26', 'warsh', 5, 26, 'قَالُواْ يَٰمُوسٜىٰٓ إِنَّا لَن نَّدْخُلَهَآ أَبَداࣰ مَّا دَامُواْ فِيهَا فَاذْهَبَ ࡰنتَ وَرَبُّكَ فَقَٰتِلَآ إِنَّا هَٰهُنَا قَٰعِدُونَ࣌', 'قالوا يموسى إنا لن ندخلها أبدا ما داموا فيها فاذهب ࡰنت وربك فقتلا إنا ههنا قعدون࣌', NULL, 112, 'local:warsh-text.json'),
  ('warsh-5-27', 'warsh', 5, 27, 'قَالَ رَبِّ إِنِّے لَآ أَمْلِكُ إِلَّا نَفْسِے࣌ وَأَخِے࣌ فَافْرُقْ بَيْنَنَا وَبَيْنَ ࡰ۬لْقَوْمِ ࡴ۬لْفَٰسِقِينَ࣌', 'قال رب إنے لا أملك إلا نفسے࣌ وأخے࣌ فافرق بيننا وبين ࡰلقوم ࡴلفسقين࣌', NULL, 112, 'local:warsh-text.json'),
  ('warsh-5-28', 'warsh', 5, 28, 'قَالَ فَإِنَّهَا مُحَرَّمَةٌ عَلَيْهِمُۥٓ࣌ أَرْبَعِينَ سَنَةࣰ يَتِيهُونَ فِے ࡴ۬لَارْضِ࣌ فَلَا تَاسَ عَلَى ࡰ۬لْقَوْمِ ࡴ۬لْفَٰسِقِينَ࣌', 'قال فإنها محرمة عليهم࣌ أربعين سنة يتيهون فے ࡴلارض࣌ فلا تاس على ࡰلقوم ࡴلفسقين࣌', NULL, 112, 'local:warsh-text.json'),
  ('warsh-5-29', 'warsh', 5, 29, 'وَاتْلُ عَلَيْهِمْ نَبَأَ ࡰٜبْنَيَ اٰدَمَ بِالْحَقِّ إِذْ قَرَّبَا قُرْبَاناࣰ فَتُقُبِّلَ مِنَ ࡰحَدِهِمَا وَلَمْ يُتَقَبَّلْ مِنَ ࡰ۬لَاخَرِ࣌ قَالَ لَأَقْتُلَنَّكَ࣌ قَالَ إِنَّمَا يَتَقَبَّلُ ࡲ۬للَّهُ مِنَ ࡰ۬لْمُتَّقِينَ࣌', 'واتل عليهم نبأ ࡰبني ادم بالحق إذ قربا قربانا فتقبل من ࡰحدهما ولم يتقبل من ࡰلاخر࣌ قال لأقتلنك࣌ قال إنما يتقبل ࡲلله من ࡰلمتقين࣌', NULL, 112, 'local:warsh-text.json'),
  ('warsh-5-30', 'warsh', 5, 30, 'لَئِنۢ بَسَطْتَّ إِلَيَّ يَدَكَ لِتَقْتُلَنِے مَآ أَنَا بِبَاسِطࣲ يَدِيَ إِلَيْكَ لِأَقْتُلَكَ࣌ إِنِّيَ أَخَافُ ࡲ۬للَّهَ رَبَّ ࡰ۬لْعَٰلَمِينَ࣌', 'لئن بسطت إلي يدك لتقتلنے ما أنا بباسط يدي إليك لأقتلك࣌ إني أخاف ࡲلله رب ࡰلعلمين࣌', NULL, 112, 'local:warsh-text.json'),
  ('warsh-5-31', 'warsh', 5, 31, 'إِنِّيَ أُرِيدُ أَن تَبُوٓأَ بِإِثْمِے وَإِثْمِكَ فَتَكُونَ مِنَ ࡰصْحَٰبِ ࡴ۬لنّٜارِ࣌ وَذَٰلِكَ جَزَٰٓؤُاْ ࡲ۬لظَّٰلِمِينَ࣌', 'إني أريد أن تبوأ بإثمے وإثمك فتكون من ࡰصحب ࡴلنار࣌ وذلك جزؤا ࡲلظلمين࣌', NULL, 112, 'local:warsh-text.json'),
  ('warsh-5-32', 'warsh', 5, 32, 'فَطَوَّعَتْ لَهُۥ نَفْسُهُۥ قَتْلَ أَخِيهِ فَقَتَلَهُۥ فَأَصْبَحَ مِنَ ࡰ۬لْخَٰسِرِينَ࣌', 'فطوعت له نفسه قتل أخيه فقتله فأصبح من ࡰلخسرين࣌', NULL, 112, 'local:warsh-text.json'),
  ('warsh-5-33', 'warsh', 5, 33, 'فَبَعَثَ ࡰ۬للَّهُ غُرَاباࣰ يَبْحَثُ فِے ࡴ۬لَارْضِ لِيُرِيَهُۥ كَيْفَ يُوَٰرِے سَوْءَةَ أَخِيهِ࣌ قَالَ يَٰوَيْلَتٜىٰٓ أَعَجَزْتُ أَنَ ࡰكُونَ مِثْلَ هَٰذَا ࡰ۬لْغُرَابِ فَأُوَٰرِيَ سَوْءَةَ أَخِے فَأَصْبَحَ مِنَ ࡰ۬لنَّٰدِمِينَ', 'فبعث ࡰلله غرابا يبحث فے ࡴلارض ليريه كيف يورے سوءة أخيه࣌ قال يويلتى أعجزت أن ࡰكون مثل هذا ࡰلغراب فأوري سوءة أخے فأصبح من ࡰلندمين', NULL, 112, 'local:warsh-text.json'),
  ('warsh-5-34', 'warsh', 5, 34, 'مِنَ ࡰجْلِ ذَٰلِكَ࣌ كَتَبْنَا عَلَىٰ بَنِےٓ إِسْرَآءِيلَ أَنَّهُۥ مَن قَتَلَ نَفْساَۢ بِغَيْرِ نَفْسٍ ࡰوْ فَسَادࣲ فِے ࡴ۬لَارْضِ فَكَأَنَّمَا قَتَلَ ࡰ۬لنَّاسَ جَمِيعاࣰ࣌ وَمَنَ ࡰحْيٜاهَا فَكَأَنَّمَآ أَحْيَا ࡰ۬لنَّاسَ جَمِيعاࣰ࣌ ۞ وَلَقَدْ جَآءَتْهُمْ رُسُلُنَا بِالْبَيِّنَٰتِ ثُمَّ إِنَّ كَثِيراࣰ مِّنْهُم بَعْدَ ذَٰلِكَ فِے ࡴ۬لَارْضِ لَمُسْرِفُونَ࣌', 'من ࡰجل ذلك࣌ كتبنا على بنے إسراءيل أنه من قتل نفسا بغير نفس ࡰو فساد فے ࡴلارض فكأنما قتل ࡰلناس جميعا࣌ ومن ࡰحياها فكأنما أحيا ࡰلناس جميعا࣌  ولقد جاءتهم رسلنا بالبينت ثم إن كثيرا منهم بعد ذلك فے ࡴلارض لمسرفون࣌', NULL, 113, 'local:warsh-text.json'),
  ('warsh-5-35', 'warsh', 5, 35, 'إِنَّمَا جَزَٰٓؤُاْ ࡲ۬لذِينَ يُحَارِبُونَ ࡰ۬للَّهَ وَرَسُولَهُۥ وَيَسْعَوْنَ فِے ࡴ۬لَارْضِ فَسَاداً ࡰنْ يُّقَتَّلُوٓاْ أَوْ يُصَلَّبُوٓاْ أَوْ تُقَطَّعَ أَيْدِيهِمْ وَأَرْجُلُهُم مِّنْ خِلَٰفٍ ࡰوْ يُنفَوْاْ مِنَ ࡰ۬لَارْضِ࣌ ذَٰلِكَ لَهُمْ خِزْيࣱ فِے ࡴ۬لدُّنْيٜا࣌ وَلَهُمْ فِے ࡴ۬لَاخِرَةِ عَذَابٌ عَظِيمٌ', 'إنما جزؤا ࡲلذين يحاربون ࡰلله ورسوله ويسعون فے ࡴلارض فسادا ࡰن يقتلوا أو يصلبوا أو تقطع أيديهم وأرجلهم من خلف ࡰو ينفوا من ࡰلارض࣌ ذلك لهم خزي فے ࡴلدنيا࣌ ولهم فے ࡴلاخرة عذاب عظيم', NULL, 113, 'local:warsh-text.json'),
  ('warsh-5-36', 'warsh', 5, 36, 'ࡴلَّا ࡰ۬لذِينَ تَابُواْ مِن قَبْلِ أَن تَقْدِرُواْ عَلَيْهِمْ فَاعْلَمُوٓاْ أَنَّ ࡰ۬للَّهَ غَفُورࣱ رَّحِيمࣱ࣌', 'ࡴلا ࡰلذين تابوا من قبل أن تقدروا عليهم فاعلموا أن ࡰلله غفور رحيم࣌', NULL, 113, 'local:warsh-text.json'),
  ('warsh-5-37', 'warsh', 5, 37, 'يَٰٓأَيُّهَا ࡰ۬لذِينَ ءَامَنُواْ ࡲٜتَّقُواْ ࡲ۬للَّهَ وَابْتَغُوٓاْ إِلَيْهِ ࡴ۬لْوَسِيلَةَ وَجَٰهِدُواْ فِے سَبِيلِهِۦ لَعَلَّكُمْ تُفْلِحُونَ࣌', 'يأيها ࡰلذين ءامنوا ࡲتقوا ࡲلله وابتغوا إليه ࡴلوسيلة وجهدوا فے سبيله لعلكم تفلحون࣌', NULL, 113, 'local:warsh-text.json'),
  ('warsh-5-38', 'warsh', 5, 38, 'إِنَّ ࡰ۬لذِينَ كَفَرُواْ لَوَ ࡰنَّ لَهُم مَّا فِے ࡴ۬لَارْضِ جَمِيعاࣰ وَمِثْلَهُۥ مَعَهُۥ لِيَفْتَدُواْ بِهِۦ مِنْ عَذَابِ يَوْمِ ࡴ۬لْقِيَٰمَةِ مَا تُقُبِّلَ مِنْهُمْ࣌ وَلَهُمْ عَذَابٌ ࡰلِيمࣱ࣌', 'إن ࡰلذين كفروا لو ࡰن لهم ما فے ࡴلارض جميعا ومثله معه ليفتدوا به من عذاب يوم ࡴلقيمة ما تقبل منهم࣌ ولهم عذاب ࡰليم࣌', NULL, 113, 'local:warsh-text.json'),
  ('warsh-5-39', 'warsh', 5, 39, 'يُرِيدُونَ أَنْ يَّخْرُجُواْ مِنَ ࡰ۬لنّٜارِ وَمَا هُم بِخَٰرِجِينَ مِنْهَا࣌ وَلَهُمْ عَذَابࣱ مُّقِيمࣱ࣌', 'يريدون أن يخرجوا من ࡰلنار وما هم بخرجين منها࣌ ولهم عذاب مقيم࣌', NULL, 114, 'local:warsh-text.json'),
  ('warsh-5-40', 'warsh', 5, 40, 'وَالسَّارِقُ وَالسَّارِقَةُ فَاقْطَعُوٓاْ أَيْدِيَهُمَا جَزَآءَۢ بِمَا كَسَبَا نَكَٰلاࣰ مِّنَ ࡰ۬للَّهِ࣌ وَاللَّهُ عَزِيزٌ حَكِيمࣱ࣌', 'والسارق والسارقة فاقطعوا أيديهما جزاء بما كسبا نكلا من ࡰلله࣌ والله عزيز حكيم࣌', NULL, 114, 'local:warsh-text.json'),
  ('warsh-5-41', 'warsh', 5, 41, 'فَمَن تَابَ مِنۢ بَعْدِ ظُلْمِهِۦ وَأَصْلَحَ فَإِنَّ ࡰ۬للَّهَ يَتُوبُ عَلَيْهِ࣌ إِنَّ ࡰ۬للَّهَ غَفُورࣱ رَّحِيمٌ࣌', 'فمن تاب من بعد ظلمه وأصلح فإن ࡰلله يتوب عليه࣌ إن ࡰلله غفور رحيم࣌', NULL, 114, 'local:warsh-text.json'),
  ('warsh-5-42', 'warsh', 5, 42, 'ࡰلَمْ تَعْلَمَ ࡰنَّ ࡰ۬للَّهَ لَهُۥ مُلْكُ ࡲ۬لسَّمَٰوَٰتِ وَالَارْضِ࣌ يُعَذِّبُ مَنْ يَّشَآءُ وَيَغْفِرُ لِمَنْ يَّشَآءُ࣌ وَاللَّهُ عَلَىٰ كُلِّ شَےْءࣲ قَدِيرࣱ࣌', 'ࡰلم تعلم ࡰن ࡰلله له ملك ࡲلسموت والارض࣌ يعذب من يشاء ويغفر لمن يشاء࣌ والله على كل شےء قدير࣌', NULL, 114, 'local:warsh-text.json'),
  ('warsh-5-43', 'warsh', 5, 43, '۞ يَٰٓأَيُّهَا ࡰ۬لرَّسُولُ لَا يُحْزِنكَ ࡰ۬لذِينَ يُسَٰرِعُونَ فِے ࡴ۬لْكُفْرِ مِنَ ࡰ۬لذِينَ قَالُوٓاْ ءَامَنَّا بِأَفْوَٰهِهِمْ وَلَمْ تُومِن قُلُوبُهُمْ࣌ وَمِنَ ࡰ۬لذِينَ هَادُواْ سَمَّٰعُونَ لِلْكَذِبِ سَمَّٰعُونَ لِقَوْمٍ اٰخَرِينَ لَمْ يَاتُوكَ࣌ يُحَرِّفُونَ ࡰ۬لْكَلِمَ مِنۢ بَعْدِ مَوَاضِعِهِۦ يَقُولُونَ إِنُ ࡳوتِيتُمْ هَٰذَا فَخُذُوهُ وَإِن لَّمْ تُوتَوْهُ فَاحْذَرُواْ࣌ وَمَنْ يُّرِدِ ࡴ۬للَّهُ فِتْنَتَهُۥ فَلَن تَمْلِكَ لَهُۥ مِنَ ࡰ۬للَّهِ شَيْـٔاً࣌ ࡳوْلَٰٓئِكَ ࡰ۬لذِينَ لَمْ يُرِدِ ࡴ۬للَّهُ أَنْ يُّطَهِّرَ قُلُوبَهُمْ࣌ لَهُمْ فِے ࡴ۬لدُّنْيٜا خِزْيࣱ࣌ وَلَهُمْ فِے ࡴ۬لَاخِرَةِ عَذَابٌ عَظِيمࣱ࣌', 'يأيها ࡰلرسول لا يحزنك ࡰلذين يسرعون فے ࡴلكفر من ࡰلذين قالوا ءامنا بأفوههم ولم تومن قلوبهم࣌ ومن ࡰلذين هادوا سمعون للكذب سمعون لقوم اخرين لم ياتوك࣌ يحرفون ࡰلكلم من بعد مواضعه يقولون إن ࡳوتيتم هذا فخذوه وإن لم توتوه فاحذروا࣌ ومن يرد ࡴلله فتنته فلن تملك له من ࡰلله شيا࣌ ࡳولئك ࡰلذين لم يرد ࡴلله أن يطهر قلوبهم࣌ لهم فے ࡴلدنيا خزي࣌ ولهم فے ࡴلاخرة عذاب عظيم࣌', NULL, 114, 'local:warsh-text.json'),
  ('warsh-5-44', 'warsh', 5, 44, 'سَمَّٰعُونَ لِلْكَذِبِ أَكَّٰلُونَ لِلسُّحْتِ࣌ فَإِن جَآءُوكَ فَاحْكُم بَيْنَهُمُۥٓ أَوَ ࡰعْرِضْ عَنْهُمْ࣌ وَإِن تُعْرِضْ عَنْهُمْ فَلَنْ يَّضُرُّوكَ شَيْـٔاࣰ࣌ وَإِنْ حَكَمْتَ فَاحْكُم بَيْنَهُم بِالْقِسْطِ࣌ إِنَّ ࡰ۬للَّهَ يُحِبُّ ࡲ۬لْمُقْسِطِينَ࣌', 'سمعون للكذب أكلون للسحت࣌ فإن جاءوك فاحكم بينهم أو ࡰعرض عنهم࣌ وإن تعرض عنهم فلن يضروك شيا࣌ وإن حكمت فاحكم بينهم بالقسط࣌ إن ࡰلله يحب ࡲلمقسطين࣌', NULL, 115, 'local:warsh-text.json'),
  ('warsh-5-45', 'warsh', 5, 45, 'وَكَيْفَ يُحَكِّمُونَكَ وَعِندَهُمُ ࡲ۬لتَّوْرٜيٰةُ فِيهَا حُكْمُ ࡲ۬للَّهِ ثُمَّ يَتَوَلَّوْنَ مِنۢ بَعْدِ ذَٰلِكَ࣌ وَمَآ أُوْلَٰٓئِكَ بِالْمُومِنِينَ࣌', 'وكيف يحكمونك وعندهم ࡲلتورية فيها حكم ࡲلله ثم يتولون من بعد ذلك࣌ وما أولئك بالمومنين࣌', NULL, 115, 'local:warsh-text.json'),
  ('warsh-5-46', 'warsh', 5, 46, 'إِنَّآ أَنزَلْنَا ࡰ۬لتَّوْرٜيٰةَ فِيهَا هُدىࣰ وَنُورࣱ يَحْكُمُ بِهَا ࡰ۬لنَّبِيٓـُٔونَ ࡰ۬لذِينَ أَسْلَمُواْ لِلذِينَ هَادُواْ وَالرَّبَّٰنِيُّونَ وَالَاحْبَارُ بِمَا ࡸَسْتُحْفِظُواْ مِن كِتَٰبِ ࡴ۬للَّهِ وَكَانُواْ عَلَيْهِ شُهَدَآءَ࣌ فَلَا تَخْشَوُاْ ࡲ۬لنَّاسَ وَاخْشَوْنِ࣌ وَلَا تَشْتَرُواْ بِـَٔايَٰتِے ثَمَناࣰ قَلِيلاࣰ࣌ وَمَن لَّمْ يَحْكُم بِمَآ أَنزَلَ ࡰ۬للَّهُ فَأُوْلَٰٓئِكَ هُمُ ࡲ۬لْكَٰفِرُونَ࣌', 'إنا أنزلنا ࡰلتورية فيها هدى ونور يحكم بها ࡰلنبيون ࡰلذين أسلموا للذين هادوا والربنيون والاحبار بما ࡸستحفظوا من كتب ࡴلله وكانوا عليه شهداء࣌ فلا تخشوا ࡲلناس واخشون࣌ ولا تشتروا بايتے ثمنا قليلا࣌ ومن لم يحكم بما أنزل ࡰلله فأولئك هم ࡲلكفرون࣌', NULL, 115, 'local:warsh-text.json'),
  ('warsh-5-47', 'warsh', 5, 47, '۞ وَكَتَبْنَا عَلَيْهِمْ فِيهَآ أَنَّ ࡰ۬لنَّفْسَ بِالنَّفْسِ وَالْعَيْنَ بِالْعَيْنِ وَالَانفَ بِالَانفِ وَالُاذْنَ بِالُاذْنِ وَالسِّنَّ بِالسِّنِّ وَالْجُرُوحَ قِصَاصࣱ࣌ فَمَن تَصَدَّقَ بِهِۦ فَهُوَ كَفَّارَةࣱ لَّهُۥ࣌ وَمَن لَّمْ يَحْكُم بِمَآ أَنزَلَ ࡰ۬للَّهُ فَأُوْلَٰٓئِكَ هُمُ ࡲ۬لظَّٰلِمُونَ࣌', 'وكتبنا عليهم فيها أن ࡰلنفس بالنفس والعين بالعين والانف بالانف والاذن بالاذن والسن بالسن والجروح قصاص࣌ فمن تصدق به فهو كفارة له࣌ ومن لم يحكم بما أنزل ࡰلله فأولئك هم ࡲلظلمون࣌', NULL, 115, 'local:warsh-text.json'),
  ('warsh-5-48', 'warsh', 5, 48, 'وَقَفَّيْنَا عَلَىٰٓ ءَاثٜـٰرِهِم بِعِيسَى ࡰٜبْنِ مَرْيَمَ مُصَدِّقاࣰ لِّمَا بَيْنَ يَدَيْهِ مِنَ ࡰ۬لتَّوْرٜيٰةِ࣌ وَءَاتَيْنَٰهُ ࡲ۬لِانجِيلَ فِيهِ هُدىࣰ وَنُورࣱ وَمُصَدِّقاࣰ لِّمَا بَيْنَ يَدَيْهِ مِنَ ࡰ۬لتَّوْرٜيٰةِ وَهُدىࣰ وَمَوْعِظَةࣰ لِّلْمُتَّقِينَ࣌', 'وقفينا على ءاثرهم بعيسى ࡰبن مريم مصدقا لما بين يديه من ࡰلتورية࣌ وءاتينه ࡲلانجيل فيه هدى ونور ومصدقا لما بين يديه من ࡰلتورية وهدى وموعظة للمتقين࣌', NULL, 116, 'local:warsh-text.json'),
  ('warsh-5-49', 'warsh', 5, 49, 'وَلْيَحْكُمَ ࡰهْلُ ࡲ۬لِانجِيلِ بِمَآ أَنزَلَ ࡰ۬للَّهُ فِيهِ࣌ وَمَن لَّمْ يَحْكُم بِمَآ أَنزَلَ ࡰ۬للَّهُ فَأُوْلَٰٓئِكَ هُمُ ࡲ۬لْفَٰسِقُونَ࣌', 'وليحكم ࡰهل ࡲلانجيل بما أنزل ࡰلله فيه࣌ ومن لم يحكم بما أنزل ࡰلله فأولئك هم ࡲلفسقون࣌', NULL, 116, 'local:warsh-text.json'),
  ('warsh-5-50', 'warsh', 5, 50, 'وَأَنزَلْنَآ إِلَيْكَ ࡰ۬لْكِتَٰبَ بِالْحَقِّ مُصَدِّقاࣰ لِّمَا بَيْنَ يَدَيْهِ مِنَ ࡰ۬لْكِتَٰبِ وَمُهَيْمِناً عَلَيْهِ࣌ فَاحْكُم بَيْنَهُم بِمَآ أَنزَلَ ࡰ۬للَّهُ وَلَا تَتَّبِعَ ࡰهْوَآءَهُمْ عَمَّا جَآءَكَ مِنَ ࡰ۬لْحَقِّ࣌ لِكُلࣲّ جَعَلْنَا مِنكُمْ شِرْعَةࣰ وَمِنْهَاجاࣰ࣌ وَلَوْ شَآءَ ࡰ۬للَّهُ لَجَعَلَكُمُۥٓ أُمَّةࣰ وَٰحِدَةࣰ࣌ وَلَٰكِن لِّيَبْلُوَكُمْ فِے مَآ ءَاتٜيٰكُمْ࣌ فَاسْتَبِقُواْ ࡲ۬لْخَيْرَٰتِ࣌ إِلَى ࡰ۬للَّهِ مَرْجِعُكُمْ جَمِيعاࣰ فَيُنَبِّئُكُم بِمَا كُنتُمْ فِيهِ تَخْتَلِفُونَ࣌', 'وأنزلنا إليك ࡰلكتب بالحق مصدقا لما بين يديه من ࡰلكتب ومهيمنا عليه࣌ فاحكم بينهم بما أنزل ࡰلله ولا تتبع ࡰهواءهم عما جاءك من ࡰلحق࣌ لكل جعلنا منكم شرعة ومنهاجا࣌ ولو شاء ࡰلله لجعلكم أمة وحدة࣌ ولكن ليبلوكم فے ما ءاتيكم࣌ فاستبقوا ࡲلخيرت࣌ إلى ࡰلله مرجعكم جميعا فينبئكم بما كنتم فيه تختلفون࣌', NULL, 116, 'local:warsh-text.json'),
  ('warsh-5-51', 'warsh', 5, 51, '۞ وَأَنُ ࡲ࢈حْكُم بَيْنَهُم بِمَآ أَنزَلَ ࡰ۬للَّهُ࣌ وَلَا تَتَّبِعَ ࡰهْوَآءَهُمْ࣌ وَاحْذَرْهُمُۥٓ أَنْ يَّفْتِنُوكَ عَنۢ بَعْضِ مَآ أَنزَلَ ࡰ۬للَّهُ إِلَيْكَ࣌ فَإِن تَوَلَّوْاْ فَاعْلَمَ ࡰنَّمَا يُرِيدُ ࡲ۬للَّهُ أَنْ يُّصِيبَهُم بِبَعْضِ ذُنُوبِهِمْ࣌ وَإِنَّ كَثِيراࣰ مِّنَ ࡰ۬لنَّاسِ لَفَٰسِقُونَ࣌', 'وأن ࡲ࢈حكم بينهم بما أنزل ࡰلله࣌ ولا تتبع ࡰهواءهم࣌ واحذرهم أن يفتنوك عن بعض ما أنزل ࡰلله إليك࣌ فإن تولوا فاعلم ࡰنما يريد ࡲلله أن يصيبهم ببعض ذنوبهم࣌ وإن كثيرا من ࡰلناس لفسقون࣌', NULL, 116, 'local:warsh-text.json'),
  ('warsh-5-52', 'warsh', 5, 52, 'أَفَحُكْمَ ࡰ۬لْجَٰهِلِيَّةِ يَبْغُونَ࣌ وَمَنَ ࡰحْسَنُ مِنَ ࡰ۬للَّهِ حُكْماࣰ لِّقَوْمࣲ يُوقِنُونَ࣌', 'أفحكم ࡰلجهلية يبغون࣌ ومن ࡰحسن من ࡰلله حكما لقوم يوقنون࣌', NULL, 116, 'local:warsh-text.json'),
  ('warsh-5-53', 'warsh', 5, 53, 'يَٰٓأَيُّهَا ࡰ۬لذِينَ ءَامَنُواْ لَا تَتَّخِذُواْ ࡲ۬لْيَهُودَ وَالنَّصَٰرٜىٰٓ أَوْلِيَآءَ࣌ بَعْضُهُمُۥٓ أَوْلِيَآءُ بَعْضࣲ࣌ وَمَنْ يَّتَوَلَّهُم مِّنكُمْ فَإِنَّهُۥ مِنْهُمُۥٓ࣌ إِنَّ ࡰ۬للَّهَ لَا يَهْدِے ࡴ۬لْقَوْمَ ࡰ۬لظَّٰلِمِينَ࣌', 'يأيها ࡰلذين ءامنوا لا تتخذوا ࡲليهود والنصرى أولياء࣌ بعضهم أولياء بعض࣌ ومن يتولهم منكم فإنه منهم࣌ إن ࡰلله لا يهدے ࡴلقوم ࡰلظلمين࣌', NULL, 117, 'local:warsh-text.json'),
  ('warsh-5-54', 'warsh', 5, 54, 'فَتَرَى ࡰ۬لذِينَ فِے قُلُوبِهِم مَّرَضࣱ يُسَٰرِعُونَ فِيهِمْ يَقُولُونَ نَخْشٜىٰٓ أَن تُصِيبَنَا دَآئِرَةࣱ࣌ فَعَسَى ࡰ۬للَّهُ أَنْ يَّاتِيَ بِالْفَتْحِ أَوَ ࡰمْرࣲ مِّنْ عِندِهِۦ فَيُصْبِحُواْ عَلَىٰ مَآ أَسَرُّواْ فِےٓ أَنفُسِهِمْ نَٰدِمِينَ࣌', 'فترى ࡰلذين فے قلوبهم مرض يسرعون فيهم يقولون نخشى أن تصيبنا دائرة࣌ فعسى ࡰلله أن ياتي بالفتح أو ࡰمر من عنده فيصبحوا على ما أسروا فے أنفسهم ندمين࣌', NULL, 117, 'local:warsh-text.json'),
  ('warsh-5-55', 'warsh', 5, 55, 'يَقُولُ ࡲ۬لذِينَ ءَامَنُوٓاْ أَهَٰٓؤُلَآءِ ࡴ۬لذِينَ أَقْسَمُواْ بِاللَّهِ جَهْدَ أَيْمَٰنِهِمُۥٓ إِنَّهُمْ لَمَعَكُمْ حَبِطَتَ ࡰعْمَٰلُهُمْ فَأَصْبَحُواْ خَٰسِرِينَ࣌', 'يقول ࡲلذين ءامنوا أهؤلاء ࡴلذين أقسموا بالله جهد أيمنهم إنهم لمعكم حبطت ࡰعملهم فأصبحوا خسرين࣌', NULL, 117, 'local:warsh-text.json'),
  ('warsh-5-56', 'warsh', 5, 56, 'يَٰٓأَيُّهَا ࡰ۬لذِينَ ءَامَنُواْ مَنْ يَّرْتَدِدْ مِنكُمْ عَن دِينِهِۦ فَسَوْفَ يَاتِے ࡴ۬للَّهُ بِقَوْمࣲ يُحِبُّهُمْ وَيُحِبُّونَهُۥٓ أَذِلَّةٍ عَلَى ࡰ۬لْمُومِنِينَ أَعِزَّةٍ عَلَى ࡰ۬لْكٜـٰفِرِينَ يُجَٰهِدُونَ فِے سَبِيلِ ࡴ۬للَّهِ وَلَا يَخَافُونَ لَوْمَةَ لَٰٓئِمࣲ࣌ ذَٰلِكَ فَضْلُ ࡲ۬للَّهِ يُوتِيهِ مَنْ يَّشَآءُ࣌ وَاللَّهُ وَٰسِعٌ عَلِيمٌ࣌', 'يأيها ࡰلذين ءامنوا من يرتدد منكم عن دينه فسوف ياتے ࡴلله بقوم يحبهم ويحبونه أذلة على ࡰلمومنين أعزة على ࡰلكفرين يجهدون فے سبيل ࡴلله ولا يخافون لومة لئم࣌ ذلك فضل ࡲلله يوتيه من يشاء࣌ والله وسع عليم࣌', NULL, 117, 'local:warsh-text.json'),
  ('warsh-5-57', 'warsh', 5, 57, 'ࡴنَّمَا وَلِيُّكُمُ ࡲ۬للَّهُ وَرَسُولُهُۥ وَالذِينَ ءَامَنُواْ ࡲ۬لذِينَ يُقِيمُونَ ࡰ۬لصَّلَوٰةَ وَيُوتُونَ ࡰ۬لزَّكَوٰةَ وَهُمْ رَٰكِعُونَ࣌', 'ࡴنما وليكم ࡲلله ورسوله والذين ءامنوا ࡲلذين يقيمون ࡰلصلوة ويوتون ࡰلزكوة وهم ركعون࣌', NULL, 117, 'local:warsh-text.json'),
  ('warsh-5-58', 'warsh', 5, 58, 'وَمَنْ يَّتَوَلَّ ࡰ۬للَّهَ وَرَسُولَهُۥ وَالذِينَ ءَامَنُواْ فَإِنَّ حِزْبَ ࡰ۬للَّهِ هُمُ ࡲ۬لْغَٰلِبُونَ࣌', 'ومن يتول ࡰلله ورسوله والذين ءامنوا فإن حزب ࡰلله هم ࡲلغلبون࣌', NULL, 117, 'local:warsh-text.json'),
  ('warsh-5-59', 'warsh', 5, 59, 'يَٰٓأَيُّهَا ࡰ۬لذِينَ ءَامَنُواْ لَا تَتَّخِذُواْ ࡲ۬لذِينَ ࡰٜتَّخَذُواْ دِينَكُمْ هُزُؤاࣰ وَلَعِباࣰ مِّنَ ࡰ۬لذِينَ أُوتُواْ ࡲ۬لْكِتَٰبَ مِن قَبْلِكُمْ وَالْكُفَّارَ أَوْلِيَآءَ࣌ وَاتَّقُواْ ࡲ۬للَّهَ إِن كُنتُم مُّومِنِينَ࣌', 'يأيها ࡰلذين ءامنوا لا تتخذوا ࡲلذين ࡰتخذوا دينكم هزؤا ولعبا من ࡰلذين أوتوا ࡲلكتب من قبلكم والكفار أولياء࣌ واتقوا ࡲلله إن كنتم مومنين࣌', NULL, 117, 'local:warsh-text.json'),
  ('warsh-5-60', 'warsh', 5, 60, '۞ وَإِذَا نَادَيْتُمُۥٓ إِلَى ࡰ۬لصَّلَوٰةِ ࡴٜتَّخَذُوهَا هُزُؤاࣰ وَلَعِباࣰ࣌ ذَٰلِكَ بِأَنَّهُمْ قَوْمࣱ لَّا يَعْقِلُونَ࣌', 'وإذا ناديتم إلى ࡰلصلوة ࡴتخذوها هزؤا ولعبا࣌ ذلك بأنهم قوم لا يعقلون࣌', NULL, 118, 'local:warsh-text.json'),
  ('warsh-5-61', 'warsh', 5, 61, 'قُلْ يَٰٓأَهْلَ ࡰ۬لْكِتَٰبِ هَلْ تَنقِمُونَ مِنَّآ إِلَّآ أَنَ اٰمَنَّا بِاللَّهِ وَمَآ أُنزِلَ إِلَيْنَا وَمَآ أُنزِلَ مِن قَبْلُ وَأَنَّ أَكْثَرَكُمْ فَٰسِقُونَ࣌', 'قل يأهل ࡰلكتب هل تنقمون منا إلا أن امنا بالله وما أنزل إلينا وما أنزل من قبل وأن أكثركم فسقون࣌', NULL, 118, 'local:warsh-text.json'),
  ('warsh-5-62', 'warsh', 5, 62, 'قُلْ هَلُ ࡳنَبِّئُكُم بِشَرࣲّ مِّن ذَٰلِكَ مَثُوبَةً عِندَ ࡰ۬للَّهِ مَن لَّعَنَهُ ࡲ۬للَّهُ وَغَضِبَ عَلَيْهِ وَجَعَلَ مِنْهُمُ ࡲ۬لْقِرَدَةَ وَالْخَنَازِيرَ وَعَبَدَ ࡰ۬لطَّٰغُوتَ࣌ أُوْلَٰٓئِكَ شَرࣱّ مَّكَاناࣰ وَأَضَلُّ عَن سَوَآءِ ࡴ۬لسَّبِيلِ࣌', 'قل هل ࡳنبئكم بشر من ذلك مثوبة عند ࡰلله من لعنه ࡲلله وغضب عليه وجعل منهم ࡲلقردة والخنازير وعبد ࡰلطغوت࣌ أولئك شر مكانا وأضل عن سواء ࡴلسبيل࣌', NULL, 118, 'local:warsh-text.json'),
  ('warsh-5-63', 'warsh', 5, 63, 'وَإِذَا جَآءُوكُمْ قَالُوٓاْ ءَامَنَّا وَقَد دَّخَلُواْ بِالْكُفْرِ وَهُمْ قَدْ خَرَجُواْ بِهِۦ࣌ وَاللَّهُ أَعْلَمُ بِمَا كَانُواْ يَكْتُمُونَ࣌', 'وإذا جاءوكم قالوا ءامنا وقد دخلوا بالكفر وهم قد خرجوا به࣌ والله أعلم بما كانوا يكتمون࣌', NULL, 118, 'local:warsh-text.json'),
  ('warsh-5-64', 'warsh', 5, 64, 'وَتَرٜىٰ كَثِيراࣰ مِّنْهُمْ يُسَٰرِعُونَ فِے ࡴ۬لِاثْمِ وَالْعُدْوَٰنِ وَأَكْلِهِمُ ࡲ۬لسُّحْتَ࣌ لَبِيسَ مَا كَانُواْ يَعْمَلُونَ࣌', 'وترى كثيرا منهم يسرعون فے ࡴلاثم والعدون وأكلهم ࡲلسحت࣌ لبيس ما كانوا يعملون࣌', NULL, 118, 'local:warsh-text.json'),
  ('warsh-5-65', 'warsh', 5, 65, 'لَوْلَا يَنْهٜيٰهُمُ ࡲ۬لرَّبَّٰنِيُّونَ وَالَاحْبَارُ عَن قَوْلِهِمُ ࡲ۬لِاثْمَ وَأَكْلِهِمُ ࡲ۬لسُّحْتَ࣌ لَبِيسَ مَا كَانُواْ يَصْنَعُونَ࣌', 'لولا ينهيهم ࡲلربنيون والاحبار عن قولهم ࡲلاثم وأكلهم ࡲلسحت࣌ لبيس ما كانوا يصنعون࣌', NULL, 118, 'local:warsh-text.json'),
  ('warsh-5-66', 'warsh', 5, 66, 'وَقَالَتِ ࡴ۬لْيَهُودُ يَدُ ࡲ۬للَّهِ مَغْلُولَةٌ࣌ غُلَّتَ ࡰيْدِيهِمْ وَلُعِنُواْ بِمَا قَالُواْ࣌ بَلْ يَدَٰهُ مَبْسُوطَتَٰنِ يُنفِقُ كَيْفَ يَشَآءُ࣌ وَلَيَزِيدَنَّ كَثِيراࣰ مِّنْهُم مَّآ أُنزِلَ إِلَيْكَ مِن رَّبِّكَ طُغْيَٰناࣰ وَكُفْراࣰ࣌ وَأَلْقَيْنَا بَيْنَهُمُ ࡲ۬لْعَدَٰوَةَ وَالْبَغْضَآءَ ࡹلَىٰ يَوْمِ ࡴ۬لْقِيَٰمَةِ࣌ كُلَّمَآ أَوْقَدُواْ نَاراࣰ لِّلْحَرْبِ أَطْفَأَهَا ࡰ۬للَّهُ࣌ وَيَسْعَوْنَ فِے ࡴ۬لَارْضِ فَسَاداࣰ࣌ وَاللَّهُ لَا يُحِبُّ ࡲ۬لْمُفْسِدِينَ࣌', 'وقالت ࡴليهود يد ࡲلله مغلولة࣌ غلت ࡰيديهم ولعنوا بما قالوا࣌ بل يده مبسوطتن ينفق كيف يشاء࣌ وليزيدن كثيرا منهم ما أنزل إليك من ربك طغينا وكفرا࣌ وألقينا بينهم ࡲلعدوة والبغضاء ࡹلى يوم ࡴلقيمة࣌ كلما أوقدوا نارا للحرب أطفأها ࡰلله࣌ ويسعون فے ࡴلارض فسادا࣌ والله لا يحب ࡲلمفسدين࣌', NULL, 118, 'local:warsh-text.json'),
  ('warsh-5-67', 'warsh', 5, 67, 'وَلَوَ ࡰنَّ أَهْلَ ࡰ۬لْكِتَٰبِ ءَامَنُواْ وَاتَّقَوْاْ لَكَفَّرْنَا عَنْهُمْ سَيِّـَٔاتِهِمْ وَلَأَدْخَلْنَٰهُمْ جَنَّٰتِ ࡴ۬لنَّعِيمِ࣌', 'ولو ࡰن أهل ࡰلكتب ءامنوا واتقوا لكفرنا عنهم سياتهم ولأدخلنهم جنت ࡴلنعيم࣌', NULL, 119, 'local:warsh-text.json'),
  ('warsh-5-68', 'warsh', 5, 68, 'وَلَوَ ࡰنَّهُمُۥٓ أَقَامُواْ ࡲ۬لتَّوْرٜيٰةَ وَالِانجِيلَ وَمَآ أُنزِلَ إِلَيْهِم مِّن رَّبِّهِمْ لَأَكَلُواْ مِن فَوْقِهِمْ وَمِن تَحْتِ أَرْجُلِهِم࣌ مِّنْهُمُۥٓ أُمَّةࣱ مُّقْتَصِدَةࣱ࣌ وَكَثِيرࣱ مِّنْهُمْ سَآءَ مَا يَعْمَلُونَ࣌', 'ولو ࡰنهم أقاموا ࡲلتورية والانجيل وما أنزل إليهم من ربهم لأكلوا من فوقهم ومن تحت أرجلهم࣌ منهم أمة مقتصدة࣌ وكثير منهم ساء ما يعملون࣌', NULL, 119, 'local:warsh-text.json'),
  ('warsh-5-69', 'warsh', 5, 69, '۞ يَٰٓأَيُّهَا ࡰ۬لرَّسُولُ بَلِّغْ مَآ أُنزِلَ إِلَيْكَ مِن رَّبِّكَ࣌ وَإِن لَّمْ تَفْعَلْ فَمَا بَلَّغْتَ رِسَالَٰتِهِۦ࣌ وَاللَّهُ يَعْصِمُكَ مِنَ ࡰ۬لنَّاسِ࣌ إِنَّ ࡰ۬للَّهَ لَا يَهْدِے ࡴ۬لْقَوْمَ ࡰ۬لْكٜـٰفِرِينَ࣌', 'يأيها ࡰلرسول بلغ ما أنزل إليك من ربك࣌ وإن لم تفعل فما بلغت رسالته࣌ والله يعصمك من ࡰلناس࣌ إن ࡰلله لا يهدے ࡴلقوم ࡰلكفرين࣌', NULL, 119, 'local:warsh-text.json'),
  ('warsh-5-70', 'warsh', 5, 70, 'قُلْ يَٰٓأَهْلَ ࡰ۬لْكِتَٰبِ لَسْتُمْ عَلَىٰ شَےْءٍ حَتَّىٰ تُقِيمُواْ ࡲ۬لتَّوْرٜيٰةَ وَالِانجِيلَ وَمَآ أُنزِلَ إِلَيْكُم مِّن رَّبِّكُمْ࣌ وَلَيَزِيدَنَّ كَثِيراࣰ مِّنْهُم مَّآ أُنزِلَ إِلَيْكَ مِن رَّبِّكَ طُغْيَٰناࣰ وَكُفْراࣰ࣌ فَلَا تَاسَ عَلَى ࡰ۬لْقَوْمِ ࡴ۬لْكٜـٰفِرِينَ࣌', 'قل يأهل ࡰلكتب لستم على شےء حتى تقيموا ࡲلتورية والانجيل وما أنزل إليكم من ربكم࣌ وليزيدن كثيرا منهم ما أنزل إليك من ربك طغينا وكفرا࣌ فلا تاس على ࡰلقوم ࡴلكفرين࣌', NULL, 119, 'local:warsh-text.json'),
  ('warsh-5-71', 'warsh', 5, 71, 'إِنَّ ࡰ۬لذِينَ ءَامَنُواْ وَالذِينَ هَادُواْ وَالصَّٰبُونَ وَالنَّصَٰرٜىٰ مَنَ اٰمَنَ بِاللَّهِ وَالْيَوْمِ ࡴ۬لَاخِرِ وَعَمِلَ صَٰلِحاࣰ فَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ࣌', 'إن ࡰلذين ءامنوا والذين هادوا والصبون والنصرى من امن بالله واليوم ࡴلاخر وعمل صلحا فلا خوف عليهم ولا هم يحزنون࣌', NULL, 119, 'local:warsh-text.json'),
  ('warsh-5-72', 'warsh', 5, 72, 'لَقَدَ ࡰخَذْنَا مِيثَٰقَ بَنِےٓ إِسْرَآءِيلَ وَأَرْسَلْنَآ إِلَيْهِمْ رُسُلاࣰ࣌ كُلَّمَا جَآءَهُمْ رَسُولُۢ بِمَا لَا تَهْوٜىٰٓ أَنفُسُهُمْ فَرِيقاࣰ كَذَّبُواْ وَفَرِيقاࣰ يَقْتُلُونَ࣌', 'لقد ࡰخذنا ميثق بنے إسراءيل وأرسلنا إليهم رسلا࣌ كلما جاءهم رسول بما لا تهوى أنفسهم فريقا كذبوا وفريقا يقتلون࣌', NULL, 119, 'local:warsh-text.json'),
  ('warsh-5-73', 'warsh', 5, 73, 'وَحَسِبُوٓاْ أَلَّا تَكُونَ فِتْنَةࣱ فَعَمُواْ وَصَمُّواْ ثُمَّ تَابَ ࡰ۬للَّهُ عَلَيْهِمْ ثُمَّ عَمُواْ وَصَمُّواْ࣌ كَثِيرࣱ مِّنْهُمْ࣌ وَاللَّهُ بَصِيرُۢ بِمَا يَعْمَلُونَ࣌', 'وحسبوا ألا تكون فتنة فعموا وصموا ثم تاب ࡰلله عليهم ثم عموا وصموا࣌ كثير منهم࣌ والله بصير بما يعملون࣌', NULL, 120, 'local:warsh-text.json'),
  ('warsh-5-74', 'warsh', 5, 74, 'لَقَدْ كَفَرَ ࡰ۬لذِينَ قَالُوٓاْ إِنَّ ࡰ۬للَّهَ هُوَ ࡰ۬لْمَسِيحُ ࡲٜبْنُ مَرْيَمَ࣌ وَقَالَ ࡰ۬لْمَسِيحُ يَٰبَنِےٓ إِسْرَآءِيلَ ࡸَعْبُدُواْ ࡲ۬للَّهَ رَبِّے وَرَبَّكُمُۥٓ࣌ إِنَّهُۥ مَنْ يُّشْرِكْ بِاللَّهِ فَقَدْ حَرَّمَ ࡰ۬للَّهُ عَلَيْهِ ࡴ۬لْجَنَّةَ وَمَأْوٜيٰهُ ࡲ۬لنَّارُ࣌ وَمَا لِلظَّٰلِمِينَ مِنَ ࡰنصٜارࣲ࣌', 'لقد كفر ࡰلذين قالوا إن ࡰلله هو ࡰلمسيح ࡲبن مريم࣌ وقال ࡰلمسيح يبنے إسراءيل ࡸعبدوا ࡲلله ربے وربكم࣌ إنه من يشرك بالله فقد حرم ࡰلله عليه ࡴلجنة ومأويه ࡲلنار࣌ وما للظلمين من ࡰنصار࣌', NULL, 120, 'local:warsh-text.json'),
  ('warsh-5-75', 'warsh', 5, 75, '۞ لَّقَدْ كَفَرَ ࡰ۬لذِينَ قَالُوٓاْ إِنَّ ࡰ۬للَّهَ ثَالِثُ ثَلَٰثَةࣲ࣌ وَمَا مِنِ ࡴلَٰهٍ ࡴلَّآ إِلَٰهࣱ وَٰحِدࣱ࣌ وَإِن لَّمْ يَنتَهُواْ عَمَّا يَقُولُونَ لَيَمَسَّنَّ ࡰ۬لذِينَ كَفَرُواْ مِنْهُمْ عَذَابٌ ࡰلِيمٌ࣌', 'لقد كفر ࡰلذين قالوا إن ࡰلله ثالث ثلثة࣌ وما من ࡴله ࡴلا إله وحد࣌ وإن لم ينتهوا عما يقولون ليمسن ࡰلذين كفروا منهم عذاب ࡰليم࣌', NULL, 120, 'local:warsh-text.json'),
  ('warsh-5-76', 'warsh', 5, 76, 'ࡰفَلَا يَتُوبُونَ إِلَى ࡰ۬للَّهِ وَيَسْتَغْفِرُونَهُۥ࣌ وَاللَّهُ غَفُورࣱ رَّحِيمࣱ࣌', 'ࡰفلا يتوبون إلى ࡰلله ويستغفرونه࣌ والله غفور رحيم࣌', NULL, 120, 'local:warsh-text.json'),
  ('warsh-5-77', 'warsh', 5, 77, 'مَّا ࡰ۬لْمَسِيحُ ࡲٜبْنُ مَرْيَمَ إِلَّا رَسُولࣱ قَدْ خَلَتْ مِن قَبْلِهِ ࡴ۬لرُّسُلُ࣌ وَأُمُّهُۥ صِدِّيقَةࣱ࣌ كَانَا يَاكُلَٰنِ ࡴ۬لطَّعَامَ࣌ ࡸَنظُرْ كَيْفَ نُبَيِّنُ لَهُمُ ࡲ۬لَايَٰتِ ثُمَّ ࡸَنظُرَ ࡰنّٜىٰ يُوفَكُونَ࣌', 'ما ࡰلمسيح ࡲبن مريم إلا رسول قد خلت من قبله ࡴلرسل࣌ وأمه صديقة࣌ كانا ياكلن ࡴلطعام࣌ ࡸنظر كيف نبين لهم ࡲلايت ثم ࡸنظر ࡰنى يوفكون࣌', NULL, 120, 'local:warsh-text.json'),
  ('warsh-5-78', 'warsh', 5, 78, 'قُلَ ࡰتَعْبُدُونَ مِن دُونِ ࡴ۬للَّهِ مَا لَا يَمْلِكُ لَكُمْ ضَرّاࣰ وَلَا نَفْعاࣰ࣌ وَاللَّهُ هُوَ ࡰ۬لسَّمِيعُ ࡲ۬لْعَلِيمُ࣌', 'قل ࡰتعبدون من دون ࡴلله ما لا يملك لكم ضرا ولا نفعا࣌ والله هو ࡰلسميع ࡲلعليم࣌', NULL, 120, 'local:warsh-text.json'),
  ('warsh-5-79', 'warsh', 5, 79, 'قُلْ يَٰٓأَهْلَ ࡰ۬لْكِتَٰبِ لَا تَغْلُواْ فِے دِينِكُمْ غَيْرَ ࡰ۬لْحَقِّ࣌ وَلَا تَتَّبِعُوٓاْ أَهْوَآءَ قَوْمࣲ قَد ضَّلُّواْ مِن قَبْلُ وَأَضَلُّواْ كَثِيراࣰ وَضَلُّواْ عَن سَوَآءِ ࡴ۬لسَّبِيلِ࣌', 'قل يأهل ࡰلكتب لا تغلوا فے دينكم غير ࡰلحق࣌ ولا تتبعوا أهواء قوم قد ضلوا من قبل وأضلوا كثيرا وضلوا عن سواء ࡴلسبيل࣌', NULL, 120, 'local:warsh-text.json'),
  ('warsh-5-80', 'warsh', 5, 80, 'لُعِنَ ࡰ۬لذِينَ كَفَرُواْ مِنۢ بَنِےٓ إِسْرَآءِيلَ عَلَىٰ لِسَانِ دَاوُۥدَ وَعِيسَى ࡰٜبْنِ مَرْيَمَ࣌ ذَٰلِكَ بِمَا عَصَواْ وَّكَانُواْ يَعْتَدُونَ࣌', 'لعن ࡰلذين كفروا من بنے إسراءيل على لسان داود وعيسى ࡰبن مريم࣌ ذلك بما عصوا وكانوا يعتدون࣌', NULL, 121, 'local:warsh-text.json'),
  ('warsh-5-81', 'warsh', 5, 81, 'كَانُواْ لَا يَتَنَاهَوْنَ عَن مُّنكَرࣲ فَعَلُوهُ࣌ لَبِيسَ مَا كَانُواْ يَفْعَلُونَ࣌', 'كانوا لا يتناهون عن منكر فعلوه࣌ لبيس ما كانوا يفعلون࣌', NULL, 121, 'local:warsh-text.json'),
  ('warsh-5-82', 'warsh', 5, 82, 'تَرٜىٰ كَثِيراࣰ مِّنْهُمْ يَتَوَلَّوْنَ ࡰ۬لذِينَ كَفَرُواْ࣌ لَبِيسَ مَا قَدَّمَتْ لَهُمُۥٓ أَنفُسُهُمُۥٓ أَن سَخِطَ ࡰ۬للَّهُ عَلَيْهِمْ وَفِے ࡴ۬لْعَذَابِ هُمْ خَٰلِدُونَ࣌', 'ترى كثيرا منهم يتولون ࡰلذين كفروا࣌ لبيس ما قدمت لهم أنفسهم أن سخط ࡰلله عليهم وفے ࡴلعذاب هم خلدون࣌', NULL, 121, 'local:warsh-text.json'),
  ('warsh-5-83', 'warsh', 5, 83, 'وَلَوْ كَانُواْ يُومِنُونَ بِاللَّهِ وَالنَّبِےٓءِ وَمَآ أُنزِلَ إِلَيْهِ مَا ࡰٜتَّخَذُوهُمُۥٓ أَوْلِيَآءَ࣌ وَلَٰكِنَّ كَثِيراࣰ مِّنْهُمْ فَٰسِقُونَ࣌', 'ولو كانوا يومنون بالله والنبےء وما أنزل إليه ما ࡰتخذوهم أولياء࣌ ولكن كثيرا منهم فسقون࣌', NULL, 121, 'local:warsh-text.json'),
  ('warsh-5-84', 'warsh', 5, 84, '۞ لَتَجِدَنَّ أَشَدَّ ࡰ۬لنَّاسِ عَدَٰوَةࣰ لِّلذِينَ ءَامَنُواْ ࡲ۬لْيَهُودَ وَالذِينَ أَشْرَكُواْ࣌ وَلَتَجِدَنَّ أَقْرَبَهُم مَّوَدَّةࣰ لِّلذِينَ ءَامَنُواْ ࡲ۬لذِينَ قَالُوٓاْ إِنَّا نَصَٰرٜىٰ࣌ ذَٰلِكَ بِأَنَّ مِنْهُمْ قِسِّيسِينَ وَرُهْبَاناࣰ وَأَنَّهُمْ لَا يَسْتَكْبِرُونَ࣌', 'لتجدن أشد ࡰلناس عدوة للذين ءامنوا ࡲليهود والذين أشركوا࣌ ولتجدن أقربهم مودة للذين ءامنوا ࡲلذين قالوا إنا نصرى࣌ ذلك بأن منهم قسيسين ورهبانا وأنهم لا يستكبرون࣌', NULL, 121, 'local:warsh-text.json'),
  ('warsh-5-85', 'warsh', 5, 85, 'وَإِذَا سَمِعُواْ مَآ أُنزِلَ إِلَى ࡰ۬لرَّسُولِ تَرٜىٰٓ أَعْيُنَهُمْ تَفِيضُ مِنَ ࡰ۬لدَّمْعِ مِمَّا عَرَفُواْ مِنَ ࡰ۬لْحَقِّ يَقُولُونَ رَبَّنَآ ءَامَنَّا فَاكْتُبْنَا مَعَ ࡰ۬لشَّٰهِدِينَ࣌', 'وإذا سمعوا ما أنزل إلى ࡰلرسول ترى أعينهم تفيض من ࡰلدمع مما عرفوا من ࡰلحق يقولون ربنا ءامنا فاكتبنا مع ࡰلشهدين࣌', NULL, 121, 'local:warsh-text.json'),
  ('warsh-5-86', 'warsh', 5, 86, 'وَمَا لَنَا لَا نُومِنُ بِاللَّهِ وَمَا جَآءَنَا مِنَ ࡰ۬لْحَقِّ وَنَطْمَعُ أَنْ يُّدْخِلَنَا رَبُّنَا مَعَ ࡰ۬لْقَوْمِ ࡴ۬لصَّٰلِحِينَ࣌', 'وما لنا لا نومن بالله وما جاءنا من ࡰلحق ونطمع أن يدخلنا ربنا مع ࡰلقوم ࡴلصلحين࣌', NULL, 122, 'local:warsh-text.json'),
  ('warsh-5-87', 'warsh', 5, 87, 'فَأَثَٰبَهُمُ ࡲ۬للَّهُ بِمَا قَالُواْ جَنَّٰتࣲ تَجْرِے مِن تَحْتِهَا ࡰ۬لَانْهَٰرُ خَٰلِدِينَ فِيهَا࣌ وَذَٰلِكَ جَزَآءُ ࡲ۬لْمُحْسِنِينَ࣌', 'فأثبهم ࡲلله بما قالوا جنت تجرے من تحتها ࡰلانهر خلدين فيها࣌ وذلك جزاء ࡲلمحسنين࣌', NULL, 122, 'local:warsh-text.json'),
  ('warsh-5-88', 'warsh', 5, 88, 'وَالذِينَ كَفَرُواْ وَكَذَّبُواْ بِـَٔايَٰتِنَآ أُوْلَٰٓئِكَ أَصْحَٰبُ ࡲ۬لْجَحِيمِ࣌', 'والذين كفروا وكذبوا بايتنا أولئك أصحب ࡲلجحيم࣌', NULL, 122, 'local:warsh-text.json'),
  ('warsh-5-89', 'warsh', 5, 89, 'يَٰٓأَيُّهَا ࡰ۬لذِينَ ءَامَنُواْ لَا تُحَرِّمُواْ طَيِّبَٰتِ مَآ أَحَلَّ ࡰ۬للَّهُ لَكُمْ وَلَا تَعْتَدُوٓاْ࣌ إِنَّ ࡰ۬للَّهَ لَا يُحِبُّ ࡲ۬لْمُعْتَدِينَ࣌', 'يأيها ࡰلذين ءامنوا لا تحرموا طيبت ما أحل ࡰلله لكم ولا تعتدوا࣌ إن ࡰلله لا يحب ࡲلمعتدين࣌', NULL, 122, 'local:warsh-text.json'),
  ('warsh-5-90', 'warsh', 5, 90, 'وَكُلُواْ مِمَّا رَزَقَكُمُ ࡲ۬للَّهُ حَلَٰلاࣰ طَيِّباࣰ࣌ وَاتَّقُواْ ࡲ۬للَّهَ ࡰ۬لذِےٓ أَنتُم بِهِۦ مُومِنُونَ࣌', 'وكلوا مما رزقكم ࡲلله حللا طيبا࣌ واتقوا ࡲلله ࡰلذے أنتم به مومنون࣌', NULL, 122, 'local:warsh-text.json'),
  ('warsh-5-91', 'warsh', 5, 91, 'لَا يُوَ۬اخِذُكُمُ ࡲ۬للَّهُ بِاللَّغْوِ فِےٓ أَيْمَٰنِكُمْ࣌ وَلَٰكِنْ يُّوَ۬اخِذُكُم بِمَا عَقَّدتُّمُ ࡲ۬لَايْمَٰنَ࣌ فَكَفَّٰرَتُهُۥٓ إِطْعَامُ عَشَرَةِ مَسَٰكِينَ مِنَ ࡰوْسَطِ مَا تُطْعِمُونَ أَهْلِيكُمُۥٓ أَوْ كِسْوَتُهُمُۥٓ أَوْ تَحْرِيرُ رَقَبَةࣲ࣌ فَمَن لَّمْ يَجِدْ فَصِيَامُ ثَلَٰثَةِ أَيَّامࣲ࣌ ذَٰلِكَ كَفَّٰرَةُ أَيْمَٰنِكُمُۥٓ إِذَا حَلَفْتُمْ࣌ وَاحْفَظُوٓاْ أَيْمَٰنَكُمْ࣌ كَذَٰلِكَ يُبَيِّنُ ࡲ۬للَّهُ لَكُمُۥٓ ءَايَٰتِهِۦ لَعَلَّكُمْ تَشْكُرُونَ࣌', 'لا يواخذكم ࡲلله باللغو فے أيمنكم࣌ ولكن يواخذكم بما عقدتم ࡲلايمن࣌ فكفرته إطعام عشرة مسكين من ࡰوسط ما تطعمون أهليكم أو كسوتهم أو تحرير رقبة࣌ فمن لم يجد فصيام ثلثة أيام࣌ ذلك كفرة أيمنكم إذا حلفتم࣌ واحفظوا أيمنكم࣌ كذلك يبين ࡲلله لكم ءايته لعلكم تشكرون࣌', NULL, 122, 'local:warsh-text.json'),
  ('warsh-5-92', 'warsh', 5, 92, '۞ يَٰٓأَيُّهَا ࡰ۬لذِينَ ءَامَنُوٓاْ إِنَّمَا ࡰ۬لْخَمْرُ وَالْمَيْسِرُ وَالَانصَابُ وَالَازْلَٰمُ رِجْسࣱ مِّنْ عَمَلِ ࡴ۬لشَّيْطَٰنِ فَاجْتَنِبُوهُ لَعَلَّكُمْ تُفْلِحُونَ࣌', 'يأيها ࡰلذين ءامنوا إنما ࡰلخمر والميسر والانصاب والازلم رجس من عمل ࡴلشيطن فاجتنبوه لعلكم تفلحون࣌', NULL, 122, 'local:warsh-text.json'),
  ('warsh-5-93', 'warsh', 5, 93, 'إِنَّمَا يُرِيدُ ࡲ۬لشَّيْطَٰنُ أَنْ يُّوقِعَ بَيْنَكُمُ ࡲ۬لْعَدَٰوَةَ وَالْبَغْضَآءَ فِے ࡴ۬لْخَمْرِ وَالْمَيْسِرِ وَيَصُدَّكُمْ عَن ذِكْرِ ࡴ۬للَّهِ وَعَنِ ࡴ۬لصَّلَوٰةِ࣌ فَهَلَ ࡰنتُم مُّنتَهُونَ࣌', 'إنما يريد ࡲلشيطن أن يوقع بينكم ࡲلعدوة والبغضاء فے ࡴلخمر والميسر ويصدكم عن ذكر ࡴلله وعن ࡴلصلوة࣌ فهل ࡰنتم منتهون࣌', NULL, 123, 'local:warsh-text.json'),
  ('warsh-5-94', 'warsh', 5, 94, 'وَأَطِيعُواْ ࡲ۬للَّهَ وَأَطِيعُواْ ࡲ۬لرَّسُولَ وَاحْذَرُواْ࣌ فَإِن تَوَلَّيْتُمْ فَاعْلَمُوٓاْ أَنَّمَا عَلَىٰ رَسُولِنَا ࡰ۬لْبَلَٰغُ ࡲ۬لْمُبِينُ࣌', 'وأطيعوا ࡲلله وأطيعوا ࡲلرسول واحذروا࣌ فإن توليتم فاعلموا أنما على رسولنا ࡰلبلغ ࡲلمبين࣌', NULL, 123, 'local:warsh-text.json'),
  ('warsh-5-95', 'warsh', 5, 95, 'لَيْسَ عَلَى ࡰ۬لذِينَ ءَامَنُواْ وَعَمِلُواْ ࡲ۬لصَّٰلِحَٰتِ جُنَاحࣱ فِيمَا طَعِمُوٓاْ إِذَا مَا ࡰٜتَّقَواْ وَّءَامَنُواْ وَعَمِلُواْ ࡲ۬لصَّٰلِحَٰتِ ثُمَّ ࡰٜتَّقَواْ وَّءَامَنُواْ ثُمَّ ࡰٜتَّقَواْ وَّأَحْسَنُواْ࣌ وَاللَّهُ يُحِبُّ ࡲ۬لْمُحْسِنِينَ࣌', 'ليس على ࡰلذين ءامنوا وعملوا ࡲلصلحت جناح فيما طعموا إذا ما ࡰتقوا وءامنوا وعملوا ࡲلصلحت ثم ࡰتقوا وءامنوا ثم ࡰتقوا وأحسنوا࣌ والله يحب ࡲلمحسنين࣌', NULL, 123, 'local:warsh-text.json'),
  ('warsh-5-96', 'warsh', 5, 96, 'يَٰٓأَيُّهَا ࡰ۬لذِينَ ءَامَنُواْ لَيَبْلُوَنَّكُمُ ࡲ۬للَّهُ بِشَےْءࣲ مِّنَ ࡰ۬لصَّيْدِ تَنَالُهُۥٓ أَيْدِيكُمْ وَرِمَاحُكُمْ لِيَعْلَمَ ࡰ۬للَّهُ مَنْ يَّخَافُهُۥ بِالْغَيْبِ࣌ فَمَنِ ࡴٜعْتَدٜىٰ بَعْدَ ذَٰلِكَ فَلَهُۥ عَذَابٌ ࡰلِيمࣱ࣌', 'يأيها ࡰلذين ءامنوا ليبلونكم ࡲلله بشےء من ࡰلصيد تناله أيديكم ورماحكم ليعلم ࡰلله من يخافه بالغيب࣌ فمن ࡴعتدى بعد ذلك فله عذاب ࡰليم࣌', NULL, 123, 'local:warsh-text.json'),
  ('warsh-5-97', 'warsh', 5, 97, 'يَٰٓأَيُّهَا ࡰ۬لذِينَ ءَامَنُواْ لَا تَقْتُلُواْ ࡲ۬لصَّيْدَ وَأَنتُمْ حُرُمࣱ࣌ وَمَن قَتَلَهُۥ مِنكُم مُّتَعَمِّداࣰ فَجَزَآءُ مِثْلِ مَا قَتَلَ مِنَ ࡰ۬لنَّعَمِ يَحْكُمُ بِهِۦ ذَوَا عَدْلࣲ مِّنكُمْ هَدْياَۢ بَٰلِغَ ࡰ۬لْكَعْبَةِ أَوْ كَفَّٰرَةُ طَعَامِ مَسَٰكِينَ أَوْ عَدْلُ ذَٰلِكَ صِيَاماࣰ لِّيَذُوقَ وَبَالَ أَمْرِهِۦ࣌ عَفَا ࡰ۬للَّهُ عَمَّا سَلَفَ࣌ وَمَنْ عَادَ فَيَنتَقِمُ ࡲ۬للَّهُ مِنْهُ࣌ وَاللَّهُ عَزِيزࣱ ذُو ࡲٜنتِقَامٍ࣌', 'يأيها ࡰلذين ءامنوا لا تقتلوا ࡲلصيد وأنتم حرم࣌ ومن قتله منكم متعمدا فجزاء مثل ما قتل من ࡰلنعم يحكم به ذوا عدل منكم هديا بلغ ࡰلكعبة أو كفرة طعام مسكين أو عدل ذلك صياما ليذوق وبال أمره࣌ عفا ࡰلله عما سلف࣌ ومن عاد فينتقم ࡲلله منه࣌ والله عزيز ذو ࡲنتقام࣌', NULL, 123, 'local:warsh-text.json'),
  ('warsh-5-98', 'warsh', 5, 98, 'ࡳحِلَّ لَكُمْ صَيْدُ ࡲ۬لْبَحْرِ وَطَعَامُهُۥ࣌ مَتَٰعاࣰ لَّكُمْ وَلِلسَّيَّارَةِ࣌ وَحُرِّمَ عَلَيْكُمْ صَيْدُ ࡲ۬لْبَرِّ مَا دُمْتُمْ حُرُماࣰ࣌ وَاتَّقُواْ ࡲ۬للَّهَ ࡰ۬لذِےٓ إِلَيْهِ تُحْشَرُونَ࣌', 'ࡳحل لكم صيد ࡲلبحر وطعامه࣌ متعا لكم وللسيارة࣌ وحرم عليكم صيد ࡲلبر ما دمتم حرما࣌ واتقوا ࡲلله ࡰلذے إليه تحشرون࣌', NULL, 124, 'local:warsh-text.json'),
  ('warsh-5-99', 'warsh', 5, 99, '۞ جَعَلَ ࡰ۬للَّهُ ࡲ۬لْكَعْبَةَ ࡰ۬لْبَيْتَ ࡰ۬لْحَرَامَ قِيَٰماࣰ لِّلنَّاسِ وَالشَّهْرَ ࡰ۬لْحَرَامَ وَالْهَدْيَ وَالْقَلَٰٓئِدَ࣌ ذَٰلِكَ لِتَعْلَمُوٓاْ أَنَّ ࡰ۬للَّهَ يَعْلَمُ مَا فِے ࡴ۬لسَّمَٰوَٰتِ وَمَا فِے ࡴ۬لَارْضِ وَأَنَّ ࡰ۬للَّهَ بِكُلِّ شَےْءٍ عَلِيمٌ࣌', 'جعل ࡰلله ࡲلكعبة ࡰلبيت ࡰلحرام قيما للناس والشهر ࡰلحرام والهدي والقلئد࣌ ذلك لتعلموا أن ࡰلله يعلم ما فے ࡴلسموت وما فے ࡴلارض وأن ࡰلله بكل شےء عليم࣌', NULL, 124, 'local:warsh-text.json'),
  ('warsh-5-100', 'warsh', 5, 100, 'ࡴٜعْلَمُوٓاْ أَنَّ ࡰ۬للَّهَ شَدِيدُ ࡲ۬لْعِقَابِ وَأَنَّ ࡰ۬للَّهَ غَفُورࣱ رَّحِيمࣱ࣌', 'ࡴعلموا أن ࡰلله شديد ࡲلعقاب وأن ࡰلله غفور رحيم࣌', NULL, 124, 'local:warsh-text.json'),
  ('warsh-5-101', 'warsh', 5, 101, 'مَّا عَلَى ࡰ۬لرَّسُولِ إِلَّا ࡰ۬لْبَلَٰغُ࣌ وَاللَّهُ يَعْلَمُ مَا تُبْدُونَ وَمَا تَكْتُمُونَ࣌', 'ما على ࡰلرسول إلا ࡰلبلغ࣌ والله يعلم ما تبدون وما تكتمون࣌', NULL, 124, 'local:warsh-text.json'),
  ('warsh-5-102', 'warsh', 5, 102, 'قُل لَّا يَسْتَوِے ࡴ۬لْخَبِيثُ وَالطَّيِّبُ وَلَوَ ࡰعْجَبَكَ كَثْرَةُ ࡲ۬لْخَبِيثِ࣌ فَاتَّقُواْ ࡲ۬للَّهَ يَٰٓأُوْلِے ࡴ۬لَالْبَٰبِ لَعَلَّكُمْ تُفْلِحُونَ࣌', 'قل لا يستوے ࡴلخبيث والطيب ولو ࡰعجبك كثرة ࡲلخبيث࣌ فاتقوا ࡲلله يأولے ࡴلالبب لعلكم تفلحون࣌', NULL, 124, 'local:warsh-text.json'),
  ('warsh-5-103', 'warsh', 5, 103, 'يَٰٓأَيُّهَا ࡰ۬لذِينَ ءَامَنُواْ لَا تَسْـَٔلُواْ عَنَ ࡰشْيَآءَ ࡹن تُبْدَ لَكُمْ تَسُؤْكُمْ࣌ وَإِن تَسْـَٔلُواْ عَنْهَا حِينَ يُنَزَّلُ ࡲ۬لْقُرْءَانُ تُبْدَ لَكُمْ عَفَا ࡰ۬للَّهُ عَنْهَا࣌ وَاللَّهُ غَفُورٌ حَلِيمࣱ࣌', 'يأيها ࡰلذين ءامنوا لا تسلوا عن ࡰشياء ࡹن تبد لكم تسؤكم࣌ وإن تسلوا عنها حين ينزل ࡲلقرءان تبد لكم عفا ࡰلله عنها࣌ والله غفور حليم࣌', NULL, 124, 'local:warsh-text.json'),
  ('warsh-5-104', 'warsh', 5, 104, 'قَدْ سَأَلَهَا قَوْمࣱ مِّن قَبْلِكُمْ ثُمَّ أَصْبَحُواْ بِهَا كٜـٰفِرِينَ࣌', 'قد سألها قوم من قبلكم ثم أصبحوا بها كفرين࣌', NULL, 124, 'local:warsh-text.json'),
  ('warsh-5-105', 'warsh', 5, 105, 'مَا جَعَلَ ࡰ۬للَّهُ مِنۢ بَحِيرَةࣲ وَلَا سَآئِبَةࣲ وَلَا وَصِيلَةࣲ وَلَا حَامࣲ࣌ وَلَٰكِنَّ ࡰ۬لذِينَ كَفَرُواْ يَفْتَرُونَ عَلَى ࡰ۬للَّهِ ࡴ۬لْكَذِبَ وَأَكْثَرُهُمْ لَا يَعْقِلُونَ࣌', 'ما جعل ࡰلله من بحيرة ولا سائبة ولا وصيلة ولا حام࣌ ولكن ࡰلذين كفروا يفترون على ࡰلله ࡴلكذب وأكثرهم لا يعقلون࣌', NULL, 124, 'local:warsh-text.json'),
  ('warsh-5-106', 'warsh', 5, 106, 'وَإِذَا قِيلَ لَهُمْ تَعَالَوِاْ ࡴلَىٰ مَآ أَنزَلَ ࡰ۬للَّهُ وَإِلَى ࡰ۬لرَّسُولِ قَالُواْ حَسْبُنَا مَا وَجَدْنَا عَلَيْهِ ءَابَآءَنَآ࣌ أَوَلَوْ كَانَ ءَابَآؤُهُمْ لَا يَعْلَمُونَ شَيْـٔاࣰ وَلَا يَهْتَدُونَ࣌', 'وإذا قيل لهم تعالوا ࡴلى ما أنزل ࡰلله وإلى ࡰلرسول قالوا حسبنا ما وجدنا عليه ءاباءنا࣌ أولو كان ءاباؤهم لا يعلمون شيا ولا يهتدون࣌', NULL, 125, 'local:warsh-text.json'),
  ('warsh-5-107', 'warsh', 5, 107, 'يَٰٓأَيُّهَا ࡰ۬لذِينَ ءَامَنُواْ عَلَيْكُمُۥٓ أَنفُسَكُمْ࣌ لَا يَضُرُّكُم مَّن ضَلَّ إِذَا ࡰٜهْتَدَيْتُمُۥٓ࣌ إِلَى ࡰ۬للَّهِ مَرْجِعُكُمْ جَمِيعاࣰ فَيُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ࣌', 'يأيها ࡰلذين ءامنوا عليكم أنفسكم࣌ لا يضركم من ضل إذا ࡰهتديتم࣌ إلى ࡰلله مرجعكم جميعا فينبئكم بما كنتم تعملون࣌', NULL, 125, 'local:warsh-text.json'),
  ('warsh-5-108', 'warsh', 5, 108, '۞ يَٰٓأَيُّهَا ࡰ۬لذِينَ ءَامَنُواْ شَهَٰدَةُ بَيْنِكُمُۥٓ إِذَا حَضَرَ أَحَدَكُمُ ࡲ۬لْمَوْتُ حِينَ ࡰ۬لْوَصِيَّةِ ࡴٜثْنَٰنِ ذَوَا عَدْلࣲ مِّنكُمُۥٓ أَوَ اٰخَرَٰنِ مِنْ غَيْرِكُمُۥٓ إِنَ ࡰنتُمْ ضَرَبْتُمْ فِے ࡴ۬لَارْضِ فَأَصَٰبَتْكُم مُّصِيبَةُ ࡲ۬لْمَوْتِ࣌ تَحْبِسُونَهُمَا مِنۢ بَعْدِ ࡴ۬لصَّلَوٰةِ فَيُقْسِمَٰنِ بِاللَّهِ إِنِ ࡴٜرْتَبْتُمْ لَا نَشْتَرِے بِهِۦ ثَمَناࣰ وَلَوْ كَانَ ذَا قُرْبٜىٰ࣌ وَلَا نَكْتُمُ شَهَٰدَةَ ࡰ۬للَّهِ إِنَّآ إِذاࣰ لَّمِنَ ࡰ۬لَاثِمِينَ࣌', 'يأيها ࡰلذين ءامنوا شهدة بينكم إذا حضر أحدكم ࡲلموت حين ࡰلوصية ࡴثنن ذوا عدل منكم أو اخرن من غيركم إن ࡰنتم ضربتم فے ࡴلارض فأصبتكم مصيبة ࡲلموت࣌ تحبسونهما من بعد ࡴلصلوة فيقسمن بالله إن ࡴرتبتم لا نشترے به ثمنا ولو كان ذا قربى࣌ ولا نكتم شهدة ࡰلله إنا إذا لمن ࡰلاثمين࣌', NULL, 125, 'local:warsh-text.json'),
  ('warsh-5-109', 'warsh', 5, 109, 'فَإِنْ عُثِرَ عَلَىٰٓ أَنَّهُمَا ࡰٜسْتَحَقَّآ إِثْماࣰ فَـَٔاخَرَٰنِ يَقُومَٰنِ مَقَامَهُمَا مِنَ ࡰ۬لذِينَ ࡸَسْتُحِقَّ عَلَيْهِمُ ࡲ۬لَاوْلَيَٰنِ فَيُقْسِمَٰنِ࣌ بِاللَّهِ لَشَهَٰدَتُنَآ أَحَقُّ مِن شَهَٰدَتِهِمَا وَمَا ࡰٜعْتَدَيْنَآ࣌ إِنَّآ إِذاࣰ لَّمِنَ ࡰ۬لظَّٰلِمِينَ࣌', 'فإن عثر على أنهما ࡰستحقا إثما فاخرن يقومن مقامهما من ࡰلذين ࡸستحق عليهم ࡲلاولين فيقسمن࣌ بالله لشهدتنا أحق من شهدتهما وما ࡰعتدينا࣌ إنا إذا لمن ࡰلظلمين࣌', NULL, 125, 'local:warsh-text.json'),
  ('warsh-5-110', 'warsh', 5, 110, 'ذَٰلِكَ أَدْنٜىٰٓ أَنْ يَّاتُواْ بِالشَّهَٰدَةِ عَلَىٰ وَجْهِهَآ أَوْ يَخَافُوٓاْ أَن تُرَدَّ أَيْمَٰنُۢ بَعْدَ أَيْمَٰنِهِمْ࣌ وَاتَّقُواْ ࡲ۬للَّهَ࣌ وَاسْمَعُواْ࣌ وَاللَّهُ لَا يَهْدِے ࡴ۬لْقَوْمَ ࡰ۬لْفَٰسِقِينَ࣌', 'ذلك أدنى أن ياتوا بالشهدة على وجهها أو يخافوا أن ترد أيمن بعد أيمنهم࣌ واتقوا ࡲلله࣌ واسمعوا࣌ والله لا يهدے ࡴلقوم ࡰلفسقين࣌', NULL, 125, 'local:warsh-text.json'),
  ('warsh-5-111', 'warsh', 5, 111, 'يَوْمَ يَجْمَعُ ࡲ۬للَّهُ ࡲ۬لرُّسُلَ فَيَقُولُ مَاذَآ أُجِبْتُمْ࣌ قَالُواْ لَا عِلْمَ لَنَآ إِنَّكَ أَنتَ عَلَّٰمُ ࡲ۬لْغُيُوبِ࣌', 'يوم يجمع ࡲلله ࡲلرسل فيقول ماذا أجبتم࣌ قالوا لا علم لنا إنك أنت علم ࡲلغيوب࣌', NULL, 126, 'local:warsh-text.json'),
  ('warsh-5-112', 'warsh', 5, 112, 'إِذْ قَالَ ࡰ۬للَّهُ يَٰعِيسَى ࡰٜبْنَ مَرْيَمَ ࡸَذْكُرْ نِعْمَتِے عَلَيْكَ وَعَلَىٰ وَٰلِدَتِكَ إِذَ ࡰيَّدتُّكَ بِرُوحِ ࡴ۬لْقُدُسِ تُكَلِّمُ ࡲ۬لنَّاسَ فِے ࡴ۬لْمَهْدِ وَكَهْلاࣰ࣌ وَإِذْ عَلَّمْتُكَ ࡰ۬لْكِتَٰبَ وَالْحِكْمَةَ وَالتَّوْرٜيٰةَ وَالِانجِيلَ࣌ وَإِذْ تَخْلُقُ مِنَ ࡰ۬لطِّينِ كَهَيْـَٔةِ ࡴ۬لطَّيْرِ بِإِذْنِے فَتَنفُخُ فِيهَا فَتَكُونُ طَٰٓئِراَۢ بِإِذْنِے࣌ وَتُبْرِۓُ ࡲ۬لَاكْمَهَ وَالَابْرَصَ بِإِذْنِے࣌ وَإِذْ تُخْرِجُ ࡲ۬لْمَوْتٜىٰ بِإِذْنِے࣌ وَإِذْ كَفَفْتُ بَنِےٓ إِسْرَآءِيلَ عَنكَ إِذْ جِئْتَهُم بِالْبَيِّنَٰتِ فَقَالَ ࡰ۬لذِينَ كَفَرُواْ مِنْهُمُۥٓ إِنْ هَٰذَآ إِلَّا سِحْرࣱ مُّبِينࣱ࣌', 'إذ قال ࡰلله يعيسى ࡰبن مريم ࡸذكر نعمتے عليك وعلى ولدتك إذ ࡰيدتك بروح ࡴلقدس تكلم ࡲلناس فے ࡴلمهد وكهلا࣌ وإذ علمتك ࡰلكتب والحكمة والتورية والانجيل࣌ وإذ تخلق من ࡰلطين كهية ࡴلطير بإذنے فتنفخ فيها فتكون طئرا بإذنے࣌ وتبرے ࡲلاكمه والابرص بإذنے࣌ وإذ تخرج ࡲلموتى بإذنے࣌ وإذ كففت بنے إسراءيل عنك إذ جئتهم بالبينت فقال ࡰلذين كفروا منهم إن هذا إلا سحر مبين࣌', NULL, 126, 'local:warsh-text.json'),
  ('warsh-5-113', 'warsh', 5, 113, '۞ وَإِذَ ࡰوْحَيْتُ إِلَى ࡰ۬لْحَوَارِيِّۑنَ أَنَ اٰمِنُواْ بِے وَبِرَسُولِے࣌ قَالُوٓاْ ءَامَنَّا وَاشْهَدْ بِأَنَّنَا مُسْلِمُونَ࣌', 'وإذ ࡰوحيت إلى ࡰلحواريۑن أن امنوا بے وبرسولے࣌ قالوا ءامنا واشهد بأننا مسلمون࣌', NULL, 126, 'local:warsh-text.json'),
  ('warsh-5-114', 'warsh', 5, 114, 'إِذْ قَالَ ࡰ۬لْحَوَارِيُّونَ يَٰعِيسَى ࡰٜبْنَ مَرْيَمَ هَلْ يَسْتَطِيعُ رَبُّكَ أَنْ يُّنَزِّلَ عَلَيْنَا مَآئِدَةࣰ مِّنَ ࡰ۬لسَّمَآءِ࣌ قَالَ ࡰٜتَّقُواْ ࡲ۬للَّهَ إِن كُنتُم مُّومِنِينَ࣌', 'إذ قال ࡰلحواريون يعيسى ࡰبن مريم هل يستطيع ربك أن ينزل علينا مائدة من ࡰلسماء࣌ قال ࡰتقوا ࡲلله إن كنتم مومنين࣌', NULL, 126, 'local:warsh-text.json'),
  ('warsh-5-115', 'warsh', 5, 115, 'قَالُواْ نُرِيدُ أَن نَّاكُلَ مِنْهَا وَتَطْمَئِنَّ قُلُوبُنَا وَنَعْلَمَ أَن قَدْ صَدَقْتَنَا وَنَكُونَ عَلَيْهَا مِنَ ࡰ۬لشَّٰهِدِينَ࣌', 'قالوا نريد أن ناكل منها وتطمئن قلوبنا ونعلم أن قد صدقتنا ونكون عليها من ࡰلشهدين࣌', NULL, 126, 'local:warsh-text.json'),
  ('warsh-5-116', 'warsh', 5, 116, 'قَالَ عِيسَى ࡰٜبْنُ مَرْيَمَ ࡰ۬للَّهُمَّ رَبَّنَآ أَنزِلْ عَلَيْنَا مَآئِدَةࣰ مِّنَ ࡰ۬لسَّمَآءِ تَكُونُ لَنَا عِيداࣰ لِّأَوَّلِنَا وَءَاخِرِنَا وَءَايَةࣰ مِّنكَ࣌ وَارْزُقْنَا࣌ وَأَنتَ خَيْرُ ࡲ۬لرَّٰزِقِينَ࣌', 'قال عيسى ࡰبن مريم ࡰللهم ربنا أنزل علينا مائدة من ࡰلسماء تكون لنا عيدا لأولنا وءاخرنا وءاية منك࣌ وارزقنا࣌ وأنت خير ࡲلرزقين࣌', NULL, 127, 'local:warsh-text.json'),
  ('warsh-5-117', 'warsh', 5, 117, 'قَالَ ࡰ۬للَّهُ إِنِّے مُنَزِّلُهَا عَلَيْكُمْ فَمَنْ يَّكْفُرْ بَعْدُ مِنكُمْ فَإِنِّيَ أُعَذِّبُهُۥ عَذَاباࣰ لَّآ أُعَذِّبُهُۥٓ أَحَداࣰ مِّنَ ࡰ۬لْعَٰلَمِينَ࣌', 'قال ࡰلله إنے منزلها عليكم فمن يكفر بعد منكم فإني أعذبه عذابا لا أعذبه أحدا من ࡰلعلمين࣌', NULL, 127, 'local:warsh-text.json'),
  ('warsh-5-118', 'warsh', 5, 118, 'وَإِذْ قَالَ ࡰ۬للَّهُ يَٰعِيسَى ࡰٜبْنَ مَرْيَمَ ءَآنتَ قُلْتَ لِلنَّاسِ ࡴٜتَّخِذُونِے وَأُمِّيَ إِلَٰهَيْنِ مِن دُونِ ࡴ۬للَّهِ࣌ قَالَ سُبْحَٰنَكَ مَا يَكُونُ لِيَ أَنَ ࡰقُولَ مَا لَيْسَ لِے بِحَقٍّ࣌ ࡴن كُنتُ قُلْتُهُۥ فَقَدْ عَلِمْتَهُۥ࣌ تَعْلَمُ مَا فِے نَفْسِے وَلَآ أَعْلَمُ مَا فِے نَفْسِكَ࣌ إِنَّكَ أَنتَ عَلَّٰمُ ࡲ۬لْغُيُوبِ࣌', 'وإذ قال ࡰلله يعيسى ࡰبن مريم ءانت قلت للناس ࡴتخذونے وأمي إلهين من دون ࡴلله࣌ قال سبحنك ما يكون لي أن ࡰقول ما ليس لے بحق࣌ ࡴن كنت قلته فقد علمته࣌ تعلم ما فے نفسے ولا أعلم ما فے نفسك࣌ إنك أنت علم ࡲلغيوب࣌', NULL, 127, 'local:warsh-text.json'),
  ('warsh-5-119', 'warsh', 5, 119, 'مَا قُلْتُ لَهُمُۥٓ إِلَّا مَآ أَمَرْتَنِے بِهِۦٓ أَنُ ࡲ࢈عْبُدُواْ ࡲ۬للَّهَ رَبِّے وَرَبَّكُمْ࣌ وَكُنتُ عَلَيْهِمْ شَهِيداࣰ مَّا دُمْتُ فِيهِمْ࣌ فَلَمَّا تَوَفَّيْتَنِے كُنتَ أَنتَ ࡰ۬لرَّقِيبَ عَلَيْهِمْ࣌ وَأَنتَ عَلَىٰ كُلِّ شَےْءࣲ شَهِيدٌ࣌', 'ما قلت لهم إلا ما أمرتنے به أن ࡲ࢈عبدوا ࡲلله ربے وربكم࣌ وكنت عليهم شهيدا ما دمت فيهم࣌ فلما توفيتنے كنت أنت ࡰلرقيب عليهم࣌ وأنت على كل شےء شهيد࣌', NULL, 127, 'local:warsh-text.json'),
  ('warsh-5-120', 'warsh', 5, 120, 'ࡴن تُعَذِّبْهُمْ فَإِنَّهُمْ عِبَادُكَ࣌ وَإِن تَغْفِرْ لَهُمْ فَإِنَّكَ أَنتَ ࡰ۬لْعَزِيزُ ࡲ۬لْحَكِيمُ࣌', 'ࡴن تعذبهم فإنهم عبادك࣌ وإن تغفر لهم فإنك أنت ࡰلعزيز ࡲلحكيم࣌', NULL, 127, 'local:warsh-text.json'),
  ('warsh-5-121', 'warsh', 5, 121, 'قَالَ ࡰ۬للَّهُ هَٰذَا يَوْمَ يَنفَعُ ࡲ۬لصَّٰدِقِينَ صِدْقُهُمْ࣌ لَهُمْ جَنَّٰتࣱ تَجْرِے مِن تَحْتِهَا ࡰ۬لَانْهَٰرُ خَٰلِدِينَ فِيهَآ أَبَداࣰ࣌ رَّضِيَ ࡰ۬للَّهُ عَنْهُمْ وَرَضُواْ عَنْهُ࣌ ذَٰلِكَ ࡰ۬لْفَوْزُ ࡲ۬لْعَظِيمُ࣌', 'قال ࡰلله هذا يوم ينفع ࡲلصدقين صدقهم࣌ لهم جنت تجرے من تحتها ࡰلانهر خلدين فيها أبدا࣌ رضي ࡰلله عنهم ورضوا عنه࣌ ذلك ࡰلفوز ࡲلعظيم࣌', NULL, 127, 'local:warsh-text.json'),
  ('warsh-5-122', 'warsh', 5, 122, 'لِلهِ مُلْكُ ࡲ۬لسَّمَٰوَٰتِ وَالَارْضِ وَمَا فِيهِنَّ࣌ وَهُوَ عَلَىٰ كُلِّ شَےْءࣲ قَدِيرٌ࣌', 'لله ملك ࡲلسموت والارض وما فيهن࣌ وهو على كل شےء قدير࣌', NULL, 127, 'local:warsh-text.json'),
  ('warsh-6-1', 'warsh', 6, 1, 'ࡴ۬لْحَمْدُ لِلهِ ࡴ۬لذِے خَلَقَ ࡰ۬لسَّمَٰوَٰتِ وَالَارْضَ وَجَعَلَ ࡰ۬لظُّلُمَٰتِ وَالنُّورَ', 'ࡴلحمد لله ࡴلذے خلق ࡰلسموت والارض وجعل ࡰلظلمت والنور', NULL, 128, 'local:warsh-text.json'),
  ('warsh-6-2', 'warsh', 6, 2, 'ثُمَّ ࡰ۬لذِينَ كَفَرُواْ بِرَبِّهِمْ يَعْدِلُونَ࣌', 'ثم ࡰلذين كفروا بربهم يعدلون࣌', NULL, 128, 'local:warsh-text.json'),
  ('warsh-6-3', 'warsh', 6, 3, 'هُوَ ࡰ۬لذِے خَلَقَكُم مِّن طِينࣲ ثُمَّ قَضٜىٰٓ أَجَلاࣰ࣌ وَأَجَلࣱ مُّسَمّىً عِندَهُۥ࣌ ثُمَّ أَنتُمْ تَمْتَرُونَ࣌', 'هو ࡰلذے خلقكم من طين ثم قضى أجلا࣌ وأجل مسمى عنده࣌ ثم أنتم تمترون࣌', NULL, 128, 'local:warsh-text.json'),
  ('warsh-6-4', 'warsh', 6, 4, 'وَهُوَ ࡰ۬للَّهُ࣌ فِے ࡴ۬لسَّمَٰوَٰتِ وَفِے ࡴ۬لَارْضِ يَعْلَمُ سِرَّكُمْ وَجَهْرَكُمْ وَيَعْلَمُ مَا تَكْسِبُونَ࣌', 'وهو ࡰلله࣌ فے ࡴلسموت وفے ࡴلارض يعلم سركم وجهركم ويعلم ما تكسبون࣌', NULL, 128, 'local:warsh-text.json'),
  ('warsh-6-5', 'warsh', 6, 5, 'وَمَا تَاتِيهِم مِّنَ اٰيَةࣲ مِّنَ اٰيَٰتِ رَبِّهِمُۥٓ إِلَّا كَانُواْ عَنْهَا مُعْرِضِينَ࣌', 'وما تاتيهم من اية من ايت ربهم إلا كانوا عنها معرضين࣌', NULL, 128, 'local:warsh-text.json'),
  ('warsh-6-6', 'warsh', 6, 6, 'فَقَدْ كَذَّبُواْ بِالْحَقِّ لَمَّا جَآءَهُمْ࣌ فَسَوْفَ يَاتِيهِمُۥٓ أَنۢبَٰٓؤُاْ مَا كَانُواْ بِهِۦ يَسْتَهْزِءُونَ࣌', 'فقد كذبوا بالحق لما جاءهم࣌ فسوف ياتيهم أنبؤا ما كانوا به يستهزءون࣌', NULL, 128, 'local:warsh-text.json'),
  ('warsh-6-7', 'warsh', 6, 7, 'أَلَمْ يَرَوْاْ كَمَ ࡰهْلَكْنَا مِن قَبْلِهِم مِّن قَرْنࣲ مَّكَّنَّٰهُمْ فِے ࡴ۬لَارْضِ مَا لَمْ نُمَكِّن لَّكُمْ࣌ وَأَرْسَلْنَا ࡰ۬لسَّمَآءَ عَلَيْهِم مِّدْرَاراࣰ࣌ وَجَعَلْنَا ࡰ۬لَانْهَٰرَ تَجْرِے مِن تَحْتِهِمْ فَأَهْلَكْنَٰهُم بِذُنُوبِهِمْ࣌ وَأَنشَأْنَا مِنۢ بَعْدِهِمْ قَرْناً اٰخَرِينَ࣌', 'ألم يروا كم ࡰهلكنا من قبلهم من قرن مكنهم فے ࡴلارض ما لم نمكن لكم࣌ وأرسلنا ࡰلسماء عليهم مدرارا࣌ وجعلنا ࡰلانهر تجرے من تحتهم فأهلكنهم بذنوبهم࣌ وأنشأنا من بعدهم قرنا اخرين࣌', NULL, 128, 'local:warsh-text.json'),
  ('warsh-6-8', 'warsh', 6, 8, 'وَلَوْ نَزَّلْنَا عَلَيْكَ كِتَٰباࣰ فِے قِرْطَاسࣲ فَلَمَسُوهُ بِأَيْدِيهِمْ لَقَالَ ࡰ۬لذِينَ كَفَرُوٓاْ إِنْ هَٰذَآ إِلَّا سِحْرࣱ مُّبِينࣱ࣌', 'ولو نزلنا عليك كتبا فے قرطاس فلمسوه بأيديهم لقال ࡰلذين كفروا إن هذا إلا سحر مبين࣌', NULL, 128, 'local:warsh-text.json'),
  ('warsh-6-9', 'warsh', 6, 9, 'وَقَالُواْ لَوْلَآ أُنزِلَ عَلَيْهِ مَلَكࣱ࣌ وَلَوَ ࡰنزَلْنَا مَلَكاࣰ لَّقُضِيَ ࡰ۬لَامْرُ ثُمَّ لَا يُنظَرُونَ࣌', 'وقالوا لولا أنزل عليه ملك࣌ ولو ࡰنزلنا ملكا لقضي ࡰلامر ثم لا ينظرون࣌', NULL, 128, 'local:warsh-text.json'),
  ('warsh-6-10', 'warsh', 6, 10, 'وَلَوْ جَعَلْنَٰهُ مَلَكاࣰ لَّجَعَلْنَٰهُ رَجُلاࣰ وَلَلَبَسْنَا عَلَيْهِم مَّا يَلْبِسُونَ࣌', 'ولو جعلنه ملكا لجعلنه رجلا وللبسنا عليهم ما يلبسون࣌', NULL, 129, 'local:warsh-text.json'),
  ('warsh-6-11', 'warsh', 6, 11, 'وَلَقَدُ ࡲ࢈سْتُهْزِۓَ بِرُسُلࣲ مِّن قَبْلِكَ فَحَاقَ بِالذِينَ سَخِرُواْ مِنْهُم مَّا كَانُواْ بِهِۦ يَسْتَهْزِءُونَ࣌', 'ولقد ࡲ࢈ستهزے برسل من قبلك فحاق بالذين سخروا منهم ما كانوا به يستهزءون࣌', NULL, 129, 'local:warsh-text.json')
insert into public.ayahs (id, riwayah, surah_number, ayah_number, text, simple_text, juz, page, source) values
  ('warsh-6-12', 'warsh', 6, 12, 'قُلْ سِيرُواْ فِے ࡴ۬لَارْضِ ثُمَّ ࡸَنظُرُواْ كَيْفَ كَانَ عَٰقِبَةُ ࡲ۬لْمُكَذِّبِينَ࣌', 'قل سيروا فے ࡴلارض ثم ࡸنظروا كيف كان عقبة ࡲلمكذبين࣌', NULL, 129, 'local:warsh-text.json'),
  ('warsh-6-13', 'warsh', 6, 13, 'قُل لِّمَن مَّا فِے ࡴ۬لسَّمَٰوَٰتِ وَالَارْضِ قُل لِّلهِ࣌ كَتَبَ عَلَىٰ نَفْسِهِ ࡴ۬لرَّحْمَةَ࣌ لَيَجْمَعَنَّكُمُۥٓ إِلَىٰ يَوْمِ ࡴ۬لْقِيَٰمَةِ لَا رَيْبَ فِيهِ࣌ ࡴ۬لذِينَ خَسِرُوٓاْ أَنفُسَهُمْ فَهُمْ لَا يُومِنُونَ࣌', 'قل لمن ما فے ࡴلسموت والارض قل لله࣌ كتب على نفسه ࡴلرحمة࣌ ليجمعنكم إلى يوم ࡴلقيمة لا ريب فيه࣌ ࡴلذين خسروا أنفسهم فهم لا يومنون࣌', NULL, 129, 'local:warsh-text.json'),
  ('warsh-6-14', 'warsh', 6, 14, '۞ وَلَهُۥ مَا سَكَنَ فِے ࡴ۬ليْلِ وَالنَّهٜارِ࣌ وَهُوَ ࡰ۬لسَّمِيعُ ࡲ۬لْعَلِيمُ࣌', 'وله ما سكن فے ࡴليل والنهار࣌ وهو ࡰلسميع ࡲلعليم࣌', NULL, 129, 'local:warsh-text.json'),
  ('warsh-6-15', 'warsh', 6, 15, 'قُلَ ࡰغَيْرَ ࡰ۬للَّهِ أَتَّخِذُ وَلِيّاࣰ فَاطِرِ ࡴ۬لسَّمَٰوَٰتِ وَالَارْضِ࣌ وَهُوَ يُطْعِمُ وَلَا يُطْعَمُ࣌ قُلِ ࡴنِّيَ أُمِرْتُ أَنَ ࡰكُونَ أَوَّلَ مَنَ ࡰسْلَمَ࣌ وَلَا تَكُونَنَّ مِنَ ࡰ۬لْمُشْرِكِينَ࣌', 'قل ࡰغير ࡰلله أتخذ وليا فاطر ࡴلسموت والارض࣌ وهو يطعم ولا يطعم࣌ قل ࡴني أمرت أن ࡰكون أول من ࡰسلم࣌ ولا تكونن من ࡰلمشركين࣌', NULL, 129, 'local:warsh-text.json'),
  ('warsh-6-16', 'warsh', 6, 16, 'قُلِ ࡴنِّيَ أَخَافُ إِنْ عَصَيْتُ رَبِّے عَذَابَ يَوْمٍ عَظِيمࣲ࣌', 'قل ࡴني أخاف إن عصيت ربے عذاب يوم عظيم࣌', NULL, 129, 'local:warsh-text.json'),
  ('warsh-6-17', 'warsh', 6, 17, 'مَّنْ يُّصْرَفْ عَنْهُ يَوْمَئِذࣲ فَقَدْ رَحِمَهُۥ࣌ وَذَٰلِكَ ࡰ۬لْفَوْزُ ࡲ۬لْمُبِينُ࣌', 'من يصرف عنه يومئذ فقد رحمه࣌ وذلك ࡰلفوز ࡲلمبين࣌', NULL, 129, 'local:warsh-text.json'),
  ('warsh-6-18', 'warsh', 6, 18, 'وَإِنْ يَّمْسَسْكَ ࡰ۬للَّهُ بِضُرࣲّ فَلَا كَاشِفَ لَهُۥٓ إِلَّا هُوَ࣌ وَإِنْ يَّمْسَسْكَ بِخَيْرࣲ فَهُوَ عَلَىٰ كُلِّ شَےْءࣲ قَدِيرࣱ࣌', 'وإن يمسسك ࡰلله بضر فلا كاشف له إلا هو࣌ وإن يمسسك بخير فهو على كل شےء قدير࣌', NULL, 129, 'local:warsh-text.json'),
  ('warsh-6-19', 'warsh', 6, 19, 'وَهُوَ ࡰ۬لْقَاهِرُ فَوْقَ عِبَادِهِۦ࣌ وَهُوَ ࡰ۬لْحَكِيمُ ࡲ۬لْخَبِيرُ࣌', 'وهو ࡰلقاهر فوق عباده࣌ وهو ࡰلحكيم ࡲلخبير࣌', NULL, 129, 'local:warsh-text.json'),
  ('warsh-6-20', 'warsh', 6, 20, 'قُلَ ࡰيُّ شَےْءٍ ࡰكْبَرُ شَهَٰدَةࣰ قُلِ ࡴ۬للَّهُ࣌ شَهِيدُۢ بَيْنِے وَبَيْنَكُمْ࣌ وَأُوحِيَ إِلَيَّ هَٰذَا ࡰ۬لْقُرْءَانُ لِأُنذِرَكُم بِهِۦ وَمَنۢ بَلَغَ࣌ أَئِنَّكُمْ لَتَشْهَدُونَ أَنَّ مَعَ ࡰ۬للَّهِ ءَالِهَةً ࡳخْرٜىٰ قُل لَّآ أَشْهَدُ࣌ قُلِ ࡴنَّمَا هُوَ إِلَٰهࣱ وَٰحِدࣱ࣌ وَإِنَّنِے بَرِےٓءࣱ مِّمَّا تُشْرِكُونَ࣌', 'قل ࡰي شےء ࡰكبر شهدة قل ࡴلله࣌ شهيد بينے وبينكم࣌ وأوحي إلي هذا ࡰلقرءان لأنذركم به ومن بلغ࣌ أئنكم لتشهدون أن مع ࡰلله ءالهة ࡳخرى قل لا أشهد࣌ قل ࡴنما هو إله وحد࣌ وإننے برےء مما تشركون࣌', NULL, 130, 'local:warsh-text.json'),
  ('warsh-6-21', 'warsh', 6, 21, 'ࡰ۬لذِينَ ءَاتَيْنَٰهُمُ ࡲ۬لْكِتَٰبَ يَعْرِفُونَهُۥ كَمَا يَعْرِفُونَ أَبْنَآءَهُمُ࣌ ࡲ۬لذِينَ خَسِرُوٓاْ أَنفُسَهُمْ فَهُمْ لَا يُومِنُونَ࣌', 'ࡰلذين ءاتينهم ࡲلكتب يعرفونه كما يعرفون أبناءهم࣌ ࡲلذين خسروا أنفسهم فهم لا يومنون࣌', NULL, 130, 'local:warsh-text.json'),
  ('warsh-6-22', 'warsh', 6, 22, 'وَمَنَ ࡰظْلَمُ مِمَّنِ ࡴٜفْتَرٜىٰ عَلَى ࡰ۬للَّهِ كَذِباً ࡰوْ كَذَّبَ بِـَٔايَٰتِهِۦٓ࣌ إِنَّهُۥ لَا يُفْلِحُ ࡲ۬لظَّٰلِمُونَ࣌', 'ومن ࡰظلم ممن ࡴفترى على ࡰلله كذبا ࡰو كذب بايته࣌ إنه لا يفلح ࡲلظلمون࣌', NULL, 130, 'local:warsh-text.json'),
  ('warsh-6-23', 'warsh', 6, 23, 'وَيَوْمَ نَحْشُرُهُمْ جَمِيعاࣰ ثُمَّ نَقُولُ لِلذِينَ أَشْرَكُوٓاْ أَيْنَ شُرَكَآؤُكُمُ ࡲ۬لذِينَ كُنتُمْ تَزْعُمُونَ࣌', 'ويوم نحشرهم جميعا ثم نقول للذين أشركوا أين شركاؤكم ࡲلذين كنتم تزعمون࣌', NULL, 130, 'local:warsh-text.json'),
  ('warsh-6-24', 'warsh', 6, 24, 'ثُمَّ لَمْ تَكُن فِتْنَتَهُمُۥٓ إِلَّآ أَن قَالُواْ وَاللَّهِ رَبِّنَا مَا كُنَّا مُشْرِكِينَ࣌', 'ثم لم تكن فتنتهم إلا أن قالوا والله ربنا ما كنا مشركين࣌', NULL, 130, 'local:warsh-text.json'),
  ('warsh-6-25', 'warsh', 6, 25, 'ࡸَنظُرْ كَيْفَ كَذَبُواْ عَلَىٰٓ أَنفُسِهِمْ وَضَلَّ عَنْهُم مَّا كَانُواْ يَفْتَرُونَ࣌', 'ࡸنظر كيف كذبوا على أنفسهم وضل عنهم ما كانوا يفترون࣌', NULL, 130, 'local:warsh-text.json'),
  ('warsh-6-26', 'warsh', 6, 26, 'وَمِنْهُم مَّنْ يَّسْتَمِعُ إِلَيْكَ࣌ وَجَعَلْنَا عَلَىٰ قُلُوبِهِمُۥٓ أَكِنَّةً ࡰنْ يَّفْقَهُوهُ وَفِےٓ ءَاذَانِهِمْ وَقْراࣰ࣌ وَإِنْ يَّرَوْاْ كُلَّ ءَايَةࣲ لَّا يُومِنُواْ بِهَا࣌ حَتَّىٰٓ إِذَا جَآءُوكَ يُجَٰدِلُونَكَ يَقُولُ ࡲ۬لذِينَ كَفَرُوٓاْ إِنْ هَٰذَآ إِلَّآ أَسَٰطِيرُ ࡲ۬لَاوَّلِينَ࣌', 'ومنهم من يستمع إليك࣌ وجعلنا على قلوبهم أكنة ࡰن يفقهوه وفے ءاذانهم وقرا࣌ وإن يروا كل ءاية لا يومنوا بها࣌ حتى إذا جاءوك يجدلونك يقول ࡲلذين كفروا إن هذا إلا أسطير ࡲلاولين࣌', NULL, 130, 'local:warsh-text.json'),
  ('warsh-6-27', 'warsh', 6, 27, '۞ وَهُمْ يَنْهَوْنَ عَنْهُ وَيَنْـَٔوْنَ عَنْهُ࣌ وَإِنْ يُّهْلِكُونَ إِلَّآ أَنفُسَهُمْ وَمَا يَشْعُرُونَ࣌', 'وهم ينهون عنه وينون عنه࣌ وإن يهلكون إلا أنفسهم وما يشعرون࣌', NULL, 130, 'local:warsh-text.json'),
  ('warsh-6-28', 'warsh', 6, 28, 'وَلَوْ تَرٜىٰٓ إِذْ وُقِفُواْ عَلَى ࡰ۬لنّٜارِ فَقَالُواْ يَٰلَيْتَنَا نُرَدُّ࣌ وَلَا نُكَذِّبُ بِـَٔايَٰتِ رَبِّنَا وَنَكُونُ مِنَ ࡰ۬لْمُومِنِينَ࣌', 'ولو ترى إذ وقفوا على ࡰلنار فقالوا يليتنا نرد࣌ ولا نكذب بايت ربنا ونكون من ࡰلمومنين࣌', NULL, 130, 'local:warsh-text.json'),
  ('warsh-6-29', 'warsh', 6, 29, 'بَلْ بَدَا لَهُم مَّا كَانُواْ يُخْفُونَ مِن قَبْلُ࣌ وَلَوْ رُدُّواْ لَعَادُواْ لِمَا نُهُواْ عَنْهُ࣌ وَإِنَّهُمْ لَكَٰذِبُونَ࣌', 'بل بدا لهم ما كانوا يخفون من قبل࣌ ولو ردوا لعادوا لما نهوا عنه࣌ وإنهم لكذبون࣌', NULL, 131, 'local:warsh-text.json'),
  ('warsh-6-30', 'warsh', 6, 30, 'وَقَالُوٓاْ إِنْ هِيَ إِلَّا حَيَاتُنَا ࡰ۬لدُّنْيٜا وَمَا نَحْنُ بِمَبْعُوثِينَ࣌', 'وقالوا إن هي إلا حياتنا ࡰلدنيا وما نحن بمبعوثين࣌', NULL, 131, 'local:warsh-text.json'),
  ('warsh-6-31', 'warsh', 6, 31, 'وَلَوْ تَرٜىٰٓ إِذْ وُقِفُواْ عَلَىٰ رَبِّهِمْ قَالَ أَلَيْسَ هَٰذَا بِالْحَقِّ࣌ قَالُواْ بَلٜىٰ وَرَبِّنَا࣌ قَالَ فَذُوقُواْ ࡲ۬لْعَذَابَ بِمَا كُنتُمْ تَكْفُرُونَ࣌', 'ولو ترى إذ وقفوا على ربهم قال أليس هذا بالحق࣌ قالوا بلى وربنا࣌ قال فذوقوا ࡲلعذاب بما كنتم تكفرون࣌', NULL, 131, 'local:warsh-text.json'),
  ('warsh-6-32', 'warsh', 6, 32, 'قَدْ خَسِرَ ࡰ۬لذِينَ كَذَّبُواْ بِلِقَآءِ ࡴ۬للَّهِ حَتَّىٰٓ إِذَا جَآءَتْهُمُ ࡲ۬لسَّاعَةُ بَغْتَةࣰ قَالُواْ يَٰحَسْرَتَنَا عَلَىٰ مَا فَرَّطْنَا فِيهَا وَهُمْ يَحْمِلُونَ أَوْزَارَهُمْ عَلَىٰ ظُهُورِهِمُۥٓ࣌ أَلَا سَآءَ مَا يَزِرُونَ࣌', 'قد خسر ࡰلذين كذبوا بلقاء ࡴلله حتى إذا جاءتهم ࡲلساعة بغتة قالوا يحسرتنا على ما فرطنا فيها وهم يحملون أوزارهم على ظهورهم࣌ ألا ساء ما يزرون࣌', NULL, 131, 'local:warsh-text.json'),
  ('warsh-6-33', 'warsh', 6, 33, 'وَمَا ࡰ۬لْحَيَوٰةُ ࡲ۬لدُّنْيٜآ إِلَّا لَعِبࣱ وَلَهْوࣱ࣌ وَلَلدَّارُ ࡲ۬لَاخِرَةُ خَيْرࣱ لِّلذِينَ يَتَّقُونَ࣌ أَفَلَا تَعْقِلُونَ࣌', 'وما ࡰلحيوة ࡲلدنيا إلا لعب ولهو࣌ وللدار ࡲلاخرة خير للذين يتقون࣌ أفلا تعقلون࣌', NULL, 131, 'local:warsh-text.json'),
  ('warsh-6-34', 'warsh', 6, 34, 'قَدْ نَعْلَمُ إِنَّهُۥ لَيُحْزِنُكَ ࡰ۬لذِے يَقُولُونَ࣌ فَإِنَّهُمْ لَا يُكْذِبُونَكَ࣌ وَلَٰكِنَّ ࡰ۬لظَّٰلِمِينَ بِـَٔايَٰتِ ࡴ۬للَّهِ يَجْحَدُونَ࣌', 'قد نعلم إنه ليحزنك ࡰلذے يقولون࣌ فإنهم لا يكذبونك࣌ ولكن ࡰلظلمين بايت ࡴلله يجحدون࣌', NULL, 131, 'local:warsh-text.json'),
  ('warsh-6-35', 'warsh', 6, 35, 'وَلَقَدْ كُذِّبَتْ رُسُلࣱ مِّن قَبْلِكَ فَصَبَرُواْ عَلَىٰ مَا كُذِّبُواْ وَأُوذُواْ حَتَّىٰٓ أَتٜيٰهُمْ نَصْرُنَا࣌ وَلَا مُبَدِّلَ لِكَلِمَٰتِ ࡴ۬للَّهِ࣌ وَلَقَدْ جَآءَكَ مِن نَّبَإِےْ ࡴ۬لْمُرْسَلِينَ࣌', 'ولقد كذبت رسل من قبلك فصبروا على ما كذبوا وأوذوا حتى أتيهم نصرنا࣌ ولا مبدل لكلمت ࡴلله࣌ ولقد جاءك من نبإے ࡴلمرسلين࣌', NULL, 131, 'local:warsh-text.json'),
  ('warsh-6-36', 'warsh', 6, 36, 'وَإِن كَانَ كَبُرَ عَلَيْكَ إِعْرَاضُهُمْ فَإِنِ ࡴٜسْتَطَعْتَ أَن تَبْتَغِيَ نَفَقاࣰ فِے ࡴ۬لَارْضِ أَوْ سُلَّماࣰ فِے ࡴ۬لسَّمَآءِ فَتَاتِيَهُم بِـَٔايَةࣲ࣌ وَلَوْ شَآءَ ࡰ۬للَّهُ لَجَمَعَهُمْ عَلَى ࡰ۬لْهُدٜىٰ࣌ فَلَا تَكُونَنَّ مِنَ ࡰ۬لْجَٰهِلِينَ࣌', 'وإن كان كبر عليك إعراضهم فإن ࡴستطعت أن تبتغي نفقا فے ࡴلارض أو سلما فے ࡴلسماء فتاتيهم باية࣌ ولو شاء ࡰلله لجمعهم على ࡰلهدى࣌ فلا تكونن من ࡰلجهلين࣌', NULL, 131, 'local:warsh-text.json'),
  ('warsh-6-37', 'warsh', 6, 37, '۞ إِنَّمَا يَسْتَجِيبُ ࡲ۬لذِينَ يَسْمَعُونَ࣌ وَالْمَوْتٜىٰ يَبْعَثُهُمُ ࡲ۬للَّهُ࣌ ثُمَّ إِلَيْهِ يُرْجَعُونَ࣌', 'إنما يستجيب ࡲلذين يسمعون࣌ والموتى يبعثهم ࡲلله࣌ ثم إليه يرجعون࣌', NULL, 132, 'local:warsh-text.json'),
  ('warsh-6-38', 'warsh', 6, 38, 'وَقَالُواْ لَوْلَا نُزِّلَ عَلَيْهِ ءَايَةࣱ مِّن رَّبِّهِۦ࣌ قُلِ ࡴنَّ ࡰ۬للَّهَ قَادِرٌ عَلَىٰٓ أَنْ يُّنَزِّلَ ءَايَةࣰ࣌ وَلَٰكِنَّ أَكْثَرَهُمْ لَا يَعْلَمُونَ࣌', 'وقالوا لولا نزل عليه ءاية من ربه࣌ قل ࡴن ࡰلله قادر على أن ينزل ءاية࣌ ولكن أكثرهم لا يعلمون࣌', NULL, 132, 'local:warsh-text.json'),
  ('warsh-6-39', 'warsh', 6, 39, 'وَمَا مِن دَآبَّةࣲ فِے ࡴ۬لَارْضِ وَلَا طَٰٓئِرࣲ يَطِيرُ بِجَنَاحَيْهِ إِلَّآ أُمَمٌ ࡰمْثَالُكُم࣌ مَّا فَرَّطْنَا فِے ࡴ۬لْكِتَٰبِ مِن شَےْءࣲ࣌ ثُمَّ إِلَىٰ رَبِّهِمْ يُحْشَرُونَ࣌', 'وما من دابة فے ࡴلارض ولا طئر يطير بجناحيه إلا أمم ࡰمثالكم࣌ ما فرطنا فے ࡴلكتب من شےء࣌ ثم إلى ربهم يحشرون࣌', NULL, 132, 'local:warsh-text.json'),
  ('warsh-6-40', 'warsh', 6, 40, 'وَالذِينَ كَذَّبُواْ بِـَٔايَٰتِنَا صُمࣱّ وَبُكْمࣱ فِے ࡴ۬لظُّلُمَٰتِ࣌ مَنْ يَّشَإِ ࡴ۬للَّهُ يُضْلِلْهُ࣌ وَمَنْ يَّشَأْ يَجْعَلْهُ عَلَىٰ صِرَٰطࣲ مُّسْتَقِيمࣲ࣌', 'والذين كذبوا بايتنا صم وبكم فے ࡴلظلمت࣌ من يشإ ࡴلله يضلله࣌ ومن يشأ يجعله على صرط مستقيم࣌', NULL, 132, 'local:warsh-text.json'),
  ('warsh-6-41', 'warsh', 6, 41, 'قُلَ ࡰرَٰٓيْتَكُمُۥٓ إِنَ ࡰتٜيٰكُمْ عَذَابُ ࡲ۬للَّهِ أَوَ ࡰتَتْكُمُ ࡲ۬لسَّاعَةُ أَغَيْرَ ࡰ۬للَّهِ تَدْعُونَ إِن كُنتُمْ صَٰدِقِينَ࣌', 'قل ࡰريتكم إن ࡰتيكم عذاب ࡲلله أو ࡰتتكم ࡲلساعة أغير ࡰلله تدعون إن كنتم صدقين࣌', NULL, 132, 'local:warsh-text.json'),
  ('warsh-6-42', 'warsh', 6, 42, 'بَلِ ࡴيَّاهُ تَدْعُونَ فَيَكْشِفُ مَا تَدْعُونَ إِلَيْهِ إِن شَآءَ وَتَنسَوْنَ مَا تُشْرِكُونَ࣌', 'بل ࡴياه تدعون فيكشف ما تدعون إليه إن شاء وتنسون ما تشركون࣌', NULL, 132, 'local:warsh-text.json'),
  ('warsh-6-43', 'warsh', 6, 43, 'وَلَقَدَ ࡰرْسَلْنَآ إِلَىٰٓ أُمَمࣲ مِّن قَبْلِكَ فَأَخَذْنَٰهُم بِالْبَأْسَآءِ وَالضَّرَّآءِ لَعَلَّهُمْ يَتَضَرَّعُونَ࣌', 'ولقد ࡰرسلنا إلى أمم من قبلك فأخذنهم بالبأساء والضراء لعلهم يتضرعون࣌', NULL, 132, 'local:warsh-text.json'),
  ('warsh-6-44', 'warsh', 6, 44, 'فَلَوْلَآ إِذْ جَآءَهُم بَأْسُنَا تَضَرَّعُواْ࣌ وَلَٰكِن قَسَتْ قُلُوبُهُمْ وَزَيَّنَ لَهُمُ ࡲ۬لشَّيْطَٰنُ مَا كَانُواْ يَعْمَلُونَ࣌', 'فلولا إذ جاءهم بأسنا تضرعوا࣌ ولكن قست قلوبهم وزين لهم ࡲلشيطن ما كانوا يعملون࣌', NULL, 132, 'local:warsh-text.json'),
  ('warsh-6-45', 'warsh', 6, 45, 'فَلَمَّا نَسُواْ مَا ذُكِّرُواْ بِهِۦ فَتَحْنَا عَلَيْهِمُۥٓ أَبْوَٰبَ كُلِّ شَےْءٍ࣌ حَتَّىٰٓ إِذَا فَرِحُواْ بِمَآ أُوتُوٓاْ أَخَذْنَٰهُم بَغْتَةࣰ فَإِذَا هُم مُّبْلِسُونَ࣌', 'فلما نسوا ما ذكروا به فتحنا عليهم أبوب كل شےء࣌ حتى إذا فرحوا بما أوتوا أخذنهم بغتة فإذا هم مبلسون࣌', NULL, 132, 'local:warsh-text.json'),
  ('warsh-6-46', 'warsh', 6, 46, 'فَقُطِعَ دَابِرُ ࡲ۬لْقَوْمِ ࡴ۬لذِينَ ظَلَمُواْ࣌ وَالْحَمْدُ لِلهِ رَبِّ ࡴ۬لْعَٰلَمِينَ࣌', 'فقطع دابر ࡲلقوم ࡴلذين ظلموا࣌ والحمد لله رب ࡴلعلمين࣌', NULL, 133, 'local:warsh-text.json'),
  ('warsh-6-47', 'warsh', 6, 47, 'قُلَ ࡰرَٰٓيْتُمُۥٓ إِنَ ࡰخَذَ ࡰ۬للَّهُ سَمْعَكُمْ وَأَبْصَٰرَكُمْ وَخَتَمَ عَلَىٰ قُلُوبِكُم مَّنِ ࡴلَٰهٌ غَيْرُ ࡲ۬للَّهِ يَاتِيكُم بِهِ࣌ ࡴ࢈نظُرْ كَيْفَ نُصَرِّفُ ࡲ۬لَايَٰتِ ثُمَّ هُمْ يَصْدِفُونَ࣌', 'قل ࡰريتم إن ࡰخذ ࡰلله سمعكم وأبصركم وختم على قلوبكم من ࡴله غير ࡲلله ياتيكم به࣌ ࡴ࢈نظر كيف نصرف ࡲلايت ثم هم يصدفون࣌', NULL, 133, 'local:warsh-text.json'),
  ('warsh-6-48', 'warsh', 6, 48, 'قُلَ ࡰرَٰٓيْتَكُمُۥٓ إِنَ ࡰتٜيٰكُمْ عَذَابُ ࡲ۬للَّهِ بَغْتَةً ࡰوْ جَهْرَةً هَلْ يُهْلَكُ إِلَّا ࡰ۬لْقَوْمُ ࡲ۬لظَّٰلِمُونَ࣌', 'قل ࡰريتكم إن ࡰتيكم عذاب ࡲلله بغتة ࡰو جهرة هل يهلك إلا ࡰلقوم ࡲلظلمون࣌', NULL, 133, 'local:warsh-text.json'),
  ('warsh-6-49', 'warsh', 6, 49, '۞ وَمَا نُرْسِلُ ࡲ۬لْمُرْسَلِينَ إِلَّا مُبَشِّرِينَ وَمُنذِرِينَ࣌ فَمَنَ اٰمَنَ وَأَصْلَحَ فَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ࣌', 'وما نرسل ࡲلمرسلين إلا مبشرين ومنذرين࣌ فمن امن وأصلح فلا خوف عليهم ولا هم يحزنون࣌', NULL, 133, 'local:warsh-text.json'),
  ('warsh-6-50', 'warsh', 6, 50, 'وَالذِينَ كَذَّبُواْ بِـَٔايَٰتِنَا يَمَسُّهُمُ ࡲ۬لْعَذَابُ بِمَا كَانُواْ يَفْسُقُونَ࣌', 'والذين كذبوا بايتنا يمسهم ࡲلعذاب بما كانوا يفسقون࣌', NULL, 133, 'local:warsh-text.json'),
  ('warsh-6-51', 'warsh', 6, 51, 'قُل لَّآ أَقُولُ لَكُمْ عِندِے خَزَآئِنُ ࡲ۬للَّهِ وَلَآ أَعْلَمُ ࡲ۬لْغَيْبَ وَلَآ أَقُولُ لَكُمُۥٓ إِنِّے مَلَكٌ࣌ ࡴنَ ࡰتَّبِعُ إِلَّا مَا يُوحٜىٰٓ إِلَيَّ࣌ قُلْ هَلْ يَسْتَوِے ࡴ۬لَاعْمٜىٰ وَالْبَصِيرُ࣌ أَفَلَا تَتَفَكَّرُونَ࣌', 'قل لا أقول لكم عندے خزائن ࡲلله ولا أعلم ࡲلغيب ولا أقول لكم إنے ملك࣌ ࡴن ࡰتبع إلا ما يوحى إلي࣌ قل هل يستوے ࡴلاعمى والبصير࣌ أفلا تتفكرون࣌', NULL, 133, 'local:warsh-text.json'),
  ('warsh-6-52', 'warsh', 6, 52, 'وَأَنذِرْ بِهِ ࡴ۬لذِينَ يَخَافُونَ أَنْ يُّحْشَرُوٓاْ إِلَىٰ رَبِّهِمْ لَيْسَ لَهُم مِّن دُونِهِۦ وَلِيࣱّ وَلَا شَفِيعࣱ لَّعَلَّهُمْ يَتَّقُونَ࣌', 'وأنذر به ࡴلذين يخافون أن يحشروا إلى ربهم ليس لهم من دونه ولي ولا شفيع لعلهم يتقون࣌', NULL, 133, 'local:warsh-text.json'),
  ('warsh-6-53', 'warsh', 6, 53, 'وَلَا تَطْرُدِ ࡴ۬لذِينَ يَدْعُونَ رَبَّهُم بِالْغَدَوٰةِ وَالْعَشِيِّ يُرِيدُونَ وَجْهَهُۥ مَا عَلَيْكَ مِنْ حِسَابِهِم مِّن شَےْءࣲ وَمَا مِنْ حِسَابِكَ عَلَيْهِم مِّن شَےْءࣲ فَتَطْرُدَهُمْ فَتَكُونَ مِنَ ࡰ۬لظَّٰلِمِينَ࣌', 'ولا تطرد ࡴلذين يدعون ربهم بالغدوة والعشي يريدون وجهه ما عليك من حسابهم من شےء وما من حسابك عليهم من شےء فتطردهم فتكون من ࡰلظلمين࣌', NULL, 133, 'local:warsh-text.json'),
  ('warsh-6-54', 'warsh', 6, 54, 'وَكَذَٰلِكَ فَتَنَّا بَعْضَهُم بِبَعْضࣲ لِّيَقُولُوٓاْ أَهَٰٓؤُلَآءِ مَنَّ ࡰ۬للَّهُ عَلَيْهِم مِّنۢ بَيْنِنَآ࣌ أَلَيْسَ ࡰ۬للَّهُ بِأَعْلَمَ بِالشَّٰكِرِينَ࣌', 'وكذلك فتنا بعضهم ببعض ليقولوا أهؤلاء من ࡰلله عليهم من بيننا࣌ أليس ࡰلله بأعلم بالشكرين࣌', NULL, 134, 'local:warsh-text.json'),
  ('warsh-6-55', 'warsh', 6, 55, 'وَإِذَا جَآءَكَ ࡰ۬لذِينَ يُومِنُونَ بِـَٔايَٰتِنَا فَقُلْ سَلَٰمٌ عَلَيْكُمْ࣌ كَتَبَ رَبُّكُمْ عَلَىٰ نَفْسِهِ ࡴ۬لرَّحْمَةَ أَنَّهُۥ مَنْ عَمِلَ مِنكُمْ سُوٓءاَۢ بِجَهَٰلَةࣲ ثُمَّ تَابَ مِنۢ بَعْدِهِۦ وَأَصْلَحَ فَإِنَّهُۥ غَفُورࣱ رَّحِيمࣱ࣌', 'وإذا جاءك ࡰلذين يومنون بايتنا فقل سلم عليكم࣌ كتب ربكم على نفسه ࡴلرحمة أنه من عمل منكم سوءا بجهلة ثم تاب من بعده وأصلح فإنه غفور رحيم࣌', NULL, 134, 'local:warsh-text.json'),
  ('warsh-6-56', 'warsh', 6, 56, 'وَكَذَٰلِكَ نُفَصِّلُ ࡲ۬لَايَٰتِ وَلِتَسْتَبِينَ سَبِيلَ ࡰ۬لْمُجْرِمِينَ࣌', 'وكذلك نفصل ࡲلايت ولتستبين سبيل ࡰلمجرمين࣌', NULL, 134, 'local:warsh-text.json'),
  ('warsh-6-57', 'warsh', 6, 57, 'قُلِ ࡴنِّے نُهِيتُ أَنَ ࡰعْبُدَ ࡰ۬لذِينَ تَدْعُونَ مِن دُونِ ࡴ۬للَّهِ࣌ قُل لَّآ أَتَّبِعُ أَهْوَآءَكُمْ࣌ قَد ضَّلَلْتُ إِذاࣰ وَمَآ أَنَا مِنَ ࡰ۬لْمُهْتَدِينَ࣌', 'قل ࡴنے نهيت أن ࡰعبد ࡰلذين تدعون من دون ࡴلله࣌ قل لا أتبع أهواءكم࣌ قد ضللت إذا وما أنا من ࡰلمهتدين࣌', NULL, 134, 'local:warsh-text.json'),
  ('warsh-6-58', 'warsh', 6, 58, 'قُلِ ࡴنِّے عَلَىٰ بَيِّنَةࣲ مِّن رَّبِّے وَكَذَّبْتُم بِهِۦ࣌ مَا عِندِے مَا تَسْتَعْجِلُونَ بِهِۦٓ࣌ إِنِ ࡴ۬لْحُكْمُ إِلَّا لِلهِ࣌ يَقُصُّ ࡲ۬لْحَقَّ࣌ وَهُوَ خَيْرُ ࡲ۬لْفَٰصِلِينَ࣌', 'قل ࡴنے على بينة من ربے وكذبتم به࣌ ما عندے ما تستعجلون به࣌ إن ࡴلحكم إلا لله࣌ يقص ࡲلحق࣌ وهو خير ࡲلفصلين࣌', NULL, 134, 'local:warsh-text.json'),
  ('warsh-6-59', 'warsh', 6, 59, 'قُل لَّوَ ࡰنَّ عِندِے مَا تَسْتَعْجِلُونَ بِهِۦ لَقُضِيَ ࡰ۬لَامْرُ بَيْنِے وَبَيْنَكُمْ࣌ وَاللَّهُ أَعْلَمُ بِالظَّٰلِمِينَ࣌', 'قل لو ࡰن عندے ما تستعجلون به لقضي ࡰلامر بينے وبينكم࣌ والله أعلم بالظلمين࣌', NULL, 134, 'local:warsh-text.json'),
  ('warsh-6-60', 'warsh', 6, 60, '۞ وَعِندَهُۥ مَفَاتِحُ ࡲ۬لْغَيْبِ لَا يَعْلَمُهَآ إِلَّا هُوَ࣌ وَيَعْلَمُ مَا فِے ࡴ۬لْبَرِّ وَالْبَحْرِ࣌ وَمَا تَسْقُطُ مِنْ وَّرَقَةٍ ࡴلَّا يَعْلَمُهَا وَلَا حَبَّةࣲ فِے ظُلُمَٰتِ ࡴ۬لَارْضِ وَلَا رَطْبࣲ وَلَا يَابِسٍ ࡴلَّا فِے كِتَٰبࣲ مُّبِينࣲ࣌', 'وعنده مفاتح ࡲلغيب لا يعلمها إلا هو࣌ ويعلم ما فے ࡴلبر والبحر࣌ وما تسقط من ورقة ࡴلا يعلمها ولا حبة فے ظلمت ࡴلارض ولا رطب ولا يابس ࡴلا فے كتب مبين࣌', NULL, 134, 'local:warsh-text.json'),
  ('warsh-6-61', 'warsh', 6, 61, 'وَهُوَ ࡰ۬لذِے يَتَوَفّٜيٰكُم بِاليْلِ وَيَعْلَمُ مَا جَرَحْتُم بِالنَّهٜارِ ثُمَّ يَبْعَثُكُمْ فِيهِ لِيُقْضٜىٰٓ أَجَلࣱ مُّسَمّىࣰ࣌ ثُمَّ إِلَيْهِ مَرْجِعُكُمْ ثُمَّ يُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ࣌', 'وهو ࡰلذے يتوفيكم باليل ويعلم ما جرحتم بالنهار ثم يبعثكم فيه ليقضى أجل مسمى࣌ ثم إليه مرجعكم ثم ينبئكم بما كنتم تعملون࣌', NULL, 135, 'local:warsh-text.json'),
  ('warsh-6-62', 'warsh', 6, 62, 'وَهُوَ ࡰ۬لْقَاهِرُ فَوْقَ عِبَادِهِۦ࣌ وَيُرْسِلُ عَلَيْكُمْ حَفَظَةً࣌ حَتَّىٰٓ إِذَا جَآءَ احَدَكُمُ ࡲ۬لْمَوْتُ تَوَفَّتْهُ رُسُلُنَا وَهُمْ لَا يُفَرِّطُونَ࣌', 'وهو ࡰلقاهر فوق عباده࣌ ويرسل عليكم حفظة࣌ حتى إذا جاء احدكم ࡲلموت توفته رسلنا وهم لا يفرطون࣌', NULL, 135, 'local:warsh-text.json'),
  ('warsh-6-63', 'warsh', 6, 63, 'ثُمَّ رُدُّوٓاْ إِلَى ࡰ۬للَّهِ مَوْلٜيٰهُمُ ࡲ۬لْحَقِّ࣌ أَلَا لَهُ ࡲ۬لْحُكْمُ࣌ وَهُوَ أَسْرَعُ ࡲ۬لْحَٰسِبِينَ࣌', 'ثم ردوا إلى ࡰلله موليهم ࡲلحق࣌ ألا له ࡲلحكم࣌ وهو أسرع ࡲلحسبين࣌', NULL, 135, 'local:warsh-text.json'),
  ('warsh-6-64', 'warsh', 6, 64, 'قُلْ مَنْ يُّنَجِّيكُم مِّن ظُلُمَٰتِ ࡴ۬لْبَرِّ وَالْبَحْرِ تَدْعُونَهُۥ تَضَرُّعاࣰ وَخُفْيَةࣰ لَّئِنَ ࡰنجَيْتَنَا مِنْ هَٰذِهِۦ لَنَكُونَنَّ مِنَ ࡰ۬لشَّٰكِرِينَ࣌', 'قل من ينجيكم من ظلمت ࡴلبر والبحر تدعونه تضرعا وخفية لئن ࡰنجيتنا من هذه لنكونن من ࡰلشكرين࣌', NULL, 135, 'local:warsh-text.json'),
  ('warsh-6-65', 'warsh', 6, 65, 'قُلِ ࡴ۬للَّهُ يُنجِيكُم مِّنْهَا وَمِن كُلِّ كَرْبࣲ ثُمَّ أَنتُمْ تُشْرِكُونَ࣌', 'قل ࡴلله ينجيكم منها ومن كل كرب ثم أنتم تشركون࣌', NULL, 135, 'local:warsh-text.json'),
  ('warsh-6-66', 'warsh', 6, 66, 'قُلْ هُوَ ࡰ۬لْقَادِرُ عَلَىٰٓ أَنْ يَّبْعَثَ عَلَيْكُمْ عَذَاباࣰ مِّن فَوْقِكُمُۥٓ أَوْ مِن تَحْتِ أَرْجُلِكُمُۥٓ أَوْ يَلْبِسَكُمْ شِيَعاࣰ وَيُذِيقَ بَعْضَكُم بَأْسَ بَعْضٍ࣌ ࡲ࢈نظُرْ كَيْفَ نُصَرِّفُ ࡲ۬لَايَٰتِ لَعَلَّهُمْ يَفْقَهُونَ࣌', 'قل هو ࡰلقادر على أن يبعث عليكم عذابا من فوقكم أو من تحت أرجلكم أو يلبسكم شيعا ويذيق بعضكم بأس بعض࣌ ࡲ࢈نظر كيف نصرف ࡲلايت لعلهم يفقهون࣌', NULL, 135, 'local:warsh-text.json'),
  ('warsh-6-67', 'warsh', 6, 67, 'وَكَذَّبَ بِهِۦ قَوْمُكَ وَهُوَ ࡰ۬لْحَقُّ࣌ قُل لَّسْتُ عَلَيْكُم بِوَكِيلࣲ࣌ لِّكُلِّ نَبَإࣲ مُّسْتَقَرࣱّ࣌ وَسَوْفَ تَعْلَمُونَ࣌', 'وكذب به قومك وهو ࡰلحق࣌ قل لست عليكم بوكيل࣌ لكل نبإ مستقر࣌ وسوف تعلمون࣌', NULL, 135, 'local:warsh-text.json'),
  ('warsh-6-68', 'warsh', 6, 68, 'وَإِذَا رَأَيْتَ ࡰ۬لذِينَ يَخُوضُونَ فِےٓ ءَايَٰتِنَا فَأَعْرِضْ عَنْهُمْ حَتَّىٰ يَخُوضُواْ فِے حَدِيثٍ غَيْرِهِۦ࣌ وَإِمَّا يُنسِيَنَّكَ ࡰ۬لشَّيْطَٰنُ فَلَا تَقْعُدْ بَعْدَ ࡰ۬لذِّكْرٜىٰ مَعَ ࡰ۬لْقَوْمِ ࡴ۬لظَّٰلِمِينَ࣌', 'وإذا رأيت ࡰلذين يخوضون فے ءايتنا فأعرض عنهم حتى يخوضوا فے حديث غيره࣌ وإما ينسينك ࡰلشيطن فلا تقعد بعد ࡰلذكرى مع ࡰلقوم ࡴلظلمين࣌', NULL, 135, 'local:warsh-text.json'),
  ('warsh-6-69', 'warsh', 6, 69, 'وَمَا عَلَى ࡰ۬لذِينَ يَتَّقُونَ مِنْ حِسَابِهِم مِّن شَےْءࣲ࣌ وَلَٰكِن ذِكْرٜىٰ لَعَلَّهُمْ يَتَّقُونَ࣌', 'وما على ࡰلذين يتقون من حسابهم من شےء࣌ ولكن ذكرى لعلهم يتقون࣌', NULL, 136, 'local:warsh-text.json'),
  ('warsh-6-70', 'warsh', 6, 70, '۞ وَذَرِ ࡴ۬لذِينَ ࡰٜتَّخَذُواْ دِينَهُمْ لَعِباࣰ وَلَهْواࣰ وَغَرَّتْهُمُ ࡲ۬لْحَيَوٰةُ ࡲ۬لدُّنْيٜا࣌ وَذَكِّرْ بِهِۦٓ أَن تُبْسَلَ نَفْسُۢ بِمَا كَسَبَتْ لَيْسَ لَهَا مِن دُونِ ࡴ۬للَّهِ وَلِيࣱّ وَلَا شَفِيعࣱ࣌ وَإِن تَعْدِلْ كُلَّ عَدْلࣲ لَّا يُوخَذْ مِنْهَآ࣌ أُوْلَٰٓئِكَ ࡰ۬لذِينَ أُبْسِلُواْ بِمَا كَسَبُواْ لَهُمْ شَرَابࣱ مِّنْ حَمِيمࣲ وَعَذَابٌ ࡰلِيمُۢ بِمَا كَانُواْ يَكْفُرُونَ࣌', 'وذر ࡴلذين ࡰتخذوا دينهم لعبا ولهوا وغرتهم ࡲلحيوة ࡲلدنيا࣌ وذكر به أن تبسل نفس بما كسبت ليس لها من دون ࡴلله ولي ولا شفيع࣌ وإن تعدل كل عدل لا يوخذ منها࣌ أولئك ࡰلذين أبسلوا بما كسبوا لهم شراب من حميم وعذاب ࡰليم بما كانوا يكفرون࣌', NULL, 136, 'local:warsh-text.json'),
  ('warsh-6-71', 'warsh', 6, 71, 'قُلَ ࡰنَدْعُواْ مِن دُونِ ࡴ۬للَّهِ مَا لَا يَنفَعُنَا وَلَا يَضُرُّنَا وَنُرَدُّ عَلَىٰٓ أَعْقَابِنَا بَعْدَ إِذْ هَدٜيٰنَا ࡰ۬للَّهُ كَالذِے ࡴٜسْتَهْوَتْهُ ࡲ۬لشَّيَٰطِينُ فِے ࡴ۬لَارْضِ حَيْرَانَ࣌ لَهُۥٓ أَصْحَٰبࣱ يَدْعُونَهُۥٓ إِلَى ࡰ۬لْهُدَى ࡰٜيتِنَا࣌ قُلِ ࡴنَّ هُدَى ࡰ۬للَّهِ هُوَ ࡰ۬لْهُدٜىٰ وَأُمِرْنَا لِنُسْلِمَ لِرَبِّ ࡴ۬لْعَٰلَمِينَ', 'قل ࡰندعوا من دون ࡴلله ما لا ينفعنا ولا يضرنا ونرد على أعقابنا بعد إذ هدينا ࡰلله كالذے ࡴستهوته ࡲلشيطين فے ࡴلارض حيران࣌ له أصحب يدعونه إلى ࡰلهدى ࡰيتنا࣌ قل ࡴن هدى ࡰلله هو ࡰلهدى وأمرنا لنسلم لرب ࡴلعلمين', NULL, 136, 'local:warsh-text.json'),
  ('warsh-6-72', 'warsh', 6, 72, 'وَأَنَ ࡰقِيمُواْ ࡲ۬لصَّلَوٰةَ وَاتَّقُوهُ࣌ وَهُوَ ࡰ۬لذِےٓ إِلَيْهِ تُحْشَرُونَ࣌', 'وأن ࡰقيموا ࡲلصلوة واتقوه࣌ وهو ࡰلذے إليه تحشرون࣌', NULL, 136, 'local:warsh-text.json'),
  ('warsh-6-73', 'warsh', 6, 73, 'وَهُوَ ࡰ۬لذِے خَلَقَ ࡰ۬لسَّمَٰوَٰتِ وَالَارْضَ بِالْحَقِّ࣌ وَيَوْمَ يَقُولُ كُن࣌ فَيَكُونُ࣌', 'وهو ࡰلذے خلق ࡰلسموت والارض بالحق࣌ ويوم يقول كن࣌ فيكون࣌', NULL, 136, 'local:warsh-text.json'),
  ('warsh-6-74', 'warsh', 6, 74, 'قَوْلُهُ ࡲ۬لْحَقُّ࣌ وَلَهُ ࡲ۬لْمُلْكُ࣌ يَوْمَ يُنفَخُ فِے ࡴ۬لصُّورِ࣌ عَٰلِمُ ࡲ۬لْغَيْبِ وَالشَّهَٰدَةِ࣌ وَهُوَ ࡰ۬لْحَكِيمُ ࡲ۬لْخَبِيرُ࣌', 'قوله ࡲلحق࣌ وله ࡲلملك࣌ يوم ينفخ فے ࡴلصور࣌ علم ࡲلغيب والشهدة࣌ وهو ࡰلحكيم ࡲلخبير࣌', NULL, 136, 'local:warsh-text.json'),
  ('warsh-6-75', 'warsh', 6, 75, 'وَإِذْ قَالَ إِبْرَٰهِيمُ لِأَبِيهِ ءَازَرَ أَتَتَّخِذُ أَصْنَاماً اٰلِهَةً࣌ ࡴنِّيَ أَرٜيٰكَ وَقَوْمَكَ فِے ضَلَٰلࣲ مُّبِينࣲ࣌', 'وإذ قال إبرهيم لأبيه ءازر أتتخذ أصناما الهة࣌ ࡴني أريك وقومك فے ضلل مبين࣌', NULL, 137, 'local:warsh-text.json'),
  ('warsh-6-76', 'warsh', 6, 76, 'وَكَذَٰلِكَ نُرِےٓ إِبْرَٰهِيمَ مَلَكُوتَ ࡰ۬لسَّمَٰوَٰتِ وَالَارْضِ وَلِيَكُونَ مِنَ ࡰ۬لْمُوقِنِينَ࣌', 'وكذلك نرے إبرهيم ملكوت ࡰلسموت والارض وليكون من ࡰلموقنين࣌', NULL, 137, 'local:warsh-text.json'),
  ('warsh-6-77', 'warsh', 6, 77, 'فَلَمَّا جَنَّ عَلَيْهِ ࡴ۬ليْلُ رٜءٜا كَوْكَباࣰ قَالَ هَٰذَا رَبِّے࣌ فَلَمَّآ أَفَلَ قَالَ لَآ أُحِبُّ ࡲ۬لَافِلِينَ࣌', 'فلما جن عليه ࡴليل رءا كوكبا قال هذا ربے࣌ فلما أفل قال لا أحب ࡲلافلين࣌', NULL, 137, 'local:warsh-text.json'),
  ('warsh-6-78', 'warsh', 6, 78, 'فَلَمَّا رَءَا ࡰ۬لْقَمَرَ بَازِغاࣰ قَالَ هَٰذَا رَبِّے࣌ فَلَمَّآ أَفَلَ قَالَ لَئِن لَّمْ يَهْدِنِے رَبِّے لَأَكُونَنَّ مِنَ ࡰ۬لْقَوْمِ ࡴ۬لضَّآلِّينَ࣌', 'فلما رءا ࡰلقمر بازغا قال هذا ربے࣌ فلما أفل قال لئن لم يهدنے ربے لأكونن من ࡰلقوم ࡴلضالين࣌', NULL, 137, 'local:warsh-text.json'),
  ('warsh-6-79', 'warsh', 6, 79, 'فَلَمَّا رَءَا ࡰ۬لشَّمْسَ بَازِغَةࣰ قَالَ هَٰذَا رَبِّے هَٰذَآ أَكْبَرُ࣌ فَلَمَّآ أَفَلَتْ قَالَ يَٰقَوْمِ إِنِّے بَرِےٓءࣱ مِّمَّا تُشْرِكُونَ࣌', 'فلما رءا ࡰلشمس بازغة قال هذا ربے هذا أكبر࣌ فلما أفلت قال يقوم إنے برےء مما تشركون࣌', NULL, 137, 'local:warsh-text.json'),
  ('warsh-6-80', 'warsh', 6, 80, 'إِنِّے وَجَّهْتُ وَجْهِيَ لِلذِے فَطَرَ ࡰ۬لسَّمَٰوَٰتِ وَالَارْضَ حَنِيفاࣰ࣌ وَمَآ أَنَا مِنَ ࡰ۬لْمُشْرِكِينَ࣌', 'إنے وجهت وجهي للذے فطر ࡰلسموت والارض حنيفا࣌ وما أنا من ࡰلمشركين࣌', NULL, 137, 'local:warsh-text.json'),
  ('warsh-6-81', 'warsh', 6, 81, '۞ وَحَآجَّهُۥ قَوْمُهُۥ࣌ قَالَ أَتُحَٰٓجُّونِے فِے ࡴ۬للَّهِ وَقَدْ هَدٜيٰنِ࣌ وَلَآ أَخَافُ مَا تُشْرِكُونَ بِهِۦٓ إِلَّآ أَنْ يَّشَآءَ رَبِّے شَيْـٔاࣰ࣌ وَسِعَ رَبِّے كُلَّ شَےْءٍ عِلْماً࣌ ࡰفَلَا تَتَذَكَّرُونَ࣌', 'وحاجه قومه࣌ قال أتحجونے فے ࡴلله وقد هدين࣌ ولا أخاف ما تشركون به إلا أن يشاء ربے شيا࣌ وسع ربے كل شےء علما࣌ ࡰفلا تتذكرون࣌', NULL, 137, 'local:warsh-text.json'),
  ('warsh-6-82', 'warsh', 6, 82, 'وَكَيْفَ أَخَافُ مَآ أَشْرَكْتُمْ࣌ وَلَا تَخَافُونَ أَنَّكُمُۥٓ أَشْرَكْتُم بِاللَّهِ مَا لَمْ يُنَزِّلْ بِهِۦ عَلَيْكُمْ سُلْطَٰناࣰ࣌ فَأَيُّ ࡲ۬لْفَرِيقَيْنِ أَحَقُّ بِالَامْنِ إِن كُنتُمْ تَعْلَمُونَ࣌', 'وكيف أخاف ما أشركتم࣌ ولا تخافون أنكم أشركتم بالله ما لم ينزل به عليكم سلطنا࣌ فأي ࡲلفريقين أحق بالامن إن كنتم تعلمون࣌', NULL, 137, 'local:warsh-text.json'),
  ('warsh-6-83', 'warsh', 6, 83, 'ࡰ۬لذِينَ ءَامَنُواْ وَلَمْ يَلْبِسُوٓاْ إِيمَٰنَهُم بِظُلْمٍ ࡳوْلَٰٓئِكَ لَهُمُ ࡲ۬لَامْنُ وَهُم مُّهْتَدُونَ࣌', 'ࡰلذين ءامنوا ولم يلبسوا إيمنهم بظلم ࡳولئك لهم ࡲلامن وهم مهتدون࣌', NULL, 138, 'local:warsh-text.json'),
  ('warsh-6-84', 'warsh', 6, 84, 'وَتِلْكَ حُجَّتُنَآ ءَاتَيْنَٰهَآ إِبْرَٰهِيمَ عَلَىٰ قَوْمِهِۦ࣌ نَرْفَعُ دَرَجَٰتِ مَن نَّشَآءُ࣌ ࡹِنَّ رَبَّكَ حَكِيمٌ عَلِيمࣱ࣌', 'وتلك حجتنا ءاتينها إبرهيم على قومه࣌ نرفع درجت من نشاء࣌ ࡹن ربك حكيم عليم࣌', NULL, 138, 'local:warsh-text.json'),
  ('warsh-6-85', 'warsh', 6, 85, 'وَوَهَبْنَا لَهُۥٓ إِسْحَٰقَ وَيَعْقُوبَ࣌ كُلّاً هَدَيْنَا࣌ وَنُوحاً هَدَيْنَا مِن قَبْلُ࣌ وَمِن ذُرِّيَّتِهِۦ دَاوُۥدَ وَسُلَيْمَٰنَ وَأَيُّوبَ وَيُوسُفَ وَمُوسٜىٰ وَهَٰرُونَ࣌ وَكَذَٰلِكَ نَجْزِے ࡴ۬لْمُحْسِنِينَ࣌', 'ووهبنا له إسحق ويعقوب࣌ كلا هدينا࣌ ونوحا هدينا من قبل࣌ ومن ذريته داود وسليمن وأيوب ويوسف وموسى وهرون࣌ وكذلك نجزے ࡴلمحسنين࣌', NULL, 138, 'local:warsh-text.json'),
  ('warsh-6-86', 'warsh', 6, 86, 'وَزَكَرِيَّآءَ وَيَحْيٜىٰ وَعِيسٜىٰ وَإِلْيَاسَ࣌ كُلࣱّ مِّنَ ࡰ۬لصَّٰلِحِينَ࣌', 'وزكرياء ويحيى وعيسى وإلياس࣌ كل من ࡰلصلحين࣌', NULL, 138, 'local:warsh-text.json'),
  ('warsh-6-87', 'warsh', 6, 87, 'وَإِسْمَٰعِيلَ وَالْيَسَعَ وَيُونُسَ وَلُوطاࣰ࣌ وَكُلّاࣰ فَضَّلْنَا عَلَى ࡰ۬لْعَٰلَمِينَ࣌', 'وإسمعيل واليسع ويونس ولوطا࣌ وكلا فضلنا على ࡰلعلمين࣌', NULL, 138, 'local:warsh-text.json'),
  ('warsh-6-88', 'warsh', 6, 88, 'وَمِنَ اٰبَآئِهِمْ وَذُرِّيَّٰتِهِمْ وَإِخْوَٰنِهِمْ࣌ وَاجْتَبَيْنَٰهُمْ وَهَدَيْنَٰهُمُۥٓ إِلَىٰ صِرَٰطࣲ مُّسْتَقِيمࣲ࣌', 'ومن ابائهم وذريتهم وإخونهم࣌ واجتبينهم وهدينهم إلى صرط مستقيم࣌', NULL, 138, 'local:warsh-text.json'),
  ('warsh-6-89', 'warsh', 6, 89, 'ذَٰلِكَ هُدَى ࡰ۬للَّهِ يَهْدِے بِهِۦ مَنْ يَّشَآءُ مِنْ عِبَادِهِۦ࣌ وَلَوَ ࡰشْرَكُواْ لَحَبِطَ عَنْهُم مَّا كَانُواْ يَعْمَلُونَ࣌', 'ذلك هدى ࡰلله يهدے به من يشاء من عباده࣌ ولو ࡰشركوا لحبط عنهم ما كانوا يعملون࣌', NULL, 138, 'local:warsh-text.json'),
  ('warsh-6-90', 'warsh', 6, 90, 'أُوْلَٰٓئِكَ ࡰ۬لذِينَ ءَاتَيْنَٰهُمُ ࡲ۬لْكِتَٰبَ وَالْحُكْمَ وَالنُّبُوٓءَةَ࣌ فَإِنْ يَّكْفُرْ بِهَا هَٰٓؤُلَآءِ فَقَدْ وَكَّلْنَا بِهَا قَوْماࣰ لَّيْسُواْ بِهَا بِكٜـٰفِرِينَ࣌', 'أولئك ࡰلذين ءاتينهم ࡲلكتب والحكم والنبوءة࣌ فإن يكفر بها هؤلاء فقد وكلنا بها قوما ليسوا بها بكفرين࣌', NULL, 138, 'local:warsh-text.json'),
  ('warsh-6-91', 'warsh', 6, 91, 'أُوْلَٰٓئِكَ ࡰ۬لذِينَ هَدَى ࡰ۬للَّهُ فَبِهُدٜيٰهُمُ ࡲٜقْتَدِهْ࣌ قُل لَّآ أَسْـَٔلُكُمْ عَلَيْهِ أَجْراً࣌ ࡴنْ هُوَ إِلَّا ذِكْرٜىٰ لِلْعَٰلَمِينَ࣌', 'أولئك ࡰلذين هدى ࡰلله فبهديهم ࡲقتده࣌ قل لا أسلكم عليه أجرا࣌ ࡴن هو إلا ذكرى للعلمين࣌', NULL, 138, 'local:warsh-text.json'),
  ('warsh-6-92', 'warsh', 6, 92, '۞ وَمَا قَدَرُواْ ࡲ۬للَّهَ حَقَّ قَدْرِهِۦٓ إِذْ قَالُواْ مَآ أَنزَلَ ࡰ۬للَّهُ عَلَىٰ بَشَرࣲ مِّن شَےْءࣲ࣌ قُلْ مَنَ ࡰنزَلَ ࡰ۬لْكِتَٰبَ ࡰ۬لذِے جَآءَ بِهِۦ مُوسٜىٰ نُوراࣰ وَهُدىࣰ لِّلنَّاسِ࣌ تَجْعَلُونَهُۥ قَرَاطِيسَ تُبْدُونَهَا وَتُخْفُونَ كَثِيراࣰ࣌ وَعُلِّمْتُم مَّا لَمْ تَعْلَمُوٓاْ أَنتُمْ وَلَآ ءَابَآؤُكُمْ قُلِ ࡴ۬للَّهُ࣌ ثُمَّ ذَرْهُمْ فِے خَوْضِهِمْ يَلْعَبُونَ࣌', 'وما قدروا ࡲلله حق قدره إذ قالوا ما أنزل ࡰلله على بشر من شےء࣌ قل من ࡰنزل ࡰلكتب ࡰلذے جاء به موسى نورا وهدى للناس࣌ تجعلونه قراطيس تبدونها وتخفون كثيرا࣌ وعلمتم ما لم تعلموا أنتم ولا ءاباؤكم قل ࡴلله࣌ ثم ذرهم فے خوضهم يلعبون࣌', NULL, 139, 'local:warsh-text.json'),
  ('warsh-6-93', 'warsh', 6, 93, 'وَهَٰذَا كِتَٰبٌ ࡰنزَلْنَٰهُ مُبَٰرَكࣱ مُّصَدِّقُ ࡲ۬لذِے بَيْنَ يَدَيْهِ وَلِتُنذِرَ أُمَّ ࡰ۬لْقُرٜىٰ وَمَنْ حَوْلَهَا࣌ وَالذِينَ يُومِنُونَ بِالَاخِرَةِ يُومِنُونَ بِهِۦ وَهُمْ عَلَىٰ صَلَاتِهِمْ يُحَافِظُونَ࣌', 'وهذا كتب ࡰنزلنه مبرك مصدق ࡲلذے بين يديه ولتنذر أم ࡰلقرى ومن حولها࣌ والذين يومنون بالاخرة يومنون به وهم على صلاتهم يحافظون࣌', NULL, 139, 'local:warsh-text.json'),
  ('warsh-6-94', 'warsh', 6, 94, 'وَمَنَ ࡰظْلَمُ مِمَّنِ ࡴٜفْتَرٜىٰ عَلَى ࡰ۬للَّهِ كَذِباً ࡰوْ قَالَ أُوحِيَ إِلَيَّ وَلَمْ يُوحَ إِلَيْهِ شَےْءࣱ وَمَن قَالَ سَأُنزِلُ مِثْلَ مَآ أَنزَلَ ࡰ۬للَّهُ࣌ وَلَوْ تَرٜىٰٓ إِذِ ࡴ۬لظَّٰلِمُونَ فِے غَمَرَٰتِ ࡴ۬لْمَوْتِ وَالْمَلَٰٓئِكَةُ بَاسِطُوٓاْ أَيْدِيهِمُۥٓ أَخْرِجُوٓاْ أَنفُسَكُمُ࣌ ࡲ۬لْيَوْمَ تُجْزَوْنَ عَذَابَ ࡰ۬لْهُونِ بِمَا كُنتُمْ تَقُولُونَ عَلَى ࡰ۬للَّهِ غَيْرَ ࡰ۬لْحَقِّ وَكُنتُمْ عَنَ اٰيَٰتِهِۦ تَسْتَكْبِرُونَ࣌', 'ومن ࡰظلم ممن ࡴفترى على ࡰلله كذبا ࡰو قال أوحي إلي ولم يوح إليه شےء ومن قال سأنزل مثل ما أنزل ࡰلله࣌ ولو ترى إذ ࡴلظلمون فے غمرت ࡴلموت والملئكة باسطوا أيديهم أخرجوا أنفسكم࣌ ࡲليوم تجزون عذاب ࡰلهون بما كنتم تقولون على ࡰلله غير ࡰلحق وكنتم عن ايته تستكبرون࣌', NULL, 139, 'local:warsh-text.json'),
  ('warsh-6-95', 'warsh', 6, 95, 'وَلَقَدْ جِئْتُمُونَا فُرَٰدٜىٰ كَمَا خَلَقْنَٰكُمُۥٓ أَوَّلَ مَرَّةࣲ وَتَرَكْتُم مَّا خَوَّلْنَٰكُمْ وَرَآءَ ظُهُورِكُمْ࣌ وَمَا نَرٜىٰ مَعَكُمْ شُفَعَآءَكُمُ ࡲ۬لذِينَ زَعَمْتُمُۥٓ أَنَّهُمْ فِيكُمْ شُرَكَٰٓؤُاْ࣌ لَقَد تَّقَطَّعَ بَيْنَكُمْ وَضَلَّ عَنكُم مَّا كُنتُمْ تَزْعُمُونَ࣌', 'ولقد جئتمونا فردى كما خلقنكم أول مرة وتركتم ما خولنكم وراء ظهوركم࣌ وما نرى معكم شفعاءكم ࡲلذين زعمتم أنهم فيكم شركؤا࣌ لقد تقطع بينكم وضل عنكم ما كنتم تزعمون࣌', NULL, 139, 'local:warsh-text.json'),
  ('warsh-6-96', 'warsh', 6, 96, '۞ إِنَّ ࡰ۬للَّهَ فَٰلِقُ ࡲ۬لْحَبِّ وَالنَّوٜىٰ࣌ يُخْرِجُ ࡲ۬لْحَيَّ مِنَ ࡰ۬لْمَيِّتِ وَمُخْرِجُ ࡲ۬لْمَيِّتِ مِنَ ࡰ۬لْحَيِّ࣌ ذَٰلِكُمُ ࡲ۬للَّهُ࣌ فَأَنّٜىٰ تُوفَكُونَ࣌', 'إن ࡰلله فلق ࡲلحب والنوى࣌ يخرج ࡲلحي من ࡰلميت ومخرج ࡲلميت من ࡰلحي࣌ ذلكم ࡲلله࣌ فأنى توفكون࣌', NULL, 140, 'local:warsh-text.json'),
  ('warsh-6-97', 'warsh', 6, 97, 'فَالِقُ ࡲ۬لِاصْبَاحِ وَجَٰعِلُ ࡲ۬ليْلِ سَكَناࣰ࣌ وَالشَّمْسَ وَالْقَمَرَ حُسْبَٰناࣰ࣌ ذَٰلِكَ تَقْدِيرُ ࡲ۬لْعَزِيزِ ࡴ۬لْعَلِيمِ࣌', 'فالق ࡲلاصباح وجعل ࡲليل سكنا࣌ والشمس والقمر حسبنا࣌ ذلك تقدير ࡲلعزيز ࡴلعليم࣌', NULL, 140, 'local:warsh-text.json'),
  ('warsh-6-98', 'warsh', 6, 98, 'وَهُوَ ࡰ۬لذِے جَعَلَ لَكُمُ ࡲ۬لنُّجُومَ لِتَهْتَدُواْ بِهَا فِے ظُلُمَٰتِ ࡴ۬لْبَرِّ وَالْبَحْرِ࣌ قَدْ فَصَّلْنَا ࡰ۬لَايَٰتِ لِقَوْمࣲ يَعْلَمُونَ࣌', 'وهو ࡰلذے جعل لكم ࡲلنجوم لتهتدوا بها فے ظلمت ࡴلبر والبحر࣌ قد فصلنا ࡰلايت لقوم يعلمون࣌', NULL, 140, 'local:warsh-text.json'),
  ('warsh-6-99', 'warsh', 6, 99, 'وَهُوَ ࡰ۬لذِےٓ أَنشَأَكُم مِّن نَّفْسࣲ وَٰحِدَةࣲ فَمُسْتَقَرࣱّ وَمُسْتَوْدَعࣱ࣌ قَدْ فَصَّلْنَا ࡰ۬لَايَٰتِ لِقَوْمࣲ يَفْقَهُونَ࣌', 'وهو ࡰلذے أنشأكم من نفس وحدة فمستقر ومستودع࣌ قد فصلنا ࡰلايت لقوم يفقهون࣌', NULL, 140, 'local:warsh-text.json'),
  ('warsh-6-100', 'warsh', 6, 100, 'وَهُوَ ࡰ۬لذِےٓ أَنزَلَ مِنَ ࡰ۬لسَّمَآءِ مَآءࣰ فَأَخْرَجْنَا بِهِۦ نَبَاتَ كُلِّ شَےْءࣲ فَأَخْرَجْنَا مِنْهُ خَضِراࣰ نُّخْرِجُ مِنْهُ حَبّاࣰ مُّتَرَاكِباࣰ وَمِنَ ࡰ۬لنَّخْلِ مِن طَلْعِهَا قِنْوَانࣱ دَانِيَةࣱ وَجَنَّٰتࣲ مِّنَ ࡰعْنَٰبࣲ وَالزَّيْتُونَ وَالرُّمَّانَ مُشْتَبِهاࣰ وَغَيْرَ مُتَشَٰبِهٍ࣌ ࡲ࢈نظُرُوٓاْ إِلَىٰ ثَمَرِهِۦٓ إِذَآ أَثْمَرَ وَيَنْعِهِۦٓ࣌ إِنَّ فِے ذَٰلِكُمْ لَأٓيَٰتࣲ لِّقَوْمࣲ يُومِنُونَ࣌', 'وهو ࡰلذے أنزل من ࡰلسماء ماء فأخرجنا به نبات كل شےء فأخرجنا منه خضرا نخرج منه حبا متراكبا ومن ࡰلنخل من طلعها قنوان دانية وجنت من ࡰعنب والزيتون والرمان مشتبها وغير متشبه࣌ ࡲ࢈نظروا إلى ثمره إذا أثمر وينعه࣌ إن فے ذلكم لأيت لقوم يومنون࣌', NULL, 140, 'local:warsh-text.json'),
  ('warsh-6-101', 'warsh', 6, 101, 'وَجَعَلُواْ لِلهِ شُرَكَآءَ ࡰ۬لْجِنَّ وَخَلَقَهُمْ࣌ وَخَرَّقُواْ لَهُۥ بَنِينَ وَبَنَٰتِۢ بِغَيْرِ عِلْمࣲ࣌ سُبْحَٰنَهُۥ وَتَعَٰلٜىٰ عَمَّا يَصِفُونَ࣌', 'وجعلوا لله شركاء ࡰلجن وخلقهم࣌ وخرقوا له بنين وبنت بغير علم࣌ سبحنه وتعلى عما يصفون࣌', NULL, 140, 'local:warsh-text.json'),
  ('warsh-6-102', 'warsh', 6, 102, 'بَدِيعُ ࡲ۬لسَّمَٰوَٰتِ وَالَارْضِ࣌ أَنّٜىٰ يَكُونُ لَهُۥ وَلَدࣱ وَلَمْ تَكُن لَّهُۥ صَٰحِبَةࣱ࣌ وَخَلَقَ كُلَّ شَےْءࣲ࣌ وَهُوَ بِكُلِّ شَےْءٍ عَلِيمࣱ࣌', 'بديع ࡲلسموت والارض࣌ أنى يكون له ولد ولم تكن له صحبة࣌ وخلق كل شےء࣌ وهو بكل شےء عليم࣌', NULL, 140, 'local:warsh-text.json'),
  ('warsh-6-103', 'warsh', 6, 103, 'ذَٰلِكُمُ ࡲ۬للَّهُ رَبُّكُمْ࣌ لَآ إِلَٰهَ إِلَّا هُوَ࣌ خَٰلِقُ كُلِّ شَےْءࣲ࣌ فَاعْبُدُوهُ࣌ وَهُوَ عَلَىٰ كُلِّ شَےْءࣲ وَكِيلࣱ࣌', 'ذلكم ࡲلله ربكم࣌ لا إله إلا هو࣌ خلق كل شےء࣌ فاعبدوه࣌ وهو على كل شےء وكيل࣌', NULL, 141, 'local:warsh-text.json'),
  ('warsh-6-104', 'warsh', 6, 104, '۞ لَّا تُدْرِكُهُ ࡲ۬لَابْصَٰرُ࣌ وَهُوَ يُدْرِكُ ࡲ۬لَابْصَٰرَ࣌ وَهُوَ ࡰ۬للَّطِيفُ ࡲ۬لْخَبِيرُ࣌', 'لا تدركه ࡲلابصر࣌ وهو يدرك ࡲلابصر࣌ وهو ࡰللطيف ࡲلخبير࣌', NULL, 141, 'local:warsh-text.json'),
  ('warsh-6-105', 'warsh', 6, 105, 'قَدْ جَآءَكُم بَصَآئِرُ مِن رَّبِّكُمْ࣌ فَمَنَ ࡰبْصَرَ فَلِنَفْسِهِۦ وَمَنْ عَمِيَ فَعَلَيْهَا࣌ وَمَآ أَنَا عَلَيْكُم بِحَفِيظࣲ࣌', 'قد جاءكم بصائر من ربكم࣌ فمن ࡰبصر فلنفسه ومن عمي فعليها࣌ وما أنا عليكم بحفيظ࣌', NULL, 141, 'local:warsh-text.json'),
  ('warsh-6-106', 'warsh', 6, 106, 'وَكَذَٰلِكَ نُصَرِّفُ ࡲ۬لَايَٰتِ وَلِيَقُولُواْ دَرَسْتَ وَلِنُبَيِّنَهُۥ لِقَوْمࣲ يَعْلَمُونَ࣌', 'وكذلك نصرف ࡲلايت وليقولوا درست ولنبينه لقوم يعلمون࣌', NULL, 141, 'local:warsh-text.json'),
  ('warsh-6-107', 'warsh', 6, 107, 'ࡰٜتَّبِعْ مَآ أُوحِيَ إِلَيْكَ مِن رَّبِّكَ࣌ لَآ إِلَٰهَ إِلَّا هُوَ࣌ وَأَعْرِضْ عَنِ ࡴ۬لْمُشْرِكِينَ࣌', 'ࡰتبع ما أوحي إليك من ربك࣌ لا إله إلا هو࣌ وأعرض عن ࡴلمشركين࣌', NULL, 141, 'local:warsh-text.json'),
  ('warsh-6-108', 'warsh', 6, 108, 'وَلَوْ شَآءَ ࡰ۬للَّهُ مَآ أَشْرَكُواْ࣌ وَمَا جَعَلْنَٰكَ عَلَيْهِمْ حَفِيظاࣰ࣌ وَمَآ أَنتَ عَلَيْهِم بِوَكِيلࣲ࣌', 'ولو شاء ࡰلله ما أشركوا࣌ وما جعلنك عليهم حفيظا࣌ وما أنت عليهم بوكيل࣌', NULL, 141, 'local:warsh-text.json'),
  ('warsh-6-109', 'warsh', 6, 109, 'وَلَا تَسُبُّواْ ࡲ۬لذِينَ يَدْعُونَ مِن دُونِ ࡴ۬للَّهِ فَيَسُبُّواْ ࡲ۬للَّهَ عَدْواَۢ بِغَيْرِ عِلْمࣲ࣌ كَذَٰلِكَ زَيَّنَّا لِكُلِّ أُمَّةٍ عَمَلَهُمْ࣌ ثُمَّ إِلَىٰ رَبِّهِم مَّرْجِعُهُمْ فَيُنَبِّئُهُم بِمَا كَانُواْ يَعْمَلُونَ࣌', 'ولا تسبوا ࡲلذين يدعون من دون ࡴلله فيسبوا ࡲلله عدوا بغير علم࣌ كذلك زينا لكل أمة عملهم࣌ ثم إلى ربهم مرجعهم فينبئهم بما كانوا يعملون࣌', NULL, 141, 'local:warsh-text.json'),
  ('warsh-6-110', 'warsh', 6, 110, 'وَأَقْسَمُواْ بِاللَّهِ جَهْدَ أَيْمَٰنِهِمْ لَئِن جَآءَتْهُمُۥٓ ءَايَةࣱ لَّيُومِنُنَّ بِهَا࣌ قُلِ ࡴنَّمَا ࡰ۬لَايَٰتُ عِندَ ࡰ۬للَّهِ࣌ وَمَا يُشْعِرُكُمُۥٓ࣌ أَنَّهَآ إِذَا جَآءَتْ لَا يُومِنُونَ࣌', 'وأقسموا بالله جهد أيمنهم لئن جاءتهم ءاية ليومنن بها࣌ قل ࡴنما ࡰلايت عند ࡰلله࣌ وما يشعركم࣌ أنها إذا جاءت لا يومنون࣌', NULL, 141, 'local:warsh-text.json'),
  ('warsh-6-111', 'warsh', 6, 111, 'وَنُقَلِّبُ أَفْـِٕدَتَهُمْ وَأَبْصَٰرَهُمْ كَمَا لَمْ يُومِنُواْ بِهِۦٓ أَوَّلَ مَرَّةࣲ وَنَذَرُهُمْ فِے طُغْيَٰنِهِمْ يَعْمَهُونَ࣌', 'ونقلب أفدتهم وأبصرهم كما لم يومنوا به أول مرة ونذرهم فے طغينهم يعمهون࣌', NULL, 141, 'local:warsh-text.json'),
  ('warsh-6-112', 'warsh', 6, 112, '۞ وَلَوَ ࡰنَّنَا نَزَّلْنَآ إِلَيْهِمُ ࡲ۬لْمَلَٰٓئِكَةَ وَكَلَّمَهُمُ ࡲ۬لْمَوْتٜىٰ وَحَشَرْنَا عَلَيْهِمْ كُلَّ شَےْءࣲ قِبَلاࣰ مَّا كَانُواْ لِيُومِنُوٓاْ إِلَّآ أَنْ يَّشَآءَ ࡰ۬للَّهُ࣌ وَلَٰكِنَّ أَكْثَرَهُمْ يَجْهَلُونَ࣌', 'ولو ࡰننا نزلنا إليهم ࡲلملئكة وكلمهم ࡲلموتى وحشرنا عليهم كل شےء قبلا ما كانوا ليومنوا إلا أن يشاء ࡰلله࣌ ولكن أكثرهم يجهلون࣌', NULL, 142, 'local:warsh-text.json'),
  ('warsh-6-113', 'warsh', 6, 113, 'وَكَذَٰلِكَ جَعَلْنَا لِكُلِّ نَبِےٓءٍ عَدُوّاࣰ شَيَٰطِينَ ࡰ۬لِانسِ وَالْجِنِّ يُوحِے بَعْضُهُمُۥٓ إِلَىٰ بَعْضࣲ زُخْرُفَ ࡰ۬لْقَوْلِ غُرُوراࣰ࣌ وَلَوْ شَآءَ رَبُّكَ مَا فَعَلُوهُ࣌ فَذَرْهُمْ وَمَا يَفْتَرُونَ࣌', 'وكذلك جعلنا لكل نبےء عدوا شيطين ࡰلانس والجن يوحے بعضهم إلى بعض زخرف ࡰلقول غرورا࣌ ولو شاء ربك ما فعلوه࣌ فذرهم وما يفترون࣌', NULL, 142, 'local:warsh-text.json'),
  ('warsh-6-114', 'warsh', 6, 114, 'وَلِتَصْغٜىٰٓ إِلَيْهِ أَفْـِٕدَةُ ࡲ۬لذِينَ لَا يُومِنُونَ بِالَاخِرَةِ وَلِيَرْضَوْهُ وَلِيَقْتَرِفُواْ مَا هُم مُّقْتَرِفُونَ࣌', 'ولتصغى إليه أفدة ࡲلذين لا يومنون بالاخرة وليرضوه وليقترفوا ما هم مقترفون࣌', NULL, 142, 'local:warsh-text.json'),
  ('warsh-6-115', 'warsh', 6, 115, 'أَفَغَيْرَ ࡰ۬للَّهِ أَبْتَغِے حَكَماࣰ وَهُوَ ࡰ۬لذِےٓ أَنزَلَ إِلَيْكُمُ ࡲ۬لْكِتَٰبَ مُفَصَّلاࣰ࣌ وَالذِينَ ءَاتَيْنَٰهُمُ ࡲ۬لْكِتَٰبَ يَعْلَمُونَ أَنَّهُۥ مُنزَلࣱ مِّن رَّبِّكَ بِالْحَقِّ࣌ فَلَا تَكُونَنَّ مِنَ ࡰ۬لْمُمْتَرِينَ࣌', 'أفغير ࡰلله أبتغے حكما وهو ࡰلذے أنزل إليكم ࡲلكتب مفصلا࣌ والذين ءاتينهم ࡲلكتب يعلمون أنه منزل من ربك بالحق࣌ فلا تكونن من ࡰلممترين࣌', NULL, 142, 'local:warsh-text.json'),
  ('warsh-6-116', 'warsh', 6, 116, 'وَتَمَّتْ كَلِمَٰتُ رَبِّكَ صِدْقاࣰ وَعَدْلاࣰ࣌ لَّا مُبَدِّلَ لِكَلِمَٰتِهِۦ࣌ وَهُوَ ࡰ۬لسَّمِيعُ ࡲ۬لْعَلِيمُ࣌', 'وتمت كلمت ربك صدقا وعدلا࣌ لا مبدل لكلمته࣌ وهو ࡰلسميع ࡲلعليم࣌', NULL, 142, 'local:warsh-text.json'),
  ('warsh-6-117', 'warsh', 6, 117, 'وَإِن تُطِعَ ࡰكْثَرَ مَن فِے ࡴ۬لَارْضِ يُضِلُّوكَ عَن سَبِيلِ ࡴ۬للَّهِ࣌ إِنْ يَّتَّبِعُونَ إِلَّا ࡰ۬لظَّنَّ࣌ وَإِنْ هُمُۥٓ إِلَّا يَخْرُصُونَ࣌', 'وإن تطع ࡰكثر من فے ࡴلارض يضلوك عن سبيل ࡴلله࣌ إن يتبعون إلا ࡰلظن࣌ وإن هم إلا يخرصون࣌', NULL, 142, 'local:warsh-text.json'),
  ('warsh-6-118', 'warsh', 6, 118, 'إِنَّ رَبَّكَ هُوَ أَعْلَمُ مَنْ يَّضِلُّ عَن سَبِيلِهِۦ࣌ وَهُوَ أَعْلَمُ بِالْمُهْتَدِينَ࣌', 'إن ربك هو أعلم من يضل عن سبيله࣌ وهو أعلم بالمهتدين࣌', NULL, 142, 'local:warsh-text.json'),
  ('warsh-6-119', 'warsh', 6, 119, 'فَكُلُواْ مِمَّا ذُكِرَ ࡰٜسْمُ ࡲ۬للَّهِ عَلَيْهِ إِن كُنتُم بِـَٔايَٰتِهِۦ مُومِنِينَ࣌', 'فكلوا مما ذكر ࡰسم ࡲلله عليه إن كنتم بايته مومنين࣌', NULL, 142, 'local:warsh-text.json'),
  ('warsh-6-120', 'warsh', 6, 120, 'وَمَا لَكُمُۥٓ أَلَّا تَاكُلُواْ مِمَّا ذُكِرَ ࡰٜسْمُ ࡲ۬للَّهِ عَلَيْهِ وَقَدْ فَصَّلَ لَكُم مَّا حَرَّمَ عَلَيْكُمُۥٓ إِلَّا مَا ࡸَضْطُرِرْتُمُۥٓ إِلَيْهِ࣌ وَإِنَّ كَثِيراࣰ لَّيَضِلُّونَ بِأَهْوَآئِهِم بِغَيْرِ عِلْمٍ࣌ ࡴنَّ رَبَّكَ هُوَ أَعْلَمُ بِالْمُعْتَدِينَ࣌', 'وما لكم ألا تاكلوا مما ذكر ࡰسم ࡲلله عليه وقد فصل لكم ما حرم عليكم إلا ما ࡸضطررتم إليه࣌ وإن كثيرا ليضلون بأهوائهم بغير علم࣌ ࡴن ربك هو أعلم بالمعتدين࣌', NULL, 143, 'local:warsh-text.json'),
  ('warsh-6-121', 'warsh', 6, 121, '۞ وَذَرُواْ ظَٰهِرَ ࡰ۬لِاثْمِ وَبَاطِنَهُۥٓ࣌ إِنَّ ࡰ۬لذِينَ يَكْسِبُونَ ࡰ۬لِاثْمَ سَيُجْزَوْنَ بِمَا كَانُواْ يَقْتَرِفُونَ࣌', 'وذروا ظهر ࡰلاثم وباطنه࣌ إن ࡰلذين يكسبون ࡰلاثم سيجزون بما كانوا يقترفون࣌', NULL, 143, 'local:warsh-text.json'),
  ('warsh-6-122', 'warsh', 6, 122, 'وَلَا تَاكُلُواْ مِمَّا لَمْ يُذْكَرِ ࡴٜسْمُ ࡲ۬للَّهِ عَلَيْهِ وَإِنَّهُۥ لَفِسْقࣱ࣌ وَإِنَّ ࡰ۬لشَّيَٰطِينَ لَيُوحُونَ إِلَىٰٓ أَوْلِيَآئِهِمْ لِيُجَٰدِلُوكُمْ࣌ وَإِنَ ࡰطَعْتُمُوهُمُۥٓ إِنَّكُمْ لَمُشْرِكُونَ࣌', 'ولا تاكلوا مما لم يذكر ࡴسم ࡲلله عليه وإنه لفسق࣌ وإن ࡰلشيطين ليوحون إلى أوليائهم ليجدلوكم࣌ وإن ࡰطعتموهم إنكم لمشركون࣌', NULL, 143, 'local:warsh-text.json'),
  ('warsh-6-123', 'warsh', 6, 123, 'أَوَمَن كَانَ مَيِّتاࣰ فَأَحْيَيْنَٰهُ وَجَعَلْنَا لَهُۥ نُوراࣰ يَمْشِے بِهِۦ فِے ࡴ۬لنَّاسِ كَمَن مَّثَلُهُۥ فِے ࡴ۬لظُّلُمَٰتِ لَيْسَ بِخَارِجࣲ مِّنْهَا࣌ كَذَٰلِكَ زُيِّنَ لِلْكٜـٰفِرِينَ مَا كَانُواْ يَعْمَلُونَ࣌', 'أومن كان ميتا فأحيينه وجعلنا له نورا يمشے به فے ࡴلناس كمن مثله فے ࡴلظلمت ليس بخارج منها࣌ كذلك زين للكفرين ما كانوا يعملون࣌', NULL, 143, 'local:warsh-text.json'),
  ('warsh-6-124', 'warsh', 6, 124, 'وَكَذَٰلِكَ جَعَلْنَا فِے كُلِّ قَرْيَةٍ ࡰكَٰبِرَ مُجْرِمِيهَا لِيَمْكُرُواْ فِيهَا࣌ وَمَا يَمْكُرُونَ إِلَّا بِأَنفُسِهِمْ وَمَا يَشْعُرُونَ࣌', 'وكذلك جعلنا فے كل قرية ࡰكبر مجرميها ليمكروا فيها࣌ وما يمكرون إلا بأنفسهم وما يشعرون࣌', NULL, 143, 'local:warsh-text.json'),
  ('warsh-6-125', 'warsh', 6, 125, 'وَإِذَا جَآءَتْهُمُۥٓ ءَايَةࣱ قَالُواْ لَن نُّومِنَ حَتَّىٰ نُوتٜىٰ مِثْلَ مَآ أُوتِيَ رُسُلُ ࡲ۬للَّهِ࣌ ࡴ۬للَّهُ أَعْلَمُ حَيْثُ يَجْعَلُ رِسَٰلَٰتِهِۦ࣌ سَيُصِيبُ ࡲ۬لذِينَ أَجْرَمُواْ صَغَارٌ عِندَ ࡰ۬للَّهِ وَعَذَابࣱ شَدِيدُۢ بِمَا كَانُواْ يَمْكُرُونَ࣌', 'وإذا جاءتهم ءاية قالوا لن نومن حتى نوتى مثل ما أوتي رسل ࡲلله࣌ ࡴلله أعلم حيث يجعل رسلته࣌ سيصيب ࡲلذين أجرموا صغار عند ࡰلله وعذاب شديد بما كانوا يمكرون࣌', NULL, 143, 'local:warsh-text.json'),
  ('warsh-6-126', 'warsh', 6, 126, 'فَمَنْ يُّرِدِ ࡴ۬للَّهُ أَنْ يَّهْدِيَهُۥ يَشْرَحْ صَدْرَهُۥ لِلِاسْلَٰمِ࣌ وَمَنْ يُّرِدَ ࡰنْ يُّضِلَّهُۥ يَجْعَلْ صَدْرَهُۥ ضَيِّقاً حَرِجاࣰ كَأَنَّمَا يَصَّعَّدُ فِے ࡴ۬لسَّمَآءِ࣌ كَذَٰلِكَ يَجْعَلُ ࡲ۬للَّهُ ࡲ۬لرِّجْسَ عَلَى ࡰ۬لذِينَ لَا يُومِنُونَ࣌', 'فمن يرد ࡴلله أن يهديه يشرح صدره للاسلم࣌ ومن يرد ࡰن يضله يجعل صدره ضيقا حرجا كأنما يصعد فے ࡴلسماء࣌ كذلك يجعل ࡲلله ࡲلرجس على ࡰلذين لا يومنون࣌', NULL, 144, 'local:warsh-text.json'),
  ('warsh-6-127', 'warsh', 6, 127, 'وَهَٰذَا صِرَٰطُ رَبِّكَ مُسْتَقِيماࣰ࣌ قَدْ فَصَّلْنَا ࡰ۬لَايَٰتِ لِقَوْمࣲ يَذَّكَّرُونَ࣌', 'وهذا صرط ربك مستقيما࣌ قد فصلنا ࡰلايت لقوم يذكرون࣌', NULL, 144, 'local:warsh-text.json'),
  ('warsh-6-128', 'warsh', 6, 128, '۞ لَهُمْ دَارُ ࡲ۬لسَّلَٰمِ عِندَ رَبِّهِمْ࣌ وَهُوَ وَلِيُّهُم بِمَا كَانُواْ يَعْمَلُونَ࣌', 'لهم دار ࡲلسلم عند ربهم࣌ وهو وليهم بما كانوا يعملون࣌', NULL, 144, 'local:warsh-text.json'),
  ('warsh-6-129', 'warsh', 6, 129, 'وَيَوْمَ نَحْشُرُهُمْ جَمِيعاࣰ يَٰمَعْشَرَ ࡰ۬لْجِنِّ قَدِ ࡴٜسْتَكْثَرْتُم مِّنَ ࡰ۬لِانسِ࣌ وَقَالَ أَوْلِيَآؤُهُم مِّنَ ࡰ۬لِانسِ رَبَّنَا ࡰٜسْتَمْتَعَ بَعْضُنَا بِبَعْضࣲ وَبَلَغْنَآ أَجَلَنَا ࡰ۬لذِےٓ أَجَّلْتَ لَنَا࣌ قَالَ ࡰ۬لنَّارُ مَثْوٜيٰكُمْ خَٰلِدِينَ فِيهَآ إِلَّا مَا شَآءَ ࡰ۬للَّهُ࣌ إِنَّ رَبَّكَ حَكِيمٌ عَلِيمࣱ࣌', 'ويوم نحشرهم جميعا يمعشر ࡰلجن قد ࡴستكثرتم من ࡰلانس࣌ وقال أولياؤهم من ࡰلانس ربنا ࡰستمتع بعضنا ببعض وبلغنا أجلنا ࡰلذے أجلت لنا࣌ قال ࡰلنار مثويكم خلدين فيها إلا ما شاء ࡰلله࣌ إن ربك حكيم عليم࣌', NULL, 144, 'local:warsh-text.json'),
  ('warsh-6-130', 'warsh', 6, 130, 'وَكَذَٰلِكَ نُوَلِّے بَعْضَ ࡰ۬لظَّٰلِمِينَ بَعْضاَۢ بِمَا كَانُواْ يَكْسِبُونَ࣌', 'وكذلك نولے بعض ࡰلظلمين بعضا بما كانوا يكسبون࣌', NULL, 144, 'local:warsh-text.json'),
  ('warsh-6-131', 'warsh', 6, 131, 'يَٰمَعْشَرَ ࡰ۬لْجِنِّ وَالِانسِ أَلَمْ يَاتِكُمْ رُسُلࣱ مِّنكُمْ يَقُصُّونَ عَلَيْكُمُۥٓ ءَايَٰتِے وَيُنذِرُونَكُمْ لِقَآءَ يَوْمِكُمْ هَٰذَا࣌ قَالُواْ شَهِدْنَا عَلَىٰٓ أَنفُسِنَا࣌ وَغَرَّتْهُمُ ࡲ۬لْحَيَوٰةُ ࡲ۬لدُّنْيٜا وَشَهِدُواْ عَلَىٰٓ أَنفُسِهِمُۥٓ أَنَّهُمْ كَانُواْ كٜـٰفِرِينَ࣌', 'يمعشر ࡰلجن والانس ألم ياتكم رسل منكم يقصون عليكم ءايتے وينذرونكم لقاء يومكم هذا࣌ قالوا شهدنا على أنفسنا࣌ وغرتهم ࡲلحيوة ࡲلدنيا وشهدوا على أنفسهم أنهم كانوا كفرين࣌', NULL, 144, 'local:warsh-text.json'),
  ('warsh-6-132', 'warsh', 6, 132, 'ذَٰلِكَ أَن لَّمْ يَكُن رَّبُّكَ مُهْلِكَ ࡰ۬لْقُرٜىٰ بِظُلْمࣲ وَأَهْلُهَا غَٰفِلُونَ࣌', 'ذلك أن لم يكن ربك مهلك ࡰلقرى بظلم وأهلها غفلون࣌', NULL, 145, 'local:warsh-text.json'),
  ('warsh-6-133', 'warsh', 6, 133, 'وَلِكُلࣲّ دَرَجَٰتࣱ مِّمَّا عَمِلُواْ࣌ وَمَا رَبُّكَ بِغَٰفِلٍ عَمَّا يَعْمَلُونَ࣌', 'ولكل درجت مما عملوا࣌ وما ربك بغفل عما يعملون࣌', NULL, 145, 'local:warsh-text.json'),
  ('warsh-6-134', 'warsh', 6, 134, 'وَرَبُّكَ ࡰ۬لْغَنِيُّ ذُو ࡲ۬لرَّحْمَةِ࣌ إِنْ يَّشَأْ يُذْهِبْكُمْ وَيَسْتَخْلِفْ مِنۢ بَعْدِكُم مَّا يَشَآءُ كَمَآ أَنشَأَكُم مِّن ذُرِّيَّةِ قَوْمٍ اٰخَرِينَ࣌', 'وربك ࡰلغني ذو ࡲلرحمة࣌ إن يشأ يذهبكم ويستخلف من بعدكم ما يشاء كما أنشأكم من ذرية قوم اخرين࣌', NULL, 145, 'local:warsh-text.json'),
  ('warsh-6-135', 'warsh', 6, 135, 'إِنَّ مَا تُوعَدُونَ لَأٓتࣲ࣌ وَمَآ أَنتُم بِمُعْجِزِينَ࣌', 'إن ما توعدون لأت࣌ وما أنتم بمعجزين࣌', NULL, 145, 'local:warsh-text.json'),
  ('warsh-6-136', 'warsh', 6, 136, '۞ قُلْ يَٰقَوْمِ ࡴٜعْمَلُواْ عَلَىٰ مَكَانَتِكُمُۥٓ إِنِّے عَامِلࣱ࣌ فَسَوْفَ تَعْلَمُونَ مَن تَكُونُ لَهُۥ عَٰقِبَةُ ࡲ۬لدّٜارِ࣌ إِنَّهُۥ لَا يُفْلِحُ ࡲ۬لظَّٰلِمُونَ࣌', 'قل يقوم ࡴعملوا على مكانتكم إنے عامل࣌ فسوف تعلمون من تكون له عقبة ࡲلدار࣌ إنه لا يفلح ࡲلظلمون࣌', NULL, 145, 'local:warsh-text.json'),
  ('warsh-6-137', 'warsh', 6, 137, 'وَجَعَلُواْ لِلهِ مِمَّا ذَرَأَ مِنَ ࡰ۬لْحَرْثِ وَالَانْعَٰمِ نَصِيباࣰ فَقَالُواْ هَٰذَا لِلهِ بِزَعْمِهِمْ وَهَٰذَا لِشُرَكَآئِنَا࣌ فَمَا كَانَ لِشُرَكَآئِهِمْ فَلَا يَصِلُ إِلَى ࡰ۬للَّهِ࣌ وَمَا كَانَ لِلهِ فَهُوَ يَصِلُ إِلَىٰ شُرَكَآئِهِمْ࣌ سَآءَ مَا يَحْكُمُونَ࣌', 'وجعلوا لله مما ذرأ من ࡰلحرث والانعم نصيبا فقالوا هذا لله بزعمهم وهذا لشركائنا࣌ فما كان لشركائهم فلا يصل إلى ࡰلله࣌ وما كان لله فهو يصل إلى شركائهم࣌ ساء ما يحكمون࣌', NULL, 145, 'local:warsh-text.json'),
  ('warsh-6-138', 'warsh', 6, 138, 'وَكَذَٰلِكَ زَيَّنَ لِكَثِيرࣲ مِّنَ ࡰ۬لْمُشْرِكِينَ قَتْلَ أَوْلَٰدِهِمْ شُرَكَآؤُهُمْ لِيُرْدُوهُمْ وَلِيَلْبِسُواْ عَلَيْهِمْ دِينَهُمْ࣌ وَلَوْ شَآءَ ࡰ۬للَّهُ مَا فَعَلُوهُ࣌ فَذَرْهُمْ وَمَا يَفْتَرُونَ࣌', 'وكذلك زين لكثير من ࡰلمشركين قتل أولدهم شركاؤهم ليردوهم وليلبسوا عليهم دينهم࣌ ولو شاء ࡰلله ما فعلوه࣌ فذرهم وما يفترون࣌', NULL, 145, 'local:warsh-text.json'),
  ('warsh-6-139', 'warsh', 6, 139, 'وَقَالُواْ هَٰذِهِۦٓ أَنْعَٰمࣱ وَحَرْثٌ حِجْرࣱ لَّا يَطْعَمُهَآ إِلَّا مَن نَّشَآءُ بِزَعْمِهِمْ وَأَنْعَٰمٌ حُرِّمَت ظُّهُورُهَا وَأَنْعَٰمࣱ لَّا يَذْكُرُونَ ࡰٜسْمَ ࡰ۬للَّهِ عَلَيْهَا ࡰٜفْتِرَآءً عَلَيْهِ࣌ سَيَجْزِيهِم بِمَا كَانُواْ يَفْتَرُونَ࣌', 'وقالوا هذه أنعم وحرث حجر لا يطعمها إلا من نشاء بزعمهم وأنعم حرمت ظهورها وأنعم لا يذكرون ࡰسم ࡰلله عليها ࡰفتراء عليه࣌ سيجزيهم بما كانوا يفترون࣌', NULL, 146, 'local:warsh-text.json'),
  ('warsh-6-140', 'warsh', 6, 140, 'وَقَالُواْ مَا فِے بُطُونِ هَٰذِهِ ࡴ۬لَانْعَٰمِ خَالِصَةࣱ لِّذُكُورِنَا وَمُحَرَّمٌ عَلَىٰٓ أَزْوَٰجِنَا࣌ وَإِنْ يَّكُن مَّيْتَةࣰ فَهُمْ فِيهِ شُرَكَآءُ࣌ سَيَجْزِيهِمْ وَصْفَهُمُۥٓ࣌ إِنَّهُۥ حَكِيمٌ عَلِيمࣱ࣌', 'وقالوا ما فے بطون هذه ࡴلانعم خالصة لذكورنا ومحرم على أزوجنا࣌ وإن يكن ميتة فهم فيه شركاء࣌ سيجزيهم وصفهم࣌ إنه حكيم عليم࣌', NULL, 146, 'local:warsh-text.json'),
  ('warsh-6-141', 'warsh', 6, 141, '۞ قَدْ خَسِرَ ࡰ۬لذِينَ قَتَلُوٓاْ أَوْلَٰدَهُمْ سَفَهاَۢ بِغَيْرِ عِلْمࣲ وَحَرَّمُواْ مَا رَزَقَهُمُ ࡲ۬للَّهُ ࡲٜفْتِرَآءً عَلَى ࡰ۬للَّهِ࣌ قَد ضَّلُّواْ وَمَا كَانُواْ مُهْتَدِينَ࣌', 'قد خسر ࡰلذين قتلوا أولدهم سفها بغير علم وحرموا ما رزقهم ࡲلله ࡲفتراء على ࡰلله࣌ قد ضلوا وما كانوا مهتدين࣌', NULL, 146, 'local:warsh-text.json'),
  ('warsh-6-142', 'warsh', 6, 142, 'وَهُوَ ࡰ۬لذِےٓ أَنشَأَ جَنَّٰتࣲ مَّعْرُوشَٰتࣲ وَغَيْرَ مَعْرُوشَٰتࣲ وَالنَّخْلَ وَالزَّرْعَ مُخْتَلِفاً ࡳكْلُهُۥ وَالزَّيْتُونَ وَالرُّمَّانَ مُتَشَٰبِهاࣰ وَغَيْرَ مُتَشَٰبِهࣲ࣌ كُلُواْ مِن ثَمَرِهِۦٓ إِذَآ أَثْمَرَ وَءَاتُواْ حَقَّهُۥ يَوْمَ حِصَادِهِۦ࣌ وَلَا تُسْرِفُوٓاْ࣌ إِنَّهُۥ لَا يُحِبُّ ࡲ۬لْمُسْرِفِينَ࣌', 'وهو ࡰلذے أنشأ جنت معروشت وغير معروشت والنخل والزرع مختلفا ࡳكله والزيتون والرمان متشبها وغير متشبه࣌ كلوا من ثمره إذا أثمر وءاتوا حقه يوم حصاده࣌ ولا تسرفوا࣌ إنه لا يحب ࡲلمسرفين࣌', NULL, 146, 'local:warsh-text.json'),
  ('warsh-6-143', 'warsh', 6, 143, 'وَمِنَ ࡰ۬لَانْعَٰمِ حَمُولَةࣰ وَفَرْشاࣰ࣌ كُلُواْ مِمَّا رَزَقَكُمُ ࡲ۬للَّهُ࣌ وَلَا تَتَّبِعُواْ خُطْوَٰتِ ࡴ۬لشَّيْطَٰنِ࣌ إِنَّهُۥ لَكُمْ عَدُوࣱّ مُّبِينࣱ࣌', 'ومن ࡰلانعم حمولة وفرشا࣌ كلوا مما رزقكم ࡲلله࣌ ولا تتبعوا خطوت ࡴلشيطن࣌ إنه لكم عدو مبين࣌', NULL, 146, 'local:warsh-text.json'),
  ('warsh-6-144', 'warsh', 6, 144, 'ثَمَٰنِيَةَ أَزْوَٰجࣲ࣌ مِّنَ ࡰ۬لضَّأْنِ ࡴٜثْنَيْنِ وَمِنَ ࡰ۬لْمَعْزِ ࡴٜثْنَيْنِ࣌ قُلَ آٓلذَّكَرَيْنِ حَرَّمَ أَمِ ࡴ۬لُانثَيَيْنِ أَمَّا ࡰٜشْتَمَلَتْ عَلَيْهِ أَرْحَامُ ࡲ۬لُانثَيَيْنِ࣌ نَبِّـُٔونِے بِعِلْمٍ ࡴن كُنتُمْ صَٰدِقِينَ࣌', 'ثمنية أزوج࣌ من ࡰلضأن ࡴثنين ومن ࡰلمعز ࡴثنين࣌ قل آلذكرين حرم أم ࡴلانثيين أما ࡰشتملت عليه أرحام ࡲلانثيين࣌ نبونے بعلم ࡴن كنتم صدقين࣌', NULL, 147, 'local:warsh-text.json'),
  ('warsh-6-145', 'warsh', 6, 145, 'وَمِنَ ࡰ۬لِابِلِ ࡴٜثْنَيْنِ وَمِنَ ࡰ۬لْبَقَرِ ࡴٜثْنَيْنِ࣌ قُلَ آٓلذَّكَرَيْنِ حَرَّمَ أَمِ ࡴ۬لُانثَيَيْنِ أَمَّا ࡰٜشْتَمَلَتْ عَلَيْهِ أَرْحَامُ ࡲ۬لُانثَيَيْنِ࣌ أَمْ كُنتُمْ شُهَدَآءَ ࡹذْ وَصّٜيٰكُمُ ࡲ۬للَّهُ بِهَٰذَا࣌ فَمَنَ ࡰظْلَمُ مِمَّنِ ࡴٜفْتَرٜىٰ عَلَى ࡰ۬للَّهِ كَذِباࣰ لِّيُضِلَّ ࡰ۬لنَّاسَ بِغَيْرِ عِلْمٍ࣌ ࡴنَّ ࡰ۬للَّهَ لَا يَهْدِے ࡴ۬لْقَوْمَ ࡰ۬لظَّٰلِمِينَ࣌', 'ومن ࡰلابل ࡴثنين ومن ࡰلبقر ࡴثنين࣌ قل آلذكرين حرم أم ࡴلانثيين أما ࡰشتملت عليه أرحام ࡲلانثيين࣌ أم كنتم شهداء ࡹذ وصيكم ࡲلله بهذا࣌ فمن ࡰظلم ممن ࡴفترى على ࡰلله كذبا ليضل ࡰلناس بغير علم࣌ ࡴن ࡰلله لا يهدے ࡴلقوم ࡰلظلمين࣌', NULL, 147, 'local:warsh-text.json'),
  ('warsh-6-146', 'warsh', 6, 146, '۞ قُل لَّآ أَجِدُ فِے مَآ أُوحِيَ إِلَيَّ مُحَرَّماً عَلَىٰ طَاعِمࣲ يَطْعَمُهُۥٓ إِلَّآ أَنْ يَّكُونَ مَيْتَةً ࡰوْ دَماࣰ مَّسْفُوحاً ࡰوْ لَحْمَ خِنزِيرࣲ فَإِنَّهُۥ رِجْسٌ࣌ ࡰوْ فِسْقاً ࡳهِلَّ لِغَيْرِ ࡴ۬للَّهِ بِهِۦ࣌ فَمَنُ ࡲ࢈ضْطُرَّ غَيْرَ بَاغࣲ وَلَا عَادࣲ فَإِنَّ رَبَّكَ غَفُورࣱ رَّحِيمࣱ࣌', 'قل لا أجد فے ما أوحي إلي محرما على طاعم يطعمه إلا أن يكون ميتة ࡰو دما مسفوحا ࡰو لحم خنزير فإنه رجس࣌ ࡰو فسقا ࡳهل لغير ࡴلله به࣌ فمن ࡲ࢈ضطر غير باغ ولا عاد فإن ربك غفور رحيم࣌', NULL, 147, 'local:warsh-text.json'),
  ('warsh-6-147', 'warsh', 6, 147, 'وَعَلَى ࡰ۬لذِينَ هَادُواْ حَرَّمْنَا كُلَّ ذِے ظُفُرࣲ وَمِنَ ࡰ۬لْبَقَرِ وَالْغَنَمِ࣌ حَرَّمْنَا عَلَيْهِمْ شُحُومَهُمَآ إِلَّا مَا حَمَلَت ظُّهُورُهُمَآ أَوِ ࡴ۬لْحَوَايٜآ أَوْ مَا ࡰٜخْتَلَطَ بِعَظْمࣲ࣌ ذَٰلِكَ جَزَيْنَٰهُم بِبَغْيِهِمْ࣌ وَإِنَّا لَصَٰدِقُونَ࣌', 'وعلى ࡰلذين هادوا حرمنا كل ذے ظفر ومن ࡰلبقر والغنم࣌ حرمنا عليهم شحومهما إلا ما حملت ظهورهما أو ࡴلحوايا أو ما ࡰختلط بعظم࣌ ذلك جزينهم ببغيهم࣌ وإنا لصدقون࣌', NULL, 147, 'local:warsh-text.json'),
  ('warsh-6-148', 'warsh', 6, 148, 'فَإِن كَذَّبُوكَ فَقُل رَّبُّكُمْ ذُو رَحْمَةࣲ وَٰسِعَةࣲ࣌ وَلَا يُرَدُّ بَأْسُهُۥ عَنِ ࡴ۬لْقَوْمِ ࡴ۬لْمُجْرِمِينَ࣌', 'فإن كذبوك فقل ربكم ذو رحمة وسعة࣌ ولا يرد بأسه عن ࡴلقوم ࡴلمجرمين࣌', NULL, 148, 'local:warsh-text.json'),
  ('warsh-6-149', 'warsh', 6, 149, 'سَيَقُولُ ࡲ۬لذِينَ أَشْرَكُواْ لَوْ شَآءَ ࡰ۬للَّهُ مَآ أَشْرَكْنَا وَلَآ ءَابَآؤُنَا وَلَا حَرَّمْنَا مِن شَےْءࣲ࣌ كَذَٰلِكَ كَذَّبَ ࡰ۬لذِينَ مِن قَبْلِهِمْ حَتَّىٰ ذَاقُواْ بَأْسَنَا࣌ قُلْ هَلْ عِندَكُم مِّنْ عِلْمࣲ فَتُخْرِجُوهُ لَنَآ࣌ إِن تَتَّبِعُونَ إِلَّا ࡰ۬لظَّنَّ࣌ وَإِنَ ࡰنتُمُۥٓ إِلَّا تَخْرُصُونَ࣌', 'سيقول ࡲلذين أشركوا لو شاء ࡰلله ما أشركنا ولا ءاباؤنا ولا حرمنا من شےء࣌ كذلك كذب ࡰلذين من قبلهم حتى ذاقوا بأسنا࣌ قل هل عندكم من علم فتخرجوه لنا࣌ إن تتبعون إلا ࡰلظن࣌ وإن ࡰنتم إلا تخرصون࣌', NULL, 148, 'local:warsh-text.json'),
  ('warsh-6-150', 'warsh', 6, 150, 'قُلْ فَلِلهِ ࡴ۬لْحُجَّةُ ࡲ۬لْبَٰلِغَةُ࣌ فَلَوْ شَآءَ لَهَدٜيٰكُمُۥٓ أَجْمَعِينَ࣌', 'قل فلله ࡴلحجة ࡲلبلغة࣌ فلو شاء لهديكم أجمعين࣌', NULL, 148, 'local:warsh-text.json'),
  ('warsh-6-151', 'warsh', 6, 151, 'قُلْ هَلُمَّ شُهَدَآءَكُمُ ࡲ۬لذِينَ يَشْهَدُونَ أَنَّ ࡰ۬للَّهَ حَرَّمَ هَٰذَا࣌ فَإِن شَهِدُواْ فَلَا تَشْهَدْ مَعَهُمْ࣌ وَلَا تَتَّبِعَ ࡰهْوَآءَ ࡰ۬لذِينَ كَذَّبُواْ بِـَٔايَٰتِنَا وَالذِينَ لَا يُومِنُونَ بِالَاخِرَةِ وَهُم بِرَبِّهِمْ يَعْدِلُونَ࣌', 'قل هلم شهداءكم ࡲلذين يشهدون أن ࡰلله حرم هذا࣌ فإن شهدوا فلا تشهد معهم࣌ ولا تتبع ࡰهواء ࡰلذين كذبوا بايتنا والذين لا يومنون بالاخرة وهم بربهم يعدلون࣌', NULL, 148, 'local:warsh-text.json'),
  ('warsh-6-152', 'warsh', 6, 152, '۞ قُلْ تَعَالَوَاْ ࡰتْلُ مَا حَرَّمَ رَبُّكُمْ عَلَيْكُمُۥٓ أَلَّا تُشْرِكُواْ بِهِۦ شَيْـٔاࣰ࣌ وَبِالْوَٰلِدَيْنِ إِحْسَٰناࣰ࣌ وَلَا تَقْتُلُوٓاْ أَوْلَٰدَكُم مِّنِ ࡴمْلَٰقࣲ࣌ نَّحْنُ نَرْزُقُكُمْ وَإِيَّاهُمْ࣌ وَلَا تَقْرَبُواْ ࡲ۬لْفَوَٰحِشَ مَا ظَهَرَ مِنْهَا وَمَا بَطَنَ࣌ وَلَا تَقْتُلُواْ ࡲ۬لنَّفْسَ ࡰ۬لتِے حَرَّمَ ࡰ۬للَّهُ إِلَّا بِالْحَقِّ࣌ ذَٰلِكُمْ وَصّٜيٰكُم بِهِۦ لَعَلَّكُمْ تَعْقِلُونَ࣌', 'قل تعالوا ࡰتل ما حرم ربكم عليكم ألا تشركوا به شيا࣌ وبالولدين إحسنا࣌ ولا تقتلوا أولدكم من ࡴملق࣌ نحن نرزقكم وإياهم࣌ ولا تقربوا ࡲلفوحش ما ظهر منها وما بطن࣌ ولا تقتلوا ࡲلنفس ࡰلتے حرم ࡰلله إلا بالحق࣌ ذلكم وصيكم به لعلكم تعقلون࣌', NULL, 148, 'local:warsh-text.json'),
  ('warsh-6-153', 'warsh', 6, 153, 'وَلَا تَقْرَبُواْ مَالَ ࡰ۬لْيَتِيمِ إِلَّا بِالتِے هِيَ أَحْسَنُ حَتَّىٰ يَبْلُغَ أَشُدَّهُۥ࣌ وَأَوْفُواْ ࡲ۬لْكَيْلَ وَالْمِيزَانَ بِالْقِسْطِ࣌ لَا نُكَلِّفُ نَفْساً ࡴلَّا وُسْعَهَا࣌ وَإِذَا قُلْتُمْ فَاعْدِلُواْ وَلَوْ كَانَ ذَا قُرْبٜىٰ࣌ وَبِعَهْدِ ࡴ۬للَّهِ أَوْفُواْ࣌ ذَٰلِكُمْ وَصّٜيٰكُم بِهِۦ لَعَلَّكُمْ تَذَّكَّرُونَ࣌', 'ولا تقربوا مال ࡰليتيم إلا بالتے هي أحسن حتى يبلغ أشده࣌ وأوفوا ࡲلكيل والميزان بالقسط࣌ لا نكلف نفسا ࡴلا وسعها࣌ وإذا قلتم فاعدلوا ولو كان ذا قربى࣌ وبعهد ࡴلله أوفوا࣌ ذلكم وصيكم به لعلكم تذكرون࣌', NULL, 149, 'local:warsh-text.json'),
  ('warsh-6-154', 'warsh', 6, 154, 'وَأَنَّ هَٰذَا صِرَٰطِے مُسْتَقِيماࣰ فَاتَّبِعُوهُ࣌ وَلَا تَتَّبِعُواْ ࡲ۬لسُّبُلَ فَتَفَرَّقَ بِكُمْ عَن سَبِيلِهِۦ࣌ ذَٰلِكُمْ وَصّٜيٰكُم بِهِۦ لَعَلَّكُمْ تَتَّقُونَ࣌', 'وأن هذا صرطے مستقيما فاتبعوه࣌ ولا تتبعوا ࡲلسبل فتفرق بكم عن سبيله࣌ ذلكم وصيكم به لعلكم تتقون࣌', NULL, 149, 'local:warsh-text.json'),
  ('warsh-6-155', 'warsh', 6, 155, 'ثُمَّ ءَاتَيْنَا مُوسَى ࡰ۬لْكِتَٰبَ تَمَاماً عَلَى ࡰ۬لذِےٓ أَحْسَنَ وَتَفْصِيلاࣰ لِّكُلِّ شَےْءࣲ وَهُدىࣰ وَرَحْمَةࣰ لَّعَلَّهُم بِلِقَآءِ رَبِّهِمْ يُومِنُونَ࣌', 'ثم ءاتينا موسى ࡰلكتب تماما على ࡰلذے أحسن وتفصيلا لكل شےء وهدى ورحمة لعلهم بلقاء ربهم يومنون࣌', NULL, 149, 'local:warsh-text.json'),
  ('warsh-6-156', 'warsh', 6, 156, 'وَهَٰذَا كِتَٰبٌ ࡰنزَلْنَٰهُ مُبَٰرَكࣱ فَاتَّبِعُوهُ وَاتَّقُواْ لَعَلَّكُمْ تُرْحَمُونَ', 'وهذا كتب ࡰنزلنه مبرك فاتبعوه واتقوا لعلكم ترحمون', NULL, 149, 'local:warsh-text.json'),
  ('warsh-6-157', 'warsh', 6, 157, 'أَن تَقُولُوٓاْ إِنَّمَآ أُنزِلَ ࡰ۬لْكِتَٰبُ عَلَىٰ طَآئِفَتَيْنِ مِن قَبْلِنَا وَإِن كُنَّا عَن دِرَاسَتِهِمْ لَغَٰفِلِينَ', 'أن تقولوا إنما أنزل ࡰلكتب على طائفتين من قبلنا وإن كنا عن دراستهم لغفلين', NULL, 149, 'local:warsh-text.json'),
  ('warsh-6-158', 'warsh', 6, 158, 'أَوْ تَقُولُواْ لَوَ ࡰنَّآ أُنزِلَ عَلَيْنَا ࡰ۬لْكِتَٰبُ لَكُنَّآ أَهْدٜىٰ مِنْهُمْ࣌ فَقَدْ جَآءَكُم بَيِّنَةࣱ مِّن رَّبِّكُمْ وَهُدىࣰ وَرَحْمَةࣱ࣌ فَمَنَ ࡰظْلَمُ مِمَّن كَذَّبَ بِـَٔايَٰتِ ࡴ۬للَّهِ وَصَدَفَ عَنْهَا࣌ سَنَجْزِے ࡴ۬لذِينَ يَصْدِفُونَ عَنَ اٰيَٰتِنَا سُوٓءَ ࡰ۬لْعَذَابِ بِمَا كَانُواْ يَصْدِفُونَ࣌', 'أو تقولوا لو ࡰنا أنزل علينا ࡰلكتب لكنا أهدى منهم࣌ فقد جاءكم بينة من ربكم وهدى ورحمة࣌ فمن ࡰظلم ممن كذب بايت ࡴلله وصدف عنها࣌ سنجزے ࡴلذين يصدفون عن ايتنا سوء ࡰلعذاب بما كانوا يصدفون࣌', NULL, 149, 'local:warsh-text.json'),
  ('warsh-6-159', 'warsh', 6, 159, '۞ هَلْ يَنظُرُونَ إِلَّآ أَن تَاتِيَهُمُ ࡲ۬لْمَلَٰٓئِكَةُ أَوْ يَاتِيَ رَبُّكَ أَوْ يَاتِيَ بَعْضُ ءَايَٰتِ رَبِّكَ࣌ يَوْمَ يَاتِے بَعْضُ ءَايَٰتِ رَبِّكَ لَا يَنفَعُ نَفْساً ࡴيمَٰنُهَا لَمْ تَكُنَ اٰمَنَتْ مِن قَبْلُ أَوْ كَسَبَتْ فِےٓ إِيمَٰنِهَا خَيْراࣰ࣌ قُلِ ࡴٜنتَظِرُوٓاْ࣌ إِنَّا مُنتَظِرُونَ࣌', 'هل ينظرون إلا أن تاتيهم ࡲلملئكة أو ياتي ربك أو ياتي بعض ءايت ربك࣌ يوم ياتے بعض ءايت ربك لا ينفع نفسا ࡴيمنها لم تكن امنت من قبل أو كسبت فے إيمنها خيرا࣌ قل ࡴنتظروا࣌ إنا منتظرون࣌', NULL, 150, 'local:warsh-text.json'),
  ('warsh-6-160', 'warsh', 6, 160, 'إِنَّ ࡰ۬لذِينَ فَرَّقُواْ دِينَهُمْ وَكَانُواْ شِيَعاࣰ لَّسْتَ مِنْهُمْ فِے شَےْءٍ࣌ ࡴنَّمَآ أَمْرُهُمُۥٓ إِلَى ࡰ۬للَّهِ࣌ ثُمَّ يُنَبِّئُهُم بِمَا كَانُواْ يَفْعَلُونَ࣌', 'إن ࡰلذين فرقوا دينهم وكانوا شيعا لست منهم فے شےء࣌ ࡴنما أمرهم إلى ࡰلله࣌ ثم ينبئهم بما كانوا يفعلون࣌', NULL, 150, 'local:warsh-text.json'),
  ('warsh-6-161', 'warsh', 6, 161, 'مَن جَآءَ بِالْحَسَنَةِ فَلَهُۥ عَشْرُ أَمْثَالِهَا࣌ وَمَن جَآءَ بِالسَّيِّئَةِ فَلَا يُجْزٜىٰٓ إِلَّا مِثْلَهَا وَهُمْ لَا يُظْلَمُونَ࣌', 'من جاء بالحسنة فله عشر أمثالها࣌ ومن جاء بالسيئة فلا يجزى إلا مثلها وهم لا يظلمون࣌', NULL, 150, 'local:warsh-text.json'),
  ('warsh-6-162', 'warsh', 6, 162, 'قُلِ ࡴنَّنِے هَدٜيٰنِے رَبِّيَ إِلَىٰ صِرَٰطࣲ مُّسْتَقِيمࣲ࣌', 'قل ࡴننے هدينے ربي إلى صرط مستقيم࣌', NULL, 150, 'local:warsh-text.json'),
  ('warsh-6-163', 'warsh', 6, 163, 'دِيناࣰ قَيِّماࣰ مِّلَّةَ إِبْرَٰهِيمَ حَنِيفاࣰ࣌ وَمَا كَانَ مِنَ ࡰ۬لْمُشْرِكِينَ࣌', 'دينا قيما ملة إبرهيم حنيفا࣌ وما كان من ࡰلمشركين࣌', NULL, 150, 'local:warsh-text.json'),
  ('warsh-6-164', 'warsh', 6, 164, 'قُلِ ࡴنَّ صَلَاتِے وَنُسُكِے وَمَحْيٜآےْ وَمَمَاتِيَ لِلهِ رَبِّ ࡴ۬لْعَٰلَمِينَ', 'قل ࡴن صلاتے ونسكے ومحياے ومماتي لله رب ࡴلعلمين', NULL, 150, 'local:warsh-text.json'),
  ('warsh-6-165', 'warsh', 6, 165, 'لَا شَرِيكَ لَهُۥ࣌ وَبِذَٰلِكَ أُمِرْتُ࣌ وَأَنَآ أَوَّلُ ࡲ۬لْمُسْلِمِينَ࣌', 'لا شريك له࣌ وبذلك أمرت࣌ وأنا أول ࡲلمسلمين࣌', NULL, 150, 'local:warsh-text.json'),
  ('warsh-6-166', 'warsh', 6, 166, 'قُلَ ࡰغَيْرَ ࡰ۬للَّهِ أَبْغِے رَبّاࣰ وَهُوَ رَبُّ كُلِّ شَےْءࣲ࣌ وَلَا تَكْسِبُ كُلُّ نَفْسٍ ࡴلَّا عَلَيْهَا࣌ وَلَا تَزِرُ وَازِرَةࣱ وِزْرَ أُخْرٜىٰ࣌ ثُمَّ إِلَىٰ رَبِّكُم مَّرْجِعُكُمْ فَيُنَبِّئُكُم بِمَا كُنتُمْ فِيهِ تَخْتَلِفُونَ࣌', 'قل ࡰغير ࡰلله أبغے ربا وهو رب كل شےء࣌ ولا تكسب كل نفس ࡴلا عليها࣌ ولا تزر وازرة وزر أخرى࣌ ثم إلى ربكم مرجعكم فينبئكم بما كنتم فيه تختلفون࣌', NULL, 150, 'local:warsh-text.json'),
  ('warsh-6-167', 'warsh', 6, 167, 'وَهُوَ ࡰ۬لذِے جَعَلَكُمْ خَلَٰٓئِفَ ࡰ۬لَارْضِ وَرَفَعَ بَعْضَكُمْ فَوْقَ بَعْضࣲ دَرَجَٰتࣲ لِّيَبْلُوَكُمْ فِے مَآ ءَاتٜيٰكُمُۥٓ࣌ إِنَّ رَبَّكَ سَرِيعُ ࡲ۬لْعِقَابِ࣌ وَإِنَّهُۥ لَغَفُورࣱ رَّحِيمٌ࣌', 'وهو ࡰلذے جعلكم خلئف ࡰلارض ورفع بعضكم فوق بعض درجت ليبلوكم فے ما ءاتيكم࣌ إن ربك سريع ࡲلعقاب࣌ وإنه لغفور رحيم࣌', NULL, 150, 'local:warsh-text.json'),
  ('warsh-7-1', 'warsh', 7, 1, 'ࡰلَٓمِّٓصَٓ࣌ كِتَٰبٌ ࡳنزِلَ إِلَيْكَ فَلَا يَكُن فِے صَدْرِكَ حَرَجࣱ مِّنْهُ لِتُنذِرَ بِهِۦ وَذِكْرٜىٰ لِلْمُومِنِينَ࣌', 'ࡰلمص࣌ كتب ࡳنزل إليك فلا يكن فے صدرك حرج منه لتنذر به وذكرى للمومنين࣌', NULL, 151, 'local:warsh-text.json'),
  ('warsh-7-2', 'warsh', 7, 2, 'ࡰٜتَّبِعُواْ مَآ أُنزِلَ إِلَيْكُم مِّن رَّبِّكُمْ࣌ وَلَا تَتَّبِعُواْ مِن دُونِهِۦٓ أَوْلِيَآءَ࣌ قَلِيلاࣰ مَّا تَذَّكَّرُونَ࣌', 'ࡰتبعوا ما أنزل إليكم من ربكم࣌ ولا تتبعوا من دونه أولياء࣌ قليلا ما تذكرون࣌', NULL, 151, 'local:warsh-text.json'),
  ('warsh-7-3', 'warsh', 7, 3, 'وَكَم مِّن قَرْيَةٍ ࡰهْلَكْنَٰهَا فَجَآءَهَا بَأْسُنَا بَيَٰتاً ࡰوْ هُمْ قَآئِلُونَ࣌', 'وكم من قرية ࡰهلكنها فجاءها بأسنا بيتا ࡰو هم قائلون࣌', NULL, 151, 'local:warsh-text.json'),
  ('warsh-7-4', 'warsh', 7, 4, '۞ فَمَا كَانَ دَعْوٜيٰهُمُۥٓ إِذْ جَآءَهُم بَأْسُنَآ إِلَّآ أَن قَالُوٓاْ إِنَّا كُنَّا ظَٰلِمِينَ࣌', 'فما كان دعويهم إذ جاءهم بأسنا إلا أن قالوا إنا كنا ظلمين࣌', NULL, 151, 'local:warsh-text.json'),
  ('warsh-7-5', 'warsh', 7, 5, 'فَلَنَسْـَٔلَنَّ ࡰ۬لذِينَ أُرْسِلَ إِلَيْهِمْ وَلَنَسْـَٔلَنَّ ࡰ۬لْمُرْسَلِينَ࣌', 'فلنسلن ࡰلذين أرسل إليهم ولنسلن ࡰلمرسلين࣌', NULL, 151, 'local:warsh-text.json'),
  ('warsh-7-6', 'warsh', 7, 6, 'فَلَنَقُصَّنَّ عَلَيْهِم بِعِلْمࣲ࣌ وَمَا كُنَّا غَآئِبِينَ࣌', 'فلنقصن عليهم بعلم࣌ وما كنا غائبين࣌', NULL, 151, 'local:warsh-text.json'),
  ('warsh-7-7', 'warsh', 7, 7, 'وَالْوَزْنُ يَوْمَئِذٍ ࡴ۬لْحَقُّ࣌ فَمَن ثَقُلَتْ مَوَٰزِينُهُۥ فَأُوْلَٰٓئِكَ هُمُ ࡲ۬لْمُفْلِحُونَ࣌', 'والوزن يومئذ ࡴلحق࣌ فمن ثقلت موزينه فأولئك هم ࡲلمفلحون࣌', NULL, 151, 'local:warsh-text.json'),
  ('warsh-7-8', 'warsh', 7, 8, 'وَمَنْ خَفَّتْ مَوَٰزِينُهُۥ فَأُوْلَٰٓئِكَ ࡰ۬لذِينَ خَسِرُوٓاْ أَنفُسَهُم بِمَا كَانُواْ بِـَٔايَٰتِنَا يَظْلِمُونَ࣌', 'ومن خفت موزينه فأولئك ࡰلذين خسروا أنفسهم بما كانوا بايتنا يظلمون࣌', NULL, 151, 'local:warsh-text.json'),
  ('warsh-7-9', 'warsh', 7, 9, 'وَلَقَدْ مَكَّنَّٰكُمْ فِے ࡴ۬لَارْضِ وَجَعَلْنَا لَكُمْ فِيهَا مَعَٰيِشَ࣌ قَلِيلاࣰ مَّا تَشْكُرُونَ࣌', 'ولقد مكنكم فے ࡴلارض وجعلنا لكم فيها معيش࣌ قليلا ما تشكرون࣌', NULL, 151, 'local:warsh-text.json'),
  ('warsh-7-10', 'warsh', 7, 10, 'وَلَقَدْ خَلَقْنَٰكُمْ ثُمَّ صَوَّرْنَٰكُمْ ثُمَّ قُلْنَا لِلْمَلَٰٓئِكَةِ ࡴ࢈سْجُدُواْ لِأٓدَمَ فَسَجَدُوٓاْ࣌ إِلَّآ إِبْلِيسَ لَمْ يَكُن مِّنَ ࡰ۬لسَّٰجِدِينَ࣌', 'ولقد خلقنكم ثم صورنكم ثم قلنا للملئكة ࡴ࢈سجدوا لأدم فسجدوا࣌ إلا إبليس لم يكن من ࡰلسجدين࣌', NULL, 151, 'local:warsh-text.json'),
  ('warsh-7-11', 'warsh', 7, 11, 'قَالَ مَا مَنَعَكَ أَلَّا تَسْجُدَ إِذَ ࡰمَرْتُكَ࣌ قَالَ أَنَا خَيْرࣱ مِّنْهُ خَلَقْتَنِے مِن نّٜارࣲ وَخَلَقْتَهُۥ مِن طِينࣲ࣌', 'قال ما منعك ألا تسجد إذ ࡰمرتك࣌ قال أنا خير منه خلقتنے من نار وخلقته من طين࣌', NULL, 152, 'local:warsh-text.json'),
  ('warsh-7-12', 'warsh', 7, 12, 'قَالَ فَاهْبِطْ مِنْهَا فَمَا يَكُونُ لَكَ أَن تَتَكَبَّرَ فِيهَا فَاخْرُجِ ࡴنَّكَ مِنَ ࡰ۬لصَّٰغِرِينَ࣌', 'قال فاهبط منها فما يكون لك أن تتكبر فيها فاخرج ࡴنك من ࡰلصغرين࣌', NULL, 152, 'local:warsh-text.json'),
  ('warsh-7-13', 'warsh', 7, 13, 'قَالَ أَنظِرْنِےٓ إِلَىٰ يَوْمِ يُبْعَثُونَ࣌', 'قال أنظرنے إلى يوم يبعثون࣌', NULL, 152, 'local:warsh-text.json'),
  ('warsh-7-14', 'warsh', 7, 14, 'قَالَ إِنَّكَ مِنَ ࡰ۬لْمُنظَرِينَ࣌', 'قال إنك من ࡰلمنظرين࣌', NULL, 152, 'local:warsh-text.json'),
  ('warsh-7-15', 'warsh', 7, 15, 'قَالَ فَبِمَآ أَغْوَيْتَنِے لَأَقْعُدَنَّ لَهُمْ صِرَٰطَكَ ࡰ۬لْمُسْتَقِيمَ', 'قال فبما أغويتنے لأقعدن لهم صرطك ࡰلمستقيم', NULL, 152, 'local:warsh-text.json'),
  ('warsh-7-16', 'warsh', 7, 16, 'ثُمَّ لَأٓتِيَنَّهُم مِّنۢ بَيْنِ أَيْدِيهِمْ وَمِنْ خَلْفِهِمْ وَعَنَ ࡰيْمَٰنِهِمْ وَعَن شَمَآئِلِهِمْ࣌ وَلَا تَجِدُ أَكْثَرَهُمْ شَٰكِرِينَ࣌', 'ثم لأتينهم من بين أيديهم ومن خلفهم وعن ࡰيمنهم وعن شمائلهم࣌ ولا تجد أكثرهم شكرين࣌', NULL, 152, 'local:warsh-text.json'),
  ('warsh-7-17', 'warsh', 7, 17, 'قَالَ ࡸَخْرُجْ مِنْهَا مَذْءُوماࣰ مَّدْحُوراࣰ࣌ لَّمَن تَبِعَكَ مِنْهُمْ لَأَمْلَأَنَّ جَهَنَّمَ مِنكُمُۥٓ أَجْمَعِينَ࣌', 'قال ࡸخرج منها مذءوما مدحورا࣌ لمن تبعك منهم لأملأن جهنم منكم أجمعين࣌', NULL, 152, 'local:warsh-text.json'),
  ('warsh-7-18', 'warsh', 7, 18, 'وَيَٰٓـَٔادَمُ ࡲ࢈سْكُنَ ࡰنتَ وَزَوْجُكَ ࡰ۬لْجَنَّةَ فَكُلَا مِنْ حَيْثُ شِئْتُمَا࣌ وَلَا تَقْرَبَا هَٰذِهِ ࡴ۬لشَّجَرَةَ فَتَكُونَا مِنَ ࡰ۬لظَّٰلِمِينَ࣌', 'ويادم ࡲ࢈سكن ࡰنت وزوجك ࡰلجنة فكلا من حيث شئتما࣌ ولا تقربا هذه ࡴلشجرة فتكونا من ࡰلظلمين࣌', NULL, 152, 'local:warsh-text.json'),
  ('warsh-7-19', 'warsh', 7, 19, 'فَوَسْوَسَ لَهُمَا ࡰ۬لشَّيْطَٰنُ لِيُبْدِيَ لَهُمَا مَا وُۥرِيَ عَنْهُمَا مِن سَوْءَٰتِهِمَا࣌ وَقَالَ مَا نَهٜيٰكُمَا رَبُّكُمَا عَنْ هَٰذِهِ ࡴ۬لشَّجَرَةِ إِلَّآ أَن تَكُونَا مَلَكَيْنِ أَوْ تَكُونَا مِنَ ࡰ۬لْخَٰلِدِينَ࣌', 'فوسوس لهما ࡰلشيطن ليبدي لهما ما وري عنهما من سوءتهما࣌ وقال ما نهيكما ربكما عن هذه ࡴلشجرة إلا أن تكونا ملكين أو تكونا من ࡰلخلدين࣌', NULL, 152, 'local:warsh-text.json'),
  ('warsh-7-20', 'warsh', 7, 20, '۞ وَقَاسَمَهُمَآ إِنِّے لَكُمَا لَمِنَ ࡰ۬لنَّٰصِحِينَ', 'وقاسمهما إنے لكما لمن ࡰلنصحين', NULL, 152, 'local:warsh-text.json'),
  ('warsh-7-21', 'warsh', 7, 21, 'فَدَلّٜيٰهُمَا بِغُرُورࣲ࣌ فَلَمَّا ذَاقَا ࡰ۬لشَّجَرَةَ بَدَتْ لَهُمَا سَوْءَٰتُهُمَا وَطَفِقَا يَخْصِفَٰنِ عَلَيْهِمَا مِنْ وَّرَقِ ࡴ۬لْجَنَّةِ࣌ وَنَادٜيٰهُمَا رَبُّهُمَآ أَلَمَ ࡰنْهَكُمَا عَن تِلْكُمَا ࡰ۬لشَّجَرَةِ وَأَقُل لَّكُمَآ إِنَّ ࡰ۬لشَّيْطَٰنَ لَكُمَا عَدُوࣱّ مُّبِينࣱ࣌', 'فدليهما بغرور࣌ فلما ذاقا ࡰلشجرة بدت لهما سوءتهما وطفقا يخصفن عليهما من ورق ࡴلجنة࣌ وناديهما ربهما ألم ࡰنهكما عن تلكما ࡰلشجرة وأقل لكما إن ࡰلشيطن لكما عدو مبين࣌', NULL, 152, 'local:warsh-text.json'),
  ('warsh-7-22', 'warsh', 7, 22, 'قَالَا رَبَّنَا ظَلَمْنَآ أَنفُسَنَا وَإِن لَّمْ تَغْفِرْ لَنَا وَتَرْحَمْنَا لَنَكُونَنَّ مِنَ ࡰ۬لْخَٰسِرِينَ࣌', 'قالا ربنا ظلمنا أنفسنا وإن لم تغفر لنا وترحمنا لنكونن من ࡰلخسرين࣌', NULL, 153, 'local:warsh-text.json'),
  ('warsh-7-23', 'warsh', 7, 23, 'قَالَ ࡰٜهْبِطُواْ࣌ بَعْضُكُمْ لِبَعْضٍ عَدُوࣱّ࣌ وَلَكُمْ فِے ࡴ۬لَارْضِ مُسْتَقَرࣱّ وَمَتَٰعٌ ࡴلَىٰ حِينࣲ࣌', 'قال ࡰهبطوا࣌ بعضكم لبعض عدو࣌ ولكم فے ࡴلارض مستقر ومتع ࡴلى حين࣌', NULL, 153, 'local:warsh-text.json'),
  ('warsh-7-24', 'warsh', 7, 24, 'قَالَ فِيهَا تَحْيَوْنَ وَفِيهَا تَمُوتُونَ وَمِنْهَا تُخْرَجُونَ࣌', 'قال فيها تحيون وفيها تموتون ومنها تخرجون࣌', NULL, 153, 'local:warsh-text.json'),
  ('warsh-7-25', 'warsh', 7, 25, 'يَٰبَنِےٓ ءَادَمَ قَدَ ࡰنزَلْنَا عَلَيْكُمْ لِبَاساࣰ يُوَٰرِے سَوْءَٰتِكُمْ وَرِيشاࣰ وَلِبَاسَ ࡰ۬لتَّقْوٜىٰ࣌ ذَٰلِكَ خَيْرࣱ࣌ ذَٰلِكَ مِنَ اٰيَٰتِ ࡴ۬للَّهِ لَعَلَّهُمْ يَذَّكَّرُونَ࣌', 'يبنے ءادم قد ࡰنزلنا عليكم لباسا يورے سوءتكم وريشا ولباس ࡰلتقوى࣌ ذلك خير࣌ ذلك من ايت ࡴلله لعلهم يذكرون࣌', NULL, 153, 'local:warsh-text.json'),
  ('warsh-7-26', 'warsh', 7, 26, 'يَٰبَنِےٓ ءَادَمَ لَا يَفْتِنَنَّكُمُ ࡲ۬لشَّيْطَٰنُ كَمَآ أَخْرَجَ أَبَوَيْكُم مِّنَ ࡰ۬لْجَنَّةِ يَنزِعُ عَنْهُمَا لِبَاسَهُمَا لِيُرِيَهُمَا سَوْءَٰتِهِمَآ࣌ إِنَّهُۥ يَرٜيٰكُمْ هُوَ وَقَبِيلُهُۥ مِنْ حَيْثُ لَا تَرَوْنَهُمُۥٓ࣌ إِنَّا جَعَلْنَا ࡰ۬لشَّيَٰطِينَ أَوْلِيَآءَ لِلذِينَ لَا يُومِنُونَ࣌', 'يبنے ءادم لا يفتننكم ࡲلشيطن كما أخرج أبويكم من ࡰلجنة ينزع عنهما لباسهما ليريهما سوءتهما࣌ إنه يريكم هو وقبيله من حيث لا ترونهم࣌ إنا جعلنا ࡰلشيطين أولياء للذين لا يومنون࣌', NULL, 153, 'local:warsh-text.json'),
  ('warsh-7-27', 'warsh', 7, 27, 'وَإِذَا فَعَلُواْ فَٰحِشَةࣰ قَالُواْ وَجَدْنَا عَلَيْهَآ ءَابَآءَنَا وَاللَّهُ أَمَرَنَا بِهَا࣌ قُلِ ࡴنَّ ࡰ۬للَّهَ لَا يَامُرُ بِالْفَحْشَآءِ࣌ ࡶَتَقُولُونَ عَلَى ࡰ۬للَّهِ مَا لَا تَعْلَمُونَ࣌', 'وإذا فعلوا فحشة قالوا وجدنا عليها ءاباءنا والله أمرنا بها࣌ قل ࡴن ࡰلله لا يامر بالفحشاء࣌ ࡶتقولون على ࡰلله ما لا تعلمون࣌', NULL, 153, 'local:warsh-text.json'),
  ('warsh-7-28', 'warsh', 7, 28, 'قُلَ ࡰمَرَ رَبِّے بِالْقِسْطِ࣌ وَأَقِيمُواْ وُجُوهَكُمْ عِندَ كُلِّ مَسْجِدࣲ࣌ وَادْعُوهُ مُخْلِصِينَ لَهُ ࡲ۬لدِّينَ࣌ كَمَا بَدَأَكُمْ تَعُودُونَ࣌ فَرِيقاً هَدٜىٰ࣌ وَفَرِيقاً حَقَّ عَلَيْهِمُ ࡲ۬لضَّلَٰلَةُ࣌ إِنَّهُمُ ࡲٜتَّخَذُواْ ࡲ۬لشَّيَٰطِينَ أَوْلِيَآءَ مِن دُونِ ࡴ۬للَّهِ وَيَحْسِبُونَ أَنَّهُم مُّهْتَدُونَ࣌', 'قل ࡰمر ربے بالقسط࣌ وأقيموا وجوهكم عند كل مسجد࣌ وادعوه مخلصين له ࡲلدين࣌ كما بدأكم تعودون࣌ فريقا هدى࣌ وفريقا حق عليهم ࡲلضللة࣌ إنهم ࡲتخذوا ࡲلشيطين أولياء من دون ࡴلله ويحسبون أنهم مهتدون࣌', NULL, 153, 'local:warsh-text.json'),
  ('warsh-7-29', 'warsh', 7, 29, 'يَٰبَنِےٓ ءَادَمَ خُذُواْ زِينَتَكُمْ عِندَ كُلِّ مَسْجِدࣲ وَكُلُواْ وَاشْرَبُواْ࣌ وَلَا تُسْرِفُوٓاْ࣌ إِنَّهُۥ لَا يُحِبُّ ࡲ۬لْمُسْرِفِينَ࣌', 'يبنے ءادم خذوا زينتكم عند كل مسجد وكلوا واشربوا࣌ ولا تسرفوا࣌ إنه لا يحب ࡲلمسرفين࣌', NULL, 154, 'local:warsh-text.json'),
  ('warsh-7-30', 'warsh', 7, 30, '۞ قُلْ مَنْ حَرَّمَ زِينَةَ ࡰ۬للَّهِ ࡴ۬لتِےٓ أَخْرَجَ لِعِبَادِهِۦ وَالطَّيِّبَٰتِ مِنَ ࡰ۬لرِّزْقِ࣌ قُلْ هِيَ لِلذِينَ ءَامَنُواْ فِے ࡴ۬لْحَيَوٰةِ ࡴ۬لدُّنْيٜا خَالِصَةࣱ يَوْمَ ࡰ۬لْقِيَٰمَةِ࣌ كَذَٰلِكَ نُفَصِّلُ ࡲ۬لَايَٰتِ لِقَوْمࣲ يَعْلَمُونَ࣌', 'قل من حرم زينة ࡰلله ࡴلتے أخرج لعباده والطيبت من ࡰلرزق࣌ قل هي للذين ءامنوا فے ࡴلحيوة ࡴلدنيا خالصة يوم ࡰلقيمة࣌ كذلك نفصل ࡲلايت لقوم يعلمون࣌', NULL, 154, 'local:warsh-text.json'),
  ('warsh-7-31', 'warsh', 7, 31, 'قُلِ ࡴنَّمَا حَرَّمَ رَبِّيَ ࡰ۬لْفَوَٰحِشَ مَا ظَهَرَ مِنْهَا وَمَا بَطَنَ وَالِاثْمَ وَالْبَغْيَ بِغَيْرِ ࡴ۬لْحَقِّ وَأَن تُشْرِكُواْ بِاللَّهِ مَا لَمْ يُنَزِّلْ بِهِۦ سُلْطَٰناࣰ وَأَن تَقُولُواْ عَلَى ࡰ۬للَّهِ مَا لَا تَعْلَمُونَ࣌', 'قل ࡴنما حرم ربي ࡰلفوحش ما ظهر منها وما بطن والاثم والبغي بغير ࡴلحق وأن تشركوا بالله ما لم ينزل به سلطنا وأن تقولوا على ࡰلله ما لا تعلمون࣌', NULL, 154, 'local:warsh-text.json'),
  ('warsh-7-32', 'warsh', 7, 32, 'وَلِكُلِّ أُمَّةٍ ࡰجَلࣱ࣌ فَإِذَا جَآءَ اجَلُهُمْ لَا يَسْتَٰخِرُونَ سَاعَةࣰ࣌ وَلَا يَسْتَقْدِمُونَ࣌', 'ولكل أمة ࡰجل࣌ فإذا جاء اجلهم لا يستخرون ساعة࣌ ولا يستقدمون࣌', NULL, 154, 'local:warsh-text.json'),
  ('warsh-7-33', 'warsh', 7, 33, 'يَٰبَنِےٓ ءَادَمَ إِمَّا يَاتِيَنَّكُمْ رُسُلࣱ مِّنكُمْ يَقُصُّونَ عَلَيْكُمُۥٓ ءَايَٰتِے فَمَنِ ࡴٜتَّقٜىٰ وَأَصْلَحَ فَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ࣌', 'يبنے ءادم إما ياتينكم رسل منكم يقصون عليكم ءايتے فمن ࡴتقى وأصلح فلا خوف عليهم ولا هم يحزنون࣌', NULL, 154, 'local:warsh-text.json'),
  ('warsh-7-34', 'warsh', 7, 34, 'وَالذِينَ كَذَّبُواْ بِـَٔايَٰتِنَا وَاسْتَكْبَرُواْ عَنْهَآ أُوْلَٰٓئِكَ أَصْحَٰبُ ࡲ۬لنّٜارِ هُمْ فِيهَا خَٰلِدُونَ࣌', 'والذين كذبوا بايتنا واستكبروا عنها أولئك أصحب ࡲلنار هم فيها خلدون࣌', NULL, 154, 'local:warsh-text.json'),
  ('warsh-7-35', 'warsh', 7, 35, 'فَمَنَ ࡰظْلَمُ مِمَّنِ ࡴٜفْتَرٜىٰ عَلَى ࡰ۬للَّهِ كَذِباً ࡰوْ كَذَّبَ بِـَٔايَٰتِهِۦٓ࣌ أُوْلَٰٓئِكَ يَنَالُهُمْ نَصِيبُهُم مِّنَ ࡰ۬لْكِتَٰبِ࣌ حَتَّىٰٓ إِذَا جَآءَتْهُمْ رُسُلُنَا يَتَوَفَّوْنَهُمْ قَالُوٓاْ أَيْنَ مَا كُنتُمْ تَدْعُونَ مِن دُونِ ࡴ۬للَّهِ قَالُواْ ضَلُّواْ عَنَّا࣌ وَشَهِدُواْ عَلَىٰٓ أَنفُسِهِمُۥٓ أَنَّهُمْ كَانُواْ كٜـٰفِرِينَ࣌', 'فمن ࡰظلم ممن ࡴفترى على ࡰلله كذبا ࡰو كذب بايته࣌ أولئك ينالهم نصيبهم من ࡰلكتب࣌ حتى إذا جاءتهم رسلنا يتوفونهم قالوا أين ما كنتم تدعون من دون ࡴلله قالوا ضلوا عنا࣌ وشهدوا على أنفسهم أنهم كانوا كفرين࣌', NULL, 154, 'local:warsh-text.json'),
  ('warsh-7-36', 'warsh', 7, 36, 'قَالَ ࡸَدْخُلُواْ فِےٓ أُمَمࣲ قَدْ خَلَتْ مِن قَبْلِكُم مِّنَ ࡰ۬لْجِنِّ وَالِانسِ فِے ࡴ۬لنّٜارِ࣌ كُلَّمَا دَخَلَتُ ࡳمَّةࣱ لَّعَنَتُ ࡳخْتَهَا࣌ حَتَّىٰٓ إِذَا ࡰٜدَّارَكُواْ فِيهَا جَمِيعاࣰ قَالَتُ ࡳخْرٜيٰهُمْ لِأُولٜيٰهُمْ رَبَّنَا هَٰٓؤُلَآءِ ࡶَضَلُّونَا فَـَٔاتِهِمْ عَذَاباࣰ ضِعْفاࣰ مِّنَ ࡰ۬لنّٜارِ࣌', 'قال ࡸدخلوا فے أمم قد خلت من قبلكم من ࡰلجن والانس فے ࡴلنار࣌ كلما دخلت ࡳمة لعنت ࡳختها࣌ حتى إذا ࡰداركوا فيها جميعا قالت ࡳخريهم لأوليهم ربنا هؤلاء ࡶضلونا فاتهم عذابا ضعفا من ࡰلنار࣌', NULL, 155, 'local:warsh-text.json'),
  ('warsh-7-37', 'warsh', 7, 37, 'قَالَ لِكُلࣲّ ضِعْفࣱ࣌ وَلَٰكِن لَّا تَعْلَمُونَ࣌', 'قال لكل ضعف࣌ ولكن لا تعلمون࣌', NULL, 155, 'local:warsh-text.json'),
  ('warsh-7-38', 'warsh', 7, 38, '۞ وَقَالَتُ ࡳولٜيٰهُمْ لِأُخْرٜيٰهُمْ فَمَا كَانَ لَكُمْ عَلَيْنَا مِن فَضْلࣲ فَذُوقُواْ ࡲ۬لْعَذَابَ بِمَا كُنتُمْ تَكْسِبُونَ࣌', 'وقالت ࡳوليهم لأخريهم فما كان لكم علينا من فضل فذوقوا ࡲلعذاب بما كنتم تكسبون࣌', NULL, 155, 'local:warsh-text.json'),
  ('warsh-7-39', 'warsh', 7, 39, 'إِنَّ ࡰ۬لذِينَ كَذَّبُواْ بِـَٔايَٰتِنَا وَاسْتَكْبَرُواْ عَنْهَا لَا تُفَتَّحُ لَهُمُۥٓ أَبْوَٰبُ ࡲ۬لسَّمَآءِ وَلَا يَدْخُلُونَ ࡰ۬لْجَنَّةَ حَتَّىٰ يَلِجَ ࡰ۬لْجَمَلُ فِے سَمِّ ࡴ۬لْخِيَاطِ࣌ وَكَذَٰلِكَ نَجْزِے ࡴ۬لْمُجْرِمِينَ࣌', 'إن ࡰلذين كذبوا بايتنا واستكبروا عنها لا تفتح لهم أبوب ࡲلسماء ولا يدخلون ࡰلجنة حتى يلج ࡰلجمل فے سم ࡴلخياط࣌ وكذلك نجزے ࡴلمجرمين࣌', NULL, 155, 'local:warsh-text.json'),
  ('warsh-7-40', 'warsh', 7, 40, 'لَهُم مِّن جَهَنَّمَ مِهَادࣱ࣌ وَمِن فَوْقِهِمْ غَوَاشࣲ࣌ وَكَذَٰلِكَ نَجْزِے ࡴ۬لظَّٰلِمِينَ࣌', 'لهم من جهنم مهاد࣌ ومن فوقهم غواش࣌ وكذلك نجزے ࡴلظلمين࣌', NULL, 155, 'local:warsh-text.json'),
  ('warsh-7-41', 'warsh', 7, 41, 'وَالذِينَ ءَامَنُواْ وَعَمِلُواْ ࡲ۬لصَّٰلِحَٰتِ لَا نُكَلِّفُ نَفْساً ࡴلَّا وُسْعَهَآ࣌ أُوْلَٰٓئِكَ أَصْحَٰبُ ࡲ۬لْجَنَّةِ هُمْ فِيهَا خَٰلِدُونَ࣌', 'والذين ءامنوا وعملوا ࡲلصلحت لا نكلف نفسا ࡴلا وسعها࣌ أولئك أصحب ࡲلجنة هم فيها خلدون࣌', NULL, 155, 'local:warsh-text.json'),
  ('warsh-7-42', 'warsh', 7, 42, 'وَنَزَعْنَا مَا فِے صُدُورِهِم مِّنْ غِلࣲّ تَجْرِے مِن تَحْتِهِمُ ࡲ۬لَانْهَٰرُ࣌ وَقَالُواْ ࡲ۬لْحَمْدُ لِلهِ ࡴ۬لذِے هَدٜيٰنَا لِهَٰذَا࣌ وَمَا كُنَّا لِنَهْتَدِيَ لَوْلَآ أَنْ هَدٜيٰنَا ࡰ۬للَّهُ࣌ لَقَدْ جَآءَتْ رُسُلُ رَبِّنَا بِالْحَقِّ࣌ وَنُودُوٓاْ أَن تِلْكُمُ ࡲ۬لْجَنَّةُ أُورِثْتُمُوهَا بِمَا كُنتُمْ تَعْمَلُونَ࣌', 'ونزعنا ما فے صدورهم من غل تجرے من تحتهم ࡲلانهر࣌ وقالوا ࡲلحمد لله ࡴلذے هدينا لهذا࣌ وما كنا لنهتدي لولا أن هدينا ࡰلله࣌ لقد جاءت رسل ربنا بالحق࣌ ونودوا أن تلكم ࡲلجنة أورثتموها بما كنتم تعملون࣌', NULL, 155, 'local:warsh-text.json'),
  ('warsh-7-43', 'warsh', 7, 43, 'وَنَادٜىٰٓ أَصْحَٰبُ ࡲ۬لْجَنَّةِ أَصْحَٰبَ ࡰ۬لنّٜارِ أَن قَدْ وَجَدْنَا مَا وَعَدَنَا رَبُّنَا حَقّاࣰ فَهَلْ وَجَدتُّم مَّا وَعَدَ رَبُّكُمْ حَقّاࣰ࣌ قَالُواْ نَعَمْ࣌ فَأَذَّنَ مُوَ۬ذِّنُۢ بَيْنَهُمُۥٓ أَن لَّعْنَةُ ࡲ۬للَّهِ عَلَى ࡰ۬لظَّٰلِمِينَ', 'ونادى أصحب ࡲلجنة أصحب ࡰلنار أن قد وجدنا ما وعدنا ربنا حقا فهل وجدتم ما وعد ربكم حقا࣌ قالوا نعم࣌ فأذن موذن بينهم أن لعنة ࡲلله على ࡰلظلمين', NULL, 156, 'local:warsh-text.json'),
  ('warsh-7-44', 'warsh', 7, 44, 'ࡰ۬لذِينَ يَصُدُّونَ عَن سَبِيلِ ࡴ۬للَّهِ وَيَبْغُونَهَا عِوَجاࣰ وَهُم بِالَاخِرَةِ كَٰفِرُونَ࣌', 'ࡰلذين يصدون عن سبيل ࡴلله ويبغونها عوجا وهم بالاخرة كفرون࣌', NULL, 156, 'local:warsh-text.json'),
  ('warsh-7-45', 'warsh', 7, 45, 'وَبَيْنَهُمَا حِجَابࣱ࣌ وَعَلَى ࡰ۬لَاعْرَافِ رِجَالࣱ يَعْرِفُونَ كُلّاَۢ بِسِيمٜيٰهُمْ࣌ وَنَادَوَاْ ࡰصْحَٰبَ ࡰ۬لْجَنَّةِ أَن سَلَٰمٌ عَلَيْكُمْ࣌ لَمْ يَدْخُلُوهَا وَهُمْ يَطْمَعُونَ࣌', 'وبينهما حجاب࣌ وعلى ࡰلاعراف رجال يعرفون كلا بسيميهم࣌ ونادوا ࡰصحب ࡰلجنة أن سلم عليكم࣌ لم يدخلوها وهم يطمعون࣌', NULL, 156, 'local:warsh-text.json'),
  ('warsh-7-46', 'warsh', 7, 46, '۞ وَإِذَا صُرِفَتَ ࡰبْصَٰرُهُمْ تِلْقَآءَ اصْحَٰبِ ࡴ۬لنّٜارِ قَالُواْ رَبَّنَا لَا تَجْعَلْنَا مَعَ ࡰ۬لْقَوْمِ ࡴ۬لظَّٰلِمِينَ࣌', 'وإذا صرفت ࡰبصرهم تلقاء اصحب ࡴلنار قالوا ربنا لا تجعلنا مع ࡰلقوم ࡴلظلمين࣌', NULL, 156, 'local:warsh-text.json'),
  ('warsh-7-47', 'warsh', 7, 47, 'وَنَادٜىٰٓ أَصْحَٰبُ ࡲ۬لَاعْرَافِ رِجَالاࣰ يَعْرِفُونَهُم بِسِيمٜيٰهُمْ قَالُواْ مَآ أَغْنٜىٰ عَنكُمْ جَمْعُكُمْ وَمَا كُنتُمْ تَسْتَكْبِرُونَ࣌', 'ونادى أصحب ࡲلاعراف رجالا يعرفونهم بسيميهم قالوا ما أغنى عنكم جمعكم وما كنتم تستكبرون࣌', NULL, 156, 'local:warsh-text.json'),
  ('warsh-7-48', 'warsh', 7, 48, 'أَهَٰٓؤُلَآءِ ࡴ۬لذِينَ أَقْسَمْتُمْ لَا يَنَالُهُمُ ࡲ۬للَّهُ بِرَحْمَةٍ࣌ ࡲ࢈دْخُلُواْ ࡲ۬لْجَنَّةَ لَا خَوْفٌ عَلَيْكُمْ وَلَآ أَنتُمْ تَحْزَنُونَ࣌', 'أهؤلاء ࡴلذين أقسمتم لا ينالهم ࡲلله برحمة࣌ ࡲ࢈دخلوا ࡲلجنة لا خوف عليكم ولا أنتم تحزنون࣌', NULL, 156, 'local:warsh-text.json'),
  ('warsh-7-49', 'warsh', 7, 49, 'وَنَادٜىٰٓ أَصْحَٰبُ ࡲ۬لنّٜارِ أَصْحَٰبَ ࡰ۬لْجَنَّةِ أَنَ ࡰفِيضُواْ عَلَيْنَا مِنَ ࡰ۬لْمَآءِ ࡶَوْ مِمَّا رَزَقَكُمُ ࡲ۬للَّهُ࣌ قَالُوٓاْ إِنَّ ࡰ۬للَّهَ حَرَّمَهُمَا عَلَى ࡰ۬لْكٜـٰفِرِينَ', 'ونادى أصحب ࡲلنار أصحب ࡰلجنة أن ࡰفيضوا علينا من ࡰلماء ࡶو مما رزقكم ࡲلله࣌ قالوا إن ࡰلله حرمهما على ࡰلكفرين', NULL, 156, 'local:warsh-text.json'),
  ('warsh-7-50', 'warsh', 7, 50, 'ࡰ۬لذِينَ ࡰٜتَّخَذُواْ دِينَهُمْ لَهْواࣰ وَلَعِباࣰ وَغَرَّتْهُمُ ࡲ۬لْحَيَوٰةُ ࡲ۬لدُّنْيٜا࣌ فَالْيَوْمَ نَنسٜيٰهُمْ كَمَا نَسُواْ لِقَآءَ يَوْمِهِمْ هَٰذَا وَمَا كَانُواْ بِـَٔايَٰتِنَا يَجْحَدُونَ࣌', 'ࡰلذين ࡰتخذوا دينهم لهوا ولعبا وغرتهم ࡲلحيوة ࡲلدنيا࣌ فاليوم ننسيهم كما نسوا لقاء يومهم هذا وما كانوا بايتنا يجحدون࣌', NULL, 156, 'local:warsh-text.json'),
  ('warsh-7-51', 'warsh', 7, 51, 'وَلَقَدْ جِئْنَٰهُم بِكِتَٰبࣲ فَصَّلْنَٰهُ عَلَىٰ عِلْمٍ هُدىࣰ وَرَحْمَةࣰ لِّقَوْمࣲ يُومِنُونَ࣌', 'ولقد جئنهم بكتب فصلنه على علم هدى ورحمة لقوم يومنون࣌', NULL, 157, 'local:warsh-text.json'),
  ('warsh-7-52', 'warsh', 7, 52, 'هَلْ يَنظُرُونَ إِلَّا تَاوِيلَهُۥ࣌ يَوْمَ يَاتِے تَاوِيلُهُۥ يَقُولُ ࡲ۬لذِينَ نَسُوهُ مِن قَبْلُ قَدْ جَآءَتْ رُسُلُ رَبِّنَا بِالْحَقِّ فَهَل لَّنَا مِن شُفَعَآءَ فَيَشْفَعُواْ لَنَآ أَوْ نُرَدُّ فَنَعْمَلَ غَيْرَ ࡰ۬لذِے كُنَّا نَعْمَلُ࣌ قَدْ خَسِرُوٓاْ أَنفُسَهُمْ وَضَلَّ عَنْهُم مَّا كَانُواْ يَفْتَرُونَ࣌', 'هل ينظرون إلا تاويله࣌ يوم ياتے تاويله يقول ࡲلذين نسوه من قبل قد جاءت رسل ربنا بالحق فهل لنا من شفعاء فيشفعوا لنا أو نرد فنعمل غير ࡰلذے كنا نعمل࣌ قد خسروا أنفسهم وضل عنهم ما كانوا يفترون࣌', NULL, 157, 'local:warsh-text.json'),
  ('warsh-7-53', 'warsh', 7, 53, 'إِنَّ رَبَّكُمُ ࡲ۬للَّهُ ࡲ۬لذِے خَلَقَ ࡰ۬لسَّمَٰوَٰتِ وَالَارْضَ فِے سِتَّةِ أَيَّامࣲ ثُمَّ ࡰٜسْتَوٜىٰ عَلَى ࡰ۬لْعَرْشِ࣌ يُغْشِے ࡴ۬ليْلَ ࡰ۬لنَّهَارَ يَطْلُبُهُۥ حَثِيثاࣰ وَالشَّمْسَ وَالْقَمَرَ وَالنُّجُومَ مُسَخَّرَٰتِۢ بِأَمْرِهِۦٓ࣌ أَلَا لَهُ ࡲ۬لْخَلْقُ وَالَامْرُ࣌ تَبَٰرَكَ ࡰ۬للَّهُ رَبُّ ࡲ۬لْعَٰلَمِينَ࣌', 'إن ربكم ࡲلله ࡲلذے خلق ࡰلسموت والارض فے ستة أيام ثم ࡰستوى على ࡰلعرش࣌ يغشے ࡴليل ࡰلنهار يطلبه حثيثا والشمس والقمر والنجوم مسخرت بأمره࣌ ألا له ࡲلخلق والامر࣌ تبرك ࡰلله رب ࡲلعلمين࣌', NULL, 157, 'local:warsh-text.json'),
  ('warsh-7-54', 'warsh', 7, 54, 'ࡸَدْعُواْ رَبَّكُمْ تَضَرُّعاࣰ وَخُفْيَةً࣌ ࡴنَّهُۥ لَا يُحِبُّ ࡲ۬لْمُعْتَدِينَ࣌', 'ࡸدعوا ربكم تضرعا وخفية࣌ ࡴنه لا يحب ࡲلمعتدين࣌', NULL, 157, 'local:warsh-text.json'),
  ('warsh-7-55', 'warsh', 7, 55, 'وَلَا تُفْسِدُواْ فِے ࡴ۬لَارْضِ بَعْدَ إِصْلَٰحِهَا࣌ وَادْعُوهُ خَوْفاࣰ وَطَمَعاً࣌ ࡴنَّ رَحْمَتَ ࡰ۬للَّهِ قَرِيبࣱ مِّنَ ࡰ۬لْمُحْسِنِينَ࣌', 'ولا تفسدوا فے ࡴلارض بعد إصلحها࣌ وادعوه خوفا وطمعا࣌ ࡴن رحمت ࡰلله قريب من ࡰلمحسنين࣌', NULL, 157, 'local:warsh-text.json'),
  ('warsh-7-56', 'warsh', 7, 56, '۞ وَهُوَ ࡰ۬لذِے يُرْسِلُ ࡲ۬لرِّيَٰحَ نُشُراَۢ بَيْنَ يَدَےْ رَحْمَتِهِۦ࣌ حَتَّىٰٓ إِذَآ أَقَلَّتْ سَحَاباࣰ ثِقَالاࣰ سُقْنَٰهُ لِبَلَدࣲ مَّيِّتࣲ فَأَنزَلْنَا بِهِ ࡴ۬لْمَآءَ فَأَخْرَجْنَا بِهِۦ مِن كُلِّ ࡴ۬لثَّمَرَٰتِ࣌ كَذَٰلِكَ نُخْرِجُ ࡲ۬لْمَوْتٜىٰ لَعَلَّكُمْ تَذَّكَّرُونَ࣌', 'وهو ࡰلذے يرسل ࡲلريح نشرا بين يدے رحمته࣌ حتى إذا أقلت سحابا ثقالا سقنه لبلد ميت فأنزلنا به ࡴلماء فأخرجنا به من كل ࡴلثمرت࣌ كذلك نخرج ࡲلموتى لعلكم تذكرون࣌', NULL, 157, 'local:warsh-text.json'),
  ('warsh-7-57', 'warsh', 7, 57, 'وَالْبَلَدُ ࡲ۬لطَّيِّبُ يَخْرُجُ نَبَاتُهُۥ بِإِذْنِ رَبِّهِۦ࣌ وَالذِے خَبُثَ لَا يَخْرُجُ إِلَّا نَكِداࣰ࣌ كَذَٰلِكَ نُصَرِّفُ ࡲ۬لَايَٰتِ لِقَوْمࣲ يَشْكُرُونَ࣌', 'والبلد ࡲلطيب يخرج نباته بإذن ربه࣌ والذے خبث لا يخرج إلا نكدا࣌ كذلك نصرف ࡲلايت لقوم يشكرون࣌', NULL, 158, 'local:warsh-text.json'),
  ('warsh-7-58', 'warsh', 7, 58, 'لَقَدَ ࡰرْسَلْنَا نُوحاً ࡴلَىٰ قَوْمِهِۦ فَقَالَ يَٰقَوْمِ ࡴ࢈عْبُدُواْ ࡲ۬للَّهَ مَا لَكُم مِّنِ ࡴلَٰهٍ غَيْرُهُۥٓ࣌ إِنِّيَ أَخَافُ عَلَيْكُمْ عَذَابَ يَوْمٍ عَظِيمࣲ࣌', 'لقد ࡰرسلنا نوحا ࡴلى قومه فقال يقوم ࡴ࢈عبدوا ࡲلله ما لكم من ࡴله غيره࣌ إني أخاف عليكم عذاب يوم عظيم࣌', NULL, 158, 'local:warsh-text.json'),
  ('warsh-7-59', 'warsh', 7, 59, 'قَالَ ࡰ۬لْمَلَأُ مِن قَوْمِهِۦٓ إِنَّا لَنَرٜيٰكَ فِے ضَلَٰلࣲ مُّبِينࣲ࣌', 'قال ࡰلملأ من قومه إنا لنريك فے ضلل مبين࣌', NULL, 158, 'local:warsh-text.json'),
  ('warsh-7-60', 'warsh', 7, 60, 'قَالَ يَٰقَوْمِ لَيْسَ بِے ضَلَٰلَةࣱ وَلَٰكِنِّے رَسُولࣱ مِّن رَّبِّ ࡴ۬لْعَٰلَمِينَ࣌', 'قال يقوم ليس بے ضللة ولكنے رسول من رب ࡴلعلمين࣌', NULL, 158, 'local:warsh-text.json'),
  ('warsh-7-61', 'warsh', 7, 61, 'أُبَلِّغُكُمْ رِسَٰلَٰتِ رَبِّے وَأَنصَحُ لَكُمْ وَأَعْلَمُ مِنَ ࡰ۬للَّهِ مَا لَا تَعْلَمُونَ࣌', 'أبلغكم رسلت ربے وأنصح لكم وأعلم من ࡰلله ما لا تعلمون࣌', NULL, 158, 'local:warsh-text.json'),
  ('warsh-7-62', 'warsh', 7, 62, 'أَوَعَجِبْتُمُۥٓ أَن جَآءَكُمْ ذِكْرࣱ مِّن رَّبِّكُمْ عَلَىٰ رَجُلࣲ مِّنكُمْ لِيُنذِرَكُمْ وَلِتَتَّقُواْ وَلَعَلَّكُمْ تُرْحَمُونَ࣌', 'أوعجبتم أن جاءكم ذكر من ربكم على رجل منكم لينذركم ولتتقوا ولعلكم ترحمون࣌', NULL, 158, 'local:warsh-text.json'),
  ('warsh-7-63', 'warsh', 7, 63, 'فَكَذَّبُوهُ فَأَنجَيْنَٰهُ وَالذِينَ مَعَهُۥ فِے ࡴ۬لْفُلْكِ࣌ وَأَغْرَقْنَا ࡰ۬لذِينَ كَذَّبُواْ بِـَٔايَٰتِنَآ࣌ إِنَّهُمْ كَانُواْ قَوْماً عَمِينَ࣌', 'فكذبوه فأنجينه والذين معه فے ࡴلفلك࣌ وأغرقنا ࡰلذين كذبوا بايتنا࣌ إنهم كانوا قوما عمين࣌', NULL, 158, 'local:warsh-text.json'),
  ('warsh-7-64', 'warsh', 7, 64, 'وَإِلَىٰ عَادٍ ࡰخَاهُمْ هُوداࣰ࣌ قَالَ يَٰقَوْمِ ࡴ࢈عْبُدُواْ ࡲ۬للَّهَ مَا لَكُم مِّنِ ࡴلَٰهٍ غَيْرُهُۥٓ࣌ أَفَلَا تَتَّقُونَ࣌', 'وإلى عاد ࡰخاهم هودا࣌ قال يقوم ࡴ࢈عبدوا ࡲلله ما لكم من ࡴله غيره࣌ أفلا تتقون࣌', NULL, 158, 'local:warsh-text.json'),
  ('warsh-7-65', 'warsh', 7, 65, 'قَالَ ࡰ۬لْمَلَأُ ࡲ۬لذِينَ كَفَرُواْ مِن قَوْمِهِۦٓ إِنَّا لَنَرٜيٰكَ فِے سَفَاهَةࣲ وَإِنَّا لَنَظُنُّكَ مِنَ ࡰ۬لْكَٰذِبِينَ࣌', 'قال ࡰلملأ ࡲلذين كفروا من قومه إنا لنريك فے سفاهة وإنا لنظنك من ࡰلكذبين࣌', NULL, 158, 'local:warsh-text.json'),
  ('warsh-7-66', 'warsh', 7, 66, 'قَالَ يَٰقَوْمِ لَيْسَ بِے سَفَاهَةࣱ وَلَٰكِنِّے رَسُولࣱ مِّن رَّبِّ ࡴ۬لْعَٰلَمِينَ࣌', 'قال يقوم ليس بے سفاهة ولكنے رسول من رب ࡴلعلمين࣌', NULL, 158, 'local:warsh-text.json'),
  ('warsh-7-67', 'warsh', 7, 67, 'أُبَلِّغُكُمْ رِسَٰلَٰتِ رَبِّے وَأَنَا لَكُمْ نَاصِحٌ ࡰمِينٌ࣌', 'أبلغكم رسلت ربے وأنا لكم ناصح ࡰمين࣌', NULL, 159, 'local:warsh-text.json'),
  ('warsh-7-68', 'warsh', 7, 68, '۞ ࡰوَعَجِبْتُمُۥٓ أَن جَآءَكُمْ ذِكْرࣱ مِّن رَّبِّكُمْ عَلَىٰ رَجُلࣲ مِّنكُمْ لِيُنذِرَكُمْ࣌ وَاذْكُرُوٓاْ إِذْ جَعَلَكُمْ خُلَفَآءَ مِنۢ بَعْدِ قَوْمِ نُوحࣲ وَزَادَكُمْ فِے ࡴ۬لْخَلْقِ بَصْطَةࣰ࣌ فَاذْكُرُوٓاْ ءَالَآءَ ࡰ۬للَّهِ لَعَلَّكُمْ تُفْلِحُونَ࣌', 'ࡰوعجبتم أن جاءكم ذكر من ربكم على رجل منكم لينذركم࣌ واذكروا إذ جعلكم خلفاء من بعد قوم نوح وزادكم فے ࡴلخلق بصطة࣌ فاذكروا ءالاء ࡰلله لعلكم تفلحون࣌', NULL, 159, 'local:warsh-text.json'),
  ('warsh-7-69', 'warsh', 7, 69, 'قَالُوٓاْ أَجِئْتَنَا لِنَعْبُدَ ࡰ۬للَّهَ وَحْدَهُۥ وَنَذَرَ مَا كَانَ يَعْبُدُ ءَابَآؤُنَا فَاتِنَا بِمَا تَعِدُنَآ إِن كُنتَ مِنَ ࡰ۬لصَّٰدِقِينَ࣌', 'قالوا أجئتنا لنعبد ࡰلله وحده ونذر ما كان يعبد ءاباؤنا فاتنا بما تعدنا إن كنت من ࡰلصدقين࣌', NULL, 159, 'local:warsh-text.json'),
  ('warsh-7-70', 'warsh', 7, 70, 'قَالَ قَدْ وَقَعَ عَلَيْكُم مِّن رَّبِّكُمْ رِجْسࣱ وَغَضَبٌ࣌ ࡰتُجَٰدِلُونَنِے فِےٓ أَسْمَآءࣲ سَمَّيْتُمُوهَآ أَنتُمْ وَءَابَآؤُكُم مَّا نَزَّلَ ࡰ۬للَّهُ بِهَا مِن سُلْطَٰنࣲ࣌ فَانتَظِرُوٓاْ࣌ إِنِّے مَعَكُم مِّنَ ࡰ۬لْمُنتَظِرِينَ࣌', 'قال قد وقع عليكم من ربكم رجس وغضب࣌ ࡰتجدلوننے فے أسماء سميتموها أنتم وءاباؤكم ما نزل ࡰلله بها من سلطن࣌ فانتظروا࣌ إنے معكم من ࡰلمنتظرين࣌', NULL, 159, 'local:warsh-text.json'),
  ('warsh-7-71', 'warsh', 7, 71, 'فَأَنجَيْنَٰهُ وَالذِينَ مَعَهُۥ بِرَحْمَةࣲ مِّنَّا وَقَطَعْنَا دَابِرَ ࡰ۬لذِينَ كَذَّبُواْ بِـَٔايَٰتِنَا وَمَا كَانُواْ مُومِنِينَ࣌', 'فأنجينه والذين معه برحمة منا وقطعنا دابر ࡰلذين كذبوا بايتنا وما كانوا مومنين࣌', NULL, 159, 'local:warsh-text.json'),
  ('warsh-7-72', 'warsh', 7, 72, 'وَإِلَىٰ ثَمُودَ أَخَاهُمْ صَٰلِحاࣰ࣌ قَالَ يَٰقَوْمِ ࡴ࢈عْبُدُواْ ࡲ۬للَّهَ مَا لَكُم مِّنِ ࡴلَٰهٍ غَيْرُهُۥ࣌ قَدْ جَآءَتْكُم بَيِّنَةࣱ مِّن رَّبِّكُمْ࣌ هَٰذِهِۦ نَاقَةُ ࡲ۬للَّهِ لَكُمُۥٓ ءَايَةࣰ࣌ فَذَرُوهَا تَاكُلْ فِےٓ أَرْضِ ࡴ۬للَّهِ࣌ وَلَا تَمَسُّوهَا بِسُوٓءࣲ فَيَاخُذَكُمْ عَذَابٌ ࡰلِيمࣱ࣌', 'وإلى ثمود أخاهم صلحا࣌ قال يقوم ࡴ࢈عبدوا ࡲلله ما لكم من ࡴله غيره࣌ قد جاءتكم بينة من ربكم࣌ هذه ناقة ࡲلله لكم ءاية࣌ فذروها تاكل فے أرض ࡴلله࣌ ولا تمسوها بسوء فياخذكم عذاب ࡰليم࣌', NULL, 159, 'local:warsh-text.json'),
  ('warsh-7-73', 'warsh', 7, 73, 'وَاذْكُرُوٓاْ إِذْ جَعَلَكُمْ خُلَفَآءَ مِنۢ بَعْدِ عَادࣲ وَبَوَّأَكُمْ فِے ࡴ۬لَارْضِ تَتَّخِذُونَ مِن سُهُولِهَا قُصُوراࣰ وَتَنْحِتُونَ ࡰ۬لْجِبَالَ بُيُوتاࣰ࣌ فَاذْكُرُوٓاْ ءَالَآءَ ࡰ۬للَّهِ࣌ وَلَا تَعْثَوْاْ فِے ࡴ۬لَارْضِ مُفْسِدِينَ࣌', 'واذكروا إذ جعلكم خلفاء من بعد عاد وبوأكم فے ࡴلارض تتخذون من سهولها قصورا وتنحتون ࡰلجبال بيوتا࣌ فاذكروا ءالاء ࡰلله࣌ ولا تعثوا فے ࡴلارض مفسدين࣌', NULL, 160, 'local:warsh-text.json'),
  ('warsh-7-74', 'warsh', 7, 74, 'قَالَ ࡰ۬لْمَلَأُ ࡲ۬لذِينَ ࡰٜسْتَكْبَرُواْ مِن قَوْمِهِۦ لِلذِينَ ࡸَسْتُضْعِفُواْ لِمَنَ اٰمَنَ مِنْهُمُۥٓ أَتَعْلَمُونَ أَنَّ صَٰلِحاࣰ مُّرْسَلࣱ مِّن رَّبِّهِۦ࣌ قَالُوٓاْ إِنَّا بِمَآ أُرْسِلَ بِهِۦ مُومِنُونَ࣌', 'قال ࡰلملأ ࡲلذين ࡰستكبروا من قومه للذين ࡸستضعفوا لمن امن منهم أتعلمون أن صلحا مرسل من ربه࣌ قالوا إنا بما أرسل به مومنون࣌', NULL, 160, 'local:warsh-text.json'),
  ('warsh-7-75', 'warsh', 7, 75, 'قَالَ ࡰ۬لذِينَ ࡰٜسْتَكْبَرُوٓاْ إِنَّا بِالذِےٓ ءَامَنتُم بِهِۦ كَٰفِرُونَ࣌', 'قال ࡰلذين ࡰستكبروا إنا بالذے ءامنتم به كفرون࣌', NULL, 160, 'local:warsh-text.json'),
  ('warsh-7-76', 'warsh', 7, 76, '۞ فَعَقَرُواْ ࡲ۬لنَّاقَةَ وَعَتَوْاْ عَنَ ࡰمْرِ رَبِّهِمْ࣌ وَقَالُواْ يَٰصَٰلِحُ ࡲٜيتِنَا بِمَا تَعِدُنَآ إِن كُنتَ مِنَ ࡰ۬لْمُرْسَلِينَ࣌', 'فعقروا ࡲلناقة وعتوا عن ࡰمر ربهم࣌ وقالوا يصلح ࡲيتنا بما تعدنا إن كنت من ࡰلمرسلين࣌', NULL, 160, 'local:warsh-text.json'),
  ('warsh-7-77', 'warsh', 7, 77, 'فَأَخَذَتْهُمُ ࡲ۬لرَّجْفَةُ فَأَصْبَحُواْ فِے دٜارِهِمْ جَٰثِمِينَ࣌', 'فأخذتهم ࡲلرجفة فأصبحوا فے دارهم جثمين࣌', NULL, 160, 'local:warsh-text.json'),
  ('warsh-7-78', 'warsh', 7, 78, 'فَتَوَلّٜىٰ عَنْهُمْ وَقَالَ يَٰقَوْمِ لَقَدَ ࡰبْلَغْتُكُمْ رِسَالَةَ رَبِّے وَنَصَحْتُ لَكُمْ࣌ وَلَٰكِن لَّا تُحِبُّونَ ࡰ۬لنَّٰصِحِينَ࣌', 'فتولى عنهم وقال يقوم لقد ࡰبلغتكم رسالة ربے ونصحت لكم࣌ ولكن لا تحبون ࡰلنصحين࣌', NULL, 160, 'local:warsh-text.json'),
  ('warsh-7-79', 'warsh', 7, 79, 'وَلُوطاً ࡴذْ قَالَ لِقَوْمِهِۦٓ أَتَاتُونَ ࡰ۬لْفَٰحِشَةَ مَا سَبَقَكُم بِهَا مِنَ ࡰحَدࣲ مِّنَ ࡰ۬لْعَٰلَمِينَ࣌', 'ولوطا ࡴذ قال لقومه أتاتون ࡰلفحشة ما سبقكم بها من ࡰحد من ࡰلعلمين࣌', NULL, 160, 'local:warsh-text.json'),
  ('warsh-7-80', 'warsh', 7, 80, 'إِنَّكُمْ لَتَاتُونَ ࡰ۬لرِّجَالَ شَهْوَةࣰ مِّن دُونِ ࡴ۬لنِّسَآءِ࣌ بَلَ ࡰنتُمْ قَوْمࣱ مُّسْرِفُونَ࣌', 'إنكم لتاتون ࡰلرجال شهوة من دون ࡴلنساء࣌ بل ࡰنتم قوم مسرفون࣌', NULL, 160, 'local:warsh-text.json'),
  ('warsh-7-81', 'warsh', 7, 81, 'وَمَا كَانَ جَوَابَ قَوْمِهِۦٓ إِلَّآ أَن قَالُوٓاْ أَخْرِجُوهُم مِّن قَرْيَتِكُمُۥٓ࣌ إِنَّهُمُۥٓ أُنَاسࣱ يَتَطَهَّرُونَ࣌', 'وما كان جواب قومه إلا أن قالوا أخرجوهم من قريتكم࣌ إنهم أناس يتطهرون࣌', NULL, 161, 'local:warsh-text.json'),
  ('warsh-7-82', 'warsh', 7, 82, 'فَأَنجَيْنَٰهُ وَأَهْلَهُۥٓ إِلَّا ࡰٜمْرَأَتَهُۥ كَانَتْ مِنَ ࡰ۬لْغَٰبِرِينَ࣌', 'فأنجينه وأهله إلا ࡰمرأته كانت من ࡰلغبرين࣌', NULL, 161, 'local:warsh-text.json'),
  ('warsh-7-83', 'warsh', 7, 83, 'وَأَمْطَرْنَا عَلَيْهِم مَّطَراࣰ࣌ فَانظُرْ كَيْفَ كَانَ عَٰقِبَةُ ࡲ۬لْمُجْرِمِينَ࣌', 'وأمطرنا عليهم مطرا࣌ فانظر كيف كان عقبة ࡲلمجرمين࣌', NULL, 161, 'local:warsh-text.json'),
  ('warsh-7-84', 'warsh', 7, 84, 'وَإِلَىٰ مَدْيَنَ أَخَاهُمْ شُعَيْباࣰ࣌ قَالَ يَٰقَوْمِ ࡴ࢈عْبُدُواْ ࡲ۬للَّهَ مَا لَكُم مِّنِ ࡴلَٰهٍ غَيْرُهُۥ࣌ قَدْ جَآءَتْكُم بَيِّنَةࣱ مِّن رَّبِّكُمْ࣌ فَأَوْفُواْ ࡲ۬لْكَيْلَ وَالْمِيزَانَ࣌ وَلَا تَبْخَسُواْ ࡲ۬لنَّاسَ أَشْيَآءَهُمْ࣌ وَلَا تُفْسِدُواْ فِے ࡴ۬لَارْضِ بَعْدَ إِصْلَٰحِهَا࣌ ذَٰلِكُمْ خَيْرࣱ لَّكُمُۥٓ إِن كُنتُم مُّومِنِينَ࣌', 'وإلى مدين أخاهم شعيبا࣌ قال يقوم ࡴ࢈عبدوا ࡲلله ما لكم من ࡴله غيره࣌ قد جاءتكم بينة من ربكم࣌ فأوفوا ࡲلكيل والميزان࣌ ولا تبخسوا ࡲلناس أشياءهم࣌ ولا تفسدوا فے ࡴلارض بعد إصلحها࣌ ذلكم خير لكم إن كنتم مومنين࣌', NULL, 161, 'local:warsh-text.json'),
  ('warsh-7-85', 'warsh', 7, 85, 'وَلَا تَقْعُدُواْ بِكُلِّ صِرَٰطࣲ تُوعِدُونَ وَتَصُدُّونَ عَن سَبِيلِ ࡴ۬للَّهِ مَنَ اٰمَنَ بِهِۦ وَتَبْغُونَهَا عِوَجاࣰ࣌ وَاذْكُرُوٓاْ إِذْ كُنتُمْ قَلِيلاࣰ فَكَثَّرَكُمْ࣌ وَانظُرُواْ كَيْفَ كَانَ عَٰقِبَةُ ࡲ۬لْمُفْسِدِينَ࣌', 'ولا تقعدوا بكل صرط توعدون وتصدون عن سبيل ࡴلله من امن به وتبغونها عوجا࣌ واذكروا إذ كنتم قليلا فكثركم࣌ وانظروا كيف كان عقبة ࡲلمفسدين࣌', NULL, 161, 'local:warsh-text.json'),
  ('warsh-7-86', 'warsh', 7, 86, 'وَإِن كَانَ طَآئِفَةࣱ مِّنكُمُۥٓ ءَامَنُواْ بِالذِےٓ أُرْسِلْتُ بِهِۦ وَطَآئِفَةࣱ لَّمْ يُومِنُواْ فَاصْبِرُواْ حَتَّىٰ يَحْكُمَ ࡰ۬للَّهُ بَيْنَنَا࣌ وَهُوَ خَيْرُ ࡲ۬لْحَٰكِمِينَ࣌', 'وإن كان طائفة منكم ءامنوا بالذے أرسلت به وطائفة لم يومنوا فاصبروا حتى يحكم ࡰلله بيننا࣌ وهو خير ࡲلحكمين࣌', NULL, 161, 'local:warsh-text.json'),
  ('warsh-7-87', 'warsh', 7, 87, '۞ قَالَ ࡰ۬لْمَلَأُ ࡲ۬لذِينَ ࡰٜسْتَكْبَرُواْ مِن قَوْمِهِۦ لَنُخْرِجَنَّكَ يَٰشُعَيْبُ وَالذِينَ ءَامَنُواْ مَعَكَ مِن قَرْيَتِنَآ أَوْ لَتَعُودُنَّ فِے مِلَّتِنَا࣌ قَالَ أَوَلَوْ كُنَّا كَٰرِهِينَ࣌', 'قال ࡰلملأ ࡲلذين ࡰستكبروا من قومه لنخرجنك يشعيب والذين ءامنوا معك من قريتنا أو لتعودن فے ملتنا࣌ قال أولو كنا كرهين࣌', NULL, 162, 'local:warsh-text.json'),
  ('warsh-7-88', 'warsh', 7, 88, 'قَدِ ࡴٜفْتَرَيْنَا عَلَى ࡰ۬للَّهِ كَذِباً ࡴنْ عُدْنَا فِے مِلَّتِكُم بَعْدَ إِذْ نَجّٜيٰنَا ࡰ۬للَّهُ مِنْهَا࣌ وَمَا يَكُونُ لَنَآ أَن نَّعُودَ فِيهَآ إِلَّآ أَنْ يَّشَآءَ ࡰ۬للَّهُ رَبُّنَا࣌ وَسِعَ رَبُّنَا كُلَّ شَےْءٍ عِلْماً࣌ عَلَى ࡰ۬للَّهِ تَوَكَّلْنَا࣌ رَبَّنَا ࡰٜفْتَحْ بَيْنَنَا وَبَيْنَ قَوْمِنَا بِالْحَقِّ࣌ وَأَنتَ خَيْرُ ࡲ۬لْفَٰتِحِينَ࣌', 'قد ࡴفترينا على ࡰلله كذبا ࡴن عدنا فے ملتكم بعد إذ نجينا ࡰلله منها࣌ وما يكون لنا أن نعود فيها إلا أن يشاء ࡰلله ربنا࣌ وسع ربنا كل شےء علما࣌ على ࡰلله توكلنا࣌ ربنا ࡰفتح بيننا وبين قومنا بالحق࣌ وأنت خير ࡲلفتحين࣌', NULL, 162, 'local:warsh-text.json'),
  ('warsh-7-89', 'warsh', 7, 89, 'وَقَالَ ࡰ۬لْمَلَأُ ࡲ۬لذِينَ كَفَرُواْ مِن قَوْمِهِۦ لَئِنِ ࡴٜتَّبَعْتُمْ شُعَيْباً ࡴنَّكُمُۥٓ إِذاࣰ لَّخَٰسِرُونَ࣌', 'وقال ࡰلملأ ࡲلذين كفروا من قومه لئن ࡴتبعتم شعيبا ࡴنكم إذا لخسرون࣌', NULL, 162, 'local:warsh-text.json'),
  ('warsh-7-90', 'warsh', 7, 90, 'فَأَخَذَتْهُمُ ࡲ۬لرَّجْفَةُ فَأَصْبَحُواْ فِے دٜارِهِمْ جَٰثِمِينَ࣌', 'فأخذتهم ࡲلرجفة فأصبحوا فے دارهم جثمين࣌', NULL, 162, 'local:warsh-text.json'),
  ('warsh-7-91', 'warsh', 7, 91, 'ࡰ۬لذِينَ كَذَّبُواْ شُعَيْباࣰ كَأَن لَّمْ يَغْنَوْاْ فِيهَا࣌ ࡰ۬لذِينَ كَذَّبُواْ شُعَيْباࣰ كَانُواْ هُمُ ࡲ۬لْخَٰسِرِينَ࣌', 'ࡰلذين كذبوا شعيبا كأن لم يغنوا فيها࣌ ࡰلذين كذبوا شعيبا كانوا هم ࡲلخسرين࣌', NULL, 162, 'local:warsh-text.json'),
  ('warsh-7-92', 'warsh', 7, 92, 'فَتَوَلّٜىٰ عَنْهُمْ وَقَالَ يَٰقَوْمِ لَقَدَ ࡰبْلَغْتُكُمْ رِسَٰلَٰتِ رَبِّے وَنَصَحْتُ لَكُمْ࣌ فَكَيْفَ ءَاسٜىٰ عَلَىٰ قَوْمࣲ كٜـٰفِرِينَ࣌', 'فتولى عنهم وقال يقوم لقد ࡰبلغتكم رسلت ربے ونصحت لكم࣌ فكيف ءاسى على قوم كفرين࣌', NULL, 162, 'local:warsh-text.json'),
  ('warsh-7-93', 'warsh', 7, 93, 'وَمَآ أَرْسَلْنَا فِے قَرْيَةࣲ مِّن نَّبِےٓءٍ ࡴلَّآ أَخَذْنَآ أَهْلَهَا بِالْبَأْسَآءِ وَالضَّرَّآءِ لَعَلَّهُمْ يَضَّرَّعُونَ࣌', 'وما أرسلنا فے قرية من نبےء ࡴلا أخذنا أهلها بالبأساء والضراء لعلهم يضرعون࣌', NULL, 162, 'local:warsh-text.json'),
  ('warsh-7-94', 'warsh', 7, 94, 'ثُمَّ بَدَّلْنَا مَكَانَ ࡰ۬لسَّيِّئَةِ ࡴ۬لْحَسَنَةَ حَتَّىٰ عَفَواْ࣌ وَّقَالُواْ قَدْ مَسَّ ءَابَآءَنَا ࡰ۬لضَّرَّآءُ وَالسَّرَّآءُ فَأَخَذْنَٰهُم بَغْتَةࣰ وَهُمْ لَا يَشْعُرُونَ࣌', 'ثم بدلنا مكان ࡰلسيئة ࡴلحسنة حتى عفوا࣌ وقالوا قد مس ءاباءنا ࡰلضراء والسراء فأخذنهم بغتة وهم لا يشعرون࣌', NULL, 162, 'local:warsh-text.json'),
  ('warsh-7-95', 'warsh', 7, 95, 'وَلَوَ ࡰنَّ أَهْلَ ࡰ۬لْقُرٜىٰٓ ءَامَنُواْ وَاتَّقَوْاْ لَفَتَحْنَا عَلَيْهِم بَرَكَٰتࣲ مِّنَ ࡰ۬لسَّمَآءِ وَالَارْضِ࣌ وَلَٰكِن كَذَّبُواْ فَأَخَذْنَٰهُم بِمَا كَانُواْ يَكْسِبُونَ࣌', 'ولو ࡰن أهل ࡰلقرى ءامنوا واتقوا لفتحنا عليهم بركت من ࡰلسماء والارض࣌ ولكن كذبوا فأخذنهم بما كانوا يكسبون࣌', NULL, 163, 'local:warsh-text.json'),
  ('warsh-7-96', 'warsh', 7, 96, 'أَفَأَمِنَ أَهْلُ ࡲ۬لْقُرٜىٰٓ أَنْ يَّاتِيَهُم بَأْسُنَا بَيَٰتاࣰ وَهُمْ نَآئِمُونَ', 'أفأمن أهل ࡲلقرى أن ياتيهم بأسنا بيتا وهم نائمون', NULL, 163, 'local:warsh-text.json'),
  ('warsh-7-97', 'warsh', 7, 97, 'أَوَࡰمِنَ أَهْلُ ࡲ۬لْقُرٜىٰٓ أَنْ يَّاتِيَهُم بَأْسُنَا ضُحىࣰ وَهُمْ يَلْعَبُونَ࣌', 'أوࡰمن أهل ࡲلقرى أن ياتيهم بأسنا ضحى وهم يلعبون࣌', NULL, 163, 'local:warsh-text.json'),
  ('warsh-7-98', 'warsh', 7, 98, 'أَفَأَمِنُواْ مَكْرَ ࡰ۬للَّهِ࣌ فَلَا يَامَنُ مَكْرَ ࡰ۬للَّهِ إِلَّا ࡰ۬لْقَوْمُ ࡲ۬لْخَٰسِرُونَ࣌', 'أفأمنوا مكر ࡰلله࣌ فلا يامن مكر ࡰلله إلا ࡰلقوم ࡲلخسرون࣌', NULL, 163, 'local:warsh-text.json'),
  ('warsh-7-99', 'warsh', 7, 99, '۞ أَوَلَمْ يَهْدِ لِلذِينَ يَرِثُونَ ࡰ۬لَارْضَ مِنۢ بَعْدِ أَهْلِهَآ أَن لَّوْ نَشَآءُ ࡶَصَبْنَٰهُم بِذُنُوبِهِمْ࣌ وَنَطْبَعُ عَلَىٰ قُلُوبِهِمْ فَهُمْ لَا يَسْمَعُونَ࣌', 'أولم يهد للذين يرثون ࡰلارض من بعد أهلها أن لو نشاء ࡶصبنهم بذنوبهم࣌ ونطبع على قلوبهم فهم لا يسمعون࣌', NULL, 163, 'local:warsh-text.json'),
  ('warsh-7-100', 'warsh', 7, 100, 'تِلْكَ ࡰ۬لْقُرٜىٰ نَقُصُّ عَلَيْكَ مِنَ ࡰنۢبَآئِهَا࣌ وَلَقَدْ جَآءَتْهُمْ رُسُلُهُم بِالْبَيِّنَٰتِ فَمَا كَانُواْ لِيُومِنُواْ بِمَا كَذَّبُواْ مِن قَبْلُ࣌ كَذَٰلِكَ يَطْبَعُ ࡲ۬للَّهُ عَلَىٰ قُلُوبِ ࡴ۬لْكٜـٰفِرِينَ࣌', 'تلك ࡰلقرى نقص عليك من ࡰنبائها࣌ ولقد جاءتهم رسلهم بالبينت فما كانوا ليومنوا بما كذبوا من قبل࣌ كذلك يطبع ࡲلله على قلوب ࡴلكفرين࣌', NULL, 163, 'local:warsh-text.json'),
  ('warsh-7-101', 'warsh', 7, 101, 'وَمَا وَجَدْنَا لِأَكْثَرِهِم مِّنْ عَهْدࣲ࣌ وَإِنْ وَّجَدْنَآ أَكْثَرَهُمْ لَفَٰسِقِينَ࣌', 'وما وجدنا لأكثرهم من عهد࣌ وإن وجدنا أكثرهم لفسقين࣌', NULL, 163, 'local:warsh-text.json'),
  ('warsh-7-102', 'warsh', 7, 102, 'ثُمَّ بَعَثْنَا مِنۢ بَعْدِهِم مُّوسٜىٰ بِـَٔايَٰتِنَآ إِلَىٰ فِرْعَوْنَ وَمَلَإِيْهِۦ فَظَلَمُواْ بِهَا࣌ فَانظُرْ كَيْفَ كَانَ عَٰقِبَةُ ࡲ۬لْمُفْسِدِينَ࣌', 'ثم بعثنا من بعدهم موسى بايتنا إلى فرعون وملإيه فظلموا بها࣌ فانظر كيف كان عقبة ࡲلمفسدين࣌', NULL, 163, 'local:warsh-text.json'),
  ('warsh-7-103', 'warsh', 7, 103, 'وَقَالَ مُوسٜىٰ يَٰفِرْعَوْنُ إِنِّے رَسُولࣱ مِّن رَّبِّ ࡴ۬لْعَٰلَمِينَ', 'وقال موسى يفرعون إنے رسول من رب ࡴلعلمين', NULL, 163, 'local:warsh-text.json'),
  ('warsh-7-104', 'warsh', 7, 104, 'حَقِيقٌ࣌ عَلَيَّ أَن لَّآ أَقُولَ عَلَى ࡰ۬للَّهِ إِلَّا ࡰ۬لْحَقَّ࣌ قَدْ جِئْتُكُم بِبَيِّنَةࣲ مِّن رَّبِّكُمْ࣌ فَأَرْسِلْ مَعِے بَنِےٓ إِسْرَآءِيلَ࣌', 'حقيق࣌ علي أن لا أقول على ࡰلله إلا ࡰلحق࣌ قد جئتكم ببينة من ربكم࣌ فأرسل معے بنے إسراءيل࣌', NULL, 164, 'local:warsh-text.json'),
  ('warsh-7-105', 'warsh', 7, 105, 'قَالَ إِن كُنتَ جِئْتَ بِـَٔايَةࣲ فَاتِ بِهَآ إِن كُنتَ مِنَ ࡰ۬لصَّٰدِقِينَ࣌', 'قال إن كنت جئت باية فات بها إن كنت من ࡰلصدقين࣌', NULL, 164, 'local:warsh-text.json'),
  ('warsh-7-106', 'warsh', 7, 106, 'فَأَلْقٜىٰ عَصَاهُ فَإِذَا هِيَ ثُعْبَانࣱ مُّبِينࣱ', 'فألقى عصاه فإذا هي ثعبان مبين', NULL, 164, 'local:warsh-text.json'),
  ('warsh-7-107', 'warsh', 7, 107, 'وَنَزَعَ يَدَهُۥ فَإِذَا هِيَ بَيْضَآءُ لِلنَّٰظِرِينَ࣌', 'ونزع يده فإذا هي بيضاء للنظرين࣌', NULL, 164, 'local:warsh-text.json'),
  ('warsh-7-108', 'warsh', 7, 108, 'قَالَ ࡰ۬لْمَلَأُ مِن قَوْمِ فِرْعَوْنَ إِنَّ هَٰذَا لَسَٰحِرٌ عَلِيمࣱ', 'قال ࡰلملأ من قوم فرعون إن هذا لسحر عليم', NULL, 164, 'local:warsh-text.json'),
  ('warsh-7-109', 'warsh', 7, 109, 'يُرِيدُ أَنْ يُّخْرِجَكُم مِّنَ ࡰرْضِكُمْ࣌ فَمَاذَا تَامُرُونَ࣌', 'يريد أن يخرجكم من ࡰرضكم࣌ فماذا تامرون࣌', NULL, 164, 'local:warsh-text.json'),
  ('warsh-7-110', 'warsh', 7, 110, 'قَالُوٓاْ أَرْجِهِۦ وَأَخَاهُ وَأَرْسِلْ فِے ࡴ۬لْمَدَآئِنِ حَٰشِرِينَ', 'قالوا أرجه وأخاه وأرسل فے ࡴلمدائن حشرين', NULL, 164, 'local:warsh-text.json'),
  ('warsh-7-111', 'warsh', 7, 111, 'يَاتُوكَ بِكُلِّ سَٰحِرٍ عَلِيمࣲ࣌', 'ياتوك بكل سحر عليم࣌', NULL, 164, 'local:warsh-text.json'),
  ('warsh-7-112', 'warsh', 7, 112, 'وَجَآءَ ࡰ۬لسَّحَرَةُ فِرْعَوْنَ قَالُوٓاْ إِنَّ لَنَا لَأَجْراً ࡴن كُنَّا نَحْنُ ࡲ۬لْغَٰلِبِينَ࣌', 'وجاء ࡰلسحرة فرعون قالوا إن لنا لأجرا ࡴن كنا نحن ࡲلغلبين࣌', NULL, 164, 'local:warsh-text.json'),
  ('warsh-7-113', 'warsh', 7, 113, 'قَالَ نَعَمْ وَإِنَّكُمْ لَمِنَ ࡰ۬لْمُقَرَّبِينَ࣌', 'قال نعم وإنكم لمن ࡰلمقربين࣌', NULL, 164, 'local:warsh-text.json'),
  ('warsh-7-114', 'warsh', 7, 114, 'قَالُواْ يَٰمُوسٜىٰٓ إِمَّآ أَن تُلْقِيَ وَإِمَّآ أَن نَّكُونَ نَحْنُ ࡲ۬لْمُلْقِينَ࣌', 'قالوا يموسى إما أن تلقي وإما أن نكون نحن ࡲلملقين࣌', NULL, 164, 'local:warsh-text.json'),
  ('warsh-7-115', 'warsh', 7, 115, 'قَالَ أَلْقُواْ࣌ فَلَمَّآ أَلْقَوْاْ سَحَرُوٓاْ أَعْيُنَ ࡰ۬لنَّاسِ وَاسْتَرْهَبُوهُمْ࣌ وَجَآءُو بِسِحْرٍ عَظِيمࣲ࣌', 'قال ألقوا࣌ فلما ألقوا سحروا أعين ࡰلناس واسترهبوهم࣌ وجاءو بسحر عظيم࣌', NULL, 164, 'local:warsh-text.json'),
  ('warsh-7-116', 'warsh', 7, 116, '۞ وَأَوْحَيْنَآ إِلَىٰ مُوسٜىٰٓ أَنَ ࡰلْقِ عَصَاكَ࣌ فَإِذَا هِيَ تَلَقَّفُ مَا يَافِكُونَ࣌', 'وأوحينا إلى موسى أن ࡰلق عصاك࣌ فإذا هي تلقف ما يافكون࣌', NULL, 164, 'local:warsh-text.json'),
  ('warsh-7-117', 'warsh', 7, 117, 'فَوَقَعَ ࡰ۬لْحَقُّ وَبَطَلَ مَا كَانُواْ يَعْمَلُونَ࣌', 'فوقع ࡰلحق وبطل ما كانوا يعملون࣌', NULL, 164, 'local:warsh-text.json'),
  ('warsh-7-118', 'warsh', 7, 118, 'فَغُلِبُواْ هُنَالِكَ وَانقَلَبُواْ صَٰغِرِينَ࣌', 'فغلبوا هنالك وانقلبوا صغرين࣌', NULL, 164, 'local:warsh-text.json'),
  ('warsh-7-119', 'warsh', 7, 119, 'وَأُلْقِيَ ࡰ۬لسَّحَرَةُ سَٰجِدِينَ࣌', 'وألقي ࡰلسحرة سجدين࣌', NULL, 164, 'local:warsh-text.json'),
  ('warsh-7-120', 'warsh', 7, 120, 'قَالُوٓاْ ءَامَنَّا بِرَبِّ ࡴ۬لْعَٰلَمِينَ', 'قالوا ءامنا برب ࡴلعلمين', NULL, 165, 'local:warsh-text.json'),
  ('warsh-7-121', 'warsh', 7, 121, 'رَبِّ مُوسٜىٰ وَهَٰرُونَ࣌', 'رب موسى وهرون࣌', NULL, 165, 'local:warsh-text.json'),
  ('warsh-7-122', 'warsh', 7, 122, 'قَالَ فِرْعَوْنُ ءَࡶٰمَنتُم بِهِۦ قَبْلَ أَنَ اٰذَنَ لَكُمُۥٓ إِنَّ هَٰذَا لَمَكْرࣱ مَّكَرْتُمُوهُ فِے ࡴ۬لْمَدِينَةِ لِتُخْرِجُواْ مِنْهَآ أَهْلَهَا࣌ فَسَوْفَ تَعْلَمُونَ࣌', 'قال فرعون ءࡶمنتم به قبل أن اذن لكم إن هذا لمكر مكرتموه فے ࡴلمدينة لتخرجوا منها أهلها࣌ فسوف تعلمون࣌', NULL, 165, 'local:warsh-text.json'),
  ('warsh-7-123', 'warsh', 7, 123, 'لَأُقَطِّعَنَّ أَيْدِيَكُمْ وَأَرْجُلَكُم مِّنْ خِلَٰفࣲ ثُمَّ لَأُصَلِّبَنَّكُمُۥٓ أَجْمَعِينَ࣌', 'لأقطعن أيديكم وأرجلكم من خلف ثم لأصلبنكم أجمعين࣌', NULL, 165, 'local:warsh-text.json'),
  ('warsh-7-124', 'warsh', 7, 124, 'قَالُوٓاْ إِنَّآ إِلَىٰ رَبِّنَا مُنقَلِبُونَ࣌', 'قالوا إنا إلى ربنا منقلبون࣌', NULL, 165, 'local:warsh-text.json'),
  ('warsh-7-125', 'warsh', 7, 125, 'وَمَا تَنقِمُ مِنَّآ إِلَّآ أَنَ اٰمَنَّا بِـَٔايَٰتِ رَبِّنَا لَمَّا جَآءَتْنَا࣌ رَبَّنَآ أَفْرِغْ عَلَيْنَا صَبْراࣰ وَتَوَفَّنَا مُسْلِمِينَ࣌', 'وما تنقم منا إلا أن امنا بايت ربنا لما جاءتنا࣌ ربنا أفرغ علينا صبرا وتوفنا مسلمين࣌', NULL, 165, 'local:warsh-text.json'),
  ('warsh-7-126', 'warsh', 7, 126, 'وَقَالَ ࡰ۬لْمَلَأُ مِن قَوْمِ فِرْعَوْنَ أَتَذَرُ مُوسٜىٰ وَقَوْمَهُۥ لِيُفْسِدُواْ فِے ࡴ۬لَارْضِ وَيَذَرَكَ وَءَالِهَتَكَ࣌ قَالَ سَنَقْتُلُ أَبْنَآءَهُمْ وَنَسْتَحْيِۦ نِسَآءَهُمْ وَإِنَّا فَوْقَهُمْ قَٰهِرُونَ࣌', 'وقال ࡰلملأ من قوم فرعون أتذر موسى وقومه ليفسدوا فے ࡴلارض ويذرك وءالهتك࣌ قال سنقتل أبناءهم ونستحي نساءهم وإنا فوقهم قهرون࣌', NULL, 165, 'local:warsh-text.json'),
  ('warsh-7-127', 'warsh', 7, 127, 'قَالَ مُوسٜىٰ لِقَوْمِهِ ࡴٜسْتَعِينُواْ بِاللَّهِ وَاصْبِرُوٓاْ࣌ إِنَّ ࡰ۬لَارْضَ لِلهِ يُورِثُهَا مَنْ يَّشَآءُ مِنْ عِبَادِهِۦ࣌ وَالْعَٰقِبَةُ لِلْمُتَّقِينَ࣌', 'قال موسى لقومه ࡴستعينوا بالله واصبروا࣌ إن ࡰلارض لله يورثها من يشاء من عباده࣌ والعقبة للمتقين࣌', NULL, 165, 'local:warsh-text.json'),
  ('warsh-7-128', 'warsh', 7, 128, 'قَالُوٓاْ أُوذِينَا مِن قَبْلِ أَن تَاتِيَنَا وَمِنۢ بَعْدِ مَا جِئْتَنَا࣌ قَالَ عَسٜىٰ رَبُّكُمُۥٓ أَنْ يُّهْلِكَ عَدُوَّكُمْ وَيَسْتَخْلِفَكُمْ فِے ࡴ۬لَارْضِ فَيَنظُرَ كَيْفَ تَعْمَلُونَ࣌', 'قالوا أوذينا من قبل أن تاتينا ومن بعد ما جئتنا࣌ قال عسى ربكم أن يهلك عدوكم ويستخلفكم فے ࡴلارض فينظر كيف تعملون࣌', NULL, 165, 'local:warsh-text.json'),
  ('warsh-7-129', 'warsh', 7, 129, 'وَلَقَدَ ࡰخَذْنَآ ءَالَ فِرْعَوْنَ بِالسِّنِينَ وَنَقْصࣲ مِّنَ ࡰ۬لثَّمَرَٰتِ لَعَلَّهُمْ يَذَّكَّرُونَ࣌', 'ولقد ࡰخذنا ءال فرعون بالسنين ونقص من ࡰلثمرت لعلهم يذكرون࣌', NULL, 165, 'local:warsh-text.json'),
  ('warsh-7-130', 'warsh', 7, 130, 'فَإِذَا جَآءَتْهُمُ ࡲ۬لْحَسَنَةُ قَالُواْ لَنَا هَٰذِهِۦ࣌ وَإِن تُصِبْهُمْ سَيِّئَةࣱ يَطَّيَّرُواْ بِمُوسٜىٰ وَمَن مَّعَهُۥٓ࣌ أَلَآ إِنَّمَا طَٰٓئِرُهُمْ عِندَ ࡰ۬للَّهِ࣌ وَلَٰكِنَّ أَكْثَرَهُمْ لَا يَعْلَمُونَ࣌', 'فإذا جاءتهم ࡲلحسنة قالوا لنا هذه࣌ وإن تصبهم سيئة يطيروا بموسى ومن معه࣌ ألا إنما طئرهم عند ࡰلله࣌ ولكن أكثرهم لا يعلمون࣌', NULL, 166, 'local:warsh-text.json'),
  ('warsh-7-131', 'warsh', 7, 131, '۞ وَقَالُواْ مَهْمَا تَاتِنَا بِهِۦ مِنَ اٰيَةࣲ لِّتَسْحَرَنَا بِهَا فَمَا نَحْنُ لَكَ بِمُومِنِينَ࣌', 'وقالوا مهما تاتنا به من اية لتسحرنا بها فما نحن لك بمومنين࣌', NULL, 166, 'local:warsh-text.json'),
  ('warsh-7-132', 'warsh', 7, 132, 'فَأَرْسَلْنَا عَلَيْهِمُ ࡲ۬لطُّوفَانَ وَالْجَرَادَ وَالْقُمَّلَ وَالضَّفَادِعَ وَالدَّمَ ءَايَٰتࣲ مُّفَصَّلَٰتࣲ فَاسْتَكْبَرُواْ وَكَانُواْ قَوْماࣰ مُّجْرِمِينَ࣌', 'فأرسلنا عليهم ࡲلطوفان والجراد والقمل والضفادع والدم ءايت مفصلت فاستكبروا وكانوا قوما مجرمين࣌', NULL, 166, 'local:warsh-text.json'),
  ('warsh-7-133', 'warsh', 7, 133, 'وَلَمَّا وَقَعَ عَلَيْهِمُ ࡲ۬لرِّجْزُ قَالُواْ يَٰمُوسَى ࡸَدْعُ لَنَا رَبَّكَ بِمَا عَهِدَ عِندَكَ لَئِن كَشَفْتَ عَنَّا ࡰ۬لرِّجْزَ لَنُومِنَنَّ لَكَ وَلَنُرْسِلَنَّ مَعَكَ بَنِےٓ إِسْرَآءِيلَ࣌', 'ولما وقع عليهم ࡲلرجز قالوا يموسى ࡸدع لنا ربك بما عهد عندك لئن كشفت عنا ࡰلرجز لنومنن لك ولنرسلن معك بنے إسراءيل࣌', NULL, 166, 'local:warsh-text.json'),
  ('warsh-7-134', 'warsh', 7, 134, 'فَلَمَّا كَشَفْنَا عَنْهُمُ ࡲ۬لرِّجْزَ إِلَىٰٓ أَجَلٍ هُم بَٰلِغُوهُ إِذَا هُمْ يَنكُثُونَ࣌', 'فلما كشفنا عنهم ࡲلرجز إلى أجل هم بلغوه إذا هم ينكثون࣌', NULL, 166, 'local:warsh-text.json'),
  ('warsh-7-135', 'warsh', 7, 135, 'فَانتَقَمْنَا مِنْهُمْ فَأَغْرَقْنَٰهُمْ فِے ࡴ۬لْيَمِّ بِأَنَّهُمْ كَذَّبُواْ بِـَٔايَٰتِنَا وَكَانُواْ عَنْهَا غَٰفِلِينَ࣌', 'فانتقمنا منهم فأغرقنهم فے ࡴليم بأنهم كذبوا بايتنا وكانوا عنها غفلين࣌', NULL, 166, 'local:warsh-text.json'),
  ('warsh-7-136', 'warsh', 7, 136, 'وَأَوْرَثْنَا ࡰ۬لْقَوْمَ ࡰ۬لذِينَ كَانُواْ يُسْتَضْعَفُونَ مَشَٰرِقَ ࡰ۬لَارْضِ وَمَغَٰرِبَهَا ࡰ۬لتِے بَٰرَكْنَا فِيهَا࣌ وَتَمَّتْ كَلِمَةُ رَبِّكَ ࡰ۬لْحُسْنٜىٰ عَلَىٰ بَنِےٓ إِسْرَآءِيلَ', 'وأورثنا ࡰلقوم ࡰلذين كانوا يستضعفون مشرق ࡰلارض ومغربها ࡰلتے بركنا فيها࣌ وتمت كلمة ربك ࡰلحسنى على بنے إسراءيل', NULL, 166, 'local:warsh-text.json'),
  ('warsh-7-137', 'warsh', 7, 137, 'بِمَا صَبَرُواْ࣌ وَدَمَّرْنَا مَا كَانَ يَصْنَعُ فِرْعَوْنُ وَقَوْمُهُۥ وَمَا كَانُواْ يَعْرِشُونَ࣌', 'بما صبروا࣌ ودمرنا ما كان يصنع فرعون وقومه وما كانوا يعرشون࣌', NULL, 166, 'local:warsh-text.json'),
  ('warsh-7-138', 'warsh', 7, 138, 'وَجَٰوَزْنَا بِبَنِےٓ إِسْرَآءِيلَ ࡰ۬لْبَحْرَ فَأَتَوْاْ عَلَىٰ قَوْمࣲ يَعْكُفُونَ عَلَىٰٓ أَصْنَامࣲ لَّهُمْ࣌ قَالُواْ يَٰمُوسَى ࡰٜجْعَل لَّنَآ إِلَٰهاࣰ كَمَا لَهُمُۥٓ ءَالِهَةࣱ࣌ قَالَ إِنَّكُمْ قَوْمࣱ تَجْهَلُونَ࣌', 'وجوزنا ببنے إسراءيل ࡰلبحر فأتوا على قوم يعكفون على أصنام لهم࣌ قالوا يموسى ࡰجعل لنا إلها كما لهم ءالهة࣌ قال إنكم قوم تجهلون࣌', NULL, 167, 'local:warsh-text.json'),
  ('warsh-7-139', 'warsh', 7, 139, 'إِنَّ هَٰٓؤُلَآءِ مُتَبَّرࣱ مَّا هُمْ فِيهِ࣌ وَبَٰطِلࣱ مَّا كَانُواْ يَعْمَلُونَ࣌', 'إن هؤلاء متبر ما هم فيه࣌ وبطل ما كانوا يعملون࣌', NULL, 167, 'local:warsh-text.json'),
  ('warsh-7-140', 'warsh', 7, 140, 'قَالَ أَغَيْرَ ࡰ۬للَّهِ أَبْغِيكُمُۥٓ إِلَٰهاࣰ وَهُوَ فَضَّلَكُمْ عَلَى ࡰ۬لْعَٰلَمِينَ࣌', 'قال أغير ࡰلله أبغيكم إلها وهو فضلكم على ࡰلعلمين࣌', NULL, 167, 'local:warsh-text.json'),
  ('warsh-7-141', 'warsh', 7, 141, 'وَإِذَ ࡰنجَيْنَٰكُم مِّنَ اٰلِ فِرْعَوْنَ يَسُومُونَكُمْ سُوٓءَ ࡰ۬لْعَذَابِ يَقْتُلُونَ أَبْنَآءَكُمْ وَيَسْتَحْيُونَ نِسَآءَكُمْ࣌ وَفِے ذَٰلِكُم بَلَآءࣱ مِّن رَّبِّكُمْ عَظِيمࣱ࣌', 'وإذ ࡰنجينكم من ال فرعون يسومونكم سوء ࡰلعذاب يقتلون أبناءكم ويستحيون نساءكم࣌ وفے ذلكم بلاء من ربكم عظيم࣌', NULL, 167, 'local:warsh-text.json'),
  ('warsh-7-142', 'warsh', 7, 142, '۞ وَوَٰعَدْنَا مُوسٜىٰ ثَلَٰثِينَ لَيْلَةࣰ وَأَتْمَمْنَٰهَا بِعَشْرࣲ فَتَمَّ مِيقَٰتُ رَبِّهِۦٓ أَرْبَعِينَ لَيْلَةࣰ࣌ وَقَالَ مُوسٜىٰ لِأَخِيهِ هَٰرُونَ ࡸَخْلُفْنِے فِے قَوْمِے وَأَصْلِحْ وَلَا تَتَّبِعْ سَبِيلَ ࡰ۬لْمُفْسِدِينَ࣌', 'ووعدنا موسى ثلثين ليلة وأتممنها بعشر فتم ميقت ربه أربعين ليلة࣌ وقال موسى لأخيه هرون ࡸخلفنے فے قومے وأصلح ولا تتبع سبيل ࡰلمفسدين࣌', NULL, 167, 'local:warsh-text.json'),
  ('warsh-7-143', 'warsh', 7, 143, 'وَلَمَّا جَآءَ مُوسٜىٰ لِمِيقَٰتِنَا وَكَلَّمَهُۥ رَبُّهُۥ قَالَ رَبِّ أَرِنِےٓ أَنظُرِ ࡴلَيْكَ࣌ قَالَ لَن تَرٜيٰنِے وَلَٰكِنُ ࡲ࢈نظُرِ ࡴلَى ࡰ۬لْجَبَلِ فَإِنِ ࡴٜسْتَقَرَّ مَكَانَهُۥ فَسَوْفَ تَرٜيٰنِے࣌ فَلَمَّا تَجَلّٜىٰ رَبُّهُۥ لِلْجَبَلِ جَعَلَهُۥ دَكّاࣰ وَخَرَّ مُوسٜىٰ صَعِقاࣰ࣌ فَلَمَّآ أَفَاقَ قَالَ سُبْحَٰنَكَ تُبْتُ إِلَيْكَ وَأَنَآ أَوَّلُ ࡲ۬لْمُومِنِينَ࣌', 'ولما جاء موسى لميقتنا وكلمه ربه قال رب أرنے أنظر ࡴليك࣌ قال لن ترينے ولكن ࡲ࢈نظر ࡴلى ࡰلجبل فإن ࡴستقر مكانه فسوف ترينے࣌ فلما تجلى ربه للجبل جعله دكا وخر موسى صعقا࣌ فلما أفاق قال سبحنك تبت إليك وأنا أول ࡲلمومنين࣌', NULL, 167, 'local:warsh-text.json'),
  ('warsh-7-144', 'warsh', 7, 144, 'قَالَ يَٰمُوسٜىٰٓ إِنِّے ࡴٜصْطَفَيْتُكَ عَلَى ࡰ۬لنَّاسِ بِرِسَالَتِے وَبِكَلَٰمِے فَخُذْ مَآ ءَاتَيْتُكَ وَكُن مِّنَ ࡰ۬لشَّٰكِرِينَ࣌', 'قال يموسى إنے ࡴصطفيتك على ࡰلناس برسالتے وبكلمے فخذ ما ءاتيتك وكن من ࡰلشكرين࣌', NULL, 168, 'local:warsh-text.json'),
  ('warsh-7-145', 'warsh', 7, 145, 'وَكَتَبْنَا لَهُۥ فِے ࡴ۬لَالْوَاحِ مِن كُلِّ شَےْءࣲ مَّوْعِظَةࣰ وَتَفْصِيلاࣰ لِّكُلِّ شَےْءࣲ࣌ فَخُذْهَا بِقُوَّةࣲ وَامُرْ قَوْمَكَ يَاخُذُواْ بِأَحْسَنِهَا࣌ سَأُوْرِيكُمْ دَارَ ࡰ۬لْفَٰسِقِينَ࣌', 'وكتبنا له فے ࡴلالواح من كل شےء موعظة وتفصيلا لكل شےء࣌ فخذها بقوة وامر قومك ياخذوا بأحسنها࣌ سأوريكم دار ࡰلفسقين࣌', NULL, 168, 'local:warsh-text.json'),
  ('warsh-7-146', 'warsh', 7, 146, 'سَأَصْرِفُ عَنَ اٰيَٰتِيَ ࡰ۬لذِينَ يَتَكَبَّرُونَ فِے ࡴ۬لَارْضِ بِغَيْرِ ࡴ۬لْحَقِّ وَإِنْ يَّرَوْاْ كُلَّ ءَايَةࣲ لَّا يُومِنُواْ بِهَا وَإِنْ يَّرَوْاْ سَبِيلَ ࡰ۬لرُّشْدِ لَا يَتَّخِذُوهُ سَبِيلاࣰ وَإِنْ يَّرَوْاْ سَبِيلَ ࡰ۬لْغَيِّ يَتَّخِذُوهُ سَبِيلاࣰ࣌ ذَٰلِكَ بِأَنَّهُمْ كَذَّبُواْ بِـَٔايَٰتِنَا وَكَانُواْ عَنْهَا غَٰفِلِينَ࣌', 'سأصرف عن ايتي ࡰلذين يتكبرون فے ࡴلارض بغير ࡴلحق وإن يروا كل ءاية لا يومنوا بها وإن يروا سبيل ࡰلرشد لا يتخذوه سبيلا وإن يروا سبيل ࡰلغي يتخذوه سبيلا࣌ ذلك بأنهم كذبوا بايتنا وكانوا عنها غفلين࣌', NULL, 168, 'local:warsh-text.json'),
  ('warsh-7-147', 'warsh', 7, 147, 'وَالذِينَ كَذَّبُواْ بِـَٔايَٰتِنَا وَلِقَآءِ ࡴ۬لَاخِرَةِ حَبِطَتَ ࡰعْمَٰلُهُمْ هَلْ يُجْزَوْنَ إِلَّا مَا كَانُواْ يَعْمَلُونَ࣌', 'والذين كذبوا بايتنا ولقاء ࡴلاخرة حبطت ࡰعملهم هل يجزون إلا ما كانوا يعملون࣌', NULL, 168, 'local:warsh-text.json'),
  ('warsh-7-148', 'warsh', 7, 148, 'وَاتَّخَذَ قَوْمُ مُوسٜىٰ مِنۢ بَعْدِهِۦ مِنْ حُلِيِّهِمْ عِجْلاࣰ جَسَداࣰ لَّهُۥ خُوَارٌ࣌ ࡰلَمْ يَرَوَاْ ࡰنَّهُۥ لَا يُكَلِّمُهُمْ وَلَا يَهْدِيهِمْ سَبِيلاً࣌ ࡴٜتَّخَذُوهُ وَكَانُواْ ظَٰلِمِينَ࣌', 'واتخذ قوم موسى من بعده من حليهم عجلا جسدا له خوار࣌ ࡰلم يروا ࡰنه لا يكلمهم ولا يهديهم سبيلا࣌ ࡴتخذوه وكانوا ظلمين࣌', NULL, 168, 'local:warsh-text.json'),
  ('warsh-7-149', 'warsh', 7, 149, '۞ وَلَمَّا سُقِطَ فِےٓ أَيْدِيهِمْ وَرَأَوَاْ ࡰنَّهُمْ قَد ضَّلُّواْ قَالُواْ لَئِن لَّمْ يَرْحَمْنَا رَبُّنَا وَيَغْفِرْ لَنَا لَنَكُونَنَّ مِنَ ࡰ۬لْخَٰسِرِينَ࣌', 'ولما سقط فے أيديهم ورأوا ࡰنهم قد ضلوا قالوا لئن لم يرحمنا ربنا ويغفر لنا لنكونن من ࡰلخسرين࣌', NULL, 168, 'local:warsh-text.json'),
  ('warsh-7-150', 'warsh', 7, 150, 'وَلَمَّا رَجَعَ مُوسٜىٰٓ إِلَىٰ قَوْمِهِۦ غَضْبَٰنَ أَسِفاࣰ قَالَ بِيسَمَا خَلَفْتُمُونِے مِنۢ بَعْدِيَ࣌ أَعَجِلْتُمُۥٓ أَمْرَ رَبِّكُمْ࣌ وَأَلْقَى ࡰ۬لَالْوَاحَ وَأَخَذَ بِرَأْسِ أَخِيهِ يَجُرُّهُۥٓ إِلَيْهِ࣌ قَالَ ࡰٜبْنَ أُمَّ إِنَّ ࡰ۬لْقَوْمَ ࡰٜسْتَضْعَفُونِے وَكَادُواْ يَقْتُلُونَنِے فَلَا تُشْمِتْ بِيَ ࡰ۬لَاعْدَآءَ وَلَا تَجْعَلْنِے مَعَ ࡰ۬لْقَوْمِ ࡴ۬لظَّٰلِمِينَ࣌', 'ولما رجع موسى إلى قومه غضبن أسفا قال بيسما خلفتمونے من بعدي࣌ أعجلتم أمر ربكم࣌ وألقى ࡰلالواح وأخذ برأس أخيه يجره إليه࣌ قال ࡰبن أم إن ࡰلقوم ࡰستضعفونے وكادوا يقتلوننے فلا تشمت بي ࡰلاعداء ولا تجعلنے مع ࡰلقوم ࡴلظلمين࣌', NULL, 169, 'local:warsh-text.json'),
  ('warsh-7-151', 'warsh', 7, 151, 'قَالَ رَبِّ ࡴٜغْفِرْ لِے وَلِأَخِے وَأَدْخِلْنَا فِے رَحْمَتِكَ࣌ وَأَنتَ أَرْحَمُ ࡲ۬لرَّٰحِمِينَ࣌', 'قال رب ࡴغفر لے ولأخے وأدخلنا فے رحمتك࣌ وأنت أرحم ࡲلرحمين࣌', NULL, 169, 'local:warsh-text.json'),
  ('warsh-7-152', 'warsh', 7, 152, 'إِنَّ ࡰ۬لذِينَ ࡰٜتَّخَذُواْ ࡲ۬لْعِجْلَ سَيَنَالُهُمْ غَضَبࣱ مِّن رَّبِّهِمْ وَذِلَّةࣱ فِے ࡴ۬لْحَيَوٰةِ ࡴ۬لدُّنْيٜا࣌ وَكَذَٰلِكَ نَجْزِے ࡴ۬لْمُفْتَرِينَ࣌', 'إن ࡰلذين ࡰتخذوا ࡲلعجل سينالهم غضب من ربهم وذلة فے ࡴلحيوة ࡴلدنيا࣌ وكذلك نجزے ࡴلمفترين࣌', NULL, 169, 'local:warsh-text.json'),
  ('warsh-7-153', 'warsh', 7, 153, 'وَالذِينَ عَمِلُواْ ࡲ۬لسَّيِّـَٔاتِ ثُمَّ تَابُواْ مِنۢ بَعْدِهَا وَءَامَنُوٓاْ إِنَّ رَبَّكَ مِنۢ بَعْدِهَا لَغَفُورࣱ رَّحِيمࣱ࣌', 'والذين عملوا ࡲلسيات ثم تابوا من بعدها وءامنوا إن ربك من بعدها لغفور رحيم࣌', NULL, 169, 'local:warsh-text.json'),
  ('warsh-7-154', 'warsh', 7, 154, 'وَلَمَّا سَكَتَ عَن مُّوسَى ࡰ۬لْغَضَبُ أَخَذَ ࡰ۬لَالْوَاحَ وَفِے نُسْخَتِهَا هُدىࣰ وَرَحْمَةࣱ لِّلذِينَ هُمْ لِرَبِّهِمْ يَرْهَبُونَ࣌', 'ولما سكت عن موسى ࡰلغضب أخذ ࡰلالواح وفے نسختها هدى ورحمة للذين هم لربهم يرهبون࣌', NULL, 169, 'local:warsh-text.json'),
  ('warsh-7-155', 'warsh', 7, 155, 'وَاخْتَارَ مُوسٜىٰ قَوْمَهُۥ سَبْعِينَ رَجُلاࣰ لِّمِيقَٰتِنَا࣌ فَلَمَّآ أَخَذَتْهُمُ ࡲ۬لرَّجْفَةُ قَالَ رَبِّ لَوْ شِئْتَ أَهْلَكْتَهُم مِّن قَبْلُ وَإِيَّٰيَ࣌ أَتُهْلِكُنَا بِمَا فَعَلَ ࡰ۬لسُّفَهَآءُ مِنَّآ࣌ إِنْ هِيَ إِلَّا فِتْنَتُكَ تُضِلُّ بِهَا مَن تَشَآءُ وَتَهْدِے مَن تَشَآءُ࣌ ࡶَنتَ وَلِيُّنَا فَاغْفِرْ لَنَا وَارْحَمْنَا وَأَنتَ خَيْرُ ࡲ۬لْغَٰفِرِينَ࣌', 'واختار موسى قومه سبعين رجلا لميقتنا࣌ فلما أخذتهم ࡲلرجفة قال رب لو شئت أهلكتهم من قبل وإيي࣌ أتهلكنا بما فعل ࡰلسفهاء منا࣌ إن هي إلا فتنتك تضل بها من تشاء وتهدے من تشاء࣌ ࡶنت ولينا فاغفر لنا وارحمنا وأنت خير ࡲلغفرين࣌', NULL, 169, 'local:warsh-text.json'),
  ('warsh-7-156', 'warsh', 7, 156, '۞ وَاكْتُبْ لَنَا فِے هَٰذِهِ ࡴ۬لدُّنْيٜا حَسَنَةࣰ وَفِے ࡴ۬لَاخِرَةِ࣌ إِنَّا هُدْنَآ إِلَيْكَ࣌ قَالَ عَذَابِيَ أُصِيبُ بِهِۦ مَنَ ࡰشَآءُ࣌ وَرَحْمَتِے وَسِعَتْ كُلَّ شَےْءࣲ࣌ فَسَأَكْتُبُهَا لِلذِينَ يَتَّقُونَ وَيُوتُونَ ࡰ۬لزَّكَوٰةَ وَالذِينَ هُم بِـَٔايَٰتِنَا يُومِنُونَ', 'واكتب لنا فے هذه ࡴلدنيا حسنة وفے ࡴلاخرة࣌ إنا هدنا إليك࣌ قال عذابي أصيب به من ࡰشاء࣌ ورحمتے وسعت كل شےء࣌ فسأكتبها للذين يتقون ويوتون ࡰلزكوة والذين هم بايتنا يومنون', NULL, 170, 'local:warsh-text.json'),
  ('warsh-7-157', 'warsh', 7, 157, 'ࡰ۬لذِينَ يَتَّبِعُونَ ࡰ۬لرَّسُولَ ࡰ۬لنَّبِےٓءَ ࡰ۬لُامِّيَّ ࡰ۬لذِے يَجِدُونَهُۥ مَكْتُوباً عِندَهُمْ فِے ࡴ۬لتَّوْرٜيٰةِ وَالِانجِيلِ يَامُرُهُم بِالْمَعْرُوفِ وَيَنْهٜيٰهُمْ عَنِ ࡴ۬لْمُنكَرِ وَيُحِلُّ لَهُمُ ࡲ۬لطَّيِّبَٰتِ وَيُحَرِّمُ عَلَيْهِمُ ࡲ۬لْخَبَٰٓئِثَ وَيَضَعُ عَنْهُمُۥٓ إِصْرَهُمْ وَالَاغْلَٰلَ ࡰ۬لتِے كَانَتْ عَلَيْهِمْ࣌ فَالذِينَ ءَامَنُواْ بِهِۦ وَعَزَّرُوهُ وَنَصَرُوهُ وَاتَّبَعُواْ ࡲ۬لنُّورَ ࡰ۬لذِےٓ أُنزِلَ مَعَهُۥٓ أُوْلَٰٓئِكَ هُمُ ࡲ۬لْمُفْلِحُونَ࣌', 'ࡰلذين يتبعون ࡰلرسول ࡰلنبےء ࡰلامي ࡰلذے يجدونه مكتوبا عندهم فے ࡴلتورية والانجيل يامرهم بالمعروف وينهيهم عن ࡴلمنكر ويحل لهم ࡲلطيبت ويحرم عليهم ࡲلخبئث ويضع عنهم إصرهم والاغلل ࡰلتے كانت عليهم࣌ فالذين ءامنوا به وعزروه ونصروه واتبعوا ࡲلنور ࡰلذے أنزل معه أولئك هم ࡲلمفلحون࣌', NULL, 170, 'local:warsh-text.json'),
  ('warsh-7-158', 'warsh', 7, 158, 'قُلْ يَٰٓأَيُّهَا ࡰ۬لنَّاسُ إِنِّے رَسُولُ ࡲ۬للَّهِ إِلَيْكُمْ جَمِيعاً ࡴ۬لذِے لَهُۥ مُلْكُ ࡲ۬لسَّمَٰوَٰتِ وَالَارْضِ࣌ لَآ إِلَٰهَ إِلَّا هُوَ࣌ يُحْيِۦ وَيُمِيتُ࣌ فَـَٔامِنُواْ بِاللَّهِ وَرَسُولِهِ ࡴ۬لنَّبِےٓءِ ࡴ۬لُامِّيِّ ࡴ۬لذِے يُومِنُ بِاللَّهِ وَكَلِمَٰتِهِۦ࣌ وَاتَّبِعُوهُ لَعَلَّكُمْ تَهْتَدُونَ࣌', 'قل يأيها ࡰلناس إنے رسول ࡲلله إليكم جميعا ࡴلذے له ملك ࡲلسموت والارض࣌ لا إله إلا هو࣌ يحي ويميت࣌ فامنوا بالله ورسوله ࡴلنبےء ࡴلامي ࡴلذے يومن بالله وكلمته࣌ واتبعوه لعلكم تهتدون࣌', NULL, 170, 'local:warsh-text.json'),
  ('warsh-7-159', 'warsh', 7, 159, 'وَمِن قَوْمِ مُوسٜىٰٓ أُمَّةࣱ يَهْدُونَ بِالْحَقِّ وَبِهِۦ يَعْدِلُونَ࣌', 'ومن قوم موسى أمة يهدون بالحق وبه يعدلون࣌', NULL, 170, 'local:warsh-text.json'),
  ('warsh-7-160', 'warsh', 7, 160, 'وَقَطَّعْنَٰهُمُ ࡲٜثْنَتَےْ عَشْرَةَ أَسْبَاطاً ࡳمَماࣰ࣌ وَأَوْحَيْنَآ إِلَىٰ مُوسٜىٰٓ إِذِ ࡴٜسْتَسْقٜيٰهُ قَوْمُهُۥٓ أَنِ ࡴٜضْرِب بِّعَصَاكَ ࡰ۬لْحَجَرَ࣌ فَانۢبَجَسَتْ مِنْهُ ࡲٜثْنَتَا عَشْرَةَ عَيْناࣰ࣌ قَدْ عَلِمَ كُلُّ أُنَاسࣲ مَّشْرَبَهُمْ࣌ وَظَلَّلْنَا عَلَيْهِمُ ࡲ۬لْغَمَٰمَ وَأَنزَلْنَا عَلَيْهِمُ ࡲ۬لْمَنَّ وَالسَّلْوٜىٰ࣌ كُلُواْ مِن طَيِّبَٰتِ مَا رَزَقْنَٰكُمْ࣌ وَمَا ظَلَمُونَا࣌ وَلَٰكِن كَانُوٓاْ أَنفُسَهُمْ يَظْلِمُونَ࣌', 'وقطعنهم ࡲثنتے عشرة أسباطا ࡳمما࣌ وأوحينا إلى موسى إذ ࡴستسقيه قومه أن ࡴضرب بعصاك ࡰلحجر࣌ فانبجست منه ࡲثنتا عشرة عينا࣌ قد علم كل أناس مشربهم࣌ وظللنا عليهم ࡲلغمم وأنزلنا عليهم ࡲلمن والسلوى࣌ كلوا من طيبت ما رزقنكم࣌ وما ظلمونا࣌ ولكن كانوا أنفسهم يظلمون࣌', NULL, 171, 'local:warsh-text.json'),
  ('warsh-7-161', 'warsh', 7, 161, 'وَإِذْ قِيلَ لَهُمُ ࡲ࢈سْكُنُواْ هَٰذِهِ ࡴ۬لْقَرْيَةَ وَكُلُواْ مِنْهَا حَيْثُ شِئْتُمْ وَقُولُواْ حِطَّةࣱ وَادْخُلُواْ ࡲ۬لْبَابَ سُجَّداࣰ تُغْفَرْ لَكُمْ خَطِيٓـَٰٔتُكُمْ࣌ سَنَزِيدُ ࡲ۬لْمُحْسِنِينَ࣌', 'وإذ قيل لهم ࡲ࢈سكنوا هذه ࡴلقرية وكلوا منها حيث شئتم وقولوا حطة وادخلوا ࡲلباب سجدا تغفر لكم خطيتكم࣌ سنزيد ࡲلمحسنين࣌', NULL, 171, 'local:warsh-text.json'),
  ('warsh-7-162', 'warsh', 7, 162, 'فَبَدَّلَ ࡰ۬لذِينَ ظَلَمُواْ مِنْهُمْ قَوْلاً غَيْرَ ࡰ۬لذِے قِيلَ لَهُمْ فَأَرْسَلْنَا عَلَيْهِمْ رِجْزاࣰ مِّنَ ࡰ۬لسَّمَآءِ بِمَا كَانُواْ يَظْلِمُونَ࣌', 'فبدل ࡰلذين ظلموا منهم قولا غير ࡰلذے قيل لهم فأرسلنا عليهم رجزا من ࡰلسماء بما كانوا يظلمون࣌', NULL, 171, 'local:warsh-text.json'),
  ('warsh-7-163', 'warsh', 7, 163, '۞ وَسْـَٔلْهُمْ عَنِ ࡴ۬لْقَرْيَةِ ࡴ۬لتِے كَانَتْ حَاضِرَةَ ࡰ۬لْبَحْرِ إِذْ يَعْدُونَ فِے ࡴ۬لسَّبْتِ إِذْ تَاتِيهِمْ حِيتَانُهُمْ يَوْمَ سَبْتِهِمْ شُرَّعاࣰ وَيَوْمَ لَا يَسْبِتُونَ لَا تَاتِيهِمْ࣌ كَذَٰلِكَ نَبْلُوهُم بِمَا كَانُواْ يَفْسُقُونَ࣌', 'وسلهم عن ࡴلقرية ࡴلتے كانت حاضرة ࡰلبحر إذ يعدون فے ࡴلسبت إذ تاتيهم حيتانهم يوم سبتهم شرعا ويوم لا يسبتون لا تاتيهم࣌ كذلك نبلوهم بما كانوا يفسقون࣌', NULL, 171, 'local:warsh-text.json'),
  ('warsh-7-164', 'warsh', 7, 164, 'وَإِذْ قَالَتُ ࡳمَّةࣱ مِّنْهُمْ لِمَ تَعِظُونَ قَوْماً ࡴ۬للَّهُ مُهْلِكُهُمُۥٓ أَوْ مُعَذِّبُهُمْ عَذَاباࣰ شَدِيداࣰ࣌ قَالُواْ مَعْذِرَةٌ ࡴلَىٰ رَبِّكُمْ وَلَعَلَّهُمْ يَتَّقُونَ࣌', 'وإذ قالت ࡳمة منهم لم تعظون قوما ࡴلله مهلكهم أو معذبهم عذابا شديدا࣌ قالوا معذرة ࡴلى ربكم ولعلهم يتقون࣌', NULL, 172, 'local:warsh-text.json'),
  ('warsh-7-165', 'warsh', 7, 165, 'فَلَمَّا نَسُواْ مَا ذُكِّرُواْ بِهِۦٓ أَنجَيْنَا ࡰ۬لذِينَ يَنْهَوْنَ عَنِ ࡴ۬لسُّوٓءِ وَأَخَذْنَا ࡰ۬لذِينَ ظَلَمُواْ بِعَذَابِۢ بِيسِۢ بِمَا كَانُواْ يَفْسُقُونَ࣌', 'فلما نسوا ما ذكروا به أنجينا ࡰلذين ينهون عن ࡴلسوء وأخذنا ࡰلذين ظلموا بعذاب بيس بما كانوا يفسقون࣌', NULL, 172, 'local:warsh-text.json'),
  ('warsh-7-166', 'warsh', 7, 166, 'فَلَمَّا عَتَوْاْ عَن مَّا نُهُواْ عَنْهُ قُلْنَا لَهُمْ كُونُواْ قِرَدَةً خَٰسِـِٕينَ࣌', 'فلما عتوا عن ما نهوا عنه قلنا لهم كونوا قردة خسين࣌', NULL, 172, 'local:warsh-text.json'),
  ('warsh-7-167', 'warsh', 7, 167, 'وَإِذْ تَأَذَّنَ رَبُّكَ لَيَبْعَثَنَّ عَلَيْهِمُۥٓ إِلَىٰ يَوْمِ ࡴ۬لْقِيَٰمَةِ مَنْ يَّسُومُهُمْ سُوٓءَ ࡰ۬لْعَذَابِ࣌ إِنَّ رَبَّكَ لَسَرِيعُ ࡲ۬لْعِقَابِ࣌ وَإِنَّهُۥ لَغَفُورࣱ رَّحِيمࣱ࣌', 'وإذ تأذن ربك ليبعثن عليهم إلى يوم ࡴلقيمة من يسومهم سوء ࡰلعذاب࣌ إن ربك لسريع ࡲلعقاب࣌ وإنه لغفور رحيم࣌', NULL, 172, 'local:warsh-text.json'),
  ('warsh-7-168', 'warsh', 7, 168, 'وَقَطَّعْنَٰهُمْ فِے ࡴ۬لَارْضِ أُمَماࣰ࣌ مِّنْهُمُ ࡲ۬لصَّٰلِحُونَ࣌ وَمِنْهُمْ دُونَ ذَٰلِكَ࣌ وَبَلَوْنَٰهُم بِالْحَسَنَٰتِ وَالسَّيِّـَٔاتِ لَعَلَّهُمْ يَرْجِعُونَ࣌', 'وقطعنهم فے ࡴلارض أمما࣌ منهم ࡲلصلحون࣌ ومنهم دون ذلك࣌ وبلونهم بالحسنت والسيات لعلهم يرجعون࣌', NULL, 172, 'local:warsh-text.json'),
  ('warsh-7-169', 'warsh', 7, 169, 'فَخَلَفَ مِنۢ بَعْدِهِمْ خَلْفࣱ وَرِثُواْ ࡲ۬لْكِتَٰبَ يَاخُذُونَ عَرَضَ هَٰذَا ࡰ۬لَادْنٜىٰ وَيَقُولُونَ سَيُغْفَرُ لَنَا وَإِنْ يَّاتِهِمْ عَرَضࣱ مِّثْلُهُۥ يَاخُذُوهُ࣌ أَلَمْ يُوخَذْ عَلَيْهِم مِّيثَٰقُ ࡲ۬لْكِتَٰبِ أَن لَّا يَقُولُواْ عَلَى ࡰ۬للَّهِ إِلَّا ࡰ۬لْحَقَّ࣌ وَدَرَسُواْ مَا فِيهِ࣌ وَالدَّارُ ࡲ۬لَاخِرَةُ خَيْرࣱ لِّلذِينَ يَتَّقُونَ࣌ أَفَلَا تَعْقِلُونَ࣌', 'فخلف من بعدهم خلف ورثوا ࡲلكتب ياخذون عرض هذا ࡰلادنى ويقولون سيغفر لنا وإن ياتهم عرض مثله ياخذوه࣌ ألم يوخذ عليهم ميثق ࡲلكتب أن لا يقولوا على ࡰلله إلا ࡰلحق࣌ ودرسوا ما فيه࣌ والدار ࡲلاخرة خير للذين يتقون࣌ أفلا تعقلون࣌', NULL, 172, 'local:warsh-text.json'),
  ('warsh-7-170', 'warsh', 7, 170, 'وَالذِينَ يُمَسِّكُونَ بِالْكِتَٰبِ وَأَقَامُواْ ࡲ۬لصَّلَوٰةَ إِنَّا لَا نُضِيعُ أَجْرَ ࡰ۬لْمُصْلِحِينَ࣌', 'والذين يمسكون بالكتب وأقاموا ࡲلصلوة إنا لا نضيع أجر ࡰلمصلحين࣌', NULL, 172, 'local:warsh-text.json'),
  ('warsh-7-171', 'warsh', 7, 171, '۞ وَإِذْ نَتَقْنَا ࡰ۬لْجَبَلَ فَوْقَهُمْ كَأَنَّهُۥ ظُلَّةࣱ وَظَنُّوٓاْ أَنَّهُۥ وَاقِعُۢ بِهِمْ࣌ خُذُواْ مَآ ءَاتَيْنَٰكُم بِقُوَّةࣲ وَاذْكُرُواْ مَا فِيهِ لَعَلَّكُمْ تَتَّقُونَ࣌', 'وإذ نتقنا ࡰلجبل فوقهم كأنه ظلة وظنوا أنه واقع بهم࣌ خذوا ما ءاتينكم بقوة واذكروا ما فيه لعلكم تتقون࣌', NULL, 173, 'local:warsh-text.json'),
  ('warsh-7-172', 'warsh', 7, 172, 'وَإِذَ ࡰخَذَ رَبُّكَ مِنۢ بَنِےٓ ءَادَمَ مِن ظُهُورِهِمْ ذُرِّيَّٰتِهِمْ وَأَشْهَدَهُمْ عَلَىٰٓ أَنفُسِهِمُۥٓ أَلَسْتُ بِرَبِّكُمْ قَالُواْ بَلٜىٰ࣌ شَهِدْنَآ أَن تَقُولُواْ يَوْمَ ࡰ۬لْقِيَٰمَةِ إِنَّا كُنَّا عَنْ هَٰذَا غَٰفِلِينَ', 'وإذ ࡰخذ ربك من بنے ءادم من ظهورهم ذريتهم وأشهدهم على أنفسهم ألست بربكم قالوا بلى࣌ شهدنا أن تقولوا يوم ࡰلقيمة إنا كنا عن هذا غفلين', NULL, 173, 'local:warsh-text.json'),
  ('warsh-7-173', 'warsh', 7, 173, 'أَوْ تَقُولُوٓاْ إِنَّمَآ أَشْرَكَ ءَابَآؤُنَا مِن قَبْلُ وَكُنَّا ذُرِّيَّةࣰ مِّنۢ بَعْدِهِمُۥٓ࣌ أَفَتُهْلِكُنَا بِمَا فَعَلَ ࡰ۬لْمُبْطِلُونَ࣌', 'أو تقولوا إنما أشرك ءاباؤنا من قبل وكنا ذرية من بعدهم࣌ أفتهلكنا بما فعل ࡰلمبطلون࣌', NULL, 173, 'local:warsh-text.json'),
  ('warsh-7-174', 'warsh', 7, 174, 'وَكَذَٰلِكَ نُفَصِّلُ ࡲ۬لَايَٰتِ وَلَعَلَّهُمْ يَرْجِعُونَ࣌', 'وكذلك نفصل ࡲلايت ولعلهم يرجعون࣌', NULL, 173, 'local:warsh-text.json'),
  ('warsh-7-175', 'warsh', 7, 175, 'وَاتْلُ عَلَيْهِمْ نَبَأَ ࡰ۬لذِےٓ ءَاتَيْنَٰهُ ءَايَٰتِنَا فَانسَلَخَ مِنْهَا فَأَتْبَعَهُ ࡲ۬لشَّيْطَٰنُ فَكَانَ مِنَ ࡰ۬لْغَاوِينَ࣌', 'واتل عليهم نبأ ࡰلذے ءاتينه ءايتنا فانسلخ منها فأتبعه ࡲلشيطن فكان من ࡰلغاوين࣌', NULL, 173, 'local:warsh-text.json'),
  ('warsh-7-176', 'warsh', 7, 176, 'وَلَوْ شِئْنَا لَرَفَعْنَٰهُ بِهَا وَلَٰكِنَّهُۥٓ أَخْلَدَ إِلَى ࡰ۬لَارْضِ وَاتَّبَعَ هَوٜيٰهُ࣌ فَمَثَلُهُۥ كَمَثَلِ ࡴ۬لْكَلْبِ إِن تَحْمِلْ عَلَيْهِ يَلْهَثَ ࡰوْ تَتْرُكْهُ يَلْهَثْ࣌ ذَٰلِكَ مَثَلُ ࡲ۬لْقَوْمِ ࡴ۬لذِينَ كَذَّبُواْ بِـَٔايَٰتِنَا࣌ فَاقْصُصِ ࡴ۬لْقَصَصَ لَعَلَّهُمْ يَتَفَكَّرُونَ࣌', 'ولو شئنا لرفعنه بها ولكنه أخلد إلى ࡰلارض واتبع هويه࣌ فمثله كمثل ࡴلكلب إن تحمل عليه يلهث ࡰو تتركه يلهث࣌ ذلك مثل ࡲلقوم ࡴلذين كذبوا بايتنا࣌ فاقصص ࡴلقصص لعلهم يتفكرون࣌', NULL, 173, 'local:warsh-text.json'),
  ('warsh-7-177', 'warsh', 7, 177, 'سَآءَ مَثَلاً ࡴ۬لْقَوْمُ ࡲ۬لذِينَ كَذَّبُواْ بِـَٔايَٰتِنَا وَأَنفُسَهُمْ كَانُواْ يَظْلِمُونَ࣌', 'ساء مثلا ࡴلقوم ࡲلذين كذبوا بايتنا وأنفسهم كانوا يظلمون࣌', NULL, 173, 'local:warsh-text.json'),
  ('warsh-7-178', 'warsh', 7, 178, 'مَنْ يَّهْدِ ࡴ۬للَّهُ فَهُوَ ࡰ۬لْمُهْتَدِے࣌ وَمَنْ يُّضْلِلْ فَأُوْلَٰٓئِكَ هُمُ ࡲ۬لْخَٰسِرُونَ࣌', 'من يهد ࡴلله فهو ࡰلمهتدے࣌ ومن يضلل فأولئك هم ࡲلخسرون࣌', NULL, 173, 'local:warsh-text.json'),
  ('warsh-7-179', 'warsh', 7, 179, '۞ وَلَقَدْ ذَرَأْنَا لِجَهَنَّمَ كَثِيراࣰ مِّنَ ࡰ۬لْجِنِّ وَالِانسِ࣌ لَهُمْ قُلُوبࣱ لَّا يَفْقَهُونَ بِهَا࣌ وَلَهُمُۥٓ أَعْيُنࣱ لَّا يُبْصِرُونَ بِهَا࣌ وَلَهُمُۥٓ ءَاذَانࣱ لَّا يَسْمَعُونَ بِهَآ࣌ أُوْلَٰٓئِكَ كَالَانْعَٰمِ بَلْ هُمُۥٓ أَضَلُّ࣌ أُوْلَٰٓئِكَ هُمُ ࡲ۬لْغَٰفِلُونَ࣌', 'ولقد ذرأنا لجهنم كثيرا من ࡰلجن والانس࣌ لهم قلوب لا يفقهون بها࣌ ولهم أعين لا يبصرون بها࣌ ولهم ءاذان لا يسمعون بها࣌ أولئك كالانعم بل هم أضل࣌ أولئك هم ࡲلغفلون࣌', NULL, 174, 'local:warsh-text.json'),
  ('warsh-7-180', 'warsh', 7, 180, 'وَلِلهِ ࡴ۬لَاسْمَآءُ ࡲ۬لْحُسْنٜىٰ فَادْعُوهُ بِهَا࣌ وَذَرُواْ ࡲ۬لذِينَ يُلْحِدُونَ فِےٓ أَسْمَٰٓئِهِۦ࣌ سَيُجْزَوْنَ مَا كَانُواْ يَعْمَلُونَ࣌', 'ولله ࡴلاسماء ࡲلحسنى فادعوه بها࣌ وذروا ࡲلذين يلحدون فے أسمئه࣌ سيجزون ما كانوا يعملون࣌', NULL, 174, 'local:warsh-text.json'),
  ('warsh-7-181', 'warsh', 7, 181, 'وَمِمَّنْ خَلَقْنَآ أُمَّةࣱ يَهْدُونَ بِالْحَقِّ وَبِهِۦ يَعْدِلُونَ࣌', 'وممن خلقنا أمة يهدون بالحق وبه يعدلون࣌', NULL, 174, 'local:warsh-text.json'),
  ('warsh-7-182', 'warsh', 7, 182, 'وَالذِينَ كَذَّبُواْ بِـَٔايَٰتِنَا سَنَسْتَدْرِجُهُم مِّنْ حَيْثُ لَا يَعْلَمُونَ', 'والذين كذبوا بايتنا سنستدرجهم من حيث لا يعلمون', NULL, 174, 'local:warsh-text.json'),
  ('warsh-7-183', 'warsh', 7, 183, 'وَأُمْلِے لَهُمُۥٓ࣌ إِنَّ كَيْدِے مَتِينٌ࣌', 'وأملے لهم࣌ إن كيدے متين࣌', NULL, 174, 'local:warsh-text.json'),
  ('warsh-7-184', 'warsh', 7, 184, 'ࡰوَلَمْ يَتَفَكَّرُواْ࣌ مَا بِصَٰحِبِهِم مِّن جِنَّةٍ࣌ ࡴنْ هُوَ إِلَّا نَذِيرࣱ مُّبِينٌ࣌', 'ࡰولم يتفكروا࣌ ما بصحبهم من جنة࣌ ࡴن هو إلا نذير مبين࣌', NULL, 174, 'local:warsh-text.json'),
  ('warsh-7-185', 'warsh', 7, 185, 'ࡰوَلَمْ يَنظُرُواْ فِے مَلَكُوتِ ࡴ۬لسَّمَٰوَٰتِ وَالَارْضِ وَمَا خَلَقَ ࡰ۬للَّهُ مِن شَےْءࣲ وَأَنْ عَسٜىٰٓ أَنْ يَّكُونَ قَدِ ࡴٜقْتَرَبَ أَجَلُهُمْ࣌ فَبِأَيِّ حَدِيثِۢ بَعْدَهُۥ يُومِنُونَ࣌', 'ࡰولم ينظروا فے ملكوت ࡴلسموت والارض وما خلق ࡰلله من شےء وأن عسى أن يكون قد ࡴقترب أجلهم࣌ فبأي حديث بعده يومنون࣌', NULL, 174, 'local:warsh-text.json'),
  ('warsh-7-186', 'warsh', 7, 186, 'مَنْ يُّضْلِلِ ࡴ۬للَّهُ فَلَا هَادِيَ لَهُۥ࣌ وَنَذَرُهُمْ فِے طُغْيَٰنِهِمْ يَعْمَهُونَ࣌', 'من يضلل ࡴلله فلا هادي له࣌ ونذرهم فے طغينهم يعمهون࣌', NULL, 174, 'local:warsh-text.json'),
  ('warsh-7-187', 'warsh', 7, 187, 'يَسْـَٔلُونَكَ عَنِ ࡴ۬لسَّاعَةِ أَيَّانَ مُرْسٜيٰهَا࣌ قُلِ ࡴنَّمَا عِلْمُهَا عِندَ رَبِّے࣌ لَا يُجَلِّيهَا لِوَقْتِهَآ إِلَّا هُوَ࣌ ثَقُلَتْ فِے ࡴ۬لسَّمَٰوَٰتِ وَالَارْضِ࣌ لَا تَاتِيكُمُۥٓ إِلَّا بَغْتَةࣰ࣌ يَسْـَٔلُونَكَ كَأَنَّكَ حَفِيٌّ عَنْهَا࣌ قُلِ ࡴنَّمَا عِلْمُهَا عِندَ ࡰ۬للَّهِ࣌ وَلَٰكِنَّ أَكْثَرَ ࡰ۬لنَّاسِ لَا يَعْلَمُونَ࣌', 'يسلونك عن ࡴلساعة أيان مرسيها࣌ قل ࡴنما علمها عند ربے࣌ لا يجليها لوقتها إلا هو࣌ ثقلت فے ࡴلسموت والارض࣌ لا تاتيكم إلا بغتة࣌ يسلونك كأنك حفي عنها࣌ قل ࡴنما علمها عند ࡰلله࣌ ولكن أكثر ࡰلناس لا يعلمون࣌', NULL, 174, 'local:warsh-text.json'),
  ('warsh-7-188', 'warsh', 7, 188, '۞ قُل لَّآ أَمْلِكُ لِنَفْسِے نَفْعاࣰ وَلَا ضَرّاً ࡴلَّا مَا شَآءَ ࡰ۬للَّهُ࣌ وَلَوْ كُنتُ أَعْلَمُ ࡲ۬لْغَيْبَ لَاسْتَكْثَرْتُ مِنَ ࡰ۬لْخَيْرِ࣌ وَمَا مَسَّنِيَ ࡰ۬لسُّوٓءُ࣌ ࡹِنَ ࡰنَا إِلَّا نَذِيرࣱ࣌ وَبَشِيرࣱ لِّقَوْمࣲ يُومِنُونَ࣌', 'قل لا أملك لنفسے نفعا ولا ضرا ࡴلا ما شاء ࡰلله࣌ ولو كنت أعلم ࡲلغيب لاستكثرت من ࡰلخير࣌ وما مسني ࡰلسوء࣌ ࡹن ࡰنا إلا نذير࣌ وبشير لقوم يومنون࣌', NULL, 175, 'local:warsh-text.json'),
  ('warsh-7-189', 'warsh', 7, 189, 'هُوَ ࡰ۬لذِے خَلَقَكُم مِّن نَّفْسࣲ وَٰحِدَةࣲ وَجَعَلَ مِنْهَا زَوْجَهَا لِيَسْكُنَ إِلَيْهَا࣌ فَلَمَّا تَغَشّٜيٰهَا حَمَلَتْ حَمْلاً خَفِيفاࣰ فَمَرَّتْ بِهِۦ࣌ فَلَمَّآ أَثْقَلَت دَّعَوَا ࡰ۬للَّهَ رَبَّهُمَا لَئِنَ اٰتَيْتَنَا صَٰلِحاࣰ لَّنَكُونَنَّ مِنَ ࡰ۬لشَّٰكِرِينَ࣌', 'هو ࡰلذے خلقكم من نفس وحدة وجعل منها زوجها ليسكن إليها࣌ فلما تغشيها حملت حملا خفيفا فمرت به࣌ فلما أثقلت دعوا ࡰلله ربهما لئن اتيتنا صلحا لنكونن من ࡰلشكرين࣌', NULL, 175, 'local:warsh-text.json'),
  ('warsh-7-190', 'warsh', 7, 190, 'فَلَمَّآ ءَاتٜيٰهُمَا صَٰلِحاࣰ جَعَلَا لَهُۥ شِرْكاࣰ فِيمَآ ءَاتٜيٰهُمَا࣌ فَتَعَٰلَى ࡰ۬للَّهُ عَمَّا يُشْرِكُونَ࣌', 'فلما ءاتيهما صلحا جعلا له شركا فيما ءاتيهما࣌ فتعلى ࡰلله عما يشركون࣌', NULL, 175, 'local:warsh-text.json'),
  ('warsh-7-191', 'warsh', 7, 191, 'أَيُشْرِكُونَ مَا لَا يَخْلُقُ شَيْـٔاࣰ وَهُمْ يُخْلَقُونَ࣌', 'أيشركون ما لا يخلق شيا وهم يخلقون࣌', NULL, 175, 'local:warsh-text.json'),
  ('warsh-7-192', 'warsh', 7, 192, 'وَلَا يَسْتَطِيعُونَ لَهُمْ نَصْراࣰ وَلَآ أَنفُسَهُمْ يَنصُرُونَ࣌', 'ولا يستطيعون لهم نصرا ولا أنفسهم ينصرون࣌', NULL, 175, 'local:warsh-text.json'),
  ('warsh-7-193', 'warsh', 7, 193, 'وَإِن تَدْعُوهُمُۥٓ إِلَى ࡰ۬لْهُدٜىٰ لَا يَتْبَعُوكُمْ࣌ سَوَآءٌ عَلَيْكُمُۥٓ أَدَعَوْتُمُوهُمُۥٓ أَمَ ࡰنتُمْ صَٰمِتُونَ࣌', 'وإن تدعوهم إلى ࡰلهدى لا يتبعوكم࣌ سواء عليكم أدعوتموهم أم ࡰنتم صمتون࣌', NULL, 175, 'local:warsh-text.json'),
  ('warsh-7-194', 'warsh', 7, 194, 'إِنَّ ࡰ۬لذِينَ تَدْعُونَ مِن دُونِ ࡴ۬للَّهِ عِبَادٌ ࡰمْثَالُكُمْ࣌ فَادْعُوهُمْ فَلْيَسْتَجِيبُواْ لَكُمُۥٓ إِن كُنتُمْ صَٰدِقِينَ࣌', 'إن ࡰلذين تدعون من دون ࡴلله عباد ࡰمثالكم࣌ فادعوهم فليستجيبوا لكم إن كنتم صدقين࣌', NULL, 175, 'local:warsh-text.json'),
  ('warsh-7-195', 'warsh', 7, 195, 'أَلَهُمُۥٓ أَرْجُلࣱ يَمْشُونَ بِهَآ࣌ أَمْ لَهُمُۥٓ أَيْدࣲ يَبْطِشُونَ بِهَآ࣌ أَمْ لَهُمُۥٓ أَعْيُنࣱ يُبْصِرُونَ بِهَآ࣌ أَمْ لَهُمُۥٓ ءَاذَانࣱ يَسْمَعُونَ بِهَا࣌ قُلُ ࡲ࢈دْعُواْ شُرَكَآءَكُمْ ثُمَّ كِيدُونِ فَلَا تُنظِرُونِ࣌', 'ألهم أرجل يمشون بها࣌ أم لهم أيد يبطشون بها࣌ أم لهم أعين يبصرون بها࣌ أم لهم ءاذان يسمعون بها࣌ قل ࡲ࢈دعوا شركاءكم ثم كيدون فلا تنظرون࣌', NULL, 175, 'local:warsh-text.json'),
  ('warsh-7-196', 'warsh', 7, 196, 'إِنَّ وَلِيِّيَ ࡰ۬للَّهُ ࡲ۬لذِے نَزَّلَ ࡰ۬لْكِتَٰبَ࣌ وَهُوَ يَتَوَلَّى ࡰ۬لصَّٰلِحِينَ࣌', 'إن وليي ࡰلله ࡲلذے نزل ࡰلكتب࣌ وهو يتولى ࡰلصلحين࣌', NULL, 176, 'local:warsh-text.json'),
  ('warsh-7-197', 'warsh', 7, 197, 'وَالذِينَ تَدْعُونَ مِن دُونِهِۦ لَا يَسْتَطِيعُونَ نَصْرَكُمْ وَلَآ أَنفُسَهُمْ يَنصُرُونَ࣌', 'والذين تدعون من دونه لا يستطيعون نصركم ولا أنفسهم ينصرون࣌', NULL, 176, 'local:warsh-text.json'),
  ('warsh-7-198', 'warsh', 7, 198, 'وَإِن تَدْعُوهُمُۥٓ إِلَى ࡰ۬لْهُدٜىٰ لَا يَسْمَعُواْ࣌ وَتَرٜيٰهُمْ يَنظُرُونَ إِلَيْكَ وَهُمْ لَا يُبْصِرُونَ࣌', 'وإن تدعوهم إلى ࡰلهدى لا يسمعوا࣌ وتريهم ينظرون إليك وهم لا يبصرون࣌', NULL, 176, 'local:warsh-text.json'),
  ('warsh-7-199', 'warsh', 7, 199, 'خُذِ ࡴ۬لْعَفْوَ࣌ وَامُرْ بِالْعُرْفِ࣌ وَأَعْرِضْ عَنِ ࡴ۬لْجَٰهِلِينَ࣌', 'خذ ࡴلعفو࣌ وامر بالعرف࣌ وأعرض عن ࡴلجهلين࣌', NULL, 176, 'local:warsh-text.json'),
  ('warsh-7-200', 'warsh', 7, 200, '۞ وَإِمَّا يَنزَغَنَّكَ مِنَ ࡰ۬لشَّيْطَٰنِ نَزْغࣱ فَاسْتَعِذْ بِاللَّهِ࣌ إِنَّهُۥ سَمِيعٌ عَلِيمٌ࣌', 'وإما ينزغنك من ࡰلشيطن نزغ فاستعذ بالله࣌ إنه سميع عليم࣌', NULL, 176, 'local:warsh-text.json'),
  ('warsh-7-201', 'warsh', 7, 201, 'ࡴنَّ ࡰ۬لذِينَ ࡰٜتَّقَوِاْ ࡴذَا مَسَّهُمْ طَٰٓئِفࣱ مِّنَ ࡰ۬لشَّيْطَٰنِ تَذَكَّرُواْ فَإِذَا هُم مُّبْصِرُونَ࣌', 'ࡴن ࡰلذين ࡰتقوا ࡴذا مسهم طئف من ࡰلشيطن تذكروا فإذا هم مبصرون࣌', NULL, 176, 'local:warsh-text.json'),
  ('warsh-7-202', 'warsh', 7, 202, 'وَإِخْوَٰنُهُمْ يُمِدُّونَهُمْ فِے ࡴ۬لْغَيِّ࣌ ثُمَّ لَا يُقْصِرُونَ࣌', 'وإخونهم يمدونهم فے ࡴلغي࣌ ثم لا يقصرون࣌', NULL, 176, 'local:warsh-text.json'),
  ('warsh-7-203', 'warsh', 7, 203, 'وَإِذَا لَمْ تَاتِهِم بِـَٔايَةࣲ قَالُواْ لَوْلَا ࡰٜجْتَبَيْتَهَا࣌ قُلِ ࡴنَّمَآ أَتَّبِعُ مَا يُوحٜىٰٓ إِلَيَّ مِن رَّبِّے࣌ هَٰذَا بَصَآئِرُ مِن رَّبِّكُمْ وَهُدىࣰ وَرَحْمَةࣱ لِّقَوْمࣲ يُومِنُونَ࣌', 'وإذا لم تاتهم باية قالوا لولا ࡰجتبيتها࣌ قل ࡴنما أتبع ما يوحى إلي من ربے࣌ هذا بصائر من ربكم وهدى ورحمة لقوم يومنون࣌', NULL, 176, 'local:warsh-text.json'),
  ('warsh-7-204', 'warsh', 7, 204, 'وَإِذَا قُرِۓَ ࡰ۬لْقُرْءَانُ فَاسْتَمِعُواْ لَهُۥ وَأَنصِتُواْ لَعَلَّكُمْ تُرْحَمُونَ࣌', 'وإذا قرے ࡰلقرءان فاستمعوا له وأنصتوا لعلكم ترحمون࣌', NULL, 176, 'local:warsh-text.json'),
  ('warsh-7-205', 'warsh', 7, 205, 'وَاذْكُر رَّبَّكَ فِے نَفْسِكَ تَضَرُّعاࣰ وَخِيفَةࣰ وَدُونَ ࡰ۬لْجَهْرِ مِنَ ࡰ۬لْقَوْلِ بِالْغُدُوِّ وَالَاصَالِ وَلَا تَكُن مِّنَ ࡰ۬لْغَٰفِلِينَ࣌', 'واذكر ربك فے نفسك تضرعا وخيفة ودون ࡰلجهر من ࡰلقول بالغدو والاصال ولا تكن من ࡰلغفلين࣌', NULL, 176, 'local:warsh-text.json'),
  ('warsh-7-206', 'warsh', 7, 206, 'إِنَّ ࡰ۬لذِينَ عِندَ رَبِّكَ لَا يَسْتَكْبِرُونَ عَنْ عِبَادَتِهِۦ وَيُسَبِّحُونَهُۥ وَلَهُۥ يَسْجُدُونَ࣌۩', 'إن ࡰلذين عند ربك لا يستكبرون عن عبادته ويسبحونه وله يسجدون࣌', NULL, 176, 'local:warsh-text.json'),
  ('warsh-8-1', 'warsh', 8, 1, 'يَسْـَٔلُونَكَ عَنِ ࡴ۬لَانفَالِ࣌ قُلِ ࡴ۬لَانفَالُ لِلهِ وَالرَّسُولِ࣌ فَاتَّقُواْ ࡲ۬للَّهَ وَأَصْلِحُواْ ذَاتَ بَيْنِكُمْ࣌ وَأَطِيعُواْ ࡲ۬للَّهَ وَرَسُولَهُۥٓ إِن كُنتُم مُّومِنِينَ࣌', 'يسلونك عن ࡴلانفال࣌ قل ࡴلانفال لله والرسول࣌ فاتقوا ࡲلله وأصلحوا ذات بينكم࣌ وأطيعوا ࡲلله ورسوله إن كنتم مومنين࣌', NULL, 177, 'local:warsh-text.json'),
  ('warsh-8-2', 'warsh', 8, 2, 'إِنَّمَا ࡰ۬لْمُومِنُونَ ࡰ۬لذِينَ إِذَا ذُكِرَ ࡰ۬للَّهُ وَجِلَتْ قُلُوبُهُمْ وَإِذَا تُلِيَتْ عَلَيْهِمُۥٓ ءَايَٰتُهُۥ زَادَتْهُمُۥٓ إِيمَٰناࣰ وَعَلَىٰ رَبِّهِمْ يَتَوَكَّلُونَ࣌', 'إنما ࡰلمومنون ࡰلذين إذا ذكر ࡰلله وجلت قلوبهم وإذا تليت عليهم ءايته زادتهم إيمنا وعلى ربهم يتوكلون࣌', NULL, 177, 'local:warsh-text.json'),
  ('warsh-8-3', 'warsh', 8, 3, 'ࡰ۬لذِينَ يُقِيمُونَ ࡰ۬لصَّلَوٰةَ وَمِمَّا رَزَقْنَٰهُمْ يُنفِقُونَ', 'ࡰلذين يقيمون ࡰلصلوة ومما رزقنهم ينفقون', NULL, 177, 'local:warsh-text.json'),
  ('warsh-8-4', 'warsh', 8, 4, 'أُوْلَٰٓئِكَ هُمُ ࡲ۬لْمُومِنُونَ حَقّاࣰ࣌ لَّهُمْ دَرَجَٰتٌ عِندَ رَبِّهِمْ وَمَغْفِرَةࣱ وَرِزْقࣱ كَرِيمࣱ࣌', 'أولئك هم ࡲلمومنون حقا࣌ لهم درجت عند ربهم ومغفرة ورزق كريم࣌', NULL, 177, 'local:warsh-text.json'),
  ('warsh-8-5', 'warsh', 8, 5, '۞ كَمَآ أَخْرَجَكَ رَبُّكَ مِنۢ بَيْتِكَ بِالْحَقِّ وَإِنَّ فَرِيقاࣰ مِّنَ ࡰ۬لْمُومِنِينَ لَكَٰرِهُونَ', 'كما أخرجك ربك من بيتك بالحق وإن فريقا من ࡰلمومنين لكرهون', NULL, 177, 'local:warsh-text.json'),
  ('warsh-8-6', 'warsh', 8, 6, 'يُجَٰدِلُونَكَ فِے ࡴ۬لْحَقِّ بَعْدَ مَا تَبَيَّنَ كَأَنَّمَا يُسَاقُونَ إِلَى ࡰ۬لْمَوْتِ وَهُمْ يَنظُرُونَ࣌', 'يجدلونك فے ࡴلحق بعد ما تبين كأنما يساقون إلى ࡰلموت وهم ينظرون࣌', NULL, 177, 'local:warsh-text.json'),
  ('warsh-8-7', 'warsh', 8, 7, 'وَإِذْ يَعِدُكُمُ ࡲ۬للَّهُ إِحْدَى ࡰ۬لطَّآئِفَتَيْنِ أَنَّهَا لَكُمْ وَتَوَدُّونَ أَنَّ غَيْرَ ذَاتِ ࡴ۬لشَّوْكَةِ تَكُونُ لَكُمْ࣌ وَيُرِيدُ ࡲ۬للَّهُ أَنْ يُّحِقَّ ࡰ۬لْحَقَّ بِكَلِمَٰتِهِۦ وَيَقْطَعَ دَابِرَ ࡰ۬لْكٜـٰفِرِينَ', 'وإذ يعدكم ࡲلله إحدى ࡰلطائفتين أنها لكم وتودون أن غير ذات ࡴلشوكة تكون لكم࣌ ويريد ࡲلله أن يحق ࡰلحق بكلمته ويقطع دابر ࡰلكفرين', NULL, 177, 'local:warsh-text.json'),
  ('warsh-8-8', 'warsh', 8, 8, 'لِيُحِقَّ ࡰ۬لْحَقَّ وَيُبْطِلَ ࡰ۬لْبَٰطِلَ وَلَوْ كَرِهَ ࡰ۬لْمُجْرِمُونَ࣌', 'ليحق ࡰلحق ويبطل ࡰلبطل ولو كره ࡰلمجرمون࣌', NULL, 177, 'local:warsh-text.json'),
  ('warsh-8-9', 'warsh', 8, 9, 'إِذْ تَسْتَغِيثُونَ رَبَّكُمْ فَاسْتَجَابَ لَكُمُۥٓ أَنِّے مُمِدُّكُم بِأَلْفࣲ مِّنَ ࡰ۬لْمَلَٰٓئِكَةِ مُرْدَفِينَ࣌', 'إذ تستغيثون ربكم فاستجاب لكم أنے ممدكم بألف من ࡰلملئكة مردفين࣌', NULL, 178, 'local:warsh-text.json'),
  ('warsh-8-10', 'warsh', 8, 10, 'وَمَا جَعَلَهُ ࡲ۬للَّهُ إِلَّا بُشْرٜىٰ وَلِتَطْمَئِنَّ بِهِۦ قُلُوبُكُمْ࣌ وَمَا ࡰ۬لنَّصْرُ إِلَّا مِنْ عِندِ ࡴ۬للَّهِ࣌ إِنَّ ࡰ۬للَّهَ عَزِيزٌ حَكِيمٌ࣌', 'وما جعله ࡲلله إلا بشرى ولتطمئن به قلوبكم࣌ وما ࡰلنصر إلا من عند ࡴلله࣌ إن ࡰلله عزيز حكيم࣌', NULL, 178, 'local:warsh-text.json'),
  ('warsh-8-11', 'warsh', 8, 11, 'ࡴذْ يُغْشِيكُمُ ࡲ۬لنُّعَاسَ أَمَنَةࣰ مِّنْهُ وَيُنَزِّلُ عَلَيْكُم مِّنَ ࡰ۬لسَّمَآءِ مَآءࣰ لِّيُطَهِّرَكُم بِهِۦ وَيُذْهِبَ عَنكُمْ رِجْزَ ࡰ۬لشَّيْطَٰنِ وَلِيَرْبِطَ عَلَىٰ قُلُوبِكُمْ وَيُثَبِّتَ بِهِ ࡴ۬لَاقْدَامَ࣌', 'ࡴذ يغشيكم ࡲلنعاس أمنة منه وينزل عليكم من ࡰلسماء ماء ليطهركم به ويذهب عنكم رجز ࡰلشيطن وليربط على قلوبكم ويثبت به ࡴلاقدام࣌', NULL, 178, 'local:warsh-text.json'),
  ('warsh-8-12', 'warsh', 8, 12, 'إِذْ يُوحِے رَبُّكَ إِلَى ࡰ۬لْمَلَٰٓئِكَةِ أَنِّے مَعَكُمْ فَثَبِّتُواْ ࡲ۬لذِينَ ءَامَنُواْ࣌ سَأُلْقِے فِے قُلُوبِ ࡴ۬لذِينَ كَفَرُواْ ࡲ۬لرُّعْبَ࣌ فَاضْرِبُواْ فَوْقَ ࡰ۬لَاعْنَاقِ وَاضْرِبُواْ مِنْهُمْ كُلَّ بَنَانࣲ࣌', 'إذ يوحے ربك إلى ࡰلملئكة أنے معكم فثبتوا ࡲلذين ءامنوا࣌ سألقے فے قلوب ࡴلذين كفروا ࡲلرعب࣌ فاضربوا فوق ࡰلاعناق واضربوا منهم كل بنان࣌', NULL, 178, 'local:warsh-text.json'),
  ('warsh-8-13', 'warsh', 8, 13, 'ذَٰلِكَ بِأَنَّهُمْ شَآقُّواْ ࡲ۬للَّهَ وَرَسُولَهُۥ࣌ وَمَنْ يُّشَاقِقِ ࡴ۬للَّهَ وَرَسُولَهُۥ فَإِنَّ ࡰ۬للَّهَ شَدِيدُ ࡲ۬لْعِقَابِ࣌', 'ذلك بأنهم شاقوا ࡲلله ورسوله࣌ ومن يشاقق ࡴلله ورسوله فإن ࡰلله شديد ࡲلعقاب࣌', NULL, 178, 'local:warsh-text.json'),
  ('warsh-8-14', 'warsh', 8, 14, 'ذَٰلِكُمْ فَذُوقُوهُ࣌ وَأَنَّ لِلْكٜـٰفِرِينَ عَذَابَ ࡰ۬لنّٜارِ࣌', 'ذلكم فذوقوه࣌ وأن للكفرين عذاب ࡰلنار࣌', NULL, 178, 'local:warsh-text.json'),
  ('warsh-8-15', 'warsh', 8, 15, '۞ يَٰٓأَيُّهَا ࡰ۬لذِينَ ءَامَنُوٓاْ إِذَا لَقِيتُمُ ࡲ۬لذِينَ كَفَرُواْ زَحْفاࣰ فَلَا تُوَلُّوهُمُ ࡲ۬لَادْبَٰرَ࣌', 'يأيها ࡰلذين ءامنوا إذا لقيتم ࡲلذين كفروا زحفا فلا تولوهم ࡲلادبر࣌', NULL, 178, 'local:warsh-text.json'),
  ('warsh-8-16', 'warsh', 8, 16, 'وَمَنْ يُّوَلِّهِمْ يَوْمَئِذࣲ دُبُرَهُۥٓ إِلَّا مُتَحَرِّفاࣰ لِّقِتَالٍ ࡰوْ مُتَحَيِّزاً ࡴلَىٰ فِئَةࣲ فَقَدْ بَآءَ بِغَضَبࣲ مِّنَ ࡰ۬للَّهِ وَمَأْوٜيٰهُ جَهَنَّمُ࣌ وَبِيسَ ࡰ۬لْمَصِيرُ࣌', 'ومن يولهم يومئذ دبره إلا متحرفا لقتال ࡰو متحيزا ࡴلى فئة فقد باء بغضب من ࡰلله ومأويه جهنم࣌ وبيس ࡰلمصير࣌', NULL, 178, 'local:warsh-text.json'),
  ('warsh-8-17', 'warsh', 8, 17, 'فَلَمْ تَقْتُلُوهُمْ࣌ وَلَٰكِنَّ ࡰ۬للَّهَ قَتَلَهُمْ࣌ وَمَا رَمَيْتَ إِذْ رَمَيْتَ وَلَٰكِنَّ ࡰ۬للَّهَ رَمٜىٰ࣌ وَلِيُبْلِيَ ࡰ۬لْمُومِنِينَ مِنْهُ بَلَآءً حَسَناً࣌ ࡴنَّ ࡰ۬للَّهَ سَمِيعٌ عَلِيمࣱ࣌', 'فلم تقتلوهم࣌ ولكن ࡰلله قتلهم࣌ وما رميت إذ رميت ولكن ࡰلله رمى࣌ وليبلي ࡰلمومنين منه بلاء حسنا࣌ ࡴن ࡰلله سميع عليم࣌', NULL, 179, 'local:warsh-text.json'),
  ('warsh-8-18', 'warsh', 8, 18, 'ذَٰلِكُمْ وَأَنَّ ࡰ۬للَّهَ مُوَهِّنࣱ كَيْدَ ࡰ۬لْكٜـٰفِرِينَ࣌', 'ذلكم وأن ࡰلله موهن كيد ࡰلكفرين࣌', NULL, 179, 'local:warsh-text.json'),
  ('warsh-8-19', 'warsh', 8, 19, 'إِن تَسْتَفْتِحُواْ فَقَدْ جَآءَكُمُ ࡲ۬لْفَتْحُ࣌ وَإِن تَنتَهُواْ فَهُوَ خَيْرࣱ لَّكُمْ࣌ وَإِن تَعُودُواْ نَعُدْ࣌ وَلَن تُغْنِيَ عَنكُمْ فِئَتُكُمْ شَيْـٔاࣰ وَلَوْ كَثُرَتْ࣌ وَأَنَّ ࡰ۬للَّهَ مَعَ ࡰ۬لْمُومِنِينَ࣌', 'إن تستفتحوا فقد جاءكم ࡲلفتح࣌ وإن تنتهوا فهو خير لكم࣌ وإن تعودوا نعد࣌ ولن تغني عنكم فئتكم شيا ولو كثرت࣌ وأن ࡰلله مع ࡰلمومنين࣌', NULL, 179, 'local:warsh-text.json'),
  ('warsh-8-20', 'warsh', 8, 20, 'يَٰٓأَيُّهَا ࡰ۬لذِينَ ءَامَنُوٓاْ أَطِيعُواْ ࡲ۬للَّهَ وَرَسُولَهُۥ࣌ وَلَا تَوَلَّوْاْ عَنْهُ وَأَنتُمْ تَسْمَعُونَ࣌', 'يأيها ࡰلذين ءامنوا أطيعوا ࡲلله ورسوله࣌ ولا تولوا عنه وأنتم تسمعون࣌', NULL, 179, 'local:warsh-text.json'),
  ('warsh-8-21', 'warsh', 8, 21, 'وَلَا تَكُونُواْ كَالذِينَ قَالُواْ سَمِعْنَا وَهُمْ لَا يَسْمَعُونَ࣌', 'ولا تكونوا كالذين قالوا سمعنا وهم لا يسمعون࣌', NULL, 179, 'local:warsh-text.json'),
  ('warsh-8-22', 'warsh', 8, 22, '۞ إِنَّ شَرَّ ࡰ۬لدَّوَآبِّ عِندَ ࡰ۬للَّهِ ࡴ۬لصُّمُّ ࡲ۬لْبُكْمُ ࡲ۬لذِينَ لَا يَعْقِلُونَ࣌', 'إن شر ࡰلدواب عند ࡰلله ࡴلصم ࡲلبكم ࡲلذين لا يعقلون࣌', NULL, 179, 'local:warsh-text.json'),
  ('warsh-8-23', 'warsh', 8, 23, 'وَلَوْ عَلِمَ ࡰ۬للَّهُ فِيهِمْ خَيْراࣰ لَّأَسْمَعَهُمْ࣌ وَلَوَ ࡰسْمَعَهُمْ لَتَوَلَّواْ وَّهُم مُّعْرِضُونَ࣌', 'ولو علم ࡰلله فيهم خيرا لأسمعهم࣌ ولو ࡰسمعهم لتولوا وهم معرضون࣌', NULL, 179, 'local:warsh-text.json'),
  ('warsh-8-24', 'warsh', 8, 24, 'يَٰٓأَيُّهَا ࡰ۬لذِينَ ءَامَنُواْ ࡲٜسْتَجِيبُواْ لِلهِ وَلِلرَّسُولِ إِذَا دَعَاكُمْ لِمَا يُحْيِيكُمْ࣌ وَاعْلَمُوٓاْ أَنَّ ࡰ۬للَّهَ يَحُولُ بَيْنَ ࡰ۬لْمَرْءِ وَقَلْبِهِۦ وَأَنَّهُۥٓ إِلَيْهِ تُحْشَرُونَ࣌', 'يأيها ࡰلذين ءامنوا ࡲستجيبوا لله وللرسول إذا دعاكم لما يحييكم࣌ واعلموا أن ࡰلله يحول بين ࡰلمرء وقلبه وأنه إليه تحشرون࣌', NULL, 179, 'local:warsh-text.json'),
  ('warsh-8-25', 'warsh', 8, 25, 'وَاتَّقُواْ فِتْنَةࣰ لَّا تُصِيبَنَّ ࡰ۬لذِينَ ظَلَمُواْ مِنكُمْ خَآصَّةࣰ࣌ وَاعْلَمُوٓاْ أَنَّ ࡰ۬للَّهَ شَدِيدُ ࡲ۬لْعِقَابِ࣌', 'واتقوا فتنة لا تصيبن ࡰلذين ظلموا منكم خاصة࣌ واعلموا أن ࡰلله شديد ࡲلعقاب࣌', NULL, 179, 'local:warsh-text.json'),
  ('warsh-8-26', 'warsh', 8, 26, 'وَاذْكُرُوٓاْ إِذَ ࡰنتُمْ قَلِيلࣱ مُّسْتَضْعَفُونَ فِے ࡴ۬لَارْضِ تَخَافُونَ أَنْ يَّتَخَطَّفَكُمُ ࡲ۬لنَّاسُ فَـَٔاوٜيٰكُمْ وَأَيَّدَكُم بِنَصْرِهِۦ وَرَزَقَكُم مِّنَ ࡰ۬لطَّيِّبَٰتِ لَعَلَّكُمْ تَشْكُرُونَ࣌', 'واذكروا إذ ࡰنتم قليل مستضعفون فے ࡴلارض تخافون أن يتخطفكم ࡲلناس فاويكم وأيدكم بنصره ورزقكم من ࡰلطيبت لعلكم تشكرون࣌', NULL, 180, 'local:warsh-text.json'),
  ('warsh-8-27', 'warsh', 8, 27, 'يَٰٓأَيُّهَا ࡰ۬لذِينَ ءَامَنُواْ لَا تَخُونُواْ ࡲ۬للَّهَ وَالرَّسُولَ وَتَخُونُوٓاْ أَمَٰنَٰتِكُمْ وَأَنتُمْ تَعْلَمُونَ࣌', 'يأيها ࡰلذين ءامنوا لا تخونوا ࡲلله والرسول وتخونوا أمنتكم وأنتم تعلمون࣌', NULL, 180, 'local:warsh-text.json'),
  ('warsh-8-28', 'warsh', 8, 28, 'وَاعْلَمُوٓاْ أَنَّمَآ أَمْوَٰلُكُمْ وَأَوْلَٰدُكُمْ فِتْنَةࣱ وَأَنَّ ࡰ۬للَّهَ عِندَهُۥٓ أَجْرٌ عَظِيمࣱ࣌', 'واعلموا أنما أمولكم وأولدكم فتنة وأن ࡰلله عنده أجر عظيم࣌', NULL, 180, 'local:warsh-text.json'),
  ('warsh-8-29', 'warsh', 8, 29, 'يَٰٓأَيُّهَا ࡰ۬لذِينَ ءَامَنُوٓاْ إِن تَتَّقُواْ ࡲ۬للَّهَ يَجْعَل لَّكُمْ فُرْقَاناࣰ وَيُكَفِّرْ عَنكُمْ سَيِّـَٔاتِكُمْ وَيَغْفِرْ لَكُمْ࣌ وَاللَّهُ ذُو ࡲ۬لْفَضْلِ ࡴ۬لْعَظِيمِ࣌', 'يأيها ࡰلذين ءامنوا إن تتقوا ࡲلله يجعل لكم فرقانا ويكفر عنكم سياتكم ويغفر لكم࣌ والله ذو ࡲلفضل ࡴلعظيم࣌', NULL, 180, 'local:warsh-text.json'),
  ('warsh-8-30', 'warsh', 8, 30, 'وَإِذْ يَمْكُرُ بِكَ ࡰ۬لذِينَ كَفَرُواْ لِيُثْبِتُوكَ أَوْ يَقْتُلُوكَ أَوْ يُخْرِجُوكَ࣌ وَيَمْكُرُونَ وَيَمْكُرُ ࡲ۬للَّهُ࣌ وَاللَّهُ خَيْرُ ࡲ۬لْمَٰكِرِينَ࣌', 'وإذ يمكر بك ࡰلذين كفروا ليثبتوك أو يقتلوك أو يخرجوك࣌ ويمكرون ويمكر ࡲلله࣌ والله خير ࡲلمكرين࣌', NULL, 180, 'local:warsh-text.json'),
  ('warsh-8-31', 'warsh', 8, 31, '۞ وَإِذَا تُتْلٜىٰ عَلَيْهِمُۥٓ ءَايَٰتُنَا قَالُواْ قَدْ سَمِعْنَا لَوْ نَشَآءُ لَقُلْنَا مِثْلَ هَٰذَآ إِنْ هَٰذَآ إِلَّآ أَسَٰطِيرُ ࡲ۬لَاوَّلِينَ࣌', 'وإذا تتلى عليهم ءايتنا قالوا قد سمعنا لو نشاء لقلنا مثل هذا إن هذا إلا أسطير ࡲلاولين࣌', NULL, 180, 'local:warsh-text.json'),
  ('warsh-8-32', 'warsh', 8, 32, 'وَإِذْ قَالُواْ ࡲ۬للَّهُمَّ إِن كَانَ هَٰذَا هُوَ ࡰ۬لْحَقَّ مِنْ عِندِكَ فَأَمْطِرْ عَلَيْنَا حِجَارَةࣰ مِّنَ ࡰ۬لسَّمَآءِ ࡶَوِ ࡴٜيتِنَا بِعَذَابٍ ࡰلِيمࣲ࣌', 'وإذ قالوا ࡲللهم إن كان هذا هو ࡰلحق من عندك فأمطر علينا حجارة من ࡰلسماء ࡶو ࡴيتنا بعذاب ࡰليم࣌', NULL, 180, 'local:warsh-text.json'),
  ('warsh-8-33', 'warsh', 8, 33, 'وَمَا كَانَ ࡰ۬للَّهُ لِيُعَذِّبَهُمْ وَأَنتَ فِيهِمْ࣌ وَمَا كَانَ ࡰ۬للَّهُ مُعَذِّبَهُمْ وَهُمْ يَسْتَغْفِرُونَ࣌', 'وما كان ࡰلله ليعذبهم وأنت فيهم࣌ وما كان ࡰلله معذبهم وهم يستغفرون࣌', NULL, 180, 'local:warsh-text.json'),
  ('warsh-8-34', 'warsh', 8, 34, 'وَمَا لَهُمُۥٓ أَلَّا يُعَذِّبَهُمُ ࡲ۬للَّهُ وَهُمْ يَصُدُّونَ عَنِ ࡴ۬لْمَسْجِدِ ࡴ۬لْحَرَامِ وَمَا كَانُوٓاْ أَوْلِيَآءَهُۥٓ࣌ إِنَ ࡰوْلِيَآؤُهُۥٓ إِلَّا ࡰ۬لْمُتَّقُونَ࣌ وَلَٰكِنَّ أَكْثَرَهُمْ لَا يَعْلَمُونَ࣌', 'وما لهم ألا يعذبهم ࡲلله وهم يصدون عن ࡴلمسجد ࡴلحرام وما كانوا أولياءه࣌ إن ࡰولياؤه إلا ࡰلمتقون࣌ ولكن أكثرهم لا يعلمون࣌', NULL, 181, 'local:warsh-text.json'),
  ('warsh-8-35', 'warsh', 8, 35, 'وَمَا كَانَ صَلَاتُهُمْ عِندَ ࡰ۬لْبَيْتِ إِلَّا مُكَآءࣰ وَتَصْدِيَةࣰ࣌ فَذُوقُواْ ࡲ۬لْعَذَابَ بِمَا كُنتُمْ تَكْفُرُونَ࣌', 'وما كان صلاتهم عند ࡰلبيت إلا مكاء وتصدية࣌ فذوقوا ࡲلعذاب بما كنتم تكفرون࣌', NULL, 181, 'local:warsh-text.json'),
  ('warsh-8-36', 'warsh', 8, 36, 'إِنَّ ࡰ۬لذِينَ كَفَرُواْ يُنفِقُونَ أَمْوَٰلَهُمْ لِيَصُدُّواْ عَن سَبِيلِ ࡴ۬للَّهِ࣌ فَسَيُنفِقُونَهَا ثُمَّ تَكُونُ عَلَيْهِمْ حَسْرَةࣰ ثُمَّ يُغْلَبُونَ࣌ وَالذِينَ كَفَرُوٓاْ إِلَىٰ جَهَنَّمَ يُحْشَرُونَ', 'إن ࡰلذين كفروا ينفقون أمولهم ليصدوا عن سبيل ࡴلله࣌ فسينفقونها ثم تكون عليهم حسرة ثم يغلبون࣌ والذين كفروا إلى جهنم يحشرون', NULL, 181, 'local:warsh-text.json'),
  ('warsh-8-37', 'warsh', 8, 37, 'لِيَمِيزَ ࡰ۬للَّهُ ࡲ۬لْخَبِيثَ مِنَ ࡰ۬لطَّيِّبِ وَيَجْعَلَ ࡰ۬لْخَبِيثَ بَعْضَهُۥ عَلَىٰ بَعْضࣲ فَيَرْكُمَهُۥ جَمِيعاࣰ فَيَجْعَلَهُۥ فِے جَهَنَّمَ࣌ أُوْلَٰٓئِكَ هُمُ ࡲ۬لْخَٰسِرُونَ࣌', 'ليميز ࡰلله ࡲلخبيث من ࡰلطيب ويجعل ࡰلخبيث بعضه على بعض فيركمه جميعا فيجعله فے جهنم࣌ أولئك هم ࡲلخسرون࣌', NULL, 181, 'local:warsh-text.json'),
  ('warsh-8-38', 'warsh', 8, 38, 'قُل لِّلذِينَ كَفَرُوٓاْ إِنْ يَّنتَهُواْ يُغْفَرْ لَهُم مَّا قَدْ سَلَفَ࣌ وَإِنْ يَّعُودُواْ فَقَدْ مَضَتْ سُنَّتُ ࡲ۬لَاوَّلِينَ࣌', 'قل للذين كفروا إن ينتهوا يغفر لهم ما قد سلف࣌ وإن يعودوا فقد مضت سنت ࡲلاولين࣌', NULL, 181, 'local:warsh-text.json')
insert into public.ayahs (id, riwayah, surah_number, ayah_number, text, simple_text, juz, page, source) values
  ('warsh-8-39', 'warsh', 8, 39, 'وَقَٰتِلُوهُمْ حَتَّىٰ لَا تَكُونَ فِتْنَةࣱ وَيَكُونَ ࡰ۬لدِّينُ كُلُّهُۥ لِلهِ࣌ فَإِنِ ࡴٜنتَهَوْاْ فَإِنَّ ࡰ۬للَّهَ بِمَا يَعْمَلُونَ بَصِيرࣱ࣌', 'وقتلوهم حتى لا تكون فتنة ويكون ࡰلدين كله لله࣌ فإن ࡴنتهوا فإن ࡰلله بما يعملون بصير࣌', NULL, 181, 'local:warsh-text.json'),
  ('warsh-8-40', 'warsh', 8, 40, 'وَإِن تَوَلَّوْاْ فَاعْلَمُوٓاْ أَنَّ ࡰ۬للَّهَ مَوْلٜيٰكُمْ࣌ نِعْمَ ࡰ۬لْمَوْلٜىٰ࣌ وَنِعْمَ ࡰ۬لنَّصِيرُ࣌', 'وإن تولوا فاعلموا أن ࡰلله موليكم࣌ نعم ࡰلمولى࣌ ونعم ࡰلنصير࣌', NULL, 181, 'local:warsh-text.json'),
  ('warsh-8-41', 'warsh', 8, 41, '۞ وَاعْلَمُوٓاْ أَنَّمَا غَنِمْتُم مِّن شَےْءࣲ فَأَنَّ لِلهِ خُمُسَهُۥ وَلِلرَّسُولِ وَلِذِے ࡴ۬لْقُرْبٜىٰ وَالْيَتَٰمٜىٰ وَالْمَسَٰكِينِ وَابْنِ ࡴ۬لسَّبِيلِ إِن كُنتُمُۥٓ ءَامَنتُم بِاللَّهِ وَمَآ أَنزَلْنَا عَلَىٰ عَبْدِنَا يَوْمَ ࡰ۬لْفُرْقَانِ يَوْمَ ࡰٜلْتَقَى ࡰ۬لْجَمْعَٰنِ࣌ وَاللَّهُ عَلَىٰ كُلِّ شَےْءࣲ قَدِيرٌ࣌', 'واعلموا أنما غنمتم من شےء فأن لله خمسه وللرسول ولذے ࡴلقربى واليتمى والمسكين وابن ࡴلسبيل إن كنتم ءامنتم بالله وما أنزلنا على عبدنا يوم ࡰلفرقان يوم ࡰلتقى ࡰلجمعن࣌ والله على كل شےء قدير࣌', NULL, 182, 'local:warsh-text.json'),
  ('warsh-8-42', 'warsh', 8, 42, 'ࡴذَ ࡰنتُم بِالْعُدْوَةِ ࡴ۬لدُّنْيٜا وَهُم بِالْعُدْوَةِ ࡴ۬لْقُصْوٜىٰ وَالرَّكْبُ أَسْفَلَ مِنكُمْ࣌ وَلَوْ تَوَاعَدتُّمْ لَاخْتَلَفْتُمْ فِے ࡴ۬لْمِيعَٰدِ࣌ وَلَٰكِن لِّيَقْضِيَ ࡰ۬للَّهُ أَمْراࣰ كَانَ مَفْعُولاࣰ', 'ࡴذ ࡰنتم بالعدوة ࡴلدنيا وهم بالعدوة ࡴلقصوى والركب أسفل منكم࣌ ولو تواعدتم لاختلفتم فے ࡴلميعد࣌ ولكن ليقضي ࡰلله أمرا كان مفعولا', NULL, 182, 'local:warsh-text.json'),
  ('warsh-8-43', 'warsh', 8, 43, 'لِّيَهْلِكَ مَنْ هَلَكَ عَنۢ بَيِّنَةࣲ وَيَحْيٜىٰ مَنْ حَيِيَ عَنۢ بَيِّنَةࣲ࣌ وَإِنَّ ࡰ۬للَّهَ لَسَمِيعٌ عَلِيمٌ࣌', 'ليهلك من هلك عن بينة ويحيى من حيي عن بينة࣌ وإن ࡰلله لسميع عليم࣌', NULL, 182, 'local:warsh-text.json'),
  ('warsh-8-44', 'warsh', 8, 44, 'ࡴذْ يُرِيكَهُمُ ࡲ۬للَّهُ فِے مَنَامِكَ قَلِيلاࣰ࣌ وَلَوَ ࡰرٜيٰكَهُمْ كَثِيراࣰ لَّفَشِلْتُمْ وَلَتَنَٰزَعْتُمْ فِے ࡴ۬لَامْرِ࣌ وَلَٰكِنَّ ࡰ۬للَّهَ سَلَّمَ࣌ إِنَّهُۥ عَلِيمُۢ بِذَاتِ ࡴ۬لصُّدُورِ࣌', 'ࡴذ يريكهم ࡲلله فے منامك قليلا࣌ ولو ࡰريكهم كثيرا لفشلتم ولتنزعتم فے ࡴلامر࣌ ولكن ࡰلله سلم࣌ إنه عليم بذات ࡴلصدور࣌', NULL, 182, 'local:warsh-text.json'),
  ('warsh-8-45', 'warsh', 8, 45, 'وَإِذْ يُرِيكُمُوهُمُۥٓ إِذِ ࡴٜلْتَقَيْتُمْ فِےٓ أَعْيُنِكُمْ قَلِيلاࣰ وَيُقَلِّلُكُمْ فِےٓ أَعْيُنِهِمْ لِيَقْضِيَ ࡰ۬للَّهُ أَمْراࣰ كَانَ مَفْعُولاࣰ࣌ وَإِلَى ࡰ۬للَّهِ تُرْجَعُ ࡲ۬لُامُورُ࣌', 'وإذ يريكموهم إذ ࡴلتقيتم فے أعينكم قليلا ويقللكم فے أعينهم ليقضي ࡰلله أمرا كان مفعولا࣌ وإلى ࡰلله ترجع ࡲلامور࣌', NULL, 182, 'local:warsh-text.json'),
  ('warsh-8-46', 'warsh', 8, 46, 'يَٰٓأَيُّهَا ࡰ۬لذِينَ ءَامَنُوٓاْ إِذَا لَقِيتُمْ فِئَةࣰ فَاثْبُتُواْ وَاذْكُرُواْ ࡲ۬للَّهَ كَثِيراࣰ لَّعَلَّكُمْ تُفْلِحُونَ࣌', 'يأيها ࡰلذين ءامنوا إذا لقيتم فئة فاثبتوا واذكروا ࡲلله كثيرا لعلكم تفلحون࣌', NULL, 182, 'local:warsh-text.json'),
  ('warsh-8-47', 'warsh', 8, 47, 'وَأَطِيعُواْ ࡲ۬للَّهَ وَرَسُولَهُۥ࣌ وَلَا تَنَٰزَعُواْ فَتَفْشَلُواْ وَتَذْهَبَ رِيحُكُمْ࣌ وَاصْبِرُوٓاْ࣌ إِنَّ ࡰ۬للَّهَ مَعَ ࡰ۬لصَّٰبِرِينَ࣌', 'وأطيعوا ࡲلله ورسوله࣌ ولا تنزعوا فتفشلوا وتذهب ريحكم࣌ واصبروا࣌ إن ࡰلله مع ࡰلصبرين࣌', NULL, 183, 'local:warsh-text.json'),
  ('warsh-8-48', 'warsh', 8, 48, 'وَلَا تَكُونُواْ كَالذِينَ خَرَجُواْ مِن دِيٜـٰرِهِم بَطَراࣰ وَرِئَآءَ ࡰ۬لنَّاسِ وَيَصُدُّونَ عَن سَبِيلِ ࡴ۬للَّهِ࣌ وَاللَّهُ بِمَا يَعْمَلُونَ مُحِيطࣱ࣌', 'ولا تكونوا كالذين خرجوا من ديرهم بطرا ورئاء ࡰلناس ويصدون عن سبيل ࡴلله࣌ والله بما يعملون محيط࣌', NULL, 183, 'local:warsh-text.json'),
  ('warsh-8-49', 'warsh', 8, 49, '۞ وَإِذْ زَيَّنَ لَهُمُ ࡲ۬لشَّيْطَٰنُ أَعْمَٰلَهُمْ وَقَالَ لَا غَالِبَ لَكُمُ ࡲ۬لْيَوْمَ مِنَ ࡰ۬لنَّاسِ وَإِنِّے جَارࣱ لَّكُمْ࣌ فَلَمَّا تَرَآءَتِ ࡴ۬لْفِئَتَٰنِ نَكَصَ عَلَىٰ عَقِبَيْهِ وَقَالَ إِنِّے بَرِےٓءࣱ مِّنكُمُۥٓ إِنِّيَ أَرٜىٰ مَا لَا تَرَوْنَ إِنِّيَ أَخَافُ ࡲ۬للَّهَ࣌ وَاللَّهُ شَدِيدُ ࡲ۬لْعِقَابِ࣌', 'وإذ زين لهم ࡲلشيطن أعملهم وقال لا غالب لكم ࡲليوم من ࡰلناس وإنے جار لكم࣌ فلما تراءت ࡴلفئتن نكص على عقبيه وقال إنے برےء منكم إني أرى ما لا ترون إني أخاف ࡲلله࣌ والله شديد ࡲلعقاب࣌', NULL, 183, 'local:warsh-text.json'),
  ('warsh-8-50', 'warsh', 8, 50, 'إِذْ يَقُولُ ࡲ۬لْمُنَٰفِقُونَ وَالذِينَ فِے قُلُوبِهِم مَّرَضٌ غَرَّ هَٰٓؤُلَآءِ دِينُهُمْ࣌ وَمَنْ يَّتَوَكَّلْ عَلَى ࡰ۬للَّهِ فَإِنَّ ࡰ۬للَّهَ عَزِيزٌ حَكِيمࣱ࣌', 'إذ يقول ࡲلمنفقون والذين فے قلوبهم مرض غر هؤلاء دينهم࣌ ومن يتوكل على ࡰلله فإن ࡰلله عزيز حكيم࣌', NULL, 183, 'local:warsh-text.json'),
  ('warsh-8-51', 'warsh', 8, 51, 'وَلَوْ تَرٜىٰٓ إِذْ يَتَوَفَّى ࡰ۬لذِينَ كَفَرُواْ࣌ ࡲ۬لْمَلَٰٓئِكَةُ يَضْرِبُونَ وُجُوهَهُمْ وَأَدْبَٰرَهُمْ وَذُوقُواْ عَذَابَ ࡰ۬لْحَرِيقِ࣌', 'ولو ترى إذ يتوفى ࡰلذين كفروا࣌ ࡲلملئكة يضربون وجوههم وأدبرهم وذوقوا عذاب ࡰلحريق࣌', NULL, 183, 'local:warsh-text.json'),
  ('warsh-8-52', 'warsh', 8, 52, 'ذَٰلِكَ بِمَا قَدَّمَتَ ࡰيْدِيكُمْ وَأَنَّ ࡰ۬للَّهَ لَيْسَ بِظَلَّٰمࣲ لِّلْعَبِيدِ࣌', 'ذلك بما قدمت ࡰيديكم وأن ࡰلله ليس بظلم للعبيد࣌', NULL, 183, 'local:warsh-text.json'),
  ('warsh-8-53', 'warsh', 8, 53, 'كَدَأْبِ ءَالِ فِرْعَوْنَ࣌ وَالذِينَ مِن قَبْلِهِمْ كَفَرُواْ بِـَٔايَٰتِ ࡴ۬للَّهِ فَأَخَذَهُمُ ࡲ۬للَّهُ بِذُنُوبِهِمُۥٓ࣌ إِنَّ ࡰ۬للَّهَ قَوِيࣱّ شَدِيدُ ࡲ۬لْعِقَابِ࣌', 'كدأب ءال فرعون࣌ والذين من قبلهم كفروا بايت ࡴلله فأخذهم ࡲلله بذنوبهم࣌ إن ࡰلله قوي شديد ࡲلعقاب࣌', NULL, 183, 'local:warsh-text.json'),
  ('warsh-8-54', 'warsh', 8, 54, 'ذَٰلِكَ بِأَنَّ ࡰ۬للَّهَ لَمْ يَكُ مُغَيِّراࣰ نِّعْمَةً ࡰنْعَمَهَا عَلَىٰ قَوْمٍ حَتَّىٰ يُغَيِّرُواْ مَا بِأَنفُسِهِمْ وَأَنَّ ࡰ۬للَّهَ سَمِيعٌ عَلِيمࣱ࣌', 'ذلك بأن ࡰلله لم يك مغيرا نعمة ࡰنعمها على قوم حتى يغيروا ما بأنفسهم وأن ࡰلله سميع عليم࣌', NULL, 184, 'local:warsh-text.json'),
  ('warsh-8-55', 'warsh', 8, 55, 'كَدَأْبِ ءَالِ فِرْعَوْنَ࣌ وَالذِينَ مِن قَبْلِهِمْ كَذَّبُواْ بِـَٔايَٰتِ رَبِّهِمْ فَأَهْلَكْنَٰهُم بِذُنُوبِهِمْ࣌ وَأَغْرَقْنَآ ءَالَ فِرْعَوْنَ࣌ وَكُلࣱّ كَانُواْ ظَٰلِمِينَ࣌', 'كدأب ءال فرعون࣌ والذين من قبلهم كذبوا بايت ربهم فأهلكنهم بذنوبهم࣌ وأغرقنا ءال فرعون࣌ وكل كانوا ظلمين࣌', NULL, 184, 'local:warsh-text.json'),
  ('warsh-8-56', 'warsh', 8, 56, 'إِنَّ شَرَّ ࡰ۬لدَّوَآبِّ عِندَ ࡰ۬للَّهِ ࡴ۬لذِينَ كَفَرُواْ فَهُمْ لَا يُومِنُونَ', 'إن شر ࡰلدواب عند ࡰلله ࡴلذين كفروا فهم لا يومنون', NULL, 184, 'local:warsh-text.json'),
  ('warsh-8-57', 'warsh', 8, 57, 'ࡰ۬لذِينَ عَٰهَدتَّ مِنْهُمْ ثُمَّ يَنقُضُونَ عَهْدَهُمْ فِے كُلِّ مَرَّةࣲ وَهُمْ لَا يَتَّقُونَ࣌', 'ࡰلذين عهدت منهم ثم ينقضون عهدهم فے كل مرة وهم لا يتقون࣌', NULL, 184, 'local:warsh-text.json'),
  ('warsh-8-58', 'warsh', 8, 58, 'فَإِمَّا تَثْقَفَنَّهُمْ فِے ࡴ۬لْحَرْبِ فَشَرِّدْ بِهِم مَّنْ خَلْفَهُمْ لَعَلَّهُمْ يَذَّكَّرُونَ࣌', 'فإما تثقفنهم فے ࡴلحرب فشرد بهم من خلفهم لعلهم يذكرون࣌', NULL, 184, 'local:warsh-text.json'),
  ('warsh-8-59', 'warsh', 8, 59, 'وَإِمَّا تَخَافَنَّ مِن قَوْمٍ خِيَانَةࣰ فَانۢبِذِ ࡴلَيْهِمْ عَلَىٰ سَوَآءٍ࣌ ࡴنَّ ࡰ۬للَّهَ لَا يُحِبُّ ࡲ۬لْخَآئِنِينَ࣌', 'وإما تخافن من قوم خيانة فانبذ ࡴليهم على سواء࣌ ࡴن ࡰلله لا يحب ࡲلخائنين࣌', NULL, 184, 'local:warsh-text.json'),
  ('warsh-8-60', 'warsh', 8, 60, 'وَلَا تَحْسِبَنَّ ࡰ۬لذِينَ كَفَرُواْ سَبَقُوٓاْ࣌ إِنَّهُمْ لَا يُعْجِزُونَ࣌', 'ولا تحسبن ࡰلذين كفروا سبقوا࣌ إنهم لا يعجزون࣌', NULL, 184, 'local:warsh-text.json'),
  ('warsh-8-61', 'warsh', 8, 61, '۞ وَأَعِدُّواْ لَهُم مَّا ࡰٜسْتَطَعْتُم مِّن قُوَّةࣲ وَمِن رِّبَاطِ ࡴ۬لْخَيْلِ࣌ تُرْهِبُونَ بِهِۦ عَدُوَّ ࡰ۬للَّهِ وَعَدُوَّكُمْ وَءَاخَرِينَ مِن دُونِهِمْ لَا تَعْلَمُونَهُمُ࣌ ࡲ۬للَّهُ يَعْلَمُهُمْ࣌ وَمَا تُنفِقُواْ مِن شَےْءࣲ فِے سَبِيلِ ࡴ۬للَّهِ يُوَفَّ إِلَيْكُمْ وَأَنتُمْ لَا تُظْلَمُونَ࣌', 'وأعدوا لهم ما ࡰستطعتم من قوة ومن رباط ࡴلخيل࣌ ترهبون به عدو ࡰلله وعدوكم وءاخرين من دونهم لا تعلمونهم࣌ ࡲلله يعلمهم࣌ وما تنفقوا من شےء فے سبيل ࡴلله يوف إليكم وأنتم لا تظلمون࣌', NULL, 184, 'local:warsh-text.json'),
  ('warsh-8-62', 'warsh', 8, 62, 'وَإِن جَنَحُواْ لِلسَّلْمِ فَاجْنَحْ لَهَا وَتَوَكَّلْ عَلَى ࡰ۬للَّهِ࣌ إِنَّهُۥ هُوَ ࡰ۬لسَّمِيعُ ࡲ۬لْعَلِيمُ࣌', 'وإن جنحوا للسلم فاجنح لها وتوكل على ࡰلله࣌ إنه هو ࡰلسميع ࡲلعليم࣌', NULL, 184, 'local:warsh-text.json'),
  ('warsh-8-63', 'warsh', 8, 63, 'وَإِنْ يُّرِيدُوٓاْ أَنْ يَّخْدَعُوكَ فَإِنَّ حَسْبَكَ ࡰ۬للَّهُ࣌ هُوَ ࡰ۬لذِےٓ أَيَّدَكَ بِنَصْرِهِۦ وَبِالْمُومِنِينَ', 'وإن يريدوا أن يخدعوك فإن حسبك ࡰلله࣌ هو ࡰلذے أيدك بنصره وبالمومنين', NULL, 185, 'local:warsh-text.json'),
  ('warsh-8-64', 'warsh', 8, 64, 'وَأَلَّفَ بَيْنَ قُلُوبِهِمْ࣌ لَوَ ࡰنفَقْتَ مَا فِے ࡴ۬لَارْضِ جَمِيعاࣰ مَّآ أَلَّفْتَ بَيْنَ قُلُوبِهِمْ࣌ وَلَٰكِنَّ ࡰ۬للَّهَ أَلَّفَ بَيْنَهُمُۥٓ࣌ إِنَّهُۥ عَزِيزٌ حَكِيمࣱ࣌', 'وألف بين قلوبهم࣌ لو ࡰنفقت ما فے ࡴلارض جميعا ما ألفت بين قلوبهم࣌ ولكن ࡰلله ألف بينهم࣌ إنه عزيز حكيم࣌', NULL, 185, 'local:warsh-text.json'),
  ('warsh-8-65', 'warsh', 8, 65, 'يَٰٓأَيُّهَا‏ ࡰ۬لنَّبِےٓءُ حَسْبُكَ ࡰ۬للَّهُ࣌ وَمَنِ ࡴٜتَّبَعَكَ مِنَ ࡰ۬لْمُومِنِينَ࣌', 'يأيها‏ ࡰلنبےء حسبك ࡰلله࣌ ومن ࡴتبعك من ࡰلمومنين࣌', NULL, 185, 'local:warsh-text.json'),
  ('warsh-8-66', 'warsh', 8, 66, 'يَٰٓأَيُّهَا‏ ࡰ۬لنَّبِےٓءُ حَرِّضِ ࡴ۬لْمُومِنِينَ عَلَى ࡰ۬لْقِتَالِ࣌ إِنْ يَّكُن مِّنكُمْ عِشْرُونَ صَٰبِرُونَ يَغْلِبُواْ مِاْئَتَيْنِ࣌ وَإِن تَكُن مِّنكُم مِّاْئَةࣱ يَغْلِبُوٓاْ أَلْفاࣰ مِّنَ ࡰ۬لذِينَ كَفَرُواْ بِأَنَّهُمْ قَوْمࣱ لَّا يَفْقَهُونَ࣌', 'يأيها‏ ࡰلنبےء حرض ࡴلمومنين على ࡰلقتال࣌ إن يكن منكم عشرون صبرون يغلبوا مائتين࣌ وإن تكن منكم مائة يغلبوا ألفا من ࡰلذين كفروا بأنهم قوم لا يفقهون࣌', NULL, 185, 'local:warsh-text.json'),
  ('warsh-8-67', 'warsh', 8, 67, 'ࡰ۬لَٰنَ خَفَّفَ ࡰ۬للَّهُ عَنكُمْ وَعَلِمَ أَنَّ فِيكُمْ ضُعْفاࣰ࣌ فَإِن تَكُن مِّنكُم مِّاْئَةࣱ صَابِرَةࣱ يَغْلِبُواْ مِاْئَتَيْنِ࣌ وَإِنْ يَّكُن مِّنكُمُۥٓ أَلْفࣱ يَغْلِبُوٓاْ أَلْفَيْنِ بِإِذْنِ ࡴ۬للَّهِ࣌ وَاللَّهُ مَعَ ࡰ۬لصَّٰبِرِينَ࣌', 'ࡰلن خفف ࡰلله عنكم وعلم أن فيكم ضعفا࣌ فإن تكن منكم مائة صابرة يغلبوا مائتين࣌ وإن يكن منكم ألف يغلبوا ألفين بإذن ࡴلله࣌ والله مع ࡰلصبرين࣌', NULL, 185, 'local:warsh-text.json'),
  ('warsh-8-68', 'warsh', 8, 68, 'مَا كَانَ لِنَبِےٓءٍ ࡰنْ يَّكُونَ لَهُۥٓ أَسْرٜىٰ حَتَّىٰ يُثْخِنَ فِے ࡴ۬لَارْضِ࣌ تُرِيدُونَ عَرَضَ ࡰ۬لدُّنْيٜا࣌ وَاللَّهُ يُرِيدُ ࡲ۬لَاخِرَةَ࣌ وَاللَّهُ عَزِيزٌ حَكِيمࣱ࣌', 'ما كان لنبےء ࡰن يكون له أسرى حتى يثخن فے ࡴلارض࣌ تريدون عرض ࡰلدنيا࣌ والله يريد ࡲلاخرة࣌ والله عزيز حكيم࣌', NULL, 185, 'local:warsh-text.json'),
  ('warsh-8-69', 'warsh', 8, 69, 'لَّوْلَا كِتَٰبࣱ مِّنَ ࡰ۬للَّهِ سَبَقَ لَمَسَّكُمْ فِيمَآ أَخَذتُّمْ عَذَابٌ عَظِيمࣱ࣌', 'لولا كتب من ࡰلله سبق لمسكم فيما أخذتم عذاب عظيم࣌', NULL, 185, 'local:warsh-text.json'),
  ('warsh-8-70', 'warsh', 8, 70, 'فَكُلُواْ مِمَّا غَنِمْتُمْ حَلَٰلاࣰ طَيِّباࣰ࣌ وَاتَّقُواْ ࡲ۬للَّهَ࣌ إِنَّ ࡰ۬للَّهَ غَفُورࣱ رَّحِيمࣱ࣌', 'فكلوا مما غنمتم حللا طيبا࣌ واتقوا ࡲلله࣌ إن ࡰلله غفور رحيم࣌', NULL, 185, 'local:warsh-text.json'),
  ('warsh-8-71', 'warsh', 8, 71, 'يَٰٓأَيُّهَا‏ ࡰ۬لنَّبِےٓءُ قُل لِّمَن فِےٓ أَيْدِيكُم مِّنَ ࡰ۬لَاسْرٜىٰٓ إِنْ يَّعْلَمِ ࡴ۬للَّهُ فِے قُلُوبِكُمْ خَيْراࣰ يُوتِكُمْ خَيْراࣰ مِّمَّآ أُخِذَ مِنكُمْ وَيَغْفِرْ لَكُمْ࣌ وَاللَّهُ غَفُورࣱ رَّحِيمࣱ࣌', 'يأيها‏ ࡰلنبےء قل لمن فے أيديكم من ࡰلاسرى إن يعلم ࡴلله فے قلوبكم خيرا يوتكم خيرا مما أخذ منكم ويغفر لكم࣌ والله غفور رحيم࣌', NULL, 186, 'local:warsh-text.json'),
  ('warsh-8-72', 'warsh', 8, 72, '۞ وَإِنْ يُّرِيدُواْ خِيَانَتَكَ فَقَدْ خَانُواْ ࡲ۬للَّهَ مِن قَبْلُ فَأَمْكَنَ مِنْهُمْ࣌ وَاللَّهُ عَلِيمٌ حَكِيمٌ࣌', 'وإن يريدوا خيانتك فقد خانوا ࡲلله من قبل فأمكن منهم࣌ والله عليم حكيم࣌', NULL, 186, 'local:warsh-text.json'),
  ('warsh-8-73', 'warsh', 8, 73, 'ࡴنَّ ࡰ۬لذِينَ ءَامَنُواْ وَهَاجَرُواْ وَجَٰهَدُواْ بِأَمْوَٰلِهِمْ وَأَنفُسِهِمْ فِے سَبِيلِ ࡴ۬للَّهِ وَالذِينَ ءَاوَواْ وَّنَصَرُوٓاْ أُوْلَٰٓئِكَ بَعْضُهُمُۥٓ أَوْلِيَآءُ بَعْضࣲ࣌ وَالذِينَ ءَامَنُواْ وَلَمْ يُهَاجِرُواْ مَا لَكُم مِّنْ وَّلَٰيَتِهِم مِّن شَےْءٍ حَتَّىٰ يُهَاجِرُواْ࣌ وَإِنِ ࡴٜسْتَنصَرُوكُمْ فِے ࡴ۬لدِّينِ فَعَلَيْكُمُ ࡲ۬لنَّصْرُ إِلَّا عَلَىٰ قَوْمِۢ بَيْنَكُمْ وَبَيْنَهُم مِّيثَٰقࣱ࣌ وَاللَّهُ بِمَا تَعْمَلُونَ بَصِيرࣱ࣌', 'ࡴن ࡰلذين ءامنوا وهاجروا وجهدوا بأمولهم وأنفسهم فے سبيل ࡴلله والذين ءاووا ونصروا أولئك بعضهم أولياء بعض࣌ والذين ءامنوا ولم يهاجروا ما لكم من وليتهم من شےء حتى يهاجروا࣌ وإن ࡴستنصروكم فے ࡴلدين فعليكم ࡲلنصر إلا على قوم بينكم وبينهم ميثق࣌ والله بما تعملون بصير࣌', NULL, 186, 'local:warsh-text.json'),
  ('warsh-8-74', 'warsh', 8, 74, 'وَالذِينَ كَفَرُواْ بَعْضُهُمُۥٓ أَوْلِيَآءُ بَعْضٍ࣌ ࡴلَّا تَفْعَلُوهُ تَكُن فِتْنَةࣱ فِے ࡴ۬لَارْضِ وَفَسَادࣱ كَبِيرࣱ࣌', 'والذين كفروا بعضهم أولياء بعض࣌ ࡴلا تفعلوه تكن فتنة فے ࡴلارض وفساد كبير࣌', NULL, 186, 'local:warsh-text.json'),
  ('warsh-8-75', 'warsh', 8, 75, 'وَالذِينَ ءَامَنُواْ وَهَاجَرُواْ وَجَٰهَدُواْ فِے سَبِيلِ ࡴ۬للَّهِ وَالذِينَ ءَاوَواْ وَّنَصَرُوٓاْ أُوْلَٰٓئِكَ هُمُ ࡲ۬لْمُومِنُونَ حَقّاࣰ࣌ لَّهُم مَّغْفِرَةࣱ وَرِزْقࣱ كَرِيمࣱ࣌', 'والذين ءامنوا وهاجروا وجهدوا فے سبيل ࡴلله والذين ءاووا ونصروا أولئك هم ࡲلمومنون حقا࣌ لهم مغفرة ورزق كريم࣌', NULL, 186, 'local:warsh-text.json'),
  ('warsh-8-76', 'warsh', 8, 76, 'وَالذِينَ ءَامَنُواْ مِنۢ بَعْدُ وَهَاجَرُواْ وَجَٰهَدُواْ مَعَكُمْ فَأُوْلَٰٓئِكَ مِنكُمْ࣌ وَأُوْلُواْ ࡲ۬لَارْحَامِ بَعْضُهُمُۥٓ أَوْلٜىٰ بِبَعْضࣲ فِے كِتَٰبِ ࡴ۬للَّهِ࣌ إِنَّ ࡰ۬للَّهَ بِكُلِّ شَےْءٍ عَلِيمُۢ࣌', 'والذين ءامنوا من بعد وهاجروا وجهدوا معكم فأولئك منكم࣌ وأولوا ࡲلارحام بعضهم أولى ببعض فے كتب ࡴلله࣌ إن ࡰلله بكل شےء عليم࣌', NULL, 186, 'local:warsh-text.json'),
  ('warsh-9-1', 'warsh', 9, 1, 'بَرَآءَةࣱ مِّنَ ࡰ۬للَّهِ وَرَسُولِهِۦٓ إِلَى ࡰ۬لذِينَ عَٰهَدتُّم مِّنَ ࡰ۬لْمُشْرِكِينَ࣌', 'براءة من ࡰلله ورسوله إلى ࡰلذين عهدتم من ࡰلمشركين࣌', NULL, 187, 'local:warsh-text.json'),
  ('warsh-9-2', 'warsh', 9, 2, 'فَسِيحُواْ فِے ࡴ۬لَارْضِ أَرْبَعَةَ أَشْهُرࣲ࣌ وَاعْلَمُوٓاْ أَنَّكُمْ غَيْرُ مُعْجِزِے ࡴ۬للَّهِ وَأَنَّ ࡰ۬للَّهَ مُخْزِے ࡴ۬لْكٜـٰفِرِينَ࣌', 'فسيحوا فے ࡴلارض أربعة أشهر࣌ واعلموا أنكم غير معجزے ࡴلله وأن ࡰلله مخزے ࡴلكفرين࣌', NULL, 187, 'local:warsh-text.json'),
  ('warsh-9-3', 'warsh', 9, 3, 'وَأَذَٰنࣱ مِّنَ ࡰ۬للَّهِ وَرَسُولِهِۦٓ إِلَى ࡰ۬لنَّاسِ يَوْمَ ࡰ۬لْحَجِّ ࡴ۬لَاكْبَرِ أَنَّ ࡰ۬للَّهَ بَرِےٓءࣱ مِّنَ ࡰ۬لْمُشْرِكِينَ وَرَسُولُهُۥ࣌ فَإِن تُبْتُمْ فَهُوَ خَيْرࣱ لَّكُمْ࣌ وَإِن تَوَلَّيْتُمْ فَاعْلَمُوٓاْ أَنَّكُمْ غَيْرُ مُعْجِزِے ࡴ۬للَّهِ࣌ وَبَشِّرِ ࡴ۬لذِينَ كَفَرُواْ بِعَذَابٍ ࡰلِيمٍ', 'وأذن من ࡰلله ورسوله إلى ࡰلناس يوم ࡰلحج ࡴلاكبر أن ࡰلله برےء من ࡰلمشركين ورسوله࣌ فإن تبتم فهو خير لكم࣌ وإن توليتم فاعلموا أنكم غير معجزے ࡴلله࣌ وبشر ࡴلذين كفروا بعذاب ࡰليم', NULL, 187, 'local:warsh-text.json'),
  ('warsh-9-4', 'warsh', 9, 4, 'ࡴلَّا ࡰ۬لذِينَ عَٰهَدتُّم مِّنَ ࡰ۬لْمُشْرِكِينَ ثُمَّ لَمْ يَنقُصُوكُمْ شَيْـٔاࣰ وَلَمْ يُظَٰهِرُواْ عَلَيْكُمُۥٓ أَحَداࣰ فَأَتِمُّوٓاْ إِلَيْهِمْ عَهْدَهُمُۥٓ إِلَىٰ مُدَّتِهِمُۥٓ࣌ إِنَّ ࡰ۬للَّهَ يُحِبُّ ࡲ۬لْمُتَّقِينَ࣌', 'ࡴلا ࡰلذين عهدتم من ࡰلمشركين ثم لم ينقصوكم شيا ولم يظهروا عليكم أحدا فأتموا إليهم عهدهم إلى مدتهم࣌ إن ࡰلله يحب ࡲلمتقين࣌', NULL, 187, 'local:warsh-text.json'),
  ('warsh-9-5', 'warsh', 9, 5, '۞ فَإِذَا ࡰٜنسَلَخَ ࡰ۬لَاشْهُرُ ࡲ۬لْحُرُمُ فَاقْتُلُواْ ࡲ۬لْمُشْرِكِينَ حَيْثُ وَجَدتُّمُوهُمْ وَخُذُوهُمْ وَاحْصُرُوهُمْ وَاقْعُدُواْ لَهُمْ كُلَّ مَرْصَدࣲ࣌ فَإِن تَابُواْ وَأَقَامُواْ ࡲ۬لصَّلَوٰةَ وَءَاتَوُاْ ࡲ۬لزَّكَوٰةَ فَخَلُّواْ سَبِيلَهُمُۥٓ࣌ إِنَّ ࡰ۬للَّهَ غَفُورࣱ رَّحِيمࣱ࣌', 'فإذا ࡰنسلخ ࡰلاشهر ࡲلحرم فاقتلوا ࡲلمشركين حيث وجدتموهم وخذوهم واحصروهم واقعدوا لهم كل مرصد࣌ فإن تابوا وأقاموا ࡲلصلوة وءاتوا ࡲلزكوة فخلوا سبيلهم࣌ إن ࡰلله غفور رحيم࣌', NULL, 187, 'local:warsh-text.json'),
  ('warsh-9-6', 'warsh', 9, 6, 'وَإِنَ ࡰحَدࣱ مِّنَ ࡰ۬لْمُشْرِكِينَ ࡰٜسْتَجَارَكَ فَأَجِرْهُ حَتَّىٰ يَسْمَعَ كَلَٰمَ ࡰ۬للَّهِ ثُمَّ أَبْلِغْهُ مَامَنَهُۥ࣌ ذَٰلِكَ بِأَنَّهُمْ قَوْمࣱ لَّا يَعْلَمُونَ࣌', 'وإن ࡰحد من ࡰلمشركين ࡰستجارك فأجره حتى يسمع كلم ࡰلله ثم أبلغه مامنه࣌ ذلك بأنهم قوم لا يعلمون࣌', NULL, 187, 'local:warsh-text.json'),
  ('warsh-9-7', 'warsh', 9, 7, 'كَيْفَ يَكُونُ لِلْمُشْرِكِينَ عَهْدٌ عِندَ ࡰ۬للَّهِ وَعِندَ رَسُولِهِۦٓ إِلَّا ࡰ۬لذِينَ عَٰهَدتُّمْ عِندَ ࡰ۬لْمَسْجِدِ ࡴ۬لْحَرَامِ فَمَا ࡰٜسْتَقَٰمُواْ لَكُمْ فَاسْتَقِيمُواْ لَهُمُۥٓ࣌ إِنَّ ࡰ۬للَّهَ يُحِبُّ ࡲ۬لْمُتَّقِينَ࣌', 'كيف يكون للمشركين عهد عند ࡰلله وعند رسوله إلا ࡰلذين عهدتم عند ࡰلمسجد ࡴلحرام فما ࡰستقموا لكم فاستقيموا لهم࣌ إن ࡰلله يحب ࡲلمتقين࣌', NULL, 188, 'local:warsh-text.json'),
  ('warsh-9-8', 'warsh', 9, 8, 'كَيْفَ وَإِنْ يَّظْهَرُواْ عَلَيْكُمْ لَا يَرْقُبُواْ فِيكُمُۥٓ إِلّاࣰ وَلَا ذِمَّةࣰ࣌ يُرْضُونَكُم بِأَفْوَٰهِهِمْ وَتَابٜىٰ قُلُوبُهُمْ وَأَكْثَرُهُمْ فَٰسِقُونَ࣌', 'كيف وإن يظهروا عليكم لا يرقبوا فيكم إلا ولا ذمة࣌ يرضونكم بأفوههم وتابى قلوبهم وأكثرهم فسقون࣌', NULL, 188, 'local:warsh-text.json'),
  ('warsh-9-9', 'warsh', 9, 9, 'ࡰٜشْتَرَوْاْ بِـَٔايَٰتِ ࡴ۬للَّهِ ثَمَناࣰ قَلِيلاࣰ فَصَدُّواْ عَن سَبِيلِهِۦٓ࣌ إِنَّهُمْ سَآءَ مَا كَانُواْ يَعْمَلُونَ࣌', 'ࡰشتروا بايت ࡴلله ثمنا قليلا فصدوا عن سبيله࣌ إنهم ساء ما كانوا يعملون࣌', NULL, 188, 'local:warsh-text.json'),
  ('warsh-9-10', 'warsh', 9, 10, 'لَا يَرْقُبُونَ فِے مُومِنٍ ࡴلّاࣰ وَلَا ذِمَّةࣰ࣌ وَأُوْلَٰٓئِكَ هُمُ ࡲ۬لْمُعْتَدُونَ࣌', 'لا يرقبون فے مومن ࡴلا ولا ذمة࣌ وأولئك هم ࡲلمعتدون࣌', NULL, 188, 'local:warsh-text.json'),
  ('warsh-9-11', 'warsh', 9, 11, 'فَإِن تَابُواْ وَأَقَامُواْ ࡲ۬لصَّلَوٰةَ وَءَاتَوُاْ ࡲ۬لزَّكَوٰةَ فَإِخْوَٰنُكُمْ فِے ࡴ۬لدِّينِ࣌ وَنُفَصِّلُ ࡲ۬لَايَٰتِ لِقَوْمࣲ يَعْلَمُونَ࣌', 'فإن تابوا وأقاموا ࡲلصلوة وءاتوا ࡲلزكوة فإخونكم فے ࡴلدين࣌ ونفصل ࡲلايت لقوم يعلمون࣌', NULL, 188, 'local:warsh-text.json'),
  ('warsh-9-12', 'warsh', 9, 12, '۞ وَإِن نَّكَثُوٓاْ أَيْمَٰنَهُم مِّنۢ بَعْدِ عَهْدِهِمْ وَطَعَنُواْ فِے دِينِكُمْ فَقَٰتِلُوٓاْ أَيٜمَّةَ ࡰ۬لْكُفْرِ࣌ إِنَّهُمْ لَآ أَيْمَٰنَ لَهُمْ لَعَلَّهُمْ يَنتَهُونَ࣌', 'وإن نكثوا أيمنهم من بعد عهدهم وطعنوا فے دينكم فقتلوا أيمة ࡰلكفر࣌ إنهم لا أيمن لهم لعلهم ينتهون࣌', NULL, 188, 'local:warsh-text.json'),
  ('warsh-9-13', 'warsh', 9, 13, 'أَلَا تُقَٰتِلُونَ قَوْماࣰ نَّكَثُوٓاْ أَيْمَٰنَهُمْ وَهَمُّواْ بِإِخْرَاجِ ࡴ۬لرَّسُولِ وَهُم بَدَءُوكُمُۥٓ أَوَّلَ مَرَّةٍ ࡰتَخْشَوْنَهُمْ࣌ فَاللَّهُ أَحَقُّ أَن تَخْشَوْهُ إِن كُنتُم مُّومِنِينَ࣌', 'ألا تقتلون قوما نكثوا أيمنهم وهموا بإخراج ࡴلرسول وهم بدءوكم أول مرة ࡰتخشونهم࣌ فالله أحق أن تخشوه إن كنتم مومنين࣌', NULL, 188, 'local:warsh-text.json'),
  ('warsh-9-14', 'warsh', 9, 14, 'قَٰتِلُوهُمْ يُعَذِّبْهُمُ ࡲ۬للَّهُ بِأَيْدِيكُمْ وَيُخْزِهِمْ وَيَنصُرْكُمْ عَلَيْهِمْ وَيَشْفِ صُدُورَ قَوْمࣲ مُّومِنِينَ', 'قتلوهم يعذبهم ࡲلله بأيديكم ويخزهم وينصركم عليهم ويشف صدور قوم مومنين', NULL, 189, 'local:warsh-text.json'),
  ('warsh-9-15', 'warsh', 9, 15, 'وَيُذْهِبْ غَيْظَ قُلُوبِهِمْ࣌ وَيَتُوبُ ࡲ۬للَّهُ عَلَىٰ مَنْ يَّشَآءُ࣌ وَاللَّهُ عَلِيمٌ حَكِيمٌ࣌', 'ويذهب غيظ قلوبهم࣌ ويتوب ࡲلله على من يشاء࣌ والله عليم حكيم࣌', NULL, 189, 'local:warsh-text.json'),
  ('warsh-9-16', 'warsh', 9, 16, 'ࡰمْ حَسِبْتُمُۥٓ أَن تُتْرَكُواْ وَلَمَّا يَعْلَمِ ࡴ۬للَّهُ ࡲ۬لذِينَ جَٰهَدُواْ مِنكُمْ وَلَمْ يَتَّخِذُواْ مِن دُونِ ࡴ۬للَّهِ وَلَا رَسُولِهِۦ وَلَا ࡰ۬لْمُومِنِينَ وَلِيجَةࣰ࣌ وَاللَّهُ خَبِيرُۢ بِمَا تَعْمَلُونَ࣌', 'ࡰم حسبتم أن تتركوا ولما يعلم ࡴلله ࡲلذين جهدوا منكم ولم يتخذوا من دون ࡴلله ولا رسوله ولا ࡰلمومنين وليجة࣌ والله خبير بما تعملون࣌', NULL, 189, 'local:warsh-text.json'),
  ('warsh-9-17', 'warsh', 9, 17, 'مَا كَانَ لِلْمُشْرِكِينَ أَنْ يَّعْمُرُواْ مَسَٰجِدَ ࡰ۬للَّهِ شَٰهِدِينَ عَلَىٰٓ أَنفُسِهِم بِالْكُفْرِ࣌ أُوْلَٰٓئِكَ حَبِطَتَ ࡰعْمَٰلُهُمْ وَفِے ࡴ۬لنّٜارِ هُمْ خَٰلِدُونَ࣌', 'ما كان للمشركين أن يعمروا مسجد ࡰلله شهدين على أنفسهم بالكفر࣌ أولئك حبطت ࡰعملهم وفے ࡴلنار هم خلدون࣌', NULL, 189, 'local:warsh-text.json'),
  ('warsh-9-18', 'warsh', 9, 18, 'إِنَّمَا يَعْمُرُ مَسَٰجِدَ ࡰ۬للَّهِ مَنَ اٰمَنَ بِاللَّهِ وَالْيَوْمِ ࡴ۬لَاخِرِ وَأَقَامَ ࡰ۬لصَّلَوٰةَ وَءَاتَى ࡰ۬لزَّكَوٰةَ وَلَمْ يَخْشَ إِلَّا ࡰ۬للَّهَ فَعَسٜىٰٓ أُوْلَٰٓئِكَ أَنْ يَّكُونُواْ مِنَ ࡰ۬لْمُهْتَدِينَ࣌', 'إنما يعمر مسجد ࡰلله من امن بالله واليوم ࡴلاخر وأقام ࡰلصلوة وءاتى ࡰلزكوة ولم يخش إلا ࡰلله فعسى أولئك أن يكونوا من ࡰلمهتدين࣌', NULL, 189, 'local:warsh-text.json'),
  ('warsh-9-19', 'warsh', 9, 19, '۞ أَجَعَلْتُمْ سِقَايَةَ ࡰ۬لْحَآجِّ وَعِمَارَةَ ࡰ۬لْمَسْجِدِ ࡴ۬لْحَرَامِ كَمَنَ اٰمَنَ بِاللَّهِ وَالْيَوْمِ ࡴ۬لَاخِرِ وَجَٰهَدَ فِے سَبِيلِ ࡴ۬للَّهِ࣌ لَا يَسْتَوُۥنَ عِندَ ࡰ۬للَّهِ࣌ وَاللَّهُ لَا يَهْدِے ࡴ۬لْقَوْمَ ࡰ۬لظَّٰلِمِينَ࣌', 'أجعلتم سقاية ࡰلحاج وعمارة ࡰلمسجد ࡴلحرام كمن امن بالله واليوم ࡴلاخر وجهد فے سبيل ࡴلله࣌ لا يستون عند ࡰلله࣌ والله لا يهدے ࡴلقوم ࡰلظلمين࣌', NULL, 189, 'local:warsh-text.json'),
  ('warsh-9-20', 'warsh', 9, 20, 'ࡰ۬لذِينَ ءَامَنُواْ وَهَاجَرُواْ وَجَٰهَدُواْ فِے سَبِيلِ ࡴ۬للَّهِ بِأَمْوَٰلِهِمْ وَأَنفُسِهِمُۥٓ أَعْظَمُ دَرَجَةً عِندَ ࡰ۬للَّهِ࣌ وَأُوْلَٰٓئِكَ هُمُ ࡲ۬لْفَآئِزُونَ࣌', 'ࡰلذين ءامنوا وهاجروا وجهدوا فے سبيل ࡴلله بأمولهم وأنفسهم أعظم درجة عند ࡰلله࣌ وأولئك هم ࡲلفائزون࣌', NULL, 189, 'local:warsh-text.json'),
  ('warsh-9-21', 'warsh', 9, 21, 'يُبَشِّرُهُمْ رَبُّهُم بِرَحْمَةࣲ مِّنْهُ وَرِضْوَٰنࣲ وَجَنَّٰتࣲ لَّهُمْ فِيهَا نَعِيمࣱ مُّقِيمٌ', 'يبشرهم ربهم برحمة منه ورضون وجنت لهم فيها نعيم مقيم', NULL, 190, 'local:warsh-text.json'),
  ('warsh-9-22', 'warsh', 9, 22, 'خَٰلِدِينَ فِيهَآ أَبَداً࣌ ࡴنَّ ࡰ۬للَّهَ عِندَهُۥٓ أَجْرٌ عَظِيمࣱ࣌', 'خلدين فيها أبدا࣌ ࡴن ࡰلله عنده أجر عظيم࣌', NULL, 190, 'local:warsh-text.json'),
  ('warsh-9-23', 'warsh', 9, 23, 'يَٰٓأَيُّهَا ࡰ۬لذِينَ ءَامَنُواْ لَا تَتَّخِذُوٓاْ ءَابَآءَكُمْ وَإِخْوَٰنَكُمُۥٓ أَوْلِيَآءَ ࡹنِ ࡴٜسْتَحَبُّواْ ࡲ۬لْكُفْرَ عَلَى ࡰ۬لِايمَٰنِ࣌ وَمَنْ يَّتَوَلَّهُم مِّنكُمْ فَأُوْلَٰٓئِكَ هُمُ ࡲ۬لظَّٰلِمُونَ࣌', 'يأيها ࡰلذين ءامنوا لا تتخذوا ءاباءكم وإخونكم أولياء ࡹن ࡴستحبوا ࡲلكفر على ࡰلايمن࣌ ومن يتولهم منكم فأولئك هم ࡲلظلمون࣌', NULL, 190, 'local:warsh-text.json'),
  ('warsh-9-24', 'warsh', 9, 24, 'قُلِ ࡴن كَانَ ءَابَآؤُكُمْ وَأَبْنَآؤُكُمْ وَإِخْوَٰنُكُمْ وَأَزْوَٰجُكُمْ وَعَشِيرَتُكُمْ وَأَمْوَٰلٌ ࡴٜقْتَرَفْتُمُوهَا وَتِجَٰرَةࣱ تَخْشَوْنَ كَسَادَهَا وَمَسَٰكِنُ تَرْضَوْنَهَآ أَحَبَّ إِلَيْكُم مِّنَ ࡰ۬للَّهِ وَرَسُولِهِۦ وَجِهَادࣲ فِے سَبِيلِهِۦ فَتَرَبَّصُواْ حَتَّىٰ يَاتِيَ ࡰ۬للَّهُ بِأَمْرِهِۦ࣌ وَاللَّهُ لَا يَهْدِے ࡴ۬لْقَوْمَ ࡰ۬لْفَٰسِقِينَ࣌', 'قل ࡴن كان ءاباؤكم وأبناؤكم وإخونكم وأزوجكم وعشيرتكم وأمول ࡴقترفتموها وتجرة تخشون كسادها ومسكن ترضونها أحب إليكم من ࡰلله ورسوله وجهاد فے سبيله فتربصوا حتى ياتي ࡰلله بأمره࣌ والله لا يهدے ࡴلقوم ࡰلفسقين࣌', NULL, 190, 'local:warsh-text.json'),
  ('warsh-9-25', 'warsh', 9, 25, 'لَقَدْ نَصَرَكُمُ ࡲ۬للَّهُ فِے مَوَاطِنَ كَثِيرَةࣲ وَيَوْمَ حُنَيْنٍ ࡴذَ ࡰعْجَبَتْكُمْ كَثْرَتُكُمْ فَلَمْ تُغْنِ عَنكُمْ شَيْـٔاࣰ وَضَاقَتْ عَلَيْكُمُ ࡲ۬لَارْضُ بِمَا رَحُبَتْ ثُمَّ وَلَّيْتُم مُّدْبِرِينَ࣌', 'لقد نصركم ࡲلله فے مواطن كثيرة ويوم حنين ࡴذ ࡰعجبتكم كثرتكم فلم تغن عنكم شيا وضاقت عليكم ࡲلارض بما رحبت ثم وليتم مدبرين࣌', NULL, 190, 'local:warsh-text.json'),
  ('warsh-9-26', 'warsh', 9, 26, 'ثُمَّ أَنزَلَ ࡰ۬للَّهُ سَكِينَتَهُۥ عَلَىٰ رَسُولِهِۦ وَعَلَى ࡰ۬لْمُومِنِينَ وَأَنزَلَ جُنُوداࣰ لَّمْ تَرَوْهَا وَعَذَّبَ ࡰ۬لذِينَ كَفَرُواْ࣌ وَذَٰلِكَ جَزَآءُ ࡲ۬لْكٜـٰفِرِينَ࣌', 'ثم أنزل ࡰلله سكينته على رسوله وعلى ࡰلمومنين وأنزل جنودا لم تروها وعذب ࡰلذين كفروا࣌ وذلك جزاء ࡲلكفرين࣌', NULL, 190, 'local:warsh-text.json'),
  ('warsh-9-27', 'warsh', 9, 27, 'ثُمَّ يَتُوبُ ࡲ۬للَّهُ مِنۢ بَعْدِ ذَٰلِكَ عَلَىٰ مَنْ يَّشَآءُ࣌ وَاللَّهُ غَفُورࣱ رَّحِيمࣱ࣌', 'ثم يتوب ࡲلله من بعد ذلك على من يشاء࣌ والله غفور رحيم࣌', NULL, 191, 'local:warsh-text.json'),
  ('warsh-9-28', 'warsh', 9, 28, '۞ يَٰٓأَيُّهَا ࡰ۬لذِينَ ءَامَنُوٓاْ إِنَّمَا ࡰ۬لْمُشْرِكُونَ نَجَسࣱ فَلَا يَقْرَبُواْ ࡲ۬لْمَسْجِدَ ࡰ۬لْحَرَامَ بَعْدَ عَامِهِمْ هَٰذَا࣌ وَإِنْ خِفْتُمْ عَيْلَةࣰ فَسَوْفَ يُغْنِيكُمُ ࡲ۬للَّهُ مِن فَضْلِهِۦٓ إِن شَآءَ࣌ ࡹنَّ ࡰ۬للَّهَ عَلِيمٌ حَكِيمࣱ࣌', 'يأيها ࡰلذين ءامنوا إنما ࡰلمشركون نجس فلا يقربوا ࡲلمسجد ࡰلحرام بعد عامهم هذا࣌ وإن خفتم عيلة فسوف يغنيكم ࡲلله من فضله إن شاء࣌ ࡹن ࡰلله عليم حكيم࣌', NULL, 191, 'local:warsh-text.json'),
  ('warsh-9-29', 'warsh', 9, 29, 'قَٰتِلُواْ ࡲ۬لذِينَ لَا يُومِنُونَ بِاللَّهِ وَلَا بِالْيَوْمِ ࡴ۬لَاخِرِ وَلَا يُحَرِّمُونَ مَا حَرَّمَ ࡰ۬للَّهُ وَرَسُولُهُۥ وَلَا يَدِينُونَ دِينَ ࡰ۬لْحَقِّ مِنَ ࡰ۬لذِينَ أُوتُواْ ࡲ۬لْكِتَٰبَ حَتَّىٰ يُعْطُواْ ࡲ۬لْجِزْيَةَ عَنْ يَّدࣲ وَهُمْ صَٰغِرُونَ࣌', 'قتلوا ࡲلذين لا يومنون بالله ولا باليوم ࡴلاخر ولا يحرمون ما حرم ࡰلله ورسوله ولا يدينون دين ࡰلحق من ࡰلذين أوتوا ࡲلكتب حتى يعطوا ࡲلجزية عن يد وهم صغرون࣌', NULL, 191, 'local:warsh-text.json'),
  ('warsh-9-30', 'warsh', 9, 30, 'وَقَالَتِ ࡴ۬لْيَهُودُ عُزَيْرُ ࡲٜبْنُ ࡲ۬للَّهِ࣌ وَقَالَتِ ࡴ۬لنَّصَٰرَى ࡰ۬لْمَسِيحُ ࡲٜبْنُ ࡲ۬للَّهِ࣌ ذَٰلِكَ قَوْلُهُم بِأَفْوَٰهِهِمْ يُضَٰهُونَ قَوْلَ ࡰ۬لذِينَ كَفَرُواْ مِن قَبْلُ࣌ قَٰتَلَهُمُ ࡲ۬للَّهُ࣌ أَنّٜىٰ يُوفَكُونَ࣌', 'وقالت ࡴليهود عزير ࡲبن ࡲلله࣌ وقالت ࡴلنصرى ࡰلمسيح ࡲبن ࡲلله࣌ ذلك قولهم بأفوههم يضهون قول ࡰلذين كفروا من قبل࣌ قتلهم ࡲلله࣌ أنى يوفكون࣌', NULL, 191, 'local:warsh-text.json'),
  ('warsh-9-31', 'warsh', 9, 31, 'ࡰٜتَّخَذُوٓاْ أَحْبَارَهُمْ وَرُهْبَٰنَهُمُۥٓ أَرْبَاباࣰ مِّن دُونِ ࡴ۬للَّهِ وَالْمَسِيحَ ࡰٜبْنَ مَرْيَمَ࣌ وَمَآ أُمِرُوٓاْ إِلَّا لِيَعْبُدُوٓاْ إِلَٰهاࣰ وَٰحِداࣰ࣌ لَّآ إِلَٰهَ إِلَّا هُوَ࣌ سُبْحَٰنَهُۥ عَمَّا يُشْرِكُونَ࣌', 'ࡰتخذوا أحبارهم ورهبنهم أربابا من دون ࡴلله والمسيح ࡰبن مريم࣌ وما أمروا إلا ليعبدوا إلها وحدا࣌ لا إله إلا هو࣌ سبحنه عما يشركون࣌', NULL, 191, 'local:warsh-text.json'),
  ('warsh-9-32', 'warsh', 9, 32, 'يُرِيدُونَ أَنْ يُّطْفِـُٔواْ نُورَ ࡰ۬للَّهِ بِأَفْوَٰهِهِمْ وَيَابَى ࡰ۬للَّهُ إِلَّآ أَنْ يُّتِمَّ نُورَهُۥ وَلَوْ كَرِهَ ࡰ۬لْكَٰفِرُونَ࣌', 'يريدون أن يطفوا نور ࡰلله بأفوههم ويابى ࡰلله إلا أن يتم نوره ولو كره ࡰلكفرون࣌', NULL, 192, 'local:warsh-text.json'),
  ('warsh-9-33', 'warsh', 9, 33, 'هُوَ ࡰ۬لذِےٓ أَرْسَلَ رَسُولَهُۥ بِالْهُدٜىٰ وَدِينِ ࡴ۬لْحَقِّ لِيُظْهِرَهُۥ عَلَى ࡰ۬لدِّينِ كُلِّهِۦ وَلَوْ كَرِهَ ࡰ۬لْمُشْرِكُونَ࣌', 'هو ࡰلذے أرسل رسوله بالهدى ودين ࡴلحق ليظهره على ࡰلدين كله ولو كره ࡰلمشركون࣌', NULL, 192, 'local:warsh-text.json'),
  ('warsh-9-34', 'warsh', 9, 34, '۞ يَٰٓأَيُّهَا ࡰ۬لذِينَ ءَامَنُوٓاْ إِنَّ كَثِيراࣰ مِّنَ ࡰ۬لَاحْبٜارِ وَالرُّهْبَانِ لَيَاكُلُونَ أَمْوَٰلَ ࡰ۬لنَّاسِ بِالْبَٰطِلِ وَيَصُدُّونَ عَن سَبِيلِ ࡴ۬للَّهِ࣌ وَالذِينَ يَكْنِزُونَ ࡰ۬لذَّهَبَ وَالْفِضَّةَ وَلَا يُنفِقُونَهَا فِے سَبِيلِ ࡴ۬للَّهِ فَبَشِّرْهُم بِعَذَابٍ ࡰلِيمࣲ࣌', 'يأيها ࡰلذين ءامنوا إن كثيرا من ࡰلاحبار والرهبان لياكلون أمول ࡰلناس بالبطل ويصدون عن سبيل ࡴلله࣌ والذين يكنزون ࡰلذهب والفضة ولا ينفقونها فے سبيل ࡴلله فبشرهم بعذاب ࡰليم࣌', NULL, 192, 'local:warsh-text.json'),
  ('warsh-9-35', 'warsh', 9, 35, 'يَوْمَ يُحْمٜىٰ عَلَيْهَا فِے نٜارِ جَهَنَّمَ فَتُكْوٜىٰ بِهَا جِبَاهُهُمْ وَجُنُوبُهُمْ وَظُهُورُهُمْ هَٰذَا مَا كَنَزْتُمْ لِأَنفُسِكُمْ فَذُوقُواْ مَا كُنتُمْ تَكْنِزُونَ࣌', 'يوم يحمى عليها فے نار جهنم فتكوى بها جباههم وجنوبهم وظهورهم هذا ما كنزتم لأنفسكم فذوقوا ما كنتم تكنزون࣌', NULL, 192, 'local:warsh-text.json'),
  ('warsh-9-36', 'warsh', 9, 36, 'إِنَّ عِدَّةَ ࡰ۬لشُّهُورِ عِندَ ࡰ۬للَّهِ ࡴٜثْنَا عَشَرَ شَهْراࣰ فِے كِتَٰبِ ࡴ۬للَّهِ يَوْمَ خَلَقَ ࡰ۬لسَّمَٰوَٰتِ وَالَارْضَ࣌ مِنْهَآ أَرْبَعَةٌ حُرُمࣱ࣌ ذَٰلِكَ ࡰ۬لدِّينُ ࡲ۬لْقَيِّمُ࣌ فَلَا تَظْلِمُواْ فِيهِنَّ أَنفُسَكُمْ࣌ وَقَٰتِلُواْ ࡲ۬لْمُشْرِكِينَ كَآفَّةࣰ كَمَا يُقَٰتِلُونَكُمْ كَآفَّةࣰ࣌ وَاعْلَمُوٓاْ أَنَّ ࡰ۬للَّهَ مَعَ ࡰ۬لْمُتَّقِينَ࣌', 'إن عدة ࡰلشهور عند ࡰلله ࡴثنا عشر شهرا فے كتب ࡴلله يوم خلق ࡰلسموت والارض࣌ منها أربعة حرم࣌ ذلك ࡰلدين ࡲلقيم࣌ فلا تظلموا فيهن أنفسكم࣌ وقتلوا ࡲلمشركين كافة كما يقتلونكم كافة࣌ واعلموا أن ࡰلله مع ࡰلمتقين࣌', NULL, 192, 'local:warsh-text.json'),
  ('warsh-9-37', 'warsh', 9, 37, 'إِنَّمَا ࡰ۬لنَّسِيُّ زِيَادَةࣱ فِے ࡴ۬لْكُفْرِ يَضِلُّ بِهِ ࡴ۬لذِينَ كَفَرُواْ يُحِلُّونَهُۥ عَاماࣰ وَيُحَرِّمُونَهُۥ عَاماࣰ لِّيُوَاطِـُٔواْ عِدَّةَ مَا حَرَّمَ ࡰ۬للَّهُ فَيُحِلُّواْ مَا حَرَّمَ ࡰ۬للَّهُ࣌ زُيِّنَ لَهُمْ سُوٓءُ ࡶَعْمَٰلِهِمْ࣌ وَاللَّهُ لَا يَهْدِے ࡴ۬لْقَوْمَ ࡰ۬لْكٜـٰفِرِينَ࣌', 'إنما ࡰلنسي زيادة فے ࡴلكفر يضل به ࡴلذين كفروا يحلونه عاما ويحرمونه عاما ليواطوا عدة ما حرم ࡰلله فيحلوا ما حرم ࡰلله࣌ زين لهم سوء ࡶعملهم࣌ والله لا يهدے ࡴلقوم ࡰلكفرين࣌', NULL, 193, 'local:warsh-text.json'),
  ('warsh-9-38', 'warsh', 9, 38, 'يَٰٓأَيُّهَا ࡰ۬لذِينَ ءَامَنُواْ مَا لَكُمُۥٓ إِذَا قِيلَ لَكُمُ ࡲٜنفِرُواْ فِے سَبِيلِ ࡴ۬للَّهِ ࡴٜثَّاقَلْتُمُۥٓ إِلَى ࡰ۬لَارْضِ࣌ أَرَضِيتُم بِالْحَيَوٰةِ ࡴ۬لدُّنْيٜا مِنَ ࡰ۬لَاخِرَةِ࣌ فَمَا مَتَٰعُ ࡲ۬لْحَيَوٰةِ ࡴ۬لدُّنْيٜا فِے ࡴ۬لَاخِرَةِ إِلَّا قَلِيلٌ࣌', 'يأيها ࡰلذين ءامنوا ما لكم إذا قيل لكم ࡲنفروا فے سبيل ࡴلله ࡴثاقلتم إلى ࡰلارض࣌ أرضيتم بالحيوة ࡴلدنيا من ࡰلاخرة࣌ فما متع ࡲلحيوة ࡴلدنيا فے ࡴلاخرة إلا قليل࣌', NULL, 193, 'local:warsh-text.json'),
  ('warsh-9-39', 'warsh', 9, 39, 'ࡴلَّا تَنفِرُواْ يُعَذِّبْكُمْ عَذَاباً ࡰلِيماࣰ وَيَسْتَبْدِلْ قَوْماً غَيْرَكُمْ وَلَا تَضُرُّوهُ شَيْـٔاࣰ࣌ وَاللَّهُ عَلَىٰ كُلِّ شَےْءࣲ قَدِيرٌ࣌', 'ࡴلا تنفروا يعذبكم عذابا ࡰليما ويستبدل قوما غيركم ولا تضروه شيا࣌ والله على كل شےء قدير࣌', NULL, 193, 'local:warsh-text.json'),
  ('warsh-9-40', 'warsh', 9, 40, '۞ ࡴلَّا تَنصُرُوهُ فَقَدْ نَصَرَهُ ࡲ۬للَّهُ إِذَ ࡰخْرَجَهُ ࡲ۬لذِينَ كَفَرُواْ ثَانِيَ ࡰٜثْنَيْنِ إِذْ هُمَا فِے ࡴ۬لْغٜارِ إِذْ يَقُولُ لِصَٰحِبِهِۦ لَا تَحْزَنِ ࡴنَّ ࡰ۬للَّهَ مَعَنَا࣌ فَأَنزَلَ ࡰ۬للَّهُ سَكِينَتَهُۥ عَلَيْهِ࣌ وَأَيَّدَهُۥ بِجُنُودࣲ لَّمْ تَرَوْهَا࣌ وَجَعَلَ كَلِمَةَ ࡰ۬لذِينَ كَفَرُواْ ࡲ۬لسُّفْلٜىٰ࣌ وَكَلِمَةُ ࡲ۬للَّهِ هِيَ ࡰ۬لْعُلْيٜا࣌ وَاللَّهُ عَزِيزٌ حَكِيمٌ࣌', 'ࡴلا تنصروه فقد نصره ࡲلله إذ ࡰخرجه ࡲلذين كفروا ثاني ࡰثنين إذ هما فے ࡴلغار إذ يقول لصحبه لا تحزن ࡴن ࡰلله معنا࣌ فأنزل ࡰلله سكينته عليه࣌ وأيده بجنود لم تروها࣌ وجعل كلمة ࡰلذين كفروا ࡲلسفلى࣌ وكلمة ࡲلله هي ࡰلعليا࣌ والله عزيز حكيم࣌', NULL, 193, 'local:warsh-text.json'),
  ('warsh-9-41', 'warsh', 9, 41, 'ࡴٜنفِرُواْ خِفَافاࣰ وَثِقَالاࣰ وَجَٰهِدُواْ بِأَمْوَٰلِكُمْ وَأَنفُسِكُمْ فِے سَبِيلِ ࡴ۬للَّهِ࣌ ذَٰلِكُمْ خَيْرࣱ لَّكُمُۥٓ إِن كُنتُمْ تَعْلَمُونَ࣌', 'ࡴنفروا خفافا وثقالا وجهدوا بأمولكم وأنفسكم فے سبيل ࡴلله࣌ ذلكم خير لكم إن كنتم تعلمون࣌', NULL, 194, 'local:warsh-text.json'),
  ('warsh-9-42', 'warsh', 9, 42, 'لَوْ كَانَ عَرَضاࣰ قَرِيباࣰ وَسَفَراࣰ قَاصِداࣰ لَّاتَّبَعُوكَ وَلَٰكِنۢ بَعُدَتْ عَلَيْهِمُ ࡲ۬لشُّقَّةُ࣌ وَسَيَحْلِفُونَ بِاللَّهِ لَوِ ࡴٜسْتَطَعْنَا لَخَرَجْنَا مَعَكُمْ࣌ يُهْلِكُونَ أَنفُسَهُمْ࣌ وَاللَّهُ يَعْلَمُ إِنَّهُمْ لَكَٰذِبُونَ࣌', 'لو كان عرضا قريبا وسفرا قاصدا لاتبعوك ولكن بعدت عليهم ࡲلشقة࣌ وسيحلفون بالله لو ࡴستطعنا لخرجنا معكم࣌ يهلكون أنفسهم࣌ والله يعلم إنهم لكذبون࣌', NULL, 194, 'local:warsh-text.json'),
  ('warsh-9-43', 'warsh', 9, 43, 'عَفَا ࡰ۬للَّهُ عَنكَ لِمَ أَذِنتَ لَهُمْ حَتَّىٰ يَتَبَيَّنَ لَكَ ࡰ۬لذِينَ صَدَقُواْ وَتَعْلَمَ ࡰ۬لْكَٰذِبِينَ࣌', 'عفا ࡰلله عنك لم أذنت لهم حتى يتبين لك ࡰلذين صدقوا وتعلم ࡰلكذبين࣌', NULL, 194, 'local:warsh-text.json'),
  ('warsh-9-44', 'warsh', 9, 44, 'لَا يَسْتَٰذِنُكَ ࡰ۬لذِينَ يُومِنُونَ بِاللَّهِ وَالْيَوْمِ ࡴ۬لَاخِرِ أَنْ يُّجَٰهِدُواْ بِأَمْوَٰلِهِمْ وَأَنفُسِهِمْ࣌ وَاللَّهُ عَلِيمُۢ بِالْمُتَّقِينَ࣌', 'لا يستذنك ࡰلذين يومنون بالله واليوم ࡴلاخر أن يجهدوا بأمولهم وأنفسهم࣌ والله عليم بالمتقين࣌', NULL, 194, 'local:warsh-text.json'),
  ('warsh-9-45', 'warsh', 9, 45, 'إِنَّمَا يَسْتَٰذِنُكَ ࡰ۬لذِينَ لَا يُومِنُونَ بِاللَّهِ وَالْيَوْمِ ࡴ۬لَاخِرِ وَارْتَابَتْ قُلُوبُهُمْ فَهُمْ فِے رَيْبِهِمْ يَتَرَدَّدُونَ࣌', 'إنما يستذنك ࡰلذين لا يومنون بالله واليوم ࡴلاخر وارتابت قلوبهم فهم فے ريبهم يترددون࣌', NULL, 194, 'local:warsh-text.json'),
  ('warsh-9-46', 'warsh', 9, 46, '۞ وَلَوَ ࡰرَادُواْ ࡲ۬لْخُرُوجَ لَأَعَدُّواْ لَهُۥ عُدَّةࣰ࣌ وَلَٰكِن كَرِهَ ࡰ۬للَّهُ ࡲٜنۢبِعَاثَهُمْ فَثَبَّطَهُمْ وَقِيلَ ࡸَقْعُدُواْ مَعَ ࡰ۬لْقَٰعِدِينَ࣌', 'ولو ࡰرادوا ࡲلخروج لأعدوا له عدة࣌ ولكن كره ࡰلله ࡲنبعاثهم فثبطهم وقيل ࡸقعدوا مع ࡰلقعدين࣌', NULL, 194, 'local:warsh-text.json'),
  ('warsh-9-47', 'warsh', 9, 47, 'لَوْ خَرَجُواْ فِيكُم مَّا زَادُوكُمُۥٓ إِلَّا خَبَالاࣰ وَلَأَوْضَعُواْ خِلَٰلَكُمْ يَبْغُونَكُمُ ࡲ۬لْفِتْنَةَ وَفِيكُمْ سَمَّٰعُونَ لَهُمْ࣌ وَاللَّهُ عَلِيمُۢ بِالظَّٰلِمِينَ࣌', 'لو خرجوا فيكم ما زادوكم إلا خبالا ولأوضعوا خللكم يبغونكم ࡲلفتنة وفيكم سمعون لهم࣌ والله عليم بالظلمين࣌', NULL, 194, 'local:warsh-text.json'),
  ('warsh-9-48', 'warsh', 9, 48, 'لَقَدِ ࡴٜبْتَغَوُاْ ࡲ۬لْفِتْنَةَ مِن قَبْلُ وَقَلَّبُواْ لَكَ ࡰ۬لُامُورَ حَتَّىٰ جَآءَ ࡰ۬لْحَقُّ وَظَهَرَ أَمْرُ ࡲ۬للَّهِ وَهُمْ كَٰرِهُونَ࣌', 'لقد ࡴبتغوا ࡲلفتنة من قبل وقلبوا لك ࡰلامور حتى جاء ࡰلحق وظهر أمر ࡲلله وهم كرهون࣌', NULL, 195, 'local:warsh-text.json'),
  ('warsh-9-49', 'warsh', 9, 49, 'وَمِنْهُم مَّنْ يَّقُولُ ࡲٜيذَن لِّے وَلَا تَفْتِنِّےٓ࣌ أَلَا فِے ࡴ۬لْفِتْنَةِ سَقَطُواْ࣌ وَإِنَّ جَهَنَّمَ لَمُحِيطَةُۢ بِالْكٜـٰفِرِينَ࣌', 'ومنهم من يقول ࡲيذن لے ولا تفتنے࣌ ألا فے ࡴلفتنة سقطوا࣌ وإن جهنم لمحيطة بالكفرين࣌', NULL, 195, 'local:warsh-text.json'),
  ('warsh-9-50', 'warsh', 9, 50, 'إِن تُصِبْكَ حَسَنَةࣱ تَسُؤْهُمْ࣌ وَإِن تُصِبْكَ مُصِيبَةࣱ يَقُولُواْ قَدَ ࡰخَذْنَآ أَمْرَنَا مِن قَبْلُ وَيَتَوَلَّواْ وَّهُمْ فَرِحُونَ࣌', 'إن تصبك حسنة تسؤهم࣌ وإن تصبك مصيبة يقولوا قد ࡰخذنا أمرنا من قبل ويتولوا وهم فرحون࣌', NULL, 195, 'local:warsh-text.json'),
  ('warsh-9-51', 'warsh', 9, 51, 'قُل لَّنْ يُّصِيبَنَآ إِلَّا مَا كَتَبَ ࡰ۬للَّهُ لَنَا࣌ هُوَ مَوْلٜيٰنَا࣌ وَعَلَى ࡰ۬للَّهِ فَلْيَتَوَكَّلِ ࡴ۬لْمُومِنُونَ࣌', 'قل لن يصيبنا إلا ما كتب ࡰلله لنا࣌ هو مولينا࣌ وعلى ࡰلله فليتوكل ࡴلمومنون࣌', NULL, 195, 'local:warsh-text.json'),
  ('warsh-9-52', 'warsh', 9, 52, 'قُلْ هَلْ تَرَبَّصُونَ بِنَآ إِلَّآ إِحْدَى ࡰ۬لْحُسْنَيَيْنِ࣌ وَنَحْنُ نَتَرَبَّصُ بِكُمُۥٓ أَنْ يُّصِيبَكُمُ ࡲ۬للَّهُ بِعَذَابࣲ مِّنْ عِندِهِۦٓ أَوْ بِأَيْدِينَا࣌ فَتَرَبَّصُوٓاْ࣌ إِنَّا مَعَكُم مُّتَرَبِّصُونَ࣌', 'قل هل تربصون بنا إلا إحدى ࡰلحسنيين࣌ ونحن نتربص بكم أن يصيبكم ࡲلله بعذاب من عنده أو بأيدينا࣌ فتربصوا࣌ إنا معكم متربصون࣌', NULL, 195, 'local:warsh-text.json'),
  ('warsh-9-53', 'warsh', 9, 53, 'قُلَ ࡰنفِقُواْ طَوْعاً ࡰوْ كَرْهاࣰ لَّنْ يُّتَقَبَّلَ مِنكُمُۥٓ࣌ إِنَّكُمْ كُنتُمْ قَوْماࣰ فَٰسِقِينَ࣌', 'قل ࡰنفقوا طوعا ࡰو كرها لن يتقبل منكم࣌ إنكم كنتم قوما فسقين࣌', NULL, 195, 'local:warsh-text.json'),
  ('warsh-9-54', 'warsh', 9, 54, 'وَمَا مَنَعَهُمُۥٓ أَن تُقْبَلَ مِنْهُمْ نَفَقَٰتُهُمُۥٓ إِلَّآ أَنَّهُمْ كَفَرُواْ بِاللَّهِ وَبِرَسُولِهِۦ وَلَا يَاتُونَ ࡰ۬لصَّلَوٰةَ إِلَّا وَهُمْ كُسَالٜىٰ وَلَا يُنفِقُونَ إِلَّا وَهُمْ كَٰرِهُونَ࣌', 'وما منعهم أن تقبل منهم نفقتهم إلا أنهم كفروا بالله وبرسوله ولا ياتون ࡰلصلوة إلا وهم كسالى ولا ينفقون إلا وهم كرهون࣌', NULL, 195, 'local:warsh-text.json'),
  ('warsh-9-55', 'warsh', 9, 55, '۞ فَلَا تُعْجِبْكَ أَمْوَٰلُهُمْ وَلَآ أَوْلَٰدُهُمُۥٓ࣌ إِنَّمَا يُرِيدُ ࡲ۬للَّهُ لِيُعَذِّبَهُم بِهَا فِے ࡴ۬لْحَيَوٰةِ ࡴ۬لدُّنْيٜا وَتَزْهَقَ أَنفُسُهُمْ وَهُمْ كَٰفِرُونَ࣌', 'فلا تعجبك أمولهم ولا أولدهم࣌ إنما يريد ࡲلله ليعذبهم بها فے ࡴلحيوة ࡴلدنيا وتزهق أنفسهم وهم كفرون࣌', NULL, 196, 'local:warsh-text.json'),
  ('warsh-9-56', 'warsh', 9, 56, 'وَيَحْلِفُونَ بِاللَّهِ إِنَّهُمْ لَمِنكُمْ وَمَا هُم مِّنكُمْ وَلَٰكِنَّهُمْ قَوْمࣱ يَفْرَقُونَ࣌', 'ويحلفون بالله إنهم لمنكم وما هم منكم ولكنهم قوم يفرقون࣌', NULL, 196, 'local:warsh-text.json'),
  ('warsh-9-57', 'warsh', 9, 57, 'لَوْ يَجِدُونَ مَلْجَـٔاً ࡰوْ مَغَٰرَٰتٍ ࡰوْ مُدَّخَلاࣰ لَّوَلَّوِاْ ࡴلَيْهِ وَهُمْ يَجْمَحُونَ࣌', 'لو يجدون ملجا ࡰو مغرت ࡰو مدخلا لولوا ࡴليه وهم يجمحون࣌', NULL, 196, 'local:warsh-text.json'),
  ('warsh-9-58', 'warsh', 9, 58, 'وَمِنْهُم مَّنْ يَّلْمِزُكَ فِے ࡴ۬لصَّدَقَٰتِ فَإِنُ ࡳعْطُواْ مِنْهَا رَضُواْ وَإِن لَّمْ يُعْطَوْاْ مِنْهَآ إِذَا هُمْ يَسْخَطُونَ࣌', 'ومنهم من يلمزك فے ࡴلصدقت فإن ࡳعطوا منها رضوا وإن لم يعطوا منها إذا هم يسخطون࣌', NULL, 196, 'local:warsh-text.json'),
  ('warsh-9-59', 'warsh', 9, 59, 'وَلَوَ ࡰنَّهُمْ رَضُواْ مَآ ءَاتٜيٰهُمُ ࡲ۬للَّهُ وَرَسُولُهُۥ وَقَالُواْ حَسْبُنَا ࡰ۬للَّهُ سَيُوتِينَا ࡰ۬للَّهُ مِن فَضْلِهِۦ وَرَسُولُهُۥٓ࣌ إِنَّآ إِلَى ࡰ۬للَّهِ رَٰغِبُونَ࣌', 'ولو ࡰنهم رضوا ما ءاتيهم ࡲلله ورسوله وقالوا حسبنا ࡰلله سيوتينا ࡰلله من فضله ورسوله࣌ إنا إلى ࡰلله رغبون࣌', NULL, 196, 'local:warsh-text.json'),
  ('warsh-9-60', 'warsh', 9, 60, 'إِنَّمَا ࡰ۬لصَّدَقَٰتُ لِلْفُقَرَآءِ وَالْمَسَٰكِينِ وَالْعَٰمِلِينَ عَلَيْهَا وَالْمُوَ۬لَّفَةِ قُلُوبُهُمْ وَفِے ࡴ۬لرِّقَابِ وَالْغَٰرِمِينَ وَفِے سَبِيلِ ࡴ۬للَّهِ وَابْنِ ࡴ۬لسَّبِيلِ فَرِيضَةࣰ مِّنَ ࡰ۬للَّهِ࣌ وَاللَّهُ عَلِيمٌ حَكِيمࣱ࣌', 'إنما ࡰلصدقت للفقراء والمسكين والعملين عليها والمولفة قلوبهم وفے ࡴلرقاب والغرمين وفے سبيل ࡴلله وابن ࡴلسبيل فريضة من ࡰلله࣌ والله عليم حكيم࣌', NULL, 196, 'local:warsh-text.json'),
  ('warsh-9-61', 'warsh', 9, 61, '۞ وَمِنْهُمُ ࡲ۬لذِينَ يُوذُونَ ࡰ۬لنَّبِےٓءَ وَيَقُولُونَ هُوَ أُذْنࣱ࣌ قُلُ ࡳذْنُ خَيْرࣲ لَّكُمْ يُومِنُ بِاللَّهِ وَيُومِنُ لِلْمُومِنِينَ وَرَحْمَةࣱ لِّلذِينَ ءَامَنُواْ مِنكُمْ࣌ وَالذِينَ يُوذُونَ رَسُولَ ࡰ۬للَّهِ لَهُمْ عَذَابٌ ࡰلِيمࣱ࣌', 'ومنهم ࡲلذين يوذون ࡰلنبےء ويقولون هو أذن࣌ قل ࡳذن خير لكم يومن بالله ويومن للمومنين ورحمة للذين ءامنوا منكم࣌ والذين يوذون رسول ࡰلله لهم عذاب ࡰليم࣌', NULL, 196, 'local:warsh-text.json'),
  ('warsh-9-62', 'warsh', 9, 62, 'يَحْلِفُونَ بِاللَّهِ لَكُمْ لِيُرْضُوكُمْ وَاللَّهُ وَرَسُولُهُۥٓ أَحَقُّ أَنْ يُّرْضُوهُ إِن كَانُواْ مُومِنِينَ࣌', 'يحلفون بالله لكم ليرضوكم والله ورسوله أحق أن يرضوه إن كانوا مومنين࣌', NULL, 197, 'local:warsh-text.json'),
  ('warsh-9-63', 'warsh', 9, 63, 'أَلَمْ يَعْلَمُوٓاْ أَنَّهُۥ مَنْ يُّحَادِدِ ࡴ۬للَّهَ وَرَسُولَهُۥ فَأَنَّ لَهُۥ نَارَ جَهَنَّمَ خَٰلِداࣰ فِيهَا࣌ ذَٰلِكَ ࡰ۬لْخِزْيُ ࡲ۬لْعَظِيمُ࣌', 'ألم يعلموا أنه من يحادد ࡴلله ورسوله فأن له نار جهنم خلدا فيها࣌ ذلك ࡰلخزي ࡲلعظيم࣌', NULL, 197, 'local:warsh-text.json'),
  ('warsh-9-64', 'warsh', 9, 64, 'يَحْذَرُ ࡲ۬لْمُنَٰفِقُونَ أَن تُنَزَّلَ عَلَيْهِمْ سُورَةࣱ تُنَبِّئُهُم بِمَا فِے قُلُوبِهِمْ࣌ قُلِ ࡴٜسْتَهْزِءُوٓاْ࣌ إِنَّ ࡰ۬للَّهَ مُخْرِجࣱ مَّا تَحْذَرُونَ࣌', 'يحذر ࡲلمنفقون أن تنزل عليهم سورة تنبئهم بما فے قلوبهم࣌ قل ࡴستهزءوا࣌ إن ࡰلله مخرج ما تحذرون࣌', NULL, 197, 'local:warsh-text.json'),
  ('warsh-9-65', 'warsh', 9, 65, 'وَلَئِن سَأَلْتَهُمْ لَيَقُولُنَّ إِنَّمَا كُنَّا نَخُوضُ وَنَلْعَبُ࣌ قُلَ ࡰبِاللَّهِ وَءَايَٰتِهِۦ وَرَسُولِهِۦ كُنتُمْ تَسْتَهْزِءُونَ࣌', 'ولئن سألتهم ليقولن إنما كنا نخوض ونلعب࣌ قل ࡰبالله وءايته ورسوله كنتم تستهزءون࣌', NULL, 197, 'local:warsh-text.json'),
  ('warsh-9-66', 'warsh', 9, 66, 'لَا تَعْتَذِرُواْ࣌ قَدْ كَفَرْتُم بَعْدَ إِيمَٰنِكُمُۥٓ࣌ إِنْ يُّعْفَ عَن طَآئِفَةࣲ مِّنكُمْ تُعَذَّبْ طَآئِفَةُۢ بِأَنَّهُمْ كَانُواْ مُجْرِمِينَ࣌', 'لا تعتذروا࣌ قد كفرتم بعد إيمنكم࣌ إن يعف عن طائفة منكم تعذب طائفة بأنهم كانوا مجرمين࣌', NULL, 197, 'local:warsh-text.json'),
  ('warsh-9-67', 'warsh', 9, 67, 'ࡰ۬لْمُنَٰفِقُونَ وَالْمُنَٰفِقَٰتُ بَعْضُهُم مِّنۢ بَعْضࣲ يَامُرُونَ بِالْمُنكَرِ وَيَنْهَوْنَ عَنِ ࡴ۬لْمَعْرُوفِ وَيَقْبِضُونَ أَيْدِيَهُمْ نَسُواْ ࡲ۬للَّهَ فَنَسِيَهُمُۥٓ࣌ إِنَّ ࡰ۬لْمُنَٰفِقِينَ هُمُ ࡲ۬لْفَٰسِقُونَ࣌', 'ࡰلمنفقون والمنفقت بعضهم من بعض يامرون بالمنكر وينهون عن ࡴلمعروف ويقبضون أيديهم نسوا ࡲلله فنسيهم࣌ إن ࡰلمنفقين هم ࡲلفسقون࣌', NULL, 197, 'local:warsh-text.json'),
  ('warsh-9-68', 'warsh', 9, 68, 'وَعَدَ ࡰ۬للَّهُ ࡲ۬لْمُنَٰفِقِينَ وَالْمُنَٰفِقَٰتِ وَالْكُفَّارَ نَارَ جَهَنَّمَ خَٰلِدِينَ فِيهَا࣌ هِيَ حَسْبُهُمْ࣌ وَلَعَنَهُمُ ࡲ۬للَّهُ࣌ وَلَهُمْ عَذَابࣱ مُّقِيمࣱ࣌', 'وعد ࡰلله ࡲلمنفقين والمنفقت والكفار نار جهنم خلدين فيها࣌ هي حسبهم࣌ ولعنهم ࡲلله࣌ ولهم عذاب مقيم࣌', NULL, 197, 'local:warsh-text.json'),
  ('warsh-9-69', 'warsh', 9, 69, 'كَالذِينَ مِن قَبْلِكُمْ كَانُوٓاْ أَشَدَّ مِنكُمْ قُوَّةࣰ وَأَكْثَرَ أَمْوَٰلاࣰ وَأَوْلَٰداࣰ فَاسْتَمْتَعُواْ بِخَلَٰقِهِمْ فَاسْتَمْتَعْتُم بِخَلَٰقِكُمْ كَمَا ࡰٜسْتَمْتَعَ ࡰ۬لذِينَ مِن قَبْلِكُم بِخَلَٰقِهِمْ وَخُضْتُمْ كَالذِے خَاضُوٓاْ࣌ أُوْلَٰٓئِكَ حَبِطَتَ ࡰعْمَٰلُهُمْ فِے ࡴ۬لدُّنْيٜا وَالَاخِرَةِ࣌ وَأُوْلَٰٓئِكَ هُمُ ࡲ۬لْخَٰسِرُونَ࣌', 'كالذين من قبلكم كانوا أشد منكم قوة وأكثر أمولا وأولدا فاستمتعوا بخلقهم فاستمتعتم بخلقكم كما ࡰستمتع ࡰلذين من قبلكم بخلقهم وخضتم كالذے خاضوا࣌ أولئك حبطت ࡰعملهم فے ࡴلدنيا والاخرة࣌ وأولئك هم ࡲلخسرون࣌', NULL, 198, 'local:warsh-text.json'),
  ('warsh-9-70', 'warsh', 9, 70, '۞ أَلَمْ يَاتِهِمْ نَبَأُ ࡲ۬لذِينَ مِن قَبْلِهِمْ قَوْمِ نُوحࣲ وَعَادࣲ وَثَمُودَ', 'ألم ياتهم نبأ ࡲلذين من قبلهم قوم نوح وعاد وثمود', NULL, 198, 'local:warsh-text.json'),
  ('warsh-9-71', 'warsh', 9, 71, 'وَقَوْمِ إِبْرَٰهِيمَ وَأَصْحَٰبِ مَدْيَنَ وَالْمُوتَفِكَٰتِ࣌ أَتَتْهُمْ رُسُلُهُم بِالْبَيِّنَٰتِ࣌ فَمَا كَانَ ࡰ۬للَّهُ لِيَظْلِمَهُمْ࣌ وَلَٰكِن كَانُوٓاْ أَنفُسَهُمْ يَظْلِمُونَ࣌', 'وقوم إبرهيم وأصحب مدين والموتفكت࣌ أتتهم رسلهم بالبينت࣌ فما كان ࡰلله ليظلمهم࣌ ولكن كانوا أنفسهم يظلمون࣌', NULL, 198, 'local:warsh-text.json'),
  ('warsh-9-72', 'warsh', 9, 72, 'وَالْمُومِنُونَ وَالْمُومِنَٰتُ بَعْضُهُمُۥٓ أَوْلِيَآءُ بَعْضࣲ࣌ يَامُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ ࡴ۬لْمُنكَرِ وَيُقِيمُونَ ࡰ۬لصَّلَوٰةَ وَيُوتُونَ ࡰ۬لزَّكَوٰةَ وَيُطِيعُونَ ࡰ۬للَّهَ وَرَسُولَهُۥٓ࣌ أُوْلَٰٓئِكَ سَيَرْحَمُهُمُ ࡲ۬للَّهُ࣌ إِنَّ ࡰ۬للَّهَ عَزِيزٌ حَكِيمࣱ࣌', 'والمومنون والمومنت بعضهم أولياء بعض࣌ يامرون بالمعروف وينهون عن ࡴلمنكر ويقيمون ࡰلصلوة ويوتون ࡰلزكوة ويطيعون ࡰلله ورسوله࣌ أولئك سيرحمهم ࡲلله࣌ إن ࡰلله عزيز حكيم࣌', NULL, 198, 'local:warsh-text.json'),
  ('warsh-9-73', 'warsh', 9, 73, 'وَعَدَ ࡰ۬للَّهُ ࡲ۬لْمُومِنِينَ وَالْمُومِنَٰتِ جَنَّٰتࣲ تَجْرِے مِن تَحْتِهَا ࡰ۬لَانْهَٰرُ خَٰلِدِينَ فِيهَا وَمَسَٰكِنَ طَيِّبَةࣰ فِے جَنَّٰتِ عَدْنࣲ࣌ وَرِضْوَٰنࣱ مِّنَ ࡰ۬للَّهِ أَكْبَرُ࣌ ذَٰلِكَ هُوَ ࡰ۬لْفَوْزُ ࡲ۬لْعَظِيمُ࣌', 'وعد ࡰلله ࡲلمومنين والمومنت جنت تجرے من تحتها ࡰلانهر خلدين فيها ومسكن طيبة فے جنت عدن࣌ ورضون من ࡰلله أكبر࣌ ذلك هو ࡰلفوز ࡲلعظيم࣌', NULL, 198, 'local:warsh-text.json'),
  ('warsh-9-74', 'warsh', 9, 74, 'يَٰٓأَيُّهَا‏ ࡰ۬لنَّبِےٓءُ جَٰهِدِ ࡴ۬لْكُفَّارَ وَالْمُنَٰفِقِينَ وَاغْلُظْ عَلَيْهِمْ࣌ وَمَأْوٜيٰهُمْ جَهَنَّمُ࣌ وَبِيسَ ࡰ۬لْمَصِيرُ࣌', 'يأيها‏ ࡰلنبےء جهد ࡴلكفار والمنفقين واغلظ عليهم࣌ ومأويهم جهنم࣌ وبيس ࡰلمصير࣌', NULL, 199, 'local:warsh-text.json'),
  ('warsh-9-75', 'warsh', 9, 75, 'يَحْلِفُونَ بِاللَّهِ مَا قَالُواْ࣌ وَلَقَدْ قَالُواْ كَلِمَةَ ࡰ۬لْكُفْرِ وَكَفَرُواْ بَعْدَ إِسْلَٰمِهِمْ وَهَمُّواْ بِمَا لَمْ يَنَالُواْ࣌ وَمَا نَقَمُوٓاْ إِلَّآ أَنَ ࡰغْنٜيٰهُمُ ࡲ۬للَّهُ وَرَسُولُهُۥ مِن فَضْلِهِۦ࣌ فَإِنْ يَّتُوبُواْ يَكُ خَيْراࣰ لَّهُمْ࣌ وَإِنْ يَّتَوَلَّوْاْ يُعَذِّبْهُمُ ࡲ۬للَّهُ عَذَاباً ࡰلِيماࣰ فِے ࡴ۬لدُّنْيٜا وَالَاخِرَةِ࣌ وَمَا لَهُمْ فِے ࡴ۬لَارْضِ مِنْ وَّلِيࣲّ وَلَا نَصِيرࣲ࣌', 'يحلفون بالله ما قالوا࣌ ولقد قالوا كلمة ࡰلكفر وكفروا بعد إسلمهم وهموا بما لم ينالوا࣌ وما نقموا إلا أن ࡰغنيهم ࡲلله ورسوله من فضله࣌ فإن يتوبوا يك خيرا لهم࣌ وإن يتولوا يعذبهم ࡲلله عذابا ࡰليما فے ࡴلدنيا والاخرة࣌ وما لهم فے ࡴلارض من ولي ولا نصير࣌', NULL, 199, 'local:warsh-text.json'),
  ('warsh-9-76', 'warsh', 9, 76, '۞ وَمِنْهُم مَّنْ عَٰهَدَ ࡰ۬للَّهَ لَئِنَ اٰتٜيٰنَا مِن فَضْلِهِۦ لَنَصَّدَّقَنَّ وَلَنَكُونَنَّ مِنَ ࡰ۬لصَّٰلِحِينَ࣌', 'ومنهم من عهد ࡰلله لئن اتينا من فضله لنصدقن ولنكونن من ࡰلصلحين࣌', NULL, 199, 'local:warsh-text.json'),
  ('warsh-9-77', 'warsh', 9, 77, 'فَلَمَّآ ءَاتٜيٰهُم مِّن فَضْلِهِۦ بَخِلُواْ بِهِۦ وَتَوَلَّواْ وَّهُم مُّعْرِضُونَ࣌', 'فلما ءاتيهم من فضله بخلوا به وتولوا وهم معرضون࣌', NULL, 199, 'local:warsh-text.json'),
  ('warsh-9-78', 'warsh', 9, 78, 'فَأَعْقَبَهُمْ نِفَاقاࣰ فِے قُلُوبِهِمُۥٓ إِلَىٰ يَوْمِ يَلْقَوْنَهُۥ بِمَآ أَخْلَفُواْ ࡲ۬للَّهَ مَا وَعَدُوهُ وَبِمَا كَانُواْ يَكْذِبُونَ࣌', 'فأعقبهم نفاقا فے قلوبهم إلى يوم يلقونه بما أخلفوا ࡲلله ما وعدوه وبما كانوا يكذبون࣌', NULL, 199, 'local:warsh-text.json'),
  ('warsh-9-79', 'warsh', 9, 79, 'أَلَمْ يَعْلَمُوٓاْ أَنَّ ࡰ۬للَّهَ يَعْلَمُ سِرَّهُمْ وَنَجْوٜيٰهُمْ وَأَنَّ ࡰ۬للَّهَ عَلَّٰمُ ࡲ۬لْغُيُوبِ࣌', 'ألم يعلموا أن ࡰلله يعلم سرهم ونجويهم وأن ࡰلله علم ࡲلغيوب࣌', NULL, 199, 'local:warsh-text.json'),
  ('warsh-9-80', 'warsh', 9, 80, 'ࡴ۬لذِينَ يَلْمِزُونَ ࡰ۬لْمُطَّوِّعِينَ مِنَ ࡰ۬لْمُومِنِينَ فِے ࡴ۬لصَّدَقَٰتِ وَالذِينَ لَا يَجِدُونَ إِلَّا جُهْدَهُمْ فَيَسْخَرُونَ مِنْهُمْ سَخِرَ ࡰ۬للَّهُ مِنْهُمْ࣌ وَلَهُمْ عَذَابٌ ࡰلِيمٌ࣌', 'ࡴلذين يلمزون ࡰلمطوعين من ࡰلمومنين فے ࡴلصدقت والذين لا يجدون إلا جهدهم فيسخرون منهم سخر ࡰلله منهم࣌ ولهم عذاب ࡰليم࣌', NULL, 199, 'local:warsh-text.json'),
  ('warsh-9-81', 'warsh', 9, 81, 'ࡴٜسْتَغْفِرْ لَهُمُۥٓ أَوْ لَا تَسْتَغْفِرْ لَهُمُۥٓ࣌ إِن تَسْتَغْفِرْ لَهُمْ سَبْعِينَ مَرَّةࣰ فَلَنْ يَّغْفِرَ ࡰ۬للَّهُ لَهُمْ࣌ ذَٰلِكَ بِأَنَّهُمْ كَفَرُواْ بِاللَّهِ وَرَسُولِهِۦ࣌ وَاللَّهُ لَا يَهْدِے ࡴ۬لْقَوْمَ ࡰ۬لْفَٰسِقِينَ࣌', 'ࡴستغفر لهم أو لا تستغفر لهم࣌ إن تستغفر لهم سبعين مرة فلن يغفر ࡰلله لهم࣌ ذلك بأنهم كفروا بالله ورسوله࣌ والله لا يهدے ࡴلقوم ࡰلفسقين࣌', NULL, 200, 'local:warsh-text.json'),
  ('warsh-9-82', 'warsh', 9, 82, 'فَرِحَ ࡰ۬لْمُخَلَّفُونَ بِمَقْعَدِهِمْ خِلَٰفَ رَسُولِ ࡴ۬للَّهِ وَكَرِهُوٓاْ أَنْ يُّجَٰهِدُواْ بِأَمْوَٰلِهِمْ وَأَنفُسِهِمْ فِے سَبِيلِ ࡴ۬للَّهِ وَقَالُواْ لَا تَنفِرُواْ فِے ࡴ۬لْحَرِّ࣌ قُلْ نَارُ جَهَنَّمَ أَشَدُّ حَرّاࣰ لَّوْ كَانُواْ يَفْقَهُونَ࣌', 'فرح ࡰلمخلفون بمقعدهم خلف رسول ࡴلله وكرهوا أن يجهدوا بأمولهم وأنفسهم فے سبيل ࡴلله وقالوا لا تنفروا فے ࡴلحر࣌ قل نار جهنم أشد حرا لو كانوا يفقهون࣌', NULL, 200, 'local:warsh-text.json'),
  ('warsh-9-83', 'warsh', 9, 83, 'فَلْيَضْحَكُواْ قَلِيلاࣰ وَلْيَبْكُواْ كَثِيراࣰ جَزَآءَۢ بِمَا كَانُواْ يَكْسِبُونَ࣌', 'فليضحكوا قليلا وليبكوا كثيرا جزاء بما كانوا يكسبون࣌', NULL, 200, 'local:warsh-text.json'),
  ('warsh-9-84', 'warsh', 9, 84, 'فَإِن رَّجَعَكَ ࡰ۬للَّهُ إِلَىٰ طَآئِفَةࣲ مِّنْهُمْ فَاسْتَٰذَنُوكَ لِلْخُرُوجِ فَقُل لَّن تَخْرُجُواْ مَعِيَ أَبَداࣰ وَلَن تُقَٰتِلُواْ مَعِے عَدُوّاً࣌ ࡴنَّكُمْ رَضِيتُم بِالْقُعُودِ أَوَّلَ مَرَّةࣲ࣌ فَاقْعُدُواْ مَعَ ࡰ۬لْخَٰلِفِينَ࣌', 'فإن رجعك ࡰلله إلى طائفة منهم فاستذنوك للخروج فقل لن تخرجوا معي أبدا ولن تقتلوا معے عدوا࣌ ࡴنكم رضيتم بالقعود أول مرة࣌ فاقعدوا مع ࡰلخلفين࣌', NULL, 200, 'local:warsh-text.json'),
  ('warsh-9-85', 'warsh', 9, 85, 'وَلَا تُصَلِّ عَلَىٰٓ أَحَدࣲ مِّنْهُم مَّاتَ أَبَداࣰ وَلَا تَقُمْ عَلَىٰ قَبْرِهِۦٓ࣌ إِنَّهُمْ كَفَرُواْ بِاللَّهِ وَرَسُولِهِۦ وَمَاتُواْ وَهُمْ فَٰسِقُونَ࣌', 'ولا تصل على أحد منهم مات أبدا ولا تقم على قبره࣌ إنهم كفروا بالله ورسوله وماتوا وهم فسقون࣌', NULL, 200, 'local:warsh-text.json'),
  ('warsh-9-86', 'warsh', 9, 86, '۞ وَلَا تُعْجِبْكَ أَمْوَٰلُهُمْ وَأَوْلَٰدُهُمُۥٓ࣌ إِنَّمَا يُرِيدُ ࡲ۬للَّهُ أَنْ يُّعَذِّبَهُم بِهَا فِے ࡴ۬لدُّنْيٜا وَتَزْهَقَ أَنفُسُهُمْ وَهُمْ كَٰفِرُونَ࣌', 'ولا تعجبك أمولهم وأولدهم࣌ إنما يريد ࡲلله أن يعذبهم بها فے ࡴلدنيا وتزهق أنفسهم وهم كفرون࣌', NULL, 200, 'local:warsh-text.json'),
  ('warsh-9-87', 'warsh', 9, 87, 'وَإِذَآ أُنزِلَتْ سُورَةٌ ࡰنَ اٰمِنُواْ بِاللَّهِ وَجَٰهِدُواْ مَعَ رَسُولِهِ ࡴٜسْتَٰذَنَكَ أُوْلُواْ ࡲ۬لطَّوْلِ مِنْهُمْ وَقَالُواْ ذَرْنَا نَكُن مَّعَ ࡰ۬لْقَٰعِدِينَ࣌', 'وإذا أنزلت سورة ࡰن امنوا بالله وجهدوا مع رسوله ࡴستذنك أولوا ࡲلطول منهم وقالوا ذرنا نكن مع ࡰلقعدين࣌', NULL, 200, 'local:warsh-text.json'),
  ('warsh-9-88', 'warsh', 9, 88, 'رَضُواْ بِأَنْ يَّكُونُواْ مَعَ ࡰ۬لْخَوَالِفِ࣌ وَطُبِعَ عَلَىٰ قُلُوبِهِمْ فَهُمْ لَا يَفْقَهُونَ࣌', 'رضوا بأن يكونوا مع ࡰلخوالف࣌ وطبع على قلوبهم فهم لا يفقهون࣌', NULL, 201, 'local:warsh-text.json'),
  ('warsh-9-89', 'warsh', 9, 89, 'لَٰكِنِ ࡴ۬لرَّسُولُ وَالذِينَ ءَامَنُواْ مَعَهُۥ جَٰهَدُواْ بِأَمْوَٰلِهِمْ وَأَنفُسِهِمْ࣌ وَأُوْلَٰٓئِكَ لَهُمُ ࡲ۬لْخَيْرَٰتُ࣌ وَأُوْلَٰٓئِكَ هُمُ ࡲ۬لْمُفْلِحُونَ࣌', 'لكن ࡴلرسول والذين ءامنوا معه جهدوا بأمولهم وأنفسهم࣌ وأولئك لهم ࡲلخيرت࣌ وأولئك هم ࡲلمفلحون࣌', NULL, 201, 'local:warsh-text.json'),
  ('warsh-9-90', 'warsh', 9, 90, 'أَعَدَّ ࡰ۬للَّهُ لَهُمْ جَنَّٰتࣲ تَجْرِے مِن تَحْتِهَا ࡰ۬لَانْهَٰرُ خَٰلِدِينَ فِيهَا࣌ ذَٰلِكَ ࡰ۬لْفَوْزُ ࡲ۬لْعَظِيمُ࣌', 'أعد ࡰلله لهم جنت تجرے من تحتها ࡰلانهر خلدين فيها࣌ ذلك ࡰلفوز ࡲلعظيم࣌', NULL, 201, 'local:warsh-text.json'),
  ('warsh-9-91', 'warsh', 9, 91, 'وَجَآءَ ࡰ۬لْمُعَذِّرُونَ مِنَ ࡰ۬لَاعْرَابِ لِيُوذَنَ لَهُمْ وَقَعَدَ ࡰ۬لذِينَ كَذَبُواْ ࡲ۬للَّهَ وَرَسُولَهُۥ࣌ سَيُصِيبُ ࡲ۬لذِينَ كَفَرُواْ مِنْهُمْ عَذَابٌ ࡰلِيمࣱ࣌', 'وجاء ࡰلمعذرون من ࡰلاعراب ليوذن لهم وقعد ࡰلذين كذبوا ࡲلله ورسوله࣌ سيصيب ࡲلذين كفروا منهم عذاب ࡰليم࣌', NULL, 201, 'local:warsh-text.json'),
  ('warsh-9-92', 'warsh', 9, 92, 'لَّيْسَ عَلَى ࡰ۬لضُّعَفَآءِ وَلَا عَلَى ࡰ۬لْمَرْضٜىٰ وَلَا عَلَى ࡰ۬لذِينَ لَا يَجِدُونَ مَا يُنفِقُونَ حَرَجٌ ࡴذَا نَصَحُواْ لِلهِ وَرَسُولِهِۦ࣌ مَا عَلَى ࡰ۬لْمُحْسِنِينَ مِن سَبِيلࣲ࣌ وَاللَّهُ غَفُورࣱ رَّحِيمࣱ࣌', 'ليس على ࡰلضعفاء ولا على ࡰلمرضى ولا على ࡰلذين لا يجدون ما ينفقون حرج ࡴذا نصحوا لله ورسوله࣌ ما على ࡰلمحسنين من سبيل࣌ والله غفور رحيم࣌', NULL, 201, 'local:warsh-text.json'),
  ('warsh-9-93', 'warsh', 9, 93, 'وَلَا عَلَى ࡰ۬لذِينَ إِذَا مَآ أَتَوْكَ لِتَحْمِلَهُمْ قُلْتَ لَآ أَجِدُ مَآ أَحْمِلُكُمْ عَلَيْهِ࣌ تَوَلَّواْ وَّأَعْيُنُهُمْ تَفِيضُ مِنَ ࡰ۬لدَّمْعِ حَزَناً ࡰلَّا يَجِدُواْ مَا يُنفِقُونَ࣌', 'ولا على ࡰلذين إذا ما أتوك لتحملهم قلت لا أجد ما أحملكم عليه࣌ تولوا وأعينهم تفيض من ࡰلدمع حزنا ࡰلا يجدوا ما ينفقون࣌', NULL, 201, 'local:warsh-text.json'),
  ('warsh-9-94', 'warsh', 9, 94, '۞ إِنَّمَا ࡰ۬لسَّبِيلُ عَلَى ࡰ۬لذِينَ يَسْتَٰذِنُونَكَ وَهُمُۥٓ أَغْنِيَآءُ࣌ رَضُواْ بِأَنْ يَّكُونُواْ مَعَ ࡰ۬لْخَوَالِفِ࣌ وَطَبَعَ ࡰ۬للَّهُ عَلَىٰ قُلُوبِهِمْ فَهُمْ لَا يَعْلَمُونَ࣌', 'إنما ࡰلسبيل على ࡰلذين يستذنونك وهم أغنياء࣌ رضوا بأن يكونوا مع ࡰلخوالف࣌ وطبع ࡰلله على قلوبهم فهم لا يعلمون࣌', NULL, 201, 'local:warsh-text.json'),
  ('warsh-9-95', 'warsh', 9, 95, 'يَعْتَذِرُونَ إِلَيْكُمُۥٓ إِذَا رَجَعْتُمُۥٓ إِلَيْهِمْ࣌ قُل لَّا تَعْتَذِرُواْ لَن نُّومِنَ لَكُمْ࣌ قَدْ نَبَّأَنَا ࡰ۬للَّهُ مِنَ ࡰخْبٜارِكُمْ࣌ وَسَيَرَى ࡰ۬للَّهُ عَمَلَكُمْ وَرَسُولُهُۥ࣌ ثُمَّ تُرَدُّونَ إِلَىٰ عَٰلِمِ ࡴ۬لْغَيْبِ وَالشَّهَٰدَةِ فَيُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ࣌', 'يعتذرون إليكم إذا رجعتم إليهم࣌ قل لا تعتذروا لن نومن لكم࣌ قد نبأنا ࡰلله من ࡰخباركم࣌ وسيرى ࡰلله عملكم ورسوله࣌ ثم تردون إلى علم ࡴلغيب والشهدة فينبئكم بما كنتم تعملون࣌', NULL, 202, 'local:warsh-text.json'),
  ('warsh-9-96', 'warsh', 9, 96, 'سَيَحْلِفُونَ بِاللَّهِ لَكُمُۥٓ إِذَا ࡰٜنقَلَبْتُمُۥٓ إِلَيْهِمْ لِتُعْرِضُواْ عَنْهُمْ࣌ فَأَعْرِضُواْ عَنْهُمُۥٓ࣌ إِنَّهُمْ رِجْسࣱ࣌ وَمَأْوٜيٰهُمْ جَهَنَّمُ࣌ جَزَآءَۢ بِمَا كَانُواْ يَكْسِبُونَ࣌', 'سيحلفون بالله لكم إذا ࡰنقلبتم إليهم لتعرضوا عنهم࣌ فأعرضوا عنهم࣌ إنهم رجس࣌ ومأويهم جهنم࣌ جزاء بما كانوا يكسبون࣌', NULL, 202, 'local:warsh-text.json'),
  ('warsh-9-97', 'warsh', 9, 97, 'يَحْلِفُونَ لَكُمْ لِتَرْضَوْاْ عَنْهُمْ فَإِن تَرْضَوْاْ عَنْهُمْ فَإِنَّ ࡰ۬للَّهَ لَا يَرْضٜىٰ عَنِ ࡴ۬لْقَوْمِ ࡴ۬لْفَٰسِقِينَ࣌', 'يحلفون لكم لترضوا عنهم فإن ترضوا عنهم فإن ࡰلله لا يرضى عن ࡴلقوم ࡴلفسقين࣌', NULL, 202, 'local:warsh-text.json'),
  ('warsh-9-98', 'warsh', 9, 98, 'ࡰ۬لَاعْرَابُ أَشَدُّ كُفْراࣰ وَنِفَاقاࣰ وَأَجْدَرُ أَلَّا يَعْلَمُواْ حُدُودَ مَآ أَنزَلَ ࡰ۬للَّهُ عَلَىٰ رَسُولِهِۦ࣌ وَاللَّهُ عَلِيمٌ حَكِيمࣱ࣌', 'ࡰلاعراب أشد كفرا ونفاقا وأجدر ألا يعلموا حدود ما أنزل ࡰلله على رسوله࣌ والله عليم حكيم࣌', NULL, 202, 'local:warsh-text.json'),
  ('warsh-9-99', 'warsh', 9, 99, 'وَمِنَ ࡰ۬لَاعْرَابِ مَنْ يَّتَّخِذُ مَا يُنفِقُ مَغْرَماࣰ وَيَتَرَبَّصُ بِكُمُ ࡲ۬لدَّوَآئِرَ࣌ عَلَيْهِمْ دَآئِرَةُ ࡲ۬لسَّوْءِ࣌ وَاللَّهُ سَمِيعٌ عَلِيمࣱ࣌', 'ومن ࡰلاعراب من يتخذ ما ينفق مغرما ويتربص بكم ࡲلدوائر࣌ عليهم دائرة ࡲلسوء࣌ والله سميع عليم࣌', NULL, 202, 'local:warsh-text.json'),
  ('warsh-9-100', 'warsh', 9, 100, 'وَمِنَ ࡰ۬لَاعْرَابِ مَنْ يُّومِنُ بِاللَّهِ وَالْيَوْمِ ࡴ۬لَاخِرِ وَيَتَّخِذُ مَا يُنفِقُ قُرُبَٰتٍ عِندَ ࡰ۬للَّهِ وَصَلَوَٰتِ ࡴ۬لرَّسُولِ࣌ أَلَآ إِنَّهَا قُرُبَةࣱ لَّهُمْ࣌ سَيُدْخِلُهُمُ ࡲ۬للَّهُ فِے رَحْمَتِهِۦٓ࣌ إِنَّ ࡰ۬للَّهَ غَفُورࣱ رَّحِيمࣱ࣌', 'ومن ࡰلاعراب من يومن بالله واليوم ࡴلاخر ويتخذ ما ينفق قربت عند ࡰلله وصلوت ࡴلرسول࣌ ألا إنها قربة لهم࣌ سيدخلهم ࡲلله فے رحمته࣌ إن ࡰلله غفور رحيم࣌', NULL, 202, 'local:warsh-text.json'),
  ('warsh-9-101', 'warsh', 9, 101, 'وَالسَّٰبِقُونَ ࡰ۬لَاوَّلُونَ مِنَ ࡰ۬لْمُهَٰجِرِينَ وَالَانصٜارِ وَالذِينَ ࡰٜتَّبَعُوهُم بِإِحْسَٰنࣲ رَّضِيَ ࡰ۬للَّهُ عَنْهُمْ وَرَضُواْ عَنْهُ࣌ وَأَعَدَّ لَهُمْ جَنَّٰتࣲ تَجْرِے تَحْتَهَا ࡰ۬لَانْهَٰرُ خَٰلِدِينَ فِيهَآ أَبَداࣰ࣌ ذَٰلِكَ ࡰ۬لْفَوْزُ ࡲ۬لْعَظِيمُ࣌', 'والسبقون ࡰلاولون من ࡰلمهجرين والانصار والذين ࡰتبعوهم بإحسن رضي ࡰلله عنهم ورضوا عنه࣌ وأعد لهم جنت تجرے تحتها ࡰلانهر خلدين فيها أبدا࣌ ذلك ࡰلفوز ࡲلعظيم࣌', NULL, 203, 'local:warsh-text.json'),
  ('warsh-9-102', 'warsh', 9, 102, '۞ وَمِمَّنْ حَوْلَكُم مِّنَ ࡰ۬لَاعْرَابِ مُنَٰفِقُونَ࣌ وَمِنَ ࡰهْلِ ࡴ۬لْمَدِينَةِ مَرَدُواْ عَلَى ࡰ۬لنِّفَاقِ لَا تَعْلَمُهُمْ࣌ نَحْنُ نَعْلَمُهُمْ࣌ سَنُعَذِّبُهُم مَّرَّتَيْنِ ثُمَّ يُرَدُّونَ إِلَىٰ عَذَابٍ عَظِيمࣲ࣌', 'وممن حولكم من ࡰلاعراب منفقون࣌ ومن ࡰهل ࡴلمدينة مردوا على ࡰلنفاق لا تعلمهم࣌ نحن نعلمهم࣌ سنعذبهم مرتين ثم يردون إلى عذاب عظيم࣌', NULL, 203, 'local:warsh-text.json'),
  ('warsh-9-103', 'warsh', 9, 103, 'وَءَاخَرُونَ ࡰٜعْتَرَفُواْ بِذُنُوبِهِمْ خَلَطُواْ عَمَلاࣰ صَٰلِحاࣰ وَءَاخَرَ سَيِّئاً عَسَى ࡰ۬للَّهُ أَنْ يَّتُوبَ عَلَيْهِمُۥٓ࣌ إِنَّ ࡰ۬للَّهَ غَفُورࣱ رَّحِيمٌ࣌', 'وءاخرون ࡰعترفوا بذنوبهم خلطوا عملا صلحا وءاخر سيئا عسى ࡰلله أن يتوب عليهم࣌ إن ࡰلله غفور رحيم࣌', NULL, 203, 'local:warsh-text.json'),
  ('warsh-9-104', 'warsh', 9, 104, 'خُذْ مِنَ ࡰمْوَٰلِهِمْ صَدَقَةࣰ تُطَهِّرُهُمْ وَتُزَكِّيهِم بِهَا وَصَلِّ عَلَيْهِمُۥٓ࣌ إِنَّ صَلَوَٰتِكَ سَكَنࣱ لَّهُمْ࣌ وَاللَّهُ سَمِيعٌ عَلِيمٌ࣌', 'خذ من ࡰمولهم صدقة تطهرهم وتزكيهم بها وصل عليهم࣌ إن صلوتك سكن لهم࣌ والله سميع عليم࣌', NULL, 203, 'local:warsh-text.json'),
  ('warsh-9-105', 'warsh', 9, 105, 'ࡰلَمْ يَعْلَمُوٓاْ أَنَّ ࡰ۬للَّهَ هُوَ يَقْبَلُ ࡲ۬لتَّوْبَةَ عَنْ عِبَادِهِۦ وَيَاخُذُ ࡲ۬لصَّدَقَٰتِ وَأَنَّ ࡰ۬للَّهَ هُوَ ࡰ۬لتَّوَّابُ ࡲ۬لرَّحِيمُ࣌', 'ࡰلم يعلموا أن ࡰلله هو يقبل ࡲلتوبة عن عباده وياخذ ࡲلصدقت وأن ࡰلله هو ࡰلتواب ࡲلرحيم࣌', NULL, 203, 'local:warsh-text.json'),
  ('warsh-9-106', 'warsh', 9, 106, 'وَقُلِ ࡴٜعْمَلُواْ فَسَيَرَى ࡰ۬للَّهُ عَمَلَكُمْ وَرَسُولُهُۥ وَالْمُومِنُونَ࣌ وَسَتُرَدُّونَ إِلَىٰ عَٰلِمِ ࡴ۬لْغَيْبِ وَالشَّهَٰدَةِ فَيُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ࣌', 'وقل ࡴعملوا فسيرى ࡰلله عملكم ورسوله والمومنون࣌ وستردون إلى علم ࡴلغيب والشهدة فينبئكم بما كنتم تعملون࣌', NULL, 203, 'local:warsh-text.json'),
  ('warsh-9-107', 'warsh', 9, 107, 'وَءَاخَرُونَ مُرْجَوْنَ لِأَمْرِ ࡴ۬للَّهِ إِمَّا يُعَذِّبُهُمْ وَإِمَّا يَتُوبُ عَلَيْهِمْ࣌ وَاللَّهُ عَلِيمٌ حَكِيمٌ࣌', 'وءاخرون مرجون لأمر ࡴلله إما يعذبهم وإما يتوب عليهم࣌ والله عليم حكيم࣌', NULL, 203, 'local:warsh-text.json'),
  ('warsh-9-108', 'warsh', 9, 108, 'ࡴ۬لذِينَ ࡰٜتَّخَذُواْ مَسْجِداࣰ ضِرَاراࣰ وَكُفْراࣰ وَتَفْرِيقاَۢ بَيْنَ ࡰ۬لْمُومِنِينَ وَإِرْصَاداࣰ لِّمَنْ حَارَبَ ࡰ۬للَّهَ وَرَسُولَهُۥ مِن قَبْلُ࣌ وَلَيَحْلِفُنَّ إِنَ ࡰرَدْنَآ إِلَّا ࡰ۬لْحُسْنٜىٰ࣌ وَاللَّهُ يَشْهَدُ إِنَّهُمْ لَكَٰذِبُونَ࣌', 'ࡴلذين ࡰتخذوا مسجدا ضرارا وكفرا وتفريقا بين ࡰلمومنين وإرصادا لمن حارب ࡰلله ورسوله من قبل࣌ وليحلفن إن ࡰردنا إلا ࡰلحسنى࣌ والله يشهد إنهم لكذبون࣌', NULL, 204, 'local:warsh-text.json'),
  ('warsh-9-109', 'warsh', 9, 109, 'لَا تَقُمْ فِيهِ أَبَداࣰ࣌ لَّمَسْجِدٌ ࡳسِّسَ عَلَى ࡰ۬لتَّقْوٜىٰ مِنَ ࡰوَّلِ يَوْمٍ ࡰحَقُّ أَن تَقُومَ فِيهِ࣌ فِيهِ رِجَالࣱ يُحِبُّونَ أَنْ يَّتَطَهَّرُواْ࣌ وَاللَّهُ يُحِبُّ ࡲ۬لْمُطَّهِّرِينَ࣌', 'لا تقم فيه أبدا࣌ لمسجد ࡳسس على ࡰلتقوى من ࡰول يوم ࡰحق أن تقوم فيه࣌ فيه رجال يحبون أن يتطهروا࣌ والله يحب ࡲلمطهرين࣌', NULL, 204, 'local:warsh-text.json'),
  ('warsh-9-110', 'warsh', 9, 110, 'أَفَمَنُ ࡳسِّسَ بُنْيَٰنُهُۥ عَلَىٰ تَقْوٜىٰ مِنَ ࡰ۬للَّهِ وَرِضْوَٰنٍ خَيْرٌ ࡰم مَّنُ ࡳسِّسَ بُنْيَٰنُهُۥ عَلَىٰ شَفَا جُرُفٍ هٜارࣲ فَانْهَارَ بِهِۦ فِے نٜارِ جَهَنَّمَ࣌ وَاللَّهُ لَا يَهْدِے ࡴ۬لْقَوْمَ ࡰ۬لظَّٰلِمِينَ࣌', 'أفمن ࡳسس بنينه على تقوى من ࡰلله ورضون خير ࡰم من ࡳسس بنينه على شفا جرف هار فانهار به فے نار جهنم࣌ والله لا يهدے ࡴلقوم ࡰلظلمين࣌', NULL, 204, 'local:warsh-text.json'),
  ('warsh-9-111', 'warsh', 9, 111, 'لَا يَزَالُ بُنْيَٰنُهُمُ ࡲ۬لذِے بَنَوْاْ رِيبَةࣰ فِے قُلُوبِهِمُۥٓ إِلَّآ أَن تُقَطَّعَ قُلُوبُهُمْ࣌ وَاللَّهُ عَلِيمٌ حَكِيمٌ࣌', 'لا يزال بنينهم ࡲلذے بنوا ريبة فے قلوبهم إلا أن تقطع قلوبهم࣌ والله عليم حكيم࣌', NULL, 204, 'local:warsh-text.json'),
  ('warsh-9-112', 'warsh', 9, 112, '۞ ࡴنَّ ࡰ۬للَّهَ ࡰٜشْتَرٜىٰ مِنَ ࡰ۬لْمُومِنِينَ أَنفُسَهُمْ وَأَمْوَٰلَهُم بِأَنَّ لَهُمُ ࡲ۬لْجَنَّةَ࣌ يُقَٰتِلُونَ فِے سَبِيلِ ࡴ۬للَّهِ فَيَقْتُلُونَ وَيُقْتَلُونَ وَعْداً عَلَيْهِ حَقّاࣰ فِے ࡴ۬لتَّوْرٜيٰةِ وَالِانجِيلِ وَالْقُرْءَانِ࣌ وَمَنَ ࡰوْفٜىٰ بِعَهْدِهِۦ مِنَ ࡰ۬للَّهِ࣌ فَاسْتَبْشِرُواْ بِبَيْعِكُمُ ࡲ۬لذِے بَايَعْتُم بِهِۦ࣌ وَذَٰلِكَ هُوَ ࡰ۬لْفَوْزُ ࡲ۬لْعَظِيمُ࣌', 'ࡴن ࡰلله ࡰشترى من ࡰلمومنين أنفسهم وأمولهم بأن لهم ࡲلجنة࣌ يقتلون فے سبيل ࡴلله فيقتلون ويقتلون وعدا عليه حقا فے ࡴلتورية والانجيل والقرءان࣌ ومن ࡰوفى بعهده من ࡰلله࣌ فاستبشروا ببيعكم ࡲلذے بايعتم به࣌ وذلك هو ࡰلفوز ࡲلعظيم࣌', NULL, 204, 'local:warsh-text.json'),
  ('warsh-9-113', 'warsh', 9, 113, 'ࡲ۬لتَّٰٓئِبُونَ ࡰ۬لْعَٰبِدُونَ ࡰ۬لْحَٰمِدُونَ ࡰ۬لسَّٰٓئِحُونَ ࡰ۬لرَّٰكِعُونَ ࡰ۬لسَّٰجِدُونَ ࡰ۬لَامِرُونَ بِالْمَعْرُوفِ وَالنَّاهُونَ عَنِ ࡴ۬لْمُنكَرِ وَالْحَٰفِظُونَ لِحُدُودِ ࡴ۬للَّهِ࣌ وَبَشِّرِ ࡴ۬لْمُومِنِينَ࣌', 'ࡲلتئبون ࡰلعبدون ࡰلحمدون ࡰلسئحون ࡰلركعون ࡰلسجدون ࡰلامرون بالمعروف والناهون عن ࡴلمنكر والحفظون لحدود ࡴلله࣌ وبشر ࡴلمومنين࣌', NULL, 205, 'local:warsh-text.json'),
  ('warsh-9-114', 'warsh', 9, 114, 'مَا كَانَ لِلنَّبِےٓءِ وَالذِينَ ءَامَنُوٓاْ أَنْ يَّسْتَغْفِرُواْ لِلْمُشْرِكِينَ وَلَوْ كَانُوٓاْ أُوْلِے قُرْبٜىٰ مِنۢ بَعْدِ مَا تَبَيَّنَ لَهُمُۥٓ أَنَّهُمُۥٓ أَصْحَٰبُ ࡲ۬لْجَحِيمِ࣌', 'ما كان للنبےء والذين ءامنوا أن يستغفروا للمشركين ولو كانوا أولے قربى من بعد ما تبين لهم أنهم أصحب ࡲلجحيم࣌', NULL, 205, 'local:warsh-text.json'),
  ('warsh-9-115', 'warsh', 9, 115, 'وَمَا كَانَ ࡰٜسْتِغْفَارُ إِبْرَٰهِيمَ لِأَبِيهِ إِلَّا عَن مَّوْعِدَةࣲ وَعَدَهَآ إِيَّاهُ࣌ فَلَمَّا تَبَيَّنَ لَهُۥٓ أَنَّهُۥ عَدُوࣱّ لِّلهِ تَبَرَّأَ مِنْهُ࣌ إِنَّ إِبْرَٰهِيمَ لَأَوَّٰهٌ حَلِيمࣱ࣌', 'وما كان ࡰستغفار إبرهيم لأبيه إلا عن موعدة وعدها إياه࣌ فلما تبين له أنه عدو لله تبرأ منه࣌ إن إبرهيم لأوه حليم࣌', NULL, 205, 'local:warsh-text.json'),
  ('warsh-9-116', 'warsh', 9, 116, 'وَمَا كَانَ ࡰ۬للَّهُ لِيُضِلَّ قَوْماَۢ بَعْدَ إِذْ هَدٜيٰهُمْ حَتَّىٰ يُبَيِّنَ لَهُم مَّا يَتَّقُونَ࣌ إِنَّ ࡰ۬للَّهَ بِكُلِّ شَےْءٍ عَلِيمٌ࣌', 'وما كان ࡰلله ليضل قوما بعد إذ هديهم حتى يبين لهم ما يتقون࣌ إن ࡰلله بكل شےء عليم࣌', NULL, 205, 'local:warsh-text.json'),
  ('warsh-9-117', 'warsh', 9, 117, 'ࡴنَّ ࡰ۬للَّهَ لَهُۥ مُلْكُ ࡲ۬لسَّمَٰوَٰتِ وَالَارْضِ࣌ يُحْيِۦ وَيُمِيتُ࣌ وَمَا لَكُم مِّن دُونِ ࡴ۬للَّهِ مِنْ وَّلِيࣲّ وَلَا نَصِيرࣲ࣌', 'ࡴن ࡰلله له ملك ࡲلسموت والارض࣌ يحي ويميت࣌ وما لكم من دون ࡴلله من ولي ولا نصير࣌', NULL, 205, 'local:warsh-text.json'),
  ('warsh-9-118', 'warsh', 9, 118, '۞ لَّقَد تَّابَ ࡰ۬للَّهُ عَلَى ࡰ۬لنَّبِےٓءِ وَالْمُهَٰجِرِينَ وَالَانصٜارِ ࡴ۬لذِينَ ࡰٜتَّبَعُوهُ فِے سَاعَةِ ࡴ۬لْعُسْرَةِ مِنۢ بَعْدِ مَا كَادَ تَزِيغُ قُلُوبُ فَرِيقࣲ مِّنْهُمْ ثُمَّ تَابَ عَلَيْهِمُۥٓ إِنَّهُۥ بِهِمْ رَءُوفࣱ رَّحِيمࣱ', 'لقد تاب ࡰلله على ࡰلنبےء والمهجرين والانصار ࡴلذين ࡰتبعوه فے ساعة ࡴلعسرة من بعد ما كاد تزيغ قلوب فريق منهم ثم تاب عليهم إنه بهم رءوف رحيم', NULL, 205, 'local:warsh-text.json'),
  ('warsh-9-119', 'warsh', 9, 119, 'وَعَلَى ࡰ۬لثَّلَٰثَةِ ࡴ۬لذِينَ خُلِّفُواْ࣌ حَتَّىٰٓ إِذَا ضَاقَتْ عَلَيْهِمُ ࡲ۬لَارْضُ بِمَا رَحُبَتْ وَضَاقَتْ عَلَيْهِمُۥٓ أَنفُسُهُمْ وَظَنُّوٓاْ أَن لَّا مَلْجَأَ مِنَ ࡰ۬للَّهِ إِلَّآ إِلَيْهِ ثُمَّ تَابَ عَلَيْهِمْ لِيَتُوبُوٓاْ࣌ إِنَّ ࡰ۬للَّهَ هُوَ ࡰ۬لتَّوَّابُ ࡲ۬لرَّحِيمُ࣌', 'وعلى ࡰلثلثة ࡴلذين خلفوا࣌ حتى إذا ضاقت عليهم ࡲلارض بما رحبت وضاقت عليهم أنفسهم وظنوا أن لا ملجأ من ࡰلله إلا إليه ثم تاب عليهم ليتوبوا࣌ إن ࡰلله هو ࡰلتواب ࡲلرحيم࣌', NULL, 206, 'local:warsh-text.json'),
  ('warsh-9-120', 'warsh', 9, 120, 'يَٰٓأَيُّهَا ࡰ۬لذِينَ ءَامَنُواْ ࡲٜتَّقُواْ ࡲ۬للَّهَ وَكُونُواْ مَعَ ࡰ۬لصَّٰدِقِينَ࣌', 'يأيها ࡰلذين ءامنوا ࡲتقوا ࡲلله وكونوا مع ࡰلصدقين࣌', NULL, 206, 'local:warsh-text.json'),
  ('warsh-9-121', 'warsh', 9, 121, 'مَا كَانَ لِأَهْلِ ࡴ۬لْمَدِينَةِ وَمَنْ حَوْلَهُم مِّنَ ࡰ۬لَاعْرَابِ أَنْ يَّتَخَلَّفُواْ عَن رَّسُولِ ࡴ۬للَّهِ وَلَا يَرْغَبُواْ بِأَنفُسِهِمْ عَن نَّفْسِهِۦ࣌ ذَٰلِكَ بِأَنَّهُمْ لَا يُصِيبُهُمْ ظَمَأࣱ وَلَا نَصَبࣱ وَلَا مَخْمَصَةࣱ فِے سَبِيلِ ࡴ۬للَّهِ وَلَا يَطَـُٔونَ مَوْطِئاࣰ يَغِيظُ ࡲ۬لْكُفَّارَ وَلَا يَنَالُونَ مِنْ عَدُوࣲّ نَّيْلاً ࡴلَّا كُتِبَ لَهُم بِهِۦ عَمَلࣱ صَٰلِحٌ࣌ ࡴنَّ ࡰ۬للَّهَ لَا يُضِيعُ أَجْرَ ࡰ۬لْمُحْسِنِينَ࣌', 'ما كان لأهل ࡴلمدينة ومن حولهم من ࡰلاعراب أن يتخلفوا عن رسول ࡴلله ولا يرغبوا بأنفسهم عن نفسه࣌ ذلك بأنهم لا يصيبهم ظمأ ولا نصب ولا مخمصة فے سبيل ࡴلله ولا يطون موطئا يغيظ ࡲلكفار ولا ينالون من عدو نيلا ࡴلا كتب لهم به عمل صلح࣌ ࡴن ࡰلله لا يضيع أجر ࡰلمحسنين࣌', NULL, 206, 'local:warsh-text.json'),
  ('warsh-9-122', 'warsh', 9, 122, 'وَلَا يُنفِقُونَ نَفَقَةࣰ صَغِيرَةࣰ وَلَا كَبِيرَةࣰ وَلَا يَقْطَعُونَ وَادِياً ࡴلَّا كُتِبَ لَهُمْ࣌ لِيَجْزِيَهُمُ ࡲ۬للَّهُ أَحْسَنَ مَا كَانُواْ يَعْمَلُونَ࣌', 'ولا ينفقون نفقة صغيرة ولا كبيرة ولا يقطعون واديا ࡴلا كتب لهم࣌ ليجزيهم ࡲلله أحسن ما كانوا يعملون࣌', NULL, 206, 'local:warsh-text.json'),
  ('warsh-9-123', 'warsh', 9, 123, 'وَمَا كَانَ ࡰ۬لْمُومِنُونَ لِيَنفِرُواْ كَآفَّةࣰ࣌ فَلَوْلَا نَفَرَ مِن كُلِّ فِرْقَةࣲ مِّنْهُمْ طَآئِفَةࣱ لِّيَتَفَقَّهُواْ فِے ࡴ۬لدِّينِ وَلِيُنذِرُواْ قَوْمَهُمُۥٓ إِذَا رَجَعُوٓاْ إِلَيْهِمْ لَعَلَّهُمْ يَحْذَرُونَ࣌', 'وما كان ࡰلمومنون لينفروا كافة࣌ فلولا نفر من كل فرقة منهم طائفة ليتفقهوا فے ࡴلدين ولينذروا قومهم إذا رجعوا إليهم لعلهم يحذرون࣌', NULL, 206, 'local:warsh-text.json'),
  ('warsh-9-124', 'warsh', 9, 124, '۞ يَٰٓأَيُّهَا ࡰ۬لذِينَ ءَامَنُواْ قَٰتِلُواْ ࡲ۬لذِينَ يَلُونَكُم مِّنَ ࡰ۬لْكُفّٜارِ وَلْيَجِدُواْ فِيكُمْ غِلْظَةࣰ࣌ وَاعْلَمُوٓاْ أَنَّ ࡰ۬للَّهَ مَعَ ࡰ۬لْمُتَّقِينَ࣌', 'يأيها ࡰلذين ءامنوا قتلوا ࡲلذين يلونكم من ࡰلكفار وليجدوا فيكم غلظة࣌ واعلموا أن ࡰلله مع ࡰلمتقين࣌', NULL, 207, 'local:warsh-text.json'),
  ('warsh-9-125', 'warsh', 9, 125, 'وَإِذَا مَآ أُنزِلَتْ سُورَةࣱ فَمِنْهُم مَّنْ يَّقُولُ أَيُّكُمْ زَادَتْهُ هَٰذِهِۦٓ إِيمَٰناࣰ࣌ فَأَمَّا ࡰ۬لذِينَ ءَامَنُواْ فَزَادَتْهُمُۥٓ إِيمَٰناࣰ وَهُمْ يَسْتَبْشِرُونَ࣌', 'وإذا ما أنزلت سورة فمنهم من يقول أيكم زادته هذه إيمنا࣌ فأما ࡰلذين ءامنوا فزادتهم إيمنا وهم يستبشرون࣌', NULL, 207, 'local:warsh-text.json'),
  ('warsh-9-126', 'warsh', 9, 126, 'وَأَمَّا ࡰ۬لذِينَ فِے قُلُوبِهِم مَّرَضࣱ فَزَادَتْهُمْ رِجْساً ࡴلَىٰ رِجْسِهِمْ وَمَاتُواْ وَهُمْ كَٰفِرُونَ࣌', 'وأما ࡰلذين فے قلوبهم مرض فزادتهم رجسا ࡴلى رجسهم وماتوا وهم كفرون࣌', NULL, 207, 'local:warsh-text.json'),
  ('warsh-9-127', 'warsh', 9, 127, 'أَوَلَا يَرَوْنَ أَنَّهُمْ يُفْتَنُونَ فِے كُلِّ عَامࣲ مَّرَّةً ࡰوْ مَرَّتَيْنِ ثُمَّ لَا يَتُوبُونَ وَلَا هُمْ يَذَّكَّرُونَ࣌', 'أولا يرون أنهم يفتنون فے كل عام مرة ࡰو مرتين ثم لا يتوبون ولا هم يذكرون࣌', NULL, 207, 'local:warsh-text.json'),
  ('warsh-9-128', 'warsh', 9, 128, 'وَإِذَا مَآ أُنزِلَتْ سُورَةࣱ نَّظَرَ بَعْضُهُمُۥٓ إِلَىٰ بَعْضٍ هَلْ يَرٜيٰكُم مِّنَ ࡰحَدࣲ ثُمَّ ࡰٜنصَرَفُواْ࣌ صَرَفَ ࡰ۬للَّهُ قُلُوبَهُم بِأَنَّهُمْ قَوْمࣱ لَّا يَفْقَهُونَ࣌', 'وإذا ما أنزلت سورة نظر بعضهم إلى بعض هل يريكم من ࡰحد ثم ࡰنصرفوا࣌ صرف ࡰلله قلوبهم بأنهم قوم لا يفقهون࣌', NULL, 207, 'local:warsh-text.json'),
  ('warsh-9-129', 'warsh', 9, 129, 'لَقَدْ جَآءَكُمْ رَسُولࣱ مِّنَ ࡰنفُسِكُمْ عَزِيزٌ عَلَيْهِ مَا عَنِتُّمْ࣌ حَرِيصٌ عَلَيْكُم࣌ بِالْمُومِنِينَ رَءُوفࣱ رَّحِيمࣱ࣌', 'لقد جاءكم رسول من ࡰنفسكم عزيز عليه ما عنتم࣌ حريص عليكم࣌ بالمومنين رءوف رحيم࣌', NULL, 207, 'local:warsh-text.json'),
  ('warsh-9-130', 'warsh', 9, 130, 'فَإِن تَوَلَّوْاْ فَقُلْ حَسْبِيَ ࡰ۬للَّهُ࣌ لَآ إِلَٰهَ إِلَّا هُوَ࣌ عَلَيْهِ تَوَكَّلْتُ࣌ وَهُوَ رَبُّ ࡲ۬لْعَرْشِ ࡴ۬لْعَظِيمِ࣌', 'فإن تولوا فقل حسبي ࡰلله࣌ لا إله إلا هو࣌ عليه توكلت࣌ وهو رب ࡲلعرش ࡴلعظيم࣌', NULL, 207, 'local:warsh-text.json'),
  ('warsh-10-1', 'warsh', 10, 1, 'أَلَٓرٜ࣌ تِلْكَ ءَايَٰتُ ࡲ۬لْكِتَٰبِ ࡴ۬لْحَكِيمِ࣌', 'ألر࣌ تلك ءايت ࡲلكتب ࡴلحكيم࣌', NULL, 208, 'local:warsh-text.json'),
  ('warsh-10-2', 'warsh', 10, 2, 'أَكَانَ لِلنَّاسِ عَجَباً ࡰنَ ࡰوْحَيْنَآ إِلَىٰ رَجُلࣲ مِّنْهُمُۥٓ أَنَ ࡰنذِرِ ࡴ۬لنَّاسَ࣌ وَبَشِّرِ ࡴ۬لذِينَ ءَامَنُوٓاْ أَنَّ لَهُمْ قَدَمَ صِدْقٍ عِندَ رَبِّهِمْ࣌ قَالَ ࡰ۬لْكَٰفِرُونَ إِنَّ هَٰذَا لَسِحْرࣱ مُّبِينٌ࣌', 'أكان للناس عجبا ࡰن ࡰوحينا إلى رجل منهم أن ࡰنذر ࡴلناس࣌ وبشر ࡴلذين ءامنوا أن لهم قدم صدق عند ربهم࣌ قال ࡰلكفرون إن هذا لسحر مبين࣌', NULL, 208, 'local:warsh-text.json'),
  ('warsh-10-3', 'warsh', 10, 3, '۞ ࡴنَّ رَبَّكُمُ ࡲ۬للَّهُ ࡲ۬لذِے خَلَقَ ࡰ۬لسَّمَٰوَٰتِ وَالَارْضَ فِے سِتَّةِ أَيَّامࣲ ثُمَّ ࡰٜسْتَوٜىٰ عَلَى ࡰ۬لْعَرْشِ࣌ يُدَبِّرُ ࡲ۬لَامْرَ࣌ مَا مِن شَفِيعٍ ࡴلَّا مِنۢ بَعْدِ إِذْنِهِۦ࣌ ذَٰلِكُمُ ࡲ۬للَّهُ رَبُّكُمْ࣌ فَاعْبُدُوهُ࣌ أَفَلَا تَذَّكَّرُونَ࣌', 'ࡴن ربكم ࡲلله ࡲلذے خلق ࡰلسموت والارض فے ستة أيام ثم ࡰستوى على ࡰلعرش࣌ يدبر ࡲلامر࣌ ما من شفيع ࡴلا من بعد إذنه࣌ ذلكم ࡲلله ربكم࣌ فاعبدوه࣌ أفلا تذكرون࣌', NULL, 208, 'local:warsh-text.json'),
  ('warsh-10-4', 'warsh', 10, 4, 'إِلَيْهِ مَرْجِعُكُمْ جَمِيعاࣰ࣌ وَعْدَ ࡰ۬للَّهِ حَقّاً࣌ ࡴنَّهُۥ يَبْدَؤُاْ ࡲ۬لْخَلْقَ ثُمَّ يُعِيدُهُۥ لِيَجْزِيَ ࡰ۬لذِينَ ءَامَنُواْ وَعَمِلُواْ ࡲ۬لصَّٰلِحَٰتِ بِالْقِسْطِ࣌ وَالذِينَ كَفَرُواْ لَهُمْ شَرَابࣱ مِّنْ حَمِيمࣲ وَعَذَابٌ ࡰلِيمُۢ بِمَا كَانُواْ يَكْفُرُونَ࣌', 'إليه مرجعكم جميعا࣌ وعد ࡰلله حقا࣌ ࡴنه يبدؤا ࡲلخلق ثم يعيده ليجزي ࡰلذين ءامنوا وعملوا ࡲلصلحت بالقسط࣌ والذين كفروا لهم شراب من حميم وعذاب ࡰليم بما كانوا يكفرون࣌', NULL, 208, 'local:warsh-text.json'),
  ('warsh-10-5', 'warsh', 10, 5, 'هُوَ ࡰ۬لذِے جَعَلَ ࡰ۬لشَّمْسَ ضِيَآءࣰ وَالْقَمَرَ نُوراࣰ وَقَدَّرَهُۥ مَنَازِلَ لِتَعْلَمُواْ عَدَدَ ࡰ۬لسِّنِينَ وَالْحِسَابَ࣌ مَا خَلَقَ ࡰ۬للَّهُ ذَٰلِكَ إِلَّا بِالْحَقِّ࣌ نُفَصِّلُ ࡲ۬لَايَٰتِ لِقَوْمࣲ يَعْلَمُونَ࣌', 'هو ࡰلذے جعل ࡰلشمس ضياء والقمر نورا وقدره منازل لتعلموا عدد ࡰلسنين والحساب࣌ ما خلق ࡰلله ذلك إلا بالحق࣌ نفصل ࡲلايت لقوم يعلمون࣌', NULL, 208, 'local:warsh-text.json'),
  ('warsh-10-6', 'warsh', 10, 6, 'إِنَّ فِے ࡴٜخْتِلَٰفِ ࡴ۬ليْلِ وَالنَّهٜارِ وَمَا خَلَقَ ࡰ۬للَّهُ فِے ࡴ۬لسَّمَٰوَٰتِ وَالَارْضِ لَأٓيَٰتࣲ لِّقَوْمࣲ يَتَّقُونَ࣌', 'إن فے ࡴختلف ࡴليل والنهار وما خلق ࡰلله فے ࡴلسموت والارض لأيت لقوم يتقون࣌', NULL, 208, 'local:warsh-text.json'),
  ('warsh-10-7', 'warsh', 10, 7, 'إِنَّ ࡰ۬لذِينَ لَا يَرْجُونَ لِقَآءَنَا وَرَضُواْ بِالْحَيَوٰةِ ࡴ۬لدُّنْيٜا وَاطْمَأَنُّواْ بِهَا وَالذِينَ هُمْ عَنَ اٰيَٰتِنَا غَٰفِلُونَ', 'إن ࡰلذين لا يرجون لقاءنا ورضوا بالحيوة ࡴلدنيا واطمأنوا بها والذين هم عن ايتنا غفلون', NULL, 209, 'local:warsh-text.json'),
  ('warsh-10-8', 'warsh', 10, 8, 'أُوْلَٰٓئِكَ مَأْوٜيٰهُمُ ࡲ۬لنَّارُ بِمَا كَانُواْ يَكْسِبُونَ࣌', 'أولئك مأويهم ࡲلنار بما كانوا يكسبون࣌', NULL, 209, 'local:warsh-text.json'),
  ('warsh-10-9', 'warsh', 10, 9, 'إِنَّ ࡰ۬لذِينَ ءَامَنُواْ وَعَمِلُواْ ࡲ۬لصَّٰلِحَٰتِ يَهْدِيهِمْ رَبُّهُم بِإِيمَٰنِهِمْ࣌ تَجْرِے مِن تَحْتِهِمُ ࡲ۬لَانْهَٰرُ فِے جَنَّٰتِ ࡴ۬لنَّعِيمِ࣌', 'إن ࡰلذين ءامنوا وعملوا ࡲلصلحت يهديهم ربهم بإيمنهم࣌ تجرے من تحتهم ࡲلانهر فے جنت ࡴلنعيم࣌', NULL, 209, 'local:warsh-text.json'),
  ('warsh-10-10', 'warsh', 10, 10, 'دَعْوٜيٰهُمْ فِيهَا سُبْحَٰنَكَ ࡰ۬للَّهُمَّ࣌ وَتَحِيَّتُهُمْ فِيهَا سَلَٰمࣱ࣌ وَءَاخِرُ دَعْوٜيٰهُمُۥٓ أَنِ ࡴ۬لْحَمْدُ لِلهِ رَبِّ ࡴ۬لْعَٰلَمِينَ࣌', 'دعويهم فيها سبحنك ࡰللهم࣌ وتحيتهم فيها سلم࣌ وءاخر دعويهم أن ࡴلحمد لله رب ࡴلعلمين࣌', NULL, 209, 'local:warsh-text.json'),
  ('warsh-10-11', 'warsh', 10, 11, '۞ وَلَوْ يُعَجِّلُ ࡲ۬للَّهُ لِلنَّاسِ ࡴ۬لشَّرَّ ࡰٜسْتِعْجَالَهُم بِالْخَيْرِ لَقُضِيَ إِلَيْهِمُۥٓ أَجَلُهُمْ࣌ فَنَذَرُ ࡲ۬لذِينَ لَا يَرْجُونَ لِقَآءَنَا فِے طُغْيَٰنِهِمْ يَعْمَهُونَ࣌', 'ولو يعجل ࡲلله للناس ࡴلشر ࡰستعجالهم بالخير لقضي إليهم أجلهم࣌ فنذر ࡲلذين لا يرجون لقاءنا فے طغينهم يعمهون࣌', NULL, 209, 'local:warsh-text.json'),
  ('warsh-10-12', 'warsh', 10, 12, 'وَإِذَا مَسَّ ࡰ۬لِانسَٰنَ ࡰ۬لضُّرُّ دَعَانَا لِجَنۢبِهِۦٓ أَوْ قَاعِداً ࡰوْ قَآئِماࣰ࣌ فَلَمَّا كَشَفْنَا عَنْهُ ضُرَّهُۥ مَرَّ كَأَن لَّمْ يَدْعُنَآ إِلَىٰ ضُرࣲّ مَّسَّهُۥ࣌ كَذَٰلِكَ زُيِّنَ لِلْمُسْرِفِينَ مَا كَانُواْ يَعْمَلُونَ࣌', 'وإذا مس ࡰلانسن ࡰلضر دعانا لجنبه أو قاعدا ࡰو قائما࣌ فلما كشفنا عنه ضره مر كأن لم يدعنا إلى ضر مسه࣌ كذلك زين للمسرفين ما كانوا يعملون࣌', NULL, 209, 'local:warsh-text.json'),
  ('warsh-10-13', 'warsh', 10, 13, 'وَلَقَدَ ࡰهْلَكْنَا ࡰ۬لْقُرُونَ مِن قَبْلِكُمْ لَمَّا ظَلَمُواْ وَجَآءَتْهُمْ رُسُلُهُم بِالْبَيِّنَٰتِ࣌ وَمَا كَانُواْ لِيُومِنُواْ࣌ كَذَٰلِكَ نَجْزِے ࡴ۬لْقَوْمَ ࡰ۬لْمُجْرِمِينَ࣌', 'ولقد ࡰهلكنا ࡰلقرون من قبلكم لما ظلموا وجاءتهم رسلهم بالبينت࣌ وما كانوا ليومنوا࣌ كذلك نجزے ࡴلقوم ࡰلمجرمين࣌', NULL, 209, 'local:warsh-text.json'),
  ('warsh-10-14', 'warsh', 10, 14, 'ثُمَّ جَعَلْنَٰكُمْ خَلَٰٓئِفَ فِے ࡴ۬لَارْضِ مِنۢ بَعْدِهِمْ لِنَنظُرَ كَيْفَ تَعْمَلُونَ࣌', 'ثم جعلنكم خلئف فے ࡴلارض من بعدهم لننظر كيف تعملون࣌', NULL, 209, 'local:warsh-text.json'),
  ('warsh-10-15', 'warsh', 10, 15, 'وَإِذَا تُتْلٜىٰ عَلَيْهِمُۥٓ ءَايَاتُنَا بَيِّنَٰتࣲ قَالَ ࡰ۬لذِينَ لَا يَرْجُونَ لِقَآءَنَا ࡰٜيتِ بِقُرْءَانٍ غَيْرِ هَٰذَآ أَوْ بَدِّلْهُ࣌ قُلْ مَا يَكُونُ لِيَ أَنُ ࡳبَدِّلَهُۥ مِن تِلْقَآءِےْ نَفْسِيَ࣌ إِنَ ࡰتَّبِعُ إِلَّا مَا يُوحٜىٰٓ إِلَيَّ࣌ إِنِّيَ أَخَافُ إِنْ عَصَيْتُ رَبِّے عَذَابَ يَوْمٍ عَظِيمࣲ࣌', 'وإذا تتلى عليهم ءاياتنا بينت قال ࡰلذين لا يرجون لقاءنا ࡰيت بقرءان غير هذا أو بدله࣌ قل ما يكون لي أن ࡳبدله من تلقاءے نفسي࣌ إن ࡰتبع إلا ما يوحى إلي࣌ إني أخاف إن عصيت ربے عذاب يوم عظيم࣌', NULL, 210, 'local:warsh-text.json'),
  ('warsh-10-16', 'warsh', 10, 16, 'قُل لَّوْ شَآءَ ࡰ۬للَّهُ مَا تَلَوْتُهُۥ عَلَيْكُمْ وَلَآ أَدْرٜيٰكُم بِهِۦ࣌ فَقَدْ لَبِثْتُ فِيكُمْ عُمُراࣰ مِّن قَبْلِهِۦٓ࣌ أَفَلَا تَعْقِلُونَ࣌', 'قل لو شاء ࡰلله ما تلوته عليكم ولا أدريكم به࣌ فقد لبثت فيكم عمرا من قبله࣌ أفلا تعقلون࣌', NULL, 210, 'local:warsh-text.json'),
  ('warsh-10-17', 'warsh', 10, 17, 'فَمَنَ ࡰظْلَمُ مِمَّنِ ࡴٜفْتَرٜىٰ عَلَى ࡰ۬للَّهِ كَذِباً ࡰوْ كَذَّبَ بِـَٔايَٰتِهِۦٓ࣌ إِنَّهُۥ لَا يُفْلِحُ ࡲ۬لْمُجْرِمُونَ࣌', 'فمن ࡰظلم ممن ࡴفترى على ࡰلله كذبا ࡰو كذب بايته࣌ إنه لا يفلح ࡲلمجرمون࣌', NULL, 210, 'local:warsh-text.json'),
  ('warsh-10-18', 'warsh', 10, 18, 'وَيَعْبُدُونَ مِن دُونِ ࡴ۬للَّهِ مَا لَا يَضُرُّهُمْ وَلَا يَنفَعُهُمْ وَيَقُولُونَ هَٰٓؤُلَآءِ شُفَعَٰٓؤُنَا عِندَ ࡰ۬للَّهِ࣌ قُلَ ࡰتُنَبِّـُٔونَ ࡰ۬للَّهَ بِمَا لَا يَعْلَمُ فِے ࡴ۬لسَّمَٰوَٰتِ وَلَا فِے ࡴ۬لَارْضِ࣌ سُبْحَٰنَهُۥ وَتَعَٰلٜىٰ عَمَّا يُشْرِكُونَ࣌', 'ويعبدون من دون ࡴلله ما لا يضرهم ولا ينفعهم ويقولون هؤلاء شفعؤنا عند ࡰلله࣌ قل ࡰتنبون ࡰلله بما لا يعلم فے ࡴلسموت ولا فے ࡴلارض࣌ سبحنه وتعلى عما يشركون࣌', NULL, 210, 'local:warsh-text.json'),
  ('warsh-10-19', 'warsh', 10, 19, '۞ وَمَا كَانَ ࡰ۬لنَّاسُ إِلَّآ أُمَّةࣰ وَٰحِدَةࣰ فَاخْتَلَفُواْ࣌ وَلَوْلَا كَلِمَةࣱ سَبَقَتْ مِن رَّبِّكَ لَقُضِيَ بَيْنَهُمْ فِيمَا فِيهِ يَخْتَلِفُونَ࣌', 'وما كان ࡰلناس إلا أمة وحدة فاختلفوا࣌ ولولا كلمة سبقت من ربك لقضي بينهم فيما فيه يختلفون࣌', NULL, 210, 'local:warsh-text.json'),
  ('warsh-10-20', 'warsh', 10, 20, 'وَيَقُولُونَ لَوْلَآ أُنزِلَ عَلَيْهِ ءَايَةࣱ مِّن رَّبِّهِۦ࣌ فَقُلِ ࡴنَّمَا ࡰ۬لْغَيْبُ لِلهِ࣌ فَانتَظِرُوٓاْ࣌ إِنِّے مَعَكُم مِّنَ ࡰ۬لْمُنتَظِرِينَ࣌', 'ويقولون لولا أنزل عليه ءاية من ربه࣌ فقل ࡴنما ࡰلغيب لله࣌ فانتظروا࣌ إنے معكم من ࡰلمنتظرين࣌', NULL, 210, 'local:warsh-text.json'),
  ('warsh-10-21', 'warsh', 10, 21, 'وَإِذَآ أَذَقْنَا ࡰ۬لنَّاسَ رَحْمَةࣰ مِّنۢ بَعْدِ ضَرَّآءَ مَسَّتْهُمُۥٓ إِذَا لَهُم مَّكْرࣱ فِےٓ ءَايَاتِنَا࣌ قُلِ ࡴ۬للَّهُ أَسْرَعُ مَكْراً࣌ ࡴنَّ رُسُلَنَا يَكْتُبُونَ مَا تَمْكُرُونَ࣌', 'وإذا أذقنا ࡰلناس رحمة من بعد ضراء مستهم إذا لهم مكر فے ءاياتنا࣌ قل ࡴلله أسرع مكرا࣌ ࡴن رسلنا يكتبون ما تمكرون࣌', NULL, 211, 'local:warsh-text.json'),
  ('warsh-10-22', 'warsh', 10, 22, 'هُوَ ࡰ۬لذِے يُسَيِّرُكُمْ فِے ࡴ۬لْبَرِّ وَالْبَحْرِ࣌ حَتَّىٰٓ إِذَا كُنتُمْ فِے ࡴ۬لْفُلْكِ وَجَرَيْنَ بِهِم بِرِيحࣲ طَيِّبَةࣲ وَفَرِحُواْ بِهَا جَآءَتْهَا رِيحٌ عَاصِفࣱ وَجَآءَهُمُ ࡲ۬لْمَوْجُ مِن كُلِّ مَكَانࣲ وَظَنُّوٓاْ أَنَّهُمُۥٓ أُحِيطَ بِهِمْ دَعَوُاْ ࡲ۬للَّهَ مُخْلِصِينَ لَهُ ࡲ۬لدِّينَ لَئِنَ ࡰنجَيْتَنَا مِنْ هَٰذِهِۦ لَنَكُونَنَّ مِنَ ࡰ۬لشَّٰكِرِينَ࣌', 'هو ࡰلذے يسيركم فے ࡴلبر والبحر࣌ حتى إذا كنتم فے ࡴلفلك وجرين بهم بريح طيبة وفرحوا بها جاءتها ريح عاصف وجاءهم ࡲلموج من كل مكان وظنوا أنهم أحيط بهم دعوا ࡲلله مخلصين له ࡲلدين لئن ࡰنجيتنا من هذه لنكونن من ࡰلشكرين࣌', NULL, 211, 'local:warsh-text.json'),
  ('warsh-10-23', 'warsh', 10, 23, 'فَلَمَّآ أَنجٜيٰهُمُۥٓ إِذَا هُمْ يَبْغُونَ فِے ࡴ۬لَارْضِ بِغَيْرِ ࡴ۬لْحَقِّ࣌ يَٰٓأَيُّهَا ࡰ۬لنَّاسُ إِنَّمَا بَغْيُكُمْ عَلَىٰٓ أَنفُسِكُم࣌ مَّتَٰعُ ࡲ۬لْحَيَوٰةِ ࡴ۬لدُّنْيٜا࣌ ثُمَّ إِلَيْنَا مَرْجِعُكُمْ فَنُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ࣌', 'فلما أنجيهم إذا هم يبغون فے ࡴلارض بغير ࡴلحق࣌ يأيها ࡰلناس إنما بغيكم على أنفسكم࣌ متع ࡲلحيوة ࡴلدنيا࣌ ثم إلينا مرجعكم فننبئكم بما كنتم تعملون࣌', NULL, 211, 'local:warsh-text.json'),
  ('warsh-10-24', 'warsh', 10, 24, 'إِنَّمَا مَثَلُ ࡲ۬لْحَيَوٰةِ ࡴ۬لدُّنْيٜا كَمَآءٍ ࡰنزَلْنَٰهُ مِنَ ࡰ۬لسَّمَآءِ فَاخْتَلَطَ࣌ بِهِۦ نَبَاتُ ࡲ۬لَارْضِ مِمَّا يَاكُلُ ࡲ۬لنَّاسُ وَالَانْعَٰمُ࣌ حَتَّىٰٓ إِذَآ أَخَذَتِ ࡴ۬لَارْضُ زُخْرُفَهَا وَازَّيَّنَتْ وَظَنَّ أَهْلُهَآ أَنَّهُمْ قَٰدِرُونَ عَلَيْهَآ أَتٜيٰهَآ أَمْرُنَا لَيْلاً ࡰوْ نَهَاراࣰ فَجَعَلْنَٰهَا حَصِيداࣰ كَأَن لَّمْ تَغْنَ بِالَامْسِ࣌ كَذَٰلِكَ نُفَصِّلُ ࡲ۬لَايَٰتِ لِقَوْمࣲ يَتَفَكَّرُونَ࣌', 'إنما مثل ࡲلحيوة ࡴلدنيا كماء ࡰنزلنه من ࡰلسماء فاختلط࣌ به نبات ࡲلارض مما ياكل ࡲلناس والانعم࣌ حتى إذا أخذت ࡴلارض زخرفها وازينت وظن أهلها أنهم قدرون عليها أتيها أمرنا ليلا ࡰو نهارا فجعلنها حصيدا كأن لم تغن بالامس࣌ كذلك نفصل ࡲلايت لقوم يتفكرون࣌', NULL, 211, 'local:warsh-text.json'),
  ('warsh-10-25', 'warsh', 10, 25, 'وَاللَّهُ يَدْعُوٓاْ إِلَىٰ دٜارِ ࡴ۬لسَّلَٰمِ وَيَهْدِے مَنْ يَّشَآءُ ࡹِلَىٰ صِرَٰطࣲ مُّسْتَقِيمࣲ࣌', 'والله يدعوا إلى دار ࡴلسلم ويهدے من يشاء ࡹلى صرط مستقيم࣌', NULL, 211, 'local:warsh-text.json'),
  ('warsh-10-26', 'warsh', 10, 26, '۞ لِّلذِينَ أَحْسَنُواْ ࡲ۬لْحُسْنٜىٰ وَزِيَادَةࣱ࣌ وَلَا يَرْهَقُ وُجُوهَهُمْ قَتَرࣱ وَلَا ذِلَّةٌ࣌ ࡳوْلَٰٓئِكَ أَصْحَٰبُ ࡲ۬لْجَنَّةِ࣌ هُمْ فِيهَا خَٰلِدُونَ࣌', 'للذين أحسنوا ࡲلحسنى وزيادة࣌ ولا يرهق وجوههم قتر ولا ذلة࣌ ࡳولئك أصحب ࡲلجنة࣌ هم فيها خلدون࣌', NULL, 212, 'local:warsh-text.json'),
  ('warsh-10-27', 'warsh', 10, 27, 'وَالذِينَ كَسَبُواْ ࡲ۬لسَّيِّـَٔاتِ جَزَآءُ سَيِّئَةِۢ بِمِثْلِهَا وَتَرْهَقُهُمْ ذِلَّةࣱ مَّا لَهُم مِّنَ ࡰ۬للَّهِ مِنْ عَاصِمࣲ كَأَنَّمَآ أُغْشِيَتْ وُجُوهُهُمْ قِطَعاࣰ مِّنَ ࡰ۬ليْلِ مُظْلِماً࣌ ࡳوْلَٰٓئِكَ أَصْحَٰبُ ࡲ۬لنّٜارِ هُمْ فِيهَا خَٰلِدُونَ࣌', 'والذين كسبوا ࡲلسيات جزاء سيئة بمثلها وترهقهم ذلة ما لهم من ࡰلله من عاصم كأنما أغشيت وجوههم قطعا من ࡰليل مظلما࣌ ࡳولئك أصحب ࡲلنار هم فيها خلدون࣌', NULL, 212, 'local:warsh-text.json'),
  ('warsh-10-28', 'warsh', 10, 28, 'وَيَوْمَ نَحْشُرُهُمْ جَمِيعاࣰ ثُمَّ نَقُولُ لِلذِينَ أَشْرَكُواْ مَكَانَكُمُۥٓ أَنتُمْ وَشُرَكَآؤُكُمْ فَزَيَّلْنَا بَيْنَهُمْ࣌ وَقَالَ شُرَكَآؤُهُم مَّا كُنتُمُۥٓ إِيَّانَا تَعْبُدُونَ࣌', 'ويوم نحشرهم جميعا ثم نقول للذين أشركوا مكانكم أنتم وشركاؤكم فزيلنا بينهم࣌ وقال شركاؤهم ما كنتم إيانا تعبدون࣌', NULL, 212, 'local:warsh-text.json'),
  ('warsh-10-29', 'warsh', 10, 29, 'فَكَفٜىٰ بِاللَّهِ شَهِيداَۢ بَيْنَنَا وَبَيْنَكُمُۥٓ إِن كُنَّا عَنْ عِبَادَتِكُمْ لَغَٰفِلِينَ࣌', 'فكفى بالله شهيدا بيننا وبينكم إن كنا عن عبادتكم لغفلين࣌', NULL, 212, 'local:warsh-text.json'),
  ('warsh-10-30', 'warsh', 10, 30, 'هُنَالِكَ تَبْلُواْ كُلُّ نَفْسࣲ مَّآ أَسْلَفَتْ࣌ وَرُدُّوٓاْ إِلَى ࡰ۬للَّهِ مَوْلٜيٰهُمُ ࡲ۬لْحَقِّ࣌ وَضَلَّ عَنْهُم مَّا كَانُواْ يَفْتَرُونَ࣌', 'هنالك تبلوا كل نفس ما أسلفت࣌ وردوا إلى ࡰلله موليهم ࡲلحق࣌ وضل عنهم ما كانوا يفترون࣌', NULL, 212, 'local:warsh-text.json'),
  ('warsh-10-31', 'warsh', 10, 31, 'قُلْ مَنْ يَّرْزُقُكُم مِّنَ ࡰ۬لسَّمَآءِ وَالَارْضِ࣌ أَمَّنْ يَّمْلِكُ ࡲ۬لسَّمْعَ وَالَابْصَٰرَ وَمَنْ يُّخْرِجُ ࡲ۬لْحَيَّ مِنَ ࡰ۬لْمَيِّتِ وَيُخْرِجُ ࡲ۬لْمَيِّتَ مِنَ ࡰ۬لْحَيِّ وَمَنْ يُّدَبِّرُ ࡲ۬لَامْرَ࣌ فَسَيَقُولُونَ ࡰ۬للَّهُ࣌ فَقُلَ ࡰفَلَا تَتَّقُونَ࣌', 'قل من يرزقكم من ࡰلسماء والارض࣌ أمن يملك ࡲلسمع والابصر ومن يخرج ࡲلحي من ࡰلميت ويخرج ࡲلميت من ࡰلحي ومن يدبر ࡲلامر࣌ فسيقولون ࡰلله࣌ فقل ࡰفلا تتقون࣌', NULL, 212, 'local:warsh-text.json'),
  ('warsh-10-32', 'warsh', 10, 32, 'فَذَٰلِكُمُ ࡲ۬للَّهُ رَبُّكُمُ ࡲ۬لْحَقُّ࣌ فَمَاذَا بَعْدَ ࡰ۬لْحَقِّ إِلَّا ࡰ۬لضَّلَٰلُ࣌ فَأَنّٜىٰ تُصْرَفُونَ࣌', 'فذلكم ࡲلله ربكم ࡲلحق࣌ فماذا بعد ࡰلحق إلا ࡰلضلل࣌ فأنى تصرفون࣌', NULL, 212, 'local:warsh-text.json'),
  ('warsh-10-33', 'warsh', 10, 33, 'كَذَٰلِكَ حَقَّتْ كَلِمَٰتُ رَبِّكَ عَلَى ࡰ۬لذِينَ فَسَقُوٓاْ أَنَّهُمْ لَا يُومِنُونَ࣌', 'كذلك حقت كلمت ربك على ࡰلذين فسقوا أنهم لا يومنون࣌', NULL, 212, 'local:warsh-text.json'),
  ('warsh-10-34', 'warsh', 10, 34, 'قُلْ هَلْ مِن شُرَكَآئِكُم مَّنْ يَّبْدَؤُاْ ࡲ۬لْخَلْقَ ثُمَّ يُعِيدُهُۥ࣌ قُلِ ࡴ۬للَّهُ يَبْدَؤُاْ ࡲ۬لْخَلْقَ ثُمَّ يُعِيدُهُۥ࣌ فَأَنّٜىٰ تُوفَكُونَ࣌', 'قل هل من شركائكم من يبدؤا ࡲلخلق ثم يعيده࣌ قل ࡴلله يبدؤا ࡲلخلق ثم يعيده࣌ فأنى توفكون࣌', NULL, 213, 'local:warsh-text.json'),
  ('warsh-10-35', 'warsh', 10, 35, 'قُلْ هَلْ مِن شُرَكَآئِكُم مَّنْ يَّهْدِےٓ إِلَى ࡰ۬لْحَقِّ࣌ قُلِ ࡴ۬للَّهُ يَهْدِے لِلْحَقِّ࣌ أَفَمَنْ يَّهْدِےٓ إِلَى ࡰ۬لْحَقِّ أَحَقُّ أَنْ يُّتَّبَعَ أَمَّن لَّا يَهَدِّےٓ إِلَّآ أَنْ يُّهْدٜىٰ࣌ فَمَا لَكُمْ࣌ كَيْفَ تَحْكُمُونَ࣌', 'قل هل من شركائكم من يهدے إلى ࡰلحق࣌ قل ࡴلله يهدے للحق࣌ أفمن يهدے إلى ࡰلحق أحق أن يتبع أمن لا يهدے إلا أن يهدى࣌ فما لكم࣌ كيف تحكمون࣌', NULL, 213, 'local:warsh-text.json'),
  ('warsh-10-36', 'warsh', 10, 36, 'وَمَا يَتَّبِعُ أَكْثَرُهُمُۥٓ إِلَّا ظَنّاً࣌ ࡴنَّ ࡰ۬لظَّنَّ لَا يُغْنِے مِنَ ࡰ۬لْحَقِّ شَيْـٔاً࣌ ࡴنَّ ࡰ۬للَّهَ عَلِيمُۢ بِمَا يَفْعَلُونَ࣌', 'وما يتبع أكثرهم إلا ظنا࣌ ࡴن ࡰلظن لا يغنے من ࡰلحق شيا࣌ ࡴن ࡰلله عليم بما يفعلون࣌', NULL, 213, 'local:warsh-text.json'),
  ('warsh-10-37', 'warsh', 10, 37, '۞ وَمَا كَانَ هَٰذَا ࡰ۬لْقُرْءَانُ أَنْ يُّفْتَرٜىٰ مِن دُونِ ࡴ۬للَّهِ࣌ وَلَٰكِن تَصْدِيقَ ࡰ۬لذِے بَيْنَ يَدَيْهِ وَتَفْصِيلَ ࡰ۬لْكِتَٰبِ لَا رَيْبَ فِيهِ مِن رَّبِّ ࡴ۬لْعَٰلَمِينَ࣌', 'وما كان هذا ࡰلقرءان أن يفترى من دون ࡴلله࣌ ولكن تصديق ࡰلذے بين يديه وتفصيل ࡰلكتب لا ريب فيه من رب ࡴلعلمين࣌', NULL, 213, 'local:warsh-text.json'),
  ('warsh-10-38', 'warsh', 10, 38, 'أَمْ يَقُولُونَ ࡰٜفْتَرٜيٰهُ࣌ قُلْ فَاتُواْ بِسُورَةࣲ مِّثْلِهِۦ࣌ وَادْعُواْ مَنِ ࡴٜسْتَطَعْتُم مِّن دُونِ ࡴ۬للَّهِ إِن كُنتُمْ صَٰدِقِينَ࣌', 'أم يقولون ࡰفتريه࣌ قل فاتوا بسورة مثله࣌ وادعوا من ࡴستطعتم من دون ࡴلله إن كنتم صدقين࣌', NULL, 213, 'local:warsh-text.json'),
  ('warsh-10-39', 'warsh', 10, 39, 'بَلْ كَذَّبُواْ بِمَا لَمْ يُحِيطُواْ بِعِلْمِهِۦ وَلَمَّا يَاتِهِمْ تَاوِيلُهُۥ࣌ كَذَٰلِكَ كَذَّبَ ࡰ۬لذِينَ مِن قَبْلِهِمْ࣌ فَانظُرْ كَيْفَ كَانَ عَٰقِبَةُ ࡲ۬لظَّٰلِمِينَ࣌', 'بل كذبوا بما لم يحيطوا بعلمه ولما ياتهم تاويله࣌ كذلك كذب ࡰلذين من قبلهم࣌ فانظر كيف كان عقبة ࡲلظلمين࣌', NULL, 213, 'local:warsh-text.json'),
  ('warsh-10-40', 'warsh', 10, 40, 'وَمِنْهُم مَّنْ يُّومِنُ بِهِۦ وَمِنْهُم مَّن لَّا يُومِنُ بِهِۦ࣌ وَرَبُّكَ أَعْلَمُ بِالْمُفْسِدِينَ࣌', 'ومنهم من يومن به ومنهم من لا يومن به࣌ وربك أعلم بالمفسدين࣌', NULL, 213, 'local:warsh-text.json'),
  ('warsh-10-41', 'warsh', 10, 41, 'وَإِن كَذَّبُوكَ فَقُل لِّے عَمَلِے وَلَكُمْ عَمَلُكُمُۥٓ أَنتُم بَرِيٓـُٔونَ مِمَّآ أَعْمَلُ وَأَنَا بَرِےٓءࣱ مِّمَّا تَعْمَلُونَ࣌', 'وإن كذبوك فقل لے عملے ولكم عملكم أنتم بريون مما أعمل وأنا برےء مما تعملون࣌', NULL, 213, 'local:warsh-text.json'),
  ('warsh-10-42', 'warsh', 10, 42, 'وَمِنْهُم مَّنْ يَّسْتَمِعُونَ إِلَيْكَ࣌ أَفَأَنتَ تُسْمِعُ ࡲ۬لصُّمَّ وَلَوْ كَانُواْ لَا يَعْقِلُونَ࣌', 'ومنهم من يستمعون إليك࣌ أفأنت تسمع ࡲلصم ولو كانوا لا يعقلون࣌', NULL, 213, 'local:warsh-text.json'),
  ('warsh-10-43', 'warsh', 10, 43, 'وَمِنْهُم مَّنْ يَّنظُرُ إِلَيْكَ࣌ أَفَأَنتَ تَهْدِے ࡴ۬لْعُمْيَ وَلَوْ كَانُواْ لَا يُبْصِرُونَ࣌', 'ومنهم من ينظر إليك࣌ أفأنت تهدے ࡴلعمي ولو كانوا لا يبصرون࣌', NULL, 214, 'local:warsh-text.json'),
  ('warsh-10-44', 'warsh', 10, 44, 'إِنَّ ࡰ۬للَّهَ لَا يَظْلِمُ ࡲ۬لنَّاسَ شَيْـٔاࣰ࣌ وَلَٰكِنَّ ࡰ۬لنَّاسَ أَنفُسَهُمْ يَظْلِمُونَ࣌', 'إن ࡰلله لا يظلم ࡲلناس شيا࣌ ولكن ࡰلناس أنفسهم يظلمون࣌', NULL, 214, 'local:warsh-text.json'),
  ('warsh-10-45', 'warsh', 10, 45, 'وَيَوْمَ نَحْشُرُهُمْ كَأَن لَّمْ يَلْبَثُوٓاْ إِلَّا سَاعَةࣰ مِّنَ ࡰ۬لنَّهٜارِ يَتَعَارَفُونَ بَيْنَهُمْ࣌ قَدْ خَسِرَ ࡰ۬لذِينَ كَذَّبُواْ بِلِقَآءِ ࡴ۬للَّهِ وَمَا كَانُواْ مُهْتَدِينَ࣌', 'ويوم نحشرهم كأن لم يلبثوا إلا ساعة من ࡰلنهار يتعارفون بينهم࣌ قد خسر ࡰلذين كذبوا بلقاء ࡴلله وما كانوا مهتدين࣌', NULL, 214, 'local:warsh-text.json'),
  ('warsh-10-46', 'warsh', 10, 46, 'وَإِمَّا نُرِيَنَّكَ بَعْضَ ࡰ۬لذِے نَعِدُهُمُۥٓ أَوْ نَتَوَفَّيَنَّكَ فَإِلَيْنَا مَرْجِعُهُمْ࣌ ثُمَّ ࡰ۬للَّهُ شَهِيدٌ عَلَىٰ مَا يَفْعَلُونَ࣌', 'وإما نرينك بعض ࡰلذے نعدهم أو نتوفينك فإلينا مرجعهم࣌ ثم ࡰلله شهيد على ما يفعلون࣌', NULL, 214, 'local:warsh-text.json'),
  ('warsh-10-47', 'warsh', 10, 47, 'وَلِكُلِّ أُمَّةࣲ رَّسُولࣱ࣌ فَإِذَا جَآءَ رَسُولُهُمْ قُضِيَ بَيْنَهُم بِالْقِسْطِ وَهُمْ لَا يُظْلَمُونَ࣌', 'ولكل أمة رسول࣌ فإذا جاء رسولهم قضي بينهم بالقسط وهم لا يظلمون࣌', NULL, 214, 'local:warsh-text.json'),
  ('warsh-10-48', 'warsh', 10, 48, 'وَيَقُولُونَ مَتٜىٰ هَٰذَا ࡰ۬لْوَعْدُ إِن كُنتُمْ صَٰدِقِينَ࣌', 'ويقولون متى هذا ࡰلوعد إن كنتم صدقين࣌', NULL, 214, 'local:warsh-text.json'),
  ('warsh-10-49', 'warsh', 10, 49, '۞ قُل لَّآ أَمْلِكُ لِنَفْسِے ضَرّاࣰ وَلَا نَفْعاً ࡴلَّا مَا شَآءَ ࡰ۬للَّهُ࣌ لِكُلِّ أُمَّةٍ ࡰجَلٌ࣌ ࡴذَا جَآءَ اجَلُهُمْ فَلَا يَسْتَٰخِرُونَ سَاعَةࣰ࣌ وَلَا يَسْتَقْدِمُونَ࣌', 'قل لا أملك لنفسے ضرا ولا نفعا ࡴلا ما شاء ࡰلله࣌ لكل أمة ࡰجل࣌ ࡴذا جاء اجلهم فلا يستخرون ساعة࣌ ولا يستقدمون࣌', NULL, 214, 'local:warsh-text.json'),
  ('warsh-10-50', 'warsh', 10, 50, 'قُلَ ࡰرَٰٓيْتُمُۥٓ إِنَ ࡰتٜيٰكُمْ عَذَابُهُۥ بَيَٰتاً ࡰوْ نَهَاراࣰ مَّاذَا يَسْتَعْجِلُ مِنْهُ ࡲ۬لْمُجْرِمُونَ࣌', 'قل ࡰريتم إن ࡰتيكم عذابه بيتا ࡰو نهارا ماذا يستعجل منه ࡲلمجرمون࣌', NULL, 214, 'local:warsh-text.json'),
  ('warsh-10-51', 'warsh', 10, 51, 'أَثُمَّ إِذَا مَا وَقَعَ ءَامَنتُم بِهِۦٓ࣌ ءَالَٰنَ وَقَدْ كُنتُم بِهِۦ تَسْتَعْجِلُونَ࣌', 'أثم إذا ما وقع ءامنتم به࣌ ءالن وقد كنتم به تستعجلون࣌', NULL, 214, 'local:warsh-text.json'),
  ('warsh-10-52', 'warsh', 10, 52, 'ثُمَّ قِيلَ لِلذِينَ ظَلَمُواْ ذُوقُواْ عَذَابَ ࡰ۬لْخُلْدِ࣌ هَلْ تُجْزَوْنَ إِلَّا بِمَا كُنتُمْ تَكْسِبُونَ࣌', 'ثم قيل للذين ظلموا ذوقوا عذاب ࡰلخلد࣌ هل تجزون إلا بما كنتم تكسبون࣌', NULL, 214, 'local:warsh-text.json'),
  ('warsh-10-53', 'warsh', 10, 53, 'وَيَسْتَنۢبِـُٔونَكَ أَحَقٌّ هُوَ࣌ قُلِ ࡴے وَرَبِّيَ إِنَّهُۥ لَحَقࣱّ وَمَآ أَنتُم بِمُعْجِزِينَ࣌', 'ويستنبونك أحق هو࣌ قل ࡴے وربي إنه لحق وما أنتم بمعجزين࣌', NULL, 214, 'local:warsh-text.json'),
  ('warsh-10-54', 'warsh', 10, 54, 'وَلَوَ ࡰنَّ لِكُلِّ نَفْسࣲ ظَلَمَتْ مَا فِے ࡴ۬لَارْضِ لَافْتَدَتْ بِهِۦ࣌ وَأَسَرُّواْ ࡲ۬لنَّدَامَةَ لَمَّا رَأَوُاْ ࡲ۬لْعَذَابَ وَقُضِيَ بَيْنَهُم بِالْقِسْطِ وَهُمْ لَا يُظْلَمُونَ࣌', 'ولو ࡰن لكل نفس ظلمت ما فے ࡴلارض لافتدت به࣌ وأسروا ࡲلندامة لما رأوا ࡲلعذاب وقضي بينهم بالقسط وهم لا يظلمون࣌', NULL, 215, 'local:warsh-text.json'),
  ('warsh-10-55', 'warsh', 10, 55, 'أَلَآ إِنَّ لِلهِ مَا فِے ࡴ۬لسَّمَٰوَٰتِ وَالَارْضِ࣌ أَلَآ إِنَّ وَعْدَ ࡰ۬للَّهِ حَقࣱّ࣌ وَلَٰكِنَّ أَكْثَرَهُمْ لَا يَعْلَمُونَ࣌', 'ألا إن لله ما فے ࡴلسموت والارض࣌ ألا إن وعد ࡰلله حق࣌ ولكن أكثرهم لا يعلمون࣌', NULL, 215, 'local:warsh-text.json'),
  ('warsh-10-56', 'warsh', 10, 56, 'هُوَ يُحْيِۦ وَيُمِيتُ࣌ وَإِلَيْهِ تُرْجَعُونَ࣌', 'هو يحي ويميت࣌ وإليه ترجعون࣌', NULL, 215, 'local:warsh-text.json'),
  ('warsh-10-57', 'warsh', 10, 57, 'يَٰٓأَيُّهَا ࡰ۬لنَّاسُ قَدْ جَآءَتْكُم مَّوْعِظَةࣱ مِّن رَّبِّكُمْ وَشِفَآءࣱ لِّمَا فِے ࡴ۬لصُّدُورِ وَهُدىࣰ وَرَحْمَةࣱ لِّلْمُومِنِينَ࣌', 'يأيها ࡰلناس قد جاءتكم موعظة من ربكم وشفاء لما فے ࡴلصدور وهدى ورحمة للمومنين࣌', NULL, 215, 'local:warsh-text.json'),
  ('warsh-10-58', 'warsh', 10, 58, 'قُلْ بِفَضْلِ ࡴ۬للَّهِ وَبِرَحْمَتِهِۦ فَبِذَٰلِكَ فَلْيَفْرَحُواْ࣌ هُوَ خَيْرࣱ مِّمَّا يَجْمَعُونَ࣌', 'قل بفضل ࡴلله وبرحمته فبذلك فليفرحوا࣌ هو خير مما يجمعون࣌', NULL, 215, 'local:warsh-text.json'),
  ('warsh-10-59', 'warsh', 10, 59, 'قُلَ ࡰرَٰٓيْتُم مَّآ أَنزَلَ ࡰ۬للَّهُ لَكُم مِّن رِّزْقࣲ فَجَعَلْتُم مِّنْهُ حَرَاماࣰ وَحَلَٰلاࣰ࣌ قُلَ آٓللَّهُ أَذِنَ لَكُمُۥٓ أَمْ عَلَى ࡰ۬للَّهِ تَفْتَرُونَ࣌', 'قل ࡰريتم ما أنزل ࡰلله لكم من رزق فجعلتم منه حراما وحللا࣌ قل آلله أذن لكم أم على ࡰلله تفترون࣌', NULL, 215, 'local:warsh-text.json'),
  ('warsh-10-60', 'warsh', 10, 60, 'وَمَا ظَنُّ ࡲ۬لذِينَ يَفْتَرُونَ عَلَى ࡰ۬للَّهِ ࡴ۬لْكَذِبَ يَوْمَ ࡰ۬لْقِيَٰمَةِ࣌ إِنَّ ࡰ۬للَّهَ لَذُو فَضْلٍ عَلَى ࡰ۬لنَّاسِ࣌ وَلَٰكِنَّ أَكْثَرَهُمْ لَا يَشْكُرُونَ࣌', 'وما ظن ࡲلذين يفترون على ࡰلله ࡴلكذب يوم ࡰلقيمة࣌ إن ࡰلله لذو فضل على ࡰلناس࣌ ولكن أكثرهم لا يشكرون࣌', NULL, 215, 'local:warsh-text.json'),
  ('warsh-10-61', 'warsh', 10, 61, '۞ وَمَا تَكُونُ فِے شَأْنࣲ وَمَا تَتْلُواْ مِنْهُ مِن قُرْءَانࣲ وَلَا تَعْمَلُونَ مِنْ عَمَلٍ ࡴلَّا كُنَّا عَلَيْكُمْ شُهُوداً ࡴذْ تُفِيضُونَ فِيهِ࣌ وَمَا يَعْزُبُ عَن رَّبِّكَ مِن مِّثْقَالِ ذَرَّةࣲ فِے ࡴ۬لَارْضِ وَلَا فِے ࡴ۬لسَّمَآءِ࣌ وَلَآ أَصْغَرَ مِن ذَٰلِكَ وَلَآ أَكْبَرَ إِلَّا فِے كِتَٰبࣲ مُّبِينٍ࣌', 'وما تكون فے شأن وما تتلوا منه من قرءان ولا تعملون من عمل ࡴلا كنا عليكم شهودا ࡴذ تفيضون فيه࣌ وما يعزب عن ربك من مثقال ذرة فے ࡴلارض ولا فے ࡴلسماء࣌ ولا أصغر من ذلك ولا أكبر إلا فے كتب مبين࣌', NULL, 215, 'local:warsh-text.json'),
  ('warsh-10-62', 'warsh', 10, 62, 'ࡰلَآ إِنَّ أَوْلِيَآءَ ࡰ۬للَّهِ لَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ࣌', 'ࡰلا إن أولياء ࡰلله لا خوف عليهم ولا هم يحزنون࣌', NULL, 216, 'local:warsh-text.json'),
  ('warsh-10-63', 'warsh', 10, 63, 'ࡰ۬لذِينَ ءَامَنُواْ وَكَانُواْ يَتَّقُونَ', 'ࡰلذين ءامنوا وكانوا يتقون', NULL, 216, 'local:warsh-text.json'),
  ('warsh-10-64', 'warsh', 10, 64, 'لَهُمُ ࡲ۬لْبُشْرٜىٰ فِے ࡴ۬لْحَيَوٰةِ ࡴ۬لدُّنْيٜا وَفِے ࡴ۬لَاخِرَةِ࣌ لَا تَبْدِيلَ لِكَلِمَٰتِ ࡴ۬للَّهِ࣌ ذَٰلِكَ هُوَ ࡰ۬لْفَوْزُ ࡲ۬لْعَظِيمُ࣌', 'لهم ࡲلبشرى فے ࡴلحيوة ࡴلدنيا وفے ࡴلاخرة࣌ لا تبديل لكلمت ࡴلله࣌ ذلك هو ࡰلفوز ࡲلعظيم࣌', NULL, 216, 'local:warsh-text.json'),
  ('warsh-10-65', 'warsh', 10, 65, 'وَلَا يُحْزِنكَ قَوْلُهُمُۥٓ࣌ إِنَّ ࡰ۬لْعِزَّةَ لِلهِ جَمِيعاً࣌ هُوَ ࡰ۬لسَّمِيعُ ࡲ۬لْعَلِيمُ࣌', 'ولا يحزنك قولهم࣌ إن ࡰلعزة لله جميعا࣌ هو ࡰلسميع ࡲلعليم࣌', NULL, 216, 'local:warsh-text.json'),
  ('warsh-10-66', 'warsh', 10, 66, 'أَلَآ إِنَّ لِلهِ مَن فِے ࡴ۬لسَّمَٰوَٰتِ وَمَن فِے ࡴ۬لَارْضِ࣌ وَمَا يَتَّبِعُ ࡲ۬لذِينَ يَدْعُونَ مِن دُونِ ࡴ۬للَّهِ شُرَكَآءَ࣌ ࡹنْ يَّتَّبِعُونَ إِلَّا ࡰ۬لظَّنَّ࣌ وَإِنْ هُمُۥٓ إِلَّا يَخْرُصُونَ࣌', 'ألا إن لله من فے ࡴلسموت ومن فے ࡴلارض࣌ وما يتبع ࡲلذين يدعون من دون ࡴلله شركاء࣌ ࡹن يتبعون إلا ࡰلظن࣌ وإن هم إلا يخرصون࣌', NULL, 216, 'local:warsh-text.json'),
  ('warsh-10-67', 'warsh', 10, 67, 'هُوَ ࡰ۬لذِے جَعَلَ لَكُمُ ࡲ۬ليْلَ لِتَسْكُنُواْ فِيهِ وَالنَّهَارَ مُبْصِراً࣌ ࡴنَّ فِے ذَٰلِكَ لَأٓيَٰتࣲ لِّقَوْمࣲ يَسْمَعُونَ࣌', 'هو ࡰلذے جعل لكم ࡲليل لتسكنوا فيه والنهار مبصرا࣌ ࡴن فے ذلك لأيت لقوم يسمعون࣌', NULL, 216, 'local:warsh-text.json'),
  ('warsh-10-68', 'warsh', 10, 68, 'قَالُواْ ࡲٜتَّخَذَ ࡰ۬للَّهُ وَلَداࣰ࣌ سُبْحَٰنَهُۥ࣌ هُوَ ࡰ۬لْغَنِيُّ࣌ لَهُۥ مَا فِے ࡴ۬لسَّمَٰوَٰتِ وَمَا فِے ࡴ۬لَارْضِ࣌ إِنْ عِندَكُم مِّن سُلْطَٰنِۢ بِهَٰذَآ࣌ أَتَقُولُونَ عَلَى ࡰ۬للَّهِ مَا لَا تَعْلَمُونَ࣌', 'قالوا ࡲتخذ ࡰلله ولدا࣌ سبحنه࣌ هو ࡰلغني࣌ له ما فے ࡴلسموت وما فے ࡴلارض࣌ إن عندكم من سلطن بهذا࣌ أتقولون على ࡰلله ما لا تعلمون࣌', NULL, 216, 'local:warsh-text.json'),
  ('warsh-10-69', 'warsh', 10, 69, 'قُلِ ࡴنَّ ࡰ۬لذِينَ يَفْتَرُونَ عَلَى ࡰ۬للَّهِ ࡴ۬لْكَذِبَ لَا يُفْلِحُونَ࣌', 'قل ࡴن ࡰلذين يفترون على ࡰلله ࡴلكذب لا يفلحون࣌', NULL, 216, 'local:warsh-text.json'),
  ('warsh-10-70', 'warsh', 10, 70, 'مَتَٰعࣱ فِے ࡴ۬لدُّنْيٜا࣌ ثُمَّ إِلَيْنَا مَرْجِعُهُمْ ثُمَّ نُذِيقُهُمُ ࡲ۬لْعَذَابَ ࡰ۬لشَّدِيدَ بِمَا كَانُواْ يَكْفُرُونَ࣌', 'متع فے ࡴلدنيا࣌ ثم إلينا مرجعهم ثم نذيقهم ࡲلعذاب ࡰلشديد بما كانوا يكفرون࣌', NULL, 216, 'local:warsh-text.json'),
  ('warsh-10-71', 'warsh', 10, 71, '۞ وَاتْلُ عَلَيْهِمْ نَبَأَ نُوحٍ ࡴذْ قَالَ لِقَوْمِهِۦ يَٰقَوْمِ إِن كَانَ كَبُرَ عَلَيْكُم مَّقَامِے وَتَذْكِيرِے بِـَٔايَٰتِ ࡴ۬للَّهِ فَعَلَى ࡰ۬للَّهِ تَوَكَّلْتُ࣌ فَأَجْمِعُوٓاْ أَمْرَكُمْ وَشُرَكَآءَكُمْ࣌ ثُمَّ لَا يَكُنَ ࡰمْرُكُمْ عَلَيْكُمْ غُمَّةࣰ࣌ ثُمَّ ࡰٜقْضُوٓاْ إِلَيَّ وَلَا تُنظِرُونِ࣌', 'واتل عليهم نبأ نوح ࡴذ قال لقومه يقوم إن كان كبر عليكم مقامے وتذكيرے بايت ࡴلله فعلى ࡰلله توكلت࣌ فأجمعوا أمركم وشركاءكم࣌ ثم لا يكن ࡰمركم عليكم غمة࣌ ثم ࡰقضوا إلي ولا تنظرون࣌', NULL, 217, 'local:warsh-text.json'),
  ('warsh-10-72', 'warsh', 10, 72, 'فَإِن تَوَلَّيْتُمْ فَمَا سَأَلْتُكُم مِّنَ ࡰجْرٍ࣌ ࡴنَ ࡰجْرِيَ إِلَّا عَلَى ࡰ۬للَّهِ࣌ وَأُمِرْتُ أَنَ ࡰكُونَ مِنَ ࡰ۬لْمُسْلِمِينَ࣌', 'فإن توليتم فما سألتكم من ࡰجر࣌ ࡴن ࡰجري إلا على ࡰلله࣌ وأمرت أن ࡰكون من ࡰلمسلمين࣌', NULL, 217, 'local:warsh-text.json'),
  ('warsh-10-73', 'warsh', 10, 73, 'فَكَذَّبُوهُ فَنَجَّيْنَٰهُ وَمَن مَّعَهُۥ فِے ࡴ۬لْفُلْكِ وَجَعَلْنَٰهُمْ خَلَٰٓئِفَ࣌ وَأَغْرَقْنَا ࡰ۬لذِينَ كَذَّبُواْ بِـَٔايَٰتِنَا࣌ فَانظُرْ كَيْفَ كَانَ عَٰقِبَةُ ࡲ۬لْمُنذَرِينَ࣌', 'فكذبوه فنجينه ومن معه فے ࡴلفلك وجعلنهم خلئف࣌ وأغرقنا ࡰلذين كذبوا بايتنا࣌ فانظر كيف كان عقبة ࡲلمنذرين࣌', NULL, 217, 'local:warsh-text.json'),
  ('warsh-10-74', 'warsh', 10, 74, 'ثُمَّ بَعَثْنَا مِنۢ بَعْدِهِۦ رُسُلاً ࡴلَىٰ قَوْمِهِمْ فَجَآءُوهُم بِالْبَيِّنَٰتِ فَمَا كَانُواْ لِيُومِنُواْ بِمَا كَذَّبُواْ بِهِۦ مِن قَبْلُ࣌ كَذَٰلِكَ نَطْبَعُ عَلَىٰ قُلُوبِ ࡴ۬لْمُعْتَدِينَ࣌', 'ثم بعثنا من بعده رسلا ࡴلى قومهم فجاءوهم بالبينت فما كانوا ليومنوا بما كذبوا به من قبل࣌ كذلك نطبع على قلوب ࡴلمعتدين࣌', NULL, 217, 'local:warsh-text.json'),
  ('warsh-10-75', 'warsh', 10, 75, 'ثُمَّ بَعَثْنَا مِنۢ بَعْدِهِم مُّوسٜىٰ وَهَٰرُونَ إِلَىٰ فِرْعَوْنَ وَمَلَإِيْهِۦ بِـَٔايَٰتِنَا فَاسْتَكْبَرُواْ وَكَانُواْ قَوْماࣰ مُّجْرِمِينَ࣌', 'ثم بعثنا من بعدهم موسى وهرون إلى فرعون وملإيه بايتنا فاستكبروا وكانوا قوما مجرمين࣌', NULL, 217, 'local:warsh-text.json'),
  ('warsh-10-76', 'warsh', 10, 76, 'فَلَمَّا جَآءَهُمُ ࡲ۬لْحَقُّ مِنْ عِندِنَا قَالُوٓاْ إِنَّ هَٰذَا لَسِحْرࣱ مُّبِينࣱ࣌', 'فلما جاءهم ࡲلحق من عندنا قالوا إن هذا لسحر مبين࣌', NULL, 217, 'local:warsh-text.json'),
  ('warsh-10-77', 'warsh', 10, 77, 'قَالَ مُوسٜىٰٓ أَتَقُولُونَ لِلْحَقِّ لَمَّا جَآءَكُمُۥٓ࣌ أَسِحْرٌ هَٰذَا࣌ وَلَا يُفْلِحُ ࡲ۬لسَّٰحِرُونَ࣌', 'قال موسى أتقولون للحق لما جاءكم࣌ أسحر هذا࣌ ولا يفلح ࡲلسحرون࣌', NULL, 217, 'local:warsh-text.json'),
  ('warsh-10-78', 'warsh', 10, 78, 'قَالُوٓاْ أَجِئْتَنَا لِتَلْفِتَنَا عَمَّا وَجَدْنَا عَلَيْهِ ءَابَآءَنَا وَتَكُونَ لَكُمَا ࡰ۬لْكِبْرِيَآءُ فِے ࡴ۬لَارْضِ وَمَا نَحْنُ لَكُمَا بِمُومِنِينَ࣌', 'قالوا أجئتنا لتلفتنا عما وجدنا عليه ءاباءنا وتكون لكما ࡰلكبرياء فے ࡴلارض وما نحن لكما بمومنين࣌', NULL, 217, 'local:warsh-text.json'),
  ('warsh-10-79', 'warsh', 10, 79, 'وَقَالَ فِرْعَوْنُ ࡲٜيتُونِے بِكُلِّ سَٰحِرٍ عَلِيمࣲ࣌', 'وقال فرعون ࡲيتونے بكل سحر عليم࣌', NULL, 218, 'local:warsh-text.json'),
  ('warsh-10-80', 'warsh', 10, 80, 'فَلَمَّا جَآءَ ࡰ۬لسَّحَرَةُ قَالَ لَهُم مُّوسٜىٰٓ أَلْقُواْ مَآ أَنتُم مُّلْقُونَ࣌', 'فلما جاء ࡰلسحرة قال لهم موسى ألقوا ما أنتم ملقون࣌', NULL, 218, 'local:warsh-text.json'),
  ('warsh-10-81', 'warsh', 10, 81, 'فَلَمَّآ أَلْقَوْاْ قَالَ مُوسٜىٰ مَا جِئْتُم بِهِ ࡴ۬لسِّحْرُ࣌ إِنَّ ࡰ۬للَّهَ سَيُبْطِلُهُۥٓ࣌ إِنَّ ࡰ۬للَّهَ لَا يُصْلِحُ عَمَلَ ࡰ۬لْمُفْسِدِينَ࣌', 'فلما ألقوا قال موسى ما جئتم به ࡴلسحر࣌ إن ࡰلله سيبطله࣌ إن ࡰلله لا يصلح عمل ࡰلمفسدين࣌', NULL, 218, 'local:warsh-text.json'),
  ('warsh-10-82', 'warsh', 10, 82, 'وَيُحِقُّ ࡲ۬للَّهُ ࡲ۬لْحَقَّ بِكَلِمَٰتِهِۦ وَلَوْ كَرِهَ ࡰ۬لْمُجْرِمُونَ࣌', 'ويحق ࡲلله ࡲلحق بكلمته ولو كره ࡰلمجرمون࣌', NULL, 218, 'local:warsh-text.json'),
  ('warsh-10-83', 'warsh', 10, 83, '۞ فَمَآ ءَامَنَ لِمُوسٜىٰٓ إِلَّا ذُرِّيَّةࣱ مِّن قَوْمِهِۦ عَلَىٰ خَوْفࣲ مِّن فِرْعَوْنَ وَمَلَإِيْهِمُۥٓ أَنْ يَّفْتِنَهُمْ࣌ وَإِنَّ فِرْعَوْنَ لَعَالࣲ فِے ࡴ۬لَارْضِ࣌ وَإِنَّهُۥ لَمِنَ ࡰ۬لْمُسْرِفِينَ࣌', 'فما ءامن لموسى إلا ذرية من قومه على خوف من فرعون وملإيهم أن يفتنهم࣌ وإن فرعون لعال فے ࡴلارض࣌ وإنه لمن ࡰلمسرفين࣌', NULL, 218, 'local:warsh-text.json'),
  ('warsh-10-84', 'warsh', 10, 84, 'وَقَالَ مُوسٜىٰ يَٰقَوْمِ إِن كُنتُمُۥٓ ءَامَنتُم بِاللَّهِ فَعَلَيْهِ تَوَكَّلُوٓاْ إِن كُنتُم مُّسْلِمِينَ࣌', 'وقال موسى يقوم إن كنتم ءامنتم بالله فعليه توكلوا إن كنتم مسلمين࣌', NULL, 218, 'local:warsh-text.json'),
  ('warsh-10-85', 'warsh', 10, 85, 'فَقَالُواْ عَلَى ࡰ۬للَّهِ تَوَكَّلْنَا࣌ رَبَّنَا لَا تَجْعَلْنَا فِتْنَةࣰ لِّلْقَوْمِ ࡴ۬لظَّٰلِمِينَ࣌', 'فقالوا على ࡰلله توكلنا࣌ ربنا لا تجعلنا فتنة للقوم ࡴلظلمين࣌', NULL, 218, 'local:warsh-text.json'),
  ('warsh-10-86', 'warsh', 10, 86, 'وَنَجِّنَا بِرَحْمَتِكَ مِنَ ࡰ۬لْقَوْمِ ࡴ۬لْكٜـٰفِرِينَ࣌', 'ونجنا برحمتك من ࡰلقوم ࡴلكفرين࣌', NULL, 218, 'local:warsh-text.json'),
  ('warsh-10-87', 'warsh', 10, 87, 'وَأَوْحَيْنَآ إِلَىٰ مُوسٜىٰ وَأَخِيهِ أَن تَبَوَّءَا لِقَوْمِكُمَا بِمِصْرَ بُيُوتاࣰ وَاجْعَلُواْ بُيُوتَكُمْ قِبْلَةࣰ وَأَقِيمُواْ ࡲ۬لصَّلَوٰةَ࣌ وَبَشِّرِ ࡴ۬لْمُومِنِينَ࣌', 'وأوحينا إلى موسى وأخيه أن تبوءا لقومكما بمصر بيوتا واجعلوا بيوتكم قبلة وأقيموا ࡲلصلوة࣌ وبشر ࡴلمومنين࣌', NULL, 218, 'local:warsh-text.json'),
  ('warsh-10-88', 'warsh', 10, 88, 'وَقَالَ مُوسٜىٰ رَبَّنَآ إِنَّكَ ءَاتَيْتَ فِرْعَوْنَ وَمَلَأَهُۥ زِينَةࣰ وَأَمْوَٰلاࣰ فِے ࡴ۬لْحَيَوٰةِ ࡴ۬لدُّنْيٜا࣌ رَبَّنَا لِيَضِلُّواْ عَن سَبِيلِكَ࣌ رَبَّنَا ࡰٜطْمِسْ عَلَىٰٓ أَمْوَٰلِهِمْ وَاشْدُدْ عَلَىٰ قُلُوبِهِمْ فَلَا يُومِنُواْ حَتَّىٰ يَرَوُاْ ࡲ۬لْعَذَابَ ࡰ۬لَالِيمَ࣌', 'وقال موسى ربنا إنك ءاتيت فرعون وملأه زينة وأمولا فے ࡴلحيوة ࡴلدنيا࣌ ربنا ليضلوا عن سبيلك࣌ ربنا ࡰطمس على أمولهم واشدد على قلوبهم فلا يومنوا حتى يروا ࡲلعذاب ࡰلاليم࣌', NULL, 218, 'local:warsh-text.json'),
  ('warsh-10-89', 'warsh', 10, 89, 'قَالَ قَدُ ࡳجِيبَت دَّعْوَتُكُمَا فَاسْتَقِيمَا࣌ وَلَا تَتَّبِعَٰٓنِّ سَبِيلَ ࡰ۬لذِينَ لَا يَعْلَمُونَ࣌', 'قال قد ࡳجيبت دعوتكما فاستقيما࣌ ولا تتبعن سبيل ࡰلذين لا يعلمون࣌', NULL, 219, 'local:warsh-text.json'),
  ('warsh-10-90', 'warsh', 10, 90, 'وَجَٰوَزْنَا بِبَنِےٓ إِسْرَآءِيلَ ࡰ۬لْبَحْرَ فَأَتْبَعَهُمْ فِرْعَوْنُ وَجُنُودُهُۥ بَغْياࣰ وَعَدْواً࣌ حَتَّىٰٓ إِذَآ أَدْرَكَهُ ࡲ۬لْغَرَقُ قَالَ ءَامَنتُ أَنَّهُۥ لَآ إِلَٰهَ إِلَّا ࡰ۬لذِےٓ ءَامَنَتْ بِهِۦ بَنُوٓاْ إِسْرَآءِيلَ وَأَنَا مِنَ ࡰ۬لْمُسْلِمِينَ࣌', 'وجوزنا ببنے إسراءيل ࡰلبحر فأتبعهم فرعون وجنوده بغيا وعدوا࣌ حتى إذا أدركه ࡲلغرق قال ءامنت أنه لا إله إلا ࡰلذے ءامنت به بنوا إسراءيل وأنا من ࡰلمسلمين࣌', NULL, 219, 'local:warsh-text.json'),
  ('warsh-10-91', 'warsh', 10, 91, 'ءَالَٰنَ وَقَدْ عَصَيْتَ قَبْلُ وَكُنتَ مِنَ ࡰ۬لْمُفْسِدِينَ࣌', 'ءالن وقد عصيت قبل وكنت من ࡰلمفسدين࣌', NULL, 219, 'local:warsh-text.json'),
  ('warsh-10-92', 'warsh', 10, 92, 'فَالْيَوْمَ نُنَجِّيكَ بِبَدَنِكَ لِتَكُونَ لِمَنْ خَلْفَكَ ءَايَةࣰ࣌ وَإِنَّ كَثِيراࣰ مِّنَ ࡰ۬لنَّاسِ عَنَ اٰيَٰتِنَا لَغَٰفِلُونَ࣌', 'فاليوم ننجيك ببدنك لتكون لمن خلفك ءاية࣌ وإن كثيرا من ࡰلناس عن ايتنا لغفلون࣌', NULL, 219, 'local:warsh-text.json'),
  ('warsh-10-93', 'warsh', 10, 93, '۞ وَلَقَدْ بَوَّأْنَا بَنِےٓ إِسْرَآءِيلَ مُبَوَّأَ صِدْقࣲ وَرَزَقْنَٰهُم مِّنَ ࡰ۬لطَّيِّبَٰتِ فَمَا ࡰٜخْتَلَفُواْ حَتَّىٰ جَآءَهُمُ ࡲ۬لْعِلْمُ࣌ إِنَّ رَبَّكَ يَقْضِے بَيْنَهُمْ يَوْمَ ࡰ۬لْقِيَٰمَةِ فِيمَا كَانُواْ فِيهِ يَخْتَلِفُونَ࣌', 'ولقد بوأنا بنے إسراءيل مبوأ صدق ورزقنهم من ࡰلطيبت فما ࡰختلفوا حتى جاءهم ࡲلعلم࣌ إن ربك يقضے بينهم يوم ࡰلقيمة فيما كانوا فيه يختلفون࣌', NULL, 219, 'local:warsh-text.json'),
  ('warsh-10-94', 'warsh', 10, 94, 'فَإِن كُنتَ فِے شَكࣲّ مِّمَّآ أَنزَلْنَآ إِلَيْكَ فَسْـَٔلِ ࡴ۬لذِينَ يَقْرَءُونَ ࡰ۬لْكِتَٰبَ مِن قَبْلِكَ࣌ لَقَدْ جَآءَكَ ࡰ۬لْحَقُّ مِن رَّبِّكَ࣌ فَلَا تَكُونَنَّ مِنَ ࡰ۬لْمُمْتَرِينَ࣌', 'فإن كنت فے شك مما أنزلنا إليك فسل ࡴلذين يقرءون ࡰلكتب من قبلك࣌ لقد جاءك ࡰلحق من ربك࣌ فلا تكونن من ࡰلممترين࣌', NULL, 219, 'local:warsh-text.json'),
  ('warsh-10-95', 'warsh', 10, 95, 'وَلَا تَكُونَنَّ مِنَ ࡰ۬لذِينَ كَذَّبُواْ بِـَٔايَٰتِ ࡴ۬للَّهِ فَتَكُونَ مِنَ ࡰ۬لْخَٰسِرِينَ࣌', 'ولا تكونن من ࡰلذين كذبوا بايت ࡴلله فتكون من ࡰلخسرين࣌', NULL, 219, 'local:warsh-text.json'),
  ('warsh-10-96', 'warsh', 10, 96, 'إِنَّ ࡰ۬لذِينَ حَقَّتْ عَلَيْهِمْ كَلِمَٰتُ رَبِّكَ لَا يُومِنُونَ', 'إن ࡰلذين حقت عليهم كلمت ربك لا يومنون', NULL, 219, 'local:warsh-text.json'),
  ('warsh-10-97', 'warsh', 10, 97, 'وَلَوْ جَآءَتْهُمْ كُلُّ ءَايَةٍ حَتَّىٰ يَرَوُاْ ࡲ۬لْعَذَابَ ࡰ۬لَالِيمَ࣌', 'ولو جاءتهم كل ءاية حتى يروا ࡲلعذاب ࡰلاليم࣌', NULL, 219, 'local:warsh-text.json'),
  ('warsh-10-98', 'warsh', 10, 98, 'فَلَوْلَا كَانَتْ قَرْيَةٌ اٰمَنَتْ فَنَفَعَهَآ إِيمَٰنُهَآ إِلَّا قَوْمَ يُونُسَ لَمَّآ ءَامَنُواْ كَشَفْنَا عَنْهُمْ عَذَابَ ࡰ۬لْخِزْيِ فِے ࡴ۬لْحَيَوٰةِ ࡴ۬لدُّنْيٜا وَمَتَّعْنَٰهُمُۥٓ إِلَىٰ حِينࣲ࣌', 'فلولا كانت قرية امنت فنفعها إيمنها إلا قوم يونس لما ءامنوا كشفنا عنهم عذاب ࡰلخزي فے ࡴلحيوة ࡴلدنيا ومتعنهم إلى حين࣌', NULL, 220, 'local:warsh-text.json'),
  ('warsh-10-99', 'warsh', 10, 99, 'وَلَوْ شَآءَ رَبُّكَ لَأٓمَنَ مَن فِے ࡴ۬لَارْضِ كُلُّهُمْ جَمِيعاً࣌ ࡰفَأَنتَ تُكْرِهُ ࡲ۬لنَّاسَ حَتَّىٰ يَكُونُواْ مُومِنِينَ࣌', 'ولو شاء ربك لأمن من فے ࡴلارض كلهم جميعا࣌ ࡰفأنت تكره ࡲلناس حتى يكونوا مومنين࣌', NULL, 220, 'local:warsh-text.json'),
  ('warsh-10-100', 'warsh', 10, 100, 'وَمَا كَانَ لِنَفْسٍ ࡰن تُومِنَ إِلَّا بِإِذْنِ ࡴ۬للَّهِ࣌ وَيَجْعَلُ ࡲ۬لرِّجْسَ عَلَى ࡰ۬لذِينَ لَا يَعْقِلُونَ࣌', 'وما كان لنفس ࡰن تومن إلا بإذن ࡴلله࣌ ويجعل ࡲلرجس على ࡰلذين لا يعقلون࣌', NULL, 220, 'local:warsh-text.json'),
  ('warsh-10-101', 'warsh', 10, 101, 'قُلُ ࡲ࢈نظُرُواْ مَاذَا فِے ࡴ۬لسَّمَٰوَٰتِ وَالَارْضِ وَمَا تُغْنِے ࡴ۬لَايَٰتُ وَالنُّذُرُ عَن قَوْمࣲ لَّا يُومِنُونَ࣌', 'قل ࡲ࢈نظروا ماذا فے ࡴلسموت والارض وما تغنے ࡴلايت والنذر عن قوم لا يومنون࣌', NULL, 220, 'local:warsh-text.json'),
  ('warsh-10-102', 'warsh', 10, 102, 'فَهَلْ يَنتَظِرُونَ إِلَّا مِثْلَ أَيَّامِ ࡴ۬لذِينَ خَلَوْاْ مِن قَبْلِهِمْ࣌ قُلْ فَانتَظِرُوٓاْ࣌ إِنِّے مَعَكُم مِّنَ ࡰ۬لْمُنتَظِرِينَ࣌', 'فهل ينتظرون إلا مثل أيام ࡴلذين خلوا من قبلهم࣌ قل فانتظروا࣌ إنے معكم من ࡰلمنتظرين࣌', NULL, 220, 'local:warsh-text.json'),
  ('warsh-10-103', 'warsh', 10, 103, 'ثُمَّ نُنَجِّے رُسُلَنَا وَالذِينَ ءَامَنُواْ كَذَٰلِكَ࣌ حَقّاً عَلَيْنَا نُنَجِّ ࡴ۬لْمُومِنِينَ࣌', 'ثم ننجے رسلنا والذين ءامنوا كذلك࣌ حقا علينا ننج ࡴلمومنين࣌', NULL, 220, 'local:warsh-text.json'),
  ('warsh-10-104', 'warsh', 10, 104, '۞ قُلْ يَٰٓأَيُّهَا ࡰ۬لنَّاسُ إِن كُنتُمْ فِے شَكࣲّ مِّن دِينِے فَلَآ أَعْبُدُ ࡲ۬لذِينَ تَعْبُدُونَ مِن دُونِ ࡴ۬للَّهِ࣌ وَلَٰكِنَ ࡰعْبُدُ ࡲ۬للَّهَ ࡰ۬لذِے يَتَوَفّٜيٰكُمْ࣌ وَأُمِرْتُ أَنَ ࡰكُونَ مِنَ ࡰ۬لْمُومِنِينَ', 'قل يأيها ࡰلناس إن كنتم فے شك من دينے فلا أعبد ࡲلذين تعبدون من دون ࡴلله࣌ ولكن ࡰعبد ࡲلله ࡰلذے يتوفيكم࣌ وأمرت أن ࡰكون من ࡰلمومنين', NULL, 220, 'local:warsh-text.json'),
  ('warsh-10-105', 'warsh', 10, 105, 'وَأَنَ ࡰقِمْ وَجْهَكَ لِلدِّينِ حَنِيفاࣰ࣌ وَلَا تَكُونَنَّ مِنَ ࡰ۬لْمُشْرِكِينَ࣌', 'وأن ࡰقم وجهك للدين حنيفا࣌ ولا تكونن من ࡰلمشركين࣌', NULL, 220, 'local:warsh-text.json'),
  ('warsh-10-106', 'warsh', 10, 106, 'وَلَا تَدْعُ مِن دُونِ ࡴ۬للَّهِ مَا لَا يَنفَعُكَ وَلَا يَضُرُّكَ࣌ فَإِن فَعَلْتَ فَإِنَّكَ إِذاࣰ مِّنَ ࡰ۬لظَّٰلِمِينَ࣌', 'ولا تدع من دون ࡴلله ما لا ينفعك ولا يضرك࣌ فإن فعلت فإنك إذا من ࡰلظلمين࣌', NULL, 220, 'local:warsh-text.json'),
  ('warsh-10-107', 'warsh', 10, 107, 'وَإِنْ يَّمْسَسْكَ ࡰ۬للَّهُ بِضُرࣲّ فَلَا كَاشِفَ لَهُۥٓ إِلَّا هُوَ࣌ وَإِنْ يُّرِدْكَ بِخَيْرࣲ فَلَا رَآدَّ لِفَضْلِهِۦ࣌ يُصِيبُ بِهِۦ مَنْ يَّشَآءُ مِنْ عِبَادِهِۦ࣌ وَهُوَ ࡰ۬لْغَفُورُ ࡲ۬لرَّحِيمُ࣌', 'وإن يمسسك ࡰلله بضر فلا كاشف له إلا هو࣌ وإن يردك بخير فلا راد لفضله࣌ يصيب به من يشاء من عباده࣌ وهو ࡰلغفور ࡲلرحيم࣌', NULL, 221, 'local:warsh-text.json'),
  ('warsh-10-108', 'warsh', 10, 108, 'قُلْ يَٰٓأَيُّهَا ࡰ۬لنَّاسُ قَدْ جَآءَكُمُ ࡲ۬لْحَقُّ مِن رَّبِّكُمْ࣌ فَمَنِ ࡴٜهْتَدٜىٰ فَإِنَّمَا يَهْتَدِے لِنَفْسِهِۦ࣌ وَمَن ضَلَّ فَإِنَّمَا يَضِلُّ عَلَيْهَا࣌ وَمَآ أَنَا عَلَيْكُم بِوَكِيلࣲ࣌', 'قل يأيها ࡰلناس قد جاءكم ࡲلحق من ربكم࣌ فمن ࡴهتدى فإنما يهتدے لنفسه࣌ ومن ضل فإنما يضل عليها࣌ وما أنا عليكم بوكيل࣌', NULL, 221, 'local:warsh-text.json'),
  ('warsh-10-109', 'warsh', 10, 109, 'وَاتَّبِعْ مَا يُوحٜىٰٓ إِلَيْكَ وَاصْبِرْ حَتَّىٰ يَحْكُمَ ࡰ۬للَّهُ࣌ وَهُوَ خَيْرُ ࡲ۬لْحَٰكِمِينَ࣌', 'واتبع ما يوحى إليك واصبر حتى يحكم ࡰلله࣌ وهو خير ࡲلحكمين࣌', NULL, 221, 'local:warsh-text.json'),
  ('warsh-11-1', 'warsh', 11, 1, 'أَلَٓرٜ࣌ كِتَٰبٌ ࡳحْكِمَتَ اٰيَٰتُهُۥ ثُمَّ فُصِّلَتْ مِن لَّدُنْ حَكِيمٍ خَبِيرٍ', 'ألر࣌ كتب ࡳحكمت ايته ثم فصلت من لدن حكيم خبير', NULL, 221, 'local:warsh-text.json'),
  ('warsh-11-2', 'warsh', 11, 2, 'ࡰلَّا تَعْبُدُوٓاْ إِلَّا ࡰ۬للَّهَ إِنَّنِے لَكُم مِّنْهُ نَذِيرࣱ وَبَشِيرࣱ', 'ࡰلا تعبدوا إلا ࡰلله إننے لكم منه نذير وبشير', NULL, 221, 'local:warsh-text.json'),
  ('warsh-11-3', 'warsh', 11, 3, 'وَأَنِ ࡴٜسْتَغْفِرُواْ رَبَّكُمْ ثُمَّ تُوبُوٓاْ إِلَيْهِ يُمَتِّعْكُم مَّتَٰعاً حَسَناً ࡴلَىٰٓ أَجَلࣲ مُّسَمّىࣰ وَيُوتِ كُلَّ ذِے فَضْلࣲ فَضْلَهُۥ࣌ وَإِن تَوَلَّوْاْ فَإِنِّيَ أَخَافُ عَلَيْكُمْ عَذَابَ يَوْمࣲ كَبِيرٍ࣌', 'وأن ࡴستغفروا ربكم ثم توبوا إليه يمتعكم متعا حسنا ࡴلى أجل مسمى ويوت كل ذے فضل فضله࣌ وإن تولوا فإني أخاف عليكم عذاب يوم كبير࣌', NULL, 221, 'local:warsh-text.json'),
  ('warsh-11-4', 'warsh', 11, 4, 'ࡴلَى ࡰ۬للَّهِ مَرْجِعُكُمْ࣌ وَهُوَ عَلَىٰ كُلِّ شَےْءࣲ قَدِيرٌ࣌', 'ࡴلى ࡰلله مرجعكم࣌ وهو على كل شےء قدير࣌', NULL, 221, 'local:warsh-text.json'),
  ('warsh-11-5', 'warsh', 11, 5, 'ࡰلَآ إِنَّهُمْ يَثْنُونَ صُدُورَهُمْ لِيَسْتَخْفُواْ مِنْهُ࣌ أَلَا حِينَ يَسْتَغْشُونَ ثِيَابَهُمْ يَعْلَمُ مَا يُسِرُّونَ وَمَا يُعْلِنُونَ࣌ إِنَّهُۥ عَلِيمُۢ بِذَاتِ ࡴ۬لصُّدُورِ࣌', 'ࡰلا إنهم يثنون صدورهم ليستخفوا منه࣌ ألا حين يستغشون ثيابهم يعلم ما يسرون وما يعلنون࣌ إنه عليم بذات ࡴلصدور࣌', NULL, 221, 'local:warsh-text.json'),
  ('warsh-11-6', 'warsh', 11, 6, '۞ وَمَا مِن دَآبَّةࣲ فِے ࡴ۬لَارْضِ إِلَّا عَلَى ࡰ۬للَّهِ رِزْقُهَا وَيَعْلَمُ مُسْتَقَرَّهَا وَمُسْتَوْدَعَهَا࣌ كُلࣱّ فِے كِتَٰبࣲ مُّبِينࣲ࣌', 'وما من دابة فے ࡴلارض إلا على ࡰلله رزقها ويعلم مستقرها ومستودعها࣌ كل فے كتب مبين࣌', NULL, 222, 'local:warsh-text.json'),
  ('warsh-11-7', 'warsh', 11, 7, 'وَهُوَ ࡰ۬لذِے خَلَقَ ࡰ۬لسَّمَٰوَٰتِ وَالَارْضَ فِے سِتَّةِ أَيَّامࣲ وَكَانَ عَرْشُهُۥ عَلَى ࡰ۬لْمَآءِ لِيَبْلُوَكُمُۥٓ أَيُّكُمُۥٓ أَحْسَنُ عَمَلاࣰ࣌ وَلَئِن قُلْتَ إِنَّكُم مَّبْعُوثُونَ مِنۢ بَعْدِ ࡴ۬لْمَوْتِ لَيَقُولَنَّ ࡰ۬لذِينَ كَفَرُوٓاْ إِنْ هَٰذَآ إِلَّا سِحْرࣱ مُّبِينࣱ࣌', 'وهو ࡰلذے خلق ࡰلسموت والارض فے ستة أيام وكان عرشه على ࡰلماء ليبلوكم أيكم أحسن عملا࣌ ولئن قلت إنكم مبعوثون من بعد ࡴلموت ليقولن ࡰلذين كفروا إن هذا إلا سحر مبين࣌', NULL, 222, 'local:warsh-text.json'),
  ('warsh-11-8', 'warsh', 11, 8, 'وَلَئِنَ ࡰخَّرْنَا عَنْهُمُ ࡲ۬لْعَذَابَ إِلَىٰٓ أُمَّةࣲ مَّعْدُودَةࣲ لَّيَقُولُنَّ مَا يَحْبِسُهُۥٓ࣌ أَلَا يَوْمَ يَاتِيهِمْ لَيْسَ مَصْرُوفاً عَنْهُمْ࣌ وَحَاقَ بِهِم مَّا كَانُواْ بِهِۦ يَسْتَهْزِءُونَ࣌', 'ولئن ࡰخرنا عنهم ࡲلعذاب إلى أمة معدودة ليقولن ما يحبسه࣌ ألا يوم ياتيهم ليس مصروفا عنهم࣌ وحاق بهم ما كانوا به يستهزءون࣌', NULL, 222, 'local:warsh-text.json'),
  ('warsh-11-9', 'warsh', 11, 9, 'وَلَئِنَ ࡰذَقْنَا ࡰ۬لِانسَٰنَ مِنَّا رَحْمَةࣰ ثُمَّ نَزَعْنَٰهَا مِنْهُ إِنَّهُۥ لَيَـُٔوسࣱ كَفُورࣱ࣌', 'ولئن ࡰذقنا ࡰلانسن منا رحمة ثم نزعنها منه إنه ليوس كفور࣌', NULL, 222, 'local:warsh-text.json'),
  ('warsh-11-10', 'warsh', 11, 10, 'وَلَئِنَ ࡰذَقْنَٰهُ نَعْمَآءَ بَعْدَ ضَرَّآءَ مَسَّتْهُ لَيَقُولَنَّ ذَهَبَ ࡰ۬لسَّيِّـَٔاتُ عَنِّيَ࣌ إِنَّهُۥ لَفَرِحࣱ فَخُورٌ࣌', 'ولئن ࡰذقنه نعماء بعد ضراء مسته ليقولن ذهب ࡰلسيات عني࣌ إنه لفرح فخور࣌', NULL, 222, 'local:warsh-text.json'),
  ('warsh-11-11', 'warsh', 11, 11, 'ࡴلَّا ࡰ۬لذِينَ صَبَرُواْ وَعَمِلُواْ ࡲ۬لصَّٰلِحَٰتِ أُوْلَٰٓئِكَ لَهُم مَّغْفِرَةࣱ وَأَجْرࣱ كَبِيرࣱ࣌', 'ࡴلا ࡰلذين صبروا وعملوا ࡲلصلحت أولئك لهم مغفرة وأجر كبير࣌', NULL, 222, 'local:warsh-text.json'),
  ('warsh-11-12', 'warsh', 11, 12, 'فَلَعَلَّكَ تَارِكُۢ بَعْضَ مَا يُوحٜىٰٓ إِلَيْكَ وَضَآئِقُۢ بِهِۦ صَدْرُكَ أَنْ يَّقُولُواْ لَوْلَآ أُنزِلَ عَلَيْهِ كَنزٌ ࡰوْ جَآءَ مَعَهُۥ مَلَكٌ࣌ ࡴنَّمَآ أَنتَ نَذِيرࣱ࣌ وَاللَّهُ عَلَىٰ كُلِّ شَےْءࣲ وَكِيلٌ࣌', 'فلعلك تارك بعض ما يوحى إليك وضائق به صدرك أن يقولوا لولا أنزل عليه كنز ࡰو جاء معه ملك࣌ ࡴنما أنت نذير࣌ والله على كل شےء وكيل࣌', NULL, 222, 'local:warsh-text.json'),
  ('warsh-11-13', 'warsh', 11, 13, 'ࡰمْ يَقُولُونَ ࡰٜفْتَرٜيٰهُ࣌ قُلْ فَاتُواْ بِعَشْرِ سُوَرࣲ مِّثْلِهِۦ مُفْتَرَيَٰتࣲ وَادْعُواْ مَنِ ࡴٜسْتَطَعْتُم مِّن دُونِ ࡴ۬للَّهِ إِن كُنتُمْ صَٰدِقِينَ࣌', 'ࡰم يقولون ࡰفتريه࣌ قل فاتوا بعشر سور مثله مفتريت وادعوا من ࡴستطعتم من دون ࡴلله إن كنتم صدقين࣌', NULL, 223, 'local:warsh-text.json'),
  ('warsh-11-14', 'warsh', 11, 14, 'فَإِلَّمْ يَسْتَجِيبُواْ لَكُمْ فَاعْلَمُوٓاْ أَنَّمَآ أُنزِلَ بِعِلْمِ ࡴ۬للَّهِ وَأَن لَّآ إِلَٰهَ إِلَّا هُوَ࣌ فَهَلَ ࡰنتُم مُّسْلِمُونَ࣌', 'فإلم يستجيبوا لكم فاعلموا أنما أنزل بعلم ࡴلله وأن لا إله إلا هو࣌ فهل ࡰنتم مسلمون࣌', NULL, 223, 'local:warsh-text.json'),
  ('warsh-11-15', 'warsh', 11, 15, '۞ مَن كَانَ يُرِيدُ ࡲ۬لْحَيَوٰةَ ࡰ۬لدُّنْيٜا وَزِينَتَهَا نُوَفِّ إِلَيْهِمُۥٓ أَعْمَٰلَهُمْ فِيهَا وَهُمْ فِيهَا لَا يُبْخَسُونَ࣌', 'من كان يريد ࡲلحيوة ࡰلدنيا وزينتها نوف إليهم أعملهم فيها وهم فيها لا يبخسون࣌', NULL, 223, 'local:warsh-text.json'),
  ('warsh-11-16', 'warsh', 11, 16, 'أُوْلَٰٓئِكَ ࡰ۬لذِينَ لَيْسَ لَهُمْ فِے ࡴ۬لَاخِرَةِ إِلَّا ࡰ۬لنَّارُ࣌ وَحَبِطَ مَا صَنَعُواْ فِيهَا࣌ وَبَٰطِلࣱ مَّا كَانُواْ يَعْمَلُونَ࣌', 'أولئك ࡰلذين ليس لهم فے ࡴلاخرة إلا ࡰلنار࣌ وحبط ما صنعوا فيها࣌ وبطل ما كانوا يعملون࣌', NULL, 223, 'local:warsh-text.json'),
  ('warsh-11-17', 'warsh', 11, 17, 'أَفَمَن كَانَ عَلَىٰ بَيِّنَةࣲ مِّن رَّبِّهِۦ وَيَتْلُوهُ شَاهِدࣱ مِّنْهُ࣌ وَمِن قَبْلِهِۦ كِتَٰبُ مُوسٜىٰٓ إِمَاماࣰ وَرَحْمَةً࣌ ࡳوْلَٰٓئِكَ يُومِنُونَ بِهِۦ࣌ وَمَنْ يَّكْفُرْ بِهِۦ مِنَ ࡰ۬لَاحْزَابِ فَالنَّارُ مَوْعِدُهُۥ࣌ فَلَا تَكُ فِے مِرْيَةࣲ مِّنْهُ࣌ إِنَّهُ ࡲ۬لْحَقُّ مِن رَّبِّكَ࣌ وَلَٰكِنَّ أَكْثَرَ ࡰ۬لنَّاسِ لَا يُومِنُونَ࣌', 'أفمن كان على بينة من ربه ويتلوه شاهد منه࣌ ومن قبله كتب موسى إماما ورحمة࣌ ࡳولئك يومنون به࣌ ومن يكفر به من ࡰلاحزاب فالنار موعده࣌ فلا تك فے مرية منه࣌ إنه ࡲلحق من ربك࣌ ولكن أكثر ࡰلناس لا يومنون࣌', NULL, 223, 'local:warsh-text.json'),
  ('warsh-11-18', 'warsh', 11, 18, 'وَمَنَ ࡰظْلَمُ مِمَّنِ ࡴٜفْتَرٜىٰ عَلَى ࡰ۬للَّهِ كَذِباً࣌ ࡳوْلَٰٓئِكَ يُعْرَضُونَ عَلَىٰ رَبِّهِمْ وَيَقُولُ ࡲ۬لَاشْهَٰدُ هَٰٓؤُلَآءِ ࡴ۬لذِينَ كَذَبُواْ عَلَىٰ رَبِّهِمُۥٓ࣌ أَلَا لَعْنَةُ ࡲ۬للَّهِ عَلَى ࡰ۬لظَّٰلِمِينَ', 'ومن ࡰظلم ممن ࡴفترى على ࡰلله كذبا࣌ ࡳولئك يعرضون على ربهم ويقول ࡲلاشهد هؤلاء ࡴلذين كذبوا على ربهم࣌ ألا لعنة ࡲلله على ࡰلظلمين', NULL, 223, 'local:warsh-text.json'),
  ('warsh-11-19', 'warsh', 11, 19, 'ࡰ۬لذِينَ يَصُدُّونَ عَن سَبِيلِ ࡴ۬للَّهِ وَيَبْغُونَهَا عِوَجاࣰ وَهُم بِالَاخِرَةِ هُمْ كَٰفِرُونَ࣌', 'ࡰلذين يصدون عن سبيل ࡴلله ويبغونها عوجا وهم بالاخرة هم كفرون࣌', NULL, 223, 'local:warsh-text.json'),
  ('warsh-11-20', 'warsh', 11, 20, 'أُوْلَٰٓئِكَ لَمْ يَكُونُواْ مُعْجِزِينَ فِے ࡴ۬لَارْضِ وَمَا كَانَ لَهُم مِّن دُونِ ࡴ۬للَّهِ مِنَ ࡰوْلِيَآءَ࣌ يُضَٰعَفُ لَهُمُ ࡲ۬لْعَذَابُ࣌ مَا كَانُواْ يَسْتَطِيعُونَ ࡰ۬لسَّمْعَ وَمَا كَانُواْ يُبْصِرُونَ࣌', 'أولئك لم يكونوا معجزين فے ࡴلارض وما كان لهم من دون ࡴلله من ࡰولياء࣌ يضعف لهم ࡲلعذاب࣌ ما كانوا يستطيعون ࡰلسمع وما كانوا يبصرون࣌', NULL, 224, 'local:warsh-text.json'),
  ('warsh-11-21', 'warsh', 11, 21, 'أُوْلَٰٓئِكَ ࡰ۬لذِينَ خَسِرُوٓاْ أَنفُسَهُمْ وَضَلَّ عَنْهُم مَّا كَانُواْ يَفْتَرُونَ࣌', 'أولئك ࡰلذين خسروا أنفسهم وضل عنهم ما كانوا يفترون࣌', NULL, 224, 'local:warsh-text.json'),
  ('warsh-11-22', 'warsh', 11, 22, 'لَا جَرَمَ أَنَّهُمْ فِے ࡴ۬لَاخِرَةِ هُمُ ࡲ۬لَاخْسَرُونَ࣌', 'لا جرم أنهم فے ࡴلاخرة هم ࡲلاخسرون࣌', NULL, 224, 'local:warsh-text.json'),
  ('warsh-11-23', 'warsh', 11, 23, 'إِنَّ ࡰ۬لذِينَ ءَامَنُواْ وَعَمِلُواْ ࡲ۬لصَّٰلِحَٰتِ وَأَخْبَتُوٓاْ إِلَىٰ رَبِّهِمُۥٓ أُوْلَٰٓئِكَ أَصْحَٰبُ ࡲ۬لْجَنَّةِ࣌ هُمْ فِيهَا خَٰلِدُونَ࣌', 'إن ࡰلذين ءامنوا وعملوا ࡲلصلحت وأخبتوا إلى ربهم أولئك أصحب ࡲلجنة࣌ هم فيها خلدون࣌', NULL, 224, 'local:warsh-text.json'),
  ('warsh-11-24', 'warsh', 11, 24, '۞ مَثَلُ ࡲ۬لْفَرِيقَيْنِ كَالَاعْمٜىٰ وَالَاصَمِّ وَالْبَصِيرِ وَالسَّمِيعِ࣌ هَلْ يَسْتَوِيَٰنِ مَثَلاً࣌ ࡰفَلَا تَذَّكَّرُونَ࣌', 'مثل ࡲلفريقين كالاعمى والاصم والبصير والسميع࣌ هل يستوين مثلا࣌ ࡰفلا تذكرون࣌', NULL, 224, 'local:warsh-text.json'),
  ('warsh-11-25', 'warsh', 11, 25, 'وَلَقَدَ ࡰرْسَلْنَا نُوحاً ࡴلَىٰ قَوْمِهِۦٓ࣌ إِنِّے لَكُمْ نَذِيرࣱ مُّبِينٌ', 'ولقد ࡰرسلنا نوحا ࡴلى قومه࣌ إنے لكم نذير مبين', NULL, 224, 'local:warsh-text.json'),
  ('warsh-11-26', 'warsh', 11, 26, 'ࡰن لَّا تَعْبُدُوٓاْ إِلَّا ࡰ۬للَّهَ࣌ إِنِّيَ أَخَافُ عَلَيْكُمْ عَذَابَ يَوْمٍ ࡰلِيمࣲ࣌', 'ࡰن لا تعبدوا إلا ࡰلله࣌ إني أخاف عليكم عذاب يوم ࡰليم࣌', NULL, 224, 'local:warsh-text.json'),
  ('warsh-11-27', 'warsh', 11, 27, 'فَقَالَ ࡰ۬لْمَلَأُ ࡲ۬لذِينَ كَفَرُواْ مِن قَوْمِهِۦ مَا نَرٜيٰكَ إِلَّا بَشَراࣰ مِّثْلَنَا وَمَا نَرٜيٰكَ ࡰٜتَّبَعَكَ إِلَّا ࡰ۬لذِينَ هُمُۥٓ أَرَاذِلُنَا بَادِيَ ࡰ۬لرَّأْيِ࣌ وَمَا نَرٜىٰ لَكُمْ عَلَيْنَا مِن فَضْلِۢ بَلْ نَظُنُّكُمْ كَٰذِبِينَ࣌', 'فقال ࡰلملأ ࡲلذين كفروا من قومه ما نريك إلا بشرا مثلنا وما نريك ࡰتبعك إلا ࡰلذين هم أراذلنا بادي ࡰلرأي࣌ وما نرى لكم علينا من فضل بل نظنكم كذبين࣌', NULL, 224, 'local:warsh-text.json'),
  ('warsh-11-28', 'warsh', 11, 28, 'قَالَ يَٰقَوْمِ أَرَٰٓيْتُمُۥٓ إِن كُنتُ عَلَىٰ بَيِّنَةࣲ مِّن رَّبِّے وَءَاتٜيٰنِے رَحْمَةࣰ مِّنْ عِندِهِۦ فَعَمِيَتْ عَلَيْكُمُۥٓ أَنُلْزِمُكُمُوهَا وَأَنتُمْ لَهَا كَٰرِهُونَ࣌', 'قال يقوم أريتم إن كنت على بينة من ربے وءاتينے رحمة من عنده فعميت عليكم أنلزمكموها وأنتم لها كرهون࣌', NULL, 224, 'local:warsh-text.json'),
  ('warsh-11-29', 'warsh', 11, 29, 'وَيَٰقَوْمِ لَآ أَسْـَٔلُكُمْ عَلَيْهِ مَالاً࣌ ࡴنَ ࡰجْرِيَ إِلَّا عَلَى ࡰ۬للَّهِ࣌ وَمَآ أَنَا بِطَارِدِ ࡴ۬لذِينَ ءَامَنُوٓاْ إِنَّهُم مُّلَٰقُواْ رَبِّهِمْ࣌ وَلَٰكِنِّيَ أَرٜيٰكُمْ قَوْماࣰ تَجْهَلُونَ࣌', 'ويقوم لا أسلكم عليه مالا࣌ ࡴن ࡰجري إلا على ࡰلله࣌ وما أنا بطارد ࡴلذين ءامنوا إنهم ملقوا ربهم࣌ ولكني أريكم قوما تجهلون࣌', NULL, 225, 'local:warsh-text.json'),
  ('warsh-11-30', 'warsh', 11, 30, 'وَيَٰقَوْمِ مَنْ يَّنصُرُنِے مِنَ ࡰ۬للَّهِ إِن طَرَدتُّهُمُۥٓ࣌ أَفَلَا تَذَّكَّرُونَ࣌', 'ويقوم من ينصرنے من ࡰلله إن طردتهم࣌ أفلا تذكرون࣌', NULL, 225, 'local:warsh-text.json'),
  ('warsh-11-31', 'warsh', 11, 31, 'وَلَآ أَقُولُ لَكُمْ عِندِے خَزَآئِنُ ࡲ۬للَّهِ وَلَآ أَعْلَمُ ࡲ۬لْغَيْبَ وَلَآ أَقُولُ إِنِّے مَلَكࣱ࣌ وَلَآ أَقُولُ لِلذِينَ تَزْدَرِےٓ أَعْيُنُكُمْ لَنْ يُّوتِيَهُمُ ࡲ۬للَّهُ خَيْراً࣌ ࡴ۬للَّهُ أَعْلَمُ بِمَا فِےٓ أَنفُسِهِمُۥٓ࣌ إِنِّيَ إِذاࣰ لَّمِنَ ࡰ۬لظَّٰلِمِينَ࣌', 'ولا أقول لكم عندے خزائن ࡲلله ولا أعلم ࡲلغيب ولا أقول إنے ملك࣌ ولا أقول للذين تزدرے أعينكم لن يوتيهم ࡲلله خيرا࣌ ࡴلله أعلم بما فے أنفسهم࣌ إني إذا لمن ࡰلظلمين࣌', NULL, 225, 'local:warsh-text.json'),
  ('warsh-11-32', 'warsh', 11, 32, '۞ قَالُواْ يَٰنُوحُ قَدْ جَٰدَلْتَنَا فَأَكْثَرْتَ جِدَٰلَنَا فَاتِنَا بِمَا تَعِدُنَآ إِن كُنتَ مِنَ ࡰ۬لصَّٰدِقِينَ࣌', 'قالوا ينوح قد جدلتنا فأكثرت جدلنا فاتنا بما تعدنا إن كنت من ࡰلصدقين࣌', NULL, 225, 'local:warsh-text.json'),
  ('warsh-11-33', 'warsh', 11, 33, 'قَالَ إِنَّمَا يَاتِيكُم بِهِ ࡴ۬للَّهُ إِن شَآءَ وَمَآ أَنتُم بِمُعْجِزِينَ࣌', 'قال إنما ياتيكم به ࡴلله إن شاء وما أنتم بمعجزين࣌', NULL, 225, 'local:warsh-text.json'),
  ('warsh-11-34', 'warsh', 11, 34, 'وَلَا يَنفَعُكُمْ نُصْحِيَ إِنَ ࡰرَدتُّ أَنَ ࡰنصَحَ لَكُمُۥٓ إِن كَانَ ࡰ۬للَّهُ يُرِيدُ أَنْ يُّغْوِيَكُمْ࣌ هُوَ رَبُّكُمْ࣌ وَإِلَيْهِ تُرْجَعُونَ࣌', 'ولا ينفعكم نصحي إن ࡰردت أن ࡰنصح لكم إن كان ࡰلله يريد أن يغويكم࣌ هو ربكم࣌ وإليه ترجعون࣌', NULL, 225, 'local:warsh-text.json'),
  ('warsh-11-35', 'warsh', 11, 35, 'أَمْ يَقُولُونَ ࡰٜفْتَرٜيٰهُ࣌ قُلِ ࡴنِ ࡴٜفْتَرَيْتُهُۥ فَعَلَيَّ إِجْرَامِے وَأَنَا بَرِےٓءࣱ مِّمَّا تُجْرِمُونَ࣌', 'أم يقولون ࡰفتريه࣌ قل ࡴن ࡴفتريته فعلي إجرامے وأنا برےء مما تجرمون࣌', NULL, 225, 'local:warsh-text.json'),
  ('warsh-11-36', 'warsh', 11, 36, 'وَأُوحِيَ إِلَىٰ نُوحٍ ࡰنَّهُۥ لَنْ يُّومِنَ مِن قَوْمِكَ إِلَّا مَن قَدَ اٰمَنَ࣌ فَلَا تَبْتَئِسْ بِمَا كَانُواْ يَفْعَلُونَ࣌', 'وأوحي إلى نوح ࡰنه لن يومن من قومك إلا من قد امن࣌ فلا تبتئس بما كانوا يفعلون࣌', NULL, 225, 'local:warsh-text.json'),
  ('warsh-11-37', 'warsh', 11, 37, 'وَاصْنَعِ ࡴ۬لْفُلْكَ بِأَعْيُنِنَا وَوَحْيِنَا࣌ وَلَا تُخَٰطِبْنِے فِے ࡴ۬لذِينَ ظَلَمُوٓاْ إِنَّهُم مُّغْرَقُونَ࣌', 'واصنع ࡴلفلك بأعيننا ووحينا࣌ ولا تخطبنے فے ࡴلذين ظلموا إنهم مغرقون࣌', NULL, 225, 'local:warsh-text.json'),
  ('warsh-11-38', 'warsh', 11, 38, 'وَيَصْنَعُ ࡲ۬لْفُلْكَ وَكُلَّمَا مَرَّ عَلَيْهِ مَلَأࣱ مِّن قَوْمِهِۦ سَخِرُواْ مِنْهُ࣌ قَالَ إِن تَسْخَرُواْ مِنَّا فَإِنَّا نَسْخَرُ مِنكُمْ كَمَا تَسْخَرُونَ࣌', 'ويصنع ࡲلفلك وكلما مر عليه ملأ من قومه سخروا منه࣌ قال إن تسخروا منا فإنا نسخر منكم كما تسخرون࣌', NULL, 226, 'local:warsh-text.json'),
  ('warsh-11-39', 'warsh', 11, 39, 'فَسَوْفَ تَعْلَمُونَ مَنْ يَّاتِيهِ عَذَابࣱ يُخْزِيهِ وَيَحِلُّ عَلَيْهِ عَذَابࣱ مُّقِيمٌ࣌', 'فسوف تعلمون من ياتيه عذاب يخزيه ويحل عليه عذاب مقيم࣌', NULL, 226, 'local:warsh-text.json'),
  ('warsh-11-40', 'warsh', 11, 40, 'حَتَّىٰٓ إِذَا جَآءَ امْرُنَا وَفَارَ ࡰ۬لتَّنُّورُ قُلْنَا ࡰٜحْمِلْ فِيهَا مِن كُلِّ زَوْجَيْنِ ࡴٜثْنَيْنِ وَأَهْلَكَ إِلَّا مَن سَبَقَ عَلَيْهِ ࡴ۬لْقَوْلُ وَمَنَ اٰمَنَ࣌ وَمَآ ءَامَنَ مَعَهُۥٓ إِلَّا قَلِيلࣱ࣌', 'حتى إذا جاء امرنا وفار ࡰلتنور قلنا ࡰحمل فيها من كل زوجين ࡴثنين وأهلك إلا من سبق عليه ࡴلقول ومن امن࣌ وما ءامن معه إلا قليل࣌', NULL, 226, 'local:warsh-text.json'),
  ('warsh-11-41', 'warsh', 11, 41, '۞ وَقَالَ ࡰٜرْكَبُواْ فِيهَا بِسْمِ ࡴ۬للَّهِ مُجْرٜيٰهَا وَمُرْسٜيٰهَآ࣌ إِنَّ رَبِّے لَغَفُورࣱ رَّحِيمࣱ࣌', 'وقال ࡰركبوا فيها بسم ࡴلله مجريها ومرسيها࣌ إن ربے لغفور رحيم࣌', NULL, 226, 'local:warsh-text.json'),
  ('warsh-11-42', 'warsh', 11, 42, 'وَهِيَ تَجْرِے بِهِمْ فِے مَوْجࣲ كَالْجِبَالِ࣌ وَنَادٜىٰ نُوحٌ ࡴٜبْنَهُۥ وَكَانَ فِے مَعْزِلࣲ يَٰبُنَيِّ ࡴٜرْكَبْ مَعَنَا وَلَا تَكُن مَّعَ ࡰ۬لْكٜـٰفِرِينَ࣌', 'وهي تجرے بهم فے موج كالجبال࣌ ونادى نوح ࡴبنه وكان فے معزل يبني ࡴركب معنا ولا تكن مع ࡰلكفرين࣌', NULL, 226, 'local:warsh-text.json'),
  ('warsh-11-43', 'warsh', 11, 43, 'قَالَ سَـَٔاوِےٓ إِلَىٰ جَبَلࣲ يَعْصِمُنِے مِنَ ࡰ۬لْمَآءِ࣌ قَالَ لَا عَٰصِمَ ࡰ۬لْيَوْمَ مِنَ ࡰمْرِ ࡴ۬للَّهِ إِلَّا مَن رَّحِمَ࣌ وَحَالَ بَيْنَهُمَا ࡰ۬لْمَوْجُ فَكَانَ مِنَ ࡰ۬لْمُغْرَقِينَ࣌', 'قال ساوے إلى جبل يعصمنے من ࡰلماء࣌ قال لا عصم ࡰليوم من ࡰمر ࡴلله إلا من رحم࣌ وحال بينهما ࡰلموج فكان من ࡰلمغرقين࣌', NULL, 226, 'local:warsh-text.json'),
  ('warsh-11-44', 'warsh', 11, 44, 'وَقِيلَ يَٰٓأَرْضُ ࡲٜبْلَعِے مَآءَكِ وَيَٰسَمَآءُ ࡶَقْلِعِے࣌ وَغِيضَ ࡰ۬لْمَآءُ وَقُضِيَ ࡰ۬لَامْرُ وَاسْتَوَتْ عَلَى ࡰ۬لْجُودِيِّ࣌ وَقِيلَ بُعْداࣰ لِّلْقَوْمِ ࡴ۬لظَّٰلِمِينَ࣌', 'وقيل يأرض ࡲبلعے ماءك ويسماء ࡶقلعے࣌ وغيض ࡰلماء وقضي ࡰلامر واستوت على ࡰلجودي࣌ وقيل بعدا للقوم ࡴلظلمين࣌', NULL, 226, 'local:warsh-text.json'),
  ('warsh-11-45', 'warsh', 11, 45, 'وَنَادٜىٰ نُوحࣱ رَّبَّهُۥ فَقَالَ رَبِّ إِنَّ ࡰٜبْنِے مِنَ ࡰهْلِے وَإِنَّ وَعْدَكَ ࡰ۬لْحَقُّ࣌ وَأَنتَ أَحْكَمُ ࡲ۬لْحَٰكِمِينَ࣌', 'ونادى نوح ربه فقال رب إن ࡰبنے من ࡰهلے وإن وعدك ࡰلحق࣌ وأنت أحكم ࡲلحكمين࣌', NULL, 226, 'local:warsh-text.json'),
  ('warsh-11-46', 'warsh', 11, 46, 'قَالَ يَٰنُوحُ إِنَّهُۥ لَيْسَ مِنَ ࡰهْلِكَ࣌ إِنَّهُۥ عَمَلٌ غَيْرُ صَٰلِحࣲ࣌ فَلَا تَسْـَٔلَنِّۦ مَا لَيْسَ لَكَ بِهِۦ عِلْمٌ࣌ ࡴنِّيَ أَعِظُكَ أَن تَكُونَ مِنَ ࡰ۬لْجَٰهِلِينَ࣌', 'قال ينوح إنه ليس من ࡰهلك࣌ إنه عمل غير صلح࣌ فلا تسلن ما ليس لك به علم࣌ ࡴني أعظك أن تكون من ࡰلجهلين࣌', NULL, 227, 'local:warsh-text.json'),
  ('warsh-11-47', 'warsh', 11, 47, 'قَالَ رَبِّ إِنِّيَ أَعُوذُ بِكَ أَنَ ࡰسْـَٔلَكَ مَا لَيْسَ لِے بِهِۦ عِلْمࣱ࣌ وَإِلَّا تَغْفِرْ لِے وَتَرْحَمْنِےٓ أَكُن مِّنَ ࡰ۬لْخَٰسِرِينَ࣌', 'قال رب إني أعوذ بك أن ࡰسلك ما ليس لے به علم࣌ وإلا تغفر لے وترحمنے أكن من ࡰلخسرين࣌', NULL, 227, 'local:warsh-text.json'),
  ('warsh-11-48', 'warsh', 11, 48, 'قِيلَ يَٰنُوحُ ࡲٜهْبِطْ بِسَلَٰمࣲ مِّنَّا وَبَرَكَٰتٍ عَلَيْكَ وَعَلَىٰٓ أُمَمࣲ مِّمَّن مَّعَكَ࣌ وَأُمَمࣱ سَنُمَتِّعُهُمْ ثُمَّ يَمَسُّهُم مِّنَّا عَذَابٌ ࡰلِيمࣱ࣌', 'قيل ينوح ࡲهبط بسلم منا وبركت عليك وعلى أمم ممن معك࣌ وأمم سنمتعهم ثم يمسهم منا عذاب ࡰليم࣌', NULL, 227, 'local:warsh-text.json'),
  ('warsh-11-49', 'warsh', 11, 49, 'تِلْكَ مِنَ ࡰنۢبَآءِ ࡴ۬لْغَيْبِ نُوحِيهَآ إِلَيْكَ࣌ مَا كُنتَ تَعْلَمُهَآ أَنتَ وَلَا قَوْمُكَ مِن قَبْلِ هَٰذَا࣌ فَاصْبِرِ࣌ ࡴنَّ ࡰ۬لْعَٰقِبَةَ لِلْمُتَّقِينَ࣌', 'تلك من ࡰنباء ࡴلغيب نوحيها إليك࣌ ما كنت تعلمها أنت ولا قومك من قبل هذا࣌ فاصبر࣌ ࡴن ࡰلعقبة للمتقين࣌', NULL, 227, 'local:warsh-text.json'),
  ('warsh-11-50', 'warsh', 11, 50, 'وَإِلَىٰ عَادٍ ࡰخَاهُمْ هُوداࣰ࣌ قَالَ يَٰقَوْمِ ࡴ࢈عْبُدُواْ ࡲ۬للَّهَ مَا لَكُم مِّنِ ࡴلَٰهٍ غَيْرُهُۥٓ࣌ إِنَ ࡰنتُمُۥٓ إِلَّا مُفْتَرُونَ࣌', 'وإلى عاد ࡰخاهم هودا࣌ قال يقوم ࡴ࢈عبدوا ࡲلله ما لكم من ࡴله غيره࣌ إن ࡰنتم إلا مفترون࣌', NULL, 227, 'local:warsh-text.json'),
  ('warsh-11-51', 'warsh', 11, 51, 'يَٰقَوْمِ لَآ أَسْـَٔلُكُمْ عَلَيْهِ أَجْراً࣌ ࡴنَ ࡰجْرِيَ إِلَّا عَلَى ࡰ۬لذِے فَطَرَنِيَ࣌ أَفَلَا تَعْقِلُونَ࣌', 'يقوم لا أسلكم عليه أجرا࣌ ࡴن ࡰجري إلا على ࡰلذے فطرني࣌ أفلا تعقلون࣌', NULL, 227, 'local:warsh-text.json'),
  ('warsh-11-52', 'warsh', 11, 52, 'وَيَٰقَوْمِ ࡴٜسْتَغْفِرُواْ رَبَّكُمْ ثُمَّ تُوبُوٓاْ إِلَيْهِ يُرْسِلِ ࡴ۬لسَّمَآءَ عَلَيْكُم مِّدْرَاراࣰ وَيَزِدْكُمْ قُوَّةً ࡴلَىٰ قُوَّتِكُمْ وَلَا تَتَوَلَّوْاْ مُجْرِمِينَ࣌', 'ويقوم ࡴستغفروا ربكم ثم توبوا إليه يرسل ࡴلسماء عليكم مدرارا ويزدكم قوة ࡴلى قوتكم ولا تتولوا مجرمين࣌', NULL, 227, 'local:warsh-text.json'),
  ('warsh-11-53', 'warsh', 11, 53, '۞ قَالُواْ يَٰهُودُ مَا جِئْتَنَا بِبَيِّنَةࣲ وَمَا نَحْنُ بِتَارِكِےٓ ءَالِهَتِنَا عَن قَوْلِكَ وَمَا نَحْنُ لَكَ بِمُومِنِينَ࣌', 'قالوا يهود ما جئتنا ببينة وما نحن بتاركے ءالهتنا عن قولك وما نحن لك بمومنين࣌', NULL, 227, 'local:warsh-text.json'),
  ('warsh-11-54', 'warsh', 11, 54, 'إِن نَّقُولُ إِلَّا ࡰٜعْتَرٜيٰكَ بَعْضُ ءَالِهَتِنَا بِسُوٓءࣲ࣌ قَالَ إِنِّيَ أُشْهِدُ ࡲ۬للَّهَ࣌ وَاشْهَدُوٓاْ أَنِّے بَرِےٓءࣱ مِّمَّا تُشْرِكُونَ مِن دُونِهِۦ࣌ فَكِيدُونِے جَمِيعاࣰ ثُمَّ لَا تُنظِرُونِ࣌', 'إن نقول إلا ࡰعتريك بعض ءالهتنا بسوء࣌ قال إني أشهد ࡲلله࣌ واشهدوا أنے برےء مما تشركون من دونه࣌ فكيدونے جميعا ثم لا تنظرون࣌', NULL, 228, 'local:warsh-text.json'),
  ('warsh-11-55', 'warsh', 11, 55, 'إِنِّے تَوَكَّلْتُ عَلَى ࡰ۬للَّهِ رَبِّے وَرَبِّكُم࣌ مَّا مِن دَآبَّةٍ ࡴلَّا هُوَ ءَاخِذُۢ بِنَاصِيَتِهَآ࣌ إِنَّ رَبِّے عَلَىٰ صِرَٰطࣲ مُّسْتَقِيمࣲ࣌', 'إنے توكلت على ࡰلله ربے وربكم࣌ ما من دابة ࡴلا هو ءاخذ بناصيتها࣌ إن ربے على صرط مستقيم࣌', NULL, 228, 'local:warsh-text.json'),
  ('warsh-11-56', 'warsh', 11, 56, 'فَإِن تَوَلَّوْاْ فَقَدَ ࡰبْلَغْتُكُم مَّآ أُرْسِلْتُ بِهِۦٓ إِلَيْكُمْ࣌ وَيَسْتَخْلِفُ رَبِّے قَوْماً غَيْرَكُمْ وَلَا تَضُرُّونَهُۥ شَيْـٔاً࣌ ࡴنَّ رَبِّے عَلَىٰ كُلِّ شَےْءٍ حَفِيظࣱ࣌', 'فإن تولوا فقد ࡰبلغتكم ما أرسلت به إليكم࣌ ويستخلف ربے قوما غيركم ولا تضرونه شيا࣌ ࡴن ربے على كل شےء حفيظ࣌', NULL, 228, 'local:warsh-text.json'),
  ('warsh-11-57', 'warsh', 11, 57, 'وَلَمَّا جَآءَ امْرُنَا نَجَّيْنَا هُوداࣰ وَالذِينَ ءَامَنُواْ مَعَهُۥ بِرَحْمَةࣲ مِّنَّا وَنَجَّيْنَٰهُم مِّنْ عَذَابٍ غَلِيظࣲ࣌', 'ولما جاء امرنا نجينا هودا والذين ءامنوا معه برحمة منا ونجينهم من عذاب غليظ࣌', NULL, 228, 'local:warsh-text.json'),
  ('warsh-11-58', 'warsh', 11, 58, 'وَتِلْكَ عَادࣱ جَحَدُواْ بِـَٔايَٰتِ رَبِّهِمْ وَعَصَوْاْ رُسُلَهُۥ وَاتَّبَعُوٓاْ أَمْرَ كُلِّ جَبّٜارٍ عَنِيدࣲ࣌', 'وتلك عاد جحدوا بايت ربهم وعصوا رسله واتبعوا أمر كل جبار عنيد࣌', NULL, 228, 'local:warsh-text.json'),
  ('warsh-11-59', 'warsh', 11, 59, 'وَأُتْبِعُواْ فِے هَٰذِهِ ࡴ۬لدُّنْيٜا لَعْنَةࣰ وَيَوْمَ ࡰ۬لْقِيَٰمَةِ࣌ أَلَآ إِنَّ عَاداࣰ كَفَرُواْ رَبَّهُمُۥٓ࣌ أَلَا بُعْداࣰ لِّعَادࣲ قَوْمِ هُودࣲ࣌', 'وأتبعوا فے هذه ࡴلدنيا لعنة ويوم ࡰلقيمة࣌ ألا إن عادا كفروا ربهم࣌ ألا بعدا لعاد قوم هود࣌', NULL, 228, 'local:warsh-text.json'),
  ('warsh-11-60', 'warsh', 11, 60, 'وَإِلَىٰ ثَمُودَ أَخَاهُمْ صَٰلِحاࣰ࣌ قَالَ يَٰقَوْمِ ࡴ࢈عْبُدُواْ ࡲ۬للَّهَ مَا لَكُم مِّنِ ࡴلَٰهٍ غَيْرُهُۥ࣌ هُوَ أَنشَأَكُم مِّنَ ࡰ۬لَارْضِ وَاسْتَعْمَرَكُمْ فِيهَا فَاسْتَغْفِرُوهُ ثُمَّ تُوبُوٓاْ إِلَيْهِ࣌ إِنَّ رَبِّے قَرِيبࣱ مُّجِيبࣱ࣌', 'وإلى ثمود أخاهم صلحا࣌ قال يقوم ࡴ࢈عبدوا ࡲلله ما لكم من ࡴله غيره࣌ هو أنشأكم من ࡰلارض واستعمركم فيها فاستغفروه ثم توبوا إليه࣌ إن ربے قريب مجيب࣌', NULL, 228, 'local:warsh-text.json'),
  ('warsh-11-61', 'warsh', 11, 61, '۞ قَالُواْ يَٰصَٰلِحُ قَدْ كُنتَ فِينَا مَرْجُوّاࣰ قَبْلَ هَٰذَآ أَتَنْهٜيٰنَآ أَن نَّعْبُدَ مَا يَعْبُدُ ءَابَآؤُنَا وَإِنَّنَا لَفِے شَكࣲّ مِّمَّا تَدْعُونَآ إِلَيْهِ مُرِيبࣲ࣌', 'قالوا يصلح قد كنت فينا مرجوا قبل هذا أتنهينا أن نعبد ما يعبد ءاباؤنا وإننا لفے شك مما تدعونا إليه مريب࣌', NULL, 228, 'local:warsh-text.json'),
  ('warsh-11-62', 'warsh', 11, 62, 'قَالَ يَٰقَوْمِ أَرَٰٓيْتُمُۥٓ إِن كُنتُ عَلَىٰ بَيِّنَةࣲ مِّن رَّبِّے وَءَاتٜيٰنِے مِنْهُ رَحْمَةࣰ فَمَنْ يَّنصُرُنِے مِنَ ࡰ۬للَّهِ إِنْ عَصَيْتُهُۥ࣌ فَمَا تَزِيدُونَنِے غَيْرَ تَخْسِيرࣲ࣌', 'قال يقوم أريتم إن كنت على بينة من ربے وءاتينے منه رحمة فمن ينصرنے من ࡰلله إن عصيته࣌ فما تزيدوننے غير تخسير࣌', NULL, 229, 'local:warsh-text.json'),
  ('warsh-11-63', 'warsh', 11, 63, 'وَيَٰقَوْمِ هَٰذِهِۦ نَاقَةُ ࡲ۬للَّهِ لَكُمُۥٓ ءَايَةࣰ࣌ فَذَرُوهَا تَاكُلْ فِےٓ أَرْضِ ࡴ۬للَّهِ࣌ وَلَا تَمَسُّوهَا بِسُوٓءࣲ فَيَاخُذَكُمْ عَذَابࣱ قَرِيبࣱ࣌', 'ويقوم هذه ناقة ࡲلله لكم ءاية࣌ فذروها تاكل فے أرض ࡴلله࣌ ولا تمسوها بسوء فياخذكم عذاب قريب࣌', NULL, 229, 'local:warsh-text.json'),
  ('warsh-11-64', 'warsh', 11, 64, 'فَعَقَرُوهَا فَقَالَ تَمَتَّعُواْ فِے دٜارِكُمْ ثَلَٰثَةَ أَيَّامࣲ࣌ ذَٰلِكَ وَعْدٌ غَيْرُ مَكْذُوبࣲ࣌', 'فعقروها فقال تمتعوا فے داركم ثلثة أيام࣌ ذلك وعد غير مكذوب࣌', NULL, 229, 'local:warsh-text.json'),
  ('warsh-11-65', 'warsh', 11, 65, 'فَلَمَّا جَآءَ امْرُنَا نَجَّيْنَا صَٰلِحاࣰ وَالذِينَ ءَامَنُواْ مَعَهُۥ بِرَحْمَةࣲ مِّنَّا وَمِنْ خِزْيِ يَوْمَئِذٍ࣌ ࡴنَّ رَبَّكَ هُوَ ࡰ۬لْقَوِيُّ ࡲ۬لْعَزِيزُ࣌', 'فلما جاء امرنا نجينا صلحا والذين ءامنوا معه برحمة منا ومن خزي يومئذ࣌ ࡴن ربك هو ࡰلقوي ࡲلعزيز࣌', NULL, 229, 'local:warsh-text.json'),
  ('warsh-11-66', 'warsh', 11, 66, 'وَأَخَذَ ࡰ۬لذِينَ ظَلَمُواْ ࡲ۬لصَّيْحَةُ فَأَصْبَحُواْ فِے دِيٜـٰرِهِمْ جَٰثِمِينَ', 'وأخذ ࡰلذين ظلموا ࡲلصيحة فأصبحوا فے ديرهم جثمين', NULL, 229, 'local:warsh-text.json'),
  ('warsh-11-67', 'warsh', 11, 67, 'كَأَن لَّمْ يَغْنَوْاْ فِيهَآ࣌ أَلَآ إِنَّ ثَمُوداࣰ كَفَرُواْ رَبَّهُمُۥٓ࣌ أَلَا بُعْداࣰ لِّثَمُودَ࣌', 'كأن لم يغنوا فيها࣌ ألا إن ثمودا كفروا ربهم࣌ ألا بعدا لثمود࣌', NULL, 229, 'local:warsh-text.json'),
  ('warsh-11-68', 'warsh', 11, 68, 'وَلَقَدْ جَآءَتْ رُسُلُنَآ إِبْرَٰهِيمَ بِالْبُشْرٜىٰ قَالُواْ سَلَٰماࣰ࣌ قَالَ سَلَٰمࣱ࣌ فَمَا لَبِثَ أَن جَآءَ بِعِجْلٍ حَنِيذࣲ࣌', 'ولقد جاءت رسلنا إبرهيم بالبشرى قالوا سلما࣌ قال سلم࣌ فما لبث أن جاء بعجل حنيذ࣌', NULL, 229, 'local:warsh-text.json'),
  ('warsh-11-69', 'warsh', 11, 69, 'فَلَمَّا رٜءٜآ أَيْدِيَهُمْ لَا تَصِلُ إِلَيْهِ نَكِرَهُمْ وَأَوْجَسَ مِنْهُمْ خِيفَةࣰ࣌ قَالُواْ لَا تَخَفِ࣌ ࡴنَّآ أُرْسِلْنَآ إِلَىٰ قَوْمِ لُوطࣲ࣌', 'فلما رءا أيديهم لا تصل إليه نكرهم وأوجس منهم خيفة࣌ قالوا لا تخف࣌ ࡴنا أرسلنا إلى قوم لوط࣌', NULL, 229, 'local:warsh-text.json'),
  ('warsh-11-70', 'warsh', 11, 70, 'وَامْرَأَتُهُۥ قَآئِمَةࣱ فَضَحِكَتْ࣌ فَبَشَّرْنَٰهَا بِإِسْحَٰقَ࣌ وَمِنْ وَّرَآءِ اسْحَٰقَ يَعْقُوبُ࣌', 'وامرأته قائمة فضحكت࣌ فبشرنها بإسحق࣌ ومن وراء اسحق يعقوب࣌', NULL, 229, 'local:warsh-text.json'),
  ('warsh-11-71', 'warsh', 11, 71, 'قَالَتْ يَٰوَيْلَتٜىٰٓ ءَالِدُ وَأَنَا عَجُوزࣱ وَهَٰذَا بَعْلِے شَيْخاً࣌ ࡴنَّ هَٰذَا لَشَےْءٌ عَجِيبࣱ࣌', 'قالت يويلتى ءالد وأنا عجوز وهذا بعلے شيخا࣌ ࡴن هذا لشےء عجيب࣌', NULL, 230, 'local:warsh-text.json'),
  ('warsh-11-72', 'warsh', 11, 72, '۞ قَالُوٓاْ أَتَعْجَبِينَ مِنَ ࡰمْرِ ࡴ۬للَّهِ࣌ رَحْمَتُ ࡲ۬للَّهِ وَبَرَكَٰتُهُۥ عَلَيْكُمُۥٓ أَهْلَ ࡰ۬لْبَيْتِ࣌ إِنَّهُۥ حَمِيدࣱ مَّجِيدࣱ࣌', 'قالوا أتعجبين من ࡰمر ࡴلله࣌ رحمت ࡲلله وبركته عليكم أهل ࡰلبيت࣌ إنه حميد مجيد࣌', NULL, 230, 'local:warsh-text.json'),
  ('warsh-11-73', 'warsh', 11, 73, 'فَلَمَّا ذَهَبَ عَنِ ࡴبْرَٰهِيمَ ࡰ۬لرَّوْعُ وَجَآءَتْهُ ࡲ۬لْبُشْرٜىٰ يُجَٰدِلُنَا فِے قَوْمِ لُوطٍ࣌', 'فلما ذهب عن ࡴبرهيم ࡰلروع وجاءته ࡲلبشرى يجدلنا فے قوم لوط࣌', NULL, 230, 'local:warsh-text.json'),
  ('warsh-11-74', 'warsh', 11, 74, 'ࡴنَّ إِبْرَٰهِيمَ لَحَلِيمٌ ࡰوَّٰهࣱ مُّنِيبࣱ࣌', 'ࡴن إبرهيم لحليم ࡰوه منيب࣌', NULL, 230, 'local:warsh-text.json'),
  ('warsh-11-75', 'warsh', 11, 75, 'يَٰٓإِبْرَٰهِيمُ أَعْرِضْ عَنْ هَٰذَآ࣌ إِنَّهُۥ قَدْ جَآءَ امْرُ رَبِّكَ࣌ وَإِنَّهُمُۥٓ ءَاتِيهِمْ عَذَابٌ غَيْرُ مَرْدُودࣲ࣌', 'يإبرهيم أعرض عن هذا࣌ إنه قد جاء امر ربك࣌ وإنهم ءاتيهم عذاب غير مردود࣌', NULL, 230, 'local:warsh-text.json'),
  ('warsh-11-76', 'warsh', 11, 76, 'وَلَمَّا جَآءَتْ رُسُلُنَا لُوطاࣰ س۬ےٓءَ بِهِمْ وَضَاقَ بِهِمْ ذَرْعاࣰ وَقَالَ هَٰذَا يَوْمٌ عَصِيبࣱ࣌', 'ولما جاءت رسلنا لوطا سےء بهم وضاق بهم ذرعا وقال هذا يوم عصيب࣌', NULL, 230, 'local:warsh-text.json'),
  ('warsh-11-77', 'warsh', 11, 77, 'وَجَآءَهُۥ قَوْمُهُۥ يُهْرَعُونَ إِلَيْهِ وَمِن قَبْلُ كَانُواْ يَعْمَلُونَ ࡰ۬لسَّيِّـَٔاتِ࣌ قَالَ يَٰقَوْمِ هَٰٓؤُلَآءِ بَنَاتِے هُنَّ أَطْهَرُ لَكُمْ فَاتَّقُواْ ࡲ۬للَّهَ وَلَا تُخْزُونِ فِے ضَيْفِيَ࣌ أَلَيْسَ مِنكُمْ رَجُلࣱ رَّشِيدࣱ࣌', 'وجاءه قومه يهرعون إليه ومن قبل كانوا يعملون ࡰلسيات࣌ قال يقوم هؤلاء بناتے هن أطهر لكم فاتقوا ࡲلله ولا تخزون فے ضيفي࣌ أليس منكم رجل رشيد࣌', NULL, 230, 'local:warsh-text.json'),
  ('warsh-11-78', 'warsh', 11, 78, 'قَالُواْ لَقَدْ عَلِمْتَ مَا لَنَا فِے بَنَاتِكَ مِنْ حَقࣲّ وَإِنَّكَ لَتَعْلَمُ مَا نُرِيدُ࣌', 'قالوا لقد علمت ما لنا فے بناتك من حق وإنك لتعلم ما نريد࣌', NULL, 230, 'local:warsh-text.json'),
  ('warsh-11-79', 'warsh', 11, 79, 'قَالَ لَوَ ࡰنَّ لِے بِكُمْ قُوَّةً ࡰوَ اٰوِےٓ إِلَىٰ رُكْنࣲ شَدِيدࣲ࣌', 'قال لو ࡰن لے بكم قوة ࡰو اوے إلى ركن شديد࣌', NULL, 230, 'local:warsh-text.json'),
  ('warsh-11-80', 'warsh', 11, 80, 'قَالُواْ يَٰلُوطُ إِنَّا رُسُلُ رَبِّكَ لَنْ يَّصِلُوٓاْ إِلَيْكَ࣌ فَاسْرِ بِأَهْلِكَ بِقِطْعࣲ مِّنَ ࡰ۬ليْلِ وَلَا يَلْتَفِتْ مِنكُمُۥٓ أَحَدٌ ࡴلَّا ࡰٜمْرَأَتَكَ࣌ إِنَّهُۥ مُصِيبُهَا مَآ أَصَابَهُمُۥٓ࣌ إِنَّ مَوْعِدَهُمُ ࡲ۬لصُّبْحُ࣌ أَلَيْسَ ࡰ۬لصُّبْحُ بِقَرِيبࣲ࣌', 'قالوا يلوط إنا رسل ربك لن يصلوا إليك࣌ فاسر بأهلك بقطع من ࡰليل ولا يلتفت منكم أحد ࡴلا ࡰمرأتك࣌ إنه مصيبها ما أصابهم࣌ إن موعدهم ࡲلصبح࣌ أليس ࡰلصبح بقريب࣌', NULL, 230, 'local:warsh-text.json'),
  ('warsh-11-81', 'warsh', 11, 81, 'فَلَمَّا جَآءَ امْرُنَا جَعَلْنَا عَٰلِيَهَا سَافِلَهَا وَأَمْطَرْنَا عَلَيْهَا حِجَارَةࣰ مِّن سِجِّيلࣲ', 'فلما جاء امرنا جعلنا عليها سافلها وأمطرنا عليها حجارة من سجيل', NULL, 231, 'local:warsh-text.json'),
  ('warsh-11-82', 'warsh', 11, 82, 'مَّنضُودࣲ مُّسَوَّمَةً عِندَ رَبِّكَ࣌ وَمَا هِيَ مِنَ ࡰ۬لظَّٰلِمِينَ بِبَعِيدࣲ࣌', 'منضود مسومة عند ربك࣌ وما هي من ࡰلظلمين ببعيد࣌', NULL, 231, 'local:warsh-text.json'),
  ('warsh-11-83', 'warsh', 11, 83, '۞ وَإِلَىٰ مَدْيَنَ أَخَاهُمْ شُعَيْباࣰ࣌ قَالَ يَٰقَوْمِ ࡴ࢈عْبُدُواْ ࡲ۬للَّهَ مَا لَكُم مِّنِ ࡴلَٰهٍ غَيْرُهُۥ࣌ وَلَا تَنقُصُواْ ࡲ۬لْمِكْيَالَ وَالْمِيزَانَ࣌ إِنِّيَ أَرٜيٰكُم بِخَيْرࣲ وَإِنِّيَ أَخَافُ عَلَيْكُمْ عَذَابَ يَوْمࣲ مُّحِيطࣲ࣌', 'وإلى مدين أخاهم شعيبا࣌ قال يقوم ࡴ࢈عبدوا ࡲلله ما لكم من ࡴله غيره࣌ ولا تنقصوا ࡲلمكيال والميزان࣌ إني أريكم بخير وإني أخاف عليكم عذاب يوم محيط࣌', NULL, 231, 'local:warsh-text.json'),
  ('warsh-11-84', 'warsh', 11, 84, 'وَيَٰقَوْمِ أَوْفُواْ ࡲ۬لْمِكْيَالَ وَالْمِيزَانَ بِالْقِسْطِ࣌ وَلَا تَبْخَسُواْ ࡲ۬لنَّاسَ أَشْيَآءَهُمْ وَلَا تَعْثَوْاْ فِے ࡴ۬لَارْضِ مُفْسِدِينَ࣌', 'ويقوم أوفوا ࡲلمكيال والميزان بالقسط࣌ ولا تبخسوا ࡲلناس أشياءهم ولا تعثوا فے ࡴلارض مفسدين࣌', NULL, 231, 'local:warsh-text.json'),
  ('warsh-11-85', 'warsh', 11, 85, 'بَقِيَّتُ ࡲ۬للَّهِ خَيْرࣱ لَّكُمُۥٓ إِن كُنتُم مُّومِنِينَ࣌', 'بقيت ࡲلله خير لكم إن كنتم مومنين࣌', NULL, 231, 'local:warsh-text.json'),
  ('warsh-11-86', 'warsh', 11, 86, 'وَمَآ أَنَا عَلَيْكُم بِحَفِيظࣲ࣌', 'وما أنا عليكم بحفيظ࣌', NULL, 231, 'local:warsh-text.json'),
  ('warsh-11-87', 'warsh', 11, 87, 'قَالُواْ يَٰشُعَيْبُ أَصَلَوَٰتُكَ تَامُرُكَ أَن نَّتْرُكَ مَا يَعْبُدُ ءَابَآؤُنَآ أَوَ ࡰن نَّفْعَلَ فِےٓ أَمْوَٰلِنَا مَا نَشَٰٓؤُاْ࣌ ࡹِنَّكَ لَأَنتَ ࡰ۬لْحَلِيمُ ࡲ۬لرَّشِيدُ࣌', 'قالوا يشعيب أصلوتك تامرك أن نترك ما يعبد ءاباؤنا أو ࡰن نفعل فے أمولنا ما نشؤا࣌ ࡹنك لأنت ࡰلحليم ࡲلرشيد࣌', NULL, 231, 'local:warsh-text.json'),
  ('warsh-11-88', 'warsh', 11, 88, 'قَالَ يَٰقَوْمِ أَرَٰٓيْتُمُۥٓ إِن كُنتُ عَلَىٰ بَيِّنَةࣲ مِّن رَّبِّے وَرَزَقَنِے مِنْهُ رِزْقاً حَسَناࣰ࣌ وَمَآ أُرِيدُ أَنُ ࡳخَالِفَكُمُۥٓ إِلَىٰ مَآ أَنْهٜيٰكُمْ عَنْهُ࣌ إِنُ ࡳرِيدُ إِلَّا ࡰ۬لِاصْلَٰحَ مَا ࡰٜسْتَطَعْتُ࣌ وَمَا تَوْفِيقِيَ إِلَّا بِاللَّهِ࣌ عَلَيْهِ تَوَكَّلْتُ࣌ وَإِلَيْهِ أُنِيبُ࣌', 'قال يقوم أريتم إن كنت على بينة من ربے ورزقنے منه رزقا حسنا࣌ وما أريد أن ࡳخالفكم إلى ما أنهيكم عنه࣌ إن ࡳريد إلا ࡰلاصلح ما ࡰستطعت࣌ وما توفيقي إلا بالله࣌ عليه توكلت࣌ وإليه أنيب࣌', NULL, 231, 'local:warsh-text.json'),
  ('warsh-11-89', 'warsh', 11, 89, 'وَيَٰقَوْمِ لَا يَجْرِمَنَّكُمْ شِقَاقِيَ أَنْ يُّصِيبَكُم مِّثْلُ مَآ أَصَابَ قَوْمَ نُوحٍ ࡰوْ قَوْمَ هُودٍ ࡰوْ قَوْمَ صَٰلِحࣲ࣌ وَمَا قَوْمُ لُوطࣲ مِّنكُم بِبَعِيدࣲ࣌', 'ويقوم لا يجرمنكم شقاقي أن يصيبكم مثل ما أصاب قوم نوح ࡰو قوم هود ࡰو قوم صلح࣌ وما قوم لوط منكم ببعيد࣌', NULL, 232, 'local:warsh-text.json'),
  ('warsh-11-90', 'warsh', 11, 90, 'وَاسْتَغْفِرُواْ رَبَّكُمْ ثُمَّ تُوبُوٓاْ إِلَيْهِ࣌ إِنَّ رَبِّے رَحِيمࣱ وَدُودࣱ࣌', 'واستغفروا ربكم ثم توبوا إليه࣌ إن ربے رحيم ودود࣌', NULL, 232, 'local:warsh-text.json'),
  ('warsh-11-91', 'warsh', 11, 91, 'قَالُواْ يَٰشُعَيْبُ مَا نَفْقَهُ كَثِيراࣰ مِّمَّا تَقُولُ وَإِنَّا لَنَرٜيٰكَ فِينَا ضَعِيفاࣰ وَلَوْلَا رَهْطُكَ لَرَجَمْنَٰكَ وَمَآ أَنتَ عَلَيْنَا بِعَزِيزࣲ࣌', 'قالوا يشعيب ما نفقه كثيرا مما تقول وإنا لنريك فينا ضعيفا ولولا رهطك لرجمنك وما أنت علينا بعزيز࣌', NULL, 232, 'local:warsh-text.json'),
  ('warsh-11-92', 'warsh', 11, 92, 'قَالَ يَٰقَوْمِ أَرَهْطِيَ أَعَزُّ عَلَيْكُم مِّنَ ࡰ۬للَّهِ وَاتَّخَذتُّمُوهُ وَرَآءَكُمْ ظِهْرِيّاً࣌ ࡴنَّ رَبِّے بِمَا تَعْمَلُونَ مُحِيطࣱ࣌', 'قال يقوم أرهطي أعز عليكم من ࡰلله واتخذتموه وراءكم ظهريا࣌ ࡴن ربے بما تعملون محيط࣌', NULL, 232, 'local:warsh-text.json'),
  ('warsh-11-93', 'warsh', 11, 93, '۞ وَيَٰقَوْمِ ࡴٜعْمَلُواْ عَلَىٰ مَكَانَتِكُمُۥٓ إِنِّے عَٰمِلࣱ࣌ سَوْفَ تَعْلَمُونَ مَنْ يَّاتِيهِ عَذَابࣱ يُخْزِيهِ وَمَنْ هُوَ كَٰذِبࣱ࣌ وَارْتَقِبُوٓاْ࣌ إِنِّے مَعَكُمْ رَقِيبࣱ࣌', 'ويقوم ࡴعملوا على مكانتكم إنے عمل࣌ سوف تعلمون من ياتيه عذاب يخزيه ومن هو كذب࣌ وارتقبوا࣌ إنے معكم رقيب࣌', NULL, 232, 'local:warsh-text.json'),
  ('warsh-11-94', 'warsh', 11, 94, 'وَلَمَّا جَآءَ امْرُنَا نَجَّيْنَا شُعَيْباࣰ وَالذِينَ ءَامَنُواْ مَعَهُۥ بِرَحْمَةࣲ مِّنَّا࣌ وَأَخَذَتِ ࡴ۬لذِينَ ظَلَمُواْ ࡲ۬لصَّيْحَةُ فَأَصْبَحُواْ فِے دِيٜـٰرِهِمْ جَٰثِمِينَ', 'ولما جاء امرنا نجينا شعيبا والذين ءامنوا معه برحمة منا࣌ وأخذت ࡴلذين ظلموا ࡲلصيحة فأصبحوا فے ديرهم جثمين', NULL, 232, 'local:warsh-text.json'),
  ('warsh-11-95', 'warsh', 11, 95, 'كَأَن لَّمْ يَغْنَوْاْ فِيهَآ࣌ أَلَا بُعْداࣰ لِّمَدْيَنَ كَمَا بَعِدَتْ ثَمُودُ࣌', 'كأن لم يغنوا فيها࣌ ألا بعدا لمدين كما بعدت ثمود࣌', NULL, 232, 'local:warsh-text.json'),
  ('warsh-11-96', 'warsh', 11, 96, 'وَلَقَدَ ࡰرْسَلْنَا مُوسٜىٰ بِـَٔايَٰتِنَا وَسُلْطَٰنࣲ مُّبِينٍ', 'ولقد ࡰرسلنا موسى بايتنا وسلطن مبين', NULL, 232, 'local:warsh-text.json'),
  ('warsh-11-97', 'warsh', 11, 97, 'ࡴلَىٰ فِرْعَوْنَ وَمَلَإِيْهِۦ فَاتَّبَعُوٓاْ أَمْرَ فِرْعَوْنَ࣌ وَمَآ أَمْرُ فِرْعَوْنَ بِرَشِيدࣲ࣌', 'ࡴلى فرعون وملإيه فاتبعوا أمر فرعون࣌ وما أمر فرعون برشيد࣌', NULL, 232, 'local:warsh-text.json'),
  ('warsh-11-98', 'warsh', 11, 98, 'يَقْدُمُ قَوْمَهُۥ يَوْمَ ࡰ۬لْقِيَٰمَةِ فَأَوْرَدَهُمُ ࡲ۬لنَّارَ࣌ وَبِيسَ ࡰ۬لْوِرْدُ ࡲ۬لْمَوْرُودُ࣌', 'يقدم قومه يوم ࡰلقيمة فأوردهم ࡲلنار࣌ وبيس ࡰلورد ࡲلمورود࣌', NULL, 233, 'local:warsh-text.json'),
  ('warsh-11-99', 'warsh', 11, 99, 'وَأُتْبِعُواْ فِے هَٰذِهِۦ لَعْنَةࣰ وَيَوْمَ ࡰ۬لْقِيَٰمَةِ࣌ بِيسَ ࡰ۬لرِّفْدُ ࡲ۬لْمَرْفُودُ࣌', 'وأتبعوا فے هذه لعنة ويوم ࡰلقيمة࣌ بيس ࡰلرفد ࡲلمرفود࣌', NULL, 233, 'local:warsh-text.json'),
  ('warsh-11-100', 'warsh', 11, 100, 'ذَٰلِكَ مِنَ ࡰنۢبَآءِ ࡴ۬لْقُرٜىٰ نَقُصُّهُۥ عَلَيْكَ مِنْهَا قَآئِمࣱ وَحَصِيدࣱ࣌', 'ذلك من ࡰنباء ࡴلقرى نقصه عليك منها قائم وحصيد࣌', NULL, 233, 'local:warsh-text.json'),
  ('warsh-11-101', 'warsh', 11, 101, 'وَمَا ظَلَمْنَٰهُمْ وَلَٰكِن ظَلَمُوٓاْ أَنفُسَهُمْ࣌ فَمَآ أَغْنَتْ عَنْهُمُۥٓ ءَالِهَتُهُمُ ࡲ۬لتِے يَدْعُونَ مِن دُونِ ࡴ۬للَّهِ مِن شَےْءࣲ لَّمَّا جَآءَ امْرُ رَبِّكَ࣌ وَمَا زَادُوهُمْ غَيْرَ تَتْبِيبࣲ࣌', 'وما ظلمنهم ولكن ظلموا أنفسهم࣌ فما أغنت عنهم ءالهتهم ࡲلتے يدعون من دون ࡴلله من شےء لما جاء امر ربك࣌ وما زادوهم غير تتبيب࣌', NULL, 233, 'local:warsh-text.json'),
  ('warsh-11-102', 'warsh', 11, 102, 'وَكَذَٰلِكَ أَخْذُ رَبِّكَ إِذَآ أَخَذَ ࡰ۬لْقُرٜىٰ وَهِيَ ظَالِمَةٌ࣌ ࡴنَّ أَخْذَهُۥٓ أَلِيمࣱ شَدِيدٌ࣌', 'وكذلك أخذ ربك إذا أخذ ࡰلقرى وهي ظالمة࣌ ࡴن أخذه أليم شديد࣌', NULL, 233, 'local:warsh-text.json'),
  ('warsh-11-103', 'warsh', 11, 103, 'ࡴنَّ فِے ذَٰلِكَ لَأٓيَةࣰ لِّمَنْ خَافَ عَذَابَ ࡰ۬لَاخِرَةِ࣌ ذَٰلِكَ يَوْمࣱ مَّجْمُوعࣱ لَّهُ ࡲ۬لنَّاسُ࣌ وَذَٰلِكَ يَوْمࣱ مَّشْهُودࣱ࣌', 'ࡴن فے ذلك لأية لمن خاف عذاب ࡰلاخرة࣌ ذلك يوم مجموع له ࡲلناس࣌ وذلك يوم مشهود࣌', NULL, 233, 'local:warsh-text.json'),
  ('warsh-11-104', 'warsh', 11, 104, 'وَمَا نُوَ۬خِّرُهُۥٓ إِلَّا لِأَجَلࣲ مَّعْدُودࣲ࣌', 'وما نوخره إلا لأجل معدود࣌', NULL, 233, 'local:warsh-text.json'),
  ('warsh-11-105', 'warsh', 11, 105, '۞ يَوْمَ يَاتِۦ لَا تَكَلَّمُ نَفْسٌ ࡴلَّا بِإِذْنِهِۦ࣌ فَمِنْهُمْ شَقِيࣱّ وَسَعِيدࣱ࣌', 'يوم يات لا تكلم نفس ࡴلا بإذنه࣌ فمنهم شقي وسعيد࣌', NULL, 233, 'local:warsh-text.json'),
  ('warsh-11-106', 'warsh', 11, 106, 'فَأَمَّا ࡰ۬لذِينَ شَقُواْ فَفِے ࡴ۬لنّٜارِ لَهُمْ فِيهَا زَفِيرࣱ وَشَهِيقٌ', 'فأما ࡰلذين شقوا ففے ࡴلنار لهم فيها زفير وشهيق', NULL, 233, 'local:warsh-text.json'),
  ('warsh-11-107', 'warsh', 11, 107, 'خَٰلِدِينَ فِيهَا مَا دَامَتِ ࡴ۬لسَّمَٰوَٰتُ وَالَارْضُ إِلَّا مَا شَآءَ رَبُّكَ࣌ إِنَّ رَبَّكَ فَعَّالࣱ لِّمَا يُرِيدُ࣌', 'خلدين فيها ما دامت ࡴلسموت والارض إلا ما شاء ربك࣌ إن ربك فعال لما يريد࣌', NULL, 233, 'local:warsh-text.json'),
  ('warsh-11-108', 'warsh', 11, 108, 'وَأَمَّا ࡰ۬لذِينَ سَعِدُواْ فَفِے ࡴ۬لْجَنَّةِ خَٰلِدِينَ فِيهَا مَا دَامَتِ ࡴ۬لسَّمَٰوَٰتُ وَالَارْضُ إِلَّا مَا شَآءَ رَبُّكَ࣌ عَطَآءً غَيْرَ مَجْذُوذࣲ࣌', 'وأما ࡰلذين سعدوا ففے ࡴلجنة خلدين فيها ما دامت ࡴلسموت والارض إلا ما شاء ربك࣌ عطاء غير مجذوذ࣌', NULL, 233, 'local:warsh-text.json'),
  ('warsh-11-109', 'warsh', 11, 109, 'فَلَا تَكُ فِے مِرْيَةࣲ مِّمَّا يَعْبُدُ هَٰٓؤُلَآءِ࣌ مَا يَعْبُدُونَ إِلَّا كَمَا يَعْبُدُ ءَابَآؤُهُم مِّن قَبْلُ࣌ وَإِنَّا لَمُوَفُّوهُمْ نَصِيبَهُمْ غَيْرَ مَنقُوصࣲ࣌', 'فلا تك فے مرية مما يعبد هؤلاء࣌ ما يعبدون إلا كما يعبد ءاباؤهم من قبل࣌ وإنا لموفوهم نصيبهم غير منقوص࣌', NULL, 234, 'local:warsh-text.json'),
  ('warsh-11-110', 'warsh', 11, 110, 'وَلَقَدَ اٰتَيْنَا مُوسَى ࡰ۬لْكِتَٰبَ فَاخْتُلِفَ فِيهِ࣌ وَلَوْلَا كَلِمَةࣱ سَبَقَتْ مِن رَّبِّكَ لَقُضِيَ بَيْنَهُمْ࣌ وَإِنَّهُمْ لَفِے شَكࣲّ مِّنْهُ مُرِيبࣲ࣌', 'ولقد اتينا موسى ࡰلكتب فاختلف فيه࣌ ولولا كلمة سبقت من ربك لقضي بينهم࣌ وإنهم لفے شك منه مريب࣌', NULL, 234, 'local:warsh-text.json'),
  ('warsh-11-111', 'warsh', 11, 111, 'وَإِن كُلّاࣰ لَّمَا لَيُوَفِّيَنَّهُمْ رَبُّكَ أَعْمَٰلَهُمُۥٓ࣌ إِنَّهُۥ بِمَا يَعْمَلُونَ خَبِيرࣱ࣌', 'وإن كلا لما ليوفينهم ربك أعملهم࣌ إنه بما يعملون خبير࣌', NULL, 234, 'local:warsh-text.json'),
  ('warsh-11-112', 'warsh', 11, 112, 'فَاسْتَقِمْ كَمَآ أُمِرْتَ وَمَن تَابَ مَعَكَ وَلَا تَطْغَوِاْ࣌ ࡴنَّهُۥ بِمَا تَعْمَلُونَ بَصِيرࣱ࣌', 'فاستقم كما أمرت ومن تاب معك ولا تطغوا࣌ ࡴنه بما تعملون بصير࣌', NULL, 234, 'local:warsh-text.json'),
  ('warsh-11-113', 'warsh', 11, 113, 'وَلَا تَرْكَنُوٓاْ إِلَى ࡰ۬لذِينَ ظَلَمُواْ فَتَمَسَّكُمُ ࡲ۬لنَّارُ࣌ وَمَا لَكُم مِّن دُونِ ࡴ۬للَّهِ مِنَ ࡰوْلِيَآءَ࣌ ثُمَّ لَا تُنصَرُونَ࣌', 'ولا تركنوا إلى ࡰلذين ظلموا فتمسكم ࡲلنار࣌ وما لكم من دون ࡴلله من ࡰولياء࣌ ثم لا تنصرون࣌', NULL, 234, 'local:warsh-text.json'),
  ('warsh-11-114', 'warsh', 11, 114, 'وَأَقِمِ ࡴ۬لصَّلَوٰةَ طَرَفَيِ ࡴ۬لنَّهٜارِ وَزُلَفاࣰ مِّنَ ࡰ۬ليْلِ࣌ إِنَّ ࡰ۬لْحَسَنَٰتِ يُذْهِبْنَ ࡰ۬لسَّيِّـَٔاتِ࣌ ذَٰلِكَ ذِكْرٜىٰ لِلذَّٰكِرِينَ࣌', 'وأقم ࡴلصلوة طرفي ࡴلنهار وزلفا من ࡰليل࣌ إن ࡰلحسنت يذهبن ࡰلسيات࣌ ذلك ذكرى للذكرين࣌', NULL, 234, 'local:warsh-text.json'),
  ('warsh-11-115', 'warsh', 11, 115, 'وَاصْبِرْ࣌ فَإِنَّ ࡰ۬للَّهَ لَا يُضِيعُ أَجْرَ ࡰ۬لْمُحْسِنِينَ࣌', 'واصبر࣌ فإن ࡰلله لا يضيع أجر ࡰلمحسنين࣌', NULL, 234, 'local:warsh-text.json'),
  ('warsh-11-116', 'warsh', 11, 116, 'فَلَوْلَا كَانَ مِنَ ࡰ۬لْقُرُونِ مِن قَبْلِكُمُۥٓ أُوْلُواْ بَقِيَّةࣲ يَنْهَوْنَ عَنِ ࡴ۬لْفَسَادِ فِے ࡴ۬لَارْضِ إِلَّا قَلِيلاࣰ مِّمَّنَ ࡰنجَيْنَا مِنْهُمْ࣌ وَاتَّبَعَ ࡰ۬لذِينَ ظَلَمُواْ مَآ أُتْرِفُواْ فِيهِ وَكَانُواْ مُجْرِمِينَ࣌', 'فلولا كان من ࡰلقرون من قبلكم أولوا بقية ينهون عن ࡴلفساد فے ࡴلارض إلا قليلا ممن ࡰنجينا منهم࣌ واتبع ࡰلذين ظلموا ما أترفوا فيه وكانوا مجرمين࣌', NULL, 234, 'local:warsh-text.json'),
  ('warsh-11-117', 'warsh', 11, 117, '۞ وَمَا كَانَ رَبُّكَ لِيُهْلِكَ ࡰ۬لْقُرٜىٰ بِظُلْمࣲ وَأَهْلُهَا مُصْلِحُونَ࣌', 'وما كان ربك ليهلك ࡰلقرى بظلم وأهلها مصلحون࣌', NULL, 234, 'local:warsh-text.json'),
  ('warsh-11-118', 'warsh', 11, 118, 'وَلَوْ شَآءَ رَبُّكَ لَجَعَلَ ࡰ۬لنَّاسَ أُمَّةࣰ وَٰحِدَةࣰ࣌ وَلَا يَزَالُونَ مُخْتَلِفِينَ إِلَّا مَن رَّحِمَ رَبُّكَ࣌ وَلِذَٰلِكَ خَلَقَهُمْ࣌ وَتَمَّتْ كَلِمَةُ رَبِّكَ لَأَمْلَأَنَّ جَهَنَّمَ مِنَ ࡰ۬لْجِنَّةِ وَالنَّاسِ أَجْمَعِينَ࣌', 'ولو شاء ربك لجعل ࡰلناس أمة وحدة࣌ ولا يزالون مختلفين إلا من رحم ربك࣌ ولذلك خلقهم࣌ وتمت كلمة ربك لأملأن جهنم من ࡰلجنة والناس أجمعين࣌', NULL, 235, 'local:warsh-text.json'),
  ('warsh-11-119', 'warsh', 11, 119, 'وَكُلّاࣰ نَّقُصُّ عَلَيْكَ مِنَ ࡰنۢبَآءِ ࡴ۬لرُّسُلِ مَا نُثَبِّتُ بِهِۦ فُؤَادَكَ࣌ وَجَآءَكَ فِے هَٰذِهِ ࡴ۬لْحَقُّ وَمَوْعِظَةࣱ وَذِكْرٜىٰ لِلْمُومِنِينَ࣌', 'وكلا نقص عليك من ࡰنباء ࡴلرسل ما نثبت به فؤادك࣌ وجاءك فے هذه ࡴلحق وموعظة وذكرى للمومنين࣌', NULL, 235, 'local:warsh-text.json'),
  ('warsh-11-120', 'warsh', 11, 120, 'وَقُل لِّلذِينَ لَا يُومِنُونَ ࡰٜعْمَلُواْ عَلَىٰ مَكَانَتِكُمُۥٓ إِنَّا عَٰمِلُونَ وَانتَظِرُوٓاْ إِنَّا مُنتَظِرُونَ࣌', 'وقل للذين لا يومنون ࡰعملوا على مكانتكم إنا عملون وانتظروا إنا منتظرون࣌', NULL, 235, 'local:warsh-text.json'),
  ('warsh-11-121', 'warsh', 11, 121, 'وَلِلهِ غَيْبُ ࡲ۬لسَّمَٰوَٰتِ وَالَارْضِ࣌ وَإِلَيْهِ يُرْجَعُ ࡲ۬لَامْرُ كُلُّهُۥ࣌ فَاعْبُدْهُ وَتَوَكَّلْ عَلَيْهِ࣌ وَمَا رَبُّكَ بِغَٰفِلٍ عَمَّا تَعْمَلُونَ࣌', 'ولله غيب ࡲلسموت والارض࣌ وإليه يرجع ࡲلامر كله࣌ فاعبده وتوكل عليه࣌ وما ربك بغفل عما تعملون࣌', NULL, 235, 'local:warsh-text.json'),
  ('warsh-12-1', 'warsh', 12, 1, 'أَلَٓرٜ࣌ تِلْكَ ءَايَٰتُ ࡲ۬لْكِتَٰبِ ࡴ۬لْمُبِينِ࣌', 'ألر࣌ تلك ءايت ࡲلكتب ࡴلمبين࣌', NULL, 235, 'local:warsh-text.json'),
  ('warsh-12-2', 'warsh', 12, 2, 'إِنَّآ أَنزَلْنَٰهُ قُرْءَٰناً عَرَبِيّاࣰ لَّعَلَّكُمْ تَعْقِلُونَ࣌', 'إنا أنزلنه قرءنا عربيا لعلكم تعقلون࣌', NULL, 235, 'local:warsh-text.json')
insert into public.ayahs (id, riwayah, surah_number, ayah_number, text, simple_text, juz, page, source) values
  ('warsh-12-3', 'warsh', 12, 3, 'نَحْنُ نَقُصُّ عَلَيْكَ أَحْسَنَ ࡰ۬لْقَصَصِ بِمَآ أَوْحَيْنَآ إِلَيْكَ هَٰذَا ࡰ۬لْقُرْءَانَ وَإِن كُنتَ مِن قَبْلِهِۦ لَمِنَ ࡰ۬لْغَٰفِلِينَ࣌', 'نحن نقص عليك أحسن ࡰلقصص بما أوحينا إليك هذا ࡰلقرءان وإن كنت من قبله لمن ࡰلغفلين࣌', NULL, 235, 'local:warsh-text.json'),
  ('warsh-12-4', 'warsh', 12, 4, 'إِذْ قَالَ يُوسُفُ لِأَبِيهِ يَٰٓأَبَتِ إِنِّے رَأَيْتُ أَحَدَ عَشَرَ كَوْكَباࣰ وَالشَّمْسَ وَالْقَمَرَ࣌ رَأَيْتُهُمْ لِے سَٰجِدِينَ࣌', 'إذ قال يوسف لأبيه يأبت إنے رأيت أحد عشر كوكبا والشمس والقمر࣌ رأيتهم لے سجدين࣌', NULL, 235, 'local:warsh-text.json'),
  ('warsh-12-5', 'warsh', 12, 5, 'قَالَ يَٰبُنَيِّ لَا تَقْصُصْ رُءْيٜاكَ عَلَىٰٓ إِخْوَتِكَ فَيَكِيدُواْ لَكَ كَيْداً࣌ ࡴنَّ ࡰ۬لشَّيْطَٰنَ لِلِانسَٰنِ عَدُوࣱّ مُّبِينࣱ࣌', 'قال يبني لا تقصص رءياك على إخوتك فيكيدوا لك كيدا࣌ ࡴن ࡰلشيطن للانسن عدو مبين࣌', NULL, 236, 'local:warsh-text.json'),
  ('warsh-12-6', 'warsh', 12, 6, 'وَكَذَٰلِكَ يَجْتَبِيكَ رَبُّكَ وَيُعَلِّمُكَ مِن تَاوِيلِ ࡴ۬لَاحَادِيثِ࣌ وَيُتِمُّ نِعْمَتَهُۥ عَلَيْكَ وَعَلَىٰٓ ءَالِ يَعْقُوبَ كَمَآ أَتَمَّهَا عَلَىٰٓ أَبَوَيْكَ مِن قَبْلُ إِبْرَٰهِيمَ وَإِسْحَٰقَ࣌ إِنَّ رَبَّكَ عَلِيمٌ حَكِيمࣱ࣌', 'وكذلك يجتبيك ربك ويعلمك من تاويل ࡴلاحاديث࣌ ويتم نعمته عليك وعلى ءال يعقوب كما أتمها على أبويك من قبل إبرهيم وإسحق࣌ إن ربك عليم حكيم࣌', NULL, 236, 'local:warsh-text.json'),
  ('warsh-12-7', 'warsh', 12, 7, 'لَّقَدْ كَانَ فِے يُوسُفَ وَإِخْوَتِهِۦٓ ءَايَٰتࣱ لِّلسَّآئِلِينَ࣌', 'لقد كان فے يوسف وإخوته ءايت للسائلين࣌', NULL, 236, 'local:warsh-text.json'),
  ('warsh-12-8', 'warsh', 12, 8, 'إِذْ قَالُواْ لَيُوسُفُ وَأَخُوهُ أَحَبُّ إِلَىٰٓ أَبِينَا مِنَّا وَنَحْنُ عُصْبَةٌ࣌ ࡴنَّ أَبَانَا لَفِے ضَلَٰلࣲ مُّبِينٍ࣌', 'إذ قالوا ليوسف وأخوه أحب إلى أبينا منا ونحن عصبة࣌ ࡴن أبانا لفے ضلل مبين࣌', NULL, 236, 'local:warsh-text.json'),
  ('warsh-12-9', 'warsh', 12, 9, 'ࡲ࢈قْتُلُواْ يُوسُفَ أَوِ ࡴٜطْرَحُوهُ أَرْضاࣰ يَخْلُ لَكُمْ وَجْهُ أَبِيكُمْ وَتَكُونُواْ مِنۢ بَعْدِهِۦ قَوْماࣰ صَٰلِحِينَ࣌', 'ࡲ࢈قتلوا يوسف أو ࡴطرحوه أرضا يخل لكم وجه أبيكم وتكونوا من بعده قوما صلحين࣌', NULL, 236, 'local:warsh-text.json'),
  ('warsh-12-10', 'warsh', 12, 10, '۞ قَالَ قَآئِلࣱ مِّنْهُمْ لَا تَقْتُلُواْ يُوسُفَ وَأَلْقُوهُ فِے غَيَٰبَٰتِ ࡴ۬لْجُبِّ يَلْتَقِطْهُ بَعْضُ ࡲ۬لسَّيَّارَةِ إِن كُنتُمْ فَٰعِلِينَ࣌', 'قال قائل منهم لا تقتلوا يوسف وألقوه فے غيبت ࡴلجب يلتقطه بعض ࡲلسيارة إن كنتم فعلين࣌', NULL, 236, 'local:warsh-text.json'),
  ('warsh-12-11', 'warsh', 12, 11, 'قَالُواْ يَٰٓأَبَانَا مَا لَكَ لَا تَامَـ۬نَّا عَلَىٰ يُوسُفَ وَإِنَّا لَهُۥ لَنَٰصِحُونَ࣌', 'قالوا يأبانا ما لك لا تامنا على يوسف وإنا له لنصحون࣌', NULL, 236, 'local:warsh-text.json'),
  ('warsh-12-12', 'warsh', 12, 12, 'أَرْسِلْهُ مَعَنَا غَداࣰ يَرْتَعِ وَيَلْعَبْ وَإِنَّا لَهُۥ لَحَٰفِظُونَ࣌', 'أرسله معنا غدا يرتع ويلعب وإنا له لحفظون࣌', NULL, 236, 'local:warsh-text.json'),
  ('warsh-12-13', 'warsh', 12, 13, 'قَالَ إِنِّے لَيُحْزِنُنِيَ أَن تَذْهَبُواْ بِهِۦ وَأَخَافُ أَنْ يَّاكُلَهُ ࡲ۬لذِّيبُ وَأَنتُمْ عَنْهُ غَٰفِلُونَ࣌', 'قال إنے ليحزنني أن تذهبوا به وأخاف أن ياكله ࡲلذيب وأنتم عنه غفلون࣌', NULL, 236, 'local:warsh-text.json'),
  ('warsh-12-14', 'warsh', 12, 14, 'قَالُواْ لَئِنَ ࡰكَلَهُ ࡲ۬لذِّيبُ وَنَحْنُ عُصْبَةٌ ࡴنَّآ إِذاࣰ لَّخَٰسِرُونَ࣌', 'قالوا لئن ࡰكله ࡲلذيب ونحن عصبة ࡴنا إذا لخسرون࣌', NULL, 236, 'local:warsh-text.json'),
  ('warsh-12-15', 'warsh', 12, 15, 'فَلَمَّا ذَهَبُواْ بِهِۦ وَأَجْمَعُوٓاْ أَنْ يَّجْعَلُوهُ فِے غَيَٰبَٰتِ ࡴ۬لْجُبِّ وَأَوْحَيْنَآ إِلَيْهِ لَتُنَبِّئَنَّهُم بِأَمْرِهِمْ هَٰذَا وَهُمْ لَا يَشْعُرُونَ࣌', 'فلما ذهبوا به وأجمعوا أن يجعلوه فے غيبت ࡴلجب وأوحينا إليه لتنبئنهم بأمرهم هذا وهم لا يشعرون࣌', NULL, 237, 'local:warsh-text.json'),
  ('warsh-12-16', 'warsh', 12, 16, 'وَجَآءُوٓ أَبَاهُمْ عِشَآءࣰ يَبْكُونَ', 'وجاءو أباهم عشاء يبكون', NULL, 237, 'local:warsh-text.json'),
  ('warsh-12-17', 'warsh', 12, 17, 'قَالُواْ يَٰٓأَبَانَآ إِنَّا ذَهَبْنَا نَسْتَبِقُ وَتَرَكْنَا يُوسُفَ عِندَ مَتَٰعِنَا فَأَكَلَهُ ࡲ۬لذِّيبُ࣌ وَمَآ أَنتَ بِمُومِنࣲ لَّنَا وَلَوْ كُنَّا صَٰدِقِينَ࣌', 'قالوا يأبانا إنا ذهبنا نستبق وتركنا يوسف عند متعنا فأكله ࡲلذيب࣌ وما أنت بمومن لنا ولو كنا صدقين࣌', NULL, 237, 'local:warsh-text.json'),
  ('warsh-12-18', 'warsh', 12, 18, 'وَجَآءُو عَلَىٰ قَمِيصِهِۦ بِدَمࣲ كَذِبࣲ࣌ قَالَ بَلْ سَوَّلَتْ لَكُمُۥٓ أَنفُسُكُمُۥٓ أَمْراࣰ࣌ فَصَبْرࣱ جَمِيلࣱ࣌ وَاللَّهُ ࡲ۬لْمُسْتَعَانُ عَلَىٰ مَا تَصِفُونَ࣌', 'وجاءو على قميصه بدم كذب࣌ قال بل سولت لكم أنفسكم أمرا࣌ فصبر جميل࣌ والله ࡲلمستعان على ما تصفون࣌', NULL, 237, 'local:warsh-text.json'),
  ('warsh-12-19', 'warsh', 12, 19, 'وَجَآءَتْ سَيَّارَةࣱ فَأَرْسَلُواْ وَارِدَهُمْ فَأَدْلٜىٰ دَلْوَهُۥ قَالَ يَٰبُشْرٰٜيَ هَٰذَا غُلَٰمࣱ࣌ وَأَسَرُّوهُ بِضَٰعَةࣰ࣌ وَاللَّهُ عَلِيمُۢ بِمَا يَعْمَلُونَ࣌', 'وجاءت سيارة فأرسلوا واردهم فأدلى دلوه قال يبشري هذا غلم࣌ وأسروه بضعة࣌ والله عليم بما يعملون࣌', NULL, 237, 'local:warsh-text.json'),
  ('warsh-12-20', 'warsh', 12, 20, 'وَشَرَوْهُ بِثَمَنِۢ بَخْسࣲ دَرَٰهِمَ مَعْدُودَةࣲ وَكَانُواْ فِيهِ مِنَ ࡰ۬لزَّٰهِدِينَ࣌', 'وشروه بثمن بخس درهم معدودة وكانوا فيه من ࡰلزهدين࣌', NULL, 237, 'local:warsh-text.json'),
  ('warsh-12-21', 'warsh', 12, 21, 'وَقَالَ ࡰ۬لذِے ࡴٜشْتَرٜيٰهُ مِن مِّصْرَ لِامْرَأَتِهِۦٓ أَكْرِمِے مَثْوٜيٰهُ عَسٜىٰٓ أَنْ يَّنفَعَنَآ أَوْ نَتَّخِذَهُۥ وَلَداࣰ࣌ وَكَذَٰلِكَ مَكَّنَّا لِيُوسُفَ فِے ࡴ۬لَارْضِ وَلِنُعَلِّمَهُۥ مِن تَاوِيلِ ࡴ۬لَاحَادِيثِ࣌ وَاللَّهُ غَالِبٌ عَلَىٰٓ أَمْرِهِۦ࣌ وَلَٰكِنَّ أَكْثَرَ ࡰ۬لنَّاسِ لَا يَعْلَمُونَ࣌', 'وقال ࡰلذے ࡴشتريه من مصر لامرأته أكرمے مثويه عسى أن ينفعنا أو نتخذه ولدا࣌ وكذلك مكنا ليوسف فے ࡴلارض ولنعلمه من تاويل ࡴلاحاديث࣌ والله غالب على أمره࣌ ولكن أكثر ࡰلناس لا يعلمون࣌', NULL, 237, 'local:warsh-text.json'),
  ('warsh-12-22', 'warsh', 12, 22, 'وَلَمَّا بَلَغَ أَشُدَّهُۥٓ ءَاتَيْنَٰهُ حُكْماࣰ وَعِلْماࣰ࣌ وَكَذَٰلِكَ نَجْزِے ࡴ۬لْمُحْسِنِينَ࣌', 'ولما بلغ أشده ءاتينه حكما وعلما࣌ وكذلك نجزے ࡴلمحسنين࣌', NULL, 237, 'local:warsh-text.json'),
  ('warsh-12-23', 'warsh', 12, 23, '۞ وَرَٰوَدَتْهُ ࡲ۬لتِے هُوَ فِے بَيْتِهَا عَن نَّفْسِهِۦ وَغَلَّقَتِ ࡴ۬لَابْوَٰبَ وَقَالَتْ هِيتَ لَكَ࣌ قَالَ مَعَاذَ ࡰ۬للَّهِ࣌ إِنَّهُۥ رَبِّيَ أَحْسَنَ مَثْوٜايَ࣌ إِنَّهُۥ لَا يُفْلِحُ ࡲ۬لظَّٰلِمُونَ࣌', 'ورودته ࡲلتے هو فے بيتها عن نفسه وغلقت ࡴلابوب وقالت هيت لك࣌ قال معاذ ࡰلله࣌ إنه ربي أحسن مثواي࣌ إنه لا يفلح ࡲلظلمون࣌', NULL, 238, 'local:warsh-text.json'),
  ('warsh-12-24', 'warsh', 12, 24, 'وَلَقَدْ هَمَّتْ بِهِۦ࣌ وَهَمَّ بِهَا لَوْلَآ أَن رّٜءٜا بُرْهَٰنَ رَبِّهِۦ࣌ كَذَٰلِكَ لِنَصْرِفَ عَنْهُ ࡲ۬لسُّوٓءَ وَالْفَحْشَآءَ࣌ ࡹنَّهُۥ مِنْ عِبَادِنَا ࡰ۬لْمُخْلَصِينَ࣌', 'ولقد همت به࣌ وهم بها لولا أن رءا برهن ربه࣌ كذلك لنصرف عنه ࡲلسوء والفحشاء࣌ ࡹنه من عبادنا ࡰلمخلصين࣌', NULL, 238, 'local:warsh-text.json'),
  ('warsh-12-25', 'warsh', 12, 25, 'وَاسْتَبَقَا ࡰ۬لْبَابَ وَقَدَّتْ قَمِيصَهُۥ مِن دُبُرࣲ وَأَلْفَيَا سَيِّدَهَا لَدَا ࡰ۬لْبَابِ࣌ قَالَتْ مَا جَزَآءُ مَنَ ࡰرَادَ بِأَهْلِكَ سُوٓءاً ࡴلَّآ أَنْ يُّسْجَنَ أَوْ عَذَابٌ ࡰلِيمࣱ࣌', 'واستبقا ࡰلباب وقدت قميصه من دبر وألفيا سيدها لدا ࡰلباب࣌ قالت ما جزاء من ࡰراد بأهلك سوءا ࡴلا أن يسجن أو عذاب ࡰليم࣌', NULL, 238, 'local:warsh-text.json'),
  ('warsh-12-26', 'warsh', 12, 26, 'قَالَ هِيَ رَٰوَدَتْنِے عَن نَّفْسِے࣌ وَشَهِدَ شَاهِدࣱ مِّنَ ࡰهْلِهَآ إِن كَانَ قَمِيصُهُۥ قُدَّ مِن قُبُلࣲ فَصَدَقَتْ وَهُوَ مِنَ ࡰ۬لْكَٰذِبِينَ', 'قال هي رودتنے عن نفسے࣌ وشهد شاهد من ࡰهلها إن كان قميصه قد من قبل فصدقت وهو من ࡰلكذبين', NULL, 238, 'local:warsh-text.json'),
  ('warsh-12-27', 'warsh', 12, 27, 'وَإِن كَانَ قَمِيصُهُۥ قُدَّ مِن دُبُرࣲ فَكَذَبَتْ࣌ وَهُوَ مِنَ ࡰ۬لصَّٰدِقِينَ࣌', 'وإن كان قميصه قد من دبر فكذبت࣌ وهو من ࡰلصدقين࣌', NULL, 238, 'local:warsh-text.json'),
  ('warsh-12-28', 'warsh', 12, 28, 'فَلَمَّا رٜءٜا قَمِيصَهُۥ قُدَّ مِن دُبُرࣲ قَالَ إِنَّهُۥ مِن كَيْدِكُنَّ إِنَّ كَيْدَكُنَّ عَظِيمࣱ࣌', 'فلما رءا قميصه قد من دبر قال إنه من كيدكن إن كيدكن عظيم࣌', NULL, 238, 'local:warsh-text.json'),
  ('warsh-12-29', 'warsh', 12, 29, 'يُوسُفُ أَعْرِضْ عَنْ هَٰذَا࣌ وَاسْتَغْفِرِے لِذَنۢبِكِ إِنَّكِ كُنتِ مِنَ ࡰ۬لْخَاطِـِٕينَ࣌', 'يوسف أعرض عن هذا࣌ واستغفرے لذنبك إنك كنت من ࡰلخاطين࣌', NULL, 238, 'local:warsh-text.json'),
  ('warsh-12-30', 'warsh', 12, 30, 'وَقَالَ نِسْوَةࣱ فِے ࡴ۬لْمَدِينَةِ ࡴٜمْرَأَتُ ࡲ۬لْعَزِيزِ تُرَٰوِدُ فَتٜيٰهَا عَن نَّفْسِهِۦ قَدْ شَغَفَهَا حُبّاً࣌ ࡴنَّا لَنَرٜيٰهَا فِے ضَلَٰلࣲ مُّبِينࣲ࣌', 'وقال نسوة فے ࡴلمدينة ࡴمرأت ࡲلعزيز ترود فتيها عن نفسه قد شغفها حبا࣌ ࡴنا لنريها فے ضلل مبين࣌', NULL, 238, 'local:warsh-text.json'),
  ('warsh-12-31', 'warsh', 12, 31, 'فَلَمَّا سَمِعَتْ بِمَكْرِهِنَّ أَرْسَلَتِ ࡴلَيْهِنَّ وَأَعْتَدَتْ لَهُنَّ مُتَّكَـٔاࣰ وَءَاتَتْ كُلَّ وَٰحِدَةࣲ مِّنْهُنَّ سِكِّيناࣰ وَقَالَتُ ࡲ࢈خْرُجْ عَلَيْهِنَّ࣌ فَلَمَّا رَأَيْنَهُۥٓ أَكْبَرْنَهُۥ وَقَطَّعْنَ أَيْدِيَهُنَّ وَقُلْنَ حَٰشَ لِلهِ مَا هَٰذَا بَشَراً࣌ ࡴنْ هَٰذَآ إِلَّا مَلَكࣱ كَرِيمࣱ࣌', 'فلما سمعت بمكرهن أرسلت ࡴليهن وأعتدت لهن متكا وءاتت كل وحدة منهن سكينا وقالت ࡲ࢈خرج عليهن࣌ فلما رأينه أكبرنه وقطعن أيديهن وقلن حش لله ما هذا بشرا࣌ ࡴن هذا إلا ملك كريم࣌', NULL, 239, 'local:warsh-text.json'),
  ('warsh-12-32', 'warsh', 12, 32, 'قَالَتْ فَذَٰلِكُنَّ ࡰ۬لذِے لُمْتُنَّنِے فِيهِ࣌ وَلَقَدْ رَٰوَدتُّهُۥ عَن نَّفْسِهِۦ فَاسْتَعْصَمَ࣌ وَلَئِن لَّمْ يَفْعَلْ مَآ ءَامُرُهُۥ لَيُسْجَنَنَّ وَلَيَكُوناࣰ مِّنَ ࡰ۬لصَّٰغِرِينَ࣌', 'قالت فذلكن ࡰلذے لمتننے فيه࣌ ولقد رودته عن نفسه فاستعصم࣌ ولئن لم يفعل ما ءامره ليسجنن وليكونا من ࡰلصغرين࣌', NULL, 239, 'local:warsh-text.json'),
  ('warsh-12-33', 'warsh', 12, 33, '۞ قَالَ رَبِّ ࡴ۬لسِّجْنُ أَحَبُّ إِلَيَّ مِمَّا يَدْعُونَنِےٓ إِلَيْهِ وَإِلَّا تَصْرِفْ عَنِّے كَيْدَهُنَّ أَصْبُ إِلَيْهِنَّ وَأَكُن مِّنَ ࡰ۬لْجَٰهِلِينَ࣌', 'قال رب ࡴلسجن أحب إلي مما يدعوننے إليه وإلا تصرف عنے كيدهن أصب إليهن وأكن من ࡰلجهلين࣌', NULL, 239, 'local:warsh-text.json'),
  ('warsh-12-34', 'warsh', 12, 34, 'فَاسْتَجَابَ لَهُۥ رَبُّهُۥ فَصَرَفَ عَنْهُ كَيْدَهُنَّ࣌ إِنَّهُۥ هُوَ ࡰ۬لسَّمِيعُ ࡲ۬لْعَلِيمُ࣌', 'فاستجاب له ربه فصرف عنه كيدهن࣌ إنه هو ࡰلسميع ࡲلعليم࣌', NULL, 239, 'local:warsh-text.json'),
  ('warsh-12-35', 'warsh', 12, 35, 'ثُمَّ بَدَا لَهُم مِّنۢ بَعْدِ مَا رَأَوُاْ ࡲ۬لَايَٰتِ لَيَسْجُنُنَّهُۥ حَتَّىٰ حِينࣲ࣌', 'ثم بدا لهم من بعد ما رأوا ࡲلايت ليسجننه حتى حين࣌', NULL, 239, 'local:warsh-text.json'),
  ('warsh-12-36', 'warsh', 12, 36, 'وَدَخَلَ مَعَهُ ࡲ۬لسِّجْنَ فَتَيَٰنِ࣌ قَالَ أَحَدُهُمَآ إِنِّيَ أَرٜيٰنِيَ أَعْصِرُ خَمْراࣰ࣌ وَقَالَ ࡰ۬لَاخَرُ إِنِّيَ أَرٜيٰنِيَ أَحْمِلُ فَوْقَ رَأْسِے خُبْزاࣰ تَاكُلُ ࡲ۬لطَّيْرُ مِنْهُ࣌ نَبِّئْنَا بِتَاوِيلِهِۦٓ إِنَّا نَرٜيٰكَ مِنَ ࡰ۬لْمُحْسِنِينَ࣌', 'ودخل معه ࡲلسجن فتين࣌ قال أحدهما إني أريني أعصر خمرا࣌ وقال ࡰلاخر إني أريني أحمل فوق رأسے خبزا تاكل ࡲلطير منه࣌ نبئنا بتاويله إنا نريك من ࡰلمحسنين࣌', NULL, 239, 'local:warsh-text.json'),
  ('warsh-12-37', 'warsh', 12, 37, 'قَالَ لَا يَاتِيكُمَا طَعَامࣱ تُرْزَقَٰنِهِۦٓ إِلَّا نَبَّأْتُكُمَا بِتَاوِيلِهِۦ قَبْلَ أَنْ يَّاتِيَكُمَا࣌ ذَٰلِكُمَا مِمَّا عَلَّمَنِے رَبِّيَ࣌ إِنِّے تَرَكْتُ مِلَّةَ قَوْمࣲ لَّا يُومِنُونَ بِاللَّهِ وَهُم بِالَاخِرَةِ هُمْ كَٰفِرُونَ࣌', 'قال لا ياتيكما طعام ترزقنه إلا نبأتكما بتاويله قبل أن ياتيكما࣌ ذلكما مما علمنے ربي࣌ إنے تركت ملة قوم لا يومنون بالله وهم بالاخرة هم كفرون࣌', NULL, 239, 'local:warsh-text.json'),
  ('warsh-12-38', 'warsh', 12, 38, 'وَاتَّبَعْتُ مِلَّةَ ءَابَآءِيَ إِبْرَٰهِيمَ وَإِسْحَٰقَ وَيَعْقُوبَ࣌ مَا كَانَ لَنَآ أَن نُّشْرِكَ بِاللَّهِ مِن شَےْءࣲ࣌ ذَٰلِكَ مِن فَضْلِ ࡴ۬للَّهِ عَلَيْنَا وَعَلَى ࡰ۬لنَّاسِ࣌ وَلَٰكِنَّ أَكْثَرَ ࡰ۬لنَّاسِ لَا يَشْكُرُونَ࣌', 'واتبعت ملة ءاباءي إبرهيم وإسحق ويعقوب࣌ ما كان لنا أن نشرك بالله من شےء࣌ ذلك من فضل ࡴلله علينا وعلى ࡰلناس࣌ ولكن أكثر ࡰلناس لا يشكرون࣌', NULL, 240, 'local:warsh-text.json'),
  ('warsh-12-39', 'warsh', 12, 39, 'يَٰصَٰحِبَيِ ࡴ۬لسِّجْنِ ءَآرْبَابࣱ مُّتَفَرِّقُونَ خَيْرٌ ࡰمِ ࡴ۬للَّهُ ࡲ۬لْوَٰحِدُ ࡲ۬لْقَهَّارُ࣌', 'يصحبي ࡴلسجن ءارباب متفرقون خير ࡰم ࡴلله ࡲلوحد ࡲلقهار࣌', NULL, 240, 'local:warsh-text.json'),
  ('warsh-12-40', 'warsh', 12, 40, 'مَا تَعْبُدُونَ مِن دُونِهِۦٓ إِلَّآ أَسْمَآءࣰ سَمَّيْتُمُوهَآ أَنتُمْ وَءَابَآؤُكُم مَّآ أَنزَلَ ࡰ۬للَّهُ بِهَا مِن سُلْطَٰنٍ࣌ ࡴنِ ࡴ۬لْحُكْمُ إِلَّا لِلهِ࣌ أَمَرَ أَلَّا تَعْبُدُوٓاْ إِلَّآ إِيَّاهُ࣌ ذَٰلِكَ ࡰ۬لدِّينُ ࡲ۬لْقَيِّمُ࣌ وَلَٰكِنَّ أَكْثَرَ ࡰ۬لنَّاسِ لَا يَعْلَمُونَ࣌', 'ما تعبدون من دونه إلا أسماء سميتموها أنتم وءاباؤكم ما أنزل ࡰلله بها من سلطن࣌ ࡴن ࡴلحكم إلا لله࣌ أمر ألا تعبدوا إلا إياه࣌ ذلك ࡰلدين ࡲلقيم࣌ ولكن أكثر ࡰلناس لا يعلمون࣌', NULL, 240, 'local:warsh-text.json'),
  ('warsh-12-41', 'warsh', 12, 41, 'يَٰصَٰحِبَيِ ࡴ۬لسِّجْنِ أَمَّآ أَحَدُكُمَا فَيَسْقِے رَبَّهُۥ خَمْراࣰ࣌ وَأَمَّا ࡰ۬لَاخَرُ فَيُصْلَبُ فَتَاكُلُ ࡲ۬لطَّيْرُ مِن رَّأْسِهِۦ࣌ قُضِيَ ࡰ۬لَامْرُ ࡲ۬لذِے فِيهِ تَسْتَفْتِيَٰنِ࣌', 'يصحبي ࡴلسجن أما أحدكما فيسقے ربه خمرا࣌ وأما ࡰلاخر فيصلب فتاكل ࡲلطير من رأسه࣌ قضي ࡰلامر ࡲلذے فيه تستفتين࣌', NULL, 240, 'local:warsh-text.json'),
  ('warsh-12-42', 'warsh', 12, 42, '۞ وَقَالَ لِلذِے ظَنَّ أَنَّهُۥ نَاجࣲ مِّنْهُمَا ࡸَذْكُرْنِے عِندَ رَبِّكَ࣌ فَأَنسٜيٰهُ ࡲ۬لشَّيْطَٰنُ ذِكْرَ رَبِّهِۦ فَلَبِثَ فِے ࡴ۬لسِّجْنِ بِضْعَ سِنِينَ࣌', 'وقال للذے ظن أنه ناج منهما ࡸذكرنے عند ربك࣌ فأنسيه ࡲلشيطن ذكر ربه فلبث فے ࡴلسجن بضع سنين࣌', NULL, 240, 'local:warsh-text.json'),
  ('warsh-12-43', 'warsh', 12, 43, 'وَقَالَ ࡰ۬لْمَلِكُ إِنِّيَ أَرٜىٰ سَبْعَ بَقَرَٰتࣲ سِمَانࣲ يَاكُلُهُنَّ سَبْعٌ عِجَافࣱ وَسَبْعَ سُنۢبُلَٰتٍ خُضْرࣲ وَأُخَرَ يَابِسَٰتࣲ࣌ يَٰٓأَيُّهَا ࡰ۬لْمَلَأُ ࡶَفْتُونِے فِے رُءْيٜـٰيَ إِن كُنتُمْ لِلرُّءْيٜا تَعْبُرُونَ࣌', 'وقال ࡰلملك إني أرى سبع بقرت سمان ياكلهن سبع عجاف وسبع سنبلت خضر وأخر يابست࣌ يأيها ࡰلملأ ࡶفتونے فے رءيي إن كنتم للرءيا تعبرون࣌', NULL, 240, 'local:warsh-text.json'),
  ('warsh-12-44', 'warsh', 12, 44, 'قَالُوٓاْ أَضْغَٰثُ أَحْلَٰمࣲ࣌ وَمَا نَحْنُ بِتَاوِيلِ ࡴ۬لَاحْلَٰمِ بِعَٰلِمِينَ࣌', 'قالوا أضغث أحلم࣌ وما نحن بتاويل ࡴلاحلم بعلمين࣌', NULL, 241, 'local:warsh-text.json'),
  ('warsh-12-45', 'warsh', 12, 45, 'وَقَالَ ࡰ۬لذِے نَجَا مِنْهُمَا وَادَّكَرَ بَعْدَ أُمَّةٍ ࡰنَآ أُنَبِّئُكُم بِتَاوِيلِهِۦ فَأَرْسِلُونِ࣌', 'وقال ࡰلذے نجا منهما وادكر بعد أمة ࡰنا أنبئكم بتاويله فأرسلون࣌', NULL, 241, 'local:warsh-text.json'),
  ('warsh-12-46', 'warsh', 12, 46, 'يُوسُفُ أَيُّهَا ࡰ۬لصِّدِّيقُ أَفْتِنَا فِے سَبْعِ بَقَرَٰتࣲ سِمَانࣲ يَاكُلُهُنَّ سَبْعٌ عِجَافࣱ وَسَبْعِ سُنۢبُلَٰتٍ خُضْرࣲ وَأُخَرَ يَابِسَٰتࣲ لَّعَلِّيَ أَرْجِعُ إِلَى ࡰ۬لنَّاسِ لَعَلَّهُمْ يَعْلَمُونَ࣌', 'يوسف أيها ࡰلصديق أفتنا فے سبع بقرت سمان ياكلهن سبع عجاف وسبع سنبلت خضر وأخر يابست لعلي أرجع إلى ࡰلناس لعلهم يعلمون࣌', NULL, 241, 'local:warsh-text.json'),
  ('warsh-12-47', 'warsh', 12, 47, 'قَالَ تَزْرَعُونَ سَبْعَ سِنِينَ دَأْباࣰ࣌ فَمَا حَصَدتُّمْ فَذَرُوهُ فِے سُنۢبُلِهِۦٓ إِلَّا قَلِيلاࣰ مِّمَّا تَاكُلُونَ࣌', 'قال تزرعون سبع سنين دأبا࣌ فما حصدتم فذروه فے سنبله إلا قليلا مما تاكلون࣌', NULL, 241, 'local:warsh-text.json'),
  ('warsh-12-48', 'warsh', 12, 48, 'ثُمَّ يَاتِے مِنۢ بَعْدِ ذَٰلِكَ سَبْعࣱ شِدَادࣱ يَاكُلْنَ مَا قَدَّمْتُمْ لَهُنَّ إِلَّا قَلِيلاࣰ مِّمَّا تُحْصِنُونَ࣌', 'ثم ياتے من بعد ذلك سبع شداد ياكلن ما قدمتم لهن إلا قليلا مما تحصنون࣌', NULL, 241, 'local:warsh-text.json'),
  ('warsh-12-49', 'warsh', 12, 49, 'ثُمَّ يَاتِے مِنۢ بَعْدِ ذَٰلِكَ عَامࣱ فِيهِ يُغَاثُ ࡲ۬لنَّاسُ وَفِيهِ يَعْصِرُونَ࣌', 'ثم ياتے من بعد ذلك عام فيه يغاث ࡲلناس وفيه يعصرون࣌', NULL, 241, 'local:warsh-text.json'),
  ('warsh-12-50', 'warsh', 12, 50, 'وَقَالَ ࡰ۬لْمَلِكُ ࡲٜيتُونِے بِهِۦ࣌ فَلَمَّا جَآءَهُ ࡲ۬لرَّسُولُ قَالَ ࡰٜرْجِعِ ࡴلَىٰ رَبِّكَ فَسْـَٔلْهُ مَا بَالُ ࡲ۬لنِّسْوَةِ ࡴ۬لتِے قَطَّعْنَ أَيْدِيَهُنَّ࣌ إِنَّ رَبِّے بِكَيْدِهِنَّ عَلِيمࣱ࣌', 'وقال ࡰلملك ࡲيتونے به࣌ فلما جاءه ࡲلرسول قال ࡰرجع ࡴلى ربك فسله ما بال ࡲلنسوة ࡴلتے قطعن أيديهن࣌ إن ربے بكيدهن عليم࣌', NULL, 241, 'local:warsh-text.json'),
  ('warsh-12-51', 'warsh', 12, 51, 'قَالَ مَا خَطْبُكُنَّ إِذْ رَٰوَدتُّنَّ يُوسُفَ عَن نَّفْسِهِۦ࣌ قُلْنَ حَٰشَ لِلهِ مَا عَلِمْنَا عَلَيْهِ مِن سُوٓءࣲ࣌ قَالَتِ ࡴٜمْرَأَتُ ࡲ۬لْعَزِيزِ ࡴ۬لَٰنَ حَصْحَصَ ࡰ۬لْحَقُّ أَنَا رَٰوَدتُّهُۥ عَن نَّفْسِهِۦ وَإِنَّهُۥ لَمِنَ ࡰ۬لصَّٰدِقِينَ࣌', 'قال ما خطبكن إذ رودتن يوسف عن نفسه࣌ قلن حش لله ما علمنا عليه من سوء࣌ قالت ࡴمرأت ࡲلعزيز ࡴلن حصحص ࡰلحق أنا رودته عن نفسه وإنه لمن ࡰلصدقين࣌', NULL, 241, 'local:warsh-text.json'),
  ('warsh-12-52', 'warsh', 12, 52, 'ذَٰلِكَ لِيَعْلَمَ أَنِّے لَمَ ࡰخُنْهُ بِالْغَيْبِ وَأَنَّ ࡰ۬للَّهَ لَا يَهْدِے كَيْدَ ࡰ۬لْخَآئِنِينَ࣌', 'ذلك ليعلم أنے لم ࡰخنه بالغيب وأن ࡰلله لا يهدے كيد ࡰلخائنين࣌', NULL, 241, 'local:warsh-text.json'),
  ('warsh-12-53', 'warsh', 12, 53, '۞ وَمَآ أُبَرِّۓُ نَفْسِيَ࣌ إِنَّ ࡰ۬لنَّفْسَ لَأَمَّارَةُۢ بِالسُّوٓءِ الَّا مَا رَحِمَ رَبِّيَ࣌ إِنَّ رَبِّے غَفُورࣱ رَّحِيمࣱ࣌', 'وما أبرے نفسي࣌ إن ࡰلنفس لأمارة بالسوء الا ما رحم ربي࣌ إن ربے غفور رحيم࣌', NULL, 242, 'local:warsh-text.json'),
  ('warsh-12-54', 'warsh', 12, 54, 'وَقَالَ ࡰ۬لْمَلِكُ ࡲٜيتُونِے بِهِۦٓ أَسْتَخْلِصْهُ لِنَفْسِے࣌ فَلَمَّا كَلَّمَهُۥ قَالَ إِنَّكَ ࡰ۬لْيَوْمَ لَدَيْنَا مَكِينٌ ࡰمِينࣱ࣌', 'وقال ࡰلملك ࡲيتونے به أستخلصه لنفسے࣌ فلما كلمه قال إنك ࡰليوم لدينا مكين ࡰمين࣌', NULL, 242, 'local:warsh-text.json'),
  ('warsh-12-55', 'warsh', 12, 55, 'قَالَ ࡰٜجْعَلْنِے عَلَىٰ خَزَآئِنِ ࡴ۬لَارْضِ إِنِّے حَفِيظٌ عَلِيمࣱ࣌', 'قال ࡰجعلنے على خزائن ࡴلارض إنے حفيظ عليم࣌', NULL, 242, 'local:warsh-text.json'),
  ('warsh-12-56', 'warsh', 12, 56, 'وَكَذَٰلِكَ مَكَّنَّا لِيُوسُفَ فِے ࡴ۬لَارْضِ يَتَبَوَّأُ مِنْهَا حَيْثُ يَشَآءُ࣌ نُصِيبُ بِرَحْمَتِنَا مَن نَّشَآءُ وَلَا نُضِيعُ أَجْرَ ࡰ۬لْمُحْسِنِينَ࣌', 'وكذلك مكنا ليوسف فے ࡴلارض يتبوأ منها حيث يشاء࣌ نصيب برحمتنا من نشاء ولا نضيع أجر ࡰلمحسنين࣌', NULL, 242, 'local:warsh-text.json'),
  ('warsh-12-57', 'warsh', 12, 57, 'وَلَأَجْرُ ࡲ۬لَاخِرَةِ خَيْرࣱ لِّلذِينَ ءَامَنُواْ وَكَانُواْ يَتَّقُونَ࣌', 'ولأجر ࡲلاخرة خير للذين ءامنوا وكانوا يتقون࣌', NULL, 242, 'local:warsh-text.json'),
  ('warsh-12-58', 'warsh', 12, 58, 'وَجَآءَ ࡹخْوَةُ يُوسُفَ فَدَخَلُواْ عَلَيْهِ فَعَرَفَهُمْ وَهُمْ لَهُۥ مُنكِرُونَ࣌', 'وجاء ࡹخوة يوسف فدخلوا عليه فعرفهم وهم له منكرون࣌', NULL, 242, 'local:warsh-text.json'),
  ('warsh-12-59', 'warsh', 12, 59, 'وَلَمَّا جَهَّزَهُم بِجَهَازِهِمْ قَالَ ࡰٜيتُونِے بِأَخࣲ لَّكُم مِّنَ ࡰبِيكُمُۥٓ࣌ أَلَا تَرَوْنَ أَنِّيَ أُوفِے ࡴ۬لْكَيْلَ وَأَنَا خَيْرُ ࡲ۬لْمُنزِلِينَ࣌', 'ولما جهزهم بجهازهم قال ࡰيتونے بأخ لكم من ࡰبيكم࣌ ألا ترون أني أوفے ࡴلكيل وأنا خير ࡲلمنزلين࣌', NULL, 242, 'local:warsh-text.json'),
  ('warsh-12-60', 'warsh', 12, 60, 'فَإِن لَّمْ تَاتُونِے بِهِۦ فَلَا كَيْلَ لَكُمْ عِندِے وَلَا تَقْرَبُونِ࣌', 'فإن لم تاتونے به فلا كيل لكم عندے ولا تقربون࣌', NULL, 242, 'local:warsh-text.json'),
  ('warsh-12-61', 'warsh', 12, 61, 'قَالُواْ سَنُرَٰوِدُ عَنْهُ أَبَاهُ وَإِنَّا لَفَٰعِلُونَ࣌', 'قالوا سنرود عنه أباه وإنا لفعلون࣌', NULL, 242, 'local:warsh-text.json'),
  ('warsh-12-62', 'warsh', 12, 62, 'وَقَالَ لِفِتْيَتِهِ ࡴٜجْعَلُواْ بِضَٰعَتَهُمْ فِے رِحَالِهِمْ لَعَلَّهُمْ يَعْرِفُونَهَآ إِذَا ࡰٜنقَلَبُوٓاْ إِلَىٰٓ أَهْلِهِمْ لَعَلَّهُمْ يَرْجِعُونَ࣌', 'وقال لفتيته ࡴجعلوا بضعتهم فے رحالهم لعلهم يعرفونها إذا ࡰنقلبوا إلى أهلهم لعلهم يرجعون࣌', NULL, 242, 'local:warsh-text.json'),
  ('warsh-12-63', 'warsh', 12, 63, 'فَلَمَّا رَجَعُوٓاْ إِلَىٰٓ أَبِيهِمْ قَالُواْ يَٰٓأَبَانَا مُنِعَ مِنَّا ࡰ۬لْكَيْلُ فَأَرْسِلْ مَعَنَآ أَخَانَا نَكْتَلْ وَإِنَّا لَهُۥ لَحَٰفِظُونَ࣌', 'فلما رجعوا إلى أبيهم قالوا يأبانا منع منا ࡰلكيل فأرسل معنا أخانا نكتل وإنا له لحفظون࣌', NULL, 242, 'local:warsh-text.json'),
  ('warsh-12-64', 'warsh', 12, 64, 'قَالَ هَلَ اٰمَنُكُمْ عَلَيْهِ إِلَّا كَمَآ أَمِنتُكُمْ عَلَىٰٓ أَخِيهِ مِن قَبْلُ࣌ فَاللَّهُ خَيْرٌ حِفْظاࣰ࣌ وَهُوَ أَرْحَمُ ࡲ۬لرَّٰحِمِينَ࣌', 'قال هل امنكم عليه إلا كما أمنتكم على أخيه من قبل࣌ فالله خير حفظا࣌ وهو أرحم ࡲلرحمين࣌', NULL, 243, 'local:warsh-text.json'),
  ('warsh-12-65', 'warsh', 12, 65, 'وَلَمَّا فَتَحُواْ مَتَٰعَهُمْ وَجَدُواْ بِضَٰعَتَهُمْ رُدَّتِ ࡴلَيْهِمْ قَالُواْ يَٰٓأَبَانَا مَا نَبْغِے࣌ هَٰذِهِۦ بِضَٰعَتُنَا رُدَّتِ ࡴلَيْنَا وَنَمِيرُ أَهْلَنَا وَنَحْفَظُ أَخَانَا وَنَزْدَادُ كَيْلَ بَعِيرࣲ࣌ ذَٰلِكَ كَيْلࣱ يَسِيرࣱ࣌', 'ولما فتحوا متعهم وجدوا بضعتهم ردت ࡴليهم قالوا يأبانا ما نبغے࣌ هذه بضعتنا ردت ࡴلينا ونمير أهلنا ونحفظ أخانا ونزداد كيل بعير࣌ ذلك كيل يسير࣌', NULL, 243, 'local:warsh-text.json'),
  ('warsh-12-66', 'warsh', 12, 66, '۞ قَالَ لَنُ ࡳرْسِلَهُۥ مَعَكُمْ حَتَّىٰ تُوتُونِ مَوْثِقاࣰ مِّنَ ࡰ۬للَّهِ لَتَاتُنَّنِے بِهِۦٓ إِلَّآ أَنْ يُّحَاطَ بِكُمْ࣌ فَلَمَّآ ءَاتَوْهُ مَوْثِقَهُمْ قَالَ ࡰ۬للَّهُ عَلَىٰ مَا نَقُولُ وَكِيلࣱ࣌', 'قال لن ࡳرسله معكم حتى توتون موثقا من ࡰلله لتاتننے به إلا أن يحاط بكم࣌ فلما ءاتوه موثقهم قال ࡰلله على ما نقول وكيل࣌', NULL, 243, 'local:warsh-text.json'),
  ('warsh-12-67', 'warsh', 12, 67, 'وَقَالَ يَٰبَنِيَّ لَا تَدْخُلُواْ مِنۢ بَابࣲ وَٰحِدࣲ وَادْخُلُواْ مِنَ ࡰبْوَٰبࣲ مُّتَفَرِّقَةࣲ࣌ وَمَآ أُغْنِے عَنكُم مِّنَ ࡰ۬للَّهِ مِن شَےْءٍ࣌ ࡴنِ ࡴ۬لْحُكْمُ إِلَّا لِلهِ࣌ عَلَيْهِ تَوَكَّلْتُ࣌ وَعَلَيْهِ فَلْيَتَوَكَّلِ ࡴ۬لْمُتَوَكِّلُونَ࣌', 'وقال يبني لا تدخلوا من باب وحد وادخلوا من ࡰبوب متفرقة࣌ وما أغنے عنكم من ࡰلله من شےء࣌ ࡴن ࡴلحكم إلا لله࣌ عليه توكلت࣌ وعليه فليتوكل ࡴلمتوكلون࣌', NULL, 243, 'local:warsh-text.json'),
  ('warsh-12-68', 'warsh', 12, 68, 'وَلَمَّا دَخَلُواْ مِنْ حَيْثُ أَمَرَهُمُۥٓ أَبُوهُم مَّا كَانَ يُغْنِے عَنْهُم مِّنَ ࡰ۬للَّهِ مِن شَےْءٍ ࡴلَّا حَاجَةࣰ فِے نَفْسِ يَعْقُوبَ قَضٜيٰهَا࣌ وَإِنَّهُۥ لَذُو عِلْمࣲ لِّمَا عَلَّمْنَٰهُ࣌ وَلَٰكِنَّ أَكْثَرَ ࡰ۬لنَّاسِ لَا يَعْلَمُونَ࣌', 'ولما دخلوا من حيث أمرهم أبوهم ما كان يغنے عنهم من ࡰلله من شےء ࡴلا حاجة فے نفس يعقوب قضيها࣌ وإنه لذو علم لما علمنه࣌ ولكن أكثر ࡰلناس لا يعلمون࣌', NULL, 243, 'local:warsh-text.json'),
  ('warsh-12-69', 'warsh', 12, 69, 'وَلَمَّا دَخَلُواْ عَلَىٰ يُوسُفَ ءَاوٜىٰٓ إِلَيْهِ أَخَاهُ࣌ قَالَ إِنِّيَ أَنَآ أَخُوكَ فَلَا تَبْتَئِسْ بِمَا كَانُواْ يَعْمَلُونَ࣌', 'ولما دخلوا على يوسف ءاوى إليه أخاه࣌ قال إني أنا أخوك فلا تبتئس بما كانوا يعملون࣌', NULL, 243, 'local:warsh-text.json'),
  ('warsh-12-70', 'warsh', 12, 70, 'فَلَمَّا جَهَّزَهُم بِجَهَازِهِمْ جَعَلَ ࡰ۬لسِّقَايَةَ فِے رَحْلِ أَخِيهِ ثُمَّ أَذَّنَ مُوَ۬ذِّنٌ ࡰيَّتُهَا ࡰ۬لْعِيرُ إِنَّكُمْ لَسَٰرِقُونَ࣌', 'فلما جهزهم بجهازهم جعل ࡰلسقاية فے رحل أخيه ثم أذن موذن ࡰيتها ࡰلعير إنكم لسرقون࣌', NULL, 244, 'local:warsh-text.json'),
  ('warsh-12-71', 'warsh', 12, 71, 'قَالُواْ وَأَقْبَلُواْ عَلَيْهِم مَّاذَا تَفْقِدُونَ࣌', 'قالوا وأقبلوا عليهم ماذا تفقدون࣌', NULL, 244, 'local:warsh-text.json'),
  ('warsh-12-72', 'warsh', 12, 72, 'قَالُواْ نَفْقِدُ صُوَاعَ ࡰ۬لْمَلِكِ࣌ وَلِمَن جَآءَ بِهِۦ حِمْلُ بَعِيرࣲ وَأَنَا بِهِۦ زَعِيمࣱ࣌', 'قالوا نفقد صواع ࡰلملك࣌ ولمن جاء به حمل بعير وأنا به زعيم࣌', NULL, 244, 'local:warsh-text.json'),
  ('warsh-12-73', 'warsh', 12, 73, 'قَالُواْ تَاللَّهِ لَقَدْ عَلِمْتُم مَّا جِئْنَا لِنُفْسِدَ فِے ࡴ۬لَارْضِ وَمَا كُنَّا سَٰرِقِينَ࣌', 'قالوا تالله لقد علمتم ما جئنا لنفسد فے ࡴلارض وما كنا سرقين࣌', NULL, 244, 'local:warsh-text.json'),
  ('warsh-12-74', 'warsh', 12, 74, 'قَالُواْ فَمَا جَزَٰٓؤُهُۥٓ إِن كُنتُمْ كَٰذِبِينَ࣌', 'قالوا فما جزؤه إن كنتم كذبين࣌', NULL, 244, 'local:warsh-text.json'),
  ('warsh-12-75', 'warsh', 12, 75, 'قَالُواْ جَزَٰٓؤُهُۥ مَنْ وُّجِدَ فِے رَحْلِهِۦ فَهُوَ جَزَٰٓؤُهُۥ࣌ كَذَٰلِكَ نَجْزِے ࡴ۬لظَّٰلِمِينَ࣌', 'قالوا جزؤه من وجد فے رحله فهو جزؤه࣌ كذلك نجزے ࡴلظلمين࣌', NULL, 244, 'local:warsh-text.json'),
  ('warsh-12-76', 'warsh', 12, 76, 'فَبَدَأَ بِأَوْعِيَتِهِمْ قَبْلَ وِعَآءِ ࡶَخِيهِ ثُمَّ ࡰٜسْتَخْرَجَهَا مِنْ وِّعَآءِ ࡶَخِيهِ࣌ كَذَٰلِكَ كِدْنَا لِيُوسُفَ࣌ مَا كَانَ لِيَاخُذَ أَخَاهُ فِے دِينِ ࡴ۬لْمَلِكِ إِلَّآ أَنْ يَّشَآءَ ࡰ۬للَّهُ࣌ نَرْفَعُ دَرَجَٰتِ مَن نَّشَآءُ࣌ وَفَوْقَ كُلِّ ذِے عِلْمٍ عَلِيمࣱ࣌', 'فبدأ بأوعيتهم قبل وعاء ࡶخيه ثم ࡰستخرجها من وعاء ࡶخيه࣌ كذلك كدنا ليوسف࣌ ما كان لياخذ أخاه فے دين ࡴلملك إلا أن يشاء ࡰلله࣌ نرفع درجت من نشاء࣌ وفوق كل ذے علم عليم࣌', NULL, 244, 'local:warsh-text.json'),
  ('warsh-12-77', 'warsh', 12, 77, '۞ قَالُوٓاْ إِنْ يَّسْرِقْ فَقَدْ سَرَقَ أَخࣱ لَّهُۥ مِن قَبْلُ࣌ فَأَسَرَّهَا يُوسُفُ فِے نَفْسِهِۦ وَلَمْ يُبْدِهَا لَهُمْ࣌ قَالَ أَنتُمْ شَرࣱّ مَّكَاناࣰ࣌ وَاللَّهُ أَعْلَمُ بِمَا تَصِفُونَ࣌', 'قالوا إن يسرق فقد سرق أخ له من قبل࣌ فأسرها يوسف فے نفسه ولم يبدها لهم࣌ قال أنتم شر مكانا࣌ والله أعلم بما تصفون࣌', NULL, 244, 'local:warsh-text.json'),
  ('warsh-12-78', 'warsh', 12, 78, 'قَالُواْ يَٰٓأَيُّهَا ࡰ۬لْعَزِيزُ إِنَّ لَهُۥٓ أَباࣰ شَيْخاࣰ كَبِيراࣰ فَخُذَ ࡰحَدَنَا مَكَانَهُۥٓ إِنَّا نَرٜيٰكَ مِنَ ࡰ۬لْمُحْسِنِينَ࣌', 'قالوا يأيها ࡰلعزيز إن له أبا شيخا كبيرا فخذ ࡰحدنا مكانه إنا نريك من ࡰلمحسنين࣌', NULL, 244, 'local:warsh-text.json'),
  ('warsh-12-79', 'warsh', 12, 79, 'قَالَ مَعَاذَ ࡰ۬للَّهِ أَن نَّاخُذَ إِلَّا مَنْ وَّجَدْنَا مَتَٰعَنَا عِندَهُۥٓ إِنَّآ إِذاࣰ لَّظَٰلِمُونَ࣌', 'قال معاذ ࡰلله أن ناخذ إلا من وجدنا متعنا عنده إنا إذا لظلمون࣌', NULL, 245, 'local:warsh-text.json'),
  ('warsh-12-80', 'warsh', 12, 80, 'فَلَمَّا ࡰٜسْتَيْـَٔسُواْ مِنْهُ خَلَصُواْ نَجِيّاࣰ࣌ قَالَ كَبِيرُهُمُۥٓ أَلَمْ تَعْلَمُوٓاْ أَنَّ أَبَاكُمْ قَدَ ࡰخَذَ عَلَيْكُم مَّوْثِقاࣰ مِّنَ ࡰ۬للَّهِ࣌ وَمِن قَبْلُ مَا فَرَّطْتُّمْ فِے يُوسُفَ࣌ فَلَنَ ࡰبْرَحَ ࡰ۬لَارْضَ حَتَّىٰ يَاذَنَ لِيَ أَبِيَ أَوْ يَحْكُمَ ࡰ۬للَّهُ لِے࣌ وَهُوَ خَيْرُ ࡲ۬لْحَٰكِمِينَ࣌', 'فلما ࡰستيسوا منه خلصوا نجيا࣌ قال كبيرهم ألم تعلموا أن أباكم قد ࡰخذ عليكم موثقا من ࡰلله࣌ ومن قبل ما فرطتم فے يوسف࣌ فلن ࡰبرح ࡰلارض حتى ياذن لي أبي أو يحكم ࡰلله لے࣌ وهو خير ࡲلحكمين࣌', NULL, 245, 'local:warsh-text.json'),
  ('warsh-12-81', 'warsh', 12, 81, 'ࡰٜرْجِعُوٓاْ إِلَىٰٓ أَبِيكُمْ فَقُولُواْ يَٰٓأَبَانَآ إِنَّ ࡰٜبْنَكَ سَرَقَ࣌ وَمَا شَهِدْنَآ إِلَّا بِمَا عَلِمْنَا وَمَا كُنَّا لِلْغَيْبِ حَٰفِظِينَ࣌', 'ࡰرجعوا إلى أبيكم فقولوا يأبانا إن ࡰبنك سرق࣌ وما شهدنا إلا بما علمنا وما كنا للغيب حفظين࣌', NULL, 245, 'local:warsh-text.json'),
  ('warsh-12-82', 'warsh', 12, 82, 'وَسْـَٔلِ ࡴ۬لْقَرْيَةَ ࡰ۬لتِے كُنَّا فِيهَا وَالْعِيرَ ࡰ۬لتِےٓ أَقْبَلْنَا فِيهَا وَإِنَّا لَصَٰدِقُونَ࣌', 'وسل ࡴلقرية ࡰلتے كنا فيها والعير ࡰلتے أقبلنا فيها وإنا لصدقون࣌', NULL, 245, 'local:warsh-text.json'),
  ('warsh-12-83', 'warsh', 12, 83, 'قَالَ بَلْ سَوَّلَتْ لَكُمُۥٓ أَنفُسُكُمُۥٓ أَمْراࣰ࣌ فَصَبْرࣱ جَمِيلٌ࣌ عَسَى ࡰ۬للَّهُ أَنْ يَّاتِيَنِے بِهِمْ جَمِيعاً࣌ ࡴنَّهُۥ هُوَ ࡰ۬لْعَلِيمُ ࡲ۬لْحَكِيمُ࣌', 'قال بل سولت لكم أنفسكم أمرا࣌ فصبر جميل࣌ عسى ࡰلله أن ياتينے بهم جميعا࣌ ࡴنه هو ࡰلعليم ࡲلحكيم࣌', NULL, 245, 'local:warsh-text.json'),
  ('warsh-12-84', 'warsh', 12, 84, 'وَتَوَلّٜىٰ عَنْهُمْ وَقَالَ يَٰٓأَسَفٜىٰ عَلَىٰ يُوسُفَ࣌ وَابْيَضَّتْ عَيْنَٰهُ مِنَ ࡰ۬لْحُزْنِ فَهُوَ كَظِيمࣱ࣌', 'وتولى عنهم وقال يأسفى على يوسف࣌ وابيضت عينه من ࡰلحزن فهو كظيم࣌', NULL, 245, 'local:warsh-text.json'),
  ('warsh-12-85', 'warsh', 12, 85, 'قَالُواْ تَاللَّهِ تَفْتَؤُاْ تَذْكُرُ يُوسُفَ حَتَّىٰ تَكُونَ حَرَضاً ࡰوْ تَكُونَ مِنَ ࡰ۬لْهَٰلِكِينَ࣌', 'قالوا تالله تفتؤا تذكر يوسف حتى تكون حرضا ࡰو تكون من ࡰلهلكين࣌', NULL, 245, 'local:warsh-text.json'),
  ('warsh-12-86', 'warsh', 12, 86, 'قَالَ إِنَّمَآ أَشْكُواْ بَثِّے وَحُزْنِيَ إِلَى ࡰ۬للَّهِ࣌ وَأَعْلَمُ مِنَ ࡰ۬للَّهِ مَا لَا تَعْلَمُونَ࣌', 'قال إنما أشكوا بثے وحزني إلى ࡰلله࣌ وأعلم من ࡰلله ما لا تعلمون࣌', NULL, 245, 'local:warsh-text.json'),
  ('warsh-12-87', 'warsh', 12, 87, 'يَٰبَنِيَّ ࡰٜذْهَبُواْ فَتَحَسَّسُواْ مِنْ يُّوسُفَ وَأَخِيهِ وَلَا تَاْيْـَٔسُواْ مِن رَّوْحِ ࡴ۬للَّهِ࣌ إِنَّهُۥ لَا يَاْيْـَٔسُ مِن رَّوْحِ ࡴ۬للَّهِ إِلَّا ࡰ۬لْقَوْمُ ࡲ۬لْكَٰفِرُونَ࣌', 'يبني ࡰذهبوا فتحسسوا من يوسف وأخيه ولا تايسوا من روح ࡴلله࣌ إنه لا يايس من روح ࡴلله إلا ࡰلقوم ࡲلكفرون࣌', NULL, 246, 'local:warsh-text.json'),
  ('warsh-12-88', 'warsh', 12, 88, '۞ فَلَمَّا دَخَلُواْ عَلَيْهِ قَالُواْ يَٰٓأَيُّهَا ࡰ۬لْعَزِيزُ مَسَّنَا وَأَهْلَنَا ࡰ۬لضُّرُّ وَجِئْنَا بِبِضَٰعَةࣲ مُّزْجٜيٰةࣲ࣌ فَأَوْفِ لَنَا ࡰ۬لْكَيْلَ وَتَصَدَّقْ عَلَيْنَآ࣌ إِنَّ ࡰ۬للَّهَ يَجْزِے ࡴ۬لْمُتَصَدِّقِينَ࣌', 'فلما دخلوا عليه قالوا يأيها ࡰلعزيز مسنا وأهلنا ࡰلضر وجئنا ببضعة مزجية࣌ فأوف لنا ࡰلكيل وتصدق علينا࣌ إن ࡰلله يجزے ࡴلمتصدقين࣌', NULL, 246, 'local:warsh-text.json'),
  ('warsh-12-89', 'warsh', 12, 89, 'قَالَ هَلْ عَلِمْتُم مَّا فَعَلْتُم بِيُوسُفَ وَأَخِيهِ إِذَ ࡰنتُمْ جَٰهِلُونَ࣌', 'قال هل علمتم ما فعلتم بيوسف وأخيه إذ ࡰنتم جهلون࣌', NULL, 246, 'local:warsh-text.json'),
  ('warsh-12-90', 'warsh', 12, 90, 'قَالُوٓاْ أَࢇنَّكَ لَأَنتَ يُوسُفُ࣌ قَالَ أَنَا يُوسُفُ وَهَٰذَآ أَخِے࣌ قَدْ مَنَّ ࡰ۬للَّهُ عَلَيْنَآ࣌ إِنَّهُۥ مَنْ يَّتَّقِ وَيَصْبِرْ فَإِنَّ ࡰ۬للَّهَ لَا يُضِيعُ أَجْرَ ࡰ۬لْمُحْسِنِينَ࣌', 'قالوا أࢇنك لأنت يوسف࣌ قال أنا يوسف وهذا أخے࣌ قد من ࡰلله علينا࣌ إنه من يتق ويصبر فإن ࡰلله لا يضيع أجر ࡰلمحسنين࣌', NULL, 246, 'local:warsh-text.json'),
  ('warsh-12-91', 'warsh', 12, 91, 'قَالُواْ تَاللَّهِ لَقَدَ اٰثَرَكَ ࡰ۬للَّهُ عَلَيْنَا وَإِن كُنَّا لَخَٰطِـِٕينَ࣌', 'قالوا تالله لقد اثرك ࡰلله علينا وإن كنا لخطين࣌', NULL, 246, 'local:warsh-text.json'),
  ('warsh-12-92', 'warsh', 12, 92, 'قَالَ لَا تَثْرِيبَ عَلَيْكُمُ࣌ ࡲ۬لْيَوْمَ يَغْفِرُ ࡲ۬للَّهُ لَكُمْ࣌ وَهُوَ أَرْحَمُ ࡲ۬لرَّٰحِمِينَ࣌', 'قال لا تثريب عليكم࣌ ࡲليوم يغفر ࡲلله لكم࣌ وهو أرحم ࡲلرحمين࣌', NULL, 246, 'local:warsh-text.json'),
  ('warsh-12-93', 'warsh', 12, 93, 'ࡰٜذْهَبُواْ بِقَمِيصِے هَٰذَا فَأَلْقُوهُ عَلَىٰ وَجْهِ أَبِے يَاتِ بَصِيراࣰ وَاتُونِے بِأَهْلِكُمُۥٓ أَجْمَعِينَ࣌', 'ࡰذهبوا بقميصے هذا فألقوه على وجه أبے يات بصيرا واتونے بأهلكم أجمعين࣌', NULL, 246, 'local:warsh-text.json'),
  ('warsh-12-94', 'warsh', 12, 94, 'وَلَمَّا فَصَلَتِ ࡴ۬لْعِيرُ قَالَ أَبُوهُمُۥٓ إِنِّے لَأَجِدُ رِيحَ يُوسُفَ لَوْلَآ أَن تُفَنِّدُونِ࣌', 'ولما فصلت ࡴلعير قال أبوهم إنے لأجد ريح يوسف لولا أن تفندون࣌', NULL, 246, 'local:warsh-text.json'),
  ('warsh-12-95', 'warsh', 12, 95, 'قَالُواْ تَاللَّهِ إِنَّكَ لَفِے ضَلَٰلِكَ ࡰ۬لْقَدِيمِ࣌', 'قالوا تالله إنك لفے ضللك ࡰلقديم࣌', NULL, 246, 'local:warsh-text.json'),
  ('warsh-12-96', 'warsh', 12, 96, 'فَلَمَّآ أَن جَآءَ ࡰ۬لْبَشِيرُ أَلْقٜيٰهُ عَلَىٰ وَجْهِهِۦ فَارْتَدَّ بَصِيراࣰ࣌ قَالَ أَلَمَ ࡰقُل لَّكُمُۥٓ إِنِّيَ أَعْلَمُ مِنَ ࡰ۬للَّهِ مَا لَا تَعْلَمُونَ࣌', 'فلما أن جاء ࡰلبشير ألقيه على وجهه فارتد بصيرا࣌ قال ألم ࡰقل لكم إني أعلم من ࡰلله ما لا تعلمون࣌', NULL, 247, 'local:warsh-text.json'),
  ('warsh-12-97', 'warsh', 12, 97, 'قَالُواْ يَٰٓأَبَانَا ࡰٜسْتَغْفِرْ لَنَا ذُنُوبَنَآ إِنَّا كُنَّا خَٰطِـِٕينَ࣌', 'قالوا يأبانا ࡰستغفر لنا ذنوبنا إنا كنا خطين࣌', NULL, 247, 'local:warsh-text.json'),
  ('warsh-12-98', 'warsh', 12, 98, 'قَالَ سَوْفَ أَسْتَغْفِرُ لَكُمْ رَبِّيَ࣌ إِنَّهُۥ هُوَ ࡰ۬لْغَفُورُ ࡲ۬لرَّحِيمُ࣌', 'قال سوف أستغفر لكم ربي࣌ إنه هو ࡰلغفور ࡲلرحيم࣌', NULL, 247, 'local:warsh-text.json'),
  ('warsh-12-99', 'warsh', 12, 99, 'فَلَمَّا دَخَلُواْ عَلَىٰ يُوسُفَ ءَاوٜىٰٓ إِلَيْهِ أَبَوَيْهِ وَقَالَ ࡸَدْخُلُواْ مِصْرَ إِن شَآءَ ࡰ۬للَّهُ ءَامِنِينَ࣌', 'فلما دخلوا على يوسف ءاوى إليه أبويه وقال ࡸدخلوا مصر إن شاء ࡰلله ءامنين࣌', NULL, 247, 'local:warsh-text.json'),
  ('warsh-12-100', 'warsh', 12, 100, 'وَرَفَعَ أَبَوَيْهِ عَلَى ࡰ۬لْعَرْشِ وَخَرُّواْ لَهُۥ سُجَّداࣰ࣌ وَقَالَ يَٰٓأَبَتِ هَٰذَا تَاوِيلُ رُءْيٜـٰيَ مِن قَبْلُ قَدْ جَعَلَهَا رَبِّے حَقّاࣰ࣌ وَقَدَ ࡰحْسَنَ بِيَ إِذَ ࡰخْرَجَنِے مِنَ ࡰ۬لسِّجْنِ وَجَآءَ بِكُم مِّنَ ࡰ۬لْبَدْوِ مِنۢ بَعْدِ أَن نَّزَغَ ࡰ۬لشَّيْطَٰنُ بَيْنِے وَبَيْنَ إِخْوَتِيَ࣌ إِنَّ رَبِّے لَطِيفࣱ لِّمَا يَشَآءُ࣌ ࡹِنَّهُۥ هُوَ ࡰ۬لْعَلِيمُ ࡲ۬لْحَكِيمُ࣌', 'ورفع أبويه على ࡰلعرش وخروا له سجدا࣌ وقال يأبت هذا تاويل رءيي من قبل قد جعلها ربے حقا࣌ وقد ࡰحسن بي إذ ࡰخرجنے من ࡰلسجن وجاء بكم من ࡰلبدو من بعد أن نزغ ࡰلشيطن بينے وبين إخوتي࣌ إن ربے لطيف لما يشاء࣌ ࡹنه هو ࡰلعليم ࡲلحكيم࣌', NULL, 247, 'local:warsh-text.json'),
  ('warsh-12-101', 'warsh', 12, 101, '۞ رَبِّ قَدَ اٰتَيْتَنِے مِنَ ࡰ۬لْمُلْكِ وَعَلَّمْتَنِے مِن تَاوِيلِ ࡴ۬لَاحَادِيثِ࣌ فَاطِرَ ࡰ۬لسَّمَٰوَٰتِ وَالَارْضِ أَنتَ وَلِيِّۦ فِے ࡴ۬لدُّنْيٜا وَالَاخِرَةِ تَوَفَّنِے مُسْلِماࣰ وَأَلْحِقْنِے بِالصَّٰلِحِينَ࣌', 'رب قد اتيتنے من ࡰلملك وعلمتنے من تاويل ࡴلاحاديث࣌ فاطر ࡰلسموت والارض أنت ولي فے ࡴلدنيا والاخرة توفنے مسلما وألحقنے بالصلحين࣌', NULL, 247, 'local:warsh-text.json'),
  ('warsh-12-102', 'warsh', 12, 102, 'ذَٰلِكَ مِنَ ࡰنۢبَآءِ ࡴ۬لْغَيْبِ نُوحِيهِ إِلَيْكَ࣌ وَمَا كُنتَ لَدَيْهِمُۥٓ إِذَ ࡰجْمَعُوٓاْ أَمْرَهُمْ وَهُمْ يَمْكُرُونَ࣌', 'ذلك من ࡰنباء ࡴلغيب نوحيه إليك࣌ وما كنت لديهم إذ ࡰجمعوا أمرهم وهم يمكرون࣌', NULL, 247, 'local:warsh-text.json'),
  ('warsh-12-103', 'warsh', 12, 103, 'وَمَآ أَكْثَرُ ࡲ۬لنَّاسِ وَلَوْ حَرَصْتَ بِمُومِنِينَ࣌', 'وما أكثر ࡲلناس ولو حرصت بمومنين࣌', NULL, 247, 'local:warsh-text.json'),
  ('warsh-12-104', 'warsh', 12, 104, 'وَمَا تَسْـَٔلُهُمْ عَلَيْهِ مِنَ ࡰجْرٍ࣌ ࡴنْ هُوَ إِلَّا ذِكْرࣱ لِّلْعَٰلَمِينَ࣌', 'وما تسلهم عليه من ࡰجر࣌ ࡴن هو إلا ذكر للعلمين࣌', NULL, 248, 'local:warsh-text.json'),
  ('warsh-12-105', 'warsh', 12, 105, 'وَكَأَيِّن مِّنَ اٰيَةࣲ فِے ࡴ۬لسَّمَٰوَٰتِ وَالَارْضِ يَمُرُّونَ عَلَيْهَا وَهُمْ عَنْهَا مُعْرِضُونَ࣌', 'وكأين من اية فے ࡴلسموت والارض يمرون عليها وهم عنها معرضون࣌', NULL, 248, 'local:warsh-text.json'),
  ('warsh-12-106', 'warsh', 12, 106, 'وَمَا يُومِنُ أَكْثَرُهُم بِاللَّهِ إِلَّا وَهُم مُّشْرِكُونَ࣌', 'وما يومن أكثرهم بالله إلا وهم مشركون࣌', NULL, 248, 'local:warsh-text.json'),
  ('warsh-12-107', 'warsh', 12, 107, 'أَفَأَمِنُوٓاْ أَن تَاتِيَهُمْ غَٰشِيَةࣱ مِّنْ عَذَابِ ࡴ۬للَّهِ أَوْ تَاتِيَهُمُ ࡲ۬لسَّاعَةُ بَغْتَةࣰ وَهُمْ لَا يَشْعُرُونَ࣌', 'أفأمنوا أن تاتيهم غشية من عذاب ࡴلله أو تاتيهم ࡲلساعة بغتة وهم لا يشعرون࣌', NULL, 248, 'local:warsh-text.json'),
  ('warsh-12-108', 'warsh', 12, 108, 'قُلْ هَٰذِهِۦ سَبِيلِيَ أَدْعُوٓاْ إِلَى ࡰ۬للَّهِ࣌ عَلَىٰ بَصِيرَةٍ ࡰنَا وَمَنِ ࡴٜتَّبَعَنِے࣌ وَسُبْحَٰنَ ࡰ۬للَّهِ࣌ وَمَآ أَنَا مِنَ ࡰ۬لْمُشْرِكِينَ࣌', 'قل هذه سبيلي أدعوا إلى ࡰلله࣌ على بصيرة ࡰنا ومن ࡴتبعنے࣌ وسبحن ࡰلله࣌ وما أنا من ࡰلمشركين࣌', NULL, 248, 'local:warsh-text.json'),
  ('warsh-12-109', 'warsh', 12, 109, 'وَمَآ أَرْسَلْنَا مِن قَبْلِكَ إِلَّا رِجَالاࣰ يُوحٜىٰٓ إِلَيْهِم مِّنَ ࡰهْلِ ࡴ۬لْقُرٜىٰٓ࣌ أَفَلَمْ يَسِيرُواْ فِے ࡴ۬لَارْضِ فَيَنظُرُواْ كَيْفَ كَانَ عَٰقِبَةُ ࡲ۬لذِينَ مِن قَبْلِهِمْ࣌ وَلَدَارُ ࡲ۬لَاخِرَةِ خَيْرࣱ لِّلذِينَ ࡰٜتَّقَوَاْ࣌ ࡰفَلَا تَعْقِلُونَ࣌', 'وما أرسلنا من قبلك إلا رجالا يوحى إليهم من ࡰهل ࡴلقرى࣌ أفلم يسيروا فے ࡴلارض فينظروا كيف كان عقبة ࡲلذين من قبلهم࣌ ولدار ࡲلاخرة خير للذين ࡰتقوا࣌ ࡰفلا تعقلون࣌', NULL, 248, 'local:warsh-text.json'),
  ('warsh-12-110', 'warsh', 12, 110, 'حَتَّىٰٓ إِذَا ࡰٜسْتَيْـَٔسَ ࡰ۬لرُّسُلُ وَظَنُّوٓاْ أَنَّهُمْ قَدْ كُذِّبُواْ جَآءَهُمْ نَصْرُنَا فَنُنجِے مَن نَّشَآءُ࣌ وَلَا يُرَدُّ بَأْسُنَا عَنِ ࡴ۬لْقَوْمِ ࡴ۬لْمُجْرِمِينَ࣌', 'حتى إذا ࡰستيس ࡰلرسل وظنوا أنهم قد كذبوا جاءهم نصرنا فننجے من نشاء࣌ ولا يرد بأسنا عن ࡴلقوم ࡴلمجرمين࣌', NULL, 248, 'local:warsh-text.json'),
  ('warsh-12-111', 'warsh', 12, 111, '۞ لَقَدْ كَانَ فِے قَصَصِهِمْ عِبْرَةࣱ لِّأُوْلِے ࡴ۬لَالْبَٰبِ࣌ مَا كَانَ حَدِيثاࣰ يُفْتَرٜىٰ࣌ وَلَٰكِن تَصْدِيقَ ࡰ۬لذِے بَيْنَ يَدَيْهِ وَتَفْصِيلَ كُلِّ شَےْءࣲ وَهُدىࣰ وَرَحْمَةࣰ لِّقَوْمࣲ يُومِنُونَ࣌', 'لقد كان فے قصصهم عبرة لأولے ࡴلالبب࣌ ما كان حديثا يفترى࣌ ولكن تصديق ࡰلذے بين يديه وتفصيل كل شےء وهدى ورحمة لقوم يومنون࣌', NULL, 248, 'local:warsh-text.json'),
  ('warsh-13-1', 'warsh', 13, 1, 'أَلَٓمِّٓرٜ࣌ تِلْكَ ءَايَٰتُ ࡲ۬لْكِتَٰبِ࣌ وَالذِےٓ أُنزِلَ إِلَيْكَ مِن رَّبِّكَ ࡰ۬لْحَقُّ࣌ وَلَٰكِنَّ أَكْثَرَ ࡰ۬لنَّاسِ لَا يُومِنُونَ࣌', 'ألمر࣌ تلك ءايت ࡲلكتب࣌ والذے أنزل إليك من ربك ࡰلحق࣌ ولكن أكثر ࡰلناس لا يومنون࣌', NULL, 249, 'local:warsh-text.json'),
  ('warsh-13-2', 'warsh', 13, 2, 'ࡰ۬للَّهُ ࡲ۬لذِے رَفَعَ ࡰ۬لسَّمَٰوَٰتِ بِغَيْرِ عَمَدࣲ࣌ تَرَوْنَهَا࣌ ثُمَّ ࡰٜسْتَوٜىٰ عَلَى ࡰ۬لْعَرْشِ࣌ وَسَخَّرَ ࡰ۬لشَّمْسَ وَالْقَمَرَ࣌ كُلࣱّ يَجْرِے لِأَجَلࣲ مُّسَمّىࣰ࣌ يُدَبِّرُ ࡲ۬لَامْرَ࣌ يُفَصِّلُ ࡲ۬لَايَٰتِ لَعَلَّكُم بِلِقَآءِ رَبِّكُمْ تُوقِنُونَ࣌', 'ࡰلله ࡲلذے رفع ࡰلسموت بغير عمد࣌ ترونها࣌ ثم ࡰستوى على ࡰلعرش࣌ وسخر ࡰلشمس والقمر࣌ كل يجرے لأجل مسمى࣌ يدبر ࡲلامر࣌ يفصل ࡲلايت لعلكم بلقاء ربكم توقنون࣌', NULL, 249, 'local:warsh-text.json'),
  ('warsh-13-3', 'warsh', 13, 3, 'وَهُوَ ࡰ۬لذِے مَدَّ ࡰ۬لَارْضَ وَجَعَلَ فِيهَا رَوَٰسِيَ وَأَنْهَٰراࣰ࣌ وَمِن كُلِّ ࡴ۬لثَّمَرَٰتِ جَعَلَ فِيهَا زَوْجَيْنِ ࡴٜثْنَيْنِ࣌ يُغْشِے ࡴ۬ليْلَ ࡰ۬لنَّهَارَ࣌ إِنَّ فِے ذَٰلِكَ لَأٓيَٰتࣲ لِّقَوْمࣲ يَتَفَكَّرُونَ࣌', 'وهو ࡰلذے مد ࡰلارض وجعل فيها روسي وأنهرا࣌ ومن كل ࡴلثمرت جعل فيها زوجين ࡴثنين࣌ يغشے ࡴليل ࡰلنهار࣌ إن فے ذلك لأيت لقوم يتفكرون࣌', NULL, 249, 'local:warsh-text.json'),
  ('warsh-13-4', 'warsh', 13, 4, 'وَفِے ࡴ۬لَارْضِ قِطَعࣱ مُّتَجَٰوِرَٰتࣱ وَجَنَّٰتࣱ مِّنَ ࡰعْنَٰبࣲ وَزَرْعࣲ وَنَخِيلࣲ صِنْوَانࣲ وَغَيْرِ صِنْوَانࣲ تُسْقٜىٰ بِمَآءࣲ وَٰحِدࣲ࣌ وَنُفَضِّلُ بَعْضَهَا عَلَىٰ بَعْضࣲ فِے ࡴ۬لُاكْلِ࣌ إِنَّ فِے ذَٰلِكَ لَأٓيَٰتࣲ لِّقَوْمࣲ يَعْقِلُونَ࣌', 'وفے ࡴلارض قطع متجورت وجنت من ࡰعنب وزرع ونخيل صنوان وغير صنوان تسقى بماء وحد࣌ ونفضل بعضها على بعض فے ࡴلاكل࣌ إن فے ذلك لأيت لقوم يعقلون࣌', NULL, 249, 'local:warsh-text.json'),
  ('warsh-13-5', 'warsh', 13, 5, '۞ وَإِن تَعْجَبْ فَعَجَبࣱ قَوْلُهُمُۥٓ أَࢇذَا كُنَّا تُرَٰباً ࡴنَّا لَفِے خَلْقࣲ جَدِيدٍ࣌', 'وإن تعجب فعجب قولهم أࢇذا كنا تربا ࡴنا لفے خلق جديد࣌', NULL, 249, 'local:warsh-text.json'),
  ('warsh-13-6', 'warsh', 13, 6, 'ࡳوْلَٰٓئِكَ ࡰ۬لذِينَ كَفَرُواْ بِرَبِّهِمْ࣌ وَأُوْلَٰٓئِكَ ࡰ۬لَاغْلَٰلُ فِےٓ أَعْنَٰقِهِمْ࣌ وَأُوْلَٰٓئِكَ أَصْحَٰبُ ࡲ۬لنّٜارِ هُمْ فِيهَا خَٰلِدُونَ࣌', 'ࡳولئك ࡰلذين كفروا بربهم࣌ وأولئك ࡰلاغلل فے أعنقهم࣌ وأولئك أصحب ࡲلنار هم فيها خلدون࣌', NULL, 249, 'local:warsh-text.json'),
  ('warsh-13-7', 'warsh', 13, 7, 'وَيَسْتَعْجِلُونَكَ بِالسَّيِّئَةِ قَبْلَ ࡰ۬لْحَسَنَةِ وَقَدْ خَلَتْ مِن قَبْلِهِمُ ࡲ۬لْمَثُلَٰتُ࣌ وَإِنَّ رَبَّكَ لَذُو مَغْفِرَةࣲ لِّلنَّاسِ عَلَىٰ ظُلْمِهِمْ࣌ وَإِنَّ رَبَّكَ لَشَدِيدُ ࡲ۬لْعِقَابِ࣌', 'ويستعجلونك بالسيئة قبل ࡰلحسنة وقد خلت من قبلهم ࡲلمثلت࣌ وإن ربك لذو مغفرة للناس على ظلمهم࣌ وإن ربك لشديد ࡲلعقاب࣌', NULL, 250, 'local:warsh-text.json'),
  ('warsh-13-8', 'warsh', 13, 8, 'وَيَقُولُ ࡲ۬لذِينَ كَفَرُواْ لَوْلَآ أُنزِلَ عَلَيْهِ ءَايَةࣱ مِّن رَّبِّهِۦٓ࣌ إِنَّمَآ أَنتَ مُنذِرࣱ࣌ وَلِكُلِّ قَوْمٍ هَادٍ࣌', 'ويقول ࡲلذين كفروا لولا أنزل عليه ءاية من ربه࣌ إنما أنت منذر࣌ ولكل قوم هاد࣌', NULL, 250, 'local:warsh-text.json'),
  ('warsh-13-9', 'warsh', 13, 9, 'ࡴ۬للَّهُ يَعْلَمُ مَا تَحْمِلُ كُلُّ أُنثٜىٰ وَمَا تَغِيضُ ࡲ۬لَارْحَامُ وَمَا تَزْدَادُ࣌ وَكُلُّ شَےْءٍ عِندَهُۥ بِمِقْدٜارٍ࣌', 'ࡴلله يعلم ما تحمل كل أنثى وما تغيض ࡲلارحام وما تزداد࣌ وكل شےء عنده بمقدار࣌', NULL, 250, 'local:warsh-text.json'),
  ('warsh-13-10', 'warsh', 13, 10, 'عَٰلِمُ ࡲ۬لْغَيْبِ وَالشَّهَٰدَةِ࣌ ࡴ۬لْكَبِيرُ ࡲ۬لْمُتَعَالِ࣌', 'علم ࡲلغيب والشهدة࣌ ࡴلكبير ࡲلمتعال࣌', NULL, 250, 'local:warsh-text.json'),
  ('warsh-13-11', 'warsh', 13, 11, 'سَوَآءࣱ مِّنكُم مَّنَ ࡰسَرَّ ࡰ۬لْقَوْلَ وَمَن جَهَرَ بِهِۦ وَمَنْ هُوَ مُسْتَخْفِۢ بِاليْلِ وَسَارِبُۢ بِالنَّهٜارِ࣌', 'سواء منكم من ࡰسر ࡰلقول ومن جهر به ومن هو مستخف باليل وسارب بالنهار࣌', NULL, 250, 'local:warsh-text.json'),
  ('warsh-13-12', 'warsh', 13, 12, 'لَهُۥ مُعَقِّبَٰتࣱ مِّنۢ بَيْنِ يَدَيْهِ وَمِنْ خَلْفِهِۦ يَحْفَظُونَهُۥ مِنَ ࡰمْرِ ࡴ۬للَّهِ࣌ إِنَّ ࡰ۬للَّهَ لَا يُغَيِّرُ مَا بِقَوْمٍ حَتَّىٰ يُغَيِّرُواْ مَا بِأَنفُسِهِمْ࣌ وَإِذَآ أَرَادَ ࡰ۬للَّهُ بِقَوْمࣲ سُوٓءاࣰ فَلَا مَرَدَّ لَهُۥ࣌ وَمَا لَهُم مِّن دُونِهِۦ مِنْ وَّالٍ࣌', 'له معقبت من بين يديه ومن خلفه يحفظونه من ࡰمر ࡴلله࣌ إن ࡰلله لا يغير ما بقوم حتى يغيروا ما بأنفسهم࣌ وإذا أراد ࡰلله بقوم سوءا فلا مرد له࣌ وما لهم من دونه من وال࣌', NULL, 250, 'local:warsh-text.json'),
  ('warsh-13-13', 'warsh', 13, 13, 'هُوَ ࡰ۬لذِے يُرِيكُمُ ࡲ۬لْبَرْقَ خَوْفاࣰ وَطَمَعاࣰ وَيُنشِۓُ ࡲ۬لسَّحَابَ ࡰ۬لثِّقَالَ', 'هو ࡰلذے يريكم ࡲلبرق خوفا وطمعا وينشے ࡲلسحاب ࡰلثقال', NULL, 250, 'local:warsh-text.json'),
  ('warsh-13-14', 'warsh', 13, 14, 'وَيُسَبِّحُ ࡲ۬لرَّعْدُ بِحَمْدِهِۦ وَالْمَلَٰٓئِكَةُ مِنْ خِيفَتِهِۦ࣌ وَيُرْسِلُ ࡲ۬لصَّوَٰعِقَ فَيُصِيبُ بِهَا مَنْ يَّشَآءُ وَهُمْ يُجَٰدِلُونَ فِے ࡴ۬للَّهِ وَهُوَ شَدِيدُ ࡲ۬لْمِحَالِ࣌', 'ويسبح ࡲلرعد بحمده والملئكة من خيفته࣌ ويرسل ࡲلصوعق فيصيب بها من يشاء وهم يجدلون فے ࡴلله وهو شديد ࡲلمحال࣌', NULL, 250, 'local:warsh-text.json'),
  ('warsh-13-15', 'warsh', 13, 15, '۞ لَهُۥ دَعْوَةُ ࡲ۬لْحَقِّ࣌ وَالذِينَ يَدْعُونَ مِن دُونِهِۦ لَا يَسْتَجِيبُونَ لَهُم بِشَےْءٍ ࡴلَّا كَبَٰسِطِ كَفَّيْهِ إِلَى ࡰ۬لْمَآءِ لِيَبْلُغَ فَاهُ وَمَا هُوَ بِبَٰلِغِهِۦ࣌ وَمَا دُعَآءُ ࡲ۬لْكٜـٰفِرِينَ إِلَّا فِے ضَلَٰلࣲ࣌', 'له دعوة ࡲلحق࣌ والذين يدعون من دونه لا يستجيبون لهم بشےء ࡴلا كبسط كفيه إلى ࡰلماء ليبلغ فاه وما هو ببلغه࣌ وما دعاء ࡲلكفرين إلا فے ضلل࣌', NULL, 251, 'local:warsh-text.json'),
  ('warsh-13-16', 'warsh', 13, 16, 'وَلِلهِ يَسْجُدُ مَن فِے ࡴ۬لسَّمَٰوَٰتِ وَالَارْضِ طَوْعاࣰ وَكَرْهاࣰ وَظِلَٰلُهُم بِالْغُدُوِّ وَالَاصَالِ࣌۩', 'ولله يسجد من فے ࡴلسموت والارض طوعا وكرها وظللهم بالغدو والاصال࣌', NULL, 251, 'local:warsh-text.json'),
  ('warsh-13-17', 'warsh', 13, 17, 'قُلْ مَن رَّبُّ ࡲ۬لسَّمَٰوَٰتِ وَالَارْضِ قُلِ ࡴ۬للَّهُ࣌ قُلَ ࡰفَاتَّخَذتُّم مِّن دُونِهِۦٓ أَوْلِيَآءَ لَا يَمْلِكُونَ لِأَنفُسِهِمْ نَفْعاࣰ وَلَا ضَرّاࣰ࣌ قُلْ هَلْ يَسْتَوِے ࡴ۬لَاعْمٜىٰ وَالْبَصِيرُ࣌ أَمْ هَلْ تَسْتَوِے ࡴ۬لظُّلُمَٰتُ وَالنُّورُ࣌', 'قل من رب ࡲلسموت والارض قل ࡴلله࣌ قل ࡰفاتخذتم من دونه أولياء لا يملكون لأنفسهم نفعا ولا ضرا࣌ قل هل يستوے ࡴلاعمى والبصير࣌ أم هل تستوے ࡴلظلمت والنور࣌', NULL, 251, 'local:warsh-text.json'),
  ('warsh-13-18', 'warsh', 13, 18, 'أَمْ جَعَلُواْ لِلهِ شُرَكَآءَ خَلَقُواْ كَخَلْقِهِۦ فَتَشَٰبَهَ ࡰ۬لْخَلْقُ عَلَيْهِمْ࣌ قُلِ ࡴ۬للَّهُ خَٰلِقُ كُلِّ شَےْءࣲ࣌ وَهُوَ ࡰ۬لْوَٰحِدُ ࡲ۬لْقَهَّٰرُ࣌', 'أم جعلوا لله شركاء خلقوا كخلقه فتشبه ࡰلخلق عليهم࣌ قل ࡴلله خلق كل شےء࣌ وهو ࡰلوحد ࡲلقهر࣌', NULL, 251, 'local:warsh-text.json'),
  ('warsh-13-19', 'warsh', 13, 19, 'أَنزَلَ مِنَ ࡰ۬لسَّمَآءِ مَآءࣰ فَسَالَتَ ࡰوْدِيَةُۢ بِقَدَرِهَا فَاحْتَمَلَ ࡰ۬لسَّيْلُ زَبَداࣰ رَّابِياࣰ࣌ وَمِمَّا تُوقِدُونَ عَلَيْهِ فِے ࡴ۬لنّٜارِ ࡴٜبْتِغَآءَ حِلْيَةٍ ࡰوْ مَتَٰعࣲ زَبَدࣱ مِّثْلُهُۥ࣌ كَذَٰلِكَ يَضْرِبُ ࡲ۬للَّهُ ࡲ۬لْحَقَّ وَالْبَٰطِلَ࣌ فَأَمَّا ࡰ۬لزَّبَدُ فَيَذْهَبُ جُفَآءࣰ࣌ وَأَمَّا مَا يَنفَعُ ࡲ۬لنَّاسَ فَيَمْكُثُ فِے ࡴ۬لَارْضِ࣌ كَذَٰلِكَ يَضْرِبُ ࡲ۬للَّهُ ࡲ۬لَامْثَالَ࣌', 'أنزل من ࡰلسماء ماء فسالت ࡰودية بقدرها فاحتمل ࡰلسيل زبدا رابيا࣌ ومما توقدون عليه فے ࡴلنار ࡴبتغاء حلية ࡰو متع زبد مثله࣌ كذلك يضرب ࡲلله ࡲلحق والبطل࣌ فأما ࡰلزبد فيذهب جفاء࣌ وأما ما ينفع ࡲلناس فيمكث فے ࡴلارض࣌ كذلك يضرب ࡲلله ࡲلامثال࣌', NULL, 251, 'local:warsh-text.json'),
  ('warsh-13-20', 'warsh', 13, 20, 'لِلذِينَ ࡰٜسْتَجَابُواْ لِرَبِّهِمُ ࡲ۬لْحُسْنٜىٰ࣌ وَالذِينَ لَمْ يَسْتَجِيبُواْ لَهُۥ لَوَ ࡰنَّ لَهُم مَّا فِے ࡴ۬لَارْضِ جَمِيعاࣰ وَمِثْلَهُۥ مَعَهُۥ لَافْتَدَوْاْ بِهِۦٓ࣌ أُوْلَٰٓئِكَ لَهُمْ سُوٓءُ ࡲ۬لْحِسَابِ࣌ وَمَأْوٜيٰهُمْ جَهَنَّمُ࣌ وَبِيسَ ࡰ۬لْمِهَادُ࣌', 'للذين ࡰستجابوا لربهم ࡲلحسنى࣌ والذين لم يستجيبوا له لو ࡰن لهم ما فے ࡴلارض جميعا ومثله معه لافتدوا به࣌ أولئك لهم سوء ࡲلحساب࣌ ومأويهم جهنم࣌ وبيس ࡰلمهاد࣌', NULL, 251, 'local:warsh-text.json'),
  ('warsh-13-21', 'warsh', 13, 21, '۞ أَفَمَنْ يَّعْلَمُ أَنَّمَآ أُنزِلَ إِلَيْكَ مِن رَّبِّكَ ࡰ۬لْحَقُّ كَمَنْ هُوَ أَعْمٜىٰٓ࣌ إِنَّمَا يَتَذَكَّرُ أُوْلُواْ ࡲ۬لَالْبَٰبِ', 'أفمن يعلم أنما أنزل إليك من ربك ࡰلحق كمن هو أعمى࣌ إنما يتذكر أولوا ࡲلالبب', NULL, 252, 'local:warsh-text.json'),
  ('warsh-13-22', 'warsh', 13, 22, 'ࡴ۬لذِينَ يُوفُونَ بِعَهْدِ ࡴ۬للَّهِ وَلَا يَنقُضُونَ ࡰ۬لْمِيثَٰقَ', 'ࡴلذين يوفون بعهد ࡴلله ولا ينقضون ࡰلميثق', NULL, 252, 'local:warsh-text.json'),
  ('warsh-13-23', 'warsh', 13, 23, 'وَالذِينَ يَصِلُونَ مَآ أَمَرَ ࡰ۬للَّهُ بِهِۦٓ أَنْ يُّوصَلَ وَيَخْشَوْنَ رَبَّهُمْ وَيَخَافُونَ سُوٓءَ ࡰ۬لْحِسَابِ', 'والذين يصلون ما أمر ࡰلله به أن يوصل ويخشون ربهم ويخافون سوء ࡰلحساب', NULL, 252, 'local:warsh-text.json'),
  ('warsh-13-24', 'warsh', 13, 24, 'وَالذِينَ صَبَرُواْ ࡲٜبْتِغَآءَ وَجْهِ رَبِّهِمْ وَأَقَامُواْ ࡲ۬لصَّلَوٰةَ وَأَنفَقُواْ مِمَّا رَزَقْنَٰهُمْ سِرّاࣰ وَعَلَٰنِيَةࣰ وَيَدْرَءُونَ بِالْحَسَنَةِ ࡴ۬لسَّيِّئَةَ࣌ أُوْلَٰٓئِكَ لَهُمْ عُقْبَى ࡰ۬لدّٜارِ࣌', 'والذين صبروا ࡲبتغاء وجه ربهم وأقاموا ࡲلصلوة وأنفقوا مما رزقنهم سرا وعلنية ويدرءون بالحسنة ࡴلسيئة࣌ أولئك لهم عقبى ࡰلدار࣌', NULL, 252, 'local:warsh-text.json'),
  ('warsh-13-25', 'warsh', 13, 25, 'جَنَّٰتُ عَدْنࣲ يَدْخُلُونَهَا وَمَن صَلَحَ مِنَ اٰبَآئِهِمْ وَأَزْوَٰجِهِمْ وَذُرِّيَّٰتِهِمْ࣌ وَالْمَلَٰٓئِكَةُ يَدْخُلُونَ عَلَيْهِم مِّن كُلِّ بَابࣲ࣌ سَلَٰمٌ عَلَيْكُم بِمَا صَبَرْتُمْ࣌ فَنِعْمَ عُقْبَى ࡰ۬لدّٜارِ࣌', 'جنت عدن يدخلونها ومن صلح من ابائهم وأزوجهم وذريتهم࣌ والملئكة يدخلون عليهم من كل باب࣌ سلم عليكم بما صبرتم࣌ فنعم عقبى ࡰلدار࣌', NULL, 252, 'local:warsh-text.json'),
  ('warsh-13-26', 'warsh', 13, 26, 'وَالذِينَ يَنقُضُونَ عَهْدَ ࡰ۬للَّهِ مِنۢ بَعْدِ مِيثَٰقِهِۦ وَيَقْطَعُونَ مَآ أَمَرَ ࡰ۬للَّهُ بِهِۦٓ أَنْ يُّوصَلَ وَيُفْسِدُونَ فِے ࡴ۬لَارْضِ أُوْلَٰٓئِكَ لَهُمُ ࡲ۬للَّعْنَةُ وَلَهُمْ سُوٓءُ ࡲ۬لدّٜارِ࣌', 'والذين ينقضون عهد ࡰلله من بعد ميثقه ويقطعون ما أمر ࡰلله به أن يوصل ويفسدون فے ࡴلارض أولئك لهم ࡲللعنة ولهم سوء ࡲلدار࣌', NULL, 252, 'local:warsh-text.json'),
  ('warsh-13-27', 'warsh', 13, 27, 'ࡴ۬للَّهُ يَبْسُطُ ࡲ۬لرِّزْقَ لِمَنْ يَّشَآءُ وَيَقْدِرُ࣌ وَفَرِحُواْ بِالْحَيَوٰةِ ࡴ۬لدُّنْيٜا࣌ وَمَا ࡰ۬لْحَيَوٰةُ ࡲ۬لدُّنْيٜا فِے ࡴ۬لَاخِرَةِ إِلَّا مَتَٰعࣱ࣌', 'ࡴلله يبسط ࡲلرزق لمن يشاء ويقدر࣌ وفرحوا بالحيوة ࡴلدنيا࣌ وما ࡰلحيوة ࡲلدنيا فے ࡴلاخرة إلا متع࣌', NULL, 252, 'local:warsh-text.json'),
  ('warsh-13-28', 'warsh', 13, 28, 'وَيَقُولُ ࡲ۬لذِينَ كَفَرُواْ لَوْلَآ أُنزِلَ عَلَيْهِ ءَايَةࣱ مِّن رَّبِّهِۦ࣌ قُلِ ࡴنَّ ࡰ۬للَّهَ يُضِلُّ مَنْ يَّشَآءُ وَيَهْدِےٓ إِلَيْهِ مَنَ ࡰنَابَ࣌', 'ويقول ࡲلذين كفروا لولا أنزل عليه ءاية من ربه࣌ قل ࡴن ࡰلله يضل من يشاء ويهدے إليه من ࡰناب࣌', NULL, 252, 'local:warsh-text.json'),
  ('warsh-13-29', 'warsh', 13, 29, 'ࡰ۬لذِينَ ءَامَنُواْ وَتَطْمَئِنُّ قُلُوبُهُم بِذِكْرِ ࡴ۬للَّهِ࣌ أَلَا بِذِكْرِ ࡴ۬للَّهِ تَطْمَئِنُّ ࡲ۬لْقُلُوبُ࣌', 'ࡰلذين ءامنوا وتطمئن قلوبهم بذكر ࡴلله࣌ ألا بذكر ࡴلله تطمئن ࡲلقلوب࣌', NULL, 252, 'local:warsh-text.json'),
  ('warsh-13-30', 'warsh', 13, 30, 'ࡲ۬لذِينَ ءَامَنُواْ وَعَمِلُواْ ࡲ۬لصَّٰلِحَٰتِ طُوبٜىٰ لَهُمْ وَحُسْنُ مَـَٔابࣲ࣌', 'ࡲلذين ءامنوا وعملوا ࡲلصلحت طوبى لهم وحسن ماب࣌', NULL, 253, 'local:warsh-text.json'),
  ('warsh-13-31', 'warsh', 13, 31, '۞ كَذَٰلِكَ أَرْسَلْنَٰكَ فِےٓ أُمَّةࣲ قَدْ خَلَتْ مِن قَبْلِهَآ أُمَمࣱ لِّتَتْلُوَاْ عَلَيْهِمُ ࡲ۬لذِےٓ أَوْحَيْنَآ إِلَيْكَ وَهُمْ يَكْفُرُونَ بِالرَّحْمَٰنِ࣌ قُلْ هُوَ رَبِّے࣌ لَآ إِلَٰهَ إِلَّا هُوَ࣌ عَلَيْهِ تَوَكَّلْتُ࣌ وَإِلَيْهِ مَتَابِ࣌', 'كذلك أرسلنك فے أمة قد خلت من قبلها أمم لتتلوا عليهم ࡲلذے أوحينا إليك وهم يكفرون بالرحمن࣌ قل هو ربے࣌ لا إله إلا هو࣌ عليه توكلت࣌ وإليه متاب࣌', NULL, 253, 'local:warsh-text.json'),
  ('warsh-13-32', 'warsh', 13, 32, 'وَلَوَ ࡰنَّ قُرْءَاناࣰ سُيِّرَتْ بِهِ ࡴ۬لْجِبَالُ أَوْ قُطِّعَتْ بِهِ ࡴ۬لَارْضُ أَوْ كُلِّمَ بِهِ ࡴ۬لْمَوْتٜىٰ࣌ بَل لِّلهِ ࡴ۬لَامْرُ جَمِيعاً࣌ ࡰفَلَمْ يَاْيْـَٔسِ ࡴ۬لذِينَ ءَامَنُوٓاْ أَن لَّوْ يَشَآءُ ࡲ۬للَّهُ لَهَدَى ࡰ۬لنَّاسَ جَمِيعاࣰ࣌ وَلَا يَزَالُ ࡲ۬لذِينَ كَفَرُواْ تُصِيبُهُم بِمَا صَنَعُواْ قَارِعَةٌ ࡰوْ تَحُلُّ قَرِيباࣰ مِّن دٜارِهِمْ حَتَّىٰ يَاتِيَ وَعْدُ ࡲ۬للَّهِ࣌ إِنَّ ࡰ۬للَّهَ لَا يُخْلِفُ ࡲ۬لْمِيعَادَ࣌', 'ولو ࡰن قرءانا سيرت به ࡴلجبال أو قطعت به ࡴلارض أو كلم به ࡴلموتى࣌ بل لله ࡴلامر جميعا࣌ ࡰفلم يايس ࡴلذين ءامنوا أن لو يشاء ࡲلله لهدى ࡰلناس جميعا࣌ ولا يزال ࡲلذين كفروا تصيبهم بما صنعوا قارعة ࡰو تحل قريبا من دارهم حتى ياتي وعد ࡲلله࣌ إن ࡰلله لا يخلف ࡲلميعاد࣌', NULL, 253, 'local:warsh-text.json'),
  ('warsh-13-33', 'warsh', 13, 33, 'وَلَقَدُ ࡲ࢈سْتُهْزِۓَ بِرُسُلࣲ مِّن قَبْلِكَ فَأَمْلَيْتُ لِلذِينَ كَفَرُواْ ثُمَّ أَخَذتُّهُمْ࣌ فَكَيْفَ كَانَ عِقَابِ࣌', 'ولقد ࡲ࢈ستهزے برسل من قبلك فأمليت للذين كفروا ثم أخذتهم࣌ فكيف كان عقاب࣌', NULL, 253, 'local:warsh-text.json'),
  ('warsh-13-34', 'warsh', 13, 34, 'أَفَمَنْ هُوَ قَآئِمٌ عَلَىٰ كُلِّ نَفْسِۢ بِمَا كَسَبَتْ࣌ وَجَعَلُواْ لِلهِ شُرَكَآءَ قُلْ سَمُّوهُمُۥٓ࣌ أَمْ تُنَبِّـُٔونَهُۥ بِمَا لَا يَعْلَمُ فِے ࡴ۬لَارْضِ أَم بِظَٰهِرࣲ مِّنَ ࡰ۬لْقَوْلِ࣌ بَلْ زُيِّنَ لِلذِينَ كَفَرُواْ مَكْرُهُمْ وَصَدُّواْ عَنِ ࡴ۬لسَّبِيلِ࣌ وَمَنْ يُّضْلِلِ ࡴ۬للَّهُ فَمَا لَهُۥ مِنْ هَادࣲ࣌', 'أفمن هو قائم على كل نفس بما كسبت࣌ وجعلوا لله شركاء قل سموهم࣌ أم تنبونه بما لا يعلم فے ࡴلارض أم بظهر من ࡰلقول࣌ بل زين للذين كفروا مكرهم وصدوا عن ࡴلسبيل࣌ ومن يضلل ࡴلله فما له من هاد࣌', NULL, 253, 'local:warsh-text.json'),
  ('warsh-13-35', 'warsh', 13, 35, 'لَّهُمْ عَذَابࣱ فِے ࡴ۬لْحَيَوٰةِ ࡴ۬لدُّنْيٜا࣌ وَلَعَذَابُ ࡲ۬لَاخِرَةِ أَشَقُّ࣌ وَمَا لَهُم مِّنَ ࡰ۬للَّهِ مِنْ وَّاقࣲ࣌', 'لهم عذاب فے ࡴلحيوة ࡴلدنيا࣌ ولعذاب ࡲلاخرة أشق࣌ وما لهم من ࡰلله من واق࣌', NULL, 253, 'local:warsh-text.json'),
  ('warsh-13-36', 'warsh', 13, 36, '۞ مَّثَلُ ࡲ۬لْجَنَّةِ ࡴ۬لتِے وُعِدَ ࡰ۬لْمُتَّقُونَ تَجْرِے مِن تَحْتِهَا ࡰ۬لَانْهَٰرُ أُكْلُهَا دَآئِمࣱ وَظِلُّهَا࣌ تِلْكَ عُقْبَى ࡰ۬لذِينَ ࡰٜتَّقَواْ࣌ وَّعُقْبَى ࡰ۬لْكٜـٰفِرِينَ ࡰ۬لنَّارُ࣌', 'مثل ࡲلجنة ࡴلتے وعد ࡰلمتقون تجرے من تحتها ࡰلانهر أكلها دائم وظلها࣌ تلك عقبى ࡰلذين ࡰتقوا࣌ وعقبى ࡰلكفرين ࡰلنار࣌', NULL, 254, 'local:warsh-text.json'),
  ('warsh-13-37', 'warsh', 13, 37, 'وَالذِينَ ءَاتَيْنَٰهُمُ ࡲ۬لْكِتَٰبَ يَفْرَحُونَ بِمَآ أُنزِلَ إِلَيْكَ࣌ وَمِنَ ࡰ۬لَاحْزَابِ مَنْ يُّنكِرُ بَعْضَهُۥ࣌ قُلِ ࡴنَّمَآ أُمِرْتُ أَنَ ࡰعْبُدَ ࡰ۬للَّهَ وَلَآ أُشْرِكَ بِهِۦٓ࣌ إِلَيْهِ أَدْعُواْ࣌ وَإِلَيْهِ مَـَٔابِ࣌', 'والذين ءاتينهم ࡲلكتب يفرحون بما أنزل إليك࣌ ومن ࡰلاحزاب من ينكر بعضه࣌ قل ࡴنما أمرت أن ࡰعبد ࡰلله ولا أشرك به࣌ إليه أدعوا࣌ وإليه ماب࣌', NULL, 254, 'local:warsh-text.json'),
  ('warsh-13-38', 'warsh', 13, 38, 'وَكَذَٰلِكَ أَنزَلْنَٰهُ حُكْماً عَرَبِيّاࣰ࣌ وَلَئِنِ ࡴٜتَّبَعْتَ أَهْوَآءَهُم بَعْدَ مَا جَآءَكَ مِنَ ࡰ۬لْعِلْمِ مَا لَكَ مِنَ ࡰ۬للَّهِ مِنْ وَّلِيࣲّ وَلَا وَاقࣲ࣌', 'وكذلك أنزلنه حكما عربيا࣌ ولئن ࡴتبعت أهواءهم بعد ما جاءك من ࡰلعلم ما لك من ࡰلله من ولي ولا واق࣌', NULL, 254, 'local:warsh-text.json'),
  ('warsh-13-39', 'warsh', 13, 39, 'وَلَقَدَ ࡰرْسَلْنَا رُسُلاࣰ مِّن قَبْلِكَ وَجَعَلْنَا لَهُمُۥٓ أَزْوَٰجاࣰ وَذُرِّيَّةࣰ࣌ وَمَا كَانَ لِرَسُولٍ ࡰنْ يَّاتِيَ بِـَٔايَةٍ ࡴلَّا بِإِذْنِ ࡴ۬للَّهِ࣌ لِكُلِّ أَجَلࣲ كِتَابࣱ࣌', 'ولقد ࡰرسلنا رسلا من قبلك وجعلنا لهم أزوجا وذرية࣌ وما كان لرسول ࡰن ياتي باية ࡴلا بإذن ࡴلله࣌ لكل أجل كتاب࣌', NULL, 254, 'local:warsh-text.json'),
  ('warsh-13-40', 'warsh', 13, 40, 'يَمْحُواْ ࡲ۬للَّهُ مَا يَشَآءُ وَيُثَبِّتُ࣌ وَعِندَهُۥٓ أُمُّ ࡲ۬لْكِتَٰبِ࣌', 'يمحوا ࡲلله ما يشاء ويثبت࣌ وعنده أم ࡲلكتب࣌', NULL, 254, 'local:warsh-text.json'),
  ('warsh-13-41', 'warsh', 13, 41, 'وَإِن مَّا نُرِيَنَّكَ بَعْضَ ࡰ۬لذِے نَعِدُهُمُۥٓ أَوْ نَتَوَفَّيَنَّكَ فَإِنَّمَا عَلَيْكَ ࡰ۬لْبَلَٰغُ وَعَلَيْنَا ࡰ۬لْحِسَابُ࣌', 'وإن ما نرينك بعض ࡰلذے نعدهم أو نتوفينك فإنما عليك ࡰلبلغ وعلينا ࡰلحساب࣌', NULL, 254, 'local:warsh-text.json'),
  ('warsh-13-42', 'warsh', 13, 42, 'أَوَلَمْ يَرَوَاْ ࡰنَّا نَاتِے ࡴ۬لَارْضَ نَنقُصُهَا مِنَ ࡰطْرَافِهَا࣌ وَاللَّهُ يَحْكُمُ لَا مُعَقِّبَ لِحُكْمِهِۦ࣌ وَهُوَ سَرِيعُ ࡲ۬لْحِسَابِ࣌', 'أولم يروا ࡰنا ناتے ࡴلارض ننقصها من ࡰطرافها࣌ والله يحكم لا معقب لحكمه࣌ وهو سريع ࡲلحساب࣌', NULL, 254, 'local:warsh-text.json'),
  ('warsh-13-43', 'warsh', 13, 43, 'وَقَدْ مَكَرَ ࡰ۬لذِينَ مِن قَبْلِهِمْ فَلِلهِ ࡴ۬لْمَكْرُ جَمِيعاࣰ࣌ يَعْلَمُ مَا تَكْسِبُ كُلُّ نَفْسࣲ࣌ وَسَيَعْلَمُ ࡲ۬لْكَٰفِرُ لِمَنْ عُقْبَى ࡰ۬لدّٜارِ࣌', 'وقد مكر ࡰلذين من قبلهم فلله ࡴلمكر جميعا࣌ يعلم ما تكسب كل نفس࣌ وسيعلم ࡲلكفر لمن عقبى ࡰلدار࣌', NULL, 254, 'local:warsh-text.json'),
  ('warsh-13-44', 'warsh', 13, 44, 'وَيَقُولُ ࡲ۬لذِينَ كَفَرُواْ لَسْتَ مُرْسَلاࣰ࣌ قُلْ كَفٜىٰ بِاللَّهِ شَهِيداَۢ بَيْنِے وَبَيْنَكُمْ وَمَنْ عِندَهُۥ عِلْمُ ࡲ۬لْكِتَٰبِ࣌', 'ويقول ࡲلذين كفروا لست مرسلا࣌ قل كفى بالله شهيدا بينے وبينكم ومن عنده علم ࡲلكتب࣌', NULL, 255, 'local:warsh-text.json'),
  ('warsh-14-1', 'warsh', 14, 1, 'أَلَٓرٜ࣌ كِتَٰبٌ ࡰنزَلْنَٰهُ إِلَيْكَ لِتُخْرِجَ ࡰ۬لنَّاسَ مِنَ ࡰ۬لظُّلُمَٰتِ إِلَى ࡰ۬لنُّورِ', 'ألر࣌ كتب ࡰنزلنه إليك لتخرج ࡰلناس من ࡰلظلمت إلى ࡰلنور', NULL, 255, 'local:warsh-text.json'),
  ('warsh-14-2', 'warsh', 14, 2, 'بِإِذْنِ رَبِّهِمُۥٓ إِلَىٰ صِرَٰطِ ࡴ۬لْعَزِيزِ ࡴ۬لْحَمِيدِ࣌', 'بإذن ربهم إلى صرط ࡴلعزيز ࡴلحميد࣌', NULL, 255, 'local:warsh-text.json'),
  ('warsh-14-3', 'warsh', 14, 3, 'ࡴ۬للَّهُ ࡲ۬لذِے لَهُۥ مَا فِے ࡴ۬لسَّمَٰوَٰتِ وَمَا فِے ࡴ۬لَارْضِ࣌ وَوَيْلࣱ لِّلْكٜـٰفِرِينَ مِنْ عَذَابࣲ شَدِيدٍ࣌', 'ࡴلله ࡲلذے له ما فے ࡴلسموت وما فے ࡴلارض࣌ وويل للكفرين من عذاب شديد࣌', NULL, 255, 'local:warsh-text.json'),
  ('warsh-14-4', 'warsh', 14, 4, 'ࡴ۬لذِينَ يَسْتَحِبُّونَ ࡰ۬لْحَيَوٰةَ ࡰ۬لدُّنْيٜا عَلَى ࡰ۬لَاخِرَةِ وَيَصُدُّونَ عَن سَبِيلِ ࡴ۬للَّهِ وَيَبْغُونَهَا عِوَجاً ࡳوْلَٰٓئِكَ فِے ضَلَٰلِۢ بَعِيدࣲ࣌', 'ࡴلذين يستحبون ࡰلحيوة ࡰلدنيا على ࡰلاخرة ويصدون عن سبيل ࡴلله ويبغونها عوجا ࡳولئك فے ضلل بعيد࣌', NULL, 255, 'local:warsh-text.json'),
  ('warsh-14-5', 'warsh', 14, 5, 'وَمَآ أَرْسَلْنَا مِن رَّسُولٍ ࡴلَّا بِلِسَانِ قَوْمِهِۦ لِيُبَيِّنَ لَهُمْ࣌ فَيُضِلُّ ࡲ۬للَّهُ مَنْ يَّشَآءُ وَيَهْدِے مَنْ يَّشَآءُ࣌ وَهُوَ ࡰ۬لْعَزِيزُ ࡲ۬لْحَكِيمُ࣌', 'وما أرسلنا من رسول ࡴلا بلسان قومه ليبين لهم࣌ فيضل ࡲلله من يشاء ويهدے من يشاء࣌ وهو ࡰلعزيز ࡲلحكيم࣌', NULL, 255, 'local:warsh-text.json'),
  ('warsh-14-6', 'warsh', 14, 6, 'وَلَقَدَ ࡰرْسَلْنَا مُوسٜىٰ بِـَٔايَٰتِنَآ أَنَ ࡰخْرِجْ قَوْمَكَ مِنَ ࡰ۬لظُّلُمَٰتِ إِلَى ࡰ۬لنُّورِ', 'ولقد ࡰرسلنا موسى بايتنا أن ࡰخرج قومك من ࡰلظلمت إلى ࡰلنور', NULL, 255, 'local:warsh-text.json'),
  ('warsh-14-7', 'warsh', 14, 7, 'وَذَكِّرْهُم بِأَييَّٰمِ ࡴ۬للَّهِ࣌ إِنَّ فِے ذَٰلِكَ لَأٓيَٰتࣲ لِّكُلِّ صَبّٜارࣲ شَكُورࣲ࣌', 'وذكرهم بأييم ࡴلله࣌ إن فے ذلك لأيت لكل صبار شكور࣌', NULL, 255, 'local:warsh-text.json'),
  ('warsh-14-8', 'warsh', 14, 8, 'وَإِذْ قَالَ مُوسٜىٰ لِقَوْمِهِ ࡴ࢈ذْكُرُواْ نِعْمَةَ ࡰ۬للَّهِ عَلَيْكُمُۥٓ إِذَ ࡰنجٜيٰكُم مِّنَ اٰلِ فِرْعَوْنَ يَسُومُونَكُمْ سُوٓءَ ࡰ۬لْعَذَابِ وَيُذَبِّحُونَ أَبْنَآءَكُمْ وَيَسْتَحْيُونَ نِسَآءَكُمْ࣌ وَفِے ذَٰلِكُم بَلَآءࣱ مِّن رَّبِّكُمْ عَظِيمࣱ࣌', 'وإذ قال موسى لقومه ࡴ࢈ذكروا نعمة ࡰلله عليكم إذ ࡰنجيكم من ال فرعون يسومونكم سوء ࡰلعذاب ويذبحون أبناءكم ويستحيون نساءكم࣌ وفے ذلكم بلاء من ربكم عظيم࣌', NULL, 256, 'local:warsh-text.json'),
  ('warsh-14-9', 'warsh', 14, 9, 'وَإِذْ تَأَذَّنَ رَبُّكُمْ لَئِن شَكَرْتُمْ لَأَزِيدَنَّكُمْ وَلَئِن كَفَرْتُمُۥٓ إِنَّ عَذَابِے لَشَدِيدࣱ࣌', 'وإذ تأذن ربكم لئن شكرتم لأزيدنكم ولئن كفرتم إن عذابے لشديد࣌', NULL, 256, 'local:warsh-text.json'),
  ('warsh-14-10', 'warsh', 14, 10, 'وَقَالَ مُوسٜىٰٓ إِن تَكْفُرُوٓاْ أَنتُمْ وَمَن فِے ࡴ۬لَارْضِ جَمِيعاࣰ فَإِنَّ ࡰ۬للَّهَ لَغَنِيٌّ حَمِيدٌ࣌', 'وقال موسى إن تكفروا أنتم ومن فے ࡴلارض جميعا فإن ࡰلله لغني حميد࣌', NULL, 256, 'local:warsh-text.json'),
  ('warsh-14-11', 'warsh', 14, 11, 'ࡰلَمْ يَاتِكُمْ نَبَؤُاْ ࡲ۬لذِينَ مِن قَبْلِكُمْ قَوْمِ نُوحࣲ وَعَادࣲ وَثَمُودَ', 'ࡰلم ياتكم نبؤا ࡲلذين من قبلكم قوم نوح وعاد وثمود', NULL, 256, 'local:warsh-text.json'),
  ('warsh-14-12', 'warsh', 14, 12, 'وَالذِينَ مِنۢ بَعْدِهِمْ࣌ لَا يَعْلَمُهُمُۥٓ إِلَّا ࡰ۬للَّهُ࣌ جَآءَتْهُمْ رُسُلُهُم بِالْبَيِّنَٰتِ فَرَدُّوٓاْ أَيْدِيَهُمْ فِےٓ أَفْوَٰهِهِمْ وَقَالُوٓاْ إِنَّا كَفَرْنَا بِمَآ أُرْسِلْتُم بِهِۦ وَإِنَّا لَفِے شَكࣲّ مِّمَّا تَدْعُونَنَآ إِلَيْهِ مُرِيبࣲ࣌', 'والذين من بعدهم࣌ لا يعلمهم إلا ࡰلله࣌ جاءتهم رسلهم بالبينت فردوا أيديهم فے أفوههم وقالوا إنا كفرنا بما أرسلتم به وإنا لفے شك مما تدعوننا إليه مريب࣌', NULL, 256, 'local:warsh-text.json'),
  ('warsh-14-13', 'warsh', 14, 13, '۞ قَالَتْ رُسُلُهُمُۥٓ أَفِے ࡴ۬للَّهِ شَكࣱّ فَاطِرِ ࡴ۬لسَّمَٰوَٰتِ وَالَارْضِ يَدْعُوكُمْ لِيَغْفِرَ لَكُم مِّن ذُنُوبِكُمْ وَيُوَ۬خِّرَكُمُۥٓ إِلَىٰٓ أَجَلࣲ مُّسَمّىࣰ࣌ قَالُوٓاْ إِنَ ࡰنتُمُۥٓ إِلَّا بَشَرࣱ مِّثْلُنَا تُرِيدُونَ أَن تَصُدُّونَا عَمَّا كَانَ يَعْبُدُ ءَابَآؤُنَا فَاتُونَا بِسُلْطَٰنࣲ مُّبِينࣲ࣌', 'قالت رسلهم أفے ࡴلله شك فاطر ࡴلسموت والارض يدعوكم ليغفر لكم من ذنوبكم ويوخركم إلى أجل مسمى࣌ قالوا إن ࡰنتم إلا بشر مثلنا تريدون أن تصدونا عما كان يعبد ءاباؤنا فاتونا بسلطن مبين࣌', NULL, 256, 'local:warsh-text.json'),
  ('warsh-14-14', 'warsh', 14, 14, 'قَالَتْ لَهُمْ رُسُلُهُمُۥٓ إِن نَّحْنُ إِلَّا بَشَرࣱ مِّثْلُكُمْ وَلَٰكِنَّ ࡰ۬للَّهَ يَمُنُّ عَلَىٰ مَنْ يَّشَآءُ مِنْ عِبَادِهِۦ࣌ وَمَا كَانَ لَنَآ أَن نَّاتِيَكُم بِسُلْطَٰنٍ ࡴلَّا بِإِذْنِ ࡴ۬للَّهِ࣌ وَعَلَى ࡰ۬للَّهِ فَلْيَتَوَكَّلِ ࡴ۬لْمُومِنُونَ࣌', 'قالت لهم رسلهم إن نحن إلا بشر مثلكم ولكن ࡰلله يمن على من يشاء من عباده࣌ وما كان لنا أن ناتيكم بسلطن ࡴلا بإذن ࡴلله࣌ وعلى ࡰلله فليتوكل ࡴلمومنون࣌', NULL, 257, 'local:warsh-text.json'),
  ('warsh-14-15', 'warsh', 14, 15, 'وَمَا لَنَآ أَلَّا نَتَوَكَّلَ عَلَى ࡰ۬للَّهِ وَقَدْ هَدٜيٰنَا سُبُلَنَا࣌ وَلَنَصْبِرَنَّ عَلَىٰ مَآ ءَاذَيْتُمُونَا࣌ وَعَلَى ࡰ۬للَّهِ فَلْيَتَوَكَّلِ ࡴ۬لْمُتَوَكِّلُونَ࣌', 'وما لنا ألا نتوكل على ࡰلله وقد هدينا سبلنا࣌ ولنصبرن على ما ءاذيتمونا࣌ وعلى ࡰلله فليتوكل ࡴلمتوكلون࣌', NULL, 257, 'local:warsh-text.json'),
  ('warsh-14-16', 'warsh', 14, 16, 'وَقَالَ ࡰ۬لذِينَ كَفَرُواْ لِرُسُلِهِمْ لَنُخْرِجَنَّكُم مِّنَ ࡰرْضِنَآ أَوْ لَتَعُودُنَّ فِے مِلَّتِنَا࣌ فَأَوْحٜىٰٓ إِلَيْهِمْ رَبُّهُمْ لَنُهْلِكَنَّ ࡰ۬لظَّٰلِمِينَ', 'وقال ࡰلذين كفروا لرسلهم لنخرجنكم من ࡰرضنا أو لتعودن فے ملتنا࣌ فأوحى إليهم ربهم لنهلكن ࡰلظلمين', NULL, 257, 'local:warsh-text.json'),
  ('warsh-14-17', 'warsh', 14, 17, 'وَلَنُسْكِنَنَّكُمُ ࡲ۬لَارْضَ مِنۢ بَعْدِهِمْ࣌ ذَٰلِكَ لِمَنْ خَافَ مَقَامِے وَخَافَ وَعِيدِۦ࣌', 'ولنسكننكم ࡲلارض من بعدهم࣌ ذلك لمن خاف مقامے وخاف وعيد࣌', NULL, 257, 'local:warsh-text.json'),
  ('warsh-14-18', 'warsh', 14, 18, 'وَاسْتَفْتَحُواْ࣌ وَخَابَ كُلُّ جَبّٜارٍ عَنِيدࣲ', 'واستفتحوا࣌ وخاب كل جبار عنيد', NULL, 257, 'local:warsh-text.json'),
  ('warsh-14-19', 'warsh', 14, 19, 'مِّنْ وَّرَآئِهِۦ جَهَنَّمُ وَيُسْقٜىٰ مِن مَّآءࣲ صَدِيدࣲ', 'من ورائه جهنم ويسقى من ماء صديد', NULL, 257, 'local:warsh-text.json'),
  ('warsh-14-20', 'warsh', 14, 20, 'يَتَجَرَّعُهُۥ وَلَا يَكَادُ يُسِيغُهُۥ وَيَاتِيهِ ࡴ۬لْمَوْتُ مِن كُلِّ مَكَانࣲ وَمَا هُوَ بِمَيِّتࣲ وَمِنْ وَّرَآئِهِۦ عَذَابٌ غَلِيظࣱ࣌', 'يتجرعه ولا يكاد يسيغه وياتيه ࡴلموت من كل مكان وما هو بميت ومن ورائه عذاب غليظ࣌', NULL, 257, 'local:warsh-text.json'),
  ('warsh-14-21', 'warsh', 14, 21, 'مَّثَلُ ࡲ۬لذِينَ كَفَرُواْ بِرَبِّهِمُۥٓ࣌ أَعْمَٰلُهُمْ كَرَمَادٍ ࡴٜشْتَدَّتْ بِهِ ࡴ۬لرِّيَٰحُ فِے يَوْمٍ عَاصِفࣲ لَّا يَقْدِرُونَ مِمَّا كَسَبُواْ عَلَىٰ شَےْءࣲ࣌ ذَٰلِكَ هُوَ ࡰ۬لضَّلَٰلُ ࡲ۬لْبَعِيدُ࣌', 'مثل ࡲلذين كفروا بربهم࣌ أعملهم كرماد ࡴشتدت به ࡴلريح فے يوم عاصف لا يقدرون مما كسبوا على شےء࣌ ذلك هو ࡰلضلل ࡲلبعيد࣌', NULL, 257, 'local:warsh-text.json'),
  ('warsh-14-22', 'warsh', 14, 22, '۞ أَلَمْ تَرَ أَنَّ ࡰ۬للَّهَ خَلَقَ ࡰ۬لسَّمَٰوَٰتِ وَالَارْضَ بِالْحَقِّ࣌ إِنْ يَّشَأْ يُذْهِبْكُمْ وَيَاتِ بِخَلْقࣲ جَدِيدࣲ࣌ وَمَا ذَٰلِكَ عَلَى ࡰ۬للَّهِ بِعَزِيزࣲ࣌', 'ألم تر أن ࡰلله خلق ࡰلسموت والارض بالحق࣌ إن يشأ يذهبكم ويات بخلق جديد࣌ وما ذلك على ࡰلله بعزيز࣌', NULL, 258, 'local:warsh-text.json'),
  ('warsh-14-23', 'warsh', 14, 23, 'وَبَرَزُواْ لِلهِ جَمِيعاࣰ فَقَالَ ࡰ۬لضُّعَفَٰٓؤُاْ لِلذِينَ ࡰٜسْتَكْبَرُوٓاْ إِنَّا كُنَّا لَكُمْ تَبَعاࣰ فَهَلَ ࡰنتُم مُّغْنُونَ عَنَّا مِنْ عَذَابِ ࡴ۬للَّهِ مِن شَےْءࣲ࣌ قَالُواْ لَوْ هَدٜيٰنَا ࡰ۬للَّهُ لَهَدَيْنَٰكُمْ࣌ سَوَآءٌ عَلَيْنَآ أَجَزِعْنَآ أَمْ صَبَرْنَا مَا لَنَا مِن مَّحِيصࣲ࣌', 'وبرزوا لله جميعا فقال ࡰلضعفؤا للذين ࡰستكبروا إنا كنا لكم تبعا فهل ࡰنتم مغنون عنا من عذاب ࡴلله من شےء࣌ قالوا لو هدينا ࡰلله لهدينكم࣌ سواء علينا أجزعنا أم صبرنا ما لنا من محيص࣌', NULL, 258, 'local:warsh-text.json'),
  ('warsh-14-24', 'warsh', 14, 24, 'وَقَالَ ࡰ۬لشَّيْطَٰنُ لَمَّا قُضِيَ ࡰ۬لَامْرُ إِنَّ ࡰ۬للَّهَ وَعَدَكُمْ وَعْدَ ࡰ۬لْحَقِّ وَوَعَدتُّكُمْ فَأَخْلَفْتُكُمْ وَمَا كَانَ لِے عَلَيْكُم مِّن سُلْطَٰنٍ ࡴلَّآ أَن دَعَوْتُكُمْ فَاسْتَجَبْتُمْ لِے فَلَا تَلُومُونِے وَلُومُوٓاْ أَنفُسَكُم مَّآ أَنَا بِمُصْرِخِكُمْ وَمَآ أَنتُم بِمُصْرِخِيَّ إِنِّے كَفَرْتُ بِمَآ أَشْرَكْتُمُونِ مِن قَبْلُ࣌ إِنَّ ࡰ۬لظَّٰلِمِينَ لَهُمْ عَذَابٌ ࡰلِيمࣱ࣌', 'وقال ࡰلشيطن لما قضي ࡰلامر إن ࡰلله وعدكم وعد ࡰلحق ووعدتكم فأخلفتكم وما كان لے عليكم من سلطن ࡴلا أن دعوتكم فاستجبتم لے فلا تلومونے ولوموا أنفسكم ما أنا بمصرخكم وما أنتم بمصرخي إنے كفرت بما أشركتمون من قبل࣌ إن ࡰلظلمين لهم عذاب ࡰليم࣌', NULL, 258, 'local:warsh-text.json'),
  ('warsh-14-25', 'warsh', 14, 25, 'وَأُدْخِلَ ࡰ۬لذِينَ ءَامَنُواْ وَعَمِلُواْ ࡲ۬لصَّٰلِحَٰتِ جَنَّٰتࣲ تَجْرِے مِن تَحْتِهَا ࡰ۬لَانْهَٰرُ خَٰلِدِينَ فِيهَا بِإِذْنِ رَبِّهِمْ࣌ تَحِيَّتُهُمْ فِيهَا سَلَٰمٌ࣌', 'وأدخل ࡰلذين ءامنوا وعملوا ࡲلصلحت جنت تجرے من تحتها ࡰلانهر خلدين فيها بإذن ربهم࣌ تحيتهم فيها سلم࣌', NULL, 258, 'local:warsh-text.json'),
  ('warsh-14-26', 'warsh', 14, 26, 'ࡰلَمْ تَرَ كَيْفَ ضَرَبَ ࡰ۬للَّهُ مَثَلاࣰ كَلِمَةࣰ طَيِّبَةࣰ كَشَجَرَةࣲ طَيِّبَةٍ ࡰصْلُهَا ثَابِتࣱ وَفَرْعُهَا فِے ࡴ۬لسَّمَآءِ', 'ࡰلم تر كيف ضرب ࡰلله مثلا كلمة طيبة كشجرة طيبة ࡰصلها ثابت وفرعها فے ࡴلسماء', NULL, 258, 'local:warsh-text.json'),
  ('warsh-14-27', 'warsh', 14, 27, 'تُوتِےٓ أُكْلَهَا كُلَّ حِينِۢ بِإِذْنِ رَبِّهَا࣌ وَيَضْرِبُ ࡲ۬للَّهُ ࡲ۬لَامْثَالَ لِلنَّاسِ لَعَلَّهُمْ يَتَذَكَّرُونَ࣌', 'توتے أكلها كل حين بإذن ربها࣌ ويضرب ࡲلله ࡲلامثال للناس لعلهم يتذكرون࣌', NULL, 259, 'local:warsh-text.json'),
  ('warsh-14-28', 'warsh', 14, 28, 'وَمَثَلُ كَلِمَةٍ خَبِيثَةࣲ كَشَجَرَةٍ خَبِيثَةٍ ࡲ࢈جْتُثَّتْ مِن فَوْقِ ࡴ۬لَارْضِ مَا لَهَا مِن قَرٜارࣲ࣌', 'ومثل كلمة خبيثة كشجرة خبيثة ࡲ࢈جتثت من فوق ࡴلارض ما لها من قرار࣌', NULL, 259, 'local:warsh-text.json'),
  ('warsh-14-29', 'warsh', 14, 29, 'يُثَبِّتُ ࡲ۬للَّهُ ࡲ۬لذِينَ ءَامَنُواْ بِالْقَوْلِ ࡴ۬لثَّابِتِ فِے ࡴ۬لْحَيَوٰةِ ࡴ۬لدُّنْيٜا وَفِے ࡴ۬لَاخِرَةِ࣌ وَيُضِلُّ ࡲ۬للَّهُ ࡲ۬لظَّٰلِمِينَ࣌ وَيَفْعَلُ ࡲ۬للَّهُ مَا يَشَآءُ࣌', 'يثبت ࡲلله ࡲلذين ءامنوا بالقول ࡴلثابت فے ࡴلحيوة ࡴلدنيا وفے ࡴلاخرة࣌ ويضل ࡲلله ࡲلظلمين࣌ ويفعل ࡲلله ما يشاء࣌', NULL, 259, 'local:warsh-text.json'),
  ('warsh-14-30', 'warsh', 14, 30, '۞ ࡶَلَمْ تَرَ إِلَى ࡰ۬لذِينَ بَدَّلُواْ نِعْمَتَ ࡰ۬للَّهِ كُفْراࣰ وَأَحَلُّواْ قَوْمَهُمْ دَارَ ࡰ۬لْبَوٜارِ', 'ࡶلم تر إلى ࡰلذين بدلوا نعمت ࡰلله كفرا وأحلوا قومهم دار ࡰلبوار', NULL, 259, 'local:warsh-text.json'),
  ('warsh-14-31', 'warsh', 14, 31, 'جَهَنَّمَ يَصْلَوْنَهَا࣌ وَبِيسَ ࡰ۬لْقَرَارُ࣌', 'جهنم يصلونها࣌ وبيس ࡰلقرار࣌', NULL, 259, 'local:warsh-text.json'),
  ('warsh-14-32', 'warsh', 14, 32, 'وَجَعَلُواْ لِلهِ أَندَاداࣰ لِّيُضِلُّواْ عَن سَبِيلِهِۦ࣌ قُلْ تَمَتَّعُواْ فَإِنَّ مَصِيرَكُمُۥٓ إِلَى ࡰ۬لنّٜارِ࣌', 'وجعلوا لله أندادا ليضلوا عن سبيله࣌ قل تمتعوا فإن مصيركم إلى ࡰلنار࣌', NULL, 259, 'local:warsh-text.json'),
  ('warsh-14-33', 'warsh', 14, 33, 'قُل لِّعِبَادِيَ ࡰ۬لذِينَ ءَامَنُواْ يُقِيمُواْ ࡲ۬لصَّلَوٰةَ وَيُنفِقُواْ مِمَّا رَزَقْنَٰهُمْ سِرّاࣰ وَعَلَٰنِيَةࣰ مِّن قَبْلِ أَنْ يَّاتِيَ يَوْمࣱ لَّا بَيْعࣱ فِيهِ وَلَا خِلَٰلٌ࣌', 'قل لعبادي ࡰلذين ءامنوا يقيموا ࡲلصلوة وينفقوا مما رزقنهم سرا وعلنية من قبل أن ياتي يوم لا بيع فيه ولا خلل࣌', NULL, 259, 'local:warsh-text.json'),
  ('warsh-14-34', 'warsh', 14, 34, 'ࡴ۬للَّهُ ࡲ۬لذِے خَلَقَ ࡰ۬لسَّمَٰوَٰتِ وَالَارْضَ وَأَنزَلَ مِنَ ࡰ۬لسَّمَآءِ مَآءࣰ فَأَخْرَجَ بِهِۦ مِنَ ࡰ۬لثَّمَرَٰتِ رِزْقاࣰ لَّكُمْ࣌ وَسَخَّرَ لَكُمُ ࡲ۬لْفُلْكَ لِتَجْرِيَ فِے ࡴ۬لْبَحْرِ بِأَمْرِهِۦ࣌ وَسَخَّرَ لَكُمُ ࡲ۬لَانْهَٰرَ࣌', 'ࡴلله ࡲلذے خلق ࡰلسموت والارض وأنزل من ࡰلسماء ماء فأخرج به من ࡰلثمرت رزقا لكم࣌ وسخر لكم ࡲلفلك لتجري فے ࡴلبحر بأمره࣌ وسخر لكم ࡲلانهر࣌', NULL, 259, 'local:warsh-text.json'),
  ('warsh-14-35', 'warsh', 14, 35, 'وَسَخَّرَ لَكُمُ ࡲ۬لشَّمْسَ وَالْقَمَرَ دَآئِبَيْنِ࣌ وَسَخَّرَ لَكُمُ ࡲ۬ليْلَ وَالنَّهَارَ࣌', 'وسخر لكم ࡲلشمس والقمر دائبين࣌ وسخر لكم ࡲليل والنهار࣌', NULL, 259, 'local:warsh-text.json'),
  ('warsh-14-36', 'warsh', 14, 36, 'وَءَاتٜيٰكُم مِّن كُلِّ مَا سَأَلْتُمُوهُ࣌ وَإِن تَعُدُّواْ نِعْمَتَ ࡰ۬للَّهِ لَا تُحْصُوهَآ࣌ إِنَّ ࡰ۬لِانسَٰنَ لَظَلُومࣱ كَفَّارࣱ࣌', 'وءاتيكم من كل ما سألتموه࣌ وإن تعدوا نعمت ࡰلله لا تحصوها࣌ إن ࡰلانسن لظلوم كفار࣌', NULL, 260, 'local:warsh-text.json'),
  ('warsh-14-37', 'warsh', 14, 37, 'وَإِذْ قَالَ إِبْرَٰهِيمُ رَبِّ ࡴٜجْعَلْ هَٰذَا ࡰ۬لْبَلَدَ ءَامِناࣰ وَاجْنُبْنِے وَبَنِيَّ أَن نَّعْبُدَ ࡰ۬لَاصْنَامَ࣌', 'وإذ قال إبرهيم رب ࡴجعل هذا ࡰلبلد ءامنا واجنبنے وبني أن نعبد ࡰلاصنام࣌', NULL, 260, 'local:warsh-text.json'),
  ('warsh-14-38', 'warsh', 14, 38, 'رَبِّ إِنَّهُنَّ أَضْلَلْنَ كَثِيراࣰ مِّنَ ࡰ۬لنَّاسِ فَمَن تَبِعَنِے فَإِنَّهُۥ مِنِّے وَمَنْ عَصٜانِے فَإِنَّكَ غَفُورࣱ رَّحِيمࣱ࣌', 'رب إنهن أضللن كثيرا من ࡰلناس فمن تبعنے فإنه منے ومن عصانے فإنك غفور رحيم࣌', NULL, 260, 'local:warsh-text.json'),
  ('warsh-14-39', 'warsh', 14, 39, 'رَّبَّنَآ إِنِّيَ أَسْكَنتُ مِن ذُرِّيَّتِے بِوَادٍ غَيْرِ ذِے زَرْعٍ عِندَ بَيْتِكَ ࡰ۬لْمُحَرَّمِ࣌ رَبَّنَا لِيُقِيمُواْ ࡲ۬لصَّلَوٰةَ فَاجْعَلَ ࡰفْـِٕدَةࣰ مِّنَ ࡰ۬لنَّاسِ تَهْوِےٓ إِلَيْهِمْ وَارْزُقْهُم مِّنَ ࡰ۬لثَّمَرَٰتِ لَعَلَّهُمْ يَشْكُرُونَ࣌', 'ربنا إني أسكنت من ذريتے بواد غير ذے زرع عند بيتك ࡰلمحرم࣌ ربنا ليقيموا ࡲلصلوة فاجعل ࡰفدة من ࡰلناس تهوے إليهم وارزقهم من ࡰلثمرت لعلهم يشكرون࣌', NULL, 260, 'local:warsh-text.json'),
  ('warsh-14-40', 'warsh', 14, 40, 'رَبَّنَآ إِنَّكَ تَعْلَمُ مَا نُخْفِے وَمَا نُعْلِنُ࣌ وَمَا يَخْفٜىٰ عَلَى ࡰ۬للَّهِ مِن شَےْءࣲ فِے ࡴ۬لَارْضِ وَلَا فِے ࡴ۬لسَّمَآءِ࣌', 'ربنا إنك تعلم ما نخفے وما نعلن࣌ وما يخفى على ࡰلله من شےء فے ࡴلارض ولا فے ࡴلسماء࣌', NULL, 260, 'local:warsh-text.json'),
  ('warsh-14-41', 'warsh', 14, 41, '۞ ࡴ۬لْحَمْدُ لِلهِ ࡴ۬لذِے وَهَبَ لِے عَلَى ࡰ۬لْكِبَرِ إِسْمَٰعِيلَ وَإِسْحَٰقَ࣌ إِنَّ رَبِّے لَسَمِيعُ ࡲ۬لدُّعَآءِ࣌', 'ࡴلحمد لله ࡴلذے وهب لے على ࡰلكبر إسمعيل وإسحق࣌ إن ربے لسميع ࡲلدعاء࣌', NULL, 260, 'local:warsh-text.json'),
  ('warsh-14-42', 'warsh', 14, 42, 'رَبِّ ࡴٜجْعَلْنِے مُقِيمَ ࡰ۬لصَّلَوٰةِ وَمِن ذُرِّيَّتِے࣌ رَبَّنَا وَتَقَبَّلْ دُعَآءِۦ࣌', 'رب ࡴجعلنے مقيم ࡰلصلوة ومن ذريتے࣌ ربنا وتقبل دعاء࣌', NULL, 260, 'local:warsh-text.json'),
  ('warsh-14-43', 'warsh', 14, 43, 'رَبَّنَا ࡰٜغْفِرْ لِے وَلِوَٰلِدَيَّ وَلِلْمُومِنِينَ يَوْمَ يَقُومُ ࡲ۬لْحِسَابُ࣌', 'ربنا ࡰغفر لے ولولدي وللمومنين يوم يقوم ࡲلحساب࣌', NULL, 260, 'local:warsh-text.json'),
  ('warsh-14-44', 'warsh', 14, 44, 'وَلَا تَحْسِبَنَّ ࡰ۬للَّهَ غَٰفِلاً عَمَّا يَعْمَلُ ࡲ۬لظَّٰلِمُونَ࣌ إِنَّمَا يُوَ۬خِّرُهُمْ لِيَوْمࣲ تَشْخَصُ فِيهِ ࡴ۬لَابْصَٰرُ', 'ولا تحسبن ࡰلله غفلا عما يعمل ࡲلظلمون࣌ إنما يوخرهم ليوم تشخص فيه ࡴلابصر', NULL, 260, 'local:warsh-text.json'),
  ('warsh-14-45', 'warsh', 14, 45, 'مُهْطِعِينَ مُقْنِعِے رُءُوسِهِمْ لَا يَرْتَدُّ إِلَيْهِمْ طَرْفُهُمْ وَأَفْـِٕدَتُهُمْ هَوَآءࣱ࣌', 'مهطعين مقنعے رءوسهم لا يرتد إليهم طرفهم وأفدتهم هواء࣌', NULL, 261, 'local:warsh-text.json'),
  ('warsh-14-46', 'warsh', 14, 46, 'وَأَنذِرِ ࡴ۬لنَّاسَ يَوْمَ يَاتِيهِمُ ࡲ۬لْعَذَابُ فَيَقُولُ ࡲ۬لذِينَ ظَلَمُواْ رَبَّنَآ أَخِّرْنَآ إِلَىٰٓ أَجَلࣲ قَرِيبࣲ نُّجِبْ دَعْوَتَكَ وَنَتَّبِعِ ࡴ۬لرُّسُلَ࣌ أَوَلَمْ تَكُونُوٓاْ أَقْسَمْتُم مِّن قَبْلُ مَا لَكُم مِّن زَوَالࣲ࣌', 'وأنذر ࡴلناس يوم ياتيهم ࡲلعذاب فيقول ࡲلذين ظلموا ربنا أخرنا إلى أجل قريب نجب دعوتك ونتبع ࡴلرسل࣌ أولم تكونوا أقسمتم من قبل ما لكم من زوال࣌', NULL, 261, 'local:warsh-text.json'),
  ('warsh-14-47', 'warsh', 14, 47, 'وَسَكَنتُمْ فِے مَسَٰكِنِ ࡴ۬لذِينَ ظَلَمُوٓاْ أَنفُسَهُمْ وَتَبَيَّنَ لَكُمْ كَيْفَ فَعَلْنَا بِهِمْ وَضَرَبْنَا لَكُمُ ࡲ۬لَامْثَالَ࣌', 'وسكنتم فے مسكن ࡴلذين ظلموا أنفسهم وتبين لكم كيف فعلنا بهم وضربنا لكم ࡲلامثال࣌', NULL, 261, 'local:warsh-text.json'),
  ('warsh-14-48', 'warsh', 14, 48, 'وَقَدْ مَكَرُواْ مَكْرَهُمْ࣌ وَعِندَ ࡰ۬للَّهِ مَكْرُهُمْ࣌ وَإِن كَانَ مَكْرُهُمْ لِتَزُولَ مِنْهُ ࡲ۬لْجِبَالُ࣌', 'وقد مكروا مكرهم࣌ وعند ࡰلله مكرهم࣌ وإن كان مكرهم لتزول منه ࡲلجبال࣌', NULL, 261, 'local:warsh-text.json'),
  ('warsh-14-49', 'warsh', 14, 49, 'فَلَا تَحْسِبَنَّ ࡰ۬للَّهَ مُخْلِفَ وَعْدِهِۦ رُسُلَهُۥٓ࣌ إِنَّ ࡰ۬للَّهَ عَزِيزࣱ ذُو ࡲٜنتِقَامࣲ࣌', 'فلا تحسبن ࡰلله مخلف وعده رسله࣌ إن ࡰلله عزيز ذو ࡲنتقام࣌', NULL, 261, 'local:warsh-text.json'),
  ('warsh-14-50', 'warsh', 14, 50, 'يَوْمَ تُبَدَّلُ ࡲ۬لَارْضُ غَيْرَ ࡰ۬لَارْضِ وَالسَّمَٰوَٰتُ࣌ وَبَرَزُواْ لِلهِ ࡴ۬لْوَٰحِدِ ࡴ۬لْقَهّٜارِ࣌', 'يوم تبدل ࡲلارض غير ࡰلارض والسموت࣌ وبرزوا لله ࡴلوحد ࡴلقهار࣌', NULL, 261, 'local:warsh-text.json'),
  ('warsh-14-51', 'warsh', 14, 51, 'وَتَرَى ࡰ۬لْمُجْرِمِينَ يَوْمَئِذࣲ مُّقَرَّنِينَ فِے ࡴ۬لَاصْفَادِ', 'وترى ࡰلمجرمين يومئذ مقرنين فے ࡴلاصفاد', NULL, 261, 'local:warsh-text.json'),
  ('warsh-14-52', 'warsh', 14, 52, 'سَرَابِيلُهُم مِّن قَطِرَانࣲ وَتَغْشٜىٰ وُجُوهَهُمُ ࡲ۬لنَّارُ', 'سرابيلهم من قطران وتغشى وجوههم ࡲلنار', NULL, 261, 'local:warsh-text.json'),
  ('warsh-14-53', 'warsh', 14, 53, 'لِيَجْزِيَ ࡰ۬للَّهُ كُلَّ نَفْسࣲ مَّا كَسَبَتِ࣌ ࡴنَّ ࡰ۬للَّهَ سَرِيعُ ࡲ۬لْحِسَابِ࣌', 'ليجزي ࡰلله كل نفس ما كسبت࣌ ࡴن ࡰلله سريع ࡲلحساب࣌', NULL, 261, 'local:warsh-text.json'),
  ('warsh-14-54', 'warsh', 14, 54, 'هَٰذَا بَلَٰغࣱ لِّلنَّاسِ وَلِيُنذَرُواْ بِهِۦ وَلِيَعْلَمُوٓاْ أَنَّمَا هُوَ إِلَٰهࣱ وَٰحِدࣱ وَلِيَذَّكَّرَ أُوْلُواْ ࡲ۬لَالْبَٰبِ࣌', 'هذا بلغ للناس ولينذروا به وليعلموا أنما هو إله وحد وليذكر أولوا ࡲلالبب࣌', NULL, 261, 'local:warsh-text.json'),
  ('warsh-15-1', 'warsh', 15, 1, 'أَلَٓرٜ࣌ تِلْكَ ءَايَٰتُ ࡲ۬لْكِتَٰبِ وَقُرْءَانࣲ مُّبِينࣲ࣌', 'ألر࣌ تلك ءايت ࡲلكتب وقرءان مبين࣌', NULL, 262, 'local:warsh-text.json'),
  ('warsh-15-2', 'warsh', 15, 2, 'رُّبَمَا يَوَدُّ ࡲ۬لذِينَ كَفَرُواْ لَوْ كَانُواْ مُسْلِمِينَ࣌', 'ربما يود ࡲلذين كفروا لو كانوا مسلمين࣌', NULL, 262, 'local:warsh-text.json'),
  ('warsh-15-3', 'warsh', 15, 3, 'ذَرْهُمْ يَاكُلُواْ وَيَتَمَتَّعُواْ وَيُلْهِهِمُ ࡲ۬لَامَلُ࣌ فَسَوْفَ يَعْلَمُونَ࣌', 'ذرهم ياكلوا ويتمتعوا ويلههم ࡲلامل࣌ فسوف يعلمون࣌', NULL, 262, 'local:warsh-text.json'),
  ('warsh-15-4', 'warsh', 15, 4, 'وَمَآ أَهْلَكْنَا مِن قَرْيَةٍ ࡴلَّا وَلَهَا كِتَابࣱ مَّعْلُومࣱ࣌', 'وما أهلكنا من قرية ࡴلا ولها كتاب معلوم࣌', NULL, 262, 'local:warsh-text.json'),
  ('warsh-15-5', 'warsh', 15, 5, 'مَّا تَسْبِقُ مِنُ ࡳمَّةٍ ࡰجَلَهَا وَمَا يَسْتَٰخِرُونَ࣌', 'ما تسبق من ࡳمة ࡰجلها وما يستخرون࣌', NULL, 262, 'local:warsh-text.json'),
  ('warsh-15-6', 'warsh', 15, 6, 'وَقَالُواْ يَٰٓأَيُّهَا ࡰ۬لذِے نُزِّلَ عَلَيْهِ ࡴ۬لذِّكْرُ إِنَّكَ لَمَجْنُونࣱ', 'وقالوا يأيها ࡰلذے نزل عليه ࡴلذكر إنك لمجنون', NULL, 262, 'local:warsh-text.json'),
  ('warsh-15-7', 'warsh', 15, 7, 'لَّوْمَا تَاتِينَا بِالْمَلَٰٓئِكَةِ إِن كُنتَ مِنَ ࡰ۬لصَّٰدِقِينَ࣌', 'لوما تاتينا بالملئكة إن كنت من ࡰلصدقين࣌', NULL, 262, 'local:warsh-text.json'),
  ('warsh-15-8', 'warsh', 15, 8, 'مَا تَنَزَّلُ ࡲ۬لْمَلَٰٓئِكَةُ إِلَّا بِالْحَقِّ࣌ وَمَا كَانُوٓاْ إِذاࣰ مُّنظَرِينَ࣌', 'ما تنزل ࡲلملئكة إلا بالحق࣌ وما كانوا إذا منظرين࣌', NULL, 262, 'local:warsh-text.json'),
  ('warsh-15-9', 'warsh', 15, 9, 'إِنَّا نَحْنُ نَزَّلْنَا ࡰ۬لذِّكْرَ࣌ وَإِنَّا لَهُۥ لَحَٰفِظُونَ࣌', 'إنا نحن نزلنا ࡰلذكر࣌ وإنا له لحفظون࣌', NULL, 262, 'local:warsh-text.json'),
  ('warsh-15-10', 'warsh', 15, 10, 'وَلَقَدَ ࡰرْسَلْنَا مِن قَبْلِكَ فِے شِيَعِ ࡴ۬لَاوَّلِينَ࣌', 'ولقد ࡰرسلنا من قبلك فے شيع ࡴلاولين࣌', NULL, 262, 'local:warsh-text.json'),
  ('warsh-15-11', 'warsh', 15, 11, 'وَمَا يَاتِيهِم مِّن رَّسُولٍ ࡴلَّا كَانُواْ بِهِۦ يَسْتَهْزِءُونَ࣌', 'وما ياتيهم من رسول ࡴلا كانوا به يستهزءون࣌', NULL, 262, 'local:warsh-text.json'),
  ('warsh-15-12', 'warsh', 15, 12, 'كَذَٰلِكَ نَسْلُكُهُۥ فِے قُلُوبِ ࡴ۬لْمُجْرِمِينَ', 'كذلك نسلكه فے قلوب ࡴلمجرمين', NULL, 262, 'local:warsh-text.json'),
  ('warsh-15-13', 'warsh', 15, 13, 'لَا يُومِنُونَ بِهِۦ وَقَدْ خَلَتْ سُنَّةُ ࡲ۬لَاوَّلِينَ࣌', 'لا يومنون به وقد خلت سنة ࡲلاولين࣌', NULL, 262, 'local:warsh-text.json'),
  ('warsh-15-14', 'warsh', 15, 14, 'وَلَوْ فَتَحْنَا عَلَيْهِم بَاباࣰ مِّنَ ࡰ۬لسَّمَآءِ فَظَلُّواْ فِيهِ يَعْرُجُونَ', 'ولو فتحنا عليهم بابا من ࡰلسماء فظلوا فيه يعرجون', NULL, 262, 'local:warsh-text.json'),
  ('warsh-15-15', 'warsh', 15, 15, 'لَقَالُوٓاْ إِنَّمَا سُكِّرَتَ ࡰبْصَٰرُنَا بَلْ نَحْنُ قَوْمࣱ مَّسْحُورُونَ࣌', 'لقالوا إنما سكرت ࡰبصرنا بل نحن قوم مسحورون࣌', NULL, 262, 'local:warsh-text.json'),
  ('warsh-15-16', 'warsh', 15, 16, 'وَلَقَدْ جَعَلْنَا فِے ࡴ۬لسَّمَآءِ بُرُوجاࣰ وَزَيَّنَّٰهَا لِلنَّٰظِرِينَ', 'ولقد جعلنا فے ࡴلسماء بروجا وزينها للنظرين', NULL, 263, 'local:warsh-text.json'),
  ('warsh-15-17', 'warsh', 15, 17, 'وَحَفِظْنَٰهَا مِن كُلِّ شَيْطَٰنࣲ رَّجِيمٍ', 'وحفظنها من كل شيطن رجيم', NULL, 263, 'local:warsh-text.json'),
  ('warsh-15-18', 'warsh', 15, 18, 'ࡴلَّا مَنِ ࡴٜسْتَرَقَ ࡰ۬لسَّمْعَ فَأَتْبَعَهُۥ شِهَابࣱ مُّبِينࣱ࣌', 'ࡴلا من ࡴسترق ࡰلسمع فأتبعه شهاب مبين࣌', NULL, 263, 'local:warsh-text.json'),
  ('warsh-15-19', 'warsh', 15, 19, 'وَالَارْضَ مَدَدْنَٰهَا وَأَلْقَيْنَا فِيهَا رَوَٰسِيَ وَأَنۢبَتْنَا فِيهَا مِن كُلِّ شَےْءࣲ مَّوْزُونࣲ', 'والارض مددنها وألقينا فيها روسي وأنبتنا فيها من كل شےء موزون', NULL, 263, 'local:warsh-text.json'),
  ('warsh-15-20', 'warsh', 15, 20, 'وَجَعَلْنَا لَكُمْ فِيهَا مَعَٰيِشَ࣌ وَمَن لَّسْتُمْ لَهُۥ بِرَٰزِقِينَ࣌', 'وجعلنا لكم فيها معيش࣌ ومن لستم له برزقين࣌', NULL, 263, 'local:warsh-text.json'),
  ('warsh-15-21', 'warsh', 15, 21, 'وَإِن مِّن شَےْءٍ ࡴلَّا عِندَنَا خَزَآئِنُهُۥ࣌ وَمَا نُنَزِّلُهُۥٓ إِلَّا بِقَدَرࣲ مَّعْلُومࣲ࣌', 'وإن من شےء ࡴلا عندنا خزائنه࣌ وما ننزله إلا بقدر معلوم࣌', NULL, 263, 'local:warsh-text.json'),
  ('warsh-15-22', 'warsh', 15, 22, '۞ وَأَرْسَلْنَا ࡰ۬لرِّيَٰحَ لَوَٰقِحَ فَأَنزَلْنَا مِنَ ࡰ۬لسَّمَآءِ مَآءࣰ فَأَسْقَيْنَٰكُمُوهُ وَمَآ أَنتُمْ لَهُۥ بِخَٰزِنِينَ࣌', 'وأرسلنا ࡰلريح لوقح فأنزلنا من ࡰلسماء ماء فأسقينكموه وما أنتم له بخزنين࣌', NULL, 263, 'local:warsh-text.json'),
  ('warsh-15-23', 'warsh', 15, 23, 'وَإِنَّا لَنَحْنُ نُحْيِۦ وَنُمِيتُ وَنَحْنُ ࡲ۬لْوَٰرِثُونَ࣌', 'وإنا لنحن نحي ونميت ونحن ࡲلورثون࣌', NULL, 263, 'local:warsh-text.json'),
  ('warsh-15-24', 'warsh', 15, 24, 'وَلَقَدْ عَلِمْنَا ࡰ۬لْمُسْتَقْدِمِينَ مِنكُمْ وَلَقَدْ عَلِمْنَا ࡰ۬لْمُسْتَٰخِرِينَ࣌', 'ولقد علمنا ࡰلمستقدمين منكم ولقد علمنا ࡰلمستخرين࣌', NULL, 263, 'local:warsh-text.json'),
  ('warsh-15-25', 'warsh', 15, 25, 'وَإِنَّ رَبَّكَ هُوَ يَحْشُرُهُمُۥٓ࣌ إِنَّهُۥ حَكِيمٌ عَلِيمࣱ࣌', 'وإن ربك هو يحشرهم࣌ إنه حكيم عليم࣌', NULL, 263, 'local:warsh-text.json'),
  ('warsh-15-26', 'warsh', 15, 26, 'وَلَقَدْ خَلَقْنَا ࡰ۬لِانسَٰنَ مِن صَلْصَٰلࣲ مِّنْ حَمَإࣲ مَّسْنُونࣲ࣌', 'ولقد خلقنا ࡰلانسن من صلصل من حمإ مسنون࣌', NULL, 263, 'local:warsh-text.json'),
  ('warsh-15-27', 'warsh', 15, 27, 'وَالْجَآنَّ خَلَقْنَٰهُ مِن قَبْلُ مِن نّٜارِ ࡴ۬لسَّمُومِ࣌', 'والجان خلقنه من قبل من نار ࡴلسموم࣌', NULL, 263, 'local:warsh-text.json'),
  ('warsh-15-28', 'warsh', 15, 28, 'وَإِذْ قَالَ رَبُّكَ لِلْمَلَٰٓئِكَةِ إِنِّے خَٰلِقُۢ بَشَراࣰ مِّن صَلْصَٰلࣲ مِّنْ حَمَإࣲ مَّسْنُونࣲ', 'وإذ قال ربك للملئكة إنے خلق بشرا من صلصل من حمإ مسنون', NULL, 263, 'local:warsh-text.json'),
  ('warsh-15-29', 'warsh', 15, 29, 'فَإِذَا سَوَّيْتُهُۥ وَنَفَخْتُ فِيهِ مِن رُّوحِے فَقَعُواْ لَهُۥ سَٰجِدِينَ࣌', 'فإذا سويته ونفخت فيه من روحے فقعوا له سجدين࣌', NULL, 263, 'local:warsh-text.json'),
  ('warsh-15-30', 'warsh', 15, 30, 'فَسَجَدَ ࡰ۬لْمَلَٰٓئِكَةُ كُلُّهُمُۥٓ أَجْمَعُونَ', 'فسجد ࡰلملئكة كلهم أجمعون', NULL, 263, 'local:warsh-text.json'),
  ('warsh-15-31', 'warsh', 15, 31, 'إِلَّآ إِبْلِيسَ أَبٜىٰٓ أَنْ يَّكُونَ مَعَ ࡰ۬لسَّٰجِدِينَ࣌', 'إلا إبليس أبى أن يكون مع ࡰلسجدين࣌', NULL, 263, 'local:warsh-text.json'),
  ('warsh-15-32', 'warsh', 15, 32, 'قَالَ يَٰٓإِبْلِيسُ مَا لَكَ أَلَّا تَكُونَ مَعَ ࡰ۬لسَّٰجِدِينَ࣌', 'قال يإبليس ما لك ألا تكون مع ࡰلسجدين࣌', NULL, 264, 'local:warsh-text.json'),
  ('warsh-15-33', 'warsh', 15, 33, 'قَالَ لَمَ ࡰكُن لِّأَسْجُدَ لِبَشَرٍ خَلَقْتَهُۥ مِن صَلْصَٰلࣲ مِّنْ حَمَإࣲ مَّسْنُونࣲ࣌', 'قال لم ࡰكن لأسجد لبشر خلقته من صلصل من حمإ مسنون࣌', NULL, 264, 'local:warsh-text.json'),
  ('warsh-15-34', 'warsh', 15, 34, 'قَالَ فَاخْرُجْ مِنْهَا فَإِنَّكَ رَجِيمࣱ', 'قال فاخرج منها فإنك رجيم', NULL, 264, 'local:warsh-text.json'),
  ('warsh-15-35', 'warsh', 15, 35, 'وَإِنَّ عَلَيْكَ ࡰ۬للَّعْنَةَ إِلَىٰ يَوْمِ ࡴ۬لدِّينِ࣌', 'وإن عليك ࡰللعنة إلى يوم ࡴلدين࣌', NULL, 264, 'local:warsh-text.json'),
  ('warsh-15-36', 'warsh', 15, 36, 'قَالَ رَبِّ فَأَنظِرْنِےٓ إِلَىٰ يَوْمِ يُبْعَثُونَ࣌', 'قال رب فأنظرنے إلى يوم يبعثون࣌', NULL, 264, 'local:warsh-text.json'),
  ('warsh-15-37', 'warsh', 15, 37, 'قَالَ فَإِنَّكَ مِنَ ࡰ۬لْمُنظَرِينَ', 'قال فإنك من ࡰلمنظرين', NULL, 264, 'local:warsh-text.json'),
  ('warsh-15-38', 'warsh', 15, 38, 'إِلَىٰ يَوْمِ ࡴ۬لْوَقْتِ ࡴ۬لْمَعْلُومِ࣌', 'إلى يوم ࡴلوقت ࡴلمعلوم࣌', NULL, 264, 'local:warsh-text.json'),
  ('warsh-15-39', 'warsh', 15, 39, 'قَالَ رَبِّ بِمَآ أَغْوَيْتَنِے لَأُزَيِّنَنَّ لَهُمْ فِے ࡴ۬لَارْضِ وَلَأُغْوِيَنَّهُمُۥٓ أَجْمَعِينَ', 'قال رب بما أغويتنے لأزينن لهم فے ࡴلارض ولأغوينهم أجمعين', NULL, 264, 'local:warsh-text.json'),
  ('warsh-15-40', 'warsh', 15, 40, 'إِلَّا عِبَادَكَ مِنْهُمُ ࡲ۬لْمُخْلَصِينَ࣌', 'إلا عبادك منهم ࡲلمخلصين࣌', NULL, 264, 'local:warsh-text.json'),
  ('warsh-15-41', 'warsh', 15, 41, 'قَالَ هَٰذَا صِرَٰطٌ عَلَيَّ مُسْتَقِيمٌ࣌', 'قال هذا صرط علي مستقيم࣌', NULL, 264, 'local:warsh-text.json'),
  ('warsh-15-42', 'warsh', 15, 42, 'ࡴنَّ عِبَادِے لَيْسَ لَكَ عَلَيْهِمْ سُلْطَٰنٌ ࡴلَّا مَنِ ࡴٜتَّبَعَكَ مِنَ ࡰ۬لْغَاوِينَ࣌', 'ࡴن عبادے ليس لك عليهم سلطن ࡴلا من ࡴتبعك من ࡰلغاوين࣌', NULL, 264, 'local:warsh-text.json'),
  ('warsh-15-43', 'warsh', 15, 43, 'وَإِنَّ جَهَنَّمَ لَمَوْعِدُهُمُۥٓ أَجْمَعِينَ', 'وإن جهنم لموعدهم أجمعين', NULL, 264, 'local:warsh-text.json'),
  ('warsh-15-44', 'warsh', 15, 44, 'لَهَا سَبْعَةُ أَبْوَٰبࣲ࣌ لِّكُلِّ بَابࣲ مِّنْهُمْ جُزْءࣱ مَّقْسُومٌ࣌', 'لها سبعة أبوب࣌ لكل باب منهم جزء مقسوم࣌', NULL, 264, 'local:warsh-text.json'),
  ('warsh-15-45', 'warsh', 15, 45, 'ࡴنَّ ࡰ۬لْمُتَّقِينَ فِے جَنَّٰتࣲ وَعُيُونٍ', 'ࡴن ࡰلمتقين فے جنت وعيون', NULL, 264, 'local:warsh-text.json'),
  ('warsh-15-46', 'warsh', 15, 46, 'ࡲ࢈دْخُلُوهَا بِسَلَٰمٍ اٰمِنِينَ࣌', 'ࡲ࢈دخلوها بسلم امنين࣌', NULL, 264, 'local:warsh-text.json'),
  ('warsh-15-47', 'warsh', 15, 47, 'وَنَزَعْنَا مَا فِے صُدُورِهِم مِّنْ غِلٍّ࣌ ࡴخْوَٰناً عَلَىٰ سُرُرࣲ مُّتَقَٰبِلِينَ࣌', 'ونزعنا ما فے صدورهم من غل࣌ ࡴخونا على سرر متقبلين࣌', NULL, 264, 'local:warsh-text.json'),
  ('warsh-15-48', 'warsh', 15, 48, 'لَا يَمَسُّهُمْ فِيهَا نَصَبࣱ࣌ وَمَا هُم مِّنْهَا بِمُخْرَجِينَ࣌', 'لا يمسهم فيها نصب࣌ وما هم منها بمخرجين࣌', NULL, 264, 'local:warsh-text.json'),
  ('warsh-15-49', 'warsh', 15, 49, '۞ نَبِّۓْ عِبَادِيَ أَنِّيَ أَنَا ࡰ۬لْغَفُورُ ࡲ۬لرَّحِيمُ', 'نبے عبادي أني أنا ࡰلغفور ࡲلرحيم', NULL, 264, 'local:warsh-text.json'),
  ('warsh-15-50', 'warsh', 15, 50, 'وَأَنَّ عَذَابِے هُوَ ࡰ۬لْعَذَابُ ࡲ۬لَالِيمُ࣌', 'وأن عذابے هو ࡰلعذاب ࡲلاليم࣌', NULL, 264, 'local:warsh-text.json'),
  ('warsh-15-51', 'warsh', 15, 51, 'وَنَبِّئْهُمْ عَن ضَيْفِ إِبْرَٰهِيمَ', 'ونبئهم عن ضيف إبرهيم', NULL, 264, 'local:warsh-text.json'),
  ('warsh-15-52', 'warsh', 15, 52, 'إِذْ دَخَلُواْ عَلَيْهِ فَقَالُواْ سَلَٰماࣰ࣌ قَالَ إِنَّا مِنكُمْ وَجِلُونَ࣌', 'إذ دخلوا عليه فقالوا سلما࣌ قال إنا منكم وجلون࣌', NULL, 265, 'local:warsh-text.json'),
  ('warsh-15-53', 'warsh', 15, 53, 'قَالُواْ لَا تَوْجَلِ ࡴنَّا نُبَشِّرُكَ بِغُلَٰمٍ عَلِيمࣲ࣌', 'قالوا لا توجل ࡴنا نبشرك بغلم عليم࣌', NULL, 265, 'local:warsh-text.json'),
  ('warsh-15-54', 'warsh', 15, 54, 'قَالَ أَبَشَّرْتُمُونِے عَلَىٰٓ أَن مَّسَّنِيَ ࡰ۬لْكِبَرُ فَبِمَ تُبَشِّرُونِ࣌', 'قال أبشرتمونے على أن مسني ࡰلكبر فبم تبشرون࣌', NULL, 265, 'local:warsh-text.json'),
  ('warsh-15-55', 'warsh', 15, 55, 'قَالُواْ بَشَّرْنَٰكَ بِالْحَقِّ فَلَا تَكُن مِّنَ ࡰ۬لْقَٰنِطِينَ࣌', 'قالوا بشرنك بالحق فلا تكن من ࡰلقنطين࣌', NULL, 265, 'local:warsh-text.json'),
  ('warsh-15-56', 'warsh', 15, 56, 'قَالَ وَمَنْ يَّقْنَطُ مِن رَّحْمَةِ رَبِّهِۦٓ إِلَّا ࡰ۬لضَّآلُّونَ࣌', 'قال ومن يقنط من رحمة ربه إلا ࡰلضالون࣌', NULL, 265, 'local:warsh-text.json'),
  ('warsh-15-57', 'warsh', 15, 57, 'قَالَ فَمَا خَطْبُكُمُۥٓ أَيُّهَا ࡰ۬لْمُرْسَلُونَ࣌', 'قال فما خطبكم أيها ࡰلمرسلون࣌', NULL, 265, 'local:warsh-text.json'),
  ('warsh-15-58', 'warsh', 15, 58, 'قَالُوٓاْ إِنَّآ أُرْسِلْنَآ إِلَىٰ قَوْمࣲ مُّجْرِمِينَ', 'قالوا إنا أرسلنا إلى قوم مجرمين', NULL, 265, 'local:warsh-text.json'),
  ('warsh-15-59', 'warsh', 15, 59, 'إِلَّآ ءَالَ لُوطٍ࣌ ࡴنَّا لَمُنَجُّوهُمُۥٓ أَجْمَعِينَ', 'إلا ءال لوط࣌ ࡴنا لمنجوهم أجمعين', NULL, 265, 'local:warsh-text.json'),
  ('warsh-15-60', 'warsh', 15, 60, 'إِلَّا ࡰٜمْرَأَتَهُۥ قَدَّرْنَآ إِنَّهَا لَمِنَ ࡰ۬لْغَٰبِرِينَ࣌', 'إلا ࡰمرأته قدرنا إنها لمن ࡰلغبرين࣌', NULL, 265, 'local:warsh-text.json'),
  ('warsh-15-61', 'warsh', 15, 61, 'فَلَمَّا جَآءَ ࢇالَ لُوطٍ ࡴ۬لْمُرْسَلُونَ', 'فلما جاء ࢇال لوط ࡴلمرسلون', NULL, 265, 'local:warsh-text.json'),
  ('warsh-15-62', 'warsh', 15, 62, 'قَالَ إِنَّكُمْ قَوْمࣱ مُّنكَرُونَ࣌', 'قال إنكم قوم منكرون࣌', NULL, 265, 'local:warsh-text.json'),
  ('warsh-15-63', 'warsh', 15, 63, 'قَالُواْ بَلْ جِئْنَٰكَ بِمَا كَانُواْ فِيهِ يَمْتَرُونَ', 'قالوا بل جئنك بما كانوا فيه يمترون', NULL, 265, 'local:warsh-text.json'),
  ('warsh-15-64', 'warsh', 15, 64, 'وَأَتَيْنَٰكَ بِالْحَقِّ وَإِنَّا لَصَٰدِقُونَ࣌', 'وأتينك بالحق وإنا لصدقون࣌', NULL, 265, 'local:warsh-text.json'),
  ('warsh-15-65', 'warsh', 15, 65, 'فَاسْرِ بِأَهْلِكَ بِقِطْعࣲ مِّنَ ࡰ۬ليْلِ وَاتَّبِعَ ࡰدْبَٰرَهُمْ وَلَا يَلْتَفِتْ مِنكُمُۥٓ أَحَدࣱ وَامْضُواْ حَيْثُ تُومَرُونَ࣌', 'فاسر بأهلك بقطع من ࡰليل واتبع ࡰدبرهم ولا يلتفت منكم أحد وامضوا حيث تومرون࣌', NULL, 265, 'local:warsh-text.json'),
  ('warsh-15-66', 'warsh', 15, 66, 'وَقَضَيْنَآ إِلَيْهِ ذَٰلِكَ ࡰ۬لَامْرَ أَنَّ دَابِرَ هَٰٓؤُلَآءِ مَقْطُوعࣱ مُّصْبِحِينَ࣌', 'وقضينا إليه ذلك ࡰلامر أن دابر هؤلاء مقطوع مصبحين࣌', NULL, 265, 'local:warsh-text.json'),
  ('warsh-15-67', 'warsh', 15, 67, 'وَجَآءَ اهْلُ ࡲ۬لْمَدِينَةِ يَسْتَبْشِرُونَ࣌', 'وجاء اهل ࡲلمدينة يستبشرون࣌', NULL, 265, 'local:warsh-text.json'),
  ('warsh-15-68', 'warsh', 15, 68, 'قَالَ إِنَّ هَٰٓؤُلَآءِ ضَيْفِے فَلَا تَفْضَحُونِ࣌', 'قال إن هؤلاء ضيفے فلا تفضحون࣌', NULL, 265, 'local:warsh-text.json'),
  ('warsh-15-69', 'warsh', 15, 69, 'وَاتَّقُواْ ࡲ۬للَّهَ وَلَا تُخْزُونِ࣌', 'واتقوا ࡲلله ولا تخزون࣌', NULL, 265, 'local:warsh-text.json'),
  ('warsh-15-70', 'warsh', 15, 70, 'قَالُوٓاْ أَوَلَمْ نَنْهَكَ عَنِ ࡴ۬لْعَٰلَمِينَ࣌', 'قالوا أولم ننهك عن ࡴلعلمين࣌', NULL, 265, 'local:warsh-text.json'),
  ('warsh-15-71', 'warsh', 15, 71, 'قَالَ هَٰٓؤُلَآءِ بَنَاتِيَ إِن كُنتُمْ فَٰعِلِينَ࣌', 'قال هؤلاء بناتي إن كنتم فعلين࣌', NULL, 266, 'local:warsh-text.json'),
  ('warsh-15-72', 'warsh', 15, 72, 'لَعَمْرُكَ إِنَّهُمْ لَفِے سَكْرَتِهِمْ يَعْمَهُونَ࣌', 'لعمرك إنهم لفے سكرتهم يعمهون࣌', NULL, 266, 'local:warsh-text.json'),
  ('warsh-15-73', 'warsh', 15, 73, 'فَأَخَذَتْهُمُ ࡲ۬لصَّيْحَةُ مُشْرِقِينَ', 'فأخذتهم ࡲلصيحة مشرقين', NULL, 266, 'local:warsh-text.json'),
  ('warsh-15-74', 'warsh', 15, 74, 'فَجَعَلْنَا عَٰلِيَهَا سَافِلَهَا وَأَمْطَرْنَا عَلَيْهِمْ حِجَارَةࣰ مِّن سِجِّيلٍ࣌', 'فجعلنا عليها سافلها وأمطرنا عليهم حجارة من سجيل࣌', NULL, 266, 'local:warsh-text.json'),
  ('warsh-15-75', 'warsh', 15, 75, 'ࡴنَّ فِے ذَٰلِكَ لَأٓيَٰتࣲ لِّلْمُتَوَسِّمِينَ࣌', 'ࡴن فے ذلك لأيت للمتوسمين࣌', NULL, 266, 'local:warsh-text.json'),
  ('warsh-15-76', 'warsh', 15, 76, 'وَإِنَّهَا لَبِسَبِيلࣲ مُّقِيمٍ࣌', 'وإنها لبسبيل مقيم࣌', NULL, 266, 'local:warsh-text.json'),
  ('warsh-15-77', 'warsh', 15, 77, 'ࡴنَّ فِے ذَٰلِكَ لَأٓيَةࣰ لِّلْمُومِنِينَ࣌', 'ࡴن فے ذلك لأية للمومنين࣌', NULL, 266, 'local:warsh-text.json'),
  ('warsh-15-78', 'warsh', 15, 78, '۞ وَإِن كَانَ أَصْحَٰبُ ࡲ۬لَايْكَةِ لَظَٰلِمِينَ࣌', 'وإن كان أصحب ࡲلايكة لظلمين࣌', NULL, 266, 'local:warsh-text.json'),
  ('warsh-15-79', 'warsh', 15, 79, 'فَانتَقَمْنَا مِنْهُمْ࣌ وَإِنَّهُمَا لَبِإِمَامࣲ مُّبِينࣲ࣌', 'فانتقمنا منهم࣌ وإنهما لبإمام مبين࣌', NULL, 266, 'local:warsh-text.json'),
  ('warsh-15-80', 'warsh', 15, 80, 'وَلَقَدْ كَذَّبَ أَصْحَٰبُ ࡲ۬لْحِجْرِ ࡴ۬لْمُرْسَلِينَ࣌', 'ولقد كذب أصحب ࡲلحجر ࡴلمرسلين࣌', NULL, 266, 'local:warsh-text.json'),
  ('warsh-15-81', 'warsh', 15, 81, 'وَءَاتَيْنَٰهُمُۥٓ ءَايَٰتِنَا فَكَانُواْ عَنْهَا مُعْرِضِينَ࣌', 'وءاتينهم ءايتنا فكانوا عنها معرضين࣌', NULL, 266, 'local:warsh-text.json'),
  ('warsh-15-82', 'warsh', 15, 82, 'وَكَانُواْ يَنْحِتُونَ مِنَ ࡰ۬لْجِبَالِ بُيُوتاً اٰمِنِينَ࣌', 'وكانوا ينحتون من ࡰلجبال بيوتا امنين࣌', NULL, 266, 'local:warsh-text.json'),
  ('warsh-15-83', 'warsh', 15, 83, 'فَأَخَذَتْهُمُ ࡲ۬لصَّيْحَةُ مُصْبِحِينَ࣌', 'فأخذتهم ࡲلصيحة مصبحين࣌', NULL, 266, 'local:warsh-text.json'),
  ('warsh-15-84', 'warsh', 15, 84, 'فَمَآ أَغْنٜىٰ عَنْهُم مَّا كَانُواْ يَكْسِبُونَ࣌', 'فما أغنى عنهم ما كانوا يكسبون࣌', NULL, 266, 'local:warsh-text.json'),
  ('warsh-15-85', 'warsh', 15, 85, 'وَمَا خَلَقْنَا ࡰ۬لسَّمَٰوَٰتِ وَالَارْضَ وَمَا بَيْنَهُمَآ إِلَّا بِالْحَقِّ࣌ وَإِنَّ ࡰ۬لسَّاعَةَ لَأٓتِيَةࣱ࣌ فَاصْفَحِ ࡴ۬لصَّفْحَ ࡰ۬لْجَمِيلَ࣌', 'وما خلقنا ࡰلسموت والارض وما بينهما إلا بالحق࣌ وإن ࡰلساعة لأتية࣌ فاصفح ࡴلصفح ࡰلجميل࣌', NULL, 266, 'local:warsh-text.json'),
  ('warsh-15-86', 'warsh', 15, 86, 'إِنَّ رَبَّكَ هُوَ ࡰ۬لْخَلَّٰقُ ࡲ۬لْعَلِيمُ࣌', 'إن ربك هو ࡰلخلق ࡲلعليم࣌', NULL, 266, 'local:warsh-text.json'),
  ('warsh-15-87', 'warsh', 15, 87, 'وَلَقَدَ اٰتَيْنَٰكَ سَبْعاࣰ مِّنَ ࡰ۬لْمَثَانِے وَالْقُرْءَانَ ࡰ۬لْعَظِيمَ࣌', 'ولقد اتينك سبعا من ࡰلمثانے والقرءان ࡰلعظيم࣌', NULL, 266, 'local:warsh-text.json'),
  ('warsh-15-88', 'warsh', 15, 88, 'لَا تَمُدَّنَّ عَيْنَيْكَ إِلَىٰ مَا مَتَّعْنَا بِهِۦٓ أَزْوَٰجاࣰ مِّنْهُمْ࣌ وَلَا تَحْزَنْ عَلَيْهِمْ࣌ وَاخْفِضْ جَنَاحَكَ لِلْمُومِنِينَ࣌', 'لا تمدن عينيك إلى ما متعنا به أزوجا منهم࣌ ولا تحزن عليهم࣌ واخفض جناحك للمومنين࣌', NULL, 266, 'local:warsh-text.json'),
  ('warsh-15-89', 'warsh', 15, 89, 'وَقُلِ ࡴنِّيَ أَنَا ࡰ۬لنَّذِيرُ ࡲ۬لْمُبِينُ', 'وقل ࡴني أنا ࡰلنذير ࡲلمبين', NULL, 266, 'local:warsh-text.json'),
  ('warsh-15-90', 'warsh', 15, 90, 'كَمَآ أَنزَلْنَا عَلَى ࡰ۬لْمُقْتَسِمِينَ', 'كما أنزلنا على ࡰلمقتسمين', NULL, 266, 'local:warsh-text.json'),
  ('warsh-15-91', 'warsh', 15, 91, 'ࡰ۬لذِينَ جَعَلُواْ ࡲ۬لْقُرْءَانَ عِضِينَ࣌', 'ࡰلذين جعلوا ࡲلقرءان عضين࣌', NULL, 267, 'local:warsh-text.json'),
  ('warsh-15-92', 'warsh', 15, 92, 'فَوَرَبِّكَ لَنَسْـَٔلَنَّهُمُۥٓ أَجْمَعِينَ', 'فوربك لنسلنهم أجمعين', NULL, 267, 'local:warsh-text.json'),
  ('warsh-15-93', 'warsh', 15, 93, 'عَمَّا كَانُواْ يَعْمَلُونَ࣌', 'عما كانوا يعملون࣌', NULL, 267, 'local:warsh-text.json'),
  ('warsh-15-94', 'warsh', 15, 94, 'فَاصْدَعْ بِمَا تُومَرُ࣌ وَأَعْرِضْ عَنِ ࡴ۬لْمُشْرِكِينَ࣌', 'فاصدع بما تومر࣌ وأعرض عن ࡴلمشركين࣌', NULL, 267, 'local:warsh-text.json'),
  ('warsh-15-95', 'warsh', 15, 95, 'إِنَّا كَفَيْنَٰكَ ࡰ۬لْمُسْتَهْزِءِينَ', 'إنا كفينك ࡰلمستهزءين', NULL, 267, 'local:warsh-text.json'),
  ('warsh-15-96', 'warsh', 15, 96, 'ࡰ۬لذِينَ يَجْعَلُونَ مَعَ ࡰ۬للَّهِ إِلَٰهاً اٰخَرَ࣌ فَسَوْفَ يَعْلَمُونَ࣌', 'ࡰلذين يجعلون مع ࡰلله إلها اخر࣌ فسوف يعلمون࣌', NULL, 267, 'local:warsh-text.json'),
  ('warsh-15-97', 'warsh', 15, 97, 'وَلَقَدْ نَعْلَمُ أَنَّكَ يَضِيقُ صَدْرُكَ بِمَا يَقُولُونَ࣌', 'ولقد نعلم أنك يضيق صدرك بما يقولون࣌', NULL, 267, 'local:warsh-text.json'),
  ('warsh-15-98', 'warsh', 15, 98, 'فَسَبِّحْ بِحَمْدِ رَبِّكَ وَكُن مِّنَ ࡰ۬لسَّٰجِدِينَ࣌', 'فسبح بحمد ربك وكن من ࡰلسجدين࣌', NULL, 267, 'local:warsh-text.json'),
  ('warsh-15-99', 'warsh', 15, 99, 'وَاعْبُدْ رَبَّكَ حَتَّىٰ يَاتِيَكَ ࡰ۬لْيَقِينُ࣌', 'واعبد ربك حتى ياتيك ࡰليقين࣌', NULL, 267, 'local:warsh-text.json'),
  ('warsh-16-1', 'warsh', 16, 1, 'أَتٜىٰٓ أَمْرُ ࡲ۬للَّهِ فَلَا تَسْتَعْجِلُوهُ࣌ سُبْحَٰنَهُۥ وَتَعَٰلٜىٰ عَمَّا يُشْرِكُونَ࣌', 'أتى أمر ࡲلله فلا تستعجلوه࣌ سبحنه وتعلى عما يشركون࣌', NULL, 267, 'local:warsh-text.json'),
  ('warsh-16-2', 'warsh', 16, 2, 'يُنَزِّلُ ࡲ۬لْمَلَٰٓئِكَةَ بِالرُّوحِ مِنَ ࡰمْرِهِۦ عَلَىٰ مَنْ يَّشَآءُ مِنْ عِبَادِهِۦٓ أَنَ ࡰنذِرُوٓاْ أَنَّهُۥ لَآ إِلَٰهَ إِلَّآ أَنَا فَاتَّقُونِ࣌', 'ينزل ࡲلملئكة بالروح من ࡰمره على من يشاء من عباده أن ࡰنذروا أنه لا إله إلا أنا فاتقون࣌', NULL, 267, 'local:warsh-text.json'),
  ('warsh-16-3', 'warsh', 16, 3, 'خَلَقَ ࡰ۬لسَّمَٰوَٰتِ وَالَارْضَ بِالْحَقِّ࣌ تَعَٰلٜىٰ عَمَّا يُشْرِكُونَ࣌', 'خلق ࡰلسموت والارض بالحق࣌ تعلى عما يشركون࣌', NULL, 267, 'local:warsh-text.json'),
  ('warsh-16-4', 'warsh', 16, 4, 'خَلَقَ ࡰ۬لِانسَٰنَ مِن نُّطْفَةࣲ فَإِذَا هُوَ خَصِيمࣱ مُّبِينࣱ࣌', 'خلق ࡰلانسن من نطفة فإذا هو خصيم مبين࣌', NULL, 267, 'local:warsh-text.json'),
  ('warsh-16-5', 'warsh', 16, 5, 'وَالَانْعَٰمَ خَلَقَهَا࣌ لَكُمْ فِيهَا دِفْءࣱ وَمَنَٰفِعُ وَمِنْهَا تَاكُلُونَ࣌', 'والانعم خلقها࣌ لكم فيها دفء ومنفع ومنها تاكلون࣌', NULL, 267, 'local:warsh-text.json'),
  ('warsh-16-6', 'warsh', 16, 6, 'وَلَكُمْ فِيهَا جَمَالٌ حِينَ تُرِيحُونَ وَحِينَ تَسْرَحُونَ࣌', 'ولكم فيها جمال حين تريحون وحين تسرحون࣌', NULL, 267, 'local:warsh-text.json'),
  ('warsh-16-7', 'warsh', 16, 7, 'وَتَحْمِلُ أَثْقَالَكُمُۥٓ إِلَىٰ بَلَدࣲ لَّمْ تَكُونُواْ بَٰلِغِيهِ إِلَّا بِشِقِّ ࡴ۬لَانفُسِ࣌ إِنَّ رَبَّكُمْ لَرَءُوفࣱ رَّحِيمࣱ࣌', 'وتحمل أثقالكم إلى بلد لم تكونوا بلغيه إلا بشق ࡴلانفس࣌ إن ربكم لرءوف رحيم࣌', NULL, 268, 'local:warsh-text.json'),
  ('warsh-16-8', 'warsh', 16, 8, 'وَالْخَيْلَ وَالْبِغَالَ وَالْحَمِيرَ لِتَرْكَبُوهَا وَزِينَةࣰ࣌ وَيَخْلُقُ مَا لَا تَعْلَمُونَ࣌', 'والخيل والبغال والحمير لتركبوها وزينة࣌ ويخلق ما لا تعلمون࣌', NULL, 268, 'local:warsh-text.json'),
  ('warsh-16-9', 'warsh', 16, 9, 'وَعَلَى ࡰ۬للَّهِ قَصْدُ ࡲ۬لسَّبِيلِ وَمِنْهَا جَآئِرࣱ࣌ وَلَوْ شَآءَ لَهَدٜيٰكُمُۥٓ أَجْمَعِينَ࣌', 'وعلى ࡰلله قصد ࡲلسبيل ومنها جائر࣌ ولو شاء لهديكم أجمعين࣌', NULL, 268, 'local:warsh-text.json'),
  ('warsh-16-10', 'warsh', 16, 10, 'هُوَ ࡰ۬لذِےٓ أَنزَلَ مِنَ ࡰ۬لسَّمَآءِ مَآءࣰ لَّكُم مِّنْهُ شَرَابࣱ وَمِنْهُ شَجَرࣱ فِيهِ تُسِيمُونَ࣌', 'هو ࡰلذے أنزل من ࡰلسماء ماء لكم منه شراب ومنه شجر فيه تسيمون࣌', NULL, 268, 'local:warsh-text.json'),
  ('warsh-16-11', 'warsh', 16, 11, 'يُنۢبِتُ لَكُم بِهِ ࡴ۬لزَّرْعَ وَالزَّيْتُونَ وَالنَّخِيلَ وَالَاعْنَٰبَ وَمِن كُلِّ ࡴ۬لثَّمَرَٰتِ࣌ إِنَّ فِے ذَٰلِكَ لَأٓيَةࣰ لِّقَوْمࣲ يَتَفَكَّرُونَ࣌', 'ينبت لكم به ࡴلزرع والزيتون والنخيل والاعنب ومن كل ࡴلثمرت࣌ إن فے ذلك لأية لقوم يتفكرون࣌', NULL, 268, 'local:warsh-text.json'),
  ('warsh-16-12', 'warsh', 16, 12, 'وَسَخَّرَ لَكُمُ ࡲ۬ليْلَ وَالنَّهَارَ وَالشَّمْسَ وَالْقَمَرَ وَالنُّجُومَ مُسَخَّرَٰتِۢ بِأَمْرِهِۦٓ࣌ إِنَّ فِے ذَٰلِكَ لَأٓيَٰتࣲ لِّقَوْمࣲ يَعْقِلُونَ࣌', 'وسخر لكم ࡲليل والنهار والشمس والقمر والنجوم مسخرت بأمره࣌ إن فے ذلك لأيت لقوم يعقلون࣌', NULL, 268, 'local:warsh-text.json'),
  ('warsh-16-13', 'warsh', 16, 13, 'وَمَا ذَرَأَ لَكُمْ فِے ࡴ۬لَارْضِ مُخْتَلِفاً ࡰلْوَٰنُهُۥٓ࣌ إِنَّ فِے ذَٰلِكَ لَأٓيَةࣰ لِّقَوْمࣲ يَذَّكَّرُونَ࣌', 'وما ذرأ لكم فے ࡴلارض مختلفا ࡰلونه࣌ إن فے ذلك لأية لقوم يذكرون࣌', NULL, 268, 'local:warsh-text.json'),
  ('warsh-16-14', 'warsh', 16, 14, 'وَهُوَ ࡰ۬لذِے سَخَّرَ ࡰ۬لْبَحْرَ لِتَاكُلُواْ مِنْهُ لَحْماࣰ طَرِيّاࣰ وَتَسْتَخْرِجُواْ مِنْهُ حِلْيَةࣰ تَلْبَسُونَهَا࣌ وَتَرَى ࡰ۬لْفُلْكَ مَوَاخِرَ فِيهِ وَلِتَبْتَغُواْ مِن فَضْلِهِۦ وَلَعَلَّكُمْ تَشْكُرُونَ࣌', 'وهو ࡰلذے سخر ࡰلبحر لتاكلوا منه لحما طريا وتستخرجوا منه حلية تلبسونها࣌ وترى ࡰلفلك مواخر فيه ولتبتغوا من فضله ولعلكم تشكرون࣌', NULL, 268, 'local:warsh-text.json'),
  ('warsh-16-15', 'warsh', 16, 15, '۞ وَأَلْقٜىٰ فِے ࡴ۬لَارْضِ رَوَٰسِيَ أَن تَمِيدَ بِكُمْ وَأَنْهَٰراࣰ وَسُبُلاࣰ لَّعَلَّكُمْ تَهْتَدُونَ', 'وألقى فے ࡴلارض روسي أن تميد بكم وأنهرا وسبلا لعلكم تهتدون', NULL, 269, 'local:warsh-text.json'),
  ('warsh-16-16', 'warsh', 16, 16, 'وَعَلَٰمَٰتࣲ࣌ وَبِالنَّجْمِ هُمْ يَهْتَدُونَ࣌', 'وعلمت࣌ وبالنجم هم يهتدون࣌', NULL, 269, 'local:warsh-text.json'),
  ('warsh-16-17', 'warsh', 16, 17, 'أَفَمَنْ يَّخْلُقُ كَمَن لَّا يَخْلُقُ࣌ أَفَلَا تَذَّكَّرُونَ࣌', 'أفمن يخلق كمن لا يخلق࣌ أفلا تذكرون࣌', NULL, 269, 'local:warsh-text.json'),
  ('warsh-16-18', 'warsh', 16, 18, 'وَإِن تَعُدُّواْ نِعْمَةَ ࡰ۬للَّهِ لَا تُحْصُوهَآ࣌ إِنَّ ࡰ۬للَّهَ لَغَفُورࣱ رَّحِيمࣱ࣌', 'وإن تعدوا نعمة ࡰلله لا تحصوها࣌ إن ࡰلله لغفور رحيم࣌', NULL, 269, 'local:warsh-text.json'),
  ('warsh-16-19', 'warsh', 16, 19, 'وَاللَّهُ يَعْلَمُ مَا تُسِرُّونَ وَمَا تُعْلِنُونَ࣌', 'والله يعلم ما تسرون وما تعلنون࣌', NULL, 269, 'local:warsh-text.json'),
  ('warsh-16-20', 'warsh', 16, 20, 'وَالذِينَ تَدْعُونَ مِن دُونِ ࡴ۬للَّهِ لَا يَخْلُقُونَ شَيْـٔاࣰ وَهُمْ يُخْلَقُونَ࣌', 'والذين تدعون من دون ࡴلله لا يخلقون شيا وهم يخلقون࣌', NULL, 269, 'local:warsh-text.json'),
  ('warsh-16-21', 'warsh', 16, 21, 'أَمْوَٰتٌ غَيْرُ أَحْيَآءࣲ࣌ وَمَا يَشْعُرُونَ أَيَّانَ يُبْعَثُونَ࣌', 'أموت غير أحياء࣌ وما يشعرون أيان يبعثون࣌', NULL, 269, 'local:warsh-text.json'),
  ('warsh-16-22', 'warsh', 16, 22, 'إِلَٰهُكُمُۥٓ إِلَٰهࣱ وَٰحِدࣱ࣌ فَالذِينَ لَا يُومِنُونَ بِالَاخِرَةِ قُلُوبُهُم مُّنكِرَةࣱ وَهُم مُّسْتَكْبِرُونَ࣌', 'إلهكم إله وحد࣌ فالذين لا يومنون بالاخرة قلوبهم منكرة وهم مستكبرون࣌', NULL, 269, 'local:warsh-text.json'),
  ('warsh-16-23', 'warsh', 16, 23, 'لَا جَرَمَ أَنَّ ࡰ۬للَّهَ يَعْلَمُ مَا يُسِرُّونَ وَمَا يُعْلِنُونَ࣌ إِنَّهُۥ لَا يُحِبُّ ࡲ۬لْمُسْتَكْبِرِينَ࣌', 'لا جرم أن ࡰلله يعلم ما يسرون وما يعلنون࣌ إنه لا يحب ࡲلمستكبرين࣌', NULL, 269, 'local:warsh-text.json'),
  ('warsh-16-24', 'warsh', 16, 24, 'وَإِذَا قِيلَ لَهُم مَّاذَآ أَنزَلَ رَبُّكُمْ قَالُوٓاْ أَسَٰطِيرُ ࡲ۬لَاوَّلِينَ', 'وإذا قيل لهم ماذا أنزل ربكم قالوا أسطير ࡲلاولين', NULL, 269, 'local:warsh-text.json'),
  ('warsh-16-25', 'warsh', 16, 25, 'لِيَحْمِلُوٓاْ أَوْزَارَهُمْ كَامِلَةࣰ يَوْمَ ࡰ۬لْقِيَٰمَةِ وَمِنَ ࡰوْزٜارِ ࡴ۬لذِينَ يُضِلُّونَهُم بِغَيْرِ عِلْمٍ࣌ ࡰلَا سَآءَ مَا يَزِرُونَ࣌', 'ليحملوا أوزارهم كاملة يوم ࡰلقيمة ومن ࡰوزار ࡴلذين يضلونهم بغير علم࣌ ࡰلا ساء ما يزرون࣌', NULL, 269, 'local:warsh-text.json'),
  ('warsh-16-26', 'warsh', 16, 26, 'قَدْ مَكَرَ ࡰ۬لذِينَ مِن قَبْلِهِمْ فَأَتَى ࡰ۬للَّهُ بُنْيَٰنَهُم مِّنَ ࡰ۬لْقَوَاعِدِ فَخَرَّ عَلَيْهِمُ ࡲ۬لسَّقْفُ مِن فَوْقِهِمْ وَأَتٜيٰهُمُ ࡲ۬لْعَذَابُ مِنْ حَيْثُ لَا يَشْعُرُونَ࣌', 'قد مكر ࡰلذين من قبلهم فأتى ࡰلله بنينهم من ࡰلقواعد فخر عليهم ࡲلسقف من فوقهم وأتيهم ࡲلعذاب من حيث لا يشعرون࣌', NULL, 269, 'local:warsh-text.json'),
  ('warsh-16-27', 'warsh', 16, 27, 'ثُمَّ يَوْمَ ࡰ۬لْقِيَٰمَةِ يُخْزِيهِمْ وَيَقُولُ أَيْنَ شُرَكَآءِيَ ࡰ۬لذِينَ كُنتُمْ تُشَٰٓقُّونِ فِيهِمْ࣌ قَالَ ࡰ۬لذِينَ أُوتُواْ ࡲ۬لْعِلْمَ إِنَّ ࡰ۬لْخِزْيَ ࡰ۬لْيَوْمَ وَالسُّوٓءَ عَلَى ࡰ۬لْكٜـٰفِرِينَ', 'ثم يوم ࡰلقيمة يخزيهم ويقول أين شركاءي ࡰلذين كنتم تشقون فيهم࣌ قال ࡰلذين أوتوا ࡲلعلم إن ࡰلخزي ࡰليوم والسوء على ࡰلكفرين', NULL, 270, 'local:warsh-text.json'),
  ('warsh-16-28', 'warsh', 16, 28, 'ࡰ۬لذِينَ تَتَوَفّٜيٰهُمُ ࡲ۬لْمَلَٰٓئِكَةُ ظَالِمِےٓ أَنفُسِهِمْ࣌ فَأَلْقَوُاْ ࡲ۬لسَّلَمَ مَا كُنَّا نَعْمَلُ مِن سُوٓءِۢ بَلٜىٰٓ࣌ إِنَّ ࡰ۬للَّهَ عَلِيمُۢ بِمَا كُنتُمْ تَعْمَلُونَ࣌', 'ࡰلذين تتوفيهم ࡲلملئكة ظالمے أنفسهم࣌ فألقوا ࡲلسلم ما كنا نعمل من سوء بلى࣌ إن ࡰلله عليم بما كنتم تعملون࣌', NULL, 270, 'local:warsh-text.json'),
  ('warsh-16-29', 'warsh', 16, 29, 'فَادْخُلُوٓاْ أَبْوَٰبَ جَهَنَّمَ خَٰلِدِينَ فِيهَا࣌ فَلَبِيسَ مَثْوَى ࡰ۬لْمُتَكَبِّرِينَ࣌', 'فادخلوا أبوب جهنم خلدين فيها࣌ فلبيس مثوى ࡰلمتكبرين࣌', NULL, 270, 'local:warsh-text.json'),
  ('warsh-16-30', 'warsh', 16, 30, '۞ وَقِيلَ لِلذِينَ ࡰٜتَّقَوْاْ مَاذَآ أَنزَلَ رَبُّكُمْ قَالُواْ خَيْراࣰ࣌ لِّلذِينَ أَحْسَنُواْ فِے هَٰذِهِ ࡴ۬لدُّنْيٜا حَسَنَةࣱ࣌ وَلَدَارُ ࡲ۬لَاخِرَةِ خَيْرࣱ࣌ وَلَنِعْمَ دَارُ ࡲ۬لْمُتَّقِينَ࣌', 'وقيل للذين ࡰتقوا ماذا أنزل ربكم قالوا خيرا࣌ للذين أحسنوا فے هذه ࡴلدنيا حسنة࣌ ولدار ࡲلاخرة خير࣌ ولنعم دار ࡲلمتقين࣌', NULL, 270, 'local:warsh-text.json'),
  ('warsh-16-31', 'warsh', 16, 31, 'جَنَّٰتُ عَدْنࣲ يَدْخُلُونَهَا تَجْرِے مِن تَحْتِهَا ࡰ۬لَانْهَٰرُ لَهُمْ فِيهَا مَا يَشَآءُونَ࣌ كَذَٰلِكَ يَجْزِے ࡴ۬للَّهُ ࡲ۬لْمُتَّقِينَ', 'جنت عدن يدخلونها تجرے من تحتها ࡰلانهر لهم فيها ما يشاءون࣌ كذلك يجزے ࡴلله ࡲلمتقين', NULL, 270, 'local:warsh-text.json'),
  ('warsh-16-32', 'warsh', 16, 32, 'ࡰ۬لذِينَ تَتَوَفّٜيٰهُمُ ࡲ۬لْمَلَٰٓئِكَةُ طَيِّبِينَ࣌ يَقُولُونَ سَلَٰمٌ عَلَيْكُمُ ࡲ࢈دْخُلُواْ ࡲ۬لْجَنَّةَ بِمَا كُنتُمْ تَعْمَلُونَ࣌', 'ࡰلذين تتوفيهم ࡲلملئكة طيبين࣌ يقولون سلم عليكم ࡲ࢈دخلوا ࡲلجنة بما كنتم تعملون࣌', NULL, 270, 'local:warsh-text.json'),
  ('warsh-16-33', 'warsh', 16, 33, 'هَلْ يَنظُرُونَ إِلَّآ أَن تَاتِيَهُمُ ࡲ۬لْمَلَٰٓئِكَةُ أَوْ يَاتِيَ أَمْرُ رَبِّكَ࣌ كَذَٰلِكَ فَعَلَ ࡰ۬لذِينَ مِن قَبْلِهِمْ࣌ وَمَا ظَلَمَهُمُ ࡲ۬للَّهُ࣌ وَلَٰكِن كَانُوٓاْ أَنفُسَهُمْ يَظْلِمُونَ࣌', 'هل ينظرون إلا أن تاتيهم ࡲلملئكة أو ياتي أمر ربك࣌ كذلك فعل ࡰلذين من قبلهم࣌ وما ظلمهم ࡲلله࣌ ولكن كانوا أنفسهم يظلمون࣌', NULL, 270, 'local:warsh-text.json'),
  ('warsh-16-34', 'warsh', 16, 34, 'فَأَصَابَهُمْ سَيِّـَٔاتُ مَا عَمِلُواْ࣌ وَحَاقَ بِهِم مَّا كَانُواْ بِهِۦ يَسْتَهْزِءُونَ࣌', 'فأصابهم سيات ما عملوا࣌ وحاق بهم ما كانوا به يستهزءون࣌', NULL, 270, 'local:warsh-text.json'),
  ('warsh-16-35', 'warsh', 16, 35, 'وَقَالَ ࡰ۬لذِينَ أَشْرَكُواْ لَوْ شَآءَ ࡰ۬للَّهُ مَا عَبَدْنَا مِن دُونِهِۦ مِن شَےْءࣲ نَّحْنُ وَلَآ ءَابَآؤُنَا وَلَا حَرَّمْنَا مِن دُونِهِۦ مِن شَےْءࣲ࣌ كَذَٰلِكَ فَعَلَ ࡰ۬لذِينَ مِن قَبْلِهِمْ࣌ فَهَلْ عَلَى ࡰ۬لرُّسُلِ إِلَّا ࡰ۬لْبَلَٰغُ ࡲ۬لْمُبِينُ࣌', 'وقال ࡰلذين أشركوا لو شاء ࡰلله ما عبدنا من دونه من شےء نحن ولا ءاباؤنا ولا حرمنا من دونه من شےء࣌ كذلك فعل ࡰلذين من قبلهم࣌ فهل على ࡰلرسل إلا ࡰلبلغ ࡲلمبين࣌', NULL, 271, 'local:warsh-text.json'),
  ('warsh-16-36', 'warsh', 16, 36, 'وَلَقَدْ بَعَثْنَا فِے كُلِّ أُمَّةࣲ رَّسُولاً ࡰنُ ࡲ࢈عْبُدُواْ ࡲ۬للَّهَ وَاجْتَنِبُواْ ࡲ۬لطَّٰغُوتَ࣌ فَمِنْهُم مَّنْ هَدَى ࡰ۬للَّهُ࣌ وَمِنْهُم مَّنْ حَقَّتْ عَلَيْهِ ࡴ۬لضَّلَٰلَةُ࣌ فَسِيرُواْ فِے ࡴ۬لَارْضِ فَانظُرُواْ كَيْفَ كَانَ عَٰقِبَةُ ࡲ۬لْمُكَذِّبِينَ࣌', 'ولقد بعثنا فے كل أمة رسولا ࡰن ࡲ࢈عبدوا ࡲلله واجتنبوا ࡲلطغوت࣌ فمنهم من هدى ࡰلله࣌ ومنهم من حقت عليه ࡴلضللة࣌ فسيروا فے ࡴلارض فانظروا كيف كان عقبة ࡲلمكذبين࣌', NULL, 271, 'local:warsh-text.json'),
  ('warsh-16-37', 'warsh', 16, 37, 'إِن تَحْرِصْ عَلَىٰ هُدٜيٰهُمْ فَإِنَّ ࡰ۬للَّهَ لَا يُهْدٜىٰ مَنْ يُّضِلُّ࣌ وَمَا لَهُم مِّن نَّٰصِرِينَ࣌', 'إن تحرص على هديهم فإن ࡰلله لا يهدى من يضل࣌ وما لهم من نصرين࣌', NULL, 271, 'local:warsh-text.json'),
  ('warsh-16-38', 'warsh', 16, 38, '۞ وَأَقْسَمُواْ بِاللَّهِ جَهْدَ أَيْمَٰنِهِمْ لَا يَبْعَثُ ࡲ۬للَّهُ مَنْ يَّمُوتُ࣌ بَلٜىٰ وَعْداً عَلَيْهِ حَقّاࣰ وَلَٰكِنَّ أَكْثَرَ ࡰ۬لنَّاسِ لَا يَعْلَمُونَ', 'وأقسموا بالله جهد أيمنهم لا يبعث ࡲلله من يموت࣌ بلى وعدا عليه حقا ولكن أكثر ࡰلناس لا يعلمون', NULL, 271, 'local:warsh-text.json'),
  ('warsh-16-39', 'warsh', 16, 39, 'لِيُبَيِّنَ لَهُمُ ࡲ۬لذِے يَخْتَلِفُونَ فِيهِ وَلِيَعْلَمَ ࡰ۬لذِينَ كَفَرُوٓاْ أَنَّهُمْ كَانُواْ كَٰذِبِينَ࣌', 'ليبين لهم ࡲلذے يختلفون فيه وليعلم ࡰلذين كفروا أنهم كانوا كذبين࣌', NULL, 271, 'local:warsh-text.json'),
  ('warsh-16-40', 'warsh', 16, 40, 'إِنَّمَا قَوْلُنَا لِشَےْءٍ ࡴذَآ أَرَدْنَٰهُ أَن نَّقُولَ لَهُۥ كُن࣌ فَيَكُونُ࣌', 'إنما قولنا لشےء ࡴذا أردنه أن نقول له كن࣌ فيكون࣌', NULL, 271, 'local:warsh-text.json'),
  ('warsh-16-41', 'warsh', 16, 41, 'وَالذِينَ هَاجَرُواْ فِے ࡴ۬للَّهِ مِنۢ بَعْدِ مَا ظُلِمُواْ لَنُبَوِّئَنَّهُمْ فِے ࡴ۬لدُّنْيٜا حَسَنَةࣰ࣌ وَلَأَجْرُ ࡲ۬لَاخِرَةِ أَكْبَرُ لَوْ كَانُواْ يَعْلَمُونَ࣌', 'والذين هاجروا فے ࡴلله من بعد ما ظلموا لنبوئنهم فے ࡴلدنيا حسنة࣌ ولأجر ࡲلاخرة أكبر لو كانوا يعلمون࣌', NULL, 271, 'local:warsh-text.json'),
  ('warsh-16-42', 'warsh', 16, 42, 'ࡰ۬لذِينَ صَبَرُواْ وَعَلَىٰ رَبِّهِمْ يَتَوَكَّلُونَ࣌', 'ࡰلذين صبروا وعلى ربهم يتوكلون࣌', NULL, 271, 'local:warsh-text.json'),
  ('warsh-16-43', 'warsh', 16, 43, 'وَمَآ أَرْسَلْنَا مِن قَبْلِكَ إِلَّا رِجَالاࣰ يُوحٜىٰٓ إِلَيْهِمْ فَسْـَٔلُوٓاْ أَهْلَ ࡰ۬لذِّكْرِ إِن كُنتُمْ لَا تَعْلَمُونَ', 'وما أرسلنا من قبلك إلا رجالا يوحى إليهم فسلوا أهل ࡰلذكر إن كنتم لا تعلمون', NULL, 272, 'local:warsh-text.json'),
  ('warsh-16-44', 'warsh', 16, 44, 'بِالْبَيِّنَٰتِ وَالزُّبُرِ࣌ وَأَنزَلْنَآ إِلَيْكَ ࡰ۬لذِّكْرَ لِتُبَيِّنَ لِلنَّاسِ مَا نُزِّلَ إِلَيْهِمْ وَلَعَلَّهُمْ يَتَفَكَّرُونَ࣌', 'بالبينت والزبر࣌ وأنزلنا إليك ࡰلذكر لتبين للناس ما نزل إليهم ولعلهم يتفكرون࣌', NULL, 272, 'local:warsh-text.json'),
  ('warsh-16-45', 'warsh', 16, 45, 'أَفَأَمِنَ ࡰ۬لذِينَ مَكَرُواْ ࡲ۬لسَّيِّـَٔاتِ أَنْ يَّخْسِفَ ࡰ۬للَّهُ بِهِمُ ࡲ۬لَارْضَ أَوْ يَاتِيَهُمُ ࡲ۬لْعَذَابُ مِنْ حَيْثُ لَا يَشْعُرُونَ', 'أفأمن ࡰلذين مكروا ࡲلسيات أن يخسف ࡰلله بهم ࡲلارض أو ياتيهم ࡲلعذاب من حيث لا يشعرون', NULL, 272, 'local:warsh-text.json'),
  ('warsh-16-46', 'warsh', 16, 46, 'أَوْ يَاخُذَهُمْ فِے تَقَلُّبِهِمْ فَمَا هُم بِمُعْجِزِينَ', 'أو ياخذهم فے تقلبهم فما هم بمعجزين', NULL, 272, 'local:warsh-text.json'),
  ('warsh-16-47', 'warsh', 16, 47, 'أَوْ يَاخُذَهُمْ عَلَىٰ تَخَوُّفࣲ࣌ فَإِنَّ رَبَّكُمْ لَرَءُوفࣱ رَّحِيمٌ࣌', 'أو ياخذهم على تخوف࣌ فإن ربكم لرءوف رحيم࣌', NULL, 272, 'local:warsh-text.json'),
  ('warsh-16-48', 'warsh', 16, 48, 'ࡰوَلَمْ يَرَوِاْ ࡴلَىٰ مَا خَلَقَ ࡰ۬للَّهُ مِن شَےْءࣲ يَتَفَيَّؤُاْ ظِلَٰلُهُۥ عَنِ ࡴ۬لْيَمِينِ وَالشَّمَآئِلِ سُجَّداࣰ لِّلهِ وَهُمْ دَٰخِرُونَ࣌', 'ࡰولم يروا ࡴلى ما خلق ࡰلله من شےء يتفيؤا ظلله عن ࡴليمين والشمائل سجدا لله وهم دخرون࣌', NULL, 272, 'local:warsh-text.json'),
  ('warsh-16-49', 'warsh', 16, 49, 'وَلِلهِ يَسْجُدُ مَا فِے ࡴ۬لسَّمَٰوَٰتِ وَمَا فِے ࡴ۬لَارْضِ مِن دَآبَّةࣲ وَالْمَلَٰٓئِكَةُ وَهُمْ لَا يَسْتَكْبِرُونَ', 'ولله يسجد ما فے ࡴلسموت وما فے ࡴلارض من دابة والملئكة وهم لا يستكبرون', NULL, 272, 'local:warsh-text.json'),
  ('warsh-16-50', 'warsh', 16, 50, 'يَخَافُونَ رَبَّهُم مِّن فَوْقِهِمْ وَيَفْعَلُونَ مَا يُومَرُونَ࣌۩', 'يخافون ربهم من فوقهم ويفعلون ما يومرون࣌', NULL, 272, 'local:warsh-text.json'),
  ('warsh-16-51', 'warsh', 16, 51, '۞ وَقَالَ ࡰ۬للَّهُ لَا تَتَّخِذُوٓاْ إِلَٰهَيْنِ ࡴٜثْنَيْنِ࣌ إِنَّمَا هُوَ إِلَٰهࣱ وَٰحِدࣱ࣌ فَإِيَّٰيَ فَارْهَبُونِ࣌', 'وقال ࡰلله لا تتخذوا إلهين ࡴثنين࣌ إنما هو إله وحد࣌ فإيي فارهبون࣌', NULL, 272, 'local:warsh-text.json'),
  ('warsh-16-52', 'warsh', 16, 52, 'وَلَهُۥ مَا فِے ࡴ۬لسَّمَٰوَٰتِ وَالَارْضِ࣌ وَلَهُ ࡲ۬لدِّينُ وَاصِباً࣌ ࡰفَغَيْرَ ࡰ۬للَّهِ تَتَّقُونَ࣌', 'وله ما فے ࡴلسموت والارض࣌ وله ࡲلدين واصبا࣌ ࡰفغير ࡰلله تتقون࣌', NULL, 272, 'local:warsh-text.json'),
  ('warsh-16-53', 'warsh', 16, 53, 'وَمَا بِكُم مِّن نِّعْمَةࣲ فَمِنَ ࡰ۬للَّهِ࣌ ثُمَّ إِذَا مَسَّكُمُ ࡲ۬لضُّرُّ فَإِلَيْهِ تَجْـَٔرُونَ࣌', 'وما بكم من نعمة فمن ࡰلله࣌ ثم إذا مسكم ࡲلضر فإليه تجرون࣌', NULL, 272, 'local:warsh-text.json'),
  ('warsh-16-54', 'warsh', 16, 54, 'ثُمَّ إِذَا كَشَفَ ࡰ۬لضُّرَّ عَنكُمُۥٓ إِذَا فَرِيقࣱ مِّنكُم بِرَبِّهِمْ يُشْرِكُونَ', 'ثم إذا كشف ࡰلضر عنكم إذا فريق منكم بربهم يشركون', NULL, 272, 'local:warsh-text.json'),
  ('warsh-16-55', 'warsh', 16, 55, 'لِيَكْفُرُواْ بِمَآ ءَاتَيْنَٰهُمْ࣌ فَتَمَتَّعُواْ࣌ فَسَوْفَ تَعْلَمُونَ࣌', 'ليكفروا بما ءاتينهم࣌ فتمتعوا࣌ فسوف تعلمون࣌', NULL, 273, 'local:warsh-text.json'),
  ('warsh-16-56', 'warsh', 16, 56, 'وَيَجْعَلُونَ لِمَا لَا يَعْلَمُونَ نَصِيباࣰ مِّمَّا رَزَقْنَٰهُمْ࣌ تَاللَّهِ لَتُسْـَٔلُنَّ عَمَّا كُنتُمْ تَفْتَرُونَ࣌', 'ويجعلون لما لا يعلمون نصيبا مما رزقنهم࣌ تالله لتسلن عما كنتم تفترون࣌', NULL, 273, 'local:warsh-text.json'),
  ('warsh-16-57', 'warsh', 16, 57, 'وَيَجْعَلُونَ لِلهِ ࡴ۬لْبَنَٰتِ سُبْحَٰنَهُۥ࣌ وَلَهُم مَّا يَشْتَهُونَ࣌', 'ويجعلون لله ࡴلبنت سبحنه࣌ ولهم ما يشتهون࣌', NULL, 273, 'local:warsh-text.json'),
  ('warsh-16-58', 'warsh', 16, 58, 'وَإِذَا بُشِّرَ أَحَدُهُم بِالُانثٜىٰ ظَلَّ وَجْهُهُۥ مُسْوَدّاࣰ وَهُوَ كَظِيمࣱ', 'وإذا بشر أحدهم بالانثى ظل وجهه مسودا وهو كظيم', NULL, 273, 'local:warsh-text.json'),
  ('warsh-16-59', 'warsh', 16, 59, 'يَتَوَٰرٜىٰ مِنَ ࡰ۬لْقَوْمِ مِن سُوٓءِ مَا بُشِّرَ بِهِۦٓ࣌ أَيُمْسِكُهُۥ عَلَىٰ هُونٍ ࡰمْ يَدُسُّهُۥ فِے ࡴ۬لتُّرَابِ࣌ أَلَا سَآءَ مَا يَحْكُمُونَ࣌', 'يتورى من ࡰلقوم من سوء ما بشر به࣌ أيمسكه على هون ࡰم يدسه فے ࡴلتراب࣌ ألا ساء ما يحكمون࣌', NULL, 273, 'local:warsh-text.json'),
  ('warsh-16-60', 'warsh', 16, 60, 'لِلذِينَ لَا يُومِنُونَ بِالَاخِرَةِ مَثَلُ ࡲ۬لسَّوْءِ࣌ وَلِلهِ ࡴ۬لْمَثَلُ ࡲ۬لَاعْلٜىٰ࣌ وَهُوَ ࡰ۬لْعَزِيزُ ࡲ۬لْحَكِيمُ࣌', 'للذين لا يومنون بالاخرة مثل ࡲلسوء࣌ ولله ࡴلمثل ࡲلاعلى࣌ وهو ࡰلعزيز ࡲلحكيم࣌', NULL, 273, 'local:warsh-text.json'),
  ('warsh-16-61', 'warsh', 16, 61, 'وَلَوْ يُوَ۬اخِذُ ࡲ۬للَّهُ ࡲ۬لنَّاسَ بِظُلْمِهِم مَّا تَرَكَ عَلَيْهَا مِن دَآبَّةࣲ࣌ وَلَٰكِنْ يُّوَ۬خِّرُهُمُۥٓ إِلَىٰٓ أَجَلࣲ مُّسَمّىࣰ࣌ فَإِذَا جَآءَ اجَلُهُمْ لَا يَسْتَٰخِرُونَ سَاعَةࣰ࣌ وَلَا يَسْتَقْدِمُونَ࣌', 'ولو يواخذ ࡲلله ࡲلناس بظلمهم ما ترك عليها من دابة࣌ ولكن يوخرهم إلى أجل مسمى࣌ فإذا جاء اجلهم لا يستخرون ساعة࣌ ولا يستقدمون࣌', NULL, 273, 'local:warsh-text.json'),
  ('warsh-16-62', 'warsh', 16, 62, 'وَيَجْعَلُونَ لِلهِ مَا يَكْرَهُونَ࣌ وَتَصِفُ أَلْسِنَتُهُمُ ࡲ۬لْكَذِبَ أَنَّ لَهُمُ ࡲ۬لْحُسْنٜىٰ࣌ لَا جَرَمَ أَنَّ لَهُمُ ࡲ۬لنَّارَ وَأَنَّهُم مُّفْرِطُونَ࣌', 'ويجعلون لله ما يكرهون࣌ وتصف ألسنتهم ࡲلكذب أن لهم ࡲلحسنى࣌ لا جرم أن لهم ࡲلنار وأنهم مفرطون࣌', NULL, 273, 'local:warsh-text.json'),
  ('warsh-16-63', 'warsh', 16, 63, '۞ تَاللَّهِ لَقَدَ ࡰرْسَلْنَآ إِلَىٰٓ أُمَمࣲ مِّن قَبْلِكَ فَزَيَّنَ لَهُمُ ࡲ۬لشَّيْطَٰنُ أَعْمَٰلَهُمْ فَهُوَ وَلِيُّهُمُ ࡲ۬لْيَوْمَ࣌ وَلَهُمْ عَذَابٌ ࡰلِيمࣱ࣌', 'تالله لقد ࡰرسلنا إلى أمم من قبلك فزين لهم ࡲلشيطن أعملهم فهو وليهم ࡲليوم࣌ ولهم عذاب ࡰليم࣌', NULL, 273, 'local:warsh-text.json'),
  ('warsh-16-64', 'warsh', 16, 64, 'وَمَآ أَنزَلْنَا عَلَيْكَ ࡰ۬لْكِتَٰبَ إِلَّا لِتُبَيِّنَ لَهُمُ ࡲ۬لذِے ࡴٜخْتَلَفُواْ فِيهِ وَهُدىࣰ وَرَحْمَةࣰ لِّقَوْمࣲ يُومِنُونَ࣌', 'وما أنزلنا عليك ࡰلكتب إلا لتبين لهم ࡲلذے ࡴختلفوا فيه وهدى ورحمة لقوم يومنون࣌', NULL, 273, 'local:warsh-text.json'),
  ('warsh-16-65', 'warsh', 16, 65, 'وَاللَّهُ أَنزَلَ مِنَ ࡰ۬لسَّمَآءِ مَآءࣰ فَأَحْيٜا بِهِ ࡴ۬لَارْضَ بَعْدَ مَوْتِهَآ࣌ إِنَّ فِے ذَٰلِكَ لَأٓيَةࣰ لِّقَوْمࣲ يَسْمَعُونَ࣌', 'والله أنزل من ࡰلسماء ماء فأحيا به ࡴلارض بعد موتها࣌ إن فے ذلك لأية لقوم يسمعون࣌', NULL, 274, 'local:warsh-text.json'),
  ('warsh-16-66', 'warsh', 16, 66, 'وَإِنَّ لَكُمْ فِے ࡴ۬لَانْعَٰمِ لَعِبْرَةࣰ࣌ نَّسْقِيكُم مِّمَّا فِے بُطُونِهِۦ مِنۢ بَيْنِ فَرْثࣲ وَدَمࣲ لَّبَناً خَالِصاࣰ سَآئِغاࣰ لِّلشَّٰرِبِينَ', 'وإن لكم فے ࡴلانعم لعبرة࣌ نسقيكم مما فے بطونه من بين فرث ودم لبنا خالصا سائغا للشربين', NULL, 274, 'local:warsh-text.json'),
  ('warsh-16-67', 'warsh', 16, 67, 'وَمِن ثَمَرَٰتِ ࡴ۬لنَّخِيلِ وَالَاعْنَٰبِ تَتَّخِذُونَ مِنْهُ سَكَراࣰ وَرِزْقاً حَسَناً࣌ ࡴنَّ فِے ذَٰلِكَ لَأٓيَةࣰ لِّقَوْمࣲ يَعْقِلُونَ࣌', 'ومن ثمرت ࡴلنخيل والاعنب تتخذون منه سكرا ورزقا حسنا࣌ ࡴن فے ذلك لأية لقوم يعقلون࣌', NULL, 274, 'local:warsh-text.json'),
  ('warsh-16-68', 'warsh', 16, 68, 'وَأَوْحٜىٰ رَبُّكَ إِلَى ࡰ۬لنَّحْلِ أَنِ ࡴٜتَّخِذِے مِنَ ࡰ۬لْجِبَالِ بُيُوتاࣰ وَمِنَ ࡰ۬لشَّجَرِ وَمِمَّا يَعْرِشُونَ', 'وأوحى ربك إلى ࡰلنحل أن ࡴتخذے من ࡰلجبال بيوتا ومن ࡰلشجر ومما يعرشون', NULL, 274, 'local:warsh-text.json'),
  ('warsh-16-69', 'warsh', 16, 69, 'ثُمَّ كُلِے مِن كُلِّ ࡴ۬لثَّمَرَٰتِ فَاسْلُكِے سُبُلَ رَبِّكِ ذُلُلاࣰ࣌ يَخْرُجُ مِنۢ بُطُونِهَا شَرَابࣱ مُّخْتَلِفٌ ࡰلْوَٰنُهُۥ فِيهِ شِفَآءࣱ لِّلنَّاسِ࣌ إِنَّ فِے ذَٰلِكَ لَأٓيَةࣰ لِّقَوْمࣲ يَتَفَكَّرُونَ࣌', 'ثم كلے من كل ࡴلثمرت فاسلكے سبل ربك ذللا࣌ يخرج من بطونها شراب مختلف ࡰلونه فيه شفاء للناس࣌ إن فے ذلك لأية لقوم يتفكرون࣌', NULL, 274, 'local:warsh-text.json'),
  ('warsh-16-70', 'warsh', 16, 70, 'وَاللَّهُ خَلَقَكُمْ ثُمَّ يَتَوَفّٜيٰكُمْ࣌ وَمِنكُم مَّنْ يُّرَدُّ إِلَىٰٓ أَرْذَلِ ࡴ۬لْعُمُرِ لِكَےْ لَا يَعْلَمَ بَعْدَ عِلْمࣲ شَيْـٔاً࣌ ࡴنَّ ࡰ۬للَّهَ عَلِيمࣱ قَدِيرࣱ࣌', 'والله خلقكم ثم يتوفيكم࣌ ومنكم من يرد إلى أرذل ࡴلعمر لكے لا يعلم بعد علم شيا࣌ ࡴن ࡰلله عليم قدير࣌', NULL, 274, 'local:warsh-text.json'),
  ('warsh-16-71', 'warsh', 16, 71, '۞ وَاللَّهُ فَضَّلَ بَعْضَكُمْ عَلَىٰ بَعْضࣲ فِے ࡴ۬لرِّزْقِ࣌ فَمَا ࡰ۬لذِينَ فُضِّلُواْ بِرَآدِّے رِزْقِهِمْ عَلَىٰ مَا مَلَكَتَ ࡰيْمَٰنُهُمْ فَهُمْ فِيهِ سَوَآءٌ࣌ ࡰفَبِنِعْمَةِ ࡴ۬للَّهِ يَجْحَدُونَ࣌', 'والله فضل بعضكم على بعض فے ࡴلرزق࣌ فما ࡰلذين فضلوا برادے رزقهم على ما ملكت ࡰيمنهم فهم فيه سواء࣌ ࡰفبنعمة ࡴلله يجحدون࣌', NULL, 274, 'local:warsh-text.json'),
  ('warsh-16-72', 'warsh', 16, 72, 'وَاللَّهُ جَعَلَ لَكُم مِّنَ ࡰنفُسِكُمُۥٓ أَزْوَٰجاࣰ وَجَعَلَ لَكُم مِّنَ ࡰزْوَٰجِكُم بَنِينَ وَحَفَدَةࣰ࣌ وَرَزَقَكُم مِّنَ ࡰ۬لطَّيِّبَٰتِ࣌ أَفَبِالْبَٰطِلِ يُومِنُونَ وَبِنِعْمَتِ ࡴ۬للَّهِ هُمْ يَكْفُرُونَ࣌', 'والله جعل لكم من ࡰنفسكم أزوجا وجعل لكم من ࡰزوجكم بنين وحفدة࣌ ورزقكم من ࡰلطيبت࣌ أفبالبطل يومنون وبنعمت ࡴلله هم يكفرون࣌', NULL, 274, 'local:warsh-text.json'),
  ('warsh-16-73', 'warsh', 16, 73, 'وَيَعْبُدُونَ مِن دُونِ ࡴ۬للَّهِ مَا لَا يَمْلِكُ لَهُمْ رِزْقاࣰ مِّنَ ࡰ۬لسَّمَٰوَٰتِ وَالَارْضِ شَيْـٔاࣰ وَلَا يَسْتَطِيعُونَ࣌', 'ويعبدون من دون ࡴلله ما لا يملك لهم رزقا من ࡰلسموت والارض شيا ولا يستطيعون࣌', NULL, 275, 'local:warsh-text.json'),
  ('warsh-16-74', 'warsh', 16, 74, 'فَلَا تَضْرِبُواْ لِلهِ ࡴ۬لَامْثَالَ࣌ إِنَّ ࡰ۬للَّهَ يَعْلَمُ࣌ وَأَنتُمْ لَا تَعْلَمُونَ࣌', 'فلا تضربوا لله ࡴلامثال࣌ إن ࡰلله يعلم࣌ وأنتم لا تعلمون࣌', NULL, 275, 'local:warsh-text.json'),
  ('warsh-16-75', 'warsh', 16, 75, 'ضَرَبَ ࡰ۬للَّهُ مَثَلاً عَبْداࣰ مَّمْلُوكاࣰ لَّا يَقْدِرُ عَلَىٰ شَےْءࣲ وَمَن رَّزَقْنَٰهُ مِنَّا رِزْقاً حَسَناࣰ فَهُوَ يُنفِقُ مِنْهُ سِرّاࣰ وَجَهْراً هَلْ يَسْتَوُۥنَ࣌ ࡰ۬لْحَمْدُ لِلهِ࣌ بَلَ ࡰكْثَرُهُمْ لَا يَعْلَمُونَ࣌', 'ضرب ࡰلله مثلا عبدا مملوكا لا يقدر على شےء ومن رزقنه منا رزقا حسنا فهو ينفق منه سرا وجهرا هل يستون࣌ ࡰلحمد لله࣌ بل ࡰكثرهم لا يعلمون࣌', NULL, 275, 'local:warsh-text.json'),
  ('warsh-16-76', 'warsh', 16, 76, 'وَضَرَبَ ࡰ۬للَّهُ مَثَلاࣰ رَّجُلَيْنِ أَحَدُهُمَآ أَبْكَمُ لَا يَقْدِرُ عَلَىٰ شَےْءࣲ وَهُوَ كَلٌّ عَلَىٰ مَوْلٜيٰهُ أَيْنَمَا يُوَجِّههُّ لَا يَاتِ بِخَيْرٍ هَلْ يَسْتَوِے هُوَ وَمَنْ يَّامُرُ بِالْعَدْلِ وَهُوَ عَلَىٰ صِرَٰطࣲ مُّسْتَقِيمࣲ࣌', 'وضرب ࡰلله مثلا رجلين أحدهما أبكم لا يقدر على شےء وهو كل على موليه أينما يوجهه لا يات بخير هل يستوے هو ومن يامر بالعدل وهو على صرط مستقيم࣌', NULL, 275, 'local:warsh-text.json'),
  ('warsh-16-77', 'warsh', 16, 77, 'وَلِلهِ غَيْبُ ࡲ۬لسَّمَٰوَٰتِ وَالَارْضِ࣌ وَمَآ أَمْرُ ࡲ۬لسَّاعَةِ إِلَّا كَلَمْحِ ࡴ۬لْبَصَرِ أَوْ هُوَ أَقْرَبُ࣌ إِنَّ ࡰ۬للَّهَ عَلَىٰ كُلِّ شَےْءࣲ قَدِيرࣱ࣌', 'ولله غيب ࡲلسموت والارض࣌ وما أمر ࡲلساعة إلا كلمح ࡴلبصر أو هو أقرب࣌ إن ࡰلله على كل شےء قدير࣌', NULL, 275, 'local:warsh-text.json'),
  ('warsh-16-78', 'warsh', 16, 78, 'وَاللَّهُ أَخْرَجَكُم مِّنۢ بُطُونِ أُمَّهَٰتِكُمْ لَا تَعْلَمُونَ شَيْـٔاࣰ࣌ وَجَعَلَ لَكُمُ ࡲ۬لسَّمْعَ وَالَابْصَٰرَ وَالَافْـِٕدَةَ لَعَلَّكُمْ تَشْكُرُونَ࣌', 'والله أخرجكم من بطون أمهتكم لا تعلمون شيا࣌ وجعل لكم ࡲلسمع والابصر والافدة لعلكم تشكرون࣌', NULL, 275, 'local:warsh-text.json'),
  ('warsh-16-79', 'warsh', 16, 79, '۞ أَلَمْ يَرَوِاْ ࡴلَى ࡰ۬لطَّيْرِ مُسَخَّرَٰتࣲ فِے جَوِّ ࡴ۬لسَّمَآءِ مَا يُمْسِكُهُنَّ إِلَّا ࡰ۬للَّهُ࣌ إِنَّ فِے ذَٰلِكَ لَأٓيَٰتࣲ لِّقَوْمࣲ يُومِنُونَ࣌', 'ألم يروا ࡴلى ࡰلطير مسخرت فے جو ࡴلسماء ما يمسكهن إلا ࡰلله࣌ إن فے ذلك لأيت لقوم يومنون࣌', NULL, 275, 'local:warsh-text.json'),
  ('warsh-16-80', 'warsh', 16, 80, 'وَاللَّهُ جَعَلَ لَكُم مِّنۢ بُيُوتِكُمْ سَكَناࣰ وَجَعَلَ لَكُم مِّن جُلُودِ ࡴ۬لَانْعَٰمِ بُيُوتاࣰ تَسْتَخِفُّونَهَا يَوْمَ ظَعَنِكُمْ وَيَوْمَ إِقَامَتِكُمْ࣌ وَمِنَ ࡰصْوَافِهَا وَأَوْبٜارِهَا وَأَشْعٜارِهَآ أَثَٰثاࣰ وَمَتَٰعاً ࡴلَىٰ حِينࣲ࣌', 'والله جعل لكم من بيوتكم سكنا وجعل لكم من جلود ࡴلانعم بيوتا تستخفونها يوم ظعنكم ويوم إقامتكم࣌ ومن ࡰصوافها وأوبارها وأشعارها أثثا ومتعا ࡴلى حين࣌', NULL, 276, 'local:warsh-text.json'),
  ('warsh-16-81', 'warsh', 16, 81, 'وَاللَّهُ جَعَلَ لَكُم مِّمَّا خَلَقَ ظِلَٰلاࣰ وَجَعَلَ لَكُم مِّنَ ࡰ۬لْجِبَالِ أَكْنَٰناࣰ وَجَعَلَ لَكُمْ سَرَٰبِيلَ تَقِيكُمُ ࡲ۬لْحَرَّ وَسَرَٰبِيلَ تَقِيكُم بَأْسَكُمْ࣌ كَذَٰلِكَ يُتِمُّ نِعْمَتَهُۥ عَلَيْكُمْ لَعَلَّكُمْ تُسْلِمُونَ࣌', 'والله جعل لكم مما خلق ظللا وجعل لكم من ࡰلجبال أكننا وجعل لكم سربيل تقيكم ࡲلحر وسربيل تقيكم بأسكم࣌ كذلك يتم نعمته عليكم لعلكم تسلمون࣌', NULL, 276, 'local:warsh-text.json'),
  ('warsh-16-82', 'warsh', 16, 82, 'فَإِن تَوَلَّوْاْ فَإِنَّمَا عَلَيْكَ ࡰ۬لْبَلَٰغُ ࡲ۬لْمُبِينُ࣌', 'فإن تولوا فإنما عليك ࡰلبلغ ࡲلمبين࣌', NULL, 276, 'local:warsh-text.json'),
  ('warsh-16-83', 'warsh', 16, 83, 'يَعْرِفُونَ نِعْمَتَ ࡰ۬للَّهِ ثُمَّ يُنكِرُونَهَا࣌ وَأَكْثَرُهُمُ ࡲ۬لْكَٰفِرُونَ࣌', 'يعرفون نعمت ࡰلله ثم ينكرونها࣌ وأكثرهم ࡲلكفرون࣌', NULL, 276, 'local:warsh-text.json'),
  ('warsh-16-84', 'warsh', 16, 84, 'وَيَوْمَ نَبْعَثُ مِن كُلِّ أُمَّةࣲ شَهِيداࣰ ثُمَّ لَا يُوذَنُ لِلذِينَ كَفَرُواْ وَلَا هُمْ يُسْتَعْتَبُونَ࣌', 'ويوم نبعث من كل أمة شهيدا ثم لا يوذن للذين كفروا ولا هم يستعتبون࣌', NULL, 276, 'local:warsh-text.json'),
  ('warsh-16-85', 'warsh', 16, 85, 'وَإِذَا رَءَا ࡰ۬لذِينَ ظَلَمُواْ ࡲ۬لْعَذَابَ فَلَا يُخَفَّفُ عَنْهُمْ وَلَا هُمْ يُنظَرُونَ࣌', 'وإذا رءا ࡰلذين ظلموا ࡲلعذاب فلا يخفف عنهم ولا هم ينظرون࣌', NULL, 276, 'local:warsh-text.json'),
  ('warsh-16-86', 'warsh', 16, 86, 'وَإِذَا رَءَا ࡰ۬لذِينَ أَشْرَكُواْ شُرَكَآءَهُمْ قَالُواْ رَبَّنَا هَٰٓؤُلَآءِ شُرَكَآؤُنَا ࡰ۬لذِينَ كُنَّا نَدْعُواْ مِن دُونِكَ࣌ فَأَلْقَوِاْ ࡴلَيْهِمُ ࡲ۬لْقَوْلَ إِنَّكُمْ لَكَٰذِبُونَ࣌', 'وإذا رءا ࡰلذين أشركوا شركاءهم قالوا ربنا هؤلاء شركاؤنا ࡰلذين كنا ندعوا من دونك࣌ فألقوا ࡴليهم ࡲلقول إنكم لكذبون࣌', NULL, 276, 'local:warsh-text.json'),
  ('warsh-16-87', 'warsh', 16, 87, 'وَأَلْقَوِاْ ࡴلَى ࡰ۬للَّهِ يَوْمَئِذٍ ࡴ۬لسَّلَمَ࣌ وَضَلَّ عَنْهُم مَّا كَانُواْ يَفْتَرُونَ࣌', 'وألقوا ࡴلى ࡰلله يومئذ ࡴلسلم࣌ وضل عنهم ما كانوا يفترون࣌', NULL, 276, 'local:warsh-text.json'),
  ('warsh-16-88', 'warsh', 16, 88, 'ࡰ۬لذِينَ كَفَرُواْ وَصَدُّواْ عَن سَبِيلِ ࡴ۬للَّهِ زِدْنَٰهُمْ عَذَاباࣰ فَوْقَ ࡰ۬لْعَذَابِ بِمَا كَانُواْ يُفْسِدُونَ࣌', 'ࡰلذين كفروا وصدوا عن سبيل ࡴلله زدنهم عذابا فوق ࡰلعذاب بما كانوا يفسدون࣌', NULL, 277, 'local:warsh-text.json'),
  ('warsh-16-89', 'warsh', 16, 89, 'وَيَوْمَ نَبْعَثُ فِے كُلِّ أُمَّةࣲ شَهِيداً عَلَيْهِم مِّنَ ࡰنفُسِهِمْ وَجِئْنَا بِكَ شَهِيداً عَلَىٰ هَٰٓؤُلَآءِ࣌ وَنَزَّلْنَا عَلَيْكَ ࡰ۬لْكِتَٰبَ تِبْيَٰناࣰ لِّكُلِّ شَےْءࣲ وَهُدىࣰ وَرَحْمَةࣰ وَبُشْرٜىٰ لِلْمُسْلِمِينَ࣌', 'ويوم نبعث فے كل أمة شهيدا عليهم من ࡰنفسهم وجئنا بك شهيدا على هؤلاء࣌ ونزلنا عليك ࡰلكتب تبينا لكل شےء وهدى ورحمة وبشرى للمسلمين࣌', NULL, 277, 'local:warsh-text.json'),
  ('warsh-16-90', 'warsh', 16, 90, '۞ إِنَّ ࡰ۬للَّهَ يَامُرُ بِالْعَدْلِ وَالِاحْسَٰنِ وَإِيتَآءِےْ ذِے ࡴ۬لْقُرْبٜىٰ࣌ وَيَنْهٜىٰ عَنِ ࡴ۬لْفَحْشَآءِ وَالْمُنكَرِ وَالْبَغْيِ࣌ يَعِظُكُمْ لَعَلَّكُمْ تَذَّكَّرُونَ࣌', 'إن ࡰلله يامر بالعدل والاحسن وإيتاءے ذے ࡴلقربى࣌ وينهى عن ࡴلفحشاء والمنكر والبغي࣌ يعظكم لعلكم تذكرون࣌', NULL, 277, 'local:warsh-text.json'),
  ('warsh-16-91', 'warsh', 16, 91, 'وَأَوْفُواْ بِعَهْدِ ࡴ۬للَّهِ إِذَا عَٰهَدتُّمْ࣌ وَلَا تَنقُضُواْ ࡲ۬لَايْمَٰنَ بَعْدَ تَوْكِيدِهَا وَقَدْ جَعَلْتُمُ ࡲ۬للَّهَ عَلَيْكُمْ كَفِيلاً࣌ ࡴنَّ ࡰ۬للَّهَ يَعْلَمُ مَا تَفْعَلُونَ࣌', 'وأوفوا بعهد ࡴلله إذا عهدتم࣌ ولا تنقضوا ࡲلايمن بعد توكيدها وقد جعلتم ࡲلله عليكم كفيلا࣌ ࡴن ࡰلله يعلم ما تفعلون࣌', NULL, 277, 'local:warsh-text.json'),
  ('warsh-16-92', 'warsh', 16, 92, 'وَلَا تَكُونُواْ كَالتِے نَقَضَتْ غَزْلَهَا مِنۢ بَعْدِ قُوَّةٍ ࡰنكَٰثاࣰ تَتَّخِذُونَ أَيْمَٰنَكُمْ دَخَلاَۢ بَيْنَكُمُۥٓ أَن تَكُونَ أُمَّةٌ هِيَ أَرْبٜىٰ مِنُ ࡳمَّةٍ࣌ ࡴنَّمَا يَبْلُوكُمُ ࡲ۬للَّهُ بِهِۦ࣌ وَلَيُبَيِّنَنَّ لَكُمْ يَوْمَ ࡰ۬لْقِيَٰمَةِ مَا كُنتُمْ فِيهِ تَخْتَلِفُونَ࣌', 'ولا تكونوا كالتے نقضت غزلها من بعد قوة ࡰنكثا تتخذون أيمنكم دخلا بينكم أن تكون أمة هي أربى من ࡳمة࣌ ࡴنما يبلوكم ࡲلله به࣌ وليبينن لكم يوم ࡰلقيمة ما كنتم فيه تختلفون࣌', NULL, 277, 'local:warsh-text.json'),
  ('warsh-16-93', 'warsh', 16, 93, 'وَلَوْ شَآءَ ࡰ۬للَّهُ لَجَعَلَكُمُۥٓ أُمَّةࣰ وَٰحِدَةࣰ࣌ وَلَٰكِنْ يُّضِلُّ مَنْ يَّشَآءُ وَيَهْدِے مَنْ يَّشَآءُ࣌ وَلَتُسْـَٔلُنَّ عَمَّا كُنتُمْ تَعْمَلُونَ࣌', 'ولو شاء ࡰلله لجعلكم أمة وحدة࣌ ولكن يضل من يشاء ويهدے من يشاء࣌ ولتسلن عما كنتم تعملون࣌', NULL, 277, 'local:warsh-text.json'),
  ('warsh-16-94', 'warsh', 16, 94, 'وَلَا تَتَّخِذُوٓاْ أَيْمَٰنَكُمْ دَخَلاَۢ بَيْنَكُمْ فَتَزِلَّ قَدَمُۢ بَعْدَ ثُبُوتِهَا وَتَذُوقُواْ ࡲ۬لسُّوٓءَ بِمَا صَدَدتُّمْ عَن سَبِيلِ ࡴ۬للَّهِ وَلَكُمْ عَذَابٌ عَظِيمࣱ࣌', 'ولا تتخذوا أيمنكم دخلا بينكم فتزل قدم بعد ثبوتها وتذوقوا ࡲلسوء بما صددتم عن سبيل ࡴلله ولكم عذاب عظيم࣌', NULL, 278, 'local:warsh-text.json')
insert into public.ayahs (id, riwayah, surah_number, ayah_number, text, simple_text, juz, page, source) values
  ('warsh-16-95', 'warsh', 16, 95, 'وَلَا تَشْتَرُواْ بِعَهْدِ ࡴ۬للَّهِ ثَمَناࣰ قَلِيلاً࣌ ࡴنَّمَا عِندَ ࡰ۬للَّهِ هُوَ خَيْرࣱ لَّكُمُۥٓ إِن كُنتُمْ تَعْلَمُونَ࣌', 'ولا تشتروا بعهد ࡴلله ثمنا قليلا࣌ ࡴنما عند ࡰلله هو خير لكم إن كنتم تعلمون࣌', NULL, 278, 'local:warsh-text.json'),
  ('warsh-16-96', 'warsh', 16, 96, 'مَا عِندَكُمْ يَنفَدُ࣌ وَمَا عِندَ ࡰ۬للَّهِ بَاقࣲ࣌ وَلَيَجْزِيَنَّ ࡰ۬لذِينَ صَبَرُوٓاْ أَجْرَهُم بِأَحْسَنِ مَا كَانُواْ يَعْمَلُونَ࣌', 'ما عندكم ينفد࣌ وما عند ࡰلله باق࣌ وليجزين ࡰلذين صبروا أجرهم بأحسن ما كانوا يعملون࣌', NULL, 278, 'local:warsh-text.json'),
  ('warsh-16-97', 'warsh', 16, 97, 'مَنْ عَمِلَ صَٰلِحاࣰ مِّن ذَكَرٍ ࡰوُ ࡳنثٜىٰ وَهُوَ مُومِنࣱ فَلَنُحْيِيَنَّهُۥ حَيَوٰةࣰ طَيِّبَةࣰ وَلَنَجْزِيَنَّهُمُۥٓ أَجْرَهُم بِأَحْسَنِ مَا كَانُواْ يَعْمَلُونَ࣌', 'من عمل صلحا من ذكر ࡰو ࡳنثى وهو مومن فلنحيينه حيوة طيبة ولنجزينهم أجرهم بأحسن ما كانوا يعملون࣌', NULL, 278, 'local:warsh-text.json'),
  ('warsh-16-98', 'warsh', 16, 98, '۞ فَإِذَا قَرَأْتَ ࡰ۬لْقُرْءَانَ فَاسْتَعِذْ بِاللَّهِ مِنَ ࡰ۬لشَّيْطَٰنِ ࡴ۬لرَّجِيمِ࣌', 'فإذا قرأت ࡰلقرءان فاستعذ بالله من ࡰلشيطن ࡴلرجيم࣌', NULL, 278, 'local:warsh-text.json'),
  ('warsh-16-99', 'warsh', 16, 99, 'إِنَّهُۥ لَيْسَ لَهُۥ سُلْطَٰنٌ عَلَى ࡰ۬لذِينَ ءَامَنُواْ وَعَلَىٰ رَبِّهِمْ يَتَوَكَّلُونَ࣌', 'إنه ليس له سلطن على ࡰلذين ءامنوا وعلى ربهم يتوكلون࣌', NULL, 278, 'local:warsh-text.json'),
  ('warsh-16-100', 'warsh', 16, 100, 'إِنَّمَا سُلْطَٰنُهُۥ عَلَى ࡰ۬لذِينَ يَتَوَلَّوْنَهُۥ وَالذِينَ هُم بِهِۦ مُشْرِكُونَ࣌', 'إنما سلطنه على ࡰلذين يتولونه والذين هم به مشركون࣌', NULL, 278, 'local:warsh-text.json'),
  ('warsh-16-101', 'warsh', 16, 101, 'وَإِذَا بَدَّلْنَآ ءَايَةࣰ مَّكَانَ ءَايَةࣲ وَاللَّهُ أَعْلَمُ بِمَا يُنَزِّلُ قَالُوٓاْ إِنَّمَآ أَنتَ مُفْتَرِۢ࣌ بَلَ ࡰكْثَرُهُمْ لَا يَعْلَمُونَ࣌', 'وإذا بدلنا ءاية مكان ءاية والله أعلم بما ينزل قالوا إنما أنت مفتر࣌ بل ࡰكثرهم لا يعلمون࣌', NULL, 278, 'local:warsh-text.json'),
  ('warsh-16-102', 'warsh', 16, 102, 'قُلْ نَزَّلَهُۥ رُوحُ ࡲ۬لْقُدُسِ مِن رَّبِّكَ بِالْحَقِّ لِيُثَبِّتَ ࡰ۬لذِينَ ءَامَنُواْ وَهُدىࣰ وَبُشْرٜىٰ لِلْمُسْلِمِينَ࣌', 'قل نزله روح ࡲلقدس من ربك بالحق ليثبت ࡰلذين ءامنوا وهدى وبشرى للمسلمين࣌', NULL, 278, 'local:warsh-text.json'),
  ('warsh-16-103', 'warsh', 16, 103, 'وَلَقَدْ نَعْلَمُ أَنَّهُمْ يَقُولُونَ إِنَّمَا يُعَلِّمُهُۥ بَشَرࣱ࣌ لِّسَانُ ࡲ۬لذِے يُلْحِدُونَ إِلَيْهِ أَعْجَمِيࣱّ وَهَٰذَا لِسَانٌ عَرَبِيࣱّ مُّبِينٌ࣌', 'ولقد نعلم أنهم يقولون إنما يعلمه بشر࣌ لسان ࡲلذے يلحدون إليه أعجمي وهذا لسان عربي مبين࣌', NULL, 279, 'local:warsh-text.json'),
  ('warsh-16-104', 'warsh', 16, 104, 'ࡴنَّ ࡰ۬لذِينَ لَا يُومِنُونَ بِـَٔايَٰتِ ࡴ۬للَّهِ لَا يَهْدِيهِمُ ࡲ۬للَّهُ࣌ وَلَهُمْ عَذَابٌ ࡰلِيمٌ࣌', 'ࡴن ࡰلذين لا يومنون بايت ࡴلله لا يهديهم ࡲلله࣌ ولهم عذاب ࡰليم࣌', NULL, 279, 'local:warsh-text.json'),
  ('warsh-16-105', 'warsh', 16, 105, 'ࡴنَّمَا يَفْتَرِے ࡴ۬لْكَذِبَ ࡰ۬لذِينَ لَا يُومِنُونَ بِـَٔايَٰتِ ࡴ۬للَّهِ࣌ وَأُوْلَٰٓئِكَ هُمُ ࡲ۬لْكَٰذِبُونَ࣌', 'ࡴنما يفترے ࡴلكذب ࡰلذين لا يومنون بايت ࡴلله࣌ وأولئك هم ࡲلكذبون࣌', NULL, 279, 'local:warsh-text.json'),
  ('warsh-16-106', 'warsh', 16, 106, 'مَن كَفَرَ بِاللَّهِ مِنۢ بَعْدِ إِيمَٰنِهِۦٓ إِلَّا مَنُ ࡳكْرِهَ وَقَلْبُهُۥ مُطْمَئِنُّۢ بِالِايمَٰنِ࣌ وَلَٰكِن مَّن شَرَحَ بِالْكُفْرِ صَدْراࣰ فَعَلَيْهِمْ غَضَبࣱ مِّنَ ࡰ۬للَّهِ࣌ وَلَهُمْ عَذَابٌ عَظِيمࣱ࣌', 'من كفر بالله من بعد إيمنه إلا من ࡳكره وقلبه مطمئن بالايمن࣌ ولكن من شرح بالكفر صدرا فعليهم غضب من ࡰلله࣌ ولهم عذاب عظيم࣌', NULL, 279, 'local:warsh-text.json'),
  ('warsh-16-107', 'warsh', 16, 107, 'ذَٰلِكَ بِأَنَّهُمُ ࡲٜسْتَحَبُّواْ ࡲ۬لْحَيَوٰةَ ࡰ۬لدُّنْيٜا عَلَى ࡰ۬لَاخِرَةِ وَأَنَّ ࡰ۬للَّهَ لَا يَهْدِے ࡴ۬لْقَوْمَ ࡰ۬لْكٜـٰفِرِينَ࣌', 'ذلك بأنهم ࡲستحبوا ࡲلحيوة ࡰلدنيا على ࡰلاخرة وأن ࡰلله لا يهدے ࡴلقوم ࡰلكفرين࣌', NULL, 279, 'local:warsh-text.json'),
  ('warsh-16-108', 'warsh', 16, 108, 'أُوْلَٰٓئِكَ ࡰ۬لذِينَ طَبَعَ ࡰ۬للَّهُ عَلَىٰ قُلُوبِهِمْ وَسَمْعِهِمْ وَأَبْصٜـٰرِهِمْ࣌ وَأُوْلَٰٓئِكَ هُمُ ࡲ۬لْغَٰفِلُونَ࣌', 'أولئك ࡰلذين طبع ࡰلله على قلوبهم وسمعهم وأبصرهم࣌ وأولئك هم ࡲلغفلون࣌', NULL, 279, 'local:warsh-text.json'),
  ('warsh-16-109', 'warsh', 16, 109, 'لَا جَرَمَ أَنَّهُمْ فِے ࡴ۬لَاخِرَةِ هُمُ ࡲ۬لْخَٰسِرُونَ࣌', 'لا جرم أنهم فے ࡴلاخرة هم ࡲلخسرون࣌', NULL, 279, 'local:warsh-text.json'),
  ('warsh-16-110', 'warsh', 16, 110, 'ثُمَّ إِنَّ رَبَّكَ لِلذِينَ هَاجَرُواْ مِنۢ بَعْدِ مَا فُتِنُواْ ثُمَّ جَٰهَدُواْ وَصَبَرُوٓاْ إِنَّ رَبَّكَ مِنۢ بَعْدِهَا لَغَفُورࣱ رَّحِيمࣱ࣌', 'ثم إن ربك للذين هاجروا من بعد ما فتنوا ثم جهدوا وصبروا إن ربك من بعدها لغفور رحيم࣌', NULL, 279, 'local:warsh-text.json'),
  ('warsh-16-111', 'warsh', 16, 111, '۞ يَوْمَ تَاتِے كُلُّ نَفْسࣲ تُجَٰدِلُ عَن نَّفْسِهَا وَتُوَفّٜىٰ كُلُّ نَفْسࣲ مَّا عَمِلَتْ وَهُمْ لَا يُظْلَمُونَ࣌', 'يوم تاتے كل نفس تجدل عن نفسها وتوفى كل نفس ما عملت وهم لا يظلمون࣌', NULL, 280, 'local:warsh-text.json'),
  ('warsh-16-112', 'warsh', 16, 112, 'وَضَرَبَ ࡰ۬للَّهُ مَثَلاࣰ قَرْيَةࣰ كَانَتَ اٰمِنَةࣰ مُّطْمَئِنَّةࣰ يَاتِيهَا رِزْقُهَا رَغَداࣰ مِّن كُلِّ مَكَانࣲ فَكَفَرَتْ بِأَنْعُمِ ࡴ۬للَّهِ فَأَذَاقَهَا ࡰ۬للَّهُ لِبَاسَ ࡰ۬لْجُوعِ وَالْخَوْفِ بِمَا كَانُواْ يَصْنَعُونَ࣌', 'وضرب ࡰلله مثلا قرية كانت امنة مطمئنة ياتيها رزقها رغدا من كل مكان فكفرت بأنعم ࡴلله فأذاقها ࡰلله لباس ࡰلجوع والخوف بما كانوا يصنعون࣌', NULL, 280, 'local:warsh-text.json'),
  ('warsh-16-113', 'warsh', 16, 113, 'وَلَقَدْ جَآءَهُمْ رَسُولࣱ مِّنْهُمْ فَكَذَّبُوهُ فَأَخَذَهُمُ ࡲ۬لْعَذَابُ وَهُمْ ظَٰلِمُونَ࣌', 'ولقد جاءهم رسول منهم فكذبوه فأخذهم ࡲلعذاب وهم ظلمون࣌', NULL, 280, 'local:warsh-text.json'),
  ('warsh-16-114', 'warsh', 16, 114, 'فَكُلُواْ مِمَّا رَزَقَكُمُ ࡲ۬للَّهُ حَلَٰلاࣰ طَيِّباࣰ࣌ وَاشْكُرُواْ نِعْمَتَ ࡰ۬للَّهِ إِن كُنتُمُۥٓ إِيَّاهُ تَعْبُدُونَ࣌', 'فكلوا مما رزقكم ࡲلله حللا طيبا࣌ واشكروا نعمت ࡰلله إن كنتم إياه تعبدون࣌', NULL, 280, 'local:warsh-text.json'),
  ('warsh-16-115', 'warsh', 16, 115, 'إِنَّمَا حَرَّمَ عَلَيْكُمُ ࡲ۬لْمَيْتَةَ وَالدَّمَ وَلَحْمَ ࡰ۬لْخِنزِيرِ وَمَآ أُهِلَّ لِغَيْرِ ࡴ۬للَّهِ بِهِۦ࣌ فَمَنُ ࡲ࢈ضْطُرَّ غَيْرَ بَاغࣲ وَلَا عَادࣲ فَإِنَّ ࡰ۬للَّهَ غَفُورࣱ رَّحِيمࣱ࣌', 'إنما حرم عليكم ࡲلميتة والدم ولحم ࡰلخنزير وما أهل لغير ࡴلله به࣌ فمن ࡲ࢈ضطر غير باغ ولا عاد فإن ࡰلله غفور رحيم࣌', NULL, 280, 'local:warsh-text.json'),
  ('warsh-16-116', 'warsh', 16, 116, 'وَلَا تَقُولُواْ لِمَا تَصِفُ أَلْسِنَتُكُمُ ࡲ۬لْكَذِبَ هَٰذَا حَلَٰلࣱ وَهَٰذَا حَرَامࣱ لِّتَفْتَرُواْ عَلَى ࡰ۬للَّهِ ࡴ۬لْكَذِبَ࣌ إِنَّ ࡰ۬لذِينَ يَفْتَرُونَ عَلَى ࡰ۬للَّهِ ࡴ۬لْكَذِبَ لَا يُفْلِحُونَ࣌', 'ولا تقولوا لما تصف ألسنتكم ࡲلكذب هذا حلل وهذا حرام لتفتروا على ࡰلله ࡴلكذب࣌ إن ࡰلذين يفترون على ࡰلله ࡴلكذب لا يفلحون࣌', NULL, 280, 'local:warsh-text.json'),
  ('warsh-16-117', 'warsh', 16, 117, 'مَتَٰعࣱ قَلِيلࣱ࣌ وَلَهُمْ عَذَابٌ ࡰلِيمࣱ࣌', 'متع قليل࣌ ولهم عذاب ࡰليم࣌', NULL, 280, 'local:warsh-text.json'),
  ('warsh-16-118', 'warsh', 16, 118, 'وَعَلَى ࡰ۬لذِينَ هَادُواْ حَرَّمْنَا مَا قَصَصْنَا عَلَيْكَ مِن قَبْلُ࣌ وَمَا ظَلَمْنَٰهُمْ࣌ وَلَٰكِن كَانُوٓاْ أَنفُسَهُمْ يَظْلِمُونَ࣌', 'وعلى ࡰلذين هادوا حرمنا ما قصصنا عليك من قبل࣌ وما ظلمنهم࣌ ولكن كانوا أنفسهم يظلمون࣌', NULL, 280, 'local:warsh-text.json'),
  ('warsh-16-119', 'warsh', 16, 119, 'ثُمَّ إِنَّ رَبَّكَ لِلذِينَ عَمِلُواْ ࡲ۬لسُّوٓءَ بِجَهَٰلَةࣲ ثُمَّ تَابُواْ مِنۢ بَعْدِ ذَٰلِكَ وَأَصْلَحُوٓاْ إِنَّ رَبَّكَ مِنۢ بَعْدِهَا لَغَفُورࣱ رَّحِيمٌ࣌', 'ثم إن ربك للذين عملوا ࡲلسوء بجهلة ثم تابوا من بعد ذلك وأصلحوا إن ربك من بعدها لغفور رحيم࣌', NULL, 281, 'local:warsh-text.json'),
  ('warsh-16-120', 'warsh', 16, 120, '۞ ࡴنَّ إِبْرَٰهِيمَ كَانَ أُمَّةࣰ قَانِتاࣰ لِّلهِ حَنِيفاࣰ وَلَمْ يَكُ مِنَ ࡰ۬لْمُشْرِكِينَ࣌', 'ࡴن إبرهيم كان أمة قانتا لله حنيفا ولم يك من ࡰلمشركين࣌', NULL, 281, 'local:warsh-text.json'),
  ('warsh-16-121', 'warsh', 16, 121, 'شَاكِراࣰ لِّأَنْعُمِهِ࣌ ࡴٜجْتَبٜيٰهُ وَهَدٜيٰهُ إِلَىٰ صِرَٰطࣲ مُّسْتَقِيمࣲ࣌', 'شاكرا لأنعمه࣌ ࡴجتبيه وهديه إلى صرط مستقيم࣌', NULL, 281, 'local:warsh-text.json'),
  ('warsh-16-122', 'warsh', 16, 122, 'وَءَاتَيْنَٰهُ فِے ࡴ۬لدُّنْيٜا حَسَنَةࣰ࣌ وَإِنَّهُۥ فِے ࡴ۬لَاخِرَةِ لَمِنَ ࡰ۬لصَّٰلِحِينَ࣌', 'وءاتينه فے ࡴلدنيا حسنة࣌ وإنه فے ࡴلاخرة لمن ࡰلصلحين࣌', NULL, 281, 'local:warsh-text.json'),
  ('warsh-16-123', 'warsh', 16, 123, 'ثُمَّ أَوْحَيْنَآ إِلَيْكَ أَنِ ࡴٜتَّبِعْ مِلَّةَ إِبْرَٰهِيمَ حَنِيفاࣰ࣌ وَمَا كَانَ مِنَ ࡰ۬لْمُشْرِكِينَ࣌', 'ثم أوحينا إليك أن ࡴتبع ملة إبرهيم حنيفا࣌ وما كان من ࡰلمشركين࣌', NULL, 281, 'local:warsh-text.json'),
  ('warsh-16-124', 'warsh', 16, 124, 'إِنَّمَا جُعِلَ ࡰ۬لسَّبْتُ عَلَى ࡰ۬لذِينَ ࡰٜخْتَلَفُواْ فِيهِ࣌ وَإِنَّ رَبَّكَ لَيَحْكُمُ بَيْنَهُمْ يَوْمَ ࡰ۬لْقِيَٰمَةِ فِيمَا كَانُواْ فِيهِ يَخْتَلِفُونَ࣌', 'إنما جعل ࡰلسبت على ࡰلذين ࡰختلفوا فيه࣌ وإن ربك ليحكم بينهم يوم ࡰلقيمة فيما كانوا فيه يختلفون࣌', NULL, 281, 'local:warsh-text.json'),
  ('warsh-16-125', 'warsh', 16, 125, 'ࡸَدْعُ إِلَىٰ سَبِيلِ رَبِّكَ بِالْحِكْمَةِ وَالْمَوْعِظَةِ ࡴ۬لْحَسَنَةِ وَجَٰدِلْهُم بِالتِے هِيَ أَحْسَنُ࣌ إِنَّ رَبَّكَ هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِۦ࣌ وَهُوَ أَعْلَمُ بِالْمُهْتَدِينَ࣌', 'ࡸدع إلى سبيل ربك بالحكمة والموعظة ࡴلحسنة وجدلهم بالتے هي أحسن࣌ إن ربك هو أعلم بمن ضل عن سبيله࣌ وهو أعلم بالمهتدين࣌', NULL, 281, 'local:warsh-text.json'),
  ('warsh-16-126', 'warsh', 16, 126, 'وَإِنْ عَاقَبْتُمْ فَعَاقِبُواْ بِمِثْلِ مَا عُوقِبْتُم بِهِۦ࣌ وَلَئِن صَبَرْتُمْ لَهُوَ خَيْرࣱ لِّلصَّٰبِرِينَ࣌', 'وإن عاقبتم فعاقبوا بمثل ما عوقبتم به࣌ ولئن صبرتم لهو خير للصبرين࣌', NULL, 281, 'local:warsh-text.json'),
  ('warsh-16-127', 'warsh', 16, 127, 'وَاصْبِرْ࣌ وَمَا صَبْرُكَ إِلَّا بِاللَّهِ࣌ وَلَا تَحْزَنْ عَلَيْهِمْ وَلَا تَكُ فِے ضَيْقࣲ مِّمَّا يَمْكُرُونَ࣌', 'واصبر࣌ وما صبرك إلا بالله࣌ ولا تحزن عليهم ولا تك فے ضيق مما يمكرون࣌', NULL, 281, 'local:warsh-text.json'),
  ('warsh-16-128', 'warsh', 16, 128, 'إِنَّ ࡰ۬للَّهَ مَعَ ࡰ۬لذِينَ ࡰٜتَّقَواْ وَّالذِينَ هُم مُّحْسِنُونَ࣌', 'إن ࡰلله مع ࡰلذين ࡰتقوا والذين هم محسنون࣌', NULL, 281, 'local:warsh-text.json'),
  ('warsh-17-1', 'warsh', 17, 1, 'سُبْحَٰنَ ࡰ۬لذِےٓ أَسْرٜىٰ بِعَبْدِهِۦ لَيْلاࣰ مِّنَ ࡰ۬لْمَسْجِدِ ࡴ۬لْحَرَامِ إِلَى ࡰ۬لْمَسْجِدِ ࡴ۬لَاقْصَا ࡰ۬لذِے بَٰرَكْنَا حَوْلَهُۥ لِنُرِيَهُۥ مِنَ اٰيَٰتِنَآ࣌ إِنَّهُۥ هُوَ ࡰ۬لسَّمِيعُ ࡲ۬لْبَصِيرُ࣌', 'سبحن ࡰلذے أسرى بعبده ليلا من ࡰلمسجد ࡴلحرام إلى ࡰلمسجد ࡴلاقصا ࡰلذے بركنا حوله لنريه من ايتنا࣌ إنه هو ࡰلسميع ࡲلبصير࣌', NULL, 282, 'local:warsh-text.json'),
  ('warsh-17-2', 'warsh', 17, 2, 'وَءَاتَيْنَا مُوسَى ࡰ۬لْكِتَٰبَ وَجَعَلْنَٰهُ هُدىࣰ لِّبَنِےٓ إِسْرَآءِيلَ أَلَّا تَتَّخِذُواْ مِن دُونِے وَكِيلاࣰ', 'وءاتينا موسى ࡰلكتب وجعلنه هدى لبنے إسراءيل ألا تتخذوا من دونے وكيلا', NULL, 282, 'local:warsh-text.json'),
  ('warsh-17-3', 'warsh', 17, 3, 'ذُرِّيَّةَ مَنْ حَمَلْنَا مَعَ نُوحٍ࣌ ࡴنَّهُۥ كَانَ عَبْداࣰ شَكُوراࣰ࣌', 'ذرية من حملنا مع نوح࣌ ࡴنه كان عبدا شكورا࣌', NULL, 282, 'local:warsh-text.json'),
  ('warsh-17-4', 'warsh', 17, 4, 'وَقَضَيْنَآ إِلَىٰ بَنِےٓ إِسْرَآءِيلَ فِے ࡴ۬لْكِتَٰبِ لَتُفْسِدُنَّ فِے ࡴ۬لَارْضِ مَرَّتَيْنِ وَلَتَعْلُنَّ عُلُوّاࣰ كَبِيراࣰ࣌', 'وقضينا إلى بنے إسراءيل فے ࡴلكتب لتفسدن فے ࡴلارض مرتين ولتعلن علوا كبيرا࣌', NULL, 282, 'local:warsh-text.json'),
  ('warsh-17-5', 'warsh', 17, 5, 'فَإِذَا جَآءَ وَعْدُ أُولٜيٰهُمَا بَعَثْنَا عَلَيْكُمْ عِبَاداࣰ لَّنَآ أُوْلِے بَأْسࣲ شَدِيدࣲ فَجَاسُواْ خِلَٰلَ ࡰ۬لدِّيٜارِ࣌ وَكَانَ وَعْداࣰ مَّفْعُولاࣰ࣌', 'فإذا جاء وعد أوليهما بعثنا عليكم عبادا لنا أولے بأس شديد فجاسوا خلل ࡰلديار࣌ وكان وعدا مفعولا࣌', NULL, 282, 'local:warsh-text.json'),
  ('warsh-17-6', 'warsh', 17, 6, 'ثُمَّ رَدَدْنَا لَكُمُ ࡲ۬لْكَرَّةَ عَلَيْهِمْ وَأَمْدَدْنَٰكُم بِأَمْوَٰلࣲ وَبَنِينَ وَجَعَلْنَٰكُمُۥٓ أَكْثَرَ نَفِيراً࣌', 'ثم رددنا لكم ࡲلكرة عليهم وأمددنكم بأمول وبنين وجعلنكم أكثر نفيرا࣌', NULL, 282, 'local:warsh-text.json'),
  ('warsh-17-7', 'warsh', 17, 7, 'ࡴنَ ࡰحْسَنتُمُۥٓ أَحْسَنتُمْ لِأَنفُسِكُمْ࣌ وَإِنَ ࡰسَأْتُمْ فَلَهَا࣌ فَإِذَا جَآءَ وَعْدُ ࡲ۬لَاخِرَةِ لِيَسُـُٔواْ وُجُوهَكُمْ وَلِيَدْخُلُواْ ࡲ۬لْمَسْجِدَ كَمَا دَخَلُوهُ أَوَّلَ مَرَّةࣲ وَلِيُتَبِّرُواْ مَا عَلَوْاْ تَتْبِيراً࣌', 'ࡴن ࡰحسنتم أحسنتم لأنفسكم࣌ وإن ࡰسأتم فلها࣌ فإذا جاء وعد ࡲلاخرة ليسوا وجوهكم وليدخلوا ࡲلمسجد كما دخلوه أول مرة وليتبروا ما علوا تتبيرا࣌', NULL, 282, 'local:warsh-text.json'),
  ('warsh-17-8', 'warsh', 17, 8, 'عَسٜىٰ رَبُّكُمُۥٓ أَنْ يَّرْحَمَكُمْ࣌ وَإِنْ عُدتُّمْ عُدْنَا࣌ وَجَعَلْنَا جَهَنَّمَ لِلْكٜـٰفِرِينَ حَصِيراً࣌', 'عسى ربكم أن يرحمكم࣌ وإن عدتم عدنا࣌ وجعلنا جهنم للكفرين حصيرا࣌', NULL, 283, 'local:warsh-text.json'),
  ('warsh-17-9', 'warsh', 17, 9, 'ࡴنَّ هَٰذَا ࡰ۬لْقُرْءَانَ يَهْدِے لِلتِے هِيَ أَقْوَمُ وَيُبَشِّرُ ࡲ۬لْمُومِنِينَ ࡰ۬لذِينَ يَعْمَلُونَ ࡰ۬لصَّٰلِحَٰتِ أَنَّ لَهُمُۥٓ أَجْراࣰ كَبِيراࣰ', 'ࡴن هذا ࡰلقرءان يهدے للتے هي أقوم ويبشر ࡲلمومنين ࡰلذين يعملون ࡰلصلحت أن لهم أجرا كبيرا', NULL, 283, 'local:warsh-text.json'),
  ('warsh-17-10', 'warsh', 17, 10, 'وَأَنَّ ࡰ۬لذِينَ لَا يُومِنُونَ بِالَاخِرَةِ أَعْتَدْنَا لَهُمْ عَذَاباً ࡰلِيماࣰ࣌', 'وأن ࡰلذين لا يومنون بالاخرة أعتدنا لهم عذابا ࡰليما࣌', NULL, 283, 'local:warsh-text.json'),
  ('warsh-17-11', 'warsh', 17, 11, '۞ وَيَدْعُ ࡲ۬لِانسَٰنُ بِالشَّرِّ دُعَآءَهُۥ بِالْخَيْرِ࣌ وَكَانَ ࡰ۬لِانسَٰنُ عَجُولاࣰ࣌', 'ويدع ࡲلانسن بالشر دعاءه بالخير࣌ وكان ࡰلانسن عجولا࣌', NULL, 283, 'local:warsh-text.json'),
  ('warsh-17-12', 'warsh', 17, 12, 'وَجَعَلْنَا ࡰ۬ليْلَ وَالنَّهَارَ ءَايَتَيْنِ فَمَحَوْنَآ ءَايَةَ ࡰ۬ليْلِ وَجَعَلْنَآ ءَايَةَ ࡰ۬لنَّهٜارِ مُبْصِرَةࣰ لِّتَبْتَغُواْ فَضْلاࣰ مِّن رَّبِّكُمْ وَلِتَعْلَمُواْ عَدَدَ ࡰ۬لسِّنِينَ وَالْحِسَابَ࣌ وَكُلَّ شَےْءࣲ فَصَّلْنَٰهُ تَفْصِيلاࣰ࣌', 'وجعلنا ࡰليل والنهار ءايتين فمحونا ءاية ࡰليل وجعلنا ءاية ࡰلنهار مبصرة لتبتغوا فضلا من ربكم ولتعلموا عدد ࡰلسنين والحساب࣌ وكل شےء فصلنه تفصيلا࣌', NULL, 283, 'local:warsh-text.json'),
  ('warsh-17-13', 'warsh', 17, 13, 'وَكُلَّ إِنسَٰنٍ ࡰلْزَمْنَٰهُ طَٰٓئِرَهُۥ فِے عُنُقِهِۦ وَنُخْرِجُ لَهُۥ يَوْمَ ࡰ۬لْقِيَٰمَةِ كِتَٰباࣰ يَلْقٜيٰهُ مَنشُوراً࣌', 'وكل إنسن ࡰلزمنه طئره فے عنقه ونخرج له يوم ࡰلقيمة كتبا يلقيه منشورا࣌', NULL, 283, 'local:warsh-text.json'),
  ('warsh-17-14', 'warsh', 17, 14, 'ࡴٜقْرَأْ كِتَٰبَكَ كَفٜىٰ بِنَفْسِكَ ࡰ۬لْيَوْمَ عَلَيْكَ حَسِيباࣰ࣌', 'ࡴقرأ كتبك كفى بنفسك ࡰليوم عليك حسيبا࣌', NULL, 283, 'local:warsh-text.json'),
  ('warsh-17-15', 'warsh', 17, 15, 'مَّنِ ࡴٜهْتَدٜىٰ فَإِنَّمَا يَهْتَدِے لِنَفْسِهِۦ࣌ وَمَن ضَلَّ فَإِنَّمَا يَضِلُّ عَلَيْهَا࣌ وَلَا تَزِرُ وَازِرَةࣱ وِزْرَ أُخْرٜىٰ࣌ وَمَا كُنَّا مُعَذِّبِينَ حَتَّىٰ نَبْعَثَ رَسُولاࣰ࣌', 'من ࡴهتدى فإنما يهتدے لنفسه࣌ ومن ضل فإنما يضل عليها࣌ ولا تزر وازرة وزر أخرى࣌ وما كنا معذبين حتى نبعث رسولا࣌', NULL, 283, 'local:warsh-text.json'),
  ('warsh-17-16', 'warsh', 17, 16, 'وَإِذَآ أَرَدْنَآ أَن نُّهْلِكَ قَرْيَةً ࡰمَرْنَا مُتْرَفِيهَا فَفَسَقُواْ فِيهَا فَحَقَّ عَلَيْهَا ࡰ۬لْقَوْلُ فَدَمَّرْنَٰهَا تَدْمِيراࣰ࣌', 'وإذا أردنا أن نهلك قرية ࡰمرنا مترفيها ففسقوا فيها فحق عليها ࡰلقول فدمرنها تدميرا࣌', NULL, 283, 'local:warsh-text.json'),
  ('warsh-17-17', 'warsh', 17, 17, 'وَكَمَ ࡰهْلَكْنَا مِنَ ࡰ۬لْقُرُونِ مِنۢ بَعْدِ نُوحࣲ࣌ وَكَفٜىٰ بِرَبِّكَ بِذُنُوبِ عِبَادِهِۦ خَبِيراَۢ بَصِيراࣰ࣌', 'وكم ࡰهلكنا من ࡰلقرون من بعد نوح࣌ وكفى بربك بذنوب عباده خبيرا بصيرا࣌', NULL, 283, 'local:warsh-text.json'),
  ('warsh-17-18', 'warsh', 17, 18, 'مَّن كَانَ يُرِيدُ ࡲ۬لْعَاجِلَةَ عَجَّلْنَا لَهُۥ فِيهَا مَا نَشَآءُ لِمَن نُّرِيدُ ثُمَّ جَعَلْنَا لَهُۥ جَهَنَّمَ يَصْلَيٰهَا مَذْمُوماࣰ مَّدْحُوراࣰ࣌', 'من كان يريد ࡲلعاجلة عجلنا له فيها ما نشاء لمن نريد ثم جعلنا له جهنم يصليها مذموما مدحورا࣌', NULL, 284, 'local:warsh-text.json'),
  ('warsh-17-19', 'warsh', 17, 19, 'وَمَنَ ࡰرَادَ ࡰ۬لَاخِرَةَ وَسَعٜىٰ لَهَا سَعْيَهَا وَهُوَ مُومِنࣱ فَأُوْلَٰٓئِكَ كَانَ سَعْيُهُم مَّشْكُوراࣰ࣌', 'ومن ࡰراد ࡰلاخرة وسعى لها سعيها وهو مومن فأولئك كان سعيهم مشكورا࣌', NULL, 284, 'local:warsh-text.json'),
  ('warsh-17-20', 'warsh', 17, 20, 'كُلّاࣰ نُّمِدُّ࣌ هَٰٓؤُلَآءِ وَهَٰٓؤُلَآءِ مِنْ عَطَآءِ رَبِّكَ࣌ وَمَا كَانَ عَطَآءُ رَبِّكَ مَحْظُوراً࣌', 'كلا نمد࣌ هؤلاء وهؤلاء من عطاء ربك࣌ وما كان عطاء ربك محظورا࣌', NULL, 284, 'local:warsh-text.json'),
  ('warsh-17-21', 'warsh', 17, 21, 'ࡲ࢈نظُرْ كَيْفَ فَضَّلْنَا بَعْضَهُمْ عَلَىٰ بَعْضࣲ࣌ وَلَلَاخِرَةُ أَكْبَرُ دَرَجَٰتࣲ وَأَكْبَرُ تَفْضِيلاࣰ࣌', 'ࡲ࢈نظر كيف فضلنا بعضهم على بعض࣌ وللاخرة أكبر درجت وأكبر تفضيلا࣌', NULL, 284, 'local:warsh-text.json'),
  ('warsh-17-22', 'warsh', 17, 22, 'لَّا تَجْعَلْ مَعَ ࡰ۬للَّهِ إِلَٰهاً اٰخَرَ فَتَقْعُدَ مَذْمُوماࣰ مَّخْذُولاࣰ࣌', 'لا تجعل مع ࡰلله إلها اخر فتقعد مذموما مخذولا࣌', NULL, 284, 'local:warsh-text.json'),
  ('warsh-17-23', 'warsh', 17, 23, '۞ وَقَضٜىٰ رَبُّكَ أَلَّا تَعْبُدُوٓاْ إِلَّآ إِيَّاهُ࣌ وَبِالْوَٰلِدَيْنِ إِحْسَٰناً࣌ ࡴمَّا يَبْلُغَنَّ عِندَكَ ࡰ۬لْكِبَرَ أَحَدُهُمَآ أَوْ كِلَاهُمَا فَلَا تَقُل لَّهُمَآ أُفࣲّ وَلَا تَنْهَرْهُمَا࣌ وَقُل لَّهُمَا قَوْلاࣰ كَرِيماࣰ࣌', 'وقضى ربك ألا تعبدوا إلا إياه࣌ وبالولدين إحسنا࣌ ࡴما يبلغن عندك ࡰلكبر أحدهما أو كلاهما فلا تقل لهما أف ولا تنهرهما࣌ وقل لهما قولا كريما࣌', NULL, 284, 'local:warsh-text.json'),
  ('warsh-17-24', 'warsh', 17, 24, 'وَاخْفِضْ لَهُمَا جَنَاحَ ࡰ۬لذُّلِّ مِنَ ࡰ۬لرَّحْمَةِ࣌ وَقُل رَّبِّ ࡴٜرْحَمْهُمَا كَمَا رَبَّيَٰنِے صَغِيراࣰ࣌', 'واخفض لهما جناح ࡰلذل من ࡰلرحمة࣌ وقل رب ࡴرحمهما كما ربينے صغيرا࣌', NULL, 284, 'local:warsh-text.json'),
  ('warsh-17-25', 'warsh', 17, 25, 'رَّبُّكُمُۥٓ أَعْلَمُ بِمَا فِے نُفُوسِكُمُۥٓ࣌ إِن تَكُونُواْ صَٰلِحِينَ فَإِنَّهُۥ كَانَ لِلَاوَّٰبِينَ غَفُوراࣰ࣌', 'ربكم أعلم بما فے نفوسكم࣌ إن تكونوا صلحين فإنه كان للاوبين غفورا࣌', NULL, 284, 'local:warsh-text.json'),
  ('warsh-17-26', 'warsh', 17, 26, 'وَءَاتِ ذَا ࡰ۬لْقُرْبٜىٰ حَقَّهُۥ وَالْمِسْكِينَ وَابْنَ ࡰ۬لسَّبِيلِ࣌ وَلَا تُبَذِّرْ تَبْذِيراً࣌', 'وءات ذا ࡰلقربى حقه والمسكين وابن ࡰلسبيل࣌ ولا تبذر تبذيرا࣌', NULL, 284, 'local:warsh-text.json'),
  ('warsh-17-27', 'warsh', 17, 27, 'ࡴنَّ ࡰ۬لْمُبَذِّرِينَ كَانُوٓاْ إِخْوَٰنَ ࡰ۬لشَّيَٰطِينِ࣌ وَكَانَ ࡰ۬لشَّيْطَٰنُ لِرَبِّهِۦ كَفُوراࣰ࣌', 'ࡴن ࡰلمبذرين كانوا إخون ࡰلشيطين࣌ وكان ࡰلشيطن لربه كفورا࣌', NULL, 284, 'local:warsh-text.json'),
  ('warsh-17-28', 'warsh', 17, 28, 'وَإِمَّا تُعْرِضَنَّ عَنْهُمُ ࡲٜبْتِغَآءَ رَحْمَةࣲ مِّن رَّبِّكَ تَرْجُوهَا فَقُل لَّهُمْ قَوْلاࣰ مَّيْسُوراࣰ࣌', 'وإما تعرضن عنهم ࡲبتغاء رحمة من ربك ترجوها فقل لهم قولا ميسورا࣌', NULL, 285, 'local:warsh-text.json'),
  ('warsh-17-29', 'warsh', 17, 29, 'وَلَا تَجْعَلْ يَدَكَ مَغْلُولَةً ࡴلَىٰ عُنُقِكَ وَلَا تَبْسُطْهَا كُلَّ ࡰ۬لْبَسْطِ فَتَقْعُدَ مَلُوماࣰ مَّحْسُوراً࣌', 'ولا تجعل يدك مغلولة ࡴلى عنقك ولا تبسطها كل ࡰلبسط فتقعد ملوما محسورا࣌', NULL, 285, 'local:warsh-text.json'),
  ('warsh-17-30', 'warsh', 17, 30, 'ࡴنَّ رَبَّكَ يَبْسُطُ ࡲ۬لرِّزْقَ لِمَنْ يَّشَآءُ وَيَقْدِرُ࣌ إِنَّهُۥ كَانَ بِعِبَادِهِۦ خَبِيراَۢ بَصِيراࣰ࣌', 'ࡴن ربك يبسط ࡲلرزق لمن يشاء ويقدر࣌ إنه كان بعباده خبيرا بصيرا࣌', NULL, 285, 'local:warsh-text.json'),
  ('warsh-17-31', 'warsh', 17, 31, 'وَلَا تَقْتُلُوٓاْ أَوْلَٰدَكُمْ خَشْيَةَ إِمْلَٰقࣲ࣌ نَّحْنُ نَرْزُقُهُمْ وَإِيَّاكُمُۥٓ࣌ إِنَّ قَتْلَهُمْ كَانَ خِطْـٔاࣰ كَبِيراࣰ࣌', 'ولا تقتلوا أولدكم خشية إملق࣌ نحن نرزقهم وإياكم࣌ إن قتلهم كان خطا كبيرا࣌', NULL, 285, 'local:warsh-text.json'),
  ('warsh-17-32', 'warsh', 17, 32, 'وَلَا تَقْرَبُواْ ࡲ۬لزِّنٜىٰٓ إِنَّهُۥ كَانَ فَٰحِشَةࣰ وَسَآءَ سَبِيلاࣰ࣌', 'ولا تقربوا ࡲلزنى إنه كان فحشة وساء سبيلا࣌', NULL, 285, 'local:warsh-text.json'),
  ('warsh-17-33', 'warsh', 17, 33, 'وَلَا تَقْتُلُواْ ࡲ۬لنَّفْسَ ࡰ۬لتِے حَرَّمَ ࡰ۬للَّهُ إِلَّا بِالْحَقِّ࣌ وَمَن قُتِلَ مَظْلُوماࣰ فَقَدْ جَعَلْنَا لِوَلِيِّهِۦ سُلْطَٰناࣰ فَلَا يُسْرِف فِّے ࡴ۬لْقَتْلِ࣌ إِنَّهُۥ كَانَ مَنصُوراࣰ࣌', 'ولا تقتلوا ࡲلنفس ࡰلتے حرم ࡰلله إلا بالحق࣌ ومن قتل مظلوما فقد جعلنا لوليه سلطنا فلا يسرف فے ࡴلقتل࣌ إنه كان منصورا࣌', NULL, 285, 'local:warsh-text.json'),
  ('warsh-17-34', 'warsh', 17, 34, 'وَلَا تَقْرَبُواْ مَالَ ࡰ۬لْيَتِيمِ إِلَّا بِالتِے هِيَ أَحْسَنُ حَتَّىٰ يَبْلُغَ أَشُدَّهُۥ࣌ وَأَوْفُواْ بِالْعَهْدِ࣌ إِنَّ ࡰ۬لْعَهْدَ كَانَ مَسْـُٔولاࣰ࣌', 'ولا تقربوا مال ࡰليتيم إلا بالتے هي أحسن حتى يبلغ أشده࣌ وأوفوا بالعهد࣌ إن ࡰلعهد كان مسولا࣌', NULL, 285, 'local:warsh-text.json'),
  ('warsh-17-35', 'warsh', 17, 35, 'وَأَوْفُواْ ࡲ۬لْكَيْلَ إِذَا كِلْتُمْ وَزِنُواْ بِالْقُسْطَاسِ ࡴ۬لْمُسْتَقِيمِ࣌ ذَٰلِكَ خَيْرࣱ وَأَحْسَنُ تَاوِيلاࣰ࣌', 'وأوفوا ࡲلكيل إذا كلتم وزنوا بالقسطاس ࡴلمستقيم࣌ ذلك خير وأحسن تاويلا࣌', NULL, 285, 'local:warsh-text.json'),
  ('warsh-17-36', 'warsh', 17, 36, '۞ وَلَا تَقْفُ مَا لَيْسَ لَكَ بِهِۦ عِلْمٌ࣌ ࡴنَّ ࡰ۬لسَّمْعَ وَالْبَصَرَ وَالْفُؤَادَ كُلُّ أُوْلَٰٓئِكَ كَانَ عَنْهُ مَسْـُٔولاࣰ࣌', 'ولا تقف ما ليس لك به علم࣌ ࡴن ࡰلسمع والبصر والفؤاد كل أولئك كان عنه مسولا࣌', NULL, 285, 'local:warsh-text.json'),
  ('warsh-17-37', 'warsh', 17, 37, 'وَلَا تَمْشِ فِے ࡴ۬لَارْضِ مَرَحاً࣌ ࡴنَّكَ لَن تَخْرِقَ ࡰ۬لَارْضَ وَلَن تَبْلُغَ ࡰ۬لْجِبَالَ طُولاࣰ࣌', 'ولا تمش فے ࡴلارض مرحا࣌ ࡴنك لن تخرق ࡰلارض ولن تبلغ ࡰلجبال طولا࣌', NULL, 285, 'local:warsh-text.json'),
  ('warsh-17-38', 'warsh', 17, 38, 'كُلُّ ذَٰلِكَ كَانَ سَيِّئَةً عِندَ رَبِّكَ مَكْرُوهاࣰ࣌', 'كل ذلك كان سيئة عند ربك مكروها࣌', NULL, 285, 'local:warsh-text.json'),
  ('warsh-17-39', 'warsh', 17, 39, 'ذَٰلِكَ مِمَّآ أَوْحٜىٰٓ إِلَيْكَ رَبُّكَ مِنَ ࡰ۬لْحِكْمَةِ࣌ وَلَا تَجْعَلْ مَعَ ࡰ۬للَّهِ إِلَٰهاً اٰخَرَ فَتُلْقٜىٰ فِے جَهَنَّمَ مَلُوماࣰ مَّدْحُوراً࣌', 'ذلك مما أوحى إليك ربك من ࡰلحكمة࣌ ولا تجعل مع ࡰلله إلها اخر فتلقى فے جهنم ملوما مدحورا࣌', NULL, 286, 'local:warsh-text.json'),
  ('warsh-17-40', 'warsh', 17, 40, 'ࡰفَأَصْفٜيٰكُمْ رَبُّكُم بِالْبَنِينَ وَاتَّخَذَ مِنَ ࡰ۬لْمَلَٰٓئِكَةِ إِنَٰثاً࣌ ࡴنَّكُمْ لَتَقُولُونَ قَوْلاً عَظِيماࣰ࣌', 'ࡰفأصفيكم ربكم بالبنين واتخذ من ࡰلملئكة إنثا࣌ ࡴنكم لتقولون قولا عظيما࣌', NULL, 286, 'local:warsh-text.json'),
  ('warsh-17-41', 'warsh', 17, 41, 'وَلَقَدْ صَرَّفْنَا فِے هَٰذَا ࡰ۬لْقُرْءَانِ لِيَذَّكَّرُواْ وَمَا يَزِيدُهُمُۥٓ إِلَّا نُفُوراࣰ࣌', 'ولقد صرفنا فے هذا ࡰلقرءان ليذكروا وما يزيدهم إلا نفورا࣌', NULL, 286, 'local:warsh-text.json'),
  ('warsh-17-42', 'warsh', 17, 42, 'قُل لَّوْ كَانَ مَعَهُۥٓ ءَالِهَةࣱ كَمَا تَقُولُونَ إِذاࣰ لَّابْتَغَوِاْ ࡴلَىٰ ذِے ࡴ۬لْعَرْشِ سَبِيلاࣰ࣌', 'قل لو كان معه ءالهة كما تقولون إذا لابتغوا ࡴلى ذے ࡴلعرش سبيلا࣌', NULL, 286, 'local:warsh-text.json'),
  ('warsh-17-43', 'warsh', 17, 43, 'سُبْحَٰنَهُۥ وَتَعَٰلٜىٰ عَمَّا يَقُولُونَ عُلُوّاࣰ كَبِيراࣰ࣌', 'سبحنه وتعلى عما يقولون علوا كبيرا࣌', NULL, 286, 'local:warsh-text.json'),
  ('warsh-17-44', 'warsh', 17, 44, 'يُسَبِّحُ لَهُ ࡲ۬لسَّمَٰوَٰتُ ࡲ۬لسَّبْعُ وَالَارْضُ وَمَن فِيهِنَّ࣌ وَإِن مِّن شَےْءٍ ࡴلَّا يُسَبِّحُ بِحَمْدِهِۦ࣌ وَلَٰكِن لَّا تَفْقَهُونَ تَسْبِيحَهُمُۥٓ࣌ إِنَّهُۥ كَانَ حَلِيماً غَفُوراࣰ࣌', 'يسبح له ࡲلسموت ࡲلسبع والارض ومن فيهن࣌ وإن من شےء ࡴلا يسبح بحمده࣌ ولكن لا تفقهون تسبيحهم࣌ إنه كان حليما غفورا࣌', NULL, 286, 'local:warsh-text.json'),
  ('warsh-17-45', 'warsh', 17, 45, 'وَإِذَا قَرَأْتَ ࡰ۬لْقُرْءَانَ جَعَلْنَا بَيْنَكَ وَبَيْنَ ࡰ۬لذِينَ لَا يُومِنُونَ بِالَاخِرَةِ حِجَاباࣰ مَّسْتُوراࣰ࣌', 'وإذا قرأت ࡰلقرءان جعلنا بينك وبين ࡰلذين لا يومنون بالاخرة حجابا مستورا࣌', NULL, 286, 'local:warsh-text.json'),
  ('warsh-17-46', 'warsh', 17, 46, 'وَجَعَلْنَا عَلَىٰ قُلُوبِهِمُۥٓ أَكِنَّةً ࡰنْ يَّفْقَهُوهُ وَفِےٓ ءَاذَانِهِمْ وَقْراࣰ࣌ وَإِذَا ذَكَرْتَ رَبَّكَ فِے ࡴ۬لْقُرْءَانِ وَحْدَهُۥ وَلَّوْاْ عَلَىٰٓ أَدْبٜـٰرِهِمْ نُفُوراࣰ࣌', 'وجعلنا على قلوبهم أكنة ࡰن يفقهوه وفے ءاذانهم وقرا࣌ وإذا ذكرت ربك فے ࡴلقرءان وحده ولوا على أدبرهم نفورا࣌', NULL, 286, 'local:warsh-text.json'),
  ('warsh-17-47', 'warsh', 17, 47, 'نَّحْنُ أَعْلَمُ بِمَا يَسْتَمِعُونَ بِهِۦٓ إِذْ يَسْتَمِعُونَ إِلَيْكَ وَإِذْ هُمْ نَجْوٜىٰٓ إِذْ يَقُولُ ࡲ۬لظَّٰلِمُونَ إِن تَتَّبِعُونَ إِلَّا رَجُلاࣰ مَّسْحُوراً࣌', 'نحن أعلم بما يستمعون به إذ يستمعون إليك وإذ هم نجوى إذ يقول ࡲلظلمون إن تتبعون إلا رجلا مسحورا࣌', NULL, 286, 'local:warsh-text.json'),
  ('warsh-17-48', 'warsh', 17, 48, 'ࡲ࢈نظُرْ كَيْفَ ضَرَبُواْ لَكَ ࡰ۬لَامْثَالَ فَضَلُّواْ࣌ فَلَا يَسْتَطِيعُونَ سَبِيلاࣰ࣌', 'ࡲ࢈نظر كيف ضربوا لك ࡰلامثال فضلوا࣌ فلا يستطيعون سبيلا࣌', NULL, 286, 'local:warsh-text.json'),
  ('warsh-17-49', 'warsh', 17, 49, 'وَقَالُوٓاْ أَࢇذَا كُنَّا عِظَٰماࣰ وَرُفَٰتاً ࡴنَّا لَمَبْعُوثُونَ خَلْقاࣰ جَدِيداࣰ࣌', 'وقالوا أࢇذا كنا عظما ورفتا ࡴنا لمبعوثون خلقا جديدا࣌', NULL, 286, 'local:warsh-text.json'),
  ('warsh-17-50', 'warsh', 17, 50, '۞ قُلْ كُونُواْ حِجَارَةً ࡰوْ حَدِيداً', 'قل كونوا حجارة ࡰو حديدا', NULL, 287, 'local:warsh-text.json'),
  ('warsh-17-51', 'warsh', 17, 51, 'ࡰوْ خَلْقاࣰ مِّمَّا يَكْبُرُ فِے صُدُورِكُمْ࣌ فَسَيَقُولُونَ مَنْ يُّعِيدُنَا࣌ قُلِ ࡴ۬لذِے فَطَرَكُمُۥٓ أَوَّلَ مَرَّةࣲ࣌ فَسَيُنْغِضُونَ إِلَيْكَ رُءُوسَهُمْ وَيَقُولُونَ مَتٜىٰ هُوَ࣌ قُلْ عَسٜىٰٓ أَنْ يَّكُونَ قَرِيباࣰ࣌', 'ࡰو خلقا مما يكبر فے صدوركم࣌ فسيقولون من يعيدنا࣌ قل ࡴلذے فطركم أول مرة࣌ فسينغضون إليك رءوسهم ويقولون متى هو࣌ قل عسى أن يكون قريبا࣌', NULL, 287, 'local:warsh-text.json'),
  ('warsh-17-52', 'warsh', 17, 52, 'يَوْمَ يَدْعُوكُمْ فَتَسْتَجِيبُونَ بِحَمْدِهِۦ وَتَظُنُّونَ إِن لَّبِثْتُمُۥٓ إِلَّا قَلِيلاࣰ࣌', 'يوم يدعوكم فتستجيبون بحمده وتظنون إن لبثتم إلا قليلا࣌', NULL, 287, 'local:warsh-text.json'),
  ('warsh-17-53', 'warsh', 17, 53, 'وَقُل لِّعِبَادِے يَقُولُواْ ࡲ۬لتِے هِيَ أَحْسَنُ࣌ إِنَّ ࡰ۬لشَّيْطَٰنَ يَنزَغُ بَيْنَهُمُۥٓ࣌ إِنَّ ࡰ۬لشَّيْطَٰنَ كَانَ لِلِانسَٰنِ عَدُوّاࣰ مُّبِيناࣰ࣌', 'وقل لعبادے يقولوا ࡲلتے هي أحسن࣌ إن ࡰلشيطن ينزغ بينهم࣌ إن ࡰلشيطن كان للانسن عدوا مبينا࣌', NULL, 287, 'local:warsh-text.json'),
  ('warsh-17-54', 'warsh', 17, 54, 'رَّبُّكُمُۥٓ أَعْلَمُ بِكُمُۥٓ إِنْ يَّشَأْ يَرْحَمْكُمُۥٓ أَوِ ࡴنْ يَّشَأْ يُعَذِّبْكُمْ࣌ وَمَآ أَرْسَلْنَٰكَ عَلَيْهِمْ وَكِيلاࣰ࣌', 'ربكم أعلم بكم إن يشأ يرحمكم أو ࡴن يشأ يعذبكم࣌ وما أرسلنك عليهم وكيلا࣌', NULL, 287, 'local:warsh-text.json'),
  ('warsh-17-55', 'warsh', 17, 55, 'وَرَبُّكَ أَعْلَمُ بِمَن فِے ࡴ۬لسَّمَٰوَٰتِ وَالَارْضِ࣌ وَلَقَدْ فَضَّلْنَا بَعْضَ ࡰ۬لنَّبِيٓـِٕۑنَ عَلَىٰ بَعْضࣲ وَءَاتَيْنَا دَاوُۥدَ زَبُوراࣰ࣌', 'وربك أعلم بمن فے ࡴلسموت والارض࣌ ولقد فضلنا بعض ࡰلنبيۑن على بعض وءاتينا داود زبورا࣌', NULL, 287, 'local:warsh-text.json'),
  ('warsh-17-56', 'warsh', 17, 56, 'قُلُ ࡲ࢈دْعُواْ ࡲ۬لذِينَ زَعَمْتُم مِّن دُونِهِۦ فَلَا يَمْلِكُونَ كَشْفَ ࡰ۬لضُّرِّ عَنكُمْ وَلَا تَحْوِيلاً࣌', 'قل ࡲ࢈دعوا ࡲلذين زعمتم من دونه فلا يملكون كشف ࡰلضر عنكم ولا تحويلا࣌', NULL, 287, 'local:warsh-text.json'),
  ('warsh-17-57', 'warsh', 17, 57, 'ࡳوْلَٰٓئِكَ ࡰ۬لذِينَ يَدْعُونَ يَبْتَغُونَ إِلَىٰ رَبِّهِمُ ࡲ۬لْوَسِيلَةَ أَيُّهُمُۥٓ أَقْرَبُ وَيَرْجُونَ رَحْمَتَهُۥ وَيَخَافُونَ عَذَابَهُۥٓ࣌ إِنَّ عَذَابَ رَبِّكَ كَانَ مَحْذُوراࣰ࣌', 'ࡳولئك ࡰلذين يدعون يبتغون إلى ربهم ࡲلوسيلة أيهم أقرب ويرجون رحمته ويخافون عذابه࣌ إن عذاب ربك كان محذورا࣌', NULL, 287, 'local:warsh-text.json'),
  ('warsh-17-58', 'warsh', 17, 58, 'وَإِن مِّن قَرْيَةٍ ࡴلَّا نَحْنُ مُهْلِكُوهَا قَبْلَ يَوْمِ ࡴ۬لْقِيَٰمَةِ أَوْ مُعَذِّبُوهَا عَذَاباࣰ شَدِيداࣰ࣌ كَانَ ذَٰلِكَ فِے ࡴ۬لْكِتَٰبِ مَسْطُوراࣰ࣌', 'وإن من قرية ࡴلا نحن مهلكوها قبل يوم ࡴلقيمة أو معذبوها عذابا شديدا࣌ كان ذلك فے ࡴلكتب مسطورا࣌', NULL, 287, 'local:warsh-text.json'),
  ('warsh-17-59', 'warsh', 17, 59, 'وَمَا مَنَعَنَآ أَن نُّرْسِلَ بِالَايَٰتِ إِلَّآ أَن كَذَّبَ بِهَا ࡰ۬لَاوَّلُونَ࣌ وَءَاتَيْنَا ثَمُودَ ࡰ۬لنَّاقَةَ مُبْصِرَةࣰ فَظَلَمُواْ بِهَا࣌ وَمَا نُرْسِلُ بِالَايَٰتِ إِلَّا تَخْوِيفاࣰ࣌', 'وما منعنا أن نرسل بالايت إلا أن كذب بها ࡰلاولون࣌ وءاتينا ثمود ࡰلناقة مبصرة فظلموا بها࣌ وما نرسل بالايت إلا تخويفا࣌', NULL, 288, 'local:warsh-text.json'),
  ('warsh-17-60', 'warsh', 17, 60, 'وَإِذْ قُلْنَا لَكَ إِنَّ رَبَّكَ أَحَاطَ بِالنَّاسِ࣌ وَمَا جَعَلْنَا ࡰ۬لرُّءْيَا ࡰ۬لتِےٓ أَرَيْنَٰكَ إِلَّا فِتْنَةࣰ لِّلنَّاسِ وَالشَّجَرَةَ ࡰ۬لْمَلْعُونَةَ فِے ࡴ۬لْقُرْءَانِ࣌ وَنُخَوِّفُهُمْ فَمَا يَزِيدُهُمُۥٓ إِلَّا طُغْيَٰناࣰ كَبِيراࣰ࣌', 'وإذ قلنا لك إن ربك أحاط بالناس࣌ وما جعلنا ࡰلرءيا ࡰلتے أرينك إلا فتنة للناس والشجرة ࡰلملعونة فے ࡴلقرءان࣌ ونخوفهم فما يزيدهم إلا طغينا كبيرا࣌', NULL, 288, 'local:warsh-text.json'),
  ('warsh-17-61', 'warsh', 17, 61, '۞ وَإِذْ قُلْنَا لِلْمَلَٰٓئِكَةِ ࡴ࢈سْجُدُواْ لِأٓدَمَ فَسَجَدُوٓاْ࣌ إِلَّآ إِبْلِيسَ قَالَ ءَآسْجُدُ لِمَنْ خَلَقْتَ طِيناࣰ࣌', 'وإذ قلنا للملئكة ࡴ࢈سجدوا لأدم فسجدوا࣌ إلا إبليس قال ءاسجد لمن خلقت طينا࣌', NULL, 288, 'local:warsh-text.json'),
  ('warsh-17-62', 'warsh', 17, 62, 'قَالَ أَرَٰٓيْتَكَ هَٰذَا ࡰ۬لذِے كَرَّمْتَ عَلَيَّ لَئِنَ ࡰخَّرْتَنِۦٓ إِلَىٰ يَوْمِ ࡴ۬لْقِيَٰمَةِ لَأَحْتَنِكَنَّ ذُرِّيَّتَهُۥٓ إِلَّا قَلِيلاࣰ࣌', 'قال أريتك هذا ࡰلذے كرمت علي لئن ࡰخرتن إلى يوم ࡴلقيمة لأحتنكن ذريته إلا قليلا࣌', NULL, 288, 'local:warsh-text.json'),
  ('warsh-17-63', 'warsh', 17, 63, 'قَالَ ࡰٜذْهَبْ فَمَن تَبِعَكَ مِنْهُمْ فَإِنَّ جَهَنَّمَ جَزَآؤُكُمْ جَزَآءࣰ مَّوْفُوراࣰ࣌', 'قال ࡰذهب فمن تبعك منهم فإن جهنم جزاؤكم جزاء موفورا࣌', NULL, 288, 'local:warsh-text.json'),
  ('warsh-17-64', 'warsh', 17, 64, 'وَاسْتَفْزِزْ مَنِ ࡴٜسْتَطَعْتَ مِنْهُم بِصَوْتِكَ وَأَجْلِبْ عَلَيْهِم بِخَيْلِكَ وَرَجْلِكَ وَشَارِكْهُمْ فِے ࡴ۬لَامْوَٰلِ وَالَاوْلَٰدِ وَعِدْهُمْ࣌ وَمَا يَعِدُهُمُ ࡲ۬لشَّيْطَٰنُ إِلَّا غُرُوراً࣌', 'واستفزز من ࡴستطعت منهم بصوتك وأجلب عليهم بخيلك ورجلك وشاركهم فے ࡴلامول والاولد وعدهم࣌ وما يعدهم ࡲلشيطن إلا غرورا࣌', NULL, 288, 'local:warsh-text.json'),
  ('warsh-17-65', 'warsh', 17, 65, 'ࡴنَّ عِبَادِے لَيْسَ لَكَ عَلَيْهِمْ سُلْطَٰنࣱ࣌ وَكَفٜىٰ بِرَبِّكَ وَكِيلاࣰ࣌', 'ࡴن عبادے ليس لك عليهم سلطن࣌ وكفى بربك وكيلا࣌', NULL, 288, 'local:warsh-text.json'),
  ('warsh-17-66', 'warsh', 17, 66, 'رَّبُّكُمُ ࡲ۬لذِے يُزْجِے لَكُمُ ࡲ۬لْفُلْكَ فِے ࡴ۬لْبَحْرِ لِتَبْتَغُواْ مِن فَضْلِهِۦٓ࣌ إِنَّهُۥ كَانَ بِكُمْ رَحِيماࣰ࣌', 'ربكم ࡲلذے يزجے لكم ࡲلفلك فے ࡴلبحر لتبتغوا من فضله࣌ إنه كان بكم رحيما࣌', NULL, 288, 'local:warsh-text.json'),
  ('warsh-17-67', 'warsh', 17, 67, 'وَإِذَا مَسَّكُمُ ࡲ۬لضُّرُّ فِے ࡴ۬لْبَحْرِ ضَلَّ مَن تَدْعُونَ إِلَّآ إِيَّاهُ࣌ فَلَمَّا نَجّٜيٰكُمُۥٓ إِلَى ࡰ۬لْبَرِّ أَعْرَضْتُمْ࣌ وَكَانَ ࡰ۬لِانسَٰنُ كَفُوراً࣌', 'وإذا مسكم ࡲلضر فے ࡴلبحر ضل من تدعون إلا إياه࣌ فلما نجيكم إلى ࡰلبر أعرضتم࣌ وكان ࡰلانسن كفورا࣌', NULL, 289, 'local:warsh-text.json'),
  ('warsh-17-68', 'warsh', 17, 68, 'ࡰفَأَمِنتُمُۥٓ أَنْ يَّخْسِفَ بِكُمْ جَانِبَ ࡰ۬لْبَرِّ أَوْ يُرْسِلَ عَلَيْكُمْ حَاصِباࣰ ثُمَّ لَا تَجِدُواْ لَكُمْ وَكِيلاً', 'ࡰفأمنتم أن يخسف بكم جانب ࡰلبر أو يرسل عليكم حاصبا ثم لا تجدوا لكم وكيلا', NULL, 289, 'local:warsh-text.json'),
  ('warsh-17-69', 'warsh', 17, 69, 'ࡰمَ ࡰمِنتُمُۥٓ أَنْ يُّعِيدَكُمْ فِيهِ تَارَةً ࡳخْرٜىٰ فَيُرْسِلَ عَلَيْكُمْ قَاصِفاࣰ مِّنَ ࡰ۬لرِّيحِ فَيُغْرِقَكُم بِمَا كَفَرْتُمْ ثُمَّ لَا تَجِدُواْ لَكُمْ عَلَيْنَا بِهِۦ تَبِيعاࣰ࣌', 'ࡰم ࡰمنتم أن يعيدكم فيه تارة ࡳخرى فيرسل عليكم قاصفا من ࡰلريح فيغرقكم بما كفرتم ثم لا تجدوا لكم علينا به تبيعا࣌', NULL, 289, 'local:warsh-text.json'),
  ('warsh-17-70', 'warsh', 17, 70, '۞ وَلَقَدْ كَرَّمْنَا بَنِےٓ ءَادَمَ وَحَمَلْنَٰهُمْ فِے ࡴ۬لْبَرِّ وَالْبَحْرِ وَرَزَقْنَٰهُم مِّنَ ࡰ۬لطَّيِّبَٰتِ وَفَضَّلْنَٰهُمْ عَلَىٰ كَثِيرࣲ مِّمَّنْ خَلَقْنَا تَفْضِيلاࣰ࣌', 'ولقد كرمنا بنے ءادم وحملنهم فے ࡴلبر والبحر ورزقنهم من ࡰلطيبت وفضلنهم على كثير ممن خلقنا تفضيلا࣌', NULL, 289, 'local:warsh-text.json'),
  ('warsh-17-71', 'warsh', 17, 71, 'يَوْمَ نَدْعُواْ كُلَّ أُنَاسِۢ بِإِمَٰمِهِمْ࣌ فَمَنُ ࡳوتِيَ كِتَٰبَهُۥ بِيَمِينِهِۦ فَأُوْلَٰٓئِكَ يَقْرَءُونَ كِتَٰبَهُمْ وَلَا يُظْلَمُونَ فَتِيلاࣰ࣌', 'يوم ندعوا كل أناس بإممهم࣌ فمن ࡳوتي كتبه بيمينه فأولئك يقرءون كتبهم ولا يظلمون فتيلا࣌', NULL, 289, 'local:warsh-text.json'),
  ('warsh-17-72', 'warsh', 17, 72, 'وَمَن كَانَ فِے هَٰذِهِۦٓ أَعْمٜىٰ فَهُوَ فِے ࡴ۬لَاخِرَةِ أَعْمٜىٰ وَأَضَلُّ سَبِيلاࣰ࣌', 'ومن كان فے هذه أعمى فهو فے ࡴلاخرة أعمى وأضل سبيلا࣌', NULL, 289, 'local:warsh-text.json'),
  ('warsh-17-73', 'warsh', 17, 73, 'وَإِن كَادُواْ لَيَفْتِنُونَكَ عَنِ ࡴ۬لذِےٓ أَوْحَيْنَآ إِلَيْكَ لِتَفْتَرِيَ عَلَيْنَا غَيْرَهُۥ࣌ وَإِذاࣰ لَّاتَّخَذُوكَ خَلِيلاࣰ࣌', 'وإن كادوا ليفتنونك عن ࡴلذے أوحينا إليك لتفتري علينا غيره࣌ وإذا لاتخذوك خليلا࣌', NULL, 289, 'local:warsh-text.json'),
  ('warsh-17-74', 'warsh', 17, 74, 'وَلَوْلَآ أَن ثَبَّتْنَٰكَ لَقَدْ كِدتَّ تَرْكَنُ إِلَيْهِمْ شَيْـٔاࣰ قَلِيلاً࣌', 'ولولا أن ثبتنك لقد كدت تركن إليهم شيا قليلا࣌', NULL, 289, 'local:warsh-text.json'),
  ('warsh-17-75', 'warsh', 17, 75, 'ࡴذاࣰ لَّأَذَقْنَٰكَ ضِعْفَ ࡰ۬لْحَيَوٰةِ وَضِعْفَ ࡰ۬لْمَمَاتِ ثُمَّ لَا تَجِدُ لَكَ عَلَيْنَا نَصِيراࣰ࣌', 'ࡴذا لأذقنك ضعف ࡰلحيوة وضعف ࡰلممات ثم لا تجد لك علينا نصيرا࣌', NULL, 289, 'local:warsh-text.json'),
  ('warsh-17-76', 'warsh', 17, 76, 'وَإِن كَادُواْ لَيَسْتَفِزُّونَكَ مِنَ ࡰ۬لَارْضِ لِيُخْرِجُوكَ مِنْهَا࣌ وَإِذاࣰ لَّا يَلْبَثُونَ خَلْفَكَ إِلَّا قَلِيلاࣰ࣌', 'وإن كادوا ليستفزونك من ࡰلارض ليخرجوك منها࣌ وإذا لا يلبثون خلفك إلا قليلا࣌', NULL, 290, 'local:warsh-text.json'),
  ('warsh-17-77', 'warsh', 17, 77, 'سُنَّةَ مَن قَدَ ࡰرْسَلْنَا قَبْلَكَ مِن رُّسُلِنَا࣌ وَلَا تَجِدُ لِسُنَّتِنَا تَحْوِيلاً࣌', 'سنة من قد ࡰرسلنا قبلك من رسلنا࣌ ولا تجد لسنتنا تحويلا࣌', NULL, 290, 'local:warsh-text.json'),
  ('warsh-17-78', 'warsh', 17, 78, 'ࡰقِمِ ࡴ۬لصَّلَوٰةَ لِدُلُوكِ ࡴ۬لشَّمْسِ إِلَىٰ غَسَقِ ࡴ۬ليْلِ وَقُرْءَانَ ࡰ۬لْفَجْرِ࣌ إِنَّ قُرْءَانَ ࡰ۬لْفَجْرِ كَانَ مَشْهُوداࣰ࣌', 'ࡰقم ࡴلصلوة لدلوك ࡴلشمس إلى غسق ࡴليل وقرءان ࡰلفجر࣌ إن قرءان ࡰلفجر كان مشهودا࣌', NULL, 290, 'local:warsh-text.json'),
  ('warsh-17-79', 'warsh', 17, 79, 'وَمِنَ ࡰ۬ليْلِ فَتَهَجَّدْ بِهِۦ نَافِلَةࣰ لَّكَ عَسٜىٰٓ أَنْ يَّبْعَثَكَ رَبُّكَ مَقَاماࣰ مَّحْمُوداࣰ࣌', 'ومن ࡰليل فتهجد به نافلة لك عسى أن يبعثك ربك مقاما محمودا࣌', NULL, 290, 'local:warsh-text.json'),
  ('warsh-17-80', 'warsh', 17, 80, 'وَقُل رَّبِّ أَدْخِلْنِے مُدْخَلَ صِدْقࣲ وَأَخْرِجْنِے مُخْرَجَ صِدْقࣲ وَاجْعَل لِّے مِن لَّدُنكَ سُلْطَٰناࣰ نَّصِيراࣰ࣌', 'وقل رب أدخلنے مدخل صدق وأخرجنے مخرج صدق واجعل لے من لدنك سلطنا نصيرا࣌', NULL, 290, 'local:warsh-text.json'),
  ('warsh-17-81', 'warsh', 17, 81, 'وَقُلْ جَآءَ ࡰ۬لْحَقُّ وَزَهَقَ ࡰ۬لْبَٰطِلُ࣌ إِنَّ ࡰ۬لْبَٰطِلَ كَانَ زَهُوقاࣰ࣌', 'وقل جاء ࡰلحق وزهق ࡰلبطل࣌ إن ࡰلبطل كان زهوقا࣌', NULL, 290, 'local:warsh-text.json'),
  ('warsh-17-82', 'warsh', 17, 82, 'وَنُنَزِّلُ مِنَ ࡰ۬لْقُرْءَانِ مَا هُوَ شِفَآءࣱ وَرَحْمَةࣱ لِّلْمُومِنِينَ࣌ وَلَا يَزِيدُ ࡲ۬لظَّٰلِمِينَ إِلَّا خَسَاراࣰ࣌', 'وننزل من ࡰلقرءان ما هو شفاء ورحمة للمومنين࣌ ولا يزيد ࡲلظلمين إلا خسارا࣌', NULL, 290, 'local:warsh-text.json'),
  ('warsh-17-83', 'warsh', 17, 83, 'وَإِذَآ أَنْعَمْنَا عَلَى ࡰ۬لِانسَٰنِ أَعْرَضَ وَنَـٜٔا بِجَانِبِهِۦ࣌ وَإِذَا مَسَّهُ ࡲ۬لشَّرُّ كَانَ يَـُٔوساࣰ࣌', 'وإذا أنعمنا على ࡰلانسن أعرض ونا بجانبه࣌ وإذا مسه ࡲلشر كان يوسا࣌', NULL, 290, 'local:warsh-text.json'),
  ('warsh-17-84', 'warsh', 17, 84, 'قُلْ كُلࣱّ يَعْمَلُ عَلَىٰ شَاكِلَتِهِۦ فَرَبُّكُمُۥٓ أَعْلَمُ بِمَنْ هُوَ أَهْدٜىٰ سَبِيلاࣰ࣌', 'قل كل يعمل على شاكلته فربكم أعلم بمن هو أهدى سبيلا࣌', NULL, 290, 'local:warsh-text.json'),
  ('warsh-17-85', 'warsh', 17, 85, '۞ وَيَسْـَٔلُونَكَ عَنِ ࡴ۬لرُّوحِ࣌ قُلِ ࡴ۬لرُّوحُ مِنَ ࡰمْرِ رَبِّے وَمَآ أُوتِيتُم مِّنَ ࡰ۬لْعِلْمِ إِلَّا قَلِيلاࣰ࣌', 'ويسلونك عن ࡴلروح࣌ قل ࡴلروح من ࡰمر ربے وما أوتيتم من ࡰلعلم إلا قليلا࣌', NULL, 290, 'local:warsh-text.json'),
  ('warsh-17-86', 'warsh', 17, 86, 'وَلَئِن شِئْنَا لَنَذْهَبَنَّ بِالذِےٓ أَوْحَيْنَآ إِلَيْكَ ثُمَّ لَا تَجِدُ لَكَ بِهِۦ عَلَيْنَا وَكِيلاً', 'ولئن شئنا لنذهبن بالذے أوحينا إليك ثم لا تجد لك به علينا وكيلا', NULL, 290, 'local:warsh-text.json'),
  ('warsh-17-87', 'warsh', 17, 87, 'ࡴلَّا رَحْمَةࣰ مِّن رَّبِّكَ࣌ إِنَّ فَضْلَهُۥ كَانَ عَلَيْكَ كَبِيراࣰ࣌', 'ࡴلا رحمة من ربك࣌ إن فضله كان عليك كبيرا࣌', NULL, 291, 'local:warsh-text.json'),
  ('warsh-17-88', 'warsh', 17, 88, 'قُل لَّئِنِ ࡴٜجْتَمَعَتِ ࡴ۬لِانسُ وَالْجِنُّ عَلَىٰٓ أَنْ يَّاتُواْ بِمِثْلِ هَٰذَا ࡰ۬لْقُرْءَانِ لَا يَاتُونَ بِمِثْلِهِۦ وَلَوْ كَانَ بَعْضُهُمْ لِبَعْضࣲ ظَهِيراࣰ࣌', 'قل لئن ࡴجتمعت ࡴلانس والجن على أن ياتوا بمثل هذا ࡰلقرءان لا ياتون بمثله ولو كان بعضهم لبعض ظهيرا࣌', NULL, 291, 'local:warsh-text.json'),
  ('warsh-17-89', 'warsh', 17, 89, 'وَلَقَدْ صَرَّفْنَا لِلنَّاسِ فِے هَٰذَا ࡰ۬لْقُرْءَانِ مِن كُلِّ مَثَلࣲ فَأَبٜىٰٓ أَكْثَرُ ࡲ۬لنَّاسِ إِلَّا كُفُوراࣰ࣌', 'ولقد صرفنا للناس فے هذا ࡰلقرءان من كل مثل فأبى أكثر ࡲلناس إلا كفورا࣌', NULL, 291, 'local:warsh-text.json'),
  ('warsh-17-90', 'warsh', 17, 90, 'وَقَالُواْ لَن نُّومِنَ لَكَ حَتَّىٰ تُفَجِّرَ لَنَا مِنَ ࡰ۬لَارْضِ يَنۢبُوعاً', 'وقالوا لن نومن لك حتى تفجر لنا من ࡰلارض ينبوعا', NULL, 291, 'local:warsh-text.json'),
  ('warsh-17-91', 'warsh', 17, 91, 'ࡰوْ تَكُونَ لَكَ جَنَّةࣱ مِّن نَّخِيلࣲ وَعِنَبࣲ فَتُفَجِّرَ ࡰ۬لَانْهَٰرَ خِلَٰلَهَا تَفْجِيراً', 'ࡰو تكون لك جنة من نخيل وعنب فتفجر ࡰلانهر خللها تفجيرا', NULL, 291, 'local:warsh-text.json'),
  ('warsh-17-92', 'warsh', 17, 92, 'ࡰوْ تُسْقِطَ ࡰ۬لسَّمَآءَ كَمَا زَعَمْتَ عَلَيْنَا كِسَفاً ࡰوْ تَاتِيَ بِاللَّهِ وَالْمَلَٰٓئِكَةِ قَبِيلاً', 'ࡰو تسقط ࡰلسماء كما زعمت علينا كسفا ࡰو تاتي بالله والملئكة قبيلا', NULL, 291, 'local:warsh-text.json'),
  ('warsh-17-93', 'warsh', 17, 93, 'ࡰوْ يَكُونَ لَكَ بَيْتࣱ مِّن زُخْرُفٍ ࡰوْ تَرْقٜىٰ فِے ࡴ۬لسَّمَآءِ وَلَن نُّومِنَ لِرُقِيِّكَ حَتَّىٰ تُنَزِّلَ عَلَيْنَا كِتَٰباࣰ نَّقْرَؤُهُۥ࣌ قُلْ سُبْحَٰنَ رَبِّے هَلْ كُنتُ إِلَّا بَشَراࣰ رَّسُولاࣰ࣌', 'ࡰو يكون لك بيت من زخرف ࡰو ترقى فے ࡴلسماء ولن نومن لرقيك حتى تنزل علينا كتبا نقرؤه࣌ قل سبحن ربے هل كنت إلا بشرا رسولا࣌', NULL, 291, 'local:warsh-text.json'),
  ('warsh-17-94', 'warsh', 17, 94, 'وَمَا مَنَعَ ࡰ۬لنَّاسَ أَنْ يُّومِنُوٓاْ إِذْ جَآءَهُمُ ࡲ۬لْهُدٜىٰٓ إِلَّآ أَن قَالُوٓاْ أَبَعَثَ ࡰ۬للَّهُ بَشَراࣰ رَّسُولاࣰ࣌', 'وما منع ࡰلناس أن يومنوا إذ جاءهم ࡲلهدى إلا أن قالوا أبعث ࡰلله بشرا رسولا࣌', NULL, 291, 'local:warsh-text.json'),
  ('warsh-17-95', 'warsh', 17, 95, 'قُل لَّوْ كَانَ فِے ࡴ۬لَارْضِ مَلَٰٓئِكَةࣱ يَمْشُونَ مُطْمَئِنِّينَ لَنَزَّلْنَا عَلَيْهِم مِّنَ ࡰ۬لسَّمَآءِ مَلَكاࣰ رَّسُولاࣰ࣌', 'قل لو كان فے ࡴلارض ملئكة يمشون مطمئنين لنزلنا عليهم من ࡰلسماء ملكا رسولا࣌', NULL, 291, 'local:warsh-text.json'),
  ('warsh-17-96', 'warsh', 17, 96, 'قُلْ كَفٜىٰ بِاللَّهِ شَهِيداَۢ بَيْنِے وَبَيْنَكُمُۥٓ࣌ إِنَّهُۥ كَانَ بِعِبَادِهِۦ خَبِيراَۢ بَصِيراࣰ࣌', 'قل كفى بالله شهيدا بينے وبينكم࣌ إنه كان بعباده خبيرا بصيرا࣌', NULL, 291, 'local:warsh-text.json'),
  ('warsh-17-97', 'warsh', 17, 97, 'وَمَنْ يَّهْدِ ࡴ۬للَّهُ فَهُوَ ࡰ۬لْمُهْتَدِۦ࣌ وَمَنْ يُّضْلِلْ فَلَن تَجِدَ لَهُمُۥٓ أَوْلِيَآءَ مِن دُونِهِۦ࣌ وَنَحْشُرُهُمْ يَوْمَ ࡰ۬لْقِيَٰمَةِ عَلَىٰ وُجُوهِهِمْ عُمْياࣰ وَبُكْماࣰ وَصُمّاࣰ࣌ مَّأْوٜيٰهُمْ جَهَنَّمُ࣌ كُلَّمَا خَبَتْ زِدْنَٰهُمْ سَعِيراࣰ࣌', 'ومن يهد ࡴلله فهو ࡰلمهتد࣌ ومن يضلل فلن تجد لهم أولياء من دونه࣌ ونحشرهم يوم ࡰلقيمة على وجوههم عميا وبكما وصما࣌ مأويهم جهنم࣌ كلما خبت زدنهم سعيرا࣌', NULL, 292, 'local:warsh-text.json'),
  ('warsh-17-98', 'warsh', 17, 98, 'ذَٰلِكَ جَزَآؤُهُم بِأَنَّهُمْ كَفَرُواْ بِـَٔايَٰتِنَا وَقَالُوٓاْ أَࢇذَا كُنَّا عِظَٰماࣰ وَرُفَٰتاً ࡴنَّا لَمَبْعُوثُونَ خَلْقاࣰ جَدِيداً࣌', 'ذلك جزاؤهم بأنهم كفروا بايتنا وقالوا أࢇذا كنا عظما ورفتا ࡴنا لمبعوثون خلقا جديدا࣌', NULL, 292, 'local:warsh-text.json'),
  ('warsh-17-99', 'warsh', 17, 99, '۞ ࡰوَلَمْ يَرَوَاْ ࡰنَّ ࡰ۬للَّهَ ࡰ۬لذِے خَلَقَ ࡰ۬لسَّمَٰوَٰتِ وَالَارْضَ قَادِرٌ عَلَىٰٓ أَنْ يَّخْلُقَ مِثْلَهُمْ وَجَعَلَ لَهُمُۥٓ أَجَلاࣰ لَّا رَيْبَ فِيهِ࣌ فَأَبَى ࡰ۬لظَّٰلِمُونَ إِلَّا كُفُوراࣰ࣌', 'ࡰولم يروا ࡰن ࡰلله ࡰلذے خلق ࡰلسموت والارض قادر على أن يخلق مثلهم وجعل لهم أجلا لا ريب فيه࣌ فأبى ࡰلظلمون إلا كفورا࣌', NULL, 292, 'local:warsh-text.json'),
  ('warsh-17-100', 'warsh', 17, 100, 'قُل لَّوَ ࡰنتُمْ تَمْلِكُونَ خَزَآئِنَ رَحْمَةِ رَبِّيَ إِذاࣰ لَّأَمْسَكْتُمْ خَشْيَةَ ࡰ۬لِانفَاقِ࣌ وَكَانَ ࡰ۬لِانسَٰنُ قَتُوراࣰ࣌', 'قل لو ࡰنتم تملكون خزائن رحمة ربي إذا لأمسكتم خشية ࡰلانفاق࣌ وكان ࡰلانسن قتورا࣌', NULL, 292, 'local:warsh-text.json'),
  ('warsh-17-101', 'warsh', 17, 101, 'وَلَقَدَ اٰتَيْنَا مُوسٜىٰ تِسْعَ ءَايَٰتِۢ بَيِّنَٰتࣲ࣌ فَسْـَٔلْ بَنِےٓ إِسْرَآءِيلَ إِذْ جَآءَهُمْ فَقَالَ لَهُۥ فِرْعَوْنُ إِنِّے لَأَظُنُّكَ يَٰمُوسٜىٰ مَسْحُوراࣰ࣌', 'ولقد اتينا موسى تسع ءايت بينت࣌ فسل بنے إسراءيل إذ جاءهم فقال له فرعون إنے لأظنك يموسى مسحورا࣌', NULL, 292, 'local:warsh-text.json'),
  ('warsh-17-102', 'warsh', 17, 102, 'قَالَ لَقَدْ عَلِمْتَ مَآ أَنزَلَ هَٰٓؤُلَآءِ الَّا رَبُّ ࡲ۬لسَّمَٰوَٰتِ وَالَارْضِ بَصَآئِرَ࣌ وَإِنِّے لَأَظُنُّكَ يَٰفِرْعَوْنُ مَثْبُوراࣰ࣌', 'قال لقد علمت ما أنزل هؤلاء الا رب ࡲلسموت والارض بصائر࣌ وإنے لأظنك يفرعون مثبورا࣌', NULL, 292, 'local:warsh-text.json'),
  ('warsh-17-103', 'warsh', 17, 103, 'فَأَرَادَ أَنْ يَّسْتَفِزَّهُم مِّنَ ࡰ۬لَارْضِ فَأَغْرَقْنَٰهُ وَمَن مَّعَهُۥ جَمِيعاࣰ࣌', 'فأراد أن يستفزهم من ࡰلارض فأغرقنه ومن معه جميعا࣌', NULL, 292, 'local:warsh-text.json'),
  ('warsh-17-104', 'warsh', 17, 104, 'وَقُلْنَا مِنۢ بَعْدِهِۦ لِبَنِےٓ إِسْرَآءِيلَ ࡸَسْكُنُواْ ࡲ۬لَارْضَ࣌ فَإِذَا جَآءَ وَعْدُ ࡲ۬لَاخِرَةِ جِئْنَا بِكُمْ لَفِيفاࣰ࣌', 'وقلنا من بعده لبنے إسراءيل ࡸسكنوا ࡲلارض࣌ فإذا جاء وعد ࡲلاخرة جئنا بكم لفيفا࣌', NULL, 292, 'local:warsh-text.json'),
  ('warsh-17-105', 'warsh', 17, 105, 'وَبِالْحَقِّ أَنزَلْنَٰهُ࣌ وَبِالْحَقِّ نَزَلَ࣌ وَمَآ أَرْسَلْنَٰكَ إِلَّا مُبَشِّراࣰ وَنَذِيراࣰ࣌', 'وبالحق أنزلنه࣌ وبالحق نزل࣌ وما أرسلنك إلا مبشرا ونذيرا࣌', NULL, 293, 'local:warsh-text.json'),
  ('warsh-17-106', 'warsh', 17, 106, 'وَقُرْءَاناࣰ فَرَقْنَٰهُ لِتَقْرَأَهُۥ عَلَى ࡰ۬لنَّاسِ عَلَىٰ مُكْثࣲ࣌ وَنَزَّلْنَٰهُ تَنزِيلاࣰ࣌', 'وقرءانا فرقنه لتقرأه على ࡰلناس على مكث࣌ ونزلنه تنزيلا࣌', NULL, 293, 'local:warsh-text.json'),
  ('warsh-17-107', 'warsh', 17, 107, 'قُلَ اٰمِنُواْ بِهِۦٓ أَوْ لَا تُومِنُوٓاْ࣌ إِنَّ ࡰ۬لذِينَ أُوتُواْ ࡲ۬لْعِلْمَ مِن قَبْلِهِۦٓ إِذَا يُتْلٜىٰ عَلَيْهِمْ يَخِرُّونَ لِلَاذْقَانِ سُجَّداࣰ وَيَقُولُونَ سُبْحَٰنَ رَبِّنَآ إِن كَانَ وَعْدُ رَبِّنَا لَمَفْعُولاࣰ࣌', 'قل امنوا به أو لا تومنوا࣌ إن ࡰلذين أوتوا ࡲلعلم من قبله إذا يتلى عليهم يخرون للاذقان سجدا ويقولون سبحن ربنا إن كان وعد ربنا لمفعولا࣌', NULL, 293, 'local:warsh-text.json'),
  ('warsh-17-108', 'warsh', 17, 108, 'وَيَخِرُّونَ لِلَاذْقَانِ يَبْكُونَ وَيَزِيدُهُمْ خُشُوعاࣰ࣌۩', 'ويخرون للاذقان يبكون ويزيدهم خشوعا࣌', NULL, 293, 'local:warsh-text.json'),
  ('warsh-17-109', 'warsh', 17, 109, 'قُلُ ࡲ࢈دْعُواْ ࡲ۬للَّهَ أَوُ ࡲ࢈دْعُواْ ࡲ۬لرَّحْمَٰنَ࣌ أَيّاࣰ مَّا تَدْعُواْ فَلَهُ ࡲ۬لَاسْمَآءُ ࡲ۬لْحُسْنٜىٰ࣌ وَلَا تَجْهَرْ بِصَلَاتِكَ وَلَا تُخَافِتْ بِهَا وَابْتَغِ بَيْنَ ذَٰلِكَ سَبِيلاࣰ࣌', 'قل ࡲ࢈دعوا ࡲلله أو ࡲ࢈دعوا ࡲلرحمن࣌ أيا ما تدعوا فله ࡲلاسماء ࡲلحسنى࣌ ولا تجهر بصلاتك ولا تخافت بها وابتغ بين ذلك سبيلا࣌', NULL, 293, 'local:warsh-text.json'),
  ('warsh-17-110', 'warsh', 17, 110, 'وَقُلِ ࡴ۬لْحَمْدُ لِلهِ ࡴ۬لذِے لَمْ يَتَّخِذْ وَلَداࣰ وَلَمْ يَكُن لَّهُۥ شَرِيكࣱ فِے ࡴ۬لْمُلْكِ وَلَمْ يَكُن لَّهُۥ وَلِيࣱّ مِّنَ ࡰ۬لذُّلِّ࣌ وَكَبِّرْهُ تَكْبِيراً࣌', 'وقل ࡴلحمد لله ࡴلذے لم يتخذ ولدا ولم يكن له شريك فے ࡴلملك ولم يكن له ولي من ࡰلذل࣌ وكبره تكبيرا࣌', NULL, 293, 'local:warsh-text.json'),
  ('warsh-18-1', 'warsh', 18, 1, 'ࡴ۬لْحَمْدُ لِلهِ ࡴ۬لذِےٓ أَنزَلَ عَلَىٰ عَبْدِهِ ࡴ۬لْكِتَٰبَ وَلَمْ يَجْعَل لَّهُۥ عِوَجاࣰ࣌', 'ࡴلحمد لله ࡴلذے أنزل على عبده ࡴلكتب ولم يجعل له عوجا࣌', NULL, 293, 'local:warsh-text.json'),
  ('warsh-18-2', 'warsh', 18, 2, 'قَيِّماࣰ لِّيُنذِرَ بَأْساࣰ شَدِيداࣰ مِّن لَّدُنْهُ وَيُبَشِّرَ ࡰ۬لْمُومِنِينَ ࡰ۬لذِينَ يَعْمَلُونَ ࡰ۬لصَّٰلِحَٰتِ أَنَّ لَهُمُۥٓ أَجْراً حَسَناࣰ', 'قيما لينذر بأسا شديدا من لدنه ويبشر ࡰلمومنين ࡰلذين يعملون ࡰلصلحت أن لهم أجرا حسنا', NULL, 293, 'local:warsh-text.json'),
  ('warsh-18-3', 'warsh', 18, 3, 'مَّٰكِثِينَ فِيهِ أَبَداࣰ', 'مكثين فيه أبدا', NULL, 293, 'local:warsh-text.json'),
  ('warsh-18-4', 'warsh', 18, 4, 'وَيُنذِرَ ࡰ۬لذِينَ قَالُواْ ࡲٜتَّخَذَ ࡰ۬للَّهُ وَلَداࣰ࣌', 'وينذر ࡰلذين قالوا ࡲتخذ ࡰلله ولدا࣌', NULL, 293, 'local:warsh-text.json'),
  ('warsh-18-5', 'warsh', 18, 5, 'مَّا لَهُم بِهِۦ مِنْ عِلْمࣲ وَلَا لِأٓبَآئِهِمْ࣌ كَبُرَتْ كَلِمَةࣰ تَخْرُجُ مِنَ ࡰفْوَٰهِهِمُۥٓ࣌ إِنْ يَّقُولُونَ إِلَّا كَذِباࣰ࣌', 'ما لهم به من علم ولا لأبائهم࣌ كبرت كلمة تخرج من ࡰفوههم࣌ إن يقولون إلا كذبا࣌', NULL, 294, 'local:warsh-text.json'),
  ('warsh-18-6', 'warsh', 18, 6, 'فَلَعَلَّكَ بَٰخِعࣱ نَّفْسَكَ عَلَىٰٓ ءَاثٜـٰرِهِمُۥٓ إِن لَّمْ يُومِنُواْ بِهَٰذَا ࡰ۬لْحَدِيثِ أَسَفاً࣌', 'فلعلك بخع نفسك على ءاثرهم إن لم يومنوا بهذا ࡰلحديث أسفا࣌', NULL, 294, 'local:warsh-text.json'),
  ('warsh-18-7', 'warsh', 18, 7, 'ࡴنَّا جَعَلْنَا مَا عَلَى ࡰ۬لَارْضِ زِينَةࣰ لَّهَا لِنَبْلُوَهُمُۥٓ أَيُّهُمُۥٓ أَحْسَنُ عَمَلاࣰ࣌', 'ࡴنا جعلنا ما على ࡰلارض زينة لها لنبلوهم أيهم أحسن عملا࣌', NULL, 294, 'local:warsh-text.json'),
  ('warsh-18-8', 'warsh', 18, 8, 'وَإِنَّا لَجَٰعِلُونَ مَا عَلَيْهَا صَعِيداࣰ جُرُزاً࣌', 'وإنا لجعلون ما عليها صعيدا جرزا࣌', NULL, 294, 'local:warsh-text.json'),
  ('warsh-18-9', 'warsh', 18, 9, 'ࡰمْ حَسِبْتَ أَنَّ أَصْحَٰبَ ࡰ۬لْكَهْفِ وَالرَّقِيمِ كَانُواْ مِنَ اٰيَٰتِنَا عَجَباً࣌', 'ࡰم حسبت أن أصحب ࡰلكهف والرقيم كانوا من ايتنا عجبا࣌', NULL, 294, 'local:warsh-text.json'),
  ('warsh-18-10', 'warsh', 18, 10, 'ࡴذَ ࡰوَى ࡰ۬لْفِتْيَةُ إِلَى ࡰ۬لْكَهْفِ فَقَالُواْ رَبَّنَآ ءَاتِنَا مِن لَّدُنكَ رَحْمَةࣰ وَهَيِّۓْ لَنَا مِنَ ࡰمْرِنَا رَشَداࣰ࣌', 'ࡴذ ࡰوى ࡰلفتية إلى ࡰلكهف فقالوا ربنا ءاتنا من لدنك رحمة وهيے لنا من ࡰمرنا رشدا࣌', NULL, 294, 'local:warsh-text.json'),
  ('warsh-18-11', 'warsh', 18, 11, 'فَضَرَبْنَا عَلَىٰٓ ءَاذَانِهِمْ فِے ࡴ۬لْكَهْفِ سِنِينَ عَدَداࣰ', 'فضربنا على ءاذانهم فے ࡴلكهف سنين عددا', NULL, 294, 'local:warsh-text.json'),
  ('warsh-18-12', 'warsh', 18, 12, 'ثُمَّ بَعَثْنَٰهُمْ لِنَعْلَمَ أَيُّ ࡲ۬لْحِزْبَيْنِ أَحْصٜىٰ لِمَا لَبِثُوٓاْ أَمَداࣰ࣌', 'ثم بعثنهم لنعلم أي ࡲلحزبين أحصى لما لبثوا أمدا࣌', NULL, 294, 'local:warsh-text.json'),
  ('warsh-18-13', 'warsh', 18, 13, 'نَّحْنُ نَقُصُّ عَلَيْكَ نَبَأَهُم بِالْحَقِّ࣌ إِنَّهُمْ فِتْيَةٌ اٰمَنُواْ بِرَبِّهِمْ وَزِدْنَٰهُمْ هُدىࣰ࣌', 'نحن نقص عليك نبأهم بالحق࣌ إنهم فتية امنوا بربهم وزدنهم هدى࣌', NULL, 294, 'local:warsh-text.json'),
  ('warsh-18-14', 'warsh', 18, 14, 'وَرَبَطْنَا عَلَىٰ قُلُوبِهِمُۥٓ إِذْ قَامُواْ فَقَالُواْ رَبُّنَا رَبُّ ࡲ۬لسَّمَٰوَٰتِ وَالَارْضِ لَن نَّدْعُوَاْ مِن دُونِهِۦٓ إِلَٰهاࣰ لَّقَدْ قُلْنَآ إِذاࣰ شَطَطاً࣌', 'وربطنا على قلوبهم إذ قاموا فقالوا ربنا رب ࡲلسموت والارض لن ندعوا من دونه إلها لقد قلنا إذا شططا࣌', NULL, 294, 'local:warsh-text.json'),
  ('warsh-18-15', 'warsh', 18, 15, 'هَٰٓؤُلَآءِ قَوْمُنَا ࡰٜتَّخَذُواْ مِن دُونِهِۦٓ ءَالِهَةࣰ لَّوْلَا يَاتُونَ عَلَيْهِم بِسُلْطَٰنِۢ بَيِّنࣲ࣌ فَمَنَ ࡰظْلَمُ مِمَّنِ ࡴٜفْتَرٜىٰ عَلَى ࡰ۬للَّهِ كَذِباࣰ࣌', 'هؤلاء قومنا ࡰتخذوا من دونه ءالهة لولا ياتون عليهم بسلطن بين࣌ فمن ࡰظلم ممن ࡴفترى على ࡰلله كذبا࣌', NULL, 294, 'local:warsh-text.json'),
  ('warsh-18-16', 'warsh', 18, 16, 'وَإِذِ ࡴٜعْتَزَلْتُمُوهُمْ وَمَا يَعْبُدُونَ إِلَّا ࡰ۬للَّهَ فَأْوُۥٓاْ إِلَى ࡰ۬لْكَهْفِ يَنشُرْ لَكُمْ رَبُّكُم مِّن رَّحْمَتِهِۦ وَيُهَيِّۓْ لَكُم مِّنَ ࡰمْرِكُم مَّرْفِقاࣰ࣌', 'وإذ ࡴعتزلتموهم وما يعبدون إلا ࡰلله فأوا إلى ࡰلكهف ينشر لكم ربكم من رحمته ويهيے لكم من ࡰمركم مرفقا࣌', NULL, 295, 'local:warsh-text.json'),
  ('warsh-18-17', 'warsh', 18, 17, '۞ وَتَرَى ࡰ۬لشَّمْسَ إِذَا طَلَعَت تَّزَّٰوَرُ عَن كَهْفِهِمْ ذَاتَ ࡰ۬لْيَمِينِ وَإِذَا غَرَبَت تَّقْرِضُهُمْ ذَاتَ ࡰ۬لشِّمَالِ وَهُمْ فِے فَجْوَةࣲ مِّنْهُ࣌ ذَٰلِكَ مِنَ اٰيَٰتِ ࡴ۬للَّهِ࣌ مَنْ يَّهْدِ ࡴ۬للَّهُ فَهُوَ ࡰ۬لْمُهْتَدِۦ࣌ وَمَنْ يُّضْلِلْ فَلَن تَجِدَ لَهُۥ وَلِيّاࣰ مُّرْشِداࣰ࣌', 'وترى ࡰلشمس إذا طلعت تزور عن كهفهم ذات ࡰليمين وإذا غربت تقرضهم ذات ࡰلشمال وهم فے فجوة منه࣌ ذلك من ايت ࡴلله࣌ من يهد ࡴلله فهو ࡰلمهتد࣌ ومن يضلل فلن تجد له وليا مرشدا࣌', NULL, 295, 'local:warsh-text.json'),
  ('warsh-18-18', 'warsh', 18, 18, 'وَتَحْسِبُهُمُۥٓ أَيْقَاظاࣰ وَهُمْ رُقُودࣱ࣌ وَنُقَلِّبُهُمْ ذَاتَ ࡰ۬لْيَمِينِ وَذَاتَ ࡰ۬لشِّمَالِ وَكَلْبُهُم بَٰسِطࣱ ذِرَاعَيْهِ بِالْوَصِيدِ࣌ لَوِ ࡴٜطَّلَعْتَ عَلَيْهِمْ لَوَلَّيْتَ مِنْهُمْ فِرَاراࣰ وَلَمُلِّئْتَ مِنْهُمْ رُعْباࣰ࣌', 'وتحسبهم أيقاظا وهم رقود࣌ ونقلبهم ذات ࡰليمين وذات ࡰلشمال وكلبهم بسط ذراعيه بالوصيد࣌ لو ࡴطلعت عليهم لوليت منهم فرارا ولملئت منهم رعبا࣌', NULL, 295, 'local:warsh-text.json'),
  ('warsh-18-19', 'warsh', 18, 19, 'وَكَذَٰلِكَ بَعَثْنَٰهُمْ لِيَتَسَآءَلُواْ بَيْنَهُمْ࣌ قَالَ قَآئِلࣱ مِّنْهُمْ كَمْ لَبِثْتُمْ࣌ قَالُواْ لَبِثْنَا يَوْماً ࡰوْ بَعْضَ يَوْمࣲ࣌ قَالُواْ رَبُّكُمُۥٓ أَعْلَمُ بِمَا لَبِثْتُمْ فَابْعَثُوٓاْ أَحَدَكُم بِوَرِقِكُمْ هَٰذِهِۦٓ إِلَى ࡰ۬لْمَدِينَةِ فَلْيَنظُرَ ࡰيُّهَآ أَزْكٜىٰ طَعَاماࣰ فَلْيَاتِكُم بِرِزْقࣲ مِّنْهُ وَلْيَتَلَطَّفْ࣌ وَلَا يُشْعِرَنَّ بِكُمُۥٓ أَحَداً࣌', 'وكذلك بعثنهم ليتساءلوا بينهم࣌ قال قائل منهم كم لبثتم࣌ قالوا لبثنا يوما ࡰو بعض يوم࣌ قالوا ربكم أعلم بما لبثتم فابعثوا أحدكم بورقكم هذه إلى ࡰلمدينة فلينظر ࡰيها أزكى طعاما فلياتكم برزق منه وليتلطف࣌ ولا يشعرن بكم أحدا࣌', NULL, 295, 'local:warsh-text.json'),
  ('warsh-18-20', 'warsh', 18, 20, 'ࡴنَّهُمُۥٓ إِنْ يَّظْهَرُواْ عَلَيْكُمْ يَرْجُمُوكُمُۥٓ أَوْ يُعِيدُوكُمْ فِے مِلَّتِهِمْ وَلَن تُفْلِحُوٓاْ إِذاً ࡰبَداࣰ࣌', 'ࡴنهم إن يظهروا عليكم يرجموكم أو يعيدوكم فے ملتهم ولن تفلحوا إذا ࡰبدا࣌', NULL, 295, 'local:warsh-text.json'),
  ('warsh-18-21', 'warsh', 18, 21, 'وَكَذَٰلِكَ أَعْثَرْنَا عَلَيْهِمْ لِيَعْلَمُوٓاْ أَنَّ وَعْدَ ࡰ۬للَّهِ حَقࣱّ وَأَنَّ ࡰ۬لسَّاعَةَ لَا رَيْبَ فِيهَآ࣌ إِذْ يَتَنَٰزَعُونَ بَيْنَهُمُۥٓ أَمْرَهُمْ فَقَالُواْ ࡲٜبْنُواْ عَلَيْهِم بُنْيَٰناࣰ࣌ رَّبُّهُمُۥٓ أَعْلَمُ بِهِمْ࣌ قَالَ ࡰ۬لذِينَ غَلَبُواْ عَلَىٰٓ أَمْرِهِمْ لَنَتَّخِذَنَّ عَلَيْهِم مَّسْجِداࣰ࣌', 'وكذلك أعثرنا عليهم ليعلموا أن وعد ࡰلله حق وأن ࡰلساعة لا ريب فيها࣌ إذ يتنزعون بينهم أمرهم فقالوا ࡲبنوا عليهم بنينا࣌ ربهم أعلم بهم࣌ قال ࡰلذين غلبوا على أمرهم لنتخذن عليهم مسجدا࣌', NULL, 296, 'local:warsh-text.json'),
  ('warsh-18-22', 'warsh', 18, 22, 'سَيَقُولُونَ ثَلَٰثَةࣱ رَّابِعُهُمْ كَلْبُهُمْ࣌ وَيَقُولُونَ خَمْسَةࣱ سَادِسُهُمْ كَلْبُهُمْ رَجْماَۢ بِالْغَيْبِ࣌ وَيَقُولُونَ سَبْعَةࣱ࣌ وَثَامِنُهُمْ كَلْبُهُمْ࣌ قُل رَّبِّيَ أَعْلَمُ بِعِدَّتِهِم࣌ مَّا يَعْلَمُهُمُۥٓ إِلَّا قَلِيلࣱ࣌', 'سيقولون ثلثة رابعهم كلبهم࣌ ويقولون خمسة سادسهم كلبهم رجما بالغيب࣌ ويقولون سبعة࣌ وثامنهم كلبهم࣌ قل ربي أعلم بعدتهم࣌ ما يعلمهم إلا قليل࣌', NULL, 296, 'local:warsh-text.json'),
  ('warsh-18-23', 'warsh', 18, 23, '۞ فَلَا تُمَارِ فِيهِمُۥٓ إِلَّا مِرَآءࣰ ظَٰهِراࣰ وَلَا تَسْتَفْتِ فِيهِم مِّنْهُمُۥٓ أَحَداࣰ࣌', 'فلا تمار فيهم إلا مراء ظهرا ولا تستفت فيهم منهم أحدا࣌', NULL, 296, 'local:warsh-text.json'),
  ('warsh-18-24', 'warsh', 18, 24, 'وَلَا تَقُولَنَّ لِشَاْےْءٍ ࡴنِّے فَاعِلࣱ ذَٰلِكَ غَداً ࡴلَّآ أَنْ يَّشَآءَ ࡰ۬للَّهُ࣌ وَاذْكُر رَّبَّكَ إِذَا نَسِيتَ࣌ وَقُلْ عَسٜىٰٓ أَنْ يَّهْدِيَنِۦ رَبِّے لِأَقْرَبَ مِنْ هَٰذَا رَشَداࣰ࣌', 'ولا تقولن لشاےء ࡴنے فاعل ذلك غدا ࡴلا أن يشاء ࡰلله࣌ واذكر ربك إذا نسيت࣌ وقل عسى أن يهدين ربے لأقرب من هذا رشدا࣌', NULL, 296, 'local:warsh-text.json'),
  ('warsh-18-25', 'warsh', 18, 25, 'وَلَبِثُواْ فِے كَهْفِهِمْ ثَلَٰثَ مِاْئَةࣲ سِنِينَ وَازْدَادُواْ تِسْعاࣰ࣌', 'ولبثوا فے كهفهم ثلث مائة سنين وازدادوا تسعا࣌', NULL, 296, 'local:warsh-text.json'),
  ('warsh-18-26', 'warsh', 18, 26, 'قُلِ ࡴ۬للَّهُ أَعْلَمُ بِمَا لَبِثُواْ࣌ لَهُۥ غَيْبُ ࡲ۬لسَّمَٰوَٰتِ وَالَارْضِ࣌ أَبْصِرْ بِهِۦ وَأَسْمِعْ࣌ مَا لَهُم مِّن دُونِهِۦ مِنْ وَّلِيࣲّ࣌ وَلَا يُشْرِكُ فِے حُكْمِهِۦٓ أَحَداࣰ࣌', 'قل ࡴلله أعلم بما لبثوا࣌ له غيب ࡲلسموت والارض࣌ أبصر به وأسمع࣌ ما لهم من دونه من ولي࣌ ولا يشرك فے حكمه أحدا࣌', NULL, 296, 'local:warsh-text.json'),
  ('warsh-18-27', 'warsh', 18, 27, 'وَاتْلُ مَآ أُوحِيَ إِلَيْكَ مِن كِتَابِ رَبِّكَ لَا مُبَدِّلَ لِكَلِمَٰتِهِۦ࣌ وَلَن تَجِدَ مِن دُونِهِۦ مُلْتَحَداࣰ࣌', 'واتل ما أوحي إليك من كتاب ربك لا مبدل لكلمته࣌ ولن تجد من دونه ملتحدا࣌', NULL, 296, 'local:warsh-text.json'),
  ('warsh-18-28', 'warsh', 18, 28, 'وَاصْبِرْ نَفْسَكَ مَعَ ࡰ۬لذِينَ يَدْعُونَ رَبَّهُم بِالْغَدَوٰةِ وَالْعَشِيِّ يُرِيدُونَ وَجْهَهُۥ࣌ وَلَا تَعْدُ عَيْنَٰكَ عَنْهُمْ تُرِيدُ زِينَةَ ࡰ۬لْحَيَوٰةِ ࡴ۬لدُّنْيٜا࣌ وَلَا تُطِعْ مَنَ ࡰغْفَلْنَا قَلْبَهُۥ عَن ذِكْرِنَا وَاتَّبَعَ هَوٜيٰهُ وَكَانَ أَمْرُهُۥ فُرُطاࣰ࣌', 'واصبر نفسك مع ࡰلذين يدعون ربهم بالغدوة والعشي يريدون وجهه࣌ ولا تعد عينك عنهم تريد زينة ࡰلحيوة ࡴلدنيا࣌ ولا تطع من ࡰغفلنا قلبه عن ذكرنا واتبع هويه وكان أمره فرطا࣌', NULL, 297, 'local:warsh-text.json'),
  ('warsh-18-29', 'warsh', 18, 29, 'وَقُلِ ࡴ۬لْحَقُّ مِن رَّبِّكُمْ فَمَن شَآءَ فَلْيُومِنْ وَّمَن شَآءَ فَلْيَكْفُرِ࣌ ࡴنَّآ أَعْتَدْنَا لِلظَّٰلِمِينَ نَاراً ࡰحَاطَ بِهِمْ سُرَادِقُهَا࣌ وَإِنْ يَّسْتَغِيثُواْ يُغَاثُواْ بِمَآءࣲ كَالْمُهْلِ يَشْوِے ࡴ۬لْوُجُوهَ࣌ بِيسَ ࡰ۬لشَّرَابُ࣌ وَسَآءَتْ مُرْتَفَقاً࣌', 'وقل ࡴلحق من ربكم فمن شاء فليومن ومن شاء فليكفر࣌ ࡴنا أعتدنا للظلمين نارا ࡰحاط بهم سرادقها࣌ وإن يستغيثوا يغاثوا بماء كالمهل يشوے ࡴلوجوه࣌ بيس ࡰلشراب࣌ وساءت مرتفقا࣌', NULL, 297, 'local:warsh-text.json'),
  ('warsh-18-30', 'warsh', 18, 30, '۞ ࡴنَّ ࡰ۬لذِينَ ءَامَنُواْ وَعَمِلُواْ ࡲ۬لصَّٰلِحَٰتِ إِنَّا لَا نُضِيعُ أَجْرَ مَنَ ࡰحْسَنَ عَمَلاً࣌', 'ࡴن ࡰلذين ءامنوا وعملوا ࡲلصلحت إنا لا نضيع أجر من ࡰحسن عملا࣌', NULL, 297, 'local:warsh-text.json'),
  ('warsh-18-31', 'warsh', 18, 31, 'ࡳوْلَٰٓئِكَ لَهُمْ جَنَّٰتُ عَدْنࣲ تَجْرِے مِن تَحْتِهِمُ ࡲ۬لَانْهَٰرُ يُحَلَّوْنَ فِيهَا مِنَ ࡰسَاوِرَ مِن ذَهَبࣲ وَيَلْبَسُونَ ثِيَاباً خُضْراࣰ مِّن سُندُسࣲ وَإِسْتَبْرَقࣲ مُّتَّكِـِٕينَ فِيهَا عَلَى ࡰ۬لَارَآئِكِ࣌ نِعْمَ ࡰ۬لثَّوَابُ࣌ وَحَسُنَتْ مُرْتَفَقاࣰ࣌', 'ࡳولئك لهم جنت عدن تجرے من تحتهم ࡲلانهر يحلون فيها من ࡰساور من ذهب ويلبسون ثيابا خضرا من سندس وإستبرق متكين فيها على ࡰلارائك࣌ نعم ࡰلثواب࣌ وحسنت مرتفقا࣌', NULL, 297, 'local:warsh-text.json'),
  ('warsh-18-32', 'warsh', 18, 32, 'وَاضْرِبْ لَهُم مَّثَلاࣰ رَّجُلَيْنِ جَعَلْنَا لِأَحَدِهِمَا جَنَّتَيْنِ مِنَ ࡰعْنَٰبࣲ وَحَفَفْنَٰهُمَا بِنَخْلࣲ وَجَعَلْنَا بَيْنَهُمَا زَرْعاࣰ࣌', 'واضرب لهم مثلا رجلين جعلنا لأحدهما جنتين من ࡰعنب وحففنهما بنخل وجعلنا بينهما زرعا࣌', NULL, 297, 'local:warsh-text.json'),
  ('warsh-18-33', 'warsh', 18, 33, 'كِلْتَا ࡰ۬لْجَنَّتَيْنِ ءَاتَتُ ࡳكْلَهَا وَلَمْ تَظْلِم مِّنْهُ شَيْـٔاࣰ࣌ وَفَجَّرْنَا خِلَٰلَهُمَا نَهَراࣰ', 'كلتا ࡰلجنتين ءاتت ࡳكلها ولم تظلم منه شيا࣌ وفجرنا خللهما نهرا', NULL, 297, 'local:warsh-text.json'),
  ('warsh-18-34', 'warsh', 18, 34, 'وَكَانَ لَهُۥ ثُمُرࣱ࣌ فَقَالَ لِصَٰحِبِهِۦ وَهُوَ يُحَاوِرُهُۥٓ أَنَآ أَكْثَرُ مِنكَ مَالاࣰ وَأَعَزُّ نَفَراࣰ࣌', 'وكان له ثمر࣌ فقال لصحبه وهو يحاوره أنا أكثر منك مالا وأعز نفرا࣌', NULL, 297, 'local:warsh-text.json'),
  ('warsh-18-35', 'warsh', 18, 35, 'وَدَخَلَ جَنَّتَهُۥ وَهُوَ ظَالِمࣱ لِّنَفْسِهِۦ࣌ قَالَ مَآ أَظُنُّ أَن تَبِيدَ هَٰذِهِۦٓ أَبَداࣰ وَمَآ أَظُنُّ ࡲ۬لسَّاعَةَ قَآئِمَةࣰ وَلَئِن رُّدِدتُّ إِلَىٰ رَبِّے لَأَجِدَنَّ خَيْراࣰ مِّنْهُمَا مُنقَلَباࣰ࣌', 'ودخل جنته وهو ظالم لنفسه࣌ قال ما أظن أن تبيد هذه أبدا وما أظن ࡲلساعة قائمة ولئن رددت إلى ربے لأجدن خيرا منهما منقلبا࣌', NULL, 298, 'local:warsh-text.json'),
  ('warsh-18-36', 'warsh', 18, 36, 'قَالَ لَهُۥ صَٰحِبُهُۥ وَهُوَ يُحَاوِرُهُۥٓ أَكَفَرْتَ بِالذِے خَلَقَكَ مِن تُرَابࣲ ثُمَّ مِن نُّطْفَةࣲ ثُمَّ سَوّٜيٰكَ رَجُلاࣰ࣌', 'قال له صحبه وهو يحاوره أكفرت بالذے خلقك من تراب ثم من نطفة ثم سويك رجلا࣌', NULL, 298, 'local:warsh-text.json'),
  ('warsh-18-37', 'warsh', 18, 37, 'لَّٰكِنَّا هُوَ ࡰ۬للَّهُ رَبِّے وَلَآ أُشْرِكُ بِرَبِّيَ أَحَداࣰ࣌', 'لكنا هو ࡰلله ربے ولا أشرك بربي أحدا࣌', NULL, 298, 'local:warsh-text.json'),
  ('warsh-18-38', 'warsh', 18, 38, 'وَلَوْلَآ إِذْ دَخَلْتَ جَنَّتَكَ قُلْتَ مَا شَآءَ ࡰ۬للَّهُ لَا قُوَّةَ إِلَّا بِاللَّهِ࣌ إِن تَرَنِ أَنَآ أَقَلَّ مِنكَ مَالاࣰ وَوَلَداࣰ', 'ولولا إذ دخلت جنتك قلت ما شاء ࡰلله لا قوة إلا بالله࣌ إن ترن أنا أقل منك مالا وولدا', NULL, 298, 'local:warsh-text.json'),
  ('warsh-18-39', 'warsh', 18, 39, 'فَعَسٜىٰ رَبِّيَ أَنْ يُّوتِيَنِۦ خَيْراࣰ مِّن جَنَّتِكَ وَيُرْسِلَ عَلَيْهَا حُسْبَٰناࣰ مِّنَ ࡰ۬لسَّمَآءِ فَتُصْبِحَ صَعِيداࣰ زَلَقاً', 'فعسى ربي أن يوتين خيرا من جنتك ويرسل عليها حسبنا من ࡰلسماء فتصبح صعيدا زلقا', NULL, 298, 'local:warsh-text.json'),
  ('warsh-18-40', 'warsh', 18, 40, 'ࡰوْ يُصْبِحَ مَآؤُهَا غَوْراࣰ فَلَن تَسْتَطِيعَ لَهُۥ طَلَباࣰ࣌', 'ࡰو يصبح ماؤها غورا فلن تستطيع له طلبا࣌', NULL, 298, 'local:warsh-text.json'),
  ('warsh-18-41', 'warsh', 18, 41, '۞ وَأُحِيطَ بِثُمُرِهِۦ فَأَصْبَحَ يُقَلِّبُ كَفَّيْهِ عَلَىٰ مَآ أَنفَقَ فِيهَا وَهِيَ خَاوِيَةٌ عَلَىٰ عُرُوشِهَا وَيَقُولُ يَٰلَيْتَنِے لَمُ ࡳشْرِكْ بِرَبِّيَ أَحَداࣰ࣌', 'وأحيط بثمره فأصبح يقلب كفيه على ما أنفق فيها وهي خاوية على عروشها ويقول يليتنے لم ࡳشرك بربي أحدا࣌', NULL, 298, 'local:warsh-text.json'),
  ('warsh-18-42', 'warsh', 18, 42, 'وَلَمْ تَكُن لَّهُۥ فِئَةࣱ يَنصُرُونَهُۥ مِن دُونِ ࡴ۬للَّهِ࣌ وَمَا كَانَ مُنتَصِراً࣌', 'ولم تكن له فئة ينصرونه من دون ࡴلله࣌ وما كان منتصرا࣌', NULL, 298, 'local:warsh-text.json'),
  ('warsh-18-43', 'warsh', 18, 43, 'هُنَالِكَ ࡰ۬لْوَلَٰيَةُ لِلهِ ࡴ۬لْحَقِّ࣌ هُوَ خَيْرࣱ ثَوَاباࣰ وَخَيْرٌ عُقُباࣰ࣌', 'هنالك ࡰلولية لله ࡴلحق࣌ هو خير ثوابا وخير عقبا࣌', NULL, 298, 'local:warsh-text.json'),
  ('warsh-18-44', 'warsh', 18, 44, 'وَاضْرِبْ لَهُم مَّثَلَ ࡰ۬لْحَيَوٰةِ ࡴ۬لدُّنْيٜا كَمَآءٍ ࡰنزَلْنَٰهُ مِنَ ࡰ۬لسَّمَآءِ فَاخْتَلَطَ بِهِۦ نَبَاتُ ࡲ۬لَارْضِ فَأَصْبَحَ هَشِيماࣰ تَذْرُوهُ ࡲ۬لرِّيَٰحُ࣌ وَكَانَ ࡰ۬للَّهُ عَلَىٰ كُلِّ شَےْءࣲ مُّقْتَدِراً࣌', 'واضرب لهم مثل ࡰلحيوة ࡴلدنيا كماء ࡰنزلنه من ࡰلسماء فاختلط به نبات ࡲلارض فأصبح هشيما تذروه ࡲلريح࣌ وكان ࡰلله على كل شےء مقتدرا࣌', NULL, 298, 'local:warsh-text.json'),
  ('warsh-18-45', 'warsh', 18, 45, 'ࡴ۬لْمَالُ وَالْبَنُونَ زِينَةُ ࡲ۬لْحَيَوٰةِ ࡴ۬لدُّنْيٜا࣌ وَالْبَٰقِيَٰتُ ࡲ۬لصَّٰلِحَٰتُ خَيْرٌ عِندَ رَبِّكَ ثَوَاباࣰ وَخَيْرٌ ࡰمَلاࣰ࣌', 'ࡴلمال والبنون زينة ࡲلحيوة ࡴلدنيا࣌ والبقيت ࡲلصلحت خير عند ربك ثوابا وخير ࡰملا࣌', NULL, 299, 'local:warsh-text.json'),
  ('warsh-18-46', 'warsh', 18, 46, 'وَيَوْمَ نُسَيِّرُ ࡲ۬لْجِبَالَ وَتَرَى ࡰ۬لَارْضَ بَارِزَةࣰ وَحَشَرْنَٰهُمْ فَلَمْ نُغَادِرْ مِنْهُمُۥٓ أَحَداࣰ࣌', 'ويوم نسير ࡲلجبال وترى ࡰلارض بارزة وحشرنهم فلم نغادر منهم أحدا࣌', NULL, 299, 'local:warsh-text.json'),
  ('warsh-18-47', 'warsh', 18, 47, 'وَعُرِضُواْ عَلَىٰ رَبِّكَ صَفّاࣰ࣌ لَّقَدْ جِئْتُمُونَا كَمَا خَلَقْنَٰكُمُۥٓ أَوَّلَ مَرَّةِۢ࣌ بَلْ زَعَمْتُمُۥٓ أَلَّن نَّجْعَلَ لَكُم مَّوْعِداࣰ࣌', 'وعرضوا على ربك صفا࣌ لقد جئتمونا كما خلقنكم أول مرة࣌ بل زعمتم ألن نجعل لكم موعدا࣌', NULL, 299, 'local:warsh-text.json'),
  ('warsh-18-48', 'warsh', 18, 48, 'وَوُضِعَ ࡰ۬لْكِتَٰبُ فَتَرَى ࡰ۬لْمُجْرِمِينَ مُشْفِقِينَ مِمَّا فِيهِ࣌ وَيَقُولُونَ يَٰوَيْلَتَنَا مَالِ هَٰذَا ࡰ۬لْكِتَٰبِ لَا يُغَادِرُ صَغِيرَةࣰ وَلَا كَبِيرَةً ࡴلَّآ أَحْصٜيٰهَا࣌ وَوَجَدُواْ مَا عَمِلُواْ حَاضِراࣰ࣌ وَلَا يَظْلِمُ رَبُّكَ أَحَداࣰ࣌', 'ووضع ࡰلكتب فترى ࡰلمجرمين مشفقين مما فيه࣌ ويقولون يويلتنا مال هذا ࡰلكتب لا يغادر صغيرة ولا كبيرة ࡴلا أحصيها࣌ ووجدوا ما عملوا حاضرا࣌ ولا يظلم ربك أحدا࣌', NULL, 299, 'local:warsh-text.json'),
  ('warsh-18-49', 'warsh', 18, 49, '۞ وَإِذْ قُلْنَا لِلْمَلَٰٓئِكَةِ ࡴ࢈سْجُدُواْ لِأٓدَمَ فَسَجَدُوٓاْ࣌ إِلَّآ إِبْلِيسَ كَانَ مِنَ ࡰ۬لْجِنِّ فَفَسَقَ عَنَ ࡰمْرِ رَبِّهِۦٓ࣌ أَفَتَتَّخِذُونَهُۥ وَذُرِّيَّتَهُۥٓ أَوْلِيَآءَ مِن دُونِے وَهُمْ لَكُمْ عَدُوُّۢ࣌ بِيسَ لِلظَّٰلِمِينَ بَدَلاࣰ࣌', 'وإذ قلنا للملئكة ࡴ࢈سجدوا لأدم فسجدوا࣌ إلا إبليس كان من ࡰلجن ففسق عن ࡰمر ربه࣌ أفتتخذونه وذريته أولياء من دونے وهم لكم عدو࣌ بيس للظلمين بدلا࣌', NULL, 299, 'local:warsh-text.json'),
  ('warsh-18-50', 'warsh', 18, 50, 'مَّآ أَشْهَدتُّهُمْ خَلْقَ ࡰ۬لسَّمَٰوَٰتِ وَالَارْضِ وَلَا خَلْقَ أَنفُسِهِمْ وَمَا كُنتُ مُتَّخِذَ ࡰ۬لْمُضِلِّينَ عَضُداࣰ࣌', 'ما أشهدتهم خلق ࡰلسموت والارض ولا خلق أنفسهم وما كنت متخذ ࡰلمضلين عضدا࣌', NULL, 299, 'local:warsh-text.json'),
  ('warsh-18-51', 'warsh', 18, 51, 'وَيَوْمَ يَقُولُ نَادُواْ شُرَكَآءِيَ ࡰ۬لذِينَ زَعَمْتُمْ فَدَعَوْهُمْ فَلَمْ يَسْتَجِيبُواْ لَهُمْ وَجَعَلْنَا بَيْنَهُم مَّوْبِقاࣰ࣌', 'ويوم يقول نادوا شركاءي ࡰلذين زعمتم فدعوهم فلم يستجيبوا لهم وجعلنا بينهم موبقا࣌', NULL, 299, 'local:warsh-text.json'),
  ('warsh-18-52', 'warsh', 18, 52, 'وَرَءَا ࡰ۬لْمُجْرِمُونَ ࡰ۬لنَّارَ فَظَنُّوٓاْ أَنَّهُم مُّوَاقِعُوهَا وَلَمْ يَجِدُواْ عَنْهَا مَصْرِفاࣰ࣌', 'ورءا ࡰلمجرمون ࡰلنار فظنوا أنهم مواقعوها ولم يجدوا عنها مصرفا࣌', NULL, 299, 'local:warsh-text.json'),
  ('warsh-18-53', 'warsh', 18, 53, 'وَلَقَدْ صَرَّفْنَا فِے هَٰذَا ࡰ۬لْقُرْءَانِ لِلنَّاسِ مِن كُلِّ مَثَلࣲ࣌ وَكَانَ ࡰ۬لِانسَٰنُ أَكْثَرَ شَےْءࣲ جَدَلاࣰ࣌', 'ولقد صرفنا فے هذا ࡰلقرءان للناس من كل مثل࣌ وكان ࡰلانسن أكثر شےء جدلا࣌', NULL, 300, 'local:warsh-text.json'),
  ('warsh-18-54', 'warsh', 18, 54, 'وَمَا مَنَعَ ࡰ۬لنَّاسَ أَنْ يُّومِنُوٓاْ إِذْ جَآءَهُمُ ࡲ۬لْهُدٜىٰ وَيَسْتَغْفِرُواْ رَبَّهُمُۥٓ إِلَّآ أَن تَاتِيَهُمْ سُنَّةُ ࡲ۬لَاوَّلِينَ أَوْ يَاتِيَهُمُ ࡲ۬لْعَذَابُ قِبَلاࣰ࣌', 'وما منع ࡰلناس أن يومنوا إذ جاءهم ࡲلهدى ويستغفروا ربهم إلا أن تاتيهم سنة ࡲلاولين أو ياتيهم ࡲلعذاب قبلا࣌', NULL, 300, 'local:warsh-text.json'),
  ('warsh-18-55', 'warsh', 18, 55, 'وَمَا نُرْسِلُ ࡲ۬لْمُرْسَلِينَ إِلَّا مُبَشِّرِينَ وَمُنذِرِينَ࣌ وَيُجَٰدِلُ ࡲ۬لذِينَ كَفَرُواْ بِالْبَٰطِلِ لِيُدْحِضُواْ بِهِ ࡴ۬لْحَقَّ࣌ وَاتَّخَذُوٓاْ ءَايَٰتِے وَمَآ أُنذِرُواْ هُزُؤاࣰ࣌', 'وما نرسل ࡲلمرسلين إلا مبشرين ومنذرين࣌ ويجدل ࡲلذين كفروا بالبطل ليدحضوا به ࡴلحق࣌ واتخذوا ءايتے وما أنذروا هزؤا࣌', NULL, 300, 'local:warsh-text.json'),
  ('warsh-18-56', 'warsh', 18, 56, 'وَمَنَ ࡰظْلَمُ مِمَّن ذُكِّرَ بِـَٔايَٰتِ رَبِّهِۦ فَأَعْرَضَ عَنْهَا وَنَسِيَ مَا قَدَّمَتْ يَدَٰهُ࣌ إِنَّا جَعَلْنَا عَلَىٰ قُلُوبِهِمُۥٓ أَكِنَّةً ࡰنْ يَّفْقَهُوهُ وَفِےٓ ءَاذَانِهِمْ وَقْراࣰ࣌ وَإِن تَدْعُهُمُۥٓ إِلَى ࡰ۬لْهُدٜىٰ فَلَنْ يَّهْتَدُوٓاْ إِذاً ࡰبَداࣰ࣌', 'ومن ࡰظلم ممن ذكر بايت ربه فأعرض عنها ونسي ما قدمت يده࣌ إنا جعلنا على قلوبهم أكنة ࡰن يفقهوه وفے ءاذانهم وقرا࣌ وإن تدعهم إلى ࡰلهدى فلن يهتدوا إذا ࡰبدا࣌', NULL, 300, 'local:warsh-text.json'),
  ('warsh-18-57', 'warsh', 18, 57, 'وَرَبُّكَ ࡰ۬لْغَفُورُ ذُو ࡲ۬لرَّحْمَةِ࣌ لَوْ يُوَ۬اخِذُهُم بِمَا كَسَبُواْ لَعَجَّلَ لَهُمُ ࡲ۬لْعَذَابَ࣌ بَل لَّهُم مَّوْعِدࣱ لَّنْ يَّجِدُواْ مِن دُونِهِۦ مَوْئِلاࣰ࣌', 'وربك ࡰلغفور ذو ࡲلرحمة࣌ لو يواخذهم بما كسبوا لعجل لهم ࡲلعذاب࣌ بل لهم موعد لن يجدوا من دونه موئلا࣌', NULL, 300, 'local:warsh-text.json'),
  ('warsh-18-58', 'warsh', 18, 58, '۞ وَتِلْكَ ࡰ۬لْقُرٜىٰٓ أَهْلَكْنَٰهُمْ لَمَّا ظَلَمُواْ وَجَعَلْنَا لِمُهْلَكِهِم مَّوْعِداࣰ࣌', 'وتلك ࡰلقرى أهلكنهم لما ظلموا وجعلنا لمهلكهم موعدا࣌', NULL, 300, 'local:warsh-text.json'),
  ('warsh-18-59', 'warsh', 18, 59, 'وَإِذْ قَالَ مُوسٜىٰ لِفَتٜيٰهُ لَآ أَبْرَحُ حَتَّىٰٓ أَبْلُغَ مَجْمَعَ ࡰ۬لْبَحْرَيْنِ أَوَ ࡰمْضِيَ حُقُباࣰ࣌', 'وإذ قال موسى لفتيه لا أبرح حتى أبلغ مجمع ࡰلبحرين أو ࡰمضي حقبا࣌', NULL, 300, 'local:warsh-text.json'),
  ('warsh-18-60', 'warsh', 18, 60, 'فَلَمَّا بَلَغَا مَجْمَعَ بَيْنِهِمَا نَسِيَا حُوتَهُمَا فَاتَّخَذَ سَبِيلَهُۥ فِے ࡴ۬لْبَحْرِ سَرَباࣰ࣌', 'فلما بلغا مجمع بينهما نسيا حوتهما فاتخذ سبيله فے ࡴلبحر سربا࣌', NULL, 300, 'local:warsh-text.json'),
  ('warsh-18-61', 'warsh', 18, 61, 'فَلَمَّا جَاوَزَا قَالَ لِفَتٜيٰهُ ءَاتِنَا غَدَآءَنَا لَقَدْ لَقِينَا مِن سَفَرِنَا هَٰذَا نَصَباࣰ࣌', 'فلما جاوزا قال لفتيه ءاتنا غداءنا لقد لقينا من سفرنا هذا نصبا࣌', NULL, 301, 'local:warsh-text.json'),
  ('warsh-18-62', 'warsh', 18, 62, 'قَالَ أَرَٰٓيْتَ إِذَ ࡰوَيْنَآ إِلَى ࡰ۬لصَّخْرَةِ فَإِنِّے نَسِيتُ ࡲ۬لْحُوتَ࣌ وَمَآ أَنسٜيٰنِيهِ إِلَّا ࡰ۬لشَّيْطَٰنُ أَنَ ࡰذْكُرَهُۥ࣌ وَاتَّخَذَ سَبِيلَهُۥ فِے ࡴ۬لْبَحْرِ࣌ عَجَباࣰ࣌', 'قال أريت إذ ࡰوينا إلى ࡰلصخرة فإنے نسيت ࡲلحوت࣌ وما أنسينيه إلا ࡰلشيطن أن ࡰذكره࣌ واتخذ سبيله فے ࡴلبحر࣌ عجبا࣌', NULL, 301, 'local:warsh-text.json'),
  ('warsh-18-63', 'warsh', 18, 63, 'قَالَ ذَٰلِكَ مَا كُنَّا نَبْغِۦ࣌ فَارْتَدَّا عَلَىٰٓ ءَاثٜارِهِمَا قَصَصاࣰ', 'قال ذلك ما كنا نبغ࣌ فارتدا على ءاثارهما قصصا', NULL, 301, 'local:warsh-text.json'),
  ('warsh-18-64', 'warsh', 18, 64, 'فَوَجَدَا عَبْداࣰ مِّنْ عِبَادِنَآ ءَاتَيْنَٰهُ رَحْمَةࣰ مِّنْ عِندِنَا وَعَلَّمْنَٰهُ مِن لَّدُنَّا عِلْماࣰ࣌', 'فوجدا عبدا من عبادنا ءاتينه رحمة من عندنا وعلمنه من لدنا علما࣌', NULL, 301, 'local:warsh-text.json'),
  ('warsh-18-65', 'warsh', 18, 65, 'قَالَ لَهُۥ مُوسٜىٰ هَلَ ࡰتَّبِعُكَ عَلَىٰٓ أَن تُعَلِّمَنِۦ مِمَّا عُلِّمْتَ رُشْداࣰ࣌', 'قال له موسى هل ࡰتبعك على أن تعلمن مما علمت رشدا࣌', NULL, 301, 'local:warsh-text.json'),
  ('warsh-18-66', 'warsh', 18, 66, 'قَالَ إِنَّكَ لَن تَسْتَطِيعَ مَعِے صَبْراࣰ࣌', 'قال إنك لن تستطيع معے صبرا࣌', NULL, 301, 'local:warsh-text.json'),
  ('warsh-18-67', 'warsh', 18, 67, 'وَكَيْفَ تَصْبِرُ عَلَىٰ مَا لَمْ تُحِطْ بِهِۦ خُبْراࣰ࣌', 'وكيف تصبر على ما لم تحط به خبرا࣌', NULL, 301, 'local:warsh-text.json'),
  ('warsh-18-68', 'warsh', 18, 68, 'قَالَ سَتَجِدُنِيَ إِن شَآءَ ࡰ۬للَّهُ صَابِراࣰ࣌ وَلَآ أَعْصِے لَكَ أَمْراࣰ࣌', 'قال ستجدني إن شاء ࡰلله صابرا࣌ ولا أعصے لك أمرا࣌', NULL, 301, 'local:warsh-text.json'),
  ('warsh-18-69', 'warsh', 18, 69, 'قَالَ فَإِنِ ࡴٜتَّبَعْتَنِے فَلَا تَسْـَٔلَنِّے عَن شَےْءٍ حَتَّىٰٓ أُحْدِثَ لَكَ مِنْهُ ذِكْراࣰ࣌', 'قال فإن ࡴتبعتنے فلا تسلنے عن شےء حتى أحدث لك منه ذكرا࣌', NULL, 301, 'local:warsh-text.json'),
  ('warsh-18-70', 'warsh', 18, 70, 'فَانطَلَقَا حَتَّىٰٓ إِذَا رَكِبَا فِے ࡴ۬لسَّفِينَةِ خَرَقَهَا࣌ قَالَ أَخَرَقْتَهَا لِتُغْرِقَ أَهْلَهَا لَقَدْ جِئْتَ شَيْـٔاً ࡴمْراࣰ࣌', 'فانطلقا حتى إذا ركبا فے ࡴلسفينة خرقها࣌ قال أخرقتها لتغرق أهلها لقد جئت شيا ࡴمرا࣌', NULL, 301, 'local:warsh-text.json'),
  ('warsh-18-71', 'warsh', 18, 71, 'قَالَ أَلَمَ ࡰقُلِ ࡴنَّكَ لَن تَسْتَطِيعَ مَعِے صَبْراࣰ࣌', 'قال ألم ࡰقل ࡴنك لن تستطيع معے صبرا࣌', NULL, 301, 'local:warsh-text.json'),
  ('warsh-18-72', 'warsh', 18, 72, 'قَالَ لَا تُوَ۬اخِذْنِے بِمَا نَسِيتُ وَلَا تُرْهِقْنِے مِنَ ࡰمْرِے عُسْراࣰ࣌', 'قال لا تواخذنے بما نسيت ولا ترهقنے من ࡰمرے عسرا࣌', NULL, 301, 'local:warsh-text.json'),
  ('warsh-18-73', 'warsh', 18, 73, 'فَانطَلَقَا حَتَّىٰٓ إِذَا لَقِيَا غُلَٰماࣰ فَقَتَلَهُۥ قَالَ أَقَتَلْتَ نَفْساࣰ زَٰكِيَةَۢ بِغَيْرِ نَفْسࣲ لَّقَدْ جِئْتَ شَيْـٔاࣰ نُّكُراࣰ࣌', 'فانطلقا حتى إذا لقيا غلما فقتله قال أقتلت نفسا زكية بغير نفس لقد جئت شيا نكرا࣌', NULL, 301, 'local:warsh-text.json'),
  ('warsh-18-74', 'warsh', 18, 74, '۞ قَالَ أَلَمَ ࡰقُل لَّكَ إِنَّكَ لَن تَسْتَطِيعَ مَعِے صَبْراࣰ࣌', 'قال ألم ࡰقل لك إنك لن تستطيع معے صبرا࣌', NULL, 302, 'local:warsh-text.json'),
  ('warsh-18-75', 'warsh', 18, 75, 'قَالَ إِن سَأَلْتُكَ عَن شَےْءِۢ بَعْدَهَا فَلَا تُصَٰحِبْنِے قَدْ بَلَغْتَ مِن لَّدُنِے عُذْراࣰ࣌', 'قال إن سألتك عن شےء بعدها فلا تصحبنے قد بلغت من لدنے عذرا࣌', NULL, 302, 'local:warsh-text.json'),
  ('warsh-18-76', 'warsh', 18, 76, 'فَانطَلَقَا حَتَّىٰٓ إِذَآ أَتَيَآ أَهْلَ قَرْيَةٍ ࡴٜسْتَطْعَمَآ أَهْلَهَا فَأَبَوَاْ ࡰنْ يُّضَيِّفُوهُمَا فَوَجَدَا فِيهَا جِدَاراࣰ يُرِيدُ أَنْ يَّنقَضَّ فَأَقَامَهُۥ࣌ قَالَ لَوْ شِئْتَ لَتَّخَذتَّ عَلَيْهِ أَجْراࣰ࣌', 'فانطلقا حتى إذا أتيا أهل قرية ࡴستطعما أهلها فأبوا ࡰن يضيفوهما فوجدا فيها جدارا يريد أن ينقض فأقامه࣌ قال لو شئت لتخذت عليه أجرا࣌', NULL, 302, 'local:warsh-text.json'),
  ('warsh-18-77', 'warsh', 18, 77, 'قَالَ هَٰذَا فِرَاقُ بَيْنِے وَبَيْنِكَ࣌ سَأُنَبِّئُكَ بِتَاوِيلِ مَا لَمْ تَسْتَطِع عَّلَيْهِ صَبْراً࣌', 'قال هذا فراق بينے وبينك࣌ سأنبئك بتاويل ما لم تستطع عليه صبرا࣌', NULL, 302, 'local:warsh-text.json'),
  ('warsh-18-78', 'warsh', 18, 78, 'ࡰمَّا ࡰ۬لسَّفِينَةُ فَكَانَتْ لِمَسَٰكِينَ يَعْمَلُونَ فِے ࡴ۬لْبَحْرِ فَأَرَدتُّ أَنَ ࡰعِيبَهَا وَكَانَ وَرَآءَهُم مَّلِكࣱ يَاخُذُ كُلَّ سَفِينَةٍ غَصْباࣰ࣌', 'ࡰما ࡰلسفينة فكانت لمسكين يعملون فے ࡴلبحر فأردت أن ࡰعيبها وكان وراءهم ملك ياخذ كل سفينة غصبا࣌', NULL, 302, 'local:warsh-text.json'),
  ('warsh-18-79', 'warsh', 18, 79, 'وَأَمَّا ࡰ۬لْغُلَٰمُ فَكَانَ أَبَوَٰهُ مُومِنَيْنِ فَخَشِينَآ أَنْ يُّرْهِقَهُمَا طُغْيَٰناࣰ وَكُفْراࣰ࣌', 'وأما ࡰلغلم فكان أبوه مومنين فخشينا أن يرهقهما طغينا وكفرا࣌', NULL, 302, 'local:warsh-text.json'),
  ('warsh-18-80', 'warsh', 18, 80, 'فَأَرَدْنَآ أَنْ يُّبَدِّلَهُمَا رَبُّهُمَا خَيْراࣰ مِّنْهُ زَكَوٰةࣰ وَأَقْرَبَ رُحْماࣰ࣌', 'فأردنا أن يبدلهما ربهما خيرا منه زكوة وأقرب رحما࣌', NULL, 302, 'local:warsh-text.json'),
  ('warsh-18-81', 'warsh', 18, 81, 'وَأَمَّا ࡰ۬لْجِدَارُ فَكَانَ لِغُلَٰمَيْنِ يَتِيمَيْنِ فِے ࡴ۬لْمَدِينَةِ وَكَانَ تَحْتَهُۥ كَنزࣱ لَّهُمَا࣌ وَكَانَ أَبُوهُمَا صَٰلِحاࣰ فَأَرَادَ رَبُّكَ أَنْ يَّبْلُغَآ أَشُدَّهُمَا وَيَسْتَخْرِجَا كَنزَهُمَا رَحْمَةࣰ مِّن رَّبِّكَ࣌ وَمَا فَعَلْتُهُۥ عَنَ ࡰمْرِے࣌ ذَٰلِكَ تَاوِيلُ مَا لَمْ تَسْطِع عَّلَيْهِ صَبْراࣰ࣌', 'وأما ࡰلجدار فكان لغلمين يتيمين فے ࡴلمدينة وكان تحته كنز لهما࣌ وكان أبوهما صلحا فأراد ربك أن يبلغا أشدهما ويستخرجا كنزهما رحمة من ربك࣌ وما فعلته عن ࡰمرے࣌ ذلك تاويل ما لم تسطع عليه صبرا࣌', NULL, 302, 'local:warsh-text.json'),
  ('warsh-18-82', 'warsh', 18, 82, 'وَيَسْـَٔلُونَكَ عَن ذِے ࡴ۬لْقَرْنَيْنِ࣌ قُلْ سَأَتْلُواْ عَلَيْكُم مِّنْهُ ذِكْراً࣌', 'ويسلونك عن ذے ࡴلقرنين࣌ قل سأتلوا عليكم منه ذكرا࣌', NULL, 302, 'local:warsh-text.json'),
  ('warsh-18-83', 'warsh', 18, 83, 'ࡴنَّا مَكَّنَّا لَهُۥ فِے ࡴ۬لَارْضِ وَءَاتَيْنَٰهُ مِن كُلِّ شَےْءࣲ سَبَباࣰ', 'ࡴنا مكنا له فے ࡴلارض وءاتينه من كل شےء سببا', NULL, 303, 'local:warsh-text.json'),
  ('warsh-18-84', 'warsh', 18, 84, 'فَاتَّبَعَ سَبَباً حَتَّىٰٓ إِذَا بَلَغَ مَغْرِبَ ࡰ۬لشَّمْسِ وَجَدَهَا تَغْرُبُ فِے عَيْنٍ حَمِئَةࣲ وَوَجَدَ عِندَهَا قَوْماࣰ࣌ قُلْنَا يَٰذَا ࡰ۬لْقَرْنَيْنِ إِمَّآ أَن تُعَذِّبَ وَإِمَّآ أَن تَتَّخِذَ فِيهِمْ حُسْناࣰ࣌', 'فاتبع سببا حتى إذا بلغ مغرب ࡰلشمس وجدها تغرب فے عين حمئة ووجد عندها قوما࣌ قلنا يذا ࡰلقرنين إما أن تعذب وإما أن تتخذ فيهم حسنا࣌', NULL, 303, 'local:warsh-text.json'),
  ('warsh-18-85', 'warsh', 18, 85, '۞ قَالَ أَمَّا مَن ظَلَمَ فَسَوْفَ نُعَذِّبُهُۥ ثُمَّ يُرَدُّ إِلَىٰ رَبِّهِۦ فَيُعَذِّبُهُۥ عَذَاباࣰ نُّكُراࣰ࣌', 'قال أما من ظلم فسوف نعذبه ثم يرد إلى ربه فيعذبه عذابا نكرا࣌', NULL, 303, 'local:warsh-text.json'),
  ('warsh-18-86', 'warsh', 18, 86, 'وَأَمَّا مَنَ اٰمَنَ وَعَمِلَ صَٰلِحاࣰ فَلَهُۥ جَزَآءُ ࡲ۬لْحُسْنٜىٰ࣌ وَسَنَقُولُ لَهُۥ مِنَ ࡰمْرِنَا يُسْراࣰ࣌', 'وأما من امن وعمل صلحا فله جزاء ࡲلحسنى࣌ وسنقول له من ࡰمرنا يسرا࣌', NULL, 303, 'local:warsh-text.json'),
  ('warsh-18-87', 'warsh', 18, 87, 'ثُمَّ ࡰٜتَّبَعَ سَبَباً حَتَّىٰٓ إِذَا بَلَغَ مَطْلِعَ ࡰ۬لشَّمْسِ وَجَدَهَا تَطْلُعُ عَلَىٰ قَوْمࣲ لَّمْ نَجْعَل لَّهُم مِّن دُونِهَا سِتْراࣰ', 'ثم ࡰتبع سببا حتى إذا بلغ مطلع ࡰلشمس وجدها تطلع على قوم لم نجعل لهم من دونها سترا', NULL, 303, 'local:warsh-text.json'),
  ('warsh-18-88', 'warsh', 18, 88, 'كَذَٰلِكَ࣌ وَقَدَ ࡰحَطْنَا بِمَا لَدَيْهِ خُبْراࣰ࣌', 'كذلك࣌ وقد ࡰحطنا بما لديه خبرا࣌', NULL, 303, 'local:warsh-text.json'),
  ('warsh-18-89', 'warsh', 18, 89, 'ثُمَّ ࡰٜتَّبَعَ سَبَباً حَتَّىٰٓ إِذَا بَلَغَ بَيْنَ ࡰ۬لسُّدَّيْنِ وَجَدَ مِن دُونِهِمَا قَوْماࣰ لَّا يَكَادُونَ يَفْقَهُونَ قَوْلاࣰ࣌', 'ثم ࡰتبع سببا حتى إذا بلغ بين ࡰلسدين وجد من دونهما قوما لا يكادون يفقهون قولا࣌', NULL, 303, 'local:warsh-text.json'),
  ('warsh-18-90', 'warsh', 18, 90, 'قَالُواْ يَٰذَا ࡰ۬لْقَرْنَيْنِ إِنَّ يَاجُوجَ وَمَاجُوجَ مُفْسِدُونَ فِے ࡴ۬لَارْضِ فَهَلْ نَجْعَلُ لَكَ خَرْجاً عَلَىٰٓ أَن تَجْعَلَ بَيْنَنَا وَبَيْنَهُمْ سُدّاࣰ࣌', 'قالوا يذا ࡰلقرنين إن ياجوج وماجوج مفسدون فے ࡴلارض فهل نجعل لك خرجا على أن تجعل بيننا وبينهم سدا࣌', NULL, 303, 'local:warsh-text.json'),
  ('warsh-18-91', 'warsh', 18, 91, 'قَالَ مَا مَكَّنِّے فِيهِ رَبِّے خَيْرࣱ࣌ فَأَعِينُونِے بِقُوَّةٍ ࡰجْعَلْ بَيْنَكُمْ وَبَيْنَهُمْ رَدْماً࣌', 'قال ما مكنے فيه ربے خير࣌ فأعينونے بقوة ࡰجعل بينكم وبينهم ردما࣌', NULL, 303, 'local:warsh-text.json'),
  ('warsh-18-92', 'warsh', 18, 92, 'اٰتُونِے زُبَرَ ࡰ۬لْحَدِيدِ࣌ حَتَّىٰٓ إِذَا سَاوٜىٰ بَيْنَ ࡰ۬لصَّدَفَيْنِ قَالَ ࡸَنفُخُواْ࣌ حَتَّىٰٓ إِذَا جَعَلَهُۥ نَاراࣰ قَالَ ءَاتُونِےٓ أُفْرِغْ عَلَيْهِ قِطْراࣰ࣌', 'اتونے زبر ࡰلحديد࣌ حتى إذا ساوى بين ࡰلصدفين قال ࡸنفخوا࣌ حتى إذا جعله نارا قال ءاتونے أفرغ عليه قطرا࣌', NULL, 303, 'local:warsh-text.json'),
  ('warsh-18-93', 'warsh', 18, 93, 'فَمَا ࡰٜسْطَٰعُوٓاْ أَنْ يَّظْهَرُوهُ وَمَا ࡰٜسْتَطَٰعُواْ لَهُۥ نَقْباࣰ࣌', 'فما ࡰسطعوا أن يظهروه وما ࡰستطعوا له نقبا࣌', NULL, 303, 'local:warsh-text.json'),
  ('warsh-18-94', 'warsh', 18, 94, 'قَالَ هَٰذَا رَحْمَةࣱ مِّن رَّبِّے࣌ فَإِذَا جَآءَ وَعْدُ رَبِّے جَعَلَهُۥ دَكّاࣰ وَكَانَ وَعْدُ رَبِّے حَقّاࣰ࣌', 'قال هذا رحمة من ربے࣌ فإذا جاء وعد ربے جعله دكا وكان وعد ربے حقا࣌', NULL, 304, 'local:warsh-text.json'),
  ('warsh-18-95', 'warsh', 18, 95, 'وَتَرَكْنَا بَعْضَهُمْ يَوْمَئِذࣲ يَمُوجُ فِے بَعْضࣲ࣌ وَنُفِخَ فِے ࡴ۬لصُّورِ فَجَمَعْنَٰهُمْ جَمْعاࣰ࣌', 'وتركنا بعضهم يومئذ يموج فے بعض࣌ ونفخ فے ࡴلصور فجمعنهم جمعا࣌', NULL, 304, 'local:warsh-text.json'),
  ('warsh-18-96', 'warsh', 18, 96, 'وَعَرَضْنَا جَهَنَّمَ يَوْمَئِذࣲ لِّلْكٜـٰفِرِينَ عَرْضاً', 'وعرضنا جهنم يومئذ للكفرين عرضا', NULL, 304, 'local:warsh-text.json'),
  ('warsh-18-97', 'warsh', 18, 97, 'ࡴ۬لذِينَ كَانَتَ ࡰعْيُنُهُمْ فِے غِطَآءٍ عَن ذِكْرِے وَكَانُواْ لَا يَسْتَطِيعُونَ سَمْعاً࣌', 'ࡴلذين كانت ࡰعينهم فے غطاء عن ذكرے وكانوا لا يستطيعون سمعا࣌', NULL, 304, 'local:warsh-text.json'),
  ('warsh-18-98', 'warsh', 18, 98, '۞ ࡰفَحَسِبَ ࡰ۬لذِينَ كَفَرُوٓاْ أَنْ يَّتَّخِذُواْ عِبَادِے مِن دُونِيَ أَوْلِيَآءَ࣌ ࡹنَّآ أَعْتَدْنَا جَهَنَّمَ لِلْكٜـٰفِرِينَ نُزُلاࣰ࣌', 'ࡰفحسب ࡰلذين كفروا أن يتخذوا عبادے من دوني أولياء࣌ ࡹنا أعتدنا جهنم للكفرين نزلا࣌', NULL, 304, 'local:warsh-text.json'),
  ('warsh-18-99', 'warsh', 18, 99, 'قُلْ هَلْ نُنَبِّئُكُم بِالَاخْسَرِينَ أَعْمَٰلاً ࡴ۬لذِينَ ضَلَّ سَعْيُهُمْ فِے ࡴ۬لْحَيَوٰةِ ࡴ۬لدُّنْيٜا وَهُمْ يَحْسِبُونَ أَنَّهُمْ يُحْسِنُونَ صُنْعاً࣌', 'قل هل ننبئكم بالاخسرين أعملا ࡴلذين ضل سعيهم فے ࡴلحيوة ࡴلدنيا وهم يحسبون أنهم يحسنون صنعا࣌', NULL, 304, 'local:warsh-text.json'),
  ('warsh-18-100', 'warsh', 18, 100, 'ࡳوْلَٰٓئِكَ ࡰ۬لذِينَ كَفَرُواْ بِـَٔايَٰتِ رَبِّهِمْ وَلِقَآئِهِۦ فَحَبِطَتَ ࡰعْمَٰلُهُمْ فَلَا نُقِيمُ لَهُمْ يَوْمَ ࡰ۬لْقِيَٰمَةِ وَزْناࣰ࣌', 'ࡳولئك ࡰلذين كفروا بايت ربهم ولقائه فحبطت ࡰعملهم فلا نقيم لهم يوم ࡰلقيمة وزنا࣌', NULL, 304, 'local:warsh-text.json'),
  ('warsh-18-101', 'warsh', 18, 101, 'ذَٰلِكَ جَزَآؤُهُمْ جَهَنَّمُ بِمَا كَفَرُواْ وَاتَّخَذُوٓاْ ءَايَٰتِے وَرُسُلِے هُزُؤاً࣌', 'ذلك جزاؤهم جهنم بما كفروا واتخذوا ءايتے ورسلے هزؤا࣌', NULL, 304, 'local:warsh-text.json'),
  ('warsh-18-102', 'warsh', 18, 102, 'ࡴنَّ ࡰ۬لذِينَ ءَامَنُواْ وَعَمِلُواْ ࡲ۬لصَّٰلِحَٰتِ كَانَتْ لَهُمْ جَنَّٰتُ ࡲ۬لْفِرْدَوْسِ نُزُلاً', 'ࡴن ࡰلذين ءامنوا وعملوا ࡲلصلحت كانت لهم جنت ࡲلفردوس نزلا', NULL, 304, 'local:warsh-text.json'),
  ('warsh-18-103', 'warsh', 18, 103, 'خَٰلِدِينَ فِيهَا لَا يَبْغُونَ عَنْهَا حِوَلاࣰ࣌', 'خلدين فيها لا يبغون عنها حولا࣌', NULL, 304, 'local:warsh-text.json'),
  ('warsh-18-104', 'warsh', 18, 104, 'قُل لَّوْ كَانَ ࡰ۬لْبَحْرُ مِدَاداࣰ لِّكَلِمَٰتِ رَبِّے لَنَفِدَ ࡰ۬لْبَحْرُ قَبْلَ أَن تَنفَدَ كَلِمَٰتُ رَبِّے وَلَوْ جِئْنَا بِمِثْلِهِۦ مَدَداࣰ࣌', 'قل لو كان ࡰلبحر مدادا لكلمت ربے لنفد ࡰلبحر قبل أن تنفد كلمت ربے ولو جئنا بمثله مددا࣌', NULL, 304, 'local:warsh-text.json'),
  ('warsh-18-105', 'warsh', 18, 105, 'قُلِ ࡴنَّمَآ أَنَا بَشَرࣱ مِّثْلُكُمْ يُوحٜىٰٓ إِلَيَّ أَنَّمَآ إِلَٰهُكُمُۥٓ إِلَٰهࣱ وَٰحِدࣱ࣌ فَمَن كَانَ يَرْجُواْ لِقَآءَ رَبِّهِۦ فَلْيَعْمَلْ عَمَلاࣰ صَٰلِحاࣰ وَلَا يُشْرِكْ بِعِبَادَةِ رَبِّهِۦٓ أَحَداࣰ࣌', 'قل ࡴنما أنا بشر مثلكم يوحى إلي أنما إلهكم إله وحد࣌ فمن كان يرجوا لقاء ربه فليعمل عملا صلحا ولا يشرك بعبادة ربه أحدا࣌', NULL, 304, 'local:warsh-text.json'),
  ('warsh-19-1', 'warsh', 19, 1, 'كَٓهٜيٜعَٓصَٓ࣌ ذِكْرُ رَحْمَتِ رَبِّكَ عَبْدَهُۥ زَكَرِيَّآءَ', 'كهيعص࣌ ذكر رحمت ربك عبده زكرياء', NULL, 305, 'local:warsh-text.json'),
  ('warsh-19-2', 'warsh', 19, 2, 'ࡹذْ نَادٜىٰ رَبَّهُۥ نِدَآءً خَفِيّاࣰ࣌', 'ࡹذ نادى ربه نداء خفيا࣌', NULL, 305, 'local:warsh-text.json'),
  ('warsh-19-3', 'warsh', 19, 3, 'قَالَ رَبِّ إِنِّے وَهَنَ ࡰ۬لْعَظْمُ مِنِّے وَاشْتَعَلَ ࡰ۬لرَّأْسُ شَيْباࣰ وَلَمَ ࡰكُنۢ بِدُعَآئِكَ رَبِّ شَقِيّاࣰ࣌', 'قال رب إنے وهن ࡰلعظم منے واشتعل ࡰلرأس شيبا ولم ࡰكن بدعائك رب شقيا࣌', NULL, 305, 'local:warsh-text.json'),
  ('warsh-19-4', 'warsh', 19, 4, 'وَإِنِّے خِفْتُ ࡲ۬لْمَوَٰلِيَ مِنْ وَّرَآءِے وَكَانَتِ ࡴٜمْرَأَتِے عَاقِراࣰ فَهَبْ لِے مِن لَّدُنكَ وَلِيّاࣰ', 'وإنے خفت ࡲلمولي من وراءے وكانت ࡴمرأتے عاقرا فهب لے من لدنك وليا', NULL, 305, 'local:warsh-text.json'),
  ('warsh-19-5', 'warsh', 19, 5, 'يَرِثُنِے وَيَرِثُ مِنَ اٰلِ يَعْقُوبَ࣌ وَاجْعَلْهُ رَبِّ رَضِيّاࣰ࣌', 'يرثنے ويرث من ال يعقوب࣌ واجعله رب رضيا࣌', NULL, 305, 'local:warsh-text.json'),
  ('warsh-19-6', 'warsh', 19, 6, '۞ يَٰزَكَرِيَّآءُ ࡹِنَّا نُبَشِّرُكَ بِغُلَٰمٍ ࡴٜسْمُهُۥ يَحْيٜىٰ لَمْ نَجْعَل لَّهُۥ مِن قَبْلُ سَمِيّاࣰ࣌', 'يزكرياء ࡹنا نبشرك بغلم ࡴسمه يحيى لم نجعل له من قبل سميا࣌', NULL, 305, 'local:warsh-text.json'),
  ('warsh-19-7', 'warsh', 19, 7, 'قَالَ رَبِّ أَنّٜىٰ يَكُونُ لِے غُلَٰمࣱ وَكَانَتِ ࡴٜمْرَأَتِے عَاقِراࣰ وَقَدْ بَلَغْتُ مِنَ ࡰ۬لْكِبَرِ عُتِيّاࣰ࣌', 'قال رب أنى يكون لے غلم وكانت ࡴمرأتے عاقرا وقد بلغت من ࡰلكبر عتيا࣌', NULL, 305, 'local:warsh-text.json'),
  ('warsh-19-8', 'warsh', 19, 8, 'قَالَ كَذَٰلِكَ قَالَ رَبُّكَ هُوَ عَلَيَّ هَيِّنࣱ وَقَدْ خَلَقْتُكَ مِن قَبْلُ وَلَمْ تَكُ شَيْـٔاࣰ࣌', 'قال كذلك قال ربك هو علي هين وقد خلقتك من قبل ولم تك شيا࣌', NULL, 305, 'local:warsh-text.json'),
  ('warsh-19-9', 'warsh', 19, 9, 'قَالَ رَبِّ ࡴٜجْعَل لِّيَ ءَايَةࣰ࣌ قَالَ ءَايَتُكَ أَلَّا تُكَلِّمَ ࡰ۬لنَّاسَ ثَلَٰثَ لَيَالࣲ سَوِيّاࣰ࣌', 'قال رب ࡴجعل لي ءاية࣌ قال ءايتك ألا تكلم ࡰلناس ثلث ليال سويا࣌', NULL, 305, 'local:warsh-text.json'),
  ('warsh-19-10', 'warsh', 19, 10, 'فَخَرَجَ عَلَىٰ قَوْمِهِۦ مِنَ ࡰ۬لْمِحْرَابِ فَأَوْحٜىٰٓ إِلَيْهِمُۥٓ أَن سَبِّحُواْ بُكْرَةࣰ وَعَشِيّاࣰ࣌', 'فخرج على قومه من ࡰلمحراب فأوحى إليهم أن سبحوا بكرة وعشيا࣌', NULL, 305, 'local:warsh-text.json'),
  ('warsh-19-11', 'warsh', 19, 11, 'يَٰيَحْيٜىٰ خُذِ ࡴ۬لْكِتَٰبَ بِقُوَّةࣲ࣌ وَءَاتَيْنَٰهُ ࡲ۬لْحُكْمَ صَبِيّاࣰ࣌', 'ييحيى خذ ࡴلكتب بقوة࣌ وءاتينه ࡲلحكم صبيا࣌', NULL, 306, 'local:warsh-text.json'),
  ('warsh-19-12', 'warsh', 19, 12, 'وَحَنَاناࣰ مِّن لَّدُنَّا وَزَكَوٰةࣰ࣌ وَكَانَ تَقِيّاࣰ࣌', 'وحنانا من لدنا وزكوة࣌ وكان تقيا࣌', NULL, 306, 'local:warsh-text.json'),
  ('warsh-19-13', 'warsh', 19, 13, 'وَبَرّاَۢ بِوَٰلِدَيْهِ وَلَمْ يَكُن جَبَّاراً عَصِيّاࣰ࣌', 'وبرا بولديه ولم يكن جبارا عصيا࣌', NULL, 306, 'local:warsh-text.json'),
  ('warsh-19-14', 'warsh', 19, 14, 'وَسَلَٰمٌ عَلَيْهِ يَوْمَ وُلِدَ وَيَوْمَ يَمُوتُ وَيَوْمَ يُبْعَثُ حَيّاࣰ࣌', 'وسلم عليه يوم ولد ويوم يموت ويوم يبعث حيا࣌', NULL, 306, 'local:warsh-text.json'),
  ('warsh-19-15', 'warsh', 19, 15, 'وَاذْكُرْ فِے ࡴ۬لْكِتَٰبِ مَرْيَمَ إِذِ ࡴٜنتَبَذَتْ مِنَ ࡰهْلِهَا مَكَاناࣰ شَرْقِيّاࣰ', 'واذكر فے ࡴلكتب مريم إذ ࡴنتبذت من ࡰهلها مكانا شرقيا', NULL, 306, 'local:warsh-text.json'),
  ('warsh-19-16', 'warsh', 19, 16, 'فَاتَّخَذَتْ مِن دُونِهِمْ حِجَاباࣰ࣌ فَأَرْسَلْنَآ إِلَيْهَا رُوحَنَا فَتَمَثَّلَ لَهَا بَشَراࣰ سَوِيّاࣰ࣌', 'فاتخذت من دونهم حجابا࣌ فأرسلنا إليها روحنا فتمثل لها بشرا سويا࣌', NULL, 306, 'local:warsh-text.json'),
  ('warsh-19-17', 'warsh', 19, 17, 'قَالَتِ ࡴنِّيَ أَعُوذُ بِالرَّحْمَٰنِ مِنكَ إِن كُنتَ تَقِيّاࣰ࣌', 'قالت ࡴني أعوذ بالرحمن منك إن كنت تقيا࣌', NULL, 306, 'local:warsh-text.json'),
  ('warsh-19-18', 'warsh', 19, 18, 'قَالَ إِنَّمَآ أَنَا رَسُولُ رَبِّكِ لِاَهَبَ لَكِ غُلَٰماࣰ زَكِيّاࣰ࣌', 'قال إنما أنا رسول ربك لاهب لك غلما زكيا࣌', NULL, 306, 'local:warsh-text.json'),
  ('warsh-19-19', 'warsh', 19, 19, 'قَالَتَ ࡰنّٜىٰ يَكُونُ لِے غُلَٰمࣱ وَلَمْ يَمْسَسْنِے بَشَرࣱ وَلَمَ ࡰكُ بَغِيّاࣰ࣌', 'قالت ࡰنى يكون لے غلم ولم يمسسنے بشر ولم ࡰك بغيا࣌', NULL, 306, 'local:warsh-text.json'),
  ('warsh-19-20', 'warsh', 19, 20, 'قَالَ كَذَٰلِكِ قَالَ رَبُّكِ هُوَ عَلَيَّ هَيِّنࣱ࣌ وَلِنَجْعَلَهُۥٓ ءَايَةࣰ لِّلنَّاسِ وَرَحْمَةࣰ مِّنَّا࣌ وَكَانَ أَمْراࣰ مَّقْضِيّاࣰ࣌', 'قال كذلك قال ربك هو علي هين࣌ ولنجعله ءاية للناس ورحمة منا࣌ وكان أمرا مقضيا࣌', NULL, 306, 'local:warsh-text.json'),
  ('warsh-19-21', 'warsh', 19, 21, '۞ فَحَمَلَتْهُ فَانتَبَذَتْ بِهِۦ مَكَاناࣰ قَصِيّاࣰ࣌', 'فحملته فانتبذت به مكانا قصيا࣌', NULL, 306, 'local:warsh-text.json'),
  ('warsh-19-22', 'warsh', 19, 22, 'فَأَجَآءَهَا ࡰ۬لْمَخَاضُ إِلَىٰ جِذْعِ ࡴ۬لنَّخْلَةِ قَالَتْ يَٰلَيْتَنِے مِتُّ قَبْلَ هَٰذَا وَكُنتُ نِسْياࣰ مَّنسِيّاࣰ࣌', 'فأجاءها ࡰلمخاض إلى جذع ࡴلنخلة قالت يليتنے مت قبل هذا وكنت نسيا منسيا࣌', NULL, 306, 'local:warsh-text.json'),
  ('warsh-19-23', 'warsh', 19, 23, 'فَنَادٜيٰهَا مِن تَحْتِهَآ أَلَّا تَحْزَنِے قَدْ جَعَلَ رَبُّكِ تَحْتَكِ سَرِيّاࣰ࣌', 'فناديها من تحتها ألا تحزنے قد جعل ربك تحتك سريا࣌', NULL, 306, 'local:warsh-text.json'),
  ('warsh-19-24', 'warsh', 19, 24, 'وَهُزِّےٓ إِلَيْكِ بِجِذْعِ ࡴ۬لنَّخْلَةِ تَسَّٰقَطْ عَلَيْكِ رُطَباࣰ جَنِيّاࣰ࣌', 'وهزے إليك بجذع ࡴلنخلة تسقط عليك رطبا جنيا࣌', NULL, 306, 'local:warsh-text.json'),
  ('warsh-19-25', 'warsh', 19, 25, 'فَكُلِے وَاشْرَبِے وَقَرِّے عَيْناࣰ࣌ فَإِمَّا تَرَيِنَّ مِنَ ࡰ۬لْبَشَرِ أَحَداࣰ فَقُولِےٓ إِنِّے نَذَرْتُ لِلرَّحْمَٰنِ صَوْماࣰ فَلَنُ ࡳكَلِّمَ ࡰ۬لْيَوْمَ إِنسِيّاࣰ࣌', 'فكلے واشربے وقرے عينا࣌ فإما ترين من ࡰلبشر أحدا فقولے إنے نذرت للرحمن صوما فلن ࡳكلم ࡰليوم إنسيا࣌', NULL, 307, 'local:warsh-text.json'),
  ('warsh-19-26', 'warsh', 19, 26, 'فَأَتَتْ بِهِۦ قَوْمَهَا تَحْمِلُهُۥ࣌ قَالُواْ يَٰمَرْيَمُ لَقَدْ جِئْتِ شَيْـٔاࣰ فَرِيّاࣰ࣌', 'فأتت به قومها تحمله࣌ قالوا يمريم لقد جئت شيا فريا࣌', NULL, 307, 'local:warsh-text.json'),
  ('warsh-19-27', 'warsh', 19, 27, 'يَٰٓأُخْتَ هَٰرُونَ مَا كَانَ أَبُوكِ ࡴٜمْرَأَ سَوْءࣲ وَمَا كَانَتُ ࡳمُّكِ بَغِيّاࣰ࣌', 'يأخت هرون ما كان أبوك ࡴمرأ سوء وما كانت ࡳمك بغيا࣌', NULL, 307, 'local:warsh-text.json'),
  ('warsh-19-28', 'warsh', 19, 28, 'فَأَشَارَتِ ࡴلَيْهِ࣌ قَالُواْ كَيْفَ نُكَلِّمُ مَن كَانَ فِے ࡴ۬لْمَهْدِ صَبِيّاࣰ࣌', 'فأشارت ࡴليه࣌ قالوا كيف نكلم من كان فے ࡴلمهد صبيا࣌', NULL, 307, 'local:warsh-text.json'),
  ('warsh-19-29', 'warsh', 19, 29, 'قَالَ إِنِّے عَبْدُ ࡲ۬للَّهِ ءَاتٜيٰنِيَ ࡰ۬لْكِتَٰبَ وَجَعَلَنِے نَبِيٓـٔاࣰ', 'قال إنے عبد ࡲلله ءاتيني ࡰلكتب وجعلنے نبيا', NULL, 307, 'local:warsh-text.json'),
  ('warsh-19-30', 'warsh', 19, 30, 'وَجَعَلَنِے مُبَٰرَكاً ࡰيْنَ مَا كُنتُ وَأَوْصٜـٰنِے بِالصَّلَوٰةِ وَالزَّكَوٰةِ مَا دُمْتُ حَيّاࣰ', 'وجعلنے مبركا ࡰين ما كنت وأوصنے بالصلوة والزكوة ما دمت حيا', NULL, 307, 'local:warsh-text.json'),
  ('warsh-19-31', 'warsh', 19, 31, 'وَبَرّاَۢ بِوَٰلِدَتِے࣌ وَلَمْ يَجْعَلْنِے جَبَّاراࣰ شَقِيّاࣰ࣌', 'وبرا بولدتے࣌ ولم يجعلنے جبارا شقيا࣌', NULL, 307, 'local:warsh-text.json'),
  ('warsh-19-32', 'warsh', 19, 32, 'وَالسَّلَٰمُ عَلَيَّ يَوْمَ وُلِدتُّ وَيَوْمَ أَمُوتُ وَيَوْمَ أُبْعَثُ حَيّاࣰ࣌', 'والسلم علي يوم ولدت ويوم أموت ويوم أبعث حيا࣌', NULL, 307, 'local:warsh-text.json'),
  ('warsh-19-33', 'warsh', 19, 33, 'ذَٰلِكَ عِيسَى ࡰٜبْنُ مَرْيَمَ࣌ قَوْلُ ࡲ۬لْحَقِّ ࡴ۬لذِے فِيهِ يَمْتَرُونَ࣌', 'ذلك عيسى ࡰبن مريم࣌ قول ࡲلحق ࡴلذے فيه يمترون࣌', NULL, 307, 'local:warsh-text.json'),
  ('warsh-19-34', 'warsh', 19, 34, 'مَا كَانَ لِلهِ أَنْ يَّتَّخِذَ مِنْ وَّلَدࣲ࣌ سُبْحَٰنَهُۥٓ࣌ إِذَا قَضٜىٰٓ أَمْراࣰ فَإِنَّمَا يَقُولُ لَهُۥ كُن࣌ فَيَكُونُ࣌', 'ما كان لله أن يتخذ من ولد࣌ سبحنه࣌ إذا قضى أمرا فإنما يقول له كن࣌ فيكون࣌', NULL, 307, 'local:warsh-text.json'),
  ('warsh-19-35', 'warsh', 19, 35, 'وَأَنَّ ࡰ۬للَّهَ رَبِّے وَرَبُّكُمْ فَاعْبُدُوهُ࣌ هَٰذَا صِرَٰطࣱ مُّسْتَقِيمࣱ࣌', 'وأن ࡰلله ربے وربكم فاعبدوه࣌ هذا صرط مستقيم࣌', NULL, 307, 'local:warsh-text.json'),
  ('warsh-19-36', 'warsh', 19, 36, 'فَاخْتَلَفَ ࡰ۬لَاحْزَابُ مِنۢ بَيْنِهِمْ࣌ فَوَيْلࣱ لِّلذِينَ كَفَرُواْ مِن مَّشْهَدِ يَوْمٍ عَظِيمٍ࣌', 'فاختلف ࡰلاحزاب من بينهم࣌ فويل للذين كفروا من مشهد يوم عظيم࣌', NULL, 307, 'local:warsh-text.json'),
  ('warsh-19-37', 'warsh', 19, 37, 'ࡰسْمِعْ بِهِمْ وَأَبْصِرْ يَوْمَ يَاتُونَنَا࣌ لَٰكِنِ ࡴ۬لظَّٰلِمُونَ ࡰ۬لْيَوْمَ فِے ضَلَٰلࣲ مُّبِينࣲ࣌', 'ࡰسمع بهم وأبصر يوم ياتوننا࣌ لكن ࡴلظلمون ࡰليوم فے ضلل مبين࣌', NULL, 307, 'local:warsh-text.json'),
  ('warsh-19-38', 'warsh', 19, 38, 'وَأَنذِرْهُمْ يَوْمَ ࡰ۬لْحَسْرَةِ إِذْ قُضِيَ ࡰ۬لَامْرُ وَهُمْ فِے غَفْلَةࣲ وَهُمْ لَا يُومِنُونَ࣌', 'وأنذرهم يوم ࡰلحسرة إذ قضي ࡰلامر وهم فے غفلة وهم لا يومنون࣌', NULL, 308, 'local:warsh-text.json'),
  ('warsh-19-39', 'warsh', 19, 39, 'إِنَّا نَحْنُ نَرِثُ ࡲ۬لَارْضَ وَمَنْ عَلَيْهَا࣌ وَإِلَيْنَا يُرْجَعُونَ࣌', 'إنا نحن نرث ࡲلارض ومن عليها࣌ وإلينا يرجعون࣌', NULL, 308, 'local:warsh-text.json'),
  ('warsh-19-40', 'warsh', 19, 40, '۞ وَاذْكُرْ فِے ࡴ۬لْكِتَٰبِ إِبْرَٰهِيمَ', 'واذكر فے ࡴلكتب إبرهيم', NULL, 308, 'local:warsh-text.json'),
  ('warsh-19-41', 'warsh', 19, 41, 'إِنَّهُۥ كَانَ صِدِّيقاࣰ نَّبِيٓـٔاً', 'إنه كان صديقا نبيا', NULL, 308, 'local:warsh-text.json'),
  ('warsh-19-42', 'warsh', 19, 42, 'ࡴذْ قَالَ لِأَبِيهِ يَٰٓأَبَتِ لِمَ تَعْبُدُ مَا لَا يَسْمَعُ وَلَا يُبْصِرُ وَلَا يُغْنِے عَنكَ شَيْـٔاࣰ࣌', 'ࡴذ قال لأبيه يأبت لم تعبد ما لا يسمع ولا يبصر ولا يغنے عنك شيا࣌', NULL, 308, 'local:warsh-text.json'),
  ('warsh-19-43', 'warsh', 19, 43, 'يَٰٓأَبَتِ إِنِّے قَدْ جَآءَنِے مِنَ ࡰ۬لْعِلْمِ مَا لَمْ يَاتِكَ فَاتَّبِعْنِےٓ أَهْدِكَ صِرَٰطاࣰ سَوِيّاࣰ࣌', 'يأبت إنے قد جاءنے من ࡰلعلم ما لم ياتك فاتبعنے أهدك صرطا سويا࣌', NULL, 308, 'local:warsh-text.json'),
  ('warsh-19-44', 'warsh', 19, 44, 'يَٰٓأَبَتِ لَا تَعْبُدِ ࡴ۬لشَّيْطَٰنَ࣌ إِنَّ ࡰ۬لشَّيْطَٰنَ كَانَ لِلرَّحْمَٰنِ عَصِيّاࣰ࣌', 'يأبت لا تعبد ࡴلشيطن࣌ إن ࡰلشيطن كان للرحمن عصيا࣌', NULL, 308, 'local:warsh-text.json'),
  ('warsh-19-45', 'warsh', 19, 45, 'يَٰٓأَبَتِ إِنِّيَ أَخَافُ أَنْ يَّمَسَّكَ عَذَابࣱ مِّنَ ࡰ۬لرَّحْمَٰنِ فَتَكُونَ لِلشَّيْطَٰنِ وَلِيّاࣰ࣌', 'يأبت إني أخاف أن يمسك عذاب من ࡰلرحمن فتكون للشيطن وليا࣌', NULL, 308, 'local:warsh-text.json'),
  ('warsh-19-46', 'warsh', 19, 46, 'قَالَ أَرَاغِبٌ ࡰنتَ عَنَ اٰلِهَتِے࣌ يَٰٓإِبْرَٰهِيمُ لَئِن لَّمْ تَنتَهِ لَأَرْجُمَنَّكَ وَاهْجُرْنِے مَلِيّاࣰ࣌', 'قال أراغب ࡰنت عن الهتے࣌ يإبرهيم لئن لم تنته لأرجمنك واهجرنے مليا࣌', NULL, 308, 'local:warsh-text.json'),
  ('warsh-19-47', 'warsh', 19, 47, 'قَالَ سَلَٰمٌ عَلَيْكَ سَأَسْتَغْفِرُ لَكَ رَبِّيَ إِنَّهُۥ كَانَ بِے حَفِيّاࣰ', 'قال سلم عليك سأستغفر لك ربي إنه كان بے حفيا', NULL, 308, 'local:warsh-text.json'),
  ('warsh-19-48', 'warsh', 19, 48, 'وَأَعْتَزِلُكُمْ وَمَا تَدْعُونَ مِن دُونِ ࡴ۬للَّهِ وَأَدْعُواْ رَبِّے عَسٜىٰٓ أَلَّآ أَكُونَ بِدُعَآءِ رَبِّے شَقِيّاࣰ࣌', 'وأعتزلكم وما تدعون من دون ࡴلله وأدعوا ربے عسى ألا أكون بدعاء ربے شقيا࣌', NULL, 308, 'local:warsh-text.json'),
  ('warsh-19-49', 'warsh', 19, 49, 'فَلَمَّا ࡰٜعْتَزَلَهُمْ وَمَا يَعْبُدُونَ مِن دُونِ ࡴ۬للَّهِ وَهَبْنَا لَهُۥٓ إِسْحَٰقَ وَيَعْقُوبَ࣌ وَكُلّاࣰ جَعَلْنَا نَبِيٓـٔاࣰ࣌', 'فلما ࡰعتزلهم وما يعبدون من دون ࡴلله وهبنا له إسحق ويعقوب࣌ وكلا جعلنا نبيا࣌', NULL, 308, 'local:warsh-text.json'),
  ('warsh-19-50', 'warsh', 19, 50, 'وَوَهَبْنَا لَهُم مِّن رَّحْمَتِنَا وَجَعَلْنَا لَهُمْ لِسَانَ صِدْقٍ عَلِيّاࣰ࣌', 'ووهبنا لهم من رحمتنا وجعلنا لهم لسان صدق عليا࣌', NULL, 308, 'local:warsh-text.json'),
  ('warsh-19-51', 'warsh', 19, 51, 'وَاذْكُرْ فِے ࡴ۬لْكِتَٰبِ مُوسٜىٰٓ إِنَّهُۥ كَانَ مُخْلِصاࣰ وَكَانَ رَسُولاࣰ نَّبِيٓـٔاࣰ࣌', 'واذكر فے ࡴلكتب موسى إنه كان مخلصا وكان رسولا نبيا࣌', NULL, 308, 'local:warsh-text.json'),
  ('warsh-19-52', 'warsh', 19, 52, 'وَنَٰدَيْنَٰهُ مِن جَانِبِ ࡴ۬لطُّورِ ࡴ۬لَايْمَنِ وَقَرَّبْنَٰهُ نَجِيّاࣰ࣌', 'وندينه من جانب ࡴلطور ࡴلايمن وقربنه نجيا࣌', NULL, 309, 'local:warsh-text.json'),
  ('warsh-19-53', 'warsh', 19, 53, 'وَوَهَبْنَا لَهُۥ مِن رَّحْمَتِنَآ أَخَاهُ هَٰرُونَ نَبِيٓـٔاࣰ࣌', 'ووهبنا له من رحمتنا أخاه هرون نبيا࣌', NULL, 309, 'local:warsh-text.json'),
  ('warsh-19-54', 'warsh', 19, 54, 'وَاذْكُرْ فِے ࡴ۬لْكِتَٰبِ إِسْمَٰعِيلَ إِنَّهُۥ كَانَ صَادِقَ ࡰ۬لْوَعْدِ وَكَانَ رَسُولاࣰ نَّبِيٓـٔاࣰ', 'واذكر فے ࡴلكتب إسمعيل إنه كان صادق ࡰلوعد وكان رسولا نبيا', NULL, 309, 'local:warsh-text.json'),
  ('warsh-19-55', 'warsh', 19, 55, 'وَكَانَ يَامُرُ أَهْلَهُۥ بِالصَّلَوٰةِ وَالزَّكَوٰةِ࣌ وَكَانَ عِندَ رَبِّهِۦ مَرْضِيّاࣰ࣌', 'وكان يامر أهله بالصلوة والزكوة࣌ وكان عند ربه مرضيا࣌', NULL, 309, 'local:warsh-text.json'),
  ('warsh-19-56', 'warsh', 19, 56, 'وَاذْكُرْ فِے ࡴ۬لْكِتَٰبِ إِدْرِيسَ إِنَّهُۥ كَانَ صِدِّيقاࣰ نَّبِيٓـٔاࣰ࣌', 'واذكر فے ࡴلكتب إدريس إنه كان صديقا نبيا࣌', NULL, 309, 'local:warsh-text.json'),
  ('warsh-19-57', 'warsh', 19, 57, 'وَرَفَعْنَٰهُ مَكَاناً عَلِيّاً࣌', 'ورفعنه مكانا عليا࣌', NULL, 309, 'local:warsh-text.json'),
  ('warsh-19-58', 'warsh', 19, 58, 'ࡳوْلَٰٓئِكَ ࡰ۬لذِينَ أَنْعَمَ ࡰ۬للَّهُ عَلَيْهِم مِّنَ ࡰ۬لنَّبِيٓـِٕۑنَ مِن ذُرِّيَّةِ ءَادَمَ وَمِمَّنْ حَمَلْنَا مَعَ نُوحࣲ وَمِن ذُرِّيَّةِ إِبْرَٰهِيمَ وَإِسْرَآءِيلَ وَمِمَّنْ هَدَيْنَا وَاجْتَبَيْنَآ࣌ إِذَا تُتْلٜىٰ عَلَيْهِمُۥٓ ءَايَٰتُ ࡲ۬لرَّحْمَٰنِ خَرُّواْ سُجَّداࣰ وَبُكِيّاࣰ࣌۩', 'ࡳولئك ࡰلذين أنعم ࡰلله عليهم من ࡰلنبيۑن من ذرية ءادم وممن حملنا مع نوح ومن ذرية إبرهيم وإسراءيل وممن هدينا واجتبينا࣌ إذا تتلى عليهم ءايت ࡲلرحمن خروا سجدا وبكيا࣌', NULL, 309, 'local:warsh-text.json'),
  ('warsh-19-59', 'warsh', 19, 59, '۞ فَخَلَفَ مِنۢ بَعْدِهِمْ خَلْفٌ ࡰضَاعُواْ ࡲ۬لصَّلَوٰةَ وَاتَّبَعُواْ ࡲ۬لشَّهَوَٰتِ فَسَوْفَ يَلْقَوْنَ غَيّاً', 'فخلف من بعدهم خلف ࡰضاعوا ࡲلصلوة واتبعوا ࡲلشهوت فسوف يلقون غيا', NULL, 309, 'local:warsh-text.json'),
  ('warsh-19-60', 'warsh', 19, 60, 'ࡴلَّا مَن تَابَ وَءَامَنَ وَعَمِلَ صَٰلِحاࣰ فَأُوْلَٰٓئِكَ يَدْخُلُونَ ࡰ۬لْجَنَّةَ وَلَا يُظْلَمُونَ شَيْـٔاࣰ', 'ࡴلا من تاب وءامن وعمل صلحا فأولئك يدخلون ࡰلجنة ولا يظلمون شيا', NULL, 309, 'local:warsh-text.json'),
  ('warsh-19-61', 'warsh', 19, 61, 'جَنَّٰتِ عَدْنٍ ࡴ۬لتِے وَعَدَ ࡰ۬لرَّحْمَٰنُ عِبَادَهُۥ بِالْغَيْبِ࣌ إِنَّهُۥ كَانَ وَعْدُهُۥ مَاتِيّاࣰ࣌', 'جنت عدن ࡴلتے وعد ࡰلرحمن عباده بالغيب࣌ إنه كان وعده ماتيا࣌', NULL, 309, 'local:warsh-text.json'),
  ('warsh-19-62', 'warsh', 19, 62, 'لَّا يَسْمَعُونَ فِيهَا لَغْواً࣌ ࡴلَّا سَلَٰماࣰ࣌ وَلَهُمْ رِزْقُهُمْ فِيهَا بُكْرَةࣰ وَعَشِيّاࣰ࣌', 'لا يسمعون فيها لغوا࣌ ࡴلا سلما࣌ ولهم رزقهم فيها بكرة وعشيا࣌', NULL, 309, 'local:warsh-text.json'),
  ('warsh-19-63', 'warsh', 19, 63, 'تِلْكَ ࡰ۬لْجَنَّةُ ࡲ۬لتِے نُورِثُ مِنْ عِبَادِنَا مَن كَانَ تَقِيّاࣰ࣌', 'تلك ࡰلجنة ࡲلتے نورث من عبادنا من كان تقيا࣌', NULL, 309, 'local:warsh-text.json'),
  ('warsh-19-64', 'warsh', 19, 64, 'وَمَا نَتَنَزَّلُ إِلَّا بِأَمْرِ رَبِّكَ࣌ لَهُۥ مَا بَيْنَ أَيْدِينَا وَمَا خَلْفَنَا وَمَا بَيْنَ ذَٰلِكَ࣌ وَمَا كَانَ رَبُّكَ نَسِيّاࣰ࣌', 'وما نتنزل إلا بأمر ربك࣌ له ما بين أيدينا وما خلفنا وما بين ذلك࣌ وما كان ربك نسيا࣌', NULL, 309, 'local:warsh-text.json'),
  ('warsh-19-65', 'warsh', 19, 65, 'رَّبُّ ࡲ۬لسَّمَٰوَٰتِ وَالَارْضِ وَمَا بَيْنَهُمَا فَاعْبُدْهُ وَاصْطَبِرْ لِعِبَٰدَتِهِۦ࣌ هَلْ تَعْلَمُ لَهُۥ سَمِيّاࣰ࣌', 'رب ࡲلسموت والارض وما بينهما فاعبده واصطبر لعبدته࣌ هل تعلم له سميا࣌', NULL, 310, 'local:warsh-text.json'),
  ('warsh-19-66', 'warsh', 19, 66, 'وَيَقُولُ ࡲ۬لِانسَٰنُ أَࢇذَا مَا مِتُّ لَسَوْفَ أُخْرَجُ حَيّاً࣌', 'ويقول ࡲلانسن أࢇذا ما مت لسوف أخرج حيا࣌', NULL, 310, 'local:warsh-text.json'),
  ('warsh-19-67', 'warsh', 19, 67, 'ࡰوَلَا يَذْكُرُ ࡲ۬لِانسَٰنُ أَنَّا خَلَقْنَٰهُ مِن قَبْلُ وَلَمْ يَكُ شَيْـٔاࣰ࣌', 'ࡰولا يذكر ࡲلانسن أنا خلقنه من قبل ولم يك شيا࣌', NULL, 310, 'local:warsh-text.json'),
  ('warsh-19-68', 'warsh', 19, 68, 'فَوَرَبِّكَ لَنَحْشُرَنَّهُمْ وَالشَّيَٰطِينَ ثُمَّ لَنُحْضِرَنَّهُمْ حَوْلَ جَهَنَّمَ جُثِيّاࣰ࣌', 'فوربك لنحشرنهم والشيطين ثم لنحضرنهم حول جهنم جثيا࣌', NULL, 310, 'local:warsh-text.json'),
  ('warsh-19-69', 'warsh', 19, 69, 'ثُمَّ لَنَنزِعَنَّ مِن كُلِّ شِيعَةٍ ࡰيُّهُمُۥٓ أَشَدُّ عَلَى ࡰ۬لرَّحْمَٰنِ عُتِيّاࣰ࣌', 'ثم لننزعن من كل شيعة ࡰيهم أشد على ࡰلرحمن عتيا࣌', NULL, 310, 'local:warsh-text.json'),
  ('warsh-19-70', 'warsh', 19, 70, 'ثُمَّ لَنَحْنُ أَعْلَمُ بِالذِينَ هُمُۥٓ أَوْلٜىٰ بِهَا صُلِيّاࣰ࣌', 'ثم لنحن أعلم بالذين هم أولى بها صليا࣌', NULL, 310, 'local:warsh-text.json'),
  ('warsh-19-71', 'warsh', 19, 71, 'وَإِن مِّنكُمُۥٓ إِلَّا وَارِدُهَا كَانَ عَلَىٰ رَبِّكَ حَتْماࣰ مَّقْضِيّاࣰ࣌', 'وإن منكم إلا واردها كان على ربك حتما مقضيا࣌', NULL, 310, 'local:warsh-text.json'),
  ('warsh-19-72', 'warsh', 19, 72, 'ثُمَّ نُنَجِّے ࡴ۬لذِينَ ࡰٜتَّقَواْ وَّنَذَرُ ࡲ۬لظَّٰلِمِينَ فِيهَا جُثِيّاࣰ࣌', 'ثم ننجے ࡴلذين ࡰتقوا ونذر ࡲلظلمين فيها جثيا࣌', NULL, 310, 'local:warsh-text.json'),
  ('warsh-19-73', 'warsh', 19, 73, 'وَإِذَا تُتْلٜىٰ عَلَيْهِمُۥٓ ءَايَٰتُنَا بَيِّنَٰتࣲ قَالَ ࡰ۬لذِينَ كَفَرُواْ لِلذِينَ ءَامَنُوٓاْ أَيُّ ࡲ۬لْفَرِيقَيْنِ خَيْرࣱ مَّقَاماࣰ وَأَحْسَنُ نَدِيّاࣰ࣌', 'وإذا تتلى عليهم ءايتنا بينت قال ࡰلذين كفروا للذين ءامنوا أي ࡲلفريقين خير مقاما وأحسن نديا࣌', NULL, 310, 'local:warsh-text.json'),
  ('warsh-19-74', 'warsh', 19, 74, 'وَكَمَ ࡰهْلَكْنَا قَبْلَهُم مِّن قَرْنٍ هُمُۥٓ أَحْسَنُ أَثَٰثاࣰ وَرِءْياࣰ࣌', 'وكم ࡰهلكنا قبلهم من قرن هم أحسن أثثا ورءيا࣌', NULL, 310, 'local:warsh-text.json'),
  ('warsh-19-75', 'warsh', 19, 75, '۞ قُلْ مَن كَانَ فِے ࡴ۬لضَّلَٰلَةِ فَلْيَمْدُدْ لَهُ ࡲ۬لرَّحْمَٰنُ مَدّاً࣌', 'قل من كان فے ࡴلضللة فليمدد له ࡲلرحمن مدا࣌', NULL, 310, 'local:warsh-text.json'),
  ('warsh-19-76', 'warsh', 19, 76, 'حَتَّىٰٓ إِذَا رَأَوْاْ مَا يُوعَدُونَ إِمَّا ࡰ۬لْعَذَابَ وَإِمَّا ࡰ۬لسَّاعَةَ فَسَيَعْلَمُونَ مَنْ هُوَ شَرࣱّ مَّكَاناࣰ وَأَضْعَفُ جُنداࣰ࣌', 'حتى إذا رأوا ما يوعدون إما ࡰلعذاب وإما ࡰلساعة فسيعلمون من هو شر مكانا وأضعف جندا࣌', NULL, 310, 'local:warsh-text.json'),
  ('warsh-19-77', 'warsh', 19, 77, 'وَيَزِيدُ ࡲ۬للَّهُ ࡲ۬لذِينَ ࡰٜهْتَدَوْاْ هُدىࣰ࣌ وَالْبَٰقِيَٰتُ ࡲ۬لصَّٰلِحَٰتُ خَيْرٌ عِندَ رَبِّكَ ثَوَاباࣰ وَخَيْرࣱ مَّرَدّاً࣌', 'ويزيد ࡲلله ࡲلذين ࡰهتدوا هدى࣌ والبقيت ࡲلصلحت خير عند ربك ثوابا وخير مردا࣌', NULL, 310, 'local:warsh-text.json'),
  ('warsh-19-78', 'warsh', 19, 78, 'ࡰفَرَٰٓيْتَ ࡰ۬لذِے كَفَرَ بِـَٔايَٰتِنَا وَقَالَ لَأُوتَيَنَّ مَالاࣰ وَوَلَداً', 'ࡰفريت ࡰلذے كفر بايتنا وقال لأوتين مالا وولدا', NULL, 311, 'local:warsh-text.json'),
  ('warsh-19-79', 'warsh', 19, 79, 'ࡰطَّلَعَ ࡰ۬لْغَيْبَ أَمِ ࡴٜتَّخَذَ عِندَ ࡰ۬لرَّحْمَٰنِ عَهْداࣰ', 'ࡰطلع ࡰلغيب أم ࡴتخذ عند ࡰلرحمن عهدا', NULL, 311, 'local:warsh-text.json'),
  ('warsh-19-80', 'warsh', 19, 80, 'كَلَّا࣌ سَنَكْتُبُ مَا يَقُولُ وَنَمُدُّ لَهُۥ مِنَ ࡰ۬لْعَذَابِ مَدّاࣰ࣌', 'كلا࣌ سنكتب ما يقول ونمد له من ࡰلعذاب مدا࣌', NULL, 311, 'local:warsh-text.json'),
  ('warsh-19-81', 'warsh', 19, 81, 'وَنَرِثُهُۥ مَا يَقُولُ وَيَاتِينَا فَرْداࣰ࣌', 'ونرثه ما يقول وياتينا فردا࣌', NULL, 311, 'local:warsh-text.json'),
  ('warsh-19-82', 'warsh', 19, 82, 'وَاتَّخَذُواْ مِن دُونِ ࡴ۬للَّهِ ءَالِهَةࣰ لِّيَكُونُواْ لَهُمْ عِزّاࣰ', 'واتخذوا من دون ࡴلله ءالهة ليكونوا لهم عزا', NULL, 311, 'local:warsh-text.json'),
  ('warsh-19-83', 'warsh', 19, 83, 'كَلَّا࣌ سَيَكْفُرُونَ بِعِبَادَتِهِمْ وَيَكُونُونَ عَلَيْهِمْ ضِدّاً࣌', 'كلا࣌ سيكفرون بعبادتهم ويكونون عليهم ضدا࣌', NULL, 311, 'local:warsh-text.json'),
  ('warsh-19-84', 'warsh', 19, 84, 'ࡰلَمْ تَرَ أَنَّآ أَرْسَلْنَا ࡰ۬لشَّيَٰطِينَ عَلَى ࡰ۬لْكٜـٰفِرِينَ تَؤُزُّهُمُۥٓ أَزّاࣰ࣌', 'ࡰلم تر أنا أرسلنا ࡰلشيطين على ࡰلكفرين تؤزهم أزا࣌', NULL, 311, 'local:warsh-text.json'),
  ('warsh-19-85', 'warsh', 19, 85, 'فَلَا تَعْجَلْ عَلَيْهِمُۥٓ࣌ إِنَّمَا نَعُدُّ لَهُمْ عَدّاࣰ࣌', 'فلا تعجل عليهم࣌ إنما نعد لهم عدا࣌', NULL, 311, 'local:warsh-text.json'),
  ('warsh-19-86', 'warsh', 19, 86, 'يَوْمَ نَحْشُرُ ࡲ۬لْمُتَّقِينَ إِلَى ࡰ۬لرَّحْمَٰنِ وَفْداࣰ', 'يوم نحشر ࡲلمتقين إلى ࡰلرحمن وفدا', NULL, 311, 'local:warsh-text.json'),
  ('warsh-19-87', 'warsh', 19, 87, 'وَنَسُوقُ ࡲ۬لْمُجْرِمِينَ إِلَىٰ جَهَنَّمَ وِرْداࣰ࣌', 'ونسوق ࡲلمجرمين إلى جهنم وردا࣌', NULL, 311, 'local:warsh-text.json'),
  ('warsh-19-88', 'warsh', 19, 88, 'لَّا يَمْلِكُونَ ࡰ۬لشَّفَٰعَةَ إِلَّا مَنِ ࡴٜتَّخَذَ عِندَ ࡰ۬لرَّحْمَٰنِ عَهْداࣰ࣌', 'لا يملكون ࡰلشفعة إلا من ࡴتخذ عند ࡰلرحمن عهدا࣌', NULL, 311, 'local:warsh-text.json'),
  ('warsh-19-89', 'warsh', 19, 89, 'وَقَالُواْ ࡲٜتَّخَذَ ࡰ۬لرَّحْمَٰنُ وَلَداࣰ࣌', 'وقالوا ࡲتخذ ࡰلرحمن ولدا࣌', NULL, 311, 'local:warsh-text.json'),
  ('warsh-19-90', 'warsh', 19, 90, 'لَّقَدْ جِئْتُمْ شَيْـٔاً ࡴدّاࣰ', 'لقد جئتم شيا ࡴدا', NULL, 311, 'local:warsh-text.json'),
  ('warsh-19-91', 'warsh', 19, 91, 'يَكَادُ ࡲ۬لسَّمَٰوَٰتُ يَتَفَطَّرْنَ مِنْهُ وَتَنشَقُّ ࡲ۬لَارْضُ وَتَخِرُّ ࡲ۬لْجِبَالُ هَدّاً', 'يكاد ࡲلسموت يتفطرن منه وتنشق ࡲلارض وتخر ࡲلجبال هدا', NULL, 311, 'local:warsh-text.json'),
  ('warsh-19-92', 'warsh', 19, 92, 'ࡰن دَعَوْاْ لِلرَّحْمَٰنِ وَلَداࣰ࣌', 'ࡰن دعوا للرحمن ولدا࣌', NULL, 311, 'local:warsh-text.json'),
  ('warsh-19-93', 'warsh', 19, 93, 'وَمَا يَنۢبَغِے لِلرَّحْمَٰنِ أَنْ يَّتَّخِذَ وَلَداً࣌', 'وما ينبغے للرحمن أن يتخذ ولدا࣌', NULL, 311, 'local:warsh-text.json'),
  ('warsh-19-94', 'warsh', 19, 94, 'ࡴن كُلُّ مَن فِے ࡴ۬لسَّمَٰوَٰتِ وَالَارْضِ إِلَّآ ءَاتِے ࡴ۬لرَّحْمَٰنِ عَبْداࣰ࣌', 'ࡴن كل من فے ࡴلسموت والارض إلا ءاتے ࡴلرحمن عبدا࣌', NULL, 311, 'local:warsh-text.json'),
  ('warsh-19-95', 'warsh', 19, 95, 'لَّقَدَ ࡰحْصٜيٰهُمْ وَعَدَّهُمْ عَدّاࣰ࣌', 'لقد ࡰحصيهم وعدهم عدا࣌', NULL, 311, 'local:warsh-text.json'),
  ('warsh-19-96', 'warsh', 19, 96, 'وَكُلُّهُمُۥٓ ءَاتِيهِ يَوْمَ ࡰ۬لْقِيَٰمَةِ فَرْداً࣌', 'وكلهم ءاتيه يوم ࡰلقيمة فردا࣌', NULL, 311, 'local:warsh-text.json'),
  ('warsh-19-97', 'warsh', 19, 97, 'ࡴنَّ ࡰ۬لذِينَ ءَامَنُواْ وَعَمِلُواْ ࡲ۬لصَّٰلِحَٰتِ سَيَجْعَلُ لَهُمُ ࡲ۬لرَّحْمَٰنُ وُدّاࣰ࣌', 'ࡴن ࡰلذين ءامنوا وعملوا ࡲلصلحت سيجعل لهم ࡲلرحمن ودا࣌', NULL, 312, 'local:warsh-text.json'),
  ('warsh-19-98', 'warsh', 19, 98, 'فَإِنَّمَا يَسَّرْنَٰهُ بِلِسَانِكَ لِتُبَشِّرَ بِهِ ࡴ۬لْمُتَّقِينَ وَتُنذِرَ بِهِۦ قَوْماࣰ لُّدّاࣰ࣌', 'فإنما يسرنه بلسانك لتبشر به ࡴلمتقين وتنذر به قوما لدا࣌', NULL, 312, 'local:warsh-text.json'),
  ('warsh-19-99', 'warsh', 19, 99, 'وَكَمَ ࡰهْلَكْنَا قَبْلَهُم مِّن قَرْنٍ هَلْ تُحِسُّ مِنْهُم مِّنَ ࡰحَدٍ ࡰوْ تَسْمَعُ لَهُمْ رِكْزاࣰ࣌', 'وكم ࡰهلكنا قبلهم من قرن هل تحس منهم من ࡰحد ࡰو تسمع لهم ركزا࣌', NULL, 312, 'local:warsh-text.json'),
  ('warsh-20-1', 'warsh', 20, 1, 'طَهٜ࣌ مَآ أَنزَلْنَا عَلَيْكَ ࡰ۬لْقُرْءَانَ لِتَشْقٜىٰٓ', 'طه࣌ ما أنزلنا عليك ࡰلقرءان لتشقى', NULL, 312, 'local:warsh-text.json'),
  ('warsh-20-2', 'warsh', 20, 2, 'إِلَّا تَذْكِرَةࣰ لِّمَنْ يَّخْشٜىٰ࣌', 'إلا تذكرة لمن يخشى࣌', NULL, 312, 'local:warsh-text.json'),
  ('warsh-20-3', 'warsh', 20, 3, 'تَنزِيلاࣰ مِّمَّنْ خَلَقَ ࡰ۬لَارْضَ وَالسَّمَٰوَٰتِ ࡴ۬لْعُلَى࣌', 'تنزيلا ممن خلق ࡰلارض والسموت ࡴلعلى࣌', NULL, 312, 'local:warsh-text.json'),
  ('warsh-20-4', 'warsh', 20, 4, 'ࡰ۬لرَّحْمَٰنُ عَلَى ࡰ۬لْعَرْشِ ࡴٜسْتَوٜىٰ࣌', 'ࡰلرحمن على ࡰلعرش ࡴستوى࣌', NULL, 312, 'local:warsh-text.json'),
  ('warsh-20-5', 'warsh', 20, 5, 'لَهُۥ مَا فِے ࡴ۬لسَّمَٰوَٰتِ وَمَا فِے ࡴ۬لَارْضِ وَمَا بَيْنَهُمَا وَمَا تَحْتَ ࡰ۬لثَّرٜىٰ࣌', 'له ما فے ࡴلسموت وما فے ࡴلارض وما بينهما وما تحت ࡰلثرى࣌', NULL, 312, 'local:warsh-text.json'),
  ('warsh-20-6', 'warsh', 20, 6, 'وَإِن تَجْهَرْ بِالْقَوْلِ فَإِنَّهُۥ يَعْلَمُ ࡲ۬لسِّرَّ وَأَخْفَى࣌', 'وإن تجهر بالقول فإنه يعلم ࡲلسر وأخفى࣌', NULL, 312, 'local:warsh-text.json'),
  ('warsh-20-7', 'warsh', 20, 7, 'ࡰ۬للَّهُ لَآ إِلَٰهَ إِلَّا هُوَ࣌ لَهُ ࡲ۬لَاسْمَآءُ ࡲ۬لْحُسْنٜىٰ࣌', 'ࡰلله لا إله إلا هو࣌ له ࡲلاسماء ࡲلحسنى࣌', NULL, 312, 'local:warsh-text.json'),
  ('warsh-20-8', 'warsh', 20, 8, 'وَهَلَ ࡰتٜيٰكَ حَدِيثُ مُوسٜىٰٓ', 'وهل ࡰتيك حديث موسى', NULL, 312, 'local:warsh-text.json'),
  ('warsh-20-9', 'warsh', 20, 9, 'إِذْ رٜءٜا نَاراࣰ فَقَالَ لِأَهْلِهِ ࡴ࢈مْكُثُوٓاْ إِنِّيَ ءَانَسْتُ نَاراࣰ لَّعَلِّيَ ءَاتِيكُم مِّنْهَا بِقَبَسٍ ࡰوَ ࡰجِدُ عَلَى ࡰ۬لنّٜارِ هُدىࣰ࣌', 'إذ رءا نارا فقال لأهله ࡴ࢈مكثوا إني ءانست نارا لعلي ءاتيكم منها بقبس ࡰو ࡰجد على ࡰلنار هدى࣌', NULL, 312, 'local:warsh-text.json'),
  ('warsh-20-10', 'warsh', 20, 10, 'فَلَمَّآ أَتٜيٰهَا نُودِيَ يَٰمُوسٜىٰٓ', 'فلما أتيها نودي يموسى', NULL, 312, 'local:warsh-text.json'),
  ('warsh-20-11', 'warsh', 20, 11, 'إِنِّيَ أَنَا رَبُّكَ فَاخْلَعْ نَعْلَيْكَ إِنَّكَ بِالْوَادِ ࡴ۬لْمُقَدَّسِ طُوٜىٰ࣌', 'إني أنا ربك فاخلع نعليك إنك بالواد ࡴلمقدس طوى࣌', NULL, 312, 'local:warsh-text.json'),
  ('warsh-20-12', 'warsh', 20, 12, 'وَأَنَا ࡰٜخْتَرْتُكَ فَاسْتَمِعْ لِمَا يُوحٜىٰٓ', 'وأنا ࡰخترتك فاستمع لما يوحى', NULL, 313, 'local:warsh-text.json'),
  ('warsh-20-13', 'warsh', 20, 13, 'إِنَّنِيَ أَنَا ࡰ۬للَّهُ لَآ إِلَٰهَ إِلَّآ أَنَا فَاعْبُدْنِے وَأَقِمِ ࡴ۬لصَّلَوٰةَ لِذِكْرِيَ࣌', 'إنني أنا ࡰلله لا إله إلا أنا فاعبدنے وأقم ࡴلصلوة لذكري࣌', NULL, 313, 'local:warsh-text.json'),
  ('warsh-20-14', 'warsh', 20, 14, 'إِنَّ ࡰ۬لسَّاعَةَ ءَاتِيَةٌ ࡰكَادُ أُخْفِيهَا لِتُجْزٜىٰ كُلُّ نَفْسِۢ بِمَا تَسْعٜىٰ࣌', 'إن ࡰلساعة ءاتية ࡰكاد أخفيها لتجزى كل نفس بما تسعى࣌', NULL, 313, 'local:warsh-text.json'),
  ('warsh-20-15', 'warsh', 20, 15, 'فَلَا يَصُدَّنَّكَ عَنْهَا مَن لَّا يُومِنُ بِهَا وَاتَّبَعَ هَوٜيٰهُ فَتَرْدٜىٰ࣌', 'فلا يصدنك عنها من لا يومن بها واتبع هويه فتردى࣌', NULL, 313, 'local:warsh-text.json'),
  ('warsh-20-16', 'warsh', 20, 16, 'وَمَا تِلْكَ بِيَمِينِكَ يَٰمُوسٜىٰ࣌', 'وما تلك بيمينك يموسى࣌', NULL, 313, 'local:warsh-text.json'),
  ('warsh-20-17', 'warsh', 20, 17, 'قَالَ هِيَ عَصَايَ أَتَوَكَّؤُاْ عَلَيْهَا وَأَهُشُّ بِهَا عَلَىٰ غَنَمِے وَلِيَ فِيهَا مَـَٔارِبُ أُخْرٜىٰ࣌', 'قال هي عصاي أتوكؤا عليها وأهش بها على غنمے ولي فيها مارب أخرى࣌', NULL, 313, 'local:warsh-text.json'),
  ('warsh-20-18', 'warsh', 20, 18, 'قَالَ أَلْقِهَا يَٰمُوسٜىٰ࣌', 'قال ألقها يموسى࣌', NULL, 313, 'local:warsh-text.json'),
  ('warsh-20-19', 'warsh', 20, 19, 'فَأَلْقٜيٰهَا فَإِذَا هِيَ حَيَّةࣱ تَسْعٜىٰ࣌', 'فألقيها فإذا هي حية تسعى࣌', NULL, 313, 'local:warsh-text.json'),
  ('warsh-20-20', 'warsh', 20, 20, 'قَالَ خُذْهَا وَلَا تَخَفْ سَنُعِيدُهَا سِيرَتَهَا ࡰ۬لُاولٜىٰ࣌', 'قال خذها ولا تخف سنعيدها سيرتها ࡰلاولى࣌', NULL, 313, 'local:warsh-text.json'),
  ('warsh-20-21', 'warsh', 20, 21, 'وَاضْمُمْ يَدَكَ إِلَىٰ جَنَاحِكَ تَخْرُجْ بَيْضَآءَ مِنْ غَيْرِ سُوٓءٍ اٰيَةً ࡳخْرٜىٰ', 'واضمم يدك إلى جناحك تخرج بيضاء من غير سوء اية ࡳخرى', NULL, 313, 'local:warsh-text.json'),
  ('warsh-20-22', 'warsh', 20, 22, 'لِنُرِيَكَ مِنَ اٰيَٰتِنَا ࡰ۬لْكُبْرَى࣌', 'لنريك من ايتنا ࡰلكبرى࣌', NULL, 313, 'local:warsh-text.json'),
  ('warsh-20-23', 'warsh', 20, 23, 'ࡰٜذْهَبِ ࡴلَىٰ فِرْعَوْنَ إِنَّهُۥ طَغٜىٰ࣌', 'ࡰذهب ࡴلى فرعون إنه طغى࣌', NULL, 313, 'local:warsh-text.json'),
  ('warsh-20-24', 'warsh', 20, 24, 'قَالَ رَبِّ ࡴٜشْرَحْ لِے صَدْرِے', 'قال رب ࡴشرح لے صدرے', NULL, 313, 'local:warsh-text.json'),
  ('warsh-20-25', 'warsh', 20, 25, 'وَيَسِّرْ لِيَ أَمْرِے', 'ويسر لي أمرے', NULL, 313, 'local:warsh-text.json'),
  ('warsh-20-26', 'warsh', 20, 26, 'وَاحْلُلْ عُقْدَةࣰ مِّن لِّسَانِے', 'واحلل عقدة من لسانے', NULL, 313, 'local:warsh-text.json'),
  ('warsh-20-27', 'warsh', 20, 27, 'يَفْقَهُواْ قَوْلِے', 'يفقهوا قولے', NULL, 313, 'local:warsh-text.json'),
  ('warsh-20-28', 'warsh', 20, 28, 'وَاجْعَل لِّے وَزِيراࣰ مِّنَ ࡰهْلِے', 'واجعل لے وزيرا من ࡰهلے', NULL, 313, 'local:warsh-text.json'),
  ('warsh-20-29', 'warsh', 20, 29, 'هَٰرُونَ أَخِے࣌', 'هرون أخے࣌', NULL, 313, 'local:warsh-text.json'),
  ('warsh-20-30', 'warsh', 20, 30, 'ࡴ࢈شْدُدْ بِهِۦٓ أَزْرِے', 'ࡴ࢈شدد به أزرے', NULL, 313, 'local:warsh-text.json'),
  ('warsh-20-31', 'warsh', 20, 31, 'وَأَشْرِكْهُ فِےٓ أَمْرِے', 'وأشركه فے أمرے', NULL, 313, 'local:warsh-text.json'),
  ('warsh-20-32', 'warsh', 20, 32, 'كَےْ نُسَبِّحَكَ كَثِيراࣰ', 'كے نسبحك كثيرا', NULL, 313, 'local:warsh-text.json'),
  ('warsh-20-33', 'warsh', 20, 33, 'وَنَذْكُرَكَ كَثِيراً', 'ونذكرك كثيرا', NULL, 313, 'local:warsh-text.json'),
  ('warsh-20-34', 'warsh', 20, 34, 'ࡴنَّكَ كُنتَ بِنَا بَصِيراࣰ࣌', 'ࡴنك كنت بنا بصيرا࣌', NULL, 313, 'local:warsh-text.json'),
  ('warsh-20-35', 'warsh', 20, 35, '۞ قَالَ قَدُ ࡳوتِيتَ سُؤْلَكَ يَٰمُوسٜىٰ࣌', 'قال قد ࡳوتيت سؤلك يموسى࣌', NULL, 313, 'local:warsh-text.json'),
  ('warsh-20-36', 'warsh', 20, 36, 'وَلَقَدْ مَنَنَّا عَلَيْكَ مَرَّةً ࡳخْرٜىٰٓ', 'ولقد مننا عليك مرة ࡳخرى', NULL, 313, 'local:warsh-text.json'),
  ('warsh-20-37', 'warsh', 20, 37, 'إِذَ ࡰوْحَيْنَآ إِلَىٰٓ أُمِّكَ مَا يُوحٜىٰٓ', 'إذ ࡰوحينا إلى أمك ما يوحى', NULL, 314, 'local:warsh-text.json'),
  ('warsh-20-38', 'warsh', 20, 38, 'أَنِ ࡴٜقْذِفِيهِ فِے ࡴ۬لتَّابُوتِ فَاقْذِفِيهِ فِے ࡴ۬لْيَمِّ࣌ فَلْيُلْقِهِ ࡴ۬لْيَمُّ بِالسَّاحِلِ يَاخُذْهُ عَدُوࣱّ لِّے وَعَدُوࣱّ لَّهُۥ࣌ وَأَلْقَيْتُ عَلَيْكَ مَحَبَّةࣰ مِّنِّے', 'أن ࡴقذفيه فے ࡴلتابوت فاقذفيه فے ࡴليم࣌ فليلقه ࡴليم بالساحل ياخذه عدو لے وعدو له࣌ وألقيت عليك محبة منے', NULL, 314, 'local:warsh-text.json'),
  ('warsh-20-39', 'warsh', 20, 39, 'وَلِتُصْنَعَ عَلَىٰ عَيْنِيَ', 'ولتصنع على عيني', NULL, 314, 'local:warsh-text.json'),
  ('warsh-20-40', 'warsh', 20, 40, 'إِذْ تَمْشِےٓ أُخْتُكَ فَتَقُولُ هَلَ ࡰدُلُّكُمْ عَلَىٰ مَنْ يَّكْفُلُهُۥ࣌ فَرَجَعْنَٰكَ إِلَىٰٓ أُمِّكَ كَےْ تَقَرَّ عَيْنُهَا وَلَا تَحْزَنَ࣌ وَقَتَلْتَ نَفْساࣰ فَنَجَّيْنَٰكَ مِنَ ࡰ۬لْغَمِّ وَفَتَنَّٰكَ فُتُوناࣰ࣌ فَلَبِثْتَ سِنِينَ فِےٓ أَهْلِ مَدْيَنَ ثُمَّ جِئْتَ عَلَىٰ قَدَرࣲ يَٰمُوسٜىٰ࣌', 'إذ تمشے أختك فتقول هل ࡰدلكم على من يكفله࣌ فرجعنك إلى أمك كے تقر عينها ولا تحزن࣌ وقتلت نفسا فنجينك من ࡰلغم وفتنك فتونا࣌ فلبثت سنين فے أهل مدين ثم جئت على قدر يموسى࣌', NULL, 314, 'local:warsh-text.json'),
  ('warsh-20-41', 'warsh', 20, 41, 'وَاصْطَنَعْتُكَ لِنَفْسِيَ࣌ ࡰٜذْهَبَ ࡰنتَ وَأَخُوكَ بِـَٔايَٰتِے وَلَا تَنِيَا فِے ذِكْرِيَ࣌', 'واصطنعتك لنفسي࣌ ࡰذهب ࡰنت وأخوك بايتے ولا تنيا فے ذكري࣌', NULL, 314, 'local:warsh-text.json'),
  ('warsh-20-42', 'warsh', 20, 42, 'ࡰٜذْهَبَآ إِلَىٰ فِرْعَوْنَ إِنَّهُۥ طَغٜىٰ', 'ࡰذهبا إلى فرعون إنه طغى', NULL, 314, 'local:warsh-text.json'),
  ('warsh-20-43', 'warsh', 20, 43, 'فَقُولَا لَهُۥ قَوْلاࣰ لَّيِّناࣰ لَّعَلَّهُۥ يَتَذَكَّرُ أَوْ يَخْشٜىٰ࣌', 'فقولا له قولا لينا لعله يتذكر أو يخشى࣌', NULL, 314, 'local:warsh-text.json'),
  ('warsh-20-44', 'warsh', 20, 44, 'قَالَا رَبَّنَآ إِنَّنَا نَخَافُ أَنْ يَّفْرُطَ عَلَيْنَآ أَوَ ࡰنْ يَّطْغٜىٰ࣌', 'قالا ربنا إننا نخاف أن يفرط علينا أو ࡰن يطغى࣌', NULL, 314, 'local:warsh-text.json'),
  ('warsh-20-45', 'warsh', 20, 45, 'قَالَ لَا تَخَافَآ إِنَّنِے مَعَكُمَآ أَسْمَعُ وَأَرٜىٰ࣌', 'قال لا تخافا إننے معكما أسمع وأرى࣌', NULL, 314, 'local:warsh-text.json'),
  ('warsh-20-46', 'warsh', 20, 46, 'فَاتِيَٰهُ فَقُولَآ إِنَّا رَسُولَا رَبِّكَ فَأَرْسِلْ مَعَنَا بَنِےٓ إِسْرَآءِيلَ وَلَا تُعَذِّبْهُمْ قَدْ جِئْنَٰكَ بِـَٔايَةࣲ مِّن رَّبِّكَ࣌ وَالسَّلَٰمُ عَلَىٰ مَنِ ࡴٜتَّبَعَ ࡰ۬لْهُدٜىٰٓ࣌', 'فاتيه فقولا إنا رسولا ربك فأرسل معنا بنے إسراءيل ولا تعذبهم قد جئنك باية من ربك࣌ والسلم على من ࡴتبع ࡰلهدى࣌', NULL, 314, 'local:warsh-text.json'),
  ('warsh-20-47', 'warsh', 20, 47, 'إِنَّا قَدُ ࡳوحِيَ إِلَيْنَآ أَنَّ ࡰ۬لْعَذَابَ عَلَىٰ مَن كَذَّبَ وَتَوَلّٜىٰ࣌', 'إنا قد ࡳوحي إلينا أن ࡰلعذاب على من كذب وتولى࣌', NULL, 314, 'local:warsh-text.json'),
  ('warsh-20-48', 'warsh', 20, 48, 'قَالَ فَمَن رَّبُّكُمَا يَٰمُوسٜىٰ࣌', 'قال فمن ربكما يموسى࣌', NULL, 314, 'local:warsh-text.json'),
  ('warsh-20-49', 'warsh', 20, 49, 'قَالَ رَبُّنَا ࡰ۬لذِےٓ أَعْطٜىٰ كُلَّ شَےْءٍ خَلْقَهُۥ ثُمَّ هَدٜىٰ࣌', 'قال ربنا ࡰلذے أعطى كل شےء خلقه ثم هدى࣌', NULL, 314, 'local:warsh-text.json'),
  ('warsh-20-50', 'warsh', 20, 50, 'قَالَ فَمَا بَالُ ࡲ۬لْقُرُونِ ࡴ۬لُاولٜىٰ࣌', 'قال فما بال ࡲلقرون ࡴلاولى࣌', NULL, 314, 'local:warsh-text.json'),
  ('warsh-20-51', 'warsh', 20, 51, 'قَالَ عِلْمُهَا عِندَ رَبِّے فِے كِتَٰبࣲ࣌ لَّا يَضِلُّ رَبِّے وَلَا يَنسَى࣌', 'قال علمها عند ربے فے كتب࣌ لا يضل ربے ولا ينسى࣌', NULL, 315, 'local:warsh-text.json'),
  ('warsh-20-52', 'warsh', 20, 52, 'ࡰ۬لذِے جَعَلَ لَكُمُ ࡲ۬لَارْضَ مِهَٰداࣰ وَسَلَكَ لَكُمْ فِيهَا سُبُلاࣰ وَأَنزَلَ مِنَ ࡰ۬لسَّمَآءِ مَآءࣰ࣌ فَأَخْرَجْنَا بِهِۦٓ أَزْوَٰجاࣰ مِّن نَّبَاتࣲ شَتّٜىٰ࣌', 'ࡰلذے جعل لكم ࡲلارض مهدا وسلك لكم فيها سبلا وأنزل من ࡰلسماء ماء࣌ فأخرجنا به أزوجا من نبات شتى࣌', NULL, 315, 'local:warsh-text.json')
insert into public.ayahs (id, riwayah, surah_number, ayah_number, text, simple_text, juz, page, source) values
  ('warsh-20-53', 'warsh', 20, 53, 'كُلُواْ وَارْعَوَاْ ࡰنْعَٰمَكُمُۥٓ࣌ إِنَّ فِے ذَٰلِكَ لَأٓيَٰتࣲ لِّأُوْلِے ࡴ۬لنُّهٜىٰ࣌', 'كلوا وارعوا ࡰنعمكم࣌ إن فے ذلك لأيت لأولے ࡴلنهى࣌', NULL, 315, 'local:warsh-text.json'),
  ('warsh-20-54', 'warsh', 20, 54, '۞ مِنْهَا خَلَقْنَٰكُمْ وَفِيهَا نُعِيدُكُمْ وَمِنْهَا نُخْرِجُكُمْ تَارَةً ࡳخْرٜىٰ࣌', 'منها خلقنكم وفيها نعيدكم ومنها نخرجكم تارة ࡳخرى࣌', NULL, 315, 'local:warsh-text.json'),
  ('warsh-20-55', 'warsh', 20, 55, 'وَلَقَدَ ࡰرَيْنَٰهُ ءَايَٰتِنَا كُلَّهَا فَكَذَّبَ وَأَبٜىٰ࣌', 'ولقد ࡰرينه ءايتنا كلها فكذب وأبى࣌', NULL, 315, 'local:warsh-text.json'),
  ('warsh-20-56', 'warsh', 20, 56, 'قَالَ أَجِئْتَنَا لِتُخْرِجَنَا مِنَ ࡰرْضِنَا بِسِحْرِكَ يَٰمُوسٜىٰ', 'قال أجئتنا لتخرجنا من ࡰرضنا بسحرك يموسى', NULL, 315, 'local:warsh-text.json'),
  ('warsh-20-57', 'warsh', 20, 57, 'فَلَنَاتِيَنَّكَ بِسِحْرࣲ مِّثْلِهِۦ࣌ فَاجْعَلْ بَيْنَنَا وَبَيْنَكَ مَوْعِداࣰ لَّا نُخْلِفُهُۥ نَحْنُ وَلَآ أَنتَ مَكَاناࣰ سِوىࣰ࣌', 'فلناتينك بسحر مثله࣌ فاجعل بيننا وبينك موعدا لا نخلفه نحن ولا أنت مكانا سوى࣌', NULL, 315, 'local:warsh-text.json'),
  ('warsh-20-58', 'warsh', 20, 58, 'قَالَ مَوْعِدُكُمْ يَوْمُ ࡲ۬لزِّينَةِ وَأَنْ يُّحْشَرَ ࡰ۬لنَّاسُ ضُحىࣰ࣌', 'قال موعدكم يوم ࡲلزينة وأن يحشر ࡰلناس ضحى࣌', NULL, 315, 'local:warsh-text.json'),
  ('warsh-20-59', 'warsh', 20, 59, 'فَتَوَلّٜىٰ فِرْعَوْنُ فَجَمَعَ كَيْدَهُۥ ثُمَّ أَتٜىٰ࣌', 'فتولى فرعون فجمع كيده ثم أتى࣌', NULL, 315, 'local:warsh-text.json'),
  ('warsh-20-60', 'warsh', 20, 60, 'قَالَ لَهُم مُّوسٜىٰ وَيْلَكُمْ لَا تَفْتَرُواْ عَلَى ࡰ۬للَّهِ كَذِباࣰ فَيَسْحَتَكُم بِعَذَابࣲ࣌ وَقَدْ خَابَ مَنِ ࡴٜفْتَرٜىٰ࣌', 'قال لهم موسى ويلكم لا تفتروا على ࡰلله كذبا فيسحتكم بعذاب࣌ وقد خاب من ࡴفترى࣌', NULL, 315, 'local:warsh-text.json'),
  ('warsh-20-61', 'warsh', 20, 61, 'فَتَنَٰزَعُوٓاْ أَمْرَهُم بَيْنَهُمْ وَأَسَرُّواْ ࡲ۬لنَّجْوٜىٰ࣌', 'فتنزعوا أمرهم بينهم وأسروا ࡲلنجوى࣌', NULL, 315, 'local:warsh-text.json'),
  ('warsh-20-62', 'warsh', 20, 62, 'قَالُوٓاْ إِنَّ هَٰذَٰنِ لَسَٰحِرَٰنِ يُرِيدَٰنِ أَنْ يُّخْرِجَٰكُم مِّنَ ࡰرْضِكُم بِسِحْرِهِمَا وَيَذْهَبَا بِطَرِيقَتِكُمُ ࡲ۬لْمُثْلٜىٰ࣌', 'قالوا إن هذن لسحرن يريدن أن يخرجكم من ࡰرضكم بسحرهما ويذهبا بطريقتكم ࡲلمثلى࣌', NULL, 315, 'local:warsh-text.json'),
  ('warsh-20-63', 'warsh', 20, 63, 'فَأَجْمِعُواْ كَيْدَكُمْ ثُمَّ ࡰٜيتُواْ صَفّاࣰ࣌ وَقَدَ ࡰفْلَحَ ࡰ۬لْيَوْمَ مَنِ ࡴٜسْتَعْلٜىٰ࣌', 'فأجمعوا كيدكم ثم ࡰيتوا صفا࣌ وقد ࡰفلح ࡰليوم من ࡴستعلى࣌', NULL, 315, 'local:warsh-text.json'),
  ('warsh-20-64', 'warsh', 20, 64, 'قَالُواْ يَٰمُوسٜىٰٓ إِمَّآ أَن تُلْقِيَ وَإِمَّآ أَن نَّكُونَ أَوَّلَ مَنَ ࡰلْقٜىٰ࣌', 'قالوا يموسى إما أن تلقي وإما أن نكون أول من ࡰلقى࣌', NULL, 316, 'local:warsh-text.json'),
  ('warsh-20-65', 'warsh', 20, 65, 'قَالَ بَلَ ࡰلْقُواْ࣌ فَإِذَا حِبَالُهُمْ وَعِصِيُّهُمْ يُخَيَّلُ إِلَيْهِ مِن سِحْرِهِمُۥٓ أَنَّهَا تَسْعٜىٰ࣌', 'قال بل ࡰلقوا࣌ فإذا حبالهم وعصيهم يخيل إليه من سحرهم أنها تسعى࣌', NULL, 316, 'local:warsh-text.json'),
  ('warsh-20-66', 'warsh', 20, 66, 'فَأَوْجَسَ فِے نَفْسِهِۦ خِيفَةࣰ مُّوسٜىٰ࣌', 'فأوجس فے نفسه خيفة موسى࣌', NULL, 316, 'local:warsh-text.json'),
  ('warsh-20-67', 'warsh', 20, 67, 'قُلْنَا لَا تَخَفِ ࡴنَّكَ أَنتَ ࡰ۬لَاعْلٜىٰ࣌', 'قلنا لا تخف ࡴنك أنت ࡰلاعلى࣌', NULL, 316, 'local:warsh-text.json'),
  ('warsh-20-68', 'warsh', 20, 68, 'وَأَلْقِ مَا فِے يَمِينِكَ تَلَقَّفْ مَا صَنَعُوٓاْ࣌ إِنَّمَا صَنَعُواْ كَيْدُ سَٰحِرࣲ࣌ وَلَا يُفْلِحُ ࡲ۬لسَّاحِرُ حَيْثُ أَتٜىٰ࣌', 'وألق ما فے يمينك تلقف ما صنعوا࣌ إنما صنعوا كيد سحر࣌ ولا يفلح ࡲلساحر حيث أتى࣌', NULL, 316, 'local:warsh-text.json'),
  ('warsh-20-69', 'warsh', 20, 69, 'فَأُلْقِيَ ࡰ۬لسَّحَرَةُ سُجَّداࣰ࣌ قَالُوٓاْ ءَامَنَّا بِرَبِّ هَٰرُونَ وَمُوسٜىٰ࣌', 'فألقي ࡰلسحرة سجدا࣌ قالوا ءامنا برب هرون وموسى࣌', NULL, 316, 'local:warsh-text.json'),
  ('warsh-20-70', 'warsh', 20, 70, 'قَالَ ءَࡶٰمَنتُمْ لَهُۥ قَبْلَ أَنَ اٰذَنَ لَكُمُۥٓ إِنَّهُۥ لَكَبِيرُكُمُ ࡲ۬لذِے عَلَّمَكُمُ ࡲ۬لسِّحْرَ࣌ فَلَأُقَطِّعَنَّ أَيْدِيَكُمْ وَأَرْجُلَكُم مِّنْ خِلَٰفࣲ وَلَأُصَلِّبَنَّكُمْ فِے جُذُوعِ ࡴ۬لنَّخْلِ وَلَتَعْلَمُنَّ أَيُّنَآ أَشَدُّ عَذَاباࣰ وَأَبْقٜىٰ࣌', 'قال ءࡶمنتم له قبل أن اذن لكم إنه لكبيركم ࡲلذے علمكم ࡲلسحر࣌ فلأقطعن أيديكم وأرجلكم من خلف ولأصلبنكم فے جذوع ࡴلنخل ولتعلمن أينا أشد عذابا وأبقى࣌', NULL, 316, 'local:warsh-text.json'),
  ('warsh-20-71', 'warsh', 20, 71, '۞ قَالُواْ لَن نُّوثِرَكَ عَلَىٰ مَا جَآءَنَا مِنَ ࡰ۬لْبَيِّنَٰتِ وَالذِے فَطَرَنَا࣌ فَاقْضِ مَآ أَنتَ قَاضٍ࣌ ࡴنَّمَا تَقْضِے هَٰذِهِ ࡴ۬لْحَيَوٰةَ ࡰ۬لدُّنْيٜآ࣌', 'قالوا لن نوثرك على ما جاءنا من ࡰلبينت والذے فطرنا࣌ فاقض ما أنت قاض࣌ ࡴنما تقضے هذه ࡴلحيوة ࡰلدنيا࣌', NULL, 316, 'local:warsh-text.json'),
  ('warsh-20-72', 'warsh', 20, 72, 'إِنَّآ ءَامَنَّا بِرَبِّنَا لِيَغْفِرَ لَنَا خَطَٰيٜـٰنَا وَمَآ أَكْرَهْتَنَا عَلَيْهِ مِنَ ࡰ۬لسِّحْرِ࣌ وَاللَّهُ خَيْرࣱ وَأَبْقٜىٰٓ࣌', 'إنا ءامنا بربنا ليغفر لنا خطينا وما أكرهتنا عليه من ࡰلسحر࣌ والله خير وأبقى࣌', NULL, 316, 'local:warsh-text.json'),
  ('warsh-20-73', 'warsh', 20, 73, 'إِنَّهُۥ مَنْ يَّاتِ رَبَّهُۥ مُجْرِماࣰ فَإِنَّ لَهُۥ جَهَنَّمَ لَا يَمُوتُ فِيهَا وَلَا يَحْيٜىٰ࣌', 'إنه من يات ربه مجرما فإن له جهنم لا يموت فيها ولا يحيى࣌', NULL, 316, 'local:warsh-text.json'),
  ('warsh-20-74', 'warsh', 20, 74, 'وَمَنْ يَّاتِهِۦ مُومِناࣰ قَدْ عَمِلَ ࡰ۬لصَّٰلِحَٰتِ فَأُوْلَٰٓئِكَ لَهُمُ ࡲ۬لدَّرَجَٰتُ ࡲ۬لْعُلٜىٰ࣌', 'ومن ياته مومنا قد عمل ࡰلصلحت فأولئك لهم ࡲلدرجت ࡲلعلى࣌', NULL, 316, 'local:warsh-text.json'),
  ('warsh-20-75', 'warsh', 20, 75, 'جَنَّٰتُ عَدْنࣲ تَجْرِے مِن تَحْتِهَا ࡰ۬لَانْهَٰرُ خَٰلِدِينَ فِيهَا࣌ وَذَٰلِكَ جَزَآءُ مَن تَزَكّٜىٰ࣌', 'جنت عدن تجرے من تحتها ࡰلانهر خلدين فيها࣌ وذلك جزاء من تزكى࣌', NULL, 316, 'local:warsh-text.json'),
  ('warsh-20-76', 'warsh', 20, 76, 'وَلَقَدَ ࡰوْحَيْنَآ إِلَىٰ مُوسٜىٰٓ أَنِ ࡴٜسْرِ بِعِبَادِے فَاضْرِبْ لَهُمْ طَرِيقاࣰ فِے ࡴ۬لْبَحْرِ يَبَساࣰ لَّا تَخَٰفُ دَرَكاࣰ وَلَا تَخْشٜىٰ࣌', 'ولقد ࡰوحينا إلى موسى أن ࡴسر بعبادے فاضرب لهم طريقا فے ࡴلبحر يبسا لا تخف دركا ولا تخشى࣌', NULL, 317, 'local:warsh-text.json'),
  ('warsh-20-77', 'warsh', 20, 77, 'فَأَتْبَعَهُمْ فِرْعَوْنُ بِجُنُودِهِۦ فَغَشِيَهُم مِّنَ ࡰ۬لْيَمِّ مَا غَشِيَهُمْ࣌ وَأَضَلَّ فِرْعَوْنُ قَوْمَهُۥ وَمَا هَدٜىٰ࣌', 'فأتبعهم فرعون بجنوده فغشيهم من ࡰليم ما غشيهم࣌ وأضل فرعون قومه وما هدى࣌', NULL, 317, 'local:warsh-text.json'),
  ('warsh-20-78', 'warsh', 20, 78, 'يَٰبَنِےٓ إِسْرَآءِيلَ قَدَ ࡰنجَيْنَٰكُم مِّنْ عَدُوِّكُمْ وَوَٰعَدْنَٰكُمْ جَانِبَ ࡰ۬لطُّورِ ࡴ۬لَايْمَنَ وَنَزَّلْنَا عَلَيْكُمُ ࡲ۬لْمَنَّ وَالسَّلْوٜىٰ࣌', 'يبنے إسراءيل قد ࡰنجينكم من عدوكم ووعدنكم جانب ࡰلطور ࡴلايمن ونزلنا عليكم ࡲلمن والسلوى࣌', NULL, 317, 'local:warsh-text.json'),
  ('warsh-20-79', 'warsh', 20, 79, 'كُلُواْ مِن طَيِّبَٰتِ مَا رَزَقْنَٰكُمْ وَلَا تَطْغَوْاْ فِيهِ فَيَحِلَّ عَلَيْكُمْ غَضَبِے࣌ وَمَنْ يَّحْلِلْ عَلَيْهِ غَضَبِے فَقَدْ هَوٜىٰ࣌', 'كلوا من طيبت ما رزقنكم ولا تطغوا فيه فيحل عليكم غضبے࣌ ومن يحلل عليه غضبے فقد هوى࣌', NULL, 317, 'local:warsh-text.json'),
  ('warsh-20-80', 'warsh', 20, 80, 'وَإِنِّے لَغَفَّارࣱ لِّمَن تَابَ وَءَامَنَ وَعَمِلَ صَٰلِحاࣰ ثُمَّ ࡰٜهْتَدٜىٰ࣌', 'وإنے لغفار لمن تاب وءامن وعمل صلحا ثم ࡰهتدى࣌', NULL, 317, 'local:warsh-text.json'),
  ('warsh-20-81', 'warsh', 20, 81, '۞ وَمَآ أَعْجَلَكَ عَن قَوْمِكَ يَٰمُوسٜىٰ࣌', 'وما أعجلك عن قومك يموسى࣌', NULL, 317, 'local:warsh-text.json'),
  ('warsh-20-82', 'warsh', 20, 82, 'قَالَ هُمُۥٓ أُوْلَآءِ عَلَىٰٓ أَثَرِے وَعَجِلْتُ إِلَيْكَ رَبِّ لِتَرْضٜىٰ࣌', 'قال هم أولاء على أثرے وعجلت إليك رب لترضى࣌', NULL, 317, 'local:warsh-text.json'),
  ('warsh-20-83', 'warsh', 20, 83, 'قَالَ فَإِنَّا قَدْ فَتَنَّا قَوْمَكَ مِنۢ بَعْدِكَ وَأَضَلَّهُمُ ࡲ۬لسَّامِرِيُّ࣌', 'قال فإنا قد فتنا قومك من بعدك وأضلهم ࡲلسامري࣌', NULL, 317, 'local:warsh-text.json'),
  ('warsh-20-84', 'warsh', 20, 84, 'فَرَجَعَ مُوسٜىٰٓ إِلَىٰ قَوْمِهِۦ غَضْبَٰنَ أَسِفاࣰ࣌ قَالَ يَٰقَوْمِ أَلَمْ يَعِدْكُمْ رَبُّكُمْ وَعْداً حَسَناً࣌', 'فرجع موسى إلى قومه غضبن أسفا࣌ قال يقوم ألم يعدكم ربكم وعدا حسنا࣌', NULL, 317, 'local:warsh-text.json'),
  ('warsh-20-85', 'warsh', 20, 85, 'ࡰفَطَالَ عَلَيْكُمُ ࡲ۬لْعَهْدُ أَمَ ࡰرَدتُّمُۥٓ أَنْ يَّحِلَّ عَلَيْكُمْ غَضَبࣱ مِّن رَّبِّكُمْ فَأَخْلَفْتُم مَّوْعِدِے࣌', 'ࡰفطال عليكم ࡲلعهد أم ࡰردتم أن يحل عليكم غضب من ربكم فأخلفتم موعدے࣌', NULL, 317, 'local:warsh-text.json'),
  ('warsh-20-86', 'warsh', 20, 86, 'قَالُواْ مَآ أَخْلَفْنَا مَوْعِدَكَ بِمَلْكِنَا وَلَٰكِنَّا حُمِّلْنَآ أَوْزَاراࣰ مِّن زِينَةِ ࡴ۬لْقَوْمِ فَقَذَفْنَٰهَا فَكَذَٰلِكَ أَلْقَى ࡰ۬لسَّامِرِيُّ࣌ فَأَخْرَجَ لَهُمْ عِجْلاࣰ جَسَداࣰ لَّهُۥ خُوَارࣱ فَقَالُواْ هَٰذَآ إِلَٰهُكُمْ وَإِلَٰهُ مُوسٜىٰ فَنَسِيَ࣌', 'قالوا ما أخلفنا موعدك بملكنا ولكنا حملنا أوزارا من زينة ࡴلقوم فقذفنها فكذلك ألقى ࡰلسامري࣌ فأخرج لهم عجلا جسدا له خوار فقالوا هذا إلهكم وإله موسى فنسي࣌', NULL, 317, 'local:warsh-text.json'),
  ('warsh-20-87', 'warsh', 20, 87, 'أَفَلَا يَرَوْنَ أَلَّا يَرْجِعُ إِلَيْهِمْ قَوْلاࣰ', 'أفلا يرون ألا يرجع إليهم قولا', NULL, 318, 'local:warsh-text.json'),
  ('warsh-20-88', 'warsh', 20, 88, 'وَلَا يَمْلِكُ لَهُمْ ضَرّاࣰ وَلَا نَفْعاࣰ࣌', 'ولا يملك لهم ضرا ولا نفعا࣌', NULL, 318, 'local:warsh-text.json'),
  ('warsh-20-89', 'warsh', 20, 89, 'وَلَقَدْ قَالَ لَهُمْ هَٰرُونُ مِن قَبْلُ يَٰقَوْمِ إِنَّمَا فُتِنتُم بِهِۦ࣌ وَإِنَّ رَبَّكُمُ ࡲ۬لرَّحْمَٰنُ فَاتَّبِعُونِے وَأَطِيعُوٓاْ أَمْرِے࣌', 'ولقد قال لهم هرون من قبل يقوم إنما فتنتم به࣌ وإن ربكم ࡲلرحمن فاتبعونے وأطيعوا أمرے࣌', NULL, 318, 'local:warsh-text.json'),
  ('warsh-20-90', 'warsh', 20, 90, 'قَالُواْ لَن نَّبْرَحَ عَلَيْهِ عَٰكِفِينَ حَتَّىٰ يَرْجِعَ إِلَيْنَا مُوسٜىٰ࣌', 'قالوا لن نبرح عليه عكفين حتى يرجع إلينا موسى࣌', NULL, 318, 'local:warsh-text.json'),
  ('warsh-20-91', 'warsh', 20, 91, 'قَالَ يَٰهَٰرُونُ مَا مَنَعَكَ إِذْ رَأَيْتَهُمْ ضَلُّوٓاْ أَلَّا تَتَّبِعَنِۦٓ أَفَعَصَيْتَ أَمْرِے࣌', 'قال يهرون ما منعك إذ رأيتهم ضلوا ألا تتبعن أفعصيت أمرے࣌', NULL, 318, 'local:warsh-text.json'),
  ('warsh-20-92', 'warsh', 20, 92, 'قَالَ يَبْنَؤُمَّ لَا تَاخُذْ بِلِحْيَتِے وَلَا بِرَأْسِيَ إِنِّے خَشِيتُ أَن تَقُولَ فَرَّقْتَ بَيْنَ بَنِےٓ إِسْرَآءِيلَ وَلَمْ تَرْقُبْ قَوْلِے࣌', 'قال يبنؤم لا تاخذ بلحيتے ولا برأسي إنے خشيت أن تقول فرقت بين بنے إسراءيل ولم ترقب قولے࣌', NULL, 318, 'local:warsh-text.json'),
  ('warsh-20-93', 'warsh', 20, 93, 'قَالَ فَمَا خَطْبُكَ يَٰسَٰمِرِيُّ࣌', 'قال فما خطبك يسمري࣌', NULL, 318, 'local:warsh-text.json'),
  ('warsh-20-94', 'warsh', 20, 94, 'قَالَ بَصُرْتُ بِمَا لَمْ يَبْصُرُواْ بِهِۦ فَقَبَضْتُ قَبْضَةࣰ مِّنَ ࡰثَرِ ࡴ۬لرَّسُولِ فَنَبَذْتُهَا وَكَذَٰلِكَ سَوَّلَتْ لِے نَفْسِے࣌', 'قال بصرت بما لم يبصروا به فقبضت قبضة من ࡰثر ࡴلرسول فنبذتها وكذلك سولت لے نفسے࣌', NULL, 318, 'local:warsh-text.json'),
  ('warsh-20-95', 'warsh', 20, 95, '۞ قَالَ فَاذْهَبْ فَإِنَّ لَكَ فِے ࡴ۬لْحَيَوٰةِ أَن تَقُولَ لَا مِسَاسَ࣌ وَإِنَّ لَكَ مَوْعِداࣰ لَّن تُخْلَفَهُۥ࣌ وَانظُرِ ࡴلَىٰٓ إِلَٰهِكَ ࡰ۬لذِے ظَلْتَ عَلَيْهِ عَاكِفاࣰ لَّنُحَرِّقَنَّهُۥ ثُمَّ لَنَنسِفَنَّهُۥ فِے ࡴ۬لْيَمِّ نَسْفاً࣌', 'قال فاذهب فإن لك فے ࡴلحيوة أن تقول لا مساس࣌ وإن لك موعدا لن تخلفه࣌ وانظر ࡴلى إلهك ࡰلذے ظلت عليه عاكفا لنحرقنه ثم لننسفنه فے ࡴليم نسفا࣌', NULL, 318, 'local:warsh-text.json'),
  ('warsh-20-96', 'warsh', 20, 96, 'ࡴنَّمَآ إِلَٰهُكُمُ ࡲ۬للَّهُ ࡲ۬لذِے لَآ إِلَٰهَ إِلَّا هُوَ࣌ وَسِعَ كُلَّ شَےْءٍ عِلْماࣰ࣌', 'ࡴنما إلهكم ࡲلله ࡲلذے لا إله إلا هو࣌ وسع كل شےء علما࣌', NULL, 318, 'local:warsh-text.json'),
  ('warsh-20-97', 'warsh', 20, 97, 'كَذَٰلِكَ نَقُصُّ عَلَيْكَ مِنَ ࡰنۢبَآءِ مَا قَدْ سَبَقَ࣌ وَقَدَ اٰتَيْنَٰكَ مِن لَّدُنَّا ذِكْراࣰ࣌', 'كذلك نقص عليك من ࡰنباء ما قد سبق࣌ وقد اتينك من لدنا ذكرا࣌', NULL, 319, 'local:warsh-text.json'),
  ('warsh-20-98', 'warsh', 20, 98, 'مَّنَ ࡰعْرَضَ عَنْهُ فَإِنَّهُۥ يَحْمِلُ يَوْمَ ࡰ۬لْقِيَٰمَةِ وِزْراً', 'من ࡰعرض عنه فإنه يحمل يوم ࡰلقيمة وزرا', NULL, 319, 'local:warsh-text.json'),
  ('warsh-20-99', 'warsh', 20, 99, 'خَٰلِدِينَ فِيهِ࣌ وَسَآءَ لَهُمْ يَوْمَ ࡰ۬لْقِيَٰمَةِ حِمْلاࣰ࣌', 'خلدين فيه࣌ وساء لهم يوم ࡰلقيمة حملا࣌', NULL, 319, 'local:warsh-text.json'),
  ('warsh-20-100', 'warsh', 20, 100, 'يَوْمَ يُنفَخُ فِے ࡴ۬لصُّورِ وَنَحْشُرُ ࡲ۬لْمُجْرِمِينَ يَوْمَئِذࣲ زُرْقاࣰ', 'يوم ينفخ فے ࡴلصور ونحشر ࡲلمجرمين يومئذ زرقا', NULL, 319, 'local:warsh-text.json'),
  ('warsh-20-101', 'warsh', 20, 101, 'يَتَخَٰفَتُونَ بَيْنَهُمُۥٓ إِن لَّبِثْتُمُۥٓ إِلَّا عَشْراࣰ࣌', 'يتخفتون بينهم إن لبثتم إلا عشرا࣌', NULL, 319, 'local:warsh-text.json'),
  ('warsh-20-102', 'warsh', 20, 102, 'نَّحْنُ أَعْلَمُ بِمَا يَقُولُونَ إِذْ يَقُولُ أَمْثَلُهُمْ طَرِيقَةً ࡴن لَّبِثْتُمُۥٓ إِلَّا يَوْماࣰ࣌', 'نحن أعلم بما يقولون إذ يقول أمثلهم طريقة ࡴن لبثتم إلا يوما࣌', NULL, 319, 'local:warsh-text.json'),
  ('warsh-20-103', 'warsh', 20, 103, 'وَيَسْـَٔلُونَكَ عَنِ ࡴ۬لْجِبَالِ فَقُلْ يَنسِفُهَا رَبِّے نَسْفاࣰ', 'ويسلونك عن ࡴلجبال فقل ينسفها ربے نسفا', NULL, 319, 'local:warsh-text.json'),
  ('warsh-20-104', 'warsh', 20, 104, 'فَيَذَرُهَا قَاعاࣰ صَفْصَفاࣰ لَّا تَرٜىٰ فِيهَا عِوَجاࣰ وَلَآ أَمْتاࣰ࣌', 'فيذرها قاعا صفصفا لا ترى فيها عوجا ولا أمتا࣌', NULL, 319, 'local:warsh-text.json'),
  ('warsh-20-105', 'warsh', 20, 105, 'يَوْمَئِذࣲ يَتَّبِعُونَ ࡰ۬لدَّاعِيَ لَا عِوَجَ لَهُۥ࣌ وَخَشَعَتِ ࡴ۬لَاصْوَاتُ لِلرَّحْمَٰنِ فَلَا تَسْمَعُ إِلَّا هَمْساࣰ࣌', 'يومئذ يتبعون ࡰلداعي لا عوج له࣌ وخشعت ࡴلاصوات للرحمن فلا تسمع إلا همسا࣌', NULL, 319, 'local:warsh-text.json'),
  ('warsh-20-106', 'warsh', 20, 106, 'يَوْمَئِذࣲ لَّا تَنفَعُ ࡲ۬لشَّفَٰعَةُ إِلَّا مَنَ ࡰذِنَ لَهُ ࡲ۬لرَّحْمَٰنُ وَرَضِيَ لَهُۥ قَوْلاࣰ࣌', 'يومئذ لا تنفع ࡲلشفعة إلا من ࡰذن له ࡲلرحمن ورضي له قولا࣌', NULL, 319, 'local:warsh-text.json'),
  ('warsh-20-107', 'warsh', 20, 107, 'يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ وَلَا يُحِيطُونَ بِهِۦ عِلْماࣰ࣌', 'يعلم ما بين أيديهم وما خلفهم ولا يحيطون به علما࣌', NULL, 319, 'local:warsh-text.json'),
  ('warsh-20-108', 'warsh', 20, 108, '۞ وَعَنَتِ ࡴ۬لْوُجُوهُ لِلْحَيِّ ࡴ۬لْقَيُّومِ࣌ وَقَدْ خَابَ مَنْ حَمَلَ ظُلْماࣰ࣌', 'وعنت ࡴلوجوه للحي ࡴلقيوم࣌ وقد خاب من حمل ظلما࣌', NULL, 319, 'local:warsh-text.json'),
  ('warsh-20-109', 'warsh', 20, 109, 'وَمَنْ يَّعْمَلْ مِنَ ࡰ۬لصَّٰلِحَٰتِ وَهُوَ مُومِنࣱ فَلَا يَخَافُ ظُلْماࣰ وَلَا هَضْماࣰ࣌', 'ومن يعمل من ࡰلصلحت وهو مومن فلا يخاف ظلما ولا هضما࣌', NULL, 319, 'local:warsh-text.json'),
  ('warsh-20-110', 'warsh', 20, 110, 'وَكَذَٰلِكَ أَنزَلْنَٰهُ قُرْءَاناً عَرَبِيّاࣰ وَصَرَّفْنَا فِيهِ مِنَ ࡰ۬لْوَعِيدِ لَعَلَّهُمْ يَتَّقُونَ أَوْ يُحْدِثُ لَهُمْ ذِكْراࣰ࣌', 'وكذلك أنزلنه قرءانا عربيا وصرفنا فيه من ࡰلوعيد لعلهم يتقون أو يحدث لهم ذكرا࣌', NULL, 319, 'local:warsh-text.json'),
  ('warsh-20-111', 'warsh', 20, 111, 'فَتَعَٰلَى ࡰ۬للَّهُ ࡲ۬لْمَلِكُ ࡲ۬لْحَقُّ࣌ وَلَا تَعْجَلْ بِالْقُرْءَانِ مِن قَبْلِ أَنْ يُّقْضٜىٰٓ إِلَيْكَ وَحْيُهُۥ࣌ وَقُل رَّبِّ زِدْنِے عِلْماࣰ࣌', 'فتعلى ࡰلله ࡲلملك ࡲلحق࣌ ولا تعجل بالقرءان من قبل أن يقضى إليك وحيه࣌ وقل رب زدنے علما࣌', NULL, 320, 'local:warsh-text.json'),
  ('warsh-20-112', 'warsh', 20, 112, 'وَلَقَدْ عَهِدْنَآ إِلَىٰٓ ءَادَمَ مِن قَبْلُ فَنَسِيَ وَلَمْ نَجِدْ لَهُۥ عَزْماࣰ࣌', 'ولقد عهدنا إلى ءادم من قبل فنسي ولم نجد له عزما࣌', NULL, 320, 'local:warsh-text.json'),
  ('warsh-20-113', 'warsh', 20, 113, 'وَإِذْ قُلْنَا لِلْمَلَٰٓئِكَةِ ࡴ࢈سْجُدُواْ لِأٓدَمَ فَسَجَدُوٓاْ࣌ إِلَّآ إِبْلِيسَ أَبٜىٰ࣌', 'وإذ قلنا للملئكة ࡴ࢈سجدوا لأدم فسجدوا࣌ إلا إبليس أبى࣌', NULL, 320, 'local:warsh-text.json'),
  ('warsh-20-114', 'warsh', 20, 114, 'فَقُلْنَا يَٰٓـَٔادَمُ إِنَّ هَٰذَا عَدُوࣱّ لَّكَ وَلِزَوْجِكَ فَلَا يُخْرِجَنَّكُمَا مِنَ ࡰ۬لْجَنَّةِ فَتَشْقٜىٰٓ࣌', 'فقلنا يادم إن هذا عدو لك ولزوجك فلا يخرجنكما من ࡰلجنة فتشقى࣌', NULL, 320, 'local:warsh-text.json'),
  ('warsh-20-115', 'warsh', 20, 115, 'إِنَّ لَكَ أَلَّا تَجُوعَ فِيهَا وَلَا تَعْرٜىٰ࣌', 'إن لك ألا تجوع فيها ولا تعرى࣌', NULL, 320, 'local:warsh-text.json'),
  ('warsh-20-116', 'warsh', 20, 116, 'وَإِنَّكَ لَا تَظْمَؤُاْ فِيهَا وَلَا تَضْحٜىٰ࣌', 'وإنك لا تظمؤا فيها ولا تضحى࣌', NULL, 320, 'local:warsh-text.json'),
  ('warsh-20-117', 'warsh', 20, 117, 'فَوَسْوَسَ إِلَيْهِ ࡴ۬لشَّيْطَٰنُ࣌ قَالَ يَٰٓـَٔادَمُ هَلَ ࡰدُلُّكَ عَلَىٰ شَجَرَةِ ࡴ۬لْخُلْدِ وَمُلْكࣲ لَّا يَبْلٜىٰ࣌', 'فوسوس إليه ࡴلشيطن࣌ قال يادم هل ࡰدلك على شجرة ࡴلخلد وملك لا يبلى࣌', NULL, 320, 'local:warsh-text.json'),
  ('warsh-20-118', 'warsh', 20, 118, 'فَأَكَلَا مِنْهَا فَبَدَتْ لَهُمَا سَوْءَٰتُهُمَا وَطَفِقَا يَخْصِفَٰنِ عَلَيْهِمَا مِنْ وَّرَقِ ࡴ۬لْجَنَّةِ࣌ وَعَصٜىٰٓ ءَادَمُ رَبَّهُۥ فَغَوٜىٰ࣌', 'فأكلا منها فبدت لهما سوءتهما وطفقا يخصفن عليهما من ورق ࡴلجنة࣌ وعصى ءادم ربه فغوى࣌', NULL, 320, 'local:warsh-text.json'),
  ('warsh-20-119', 'warsh', 20, 119, 'ثُمَّ ࡰٜجْتَبٜـٰهُ رَبُّهُۥ فَتَابَ عَلَيْهِ وَهَدٜىٰ࣌', 'ثم ࡰجتبه ربه فتاب عليه وهدى࣌', NULL, 320, 'local:warsh-text.json'),
  ('warsh-20-120', 'warsh', 20, 120, 'قَالَ ࡰٜهْبِطَا مِنْهَا جَمِيعاَۢ࣌ بَعْضُكُمْ لِبَعْضٍ عَدُوࣱّ࣌ فَإِمَّا يَاتِيَنَّكُم مِّنِّے هُدىࣰ', 'قال ࡰهبطا منها جميعا࣌ بعضكم لبعض عدو࣌ فإما ياتينكم منے هدى', NULL, 320, 'local:warsh-text.json'),
  ('warsh-20-121', 'warsh', 20, 121, 'فَمَنِ ࡴٜتَّبَعَ هُدٜايَ فَلَا يَضِلُّ وَلَا يَشْقٜىٰ࣌', 'فمن ࡴتبع هداي فلا يضل ولا يشقى࣌', NULL, 320, 'local:warsh-text.json'),
  ('warsh-20-122', 'warsh', 20, 122, 'وَمَنَ ࡰعْرَضَ عَن ذِكْرِے فَإِنَّ لَهُۥ مَعِيشَةࣰ ضَنكاࣰ وَنَحْشُرُهُۥ يَوْمَ ࡰ۬لْقِيَٰمَةِ أَعْمٜىٰ࣌', 'ومن ࡰعرض عن ذكرے فإن له معيشة ضنكا ونحشره يوم ࡰلقيمة أعمى࣌', NULL, 320, 'local:warsh-text.json'),
  ('warsh-20-123', 'warsh', 20, 123, 'قَالَ رَبِّ لِمَ حَشَرْتَنِيَ أَعْمٜىٰ وَقَدْ كُنتُ بَصِيراࣰ࣌', 'قال رب لم حشرتني أعمى وقد كنت بصيرا࣌', NULL, 320, 'local:warsh-text.json'),
  ('warsh-20-124', 'warsh', 20, 124, '۞ قَالَ كَذَٰلِكَ أَتَتْكَ ءَايَٰتُنَا فَنَسِيتَهَا࣌ وَكَذَٰلِكَ ࡰ۬لْيَوْمَ تُنسٜىٰ࣌', 'قال كذلك أتتك ءايتنا فنسيتها࣌ وكذلك ࡰليوم تنسى࣌', NULL, 321, 'local:warsh-text.json'),
  ('warsh-20-125', 'warsh', 20, 125, 'وَكَذَٰلِكَ نَجْزِے مَنَ ࡰسْرَفَ وَلَمْ يُومِنۢ بِـَٔايَٰتِ رَبِّهِۦ࣌ وَلَعَذَابُ ࡲ۬لَاخِرَةِ أَشَدُّ وَأَبْقٜىٰٓ࣌', 'وكذلك نجزے من ࡰسرف ولم يومن بايت ربه࣌ ولعذاب ࡲلاخرة أشد وأبقى࣌', NULL, 321, 'local:warsh-text.json'),
  ('warsh-20-126', 'warsh', 20, 126, 'أَفَلَمْ يَهْدِ لَهُمْ كَمَ ࡰهْلَكْنَا قَبْلَهُم مِّنَ ࡰ۬لْقُرُونِ يَمْشُونَ فِے مَسَٰكِنِهِمُۥٓ࣌ إِنَّ فِے ذَٰلِكَ لَأٓيَٰتࣲ لِّأُوْلِے ࡴ۬لنُّهٜىٰ࣌', 'أفلم يهد لهم كم ࡰهلكنا قبلهم من ࡰلقرون يمشون فے مسكنهم࣌ إن فے ذلك لأيت لأولے ࡴلنهى࣌', NULL, 321, 'local:warsh-text.json'),
  ('warsh-20-127', 'warsh', 20, 127, 'وَلَوْلَا كَلِمَةࣱ سَبَقَتْ مِن رَّبِّكَ لَكَانَ لِزَاماࣰ وَأَجَلࣱ مُّسَمّىࣰ࣌', 'ولولا كلمة سبقت من ربك لكان لزاما وأجل مسمى࣌', NULL, 321, 'local:warsh-text.json'),
  ('warsh-20-128', 'warsh', 20, 128, 'فَاصْبِرْ عَلَىٰ مَا يَقُولُونَ࣌ وَسَبِّحْ بِحَمْدِ رَبِّكَ قَبْلَ طُلُوعِ ࡴ۬لشَّمْسِ وَقَبْلَ غُرُوبِهَا࣌ وَمِنَ اٰنَآءِےْ ࡴ۬ليْلِ فَسَبِّحْ وَأَطْرَافَ ࡰ۬لنَّهٜارِ لَعَلَّكَ تَرْضٜىٰ࣌', 'فاصبر على ما يقولون࣌ وسبح بحمد ربك قبل طلوع ࡴلشمس وقبل غروبها࣌ ومن اناءے ࡴليل فسبح وأطراف ࡰلنهار لعلك ترضى࣌', NULL, 321, 'local:warsh-text.json'),
  ('warsh-20-129', 'warsh', 20, 129, 'وَلَا تَمُدَّنَّ عَيْنَيْكَ إِلَىٰ مَا مَتَّعْنَا بِهِۦٓ أَزْوَٰجاࣰ مِّنْهُمْ زَهْرَةَ ࡰ۬لْحَيَوٰةِ ࡴ۬لدُّنْيٜا', 'ولا تمدن عينيك إلى ما متعنا به أزوجا منهم زهرة ࡰلحيوة ࡴلدنيا', NULL, 321, 'local:warsh-text.json'),
  ('warsh-20-130', 'warsh', 20, 130, 'لِنَفْتِنَهُمْ فِيهِ࣌ وَرِزْقُ رَبِّكَ خَيْرࣱ وَأَبْقٜىٰ࣌', 'لنفتنهم فيه࣌ ورزق ربك خير وأبقى࣌', NULL, 321, 'local:warsh-text.json'),
  ('warsh-20-131', 'warsh', 20, 131, 'وَامُرَ ࡰهْلَكَ بِالصَّلَوٰةِ وَاصْطَبِرْ عَلَيْهَا࣌ لَا نَسْـَٔلُكَ رِزْقاࣰ࣌ نَّحْنُ نَرْزُقُكَ࣌ وَالْعَٰقِبَةُ لِلتَّقْوٜىٰ࣌', 'وامر ࡰهلك بالصلوة واصطبر عليها࣌ لا نسلك رزقا࣌ نحن نرزقك࣌ والعقبة للتقوى࣌', NULL, 321, 'local:warsh-text.json'),
  ('warsh-20-132', 'warsh', 20, 132, 'وَقَالُواْ لَوْلَا يَاتِينَا بِـَٔايَةࣲ مِّن رَّبِّهِۦٓ࣌ أَوَلَمْ تَاتِهِم بَيِّنَةُ مَا فِے ࡴ۬لصُّحُفِ ࡴ۬لُاولٜىٰ࣌', 'وقالوا لولا ياتينا باية من ربه࣌ أولم تاتهم بينة ما فے ࡴلصحف ࡴلاولى࣌', NULL, 321, 'local:warsh-text.json'),
  ('warsh-20-133', 'warsh', 20, 133, 'وَلَوَ ࡰنَّآ أَهْلَكْنَٰهُم بِعَذَابࣲ مِّن قَبْلِهِۦ لَقَالُواْ رَبَّنَا لَوْلَآ أَرْسَلْتَ إِلَيْنَا رَسُولاࣰ فَنَتَّبِعَ ءَايَٰتِكَ مِن قَبْلِ أَن نَّذِلَّ وَنَخْزٜىٰ࣌', 'ولو ࡰنا أهلكنهم بعذاب من قبله لقالوا ربنا لولا أرسلت إلينا رسولا فنتبع ءايتك من قبل أن نذل ونخزى࣌', NULL, 321, 'local:warsh-text.json'),
  ('warsh-20-134', 'warsh', 20, 134, 'قُلْ كُلࣱّ مُّتَرَبِّصࣱ فَتَرَبَّصُواْ࣌ فَسَتَعْلَمُونَ مَنَ ࡰصْحَٰبُ ࡲ۬لصِّرَٰطِ ࡴ۬لسَّوِيِّ وَمَنِ ࡴٜهْتَدَى࣌', 'قل كل متربص فتربصوا࣌ فستعلمون من ࡰصحب ࡲلصرط ࡴلسوي ومن ࡴهتدى࣌', NULL, 321, 'local:warsh-text.json'),
  ('warsh-21-1', 'warsh', 21, 1, 'ࡰٜقْتَرَبَ لِلنَّاسِ حِسَابُهُمْ وَهُمْ فِے غَفْلَةࣲ مُّعْرِضُونَ࣌', 'ࡰقترب للناس حسابهم وهم فے غفلة معرضون࣌', NULL, 322, 'local:warsh-text.json'),
  ('warsh-21-2', 'warsh', 21, 2, 'مَا يَاتِيهِم مِّن ذِكْرࣲ مِّن رَّبِّهِم مُّحْدَثٍ ࡴلَّا ࡰٜسْتَمَعُوهُ وَهُمْ يَلْعَبُونَ', 'ما ياتيهم من ذكر من ربهم محدث ࡴلا ࡰستمعوه وهم يلعبون', NULL, 322, 'local:warsh-text.json'),
  ('warsh-21-3', 'warsh', 21, 3, 'لَٰهِيَةࣰ قُلُوبُهُمْ࣌ وَأَسَرُّواْ ࡲ۬لنَّجْوَى ࡰ۬لذِينَ ظَلَمُواْ هَلْ هَٰذَآ إِلَّا بَشَرࣱ مِّثْلُكُمُۥٓ࣌ أَفَتَاتُونَ ࡰ۬لسِّحْرَ وَأَنتُمْ تُبْصِرُونَ࣌', 'لهية قلوبهم࣌ وأسروا ࡲلنجوى ࡰلذين ظلموا هل هذا إلا بشر مثلكم࣌ أفتاتون ࡰلسحر وأنتم تبصرون࣌', NULL, 322, 'local:warsh-text.json'),
  ('warsh-21-4', 'warsh', 21, 4, 'قُل رَّبِّے يَعْلَمُ ࡲ۬لْقَوْلَ فِے ࡴ۬لسَّمَآءِ وَالَارْضِ࣌ وَهُوَ ࡰ۬لسَّمِيعُ ࡲ۬لْعَلِيمُ࣌', 'قل ربے يعلم ࡲلقول فے ࡴلسماء والارض࣌ وهو ࡰلسميع ࡲلعليم࣌', NULL, 322, 'local:warsh-text.json'),
  ('warsh-21-5', 'warsh', 21, 5, 'بَلْ قَالُوٓاْ أَضْغَٰثُ أَحْلَٰمِۢ بَلِ ࡴٜفْتَرٜيٰهُ بَلْ هُوَ شَاعِرࣱ࣌ فَلْيَاتِنَا بِـَٔايَةࣲ كَمَآ أُرْسِلَ ࡰ۬لَاوَّلُونَ࣌', 'بل قالوا أضغث أحلم بل ࡴفتريه بل هو شاعر࣌ فلياتنا باية كما أرسل ࡰلاولون࣌', NULL, 322, 'local:warsh-text.json'),
  ('warsh-21-6', 'warsh', 21, 6, 'مَآ ءَامَنَتْ قَبْلَهُم مِّن قَرْيَةٍ ࡰهْلَكْنَٰهَآ࣌ أَفَهُمْ يُومِنُونَ࣌', 'ما ءامنت قبلهم من قرية ࡰهلكنها࣌ أفهم يومنون࣌', NULL, 322, 'local:warsh-text.json'),
  ('warsh-21-7', 'warsh', 21, 7, 'وَمَآ أَرْسَلْنَا قَبْلَكَ إِلَّا رِجَالاࣰ يُوحٜىٰٓ إِلَيْهِمْ فَسْـَٔلُوٓاْ أَهْلَ ࡰ۬لذِّكْرِ إِن كُنتُمْ لَا تَعْلَمُونَ࣌', 'وما أرسلنا قبلك إلا رجالا يوحى إليهم فسلوا أهل ࡰلذكر إن كنتم لا تعلمون࣌', NULL, 322, 'local:warsh-text.json'),
  ('warsh-21-8', 'warsh', 21, 8, 'وَمَا جَعَلْنَٰهُمْ جَسَداࣰ لَّا يَاكُلُونَ ࡰ۬لطَّعَامَ࣌ وَمَا كَانُواْ خَٰلِدِينَ࣌', 'وما جعلنهم جسدا لا ياكلون ࡰلطعام࣌ وما كانوا خلدين࣌', NULL, 322, 'local:warsh-text.json'),
  ('warsh-21-9', 'warsh', 21, 9, 'ثُمَّ صَدَقْنَٰهُمُ ࡲ۬لْوَعْدَ فَأَنجَيْنَٰهُمْ وَمَن نَّشَآءُ وَأَهْلَكْنَا ࡰ۬لْمُسْرِفِينَ࣌', 'ثم صدقنهم ࡲلوعد فأنجينهم ومن نشاء وأهلكنا ࡰلمسرفين࣌', NULL, 322, 'local:warsh-text.json'),
  ('warsh-21-10', 'warsh', 21, 10, 'لَقَدَ ࡰنزَلْنَآ إِلَيْكُمْ كِتَٰباࣰ فِيهِ ذِكْرُكُمُۥٓ࣌ أَفَلَا تَعْقِلُونَ࣌', 'لقد ࡰنزلنا إليكم كتبا فيه ذكركم࣌ أفلا تعقلون࣌', NULL, 322, 'local:warsh-text.json'),
  ('warsh-21-11', 'warsh', 21, 11, 'وَكَمْ قَصَمْنَا مِن قَرْيَةࣲ كَانَت ظَّالِمَةࣰ وَأَنشَأْنَا بَعْدَهَا قَوْماً اٰخَرِينَ࣌', 'وكم قصمنا من قرية كانت ظالمة وأنشأنا بعدها قوما اخرين࣌', NULL, 323, 'local:warsh-text.json'),
  ('warsh-21-12', 'warsh', 21, 12, 'فَلَمَّآ أَحَسُّواْ بَأْسَنَآ إِذَا هُم مِّنْهَا يَرْكُضُونَ࣌', 'فلما أحسوا بأسنا إذا هم منها يركضون࣌', NULL, 323, 'local:warsh-text.json'),
  ('warsh-21-13', 'warsh', 21, 13, 'لَا تَرْكُضُواْ وَارْجِعُوٓاْ إِلَىٰ مَآ أُتْرِفْتُمْ فِيهِ وَمَسَٰكِنِكُمْ لَعَلَّكُمْ تُسْـَٔلُونَ࣌', 'لا تركضوا وارجعوا إلى ما أترفتم فيه ومسكنكم لعلكم تسلون࣌', NULL, 323, 'local:warsh-text.json'),
  ('warsh-21-14', 'warsh', 21, 14, 'قَالُواْ يَٰوَيْلَنَآ إِنَّا كُنَّا ظَٰلِمِينَ࣌', 'قالوا يويلنا إنا كنا ظلمين࣌', NULL, 323, 'local:warsh-text.json'),
  ('warsh-21-15', 'warsh', 21, 15, '۞ فَمَا زَالَت تِّلْكَ دَعْوٜيٰهُمْ حَتَّىٰ جَعَلْنَٰهُمْ حَصِيداً خَٰمِدِينَ࣌', 'فما زالت تلك دعويهم حتى جعلنهم حصيدا خمدين࣌', NULL, 323, 'local:warsh-text.json'),
  ('warsh-21-16', 'warsh', 21, 16, 'وَمَا خَلَقْنَا ࡰ۬لسَّمَآءَ وَالَارْضَ وَمَا بَيْنَهُمَا لَٰعِبِينَ࣌', 'وما خلقنا ࡰلسماء والارض وما بينهما لعبين࣌', NULL, 323, 'local:warsh-text.json'),
  ('warsh-21-17', 'warsh', 21, 17, 'لَوَ ࡰرَدْنَآ أَن نَّتَّخِذَ لَهْواࣰ لَّاتَّخَذْنَٰهُ مِن لَّدُنَّآ࣌ إِن كُنَّا فَٰعِلِينَ࣌', 'لو ࡰردنا أن نتخذ لهوا لاتخذنه من لدنا࣌ إن كنا فعلين࣌', NULL, 323, 'local:warsh-text.json'),
  ('warsh-21-18', 'warsh', 21, 18, 'بَلْ نَقْذِفُ بِالْحَقِّ عَلَى ࡰ۬لْبَٰطِلِ فَيَدْمَغُهُۥ فَإِذَا هُوَ زَاهِقࣱ࣌ وَلَكُمُ ࡲ۬لْوَيْلُ مِمَّا تَصِفُونَ࣌', 'بل نقذف بالحق على ࡰلبطل فيدمغه فإذا هو زاهق࣌ ولكم ࡲلويل مما تصفون࣌', NULL, 323, 'local:warsh-text.json'),
  ('warsh-21-19', 'warsh', 21, 19, 'وَلَهُۥ مَن فِے ࡴ۬لسَّمَٰوَٰتِ وَالَارْضِ࣌ وَمَنْ عِندَهُۥ لَا يَسْتَكْبِرُونَ عَنْ عِبَادَتِهِۦ وَلَا يَسْتَحْسِرُونَ࣌', 'وله من فے ࡴلسموت والارض࣌ ومن عنده لا يستكبرون عن عبادته ولا يستحسرون࣌', NULL, 323, 'local:warsh-text.json'),
  ('warsh-21-20', 'warsh', 21, 20, 'يُسَبِّحُونَ ࡰ۬ليْلَ وَالنَّهَارَ لَا يَفْتُرُونَ࣌', 'يسبحون ࡰليل والنهار لا يفترون࣌', NULL, 323, 'local:warsh-text.json'),
  ('warsh-21-21', 'warsh', 21, 21, 'أَمِ ࡴٜتَّخَذُوٓاْ ءَالِهَةࣰ مِّنَ ࡰ۬لَارْضِ هُمْ يُنشِرُونَ࣌', 'أم ࡴتخذوا ءالهة من ࡰلارض هم ينشرون࣌', NULL, 323, 'local:warsh-text.json'),
  ('warsh-21-22', 'warsh', 21, 22, 'لَوْ كَانَ فِيهِمَآ ءَالِهَةٌ ࡴلَّا ࡰ۬للَّهُ لَفَسَدَتَا࣌ فَسُبْحَٰنَ ࡰ۬للَّهِ رَبِّ ࡴ۬لْعَرْشِ عَمَّا يَصِفُونَ࣌', 'لو كان فيهما ءالهة ࡴلا ࡰلله لفسدتا࣌ فسبحن ࡰلله رب ࡴلعرش عما يصفون࣌', NULL, 323, 'local:warsh-text.json'),
  ('warsh-21-23', 'warsh', 21, 23, 'لَا يُسْـَٔلُ عَمَّا يَفْعَلُ࣌ وَهُمْ يُسْـَٔلُونَ࣌', 'لا يسل عما يفعل࣌ وهم يسلون࣌', NULL, 323, 'local:warsh-text.json'),
  ('warsh-21-24', 'warsh', 21, 24, 'أَمِ ࡴٜتَّخَذُواْ مِن دُونِهِۦٓ ءَالِهَةࣰ࣌ قُلْ هَاتُواْ بُرْهَٰنَكُمْ࣌ هَٰذَا ذِكْرُ مَن مَّعِے وَذِكْرُ مَن قَبْلِے࣌ بَلَ ࡰكْثَرُهُمْ لَا يَعْلَمُونَ ࡰ۬لْحَقَّ فَهُم مُّعْرِضُونَ࣌', 'أم ࡴتخذوا من دونه ءالهة࣌ قل هاتوا برهنكم࣌ هذا ذكر من معے وذكر من قبلے࣌ بل ࡰكثرهم لا يعلمون ࡰلحق فهم معرضون࣌', NULL, 323, 'local:warsh-text.json'),
  ('warsh-21-25', 'warsh', 21, 25, 'وَمَآ أَرْسَلْنَا مِن قَبْلِكَ مِن رَّسُولٍ ࡴلَّا يُوحٜىٰٓ إِلَيْهِ أَنَّهُۥ لَآ إِلَٰهَ إِلَّآ أَنَا فَاعْبُدُونِ࣌', 'وما أرسلنا من قبلك من رسول ࡴلا يوحى إليه أنه لا إله إلا أنا فاعبدون࣌', NULL, 324, 'local:warsh-text.json'),
  ('warsh-21-26', 'warsh', 21, 26, 'وَقَالُواْ ࡲٜتَّخَذَ ࡰ۬لرَّحْمَٰنُ وَلَداࣰ࣌ سُبْحَٰنَهُۥ࣌ بَلْ عِبَادࣱ مُّكْرَمُونَ࣌', 'وقالوا ࡲتخذ ࡰلرحمن ولدا࣌ سبحنه࣌ بل عباد مكرمون࣌', NULL, 324, 'local:warsh-text.json'),
  ('warsh-21-27', 'warsh', 21, 27, 'لَا يَسْبِقُونَهُۥ بِالْقَوْلِ وَهُم بِأَمْرِهِۦ يَعْمَلُونَ࣌', 'لا يسبقونه بالقول وهم بأمره يعملون࣌', NULL, 324, 'local:warsh-text.json'),
  ('warsh-21-28', 'warsh', 21, 28, 'يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ࣌ وَلَا يَشْفَعُونَ إِلَّا لِمَنِ ࡴٜرْتَضٜىٰ وَهُم مِّنْ خَشْيَتِهِۦ مُشْفِقُونَ࣌', 'يعلم ما بين أيديهم وما خلفهم࣌ ولا يشفعون إلا لمن ࡴرتضى وهم من خشيته مشفقون࣌', NULL, 324, 'local:warsh-text.json'),
  ('warsh-21-29', 'warsh', 21, 29, 'وَمَنْ يَّقُلْ مِنْهُمُۥٓ إِنِّيَ إِلَٰهࣱ مِّن دُونِهِۦ فَذَٰلِكَ نَجْزِيهِ جَهَنَّمَ࣌ كَذَٰلِكَ نَجْزِے ࡴ۬لظَّٰلِمِينَ࣌', 'ومن يقل منهم إني إله من دونه فذلك نجزيه جهنم࣌ كذلك نجزے ࡴلظلمين࣌', NULL, 324, 'local:warsh-text.json'),
  ('warsh-21-30', 'warsh', 21, 30, '۞ أَوَلَمْ يَرَ ࡰ۬لذِينَ كَفَرُوٓاْ أَنَّ ࡰ۬لسَّمَٰوَٰتِ وَالَارْضَ كَانَتَا رَتْقاࣰ فَفَتَقْنَٰهُمَا࣌ وَجَعَلْنَا مِنَ ࡰ۬لْمَآءِ كُلَّ شَےْءٍ حَيٍّ࣌ ࡰفَلَا يُومِنُونَ࣌', 'أولم ير ࡰلذين كفروا أن ࡰلسموت والارض كانتا رتقا ففتقنهما࣌ وجعلنا من ࡰلماء كل شےء حي࣌ ࡰفلا يومنون࣌', NULL, 324, 'local:warsh-text.json'),
  ('warsh-21-31', 'warsh', 21, 31, 'وَجَعَلْنَا فِے ࡴ۬لَارْضِ رَوَٰسِيَ أَن تَمِيدَ بِهِمْ࣌ وَجَعَلْنَا فِيهَا فِجَاجاࣰ سُبُلاࣰ لَّعَلَّهُمْ يَهْتَدُونَ࣌', 'وجعلنا فے ࡴلارض روسي أن تميد بهم࣌ وجعلنا فيها فجاجا سبلا لعلهم يهتدون࣌', NULL, 324, 'local:warsh-text.json'),
  ('warsh-21-32', 'warsh', 21, 32, 'وَجَعَلْنَا ࡰ۬لسَّمَآءَ سَقْفاࣰ مَّحْفُوظاࣰ࣌ وَهُمْ عَنَ اٰيَٰتِهَا مُعْرِضُونَ࣌', 'وجعلنا ࡰلسماء سقفا محفوظا࣌ وهم عن ايتها معرضون࣌', NULL, 324, 'local:warsh-text.json'),
  ('warsh-21-33', 'warsh', 21, 33, 'وَهُوَ ࡰ۬لذِے خَلَقَ ࡰ۬ليْلَ وَالنَّهَارَ وَالشَّمْسَ وَالْقَمَرَ࣌ كُلࣱّ فِے فَلَكࣲ يَسْبَحُونَ࣌', 'وهو ࡰلذے خلق ࡰليل والنهار والشمس والقمر࣌ كل فے فلك يسبحون࣌', NULL, 324, 'local:warsh-text.json'),
  ('warsh-21-34', 'warsh', 21, 34, 'وَمَا جَعَلْنَا لِبَشَرࣲ مِّن قَبْلِكَ ࡰ۬لْخُلْدَ࣌ أَفَإِيْن مِّتَّ فَهُمُ ࡲ۬لْخَٰلِدُونَ࣌', 'وما جعلنا لبشر من قبلك ࡰلخلد࣌ أفإين مت فهم ࡲلخلدون࣌', NULL, 324, 'local:warsh-text.json'),
  ('warsh-21-35', 'warsh', 21, 35, 'كُلُّ نَفْسࣲ ذَآئِقَةُ ࡲ۬لْمَوْتِ࣌ وَنَبْلُوكُم بِالشَّرِّ وَالْخَيْرِ فِتْنَةࣰ࣌ وَإِلَيْنَا تُرْجَعُونَ࣌', 'كل نفس ذائقة ࡲلموت࣌ ونبلوكم بالشر والخير فتنة࣌ وإلينا ترجعون࣌', NULL, 324, 'local:warsh-text.json'),
  ('warsh-21-36', 'warsh', 21, 36, 'وَإِذَا رٜءٜاكَ ࡰ۬لذِينَ كَفَرُوٓاْ إِنْ يَّتَّخِذُونَكَ إِلَّا هُزُؤاً࣌ ࡰهَٰذَا ࡰ۬لذِے يَذْكُرُ ءَالِهَتَكُمْ وَهُم بِذِكْرِ ࡴ۬لرَّحْمَٰنِ هُمْ كَٰفِرُونَ࣌', 'وإذا رءاك ࡰلذين كفروا إن يتخذونك إلا هزؤا࣌ ࡰهذا ࡰلذے يذكر ءالهتكم وهم بذكر ࡴلرحمن هم كفرون࣌', NULL, 325, 'local:warsh-text.json'),
  ('warsh-21-37', 'warsh', 21, 37, 'خُلِقَ ࡰ۬لِانسَٰنُ مِنْ عَجَلࣲ࣌ سَأُوْرِيكُمُۥٓ ءَايَٰتِے فَلَا تَسْتَعْجِلُونِ࣌', 'خلق ࡰلانسن من عجل࣌ سأوريكم ءايتے فلا تستعجلون࣌', NULL, 325, 'local:warsh-text.json'),
  ('warsh-21-38', 'warsh', 21, 38, 'وَيَقُولُونَ مَتٜىٰ هَٰذَا ࡰ۬لْوَعْدُ إِن كُنتُمْ صَٰدِقِينَ࣌', 'ويقولون متى هذا ࡰلوعد إن كنتم صدقين࣌', NULL, 325, 'local:warsh-text.json'),
  ('warsh-21-39', 'warsh', 21, 39, 'لَوْ يَعْلَمُ ࡲ۬لذِينَ كَفَرُواْ حِينَ لَا يَكُفُّونَ عَنْ وُّجُوهِهِمُ ࡲ۬لنَّارَ وَلَا عَن ظُهُورِهِمْ وَلَا هُمْ يُنصَرُونَ࣌', 'لو يعلم ࡲلذين كفروا حين لا يكفون عن وجوههم ࡲلنار ولا عن ظهورهم ولا هم ينصرون࣌', NULL, 325, 'local:warsh-text.json'),
  ('warsh-21-40', 'warsh', 21, 40, 'بَلْ تَاتِيهِم بَغْتَةࣰ فَتَبْهَتُهُمْ فَلَا يَسْتَطِيعُونَ رَدَّهَا وَلَا هُمْ يُنظَرُونَ࣌', 'بل تاتيهم بغتة فتبهتهم فلا يستطيعون ردها ولا هم ينظرون࣌', NULL, 325, 'local:warsh-text.json'),
  ('warsh-21-41', 'warsh', 21, 41, 'وَلَقَدُ ࡲ࢈سْتُهْزِۓَ بِرُسُلࣲ مِّن قَبْلِكَ فَحَاقَ بِالذِينَ سَخِرُواْ مِنْهُم مَّا كَانُواْ بِهِۦ يَسْتَهْزِءُونَ࣌', 'ولقد ࡲ࢈ستهزے برسل من قبلك فحاق بالذين سخروا منهم ما كانوا به يستهزءون࣌', NULL, 325, 'local:warsh-text.json'),
  ('warsh-21-42', 'warsh', 21, 42, '۞ قُلْ مَنْ يَّكْلَؤُكُم بِاليْلِ وَالنَّهٜارِ مِنَ ࡰ۬لرَّحْمَٰنِ࣌ بَلْ هُمْ عَن ذِكْرِ رَبِّهِم مُّعْرِضُونَ࣌', 'قل من يكلؤكم باليل والنهار من ࡰلرحمن࣌ بل هم عن ذكر ربهم معرضون࣌', NULL, 325, 'local:warsh-text.json'),
  ('warsh-21-43', 'warsh', 21, 43, 'أَمْ لَهُمُۥٓ ءَالِهَةࣱ تَمْنَعُهُم مِّن دُونِنَا࣌ لَا يَسْتَطِيعُونَ نَصْرَ أَنفُسِهِمْ وَلَا هُم مِّنَّا يُصْحَبُونَ࣌', 'أم لهم ءالهة تمنعهم من دوننا࣌ لا يستطيعون نصر أنفسهم ولا هم منا يصحبون࣌', NULL, 325, 'local:warsh-text.json'),
  ('warsh-21-44', 'warsh', 21, 44, 'بَلْ مَتَّعْنَا هَٰٓؤُلَآءِ وَءَابَآءَهُمْ حَتَّىٰ طَالَ عَلَيْهِمُ ࡲ۬لْعُمُرُ࣌ أَفَلَا يَرَوْنَ أَنَّا نَاتِے ࡴ۬لَارْضَ نَنقُصُهَا مِنَ ࡰطْرَافِهَآ࣌ أَفَهُمُ ࡲ۬لْغَٰلِبُونَ࣌', 'بل متعنا هؤلاء وءاباءهم حتى طال عليهم ࡲلعمر࣌ أفلا يرون أنا ناتے ࡴلارض ننقصها من ࡰطرافها࣌ أفهم ࡲلغلبون࣌', NULL, 325, 'local:warsh-text.json'),
  ('warsh-21-45', 'warsh', 21, 45, 'قُلِ ࡴنَّمَآ أُنذِرُكُم بِالْوَحْيِ࣌ وَلَا يَسْمَعُ ࡲ۬لصُّمُّ ࡲ۬لدُّعَآءَ ࡹذَا مَا يُنذَرُونَ࣌', 'قل ࡴنما أنذركم بالوحي࣌ ولا يسمع ࡲلصم ࡲلدعاء ࡹذا ما ينذرون࣌', NULL, 326, 'local:warsh-text.json'),
  ('warsh-21-46', 'warsh', 21, 46, 'وَلَئِن مَّسَّتْهُمْ نَفْحَةࣱ مِّنْ عَذَابِ رَبِّكَ لَيَقُولُنَّ يَٰوَيْلَنَآ إِنَّا كُنَّا ظَٰلِمِينَ࣌', 'ولئن مستهم نفحة من عذاب ربك ليقولن يويلنا إنا كنا ظلمين࣌', NULL, 326, 'local:warsh-text.json'),
  ('warsh-21-47', 'warsh', 21, 47, 'وَنَضَعُ ࡲ۬لْمَوَٰزِينَ ࡰ۬لْقِسْطَ لِيَوْمِ ࡴ۬لْقِيَٰمَةِ فَلَا تُظْلَمُ نَفْسࣱ شَيْـٔاࣰ࣌ وَإِن كَانَ مِثْقَالُ حَبَّةࣲ مِّنْ خَرْدَلٍ ࡰتَيْنَا بِهَا وَكَفٜىٰ بِنَا حَٰسِبِينَ࣌', 'ونضع ࡲلموزين ࡰلقسط ليوم ࡴلقيمة فلا تظلم نفس شيا࣌ وإن كان مثقال حبة من خردل ࡰتينا بها وكفى بنا حسبين࣌', NULL, 326, 'local:warsh-text.json'),
  ('warsh-21-48', 'warsh', 21, 48, 'وَلَقَدَ اٰتَيْنَا مُوسٜىٰ وَهَٰرُونَ ࡰ۬لْفُرْقَانَ وَضِيَآءࣰ وَذِكْراࣰ لِّلْمُتَّقِينَ', 'ولقد اتينا موسى وهرون ࡰلفرقان وضياء وذكرا للمتقين', NULL, 326, 'local:warsh-text.json'),
  ('warsh-21-49', 'warsh', 21, 49, 'ࡰ۬لذِينَ يَخْشَوْنَ رَبَّهُم بِالْغَيْبِ وَهُم مِّنَ ࡰ۬لسَّاعَةِ مُشْفِقُونَ࣌', 'ࡰلذين يخشون ربهم بالغيب وهم من ࡰلساعة مشفقون࣌', NULL, 326, 'local:warsh-text.json'),
  ('warsh-21-50', 'warsh', 21, 50, 'وَهَٰذَا ذِكْرࣱ مُّبَٰرَكٌ ࡰنزَلْنَٰهُ࣌ أَفَأَنتُمْ لَهُۥ مُنكِرُونَ࣌', 'وهذا ذكر مبرك ࡰنزلنه࣌ أفأنتم له منكرون࣌', NULL, 326, 'local:warsh-text.json'),
  ('warsh-21-51', 'warsh', 21, 51, '۞ وَلَقَدَ اٰتَيْنَآ إِبْرَٰهِيمَ رُشْدَهُۥ مِن قَبْلُ وَكُنَّا بِهِۦ عَٰلِمِينَ࣌', 'ولقد اتينا إبرهيم رشده من قبل وكنا به علمين࣌', NULL, 326, 'local:warsh-text.json'),
  ('warsh-21-52', 'warsh', 21, 52, 'إِذْ قَالَ لِأَبِيهِ وَقَوْمِهِۦ مَا هَٰذِهِ ࡴ۬لتَّمَاثِيلُ ࡲ۬لتِےٓ أَنتُمْ لَهَا عَٰكِفُونَ࣌', 'إذ قال لأبيه وقومه ما هذه ࡴلتماثيل ࡲلتے أنتم لها عكفون࣌', NULL, 326, 'local:warsh-text.json'),
  ('warsh-21-53', 'warsh', 21, 53, 'قَالُواْ وَجَدْنَآ ءَابَآءَنَا لَهَا عَٰبِدِينَ࣌', 'قالوا وجدنا ءاباءنا لها عبدين࣌', NULL, 326, 'local:warsh-text.json'),
  ('warsh-21-54', 'warsh', 21, 54, 'قَالَ لَقَدْ كُنتُمُۥٓ أَنتُمْ وَءَابَآؤُكُمْ فِے ضَلَٰلࣲ مُّبِينࣲ࣌', 'قال لقد كنتم أنتم وءاباؤكم فے ضلل مبين࣌', NULL, 326, 'local:warsh-text.json'),
  ('warsh-21-55', 'warsh', 21, 55, 'قَالُوٓاْ أَجِئْتَنَا بِالْحَقِّ أَمَ ࡰنتَ مِنَ ࡰ۬للَّٰعِبِينَ࣌', 'قالوا أجئتنا بالحق أم ࡰنت من ࡰللعبين࣌', NULL, 326, 'local:warsh-text.json'),
  ('warsh-21-56', 'warsh', 21, 56, 'قَالَ بَل رَّبُّكُمْ رَبُّ ࡲ۬لسَّمَٰوَٰتِ وَالَارْضِ ࡴ۬لذِے فَطَرَهُنَّ࣌ وَأَنَا عَلَىٰ ذَٰلِكُم مِّنَ ࡰ۬لشَّٰهِدِينَ࣌', 'قال بل ربكم رب ࡲلسموت والارض ࡴلذے فطرهن࣌ وأنا على ذلكم من ࡰلشهدين࣌', NULL, 326, 'local:warsh-text.json'),
  ('warsh-21-57', 'warsh', 21, 57, 'وَتَاللَّهِ لَأَكِيدَنَّ أَصْنَٰمَكُم بَعْدَ أَن تُوَلُّواْ مُدْبِرِينَ࣌', 'وتالله لأكيدن أصنمكم بعد أن تولوا مدبرين࣌', NULL, 326, 'local:warsh-text.json'),
  ('warsh-21-58', 'warsh', 21, 58, 'فَجَعَلَهُمْ جُذَٰذاً ࡴلَّا كَبِيراࣰ لَّهُمْ لَعَلَّهُمُۥٓ إِلَيْهِ يَرْجِعُونَ࣌', 'فجعلهم جذذا ࡴلا كبيرا لهم لعلهم إليه يرجعون࣌', NULL, 327, 'local:warsh-text.json'),
  ('warsh-21-59', 'warsh', 21, 59, 'قَالُواْ مَن فَعَلَ هَٰذَا بِـَٔالِهَتِنَآ إِنَّهُۥ لَمِنَ ࡰ۬لظَّٰلِمِينَ࣌', 'قالوا من فعل هذا بالهتنا إنه لمن ࡰلظلمين࣌', NULL, 327, 'local:warsh-text.json'),
  ('warsh-21-60', 'warsh', 21, 60, 'قَالُواْ سَمِعْنَا فَتىࣰ يَذْكُرُهُمْ يُقَالُ لَهُۥٓ إِبْرَٰهِيمُ࣌', 'قالوا سمعنا فتى يذكرهم يقال له إبرهيم࣌', NULL, 327, 'local:warsh-text.json'),
  ('warsh-21-61', 'warsh', 21, 61, 'قَالُواْ فَاتُواْ بِهِۦ عَلَىٰٓ أَعْيُنِ ࡴ۬لنَّاسِ لَعَلَّهُمْ يَشْهَدُونَ࣌', 'قالوا فاتوا به على أعين ࡴلناس لعلهم يشهدون࣌', NULL, 327, 'local:warsh-text.json'),
  ('warsh-21-62', 'warsh', 21, 62, 'قَالُوٓاْ ءَآنتَ فَعَلْتَ هَٰذَا بِـَٔالِهَتِنَا يَٰٓإِبْرَٰهِيمُ࣌', 'قالوا ءانت فعلت هذا بالهتنا يإبرهيم࣌', NULL, 327, 'local:warsh-text.json'),
  ('warsh-21-63', 'warsh', 21, 63, 'قَالَ بَلْ فَعَلَهُۥ كَبِيرُهُمْ هَٰذَا فَسْـَٔلُوهُمُۥٓ إِن كَانُواْ يَنطِقُونَ࣌', 'قال بل فعله كبيرهم هذا فسلوهم إن كانوا ينطقون࣌', NULL, 327, 'local:warsh-text.json'),
  ('warsh-21-64', 'warsh', 21, 64, 'فَرَجَعُوٓاْ إِلَىٰٓ أَنفُسِهِمْ فَقَالُوٓاْ إِنَّكُمُۥٓ أَنتُمُ ࡲ۬لظَّٰلِمُونَ࣌', 'فرجعوا إلى أنفسهم فقالوا إنكم أنتم ࡲلظلمون࣌', NULL, 327, 'local:warsh-text.json'),
  ('warsh-21-65', 'warsh', 21, 65, 'ثُمَّ نُكِسُواْ عَلَىٰ رُءُوسِهِمْ࣌ لَقَدْ عَلِمْتَ مَا هَٰٓؤُلَآءِ يَنطِقُونَ࣌', 'ثم نكسوا على رءوسهم࣌ لقد علمت ما هؤلاء ينطقون࣌', NULL, 327, 'local:warsh-text.json'),
  ('warsh-21-66', 'warsh', 21, 66, 'قَالَ أَفَتَعْبُدُونَ مِن دُونِ ࡴ۬للَّهِ مَا لَا يَنفَعُكُمْ شَيْـٔاࣰ وَلَا يَضُرُّكُمُۥٓ࣌ أُفࣲّ لَّكُمْ وَلِمَا تَعْبُدُونَ مِن دُونِ ࡴ۬للَّهِ࣌ أَفَلَا تَعْقِلُونَ࣌', 'قال أفتعبدون من دون ࡴلله ما لا ينفعكم شيا ولا يضركم࣌ أف لكم ولما تعبدون من دون ࡴلله࣌ أفلا تعقلون࣌', NULL, 327, 'local:warsh-text.json'),
  ('warsh-21-67', 'warsh', 21, 67, 'قَالُواْ حَرِّقُوهُ وَانصُرُوٓاْ ءَالِهَتَكُمُۥٓ إِن كُنتُمْ فَٰعِلِينَ࣌', 'قالوا حرقوه وانصروا ءالهتكم إن كنتم فعلين࣌', NULL, 327, 'local:warsh-text.json'),
  ('warsh-21-68', 'warsh', 21, 68, 'قُلْنَا يَٰنَارُ كُونِے بَرْداࣰ وَسَلَٰماً عَلَىٰٓ إِبْرَٰهِيمَ࣌', 'قلنا ينار كونے بردا وسلما على إبرهيم࣌', NULL, 327, 'local:warsh-text.json'),
  ('warsh-21-69', 'warsh', 21, 69, 'وَأَرَادُواْ بِهِۦ كَيْداࣰ فَجَعَلْنَٰهُمُ ࡲ۬لَاخْسَرِينَ࣌', 'وأرادوا به كيدا فجعلنهم ࡲلاخسرين࣌', NULL, 327, 'local:warsh-text.json'),
  ('warsh-21-70', 'warsh', 21, 70, 'وَنَجَّيْنَٰهُ وَلُوطاً ࡴلَى ࡰ۬لَارْضِ ࡴ۬لتِے بَٰرَكْنَا فِيهَا لِلْعَٰلَمِينَ࣌', 'ونجينه ولوطا ࡴلى ࡰلارض ࡴلتے بركنا فيها للعلمين࣌', NULL, 327, 'local:warsh-text.json'),
  ('warsh-21-71', 'warsh', 21, 71, 'وَوَهَبْنَا لَهُۥٓ إِسْحَٰقَ࣌ وَيَعْقُوبَ نَافِلَةࣰ࣌ وَكُلّاࣰ جَعَلْنَا صَٰلِحِينَ࣌', 'ووهبنا له إسحق࣌ ويعقوب نافلة࣌ وكلا جعلنا صلحين࣌', NULL, 327, 'local:warsh-text.json'),
  ('warsh-21-72', 'warsh', 21, 72, '۞ وَجَعَلْنَٰهُمُۥٓ أَئِمَّةࣰ يَهْدُونَ بِأَمْرِنَا࣌ وَأَوْحَيْنَآ إِلَيْهِمْ فِعْلَ ࡰ۬لْخَيْرَٰتِ وَإِقَامَ ࡰ۬لصَّلَوٰةِ وَإِيتَآءَ ࡰ۬لزَّكَوٰةِ࣌ وَكَانُواْ لَنَا عَٰبِدِينَ࣌', 'وجعلنهم أئمة يهدون بأمرنا࣌ وأوحينا إليهم فعل ࡰلخيرت وإقام ࡰلصلوة وإيتاء ࡰلزكوة࣌ وكانوا لنا عبدين࣌', NULL, 328, 'local:warsh-text.json'),
  ('warsh-21-73', 'warsh', 21, 73, 'وَلُوطاً اٰتَيْنَٰهُ حُكْماࣰ وَعِلْماࣰ࣌ وَنَجَّيْنَٰهُ مِنَ ࡰ۬لْقَرْيَةِ ࡴ۬لتِے كَانَت تَّعْمَلُ ࡲ۬لْخَبَٰٓئِثَ࣌ إِنَّهُمْ كَانُواْ قَوْمَ سَوْءࣲ فَٰسِقِينَ࣌', 'ولوطا اتينه حكما وعلما࣌ ونجينه من ࡰلقرية ࡴلتے كانت تعمل ࡲلخبئث࣌ إنهم كانوا قوم سوء فسقين࣌', NULL, 328, 'local:warsh-text.json'),
  ('warsh-21-74', 'warsh', 21, 74, 'وَأَدْخَلْنَٰهُ فِے رَحْمَتِنَآ࣌ إِنَّهُۥ مِنَ ࡰ۬لصَّٰلِحِينَ࣌', 'وأدخلنه فے رحمتنا࣌ إنه من ࡰلصلحين࣌', NULL, 328, 'local:warsh-text.json'),
  ('warsh-21-75', 'warsh', 21, 75, 'وَنُوحاً ࡴذْ نَادٜىٰ مِن قَبْلُ فَاسْتَجَبْنَا لَهُۥ فَنَجَّيْنَٰهُ وَأَهْلَهُۥ مِنَ ࡰ۬لْكَرْبِ ࡴ۬لْعَظِيمِ࣌', 'ونوحا ࡴذ نادى من قبل فاستجبنا له فنجينه وأهله من ࡰلكرب ࡴلعظيم࣌', NULL, 328, 'local:warsh-text.json'),
  ('warsh-21-76', 'warsh', 21, 76, 'وَنَصَرْنَٰهُ مِنَ ࡰ۬لْقَوْمِ ࡴ۬لذِينَ كَذَّبُواْ بِـَٔايَٰتِنَآ࣌ إِنَّهُمْ كَانُواْ قَوْمَ سَوْءࣲ فَأَغْرَقْنَٰهُمُۥٓ أَجْمَعِينَ࣌', 'ونصرنه من ࡰلقوم ࡴلذين كذبوا بايتنا࣌ إنهم كانوا قوم سوء فأغرقنهم أجمعين࣌', NULL, 328, 'local:warsh-text.json'),
  ('warsh-21-77', 'warsh', 21, 77, 'وَدَاوُۥدَ وَسُلَيْمَٰنَ إِذْ يَحْكُمَٰنِ فِے ࡴ۬لْحَرْثِ إِذْ نَفَشَتْ فِيهِ غَنَمُ ࡲ۬لْقَوْمِ࣌ وَكُنَّا لِحُكْمِهِمْ شَٰهِدِينَ࣌', 'وداود وسليمن إذ يحكمن فے ࡴلحرث إذ نفشت فيه غنم ࡲلقوم࣌ وكنا لحكمهم شهدين࣌', NULL, 328, 'local:warsh-text.json'),
  ('warsh-21-78', 'warsh', 21, 78, 'فَفَهَّمْنَٰهَا سُلَيْمَٰنَ࣌ وَكُلّاً اٰتَيْنَا حُكْماࣰ وَعِلْماࣰ࣌ وَسَخَّرْنَا مَعَ دَاوُۥدَ ࡰ۬لْجِبَالَ يُسَبِّحْنَ وَالطَّيْرَ࣌ وَكُنَّا فَٰعِلِينَ࣌', 'ففهمنها سليمن࣌ وكلا اتينا حكما وعلما࣌ وسخرنا مع داود ࡰلجبال يسبحن والطير࣌ وكنا فعلين࣌', NULL, 328, 'local:warsh-text.json'),
  ('warsh-21-79', 'warsh', 21, 79, 'وَعَلَّمْنَٰهُ صَنْعَةَ لَبُوسࣲ لَّكُمْ لِيُحْصِنَكُم مِّنۢ بَأْسِكُمْ࣌ فَهَلَ ࡰنتُمْ شَٰكِرُونَ࣌', 'وعلمنه صنعة لبوس لكم ليحصنكم من بأسكم࣌ فهل ࡰنتم شكرون࣌', NULL, 328, 'local:warsh-text.json'),
  ('warsh-21-80', 'warsh', 21, 80, 'وَلِسُلَيْمَٰنَ ࡰ۬لرِّيحَ عَاصِفَةࣰ تَجْرِے بِأَمْرِهِۦٓ إِلَى ࡰ۬لَارْضِ ࡴ۬لتِے بَٰرَكْنَا فِيهَا࣌ وَكُنَّا بِكُلِّ شَےْءٍ عَٰلِمِينَ࣌', 'ولسليمن ࡰلريح عاصفة تجرے بأمره إلى ࡰلارض ࡴلتے بركنا فيها࣌ وكنا بكل شےء علمين࣌', NULL, 328, 'local:warsh-text.json'),
  ('warsh-21-81', 'warsh', 21, 81, 'وَمِنَ ࡰ۬لشَّيَٰطِينِ مَنْ يَّغُوصُونَ لَهُۥ وَيَعْمَلُونَ عَمَلاࣰ دُونَ ذَٰلِكَ࣌ وَكُنَّا لَهُمْ حَٰفِظِينَ࣌', 'ومن ࡰلشيطين من يغوصون له ويعملون عملا دون ذلك࣌ وكنا لهم حفظين࣌', NULL, 329, 'local:warsh-text.json'),
  ('warsh-21-82', 'warsh', 21, 82, 'وَأَيُّوبَ إِذْ نَادٜىٰ رَبَّهُۥٓ أَنِّے مَسَّنِيَ ࡰ۬لضُّرُّ وَأَنتَ أَرْحَمُ ࡲ۬لرَّٰحِمِينَ࣌', 'وأيوب إذ نادى ربه أنے مسني ࡰلضر وأنت أرحم ࡲلرحمين࣌', NULL, 329, 'local:warsh-text.json'),
  ('warsh-21-83', 'warsh', 21, 83, 'فَاسْتَجَبْنَا لَهُۥ فَكَشَفْنَا مَا بِهِۦ مِن ضُرࣲّ࣌ وَءَاتَيْنَٰهُ أَهْلَهُۥ وَمِثْلَهُم مَّعَهُمْ رَحْمَةࣰ مِّنْ عِندِنَا وَذِكْرٜىٰ لِلْعَٰبِدِينَ࣌', 'فاستجبنا له فكشفنا ما به من ضر࣌ وءاتينه أهله ومثلهم معهم رحمة من عندنا وذكرى للعبدين࣌', NULL, 329, 'local:warsh-text.json'),
  ('warsh-21-84', 'warsh', 21, 84, 'وَإِسْمَٰعِيلَ وَإِدْرِيسَ وَذَا ࡰ۬لْكِفْلِ࣌ كُلࣱّ مِّنَ ࡰ۬لصَّٰبِرِينَ࣌', 'وإسمعيل وإدريس وذا ࡰلكفل࣌ كل من ࡰلصبرين࣌', NULL, 329, 'local:warsh-text.json'),
  ('warsh-21-85', 'warsh', 21, 85, 'وَأَدْخَلْنَٰهُمْ فِے رَحْمَتِنَآ࣌ إِنَّهُم مِّنَ ࡰ۬لصَّٰلِحِينَ࣌', 'وأدخلنهم فے رحمتنا࣌ إنهم من ࡰلصلحين࣌', NULL, 329, 'local:warsh-text.json'),
  ('warsh-21-86', 'warsh', 21, 86, '۞ وَذَا ࡰ۬لنُّونِ إِذ ذَّهَبَ مُغَٰضِباࣰ فَظَنَّ أَن لَّن نَّقْدِرَ عَلَيْهِ فَنَادٜىٰ فِے ࡴ۬لظُّلُمَٰتِ أَن لَّآ إِلَٰهَ إِلَّآ أَنتَ سُبْحَٰنَكَ إِنِّے كُنتُ مِنَ ࡰ۬لظَّٰلِمِينَ࣌', 'وذا ࡰلنون إذ ذهب مغضبا فظن أن لن نقدر عليه فنادى فے ࡴلظلمت أن لا إله إلا أنت سبحنك إنے كنت من ࡰلظلمين࣌', NULL, 329, 'local:warsh-text.json'),
  ('warsh-21-87', 'warsh', 21, 87, 'فَاسْتَجَبْنَا لَهُۥ وَنَجَّيْنَٰهُ مِنَ ࡰ۬لْغَمِّ࣌ وَكَذَٰلِكَ نُنجِے ࡴ۬لْمُومِنِينَ࣌', 'فاستجبنا له ونجينه من ࡰلغم࣌ وكذلك ننجے ࡴلمومنين࣌', NULL, 329, 'local:warsh-text.json'),
  ('warsh-21-88', 'warsh', 21, 88, 'وَزَكَرِيَّآءَ ࡹذْ نَادٜىٰ رَبَّهُۥ رَبِّ لَا تَذَرْنِے فَرْداࣰ وَأَنتَ خَيْرُ ࡲ۬لْوَٰرِثِينَ࣌', 'وزكرياء ࡹذ نادى ربه رب لا تذرنے فردا وأنت خير ࡲلورثين࣌', NULL, 329, 'local:warsh-text.json'),
  ('warsh-21-89', 'warsh', 21, 89, 'فَاسْتَجَبْنَا لَهُۥ وَوَهَبْنَا لَهُۥ يَحْيٜىٰ وَأَصْلَحْنَا لَهُۥ زَوْجَهُۥٓ࣌ إِنَّهُمْ كَانُواْ يُسَٰرِعُونَ فِے ࡴ۬لْخَيْرَٰتِ وَيَدْعُونَنَا رَغَباࣰ وَرَهَباࣰ وَكَانُواْ لَنَا خَٰشِعِينَ࣌', 'فاستجبنا له ووهبنا له يحيى وأصلحنا له زوجه࣌ إنهم كانوا يسرعون فے ࡴلخيرت ويدعوننا رغبا ورهبا وكانوا لنا خشعين࣌', NULL, 329, 'local:warsh-text.json'),
  ('warsh-21-90', 'warsh', 21, 90, 'وَالتِےٓ أَحْصَنَتْ فَرْجَهَا فَنَفَخْنَا فِيهَا مِن رُّوحِنَا وَجَعَلْنَٰهَا وَابْنَهَآ ءَايَةࣰ لِّلْعَٰلَمِينَ࣌', 'والتے أحصنت فرجها فنفخنا فيها من روحنا وجعلنها وابنها ءاية للعلمين࣌', NULL, 330, 'local:warsh-text.json'),
  ('warsh-21-91', 'warsh', 21, 91, 'إِنَّ هَٰذِهِۦٓ أُمَّتُكُمُۥٓ أُمَّةࣰ وَٰحِدَةࣰ࣌ وَأَنَا رَبُّكُمْ فَاعْبُدُونِ࣌', 'إن هذه أمتكم أمة وحدة࣌ وأنا ربكم فاعبدون࣌', NULL, 330, 'local:warsh-text.json'),
  ('warsh-21-92', 'warsh', 21, 92, 'وَتَقَطَّعُوٓاْ أَمْرَهُم بَيْنَهُمْ࣌ كُلٌّ ࡴلَيْنَا رَٰجِعُونَ࣌', 'وتقطعوا أمرهم بينهم࣌ كل ࡴلينا رجعون࣌', NULL, 330, 'local:warsh-text.json'),
  ('warsh-21-93', 'warsh', 21, 93, 'فَمَنْ يَّعْمَلْ مِنَ ࡰ۬لصَّٰلِحَٰتِ وَهُوَ مُومِنࣱ فَلَا كُفْرَانَ لِسَعْيِهِۦ࣌ وَإِنَّا لَهُۥ كَٰتِبُونَ࣌', 'فمن يعمل من ࡰلصلحت وهو مومن فلا كفران لسعيه࣌ وإنا له كتبون࣌', NULL, 330, 'local:warsh-text.json'),
  ('warsh-21-94', 'warsh', 21, 94, 'وَحَرَٰمٌ عَلَىٰ قَرْيَةٍ ࡰهْلَكْنَٰهَآ أَنَّهُمْ لَا يَرْجِعُونَ࣌', 'وحرم على قرية ࡰهلكنها أنهم لا يرجعون࣌', NULL, 330, 'local:warsh-text.json'),
  ('warsh-21-95', 'warsh', 21, 95, 'حَتَّىٰٓ إِذَا فُتِحَتْ يَاجُوجُ وَمَاجُوجُ وَهُم مِّن كُلِّ حَدَبࣲ يَنسِلُونَ', 'حتى إذا فتحت ياجوج وماجوج وهم من كل حدب ينسلون', NULL, 330, 'local:warsh-text.json'),
  ('warsh-21-96', 'warsh', 21, 96, 'وَاقْتَرَبَ ࡰ۬لْوَعْدُ ࡲ۬لْحَقُّ فَإِذَا هِيَ شَٰخِصَةٌ ࡰبْصَٰرُ ࡲ۬لذِينَ كَفَرُواْ يَٰوَيْلَنَا قَدْ كُنَّا فِے غَفْلَةࣲ مِّنْ هَٰذَا بَلْ كُنَّا ظَٰلِمِينَ࣌', 'واقترب ࡰلوعد ࡲلحق فإذا هي شخصة ࡰبصر ࡲلذين كفروا يويلنا قد كنا فے غفلة من هذا بل كنا ظلمين࣌', NULL, 330, 'local:warsh-text.json'),
  ('warsh-21-97', 'warsh', 21, 97, 'إِنَّكُمْ وَمَا تَعْبُدُونَ مِن دُونِ ࡴ۬للَّهِ حَصَبُ جَهَنَّمَ أَنتُمْ لَهَا وَٰرِدُونَ࣌', 'إنكم وما تعبدون من دون ࡴلله حصب جهنم أنتم لها وردون࣌', NULL, 330, 'local:warsh-text.json'),
  ('warsh-21-98', 'warsh', 21, 98, 'لَوْ كَانَ هَٰٓؤُلَآءِ ࢇَالِهَةࣰ مَّا وَرَدُوهَا࣌ وَكُلࣱّ فِيهَا خَٰلِدُونَ࣌', 'لو كان هؤلاء ࢇالهة ما وردوها࣌ وكل فيها خلدون࣌', NULL, 330, 'local:warsh-text.json'),
  ('warsh-21-99', 'warsh', 21, 99, 'لَهُمْ فِيهَا زَفِيرࣱ وَهُمْ فِيهَا لَا يَسْمَعُونَ࣌', 'لهم فيها زفير وهم فيها لا يسمعون࣌', NULL, 330, 'local:warsh-text.json'),
  ('warsh-21-100', 'warsh', 21, 100, '۞ إِنَّ ࡰ۬لذِينَ سَبَقَتْ لَهُم مِّنَّا ࡰ۬لْحُسْنٜىٰٓ أُوْلَٰٓئِكَ عَنْهَا مُبْعَدُونَ࣌', 'إن ࡰلذين سبقت لهم منا ࡰلحسنى أولئك عنها مبعدون࣌', NULL, 330, 'local:warsh-text.json'),
  ('warsh-21-101', 'warsh', 21, 101, 'لَا يَسْمَعُونَ حَسِيسَهَا وَهُمْ فِے مَا ࡰٜشْتَهَتَ ࡰنفُسُهُمْ خَٰلِدُونَ࣌', 'لا يسمعون حسيسها وهم فے ما ࡰشتهت ࡰنفسهم خلدون࣌', NULL, 331, 'local:warsh-text.json'),
  ('warsh-21-102', 'warsh', 21, 102, 'لَا يَحْزُنُهُمُ ࡲ۬لْفَزَعُ ࡲ۬لَاكْبَرُ࣌ وَتَتَلَقّٜيٰهُمُ ࡲ۬لْمَلَٰٓئِكَةُ هَٰذَا يَوْمُكُمُ ࡲ۬لذِے كُنتُمْ تُوعَدُونَ࣌', 'لا يحزنهم ࡲلفزع ࡲلاكبر࣌ وتتلقيهم ࡲلملئكة هذا يومكم ࡲلذے كنتم توعدون࣌', NULL, 331, 'local:warsh-text.json'),
  ('warsh-21-103', 'warsh', 21, 103, 'يَوْمَ نَطْوِے ࡴ۬لسَّمَآءَ كَطَيِّ ࡴ۬لسِّجِلِّ لِلْكِتَٰبِ࣌ كَمَا بَدَأْنَآ أَوَّلَ خَلْقࣲ نُّعِيدُهُۥ࣌ وَعْداً عَلَيْنَآ࣌ إِنَّا كُنَّا فَٰعِلِينَ࣌', 'يوم نطوے ࡴلسماء كطي ࡴلسجل للكتب࣌ كما بدأنا أول خلق نعيده࣌ وعدا علينا࣌ إنا كنا فعلين࣌', NULL, 331, 'local:warsh-text.json'),
  ('warsh-21-104', 'warsh', 21, 104, 'وَلَقَدْ كَتَبْنَا فِے ࡴ۬لزَّبُورِ مِنۢ بَعْدِ ࡴ۬لذِّكْرِ أَنَّ ࡰ۬لَارْضَ يَرِثُهَا عِبَادِيَ ࡰ۬لصَّٰلِحُونَ࣌', 'ولقد كتبنا فے ࡴلزبور من بعد ࡴلذكر أن ࡰلارض يرثها عبادي ࡰلصلحون࣌', NULL, 331, 'local:warsh-text.json'),
  ('warsh-21-105', 'warsh', 21, 105, 'إِنَّ فِے هَٰذَا لَبَلَٰغاࣰ لِّقَوْمٍ عَٰبِدِينَ࣌', 'إن فے هذا لبلغا لقوم عبدين࣌', NULL, 331, 'local:warsh-text.json'),
  ('warsh-21-106', 'warsh', 21, 106, 'وَمَآ أَرْسَلْنَٰكَ إِلَّا رَحْمَةࣰ لِّلْعَٰلَمِينَ࣌', 'وما أرسلنك إلا رحمة للعلمين࣌', NULL, 331, 'local:warsh-text.json'),
  ('warsh-21-107', 'warsh', 21, 107, 'قُلِ ࡴنَّمَا يُوحٜىٰٓ إِلَيَّ أَنَّمَآ إِلَٰهُكُمُۥٓ إِلَٰهࣱ وَٰحِدࣱ࣌ فَهَلَ ࡰنتُم مُّسْلِمُونَ࣌', 'قل ࡴنما يوحى إلي أنما إلهكم إله وحد࣌ فهل ࡰنتم مسلمون࣌', NULL, 331, 'local:warsh-text.json'),
  ('warsh-21-108', 'warsh', 21, 108, 'فَإِن تَوَلَّوْاْ فَقُلَ اٰذَنتُكُمْ عَلَىٰ سَوَآءࣲ࣌ وَإِنَ ࡰدْرِےٓ أَقَرِيبٌ ࡰم بَعِيدࣱ مَّا تُوعَدُونَ࣌', 'فإن تولوا فقل اذنتكم على سواء࣌ وإن ࡰدرے أقريب ࡰم بعيد ما توعدون࣌', NULL, 331, 'local:warsh-text.json'),
  ('warsh-21-109', 'warsh', 21, 109, 'إِنَّهُۥ يَعْلَمُ ࡲ۬لْجَهْرَ مِنَ ࡰ۬لْقَوْلِ وَيَعْلَمُ مَا تَكْتُمُونَ࣌', 'إنه يعلم ࡲلجهر من ࡰلقول ويعلم ما تكتمون࣌', NULL, 331, 'local:warsh-text.json'),
  ('warsh-21-110', 'warsh', 21, 110, 'وَإِنَ ࡰدْرِے لَعَلَّهُۥ فِتْنَةࣱ لَّكُمْ وَمَتَٰعٌ ࡴلَىٰ حِينࣲ࣌', 'وإن ࡰدرے لعله فتنة لكم ومتع ࡴلى حين࣌', NULL, 331, 'local:warsh-text.json'),
  ('warsh-21-111', 'warsh', 21, 111, 'قُل رَّبِّ ࡴ࢈حْكُم بِالْحَقِّ࣌ وَرَبُّنَا ࡰ۬لرَّحْمَٰنُ ࡲ۬لْمُسْتَعَانُ عَلَىٰ مَا تَصِفُونَ࣌', 'قل رب ࡴ࢈حكم بالحق࣌ وربنا ࡰلرحمن ࡲلمستعان على ما تصفون࣌', NULL, 331, 'local:warsh-text.json'),
  ('warsh-22-1', 'warsh', 22, 1, 'يَٰٓأَيُّهَا ࡰ۬لنَّاسُ ࡲٜتَّقُواْ رَبَّكُمُۥٓ࣌ إِنَّ زَلْزَلَةَ ࡰ۬لسَّاعَةِ شَےْءٌ عَظِيمࣱ࣌', 'يأيها ࡰلناس ࡲتقوا ربكم࣌ إن زلزلة ࡰلساعة شےء عظيم࣌', NULL, 332, 'local:warsh-text.json'),
  ('warsh-22-2', 'warsh', 22, 2, 'يَوْمَ تَرَوْنَهَا تَذْهَلُ كُلُّ مُرْضِعَةٍ عَمَّآ أَرْضَعَتْ وَتَضَعُ كُلُّ ذَاتِ حَمْلٍ حَمْلَهَا وَتَرَى ࡰ۬لنَّاسَ سُكَٰرٜىٰ وَمَا هُم بِسُكَٰرٜىٰ وَلَٰكِنَّ عَذَابَ ࡰ۬للَّهِ شَدِيدࣱ࣌', 'يوم ترونها تذهل كل مرضعة عما أرضعت وتضع كل ذات حمل حملها وترى ࡰلناس سكرى وما هم بسكرى ولكن عذاب ࡰلله شديد࣌', NULL, 332, 'local:warsh-text.json'),
  ('warsh-22-3', 'warsh', 22, 3, 'وَمِنَ ࡰ۬لنَّاسِ مَنْ يُّجَٰدِلُ فِے ࡴ۬للَّهِ بِغَيْرِ عِلْمࣲ وَيَتَّبِعُ كُلَّ شَيْطَٰنࣲ مَّرِيدࣲ', 'ومن ࡰلناس من يجدل فے ࡴلله بغير علم ويتبع كل شيطن مريد', NULL, 332, 'local:warsh-text.json'),
  ('warsh-22-4', 'warsh', 22, 4, 'كُتِبَ عَلَيْهِ أَنَّهُۥ مَن تَوَلّٜاهُ فَأَنَّهُۥ يُضِلُّهُۥ وَيَهْدِيهِ إِلَىٰ عَذَابِ ࡴ۬لسَّعِيرِ࣌', 'كتب عليه أنه من تولاه فأنه يضله ويهديه إلى عذاب ࡴلسعير࣌', NULL, 332, 'local:warsh-text.json'),
  ('warsh-22-5', 'warsh', 22, 5, 'يَٰٓأَيُّهَا ࡰ۬لنَّاسُ إِن كُنتُمْ فِے رَيْبࣲ مِّنَ ࡰ۬لْبَعْثِ فَإِنَّا خَلَقْنَٰكُم مِّن تُرَابࣲ ثُمَّ مِن نُّطْفَةࣲ ثُمَّ مِنْ عَلَقَةࣲ ثُمَّ مِن مُّضْغَةࣲ مُّخَلَّقَةࣲ وَغَيْرِ مُخَلَّقَةࣲ لِّنُبَيِّنَ لَكُمْ࣌ وَنُقِرُّ فِے ࡴ۬لَارْحَامِ مَا نَشَآءُ ࡹِلَىٰٓ أَجَلࣲ مُّسَمّىࣰ࣌ ثُمَّ نُخْرِجُكُمْ طِفْلاࣰ ثُمَّ لِتَبْلُغُوٓاْ أَشُدَّكُمْ࣌ وَمِنكُم مَّنْ يُّتَوَفّٜىٰ وَمِنكُم مَّنْ يُّرَدُّ إِلَىٰٓ أَرْذَلِ ࡴ۬لْعُمُرِ لِكَيْلَا يَعْلَمَ مِنۢ بَعْدِ عِلْمࣲ شَيْـٔاࣰ࣌ وَتَرَى ࡰ۬لَارْضَ هَامِدَةࣰ فَإِذَآ أَنزَلْنَا عَلَيْهَا ࡰ۬لْمَآءَ ࡰٜهْتَزَّتْ وَرَبَتْ وَأَنۢبَتَتْ مِن كُلِّ زَوْجِۢ بَهِيجࣲ࣌', 'يأيها ࡰلناس إن كنتم فے ريب من ࡰلبعث فإنا خلقنكم من تراب ثم من نطفة ثم من علقة ثم من مضغة مخلقة وغير مخلقة لنبين لكم࣌ ونقر فے ࡴلارحام ما نشاء ࡹلى أجل مسمى࣌ ثم نخرجكم طفلا ثم لتبلغوا أشدكم࣌ ومنكم من يتوفى ومنكم من يرد إلى أرذل ࡴلعمر لكيلا يعلم من بعد علم شيا࣌ وترى ࡰلارض هامدة فإذا أنزلنا عليها ࡰلماء ࡰهتزت وربت وأنبتت من كل زوج بهيج࣌', NULL, 332, 'local:warsh-text.json'),
  ('warsh-22-6', 'warsh', 22, 6, 'ذَٰلِكَ بِأَنَّ ࡰ۬للَّهَ هُوَ ࡰ۬لْحَقُّ وَأَنَّهُۥ يُحْيِ ࡴ۬لْمَوْتٜىٰ وَأَنَّهُۥ عَلَىٰ كُلِّ شَےْءࣲ قَدِيرࣱ', 'ذلك بأن ࡰلله هو ࡰلحق وأنه يحي ࡴلموتى وأنه على كل شےء قدير', NULL, 333, 'local:warsh-text.json'),
  ('warsh-22-7', 'warsh', 22, 7, 'وَأَنَّ ࡰ۬لسَّاعَةَ ءَاتِيَةࣱ لَّا رَيْبَ فِيهَا وَأَنَّ ࡰ۬للَّهَ يَبْعَثُ مَن فِے ࡴ۬لْقُبُورِ࣌', 'وأن ࡰلساعة ءاتية لا ريب فيها وأن ࡰلله يبعث من فے ࡴلقبور࣌', NULL, 333, 'local:warsh-text.json'),
  ('warsh-22-8', 'warsh', 22, 8, 'وَمِنَ ࡰ۬لنَّاسِ مَنْ يُّجَٰدِلُ فِے ࡴ۬للَّهِ بِغَيْرِ عِلْمࣲ وَلَا هُدىࣰ وَلَا كِتَٰبࣲ مُّنِيرࣲ', 'ومن ࡰلناس من يجدل فے ࡴلله بغير علم ولا هدى ولا كتب منير', NULL, 333, 'local:warsh-text.json'),
  ('warsh-22-9', 'warsh', 22, 9, 'ثَانِيَ عِطْفِهِۦ لِيُضِلَّ عَن سَبِيلِ ࡴ۬للَّهِ࣌ لَهُۥ فِے ࡴ۬لدُّنْيٜا خِزْيࣱ࣌ وَنُذِيقُهُۥ يَوْمَ ࡰ۬لْقِيَٰمَةِ عَذَابَ ࡰ۬لْحَرِيقِ࣌', 'ثاني عطفه ليضل عن سبيل ࡴلله࣌ له فے ࡴلدنيا خزي࣌ ونذيقه يوم ࡰلقيمة عذاب ࡰلحريق࣌', NULL, 333, 'local:warsh-text.json'),
  ('warsh-22-10', 'warsh', 22, 10, 'ذَٰلِكَ بِمَا قَدَّمَتْ يَدَٰكَ وَأَنَّ ࡰ۬للَّهَ لَيْسَ بِظَلَّٰمࣲ لِّلْعَبِيدِ࣌', 'ذلك بما قدمت يدك وأن ࡰلله ليس بظلم للعبيد࣌', NULL, 333, 'local:warsh-text.json'),
  ('warsh-22-11', 'warsh', 22, 11, '۞ وَمِنَ ࡰ۬لنَّاسِ مَنْ يَّعْبُدُ ࡲ۬للَّهَ عَلَىٰ حَرْفࣲ فَإِنَ ࡰصَابَهُۥ خَيْرٌ ࡴٜطْمَأَنَّ بِهِۦ وَإِنَ ࡰصَابَتْهُ فِتْنَةٌ ࡴٜنقَلَبَ عَلَىٰ وَجْهِهِۦ خَسِرَ ࡰ۬لدُّنْيٜا وَالَاخِرَةَ࣌ ذَٰلِكَ هُوَ ࡰ۬لْخُسْرَانُ ࡲ۬لْمُبِينُ࣌', 'ومن ࡰلناس من يعبد ࡲلله على حرف فإن ࡰصابه خير ࡴطمأن به وإن ࡰصابته فتنة ࡴنقلب على وجهه خسر ࡰلدنيا والاخرة࣌ ذلك هو ࡰلخسران ࡲلمبين࣌', NULL, 333, 'local:warsh-text.json'),
  ('warsh-22-12', 'warsh', 22, 12, 'يَدْعُواْ مِن دُونِ ࡴ۬للَّهِ مَا لَا يَضُرُّهُۥ وَمَا لَا يَنفَعُهُۥ࣌ ذَٰلِكَ هُوَ ࡰ۬لضَّلَٰلُ ࡲ۬لْبَعِيدُ', 'يدعوا من دون ࡴلله ما لا يضره وما لا ينفعه࣌ ذلك هو ࡰلضلل ࡲلبعيد', NULL, 333, 'local:warsh-text.json'),
  ('warsh-22-13', 'warsh', 22, 13, 'يَدْعُواْ࣌ لَمَن ضَرُّهُۥٓ أَقْرَبُ مِن نَّفْعِهِۦ لَبِيسَ ࡰ۬لْمَوْلٜىٰ وَلَبِيسَ ࡰ۬لْعَشِيرُ࣌', 'يدعوا࣌ لمن ضره أقرب من نفعه لبيس ࡰلمولى ولبيس ࡰلعشير࣌', NULL, 333, 'local:warsh-text.json'),
  ('warsh-22-14', 'warsh', 22, 14, 'إِنَّ ࡰ۬للَّهَ يُدْخِلُ ࡲ۬لذِينَ ءَامَنُواْ وَعَمِلُواْ ࡲ۬لصَّٰلِحَٰتِ جَنَّٰتࣲ تَجْرِے مِن تَحْتِهَا ࡰ۬لَانْهَٰرُ࣌ إِنَّ ࡰ۬للَّهَ يَفْعَلُ مَا يُرِيدُ࣌', 'إن ࡰلله يدخل ࡲلذين ءامنوا وعملوا ࡲلصلحت جنت تجرے من تحتها ࡰلانهر࣌ إن ࡰلله يفعل ما يريد࣌', NULL, 333, 'local:warsh-text.json'),
  ('warsh-22-15', 'warsh', 22, 15, 'مَن كَانَ يَظُنُّ أَن لَّنْ يَّنصُرَهُ ࡲ۬للَّهُ فِے ࡴ۬لدُّنْيٜا وَالَاخِرَةِ فَلْيَمْدُدْ بِسَبَبٍ ࡴلَى ࡰ۬لسَّمَآءِ ثُمَّ لِيَقْطَعْ فَلْيَنظُرْ هَلْ يُذْهِبَنَّ كَيْدُهُۥ مَا يَغِيظُ࣌', 'من كان يظن أن لن ينصره ࡲلله فے ࡴلدنيا والاخرة فليمدد بسبب ࡴلى ࡰلسماء ثم ليقطع فلينظر هل يذهبن كيده ما يغيظ࣌', NULL, 333, 'local:warsh-text.json'),
  ('warsh-22-16', 'warsh', 22, 16, 'وَكَذَٰلِكَ أَنزَلْنَٰهُ ءَايَٰتِۢ بَيِّنَٰتࣲ࣌ وَأَنَّ ࡰ۬للَّهَ يَهْدِے مَنْ يُّرِيدُ࣌', 'وكذلك أنزلنه ءايت بينت࣌ وأن ࡰلله يهدے من يريد࣌', NULL, 334, 'local:warsh-text.json'),
  ('warsh-22-17', 'warsh', 22, 17, 'إِنَّ ࡰ۬لذِينَ ءَامَنُواْ وَالذِينَ هَادُواْ وَالصَّٰبِينَ وَالنَّصَٰرٜىٰ وَالْمَجُوسَ وَالذِينَ أَشْرَكُوٓاْ إِنَّ ࡰ۬للَّهَ يَفْصِلُ بَيْنَهُمْ يَوْمَ ࡰ۬لْقِيَٰمَةِ࣌ إِنَّ ࡰ۬للَّهَ عَلَىٰ كُلِّ شَےْءࣲ شَهِيدٌ࣌', 'إن ࡰلذين ءامنوا والذين هادوا والصبين والنصرى والمجوس والذين أشركوا إن ࡰلله يفصل بينهم يوم ࡰلقيمة࣌ إن ࡰلله على كل شےء شهيد࣌', NULL, 334, 'local:warsh-text.json'),
  ('warsh-22-18', 'warsh', 22, 18, 'ࡰلَمْ تَرَ أَنَّ ࡰ۬للَّهَ يَسْجُدُ لَهُۥ مَن فِے ࡴ۬لسَّمَٰوَٰتِ وَمَن فِے ࡴ۬لَارْضِ وَالشَّمْسُ وَالْقَمَرُ وَالنُّجُومُ وَالْجِبَالُ وَالشَّجَرُ وَالدَّوَآبُّ وَكَثِيرࣱ مِّنَ ࡰ۬لنَّاسِ࣌ وَكَثِيرٌ حَقَّ عَلَيْهِ ࡴ۬لْعَذَابُ࣌ وَمَنْ يُّهِنِ ࡴ۬للَّهُ فَمَا لَهُۥ مِن مُّكْرِمٍ࣌ ࡴنَّ ࡰ۬للَّهَ يَفْعَلُ مَا يَشَآءُ࣌۩', 'ࡰلم تر أن ࡰلله يسجد له من فے ࡴلسموت ومن فے ࡴلارض والشمس والقمر والنجوم والجبال والشجر والدواب وكثير من ࡰلناس࣌ وكثير حق عليه ࡴلعذاب࣌ ومن يهن ࡴلله فما له من مكرم࣌ ࡴن ࡰلله يفعل ما يشاء࣌', NULL, 334, 'local:warsh-text.json'),
  ('warsh-22-19', 'warsh', 22, 19, '۞ هَٰذَٰنِ خَصْمَٰنِ ࡴٜخْتَصَمُواْ فِے رَبِّهِمْ࣌ فَالذِينَ كَفَرُواْ قُطِّعَتْ لَهُمْ ثِيَابࣱ مِّن نّٜارࣲ يُصَبُّ مِن فَوْقِ رُءُوسِهِمُ ࡲ۬لْحَمِيمُ يُصْهَرُ بِهِۦ مَا فِے بُطُونِهِمْ وَالْجُلُودُ࣌ وَلَهُم مَّقَٰمِعُ مِنْ حَدِيدࣲ࣌', 'هذن خصمن ࡴختصموا فے ربهم࣌ فالذين كفروا قطعت لهم ثياب من نار يصب من فوق رءوسهم ࡲلحميم يصهر به ما فے بطونهم والجلود࣌ ولهم مقمع من حديد࣌', NULL, 334, 'local:warsh-text.json'),
  ('warsh-22-20', 'warsh', 22, 20, 'كُلَّمَآ أَرَادُوٓاْ أَنْ يَّخْرُجُواْ مِنْهَا مِنْ غَمٍّ ࡳعِيدُواْ فِيهَا࣌ وَذُوقُواْ عَذَابَ ࡰ۬لْحَرِيقِ࣌', 'كلما أرادوا أن يخرجوا منها من غم ࡳعيدوا فيها࣌ وذوقوا عذاب ࡰلحريق࣌', NULL, 334, 'local:warsh-text.json'),
  ('warsh-22-21', 'warsh', 22, 21, 'إِنَّ ࡰ۬للَّهَ يُدْخِلُ ࡲ۬لذِينَ ءَامَنُواْ وَعَمِلُواْ ࡲ۬لصَّٰلِحَٰتِ جَنَّٰتࣲ تَجْرِے مِن تَحْتِهَا ࡰ۬لَانْهَٰرُ يُحَلَّوْنَ فِيهَا مِنَ ࡰسَاوِرَ مِن ذَهَبࣲ وَلُؤْلُؤاࣰ࣌ وَلِبَاسُهُمْ فِيهَا حَرِيرࣱ࣌', 'إن ࡰلله يدخل ࡲلذين ءامنوا وعملوا ࡲلصلحت جنت تجرے من تحتها ࡰلانهر يحلون فيها من ࡰساور من ذهب ولؤلؤا࣌ ولباسهم فيها حرير࣌', NULL, 334, 'local:warsh-text.json'),
  ('warsh-22-22', 'warsh', 22, 22, 'وَهُدُوٓاْ إِلَى ࡰ۬لطَّيِّبِ مِنَ ࡰ۬لْقَوْلِ࣌ وَهُدُوٓاْ إِلَىٰ صِرَٰطِ ࡴ۬لْحَمِيدِ࣌', 'وهدوا إلى ࡰلطيب من ࡰلقول࣌ وهدوا إلى صرط ࡴلحميد࣌', NULL, 335, 'local:warsh-text.json'),
  ('warsh-22-23', 'warsh', 22, 23, 'إِنَّ ࡰ۬لذِينَ كَفَرُواْ وَيَصُدُّونَ عَن سَبِيلِ ࡴ۬للَّهِ وَالْمَسْجِدِ ࡴ۬لْحَرَامِ ࡴ۬لذِے جَعَلْنَٰهُ لِلنَّاسِ سَوَآءٌ ࡴ۬لْعَٰكِفُ فِيهِ وَالْبَادِۦ࣌ وَمَنْ يُّرِدْ فِيهِ بِإِلْحَادِۢ بِظُلْمࣲ نُّذِقْهُ مِنْ عَذَابٍ ࡰلِيمࣲ࣌', 'إن ࡰلذين كفروا ويصدون عن سبيل ࡴلله والمسجد ࡴلحرام ࡴلذے جعلنه للناس سواء ࡴلعكف فيه والباد࣌ ومن يرد فيه بإلحاد بظلم نذقه من عذاب ࡰليم࣌', NULL, 335, 'local:warsh-text.json'),
  ('warsh-22-24', 'warsh', 22, 24, 'وَإِذْ بَوَّأْنَا لِإِبْرَٰهِيمَ مَكَانَ ࡰ۬لْبَيْتِ أَن لَّا تُشْرِكْ بِے شَيْـٔاࣰ࣌ وَطَهِّرْ بَيْتِيَ لِلطَّآئِفِينَ وَالْقَآئِمِينَ وَالرُّكَّعِ ࡴ۬لسُّجُودِ࣌', 'وإذ بوأنا لإبرهيم مكان ࡰلبيت أن لا تشرك بے شيا࣌ وطهر بيتي للطائفين والقائمين والركع ࡴلسجود࣌', NULL, 335, 'local:warsh-text.json'),
  ('warsh-22-25', 'warsh', 22, 25, 'وَأَذِّن فِے ࡴ۬لنَّاسِ بِالْحَجِّ يَاتُوكَ رِجَالاࣰ وَعَلَىٰ كُلِّ ضَامِرࣲ يَاتِينَ مِن كُلِّ فَجٍّ عَمِيقࣲ', 'وأذن فے ࡴلناس بالحج ياتوك رجالا وعلى كل ضامر ياتين من كل فج عميق', NULL, 335, 'local:warsh-text.json'),
  ('warsh-22-26', 'warsh', 22, 26, 'لِّيَشْهَدُواْ مَنَٰفِعَ لَهُمْ وَيَذْكُرُواْ ࡲٜسْمَ ࡰ۬للَّهِ فِےٓ أَيَّامࣲ مَّعْلُومَٰتٍ عَلَىٰ مَا رَزَقَهُم مِّنۢ بَهِيمَةِ ࡴ۬لَانْعَٰمِ࣌ فَكُلُواْ مِنْهَا وَأَطْعِمُواْ ࡲ۬لْبَآئِسَ ࡰ۬لْفَقِيرَ࣌', 'ليشهدوا منفع لهم ويذكروا ࡲسم ࡰلله فے أيام معلومت على ما رزقهم من بهيمة ࡴلانعم࣌ فكلوا منها وأطعموا ࡲلبائس ࡰلفقير࣌', NULL, 335, 'local:warsh-text.json'),
  ('warsh-22-27', 'warsh', 22, 27, 'ثُمَّ لِيَقْضُواْ تَفَثَهُمْ وَلْيُوفُواْ نُذُورَهُمْ وَلْيَطَّوَّفُواْ بِالْبَيْتِ ࡴ۬لْعَتِيقِ࣌', 'ثم ليقضوا تفثهم وليوفوا نذورهم وليطوفوا بالبيت ࡴلعتيق࣌', NULL, 335, 'local:warsh-text.json'),
  ('warsh-22-28', 'warsh', 22, 28, '۞ ذَٰلِكَ࣌ وَمَنْ يُّعَظِّمْ حُرُمَٰتِ ࡴ۬للَّهِ فَهُوَ خَيْرࣱ لَّهُۥ عِندَ رَبِّهِۦ࣌ وَأُحِلَّتْ لَكُمُ ࡲ۬لَانْعَٰمُ إِلَّا مَا يُتْلٜىٰ عَلَيْكُمْ࣌ فَاجْتَنِبُواْ ࡲ۬لرِّجْسَ مِنَ ࡰ۬لَاوْثَٰنِ وَاجْتَنِبُواْ قَوْلَ ࡰ۬لزُّورِ', 'ذلك࣌ ومن يعظم حرمت ࡴلله فهو خير له عند ربه࣌ وأحلت لكم ࡲلانعم إلا ما يتلى عليكم࣌ فاجتنبوا ࡲلرجس من ࡰلاوثن واجتنبوا قول ࡰلزور', NULL, 335, 'local:warsh-text.json'),
  ('warsh-22-29', 'warsh', 22, 29, 'حُنَفَآءَ لِلهِ غَيْرَ مُشْرِكِينَ بِهِۦ࣌ وَمَنْ يُّشْرِكْ بِاللَّهِ فَكَأَنَّمَا خَرَّ مِنَ ࡰ۬لسَّمَآءِ فَتَخَطَّفُهُ ࡲ۬لطَّيْرُ أَوْ تَهْوِے بِهِ ࡴ۬لرِّيحُ فِے مَكَانࣲ سَحِيقࣲ࣌', 'حنفاء لله غير مشركين به࣌ ومن يشرك بالله فكأنما خر من ࡰلسماء فتخطفه ࡲلطير أو تهوے به ࡴلريح فے مكان سحيق࣌', NULL, 336, 'local:warsh-text.json'),
  ('warsh-22-30', 'warsh', 22, 30, 'ذَٰلِكَ࣌ وَمَنْ يُّعَظِّمْ شَعَٰٓئِرَ ࡰ۬للَّهِ فَإِنَّهَا مِن تَقْوَى ࡰ۬لْقُلُوبِ࣌', 'ذلك࣌ ومن يعظم شعئر ࡰلله فإنها من تقوى ࡰلقلوب࣌', NULL, 336, 'local:warsh-text.json'),
  ('warsh-22-31', 'warsh', 22, 31, 'لَكُمْ فِيهَا مَنَٰفِعُ إِلَىٰٓ أَجَلࣲ مُّسَمّىࣰ ثُمَّ مَحِلُّهَآ إِلَى ࡰ۬لْبَيْتِ ࡴ۬لْعَتِيقِ࣌', 'لكم فيها منفع إلى أجل مسمى ثم محلها إلى ࡰلبيت ࡴلعتيق࣌', NULL, 336, 'local:warsh-text.json'),
  ('warsh-22-32', 'warsh', 22, 32, 'وَلِكُلِّ أُمَّةࣲ جَعَلْنَا مَنسَكاࣰ لِّيَذْكُرُواْ ࡲٜسْمَ ࡰ۬للَّهِ عَلَىٰ مَا رَزَقَهُم مِّنۢ بَهِيمَةِ ࡴ۬لَانْعَٰمِ࣌ فَإِلَٰهُكُمُۥٓ إِلَٰهࣱ وَٰحِدࣱ࣌ فَلَهُۥٓ أَسْلِمُواْ࣌ وَبَشِّرِ ࡴ۬لْمُخْبِتِينَ', 'ولكل أمة جعلنا منسكا ليذكروا ࡲسم ࡰلله على ما رزقهم من بهيمة ࡴلانعم࣌ فإلهكم إله وحد࣌ فله أسلموا࣌ وبشر ࡴلمخبتين', NULL, 336, 'local:warsh-text.json'),
  ('warsh-22-33', 'warsh', 22, 33, 'ࡰ۬لذِينَ إِذَا ذُكِرَ ࡰ۬للَّهُ وَجِلَتْ قُلُوبُهُمْ وَالصَّٰبِرِينَ عَلَىٰ مَآ أَصَابَهُمْ وَالْمُقِيمِے ࡴ۬لصَّلَوٰةِ وَمِمَّا رَزَقْنَٰهُمْ يُنفِقُونَ࣌', 'ࡰلذين إذا ذكر ࡰلله وجلت قلوبهم والصبرين على ما أصابهم والمقيمے ࡴلصلوة ومما رزقنهم ينفقون࣌', NULL, 336, 'local:warsh-text.json'),
  ('warsh-22-34', 'warsh', 22, 34, 'وَالْبُدْنَ جَعَلْنَٰهَا لَكُم مِّن شَعَٰٓئِرِ ࡴ۬للَّهِ لَكُمْ فِيهَا خَيْرࣱ࣌ فَاذْكُرُواْ ࡲٜسْمَ ࡰ۬للَّهِ عَلَيْهَا صَوَآفَّ࣌ فَإِذَا وَجَبَتْ جُنُوبُهَا فَكُلُواْ مِنْهَا وَأَطْعِمُواْ ࡲ۬لْقَانِعَ وَالْمُعْتَرَّ࣌ كَذَٰلِكَ سَخَّرْنَٰهَا لَكُمْ لَعَلَّكُمْ تَشْكُرُونَ࣌', 'والبدن جعلنها لكم من شعئر ࡴلله لكم فيها خير࣌ فاذكروا ࡲسم ࡰلله عليها صواف࣌ فإذا وجبت جنوبها فكلوا منها وأطعموا ࡲلقانع والمعتر࣌ كذلك سخرنها لكم لعلكم تشكرون࣌', NULL, 336, 'local:warsh-text.json'),
  ('warsh-22-35', 'warsh', 22, 35, 'لَنْ يَّنَالَ ࡰ۬للَّهَ لُحُومُهَا وَلَا دِمَآؤُهَا وَلَٰكِنْ يَّنَالُهُ ࡲ۬لتَّقْوٜىٰ مِنكُمْ࣌ كَذَٰلِكَ سَخَّرَهَا لَكُمْ لِتُكَبِّرُواْ ࡲ۬للَّهَ عَلَىٰ مَا هَدٜيٰكُمْ࣌ وَبَشِّرِ ࡴ۬لْمُحْسِنِينَ࣌', 'لن ينال ࡰلله لحومها ولا دماؤها ولكن يناله ࡲلتقوى منكم࣌ كذلك سخرها لكم لتكبروا ࡲلله على ما هديكم࣌ وبشر ࡴلمحسنين࣌', NULL, 336, 'local:warsh-text.json'),
  ('warsh-22-36', 'warsh', 22, 36, '۞ إِنَّ ࡰ۬للَّهَ يُدَٰفِعُ عَنِ ࡴ۬لذِينَ ءَامَنُوٓاْ࣌ إِنَّ ࡰ۬للَّهَ لَا يُحِبُّ كُلَّ خَوَّانࣲ كَفُورٍ࣌', 'إن ࡰلله يدفع عن ࡴلذين ءامنوا࣌ إن ࡰلله لا يحب كل خوان كفور࣌', NULL, 336, 'local:warsh-text.json'),
  ('warsh-22-37', 'warsh', 22, 37, 'ࡳذِنَ لِلذِينَ يُقَٰتَلُونَ بِأَنَّهُمْ ظُلِمُواْ࣌ وَإِنَّ ࡰ۬للَّهَ عَلَىٰ نَصْرِهِمْ لَقَدِيرٌ࣌', 'ࡳذن للذين يقتلون بأنهم ظلموا࣌ وإن ࡰلله على نصرهم لقدير࣌', NULL, 337, 'local:warsh-text.json'),
  ('warsh-22-38', 'warsh', 22, 38, 'ࡴ۬لذِينَ أُخْرِجُواْ مِن دِيٜـٰرِهِم بِغَيْرِ حَقٍّ ࡴلَّآ أَنْ يَّقُولُواْ رَبُّنَا ࡰ۬للَّهُ࣌ وَلَوْلَا دِفَٰعُ ࡲ۬للَّهِ ࡴ۬لنَّاسَ بَعْضَهُم بِبَعْضࣲ لَّهُدِمَتْ صَوَٰمِعُ وَبِيَعࣱ وَصَلَوَٰتࣱ وَمَسَٰجِدُ يُذْكَرُ فِيهَا ࡰٜسْمُ ࡲ۬للَّهِ كَثِيراࣰ࣌ وَلَيَنصُرَنَّ ࡰ۬للَّهُ مَنْ يَّنصُرُهُۥٓ࣌ إِنَّ ࡰ۬للَّهَ لَقَوِيٌّ عَزِيزٌ࣌', 'ࡴلذين أخرجوا من ديرهم بغير حق ࡴلا أن يقولوا ربنا ࡰلله࣌ ولولا دفع ࡲلله ࡴلناس بعضهم ببعض لهدمت صومع وبيع وصلوت ومسجد يذكر فيها ࡰسم ࡲلله كثيرا࣌ ولينصرن ࡰلله من ينصره࣌ إن ࡰلله لقوي عزيز࣌', NULL, 337, 'local:warsh-text.json'),
  ('warsh-22-39', 'warsh', 22, 39, 'ࡴ۬لذِينَ إِن مَّكَّنَّٰهُمْ فِے ࡴ۬لَارْضِ أَقَامُواْ ࡲ۬لصَّلَوٰةَ وَءَاتَوُاْ ࡲ۬لزَّكَوٰةَ وَأَمَرُواْ بِالْمَعْرُوفِ وَنَهَوْاْ عَنِ ࡴ۬لْمُنكَرِ࣌ وَلِلهِ عَٰقِبَةُ ࡲ۬لُامُورِ࣌', 'ࡴلذين إن مكنهم فے ࡴلارض أقاموا ࡲلصلوة وءاتوا ࡲلزكوة وأمروا بالمعروف ونهوا عن ࡴلمنكر࣌ ولله عقبة ࡲلامور࣌', NULL, 337, 'local:warsh-text.json'),
  ('warsh-22-40', 'warsh', 22, 40, 'وَإِنْ يُّكَذِّبُوكَ فَقَدْ كَذَّبَتْ قَبْلَهُمْ قَوْمُ نُوحࣲ وَعَادࣱ وَثَمُودُ', 'وإن يكذبوك فقد كذبت قبلهم قوم نوح وعاد وثمود', NULL, 337, 'local:warsh-text.json'),
  ('warsh-22-41', 'warsh', 22, 41, 'وَقَوْمُ إِبْرَٰهِيمَ وَقَوْمُ لُوطࣲ', 'وقوم إبرهيم وقوم لوط', NULL, 337, 'local:warsh-text.json'),
  ('warsh-22-42', 'warsh', 22, 42, 'وَأَصْحَٰبُ مَدْيَنَ࣌ وَكُذِّبَ مُوسٜىٰ࣌ فَأَمْلَيْتُ لِلْكٜـٰفِرِينَ ثُمَّ أَخَذتُّهُمْ࣌ فَكَيْفَ كَانَ نَكِيرِۦ࣌', 'وأصحب مدين࣌ وكذب موسى࣌ فأمليت للكفرين ثم أخذتهم࣌ فكيف كان نكير࣌', NULL, 337, 'local:warsh-text.json'),
  ('warsh-22-43', 'warsh', 22, 43, 'فَكَأَيِّن مِّن قَرْيَةٍ ࡰهْلَكْنَٰهَا وَهِيَ ظَالِمَةࣱ فَهِيَ خَاوِيَةٌ عَلَىٰ عُرُوشِهَا وَبِيرࣲ مُّعَطَّلَةࣲ وَقَصْرࣲ مَّشِيدٍ࣌', 'فكأين من قرية ࡰهلكنها وهي ظالمة فهي خاوية على عروشها وبير معطلة وقصر مشيد࣌', NULL, 337, 'local:warsh-text.json'),
  ('warsh-22-44', 'warsh', 22, 44, 'ࡰفَلَمْ يَسِيرُواْ فِے ࡴ۬لَارْضِ فَتَكُونَ لَهُمْ قُلُوبࣱ يَعْقِلُونَ بِهَآ أَوَ اٰذَانࣱ يَسْمَعُونَ بِهَا࣌ فَإِنَّهَا لَا تَعْمَى ࡰ۬لَابْصَٰرُ وَلَٰكِن تَعْمَى ࡰ۬لْقُلُوبُ ࡲ۬لتِے فِے ࡴ۬لصُّدُورِ࣌', 'ࡰفلم يسيروا فے ࡴلارض فتكون لهم قلوب يعقلون بها أو اذان يسمعون بها࣌ فإنها لا تعمى ࡰلابصر ولكن تعمى ࡰلقلوب ࡲلتے فے ࡴلصدور࣌', NULL, 337, 'local:warsh-text.json'),
  ('warsh-22-45', 'warsh', 22, 45, 'وَيَسْتَعْجِلُونَكَ بِالْعَذَابِ࣌ وَلَنْ يُّخْلِفَ ࡰ۬للَّهُ وَعْدَهُۥ࣌ وَإِنَّ يَوْماً عِندَ رَبِّكَ كَأَلْفِ سَنَةࣲ مِّمَّا تَعُدُّونَ࣌', 'ويستعجلونك بالعذاب࣌ ولن يخلف ࡰلله وعده࣌ وإن يوما عند ربك كألف سنة مما تعدون࣌', NULL, 338, 'local:warsh-text.json'),
  ('warsh-22-46', 'warsh', 22, 46, 'وَكَأَيِّن مِّن قَرْيَةٍ ࡰمْلَيْتُ لَهَا وَهِيَ ظَالِمَةࣱ ثُمَّ أَخَذتُّهَا࣌ وَإِلَيَّ ࡰ۬لْمَصِيرُ࣌', 'وكأين من قرية ࡰمليت لها وهي ظالمة ثم أخذتها࣌ وإلي ࡰلمصير࣌', NULL, 338, 'local:warsh-text.json'),
  ('warsh-22-47', 'warsh', 22, 47, '۞ قُلْ يَٰٓأَيُّهَا ࡰ۬لنَّاسُ إِنَّمَآ أَنَا لَكُمْ نَذِيرࣱ مُّبِينࣱ࣌', 'قل يأيها ࡰلناس إنما أنا لكم نذير مبين࣌', NULL, 338, 'local:warsh-text.json'),
  ('warsh-22-48', 'warsh', 22, 48, 'فَالذِينَ ءَامَنُواْ وَعَمِلُواْ ࡲ۬لصَّٰلِحَٰتِ لَهُم مَّغْفِرَةࣱ وَرِزْقࣱ كَرِيمࣱ࣌', 'فالذين ءامنوا وعملوا ࡲلصلحت لهم مغفرة ورزق كريم࣌', NULL, 338, 'local:warsh-text.json'),
  ('warsh-22-49', 'warsh', 22, 49, 'وَالذِينَ سَعَوْاْ فِےٓ ءَايَٰتِنَا مُعَٰجِزِينَ أُوْلَٰٓئِكَ أَصْحَٰبُ ࡲ۬لْجَحِيمِ࣌', 'والذين سعوا فے ءايتنا معجزين أولئك أصحب ࡲلجحيم࣌', NULL, 338, 'local:warsh-text.json'),
  ('warsh-22-50', 'warsh', 22, 50, 'وَمَآ أَرْسَلْنَا مِن قَبْلِكَ مِن رَّسُولࣲ وَلَا نَبِےٓءٍ ࡴلَّآ إِذَا تَمَنّٜىٰٓ أَلْقَى ࡰ۬لشَّيْطَٰنُ فِےٓ أُمْنِيَّتِهِۦ فَيَنسَخُ ࡲ۬للَّهُ مَا يُلْقِے ࡴ۬لشَّيْطَٰنُ ثُمَّ يُحْكِمُ ࡲ۬للَّهُ ءَايَٰتِهِۦ وَاللَّهُ عَلِيمٌ حَكِيمࣱ', 'وما أرسلنا من قبلك من رسول ولا نبےء ࡴلا إذا تمنى ألقى ࡰلشيطن فے أمنيته فينسخ ࡲلله ما يلقے ࡴلشيطن ثم يحكم ࡲلله ءايته والله عليم حكيم', NULL, 338, 'local:warsh-text.json'),
  ('warsh-22-51', 'warsh', 22, 51, 'لِّيَجْعَلَ مَا يُلْقِے ࡴ۬لشَّيْطَٰنُ فِتْنَةࣰ لِّلذِينَ فِے قُلُوبِهِم مَّرَضࣱ وَالْقَاسِيَةِ قُلُوبُهُمْ࣌ وَإِنَّ ࡰ۬لظَّٰلِمِينَ لَفِے شِقَاقِۢ بَعِيدࣲ࣌', 'ليجعل ما يلقے ࡴلشيطن فتنة للذين فے قلوبهم مرض والقاسية قلوبهم࣌ وإن ࡰلظلمين لفے شقاق بعيد࣌', NULL, 338, 'local:warsh-text.json'),
  ('warsh-22-52', 'warsh', 22, 52, 'وَلِيَعْلَمَ ࡰ۬لذِينَ أُوتُواْ ࡲ۬لْعِلْمَ أَنَّهُ ࡲ۬لْحَقُّ مِن رَّبِّكَ فَيُومِنُواْ بِهِۦ فَتُخْبِتَ لَهُۥ قُلُوبُهُمْ࣌ وَإِنَّ ࡰ۬للَّهَ لَهَادِ ࡴ۬لذِينَ ءَامَنُوٓاْ إِلَىٰ صِرَٰطࣲ مُّسْتَقِيمࣲ࣌', 'وليعلم ࡰلذين أوتوا ࡲلعلم أنه ࡲلحق من ربك فيومنوا به فتخبت له قلوبهم࣌ وإن ࡰلله لهاد ࡴلذين ءامنوا إلى صرط مستقيم࣌', NULL, 338, 'local:warsh-text.json'),
  ('warsh-22-53', 'warsh', 22, 53, 'وَلَا يَزَالُ ࡲ۬لذِينَ كَفَرُواْ فِے مِرْيَةࣲ مِّنْهُ حَتَّىٰ تَاتِيَهُمُ ࡲ۬لسَّاعَةُ بَغْتَةً ࡰوْ يَاتِيَهُمْ عَذَابُ يَوْمٍ عَقِيمٍ࣌', 'ولا يزال ࡲلذين كفروا فے مرية منه حتى تاتيهم ࡲلساعة بغتة ࡰو ياتيهم عذاب يوم عقيم࣌', NULL, 338, 'local:warsh-text.json'),
  ('warsh-22-54', 'warsh', 22, 54, 'ࡴ۬لْمُلْكُ يَوْمَئِذࣲ لِّلهِ࣌ يَحْكُمُ بَيْنَهُمْ࣌ فَالذِينَ ءَامَنُواْ وَعَمِلُواْ ࡲ۬لصَّٰلِحَٰتِ فِے جَنَّٰتِ ࡴ۬لنَّعِيمِ࣌', 'ࡴلملك يومئذ لله࣌ يحكم بينهم࣌ فالذين ءامنوا وعملوا ࡲلصلحت فے جنت ࡴلنعيم࣌', NULL, 339, 'local:warsh-text.json'),
  ('warsh-22-55', 'warsh', 22, 55, 'وَالذِينَ كَفَرُواْ وَكَذَّبُواْ بِـَٔايَٰتِنَا فَأُوْلَٰٓئِكَ لَهُمْ عَذَابࣱ مُّهِينࣱ࣌', 'والذين كفروا وكذبوا بايتنا فأولئك لهم عذاب مهين࣌', NULL, 339, 'local:warsh-text.json'),
  ('warsh-22-56', 'warsh', 22, 56, 'وَالذِينَ هَاجَرُواْ فِے سَبِيلِ ࡴ۬للَّهِ ثُمَّ قُتِلُوٓاْ أَوْ مَاتُواْ لَيَرْزُقَنَّهُمُ ࡲ۬للَّهُ رِزْقاً حَسَناࣰ࣌ وَإِنَّ ࡰ۬للَّهَ لَهُوَ خَيْرُ ࡲ۬لرَّٰزِقِينَ࣌', 'والذين هاجروا فے سبيل ࡴلله ثم قتلوا أو ماتوا ليرزقنهم ࡲلله رزقا حسنا࣌ وإن ࡰلله لهو خير ࡲلرزقين࣌', NULL, 339, 'local:warsh-text.json'),
  ('warsh-22-57', 'warsh', 22, 57, 'لَيُدْخِلَنَّهُم مَّدْخَلاࣰ يَرْضَوْنَهُۥ࣌ وَإِنَّ ࡰ۬للَّهَ لَعَلِيمٌ حَلِيمࣱ࣌', 'ليدخلنهم مدخلا يرضونه࣌ وإن ࡰلله لعليم حليم࣌', NULL, 339, 'local:warsh-text.json'),
  ('warsh-22-58', 'warsh', 22, 58, '۞ ذَٰلِكَ࣌ وَمَنْ عَاقَبَ بِمِثْلِ مَا عُوقِبَ بِهِۦ ثُمَّ بُغِيَ عَلَيْهِ لَيَنصُرَنَّهُ ࡲ۬للَّهُ࣌ إِنَّ ࡰ۬للَّهَ لَعَفُوٌّ غَفُورࣱ࣌', 'ذلك࣌ ومن عاقب بمثل ما عوقب به ثم بغي عليه لينصرنه ࡲلله࣌ إن ࡰلله لعفو غفور࣌', NULL, 339, 'local:warsh-text.json'),
  ('warsh-22-59', 'warsh', 22, 59, 'ذَٰلِكَ بِأَنَّ ࡰ۬للَّهَ يُولِجُ ࡲ۬ليْلَ فِے ࡴ۬لنَّهٜارِ وَيُولِجُ ࡲ۬لنَّهَارَ فِے ࡴ۬ليْلِ وَأَنَّ ࡰ۬للَّهَ سَمِيعُۢ بَصِيرࣱ࣌', 'ذلك بأن ࡰلله يولج ࡲليل فے ࡴلنهار ويولج ࡲلنهار فے ࡴليل وأن ࡰلله سميع بصير࣌', NULL, 339, 'local:warsh-text.json'),
  ('warsh-22-60', 'warsh', 22, 60, 'ذَٰلِكَ بِأَنَّ ࡰ۬للَّهَ هُوَ ࡰ۬لْحَقُّ وَأَنَّ مَا تَدْعُونَ مِن دُونِهِۦ هُوَ ࡰ۬لْبَٰطِلُ وَأَنَّ ࡰ۬للَّهَ هُوَ ࡰ۬لْعَلِيُّ ࡲ۬لْكَبِيرُ࣌', 'ذلك بأن ࡰلله هو ࡰلحق وأن ما تدعون من دونه هو ࡰلبطل وأن ࡰلله هو ࡰلعلي ࡲلكبير࣌', NULL, 339, 'local:warsh-text.json'),
  ('warsh-22-61', 'warsh', 22, 61, 'أَلَمْ تَرَ أَنَّ ࡰ۬للَّهَ أَنزَلَ مِنَ ࡰ۬لسَّمَآءِ مَآءࣰ فَتُصْبِحُ ࡲ۬لَارْضُ مُخْضَرَّةً࣌ ࡴنَّ ࡰ۬للَّهَ لَطِيفٌ خَبِيرࣱ࣌', 'ألم تر أن ࡰلله أنزل من ࡰلسماء ماء فتصبح ࡲلارض مخضرة࣌ ࡴن ࡰلله لطيف خبير࣌', NULL, 339, 'local:warsh-text.json'),
  ('warsh-22-62', 'warsh', 22, 62, 'لَّهُۥ مَا فِے ࡴ۬لسَّمَٰوَٰتِ وَمَا فِے ࡴ۬لَارْضِ࣌ وَإِنَّ ࡰ۬للَّهَ لَهُوَ ࡰ۬لْغَنِيُّ ࡲ۬لْحَمِيدُ࣌', 'له ما فے ࡴلسموت وما فے ࡴلارض࣌ وإن ࡰلله لهو ࡰلغني ࡲلحميد࣌', NULL, 339, 'local:warsh-text.json'),
  ('warsh-22-63', 'warsh', 22, 63, 'أَلَمْ تَرَ أَنَّ ࡰ۬للَّهَ سَخَّرَ لَكُم مَّا فِے ࡴ۬لَارْضِ وَالْفُلْكَ تَجْرِے فِے ࡴ۬لْبَحْرِ بِأَمْرِهِۦ࣌ وَيُمْسِكُ ࡲ۬لسَّمَآءَ ان تَقَعَ عَلَى ࡰ۬لَارْضِ إِلَّا بِإِذْنِهِۦٓ࣌ إِنَّ ࡰ۬للَّهَ بِالنَّاسِ لَرَءُوفࣱ رَّحِيمࣱ࣌', 'ألم تر أن ࡰلله سخر لكم ما فے ࡴلارض والفلك تجرے فے ࡴلبحر بأمره࣌ ويمسك ࡲلسماء ان تقع على ࡰلارض إلا بإذنه࣌ إن ࡰلله بالناس لرءوف رحيم࣌', NULL, 340, 'local:warsh-text.json'),
  ('warsh-22-64', 'warsh', 22, 64, 'وَهُوَ ࡰ۬لذِےٓ أَحْيٜاكُمْ ثُمَّ يُمِيتُكُمْ࣌ ثُمَّ يُحْيِيكُمُۥٓ࣌ إِنَّ ࡰ۬لِانسَٰنَ لَكَفُورࣱ࣌', 'وهو ࡰلذے أحياكم ثم يميتكم࣌ ثم يحييكم࣌ إن ࡰلانسن لكفور࣌', NULL, 340, 'local:warsh-text.json'),
  ('warsh-22-65', 'warsh', 22, 65, 'لِّكُلِّ أُمَّةࣲ جَعَلْنَا مَنسَكاً هُمْ نَاسِكُوهُ࣌ فَلَا يُنَٰزِعُنَّكَ فِے ࡴ۬لَامْرِ࣌ وَادْعُ إِلَىٰ رَبِّكَ࣌ إِنَّكَ لَعَلَىٰ هُدىࣰ مُّسْتَقِيمࣲ࣌', 'لكل أمة جعلنا منسكا هم ناسكوه࣌ فلا ينزعنك فے ࡴلامر࣌ وادع إلى ربك࣌ إنك لعلى هدى مستقيم࣌', NULL, 340, 'local:warsh-text.json'),
  ('warsh-22-66', 'warsh', 22, 66, 'وَإِن جَٰدَلُوكَ فَقُلِ ࡴ۬للَّهُ أَعْلَمُ بِمَا تَعْمَلُونَ࣌', 'وإن جدلوك فقل ࡴلله أعلم بما تعملون࣌', NULL, 340, 'local:warsh-text.json'),
  ('warsh-22-67', 'warsh', 22, 67, 'ࡰ۬للَّهُ يَحْكُمُ بَيْنَكُمْ يَوْمَ ࡰ۬لْقِيَٰمَةِ فِيمَا كُنتُمْ فِيهِ تَخْتَلِفُونَ࣌', 'ࡰلله يحكم بينكم يوم ࡰلقيمة فيما كنتم فيه تختلفون࣌', NULL, 340, 'local:warsh-text.json'),
  ('warsh-22-68', 'warsh', 22, 68, 'أَلَمْ تَعْلَمَ ࡰنَّ ࡰ۬للَّهَ يَعْلَمُ مَا فِے ࡴ۬لسَّمَآءِ وَالَارْضِ࣌ إِنَّ ذَٰلِكَ فِے كِتَٰبٍ࣌ ࡴنَّ ذَٰلِكَ عَلَى ࡰ۬للَّهِ يَسِيرࣱ࣌', 'ألم تعلم ࡰن ࡰلله يعلم ما فے ࡴلسماء والارض࣌ إن ذلك فے كتب࣌ ࡴن ذلك على ࡰلله يسير࣌', NULL, 340, 'local:warsh-text.json'),
  ('warsh-22-69', 'warsh', 22, 69, 'وَيَعْبُدُونَ مِن دُونِ ࡴ۬للَّهِ مَا لَمْ يُنَزِّلْ بِهِۦ سُلْطَٰناࣰ وَمَا لَيْسَ لَهُم بِهِۦ عِلْمࣱ࣌ وَمَا لِلظَّٰلِمِينَ مِن نَّصِيرࣲ࣌', 'ويعبدون من دون ࡴلله ما لم ينزل به سلطنا وما ليس لهم به علم࣌ وما للظلمين من نصير࣌', NULL, 340, 'local:warsh-text.json'),
  ('warsh-22-70', 'warsh', 22, 70, '۞ وَإِذَا تُتْلٜىٰ عَلَيْهِمُۥٓ ءَايَٰتُنَا بَيِّنَٰتࣲ تَعْرِفُ فِے وُجُوهِ ࡴ۬لذِينَ كَفَرُواْ ࡲ۬لْمُنكَرَ يَكَادُونَ يَسْطُونَ بِالذِينَ يَتْلُونَ عَلَيْهِمُۥٓ ءَايَٰتِنَا࣌ قُلَ ࡰفَأُنَبِّئُكُم بِشَرࣲّ مِّن ذَٰلِكُمُ࣌ ࡲ۬لنَّارُ وَعَدَهَا ࡰ۬للَّهُ ࡲ۬لذِينَ كَفَرُواْ࣌ وَبِيسَ ࡰ۬لْمَصِيرُ࣌', 'وإذا تتلى عليهم ءايتنا بينت تعرف فے وجوه ࡴلذين كفروا ࡲلمنكر يكادون يسطون بالذين يتلون عليهم ءايتنا࣌ قل ࡰفأنبئكم بشر من ذلكم࣌ ࡲلنار وعدها ࡰلله ࡲلذين كفروا࣌ وبيس ࡰلمصير࣌', NULL, 340, 'local:warsh-text.json'),
  ('warsh-22-71', 'warsh', 22, 71, 'يَٰٓأَيُّهَا ࡰ۬لنَّاسُ ضُرِبَ مَثَلࣱ فَاسْتَمِعُواْ لَهُۥٓ࣌ إِنَّ ࡰ۬لذِينَ تَدْعُونَ مِن دُونِ ࡴ۬للَّهِ لَنْ يَّخْلُقُواْ ذُبَاباࣰ وَلَوِ ࡴٜجْتَمَعُواْ لَهُۥ࣌ وَإِنْ يَّسْلُبْهُمُ ࡲ۬لذُّبَابُ شَيْـٔاࣰ لَّا يَسْتَنقِذُوهُ مِنْهُ࣌ ضَعُفَ ࡰ۬لطَّالِبُ وَالْمَطْلُوبُ࣌', 'يأيها ࡰلناس ضرب مثل فاستمعوا له࣌ إن ࡰلذين تدعون من دون ࡴلله لن يخلقوا ذبابا ولو ࡴجتمعوا له࣌ وإن يسلبهم ࡲلذباب شيا لا يستنقذوه منه࣌ ضعف ࡰلطالب والمطلوب࣌', NULL, 341, 'local:warsh-text.json'),
  ('warsh-22-72', 'warsh', 22, 72, 'مَا قَدَرُواْ ࡲ۬للَّهَ حَقَّ قَدْرِهِۦٓ࣌ إِنَّ ࡰ۬للَّهَ لَقَوِيٌّ عَزِيزٌ࣌', 'ما قدروا ࡲلله حق قدره࣌ إن ࡰلله لقوي عزيز࣌', NULL, 341, 'local:warsh-text.json'),
  ('warsh-22-73', 'warsh', 22, 73, 'ࡴ۬للَّهُ يَصْطَفِے مِنَ ࡰ۬لْمَلَٰٓئِكَةِ رُسُلاࣰ وَمِنَ ࡰ۬لنَّاسِ࣌ إِنَّ ࡰ۬للَّهَ سَمِيعُۢ بَصِيرࣱ࣌', 'ࡴلله يصطفے من ࡰلملئكة رسلا ومن ࡰلناس࣌ إن ࡰلله سميع بصير࣌', NULL, 341, 'local:warsh-text.json'),
  ('warsh-22-74', 'warsh', 22, 74, 'يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ࣌ وَإِلَى ࡰ۬للَّهِ تُرْجَعُ ࡲ۬لُامُورُ࣌', 'يعلم ما بين أيديهم وما خلفهم࣌ وإلى ࡰلله ترجع ࡲلامور࣌', NULL, 341, 'local:warsh-text.json'),
  ('warsh-22-75', 'warsh', 22, 75, 'يَٰٓأَيُّهَا ࡰ۬لذِينَ ءَامَنُواْ ࡲٜرْكَعُواْ وَاسْجُدُواْ وَاعْبُدُواْ رَبَّكُمْ وَافْعَلُواْ ࡲ۬لْخَيْرَ لَعَلَّكُمْ تُفْلِحُونَ࣌', 'يأيها ࡰلذين ءامنوا ࡲركعوا واسجدوا واعبدوا ربكم وافعلوا ࡲلخير لعلكم تفلحون࣌', NULL, 341, 'local:warsh-text.json'),
  ('warsh-22-76', 'warsh', 22, 76, 'وَجَٰهِدُواْ فِے ࡴ۬للَّهِ حَقَّ جِهَادِهِۦ࣌ هُوَ ࡰٜجْتَبٜيٰكُمْ࣌ وَمَا جَعَلَ عَلَيْكُمْ فِے ࡴ۬لدِّينِ مِنْ حَرَجࣲ࣌ مِّلَّةَ أَبِيكُمُۥٓ إِبْرَٰهِيمَ࣌ هُوَ سَمّٜيٰكُمُ ࡲ۬لْمُسْلِمِينَ مِن قَبْلُ وَفِے هَٰذَا لِيَكُونَ ࡰ۬لرَّسُولُ شَهِيداً عَلَيْكُمْ وَتَكُونُواْ شُهَدَآءَ عَلَى ࡰ۬لنَّاسِ࣌ فَأَقِيمُواْ ࡲ۬لصَّلَوٰةَ وَءَاتُواْ ࡲ۬لزَّكَوٰةَ࣌ وَاعْتَصِمُواْ بِاللَّهِ࣌ هُوَ مَوْلٜيٰكُمْ࣌ فَنِعْمَ ࡰ۬لْمَوْلٜىٰ࣌ وَنِعْمَ ࡰ۬لنَّصِيرُ࣌', 'وجهدوا فے ࡴلله حق جهاده࣌ هو ࡰجتبيكم࣌ وما جعل عليكم فے ࡴلدين من حرج࣌ ملة أبيكم إبرهيم࣌ هو سميكم ࡲلمسلمين من قبل وفے هذا ليكون ࡰلرسول شهيدا عليكم وتكونوا شهداء على ࡰلناس࣌ فأقيموا ࡲلصلوة وءاتوا ࡲلزكوة࣌ واعتصموا بالله࣌ هو موليكم࣌ فنعم ࡰلمولى࣌ ونعم ࡰلنصير࣌', NULL, 341, 'local:warsh-text.json'),
  ('warsh-23-1', 'warsh', 23, 1, 'قَدَ ࡰفْلَحَ ࡰ۬لْمُومِنُونَ࣌', 'قد ࡰفلح ࡰلمومنون࣌', NULL, 342, 'local:warsh-text.json'),
  ('warsh-23-2', 'warsh', 23, 2, 'ࡰ۬لذِينَ هُمْ فِے صَلَاتِهِمْ خَٰشِعُونَ࣌', 'ࡰلذين هم فے صلاتهم خشعون࣌', NULL, 342, 'local:warsh-text.json'),
  ('warsh-23-3', 'warsh', 23, 3, 'وَالذِينَ هُمْ عَنِ ࡴ۬للَّغْوِ مُعْرِضُونَ࣌', 'والذين هم عن ࡴللغو معرضون࣌', NULL, 342, 'local:warsh-text.json'),
  ('warsh-23-4', 'warsh', 23, 4, 'وَالذِينَ هُمْ لِلزَّكَوٰةِ فَٰعِلُونَ࣌', 'والذين هم للزكوة فعلون࣌', NULL, 342, 'local:warsh-text.json'),
  ('warsh-23-5', 'warsh', 23, 5, 'وَالذِينَ هُمْ لِفُرُوجِهِمْ حَٰفِظُونَ', 'والذين هم لفروجهم حفظون', NULL, 342, 'local:warsh-text.json'),
  ('warsh-23-6', 'warsh', 23, 6, 'إِلَّا عَلَىٰٓ أَزْوَٰجِهِمُۥٓ أَوْ مَا مَلَكَتَ ࡰيْمَٰنُهُمْ فَإِنَّهُمْ غَيْرُ مَلُومِينَ࣌', 'إلا على أزوجهم أو ما ملكت ࡰيمنهم فإنهم غير ملومين࣌', NULL, 342, 'local:warsh-text.json'),
  ('warsh-23-7', 'warsh', 23, 7, 'فَمَنِ ࡴٜبْتَغٜىٰ وَرَآءَ ذَٰلِكَ فَأُوْلَٰٓئِكَ هُمُ ࡲ۬لْعَادُونَ࣌', 'فمن ࡴبتغى وراء ذلك فأولئك هم ࡲلعادون࣌', NULL, 342, 'local:warsh-text.json'),
  ('warsh-23-8', 'warsh', 23, 8, 'وَالذِينَ هُمْ لِأَمَٰنَٰتِهِمْ وَعَهْدِهِمْ رَٰعُونَ࣌', 'والذين هم لأمنتهم وعهدهم رعون࣌', NULL, 342, 'local:warsh-text.json'),
  ('warsh-23-9', 'warsh', 23, 9, 'وَالذِينَ هُمْ عَلَىٰ صَلَوَٰتِهِمْ يُحَافِظُونَ', 'والذين هم على صلوتهم يحافظون', NULL, 342, 'local:warsh-text.json'),
  ('warsh-23-10', 'warsh', 23, 10, 'أُوْلَٰٓئِكَ هُمُ ࡲ۬لْوَٰرِثُونَ', 'أولئك هم ࡲلورثون', NULL, 342, 'local:warsh-text.json'),
  ('warsh-23-11', 'warsh', 23, 11, 'ࡰ۬لذِينَ يَرِثُونَ ࡰ۬لْفِرْدَوْسَ࣌ هُمْ فِيهَا خَٰلِدُونَ࣌', 'ࡰلذين يرثون ࡰلفردوس࣌ هم فيها خلدون࣌', NULL, 342, 'local:warsh-text.json'),
  ('warsh-23-12', 'warsh', 23, 12, 'وَلَقَدْ خَلَقْنَا ࡰ۬لِانسَٰنَ مِن سُلَٰلَةࣲ مِّن طِينࣲ࣌', 'ولقد خلقنا ࡰلانسن من سللة من طين࣌', NULL, 342, 'local:warsh-text.json'),
  ('warsh-23-13', 'warsh', 23, 13, 'ثُمَّ جَعَلْنَٰهُ نُطْفَةࣰ فِے قَرٜارࣲ مَّكِينࣲ࣌', 'ثم جعلنه نطفة فے قرار مكين࣌', NULL, 342, 'local:warsh-text.json'),
  ('warsh-23-14', 'warsh', 23, 14, 'ثُمَّ خَلَقْنَا ࡰ۬لنُّطْفَةَ عَلَقَةࣰ فَخَلَقْنَا ࡰ۬لْعَلَقَةَ مُضْغَةࣰ فَخَلَقْنَا ࡰ۬لْمُضْغَةَ عِظَٰماࣰ فَكَسَوْنَا ࡰ۬لْعِظَٰمَ لَحْماࣰ ثُمَّ أَنشَأْنَٰهُ خَلْقاً اٰخَرَ࣌ فَتَبَٰرَكَ ࡰ۬للَّهُ أَحْسَنُ ࡲ۬لْخَٰلِقِينَ࣌', 'ثم خلقنا ࡰلنطفة علقة فخلقنا ࡰلعلقة مضغة فخلقنا ࡰلمضغة عظما فكسونا ࡰلعظم لحما ثم أنشأنه خلقا اخر࣌ فتبرك ࡰلله أحسن ࡲلخلقين࣌', NULL, 342, 'local:warsh-text.json'),
  ('warsh-23-15', 'warsh', 23, 15, 'ثُمَّ إِنَّكُم بَعْدَ ذَٰلِكَ لَمَيِّتُونَ࣌', 'ثم إنكم بعد ذلك لميتون࣌', NULL, 342, 'local:warsh-text.json'),
  ('warsh-23-16', 'warsh', 23, 16, 'ثُمَّ إِنَّكُمْ يَوْمَ ࡰ۬لْقِيَٰمَةِ تُبْعَثُونَ࣌', 'ثم إنكم يوم ࡰلقيمة تبعثون࣌', NULL, 342, 'local:warsh-text.json'),
  ('warsh-23-17', 'warsh', 23, 17, 'وَلَقَدْ خَلَقْنَا فَوْقَكُمْ سَبْعَ طَرَآئِقَ࣌ وَمَا كُنَّا عَنِ ࡴ۬لْخَلْقِ غَٰفِلِينَ࣌', 'ولقد خلقنا فوقكم سبع طرائق࣌ وما كنا عن ࡴلخلق غفلين࣌', NULL, 342, 'local:warsh-text.json'),
  ('warsh-23-18', 'warsh', 23, 18, 'وَأَنزَلْنَا مِنَ ࡰ۬لسَّمَآءِ مَآءَۢ بِقَدَرࣲ فَأَسْكَنَّٰهُ فِے ࡴ۬لَارْضِ࣌ وَإِنَّا عَلَىٰ ذَهَابِۢ بِهِۦ لَقَٰدِرُونَ࣌', 'وأنزلنا من ࡰلسماء ماء بقدر فأسكنه فے ࡴلارض࣌ وإنا على ذهاب به لقدرون࣌', NULL, 343, 'local:warsh-text.json'),
  ('warsh-23-19', 'warsh', 23, 19, 'فَأَنشَأْنَا لَكُم بِهِۦ جَنَّٰتࣲ مِّن نَّخِيلࣲ وَأَعْنَٰبࣲ لَّكُمْ فِيهَا فَوَٰكِهُ كَثِيرَةࣱ وَمِنْهَا تَاكُلُونَ', 'فأنشأنا لكم به جنت من نخيل وأعنب لكم فيها فوكه كثيرة ومنها تاكلون', NULL, 343, 'local:warsh-text.json'),
  ('warsh-23-20', 'warsh', 23, 20, 'وَشَجَرَةࣰ تَخْرُجُ مِن طُورِ سِينَآءَ تَنۢبُتُ بِالدُّهْنِ وَصِبْغࣲ لِّلَاكِلِينَ࣌', 'وشجرة تخرج من طور سيناء تنبت بالدهن وصبغ للاكلين࣌', NULL, 343, 'local:warsh-text.json'),
  ('warsh-23-21', 'warsh', 23, 21, 'وَإِنَّ لَكُمْ فِے ࡴ۬لَانْعَٰمِ لَعِبْرَةࣰ࣌ نَّسْقِيكُم مِّمَّا فِے بُطُونِهَا࣌ وَلَكُمْ فِيهَا مَنَٰفِعُ كَثِيرَةࣱ وَمِنْهَا تَاكُلُونَ', 'وإن لكم فے ࡴلانعم لعبرة࣌ نسقيكم مما فے بطونها࣌ ولكم فيها منفع كثيرة ومنها تاكلون', NULL, 343, 'local:warsh-text.json'),
  ('warsh-23-22', 'warsh', 23, 22, 'وَعَلَيْهَا وَعَلَى ࡰ۬لْفُلْكِ تُحْمَلُونَ࣌', 'وعليها وعلى ࡰلفلك تحملون࣌', NULL, 343, 'local:warsh-text.json'),
  ('warsh-23-23', 'warsh', 23, 23, 'وَلَقَدَ ࡰرْسَلْنَا نُوحاً ࡴلَىٰ قَوْمِهِۦ فَقَالَ يَٰقَوْمِ ࡴ࢈عْبُدُواْ ࡲ۬للَّهَ مَا لَكُم مِّنِ ࡴلَٰهٍ غَيْرُهُۥٓ࣌ أَفَلَا تَتَّقُونَ࣌', 'ولقد ࡰرسلنا نوحا ࡴلى قومه فقال يقوم ࡴ࢈عبدوا ࡲلله ما لكم من ࡴله غيره࣌ أفلا تتقون࣌', NULL, 343, 'local:warsh-text.json'),
  ('warsh-23-24', 'warsh', 23, 24, '۞ فَقَالَ ࡰ۬لْمَلَؤُاْ ࡲ۬لذِينَ كَفَرُواْ مِن قَوْمِهِۦ مَا هَٰذَآ إِلَّا بَشَرࣱ مِّثْلُكُمْ يُرِيدُ أَنْ يَّتَفَضَّلَ عَلَيْكُمْ وَلَوْ شَآءَ ࡰ۬للَّهُ لَأَنزَلَ مَلَٰٓئِكَةࣰ مَّا سَمِعْنَا بِهَٰذَا فِےٓ ءَابَآئِنَا ࡰ۬لَاوَّلِينَ', 'فقال ࡰلملؤا ࡲلذين كفروا من قومه ما هذا إلا بشر مثلكم يريد أن يتفضل عليكم ولو شاء ࡰلله لأنزل ملئكة ما سمعنا بهذا فے ءابائنا ࡰلاولين', NULL, 343, 'local:warsh-text.json'),
  ('warsh-23-25', 'warsh', 23, 25, 'إِنْ هُوَ إِلَّا رَجُلُۢ بِهِۦ جِنَّةࣱ فَتَرَبَّصُواْ بِهِۦ حَتَّىٰ حِينࣲ࣌', 'إن هو إلا رجل به جنة فتربصوا به حتى حين࣌', NULL, 343, 'local:warsh-text.json'),
  ('warsh-23-26', 'warsh', 23, 26, 'قَالَ رَبِّ ࡴ࢈نصُرْنِے بِمَا كَذَّبُونِ࣌', 'قال رب ࡴ࢈نصرنے بما كذبون࣌', NULL, 343, 'local:warsh-text.json'),
  ('warsh-23-27', 'warsh', 23, 27, 'فَأَوْحَيْنَآ إِلَيْهِ أَنِ ࡴٜصْنَعِ ࡴ۬لْفُلْكَ بِأَعْيُنِنَا وَوَحْيِنَا࣌ فَإِذَا جَآءَ امْرُنَا وَفَارَ ࡰ۬لتَّنُّورُ فَاسْلُكْ فِيهَا مِن كُلِّ زَوْجَيْنِ ࡴٜثْنَيْنِ وَأَهْلَكَ إِلَّا مَن سَبَقَ عَلَيْهِ ࡴ۬لْقَوْلُ مِنْهُمْ࣌ وَلَا تُخَٰطِبْنِے فِے ࡴ۬لذِينَ ظَلَمُوٓاْ إِنَّهُم مُّغْرَقُونَ࣌', 'فأوحينا إليه أن ࡴصنع ࡴلفلك بأعيننا ووحينا࣌ فإذا جاء امرنا وفار ࡰلتنور فاسلك فيها من كل زوجين ࡴثنين وأهلك إلا من سبق عليه ࡴلقول منهم࣌ ولا تخطبنے فے ࡴلذين ظلموا إنهم مغرقون࣌', NULL, 343, 'local:warsh-text.json'),
  ('warsh-23-28', 'warsh', 23, 28, 'فَإِذَا ࡰٜسْتَوَيْتَ أَنتَ وَمَن مَّعَكَ عَلَى ࡰ۬لْفُلْكِ فَقُلِ ࡴ۬لْحَمْدُ لِلهِ ࡴ۬لذِے نَجّٜيٰنَا مِنَ ࡰ۬لْقَوْمِ ࡴ۬لظَّٰلِمِينَ࣌', 'فإذا ࡰستويت أنت ومن معك على ࡰلفلك فقل ࡴلحمد لله ࡴلذے نجينا من ࡰلقوم ࡴلظلمين࣌', NULL, 344, 'local:warsh-text.json'),
  ('warsh-23-29', 'warsh', 23, 29, 'وَقُل رَّبِّ أَنزِلْنِے مُنزَلاࣰ مُّبَٰرَكاࣰ وَأَنتَ خَيْرُ ࡲ۬لْمُنزِلِينَ࣌', 'وقل رب أنزلنے منزلا مبركا وأنت خير ࡲلمنزلين࣌', NULL, 344, 'local:warsh-text.json'),
  ('warsh-23-30', 'warsh', 23, 30, 'إِنَّ فِے ذَٰلِكَ لَأٓيَٰتࣲ࣌ وَإِن كُنَّا لَمُبْتَلِينَ࣌', 'إن فے ذلك لأيت࣌ وإن كنا لمبتلين࣌', NULL, 344, 'local:warsh-text.json'),
  ('warsh-23-31', 'warsh', 23, 31, 'ثُمَّ أَنشَأْنَا مِنۢ بَعْدِهِمْ قَرْناً اٰخَرِينَ', 'ثم أنشأنا من بعدهم قرنا اخرين', NULL, 344, 'local:warsh-text.json'),
  ('warsh-23-32', 'warsh', 23, 32, 'فَأَرْسَلْنَا فِيهِمْ رَسُولاࣰ مِّنْهُمُۥٓ أَنُ ࡲ࢈عْبُدُواْ ࡲ۬للَّهَ مَا لَكُم مِّنِ ࡴلَٰهٍ غَيْرُهُۥٓ࣌ أَفَلَا تَتَّقُونَ࣌', 'فأرسلنا فيهم رسولا منهم أن ࡲ࢈عبدوا ࡲلله ما لكم من ࡴله غيره࣌ أفلا تتقون࣌', NULL, 344, 'local:warsh-text.json'),
  ('warsh-23-33', 'warsh', 23, 33, 'وَقَالَ ࡰ۬لْمَلَأُ مِن قَوْمِهِ ࡴ۬لذِينَ كَفَرُواْ وَكَذَّبُواْ بِلِقَآءِ ࡴ۬لَاخِرَةِ وَأَتْرَفْنَٰهُمْ فِے ࡴ۬لْحَيَوٰةِ ࡴ۬لدُّنْيٜا مَا هَٰذَآ إِلَّا بَشَرࣱ مِّثْلُكُمْ يَاكُلُ مِمَّا تَاكُلُونَ مِنْهُ وَيَشْرَبُ مِمَّا تَشْرَبُونَ', 'وقال ࡰلملأ من قومه ࡴلذين كفروا وكذبوا بلقاء ࡴلاخرة وأترفنهم فے ࡴلحيوة ࡴلدنيا ما هذا إلا بشر مثلكم ياكل مما تاكلون منه ويشرب مما تشربون', NULL, 344, 'local:warsh-text.json'),
  ('warsh-23-34', 'warsh', 23, 34, 'وَلَئِنَ ࡰطَعْتُم بَشَراࣰ مِّثْلَكُمُۥٓ إِنَّكُمُۥٓ إِذاࣰ لَّخَٰسِرُونَ', 'ولئن ࡰطعتم بشرا مثلكم إنكم إذا لخسرون', NULL, 344, 'local:warsh-text.json'),
  ('warsh-23-35', 'warsh', 23, 35, 'أَيَعِدُكُمُۥٓ أَنَّكُمُۥٓ إِذَا مِتُّمْ وَكُنتُمْ تُرَاباࣰ وَعِظَٰماً ࡰنَّكُم مُّخْرَجُونَ', 'أيعدكم أنكم إذا متم وكنتم ترابا وعظما ࡰنكم مخرجون', NULL, 344, 'local:warsh-text.json'),
  ('warsh-23-36', 'warsh', 23, 36, 'هَيْهَاتَ هَيْهَاتَ لِمَا تُوعَدُونَ', 'هيهات هيهات لما توعدون', NULL, 344, 'local:warsh-text.json'),
  ('warsh-23-37', 'warsh', 23, 37, 'إِنْ هِيَ إِلَّا حَيَاتُنَا ࡰ۬لدُّنْيٜا نَمُوتُ وَنَحْيٜا وَمَا نَحْنُ بِمَبْعُوثِينَ', 'إن هي إلا حياتنا ࡰلدنيا نموت ونحيا وما نحن بمبعوثين', NULL, 344, 'local:warsh-text.json'),
  ('warsh-23-38', 'warsh', 23, 38, 'إِنْ هُوَ إِلَّا رَجُلٌ ࡴٜفْتَرٜىٰ عَلَى ࡰ۬للَّهِ كَذِباࣰ وَمَا نَحْنُ لَهُۥ بِمُومِنِينَ࣌', 'إن هو إلا رجل ࡴفترى على ࡰلله كذبا وما نحن له بمومنين࣌', NULL, 344, 'local:warsh-text.json'),
  ('warsh-23-39', 'warsh', 23, 39, '۞ قَالَ رَبِّ ࡴ࢈نصُرْنِے بِمَا كَذَّبُونِ࣌', 'قال رب ࡴ࢈نصرنے بما كذبون࣌', NULL, 344, 'local:warsh-text.json'),
  ('warsh-23-40', 'warsh', 23, 40, 'قَالَ عَمَّا قَلِيلࣲ لَّيُصْبِحُنَّ نَٰدِمِينَ࣌', 'قال عما قليل ليصبحن ندمين࣌', NULL, 344, 'local:warsh-text.json'),
  ('warsh-23-41', 'warsh', 23, 41, 'فَأَخَذَتْهُمُ ࡲ۬لصَّيْحَةُ بِالْحَقِّ فَجَعَلْنَٰهُمْ غُثَآءࣰ࣌ فَبُعْداࣰ لِّلْقَوْمِ ࡴ۬لظَّٰلِمِينَ࣌', 'فأخذتهم ࡲلصيحة بالحق فجعلنهم غثاء࣌ فبعدا للقوم ࡴلظلمين࣌', NULL, 344, 'local:warsh-text.json'),
  ('warsh-23-42', 'warsh', 23, 42, 'ثُمَّ أَنشَأْنَا مِنۢ بَعْدِهِمْ قُرُوناً اٰخَرِينَ࣌', 'ثم أنشأنا من بعدهم قرونا اخرين࣌', NULL, 344, 'local:warsh-text.json'),
  ('warsh-23-43', 'warsh', 23, 43, 'مَا تَسْبِقُ مِنُ ࡳمَّةٍ ࡰجَلَهَا وَمَا يَسْتَٰخِرُونَ࣌', 'ما تسبق من ࡳمة ࡰجلها وما يستخرون࣌', NULL, 345, 'local:warsh-text.json'),
  ('warsh-23-44', 'warsh', 23, 44, 'ثُمَّ أَرْسَلْنَا رُسُلَنَا تَتْرٜا࣌ كُلَّ مَا جَآءَ ࡸمَّةࣰ رَّسُولُهَا كَذَّبُوهُ࣌ فَأَتْبَعْنَا بَعْضَهُم بَعْضاࣰ وَجَعَلْنَٰهُمُۥٓ أَحَادِيثَ࣌ فَبُعْداࣰ لِّقَوْمࣲ لَّا يُومِنُونَ࣌', 'ثم أرسلنا رسلنا تترا࣌ كل ما جاء ࡸمة رسولها كذبوه࣌ فأتبعنا بعضهم بعضا وجعلنهم أحاديث࣌ فبعدا لقوم لا يومنون࣌', NULL, 345, 'local:warsh-text.json'),
  ('warsh-23-45', 'warsh', 23, 45, 'ثُمَّ أَرْسَلْنَا مُوسٜىٰ وَأَخَاهُ هَٰرُونَ', 'ثم أرسلنا موسى وأخاه هرون', NULL, 345, 'local:warsh-text.json'),
  ('warsh-23-46', 'warsh', 23, 46, 'بِـَٔايَٰتِنَا وَسُلْطَٰنࣲ مُّبِينٍ', 'بايتنا وسلطن مبين', NULL, 345, 'local:warsh-text.json'),
  ('warsh-23-47', 'warsh', 23, 47, 'ࡴلَىٰ فِرْعَوْنَ وَمَلَإِيْهِۦ فَاسْتَكْبَرُواْ وَكَانُواْ قَوْماً عَالِينَ࣌', 'ࡴلى فرعون وملإيه فاستكبروا وكانوا قوما عالين࣌', NULL, 345, 'local:warsh-text.json'),
  ('warsh-23-48', 'warsh', 23, 48, 'فَقَالُوٓاْ أَنُومِنُ لِبَشَرَيْنِ مِثْلِنَا وَقَوْمُهُمَا لَنَا عَٰبِدُونَ࣌', 'فقالوا أنومن لبشرين مثلنا وقومهما لنا عبدون࣌', NULL, 345, 'local:warsh-text.json'),
  ('warsh-23-49', 'warsh', 23, 49, 'فَكَذَّبُوهُمَا فَكَانُواْ مِنَ ࡰ۬لْمُهْلَكِينَ࣌', 'فكذبوهما فكانوا من ࡰلمهلكين࣌', NULL, 345, 'local:warsh-text.json'),
  ('warsh-23-50', 'warsh', 23, 50, 'وَلَقَدَ اٰتَيْنَا مُوسَى ࡰ۬لْكِتَٰبَ لَعَلَّهُمْ يَهْتَدُونَ࣌', 'ولقد اتينا موسى ࡰلكتب لعلهم يهتدون࣌', NULL, 345, 'local:warsh-text.json'),
  ('warsh-23-51', 'warsh', 23, 51, 'وَجَعَلْنَا ࡰٜبْنَ مَرْيَمَ وَأُمَّهُۥٓ ءَايَةࣰ࣌ وَءَاوَيْنَٰهُمَآ إِلَىٰ رُبْوَةࣲ ذَاتِ قَرٜارࣲ وَمَعِينࣲ࣌', 'وجعلنا ࡰبن مريم وأمه ءاية࣌ وءاوينهما إلى ربوة ذات قرار ومعين࣌', NULL, 345, 'local:warsh-text.json'),
  ('warsh-23-52', 'warsh', 23, 52, 'يَٰٓأَيُّهَا ࡰ۬لرُّسُلُ كُلُواْ مِنَ ࡰ۬لطَّيِّبَٰتِ وَاعْمَلُواْ صَٰلِحاً࣌ ࡴنِّے بِمَا تَعْمَلُونَ عَلِيمࣱ࣌', 'يأيها ࡰلرسل كلوا من ࡰلطيبت واعملوا صلحا࣌ ࡴنے بما تعملون عليم࣌', NULL, 345, 'local:warsh-text.json'),
  ('warsh-23-53', 'warsh', 23, 53, 'وَأَنَّ هَٰذِهِۦٓ أُمَّتُكُمُۥٓ أُمَّةࣰ وَٰحِدَةࣰ࣌ وَأَنَا رَبُّكُمْ فَاتَّقُونِ࣌', 'وأن هذه أمتكم أمة وحدة࣌ وأنا ربكم فاتقون࣌', NULL, 345, 'local:warsh-text.json'),
  ('warsh-23-54', 'warsh', 23, 54, 'فَتَقَطَّعُوٓاْ أَمْرَهُم بَيْنَهُمْ زُبُراࣰ࣌ كُلُّ حِزْبِۢ بِمَا لَدَيْهِمْ فَرِحُونَ࣌', 'فتقطعوا أمرهم بينهم زبرا࣌ كل حزب بما لديهم فرحون࣌', NULL, 345, 'local:warsh-text.json'),
  ('warsh-23-55', 'warsh', 23, 55, 'فَذَرْهُمْ فِے غَمْرَتِهِمْ حَتَّىٰ حِينٍ࣌', 'فذرهم فے غمرتهم حتى حين࣌', NULL, 345, 'local:warsh-text.json'),
  ('warsh-23-56', 'warsh', 23, 56, 'ࡰيَحْسِبُونَ أَنَّمَا نُمِدُّهُم بِهِۦ مِن مَّالࣲ وَبَنِينَ', 'ࡰيحسبون أنما نمدهم به من مال وبنين', NULL, 345, 'local:warsh-text.json'),
  ('warsh-23-57', 'warsh', 23, 57, 'نُسَارِعُ لَهُمْ فِے ࡴ۬لْخَيْرَٰتِ࣌ بَل لَّا يَشْعُرُونَ࣌', 'نسارع لهم فے ࡴلخيرت࣌ بل لا يشعرون࣌', NULL, 345, 'local:warsh-text.json'),
  ('warsh-23-58', 'warsh', 23, 58, '۞ إِنَّ ࡰ۬لذِينَ هُم مِّنْ خَشْيَةِ رَبِّهِم مُّشْفِقُونَ', 'إن ࡰلذين هم من خشية ربهم مشفقون', NULL, 345, 'local:warsh-text.json'),
  ('warsh-23-59', 'warsh', 23, 59, 'وَالذِينَ هُم بِـَٔايَٰتِ رَبِّهِمْ يُومِنُونَ', 'والذين هم بايت ربهم يومنون', NULL, 345, 'local:warsh-text.json'),
  ('warsh-23-60', 'warsh', 23, 60, 'وَالذِينَ هُم بِرَبِّهِمْ لَا يُشْرِكُونَ', 'والذين هم بربهم لا يشركون', NULL, 345, 'local:warsh-text.json'),
  ('warsh-23-61', 'warsh', 23, 61, 'وَالذِينَ يُوتُونَ مَآ ءَاتَواْ وَّقُلُوبُهُمْ وَجِلَةٌ ࡰنَّهُمُۥٓ إِلَىٰ رَبِّهِمْ رَٰجِعُونَ', 'والذين يوتون ما ءاتوا وقلوبهم وجلة ࡰنهم إلى ربهم رجعون', NULL, 346, 'local:warsh-text.json'),
  ('warsh-23-62', 'warsh', 23, 62, 'أُوْلَٰٓئِكَ يُسَٰرِعُونَ فِے ࡴ۬لْخَيْرَٰتِ࣌ وَهُمْ لَهَا سَٰبِقُونَ࣌', 'أولئك يسرعون فے ࡴلخيرت࣌ وهم لها سبقون࣌', NULL, 346, 'local:warsh-text.json'),
  ('warsh-23-63', 'warsh', 23, 63, 'وَلَا نُكَلِّفُ نَفْساً ࡴلَّا وُسْعَهَا࣌ وَلَدَيْنَا كِتَٰبࣱ يَنطِقُ بِالْحَقِّ وَهُمْ لَا يُظْلَمُونَ࣌', 'ولا نكلف نفسا ࡴلا وسعها࣌ ولدينا كتب ينطق بالحق وهم لا يظلمون࣌', NULL, 346, 'local:warsh-text.json'),
  ('warsh-23-64', 'warsh', 23, 64, 'بَلْ قُلُوبُهُمْ فِے غَمْرَةࣲ مِّنْ هَٰذَا࣌ وَلَهُمُۥٓ أَعْمَٰلࣱ مِّن دُونِ ذَٰلِكَ࣌ هُمْ لَهَا عَٰمِلُونَ࣌', 'بل قلوبهم فے غمرة من هذا࣌ ولهم أعمل من دون ذلك࣌ هم لها عملون࣌', NULL, 346, 'local:warsh-text.json'),
  ('warsh-23-65', 'warsh', 23, 65, 'حَتَّىٰٓ إِذَآ أَخَذْنَا مُتْرَفِيهِم بِالْعَذَابِ إِذَا هُمْ يَجْـَٔرُونَ࣌', 'حتى إذا أخذنا مترفيهم بالعذاب إذا هم يجرون࣌', NULL, 346, 'local:warsh-text.json'),
  ('warsh-23-66', 'warsh', 23, 66, 'لَا تَجْـَٔرُواْ ࡲ۬لْيَوْمَ࣌ إِنَّكُم مِّنَّا لَا تُنصَرُونَ࣌', 'لا تجروا ࡲليوم࣌ إنكم منا لا تنصرون࣌', NULL, 346, 'local:warsh-text.json'),
  ('warsh-23-67', 'warsh', 23, 67, 'قَدْ كَانَتَ اٰيَٰتِے تُتْلٜىٰ عَلَيْكُمْ فَكُنتُمْ عَلَىٰٓ أَعْقَٰبِكُمْ تَنكِصُونَ', 'قد كانت ايتے تتلى عليكم فكنتم على أعقبكم تنكصون', NULL, 346, 'local:warsh-text.json'),
  ('warsh-23-68', 'warsh', 23, 68, 'مُسْتَكْبِرِينَ بِهِۦ࣌ سَٰمِراࣰ تُهْجِرُونَ࣌', 'مستكبرين به࣌ سمرا تهجرون࣌', NULL, 346, 'local:warsh-text.json'),
  ('warsh-23-69', 'warsh', 23, 69, 'أَفَلَمْ يَدَّبَّرُواْ ࡲ۬لْقَوْلَ أَمْ جَآءَهُم مَّا لَمْ يَاتِ ءَابَآءَهُمُ ࡲ۬لَاوَّلِينَ࣌', 'أفلم يدبروا ࡲلقول أم جاءهم ما لم يات ءاباءهم ࡲلاولين࣌', NULL, 346, 'local:warsh-text.json'),
  ('warsh-23-70', 'warsh', 23, 70, 'أَمْ لَمْ يَعْرِفُواْ رَسُولَهُمْ فَهُمْ لَهُۥ مُنكِرُونَ࣌', 'أم لم يعرفوا رسولهم فهم له منكرون࣌', NULL, 346, 'local:warsh-text.json'),
  ('warsh-23-71', 'warsh', 23, 71, 'أَمْ يَقُولُونَ بِهِۦ جِنَّةُۢ࣌ بَلْ جَآءَهُم بِالْحَقِّ࣌ وَأَكْثَرُهُمْ لِلْحَقِّ كَٰرِهُونَ࣌', 'أم يقولون به جنة࣌ بل جاءهم بالحق࣌ وأكثرهم للحق كرهون࣌', NULL, 346, 'local:warsh-text.json'),
  ('warsh-23-72', 'warsh', 23, 72, 'وَلَوِ ࡴٜتَّبَعَ ࡰ۬لْحَقُّ أَهْوَآءَهُمْ لَفَسَدَتِ ࡴ۬لسَّمَٰوَٰتُ وَالَارْضُ وَمَن فِيهِنَّ࣌ بَلَ ࡰتَيْنَٰهُم بِذِكْرِهِمْ࣌ فَهُمْ عَن ذِكْرِهِم مُّعْرِضُونَ࣌', 'ولو ࡴتبع ࡰلحق أهواءهم لفسدت ࡴلسموت والارض ومن فيهن࣌ بل ࡰتينهم بذكرهم࣌ فهم عن ذكرهم معرضون࣌', NULL, 346, 'local:warsh-text.json'),
  ('warsh-23-73', 'warsh', 23, 73, 'أَمْ تَسْـَٔلُهُمْ خَرْجاࣰ࣌ فَخَرَاجُ رَبِّكَ خَيْرࣱ࣌ وَهُوَ خَيْرُ ࡲ۬لرَّٰزِقِينَ࣌', 'أم تسلهم خرجا࣌ فخراج ربك خير࣌ وهو خير ࡲلرزقين࣌', NULL, 346, 'local:warsh-text.json'),
  ('warsh-23-74', 'warsh', 23, 74, 'وَإِنَّكَ لَتَدْعُوهُمُۥٓ إِلَىٰ صِرَٰطࣲ مُّسْتَقِيمࣲ࣌', 'وإنك لتدعوهم إلى صرط مستقيم࣌', NULL, 346, 'local:warsh-text.json'),
  ('warsh-23-75', 'warsh', 23, 75, 'وَإِنَّ ࡰ۬لذِينَ لَا يُومِنُونَ بِالَاخِرَةِ عَنِ ࡴ۬لصِّرَٰطِ لَنَٰكِبُونَ࣌', 'وإن ࡰلذين لا يومنون بالاخرة عن ࡴلصرط لنكبون࣌', NULL, 346, 'local:warsh-text.json'),
  ('warsh-23-76', 'warsh', 23, 76, '۞ وَلَوْ رَحِمْنَٰهُمْ وَكَشَفْنَا مَا بِهِم مِّن ضُرࣲّ لَّلَجُّواْ فِے طُغْيَٰنِهِمْ يَعْمَهُونَ࣌', 'ولو رحمنهم وكشفنا ما بهم من ضر للجوا فے طغينهم يعمهون࣌', NULL, 347, 'local:warsh-text.json'),
  ('warsh-23-77', 'warsh', 23, 77, 'وَلَقَدَ ࡰخَذْنَٰهُم بِالْعَذَابِ فَمَا ࡰٜسْتَكَانُواْ لِرَبِّهِمْ وَمَا يَتَضَرَّعُونَ࣌', 'ولقد ࡰخذنهم بالعذاب فما ࡰستكانوا لربهم وما يتضرعون࣌', NULL, 347, 'local:warsh-text.json'),
  ('warsh-23-78', 'warsh', 23, 78, 'حَتَّىٰٓ إِذَا فَتَحْنَا عَلَيْهِم بَاباࣰ ذَا عَذَابࣲ شَدِيدٍ ࡴذَا هُمْ فِيهِ مُبْلِسُونَ࣌', 'حتى إذا فتحنا عليهم بابا ذا عذاب شديد ࡴذا هم فيه مبلسون࣌', NULL, 347, 'local:warsh-text.json'),
  ('warsh-23-79', 'warsh', 23, 79, 'وَهُوَ ࡰ۬لذِےٓ أَنشَأَ لَكُمُ ࡲ۬لسَّمْعَ وَالَابْصَٰرَ وَالَافْـِٕدَةَ࣌ قَلِيلاࣰ مَّا تَشْكُرُونَ࣌', 'وهو ࡰلذے أنشأ لكم ࡲلسمع والابصر والافدة࣌ قليلا ما تشكرون࣌', NULL, 347, 'local:warsh-text.json'),
  ('warsh-23-80', 'warsh', 23, 80, 'وَهُوَ ࡰ۬لذِے ذَرَأَكُمْ فِے ࡴ۬لَارْضِ وَإِلَيْهِ تُحْشَرُونَ࣌', 'وهو ࡰلذے ذرأكم فے ࡴلارض وإليه تحشرون࣌', NULL, 347, 'local:warsh-text.json'),
  ('warsh-23-81', 'warsh', 23, 81, 'وَهُوَ ࡰ۬لذِے يُحْيِۦ وَيُمِيتُ࣌ وَلَهُ ࡲٜخْتِلَٰفُ ࡲ۬ليْلِ وَالنَّهٜارِ࣌ أَفَلَا تَعْقِلُونَ࣌', 'وهو ࡰلذے يحي ويميت࣌ وله ࡲختلف ࡲليل والنهار࣌ أفلا تعقلون࣌', NULL, 347, 'local:warsh-text.json'),
  ('warsh-23-82', 'warsh', 23, 82, 'بَلْ قَالُواْ مِثْلَ مَا قَالَ ࡰ۬لَاوَّلُونَ', 'بل قالوا مثل ما قال ࡰلاولون', NULL, 347, 'local:warsh-text.json'),
  ('warsh-23-83', 'warsh', 23, 83, 'قَالُوٓاْ أَࢇذَا مِتْنَا وَكُنَّا تُرَاباࣰ وَعِظَٰماً ࡴنَّا لَمَبْعُوثُونَ࣌', 'قالوا أࢇذا متنا وكنا ترابا وعظما ࡴنا لمبعوثون࣌', NULL, 347, 'local:warsh-text.json'),
  ('warsh-23-84', 'warsh', 23, 84, 'لَقَدْ وُعِدْنَا نَحْنُ وَءَابَآؤُنَا هَٰذَا مِن قَبْلُ࣌ إِنْ هَٰذَآ إِلَّآ أَسَٰطِيرُ ࡲ۬لَاوَّلِينَ࣌', 'لقد وعدنا نحن وءاباؤنا هذا من قبل࣌ إن هذا إلا أسطير ࡲلاولين࣌', NULL, 347, 'local:warsh-text.json'),
  ('warsh-23-85', 'warsh', 23, 85, 'قُل لِّمَنِ ࡴ۬لَارْضُ وَمَن فِيهَآ إِن كُنتُمْ تَعْلَمُونَ', 'قل لمن ࡴلارض ومن فيها إن كنتم تعلمون', NULL, 347, 'local:warsh-text.json'),
  ('warsh-23-86', 'warsh', 23, 86, 'سَيَقُولُونَ لِلهِ࣌ قُلَ ࡰفَلَا تَذَّكَّرُونَ࣌', 'سيقولون لله࣌ قل ࡰفلا تذكرون࣌', NULL, 347, 'local:warsh-text.json'),
  ('warsh-23-87', 'warsh', 23, 87, 'قُلْ مَن رَّبُّ ࡲ۬لسَّمَٰوَٰتِ ࡴ۬لسَّبْعِ وَرَبُّ ࡲ۬لْعَرْشِ ࡴ۬لْعَظِيمِ࣌', 'قل من رب ࡲلسموت ࡴلسبع ورب ࡲلعرش ࡴلعظيم࣌', NULL, 347, 'local:warsh-text.json'),
  ('warsh-23-88', 'warsh', 23, 88, 'سَيَقُولُونَ لِلهِ࣌ قُلَ ࡰفَلَا تَتَّقُونَ࣌', 'سيقولون لله࣌ قل ࡰفلا تتقون࣌', NULL, 347, 'local:warsh-text.json'),
  ('warsh-23-89', 'warsh', 23, 89, 'قُلْ مَنۢ بِيَدِهِۦ مَلَكُوتُ كُلِّ شَےْءࣲ وَهُوَ يُجِيرُ وَلَا يُجَارُ عَلَيْهِ إِن كُنتُمْ تَعْلَمُونَ', 'قل من بيده ملكوت كل شےء وهو يجير ولا يجار عليه إن كنتم تعلمون', NULL, 347, 'local:warsh-text.json'),
  ('warsh-23-90', 'warsh', 23, 90, 'سَيَقُولُونَ لِلهِ࣌ قُلْ فَأَنّٜىٰ تُسْحَرُونَ࣌', 'سيقولون لله࣌ قل فأنى تسحرون࣌', NULL, 347, 'local:warsh-text.json'),
  ('warsh-23-91', 'warsh', 23, 91, 'بَلَ ࡰتَيْنَٰهُم بِالْحَقِّ࣌ وَإِنَّهُمْ لَكَٰذِبُونَ࣌', 'بل ࡰتينهم بالحق࣌ وإنهم لكذبون࣌', NULL, 348, 'local:warsh-text.json'),
  ('warsh-23-92', 'warsh', 23, 92, 'مَا ࡰٜتَّخَذَ ࡰ۬للَّهُ مِنْ وَّلَدࣲ࣌ وَمَا كَانَ مَعَهُۥ مِنِ ࡴلَٰهٍ࣌ ࡴذاࣰ لَّذَهَبَ كُلُّ إِلَٰهِۢ بِمَا خَلَقَ وَلَعَلَا بَعْضُهُمْ عَلَىٰ بَعْضࣲ࣌ سُبْحَٰنَ ࡰ۬للَّهِ عَمَّا يَصِفُونَ࣌', 'ما ࡰتخذ ࡰلله من ولد࣌ وما كان معه من ࡴله࣌ ࡴذا لذهب كل إله بما خلق ولعلا بعضهم على بعض࣌ سبحن ࡰلله عما يصفون࣌', NULL, 348, 'local:warsh-text.json'),
  ('warsh-23-93', 'warsh', 23, 93, 'عَٰلِمُ ࡲ۬لْغَيْبِ وَالشَّهَٰدَةِ࣌ فَتَعَٰلٜىٰ عَمَّا يُشْرِكُونَ࣌', 'علم ࡲلغيب والشهدة࣌ فتعلى عما يشركون࣌', NULL, 348, 'local:warsh-text.json'),
  ('warsh-23-94', 'warsh', 23, 94, '۞ قُل رَّبِّ إِمَّا تُرِيَنِّے مَا يُوعَدُونَ', 'قل رب إما ترينے ما يوعدون', NULL, 348, 'local:warsh-text.json'),
  ('warsh-23-95', 'warsh', 23, 95, 'رَبِّ فَلَا تَجْعَلْنِے فِے ࡴ۬لْقَوْمِ ࡴ۬لظَّٰلِمِينَ࣌', 'رب فلا تجعلنے فے ࡴلقوم ࡴلظلمين࣌', NULL, 348, 'local:warsh-text.json'),
  ('warsh-23-96', 'warsh', 23, 96, 'وَإِنَّا عَلَىٰٓ أَن نُّرِيَكَ مَا نَعِدُهُمْ لَقَٰدِرُونَ࣌', 'وإنا على أن نريك ما نعدهم لقدرون࣌', NULL, 348, 'local:warsh-text.json'),
  ('warsh-23-97', 'warsh', 23, 97, 'ࡰٜدْفَعْ بِالتِے هِيَ أَحْسَنُ ࡲ۬لسَّيِّئَةَ࣌ نَحْنُ أَعْلَمُ بِمَا يَصِفُونَ࣌', 'ࡰدفع بالتے هي أحسن ࡲلسيئة࣌ نحن أعلم بما يصفون࣌', NULL, 348, 'local:warsh-text.json'),
  ('warsh-23-98', 'warsh', 23, 98, 'وَقُل رَّبِّ أَعُوذُ بِكَ مِنْ هَمَزَٰتِ ࡴ۬لشَّيَٰطِينِ', 'وقل رب أعوذ بك من همزت ࡴلشيطين', NULL, 348, 'local:warsh-text.json'),
  ('warsh-23-99', 'warsh', 23, 99, 'وَأَعُوذُ بِكَ رَبِّ أَنْ يَّحْضُرُونِ࣌', 'وأعوذ بك رب أن يحضرون࣌', NULL, 348, 'local:warsh-text.json'),
  ('warsh-23-100', 'warsh', 23, 100, 'حَتَّىٰٓ إِذَا جَآءَ احَدَهُمُ ࡲ۬لْمَوْتُ قَالَ رَبِّ ࡴٜرْجِعُونِ', 'حتى إذا جاء احدهم ࡲلموت قال رب ࡴرجعون', NULL, 348, 'local:warsh-text.json'),
  ('warsh-23-101', 'warsh', 23, 101, 'لَعَلِّيَ أَعْمَلُ صَٰلِحاࣰ فِيمَا تَرَكْتُ كَلَّآ࣌ إِنَّهَا كَلِمَةٌ هُوَ قَآئِلُهَا࣌ وَمِنْ وَّرَآئِهِم بَرْزَخٌ ࡴلَىٰ يَوْمِ يُبْعَثُونَ࣌', 'لعلي أعمل صلحا فيما تركت كلا࣌ إنها كلمة هو قائلها࣌ ومن ورائهم برزخ ࡴلى يوم يبعثون࣌', NULL, 348, 'local:warsh-text.json'),
  ('warsh-23-102', 'warsh', 23, 102, 'فَإِذَا نُفِخَ فِے ࡴ۬لصُّورِ فَلَآ أَنسَابَ بَيْنَهُمْ يَوْمَئِذࣲ وَلَا يَتَسَآءَلُونَ࣌', 'فإذا نفخ فے ࡴلصور فلا أنساب بينهم يومئذ ولا يتساءلون࣌', NULL, 348, 'local:warsh-text.json'),
  ('warsh-23-103', 'warsh', 23, 103, 'فَمَن ثَقُلَتْ مَوَٰزِينُهُۥ فَأُوْلَٰٓئِكَ هُمُ ࡲ۬لْمُفْلِحُونَ࣌', 'فمن ثقلت موزينه فأولئك هم ࡲلمفلحون࣌', NULL, 348, 'local:warsh-text.json'),
  ('warsh-23-104', 'warsh', 23, 104, 'وَمَنْ خَفَّتْ مَوَٰزِينُهُۥ فَأُوْلَٰٓئِكَ ࡰ۬لذِينَ خَسِرُوٓاْ أَنفُسَهُمْ فِے جَهَنَّمَ خَٰلِدُونَ', 'ومن خفت موزينه فأولئك ࡰلذين خسروا أنفسهم فے جهنم خلدون', NULL, 348, 'local:warsh-text.json'),
  ('warsh-23-105', 'warsh', 23, 105, 'تَلْفَحُ وُجُوهَهُمُ ࡲ۬لنَّارُ وَهُمْ فِيهَا كَٰلِحُونَ࣌', 'تلفح وجوههم ࡲلنار وهم فيها كلحون࣌', NULL, 348, 'local:warsh-text.json'),
  ('warsh-23-106', 'warsh', 23, 106, 'أَلَمْ تَكُنَ اٰيَٰتِے تُتْلٜىٰ عَلَيْكُمْ فَكُنتُم بِهَا تُكَذِّبُونَ࣌', 'ألم تكن ايتے تتلى عليكم فكنتم بها تكذبون࣌', NULL, 349, 'local:warsh-text.json'),
  ('warsh-23-107', 'warsh', 23, 107, 'قَالُواْ رَبَّنَا غَلَبَتْ عَلَيْنَا شِقْوَتُنَا وَكُنَّا قَوْماࣰ ضَآلِّينَ࣌', 'قالوا ربنا غلبت علينا شقوتنا وكنا قوما ضالين࣌', NULL, 349, 'local:warsh-text.json'),
  ('warsh-23-108', 'warsh', 23, 108, 'رَبَّنَآ أَخْرِجْنَا مِنْهَا فَإِنْ عُدْنَا فَإِنَّا ظَٰلِمُونَ࣌', 'ربنا أخرجنا منها فإن عدنا فإنا ظلمون࣌', NULL, 349, 'local:warsh-text.json'),
  ('warsh-23-109', 'warsh', 23, 109, 'قَالَ ࡰٜخْسَـُٔواْ فِيهَا وَلَا تُكَلِّمُونِ࣌', 'قال ࡰخسوا فيها ولا تكلمون࣌', NULL, 349, 'local:warsh-text.json'),
  ('warsh-23-110', 'warsh', 23, 110, 'إِنَّهُۥ كَانَ فَرِيقࣱ مِّنْ عِبَادِے يَقُولُونَ رَبَّنَآ ءَامَنَّا فَاغْفِرْ لَنَا وَارْحَمْنَا وَأَنتَ خَيْرُ ࡲ۬لرَّٰحِمِينَ', 'إنه كان فريق من عبادے يقولون ربنا ءامنا فاغفر لنا وارحمنا وأنت خير ࡲلرحمين', NULL, 349, 'local:warsh-text.json'),
  ('warsh-23-111', 'warsh', 23, 111, 'فَاتَّخَذتُّمُوهُمْ سُخْرِيّاً حَتَّىٰٓ أَنسَوْكُمْ ذِكْرِے وَكُنتُم مِّنْهُمْ تَضْحَكُونَ࣌', 'فاتخذتموهم سخريا حتى أنسوكم ذكرے وكنتم منهم تضحكون࣌', NULL, 349, 'local:warsh-text.json'),
  ('warsh-23-112', 'warsh', 23, 112, 'إِنِّے جَزَيْتُهُمُ ࡲ۬لْيَوْمَ بِمَا صَبَرُوٓاْ أَنَّهُمْ هُمُ ࡲ۬لْفَآئِزُونَ࣌', 'إنے جزيتهم ࡲليوم بما صبروا أنهم هم ࡲلفائزون࣌', NULL, 349, 'local:warsh-text.json'),
  ('warsh-23-113', 'warsh', 23, 113, 'قَالَ كَمْ لَبِثْتُمْ فِے ࡴ۬لَارْضِ عَدَدَ سِنِينَ࣌', 'قال كم لبثتم فے ࡴلارض عدد سنين࣌', NULL, 349, 'local:warsh-text.json'),
  ('warsh-23-114', 'warsh', 23, 114, 'قَالُواْ لَبِثْنَا يَوْماً ࡰوْ بَعْضَ يَوْمࣲ࣌ فَسْـَٔلِ ࡴ۬لْعَآدِّينَ࣌', 'قالوا لبثنا يوما ࡰو بعض يوم࣌ فسل ࡴلعادين࣌', NULL, 349, 'local:warsh-text.json'),
  ('warsh-23-115', 'warsh', 23, 115, 'قَالَ إِن لَّبِثْتُمُۥٓ إِلَّا قَلِيلاࣰ لَّوَ ࡰنَّكُمْ كُنتُمْ تَعْلَمُونَ࣌', 'قال إن لبثتم إلا قليلا لو ࡰنكم كنتم تعلمون࣌', NULL, 349, 'local:warsh-text.json'),
  ('warsh-23-116', 'warsh', 23, 116, '۞ أَفَحَسِبْتُمُۥٓ أَنَّمَا خَلَقْنَٰكُمْ عَبَثاࣰ وَأَنَّكُمُۥٓ إِلَيْنَا لَا تُرْجَعُونَ࣌', 'أفحسبتم أنما خلقنكم عبثا وأنكم إلينا لا ترجعون࣌', NULL, 349, 'local:warsh-text.json'),
  ('warsh-23-117', 'warsh', 23, 117, 'فَتَعَٰلَى ࡰ۬للَّهُ ࡲ۬لْمَلِكُ ࡲ۬لْحَقُّ࣌ لَآ إِلَٰهَ إِلَّا هُوَ࣌ رَبُّ ࡲ۬لْعَرْشِ ࡴ۬لْكَرِيمِ࣌', 'فتعلى ࡰلله ࡲلملك ࡲلحق࣌ لا إله إلا هو࣌ رب ࡲلعرش ࡴلكريم࣌', NULL, 349, 'local:warsh-text.json'),
  ('warsh-23-118', 'warsh', 23, 118, 'وَمَنْ يَّدْعُ مَعَ ࡰ۬للَّهِ إِلَٰهاً اٰخَرَ لَا بُرْهَٰنَ لَهُۥ بِهِۦ فَإِنَّمَا حِسَابُهُۥ عِندَ رَبِّهِۦٓ࣌ إِنَّهُۥ لَا يُفْلِحُ ࡲ۬لْكَٰفِرُونَ࣌', 'ومن يدع مع ࡰلله إلها اخر لا برهن له به فإنما حسابه عند ربه࣌ إنه لا يفلح ࡲلكفرون࣌', NULL, 349, 'local:warsh-text.json'),
  ('warsh-23-119', 'warsh', 23, 119, 'وَقُل رَّبِّ ࡴٜغْفِرْ وَارْحَمْ وَأَنتَ خَيْرُ ࡲ۬لرَّٰحِمِينَ࣌', 'وقل رب ࡴغفر وارحم وأنت خير ࡲلرحمين࣌', NULL, 349, 'local:warsh-text.json'),
  ('warsh-24-1', 'warsh', 24, 1, 'سُورَةٌ ࡰنزَلْنَٰهَا وَفَرَضْنَٰهَا وَأَنزَلْنَا فِيهَآ ءَايَٰتِۢ بَيِّنَٰتࣲ لَّعَلَّكُمْ تَذَّكَّرُونَ࣌', 'سورة ࡰنزلنها وفرضنها وأنزلنا فيها ءايت بينت لعلكم تذكرون࣌', NULL, 350, 'local:warsh-text.json'),
  ('warsh-24-2', 'warsh', 24, 2, 'ࡰ۬لزَّانِيَةُ وَالزَّانِے فَاجْلِدُواْ كُلَّ وَٰحِدࣲ مِّنْهُمَا مِاْئَةَ جَلْدَةࣲ࣌ وَلَا تَاخُذْكُم بِهِمَا رَأْفَةࣱ فِے دِينِ ࡴ۬للَّهِ إِن كُنتُمْ تُومِنُونَ بِاللَّهِ وَالْيَوْمِ ࡴ۬لَاخِرِ࣌ وَلْيَشْهَدْ عَذَابَهُمَا طَآئِفَةࣱ مِّنَ ࡰ۬لْمُومِنِينَ࣌', 'ࡰلزانية والزانے فاجلدوا كل وحد منهما مائة جلدة࣌ ولا تاخذكم بهما رأفة فے دين ࡴلله إن كنتم تومنون بالله واليوم ࡴلاخر࣌ وليشهد عذابهما طائفة من ࡰلمومنين࣌', NULL, 350, 'local:warsh-text.json'),
  ('warsh-24-3', 'warsh', 24, 3, 'ࡰ۬لزَّانِے لَا يَنكِحُ إِلَّا زَانِيَةً ࡰوْ مُشْرِكَةࣰ࣌ وَالزَّانِيَةُ لَا يَنكِحُهَآ إِلَّا زَانٍ ࡰوْ مُشْرِكࣱ࣌ وَحُرِّمَ ذَٰلِكَ عَلَى ࡰ۬لْمُومِنِينَ࣌', 'ࡰلزانے لا ينكح إلا زانية ࡰو مشركة࣌ والزانية لا ينكحها إلا زان ࡰو مشرك࣌ وحرم ذلك على ࡰلمومنين࣌', NULL, 350, 'local:warsh-text.json'),
  ('warsh-24-4', 'warsh', 24, 4, 'وَالذِينَ يَرْمُونَ ࡰ۬لْمُحْصَنَٰتِ ثُمَّ لَمْ يَاتُواْ بِأَرْبَعَةِ شُهَدَآءَ فَاجْلِدُوهُمْ ثَمَٰنِينَ جَلْدَةࣰ࣌ وَلَا تَقْبَلُواْ لَهُمْ شَهَٰدَةً ࡰبَداࣰ وَأُوْلَٰٓئِكَ هُمُ ࡲ۬لْفَٰسِقُونَ', 'والذين يرمون ࡰلمحصنت ثم لم ياتوا بأربعة شهداء فاجلدوهم ثمنين جلدة࣌ ولا تقبلوا لهم شهدة ࡰبدا وأولئك هم ࡲلفسقون', NULL, 350, 'local:warsh-text.json'),
  ('warsh-24-5', 'warsh', 24, 5, 'إِلَّا ࡰ۬لذِينَ تَابُواْ مِنۢ بَعْدِ ذَٰلِكَ وَأَصْلَحُواْ فَإِنَّ ࡰ۬للَّهَ غَفُورࣱ رَّحِيمࣱ࣌', 'إلا ࡰلذين تابوا من بعد ذلك وأصلحوا فإن ࡰلله غفور رحيم࣌', NULL, 350, 'local:warsh-text.json'),
  ('warsh-24-6', 'warsh', 24, 6, 'وَالذِينَ يَرْمُونَ أَزْوَٰجَهُمْ وَلَمْ يَكُن لَّهُمْ شُهَدَآءُ ࡹِلَّآ أَنفُسُهُمْ فَشَهَٰدَةُ أَحَدِهِمُۥٓ أَرْبَعَ شَهَٰدَٰتِۢ بِاللَّهِ إِنَّهُۥ لَمِنَ ࡰ۬لصَّٰدِقِينَ', 'والذين يرمون أزوجهم ولم يكن لهم شهداء ࡹلا أنفسهم فشهدة أحدهم أربع شهدت بالله إنه لمن ࡰلصدقين', NULL, 350, 'local:warsh-text.json'),
  ('warsh-24-7', 'warsh', 24, 7, 'وَالْخَٰمِسَةُ أَن لَّعْنَتُ ࡲ۬للَّهِ عَلَيْهِ إِن كَانَ مِنَ ࡰ۬لْكَٰذِبِينَ࣌', 'والخمسة أن لعنت ࡲلله عليه إن كان من ࡰلكذبين࣌', NULL, 350, 'local:warsh-text.json'),
  ('warsh-24-8', 'warsh', 24, 8, 'وَيَدْرَؤُاْ عَنْهَا ࡰ۬لْعَذَابَ أَن تَشْهَدَ أَرْبَعَ شَهَٰدَٰتِۢ بِاللَّهِ إِنَّهُۥ لَمِنَ ࡰ۬لْكَٰذِبِينَ', 'ويدرؤا عنها ࡰلعذاب أن تشهد أربع شهدت بالله إنه لمن ࡰلكذبين', NULL, 350, 'local:warsh-text.json'),
  ('warsh-24-9', 'warsh', 24, 9, 'وَالْخَٰمِسَةُ أَنْ غَضِبَ ࡰ۬للَّهُ عَلَيْهَآ إِن كَانَ مِنَ ࡰ۬لصَّٰدِقِينَ࣌', 'والخمسة أن غضب ࡰلله عليها إن كان من ࡰلصدقين࣌', NULL, 350, 'local:warsh-text.json'),
  ('warsh-24-10', 'warsh', 24, 10, 'وَلَوْلَا فَضْلُ ࡲ۬للَّهِ عَلَيْكُمْ وَرَحْمَتُهُۥ وَأَنَّ ࡰ۬للَّهَ تَوَّابٌ حَكِيمٌ࣌', 'ولولا فضل ࡲلله عليكم ورحمته وأن ࡰلله تواب حكيم࣌', NULL, 350, 'local:warsh-text.json'),
  ('warsh-24-11', 'warsh', 24, 11, '۞ ࡴنَّ ࡰ۬لذِينَ جَآءُو بِالِافْكِ عُصْبَةࣱ مِّنكُمْ لَا تَحْسِبُوهُ شَرّاࣰ لَّكُم࣌ بَلْ هُوَ خَيْرࣱ لَّكُمْ࣌ لِكُلِّ ࡴٜمْرِےࣲٕ مِّنْهُم مَّا ࡰٜكْتَسَبَ مِنَ ࡰ۬لِاثْمِ࣌ وَالذِے تَوَلّٜىٰ كِبْرَهُۥ مِنْهُمْ لَهُۥ عَذَابٌ عَظِيمࣱ࣌', 'ࡴن ࡰلذين جاءو بالافك عصبة منكم لا تحسبوه شرا لكم࣌ بل هو خير لكم࣌ لكل ࡴمرے منهم ما ࡰكتسب من ࡰلاثم࣌ والذے تولى كبره منهم له عذاب عظيم࣌', NULL, 351, 'local:warsh-text.json'),
  ('warsh-24-12', 'warsh', 24, 12, 'لَّوْلَآ إِذْ سَمِعْتُمُوهُ ظَنَّ ࡰ۬لْمُومِنُونَ وَالْمُومِنَٰتُ بِأَنفُسِهِمْ خَيْراࣰ وَقَالُواْ هَٰذَآ إِفْكࣱ مُّبِينࣱ࣌', 'لولا إذ سمعتموه ظن ࡰلمومنون والمومنت بأنفسهم خيرا وقالوا هذا إفك مبين࣌', NULL, 351, 'local:warsh-text.json')
insert into public.ayahs (id, riwayah, surah_number, ayah_number, text, simple_text, juz, page, source) values
  ('warsh-24-13', 'warsh', 24, 13, 'لَّوْلَا جَآءُو عَلَيْهِ بِأَرْبَعَةِ شُهَدَآءَ࣌ فَإِذْ لَمْ يَاتُواْ بِالشُّهَدَآءِ فَأُوْلَٰٓئِكَ عِندَ ࡰ۬للَّهِ هُمُ ࡲ۬لْكَٰذِبُونَ࣌', 'لولا جاءو عليه بأربعة شهداء࣌ فإذ لم ياتوا بالشهداء فأولئك عند ࡰلله هم ࡲلكذبون࣌', NULL, 351, 'local:warsh-text.json'),
  ('warsh-24-14', 'warsh', 24, 14, 'وَلَوْلَا فَضْلُ ࡲ۬للَّهِ عَلَيْكُمْ وَرَحْمَتُهُۥ فِے ࡴ۬لدُّنْيٜا وَالَاخِرَةِ لَمَسَّكُمْ فِے مَآ أَفَضْتُمْ فِيهِ عَذَابٌ عَظِيمٌ', 'ولولا فضل ࡲلله عليكم ورحمته فے ࡴلدنيا والاخرة لمسكم فے ما أفضتم فيه عذاب عظيم', NULL, 351, 'local:warsh-text.json'),
  ('warsh-24-15', 'warsh', 24, 15, 'ࡴذْ تَلَقَّوْنَهُۥ بِأَلْسِنَتِكُمْ وَتَقُولُونَ بِأَفْوَاهِكُم مَّا لَيْسَ لَكُم بِهِۦ عِلْمࣱ وَتَحْسِبُونَهُۥ هَيِّناࣰ وَهُوَ عِندَ ࡰ۬للَّهِ عَظِيمࣱ࣌', 'ࡴذ تلقونه بألسنتكم وتقولون بأفواهكم ما ليس لكم به علم وتحسبونه هينا وهو عند ࡰلله عظيم࣌', NULL, 351, 'local:warsh-text.json'),
  ('warsh-24-16', 'warsh', 24, 16, 'وَلَوْلَآ إِذْ سَمِعْتُمُوهُ قُلْتُم مَّا يَكُونُ لَنَآ أَن نَّتَكَلَّمَ بِهَٰذَا سُبْحَٰنَكَ هَٰذَا بُهْتَٰنٌ عَظِيمࣱ࣌', 'ولولا إذ سمعتموه قلتم ما يكون لنا أن نتكلم بهذا سبحنك هذا بهتن عظيم࣌', NULL, 351, 'local:warsh-text.json'),
  ('warsh-24-17', 'warsh', 24, 17, 'يَعِظُكُمُ ࡲ۬للَّهُ أَن تَعُودُواْ لِمِثْلِهِۦٓ أَبَداً ࡴن كُنتُم مُّومِنِينَ࣌', 'يعظكم ࡲلله أن تعودوا لمثله أبدا ࡴن كنتم مومنين࣌', NULL, 351, 'local:warsh-text.json'),
  ('warsh-24-18', 'warsh', 24, 18, 'وَيُبَيِّنُ ࡲ۬للَّهُ لَكُمُ ࡲ۬لَايَٰتِ࣌ وَاللَّهُ عَلِيمٌ حَكِيمٌ࣌', 'ويبين ࡲلله لكم ࡲلايت࣌ والله عليم حكيم࣌', NULL, 351, 'local:warsh-text.json'),
  ('warsh-24-19', 'warsh', 24, 19, 'ࡴنَّ ࡰ۬لذِينَ يُحِبُّونَ أَن تَشِيعَ ࡰ۬لْفَٰحِشَةُ فِے ࡴ۬لذِينَ ءَامَنُواْ لَهُمْ عَذَابٌ ࡰلِيمࣱ فِے ࡴ۬لدُّنْيٜا وَالَاخِرَةِ࣌ وَاللَّهُ يَعْلَمُ࣌ وَأَنتُمْ لَا تَعْلَمُونَ࣌', 'ࡴن ࡰلذين يحبون أن تشيع ࡰلفحشة فے ࡴلذين ءامنوا لهم عذاب ࡰليم فے ࡴلدنيا والاخرة࣌ والله يعلم࣌ وأنتم لا تعلمون࣌', NULL, 351, 'local:warsh-text.json'),
  ('warsh-24-20', 'warsh', 24, 20, 'وَلَوْلَا فَضْلُ ࡲ۬للَّهِ عَلَيْكُمْ وَرَحْمَتُهُۥ وَأَنَّ ࡰ۬للَّهَ رَءُوفࣱ رَّحِيمࣱ࣌', 'ولولا فضل ࡲلله عليكم ورحمته وأن ࡰلله رءوف رحيم࣌', NULL, 351, 'local:warsh-text.json'),
  ('warsh-24-21', 'warsh', 24, 21, '۞ يَٰٓأَيُّهَا ࡰ۬لذِينَ ءَامَنُواْ لَا تَتَّبِعُواْ خُطْوَٰتِ ࡴ۬لشَّيْطَٰنِ࣌ وَمَنْ يَّتَّبِعْ خُطْوَٰتِ ࡴ۬لشَّيْطَٰنِ فَإِنَّهُۥ يَامُرُ بِالْفَحْشَآءِ وَالْمُنكَرِ࣌ وَلَوْلَا فَضْلُ ࡲ۬للَّهِ عَلَيْكُمْ وَرَحْمَتُهُۥ مَا زَكَىٰ مِنكُم مِّنَ ࡰحَدٍ ࡰبَداࣰ࣌ وَلَٰكِنَّ ࡰ۬للَّهَ يُزَكِّے مَنْ يَّشَآءُ࣌ وَاللَّهُ سَمِيعٌ عَلِيمࣱ࣌', 'يأيها ࡰلذين ءامنوا لا تتبعوا خطوت ࡴلشيطن࣌ ومن يتبع خطوت ࡴلشيطن فإنه يامر بالفحشاء والمنكر࣌ ولولا فضل ࡲلله عليكم ورحمته ما زكى منكم من ࡰحد ࡰبدا࣌ ولكن ࡰلله يزكے من يشاء࣌ والله سميع عليم࣌', NULL, 352, 'local:warsh-text.json'),
  ('warsh-24-22', 'warsh', 24, 22, 'وَلَا يَاتَلِ أُوْلُواْ ࡲ۬لْفَضْلِ مِنكُمْ وَالسَّعَةِ أَنْ يُّوتُوٓاْ أُوْلِے ࡴ۬لْقُرْبٜىٰ وَالْمَسَٰكِينَ وَالْمُهَٰجِرِينَ فِے سَبِيلِ ࡴ۬للَّهِ࣌ وَلْيَعْفُواْ وَلْيَصْفَحُوٓاْ࣌ أَلَا تُحِبُّونَ أَنْ يَّغْفِرَ ࡰ۬للَّهُ لَكُمْ࣌ وَاللَّهُ غَفُورࣱ رَّحِيمٌ࣌', 'ولا ياتل أولوا ࡲلفضل منكم والسعة أن يوتوا أولے ࡴلقربى والمسكين والمهجرين فے سبيل ࡴلله࣌ وليعفوا وليصفحوا࣌ ألا تحبون أن يغفر ࡰلله لكم࣌ والله غفور رحيم࣌', NULL, 352, 'local:warsh-text.json'),
  ('warsh-24-23', 'warsh', 24, 23, 'ࡴنَّ ࡰ۬لذِينَ يَرْمُونَ ࡰ۬لْمُحْصَنَٰتِ ࡴ۬لْغَٰفِلَٰتِ ࡴ۬لْمُومِنَٰتِ لُعِنُواْ فِے ࡴ۬لدُّنْيٜا وَالَاخِرَةِ وَلَهُمْ عَذَابٌ عَظِيمࣱ', 'ࡴن ࡰلذين يرمون ࡰلمحصنت ࡴلغفلت ࡴلمومنت لعنوا فے ࡴلدنيا والاخرة ولهم عذاب عظيم', NULL, 352, 'local:warsh-text.json'),
  ('warsh-24-24', 'warsh', 24, 24, 'يَوْمَ تَشْهَدُ عَلَيْهِمُۥٓ أَلْسِنَتُهُمْ وَأَيْدِيهِمْ وَأَرْجُلُهُم بِمَا كَانُواْ يَعْمَلُونَ࣌', 'يوم تشهد عليهم ألسنتهم وأيديهم وأرجلهم بما كانوا يعملون࣌', NULL, 352, 'local:warsh-text.json'),
  ('warsh-24-25', 'warsh', 24, 25, 'يَوْمَئِذࣲ يُوَفِّيهِمُ ࡲ۬للَّهُ دِينَهُمُ ࡲ۬لْحَقَّ࣌ وَيَعْلَمُونَ أَنَّ ࡰ۬للَّهَ هُوَ ࡰ۬لْحَقُّ ࡲ۬لْمُبِينُ࣌', 'يومئذ يوفيهم ࡲلله دينهم ࡲلحق࣌ ويعلمون أن ࡰلله هو ࡰلحق ࡲلمبين࣌', NULL, 352, 'local:warsh-text.json'),
  ('warsh-24-26', 'warsh', 24, 26, 'ࡲ۬لْخَبِيثَٰتُ لِلْخَبِيثِينَ وَالْخَبِيثُونَ لِلْخَبِيثَٰتِ࣌ وَالطَّيِّبَٰتُ لِلطَّيِّبِينَ وَالطَّيِّبُونَ لِلطَّيِّبَٰتِ࣌ أُوْلَٰٓئِكَ مُبَرَّءُونَ مِمَّا يَقُولُونَ࣌ لَهُم مَّغْفِرَةࣱ وَرِزْقࣱ كَرِيمࣱ࣌', 'ࡲلخبيثت للخبيثين والخبيثون للخبيثت࣌ والطيبت للطيبين والطيبون للطيبت࣌ أولئك مبرءون مما يقولون࣌ لهم مغفرة ورزق كريم࣌', NULL, 352, 'local:warsh-text.json'),
  ('warsh-24-27', 'warsh', 24, 27, 'يَٰٓأَيُّهَا ࡰ۬لذِينَ ءَامَنُواْ لَا تَدْخُلُواْ بُيُوتاً غَيْرَ بُيُوتِكُمْ حَتَّىٰ تَسْتَانِسُواْ وَتُسَلِّمُواْ عَلَىٰٓ أَهْلِهَا࣌ ذَٰلِكُمْ خَيْرࣱ لَّكُمْ لَعَلَّكُمْ تَذَّكَّرُونَ࣌', 'يأيها ࡰلذين ءامنوا لا تدخلوا بيوتا غير بيوتكم حتى تستانسوا وتسلموا على أهلها࣌ ذلكم خير لكم لعلكم تذكرون࣌', NULL, 352, 'local:warsh-text.json'),
  ('warsh-24-28', 'warsh', 24, 28, 'فَإِن لَّمْ تَجِدُواْ فِيهَآ أَحَداࣰ فَلَا تَدْخُلُوهَا حَتَّىٰ يُوذَنَ لَكُمْ࣌ وَإِن قِيلَ لَكُمُ ࡲٜرْجِعُواْ فَارْجِعُواْ هُوَ أَزْكٜىٰ لَكُمْ࣌ وَاللَّهُ بِمَا تَعْمَلُونَ عَلِيمࣱ࣌', 'فإن لم تجدوا فيها أحدا فلا تدخلوها حتى يوذن لكم࣌ وإن قيل لكم ࡲرجعوا فارجعوا هو أزكى لكم࣌ والله بما تعملون عليم࣌', NULL, 353, 'local:warsh-text.json'),
  ('warsh-24-29', 'warsh', 24, 29, 'لَّيْسَ عَلَيْكُمْ جُنَاحٌ ࡰن تَدْخُلُواْ بُيُوتاً غَيْرَ مَسْكُونَةࣲ فِيهَا مَتَٰعࣱ لَّكُمْ࣌ وَاللَّهُ يَعْلَمُ مَا تُبْدُونَ وَمَا تَكْتُمُونَ࣌', 'ليس عليكم جناح ࡰن تدخلوا بيوتا غير مسكونة فيها متع لكم࣌ والله يعلم ما تبدون وما تكتمون࣌', NULL, 353, 'local:warsh-text.json'),
  ('warsh-24-30', 'warsh', 24, 30, '۞ قُل لِّلْمُومِنِينَ يَغُضُّواْ مِنَ ࡰبْصٜـٰرِهِمْ وَيَحْفَظُواْ فُرُوجَهُمْ ذَٰلِكَ أَزْكٜىٰ لَهُمُۥٓ࣌ إِنَّ ࡰ۬للَّهَ خَبِيرُۢ بِمَا يَصْنَعُونَ࣌', 'قل للمومنين يغضوا من ࡰبصرهم ويحفظوا فروجهم ذلك أزكى لهم࣌ إن ࡰلله خبير بما يصنعون࣌', NULL, 353, 'local:warsh-text.json'),
  ('warsh-24-31', 'warsh', 24, 31, 'وَقُل لِّلْمُومِنَٰتِ يَغْضُضْنَ مِنَ ࡰبْصٜـٰرِهِنَّ وَيَحْفَظْنَ فُرُوجَهُنَّ࣌ وَلَا يُبْدِينَ زِينَتَهُنَّ إِلَّا مَا ظَهَرَ مِنْهَا࣌ وَلْيَضْرِبْنَ بِخُمُرِهِنَّ عَلَىٰ جُيُوبِهِنَّ࣌ وَلَا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ أَوَ اٰبَآئِهِنَّ أَوَ اٰبَآءِ بُعُولَتِهِنَّ أَوَ ࡰبْنَآئِهِنَّ أَوَ ࡰبْنَآءِ بُعُولَتِهِنَّ أَوِ ࡴخْوَٰنِهِنَّ أَوْ بَنِےٓ إِخْوَٰنِهِنَّ أَوْ بَنِےٓ أَخَوَٰتِهِنَّ أَوْ نِسَآئِهِنَّ أَوْ مَا مَلَكَتَ ࡰيْمَٰنُهُنَّ أَوِ ࡴ۬لتَّٰبِعِينَ غَيْرِ أُوْلِے ࡴ۬لِارْبَةِ مِنَ ࡰ۬لرِّجَالِ أَوِ ࡴ۬لطِّفْلِ ࡴ۬لذِينَ لَمْ يَظْهَرُواْ عَلَىٰ عَوْرَٰتِ ࡴ۬لنِّسَآءِ࣌ وَلَا يَضْرِبْنَ بِأَرْجُلِهِنَّ لِيُعْلَمَ مَا يُخْفِينَ مِن زِينَتِهِنَّ࣌ وَتُوبُوٓاْ إِلَى ࡰ۬للَّهِ جَمِيعاً ࡰيُّهَ ࡰ۬لْمُومِنُونَ لَعَلَّكُمْ تُفْلِحُونَ࣌', 'وقل للمومنت يغضضن من ࡰبصرهن ويحفظن فروجهن࣌ ولا يبدين زينتهن إلا ما ظهر منها࣌ وليضربن بخمرهن على جيوبهن࣌ ولا يبدين زينتهن إلا لبعولتهن أو ابائهن أو اباء بعولتهن أو ࡰبنائهن أو ࡰبناء بعولتهن أو ࡴخونهن أو بنے إخونهن أو بنے أخوتهن أو نسائهن أو ما ملكت ࡰيمنهن أو ࡴلتبعين غير أولے ࡴلاربة من ࡰلرجال أو ࡴلطفل ࡴلذين لم يظهروا على عورت ࡴلنساء࣌ ولا يضربن بأرجلهن ليعلم ما يخفين من زينتهن࣌ وتوبوا إلى ࡰلله جميعا ࡰيه ࡰلمومنون لعلكم تفلحون࣌', NULL, 353, 'local:warsh-text.json'),
  ('warsh-24-32', 'warsh', 24, 32, 'وَأَنكِحُواْ ࡲ۬لَايَٰمٜىٰ مِنكُمْ وَالصَّٰلِحِينَ مِنْ عِبَادِكُمْ وَإِمَآئِكُمُۥٓ࣌ إِنْ يَّكُونُواْ فُقَرَآءَ يُغْنِهِمُ ࡲ۬للَّهُ مِن فَضْلِهِۦ࣌ وَاللَّهُ وَٰسِعٌ عَلِيمࣱ࣌', 'وأنكحوا ࡲلايمى منكم والصلحين من عبادكم وإمائكم࣌ إن يكونوا فقراء يغنهم ࡲلله من فضله࣌ والله وسع عليم࣌', NULL, 354, 'local:warsh-text.json'),
  ('warsh-24-33', 'warsh', 24, 33, 'وَلْيَسْتَعْفِفِ ࡴ۬لذِينَ لَا يَجِدُونَ نِكَاحاً حَتَّىٰ يُغْنِيَهُمُ ࡲ۬للَّهُ مِن فَضْلِهِۦ࣌ وَالذِينَ يَبْتَغُونَ ࡰ۬لْكِتَٰبَ مِمَّا مَلَكَتَ ࡰيْمَٰنُكُمْ فَكَاتِبُوهُمُۥٓ إِنْ عَلِمْتُمْ فِيهِمْ خَيْراࣰ࣌ وَءَاتُوهُم مِّن مَّالِ ࡴ۬للَّهِ ࡴ۬لذِےٓ ءَاتٜيٰكُمْ࣌ وَلَا تُكْرِهُواْ فَتَيَٰتِكُمْ عَلَى ࡰ۬لْبِغَآءِ انَ ࡰرَدْنَ تَحَصُّناࣰ لِّتَبْتَغُواْ عَرَضَ ࡰ۬لْحَيَوٰةِ ࡴ۬لدُّنْيٜا࣌ وَمَنْ يُّكْرِههُّنَّ فَإِنَّ ࡰ۬للَّهَ مِنۢ بَعْدِ إِكْرَٰهِهِنَّ غَفُورࣱ رَّحِيمࣱ࣌', 'وليستعفف ࡴلذين لا يجدون نكاحا حتى يغنيهم ࡲلله من فضله࣌ والذين يبتغون ࡰلكتب مما ملكت ࡰيمنكم فكاتبوهم إن علمتم فيهم خيرا࣌ وءاتوهم من مال ࡴلله ࡴلذے ءاتيكم࣌ ولا تكرهوا فتيتكم على ࡰلبغاء ان ࡰردن تحصنا لتبتغوا عرض ࡰلحيوة ࡴلدنيا࣌ ومن يكرههن فإن ࡰلله من بعد إكرههن غفور رحيم࣌', NULL, 354, 'local:warsh-text.json'),
  ('warsh-24-34', 'warsh', 24, 34, 'وَلَقَدَ ࡰنزَلْنَآ إِلَيْكُمُۥٓ ءَايَٰتࣲ مُّبَيَّنَٰتࣲ وَمَثَلاࣰ مِّنَ ࡰ۬لذِينَ خَلَوْاْ مِن قَبْلِكُمْ وَمَوْعِظَةࣰ لِّلْمُتَّقِينَ࣌', 'ولقد ࡰنزلنا إليكم ءايت مبينت ومثلا من ࡰلذين خلوا من قبلكم وموعظة للمتقين࣌', NULL, 354, 'local:warsh-text.json'),
  ('warsh-24-35', 'warsh', 24, 35, '۞ ࡰ۬للَّهُ نُورُ ࡲ۬لسَّمَٰوَٰتِ وَالَارْضِ࣌ مَثَلُ نُورِهِۦ كَمِشْكَوٰةࣲ فِيهَا مِصْبَاحٌ࣌ ࡴ۬لْمِصْبَاحُ فِے زُجَاجَةٍ࣌ ࡴ۬لزُّجَاجَةُ كَأَنَّهَا كَوْكَبࣱ دُرِّيࣱّ يُوقَدُ مِن شَجَرَةࣲ مُّبَٰرَكَةࣲ زَيْتُونَةࣲ لَّا شَرْقِيَّةࣲ وَلَا غَرْبِيَّةࣲ يَكَادُ زَيْتُهَا يُضِےٓءُ وَلَوْ لَمْ تَمْسَسْهُ نَارࣱ࣌ نُّورٌ عَلَىٰ نُورࣲ࣌ يَهْدِے ࡴ۬للَّهُ لِنُورِهِۦ مَنْ يَّشَآءُ࣌ وَيَضْرِبُ ࡲ۬للَّهُ ࡲ۬لَامْثَٰلَ لِلنَّاسِ࣌ وَاللَّهُ بِكُلِّ شَےْءٍ عَلِيمࣱ࣌', 'ࡰلله نور ࡲلسموت والارض࣌ مثل نوره كمشكوة فيها مصباح࣌ ࡴلمصباح فے زجاجة࣌ ࡴلزجاجة كأنها كوكب دري يوقد من شجرة مبركة زيتونة لا شرقية ولا غربية يكاد زيتها يضےء ولو لم تمسسه نار࣌ نور على نور࣌ يهدے ࡴلله لنوره من يشاء࣌ ويضرب ࡲلله ࡲلامثل للناس࣌ والله بكل شےء عليم࣌', NULL, 354, 'local:warsh-text.json'),
  ('warsh-24-36', 'warsh', 24, 36, 'فِے بُيُوتٍ ࡰذِنَ ࡰ۬للَّهُ أَن تُرْفَعَ وَيُذْكَرَ فِيهَا ࡰٜسْمُهُۥ يُسَبِّحُ لَهُۥ فِيهَا بِالْغُدُوِّ وَالَاصَالِ رِجَالࣱ لَّا تُلْهِيهِمْ تِجَٰرَةࣱ وَلَا بَيْعٌ عَن ذِكْرِ ࡴ۬للَّهِ وَإِقَامِ ࡴ۬لصَّلَوٰةِ وَإِيتَآءِ ࡴ۬لزَّكَوٰةِ࣌ يَخَافُونَ يَوْماࣰ تَتَقَلَّبُ فِيهِ ࡴ۬لْقُلُوبُ وَالَابْصَٰرُ', 'فے بيوت ࡰذن ࡰلله أن ترفع ويذكر فيها ࡰسمه يسبح له فيها بالغدو والاصال رجال لا تلهيهم تجرة ولا بيع عن ذكر ࡴلله وإقام ࡴلصلوة وإيتاء ࡴلزكوة࣌ يخافون يوما تتقلب فيه ࡴلقلوب والابصر', NULL, 354, 'local:warsh-text.json'),
  ('warsh-24-37', 'warsh', 24, 37, 'لِيَجْزِيَهُمُ ࡲ۬للَّهُ أَحْسَنَ مَا عَمِلُواْ وَيَزِيدَهُم مِّن فَضْلِهِۦ࣌ وَاللَّهُ يَرْزُقُ مَنْ يَّشَآءُ بِغَيْرِ حِسَابࣲ࣌', 'ليجزيهم ࡲلله أحسن ما عملوا ويزيدهم من فضله࣌ والله يرزق من يشاء بغير حساب࣌', NULL, 355, 'local:warsh-text.json'),
  ('warsh-24-38', 'warsh', 24, 38, 'وَالذِينَ كَفَرُوٓاْ أَعْمَٰلُهُمْ كَسَرَابِۢ بِقِيعَةࣲ يَحْسِبُهُ ࡲ۬لظَّمْـَٔانُ مَآءً حَتَّىٰٓ إِذَا جَآءَهُۥ لَمْ يَجِدْهُ شَيْـٔاࣰ وَوَجَدَ ࡰ۬للَّهَ عِندَهُۥ فَوَفّٜيٰهُ حِسَابَهُۥ࣌ وَاللَّهُ سَرِيعُ ࡲ۬لْحِسَابِ࣌', 'والذين كفروا أعملهم كسراب بقيعة يحسبه ࡲلظمان ماء حتى إذا جاءه لم يجده شيا ووجد ࡰلله عنده فوفيه حسابه࣌ والله سريع ࡲلحساب࣌', NULL, 355, 'local:warsh-text.json'),
  ('warsh-24-39', 'warsh', 24, 39, 'أَوْ كَظُلُمَٰتࣲ فِے بَحْرࣲ لُّجِّيࣲّ يَغْشٜيٰهُ مَوْجࣱ مِّن فَوْقِهِۦ مَوْجࣱ مِّن فَوْقِهِۦ سَحَابࣱ࣌ ظُلُمَٰتُۢ بَعْضُهَا فَوْقَ بَعْضٍ࣌ ࡴذَآ أَخْرَجَ يَدَهُۥ لَمْ يَكَدْ يَرٜيٰهَا࣌ وَمَن لَّمْ يَجْعَلِ ࡴ۬للَّهُ لَهُۥ نُوراࣰ فَمَا لَهُۥ مِن نُّورٍ࣌', 'أو كظلمت فے بحر لجي يغشيه موج من فوقه موج من فوقه سحاب࣌ ظلمت بعضها فوق بعض࣌ ࡴذا أخرج يده لم يكد يريها࣌ ومن لم يجعل ࡴلله له نورا فما له من نور࣌', NULL, 355, 'local:warsh-text.json'),
  ('warsh-24-40', 'warsh', 24, 40, 'ࡰلَمْ تَرَ أَنَّ ࡰ۬للَّهَ يُسَبِّحُ لَهُۥ مَن فِے ࡴ۬لسَّمَٰوَٰتِ وَالَارْضِ وَالطَّيْرُ صَٰٓفَّٰتࣲ࣌ كُلࣱّ قَدْ عَلِمَ صَلَاتَهُۥ وَتَسْبِيحَهُۥ࣌ وَاللَّهُ عَلِيمُۢ بِمَا يَفْعَلُونَ࣌', 'ࡰلم تر أن ࡰلله يسبح له من فے ࡴلسموت والارض والطير صفت࣌ كل قد علم صلاته وتسبيحه࣌ والله عليم بما يفعلون࣌', NULL, 355, 'local:warsh-text.json'),
  ('warsh-24-41', 'warsh', 24, 41, 'وَلِلهِ مُلْكُ ࡲ۬لسَّمَٰوَٰتِ وَالَارْضِ࣌ وَإِلَى ࡰ۬للَّهِ ࡴ۬لْمَصِيرُ࣌', 'ولله ملك ࡲلسموت والارض࣌ وإلى ࡰلله ࡴلمصير࣌', NULL, 355, 'local:warsh-text.json'),
  ('warsh-24-42', 'warsh', 24, 42, '۞ أَلَمْ تَرَ أَنَّ ࡰ۬للَّهَ يُزْجِے سَحَاباࣰ ثُمَّ يُوَ۬لِّفُ بَيْنَهُۥ ثُمَّ يَجْعَلُهُۥ رُكَاماࣰ فَتَرَى ࡰ۬لْوَدْقَ يَخْرُجُ مِنْ خِلَٰلِهِۦ࣌ وَيُنَزِّلُ مِنَ ࡰ۬لسَّمَآءِ مِن جِبَالࣲ فِيهَا مِنۢ بَرَدࣲ فَيُصِيبُ بِهِۦ مَنْ يَّشَآءُ وَيَصْرِفُهُۥ عَن مَّنْ يَّشَآءُ࣌ يَكَادُ سَنَا بَرْقِهِۦ يَذْهَبُ بِالَابْصٜـٰرِ࣌ يُقَلِّبُ ࡲ۬للَّهُ ࡲ۬ليْلَ وَالنَّهَارَ࣌ إِنَّ فِے ذَٰلِكَ لَعِبْرَةࣰ لِّأُوْلِے ࡴ۬لَابْصٜـٰرِ࣌', 'ألم تر أن ࡰلله يزجے سحابا ثم يولف بينه ثم يجعله ركاما فترى ࡰلودق يخرج من خلله࣌ وينزل من ࡰلسماء من جبال فيها من برد فيصيب به من يشاء ويصرفه عن من يشاء࣌ يكاد سنا برقه يذهب بالابصر࣌ يقلب ࡲلله ࡲليل والنهار࣌ إن فے ذلك لعبرة لأولے ࡴلابصر࣌', NULL, 355, 'local:warsh-text.json'),
  ('warsh-24-43', 'warsh', 24, 43, 'وَاللَّهُ خَلَقَ كُلَّ دَآبَّةࣲ مِّن مَّآءࣲ࣌ فَمِنْهُم مَّنْ يَّمْشِے عَلَىٰ بَطْنِهِۦ࣌ وَمِنْهُم مَّنْ يَّمْشِے عَلَىٰ رِجْلَيْنِ࣌ وَمِنْهُم مَّنْ يَّمْشِے عَلَىٰٓ أَرْبَعࣲ࣌ يَخْلُقُ ࡲ۬للَّهُ مَا يَشَآءُ࣌ ࡹِنَّ ࡰ۬للَّهَ عَلَىٰ كُلِّ شَےْءࣲ قَدِيرࣱ࣌', 'والله خلق كل دابة من ماء࣌ فمنهم من يمشے على بطنه࣌ ومنهم من يمشے على رجلين࣌ ومنهم من يمشے على أربع࣌ يخلق ࡲلله ما يشاء࣌ ࡹن ࡰلله على كل شےء قدير࣌', NULL, 356, 'local:warsh-text.json'),
  ('warsh-24-44', 'warsh', 24, 44, 'لَّقَدَ ࡰنزَلْنَآ ءَايَٰتࣲ مُّبَيَّنَٰتࣲ࣌ وَاللَّهُ يَهْدِے مَنْ يَّشَآءُ ࡹِلَىٰ صِرَٰطࣲ مُّسْتَقِيمࣲ࣌', 'لقد ࡰنزلنا ءايت مبينت࣌ والله يهدے من يشاء ࡹلى صرط مستقيم࣌', NULL, 356, 'local:warsh-text.json'),
  ('warsh-24-45', 'warsh', 24, 45, 'وَيَقُولُونَ ءَامَنَّا بِاللَّهِ وَبِالرَّسُولِ وَأَطَعْنَا ثُمَّ يَتَوَلّٜىٰ فَرِيقࣱ مِّنْهُم مِّنۢ بَعْدِ ذَٰلِكَ࣌ وَمَآ أُوْلَٰٓئِكَ بِالْمُومِنِينَ࣌', 'ويقولون ءامنا بالله وبالرسول وأطعنا ثم يتولى فريق منهم من بعد ذلك࣌ وما أولئك بالمومنين࣌', NULL, 356, 'local:warsh-text.json'),
  ('warsh-24-46', 'warsh', 24, 46, 'وَإِذَا دُعُوٓاْ إِلَى ࡰ۬للَّهِ وَرَسُولِهِۦ لِيَحْكُمَ بَيْنَهُمُۥٓ إِذَا فَرِيقࣱ مِّنْهُم مُّعْرِضُونَ࣌', 'وإذا دعوا إلى ࡰلله ورسوله ليحكم بينهم إذا فريق منهم معرضون࣌', NULL, 356, 'local:warsh-text.json'),
  ('warsh-24-47', 'warsh', 24, 47, 'وَإِنْ يَّكُن لَّهُمُ ࡲ۬لْحَقُّ يَاتُوٓاْ إِلَيْهِ مُذْعِنِينَ࣌', 'وإن يكن لهم ࡲلحق ياتوا إليه مذعنين࣌', NULL, 356, 'local:warsh-text.json'),
  ('warsh-24-48', 'warsh', 24, 48, 'أَفِے قُلُوبِهِم مَّرَضٌ ࡰمِ ࡴٜرْتَابُوٓاْ أَمْ يَخَافُونَ أَنْ يَّحِيفَ ࡰ۬للَّهُ عَلَيْهِمْ وَرَسُولُهُۥ࣌ بَلُ ࡳوْلَٰٓئِكَ هُمُ ࡲ۬لظَّٰلِمُونَ࣌', 'أفے قلوبهم مرض ࡰم ࡴرتابوا أم يخافون أن يحيف ࡰلله عليهم ورسوله࣌ بل ࡳولئك هم ࡲلظلمون࣌', NULL, 356, 'local:warsh-text.json'),
  ('warsh-24-49', 'warsh', 24, 49, 'إِنَّمَا كَانَ قَوْلَ ࡰ۬لْمُومِنِينَ إِذَا دُعُوٓاْ إِلَى ࡰ۬للَّهِ وَرَسُولِهِۦ لِيَحْكُمَ بَيْنَهُمُۥٓ أَنْ يَّقُولُواْ سَمِعْنَا وَأَطَعْنَا࣌ وَأُوْلَٰٓئِكَ هُمُ ࡲ۬لْمُفْلِحُونَ࣌', 'إنما كان قول ࡰلمومنين إذا دعوا إلى ࡰلله ورسوله ليحكم بينهم أن يقولوا سمعنا وأطعنا࣌ وأولئك هم ࡲلمفلحون࣌', NULL, 356, 'local:warsh-text.json'),
  ('warsh-24-50', 'warsh', 24, 50, 'وَمَنْ يُّطِعِ ࡴ۬للَّهَ وَرَسُولَهُۥ وَيَخْشَ ࡰ۬للَّهَ وَيَتَّقِهِۦ فَأُوْلَٰٓئِكَ هُمُ ࡲ۬لْفَآئِزُونَ࣌', 'ومن يطع ࡴلله ورسوله ويخش ࡰلله ويتقه فأولئك هم ࡲلفائزون࣌', NULL, 356, 'local:warsh-text.json'),
  ('warsh-24-51', 'warsh', 24, 51, '۞ وَأَقْسَمُواْ بِاللَّهِ جَهْدَ أَيْمَٰنِهِمْ لَئِنَ ࡰمَرْتَهُمْ لَيَخْرُجُنَّ࣌ قُل لَّا تُقْسِمُواْ࣌ طَاعَةࣱ مَّعْرُوفَةٌ࣌ ࡴنَّ ࡰ۬للَّهَ خَبِيرُۢ بِمَا تَعْمَلُونَ࣌', 'وأقسموا بالله جهد أيمنهم لئن ࡰمرتهم ليخرجن࣌ قل لا تقسموا࣌ طاعة معروفة࣌ ࡴن ࡰلله خبير بما تعملون࣌', NULL, 356, 'local:warsh-text.json'),
  ('warsh-24-52', 'warsh', 24, 52, 'قُلَ ࡰطِيعُواْ ࡲ۬للَّهَ وَأَطِيعُواْ ࡲ۬لرَّسُولَ࣌ فَإِن تَوَلَّوْاْ فَإِنَّمَا عَلَيْهِ مَا حُمِّلَ وَعَلَيْكُم مَّا حُمِّلْتُمْ࣌ وَإِن تُطِيعُوهُ تَهْتَدُواْ࣌ وَمَا عَلَى ࡰ۬لرَّسُولِ إِلَّا ࡰ۬لْبَلَٰغُ ࡲ۬لْمُبِينُ࣌', 'قل ࡰطيعوا ࡲلله وأطيعوا ࡲلرسول࣌ فإن تولوا فإنما عليه ما حمل وعليكم ما حملتم࣌ وإن تطيعوه تهتدوا࣌ وما على ࡰلرسول إلا ࡰلبلغ ࡲلمبين࣌', NULL, 357, 'local:warsh-text.json'),
  ('warsh-24-53', 'warsh', 24, 53, 'وَعَدَ ࡰ۬للَّهُ ࡲ۬لذِينَ ءَامَنُواْ مِنكُمْ وَعَمِلُواْ ࡲ۬لصَّٰلِحَٰتِ لَيَسْتَخْلِفَنَّهُمْ فِے ࡴ۬لَارْضِ كَمَا ࡰٜسْتَخْلَفَ ࡰ۬لذِينَ مِن قَبْلِهِمْ وَلَيُمَكِّنَنَّ لَهُمْ دِينَهُمُ ࡲ۬لذِے ࡴٜرْتَضٜىٰ لَهُمْ وَلَيُبَدِّلَنَّهُم مِّنۢ بَعْدِ خَوْفِهِمُۥٓ أَمْناࣰ࣌ يَعْبُدُونَنِے لَا يُشْرِكُونَ بِے شَيْـٔاࣰ࣌ وَمَن كَفَرَ بَعْدَ ذَٰلِكَ فَأُوْلَٰٓئِكَ هُمُ ࡲ۬لْفَٰسِقُونَ࣌', 'وعد ࡰلله ࡲلذين ءامنوا منكم وعملوا ࡲلصلحت ليستخلفنهم فے ࡴلارض كما ࡰستخلف ࡰلذين من قبلهم وليمكنن لهم دينهم ࡲلذے ࡴرتضى لهم وليبدلنهم من بعد خوفهم أمنا࣌ يعبدوننے لا يشركون بے شيا࣌ ومن كفر بعد ذلك فأولئك هم ࡲلفسقون࣌', NULL, 357, 'local:warsh-text.json'),
  ('warsh-24-54', 'warsh', 24, 54, 'وَأَقِيمُواْ ࡲ۬لصَّلَوٰةَ وَءَاتُواْ ࡲ۬لزَّكَوٰةَ࣌ وَأَطِيعُواْ ࡲ۬لرَّسُولَ لَعَلَّكُمْ تُرْحَمُونَ࣌', 'وأقيموا ࡲلصلوة وءاتوا ࡲلزكوة࣌ وأطيعوا ࡲلرسول لعلكم ترحمون࣌', NULL, 357, 'local:warsh-text.json'),
  ('warsh-24-55', 'warsh', 24, 55, 'لَا تَحْسِبَنَّ ࡰ۬لذِينَ كَفَرُواْ مُعْجِزِينَ فِے ࡴ۬لَارْضِ࣌ وَمَأْوٜيٰهُمُ ࡲ۬لنَّارُ࣌ وَلَبِيسَ ࡰ۬لْمَصِيرُ࣌', 'لا تحسبن ࡰلذين كفروا معجزين فے ࡴلارض࣌ ومأويهم ࡲلنار࣌ ولبيس ࡰلمصير࣌', NULL, 357, 'local:warsh-text.json'),
  ('warsh-24-56', 'warsh', 24, 56, 'يَٰٓأَيُّهَا ࡰ۬لذِينَ ءَامَنُواْ لِيَسْتَٰذِنكُمُ ࡲ۬لذِينَ مَلَكَتَ ࡰيْمَٰنُكُمْ وَالذِينَ لَمْ يَبْلُغُواْ ࡲ۬لْحُلُمَ مِنكُمْ ثَلَٰثَ مَرَّٰتࣲ مِّن قَبْلِ صَلَوٰةِ ࡴ۬لْفَجْرِ وَحِينَ تَضَعُونَ ثِيَابَكُم مِّنَ ࡰ۬لظَّهِيرَةِ وَمِنۢ بَعْدِ صَلَوٰةِ ࡴ۬لْعِشَآءِ࣌ ثَلَٰثُ عَوْرَٰتࣲ لَّكُمْ࣌ لَيْسَ عَلَيْكُمْ وَلَا عَلَيْهِمْ جُنَاحُۢ بَعْدَهُنَّ࣌ طَوَّٰفُونَ عَلَيْكُم࣌ بَعْضُكُمْ عَلَىٰ بَعْضࣲ࣌ كَذَٰلِكَ يُبَيِّنُ ࡲ۬للَّهُ لَكُمُ ࡲ۬لَايَٰتِ࣌ وَاللَّهُ عَلِيمٌ حَكِيمࣱ࣌', 'يأيها ࡰلذين ءامنوا ليستذنكم ࡲلذين ملكت ࡰيمنكم والذين لم يبلغوا ࡲلحلم منكم ثلث مرت من قبل صلوة ࡴلفجر وحين تضعون ثيابكم من ࡰلظهيرة ومن بعد صلوة ࡴلعشاء࣌ ثلث عورت لكم࣌ ليس عليكم ولا عليهم جناح بعدهن࣌ طوفون عليكم࣌ بعضكم على بعض࣌ كذلك يبين ࡲلله لكم ࡲلايت࣌ والله عليم حكيم࣌', NULL, 357, 'local:warsh-text.json'),
  ('warsh-24-57', 'warsh', 24, 57, 'وَإِذَا بَلَغَ ࡰ۬لَاطْفَٰلُ مِنكُمُ ࡲ۬لْحُلُمَ فَلْيَسْتَٰذِنُواْ كَمَا ࡰٜسْتَٰذَنَ ࡰ۬لذِينَ مِن قَبْلِهِمْ࣌ كَذَٰلِكَ يُبَيِّنُ ࡲ۬للَّهُ لَكُمُۥٓ ءَايَٰتِهِۦ࣌ وَاللَّهُ عَلِيمٌ حَكِيمࣱ࣌', 'وإذا بلغ ࡰلاطفل منكم ࡲلحلم فليستذنوا كما ࡰستذن ࡰلذين من قبلهم࣌ كذلك يبين ࡲلله لكم ءايته࣌ والله عليم حكيم࣌', NULL, 358, 'local:warsh-text.json'),
  ('warsh-24-58', 'warsh', 24, 58, '۞ وَالْقَوَٰعِدُ مِنَ ࡰ۬لنِّسَآءِ ࡴ۬لتِے لَا يَرْجُونَ نِكَاحاࣰ فَلَيْسَ عَلَيْهِنَّ جُنَاحٌ ࡰنْ يَّضَعْنَ ثِيَابَهُنَّ غَيْرَ مُتَبَرِّجَٰتِۢ بِزِينَةࣲ࣌ وَأَنْ يَّسْتَعْفِفْنَ خَيْرࣱ لَّهُنَّ࣌ وَاللَّهُ سَمِيعٌ عَلِيمࣱ࣌', 'والقوعد من ࡰلنساء ࡴلتے لا يرجون نكاحا فليس عليهن جناح ࡰن يضعن ثيابهن غير متبرجت بزينة࣌ وأن يستعففن خير لهن࣌ والله سميع عليم࣌', NULL, 358, 'local:warsh-text.json'),
  ('warsh-24-59', 'warsh', 24, 59, 'لَّيْسَ عَلَى ࡰ۬لَاعْمٜىٰ حَرَجࣱ وَلَا عَلَى ࡰ۬لَاعْرَجِ حَرَجࣱ وَلَا عَلَى ࡰ۬لْمَرِيضِ حَرَجࣱ وَلَا عَلَىٰٓ أَنفُسِكُمُۥٓ أَن تَاكُلُواْ مِنۢ بُيُوتِكُمُۥٓ أَوْ بُيُوتِ ءَابَآئِكُمُۥٓ أَوْ بُيُوتِ أُمَّهَٰتِكُمُۥٓ أَوْ بُيُوتِ إِخْوَٰنِكُمُۥٓ أَوْ بُيُوتِ أَخَوَٰتِكُمُۥٓ أَوْ بُيُوتِ أَعْمَٰمِكُمُۥٓ أَوْ بُيُوتِ عَمَّٰتِكُمُۥٓ أَوْ بُيُوتِ أَخْوَٰلِكُمُۥٓ أَوْ بُيُوتِ خَٰلَٰتِكُمُۥٓ أَوْ مَا مَلَكْتُم مَّفَاتِحَهُۥٓ أَوْ صَدِيقِكُمْ࣌ لَيْسَ عَلَيْكُمْ جُنَاحٌ ࡰن تَاكُلُواْ جَمِيعاً ࡰوَ ࡰشْتَاتاࣰ࣌ فَإِذَا دَخَلْتُم بُيُوتاࣰ فَسَلِّمُواْ عَلَىٰٓ أَنفُسِكُمْ تَحِيَّةࣰ مِّنْ عِندِ ࡴ۬للَّهِ مُبَٰرَكَةࣰ طَيِّبَةࣰ࣌ كَذَٰلِكَ يُبَيِّنُ ࡲ۬للَّهُ لَكُمُ ࡲ۬لَايَٰتِ لَعَلَّكُمْ تَعْقِلُونَ࣌', 'ليس على ࡰلاعمى حرج ولا على ࡰلاعرج حرج ولا على ࡰلمريض حرج ولا على أنفسكم أن تاكلوا من بيوتكم أو بيوت ءابائكم أو بيوت أمهتكم أو بيوت إخونكم أو بيوت أخوتكم أو بيوت أعممكم أو بيوت عمتكم أو بيوت أخولكم أو بيوت خلتكم أو ما ملكتم مفاتحه أو صديقكم࣌ ليس عليكم جناح ࡰن تاكلوا جميعا ࡰو ࡰشتاتا࣌ فإذا دخلتم بيوتا فسلموا على أنفسكم تحية من عند ࡴلله مبركة طيبة࣌ كذلك يبين ࡲلله لكم ࡲلايت لعلكم تعقلون࣌', NULL, 358, 'local:warsh-text.json'),
  ('warsh-24-60', 'warsh', 24, 60, 'إِنَّمَا ࡰ۬لْمُومِنُونَ ࡰ۬لذِينَ ءَامَنُواْ بِاللَّهِ وَرَسُولِهِۦ وَإِذَا كَانُواْ مَعَهُۥ عَلَىٰٓ أَمْرࣲ جَامِعࣲ لَّمْ يَذْهَبُواْ حَتَّىٰ يَسْتَٰذِنُوهُ࣌ إِنَّ ࡰ۬لذِينَ يَسْتَٰذِنُونَكَ أُوْلَٰٓئِكَ ࡰ۬لذِينَ يُومِنُونَ بِاللَّهِ وَرَسُولِهِۦ࣌ فَإِذَا ࡰٜسْتَٰذَنُوكَ لِبَعْضِ شَأْنِهِمْ فَاذَن لِّمَن شِئْتَ مِنْهُمْ وَاسْتَغْفِرْ لَهُمُ ࡲ۬للَّهَ࣌ إِنَّ ࡰ۬للَّهَ غَفُورࣱ رَّحِيمࣱ࣌', 'إنما ࡰلمومنون ࡰلذين ءامنوا بالله ورسوله وإذا كانوا معه على أمر جامع لم يذهبوا حتى يستذنوه࣌ إن ࡰلذين يستذنونك أولئك ࡰلذين يومنون بالله ورسوله࣌ فإذا ࡰستذنوك لبعض شأنهم فاذن لمن شئت منهم واستغفر لهم ࡲلله࣌ إن ࡰلله غفور رحيم࣌', NULL, 359, 'local:warsh-text.json'),
  ('warsh-24-61', 'warsh', 24, 61, '۞ لَّا تَجْعَلُواْ دُعَآءَ ࡰ۬لرَّسُولِ بَيْنَكُمْ كَدُعَآءِ بَعْضِكُم بَعْضاࣰ࣌ قَدْ يَعْلَمُ ࡲ۬للَّهُ ࡲ۬لذِينَ يَتَسَلَّلُونَ مِنكُمْ لِوَاذاࣰ࣌ فَلْيَحْذَرِ ࡴ۬لذِينَ يُخَالِفُونَ عَنَ ࡰمْرِهِۦٓ أَن تُصِيبَهُمْ فِتْنَةٌ ࡰوْ يُصِيبَهُمْ عَذَابٌ ࡰلِيمٌ࣌', 'لا تجعلوا دعاء ࡰلرسول بينكم كدعاء بعضكم بعضا࣌ قد يعلم ࡲلله ࡲلذين يتسللون منكم لواذا࣌ فليحذر ࡴلذين يخالفون عن ࡰمره أن تصيبهم فتنة ࡰو يصيبهم عذاب ࡰليم࣌', NULL, 359, 'local:warsh-text.json'),
  ('warsh-24-62', 'warsh', 24, 62, 'ࡰلَآ إِنَّ لِلهِ مَا فِے ࡴ۬لسَّمَٰوَٰتِ وَالَارْضِ࣌ قَدْ يَعْلَمُ مَآ أَنتُمْ عَلَيْهِ࣌ وَيَوْمَ يُرْجَعُونَ إِلَيْهِ فَيُنَبِّئُهُم بِمَا عَمِلُواْ࣌ وَاللَّهُ بِكُلِّ شَےْءٍ عَلِيمࣱ࣌', 'ࡰلا إن لله ما فے ࡴلسموت والارض࣌ قد يعلم ما أنتم عليه࣌ ويوم يرجعون إليه فينبئهم بما عملوا࣌ والله بكل شےء عليم࣌', NULL, 359, 'local:warsh-text.json'),
  ('warsh-25-1', 'warsh', 25, 1, 'تَبَٰرَكَ ࡰ۬لذِے نَزَّلَ ࡰ۬لْفُرْقَانَ عَلَىٰ عَبْدِهِۦ لِيَكُونَ لِلْعَٰلَمِينَ نَذِيراً࣌', 'تبرك ࡰلذے نزل ࡰلفرقان على عبده ليكون للعلمين نذيرا࣌', NULL, 359, 'local:warsh-text.json'),
  ('warsh-25-2', 'warsh', 25, 2, 'ࡴ۬لذِے لَهُۥ مُلْكُ ࡲ۬لسَّمَٰوَٰتِ وَالَارْضِ وَلَمْ يَتَّخِذْ وَلَداࣰ وَلَمْ يَكُن لَّهُۥ شَرِيكࣱ فِے ࡴ۬لْمُلْكِ࣌ وَخَلَقَ كُلَّ شَےْءࣲ فَقَدَّرَهُۥ تَقْدِيراࣰ࣌', 'ࡴلذے له ملك ࡲلسموت والارض ولم يتخذ ولدا ولم يكن له شريك فے ࡴلملك࣌ وخلق كل شےء فقدره تقديرا࣌', NULL, 359, 'local:warsh-text.json'),
  ('warsh-25-3', 'warsh', 25, 3, 'وَاتَّخَذُواْ مِن دُونِهِۦٓ ءَالِهَةࣰ لَّا يَخْلُقُونَ شَيْـٔاࣰ وَهُمْ يُخْلَقُونَ وَلَا يَمْلِكُونَ لِأَنفُسِهِمْ ضَرّاࣰ وَلَا نَفْعاࣰ وَلَا يَمْلِكُونَ مَوْتاࣰ وَلَا حَيَوٰةࣰ وَلَا نُشُوراࣰ࣌', 'واتخذوا من دونه ءالهة لا يخلقون شيا وهم يخلقون ولا يملكون لأنفسهم ضرا ولا نفعا ولا يملكون موتا ولا حيوة ولا نشورا࣌', NULL, 360, 'local:warsh-text.json'),
  ('warsh-25-4', 'warsh', 25, 4, 'وَقَالَ ࡰ۬لذِينَ كَفَرُوٓاْ إِنْ هَٰذَآ إِلَّآ إِفْكٌ ࡴٜفْتَرٜيٰهُ وَأَعَانَهُۥ عَلَيْهِ قَوْمٌ اٰخَرُونَ࣌ فَقَدْ جَآءُو ظُلْماࣰ وَزُوراࣰ', 'وقال ࡰلذين كفروا إن هذا إلا إفك ࡴفتريه وأعانه عليه قوم اخرون࣌ فقد جاءو ظلما وزورا', NULL, 360, 'local:warsh-text.json'),
  ('warsh-25-5', 'warsh', 25, 5, 'وَقَالُوٓاْ أَسَٰطِيرُ ࡲ۬لَاوَّلِينَ ࡰٜكْتَتَبَهَا فَهِيَ تُمْلٜىٰ عَلَيْهِ بُكْرَةࣰ وَأَصِيلاࣰ࣌', 'وقالوا أسطير ࡲلاولين ࡰكتتبها فهي تملى عليه بكرة وأصيلا࣌', NULL, 360, 'local:warsh-text.json'),
  ('warsh-25-6', 'warsh', 25, 6, 'قُلَ ࡰنزَلَهُ ࡲ۬لذِے يَعْلَمُ ࡲ۬لسِّرَّ فِے ࡴ۬لسَّمَٰوَٰتِ وَالَارْضِ࣌ إِنَّهُۥ كَانَ غَفُوراࣰ رَّحِيماࣰ࣌', 'قل ࡰنزله ࡲلذے يعلم ࡲلسر فے ࡴلسموت والارض࣌ إنه كان غفورا رحيما࣌', NULL, 360, 'local:warsh-text.json'),
  ('warsh-25-7', 'warsh', 25, 7, 'وَقَالُواْ مَالِ هَٰذَا ࡰ۬لرَّسُولِ يَاكُلُ ࡲ۬لطَّعَامَ وَيَمْشِے فِے ࡴ۬لَاسْوَاقِ لَوْلَآ أُنزِلَ إِلَيْهِ مَلَكࣱ فَيَكُونَ مَعَهُۥ نَذِيراً', 'وقالوا مال هذا ࡰلرسول ياكل ࡲلطعام ويمشے فے ࡴلاسواق لولا أنزل إليه ملك فيكون معه نذيرا', NULL, 360, 'local:warsh-text.json'),
  ('warsh-25-8', 'warsh', 25, 8, 'ࡰوْ يُلْقٜىٰٓ إِلَيْهِ كَنزٌ ࡰوْ تَكُونُ لَهُۥ جَنَّةࣱ يَاكُلُ مِنْهَا࣌ وَقَالَ ࡰ۬لظَّٰلِمُونَ إِن تَتَّبِعُونَ إِلَّا رَجُلاࣰ مَّسْحُوراً࣌', 'ࡰو يلقى إليه كنز ࡰو تكون له جنة ياكل منها࣌ وقال ࡰلظلمون إن تتبعون إلا رجلا مسحورا࣌', NULL, 360, 'local:warsh-text.json'),
  ('warsh-25-9', 'warsh', 25, 9, 'ࡲ࢈نظُرْ كَيْفَ ضَرَبُواْ لَكَ ࡰ۬لَامْثَٰلَ فَضَلُّواْ فَلَا يَسْتَطِيعُونَ سَبِيلاࣰ࣌', 'ࡲ࢈نظر كيف ضربوا لك ࡰلامثل فضلوا فلا يستطيعون سبيلا࣌', NULL, 360, 'local:warsh-text.json'),
  ('warsh-25-10', 'warsh', 25, 10, '۞ تَبَٰرَكَ ࡰ۬لذِےٓ إِن شَآءَ جَعَلَ لَكَ خَيْراࣰ مِّن ذَٰلِكَ جَنَّٰتࣲ تَجْرِے مِن تَحْتِهَا ࡰ۬لَانْهَٰرُ وَيَجْعَل لَّكَ قُصُوراَۢ࣌', 'تبرك ࡰلذے إن شاء جعل لك خيرا من ذلك جنت تجرے من تحتها ࡰلانهر ويجعل لك قصورا࣌', NULL, 360, 'local:warsh-text.json'),
  ('warsh-25-11', 'warsh', 25, 11, 'بَلْ كَذَّبُواْ بِالسَّاعَةِ࣌ وَأَعْتَدْنَا لِمَن كَذَّبَ بِالسَّاعَةِ سَعِيراً', 'بل كذبوا بالساعة࣌ وأعتدنا لمن كذب بالساعة سعيرا', NULL, 360, 'local:warsh-text.json'),
  ('warsh-25-12', 'warsh', 25, 12, 'ࡴذَا رَأَتْهُم مِّن مَّكَانِۢ بَعِيدࣲ سَمِعُواْ لَهَا تَغَيُّظاࣰ وَزَفِيراࣰ࣌', 'ࡴذا رأتهم من مكان بعيد سمعوا لها تغيظا وزفيرا࣌', NULL, 361, 'local:warsh-text.json'),
  ('warsh-25-13', 'warsh', 25, 13, 'وَإِذَآ أُلْقُواْ مِنْهَا مَكَاناࣰ ضَيِّقاࣰ مُّقَرَّنِينَ دَعَوْاْ هُنَالِكَ ثُبُوراࣰ࣌', 'وإذا ألقوا منها مكانا ضيقا مقرنين دعوا هنالك ثبورا࣌', NULL, 361, 'local:warsh-text.json'),
  ('warsh-25-14', 'warsh', 25, 14, 'لَّا تَدْعُواْ ࡲ۬لْيَوْمَ ثُبُوراࣰ وَٰحِداࣰ وَادْعُواْ ثُبُوراࣰ كَثِيراࣰ࣌', 'لا تدعوا ࡲليوم ثبورا وحدا وادعوا ثبورا كثيرا࣌', NULL, 361, 'local:warsh-text.json'),
  ('warsh-25-15', 'warsh', 25, 15, 'قُلَ ࡰذَٰلِكَ خَيْرٌ ࡰمْ جَنَّةُ ࡲ۬لْخُلْدِ ࡴ۬لتِے وُعِدَ ࡰ۬لْمُتَّقُونَ࣌ كَانَتْ لَهُمْ جَزَآءࣰ وَمَصِيراࣰ࣌', 'قل ࡰذلك خير ࡰم جنة ࡲلخلد ࡴلتے وعد ࡰلمتقون࣌ كانت لهم جزاء ومصيرا࣌', NULL, 361, 'local:warsh-text.json'),
  ('warsh-25-16', 'warsh', 25, 16, 'لَّهُمْ فِيهَا مَا يَشَآءُونَ خَٰلِدِينَ࣌ كَانَ عَلَىٰ رَبِّكَ وَعْداࣰ مَّسْـُٔولاࣰ࣌', 'لهم فيها ما يشاءون خلدين࣌ كان على ربك وعدا مسولا࣌', NULL, 361, 'local:warsh-text.json'),
  ('warsh-25-17', 'warsh', 25, 17, 'وَيَوْمَ نَحْشُرُهُمْ وَمَا يَعْبُدُونَ مِن دُونِ ࡴ۬للَّهِ فَيَقُولُ ءَآنتُمُۥٓ أَضْلَلْتُمْ عِبَادِے هَٰٓؤُلَآءِ ࡶَمْ هُمْ ضَلُّواْ ࡲ۬لسَّبِيلَ࣌', 'ويوم نحشرهم وما يعبدون من دون ࡴلله فيقول ءانتم أضللتم عبادے هؤلاء ࡶم هم ضلوا ࡲلسبيل࣌', NULL, 361, 'local:warsh-text.json'),
  ('warsh-25-18', 'warsh', 25, 18, 'قَالُواْ سُبْحَٰنَكَ مَا كَانَ يَنۢبَغِے لَنَآ أَن نَّتَّخِذَ مِن دُونِكَ مِنَ ࡰوْلِيَآءَ࣌ وَلَٰكِن مَّتَّعْتَهُمْ وَءَابَآءَهُمْ حَتَّىٰ نَسُواْ ࡲ۬لذِّكْرَ وَكَانُواْ قَوْماَۢ بُوراࣰ࣌', 'قالوا سبحنك ما كان ينبغے لنا أن نتخذ من دونك من ࡰولياء࣌ ولكن متعتهم وءاباءهم حتى نسوا ࡲلذكر وكانوا قوما بورا࣌', NULL, 361, 'local:warsh-text.json'),
  ('warsh-25-19', 'warsh', 25, 19, 'فَقَدْ كَذَّبُوكُم بِمَا تَقُولُونَ فَمَا يَسْتَطِيعُونَ صَرْفاࣰ وَلَا نَصْراࣰ࣌ وَمَنْ يَّظْلِم مِّنكُمْ نُذِقْهُ عَذَاباࣰ كَبِيراࣰ࣌', 'فقد كذبوكم بما تقولون فما يستطيعون صرفا ولا نصرا࣌ ومن يظلم منكم نذقه عذابا كبيرا࣌', NULL, 361, 'local:warsh-text.json'),
  ('warsh-25-20', 'warsh', 25, 20, 'وَمَآ أَرْسَلْنَا قَبْلَكَ مِنَ ࡰ۬لْمُرْسَلِينَ إِلَّآ إِنَّهُمْ لَيَاكُلُونَ ࡰ۬لطَّعَامَ وَيَمْشُونَ فِے ࡴ۬لَاسْوَاقِ࣌ وَجَعَلْنَا بَعْضَكُمْ لِبَعْضࣲ فِتْنَةً࣌ ࡰتَصْبِرُونَ࣌ وَكَانَ رَبُّكَ بَصِيراࣰ࣌', 'وما أرسلنا قبلك من ࡰلمرسلين إلا إنهم لياكلون ࡰلطعام ويمشون فے ࡴلاسواق࣌ وجعلنا بعضكم لبعض فتنة࣌ ࡰتصبرون࣌ وكان ربك بصيرا࣌', NULL, 361, 'local:warsh-text.json'),
  ('warsh-25-21', 'warsh', 25, 21, '۞ وَقَالَ ࡰ۬لذِينَ لَا يَرْجُونَ لِقَآءَنَا لَوْلَآ أُنزِلَ عَلَيْنَا ࡰ۬لْمَلَٰٓئِكَةُ أَوْ نَرٜىٰ رَبَّنَا࣌ لَقَدِ ࡴٜسْتَكْبَرُواْ فِےٓ أَنفُسِهِمْ وَعَتَوْ عُتُوّاࣰ كَبِيراࣰ࣌', 'وقال ࡰلذين لا يرجون لقاءنا لولا أنزل علينا ࡰلملئكة أو نرى ربنا࣌ لقد ࡴستكبروا فے أنفسهم وعتو عتوا كبيرا࣌', NULL, 362, 'local:warsh-text.json'),
  ('warsh-25-22', 'warsh', 25, 22, 'يَوْمَ يَرَوْنَ ࡰ۬لْمَلَٰٓئِكَةَ لَا بُشْرٜىٰ يَوْمَئِذࣲ لِّلْمُجْرِمِينَ࣌ وَيَقُولُونَ حِجْراࣰ࣌ مَّحْجُوراࣰ࣌', 'يوم يرون ࡰلملئكة لا بشرى يومئذ للمجرمين࣌ ويقولون حجرا࣌ محجورا࣌', NULL, 362, 'local:warsh-text.json'),
  ('warsh-25-23', 'warsh', 25, 23, 'وَقَدِمْنَآ إِلَىٰ مَا عَمِلُواْ مِنْ عَمَلࣲ فَجَعَلْنَٰهُ هَبَآءࣰ مَّنثُوراً࣌', 'وقدمنا إلى ما عملوا من عمل فجعلنه هباء منثورا࣌', NULL, 362, 'local:warsh-text.json'),
  ('warsh-25-24', 'warsh', 25, 24, 'ࡰصْحَٰبُ ࡲ۬لْجَنَّةِ يَوْمَئِذٍ خَيْرࣱ مُّسْتَقَرّاࣰ وَأَحْسَنُ مَقِيلاࣰ࣌', 'ࡰصحب ࡲلجنة يومئذ خير مستقرا وأحسن مقيلا࣌', NULL, 362, 'local:warsh-text.json'),
  ('warsh-25-25', 'warsh', 25, 25, 'وَيَوْمَ تَشَّقَّقُ ࡲ۬لسَّمَآءُ بِالْغَمَٰمِ وَنُزِّلَ ࡰ۬لْمَلَٰٓئِكَةُ تَنزِيلاً࣌', 'ويوم تشقق ࡲلسماء بالغمم ونزل ࡰلملئكة تنزيلا࣌', NULL, 362, 'local:warsh-text.json'),
  ('warsh-25-26', 'warsh', 25, 26, 'ࡴ۬لْمُلْكُ يَوْمَئِذٍ ࡴ۬لْحَقُّ لِلرَّحْمَٰنِ࣌ وَكَانَ يَوْماً عَلَى ࡰ۬لْكٜـٰفِرِينَ عَسِيراࣰ࣌', 'ࡴلملك يومئذ ࡴلحق للرحمن࣌ وكان يوما على ࡰلكفرين عسيرا࣌', NULL, 362, 'local:warsh-text.json'),
  ('warsh-25-27', 'warsh', 25, 27, 'وَيَوْمَ يَعَضُّ ࡲ۬لظَّالِمُ عَلَىٰ يَدَيْهِ يَقُولُ يَٰلَيْتَنِے ࡴٜتَّخَذتُّ مَعَ ࡰ۬لرَّسُولِ سَبِيلاࣰ', 'ويوم يعض ࡲلظالم على يديه يقول يليتنے ࡴتخذت مع ࡰلرسول سبيلا', NULL, 362, 'local:warsh-text.json'),
  ('warsh-25-28', 'warsh', 25, 28, 'يَٰوَيْلَتٜىٰ لَيْتَنِے لَمَ ࡰتَّخِذْ فُلَٰناً خَلِيلاࣰ', 'يويلتى ليتنے لم ࡰتخذ فلنا خليلا', NULL, 362, 'local:warsh-text.json'),
  ('warsh-25-29', 'warsh', 25, 29, 'لَّقَدَ ࡰضَلَّنِے عَنِ ࡴ۬لذِّكْرِ بَعْدَ إِذْ جَآءَنِے࣌ وَكَانَ ࡰ۬لشَّيْطَٰنُ لِلِانسَٰنِ خَذُولاࣰ࣌', 'لقد ࡰضلنے عن ࡴلذكر بعد إذ جاءنے࣌ وكان ࡰلشيطن للانسن خذولا࣌', NULL, 362, 'local:warsh-text.json'),
  ('warsh-25-30', 'warsh', 25, 30, 'وَقَالَ ࡰ۬لرَّسُولُ يَٰرَبِّ إِنَّ قَوْمِيَ ࡰٜتَّخَذُواْ هَٰذَا ࡰ۬لْقُرْءَانَ مَهْجُوراࣰ࣌', 'وقال ࡰلرسول يرب إن قومي ࡰتخذوا هذا ࡰلقرءان مهجورا࣌', NULL, 362, 'local:warsh-text.json'),
  ('warsh-25-31', 'warsh', 25, 31, 'وَكَذَٰلِكَ جَعَلْنَا لِكُلِّ نَبِےٓءٍ عَدُوّاࣰ مِّنَ ࡰ۬لْمُجْرِمِينَ࣌ وَكَفٜىٰ بِرَبِّكَ هَادِياࣰ وَنَصِيراࣰ࣌', 'وكذلك جعلنا لكل نبےء عدوا من ࡰلمجرمين࣌ وكفى بربك هاديا ونصيرا࣌', NULL, 362, 'local:warsh-text.json'),
  ('warsh-25-32', 'warsh', 25, 32, 'وَقَالَ ࡰ۬لذِينَ كَفَرُواْ لَوْلَا نُزِّلَ عَلَيْهِ ࡴ۬لْقُرْءَانُ جُمْلَةࣰ وَٰحِدَةࣰ࣌ كَذَٰلِكَ لِنُثَبِّتَ بِهِۦ فُؤَادَكَ࣌ وَرَتَّلْنَٰهُ تَرْتِيلاࣰ࣌', 'وقال ࡰلذين كفروا لولا نزل عليه ࡴلقرءان جملة وحدة࣌ كذلك لنثبت به فؤادك࣌ ورتلنه ترتيلا࣌', NULL, 362, 'local:warsh-text.json'),
  ('warsh-25-33', 'warsh', 25, 33, 'وَلَا يَاتُونَكَ بِمَثَلٍ ࡴلَّا جِئْنَٰكَ بِالْحَقِّ وَأَحْسَنَ تَفْسِيراً࣌', 'ولا ياتونك بمثل ࡴلا جئنك بالحق وأحسن تفسيرا࣌', NULL, 363, 'local:warsh-text.json'),
  ('warsh-25-34', 'warsh', 25, 34, 'ࡴ۬لذِينَ يُحْشَرُونَ عَلَىٰ وُجُوهِهِمُۥٓ إِلَىٰ جَهَنَّمَ أُوْلَٰٓئِكَ شَرࣱّ مَّكَاناࣰ وَأَضَلُّ سَبِيلاࣰ࣌', 'ࡴلذين يحشرون على وجوههم إلى جهنم أولئك شر مكانا وأضل سبيلا࣌', NULL, 363, 'local:warsh-text.json'),
  ('warsh-25-35', 'warsh', 25, 35, '۞ وَلَقَدَ اٰتَيْنَا مُوسَى ࡰ۬لْكِتَٰبَ وَجَعَلْنَا مَعَهُۥٓ أَخَاهُ هَٰرُونَ وَزِيراࣰ࣌', 'ولقد اتينا موسى ࡰلكتب وجعلنا معه أخاه هرون وزيرا࣌', NULL, 363, 'local:warsh-text.json'),
  ('warsh-25-36', 'warsh', 25, 36, 'فَقُلْنَا ࡰٜذْهَبَآ إِلَى ࡰ۬لْقَوْمِ ࡴ۬لذِينَ كَذَّبُواْ بِـَٔايَٰتِنَا࣌ فَدَمَّرْنَٰهُمْ تَدْمِيراࣰ࣌', 'فقلنا ࡰذهبا إلى ࡰلقوم ࡴلذين كذبوا بايتنا࣌ فدمرنهم تدميرا࣌', NULL, 363, 'local:warsh-text.json'),
  ('warsh-25-37', 'warsh', 25, 37, 'وَقَوْمَ نُوحࣲ لَّمَّا كَذَّبُواْ ࡲ۬لرُّسُلَ أَغْرَقْنَٰهُمْ وَجَعَلْنَٰهُمْ لِلنَّاسِ ءَايَةࣰ࣌ وَأَعْتَدْنَا لِلظَّٰلِمِينَ عَذَاباً ࡰلِيماࣰ࣌', 'وقوم نوح لما كذبوا ࡲلرسل أغرقنهم وجعلنهم للناس ءاية࣌ وأعتدنا للظلمين عذابا ࡰليما࣌', NULL, 363, 'local:warsh-text.json'),
  ('warsh-25-38', 'warsh', 25, 38, 'وَعَاداࣰ وَثَمُوداࣰ وَأَصْحَٰبَ ࡰ۬لرَّسِّ وَقُرُوناَۢ بَيْنَ ذَٰلِكَ كَثِيراࣰ࣌', 'وعادا وثمودا وأصحب ࡰلرس وقرونا بين ذلك كثيرا࣌', NULL, 363, 'local:warsh-text.json'),
  ('warsh-25-39', 'warsh', 25, 39, 'وَكُلّاࣰ ضَرَبْنَا لَهُ ࡲ۬لَامْثَٰلَ࣌ وَكُلّاࣰ تَبَّرْنَا تَتْبِيراࣰ࣌', 'وكلا ضربنا له ࡲلامثل࣌ وكلا تبرنا تتبيرا࣌', NULL, 363, 'local:warsh-text.json'),
  ('warsh-25-40', 'warsh', 25, 40, 'وَلَقَدَ ࡰتَوْاْ عَلَى ࡰ۬لْقَرْيَةِ ࡴ۬لتِےٓ أُمْطِرَتْ مَطَرَ ࡰ۬لسَّوْءِ࣌ ࡶَفَلَمْ يَكُونُواْ يَرَوْنَهَا࣌ بَلْ كَانُواْ لَا يَرْجُونَ نُشُوراࣰ࣌', 'ولقد ࡰتوا على ࡰلقرية ࡴلتے أمطرت مطر ࡰلسوء࣌ ࡶفلم يكونوا يرونها࣌ بل كانوا لا يرجون نشورا࣌', NULL, 363, 'local:warsh-text.json'),
  ('warsh-25-41', 'warsh', 25, 41, 'وَإِذَا رَأَوْكَ إِنْ يَّتَّخِذُونَكَ إِلَّا هُزُؤاً࣌ ࡰهَٰذَا ࡰ۬لذِے بَعَثَ ࡰ۬للَّهُ رَسُولاً', 'وإذا رأوك إن يتخذونك إلا هزؤا࣌ ࡰهذا ࡰلذے بعث ࡰلله رسولا', NULL, 363, 'local:warsh-text.json'),
  ('warsh-25-42', 'warsh', 25, 42, 'ࡴن كَادَ لَيُضِلُّنَا عَنَ اٰلِهَتِنَا لَوْلَآ أَن صَبَرْنَا عَلَيْهَا࣌ وَسَوْفَ يَعْلَمُونَ حِينَ يَرَوْنَ ࡰ۬لْعَذَابَ مَنَ ࡰضَلُّ سَبِيلاً࣌', 'ࡴن كاد ليضلنا عن الهتنا لولا أن صبرنا عليها࣌ وسوف يعلمون حين يرون ࡰلعذاب من ࡰضل سبيلا࣌', NULL, 363, 'local:warsh-text.json'),
  ('warsh-25-43', 'warsh', 25, 43, 'ࡰرَٰٓيْتَ مَنِ ࡴٜتَّخَذَ إِلَٰهَهُۥ هَوٜيٰهُ أَفَأَنتَ تَكُونُ عَلَيْهِ وَكِيلاً࣌', 'ࡰريت من ࡴتخذ إلهه هويه أفأنت تكون عليه وكيلا࣌', NULL, 363, 'local:warsh-text.json'),
  ('warsh-25-44', 'warsh', 25, 44, 'ࡰمْ تَحْسِبُ أَنَّ أَكْثَرَهُمْ يَسْمَعُونَ أَوْ يَعْقِلُونَ࣌ إِنْ هُمُۥٓ إِلَّا كَالَانْعَٰمِ بَلْ هُمُۥٓ أَضَلُّ سَبِيلاً࣌', 'ࡰم تحسب أن أكثرهم يسمعون أو يعقلون࣌ إن هم إلا كالانعم بل هم أضل سبيلا࣌', NULL, 364, 'local:warsh-text.json'),
  ('warsh-25-45', 'warsh', 25, 45, '۞ ࡰلَمْ تَرَ إِلَىٰ رَبِّكَ كَيْفَ مَدَّ ࡰ۬لظِّلَّ࣌ وَلَوْ شَآءَ لَجَعَلَهُۥ سَاكِناࣰ࣌ ثُمَّ جَعَلْنَا ࡰ۬لشَّمْسَ عَلَيْهِ دَلِيلاࣰ', 'ࡰلم تر إلى ربك كيف مد ࡰلظل࣌ ولو شاء لجعله ساكنا࣌ ثم جعلنا ࡰلشمس عليه دليلا', NULL, 364, 'local:warsh-text.json'),
  ('warsh-25-46', 'warsh', 25, 46, 'ثُمَّ قَبَضْنَٰهُ إِلَيْنَا قَبْضاࣰ يَسِيراࣰ࣌', 'ثم قبضنه إلينا قبضا يسيرا࣌', NULL, 364, 'local:warsh-text.json'),
  ('warsh-25-47', 'warsh', 25, 47, 'وَهُوَ ࡰ۬لذِے جَعَلَ لَكُمُ ࡲ۬ليْلَ لِبَاساࣰ وَالنَّوْمَ سُبَاتاࣰ وَجَعَلَ ࡰ۬لنَّهَارَ نُشُوراࣰ࣌', 'وهو ࡰلذے جعل لكم ࡲليل لباسا والنوم سباتا وجعل ࡰلنهار نشورا࣌', NULL, 364, 'local:warsh-text.json'),
  ('warsh-25-48', 'warsh', 25, 48, 'وَهُوَ ࡰ۬لذِےٓ أَرْسَلَ ࡰ۬لرِّيَٰحَ نُشُراَۢ بَيْنَ يَدَےْ رَحْمَتِهِۦ࣌ وَأَنزَلْنَا مِنَ ࡰ۬لسَّمَآءِ مَآءࣰ طَهُوراࣰ', 'وهو ࡰلذے أرسل ࡰلريح نشرا بين يدے رحمته࣌ وأنزلنا من ࡰلسماء ماء طهورا', NULL, 364, 'local:warsh-text.json'),
  ('warsh-25-49', 'warsh', 25, 49, 'لِّنُحْۑِيَ بِهِۦ بَلْدَةࣰ مَّيْتاࣰ وَنُسْقِيَهُۥ مِمَّا خَلَقْنَآ أَنْعَٰماࣰ وَأَنَاسِيَّ كَثِيراࣰ࣌', 'لنحۑي به بلدة ميتا ونسقيه مما خلقنا أنعما وأناسي كثيرا࣌', NULL, 364, 'local:warsh-text.json'),
  ('warsh-25-50', 'warsh', 25, 50, 'وَلَقَدْ صَرَّفْنَٰهُ بَيْنَهُمْ لِيَذَّكَّرُواْ فَأَبٜىٰٓ أَكْثَرُ ࡲ۬لنَّاسِ إِلَّا كُفُوراࣰ࣌', 'ولقد صرفنه بينهم ليذكروا فأبى أكثر ࡲلناس إلا كفورا࣌', NULL, 364, 'local:warsh-text.json'),
  ('warsh-25-51', 'warsh', 25, 51, 'وَلَوْ شِئْنَا لَبَعَثْنَا فِے كُلِّ قَرْيَةࣲ نَّذِيراࣰ࣌', 'ولو شئنا لبعثنا فے كل قرية نذيرا࣌', NULL, 364, 'local:warsh-text.json'),
  ('warsh-25-52', 'warsh', 25, 52, 'فَلَا تُطِعِ ࡴ۬لْكٜـٰفِرِينَ࣌ وَجَٰهِدْهُم بِهِۦ جِهَاداࣰ كَبِيراࣰ࣌', 'فلا تطع ࡴلكفرين࣌ وجهدهم به جهادا كبيرا࣌', NULL, 364, 'local:warsh-text.json'),
  ('warsh-25-53', 'warsh', 25, 53, 'وَهُوَ ࡰ۬لذِے مَرَجَ ࡰ۬لْبَحْرَيْنِ هَٰذَا عَذْبࣱ فُرَاتࣱ وَهَٰذَا مِلْحٌ ࡳجَاجࣱ࣌ وَجَعَلَ بَيْنَهُمَا بَرْزَخاࣰ وَحِجْراࣰ مَّحْجُوراࣰ࣌', 'وهو ࡰلذے مرج ࡰلبحرين هذا عذب فرات وهذا ملح ࡳجاج࣌ وجعل بينهما برزخا وحجرا محجورا࣌', NULL, 364, 'local:warsh-text.json'),
  ('warsh-25-54', 'warsh', 25, 54, 'وَهُوَ ࡰ۬لذِے خَلَقَ مِنَ ࡰ۬لْمَآءِ بَشَراࣰ فَجَعَلَهُۥ نَسَباࣰ وَصِهْراࣰ࣌ وَكَانَ رَبُّكَ قَدِيراࣰ࣌', 'وهو ࡰلذے خلق من ࡰلماء بشرا فجعله نسبا وصهرا࣌ وكان ربك قديرا࣌', NULL, 364, 'local:warsh-text.json'),
  ('warsh-25-55', 'warsh', 25, 55, 'وَيَعْبُدُونَ مِن دُونِ ࡴ۬للَّهِ مَا لَا يَنفَعُهُمْ وَلَا يَضُرُّهُمْ࣌ وَكَانَ ࡰ۬لْكَافِرُ عَلَىٰ رَبِّهِۦ ظَهِيراࣰ࣌', 'ويعبدون من دون ࡴلله ما لا ينفعهم ولا يضرهم࣌ وكان ࡰلكافر على ربه ظهيرا࣌', NULL, 364, 'local:warsh-text.json'),
  ('warsh-25-56', 'warsh', 25, 56, 'وَمَآ أَرْسَلْنَٰكَ إِلَّا مُبَشِّراࣰ وَنَذِيراࣰ࣌', 'وما أرسلنك إلا مبشرا ونذيرا࣌', NULL, 365, 'local:warsh-text.json'),
  ('warsh-25-57', 'warsh', 25, 57, 'قُلْ مَآ أَسْـَٔلُكُمْ عَلَيْهِ مِنَ ࡰجْرٍ ࡴلَّا مَن شَآءَ انْ يَّتَّخِذَ إِلَىٰ رَبِّهِۦ سَبِيلاࣰ࣌', 'قل ما أسلكم عليه من ࡰجر ࡴلا من شاء ان يتخذ إلى ربه سبيلا࣌', NULL, 365, 'local:warsh-text.json'),
  ('warsh-25-58', 'warsh', 25, 58, 'وَتَوَكَّلْ عَلَى ࡰ۬لْحَيِّ ࡴ۬لذِے لَا يَمُوتُ࣌ وَسَبِّحْ بِحَمْدِهِۦ࣌ وَكَفٜىٰ بِهِۦ بِذُنُوبِ عِبَادِهِۦ خَبِيراً࣌', 'وتوكل على ࡰلحي ࡴلذے لا يموت࣌ وسبح بحمده࣌ وكفى به بذنوب عباده خبيرا࣌', NULL, 365, 'local:warsh-text.json'),
  ('warsh-25-59', 'warsh', 25, 59, 'ࡴ۬لذِے خَلَقَ ࡰ۬لسَّمَٰوَٰتِ وَالَارْضَ وَمَا بَيْنَهُمَا فِے سِتَّةِ أَيَّامࣲ ثُمَّ ࡰٜسْتَوٜىٰ عَلَى ࡰ۬لْعَرْشِ࣌ ࡴ۬لرَّحْمَٰنُ࣌ فَسْـَٔلْ بِهِۦ خَبِيراࣰ࣌', 'ࡴلذے خلق ࡰلسموت والارض وما بينهما فے ستة أيام ثم ࡰستوى على ࡰلعرش࣌ ࡴلرحمن࣌ فسل به خبيرا࣌', NULL, 365, 'local:warsh-text.json'),
  ('warsh-25-60', 'warsh', 25, 60, 'وَإِذَا قِيلَ لَهُمُ ࡲ࢈سْجُدُواْ لِلرَّحْمَٰنِ قَالُواْ وَمَا ࡰ۬لرَّحْمَٰنُ࣌ أَنَسْجُدُ لِمَا تَامُرُنَا وَزَادَهُمْ نُفُوراࣰ࣌۩', 'وإذا قيل لهم ࡲ࢈سجدوا للرحمن قالوا وما ࡰلرحمن࣌ أنسجد لما تامرنا وزادهم نفورا࣌', NULL, 365, 'local:warsh-text.json'),
  ('warsh-25-61', 'warsh', 25, 61, '۞ تَبَٰرَكَ ࡰ۬لذِے جَعَلَ فِے ࡴ۬لسَّمَآءِ بُرُوجاࣰ وَجَعَلَ فِيهَا سِرَٰجاࣰ وَقَمَراࣰ مُّنِيراࣰ࣌', 'تبرك ࡰلذے جعل فے ࡴلسماء بروجا وجعل فيها سرجا وقمرا منيرا࣌', NULL, 365, 'local:warsh-text.json'),
  ('warsh-25-62', 'warsh', 25, 62, 'وَهُوَ ࡰ۬لذِے جَعَلَ ࡰ۬ليْلَ وَالنَّهَارَ خِلْفَةࣰ لِّمَنَ ࡰرَادَ أَنْ يَّذَّكَّرَ أَوَ ࡰرَادَ شُكُوراࣰ࣌', 'وهو ࡰلذے جعل ࡰليل والنهار خلفة لمن ࡰراد أن يذكر أو ࡰراد شكورا࣌', NULL, 365, 'local:warsh-text.json'),
  ('warsh-25-63', 'warsh', 25, 63, 'وَعِبَادُ ࡲ۬لرَّحْمَٰنِ ࡴ۬لذِينَ يَمْشُونَ عَلَى ࡰ۬لَارْضِ هَوْناࣰ وَإِذَا خَاطَبَهُمُ ࡲ۬لْجَٰهِلُونَ قَالُواْ سَلَٰماࣰ࣌', 'وعباد ࡲلرحمن ࡴلذين يمشون على ࡰلارض هونا وإذا خاطبهم ࡲلجهلون قالوا سلما࣌', NULL, 365, 'local:warsh-text.json'),
  ('warsh-25-64', 'warsh', 25, 64, 'وَالذِينَ يَبِيتُونَ لِرَبِّهِمْ سُجَّداࣰ وَقِيَٰماࣰ࣌', 'والذين يبيتون لربهم سجدا وقيما࣌', NULL, 365, 'local:warsh-text.json'),
  ('warsh-25-65', 'warsh', 25, 65, 'وَالذِينَ يَقُولُونَ رَبَّنَا ࡰٜصْرِفْ عَنَّا عَذَابَ جَهَنَّمَ إِنَّ عَذَابَهَا كَانَ غَرَاماً࣌', 'والذين يقولون ربنا ࡰصرف عنا عذاب جهنم إن عذابها كان غراما࣌', NULL, 365, 'local:warsh-text.json'),
  ('warsh-25-66', 'warsh', 25, 66, 'ࡴنَّهَا سَآءَتْ مُسْتَقَرّاࣰ وَمُقَاماࣰ࣌', 'ࡴنها ساءت مستقرا ومقاما࣌', NULL, 365, 'local:warsh-text.json'),
  ('warsh-25-67', 'warsh', 25, 67, 'وَالذِينَ إِذَآ أَنفَقُواْ لَمْ يُسْرِفُواْ وَلَمْ يُقْتِرُواْ وَكَانَ بَيْنَ ذَٰلِكَ قَوَاماࣰ࣌', 'والذين إذا أنفقوا لم يسرفوا ولم يقتروا وكان بين ذلك قواما࣌', NULL, 365, 'local:warsh-text.json'),
  ('warsh-25-68', 'warsh', 25, 68, 'وَالذِينَ لَا يَدْعُونَ مَعَ ࡰ۬للَّهِ إِلَٰهاً اٰخَرَ وَلَا يَقْتُلُونَ ࡰ۬لنَّفْسَ ࡰ۬لتِے حَرَّمَ ࡰ۬للَّهُ إِلَّا بِالْحَقِّ وَلَا يَزْنُونَ࣌ وَمَنْ يَّفْعَلْ ذَٰلِكَ يَلْقَ أَثَاماࣰ', 'والذين لا يدعون مع ࡰلله إلها اخر ولا يقتلون ࡰلنفس ࡰلتے حرم ࡰلله إلا بالحق ولا يزنون࣌ ومن يفعل ذلك يلق أثاما', NULL, 366, 'local:warsh-text.json'),
  ('warsh-25-69', 'warsh', 25, 69, 'يُضَٰعَفْ لَهُ ࡲ۬لْعَذَابُ يَوْمَ ࡰ۬لْقِيَٰمَةِ وَيَخْلُدْ فِيهِ مُهَاناً', 'يضعف له ࡲلعذاب يوم ࡰلقيمة ويخلد فيه مهانا', NULL, 366, 'local:warsh-text.json'),
  ('warsh-25-70', 'warsh', 25, 70, 'ࡴلَّا مَن تَابَ وَءَامَنَ وَعَمِلَ عَمَلاࣰ صَٰلِحاࣰ فَأُوْلَٰٓئِكَ يُبَدِّلُ ࡲ۬للَّهُ سَيِّـَٔاتِهِمْ حَسَنَٰتࣲ࣌ وَكَانَ ࡰ۬للَّهُ غَفُوراࣰ رَّحِيماࣰ࣌', 'ࡴلا من تاب وءامن وعمل عملا صلحا فأولئك يبدل ࡲلله سياتهم حسنت࣌ وكان ࡰلله غفورا رحيما࣌', NULL, 366, 'local:warsh-text.json'),
  ('warsh-25-71', 'warsh', 25, 71, 'وَمَن تَابَ وَعَمِلَ صَٰلِحاࣰ فَإِنَّهُۥ يَتُوبُ إِلَى ࡰ۬للَّهِ مَتَاباࣰ࣌', 'ومن تاب وعمل صلحا فإنه يتوب إلى ࡰلله متابا࣌', NULL, 366, 'local:warsh-text.json'),
  ('warsh-25-72', 'warsh', 25, 72, 'وَالذِينَ لَا يَشْهَدُونَ ࡰ۬لزُّورَ وَإِذَا مَرُّواْ بِاللَّغْوِ مَرُّواْ كِرَاماࣰ࣌', 'والذين لا يشهدون ࡰلزور وإذا مروا باللغو مروا كراما࣌', NULL, 366, 'local:warsh-text.json'),
  ('warsh-25-73', 'warsh', 25, 73, 'وَالذِينَ إِذَا ذُكِّرُواْ بِـَٔايَٰتِ رَبِّهِمْ لَمْ يَخِرُّواْ عَلَيْهَا صُمّاࣰ وَعُمْيَاناࣰ࣌', 'والذين إذا ذكروا بايت ربهم لم يخروا عليها صما وعميانا࣌', NULL, 366, 'local:warsh-text.json'),
  ('warsh-25-74', 'warsh', 25, 74, 'وَالذِينَ يَقُولُونَ رَبَّنَا هَبْ لَنَا مِنَ ࡰزْوَٰجِنَا وَذُرِّيَّٰتِنَا قُرَّةَ أَعْيُنࣲ وَاجْعَلْنَا لِلْمُتَّقِينَ إِمَاماً࣌', 'والذين يقولون ربنا هب لنا من ࡰزوجنا وذريتنا قرة أعين واجعلنا للمتقين إماما࣌', NULL, 366, 'local:warsh-text.json'),
  ('warsh-25-75', 'warsh', 25, 75, 'ࡳوْلَٰٓئِكَ يُجْزَوْنَ ࡰ۬لْغُرْفَةَ بِمَا صَبَرُواْ وَيُلَقَّوْنَ فِيهَا تَحِيَّةࣰ وَسَلَٰماً', 'ࡳولئك يجزون ࡰلغرفة بما صبروا ويلقون فيها تحية وسلما', NULL, 366, 'local:warsh-text.json'),
  ('warsh-25-76', 'warsh', 25, 76, 'خَٰلِدِينَ فِيهَا࣌ حَسُنَتْ مُسْتَقَرّاࣰ وَمُقَاماࣰ࣌', 'خلدين فيها࣌ حسنت مستقرا ومقاما࣌', NULL, 366, 'local:warsh-text.json'),
  ('warsh-25-77', 'warsh', 25, 77, 'قُلْ مَا يَعْبَؤُاْ بِكُمْ رَبِّے لَوْلَا دُعَآؤُكُمْ࣌ فَقَدْ كَذَّبْتُمْ فَسَوْفَ يَكُونُ لِزَاماࣰ࣌', 'قل ما يعبؤا بكم ربے لولا دعاؤكم࣌ فقد كذبتم فسوف يكون لزاما࣌', NULL, 366, 'local:warsh-text.json'),
  ('warsh-26-1', 'warsh', 26, 1, 'طَسِٓمِّٓ࣌ تِلْكَ ءَايَٰتُ ࡲ۬لْكِتَٰبِ ࡴ۬لْمُبِينِ࣌', 'طسم࣌ تلك ءايت ࡲلكتب ࡴلمبين࣌', NULL, 367, 'local:warsh-text.json'),
  ('warsh-26-2', 'warsh', 26, 2, 'لَعَلَّكَ بَٰخِعࣱ نَّفْسَكَ أَلَّا يَكُونُواْ مُومِنِينَ࣌', 'لعلك بخع نفسك ألا يكونوا مومنين࣌', NULL, 367, 'local:warsh-text.json'),
  ('warsh-26-3', 'warsh', 26, 3, 'إِن نَّشَأْ نُنَزِّلْ عَلَيْهِم مِّنَ ࡰ۬لسَّمَآءِ ࢇَايَةࣰ فَظَلَّتَ ࡰعْنَٰقُهُمْ لَهَا خَٰضِعِينَ࣌', 'إن نشأ ننزل عليهم من ࡰلسماء ࢇاية فظلت ࡰعنقهم لها خضعين࣌', NULL, 367, 'local:warsh-text.json'),
  ('warsh-26-4', 'warsh', 26, 4, 'وَمَا يَاتِيهِم مِّن ذِكْرࣲ مِّنَ ࡰ۬لرَّحْمَٰنِ مُحْدَثٍ ࡴلَّا كَانُواْ عَنْهُ مُعْرِضِينَ࣌', 'وما ياتيهم من ذكر من ࡰلرحمن محدث ࡴلا كانوا عنه معرضين࣌', NULL, 367, 'local:warsh-text.json'),
  ('warsh-26-5', 'warsh', 26, 5, 'فَقَدْ كَذَّبُواْ فَسَيَاتِيهِمُۥٓ أَنۢبَٰٓؤُاْ مَا كَانُواْ بِهِۦ يَسْتَهْزِءُونَ࣌', 'فقد كذبوا فسياتيهم أنبؤا ما كانوا به يستهزءون࣌', NULL, 367, 'local:warsh-text.json'),
  ('warsh-26-6', 'warsh', 26, 6, 'أَوَلَمْ يَرَوِاْ ࡴلَى ࡰ۬لَارْضِ كَمَ ࡰنۢبَتْنَا فِيهَا مِن كُلِّ زَوْجࣲ كَرِيمٍ࣌', 'أولم يروا ࡴلى ࡰلارض كم ࡰنبتنا فيها من كل زوج كريم࣌', NULL, 367, 'local:warsh-text.json'),
  ('warsh-26-7', 'warsh', 26, 7, 'ࡴنَّ فِے ذَٰلِكَ لَأٓيَةࣰ࣌ وَمَا كَانَ أَكْثَرُهُم مُّومِنِينَ࣌', 'ࡴن فے ذلك لأية࣌ وما كان أكثرهم مومنين࣌', NULL, 367, 'local:warsh-text.json'),
  ('warsh-26-8', 'warsh', 26, 8, 'وَإِنَّ رَبَّكَ لَهُوَ ࡰ۬لْعَزِيزُ ࡲ۬لرَّحِيمُ࣌', 'وإن ربك لهو ࡰلعزيز ࡲلرحيم࣌', NULL, 367, 'local:warsh-text.json'),
  ('warsh-26-9', 'warsh', 26, 9, 'وَإِذْ نَادٜىٰ رَبُّكَ مُوسٜىٰٓ أَنِ ࡴٜيتِ ࡴ۬لْقَوْمَ ࡰ۬لظَّٰلِمِينَ', 'وإذ نادى ربك موسى أن ࡴيت ࡴلقوم ࡰلظلمين', NULL, 367, 'local:warsh-text.json'),
  ('warsh-26-10', 'warsh', 26, 10, 'قَوْمَ فِرْعَوْنَ࣌ أَلَا يَتَّقُونَ࣌', 'قوم فرعون࣌ ألا يتقون࣌', NULL, 367, 'local:warsh-text.json'),
  ('warsh-26-11', 'warsh', 26, 11, 'قَالَ رَبِّ إِنِّيَ أَخَافُ أَنْ يُّكَذِّبُونِ', 'قال رب إني أخاف أن يكذبون', NULL, 367, 'local:warsh-text.json'),
  ('warsh-26-12', 'warsh', 26, 12, 'وَيَضِيقُ صَدْرِے وَلَا يَنطَلِقُ لِسَانِے فَأَرْسِلِ ࡴلَىٰ هَٰرُونَ', 'ويضيق صدرے ولا ينطلق لسانے فأرسل ࡴلى هرون', NULL, 367, 'local:warsh-text.json'),
  ('warsh-26-13', 'warsh', 26, 13, 'وَلَهُمْ عَلَيَّ ذَنۢبࣱ فَأَخَافُ أَنْ يَّقْتُلُونِ࣌', 'ولهم علي ذنب فأخاف أن يقتلون࣌', NULL, 367, 'local:warsh-text.json'),
  ('warsh-26-14', 'warsh', 26, 14, 'قَالَ كَلَّا࣌ فَاذْهَبَا بِـَٔايَٰتِنَآ إِنَّا مَعَكُم مُّسْتَمِعُونَ࣌', 'قال كلا࣌ فاذهبا بايتنا إنا معكم مستمعون࣌', NULL, 367, 'local:warsh-text.json'),
  ('warsh-26-15', 'warsh', 26, 15, 'فَاتِيَا فِرْعَوْنَ فَقُولَآ إِنَّا رَسُولُ رَبِّ ࡴ۬لْعَٰلَمِينَ', 'فاتيا فرعون فقولا إنا رسول رب ࡴلعلمين', NULL, 367, 'local:warsh-text.json'),
  ('warsh-26-16', 'warsh', 26, 16, 'أَنَ ࡰرْسِلْ مَعَنَا بَنِےٓ إِسْرَآءِيلَ࣌', 'أن ࡰرسل معنا بنے إسراءيل࣌', NULL, 367, 'local:warsh-text.json'),
  ('warsh-26-17', 'warsh', 26, 17, 'قَالَ أَلَمْ نُرَبِّكَ فِينَا وَلِيداࣰ وَلَبِثْتَ فِينَا مِنْ عُمُرِكَ سِنِينَ', 'قال ألم نربك فينا وليدا ولبثت فينا من عمرك سنين', NULL, 367, 'local:warsh-text.json'),
  ('warsh-26-18', 'warsh', 26, 18, 'وَفَعَلْتَ فَعْلَتَكَ ࡰ۬لتِے فَعَلْتَ وَأَنتَ مِنَ ࡰ۬لْكٜـٰفِرِينَ࣌', 'وفعلت فعلتك ࡰلتے فعلت وأنت من ࡰلكفرين࣌', NULL, 367, 'local:warsh-text.json'),
  ('warsh-26-19', 'warsh', 26, 19, 'قَالَ فَعَلْتُهَآ إِذاࣰ وَأَنَا مِنَ ࡰ۬لضَّآلِّينَ࣌', 'قال فعلتها إذا وأنا من ࡰلضالين࣌', NULL, 368, 'local:warsh-text.json'),
  ('warsh-26-20', 'warsh', 26, 20, 'فَفَرَرْتُ مِنكُمْ لَمَّا خِفْتُكُمْ فَوَهَبَ لِے رَبِّے حُكْماࣰ وَجَعَلَنِے مِنَ ࡰ۬لْمُرْسَلِينَ࣌', 'ففررت منكم لما خفتكم فوهب لے ربے حكما وجعلنے من ࡰلمرسلين࣌', NULL, 368, 'local:warsh-text.json'),
  ('warsh-26-21', 'warsh', 26, 21, 'وَتِلْكَ نِعْمَةࣱ تَمُنُّهَا عَلَيَّ أَنْ عَبَّدتَّ بَنِےٓ إِسْرَآءِيلَ࣌', 'وتلك نعمة تمنها علي أن عبدت بنے إسراءيل࣌', NULL, 368, 'local:warsh-text.json'),
  ('warsh-26-22', 'warsh', 26, 22, 'قَالَ فِرْعَوْنُ وَمَا رَبُّ ࡲ۬لْعَٰلَمِينَ࣌', 'قال فرعون وما رب ࡲلعلمين࣌', NULL, 368, 'local:warsh-text.json'),
  ('warsh-26-23', 'warsh', 26, 23, 'قَالَ رَبُّ ࡲ۬لسَّمَٰوَٰتِ وَالَارْضِ وَمَا بَيْنَهُمَآ إِن كُنتُم مُّوقِنِينَ࣌', 'قال رب ࡲلسموت والارض وما بينهما إن كنتم موقنين࣌', NULL, 368, 'local:warsh-text.json'),
  ('warsh-26-24', 'warsh', 26, 24, '۞ قَالَ لِمَنْ حَوْلَهُۥٓ أَلَا تَسْتَمِعُونَ࣌', 'قال لمن حوله ألا تستمعون࣌', NULL, 368, 'local:warsh-text.json'),
  ('warsh-26-25', 'warsh', 26, 25, 'قَالَ رَبُّكُمْ وَرَبُّ ءَابَآئِكُمُ ࡲ۬لَاوَّلِينَ࣌', 'قال ربكم ورب ءابائكم ࡲلاولين࣌', NULL, 368, 'local:warsh-text.json'),
  ('warsh-26-26', 'warsh', 26, 26, 'قَالَ إِنَّ رَسُولَكُمُ ࡲ۬لذِےٓ أُرْسِلَ إِلَيْكُمْ لَمَجْنُونࣱ࣌', 'قال إن رسولكم ࡲلذے أرسل إليكم لمجنون࣌', NULL, 368, 'local:warsh-text.json'),
  ('warsh-26-27', 'warsh', 26, 27, 'قَالَ رَبُّ ࡲ۬لْمَشْرِقِ وَالْمَغْرِبِ وَمَا بَيْنَهُمَآ إِن كُنتُمْ تَعْقِلُونَ࣌', 'قال رب ࡲلمشرق والمغرب وما بينهما إن كنتم تعقلون࣌', NULL, 368, 'local:warsh-text.json'),
  ('warsh-26-28', 'warsh', 26, 28, 'قَالَ لَئِنِ ࡴٜتَّخَذتَّ إِلَٰهاً غَيْرِے لَأَجْعَلَنَّكَ مِنَ ࡰ۬لْمَسْجُونِينَ࣌', 'قال لئن ࡴتخذت إلها غيرے لأجعلنك من ࡰلمسجونين࣌', NULL, 368, 'local:warsh-text.json'),
  ('warsh-26-29', 'warsh', 26, 29, 'قَالَ أَوَلَوْ جِئْتُكَ بِشَےْءࣲ مُّبِينࣲ࣌', 'قال أولو جئتك بشےء مبين࣌', NULL, 368, 'local:warsh-text.json'),
  ('warsh-26-30', 'warsh', 26, 30, 'قَالَ فَاتِ بِهِۦٓ إِن كُنتَ مِنَ ࡰ۬لصَّٰدِقِينَ࣌', 'قال فات به إن كنت من ࡰلصدقين࣌', NULL, 368, 'local:warsh-text.json'),
  ('warsh-26-31', 'warsh', 26, 31, 'فَأَلْقٜىٰ عَصَاهُ فَإِذَا هِيَ ثُعْبَانࣱ مُّبِينࣱ', 'فألقى عصاه فإذا هي ثعبان مبين', NULL, 368, 'local:warsh-text.json'),
  ('warsh-26-32', 'warsh', 26, 32, 'وَنَزَعَ يَدَهُۥ فَإِذَا هِيَ بَيْضَآءُ لِلنَّٰظِرِينَ࣌', 'ونزع يده فإذا هي بيضاء للنظرين࣌', NULL, 368, 'local:warsh-text.json'),
  ('warsh-26-33', 'warsh', 26, 33, 'قَالَ لِلْمَلَإِ حَوْلَهُۥٓ إِنَّ هَٰذَا لَسَٰحِرٌ عَلِيمࣱ', 'قال للملإ حوله إن هذا لسحر عليم', NULL, 368, 'local:warsh-text.json'),
  ('warsh-26-34', 'warsh', 26, 34, 'يُرِيدُ أَنْ يُّخْرِجَكُم مِّنَ ࡰرْضِكُم بِسِحْرِهِۦ فَمَاذَا تَامُرُونَ࣌', 'يريد أن يخرجكم من ࡰرضكم بسحره فماذا تامرون࣌', NULL, 368, 'local:warsh-text.json'),
  ('warsh-26-35', 'warsh', 26, 35, 'قَالُوٓاْ أَرْجِهِۦ وَأَخَاهُ وَابْعَثْ فِے ࡴ۬لْمَدَآئِنِ حَٰشِرِينَ', 'قالوا أرجه وأخاه وابعث فے ࡴلمدائن حشرين', NULL, 368, 'local:warsh-text.json'),
  ('warsh-26-36', 'warsh', 26, 36, 'يَاتُوكَ بِكُلِّ سَحّٜارٍ عَلِيمࣲ࣌', 'ياتوك بكل سحار عليم࣌', NULL, 368, 'local:warsh-text.json'),
  ('warsh-26-37', 'warsh', 26, 37, 'فَجُمِعَ ࡰ۬لسَّحَرَةُ لِمِيقَٰتِ يَوْمࣲ مَّعْلُومࣲ࣌', 'فجمع ࡰلسحرة لميقت يوم معلوم࣌', NULL, 368, 'local:warsh-text.json'),
  ('warsh-26-38', 'warsh', 26, 38, 'وَقِيلَ لِلنَّاسِ هَلَ ࡰنتُم مُّجْتَمِعُونَ', 'وقيل للناس هل ࡰنتم مجتمعون', NULL, 368, 'local:warsh-text.json'),
  ('warsh-26-39', 'warsh', 26, 39, 'لَعَلَّنَا نَتَّبِعُ ࡲ۬لسَّحَرَةَ إِن كَانُواْ هُمُ ࡲ۬لْغَٰلِبِينَ࣌', 'لعلنا نتبع ࡲلسحرة إن كانوا هم ࡲلغلبين࣌', NULL, 369, 'local:warsh-text.json'),
  ('warsh-26-40', 'warsh', 26, 40, 'فَلَمَّا جَآءَ ࡰ۬لسَّحَرَةُ قَالُواْ لِفِرْعَوْنَ أَئِنَّ لَنَا لَأَجْراً ࡴن كُنَّا نَحْنُ ࡲ۬لْغَٰلِبِينَ࣌', 'فلما جاء ࡰلسحرة قالوا لفرعون أئن لنا لأجرا ࡴن كنا نحن ࡲلغلبين࣌', NULL, 369, 'local:warsh-text.json'),
  ('warsh-26-41', 'warsh', 26, 41, 'قَالَ نَعَمْ وَإِنَّكُمُۥٓ إِذاࣰ لَّمِنَ ࡰ۬لْمُقَرَّبِينَ࣌', 'قال نعم وإنكم إذا لمن ࡰلمقربين࣌', NULL, 369, 'local:warsh-text.json'),
  ('warsh-26-42', 'warsh', 26, 42, 'قَالَ لَهُم مُّوسٜىٰٓ أَلْقُواْ مَآ أَنتُم مُّلْقُونَ࣌', 'قال لهم موسى ألقوا ما أنتم ملقون࣌', NULL, 369, 'local:warsh-text.json'),
  ('warsh-26-43', 'warsh', 26, 43, 'فَأَلْقَوْاْ حِبَالَهُمْ وَعِصِيَّهُمْ وَقَالُواْ بِعِزَّةِ فِرْعَوْنَ إِنَّا لَنَحْنُ ࡲ۬لْغَٰلِبُونَ࣌', 'فألقوا حبالهم وعصيهم وقالوا بعزة فرعون إنا لنحن ࡲلغلبون࣌', NULL, 369, 'local:warsh-text.json'),
  ('warsh-26-44', 'warsh', 26, 44, 'فَأَلْقٜىٰ مُوسٜىٰ عَصَاهُ فَإِذَا هِيَ تَلَقَّفُ مَا يَافِكُونَ࣌', 'فألقى موسى عصاه فإذا هي تلقف ما يافكون࣌', NULL, 369, 'local:warsh-text.json'),
  ('warsh-26-45', 'warsh', 26, 45, 'فَأُلْقِيَ ࡰ۬لسَّحَرَةُ سَٰجِدِينَ࣌', 'فألقي ࡰلسحرة سجدين࣌', NULL, 369, 'local:warsh-text.json'),
  ('warsh-26-46', 'warsh', 26, 46, 'قَالُوٓاْ ءَامَنَّا بِرَبِّ ࡴ۬لْعَٰلَمِينَ࣌', 'قالوا ءامنا برب ࡴلعلمين࣌', NULL, 369, 'local:warsh-text.json'),
  ('warsh-26-47', 'warsh', 26, 47, 'رَبِّ مُوسٜىٰ وَهَٰرُونَ࣌', 'رب موسى وهرون࣌', NULL, 369, 'local:warsh-text.json'),
  ('warsh-26-48', 'warsh', 26, 48, 'قَالَ ءَࡶٰمَنتُمْ لَهُۥ قَبْلَ أَنَ اٰذَنَ لَكُمُۥٓ إِنَّهُۥ لَكَبِيرُكُمُ ࡲ۬لذِے عَلَّمَكُمُ ࡲ۬لسِّحْرَ࣌ فَلَسَوْفَ تَعْلَمُونَ࣌', 'قال ءࡶمنتم له قبل أن اذن لكم إنه لكبيركم ࡲلذے علمكم ࡲلسحر࣌ فلسوف تعلمون࣌', NULL, 369, 'local:warsh-text.json'),
  ('warsh-26-49', 'warsh', 26, 49, 'لَأُقَطِّعَنَّ أَيْدِيَكُمْ وَأَرْجُلَكُم مِّنْ خِلَٰفࣲ وَلَأُصَلِّبَنَّكُمُۥٓ أَجْمَعِينَ࣌', 'لأقطعن أيديكم وأرجلكم من خلف ولأصلبنكم أجمعين࣌', NULL, 369, 'local:warsh-text.json'),
  ('warsh-26-50', 'warsh', 26, 50, '۞ قَالُواْ لَا ضَيْرَ࣌ إِنَّآ إِلَىٰ رَبِّنَا مُنقَلِبُونَ࣌', 'قالوا لا ضير࣌ إنا إلى ربنا منقلبون࣌', NULL, 369, 'local:warsh-text.json'),
  ('warsh-26-51', 'warsh', 26, 51, 'إِنَّا نَطْمَعُ أَنْ يَّغْفِرَ لَنَا رَبُّنَا خَطَٰيٜـٰنَآ أَن كُنَّآ أَوَّلَ ࡰ۬لْمُومِنِينَ࣌', 'إنا نطمع أن يغفر لنا ربنا خطينا أن كنا أول ࡰلمومنين࣌', NULL, 369, 'local:warsh-text.json'),
  ('warsh-26-52', 'warsh', 26, 52, 'وَأَوْحَيْنَآ إِلَىٰ مُوسٜىٰٓ أَنِ ࡴٜسْرِ بِعِبَادِيَ إِنَّكُم مُّتَّبَعُونَ࣌', 'وأوحينا إلى موسى أن ࡴسر بعبادي إنكم متبعون࣌', NULL, 369, 'local:warsh-text.json'),
  ('warsh-26-53', 'warsh', 26, 53, 'فَأَرْسَلَ فِرْعَوْنُ فِے ࡴ۬لْمَدَآئِنِ حَٰشِرِينَ࣌', 'فأرسل فرعون فے ࡴلمدائن حشرين࣌', NULL, 369, 'local:warsh-text.json'),
  ('warsh-26-54', 'warsh', 26, 54, 'إِنَّ هَٰٓؤُلَآءِ لَشِرْذِمَةࣱ قَلِيلُونَ', 'إن هؤلاء لشرذمة قليلون', NULL, 369, 'local:warsh-text.json'),
  ('warsh-26-55', 'warsh', 26, 55, 'وَإِنَّهُمْ لَنَا لَغَآئِظُونَ', 'وإنهم لنا لغائظون', NULL, 369, 'local:warsh-text.json'),
  ('warsh-26-56', 'warsh', 26, 56, 'وَإِنَّا لَجَمِيعٌ حَذِرُونَ࣌', 'وإنا لجميع حذرون࣌', NULL, 369, 'local:warsh-text.json'),
  ('warsh-26-57', 'warsh', 26, 57, 'فَأَخْرَجْنَٰهُم مِّن جَنَّٰتࣲ وَعُيُونࣲ', 'فأخرجنهم من جنت وعيون', NULL, 369, 'local:warsh-text.json'),
  ('warsh-26-58', 'warsh', 26, 58, 'وَكُنُوزࣲ وَمَقَامࣲ كَرِيمࣲ࣌', 'وكنوز ومقام كريم࣌', NULL, 369, 'local:warsh-text.json'),
  ('warsh-26-59', 'warsh', 26, 59, 'كَذَٰلِكَ࣌ وَأَوْرَثْنَٰهَا بَنِےٓ إِسْرَآءِيلَ', 'كذلك࣌ وأورثنها بنے إسراءيل', NULL, 369, 'local:warsh-text.json'),
  ('warsh-26-60', 'warsh', 26, 60, 'فَأَتْبَعُوهُم مُّشْرِقِينَ࣌', 'فأتبعوهم مشرقين࣌', NULL, 369, 'local:warsh-text.json'),
  ('warsh-26-61', 'warsh', 26, 61, 'فَلَمَّا تَرَٰٓءَا ࡰ۬لْجَمْعَٰنِ قَالَ أَصْحَٰبُ مُوسٜىٰٓ إِنَّا لَمُدْرَكُونَ࣌', 'فلما ترءا ࡰلجمعن قال أصحب موسى إنا لمدركون࣌', NULL, 370, 'local:warsh-text.json'),
  ('warsh-26-62', 'warsh', 26, 62, 'قَالَ كَلَّآ࣌ إِنَّ مَعِے رَبِّے سَيَهْدِينِ࣌', 'قال كلا࣌ إن معے ربے سيهدين࣌', NULL, 370, 'local:warsh-text.json'),
  ('warsh-26-63', 'warsh', 26, 63, 'فَأَوْحَيْنَآ إِلَىٰ مُوسٜىٰٓ أَنِ ࡴٜضْرِب بِّعَصَاكَ ࡰ۬لْبَحْرَ فَانفَلَقَ فَكَانَ كُلُّ فِرْقࣲ كَالطَّوْدِ ࡴ۬لْعَظِيمِ࣌', 'فأوحينا إلى موسى أن ࡴضرب بعصاك ࡰلبحر فانفلق فكان كل فرق كالطود ࡴلعظيم࣌', NULL, 370, 'local:warsh-text.json'),
  ('warsh-26-64', 'warsh', 26, 64, 'وَأَزْلَفْنَا ثَمَّ ࡰ۬لَاخَرِينَ࣌', 'وأزلفنا ثم ࡰلاخرين࣌', NULL, 370, 'local:warsh-text.json'),
  ('warsh-26-65', 'warsh', 26, 65, 'وَأَنجَيْنَا مُوسٜىٰ وَمَن مَّعَهُۥٓ أَجْمَعِينَ', 'وأنجينا موسى ومن معه أجمعين', NULL, 370, 'local:warsh-text.json'),
  ('warsh-26-66', 'warsh', 26, 66, 'ثُمَّ أَغْرَقْنَا ࡰ۬لَاخَرِينَ࣌', 'ثم أغرقنا ࡰلاخرين࣌', NULL, 370, 'local:warsh-text.json'),
  ('warsh-26-67', 'warsh', 26, 67, 'إِنَّ فِے ذَٰلِكَ لَأٓيَةࣰ࣌ وَمَا كَانَ أَكْثَرُهُم مُّومِنِينَ࣌', 'إن فے ذلك لأية࣌ وما كان أكثرهم مومنين࣌', NULL, 370, 'local:warsh-text.json'),
  ('warsh-26-68', 'warsh', 26, 68, 'وَإِنَّ رَبَّكَ لَهُوَ ࡰ۬لْعَزِيزُ ࡲ۬لرَّحِيمُ࣌', 'وإن ربك لهو ࡰلعزيز ࡲلرحيم࣌', NULL, 370, 'local:warsh-text.json'),
  ('warsh-26-69', 'warsh', 26, 69, 'وَاتْلُ عَلَيْهِمْ نَبَأَ ࡹبْرَٰهِيمَ', 'واتل عليهم نبأ ࡹبرهيم', NULL, 370, 'local:warsh-text.json'),
  ('warsh-26-70', 'warsh', 26, 70, 'إِذْ قَالَ لِأَبِيهِ وَقَوْمِهِۦ مَا تَعْبُدُونَ࣌', 'إذ قال لأبيه وقومه ما تعبدون࣌', NULL, 370, 'local:warsh-text.json'),
  ('warsh-26-71', 'warsh', 26, 71, 'قَالُواْ نَعْبُدُ أَصْنَاماࣰ فَنَظَلُّ لَهَا عَٰكِفِينَ࣌', 'قالوا نعبد أصناما فنظل لها عكفين࣌', NULL, 370, 'local:warsh-text.json'),
  ('warsh-26-72', 'warsh', 26, 72, 'قَالَ هَلْ يَسْمَعُونَكُمُۥٓ إِذْ تَدْعُونَ', 'قال هل يسمعونكم إذ تدعون', NULL, 370, 'local:warsh-text.json'),
  ('warsh-26-73', 'warsh', 26, 73, 'أَوْ يَنفَعُونَكُمُۥٓ أَوْ يَضُرُّونَ࣌', 'أو ينفعونكم أو يضرون࣌', NULL, 370, 'local:warsh-text.json'),
  ('warsh-26-74', 'warsh', 26, 74, 'قَالُواْ بَلْ وَجَدْنَآ ءَابَآءَنَا كَذَٰلِكَ يَفْعَلُونَ࣌', 'قالوا بل وجدنا ءاباءنا كذلك يفعلون࣌', NULL, 370, 'local:warsh-text.json'),
  ('warsh-26-75', 'warsh', 26, 75, 'قَالَ أَفَرَٰٓيْتُم مَّا كُنتُمْ تَعْبُدُونَ', 'قال أفريتم ما كنتم تعبدون', NULL, 370, 'local:warsh-text.json'),
  ('warsh-26-76', 'warsh', 26, 76, 'أَنتُمْ وَءَابَآؤُكُمُ ࡲ۬لَاقْدَمُونَ', 'أنتم وءاباؤكم ࡲلاقدمون', NULL, 370, 'local:warsh-text.json'),
  ('warsh-26-77', 'warsh', 26, 77, 'فَإِنَّهُمْ عَدُوࣱّ لِّيَ࣌ إِلَّا رَبَّ ࡰ۬لْعَٰلَمِينَ', 'فإنهم عدو لي࣌ إلا رب ࡰلعلمين', NULL, 370, 'local:warsh-text.json'),
  ('warsh-26-78', 'warsh', 26, 78, 'ࡰ۬لذِے خَلَقَنِے فَهُوَ يَهْدِينِ࣌', 'ࡰلذے خلقنے فهو يهدين࣌', NULL, 370, 'local:warsh-text.json'),
  ('warsh-26-79', 'warsh', 26, 79, 'وَالذِے هُوَ يُطْعِمُنِے وَيَسْقِينِ', 'والذے هو يطعمنے ويسقين', NULL, 370, 'local:warsh-text.json'),
  ('warsh-26-80', 'warsh', 26, 80, 'وَإِذَا مَرِضْتُ فَهُوَ يَشْفِينِ࣌', 'وإذا مرضت فهو يشفين࣌', NULL, 370, 'local:warsh-text.json'),
  ('warsh-26-81', 'warsh', 26, 81, 'وَالذِے يُمِيتُنِے ثُمَّ يُحْيِينِ࣌', 'والذے يميتنے ثم يحيين࣌', NULL, 370, 'local:warsh-text.json'),
  ('warsh-26-82', 'warsh', 26, 82, '۞ وَالذِےٓ أَطْمَعُ أَنْ يَّغْفِرَ لِے خَطِيٓـَٔتِے يَوْمَ ࡰ۬لدِّينِ࣌', 'والذے أطمع أن يغفر لے خطيتے يوم ࡰلدين࣌', NULL, 370, 'local:warsh-text.json'),
  ('warsh-26-83', 'warsh', 26, 83, 'رَبِّ هَبْ لِے حُكْماࣰ وَأَلْحِقْنِے بِالصَّٰلِحِينَ࣌', 'رب هب لے حكما وألحقنے بالصلحين࣌', NULL, 370, 'local:warsh-text.json'),
  ('warsh-26-84', 'warsh', 26, 84, 'وَاجْعَل لِّے لِسَانَ صِدْقࣲ فِے ࡴ۬لَاخِرِينَ࣌', 'واجعل لے لسان صدق فے ࡴلاخرين࣌', NULL, 371, 'local:warsh-text.json'),
  ('warsh-26-85', 'warsh', 26, 85, 'وَاجْعَلْنِے مِنْ وَّرَثَةِ جَنَّةِ ࡴ۬لنَّعِيمِ࣌', 'واجعلنے من ورثة جنة ࡴلنعيم࣌', NULL, 371, 'local:warsh-text.json'),
  ('warsh-26-86', 'warsh', 26, 86, 'وَاغْفِرْ لِأَبِيَ إِنَّهُۥ كَانَ مِنَ ࡰ۬لضَّآلِّينَ࣌', 'واغفر لأبي إنه كان من ࡰلضالين࣌', NULL, 371, 'local:warsh-text.json'),
  ('warsh-26-87', 'warsh', 26, 87, 'وَلَا تُخْزِنِے يَوْمَ يُبْعَثُونَ', 'ولا تخزنے يوم يبعثون', NULL, 371, 'local:warsh-text.json'),
  ('warsh-26-88', 'warsh', 26, 88, 'يَوْمَ لَا يَنفَعُ مَالࣱ وَلَا بَنُونَ', 'يوم لا ينفع مال ولا بنون', NULL, 371, 'local:warsh-text.json'),
  ('warsh-26-89', 'warsh', 26, 89, 'إِلَّا مَنَ ࡰتَى ࡰ۬للَّهَ بِقَلْبࣲ سَلِيمࣲ࣌', 'إلا من ࡰتى ࡰلله بقلب سليم࣌', NULL, 371, 'local:warsh-text.json'),
  ('warsh-26-90', 'warsh', 26, 90, 'وَأُزْلِفَتِ ࡴ۬لْجَنَّةُ لِلْمُتَّقِينَ࣌', 'وأزلفت ࡴلجنة للمتقين࣌', NULL, 371, 'local:warsh-text.json'),
  ('warsh-26-91', 'warsh', 26, 91, 'وَبُرِّزَتِ ࡴ۬لْجَحِيمُ لِلْغَاوِينَ࣌', 'وبرزت ࡴلجحيم للغاوين࣌', NULL, 371, 'local:warsh-text.json'),
  ('warsh-26-92', 'warsh', 26, 92, 'وَقِيلَ لَهُمُۥٓ أَيْنَ مَا كُنتُمْ تَعْبُدُونَ', 'وقيل لهم أين ما كنتم تعبدون', NULL, 371, 'local:warsh-text.json'),
  ('warsh-26-93', 'warsh', 26, 93, 'مِن دُونِ ࡴ۬للَّهِ࣌ هَلْ يَنصُرُونَكُمُۥٓ أَوْ يَنتَصِرُونَ࣌', 'من دون ࡴلله࣌ هل ينصرونكم أو ينتصرون࣌', NULL, 371, 'local:warsh-text.json'),
  ('warsh-26-94', 'warsh', 26, 94, 'فَكُبْكِبُواْ فِيهَا هُمْ وَالْغَاوُۥنَ', 'فكبكبوا فيها هم والغاون', NULL, 371, 'local:warsh-text.json'),
  ('warsh-26-95', 'warsh', 26, 95, 'وَجُنُودُ إِبْلِيسَ أَجْمَعُونَ࣌', 'وجنود إبليس أجمعون࣌', NULL, 371, 'local:warsh-text.json'),
  ('warsh-26-96', 'warsh', 26, 96, 'قَالُواْ وَهُمْ فِيهَا يَخْتَصِمُونَ', 'قالوا وهم فيها يختصمون', NULL, 371, 'local:warsh-text.json'),
  ('warsh-26-97', 'warsh', 26, 97, 'تَاللَّهِ إِن كُنَّا لَفِے ضَلَٰلࣲ مُّبِينٍ', 'تالله إن كنا لفے ضلل مبين', NULL, 371, 'local:warsh-text.json'),
  ('warsh-26-98', 'warsh', 26, 98, 'ࡴذْ نُسَوِّيكُم بِرَبِّ ࡴ۬لْعَٰلَمِينَ࣌', 'ࡴذ نسويكم برب ࡴلعلمين࣌', NULL, 371, 'local:warsh-text.json'),
  ('warsh-26-99', 'warsh', 26, 99, 'وَمَآ أَضَلَّنَآ إِلَّا ࡰ۬لْمُجْرِمُونَ࣌', 'وما أضلنا إلا ࡰلمجرمون࣌', NULL, 371, 'local:warsh-text.json'),
  ('warsh-26-100', 'warsh', 26, 100, 'فَمَا لَنَا مِن شَٰفِعِينَ', 'فما لنا من شفعين', NULL, 371, 'local:warsh-text.json'),
  ('warsh-26-101', 'warsh', 26, 101, 'وَلَا صَدِيقٍ حَمِيمࣲ࣌', 'ولا صديق حميم࣌', NULL, 371, 'local:warsh-text.json'),
  ('warsh-26-102', 'warsh', 26, 102, 'فَلَوَ ࡰنَّ لَنَا كَرَّةࣰ فَنَكُونَ مِنَ ࡰ۬لْمُومِنِينَ࣌', 'فلو ࡰن لنا كرة فنكون من ࡰلمومنين࣌', NULL, 371, 'local:warsh-text.json'),
  ('warsh-26-103', 'warsh', 26, 103, 'إِنَّ فِے ذَٰلِكَ لَأٓيَةࣰ࣌ وَمَا كَانَ أَكْثَرُهُم مُّومِنِينَ࣌', 'إن فے ذلك لأية࣌ وما كان أكثرهم مومنين࣌', NULL, 371, 'local:warsh-text.json'),
  ('warsh-26-104', 'warsh', 26, 104, 'وَإِنَّ رَبَّكَ لَهُوَ ࡰ۬لْعَزِيزُ ࡲ۬لرَّحِيمُ࣌', 'وإن ربك لهو ࡰلعزيز ࡲلرحيم࣌', NULL, 371, 'local:warsh-text.json'),
  ('warsh-26-105', 'warsh', 26, 105, 'كَذَّبَتْ قَوْمُ نُوحٍ ࡴ۬لْمُرْسَلِينَ', 'كذبت قوم نوح ࡴلمرسلين', NULL, 371, 'local:warsh-text.json'),
  ('warsh-26-106', 'warsh', 26, 106, 'إِذْ قَالَ لَهُمُۥٓ أَخُوهُمْ نُوحٌ ࡰلَا تَتَّقُونَ', 'إذ قال لهم أخوهم نوح ࡰلا تتقون', NULL, 371, 'local:warsh-text.json'),
  ('warsh-26-107', 'warsh', 26, 107, 'إِنِّے لَكُمْ رَسُولٌ ࡰمِينࣱ࣌', 'إنے لكم رسول ࡰمين࣌', NULL, 371, 'local:warsh-text.json'),
  ('warsh-26-108', 'warsh', 26, 108, 'فَاتَّقُواْ ࡲ۬للَّهَ وَأَطِيعُونِ࣌', 'فاتقوا ࡲلله وأطيعون࣌', NULL, 371, 'local:warsh-text.json'),
  ('warsh-26-109', 'warsh', 26, 109, 'وَمَآ أَسْـَٔلُكُمْ عَلَيْهِ مِنَ ࡰجْرٍ࣌ ࡴنَ ࡰجْرِيَ إِلَّا عَلَىٰ رَبِّ ࡴ۬لْعَٰلَمِينَ࣌', 'وما أسلكم عليه من ࡰجر࣌ ࡴن ࡰجري إلا على رب ࡴلعلمين࣌', NULL, 371, 'local:warsh-text.json'),
  ('warsh-26-110', 'warsh', 26, 110, 'فَاتَّقُواْ ࡲ۬للَّهَ وَأَطِيعُونِ࣌', 'فاتقوا ࡲلله وأطيعون࣌', NULL, 371, 'local:warsh-text.json'),
  ('warsh-26-111', 'warsh', 26, 111, '۞ قَالُوٓاْ أَنُومِنُ لَكَ وَاتَّبَعَكَ ࡰ۬لَارْذَلُونَ࣌', 'قالوا أنومن لك واتبعك ࡰلارذلون࣌', NULL, 371, 'local:warsh-text.json'),
  ('warsh-26-112', 'warsh', 26, 112, 'قَالَ وَمَا عِلْمِے بِمَا كَانُواْ يَعْمَلُونَ࣌', 'قال وما علمے بما كانوا يعملون࣌', NULL, 372, 'local:warsh-text.json'),
  ('warsh-26-113', 'warsh', 26, 113, 'إِنْ حِسَابُهُمُۥٓ إِلَّا عَلَىٰ رَبِّے لَوْ تَشْعُرُونَ࣌', 'إن حسابهم إلا على ربے لو تشعرون࣌', NULL, 372, 'local:warsh-text.json'),
  ('warsh-26-114', 'warsh', 26, 114, 'وَمَآ أَنَا بِطَارِدِ ࡴ۬لْمُومِنِينَ', 'وما أنا بطارد ࡴلمومنين', NULL, 372, 'local:warsh-text.json'),
  ('warsh-26-115', 'warsh', 26, 115, 'إِنَ ࡰنَا إِلَّا نَذِيرࣱ مُّبِينࣱ࣌', 'إن ࡰنا إلا نذير مبين࣌', NULL, 372, 'local:warsh-text.json'),
  ('warsh-26-116', 'warsh', 26, 116, 'قَالُواْ لَئِن لَّمْ تَنتَهِ يَٰنُوحُ لَتَكُونَنَّ مِنَ ࡰ۬لْمَرْجُومِينَ࣌', 'قالوا لئن لم تنته ينوح لتكونن من ࡰلمرجومين࣌', NULL, 372, 'local:warsh-text.json'),
  ('warsh-26-117', 'warsh', 26, 117, 'قَالَ رَبِّ إِنَّ قَوْمِے كَذَّبُونِ', 'قال رب إن قومے كذبون', NULL, 372, 'local:warsh-text.json'),
  ('warsh-26-118', 'warsh', 26, 118, 'فَافْتَحْ بَيْنِے وَبَيْنَهُمْ فَتْحاࣰ وَنَجِّنِے وَمَن مَّعِيَ مِنَ ࡰ۬لْمُومِنِينَ࣌', 'فافتح بينے وبينهم فتحا ونجنے ومن معي من ࡰلمومنين࣌', NULL, 372, 'local:warsh-text.json'),
  ('warsh-26-119', 'warsh', 26, 119, 'فَأَنجَيْنَٰهُ وَمَن مَّعَهُۥ فِے ࡴ۬لْفُلْكِ ࡴ۬لْمَشْحُونِ࣌', 'فأنجينه ومن معه فے ࡴلفلك ࡴلمشحون࣌', NULL, 372, 'local:warsh-text.json'),
  ('warsh-26-120', 'warsh', 26, 120, 'ثُمَّ أَغْرَقْنَا بَعْدُ ࡲ۬لْبَاقِينَ࣌', 'ثم أغرقنا بعد ࡲلباقين࣌', NULL, 372, 'local:warsh-text.json'),
  ('warsh-26-121', 'warsh', 26, 121, 'إِنَّ فِے ذَٰلِكَ لَأٓيَةࣰ࣌ وَمَا كَانَ أَكْثَرُهُم مُّومِنِينَ࣌', 'إن فے ذلك لأية࣌ وما كان أكثرهم مومنين࣌', NULL, 372, 'local:warsh-text.json'),
  ('warsh-26-122', 'warsh', 26, 122, 'وَإِنَّ رَبَّكَ لَهُوَ ࡰ۬لْعَزِيزُ ࡲ۬لرَّحِيمُ࣌', 'وإن ربك لهو ࡰلعزيز ࡲلرحيم࣌', NULL, 372, 'local:warsh-text.json'),
  ('warsh-26-123', 'warsh', 26, 123, 'كَذَّبَتْ عَادٌ ࡴ۬لْمُرْسَلِينَ', 'كذبت عاد ࡴلمرسلين', NULL, 372, 'local:warsh-text.json'),
  ('warsh-26-124', 'warsh', 26, 124, 'إِذْ قَالَ لَهُمُۥٓ أَخُوهُمْ هُودٌ ࡰلَا تَتَّقُونَ', 'إذ قال لهم أخوهم هود ࡰلا تتقون', NULL, 372, 'local:warsh-text.json'),
  ('warsh-26-125', 'warsh', 26, 125, 'إِنِّے لَكُمْ رَسُولٌ ࡰمِينࣱ࣌', 'إنے لكم رسول ࡰمين࣌', NULL, 372, 'local:warsh-text.json'),
  ('warsh-26-126', 'warsh', 26, 126, 'فَاتَّقُواْ ࡲ۬للَّهَ وَأَطِيعُونِ࣌', 'فاتقوا ࡲلله وأطيعون࣌', NULL, 372, 'local:warsh-text.json'),
  ('warsh-26-127', 'warsh', 26, 127, 'وَمَآ أَسْـَٔلُكُمْ عَلَيْهِ مِنَ ࡰجْرٍ࣌ ࡴنَ ࡰجْرِيَ إِلَّا عَلَىٰ رَبِّ ࡴ۬لْعَٰلَمِينَ࣌', 'وما أسلكم عليه من ࡰجر࣌ ࡴن ࡰجري إلا على رب ࡴلعلمين࣌', NULL, 372, 'local:warsh-text.json'),
  ('warsh-26-128', 'warsh', 26, 128, 'أَتَبْنُونَ بِكُلِّ رِيعٍ اٰيَةࣰ تَعْبَثُونَ', 'أتبنون بكل ريع اية تعبثون', NULL, 372, 'local:warsh-text.json'),
  ('warsh-26-129', 'warsh', 26, 129, 'وَتَتَّخِذُونَ مَصَانِعَ لَعَلَّكُمْ تَخْلُدُونَ', 'وتتخذون مصانع لعلكم تخلدون', NULL, 372, 'local:warsh-text.json'),
  ('warsh-26-130', 'warsh', 26, 130, 'وَإِذَا بَطَشْتُم بَطَشْتُمْ جَبّٜارِينَ࣌', 'وإذا بطشتم بطشتم جبارين࣌', NULL, 372, 'local:warsh-text.json'),
  ('warsh-26-131', 'warsh', 26, 131, 'فَاتَّقُواْ ࡲ۬للَّهَ وَأَطِيعُونِ࣌', 'فاتقوا ࡲلله وأطيعون࣌', NULL, 372, 'local:warsh-text.json'),
  ('warsh-26-132', 'warsh', 26, 132, 'وَاتَّقُواْ ࡲ۬لذِےٓ أَمَدَّكُم بِمَا تَعْلَمُونَ', 'واتقوا ࡲلذے أمدكم بما تعلمون', NULL, 372, 'local:warsh-text.json'),
  ('warsh-26-133', 'warsh', 26, 133, 'أَمَدَّكُم بِأَنْعَٰمࣲ وَبَنِينَ', 'أمدكم بأنعم وبنين', NULL, 372, 'local:warsh-text.json'),
  ('warsh-26-134', 'warsh', 26, 134, 'وَجَنَّٰتࣲ وَعُيُونٍ࣌', 'وجنت وعيون࣌', NULL, 372, 'local:warsh-text.json'),
  ('warsh-26-135', 'warsh', 26, 135, 'ࡴنِّيَ أَخَافُ عَلَيْكُمْ عَذَابَ يَوْمٍ عَظِيمࣲ࣌', 'ࡴني أخاف عليكم عذاب يوم عظيم࣌', NULL, 372, 'local:warsh-text.json'),
  ('warsh-26-136', 'warsh', 26, 136, 'قَالُواْ سَوَآءٌ عَلَيْنَآ أَوَعَظْتَ أَمْ لَمْ تَكُن مِّنَ ࡰ۬لْوَٰعِظِينَ', 'قالوا سواء علينا أوعظت أم لم تكن من ࡰلوعظين', NULL, 372, 'local:warsh-text.json'),
  ('warsh-26-137', 'warsh', 26, 137, 'إِنْ هَٰذَآ إِلَّا خُلُقُ ࡲ۬لَاوَّلِينَ', 'إن هذا إلا خلق ࡲلاولين', NULL, 373, 'local:warsh-text.json'),
  ('warsh-26-138', 'warsh', 26, 138, 'وَمَا نَحْنُ بِمُعَذَّبِينَ࣌', 'وما نحن بمعذبين࣌', NULL, 373, 'local:warsh-text.json'),
  ('warsh-26-139', 'warsh', 26, 139, 'فَكَذَّبُوهُ فَأَهْلَكْنَٰهُمُۥٓ࣌ إِنَّ فِے ذَٰلِكَ لَأٓيَةࣰ࣌ وَمَا كَانَ أَكْثَرُهُم مُّومِنِينَ࣌', 'فكذبوه فأهلكنهم࣌ إن فے ذلك لأية࣌ وما كان أكثرهم مومنين࣌', NULL, 373, 'local:warsh-text.json'),
  ('warsh-26-140', 'warsh', 26, 140, 'وَإِنَّ رَبَّكَ لَهُوَ ࡰ۬لْعَزِيزُ ࡲ۬لرَّحِيمُ࣌', 'وإن ربك لهو ࡰلعزيز ࡲلرحيم࣌', NULL, 373, 'local:warsh-text.json'),
  ('warsh-26-141', 'warsh', 26, 141, 'كَذَّبَتْ ثَمُودُ ࡲ۬لْمُرْسَلِينَ', 'كذبت ثمود ࡲلمرسلين', NULL, 373, 'local:warsh-text.json'),
  ('warsh-26-142', 'warsh', 26, 142, 'إِذْ قَالَ لَهُمُۥٓ أَخُوهُمْ صَٰلِحٌ ࡰلَا تَتَّقُونَ', 'إذ قال لهم أخوهم صلح ࡰلا تتقون', NULL, 373, 'local:warsh-text.json'),
  ('warsh-26-143', 'warsh', 26, 143, 'إِنِّے لَكُمْ رَسُولٌ ࡰمِينࣱ࣌', 'إنے لكم رسول ࡰمين࣌', NULL, 373, 'local:warsh-text.json'),
  ('warsh-26-144', 'warsh', 26, 144, 'فَاتَّقُواْ ࡲ۬للَّهَ وَأَطِيعُونِ࣌', 'فاتقوا ࡲلله وأطيعون࣌', NULL, 373, 'local:warsh-text.json'),
  ('warsh-26-145', 'warsh', 26, 145, 'وَمَآ أَسْـَٔلُكُمْ عَلَيْهِ مِنَ ࡰجْرٍ࣌ ࡴنَ ࡰجْرِيَ إِلَّا عَلَىٰ رَبِّ ࡴ۬لْعَٰلَمِينَ࣌', 'وما أسلكم عليه من ࡰجر࣌ ࡴن ࡰجري إلا على رب ࡴلعلمين࣌', NULL, 373, 'local:warsh-text.json'),
  ('warsh-26-146', 'warsh', 26, 146, '۞ أَتُتْرَكُونَ فِے مَا هَٰهُنَآ ءَامِنِينَ', 'أتتركون فے ما ههنا ءامنين', NULL, 373, 'local:warsh-text.json'),
  ('warsh-26-147', 'warsh', 26, 147, 'فِے جَنَّٰتࣲ وَعُيُونࣲ', 'فے جنت وعيون', NULL, 373, 'local:warsh-text.json'),
  ('warsh-26-148', 'warsh', 26, 148, 'وَزُرُوعࣲ وَنَخْلࣲ طَلْعُهَا هَضِيمࣱ', 'وزروع ونخل طلعها هضيم', NULL, 373, 'local:warsh-text.json'),
  ('warsh-26-149', 'warsh', 26, 149, 'وَتَنْحِتُونَ مِنَ ࡰ۬لْجِبَالِ بُيُوتاࣰ فَرِهِينَ࣌', 'وتنحتون من ࡰلجبال بيوتا فرهين࣌', NULL, 373, 'local:warsh-text.json'),
  ('warsh-26-150', 'warsh', 26, 150, 'فَاتَّقُواْ ࡲ۬للَّهَ وَأَطِيعُونِ࣌', 'فاتقوا ࡲلله وأطيعون࣌', NULL, 373, 'local:warsh-text.json'),
  ('warsh-26-151', 'warsh', 26, 151, 'وَلَا تُطِيعُوٓاْ أَمْرَ ࡰ۬لْمُسْرِفِينَ', 'ولا تطيعوا أمر ࡰلمسرفين', NULL, 373, 'local:warsh-text.json'),
  ('warsh-26-152', 'warsh', 26, 152, 'ࡰ۬لذِينَ يُفْسِدُونَ فِے ࡴ۬لَارْضِ وَلَا يُصْلِحُونَ࣌', 'ࡰلذين يفسدون فے ࡴلارض ولا يصلحون࣌', NULL, 373, 'local:warsh-text.json'),
  ('warsh-26-153', 'warsh', 26, 153, 'قَالُوٓاْ إِنَّمَآ أَنتَ مِنَ ࡰ۬لْمُسَحَّرِينَ', 'قالوا إنما أنت من ࡰلمسحرين', NULL, 373, 'local:warsh-text.json'),
  ('warsh-26-154', 'warsh', 26, 154, 'مَآ أَنتَ إِلَّا بَشَرࣱ مِّثْلُنَا فَاتِ بِـَٔايَةٍ ࡴن كُنتَ مِنَ ࡰ۬لصَّٰدِقِينَ࣌', 'ما أنت إلا بشر مثلنا فات باية ࡴن كنت من ࡰلصدقين࣌', NULL, 373, 'local:warsh-text.json'),
  ('warsh-26-155', 'warsh', 26, 155, 'قَالَ هَٰذِهِۦ نَاقَةࣱ لَّهَا شِرْبࣱ࣌ وَلَكُمْ شِرْبُ يَوْمࣲ مَّعْلُومࣲ࣌', 'قال هذه ناقة لها شرب࣌ ولكم شرب يوم معلوم࣌', NULL, 373, 'local:warsh-text.json'),
  ('warsh-26-156', 'warsh', 26, 156, 'وَلَا تَمَسُّوهَا بِسُوٓءࣲ فَيَاخُذَكُمْ عَذَابُ يَوْمٍ عَظِيمࣲ࣌', 'ولا تمسوها بسوء فياخذكم عذاب يوم عظيم࣌', NULL, 373, 'local:warsh-text.json'),
  ('warsh-26-157', 'warsh', 26, 157, 'فَعَقَرُوهَا فَأَصْبَحُواْ نَٰدِمِينَ', 'فعقروها فأصبحوا ندمين', NULL, 373, 'local:warsh-text.json'),
  ('warsh-26-158', 'warsh', 26, 158, 'فَأَخَذَهُمُ ࡲ۬لْعَذَابُ࣌ إِنَّ فِے ذَٰلِكَ لَأٓيَةࣰ࣌ وَمَا كَانَ أَكْثَرُهُم مُّومِنِينَ࣌', 'فأخذهم ࡲلعذاب࣌ إن فے ذلك لأية࣌ وما كان أكثرهم مومنين࣌', NULL, 373, 'local:warsh-text.json'),
  ('warsh-26-159', 'warsh', 26, 159, 'وَإِنَّ رَبَّكَ لَهُوَ ࡰ۬لْعَزِيزُ ࡲ۬لرَّحِيمُ࣌', 'وإن ربك لهو ࡰلعزيز ࡲلرحيم࣌', NULL, 373, 'local:warsh-text.json'),
  ('warsh-26-160', 'warsh', 26, 160, 'كَذَّبَتْ قَوْمُ لُوطٍ ࡴ۬لْمُرْسَلِينَ', 'كذبت قوم لوط ࡴلمرسلين', NULL, 374, 'local:warsh-text.json'),
  ('warsh-26-161', 'warsh', 26, 161, 'إِذْ قَالَ لَهُمُۥٓ أَخُوهُمْ لُوطٌ ࡰلَا تَتَّقُونَ', 'إذ قال لهم أخوهم لوط ࡰلا تتقون', NULL, 374, 'local:warsh-text.json'),
  ('warsh-26-162', 'warsh', 26, 162, 'إِنِّے لَكُمْ رَسُولٌ ࡰمِينࣱ࣌', 'إنے لكم رسول ࡰمين࣌', NULL, 374, 'local:warsh-text.json'),
  ('warsh-26-163', 'warsh', 26, 163, 'فَاتَّقُواْ ࡲ۬للَّهَ وَأَطِيعُونِ࣌', 'فاتقوا ࡲلله وأطيعون࣌', NULL, 374, 'local:warsh-text.json'),
  ('warsh-26-164', 'warsh', 26, 164, 'وَمَآ أَسْـَٔلُكُمْ عَلَيْهِ مِنَ ࡰجْرٍ࣌ ࡴنَ ࡰجْرِيَ إِلَّا عَلَىٰ رَبِّ ࡴ۬لْعَٰلَمِينَ࣌', 'وما أسلكم عليه من ࡰجر࣌ ࡴن ࡰجري إلا على رب ࡴلعلمين࣌', NULL, 374, 'local:warsh-text.json'),
  ('warsh-26-165', 'warsh', 26, 165, 'أَتَاتُونَ ࡰ۬لذُّكْرَانَ مِنَ ࡰ۬لْعَٰلَمِينَ', 'أتاتون ࡰلذكران من ࡰلعلمين', NULL, 374, 'local:warsh-text.json'),
  ('warsh-26-166', 'warsh', 26, 166, 'وَتَذَرُونَ مَا خَلَقَ لَكُمْ رَبُّكُم مِّنَ ࡰزْوَٰجِكُم࣌ بَلَ ࡰنتُمْ قَوْمٌ عَادُونَ࣌', 'وتذرون ما خلق لكم ربكم من ࡰزوجكم࣌ بل ࡰنتم قوم عادون࣌', NULL, 374, 'local:warsh-text.json'),
  ('warsh-26-167', 'warsh', 26, 167, 'قَالُواْ لَئِن لَّمْ تَنتَهِ يَٰلُوطُ لَتَكُونَنَّ مِنَ ࡰ۬لْمُخْرَجِينَ࣌', 'قالوا لئن لم تنته يلوط لتكونن من ࡰلمخرجين࣌', NULL, 374, 'local:warsh-text.json'),
  ('warsh-26-168', 'warsh', 26, 168, 'قَالَ إِنِّے لِعَمَلِكُم مِّنَ ࡰ۬لْقَالِينَ࣌', 'قال إنے لعملكم من ࡰلقالين࣌', NULL, 374, 'local:warsh-text.json'),
  ('warsh-26-169', 'warsh', 26, 169, 'رَبِّ نَجِّنِے وَأَهْلِے مِمَّا يَعْمَلُونَ࣌', 'رب نجنے وأهلے مما يعملون࣌', NULL, 374, 'local:warsh-text.json'),
  ('warsh-26-170', 'warsh', 26, 170, 'فَنَجَّيْنَٰهُ وَأَهْلَهُۥٓ أَجْمَعِينَ', 'فنجينه وأهله أجمعين', NULL, 374, 'local:warsh-text.json'),
  ('warsh-26-171', 'warsh', 26, 171, 'إِلَّا عَجُوزاࣰ فِے ࡴ۬لْغَٰبِرِينَ', 'إلا عجوزا فے ࡴلغبرين', NULL, 374, 'local:warsh-text.json'),
  ('warsh-26-172', 'warsh', 26, 172, 'ثُمَّ دَمَّرْنَا ࡰ۬لَاخَرِينَ࣌', 'ثم دمرنا ࡰلاخرين࣌', NULL, 374, 'local:warsh-text.json'),
  ('warsh-26-173', 'warsh', 26, 173, 'وَأَمْطَرْنَا عَلَيْهِم مَّطَراࣰ࣌ فَسَآءَ مَطَرُ ࡲ۬لْمُنذَرِينَ࣌', 'وأمطرنا عليهم مطرا࣌ فساء مطر ࡲلمنذرين࣌', NULL, 374, 'local:warsh-text.json'),
  ('warsh-26-174', 'warsh', 26, 174, 'إِنَّ فِے ذَٰلِكَ لَأٓيَةࣰ࣌ وَمَا كَانَ أَكْثَرُهُم مُّومِنِينَ࣌', 'إن فے ذلك لأية࣌ وما كان أكثرهم مومنين࣌', NULL, 374, 'local:warsh-text.json'),
  ('warsh-26-175', 'warsh', 26, 175, 'وَإِنَّ رَبَّكَ لَهُوَ ࡰ۬لْعَزِيزُ ࡲ۬لرَّحِيمُ࣌', 'وإن ربك لهو ࡰلعزيز ࡲلرحيم࣌', NULL, 374, 'local:warsh-text.json'),
  ('warsh-26-176', 'warsh', 26, 176, 'كَذَّبَ أَصْحَٰبُ لَيْكَةَ ࡰ۬لْمُرْسَلِينَ', 'كذب أصحب ليكة ࡰلمرسلين', NULL, 374, 'local:warsh-text.json'),
  ('warsh-26-177', 'warsh', 26, 177, 'إِذْ قَالَ لَهُمْ شُعَيْبٌ ࡰلَا تَتَّقُونَ', 'إذ قال لهم شعيب ࡰلا تتقون', NULL, 374, 'local:warsh-text.json'),
  ('warsh-26-178', 'warsh', 26, 178, 'إِنِّے لَكُمْ رَسُولٌ ࡰمِينࣱ࣌', 'إنے لكم رسول ࡰمين࣌', NULL, 374, 'local:warsh-text.json'),
  ('warsh-26-179', 'warsh', 26, 179, 'فَاتَّقُواْ ࡲ۬للَّهَ وَأَطِيعُونِ࣌', 'فاتقوا ࡲلله وأطيعون࣌', NULL, 374, 'local:warsh-text.json'),
  ('warsh-26-180', 'warsh', 26, 180, 'وَمَآ أَسْـَٔلُكُمْ عَلَيْهِ مِنَ ࡰجْرٍ࣌ ࡴنَ ࡰجْرِيَ إِلَّا عَلَىٰ رَبِّ ࡴ۬لْعَٰلَمِينَ࣌', 'وما أسلكم عليه من ࡰجر࣌ ࡴن ࡰجري إلا على رب ࡴلعلمين࣌', NULL, 374, 'local:warsh-text.json'),
  ('warsh-26-181', 'warsh', 26, 181, '۞ أَوْفُواْ ࡲ۬لْكَيْلَ࣌ وَلَا تَكُونُواْ مِنَ ࡰ۬لْمُخْسِرِينَ࣌', 'أوفوا ࡲلكيل࣌ ولا تكونوا من ࡰلمخسرين࣌', NULL, 374, 'local:warsh-text.json'),
  ('warsh-26-182', 'warsh', 26, 182, 'وَزِنُواْ بِالْقُسْطَاسِ ࡴ۬لْمُسْتَقِيمِ࣌', 'وزنوا بالقسطاس ࡴلمستقيم࣌', NULL, 374, 'local:warsh-text.json'),
  ('warsh-26-183', 'warsh', 26, 183, 'وَلَا تَبْخَسُواْ ࡲ۬لنَّاسَ أَشْيَآءَهُمْ࣌ وَلَا تَعْثَوْاْ فِے ࡴ۬لَارْضِ مُفْسِدِينَ࣌', 'ولا تبخسوا ࡲلناس أشياءهم࣌ ولا تعثوا فے ࡴلارض مفسدين࣌', NULL, 374, 'local:warsh-text.json'),
  ('warsh-26-184', 'warsh', 26, 184, 'وَاتَّقُواْ ࡲ۬لذِے خَلَقَكُمْ وَالْجِبِلَّةَ ࡰ۬لَاوَّلِينَ࣌', 'واتقوا ࡲلذے خلقكم والجبلة ࡰلاولين࣌', NULL, 375, 'local:warsh-text.json'),
  ('warsh-26-185', 'warsh', 26, 185, 'قَالُوٓاْ إِنَّمَآ أَنتَ مِنَ ࡰ۬لْمُسَحَّرِينَ', 'قالوا إنما أنت من ࡰلمسحرين', NULL, 375, 'local:warsh-text.json'),
  ('warsh-26-186', 'warsh', 26, 186, 'وَمَآ أَنتَ إِلَّا بَشَرࣱ مِّثْلُنَا وَإِن نَّظُنُّكَ لَمِنَ ࡰ۬لْكَٰذِبِينَ', 'وما أنت إلا بشر مثلنا وإن نظنك لمن ࡰلكذبين', NULL, 375, 'local:warsh-text.json'),
  ('warsh-26-187', 'warsh', 26, 187, 'فَأَسْقِطْ عَلَيْنَا كِسْفاࣰ مِّنَ ࡰ۬لسَّمَآءِ ان كُنتَ مِنَ ࡰ۬لصَّٰدِقِينَ࣌', 'فأسقط علينا كسفا من ࡰلسماء ان كنت من ࡰلصدقين࣌', NULL, 375, 'local:warsh-text.json'),
  ('warsh-26-188', 'warsh', 26, 188, 'قَالَ رَبِّيَ أَعْلَمُ بِمَا تَعْمَلُونَ࣌', 'قال ربي أعلم بما تعملون࣌', NULL, 375, 'local:warsh-text.json'),
  ('warsh-26-189', 'warsh', 26, 189, 'فَكَذَّبُوهُ فَأَخَذَهُمْ عَذَابُ يَوْمِ ࡴ۬لظُّلَّةِ࣌ إِنَّهُۥ كَانَ عَذَابَ يَوْمٍ عَظِيمٍ࣌', 'فكذبوه فأخذهم عذاب يوم ࡴلظلة࣌ إنه كان عذاب يوم عظيم࣌', NULL, 375, 'local:warsh-text.json'),
  ('warsh-26-190', 'warsh', 26, 190, 'ࡴنَّ فِے ذَٰلِكَ لَأٓيَةࣰ࣌ وَمَا كَانَ أَكْثَرُهُم مُّومِنِينَ࣌', 'ࡴن فے ذلك لأية࣌ وما كان أكثرهم مومنين࣌', NULL, 375, 'local:warsh-text.json'),
  ('warsh-26-191', 'warsh', 26, 191, 'وَإِنَّ رَبَّكَ لَهُوَ ࡰ۬لْعَزِيزُ ࡲ۬لرَّحِيمُ࣌', 'وإن ربك لهو ࡰلعزيز ࡲلرحيم࣌', NULL, 375, 'local:warsh-text.json'),
  ('warsh-26-192', 'warsh', 26, 192, 'وَإِنَّهُۥ لَتَنزِيلُ رَبِّ ࡴ۬لْعَٰلَمِينَ࣌', 'وإنه لتنزيل رب ࡴلعلمين࣌', NULL, 375, 'local:warsh-text.json'),
  ('warsh-26-193', 'warsh', 26, 193, 'نَزَلَ بِهِ ࡴ۬لرُّوحُ ࡲ۬لَامِينُ', 'نزل به ࡴلروح ࡲلامين', NULL, 375, 'local:warsh-text.json'),
  ('warsh-26-194', 'warsh', 26, 194, 'عَلَىٰ قَلْبِكَ لِتَكُونَ مِنَ ࡰ۬لْمُنذِرِينَ', 'على قلبك لتكون من ࡰلمنذرين', NULL, 375, 'local:warsh-text.json'),
  ('warsh-26-195', 'warsh', 26, 195, 'بِلِسَانٍ عَرَبِيࣲّ مُّبِينࣲ࣌', 'بلسان عربي مبين࣌', NULL, 375, 'local:warsh-text.json'),
  ('warsh-26-196', 'warsh', 26, 196, 'وَإِنَّهُۥ لَفِے زُبُرِ ࡴ۬لَاوَّلِينَ࣌', 'وإنه لفے زبر ࡴلاولين࣌', NULL, 375, 'local:warsh-text.json'),
  ('warsh-26-197', 'warsh', 26, 197, 'أَوَلَمْ يَكُن لَّهُمُۥٓ ءَايَةً ࡰنْ يَّعْلَمَهُۥ عُلَمَٰٓؤُاْ بَنِےٓ إِسْرَآءِيلَ࣌', 'أولم يكن لهم ءاية ࡰن يعلمه علمؤا بنے إسراءيل࣌', NULL, 375, 'local:warsh-text.json'),
  ('warsh-26-198', 'warsh', 26, 198, 'وَلَوْ نَزَّلْنَٰهُ عَلَىٰ بَعْضِ ࡴ۬لَاعْجَمِينَ', 'ولو نزلنه على بعض ࡴلاعجمين', NULL, 375, 'local:warsh-text.json'),
  ('warsh-26-199', 'warsh', 26, 199, 'فَقَرَأَهُۥ عَلَيْهِم مَّا كَانُواْ بِهِۦ مُومِنِينَ࣌', 'فقرأه عليهم ما كانوا به مومنين࣌', NULL, 375, 'local:warsh-text.json'),
  ('warsh-26-200', 'warsh', 26, 200, 'كَذَٰلِكَ سَلَكْنَٰهُ فِے قُلُوبِ ࡴ۬لْمُجْرِمِينَ', 'كذلك سلكنه فے قلوب ࡴلمجرمين', NULL, 375, 'local:warsh-text.json'),
  ('warsh-26-201', 'warsh', 26, 201, 'لَا يُومِنُونَ بِهِۦ حَتَّىٰ يَرَوُاْ ࡲ۬لْعَذَابَ ࡰ۬لَالِيمَ', 'لا يومنون به حتى يروا ࡲلعذاب ࡰلاليم', NULL, 375, 'local:warsh-text.json'),
  ('warsh-26-202', 'warsh', 26, 202, 'فَيَاتِيَهُم بَغْتَةࣰ وَهُمْ لَا يَشْعُرُونَ', 'فياتيهم بغتة وهم لا يشعرون', NULL, 375, 'local:warsh-text.json'),
  ('warsh-26-203', 'warsh', 26, 203, 'فَيَقُولُواْ هَلْ نَحْنُ مُنظَرُونَ࣌', 'فيقولوا هل نحن منظرون࣌', NULL, 375, 'local:warsh-text.json'),
  ('warsh-26-204', 'warsh', 26, 204, 'أَفَبِعَذَابِنَا يَسْتَعْجِلُونَ࣌', 'أفبعذابنا يستعجلون࣌', NULL, 375, 'local:warsh-text.json'),
  ('warsh-26-205', 'warsh', 26, 205, 'أَفَرَٰٓيْتَ إِن مَّتَّعْنَٰهُمْ سِنِينَ', 'أفريت إن متعنهم سنين', NULL, 375, 'local:warsh-text.json'),
  ('warsh-26-206', 'warsh', 26, 206, 'ثُمَّ جَآءَهُم مَّا كَانُواْ يُوعَدُونَ', 'ثم جاءهم ما كانوا يوعدون', NULL, 375, 'local:warsh-text.json'),
  ('warsh-26-207', 'warsh', 26, 207, 'مَآ أَغْنٜىٰ عَنْهُم مَّا كَانُواْ يُمَتَّعُونَ࣌', 'ما أغنى عنهم ما كانوا يمتعون࣌', NULL, 376, 'local:warsh-text.json'),
  ('warsh-26-208', 'warsh', 26, 208, 'وَمَآ أَهْلَكْنَا مِن قَرْيَةٍ ࡴلَّا لَهَا مُنذِرُونَ', 'وما أهلكنا من قرية ࡴلا لها منذرون', NULL, 376, 'local:warsh-text.json'),
  ('warsh-26-209', 'warsh', 26, 209, 'ذِكْرٜىٰ࣌ وَمَا كُنَّا ظَٰلِمِينَ࣌', 'ذكرى࣌ وما كنا ظلمين࣌', NULL, 376, 'local:warsh-text.json'),
  ('warsh-26-210', 'warsh', 26, 210, '۞ وَمَا تَنَزَّلَتْ بِهِ ࡴ۬لشَّيَٰطِينُ وَمَا يَنۢبَغِے لَهُمْ وَمَا يَسْتَطِيعُونَ࣌', 'وما تنزلت به ࡴلشيطين وما ينبغے لهم وما يستطيعون࣌', NULL, 376, 'local:warsh-text.json'),
  ('warsh-26-211', 'warsh', 26, 211, 'إِنَّهُمْ عَنِ ࡴ۬لسَّمْعِ لَمَعْزُولُونَ࣌', 'إنهم عن ࡴلسمع لمعزولون࣌', NULL, 376, 'local:warsh-text.json'),
  ('warsh-26-212', 'warsh', 26, 212, 'فَلَا تَدْعُ مَعَ ࡰ۬للَّهِ إِلَٰهاً اٰخَرَ فَتَكُونَ مِنَ ࡰ۬لْمُعَذَّبِينَ࣌', 'فلا تدع مع ࡰلله إلها اخر فتكون من ࡰلمعذبين࣌', NULL, 376, 'local:warsh-text.json'),
  ('warsh-26-213', 'warsh', 26, 213, 'وَأَنذِرْ عَشِيرَتَكَ ࡰ۬لَاقْرَبِينَ', 'وأنذر عشيرتك ࡰلاقربين', NULL, 376, 'local:warsh-text.json'),
  ('warsh-26-214', 'warsh', 26, 214, 'وَاخْفِضْ جَنَاحَكَ لِمَنِ ࡴٜتَّبَعَكَ مِنَ ࡰ۬لْمُومِنِينَ࣌', 'واخفض جناحك لمن ࡴتبعك من ࡰلمومنين࣌', NULL, 376, 'local:warsh-text.json'),
  ('warsh-26-215', 'warsh', 26, 215, 'فَإِنْ عَصَوْكَ فَقُلِ ࡴنِّے بَرِےٓءࣱ مِّمَّا تَعْمَلُونَ࣌', 'فإن عصوك فقل ࡴنے برےء مما تعملون࣌', NULL, 376, 'local:warsh-text.json'),
  ('warsh-26-216', 'warsh', 26, 216, 'فَتَوَكَّلْ عَلَى ࡰ۬لْعَزِيزِ ࡴ۬لرَّحِيمِ', 'فتوكل على ࡰلعزيز ࡴلرحيم', NULL, 376, 'local:warsh-text.json'),
  ('warsh-26-217', 'warsh', 26, 217, 'ࡴ۬لذِے يَرٜيٰكَ حِينَ تَقُومُ', 'ࡴلذے يريك حين تقوم', NULL, 376, 'local:warsh-text.json'),
  ('warsh-26-218', 'warsh', 26, 218, 'وَتَقَلُّبَكَ فِے ࡴ۬لسَّٰجِدِينَ࣌', 'وتقلبك فے ࡴلسجدين࣌', NULL, 376, 'local:warsh-text.json'),
  ('warsh-26-219', 'warsh', 26, 219, 'إِنَّهُۥ هُوَ ࡰ۬لسَّمِيعُ ࡲ۬لْعَلِيمُ࣌', 'إنه هو ࡰلسميع ࡲلعليم࣌', NULL, 376, 'local:warsh-text.json'),
  ('warsh-26-220', 'warsh', 26, 220, 'هَلُ ࡳنَبِّئُكُمْ عَلَىٰ مَن تَنَزَّلُ ࡲ۬لشَّيَٰطِينُ', 'هل ࡳنبئكم على من تنزل ࡲلشيطين', NULL, 376, 'local:warsh-text.json'),
  ('warsh-26-221', 'warsh', 26, 221, 'تَنَزَّلُ عَلَىٰ كُلِّ أَفَّاكٍ ࡰثِيمࣲ', 'تنزل على كل أفاك ࡰثيم', NULL, 376, 'local:warsh-text.json'),
  ('warsh-26-222', 'warsh', 26, 222, 'يُلْقُونَ ࡰ۬لسَّمْعَ وَأَكْثَرُهُمْ كَٰذِبُونَ࣌', 'يلقون ࡰلسمع وأكثرهم كذبون࣌', NULL, 376, 'local:warsh-text.json'),
  ('warsh-26-223', 'warsh', 26, 223, 'وَالشُّعَرَآءُ يَتْبَعُهُمُ ࡲ۬لْغَاوُۥنَ࣌', 'والشعراء يتبعهم ࡲلغاون࣌', NULL, 376, 'local:warsh-text.json'),
  ('warsh-26-224', 'warsh', 26, 224, 'أَلَمْ تَرَ أَنَّهُمْ فِے كُلِّ وَادࣲ يَهِيمُونَ', 'ألم تر أنهم فے كل واد يهيمون', NULL, 376, 'local:warsh-text.json'),
  ('warsh-26-225', 'warsh', 26, 225, 'وَأَنَّهُمْ يَقُولُونَ مَا لَا يَفْعَلُونَ࣌', 'وأنهم يقولون ما لا يفعلون࣌', NULL, 376, 'local:warsh-text.json'),
  ('warsh-26-226', 'warsh', 26, 226, 'إِلَّا ࡰ۬لذِينَ ءَامَنُواْ وَعَمِلُواْ ࡲ۬لصَّٰلِحَٰتِ وَذَكَرُواْ ࡲ۬للَّهَ كَثِيراࣰ وَانتَصَرُواْ مِنۢ بَعْدِ مَا ظُلِمُواْ࣌ وَسَيَعْلَمُ ࡲ۬لذِينَ ظَلَمُوٓاْ أَيَّ مُنقَلَبࣲ يَنقَلِبُونَ࣌', 'إلا ࡰلذين ءامنوا وعملوا ࡲلصلحت وذكروا ࡲلله كثيرا وانتصروا من بعد ما ظلموا࣌ وسيعلم ࡲلذين ظلموا أي منقلب ينقلبون࣌', NULL, 376, 'local:warsh-text.json'),
  ('warsh-27-1', 'warsh', 27, 1, 'طَسِٓ࣌ تِلْكَ ءَايَٰتُ ࡲ۬لْقُرْءَانِ وَكِتَابࣲ مُّبِينٍ࣌', 'طس࣌ تلك ءايت ࡲلقرءان وكتاب مبين࣌', NULL, 377, 'local:warsh-text.json'),
  ('warsh-27-2', 'warsh', 27, 2, 'هُدىࣰ وَبُشْرٜىٰ لِلْمُومِنِينَ', 'هدى وبشرى للمومنين', NULL, 377, 'local:warsh-text.json'),
  ('warsh-27-3', 'warsh', 27, 3, 'ࡰ۬لذِينَ يُقِيمُونَ ࡰ۬لصَّلَوٰةَ وَيُوتُونَ ࡰ۬لزَّكَوٰةَ وَهُم بِالَاخِرَةِ هُمْ يُوقِنُونَ࣌', 'ࡰلذين يقيمون ࡰلصلوة ويوتون ࡰلزكوة وهم بالاخرة هم يوقنون࣌', NULL, 377, 'local:warsh-text.json'),
  ('warsh-27-4', 'warsh', 27, 4, 'إِنَّ ࡰ۬لذِينَ لَا يُومِنُونَ بِالَاخِرَةِ زَيَّنَّا لَهُمُۥٓ أَعْمَٰلَهُمْ فَهُمْ يَعْمَهُونَ࣌', 'إن ࡰلذين لا يومنون بالاخرة زينا لهم أعملهم فهم يعمهون࣌', NULL, 377, 'local:warsh-text.json'),
  ('warsh-27-5', 'warsh', 27, 5, 'أُوْلَٰٓئِكَ ࡰ۬لذِينَ لَهُمْ سُوٓءُ ࡲ۬لْعَذَابِ وَهُمْ فِے ࡴ۬لَاخِرَةِ هُمُ ࡲ۬لَاخْسَرُونَ࣌', 'أولئك ࡰلذين لهم سوء ࡲلعذاب وهم فے ࡴلاخرة هم ࡲلاخسرون࣌', NULL, 377, 'local:warsh-text.json'),
  ('warsh-27-6', 'warsh', 27, 6, '۞ وَإِنَّكَ لَتُلَقَّى ࡰ۬لْقُرْءَانَ مِن لَّدُنْ حَكِيمٍ عَلِيمٍ࣌', 'وإنك لتلقى ࡰلقرءان من لدن حكيم عليم࣌', NULL, 377, 'local:warsh-text.json'),
  ('warsh-27-7', 'warsh', 27, 7, 'ࡴذْ قَالَ مُوسٜىٰ لِأَهْلِهِۦٓ إِنِّيَ ءَانَسْتُ نَاراࣰ سَـَٔاتِيكُم مِّنْهَا بِخَبَرٍ ࡰوَ اٰتِيكُم بِشِهَابِ قَبَسࣲ لَّعَلَّكُمْ تَصْطَلُونَ࣌', 'ࡴذ قال موسى لأهله إني ءانست نارا ساتيكم منها بخبر ࡰو اتيكم بشهاب قبس لعلكم تصطلون࣌', NULL, 377, 'local:warsh-text.json'),
  ('warsh-27-8', 'warsh', 27, 8, 'فَلَمَّا جَآءَهَا نُودِيَ أَنۢ بُورِكَ مَن فِے ࡴ۬لنّٜارِ وَمَنْ حَوْلَهَا࣌ وَسُبْحَٰنَ ࡰ۬للَّهِ رَبِّ ࡴ۬لْعَٰلَمِينَ࣌', 'فلما جاءها نودي أن بورك من فے ࡴلنار ومن حولها࣌ وسبحن ࡰلله رب ࡴلعلمين࣌', NULL, 377, 'local:warsh-text.json'),
  ('warsh-27-9', 'warsh', 27, 9, 'يَٰمُوسٜىٰٓ إِنَّهُۥٓ أَنَا ࡰ۬للَّهُ ࡲ۬لْعَزِيزُ ࡲ۬لْحَكِيمُ', 'يموسى إنه أنا ࡰلله ࡲلعزيز ࡲلحكيم', NULL, 377, 'local:warsh-text.json'),
  ('warsh-27-10', 'warsh', 27, 10, 'وَأَلْقِ عَصَاكَ࣌ فَلَمَّا رٜءٜاهَا تَهْتَزُّ كَأَنَّهَا جَآنࣱّ وَلّٜىٰ مُدْبِراࣰ وَلَمْ يُعَقِّبْ࣌ يَٰمُوسٜىٰ لَا تَخَفِ࣌ ࡴنِّے لَا يَخَافُ لَدَيَّ ࡰ۬لْمُرْسَلُونَ࣌', 'وألق عصاك࣌ فلما رءاها تهتز كأنها جان ولى مدبرا ولم يعقب࣌ يموسى لا تخف࣌ ࡴنے لا يخاف لدي ࡰلمرسلون࣌', NULL, 377, 'local:warsh-text.json'),
  ('warsh-27-11', 'warsh', 27, 11, 'إِلَّا مَن ظَلَمَ ثُمَّ بَدَّلَ حُسْناَۢ بَعْدَ سُوٓءࣲ فَإِنِّے غَفُورࣱ رَّحِيمࣱ࣌', 'إلا من ظلم ثم بدل حسنا بعد سوء فإنے غفور رحيم࣌', NULL, 377, 'local:warsh-text.json'),
  ('warsh-27-12', 'warsh', 27, 12, 'وَأَدْخِلْ يَدَكَ فِے جَيْبِكَ تَخْرُجْ بَيْضَآءَ مِنْ غَيْرِ سُوٓءࣲ࣌ فِے تِسْعِ ءَايَٰتٍ ࡴلَىٰ فِرْعَوْنَ وَقَوْمِهِۦٓ࣌ إِنَّهُمْ كَانُواْ قَوْماࣰ فَٰسِقِينَ࣌', 'وأدخل يدك فے جيبك تخرج بيضاء من غير سوء࣌ فے تسع ءايت ࡴلى فرعون وقومه࣌ إنهم كانوا قوما فسقين࣌', NULL, 377, 'local:warsh-text.json'),
  ('warsh-27-13', 'warsh', 27, 13, 'فَلَمَّا جَآءَتْهُمُۥٓ ءَايَٰتُنَا مُبْصِرَةࣰ قَالُواْ هَٰذَا سِحْرࣱ مُّبِينࣱ࣌', 'فلما جاءتهم ءايتنا مبصرة قالوا هذا سحر مبين࣌', NULL, 377, 'local:warsh-text.json'),
  ('warsh-27-14', 'warsh', 27, 14, 'وَجَحَدُواْ بِهَا وَاسْتَيْقَنَتْهَآ أَنفُسُهُمْ ظُلْماࣰ وَعُلُوّاࣰ࣌ فَانظُرْ كَيْفَ كَانَ عَٰقِبَةُ ࡲ۬لْمُفْسِدِينَ࣌', 'وجحدوا بها واستيقنتها أنفسهم ظلما وعلوا࣌ فانظر كيف كان عقبة ࡲلمفسدين࣌', NULL, 378, 'local:warsh-text.json'),
  ('warsh-27-15', 'warsh', 27, 15, 'وَلَقَدَ اٰتَيْنَا دَاوُۥدَ وَسُلَيْمَٰنَ عِلْماࣰ وَقَالَا ࡰ۬لْحَمْدُ لِلهِ ࡴ۬لذِے فَضَّلَنَا عَلَىٰ كَثِيرࣲ مِّنْ عِبَادِهِ ࡴ۬لْمُومِنِينَ࣌', 'ولقد اتينا داود وسليمن علما وقالا ࡰلحمد لله ࡴلذے فضلنا على كثير من عباده ࡴلمومنين࣌', NULL, 378, 'local:warsh-text.json'),
  ('warsh-27-16', 'warsh', 27, 16, 'وَوَرِثَ سُلَيْمَٰنُ دَاوُۥدَ وَقَالَ يَٰٓأَيُّهَا ࡰ۬لنَّاسُ عُلِّمْنَا مَنطِقَ ࡰ۬لطَّيْرِ وَأُوتِينَا مِن كُلِّ شَےْءٍ࣌ ࡴنَّ هَٰذَا لَهُوَ ࡰ۬لْفَضْلُ ࡲ۬لْمُبِينُ࣌', 'وورث سليمن داود وقال يأيها ࡰلناس علمنا منطق ࡰلطير وأوتينا من كل شےء࣌ ࡴن هذا لهو ࡰلفضل ࡲلمبين࣌', NULL, 378, 'local:warsh-text.json'),
  ('warsh-27-17', 'warsh', 27, 17, '۞ وَحُشِرَ لِسُلَيْمَٰنَ جُنُودُهُۥ مِنَ ࡰ۬لْجِنِّ وَالِانسِ وَالطَّيْرِ فَهُمْ يُوزَعُونَ࣌', 'وحشر لسليمن جنوده من ࡰلجن والانس والطير فهم يوزعون࣌', NULL, 378, 'local:warsh-text.json'),
  ('warsh-27-18', 'warsh', 27, 18, 'حَتَّىٰٓ إِذَآ أَتَوْاْ عَلَىٰ وَادِ ࡴ۬لنَّمْلِ قَالَتْ نَمْلَةࣱ يَٰٓأَيُّهَا ࡰ۬لنَّمْلُ ࡲ࢈دْخُلُواْ مَسَٰكِنَكُمْ لَا يَحْطِمَنَّكُمْ سُلَيْمَٰنُ وَجُنُودُهُۥ وَهُمْ لَا يَشْعُرُونَ࣌', 'حتى إذا أتوا على واد ࡴلنمل قالت نملة يأيها ࡰلنمل ࡲ࢈دخلوا مسكنكم لا يحطمنكم سليمن وجنوده وهم لا يشعرون࣌', NULL, 378, 'local:warsh-text.json'),
  ('warsh-27-19', 'warsh', 27, 19, 'فَتَبَسَّمَ ضَاحِكاࣰ مِّن قَوْلِهَا وَقَالَ رَبِّ أَوْزِعْنِيَ أَنَ ࡰشْكُرَ نِعْمَتَكَ ࡰ۬لتِےٓ أَنْعَمْتَ عَلَيَّ وَعَلَىٰ وَٰلِدَيَّ وَأَنَ ࡰعْمَلَ صَٰلِحاࣰ تَرْضٜيٰهُ وَأَدْخِلْنِے بِرَحْمَتِكَ فِے عِبَادِكَ ࡰ۬لصَّٰلِحِينَ࣌', 'فتبسم ضاحكا من قولها وقال رب أوزعني أن ࡰشكر نعمتك ࡰلتے أنعمت علي وعلى ولدي وأن ࡰعمل صلحا ترضيه وأدخلنے برحمتك فے عبادك ࡰلصلحين࣌', NULL, 378, 'local:warsh-text.json'),
  ('warsh-27-20', 'warsh', 27, 20, 'وَتَفَقَّدَ ࡰ۬لطَّيْرَ فَقَالَ مَا لِے لَآ أَرَى ࡰ۬لْهُدْهُدَ أَمْ كَانَ مِنَ ࡰ۬لْغَآئِبِينَ࣌', 'وتفقد ࡰلطير فقال ما لے لا أرى ࡰلهدهد أم كان من ࡰلغائبين࣌', NULL, 378, 'local:warsh-text.json'),
  ('warsh-27-21', 'warsh', 27, 21, 'لَأُعَذِّبَنَّهُۥ عَذَاباࣰ شَدِيداً ࡰوْ لَأَاْذْبَحَنَّهُۥٓ أَوْ لَيَاتِيَنِّے بِسُلْطَٰنࣲ مُّبِينࣲ࣌', 'لأعذبنه عذابا شديدا ࡰو لأاذبحنه أو لياتينے بسلطن مبين࣌', NULL, 378, 'local:warsh-text.json'),
  ('warsh-27-22', 'warsh', 27, 22, 'فَمَكُثَ غَيْرَ بَعِيدࣲ࣌ فَقَالَ أَحَطْتُّ بِمَا لَمْ تُحِطْ بِهِۦ وَجِئْتُكَ مِن سَبَإِۢ بِنَبَإࣲ يَقِينٍ࣌', 'فمكث غير بعيد࣌ فقال أحطت بما لم تحط به وجئتك من سبإ بنبإ يقين࣌', NULL, 378, 'local:warsh-text.json'),
  ('warsh-27-23', 'warsh', 27, 23, 'ࡴنِّے وَجَدتُّ ࡲٜمْرَأَةࣰ تَمْلِكُهُمْ وَأُوتِيَتْ مِن كُلِّ شَےْءࣲ࣌ وَلَهَا عَرْشٌ عَظِيمࣱ࣌', 'ࡴنے وجدت ࡲمرأة تملكهم وأوتيت من كل شےء࣌ ولها عرش عظيم࣌', NULL, 379, 'local:warsh-text.json'),
  ('warsh-27-24', 'warsh', 27, 24, 'وَجَدتُّهَا وَقَوْمَهَا يَسْجُدُونَ لِلشَّمْسِ مِن دُونِ ࡴ۬للَّهِ وَزَيَّنَ لَهُمُ ࡲ۬لشَّيْطَٰنُ أَعْمَٰلَهُمْ فَصَدَّهُمْ عَنِ ࡴ۬لسَّبِيلِ فَهُمْ لَا يَهْتَدُونَ', 'وجدتها وقومها يسجدون للشمس من دون ࡴلله وزين لهم ࡲلشيطن أعملهم فصدهم عن ࡴلسبيل فهم لا يهتدون', NULL, 379, 'local:warsh-text.json'),
  ('warsh-27-25', 'warsh', 27, 25, 'أَلَّا يَسْجُدُواْ لِلهِ ࡴ۬لذِے يُخْرِجُ ࡲ۬لْخَبْءَ فِے ࡴ۬لسَّمَٰوَٰتِ وَالَارْضِ وَيَعْلَمُ مَا يُخْفُونَ وَمَا يُعْلِنُونَ࣌', 'ألا يسجدوا لله ࡴلذے يخرج ࡲلخبء فے ࡴلسموت والارض ويعلم ما يخفون وما يعلنون࣌', NULL, 379, 'local:warsh-text.json'),
  ('warsh-27-26', 'warsh', 27, 26, 'ࡰ۬للَّهُ لَآ إِلَٰهَ إِلَّا هُوَ رَبُّ ࡲ۬لْعَرْشِ ࡴ۬لْعَظِيمِ࣌۩', 'ࡰلله لا إله إلا هو رب ࡲلعرش ࡴلعظيم࣌', NULL, 379, 'local:warsh-text.json'),
  ('warsh-27-27', 'warsh', 27, 27, '۞ قَالَ سَنَنظُرُ أَصَدَقْتَ أَمْ كُنتَ مِنَ ࡰ۬لْكَٰذِبِينَ࣌', 'قال سننظر أصدقت أم كنت من ࡰلكذبين࣌', NULL, 379, 'local:warsh-text.json'),
  ('warsh-27-28', 'warsh', 27, 28, 'ࡰٜذْهَب بِّكِتَٰبِے هَٰذَا فَأَلْقِهِۦٓ إِلَيْهِمْ ثُمَّ تَوَلَّ عَنْهُمْ فَانظُرْ مَاذَا يَرْجِعُونَ࣌', 'ࡰذهب بكتبے هذا فألقه إليهم ثم تول عنهم فانظر ماذا يرجعون࣌', NULL, 379, 'local:warsh-text.json'),
  ('warsh-27-29', 'warsh', 27, 29, 'قَالَتْ يَٰٓأَيُّهَا ࡰ۬لْمَلَؤُاْ ࡹِنِّيَ أُلْقِيَ إِلَيَّ كِتَٰبࣱ كَرِيمٌ', 'قالت يأيها ࡰلملؤا ࡹني ألقي إلي كتب كريم', NULL, 379, 'local:warsh-text.json'),
  ('warsh-27-30', 'warsh', 27, 30, 'ࡴنَّهُۥ مِن سُلَيْمَٰنَ وَإِنَّهُۥ بِسْمِ ࡴ۬للَّهِ ࡴ۬لرَّحْمَٰنِ ࡴ۬لرَّحِيمِ', 'ࡴنه من سليمن وإنه بسم ࡴلله ࡴلرحمن ࡴلرحيم', NULL, 379, 'local:warsh-text.json'),
  ('warsh-27-31', 'warsh', 27, 31, 'أَلَّا تَعْلُواْ عَلَيَّ وَاتُونِے مُسْلِمِينَ࣌', 'ألا تعلوا علي واتونے مسلمين࣌', NULL, 379, 'local:warsh-text.json'),
  ('warsh-27-32', 'warsh', 27, 32, 'قَالَتْ يَٰٓأَيُّهَا ࡰ۬لْمَلَؤُاْ ࡶَفْتُونِے فِےٓ أَمْرِے مَا كُنتُ قَاطِعَةً ࡰمْراً حَتَّىٰ تَشْهَدُونِ࣌', 'قالت يأيها ࡰلملؤا ࡶفتونے فے أمرے ما كنت قاطعة ࡰمرا حتى تشهدون࣌', NULL, 379, 'local:warsh-text.json'),
  ('warsh-27-33', 'warsh', 27, 33, 'قَالُواْ نَحْنُ أُوْلُواْ قُوَّةࣲ وَأُوْلُواْ بَأْسࣲ شَدِيدࣲ', 'قالوا نحن أولوا قوة وأولوا بأس شديد', NULL, 379, 'local:warsh-text.json'),
  ('warsh-27-34', 'warsh', 27, 34, 'وَالَامْرُ إِلَيْكِ فَانظُرِے مَاذَا تَامُرِينَ࣌', 'والامر إليك فانظرے ماذا تامرين࣌', NULL, 379, 'local:warsh-text.json'),
  ('warsh-27-35', 'warsh', 27, 35, 'قَالَتِ ࡴنَّ ࡰ۬لْمُلُوكَ إِذَا دَخَلُواْ قَرْيَةً ࡰفْسَدُوهَا وَجَعَلُوٓاْ أَعِزَّةَ أَهْلِهَآ أَذِلَّةࣰ࣌ وَكَذَٰلِكَ يَفْعَلُونَ࣌', 'قالت ࡴن ࡰلملوك إذا دخلوا قرية ࡰفسدوها وجعلوا أعزة أهلها أذلة࣌ وكذلك يفعلون࣌', NULL, 379, 'local:warsh-text.json'),
  ('warsh-27-36', 'warsh', 27, 36, 'وَإِنِّے مُرْسِلَةٌ ࡴلَيْهِم بِهَدِيَّةࣲ فَنَٰظِرَةُۢ بِمَ يَرْجِعُ ࡲ۬لْمُرْسَلُونَ࣌', 'وإنے مرسلة ࡴليهم بهدية فنظرة بم يرجع ࡲلمرسلون࣌', NULL, 379, 'local:warsh-text.json'),
  ('warsh-27-37', 'warsh', 27, 37, 'فَلَمَّا جَآءَ سُلَيْمَٰنَ قَالَ أَتُمِدُّونَنِۦ بِمَالࣲ فَمَآ ءَاتٜيٰنِࣉَ ࡰ۬للَّهُ خَيْرࣱ مِّمَّآ ءَاتٜيٰكُم بَلَ ࡰنتُم بِهَدِيَّتِكُمْ تَفْرَحُونَ࣌', 'فلما جاء سليمن قال أتمدونن بمال فما ءاتينࣉ ࡰلله خير مما ءاتيكم بل ࡰنتم بهديتكم تفرحون࣌', NULL, 380, 'local:warsh-text.json'),
  ('warsh-27-38', 'warsh', 27, 38, 'ࡰٜرْجِعِ ࡴلَيْهِمْ فَلَنَاتِيَنَّهُم بِجُنُودࣲ لَّا قِبَلَ لَهُم بِهَا وَلَنُخْرِجَنَّهُم مِّنْهَآ أَذِلَّةࣰ وَهُمْ صَٰغِرُونَ࣌', 'ࡰرجع ࡴليهم فلناتينهم بجنود لا قبل لهم بها ولنخرجنهم منها أذلة وهم صغرون࣌', NULL, 380, 'local:warsh-text.json'),
  ('warsh-27-39', 'warsh', 27, 39, 'قَالَ يَٰٓأَيُّهَا ࡰ۬لْمَلَؤُاْ ࡶَيُّكُمْ يَاتِينِے بِعَرْشِهَا قَبْلَ أَنْ يَّاتُونِے مُسْلِمِينَ࣌', 'قال يأيها ࡰلملؤا ࡶيكم ياتينے بعرشها قبل أن ياتونے مسلمين࣌', NULL, 380, 'local:warsh-text.json'),
  ('warsh-27-40', 'warsh', 27, 40, 'قَالَ عِفْرِيتࣱ مِّنَ ࡰ۬لْجِنِّ أَنَآ ءَاتِيكَ بِهِۦ قَبْلَ أَن تَقُومَ مِن مَّقَامِكَ وَإِنِّے عَلَيْهِ لَقَوِيٌّ ࡰمِينࣱ࣌', 'قال عفريت من ࡰلجن أنا ءاتيك به قبل أن تقوم من مقامك وإنے عليه لقوي ࡰمين࣌', NULL, 380, 'local:warsh-text.json'),
  ('warsh-27-41', 'warsh', 27, 41, 'قَالَ ࡰ۬لذِے عِندَهُۥ عِلْمࣱ مِّنَ ࡰ۬لْكِتَٰبِ أَنَآ ءَاتِيكَ بِهِۦ قَبْلَ أَنْ يَّرْتَدَّ إِلَيْكَ طَرْفُكَ࣌ فَلَمَّا رٜءٜاهُ مُسْتَقِرّاً عِندَهُۥ قَالَ هَٰذَا مِن فَضْلِ رَبِّے لِيَبْلُوَنِيَ ءَآشْكُرُ أَمَ ࡰكْفُرُ࣌ وَمَن شَكَرَ فَإِنَّمَا يَشْكُرُ لِنَفْسِهِۦ࣌ وَمَن كَفَرَ فَإِنَّ رَبِّے غَنِيࣱّ كَرِيمࣱ࣌', 'قال ࡰلذے عنده علم من ࡰلكتب أنا ءاتيك به قبل أن يرتد إليك طرفك࣌ فلما رءاه مستقرا عنده قال هذا من فضل ربے ليبلوني ءاشكر أم ࡰكفر࣌ ومن شكر فإنما يشكر لنفسه࣌ ومن كفر فإن ربے غني كريم࣌', NULL, 380, 'local:warsh-text.json'),
  ('warsh-27-42', 'warsh', 27, 42, '۞ قَالَ نَكِّرُواْ لَهَا عَرْشَهَا نَنظُرَ ࡰتَهْتَدِےٓ أَمْ تَكُونُ مِنَ ࡰ۬لذِينَ لَا يَهْتَدُونَ࣌', 'قال نكروا لها عرشها ننظر ࡰتهتدے أم تكون من ࡰلذين لا يهتدون࣌', NULL, 380, 'local:warsh-text.json'),
  ('warsh-27-43', 'warsh', 27, 43, 'فَلَمَّا جَآءَتْ قِيلَ أَهَٰكَذَا عَرْشُكِ قَالَتْ كَأَنَّهُۥ هُوَ࣌ وَأُوتِينَا ࡰ۬لْعِلْمَ مِن قَبْلِهَا وَكُنَّا مُسْلِمِينَ࣌', 'فلما جاءت قيل أهكذا عرشك قالت كأنه هو࣌ وأوتينا ࡰلعلم من قبلها وكنا مسلمين࣌', NULL, 380, 'local:warsh-text.json'),
  ('warsh-27-44', 'warsh', 27, 44, 'وَصَدَّهَا مَا كَانَت تَّعْبُدُ مِن دُونِ ࡴ۬للَّهِ࣌ إِنَّهَا كَانَتْ مِن قَوْمࣲ كٜـٰفِرِينَ࣌', 'وصدها ما كانت تعبد من دون ࡴلله࣌ إنها كانت من قوم كفرين࣌', NULL, 380, 'local:warsh-text.json'),
  ('warsh-27-45', 'warsh', 27, 45, 'قِيلَ لَهَا ࡸَدْخُلِے ࡴ۬لصَّرْحَ࣌ فَلَمَّا رَأَتْهُ حَسِبَتْهُ لُجَّةࣰ وَكَشَفَتْ عَن سَاقَيْهَا࣌ قَالَ إِنَّهُۥ صَرْحࣱ مُّمَرَّدࣱ مِّن قَوَارِيرَ࣌', 'قيل لها ࡸدخلے ࡴلصرح࣌ فلما رأته حسبته لجة وكشفت عن ساقيها࣌ قال إنه صرح ممرد من قوارير࣌', NULL, 380, 'local:warsh-text.json'),
  ('warsh-27-46', 'warsh', 27, 46, 'قَالَتْ رَبِّ إِنِّے ظَلَمْتُ نَفْسِے وَأَسْلَمْتُ مَعَ سُلَيْمَٰنَ لِلهِ رَبِّ ࡴ۬لْعَٰلَمِينَ࣌', 'قالت رب إنے ظلمت نفسے وأسلمت مع سليمن لله رب ࡴلعلمين࣌', NULL, 380, 'local:warsh-text.json'),
  ('warsh-27-47', 'warsh', 27, 47, 'وَلَقَدَ ࡰرْسَلْنَآ إِلَىٰ ثَمُودَ أَخَاهُمْ صَٰلِحاً ࡰنُ ࡲ࢈عْبُدُواْ ࡲ۬للَّهَ فَإِذَا هُمْ فَرِيقَٰنِ يَخْتَصِمُونَ࣌', 'ولقد ࡰرسلنا إلى ثمود أخاهم صلحا ࡰن ࡲ࢈عبدوا ࡲلله فإذا هم فريقن يختصمون࣌', NULL, 381, 'local:warsh-text.json')
insert into public.ayahs (id, riwayah, surah_number, ayah_number, text, simple_text, juz, page, source) values
  ('warsh-27-48', 'warsh', 27, 48, 'قَالَ يَٰقَوْمِ لِمَ تَسْتَعْجِلُونَ بِالسَّيِّئَةِ قَبْلَ ࡰ۬لْحَسَنَةِ لَوْلَا تَسْتَغْفِرُونَ ࡰ۬للَّهَ لَعَلَّكُمْ تُرْحَمُونَ࣌', 'قال يقوم لم تستعجلون بالسيئة قبل ࡰلحسنة لولا تستغفرون ࡰلله لعلكم ترحمون࣌', NULL, 381, 'local:warsh-text.json'),
  ('warsh-27-49', 'warsh', 27, 49, 'قَالُواْ ࡲٜطَّيَّرْنَا بِكَ وَبِمَن مَّعَكَ࣌ قَالَ طَٰٓئِرُكُمْ عِندَ ࡰ۬للَّهِ࣌ بَلَ ࡰنتُمْ قَوْمࣱ تُفْتَنُونَ࣌', 'قالوا ࡲطيرنا بك وبمن معك࣌ قال طئركم عند ࡰلله࣌ بل ࡰنتم قوم تفتنون࣌', NULL, 381, 'local:warsh-text.json'),
  ('warsh-27-50', 'warsh', 27, 50, 'وَكَانَ فِے ࡴ۬لْمَدِينَةِ تِسْعَةُ رَهْطࣲ يُفْسِدُونَ فِے ࡴ۬لَارْضِ وَلَا يُصْلِحُونَ࣌', 'وكان فے ࡴلمدينة تسعة رهط يفسدون فے ࡴلارض ولا يصلحون࣌', NULL, 381, 'local:warsh-text.json'),
  ('warsh-27-51', 'warsh', 27, 51, 'قَالُواْ تَقَاسَمُواْ بِاللَّهِ لَنُبَيِّتَنَّهُۥ وَأَهْلَهُۥ ثُمَّ لَنَقُولَنَّ لِوَلِيِّهِۦ مَا شَهِدْنَا مُهْلَكَ أَهْلِهِۦ وَإِنَّا لَصَٰدِقُونَ࣌', 'قالوا تقاسموا بالله لنبيتنه وأهله ثم لنقولن لوليه ما شهدنا مهلك أهله وإنا لصدقون࣌', NULL, 381, 'local:warsh-text.json'),
  ('warsh-27-52', 'warsh', 27, 52, 'وَمَكَرُواْ مَكْراࣰ وَمَكَرْنَا مَكْراࣰ وَهُمْ لَا يَشْعُرُونَ࣌', 'ومكروا مكرا ومكرنا مكرا وهم لا يشعرون࣌', NULL, 381, 'local:warsh-text.json'),
  ('warsh-27-53', 'warsh', 27, 53, 'فَانظُرْ كَيْفَ كَانَ عَٰقِبَةُ مَكْرِهِمُۥٓ࣌ إِنَّا دَمَّرْنَٰهُمْ وَقَوْمَهُمُۥٓ أَجْمَعِينَ࣌', 'فانظر كيف كان عقبة مكرهم࣌ إنا دمرنهم وقومهم أجمعين࣌', NULL, 381, 'local:warsh-text.json'),
  ('warsh-27-54', 'warsh', 27, 54, 'فَتِلْكَ بُيُوتُهُمْ خَاوِيَةَۢ بِمَا ظَلَمُوٓاْ࣌ إِنَّ فِے ذَٰلِكَ لَأٓيَةࣰ لِّقَوْمࣲ يَعْلَمُونَ࣌', 'فتلك بيوتهم خاوية بما ظلموا࣌ إن فے ذلك لأية لقوم يعلمون࣌', NULL, 381, 'local:warsh-text.json'),
  ('warsh-27-55', 'warsh', 27, 55, 'وَأَنجَيْنَا ࡰ۬لذِينَ ءَامَنُواْ وَكَانُواْ يَتَّقُونَ࣌', 'وأنجينا ࡰلذين ءامنوا وكانوا يتقون࣌', NULL, 381, 'local:warsh-text.json'),
  ('warsh-27-56', 'warsh', 27, 56, 'وَلُوطاً ࡴذْ قَالَ لِقَوْمِهِۦٓ أَتَاتُونَ ࡰ۬لْفَٰحِشَةَ وَأَنتُمْ تُبْصِرُونَ࣌', 'ولوطا ࡴذ قال لقومه أتاتون ࡰلفحشة وأنتم تبصرون࣌', NULL, 381, 'local:warsh-text.json'),
  ('warsh-27-57', 'warsh', 27, 57, 'أَئِنَّكُمْ لَتَاتُونَ ࡰ۬لرِّجَالَ شَهْوَةࣰ مِّن دُونِ ࡴ۬لنِّسَآءِ࣌ بَلَ ࡰنتُمْ قَوْمࣱ تَجْهَلُونَ࣌', 'أئنكم لتاتون ࡰلرجال شهوة من دون ࡴلنساء࣌ بل ࡰنتم قوم تجهلون࣌', NULL, 381, 'local:warsh-text.json'),
  ('warsh-27-58', 'warsh', 27, 58, '۞ فَمَا كَانَ جَوَابَ قَوْمِهِۦٓ إِلَّآ أَن قَالُوٓاْ أَخْرِجُوٓاْ ءَالَ لُوطࣲ مِّن قَرْيَتِكُمُۥٓ࣌ إِنَّهُمُۥٓ أُنَاسࣱ يَتَطَهَّرُونَ࣌', 'فما كان جواب قومه إلا أن قالوا أخرجوا ءال لوط من قريتكم࣌ إنهم أناس يتطهرون࣌', NULL, 382, 'local:warsh-text.json'),
  ('warsh-27-59', 'warsh', 27, 59, 'فَأَنجَيْنَٰهُ وَأَهْلَهُۥٓ إِلَّا ࡰٜمْرَأَتَهُۥ قَدَّرْنَٰهَا مِنَ ࡰ۬لْغَٰبِرِينَ࣌', 'فأنجينه وأهله إلا ࡰمرأته قدرنها من ࡰلغبرين࣌', NULL, 382, 'local:warsh-text.json'),
  ('warsh-27-60', 'warsh', 27, 60, 'وَأَمْطَرْنَا عَلَيْهِم مَّطَراࣰ࣌ فَسَآءَ مَطَرُ ࡲ۬لْمُنذَرِينَ࣌', 'وأمطرنا عليهم مطرا࣌ فساء مطر ࡲلمنذرين࣌', NULL, 382, 'local:warsh-text.json'),
  ('warsh-27-61', 'warsh', 27, 61, 'قُلِ ࡴ۬لْحَمْدُ لِلهِ وَسَلَٰمٌ عَلَىٰ عِبَادِهِ ࡴ۬لذِينَ ࡰٜصْطَفٜىٰٓ࣌ ءَآللَّهُ خَيْرٌ ࡰمَّا تُشْرِكُونَ࣌', 'قل ࡴلحمد لله وسلم على عباده ࡴلذين ࡰصطفى࣌ ءالله خير ࡰما تشركون࣌', NULL, 382, 'local:warsh-text.json'),
  ('warsh-27-62', 'warsh', 27, 62, 'أَمَّنْ خَلَقَ ࡰ۬لسَّمَٰوَٰتِ وَالَارْضَ وَأَنزَلَ لَكُم مِّنَ ࡰ۬لسَّمَآءِ مَآءࣰ فَأَنۢبَتْنَا بِهِۦ حَدَآئِقَ ذَاتَ بَهْجَةࣲ࣌ مَّا كَانَ لَكُمُۥٓ أَن تُنۢبِتُواْ شَجَرَهَآ࣌ أَࢇلَٰهࣱ مَّعَ ࡰ۬للَّهِ࣌ بَلْ هُمْ قَوْمࣱ يَعْدِلُونَ࣌', 'أمن خلق ࡰلسموت والارض وأنزل لكم من ࡰلسماء ماء فأنبتنا به حدائق ذات بهجة࣌ ما كان لكم أن تنبتوا شجرها࣌ أࢇله مع ࡰلله࣌ بل هم قوم يعدلون࣌', NULL, 382, 'local:warsh-text.json'),
  ('warsh-27-63', 'warsh', 27, 63, 'أَمَّن جَعَلَ ࡰ۬لَارْضَ قَرَاراࣰ وَجَعَلَ خِلَٰلَهَآ أَنْهَٰراࣰ وَجَعَلَ لَهَا رَوَٰسِيَ وَجَعَلَ بَيْنَ ࡰ۬لْبَحْرَيْنِ حَاجِزاً࣌ ࡰࢇلَٰهࣱ مَّعَ ࡰ۬للَّهِ࣌ بَلَ ࡰكْثَرُهُمْ لَا يَعْلَمُونَ࣌', 'أمن جعل ࡰلارض قرارا وجعل خللها أنهرا وجعل لها روسي وجعل بين ࡰلبحرين حاجزا࣌ ࡰࢇله مع ࡰلله࣌ بل ࡰكثرهم لا يعلمون࣌', NULL, 382, 'local:warsh-text.json'),
  ('warsh-27-64', 'warsh', 27, 64, 'أَمَّنْ يُّجِيبُ ࡲ۬لْمُضْطَرَّ إِذَا دَعَاهُ وَيَكْشِفُ ࡲ۬لسُّوٓءَ وَيَجْعَلُكُمْ خُلَفَآءَ ࡰ۬لَارْضِ࣌ أَࢇلَٰهࣱ مَّعَ ࡰ۬للَّهِ࣌ قَلِيلاࣰ مَّا تَذَّكَّرُونَ࣌', 'أمن يجيب ࡲلمضطر إذا دعاه ويكشف ࡲلسوء ويجعلكم خلفاء ࡰلارض࣌ أࢇله مع ࡰلله࣌ قليلا ما تذكرون࣌', NULL, 382, 'local:warsh-text.json'),
  ('warsh-27-65', 'warsh', 27, 65, 'أَمَّنْ يَّهْدِيكُمْ فِے ظُلُمَٰتِ ࡴ۬لْبَرِّ وَالْبَحْرِ وَمَنْ يُّرْسِلُ ࡲ۬لرِّيَٰحَ نُشُراَۢ بَيْنَ يَدَےْ رَحْمَتِهِۦٓ࣌ أَࢇلَٰهࣱ مَّعَ ࡰ۬للَّهِ࣌ تَعَٰلَى ࡰ۬للَّهُ عَمَّا يُشْرِكُونَ࣌', 'أمن يهديكم فے ظلمت ࡴلبر والبحر ومن يرسل ࡲلريح نشرا بين يدے رحمته࣌ أࢇله مع ࡰلله࣌ تعلى ࡰلله عما يشركون࣌', NULL, 382, 'local:warsh-text.json'),
  ('warsh-27-66', 'warsh', 27, 66, 'أَمَّنْ يَّبْدَؤُاْ ࡲ۬لْخَلْقَ ثُمَّ يُعِيدُهُۥ وَمَنْ يَّرْزُقُكُم مِّنَ ࡰ۬لسَّمَآءِ وَالَارْضِ࣌ أَࢇلَٰهࣱ مَّعَ ࡰ۬للَّهِ࣌ قُلْ هَاتُواْ بُرْهَٰنَكُمُۥٓ إِن كُنتُمْ صَٰدِقِينَ࣌', 'أمن يبدؤا ࡲلخلق ثم يعيده ومن يرزقكم من ࡰلسماء والارض࣌ أࢇله مع ࡰلله࣌ قل هاتوا برهنكم إن كنتم صدقين࣌', NULL, 383, 'local:warsh-text.json'),
  ('warsh-27-67', 'warsh', 27, 67, 'قُل لَّا يَعْلَمُ مَن فِے ࡴ۬لسَّمَٰوَٰتِ وَالَارْضِ ࡴ۬لْغَيْبَ إِلَّا ࡰ۬للَّهُ࣌ وَمَا يَشْعُرُونَ أَيَّانَ يُبْعَثُونَ࣌', 'قل لا يعلم من فے ࡴلسموت والارض ࡴلغيب إلا ࡰلله࣌ وما يشعرون أيان يبعثون࣌', NULL, 383, 'local:warsh-text.json'),
  ('warsh-27-68', 'warsh', 27, 68, '۞ بَلِ ࡴٜدَّٰرَكَ عِلْمُهُمْ فِے ࡴ۬لَاخِرَةِ࣌ بَلْ هُمْ فِے شَكࣲّ مِّنْهَا بَلْ هُم مِّنْهَا عَمُونَ࣌', 'بل ࡴدرك علمهم فے ࡴلاخرة࣌ بل هم فے شك منها بل هم منها عمون࣌', NULL, 383, 'local:warsh-text.json'),
  ('warsh-27-69', 'warsh', 27, 69, 'وَقَالَ ࡰ۬لذِينَ كَفَرُوٓاْ إِذَا كُنَّا تُرَٰباࣰ وَءَابَآؤُنَآ أَئِنَّا لَمُخْرَجُونَ࣌', 'وقال ࡰلذين كفروا إذا كنا تربا وءاباؤنا أئنا لمخرجون࣌', NULL, 383, 'local:warsh-text.json'),
  ('warsh-27-70', 'warsh', 27, 70, 'لَقَدْ وُعِدْنَا هَٰذَا نَحْنُ وَءَابَآؤُنَا مِن قَبْلُ࣌ إِنْ هَٰذَآ إِلَّآ أَسَٰطِيرُ ࡲ۬لَاوَّلِينَ࣌', 'لقد وعدنا هذا نحن وءاباؤنا من قبل࣌ إن هذا إلا أسطير ࡲلاولين࣌', NULL, 383, 'local:warsh-text.json'),
  ('warsh-27-71', 'warsh', 27, 71, 'قُلْ سِيرُواْ فِے ࡴ۬لَارْضِ فَانظُرُواْ كَيْفَ كَانَ عَٰقِبَةُ ࡲ۬لْمُجْرِمِينَ࣌', 'قل سيروا فے ࡴلارض فانظروا كيف كان عقبة ࡲلمجرمين࣌', NULL, 383, 'local:warsh-text.json'),
  ('warsh-27-72', 'warsh', 27, 72, 'وَلَا تَحْزَنْ عَلَيْهِمْ وَلَا تَكُن فِے ضَيْقࣲ مِّمَّا يَمْكُرُونَ࣌', 'ولا تحزن عليهم ولا تكن فے ضيق مما يمكرون࣌', NULL, 383, 'local:warsh-text.json'),
  ('warsh-27-73', 'warsh', 27, 73, 'وَيَقُولُونَ مَتٜىٰ هَٰذَا ࡰ۬لْوَعْدُ إِن كُنتُمْ صَٰدِقِينَ࣌', 'ويقولون متى هذا ࡰلوعد إن كنتم صدقين࣌', NULL, 383, 'local:warsh-text.json'),
  ('warsh-27-74', 'warsh', 27, 74, 'قُلْ عَسٜىٰٓ أَنْ يَّكُونَ رَدِفَ لَكُم بَعْضُ ࡲ۬لذِے تَسْتَعْجِلُونَ࣌', 'قل عسى أن يكون ردف لكم بعض ࡲلذے تستعجلون࣌', NULL, 383, 'local:warsh-text.json'),
  ('warsh-27-75', 'warsh', 27, 75, 'وَإِنَّ رَبَّكَ لَذُو فَضْلٍ عَلَى ࡰ۬لنَّاسِ࣌ وَلَٰكِنَّ أَكْثَرَهُمْ لَا يَشْكُرُونَ࣌', 'وإن ربك لذو فضل على ࡰلناس࣌ ولكن أكثرهم لا يشكرون࣌', NULL, 383, 'local:warsh-text.json'),
  ('warsh-27-76', 'warsh', 27, 76, 'وَإِنَّ رَبَّكَ لَيَعْلَمُ مَا تُكِنُّ صُدُورُهُمْ وَمَا يُعْلِنُونَ࣌', 'وإن ربك ليعلم ما تكن صدورهم وما يعلنون࣌', NULL, 383, 'local:warsh-text.json'),
  ('warsh-27-77', 'warsh', 27, 77, 'وَمَا مِنْ غَآئِبَةࣲ فِے ࡴ۬لسَّمَآءِ وَالَارْضِ إِلَّا فِے كِتَٰبࣲ مُّبِينٍ࣌', 'وما من غائبة فے ࡴلسماء والارض إلا فے كتب مبين࣌', NULL, 383, 'local:warsh-text.json'),
  ('warsh-27-78', 'warsh', 27, 78, 'ࡴنَّ هَٰذَا ࡰ۬لْقُرْءَانَ يَقُصُّ عَلَىٰ بَنِےٓ إِسْرَآءِيلَ أَكْثَرَ ࡰ۬لذِے هُمْ فِيهِ يَخْتَلِفُونَ࣌', 'ࡴن هذا ࡰلقرءان يقص على بنے إسراءيل أكثر ࡰلذے هم فيه يختلفون࣌', NULL, 383, 'local:warsh-text.json'),
  ('warsh-27-79', 'warsh', 27, 79, 'وَإِنَّهُۥ لَهُدىࣰ وَرَحْمَةࣱ لِّلْمُومِنِينَ࣌', 'وإنه لهدى ورحمة للمومنين࣌', NULL, 384, 'local:warsh-text.json'),
  ('warsh-27-80', 'warsh', 27, 80, 'إِنَّ رَبَّكَ يَقْضِے بَيْنَهُم بِحُكْمِهِۦ࣌ وَهُوَ ࡰ۬لْعَزِيزُ ࡲ۬لْعَلِيمُ࣌', 'إن ربك يقضے بينهم بحكمه࣌ وهو ࡰلعزيز ࡲلعليم࣌', NULL, 384, 'local:warsh-text.json'),
  ('warsh-27-81', 'warsh', 27, 81, 'فَتَوَكَّلْ عَلَى ࡰ۬للَّهِ࣌ إِنَّكَ عَلَى ࡰ۬لْحَقِّ ࡴ۬لْمُبِينِ࣌', 'فتوكل على ࡰلله࣌ إنك على ࡰلحق ࡴلمبين࣌', NULL, 384, 'local:warsh-text.json'),
  ('warsh-27-82', 'warsh', 27, 82, 'إِنَّكَ لَا تُسْمِعُ ࡲ۬لْمَوْتٜىٰ وَلَا تُسْمِعُ ࡲ۬لصُّمَّ ࡰ۬لدُّعَآءَ ࡹذَا وَلَّوْاْ مُدْبِرِينَ࣌', 'إنك لا تسمع ࡲلموتى ولا تسمع ࡲلصم ࡰلدعاء ࡹذا ولوا مدبرين࣌', NULL, 384, 'local:warsh-text.json'),
  ('warsh-27-83', 'warsh', 27, 83, 'وَمَآ أَنتَ بِهَٰدِے ࡴ۬لْعُمْيِ عَن ضَلَٰلَتِهِمُۥٓ࣌ إِن تُسْمِعُ إِلَّا مَنْ يُّومِنُ بِـَٔايَٰتِنَا فَهُم مُّسْلِمُونَ࣌', 'وما أنت بهدے ࡴلعمي عن ضللتهم࣌ إن تسمع إلا من يومن بايتنا فهم مسلمون࣌', NULL, 384, 'local:warsh-text.json'),
  ('warsh-27-84', 'warsh', 27, 84, '۞ وَإِذَا وَقَعَ ࡰ۬لْقَوْلُ عَلَيْهِمُۥٓ أَخْرَجْنَا لَهُمْ دَآبَّةࣰ مِّنَ ࡰ۬لَارْضِ تُكَلِّمُهُمُۥٓ࣌ إِنَّ ࡰ۬لنَّاسَ كَانُواْ بِـَٔايَٰتِنَا لَا يُوقِنُونَ࣌', 'وإذا وقع ࡰلقول عليهم أخرجنا لهم دابة من ࡰلارض تكلمهم࣌ إن ࡰلناس كانوا بايتنا لا يوقنون࣌', NULL, 384, 'local:warsh-text.json'),
  ('warsh-27-85', 'warsh', 27, 85, 'وَيَوْمَ نَحْشُرُ مِن كُلِّ أُمَّةࣲ فَوْجاࣰ مِّمَّنْ يُّكَذِّبُ بِـَٔايَٰتِنَا فَهُمْ يُوزَعُونَ࣌', 'ويوم نحشر من كل أمة فوجا ممن يكذب بايتنا فهم يوزعون࣌', NULL, 384, 'local:warsh-text.json'),
  ('warsh-27-86', 'warsh', 27, 86, 'حَتَّىٰٓ إِذَا جَآءُو قَالَ أَكَذَّبْتُم بِـَٔايَٰتِے وَلَمْ تُحِيطُواْ بِهَا عِلْماً࣌ ࡰمَّاذَا كُنتُمْ تَعْمَلُونَ࣌', 'حتى إذا جاءو قال أكذبتم بايتے ولم تحيطوا بها علما࣌ ࡰماذا كنتم تعملون࣌', NULL, 384, 'local:warsh-text.json'),
  ('warsh-27-87', 'warsh', 27, 87, 'وَوَقَعَ ࡰ۬لْقَوْلُ عَلَيْهِم بِمَا ظَلَمُواْ فَهُمْ لَا يَنطِقُونَ࣌', 'ووقع ࡰلقول عليهم بما ظلموا فهم لا ينطقون࣌', NULL, 384, 'local:warsh-text.json'),
  ('warsh-27-88', 'warsh', 27, 88, 'أَلَمْ يَرَوَاْ ࡰنَّا جَعَلْنَا ࡰ۬ليْلَ لِيَسْكُنُواْ فِيهِ وَالنَّهَارَ مُبْصِراً࣌ ࡴنَّ فِے ذَٰلِكَ لَأٓيَٰتࣲ لِّقَوْمࣲ يُومِنُونَ࣌', 'ألم يروا ࡰنا جعلنا ࡰليل ليسكنوا فيه والنهار مبصرا࣌ ࡴن فے ذلك لأيت لقوم يومنون࣌', NULL, 384, 'local:warsh-text.json'),
  ('warsh-27-89', 'warsh', 27, 89, 'وَيَوْمَ يُنفَخُ فِے ࡴ۬لصُّورِ فَفَزِعَ مَن فِے ࡴ۬لسَّمَٰوَٰتِ وَمَن فِے ࡴ۬لَارْضِ إِلَّا مَن شَآءَ ࡰ۬للَّهُ࣌ وَكُلٌّ اٰتُوهُ دَٰخِرِينَ࣌', 'ويوم ينفخ فے ࡴلصور ففزع من فے ࡴلسموت ومن فے ࡴلارض إلا من شاء ࡰلله࣌ وكل اتوه دخرين࣌', NULL, 384, 'local:warsh-text.json'),
  ('warsh-27-90', 'warsh', 27, 90, 'وَتَرَى ࡰ۬لْجِبَالَ تَحْسِبُهَا جَامِدَةࣰ وَهِيَ تَمُرُّ مَرَّ ࡰ۬لسَّحَابِ࣌ صُنْعَ ࡰ۬للَّهِ ࡴ۬لذِےٓ أَتْقَنَ كُلَّ شَےْءٍ࣌ ࡴنَّهُۥ خَبِيرُۢ بِمَا تَفْعَلُونَ࣌', 'وترى ࡰلجبال تحسبها جامدة وهي تمر مر ࡰلسحاب࣌ صنع ࡰلله ࡴلذے أتقن كل شےء࣌ ࡴنه خبير بما تفعلون࣌', NULL, 384, 'local:warsh-text.json'),
  ('warsh-27-91', 'warsh', 27, 91, 'مَن جَآءَ بِالْحَسَنَةِ فَلَهُۥ خَيْرࣱ مِّنْهَا وَهُم مِّن فَزَعِ يَوْمَئِذٍ اٰمِنُونَ࣌', 'من جاء بالحسنة فله خير منها وهم من فزع يومئذ امنون࣌', NULL, 385, 'local:warsh-text.json'),
  ('warsh-27-92', 'warsh', 27, 92, 'وَمَن جَآءَ بِالسَّيِّئَةِ فَكُبَّتْ وُجُوهُهُمْ فِے ࡴ۬لنّٜارِ࣌ هَلْ تُجْزَوْنَ إِلَّا مَا كُنتُمْ تَعْمَلُونَ࣌', 'ومن جاء بالسيئة فكبت وجوههم فے ࡴلنار࣌ هل تجزون إلا ما كنتم تعملون࣌', NULL, 385, 'local:warsh-text.json'),
  ('warsh-27-93', 'warsh', 27, 93, 'إِنَّمَآ أُمِرْتُ أَنَ ࡰعْبُدَ رَبَّ هَٰذِهِ ࡴ۬لْبَلْدَةِ ࡴ۬لذِے حَرَّمَهَا وَلَهُۥ كُلُّ شَےْءࣲ࣌ وَأُمِرْتُ أَنَ ࡰكُونَ مِنَ ࡰ۬لْمُسْلِمِينَ', 'إنما أمرت أن ࡰعبد رب هذه ࡴلبلدة ࡴلذے حرمها وله كل شےء࣌ وأمرت أن ࡰكون من ࡰلمسلمين', NULL, 385, 'local:warsh-text.json'),
  ('warsh-27-94', 'warsh', 27, 94, 'وَأَنَ ࡰتْلُوَاْ ࡰ۬لْقُرْءَانَ࣌ فَمَنِ ࡴٜهْتَدٜىٰ فَإِنَّمَا يَهْتَدِے لِنَفْسِهِۦ࣌ وَمَن ضَلَّ فَقُلِ ࡴنَّمَآ أَنَا مِنَ ࡰ۬لْمُنذِرِينَ࣌', 'وأن ࡰتلوا ࡰلقرءان࣌ فمن ࡴهتدى فإنما يهتدے لنفسه࣌ ومن ضل فقل ࡴنما أنا من ࡰلمنذرين࣌', NULL, 385, 'local:warsh-text.json'),
  ('warsh-27-95', 'warsh', 27, 95, 'وَقُلِ ࡴ۬لْحَمْدُ لِلهِ سَيُرِيكُمُۥٓ ءَايَٰتِهِۦ فَتَعْرِفُونَهَا࣌ وَمَا رَبُّكَ بِغَٰفِلٍ عَمَّا تَعْمَلُونَ࣌', 'وقل ࡴلحمد لله سيريكم ءايته فتعرفونها࣌ وما ربك بغفل عما تعملون࣌', NULL, 385, 'local:warsh-text.json'),
  ('warsh-28-1', 'warsh', 28, 1, 'طَسِٓمِّٓ࣌ تِلْكَ ءَايَٰتُ ࡲ۬لْكِتَٰبِ ࡴ۬لْمُبِينِ࣌', 'طسم࣌ تلك ءايت ࡲلكتب ࡴلمبين࣌', NULL, 385, 'local:warsh-text.json'),
  ('warsh-28-2', 'warsh', 28, 2, 'نَتْلُواْ عَلَيْكَ مِن نَّبَإِ مُوسٜىٰ وَفِرْعَوْنَ بِالْحَقِّ لِقَوْمࣲ يُومِنُونَ࣌', 'نتلوا عليك من نبإ موسى وفرعون بالحق لقوم يومنون࣌', NULL, 385, 'local:warsh-text.json'),
  ('warsh-28-3', 'warsh', 28, 3, 'إِنَّ فِرْعَوْنَ عَلَا فِے ࡴ۬لَارْضِ وَجَعَلَ أَهْلَهَا شِيَعاࣰ يَسْتَضْعِفُ طَآئِفَةࣰ مِّنْهُمْ يُذَبِّحُ أَبْنَآءَهُمْ وَيَسْتَحْيِۦ نِسَآءَهُمُۥٓ࣌ إِنَّهُۥ كَانَ مِنَ ࡰ۬لْمُفْسِدِينَ࣌', 'إن فرعون علا فے ࡴلارض وجعل أهلها شيعا يستضعف طائفة منهم يذبح أبناءهم ويستحي نساءهم࣌ إنه كان من ࡰلمفسدين࣌', NULL, 385, 'local:warsh-text.json'),
  ('warsh-28-4', 'warsh', 28, 4, 'وَنُرِيدُ أَن نَّمُنَّ عَلَى ࡰ۬لذِينَ ࡸَسْتُضْعِفُواْ فِے ࡴ۬لَارْضِ وَنَجْعَلَهُمُۥٓ أَئِمَّةࣰ وَنَجْعَلَهُمُ ࡲ۬لْوَٰرِثِينَ', 'ونريد أن نمن على ࡰلذين ࡸستضعفوا فے ࡴلارض ونجعلهم أئمة ونجعلهم ࡲلورثين', NULL, 385, 'local:warsh-text.json'),
  ('warsh-28-5', 'warsh', 28, 5, 'وَنُمَكِّنَ لَهُمْ فِے ࡴ۬لَارْضِ وَنُرِيَ فِرْعَوْنَ وَهَامَٰنَ وَجُنُودَهُمَا مِنْهُم مَّا كَانُواْ يَحْذَرُونَ࣌', 'ونمكن لهم فے ࡴلارض ونري فرعون وهامن وجنودهما منهم ما كانوا يحذرون࣌', NULL, 386, 'local:warsh-text.json'),
  ('warsh-28-6', 'warsh', 28, 6, 'وَأَوْحَيْنَآ إِلَىٰٓ أُمِّ مُوسٜىٰٓ أَنَ ࡰرْضِعِيهِ فَإِذَا خِفْتِ عَلَيْهِ فَأَلْقِيهِ فِے ࡴ۬لْيَمِّ وَلَا تَخَافِے وَلَا تَحْزَنِےٓ࣌ إِنَّا رَآدُّوهُ إِلَيْكِ وَجَاعِلُوهُ مِنَ ࡰ۬لْمُرْسَلِينَ࣌', 'وأوحينا إلى أم موسى أن ࡰرضعيه فإذا خفت عليه فألقيه فے ࡴليم ولا تخافے ولا تحزنے࣌ إنا رادوه إليك وجاعلوه من ࡰلمرسلين࣌', NULL, 386, 'local:warsh-text.json'),
  ('warsh-28-7', 'warsh', 28, 7, 'فَالْتَقَطَهُۥٓ ءَالُ فِرْعَوْنَ لِيَكُونَ لَهُمْ عَدُوّاࣰ وَحَزَناً࣌ ࡴنَّ فِرْعَوْنَ وَهَامَٰنَ وَجُنُودَهُمَا كَانُواْ خَٰطِـِٕينَ࣌', 'فالتقطه ءال فرعون ليكون لهم عدوا وحزنا࣌ ࡴن فرعون وهامن وجنودهما كانوا خطين࣌', NULL, 386, 'local:warsh-text.json'),
  ('warsh-28-8', 'warsh', 28, 8, 'وَقَالَتِ ࡴٜمْرَأَتُ فِرْعَوْنَ قُرَّتُ عَيْنࣲ لِّے وَلَكَ لَا تَقْتُلُوهُ࣌ عَسٜىٰٓ أَنْ يَّنفَعَنَآ أَوْ نَتَّخِذَهُۥ وَلَداࣰ وَهُمْ لَا يَشْعُرُونَ࣌', 'وقالت ࡴمرأت فرعون قرت عين لے ولك لا تقتلوه࣌ عسى أن ينفعنا أو نتخذه ولدا وهم لا يشعرون࣌', NULL, 386, 'local:warsh-text.json'),
  ('warsh-28-9', 'warsh', 28, 9, 'وَأَصْبَحَ فُؤَادُ أُمِّ مُوسٜىٰ فَٰرِغاً ࡴن كَٰدَتْ لَتُبْدِے بِهِۦ لَوْلَآ أَن رَّبَطْنَا عَلَىٰ قَلْبِهَا لِتَكُونَ مِنَ ࡰ۬لْمُومِنِينَ࣌', 'وأصبح فؤاد أم موسى فرغا ࡴن كدت لتبدے به لولا أن ربطنا على قلبها لتكون من ࡰلمومنين࣌', NULL, 386, 'local:warsh-text.json'),
  ('warsh-28-10', 'warsh', 28, 10, 'وَقَالَتْ لِأُخْتِهِۦ قُصِّيهِ فَبَصُرَتْ بِهِۦ عَن جُنُبࣲ وَهُمْ لَا يَشْعُرُونَ࣌', 'وقالت لأخته قصيه فبصرت به عن جنب وهم لا يشعرون࣌', NULL, 386, 'local:warsh-text.json'),
  ('warsh-28-11', 'warsh', 28, 11, '۞ وَحَرَّمْنَا عَلَيْهِ ࡴ۬لْمَرَاضِعَ مِن قَبْلُ فَقَالَتْ هَلَ ࡰدُلُّكُمْ عَلَىٰٓ أَهْلِ بَيْتࣲ يَكْفُلُونَهُۥ لَكُمْ وَهُمْ لَهُۥ نَٰصِحُونَ࣌', 'وحرمنا عليه ࡴلمراضع من قبل فقالت هل ࡰدلكم على أهل بيت يكفلونه لكم وهم له نصحون࣌', NULL, 386, 'local:warsh-text.json'),
  ('warsh-28-12', 'warsh', 28, 12, 'فَرَدَدْنَٰهُ إِلَىٰٓ أُمِّهِۦ كَےْ تَقَرَّ عَيْنُهَا وَلَا تَحْزَنَ وَلِتَعْلَمَ أَنَّ وَعْدَ ࡰ۬للَّهِ حَقࣱّ࣌ وَلَٰكِنَّ أَكْثَرَهُمْ لَا يَعْلَمُونَ࣌', 'فرددنه إلى أمه كے تقر عينها ولا تحزن ولتعلم أن وعد ࡰلله حق࣌ ولكن أكثرهم لا يعلمون࣌', NULL, 386, 'local:warsh-text.json'),
  ('warsh-28-13', 'warsh', 28, 13, 'وَلَمَّا بَلَغَ أَشُدَّهُۥ وَاسْتَوٜىٰٓ ءَاتَيْنَٰهُ حُكْماࣰ وَعِلْماࣰ࣌ وَكَذَٰلِكَ نَجْزِے ࡴ۬لْمُحْسِنِينَ࣌', 'ولما بلغ أشده واستوى ءاتينه حكما وعلما࣌ وكذلك نجزے ࡴلمحسنين࣌', NULL, 387, 'local:warsh-text.json'),
  ('warsh-28-14', 'warsh', 28, 14, 'وَدَخَلَ ࡰ۬لْمَدِينَةَ عَلَىٰ حِينِ غَفْلَةࣲ مِّنَ ࡰهْلِهَا فَوَجَدَ فِيهَا رَجُلَيْنِ يَقْتَتِلَٰنِ هَٰذَا مِن شِيعَتِهِۦ وَهَٰذَا مِنْ عَدُوِّهِۦ࣌ فَاسْتَغَٰثَهُ ࡲ۬لذِے مِن شِيعَتِهِۦ عَلَى ࡰ۬لذِے مِنْ عَدُوِّهِۦ فَوَكَزَهُۥ مُوسٜىٰ فَقَضٜىٰ عَلَيْهِ࣌ قَالَ هَٰذَا مِنْ عَمَلِ ࡴ۬لشَّيْطَٰنِ࣌ إِنَّهُۥ عَدُوࣱّ مُّضِلࣱّ مُّبِينࣱ࣌', 'ودخل ࡰلمدينة على حين غفلة من ࡰهلها فوجد فيها رجلين يقتتلن هذا من شيعته وهذا من عدوه࣌ فاستغثه ࡲلذے من شيعته على ࡰلذے من عدوه فوكزه موسى فقضى عليه࣌ قال هذا من عمل ࡴلشيطن࣌ إنه عدو مضل مبين࣌', NULL, 387, 'local:warsh-text.json'),
  ('warsh-28-15', 'warsh', 28, 15, 'قَالَ رَبِّ إِنِّے ظَلَمْتُ نَفْسِے فَاغْفِرْ لِے࣌ فَغَفَرَ لَهُۥٓ࣌ إِنَّهُۥ هُوَ ࡰ۬لْغَفُورُ ࡲ۬لرَّحِيمُ࣌', 'قال رب إنے ظلمت نفسے فاغفر لے࣌ فغفر له࣌ إنه هو ࡰلغفور ࡲلرحيم࣌', NULL, 387, 'local:warsh-text.json'),
  ('warsh-28-16', 'warsh', 28, 16, 'قَالَ رَبِّ بِمَآ أَنْعَمْتَ عَلَيَّ فَلَنَ ࡰكُونَ ظَهِيراࣰ لِّلْمُجْرِمِينَ࣌', 'قال رب بما أنعمت علي فلن ࡰكون ظهيرا للمجرمين࣌', NULL, 387, 'local:warsh-text.json'),
  ('warsh-28-17', 'warsh', 28, 17, 'فَأَصْبَحَ فِے ࡴ۬لْمَدِينَةِ خَآئِفاࣰ يَتَرَقَّبُ فَإِذَا ࡰ۬لذِے ࡴٜسْتَنصَرَهُۥ بِالَامْسِ يَسْتَصْرِخُهُۥ࣌ قَالَ لَهُۥ مُوسٜىٰٓ إِنَّكَ لَغَوِيࣱّ مُّبِينࣱ࣌', 'فأصبح فے ࡴلمدينة خائفا يترقب فإذا ࡰلذے ࡴستنصره بالامس يستصرخه࣌ قال له موسى إنك لغوي مبين࣌', NULL, 387, 'local:warsh-text.json'),
  ('warsh-28-18', 'warsh', 28, 18, 'فَلَمَّآ أَنَ ࡰرَادَ أَنْ يَّبْطِشَ بِالذِے هُوَ عَدُوࣱّ لَّهُمَا قَالَ يَٰمُوسٜىٰٓ أَتُرِيدُ أَن تَقْتُلَنِے كَمَا قَتَلْتَ نَفْساَۢ بِالَامْسِ࣌ إِن تُرِيدُ إِلَّآ أَن تَكُونَ جَبَّاراࣰ فِے ࡴ۬لَارْضِ وَمَا تُرِيدُ أَن تَكُونَ مِنَ ࡰ۬لْمُصْلِحِينَ࣌', 'فلما أن ࡰراد أن يبطش بالذے هو عدو لهما قال يموسى أتريد أن تقتلنے كما قتلت نفسا بالامس࣌ إن تريد إلا أن تكون جبارا فے ࡴلارض وما تريد أن تكون من ࡰلمصلحين࣌', NULL, 387, 'local:warsh-text.json'),
  ('warsh-28-19', 'warsh', 28, 19, 'وَجَآءَ رَجُلࣱ مِّنَ ࡰقْصَا ࡰ۬لْمَدِينَةِ يَسْعٜىٰ࣌ قَالَ يَٰمُوسٜىٰٓ إِنَّ ࡰ۬لْمَلَأَ يَاتَمِرُونَ بِكَ لِيَقْتُلُوكَ فَاخْرُجِ ࡴنِّے لَكَ مِنَ ࡰ۬لنَّٰصِحِينَ࣌', 'وجاء رجل من ࡰقصا ࡰلمدينة يسعى࣌ قال يموسى إن ࡰلملأ ياتمرون بك ليقتلوك فاخرج ࡴنے لك من ࡰلنصحين࣌', NULL, 387, 'local:warsh-text.json'),
  ('warsh-28-20', 'warsh', 28, 20, 'فَخَرَجَ مِنْهَا خَآئِفاࣰ يَتَرَقَّبُ࣌ قَالَ رَبِّ نَجِّنِے مِنَ ࡰ۬لْقَوْمِ ࡴ۬لظَّٰلِمِينَ࣌', 'فخرج منها خائفا يترقب࣌ قال رب نجنے من ࡰلقوم ࡴلظلمين࣌', NULL, 387, 'local:warsh-text.json'),
  ('warsh-28-21', 'warsh', 28, 21, '۞ وَلَمَّا تَوَجَّهَ تِلْقَآءَ مَدْيَنَ قَالَ عَسٜىٰ رَبِّيَ أَنْ يَّهْدِيَنِے سَوَآءَ ࡰ۬لسَّبِيلِ࣌', 'ولما توجه تلقاء مدين قال عسى ربي أن يهدينے سواء ࡰلسبيل࣌', NULL, 388, 'local:warsh-text.json'),
  ('warsh-28-22', 'warsh', 28, 22, 'وَلَمَّا وَرَدَ مَآءَ مَدْيَنَ وَجَدَ عَلَيْهِ أُمَّةࣰ مِّنَ ࡰ۬لنَّاسِ يَسْقُونَ', 'ولما ورد ماء مدين وجد عليه أمة من ࡰلناس يسقون', NULL, 388, 'local:warsh-text.json'),
  ('warsh-28-23', 'warsh', 28, 23, 'وَوَجَدَ مِن دُونِهِمُ ࡲٜمْرَأَتَيْنِ تَذُودَٰنِ࣌ قَالَ مَا خَطْبُكُمَا࣌ قَالَتَا لَا نَسْقِے حَتَّىٰ يُصْدِرَ ࡰ۬لرِّعَآءُ وَأَبُونَا شَيْخࣱ كَبِيرࣱ࣌', 'ووجد من دونهم ࡲمرأتين تذودن࣌ قال ما خطبكما࣌ قالتا لا نسقے حتى يصدر ࡰلرعاء وأبونا شيخ كبير࣌', NULL, 388, 'local:warsh-text.json'),
  ('warsh-28-24', 'warsh', 28, 24, 'فَسَقٜىٰ لَهُمَا ثُمَّ تَوَلّٜىٰٓ إِلَى ࡰ۬لظِّلِّ فَقَالَ رَبِّ إِنِّے لِمَآ أَنزَلْتَ إِلَيَّ مِنْ خَيْرࣲ فَقِيرࣱ࣌', 'فسقى لهما ثم تولى إلى ࡰلظل فقال رب إنے لما أنزلت إلي من خير فقير࣌', NULL, 388, 'local:warsh-text.json'),
  ('warsh-28-25', 'warsh', 28, 25, 'فَجَآءَتْهُ إِحْدٜيٰهُمَا تَمْشِے عَلَى ࡰٜسْتِحْيَآءࣲ࣌ قَالَتِ ࡴنَّ أَبِے يَدْعُوكَ لِيَجْزِيَكَ أَجْرَ مَا سَقَيْتَ لَنَا࣌ فَلَمَّا جَآءَهُۥ وَقَصَّ عَلَيْهِ ࡴ۬لْقَصَصَ قَالَ لَا تَخَفْ نَجَوْتَ مِنَ ࡰ۬لْقَوْمِ ࡴ۬لظَّٰلِمِينَ࣌', 'فجاءته إحديهما تمشے على ࡰستحياء࣌ قالت ࡴن أبے يدعوك ليجزيك أجر ما سقيت لنا࣌ فلما جاءه وقص عليه ࡴلقصص قال لا تخف نجوت من ࡰلقوم ࡴلظلمين࣌', NULL, 388, 'local:warsh-text.json'),
  ('warsh-28-26', 'warsh', 28, 26, 'قَالَتِ ࡴحْدٜيٰهُمَا يَٰٓأَبَتِ ࡴٜسْتَٰجِرْهُ࣌ إِنَّ خَيْرَ مَنِ ࡴٜسْتَٰجَرْتَ ࡰ۬لْقَوِيُّ ࡲ۬لَامِينُ࣌', 'قالت ࡴحديهما يأبت ࡴستجره࣌ إن خير من ࡴستجرت ࡰلقوي ࡲلامين࣌', NULL, 388, 'local:warsh-text.json'),
  ('warsh-28-27', 'warsh', 28, 27, 'قَالَ إِنِّيَ أُرِيدُ أَنُ ࡳنكِحَكَ إِحْدَى ࡰٜبْنَتَيَّ هَٰتَيْنِ عَلَىٰٓ أَن تَاجُرَنِے ثَمَٰنِيَ حِجَجࣲ࣌ فَإِنَ ࡰتْمَمْتَ عَشْراࣰ فَمِنْ عِندِكَ࣌ وَمَآ أُرِيدُ أَنَ ࡰشُقَّ عَلَيْكَ࣌ سَتَجِدُنِيَ إِن شَآءَ ࡰ۬للَّهُ مِنَ ࡰ۬لصَّٰلِحِينَ࣌', 'قال إني أريد أن ࡳنكحك إحدى ࡰبنتي هتين على أن تاجرنے ثمني حجج࣌ فإن ࡰتممت عشرا فمن عندك࣌ وما أريد أن ࡰشق عليك࣌ ستجدني إن شاء ࡰلله من ࡰلصلحين࣌', NULL, 388, 'local:warsh-text.json'),
  ('warsh-28-28', 'warsh', 28, 28, 'قَالَ ذَٰلِكَ بَيْنِے وَبَيْنَكَ࣌ أَيَّمَا ࡰ۬لَاجَلَيْنِ قَضَيْتُ فَلَا عُدْوَٰنَ عَلَيَّ࣌ وَاللَّهُ عَلَىٰ مَا نَقُولُ وَكِيلࣱ࣌', 'قال ذلك بينے وبينك࣌ أيما ࡰلاجلين قضيت فلا عدون علي࣌ والله على ما نقول وكيل࣌', NULL, 388, 'local:warsh-text.json'),
  ('warsh-28-29', 'warsh', 28, 29, '۞ فَلَمَّا قَضٜىٰ مُوسَى ࡰ۬لَاجَلَ وَسَارَ بِأَهْلِهِۦٓ ءَانَسَ مِن جَانِبِ ࡴ۬لطُّورِ نَاراࣰ࣌ قَالَ لِأَهْلِهِ ࡴ࢈مْكُثُوٓاْ إِنِّيَ ءَانَسْتُ نَاراࣰ لَّعَلِّيَ ءَاتِيكُم مِّنْهَا بِخَبَرٍ ࡰوْ جِذْوَةࣲ مِّنَ ࡰ۬لنّٜارِ لَعَلَّكُمْ تَصْطَلُونَ࣌', 'فلما قضى موسى ࡰلاجل وسار بأهله ءانس من جانب ࡴلطور نارا࣌ قال لأهله ࡴ࢈مكثوا إني ءانست نارا لعلي ءاتيكم منها بخبر ࡰو جذوة من ࡰلنار لعلكم تصطلون࣌', NULL, 389, 'local:warsh-text.json'),
  ('warsh-28-30', 'warsh', 28, 30, 'فَلَمَّآ أَتٜيٰهَا نُودِيَ مِن شَٰطِےِٕ ࡴ۬لْوَادِ ࡴ۬لَايْمَنِ فِے ࡴ۬لْبُقْعَةِ ࡴ۬لْمُبَٰرَكَةِ مِنَ ࡰ۬لشَّجَرَةِ أَنْ يَّٰمُوسٜىٰٓ إِنِّيَ أَنَا ࡰ۬للَّهُ رَبُّ ࡲ۬لْعَٰلَمِينَ', 'فلما أتيها نودي من شطے ࡴلواد ࡴلايمن فے ࡴلبقعة ࡴلمبركة من ࡰلشجرة أن يموسى إني أنا ࡰلله رب ࡲلعلمين', NULL, 389, 'local:warsh-text.json'),
  ('warsh-28-31', 'warsh', 28, 31, 'وَأَنَ ࡰلْقِ عَصَاكَ࣌ فَلَمَّا رٜءٜاهَا تَهْتَزُّ كَأَنَّهَا جَآنࣱّ وَلّٜىٰ مُدْبِراࣰ وَلَمْ يُعَقِّبْ࣌ يَٰمُوسٜىٰٓ أَقْبِلْ وَلَا تَخَفِ࣌ ࡴنَّكَ مِنَ ࡰ۬لَامِنِينَ࣌', 'وأن ࡰلق عصاك࣌ فلما رءاها تهتز كأنها جان ولى مدبرا ولم يعقب࣌ يموسى أقبل ولا تخف࣌ ࡴنك من ࡰلامنين࣌', NULL, 389, 'local:warsh-text.json'),
  ('warsh-28-32', 'warsh', 28, 32, 'ࡸَسْلُكْ يَدَكَ فِے جَيْبِكَ تَخْرُجْ بَيْضَآءَ مِنْ غَيْرِ سُوٓءࣲ࣌ وَاضْمُمِ ࡴلَيْكَ جَنَاحَكَ مِنَ ࡰ۬لرَّهَبِ࣌ فَذَٰنِكَ بُرْهَٰنَٰنِ مِن رَّبِّكَ إِلَىٰ فِرْعَوْنَ وَمَلَإِيْهِۦٓ࣌ إِنَّهُمْ كَانُواْ قَوْماࣰ فَٰسِقِينَ࣌', 'ࡸسلك يدك فے جيبك تخرج بيضاء من غير سوء࣌ واضمم ࡴليك جناحك من ࡰلرهب࣌ فذنك برهنن من ربك إلى فرعون وملإيه࣌ إنهم كانوا قوما فسقين࣌', NULL, 389, 'local:warsh-text.json'),
  ('warsh-28-33', 'warsh', 28, 33, 'قَالَ رَبِّ إِنِّے قَتَلْتُ مِنْهُمْ نَفْساࣰ فَأَخَافُ أَنْ يَّقْتُلُونِ', 'قال رب إنے قتلت منهم نفسا فأخاف أن يقتلون', NULL, 389, 'local:warsh-text.json'),
  ('warsh-28-34', 'warsh', 28, 34, 'وَأَخِے هَٰرُونُ هُوَ أَفْصَحُ مِنِّے لِسَاناࣰ فَأَرْسِلْهُ مَعِے رِداࣰ يُصَدِّقْنِےٓ࣌ إِنِّيَ أَخَافُ أَنْ يُّكَذِّبُونِۦ࣌', 'وأخے هرون هو أفصح منے لسانا فأرسله معے ردا يصدقنے࣌ إني أخاف أن يكذبون࣌', NULL, 389, 'local:warsh-text.json'),
  ('warsh-28-35', 'warsh', 28, 35, 'قَالَ سَنَشُدُّ عَضُدَكَ بِأَخِيكَ وَنَجْعَلُ لَكُمَا سُلْطَٰناࣰ فَلَا يَصِلُونَ إِلَيْكُمَا بِـَٔايَٰتِنَآ࣌ أَنتُمَا وَمَنِ ࡴٜتَّبَعَكُمَا ࡰ۬لْغَٰلِبُونَ࣌', 'قال سنشد عضدك بأخيك ونجعل لكما سلطنا فلا يصلون إليكما بايتنا࣌ أنتما ومن ࡴتبعكما ࡰلغلبون࣌', NULL, 389, 'local:warsh-text.json'),
  ('warsh-28-36', 'warsh', 28, 36, 'فَلَمَّا جَآءَهُم مُّوسٜىٰ بِـَٔايَٰتِنَا بَيِّنَٰتࣲ قَالُواْ مَا هَٰذَآ إِلَّا سِحْرࣱ مُّفْتَرىࣰ وَمَا سَمِعْنَا بِهَٰذَا فِےٓ ءَابَآئِنَا ࡰ۬لَاوَّلِينَ࣌', 'فلما جاءهم موسى بايتنا بينت قالوا ما هذا إلا سحر مفترى وما سمعنا بهذا فے ءابائنا ࡰلاولين࣌', NULL, 390, 'local:warsh-text.json'),
  ('warsh-28-37', 'warsh', 28, 37, 'وَقَالَ مُوسٜىٰ رَبِّيَ أَعْلَمُ بِمَن جَآءَ بِالْهُدٜىٰ مِنْ عِندِهِۦ وَمَن تَكُونُ لَهُۥ عَٰقِبَةُ ࡲ۬لدّٜارِ࣌ إِنَّهُۥ لَا يُفْلِحُ ࡲ۬لظَّٰلِمُونَ࣌', 'وقال موسى ربي أعلم بمن جاء بالهدى من عنده ومن تكون له عقبة ࡲلدار࣌ إنه لا يفلح ࡲلظلمون࣌', NULL, 390, 'local:warsh-text.json'),
  ('warsh-28-38', 'warsh', 28, 38, 'وَقَالَ فِرْعَوْنُ يَٰٓأَيُّهَا ࡰ۬لْمَلَأُ مَا عَلِمْتُ لَكُم مِّنِ ࡴلَٰهٍ غَيْرِے فَأَوْقِدْ لِے يَٰهَامَٰنُ عَلَى ࡰ۬لطِّينِ فَاجْعَل لِّے صَرْحاࣰ لَّعَلِّيَ أَطَّلِعُ إِلَىٰٓ إِلَٰهِ مُوسٜىٰ وَإِنِّے لَأَظُنُّهُۥ مِنَ ࡰ۬لْكَٰذِبِينَ࣌', 'وقال فرعون يأيها ࡰلملأ ما علمت لكم من ࡴله غيرے فأوقد لے يهامن على ࡰلطين فاجعل لے صرحا لعلي أطلع إلى إله موسى وإنے لأظنه من ࡰلكذبين࣌', NULL, 390, 'local:warsh-text.json'),
  ('warsh-28-39', 'warsh', 28, 39, '۞ وَاسْتَكْبَرَ هُوَ وَجُنُودُهُۥ فِے ࡴ۬لَارْضِ بِغَيْرِ ࡴ۬لْحَقِّ وَظَنُّوٓاْ أَنَّهُمُۥٓ إِلَيْنَا لَا يَرْجِعُونَ࣌', 'واستكبر هو وجنوده فے ࡴلارض بغير ࡴلحق وظنوا أنهم إلينا لا يرجعون࣌', NULL, 390, 'local:warsh-text.json'),
  ('warsh-28-40', 'warsh', 28, 40, 'فَأَخَذْنَٰهُ وَجُنُودَهُۥ فَنَبَذْنَٰهُمْ فِے ࡴ۬لْيَمِّ࣌ فَانظُرْ كَيْفَ كَانَ عَٰقِبَةُ ࡲ۬لظَّٰلِمِينَ࣌', 'فأخذنه وجنوده فنبذنهم فے ࡴليم࣌ فانظر كيف كان عقبة ࡲلظلمين࣌', NULL, 390, 'local:warsh-text.json'),
  ('warsh-28-41', 'warsh', 28, 41, 'وَجَعَلْنَٰهُمُۥٓ أَئِمَّةࣰ يَدْعُونَ إِلَى ࡰ۬لنّٜارِ࣌ وَيَوْمَ ࡰ۬لْقِيَٰمَةِ لَا يُنصَرُونَ࣌', 'وجعلنهم أئمة يدعون إلى ࡰلنار࣌ ويوم ࡰلقيمة لا ينصرون࣌', NULL, 390, 'local:warsh-text.json'),
  ('warsh-28-42', 'warsh', 28, 42, 'وَأَتْبَعْنَٰهُمْ فِے هَٰذِهِ ࡴ۬لدُّنْيٜا لَعْنَةࣰ࣌ وَيَوْمَ ࡰ۬لْقِيَٰمَةِ هُم مِّنَ ࡰ۬لْمَقْبُوحِينَ࣌', 'وأتبعنهم فے هذه ࡴلدنيا لعنة࣌ ويوم ࡰلقيمة هم من ࡰلمقبوحين࣌', NULL, 390, 'local:warsh-text.json'),
  ('warsh-28-43', 'warsh', 28, 43, 'وَلَقَدَ اٰتَيْنَا مُوسَى ࡰ۬لْكِتَٰبَ مِنۢ بَعْدِ مَآ أَهْلَكْنَا ࡰ۬لْقُرُونَ ࡰ۬لُاولٜىٰ بَصَآئِرَ لِلنَّاسِ وَهُدىࣰ وَرَحْمَةࣰ لَّعَلَّهُمْ يَتَذَكَّرُونَ࣌', 'ولقد اتينا موسى ࡰلكتب من بعد ما أهلكنا ࡰلقرون ࡰلاولى بصائر للناس وهدى ورحمة لعلهم يتذكرون࣌', NULL, 390, 'local:warsh-text.json'),
  ('warsh-28-44', 'warsh', 28, 44, 'وَمَا كُنتَ بِجَانِبِ ࡴ۬لْغَرْبِيِّ إِذْ قَضَيْنَآ إِلَىٰ مُوسَى ࡰ۬لَامْرَ࣌ وَمَا كُنتَ مِنَ ࡰ۬لشَّٰهِدِينَ࣌', 'وما كنت بجانب ࡴلغربي إذ قضينا إلى موسى ࡰلامر࣌ وما كنت من ࡰلشهدين࣌', NULL, 391, 'local:warsh-text.json'),
  ('warsh-28-45', 'warsh', 28, 45, 'وَلَٰكِنَّآ أَنشَأْنَا قُرُوناࣰ فَتَطَاوَلَ عَلَيْهِمُ ࡲ۬لْعُمُرُ࣌ وَمَا كُنتَ ثَاوِياࣰ فِےٓ أَهْلِ مَدْيَنَ تَتْلُواْ عَلَيْهِمُۥٓ ءَايَٰتِنَا࣌ وَلَٰكِنَّا كُنَّا مُرْسِلِينَ࣌', 'ولكنا أنشأنا قرونا فتطاول عليهم ࡲلعمر࣌ وما كنت ثاويا فے أهل مدين تتلوا عليهم ءايتنا࣌ ولكنا كنا مرسلين࣌', NULL, 391, 'local:warsh-text.json'),
  ('warsh-28-46', 'warsh', 28, 46, 'وَمَا كُنتَ بِجَانِبِ ࡴ۬لطُّورِ إِذْ نَادَيْنَا࣌ وَلَٰكِن رَّحْمَةࣰ مِّن رَّبِّكَ لِتُنذِرَ قَوْماࣰ مَّآ أَتٜيٰهُم مِّن نَّذِيرࣲ مِّن قَبْلِكَ لَعَلَّهُمْ يَتَذَكَّرُونَ࣌', 'وما كنت بجانب ࡴلطور إذ نادينا࣌ ولكن رحمة من ربك لتنذر قوما ما أتيهم من نذير من قبلك لعلهم يتذكرون࣌', NULL, 391, 'local:warsh-text.json'),
  ('warsh-28-47', 'warsh', 28, 47, 'وَلَوْلَآ أَن تُصِيبَهُم مُّصِيبَةُۢ بِمَا قَدَّمَتَ ࡰيْدِيهِمْ فَيَقُولُواْ رَبَّنَا لَوْلَآ أَرْسَلْتَ إِلَيْنَا رَسُولاࣰ فَنَتَّبِعَ ءَايَٰتِكَ وَنَكُونَ مِنَ ࡰ۬لْمُومِنِينَ࣌', 'ولولا أن تصيبهم مصيبة بما قدمت ࡰيديهم فيقولوا ربنا لولا أرسلت إلينا رسولا فنتبع ءايتك ونكون من ࡰلمومنين࣌', NULL, 391, 'local:warsh-text.json'),
  ('warsh-28-48', 'warsh', 28, 48, 'فَلَمَّا جَآءَهُمُ ࡲ۬لْحَقُّ مِنْ عِندِنَا قَالُواْ لَوْلَآ أُوتِيَ مِثْلَ مَآ أُوتِيَ مُوسٜىٰٓ࣌ أَوَلَمْ يَكْفُرُواْ بِمَآ أُوتِيَ مُوسٜىٰ مِن قَبْلُ࣌ قَالُواْ سَٰحِرَٰنِ تَظَٰهَرَا࣌ وَقَالُوٓاْ إِنَّا بِكُلࣲّ كَٰفِرُونَ࣌', 'فلما جاءهم ࡲلحق من عندنا قالوا لولا أوتي مثل ما أوتي موسى࣌ أولم يكفروا بما أوتي موسى من قبل࣌ قالوا سحرن تظهرا࣌ وقالوا إنا بكل كفرون࣌', NULL, 391, 'local:warsh-text.json'),
  ('warsh-28-49', 'warsh', 28, 49, 'قُلْ فَاتُواْ بِكِتَٰبࣲ مِّنْ عِندِ ࡴ۬للَّهِ هُوَ أَهْدٜىٰ مِنْهُمَآ أَتَّبِعْهُ إِن كُنتُمْ صَٰدِقِينَ࣌', 'قل فاتوا بكتب من عند ࡴلله هو أهدى منهما أتبعه إن كنتم صدقين࣌', NULL, 391, 'local:warsh-text.json'),
  ('warsh-28-50', 'warsh', 28, 50, 'فَإِن لَّمْ يَسْتَجِيبُواْ لَكَ فَاعْلَمَ ࡰنَّمَا يَتَّبِعُونَ أَهْوَآءَهُمْ࣌ وَمَنَ ࡰضَلُّ مِمَّنِ ࡴٜتَّبَعَ هَوٜيٰهُ بِغَيْرِ هُدىࣰ مِّنَ ࡰ۬للَّهِ࣌ إِنَّ ࡰ۬للَّهَ لَا يَهْدِے ࡴ۬لْقَوْمَ ࡰ۬لظَّٰلِمِينَ࣌', 'فإن لم يستجيبوا لك فاعلم ࡰنما يتبعون أهواءهم࣌ ومن ࡰضل ممن ࡴتبع هويه بغير هدى من ࡰلله࣌ إن ࡰلله لا يهدے ࡴلقوم ࡰلظلمين࣌', NULL, 391, 'local:warsh-text.json'),
  ('warsh-28-51', 'warsh', 28, 51, '۞ وَلَقَدْ وَصَّلْنَا لَهُمُ ࡲ۬لْقَوْلَ لَعَلَّهُمْ يَتَذَكَّرُونَ࣌', 'ولقد وصلنا لهم ࡲلقول لعلهم يتذكرون࣌', NULL, 392, 'local:warsh-text.json'),
  ('warsh-28-52', 'warsh', 28, 52, 'ࡰ۬لذِينَ ءَاتَيْنَٰهُمُ ࡲ۬لْكِتَٰبَ مِن قَبْلِهِۦ هُم بِهِۦ يُومِنُونَ࣌', 'ࡰلذين ءاتينهم ࡲلكتب من قبله هم به يومنون࣌', NULL, 392, 'local:warsh-text.json'),
  ('warsh-28-53', 'warsh', 28, 53, 'وَإِذَا يُتْلٜىٰ عَلَيْهِمْ قَالُوٓاْ ءَامَنَّا بِهِۦٓ إِنَّهُ ࡲ۬لْحَقُّ مِن رَّبِّنَآ إِنَّا كُنَّا مِن قَبْلِهِۦ مُسْلِمِينَ࣌', 'وإذا يتلى عليهم قالوا ءامنا به إنه ࡲلحق من ربنا إنا كنا من قبله مسلمين࣌', NULL, 392, 'local:warsh-text.json'),
  ('warsh-28-54', 'warsh', 28, 54, 'أُوْلَٰٓئِكَ يُوتَوْنَ أَجْرَهُم مَّرَّتَيْنِ بِمَا صَبَرُواْ وَيَدْرَءُونَ بِالْحَسَنَةِ ࡴ۬لسَّيِّئَةَ وَمِمَّا رَزَقْنَٰهُمْ يُنفِقُونَ࣌', 'أولئك يوتون أجرهم مرتين بما صبروا ويدرءون بالحسنة ࡴلسيئة ومما رزقنهم ينفقون࣌', NULL, 392, 'local:warsh-text.json'),
  ('warsh-28-55', 'warsh', 28, 55, 'وَإِذَا سَمِعُواْ ࡲ۬للَّغْوَ أَعْرَضُواْ عَنْهُ وَقَالُواْ لَنَآ أَعْمَٰلُنَا وَلَكُمُۥٓ أَعْمَٰلُكُمْ سَلَٰمٌ عَلَيْكُمْ لَا نَبْتَغِے ࡴ۬لْجَٰهِلِينَ࣌', 'وإذا سمعوا ࡲللغو أعرضوا عنه وقالوا لنا أعملنا ولكم أعملكم سلم عليكم لا نبتغے ࡴلجهلين࣌', NULL, 392, 'local:warsh-text.json'),
  ('warsh-28-56', 'warsh', 28, 56, 'إِنَّكَ لَا تَهْدِے مَنَ ࡰحْبَبْتَ࣌ وَلَٰكِنَّ ࡰ۬للَّهَ يَهْدِے مَنْ يَّشَآءُ࣌ وَهُوَ أَعْلَمُ بِالْمُهْتَدِينَ࣌', 'إنك لا تهدے من ࡰحببت࣌ ولكن ࡰلله يهدے من يشاء࣌ وهو أعلم بالمهتدين࣌', NULL, 392, 'local:warsh-text.json'),
  ('warsh-28-57', 'warsh', 28, 57, 'وَقَالُوٓاْ إِن نَّتَّبِعِ ࡴ۬لْهُدٜىٰ مَعَكَ نُتَخَطَّفْ مِنَ ࡰرْضِنَآ࣌ أَوَلَمْ نُمَكِّن لَّهُمْ حَرَماً اٰمِناࣰ تُجْبٜىٰٓ إِلَيْهِ ثَمَرَٰتُ كُلِّ شَےْءࣲ رِّزْقاࣰ مِّن لَّدُنَّا࣌ وَلَٰكِنَّ أَكْثَرَهُمْ لَا يَعْلَمُونَ࣌', 'وقالوا إن نتبع ࡴلهدى معك نتخطف من ࡰرضنا࣌ أولم نمكن لهم حرما امنا تجبى إليه ثمرت كل شےء رزقا من لدنا࣌ ولكن أكثرهم لا يعلمون࣌', NULL, 392, 'local:warsh-text.json'),
  ('warsh-28-58', 'warsh', 28, 58, 'وَكَمَ ࡰهْلَكْنَا مِن قَرْيَةِۢ بَطِرَتْ مَعِيشَتَهَا࣌ فَتِلْكَ مَسَٰكِنُهُمْ لَمْ تُسْكَن مِّنۢ بَعْدِهِمُۥٓ إِلَّا قَلِيلاࣰ وَكُنَّا نَحْنُ ࡲ۬لْوَٰرِثِينَ࣌', 'وكم ࡰهلكنا من قرية بطرت معيشتها࣌ فتلك مسكنهم لم تسكن من بعدهم إلا قليلا وكنا نحن ࡲلورثين࣌', NULL, 392, 'local:warsh-text.json'),
  ('warsh-28-59', 'warsh', 28, 59, 'وَمَا كَانَ رَبُّكَ مُهْلِكَ ࡰ۬لْقُرٜىٰ حَتَّىٰ يَبْعَثَ فِےٓ أُمِّهَا رَسُولاࣰ يَتْلُواْ عَلَيْهِمُۥٓ ءَايَٰتِنَا࣌ وَمَا كُنَّا مُهْلِكِے ࡴ۬لْقُرٜىٰٓ إِلَّا وَأَهْلُهَا ظَٰلِمُونَ࣌', 'وما كان ربك مهلك ࡰلقرى حتى يبعث فے أمها رسولا يتلوا عليهم ءايتنا࣌ وما كنا مهلكے ࡴلقرى إلا وأهلها ظلمون࣌', NULL, 392, 'local:warsh-text.json'),
  ('warsh-28-60', 'warsh', 28, 60, 'وَمَآ أُوتِيتُم مِّن شَےْءࣲ فَمَتَٰعُ ࡲ۬لْحَيَوٰةِ ࡴ۬لدُّنْيٜا وَزِينَتُهَا࣌ وَمَا عِندَ ࡰ۬للَّهِ خَيْرࣱ وَأَبْقٜىٰٓ࣌ أَفَلَا تَعْقِلُونَ࣌', 'وما أوتيتم من شےء فمتع ࡲلحيوة ࡴلدنيا وزينتها࣌ وما عند ࡰلله خير وأبقى࣌ أفلا تعقلون࣌', NULL, 393, 'local:warsh-text.json'),
  ('warsh-28-61', 'warsh', 28, 61, 'أَفَمَنْ وَّعَدْنَٰهُ وَعْداً حَسَناࣰ فَهُوَ لَٰقِيهِ كَمَن مَّتَّعْنَٰهُ مَتَٰعَ ࡰ۬لْحَيَوٰةِ ࡴ۬لدُّنْيٜا ثُمَّ هُوَ يَوْمَ ࡰ۬لْقِيَٰمَةِ مِنَ ࡰ۬لْمُحْضَرِينَ࣌', 'أفمن وعدنه وعدا حسنا فهو لقيه كمن متعنه متع ࡰلحيوة ࡴلدنيا ثم هو يوم ࡰلقيمة من ࡰلمحضرين࣌', NULL, 393, 'local:warsh-text.json'),
  ('warsh-28-62', 'warsh', 28, 62, 'وَيَوْمَ يُنَادِيهِمْ فَيَقُولُ أَيْنَ شُرَكَآءِيَ ࡰ۬لذِينَ كُنتُمْ تَزْعُمُونَ࣌', 'ويوم يناديهم فيقول أين شركاءي ࡰلذين كنتم تزعمون࣌', NULL, 393, 'local:warsh-text.json'),
  ('warsh-28-63', 'warsh', 28, 63, '۞ قَالَ ࡰ۬لذِينَ حَقَّ عَلَيْهِمُ ࡲ۬لْقَوْلُ رَبَّنَا هَٰٓؤُلَآءِ ࡴ۬لذِينَ أَغْوَيْنَآ أَغْوَيْنَٰهُمْ كَمَا غَوَيْنَا࣌ تَبَرَّأْنَآ إِلَيْكَ࣌ مَا كَانُوٓاْ إِيَّانَا يَعْبُدُونَ࣌', 'قال ࡰلذين حق عليهم ࡲلقول ربنا هؤلاء ࡴلذين أغوينا أغوينهم كما غوينا࣌ تبرأنا إليك࣌ ما كانوا إيانا يعبدون࣌', NULL, 393, 'local:warsh-text.json'),
  ('warsh-28-64', 'warsh', 28, 64, 'وَقِيلَ ࡸَدْعُواْ شُرَكَآءَكُمْ فَدَعَوْهُمْ فَلَمْ يَسْتَجِيبُواْ لَهُمْ وَرَأَوُاْ ࡲ۬لْعَذَابَ لَوَ ࡰنَّهُمْ كَانُواْ يَهْتَدُونَ࣌', 'وقيل ࡸدعوا شركاءكم فدعوهم فلم يستجيبوا لهم ورأوا ࡲلعذاب لو ࡰنهم كانوا يهتدون࣌', NULL, 393, 'local:warsh-text.json'),
  ('warsh-28-65', 'warsh', 28, 65, 'وَيَوْمَ يُنَادِيهِمْ فَيَقُولُ مَاذَآ أَجَبْتُمُ ࡲ۬لْمُرْسَلِينَ࣌', 'ويوم يناديهم فيقول ماذا أجبتم ࡲلمرسلين࣌', NULL, 393, 'local:warsh-text.json'),
  ('warsh-28-66', 'warsh', 28, 66, 'فَعَمِيَتْ عَلَيْهِمُ ࡲ۬لَانۢبَآءُ يَوْمَئِذࣲ فَهُمْ لَا يَتَسَآءَلُونَ࣌', 'فعميت عليهم ࡲلانباء يومئذ فهم لا يتساءلون࣌', NULL, 393, 'local:warsh-text.json'),
  ('warsh-28-67', 'warsh', 28, 67, 'فَأَمَّا مَن تَابَ وَءَامَنَ وَعَمِلَ صَٰلِحاࣰ فَعَسٜىٰٓ أَنْ يَّكُونَ مِنَ ࡰ۬لْمُفْلِحِينَ࣌', 'فأما من تاب وءامن وعمل صلحا فعسى أن يكون من ࡰلمفلحين࣌', NULL, 393, 'local:warsh-text.json'),
  ('warsh-28-68', 'warsh', 28, 68, 'وَرَبُّكَ يَخْلُقُ مَا يَشَآءُ وَيَخْتَارُ࣌ مَا كَانَ لَهُمُ ࡲ۬لْخِيَرَةُ࣌ سُبْحَٰنَ ࡰ۬للَّهِ وَتَعَٰلٜىٰ عَمَّا يُشْرِكُونَ࣌', 'وربك يخلق ما يشاء ويختار࣌ ما كان لهم ࡲلخيرة࣌ سبحن ࡰلله وتعلى عما يشركون࣌', NULL, 393, 'local:warsh-text.json'),
  ('warsh-28-69', 'warsh', 28, 69, 'وَرَبُّكَ يَعْلَمُ مَا تُكِنُّ صُدُورُهُمْ وَمَا يُعْلِنُونَ࣌', 'وربك يعلم ما تكن صدورهم وما يعلنون࣌', NULL, 393, 'local:warsh-text.json'),
  ('warsh-28-70', 'warsh', 28, 70, 'وَهُوَ ࡰ۬للَّهُ لَآ إِلَٰهَ إِلَّا هُوَ࣌ لَهُ ࡲ۬لْحَمْدُ فِے ࡴ۬لُاولٜىٰ وَالَاخِرَةِ࣌ وَلَهُ ࡲ۬لْحُكْمُ࣌ وَإِلَيْهِ تُرْجَعُونَ࣌', 'وهو ࡰلله لا إله إلا هو࣌ له ࡲلحمد فے ࡴلاولى والاخرة࣌ وله ࡲلحكم࣌ وإليه ترجعون࣌', NULL, 393, 'local:warsh-text.json'),
  ('warsh-28-71', 'warsh', 28, 71, 'قُلَ ࡰرَٰٓيْتُمُۥٓ إِن جَعَلَ ࡰ۬للَّهُ عَلَيْكُمُ ࡲ۬ليْلَ سَرْمَداً ࡴلَىٰ يَوْمِ ࡴ۬لْقِيَٰمَةِ مَنِ ࡴلَٰهٌ غَيْرُ ࡲ۬للَّهِ يَاتِيكُم بِضِيَآءٍ࣌ ࡰفَلَا تَسْمَعُونَ࣌', 'قل ࡰريتم إن جعل ࡰلله عليكم ࡲليل سرمدا ࡴلى يوم ࡴلقيمة من ࡴله غير ࡲلله ياتيكم بضياء࣌ ࡰفلا تسمعون࣌', NULL, 394, 'local:warsh-text.json'),
  ('warsh-28-72', 'warsh', 28, 72, 'قُلَ ࡰرَٰٓيْتُمُۥٓ إِن جَعَلَ ࡰ۬للَّهُ عَلَيْكُمُ ࡲ۬لنَّهَارَ سَرْمَداً ࡴلَىٰ يَوْمِ ࡴ۬لْقِيَٰمَةِ مَنِ ࡴلَٰهٌ غَيْرُ ࡲ۬للَّهِ يَاتِيكُم بِلَيْلࣲ تَسْكُنُونَ فِيهِ࣌ أَفَلَا تُبْصِرُونَ࣌', 'قل ࡰريتم إن جعل ࡰلله عليكم ࡲلنهار سرمدا ࡴلى يوم ࡴلقيمة من ࡴله غير ࡲلله ياتيكم بليل تسكنون فيه࣌ أفلا تبصرون࣌', NULL, 394, 'local:warsh-text.json'),
  ('warsh-28-73', 'warsh', 28, 73, 'وَمِن رَّحْمَتِهِۦ جَعَلَ لَكُمُ ࡲ۬ليْلَ وَالنَّهَارَ لِتَسْكُنُواْ فِيهِ وَلِتَبْتَغُواْ مِن فَضْلِهِۦ وَلَعَلَّكُمْ تَشْكُرُونَ࣌', 'ومن رحمته جعل لكم ࡲليل والنهار لتسكنوا فيه ولتبتغوا من فضله ولعلكم تشكرون࣌', NULL, 394, 'local:warsh-text.json'),
  ('warsh-28-74', 'warsh', 28, 74, 'وَيَوْمَ يُنَادِيهِمْ فَيَقُولُ أَيْنَ شُرَكَآءِيَ ࡰ۬لذِينَ كُنتُمْ تَزْعُمُونَ࣌', 'ويوم يناديهم فيقول أين شركاءي ࡰلذين كنتم تزعمون࣌', NULL, 394, 'local:warsh-text.json'),
  ('warsh-28-75', 'warsh', 28, 75, 'وَنَزَعْنَا مِن كُلِّ أُمَّةࣲ شَهِيداࣰ فَقُلْنَا هَاتُواْ بُرْهَٰنَكُمْ فَعَلِمُوٓاْ أَنَّ ࡰ۬لْحَقَّ لِلهِ وَضَلَّ عَنْهُم مَّا كَانُواْ يَفْتَرُونَ࣌', 'ونزعنا من كل أمة شهيدا فقلنا هاتوا برهنكم فعلموا أن ࡰلحق لله وضل عنهم ما كانوا يفترون࣌', NULL, 394, 'local:warsh-text.json'),
  ('warsh-28-76', 'warsh', 28, 76, '۞ إِنَّ قَارُونَ كَانَ مِن قَوْمِ مُوسٜىٰ فَبَغٜىٰ عَلَيْهِمْ࣌ وَءَاتَيْنَٰهُ مِنَ ࡰ۬لْكُنُوزِ مَآ إِنَّ مَفَاتِحَهُۥ لَتَنُوٓأُ بِالْعُصْبَةِ أُوْلِے ࡴ۬لْقُوَّةِ࣌ إِذْ قَالَ لَهُۥ قَوْمُهُۥ لَا تَفْرَحِ ࡴنَّ ࡰ۬للَّهَ لَا يُحِبُّ ࡲ۬لْفَرِحِينَ࣌', 'إن قارون كان من قوم موسى فبغى عليهم࣌ وءاتينه من ࡰلكنوز ما إن مفاتحه لتنوأ بالعصبة أولے ࡴلقوة࣌ إذ قال له قومه لا تفرح ࡴن ࡰلله لا يحب ࡲلفرحين࣌', NULL, 394, 'local:warsh-text.json'),
  ('warsh-28-77', 'warsh', 28, 77, 'وَابْتَغِ فِيمَآ ءَاتٜيٰكَ ࡰ۬للَّهُ ࡲ۬لدَّارَ ࡰ۬لَاخِرَةَ࣌ وَلَا تَنسَ نَصِيبَكَ مِنَ ࡰ۬لدُّنْيٜا࣌ وَأَحْسِن كَمَآ أَحْسَنَ ࡰ۬للَّهُ إِلَيْكَ࣌ وَلَا تَبْغِ ࡴ۬لْفَسَادَ فِے ࡴ۬لَارْضِ࣌ إِنَّ ࡰ۬للَّهَ لَا يُحِبُّ ࡲ۬لْمُفْسِدِينَ࣌', 'وابتغ فيما ءاتيك ࡰلله ࡲلدار ࡰلاخرة࣌ ولا تنس نصيبك من ࡰلدنيا࣌ وأحسن كما أحسن ࡰلله إليك࣌ ولا تبغ ࡴلفساد فے ࡴلارض࣌ إن ࡰلله لا يحب ࡲلمفسدين࣌', NULL, 394, 'local:warsh-text.json'),
  ('warsh-28-78', 'warsh', 28, 78, 'قَالَ إِنَّمَآ أُوتِيتُهُۥ عَلَىٰ عِلْمٍ عِندِيَ࣌ أَوَلَمْ يَعْلَمَ ࡰنَّ ࡰ۬للَّهَ قَدَ ࡰهْلَكَ مِن قَبْلِهِۦ مِنَ ࡰ۬لْقُرُونِ مَنْ هُوَ أَشَدُّ مِنْهُ قُوَّةࣰ وَأَكْثَرُ جَمْعاࣰ࣌ وَلَا يُسْـَٔلُ عَن ذُنُوبِهِمُ ࡲ۬لْمُجْرِمُونَ࣌', 'قال إنما أوتيته على علم عندي࣌ أولم يعلم ࡰن ࡰلله قد ࡰهلك من قبله من ࡰلقرون من هو أشد منه قوة وأكثر جمعا࣌ ولا يسل عن ذنوبهم ࡲلمجرمون࣌', NULL, 395, 'local:warsh-text.json'),
  ('warsh-28-79', 'warsh', 28, 79, 'فَخَرَجَ عَلَىٰ قَوْمِهِۦ فِے زِينَتِهِۦ࣌ قَالَ ࡰ۬لذِينَ يُرِيدُونَ ࡰ۬لْحَيَوٰةَ ࡰ۬لدُّنْيٜا يَٰلَيْتَ لَنَا مِثْلَ مَآ أُوتِيَ قَارُونُ إِنَّهُۥ لَذُو حَظٍّ عَظِيمࣲ࣌', 'فخرج على قومه فے زينته࣌ قال ࡰلذين يريدون ࡰلحيوة ࡰلدنيا يليت لنا مثل ما أوتي قارون إنه لذو حظ عظيم࣌', NULL, 395, 'local:warsh-text.json'),
  ('warsh-28-80', 'warsh', 28, 80, 'وَقَالَ ࡰ۬لذِينَ أُوتُواْ ࡲ۬لْعِلْمَ وَيْلَكُمْ ثَوَابُ ࡲ۬للَّهِ خَيْرࣱ لِّمَنَ اٰمَنَ وَعَمِلَ صَٰلِحاࣰ࣌ وَلَا يُلَقّٜيٰهَآ إِلَّا ࡰ۬لصَّٰبِرُونَ࣌', 'وقال ࡰلذين أوتوا ࡲلعلم ويلكم ثواب ࡲلله خير لمن امن وعمل صلحا࣌ ولا يلقيها إلا ࡰلصبرون࣌', NULL, 395, 'local:warsh-text.json'),
  ('warsh-28-81', 'warsh', 28, 81, 'فَخَسَفْنَا بِهِۦ وَبِدٜارِهِ ࡴ۬لَارْضَ࣌ فَمَا كَانَ لَهُۥ مِن فِئَةࣲ يَنصُرُونَهُۥ مِن دُونِ ࡴ۬للَّهِ࣌ وَمَا كَانَ مِنَ ࡰ۬لْمُنتَصِرِينَ࣌', 'فخسفنا به وبداره ࡴلارض࣌ فما كان له من فئة ينصرونه من دون ࡴلله࣌ وما كان من ࡰلمنتصرين࣌', NULL, 395, 'local:warsh-text.json'),
  ('warsh-28-82', 'warsh', 28, 82, 'وَأَصْبَحَ ࡰ۬لذِينَ تَمَنَّوْاْ مَكَانَهُۥ بِالَامْسِ يَقُولُونَ وَيْكَأَنَّ ࡰ۬للَّهَ يَبْسُطُ ࡲ۬لرِّزْقَ لِمَنْ يَّشَآءُ مِنْ عِبَادِهِۦ وَيَقْدِرُ࣌ لَوْلَآ أَن مَّنَّ ࡰ۬للَّهُ عَلَيْنَا لَخُسِفَ بِنَا࣌ وَيْكَأَنَّهُۥ لَا يُفْلِحُ ࡲ۬لْكَٰفِرُونَ࣌', 'وأصبح ࡰلذين تمنوا مكانه بالامس يقولون ويكأن ࡰلله يبسط ࡲلرزق لمن يشاء من عباده ويقدر࣌ لولا أن من ࡰلله علينا لخسف بنا࣌ ويكأنه لا يفلح ࡲلكفرون࣌', NULL, 395, 'local:warsh-text.json'),
  ('warsh-28-83', 'warsh', 28, 83, '۞ تِلْكَ ࡰ۬لدَّارُ ࡲ۬لَاخِرَةُ نَجْعَلُهَا لِلذِينَ لَا يُرِيدُونَ عُلُوّاࣰ فِے ࡴ۬لَارْضِ وَلَا فَسَاداࣰ࣌ وَالْعَٰقِبَةُ لِلْمُتَّقِينَ࣌', 'تلك ࡰلدار ࡲلاخرة نجعلها للذين لا يريدون علوا فے ࡴلارض ولا فسادا࣌ والعقبة للمتقين࣌', NULL, 395, 'local:warsh-text.json'),
  ('warsh-28-84', 'warsh', 28, 84, 'مَن جَآءَ بِالْحَسَنَةِ فَلَهُۥ خَيْرࣱ مِّنْهَا࣌ وَمَن جَآءَ بِالسَّيِّئَةِ فَلَا يُجْزَى ࡰ۬لذِينَ عَمِلُواْ ࡲ۬لسَّيِّـَٔاتِ إِلَّا مَا كَانُواْ يَعْمَلُونَ࣌', 'من جاء بالحسنة فله خير منها࣌ ومن جاء بالسيئة فلا يجزى ࡰلذين عملوا ࡲلسيات إلا ما كانوا يعملون࣌', NULL, 395, 'local:warsh-text.json'),
  ('warsh-28-85', 'warsh', 28, 85, 'إِنَّ ࡰ۬لذِے فَرَضَ عَلَيْكَ ࡰ۬لْقُرْءَانَ لَرَآدُّكَ إِلَىٰ مَعَادࣲ࣌ قُل رَّبِّيَ أَعْلَمُ مَن جَآءَ بِالْهُدٜىٰ وَمَنْ هُوَ فِے ضَلَٰلࣲ مُّبِينࣲ࣌', 'إن ࡰلذے فرض عليك ࡰلقرءان لرادك إلى معاد࣌ قل ربي أعلم من جاء بالهدى ومن هو فے ضلل مبين࣌', NULL, 396, 'local:warsh-text.json'),
  ('warsh-28-86', 'warsh', 28, 86, 'وَمَا كُنتَ تَرْجُوٓاْ أَنْ يُّلْقٜىٰٓ إِلَيْكَ ࡰ۬لْكِتَٰبُ إِلَّا رَحْمَةࣰ مِّن رَّبِّكَ࣌ فَلَا تَكُونَنَّ ظَهِيراࣰ لِّلْكٜـٰفِرِينَ࣌', 'وما كنت ترجوا أن يلقى إليك ࡰلكتب إلا رحمة من ربك࣌ فلا تكونن ظهيرا للكفرين࣌', NULL, 396, 'local:warsh-text.json'),
  ('warsh-28-87', 'warsh', 28, 87, 'وَلَا يَصُدُّنَّكَ عَنَ اٰيَٰتِ ࡴ۬للَّهِ بَعْدَ إِذُ ࡳنزِلَتِ ࡴلَيْكَ࣌ وَادْعُ إِلَىٰ رَبِّكَ࣌ وَلَا تَكُونَنَّ مِنَ ࡰ۬لْمُشْرِكِينَ࣌', 'ولا يصدنك عن ايت ࡴلله بعد إذ ࡳنزلت ࡴليك࣌ وادع إلى ربك࣌ ولا تكونن من ࡰلمشركين࣌', NULL, 396, 'local:warsh-text.json'),
  ('warsh-28-88', 'warsh', 28, 88, 'وَلَا تَدْعُ مَعَ ࡰ۬للَّهِ إِلَٰهاً اٰخَرَ࣌ لَآ إِلَٰهَ إِلَّا هُوَ࣌ كُلُّ شَےْءٍ هَالِكٌ ࡴلَّا وَجْهَهُۥ࣌ لَهُ ࡲ۬لْحُكْمُ࣌ وَإِلَيْهِ تُرْجَعُونَ࣌', 'ولا تدع مع ࡰلله إلها اخر࣌ لا إله إلا هو࣌ كل شےء هالك ࡴلا وجهه࣌ له ࡲلحكم࣌ وإليه ترجعون࣌', NULL, 396, 'local:warsh-text.json'),
  ('warsh-29-1', 'warsh', 29, 1, 'أَلَٓمِّٓ࣌ ࡰحَسِبَ ࡰ۬لنَّاسُ أَنْ يُّتْرَكُوٓاْ أَنْ يَّقُولُوٓاْ ءَامَنَّا وَهُمْ لَا يُفْتَنُونَ࣌', 'ألم࣌ ࡰحسب ࡰلناس أن يتركوا أن يقولوا ءامنا وهم لا يفتنون࣌', NULL, 396, 'local:warsh-text.json'),
  ('warsh-29-2', 'warsh', 29, 2, 'وَلَقَدْ فَتَنَّا ࡰ۬لذِينَ مِن قَبْلِهِمْ࣌ فَلَيَعْلَمَنَّ ࡰ۬للَّهُ ࡲ۬لذِينَ صَدَقُواْ وَلَيَعْلَمَنَّ ࡰ۬لْكَٰذِبِينَ࣌', 'ولقد فتنا ࡰلذين من قبلهم࣌ فليعلمن ࡰلله ࡲلذين صدقوا وليعلمن ࡰلكذبين࣌', NULL, 396, 'local:warsh-text.json'),
  ('warsh-29-3', 'warsh', 29, 3, 'أَمْ حَسِبَ ࡰ۬لذِينَ يَعْمَلُونَ ࡰ۬لسَّيِّـَٔاتِ أَنْ يَّسْبِقُونَا࣌ سَآءَ مَا يَحْكُمُونَ࣌', 'أم حسب ࡰلذين يعملون ࡰلسيات أن يسبقونا࣌ ساء ما يحكمون࣌', NULL, 396, 'local:warsh-text.json'),
  ('warsh-29-4', 'warsh', 29, 4, 'مَن كَانَ يَرْجُواْ لِقَآءَ ࡰ۬للَّهِ فَإِنَّ أَجَلَ ࡰ۬للَّهِ لَأٓتࣲ࣌ وَهُوَ ࡰ۬لسَّمِيعُ ࡲ۬لْعَلِيمُ࣌', 'من كان يرجوا لقاء ࡰلله فإن أجل ࡰلله لأت࣌ وهو ࡰلسميع ࡲلعليم࣌', NULL, 396, 'local:warsh-text.json'),
  ('warsh-29-5', 'warsh', 29, 5, 'وَمَن جَٰهَدَ فَإِنَّمَا يُجَٰهِدُ لِنَفْسِهِۦٓ࣌ إِنَّ ࡰ۬للَّهَ لَغَنِيٌّ عَنِ ࡴ۬لْعَٰلَمِينَ࣌', 'ومن جهد فإنما يجهد لنفسه࣌ إن ࡰلله لغني عن ࡴلعلمين࣌', NULL, 396, 'local:warsh-text.json'),
  ('warsh-29-6', 'warsh', 29, 6, 'وَالذِينَ ءَامَنُواْ وَعَمِلُواْ ࡲ۬لصَّٰلِحَٰتِ لَنُكَفِّرَنَّ عَنْهُمْ سَيِّـَٔاتِهِمْ وَلَنَجْزِيَنَّهُمُۥٓ أَحْسَنَ ࡰ۬لذِے كَانُواْ يَعْمَلُونَ࣌', 'والذين ءامنوا وعملوا ࡲلصلحت لنكفرن عنهم سياتهم ولنجزينهم أحسن ࡰلذے كانوا يعملون࣌', NULL, 397, 'local:warsh-text.json'),
  ('warsh-29-7', 'warsh', 29, 7, '۞ وَوَصَّيْنَا ࡰ۬لِانسَٰنَ بِوَٰلِدَيْهِ حُسْناࣰ࣌ وَإِن جَٰهَدَٰكَ لِتُشْرِكَ بِے مَا لَيْسَ لَكَ بِهِۦ عِلْمࣱ فَلَا تُطِعْهُمَآ࣌ إِلَيَّ مَرْجِعُكُمْ فَأُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ࣌', 'ووصينا ࡰلانسن بولديه حسنا࣌ وإن جهدك لتشرك بے ما ليس لك به علم فلا تطعهما࣌ إلي مرجعكم فأنبئكم بما كنتم تعملون࣌', NULL, 397, 'local:warsh-text.json'),
  ('warsh-29-8', 'warsh', 29, 8, 'وَالذِينَ ءَامَنُواْ وَعَمِلُواْ ࡲ۬لصَّٰلِحَٰتِ لَنُدْخِلَنَّهُمْ فِے ࡴ۬لصَّٰلِحِينَ࣌', 'والذين ءامنوا وعملوا ࡲلصلحت لندخلنهم فے ࡴلصلحين࣌', NULL, 397, 'local:warsh-text.json'),
  ('warsh-29-9', 'warsh', 29, 9, 'وَمِنَ ࡰ۬لنَّاسِ مَنْ يَّقُولُ ءَامَنَّا بِاللَّهِ فَإِذَآ أُوذِيَ فِے ࡴ۬للَّهِ جَعَلَ فِتْنَةَ ࡰ۬لنَّاسِ كَعَذَابِ ࡴ۬للَّهِ࣌ وَلَئِن جَآءَ نَصْرࣱ مِّن رَّبِّكَ لَيَقُولُنَّ إِنَّا كُنَّا مَعَكُمُۥٓ࣌ أَوَلَيْسَ ࡰ۬للَّهُ بِأَعْلَمَ بِمَا فِے صُدُورِ ࡴ۬لْعَٰلَمِينَ࣌', 'ومن ࡰلناس من يقول ءامنا بالله فإذا أوذي فے ࡴلله جعل فتنة ࡰلناس كعذاب ࡴلله࣌ ولئن جاء نصر من ربك ليقولن إنا كنا معكم࣌ أوليس ࡰلله بأعلم بما فے صدور ࡴلعلمين࣌', NULL, 397, 'local:warsh-text.json'),
  ('warsh-29-10', 'warsh', 29, 10, 'وَلَيَعْلَمَنَّ ࡰ۬للَّهُ ࡲ۬لذِينَ ءَامَنُواْ وَلَيَعْلَمَنَّ ࡰ۬لْمُنَٰفِقِينَ࣌', 'وليعلمن ࡰلله ࡲلذين ءامنوا وليعلمن ࡰلمنفقين࣌', NULL, 397, 'local:warsh-text.json'),
  ('warsh-29-11', 'warsh', 29, 11, 'وَقَالَ ࡰ۬لذِينَ كَفَرُواْ لِلذِينَ ءَامَنُواْ ࡲٜتَّبِعُواْ سَبِيلَنَا وَلْنَحْمِلْ خَطَٰيٜـٰكُمْ࣌ وَمَا هُم بِحَٰمِلِينَ مِنْ خَطَٰيٜـٰهُم مِّن شَےْءٍ࣌ ࡴنَّهُمْ لَكَٰذِبُونَ࣌', 'وقال ࡰلذين كفروا للذين ءامنوا ࡲتبعوا سبيلنا ولنحمل خطيكم࣌ وما هم بحملين من خطيهم من شےء࣌ ࡴنهم لكذبون࣌', NULL, 397, 'local:warsh-text.json'),
  ('warsh-29-12', 'warsh', 29, 12, 'وَلَيَحْمِلُنَّ أَثْقَالَهُمْ وَأَثْقَالاࣰ مَّعَ أَثْقَالِهِمْ࣌ وَلَيُسْـَٔلُنَّ يَوْمَ ࡰ۬لْقِيَٰمَةِ عَمَّا كَانُواْ يَفْتَرُونَ࣌', 'وليحملن أثقالهم وأثقالا مع أثقالهم࣌ وليسلن يوم ࡰلقيمة عما كانوا يفترون࣌', NULL, 397, 'local:warsh-text.json'),
  ('warsh-29-13', 'warsh', 29, 13, 'وَلَقَدَ ࡰرْسَلْنَا نُوحاً ࡴلَىٰ قَوْمِهِۦ فَلَبِثَ فِيهِمُۥٓ أَلْفَ سَنَةٍ ࡴلَّا خَمْسِينَ عَاماࣰ فَأَخَذَهُمُ ࡲ۬لطُّوفَانُ وَهُمْ ظَٰلِمُونَ࣌', 'ولقد ࡰرسلنا نوحا ࡴلى قومه فلبث فيهم ألف سنة ࡴلا خمسين عاما فأخذهم ࡲلطوفان وهم ظلمون࣌', NULL, 397, 'local:warsh-text.json'),
  ('warsh-29-14', 'warsh', 29, 14, 'فَأَنجَيْنَٰهُ وَأَصْحَٰبَ ࡰ۬لسَّفِينَةِ࣌ وَجَعَلْنَٰهَآ ءَايَةࣰ لِّلْعَٰلَمِينَ࣌', 'فأنجينه وأصحب ࡰلسفينة࣌ وجعلنها ءاية للعلمين࣌', NULL, 398, 'local:warsh-text.json'),
  ('warsh-29-15', 'warsh', 29, 15, 'وَإِبْرَٰهِيمَ إِذْ قَالَ لِقَوْمِهِ ࡴ࢈عْبُدُواْ ࡲ۬للَّهَ وَاتَّقُوهُ࣌ ذَٰلِكُمْ خَيْرࣱ لَّكُمُۥٓ إِن كُنتُمْ تَعْلَمُونَ࣌', 'وإبرهيم إذ قال لقومه ࡴ࢈عبدوا ࡲلله واتقوه࣌ ذلكم خير لكم إن كنتم تعلمون࣌', NULL, 398, 'local:warsh-text.json'),
  ('warsh-29-16', 'warsh', 29, 16, '۞ إِنَّمَا تَعْبُدُونَ مِن دُونِ ࡴ۬للَّهِ أَوْثَٰناࣰ وَتَخْلُقُونَ إِفْكاً࣌ ࡴنَّ ࡰ۬لذِينَ تَعْبُدُونَ مِن دُونِ ࡴ۬للَّهِ لَا يَمْلِكُونَ لَكُمْ رِزْقاࣰ࣌ فَابْتَغُواْ عِندَ ࡰ۬للَّهِ ࡴ۬لرِّزْقَ࣌ وَاعْبُدُوهُ࣌ وَاشْكُرُواْ لَهُۥٓ࣌ إِلَيْهِ تُرْجَعُونَ࣌', 'إنما تعبدون من دون ࡴلله أوثنا وتخلقون إفكا࣌ ࡴن ࡰلذين تعبدون من دون ࡴلله لا يملكون لكم رزقا࣌ فابتغوا عند ࡰلله ࡴلرزق࣌ واعبدوه࣌ واشكروا له࣌ إليه ترجعون࣌', NULL, 398, 'local:warsh-text.json'),
  ('warsh-29-17', 'warsh', 29, 17, 'وَإِن تُكَذِّبُواْ فَقَدْ كَذَّبَ أُمَمࣱ مِّن قَبْلِكُمْ࣌ وَمَا عَلَى ࡰ۬لرَّسُولِ إِلَّا ࡰ۬لْبَلَٰغُ ࡲ۬لْمُبِينُ࣌', 'وإن تكذبوا فقد كذب أمم من قبلكم࣌ وما على ࡰلرسول إلا ࡰلبلغ ࡲلمبين࣌', NULL, 398, 'local:warsh-text.json'),
  ('warsh-29-18', 'warsh', 29, 18, 'أَوَلَمْ يَرَوْاْ كَيْفَ يُبْدِۓُ ࡲ۬للَّهُ ࡲ۬لْخَلْقَ࣌ ثُمَّ يُعِيدُهُۥٓ࣌ إِنَّ ذَٰلِكَ عَلَى ࡰ۬للَّهِ يَسِيرࣱ࣌', 'أولم يروا كيف يبدے ࡲلله ࡲلخلق࣌ ثم يعيده࣌ إن ذلك على ࡰلله يسير࣌', NULL, 398, 'local:warsh-text.json'),
  ('warsh-29-19', 'warsh', 29, 19, 'قُلْ سِيرُواْ فِے ࡴ۬لَارْضِ فَانظُرُواْ كَيْفَ بَدَأَ ࡰ۬لْخَلْقَ࣌ ثُمَّ ࡰ۬للَّهُ يُنشِۓُ ࡲ۬لنَّشْأَةَ ࡰ۬لَاخِرَةَ࣌ إِنَّ ࡰ۬للَّهَ عَلَىٰ كُلِّ شَےْءࣲ قَدِيرࣱ࣌', 'قل سيروا فے ࡴلارض فانظروا كيف بدأ ࡰلخلق࣌ ثم ࡰلله ينشے ࡲلنشأة ࡰلاخرة࣌ إن ࡰلله على كل شےء قدير࣌', NULL, 398, 'local:warsh-text.json'),
  ('warsh-29-20', 'warsh', 29, 20, 'يُعَذِّبُ مَنْ يَّشَآءُ وَيَرْحَمُ مَنْ يَّشَآءُ࣌ وَإِلَيْهِ تُقْلَبُونَ࣌', 'يعذب من يشاء ويرحم من يشاء࣌ وإليه تقلبون࣌', NULL, 398, 'local:warsh-text.json'),
  ('warsh-29-21', 'warsh', 29, 21, 'وَمَآ أَنتُم بِمُعْجِزِينَ فِے ࡴ۬لَارْضِ وَلَا فِے ࡴ۬لسَّمَآءِ࣌ وَمَا لَكُم مِّن دُونِ ࡴ۬للَّهِ مِنْ وَّلِيࣲّ وَلَا نَصِيرࣲ࣌', 'وما أنتم بمعجزين فے ࡴلارض ولا فے ࡴلسماء࣌ وما لكم من دون ࡴلله من ولي ولا نصير࣌', NULL, 398, 'local:warsh-text.json'),
  ('warsh-29-22', 'warsh', 29, 22, 'وَالذِينَ كَفَرُواْ بِـَٔايَٰتِ ࡴ۬للَّهِ وَلِقَآئِهِۦٓ أُوْلَٰٓئِكَ يَئِسُواْ مِن رَّحْمَتِے࣌ وَأُوْلَٰٓئِكَ لَهُمْ عَذَابٌ ࡰلِيمࣱ࣌', 'والذين كفروا بايت ࡴلله ولقائه أولئك يئسوا من رحمتے࣌ وأولئك لهم عذاب ࡰليم࣌', NULL, 398, 'local:warsh-text.json'),
  ('warsh-29-23', 'warsh', 29, 23, 'فَمَا كَانَ جَوَابَ قَوْمِهِۦٓ إِلَّآ أَن قَالُواْ ࡲ࢈قْتُلُوهُ أَوْ حَرِّقُوهُ࣌ فَأَنجٜيٰهُ ࡲ۬للَّهُ مِنَ ࡰ۬لنّٜارِ࣌ إِنَّ فِے ذَٰلِكَ لَأٓيَٰتࣲ لِّقَوْمࣲ يُومِنُونَ࣌', 'فما كان جواب قومه إلا أن قالوا ࡲ࢈قتلوه أو حرقوه࣌ فأنجيه ࡲلله من ࡰلنار࣌ إن فے ذلك لأيت لقوم يومنون࣌', NULL, 399, 'local:warsh-text.json'),
  ('warsh-29-24', 'warsh', 29, 24, 'وَقَالَ إِنَّمَا ࡰٜتَّخَذتُّم مِّن دُونِ ࡴ۬للَّهِ أَوْثَٰناࣰ مَّوَدَّةَۢ بَيْنَكُمْ فِے ࡴ۬لْحَيَوٰةِ ࡴ۬لدُّنْيٜا࣌ ثُمَّ يَوْمَ ࡰ۬لْقِيَٰمَةِ يَكْفُرُ بَعْضُكُم بِبَعْضࣲ وَيَلْعَنُ بَعْضُكُم بَعْضاࣰ࣌ وَمَأْوٜيٰكُمُ ࡲ۬لنَّارُ وَمَا لَكُم مِّن نَّٰصِرِينَ࣌', 'وقال إنما ࡰتخذتم من دون ࡴلله أوثنا مودة بينكم فے ࡴلحيوة ࡴلدنيا࣌ ثم يوم ࡰلقيمة يكفر بعضكم ببعض ويلعن بعضكم بعضا࣌ ومأويكم ࡲلنار وما لكم من نصرين࣌', NULL, 399, 'local:warsh-text.json'),
  ('warsh-29-25', 'warsh', 29, 25, '۞ فَـَٔامَنَ لَهُۥ لُوطࣱ࣌ وَقَالَ إِنِّے مُهَاجِرٌ ࡴلَىٰ رَبِّيَ࣌ إِنَّهُۥ هُوَ ࡰ۬لْعَزِيزُ ࡲ۬لْحَكِيمُ࣌', 'فامن له لوط࣌ وقال إنے مهاجر ࡴلى ربي࣌ إنه هو ࡰلعزيز ࡲلحكيم࣌', NULL, 399, 'local:warsh-text.json'),
  ('warsh-29-26', 'warsh', 29, 26, 'وَوَهَبْنَا لَهُۥٓ إِسْحَٰقَ وَيَعْقُوبَ࣌ وَجَعَلْنَا فِے ذُرِّيَّتِهِ ࡴ۬لنُّبُوٓءَةَ وَالْكِتَٰبَ࣌ وَءَاتَيْنَٰهُ أَجْرَهُۥ فِے ࡴ۬لدُّنْيٜا࣌ وَإِنَّهُۥ فِے ࡴ۬لَاخِرَةِ لَمِنَ ࡰ۬لصَّٰلِحِينَ࣌', 'ووهبنا له إسحق ويعقوب࣌ وجعلنا فے ذريته ࡴلنبوءة والكتب࣌ وءاتينه أجره فے ࡴلدنيا࣌ وإنه فے ࡴلاخرة لمن ࡰلصلحين࣌', NULL, 399, 'local:warsh-text.json'),
  ('warsh-29-27', 'warsh', 29, 27, 'وَلُوطاً ࡴذْ قَالَ لِقَوْمِهِۦٓ إِنَّكُمْ لَتَاتُونَ ࡰ۬لْفَٰحِشَةَ مَا سَبَقَكُم بِهَا مِنَ ࡰحَدࣲ مِّنَ ࡰ۬لْعَٰلَمِينَ', 'ولوطا ࡴذ قال لقومه إنكم لتاتون ࡰلفحشة ما سبقكم بها من ࡰحد من ࡰلعلمين', NULL, 399, 'local:warsh-text.json'),
  ('warsh-29-28', 'warsh', 29, 28, 'أَئِنَّكُمْ لَتَاتُونَ ࡰ۬لرِّجَالَ وَتَقْطَعُونَ ࡰ۬لسَّبِيلَ', 'أئنكم لتاتون ࡰلرجال وتقطعون ࡰلسبيل', NULL, 399, 'local:warsh-text.json'),
  ('warsh-29-29', 'warsh', 29, 29, 'وَتَاتُونَ فِے نَادِيكُمُ ࡲ۬لْمُنكَرَ࣌ فَمَا كَانَ جَوَابَ قَوْمِهِۦٓ إِلَّآ أَن قَالُواْ ࡲٜيتِنَا بِعَذَابِ ࡴ۬للَّهِ إِن كُنتَ مِنَ ࡰ۬لصَّٰدِقِينَ࣌', 'وتاتون فے ناديكم ࡲلمنكر࣌ فما كان جواب قومه إلا أن قالوا ࡲيتنا بعذاب ࡴلله إن كنت من ࡰلصدقين࣌', NULL, 399, 'local:warsh-text.json'),
  ('warsh-29-30', 'warsh', 29, 30, 'قَالَ رَبِّ ࡴ࢈نصُرْنِے عَلَى ࡰ۬لْقَوْمِ ࡴ۬لْمُفْسِدِينَ࣌', 'قال رب ࡴ࢈نصرنے على ࡰلقوم ࡴلمفسدين࣌', NULL, 399, 'local:warsh-text.json'),
  ('warsh-29-31', 'warsh', 29, 31, 'وَلَمَّا جَآءَتْ رُسُلُنَآ إِبْرَٰهِيمَ بِالْبُشْرٜىٰ قَالُوٓاْ إِنَّا مُهْلِكُوٓاْ أَهْلِ هَٰذِهِ ࡴ۬لْقَرْيَةِ إِنَّ أَهْلَهَا كَانُواْ ظَٰلِمِينَ࣌', 'ولما جاءت رسلنا إبرهيم بالبشرى قالوا إنا مهلكوا أهل هذه ࡴلقرية إن أهلها كانوا ظلمين࣌', NULL, 400, 'local:warsh-text.json'),
  ('warsh-29-32', 'warsh', 29, 32, 'قَالَ إِنَّ فِيهَا لُوطاࣰ࣌ قَالُواْ نَحْنُ أَعْلَمُ بِمَن فِيهَا࣌ لَنُنَجِّيَنَّهُۥ وَأَهْلَهُۥٓ إِلَّا ࡰٜمْرَأَتَهُۥ كَانَتْ مِنَ ࡰ۬لْغَٰبِرِينَ࣌', 'قال إن فيها لوطا࣌ قالوا نحن أعلم بمن فيها࣌ لننجينه وأهله إلا ࡰمرأته كانت من ࡰلغبرين࣌', NULL, 400, 'local:warsh-text.json'),
  ('warsh-29-33', 'warsh', 29, 33, 'وَلَمَّآ أَن جَآءَتْ رُسُلُنَا لُوطاࣰ س۬ےٓءَ بِهِمْ وَضَاقَ بِهِمْ ذَرْعاࣰ࣌ وَقَالُواْ لَا تَخَفْ وَلَا تَحْزَنِ ࡴنَّا مُنَجُّوكَ وَأَهْلَكَ إِلَّا ࡰٜمْرَأَتَكَ كَانَتْ مِنَ ࡰ۬لْغَٰبِرِينَ࣌', 'ولما أن جاءت رسلنا لوطا سےء بهم وضاق بهم ذرعا࣌ وقالوا لا تخف ولا تحزن ࡴنا منجوك وأهلك إلا ࡰمرأتك كانت من ࡰلغبرين࣌', NULL, 400, 'local:warsh-text.json'),
  ('warsh-29-34', 'warsh', 29, 34, 'إِنَّا مُنزِلُونَ عَلَىٰٓ أَهْلِ هَٰذِهِ ࡴ۬لْقَرْيَةِ رِجْزاࣰ مِّنَ ࡰ۬لسَّمَآءِ بِمَا كَانُواْ يَفْسُقُونَ࣌', 'إنا منزلون على أهل هذه ࡴلقرية رجزا من ࡰلسماء بما كانوا يفسقون࣌', NULL, 400, 'local:warsh-text.json'),
  ('warsh-29-35', 'warsh', 29, 35, 'وَلَقَد تَّرَكْنَا مِنْهَآ ءَايَةَۢ بَيِّنَةࣰ لِّقَوْمࣲ يَعْقِلُونَ࣌', 'ولقد تركنا منها ءاية بينة لقوم يعقلون࣌', NULL, 400, 'local:warsh-text.json'),
  ('warsh-29-36', 'warsh', 29, 36, '۞ وَإِلَىٰ مَدْيَنَ أَخَاهُمْ شُعَيْباࣰ فَقَالَ يَٰقَوْمِ ࡴ࢈عْبُدُواْ ࡲ۬للَّهَ وَارْجُواْ ࡲ۬لْيَوْمَ ࡰ۬لَاخِرَ وَلَا تَعْثَوْاْ فِے ࡴ۬لَارْضِ مُفْسِدِينَ࣌', 'وإلى مدين أخاهم شعيبا فقال يقوم ࡴ࢈عبدوا ࡲلله وارجوا ࡲليوم ࡰلاخر ولا تعثوا فے ࡴلارض مفسدين࣌', NULL, 400, 'local:warsh-text.json'),
  ('warsh-29-37', 'warsh', 29, 37, 'فَكَذَّبُوهُ فَأَخَذَتْهُمُ ࡲ۬لرَّجْفَةُ فَأَصْبَحُواْ فِے دٜارِهِمْ جَٰثِمِينَ࣌', 'فكذبوه فأخذتهم ࡲلرجفة فأصبحوا فے دارهم جثمين࣌', NULL, 400, 'local:warsh-text.json'),
  ('warsh-29-38', 'warsh', 29, 38, 'وَعَاداࣰ وَثَمُوداࣰ وَقَد تَّبَيَّنَ لَكُم مِّن مَّسَٰكِنِهِمْ وَزَيَّنَ لَهُمُ ࡲ۬لشَّيْطَٰنُ أَعْمَٰلَهُمْ فَصَدَّهُمْ عَنِ ࡴ۬لسَّبِيلِ وَكَانُواْ مُسْتَبْصِرِينَ࣌', 'وعادا وثمودا وقد تبين لكم من مسكنهم وزين لهم ࡲلشيطن أعملهم فصدهم عن ࡴلسبيل وكانوا مستبصرين࣌', NULL, 400, 'local:warsh-text.json'),
  ('warsh-29-39', 'warsh', 29, 39, 'وَقَارُونَ وَفِرْعَوْنَ وَهَامَٰنَ࣌ وَلَقَدْ جَآءَهُم مُّوسٜىٰ بِالْبَيِّنَٰتِ فَاسْتَكْبَرُواْ فِے ࡴ۬لَارْضِ وَمَا كَانُواْ سَٰبِقِينَ࣌', 'وقارون وفرعون وهامن࣌ ولقد جاءهم موسى بالبينت فاستكبروا فے ࡴلارض وما كانوا سبقين࣌', NULL, 401, 'local:warsh-text.json'),
  ('warsh-29-40', 'warsh', 29, 40, 'فَكُلّاً ࡰخَذْنَا بِذَنۢبِهِۦ࣌ فَمِنْهُم مَّنَ ࡰرْسَلْنَا عَلَيْهِ حَاصِباࣰ࣌ وَمِنْهُم مَّنَ ࡰخَذَتْهُ ࡲ۬لصَّيْحَةُ࣌ وَمِنْهُم مَّنْ خَسَفْنَا بِهِ ࡴ۬لَارْضَ࣌ وَمِنْهُم مَّنَ ࡰغْرَقْنَا࣌ وَمَا كَانَ ࡰ۬للَّهُ لِيَظْلِمَهُمْ࣌ وَلَٰكِن كَانُوٓاْ أَنفُسَهُمْ يَظْلِمُونَ࣌', 'فكلا ࡰخذنا بذنبه࣌ فمنهم من ࡰرسلنا عليه حاصبا࣌ ومنهم من ࡰخذته ࡲلصيحة࣌ ومنهم من خسفنا به ࡴلارض࣌ ومنهم من ࡰغرقنا࣌ وما كان ࡰلله ليظلمهم࣌ ولكن كانوا أنفسهم يظلمون࣌', NULL, 401, 'local:warsh-text.json'),
  ('warsh-29-41', 'warsh', 29, 41, 'مَثَلُ ࡲ۬لذِينَ ࡰٜتَّخَذُواْ مِن دُونِ ࡴ۬للَّهِ أَوْلِيَآءَ كَمَثَلِ ࡴ۬لْعَنكَبُوتِ ࡴٜتَّخَذَتْ بَيْتاࣰ࣌ وَإِنَّ أَوْهَنَ ࡰ۬لْبُيُوتِ لَبَيْتُ ࡲ۬لْعَنكَبُوتِ لَوْ كَانُواْ يَعْلَمُونَ࣌', 'مثل ࡲلذين ࡰتخذوا من دون ࡴلله أولياء كمثل ࡴلعنكبوت ࡴتخذت بيتا࣌ وإن أوهن ࡰلبيوت لبيت ࡲلعنكبوت لو كانوا يعلمون࣌', NULL, 401, 'local:warsh-text.json'),
  ('warsh-29-42', 'warsh', 29, 42, 'إِنَّ ࡰ۬للَّهَ يَعْلَمُ مَا تَدْعُونَ مِن دُونِهِۦ مِن شَےْءࣲ࣌ وَهُوَ ࡰ۬لْعَزِيزُ ࡲ۬لْحَكِيمُ࣌', 'إن ࡰلله يعلم ما تدعون من دونه من شےء࣌ وهو ࡰلعزيز ࡲلحكيم࣌', NULL, 401, 'local:warsh-text.json'),
  ('warsh-29-43', 'warsh', 29, 43, 'وَتِلْكَ ࡰ۬لَامْثَٰلُ نَضْرِبُهَا لِلنَّاسِ࣌ وَمَا يَعْقِلُهَآ إِلَّا ࡰ۬لْعَٰلِمُونَ࣌', 'وتلك ࡰلامثل نضربها للناس࣌ وما يعقلها إلا ࡰلعلمون࣌', NULL, 401, 'local:warsh-text.json'),
  ('warsh-29-44', 'warsh', 29, 44, 'خَلَقَ ࡰ۬للَّهُ ࡲ۬لسَّمَٰوَٰتِ وَالَارْضَ بِالْحَقِّ࣌ إِنَّ فِے ذَٰلِكَ لَأٓيَةࣰ لِّلْمُومِنِينَ࣌', 'خلق ࡰلله ࡲلسموت والارض بالحق࣌ إن فے ذلك لأية للمومنين࣌', NULL, 401, 'local:warsh-text.json'),
  ('warsh-29-45', 'warsh', 29, 45, 'ࡸَتْلُ مَآ أُوحِيَ إِلَيْكَ مِنَ ࡰ۬لْكِتَٰبِ وَأَقِمِ ࡴ۬لصَّلَوٰةَ࣌ إِنَّ ࡰ۬لصَّلَوٰةَ تَنْهٜىٰ عَنِ ࡴ۬لْفَحْشَآءِ وَالْمُنكَرِ࣌ وَلَذِكْرُ ࡲ۬للَّهِ أَكْبَرُ࣌ وَاللَّهُ يَعْلَمُ مَا تَصْنَعُونَ࣌', 'ࡸتل ما أوحي إليك من ࡰلكتب وأقم ࡴلصلوة࣌ إن ࡰلصلوة تنهى عن ࡴلفحشاء والمنكر࣌ ولذكر ࡲلله أكبر࣌ والله يعلم ما تصنعون࣌', NULL, 401, 'local:warsh-text.json'),
  ('warsh-29-46', 'warsh', 29, 46, '۞ وَلَا تُجَٰدِلُوٓاْ أَهْلَ ࡰ۬لْكِتَٰبِ إِلَّا بِالتِے هِيَ أَحْسَنُ࣌ إِلَّا ࡰ۬لذِينَ ظَلَمُواْ مِنْهُمْ࣌ وَقُولُوٓاْ ءَامَنَّا بِالذِےٓ أُنزِلَ إِلَيْنَا وَأُنزِلَ إِلَيْكُمْ وَإِلَٰهُنَا وَإِلَٰهُكُمْ وَٰحِدࣱ وَنَحْنُ لَهُۥ مُسْلِمُونَ࣌', 'ولا تجدلوا أهل ࡰلكتب إلا بالتے هي أحسن࣌ إلا ࡰلذين ظلموا منهم࣌ وقولوا ءامنا بالذے أنزل إلينا وأنزل إليكم وإلهنا وإلهكم وحد ونحن له مسلمون࣌', NULL, 402, 'local:warsh-text.json'),
  ('warsh-29-47', 'warsh', 29, 47, 'وَكَذَٰلِكَ أَنزَلْنَآ إِلَيْكَ ࡰ۬لْكِتَٰبَ࣌ فَالذِينَ ءَاتَيْنَٰهُمُ ࡲ۬لْكِتَٰبَ يُومِنُونَ بِهِۦ وَمِنْ هَٰٓؤُلَآءِ مَنْ يُّومِنُ بِهِۦ࣌ وَمَا يَجْحَدُ بِـَٔايَٰتِنَآ إِلَّا ࡰ۬لْكَٰفِرُونَ࣌', 'وكذلك أنزلنا إليك ࡰلكتب࣌ فالذين ءاتينهم ࡲلكتب يومنون به ومن هؤلاء من يومن به࣌ وما يجحد بايتنا إلا ࡰلكفرون࣌', NULL, 402, 'local:warsh-text.json'),
  ('warsh-29-48', 'warsh', 29, 48, 'وَمَا كُنتَ تَتْلُواْ مِن قَبْلِهِۦ مِن كِتَٰبࣲ وَلَا تَخُطُّهُۥ بِيَمِينِكَ࣌ إِذاࣰ لَّارْتَابَ ࡰ۬لْمُبْطِلُونَ࣌', 'وما كنت تتلوا من قبله من كتب ولا تخطه بيمينك࣌ إذا لارتاب ࡰلمبطلون࣌', NULL, 402, 'local:warsh-text.json'),
  ('warsh-29-49', 'warsh', 29, 49, 'بَلْ هُوَ ءَايَٰتُۢ بَيِّنَٰتࣱ فِے صُدُورِ ࡴ۬لذِينَ أُوتُواْ ࡲ۬لْعِلْمَ࣌ وَمَا يَجْحَدُ بِـَٔايَٰتِنَآ إِلَّا ࡰ۬لظَّٰلِمُونَ࣌', 'بل هو ءايت بينت فے صدور ࡴلذين أوتوا ࡲلعلم࣌ وما يجحد بايتنا إلا ࡰلظلمون࣌', NULL, 402, 'local:warsh-text.json'),
  ('warsh-29-50', 'warsh', 29, 50, 'وَقَالُواْ لَوْلَآ أُنزِلَ عَلَيْهِ ءَايَٰتࣱ مِّن رَّبِّهِۦ࣌ قُلِ ࡴنَّمَا ࡰ۬لَايَٰتُ عِندَ ࡰ۬للَّهِ وَإِنَّمَآ أَنَا نَذِيرࣱ مُّبِينٌ࣌', 'وقالوا لولا أنزل عليه ءايت من ربه࣌ قل ࡴنما ࡰلايت عند ࡰلله وإنما أنا نذير مبين࣌', NULL, 402, 'local:warsh-text.json'),
  ('warsh-29-51', 'warsh', 29, 51, 'ࡰوَلَمْ يَكْفِهِمُۥٓ أَنَّآ أَنزَلْنَا عَلَيْكَ ࡰ۬لْكِتَٰبَ يُتْلٜىٰ عَلَيْهِمُۥٓ࣌ إِنَّ فِے ذَٰلِكَ لَرَحْمَةࣰ وَذِكْرٜىٰ لِقَوْمࣲ يُومِنُونَ࣌', 'ࡰولم يكفهم أنا أنزلنا عليك ࡰلكتب يتلى عليهم࣌ إن فے ذلك لرحمة وذكرى لقوم يومنون࣌', NULL, 402, 'local:warsh-text.json'),
  ('warsh-29-52', 'warsh', 29, 52, 'قُلْ كَفٜىٰ بِاللَّهِ بَيْنِے وَبَيْنَكُمْ شَهِيداࣰ࣌ يَعْلَمُ مَا فِے ࡴ۬لسَّمَٰوَٰتِ وَالَارْضِ࣌ وَالذِينَ ءَامَنُواْ بِالْبَٰطِلِ وَكَفَرُواْ بِاللَّهِ أُوْلَٰٓئِكَ هُمُ ࡲ۬لْخَٰسِرُونَ࣌', 'قل كفى بالله بينے وبينكم شهيدا࣌ يعلم ما فے ࡴلسموت والارض࣌ والذين ءامنوا بالبطل وكفروا بالله أولئك هم ࡲلخسرون࣌', NULL, 402, 'local:warsh-text.json'),
  ('warsh-29-53', 'warsh', 29, 53, 'وَيَسْتَعْجِلُونَكَ بِالْعَذَابِ࣌ وَلَوْلَآ أَجَلࣱ مُّسَمّىࣰ لَّجَآءَهُمُ ࡲ۬لْعَذَابُ وَلَيَاتِيَنَّهُم بَغْتَةࣰ وَهُمْ لَا يَشْعُرُونَ࣌', 'ويستعجلونك بالعذاب࣌ ولولا أجل مسمى لجاءهم ࡲلعذاب ولياتينهم بغتة وهم لا يشعرون࣌', NULL, 403, 'local:warsh-text.json'),
  ('warsh-29-54', 'warsh', 29, 54, 'يَسْتَعْجِلُونَكَ بِالْعَذَابِ࣌ وَإِنَّ جَهَنَّمَ لَمُحِيطَةُۢ بِالْكٜـٰفِرِينَ࣌', 'يستعجلونك بالعذاب࣌ وإن جهنم لمحيطة بالكفرين࣌', NULL, 403, 'local:warsh-text.json'),
  ('warsh-29-55', 'warsh', 29, 55, 'يَوْمَ يَغْشٜيٰهُمُ ࡲ۬لْعَذَابُ مِن فَوْقِهِمْ وَمِن تَحْتِ أَرْجُلِهِمْ وَيَقُولُ ذُوقُواْ مَا كُنتُمْ تَعْمَلُونَ࣌', 'يوم يغشيهم ࡲلعذاب من فوقهم ومن تحت أرجلهم ويقول ذوقوا ما كنتم تعملون࣌', NULL, 403, 'local:warsh-text.json'),
  ('warsh-29-56', 'warsh', 29, 56, 'يَٰعِبَادِيَ ࡰ۬لذِينَ ءَامَنُوٓاْ إِنَّ أَرْضِے وَٰسِعَةࣱ فَإِيَّٰيَ فَاعْبُدُونِ࣌', 'يعبادي ࡰلذين ءامنوا إن أرضے وسعة فإيي فاعبدون࣌', NULL, 403, 'local:warsh-text.json'),
  ('warsh-29-57', 'warsh', 29, 57, 'كُلُّ نَفْسࣲ ذَآئِقَةُ ࡲ۬لْمَوْتِ࣌ ثُمَّ إِلَيْنَا تُرْجَعُونَ࣌', 'كل نفس ذائقة ࡲلموت࣌ ثم إلينا ترجعون࣌', NULL, 403, 'local:warsh-text.json'),
  ('warsh-29-58', 'warsh', 29, 58, 'وَالذِينَ ءَامَنُواْ وَعَمِلُواْ ࡲ۬لصَّٰلِحَٰتِ لَنُبَوِّئَنَّهُم مِّنَ ࡰ۬لْجَنَّةِ غُرَفاࣰ تَجْرِے مِن تَحْتِهَا ࡰ۬لَانْهَٰرُ خَٰلِدِينَ فِيهَا࣌ نِعْمَ أَجْرُ ࡲ۬لْعَٰمِلِينَ࣌', 'والذين ءامنوا وعملوا ࡲلصلحت لنبوئنهم من ࡰلجنة غرفا تجرے من تحتها ࡰلانهر خلدين فيها࣌ نعم أجر ࡲلعملين࣌', NULL, 403, 'local:warsh-text.json'),
  ('warsh-29-59', 'warsh', 29, 59, 'ࡰ۬لذِينَ صَبَرُواْ وَعَلَىٰ رَبِّهِمْ يَتَوَكَّلُونَ࣌', 'ࡰلذين صبروا وعلى ربهم يتوكلون࣌', NULL, 403, 'local:warsh-text.json'),
  ('warsh-29-60', 'warsh', 29, 60, '۞ وَكَأَيِّن مِّن دَآبَّةࣲ لَّا تَحْمِلُ رِزْقَهَا ࡰ۬للَّهُ يَرْزُقُهَا وَإِيَّاكُمْ࣌ وَهُوَ ࡰ۬لسَّمِيعُ ࡲ۬لْعَلِيمُ࣌', 'وكأين من دابة لا تحمل رزقها ࡰلله يرزقها وإياكم࣌ وهو ࡰلسميع ࡲلعليم࣌', NULL, 403, 'local:warsh-text.json'),
  ('warsh-29-61', 'warsh', 29, 61, 'وَلَئِن سَأَلْتَهُم مَّنْ خَلَقَ ࡰ۬لسَّمَٰوَٰتِ وَالَارْضَ وَسَخَّرَ ࡰ۬لشَّمْسَ وَالْقَمَرَ لَيَقُولُنَّ ࡰ۬للَّهُ࣌ فَأَنّٜىٰ يُوفَكُونَ࣌', 'ولئن سألتهم من خلق ࡰلسموت والارض وسخر ࡰلشمس والقمر ليقولن ࡰلله࣌ فأنى يوفكون࣌', NULL, 403, 'local:warsh-text.json'),
  ('warsh-29-62', 'warsh', 29, 62, 'ࡰ۬للَّهُ يَبْسُطُ ࡲ۬لرِّزْقَ لِمَنْ يَّشَآءُ مِنْ عِبَادِهِۦ وَيَقْدِرُ لَهُۥٓ࣌ إِنَّ ࡰ۬للَّهَ بِكُلِّ شَےْءٍ عَلِيمࣱ࣌', 'ࡰلله يبسط ࡲلرزق لمن يشاء من عباده ويقدر له࣌ إن ࡰلله بكل شےء عليم࣌', NULL, 403, 'local:warsh-text.json'),
  ('warsh-29-63', 'warsh', 29, 63, 'وَلَئِن سَأَلْتَهُم مَّن نَّزَّلَ مِنَ ࡰ۬لسَّمَآءِ مَآءࣰ فَأَحْيٜا بِهِ ࡴ۬لَارْضَ مِنۢ بَعْدِ مَوْتِهَا لَيَقُولُنَّ ࡰ۬للَّهُ࣌ قُلِ ࡴ۬لْحَمْدُ لِلهِ࣌ بَلَ ࡰكْثَرُهُمْ لَا يَعْقِلُونَ࣌', 'ولئن سألتهم من نزل من ࡰلسماء ماء فأحيا به ࡴلارض من بعد موتها ليقولن ࡰلله࣌ قل ࡴلحمد لله࣌ بل ࡰكثرهم لا يعقلون࣌', NULL, 403, 'local:warsh-text.json'),
  ('warsh-29-64', 'warsh', 29, 64, 'وَمَا هَٰذِهِ ࡴ۬لْحَيَوٰةُ ࡲ۬لدُّنْيٜآ إِلَّا لَهْوࣱ وَلَعِبࣱ࣌ وَإِنَّ ࡰ۬لدَّارَ ࡰ۬لَاخِرَةَ لَهِيَ ࡰ۬لْحَيَوَانُ لَوْ كَانُواْ يَعْلَمُونَ࣌', 'وما هذه ࡴلحيوة ࡲلدنيا إلا لهو ولعب࣌ وإن ࡰلدار ࡰلاخرة لهي ࡰلحيوان لو كانوا يعلمون࣌', NULL, 404, 'local:warsh-text.json'),
  ('warsh-29-65', 'warsh', 29, 65, 'فَإِذَا رَكِبُواْ فِے ࡴ۬لْفُلْكِ دَعَوُاْ ࡲ۬للَّهَ مُخْلِصِينَ لَهُ ࡲ۬لدِّينَ࣌ فَلَمَّا نَجّٜيٰهُمُۥٓ إِلَى ࡰ۬لْبَرِّ إِذَا هُمْ يُشْرِكُونَ', 'فإذا ركبوا فے ࡴلفلك دعوا ࡲلله مخلصين له ࡲلدين࣌ فلما نجيهم إلى ࡰلبر إذا هم يشركون', NULL, 404, 'local:warsh-text.json'),
  ('warsh-29-66', 'warsh', 29, 66, 'لِيَكْفُرُواْ بِمَآ ءَاتَيْنَٰهُمْ࣌ وَلِيَتَمَتَّعُواْ فَسَوْفَ يَعْلَمُونَ࣌', 'ليكفروا بما ءاتينهم࣌ وليتمتعوا فسوف يعلمون࣌', NULL, 404, 'local:warsh-text.json'),
  ('warsh-29-67', 'warsh', 29, 67, 'أَوَلَمْ يَرَوَاْ ࡰنَّا جَعَلْنَا حَرَماً اٰمِناࣰ وَيُتَخَطَّفُ ࡲ۬لنَّاسُ مِنْ حَوْلِهِمُۥٓ࣌ أَفَبِالْبَٰطِلِ يُومِنُونَ وَبِنِعْمَةِ ࡴ۬للَّهِ يَكْفُرُونَ࣌', 'أولم يروا ࡰنا جعلنا حرما امنا ويتخطف ࡲلناس من حولهم࣌ أفبالبطل يومنون وبنعمة ࡴلله يكفرون࣌', NULL, 404, 'local:warsh-text.json'),
  ('warsh-29-68', 'warsh', 29, 68, 'وَمَنَ ࡰظْلَمُ مِمَّنِ ࡴٜفْتَرٜىٰ عَلَى ࡰ۬للَّهِ كَذِباً ࡰوْ كَذَّبَ بِالْحَقِّ لَمَّا جَآءَهُۥٓ࣌ أَلَيْسَ فِے جَهَنَّمَ مَثْوىࣰ لِّلْكٜـٰفِرِينَ࣌', 'ومن ࡰظلم ممن ࡴفترى على ࡰلله كذبا ࡰو كذب بالحق لما جاءه࣌ أليس فے جهنم مثوى للكفرين࣌', NULL, 404, 'local:warsh-text.json'),
  ('warsh-29-69', 'warsh', 29, 69, 'وَالذِينَ جَٰهَدُواْ فِينَا لَنَهْدِيَنَّهُمْ سُبُلَنَا࣌ وَإِنَّ ࡰ۬للَّهَ لَمَعَ ࡰ۬لْمُحْسِنِينَ࣌', 'والذين جهدوا فينا لنهدينهم سبلنا࣌ وإن ࡰلله لمع ࡰلمحسنين࣌', NULL, 404, 'local:warsh-text.json'),
  ('warsh-30-1', 'warsh', 30, 1, 'أَلَٓمِّٓ࣌ غُلِبَتِ ࡴ۬لرُّومُ فِےٓ أَدْنَى ࡰ۬لَارْضِ وَهُم مِّنۢ بَعْدِ غَلَبِهِمْ سَيَغْلِبُونَ', 'ألم࣌ غلبت ࡴلروم فے أدنى ࡰلارض وهم من بعد غلبهم سيغلبون', NULL, 404, 'local:warsh-text.json'),
  ('warsh-30-2', 'warsh', 30, 2, 'فِے بِضْعِ سِنِينَ࣌', 'فے بضع سنين࣌', NULL, 404, 'local:warsh-text.json'),
  ('warsh-30-3', 'warsh', 30, 3, 'لِلهِ ࡴ۬لَامْرُ مِن قَبْلُ وَمِنۢ بَعْدُ࣌ وَيَوْمَئِذࣲ يَفْرَحُ ࡲ۬لْمُومِنُونَ', 'لله ࡴلامر من قبل ومن بعد࣌ ويومئذ يفرح ࡲلمومنون', NULL, 404, 'local:warsh-text.json'),
  ('warsh-30-4', 'warsh', 30, 4, 'بِنَصْرِ ࡴ۬للَّهِ࣌ يَنصُرُ مَنْ يَّشَآءُ࣌ وَهُوَ ࡰ۬لْعَزِيزُ ࡲ۬لرَّحِيمُ࣌', 'بنصر ࡴلله࣌ ينصر من يشاء࣌ وهو ࡰلعزيز ࡲلرحيم࣌', NULL, 404, 'local:warsh-text.json'),
  ('warsh-30-5', 'warsh', 30, 5, 'وَعْدَ ࡰ۬للَّهِ لَا يُخْلِفُ ࡲ۬للَّهُ وَعْدَهُۥ࣌ وَلَٰكِنَّ أَكْثَرَ ࡰ۬لنَّاسِ لَا يَعْلَمُونَ࣌', 'وعد ࡰلله لا يخلف ࡲلله وعده࣌ ولكن أكثر ࡰلناس لا يعلمون࣌', NULL, 405, 'local:warsh-text.json'),
  ('warsh-30-6', 'warsh', 30, 6, 'يَعْلَمُونَ ظَٰهِراࣰ مِّنَ ࡰ۬لْحَيَوٰةِ ࡴ۬لدُّنْيٜا وَهُمْ عَنِ ࡴ۬لَاخِرَةِ هُمْ غَٰفِلُونَ࣌', 'يعلمون ظهرا من ࡰلحيوة ࡴلدنيا وهم عن ࡴلاخرة هم غفلون࣌', NULL, 405, 'local:warsh-text.json'),
  ('warsh-30-7', 'warsh', 30, 7, 'أَوَلَمْ يَتَفَكَّرُواْ فِےٓ أَنفُسِهِم࣌ مَّا خَلَقَ ࡰ۬للَّهُ ࡲ۬لسَّمَٰوَٰتِ وَالَارْضَ وَمَا بَيْنَهُمَآ إِلَّا بِالْحَقِّ وَأَجَلࣲ مُّسَمّىࣰ࣌ وَإِنَّ كَثِيراࣰ مِّنَ ࡰ۬لنَّاسِ بِلِقَآءِ رَبِّهِمْ لَكَٰفِرُونَ࣌', 'أولم يتفكروا فے أنفسهم࣌ ما خلق ࡰلله ࡲلسموت والارض وما بينهما إلا بالحق وأجل مسمى࣌ وإن كثيرا من ࡰلناس بلقاء ربهم لكفرون࣌', NULL, 405, 'local:warsh-text.json'),
  ('warsh-30-8', 'warsh', 30, 8, '۞ أَوَلَمْ يَسِيرُواْ فِے ࡴ۬لَارْضِ فَيَنظُرُواْ كَيْفَ كَانَ عَٰقِبَةُ ࡲ۬لذِينَ مِن قَبْلِهِمْ كَانُوٓاْ أَشَدَّ مِنْهُمْ قُوَّةࣰ وَأَثَارُواْ ࡲ۬لَارْضَ࣌ وَعَمَرُوهَآ أَكْثَرَ مِمَّا عَمَرُوهَا وَجَآءَتْهُمْ رُسُلُهُم بِالْبَيِّنَٰتِ࣌ فَمَا كَانَ ࡰ۬للَّهُ لِيَظْلِمَهُمْ࣌ وَلَٰكِن كَانُوٓاْ أَنفُسَهُمْ يَظْلِمُونَ࣌', 'أولم يسيروا فے ࡴلارض فينظروا كيف كان عقبة ࡲلذين من قبلهم كانوا أشد منهم قوة وأثاروا ࡲلارض࣌ وعمروها أكثر مما عمروها وجاءتهم رسلهم بالبينت࣌ فما كان ࡰلله ليظلمهم࣌ ولكن كانوا أنفسهم يظلمون࣌', NULL, 405, 'local:warsh-text.json'),
  ('warsh-30-9', 'warsh', 30, 9, 'ثُمَّ كَانَ عَٰقِبَةُ ࡲ۬لذِينَ أَسَٰٓـُٔواْ ࡲ۬لسُّوٓأٜىٰٓ أَن كَذَّبُواْ بِـَٔايَٰتِ ࡴ۬للَّهِ وَكَانُواْ بِهَا يَسْتَهْزِءُونَ࣌', 'ثم كان عقبة ࡲلذين أسوا ࡲلسوأى أن كذبوا بايت ࡴلله وكانوا بها يستهزءون࣌', NULL, 405, 'local:warsh-text.json'),
  ('warsh-30-10', 'warsh', 30, 10, 'ࡰ۬للَّهُ يَبْدَؤُاْ ࡲ۬لْخَلْقَ ثُمَّ يُعِيدُهُۥ ثُمَّ إِلَيْهِ تُرْجَعُونَ࣌', 'ࡰلله يبدؤا ࡲلخلق ثم يعيده ثم إليه ترجعون࣌', NULL, 405, 'local:warsh-text.json'),
  ('warsh-30-11', 'warsh', 30, 11, 'وَيَوْمَ تَقُومُ ࡲ۬لسَّاعَةُ يُبْلِسُ ࡲ۬لْمُجْرِمُونَ', 'ويوم تقوم ࡲلساعة يبلس ࡲلمجرمون', NULL, 405, 'local:warsh-text.json'),
  ('warsh-30-12', 'warsh', 30, 12, 'وَلَمْ يَكُن لَّهُم مِّن شُرَكَآئِهِمْ شُفَعَٰٓؤُاْ وَكَانُواْ بِشُرَكَآئِهِمْ كٜـٰفِرِينَ࣌', 'ولم يكن لهم من شركائهم شفعؤا وكانوا بشركائهم كفرين࣌', NULL, 405, 'local:warsh-text.json'),
  ('warsh-30-13', 'warsh', 30, 13, 'وَيَوْمَ تَقُومُ ࡲ۬لسَّاعَةُ يَوْمَئِذࣲ يَتَفَرَّقُونَ࣌', 'ويوم تقوم ࡲلساعة يومئذ يتفرقون࣌', NULL, 405, 'local:warsh-text.json'),
  ('warsh-30-14', 'warsh', 30, 14, 'فَأَمَّا ࡰ۬لذِينَ ءَامَنُواْ وَعَمِلُواْ ࡲ۬لصَّٰلِحَٰتِ فَهُمْ فِے رَوْضَةࣲ يُحْبَرُونَ࣌', 'فأما ࡰلذين ءامنوا وعملوا ࡲلصلحت فهم فے روضة يحبرون࣌', NULL, 405, 'local:warsh-text.json'),
  ('warsh-30-15', 'warsh', 30, 15, 'وَأَمَّا ࡰ۬لذِينَ كَفَرُواْ وَكَذَّبُواْ بِـَٔايَٰتِنَا وَلِقَآءِ ࡴ۬لَاخِرَةِ فَأُوْلَٰٓئِكَ فِے ࡴ۬لْعَذَابِ مُحْضَرُونَ࣌', 'وأما ࡰلذين كفروا وكذبوا بايتنا ولقاء ࡴلاخرة فأولئك فے ࡴلعذاب محضرون࣌', NULL, 406, 'local:warsh-text.json'),
  ('warsh-30-16', 'warsh', 30, 16, 'فَسُبْحَٰنَ ࡰ۬للَّهِ حِينَ تُمْسُونَ وَحِينَ تُصْبِحُونَ', 'فسبحن ࡰلله حين تمسون وحين تصبحون', NULL, 406, 'local:warsh-text.json'),
  ('warsh-30-17', 'warsh', 30, 17, 'وَلَهُ ࡲ۬لْحَمْدُ فِے ࡴ۬لسَّمَٰوَٰتِ وَالَارْضِ وَعَشِيّاࣰ وَحِينَ تُظْهِرُونَ࣌', 'وله ࡲلحمد فے ࡴلسموت والارض وعشيا وحين تظهرون࣌', NULL, 406, 'local:warsh-text.json'),
  ('warsh-30-18', 'warsh', 30, 18, 'يُخْرِجُ ࡲ۬لْحَيَّ مِنَ ࡰ۬لْمَيِّتِ وَيُخْرِجُ ࡲ۬لْمَيِّتَ مِنَ ࡰ۬لْحَيِّ وَيُحْيِ ࡴ۬لَارْضَ بَعْدَ مَوْتِهَا࣌ وَكَذَٰلِكَ تُخْرَجُونَ࣌', 'يخرج ࡲلحي من ࡰلميت ويخرج ࡲلميت من ࡰلحي ويحي ࡴلارض بعد موتها࣌ وكذلك تخرجون࣌', NULL, 406, 'local:warsh-text.json'),
  ('warsh-30-19', 'warsh', 30, 19, 'وَمِنَ اٰيَٰتِهِۦٓ أَنْ خَلَقَكُم مِّن تُرَابࣲ ثُمَّ إِذَآ أَنتُم بَشَرࣱ تَنتَشِرُونَ࣌', 'ومن ايته أن خلقكم من تراب ثم إذا أنتم بشر تنتشرون࣌', NULL, 406, 'local:warsh-text.json'),
  ('warsh-30-20', 'warsh', 30, 20, 'وَمِنَ اٰيَٰتِهِۦٓ أَنْ خَلَقَ لَكُم مِّنَ ࡰنفُسِكُمُۥٓ أَزْوَٰجاࣰ لِّتَسْكُنُوٓاْ إِلَيْهَا وَجَعَلَ بَيْنَكُم مَّوَدَّةࣰ وَرَحْمَةً࣌ ࡴنَّ فِے ذَٰلِكَ لَأٓيَٰتࣲ لِّقَوْمࣲ يَتَفَكَّرُونَ࣌', 'ومن ايته أن خلق لكم من ࡰنفسكم أزوجا لتسكنوا إليها وجعل بينكم مودة ورحمة࣌ ࡴن فے ذلك لأيت لقوم يتفكرون࣌', NULL, 406, 'local:warsh-text.json'),
  ('warsh-30-21', 'warsh', 30, 21, '۞ وَمِنَ اٰيَٰتِهِۦ خَلْقُ ࡲ۬لسَّمَٰوَٰتِ وَالَارْضِ وَاخْتِلَٰفُ أَلْسِنَتِكُمْ وَأَلْوَٰنِكُمُۥٓ࣌ إِنَّ فِے ذَٰلِكَ لَأٓيَٰتࣲ لِّلْعَٰلَمِينَ࣌', 'ومن ايته خلق ࡲلسموت والارض واختلف ألسنتكم وألونكم࣌ إن فے ذلك لأيت للعلمين࣌', NULL, 406, 'local:warsh-text.json'),
  ('warsh-30-22', 'warsh', 30, 22, 'وَمِنَ اٰيَٰتِهِۦ مَنَامُكُم بِاليْلِ وَالنَّهٜارِ وَابْتِغَآؤُكُم مِّن فَضْلِهِۦٓ࣌ إِنَّ فِے ذَٰلِكَ لَأٓيَٰتࣲ لِّقَوْمࣲ يَسْمَعُونَ࣌', 'ومن ايته منامكم باليل والنهار وابتغاؤكم من فضله࣌ إن فے ذلك لأيت لقوم يسمعون࣌', NULL, 406, 'local:warsh-text.json'),
  ('warsh-30-23', 'warsh', 30, 23, 'وَمِنَ اٰيَٰتِهِۦ يُرِيكُمُ ࡲ۬لْبَرْقَ خَوْفاࣰ وَطَمَعاࣰ وَيُنَزِّلُ مِنَ ࡰ۬لسَّمَآءِ مَآءࣰ فَيُحْيِۦ بِهِ ࡴ۬لَارْضَ بَعْدَ مَوْتِهَآ࣌ إِنَّ فِے ذَٰلِكَ لَأٓيَٰتࣲ لِّقَوْمࣲ يَعْقِلُونَ࣌', 'ومن ايته يريكم ࡲلبرق خوفا وطمعا وينزل من ࡰلسماء ماء فيحي به ࡴلارض بعد موتها࣌ إن فے ذلك لأيت لقوم يعقلون࣌', NULL, 406, 'local:warsh-text.json'),
  ('warsh-30-24', 'warsh', 30, 24, 'وَمِنَ اٰيَٰتِهِۦٓ أَن تَقُومَ ࡰ۬لسَّمَآءُ وَالَارْضُ بِأَمْرِهِۦ࣌ ثُمَّ إِذَا دَعَاكُمْ دَعْوَةࣰ مِّنَ ࡰ۬لَارْضِ إِذَآ أَنتُمْ تَخْرُجُونَ࣌', 'ومن ايته أن تقوم ࡰلسماء والارض بأمره࣌ ثم إذا دعاكم دعوة من ࡰلارض إذا أنتم تخرجون࣌', NULL, 407, 'local:warsh-text.json'),
  ('warsh-30-25', 'warsh', 30, 25, 'وَلَهُۥ مَن فِے ࡴ۬لسَّمَٰوَٰتِ وَالَارْضِ࣌ كُلࣱّ لَّهُۥ قَٰنِتُونَ࣌', 'وله من فے ࡴلسموت والارض࣌ كل له قنتون࣌', NULL, 407, 'local:warsh-text.json'),
  ('warsh-30-26', 'warsh', 30, 26, 'وَهُوَ ࡰ۬لذِے يَبْدَؤُاْ ࡲ۬لْخَلْقَ ثُمَّ يُعِيدُهُۥ وَهُوَ أَهْوَنُ عَلَيْهِ࣌ وَلَهُ ࡲ۬لْمَثَلُ ࡲ۬لَاعْلٜىٰ فِے ࡴ۬لسَّمَٰوَٰتِ وَالَارْضِ࣌ وَهُوَ ࡰ۬لْعَزِيزُ ࡲ۬لْحَكِيمُ࣌', 'وهو ࡰلذے يبدؤا ࡲلخلق ثم يعيده وهو أهون عليه࣌ وله ࡲلمثل ࡲلاعلى فے ࡴلسموت والارض࣌ وهو ࡰلعزيز ࡲلحكيم࣌', NULL, 407, 'local:warsh-text.json'),
  ('warsh-30-27', 'warsh', 30, 27, 'ضَرَبَ لَكُم مَّثَلاࣰ مِّنَ ࡰنفُسِكُمْ هَل لَّكُم مِّن مَّا مَلَكَتَ ࡰيْمَٰنُكُم مِّن شُرَكَآءَ فِے مَا رَزَقْنَٰكُمْ فَأَنتُمْ فِيهِ سَوَآءࣱ تَخَافُونَهُمْ كَخِيفَتِكُمُۥٓ أَنفُسَكُمْ࣌ كَذَٰلِكَ نُفَصِّلُ ࡲ۬لَايَٰتِ لِقَوْمࣲ يَعْقِلُونَ࣌', 'ضرب لكم مثلا من ࡰنفسكم هل لكم من ما ملكت ࡰيمنكم من شركاء فے ما رزقنكم فأنتم فيه سواء تخافونهم كخيفتكم أنفسكم࣌ كذلك نفصل ࡲلايت لقوم يعقلون࣌', NULL, 407, 'local:warsh-text.json'),
  ('warsh-30-28', 'warsh', 30, 28, 'بَلِ ࡴٜتَّبَعَ ࡰ۬لذِينَ ظَلَمُوٓاْ أَهْوَآءَهُم بِغَيْرِ عِلْمࣲ࣌ فَمَنْ يَّهْدِے مَنَ ࡰضَلَّ ࡰ۬للَّهُ࣌ وَمَا لَهُم مِّن نَّٰصِرِينَ࣌', 'بل ࡴتبع ࡰلذين ظلموا أهواءهم بغير علم࣌ فمن يهدے من ࡰضل ࡰلله࣌ وما لهم من نصرين࣌', NULL, 407, 'local:warsh-text.json'),
  ('warsh-30-29', 'warsh', 30, 29, '۞ فَأَقِمْ وَجْهَكَ لِلدِّينِ حَنِيفاࣰ فِطْرَتَ ࡰ۬للَّهِ ࡴ۬لتِے فَطَرَ ࡰ۬لنَّاسَ عَلَيْهَا لَا تَبْدِيلَ لِخَلْقِ ࡴ۬للَّهِ ذَٰلِكَ ࡰ۬لدِّينُ ࡲ۬لْقَيِّمُ وَلَٰكِنَّ أَكْثَرَ ࡰ۬لنَّاسِ لَا يَعْلَمُونَ', 'فأقم وجهك للدين حنيفا فطرت ࡰلله ࡴلتے فطر ࡰلناس عليها لا تبديل لخلق ࡴلله ذلك ࡰلدين ࡲلقيم ولكن أكثر ࡰلناس لا يعلمون', NULL, 407, 'local:warsh-text.json'),
  ('warsh-30-30', 'warsh', 30, 30, 'مُنِيبِينَ إِلَيْهِ وَاتَّقُوهُ وَأَقِيمُواْ ࡲ۬لصَّلَوٰةَ وَلَا تَكُونُواْ مِنَ ࡰ۬لْمُشْرِكِينَ', 'منيبين إليه واتقوه وأقيموا ࡲلصلوة ولا تكونوا من ࡰلمشركين', NULL, 407, 'local:warsh-text.json'),
  ('warsh-30-31', 'warsh', 30, 31, 'مِنَ ࡰ۬لذِينَ فَرَّقُواْ دِينَهُمْ وَكَانُواْ شِيَعاࣰ࣌ كُلُّ حِزْبِۢ بِمَا لَدَيْهِمْ فَرِحُونَ࣌', 'من ࡰلذين فرقوا دينهم وكانوا شيعا࣌ كل حزب بما لديهم فرحون࣌', NULL, 407, 'local:warsh-text.json'),
  ('warsh-30-32', 'warsh', 30, 32, 'وَإِذَا مَسَّ ࡰ۬لنَّاسَ ضُرࣱّ دَعَوْاْ رَبَّهُم مُّنِيبِينَ إِلَيْهِ࣌ ثُمَّ إِذَآ أَذَاقَهُم مِّنْهُ رَحْمَةً ࡴذَا فَرِيقࣱ مِّنْهُم بِرَبِّهِمْ يُشْرِكُونَ࣌', 'وإذا مس ࡰلناس ضر دعوا ربهم منيبين إليه࣌ ثم إذا أذاقهم منه رحمة ࡴذا فريق منهم بربهم يشركون࣌', NULL, 408, 'local:warsh-text.json'),
  ('warsh-30-33', 'warsh', 30, 33, 'لِيَكْفُرُواْ بِمَآ ءَاتَيْنَٰهُمْ࣌ فَتَمَتَّعُواْ فَسَوْفَ تَعْلَمُونَ࣌', 'ليكفروا بما ءاتينهم࣌ فتمتعوا فسوف تعلمون࣌', NULL, 408, 'local:warsh-text.json'),
  ('warsh-30-34', 'warsh', 30, 34, 'أَمَ ࡰنزَلْنَا عَلَيْهِمْ سُلْطَٰناࣰ فَهُوَ يَتَكَلَّمُ بِمَا كَانُواْ بِهِۦ يُشْرِكُونَ࣌', 'أم ࡰنزلنا عليهم سلطنا فهو يتكلم بما كانوا به يشركون࣌', NULL, 408, 'local:warsh-text.json'),
  ('warsh-30-35', 'warsh', 30, 35, 'وَإِذَآ أَذَقْنَا ࡰ۬لنَّاسَ رَحْمَةࣰ فَرِحُواْ بِهَا࣌ وَإِن تُصِبْهُمْ سَيِّئَةُۢ بِمَا قَدَّمَتَ ࡰيْدِيهِمُۥٓ إِذَا هُمْ يَقْنَطُونَ࣌', 'وإذا أذقنا ࡰلناس رحمة فرحوا بها࣌ وإن تصبهم سيئة بما قدمت ࡰيديهم إذا هم يقنطون࣌', NULL, 408, 'local:warsh-text.json'),
  ('warsh-30-36', 'warsh', 30, 36, 'أَوَلَمْ يَرَوَاْ ࡰنَّ ࡰ۬للَّهَ يَبْسُطُ ࡲ۬لرِّزْقَ لِمَنْ يَّشَآءُ وَيَقْدِرُ࣌ إِنَّ فِے ذَٰلِكَ لَأٓيَٰتࣲ لِّقَوْمࣲ يُومِنُونَ࣌', 'أولم يروا ࡰن ࡰلله يبسط ࡲلرزق لمن يشاء ويقدر࣌ إن فے ذلك لأيت لقوم يومنون࣌', NULL, 408, 'local:warsh-text.json'),
  ('warsh-30-37', 'warsh', 30, 37, 'فَـَٔاتِ ذَا ࡰ۬لْقُرْبٜىٰ حَقَّهُۥ وَالْمِسْكِينَ وَابْنَ ࡰ۬لسَّبِيلِ࣌ ذَٰلِكَ خَيْرࣱ لِّلذِينَ يُرِيدُونَ وَجْهَ ࡰ۬للَّهِ࣌ وَأُوْلَٰٓئِكَ هُمُ ࡲ۬لْمُفْلِحُونَ࣌', 'فات ذا ࡰلقربى حقه والمسكين وابن ࡰلسبيل࣌ ذلك خير للذين يريدون وجه ࡰلله࣌ وأولئك هم ࡲلمفلحون࣌', NULL, 408, 'local:warsh-text.json'),
  ('warsh-30-38', 'warsh', 30, 38, 'وَمَآ ءَاتَيْتُم مِّن رِّباࣰ لِّتُرْبُواْ فِےٓ أَمْوَٰلِ ࡴ۬لنَّاسِ فَلَا يَرْبُواْ عِندَ ࡰ۬للَّهِ࣌ وَمَآ ءَاتَيْتُم مِّن زَكَوٰةࣲ تُرِيدُونَ وَجْهَ ࡰ۬للَّهِ فَأُوْلَٰٓئِكَ هُمُ ࡲ۬لْمُضْعِفُونَ࣌', 'وما ءاتيتم من ربا لتربوا فے أمول ࡴلناس فلا يربوا عند ࡰلله࣌ وما ءاتيتم من زكوة تريدون وجه ࡰلله فأولئك هم ࡲلمضعفون࣌', NULL, 408, 'local:warsh-text.json'),
  ('warsh-30-39', 'warsh', 30, 39, 'ࡰ۬للَّهُ ࡲ۬لذِے خَلَقَكُمْ ثُمَّ رَزَقَكُمْ ثُمَّ يُمِيتُكُمْ ثُمَّ يُحْيِيكُمْ࣌ هَلْ مِن شُرَكَآئِكُم مَّنْ يَّفْعَلُ مِن ذَٰلِكُم مِّن شَےْءࣲ࣌ سُبْحَٰنَهُۥ وَتَعَٰلٜىٰ عَمَّا يُشْرِكُونَ࣌', 'ࡰلله ࡲلذے خلقكم ثم رزقكم ثم يميتكم ثم يحييكم࣌ هل من شركائكم من يفعل من ذلكم من شےء࣌ سبحنه وتعلى عما يشركون࣌', NULL, 408, 'local:warsh-text.json'),
  ('warsh-30-40', 'warsh', 30, 40, '۞ ظَهَرَ ࡰ۬لْفَسَادُ فِے ࡴ۬لْبَرِّ وَالْبَحْرِ بِمَا كَسَبَتَ ࡰيْدِے ࡴ۬لنَّاسِ لِيُذِيقَهُم بَعْضَ ࡰ۬لذِے عَمِلُواْ لَعَلَّهُمْ يَرْجِعُونَ࣌', 'ظهر ࡰلفساد فے ࡴلبر والبحر بما كسبت ࡰيدے ࡴلناس ليذيقهم بعض ࡰلذے عملوا لعلهم يرجعون࣌', NULL, 408, 'local:warsh-text.json'),
  ('warsh-30-41', 'warsh', 30, 41, 'قُلْ سِيرُواْ فِے ࡴ۬لَارْضِ فَانظُرُواْ كَيْفَ كَانَ عَٰقِبَةُ ࡲ۬لذِينَ مِن قَبْلُ࣌ كَانَ أَكْثَرُهُم مُّشْرِكِينَ࣌', 'قل سيروا فے ࡴلارض فانظروا كيف كان عقبة ࡲلذين من قبل࣌ كان أكثرهم مشركين࣌', NULL, 409, 'local:warsh-text.json'),
  ('warsh-30-42', 'warsh', 30, 42, 'فَأَقِمْ وَجْهَكَ لِلدِّينِ ࡴ۬لْقَيِّمِ مِن قَبْلِ أَنْ يَّاتِيَ يَوْمࣱ لَّا مَرَدَّ لَهُۥ مِنَ ࡰ۬للَّهِ࣌ يَوْمَئِذࣲ يَصَّدَّعُونَ࣌', 'فأقم وجهك للدين ࡴلقيم من قبل أن ياتي يوم لا مرد له من ࡰلله࣌ يومئذ يصدعون࣌', NULL, 409, 'local:warsh-text.json'),
  ('warsh-30-43', 'warsh', 30, 43, 'مَن كَفَرَ فَعَلَيْهِ كُفْرُهُۥ࣌ وَمَنْ عَمِلَ صَٰلِحاࣰ فَلِأَنفُسِهِمْ يَمْهَدُونَ', 'من كفر فعليه كفره࣌ ومن عمل صلحا فلأنفسهم يمهدون', NULL, 409, 'local:warsh-text.json'),
  ('warsh-30-44', 'warsh', 30, 44, 'لِيَجْزِيَ ࡰ۬لذِينَ ءَامَنُواْ وَعَمِلُواْ ࡲ۬لصَّٰلِحَٰتِ مِن فَضْلِهِۦٓ࣌ إِنَّهُۥ لَا يُحِبُّ ࡲ۬لْكٜـٰفِرِينَ࣌', 'ليجزي ࡰلذين ءامنوا وعملوا ࡲلصلحت من فضله࣌ إنه لا يحب ࡲلكفرين࣌', NULL, 409, 'local:warsh-text.json'),
  ('warsh-30-45', 'warsh', 30, 45, 'وَمِنَ اٰيَٰتِهِۦٓ أَنْ يُّرْسِلَ ࡰ۬لرِّيَاحَ مُبَشِّرَٰتࣲ وَلِيُذِيقَكُم مِّن رَّحْمَتِهِۦ وَلِتَجْرِيَ ࡰ۬لْفُلْكُ بِأَمْرِهِۦ وَلِتَبْتَغُواْ مِن فَضْلِهِۦ وَلَعَلَّكُمْ تَشْكُرُونَ࣌', 'ومن ايته أن يرسل ࡰلرياح مبشرت وليذيقكم من رحمته ولتجري ࡰلفلك بأمره ولتبتغوا من فضله ولعلكم تشكرون࣌', NULL, 409, 'local:warsh-text.json'),
  ('warsh-30-46', 'warsh', 30, 46, 'وَلَقَدَ ࡰرْسَلْنَا مِن قَبْلِكَ رُسُلاً ࡴلَىٰ قَوْمِهِمْ فَجَآءُوهُم بِالْبَيِّنَٰتِ فَانتَقَمْنَا مِنَ ࡰ۬لذِينَ أَجْرَمُواْ࣌ وَكَانَ حَقّاً عَلَيْنَا نَصْرُ ࡲ۬لْمُومِنِينَ࣌', 'ولقد ࡰرسلنا من قبلك رسلا ࡴلى قومهم فجاءوهم بالبينت فانتقمنا من ࡰلذين أجرموا࣌ وكان حقا علينا نصر ࡲلمومنين࣌', NULL, 409, 'local:warsh-text.json'),
  ('warsh-30-47', 'warsh', 30, 47, 'ࡰ۬للَّهُ ࡲ۬لذِے يُرْسِلُ ࡲ۬لرِّيَٰحَ فَتُثِيرُ سَحَاباࣰ فَيَبْسُطُهُۥ فِے ࡴ۬لسَّمَآءِ كَيْفَ يَشَآءُ وَيَجْعَلُهُۥ كِسَفاࣰ فَتَرَى ࡰ۬لْوَدْقَ يَخْرُجُ مِنْ خِلَٰلِهِۦ࣌ فَإِذَآ أَصَابَ بِهِۦ مَنْ يَّشَآءُ مِنْ عِبَادِهِۦٓ إِذَا هُمْ يَسْتَبْشِرُونَ࣌', 'ࡰلله ࡲلذے يرسل ࡲلريح فتثير سحابا فيبسطه فے ࡴلسماء كيف يشاء ويجعله كسفا فترى ࡰلودق يخرج من خلله࣌ فإذا أصاب به من يشاء من عباده إذا هم يستبشرون࣌', NULL, 409, 'local:warsh-text.json'),
  ('warsh-30-48', 'warsh', 30, 48, 'وَإِن كَانُواْ مِن قَبْلِ أَنْ يُّنَزَّلَ عَلَيْهِم مِّن قَبْلِهِۦ لَمُبْلِسِينَ࣌', 'وإن كانوا من قبل أن ينزل عليهم من قبله لمبلسين࣌', NULL, 409, 'local:warsh-text.json'),
  ('warsh-30-49', 'warsh', 30, 49, 'فَانظُرِ ࡴلَىٰٓ أَثَرِ رَحْمَتِ ࡴ۬للَّهِ كَيْفَ يُحْيِ ࡴ۬لَارْضَ بَعْدَ مَوْتِهَآ࣌ إِنَّ ذَٰلِكَ لَمُحْيِ ࡴ۬لْمَوْتٜىٰ࣌ وَهُوَ عَلَىٰ كُلِّ شَےْءࣲ قَدِيرࣱ࣌', 'فانظر ࡴلى أثر رحمت ࡴلله كيف يحي ࡴلارض بعد موتها࣌ إن ذلك لمحي ࡴلموتى࣌ وهو على كل شےء قدير࣌', NULL, 409, 'local:warsh-text.json'),
  ('warsh-30-50', 'warsh', 30, 50, 'وَلَئِنَ ࡰرْسَلْنَا رِيحاࣰ فَرَأَوْهُ مُصْفَرّاࣰ لَّظَلُّواْ مِنۢ بَعْدِهِۦ يَكْفُرُونَ࣌', 'ولئن ࡰرسلنا ريحا فرأوه مصفرا لظلوا من بعده يكفرون࣌', NULL, 410, 'local:warsh-text.json'),
  ('warsh-30-51', 'warsh', 30, 51, 'فَإِنَّكَ لَا تُسْمِعُ ࡲ۬لْمَوْتٜىٰ وَلَا تُسْمِعُ ࡲ۬لصُّمَّ ࡰ۬لدُّعَآءَ ࡹذَا وَلَّوْاْ مُدْبِرِينَ࣌', 'فإنك لا تسمع ࡲلموتى ولا تسمع ࡲلصم ࡰلدعاء ࡹذا ولوا مدبرين࣌', NULL, 410, 'local:warsh-text.json'),
  ('warsh-30-52', 'warsh', 30, 52, 'وَمَآ أَنتَ بِهَٰدِ ࡴ۬لْعُمْيِ عَن ضَلَٰلَتِهِمُۥٓ࣌ إِن تُسْمِعُ إِلَّا مَنْ يُّومِنُ بِـَٔايَٰتِنَا فَهُم مُّسْلِمُونَ࣌', 'وما أنت بهد ࡴلعمي عن ضللتهم࣌ إن تسمع إلا من يومن بايتنا فهم مسلمون࣌', NULL, 410, 'local:warsh-text.json'),
  ('warsh-30-53', 'warsh', 30, 53, '۞ ࡰ۬للَّهُ ࡲ۬لذِے خَلَقَكُم مِّن ضُعْفࣲ ثُمَّ جَعَلَ مِنۢ بَعْدِ ضُعْفࣲ قُوَّةࣰ ثُمَّ جَعَلَ مِنۢ بَعْدِ قُوَّةࣲ ضُعْفاࣰ وَشَيْبَةࣰ࣌ يَخْلُقُ مَا يَشَآءُ࣌ وَهُوَ ࡰ۬لْعَلِيمُ ࡲ۬لْقَدِيرُ࣌', 'ࡰلله ࡲلذے خلقكم من ضعف ثم جعل من بعد ضعف قوة ثم جعل من بعد قوة ضعفا وشيبة࣌ يخلق ما يشاء࣌ وهو ࡰلعليم ࡲلقدير࣌', NULL, 410, 'local:warsh-text.json'),
  ('warsh-30-54', 'warsh', 30, 54, 'وَيَوْمَ تَقُومُ ࡲ۬لسَّاعَةُ يُقْسِمُ ࡲ۬لْمُجْرِمُونَ مَا لَبِثُواْ غَيْرَ سَاعَةࣲ࣌ كَذَٰلِكَ كَانُواْ يُوفَكُونَ࣌', 'ويوم تقوم ࡲلساعة يقسم ࡲلمجرمون ما لبثوا غير ساعة࣌ كذلك كانوا يوفكون࣌', NULL, 410, 'local:warsh-text.json'),
  ('warsh-30-55', 'warsh', 30, 55, 'وَقَالَ ࡰ۬لذِينَ أُوتُواْ ࡲ۬لْعِلْمَ وَالِايمَٰنَ لَقَدْ لَبِثْتُمْ فِے كِتَٰبِ ࡴ۬للَّهِ إِلَىٰ يَوْمِ ࡴ۬لْبَعْثِ࣌ فَهَٰذَا يَوْمُ ࡲ۬لْبَعْثِ وَلَٰكِنَّكُمْ كُنتُمْ لَا تَعْلَمُونَ࣌', 'وقال ࡰلذين أوتوا ࡲلعلم والايمن لقد لبثتم فے كتب ࡴلله إلى يوم ࡴلبعث࣌ فهذا يوم ࡲلبعث ولكنكم كنتم لا تعلمون࣌', NULL, 410, 'local:warsh-text.json'),
  ('warsh-30-56', 'warsh', 30, 56, 'فَيَوْمَئِذࣲ لَّا تَنفَعُ ࡲ۬لذِينَ ظَلَمُواْ مَعْذِرَتُهُمْ وَلَا هُمْ يُسْتَعْتَبُونَ࣌', 'فيومئذ لا تنفع ࡲلذين ظلموا معذرتهم ولا هم يستعتبون࣌', NULL, 410, 'local:warsh-text.json'),
  ('warsh-30-57', 'warsh', 30, 57, 'وَلَقَد ضَّرَبْنَا لِلنَّاسِ فِے هَٰذَا ࡰ۬لْقُرْءَانِ مِن كُلِّ مَثَلࣲ࣌ وَلَئِن جِئْتَهُم بِـَٔايَةࣲ لَّيَقُولَنَّ ࡰ۬لذِينَ كَفَرُوٓاْ إِنَ ࡰنتُمُۥٓ إِلَّا مُبْطِلُونَ࣌', 'ولقد ضربنا للناس فے هذا ࡰلقرءان من كل مثل࣌ ولئن جئتهم باية ليقولن ࡰلذين كفروا إن ࡰنتم إلا مبطلون࣌', NULL, 410, 'local:warsh-text.json'),
  ('warsh-30-58', 'warsh', 30, 58, 'كَذَٰلِكَ يَطْبَعُ ࡲ۬للَّهُ عَلَىٰ قُلُوبِ ࡴ۬لذِينَ لَا يَعْلَمُونَ࣌', 'كذلك يطبع ࡲلله على قلوب ࡴلذين لا يعلمون࣌', NULL, 410, 'local:warsh-text.json'),
  ('warsh-30-59', 'warsh', 30, 59, 'فَاصْبِرِ࣌ ࡴنَّ وَعْدَ ࡰ۬للَّهِ حَقࣱّ࣌ وَلَا يَسْتَخِفَّنَّكَ ࡰ۬لذِينَ لَا يُوقِنُونَ࣌', 'فاصبر࣌ ࡴن وعد ࡰلله حق࣌ ولا يستخفنك ࡰلذين لا يوقنون࣌', NULL, 410, 'local:warsh-text.json'),
  ('warsh-31-1', 'warsh', 31, 1, 'أَلَٓمِّٓ࣌ تِلْكَ ءَايَٰتُ ࡲ۬لْكِتَٰبِ ࡴ۬لْحَكِيمِ', 'ألم࣌ تلك ءايت ࡲلكتب ࡴلحكيم', NULL, 411, 'local:warsh-text.json'),
  ('warsh-31-2', 'warsh', 31, 2, 'هُدىࣰ وَرَحْمَةࣰ لِّلْمُحْسِنِينَ', 'هدى ورحمة للمحسنين', NULL, 411, 'local:warsh-text.json'),
  ('warsh-31-3', 'warsh', 31, 3, 'ࡰ۬لذِينَ يُقِيمُونَ ࡰ۬لصَّلَوٰةَ وَيُوتُونَ ࡰ۬لزَّكَوٰةَ وَهُم بِالَاخِرَةِ هُمْ يُوقِنُونَ࣌', 'ࡰلذين يقيمون ࡰلصلوة ويوتون ࡰلزكوة وهم بالاخرة هم يوقنون࣌', NULL, 411, 'local:warsh-text.json'),
  ('warsh-31-4', 'warsh', 31, 4, 'أُوْلَٰٓئِكَ عَلَىٰ هُدىࣰ مِّن رَّبِّهِمْ࣌ وَأُوْلَٰٓئِكَ هُمُ ࡲ۬لْمُفْلِحُونَ࣌', 'أولئك على هدى من ربهم࣌ وأولئك هم ࡲلمفلحون࣌', NULL, 411, 'local:warsh-text.json'),
  ('warsh-31-5', 'warsh', 31, 5, 'وَمِنَ ࡰ۬لنَّاسِ مَنْ يَّشْتَرِے لَهْوَ ࡰ۬لْحَدِيثِ لِيُضِلَّ عَن سَبِيلِ ࡴ۬للَّهِ بِغَيْرِ عِلْمࣲ وَيَتَّخِذُهَا هُزُؤاً࣌ ࡳوْلَٰٓئِكَ لَهُمْ عَذَابࣱ مُّهِينࣱ࣌', 'ومن ࡰلناس من يشترے لهو ࡰلحديث ليضل عن سبيل ࡴلله بغير علم ويتخذها هزؤا࣌ ࡳولئك لهم عذاب مهين࣌', NULL, 411, 'local:warsh-text.json'),
  ('warsh-31-6', 'warsh', 31, 6, 'وَإِذَا تُتْلٜىٰ عَلَيْهِ ءَايَٰتُنَا وَلّٜىٰ مُسْتَكْبِراࣰ كَأَن لَّمْ يَسْمَعْهَا كَأَنَّ فِےٓ أُذْنَيْهِ وَقْراࣰ࣌ فَبَشِّرْهُ بِعَذَابٍ ࡰلِيمٍ࣌', 'وإذا تتلى عليه ءايتنا ولى مستكبرا كأن لم يسمعها كأن فے أذنيه وقرا࣌ فبشره بعذاب ࡰليم࣌', NULL, 411, 'local:warsh-text.json'),
  ('warsh-31-7', 'warsh', 31, 7, 'ࡴنَّ ࡰ۬لذِينَ ءَامَنُواْ وَعَمِلُواْ ࡲ۬لصَّٰلِحَٰتِ لَهُمْ جَنَّٰتُ ࡲ۬لنَّعِيمِ', 'ࡴن ࡰلذين ءامنوا وعملوا ࡲلصلحت لهم جنت ࡲلنعيم', NULL, 411, 'local:warsh-text.json'),
  ('warsh-31-8', 'warsh', 31, 8, 'خَٰلِدِينَ فِيهَا࣌ وَعْدَ ࡰ۬للَّهِ حَقّاࣰ࣌ وَهُوَ ࡰ۬لْعَزِيزُ ࡲ۬لْحَكِيمُ࣌', 'خلدين فيها࣌ وعد ࡰلله حقا࣌ وهو ࡰلعزيز ࡲلحكيم࣌', NULL, 411, 'local:warsh-text.json'),
  ('warsh-31-9', 'warsh', 31, 9, 'خَلَقَ ࡰ۬لسَّمَٰوَٰتِ بِغَيْرِ عَمَدࣲ࣌ تَرَوْنَهَا࣌ وَأَلْقٜىٰ فِے ࡴ۬لَارْضِ رَوَٰسِيَ أَن تَمِيدَ بِكُمْ وَبَثَّ فِيهَا مِن كُلِّ دَآبَّةࣲ࣌ وَأَنزَلْنَا مِنَ ࡰ۬لسَّمَآءِ مَآءࣰ فَأَنۢبَتْنَا فِيهَا مِن كُلِّ زَوْجࣲ كَرِيمٍ࣌', 'خلق ࡰلسموت بغير عمد࣌ ترونها࣌ وألقى فے ࡴلارض روسي أن تميد بكم وبث فيها من كل دابة࣌ وأنزلنا من ࡰلسماء ماء فأنبتنا فيها من كل زوج كريم࣌', NULL, 411, 'local:warsh-text.json'),
  ('warsh-31-10', 'warsh', 31, 10, '۞ هَٰذَا خَلْقُ ࡲ۬للَّهِ࣌ فَأَرُونِے مَاذَا خَلَقَ ࡰ۬لذِينَ مِن دُونِهِۦ࣌ بَلِ ࡴ۬لظَّٰلِمُونَ فِے ضَلَٰلࣲ مُّبِينࣲ࣌', 'هذا خلق ࡲلله࣌ فأرونے ماذا خلق ࡰلذين من دونه࣌ بل ࡴلظلمون فے ضلل مبين࣌', NULL, 411, 'local:warsh-text.json'),
  ('warsh-31-11', 'warsh', 31, 11, 'وَلَقَدَ اٰتَيْنَا لُقْمَٰنَ ࡰ۬لْحِكْمَةَ أَنُ ࡲ࢈شْكُرْ لِلهِ࣌ وَمَنْ يَّشْكُرْ فَإِنَّمَا يَشْكُرُ لِنَفْسِهِۦ࣌ وَمَن كَفَرَ فَإِنَّ ࡰ۬للَّهَ غَنِيٌّ حَمِيدࣱ࣌', 'ولقد اتينا لقمن ࡰلحكمة أن ࡲ࢈شكر لله࣌ ومن يشكر فإنما يشكر لنفسه࣌ ومن كفر فإن ࡰلله غني حميد࣌', NULL, 412, 'local:warsh-text.json'),
  ('warsh-31-12', 'warsh', 31, 12, 'وَإِذْ قَالَ لُقْمَٰنُ لِابْنِهِۦ وَهُوَ يَعِظُهُۥ يَٰبُنَيِّ لَا تُشْرِكْ بِاللَّهِ࣌ إِنَّ ࡰ۬لشِّرْكَ لَظُلْمٌ عَظِيمࣱ࣌', 'وإذ قال لقمن لابنه وهو يعظه يبني لا تشرك بالله࣌ إن ࡰلشرك لظلم عظيم࣌', NULL, 412, 'local:warsh-text.json'),
  ('warsh-31-13', 'warsh', 31, 13, 'وَوَصَّيْنَا ࡰ۬لِانسَٰنَ بِوَٰلِدَيْهِ࣌ حَمَلَتْهُ أُمُّهُۥ وَهْناً عَلَىٰ وَهْنࣲ࣌ وَفِصَٰلُهُۥ فِے عَامَيْنِ࣌ أَنُ ࡲ࢈شْكُرْ لِے وَلِوَٰلِدَيْكَ࣌ إِلَيَّ ࡰ۬لْمَصِيرُ࣌', 'ووصينا ࡰلانسن بولديه࣌ حملته أمه وهنا على وهن࣌ وفصله فے عامين࣌ أن ࡲ࢈شكر لے ولولديك࣌ إلي ࡰلمصير࣌', NULL, 412, 'local:warsh-text.json'),
  ('warsh-31-14', 'warsh', 31, 14, 'وَإِن جَٰهَدَٰكَ عَلَىٰٓ أَن تُشْرِكَ بِے مَا لَيْسَ لَكَ بِهِۦ عِلْمࣱ فَلَا تُطِعْهُمَا࣌ وَصَاحِبْهُمَا فِے ࡴ۬لدُّنْيٜا مَعْرُوفاࣰ࣌ وَاتَّبِعْ سَبِيلَ مَنَ ࡰنَابَ إِلَيَّ࣌ ثُمَّ إِلَيَّ مَرْجِعُكُمْ فَأُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ࣌', 'وإن جهدك على أن تشرك بے ما ليس لك به علم فلا تطعهما࣌ وصاحبهما فے ࡴلدنيا معروفا࣌ واتبع سبيل من ࡰناب إلي࣌ ثم إلي مرجعكم فأنبئكم بما كنتم تعملون࣌', NULL, 412, 'local:warsh-text.json'),
  ('warsh-31-15', 'warsh', 31, 15, 'يَٰبُنَيِّ إِنَّهَآ إِن تَكُ مِثْقَالُ حَبَّةࣲ مِّنْ خَرْدَلࣲ فَتَكُن فِے صَخْرَةٍ ࡰوْ فِے ࡴ۬لسَّمَٰوَٰتِ أَوْ فِے ࡴ۬لَارْضِ يَاتِ بِهَا ࡰ۬للَّهُ࣌ إِنَّ ࡰ۬للَّهَ لَطِيفٌ خَبِيرࣱ࣌', 'يبني إنها إن تك مثقال حبة من خردل فتكن فے صخرة ࡰو فے ࡴلسموت أو فے ࡴلارض يات بها ࡰلله࣌ إن ࡰلله لطيف خبير࣌', NULL, 412, 'local:warsh-text.json'),
  ('warsh-31-16', 'warsh', 31, 16, 'يَٰبُنَيِّ أَقِمِ ࡴ۬لصَّلَوٰةَ࣌ وَامُرْ بِالْمَعْرُوفِ࣌ وَانْهَ عَنِ ࡴ۬لْمُنكَرِ࣌ وَاصْبِرْ عَلَىٰ مَآ أَصَابَكَ࣌ إِنَّ ذَٰلِكَ مِنْ عَزْمِ ࡴ۬لُامُورِ࣌', 'يبني أقم ࡴلصلوة࣌ وامر بالمعروف࣌ وانه عن ࡴلمنكر࣌ واصبر على ما أصابك࣌ إن ذلك من عزم ࡴلامور࣌', NULL, 412, 'local:warsh-text.json'),
  ('warsh-31-17', 'warsh', 31, 17, 'وَلَا تُصَٰعِرْ خَدَّكَ لِلنَّاسِ࣌ وَلَا تَمْشِ فِے ࡴ۬لَارْضِ مَرَحاً࣌ ࡴنَّ ࡰ۬للَّهَ لَا يُحِبُّ كُلَّ مُخْتَالࣲ فَخُورࣲ࣌', 'ولا تصعر خدك للناس࣌ ولا تمش فے ࡴلارض مرحا࣌ ࡴن ࡰلله لا يحب كل مختال فخور࣌', NULL, 412, 'local:warsh-text.json'),
  ('warsh-31-18', 'warsh', 31, 18, 'وَاقْصِدْ فِے مَشْيِكَ࣌ وَاغْضُضْ مِن صَوْتِكَ࣌ إِنَّ أَنكَرَ ࡰ۬لَاصْوَٰتِ لَصَوْتُ ࡲ۬لْحَمِيرِ࣌', 'واقصد فے مشيك࣌ واغضض من صوتك࣌ إن أنكر ࡰلاصوت لصوت ࡲلحمير࣌', NULL, 412, 'local:warsh-text.json'),
  ('warsh-31-19', 'warsh', 31, 19, 'أَلَمْ تَرَوَاْ ࡰنَّ ࡰ۬للَّهَ سَخَّرَ لَكُم مَّا فِے ࡴ۬لسَّمَٰوَٰتِ وَمَا فِے ࡴ۬لَارْضِ وَأَسْبَغَ عَلَيْكُمْ نِعَمَهُۥ ظَٰهِرَةࣰ وَبَاطِنَةࣰ࣌ وَمِنَ ࡰ۬لنَّاسِ مَنْ يُّجَٰدِلُ فِے ࡴ۬للَّهِ بِغَيْرِ عِلْمࣲ وَلَا هُدىࣰ وَلَا كِتَٰبࣲ مُّنِيرࣲ࣌', 'ألم تروا ࡰن ࡰلله سخر لكم ما فے ࡴلسموت وما فے ࡴلارض وأسبغ عليكم نعمه ظهرة وباطنة࣌ ومن ࡰلناس من يجدل فے ࡴلله بغير علم ولا هدى ولا كتب منير࣌', NULL, 413, 'local:warsh-text.json'),
  ('warsh-31-20', 'warsh', 31, 20, 'وَإِذَا قِيلَ لَهُمُ ࡲٜتَّبِعُواْ مَآ أَنزَلَ ࡰ۬للَّهُ قَالُواْ بَلْ نَتَّبِعُ مَا وَجَدْنَا عَلَيْهِ ءَابَآءَنَآ࣌ أَوَلَوْ كَانَ ࡰ۬لشَّيْطَٰنُ يَدْعُوهُمُۥٓ إِلَىٰ عَذَابِ ࡴ۬لسَّعِيرِ࣌', 'وإذا قيل لهم ࡲتبعوا ما أنزل ࡰلله قالوا بل نتبع ما وجدنا عليه ءاباءنا࣌ أولو كان ࡰلشيطن يدعوهم إلى عذاب ࡴلسعير࣌', NULL, 413, 'local:warsh-text.json'),
  ('warsh-31-21', 'warsh', 31, 21, '۞ وَمَنْ يُّسْلِمْ وَجْهَهُۥٓ إِلَى ࡰ۬للَّهِ وَهُوَ مُحْسِنࣱ فَقَدِ ࡴٜسْتَمْسَكَ بِالْعُرْوَةِ ࡴ۬لْوُثْقٜىٰ࣌ وَإِلَى ࡰ۬للَّهِ عَٰقِبَةُ ࡲ۬لُامُورِ࣌', 'ومن يسلم وجهه إلى ࡰلله وهو محسن فقد ࡴستمسك بالعروة ࡴلوثقى࣌ وإلى ࡰلله عقبة ࡲلامور࣌', NULL, 413, 'local:warsh-text.json'),
  ('warsh-31-22', 'warsh', 31, 22, 'وَمَن كَفَرَ فَلَا يُحْزِنكَ كُفْرُهُۥٓ࣌ إِلَيْنَا مَرْجِعُهُمْ فَنُنَبِّئُهُم بِمَا عَمِلُوٓاْ࣌ إِنَّ ࡰ۬للَّهَ عَلِيمُۢ بِذَاتِ ࡴ۬لصُّدُورِ࣌', 'ومن كفر فلا يحزنك كفره࣌ إلينا مرجعهم فننبئهم بما عملوا࣌ إن ࡰلله عليم بذات ࡴلصدور࣌', NULL, 413, 'local:warsh-text.json'),
  ('warsh-31-23', 'warsh', 31, 23, 'نُمَتِّعُهُمْ قَلِيلاࣰ ثُمَّ نَضْطَرُّهُمُۥٓ إِلَىٰ عَذَابٍ غَلِيظࣲ࣌', 'نمتعهم قليلا ثم نضطرهم إلى عذاب غليظ࣌', NULL, 413, 'local:warsh-text.json'),
  ('warsh-31-24', 'warsh', 31, 24, 'وَلَئِن سَأَلْتَهُم مَّنْ خَلَقَ ࡰ۬لسَّمَٰوَٰتِ وَالَارْضَ لَيَقُولُنَّ ࡰ۬للَّهُ࣌ قُلِ ࡴ۬لْحَمْدُ لِلهِ࣌ بَلَ ࡰكْثَرُهُمْ لَا يَعْلَمُونَ࣌', 'ولئن سألتهم من خلق ࡰلسموت والارض ليقولن ࡰلله࣌ قل ࡴلحمد لله࣌ بل ࡰكثرهم لا يعلمون࣌', NULL, 413, 'local:warsh-text.json'),
  ('warsh-31-25', 'warsh', 31, 25, 'لِلهِ مَا فِے ࡴ۬لسَّمَٰوَٰتِ وَالَارْضِ࣌ إِنَّ ࡰ۬للَّهَ هُوَ ࡰ۬لْغَنِيُّ ࡲ۬لْحَمِيدُ࣌', 'لله ما فے ࡴلسموت والارض࣌ إن ࡰلله هو ࡰلغني ࡲلحميد࣌', NULL, 413, 'local:warsh-text.json'),
  ('warsh-31-26', 'warsh', 31, 26, 'وَلَوَ ࡰنَّمَا فِے ࡴ۬لَارْضِ مِن شَجَرَةٍ ࡰقْلَٰمࣱ وَالْبَحْرُ يَمُدُّهُۥ مِنۢ بَعْدِهِۦ سَبْعَةُ أَبْحُرࣲ مَّا نَفِدَتْ كَلِمَٰتُ ࡲ۬للَّهِ࣌ إِنَّ ࡰ۬للَّهَ عَزِيزٌ حَكِيمࣱ࣌', 'ولو ࡰنما فے ࡴلارض من شجرة ࡰقلم والبحر يمده من بعده سبعة أبحر ما نفدت كلمت ࡲلله࣌ إن ࡰلله عزيز حكيم࣌', NULL, 413, 'local:warsh-text.json'),
  ('warsh-31-27', 'warsh', 31, 27, 'مَّا خَلْقُكُمْ وَلَا بَعْثُكُمُۥٓ إِلَّا كَنَفْسࣲ وَٰحِدَةٍ࣌ ࡴنَّ ࡰ۬للَّهَ سَمِيعُۢ بَصِيرٌ࣌', 'ما خلقكم ولا بعثكم إلا كنفس وحدة࣌ ࡴن ࡰلله سميع بصير࣌', NULL, 413, 'local:warsh-text.json'),
  ('warsh-31-28', 'warsh', 31, 28, 'ࡰلَمْ تَرَ أَنَّ ࡰ۬للَّهَ يُولِجُ ࡲ۬ليْلَ فِے ࡴ۬لنَّهٜارِ وَيُولِجُ ࡲ۬لنَّهَارَ فِے ࡴ۬ليْلِ وَسَخَّرَ ࡰ۬لشَّمْسَ وَالْقَمَرَ كُلࣱّ يَجْرِےٓ إِلَىٰٓ أَجَلࣲ مُّسَمّىࣰ وَأَنَّ ࡰ۬للَّهَ بِمَا تَعْمَلُونَ خَبِيرࣱ࣌', 'ࡰلم تر أن ࡰلله يولج ࡲليل فے ࡴلنهار ويولج ࡲلنهار فے ࡴليل وسخر ࡰلشمس والقمر كل يجرے إلى أجل مسمى وأن ࡰلله بما تعملون خبير࣌', NULL, 414, 'local:warsh-text.json'),
  ('warsh-31-29', 'warsh', 31, 29, 'ذَٰلِكَ بِأَنَّ ࡰ۬للَّهَ هُوَ ࡰ۬لْحَقُّ وَأَنَّ مَا تَدْعُونَ مِن دُونِهِ ࡴ۬لْبَٰطِلُ وَأَنَّ ࡰ۬للَّهَ هُوَ ࡰ۬لْعَلِيُّ ࡲ۬لْكَبِيرُ࣌', 'ذلك بأن ࡰلله هو ࡰلحق وأن ما تدعون من دونه ࡴلبطل وأن ࡰلله هو ࡰلعلي ࡲلكبير࣌', NULL, 414, 'local:warsh-text.json'),
  ('warsh-31-30', 'warsh', 31, 30, 'أَلَمْ تَرَ أَنَّ ࡰ۬لْفُلْكَ تَجْرِے فِے ࡴ۬لْبَحْرِ بِنِعْمَتِ ࡴ۬للَّهِ لِيُرِيَكُم مِّنَ اٰيَٰتِهِۦٓ࣌ إِنَّ فِے ذَٰلِكَ لَأٓيَٰتࣲ لِّكُلِّ صَبّٜارࣲ شَكُورࣲ࣌', 'ألم تر أن ࡰلفلك تجرے فے ࡴلبحر بنعمت ࡴلله ليريكم من ايته࣌ إن فے ذلك لأيت لكل صبار شكور࣌', NULL, 414, 'local:warsh-text.json'),
  ('warsh-31-31', 'warsh', 31, 31, 'وَإِذَا غَشِيَهُم مَّوْجࣱ كَالظُّلَلِ دَعَوُاْ ࡲ۬للَّهَ مُخْلِصِينَ لَهُ ࡲ۬لدِّينَ࣌ فَلَمَّا نَجّٜيٰهُمُۥٓ إِلَى ࡰ۬لْبَرِّ فَمِنْهُم مُّقْتَصِدࣱ࣌ وَمَا يَجْحَدُ بِـَٔايَٰتِنَآ إِلَّا كُلُّ خَتّٜارࣲ كَفُورࣲ࣌', 'وإذا غشيهم موج كالظلل دعوا ࡲلله مخلصين له ࡲلدين࣌ فلما نجيهم إلى ࡰلبر فمنهم مقتصد࣌ وما يجحد بايتنا إلا كل ختار كفور࣌', NULL, 414, 'local:warsh-text.json'),
  ('warsh-31-32', 'warsh', 31, 32, '۞ يَٰٓأَيُّهَا ࡰ۬لنَّاسُ ࡲٜتَّقُواْ رَبَّكُمْ وَاخْشَوْاْ يَوْماࣰ لَّا يَجْزِے وَالِدٌ عَنْ وَّلَدِهِۦ وَلَا مَوْلُودٌ هُوَ جَازٍ عَنْ وَّالِدِهِۦ شَيْـٔاً࣌ ࡴنَّ وَعْدَ ࡰ۬للَّهِ حَقࣱّ࣌ فَلَا تَغُرَّنَّكُمُ ࡲ۬لْحَيَوٰةُ ࡲ۬لدُّنْيٜا࣌ وَلَا يَغُرَّنَّكُم بِاللَّهِ ࡴ۬لْغَرُورُ࣌', 'يأيها ࡰلناس ࡲتقوا ربكم واخشوا يوما لا يجزے والد عن ولده ولا مولود هو جاز عن والده شيا࣌ ࡴن وعد ࡰلله حق࣌ فلا تغرنكم ࡲلحيوة ࡲلدنيا࣌ ولا يغرنكم بالله ࡴلغرور࣌', NULL, 414, 'local:warsh-text.json'),
  ('warsh-31-33', 'warsh', 31, 33, 'إِنَّ ࡰ۬للَّهَ عِندَهُۥ عِلْمُ ࡲ۬لسَّاعَةِ࣌ وَيُنَزِّلُ ࡲ۬لْغَيْثَ࣌ وَيَعْلَمُ مَا فِے ࡴ۬لَارْحَامِ࣌ وَمَا تَدْرِے نَفْسࣱ مَّاذَا تَكْسِبُ غَداࣰ࣌ وَمَا تَدْرِے نَفْسُۢ بِأَيِّ أَرْضࣲ تَمُوتُ࣌ إِنَّ ࡰ۬للَّهَ عَلِيمٌ خَبِيرٌ࣌', 'إن ࡰلله عنده علم ࡲلساعة࣌ وينزل ࡲلغيث࣌ ويعلم ما فے ࡴلارحام࣌ وما تدرے نفس ماذا تكسب غدا࣌ وما تدرے نفس بأي أرض تموت࣌ إن ࡰلله عليم خبير࣌', NULL, 414, 'local:warsh-text.json'),
  ('warsh-32-1', 'warsh', 32, 1, 'ࡰلَٓمِّٓ࣌ تَنزِيلُ ࡲ۬لْكِتَٰبِ لَا رَيْبَ فِيهِ مِن رَّبِّ ࡴ۬لْعَٰلَمِينَ࣌', 'ࡰلم࣌ تنزيل ࡲلكتب لا ريب فيه من رب ࡴلعلمين࣌', NULL, 415, 'local:warsh-text.json'),
  ('warsh-32-2', 'warsh', 32, 2, 'أَمْ يَقُولُونَ ࡰٜفْتَرٜيٰهُ࣌ بَلْ هُوَ ࡰ۬لْحَقُّ مِن رَّبِّكَ لِتُنذِرَ قَوْماࣰ مَّآ أَتٜيٰهُم مِّن نَّذِيرࣲ مِّن قَبْلِكَ لَعَلَّهُمْ يَهْتَدُونَ࣌', 'أم يقولون ࡰفتريه࣌ بل هو ࡰلحق من ربك لتنذر قوما ما أتيهم من نذير من قبلك لعلهم يهتدون࣌', NULL, 415, 'local:warsh-text.json'),
  ('warsh-32-3', 'warsh', 32, 3, 'ࡰ۬للَّهُ ࡲ۬لذِے خَلَقَ ࡰ۬لسَّمَٰوَٰتِ وَالَارْضَ وَمَا بَيْنَهُمَا فِے سِتَّةِ أَيَّامࣲ ثُمَّ ࡰٜسْتَوٜىٰ عَلَى ࡰ۬لْعَرْشِ࣌ مَا لَكُم مِّن دُونِهِۦ مِنْ وَّلِيࣲّ وَلَا شَفِيعٍ࣌ ࡰفَلَا تَتَذَكَّرُونَ࣌', 'ࡰلله ࡲلذے خلق ࡰلسموت والارض وما بينهما فے ستة أيام ثم ࡰستوى على ࡰلعرش࣌ ما لكم من دونه من ولي ولا شفيع࣌ ࡰفلا تتذكرون࣌', NULL, 415, 'local:warsh-text.json'),
  ('warsh-32-4', 'warsh', 32, 4, 'يُدَبِّرُ ࡲ۬لَامْرَ مِنَ ࡰ۬لسَّمَآءِ الَى ࡰ۬لَارْضِ ثُمَّ يَعْرُجُ إِلَيْهِ فِے يَوْمࣲ كَانَ مِقْدَارُهُۥٓ أَلْفَ سَنَةࣲ مِّمَّا تَعُدُّونَ࣌', 'يدبر ࡲلامر من ࡰلسماء الى ࡰلارض ثم يعرج إليه فے يوم كان مقداره ألف سنة مما تعدون࣌', NULL, 415, 'local:warsh-text.json'),
  ('warsh-32-5', 'warsh', 32, 5, 'ذَٰلِكَ عَٰلِمُ ࡲ۬لْغَيْبِ وَالشَّهَٰدَةِ ࡴ۬لْعَزِيزُ ࡲ۬لرَّحِيمُ࣌', 'ذلك علم ࡲلغيب والشهدة ࡴلعزيز ࡲلرحيم࣌', NULL, 415, 'local:warsh-text.json'),
  ('warsh-32-6', 'warsh', 32, 6, 'ࡲ۬لذِےٓ أَحْسَنَ كُلَّ شَےْءٍ خَلَقَهُۥ وَبَدَأَ خَلْقَ ࡰ۬لِانسَٰنِ مِن طِينࣲ࣌', 'ࡲلذے أحسن كل شےء خلقه وبدأ خلق ࡰلانسن من طين࣌', NULL, 415, 'local:warsh-text.json'),
  ('warsh-32-7', 'warsh', 32, 7, 'ثُمَّ جَعَلَ نَسْلَهُۥ مِن سُلَٰلَةࣲ مِّن مَّآءࣲ مَّهِينࣲ࣌', 'ثم جعل نسله من سللة من ماء مهين࣌', NULL, 415, 'local:warsh-text.json'),
  ('warsh-32-8', 'warsh', 32, 8, 'ثُمَّ سَوّٜيٰهُ وَنَفَخَ فِيهِ مِن رُّوحِهِۦ࣌ وَجَعَلَ لَكُمُ ࡲ۬لسَّمْعَ وَالَابْصَٰرَ وَالَافْـِٕدَةَ࣌ قَلِيلاࣰ مَّا تَشْكُرُونَ࣌', 'ثم سويه ونفخ فيه من روحه࣌ وجعل لكم ࡲلسمع والابصر والافدة࣌ قليلا ما تشكرون࣌', NULL, 415, 'local:warsh-text.json'),
  ('warsh-32-9', 'warsh', 32, 9, 'وَقَالُوٓاْ أَࢇذَا ضَلَلْنَا فِے ࡴ۬لَارْضِ إِنَّا لَفِے خَلْقࣲ جَدِيدِۢ࣌', 'وقالوا أࢇذا ضللنا فے ࡴلارض إنا لفے خلق جديد࣌', NULL, 415, 'local:warsh-text.json'),
  ('warsh-32-10', 'warsh', 32, 10, 'بَلْ هُم بِلِقَآءِ رَبِّهِمْ كَٰفِرُونَ࣌', 'بل هم بلقاء ربهم كفرون࣌', NULL, 415, 'local:warsh-text.json'),
  ('warsh-32-11', 'warsh', 32, 11, '۞ قُلْ يَتَوَفّٜيٰكُم مَّلَكُ ࡲ۬لْمَوْتِ ࡴ۬لذِے وُكِّلَ بِكُمْ ثُمَّ إِلَىٰ رَبِّكُمْ تُرْجَعُونَ࣌', 'قل يتوفيكم ملك ࡲلموت ࡴلذے وكل بكم ثم إلى ربكم ترجعون࣌', NULL, 415, 'local:warsh-text.json'),
  ('warsh-32-12', 'warsh', 32, 12, 'وَلَوْ تَرٜىٰٓ إِذِ ࡴ۬لْمُجْرِمُونَ نَاكِسُواْ رُءُوسِهِمْ عِندَ رَبِّهِمْ رَبَّنَآ أَبْصَرْنَا وَسَمِعْنَا فَارْجِعْنَا نَعْمَلْ صَٰلِحاً ࡴنَّا مُوقِنُونَ࣌', 'ولو ترى إذ ࡴلمجرمون ناكسوا رءوسهم عند ربهم ربنا أبصرنا وسمعنا فارجعنا نعمل صلحا ࡴنا موقنون࣌', NULL, 416, 'local:warsh-text.json'),
  ('warsh-32-13', 'warsh', 32, 13, 'وَلَوْ شِئْنَا لَأٓتَيْنَا كُلَّ نَفْسٍ هُدٜيٰهَا࣌ وَلَٰكِنْ حَقَّ ࡰ۬لْقَوْلُ مِنِّے لَأَمْلَأَنَّ جَهَنَّمَ مِنَ ࡰ۬لْجِنَّةِ وَالنَّاسِ أَجْمَعِينَ࣌', 'ولو شئنا لأتينا كل نفس هديها࣌ ولكن حق ࡰلقول منے لأملأن جهنم من ࡰلجنة والناس أجمعين࣌', NULL, 416, 'local:warsh-text.json'),
  ('warsh-32-14', 'warsh', 32, 14, 'فَذُوقُواْ بِمَا نَسِيتُمْ لِقَآءَ يَوْمِكُمْ هَٰذَآ إِنَّا نَسِينَٰكُمْ࣌ وَذُوقُواْ عَذَابَ ࡰ۬لْخُلْدِ بِمَا كُنتُمْ تَعْمَلُونَ࣌', 'فذوقوا بما نسيتم لقاء يومكم هذا إنا نسينكم࣌ وذوقوا عذاب ࡰلخلد بما كنتم تعملون࣌', NULL, 416, 'local:warsh-text.json'),
  ('warsh-32-15', 'warsh', 32, 15, 'إِنَّمَا يُومِنُ بِـَٔايَٰتِنَا ࡰ۬لذِينَ إِذَا ذُكِّرُواْ بِهَا خَرُّواْ سُجَّداࣰ وَسَبَّحُواْ بِحَمْدِ رَبِّهِمْ وَهُمْ لَا يَسْتَكْبِرُونَ࣌۩', 'إنما يومن بايتنا ࡰلذين إذا ذكروا بها خروا سجدا وسبحوا بحمد ربهم وهم لا يستكبرون࣌', NULL, 416, 'local:warsh-text.json'),
  ('warsh-32-16', 'warsh', 32, 16, 'تَتَجَافٜىٰ جُنُوبُهُمْ عَنِ ࡴ۬لْمَضَاجِعِ يَدْعُونَ رَبَّهُمْ خَوْفاࣰ وَطَمَعاࣰ وَمِمَّا رَزَقْنَٰهُمْ يُنفِقُونَ࣌', 'تتجافى جنوبهم عن ࡴلمضاجع يدعون ربهم خوفا وطمعا ومما رزقنهم ينفقون࣌', NULL, 416, 'local:warsh-text.json'),
  ('warsh-32-17', 'warsh', 32, 17, 'فَلَا تَعْلَمُ نَفْسࣱ مَّآ أُخْفِيَ لَهُم مِّن قُرَّةِ أَعْيُنࣲ جَزَآءَۢ بِمَا كَانُواْ يَعْمَلُونَ࣌', 'فلا تعلم نفس ما أخفي لهم من قرة أعين جزاء بما كانوا يعملون࣌', NULL, 416, 'local:warsh-text.json'),
  ('warsh-32-18', 'warsh', 32, 18, 'أَفَمَن كَانَ مُومِناࣰ كَمَن كَانَ فَاسِقاࣰ࣌ لَّا يَسْتَوُۥنَ࣌', 'أفمن كان مومنا كمن كان فاسقا࣌ لا يستون࣌', NULL, 416, 'local:warsh-text.json'),
  ('warsh-32-19', 'warsh', 32, 19, 'أَمَّا ࡰ۬لذِينَ ءَامَنُواْ وَعَمِلُواْ ࡲ۬لصَّٰلِحَٰتِ فَلَهُمْ جَنَّٰتُ ࡲ۬لْمَأْوٜىٰ نُزُلاَۢ بِمَا كَانُواْ يَعْمَلُونَ࣌', 'أما ࡰلذين ءامنوا وعملوا ࡲلصلحت فلهم جنت ࡲلمأوى نزلا بما كانوا يعملون࣌', NULL, 416, 'local:warsh-text.json'),
  ('warsh-32-20', 'warsh', 32, 20, 'وَأَمَّا ࡰ۬لذِينَ فَسَقُواْ فَمَأْوٜيٰهُمُ ࡲ۬لنَّارُ࣌ كُلَّمَآ أَرَادُوٓاْ أَنْ يَّخْرُجُواْ مِنْهَآ أُعِيدُواْ فِيهَا وَقِيلَ لَهُمْ ذُوقُواْ عَذَابَ ࡰ۬لنّٜارِ ࡴ۬لذِے كُنتُم بِهِۦ تُكَذِّبُونَ࣌', 'وأما ࡰلذين فسقوا فمأويهم ࡲلنار࣌ كلما أرادوا أن يخرجوا منها أعيدوا فيها وقيل لهم ذوقوا عذاب ࡰلنار ࡴلذے كنتم به تكذبون࣌', NULL, 416, 'local:warsh-text.json'),
  ('warsh-32-21', 'warsh', 32, 21, '۞ وَلَنُذِيقَنَّهُم مِّنَ ࡰ۬لْعَذَابِ ࡴ۬لَادْنٜىٰ دُونَ ࡰ۬لْعَذَابِ ࡴ۬لَاكْبَرِ لَعَلَّهُمْ يَرْجِعُونَ࣌', 'ولنذيقنهم من ࡰلعذاب ࡴلادنى دون ࡰلعذاب ࡴلاكبر لعلهم يرجعون࣌', NULL, 417, 'local:warsh-text.json'),
  ('warsh-32-22', 'warsh', 32, 22, 'وَمَنَ ࡰظْلَمُ مِمَّن ذُكِّرَ بِـَٔايَٰتِ رَبِّهِۦ ثُمَّ أَعْرَضَ عَنْهَآ࣌ إِنَّا مِنَ ࡰ۬لْمُجْرِمِينَ مُنتَقِمُونَ࣌', 'ومن ࡰظلم ممن ذكر بايت ربه ثم أعرض عنها࣌ إنا من ࡰلمجرمين منتقمون࣌', NULL, 417, 'local:warsh-text.json'),
  ('warsh-32-23', 'warsh', 32, 23, 'وَلَقَدَ اٰتَيْنَا مُوسَى ࡰ۬لْكِتَٰبَ࣌ فَلَا تَكُن فِے مِرْيَةࣲ مِّن لِّقَآئِهِۦ࣌ وَجَعَلْنَٰهُ هُدىࣰ لِّبَنِےٓ إِسْرَآءِيلَ࣌', 'ولقد اتينا موسى ࡰلكتب࣌ فلا تكن فے مرية من لقائه࣌ وجعلنه هدى لبنے إسراءيل࣌', NULL, 417, 'local:warsh-text.json'),
  ('warsh-32-24', 'warsh', 32, 24, 'وَجَعَلْنَا مِنْهُمُۥٓ أَئِمَّةࣰ يَهْدُونَ بِأَمْرِنَا لَمَّا صَبَرُواْ࣌ وَكَانُواْ بِـَٔايَٰتِنَا يُوقِنُونَ࣌', 'وجعلنا منهم أئمة يهدون بأمرنا لما صبروا࣌ وكانوا بايتنا يوقنون࣌', NULL, 417, 'local:warsh-text.json'),
  ('warsh-32-25', 'warsh', 32, 25, 'إِنَّ رَبَّكَ هُوَ يَفْصِلُ بَيْنَهُمْ يَوْمَ ࡰ۬لْقِيَٰمَةِ فِيمَا كَانُواْ فِيهِ يَخْتَلِفُونَ࣌', 'إن ربك هو يفصل بينهم يوم ࡰلقيمة فيما كانوا فيه يختلفون࣌', NULL, 417, 'local:warsh-text.json'),
  ('warsh-32-26', 'warsh', 32, 26, 'أَوَلَمْ يَهْدِ لَهُمْ كَمَ ࡰهْلَكْنَا مِن قَبْلِهِم مِّنَ ࡰ۬لْقُرُونِ يَمْشُونَ فِے مَسَٰكِنِهِمُۥٓ࣌ إِنَّ فِے ذَٰلِكَ لَأٓيَٰتٍ࣌ ࡰفَلَا يَسْمَعُونَ࣌', 'أولم يهد لهم كم ࡰهلكنا من قبلهم من ࡰلقرون يمشون فے مسكنهم࣌ إن فے ذلك لأيت࣌ ࡰفلا يسمعون࣌', NULL, 417, 'local:warsh-text.json'),
  ('warsh-32-27', 'warsh', 32, 27, 'أَوَلَمْ يَرَوَاْ ࡰنَّا نَسُوقُ ࡲ۬لْمَآءَ ࡹلَى ࡰ۬لَارْضِ ࡴ۬لْجُرُزِ فَنُخْرِجُ بِهِۦ زَرْعاࣰ تَاكُلُ مِنْهُ أَنْعَٰمُهُمْ وَأَنفُسُهُمُۥٓ࣌ أَفَلَا يُبْصِرُونَ࣌', 'أولم يروا ࡰنا نسوق ࡲلماء ࡹلى ࡰلارض ࡴلجرز فنخرج به زرعا تاكل منه أنعمهم وأنفسهم࣌ أفلا يبصرون࣌', NULL, 417, 'local:warsh-text.json'),
  ('warsh-32-28', 'warsh', 32, 28, 'وَيَقُولُونَ مَتٜىٰ هَٰذَا ࡰ۬لْفَتْحُ إِن كُنتُمْ صَٰدِقِينَ࣌', 'ويقولون متى هذا ࡰلفتح إن كنتم صدقين࣌', NULL, 417, 'local:warsh-text.json'),
  ('warsh-32-29', 'warsh', 32, 29, 'قُلْ يَوْمَ ࡰ۬لْفَتْحِ لَا يَنفَعُ ࡲ۬لذِينَ كَفَرُوٓاْ إِيمَٰنُهُمْ وَلَا هُمْ يُنظَرُونَ࣌', 'قل يوم ࡰلفتح لا ينفع ࡲلذين كفروا إيمنهم ولا هم ينظرون࣌', NULL, 417, 'local:warsh-text.json'),
  ('warsh-32-30', 'warsh', 32, 30, 'فَأَعْرِضْ عَنْهُمْ وَانتَظِرِ࣌ ࡴنَّهُم مُّنتَظِرُونَ࣌', 'فأعرض عنهم وانتظر࣌ ࡴنهم منتظرون࣌', NULL, 417, 'local:warsh-text.json'),
  ('warsh-33-1', 'warsh', 33, 1, 'يَٰٓأَيُّهَا‏ ࡰ۬لنَّبِےٓءُ ࡲٜتَّقِ ࡴ۬للَّهَ࣌ وَلَا تُطِعِ ࡴ۬لْكٜـٰفِرِينَ وَالْمُنَٰفِقِينَ࣌ إِنَّ ࡰ۬للَّهَ كَانَ عَلِيماً حَكِيماࣰ࣌', 'يأيها‏ ࡰلنبےء ࡲتق ࡴلله࣌ ولا تطع ࡴلكفرين والمنفقين࣌ إن ࡰلله كان عليما حكيما࣌', NULL, 418, 'local:warsh-text.json'),
  ('warsh-33-2', 'warsh', 33, 2, 'وَاتَّبِعْ مَا يُوحٜىٰٓ إِلَيْكَ مِن رَّبِّكَ࣌ إِنَّ ࡰ۬للَّهَ كَانَ بِمَا تَعْمَلُونَ خَبِيراࣰ࣌', 'واتبع ما يوحى إليك من ربك࣌ إن ࡰلله كان بما تعملون خبيرا࣌', NULL, 418, 'local:warsh-text.json'),
  ('warsh-33-3', 'warsh', 33, 3, 'وَتَوَكَّلْ عَلَى ࡰ۬للَّهِ࣌ وَكَفٜىٰ بِاللَّهِ وَكِيلاࣰ࣌', 'وتوكل على ࡰلله࣌ وكفى بالله وكيلا࣌', NULL, 418, 'local:warsh-text.json'),
  ('warsh-33-4', 'warsh', 33, 4, 'مَّا جَعَلَ ࡰ۬للَّهُ لِرَجُلࣲ مِّن قَلْبَيْنِ فِے جَوْفِهِۦ࣌ وَمَا جَعَلَ أَزْوَٰجَكُمُ ࡲ۬لٜےْ تَظَّهَّرُونَ مِنْهُنَّ أُمَّهَٰتِكُمْ࣌ وَمَا جَعَلَ أَدْعِيَآءَكُمُۥٓ أَبْنَآءَكُمْ࣌ ذَٰلِكُمْ قَوْلُكُم بِأَفْوَٰهِكُمْ࣌ وَاللَّهُ يَقُولُ ࡲ۬لْحَقَّ࣌ وَهُوَ يَهْدِے ࡴ۬لسَّبِيلَ࣌', 'ما جعل ࡰلله لرجل من قلبين فے جوفه࣌ وما جعل أزوجكم ࡲلے تظهرون منهن أمهتكم࣌ وما جعل أدعياءكم أبناءكم࣌ ذلكم قولكم بأفوهكم࣌ والله يقول ࡲلحق࣌ وهو يهدے ࡴلسبيل࣌', NULL, 418, 'local:warsh-text.json'),
  ('warsh-33-5', 'warsh', 33, 5, 'ࡸَدْعُوهُمْ لِأٓبَآئِهِمْ هُوَ أَقْسَطُ عِندَ ࡰ۬للَّهِ࣌ فَإِن لَّمْ تَعْلَمُوٓاْ ءَابَآءَهُمْ فَإِخْوَٰنُكُمْ فِے ࡴ۬لدِّينِ وَمَوَٰلِيكُمْ࣌ وَلَيْسَ عَلَيْكُمْ جُنَاحࣱ فِيمَآ أَخْطَأْتُم بِهِۦ࣌ وَلَٰكِن مَّا تَعَمَّدَتْ قُلُوبُكُمْ࣌ وَكَانَ ࡰ۬للَّهُ غَفُوراࣰ رَّحِيماً࣌', 'ࡸدعوهم لأبائهم هو أقسط عند ࡰلله࣌ فإن لم تعلموا ءاباءهم فإخونكم فے ࡴلدين وموليكم࣌ وليس عليكم جناح فيما أخطأتم به࣌ ولكن ما تعمدت قلوبكم࣌ وكان ࡰلله غفورا رحيما࣌', NULL, 418, 'local:warsh-text.json'),
  ('warsh-33-6', 'warsh', 33, 6, 'ࡴ۬لنَّبِےٓءُ ࡶَوْلٜىٰ بِالْمُومِنِينَ مِنَ ࡰنفُسِهِمْ࣌ وَأَزْوَٰجُهُۥٓ أُمَّهَٰتُهُمْ࣌ وَأُوْلُواْ ࡲ۬لَارْحَامِ بَعْضُهُمُۥٓ أَوْلٜىٰ بِبَعْضࣲ فِے كِتَٰبِ ࡴ۬للَّهِ مِنَ ࡰ۬لْمُومِنِينَ وَالْمُهَٰجِرِينَ إِلَّآ أَن تَفْعَلُوٓاْ إِلَىٰٓ أَوْلِيَآئِكُم مَّعْرُوفاࣰ࣌ كَانَ ذَٰلِكَ فِے ࡴ۬لْكِتَٰبِ مَسْطُوراࣰ࣌', 'ࡴلنبےء ࡶولى بالمومنين من ࡰنفسهم࣌ وأزوجه أمهتهم࣌ وأولوا ࡲلارحام بعضهم أولى ببعض فے كتب ࡴلله من ࡰلمومنين والمهجرين إلا أن تفعلوا إلى أوليائكم معروفا࣌ كان ذلك فے ࡴلكتب مسطورا࣌', NULL, 418, 'local:warsh-text.json'),
  ('warsh-33-7', 'warsh', 33, 7, 'وَإِذَ ࡰخَذْنَا مِنَ ࡰ۬لنَّبِيٓـِٕۑنَ مِيثَٰقَهُمْ وَمِنكَ وَمِن نُّوحࣲ وَإِبْرَٰهِيمَ وَمُوسٜىٰ وَعِيسَى ࡰٜبْنِ مَرْيَمَ࣌ وَأَخَذْنَا مِنْهُم مِّيثَٰقاً غَلِيظاࣰ', 'وإذ ࡰخذنا من ࡰلنبيۑن ميثقهم ومنك ومن نوح وإبرهيم وموسى وعيسى ࡰبن مريم࣌ وأخذنا منهم ميثقا غليظا', NULL, 419, 'local:warsh-text.json'),
  ('warsh-33-8', 'warsh', 33, 8, 'لِّيَسْـَٔلَ ࡰ۬لصَّٰدِقِينَ عَن صِدْقِهِمْ࣌ وَأَعَدَّ لِلْكٜـٰفِرِينَ عَذَاباً ࡰلِيماࣰ࣌', 'ليسل ࡰلصدقين عن صدقهم࣌ وأعد للكفرين عذابا ࡰليما࣌', NULL, 419, 'local:warsh-text.json'),
  ('warsh-33-9', 'warsh', 33, 9, '۞ يَٰٓأَيُّهَا ࡰ۬لذِينَ ءَامَنُواْ ࡲ࢈ذْكُرُواْ نِعْمَةَ ࡰ۬للَّهِ عَلَيْكُمُۥٓ إِذْ جَآءَتْكُمْ جُنُودࣱ فَأَرْسَلْنَا عَلَيْهِمْ رِيحاࣰ وَجُنُوداࣰ لَّمْ تَرَوْهَا࣌ وَكَانَ ࡰ۬للَّهُ بِمَا تَعْمَلُونَ بَصِيراً࣌', 'يأيها ࡰلذين ءامنوا ࡲ࢈ذكروا نعمة ࡰلله عليكم إذ جاءتكم جنود فأرسلنا عليهم ريحا وجنودا لم تروها࣌ وكان ࡰلله بما تعملون بصيرا࣌', NULL, 419, 'local:warsh-text.json'),
  ('warsh-33-10', 'warsh', 33, 10, 'ࡴذْ جَآءُوكُم مِّن فَوْقِكُمْ وَمِنَ ࡰسْفَلَ مِنكُمْ࣌ وَإِذْ زَاغَتِ ࡴ۬لَابْصَٰرُ وَبَلَغَتِ ࡴ۬لْقُلُوبُ ࡲ۬لْحَنَاجِرَ وَتَظُنُّونَ بِاللَّهِ ࡴ۬لظُّنُونَا࣌', 'ࡴذ جاءوكم من فوقكم ومن ࡰسفل منكم࣌ وإذ زاغت ࡴلابصر وبلغت ࡴلقلوب ࡲلحناجر وتظنون بالله ࡴلظنونا࣌', NULL, 419, 'local:warsh-text.json'),
  ('warsh-33-11', 'warsh', 33, 11, 'هُنَالِكَ ࡸَبْتُلِيَ ࡰ۬لْمُومِنُونَ وَزُلْزِلُواْ زِلْزَالاࣰ شَدِيداࣰ࣌', 'هنالك ࡸبتلي ࡰلمومنون وزلزلوا زلزالا شديدا࣌', NULL, 419, 'local:warsh-text.json'),
  ('warsh-33-12', 'warsh', 33, 12, 'وَإِذْ يَقُولُ ࡲ۬لْمُنَٰفِقُونَ وَالذِينَ فِے قُلُوبِهِم مَّرَضࣱ مَّا وَعَدَنَا ࡰ۬للَّهُ وَرَسُولُهُۥٓ إِلَّا غُرُوراࣰ࣌', 'وإذ يقول ࡲلمنفقون والذين فے قلوبهم مرض ما وعدنا ࡰلله ورسوله إلا غرورا࣌', NULL, 419, 'local:warsh-text.json'),
  ('warsh-33-13', 'warsh', 33, 13, 'وَإِذْ قَالَت طَّآئِفَةࣱ مِّنْهُمْ يَٰٓأَهْلَ يَثْرِبَ لَا مَقَامَ لَكُمْ فَارْجِعُواْ࣌ وَيَسْتَٰذِنُ فَرِيقࣱ مِّنْهُمُ ࡲ۬لنَّبِےٓءَ يَقُولُونَ إِنَّ بُيُوتَنَا عَوْرَةࣱ وَمَا هِيَ بِعَوْرَةٍ࣌ ࡴنْ يُّرِيدُونَ إِلَّا فِرَاراࣰ࣌', 'وإذ قالت طائفة منهم يأهل يثرب لا مقام لكم فارجعوا࣌ ويستذن فريق منهم ࡲلنبےء يقولون إن بيوتنا عورة وما هي بعورة࣌ ࡴن يريدون إلا فرارا࣌', NULL, 419, 'local:warsh-text.json'),
  ('warsh-33-14', 'warsh', 33, 14, 'وَلَوْ دُخِلَتْ عَلَيْهِم مِّنَ ࡰقْطٜارِهَا ثُمَّ سُئِلُواْ ࡲ۬لْفِتْنَةَ لَأَتَوْهَا وَمَا تَلَبَّثُواْ بِهَآ إِلَّا يَسِيراࣰ࣌', 'ولو دخلت عليهم من ࡰقطارها ثم سئلوا ࡲلفتنة لأتوها وما تلبثوا بها إلا يسيرا࣌', NULL, 419, 'local:warsh-text.json'),
  ('warsh-33-15', 'warsh', 33, 15, 'وَلَقَدْ كَانُواْ عَٰهَدُواْ ࡲ۬للَّهَ مِن قَبْلُ لَا يُوَلُّونَ ࡰ۬لَادْبَٰرَ࣌ وَكَانَ عَهْدُ ࡲ۬للَّهِ مَسْـُٔولاࣰ࣌', 'ولقد كانوا عهدوا ࡲلله من قبل لا يولون ࡰلادبر࣌ وكان عهد ࡲلله مسولا࣌', NULL, 419, 'local:warsh-text.json'),
  ('warsh-33-16', 'warsh', 33, 16, 'قُل لَّنْ يَّنفَعَكُمُ ࡲ۬لْفِرَارُ إِن فَرَرْتُم مِّنَ ࡰ۬لْمَوْتِ أَوِ ࡴ۬لْقَتْلِ࣌ وَإِذاࣰ لَّا تُمَتَّعُونَ إِلَّا قَلِيلاࣰ࣌', 'قل لن ينفعكم ࡲلفرار إن فررتم من ࡰلموت أو ࡴلقتل࣌ وإذا لا تمتعون إلا قليلا࣌', NULL, 420, 'local:warsh-text.json'),
  ('warsh-33-17', 'warsh', 33, 17, 'قُلْ مَن ذَا ࡰ۬لذِے يَعْصِمُكُم مِّنَ ࡰ۬للَّهِ إِنَ ࡰرَادَ بِكُمْ سُوٓءاً ࡰوَ ࡰرَادَ بِكُمْ رَحْمَةࣰ࣌ وَلَا يَجِدُونَ لَهُم مِّن دُونِ ࡴ۬للَّهِ وَلِيّاࣰ وَلَا نَصِيراࣰ࣌', 'قل من ذا ࡰلذے يعصمكم من ࡰلله إن ࡰراد بكم سوءا ࡰو ࡰراد بكم رحمة࣌ ولا يجدون لهم من دون ࡴلله وليا ولا نصيرا࣌', NULL, 420, 'local:warsh-text.json'),
  ('warsh-33-18', 'warsh', 33, 18, '۞ قَدْ يَعْلَمُ ࡲ۬للَّهُ ࡲ۬لْمُعَوِّقِينَ مِنكُمْ وَالْقَآئِلِينَ لِإِخْوَٰنِهِمْ هَلُمَّ إِلَيْنَا وَلَا يَاتُونَ ࡰ۬لْبَأْسَ إِلَّا قَلِيلاً', 'قد يعلم ࡲلله ࡲلمعوقين منكم والقائلين لإخونهم هلم إلينا ولا ياتون ࡰلبأس إلا قليلا', NULL, 420, 'local:warsh-text.json'),
  ('warsh-33-19', 'warsh', 33, 19, 'ࡰشِحَّةً عَلَيْكُمْ࣌ فَإِذَا جَآءَ ࡰ۬لْخَوْفُ رَأَيْتَهُمْ يَنظُرُونَ إِلَيْكَ تَدُورُ أَعْيُنُهُمْ كَالذِے يُغْشٜىٰ عَلَيْهِ مِنَ ࡰ۬لْمَوْتِ࣌ فَإِذَا ذَهَبَ ࡰ۬لْخَوْفُ سَلَقُوكُم بِأَلْسِنَةٍ حِدَادٍ ࡰشِحَّةً عَلَى ࡰ۬لْخَيْرِ࣌ أُوْلَٰٓئِكَ لَمْ يُومِنُواْ فَأَحْبَطَ ࡰ۬للَّهُ أَعْمَٰلَهُمْ࣌ وَكَانَ ذَٰلِكَ عَلَى ࡰ۬للَّهِ يَسِيراࣰ࣌', 'ࡰشحة عليكم࣌ فإذا جاء ࡰلخوف رأيتهم ينظرون إليك تدور أعينهم كالذے يغشى عليه من ࡰلموت࣌ فإذا ذهب ࡰلخوف سلقوكم بألسنة حداد ࡰشحة على ࡰلخير࣌ أولئك لم يومنوا فأحبط ࡰلله أعملهم࣌ وكان ذلك على ࡰلله يسيرا࣌', NULL, 420, 'local:warsh-text.json'),
  ('warsh-33-20', 'warsh', 33, 20, 'يَحْسِبُونَ ࡰ۬لَاحْزَابَ لَمْ يَذْهَبُواْ࣌ وَإِنْ يَّاتِ ࡴ۬لَاحْزَابُ يَوَدُّواْ لَوَ ࡰنَّهُم بَادُونَ فِے ࡴ۬لَاعْرَابِ࣌ يَسْـَٔلُونَ عَنَ ࡰنۢبَآئِكُمْ وَلَوْ كَانُواْ فِيكُم مَّا قَٰتَلُوٓاْ إِلَّا قَلِيلاࣰ࣌', 'يحسبون ࡰلاحزاب لم يذهبوا࣌ وإن يات ࡴلاحزاب يودوا لو ࡰنهم بادون فے ࡴلاعراب࣌ يسلون عن ࡰنبائكم ولو كانوا فيكم ما قتلوا إلا قليلا࣌', NULL, 420, 'local:warsh-text.json'),
  ('warsh-33-21', 'warsh', 33, 21, 'لَّقَدْ كَانَ لَكُمْ فِے رَسُولِ ࡴ۬للَّهِ إِسْوَةٌ حَسَنَةࣱ لِّمَن كَانَ يَرْجُواْ ࡲ۬للَّهَ وَالْيَوْمَ ࡰ۬لَاخِرَ وَذَكَرَ ࡰ۬للَّهَ كَثِيراࣰ࣌', 'لقد كان لكم فے رسول ࡴلله إسوة حسنة لمن كان يرجوا ࡲلله واليوم ࡰلاخر وذكر ࡰلله كثيرا࣌', NULL, 420, 'local:warsh-text.json'),
  ('warsh-33-22', 'warsh', 33, 22, 'وَلَمَّا رَءَا ࡰ۬لْمُومِنُونَ ࡰ۬لَاحْزَابَ قَالُواْ هَٰذَا مَا وَعَدَنَا ࡰ۬للَّهُ وَرَسُولُهُۥ وَصَدَقَ ࡰ۬للَّهُ وَرَسُولُهُۥ࣌ وَمَا زَادَهُمُۥٓ إِلَّآ إِيمَٰناࣰ وَتَسْلِيماࣰ࣌', 'ولما رءا ࡰلمومنون ࡰلاحزاب قالوا هذا ما وعدنا ࡰلله ورسوله وصدق ࡰلله ورسوله࣌ وما زادهم إلا إيمنا وتسليما࣌', NULL, 420, 'local:warsh-text.json'),
  ('warsh-33-23', 'warsh', 33, 23, 'مِّنَ ࡰ۬لْمُومِنِينَ رِجَالࣱ صَدَقُواْ مَا عَٰهَدُواْ ࡲ۬للَّهَ عَلَيْهِ࣌ فَمِنْهُم مَّن قَضٜىٰ نَحْبَهُۥ وَمِنْهُم مَّنْ يَّنتَظِرُ࣌ وَمَا بَدَّلُواْ تَبْدِيلاࣰ', 'من ࡰلمومنين رجال صدقوا ما عهدوا ࡲلله عليه࣌ فمنهم من قضى نحبه ومنهم من ينتظر࣌ وما بدلوا تبديلا', NULL, 421, 'local:warsh-text.json'),
  ('warsh-33-24', 'warsh', 33, 24, 'لِّيَجْزِيَ ࡰ۬للَّهُ ࡲ۬لصَّٰدِقِينَ بِصِدْقِهِمْ وَيُعَذِّبَ ࡰ۬لْمُنَٰفِقِينَ إِن شَآءَ اوْ يَتُوبَ عَلَيْهِمُۥٓ࣌ إِنَّ ࡰ۬للَّهَ كَانَ غَفُوراࣰ رَّحِيماࣰ࣌', 'ليجزي ࡰلله ࡲلصدقين بصدقهم ويعذب ࡰلمنفقين إن شاء او يتوب عليهم࣌ إن ࡰلله كان غفورا رحيما࣌', NULL, 421, 'local:warsh-text.json'),
  ('warsh-33-25', 'warsh', 33, 25, '۞ وَرَدَّ ࡰ۬للَّهُ ࡲ۬لذِينَ كَفَرُواْ بِغَيْظِهِمْ لَمْ يَنَالُواْ خَيْراࣰ࣌ وَكَفَى ࡰ۬للَّهُ ࡲ۬لْمُومِنِينَ ࡰ۬لْقِتَالَ࣌ وَكَانَ ࡰ۬للَّهُ قَوِيّاً عَزِيزاࣰ࣌', 'ورد ࡰلله ࡲلذين كفروا بغيظهم لم ينالوا خيرا࣌ وكفى ࡰلله ࡲلمومنين ࡰلقتال࣌ وكان ࡰلله قويا عزيزا࣌', NULL, 421, 'local:warsh-text.json'),
  ('warsh-33-26', 'warsh', 33, 26, 'وَأَنزَلَ ࡰ۬لذِينَ ظَٰهَرُوهُم مِّنَ ࡰهْلِ ࡴ۬لْكِتَٰبِ مِن صَيَاصِيهِمْ وَقَذَفَ فِے قُلُوبِهِمُ ࡲ۬لرُّعْبَ࣌ فَرِيقاࣰ تَقْتُلُونَ وَتَاسِرُونَ فَرِيقاࣰ࣌', 'وأنزل ࡰلذين ظهروهم من ࡰهل ࡴلكتب من صياصيهم وقذف فے قلوبهم ࡲلرعب࣌ فريقا تقتلون وتاسرون فريقا࣌', NULL, 421, 'local:warsh-text.json'),
  ('warsh-33-27', 'warsh', 33, 27, 'وَأَوْرَثَكُمُۥٓ أَرْضَهُمْ وَدِيَٰرَهُمْ وَأَمْوَٰلَهُمْ وَأَرْضاࣰ لَّمْ تَطَـُٔوهَا࣌ وَكَانَ ࡰ۬للَّهُ عَلَىٰ كُلِّ شَےْءࣲ قَدِيراࣰ࣌', 'وأورثكم أرضهم وديرهم وأمولهم وأرضا لم تطوها࣌ وكان ࡰلله على كل شےء قديرا࣌', NULL, 421, 'local:warsh-text.json'),
  ('warsh-33-28', 'warsh', 33, 28, 'يَٰٓأَيُّهَا‏ ࡰ۬لنَّبِےٓءُ قُل لِّأَزْوَٰجِكَ إِن كُنتُنَّ تُرِدْنَ ࡰ۬لْحَيَوٰةَ ࡰ۬لدُّنْيٜا وَزِينَتَهَا فَتَعَالَيْنَ أُمَتِّعْكُنَّ وَأُسَرِّحْكُنَّ سَرَاحاࣰ جَمِيلاࣰ࣌', 'يأيها‏ ࡰلنبےء قل لأزوجك إن كنتن تردن ࡰلحيوة ࡰلدنيا وزينتها فتعالين أمتعكن وأسرحكن سراحا جميلا࣌', NULL, 421, 'local:warsh-text.json'),
  ('warsh-33-29', 'warsh', 33, 29, 'وَإِن كُنتُنَّ تُرِدْنَ ࡰ۬للَّهَ وَرَسُولَهُۥ وَالدَّارَ ࡰ۬لَاخِرَةَ فَإِنَّ ࡰ۬للَّهَ أَعَدَّ لِلْمُحْسِنَٰتِ مِنكُنَّ أَجْراً عَظِيماࣰ࣌', 'وإن كنتن تردن ࡰلله ورسوله والدار ࡰلاخرة فإن ࡰلله أعد للمحسنت منكن أجرا عظيما࣌', NULL, 421, 'local:warsh-text.json'),
  ('warsh-33-30', 'warsh', 33, 30, 'يَٰنِسَآءَ ࡰ۬لنَّبِےٓءِ مَنْ يَّاتِ مِنكُنَّ بِفَٰحِشَةࣲ مُّبَيِّنَةࣲ يُضَٰعَفْ لَهَا ࡰ۬لْعَذَابُ ضِعْفَيْنِ࣌ وَكَانَ ذَٰلِكَ عَلَى ࡰ۬للَّهِ يَسِيراࣰ࣌', 'ينساء ࡰلنبےء من يات منكن بفحشة مبينة يضعف لها ࡰلعذاب ضعفين࣌ وكان ذلك على ࡰلله يسيرا࣌', NULL, 421, 'local:warsh-text.json'),
  ('warsh-33-31', 'warsh', 33, 31, '۞ وَمَنْ يَّقْنُتْ مِنكُنَّ لِلهِ وَرَسُولِهِۦ وَتَعْمَلْ صَٰلِحاࣰ نُّوتِهَآ أَجْرَهَا مَرَّتَيْنِ وَأَعْتَدْنَا لَهَا رِزْقاࣰ كَرِيماࣰ࣌', 'ومن يقنت منكن لله ورسوله وتعمل صلحا نوتها أجرها مرتين وأعتدنا لها رزقا كريما࣌', NULL, 422, 'local:warsh-text.json'),
  ('warsh-33-32', 'warsh', 33, 32, 'يَٰنِسَآءَ ࡰ۬لنَّبِےٓءِ لَسْتُنَّ كَأَحَدࣲ مِّنَ ࡰ۬لنِّسَآءِ انِ ࡴٜتَّقَيْتُنَّ࣌ فَلَا تَخْضَعْنَ بِالْقَوْلِ فَيَطْمَعَ ࡰ۬لذِے فِے قَلْبِهِۦ مَرَضࣱ وَقُلْنَ قَوْلاࣰ مَّعْرُوفاࣰ', 'ينساء ࡰلنبےء لستن كأحد من ࡰلنساء ان ࡴتقيتن࣌ فلا تخضعن بالقول فيطمع ࡰلذے فے قلبه مرض وقلن قولا معروفا', NULL, 422, 'local:warsh-text.json'),
  ('warsh-33-33', 'warsh', 33, 33, 'وَقَرْنَ فِے بُيُوتِكُنَّ࣌ وَلَا تَبَرَّجْنَ تَبَرُّجَ ࡰ۬لْجَٰهِلِيَّةِ ࡴ۬لُاولٜىٰ࣌ وَأَقِمْنَ ࡰ۬لصَّلَوٰةَ وَءَاتِينَ ࡰ۬لزَّكَوٰةَ࣌ وَأَطِعْنَ ࡰ۬للَّهَ وَرَسُولَهُۥٓ࣌ إِنَّمَا يُرِيدُ ࡲ۬للَّهُ لِيُذْهِبَ عَنكُمُ ࡲ۬لرِّجْسَ أَهْلَ ࡰ۬لْبَيْتِ وَيُطَهِّرَكُمْ تَطْهِيراࣰ࣌', 'وقرن فے بيوتكن࣌ ولا تبرجن تبرج ࡰلجهلية ࡴلاولى࣌ وأقمن ࡰلصلوة وءاتين ࡰلزكوة࣌ وأطعن ࡰلله ورسوله࣌ إنما يريد ࡲلله ليذهب عنكم ࡲلرجس أهل ࡰلبيت ويطهركم تطهيرا࣌', NULL, 422, 'local:warsh-text.json'),
  ('warsh-33-34', 'warsh', 33, 34, 'وَاذْكُرْنَ مَا يُتْلٜىٰ فِے بُيُوتِكُنَّ مِنَ اٰيَٰتِ ࡴ۬للَّهِ وَالْحِكْمَةِ࣌ إِنَّ ࡰ۬للَّهَ كَانَ لَطِيفاً خَبِيراً࣌', 'واذكرن ما يتلى فے بيوتكن من ايت ࡴلله والحكمة࣌ إن ࡰلله كان لطيفا خبيرا࣌', NULL, 422, 'local:warsh-text.json'),
  ('warsh-33-35', 'warsh', 33, 35, 'ࡴنَّ ࡰ۬لْمُسْلِمِينَ وَالْمُسْلِمَٰتِ وَالْمُومِنِينَ وَالْمُومِنَٰتِ وَالْقَٰنِتِينَ وَالْقَٰنِتَٰتِ وَالصَّٰدِقِينَ وَالصَّٰدِقَٰتِ وَالصَّٰبِرِينَ وَالصَّٰبِرَٰتِ وَالْخَٰشِعِينَ وَالْخَٰشِعَٰتِ وَالْمُتَصَدِّقِينَ وَالْمُتَصَدِّقَٰتِ وَالصَّٰٓئِمِينَ وَالصَّٰٓئِمَٰتِ وَالْحَٰفِظِينَ فُرُوجَهُمْ وَالْحَٰفِظَٰتِ وَالذَّٰكِرِينَ ࡰ۬للَّهَ كَثِيراࣰ وَالذَّٰكِرَٰتِ أَعَدَّ ࡰ۬للَّهُ لَهُم مَّغْفِرَةࣰ وَأَجْراً عَظِيماࣰ࣌', 'ࡴن ࡰلمسلمين والمسلمت والمومنين والمومنت والقنتين والقنتت والصدقين والصدقت والصبرين والصبرت والخشعين والخشعت والمتصدقين والمتصدقت والصئمين والصئمت والحفظين فروجهم والحفظت والذكرين ࡰلله كثيرا والذكرت أعد ࡰلله لهم مغفرة وأجرا عظيما࣌', NULL, 422, 'local:warsh-text.json'),
  ('warsh-33-36', 'warsh', 33, 36, 'وَمَا كَانَ لِمُومِنࣲ وَلَا مُومِنَةٍ ࡴذَا قَضَى ࡰ۬للَّهُ وَرَسُولُهُۥٓ أَمْراً ࡰن تَكُونَ لَهُمُ ࡲ۬لْخِيَرَةُ مِنَ ࡰمْرِهِمْ࣌ وَمَنْ يَّعْصِ ࡴ۬للَّهَ وَرَسُولَهُۥ فَقَد ضَّلَّ ضَلَٰلاࣰ مُّبِيناࣰ࣌', 'وما كان لمومن ولا مومنة ࡴذا قضى ࡰلله ورسوله أمرا ࡰن تكون لهم ࡲلخيرة من ࡰمرهم࣌ ومن يعص ࡴلله ورسوله فقد ضل ضللا مبينا࣌', NULL, 423, 'local:warsh-text.json'),
  ('warsh-33-37', 'warsh', 33, 37, 'وَإِذْ تَقُولُ لِلذِےٓ أَنْعَمَ ࡰ۬للَّهُ عَلَيْهِ وَأَنْعَمْتَ عَلَيْهِ أَمْسِكْ عَلَيْكَ زَوْجَكَ وَاتَّقِ ࡴ۬للَّهَ وَتُخْفِے فِے نَفْسِكَ مَا ࡰ۬للَّهُ مُبْدِيهِ وَتَخْشَى ࡰ۬لنَّاسَ وَاللَّهُ أَحَقُّ أَن تَخْشٜيٰهُ࣌ ۞ فَلَمَّا قَضٜىٰ زَيْدࣱ مِّنْهَا وَطَراࣰ زَوَّجْنَٰكَهَا لِكَےْ لَا يَكُونَ عَلَى ࡰ۬لْمُومِنِينَ حَرَجࣱ فِےٓ أَزْوَٰجِ أَدْعِيَآئِهِمُۥٓ إِذَا قَضَوْاْ مِنْهُنَّ وَطَراࣰ࣌ وَكَانَ أَمْرُ ࡲ۬للَّهِ مَفْعُولاࣰ࣌', 'وإذ تقول للذے أنعم ࡰلله عليه وأنعمت عليه أمسك عليك زوجك واتق ࡴلله وتخفے فے نفسك ما ࡰلله مبديه وتخشى ࡰلناس والله أحق أن تخشيه࣌  فلما قضى زيد منها وطرا زوجنكها لكے لا يكون على ࡰلمومنين حرج فے أزوج أدعيائهم إذا قضوا منهن وطرا࣌ وكان أمر ࡲلله مفعولا࣌', NULL, 423, 'local:warsh-text.json'),
  ('warsh-33-38', 'warsh', 33, 38, 'مَّا كَانَ عَلَى ࡰ۬لنَّبِےٓءِ مِنْ حَرَجࣲ فِيمَا فَرَضَ ࡰ۬للَّهُ لَهُۥ࣌ سُنَّةَ ࡰ۬للَّهِ فِے ࡴ۬لذِينَ خَلَوْاْ مِن قَبْلُ࣌ وَكَانَ أَمْرُ ࡲ۬للَّهِ قَدَراࣰ مَّقْدُوراً࣌', 'ما كان على ࡰلنبےء من حرج فيما فرض ࡰلله له࣌ سنة ࡰلله فے ࡴلذين خلوا من قبل࣌ وكان أمر ࡲلله قدرا مقدورا࣌', NULL, 423, 'local:warsh-text.json'),
  ('warsh-33-39', 'warsh', 33, 39, 'ࡴ۬لذِينَ يُبَلِّغُونَ رِسَٰلَٰتِ ࡴ۬للَّهِ وَيَخْشَوْنَهُۥ وَلَا يَخْشَوْنَ أَحَداً ࡴلَّا ࡰ۬للَّهَ࣌ وَكَفٜىٰ بِاللَّهِ حَسِيباࣰ࣌', 'ࡴلذين يبلغون رسلت ࡴلله ويخشونه ولا يخشون أحدا ࡴلا ࡰلله࣌ وكفى بالله حسيبا࣌', NULL, 423, 'local:warsh-text.json'),
  ('warsh-33-40', 'warsh', 33, 40, 'مَّا كَانَ مُحَمَّدٌ ࡰبَآ أَحَدࣲ مِّن رِّجَالِكُمْ࣌ وَلَٰكِن رَّسُولَ ࡰ۬للَّهِ وَخَاتِمَ ࡰ۬لنَّبِيٓـِٕۑنَ࣌ وَكَانَ ࡰ۬للَّهُ بِكُلِّ شَےْءٍ عَلِيماࣰ࣌', 'ما كان محمد ࡰبا أحد من رجالكم࣌ ولكن رسول ࡰلله وخاتم ࡰلنبيۑن࣌ وكان ࡰلله بكل شےء عليما࣌', NULL, 423, 'local:warsh-text.json'),
  ('warsh-33-41', 'warsh', 33, 41, 'يَٰٓأَيُّهَا ࡰ۬لذِينَ ءَامَنُواْ ࡲ࢈ذْكُرُواْ ࡲ۬للَّهَ ذِكْراࣰ كَثِيراࣰ', 'يأيها ࡰلذين ءامنوا ࡲ࢈ذكروا ࡲلله ذكرا كثيرا', NULL, 423, 'local:warsh-text.json'),
  ('warsh-33-42', 'warsh', 33, 42, 'وَسَبِّحُوهُ بُكْرَةࣰ وَأَصِيلاً࣌', 'وسبحوه بكرة وأصيلا࣌', NULL, 423, 'local:warsh-text.json'),
  ('warsh-33-43', 'warsh', 33, 43, 'هُوَ ࡰ۬لذِے يُصَلِّے عَلَيْكُمْ وَمَلَٰٓئِكَتُهُۥ لِيُخْرِجَكُم مِّنَ ࡰ۬لظُّلُمَٰتِ إِلَى ࡰ۬لنُّورِ࣌ وَكَانَ بِالْمُومِنِينَ رَحِيماࣰ࣌', 'هو ࡰلذے يصلے عليكم وملئكته ليخرجكم من ࡰلظلمت إلى ࡰلنور࣌ وكان بالمومنين رحيما࣌', NULL, 423, 'local:warsh-text.json'),
  ('warsh-33-44', 'warsh', 33, 44, 'تَحِيَّتُهُمْ يَوْمَ يَلْقَوْنَهُۥ سَلَٰمࣱ࣌ وَأَعَدَّ لَهُمُۥٓ أَجْراࣰ كَرِيماࣰ࣌', 'تحيتهم يوم يلقونه سلم࣌ وأعد لهم أجرا كريما࣌', NULL, 424, 'local:warsh-text.json'),
  ('warsh-33-45', 'warsh', 33, 45, 'يَٰٓأَيُّهَا ࡰ۬لنَّبِےٓءُ ࡹِنَّآ أَرْسَلْنَٰكَ شَٰهِداࣰ وَمُبَشِّراࣰ وَنَذِيراࣰ', 'يأيها ࡰلنبےء ࡹنا أرسلنك شهدا ومبشرا ونذيرا', NULL, 424, 'local:warsh-text.json'),
  ('warsh-33-46', 'warsh', 33, 46, 'وَدَاعِياً ࡴلَى ࡰ۬للَّهِ بِإِذْنِهِۦ وَسِرَاجاࣰ مُّنِيراࣰ࣌', 'وداعيا ࡴلى ࡰلله بإذنه وسراجا منيرا࣌', NULL, 424, 'local:warsh-text.json'),
  ('warsh-33-47', 'warsh', 33, 47, 'وَبَشِّرِ ࡴ۬لْمُومِنِينَ بِأَنَّ لَهُم مِّنَ ࡰ۬للَّهِ فَضْلاࣰ كَبِيراࣰ࣌', 'وبشر ࡴلمومنين بأن لهم من ࡰلله فضلا كبيرا࣌', NULL, 424, 'local:warsh-text.json'),
  ('warsh-33-48', 'warsh', 33, 48, 'وَلَا تُطِعِ ࡴ۬لْكٜـٰفِرِينَ وَالْمُنَٰفِقِينَ࣌ وَدَعَ ࡰذٜيٰهُمْ࣌ وَتَوَكَّلْ عَلَى ࡰ۬للَّهِ࣌ وَكَفٜىٰ بِاللَّهِ وَكِيلاࣰ࣌', 'ولا تطع ࡴلكفرين والمنفقين࣌ ودع ࡰذيهم࣌ وتوكل على ࡰلله࣌ وكفى بالله وكيلا࣌', NULL, 424, 'local:warsh-text.json'),
  ('warsh-33-49', 'warsh', 33, 49, '۞ يَٰٓأَيُّهَا ࡰ۬لذِينَ ءَامَنُوٓاْ إِذَا نَكَحْتُمُ ࡲ۬لْمُومِنَٰتِ ثُمَّ طَلَّقْتُمُوهُنَّ مِن قَبْلِ أَن تَمَسُّوهُنَّ فَمَا لَكُمْ عَلَيْهِنَّ مِنْ عِدَّةࣲ تَعْتَدُّونَهَا࣌ فَمَتِّعُوهُنَّ وَسَرِّحُوهُنَّ سَرَاحاࣰ جَمِيلاࣰ࣌', 'يأيها ࡰلذين ءامنوا إذا نكحتم ࡲلمومنت ثم طلقتموهن من قبل أن تمسوهن فما لكم عليهن من عدة تعتدونها࣌ فمتعوهن وسرحوهن سراحا جميلا࣌', NULL, 424, 'local:warsh-text.json'),
  ('warsh-33-50', 'warsh', 33, 50, 'يَٰٓأَيُّهَا‏ ࡰ۬لنَّبِےٓءُ ࡹِنَّآ أَحْلَلْنَا لَكَ أَزْوَٰجَكَ ࡰ۬لتِےٓ ءَاتَيْتَ أُجُورَهُنَّ وَمَا مَلَكَتْ يَمِينُكَ مِمَّآ أَفَآءَ ࡰ۬للَّهُ عَلَيْكَ وَبَنَاتِ عَمِّكَ وَبَنَاتِ عَمَّٰتِكَ وَبَنَاتِ خَالِكَ وَبَنَاتِ خَٰلَٰتِكَ ࡰ۬لتِے هَاجَرْنَ مَعَكَ وَامْرَأَةࣰ مُّومِنَةً ࡴنْ وَّهَبَتْ نَفْسَهَا لِلنَّبِےٓءِ انَ ࡰرَادَ‏ ࡰ۬لنَّبِےٓءُ ࡶَنْ يَّسْتَنكِحَهَا࣌ خَالِصَةࣰ لَّكَ مِن دُونِ ࡴ۬لْمُومِنِينَ࣌ قَدْ عَلِمْنَا مَا فَرَضْنَا عَلَيْهِمْ فِےٓ أَزْوَٰجِهِمْ وَمَا مَلَكَتَ ࡰيْمَٰنُهُمْ لِكَيْلَا يَكُونَ عَلَيْكَ حَرَجࣱ࣌ وَكَانَ ࡰ۬للَّهُ غَفُوراࣰ رَّحِيماࣰ࣌', 'يأيها‏ ࡰلنبےء ࡹنا أحللنا لك أزوجك ࡰلتے ءاتيت أجورهن وما ملكت يمينك مما أفاء ࡰلله عليك وبنات عمك وبنات عمتك وبنات خالك وبنات خلتك ࡰلتے هاجرن معك وامرأة مومنة ࡴن وهبت نفسها للنبےء ان ࡰراد‏ ࡰلنبےء ࡶن يستنكحها࣌ خالصة لك من دون ࡴلمومنين࣌ قد علمنا ما فرضنا عليهم فے أزوجهم وما ملكت ࡰيمنهم لكيلا يكون عليك حرج࣌ وكان ࡰلله غفورا رحيما࣌', NULL, 424, 'local:warsh-text.json'),
  ('warsh-33-51', 'warsh', 33, 51, 'تُرْجِے مَن تَشَآءُ مِنْهُنَّ وَتُـْٔوِےٓ إِلَيْكَ مَن تَشَآءُ࣌ وَمَنِ ࡴٜبْتَغَيْتَ مِمَّنْ عَزَلْتَ فَلَا جُنَاحَ عَلَيْكَ࣌ ذَٰلِكَ أَدْنٜىٰٓ أَن تَقَرَّ أَعْيُنُهُنَّ وَلَا يَحْزَنَّ وَيَرْضَيْنَ بِمَآ ءَاتَيْتَهُنَّ كُلُّهُنَّ࣌ وَاللَّهُ يَعْلَمُ مَا فِے قُلُوبِكُمْ࣌ وَكَانَ ࡰ۬للَّهُ عَلِيماً حَلِيماࣰ࣌', 'ترجے من تشاء منهن وتوے إليك من تشاء࣌ ومن ࡴبتغيت ممن عزلت فلا جناح عليك࣌ ذلك أدنى أن تقر أعينهن ولا يحزن ويرضين بما ءاتيتهن كلهن࣌ والله يعلم ما فے قلوبكم࣌ وكان ࡰلله عليما حليما࣌', NULL, 425, 'local:warsh-text.json'),
  ('warsh-33-52', 'warsh', 33, 52, 'لَّا يَحِلُّ لَكَ ࡰ۬لنِّسَآءُ مِنۢ بَعْدُ وَلَآ أَن تَبَدَّلَ بِهِنَّ مِنَ ࡰزْوَٰجࣲ وَلَوَ ࡰعْجَبَكَ حُسْنُهُنَّ إِلَّا مَا مَلَكَتْ يَمِينُكَ࣌ وَكَانَ ࡰ۬للَّهُ عَلَىٰ كُلِّ شَےْءࣲ رَّقِيباࣰ࣌', 'لا يحل لك ࡰلنساء من بعد ولا أن تبدل بهن من ࡰزوج ولو ࡰعجبك حسنهن إلا ما ملكت يمينك࣌ وكان ࡰلله على كل شےء رقيبا࣌', NULL, 425, 'local:warsh-text.json'),
  ('warsh-33-53', 'warsh', 33, 53, '۞ يَٰٓأَيُّهَا ࡰ۬لذِينَ ءَامَنُواْ لَا تَدْخُلُواْ بُيُوتَ ࡰ۬لنَّبِےٓءِ الَّآ أَنْ يُّوذَنَ لَكُمُۥٓ إِلَىٰ طَعَامٍ غَيْرَ نَٰظِرِينَ إِنٜيٰهُ࣌ وَلَٰكِنِ ࡴذَا دُعِيتُمْ فَادْخُلُواْ فَإِذَا طَعِمْتُمْ فَانتَشِرُواْ وَلَا مُسْتَٰنِسِينَ لِحَدِيثٍ࣌ ࡴنَّ ذَٰلِكُمْ كَانَ يُوذِے ࡴ۬لنَّبِےٓءَ فَيَسْتَحْيِۦ مِنكُمْ࣌ وَاللَّهُ لَا يَسْتَحْيِۦ مِنَ ࡰ۬لْحَقِّ࣌ وَإِذَا سَأَلْتُمُوهُنَّ مَتَٰعاࣰ فَسْـَٔلُوهُنَّ مِنْ وَّرَآءِ حِجَابࣲ࣌ ذَٰلِكُمُۥٓ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ࣌ وَمَا كَانَ لَكُمُۥٓ أَن تُوذُواْ رَسُولَ ࡰ۬للَّهِ وَلَآ أَن تَنكِحُوٓاْ أَزْوَٰجَهُۥ مِنۢ بَعْدِهِۦٓ أَبَداً࣌ ࡴنَّ ذَٰلِكُمْ كَانَ عِندَ ࡰ۬للَّهِ عَظِيماً࣌', 'يأيها ࡰلذين ءامنوا لا تدخلوا بيوت ࡰلنبےء الا أن يوذن لكم إلى طعام غير نظرين إنيه࣌ ولكن ࡴذا دعيتم فادخلوا فإذا طعمتم فانتشروا ولا مستنسين لحديث࣌ ࡴن ذلكم كان يوذے ࡴلنبےء فيستحي منكم࣌ والله لا يستحي من ࡰلحق࣌ وإذا سألتموهن متعا فسلوهن من وراء حجاب࣌ ذلكم أطهر لقلوبكم وقلوبهن࣌ وما كان لكم أن توذوا رسول ࡰلله ولا أن تنكحوا أزوجه من بعده أبدا࣌ ࡴن ذلكم كان عند ࡰلله عظيما࣌', NULL, 425, 'local:warsh-text.json'),
  ('warsh-33-54', 'warsh', 33, 54, 'ࡴن تُبْدُواْ شَيْـٔاً ࡰوْ تُخْفُوهُ فَإِنَّ ࡰ۬للَّهَ كَانَ بِكُلِّ شَےْءٍ عَلِيماࣰ࣌', 'ࡴن تبدوا شيا ࡰو تخفوه فإن ࡰلله كان بكل شےء عليما࣌', NULL, 425, 'local:warsh-text.json'),
  ('warsh-33-55', 'warsh', 33, 55, 'لَّا جُنَاحَ عَلَيْهِنَّ فِےٓ ءَابَآئِهِنَّ وَلَآ أَبْنَآئِهِنَّ وَلَآ إِخْوَٰنِهِنَّ وَلَآ أَبْنَآءِ اخْوَٰنِهِنَّ وَلَآ أَبْنَآءِ ࡶَخَوَٰتِهِنَّ وَلَا نِسَآئِهِنَّ وَلَا مَا مَلَكَتَ ࡰيْمَٰنُهُنَّ࣌ وَاتَّقِينَ ࡰ۬للَّهَ࣌ إِنَّ ࡰ۬للَّهَ كَانَ عَلَىٰ كُلِّ شَےْءࣲ شَهِيداً࣌', 'لا جناح عليهن فے ءابائهن ولا أبنائهن ولا إخونهن ولا أبناء اخونهن ولا أبناء ࡶخوتهن ولا نسائهن ولا ما ملكت ࡰيمنهن࣌ واتقين ࡰلله࣌ إن ࡰلله كان على كل شےء شهيدا࣌', NULL, 426, 'local:warsh-text.json'),
  ('warsh-33-56', 'warsh', 33, 56, 'ࡴنَّ ࡰ۬للَّهَ وَمَلَٰٓئِكَتَهُۥ يُصَلُّونَ عَلَى ࡰ۬لنَّبِےٓءِ࣌ يَٰٓأَيُّهَا ࡰ۬لذِينَ ءَامَنُواْ صَلُّواْ عَلَيْهِ وَسَلِّمُواْ تَسْلِيماً࣌', 'ࡴن ࡰلله وملئكته يصلون على ࡰلنبےء࣌ يأيها ࡰلذين ءامنوا صلوا عليه وسلموا تسليما࣌', NULL, 426, 'local:warsh-text.json'),
  ('warsh-33-57', 'warsh', 33, 57, 'ࡴنَّ ࡰ۬لذِينَ يُوذُونَ ࡰ۬للَّهَ وَرَسُولَهُۥ لَعَنَهُمُ ࡲ۬للَّهُ فِے ࡴ۬لدُّنْيٜا وَالَاخِرَةِ وَأَعَدَّ لَهُمْ عَذَاباࣰ مُّهِيناࣰ࣌', 'ࡴن ࡰلذين يوذون ࡰلله ورسوله لعنهم ࡲلله فے ࡴلدنيا والاخرة وأعد لهم عذابا مهينا࣌', NULL, 426, 'local:warsh-text.json'),
  ('warsh-33-58', 'warsh', 33, 58, 'وَالذِينَ يُوذُونَ ࡰ۬لْمُومِنِينَ وَالْمُومِنَٰتِ بِغَيْرِ مَا ࡰٜكْتَسَبُواْ فَقَدِ ࡴٜحْتَمَلُواْ بُهْتَٰناࣰ وَإِثْماࣰ مُّبِيناࣰ࣌', 'والذين يوذون ࡰلمومنين والمومنت بغير ما ࡰكتسبوا فقد ࡴحتملوا بهتنا وإثما مبينا࣌', NULL, 426, 'local:warsh-text.json'),
  ('warsh-33-59', 'warsh', 33, 59, 'يَٰٓأَيُّهَا‏ ࡰ۬لنَّبِےٓءُ قُل لِّأَزْوَٰجِكَ وَبَنَاتِكَ وَنِسَآءِ ࡴ۬لْمُومِنِينَ يُدْنِينَ عَلَيْهِنَّ مِن جَلَٰبِيبِهِنَّ࣌ ذَٰلِكَ أَدْنٜىٰٓ أَنْ يُّعْرَفْنَ فَلَا يُوذَيْنَ࣌ وَكَانَ ࡰ۬للَّهُ غَفُوراࣰ رَّحِيماࣰ࣌', 'يأيها‏ ࡰلنبےء قل لأزوجك وبناتك ونساء ࡴلمومنين يدنين عليهن من جلبيبهن࣌ ذلك أدنى أن يعرفن فلا يوذين࣌ وكان ࡰلله غفورا رحيما࣌', NULL, 426, 'local:warsh-text.json'),
  ('warsh-33-60', 'warsh', 33, 60, '۞ لَّئِن لَّمْ يَنتَهِ ࡴ۬لْمُنَٰفِقُونَ وَالذِينَ فِے قُلُوبِهِم مَّرَضࣱ وَالْمُرْجِفُونَ فِے ࡴ۬لْمَدِينَةِ لَنُغْرِيَنَّكَ بِهِمْ ثُمَّ لَا يُجَاوِرُونَكَ فِيهَآ إِلَّا قَلِيلاࣰ', 'لئن لم ينته ࡴلمنفقون والذين فے قلوبهم مرض والمرجفون فے ࡴلمدينة لنغرينك بهم ثم لا يجاورونك فيها إلا قليلا', NULL, 426, 'local:warsh-text.json'),
  ('warsh-33-61', 'warsh', 33, 61, 'مَّلْعُونِينَ࣌ أَيْنَمَا ثُقِفُوٓاْ أُخِذُواْ وَقُتِّلُواْ تَقْتِيلاࣰ࣌', 'ملعونين࣌ أينما ثقفوا أخذوا وقتلوا تقتيلا࣌', NULL, 426, 'local:warsh-text.json'),
  ('warsh-33-62', 'warsh', 33, 62, 'سُنَّةَ ࡰ۬للَّهِ فِے ࡴ۬لذِينَ خَلَوْاْ مِن قَبْلُ࣌ وَلَن تَجِدَ لِسُنَّةِ ࡴ۬للَّهِ تَبْدِيلاࣰ࣌', 'سنة ࡰلله فے ࡴلذين خلوا من قبل࣌ ولن تجد لسنة ࡴلله تبديلا࣌', NULL, 426, 'local:warsh-text.json'),
  ('warsh-33-63', 'warsh', 33, 63, 'يَسْـَٔلُكَ ࡰ۬لنَّاسُ عَنِ ࡴ۬لسَّاعَةِ࣌ قُلِ ࡴنَّمَا عِلْمُهَا عِندَ ࡰ۬للَّهِ࣌ وَمَا يُدْرِيكَ࣌ لَعَلَّ ࡰ۬لسَّاعَةَ تَكُونُ قَرِيباً࣌', 'يسلك ࡰلناس عن ࡴلساعة࣌ قل ࡴنما علمها عند ࡰلله࣌ وما يدريك࣌ لعل ࡰلساعة تكون قريبا࣌', NULL, 427, 'local:warsh-text.json'),
  ('warsh-33-64', 'warsh', 33, 64, 'ࡴنَّ ࡰ۬للَّهَ لَعَنَ ࡰ۬لْكٜـٰفِرِينَ وَأَعَدَّ لَهُمْ سَعِيراً', 'ࡴن ࡰلله لعن ࡰلكفرين وأعد لهم سعيرا', NULL, 427, 'local:warsh-text.json'),
  ('warsh-33-65', 'warsh', 33, 65, 'خَٰلِدِينَ فِيهَآ أَبَداࣰ لَّا يَجِدُونَ وَلِيّاࣰ وَلَا نَصِيراࣰ࣌', 'خلدين فيها أبدا لا يجدون وليا ولا نصيرا࣌', NULL, 427, 'local:warsh-text.json'),
  ('warsh-33-66', 'warsh', 33, 66, 'يَوْمَ تُقَلَّبُ وُجُوهُهُمْ فِے ࡴ۬لنّٜارِ يَقُولُونَ يَٰلَيْتَنَآ أَطَعْنَا ࡰ۬للَّهَ وَأَطَعْنَا ࡰ۬لرَّسُولَا࣌', 'يوم تقلب وجوههم فے ࡴلنار يقولون يليتنا أطعنا ࡰلله وأطعنا ࡰلرسولا࣌', NULL, 427, 'local:warsh-text.json'),
  ('warsh-33-67', 'warsh', 33, 67, 'وَقَالُواْ رَبَّنَآ إِنَّآ أَطَعْنَا سَادَتَنَا وَكُبَرَآءَنَا فَأَضَلُّونَا ࡰ۬لسَّبِيلَا࣌', 'وقالوا ربنا إنا أطعنا سادتنا وكبراءنا فأضلونا ࡰلسبيلا࣌', NULL, 427, 'local:warsh-text.json'),
  ('warsh-33-68', 'warsh', 33, 68, 'رَبَّنَآ ءَاتِهِمْ ضِعْفَيْنِ مِنَ ࡰ۬لْعَذَابِ وَالْعَنْهُمْ لَعْناࣰ كَثِيراࣰ࣌', 'ربنا ءاتهم ضعفين من ࡰلعذاب والعنهم لعنا كثيرا࣌', NULL, 427, 'local:warsh-text.json'),
  ('warsh-33-69', 'warsh', 33, 69, 'يَٰٓأَيُّهَا ࡰ۬لذِينَ ءَامَنُواْ لَا تَكُونُواْ كَالذِينَ ءَاذَوْاْ مُوسٜىٰ فَبَرَّأَهُ ࡲ۬للَّهُ مِمَّا قَالُواْ࣌ وَكَانَ عِندَ ࡰ۬للَّهِ وَجِيهاࣰ࣌', 'يأيها ࡰلذين ءامنوا لا تكونوا كالذين ءاذوا موسى فبرأه ࡲلله مما قالوا࣌ وكان عند ࡰلله وجيها࣌', NULL, 427, 'local:warsh-text.json'),
  ('warsh-33-70', 'warsh', 33, 70, 'يَٰٓأَيُّهَا ࡰ۬لذِينَ ءَامَنُواْ ࡲٜتَّقُواْ ࡲ۬للَّهَ وَقُولُواْ قَوْلاࣰ سَدِيداࣰ', 'يأيها ࡰلذين ءامنوا ࡲتقوا ࡲلله وقولوا قولا سديدا', NULL, 427, 'local:warsh-text.json'),
  ('warsh-33-71', 'warsh', 33, 71, 'يُصْلِحْ لَكُمُۥٓ أَعْمَٰلَكُمْ وَيَغْفِرْ لَكُمْ ذُنُوبَكُمْ࣌ وَمَنْ يُّطِعِ ࡴ۬للَّهَ وَرَسُولَهُۥ فَقَدْ فَازَ فَوْزاً عَظِيماً࣌', 'يصلح لكم أعملكم ويغفر لكم ذنوبكم࣌ ومن يطع ࡴلله ورسوله فقد فاز فوزا عظيما࣌', NULL, 427, 'local:warsh-text.json'),
  ('warsh-33-72', 'warsh', 33, 72, 'ࡴنَّا عَرَضْنَا ࡰ۬لَامَانَةَ عَلَى ࡰ۬لسَّمَٰوَٰتِ وَالَارْضِ وَالْجِبَالِ فَأَبَيْنَ أَنْ يَّحْمِلْنَهَا وَأَشْفَقْنَ مِنْهَا࣌ وَحَمَلَهَا ࡰ۬لِانسَٰنُ إِنَّهُۥ كَانَ ظَلُوماࣰ جَهُولاࣰ', 'ࡴنا عرضنا ࡰلامانة على ࡰلسموت والارض والجبال فأبين أن يحملنها وأشفقن منها࣌ وحملها ࡰلانسن إنه كان ظلوما جهولا', NULL, 427, 'local:warsh-text.json'),
  ('warsh-33-73', 'warsh', 33, 73, 'لِّيُعَذِّبَ ࡰ۬للَّهُ ࡲ۬لْمُنَٰفِقِينَ وَالْمُنَٰفِقَٰتِ وَالْمُشْرِكِينَ وَالْمُشْرِكَٰتِ وَيَتُوبَ ࡰ۬للَّهُ عَلَى ࡰ۬لْمُومِنِينَ وَالْمُومِنَٰتِ࣌ وَكَانَ ࡰ۬للَّهُ غَفُوراࣰ رَّحِيماً࣌', 'ليعذب ࡰلله ࡲلمنفقين والمنفقت والمشركين والمشركت ويتوب ࡰلله على ࡰلمومنين والمومنت࣌ وكان ࡰلله غفورا رحيما࣌', NULL, 427, 'local:warsh-text.json')
insert into public.ayahs (id, riwayah, surah_number, ayah_number, text, simple_text, juz, page, source) values
  ('warsh-34-1', 'warsh', 34, 1, 'ࡴ۬لْحَمْدُ لِلهِ ࡴ۬لذِے لَهُۥ مَا فِے ࡴ۬لسَّمَٰوَٰتِ وَمَا فِے ࡴ۬لَارْضِ࣌ وَلَهُ ࡲ۬لْحَمْدُ فِے ࡴ۬لَاخِرَةِ࣌ وَهُوَ ࡰ۬لْحَكِيمُ ࡲ۬لْخَبِيرُ࣌', 'ࡴلحمد لله ࡴلذے له ما فے ࡴلسموت وما فے ࡴلارض࣌ وله ࡲلحمد فے ࡴلاخرة࣌ وهو ࡰلحكيم ࡲلخبير࣌', NULL, 428, 'local:warsh-text.json'),
  ('warsh-34-2', 'warsh', 34, 2, 'يَعْلَمُ مَا يَلِجُ فِے ࡴ۬لَارْضِ وَمَا يَخْرُجُ مِنْهَا وَمَا يَنزِلُ مِنَ ࡰ۬لسَّمَآءِ وَمَا يَعْرُجُ فِيهَا࣌ وَهُوَ ࡰ۬لرَّحِيمُ ࡲ۬لْغَفُورُ࣌', 'يعلم ما يلج فے ࡴلارض وما يخرج منها وما ينزل من ࡰلسماء وما يعرج فيها࣌ وهو ࡰلرحيم ࡲلغفور࣌', NULL, 428, 'local:warsh-text.json'),
  ('warsh-34-3', 'warsh', 34, 3, 'وَقَالَ ࡰ۬لذِينَ كَفَرُواْ لَا تَاتِينَا ࡰ۬لسَّاعَةُ࣌ قُلْ بَلٜىٰ وَرَبِّے لَتَاتِيَنَّكُمْ࣌ عَٰلِمُ ࡲ۬لْغَيْبِ لَا يَعْزُبُ عَنْهُ مِثْقَالُ ذَرَّةࣲ فِے ࡴ۬لسَّمَٰوَٰتِ وَلَا فِے ࡴ۬لَارْضِ࣌ وَلَآ أَصْغَرُ مِن ذَٰلِكَ وَلَآ أَكْبَرُ إِلَّا فِے كِتَٰبࣲ مُّبِينࣲ', 'وقال ࡰلذين كفروا لا تاتينا ࡰلساعة࣌ قل بلى وربے لتاتينكم࣌ علم ࡲلغيب لا يعزب عنه مثقال ذرة فے ࡴلسموت ولا فے ࡴلارض࣌ ولا أصغر من ذلك ولا أكبر إلا فے كتب مبين', NULL, 428, 'local:warsh-text.json'),
  ('warsh-34-4', 'warsh', 34, 4, 'لِّيَجْزِيَ ࡰ۬لذِينَ ءَامَنُواْ وَعَمِلُواْ ࡲ۬لصَّٰلِحَٰتِ࣌ أُوْلَٰٓئِكَ لَهُم مَّغْفِرَةࣱ وَرِزْقࣱ كَرِيمࣱ࣌', 'ليجزي ࡰلذين ءامنوا وعملوا ࡲلصلحت࣌ أولئك لهم مغفرة ورزق كريم࣌', NULL, 428, 'local:warsh-text.json'),
  ('warsh-34-5', 'warsh', 34, 5, 'وَالذِينَ سَعَوْ فِےٓ ءَايَٰتِنَا مُعَٰجِزِينَ أُوْلَٰٓئِكَ لَهُمْ عَذَابࣱ مِّن رِّجْزٍ ࡰلِيمࣲ࣌', 'والذين سعو فے ءايتنا معجزين أولئك لهم عذاب من رجز ࡰليم࣌', NULL, 428, 'local:warsh-text.json'),
  ('warsh-34-6', 'warsh', 34, 6, 'وَيَرَى ࡰ۬لذِينَ أُوتُواْ ࡲ۬لْعِلْمَ ࡰ۬لذِےٓ أُنزِلَ إِلَيْكَ مِن رَّبِّكَ هُوَ ࡰ۬لْحَقَّ وَيَهْدِےٓ إِلَىٰ صِرَٰطِ ࡴ۬لْعَزِيزِ ࡴ۬لْحَمِيدِ࣌', 'ويرى ࡰلذين أوتوا ࡲلعلم ࡰلذے أنزل إليك من ربك هو ࡰلحق ويهدے إلى صرط ࡴلعزيز ࡴلحميد࣌', NULL, 428, 'local:warsh-text.json'),
  ('warsh-34-7', 'warsh', 34, 7, 'وَقَالَ ࡰ۬لذِينَ كَفَرُواْ هَلْ نَدُلُّكُمْ عَلَىٰ رَجُلࣲ يُنَبِّئُكُمُۥٓ إِذَا مُزِّقْتُمْ كُلَّ مُمَزَّقٍ ࡴنَّكُمْ لَفِے خَلْقࣲ جَدِيدٍ࣌', 'وقال ࡰلذين كفروا هل ندلكم على رجل ينبئكم إذا مزقتم كل ممزق ࡴنكم لفے خلق جديد࣌', NULL, 428, 'local:warsh-text.json'),
  ('warsh-34-8', 'warsh', 34, 8, 'ࡰفْتَرٜىٰ عَلَى ࡰ۬للَّهِ كَذِباً ࡰم بِهِۦ جِنَّةُۢ࣌ بَلِ ࡴ۬لذِينَ لَا يُومِنُونَ بِالَاخِرَةِ فِے ࡴ۬لْعَذَابِ وَالضَّلَٰلِ ࡴ۬لْبَعِيدِ࣌', 'ࡰفترى على ࡰلله كذبا ࡰم به جنة࣌ بل ࡴلذين لا يومنون بالاخرة فے ࡴلعذاب والضلل ࡴلبعيد࣌', NULL, 429, 'local:warsh-text.json'),
  ('warsh-34-9', 'warsh', 34, 9, 'أَفَلَمْ يَرَوِاْ ࡴلَىٰ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُم مِّنَ ࡰ۬لسَّمَآءِ وَالَارْضِ࣌ إِن نَّشَأْ نَخْسِفْ بِهِمُ ࡲ۬لَارْضَ أَوْ نُسْقِطْ عَلَيْهِمْ كِسْفاࣰ مِّنَ ࡰ۬لسَّمَآءِ࣌ انَّ فِے ذَٰلِكَ لَأٓيَةࣰ لِّكُلِّ عَبْدࣲ مُّنِيبࣲ࣌', 'أفلم يروا ࡴلى ما بين أيديهم وما خلفهم من ࡰلسماء والارض࣌ إن نشأ نخسف بهم ࡲلارض أو نسقط عليهم كسفا من ࡰلسماء࣌ ان فے ذلك لأية لكل عبد منيب࣌', NULL, 429, 'local:warsh-text.json'),
  ('warsh-34-10', 'warsh', 34, 10, '۞ وَلَقَدَ اٰتَيْنَا دَاوُۥدَ مِنَّا فَضْلاࣰ يَٰجِبَالُ أَوِّبِے مَعَهُۥ وَالطَّيْرَ࣌ وَأَلَنَّا لَهُ ࡲ۬لْحَدِيدَ', 'ولقد اتينا داود منا فضلا يجبال أوبے معه والطير࣌ وألنا له ࡲلحديد', NULL, 429, 'local:warsh-text.json'),
  ('warsh-34-11', 'warsh', 34, 11, 'أَنِ ࡴٜعْمَلْ سَٰبِغَٰتࣲ وَقَدِّرْ فِے ࡴ۬لسَّرْدِ࣌ وَاعْمَلُواْ صَٰلِحاً࣌ ࡴنِّے بِمَا تَعْمَلُونَ بَصِيرࣱ࣌', 'أن ࡴعمل سبغت وقدر فے ࡴلسرد࣌ واعملوا صلحا࣌ ࡴنے بما تعملون بصير࣌', NULL, 429, 'local:warsh-text.json'),
  ('warsh-34-12', 'warsh', 34, 12, 'وَلِسُلَيْمَٰنَ ࡰ۬لرِّيحَ غُدُوُّهَا شَهْرࣱ وَرَوَاحُهَا شَهْرࣱ࣌ وَأَسَلْنَا لَهُۥ عَيْنَ ࡰ۬لْقِطْرِ࣌ وَمِنَ ࡰ۬لْجِنِّ مَنْ يَّعْمَلُ بَيْنَ يَدَيْهِ بِإِذْنِ رَبِّهِۦ࣌ وَمَنْ يَّزِغْ مِنْهُمْ عَنَ ࡰمْرِنَا نُذِقْهُ مِنْ عَذَابِ ࡴ۬لسَّعِيرِ࣌', 'ولسليمن ࡰلريح غدوها شهر ورواحها شهر࣌ وأسلنا له عين ࡰلقطر࣌ ومن ࡰلجن من يعمل بين يديه بإذن ربه࣌ ومن يزغ منهم عن ࡰمرنا نذقه من عذاب ࡴلسعير࣌', NULL, 429, 'local:warsh-text.json'),
  ('warsh-34-13', 'warsh', 34, 13, 'يَعْمَلُونَ لَهُۥ مَا يَشَآءُ مِن مَّحَٰرِيبَ وَتَمَٰثِيلَ وَجِفَانࣲ كَالْجَوَابِۦ وَقُدُورࣲ رَّاسِيَٰتٍ࣌ ࡴٜعْمَلُوٓاْ ءَالَ دَاوُۥدَ࣌ شُكْراࣰ࣌ وَقَلِيلࣱ مِّنْ عِبَادِيَ ࡰ۬لشَّكُورُ࣌', 'يعملون له ما يشاء من محريب وتمثيل وجفان كالجواب وقدور راسيت࣌ ࡴعملوا ءال داود࣌ شكرا࣌ وقليل من عبادي ࡰلشكور࣌', NULL, 429, 'local:warsh-text.json'),
  ('warsh-34-14', 'warsh', 34, 14, 'فَلَمَّا قَضَيْنَا عَلَيْهِ ࡴ۬لْمَوْتَ مَا دَلَّهُمْ عَلَىٰ مَوْتِهِۦٓ إِلَّا دَآبَّةُ ࡲ۬لَارْضِ تَاكُلُ مِنسَاتَهُۥ࣌ فَلَمَّا خَرَّ تَبَيَّنَتِ ࡴ۬لْجِنُّ أَن لَّوْ كَانُواْ يَعْلَمُونَ ࡰ۬لْغَيْبَ مَا لَبِثُواْ فِے ࡴ۬لْعَذَابِ ࡴ۬لْمُهِينِ࣌', 'فلما قضينا عليه ࡴلموت ما دلهم على موته إلا دابة ࡲلارض تاكل منساته࣌ فلما خر تبينت ࡴلجن أن لو كانوا يعلمون ࡰلغيب ما لبثوا فے ࡴلعذاب ࡴلمهين࣌', NULL, 429, 'local:warsh-text.json'),
  ('warsh-34-15', 'warsh', 34, 15, 'لَقَدْ كَانَ لِسَبَإࣲ فِے مَسَٰكِنِهِمُۥٓ ءَايَةࣱ࣌ جَنَّتَٰنِ عَنْ يَّمِينࣲ وَشِمَالࣲ࣌ كُلُواْ مِن رِّزْقِ رَبِّكُمْ وَاشْكُرُواْ لَهُۥ࣌ بَلْدَةࣱ طَيِّبَةࣱ وَرَبٌّ غَفُورࣱ࣌', 'لقد كان لسبإ فے مسكنهم ءاية࣌ جنتن عن يمين وشمال࣌ كلوا من رزق ربكم واشكروا له࣌ بلدة طيبة ورب غفور࣌', NULL, 430, 'local:warsh-text.json'),
  ('warsh-34-16', 'warsh', 34, 16, 'فَأَعْرَضُواْ فَأَرْسَلْنَا عَلَيْهِمْ سَيْلَ ࡰ۬لْعَرِمِ࣌ وَبَدَّلْنَٰهُم بِجَنَّتَيْهِمْ جَنَّتَيْنِ ذَوَاتَيُ ࡳكْلٍ خَمْطࣲ وَأَثْلࣲ وَشَےْءࣲ مِّن سِدْرࣲ قَلِيلࣲ࣌', 'فأعرضوا فأرسلنا عليهم سيل ࡰلعرم࣌ وبدلنهم بجنتيهم جنتين ذواتي ࡳكل خمط وأثل وشےء من سدر قليل࣌', NULL, 430, 'local:warsh-text.json'),
  ('warsh-34-17', 'warsh', 34, 17, 'ذَٰلِكَ جَزَيْنَٰهُم بِمَا كَفَرُواْ࣌ وَهَلْ يُجَٰزٜىٰٓ إِلَّا ࡰ۬لْكَفُورُ࣌', 'ذلك جزينهم بما كفروا࣌ وهل يجزى إلا ࡰلكفور࣌', NULL, 430, 'local:warsh-text.json'),
  ('warsh-34-18', 'warsh', 34, 18, '۞ وَجَعَلْنَا بَيْنَهُمْ وَبَيْنَ ࡰ۬لْقُرَى ࡰ۬لتِے بَٰرَكْنَا فِيهَا قُرىࣰ ظَٰهِرَةࣰ وَقَدَّرْنَا فِيهَا ࡰ۬لسَّيْرَ࣌ سِيرُواْ فِيهَا لَيَالِيَ وَأَيَّاماً اٰمِنِينَ࣌', 'وجعلنا بينهم وبين ࡰلقرى ࡰلتے بركنا فيها قرى ظهرة وقدرنا فيها ࡰلسير࣌ سيروا فيها ليالي وأياما امنين࣌', NULL, 430, 'local:warsh-text.json'),
  ('warsh-34-19', 'warsh', 34, 19, 'فَقَالُواْ رَبَّنَا بَٰعِدْ بَيْنَ أَسْفٜارِنَا وَظَلَمُوٓاْ أَنفُسَهُمْ فَجَعَلْنَٰهُمُۥٓ أَحَادِيثَ وَمَزَّقْنَٰهُمْ كُلَّ مُمَزَّقٍ࣌ ࡴنَّ فِے ذَٰلِكَ لَأٓيَٰتࣲ لِّكُلِّ صَبّٜارࣲ شَكُورࣲ࣌', 'فقالوا ربنا بعد بين أسفارنا وظلموا أنفسهم فجعلنهم أحاديث ومزقنهم كل ممزق࣌ ࡴن فے ذلك لأيت لكل صبار شكور࣌', NULL, 430, 'local:warsh-text.json'),
  ('warsh-34-20', 'warsh', 34, 20, 'وَلَقَدْ صَدَقَ عَلَيْهِمُۥٓ إِبْلِيسُ ظَنَّهُۥ فَاتَّبَعُوهُ إِلَّا فَرِيقاࣰ مِّنَ ࡰ۬لْمُومِنِينَ࣌', 'ولقد صدق عليهم إبليس ظنه فاتبعوه إلا فريقا من ࡰلمومنين࣌', NULL, 430, 'local:warsh-text.json'),
  ('warsh-34-21', 'warsh', 34, 21, 'وَمَا كَانَ لَهُۥ عَلَيْهِم مِّن سُلْطَٰنٍ ࡴلَّا لِنَعْلَمَ مَنْ يُّومِنُ بِالَاخِرَةِ مِمَّنْ هُوَ مِنْهَا فِے شَكࣲّ࣌ وَرَبُّكَ عَلَىٰ كُلِّ شَےْءٍ حَفِيظࣱ࣌', 'وما كان له عليهم من سلطن ࡴلا لنعلم من يومن بالاخرة ممن هو منها فے شك࣌ وربك على كل شےء حفيظ࣌', NULL, 430, 'local:warsh-text.json'),
  ('warsh-34-22', 'warsh', 34, 22, 'قُلُ ࡲ࢈دْعُواْ ࡲ۬لذِينَ زَعَمْتُم مِّن دُونِ ࡴ۬للَّهِ࣌ لَا يَمْلِكُونَ مِثْقَالَ ذَرَّةࣲ فِے ࡴ۬لسَّمَٰوَٰتِ وَلَا فِے ࡴ۬لَارْضِ࣌ وَمَا لَهُمْ فِيهِمَا مِن شِرْكࣲ࣌ وَمَا لَهُۥ مِنْهُم مِّن ظَهِيرࣲ࣌', 'قل ࡲ࢈دعوا ࡲلذين زعمتم من دون ࡴلله࣌ لا يملكون مثقال ذرة فے ࡴلسموت ولا فے ࡴلارض࣌ وما لهم فيهما من شرك࣌ وما له منهم من ظهير࣌', NULL, 430, 'local:warsh-text.json'),
  ('warsh-34-23', 'warsh', 34, 23, 'وَلَا تَنفَعُ ࡲ۬لشَّفَٰعَةُ عِندَهُۥٓ إِلَّا لِمَنَ ࡰذِنَ لَهُۥ࣌ حَتَّىٰٓ إِذَا فُزِّعَ عَن قُلُوبِهِمْ قَالُواْ مَاذَا قَالَ رَبُّكُمْ قَالُواْ ࡲ۬لْحَقَّ࣌ وَهُوَ ࡰ۬لْعَلِيُّ ࡲ۬لْكَبِيرُ࣌', 'ولا تنفع ࡲلشفعة عنده إلا لمن ࡰذن له࣌ حتى إذا فزع عن قلوبهم قالوا ماذا قال ربكم قالوا ࡲلحق࣌ وهو ࡰلعلي ࡲلكبير࣌', NULL, 431, 'local:warsh-text.json'),
  ('warsh-34-24', 'warsh', 34, 24, '۞ قُلْ مَنْ يَّرْزُقُكُم مِّنَ ࡰ۬لسَّمَٰوَٰتِ وَالَارْضِ قُلِ ࡴ۬للَّهُ࣌ وَإِنَّآ أَوِ ࡴيَّاكُمْ لَعَلَىٰ هُدىً ࡰوْ فِے ضَلَٰلࣲ مُّبِينࣲ࣌', 'قل من يرزقكم من ࡰلسموت والارض قل ࡴلله࣌ وإنا أو ࡴياكم لعلى هدى ࡰو فے ضلل مبين࣌', NULL, 431, 'local:warsh-text.json'),
  ('warsh-34-25', 'warsh', 34, 25, 'قُل لَّا تُسْـَٔلُونَ عَمَّآ أَجْرَمْنَا وَلَا نُسْـَٔلُ عَمَّا تَعْمَلُونَ࣌', 'قل لا تسلون عما أجرمنا ولا نسل عما تعملون࣌', NULL, 431, 'local:warsh-text.json'),
  ('warsh-34-26', 'warsh', 34, 26, 'قُلْ يَجْمَعُ بَيْنَنَا رَبُّنَا ثُمَّ يَفْتَحُ بَيْنَنَا بِالْحَقِّ࣌ وَهُوَ ࡰ۬لْفَتَّاحُ ࡲ۬لْعَلِيمُ࣌', 'قل يجمع بيننا ربنا ثم يفتح بيننا بالحق࣌ وهو ࡰلفتاح ࡲلعليم࣌', NULL, 431, 'local:warsh-text.json'),
  ('warsh-34-27', 'warsh', 34, 27, 'قُلَ ࡰرُونِيَ ࡰ۬لذِينَ أَلْحَقْتُم بِهِۦ شُرَكَآءَ كَلَّا࣌ بَلْ هُوَ ࡰ۬للَّهُ ࡲ۬لْعَزِيزُ ࡲ۬لْحَكِيمُ࣌', 'قل ࡰروني ࡰلذين ألحقتم به شركاء كلا࣌ بل هو ࡰلله ࡲلعزيز ࡲلحكيم࣌', NULL, 431, 'local:warsh-text.json'),
  ('warsh-34-28', 'warsh', 34, 28, 'وَمَآ أَرْسَلْنَٰكَ إِلَّا كَآفَّةࣰ لِّلنَّاسِ بَشِيراࣰ وَنَذِيراࣰ࣌ وَلَٰكِنَّ أَكْثَرَ ࡰ۬لنَّاسِ لَا يَعْلَمُونَ࣌', 'وما أرسلنك إلا كافة للناس بشيرا ونذيرا࣌ ولكن أكثر ࡰلناس لا يعلمون࣌', NULL, 431, 'local:warsh-text.json'),
  ('warsh-34-29', 'warsh', 34, 29, 'وَيَقُولُونَ مَتٜىٰ هَٰذَا ࡰ۬لْوَعْدُ إِن كُنتُمْ صَٰدِقِينَ࣌', 'ويقولون متى هذا ࡰلوعد إن كنتم صدقين࣌', NULL, 431, 'local:warsh-text.json'),
  ('warsh-34-30', 'warsh', 34, 30, 'قُل لَّكُم مِّيعَادُ يَوْمࣲ لَّا تَسْتَٰخِرُونَ عَنْهُ سَاعَةࣰ وَلَا تَسْتَقْدِمُونَ࣌', 'قل لكم ميعاد يوم لا تستخرون عنه ساعة ولا تستقدمون࣌', NULL, 431, 'local:warsh-text.json'),
  ('warsh-34-31', 'warsh', 34, 31, 'وَقَالَ ࡰ۬لذِينَ كَفَرُواْ لَن نُّومِنَ بِهَٰذَا ࡰ۬لْقُرْءَانِ وَلَا بِالذِے بَيْنَ يَدَيْهِ࣌ وَلَوْ تَرٜىٰٓ إِذِ ࡴ۬لظَّٰلِمُونَ مَوْقُوفُونَ عِندَ رَبِّهِمْ يَرْجِعُ بَعْضُهُمُۥٓ إِلَىٰ بَعْضٍ ࡴ۬لْقَوْلَ࣌ يَقُولُ ࡲ۬لذِينَ ࡸَسْتُضْعِفُواْ لِلذِينَ ࡰٜسْتَكْبَرُواْ لَوْلَآ أَنتُمْ لَكُنَّا مُومِنِينَ࣌', 'وقال ࡰلذين كفروا لن نومن بهذا ࡰلقرءان ولا بالذے بين يديه࣌ ولو ترى إذ ࡴلظلمون موقوفون عند ربهم يرجع بعضهم إلى بعض ࡴلقول࣌ يقول ࡲلذين ࡸستضعفوا للذين ࡰستكبروا لولا أنتم لكنا مومنين࣌', NULL, 431, 'local:warsh-text.json'),
  ('warsh-34-32', 'warsh', 34, 32, 'قَالَ ࡰ۬لذِينَ ࡰٜسْتَكْبَرُواْ لِلذِينَ ࡸَسْتُضْعِفُوٓاْ أَنَحْنُ صَدَدْنَٰكُمْ عَنِ ࡴ۬لْهُدٜىٰ بَعْدَ إِذْ جَآءَكُم بَلْ كُنتُم مُّجْرِمِينَ࣌', 'قال ࡰلذين ࡰستكبروا للذين ࡸستضعفوا أنحن صددنكم عن ࡴلهدى بعد إذ جاءكم بل كنتم مجرمين࣌', NULL, 432, 'local:warsh-text.json'),
  ('warsh-34-33', 'warsh', 34, 33, 'وَقَالَ ࡰ۬لذِينَ ࡸَسْتُضْعِفُواْ لِلذِينَ ࡰٜسْتَكْبَرُواْ بَلْ مَكْرُ ࡲ۬ليْلِ وَالنَّهٜارِ إِذْ تَامُرُونَنَآ أَن نَّكْفُرَ بِاللَّهِ وَنَجْعَلَ لَهُۥٓ أَندَاداࣰ࣌ وَأَسَرُّواْ ࡲ۬لنَّدَامَةَ لَمَّا رَأَوُاْ ࡲ۬لْعَذَابَ࣌ وَجَعَلْنَا ࡰ۬لَاغْلَٰلَ فِےٓ أَعْنَاقِ ࡴ۬لذِينَ كَفَرُواْ࣌ هَلْ يُجْزَوْنَ إِلَّا مَا كَانُواْ يَعْمَلُونَ࣌', 'وقال ࡰلذين ࡸستضعفوا للذين ࡰستكبروا بل مكر ࡲليل والنهار إذ تامروننا أن نكفر بالله ونجعل له أندادا࣌ وأسروا ࡲلندامة لما رأوا ࡲلعذاب࣌ وجعلنا ࡰلاغلل فے أعناق ࡴلذين كفروا࣌ هل يجزون إلا ما كانوا يعملون࣌', NULL, 432, 'local:warsh-text.json'),
  ('warsh-34-34', 'warsh', 34, 34, 'وَمَآ أَرْسَلْنَا فِے قَرْيَةࣲ مِّن نَّذِيرٍ ࡴلَّا قَالَ مُتْرَفُوهَآ إِنَّا بِمَآ أُرْسِلْتُم بِهِۦ كَٰفِرُونَ࣌', 'وما أرسلنا فے قرية من نذير ࡴلا قال مترفوها إنا بما أرسلتم به كفرون࣌', NULL, 432, 'local:warsh-text.json'),
  ('warsh-34-35', 'warsh', 34, 35, 'وَقَالُواْ نَحْنُ أَكْثَرُ أَمْوَٰلاࣰ وَأَوْلَٰداࣰ وَمَا نَحْنُ بِمُعَذَّبِينَ࣌', 'وقالوا نحن أكثر أمولا وأولدا وما نحن بمعذبين࣌', NULL, 432, 'local:warsh-text.json'),
  ('warsh-34-36', 'warsh', 34, 36, 'قُلِ ࡴنَّ رَبِّے يَبْسُطُ ࡲ۬لرِّزْقَ لِمَنْ يَّشَآءُ وَيَقْدِرُ࣌ وَلَٰكِنَّ أَكْثَرَ ࡰ۬لنَّاسِ لَا يَعْلَمُونَ࣌', 'قل ࡴن ربے يبسط ࡲلرزق لمن يشاء ويقدر࣌ ولكن أكثر ࡰلناس لا يعلمون࣌', NULL, 432, 'local:warsh-text.json'),
  ('warsh-34-37', 'warsh', 34, 37, '۞ وَمَآ أَمْوَٰلُكُمْ وَلَآ أَوْلَٰدُكُم بِالتِے تُقَرِّبُكُمْ عِندَنَا زُلْفٜىٰٓ إِلَّا مَنَ اٰمَنَ وَعَمِلَ صَٰلِحاࣰ فَأُوْلَٰٓئِكَ لَهُمْ جَزَآءُ ࡲ۬لضِّعْفِ بِمَا عَمِلُواْ وَهُمْ فِے ࡴ۬لْغُرُفَٰتِ ءَامِنُونَ࣌', 'وما أمولكم ولا أولدكم بالتے تقربكم عندنا زلفى إلا من امن وعمل صلحا فأولئك لهم جزاء ࡲلضعف بما عملوا وهم فے ࡴلغرفت ءامنون࣌', NULL, 432, 'local:warsh-text.json'),
  ('warsh-34-38', 'warsh', 34, 38, 'وَالذِينَ يَسْعَوْنَ فِےٓ ءَايَٰتِنَا مُعَٰجِزِينَ أُوْلَٰٓئِكَ فِے ࡴ۬لْعَذَابِ مُحْضَرُونَ࣌', 'والذين يسعون فے ءايتنا معجزين أولئك فے ࡴلعذاب محضرون࣌', NULL, 432, 'local:warsh-text.json'),
  ('warsh-34-39', 'warsh', 34, 39, 'قُلِ ࡴنَّ رَبِّے يَبْسُطُ ࡲ۬لرِّزْقَ لِمَنْ يَّشَآءُ مِنْ عِبَادِهِۦ وَيَقْدِرُ لَهُۥ࣌ وَمَآ أَنفَقْتُم مِّن شَےْءࣲ فَهُوَ يُخْلِفُهُۥ࣌ وَهُوَ خَيْرُ ࡲ۬لرَّٰزِقِينَ࣌', 'قل ࡴن ربے يبسط ࡲلرزق لمن يشاء من عباده ويقدر له࣌ وما أنفقتم من شےء فهو يخلفه࣌ وهو خير ࡲلرزقين࣌', NULL, 432, 'local:warsh-text.json'),
  ('warsh-34-40', 'warsh', 34, 40, 'وَيَوْمَ نَحْشُرُهُمْ جَمِيعاࣰ ثُمَّ نَقُولُ لِلْمَلَٰٓئِكَةِ أَهَٰٓؤُلَآءِ ايَّاكُمْ كَانُواْ يَعْبُدُونَ࣌', 'ويوم نحشرهم جميعا ثم نقول للملئكة أهؤلاء اياكم كانوا يعبدون࣌', NULL, 433, 'local:warsh-text.json'),
  ('warsh-34-41', 'warsh', 34, 41, 'قَالُواْ سُبْحَٰنَكَ أَنتَ وَلِيُّنَا مِن دُونِهِم࣌ بَلْ كَانُواْ يَعْبُدُونَ ࡰ۬لْجِنَّ࣌ أَكْثَرُهُم بِهِم مُّومِنُونَ࣌', 'قالوا سبحنك أنت ولينا من دونهم࣌ بل كانوا يعبدون ࡰلجن࣌ أكثرهم بهم مومنون࣌', NULL, 433, 'local:warsh-text.json'),
  ('warsh-34-42', 'warsh', 34, 42, 'فَالْيَوْمَ لَا يَمْلِكُ بَعْضُكُمْ لِبَعْضࣲ نَّفْعاࣰ وَلَا ضَرّاࣰ وَنَقُولُ لِلذِينَ ظَلَمُواْ ذُوقُواْ عَذَابَ ࡰ۬لنّٜارِ ࡴ۬لتِے كُنتُم بِهَا تُكَذِّبُونَ࣌', 'فاليوم لا يملك بعضكم لبعض نفعا ولا ضرا ونقول للذين ظلموا ذوقوا عذاب ࡰلنار ࡴلتے كنتم بها تكذبون࣌', NULL, 433, 'local:warsh-text.json'),
  ('warsh-34-43', 'warsh', 34, 43, 'وَإِذَا تُتْلٜىٰ عَلَيْهِمُۥٓ ءَايَٰتُنَا بَيِّنَٰتࣲ قَالُواْ مَا هَٰذَآ إِلَّا رَجُلࣱ يُرِيدُ أَنْ يَّصُدَّكُمْ عَمَّا كَانَ يَعْبُدُ ءَابَآؤُكُمْ وَقَالُواْ مَا هَٰذَآ إِلَّآ إِفْكࣱ مُّفْتَرىࣰ࣌ وَقَالَ ࡰ۬لذِينَ كَفَرُواْ لِلْحَقِّ لَمَّا جَآءَهُمُۥٓ إِنْ هَٰذَآ إِلَّا سِحْرࣱ مُّبِينࣱ࣌', 'وإذا تتلى عليهم ءايتنا بينت قالوا ما هذا إلا رجل يريد أن يصدكم عما كان يعبد ءاباؤكم وقالوا ما هذا إلا إفك مفترى࣌ وقال ࡰلذين كفروا للحق لما جاءهم إن هذا إلا سحر مبين࣌', NULL, 433, 'local:warsh-text.json'),
  ('warsh-34-44', 'warsh', 34, 44, 'وَمَآ ءَاتَيْنَٰهُم مِّن كُتُبࣲ يَدْرُسُونَهَا࣌ وَمَآ أَرْسَلْنَآ إِلَيْهِمْ قَبْلَكَ مِن نَّذِيرࣲ࣌', 'وما ءاتينهم من كتب يدرسونها࣌ وما أرسلنا إليهم قبلك من نذير࣌', NULL, 433, 'local:warsh-text.json'),
  ('warsh-34-45', 'warsh', 34, 45, 'وَكَذَّبَ ࡰ۬لذِينَ مِن قَبْلِهِمْ وَمَا بَلَغُواْ مِعْشَارَ مَآ ءَاتَيْنَٰهُمْ࣌ فَكَذَّبُواْ رُسُلِے࣌ فَكَيْفَ كَانَ نَكِيرِۦ࣌', 'وكذب ࡰلذين من قبلهم وما بلغوا معشار ما ءاتينهم࣌ فكذبوا رسلے࣌ فكيف كان نكير࣌', NULL, 433, 'local:warsh-text.json'),
  ('warsh-34-46', 'warsh', 34, 46, '۞ قُلِ ࡴنَّمَآ أَعِظُكُم بِوَٰحِدَةٍ࣌ ࡰن تَقُومُواْ لِلهِ مَثْنٜىٰ وَفُرَٰدٜىٰ ثُمَّ تَتَفَكَّرُواْ࣌ مَا بِصَٰحِبِكُم مِّن جِنَّةٍ࣌ ࡴنْ هُوَ إِلَّا نَذِيرࣱ لَّكُم بَيْنَ يَدَےْ عَذَابࣲ شَدِيدࣲ࣌', 'قل ࡴنما أعظكم بوحدة࣌ ࡰن تقوموا لله مثنى وفردى ثم تتفكروا࣌ ما بصحبكم من جنة࣌ ࡴن هو إلا نذير لكم بين يدے عذاب شديد࣌', NULL, 433, 'local:warsh-text.json'),
  ('warsh-34-47', 'warsh', 34, 47, 'قُلْ مَا سَأَلْتُكُم مِّنَ ࡰجْرࣲ فَهُوَ لَكُمُۥٓ࣌ إِنَ ࡰجْرِيَ إِلَّا عَلَى ࡰ۬للَّهِ࣌ وَهُوَ عَلَىٰ كُلِّ شَےْءࣲ شَهِيدࣱ࣌', 'قل ما سألتكم من ࡰجر فهو لكم࣌ إن ࡰجري إلا على ࡰلله࣌ وهو على كل شےء شهيد࣌', NULL, 433, 'local:warsh-text.json'),
  ('warsh-34-48', 'warsh', 34, 48, 'قُلِ ࡴنَّ رَبِّے يَقْذِفُ بِالْحَقِّ࣌ عَلَّٰمُ ࡲ۬لْغُيُوبِ࣌', 'قل ࡴن ربے يقذف بالحق࣌ علم ࡲلغيوب࣌', NULL, 433, 'local:warsh-text.json'),
  ('warsh-34-49', 'warsh', 34, 49, 'قُلْ جَآءَ ࡰ۬لْحَقُّ وَمَا يُبْدِۓُ ࡲ۬لْبَٰطِلُ وَمَا يُعِيدُ࣌', 'قل جاء ࡰلحق وما يبدے ࡲلبطل وما يعيد࣌', NULL, 434, 'local:warsh-text.json'),
  ('warsh-34-50', 'warsh', 34, 50, 'قُلِ ࡴن ضَلَلْتُ فَإِنَّمَآ أَضِلُّ عَلَىٰ نَفْسِے وَإِنِ ࡴٜهْتَدَيْتُ فَبِمَا يُوحِےٓ إِلَيَّ رَبِّيَ࣌ إِنَّهُۥ سَمِيعࣱ قَرِيبࣱ࣌', 'قل ࡴن ضللت فإنما أضل على نفسے وإن ࡴهتديت فبما يوحے إلي ربي࣌ إنه سميع قريب࣌', NULL, 434, 'local:warsh-text.json'),
  ('warsh-34-51', 'warsh', 34, 51, 'وَلَوْ تَرٜىٰٓ إِذْ فَزِعُواْ فَلَا فَوْتَ وَأُخِذُواْ مِن مَّكَانࣲ قَرِيبࣲ࣌', 'ولو ترى إذ فزعوا فلا فوت وأخذوا من مكان قريب࣌', NULL, 434, 'local:warsh-text.json'),
  ('warsh-34-52', 'warsh', 34, 52, 'وَقَالُوٓاْ ءَامَنَّا بِهِۦ࣌ وَأَنّٜىٰ لَهُمُ ࡲ۬لتَّنَاوُشُ مِن مَّكَانِۢ بَعِيدࣲ', 'وقالوا ءامنا به࣌ وأنى لهم ࡲلتناوش من مكان بعيد', NULL, 434, 'local:warsh-text.json'),
  ('warsh-34-53', 'warsh', 34, 53, 'وَقَدْ كَفَرُواْ بِهِۦ مِن قَبْلُ࣌ وَيَقْذِفُونَ بِالْغَيْبِ مِن مَّكَانِۢ بَعِيدࣲ࣌', 'وقد كفروا به من قبل࣌ ويقذفون بالغيب من مكان بعيد࣌', NULL, 434, 'local:warsh-text.json'),
  ('warsh-34-54', 'warsh', 34, 54, 'وَحِيلَ بَيْنَهُمْ وَبَيْنَ مَا يَشْتَهُونَ كَمَا فُعِلَ بِأَشْيَاعِهِم مِّن قَبْلُ إِنَّهُمْ كَانُواْ فِے شَكࣲّ مُّرِيبٍ࣌', 'وحيل بينهم وبين ما يشتهون كما فعل بأشياعهم من قبل إنهم كانوا فے شك مريب࣌', NULL, 434, 'local:warsh-text.json'),
  ('warsh-35-1', 'warsh', 35, 1, 'ࡴ۬لْحَمْدُ لِلهِ فَاطِرِ ࡴ۬لسَّمَٰوَٰتِ وَالَارْضِ جَاعِلِ ࡴ۬لْمَلَٰٓئِكَةِ رُسُلاً ࡳوْلِےٓ أَجْنِحَةࣲ مَّثْنٜىٰ وَثُلَٰثَ وَرُبَٰعَ࣌ يَزِيدُ فِے ࡴ۬لْخَلْقِ مَا يَشَآءُ࣌ ࡹِنَّ ࡰ۬للَّهَ عَلَىٰ كُلِّ شَےْءࣲ قَدِيرࣱ࣌', 'ࡴلحمد لله فاطر ࡴلسموت والارض جاعل ࡴلملئكة رسلا ࡳولے أجنحة مثنى وثلث وربع࣌ يزيد فے ࡴلخلق ما يشاء࣌ ࡹن ࡰلله على كل شےء قدير࣌', NULL, 434, 'local:warsh-text.json'),
  ('warsh-35-2', 'warsh', 35, 2, 'مَّا يَفْتَحِ ࡴ۬للَّهُ لِلنَّاسِ مِن رَّحْمَةࣲ فَلَا مُمْسِكَ لَهَا࣌ وَمَا يُمْسِكْ فَلَا مُرْسِلَ لَهُۥ مِنۢ بَعْدِهِۦ࣌ وَهُوَ ࡰ۬لْعَزِيزُ ࡲ۬لْحَكِيمُ࣌', 'ما يفتح ࡴلله للناس من رحمة فلا ممسك لها࣌ وما يمسك فلا مرسل له من بعده࣌ وهو ࡰلعزيز ࡲلحكيم࣌', NULL, 434, 'local:warsh-text.json'),
  ('warsh-35-3', 'warsh', 35, 3, 'يَٰٓأَيُّهَا ࡰ۬لنَّاسُ ࡲ࢈ذْكُرُواْ نِعْمَتَ ࡰ۬للَّهِ عَلَيْكُمْ࣌ هَلْ مِنْ خَٰلِقٍ غَيْرُ ࡲ۬للَّهِ يَرْزُقُكُم مِّنَ ࡰ۬لسَّمَآءِ وَالَارْضِ࣌ لَآ إِلَٰهَ إِلَّا هُوَ࣌ فَأَنّٜىٰ تُوفَكُونَ࣌', 'يأيها ࡰلناس ࡲ࢈ذكروا نعمت ࡰلله عليكم࣌ هل من خلق غير ࡲلله يرزقكم من ࡰلسماء والارض࣌ لا إله إلا هو࣌ فأنى توفكون࣌', NULL, 434, 'local:warsh-text.json'),
  ('warsh-35-4', 'warsh', 35, 4, 'وَإِنْ يُّكَذِّبُوكَ فَقَدْ كُذِّبَتْ رُسُلࣱ مِّن قَبْلِكَ࣌ وَإِلَى ࡰ۬للَّهِ تُرْجَعُ ࡲ۬لُامُورُ࣌', 'وإن يكذبوك فقد كذبت رسل من قبلك࣌ وإلى ࡰلله ترجع ࡲلامور࣌', NULL, 435, 'local:warsh-text.json'),
  ('warsh-35-5', 'warsh', 35, 5, 'يَٰٓأَيُّهَا ࡰ۬لنَّاسُ إِنَّ وَعْدَ ࡰ۬للَّهِ حَقࣱّ࣌ فَلَا تَغُرَّنَّكُمُ ࡲ۬لْحَيَوٰةُ ࡲ۬لدُّنْيٜا࣌ وَلَا يَغُرَّنَّكُم بِاللَّهِ ࡴ۬لْغَرُورُ࣌', 'يأيها ࡰلناس إن وعد ࡰلله حق࣌ فلا تغرنكم ࡲلحيوة ࡲلدنيا࣌ ولا يغرنكم بالله ࡴلغرور࣌', NULL, 435, 'local:warsh-text.json'),
  ('warsh-35-6', 'warsh', 35, 6, 'إِنَّ ࡰ۬لشَّيْطَٰنَ لَكُمْ عَدُوࣱّ فَاتَّخِذُوهُ عَدُوّاً࣌ ࡴنَّمَا يَدْعُواْ حِزْبَهُۥ لِيَكُونُواْ مِنَ ࡰصْحَٰبِ ࡴ۬لسَّعِيرِ࣌', 'إن ࡰلشيطن لكم عدو فاتخذوه عدوا࣌ ࡴنما يدعوا حزبه ليكونوا من ࡰصحب ࡴلسعير࣌', NULL, 435, 'local:warsh-text.json'),
  ('warsh-35-7', 'warsh', 35, 7, 'ࡴ۬لذِينَ كَفَرُواْ لَهُمْ عَذَابࣱ شَدِيدࣱ࣌ وَالذِينَ ءَامَنُواْ وَعَمِلُواْ ࡲ۬لصَّٰلِحَٰتِ لَهُم مَّغْفِرَةࣱ وَأَجْرࣱ كَبِيرٌ࣌', 'ࡴلذين كفروا لهم عذاب شديد࣌ والذين ءامنوا وعملوا ࡲلصلحت لهم مغفرة وأجر كبير࣌', NULL, 435, 'local:warsh-text.json'),
  ('warsh-35-8', 'warsh', 35, 8, '۞ ࡰفَمَن زُيِّنَ لَهُۥ سُوٓءُ عَمَلِهِۦ فَرٜءٜاهُ حَسَناࣰ࣌ فَإِنَّ ࡰ۬للَّهَ يُضِلُّ مَنْ يَّشَآءُ وَيَهْدِے مَنْ يَّشَآءُ࣌ فَلَا تَذْهَبْ نَفْسُكَ عَلَيْهِمْ حَسَرَٰتٍ࣌ ࡴنَّ ࡰ۬للَّهَ عَلِيمُۢ بِمَا يَصْنَعُونَ࣌', 'ࡰفمن زين له سوء عمله فرءاه حسنا࣌ فإن ࡰلله يضل من يشاء ويهدے من يشاء࣌ فلا تذهب نفسك عليهم حسرت࣌ ࡴن ࡰلله عليم بما يصنعون࣌', NULL, 435, 'local:warsh-text.json'),
  ('warsh-35-9', 'warsh', 35, 9, 'وَاللَّهُ ࡲ۬لذِےٓ أَرْسَلَ ࡰ۬لرِّيَٰحَ فَتُثِيرُ سَحَاباࣰ فَسُقْنَٰهُ إِلَىٰ بَلَدࣲ مَّيِّتࣲ فَأَحْيَيْنَا بِهِ ࡴ۬لَارْضَ بَعْدَ مَوْتِهَا࣌ كَذَٰلِكَ ࡰ۬لنُّشُورُ࣌', 'والله ࡲلذے أرسل ࡰلريح فتثير سحابا فسقنه إلى بلد ميت فأحيينا به ࡴلارض بعد موتها࣌ كذلك ࡰلنشور࣌', NULL, 435, 'local:warsh-text.json'),
  ('warsh-35-10', 'warsh', 35, 10, 'مَن كَانَ يُرِيدُ ࡲ۬لْعِزَّةَ فَلِلهِ ࡴ۬لْعِزَّةُ جَمِيعاً࣌ ࡴلَيْهِ يَصْعَدُ ࡲ۬لْكَلِمُ ࡲ۬لطَّيِّبُ࣌ وَالْعَمَلُ ࡲ۬لصَّٰلِحُ يَرْفَعُهُۥ࣌ وَالذِينَ يَمْكُرُونَ ࡰ۬لسَّيِّـَٔاتِ لَهُمْ عَذَابࣱ شَدِيدࣱ࣌ وَمَكْرُ أُوْلَٰٓئِكَ هُوَ يَبُورُ࣌', 'من كان يريد ࡲلعزة فلله ࡴلعزة جميعا࣌ ࡴليه يصعد ࡲلكلم ࡲلطيب࣌ والعمل ࡲلصلح يرفعه࣌ والذين يمكرون ࡰلسيات لهم عذاب شديد࣌ ومكر أولئك هو يبور࣌', NULL, 435, 'local:warsh-text.json'),
  ('warsh-35-11', 'warsh', 35, 11, 'وَاللَّهُ خَلَقَكُم مِّن تُرَابࣲ ثُمَّ مِن نُّطْفَةࣲ ثُمَّ جَعَلَكُمُۥٓ أَزْوَٰجاࣰ࣌ وَمَا تَحْمِلُ مِنُ ࡳنثٜىٰ وَلَا تَضَعُ إِلَّا بِعِلْمِهِۦ࣌ وَمَا يُعَمَّرُ مِن مُّعَمَّرࣲ وَلَا يُنقَصُ مِنْ عُمُرِهِۦٓ إِلَّا فِے كِتَٰبٍ࣌ ࡴنَّ ذَٰلِكَ عَلَى ࡰ۬للَّهِ يَسِيرࣱ࣌', 'والله خلقكم من تراب ثم من نطفة ثم جعلكم أزوجا࣌ وما تحمل من ࡳنثى ولا تضع إلا بعلمه࣌ وما يعمر من معمر ولا ينقص من عمره إلا فے كتب࣌ ࡴن ذلك على ࡰلله يسير࣌', NULL, 435, 'local:warsh-text.json'),
  ('warsh-35-12', 'warsh', 35, 12, 'وَمَا يَسْتَوِے ࡴ۬لْبَحْرَٰنِ࣌ هَٰذَا عَذْبࣱ فُرَاتࣱ سَآئِغࣱ شَرَابُهُۥ وَهَٰذَا مِلْحٌ ࡳجَاجࣱ࣌ وَمِن كُلࣲّ تَاكُلُونَ لَحْماࣰ طَرِيّاࣰ وَتَسْتَخْرِجُونَ حِلْيَةࣰ تَلْبَسُونَهَا࣌ وَتَرَى ࡰ۬لْفُلْكَ فِيهِ مَوَاخِرَ لِتَبْتَغُواْ مِن فَضْلِهِۦ وَلَعَلَّكُمْ تَشْكُرُونَ࣌', 'وما يستوے ࡴلبحرن࣌ هذا عذب فرات سائغ شرابه وهذا ملح ࡳجاج࣌ ومن كل تاكلون لحما طريا وتستخرجون حلية تلبسونها࣌ وترى ࡰلفلك فيه مواخر لتبتغوا من فضله ولعلكم تشكرون࣌', NULL, 436, 'local:warsh-text.json'),
  ('warsh-35-13', 'warsh', 35, 13, 'يُولِجُ ࡲ۬ليْلَ فِے ࡴ۬لنَّهٜارِ وَيُولِجُ ࡲ۬لنَّهَارَ فِے ࡴ۬ليْلِ࣌ وَسَخَّرَ ࡰ۬لشَّمْسَ وَالْقَمَرَ࣌ كُلࣱّ يَجْرِے لِأَجَلࣲ مُّسَمّىࣰ࣌ ذَٰلِكُمُ ࡲ۬للَّهُ رَبُّكُمْ لَهُ ࡲ۬لْمُلْكُ࣌ وَالذِينَ تَدْعُونَ مِن دُونِهِۦ مَا يَمْلِكُونَ مِن قِطْمِيرٍ࣌', 'يولج ࡲليل فے ࡴلنهار ويولج ࡲلنهار فے ࡴليل࣌ وسخر ࡰلشمس والقمر࣌ كل يجرے لأجل مسمى࣌ ذلكم ࡲلله ربكم له ࡲلملك࣌ والذين تدعون من دونه ما يملكون من قطمير࣌', NULL, 436, 'local:warsh-text.json'),
  ('warsh-35-14', 'warsh', 35, 14, 'ࡴن تَدْعُوهُمْ لَا يَسْمَعُواْ دُعَآءَكُمْ وَلَوْ سَمِعُواْ مَا ࡰٜسْتَجَابُواْ لَكُمْ࣌ وَيَوْمَ ࡰ۬لْقِيَٰمَةِ يَكْفُرُونَ بِشِرْكِكُمْ࣌ وَلَا يُنَبِّئُكَ مِثْلُ خَبِيرࣲ࣌', 'ࡴن تدعوهم لا يسمعوا دعاءكم ولو سمعوا ما ࡰستجابوا لكم࣌ ويوم ࡰلقيمة يكفرون بشرككم࣌ ولا ينبئك مثل خبير࣌', NULL, 436, 'local:warsh-text.json'),
  ('warsh-35-15', 'warsh', 35, 15, '۞ يَٰٓأَيُّهَا ࡰ۬لنَّاسُ أَنتُمُ ࡲ۬لْفُقَرَآءُ ࡹِلَى ࡰ۬للَّهِ࣌ وَاللَّهُ هُوَ ࡰ۬لْغَنِيُّ ࡲ۬لْحَمِيدُ࣌', 'يأيها ࡰلناس أنتم ࡲلفقراء ࡹلى ࡰلله࣌ والله هو ࡰلغني ࡲلحميد࣌', NULL, 436, 'local:warsh-text.json'),
  ('warsh-35-16', 'warsh', 35, 16, 'إِنْ يَّشَأْ يُذْهِبْكُمْ وَيَاتِ بِخَلْقࣲ جَدِيدࣲ࣌', 'إن يشأ يذهبكم ويات بخلق جديد࣌', NULL, 436, 'local:warsh-text.json'),
  ('warsh-35-17', 'warsh', 35, 17, 'وَمَا ذَٰلِكَ عَلَى ࡰ۬للَّهِ بِعَزِيزࣲ࣌', 'وما ذلك على ࡰلله بعزيز࣌', NULL, 436, 'local:warsh-text.json'),
  ('warsh-35-18', 'warsh', 35, 18, 'وَلَا تَزِرُ وَازِرَةࣱ وِزْرَ أُخْرٜىٰ࣌ وَإِن تَدْعُ مُثْقَلَةٌ ࡴلَىٰ حِمْلِهَا لَا يُحْمَلْ مِنْهُ شَےْءࣱ وَلَوْ كَانَ ذَا قُرْبٜىٰٓ࣌ إِنَّمَا تُنذِرُ ࡲ۬لذِينَ يَخْشَوْنَ رَبَّهُم بِالْغَيْبِ وَأَقَامُواْ ࡲ۬لصَّلَوٰةَ࣌ وَمَن تَزَكّٜىٰ فَإِنَّمَا يَتَزَكّٜىٰ لِنَفْسِهِۦ࣌ وَإِلَى ࡰ۬للَّهِ ࡴ۬لْمَصِيرُ࣌', 'ولا تزر وازرة وزر أخرى࣌ وإن تدع مثقلة ࡴلى حملها لا يحمل منه شےء ولو كان ذا قربى࣌ إنما تنذر ࡲلذين يخشون ربهم بالغيب وأقاموا ࡲلصلوة࣌ ومن تزكى فإنما يتزكى لنفسه࣌ وإلى ࡰلله ࡴلمصير࣌', NULL, 436, 'local:warsh-text.json'),
  ('warsh-35-19', 'warsh', 35, 19, 'وَمَا يَسْتَوِے ࡴ۬لَاعْمٜىٰ وَالْبَصِيرُ', 'وما يستوے ࡴلاعمى والبصير', NULL, 437, 'local:warsh-text.json'),
  ('warsh-35-20', 'warsh', 35, 20, 'وَلَا ࡰ۬لظُّلُمَٰتُ وَلَا ࡰ۬لنُّورُ', 'ولا ࡰلظلمت ولا ࡰلنور', NULL, 437, 'local:warsh-text.json'),
  ('warsh-35-21', 'warsh', 35, 21, 'وَلَا ࡰ۬لظِّلُّ وَلَا ࡰ۬لْحَرُورُ࣌', 'ولا ࡰلظل ولا ࡰلحرور࣌', NULL, 437, 'local:warsh-text.json'),
  ('warsh-35-22', 'warsh', 35, 22, 'وَمَا يَسْتَوِے ࡴ۬لَاحْيَآءُ وَلَا ࡰ۬لَامْوَٰتُ࣌ إِنَّ ࡰ۬للَّهَ يُسْمِعُ مَنْ يَّشَآءُ࣌ وَمَآ أَنتَ بِمُسْمِعࣲ مَّن فِے ࡴ۬لْقُبُورِ࣌', 'وما يستوے ࡴلاحياء ولا ࡰلاموت࣌ إن ࡰلله يسمع من يشاء࣌ وما أنت بمسمع من فے ࡴلقبور࣌', NULL, 437, 'local:warsh-text.json'),
  ('warsh-35-23', 'warsh', 35, 23, 'إِنَ ࡰنتَ إِلَّا نَذِيرٌ࣌', 'إن ࡰنت إلا نذير࣌', NULL, 437, 'local:warsh-text.json'),
  ('warsh-35-24', 'warsh', 35, 24, 'ࡴنَّآ أَرْسَلْنَٰكَ بِالْحَقِّ بَشِيراࣰ وَنَذِيراࣰ࣌ وَإِن مِّنُ ࡳمَّةٍ ࡴلَّا خَلَا فِيهَا نَذِيرࣱ࣌', 'ࡴنا أرسلنك بالحق بشيرا ونذيرا࣌ وإن من ࡳمة ࡴلا خلا فيها نذير࣌', NULL, 437, 'local:warsh-text.json'),
  ('warsh-35-25', 'warsh', 35, 25, 'وَإِنْ يُّكَذِّبُوكَ فَقَدْ كَذَّبَ ࡰ۬لذِينَ مِن قَبْلِهِمْ جَآءَتْهُمْ رُسُلُهُم بِالْبَيِّنَٰتِ وَبِالزُّبُرِ وَبِالْكِتَٰبِ ࡴ۬لْمُنِيرِ', 'وإن يكذبوك فقد كذب ࡰلذين من قبلهم جاءتهم رسلهم بالبينت وبالزبر وبالكتب ࡴلمنير', NULL, 437, 'local:warsh-text.json'),
  ('warsh-35-26', 'warsh', 35, 26, 'ثُمَّ أَخَذتُّ ࡲ۬لذِينَ كَفَرُواْ࣌ فَكَيْفَ كَانَ نَكِيرِۦٓ࣌', 'ثم أخذت ࡲلذين كفروا࣌ فكيف كان نكير࣌', NULL, 437, 'local:warsh-text.json'),
  ('warsh-35-27', 'warsh', 35, 27, 'أَلَمْ تَرَ أَنَّ ࡰ۬للَّهَ أَنزَلَ مِنَ ࡰ۬لسَّمَآءِ مَآءࣰ فَأَخْرَجْنَا بِهِۦ ثَمَرَٰتࣲ مُّخْتَلِفاً ࡰلْوَٰنُهَا࣌ وَمِنَ ࡰ۬لْجِبَالِ جُدَدُۢ بِيضࣱ وَحُمْرࣱ مُّخْتَلِفٌ ࡰلْوَٰنُهَا وَغَرَابِيبُ سُودࣱ࣌', 'ألم تر أن ࡰلله أنزل من ࡰلسماء ماء فأخرجنا به ثمرت مختلفا ࡰلونها࣌ ومن ࡰلجبال جدد بيض وحمر مختلف ࡰلونها وغرابيب سود࣌', NULL, 437, 'local:warsh-text.json'),
  ('warsh-35-28', 'warsh', 35, 28, 'وَمِنَ ࡰ۬لنَّاسِ وَالدَّوَآبِّ وَالَانْعَٰمِ مُخْتَلِفٌ ࡰلْوَٰنُهُۥ كَذَٰلِكَ࣌ إِنَّمَا يَخْشَى ࡰ۬للَّهَ مِنْ عِبَادِهِ ࡴ۬لْعُلَمَٰٓؤُاْ࣌ ࡹِنَّ ࡰ۬للَّهَ عَزِيزٌ غَفُورٌ࣌', 'ومن ࡰلناس والدواب والانعم مختلف ࡰلونه كذلك࣌ إنما يخشى ࡰلله من عباده ࡴلعلمؤا࣌ ࡹن ࡰلله عزيز غفور࣌', NULL, 437, 'local:warsh-text.json'),
  ('warsh-35-29', 'warsh', 35, 29, 'ࡴنَّ ࡰ۬لذِينَ يَتْلُونَ كِتَٰبَ ࡰ۬للَّهِ وَأَقَامُواْ ࡲ۬لصَّلَوٰةَ وَأَنفَقُواْ مِمَّا رَزَقْنَٰهُمْ سِرّاࣰ وَعَلَٰنِيَةࣰ يَرْجُونَ تِجَٰرَةࣰ لَّن تَبُورَ', 'ࡴن ࡰلذين يتلون كتب ࡰلله وأقاموا ࡲلصلوة وأنفقوا مما رزقنهم سرا وعلنية يرجون تجرة لن تبور', NULL, 437, 'local:warsh-text.json'),
  ('warsh-35-30', 'warsh', 35, 30, 'لِيُوَفِّيَهُمُۥٓ أُجُورَهُمْ وَيَزِيدَهُم مِّن فَضْلِهِۦٓ࣌ إِنَّهُۥ غَفُورࣱ شَكُورࣱ࣌', 'ليوفيهم أجورهم ويزيدهم من فضله࣌ إنه غفور شكور࣌', NULL, 437, 'local:warsh-text.json'),
  ('warsh-35-31', 'warsh', 35, 31, '۞ وَالذِےٓ أَوْحَيْنَآ إِلَيْكَ مِنَ ࡰ۬لْكِتَٰبِ هُوَ ࡰ۬لْحَقُّ مُصَدِّقاࣰ لِّمَا بَيْنَ يَدَيْهِ࣌ إِنَّ ࡰ۬للَّهَ بِعِبَادِهِۦ لَخَبِيرُۢ بَصِيرࣱ࣌', 'والذے أوحينا إليك من ࡰلكتب هو ࡰلحق مصدقا لما بين يديه࣌ إن ࡰلله بعباده لخبير بصير࣌', NULL, 438, 'local:warsh-text.json'),
  ('warsh-35-32', 'warsh', 35, 32, 'ثُمَّ أَوْرَثْنَا ࡰ۬لْكِتَٰبَ ࡰ۬لذِينَ ࡰٜصْطَفَيْنَا مِنْ عِبَادِنَا࣌ فَمِنْهُمْ ظَالِمࣱ لِّنَفْسِهِۦ࣌ وَمِنْهُم مُّقْتَصِدࣱ࣌ وَمِنْهُمْ سَابِقُۢ بِالْخَيْرَٰتِ بِإِذْنِ ࡴ۬للَّهِ࣌ ذَٰلِكَ هُوَ ࡰ۬لْفَضْلُ ࡲ۬لْكَبِيرُ࣌', 'ثم أورثنا ࡰلكتب ࡰلذين ࡰصطفينا من عبادنا࣌ فمنهم ظالم لنفسه࣌ ومنهم مقتصد࣌ ومنهم سابق بالخيرت بإذن ࡴلله࣌ ذلك هو ࡰلفضل ࡲلكبير࣌', NULL, 438, 'local:warsh-text.json'),
  ('warsh-35-33', 'warsh', 35, 33, 'جَنَّٰتُ عَدْنࣲ يَدْخُلُونَهَا يُحَلَّوْنَ فِيهَا مِنَ ࡰسَاوِرَ مِن ذَهَبࣲ وَلُؤْلُؤاࣰ࣌ وَلِبَاسُهُمْ فِيهَا حَرِيرࣱ࣌', 'جنت عدن يدخلونها يحلون فيها من ࡰساور من ذهب ولؤلؤا࣌ ولباسهم فيها حرير࣌', NULL, 438, 'local:warsh-text.json'),
  ('warsh-35-34', 'warsh', 35, 34, 'وَقَالُواْ ࡲ۬لْحَمْدُ لِلهِ ࡴ۬لذِےٓ أَذْهَبَ عَنَّا ࡰ۬لْحَزَنَ إِنَّ رَبَّنَا لَغَفُورࣱ شَكُورٌ࣌', 'وقالوا ࡲلحمد لله ࡴلذے أذهب عنا ࡰلحزن إن ربنا لغفور شكور࣌', NULL, 438, 'local:warsh-text.json'),
  ('warsh-35-35', 'warsh', 35, 35, 'ࡴ۬لذِےٓ أَحَلَّنَا دَارَ ࡰ۬لْمُقَامَةِ مِن فَضْلِهِۦ لَا يَمَسُّنَا فِيهَا نَصَبࣱ وَلَا يَمَسُّنَا فِيهَا لُغُوبࣱ࣌', 'ࡴلذے أحلنا دار ࡰلمقامة من فضله لا يمسنا فيها نصب ولا يمسنا فيها لغوب࣌', NULL, 438, 'local:warsh-text.json'),
  ('warsh-35-36', 'warsh', 35, 36, 'وَالذِينَ كَفَرُواْ لَهُمْ نَارُ جَهَنَّمَ لَا يُقْضٜىٰ عَلَيْهِمْ فَيَمُوتُواْ وَلَا يُخَفَّفُ عَنْهُم مِّنْ عَذَابِهَا࣌ كَذَٰلِكَ نَجْزِے كُلَّ كَفُورࣲ࣌', 'والذين كفروا لهم نار جهنم لا يقضى عليهم فيموتوا ولا يخفف عنهم من عذابها࣌ كذلك نجزے كل كفور࣌', NULL, 438, 'local:warsh-text.json'),
  ('warsh-35-37', 'warsh', 35, 37, 'وَهُمْ يَصْطَرِخُونَ فِيهَا رَبَّنَآ أَخْرِجْنَا نَعْمَلْ صَٰلِحاً غَيْرَ ࡰ۬لذِے كُنَّا نَعْمَلُ࣌ أَوَلَمْ نُعَمِّرْكُم مَّا يَتَذَكَّرُ فِيهِ مَن تَذَكَّرَ وَجَآءَكُمُ ࡲ۬لنَّذِيرُ࣌ فَذُوقُواْ࣌ فَمَا لِلظَّٰلِمِينَ مِن نَّصِيرٍ࣌', 'وهم يصطرخون فيها ربنا أخرجنا نعمل صلحا غير ࡰلذے كنا نعمل࣌ أولم نعمركم ما يتذكر فيه من تذكر وجاءكم ࡲلنذير࣌ فذوقوا࣌ فما للظلمين من نصير࣌', NULL, 438, 'local:warsh-text.json'),
  ('warsh-35-38', 'warsh', 35, 38, 'ࡴنَّ ࡰ۬للَّهَ عَٰلِمُ غَيْبِ ࡴ۬لسَّمَٰوَٰتِ وَالَارْضِ࣌ إِنَّهُۥ عَلِيمُۢ بِذَاتِ ࡴ۬لصُّدُورِ࣌', 'ࡴن ࡰلله علم غيب ࡴلسموت والارض࣌ إنه عليم بذات ࡴلصدور࣌', NULL, 438, 'local:warsh-text.json'),
  ('warsh-35-39', 'warsh', 35, 39, 'هُوَ ࡰ۬لذِے جَعَلَكُمْ خَلَٰٓئِفَ فِے ࡴ۬لَارْضِ࣌ فَمَن كَفَرَ فَعَلَيْهِ كُفْرُهُۥ࣌ وَلَا يَزِيدُ ࡲ۬لْكٜـٰفِرِينَ كُفْرُهُمْ عِندَ رَبِّهِمُۥٓ إِلَّا مَقْتاࣰ࣌ وَلَا يَزِيدُ ࡲ۬لْكٜـٰفِرِينَ كُفْرُهُمُۥٓ إِلَّا خَسَاراࣰ࣌', 'هو ࡰلذے جعلكم خلئف فے ࡴلارض࣌ فمن كفر فعليه كفره࣌ ولا يزيد ࡲلكفرين كفرهم عند ربهم إلا مقتا࣌ ولا يزيد ࡲلكفرين كفرهم إلا خسارا࣌', NULL, 439, 'local:warsh-text.json'),
  ('warsh-35-40', 'warsh', 35, 40, 'قُلَ ࡰرَٰٓيْتُمْ شُرَكَآءَكُمُ ࡲ۬لذِينَ تَدْعُونَ مِن دُونِ ࡴ۬للَّهِ أَرُونِے مَاذَا خَلَقُواْ مِنَ ࡰ۬لَارْضِ أَمْ لَهُمْ شِرْكࣱ فِے ࡴ۬لسَّمَٰوَٰتِ࣌ أَمَ اٰتَيْنَٰهُمْ كِتَٰباࣰ فَهُمْ عَلَىٰ بَيِّنَٰتࣲ مِّنْهُ࣌ بَلِ ࡴنْ يَّعِدُ ࡲ۬لظَّٰلِمُونَ بَعْضُهُم بَعْضاً ࡴلَّا غُرُوراً࣌', 'قل ࡰريتم شركاءكم ࡲلذين تدعون من دون ࡴلله أرونے ماذا خلقوا من ࡰلارض أم لهم شرك فے ࡴلسموت࣌ أم اتينهم كتبا فهم على بينت منه࣌ بل ࡴن يعد ࡲلظلمون بعضهم بعضا ࡴلا غرورا࣌', NULL, 439, 'local:warsh-text.json'),
  ('warsh-35-41', 'warsh', 35, 41, '۞ ࡴنَّ ࡰ۬للَّهَ يُمْسِكُ ࡲ۬لسَّمَٰوَٰتِ وَالَارْضَ أَن تَزُولَا࣌ وَلَئِن زَالَتَآ إِنَ ࡰمْسَكَهُمَا مِنَ ࡰحَدࣲ مِّنۢ بَعْدِهِۦٓ࣌ إِنَّهُۥ كَانَ حَلِيماً غَفُوراࣰ࣌', 'ࡴن ࡰلله يمسك ࡲلسموت والارض أن تزولا࣌ ولئن زالتا إن ࡰمسكهما من ࡰحد من بعده࣌ إنه كان حليما غفورا࣌', NULL, 439, 'local:warsh-text.json'),
  ('warsh-35-42', 'warsh', 35, 42, 'وَأَقْسَمُواْ بِاللَّهِ جَهْدَ أَيْمَٰنِهِمْ لَئِن جَآءَهُمْ نَذِيرࣱ لَّيَكُونُنَّ أَهْدٜىٰ مِنِ ࡴحْدَى ࡰ۬لُامَمِ࣌ فَلَمَّا جَآءَهُمْ نَذِيرࣱ مَّا زَادَهُمُۥٓ إِلَّا نُفُوراً࣌', 'وأقسموا بالله جهد أيمنهم لئن جاءهم نذير ليكونن أهدى من ࡴحدى ࡰلامم࣌ فلما جاءهم نذير ما زادهم إلا نفورا࣌', NULL, 439, 'local:warsh-text.json'),
  ('warsh-35-43', 'warsh', 35, 43, 'ࡴٜسْتِكْبَاراࣰ فِے ࡴ۬لَارْضِ وَمَكْرَ ࡰ۬لسَّيِّےِٕ࣌ وَلَا يَحِيقُ ࡲ۬لْمَكْرُ ࡲ۬لسَّيِّۓُ ࡹِلَّا بِأَهْلِهِۦ࣌ فَهَلْ يَنظُرُونَ إِلَّا سُنَّتَ ࡰ۬لَاوَّلِينَ࣌ فَلَن تَجِدَ لِسُنَّتِ ࡴ۬للَّهِ تَبْدِيلاࣰ࣌', 'ࡴستكبارا فے ࡴلارض ومكر ࡰلسيے࣌ ولا يحيق ࡲلمكر ࡲلسيے ࡹلا بأهله࣌ فهل ينظرون إلا سنت ࡰلاولين࣌ فلن تجد لسنت ࡴلله تبديلا࣌', NULL, 439, 'local:warsh-text.json'),
  ('warsh-35-44', 'warsh', 35, 44, 'وَلَن تَجِدَ لِسُنَّتِ ࡴ۬للَّهِ تَحْوِيلاً࣌', 'ولن تجد لسنت ࡴلله تحويلا࣌', NULL, 439, 'local:warsh-text.json'),
  ('warsh-35-45', 'warsh', 35, 45, 'ࡰوَلَمْ يَسِيرُواْ فِے ࡴ۬لَارْضِ فَيَنظُرُواْ كَيْفَ كَانَ عَٰقِبَةُ ࡲ۬لذِينَ مِن قَبْلِهِمْ وَكَانُوٓاْ أَشَدَّ مِنْهُمْ قُوَّةࣰ࣌ وَمَا كَانَ ࡰ۬للَّهُ لِيُعْجِزَهُۥ مِن شَےْءࣲ فِے ࡴ۬لسَّمَٰوَٰتِ وَلَا فِے ࡴ۬لَارْضِ࣌ إِنَّهُۥ كَانَ عَلِيماࣰ قَدِيراࣰ࣌', 'ࡰولم يسيروا فے ࡴلارض فينظروا كيف كان عقبة ࡲلذين من قبلهم وكانوا أشد منهم قوة࣌ وما كان ࡰلله ليعجزه من شےء فے ࡴلسموت ولا فے ࡴلارض࣌ إنه كان عليما قديرا࣌', NULL, 439, 'local:warsh-text.json'),
  ('warsh-35-46', 'warsh', 35, 46, 'وَلَوْ يُوَ۬اخِذُ ࡲ۬للَّهُ ࡲ۬لنَّاسَ بِمَا كَسَبُواْ مَا تَرَكَ عَلَىٰ ظَهْرِهَا مِن دَآبَّةࣲ࣌ وَلَٰكِنْ يُّوَ۬خِّرُهُمُۥٓ إِلَىٰٓ أَجَلࣲ مُّسَمّىࣰ࣌ فَإِذَا جَآءَ اجَلُهُمْ فَإِنَّ ࡰ۬للَّهَ كَانَ بِعِبَادِهِۦ بَصِيراࣰ࣌', 'ولو يواخذ ࡲلله ࡲلناس بما كسبوا ما ترك على ظهرها من دابة࣌ ولكن يوخرهم إلى أجل مسمى࣌ فإذا جاء اجلهم فإن ࡰلله كان بعباده بصيرا࣌', NULL, 440, 'local:warsh-text.json'),
  ('warsh-36-1', 'warsh', 36, 1, 'يَسِٓ࣌ وَالْقُرْءَانِ ࡴ۬لْحَكِيمِ', 'يس࣌ والقرءان ࡴلحكيم', NULL, 440, 'local:warsh-text.json'),
  ('warsh-36-2', 'warsh', 36, 2, 'إِنَّكَ لَمِنَ ࡰ۬لْمُرْسَلِينَ', 'إنك لمن ࡰلمرسلين', NULL, 440, 'local:warsh-text.json'),
  ('warsh-36-3', 'warsh', 36, 3, 'عَلَىٰ صِرَٰطࣲ مُّسْتَقِيمࣲ࣌', 'على صرط مستقيم࣌', NULL, 440, 'local:warsh-text.json'),
  ('warsh-36-4', 'warsh', 36, 4, 'تَنزِيلُ ࡲ۬لْعَزِيزِ ࡴ۬لرَّحِيمِ', 'تنزيل ࡲلعزيز ࡴلرحيم', NULL, 440, 'local:warsh-text.json'),
  ('warsh-36-5', 'warsh', 36, 5, 'لِتُنذِرَ قَوْماࣰ مَّآ أُنذِرَ ءَابَآؤُهُمْ فَهُمْ غَٰفِلُونَ࣌', 'لتنذر قوما ما أنذر ءاباؤهم فهم غفلون࣌', NULL, 440, 'local:warsh-text.json'),
  ('warsh-36-6', 'warsh', 36, 6, '۞ لَقَدْ حَقَّ ࡰ۬لْقَوْلُ عَلَىٰٓ أَكْثَرِهِمْ فَهُمْ لَا يُومِنُونَ࣌', 'لقد حق ࡰلقول على أكثرهم فهم لا يومنون࣌', NULL, 440, 'local:warsh-text.json'),
  ('warsh-36-7', 'warsh', 36, 7, 'إِنَّا جَعَلْنَا فِےٓ أَعْنَٰقِهِمُۥٓ أَغْلَٰلاࣰ فَهِيَ إِلَى ࡰ۬لَاذْقَانِ فَهُم مُّقْمَحُونَ࣌', 'إنا جعلنا فے أعنقهم أغللا فهي إلى ࡰلاذقان فهم مقمحون࣌', NULL, 440, 'local:warsh-text.json'),
  ('warsh-36-8', 'warsh', 36, 8, 'وَجَعَلْنَا مِنۢ بَيْنِ أَيْدِيهِمْ سُدّاࣰ وَمِنْ خَلْفِهِمْ سُدّاࣰ فَأَغْشَيْنَٰهُمْ فَهُمْ لَا يُبْصِرُونَ࣌', 'وجعلنا من بين أيديهم سدا ومن خلفهم سدا فأغشينهم فهم لا يبصرون࣌', NULL, 440, 'local:warsh-text.json'),
  ('warsh-36-9', 'warsh', 36, 9, 'وَسَوَآءٌ عَلَيْهِمُۥٓ ءَآنذَرْتَهُمُۥٓ أَمْ لَمْ تُنذِرْهُمْ لَا يُومِنُونَ࣌', 'وسواء عليهم ءانذرتهم أم لم تنذرهم لا يومنون࣌', NULL, 440, 'local:warsh-text.json'),
  ('warsh-36-10', 'warsh', 36, 10, 'إِنَّمَا تُنذِرُ مَنِ ࡴٜتَّبَعَ ࡰ۬لذِّكْرَ وَخَشِيَ ࡰ۬لرَّحْمَٰنَ بِالْغَيْبِ فَبَشِّرْهُ بِمَغْفِرَةࣲ وَأَجْرࣲ كَرِيمٍ࣌', 'إنما تنذر من ࡴتبع ࡰلذكر وخشي ࡰلرحمن بالغيب فبشره بمغفرة وأجر كريم࣌', NULL, 440, 'local:warsh-text.json'),
  ('warsh-36-11', 'warsh', 36, 11, 'ࡴنَّا نَحْنُ نُحْيِ ࡴ۬لْمَوْتٜىٰ وَنَكْتُبُ مَا قَدَّمُواْ وَءَاثَٰرَهُمْ࣌ وَكُلَّ شَےْءٍ ࡰحْصَيْنَٰهُ فِےٓ إِمَامࣲ مُّبِينࣲ࣌', 'ࡴنا نحن نحي ࡴلموتى ونكتب ما قدموا وءاثرهم࣌ وكل شےء ࡰحصينه فے إمام مبين࣌', NULL, 440, 'local:warsh-text.json'),
  ('warsh-36-12', 'warsh', 36, 12, 'وَاضْرِبْ لَهُم مَّثَلاً ࡰصْحَٰبَ ࡰ۬لْقَرْيَةِ إِذْ جَآءَهَا ࡰ۬لْمُرْسَلُونَ', 'واضرب لهم مثلا ࡰصحب ࡰلقرية إذ جاءها ࡰلمرسلون', NULL, 441, 'local:warsh-text.json'),
  ('warsh-36-13', 'warsh', 36, 13, 'إِذَ ࡰرْسَلْنَآ إِلَيْهِمُ ࡲٜثْنَيْنِ فَكَذَّبُوهُمَا فَعَزَّزْنَا بِثَالِثࣲ فَقَالُوٓاْ إِنَّآ إِلَيْكُم مُّرْسَلُونَ࣌', 'إذ ࡰرسلنا إليهم ࡲثنين فكذبوهما فعززنا بثالث فقالوا إنا إليكم مرسلون࣌', NULL, 441, 'local:warsh-text.json'),
  ('warsh-36-14', 'warsh', 36, 14, 'قَالُواْ مَآ أَنتُمُۥٓ إِلَّا بَشَرࣱ مِّثْلُنَا وَمَآ أَنزَلَ ࡰ۬لرَّحْمَٰنُ مِن شَےْءٍ ࡴنَ ࡰنتُمُۥٓ إِلَّا تَكْذِبُونَ࣌', 'قالوا ما أنتم إلا بشر مثلنا وما أنزل ࡰلرحمن من شےء ࡴن ࡰنتم إلا تكذبون࣌', NULL, 441, 'local:warsh-text.json'),
  ('warsh-36-15', 'warsh', 36, 15, 'قَالُواْ رَبُّنَا يَعْلَمُ إِنَّآ إِلَيْكُمْ لَمُرْسَلُونَ', 'قالوا ربنا يعلم إنا إليكم لمرسلون', NULL, 441, 'local:warsh-text.json'),
  ('warsh-36-16', 'warsh', 36, 16, 'وَمَا عَلَيْنَآ إِلَّا ࡰ۬لْبَلَٰغُ ࡲ۬لْمُبِينُ࣌', 'وما علينا إلا ࡰلبلغ ࡲلمبين࣌', NULL, 441, 'local:warsh-text.json'),
  ('warsh-36-17', 'warsh', 36, 17, 'قَالُوٓاْ إِنَّا تَطَيَّرْنَا بِكُمْ لَئِن لَّمْ تَنتَهُواْ لَنَرْجُمَنَّكُمْ وَلَيَمَسَّنَّكُم مِّنَّا عَذَابٌ ࡰلِيمࣱ࣌', 'قالوا إنا تطيرنا بكم لئن لم تنتهوا لنرجمنكم وليمسنكم منا عذاب ࡰليم࣌', NULL, 441, 'local:warsh-text.json'),
  ('warsh-36-18', 'warsh', 36, 18, 'قَالُواْ طَٰٓئِرُكُم مَّعَكُمُۥٓ أَئِن ذُكِّرْتُم࣌ بَلَ ࡰنتُمْ قَوْمࣱ مُّسْرِفُونَ࣌', 'قالوا طئركم معكم أئن ذكرتم࣌ بل ࡰنتم قوم مسرفون࣌', NULL, 441, 'local:warsh-text.json'),
  ('warsh-36-19', 'warsh', 36, 19, 'وَجَآءَ مِنَ ࡰقْصَا ࡰ۬لْمَدِينَةِ رَجُلࣱ يَسْعٜىٰ࣌ قَالَ يَٰقَوْمِ ࡴٜتَّبِعُواْ ࡲ۬لْمُرْسَلِينَ', 'وجاء من ࡰقصا ࡰلمدينة رجل يسعى࣌ قال يقوم ࡴتبعوا ࡲلمرسلين', NULL, 441, 'local:warsh-text.json'),
  ('warsh-36-20', 'warsh', 36, 20, 'ࡰٜتَّبِعُواْ مَن لَّا يَسْـَٔلُكُمُۥٓ أَجْراࣰ وَهُم مُّهْتَدُونَ࣌', 'ࡰتبعوا من لا يسلكم أجرا وهم مهتدون࣌', NULL, 441, 'local:warsh-text.json'),
  ('warsh-36-21', 'warsh', 36, 21, 'وَمَا لِيَ لَآ أَعْبُدُ ࡲ۬لذِے فَطَرَنِے وَإِلَيْهِ تُرْجَعُونَ࣌', 'وما لي لا أعبد ࡲلذے فطرنے وإليه ترجعون࣌', NULL, 441, 'local:warsh-text.json'),
  ('warsh-36-22', 'warsh', 36, 22, 'ءَآتَّخِذُ مِن دُونِهِۦٓ ءَالِهَةً ࡴنْ يُّرِدْنِ ࡴ۬لرَّحْمَٰنُ بِضُرࣲّ لَّا تُغْنِ عَنِّے شَفَٰعَتُهُمْ شَيْـٔاࣰ وَلَا يُنقِذُونِۦٓ࣌', 'ءاتخذ من دونه ءالهة ࡴن يردن ࡴلرحمن بضر لا تغن عنے شفعتهم شيا ولا ينقذون࣌', NULL, 441, 'local:warsh-text.json'),
  ('warsh-36-23', 'warsh', 36, 23, 'إِنِّيَ إِذاࣰ لَّفِے ضَلَٰلࣲ مُّبِينٍ࣌', 'إني إذا لفے ضلل مبين࣌', NULL, 441, 'local:warsh-text.json'),
  ('warsh-36-24', 'warsh', 36, 24, 'ࡴنِّيَ ءَامَنتُ بِرَبِّكُمْ فَاسْمَعُونِ࣌', 'ࡴني ءامنت بربكم فاسمعون࣌', NULL, 441, 'local:warsh-text.json'),
  ('warsh-36-25', 'warsh', 36, 25, 'قِيلَ ࡸَدْخُلِ ࡴ۬لْجَنَّةَ࣌ قَالَ يَٰلَيْتَ قَوْمِے يَعْلَمُونَ', 'قيل ࡸدخل ࡴلجنة࣌ قال يليت قومے يعلمون', NULL, 441, 'local:warsh-text.json'),
  ('warsh-36-26', 'warsh', 36, 26, 'بِمَا غَفَرَ لِے رَبِّے وَجَعَلَنِے مِنَ ࡰ۬لْمُكْرَمِينَ࣌', 'بما غفر لے ربے وجعلنے من ࡰلمكرمين࣌', NULL, 441, 'local:warsh-text.json'),
  ('warsh-36-27', 'warsh', 36, 27, '۞ وَمَآ أَنزَلْنَا عَلَىٰ قَوْمِهِۦ مِنۢ بَعْدِهِۦ مِن جُندࣲ مِّنَ ࡰ۬لسَّمَآءِ وَمَا كُنَّا مُنزِلِينَ࣌', 'وما أنزلنا على قومه من بعده من جند من ࡰلسماء وما كنا منزلين࣌', NULL, 442, 'local:warsh-text.json'),
  ('warsh-36-28', 'warsh', 36, 28, 'إِن كَانَتِ ࡴلَّا صَيْحَةࣰ وَٰحِدَةࣰ فَإِذَا هُمْ خَٰمِدُونَ࣌', 'إن كانت ࡴلا صيحة وحدة فإذا هم خمدون࣌', NULL, 442, 'local:warsh-text.json'),
  ('warsh-36-29', 'warsh', 36, 29, 'يَٰحَسْرَةً عَلَى ࡰ۬لْعِبَادِ࣌ مَا يَاتِيهِم مِّن رَّسُولٍ ࡴلَّا كَانُواْ بِهِۦ يَسْتَهْزِءُونَ࣌', 'يحسرة على ࡰلعباد࣌ ما ياتيهم من رسول ࡴلا كانوا به يستهزءون࣌', NULL, 442, 'local:warsh-text.json'),
  ('warsh-36-30', 'warsh', 36, 30, 'أَلَمْ يَرَوْاْ كَمَ ࡰهْلَكْنَا قَبْلَهُم مِّنَ ࡰ۬لْقُرُونِ أَنَّهُمُۥٓ إِلَيْهِمْ لَا يَرْجِعُونَ࣌', 'ألم يروا كم ࡰهلكنا قبلهم من ࡰلقرون أنهم إليهم لا يرجعون࣌', NULL, 442, 'local:warsh-text.json'),
  ('warsh-36-31', 'warsh', 36, 31, 'وَإِن كُلࣱّ لَّمَا جَمِيعࣱ لَّدَيْنَا مُحْضَرُونَ࣌', 'وإن كل لما جميع لدينا محضرون࣌', NULL, 442, 'local:warsh-text.json'),
  ('warsh-36-32', 'warsh', 36, 32, 'وَءَايَةࣱ لَّهُمُ ࡲ۬لَارْضُ ࡲ۬لْمَيِّتَةُ أَحْيَيْنَٰهَا وَأَخْرَجْنَا مِنْهَا حَبّاࣰ فَمِنْهُ يَاكُلُونَ࣌', 'وءاية لهم ࡲلارض ࡲلميتة أحيينها وأخرجنا منها حبا فمنه ياكلون࣌', NULL, 442, 'local:warsh-text.json'),
  ('warsh-36-33', 'warsh', 36, 33, 'وَجَعَلْنَا فِيهَا جَنَّٰتࣲ مِّن نَّخِيلࣲ وَأَعْنَٰبࣲ وَفَجَّرْنَا فِيهَا مِنَ ࡰ۬لْعُيُونِ', 'وجعلنا فيها جنت من نخيل وأعنب وفجرنا فيها من ࡰلعيون', NULL, 442, 'local:warsh-text.json'),
  ('warsh-36-34', 'warsh', 36, 34, 'لِيَاكُلُواْ مِن ثَمَرِهِۦ وَمَا عَمِلَتْهُ أَيْدِيهِمُۥٓ࣌ أَفَلَا يَشْكُرُونَ࣌', 'لياكلوا من ثمره وما عملته أيديهم࣌ أفلا يشكرون࣌', NULL, 442, 'local:warsh-text.json'),
  ('warsh-36-35', 'warsh', 36, 35, 'سُبْحَٰنَ ࡰ۬لذِے خَلَقَ ࡰ۬لَازْوَٰجَ كُلَّهَا مِمَّا تُنۢبِتُ ࡲ۬لَارْضُ وَمِنَ ࡰنفُسِهِمْ وَمِمَّا لَا يَعْلَمُونَ࣌', 'سبحن ࡰلذے خلق ࡰلازوج كلها مما تنبت ࡲلارض ومن ࡰنفسهم ومما لا يعلمون࣌', NULL, 442, 'local:warsh-text.json'),
  ('warsh-36-36', 'warsh', 36, 36, 'وَءَايَةࣱ لَّهُمُ ࡲ۬ليْلُ نَسْلَخُ مِنْهُ ࡲ۬لنَّهَارَ فَإِذَا هُم مُّظْلِمُونَ࣌', 'وءاية لهم ࡲليل نسلخ منه ࡲلنهار فإذا هم مظلمون࣌', NULL, 442, 'local:warsh-text.json'),
  ('warsh-36-37', 'warsh', 36, 37, 'وَالشَّمْسُ تَجْرِے لِمُسْتَقَرࣲّ لَّهَا࣌ ذَٰلِكَ تَقْدِيرُ ࡲ۬لْعَزِيزِ ࡴ۬لْعَلِيمِ࣌', 'والشمس تجرے لمستقر لها࣌ ذلك تقدير ࡲلعزيز ࡴلعليم࣌', NULL, 442, 'local:warsh-text.json'),
  ('warsh-36-38', 'warsh', 36, 38, 'وَالْقَمَرُ قَدَّرْنَٰهُ مَنَازِلَ حَتَّىٰ عَادَ كَالْعُرْجُونِ ࡴ۬لْقَدِيمِ࣌', 'والقمر قدرنه منازل حتى عاد كالعرجون ࡴلقديم࣌', NULL, 442, 'local:warsh-text.json'),
  ('warsh-36-39', 'warsh', 36, 39, 'لَا ࡰ۬لشَّمْسُ يَنۢبَغِے لَهَآ أَن تُدْرِكَ ࡰ۬لْقَمَرَ وَلَا ࡰ۬ليْلُ سَابِقُ ࡲ۬لنَّهٜارِ࣌ وَكُلࣱّ فِے فَلَكࣲ يَسْبَحُونَ࣌', 'لا ࡰلشمس ينبغے لها أن تدرك ࡰلقمر ولا ࡰليل سابق ࡲلنهار࣌ وكل فے فلك يسبحون࣌', NULL, 442, 'local:warsh-text.json'),
  ('warsh-36-40', 'warsh', 36, 40, 'وَءَايَةࣱ لَّهُمُۥٓ أَنَّا حَمَلْنَا ذُرِّيَّٰتِهِمْ فِے ࡴ۬لْفُلْكِ ࡴ۬لْمَشْحُونِ', 'وءاية لهم أنا حملنا ذريتهم فے ࡴلفلك ࡴلمشحون', NULL, 443, 'local:warsh-text.json'),
  ('warsh-36-41', 'warsh', 36, 41, 'وَخَلَقْنَا لَهُم مِّن مِّثْلِهِۦ مَا يَرْكَبُونَ࣌', 'وخلقنا لهم من مثله ما يركبون࣌', NULL, 443, 'local:warsh-text.json'),
  ('warsh-36-42', 'warsh', 36, 42, 'وَإِن نَّشَأْ نُغْرِقْهُمْ فَلَا صَرِيخَ لَهُمْ وَلَا هُمْ يُنقَذُونَ', 'وإن نشأ نغرقهم فلا صريخ لهم ولا هم ينقذون', NULL, 443, 'local:warsh-text.json'),
  ('warsh-36-43', 'warsh', 36, 43, 'إِلَّا رَحْمَةࣰ مِّنَّا وَمَتَٰعاً ࡴلَىٰ حِينࣲ࣌', 'إلا رحمة منا ومتعا ࡴلى حين࣌', NULL, 443, 'local:warsh-text.json'),
  ('warsh-36-44', 'warsh', 36, 44, 'وَإِذَا قِيلَ لَهُمُ ࡲٜتَّقُواْ مَا بَيْنَ أَيْدِيكُمْ وَمَا خَلْفَكُمْ لَعَلَّكُمْ تُرْحَمُونَ࣌', 'وإذا قيل لهم ࡲتقوا ما بين أيديكم وما خلفكم لعلكم ترحمون࣌', NULL, 443, 'local:warsh-text.json'),
  ('warsh-36-45', 'warsh', 36, 45, '۞ وَمَا تَاتِيهِم مِّنَ اٰيَةࣲ مِّنَ اٰيَٰتِ رَبِّهِمُۥٓ إِلَّا كَانُواْ عَنْهَا مُعْرِضِينَ࣌', 'وما تاتيهم من اية من ايت ربهم إلا كانوا عنها معرضين࣌', NULL, 443, 'local:warsh-text.json'),
  ('warsh-36-46', 'warsh', 36, 46, 'وَإِذَا قِيلَ لَهُمُۥٓ أَنفِقُواْ مِمَّا رَزَقَكُمُ ࡲ۬للَّهُ قَالَ ࡰ۬لذِينَ كَفَرُواْ لِلذِينَ ءَامَنُوٓاْ أَنُطْعِمُ مَن لَّوْ يَشَآءُ ࡲ۬للَّهُ أَطْعَمَهُۥٓ إِنَ ࡰنتُمُۥٓ إِلَّا فِے ضَلَٰلࣲ مُّبِينࣲ࣌', 'وإذا قيل لهم أنفقوا مما رزقكم ࡲلله قال ࡰلذين كفروا للذين ءامنوا أنطعم من لو يشاء ࡲلله أطعمه إن ࡰنتم إلا فے ضلل مبين࣌', NULL, 443, 'local:warsh-text.json'),
  ('warsh-36-47', 'warsh', 36, 47, 'وَيَقُولُونَ مَتٜىٰ هَٰذَا ࡰ۬لْوَعْدُ إِن كُنتُمْ صَٰدِقِينَ࣌', 'ويقولون متى هذا ࡰلوعد إن كنتم صدقين࣌', NULL, 443, 'local:warsh-text.json'),
  ('warsh-36-48', 'warsh', 36, 48, 'مَا يَنظُرُونَ إِلَّا صَيْحَةࣰ وَٰحِدَةࣰ تَاخُذُهُمْ وَهُمْ يَخَصِّمُونَ࣌', 'ما ينظرون إلا صيحة وحدة تاخذهم وهم يخصمون࣌', NULL, 443, 'local:warsh-text.json'),
  ('warsh-36-49', 'warsh', 36, 49, 'فَلَا يَسْتَطِيعُونَ تَوْصِيَةࣰ وَلَآ إِلَىٰٓ أَهْلِهِمْ يَرْجِعُونَ࣌', 'فلا يستطيعون توصية ولا إلى أهلهم يرجعون࣌', NULL, 443, 'local:warsh-text.json'),
  ('warsh-36-50', 'warsh', 36, 50, 'وَنُفِخَ فِے ࡴ۬لصُّورِ فَإِذَا هُم مِّنَ ࡰ۬لَاجْدَاثِ إِلَىٰ رَبِّهِمْ يَنسِلُونَ࣌', 'ونفخ فے ࡴلصور فإذا هم من ࡰلاجداث إلى ربهم ينسلون࣌', NULL, 443, 'local:warsh-text.json'),
  ('warsh-36-51', 'warsh', 36, 51, 'قَالُواْ يَٰوَيْلَنَا مَنۢ بَعَثَنَا مِن مَّرْقَدِنَا࣌ هَٰذَا مَا وَعَدَ ࡰ۬لرَّحْمَٰنُ وَصَدَقَ ࡰ۬لْمُرْسَلُونَ࣌', 'قالوا يويلنا من بعثنا من مرقدنا࣌ هذا ما وعد ࡰلرحمن وصدق ࡰلمرسلون࣌', NULL, 443, 'local:warsh-text.json'),
  ('warsh-36-52', 'warsh', 36, 52, 'إِن كَانَتِ ࡴلَّا صَيْحَةࣰ وَٰحِدَةࣰ فَإِذَا هُمْ جَمِيعࣱ لَّدَيْنَا مُحْضَرُونَ࣌', 'إن كانت ࡴلا صيحة وحدة فإذا هم جميع لدينا محضرون࣌', NULL, 443, 'local:warsh-text.json'),
  ('warsh-36-53', 'warsh', 36, 53, 'فَالْيَوْمَ لَا تُظْلَمُ نَفْسࣱ شَيْـٔاࣰ وَلَا تُجْزَوْنَ إِلَّا مَا كُنتُمْ تَعْمَلُونَ࣌', 'فاليوم لا تظلم نفس شيا ولا تجزون إلا ما كنتم تعملون࣌', NULL, 443, 'local:warsh-text.json'),
  ('warsh-36-54', 'warsh', 36, 54, 'إِنَّ أَصْحَٰبَ ࡰ۬لْجَنَّةِ ࡴ۬لْيَوْمَ فِے شُغْلࣲ فَٰكِهُونَ', 'إن أصحب ࡰلجنة ࡴليوم فے شغل فكهون', NULL, 444, 'local:warsh-text.json'),
  ('warsh-36-55', 'warsh', 36, 55, 'هُمْ وَأَزْوَٰجُهُمْ فِے ظِلَٰلٍ عَلَى ࡰ۬لَارَآئِكِ مُتَّكِـُٔونَ࣌', 'هم وأزوجهم فے ظلل على ࡰلارائك متكون࣌', NULL, 444, 'local:warsh-text.json'),
  ('warsh-36-56', 'warsh', 36, 56, 'لَهُمْ فِيهَا فَٰكِهَةࣱ࣌ وَلَهُم مَّا يَدَّعُونَ', 'لهم فيها فكهة࣌ ولهم ما يدعون', NULL, 444, 'local:warsh-text.json'),
  ('warsh-36-57', 'warsh', 36, 57, 'سَلَٰمࣱ࣌ قَوْلاࣰ مِّن رَّبࣲّ رَّحِيمࣲ࣌', 'سلم࣌ قولا من رب رحيم࣌', NULL, 444, 'local:warsh-text.json'),
  ('warsh-36-58', 'warsh', 36, 58, 'وَامْتَٰزُواْ ࡲ۬لْيَوْمَ أَيُّهَا ࡰ۬لْمُجْرِمُونَ࣌', 'وامتزوا ࡲليوم أيها ࡰلمجرمون࣌', NULL, 444, 'local:warsh-text.json'),
  ('warsh-36-59', 'warsh', 36, 59, '۞ أَلَمَ ࡰعْهَدِ ࡴلَيْكُمْ يَٰبَنِےٓ ءَادَمَ أَن لَّا تَعْبُدُواْ ࡲ۬لشَّيْطَٰنَ إِنَّهُۥ لَكُمْ عَدُوࣱّ مُّبِينࣱ', 'ألم ࡰعهد ࡴليكم يبنے ءادم أن لا تعبدوا ࡲلشيطن إنه لكم عدو مبين', NULL, 444, 'local:warsh-text.json'),
  ('warsh-36-60', 'warsh', 36, 60, 'وَأَنُ ࡲ࢈عْبُدُونِے࣌ هَٰذَا صِرَٰطࣱ مُّسْتَقِيمࣱ࣌', 'وأن ࡲ࢈عبدونے࣌ هذا صرط مستقيم࣌', NULL, 444, 'local:warsh-text.json'),
  ('warsh-36-61', 'warsh', 36, 61, 'وَلَقَدَ ࡰضَلَّ مِنكُمْ جِبِلّاࣰ كَثِيراً࣌ ࡰفَلَمْ تَكُونُواْ تَعْقِلُونَ࣌', 'ولقد ࡰضل منكم جبلا كثيرا࣌ ࡰفلم تكونوا تعقلون࣌', NULL, 444, 'local:warsh-text.json'),
  ('warsh-36-62', 'warsh', 36, 62, 'هَٰذِهِۦ جَهَنَّمُ ࡲ۬لتِے كُنتُمْ تُوعَدُونَ', 'هذه جهنم ࡲلتے كنتم توعدون', NULL, 444, 'local:warsh-text.json'),
  ('warsh-36-63', 'warsh', 36, 63, 'ࡰٜصْلَوْهَا ࡰ۬لْيَوْمَ بِمَا كُنتُمْ تَكْفُرُونَ࣌', 'ࡰصلوها ࡰليوم بما كنتم تكفرون࣌', NULL, 444, 'local:warsh-text.json'),
  ('warsh-36-64', 'warsh', 36, 64, 'ࡰ۬لْيَوْمَ نَخْتِمُ عَلَىٰٓ أَفْوَٰهِهِمْ وَتُكَلِّمُنَآ أَيْدِيهِمْ وَتَشْهَدُ أَرْجُلُهُم بِمَا كَانُواْ يَكْسِبُونَ࣌', 'ࡰليوم نختم على أفوههم وتكلمنا أيديهم وتشهد أرجلهم بما كانوا يكسبون࣌', NULL, 444, 'local:warsh-text.json'),
  ('warsh-36-65', 'warsh', 36, 65, 'وَلَوْ نَشَآءُ لَطَمَسْنَا عَلَىٰٓ أَعْيُنِهِمْ فَاسْتَبَقُواْ ࡲ۬لصِّرَٰطَ فَأَنّٜىٰ يُبْصِرُونَ࣌', 'ولو نشاء لطمسنا على أعينهم فاستبقوا ࡲلصرط فأنى يبصرون࣌', NULL, 444, 'local:warsh-text.json'),
  ('warsh-36-66', 'warsh', 36, 66, 'وَلَوْ نَشَآءُ لَمَسَخْنَٰهُمْ عَلَىٰ مَكَانَتِهِمْ فَمَا ࡰٜسْتَطَٰعُواْ مُضِيّاࣰ وَلَا يَرْجِعُونَ࣌', 'ولو نشاء لمسخنهم على مكانتهم فما ࡰستطعوا مضيا ولا يرجعون࣌', NULL, 444, 'local:warsh-text.json'),
  ('warsh-36-67', 'warsh', 36, 67, 'وَمَن نُّعَمِّرْهُ نَنكُسْهُ فِے ࡴ۬لْخَلْقِ࣌ أَفَلَا تَعْقِلُونَ࣌', 'ومن نعمره ننكسه فے ࡴلخلق࣌ أفلا تعقلون࣌', NULL, 444, 'local:warsh-text.json'),
  ('warsh-36-68', 'warsh', 36, 68, 'وَمَا عَلَّمْنَٰهُ ࡲ۬لشِّعْرَ وَمَا يَنۢبَغِے لَهُۥٓ࣌ إِنْ هُوَ إِلَّا ذِكْرࣱ وَقُرْءَانࣱ مُّبِينࣱ', 'وما علمنه ࡲلشعر وما ينبغے له࣌ إن هو إلا ذكر وقرءان مبين', NULL, 444, 'local:warsh-text.json'),
  ('warsh-36-69', 'warsh', 36, 69, 'لِّتُنذِرَ مَن كَانَ حَيّاࣰ وَيَحِقَّ ࡰ۬لْقَوْلُ عَلَى ࡰ۬لْكٜـٰفِرِينَ࣌', 'لتنذر من كان حيا ويحق ࡰلقول على ࡰلكفرين࣌', NULL, 444, 'local:warsh-text.json'),
  ('warsh-36-70', 'warsh', 36, 70, 'أَوَلَمْ يَرَوَاْ ࡰنَّا خَلَقْنَا لَهُم مِّمَّا عَمِلَتَ ࡰيْدِينَآ أَنْعَٰماࣰ فَهُمْ لَهَا مَٰلِكُونَ࣌', 'أولم يروا ࡰنا خلقنا لهم مما عملت ࡰيدينا أنعما فهم لها ملكون࣌', NULL, 445, 'local:warsh-text.json'),
  ('warsh-36-71', 'warsh', 36, 71, 'وَذَلَّلْنَٰهَا لَهُمْ فَمِنْهَا رَكُوبُهُمْ وَمِنْهَا يَاكُلُونَ࣌', 'وذللنها لهم فمنها ركوبهم ومنها ياكلون࣌', NULL, 445, 'local:warsh-text.json'),
  ('warsh-36-72', 'warsh', 36, 72, 'وَلَهُمْ فِيهَا مَنَٰفِعُ وَمَشَارِبُ࣌ أَفَلَا يَشْكُرُونَ࣌', 'ولهم فيها منفع ومشارب࣌ أفلا يشكرون࣌', NULL, 445, 'local:warsh-text.json'),
  ('warsh-36-73', 'warsh', 36, 73, 'وَاتَّخَذُواْ مِن دُونِ ࡴ۬للَّهِ ءَالِهَةࣰ لَّعَلَّهُمْ يُنصَرُونَ', 'واتخذوا من دون ࡴلله ءالهة لعلهم ينصرون', NULL, 445, 'local:warsh-text.json'),
  ('warsh-36-74', 'warsh', 36, 74, 'لَا يَسْتَطِيعُونَ نَصْرَهُمْ وَهُمْ لَهُمْ جُندࣱ مُّحْضَرُونَ࣌', 'لا يستطيعون نصرهم وهم لهم جند محضرون࣌', NULL, 445, 'local:warsh-text.json'),
  ('warsh-36-75', 'warsh', 36, 75, 'فَلَا يُحْزِنكَ قَوْلُهُمُۥٓ࣌ إِنَّا نَعْلَمُ مَا يُسِرُّونَ وَمَا يُعْلِنُونَ࣌', 'فلا يحزنك قولهم࣌ إنا نعلم ما يسرون وما يعلنون࣌', NULL, 445, 'local:warsh-text.json'),
  ('warsh-36-76', 'warsh', 36, 76, 'أَوَلَمْ يَرَ ࡰ۬لِانسَٰنُ أَنَّا خَلَقْنَٰهُ مِن نُّطْفَةࣲ فَإِذَا هُوَ خَصِيمࣱ مُّبِينࣱ࣌', 'أولم ير ࡰلانسن أنا خلقنه من نطفة فإذا هو خصيم مبين࣌', NULL, 445, 'local:warsh-text.json'),
  ('warsh-36-77', 'warsh', 36, 77, 'وَضَرَبَ لَنَا مَثَلاࣰ وَنَسِيَ خَلْقَهُۥ࣌ قَالَ مَنْ يُّحْيِ ࡴ۬لْعِظَٰمَ وَهِيَ رَمِيمࣱ࣌', 'وضرب لنا مثلا ونسي خلقه࣌ قال من يحي ࡴلعظم وهي رميم࣌', NULL, 445, 'local:warsh-text.json'),
  ('warsh-36-78', 'warsh', 36, 78, 'قُلْ يُحْيِيهَا ࡰ۬لذِےٓ أَنشَأَهَآ أَوَّلَ مَرَّةࣲ وَهُوَ بِكُلِّ خَلْقٍ عَلِيمٌ࣌', 'قل يحييها ࡰلذے أنشأها أول مرة وهو بكل خلق عليم࣌', NULL, 445, 'local:warsh-text.json'),
  ('warsh-36-79', 'warsh', 36, 79, '۞ ࡴ۬لذِے جَعَلَ لَكُم مِّنَ ࡰ۬لشَّجَرِ ࡴ۬لَاخْضَرِ نَاراࣰ فَإِذَآ أَنتُم مِّنْهُ تُوقِدُونَ࣌', 'ࡴلذے جعل لكم من ࡰلشجر ࡴلاخضر نارا فإذا أنتم منه توقدون࣌', NULL, 445, 'local:warsh-text.json'),
  ('warsh-36-80', 'warsh', 36, 80, 'أَوَلَيْسَ ࡰ۬لذِے خَلَقَ ࡰ۬لسَّمَٰوَٰتِ وَالَارْضَ بِقَٰدِرٍ عَلَىٰٓ أَنْ يَّخْلُقَ مِثْلَهُم࣌ بَلٜىٰ وَهُوَ ࡰ۬لْخَلَّٰقُ ࡲ۬لْعَلِيمُ࣌', 'أوليس ࡰلذے خلق ࡰلسموت والارض بقدر على أن يخلق مثلهم࣌ بلى وهو ࡰلخلق ࡲلعليم࣌', NULL, 445, 'local:warsh-text.json'),
  ('warsh-36-81', 'warsh', 36, 81, 'إِنَّمَآ أَمْرُهُۥٓ إِذَآ أَرَادَ شَيْـٔاً ࡰنْ يَّقُولَ لَهُۥ كُن࣌ فَيَكُونُ࣌', 'إنما أمره إذا أراد شيا ࡰن يقول له كن࣌ فيكون࣌', NULL, 445, 'local:warsh-text.json'),
  ('warsh-36-82', 'warsh', 36, 82, 'فَسُبْحَٰنَ ࡰ۬لذِے بِيَدِهِۦ مَلَكُوتُ كُلِّ شَےْءࣲ وَإِلَيْهِ تُرْجَعُونَ࣌', 'فسبحن ࡰلذے بيده ملكوت كل شےء وإليه ترجعون࣌', NULL, 445, 'local:warsh-text.json'),
  ('warsh-37-1', 'warsh', 37, 1, 'وَالصَّٰٓفَّٰتِ صَفّاࣰ', 'والصفت صفا', NULL, 446, 'local:warsh-text.json'),
  ('warsh-37-2', 'warsh', 37, 2, 'فَالزَّٰجِرَٰتِ زَجْراࣰ', 'فالزجرت زجرا', NULL, 446, 'local:warsh-text.json'),
  ('warsh-37-3', 'warsh', 37, 3, 'فَالتَّٰلِيَٰتِ ذِكْراً', 'فالتليت ذكرا', NULL, 446, 'local:warsh-text.json'),
  ('warsh-37-4', 'warsh', 37, 4, 'ࡴنَّ إِلَٰهَكُمْ لَوَٰحِدࣱ࣌', 'ࡴن إلهكم لوحد࣌', NULL, 446, 'local:warsh-text.json'),
  ('warsh-37-5', 'warsh', 37, 5, 'رَّبُّ ࡲ۬لسَّمَٰوَٰتِ وَالَارْضِ وَمَا بَيْنَهُمَا وَرَبُّ ࡲ۬لْمَشَٰرِقِ࣌', 'رب ࡲلسموت والارض وما بينهما ورب ࡲلمشرق࣌', NULL, 446, 'local:warsh-text.json'),
  ('warsh-37-6', 'warsh', 37, 6, 'إِنَّا زَيَّنَّا ࡰ۬لسَّمَآءَ ࡰ۬لدُّنْيٜا بِزِينَةِ ࡴ۬لْكَوَاكِبِ࣌', 'إنا زينا ࡰلسماء ࡰلدنيا بزينة ࡴلكواكب࣌', NULL, 446, 'local:warsh-text.json'),
  ('warsh-37-7', 'warsh', 37, 7, 'وَحِفْظاࣰ مِّن كُلِّ شَيْطَٰنࣲ مَّارِدࣲ࣌', 'وحفظا من كل شيطن مارد࣌', NULL, 446, 'local:warsh-text.json'),
  ('warsh-37-8', 'warsh', 37, 8, 'لَّا يَسْمَعُونَ إِلَى ࡰ۬لْمَلَإِ ࡴ۬لَاعْلٜىٰ وَيُقْذَفُونَ مِن كُلِّ جَانِبࣲ࣌', 'لا يسمعون إلى ࡰلملإ ࡴلاعلى ويقذفون من كل جانب࣌', NULL, 446, 'local:warsh-text.json'),
  ('warsh-37-9', 'warsh', 37, 9, 'دُحُوراࣰ࣌ وَلَهُمْ عَذَابࣱ وَاصِبٌ', 'دحورا࣌ ولهم عذاب واصب', NULL, 446, 'local:warsh-text.json'),
  ('warsh-37-10', 'warsh', 37, 10, 'ࡴلَّا مَنْ خَطِفَ ࡰ۬لْخَطْفَةَ فَأَتْبَعَهُۥ شِهَابࣱ ثَاقِبࣱ࣌', 'ࡴلا من خطف ࡰلخطفة فأتبعه شهاب ثاقب࣌', NULL, 446, 'local:warsh-text.json'),
  ('warsh-37-11', 'warsh', 37, 11, 'فَاسْتَفْتِهِمُۥٓ أَهُمُۥٓ أَشَدُّ خَلْقاً ࡰم مَّنْ خَلَقْنَآ࣌ إِنَّا خَلَقْنَٰهُم مِّن طِينࣲ لَّٰزِبِۢ࣌', 'فاستفتهم أهم أشد خلقا ࡰم من خلقنا࣌ إنا خلقنهم من طين لزب࣌', NULL, 446, 'local:warsh-text.json'),
  ('warsh-37-12', 'warsh', 37, 12, 'بَلْ عَجِبْتَ وَيَسْخَرُونَ࣌', 'بل عجبت ويسخرون࣌', NULL, 446, 'local:warsh-text.json'),
  ('warsh-37-13', 'warsh', 37, 13, 'وَإِذَا ذُكِّرُواْ لَا يَذْكُرُونَ࣌', 'وإذا ذكروا لا يذكرون࣌', NULL, 446, 'local:warsh-text.json'),
  ('warsh-37-14', 'warsh', 37, 14, 'وَإِذَا رَأَوَاْ اٰيَةࣰ يَسْتَسْخِرُونَ࣌', 'وإذا رأوا اية يستسخرون࣌', NULL, 446, 'local:warsh-text.json'),
  ('warsh-37-15', 'warsh', 37, 15, 'وَقَالُوٓاْ إِنْ هَٰذَآ إِلَّا سِحْرࣱ مُّبِينٌ', 'وقالوا إن هذا إلا سحر مبين', NULL, 446, 'local:warsh-text.json'),
  ('warsh-37-16', 'warsh', 37, 16, 'ࡰࢇذَا مِتْنَا وَكُنَّا تُرَاباࣰ وَعِظَٰماً ࡴنَّا لَمَبْعُوثُونَ', 'ࡰࢇذا متنا وكنا ترابا وعظما ࡴنا لمبعوثون', NULL, 446, 'local:warsh-text.json'),
  ('warsh-37-17', 'warsh', 37, 17, 'أَوَءَابَآؤُنَا ࡰ۬لَاوَّلُونَ࣌', 'أوءاباؤنا ࡰلاولون࣌', NULL, 446, 'local:warsh-text.json'),
  ('warsh-37-18', 'warsh', 37, 18, 'قُلْ نَعَمْ وَأَنتُمْ دَٰخِرُونَ࣌', 'قل نعم وأنتم دخرون࣌', NULL, 446, 'local:warsh-text.json'),
  ('warsh-37-19', 'warsh', 37, 19, 'فَإِنَّمَا هِيَ زَجْرَةࣱ وَٰحِدَةࣱ فَإِذَا هُمْ يَنظُرُونَ࣌', 'فإنما هي زجرة وحدة فإذا هم ينظرون࣌', NULL, 446, 'local:warsh-text.json'),
  ('warsh-37-20', 'warsh', 37, 20, 'وَقَالُواْ يَٰوَيْلَنَا هَٰذَا يَوْمُ ࡲ۬لدِّينِ࣌', 'وقالوا يويلنا هذا يوم ࡲلدين࣌', NULL, 446, 'local:warsh-text.json'),
  ('warsh-37-21', 'warsh', 37, 21, 'هَٰذَا يَوْمُ ࡲ۬لْفَصْلِ ࡴ۬لذِے كُنتُم بِهِۦ تُكَذِّبُونَ࣌', 'هذا يوم ࡲلفصل ࡴلذے كنتم به تكذبون࣌', NULL, 446, 'local:warsh-text.json'),
  ('warsh-37-22', 'warsh', 37, 22, '۞ ࡸَحْشُرُواْ ࡲ۬لذِينَ ظَلَمُواْ وَأَزْوَٰجَهُمْ وَمَا كَانُواْ يَعْبُدُونَ', 'ࡸحشروا ࡲلذين ظلموا وأزوجهم وما كانوا يعبدون', NULL, 446, 'local:warsh-text.json'),
  ('warsh-37-23', 'warsh', 37, 23, 'مِن دُونِ ࡴ۬للَّهِ فَاهْدُوهُمُۥٓ إِلَىٰ صِرَٰطِ ࡴ۬لْجَحِيمِ࣌', 'من دون ࡴلله فاهدوهم إلى صرط ࡴلجحيم࣌', NULL, 446, 'local:warsh-text.json'),
  ('warsh-37-24', 'warsh', 37, 24, 'وَقِفُوهُمُۥٓ إِنَّهُم مَّسْـُٔولُونَ࣌', 'وقفوهم إنهم مسولون࣌', NULL, 446, 'local:warsh-text.json'),
  ('warsh-37-25', 'warsh', 37, 25, 'مَا لَكُمْ لَا تَنَاصَرُونَ࣌', 'ما لكم لا تناصرون࣌', NULL, 447, 'local:warsh-text.json'),
  ('warsh-37-26', 'warsh', 37, 26, 'بَلْ هُمُ ࡲ۬لْيَوْمَ مُسْتَسْلِمُونَ࣌', 'بل هم ࡲليوم مستسلمون࣌', NULL, 447, 'local:warsh-text.json'),
  ('warsh-37-27', 'warsh', 37, 27, 'وَأَقْبَلَ بَعْضُهُمْ عَلَىٰ بَعْضࣲ يَتَسَآءَلُونَ࣌', 'وأقبل بعضهم على بعض يتساءلون࣌', NULL, 447, 'local:warsh-text.json'),
  ('warsh-37-28', 'warsh', 37, 28, 'قَالُوٓاْ إِنَّكُمْ كُنتُمْ تَاتُونَنَا عَنِ ࡴ۬لْيَمِينِ࣌', 'قالوا إنكم كنتم تاتوننا عن ࡴليمين࣌', NULL, 447, 'local:warsh-text.json'),
  ('warsh-37-29', 'warsh', 37, 29, 'قَالُواْ بَل لَّمْ تَكُونُواْ مُومِنِينَ࣌', 'قالوا بل لم تكونوا مومنين࣌', NULL, 447, 'local:warsh-text.json'),
  ('warsh-37-30', 'warsh', 37, 30, 'وَمَا كَانَ لَنَا عَلَيْكُم مِّن سُلْطَٰنِۢ بَلْ كُنتُمْ قَوْماࣰ طَٰغِينَ࣌', 'وما كان لنا عليكم من سلطن بل كنتم قوما طغين࣌', NULL, 447, 'local:warsh-text.json'),
  ('warsh-37-31', 'warsh', 37, 31, 'فَحَقَّ عَلَيْنَا قَوْلُ رَبِّنَآ إِنَّا لَذَآئِقُونَ', 'فحق علينا قول ربنا إنا لذائقون', NULL, 447, 'local:warsh-text.json'),
  ('warsh-37-32', 'warsh', 37, 32, 'فَأَغْوَيْنَٰكُمُۥٓ إِنَّا كُنَّا غَٰوِينَ࣌', 'فأغوينكم إنا كنا غوين࣌', NULL, 447, 'local:warsh-text.json'),
  ('warsh-37-33', 'warsh', 37, 33, 'فَإِنَّهُمْ يَوْمَئِذࣲ فِے ࡴ۬لْعَذَابِ مُشْتَرِكُونَ࣌', 'فإنهم يومئذ فے ࡴلعذاب مشتركون࣌', NULL, 447, 'local:warsh-text.json'),
  ('warsh-37-34', 'warsh', 37, 34, 'إِنَّا كَذَٰلِكَ نَفْعَلُ بِالْمُجْرِمِينَ࣌', 'إنا كذلك نفعل بالمجرمين࣌', NULL, 447, 'local:warsh-text.json'),
  ('warsh-37-35', 'warsh', 37, 35, 'إِنَّهُمْ كَانُوٓاْ إِذَا قِيلَ لَهُمْ لَآ إِلَٰهَ إِلَّا ࡰ۬للَّهُ يَسْتَكْبِرُونَ', 'إنهم كانوا إذا قيل لهم لا إله إلا ࡰلله يستكبرون', NULL, 447, 'local:warsh-text.json'),
  ('warsh-37-36', 'warsh', 37, 36, 'وَيَقُولُونَ أَئِنَّا لَتَارِكُوٓاْ ءَالِهَتِنَا لِشَاعِرࣲ مَّجْنُونِۢ࣌', 'ويقولون أئنا لتاركوا ءالهتنا لشاعر مجنون࣌', NULL, 447, 'local:warsh-text.json'),
  ('warsh-37-37', 'warsh', 37, 37, 'بَلْ جَآءَ بِالْحَقِّ وَصَدَّقَ ࡰ۬لْمُرْسَلِينَ࣌', 'بل جاء بالحق وصدق ࡰلمرسلين࣌', NULL, 447, 'local:warsh-text.json'),
  ('warsh-37-38', 'warsh', 37, 38, 'إِنَّكُمْ لَذَآئِقُواْ ࡲ۬لْعَذَابِ ࡴ۬لَالِيمِ࣌', 'إنكم لذائقوا ࡲلعذاب ࡴلاليم࣌', NULL, 447, 'local:warsh-text.json'),
  ('warsh-37-39', 'warsh', 37, 39, 'وَمَا تُجْزَوْنَ إِلَّا مَا كُنتُمْ تَعْمَلُونَ', 'وما تجزون إلا ما كنتم تعملون', NULL, 447, 'local:warsh-text.json'),
  ('warsh-37-40', 'warsh', 37, 40, 'إِلَّا عِبَادَ ࡰ۬للَّهِ ࡴ۬لْمُخْلَصِينَ࣌', 'إلا عباد ࡰلله ࡴلمخلصين࣌', NULL, 447, 'local:warsh-text.json'),
  ('warsh-37-41', 'warsh', 37, 41, 'أُوْلَٰٓئِكَ لَهُمْ رِزْقࣱ مَّعْلُومࣱ', 'أولئك لهم رزق معلوم', NULL, 447, 'local:warsh-text.json'),
  ('warsh-37-42', 'warsh', 37, 42, 'فَوَٰكِهُ࣌ وَهُم مُّكْرَمُونَ', 'فوكه࣌ وهم مكرمون', NULL, 447, 'local:warsh-text.json'),
  ('warsh-37-43', 'warsh', 37, 43, 'فِے جَنَّٰتِ ࡴ۬لنَّعِيمِ', 'فے جنت ࡴلنعيم', NULL, 447, 'local:warsh-text.json'),
  ('warsh-37-44', 'warsh', 37, 44, 'عَلَىٰ سُرُرࣲ مُّتَقَٰبِلِينَ࣌', 'على سرر متقبلين࣌', NULL, 447, 'local:warsh-text.json'),
  ('warsh-37-45', 'warsh', 37, 45, 'يُطَافُ عَلَيْهِم بِكَأْسࣲ مِّن مَّعِينِۢ', 'يطاف عليهم بكأس من معين', NULL, 447, 'local:warsh-text.json'),
  ('warsh-37-46', 'warsh', 37, 46, 'بَيْضَآءَ لَذَّةࣲ لِّلشَّٰرِبِينَ', 'بيضاء لذة للشربين', NULL, 447, 'local:warsh-text.json'),
  ('warsh-37-47', 'warsh', 37, 47, 'لَا فِيهَا غَوْلࣱ وَلَا هُمْ عَنْهَا يُنزَفُونَ࣌', 'لا فيها غول ولا هم عنها ينزفون࣌', NULL, 447, 'local:warsh-text.json'),
  ('warsh-37-48', 'warsh', 37, 48, 'وَعِندَهُمْ قَٰصِرَٰتُ ࡲ۬لطَّرْفِ عِينࣱ', 'وعندهم قصرت ࡲلطرف عين', NULL, 447, 'local:warsh-text.json'),
  ('warsh-37-49', 'warsh', 37, 49, 'كَأَنَّهُنَّ بَيْضࣱ مَّكْنُونࣱ࣌', 'كأنهن بيض مكنون࣌', NULL, 447, 'local:warsh-text.json'),
  ('warsh-37-50', 'warsh', 37, 50, 'فَأَقْبَلَ بَعْضُهُمْ عَلَىٰ بَعْضࣲ يَتَسَآءَلُونَ࣌', 'فأقبل بعضهم على بعض يتساءلون࣌', NULL, 447, 'local:warsh-text.json'),
  ('warsh-37-51', 'warsh', 37, 51, '۞ قَالَ قَآئِلࣱ مِّنْهُمُۥٓ إِنِّے كَانَ لِے قَرِينࣱ', 'قال قائل منهم إنے كان لے قرين', NULL, 447, 'local:warsh-text.json'),
  ('warsh-37-52', 'warsh', 37, 52, 'يَقُولُ أَࢇنَّكَ لَمِنَ ࡰ۬لْمُصَدِّقِينَ', 'يقول أࢇنك لمن ࡰلمصدقين', NULL, 448, 'local:warsh-text.json'),
  ('warsh-37-53', 'warsh', 37, 53, 'أَࢇذَا مِتْنَا وَكُنَّا تُرَاباࣰ وَعِظَٰماً ࡴنَّا لَمَدِينُونَ࣌', 'أࢇذا متنا وكنا ترابا وعظما ࡴنا لمدينون࣌', NULL, 448, 'local:warsh-text.json'),
  ('warsh-37-54', 'warsh', 37, 54, 'قَالَ هَلَ ࡰنتُم مُّطَّلِعُونَ', 'قال هل ࡰنتم مطلعون', NULL, 448, 'local:warsh-text.json'),
  ('warsh-37-55', 'warsh', 37, 55, 'فَاطَّلَعَ فَرٜءٜاهُ فِے سَوَآءِ ࡴ۬لْجَحِيمِ࣌', 'فاطلع فرءاه فے سواء ࡴلجحيم࣌', NULL, 448, 'local:warsh-text.json'),
  ('warsh-37-56', 'warsh', 37, 56, 'قَالَ تَاللَّهِ إِن كِدتَّ لَتُرْدِينِۦ', 'قال تالله إن كدت لتردين', NULL, 448, 'local:warsh-text.json'),
  ('warsh-37-57', 'warsh', 37, 57, 'وَلَوْلَا نِعْمَةُ رَبِّے لَكُنتُ مِنَ ࡰ۬لْمُحْضَرِينَ࣌', 'ولولا نعمة ربے لكنت من ࡰلمحضرين࣌', NULL, 448, 'local:warsh-text.json'),
  ('warsh-37-58', 'warsh', 37, 58, 'أَفَمَا نَحْنُ بِمَيِّتِينَ', 'أفما نحن بميتين', NULL, 448, 'local:warsh-text.json'),
  ('warsh-37-59', 'warsh', 37, 59, 'إِلَّا مَوْتَتَنَا ࡰ۬لُاولٜىٰ وَمَا نَحْنُ بِمُعَذَّبِينَ࣌', 'إلا موتتنا ࡰلاولى وما نحن بمعذبين࣌', NULL, 448, 'local:warsh-text.json'),
  ('warsh-37-60', 'warsh', 37, 60, 'إِنَّ هَٰذَا لَهُوَ ࡰ۬لْفَوْزُ ࡲ۬لْعَظِيمُ࣌', 'إن هذا لهو ࡰلفوز ࡲلعظيم࣌', NULL, 448, 'local:warsh-text.json'),
  ('warsh-37-61', 'warsh', 37, 61, 'لِمِثْلِ هَٰذَا فَلْيَعْمَلِ ࡴ۬لْعَٰمِلُونَ࣌', 'لمثل هذا فليعمل ࡴلعملون࣌', NULL, 448, 'local:warsh-text.json'),
  ('warsh-37-62', 'warsh', 37, 62, 'أَذَٰلِكَ خَيْرࣱ نُّزُلاً ࡰمْ شَجَرَةُ ࡲ۬لزَّقُّومِ࣌', 'أذلك خير نزلا ࡰم شجرة ࡲلزقوم࣌', NULL, 448, 'local:warsh-text.json'),
  ('warsh-37-63', 'warsh', 37, 63, 'إِنَّا جَعَلْنَٰهَا فِتْنَةࣰ لِّلظَّٰلِمِينَ࣌', 'إنا جعلنها فتنة للظلمين࣌', NULL, 448, 'local:warsh-text.json'),
  ('warsh-37-64', 'warsh', 37, 64, 'إِنَّهَا شَجَرَةࣱ تَخْرُجُ فِےٓ أَصْلِ ࡴ۬لْجَحِيمِ', 'إنها شجرة تخرج فے أصل ࡴلجحيم', NULL, 448, 'local:warsh-text.json'),
  ('warsh-37-65', 'warsh', 37, 65, 'طَلْعُهَا كَأَنَّهُۥ رُءُوسُ ࡲ۬لشَّيَٰطِينِ࣌', 'طلعها كأنه رءوس ࡲلشيطين࣌', NULL, 448, 'local:warsh-text.json'),
  ('warsh-37-66', 'warsh', 37, 66, 'فَإِنَّهُمْ لَأٓكِلُونَ مِنْهَا فَمَالِـُٔونَ مِنْهَا ࡰ۬لْبُطُونَ', 'فإنهم لأكلون منها فمالون منها ࡰلبطون', NULL, 448, 'local:warsh-text.json'),
  ('warsh-37-67', 'warsh', 37, 67, 'ثُمَّ إِنَّ لَهُمْ عَلَيْهَا لَشَوْباࣰ مِّنْ حَمِيمࣲ࣌', 'ثم إن لهم عليها لشوبا من حميم࣌', NULL, 448, 'local:warsh-text.json'),
  ('warsh-37-68', 'warsh', 37, 68, 'ثُمَّ إِنَّ مَرْجِعَهُمْ لَإِلَى ࡰ۬لْجَحِيمِ࣌', 'ثم إن مرجعهم لإلى ࡰلجحيم࣌', NULL, 448, 'local:warsh-text.json'),
  ('warsh-37-69', 'warsh', 37, 69, 'إِنَّهُمُۥٓ أَلْفَوَاْ اٰبَآءَهُمْ ضَآلِّينَ', 'إنهم ألفوا اباءهم ضالين', NULL, 448, 'local:warsh-text.json'),
  ('warsh-37-70', 'warsh', 37, 70, 'فَهُمْ عَلَىٰٓ ءَاثٜـٰرِهِمْ يُهْرَعُونَ࣌', 'فهم على ءاثرهم يهرعون࣌', NULL, 448, 'local:warsh-text.json'),
  ('warsh-37-71', 'warsh', 37, 71, 'وَلَقَد ضَّلَّ قَبْلَهُمُۥٓ أَكْثَرُ ࡲ۬لَاوَّلِينَ࣌', 'ولقد ضل قبلهم أكثر ࡲلاولين࣌', NULL, 448, 'local:warsh-text.json'),
  ('warsh-37-72', 'warsh', 37, 72, 'وَلَقَدَ ࡰرْسَلْنَا فِيهِم مُّنذِرِينَ࣌', 'ولقد ࡰرسلنا فيهم منذرين࣌', NULL, 448, 'local:warsh-text.json'),
  ('warsh-37-73', 'warsh', 37, 73, 'فَانظُرْ كَيْفَ كَانَ عَٰقِبَةُ ࡲ۬لْمُنذَرِينَ', 'فانظر كيف كان عقبة ࡲلمنذرين', NULL, 448, 'local:warsh-text.json'),
  ('warsh-37-74', 'warsh', 37, 74, 'إِلَّا عِبَادَ ࡰ۬للَّهِ ࡴ۬لْمُخْلَصِينَ࣌', 'إلا عباد ࡰلله ࡴلمخلصين࣌', NULL, 448, 'local:warsh-text.json'),
  ('warsh-37-75', 'warsh', 37, 75, 'وَلَقَدْ نَادٜيٰنَا نُوحࣱ࣌ فَلَنِعْمَ ࡰ۬لْمُجِيبُونَ࣌', 'ولقد نادينا نوح࣌ فلنعم ࡰلمجيبون࣌', NULL, 448, 'local:warsh-text.json'),
  ('warsh-37-76', 'warsh', 37, 76, 'وَنَجَّيْنَٰهُ وَأَهْلَهُۥ مِنَ ࡰ۬لْكَرْبِ ࡴ۬لْعَظِيمِ࣌', 'ونجينه وأهله من ࡰلكرب ࡴلعظيم࣌', NULL, 448, 'local:warsh-text.json'),
  ('warsh-37-77', 'warsh', 37, 77, 'وَجَعَلْنَا ذُرِّيَّتَهُۥ هُمُ ࡲ۬لْبَاقِينَ࣌', 'وجعلنا ذريته هم ࡲلباقين࣌', NULL, 449, 'local:warsh-text.json'),
  ('warsh-37-78', 'warsh', 37, 78, 'وَتَرَكْنَا عَلَيْهِ فِے ࡴ۬لَاخِرِينَ࣌', 'وتركنا عليه فے ࡴلاخرين࣌', NULL, 449, 'local:warsh-text.json'),
  ('warsh-37-79', 'warsh', 37, 79, 'سَلَٰمٌ عَلَىٰ نُوحࣲ فِے ࡴ۬لْعَٰلَمِينَ࣌', 'سلم على نوح فے ࡴلعلمين࣌', NULL, 449, 'local:warsh-text.json'),
  ('warsh-37-80', 'warsh', 37, 80, 'إِنَّا كَذَٰلِكَ نَجْزِے ࡴ۬لْمُحْسِنِينَ࣌', 'إنا كذلك نجزے ࡴلمحسنين࣌', NULL, 449, 'local:warsh-text.json'),
  ('warsh-37-81', 'warsh', 37, 81, 'إِنَّهُۥ مِنْ عِبَادِنَا ࡰ۬لْمُومِنِينَ࣌', 'إنه من عبادنا ࡰلمومنين࣌', NULL, 449, 'local:warsh-text.json'),
  ('warsh-37-82', 'warsh', 37, 82, 'ثُمَّ أَغْرَقْنَا ࡰ۬لَاخَرِينَ࣌', 'ثم أغرقنا ࡰلاخرين࣌', NULL, 449, 'local:warsh-text.json'),
  ('warsh-37-83', 'warsh', 37, 83, '۞ وَإِنَّ مِن شِيعَتِهِۦ لَإِبْرَٰهِيمَ', 'وإن من شيعته لإبرهيم', NULL, 449, 'local:warsh-text.json'),
  ('warsh-37-84', 'warsh', 37, 84, 'إِذْ جَآءَ رَبَّهُۥ بِقَلْبࣲ سَلِيمٍ', 'إذ جاء ربه بقلب سليم', NULL, 449, 'local:warsh-text.json'),
  ('warsh-37-85', 'warsh', 37, 85, 'ࡴذْ قَالَ لِأَبِيهِ وَقَوْمِهِۦ مَاذَا تَعْبُدُونَ࣌', 'ࡴذ قال لأبيه وقومه ماذا تعبدون࣌', NULL, 449, 'local:warsh-text.json'),
  ('warsh-37-86', 'warsh', 37, 86, 'أَئِفْكاً اٰلِهَةࣰ دُونَ ࡰ۬للَّهِ تُرِيدُونَ࣌', 'أئفكا الهة دون ࡰلله تريدون࣌', NULL, 449, 'local:warsh-text.json'),
  ('warsh-37-87', 'warsh', 37, 87, 'فَمَا ظَنُّكُم بِرَبِّ ࡴ۬لْعَٰلَمِينَ࣌', 'فما ظنكم برب ࡴلعلمين࣌', NULL, 449, 'local:warsh-text.json'),
  ('warsh-37-88', 'warsh', 37, 88, 'فَنَظَرَ نَظْرَةࣰ فِے ࡴ۬لنُّجُومِ', 'فنظر نظرة فے ࡴلنجوم', NULL, 449, 'local:warsh-text.json'),
  ('warsh-37-89', 'warsh', 37, 89, 'فَقَالَ إِنِّے سَقِيمࣱ', 'فقال إنے سقيم', NULL, 449, 'local:warsh-text.json'),
  ('warsh-37-90', 'warsh', 37, 90, 'فَتَوَلَّوْاْ عَنْهُ مُدْبِرِينَ࣌', 'فتولوا عنه مدبرين࣌', NULL, 449, 'local:warsh-text.json'),
  ('warsh-37-91', 'warsh', 37, 91, 'فَرَاغَ إِلَىٰٓ ءَالِهَتِهِمْ فَقَالَ أَلَا تَاكُلُونَ', 'فراغ إلى ءالهتهم فقال ألا تاكلون', NULL, 449, 'local:warsh-text.json'),
  ('warsh-37-92', 'warsh', 37, 92, 'مَا لَكُمْ لَا تَنطِقُونَ࣌', 'ما لكم لا تنطقون࣌', NULL, 449, 'local:warsh-text.json'),
  ('warsh-37-93', 'warsh', 37, 93, 'فَرَاغَ عَلَيْهِمْ ضَرْباَۢ بِالْيَمِينِ', 'فراغ عليهم ضربا باليمين', NULL, 449, 'local:warsh-text.json'),
  ('warsh-37-94', 'warsh', 37, 94, 'فَأَقْبَلُوٓاْ إِلَيْهِ يَزِفُّونَ࣌', 'فأقبلوا إليه يزفون࣌', NULL, 449, 'local:warsh-text.json'),
  ('warsh-37-95', 'warsh', 37, 95, 'قَالَ أَتَعْبُدُونَ مَا تَنْحِتُونَ', 'قال أتعبدون ما تنحتون', NULL, 449, 'local:warsh-text.json'),
  ('warsh-37-96', 'warsh', 37, 96, 'وَاللَّهُ خَلَقَكُمْ وَمَا تَعْمَلُونَ࣌', 'والله خلقكم وما تعملون࣌', NULL, 449, 'local:warsh-text.json'),
  ('warsh-37-97', 'warsh', 37, 97, 'قَالُواْ ࡲٜبْنُواْ لَهُۥ بُنْيَٰناࣰ فَأَلْقُوهُ فِے ࡴ۬لْجَحِيمِ', 'قالوا ࡲبنوا له بنينا فألقوه فے ࡴلجحيم', NULL, 449, 'local:warsh-text.json'),
  ('warsh-37-98', 'warsh', 37, 98, 'فَأَرَادُواْ بِهِۦ كَيْداࣰ فَجَعَلْنَٰهُمُ ࡲ۬لَاسْفَلِينَ࣌', 'فأرادوا به كيدا فجعلنهم ࡲلاسفلين࣌', NULL, 449, 'local:warsh-text.json'),
  ('warsh-37-99', 'warsh', 37, 99, 'وَقَالَ إِنِّے ذَاهِبٌ ࡴلَىٰ رَبِّے سَيَهْدِينِ࣌', 'وقال إنے ذاهب ࡴلى ربے سيهدين࣌', NULL, 449, 'local:warsh-text.json'),
  ('warsh-37-100', 'warsh', 37, 100, 'رَبِّ هَبْ لِے مِنَ ࡰ۬لصَّٰلِحِينَ࣌', 'رب هب لے من ࡰلصلحين࣌', NULL, 449, 'local:warsh-text.json'),
  ('warsh-37-101', 'warsh', 37, 101, 'فَبَشَّرْنَٰهُ بِغُلَٰمٍ حَلِيمࣲ࣌', 'فبشرنه بغلم حليم࣌', NULL, 449, 'local:warsh-text.json'),
  ('warsh-37-102', 'warsh', 37, 102, 'فَلَمَّا بَلَغَ مَعَهُ ࡲ۬لسَّعْيَ قَالَ يَٰبُنَيِّ إِنِّيَ أَرٜىٰ فِے ࡴ۬لْمَنَامِ أَنِّيَ أَذْبَحُكَ فَانظُرْ مَاذَا تَرٜىٰ࣌ قَالَ يَٰٓأَبَتِ ࡴٜفْعَلْ مَا تُومَرُ࣌ سَتَجِدُنِيَ إِن شَآءَ ࡰ۬للَّهُ مِنَ ࡰ۬لصَّٰبِرِينَ࣌', 'فلما بلغ معه ࡲلسعي قال يبني إني أرى فے ࡴلمنام أني أذبحك فانظر ماذا ترى࣌ قال يأبت ࡴفعل ما تومر࣌ ستجدني إن شاء ࡰلله من ࡰلصبرين࣌', NULL, 449, 'local:warsh-text.json'),
  ('warsh-37-103', 'warsh', 37, 103, 'فَلَمَّآ أَسْلَمَا وَتَلَّهُۥ لِلْجَبِينِ', 'فلما أسلما وتله للجبين', NULL, 450, 'local:warsh-text.json'),
  ('warsh-37-104', 'warsh', 37, 104, 'وَنَٰدَيْنَٰهُ أَنْ يَّٰٓإِبْرَٰهِيمُ', 'وندينه أن يإبرهيم', NULL, 450, 'local:warsh-text.json'),
  ('warsh-37-105', 'warsh', 37, 105, 'قَدْ صَدَّقْتَ ࡰ۬لرُّءْيٜآ࣌ إِنَّا كَذَٰلِكَ نَجْزِے ࡴ۬لْمُحْسِنِينَ࣌', 'قد صدقت ࡰلرءيا࣌ إنا كذلك نجزے ࡴلمحسنين࣌', NULL, 450, 'local:warsh-text.json'),
  ('warsh-37-106', 'warsh', 37, 106, 'إِنَّ هَٰذَا لَهُوَ ࡰ۬لْبَلَٰٓؤُاْ ࡲ۬لْمُبِينُ࣌', 'إن هذا لهو ࡰلبلؤا ࡲلمبين࣌', NULL, 450, 'local:warsh-text.json'),
  ('warsh-37-107', 'warsh', 37, 107, 'وَفَدَيْنَٰهُ بِذِبْحٍ عَظِيمࣲ࣌', 'وفدينه بذبح عظيم࣌', NULL, 450, 'local:warsh-text.json'),
  ('warsh-37-108', 'warsh', 37, 108, 'وَتَرَكْنَا عَلَيْهِ فِے ࡴ۬لَاخِرِينَ࣌', 'وتركنا عليه فے ࡴلاخرين࣌', NULL, 450, 'local:warsh-text.json'),
  ('warsh-37-109', 'warsh', 37, 109, 'سَلَٰمٌ عَلَىٰٓ إِبْرَٰهِيمَ࣌', 'سلم على إبرهيم࣌', NULL, 450, 'local:warsh-text.json'),
  ('warsh-37-110', 'warsh', 37, 110, 'كَذَٰلِكَ نَجْزِے ࡴ۬لْمُحْسِنِينَ࣌', 'كذلك نجزے ࡴلمحسنين࣌', NULL, 450, 'local:warsh-text.json'),
  ('warsh-37-111', 'warsh', 37, 111, 'إِنَّهُۥ مِنْ عِبَادِنَا ࡰ۬لْمُومِنِينَ࣌', 'إنه من عبادنا ࡰلمومنين࣌', NULL, 450, 'local:warsh-text.json'),
  ('warsh-37-112', 'warsh', 37, 112, 'وَبَشَّرْنَٰهُ بِإِسْحَٰقَ نَبِيٓـٔاࣰ مِّنَ ࡰ۬لصَّٰلِحِينَ', 'وبشرنه بإسحق نبيا من ࡰلصلحين', NULL, 450, 'local:warsh-text.json'),
  ('warsh-37-113', 'warsh', 37, 113, 'وَبَٰرَكْنَا عَلَيْهِ وَعَلَىٰٓ إِسْحَٰقَ࣌ وَمِن ذُرِّيَّتِهِمَا مُحْسِنࣱ وَظَالِمࣱ لِّنَفْسِهِۦ مُبِينࣱ࣌', 'وبركنا عليه وعلى إسحق࣌ ومن ذريتهما محسن وظالم لنفسه مبين࣌', NULL, 450, 'local:warsh-text.json'),
  ('warsh-37-114', 'warsh', 37, 114, '۞ وَلَقَدْ مَنَنَّا عَلَىٰ مُوسٜىٰ وَهَٰرُونَ', 'ولقد مننا على موسى وهرون', NULL, 450, 'local:warsh-text.json'),
  ('warsh-37-115', 'warsh', 37, 115, 'وَنَجَّيْنَٰهُمَا وَقَوْمَهُمَا مِنَ ࡰ۬لْكَرْبِ ࡴ۬لْعَظِيمِ࣌', 'ونجينهما وقومهما من ࡰلكرب ࡴلعظيم࣌', NULL, 450, 'local:warsh-text.json'),
  ('warsh-37-116', 'warsh', 37, 116, 'وَنَصَرْنَٰهُمْ فَكَانُواْ هُمُ ࡲ۬لْغَٰلِبِينَ࣌', 'ونصرنهم فكانوا هم ࡲلغلبين࣌', NULL, 450, 'local:warsh-text.json'),
  ('warsh-37-117', 'warsh', 37, 117, 'وَءَاتَيْنَٰهُمَا ࡰ۬لْكِتَٰبَ ࡰ۬لْمُسْتَبِينَ࣌', 'وءاتينهما ࡰلكتب ࡰلمستبين࣌', NULL, 450, 'local:warsh-text.json'),
  ('warsh-37-118', 'warsh', 37, 118, 'وَهَدَيْنَٰهُمَا ࡰ۬لصِّرَٰطَ ࡰ۬لْمُسْتَقِيمَ࣌', 'وهدينهما ࡰلصرط ࡰلمستقيم࣌', NULL, 450, 'local:warsh-text.json'),
  ('warsh-37-119', 'warsh', 37, 119, 'وَتَرَكْنَا عَلَيْهِمَا فِے ࡴ۬لَاخِرِينَ࣌', 'وتركنا عليهما فے ࡴلاخرين࣌', NULL, 450, 'local:warsh-text.json'),
  ('warsh-37-120', 'warsh', 37, 120, 'سَلَٰمٌ عَلَىٰ مُوسٜىٰ وَهَٰرُونَ࣌', 'سلم على موسى وهرون࣌', NULL, 450, 'local:warsh-text.json'),
  ('warsh-37-121', 'warsh', 37, 121, 'إِنَّا كَذَٰلِكَ نَجْزِے ࡴ۬لْمُحْسِنِينَ࣌', 'إنا كذلك نجزے ࡴلمحسنين࣌', NULL, 450, 'local:warsh-text.json'),
  ('warsh-37-122', 'warsh', 37, 122, 'إِنَّهُمَا مِنْ عِبَادِنَا ࡰ۬لْمُومِنِينَ࣌', 'إنهما من عبادنا ࡰلمومنين࣌', NULL, 450, 'local:warsh-text.json'),
  ('warsh-37-123', 'warsh', 37, 123, 'وَإِنَّ إِلْيَاسَ لَمِنَ ࡰ۬لْمُرْسَلِينَ', 'وإن إلياس لمن ࡰلمرسلين', NULL, 450, 'local:warsh-text.json'),
  ('warsh-37-124', 'warsh', 37, 124, 'إِذْ قَالَ لِقَوْمِهِۦٓ أَلَا تَتَّقُونَ', 'إذ قال لقومه ألا تتقون', NULL, 450, 'local:warsh-text.json'),
  ('warsh-37-125', 'warsh', 37, 125, 'أَتَدْعُونَ بَعْلاࣰ وَتَذَرُونَ أَحْسَنَ ࡰ۬لْخَٰلِقِينَ࣌', 'أتدعون بعلا وتذرون أحسن ࡰلخلقين࣌', NULL, 450, 'local:warsh-text.json'),
  ('warsh-37-126', 'warsh', 37, 126, 'ࡰ۬للَّهُ رَبُّكُمْ وَرَبُّ ءَابَآئِكُمُ ࡲ۬لَاوَّلِينَ࣌', 'ࡰلله ربكم ورب ءابائكم ࡲلاولين࣌', NULL, 450, 'local:warsh-text.json'),
  ('warsh-37-127', 'warsh', 37, 127, 'فَكَذَّبُوهُ فَإِنَّهُمْ لَمُحْضَرُونَ', 'فكذبوه فإنهم لمحضرون', NULL, 451, 'local:warsh-text.json'),
  ('warsh-37-128', 'warsh', 37, 128, 'إِلَّا عِبَادَ ࡰ۬للَّهِ ࡴ۬لْمُخْلَصِينَ࣌', 'إلا عباد ࡰلله ࡴلمخلصين࣌', NULL, 451, 'local:warsh-text.json'),
  ('warsh-37-129', 'warsh', 37, 129, 'وَتَرَكْنَا عَلَيْهِ فِے ࡴ۬لَاخِرِينَ࣌', 'وتركنا عليه فے ࡴلاخرين࣌', NULL, 451, 'local:warsh-text.json'),
  ('warsh-37-130', 'warsh', 37, 130, 'سَلَٰمٌ عَلَىٰٓ ءَالِ يَاسِينَ࣌', 'سلم على ءال ياسين࣌', NULL, 451, 'local:warsh-text.json'),
  ('warsh-37-131', 'warsh', 37, 131, 'إِنَّا كَذَٰلِكَ نَجْزِے ࡴ۬لْمُحْسِنِينَ࣌', 'إنا كذلك نجزے ࡴلمحسنين࣌', NULL, 451, 'local:warsh-text.json'),
  ('warsh-37-132', 'warsh', 37, 132, 'إِنَّهُۥ مِنْ عِبَادِنَا ࡰ۬لْمُومِنِينَ࣌', 'إنه من عبادنا ࡰلمومنين࣌', NULL, 451, 'local:warsh-text.json'),
  ('warsh-37-133', 'warsh', 37, 133, 'وَإِنَّ لُوطاࣰ لَّمِنَ ࡰ۬لْمُرْسَلِينَ', 'وإن لوطا لمن ࡰلمرسلين', NULL, 451, 'local:warsh-text.json'),
  ('warsh-37-134', 'warsh', 37, 134, 'إِذْ نَجَّيْنَٰهُ وَأَهْلَهُۥٓ أَجْمَعِينَ', 'إذ نجينه وأهله أجمعين', NULL, 451, 'local:warsh-text.json'),
  ('warsh-37-135', 'warsh', 37, 135, 'إِلَّا عَجُوزاࣰ فِے ࡴ۬لْغَٰبِرِينَ', 'إلا عجوزا فے ࡴلغبرين', NULL, 451, 'local:warsh-text.json'),
  ('warsh-37-136', 'warsh', 37, 136, 'ثُمَّ دَمَّرْنَا ࡰ۬لَاخَرِينَ࣌', 'ثم دمرنا ࡰلاخرين࣌', NULL, 451, 'local:warsh-text.json'),
  ('warsh-37-137', 'warsh', 37, 137, 'وَإِنَّكُمْ لَتَمُرُّونَ عَلَيْهِم مُّصْبِحِينَ', 'وإنكم لتمرون عليهم مصبحين', NULL, 451, 'local:warsh-text.json'),
  ('warsh-37-138', 'warsh', 37, 138, 'وَبِاليْلِ࣌ أَفَلَا تَعْقِلُونَ࣌', 'وباليل࣌ أفلا تعقلون࣌', NULL, 451, 'local:warsh-text.json'),
  ('warsh-37-139', 'warsh', 37, 139, 'وَإِنَّ يُونُسَ لَمِنَ ࡰ۬لْمُرْسَلِينَ', 'وإن يونس لمن ࡰلمرسلين', NULL, 451, 'local:warsh-text.json'),
  ('warsh-37-140', 'warsh', 37, 140, 'إِذَ ࡰبَقَ إِلَى ࡰ۬لْفُلْكِ ࡴ۬لْمَشْحُونِ', 'إذ ࡰبق إلى ࡰلفلك ࡴلمشحون', NULL, 451, 'local:warsh-text.json'),
  ('warsh-37-141', 'warsh', 37, 141, 'فَسَاهَمَ فَكَانَ مِنَ ࡰ۬لْمُدْحَضِينَ', 'فساهم فكان من ࡰلمدحضين', NULL, 451, 'local:warsh-text.json'),
  ('warsh-37-142', 'warsh', 37, 142, 'فَالْتَقَمَهُ ࡲ۬لْحُوتُ وَهُوَ مُلِيمࣱ࣌', 'فالتقمه ࡲلحوت وهو مليم࣌', NULL, 451, 'local:warsh-text.json'),
  ('warsh-37-143', 'warsh', 37, 143, 'فَلَوْلَآ أَنَّهُۥ كَانَ مِنَ ࡰ۬لْمُسَبِّحِينَ', 'فلولا أنه كان من ࡰلمسبحين', NULL, 451, 'local:warsh-text.json'),
  ('warsh-37-144', 'warsh', 37, 144, 'لَلَبِثَ فِے بَطْنِهِۦٓ إِلَىٰ يَوْمِ يُبْعَثُونَ࣌', 'للبث فے بطنه إلى يوم يبعثون࣌', NULL, 451, 'local:warsh-text.json'),
  ('warsh-37-145', 'warsh', 37, 145, '۞ فَنَبَذْنَٰهُ بِالْعَرَآءِ وَهُوَ سَقِيمࣱ࣌', 'فنبذنه بالعراء وهو سقيم࣌', NULL, 451, 'local:warsh-text.json'),
  ('warsh-37-146', 'warsh', 37, 146, 'وَأَنۢبَتْنَا عَلَيْهِ شَجَرَةࣰ مِّنْ يَّقْطِينࣲ࣌', 'وأنبتنا عليه شجرة من يقطين࣌', NULL, 451, 'local:warsh-text.json'),
  ('warsh-37-147', 'warsh', 37, 147, 'وَأَرْسَلْنَٰهُ إِلَىٰ مِاْئَةِ أَلْفٍ ࡰوْ يَزِيدُونَ࣌', 'وأرسلنه إلى مائة ألف ࡰو يزيدون࣌', NULL, 451, 'local:warsh-text.json'),
  ('warsh-37-148', 'warsh', 37, 148, 'فَـَٔامَنُواْ فَمَتَّعْنَٰهُمُۥٓ إِلَىٰ حِينࣲ࣌', 'فامنوا فمتعنهم إلى حين࣌', NULL, 451, 'local:warsh-text.json'),
  ('warsh-37-149', 'warsh', 37, 149, 'فَاسْتَفْتِهِمُۥٓ أَلِرَبِّكَ ࡰ۬لْبَنَاتُ وَلَهُمُ ࡲ۬لْبَنُونَ࣌', 'فاستفتهم ألربك ࡰلبنات ولهم ࡲلبنون࣌', NULL, 451, 'local:warsh-text.json'),
  ('warsh-37-150', 'warsh', 37, 150, 'أَمْ خَلَقْنَا ࡰ۬لْمَلَٰٓئِكَةَ إِنَٰثاࣰ وَهُمْ شَٰهِدُونَ࣌', 'أم خلقنا ࡰلملئكة إنثا وهم شهدون࣌', NULL, 451, 'local:warsh-text.json'),
  ('warsh-37-151', 'warsh', 37, 151, 'أَلَآ إِنَّهُم مِّنِ ࡴفْكِهِمْ لَيَقُولُونَ', 'ألا إنهم من ࡴفكهم ليقولون', NULL, 451, 'local:warsh-text.json'),
  ('warsh-37-152', 'warsh', 37, 152, 'وَلَدَ ࡰ۬للَّهُ وَإِنَّهُمْ لَكَٰذِبُونَ࣌', 'ولد ࡰلله وإنهم لكذبون࣌', NULL, 451, 'local:warsh-text.json'),
  ('warsh-37-153', 'warsh', 37, 153, 'أَصْطَفَى ࡰ۬لْبَنَاتِ عَلَى ࡰ۬لْبَنِينَ࣌', 'أصطفى ࡰلبنات على ࡰلبنين࣌', NULL, 451, 'local:warsh-text.json'),
  ('warsh-37-154', 'warsh', 37, 154, 'مَا لَكُمْ࣌ كَيْفَ تَحْكُمُونَ࣌', 'ما لكم࣌ كيف تحكمون࣌', NULL, 452, 'local:warsh-text.json'),
  ('warsh-37-155', 'warsh', 37, 155, 'أَفَلَا تَذَّكَّرُونَ࣌', 'أفلا تذكرون࣌', NULL, 452, 'local:warsh-text.json'),
  ('warsh-37-156', 'warsh', 37, 156, 'أَمْ لَكُمْ سُلْطَٰنࣱ مُّبِينࣱ', 'أم لكم سلطن مبين', NULL, 452, 'local:warsh-text.json'),
  ('warsh-37-157', 'warsh', 37, 157, 'فَاتُواْ بِكِتَٰبِكُمُۥٓ إِن كُنتُمْ صَٰدِقِينَ࣌', 'فاتوا بكتبكم إن كنتم صدقين࣌', NULL, 452, 'local:warsh-text.json'),
  ('warsh-37-158', 'warsh', 37, 158, 'وَجَعَلُواْ بَيْنَهُۥ وَبَيْنَ ࡰ۬لْجِنَّةِ نَسَباࣰ࣌ وَلَقَدْ عَلِمَتِ ࡴ۬لْجِنَّةُ إِنَّهُمْ لَمُحْضَرُونَ࣌', 'وجعلوا بينه وبين ࡰلجنة نسبا࣌ ولقد علمت ࡴلجنة إنهم لمحضرون࣌', NULL, 452, 'local:warsh-text.json'),
  ('warsh-37-159', 'warsh', 37, 159, 'سُبْحَٰنَ ࡰ۬للَّهِ عَمَّا يَصِفُونَ࣌', 'سبحن ࡰلله عما يصفون࣌', NULL, 452, 'local:warsh-text.json'),
  ('warsh-37-160', 'warsh', 37, 160, 'إِلَّا عِبَادَ ࡰ۬للَّهِ ࡴ۬لْمُخْلَصِينَ࣌', 'إلا عباد ࡰلله ࡴلمخلصين࣌', NULL, 452, 'local:warsh-text.json'),
  ('warsh-37-161', 'warsh', 37, 161, 'فَإِنَّكُمْ وَمَا تَعْبُدُونَ', 'فإنكم وما تعبدون', NULL, 452, 'local:warsh-text.json'),
  ('warsh-37-162', 'warsh', 37, 162, 'مَآ أَنتُمْ عَلَيْهِ بِفَٰتِنِينَ', 'ما أنتم عليه بفتنين', NULL, 452, 'local:warsh-text.json'),
  ('warsh-37-163', 'warsh', 37, 163, 'إِلَّا مَنْ هُوَ صَالِ ࡴ۬لْجَحِيمِ࣌', 'إلا من هو صال ࡴلجحيم࣌', NULL, 452, 'local:warsh-text.json'),
  ('warsh-37-164', 'warsh', 37, 164, 'وَمَا مِنَّآ إِلَّا لَهُۥ مَقَامࣱ مَّعْلُومࣱ࣌', 'وما منا إلا له مقام معلوم࣌', NULL, 452, 'local:warsh-text.json'),
  ('warsh-37-165', 'warsh', 37, 165, 'وَإِنَّا لَنَحْنُ ࡲ۬لصَّآفُّونَ', 'وإنا لنحن ࡲلصافون', NULL, 452, 'local:warsh-text.json'),
  ('warsh-37-166', 'warsh', 37, 166, 'وَإِنَّا لَنَحْنُ ࡲ۬لْمُسَبِّحُونَ࣌', 'وإنا لنحن ࡲلمسبحون࣌', NULL, 452, 'local:warsh-text.json'),
  ('warsh-37-167', 'warsh', 37, 167, 'وَإِن كَانُواْ لَيَقُولُونَ', 'وإن كانوا ليقولون', NULL, 452, 'local:warsh-text.json'),
  ('warsh-37-168', 'warsh', 37, 168, 'لَوَ ࡰنَّ عِندَنَا ذِكْراࣰ مِّنَ ࡰ۬لَاوَّلِينَ', 'لو ࡰن عندنا ذكرا من ࡰلاولين', NULL, 452, 'local:warsh-text.json'),
  ('warsh-37-169', 'warsh', 37, 169, 'لَكُنَّا عِبَادَ ࡰ۬للَّهِ ࡴ۬لْمُخْلَصِينَ࣌', 'لكنا عباد ࡰلله ࡴلمخلصين࣌', NULL, 452, 'local:warsh-text.json'),
  ('warsh-37-170', 'warsh', 37, 170, 'فَكَفَرُواْ بِهِۦ࣌ فَسَوْفَ يَعْلَمُونَ࣌', 'فكفروا به࣌ فسوف يعلمون࣌', NULL, 452, 'local:warsh-text.json'),
  ('warsh-37-171', 'warsh', 37, 171, 'وَلَقَدْ سَبَقَتْ كَلِمَتُنَا لِعِبَادِنَا ࡰ۬لْمُرْسَلِينَ', 'ولقد سبقت كلمتنا لعبادنا ࡰلمرسلين', NULL, 452, 'local:warsh-text.json'),
  ('warsh-37-172', 'warsh', 37, 172, 'إِنَّهُمْ لَهُمُ ࡲ۬لْمَنصُورُونَ', 'إنهم لهم ࡲلمنصورون', NULL, 452, 'local:warsh-text.json'),
  ('warsh-37-173', 'warsh', 37, 173, 'وَإِنَّ جُندَنَا لَهُمُ ࡲ۬لْغَٰلِبُونَ࣌', 'وإن جندنا لهم ࡲلغلبون࣌', NULL, 452, 'local:warsh-text.json'),
  ('warsh-37-174', 'warsh', 37, 174, 'فَتَوَلَّ عَنْهُمْ حَتَّىٰ حِينࣲ࣌', 'فتول عنهم حتى حين࣌', NULL, 452, 'local:warsh-text.json'),
  ('warsh-37-175', 'warsh', 37, 175, 'وَأَبْصِرْهُمْ فَسَوْفَ يُبْصِرُونَ࣌', 'وأبصرهم فسوف يبصرون࣌', NULL, 452, 'local:warsh-text.json'),
  ('warsh-37-176', 'warsh', 37, 176, 'أَفَبِعَذَابِنَا يَسْتَعْجِلُونَ࣌', 'أفبعذابنا يستعجلون࣌', NULL, 452, 'local:warsh-text.json'),
  ('warsh-37-177', 'warsh', 37, 177, 'فَإِذَا نَزَلَ بِسَاحَتِهِمْ فَسَآءَ صَبَاحُ ࡲ۬لْمُنذَرِينَ࣌', 'فإذا نزل بساحتهم فساء صباح ࡲلمنذرين࣌', NULL, 452, 'local:warsh-text.json'),
  ('warsh-37-178', 'warsh', 37, 178, 'وَتَوَلَّ عَنْهُمْ حَتَّىٰ حِينࣲ࣌', 'وتول عنهم حتى حين࣌', NULL, 452, 'local:warsh-text.json'),
  ('warsh-37-179', 'warsh', 37, 179, 'وَأَبْصِرْ فَسَوْفَ يُبْصِرُونَ࣌', 'وأبصر فسوف يبصرون࣌', NULL, 452, 'local:warsh-text.json'),
  ('warsh-37-180', 'warsh', 37, 180, 'سُبْحَٰنَ رَبِّكَ رَبِّ ࡴ۬لْعِزَّةِ عَمَّا يَصِفُونَ࣌', 'سبحن ربك رب ࡴلعزة عما يصفون࣌', NULL, 452, 'local:warsh-text.json'),
  ('warsh-37-181', 'warsh', 37, 181, 'وَسَلَٰمٌ عَلَى ࡰ۬لْمُرْسَلِينَ࣌', 'وسلم على ࡰلمرسلين࣌', NULL, 452, 'local:warsh-text.json'),
  ('warsh-37-182', 'warsh', 37, 182, 'وَالْحَمْدُ لِلهِ رَبِّ ࡴ۬لْعَٰلَمِينَ࣌', 'والحمد لله رب ࡴلعلمين࣌', NULL, 452, 'local:warsh-text.json'),
  ('warsh-38-1', 'warsh', 38, 1, 'صَٓ࣌ وَالْقُرْءَانِ ذِے ࡴ۬لذِّكْرِ࣌ بَلِ ࡴ۬لذِينَ كَفَرُواْ فِے عِزَّةࣲ وَشِقَاقࣲ࣌', 'ص࣌ والقرءان ذے ࡴلذكر࣌ بل ࡴلذين كفروا فے عزة وشقاق࣌', NULL, 453, 'local:warsh-text.json'),
  ('warsh-38-2', 'warsh', 38, 2, 'كَمَ ࡰهْلَكْنَا مِن قَبْلِهِم مِّن قَرْنࣲ فَنَادَواْ وَّلَاتَ حِينَ مَنَاصࣲ࣌', 'كم ࡰهلكنا من قبلهم من قرن فنادوا ولات حين مناص࣌', NULL, 453, 'local:warsh-text.json'),
  ('warsh-38-3', 'warsh', 38, 3, 'وَعَجِبُوٓاْ أَن جَآءَهُم مُّنذِرࣱ مِّنْهُمْ࣌ وَقَالَ ࡰ۬لْكَٰفِرُونَ هَٰذَا سَٰحِرࣱ كَذَّابٌ', 'وعجبوا أن جاءهم منذر منهم࣌ وقال ࡰلكفرون هذا سحر كذاب', NULL, 453, 'local:warsh-text.json'),
  ('warsh-38-4', 'warsh', 38, 4, 'ࡰجَعَلَ ࡰ۬لَالِهَةَ إِلَٰهاࣰ وَٰحِداً ࡴنَّ هَٰذَا لَشَےْءٌ عُجَابࣱ࣌', 'ࡰجعل ࡰلالهة إلها وحدا ࡴن هذا لشےء عجاب࣌', NULL, 453, 'local:warsh-text.json'),
  ('warsh-38-5', 'warsh', 38, 5, 'وَانطَلَقَ ࡰ۬لْمَلَأُ مِنْهُمُۥٓ أَنِ ࡴٜمْشُواْ وَاصْبِرُواْ عَلَىٰٓ ءَالِهَتِكُمُۥٓ إِنَّ هَٰذَا لَشَےْءࣱ يُرَادُ', 'وانطلق ࡰلملأ منهم أن ࡴمشوا واصبروا على ءالهتكم إن هذا لشےء يراد', NULL, 453, 'local:warsh-text.json'),
  ('warsh-38-6', 'warsh', 38, 6, 'مَا سَمِعْنَا بِهَٰذَا فِے ࡴ۬لْمِلَّةِ ࡴ۬لَاخِرَةِ إِنْ هَٰذَآ إِلَّا ࡰٜخْتِلَٰقٌ', 'ما سمعنا بهذا فے ࡴلملة ࡴلاخرة إن هذا إلا ࡰختلق', NULL, 453, 'local:warsh-text.json'),
  ('warsh-38-7', 'warsh', 38, 7, 'ࡰࢇنزِلَ عَلَيْهِ ࡴ۬لذِّكْرُ مِنۢ بَيْنِنَا࣌ بَلْ هُمْ فِے شَكࣲّ مِّن ذِكْرِے بَل لَّمَّا يَذُوقُواْ عَذَابِ࣌', 'ࡰࢇنزل عليه ࡴلذكر من بيننا࣌ بل هم فے شك من ذكرے بل لما يذوقوا عذاب࣌', NULL, 453, 'local:warsh-text.json'),
  ('warsh-38-8', 'warsh', 38, 8, 'أَمْ عِندَهُمْ خَزَآئِنُ رَحْمَةِ رَبِّكَ ࡰ۬لْعَزِيزِ ࡴ۬لْوَهَّابِ࣌', 'أم عندهم خزائن رحمة ربك ࡰلعزيز ࡴلوهاب࣌', NULL, 453, 'local:warsh-text.json'),
  ('warsh-38-9', 'warsh', 38, 9, 'أَمْ لَهُم مُّلْكُ ࡲ۬لسَّمَٰوَٰتِ وَالَارْضِ وَمَا بَيْنَهُمَا࣌ فَلْيَرْتَقُواْ فِے ࡴ۬لَاسْبَٰبِ࣌', 'أم لهم ملك ࡲلسموت والارض وما بينهما࣌ فليرتقوا فے ࡴلاسبب࣌', NULL, 453, 'local:warsh-text.json'),
  ('warsh-38-10', 'warsh', 38, 10, 'جُندࣱ مَّا هُنَالِكَ مَهْزُومࣱ مِّنَ ࡰ۬لَاحْزَابِ࣌', 'جند ما هنالك مهزوم من ࡰلاحزاب࣌', NULL, 453, 'local:warsh-text.json'),
  ('warsh-38-11', 'warsh', 38, 11, 'كَذَّبَتْ قَبْلَهُمْ قَوْمُ نُوحࣲ وَعَادࣱ وَفِرْعَوْنُ ذُو ࡲ۬لَاوْتَادِ', 'كذبت قبلهم قوم نوح وعاد وفرعون ذو ࡲلاوتاد', NULL, 453, 'local:warsh-text.json'),
  ('warsh-38-12', 'warsh', 38, 12, 'وَثَمُودُ وَقَوْمُ لُوطࣲ وَأَصْحَٰبُ لَيْكَةَ࣌ أُوْلَٰٓئِكَ ࡰ۬لَاحْزَابُ࣌', 'وثمود وقوم لوط وأصحب ليكة࣌ أولئك ࡰلاحزاب࣌', NULL, 453, 'local:warsh-text.json'),
  ('warsh-38-13', 'warsh', 38, 13, 'إِن كُلٌّ ࡴلَّا كَذَّبَ ࡰ۬لرُّسُلَ فَحَقَّ عِقَابِ࣌', 'إن كل ࡴلا كذب ࡰلرسل فحق عقاب࣌', NULL, 453, 'local:warsh-text.json'),
  ('warsh-38-14', 'warsh', 38, 14, 'وَمَا يَنظُرُ هَٰٓؤُلَآءِ الَّا صَيْحَةࣰ وَٰحِدَةࣰ مَّا لَهَا مِن فَوَاقࣲ࣌', 'وما ينظر هؤلاء الا صيحة وحدة ما لها من فواق࣌', NULL, 453, 'local:warsh-text.json'),
  ('warsh-38-15', 'warsh', 38, 15, 'وَقَالُواْ رَبَّنَا عَجِّل لَّنَا قِطَّنَا قَبْلَ يَوْمِ ࡴ۬لْحِسَابِ࣌', 'وقالوا ربنا عجل لنا قطنا قبل يوم ࡴلحساب࣌', NULL, 453, 'local:warsh-text.json'),
  ('warsh-38-16', 'warsh', 38, 16, 'ࡴٜصْبِرْ عَلَىٰ مَا يَقُولُونَ࣌ وَاذْكُرْ عَبْدَنَا دَاوُۥدَ ذَا ࡰ۬لَايْدِ࣌ إِنَّهُۥٓ أَوَّابٌ࣌', 'ࡴصبر على ما يقولون࣌ واذكر عبدنا داود ذا ࡰلايد࣌ إنه أواب࣌', NULL, 454, 'local:warsh-text.json'),
  ('warsh-38-17', 'warsh', 38, 17, 'ࡴنَّا سَخَّرْنَا ࡰ۬لْجِبَالَ مَعَهُۥ يُسَبِّحْنَ بِالْعَشِيِّ وَالِاشْرَاقِ', 'ࡴنا سخرنا ࡰلجبال معه يسبحن بالعشي والاشراق', NULL, 454, 'local:warsh-text.json'),
  ('warsh-38-18', 'warsh', 38, 18, 'وَالطَّيْرَ مَحْشُورَةࣰ࣌ كُلࣱّ لَّهُۥٓ أَوَّابࣱ࣌', 'والطير محشورة࣌ كل له أواب࣌', NULL, 454, 'local:warsh-text.json'),
  ('warsh-38-19', 'warsh', 38, 19, 'وَشَدَدْنَا مُلْكَهُۥ وَءَاتَيْنَٰهُ ࡲ۬لْحِكْمَةَ وَفَصْلَ ࡰ۬لْخِطَابِ࣌', 'وشددنا ملكه وءاتينه ࡲلحكمة وفصل ࡰلخطاب࣌', NULL, 454, 'local:warsh-text.json'),
  ('warsh-38-20', 'warsh', 38, 20, '۞ وَهَلَ ࡰتٜيٰكَ نَبَؤُاْ ࡲ۬لْخَصْمِ إِذْ تَسَوَّرُواْ ࡲ۬لْمِحْرَابَ', 'وهل ࡰتيك نبؤا ࡲلخصم إذ تسوروا ࡲلمحراب', NULL, 454, 'local:warsh-text.json'),
  ('warsh-38-21', 'warsh', 38, 21, 'إِذْ دَخَلُواْ عَلَىٰ دَاوُۥدَ فَفَزِعَ مِنْهُمْ قَالُواْ لَا تَخَفْ࣌ خَصْمَٰنِ بَغٜىٰ بَعْضُنَا عَلَىٰ بَعْضࣲ فَاحْكُم بَيْنَنَا بِالْحَقِّ وَلَا تُشْطِطْ࣌ وَاهْدِنَآ إِلَىٰ سَوَآءِ ࡴ۬لصِّرَٰطِ࣌', 'إذ دخلوا على داود ففزع منهم قالوا لا تخف࣌ خصمن بغى بعضنا على بعض فاحكم بيننا بالحق ولا تشطط࣌ واهدنا إلى سواء ࡴلصرط࣌', NULL, 454, 'local:warsh-text.json'),
  ('warsh-38-22', 'warsh', 38, 22, 'إِنَّ هَٰذَآ أَخِے لَهُۥ تِسْعࣱ وَتِسْعُونَ نَعْجَةࣰ وَلِے نَعْجَةࣱ وَٰحِدَةࣱ فَقَالَ أَكْفِلْنِيهَا وَعَزَّنِے فِے ࡴ۬لْخِطَابِ࣌', 'إن هذا أخے له تسع وتسعون نعجة ولے نعجة وحدة فقال أكفلنيها وعزنے فے ࡴلخطاب࣌', NULL, 454, 'local:warsh-text.json'),
  ('warsh-38-23', 'warsh', 38, 23, 'قَالَ لَقَد ظَّلَمَكَ بِسُؤَالِ نَعْجَتِكَ إِلَىٰ نِعَاجِهِۦ࣌ وَإِنَّ كَثِيراࣰ مِّنَ ࡰ۬لْخُلَطَآءِ لَيَبْغِے بَعْضُهُمْ عَلَىٰ بَعْضٍ ࡴلَّا ࡰ۬لذِينَ ءَامَنُواْ وَعَمِلُواْ ࡲ۬لصَّٰلِحَٰتِ࣌ وَقَلِيلࣱ مَّا هُمْ࣌ وَظَنَّ دَاوُۥدُ أَنَّمَا فَتَنَّٰهُ فَاسْتَغْفَرَ رَبَّهُۥ وَخَرَّ رَاكِعاࣰ وَأَنَابَ࣌۩', 'قال لقد ظلمك بسؤال نعجتك إلى نعاجه࣌ وإن كثيرا من ࡰلخلطاء ليبغے بعضهم على بعض ࡴلا ࡰلذين ءامنوا وعملوا ࡲلصلحت࣌ وقليل ما هم࣌ وظن داود أنما فتنه فاستغفر ربه وخر راكعا وأناب࣌', NULL, 454, 'local:warsh-text.json'),
  ('warsh-38-24', 'warsh', 38, 24, 'فَغَفَرْنَا لَهُۥ ذَٰلِكَ࣌ وَإِنَّ لَهُۥ عِندَنَا لَزُلْفٜىٰ وَحُسْنَ مَـَٔابࣲ࣌', 'فغفرنا له ذلك࣌ وإن له عندنا لزلفى وحسن ماب࣌', NULL, 454, 'local:warsh-text.json'),
  ('warsh-38-25', 'warsh', 38, 25, 'يَٰدَاوُۥدُ إِنَّا جَعَلْنَٰكَ خَلِيفَةࣰ فِے ࡴ۬لَارْضِ فَاحْكُم بَيْنَ ࡰ۬لنَّاسِ بِالْحَقِّ وَلَا تَتَّبِعِ ࡴ۬لْهَوٜىٰ فَيُضِلَّكَ عَن سَبِيلِ ࡴ۬للَّهِ࣌ إِنَّ ࡰ۬لذِينَ يَضِلُّونَ عَن سَبِيلِ ࡴ۬للَّهِ لَهُمْ عَذَابࣱ شَدِيدُۢ بِمَا نَسُواْ يَوْمَ ࡰ۬لْحِسَابِ࣌', 'يداود إنا جعلنك خليفة فے ࡴلارض فاحكم بين ࡰلناس بالحق ولا تتبع ࡴلهوى فيضلك عن سبيل ࡴلله࣌ إن ࡰلذين يضلون عن سبيل ࡴلله لهم عذاب شديد بما نسوا يوم ࡰلحساب࣌', NULL, 454, 'local:warsh-text.json'),
  ('warsh-38-26', 'warsh', 38, 26, 'وَمَا خَلَقْنَا ࡰ۬لسَّمَآءَ وَالَارْضَ وَمَا بَيْنَهُمَا بَٰطِلاࣰ࣌ ذَٰلِكَ ظَنُّ ࡲ۬لذِينَ كَفَرُواْ࣌ فَوَيْلࣱ لِّلذِينَ كَفَرُواْ مِنَ ࡰ۬لنّٜارِ࣌', 'وما خلقنا ࡰلسماء والارض وما بينهما بطلا࣌ ذلك ظن ࡲلذين كفروا࣌ فويل للذين كفروا من ࡰلنار࣌', NULL, 455, 'local:warsh-text.json'),
  ('warsh-38-27', 'warsh', 38, 27, 'أَمْ نَجْعَلُ ࡲ۬لذِينَ ءَامَنُواْ وَعَمِلُواْ ࡲ۬لصَّٰلِحَٰتِ كَالْمُفْسِدِينَ فِے ࡴ۬لَارْضِ࣌ أَمْ نَجْعَلُ ࡲ۬لْمُتَّقِينَ كَالْفُجّٜارِ࣌', 'أم نجعل ࡲلذين ءامنوا وعملوا ࡲلصلحت كالمفسدين فے ࡴلارض࣌ أم نجعل ࡲلمتقين كالفجار࣌', NULL, 455, 'local:warsh-text.json'),
  ('warsh-38-28', 'warsh', 38, 28, 'كِتَٰبٌ ࡰنزَلْنَٰهُ إِلَيْكَ مُبَٰرَكࣱ لِّيَدَّبَّرُوٓاْ ءَايَٰتِهِۦ وَلِيَتَذَكَّرَ أُوْلُواْ ࡲ۬لَالْبَٰبِ࣌', 'كتب ࡰنزلنه إليك مبرك ليدبروا ءايته وليتذكر أولوا ࡲلالبب࣌', NULL, 455, 'local:warsh-text.json'),
  ('warsh-38-29', 'warsh', 38, 29, 'وَوَهَبْنَا لِدَاوُۥدَ سُلَيْمَٰنَ࣌ نِعْمَ ࡰ۬لْعَبْدُ࣌ إِنَّهُۥٓ أَوَّابٌ࣌', 'ووهبنا لداود سليمن࣌ نعم ࡰلعبد࣌ إنه أواب࣌', NULL, 455, 'local:warsh-text.json'),
  ('warsh-38-30', 'warsh', 38, 30, '۞ ࡴذْ عُرِضَ عَلَيْهِ بِالْعَشِيِّ ࡴ۬لصَّٰفِنَٰتُ ࡲ۬لْجِيَادُ', 'ࡴذ عرض عليه بالعشي ࡴلصفنت ࡲلجياد', NULL, 455, 'local:warsh-text.json'),
  ('warsh-38-31', 'warsh', 38, 31, 'فَقَالَ إِنِّيَ أَحْبَبْتُ حُبَّ ࡰ۬لْخَيْرِ عَن ذِكْرِ رَبِّے حَتَّىٰ تَوَارَتْ بِالْحِجَابِ࣌', 'فقال إني أحببت حب ࡰلخير عن ذكر ربے حتى توارت بالحجاب࣌', NULL, 455, 'local:warsh-text.json'),
  ('warsh-38-32', 'warsh', 38, 32, 'رُدُّوهَا عَلَيَّ فَطَفِقَ مَسْحاَۢ بِالسُّوقِ وَالَاعْنَاقِ࣌', 'ردوها علي فطفق مسحا بالسوق والاعناق࣌', NULL, 455, 'local:warsh-text.json'),
  ('warsh-38-33', 'warsh', 38, 33, 'وَلَقَدْ فَتَنَّا سُلَيْمَٰنَ وَأَلْقَيْنَا عَلَىٰ كُرْسِيِّهِۦ جَسَداࣰ ثُمَّ أَنَابَ࣌', 'ولقد فتنا سليمن وألقينا على كرسيه جسدا ثم أناب࣌', NULL, 455, 'local:warsh-text.json'),
  ('warsh-38-34', 'warsh', 38, 34, 'قَالَ رَبِّ ࡴٜغْفِرْ لِے وَهَبْ لِے مُلْكاࣰ لَّا يَنۢبَغِے لِأَحَدࣲ مِّنۢ بَعْدِيَ࣌ إِنَّكَ أَنتَ ࡰ۬لْوَهَّابُ࣌', 'قال رب ࡴغفر لے وهب لے ملكا لا ينبغے لأحد من بعدي࣌ إنك أنت ࡰلوهاب࣌', NULL, 455, 'local:warsh-text.json'),
  ('warsh-38-35', 'warsh', 38, 35, 'فَسَخَّرْنَا لَهُ ࡲ۬لرِّيحَ تَجْرِے بِأَمْرِهِۦ رُخَآءً حَيْثُ أَصَابَ', 'فسخرنا له ࡲلريح تجرے بأمره رخاء حيث أصاب', NULL, 455, 'local:warsh-text.json'),
  ('warsh-38-36', 'warsh', 38, 36, 'وَالشَّيَٰطِينَ كُلَّ بَنَّآءࣲ وَغَوَّاصࣲ', 'والشيطين كل بناء وغواص', NULL, 455, 'local:warsh-text.json')
insert into public.ayahs (id, riwayah, surah_number, ayah_number, text, simple_text, juz, page, source) values
  ('warsh-38-37', 'warsh', 38, 37, 'وَءَاخَرِينَ مُقَرَّنِينَ فِے ࡴ۬لَاصْفَادِ࣌', 'وءاخرين مقرنين فے ࡴلاصفاد࣌', NULL, 455, 'local:warsh-text.json'),
  ('warsh-38-38', 'warsh', 38, 38, 'هَٰذَا عَطَآؤُنَا فَامْنُنَ ࡰوَ ࡰمْسِكْ بِغَيْرِ حِسَابࣲ࣌', 'هذا عطاؤنا فامنن ࡰو ࡰمسك بغير حساب࣌', NULL, 455, 'local:warsh-text.json'),
  ('warsh-38-39', 'warsh', 38, 39, 'وَإِنَّ لَهُۥ عِندَنَا لَزُلْفٜىٰ وَحُسْنَ مَـَٔابࣲ࣌', 'وإن له عندنا لزلفى وحسن ماب࣌', NULL, 455, 'local:warsh-text.json'),
  ('warsh-38-40', 'warsh', 38, 40, 'وَاذْكُرْ عَبْدَنَآ أَيُّوبَ إِذْ نَادٜىٰ رَبَّهُۥٓ أَنِّے مَسَّنِيَ ࡰ۬لشَّيْطَٰنُ بِنُصْبࣲ وَعَذَابٍ࣌', 'واذكر عبدنا أيوب إذ نادى ربه أنے مسني ࡰلشيطن بنصب وعذاب࣌', NULL, 455, 'local:warsh-text.json'),
  ('warsh-38-41', 'warsh', 38, 41, 'ࡲ࢈رْكُضْ بِرِجْلِكَ࣌ هَٰذَا مُغْتَسَلُۢ بَارِدࣱ وَشَرَابࣱ࣌', 'ࡲ࢈ركض برجلك࣌ هذا مغتسل بارد وشراب࣌', NULL, 455, 'local:warsh-text.json'),
  ('warsh-38-42', 'warsh', 38, 42, 'وَوَهَبْنَا لَهُۥٓ أَهْلَهُۥ وَمِثْلَهُم مَّعَهُمْ رَحْمَةࣰ مِّنَّا وَذِكْرٜىٰ لِأُوْلِے ࡴ۬لَالْبَٰبِ࣌', 'ووهبنا له أهله ومثلهم معهم رحمة منا وذكرى لأولے ࡴلالبب࣌', NULL, 456, 'local:warsh-text.json'),
  ('warsh-38-43', 'warsh', 38, 43, 'وَخُذْ بِيَدِكَ ضِغْثاࣰ فَاضْرِب بِّهِۦ وَلَا تَحْنَثِ࣌ ࡴنَّا وَجَدْنَٰهُ صَابِراࣰ࣌ نِّعْمَ ࡰ۬لْعَبْدُ࣌ إِنَّهُۥٓ أَوَّابࣱ࣌', 'وخذ بيدك ضغثا فاضرب به ولا تحنث࣌ ࡴنا وجدنه صابرا࣌ نعم ࡰلعبد࣌ إنه أواب࣌', NULL, 456, 'local:warsh-text.json'),
  ('warsh-38-44', 'warsh', 38, 44, 'وَاذْكُرْ عِبَٰدَنَآ إِبْرَٰهِيمَ وَإِسْحَٰقَ وَيَعْقُوبَ أُوْلِے ࡴ۬لَايْدِے وَالَابْصٜـٰرِ࣌', 'واذكر عبدنا إبرهيم وإسحق ويعقوب أولے ࡴلايدے والابصر࣌', NULL, 456, 'local:warsh-text.json'),
  ('warsh-38-45', 'warsh', 38, 45, 'إِنَّآ أَخْلَصْنَٰهُم بِخَالِصَةِ ذِكْرَى ࡰ۬لدّٜارِ࣌', 'إنا أخلصنهم بخالصة ذكرى ࡰلدار࣌', NULL, 456, 'local:warsh-text.json'),
  ('warsh-38-46', 'warsh', 38, 46, 'وَإِنَّهُمْ عِندَنَا لَمِنَ ࡰ۬لْمُصْطَفَيْنَ ࡰ۬لَاخْيٜارِ࣌', 'وإنهم عندنا لمن ࡰلمصطفين ࡰلاخيار࣌', NULL, 456, 'local:warsh-text.json'),
  ('warsh-38-47', 'warsh', 38, 47, 'وَاذْكُرِ ࡴسْمَٰعِيلَ وَالْيَسَعَ وَذَا ࡰ۬لْكِفْلِ࣌ وَكُلࣱّ مِّنَ ࡰ۬لَاخْيٜارِ࣌', 'واذكر ࡴسمعيل واليسع وذا ࡰلكفل࣌ وكل من ࡰلاخيار࣌', NULL, 456, 'local:warsh-text.json'),
  ('warsh-38-48', 'warsh', 38, 48, 'هَٰذَا ذِكْرࣱ࣌ وَإِنَّ لِلْمُتَّقِينَ لَحُسْنَ مَـَٔابࣲ', 'هذا ذكر࣌ وإن للمتقين لحسن ماب', NULL, 456, 'local:warsh-text.json'),
  ('warsh-38-49', 'warsh', 38, 49, 'جَنَّٰتِ عَدْنࣲ مُّفَتَّحَةࣰ لَّهُمُ ࡲ۬لَابْوَٰبُ', 'جنت عدن مفتحة لهم ࡲلابوب', NULL, 456, 'local:warsh-text.json'),
  ('warsh-38-50', 'warsh', 38, 50, 'مُتَّكِـِٕينَ فِيهَا يَدْعُونَ فِيهَا بِفَٰكِهَةࣲ كَثِيرَةࣲ وَشَرَابࣲ࣌', 'متكين فيها يدعون فيها بفكهة كثيرة وشراب࣌', NULL, 456, 'local:warsh-text.json'),
  ('warsh-38-51', 'warsh', 38, 51, '۞ وَعِندَهُمْ قَٰصِرَٰتُ ࡲ۬لطَّرْفِ أَتْرَابٌ࣌', 'وعندهم قصرت ࡲلطرف أتراب࣌', NULL, 456, 'local:warsh-text.json'),
  ('warsh-38-52', 'warsh', 38, 52, 'هَٰذَا مَا تُوعَدُونَ لِيَوْمِ ࡴ۬لْحِسَابِ࣌', 'هذا ما توعدون ليوم ࡴلحساب࣌', NULL, 456, 'local:warsh-text.json'),
  ('warsh-38-53', 'warsh', 38, 53, 'إِنَّ هَٰذَا لَرِزْقُنَا مَا لَهُۥ مِن نَّفَادٍ࣌', 'إن هذا لرزقنا ما له من نفاد࣌', NULL, 456, 'local:warsh-text.json'),
  ('warsh-38-54', 'warsh', 38, 54, 'هَٰذَا وَإِنَّ لِلطَّٰغِينَ لَشَرَّ مَـَٔابࣲ', 'هذا وإن للطغين لشر ماب', NULL, 456, 'local:warsh-text.json'),
  ('warsh-38-55', 'warsh', 38, 55, 'جَهَنَّمَ يَصْلَوْنَهَا࣌ فَبِيسَ ࡰ۬لْمِهَادُ࣌', 'جهنم يصلونها࣌ فبيس ࡰلمهاد࣌', NULL, 456, 'local:warsh-text.json'),
  ('warsh-38-56', 'warsh', 38, 56, 'هَٰذَا فَلْيَذُوقُوهُ حَمِيمࣱ وَغَسَاقࣱ', 'هذا فليذوقوه حميم وغساق', NULL, 456, 'local:warsh-text.json'),
  ('warsh-38-57', 'warsh', 38, 57, 'وَءَاخَرُ مِن شَكْلِهِۦٓ أَزْوَٰجٌ࣌', 'وءاخر من شكله أزوج࣌', NULL, 456, 'local:warsh-text.json'),
  ('warsh-38-58', 'warsh', 38, 58, 'هَٰذَا فَوْجࣱ مُّقْتَحِمࣱ مَّعَكُمْ࣌ لَا مَرْحَباَۢ بِهِمُۥٓ࣌ إِنَّهُمْ صَالُواْ ࡲ۬لنّٜارِ࣌', 'هذا فوج مقتحم معكم࣌ لا مرحبا بهم࣌ إنهم صالوا ࡲلنار࣌', NULL, 456, 'local:warsh-text.json'),
  ('warsh-38-59', 'warsh', 38, 59, 'قَالُواْ بَلَ ࡰنتُمْ لَا مَرْحَباَۢ بِكُمُۥٓ أَنتُمْ قَدَّمْتُمُوهُ لَنَا࣌ فَبِيسَ ࡰ۬لْقَرَارُ࣌', 'قالوا بل ࡰنتم لا مرحبا بكم أنتم قدمتموه لنا࣌ فبيس ࡰلقرار࣌', NULL, 456, 'local:warsh-text.json'),
  ('warsh-38-60', 'warsh', 38, 60, 'قَالُواْ رَبَّنَا مَن قَدَّمَ لَنَا هَٰذَا فَزِدْهُ عَذَاباࣰ ضِعْفاࣰ فِے ࡴ۬لنّٜارِ࣌', 'قالوا ربنا من قدم لنا هذا فزده عذابا ضعفا فے ࡴلنار࣌', NULL, 456, 'local:warsh-text.json'),
  ('warsh-38-61', 'warsh', 38, 61, 'وَقَالُواْ مَا لَنَا لَا نَرٜىٰ رِجَالاࣰ كُنَّا نَعُدُّهُم مِّنَ ࡰ۬لَاشْرٜارِ࣌', 'وقالوا ما لنا لا نرى رجالا كنا نعدهم من ࡰلاشرار࣌', NULL, 457, 'local:warsh-text.json'),
  ('warsh-38-62', 'warsh', 38, 62, 'أَتَّخَذْنَٰهُمْ سُخْرِيّاً ࡰمْ زَاغَتْ عَنْهُمُ ࡲ۬لَابْصَٰرُ࣌', 'أتخذنهم سخريا ࡰم زاغت عنهم ࡲلابصر࣌', NULL, 457, 'local:warsh-text.json'),
  ('warsh-38-63', 'warsh', 38, 63, 'إِنَّ ذَٰلِكَ لَحَقࣱّ تَخَاصُمُ أَهْلِ ࡴ۬لنّٜارِ࣌', 'إن ذلك لحق تخاصم أهل ࡴلنار࣌', NULL, 457, 'local:warsh-text.json'),
  ('warsh-38-64', 'warsh', 38, 64, 'قُلِ ࡴنَّمَآ أَنَا مُنذِرࣱ࣌ وَمَا مِنِ ࡴلَٰهٍ ࡴلَّا ࡰ۬للَّهُ ࡲ۬لْوَٰحِدُ ࡲ۬لْقَهَّارُ࣌', 'قل ࡴنما أنا منذر࣌ وما من ࡴله ࡴلا ࡰلله ࡲلوحد ࡲلقهار࣌', NULL, 457, 'local:warsh-text.json'),
  ('warsh-38-65', 'warsh', 38, 65, 'رَبُّ ࡲ۬لسَّمَٰوَٰتِ وَالَارْضِ وَمَا بَيْنَهُمَا࣌ ࡰ۬لْعَزِيزُ ࡲ۬لْغَفَّٰرُ࣌', 'رب ࡲلسموت والارض وما بينهما࣌ ࡰلعزيز ࡲلغفر࣌', NULL, 457, 'local:warsh-text.json'),
  ('warsh-38-66', 'warsh', 38, 66, 'قُلْ هُوَ نَبَؤٌاْ عَظِيمٌ', 'قل هو نبؤا عظيم', NULL, 457, 'local:warsh-text.json'),
  ('warsh-38-67', 'warsh', 38, 67, 'ࡰنتُمْ عَنْهُ مُعْرِضُونَ࣌', 'ࡰنتم عنه معرضون࣌', NULL, 457, 'local:warsh-text.json'),
  ('warsh-38-68', 'warsh', 38, 68, 'مَا كَانَ لِے مِنْ عِلْمِۢ بِالْمَلَإِ ࡴ۬لَاعْلٜىٰٓ إِذْ يَخْتَصِمُونَ࣌', 'ما كان لے من علم بالملإ ࡴلاعلى إذ يختصمون࣌', NULL, 457, 'local:warsh-text.json'),
  ('warsh-38-69', 'warsh', 38, 69, 'إِنْ يُّوحٜىٰٓ إِلَيَّ إِلَّآ أَنَّمَآ أَنَا نَذِيرࣱ مُّبِينٌ࣌', 'إن يوحى إلي إلا أنما أنا نذير مبين࣌', NULL, 457, 'local:warsh-text.json'),
  ('warsh-38-70', 'warsh', 38, 70, 'ࡴذْ قَالَ رَبُّكَ لِلْمَلَٰٓئِكَةِ إِنِّے خَٰلِقُۢ بَشَراࣰ مِّن طِينࣲ', 'ࡴذ قال ربك للملئكة إنے خلق بشرا من طين', NULL, 457, 'local:warsh-text.json'),
  ('warsh-38-71', 'warsh', 38, 71, 'فَإِذَا سَوَّيْتُهُۥ وَنَفَخْتُ فِيهِ مِن رُّوحِے فَقَعُواْ لَهُۥ سَٰجِدِينَ࣌', 'فإذا سويته ونفخت فيه من روحے فقعوا له سجدين࣌', NULL, 457, 'local:warsh-text.json'),
  ('warsh-38-72', 'warsh', 38, 72, 'فَسَجَدَ ࡰ۬لْمَلَٰٓئِكَةُ كُلُّهُمُۥٓ أَجْمَعُونَ', 'فسجد ࡰلملئكة كلهم أجمعون', NULL, 457, 'local:warsh-text.json'),
  ('warsh-38-73', 'warsh', 38, 73, 'إِلَّآ إِبْلِيسَ ࡰٜسْتَكْبَرَ وَكَانَ مِنَ ࡰ۬لْكٜـٰفِرِينَ࣌', 'إلا إبليس ࡰستكبر وكان من ࡰلكفرين࣌', NULL, 457, 'local:warsh-text.json'),
  ('warsh-38-74', 'warsh', 38, 74, 'قَالَ يَٰٓإِبْلِيسُ مَا مَنَعَكَ أَن تَسْجُدَ لِمَا خَلَقْتُ بِيَدَيَّ أَسْتَكْبَرْتَ أَمْ كُنتَ مِنَ ࡰ۬لْعَالِينَ࣌', 'قال يإبليس ما منعك أن تسجد لما خلقت بيدي أستكبرت أم كنت من ࡰلعالين࣌', NULL, 457, 'local:warsh-text.json'),
  ('warsh-38-75', 'warsh', 38, 75, 'قَالَ أَنَا خَيْرࣱ مِّنْهُ خَلَقْتَنِے مِن نّٜارࣲ وَخَلَقْتَهُۥ مِن طِينࣲ࣌', 'قال أنا خير منه خلقتنے من نار وخلقته من طين࣌', NULL, 457, 'local:warsh-text.json'),
  ('warsh-38-76', 'warsh', 38, 76, 'قَالَ فَاخْرُجْ مِنْهَا فَإِنَّكَ رَجِيمࣱ', 'قال فاخرج منها فإنك رجيم', NULL, 457, 'local:warsh-text.json'),
  ('warsh-38-77', 'warsh', 38, 77, 'وَإِنَّ عَلَيْكَ لَعْنَتِيَ إِلَىٰ يَوْمِ ࡴ۬لدِّينِ࣌', 'وإن عليك لعنتي إلى يوم ࡴلدين࣌', NULL, 457, 'local:warsh-text.json'),
  ('warsh-38-78', 'warsh', 38, 78, 'قَالَ رَبِّ فَأَنظِرْنِےٓ إِلَىٰ يَوْمِ يُبْعَثُونَ࣌', 'قال رب فأنظرنے إلى يوم يبعثون࣌', NULL, 457, 'local:warsh-text.json'),
  ('warsh-38-79', 'warsh', 38, 79, 'قَالَ فَإِنَّكَ مِنَ ࡰ۬لْمُنظَرِينَ', 'قال فإنك من ࡰلمنظرين', NULL, 457, 'local:warsh-text.json'),
  ('warsh-38-80', 'warsh', 38, 80, 'إِلَىٰ يَوْمِ ࡴ۬لْوَقْتِ ࡴ۬لْمَعْلُومِ࣌', 'إلى يوم ࡴلوقت ࡴلمعلوم࣌', NULL, 457, 'local:warsh-text.json'),
  ('warsh-38-81', 'warsh', 38, 81, 'قَالَ فَبِعِزَّتِكَ لَأُغْوِيَنَّهُمُۥٓ أَجْمَعِينَ', 'قال فبعزتك لأغوينهم أجمعين', NULL, 457, 'local:warsh-text.json'),
  ('warsh-38-82', 'warsh', 38, 82, 'إِلَّا عِبَادَكَ مِنْهُمُ ࡲ۬لْمُخْلَصِينَ࣌', 'إلا عبادك منهم ࡲلمخلصين࣌', NULL, 457, 'local:warsh-text.json'),
  ('warsh-38-83', 'warsh', 38, 83, '۞ قَالَ فَالْحَقَّ وَالْحَقَّ أَقُولُ࣌ لَأَمْلَأَنَّ جَهَنَّمَ مِنكَ وَمِمَّن تَبِعَكَ مِنْهُمُۥٓ أَجْمَعِينَ࣌', 'قال فالحق والحق أقول࣌ لأملأن جهنم منك وممن تبعك منهم أجمعين࣌', NULL, 458, 'local:warsh-text.json'),
  ('warsh-38-84', 'warsh', 38, 84, 'قُلْ مَآ أَسْـَٔلُكُمْ عَلَيْهِ مِنَ ࡰجْرࣲ وَمَآ أَنَا مِنَ ࡰ۬لْمُتَكَلِّفِينَ࣌', 'قل ما أسلكم عليه من ࡰجر وما أنا من ࡰلمتكلفين࣌', NULL, 458, 'local:warsh-text.json'),
  ('warsh-38-85', 'warsh', 38, 85, 'إِنْ هُوَ إِلَّا ذِكْرࣱ لِّلْعَٰلَمِينَ࣌', 'إن هو إلا ذكر للعلمين࣌', NULL, 458, 'local:warsh-text.json'),
  ('warsh-38-86', 'warsh', 38, 86, 'وَلَتَعْلَمُنَّ نَبَأَهُۥ بَعْدَ حِينࣲ࣌', 'ولتعلمن نبأه بعد حين࣌', NULL, 458, 'local:warsh-text.json'),
  ('warsh-39-1', 'warsh', 39, 1, 'تَنزِيلُ ࡲ۬لْكِتَٰبِ مِنَ ࡰ۬للَّهِ ࡴ۬لْعَزِيزِ ࡴ۬لْحَكِيمِ࣌', 'تنزيل ࡲلكتب من ࡰلله ࡴلعزيز ࡴلحكيم࣌', NULL, 458, 'local:warsh-text.json'),
  ('warsh-39-2', 'warsh', 39, 2, 'إِنَّآ أَنزَلْنَآ إِلَيْكَ ࡰ۬لْكِتَٰبَ بِالْحَقِّ فَاعْبُدِ ࡴ۬للَّهَ مُخْلِصاࣰ لَّهُ ࡲ۬لدِّينَ࣌', 'إنا أنزلنا إليك ࡰلكتب بالحق فاعبد ࡴلله مخلصا له ࡲلدين࣌', NULL, 458, 'local:warsh-text.json'),
  ('warsh-39-3', 'warsh', 39, 3, 'أَلَا لِلهِ ࡴ۬لدِّينُ ࡲ۬لْخَالِصُ࣌ وَالذِينَ ࡰٜتَّخَذُواْ مِن دُونِهِۦٓ أَوْلِيَآءَ مَا نَعْبُدُهُمُۥٓ إِلَّا لِيُقَرِّبُونَآ إِلَى ࡰ۬للَّهِ زُلْفٜىٰٓ࣌ إِنَّ ࡰ۬للَّهَ يَحْكُمُ بَيْنَهُمْ فِے مَا هُمْ فِيهِ يَخْتَلِفُونَ࣌', 'ألا لله ࡴلدين ࡲلخالص࣌ والذين ࡰتخذوا من دونه أولياء ما نعبدهم إلا ليقربونا إلى ࡰلله زلفى࣌ إن ࡰلله يحكم بينهم فے ما هم فيه يختلفون࣌', NULL, 458, 'local:warsh-text.json'),
  ('warsh-39-4', 'warsh', 39, 4, 'إِنَّ ࡰ۬للَّهَ لَا يَهْدِے مَنْ هُوَ كَٰذِبࣱ كَفَّارࣱ࣌', 'إن ࡰلله لا يهدے من هو كذب كفار࣌', NULL, 458, 'local:warsh-text.json'),
  ('warsh-39-5', 'warsh', 39, 5, 'لَّوَ ࡰرَادَ ࡰ۬للَّهُ أَنْ يَّتَّخِذَ وَلَداࣰ لَّاصْطَفٜىٰ مِمَّا يَخْلُقُ مَا يَشَآءُ࣌ سُبْحَٰنَهُۥ࣌ هُوَ ࡰ۬للَّهُ ࡲ۬لْوَٰحِدُ ࡲ۬لْقَهَّارُ࣌', 'لو ࡰراد ࡰلله أن يتخذ ولدا لاصطفى مما يخلق ما يشاء࣌ سبحنه࣌ هو ࡰلله ࡲلوحد ࡲلقهار࣌', NULL, 458, 'local:warsh-text.json'),
  ('warsh-39-6', 'warsh', 39, 6, 'خَلَقَ ࡰ۬لسَّمَٰوَٰتِ وَالَارْضَ بِالْحَقِّ࣌ يُكَوِّرُ ࡲ۬ليْلَ عَلَى ࡰ۬لنَّهٜارِ وَيُكَوِّرُ ࡲ۬لنَّهَارَ عَلَى ࡰ۬ليْلِ࣌ وَسَخَّرَ ࡰ۬لشَّمْسَ وَالْقَمَرَ࣌ كُلࣱّ يَجْرِے لِأَجَلࣲ مُّسَمّىً࣌ ࡰلَا هُوَ ࡰ۬لْعَزِيزُ ࡲ۬لْغَفَّٰرُ࣌', 'خلق ࡰلسموت والارض بالحق࣌ يكور ࡲليل على ࡰلنهار ويكور ࡲلنهار على ࡰليل࣌ وسخر ࡰلشمس والقمر࣌ كل يجرے لأجل مسمى࣌ ࡰلا هو ࡰلعزيز ࡲلغفر࣌', NULL, 458, 'local:warsh-text.json'),
  ('warsh-39-7', 'warsh', 39, 7, 'خَلَقَكُم مِّن نَّفْسࣲ وَٰحِدَةࣲ ثُمَّ جَعَلَ مِنْهَا زَوْجَهَا࣌ وَأَنزَلَ لَكُم مِّنَ ࡰ۬لَانْعَٰمِ ثَمَٰنِيَةَ أَزْوَٰجࣲ࣌ يَخْلُقُكُمْ فِے بُطُونِ أُمَّهَٰتِكُمْ خَلْقاࣰ مِّنۢ بَعْدِ خَلْقࣲ فِے ظُلُمَٰتࣲ ثَلَٰثࣲ࣌ ذَٰلِكُمُ ࡲ۬للَّهُ رَبُّكُمْ لَهُ ࡲ۬لْمُلْكُ࣌ لَآ إِلَٰهَ إِلَّا هُوَ࣌ فَأَنّٜىٰ تُصْرَفُونَ࣌', 'خلقكم من نفس وحدة ثم جعل منها زوجها࣌ وأنزل لكم من ࡰلانعم ثمنية أزوج࣌ يخلقكم فے بطون أمهتكم خلقا من بعد خلق فے ظلمت ثلث࣌ ذلكم ࡲلله ربكم له ࡲلملك࣌ لا إله إلا هو࣌ فأنى تصرفون࣌', NULL, 459, 'local:warsh-text.json'),
  ('warsh-39-8', 'warsh', 39, 8, 'إِن تَكْفُرُواْ فَإِنَّ ࡰ۬للَّهَ غَنِيٌّ عَنكُمْ࣌ وَلَا يَرْضٜىٰ لِعِبَادِهِ ࡴ۬لْكُفْرَ࣌ وَإِن تَشْكُرُواْ يَرْضَهُ لَكُمْ࣌ وَلَا تَزِرُ وَازِرَةࣱ وِزْرَ أُخْرٜىٰ࣌ ثُمَّ إِلَىٰ رَبِّكُم مَّرْجِعُكُمْ فَيُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ࣌ إِنَّهُۥ عَلِيمُۢ بِذَاتِ ࡴ۬لصُّدُورِ࣌', 'إن تكفروا فإن ࡰلله غني عنكم࣌ ولا يرضى لعباده ࡴلكفر࣌ وإن تشكروا يرضه لكم࣌ ولا تزر وازرة وزر أخرى࣌ ثم إلى ربكم مرجعكم فينبئكم بما كنتم تعملون࣌ إنه عليم بذات ࡴلصدور࣌', NULL, 459, 'local:warsh-text.json'),
  ('warsh-39-9', 'warsh', 39, 9, '۞ وَإِذَا مَسَّ ࡰ۬لِانسَٰنَ ضُرࣱّ دَعَا رَبَّهُۥ مُنِيباً ࡴلَيْهِ࣌ ثُمَّ إِذَا خَوَّلَهُۥ نِعْمَةࣰ مِّنْهُ نَسِيَ مَا كَانَ يَدْعُوٓاْ إِلَيْهِ مِن قَبْلُ وَجَعَلَ لِلهِ أَندَاداࣰ لِّيُضِلَّ عَن سَبِيلِهِۦ࣌ قُلْ تَمَتَّعْ بِكُفْرِكَ قَلِيلاً ࡴنَّكَ مِنَ ࡰصْحَٰبِ ࡴ۬لنّٜارِ࣌', 'وإذا مس ࡰلانسن ضر دعا ربه منيبا ࡴليه࣌ ثم إذا خوله نعمة منه نسي ما كان يدعوا إليه من قبل وجعل لله أندادا ليضل عن سبيله࣌ قل تمتع بكفرك قليلا ࡴنك من ࡰصحب ࡴلنار࣌', NULL, 459, 'local:warsh-text.json'),
  ('warsh-39-10', 'warsh', 39, 10, 'أَمَنْ هُوَ قَٰنِتٌ اٰنَآءَ ࡰ۬ليْلِ سَاجِداࣰ وَقَآئِماࣰ يَحْذَرُ ࡲ۬لَاخِرَةَ وَيَرْجُواْ رَحْمَةَ رَبِّهِۦ࣌ قُلْ هَلْ يَسْتَوِے ࡴ۬لذِينَ يَعْلَمُونَ وَالذِينَ لَا يَعْلَمُونَ࣌ إِنَّمَا يَتَذَكَّرُ أُوْلُواْ ࡲ۬لَالْبَٰبِ࣌', 'أمن هو قنت اناء ࡰليل ساجدا وقائما يحذر ࡲلاخرة ويرجوا رحمة ربه࣌ قل هل يستوے ࡴلذين يعلمون والذين لا يعلمون࣌ إنما يتذكر أولوا ࡲلالبب࣌', NULL, 459, 'local:warsh-text.json'),
  ('warsh-39-11', 'warsh', 39, 11, 'قُلْ يَٰعِبَادِ ࡴ۬لذِينَ ءَامَنُواْ ࡲٜتَّقُواْ رَبَّكُمْ࣌ لِلذِينَ أَحْسَنُواْ فِے هَٰذِهِ ࡴ۬لدُّنْيٜا حَسَنَةࣱ࣌ وَأَرْضُ ࡲ۬للَّهِ وَٰسِعَةٌ࣌ ࡴنَّمَا يُوَفَّى ࡰ۬لصَّٰبِرُونَ أَجْرَهُم بِغَيْرِ حِسَابࣲ࣌', 'قل يعباد ࡴلذين ءامنوا ࡲتقوا ربكم࣌ للذين أحسنوا فے هذه ࡴلدنيا حسنة࣌ وأرض ࡲلله وسعة࣌ ࡴنما يوفى ࡰلصبرون أجرهم بغير حساب࣌', NULL, 459, 'local:warsh-text.json'),
  ('warsh-39-12', 'warsh', 39, 12, 'قُلِ ࡴنِّيَ أُمِرْتُ أَنَ ࡰعْبُدَ ࡰ۬للَّهَ مُخْلِصاࣰ لَّهُ ࡲ۬لدِّينَ وَأُمِرْتُ لِأَنَ ࡰكُونَ أَوَّلَ ࡰ۬لْمُسْلِمِينَ࣌', 'قل ࡴني أمرت أن ࡰعبد ࡰلله مخلصا له ࡲلدين وأمرت لأن ࡰكون أول ࡰلمسلمين࣌', NULL, 460, 'local:warsh-text.json'),
  ('warsh-39-13', 'warsh', 39, 13, 'قُلِ ࡴنِّيَ أَخَافُ إِنْ عَصَيْتُ رَبِّے عَذَابَ يَوْمٍ عَظِيمࣲ࣌', 'قل ࡴني أخاف إن عصيت ربے عذاب يوم عظيم࣌', NULL, 460, 'local:warsh-text.json'),
  ('warsh-39-14', 'warsh', 39, 14, 'قُلِ ࡴ۬للَّهَ أَعْبُدُ مُخْلِصاࣰ لَّهُۥ دِينِے࣌ فَاعْبُدُواْ مَا شِئْتُم مِّن دُونِهِۦ࣌ قُلِ ࡴنَّ ࡰ۬لْخَٰسِرِينَ ࡰ۬لذِينَ خَسِرُوٓاْ أَنفُسَهُمْ وَأَهْلِيهِمْ يَوْمَ ࡰ۬لْقِيَٰمَةِ࣌ أَلَا ذَٰلِكَ هُوَ ࡰ۬لْخُسْرَانُ ࡲ۬لْمُبِينُ࣌', 'قل ࡴلله أعبد مخلصا له دينے࣌ فاعبدوا ما شئتم من دونه࣌ قل ࡴن ࡰلخسرين ࡰلذين خسروا أنفسهم وأهليهم يوم ࡰلقيمة࣌ ألا ذلك هو ࡰلخسران ࡲلمبين࣌', NULL, 460, 'local:warsh-text.json'),
  ('warsh-39-15', 'warsh', 39, 15, 'لَهُم مِّن فَوْقِهِمْ ظُلَلࣱ مِّنَ ࡰ۬لنّٜارِ وَمِن تَحْتِهِمْ ظُلَلࣱ࣌ ذَٰلِكَ يُخَوِّفُ ࡲ۬للَّهُ بِهِۦ عِبَادَهُۥ࣌ يَٰعِبَادِ فَاتَّقُونِ࣌', 'لهم من فوقهم ظلل من ࡰلنار ومن تحتهم ظلل࣌ ذلك يخوف ࡲلله به عباده࣌ يعباد فاتقون࣌', NULL, 460, 'local:warsh-text.json'),
  ('warsh-39-16', 'warsh', 39, 16, 'وَالذِينَ ࡰٜجْتَنَبُواْ ࡲ۬لطَّٰغُوتَ أَنْ يَّعْبُدُوهَا وَأَنَابُوٓاْ إِلَى ࡰ۬للَّهِ لَهُمُ ࡲ۬لْبُشْرٜىٰ࣌ فَبَشِّرْ عِبَادِ', 'والذين ࡰجتنبوا ࡲلطغوت أن يعبدوها وأنابوا إلى ࡰلله لهم ࡲلبشرى࣌ فبشر عباد', NULL, 460, 'local:warsh-text.json'),
  ('warsh-39-17', 'warsh', 39, 17, 'ࡴ۬لذِينَ يَسْتَمِعُونَ ࡰ۬لْقَوْلَ فَيَتَّبِعُونَ أَحْسَنَهُۥٓ࣌ أُوْلَٰٓئِكَ ࡰ۬لذِينَ هَدٜيٰهُمُ ࡲ۬للَّهُ࣌ وَأُوْلَٰٓئِكَ هُمُۥٓ أُوْلُواْ ࡲ۬لَالْبَٰبِ࣌', 'ࡴلذين يستمعون ࡰلقول فيتبعون أحسنه࣌ أولئك ࡰلذين هديهم ࡲلله࣌ وأولئك هم أولوا ࡲلالبب࣌', NULL, 460, 'local:warsh-text.json'),
  ('warsh-39-18', 'warsh', 39, 18, 'أَفَمَنْ حَقَّ عَلَيْهِ كَلِمَةُ ࡲ۬لْعَذَابِ أَفَأَنتَ تُنقِذُ مَن فِے ࡴ۬لنّٜارِ࣌', 'أفمن حق عليه كلمة ࡲلعذاب أفأنت تنقذ من فے ࡴلنار࣌', NULL, 460, 'local:warsh-text.json'),
  ('warsh-39-19', 'warsh', 39, 19, 'لَٰكِنِ ࡴ۬لذِينَ ࡰٜتَّقَوْاْ رَبَّهُمْ لَهُمْ غُرَفࣱ مِّن فَوْقِهَا غُرَفࣱ مَّبْنِيَّةࣱ تَجْرِے مِن تَحْتِهَا ࡰ۬لَانْهَٰرُ࣌ وَعْدَ ࡰ۬للَّهِ࣌ لَا يُخْلِفُ ࡲ۬للَّهُ ࡲ۬لْمِيعَادَ࣌', 'لكن ࡴلذين ࡰتقوا ربهم لهم غرف من فوقها غرف مبنية تجرے من تحتها ࡰلانهر࣌ وعد ࡰلله࣌ لا يخلف ࡲلله ࡲلميعاد࣌', NULL, 460, 'local:warsh-text.json'),
  ('warsh-39-20', 'warsh', 39, 20, '۞ أَلَمْ تَرَ أَنَّ ࡰ۬للَّهَ أَنزَلَ مِنَ ࡰ۬لسَّمَآءِ مَآءࣰ فَسَلَكَهُۥ يَنَٰبِيعَ فِے ࡴ۬لَارْضِ ثُمَّ يُخْرِجُ بِهِۦ زَرْعاࣰ مُّخْتَلِفاً ࡰلْوَٰنُهُۥ ثُمَّ يَهِيجُ فَتَرٜيٰهُ مُصْفَرّاࣰ ثُمَّ يَجْعَلُهُۥ حُطَٰماً࣌ ࡴنَّ فِے ذَٰلِكَ لَذِكْرٜىٰ لِأُوْلِے ࡴ۬لَالْبَٰبِ࣌', 'ألم تر أن ࡰلله أنزل من ࡰلسماء ماء فسلكه ينبيع فے ࡴلارض ثم يخرج به زرعا مختلفا ࡰلونه ثم يهيج فتريه مصفرا ثم يجعله حطما࣌ ࡴن فے ذلك لذكرى لأولے ࡴلالبب࣌', NULL, 460, 'local:warsh-text.json'),
  ('warsh-39-21', 'warsh', 39, 21, 'أَفَمَن شَرَحَ ࡰ۬للَّهُ صَدْرَهُۥ لِلِاسْلَٰمِ فَهُوَ عَلَىٰ نُورࣲ مِّن رَّبِّهِۦ࣌ فَوَيْلࣱ لِّلْقَٰسِيَةِ قُلُوبُهُم مِّن ذِكْرِ ࡴ۬للَّهِ࣌ أُوْلَٰٓئِكَ فِے ضَلَٰلࣲ مُّبِينٍ࣌', 'أفمن شرح ࡰلله صدره للاسلم فهو على نور من ربه࣌ فويل للقسية قلوبهم من ذكر ࡴلله࣌ أولئك فے ضلل مبين࣌', NULL, 461, 'local:warsh-text.json'),
  ('warsh-39-22', 'warsh', 39, 22, 'ࡴ۬للَّهُ نَزَّلَ أَحْسَنَ ࡰ۬لْحَدِيثِ كِتَٰباࣰ مُّتَشَٰبِهاࣰ مَّثَانِيَ࣌ تَقْشَعِرُّ مِنْهُ جُلُودُ ࡲ۬لذِينَ يَخْشَوْنَ رَبَّهُمْ ثُمَّ تَلِينُ جُلُودُهُمْ وَقُلُوبُهُمُۥٓ إِلَىٰ ذِكْرِ ࡴ۬للَّهِ࣌ ذَٰلِكَ هُدَى ࡰ۬للَّهِ يَهْدِے بِهِۦ مَنْ يَّشَآءُ࣌ وَمَنْ يُّضْلِلِ ࡴ۬للَّهُ فَمَا لَهُۥ مِنْ هَادٍ࣌', 'ࡴلله نزل أحسن ࡰلحديث كتبا متشبها مثاني࣌ تقشعر منه جلود ࡲلذين يخشون ربهم ثم تلين جلودهم وقلوبهم إلى ذكر ࡴلله࣌ ذلك هدى ࡰلله يهدے به من يشاء࣌ ومن يضلل ࡴلله فما له من هاد࣌', NULL, 461, 'local:warsh-text.json'),
  ('warsh-39-23', 'warsh', 39, 23, 'ࡰفَمَنْ يَّتَّقِے بِوَجْهِهِۦ سُوٓءَ ࡰ۬لْعَذَابِ يَوْمَ ࡰ۬لْقِيَٰمَةِ࣌ وَقِيلَ لِلظَّٰلِمِينَ ذُوقُواْ مَا كُنتُمْ تَكْسِبُونَ࣌', 'ࡰفمن يتقے بوجهه سوء ࡰلعذاب يوم ࡰلقيمة࣌ وقيل للظلمين ذوقوا ما كنتم تكسبون࣌', NULL, 461, 'local:warsh-text.json'),
  ('warsh-39-24', 'warsh', 39, 24, 'كَذَّبَ ࡰ۬لذِينَ مِن قَبْلِهِمْ فَأَتٜيٰهُمُ ࡲ۬لْعَذَابُ مِنْ حَيْثُ لَا يَشْعُرُونَ࣌', 'كذب ࡰلذين من قبلهم فأتيهم ࡲلعذاب من حيث لا يشعرون࣌', NULL, 461, 'local:warsh-text.json'),
  ('warsh-39-25', 'warsh', 39, 25, 'فَأَذَاقَهُمُ ࡲ۬للَّهُ ࡲ۬لْخِزْيَ فِے ࡴ۬لْحَيَوٰةِ ࡴ۬لدُّنْيٜا࣌ وَلَعَذَابُ ࡲ۬لَاخِرَةِ أَكْبَرُ لَوْ كَانُواْ يَعْلَمُونَ࣌', 'فأذاقهم ࡲلله ࡲلخزي فے ࡴلحيوة ࡴلدنيا࣌ ولعذاب ࡲلاخرة أكبر لو كانوا يعلمون࣌', NULL, 461, 'local:warsh-text.json'),
  ('warsh-39-26', 'warsh', 39, 26, 'وَلَقَد ضَّرَبْنَا لِلنَّاسِ فِے هَٰذَا ࡰ۬لْقُرْءَانِ مِن كُلِّ مَثَلࣲ لَّعَلَّهُمْ يَتَذَكَّرُونَ', 'ولقد ضربنا للناس فے هذا ࡰلقرءان من كل مثل لعلهم يتذكرون', NULL, 461, 'local:warsh-text.json'),
  ('warsh-39-27', 'warsh', 39, 27, 'قُرْءَاناً عَرَبِيّاً غَيْرَ ذِے عِوَجࣲ لَّعَلَّهُمْ يَتَّقُونَ࣌', 'قرءانا عربيا غير ذے عوج لعلهم يتقون࣌', NULL, 461, 'local:warsh-text.json'),
  ('warsh-39-28', 'warsh', 39, 28, 'ضَرَبَ ࡰ۬للَّهُ مَثَلاࣰ رَّجُلاࣰ فِيهِ شُرَكَآءُ مُتَشَٰكِسُونَ وَرَجُلاࣰ سَلَماࣰ لِّرَجُلٍ࣌ هَلْ يَسْتَوِيَٰنِ مَثَلاً࣌ ࡴ۬لْحَمْدُ لِلهِ࣌ بَلَ ࡰكْثَرُهُمْ لَا يَعْلَمُونَ࣌', 'ضرب ࡰلله مثلا رجلا فيه شركاء متشكسون ورجلا سلما لرجل࣌ هل يستوين مثلا࣌ ࡴلحمد لله࣌ بل ࡰكثرهم لا يعلمون࣌', NULL, 461, 'local:warsh-text.json'),
  ('warsh-39-29', 'warsh', 39, 29, 'إِنَّكَ مَيِّتࣱ وَإِنَّهُم مَّيِّتُونَ', 'إنك ميت وإنهم ميتون', NULL, 461, 'local:warsh-text.json'),
  ('warsh-39-30', 'warsh', 39, 30, 'ثُمَّ إِنَّكُمْ يَوْمَ ࡰ۬لْقِيَٰمَةِ عِندَ رَبِّكُمْ تَخْتَصِمُونَ࣌', 'ثم إنكم يوم ࡰلقيمة عند ربكم تختصمون࣌', NULL, 461, 'local:warsh-text.json'),
  ('warsh-39-31', 'warsh', 39, 31, '۞ فَمَنَ ࡰظْلَمُ مِمَّن كَذَبَ عَلَى ࡰ۬للَّهِ وَكَذَّبَ بِالصِّدْقِ إِذْ جَآءَهُۥٓ࣌ أَلَيْسَ فِے جَهَنَّمَ مَثْوىࣰ لِّلْكٜـٰفِرِينَ࣌', 'فمن ࡰظلم ممن كذب على ࡰلله وكذب بالصدق إذ جاءه࣌ أليس فے جهنم مثوى للكفرين࣌', NULL, 462, 'local:warsh-text.json'),
  ('warsh-39-32', 'warsh', 39, 32, 'وَالذِے جَآءَ بِالصِّدْقِ وَصَدَّقَ بِهِۦٓ أُوْلَٰٓئِكَ هُمُ ࡲ۬لْمُتَّقُونَ࣌', 'والذے جاء بالصدق وصدق به أولئك هم ࡲلمتقون࣌', NULL, 462, 'local:warsh-text.json'),
  ('warsh-39-33', 'warsh', 39, 33, 'لَهُم مَّا يَشَآءُونَ عِندَ رَبِّهِمْ࣌ ذَٰلِكَ جَزَٰٓؤُاْ ࡲ۬لْمُحْسِنِينَ', 'لهم ما يشاءون عند ربهم࣌ ذلك جزؤا ࡲلمحسنين', NULL, 462, 'local:warsh-text.json'),
  ('warsh-39-34', 'warsh', 39, 34, 'لِيُكَفِّرَ ࡰ۬للَّهُ عَنْهُمُۥٓ أَسْوَأَ ࡰ۬لذِے عَمِلُواْ وَيَجْزِيَهُمُۥٓ أَجْرَهُم بِأَحْسَنِ ࡴ۬لذِے كَانُواْ يَعْمَلُونَ࣌', 'ليكفر ࡰلله عنهم أسوأ ࡰلذے عملوا ويجزيهم أجرهم بأحسن ࡴلذے كانوا يعملون࣌', NULL, 462, 'local:warsh-text.json'),
  ('warsh-39-35', 'warsh', 39, 35, 'أَلَيْسَ ࡰ۬للَّهُ بِكَافٍ عَبْدَهُۥ࣌ وَيُخَوِّفُونَكَ بِالذِينَ مِن دُونِهِۦ࣌ وَمَنْ يُّضْلِلِ ࡴ۬للَّهُ فَمَا لَهُۥ مِنْ هَادࣲ࣌ وَمَنْ يَّهْدِ ࡴ۬للَّهُ فَمَا لَهُۥ مِن مُّضِلٍّ࣌ ࡰلَيْسَ ࡰ۬للَّهُ بِعَزِيزࣲ ذِے ࡴٜنتِقَامࣲ࣌', 'أليس ࡰلله بكاف عبده࣌ ويخوفونك بالذين من دونه࣌ ومن يضلل ࡴلله فما له من هاد࣌ ومن يهد ࡴلله فما له من مضل࣌ ࡰليس ࡰلله بعزيز ذے ࡴنتقام࣌', NULL, 462, 'local:warsh-text.json'),
  ('warsh-39-36', 'warsh', 39, 36, 'وَلَئِن سَأَلْتَهُم مَّنْ خَلَقَ ࡰ۬لسَّمَٰوَٰتِ وَالَارْضَ لَيَقُولُنَّ ࡰ۬للَّهُ࣌ قُلَ ࡰفَرَٰٓيْتُم مَّا تَدْعُونَ مِن دُونِ ࡴ۬للَّهِ إِنَ ࡰرَادَنِيَ ࡰ۬للَّهُ بِضُرٍّ هَلْ هُنَّ كَٰشِفَٰتُ ضُرِّهِۦٓ أَوَ ࡰرَادَنِے بِرَحْمَةٍ هَلْ هُنَّ مُمْسِكَٰتُ رَحْمَتِهِۦ࣌ قُلْ حَسْبِيَ ࡰ۬للَّهُ࣌ عَلَيْهِ يَتَوَكَّلُ ࡲ۬لْمُتَوَكِّلُونَ࣌', 'ولئن سألتهم من خلق ࡰلسموت والارض ليقولن ࡰلله࣌ قل ࡰفريتم ما تدعون من دون ࡴلله إن ࡰرادني ࡰلله بضر هل هن كشفت ضره أو ࡰرادنے برحمة هل هن ممسكت رحمته࣌ قل حسبي ࡰلله࣌ عليه يتوكل ࡲلمتوكلون࣌', NULL, 462, 'local:warsh-text.json'),
  ('warsh-39-37', 'warsh', 39, 37, 'قُلْ يَٰقَوْمِ ࡴٜعْمَلُواْ عَلَىٰ مَكَانَتِكُمُۥٓ إِنِّے عَٰمِلࣱ࣌ فَسَوْفَ تَعْلَمُونَ مَنْ يَّاتِيهِ عَذَابࣱ يُخْزِيهِ وَيَحِلُّ عَلَيْهِ عَذَابࣱ مُّقِيمٌ࣌', 'قل يقوم ࡴعملوا على مكانتكم إنے عمل࣌ فسوف تعلمون من ياتيه عذاب يخزيه ويحل عليه عذاب مقيم࣌', NULL, 462, 'local:warsh-text.json'),
  ('warsh-39-38', 'warsh', 39, 38, 'ࡴنَّآ أَنزَلْنَا عَلَيْكَ ࡰ۬لْكِتَٰبَ لِلنَّاسِ بِالْحَقِّ࣌ فَمَنِ ࡴٜهْتَدٜىٰ فَلِنَفْسِهِۦ࣌ وَمَن ضَلَّ فَإِنَّمَا يَضِلُّ عَلَيْهَا࣌ وَمَآ أَنتَ عَلَيْهِم بِوَكِيلٍ࣌', 'ࡴنا أنزلنا عليك ࡰلكتب للناس بالحق࣌ فمن ࡴهتدى فلنفسه࣌ ومن ضل فإنما يضل عليها࣌ وما أنت عليهم بوكيل࣌', NULL, 463, 'local:warsh-text.json'),
  ('warsh-39-39', 'warsh', 39, 39, 'ࡴ۬للَّهُ يَتَوَفَّى ࡰ۬لَانفُسَ حِينَ مَوْتِهَا وَالتِے لَمْ تَمُتْ فِے مَنَامِهَا࣌ فَيُمْسِكُ ࡲ۬لتِے قَضٜىٰ عَلَيْهَا ࡰ۬لْمَوْتَ وَيُرْسِلُ ࡲ۬لُاخْرٜىٰٓ إِلَىٰٓ أَجَلࣲ مُّسَمّىً࣌ ࡴنَّ فِے ذَٰلِكَ لَأٓيَٰتࣲ لِّقَوْمࣲ يَتَفَكَّرُونَ࣌', 'ࡴلله يتوفى ࡰلانفس حين موتها والتے لم تمت فے منامها࣌ فيمسك ࡲلتے قضى عليها ࡰلموت ويرسل ࡲلاخرى إلى أجل مسمى࣌ ࡴن فے ذلك لأيت لقوم يتفكرون࣌', NULL, 463, 'local:warsh-text.json'),
  ('warsh-39-40', 'warsh', 39, 40, '۞ أَمِ ࡴٜتَّخَذُواْ مِن دُونِ ࡴ۬للَّهِ شُفَعَآءَ࣌ قُلَ ࡰوَلَوْ كَانُواْ لَا يَمْلِكُونَ شَيْـٔاࣰ وَلَا يَعْقِلُونَ࣌', 'أم ࡴتخذوا من دون ࡴلله شفعاء࣌ قل ࡰولو كانوا لا يملكون شيا ولا يعقلون࣌', NULL, 463, 'local:warsh-text.json'),
  ('warsh-39-41', 'warsh', 39, 41, 'قُل لِّلهِ ࡴ۬لشَّفَٰعَةُ جَمِيعاࣰ࣌ لَّهُۥ مُلْكُ ࡲ۬لسَّمَٰوَٰتِ وَالَارْضِ࣌ ثُمَّ إِلَيْهِ تُرْجَعُونَ࣌', 'قل لله ࡴلشفعة جميعا࣌ له ملك ࡲلسموت والارض࣌ ثم إليه ترجعون࣌', NULL, 463, 'local:warsh-text.json'),
  ('warsh-39-42', 'warsh', 39, 42, 'وَإِذَا ذُكِرَ ࡰ۬للَّهُ وَحْدَهُ ࡲٜشْمَأَزَّتْ قُلُوبُ ࡲ۬لذِينَ لَا يُومِنُونَ بِالَاخِرَةِ࣌ وَإِذَا ذُكِرَ ࡰ۬لذِينَ مِن دُونِهِۦٓ إِذَا هُمْ يَسْتَبْشِرُونَ࣌', 'وإذا ذكر ࡰلله وحده ࡲشمأزت قلوب ࡲلذين لا يومنون بالاخرة࣌ وإذا ذكر ࡰلذين من دونه إذا هم يستبشرون࣌', NULL, 463, 'local:warsh-text.json'),
  ('warsh-39-43', 'warsh', 39, 43, 'قُلِ ࡴ۬للَّهُمَّ فَاطِرَ ࡰ۬لسَّمَٰوَٰتِ وَالَارْضِ عَٰلِمَ ࡰ۬لْغَيْبِ وَالشَّهَٰدَةِ أَنتَ تَحْكُمُ بَيْنَ عِبَادِكَ فِے مَا كَانُواْ فِيهِ يَخْتَلِفُونَ࣌', 'قل ࡴللهم فاطر ࡰلسموت والارض علم ࡰلغيب والشهدة أنت تحكم بين عبادك فے ما كانوا فيه يختلفون࣌', NULL, 463, 'local:warsh-text.json'),
  ('warsh-39-44', 'warsh', 39, 44, 'وَلَوَ ࡰنَّ لِلذِينَ ظَلَمُواْ مَا فِے ࡴ۬لَارْضِ جَمِيعاࣰ وَمِثْلَهُۥ مَعَهُۥ لَافْتَدَوْاْ بِهِۦ مِن سُوٓءِ ࡴ۬لْعَذَابِ يَوْمَ ࡰ۬لْقِيَٰمَةِ࣌ وَبَدَا لَهُم مِّنَ ࡰ۬للَّهِ مَا لَمْ يَكُونُواْ يَحْتَسِبُونَ࣌', 'ولو ࡰن للذين ظلموا ما فے ࡴلارض جميعا ومثله معه لافتدوا به من سوء ࡴلعذاب يوم ࡰلقيمة࣌ وبدا لهم من ࡰلله ما لم يكونوا يحتسبون࣌', NULL, 463, 'local:warsh-text.json'),
  ('warsh-39-45', 'warsh', 39, 45, 'وَبَدَا لَهُمْ سَيِّـَٔاتُ مَا كَسَبُواْ࣌ وَحَاقَ بِهِم مَّا كَانُواْ بِهِۦ يَسْتَهْزِءُونَ࣌', 'وبدا لهم سيات ما كسبوا࣌ وحاق بهم ما كانوا به يستهزءون࣌', NULL, 464, 'local:warsh-text.json'),
  ('warsh-39-46', 'warsh', 39, 46, 'فَإِذَا مَسَّ ࡰ۬لِانسَٰنَ ضُرࣱّ دَعَانَا ثُمَّ إِذَا خَوَّلْنَٰهُ نِعْمَةࣰ مِّنَّا قَالَ إِنَّمَآ أُوتِيتُهُۥ عَلَىٰ عِلْمِۢ࣌ بَلْ هِيَ فِتْنَةࣱ وَلَٰكِنَّ أَكْثَرَهُمْ لَا يَعْلَمُونَ࣌', 'فإذا مس ࡰلانسن ضر دعانا ثم إذا خولنه نعمة منا قال إنما أوتيته على علم࣌ بل هي فتنة ولكن أكثرهم لا يعلمون࣌', NULL, 464, 'local:warsh-text.json'),
  ('warsh-39-47', 'warsh', 39, 47, 'قَدْ قَالَهَا ࡰ۬لذِينَ مِن قَبْلِهِمْ فَمَآ أَغْنٜىٰ عَنْهُم مَّا كَانُواْ يَكْسِبُونَ࣌', 'قد قالها ࡰلذين من قبلهم فما أغنى عنهم ما كانوا يكسبون࣌', NULL, 464, 'local:warsh-text.json'),
  ('warsh-39-48', 'warsh', 39, 48, 'فَأَصَابَهُمْ سَيِّـَٔاتُ مَا كَسَبُواْ࣌ وَالذِينَ ظَلَمُواْ مِنْ هَٰٓؤُلَآءِ سَيُصِيبُهُمْ سَيِّـَٔاتُ مَا كَسَبُواْ وَمَا هُم بِمُعْجِزِينَ࣌', 'فأصابهم سيات ما كسبوا࣌ والذين ظلموا من هؤلاء سيصيبهم سيات ما كسبوا وما هم بمعجزين࣌', NULL, 464, 'local:warsh-text.json'),
  ('warsh-39-49', 'warsh', 39, 49, 'أَوَلَمْ يَعْلَمُوٓاْ أَنَّ ࡰ۬للَّهَ يَبْسُطُ ࡲ۬لرِّزْقَ لِمَنْ يَّشَآءُ وَيَقْدِرُ࣌ إِنَّ فِے ذَٰلِكَ لَأٓيَٰتࣲ لِّقَوْمࣲ يُومِنُونَ࣌', 'أولم يعلموا أن ࡰلله يبسط ࡲلرزق لمن يشاء ويقدر࣌ إن فے ذلك لأيت لقوم يومنون࣌', NULL, 464, 'local:warsh-text.json'),
  ('warsh-39-50', 'warsh', 39, 50, 'قُلْ يَٰعِبَادِيَ ࡰ۬لذِينَ أَسْرَفُواْ عَلَىٰٓ أَنفُسِهِمْ لَا تَقْنَطُواْ مِن رَّحْمَةِ ࡴ۬للَّهِ࣌ إِنَّ ࡰ۬للَّهَ يَغْفِرُ ࡲ۬لذُّنُوبَ جَمِيعاً࣌ ࡴنَّهُۥ هُوَ ࡰ۬لْغَفُورُ ࡲ۬لرَّحِيمُ࣌', 'قل يعبادي ࡰلذين أسرفوا على أنفسهم لا تقنطوا من رحمة ࡴلله࣌ إن ࡰلله يغفر ࡲلذنوب جميعا࣌ ࡴنه هو ࡰلغفور ࡲلرحيم࣌', NULL, 464, 'local:warsh-text.json'),
  ('warsh-39-51', 'warsh', 39, 51, '۞ وَأَنِيبُوٓاْ إِلَىٰ رَبِّكُمْ وَأَسْلِمُواْ لَهُۥ مِن قَبْلِ أَنْ يَّاتِيَكُمُ ࡲ۬لْعَذَابُ ثُمَّ لَا تُنصَرُونَ࣌', 'وأنيبوا إلى ربكم وأسلموا له من قبل أن ياتيكم ࡲلعذاب ثم لا تنصرون࣌', NULL, 464, 'local:warsh-text.json'),
  ('warsh-39-52', 'warsh', 39, 52, 'وَاتَّبِعُوٓاْ أَحْسَنَ مَآ أُنزِلَ إِلَيْكُم مِّن رَّبِّكُم مِّن قَبْلِ أَنْ يَّاتِيَكُمُ ࡲ۬لْعَذَابُ بَغْتَةࣰ وَأَنتُمْ لَا تَشْعُرُونَ', 'واتبعوا أحسن ما أنزل إليكم من ربكم من قبل أن ياتيكم ࡲلعذاب بغتة وأنتم لا تشعرون', NULL, 464, 'local:warsh-text.json'),
  ('warsh-39-53', 'warsh', 39, 53, 'أَن تَقُولَ نَفْسࣱ يَٰحَسْرَتٜىٰ عَلَىٰ مَا فَرَّطْتُّ فِے جَنۢبِ ࡴ۬للَّهِ وَإِن كُنتُ لَمِنَ ࡰ۬لسَّٰخِرِينَ', 'أن تقول نفس يحسرتى على ما فرطت فے جنب ࡴلله وإن كنت لمن ࡰلسخرين', NULL, 464, 'local:warsh-text.json'),
  ('warsh-39-54', 'warsh', 39, 54, 'أَوْ تَقُولَ لَوَ ࡰنَّ ࡰ۬للَّهَ هَدٜيٰنِے لَكُنتُ مِنَ ࡰ۬لْمُتَّقِينَ', 'أو تقول لو ࡰن ࡰلله هدينے لكنت من ࡰلمتقين', NULL, 465, 'local:warsh-text.json'),
  ('warsh-39-55', 'warsh', 39, 55, 'أَوْ تَقُولَ حِينَ تَرَى ࡰ۬لْعَذَابَ لَوَ ࡰنَّ لِے كَرَّةࣰ فَأَكُونَ مِنَ ࡰ۬لْمُحْسِنِينَ࣌', 'أو تقول حين ترى ࡰلعذاب لو ࡰن لے كرة فأكون من ࡰلمحسنين࣌', NULL, 465, 'local:warsh-text.json'),
  ('warsh-39-56', 'warsh', 39, 56, 'بَلٜىٰ قَدْ جَآءَتْكَ ءَايَٰتِے فَكَذَّبْتَ بِهَا وَاسْتَكْبَرْتَ وَكُنتَ مِنَ ࡰ۬لْكٜـٰفِرِينَ࣌', 'بلى قد جاءتك ءايتے فكذبت بها واستكبرت وكنت من ࡰلكفرين࣌', NULL, 465, 'local:warsh-text.json'),
  ('warsh-39-57', 'warsh', 39, 57, 'وَيَوْمَ ࡰ۬لْقِيَٰمَةِ تَرَى ࡰ۬لذِينَ كَذَبُواْ عَلَى ࡰ۬للَّهِ وُجُوهُهُم مُّسْوَدَّةٌ࣌ ࡰلَيْسَ فِے جَهَنَّمَ مَثْوىࣰ لِّلْمُتَكَبِّرِينَ࣌', 'ويوم ࡰلقيمة ترى ࡰلذين كذبوا على ࡰلله وجوههم مسودة࣌ ࡰليس فے جهنم مثوى للمتكبرين࣌', NULL, 465, 'local:warsh-text.json'),
  ('warsh-39-58', 'warsh', 39, 58, 'وَيُنَجِّے ࡴ۬للَّهُ ࡲ۬لذِينَ ࡰٜتَّقَوْاْ بِمَفَازَتِهِمْ لَا يَمَسُّهُمُ ࡲ۬لسُّوٓءُ وَلَا هُمْ يَحْزَنُونَ࣌', 'وينجے ࡴلله ࡲلذين ࡰتقوا بمفازتهم لا يمسهم ࡲلسوء ولا هم يحزنون࣌', NULL, 465, 'local:warsh-text.json'),
  ('warsh-39-59', 'warsh', 39, 59, 'ࡰ۬للَّهُ خَٰلِقُ كُلِّ شَےْءࣲ࣌ وَهُوَ عَلَىٰ كُلِّ شَےْءࣲ وَكِيلࣱ࣌', 'ࡰلله خلق كل شےء࣌ وهو على كل شےء وكيل࣌', NULL, 465, 'local:warsh-text.json'),
  ('warsh-39-60', 'warsh', 39, 60, 'لَّهُۥ مَقَالِيدُ ࡲ۬لسَّمَٰوَٰتِ وَالَارْضِ࣌ وَالذِينَ كَفَرُواْ بِـَٔايَٰتِ ࡴ۬للَّهِ أُوْلَٰٓئِكَ هُمُ ࡲ۬لْخَٰسِرُونَ࣌', 'له مقاليد ࡲلسموت والارض࣌ والذين كفروا بايت ࡴلله أولئك هم ࡲلخسرون࣌', NULL, 465, 'local:warsh-text.json'),
  ('warsh-39-61', 'warsh', 39, 61, 'قُلَ ࡰفَغَيْرَ ࡰ۬للَّهِ تَامُرُونِيَ أَعْبُدُ أَيُّهَا ࡰ۬لْجَٰهِلُونَ࣌', 'قل ࡰفغير ࡰلله تامروني أعبد أيها ࡰلجهلون࣌', NULL, 465, 'local:warsh-text.json'),
  ('warsh-39-62', 'warsh', 39, 62, 'وَلَقَدُ ࡳوحِيَ إِلَيْكَ وَإِلَى ࡰ۬لذِينَ مِن قَبْلِكَ لَئِنَ ࡰشْرَكْتَ لَيَحْبَطَنَّ عَمَلُكَ وَلَتَكُونَنَّ مِنَ ࡰ۬لْخَٰسِرِينَ࣌', 'ولقد ࡳوحي إليك وإلى ࡰلذين من قبلك لئن ࡰشركت ليحبطن عملك ولتكونن من ࡰلخسرين࣌', NULL, 465, 'local:warsh-text.json'),
  ('warsh-39-63', 'warsh', 39, 63, 'بَلِ ࡴ۬للَّهَ فَاعْبُدْ وَكُن مِّنَ ࡰ۬لشَّٰكِرِينَ࣌', 'بل ࡴلله فاعبد وكن من ࡰلشكرين࣌', NULL, 465, 'local:warsh-text.json'),
  ('warsh-39-64', 'warsh', 39, 64, '۞ وَمَا قَدَرُواْ ࡲ۬للَّهَ حَقَّ قَدْرِهِۦ وَالَارْضُ جَمِيعاࣰ قَبْضَتُهُۥ يَوْمَ ࡰ۬لْقِيَٰمَةِ وَالسَّمَٰوَٰتُ مَطْوِيَّٰتُۢ بِيَمِينِهِۦ࣌ سُبْحَٰنَهُۥ وَتَعَٰلٜىٰ عَمَّا يُشْرِكُونَ࣌', 'وما قدروا ࡲلله حق قدره والارض جميعا قبضته يوم ࡰلقيمة والسموت مطويت بيمينه࣌ سبحنه وتعلى عما يشركون࣌', NULL, 465, 'local:warsh-text.json'),
  ('warsh-39-65', 'warsh', 39, 65, 'وَنُفِخَ فِے ࡴ۬لصُّورِ فَصَعِقَ مَن فِے ࡴ۬لسَّمَٰوَٰتِ وَمَن فِے ࡴ۬لَارْضِ إِلَّا مَن شَآءَ ࡰ۬للَّهُ࣌ ثُمَّ نُفِخَ فِيهِ أُخْرٜىٰ فَإِذَا هُمْ قِيَامࣱ يَنظُرُونَ࣌', 'ونفخ فے ࡴلصور فصعق من فے ࡴلسموت ومن فے ࡴلارض إلا من شاء ࡰلله࣌ ثم نفخ فيه أخرى فإذا هم قيام ينظرون࣌', NULL, 466, 'local:warsh-text.json'),
  ('warsh-39-66', 'warsh', 39, 66, 'وَأَشْرَقَتِ ࡴ۬لَارْضُ بِنُورِ رَبِّهَا وَوُضِعَ ࡰ۬لْكِتَٰبُ وَجِےٓءَ بِالنَّبِيٓـِٕۑنَ وَالشُّهَدَآءِ وَقُضِيَ بَيْنَهُم بِالْحَقِّ وَهُمْ لَا يُظْلَمُونَ࣌', 'وأشرقت ࡴلارض بنور ربها ووضع ࡰلكتب وجےء بالنبيۑن والشهداء وقضي بينهم بالحق وهم لا يظلمون࣌', NULL, 466, 'local:warsh-text.json'),
  ('warsh-39-67', 'warsh', 39, 67, 'وَوُفِّيَتْ كُلُّ نَفْسࣲ مَّا عَمِلَتْ وَهُوَ أَعْلَمُ بِمَا يَفْعَلُونَ࣌', 'ووفيت كل نفس ما عملت وهو أعلم بما يفعلون࣌', NULL, 466, 'local:warsh-text.json'),
  ('warsh-39-68', 'warsh', 39, 68, 'وَسِيقَ ࡰ۬لذِينَ كَفَرُوٓاْ إِلَىٰ جَهَنَّمَ زُمَراً࣌ حَتَّىٰٓ إِذَا جَآءُوهَا فُتِّحَتَ ࡰبْوَٰبُهَا وَقَالَ لَهُمْ خَزَنَتُهَآ أَلَمْ يَاتِكُمْ رُسُلࣱ مِّنكُمْ يَتْلُونَ عَلَيْكُمُۥٓ ءَايَٰتِ رَبِّكُمْ وَيُنذِرُونَكُمْ لِقَآءَ يَوْمِكُمْ هَٰذَا࣌ قَالُواْ بَلٜىٰ وَلَٰكِنْ حَقَّتْ كَلِمَةُ ࡲ۬لْعَذَابِ عَلَى ࡰ۬لْكٜـٰفِرِينَ࣌', 'وسيق ࡰلذين كفروا إلى جهنم زمرا࣌ حتى إذا جاءوها فتحت ࡰبوبها وقال لهم خزنتها ألم ياتكم رسل منكم يتلون عليكم ءايت ربكم وينذرونكم لقاء يومكم هذا࣌ قالوا بلى ولكن حقت كلمة ࡲلعذاب على ࡰلكفرين࣌', NULL, 466, 'local:warsh-text.json'),
  ('warsh-39-69', 'warsh', 39, 69, 'قِيلَ ࡸَدْخُلُوٓاْ أَبْوَٰبَ جَهَنَّمَ خَٰلِدِينَ فِيهَا࣌ فَبِيسَ مَثْوَى ࡰ۬لْمُتَكَبِّرِينَ࣌', 'قيل ࡸدخلوا أبوب جهنم خلدين فيها࣌ فبيس مثوى ࡰلمتكبرين࣌', NULL, 466, 'local:warsh-text.json'),
  ('warsh-39-70', 'warsh', 39, 70, 'وَسِيقَ ࡰ۬لذِينَ ࡰٜتَّقَوْاْ رَبَّهُمُۥٓ إِلَى ࡰ۬لْجَنَّةِ زُمَراً࣌ حَتَّىٰٓ إِذَا جَآءُوهَا وَفُتِّحَتَ ࡰبْوَٰبُهَا وَقَالَ لَهُمْ خَزَنَتُهَا سَلَٰمٌ عَلَيْكُمْ طِبْتُمْ فَادْخُلُوهَا خَٰلِدِينَ࣌', 'وسيق ࡰلذين ࡰتقوا ربهم إلى ࡰلجنة زمرا࣌ حتى إذا جاءوها وفتحت ࡰبوبها وقال لهم خزنتها سلم عليكم طبتم فادخلوها خلدين࣌', NULL, 466, 'local:warsh-text.json'),
  ('warsh-39-71', 'warsh', 39, 71, 'وَقَالُواْ ࡲ۬لْحَمْدُ لِلهِ ࡴ۬لذِے صَدَقَنَا وَعْدَهُۥ وَأَوْرَثَنَا ࡰ۬لَارْضَ نَتَبَوَّأُ مِنَ ࡰ۬لْجَنَّةِ حَيْثُ نَشَآءُ فَنِعْمَ أَجْرُ ࡲ۬لْعَٰمِلِينَ࣌', 'وقالوا ࡲلحمد لله ࡴلذے صدقنا وعده وأورثنا ࡰلارض نتبوأ من ࡰلجنة حيث نشاء فنعم أجر ࡲلعملين࣌', NULL, 466, 'local:warsh-text.json'),
  ('warsh-39-72', 'warsh', 39, 72, 'وَتَرَى ࡰ۬لْمَلَٰٓئِكَةَ حَآفِّينَ مِنْ حَوْلِ ࡴ۬لْعَرْشِ يُسَبِّحُونَ بِحَمْدِ رَبِّهِمْ࣌ وَقُضِيَ بَيْنَهُم بِالْحَقِّ࣌ وَقِيلَ ࡰ۬لْحَمْدُ لِلهِ رَبِّ ࡴ۬لْعَٰلَمِينَ࣌', 'وترى ࡰلملئكة حافين من حول ࡴلعرش يسبحون بحمد ربهم࣌ وقضي بينهم بالحق࣌ وقيل ࡰلحمد لله رب ࡴلعلمين࣌', NULL, 467, 'local:warsh-text.json'),
  ('warsh-40-1', 'warsh', 40, 1, 'حٜمِٓ࣌ تَنزِيلُ ࡲ۬لْكِتَٰبِ مِنَ ࡰ۬للَّهِ ࡴ۬لْعَزِيزِ ࡴ۬لْعَلِيمِ', 'حم࣌ تنزيل ࡲلكتب من ࡰلله ࡴلعزيز ࡴلعليم', NULL, 467, 'local:warsh-text.json'),
  ('warsh-40-2', 'warsh', 40, 2, 'غَافِرِ ࡴ۬لذَّنۢبِ وَقَابِلِ ࡴ۬لتَّوْبِ شَدِيدِ ࡴ۬لْعِقَابِ ذِے ࡴ۬لطَّوْلِ࣌ لَآ إِلَٰهَ إِلَّا هُوَ࣌ إِلَيْهِ ࡴ۬لْمَصِيرُ࣌', 'غافر ࡴلذنب وقابل ࡴلتوب شديد ࡴلعقاب ذے ࡴلطول࣌ لا إله إلا هو࣌ إليه ࡴلمصير࣌', NULL, 467, 'local:warsh-text.json'),
  ('warsh-40-3', 'warsh', 40, 3, 'مَا يُجَٰدِلُ فِےٓ ءَايَٰتِ ࡴ۬للَّهِ إِلَّا ࡰ۬لذِينَ كَفَرُواْ࣌ فَلَا يَغْرُرْكَ تَقَلُّبُهُمْ فِے ࡴ۬لْبِلَٰدِ࣌', 'ما يجدل فے ءايت ࡴلله إلا ࡰلذين كفروا࣌ فلا يغررك تقلبهم فے ࡴلبلد࣌', NULL, 467, 'local:warsh-text.json'),
  ('warsh-40-4', 'warsh', 40, 4, 'كَذَّبَتْ قَبْلَهُمْ قَوْمُ نُوحࣲ وَالَاحْزَابُ مِنۢ بَعْدِهِمْ࣌ وَهَمَّتْ كُلُّ أُمَّةِۢ بِرَسُولِهِمْ لِيَاخُذُوهُ࣌ وَجَٰدَلُواْ بِالْبَٰطِلِ لِيُدْحِضُواْ بِهِ ࡴ۬لْحَقَّ فَأَخَذتُّهُمْ࣌ فَكَيْفَ كَانَ عِقَابِ࣌', 'كذبت قبلهم قوم نوح والاحزاب من بعدهم࣌ وهمت كل أمة برسولهم لياخذوه࣌ وجدلوا بالبطل ليدحضوا به ࡴلحق فأخذتهم࣌ فكيف كان عقاب࣌', NULL, 467, 'local:warsh-text.json'),
  ('warsh-40-5', 'warsh', 40, 5, 'وَكَذَٰلِكَ حَقَّتْ كَلِمَٰتُ رَبِّكَ عَلَى ࡰ۬لذِينَ كَفَرُوٓاْ أَنَّهُمُۥٓ أَصْحَٰبُ ࡲ۬لنّٜارِ࣌', 'وكذلك حقت كلمت ربك على ࡰلذين كفروا أنهم أصحب ࡲلنار࣌', NULL, 467, 'local:warsh-text.json'),
  ('warsh-40-6', 'warsh', 40, 6, 'ࡴ۬لذِينَ يَحْمِلُونَ ࡰ۬لْعَرْشَ وَمَنْ حَوْلَهُۥ يُسَبِّحُونَ بِحَمْدِ رَبِّهِمْ وَيُومِنُونَ بِهِۦ وَيَسْتَغْفِرُونَ لِلذِينَ ءَامَنُواْ࣌ رَبَّنَا وَسِعْتَ كُلَّ شَےْءࣲ رَّحْمَةࣰ وَعِلْماࣰ فَاغْفِرْ لِلذِينَ تَابُواْ وَاتَّبَعُواْ سَبِيلَكَ وَقِهِمْ عَذَابَ ࡰ۬لْجَحِيمِ࣌', 'ࡴلذين يحملون ࡰلعرش ومن حوله يسبحون بحمد ربهم ويومنون به ويستغفرون للذين ءامنوا࣌ ربنا وسعت كل شےء رحمة وعلما فاغفر للذين تابوا واتبعوا سبيلك وقهم عذاب ࡰلجحيم࣌', NULL, 467, 'local:warsh-text.json'),
  ('warsh-40-7', 'warsh', 40, 7, 'رَبَّنَا وَأَدْخِلْهُمْ جَنَّٰتِ عَدْنٍ ࡴ۬لتِے وَعَدتَّهُمْ وَمَن صَلَحَ مِنَ اٰبَآئِهِمْ وَأَزْوَٰجِهِمْ وَذُرِّيَّٰتِهِمُۥٓ࣌ إِنَّكَ أَنتَ ࡰ۬لْعَزِيزُ ࡲ۬لْحَكِيمُ࣌', 'ربنا وأدخلهم جنت عدن ࡴلتے وعدتهم ومن صلح من ابائهم وأزوجهم وذريتهم࣌ إنك أنت ࡰلعزيز ࡲلحكيم࣌', NULL, 468, 'local:warsh-text.json'),
  ('warsh-40-8', 'warsh', 40, 8, 'وَقِهِمُ ࡲ۬لسَّيِّـَٔاتِ࣌ وَمَن تَقِ ࡴ۬لسَّيِّـَٔاتِ يَوْمَئِذࣲ فَقَدْ رَحِمْتَهُۥ࣌ وَذَٰلِكَ هُوَ ࡰ۬لْفَوْزُ ࡲ۬لْعَظِيمُ࣌', 'وقهم ࡲلسيات࣌ ومن تق ࡴلسيات يومئذ فقد رحمته࣌ وذلك هو ࡰلفوز ࡲلعظيم࣌', NULL, 468, 'local:warsh-text.json'),
  ('warsh-40-9', 'warsh', 40, 9, 'إِنَّ ࡰ۬لذِينَ كَفَرُواْ يُنَادَوْنَ لَمَقْتُ ࡲ۬للَّهِ أَكْبَرُ مِن مَّقْتِكُمُۥٓ أَنفُسَكُمُۥٓ إِذْ تُدْعَوْنَ إِلَى ࡰ۬لِايمَٰنِ فَتَكْفُرُونَ࣌', 'إن ࡰلذين كفروا ينادون لمقت ࡲلله أكبر من مقتكم أنفسكم إذ تدعون إلى ࡰلايمن فتكفرون࣌', NULL, 468, 'local:warsh-text.json'),
  ('warsh-40-10', 'warsh', 40, 10, '۞ قَالُواْ رَبَّنَآ أَمَتَّنَا ࡰٜثْنَتَيْنِ وَأَحْيَيْتَنَا ࡰٜثْنَتَيْنِ فَاعْتَرَفْنَا بِذُنُوبِنَا فَهَلِ ࡴلَىٰ خُرُوجࣲ مِّن سَبِيلࣲ࣌', 'قالوا ربنا أمتنا ࡰثنتين وأحييتنا ࡰثنتين فاعترفنا بذنوبنا فهل ࡴلى خروج من سبيل࣌', NULL, 468, 'local:warsh-text.json'),
  ('warsh-40-11', 'warsh', 40, 11, 'ذَٰلِكُم بِأَنَّهُۥٓ إِذَا دُعِيَ ࡰ۬للَّهُ وَحْدَهُۥ كَفَرْتُمْ وَإِنْ يُّشْرَكْ بِهِۦ تُومِنُواْ࣌ فَالْحُكْمُ لِلهِ ࡴ۬لْعَلِيِّ ࡴ۬لْكَبِيرِ࣌', 'ذلكم بأنه إذا دعي ࡰلله وحده كفرتم وإن يشرك به تومنوا࣌ فالحكم لله ࡴلعلي ࡴلكبير࣌', NULL, 468, 'local:warsh-text.json'),
  ('warsh-40-12', 'warsh', 40, 12, 'هُوَ ࡰ۬لذِے يُرِيكُمُۥٓ ءَايَٰتِهِۦ وَيُنَزِّلُ لَكُم مِّنَ ࡰ۬لسَّمَآءِ رِزْقاࣰ࣌ وَمَا يَتَذَكَّرُ إِلَّا مَنْ يُّنِيبُ࣌', 'هو ࡰلذے يريكم ءايته وينزل لكم من ࡰلسماء رزقا࣌ وما يتذكر إلا من ينيب࣌', NULL, 468, 'local:warsh-text.json'),
  ('warsh-40-13', 'warsh', 40, 13, 'فَادْعُواْ ࡲ۬للَّهَ مُخْلِصِينَ لَهُ ࡲ۬لدِّينَ وَلَوْ كَرِهَ ࡰ۬لْكَٰفِرُونَ࣌', 'فادعوا ࡲلله مخلصين له ࡲلدين ولو كره ࡰلكفرون࣌', NULL, 468, 'local:warsh-text.json'),
  ('warsh-40-14', 'warsh', 40, 14, 'رَفِيعُ ࡲ۬لدَّرَجَٰتِ ذُو ࡲ۬لْعَرْشِ࣌ يُلْقِے ࡴ۬لرُّوحَ مِنَ ࡰمْرِهِۦ عَلَىٰ مَنْ يَّشَآءُ مِنْ عِبَادِهِۦ لِيُنذِرَ يَوْمَ ࡰ۬لتَّلَٰقِۦ', 'رفيع ࡲلدرجت ذو ࡲلعرش࣌ يلقے ࡴلروح من ࡰمره على من يشاء من عباده لينذر يوم ࡰلتلق', NULL, 468, 'local:warsh-text.json'),
  ('warsh-40-15', 'warsh', 40, 15, 'يَوْمَ هُم بَٰرِزُونَ࣌ لَا يَخْفٜىٰ عَلَى ࡰ۬للَّهِ مِنْهُمْ شَےْءࣱ࣌ لِّمَنِ ࡴ۬لْمُلْكُ ࡲ۬لْيَوْمَ࣌ لِلهِ ࡴ۬لْوَٰحِدِ ࡴ۬لْقَهّٜارِ࣌', 'يوم هم برزون࣌ لا يخفى على ࡰلله منهم شےء࣌ لمن ࡴلملك ࡲليوم࣌ لله ࡴلوحد ࡴلقهار࣌', NULL, 468, 'local:warsh-text.json'),
  ('warsh-40-16', 'warsh', 40, 16, 'ࡴ۬لْيَوْمَ تُجْزٜىٰ كُلُّ نَفْسِۢ بِمَا كَسَبَتْ࣌ لَا ظُلْمَ ࡰ۬لْيَوْمَ࣌ إِنَّ ࡰ۬للَّهَ سَرِيعُ ࡲ۬لْحِسَابِ࣌', 'ࡴليوم تجزى كل نفس بما كسبت࣌ لا ظلم ࡰليوم࣌ إن ࡰلله سريع ࡲلحساب࣌', NULL, 469, 'local:warsh-text.json'),
  ('warsh-40-17', 'warsh', 40, 17, 'وَأَنذِرْهُمْ يَوْمَ ࡰ۬لَازِفَةِ إِذِ ࡴ۬لْقُلُوبُ لَدَى ࡰ۬لْحَنَاجِرِ كَٰظِمِينَ࣌', 'وأنذرهم يوم ࡰلازفة إذ ࡴلقلوب لدى ࡰلحناجر كظمين࣌', NULL, 469, 'local:warsh-text.json'),
  ('warsh-40-18', 'warsh', 40, 18, 'مَا لِلظَّٰلِمِينَ مِنْ حَمِيمࣲ وَلَا شَفِيعࣲ يُطَاعُ࣌', 'ما للظلمين من حميم ولا شفيع يطاع࣌', NULL, 469, 'local:warsh-text.json'),
  ('warsh-40-19', 'warsh', 40, 19, 'يَعْلَمُ خَآئِنَةَ ࡰ۬لَاعْيُنِ وَمَا تُخْفِے ࡴ۬لصُّدُورُ࣌', 'يعلم خائنة ࡰلاعين وما تخفے ࡴلصدور࣌', NULL, 469, 'local:warsh-text.json'),
  ('warsh-40-20', 'warsh', 40, 20, 'وَاللَّهُ يَقْضِے بِالْحَقِّ࣌ وَالذِينَ تَدْعُونَ مِن دُونِهِۦ لَا يَقْضُونَ بِشَےْءٍ࣌ ࡴنَّ ࡰ۬للَّهَ هُوَ ࡰ۬لسَّمِيعُ ࡲ۬لْبَصِيرُ࣌', 'والله يقضے بالحق࣌ والذين تدعون من دونه لا يقضون بشےء࣌ ࡴن ࡰلله هو ࡰلسميع ࡲلبصير࣌', NULL, 469, 'local:warsh-text.json'),
  ('warsh-40-21', 'warsh', 40, 21, '۞ أَوَلَمْ يَسِيرُواْ فِے ࡴ۬لَارْضِ فَيَنظُرُواْ كَيْفَ كَانَ عَٰقِبَةُ ࡲ۬لذِينَ كَانُواْ مِن قَبْلِهِمْ࣌ كَانُواْ هُمُۥٓ أَشَدَّ مِنْهُمْ قُوَّةࣰ وَءَاثَاراࣰ فِے ࡴ۬لَارْضِ فَأَخَذَهُمُ ࡲ۬للَّهُ بِذُنُوبِهِمْ࣌ وَمَا كَانَ لَهُم مِّنَ ࡰ۬للَّهِ مِنْ وَّاقࣲ࣌', 'أولم يسيروا فے ࡴلارض فينظروا كيف كان عقبة ࡲلذين كانوا من قبلهم࣌ كانوا هم أشد منهم قوة وءاثارا فے ࡴلارض فأخذهم ࡲلله بذنوبهم࣌ وما كان لهم من ࡰلله من واق࣌', NULL, 469, 'local:warsh-text.json'),
  ('warsh-40-22', 'warsh', 40, 22, 'ذَٰلِكَ بِأَنَّهُمْ كَانَت تَّاتِيهِمْ رُسُلُهُم بِالْبَيِّنَٰتِ فَكَفَرُواْ فَأَخَذَهُمُ ࡲ۬للَّهُ࣌ إِنَّهُۥ قَوِيࣱّ شَدِيدُ ࡲ۬لْعِقَابِ࣌', 'ذلك بأنهم كانت تاتيهم رسلهم بالبينت فكفروا فأخذهم ࡲلله࣌ إنه قوي شديد ࡲلعقاب࣌', NULL, 469, 'local:warsh-text.json'),
  ('warsh-40-23', 'warsh', 40, 23, 'وَلَقَدَ ࡰرْسَلْنَا مُوسٜىٰ بِـَٔايَٰتِنَا وَسُلْطَٰنࣲ مُّبِينٍ', 'ولقد ࡰرسلنا موسى بايتنا وسلطن مبين', NULL, 469, 'local:warsh-text.json'),
  ('warsh-40-24', 'warsh', 40, 24, 'ࡴلَىٰ فِرْعَوْنَ وَهَامَٰنَ وَقَارُونَ فَقَالُواْ سَٰحِرࣱ كَذَّابࣱ࣌', 'ࡴلى فرعون وهامن وقارون فقالوا سحر كذاب࣌', NULL, 469, 'local:warsh-text.json'),
  ('warsh-40-25', 'warsh', 40, 25, 'فَلَمَّا جَآءَهُم بِالْحَقِّ مِنْ عِندِنَا قَالُواْ ࡲ࢈قْتُلُوٓاْ أَبْنَآءَ ࡰ۬لذِينَ ءَامَنُواْ مَعَهُۥ وَاسْتَحْيُواْ نِسَآءَهُمْ࣌ وَمَا كَيْدُ ࡲ۬لْكٜـٰفِرِينَ إِلَّا فِے ضَلَٰلࣲ࣌', 'فلما جاءهم بالحق من عندنا قالوا ࡲ࢈قتلوا أبناء ࡰلذين ءامنوا معه واستحيوا نساءهم࣌ وما كيد ࡲلكفرين إلا فے ضلل࣌', NULL, 469, 'local:warsh-text.json'),
  ('warsh-40-26', 'warsh', 40, 26, 'وَقَالَ فِرْعَوْنُ ذَرُونِےٓ أَقْتُلْ مُوسٜىٰ وَلْيَدْعُ رَبَّهُۥٓ إِنِّيَ أَخَافُ أَنْ يُّبَدِّلَ دِينَكُمْ وَأَنْ يُّظْهِرَ فِے ࡴ۬لَارْضِ ࡴ۬لْفَسَادَ࣌', 'وقال فرعون ذرونے أقتل موسى وليدع ربه إني أخاف أن يبدل دينكم وأن يظهر فے ࡴلارض ࡴلفساد࣌', NULL, 470, 'local:warsh-text.json'),
  ('warsh-40-27', 'warsh', 40, 27, 'وَقَالَ مُوسٜىٰٓ إِنِّے عُذْتُ بِرَبِّے وَرَبِّكُم مِّن كُلِّ مُتَكَبِّرࣲ لَّا يُومِنُ بِيَوْمِ ࡴ۬لْحِسَابِ࣌', 'وقال موسى إنے عذت بربے وربكم من كل متكبر لا يومن بيوم ࡴلحساب࣌', NULL, 470, 'local:warsh-text.json'),
  ('warsh-40-28', 'warsh', 40, 28, 'وَقَالَ رَجُلࣱ مُّومِنࣱ مِّنَ اٰلِ فِرْعَوْنَ يَكْتُمُ إِيمَٰنَهُۥٓ أَتَقْتُلُونَ رَجُلاً ࡰنْ يَّقُولَ رَبِّيَ ࡰ۬للَّهُ وَقَدْ جَآءَكُم بِالْبَيِّنَٰتِ مِن رَّبِّكُمْ وَإِنْ يَّكُ كَٰذِباࣰ فَعَلَيْهِ كَذِبُهُۥ وَإِنْ يَّكُ صَادِقاࣰ يُصِبْكُم بَعْضُ ࡲ۬لذِے يَعِدُكُمُۥٓ࣌ إِنَّ ࡰ۬للَّهَ لَا يَهْدِے مَنْ هُوَ مُسْرِفࣱ كَذَّابࣱ࣌', 'وقال رجل مومن من ال فرعون يكتم إيمنه أتقتلون رجلا ࡰن يقول ربي ࡰلله وقد جاءكم بالبينت من ربكم وإن يك كذبا فعليه كذبه وإن يك صادقا يصبكم بعض ࡲلذے يعدكم࣌ إن ࡰلله لا يهدے من هو مسرف كذاب࣌', NULL, 470, 'local:warsh-text.json'),
  ('warsh-40-29', 'warsh', 40, 29, 'يَٰقَوْمِ لَكُمُ ࡲ۬لْمُلْكُ ࡲ۬لْيَوْمَ ظَٰهِرِينَ فِے ࡴ۬لَارْضِ فَمَنْ يَّنصُرُنَا مِنۢ بَأْسِ ࡴ۬للَّهِ إِن جَآءَنَا࣌ قَالَ فِرْعَوْنُ مَآ أُرِيكُمُۥٓ إِلَّا مَآ أَرٜىٰ وَمَآ أَهْدِيكُمُۥٓ إِلَّا سَبِيلَ ࡰ۬لرَّشَادِ࣌', 'يقوم لكم ࡲلملك ࡲليوم ظهرين فے ࡴلارض فمن ينصرنا من بأس ࡴلله إن جاءنا࣌ قال فرعون ما أريكم إلا ما أرى وما أهديكم إلا سبيل ࡰلرشاد࣌', NULL, 470, 'local:warsh-text.json'),
  ('warsh-40-30', 'warsh', 40, 30, '۞ وَقَالَ ࡰ۬لذِےٓ ءَامَنَ يَٰقَوْمِ إِنِّيَ أَخَافُ عَلَيْكُم مِّثْلَ يَوْمِ ࡴ۬لَاحْزَابِ', 'وقال ࡰلذے ءامن يقوم إني أخاف عليكم مثل يوم ࡴلاحزاب', NULL, 470, 'local:warsh-text.json'),
  ('warsh-40-31', 'warsh', 40, 31, 'مِثْلَ دَأْبِ قَوْمِ نُوحࣲ وَعَادࣲ وَثَمُودَ وَالذِينَ مِنۢ بَعْدِهِمْ࣌ وَمَا ࡰ۬للَّهُ يُرِيدُ ظُلْماࣰ لِّلْعِبَادِ࣌', 'مثل دأب قوم نوح وعاد وثمود والذين من بعدهم࣌ وما ࡰلله يريد ظلما للعباد࣌', NULL, 470, 'local:warsh-text.json'),
  ('warsh-40-32', 'warsh', 40, 32, 'وَيَٰقَوْمِ إِنِّيَ أَخَافُ عَلَيْكُمْ يَوْمَ ࡰ۬لتَّنَادِۦ', 'ويقوم إني أخاف عليكم يوم ࡰلتناد', NULL, 470, 'local:warsh-text.json'),
  ('warsh-40-33', 'warsh', 40, 33, 'يَوْمَ تُوَلُّونَ مُدْبِرِينَ مَا لَكُم مِّنَ ࡰ۬للَّهِ مِنْ عَٰصِمࣲ࣌ وَمَنْ يُّضْلِلِ ࡴ۬للَّهُ فَمَا لَهُۥ مِنْ هَادࣲ࣌', 'يوم تولون مدبرين ما لكم من ࡰلله من عصم࣌ ومن يضلل ࡴلله فما له من هاد࣌', NULL, 470, 'local:warsh-text.json'),
  ('warsh-40-34', 'warsh', 40, 34, 'وَلَقَدْ جَآءَكُمْ يُوسُفُ مِن قَبْلُ بِالْبَيِّنَٰتِ فَمَا زِلْتُمْ فِے شَكࣲّ مِّمَّا جَآءَكُم بِهِۦ حَتَّىٰٓ إِذَا هَلَكَ قُلْتُمْ لَنْ يَّبْعَثَ ࡰ۬للَّهُ مِنۢ بَعْدِهِۦ رَسُولاࣰ࣌ كَذَٰلِكَ يُضِلُّ ࡲ۬للَّهُ مَنْ هُوَ مُسْرِفࣱ مُّرْتَابٌ࣌', 'ولقد جاءكم يوسف من قبل بالبينت فما زلتم فے شك مما جاءكم به حتى إذا هلك قلتم لن يبعث ࡰلله من بعده رسولا࣌ كذلك يضل ࡲلله من هو مسرف مرتاب࣌', NULL, 471, 'local:warsh-text.json'),
  ('warsh-40-35', 'warsh', 40, 35, 'ࡴ۬لذِينَ يُجَٰدِلُونَ فِےٓ ءَايَٰتِ ࡴ۬للَّهِ بِغَيْرِ سُلْطَٰنٍ ࡰتٜيٰهُمْ࣌ كَبُرَ مَقْتاً عِندَ ࡰ۬للَّهِ وَعِندَ ࡰ۬لذِينَ ءَامَنُواْ࣌ كَذَٰلِكَ يَطْبَعُ ࡲ۬للَّهُ عَلَىٰ كُلِّ قَلْبِ مُتَكَبِّرࣲ جَبّٜارࣲ࣌', 'ࡴلذين يجدلون فے ءايت ࡴلله بغير سلطن ࡰتيهم࣌ كبر مقتا عند ࡰلله وعند ࡰلذين ءامنوا࣌ كذلك يطبع ࡲلله على كل قلب متكبر جبار࣌', NULL, 471, 'local:warsh-text.json'),
  ('warsh-40-36', 'warsh', 40, 36, 'وَقَالَ فِرْعَوْنُ يَٰهَامَٰنُ ࡲٜبْنِ لِے صَرْحاࣰ لَّعَلِّيَ أَبْلُغُ ࡲ۬لَاسْبَٰبَ', 'وقال فرعون يهامن ࡲبن لے صرحا لعلي أبلغ ࡲلاسبب', NULL, 471, 'local:warsh-text.json'),
  ('warsh-40-37', 'warsh', 40, 37, 'أَسْبَٰبَ ࡰ۬لسَّمَٰوَٰتِ فَأَطَّلِعُ إِلَىٰٓ إِلَٰهِ مُوسٜىٰ وَإِنِّے لَأَظُنُّهُۥ كَٰذِباࣰ࣌ وَكَذَٰلِكَ زُيِّنَ لِفِرْعَوْنَ سُوٓءُ عَمَلِهِۦ وَصَدَّ عَنِ ࡴ۬لسَّبِيلِ࣌ وَمَا كَيْدُ فِرْعَوْنَ إِلَّا فِے تَبَابࣲ࣌', 'أسبب ࡰلسموت فأطلع إلى إله موسى وإنے لأظنه كذبا࣌ وكذلك زين لفرعون سوء عمله وصد عن ࡴلسبيل࣌ وما كيد فرعون إلا فے تباب࣌', NULL, 471, 'local:warsh-text.json'),
  ('warsh-40-38', 'warsh', 40, 38, 'وَقَالَ ࡰ۬لذِےٓ ءَامَنَ يَٰقَوْمِ ࡴٜتَّبِعُونِ أَهْدِكُمْ سَبِيلَ ࡰ۬لرَّشَادِ࣌', 'وقال ࡰلذے ءامن يقوم ࡴتبعون أهدكم سبيل ࡰلرشاد࣌', NULL, 471, 'local:warsh-text.json'),
  ('warsh-40-39', 'warsh', 40, 39, 'يَٰقَوْمِ إِنَّمَا هَٰذِهِ ࡴ۬لْحَيَوٰةُ ࡲ۬لدُّنْيٜا مَتَٰعࣱ࣌ وَإِنَّ ࡰ۬لَاخِرَةَ هِيَ دَارُ ࡲ۬لْقَرٜارِ࣌', 'يقوم إنما هذه ࡴلحيوة ࡲلدنيا متع࣌ وإن ࡰلاخرة هي دار ࡲلقرار࣌', NULL, 471, 'local:warsh-text.json'),
  ('warsh-40-40', 'warsh', 40, 40, 'مَنْ عَمِلَ سَيِّئَةࣰ فَلَا يُجْزٜىٰٓ إِلَّا مِثْلَهَا࣌ وَمَنْ عَمِلَ صَٰلِحاࣰ مِّن ذَكَرٍ ࡰوُ ࡳنثٜىٰ وَهُوَ مُومِنࣱ فَأُوْلَٰٓئِكَ يَدْخُلُونَ ࡰ۬لْجَنَّةَ يُرْزَقُونَ فِيهَا بِغَيْرِ حِسَابࣲ࣌', 'من عمل سيئة فلا يجزى إلا مثلها࣌ ومن عمل صلحا من ذكر ࡰو ࡳنثى وهو مومن فأولئك يدخلون ࡰلجنة يرزقون فيها بغير حساب࣌', NULL, 471, 'local:warsh-text.json'),
  ('warsh-40-41', 'warsh', 40, 41, '۞ وَيَٰقَوْمِ مَا لِيَ أَدْعُوكُمُۥٓ إِلَى ࡰ۬لنَّجَوٰةِ وَتَدْعُونَنِےٓ إِلَى ࡰ۬لنّٜارِ࣌', 'ويقوم ما لي أدعوكم إلى ࡰلنجوة وتدعوننے إلى ࡰلنار࣌', NULL, 472, 'local:warsh-text.json'),
  ('warsh-40-42', 'warsh', 40, 42, 'تَدْعُونَنِے لِأَكْفُرَ بِاللَّهِ وَأُشْرِكَ بِهِۦ مَا لَيْسَ لِے بِهِۦ عِلْمࣱ وَأَنَآ أَدْعُوكُمُۥٓ إِلَى ࡰ۬لْعَزِيزِ ࡴ۬لْغَفّٜـٰرِ࣌', 'تدعوننے لأكفر بالله وأشرك به ما ليس لے به علم وأنا أدعوكم إلى ࡰلعزيز ࡴلغفر࣌', NULL, 472, 'local:warsh-text.json'),
  ('warsh-40-43', 'warsh', 40, 43, 'لَا جَرَمَ أَنَّمَا تَدْعُونَنِےٓ إِلَيْهِ لَيْسَ لَهُۥ دَعْوَةࣱ فِے ࡴ۬لدُّنْيٜا وَلَا فِے ࡴ۬لَاخِرَةِ وَأَنَّ مَرَدَّنَآ إِلَى ࡰ۬للَّهِ وَأَنَّ ࡰ۬لْمُسْرِفِينَ هُمُۥٓ أَصْحَٰبُ ࡲ۬لنّٜارِ࣌', 'لا جرم أنما تدعوننے إليه ليس له دعوة فے ࡴلدنيا ولا فے ࡴلاخرة وأن مردنا إلى ࡰلله وأن ࡰلمسرفين هم أصحب ࡲلنار࣌', NULL, 472, 'local:warsh-text.json'),
  ('warsh-40-44', 'warsh', 40, 44, 'فَسَتَذْكُرُونَ مَآ أَقُولُ لَكُمْ࣌ وَأُفَوِّضُ أَمْرِيَ إِلَى ࡰ۬للَّهِ࣌ إِنَّ ࡰ۬للَّهَ بَصِيرُۢ بِالْعِبَادِ࣌', 'فستذكرون ما أقول لكم࣌ وأفوض أمري إلى ࡰلله࣌ إن ࡰلله بصير بالعباد࣌', NULL, 472, 'local:warsh-text.json'),
  ('warsh-40-45', 'warsh', 40, 45, 'فَوَقٜيٰهُ ࡲ۬للَّهُ سَيِّـَٔاتِ مَا مَكَرُواْ࣌ وَحَاقَ بِـَٔالِ فِرْعَوْنَ سُوٓءُ ࡲ۬لْعَذَابِ࣌', 'فوقيه ࡲلله سيات ما مكروا࣌ وحاق بال فرعون سوء ࡲلعذاب࣌', NULL, 472, 'local:warsh-text.json'),
  ('warsh-40-46', 'warsh', 40, 46, 'ࡴ۬لنَّارُ يُعْرَضُونَ عَلَيْهَا غُدُوّاࣰ وَعَشِيّاࣰ࣌ وَيَوْمَ تَقُومُ ࡲ۬لسَّاعَةُ أَدْخِلُوٓاْ ءَالَ فِرْعَوْنَ أَشَدَّ ࡰ۬لْعَذَابِ࣌', 'ࡴلنار يعرضون عليها غدوا وعشيا࣌ ويوم تقوم ࡲلساعة أدخلوا ءال فرعون أشد ࡰلعذاب࣌', NULL, 472, 'local:warsh-text.json'),
  ('warsh-40-47', 'warsh', 40, 47, 'وَإِذْ يَتَحَآجُّونَ فِے ࡴ۬لنّٜارِ فَيَقُولُ ࡲ۬لضُّعَفَٰٓؤُاْ لِلذِينَ ࡰٜسْتَكْبَرُوٓاْ إِنَّا كُنَّا لَكُمْ تَبَعاࣰ فَهَلَ ࡰنتُم مُّغْنُونَ عَنَّا نَصِيباࣰ مِّنَ ࡰ۬لنّٜارِ࣌', 'وإذ يتحاجون فے ࡴلنار فيقول ࡲلضعفؤا للذين ࡰستكبروا إنا كنا لكم تبعا فهل ࡰنتم مغنون عنا نصيبا من ࡰلنار࣌', NULL, 472, 'local:warsh-text.json'),
  ('warsh-40-48', 'warsh', 40, 48, 'قَالَ ࡰ۬لذِينَ ࡰٜسْتَكْبَرُوٓاْ إِنَّا كُلࣱّ فِيهَآ إِنَّ ࡰ۬للَّهَ قَدْ حَكَمَ بَيْنَ ࡰ۬لْعِبَادِ࣌', 'قال ࡰلذين ࡰستكبروا إنا كل فيها إن ࡰلله قد حكم بين ࡰلعباد࣌', NULL, 472, 'local:warsh-text.json'),
  ('warsh-40-49', 'warsh', 40, 49, 'وَقَالَ ࡰ۬لذِينَ فِے ࡴ۬لنّٜارِ لِخَزَنَةِ جَهَنَّمَ ࡸَدْعُواْ رَبَّكُمْ يُخَفِّفْ عَنَّا يَوْماࣰ مِّنَ ࡰ۬لْعَذَابِ࣌', 'وقال ࡰلذين فے ࡴلنار لخزنة جهنم ࡸدعوا ربكم يخفف عنا يوما من ࡰلعذاب࣌', NULL, 472, 'local:warsh-text.json'),
  ('warsh-40-50', 'warsh', 40, 50, 'قَالُوٓاْ أَوَلَمْ تَكُ تَاتِيكُمْ رُسُلُكُم بِالْبَيِّنَٰتِ قَالُواْ بَلٜىٰ قَالُواْ فَادْعُواْ࣌ وَمَا دُعَٰٓؤُاْ ࡲ۬لْكٜـٰفِرِينَ إِلَّا فِے ضَلَٰلٍ࣌', 'قالوا أولم تك تاتيكم رسلكم بالبينت قالوا بلى قالوا فادعوا࣌ وما دعؤا ࡲلكفرين إلا فے ضلل࣌', NULL, 473, 'local:warsh-text.json'),
  ('warsh-40-51', 'warsh', 40, 51, 'ࡴنَّا لَنَنصُرُ رُسُلَنَا وَالذِينَ ءَامَنُواْ فِے ࡴ۬لْحَيَوٰةِ ࡴ۬لدُّنْيٜا وَيَوْمَ يَقُومُ ࡲ۬لَاشْهَٰدُ', 'ࡴنا لننصر رسلنا والذين ءامنوا فے ࡴلحيوة ࡴلدنيا ويوم يقوم ࡲلاشهد', NULL, 473, 'local:warsh-text.json'),
  ('warsh-40-52', 'warsh', 40, 52, 'يَوْمَ لَا يَنفَعُ ࡲ۬لظَّٰلِمِينَ مَعْذِرَتُهُمْ وَلَهُمُ ࡲ۬للَّعْنَةُ وَلَهُمْ سُوٓءُ ࡲ۬لدّٜارِ࣌', 'يوم لا ينفع ࡲلظلمين معذرتهم ولهم ࡲللعنة ولهم سوء ࡲلدار࣌', NULL, 473, 'local:warsh-text.json'),
  ('warsh-40-53', 'warsh', 40, 53, '۞ وَلَقَدَ اٰتَيْنَا مُوسَى ࡰ۬لْهُدٜىٰ وَأَوْرَثْنَا بَنِےٓ إِسْرَآءِيلَ ࡰ۬لْكِتَٰبَ هُدىࣰ وَذِكْرٜىٰ لِأُوْلِے ࡴ۬لَالْبَٰبِ࣌', 'ولقد اتينا موسى ࡰلهدى وأورثنا بنے إسراءيل ࡰلكتب هدى وذكرى لأولے ࡴلالبب࣌', NULL, 473, 'local:warsh-text.json'),
  ('warsh-40-54', 'warsh', 40, 54, 'فَاصْبِرِ ࡴنَّ وَعْدَ ࡰ۬للَّهِ حَقࣱّ࣌ وَاسْتَغْفِرْ لِذَنۢبِكَ وَسَبِّحْ بِحَمْدِ رَبِّكَ بِالْعَشِيِّ وَالِابْكٜـٰرِ࣌', 'فاصبر ࡴن وعد ࡰلله حق࣌ واستغفر لذنبك وسبح بحمد ربك بالعشي والابكر࣌', NULL, 473, 'local:warsh-text.json'),
  ('warsh-40-55', 'warsh', 40, 55, 'إِنَّ ࡰ۬لذِينَ يُجَٰدِلُونَ فِےٓ ءَايَٰتِ ࡴ۬للَّهِ بِغَيْرِ سُلْطَٰنٍ ࡰتٜيٰهُمُۥٓ إِن فِے صُدُورِهِمُۥٓ إِلَّا كِبْرࣱ مَّا هُم بِبَٰلِغِيهِ࣌ فَاسْتَعِذْ بِاللَّهِ࣌ إِنَّهُۥ هُوَ ࡰ۬لسَّمِيعُ ࡲ۬لْبَصِيرُ࣌', 'إن ࡰلذين يجدلون فے ءايت ࡴلله بغير سلطن ࡰتيهم إن فے صدورهم إلا كبر ما هم ببلغيه࣌ فاستعذ بالله࣌ إنه هو ࡰلسميع ࡲلبصير࣌', NULL, 473, 'local:warsh-text.json'),
  ('warsh-40-56', 'warsh', 40, 56, 'لَخَلْقُ ࡲ۬لسَّمَٰوَٰتِ وَالَارْضِ أَكْبَرُ مِنْ خَلْقِ ࡴ۬لنَّاسِ࣌ وَلَٰكِنَّ أَكْثَرَ ࡰ۬لنَّاسِ لَا يَعْلَمُونَ࣌', 'لخلق ࡲلسموت والارض أكبر من خلق ࡴلناس࣌ ولكن أكثر ࡰلناس لا يعلمون࣌', NULL, 473, 'local:warsh-text.json'),
  ('warsh-40-57', 'warsh', 40, 57, 'وَمَا يَسْتَوِے ࡴ۬لَاعْمٜىٰ وَالْبَصِيرُ', 'وما يستوے ࡴلاعمى والبصير', NULL, 473, 'local:warsh-text.json'),
  ('warsh-40-58', 'warsh', 40, 58, 'وَالذِينَ ءَامَنُواْ وَعَمِلُواْ ࡲ۬لصَّٰلِحَٰتِ وَلَا ࡰ۬لْمُسِےٓءُ࣌ قَلِيلاࣰ مَّا يَتَذَكَّرُونَ࣌', 'والذين ءامنوا وعملوا ࡲلصلحت ولا ࡰلمسےء࣌ قليلا ما يتذكرون࣌', NULL, 473, 'local:warsh-text.json'),
  ('warsh-40-59', 'warsh', 40, 59, 'إِنَّ ࡰ۬لسَّاعَةَ لَأٓتِيَةࣱ لَّا رَيْبَ فِيهَا࣌ وَلَٰكِنَّ أَكْثَرَ ࡰ۬لنَّاسِ لَا يُومِنُونَ࣌', 'إن ࡰلساعة لأتية لا ريب فيها࣌ ولكن أكثر ࡰلناس لا يومنون࣌', NULL, 474, 'local:warsh-text.json'),
  ('warsh-40-60', 'warsh', 40, 60, 'وَقَالَ رَبُّكُمُ ࡲ࢈دْعُونِےٓ أَسْتَجِبْ لَكُمُۥٓ࣌ إِنَّ ࡰ۬لذِينَ يَسْتَكْبِرُونَ عَنْ عِبَادَتِے سَيَدْخُلُونَ جَهَنَّمَ دَاخِرِينَ࣌', 'وقال ربكم ࡲ࢈دعونے أستجب لكم࣌ إن ࡰلذين يستكبرون عن عبادتے سيدخلون جهنم داخرين࣌', NULL, 474, 'local:warsh-text.json'),
  ('warsh-40-61', 'warsh', 40, 61, 'ࡰ۬للَّهُ ࡲ۬لذِے جَعَلَ لَكُمُ ࡲ۬ليْلَ لِتَسْكُنُواْ فِيهِ وَالنَّهَارَ مُبْصِراً࣌ ࡴنَّ ࡰ۬للَّهَ لَذُو فَضْلٍ عَلَى ࡰ۬لنَّاسِ࣌ وَلَٰكِنَّ أَكْثَرَ ࡰ۬لنَّاسِ لَا يَشْكُرُونَ࣌', 'ࡰلله ࡲلذے جعل لكم ࡲليل لتسكنوا فيه والنهار مبصرا࣌ ࡴن ࡰلله لذو فضل على ࡰلناس࣌ ولكن أكثر ࡰلناس لا يشكرون࣌', NULL, 474, 'local:warsh-text.json'),
  ('warsh-40-62', 'warsh', 40, 62, 'ذَٰلِكُمُ ࡲ۬للَّهُ رَبُّكُمْ࣌ خَٰلِقُ كُلِّ شَےْءࣲ࣌ لَّآ إِلَٰهَ إِلَّا هُوَ࣌ فَأَنّٜىٰ تُوفَكُونَ࣌', 'ذلكم ࡲلله ربكم࣌ خلق كل شےء࣌ لا إله إلا هو࣌ فأنى توفكون࣌', NULL, 474, 'local:warsh-text.json'),
  ('warsh-40-63', 'warsh', 40, 63, 'كَذَٰلِكَ يُوفَكُ ࡲ۬لذِينَ كَانُواْ بِـَٔايَٰتِ ࡴ۬للَّهِ يَجْحَدُونَ࣌', 'كذلك يوفك ࡲلذين كانوا بايت ࡴلله يجحدون࣌', NULL, 474, 'local:warsh-text.json'),
  ('warsh-40-64', 'warsh', 40, 64, 'ࡰ۬للَّهُ ࡲ۬لذِے جَعَلَ لَكُمُ ࡲ۬لَارْضَ قَرَاراࣰ وَالسَّمَآءَ بِنَآءࣰ وَصَوَّرَكُمْ فَأَحْسَنَ صُوَرَكُمْ وَرَزَقَكُم مِّنَ ࡰ۬لطَّيِّبَٰتِ࣌ ذَٰلِكُمُ ࡲ۬للَّهُ رَبُّكُمْ࣌ فَتَبَٰرَكَ ࡰ۬للَّهُ رَبُّ ࡲ۬لْعَٰلَمِينَ࣌', 'ࡰلله ࡲلذے جعل لكم ࡲلارض قرارا والسماء بناء وصوركم فأحسن صوركم ورزقكم من ࡰلطيبت࣌ ذلكم ࡲلله ربكم࣌ فتبرك ࡰلله رب ࡲلعلمين࣌', NULL, 474, 'local:warsh-text.json'),
  ('warsh-40-65', 'warsh', 40, 65, 'هُوَ ࡰ۬لْحَيُّ࣌ لَآ إِلَٰهَ إِلَّا هُوَ࣌ فَادْعُوهُ مُخْلِصِينَ لَهُ ࡲ۬لدِّينَ࣌ ࡰ۬لْحَمْدُ لِلهِ رَبِّ ࡴ۬لْعَٰلَمِينَ࣌', 'هو ࡰلحي࣌ لا إله إلا هو࣌ فادعوه مخلصين له ࡲلدين࣌ ࡰلحمد لله رب ࡴلعلمين࣌', NULL, 474, 'local:warsh-text.json'),
  ('warsh-40-66', 'warsh', 40, 66, '۞ قُلِ ࡴنِّے نُهِيتُ أَنَ ࡰعْبُدَ ࡰ۬لذِينَ تَدْعُونَ مِن دُونِ ࡴ۬للَّهِ لَمَّا جَآءَنِيَ ࡰ۬لْبَيِّنَٰتُ مِن رَّبِّے وَأُمِرْتُ أَنُ ࡳسْلِمَ لِرَبِّ ࡴ۬لْعَٰلَمِينَ࣌', 'قل ࡴنے نهيت أن ࡰعبد ࡰلذين تدعون من دون ࡴلله لما جاءني ࡰلبينت من ربے وأمرت أن ࡳسلم لرب ࡴلعلمين࣌', NULL, 474, 'local:warsh-text.json'),
  ('warsh-40-67', 'warsh', 40, 67, 'هُوَ ࡰ۬لذِے خَلَقَكُم مِّن تُرَابࣲ ثُمَّ مِن نُّطْفَةࣲ ثُمَّ مِنْ عَلَقَةࣲ ثُمَّ يُخْرِجُكُمْ طِفْلاࣰ ثُمَّ لِتَبْلُغُوٓاْ أَشُدَّكُمْ ثُمَّ لِتَكُونُواْ شُيُوخاࣰ࣌ وَمِنكُم مَّنْ يُّتَوَفّٜىٰ مِن قَبْلُ وَلِتَبْلُغُوٓاْ أَجَلاࣰ مُّسَمّىࣰ وَلَعَلَّكُمْ تَعْقِلُونَ࣌', 'هو ࡰلذے خلقكم من تراب ثم من نطفة ثم من علقة ثم يخرجكم طفلا ثم لتبلغوا أشدكم ثم لتكونوا شيوخا࣌ ومنكم من يتوفى من قبل ولتبلغوا أجلا مسمى ولعلكم تعقلون࣌', NULL, 475, 'local:warsh-text.json'),
  ('warsh-40-68', 'warsh', 40, 68, 'هُوَ ࡰ۬لذِے يُحْيِۦ وَيُمِيتُ࣌ فَإِذَا قَضٜىٰٓ أَمْراࣰ فَإِنَّمَا يَقُولُ لَهُۥ كُن࣌ فَيَكُونُ࣌', 'هو ࡰلذے يحي ويميت࣌ فإذا قضى أمرا فإنما يقول له كن࣌ فيكون࣌', NULL, 475, 'local:warsh-text.json'),
  ('warsh-40-69', 'warsh', 40, 69, 'أَلَمْ تَرَ إِلَى ࡰ۬لذِينَ يُجَٰدِلُونَ فِےٓ ءَايَٰتِ ࡴ۬للَّهِ أَنّٜىٰ يُصْرَفُونَ࣌', 'ألم تر إلى ࡰلذين يجدلون فے ءايت ࡴلله أنى يصرفون࣌', NULL, 475, 'local:warsh-text.json'),
  ('warsh-40-70', 'warsh', 40, 70, 'ࡰ۬لذِينَ كَذَّبُواْ بِالْكِتَٰبِ وَبِمَآ أَرْسَلْنَا بِهِۦ رُسُلَنَا فَسَوْفَ يَعْلَمُونَ', 'ࡰلذين كذبوا بالكتب وبما أرسلنا به رسلنا فسوف يعلمون', NULL, 475, 'local:warsh-text.json'),
  ('warsh-40-71', 'warsh', 40, 71, 'إِذِ ࡴ۬لَاغْلَٰلُ فِےٓ أَعْنَٰقِهِمْ وَالسَّلَٰسِلُ࣌ يُسْحَبُونَ', 'إذ ࡴلاغلل فے أعنقهم والسلسل࣌ يسحبون', NULL, 475, 'local:warsh-text.json'),
  ('warsh-40-72', 'warsh', 40, 72, 'فِے ࡴ۬لْحَمِيمِ ثُمَّ فِے ࡴ۬لنّٜارِ يُسْجَرُونَ࣌', 'فے ࡴلحميم ثم فے ࡴلنار يسجرون࣌', NULL, 475, 'local:warsh-text.json'),
  ('warsh-40-73', 'warsh', 40, 73, 'ثُمَّ قِيلَ لَهُمُۥٓ أَيْنَ مَا كُنتُمْ تُشْرِكُونَ مِن دُونِ ࡴ۬للَّهِ࣌ قَالُواْ ضَلُّواْ عَنَّا بَل لَّمْ نَكُن نَّدْعُواْ مِن قَبْلُ شَيْـٔاࣰ࣌ كَذَٰلِكَ يُضِلُّ ࡲ۬للَّهُ ࡲ۬لْكٜـٰفِرِينَ࣌', 'ثم قيل لهم أين ما كنتم تشركون من دون ࡴلله࣌ قالوا ضلوا عنا بل لم نكن ندعوا من قبل شيا࣌ كذلك يضل ࡲلله ࡲلكفرين࣌', NULL, 475, 'local:warsh-text.json'),
  ('warsh-40-74', 'warsh', 40, 74, 'ذَٰلِكُم بِمَا كُنتُمْ تَفْرَحُونَ فِے ࡴ۬لَارْضِ بِغَيْرِ ࡴ۬لْحَقِّ وَبِمَا كُنتُمْ تَمْرَحُونَ࣌', 'ذلكم بما كنتم تفرحون فے ࡴلارض بغير ࡴلحق وبما كنتم تمرحون࣌', NULL, 475, 'local:warsh-text.json'),
  ('warsh-40-75', 'warsh', 40, 75, 'ࡸَدْخُلُوٓاْ أَبْوَٰبَ جَهَنَّمَ خَٰلِدِينَ فِيهَا࣌ فَبِيسَ مَثْوَى ࡰ۬لْمُتَكَبِّرِينَ࣌', 'ࡸدخلوا أبوب جهنم خلدين فيها࣌ فبيس مثوى ࡰلمتكبرين࣌', NULL, 475, 'local:warsh-text.json'),
  ('warsh-40-76', 'warsh', 40, 76, 'فَاصْبِرِ ࡴنَّ وَعْدَ ࡰ۬للَّهِ حَقࣱّ࣌ فَإِمَّا نُرِيَنَّكَ بَعْضَ ࡰ۬لذِے نَعِدُهُمُۥٓ أَوْ نَتَوَفَّيَنَّكَ فَإِلَيْنَا يُرْجَعُونَ࣌', 'فاصبر ࡴن وعد ࡰلله حق࣌ فإما نرينك بعض ࡰلذے نعدهم أو نتوفينك فإلينا يرجعون࣌', NULL, 475, 'local:warsh-text.json'),
  ('warsh-40-77', 'warsh', 40, 77, 'وَلَقَدَ ࡰرْسَلْنَا رُسُلاࣰ مِّن قَبْلِكَ مِنْهُم مَّن قَصَصْنَا عَلَيْكَ وَمِنْهُم مَّن لَّمْ نَقْصُصْ عَلَيْكَ࣌ وَمَا كَانَ لِرَسُولٍ ࡰنْ يَّاتِيَ بِـَٔايَةٍ ࡴلَّا بِإِذْنِ ࡴ۬للَّهِ࣌ فَإِذَا جَآءَ امْرُ ࡲ۬للَّهِ قُضِيَ بِالْحَقِّ وَخَسِرَ هُنَالِكَ ࡰ۬لْمُبْطِلُونَ࣌', 'ولقد ࡰرسلنا رسلا من قبلك منهم من قصصنا عليك ومنهم من لم نقصص عليك࣌ وما كان لرسول ࡰن ياتي باية ࡴلا بإذن ࡴلله࣌ فإذا جاء امر ࡲلله قضي بالحق وخسر هنالك ࡰلمبطلون࣌', NULL, 476, 'local:warsh-text.json'),
  ('warsh-40-78', 'warsh', 40, 78, '۞ ࡰ۬للَّهُ ࡲ۬لذِے جَعَلَ لَكُمُ ࡲ۬لَانْعَٰمَ لِتَرْكَبُواْ مِنْهَا وَمِنْهَا تَاكُلُونَ࣌', 'ࡰلله ࡲلذے جعل لكم ࡲلانعم لتركبوا منها ومنها تاكلون࣌', NULL, 476, 'local:warsh-text.json'),
  ('warsh-40-79', 'warsh', 40, 79, 'وَلَكُمْ فِيهَا مَنَٰفِعُ࣌ وَلِتَبْلُغُواْ عَلَيْهَا حَاجَةࣰ فِے صُدُورِكُمْ࣌ وَعَلَيْهَا وَعَلَى ࡰ۬لْفُلْكِ تُحْمَلُونَ࣌', 'ولكم فيها منفع࣌ ولتبلغوا عليها حاجة فے صدوركم࣌ وعليها وعلى ࡰلفلك تحملون࣌', NULL, 476, 'local:warsh-text.json'),
  ('warsh-40-80', 'warsh', 40, 80, 'وَيُرِيكُمُۥٓ ءَايَٰتِهِۦ࣌ فَأَيَّ ءَايَٰتِ ࡴ۬للَّهِ تُنكِرُونَ࣌', 'ويريكم ءايته࣌ فأي ءايت ࡴلله تنكرون࣌', NULL, 476, 'local:warsh-text.json'),
  ('warsh-40-81', 'warsh', 40, 81, 'أَفَلَمْ يَسِيرُواْ فِے ࡴ۬لَارْضِ فَيَنظُرُواْ كَيْفَ كَانَ عَٰقِبَةُ ࡲ۬لذِينَ مِن قَبْلِهِمْ࣌ كَانُوٓاْ أَكْثَرَ مِنْهُمْ وَأَشَدَّ قُوَّةࣰ وَءَاثَاراࣰ فِے ࡴ۬لَارْضِ فَمَآ أَغْنٜىٰ عَنْهُم مَّا كَانُواْ يَكْسِبُونَ࣌', 'أفلم يسيروا فے ࡴلارض فينظروا كيف كان عقبة ࡲلذين من قبلهم࣌ كانوا أكثر منهم وأشد قوة وءاثارا فے ࡴلارض فما أغنى عنهم ما كانوا يكسبون࣌', NULL, 476, 'local:warsh-text.json'),
  ('warsh-40-82', 'warsh', 40, 82, 'فَلَمَّا جَآءَتْهُمْ رُسُلُهُم بِالْبَيِّنَٰتِ فَرِحُواْ بِمَا عِندَهُم مِّنَ ࡰ۬لْعِلْمِ࣌ وَحَاقَ بِهِم مَّا كَانُواْ بِهِۦ يَسْتَهْزِءُونَ࣌', 'فلما جاءتهم رسلهم بالبينت فرحوا بما عندهم من ࡰلعلم࣌ وحاق بهم ما كانوا به يستهزءون࣌', NULL, 476, 'local:warsh-text.json'),
  ('warsh-40-83', 'warsh', 40, 83, 'فَلَمَّا رَأَوْاْ بَأْسَنَا قَالُوٓاْ ءَامَنَّا بِاللَّهِ وَحْدَهُۥ وَكَفَرْنَا بِمَا كُنَّا بِهِۦ مُشْرِكِينَ࣌', 'فلما رأوا بأسنا قالوا ءامنا بالله وحده وكفرنا بما كنا به مشركين࣌', NULL, 476, 'local:warsh-text.json'),
  ('warsh-40-84', 'warsh', 40, 84, 'فَلَمْ يَكُ يَنفَعُهُمُۥٓ إِيمَٰنُهُمْ لَمَّا رَأَوْاْ بَأْسَنَا࣌ سُنَّتَ ࡰ۬للَّهِ ࡴ۬لتِے قَدْ خَلَتْ فِے عِبَادِهِۦ࣌ وَخَسِرَ هُنَالِكَ ࡰ۬لْكَٰفِرُونَ࣌', 'فلم يك ينفعهم إيمنهم لما رأوا بأسنا࣌ سنت ࡰلله ࡴلتے قد خلت فے عباده࣌ وخسر هنالك ࡰلكفرون࣌', NULL, 476, 'local:warsh-text.json'),
  ('warsh-41-1', 'warsh', 41, 1, 'حٜمِٓ࣌ تَنزِيلࣱ مِّنَ ࡰ۬لرَّحْمَٰنِ ࡴ۬لرَّحِيمِ', 'حم࣌ تنزيل من ࡰلرحمن ࡴلرحيم', NULL, 477, 'local:warsh-text.json'),
  ('warsh-41-2', 'warsh', 41, 2, 'كِتَٰبࣱ فُصِّلَتَ اٰيَٰتُهُۥ قُرْءَاناً عَرَبِيّاࣰ لِّقَوْمࣲ يَعْلَمُونَ', 'كتب فصلت ايته قرءانا عربيا لقوم يعلمون', NULL, 477, 'local:warsh-text.json'),
  ('warsh-41-3', 'warsh', 41, 3, 'بَشِيراࣰ وَنَذِيراࣰ࣌ فَأَعْرَضَ أَكْثَرُهُمْ فَهُمْ لَا يَسْمَعُونَ࣌', 'بشيرا ونذيرا࣌ فأعرض أكثرهم فهم لا يسمعون࣌', NULL, 477, 'local:warsh-text.json'),
  ('warsh-41-4', 'warsh', 41, 4, 'وَقَالُواْ قُلُوبُنَا فِےٓ أَكِنَّةࣲ مِّمَّا تَدْعُونَآ إِلَيْهِ وَفِےٓ ءَاذَانِنَا وَقْرࣱ وَمِنۢ بَيْنِنَا وَبَيْنِكَ حِجَابࣱ فَاعْمَلِ ࡴنَّنَا عَٰمِلُونَ࣌', 'وقالوا قلوبنا فے أكنة مما تدعونا إليه وفے ءاذاننا وقر ومن بيننا وبينك حجاب فاعمل ࡴننا عملون࣌', NULL, 477, 'local:warsh-text.json'),
  ('warsh-41-5', 'warsh', 41, 5, 'قُلِ ࡴنَّمَآ أَنَا بَشَرࣱ مِّثْلُكُمْ يُوحٜىٰٓ إِلَيَّ أَنَّمَآ إِلَٰهُكُمُۥٓ إِلَٰهࣱ وَٰحِدࣱ فَاسْتَقِيمُوٓاْ إِلَيْهِ وَاسْتَغْفِرُوهُ࣌ وَوَيْلࣱ لِّلْمُشْرِكِينَ', 'قل ࡴنما أنا بشر مثلكم يوحى إلي أنما إلهكم إله وحد فاستقيموا إليه واستغفروه࣌ وويل للمشركين', NULL, 477, 'local:warsh-text.json'),
  ('warsh-41-6', 'warsh', 41, 6, 'ࡰ۬لذِينَ لَا يُوتُونَ ࡰ۬لزَّكَوٰةَ وَهُم بِالَاخِرَةِ هُمْ كَٰفِرُونَ࣌', 'ࡰلذين لا يوتون ࡰلزكوة وهم بالاخرة هم كفرون࣌', NULL, 477, 'local:warsh-text.json'),
  ('warsh-41-7', 'warsh', 41, 7, 'إِنَّ ࡰ۬لذِينَ ءَامَنُواْ وَعَمِلُواْ ࡲ۬لصَّٰلِحَٰتِ لَهُمُۥٓ أَجْرٌ غَيْرُ مَمْنُونࣲ࣌', 'إن ࡰلذين ءامنوا وعملوا ࡲلصلحت لهم أجر غير ممنون࣌', NULL, 477, 'local:warsh-text.json'),
  ('warsh-41-8', 'warsh', 41, 8, '۞ قُلَ ࡰئِنَّكُمْ لَتَكْفُرُونَ بِالذِے خَلَقَ ࡰ۬لَارْضَ فِے يَوْمَيْنِ وَتَجْعَلُونَ لَهُۥٓ أَندَاداࣰ࣌ ذَٰلِكَ رَبُّ ࡲ۬لْعَٰلَمِينَ࣌', 'قل ࡰئنكم لتكفرون بالذے خلق ࡰلارض فے يومين وتجعلون له أندادا࣌ ذلك رب ࡲلعلمين࣌', NULL, 477, 'local:warsh-text.json'),
  ('warsh-41-9', 'warsh', 41, 9, 'وَجَعَلَ فِيهَا رَوَٰسِيَ مِن فَوْقِهَا وَبَٰرَكَ فِيهَا وَقَدَّرَ فِيهَآ أَقْوَٰتَهَا فِےٓ أَرْبَعَةِ أَيَّامࣲ سَوَآءࣰ لِّلسَّآئِلِينَ࣌', 'وجعل فيها روسي من فوقها وبرك فيها وقدر فيها أقوتها فے أربعة أيام سواء للسائلين࣌', NULL, 477, 'local:warsh-text.json'),
  ('warsh-41-10', 'warsh', 41, 10, 'ثُمَّ ࡰٜسْتَوٜىٰٓ إِلَى ࡰ۬لسَّمَآءِ وَهِيَ دُخَانࣱ فَقَالَ لَهَا وَلِلَارْضِ ࡴٜيتِيَا طَوْعاً ࡰوْ كَرْهاࣰ࣌ قَالَتَآ أَتَيْنَا طَآئِعِينَ࣌', 'ثم ࡰستوى إلى ࡰلسماء وهي دخان فقال لها وللارض ࡴيتيا طوعا ࡰو كرها࣌ قالتا أتينا طائعين࣌', NULL, 477, 'local:warsh-text.json'),
  ('warsh-41-11', 'warsh', 41, 11, 'فَقَضٜيٰهُنَّ سَبْعَ سَمَٰوَاتࣲ فِے يَوْمَيْنِ وَأَوْحٜىٰ فِے كُلِّ سَمَآءٍ ࡰمْرَهَا࣌ وَزَيَّنَّا ࡰ۬لسَّمَآءَ ࡰ۬لدُّنْيٜا بِمَصَٰبِيحَ࣌ وَحِفْظاࣰ࣌ ذَٰلِكَ تَقْدِيرُ ࡲ۬لْعَزِيزِ ࡴ۬لْعَلِيمِ࣌', 'فقضيهن سبع سموات فے يومين وأوحى فے كل سماء ࡰمرها࣌ وزينا ࡰلسماء ࡰلدنيا بمصبيح࣌ وحفظا࣌ ذلك تقدير ࡲلعزيز ࡴلعليم࣌', NULL, 478, 'local:warsh-text.json'),
  ('warsh-41-12', 'warsh', 41, 12, 'فَإِنَ ࡰعْرَضُواْ فَقُلَ ࡰنذَرْتُكُمْ صَٰعِقَةࣰ مِّثْلَ صَٰعِقَةِ عَادࣲ وَثَمُودَ', 'فإن ࡰعرضوا فقل ࡰنذرتكم صعقة مثل صعقة عاد وثمود', NULL, 478, 'local:warsh-text.json'),
  ('warsh-41-13', 'warsh', 41, 13, 'إِذْ جَآءَتْهُمُ ࡲ۬لرُّسُلُ مِنۢ بَيْنِ أَيْدِيهِمْ وَمِنْ خَلْفِهِمُۥٓ أَلَّا تَعْبُدُوٓاْ إِلَّا ࡰ۬للَّهَ࣌ قَالُواْ لَوْ شَآءَ رَبُّنَا لَأَنزَلَ مَلَٰٓئِكَةࣰ فَإِنَّا بِمَآ أُرْسِلْتُم بِهِۦ كَٰفِرُونَ࣌', 'إذ جاءتهم ࡲلرسل من بين أيديهم ومن خلفهم ألا تعبدوا إلا ࡰلله࣌ قالوا لو شاء ربنا لأنزل ملئكة فإنا بما أرسلتم به كفرون࣌', NULL, 478, 'local:warsh-text.json'),
  ('warsh-41-14', 'warsh', 41, 14, 'فَأَمَّا عَادࣱ فَاسْتَكْبَرُواْ فِے ࡴ۬لَارْضِ بِغَيْرِ ࡴ۬لْحَقِّ وَقَالُواْ مَنَ ࡰشَدُّ مِنَّا قُوَّةً࣌ ࡰوَلَمْ يَرَوَاْ ࡰنَّ ࡰ۬للَّهَ ࡰ۬لذِے خَلَقَهُمْ هُوَ أَشَدُّ مِنْهُمْ قُوَّةࣰ࣌ وَكَانُواْ بِـَٔايَٰتِنَا يَجْحَدُونَ࣌', 'فأما عاد فاستكبروا فے ࡴلارض بغير ࡴلحق وقالوا من ࡰشد منا قوة࣌ ࡰولم يروا ࡰن ࡰلله ࡰلذے خلقهم هو أشد منهم قوة࣌ وكانوا بايتنا يجحدون࣌', NULL, 478, 'local:warsh-text.json'),
  ('warsh-41-15', 'warsh', 41, 15, 'فَأَرْسَلْنَا عَلَيْهِمْ رِيحاࣰ صَرْصَراࣰ فِےٓ أَيَّامࣲ نَّحْسَاتࣲ لِّنُذِيقَهُمْ عَذَابَ ࡰ۬لْخِزْيِ فِے ࡴ۬لْحَيَوٰةِ ࡴ۬لدُّنْيٜا࣌ وَلَعَذَابُ ࡲ۬لَاخِرَةِ أَخْزٜىٰ وَهُمْ لَا يُنصَرُونَ࣌', 'فأرسلنا عليهم ريحا صرصرا فے أيام نحسات لنذيقهم عذاب ࡰلخزي فے ࡴلحيوة ࡴلدنيا࣌ ولعذاب ࡲلاخرة أخزى وهم لا ينصرون࣌', NULL, 478, 'local:warsh-text.json'),
  ('warsh-41-16', 'warsh', 41, 16, '۞ وَأَمَّا ثَمُودُ فَهَدَيْنَٰهُمْ فَاسْتَحَبُّواْ ࡲ۬لْعَمٜىٰ عَلَى ࡰ۬لْهُدٜىٰ فَأَخَذَتْهُمْ صَٰعِقَةُ ࡲ۬لْعَذَابِ ࡴ۬لْهُونِ بِمَا كَانُواْ يَكْسِبُونَ࣌', 'وأما ثمود فهدينهم فاستحبوا ࡲلعمى على ࡰلهدى فأخذتهم صعقة ࡲلعذاب ࡴلهون بما كانوا يكسبون࣌', NULL, 478, 'local:warsh-text.json'),
  ('warsh-41-17', 'warsh', 41, 17, 'وَنَجَّيْنَا ࡰ۬لذِينَ ءَامَنُواْ وَكَانُواْ يَتَّقُونَ࣌', 'ونجينا ࡰلذين ءامنوا وكانوا يتقون࣌', NULL, 478, 'local:warsh-text.json'),
  ('warsh-41-18', 'warsh', 41, 18, 'وَيَوْمَ نَحْشُرُ أَعْدَآءَ ࡰ۬للَّهِ إِلَى ࡰ۬لنّٜارِ فَهُمْ يُوزَعُونَ࣌', 'ويوم نحشر أعداء ࡰلله إلى ࡰلنار فهم يوزعون࣌', NULL, 478, 'local:warsh-text.json'),
  ('warsh-41-19', 'warsh', 41, 19, 'حَتَّىٰٓ إِذَا مَا جَآءُوهَا شَهِدَ عَلَيْهِمْ سَمْعُهُمْ وَأَبْصَٰرُهُمْ وَجُلُودُهُم بِمَا كَانُواْ يَعْمَلُونَ࣌', 'حتى إذا ما جاءوها شهد عليهم سمعهم وأبصرهم وجلودهم بما كانوا يعملون࣌', NULL, 478, 'local:warsh-text.json'),
  ('warsh-41-20', 'warsh', 41, 20, 'وَقَالُواْ لِجُلُودِهِمْ لِمَ شَهِدتُّمْ عَلَيْنَا࣌ قَالُوٓاْ أَنطَقَنَا ࡰ۬للَّهُ ࡲ۬لذِےٓ أَنطَقَ كُلَّ شَےْءࣲ࣌ وَهُوَ خَلَقَكُمُۥٓ أَوَّلَ مَرَّةࣲ وَإِلَيْهِ تُرْجَعُونَ࣌', 'وقالوا لجلودهم لم شهدتم علينا࣌ قالوا أنطقنا ࡰلله ࡲلذے أنطق كل شےء࣌ وهو خلقكم أول مرة وإليه ترجعون࣌', NULL, 479, 'local:warsh-text.json'),
  ('warsh-41-21', 'warsh', 41, 21, 'وَمَا كُنتُمْ تَسْتَتِرُونَ أَنْ يَّشْهَدَ عَلَيْكُمْ سَمْعُكُمْ وَلَآ أَبْصَٰرُكُمْ وَلَا جُلُودُكُمْ࣌ وَلَٰكِن ظَنَنتُمُۥٓ أَنَّ ࡰ۬للَّهَ لَا يَعْلَمُ كَثِيراࣰ مِّمَّا تَعْمَلُونَ࣌', 'وما كنتم تستترون أن يشهد عليكم سمعكم ولا أبصركم ولا جلودكم࣌ ولكن ظننتم أن ࡰلله لا يعلم كثيرا مما تعملون࣌', NULL, 479, 'local:warsh-text.json'),
  ('warsh-41-22', 'warsh', 41, 22, 'وَذَٰلِكُمْ ظَنُّكُمُ ࡲ۬لذِے ظَنَنتُم بِرَبِّكُمُۥٓ أَرْدٜيٰكُمْ فَأَصْبَحْتُم مِّنَ ࡰ۬لْخَٰسِرِينَ࣌', 'وذلكم ظنكم ࡲلذے ظننتم بربكم أرديكم فأصبحتم من ࡰلخسرين࣌', NULL, 479, 'local:warsh-text.json'),
  ('warsh-41-23', 'warsh', 41, 23, 'فَإِنْ يَّصْبِرُواْ فَالنَّارُ مَثْوىࣰ لَّهُمْ࣌ وَإِنْ يَّسْتَعْتِبُواْ فَمَا هُم مِّنَ ࡰ۬لْمُعْتَبِينَ࣌', 'فإن يصبروا فالنار مثوى لهم࣌ وإن يستعتبوا فما هم من ࡰلمعتبين࣌', NULL, 479, 'local:warsh-text.json'),
  ('warsh-41-24', 'warsh', 41, 24, '۞ وَقَيَّضْنَا لَهُمْ قُرَنَآءَ فَزَيَّنُواْ لَهُم مَّا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ࣌ وَحَقَّ عَلَيْهِمُ ࡲ۬لْقَوْلُ فِےٓ أُمَمࣲ قَدْ خَلَتْ مِن قَبْلِهِم مِّنَ ࡰ۬لْجِنِّ وَالِانسِ࣌ إِنَّهُمْ كَانُواْ خَٰسِرِينَ࣌', 'وقيضنا لهم قرناء فزينوا لهم ما بين أيديهم وما خلفهم࣌ وحق عليهم ࡲلقول فے أمم قد خلت من قبلهم من ࡰلجن والانس࣌ إنهم كانوا خسرين࣌', NULL, 479, 'local:warsh-text.json'),
  ('warsh-41-25', 'warsh', 41, 25, 'وَقَالَ ࡰ۬لذِينَ كَفَرُواْ لَا تَسْمَعُواْ لِهَٰذَا ࡰ۬لْقُرْءَانِ وَالْغَوْاْ فِيهِ لَعَلَّكُمْ تَغْلِبُونَ࣌', 'وقال ࡰلذين كفروا لا تسمعوا لهذا ࡰلقرءان والغوا فيه لعلكم تغلبون࣌', NULL, 479, 'local:warsh-text.json'),
  ('warsh-41-26', 'warsh', 41, 26, 'فَلَنُذِيقَنَّ ࡰ۬لذِينَ كَفَرُواْ عَذَاباࣰ شَدِيداࣰ وَلَنَجْزِيَنَّهُمُۥٓ أَسْوَأَ ࡰ۬لذِے كَانُواْ يَعْمَلُونَ࣌', 'فلنذيقن ࡰلذين كفروا عذابا شديدا ولنجزينهم أسوأ ࡰلذے كانوا يعملون࣌', NULL, 479, 'local:warsh-text.json'),
  ('warsh-41-27', 'warsh', 41, 27, 'ذَٰلِكَ جَزَآءُ ࡶَعْدَآءِ ࡴ۬للَّهِ ࡴ۬لنَّارُ࣌ لَهُمْ فِيهَا دَارُ ࡲ۬لْخُلْدِ࣌ جَزَآءَۢ بِمَا كَانُواْ بِـَٔايَٰتِنَا يَجْحَدُونَ࣌', 'ذلك جزاء ࡶعداء ࡴلله ࡴلنار࣌ لهم فيها دار ࡲلخلد࣌ جزاء بما كانوا بايتنا يجحدون࣌', NULL, 479, 'local:warsh-text.json'),
  ('warsh-41-28', 'warsh', 41, 28, 'وَقَالَ ࡰ۬لذِينَ كَفَرُواْ رَبَّنَآ أَرِنَا ࡰ۬لذَيْنِ أَضَلَّٰنَا مِنَ ࡰ۬لْجِنِّ وَالِانسِ نَجْعَلْهُمَا تَحْتَ أَقْدَامِنَا لِيَكُونَا مِنَ ࡰ۬لَاسْفَلِينَ࣌', 'وقال ࡰلذين كفروا ربنا أرنا ࡰلذين أضلنا من ࡰلجن والانس نجعلهما تحت أقدامنا ليكونا من ࡰلاسفلين࣌', NULL, 479, 'local:warsh-text.json'),
  ('warsh-41-29', 'warsh', 41, 29, 'إِنَّ ࡰ۬لذِينَ قَالُواْ رَبُّنَا ࡰ۬للَّهُ ثُمَّ ࡰٜسْتَقَٰمُواْ تَتَنَزَّلُ عَلَيْهِمُ ࡲ۬لْمَلَٰٓئِكَةُ أَلَّا تَخَافُواْ وَلَا تَحْزَنُواْ وَأَبْشِرُواْ بِالْجَنَّةِ ࡴ۬لتِے كُنتُمْ تُوعَدُونَ࣌', 'إن ࡰلذين قالوا ربنا ࡰلله ثم ࡰستقموا تتنزل عليهم ࡲلملئكة ألا تخافوا ولا تحزنوا وأبشروا بالجنة ࡴلتے كنتم توعدون࣌', NULL, 480, 'local:warsh-text.json'),
  ('warsh-41-30', 'warsh', 41, 30, 'نَحْنُ أَوْلِيَآؤُكُمْ فِے ࡴ۬لْحَيَوٰةِ ࡴ۬لدُّنْيٜا وَفِے ࡴ۬لَاخِرَةِ࣌ وَلَكُمْ فِيهَا مَا تَشْتَهِےٓ أَنفُسُكُمْ وَلَكُمْ فِيهَا مَا تَدَّعُونَ', 'نحن أولياؤكم فے ࡴلحيوة ࡴلدنيا وفے ࡴلاخرة࣌ ولكم فيها ما تشتهے أنفسكم ولكم فيها ما تدعون', NULL, 480, 'local:warsh-text.json'),
  ('warsh-41-31', 'warsh', 41, 31, 'نُزُلاࣰ مِّنْ غَفُورࣲ رَّحِيمࣲ࣌', 'نزلا من غفور رحيم࣌', NULL, 480, 'local:warsh-text.json'),
  ('warsh-41-32', 'warsh', 41, 32, 'وَمَنَ ࡰحْسَنُ قَوْلاࣰ مِّمَّن دَعَآ إِلَى ࡰ۬للَّهِ وَعَمِلَ صَٰلِحاࣰ وَقَالَ إِنَّنِے مِنَ ࡰ۬لْمُسْلِمِينَ࣌', 'ومن ࡰحسن قولا ممن دعا إلى ࡰلله وعمل صلحا وقال إننے من ࡰلمسلمين࣌', NULL, 480, 'local:warsh-text.json'),
  ('warsh-41-33', 'warsh', 41, 33, 'وَلَا تَسْتَوِے ࡴ۬لْحَسَنَةُ وَلَا ࡰ۬لسَّيِّئَةُ࣌ ࡲٜدْفَعْ بِالتِے هِيَ أَحْسَنُ فَإِذَا ࡰ۬لذِے بَيْنَكَ وَبَيْنَهُۥ عَدَٰوَةࣱ كَأَنَّهُۥ وَلِيٌّ حَمِيمࣱ࣌', 'ولا تستوے ࡴلحسنة ولا ࡰلسيئة࣌ ࡲدفع بالتے هي أحسن فإذا ࡰلذے بينك وبينه عدوة كأنه ولي حميم࣌', NULL, 480, 'local:warsh-text.json'),
  ('warsh-41-34', 'warsh', 41, 34, 'وَمَا يُلَقّٜيٰهَآ إِلَّا ࡰ۬لذِينَ صَبَرُواْ࣌ وَمَا يُلَقّٜيٰهَآ إِلَّا ذُو حَظٍّ عَظِيمࣲ࣌', 'وما يلقيها إلا ࡰلذين صبروا࣌ وما يلقيها إلا ذو حظ عظيم࣌', NULL, 480, 'local:warsh-text.json'),
  ('warsh-41-35', 'warsh', 41, 35, 'وَإِمَّا يَنزَغَنَّكَ مِنَ ࡰ۬لشَّيْطَٰنِ نَزْغࣱ فَاسْتَعِذْ بِاللَّهِ࣌ إِنَّهُۥ هُوَ ࡰ۬لسَّمِيعُ ࡲ۬لْعَلِيمُ࣌', 'وإما ينزغنك من ࡰلشيطن نزغ فاستعذ بالله࣌ إنه هو ࡰلسميع ࡲلعليم࣌', NULL, 480, 'local:warsh-text.json'),
  ('warsh-41-36', 'warsh', 41, 36, 'وَمِنَ اٰيَٰتِهِ ࡴ۬ليْلُ وَالنَّهَارُ وَالشَّمْسُ وَالْقَمَرُ࣌ لَا تَسْجُدُواْ لِلشَّمْسِ وَلَا لِلْقَمَرِ࣌ وَاسْجُدُواْ لِلهِ ࡴ۬لذِے خَلَقَهُنَّ إِن كُنتُمُۥٓ إِيَّاهُ تَعْبُدُونَ࣌۩', 'ومن ايته ࡴليل والنهار والشمس والقمر࣌ لا تسجدوا للشمس ولا للقمر࣌ واسجدوا لله ࡴلذے خلقهن إن كنتم إياه تعبدون࣌', NULL, 480, 'local:warsh-text.json'),
  ('warsh-41-37', 'warsh', 41, 37, '۞ فَإِنِ ࡴٜسْتَكْبَرُواْ فَالذِينَ عِندَ رَبِّكَ يُسَبِّحُونَ لَهُۥ بِاليْلِ وَالنَّهٜارِ وَهُمْ لَا يَسْـَٔمُونَ࣌', 'فإن ࡴستكبروا فالذين عند ربك يسبحون له باليل والنهار وهم لا يسمون࣌', NULL, 480, 'local:warsh-text.json'),
  ('warsh-41-38', 'warsh', 41, 38, 'وَمِنَ اٰيَٰتِهِۦٓ أَنَّكَ تَرَى ࡰ۬لَارْضَ خَٰشِعَةࣰ فَإِذَآ أَنزَلْنَا عَلَيْهَا ࡰ۬لْمَآءَ ࡰٜهْتَزَّتْ وَرَبَتِ࣌ ࡴنَّ ࡰ۬لذِےٓ أَحْيٜاهَا لَمُحْيِ ࡴ۬لْمَوْتٜىٰٓ࣌ إِنَّهُۥ عَلَىٰ كُلِّ شَےْءࣲ قَدِيرٌ࣌', 'ومن ايته أنك ترى ࡰلارض خشعة فإذا أنزلنا عليها ࡰلماء ࡰهتزت وربت࣌ ࡴن ࡰلذے أحياها لمحي ࡴلموتى࣌ إنه على كل شےء قدير࣌', NULL, 481, 'local:warsh-text.json'),
  ('warsh-41-39', 'warsh', 41, 39, 'ࡴنَّ ࡰ۬لذِينَ يُلْحِدُونَ فِےٓ ءَايَٰتِنَا لَا يَخْفَوْنَ عَلَيْنَآ࣌ أَفَمَنْ يُّلْقٜىٰ فِے ࡴ۬لنّٜارِ خَيْرٌ ࡰم مَّنْ يَّاتِےٓ ءَامِناࣰ يَوْمَ ࡰ۬لْقِيَٰمَةِ࣌ ࡴٜعْمَلُواْ مَا شِئْتُمُۥٓ࣌ إِنَّهُۥ بِمَا تَعْمَلُونَ بَصِيرٌ࣌', 'ࡴن ࡰلذين يلحدون فے ءايتنا لا يخفون علينا࣌ أفمن يلقى فے ࡴلنار خير ࡰم من ياتے ءامنا يوم ࡰلقيمة࣌ ࡴعملوا ما شئتم࣌ إنه بما تعملون بصير࣌', NULL, 481, 'local:warsh-text.json'),
  ('warsh-41-40', 'warsh', 41, 40, 'ࡴنَّ ࡰ۬لذِينَ كَفَرُواْ بِالذِّكْرِ لَمَّا جَآءَهُمْ وَإِنَّهُۥ لَكِتَٰبٌ عَزِيزࣱ', 'ࡴن ࡰلذين كفروا بالذكر لما جاءهم وإنه لكتب عزيز', NULL, 481, 'local:warsh-text.json'),
  ('warsh-41-41', 'warsh', 41, 41, 'لَّا يَاتِيهِ ࡴ۬لْبَٰطِلُ مِنۢ بَيْنِ يَدَيْهِ وَلَا مِنْ خَلْفِهِۦ࣌ تَنزِيلࣱ مِّنْ حَكِيمٍ حَمِيدࣲ࣌', 'لا ياتيه ࡴلبطل من بين يديه ولا من خلفه࣌ تنزيل من حكيم حميد࣌', NULL, 481, 'local:warsh-text.json'),
  ('warsh-41-42', 'warsh', 41, 42, 'مَّا يُقَالُ لَكَ إِلَّا مَا قَدْ قِيلَ لِلرُّسُلِ مِن قَبْلِكَ࣌ إِنَّ رَبَّكَ لَذُو مَغْفِرَةࣲ وَذُو عِقَابٍ ࡰلِيمࣲ࣌', 'ما يقال لك إلا ما قد قيل للرسل من قبلك࣌ إن ربك لذو مغفرة وذو عقاب ࡰليم࣌', NULL, 481, 'local:warsh-text.json'),
  ('warsh-41-43', 'warsh', 41, 43, 'وَلَوْ جَعَلْنَٰهُ قُرْءَاناً ࡰعْجَمِيّاࣰ لَّقَالُواْ لَوْلَا فُصِّلَتَ اٰيَٰتُهُۥٓ࣌ ءَآعْجَمِيࣱّ وَعَرَبِيࣱّ࣌ قُلْ هُوَ لِلذِينَ ءَامَنُواْ هُدىࣰ وَشِفَآءࣱ࣌ وَالذِينَ لَا يُومِنُونَ فِےٓ ءَاذَانِهِمْ وَقْرࣱ وَهُوَ عَلَيْهِمْ عَمىً࣌ ࡳوْلَٰٓئِكَ يُنَادَوْنَ مِن مَّكَانِۢ بَعِيدࣲ࣌', 'ولو جعلنه قرءانا ࡰعجميا لقالوا لولا فصلت ايته࣌ ءاعجمي وعربي࣌ قل هو للذين ءامنوا هدى وشفاء࣌ والذين لا يومنون فے ءاذانهم وقر وهو عليهم عمى࣌ ࡳولئك ينادون من مكان بعيد࣌', NULL, 481, 'local:warsh-text.json'),
  ('warsh-41-44', 'warsh', 41, 44, 'وَلَقَدَ اٰتَيْنَا مُوسَى ࡰ۬لْكِتَٰبَ فَاخْتُلِفَ فِيهِ࣌ وَلَوْلَا كَلِمَةࣱ سَبَقَتْ مِن رَّبِّكَ لَقُضِيَ بَيْنَهُمْ࣌ وَإِنَّهُمْ لَفِے شَكࣲّ مِّنْهُ مُرِيبࣲ࣌', 'ولقد اتينا موسى ࡰلكتب فاختلف فيه࣌ ولولا كلمة سبقت من ربك لقضي بينهم࣌ وإنهم لفے شك منه مريب࣌', NULL, 481, 'local:warsh-text.json'),
  ('warsh-41-45', 'warsh', 41, 45, 'مَّنْ عَمِلَ صَٰلِحاࣰ فَلِنَفْسِهِۦ࣌ وَمَنَ ࡰسَآءَ فَعَلَيْهَا࣌ وَمَا رَبُّكَ بِظَلَّٰمࣲ لِّلْعَبِيدِ࣌', 'من عمل صلحا فلنفسه࣌ ومن ࡰساء فعليها࣌ وما ربك بظلم للعبيد࣌', NULL, 481, 'local:warsh-text.json'),
  ('warsh-41-46', 'warsh', 41, 46, '۞ إِلَيْهِ يُرَدُّ عِلْمُ ࡲ۬لسَّاعَةِ࣌ وَمَا تَخْرُجُ مِن ثَمَرَٰتࣲ مِّنَ ࡰكْمَامِهَا وَمَا تَحْمِلُ مِنُ ࡳنثٜىٰ وَلَا تَضَعُ إِلَّا بِعِلْمِهِۦ࣌ وَيَوْمَ يُنَادِيهِمُۥٓ أَيْنَ شُرَكَآءِے قَالُوٓاْ ءَاذَنَّٰكَ مَا مِنَّا مِن شَهِيدࣲ࣌', 'إليه يرد علم ࡲلساعة࣌ وما تخرج من ثمرت من ࡰكمامها وما تحمل من ࡳنثى ولا تضع إلا بعلمه࣌ ويوم يناديهم أين شركاءے قالوا ءاذنك ما منا من شهيد࣌', NULL, 482, 'local:warsh-text.json'),
  ('warsh-41-47', 'warsh', 41, 47, 'وَضَلَّ عَنْهُم مَّا كَانُواْ يَدْعُونَ مِن قَبْلُ وَظَنُّواْ࣌ مَا لَهُم مِّن مَّحِيصࣲ࣌', 'وضل عنهم ما كانوا يدعون من قبل وظنوا࣌ ما لهم من محيص࣌', NULL, 482, 'local:warsh-text.json'),
  ('warsh-41-48', 'warsh', 41, 48, 'لَّا يَسْـَٔمُ ࡲ۬لِانسَٰنُ مِن دُعَآءِ ࡴ۬لْخَيْرِ࣌ وَإِن مَّسَّهُ ࡲ۬لشَّرُّ فَيَـُٔوسࣱ قَنُوطࣱ࣌', 'لا يسم ࡲلانسن من دعاء ࡴلخير࣌ وإن مسه ࡲلشر فيوس قنوط࣌', NULL, 482, 'local:warsh-text.json'),
  ('warsh-41-49', 'warsh', 41, 49, 'وَلَئِنَ ࡰذَقْنَٰهُ رَحْمَةࣰ مِّنَّا مِنۢ بَعْدِ ضَرَّآءَ مَسَّتْهُ لَيَقُولَنَّ هَٰذَا لِے وَمَآ أَظُنُّ ࡲ۬لسَّاعَةَ قَآئِمَةࣰ وَلَئِن رُّجِعْتُ إِلَىٰ رَبِّيَ إِنَّ لِے عِندَهُۥ لَلْحُسْنٜىٰ࣌ فَلَنُنَبِّئَنَّ ࡰ۬لذِينَ كَفَرُواْ بِمَا عَمِلُواْ وَلَنُذِيقَنَّهُم مِّنْ عَذَابٍ غَلِيظࣲ࣌', 'ولئن ࡰذقنه رحمة منا من بعد ضراء مسته ليقولن هذا لے وما أظن ࡲلساعة قائمة ولئن رجعت إلى ربي إن لے عنده للحسنى࣌ فلننبئن ࡰلذين كفروا بما عملوا ولنذيقنهم من عذاب غليظ࣌', NULL, 482, 'local:warsh-text.json'),
  ('warsh-41-50', 'warsh', 41, 50, 'وَإِذَآ أَنْعَمْنَا عَلَى ࡰ۬لِانسَٰنِ أَعْرَضَ وَنَـٜٔا بِجَانِبِهِۦ࣌ وَإِذَا مَسَّهُ ࡲ۬لشَّرُّ فَذُو دُعَآءٍ عَرِيضࣲ࣌', 'وإذا أنعمنا على ࡰلانسن أعرض ونا بجانبه࣌ وإذا مسه ࡲلشر فذو دعاء عريض࣌', NULL, 482, 'local:warsh-text.json'),
  ('warsh-41-51', 'warsh', 41, 51, 'قُلَ ࡰرَٰٓيْتُمُۥٓ إِن كَانَ مِنْ عِندِ ࡴ۬للَّهِ ثُمَّ كَفَرْتُم بِهِۦ مَنَ ࡰضَلُّ مِمَّنْ هُوَ فِے شِقَاقِۢ بَعِيدࣲ࣌', 'قل ࡰريتم إن كان من عند ࡴلله ثم كفرتم به من ࡰضل ممن هو فے شقاق بعيد࣌', NULL, 482, 'local:warsh-text.json'),
  ('warsh-41-52', 'warsh', 41, 52, 'سَنُرِيهِمُۥٓ ءَايَٰتِنَا فِے ࡴ۬لَافَاقِ وَفِےٓ أَنفُسِهِمْ حَتَّىٰ يَتَبَيَّنَ لَهُمُۥٓ أَنَّهُ ࡲ۬لْحَقُّ࣌ أَوَلَمْ يَكْفِ بِرَبِّكَ أَنَّهُۥ عَلَىٰ كُلِّ شَےْءࣲ شَهِيدٌ࣌', 'سنريهم ءايتنا فے ࡴلافاق وفے أنفسهم حتى يتبين لهم أنه ࡲلحق࣌ أولم يكف بربك أنه على كل شےء شهيد࣌', NULL, 482, 'local:warsh-text.json'),
  ('warsh-41-53', 'warsh', 41, 53, 'ࡰلَآ إِنَّهُمْ فِے مِرْيَةࣲ مِّن لِّقَآءِ رَبِّهِمُۥٓ࣌ أَلَآ إِنَّهُۥ بِكُلِّ شَےْءࣲ مُّحِيطٌ࣌', 'ࡰلا إنهم فے مرية من لقاء ربهم࣌ ألا إنه بكل شےء محيط࣌', NULL, 482, 'local:warsh-text.json'),
  ('warsh-42-1', 'warsh', 42, 1, 'حٜمِٓ عَٓسِٓقَٓ࣌ كَذَٰلِكَ يُوحِےٓ إِلَيْكَ وَإِلَى ࡰ۬لذِينَ مِن قَبْلِكَ ࡰ۬للَّهُ ࡲ۬لْعَزِيزُ ࡲ۬لْحَكِيمُ࣌', 'حم عسق࣌ كذلك يوحے إليك وإلى ࡰلذين من قبلك ࡰلله ࡲلعزيز ࡲلحكيم࣌', NULL, 483, 'local:warsh-text.json'),
  ('warsh-42-2', 'warsh', 42, 2, 'لَهُۥ مَا فِے ࡴ۬لسَّمَٰوَٰتِ وَمَا فِے ࡴ۬لَارْضِ࣌ وَهُوَ ࡰ۬لْعَلِيُّ ࡲ۬لْعَظِيمُ࣌', 'له ما فے ࡴلسموت وما فے ࡴلارض࣌ وهو ࡰلعلي ࡲلعظيم࣌', NULL, 483, 'local:warsh-text.json'),
  ('warsh-42-3', 'warsh', 42, 3, '۞ يَكَادُ ࡲ۬لسَّمَٰوَٰتُ يَتَفَطَّرْنَ مِن فَوْقِهِنَّ࣌ وَالْمَلَٰٓئِكَةُ يُسَبِّحُونَ بِحَمْدِ رَبِّهِمْ وَيَسْتَغْفِرُونَ لِمَن فِے ࡴ۬لَارْضِ࣌ أَلَآ إِنَّ ࡰ۬للَّهَ هُوَ ࡰ۬لْغَفُورُ ࡲ۬لرَّحِيمُ࣌', 'يكاد ࡲلسموت يتفطرن من فوقهن࣌ والملئكة يسبحون بحمد ربهم ويستغفرون لمن فے ࡴلارض࣌ ألا إن ࡰلله هو ࡰلغفور ࡲلرحيم࣌', NULL, 483, 'local:warsh-text.json'),
  ('warsh-42-4', 'warsh', 42, 4, 'وَالذِينَ ࡰٜتَّخَذُواْ مِن دُونِهِۦٓ أَوْلِيَآءَ ࡰ۬للَّهُ حَفِيظٌ عَلَيْهِمْ࣌ وَمَآ أَنتَ عَلَيْهِم بِوَكِيلࣲ࣌', 'والذين ࡰتخذوا من دونه أولياء ࡰلله حفيظ عليهم࣌ وما أنت عليهم بوكيل࣌', NULL, 483, 'local:warsh-text.json'),
  ('warsh-42-5', 'warsh', 42, 5, 'وَكَذَٰلِكَ أَوْحَيْنَآ إِلَيْكَ قُرْءَاناً عَرَبِيّاࣰ لِّتُنذِرَ أُمَّ ࡰ۬لْقُرٜىٰ وَمَنْ حَوْلَهَا وَتُنذِرَ يَوْمَ ࡰ۬لْجَمْعِ لَا رَيْبَ فِيهِ࣌ فَرِيقࣱ فِے ࡴ۬لْجَنَّةِ࣌ وَفَرِيقࣱ فِے ࡴ۬لسَّعِيرِ࣌', 'وكذلك أوحينا إليك قرءانا عربيا لتنذر أم ࡰلقرى ومن حولها وتنذر يوم ࡰلجمع لا ريب فيه࣌ فريق فے ࡴلجنة࣌ وفريق فے ࡴلسعير࣌', NULL, 483, 'local:warsh-text.json'),
  ('warsh-42-6', 'warsh', 42, 6, 'وَلَوْ شَآءَ ࡰ۬للَّهُ لَجَعَلَهُمُۥٓ أُمَّةࣰ وَٰحِدَةࣰ࣌ وَلَٰكِنْ يُّدْخِلُ مَنْ يَّشَآءُ فِے رَحْمَتِهِۦ࣌ وَالظَّٰلِمُونَ مَا لَهُم مِّنْ وَّلِيࣲّ وَلَا نَصِيرٍ࣌', 'ولو شاء ࡰلله لجعلهم أمة وحدة࣌ ولكن يدخل من يشاء فے رحمته࣌ والظلمون ما لهم من ولي ولا نصير࣌', NULL, 483, 'local:warsh-text.json'),
  ('warsh-42-7', 'warsh', 42, 7, 'ࡰمِ ࡴٜتَّخَذُواْ مِن دُونِهِۦٓ أَوْلِيَآءَ࣌ فَاللَّهُ هُوَ ࡰ۬لْوَلِيُّ࣌ وَهُوَ يُحْيِ ࡴ۬لْمَوْتٜىٰ࣌ وَهُوَ عَلَىٰ كُلِّ شَےْءࣲ قَدِيرࣱ࣌', 'ࡰم ࡴتخذوا من دونه أولياء࣌ فالله هو ࡰلولي࣌ وهو يحي ࡴلموتى࣌ وهو على كل شےء قدير࣌', NULL, 483, 'local:warsh-text.json'),
  ('warsh-42-8', 'warsh', 42, 8, 'وَمَا ࡰٜخْتَلَفْتُمْ فِيهِ مِن شَےْءࣲ فَحُكْمُهُۥٓ إِلَى ࡰ۬للَّهِ࣌ ذَٰلِكُمُ ࡲ۬للَّهُ رَبِّے࣌ عَلَيْهِ تَوَكَّلْتُ࣌ وَإِلَيْهِ أُنِيبُ࣌', 'وما ࡰختلفتم فيه من شےء فحكمه إلى ࡰلله࣌ ذلكم ࡲلله ربے࣌ عليه توكلت࣌ وإليه أنيب࣌', NULL, 483, 'local:warsh-text.json'),
  ('warsh-42-9', 'warsh', 42, 9, 'فَاطِرُ ࡲ۬لسَّمَٰوَٰتِ وَالَارْضِ جَعَلَ لَكُم مِّنَ ࡰنفُسِكُمُۥٓ أَزْوَٰجاࣰ وَمِنَ ࡰ۬لَانْعَٰمِ أَزْوَٰجاࣰ يَذْرَؤُكُمْ فِيهِ࣌ لَيْسَ كَمِثْلِهِۦ شَےْءࣱ࣌ وَهُوَ ࡰ۬لسَّمِيعُ ࡲ۬لْبَصِيرُ࣌', 'فاطر ࡲلسموت والارض جعل لكم من ࡰنفسكم أزوجا ومن ࡰلانعم أزوجا يذرؤكم فيه࣌ ليس كمثله شےء࣌ وهو ࡰلسميع ࡲلبصير࣌', NULL, 484, 'local:warsh-text.json'),
  ('warsh-42-10', 'warsh', 42, 10, 'لَهُۥ مَقَالِيدُ ࡲ۬لسَّمَٰوَٰتِ وَالَارْضِ࣌ يَبْسُطُ ࡲ۬لرِّزْقَ لِمَنْ يَّشَآءُ وَيَقْدِرُ࣌ إِنَّهُۥ بِكُلِّ شَےْءٍ عَلِيمࣱ࣌', 'له مقاليد ࡲلسموت والارض࣌ يبسط ࡲلرزق لمن يشاء ويقدر࣌ إنه بكل شےء عليم࣌', NULL, 484, 'local:warsh-text.json'),
  ('warsh-42-11', 'warsh', 42, 11, '۞ شَرَعَ لَكُم مِّنَ ࡰ۬لدِّينِ مَا وَصّٜىٰ بِهِۦ نُوحاࣰ وَالذِےٓ أَوْحَيْنَآ إِلَيْكَ وَمَا وَصَّيْنَا بِهِۦٓ إِبْرَٰهِيمَ وَمُوسٜىٰ وَعِيسٜىٰٓ أَنَ ࡰقِيمُواْ ࡲ۬لدِّينَ وَلَا تَتَفَرَّقُواْ فِيهِ࣌ كَبُرَ عَلَى ࡰ۬لْمُشْرِكِينَ مَا تَدْعُوهُمُۥٓ إِلَيْهِ࣌ ࡴ۬للَّهُ يَجْتَبِےٓ إِلَيْهِ مَنْ يَّشَآءُ وَيَهْدِےٓ إِلَيْهِ مَنْ يُّنِيبُ࣌', 'شرع لكم من ࡰلدين ما وصى به نوحا والذے أوحينا إليك وما وصينا به إبرهيم وموسى وعيسى أن ࡰقيموا ࡲلدين ولا تتفرقوا فيه࣌ كبر على ࡰلمشركين ما تدعوهم إليه࣌ ࡴلله يجتبے إليه من يشاء ويهدے إليه من ينيب࣌', NULL, 484, 'local:warsh-text.json'),
  ('warsh-42-12', 'warsh', 42, 12, 'وَمَا تَفَرَّقُوٓاْ إِلَّا مِنۢ بَعْدِ مَا جَآءَهُمُ ࡲ۬لْعِلْمُ࣌ بَغْياَۢ بَيْنَهُمْ࣌ وَلَوْلَا كَلِمَةࣱ سَبَقَتْ مِن رَّبِّكَ إِلَىٰٓ أَجَلࣲ مُّسَمّىࣰ لَّقُضِيَ بَيْنَهُمْ࣌ وَإِنَّ ࡰ۬لذِينَ أُورِثُواْ ࡲ۬لْكِتَٰبَ مِنۢ بَعْدِهِمْ لَفِے شَكࣲّ مِّنْهُ مُرِيبࣲ࣌', 'وما تفرقوا إلا من بعد ما جاءهم ࡲلعلم࣌ بغيا بينهم࣌ ولولا كلمة سبقت من ربك إلى أجل مسمى لقضي بينهم࣌ وإن ࡰلذين أورثوا ࡲلكتب من بعدهم لفے شك منه مريب࣌', NULL, 484, 'local:warsh-text.json'),
  ('warsh-42-13', 'warsh', 42, 13, 'فَلِذَٰلِكَ فَادْعُ وَاسْتَقِمْ كَمَآ أُمِرْتَ وَلَا تَتَّبِعَ ࡰهْوَآءَهُمْ࣌ وَقُلَ اٰمَنتُ بِمَآ أَنزَلَ ࡰ۬للَّهُ مِن كِتَٰبࣲ وَأُمِرْتُ لِأَعْدِلَ بَيْنَكُمُ࣌ ࡲ۬للَّهُ رَبُّنَا وَرَبُّكُمْ࣌ لَنَآ أَعْمَٰلُنَا وَلَكُمُۥٓ أَعْمَٰلُكُمْ࣌ لَا حُجَّةَ بَيْنَنَا وَبَيْنَكُمُ࣌ ࡲ۬للَّهُ يَجْمَعُ بَيْنَنَا࣌ وَإِلَيْهِ ࡴ۬لْمَصِيرُ࣌', 'فلذلك فادع واستقم كما أمرت ولا تتبع ࡰهواءهم࣌ وقل امنت بما أنزل ࡰلله من كتب وأمرت لأعدل بينكم࣌ ࡲلله ربنا وربكم࣌ لنا أعملنا ولكم أعملكم࣌ لا حجة بيننا وبينكم࣌ ࡲلله يجمع بيننا࣌ وإليه ࡴلمصير࣌', NULL, 484, 'local:warsh-text.json'),
  ('warsh-42-14', 'warsh', 42, 14, 'وَالذِينَ يُحَآجُّونَ فِے ࡴ۬للَّهِ مِنۢ بَعْدِ مَا ࡸَسْتُجِيبَ لَهُۥ حُجَّتُهُمْ دَاحِضَةٌ عِندَ رَبِّهِمْ وَعَلَيْهِمْ غَضَبࣱ࣌ وَلَهُمْ عَذَابࣱ شَدِيدٌ࣌', 'والذين يحاجون فے ࡴلله من بعد ما ࡸستجيب له حجتهم داحضة عند ربهم وعليهم غضب࣌ ولهم عذاب شديد࣌', NULL, 485, 'local:warsh-text.json'),
  ('warsh-42-15', 'warsh', 42, 15, 'ࡴ۬للَّهُ ࡲ۬لذِےٓ أَنزَلَ ࡰ۬لْكِتَٰبَ بِالْحَقِّ وَالْمِيزَانَ࣌ وَمَا يُدْرِيكَ لَعَلَّ ࡰ۬لسَّاعَةَ قَرِيبࣱ࣌', 'ࡴلله ࡲلذے أنزل ࡰلكتب بالحق والميزان࣌ وما يدريك لعل ࡰلساعة قريب࣌', NULL, 485, 'local:warsh-text.json'),
  ('warsh-42-16', 'warsh', 42, 16, 'يَسْتَعْجِلُ بِهَا ࡰ۬لذِينَ لَا يُومِنُونَ بِهَا࣌ وَالذِينَ ءَامَنُواْ مُشْفِقُونَ مِنْهَا وَيَعْلَمُونَ أَنَّهَا ࡰ۬لْحَقُّ࣌ أَلَآ إِنَّ ࡰ۬لذِينَ يُمَارُونَ فِے ࡴ۬لسَّاعَةِ لَفِے ضَلَٰلِۢ بَعِيدٍ࣌', 'يستعجل بها ࡰلذين لا يومنون بها࣌ والذين ءامنوا مشفقون منها ويعلمون أنها ࡰلحق࣌ ألا إن ࡰلذين يمارون فے ࡴلساعة لفے ضلل بعيد࣌', NULL, 485, 'local:warsh-text.json'),
  ('warsh-42-17', 'warsh', 42, 17, 'ࡴ۬للَّهُ لَطِيفُۢ بِعِبَادِهِۦ࣌ يَرْزُقُ مَنْ يَّشَآءُ࣌ وَهُوَ ࡰ۬لْقَوِيُّ ࡲ۬لْعَزِيزُ࣌', 'ࡴلله لطيف بعباده࣌ يرزق من يشاء࣌ وهو ࡰلقوي ࡲلعزيز࣌', NULL, 485, 'local:warsh-text.json'),
  ('warsh-42-18', 'warsh', 42, 18, '۞ مَن كَانَ يُرِيدُ حَرْثَ ࡰ۬لَاخِرَةِ نَزِدْ لَهُۥ فِے حَرْثِهِۦ࣌ وَمَن كَانَ يُرِيدُ حَرْثَ ࡰ۬لدُّنْيٜا نُوتِهِۦ مِنْهَا࣌ وَمَا لَهُۥ فِے ࡴ۬لَاخِرَةِ مِن نَّصِيبٍ࣌', 'من كان يريد حرث ࡰلاخرة نزد له فے حرثه࣌ ومن كان يريد حرث ࡰلدنيا نوته منها࣌ وما له فے ࡴلاخرة من نصيب࣌', NULL, 485, 'local:warsh-text.json'),
  ('warsh-42-19', 'warsh', 42, 19, 'ࡰمْ لَهُمْ شُرَكَٰٓؤُاْ شَرَعُواْ لَهُم مِّنَ ࡰ۬لدِّينِ مَا لَمْ يَاذَنۢ بِهِ ࡴ۬للَّهُ࣌ وَلَوْلَا كَلِمَةُ ࡲ۬لْفَصْلِ لَقُضِيَ بَيْنَهُمْ࣌ وَإِنَّ ࡰ۬لظَّٰلِمِينَ لَهُمْ عَذَابٌ ࡰلِيمࣱ࣌', 'ࡰم لهم شركؤا شرعوا لهم من ࡰلدين ما لم ياذن به ࡴلله࣌ ولولا كلمة ࡲلفصل لقضي بينهم࣌ وإن ࡰلظلمين لهم عذاب ࡰليم࣌', NULL, 485, 'local:warsh-text.json'),
  ('warsh-42-20', 'warsh', 42, 20, 'تَرَى ࡰ۬لظَّٰلِمِينَ مُشْفِقِينَ مِمَّا كَسَبُواْ وَهُوَ وَاقِعُۢ بِهِمْ࣌ وَالذِينَ ءَامَنُواْ وَعَمِلُواْ ࡲ۬لصَّٰلِحَٰتِ فِے رَوْضَاتِ ࡴ۬لْجَنَّاتِ࣌ لَهُم مَّا يَشَآءُونَ عِندَ رَبِّهِمْ࣌ ذَٰلِكَ هُوَ ࡰ۬لْفَضْلُ ࡲ۬لْكَبِيرُ࣌', 'ترى ࡰلظلمين مشفقين مما كسبوا وهو واقع بهم࣌ والذين ءامنوا وعملوا ࡲلصلحت فے روضات ࡴلجنات࣌ لهم ما يشاءون عند ربهم࣌ ذلك هو ࡰلفضل ࡲلكبير࣌', NULL, 485, 'local:warsh-text.json'),
  ('warsh-42-21', 'warsh', 42, 21, 'ذَٰلِكَ ࡰ۬لذِے يُبَشِّرُ ࡲ۬للَّهُ عِبَادَهُ ࡲ۬لذِينَ ءَامَنُواْ وَعَمِلُواْ ࡲ۬لصَّٰلِحَٰتِ࣌ قُل لَّآ أَسْـَٔلُكُمْ عَلَيْهِ أَجْراً ࡴلَّا ࡰ۬لْمَوَدَّةَ فِے ࡴ۬لْقُرْبٜىٰ࣌ وَمَنْ يَّقْتَرِفْ حَسَنَةࣰ نَّزِدْ لَهُۥ فِيهَا حُسْناً࣌ ࡴنَّ ࡰ۬للَّهَ غَفُورࣱ شَكُورٌ࣌', 'ذلك ࡰلذے يبشر ࡲلله عباده ࡲلذين ءامنوا وعملوا ࡲلصلحت࣌ قل لا أسلكم عليه أجرا ࡴلا ࡰلمودة فے ࡴلقربى࣌ ومن يقترف حسنة نزد له فيها حسنا࣌ ࡴن ࡰلله غفور شكور࣌', NULL, 486, 'local:warsh-text.json'),
  ('warsh-42-22', 'warsh', 42, 22, 'ࡰمْ يَقُولُونَ ࡰٜفْتَرٜىٰ عَلَى ࡰ۬للَّهِ كَذِباࣰ࣌ فَإِنْ يَّشَإِ ࡴ۬للَّهُ يَخْتِمْ عَلَىٰ قَلْبِكَ࣌ وَيَمْحُ ࡲ۬للَّهُ ࡲ۬لْبَٰطِلَ وَيُحِقُّ ࡲ۬لْحَقَّ بِكَلِمَٰتِهِۦٓ࣌ إِنَّهُۥ عَلِيمُۢ بِذَاتِ ࡴ۬لصُّدُورِ࣌', 'ࡰم يقولون ࡰفترى على ࡰلله كذبا࣌ فإن يشإ ࡴلله يختم على قلبك࣌ ويمح ࡲلله ࡲلبطل ويحق ࡲلحق بكلمته࣌ إنه عليم بذات ࡴلصدور࣌', NULL, 486, 'local:warsh-text.json'),
  ('warsh-42-23', 'warsh', 42, 23, 'وَهُوَ ࡰ۬لذِے يَقْبَلُ ࡲ۬لتَّوْبَةَ عَنْ عِبَادِهِۦ وَيَعْفُواْ عَنِ ࡴ۬لسَّيِّـَٔاتِ وَيَعْلَمُ مَا يَفْعَلُونَ࣌', 'وهو ࡰلذے يقبل ࡲلتوبة عن عباده ويعفوا عن ࡴلسيات ويعلم ما يفعلون࣌', NULL, 486, 'local:warsh-text.json'),
  ('warsh-42-24', 'warsh', 42, 24, 'وَيَسْتَجِيبُ ࡲ۬لذِينَ ءَامَنُواْ وَعَمِلُواْ ࡲ۬لصَّٰلِحَٰتِ وَيَزِيدُهُم مِّن فَضْلِهِۦ࣌ وَالْكَٰفِرُونَ لَهُمْ عَذَابࣱ شَدِيدࣱ࣌', 'ويستجيب ࡲلذين ءامنوا وعملوا ࡲلصلحت ويزيدهم من فضله࣌ والكفرون لهم عذاب شديد࣌', NULL, 486, 'local:warsh-text.json'),
  ('warsh-42-25', 'warsh', 42, 25, '۞ وَلَوْ بَسَطَ ࡰ۬للَّهُ ࡲ۬لرِّزْقَ لِعِبَادِهِۦ لَبَغَوْاْ فِے ࡴ۬لَارْضِ࣌ وَلَٰكِنْ يُّنَزِّلُ بِقَدَرࣲ مَّا يَشَآءُ࣌ ࡹِنَّهُۥ بِعِبَادِهِۦ خَبِيرُۢ بَصِيرࣱ࣌', 'ولو بسط ࡰلله ࡲلرزق لعباده لبغوا فے ࡴلارض࣌ ولكن ينزل بقدر ما يشاء࣌ ࡹنه بعباده خبير بصير࣌', NULL, 486, 'local:warsh-text.json'),
  ('warsh-42-26', 'warsh', 42, 26, 'وَهُوَ ࡰ۬لذِے يُنَزِّلُ ࡲ۬لْغَيْثَ مِنۢ بَعْدِ مَا قَنَطُواْ وَيَنشُرُ رَحْمَتَهُۥ࣌ وَهُوَ ࡰ۬لْوَلِيُّ ࡲ۬لْحَمِيدُ࣌', 'وهو ࡰلذے ينزل ࡲلغيث من بعد ما قنطوا وينشر رحمته࣌ وهو ࡰلولي ࡲلحميد࣌', NULL, 486, 'local:warsh-text.json'),
  ('warsh-42-27', 'warsh', 42, 27, 'وَمِنَ اٰيَٰتِهِۦ خَلْقُ ࡲ۬لسَّمَٰوَٰتِ وَالَارْضِ وَمَا بَثَّ فِيهِمَا مِن دَآبَّةࣲ࣌ وَهُوَ عَلَىٰ جَمْعِهِمُۥٓ إِذَا يَشَآءُ قَدِيرࣱ࣌', 'ومن ايته خلق ࡲلسموت والارض وما بث فيهما من دابة࣌ وهو على جمعهم إذا يشاء قدير࣌', NULL, 486, 'local:warsh-text.json'),
  ('warsh-42-28', 'warsh', 42, 28, 'وَمَآ أَصَٰبَكُم مِّن مُّصِيبَةِۢ بِمَا كَسَبَتَ ࡰيْدِيكُمْ وَيَعْفُواْ عَن كَثِيرࣲ࣌', 'وما أصبكم من مصيبة بما كسبت ࡰيديكم ويعفوا عن كثير࣌', NULL, 486, 'local:warsh-text.json'),
  ('warsh-42-29', 'warsh', 42, 29, 'وَمَآ أَنتُم بِمُعْجِزِينَ فِے ࡴ۬لَارْضِ࣌ وَمَا لَكُم مِّن دُونِ ࡴ۬للَّهِ مِنْ وَّلِيࣲّ وَلَا نَصِيرࣲ࣌', 'وما أنتم بمعجزين فے ࡴلارض࣌ وما لكم من دون ࡴلله من ولي ولا نصير࣌', NULL, 486, 'local:warsh-text.json'),
  ('warsh-42-30', 'warsh', 42, 30, 'وَمِنَ اٰيَٰتِهِ ࡴ۬لْجَوَارِۦ فِے ࡴ۬لْبَحْرِ كَالَاعْلَٰمِ࣌ إِنْ يَّشَأْ يُسْكِنِ ࡴ۬لرِّيَٰحَ فَيَظْلَلْنَ رَوَاكِدَ عَلَىٰ ظَهْرِهِۦٓ إِنَّ فِے ذَٰلِكَ لَأٓيَٰتࣲ لِّكُلِّ صَبّٜارࣲ شَكُورٍ', 'ومن ايته ࡴلجوار فے ࡴلبحر كالاعلم࣌ إن يشأ يسكن ࡴلريح فيظللن رواكد على ظهره إن فے ذلك لأيت لكل صبار شكور', NULL, 487, 'local:warsh-text.json'),
  ('warsh-42-31', 'warsh', 42, 31, 'ࡰوْ يُوبِقْهُنَّ بِمَا كَسَبُواْ وَيَعْفُ عَن كَثِيرࣲ࣌', 'ࡰو يوبقهن بما كسبوا ويعف عن كثير࣌', NULL, 487, 'local:warsh-text.json'),
  ('warsh-42-32', 'warsh', 42, 32, 'وَيَعْلَمُ ࡲ۬لذِينَ يُجَٰدِلُونَ فِےٓ ءَايَٰتِنَا مَا لَهُم مِّن مَّحِيصࣲ࣌', 'ويعلم ࡲلذين يجدلون فے ءايتنا ما لهم من محيص࣌', NULL, 487, 'local:warsh-text.json'),
  ('warsh-42-33', 'warsh', 42, 33, 'فَمَآ أُوتِيتُم مِّن شَےْءࣲ فَمَتَٰعُ ࡲ۬لْحَيَوٰةِ ࡴ۬لدُّنْيٜا࣌ وَمَا عِندَ ࡰ۬للَّهِ خَيْرࣱ وَأَبْقٜىٰ لِلذِينَ ءَامَنُواْ وَعَلَىٰ رَبِّهِمْ يَتَوَكَّلُونَ࣌', 'فما أوتيتم من شےء فمتع ࡲلحيوة ࡴلدنيا࣌ وما عند ࡰلله خير وأبقى للذين ءامنوا وعلى ربهم يتوكلون࣌', NULL, 487, 'local:warsh-text.json'),
  ('warsh-42-34', 'warsh', 42, 34, 'وَالذِينَ يَجْتَنِبُونَ كَبَٰٓئِرَ ࡰ۬لِاثْمِ وَالْفَوَٰحِشَ وَإِذَا مَا غَضِبُواْ هُمْ يَغْفِرُونَ࣌', 'والذين يجتنبون كبئر ࡰلاثم والفوحش وإذا ما غضبوا هم يغفرون࣌', NULL, 487, 'local:warsh-text.json'),
  ('warsh-42-35', 'warsh', 42, 35, 'وَالذِينَ ࡰٜسْتَجَابُواْ لِرَبِّهِمْ وَأَقَامُواْ ࡲ۬لصَّلَوٰةَ وَأَمْرُهُمْ شُورٜىٰ بَيْنَهُمْ وَمِمَّا رَزَقْنَٰهُمْ يُنفِقُونَ࣌', 'والذين ࡰستجابوا لربهم وأقاموا ࡲلصلوة وأمرهم شورى بينهم ومما رزقنهم ينفقون࣌', NULL, 487, 'local:warsh-text.json'),
  ('warsh-42-36', 'warsh', 42, 36, 'وَالذِينَ إِذَآ أَصَابَهُمُ ࡲ۬لْبَغْيُ هُمْ يَنتَصِرُونَ࣌', 'والذين إذا أصابهم ࡲلبغي هم ينتصرون࣌', NULL, 487, 'local:warsh-text.json'),
  ('warsh-42-37', 'warsh', 42, 37, 'وَجَزَٰٓؤُاْ سَيِّئَةࣲ سَيِّئَةࣱ مِّثْلُهَا࣌ فَمَنْ عَفَا وَأَصْلَحَ فَأَجْرُهُۥ عَلَى ࡰ۬للَّهِ࣌ إِنَّهُۥ لَا يُحِبُّ ࡲ۬لظَّٰلِمِينَ࣌', 'وجزؤا سيئة سيئة مثلها࣌ فمن عفا وأصلح فأجره على ࡰلله࣌ إنه لا يحب ࡲلظلمين࣌', NULL, 487, 'local:warsh-text.json'),
  ('warsh-42-38', 'warsh', 42, 38, 'وَلَمَنِ ࡴٜنتَصَرَ بَعْدَ ظُلْمِهِۦ فَأُوْلَٰٓئِكَ مَا عَلَيْهِم مِّن سَبِيلٍ࣌', 'ولمن ࡴنتصر بعد ظلمه فأولئك ما عليهم من سبيل࣌', NULL, 487, 'local:warsh-text.json'),
  ('warsh-42-39', 'warsh', 42, 39, '۞ ࡴنَّمَا ࡰ۬لسَّبِيلُ عَلَى ࡰ۬لذِينَ يَظْلِمُونَ ࡰ۬لنَّاسَ وَيَبْغُونَ فِے ࡴ۬لَارْضِ بِغَيْرِ ࡴ۬لْحَقِّ࣌ أُوْلَٰٓئِكَ لَهُمْ عَذَابٌ ࡰلِيمࣱ࣌', 'ࡴنما ࡰلسبيل على ࡰلذين يظلمون ࡰلناس ويبغون فے ࡴلارض بغير ࡴلحق࣌ أولئك لهم عذاب ࡰليم࣌', NULL, 487, 'local:warsh-text.json'),
  ('warsh-42-40', 'warsh', 42, 40, 'وَلَمَن صَبَرَ وَغَفَرَ إِنَّ ذَٰلِكَ لَمِنْ عَزْمِ ࡴ۬لُامُورِ࣌', 'ولمن صبر وغفر إن ذلك لمن عزم ࡴلامور࣌', NULL, 487, 'local:warsh-text.json'),
  ('warsh-42-41', 'warsh', 42, 41, 'وَمَنْ يُّضْلِلِ ࡴ۬للَّهُ فَمَا لَهُۥ مِنْ وَّلِيࣲّ مِّنۢ بَعْدِهِۦ࣌ وَتَرَى ࡰ۬لظَّٰلِمِينَ لَمَّا رَأَوُاْ ࡲ۬لْعَذَابَ يَقُولُونَ هَلِ ࡴلَىٰ مَرَدࣲّ مِّن سَبِيلࣲ࣌', 'ومن يضلل ࡴلله فما له من ولي من بعده࣌ وترى ࡰلظلمين لما رأوا ࡲلعذاب يقولون هل ࡴلى مرد من سبيل࣌', NULL, 487, 'local:warsh-text.json'),
  ('warsh-42-42', 'warsh', 42, 42, 'وَتَرٜيٰهُمْ يُعْرَضُونَ عَلَيْهَا خَٰشِعِينَ࣌ مِنَ ࡰ۬لذُّلِّ يَنظُرُونَ مِن طَرْفٍ خَفِيࣲّ࣌ وَقَالَ ࡰ۬لذِينَ ءَامَنُوٓاْ إِنَّ ࡰ۬لْخَٰسِرِينَ ࡰ۬لذِينَ خَسِرُوٓاْ أَنفُسَهُمْ وَأَهْلِيهِمْ يَوْمَ ࡰ۬لْقِيَٰمَةِ࣌ أَلَآ إِنَّ ࡰ۬لظَّٰلِمِينَ فِے عَذَابࣲ مُّقِيمࣲ࣌', 'وتريهم يعرضون عليها خشعين࣌ من ࡰلذل ينظرون من طرف خفي࣌ وقال ࡰلذين ءامنوا إن ࡰلخسرين ࡰلذين خسروا أنفسهم وأهليهم يوم ࡰلقيمة࣌ ألا إن ࡰلظلمين فے عذاب مقيم࣌', NULL, 488, 'local:warsh-text.json'),
  ('warsh-42-43', 'warsh', 42, 43, 'وَمَا كَانَ لَهُم مِّنَ ࡰوْلِيَآءَ يَنصُرُونَهُم مِّن دُونِ ࡴ۬للَّهِ࣌ وَمَنْ يُّضْلِلِ ࡴ۬للَّهُ فَمَا لَهُۥ مِن سَبِيلٍ࣌', 'وما كان لهم من ࡰولياء ينصرونهم من دون ࡴلله࣌ ومن يضلل ࡴلله فما له من سبيل࣌', NULL, 488, 'local:warsh-text.json'),
  ('warsh-42-44', 'warsh', 42, 44, 'ࡴٜسْتَجِيبُواْ لِرَبِّكُم مِّن قَبْلِ أَنْ يَّاتِيَ يَوْمࣱ لَّا مَرَدَّ لَهُۥ مِنَ ࡰ۬للَّهِ࣌ مَا لَكُم مِّن مَّلْجَإࣲ يَوْمَئِذࣲ࣌ وَمَا لَكُم مِّن نَّكِيرࣲ࣌', 'ࡴستجيبوا لربكم من قبل أن ياتي يوم لا مرد له من ࡰلله࣌ ما لكم من ملجإ يومئذ࣌ وما لكم من نكير࣌', NULL, 488, 'local:warsh-text.json'),
  ('warsh-42-45', 'warsh', 42, 45, 'فَإِنَ ࡰعْرَضُواْ فَمَآ أَرْسَلْنَٰكَ عَلَيْهِمْ حَفِيظاً࣌ ࡴنْ عَلَيْكَ إِلَّا ࡰ۬لْبَلَٰغُ࣌ وَإِنَّآ إِذَآ أَذَقْنَا ࡰ۬لِانسَٰنَ مِنَّا رَحْمَةࣰ فَرِحَ بِهَا࣌ وَإِن تُصِبْهُمْ سَيِّئَةُۢ بِمَا قَدَّمَتَ ࡰيْدِيهِمْ فَإِنَّ ࡰ۬لِانسَٰنَ كَفُورࣱ࣌', 'فإن ࡰعرضوا فما أرسلنك عليهم حفيظا࣌ ࡴن عليك إلا ࡰلبلغ࣌ وإنا إذا أذقنا ࡰلانسن منا رحمة فرح بها࣌ وإن تصبهم سيئة بما قدمت ࡰيديهم فإن ࡰلانسن كفور࣌', NULL, 488, 'local:warsh-text.json'),
  ('warsh-42-46', 'warsh', 42, 46, 'لِّلهِ مُلْكُ ࡲ۬لسَّمَٰوَٰتِ وَالَارْضِ࣌ يَخْلُقُ مَا يَشَآءُ࣌ يَهَبُ لِمَنْ يَّشَآءُ ࡹِنَٰثاࣰ وَيَهَبُ لِمَنْ يَّشَآءُ ࡲ۬لذُّكُورَ', 'لله ملك ࡲلسموت والارض࣌ يخلق ما يشاء࣌ يهب لمن يشاء ࡹنثا ويهب لمن يشاء ࡲلذكور', NULL, 488, 'local:warsh-text.json'),
  ('warsh-42-47', 'warsh', 42, 47, 'أَوْ يُزَوِّجُهُمْ ذُكْرَاناࣰ وَإِنَٰثاࣰ وَيَجْعَلُ مَنْ يَّشَآءُ عَقِيماً࣌ ࡴنَّهُۥ عَلِيمࣱ قَدِيرࣱ࣌', 'أو يزوجهم ذكرانا وإنثا ويجعل من يشاء عقيما࣌ ࡴنه عليم قدير࣌', NULL, 488, 'local:warsh-text.json'),
  ('warsh-42-48', 'warsh', 42, 48, '۞ وَمَا كَانَ لِبَشَرٍ ࡰنْ يُّكَلِّمَهُ ࡲ۬للَّهُ إِلَّا وَحْياً ࡰوْ مِنْ وَّرَآءِےْ حِجَابٍ ࡰوْ يُرْسِلُ رَسُولاࣰ فَيُوحِے بِإِذْنِهِۦ مَا يَشَآءُ࣌ ࡹِنَّهُۥ عَلِيٌّ حَكِيمࣱ࣌', 'وما كان لبشر ࡰن يكلمه ࡲلله إلا وحيا ࡰو من وراءے حجاب ࡰو يرسل رسولا فيوحے بإذنه ما يشاء࣌ ࡹنه علي حكيم࣌', NULL, 488, 'local:warsh-text.json'),
  ('warsh-42-49', 'warsh', 42, 49, 'وَكَذَٰلِكَ أَوْحَيْنَآ إِلَيْكَ رُوحاࣰ مِّنَ ࡰمْرِنَا࣌ مَا كُنتَ تَدْرِے مَا ࡰ۬لْكِتَٰبُ وَلَا ࡰ۬لِايمَٰنُ࣌ وَلَٰكِن جَعَلْنَٰهُ نُوراࣰ نَّهْدِے بِهِۦ مَن نَّشَآءُ مِنْ عِبَادِنَا࣌ وَإِنَّكَ لَتَهْدِےٓ إِلَىٰ صِرَٰطࣲ مُّسْتَقِيمࣲ', 'وكذلك أوحينا إليك روحا من ࡰمرنا࣌ ما كنت تدرے ما ࡰلكتب ولا ࡰلايمن࣌ ولكن جعلنه نورا نهدے به من نشاء من عبادنا࣌ وإنك لتهدے إلى صرط مستقيم', NULL, 489, 'local:warsh-text.json'),
  ('warsh-42-50', 'warsh', 42, 50, 'صِرَٰطِ ࡴ۬للَّهِ ࡴ۬لذِے لَهُۥ مَا فِے ࡴ۬لسَّمَٰوَٰتِ وَمَا فِے ࡴ۬لَارْضِ࣌ أَلَآ إِلَى ࡰ۬للَّهِ تَصِيرُ ࡲ۬لُامُورُ࣌', 'صرط ࡴلله ࡴلذے له ما فے ࡴلسموت وما فے ࡴلارض࣌ ألا إلى ࡰلله تصير ࡲلامور࣌', NULL, 489, 'local:warsh-text.json'),
  ('warsh-43-1', 'warsh', 43, 1, 'حٜمِٓ࣌ وَالْكِتَٰبِ ࡴ۬لْمُبِينِ', 'حم࣌ والكتب ࡴلمبين', NULL, 489, 'local:warsh-text.json'),
  ('warsh-43-2', 'warsh', 43, 2, 'إِنَّا جَعَلْنَٰهُ قُرْءَٰناً عَرَبِيّاࣰ لَّعَلَّكُمْ تَعْقِلُونَ࣌', 'إنا جعلنه قرءنا عربيا لعلكم تعقلون࣌', NULL, 489, 'local:warsh-text.json'),
  ('warsh-43-3', 'warsh', 43, 3, 'وَإِنَّهُۥ فِےٓ أُمِّ ࡴ۬لْكِتَٰبِ لَدَيْنَا لَعَلِيٌّ حَكِيمٌ࣌', 'وإنه فے أم ࡴلكتب لدينا لعلي حكيم࣌', NULL, 489, 'local:warsh-text.json'),
  ('warsh-43-4', 'warsh', 43, 4, 'ࡰفَنَضْرِبُ عَنكُمُ ࡲ۬لذِّكْرَ صَفْحاً ࡴن كُنتُمْ قَوْماࣰ مُّسْرِفِينَ࣌', 'ࡰفنضرب عنكم ࡲلذكر صفحا ࡴن كنتم قوما مسرفين࣌', NULL, 489, 'local:warsh-text.json'),
  ('warsh-43-5', 'warsh', 43, 5, 'وَكَمَ ࡰرْسَلْنَا مِن نَّبِےٓءࣲ فِے ࡴ۬لَاوَّلِينَ࣌', 'وكم ࡰرسلنا من نبےء فے ࡴلاولين࣌', NULL, 489, 'local:warsh-text.json'),
  ('warsh-43-6', 'warsh', 43, 6, 'وَمَا يَاتِيهِم مِّن نَّبِےٓءٍ ࡴلَّا كَانُواْ بِهِۦ يَسْتَهْزِءُونَ࣌', 'وما ياتيهم من نبےء ࡴلا كانوا به يستهزءون࣌', NULL, 489, 'local:warsh-text.json'),
  ('warsh-43-7', 'warsh', 43, 7, 'فَأَهْلَكْنَآ أَشَدَّ مِنْهُم بَطْشاࣰ࣌ وَمَضٜىٰ مَثَلُ ࡲ۬لَاوَّلِينَ࣌', 'فأهلكنا أشد منهم بطشا࣌ ومضى مثل ࡲلاولين࣌', NULL, 489, 'local:warsh-text.json'),
  ('warsh-43-8', 'warsh', 43, 8, 'وَلَئِن سَأَلْتَهُم مَّنْ خَلَقَ ࡰ۬لسَّمَٰوَٰتِ وَالَارْضَ لَيَقُولُنَّ خَلَقَهُنَّ ࡰ۬لْعَزِيزُ ࡲ۬لْعَلِيمُ࣌', 'ولئن سألتهم من خلق ࡰلسموت والارض ليقولن خلقهن ࡰلعزيز ࡲلعليم࣌', NULL, 489, 'local:warsh-text.json'),
  ('warsh-43-9', 'warsh', 43, 9, 'ࡲ۬لذِے جَعَلَ لَكُمُ ࡲ۬لَارْضَ مِهَٰداࣰ وَجَعَلَ لَكُمْ فِيهَا سُبُلاࣰ لَّعَلَّكُمْ تَهْتَدُونَ࣌', 'ࡲلذے جعل لكم ࡲلارض مهدا وجعل لكم فيها سبلا لعلكم تهتدون࣌', NULL, 489, 'local:warsh-text.json'),
  ('warsh-43-10', 'warsh', 43, 10, '۞ وَالذِے نَزَّلَ مِنَ ࡰ۬لسَّمَآءِ مَآءَۢ بِقَدَرࣲ فَأَنشَرْنَا بِهِۦ بَلْدَةࣰ مَّيْتاࣰ࣌ كَذَٰلِكَ تُخْرَجُونَ࣌', 'والذے نزل من ࡰلسماء ماء بقدر فأنشرنا به بلدة ميتا࣌ كذلك تخرجون࣌', NULL, 490, 'local:warsh-text.json'),
  ('warsh-43-11', 'warsh', 43, 11, 'وَالذِے خَلَقَ ࡰ۬لَازْوَٰجَ كُلَّهَا وَجَعَلَ لَكُم مِّنَ ࡰ۬لْفُلْكِ وَالَانْعَٰمِ مَا تَرْكَبُونَ', 'والذے خلق ࡰلازوج كلها وجعل لكم من ࡰلفلك والانعم ما تركبون', NULL, 490, 'local:warsh-text.json'),
  ('warsh-43-12', 'warsh', 43, 12, 'لِتَسْتَوُۥاْ عَلَىٰ ظُهُورِهِۦ ثُمَّ تَذْكُرُواْ نِعْمَةَ رَبِّكُمُۥٓ إِذَا ࡰٜسْتَوَيْتُمْ عَلَيْهِ وَتَقُولُواْ سُبْحَٰنَ ࡰ۬لذِے سَخَّرَ لَنَا هَٰذَا وَمَا كُنَّا لَهُۥ مُقْرِنِينَ', 'لتستوا على ظهوره ثم تذكروا نعمة ربكم إذا ࡰستويتم عليه وتقولوا سبحن ࡰلذے سخر لنا هذا وما كنا له مقرنين', NULL, 490, 'local:warsh-text.json'),
  ('warsh-43-13', 'warsh', 43, 13, 'وَإِنَّآ إِلَىٰ رَبِّنَا لَمُنقَلِبُونَ࣌', 'وإنا إلى ربنا لمنقلبون࣌', NULL, 490, 'local:warsh-text.json'),
  ('warsh-43-14', 'warsh', 43, 14, 'وَجَعَلُواْ لَهُۥ مِنْ عِبَادِهِۦ جُزْءاً࣌ ࡴنَّ ࡰ۬لِانسَٰنَ لَكَفُورࣱ مُّبِينٌ࣌', 'وجعلوا له من عباده جزءا࣌ ࡴن ࡰلانسن لكفور مبين࣌', NULL, 490, 'local:warsh-text.json'),
  ('warsh-43-15', 'warsh', 43, 15, 'ࡰمِ ࡴٜتَّخَذَ مِمَّا يَخْلُقُ بَنَاتࣲ وَأَصْفٜيٰكُم بِالْبَنِينَ࣌', 'ࡰم ࡴتخذ مما يخلق بنات وأصفيكم بالبنين࣌', NULL, 490, 'local:warsh-text.json'),
  ('warsh-43-16', 'warsh', 43, 16, 'وَإِذَا بُشِّرَ أَحَدُهُم بِمَا ضَرَبَ لِلرَّحْمَٰنِ مَثَلاࣰ ظَلَّ وَجْهُهُۥ مُسْوَدّاࣰ وَهُوَ كَظِيمٌ࣌', 'وإذا بشر أحدهم بما ضرب للرحمن مثلا ظل وجهه مسودا وهو كظيم࣌', NULL, 490, 'local:warsh-text.json'),
  ('warsh-43-17', 'warsh', 43, 17, 'ࡰوَمَنْ يَّنشَؤُاْ فِے ࡴ۬لْحِلْيَةِ وَهُوَ فِے ࡴ۬لْخِصَامِ غَيْرُ مُبِينࣲ࣌', 'ࡰومن ينشؤا فے ࡴلحلية وهو فے ࡴلخصام غير مبين࣌', NULL, 490, 'local:warsh-text.json'),
  ('warsh-43-18', 'warsh', 43, 18, 'وَجَعَلُواْ ࡲ۬لْمَلَٰٓئِكَةَ ࡰ۬لذِينَ هُمْ عِندَ ࡰ۬لرَّحْمَٰنِ إِنَٰثاً࣌ ࡸَشْهِدُواْ خَلْقَهُمْ࣌ سَتُكْتَبُ شَهَٰدَتُهُمْ وَيُسْـَٔلُونَ࣌', 'وجعلوا ࡲلملئكة ࡰلذين هم عند ࡰلرحمن إنثا࣌ ࡸشهدوا خلقهم࣌ ستكتب شهدتهم ويسلون࣌', NULL, 490, 'local:warsh-text.json'),
  ('warsh-43-19', 'warsh', 43, 19, 'وَقَالُواْ لَوْ شَآءَ ࡰ۬لرَّحْمَٰنُ مَا عَبَدْنَٰهُم࣌ مَّا لَهُم بِذَٰلِكَ مِنْ عِلْمٍ࣌ ࡴنْ هُمُۥٓ إِلَّا يَخْرُصُونَ࣌', 'وقالوا لو شاء ࡰلرحمن ما عبدنهم࣌ ما لهم بذلك من علم࣌ ࡴن هم إلا يخرصون࣌', NULL, 490, 'local:warsh-text.json'),
  ('warsh-43-20', 'warsh', 43, 20, 'أَمَ اٰتَيْنَٰهُمْ كِتَٰباࣰ مِّن قَبْلِهِۦ فَهُم بِهِۦ مُسْتَمْسِكُونَ࣌', 'أم اتينهم كتبا من قبله فهم به مستمسكون࣌', NULL, 490, 'local:warsh-text.json'),
  ('warsh-43-21', 'warsh', 43, 21, 'بَلْ قَالُوٓاْ إِنَّا وَجَدْنَآ ءَابَآءَنَا عَلَىٰٓ أُمَّةࣲ وَإِنَّا عَلَىٰٓ ءَاثٜـٰرِهِم مُّهْتَدُونَ࣌', 'بل قالوا إنا وجدنا ءاباءنا على أمة وإنا على ءاثرهم مهتدون࣌', NULL, 490, 'local:warsh-text.json'),
  ('warsh-43-22', 'warsh', 43, 22, 'وَكَذَٰلِكَ مَآ أَرْسَلْنَا مِن قَبْلِكَ فِے قَرْيَةࣲ مِّن نَّذِيرٍ ࡴلَّا قَالَ مُتْرَفُوهَآ إِنَّا وَجَدْنَآ ءَابَآءَنَا عَلَىٰٓ أُمَّةࣲ وَإِنَّا عَلَىٰٓ ءَاثٜـٰرِهِم مُّقْتَدُونَ࣌', 'وكذلك ما أرسلنا من قبلك فے قرية من نذير ࡴلا قال مترفوها إنا وجدنا ءاباءنا على أمة وإنا على ءاثرهم مقتدون࣌', NULL, 491, 'local:warsh-text.json'),
  ('warsh-43-23', 'warsh', 43, 23, '۞ قُلَ ࡰوَلَوْ جِئْتُكُم بِأَهْدٜىٰ مِمَّا وَجَدتُّمْ عَلَيْهِ ءَابَآءَكُمْ࣌ قَالُوٓاْ إِنَّا بِمَآ أُرْسِلْتُم بِهِۦ كَٰفِرُونَ࣌', 'قل ࡰولو جئتكم بأهدى مما وجدتم عليه ءاباءكم࣌ قالوا إنا بما أرسلتم به كفرون࣌', NULL, 491, 'local:warsh-text.json'),
  ('warsh-43-24', 'warsh', 43, 24, 'فَانتَقَمْنَا مِنْهُمْ فَانظُرْ كَيْفَ كَانَ عَٰقِبَةُ ࡲ۬لْمُكَذِّبِينَ࣌', 'فانتقمنا منهم فانظر كيف كان عقبة ࡲلمكذبين࣌', NULL, 491, 'local:warsh-text.json'),
  ('warsh-43-25', 'warsh', 43, 25, 'وَإِذْ قَالَ إِبْرَٰهِيمُ لِأَبِيهِ وَقَوْمِهِۦٓ إِنَّنِے بَرَآءࣱ مِّمَّا تَعْبُدُونَ', 'وإذ قال إبرهيم لأبيه وقومه إننے براء مما تعبدون', NULL, 491, 'local:warsh-text.json'),
  ('warsh-43-26', 'warsh', 43, 26, 'إِلَّا ࡰ۬لذِے فَطَرَنِے فَإِنَّهُۥ سَيَهْدِينِ࣌', 'إلا ࡰلذے فطرنے فإنه سيهدين࣌', NULL, 491, 'local:warsh-text.json'),
  ('warsh-43-27', 'warsh', 43, 27, 'وَجَعَلَهَا كَلِمَةَۢ بَاقِيَةࣰ فِے عَقِبِهِۦ لَعَلَّهُمْ يَرْجِعُونَ࣌', 'وجعلها كلمة باقية فے عقبه لعلهم يرجعون࣌', NULL, 491, 'local:warsh-text.json'),
  ('warsh-43-28', 'warsh', 43, 28, 'بَلْ مَتَّعْتُ هَٰٓؤُلَآءِ وَءَابَآءَهُمْ حَتَّىٰ جَآءَهُمُ ࡲ۬لْحَقُّ وَرَسُولࣱ مُّبِينࣱ࣌', 'بل متعت هؤلاء وءاباءهم حتى جاءهم ࡲلحق ورسول مبين࣌', NULL, 491, 'local:warsh-text.json'),
  ('warsh-43-29', 'warsh', 43, 29, 'وَلَمَّا جَآءَهُمُ ࡲ۬لْحَقُّ قَالُواْ هَٰذَا سِحْرࣱ وَإِنَّا بِهِۦ كَٰفِرُونَ࣌', 'ولما جاءهم ࡲلحق قالوا هذا سحر وإنا به كفرون࣌', NULL, 491, 'local:warsh-text.json'),
  ('warsh-43-30', 'warsh', 43, 30, 'وَقَالُواْ لَوْلَا نُزِّلَ هَٰذَا ࡰ۬لْقُرْءَانُ عَلَىٰ رَجُلࣲ مِّنَ ࡰ۬لْقَرْيَتَيْنِ عَظِيمٍ࣌', 'وقالوا لولا نزل هذا ࡰلقرءان على رجل من ࡰلقريتين عظيم࣌', NULL, 491, 'local:warsh-text.json'),
  ('warsh-43-31', 'warsh', 43, 31, 'ࡰهُمْ يَقْسِمُونَ رَحْمَتَ رَبِّكَ࣌ نَحْنُ قَسَمْنَا بَيْنَهُم مَّعِيشَتَهُمْ فِے ࡴ۬لْحَيَوٰةِ ࡴ۬لدُّنْيٜا وَرَفَعْنَا بَعْضَهُمْ فَوْقَ بَعْضࣲ دَرَجَٰتࣲ لِّيَتَّخِذَ بَعْضُهُم بَعْضاࣰ سُخْرِيّاࣰ࣌ وَرَحْمَتُ رَبِّكَ خَيْرࣱ مِّمَّا يَجْمَعُونَ࣌', 'ࡰهم يقسمون رحمت ربك࣌ نحن قسمنا بينهم معيشتهم فے ࡴلحيوة ࡴلدنيا ورفعنا بعضهم فوق بعض درجت ليتخذ بعضهم بعضا سخريا࣌ ورحمت ربك خير مما يجمعون࣌', NULL, 491, 'local:warsh-text.json'),
  ('warsh-43-32', 'warsh', 43, 32, 'وَلَوْلَآ أَنْ يَّكُونَ ࡰ۬لنَّاسُ أُمَّةࣰ وَٰحِدَةࣰ لَّجَعَلْنَا لِمَنْ يَّكْفُرُ بِالرَّحْمَٰنِ لِبُيُوتِهِمْ سُقُفاࣰ مِّن فِضَّةࣲ وَمَعَارِجَ عَلَيْهَا يَظْهَرُونَ', 'ولولا أن يكون ࡰلناس أمة وحدة لجعلنا لمن يكفر بالرحمن لبيوتهم سقفا من فضة ومعارج عليها يظهرون', NULL, 491, 'local:warsh-text.json'),
  ('warsh-43-33', 'warsh', 43, 33, 'وَلِبُيُوتِهِمُۥٓ أَبْوَٰباࣰ وَسُرُراً عَلَيْهَا يَتَّكِـُٔونَ', 'ولبيوتهم أبوبا وسررا عليها يتكون', NULL, 492, 'local:warsh-text.json'),
  ('warsh-43-34', 'warsh', 43, 34, 'وَزُخْرُفاࣰ࣌ وَإِن كُلُّ ذَٰلِكَ لَمَا مَتَٰعُ ࡲ۬لْحَيَوٰةِ ࡴ۬لدُّنْيٜا࣌ وَالَاخِرَةُ عِندَ رَبِّكَ لِلْمُتَّقِينَ࣌', 'وزخرفا࣌ وإن كل ذلك لما متع ࡲلحيوة ࡴلدنيا࣌ والاخرة عند ربك للمتقين࣌', NULL, 492, 'local:warsh-text.json'),
  ('warsh-43-35', 'warsh', 43, 35, 'وَمَنْ يَّعْشُ عَن ذِكْرِ ࡴ۬لرَّحْمَٰنِ نُقَيِّضْ لَهُۥ شَيْطَٰناࣰ فَهُوَ لَهُۥ قَرِينࣱ࣌', 'ومن يعش عن ذكر ࡴلرحمن نقيض له شيطنا فهو له قرين࣌', NULL, 492, 'local:warsh-text.json'),
  ('warsh-43-36', 'warsh', 43, 36, 'وَإِنَّهُمْ لَيَصُدُّونَهُمْ عَنِ ࡴ۬لسَّبِيلِ وَيَحْسِبُونَ أَنَّهُم مُّهْتَدُونَ࣌', 'وإنهم ليصدونهم عن ࡴلسبيل ويحسبون أنهم مهتدون࣌', NULL, 492, 'local:warsh-text.json'),
  ('warsh-43-37', 'warsh', 43, 37, 'حَتَّىٰٓ إِذَا جَآءَٰنَا قَالَ يَٰلَيْتَ بَيْنِے وَبَيْنَكَ بُعْدَ ࡰ۬لْمَشْرِقَيْنِ࣌ فَبِيسَ ࡰ۬لْقَرِينُ࣌', 'حتى إذا جاءنا قال يليت بينے وبينك بعد ࡰلمشرقين࣌ فبيس ࡰلقرين࣌', NULL, 492, 'local:warsh-text.json'),
  ('warsh-43-38', 'warsh', 43, 38, 'وَلَنْ يَّنفَعَكُمُ ࡲ۬لْيَوْمَ إِذ ظَّلَمْتُمُۥٓ أَنَّكُمْ فِے ࡴ۬لْعَذَابِ مُشْتَرِكُونَ࣌', 'ولن ينفعكم ࡲليوم إذ ظلمتم أنكم فے ࡴلعذاب مشتركون࣌', NULL, 492, 'local:warsh-text.json'),
  ('warsh-43-39', 'warsh', 43, 39, 'أَفَأَنتَ تُسْمِعُ ࡲ۬لصُّمَّ أَوْ تَهْدِے ࡴ۬لْعُمْيَ وَمَن كَانَ فِے ضَلَٰلࣲ مُّبِينࣲ࣌', 'أفأنت تسمع ࡲلصم أو تهدے ࡴلعمي ومن كان فے ضلل مبين࣌', NULL, 492, 'local:warsh-text.json'),
  ('warsh-43-40', 'warsh', 43, 40, 'فَإِمَّا نَذْهَبَنَّ بِكَ فَإِنَّا مِنْهُم مُّنتَقِمُونَ', 'فإما نذهبن بك فإنا منهم منتقمون', NULL, 492, 'local:warsh-text.json'),
  ('warsh-43-41', 'warsh', 43, 41, 'أَوْ نُرِيَنَّكَ ࡰ۬لذِے وَعَدْنَٰهُمْ فَإِنَّا عَلَيْهِم مُّقْتَدِرُونَ࣌', 'أو نرينك ࡰلذے وعدنهم فإنا عليهم مقتدرون࣌', NULL, 492, 'local:warsh-text.json'),
  ('warsh-43-42', 'warsh', 43, 42, '۞ فَاسْتَمْسِكْ بِالذِےٓ أُوحِيَ إِلَيْكَ࣌ إِنَّكَ عَلَىٰ صِرَٰطࣲ مُّسْتَقِيمࣲ࣌', 'فاستمسك بالذے أوحي إليك࣌ إنك على صرط مستقيم࣌', NULL, 492, 'local:warsh-text.json'),
  ('warsh-43-43', 'warsh', 43, 43, 'وَإِنَّهُۥ لَذِكْرࣱ لَّكَ وَلِقَوْمِكَ࣌ وَسَوْفَ تُسْـَٔلُونَ࣌', 'وإنه لذكر لك ولقومك࣌ وسوف تسلون࣌', NULL, 492, 'local:warsh-text.json'),
  ('warsh-43-44', 'warsh', 43, 44, 'وَسْـَٔلْ مَنَ ࡰرْسَلْنَا مِن قَبْلِكَ مِن رُّسُلِنَآ࣌ أَجَعَلْنَا مِن دُونِ ࡴ۬لرَّحْمَٰنِ ءَالِهَةࣰ يُعْبَدُونَ࣌', 'وسل من ࡰرسلنا من قبلك من رسلنا࣌ أجعلنا من دون ࡴلرحمن ءالهة يعبدون࣌', NULL, 492, 'local:warsh-text.json'),
  ('warsh-43-45', 'warsh', 43, 45, 'وَلَقَدَ ࡰرْسَلْنَا مُوسٜىٰ بِـَٔايَٰتِنَآ إِلَىٰ فِرْعَوْنَ وَمَلَإِيْهِۦ فَقَالَ إِنِّے رَسُولُ رَبِّ ࡴ۬لْعَٰلَمِينَ࣌', 'ولقد ࡰرسلنا موسى بايتنا إلى فرعون وملإيه فقال إنے رسول رب ࡴلعلمين࣌', NULL, 492, 'local:warsh-text.json'),
  ('warsh-43-46', 'warsh', 43, 46, 'فَلَمَّا جَآءَهُم بِـَٔايَٰتِنَآ إِذَا هُم مِّنْهَا يَضْحَكُونَ࣌', 'فلما جاءهم بايتنا إذا هم منها يضحكون࣌', NULL, 492, 'local:warsh-text.json'),
  ('warsh-43-47', 'warsh', 43, 47, 'وَمَا نُرِيهِم مِّنَ اٰيَةٍ ࡴلَّا هِيَ أَكْبَرُ مِنُ ࡳخْتِهَا࣌ وَأَخَذْنَٰهُم بِالْعَذَابِ لَعَلَّهُمْ يَرْجِعُونَ࣌', 'وما نريهم من اية ࡴلا هي أكبر من ࡳختها࣌ وأخذنهم بالعذاب لعلهم يرجعون࣌', NULL, 493, 'local:warsh-text.json'),
  ('warsh-43-48', 'warsh', 43, 48, 'وَقَالُواْ يَٰٓأَيُّهَ ࡰ۬لسَّاحِرُ ࡲ࢈دْعُ لَنَا رَبَّكَ بِمَا عَهِدَ عِندَكَ إِنَّنَا لَمُهْتَدُونَ࣌', 'وقالوا يأيه ࡰلساحر ࡲ࢈دع لنا ربك بما عهد عندك إننا لمهتدون࣌', NULL, 493, 'local:warsh-text.json'),
  ('warsh-43-49', 'warsh', 43, 49, 'فَلَمَّا كَشَفْنَا عَنْهُمُ ࡲ۬لْعَذَابَ إِذَا هُمْ يَنكُثُونَ࣌', 'فلما كشفنا عنهم ࡲلعذاب إذا هم ينكثون࣌', NULL, 493, 'local:warsh-text.json'),
  ('warsh-43-50', 'warsh', 43, 50, 'وَنَادٜىٰ فِرْعَوْنُ فِے قَوْمِهِۦ قَالَ يَٰقَوْمِ أَلَيْسَ لِے مُلْكُ مِصْرَ وَهَٰذِهِ ࡴ۬لَانْهَٰرُ تَجْرِے مِن تَحْتِيَ࣌ أَفَلَا تُبْصِرُونَ࣌', 'ونادى فرعون فے قومه قال يقوم أليس لے ملك مصر وهذه ࡴلانهر تجرے من تحتي࣌ أفلا تبصرون࣌', NULL, 493, 'local:warsh-text.json'),
  ('warsh-43-51', 'warsh', 43, 51, 'أَمَ ࡰنَا خَيْرࣱ مِّنْ هَٰذَا ࡰ۬لذِے هُوَ مَهِينࣱ', 'أم ࡰنا خير من هذا ࡰلذے هو مهين', NULL, 493, 'local:warsh-text.json'),
  ('warsh-43-52', 'warsh', 43, 52, 'وَلَا يَكَادُ يُبِينُ࣌', 'ولا يكاد يبين࣌', NULL, 493, 'local:warsh-text.json'),
  ('warsh-43-53', 'warsh', 43, 53, 'فَلَوْلَآ أُلْقِيَ عَلَيْهِ أَسَٰوِرَةࣱ مِّن ذَهَبٍ ࡰوْ جَآءَ مَعَهُ ࡲ۬لْمَلَٰٓئِكَةُ مُقْتَرِنِينَ࣌', 'فلولا ألقي عليه أسورة من ذهب ࡰو جاء معه ࡲلملئكة مقترنين࣌', NULL, 493, 'local:warsh-text.json'),
  ('warsh-43-54', 'warsh', 43, 54, 'فَاسْتَخَفَّ قَوْمَهُۥ فَأَطَاعُوهُ࣌ إِنَّهُمْ كَانُواْ قَوْماࣰ فَٰسِقِينَ࣌', 'فاستخف قومه فأطاعوه࣌ إنهم كانوا قوما فسقين࣌', NULL, 493, 'local:warsh-text.json'),
  ('warsh-43-55', 'warsh', 43, 55, 'فَلَمَّآ ءَاسَفُونَا ࡰٜنتَقَمْنَا مِنْهُمْ فَأَغْرَقْنَٰهُمُۥٓ أَجْمَعِينَ', 'فلما ءاسفونا ࡰنتقمنا منهم فأغرقنهم أجمعين', NULL, 493, 'local:warsh-text.json'),
  ('warsh-43-56', 'warsh', 43, 56, 'فَجَعَلْنَٰهُمْ سَلَفاࣰ وَمَثَلاࣰ لِّلَاخِرِينَ࣌', 'فجعلنهم سلفا ومثلا للاخرين࣌', NULL, 493, 'local:warsh-text.json'),
  ('warsh-43-57', 'warsh', 43, 57, 'وَلَمَّا ضُرِبَ ࡰٜبْنُ مَرْيَمَ مَثَلاً ࡴذَا قَوْمُكَ مِنْهُ يَصُدُّونَ࣌', 'ولما ضرب ࡰبن مريم مثلا ࡴذا قومك منه يصدون࣌', NULL, 493, 'local:warsh-text.json'),
  ('warsh-43-58', 'warsh', 43, 58, 'وَقَالُوٓاْ ءَࡶٰلِهَتُنَا خَيْرٌ ࡰمْ هُوَ࣌ مَا ضَرَبُوهُ لَكَ إِلَّا جَدَلاَ࣌ بَلْ هُمْ قَوْمٌ خَصِمُونَ࣌', 'وقالوا ءࡶلهتنا خير ࡰم هو࣌ ما ضربوه لك إلا جدلا࣌ بل هم قوم خصمون࣌', NULL, 493, 'local:warsh-text.json'),
  ('warsh-43-59', 'warsh', 43, 59, 'إِنْ هُوَ إِلَّا عَبْدٌ ࡰنْعَمْنَا عَلَيْهِ وَجَعَلْنَٰهُ مَثَلاࣰ لِّبَنِےٓ إِسْرَآءِيلَ࣌', 'إن هو إلا عبد ࡰنعمنا عليه وجعلنه مثلا لبنے إسراءيل࣌', NULL, 493, 'local:warsh-text.json'),
  ('warsh-43-60', 'warsh', 43, 60, 'وَلَوْ نَشَآءُ لَجَعَلْنَا مِنكُم مَّلَٰٓئِكَةࣰ فِے ࡴ۬لَارْضِ يَخْلُفُونَ࣌', 'ولو نشاء لجعلنا منكم ملئكة فے ࡴلارض يخلفون࣌', NULL, 493, 'local:warsh-text.json'),
  ('warsh-43-61', 'warsh', 43, 61, 'وَإِنَّهُۥ لَعِلْمࣱ لِّلسَّاعَةِ فَلَا تَمْتَرُنَّ بِهَا࣌ وَاتَّبِعُونِ هَٰذَا صِرَٰطࣱ مُّسْتَقِيمࣱ࣌', 'وإنه لعلم للساعة فلا تمترن بها࣌ واتبعون هذا صرط مستقيم࣌', NULL, 494, 'local:warsh-text.json'),
  ('warsh-43-62', 'warsh', 43, 62, 'وَلَا يَصُدَّنَّكُمُ ࡲ۬لشَّيْطَٰنُ࣌ إِنَّهُۥ لَكُمْ عَدُوࣱّ مُّبِينࣱ࣌', 'ولا يصدنكم ࡲلشيطن࣌ إنه لكم عدو مبين࣌', NULL, 494, 'local:warsh-text.json'),
  ('warsh-43-63', 'warsh', 43, 63, '۞ وَلَمَّا جَآءَ عِيسٜىٰ بِالْبَيِّنَٰتِ قَالَ قَدْ جِئْتُكُم بِالْحِكْمَةِ وَلِأُبَيِّنَ لَكُم بَعْضَ ࡰ۬لذِے تَخْتَلِفُونَ فِيهِ࣌ فَاتَّقُواْ ࡲ۬للَّهَ وَأَطِيعُونِ࣌', 'ولما جاء عيسى بالبينت قال قد جئتكم بالحكمة ولأبين لكم بعض ࡰلذے تختلفون فيه࣌ فاتقوا ࡲلله وأطيعون࣌', NULL, 494, 'local:warsh-text.json'),
  ('warsh-43-64', 'warsh', 43, 64, 'إِنَّ ࡰ۬للَّهَ هُوَ رَبِّے وَرَبُّكُمْ فَاعْبُدُوهُ࣌ هَٰذَا صِرَٰطࣱ مُّسْتَقِيمࣱ࣌', 'إن ࡰلله هو ربے وربكم فاعبدوه࣌ هذا صرط مستقيم࣌', NULL, 494, 'local:warsh-text.json'),
  ('warsh-43-65', 'warsh', 43, 65, 'فَاخْتَلَفَ ࡰ۬لَاحْزَابُ مِنۢ بَيْنِهِمْ࣌ فَوَيْلࣱ لِّلذِينَ ظَلَمُواْ مِنْ عَذَابِ يَوْمٍ ࡰلِيمٍ࣌', 'فاختلف ࡰلاحزاب من بينهم࣌ فويل للذين ظلموا من عذاب يوم ࡰليم࣌', NULL, 494, 'local:warsh-text.json'),
  ('warsh-43-66', 'warsh', 43, 66, 'هَلْ يَنظُرُونَ إِلَّا ࡰ۬لسَّاعَةَ أَن تَاتِيَهُم بَغْتَةࣰ وَهُمْ لَا يَشْعُرُونَ࣌', 'هل ينظرون إلا ࡰلساعة أن تاتيهم بغتة وهم لا يشعرون࣌', NULL, 494, 'local:warsh-text.json'),
  ('warsh-43-67', 'warsh', 43, 67, 'ࡰ۬لَاخِلَّآءُ يَوْمَئِذِۢ بَعْضُهُمْ لِبَعْضٍ عَدُوٌّ ࡴلَّا ࡰ۬لْمُتَّقِينَ࣌', 'ࡰلاخلاء يومئذ بعضهم لبعض عدو ࡴلا ࡰلمتقين࣌', NULL, 494, 'local:warsh-text.json'),
  ('warsh-43-68', 'warsh', 43, 68, 'يَٰعِبَادِے لَا خَوْفٌ عَلَيْكُمُ ࡲ۬لْيَوْمَ وَلَآ أَنتُمْ تَحْزَنُونَ࣌', 'يعبادے لا خوف عليكم ࡲليوم ولا أنتم تحزنون࣌', NULL, 494, 'local:warsh-text.json'),
  ('warsh-43-69', 'warsh', 43, 69, 'ࡰ۬لذِينَ ءَامَنُواْ بِـَٔايَٰتِنَا وَكَانُواْ مُسْلِمِينَ', 'ࡰلذين ءامنوا بايتنا وكانوا مسلمين', NULL, 494, 'local:warsh-text.json'),
  ('warsh-43-70', 'warsh', 43, 70, 'ࡸَدْخُلُواْ ࡲ۬لْجَنَّةَ أَنتُمْ وَأَزْوَٰجُكُمْ تُحْبَرُونَ࣌', 'ࡸدخلوا ࡲلجنة أنتم وأزوجكم تحبرون࣌', NULL, 494, 'local:warsh-text.json'),
  ('warsh-43-71', 'warsh', 43, 71, 'يُطَافُ عَلَيْهِم بِصِحَافࣲ مِّن ذَهَبࣲ وَأَكْوَابࣲ࣌ وَفِيهَا مَا تَشْتَهِيهِ ࡴ۬لَانفُسُ وَتَلَذُّ ࡲ۬لَاعْيُنُ࣌ وَأَنتُمْ فِيهَا خَٰلِدُونَ࣌', 'يطاف عليهم بصحاف من ذهب وأكواب࣌ وفيها ما تشتهيه ࡴلانفس وتلذ ࡲلاعين࣌ وأنتم فيها خلدون࣌', NULL, 494, 'local:warsh-text.json'),
  ('warsh-43-72', 'warsh', 43, 72, 'وَتِلْكَ ࡰ۬لْجَنَّةُ ࡲ۬لتِےٓ أُورِثْتُمُوهَا بِمَا كُنتُمْ تَعْمَلُونَ࣌', 'وتلك ࡰلجنة ࡲلتے أورثتموها بما كنتم تعملون࣌', NULL, 494, 'local:warsh-text.json'),
  ('warsh-43-73', 'warsh', 43, 73, 'لَكُمْ فِيهَا فَٰكِهَةࣱ كَثِيرَةࣱ مِّنْهَا تَاكُلُونَ࣌', 'لكم فيها فكهة كثيرة منها تاكلون࣌', NULL, 494, 'local:warsh-text.json'),
  ('warsh-43-74', 'warsh', 43, 74, 'إِنَّ ࡰ۬لْمُجْرِمِينَ فِے عَذَابِ جَهَنَّمَ خَٰلِدُونَ࣌', 'إن ࡰلمجرمين فے عذاب جهنم خلدون࣌', NULL, 495, 'local:warsh-text.json'),
  ('warsh-43-75', 'warsh', 43, 75, 'لَا يُفَتَّرُ عَنْهُمْ وَهُمْ فِيهِ مُبْلِسُونَ࣌', 'لا يفتر عنهم وهم فيه مبلسون࣌', NULL, 495, 'local:warsh-text.json'),
  ('warsh-43-76', 'warsh', 43, 76, 'وَمَا ظَلَمْنَٰهُمْ࣌ وَلَٰكِن كَانُواْ هُمُ ࡲ۬لظَّٰلِمِينَ࣌', 'وما ظلمنهم࣌ ولكن كانوا هم ࡲلظلمين࣌', NULL, 495, 'local:warsh-text.json'),
  ('warsh-43-77', 'warsh', 43, 77, 'وَنَادَوْاْ يَٰمَٰلِكُ لِيَقْضِ عَلَيْنَا رَبُّكَ࣌ قَالَ إِنَّكُم مَّٰكِثُونَ࣌', 'ونادوا يملك ليقض علينا ربك࣌ قال إنكم مكثون࣌', NULL, 495, 'local:warsh-text.json'),
  ('warsh-43-78', 'warsh', 43, 78, 'لَقَدْ جِئْنَٰكُم بِالْحَقِّ࣌ وَلَٰكِنَّ أَكْثَرَكُمْ لِلْحَقِّ كَٰرِهُونَ࣌', 'لقد جئنكم بالحق࣌ ولكن أكثركم للحق كرهون࣌', NULL, 495, 'local:warsh-text.json'),
  ('warsh-43-79', 'warsh', 43, 79, 'أَمَ ࡰبْرَمُوٓاْ أَمْراࣰ فَإِنَّا مُبْرِمُونَ࣌', 'أم ࡰبرموا أمرا فإنا مبرمون࣌', NULL, 495, 'local:warsh-text.json'),
  ('warsh-43-80', 'warsh', 43, 80, 'أَمْ يَحْسِبُونَ أَنَّا لَا نَسْمَعُ سِرَّهُمْ وَنَجْوٜيٰهُم بَلٜىٰ࣌ وَرُسُلُنَا لَدَيْهِمْ يَكْتُبُونَ࣌', 'أم يحسبون أنا لا نسمع سرهم ونجويهم بلى࣌ ورسلنا لديهم يكتبون࣌', NULL, 495, 'local:warsh-text.json'),
  ('warsh-43-81', 'warsh', 43, 81, 'قُلِ ࡴن كَانَ لِلرَّحْمَٰنِ وَلَدࣱ࣌ فَأَنَآ أَوَّلُ ࡲ۬لْعَٰبِدِينَ࣌', 'قل ࡴن كان للرحمن ولد࣌ فأنا أول ࡲلعبدين࣌', NULL, 495, 'local:warsh-text.json'),
  ('warsh-43-82', 'warsh', 43, 82, 'سُبْحَٰنَ رَبِّ ࡴ۬لسَّمَٰوَٰتِ وَالَارْضِ رَبِّ ࡴ۬لْعَرْشِ عَمَّا يَصِفُونَ࣌', 'سبحن رب ࡴلسموت والارض رب ࡴلعرش عما يصفون࣌', NULL, 495, 'local:warsh-text.json'),
  ('warsh-43-83', 'warsh', 43, 83, 'فَذَرْهُمْ يَخُوضُواْ وَيَلْعَبُواْ حَتَّىٰ يُلَٰقُواْ يَوْمَهُمُ ࡲ۬لذِے يُوعَدُونَ࣌', 'فذرهم يخوضوا ويلعبوا حتى يلقوا يومهم ࡲلذے يوعدون࣌', NULL, 495, 'local:warsh-text.json'),
  ('warsh-43-84', 'warsh', 43, 84, 'وَهُوَ ࡰ۬لذِے فِے ࡴ۬لسَّمَآءِ الَٰهࣱ وَفِے ࡴ۬لَارْضِ إِلَٰهࣱ࣌ وَهُوَ ࡰ۬لْحَكِيمُ ࡲ۬لْعَلِيمُ࣌', 'وهو ࡰلذے فے ࡴلسماء اله وفے ࡴلارض إله࣌ وهو ࡰلحكيم ࡲلعليم࣌', NULL, 495, 'local:warsh-text.json'),
  ('warsh-43-85', 'warsh', 43, 85, '۞ وَتَبَٰرَكَ ࡰ۬لذِے لَهُۥ مُلْكُ ࡲ۬لسَّمَٰوَٰتِ وَالَارْضِ وَمَا بَيْنَهُمَا࣌ وَعِندَهُۥ عِلْمُ ࡲ۬لسَّاعَةِ࣌ وَإِلَيْهِ تُرْجَعُونَ࣌', 'وتبرك ࡰلذے له ملك ࡲلسموت والارض وما بينهما࣌ وعنده علم ࡲلساعة࣌ وإليه ترجعون࣌', NULL, 495, 'local:warsh-text.json'),
  ('warsh-43-86', 'warsh', 43, 86, 'وَلَا يَمْلِكُ ࡲ۬لذِينَ يَدْعُونَ مِن دُونِهِ ࡴ۬لشَّفَٰعَةَ إِلَّا مَن شَهِدَ بِالْحَقِّ وَهُمْ يَعْلَمُونَ࣌', 'ولا يملك ࡲلذين يدعون من دونه ࡴلشفعة إلا من شهد بالحق وهم يعلمون࣌', NULL, 495, 'local:warsh-text.json'),
  ('warsh-43-87', 'warsh', 43, 87, 'وَلَئِن سَأَلْتَهُم مَّنْ خَلَقَهُمْ لَيَقُولُنَّ ࡰ۬للَّهُ࣌ فَأَنّٜىٰ يُوفَكُونَ࣌', 'ولئن سألتهم من خلقهم ليقولن ࡰلله࣌ فأنى يوفكون࣌', NULL, 495, 'local:warsh-text.json'),
  ('warsh-43-88', 'warsh', 43, 88, 'وَقِيلَهُۥ يَٰرَبِّ إِنَّ هَٰٓؤُلَآءِ قَوْمࣱ لَّا يُومِنُونَ࣌', 'وقيله يرب إن هؤلاء قوم لا يومنون࣌', NULL, 495, 'local:warsh-text.json'),
  ('warsh-43-89', 'warsh', 43, 89, 'فَاصْفَحْ عَنْهُمْ وَقُلْ سَلَٰمࣱ࣌ فَسَوْفَ تَعْلَمُونَ࣌', 'فاصفح عنهم وقل سلم࣌ فسوف تعلمون࣌', NULL, 495, 'local:warsh-text.json'),
  ('warsh-44-1', 'warsh', 44, 1, 'حٜمِٓ࣌ وَالْكِتَٰبِ ࡴ۬لْمُبِينِ', 'حم࣌ والكتب ࡴلمبين', NULL, 496, 'local:warsh-text.json'),
  ('warsh-44-2', 'warsh', 44, 2, 'إِنَّآ أَنزَلْنَٰهُ فِے لَيْلَةࣲ مُّبَٰرَكَةٍ ࡴنَّا كُنَّا مُنذِرِينَ࣌', 'إنا أنزلنه فے ليلة مبركة ࡴنا كنا منذرين࣌', NULL, 496, 'local:warsh-text.json')
insert into public.ayahs (id, riwayah, surah_number, ayah_number, text, simple_text, juz, page, source) values
  ('warsh-44-3', 'warsh', 44, 3, 'فِيهَا يُفْرَقُ كُلُّ أَمْرٍ حَكِيمٍ', 'فيها يفرق كل أمر حكيم', NULL, 496, 'local:warsh-text.json'),
  ('warsh-44-4', 'warsh', 44, 4, 'ࡰمْراࣰ مِّنْ عِندِنَآ࣌ إِنَّا كُنَّا مُرْسِلِينَ', 'ࡰمرا من عندنا࣌ إنا كنا مرسلين', NULL, 496, 'local:warsh-text.json'),
  ('warsh-44-5', 'warsh', 44, 5, 'رَحْمَةࣰ مِّن رَّبِّكَ࣌ إِنَّهُۥ هُوَ ࡰ۬لسَّمِيعُ ࡲ۬لْعَلِيمُ࣌', 'رحمة من ربك࣌ إنه هو ࡰلسميع ࡲلعليم࣌', NULL, 496, 'local:warsh-text.json'),
  ('warsh-44-6', 'warsh', 44, 6, 'رَبُّ ࡲ۬لسَّمَٰوَٰتِ وَالَارْضِ وَمَا بَيْنَهُمَآ إِن كُنتُم مُّوقِنِينَ࣌', 'رب ࡲلسموت والارض وما بينهما إن كنتم موقنين࣌', NULL, 496, 'local:warsh-text.json'),
  ('warsh-44-7', 'warsh', 44, 7, 'لَآ إِلَٰهَ إِلَّا هُوَ࣌ يُحْيِۦ وَيُمِيتُ࣌ رَبُّكُمْ وَرَبُّ ءَابَآئِكُمُ ࡲ۬لَاوَّلِينَ࣌', 'لا إله إلا هو࣌ يحي ويميت࣌ ربكم ورب ءابائكم ࡲلاولين࣌', NULL, 496, 'local:warsh-text.json'),
  ('warsh-44-8', 'warsh', 44, 8, 'بَلْ هُمْ فِے شَكࣲّ يَلْعَبُونَ࣌', 'بل هم فے شك يلعبون࣌', NULL, 496, 'local:warsh-text.json'),
  ('warsh-44-9', 'warsh', 44, 9, 'فَارْتَقِبْ يَوْمَ تَاتِے ࡴ۬لسَّمَآءُ بِدُخَانࣲ مُّبِينࣲ', 'فارتقب يوم تاتے ࡴلسماء بدخان مبين', NULL, 496, 'local:warsh-text.json'),
  ('warsh-44-10', 'warsh', 44, 10, 'يَغْشَى ࡰ۬لنَّاسَ࣌ هَٰذَا عَذَابٌ ࡰلِيمࣱ࣌', 'يغشى ࡰلناس࣌ هذا عذاب ࡰليم࣌', NULL, 496, 'local:warsh-text.json'),
  ('warsh-44-11', 'warsh', 44, 11, 'رَّبَّنَا ࡰٜكْشِفْ عَنَّا ࡰ۬لْعَذَابَ إِنَّا مُومِنُونَ࣌', 'ربنا ࡰكشف عنا ࡰلعذاب إنا مومنون࣌', NULL, 496, 'local:warsh-text.json'),
  ('warsh-44-12', 'warsh', 44, 12, 'أَنّٜىٰ لَهُمُ ࡲ۬لذِّكْرٜىٰ وَقَدْ جَآءَهُمْ رَسُولࣱ مُّبِينࣱ', 'أنى لهم ࡲلذكرى وقد جاءهم رسول مبين', NULL, 496, 'local:warsh-text.json'),
  ('warsh-44-13', 'warsh', 44, 13, 'ثُمَّ تَوَلَّوْاْ عَنْهُ وَقَالُواْ مُعَلَّمࣱ مَّجْنُونٌ࣌', 'ثم تولوا عنه وقالوا معلم مجنون࣌', NULL, 496, 'local:warsh-text.json'),
  ('warsh-44-14', 'warsh', 44, 14, 'ࡴنَّا كَاشِفُواْ ࡲ۬لْعَذَابِ قَلِيلاً࣌ ࡴنَّكُمْ عَآئِدُونَ࣌', 'ࡴنا كاشفوا ࡲلعذاب قليلا࣌ ࡴنكم عائدون࣌', NULL, 496, 'local:warsh-text.json'),
  ('warsh-44-15', 'warsh', 44, 15, 'يَوْمَ نَبْطِشُ ࡲ۬لْبَطْشَةَ ࡰ۬لْكُبْرٜىٰٓ࣌ إِنَّا مُنتَقِمُونَ࣌', 'يوم نبطش ࡲلبطشة ࡰلكبرى࣌ إنا منتقمون࣌', NULL, 496, 'local:warsh-text.json'),
  ('warsh-44-16', 'warsh', 44, 16, 'وَلَقَدْ فَتَنَّا قَبْلَهُمْ قَوْمَ فِرْعَوْنَ وَجَآءَهُمْ رَسُولࣱ كَرِيمٌ', 'ولقد فتنا قبلهم قوم فرعون وجاءهم رسول كريم', NULL, 496, 'local:warsh-text.json'),
  ('warsh-44-17', 'warsh', 44, 17, 'ࡰنَ ࡰدُّوٓاْ إِلَيَّ عِبَادَ ࡰ۬للَّهِ إِنِّے لَكُمْ رَسُولٌ ࡰمِينࣱ', 'ࡰن ࡰدوا إلي عباد ࡰلله إنے لكم رسول ࡰمين', NULL, 496, 'local:warsh-text.json'),
  ('warsh-44-18', 'warsh', 44, 18, 'وَأَن لَّا تَعْلُواْ عَلَى ࡰ۬للَّهِ إِنِّيَ ءَاتِيكُم بِسُلْطَٰنࣲ مُّبِينࣲ', 'وأن لا تعلوا على ࡰلله إني ءاتيكم بسلطن مبين', NULL, 497, 'local:warsh-text.json'),
  ('warsh-44-19', 'warsh', 44, 19, 'وَإِنِّے عُذْتُ بِرَبِّے وَرَبِّكُمُۥٓ أَن تَرْجُمُونِۦ', 'وإنے عذت بربے وربكم أن ترجمون', NULL, 497, 'local:warsh-text.json'),
  ('warsh-44-20', 'warsh', 44, 20, 'وَإِن لَّمْ تُومِنُواْ لِيَ فَاعْتَزِلُونِۦ࣌', 'وإن لم تومنوا لي فاعتزلون࣌', NULL, 497, 'local:warsh-text.json'),
  ('warsh-44-21', 'warsh', 44, 21, 'فَدَعَا رَبَّهُۥٓ أَنَّ هَٰٓؤُلَآءِ قَوْمࣱ مُّجْرِمُونَ࣌', 'فدعا ربه أن هؤلاء قوم مجرمون࣌', NULL, 497, 'local:warsh-text.json'),
  ('warsh-44-22', 'warsh', 44, 22, 'فَاسْرِ بِعِبَادِے لَيْلاً ࡴنَّكُم مُّتَّبَعُونَ', 'فاسر بعبادے ليلا ࡴنكم متبعون', NULL, 497, 'local:warsh-text.json'),
  ('warsh-44-23', 'warsh', 44, 23, 'وَاتْرُكِ ࡴ۬لْبَحْرَ رَهْواً࣌ ࡴنَّهُمْ جُندࣱ مُّغْرَقُونَ࣌', 'واترك ࡴلبحر رهوا࣌ ࡴنهم جند مغرقون࣌', NULL, 497, 'local:warsh-text.json'),
  ('warsh-44-24', 'warsh', 44, 24, '۞ كَمْ تَرَكُواْ مِن جَنَّٰتࣲ وَعُيُونࣲ', 'كم تركوا من جنت وعيون', NULL, 497, 'local:warsh-text.json'),
  ('warsh-44-25', 'warsh', 44, 25, 'وَزُرُوعࣲ وَمَقَامࣲ كَرِيمࣲ', 'وزروع ومقام كريم', NULL, 497, 'local:warsh-text.json'),
  ('warsh-44-26', 'warsh', 44, 26, 'وَنَعْمَةࣲ كَانُواْ فِيهَا فَٰكِهِينَ࣌', 'ونعمة كانوا فيها فكهين࣌', NULL, 497, 'local:warsh-text.json'),
  ('warsh-44-27', 'warsh', 44, 27, 'كَذَٰلِكَ࣌ وَأَوْرَثْنَٰهَا قَوْماً اٰخَرِينَ࣌', 'كذلك࣌ وأورثنها قوما اخرين࣌', NULL, 497, 'local:warsh-text.json'),
  ('warsh-44-28', 'warsh', 44, 28, 'فَمَا بَكَتْ عَلَيْهِمُ ࡲ۬لسَّمَآءُ وَالَارْضُ وَمَا كَانُواْ مُنظَرِينَ࣌', 'فما بكت عليهم ࡲلسماء والارض وما كانوا منظرين࣌', NULL, 497, 'local:warsh-text.json'),
  ('warsh-44-29', 'warsh', 44, 29, 'وَلَقَدْ نَجَّيْنَا بَنِےٓ إِسْرَآءِيلَ مِنَ ࡰ۬لْعَذَابِ ࡴ۬لْمُهِينِ', 'ولقد نجينا بنے إسراءيل من ࡰلعذاب ࡴلمهين', NULL, 497, 'local:warsh-text.json'),
  ('warsh-44-30', 'warsh', 44, 30, 'مِن فِرْعَوْنَ࣌ إِنَّهُۥ كَانَ عَالِياࣰ مِّنَ ࡰ۬لْمُسْرِفِينَ࣌', 'من فرعون࣌ إنه كان عاليا من ࡰلمسرفين࣌', NULL, 497, 'local:warsh-text.json'),
  ('warsh-44-31', 'warsh', 44, 31, 'وَلَقَدِ ࡴٜخْتَرْنَٰهُمْ عَلَىٰ عِلْمٍ عَلَى ࡰ۬لْعَٰلَمِينَ', 'ولقد ࡴخترنهم على علم على ࡰلعلمين', NULL, 497, 'local:warsh-text.json'),
  ('warsh-44-32', 'warsh', 44, 32, 'وَءَاتَيْنَٰهُم مِّنَ ࡰ۬لَايَٰتِ مَا فِيهِ بَلَٰٓؤࣱاْ مُّبِينٌ࣌', 'وءاتينهم من ࡰلايت ما فيه بلؤا مبين࣌', NULL, 497, 'local:warsh-text.json'),
  ('warsh-44-33', 'warsh', 44, 33, 'ࡴنَّ هَٰٓؤُلَآءِ لَيَقُولُونَ إِنْ هِيَ إِلَّا مَوْتَتُنَا ࡰ۬لُاولٜىٰ وَمَا نَحْنُ بِمُنشَرِينَ', 'ࡴن هؤلاء ليقولون إن هي إلا موتتنا ࡰلاولى وما نحن بمنشرين', NULL, 497, 'local:warsh-text.json'),
  ('warsh-44-34', 'warsh', 44, 34, 'فَاتُواْ بِـَٔابَآئِنَآ إِن كُنتُمْ صَٰدِقِينَ࣌', 'فاتوا بابائنا إن كنتم صدقين࣌', NULL, 497, 'local:warsh-text.json'),
  ('warsh-44-35', 'warsh', 44, 35, 'أَهُمْ خَيْرٌ ࡰمْ قَوْمُ تُبَّعࣲ࣌ وَالذِينَ مِن قَبْلِهِمُۥٓ أَهْلَكْنَٰهُمُۥٓ࣌ إِنَّهُمْ كَانُواْ مُجْرِمِينَ࣌', 'أهم خير ࡰم قوم تبع࣌ والذين من قبلهم أهلكنهم࣌ إنهم كانوا مجرمين࣌', NULL, 497, 'local:warsh-text.json'),
  ('warsh-44-36', 'warsh', 44, 36, 'وَمَا خَلَقْنَا ࡰ۬لسَّمَٰوَٰتِ وَالَارْضَ وَمَا بَيْنَهُمَا لَٰعِبِينَ࣌', 'وما خلقنا ࡰلسموت والارض وما بينهما لعبين࣌', NULL, 497, 'local:warsh-text.json'),
  ('warsh-44-37', 'warsh', 44, 37, 'مَا خَلَقْنَٰهُمَآ إِلَّا بِالْحَقِّ࣌ وَلَٰكِنَّ أَكْثَرَهُمْ لَا يَعْلَمُونَ࣌', 'ما خلقنهما إلا بالحق࣌ ولكن أكثرهم لا يعلمون࣌', NULL, 497, 'local:warsh-text.json'),
  ('warsh-44-38', 'warsh', 44, 38, 'إِنَّ يَوْمَ ࡰ۬لْفَصْلِ مِيقَٰتُهُمُۥٓ أَجْمَعِينَ', 'إن يوم ࡰلفصل ميقتهم أجمعين', NULL, 498, 'local:warsh-text.json'),
  ('warsh-44-39', 'warsh', 44, 39, 'يَوْمَ لَا يُغْنِے مَوْلىً عَن مَّوْلىࣰ شَيْـٔاࣰ وَلَا هُمْ يُنصَرُونَ', 'يوم لا يغنے مولى عن مولى شيا ولا هم ينصرون', NULL, 498, 'local:warsh-text.json'),
  ('warsh-44-40', 'warsh', 44, 40, 'إِلَّا مَن رَّحِمَ ࡰ۬للَّهُ࣌ إِنَّهُۥ هُوَ ࡰ۬لْعَزِيزُ ࡲ۬لرَّحِيمُ࣌', 'إلا من رحم ࡰلله࣌ إنه هو ࡰلعزيز ࡲلرحيم࣌', NULL, 498, 'local:warsh-text.json'),
  ('warsh-44-41', 'warsh', 44, 41, 'إِنَّ شَجَرَتَ ࡰ۬لزَّقُّومِ طَعَامُ ࡲ۬لَاثِيمِ', 'إن شجرت ࡰلزقوم طعام ࡲلاثيم', NULL, 498, 'local:warsh-text.json'),
  ('warsh-44-42', 'warsh', 44, 42, 'كَالْمُهْلِ تَغْلِے فِے ࡴ۬لْبُطُونِ', 'كالمهل تغلے فے ࡴلبطون', NULL, 498, 'local:warsh-text.json'),
  ('warsh-44-43', 'warsh', 44, 43, 'كَغَلْيِ ࡴ۬لْحَمِيمِ࣌', 'كغلي ࡴلحميم࣌', NULL, 498, 'local:warsh-text.json'),
  ('warsh-44-44', 'warsh', 44, 44, 'خُذُوهُ فَاعْتُلُوهُ إِلَىٰ سَوَآءِ ࡴ۬لْجَحِيمِ', 'خذوه فاعتلوه إلى سواء ࡴلجحيم', NULL, 498, 'local:warsh-text.json'),
  ('warsh-44-45', 'warsh', 44, 45, 'ثُمَّ صُبُّواْ فَوْقَ رَأْسِهِۦ مِنْ عَذَابِ ࡴ۬لْحَمِيمِ', 'ثم صبوا فوق رأسه من عذاب ࡴلحميم', NULL, 498, 'local:warsh-text.json'),
  ('warsh-44-46', 'warsh', 44, 46, 'ذُقِ࣌ ࡴنَّكَ أَنتَ ࡰ۬لْعَزِيزُ ࡲ۬لْكَرِيمُ࣌', 'ذق࣌ ࡴنك أنت ࡰلعزيز ࡲلكريم࣌', NULL, 498, 'local:warsh-text.json'),
  ('warsh-44-47', 'warsh', 44, 47, 'إِنَّ هَٰذَا مَا كُنتُم بِهِۦ تَمْتَرُونَ࣌', 'إن هذا ما كنتم به تمترون࣌', NULL, 498, 'local:warsh-text.json'),
  ('warsh-44-48', 'warsh', 44, 48, 'إِنَّ ࡰ۬لْمُتَّقِينَ فِے مُقَامٍ ࡰمِينࣲ', 'إن ࡰلمتقين فے مقام ࡰمين', NULL, 498, 'local:warsh-text.json'),
  ('warsh-44-49', 'warsh', 44, 49, 'فِے جَنَّٰتࣲ وَعُيُونࣲ', 'فے جنت وعيون', NULL, 498, 'local:warsh-text.json'),
  ('warsh-44-50', 'warsh', 44, 50, 'يَلْبَسُونَ مِن سُندُسࣲ وَإِسْتَبْرَقࣲ مُّتَقَٰبِلِينَ࣌', 'يلبسون من سندس وإستبرق متقبلين࣌', NULL, 498, 'local:warsh-text.json'),
  ('warsh-44-51', 'warsh', 44, 51, 'كَذَٰلِكَ࣌ وَزَوَّجْنَٰهُم بِحُورٍ عِينࣲ࣌', 'كذلك࣌ وزوجنهم بحور عين࣌', NULL, 498, 'local:warsh-text.json'),
  ('warsh-44-52', 'warsh', 44, 52, 'يَدْعُونَ فِيهَا بِكُلِّ فَٰكِهَةٍ اٰمِنِينَ࣌', 'يدعون فيها بكل فكهة امنين࣌', NULL, 498, 'local:warsh-text.json'),
  ('warsh-44-53', 'warsh', 44, 53, 'لَا يَذُوقُونَ فِيهَا ࡰ۬لْمَوْتَ࣌ إِلَّا ࡰ۬لْمَوْتَةَ ࡰ۬لُاولٜىٰ࣌ وَوَقٜيٰهُمْ عَذَابَ ࡰ۬لْجَحِيمِ', 'لا يذوقون فيها ࡰلموت࣌ إلا ࡰلموتة ࡰلاولى࣌ ووقيهم عذاب ࡰلجحيم', NULL, 498, 'local:warsh-text.json'),
  ('warsh-44-54', 'warsh', 44, 54, 'فَضْلاࣰ مِّن رَّبِّكَ࣌ ذَٰلِكَ هُوَ ࡰ۬لْفَوْزُ ࡲ۬لْعَظِيمُ࣌', 'فضلا من ربك࣌ ذلك هو ࡰلفوز ࡲلعظيم࣌', NULL, 498, 'local:warsh-text.json'),
  ('warsh-44-55', 'warsh', 44, 55, 'فَإِنَّمَا يَسَّرْنَٰهُ بِلِسَانِكَ لَعَلَّهُمْ يَتَذَكَّرُونَ࣌', 'فإنما يسرنه بلسانك لعلهم يتذكرون࣌', NULL, 498, 'local:warsh-text.json'),
  ('warsh-44-56', 'warsh', 44, 56, 'فَارْتَقِبِ࣌ ࡴنَّهُم مُّرْتَقِبُونَ࣌', 'فارتقب࣌ ࡴنهم مرتقبون࣌', NULL, 498, 'local:warsh-text.json'),
  ('warsh-45-1', 'warsh', 45, 1, 'حٜمِٓ࣌ تَنزِيلُ ࡲ۬لْكِتَٰبِ مِنَ ࡰ۬للَّهِ ࡴ۬لْعَزِيزِ ࡴ۬لْحَكِيمِ࣌', 'حم࣌ تنزيل ࡲلكتب من ࡰلله ࡴلعزيز ࡴلحكيم࣌', NULL, 499, 'local:warsh-text.json'),
  ('warsh-45-2', 'warsh', 45, 2, 'إِنَّ فِے ࡴ۬لسَّمَٰوَٰتِ وَالَارْضِ لَأٓيَٰتࣲ لِّلْمُومِنِينَ࣌', 'إن فے ࡴلسموت والارض لأيت للمومنين࣌', NULL, 499, 'local:warsh-text.json'),
  ('warsh-45-3', 'warsh', 45, 3, 'وَفِے خَلْقِكُمْ وَمَا يَبُثُّ مِن دَآبَّةٍ اٰيَٰتࣱ لِّقَوْمࣲ يُوقِنُونَ', 'وفے خلقكم وما يبث من دابة ايت لقوم يوقنون', NULL, 499, 'local:warsh-text.json'),
  ('warsh-45-4', 'warsh', 45, 4, 'وَاخْتِلَٰفِ ࡴ۬ليْلِ وَالنَّهٜارِ وَمَآ أَنزَلَ ࡰ۬للَّهُ مِنَ ࡰ۬لسَّمَآءِ مِن رِّزْقࣲ فَأَحْيٜا بِهِ ࡴ۬لَارْضَ بَعْدَ مَوْتِهَا وَتَصْرِيفِ ࡴ۬لرِّيَٰحِ ءَايَٰتࣱ لِّقَوْمࣲ يَعْقِلُونَ࣌', 'واختلف ࡴليل والنهار وما أنزل ࡰلله من ࡰلسماء من رزق فأحيا به ࡴلارض بعد موتها وتصريف ࡴلريح ءايت لقوم يعقلون࣌', NULL, 499, 'local:warsh-text.json'),
  ('warsh-45-5', 'warsh', 45, 5, 'تِلْكَ ءَايَٰتُ ࡲ۬للَّهِ نَتْلُوهَا عَلَيْكَ بِالْحَقِّ࣌ فَبِأَيِّ حَدِيثِۢ بَعْدَ ࡰ۬للَّهِ وَءَايَٰتِهِۦ يُومِنُونَ࣌', 'تلك ءايت ࡲلله نتلوها عليك بالحق࣌ فبأي حديث بعد ࡰلله وءايته يومنون࣌', NULL, 499, 'local:warsh-text.json'),
  ('warsh-45-6', 'warsh', 45, 6, 'وَيْلࣱ لِّكُلِّ أَفَّاكٍ ࡰثِيمࣲ', 'ويل لكل أفاك ࡰثيم', NULL, 499, 'local:warsh-text.json'),
  ('warsh-45-7', 'warsh', 45, 7, 'يَسْمَعُ ءَايَٰتِ ࡴ۬للَّهِ تُتْلٜىٰ عَلَيْهِ ثُمَّ يُصِرُّ مُسْتَكْبِراࣰ كَأَن لَّمْ يَسْمَعْهَا࣌ فَبَشِّرْهُ بِعَذَابٍ ࡰلِيمࣲ࣌', 'يسمع ءايت ࡴلله تتلى عليه ثم يصر مستكبرا كأن لم يسمعها࣌ فبشره بعذاب ࡰليم࣌', NULL, 499, 'local:warsh-text.json'),
  ('warsh-45-8', 'warsh', 45, 8, 'وَإِذَا عَلِمَ مِنَ اٰيَٰتِنَا شَيْـٔاً ࡴٜتَّخَذَهَا هُزُؤاً࣌ ࡳوْلَٰٓئِكَ لَهُمْ عَذَابࣱ مُّهِينࣱ࣌', 'وإذا علم من ايتنا شيا ࡴتخذها هزؤا࣌ ࡳولئك لهم عذاب مهين࣌', NULL, 499, 'local:warsh-text.json'),
  ('warsh-45-9', 'warsh', 45, 9, 'مِّنْ وَّرَآئِهِمْ جَهَنَّمُ وَلَا يُغْنِے عَنْهُم مَّا كَسَبُواْ شَيْـٔاࣰ وَلَا مَا ࡰٜتَّخَذُواْ مِن دُونِ ࡴ۬للَّهِ أَوْلِيَآءَ࣌ وَلَهُمْ عَذَابٌ عَظِيمٌ࣌', 'من ورائهم جهنم ولا يغنے عنهم ما كسبوا شيا ولا ما ࡰتخذوا من دون ࡴلله أولياء࣌ ولهم عذاب عظيم࣌', NULL, 499, 'local:warsh-text.json'),
  ('warsh-45-10', 'warsh', 45, 10, 'هَٰذَا هُدىࣰ࣌ وَالذِينَ كَفَرُواْ بِـَٔايَٰتِ رَبِّهِمْ لَهُمْ عَذَابࣱ مِّن رِّجْزٍ ࡰلِيمٍ࣌', 'هذا هدى࣌ والذين كفروا بايت ربهم لهم عذاب من رجز ࡰليم࣌', NULL, 499, 'local:warsh-text.json'),
  ('warsh-45-11', 'warsh', 45, 11, 'ࡴ۬للَّهُ ࡲ۬لذِے سَخَّرَ لَكُمُ ࡲ۬لْبَحْرَ لِتَجْرِيَ ࡰ۬لْفُلْكُ فِيهِ بِأَمْرِهِۦ وَلِتَبْتَغُواْ مِن فَضْلِهِۦ وَلَعَلَّكُمْ تَشْكُرُونَ࣌', 'ࡴلله ࡲلذے سخر لكم ࡲلبحر لتجري ࡰلفلك فيه بأمره ولتبتغوا من فضله ولعلكم تشكرون࣌', NULL, 499, 'local:warsh-text.json'),
  ('warsh-45-12', 'warsh', 45, 12, 'وَسَخَّرَ لَكُم مَّا فِے ࡴ۬لسَّمَٰوَٰتِ وَمَا فِے ࡴ۬لَارْضِ جَمِيعاࣰ مِّنْهُ࣌ إِنَّ فِے ذَٰلِكَ لَأٓيَٰتࣲ لِّقَوْمࣲ يَتَفَكَّرُونَ࣌', 'وسخر لكم ما فے ࡴلسموت وما فے ࡴلارض جميعا منه࣌ إن فے ذلك لأيت لقوم يتفكرون࣌', NULL, 499, 'local:warsh-text.json'),
  ('warsh-45-13', 'warsh', 45, 13, '۞ قُل لِّلذِينَ ءَامَنُواْ يَغْفِرُواْ لِلذِينَ لَا يَرْجُونَ أَيَّامَ ࡰ۬للَّهِ لِيَجْزِيَ قَوْماَۢ بِمَا كَانُواْ يَكْسِبُونَ࣌', 'قل للذين ءامنوا يغفروا للذين لا يرجون أيام ࡰلله ليجزي قوما بما كانوا يكسبون࣌', NULL, 500, 'local:warsh-text.json'),
  ('warsh-45-14', 'warsh', 45, 14, 'مَنْ عَمِلَ صَٰلِحاࣰ فَلِنَفْسِهِۦ࣌ وَمَنَ ࡰسَآءَ فَعَلَيْهَا࣌ ثُمَّ إِلَىٰ رَبِّكُمْ تُرْجَعُونَ࣌', 'من عمل صلحا فلنفسه࣌ ومن ࡰساء فعليها࣌ ثم إلى ربكم ترجعون࣌', NULL, 500, 'local:warsh-text.json'),
  ('warsh-45-15', 'warsh', 45, 15, 'وَلَقَدَ اٰتَيْنَا بَنِےٓ إِسْرَآءِيلَ ࡰ۬لْكِتَٰبَ وَالْحُكْمَ وَالنُّبُوٓءَةَ وَرَزَقْنَٰهُم مِّنَ ࡰ۬لطَّيِّبَٰتِ وَفَضَّلْنَٰهُمْ عَلَى ࡰ۬لْعَٰلَمِينَ', 'ولقد اتينا بنے إسراءيل ࡰلكتب والحكم والنبوءة ورزقنهم من ࡰلطيبت وفضلنهم على ࡰلعلمين', NULL, 500, 'local:warsh-text.json'),
  ('warsh-45-16', 'warsh', 45, 16, 'وَءَاتَيْنَٰهُم بَيِّنَٰتࣲ مِّنَ ࡰ۬لَامْرِ࣌ فَمَا ࡰٜخْتَلَفُوٓاْ إِلَّا مِنۢ بَعْدِ مَا جَآءَهُمُ ࡲ۬لْعِلْمُ࣌ بَغْياَۢ بَيْنَهُمُۥٓ࣌ إِنَّ رَبَّكَ يَقْضِے بَيْنَهُمْ يَوْمَ ࡰ۬لْقِيَٰمَةِ فِيمَا كَانُواْ فِيهِ يَخْتَلِفُونَ࣌', 'وءاتينهم بينت من ࡰلامر࣌ فما ࡰختلفوا إلا من بعد ما جاءهم ࡲلعلم࣌ بغيا بينهم࣌ إن ربك يقضے بينهم يوم ࡰلقيمة فيما كانوا فيه يختلفون࣌', NULL, 500, 'local:warsh-text.json'),
  ('warsh-45-17', 'warsh', 45, 17, 'ثُمَّ جَعَلْنَٰكَ عَلَىٰ شَرِيعَةࣲ مِّنَ ࡰ۬لَامْرِ فَاتَّبِعْهَا࣌ وَلَا تَتَّبِعَ ࡰهْوَآءَ ࡰ۬لذِينَ لَا يَعْلَمُونَ࣌', 'ثم جعلنك على شريعة من ࡰلامر فاتبعها࣌ ولا تتبع ࡰهواء ࡰلذين لا يعلمون࣌', NULL, 500, 'local:warsh-text.json'),
  ('warsh-45-18', 'warsh', 45, 18, 'إِنَّهُمْ لَنْ يُّغْنُواْ عَنكَ مِنَ ࡰ۬للَّهِ شَيْـٔاࣰ࣌ وَإِنَّ ࡰ۬لظَّٰلِمِينَ بَعْضُهُمُۥٓ أَوْلِيَآءُ بَعْضࣲ࣌ وَاللَّهُ وَلِيُّ ࡲ۬لْمُتَّقِينَ࣌', 'إنهم لن يغنوا عنك من ࡰلله شيا࣌ وإن ࡰلظلمين بعضهم أولياء بعض࣌ والله ولي ࡲلمتقين࣌', NULL, 500, 'local:warsh-text.json'),
  ('warsh-45-19', 'warsh', 45, 19, 'هَٰذَا بَصَٰٓئِرُ لِلنَّاسِ وَهُدىࣰ وَرَحْمَةࣱ لِّقَوْمࣲ يُوقِنُونَ࣌', 'هذا بصئر للناس وهدى ورحمة لقوم يوقنون࣌', NULL, 500, 'local:warsh-text.json'),
  ('warsh-45-20', 'warsh', 45, 20, 'أَمْ حَسِبَ ࡰ۬لذِينَ ࡰٜجْتَرَحُواْ ࡲ۬لسَّيِّـَٔاتِ أَن نَّجْعَلَهُمْ كَالذِينَ ءَامَنُواْ وَعَمِلُواْ ࡲ۬لصَّٰلِحَٰتِ سَوَآءࣱ مَّحْيٜاهُمْ وَمَمَاتُهُمْ࣌ سَآءَ مَا يَحْكُمُونَ࣌', 'أم حسب ࡰلذين ࡰجترحوا ࡲلسيات أن نجعلهم كالذين ءامنوا وعملوا ࡲلصلحت سواء محياهم ومماتهم࣌ ساء ما يحكمون࣌', NULL, 500, 'local:warsh-text.json'),
  ('warsh-45-21', 'warsh', 45, 21, 'وَخَلَقَ ࡰ۬للَّهُ ࡲ۬لسَّمَٰوَٰتِ وَالَارْضَ بِالْحَقِّ࣌ وَلِتُجْزٜىٰ كُلُّ نَفْسِۢ بِمَا كَسَبَتْ وَهُمْ لَا يُظْلَمُونَ࣌', 'وخلق ࡰلله ࡲلسموت والارض بالحق࣌ ولتجزى كل نفس بما كسبت وهم لا يظلمون࣌', NULL, 500, 'local:warsh-text.json'),
  ('warsh-45-22', 'warsh', 45, 22, 'أَفَرَٰٓيْتَ مَنِ ࡴٜتَّخَذَ إِلَٰهَهُۥ هَوٜيٰهُ وَأَضَلَّهُ ࡲ۬للَّهُ عَلَىٰ عِلْمࣲ وَخَتَمَ عَلَىٰ سَمْعِهِۦ وَقَلْبِهِۦ وَجَعَلَ عَلَىٰ بَصَرِهِۦ غِشَٰوَةࣰ فَمَنْ يَّهْدِيهِ مِنۢ بَعْدِ ࡴ۬للَّهِ࣌ أَفَلَا تَذَّكَّرُونَ࣌', 'أفريت من ࡴتخذ إلهه هويه وأضله ࡲلله على علم وختم على سمعه وقلبه وجعل على بصره غشوة فمن يهديه من بعد ࡴلله࣌ أفلا تذكرون࣌', NULL, 501, 'local:warsh-text.json'),
  ('warsh-45-23', 'warsh', 45, 23, 'وَقَالُواْ مَا هِيَ إِلَّا حَيَاتُنَا ࡰ۬لدُّنْيٜا نَمُوتُ وَنَحْيٜا وَمَا يُهْلِكُنَآ إِلَّا ࡰ۬لدَّهْرُ࣌ وَمَا لَهُم بِذَٰلِكَ مِنْ عِلْمٍ࣌ ࡴنْ هُمُۥٓ إِلَّا يَظُنُّونَ࣌', 'وقالوا ما هي إلا حياتنا ࡰلدنيا نموت ونحيا وما يهلكنا إلا ࡰلدهر࣌ وما لهم بذلك من علم࣌ ࡴن هم إلا يظنون࣌', NULL, 501, 'local:warsh-text.json'),
  ('warsh-45-24', 'warsh', 45, 24, '۞ وَإِذَا تُتْلٜىٰ عَلَيْهِمُۥٓ ءَايَٰتُنَا بَيِّنَٰتࣲ مَّا كَانَ حُجَّتَهُمُۥٓ إِلَّآ أَن قَالُواْ ࡲٜيتُواْ بِـَٔابَآئِنَآ إِن كُنتُمْ صَٰدِقِينَ࣌', 'وإذا تتلى عليهم ءايتنا بينت ما كان حجتهم إلا أن قالوا ࡲيتوا بابائنا إن كنتم صدقين࣌', NULL, 501, 'local:warsh-text.json'),
  ('warsh-45-25', 'warsh', 45, 25, 'قُلِ ࡴ۬للَّهُ يُحْيِيكُمْ ثُمَّ يُمِيتُكُمْ ثُمَّ يَجْمَعُكُمُۥٓ إِلَىٰ يَوْمِ ࡴ۬لْقِيَٰمَةِ لَا رَيْبَ فِيهِ࣌ وَلَٰكِنَّ أَكْثَرَ ࡰ۬لنَّاسِ لَا يَعْلَمُونَ࣌', 'قل ࡴلله يحييكم ثم يميتكم ثم يجمعكم إلى يوم ࡴلقيمة لا ريب فيه࣌ ولكن أكثر ࡰلناس لا يعلمون࣌', NULL, 501, 'local:warsh-text.json'),
  ('warsh-45-26', 'warsh', 45, 26, 'وَلِلهِ مُلْكُ ࡲ۬لسَّمَٰوَٰتِ وَالَارْضِ࣌ وَيَوْمَ تَقُومُ ࡲ۬لسَّاعَةُ يَوْمَئِذࣲ يَخْسَرُ ࡲ۬لْمُبْطِلُونَ࣌', 'ولله ملك ࡲلسموت والارض࣌ ويوم تقوم ࡲلساعة يومئذ يخسر ࡲلمبطلون࣌', NULL, 501, 'local:warsh-text.json'),
  ('warsh-45-27', 'warsh', 45, 27, 'وَتَرٜىٰ كُلَّ أُمَّةࣲ جَاثِيَةࣰ࣌ كُلُّ أُمَّةࣲ تُدْعٜىٰٓ إِلَىٰ كِتَٰبِهَا࣌ ࡰ۬لْيَوْمَ تُجْزَوْنَ مَا كُنتُمْ تَعْمَلُونَ࣌', 'وترى كل أمة جاثية࣌ كل أمة تدعى إلى كتبها࣌ ࡰليوم تجزون ما كنتم تعملون࣌', NULL, 501, 'local:warsh-text.json'),
  ('warsh-45-28', 'warsh', 45, 28, 'هَٰذَا كِتَٰبُنَا يَنطِقُ عَلَيْكُم بِالْحَقِّ࣌ إِنَّا كُنَّا نَسْتَنسِخُ مَا كُنتُمْ تَعْمَلُونَ࣌', 'هذا كتبنا ينطق عليكم بالحق࣌ إنا كنا نستنسخ ما كنتم تعملون࣌', NULL, 501, 'local:warsh-text.json'),
  ('warsh-45-29', 'warsh', 45, 29, 'فَأَمَّا ࡰ۬لذِينَ ءَامَنُواْ وَعَمِلُواْ ࡲ۬لصَّٰلِحَٰتِ فَيُدْخِلُهُمْ رَبُّهُمْ فِے رَحْمَتِهِۦ࣌ ذَٰلِكَ هُوَ ࡰ۬لْفَوْزُ ࡲ۬لْمُبِينُ࣌', 'فأما ࡰلذين ءامنوا وعملوا ࡲلصلحت فيدخلهم ربهم فے رحمته࣌ ذلك هو ࡰلفوز ࡲلمبين࣌', NULL, 501, 'local:warsh-text.json'),
  ('warsh-45-30', 'warsh', 45, 30, 'وَأَمَّا ࡰ۬لذِينَ كَفَرُوٓاْ أَفَلَمْ تَكُنَ اٰيَٰتِے تُتْلٜىٰ عَلَيْكُمْ فَاسْتَكْبَرْتُمْ وَكُنتُمْ قَوْماࣰ مُّجْرِمِينَ࣌', 'وأما ࡰلذين كفروا أفلم تكن ايتے تتلى عليكم فاستكبرتم وكنتم قوما مجرمين࣌', NULL, 501, 'local:warsh-text.json'),
  ('warsh-45-31', 'warsh', 45, 31, 'وَإِذَا قِيلَ إِنَّ وَعْدَ ࡰ۬للَّهِ حَقࣱّ وَالسَّاعَةُ لَا رَيْبَ فِيهَا قُلْتُم مَّا نَدْرِے مَا ࡰ۬لسَّاعَةُ إِن نَّظُنُّ إِلَّا ظَنّاࣰ وَمَا نَحْنُ بِمُسْتَيْقِنِينَ࣌', 'وإذا قيل إن وعد ࡰلله حق والساعة لا ريب فيها قلتم ما ندرے ما ࡰلساعة إن نظن إلا ظنا وما نحن بمستيقنين࣌', NULL, 501, 'local:warsh-text.json'),
  ('warsh-45-32', 'warsh', 45, 32, 'وَبَدَا لَهُمْ سَيِّـَٔاتُ مَا عَمِلُواْ࣌ وَحَاقَ بِهِم مَّا كَانُواْ بِهِۦ يَسْتَهْزِءُونَ࣌', 'وبدا لهم سيات ما عملوا࣌ وحاق بهم ما كانوا به يستهزءون࣌', NULL, 502, 'local:warsh-text.json'),
  ('warsh-45-33', 'warsh', 45, 33, 'وَقِيلَ ࡰ۬لْيَوْمَ نَنسٜيٰكُمْ كَمَا نَسِيتُمْ لِقَآءَ يَوْمِكُمْ هَٰذَا وَمَأْوٜيٰكُمُ ࡲ۬لنَّارُ وَمَا لَكُم مِّن نَّٰصِرِينَ࣌', 'وقيل ࡰليوم ننسيكم كما نسيتم لقاء يومكم هذا ومأويكم ࡲلنار وما لكم من نصرين࣌', NULL, 502, 'local:warsh-text.json'),
  ('warsh-45-34', 'warsh', 45, 34, 'ذَٰلِكُم بِأَنَّكُمُ ࡲٜتَّخَذتُّمُۥٓ ءَايَٰتِ ࡴ۬للَّهِ هُزُؤاࣰ وَغَرَّتْكُمُ ࡲ۬لْحَيَوٰةُ ࡲ۬لدُّنْيٜا࣌ فَالْيَوْمَ لَا يُخْرَجُونَ مِنْهَا وَلَا هُمْ يُسْتَعْتَبُونَ࣌', 'ذلكم بأنكم ࡲتخذتم ءايت ࡴلله هزؤا وغرتكم ࡲلحيوة ࡲلدنيا࣌ فاليوم لا يخرجون منها ولا هم يستعتبون࣌', NULL, 502, 'local:warsh-text.json'),
  ('warsh-45-35', 'warsh', 45, 35, 'فَلِلهِ ࡴ۬لْحَمْدُ رَبِّ ࡴ۬لسَّمَٰوَٰتِ وَرَبِّ ࡴ۬لَارْضِ رَبِّ ࡴ۬لْعَٰلَمِينَ࣌', 'فلله ࡴلحمد رب ࡴلسموت ورب ࡴلارض رب ࡴلعلمين࣌', NULL, 502, 'local:warsh-text.json'),
  ('warsh-45-36', 'warsh', 45, 36, 'وَلَهُ ࡲ۬لْكِبْرِيَآءُ فِے ࡴ۬لسَّمَٰوَٰتِ وَالَارْضِ࣌ وَهُوَ ࡰ۬لْعَزِيزُ ࡲ۬لْحَكِيمُ࣌', 'وله ࡲلكبرياء فے ࡴلسموت والارض࣌ وهو ࡰلعزيز ࡲلحكيم࣌', NULL, 502, 'local:warsh-text.json'),
  ('warsh-46-1', 'warsh', 46, 1, 'حٜمِٓ࣌ تَنزِيلُ ࡲ۬لْكِتَٰبِ مِنَ ࡰ۬للَّهِ ࡴ۬لْعَزِيزِ ࡴ۬لْحَكِيمِ࣌', 'حم࣌ تنزيل ࡲلكتب من ࡰلله ࡴلعزيز ࡴلحكيم࣌', NULL, 502, 'local:warsh-text.json'),
  ('warsh-46-2', 'warsh', 46, 2, 'مَا خَلَقْنَا ࡰ۬لسَّمَٰوَٰتِ وَالَارْضَ وَمَا بَيْنَهُمَآ إِلَّا بِالْحَقِّ وَأَجَلࣲ مُّسَمّىࣰ࣌ وَالذِينَ كَفَرُواْ عَمَّآ أُنذِرُواْ مُعْرِضُونَ࣌', 'ما خلقنا ࡰلسموت والارض وما بينهما إلا بالحق وأجل مسمى࣌ والذين كفروا عما أنذروا معرضون࣌', NULL, 502, 'local:warsh-text.json'),
  ('warsh-46-3', 'warsh', 46, 3, 'قُلَ ࡰرَٰٓيْتُم مَّا تَدْعُونَ مِن دُونِ ࡴ۬للَّهِ أَرُونِے مَاذَا خَلَقُواْ مِنَ ࡰ۬لَارْضِ أَمْ لَهُمْ شِرْكࣱ فِے ࡴ۬لسَّمَٰوَٰتِ࣌ ࡴٜيتُونِے بِكِتَٰبࣲ مِّن قَبْلِ هَٰذَآ أَوَ ࡰثَٰرَةࣲ مِّنْ عِلْمٍ ࡴن كُنتُمْ صَٰدِقِينَ࣌', 'قل ࡰريتم ما تدعون من دون ࡴلله أرونے ماذا خلقوا من ࡰلارض أم لهم شرك فے ࡴلسموت࣌ ࡴيتونے بكتب من قبل هذا أو ࡰثرة من علم ࡴن كنتم صدقين࣌', NULL, 502, 'local:warsh-text.json'),
  ('warsh-46-4', 'warsh', 46, 4, 'وَمَنَ ࡰضَلُّ مِمَّنْ يَّدْعُواْ مِن دُونِ ࡴ۬للَّهِ مَن لَّا يَسْتَجِيبُ لَهُۥٓ إِلَىٰ يَوْمِ ࡴ۬لْقِيَٰمَةِ وَهُمْ عَن دُعَآئِهِمْ غَٰفِلُونَ࣌', 'ومن ࡰضل ممن يدعوا من دون ࡴلله من لا يستجيب له إلى يوم ࡴلقيمة وهم عن دعائهم غفلون࣌', NULL, 502, 'local:warsh-text.json'),
  ('warsh-46-5', 'warsh', 46, 5, 'وَإِذَا حُشِرَ ࡰ۬لنَّاسُ كَانُواْ لَهُمُۥٓ أَعْدَآءࣰ وَكَانُواْ بِعِبَادَتِهِمْ كٜـٰفِرِينَ࣌', 'وإذا حشر ࡰلناس كانوا لهم أعداء وكانوا بعبادتهم كفرين࣌', NULL, 503, 'local:warsh-text.json'),
  ('warsh-46-6', 'warsh', 46, 6, 'وَإِذَا تُتْلٜىٰ عَلَيْهِمُۥٓ ءَايَٰتُنَا بَيِّنَٰتࣲ قَالَ ࡰ۬لذِينَ كَفَرُواْ لِلْحَقِّ لَمَّا جَآءَهُمْ هَٰذَا سِحْرࣱ مُّبِينٌ࣌', 'وإذا تتلى عليهم ءايتنا بينت قال ࡰلذين كفروا للحق لما جاءهم هذا سحر مبين࣌', NULL, 503, 'local:warsh-text.json'),
  ('warsh-46-7', 'warsh', 46, 7, 'ࡰمْ يَقُولُونَ ࡰٜفْتَرٜيٰهُ࣌ قُلِ ࡴنِ ࡴٜفْتَرَيْتُهُۥ فَلَا تَمْلِكُونَ لِے مِنَ ࡰ۬للَّهِ شَيْـٔاً࣌ هُوَ أَعْلَمُ بِمَا تُفِيضُونَ فِيهِ࣌ كَفٜىٰ بِهِۦ شَهِيداَۢ بَيْنِے وَبَيْنَكُمْ࣌ وَهُوَ ࡰ۬لْغَفُورُ ࡲ۬لرَّحِيمُ࣌', 'ࡰم يقولون ࡰفتريه࣌ قل ࡴن ࡴفتريته فلا تملكون لے من ࡰلله شيا࣌ هو أعلم بما تفيضون فيه࣌ كفى به شهيدا بينے وبينكم࣌ وهو ࡰلغفور ࡲلرحيم࣌', NULL, 503, 'local:warsh-text.json'),
  ('warsh-46-8', 'warsh', 46, 8, 'قُلْ مَا كُنتُ بِدْعاࣰ مِّنَ ࡰ۬لرُّسُلِ وَمَآ أَدْرِے مَا يُفْعَلُ بِے وَلَا بِكُمُۥٓ࣌ إِنَ ࡰتَّبِعُ إِلَّا مَا يُوحٜىٰٓ إِلَيَّ࣌ وَمَآ أَنَا إِلَّا نَذِيرࣱ مُّبِينࣱ࣌', 'قل ما كنت بدعا من ࡰلرسل وما أدرے ما يفعل بے ولا بكم࣌ إن ࡰتبع إلا ما يوحى إلي࣌ وما أنا إلا نذير مبين࣌', NULL, 503, 'local:warsh-text.json'),
  ('warsh-46-9', 'warsh', 46, 9, 'قُلَ ࡰرَٰٓيْتُمُۥٓ إِن كَانَ مِنْ عِندِ ࡴ۬للَّهِ وَكَفَرْتُم بِهِۦ وَشَهِدَ شَاهِدࣱ مِّنۢ بَنِےٓ إِسْرَآءِيلَ عَلَىٰ مِثْلِهِۦ فَـَٔامَنَ وَاسْتَكْبَرْتُمُۥٓ࣌ إِنَّ ࡰ۬للَّهَ لَا يَهْدِے ࡴ۬لْقَوْمَ ࡰ۬لظَّٰلِمِينَ࣌', 'قل ࡰريتم إن كان من عند ࡴلله وكفرتم به وشهد شاهد من بنے إسراءيل على مثله فامن واستكبرتم࣌ إن ࡰلله لا يهدے ࡴلقوم ࡰلظلمين࣌', NULL, 503, 'local:warsh-text.json'),
  ('warsh-46-10', 'warsh', 46, 10, 'وَقَالَ ࡰ۬لذِينَ كَفَرُواْ لِلذِينَ ءَامَنُواْ لَوْ كَانَ خَيْراࣰ مَّا سَبَقُونَآ إِلَيْهِ࣌ وَإِذْ لَمْ يَهْتَدُواْ بِهِۦ فَسَيَقُولُونَ هَٰذَآ إِفْكࣱ قَدِيمࣱ࣌', 'وقال ࡰلذين كفروا للذين ءامنوا لو كان خيرا ما سبقونا إليه࣌ وإذ لم يهتدوا به فسيقولون هذا إفك قديم࣌', NULL, 503, 'local:warsh-text.json'),
  ('warsh-46-11', 'warsh', 46, 11, 'وَمِن قَبْلِهِۦ كِتَٰبُ مُوسٜىٰٓ إِمَاماࣰ وَرَحْمَةࣰ࣌ وَهَٰذَا كِتَٰبࣱ مُّصَدِّقࣱ لِّسَاناً عَرَبِيّاࣰ لِّتُنذِرَ ࡰ۬لذِينَ ظَلَمُواْ وَبُشْرٜىٰ لِلْمُحْسِنِينَ࣌', 'ومن قبله كتب موسى إماما ورحمة࣌ وهذا كتب مصدق لسانا عربيا لتنذر ࡰلذين ظلموا وبشرى للمحسنين࣌', NULL, 503, 'local:warsh-text.json'),
  ('warsh-46-12', 'warsh', 46, 12, 'إِنَّ ࡰ۬لذِينَ قَالُواْ رَبُّنَا ࡰ۬للَّهُ ثُمَّ ࡰٜسْتَقَٰمُواْ فَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ࣌', 'إن ࡰلذين قالوا ربنا ࡰلله ثم ࡰستقموا فلا خوف عليهم ولا هم يحزنون࣌', NULL, 503, 'local:warsh-text.json'),
  ('warsh-46-13', 'warsh', 46, 13, 'أُوْلَٰٓئِكَ أَصْحَٰبُ ࡲ۬لْجَنَّةِ خَٰلِدِينَ فِيهَا࣌ جَزَآءَۢ بِمَا كَانُواْ يَعْمَلُونَ࣌', 'أولئك أصحب ࡲلجنة خلدين فيها࣌ جزاء بما كانوا يعملون࣌', NULL, 503, 'local:warsh-text.json'),
  ('warsh-46-14', 'warsh', 46, 14, '۞ وَوَصَّيْنَا ࡰ۬لِانسَٰنَ بِوَٰلِدَيْهِ حُسْناً࣌ حَمَلَتْهُ أُمُّهُۥ كَرْهاࣰ وَوَضَعَتْهُ كَرْهاࣰ࣌ وَحَمْلُهُۥ وَفِصَٰلُهُۥ ثَلَٰثُونَ شَهْراً࣌ حَتَّىٰٓ إِذَا بَلَغَ أَشُدَّهُۥ وَبَلَغَ أَرْبَعِينَ سَنَةࣰ قَالَ رَبِّ أَوْزِعْنِيَ أَنَ ࡰشْكُرَ نِعْمَتَكَ ࡰ۬لتِےٓ أَنْعَمْتَ عَلَيَّ وَعَلَىٰ وَٰلِدَيَّ وَأَنَ ࡰعْمَلَ صَٰلِحاࣰ تَرْضٜيٰهُ࣌ وَأَصْلِحْ لِے فِے ذُرِّيَّتِےٓ࣌ إِنِّے تُبْتُ إِلَيْكَ وَإِنِّے مِنَ ࡰ۬لْمُسْلِمِينَ࣌', 'ووصينا ࡰلانسن بولديه حسنا࣌ حملته أمه كرها ووضعته كرها࣌ وحمله وفصله ثلثون شهرا࣌ حتى إذا بلغ أشده وبلغ أربعين سنة قال رب أوزعني أن ࡰشكر نعمتك ࡰلتے أنعمت علي وعلى ولدي وأن ࡰعمل صلحا ترضيه࣌ وأصلح لے فے ذريتے࣌ إنے تبت إليك وإنے من ࡰلمسلمين࣌', NULL, 504, 'local:warsh-text.json'),
  ('warsh-46-15', 'warsh', 46, 15, 'أُوْلَٰٓئِكَ ࡰ۬لذِينَ يُتَقَبَّلُ عَنْهُمُۥٓ أَحْسَنُ مَا عَمِلُواْ وَيُتَجَاوَزُ عَن سَيِّـَٔاتِهِمْ فِےٓ أَصْحَٰبِ ࡴ۬لْجَنَّةِ࣌ وَعْدَ ࡰ۬لصِّدْقِ ࡴ۬لذِے كَانُواْ يُوعَدُونَ࣌', 'أولئك ࡰلذين يتقبل عنهم أحسن ما عملوا ويتجاوز عن سياتهم فے أصحب ࡴلجنة࣌ وعد ࡰلصدق ࡴلذے كانوا يوعدون࣌', NULL, 504, 'local:warsh-text.json'),
  ('warsh-46-16', 'warsh', 46, 16, 'وَالذِے قَالَ لِوَٰلِدَيْهِ أُفࣲّ لَّكُمَآ أَتَعِدَٰنِنِيَ أَنُ ࡳخْرَجَ وَقَدْ خَلَتِ ࡴ۬لْقُرُونُ مِن قَبْلِے وَهُمَا يَسْتَغِيثَٰنِ ࡴ۬للَّهَ وَيْلَكَ ءَامِنِ ࡴنَّ وَعْدَ ࡰ۬للَّهِ حَقࣱّ فَيَقُولُ مَا هَٰذَآ إِلَّآ أَسَٰطِيرُ ࡲ۬لَاوَّلِينَ࣌', 'والذے قال لولديه أف لكما أتعدنني أن ࡳخرج وقد خلت ࡴلقرون من قبلے وهما يستغيثن ࡴلله ويلك ءامن ࡴن وعد ࡰلله حق فيقول ما هذا إلا أسطير ࡲلاولين࣌', NULL, 504, 'local:warsh-text.json'),
  ('warsh-46-17', 'warsh', 46, 17, 'أُوْلَٰٓئِكَ ࡰ۬لذِينَ حَقَّ عَلَيْهِمُ ࡲ۬لْقَوْلُ فِےٓ أُمَمࣲ قَدْ خَلَتْ مِن قَبْلِهِم مِّنَ ࡰ۬لْجِنِّ وَالِانسِ࣌ إِنَّهُمْ كَانُواْ خَٰسِرِينَ࣌', 'أولئك ࡰلذين حق عليهم ࡲلقول فے أمم قد خلت من قبلهم من ࡰلجن والانس࣌ إنهم كانوا خسرين࣌', NULL, 504, 'local:warsh-text.json'),
  ('warsh-46-18', 'warsh', 46, 18, 'وَلِكُلࣲّ دَرَجَٰتࣱ مِّمَّا عَمِلُواْ࣌ وَلِنُوَفِّيَهُمُۥٓ أَعْمَٰلَهُمْ وَهُمْ لَا يُظْلَمُونَ࣌', 'ولكل درجت مما عملوا࣌ ولنوفيهم أعملهم وهم لا يظلمون࣌', NULL, 504, 'local:warsh-text.json'),
  ('warsh-46-19', 'warsh', 46, 19, 'وَيَوْمَ يُعْرَضُ ࡲ۬لذِينَ كَفَرُواْ عَلَى ࡰ۬لنّٜارِ أَذْهَبْتُمْ طَيِّبَٰتِكُمْ فِے حَيَاتِكُمُ ࡲ۬لدُّنْيٜا وَاسْتَمْتَعْتُم بِهَا࣌ فَالْيَوْمَ تُجْزَوْنَ عَذَابَ ࡰ۬لْهُونِ بِمَا كُنتُمْ تَسْتَكْبِرُونَ فِے ࡴ۬لَارْضِ بِغَيْرِ ࡴ۬لْحَقِّ وَبِمَا كُنتُمْ تَفْسُقُونَ࣌', 'ويوم يعرض ࡲلذين كفروا على ࡰلنار أذهبتم طيبتكم فے حياتكم ࡲلدنيا واستمتعتم بها࣌ فاليوم تجزون عذاب ࡰلهون بما كنتم تستكبرون فے ࡴلارض بغير ࡴلحق وبما كنتم تفسقون࣌', NULL, 504, 'local:warsh-text.json'),
  ('warsh-46-20', 'warsh', 46, 20, '۞ وَاذْكُرَ ࡰخَا عَادٍ ࡴذَ ࡰنذَرَ قَوْمَهُۥ بِالَاحْقَافِ وَقَدْ خَلَتِ ࡴ۬لنُّذُرُ مِنۢ بَيْنِ يَدَيْهِ وَمِنْ خَلْفِهِۦٓ أَلَّا تَعْبُدُوٓاْ إِلَّا ࡰ۬للَّهَ࣌ إِنِّيَ أَخَافُ عَلَيْكُمْ عَذَابَ يَوْمٍ عَظِيمࣲ࣌', 'واذكر ࡰخا عاد ࡴذ ࡰنذر قومه بالاحقاف وقد خلت ࡴلنذر من بين يديه ومن خلفه ألا تعبدوا إلا ࡰلله࣌ إني أخاف عليكم عذاب يوم عظيم࣌', NULL, 505, 'local:warsh-text.json'),
  ('warsh-46-21', 'warsh', 46, 21, 'قَالُوٓاْ أَجِئْتَنَا لِتَافِكَنَا عَنَ اٰلِهَتِنَا فَاتِنَا بِمَا تَعِدُنَآ إِن كُنتَ مِنَ ࡰ۬لصَّٰدِقِينَ࣌', 'قالوا أجئتنا لتافكنا عن الهتنا فاتنا بما تعدنا إن كنت من ࡰلصدقين࣌', NULL, 505, 'local:warsh-text.json'),
  ('warsh-46-22', 'warsh', 46, 22, 'قَالَ إِنَّمَا ࡰ۬لْعِلْمُ عِندَ ࡰ۬للَّهِ وَأُبَلِّغُكُم مَّآ أُرْسِلْتُ بِهِۦ وَلَٰكِنِّيَ أَرٜيٰكُمْ قَوْماࣰ تَجْهَلُونَ࣌', 'قال إنما ࡰلعلم عند ࡰلله وأبلغكم ما أرسلت به ولكني أريكم قوما تجهلون࣌', NULL, 505, 'local:warsh-text.json'),
  ('warsh-46-23', 'warsh', 46, 23, 'فَلَمَّا رَأَوْهُ عَارِضاࣰ مُّسْتَقْبِلَ أَوْدِيَتِهِمْ قَالُواْ هَٰذَا عَارِضࣱ مُّمْطِرُنَا࣌ بَلْ هُوَ مَا ࡰٜسْتَعْجَلْتُم بِهِۦ࣌ رِيحࣱ فِيهَا عَذَابٌ ࡰلِيمࣱ࣌', 'فلما رأوه عارضا مستقبل أوديتهم قالوا هذا عارض ممطرنا࣌ بل هو ما ࡰستعجلتم به࣌ ريح فيها عذاب ࡰليم࣌', NULL, 505, 'local:warsh-text.json'),
  ('warsh-46-24', 'warsh', 46, 24, 'تُدَمِّرُ كُلَّ شَےْءِۢ بِأَمْرِ رَبِّهَا࣌ فَأَصْبَحُواْ لَا تَرٜىٰٓ إِلَّا مَسَٰكِنَهُمْ࣌ كَذَٰلِكَ نَجْزِے ࡴ۬لْقَوْمَ ࡰ۬لْمُجْرِمِينَ࣌', 'تدمر كل شےء بأمر ربها࣌ فأصبحوا لا ترى إلا مسكنهم࣌ كذلك نجزے ࡴلقوم ࡰلمجرمين࣌', NULL, 505, 'local:warsh-text.json'),
  ('warsh-46-25', 'warsh', 46, 25, 'وَلَقَدْ مَكَّنَّٰهُمْ فِيمَآ إِن مَّكَّنَّٰكُمْ فِيهِ وَجَعَلْنَا لَهُمْ سَمْعاࣰ وَأَبْصَٰراࣰ وَأَفْـِٕدَةࣰ࣌ فَمَآ أَغْنٜىٰ عَنْهُمْ سَمْعُهُمْ وَلَآ أَبْصَٰرُهُمْ وَلَآ أَفْـِٕدَتُهُم مِّن شَےْءٍ ࡴذْ كَانُواْ يَجْحَدُونَ بِـَٔايَٰتِ ࡴ۬للَّهِ࣌ وَحَاقَ بِهِم مَّا كَانُواْ بِهِۦ يَسْتَهْزِءُونَ࣌', 'ولقد مكنهم فيما إن مكنكم فيه وجعلنا لهم سمعا وأبصرا وأفدة࣌ فما أغنى عنهم سمعهم ولا أبصرهم ولا أفدتهم من شےء ࡴذ كانوا يجحدون بايت ࡴلله࣌ وحاق بهم ما كانوا به يستهزءون࣌', NULL, 505, 'local:warsh-text.json'),
  ('warsh-46-26', 'warsh', 46, 26, 'وَلَقَدَ ࡰهْلَكْنَا مَا حَوْلَكُم مِّنَ ࡰ۬لْقُرٜىٰ وَصَرَّفْنَا ࡰ۬لَايَٰتِ لَعَلَّهُمْ يَرْجِعُونَ࣌', 'ولقد ࡰهلكنا ما حولكم من ࡰلقرى وصرفنا ࡰلايت لعلهم يرجعون࣌', NULL, 505, 'local:warsh-text.json'),
  ('warsh-46-27', 'warsh', 46, 27, 'فَلَوْلَا نَصَرَهُمُ ࡲ۬لذِينَ ࡰٜتَّخَذُواْ مِن دُونِ ࡴ۬للَّهِ قُرْبَاناً اٰلِهَةَۢ࣌ بَلْ ضَلُّواْ عَنْهُمْ࣌ وَذَٰلِكَ إِفْكُهُمْ وَمَا كَانُواْ يَفْتَرُونَ࣌', 'فلولا نصرهم ࡲلذين ࡰتخذوا من دون ࡴلله قربانا الهة࣌ بل ضلوا عنهم࣌ وذلك إفكهم وما كانوا يفترون࣌', NULL, 505, 'local:warsh-text.json'),
  ('warsh-46-28', 'warsh', 46, 28, 'وَإِذْ صَرَفْنَآ إِلَيْكَ نَفَراࣰ مِّنَ ࡰ۬لْجِنِّ يَسْتَمِعُونَ ࡰ۬لْقُرْءَانَ فَلَمَّا حَضَرُوهُ قَالُوٓاْ أَنصِتُواْ࣌ فَلَمَّا قُضِيَ وَلَّوِاْ ࡴلَىٰ قَوْمِهِم مُّنذِرِينَ࣌', 'وإذ صرفنا إليك نفرا من ࡰلجن يستمعون ࡰلقرءان فلما حضروه قالوا أنصتوا࣌ فلما قضي ولوا ࡴلى قومهم منذرين࣌', NULL, 506, 'local:warsh-text.json'),
  ('warsh-46-29', 'warsh', 46, 29, 'قَالُواْ يَٰقَوْمَنَآ إِنَّا سَمِعْنَا كِتَٰباً ࡳنزِلَ مِنۢ بَعْدِ مُوسٜىٰ مُصَدِّقاࣰ لِّمَا بَيْنَ يَدَيْهِ يَهْدِےٓ إِلَى ࡰ۬لْحَقِّ وَإِلَىٰ طَرِيقࣲ مُّسْتَقِيمࣲ࣌', 'قالوا يقومنا إنا سمعنا كتبا ࡳنزل من بعد موسى مصدقا لما بين يديه يهدے إلى ࡰلحق وإلى طريق مستقيم࣌', NULL, 506, 'local:warsh-text.json'),
  ('warsh-46-30', 'warsh', 46, 30, 'يَٰقَوْمَنَآ أَجِيبُواْ دَاعِيَ ࡰ۬للَّهِ وَءَامِنُواْ بِهِۦ يَغْفِرْ لَكُم مِّن ذُنُوبِكُمْ وَيُجِرْكُم مِّنْ عَذَابٍ ࡰلِيمࣲ࣌', 'يقومنا أجيبوا داعي ࡰلله وءامنوا به يغفر لكم من ذنوبكم ويجركم من عذاب ࡰليم࣌', NULL, 506, 'local:warsh-text.json'),
  ('warsh-46-31', 'warsh', 46, 31, 'وَمَن لَّا يُجِبْ دَاعِيَ ࡰ۬للَّهِ فَلَيْسَ بِمُعْجِزࣲ فِے ࡴ۬لَارْضِ وَلَيْسَ لَهُۥ مِن دُونِهِۦٓ أَوْلِيَآءُ࣌ اوْلَٰٓئِكَ فِے ضَلَٰلࣲ مُّبِينٍ࣌', 'ومن لا يجب داعي ࡰلله فليس بمعجز فے ࡴلارض وليس له من دونه أولياء࣌ اولئك فے ضلل مبين࣌', NULL, 506, 'local:warsh-text.json'),
  ('warsh-46-32', 'warsh', 46, 32, '۞ ࡰوَلَمْ يَرَوَاْ ࡰنَّ ࡰ۬للَّهَ ࡰ۬لذِے خَلَقَ ࡰ۬لسَّمَٰوَٰتِ وَالَارْضَ وَلَمْ يَعْيَ بِخَلْقِهِنَّ بِقَٰدِرٍ عَلَىٰٓ أَنْ يُّحْۑِيَ ࡰ۬لْمَوْتٜىٰ بَلٜىٰٓ࣌ إِنَّهُۥ عَلَىٰ كُلِّ شَےْءࣲ قَدِيرࣱ࣌', 'ࡰولم يروا ࡰن ࡰلله ࡰلذے خلق ࡰلسموت والارض ولم يعي بخلقهن بقدر على أن يحۑي ࡰلموتى بلى࣌ إنه على كل شےء قدير࣌', NULL, 506, 'local:warsh-text.json'),
  ('warsh-46-33', 'warsh', 46, 33, 'وَيَوْمَ يُعْرَضُ ࡲ۬لذِينَ كَفَرُواْ عَلَى ࡰ۬لنّٜارِ أَلَيْسَ هَٰذَا بِالْحَقِّ࣌ قَالُواْ بَلٜىٰ وَرَبِّنَا࣌ قَالَ فَذُوقُواْ ࡲ۬لْعَذَابَ بِمَا كُنتُمْ تَكْفُرُونَ࣌', 'ويوم يعرض ࡲلذين كفروا على ࡰلنار أليس هذا بالحق࣌ قالوا بلى وربنا࣌ قال فذوقوا ࡲلعذاب بما كنتم تكفرون࣌', NULL, 506, 'local:warsh-text.json'),
  ('warsh-46-34', 'warsh', 46, 34, 'فَاصْبِرْ كَمَا صَبَرَ أُوْلُواْ ࡲ۬لْعَزْمِ مِنَ ࡰ۬لرُّسُلِ وَلَا تَسْتَعْجِل࣌ لَّهُمْ كَأَنَّهُمْ يَوْمَ يَرَوْنَ مَا يُوعَدُونَ لَمْ يَلْبَثُوٓاْ إِلَّا سَاعَةࣰ مِّن نَّهٜارِۢ بَلَٰغࣱ࣌ فَهَلْ يُهْلَكُ إِلَّا ࡰ۬لْقَوْمُ ࡲ۬لْفَٰسِقُونَ࣌', 'فاصبر كما صبر أولوا ࡲلعزم من ࡰلرسل ولا تستعجل࣌ لهم كأنهم يوم يرون ما يوعدون لم يلبثوا إلا ساعة من نهار بلغ࣌ فهل يهلك إلا ࡰلقوم ࡲلفسقون࣌', NULL, 506, 'local:warsh-text.json'),
  ('warsh-47-1', 'warsh', 47, 1, 'ࡰ۬لذِينَ كَفَرُواْ وَصَدُّواْ عَن سَبِيلِ ࡴ۬للَّهِ أَضَلَّ أَعْمَٰلَهُمْ࣌', 'ࡰلذين كفروا وصدوا عن سبيل ࡴلله أضل أعملهم࣌', NULL, 507, 'local:warsh-text.json'),
  ('warsh-47-2', 'warsh', 47, 2, 'وَالذِينَ ءَامَنُواْ وَعَمِلُواْ ࡲ۬لصَّٰلِحَٰتِ وَءَامَنُواْ بِمَا نُزِّلَ عَلَىٰ مُحَمَّدࣲ وَهُوَ ࡰ۬لْحَقُّ مِن رَّبِّهِمْ كَفَّرَ عَنْهُمْ سَيِّـَٔاتِهِمْ وَأَصْلَحَ بَالَهُمْ࣌', 'والذين ءامنوا وعملوا ࡲلصلحت وءامنوا بما نزل على محمد وهو ࡰلحق من ربهم كفر عنهم سياتهم وأصلح بالهم࣌', NULL, 507, 'local:warsh-text.json'),
  ('warsh-47-3', 'warsh', 47, 3, 'ذَٰلِكَ بِأَنَّ ࡰ۬لذِينَ كَفَرُواْ ࡲٜتَّبَعُواْ ࡲ۬لْبَٰطِلَ وَأَنَّ ࡰ۬لذِينَ ءَامَنُواْ ࡲٜتَّبَعُواْ ࡲ۬لْحَقَّ مِن رَّبِّهِمْ࣌ كَذَٰلِكَ يَضْرِبُ ࡲ۬للَّهُ لِلنَّاسِ أَمْثَٰلَهُمْ࣌', 'ذلك بأن ࡰلذين كفروا ࡲتبعوا ࡲلبطل وأن ࡰلذين ءامنوا ࡲتبعوا ࡲلحق من ربهم࣌ كذلك يضرب ࡲلله للناس أمثلهم࣌', NULL, 507, 'local:warsh-text.json'),
  ('warsh-47-4', 'warsh', 47, 4, 'فَإِذَا لَقِيتُمُ ࡲ۬لذِينَ كَفَرُواْ فَضَرْبَ ࡰ۬لرِّقَابِ࣌ حَتَّىٰٓ إِذَآ أَثْخَنتُمُوهُمْ فَشُدُّواْ ࡲ۬لْوَثَاقَ࣌ فَإِمَّا مَنّاَۢ بَعْدُ وَإِمَّا فِدَآءً حَتَّىٰ تَضَعَ ࡰ۬لْحَرْبُ أَوْزَارَهَا࣌', 'فإذا لقيتم ࡲلذين كفروا فضرب ࡰلرقاب࣌ حتى إذا أثخنتموهم فشدوا ࡲلوثاق࣌ فإما منا بعد وإما فداء حتى تضع ࡰلحرب أوزارها࣌', NULL, 507, 'local:warsh-text.json'),
  ('warsh-47-5', 'warsh', 47, 5, 'ذَٰلِكَ وَلَوْ يَشَآءُ ࡲ۬للَّهُ لَانتَصَرَ مِنْهُمْ࣌ وَلَٰكِن لِّيَبْلُوَاْ بَعْضَكُم بِبَعْضࣲ࣌ وَالذِينَ قَٰتَلُواْ فِے سَبِيلِ ࡴ۬للَّهِ فَلَنْ يُّضِلَّ أَعْمَٰلَهُمْ࣌', 'ذلك ولو يشاء ࡲلله لانتصر منهم࣌ ولكن ليبلوا بعضكم ببعض࣌ والذين قتلوا فے سبيل ࡴلله فلن يضل أعملهم࣌', NULL, 507, 'local:warsh-text.json'),
  ('warsh-47-6', 'warsh', 47, 6, 'سَيَهْدِيهِمْ وَيُصْلِحُ بَالَهُمْ', 'سيهديهم ويصلح بالهم', NULL, 507, 'local:warsh-text.json'),
  ('warsh-47-7', 'warsh', 47, 7, 'وَيُدْخِلُهُمُ ࡲ۬لْجَنَّةَ عَرَّفَهَا لَهُمْ࣌', 'ويدخلهم ࡲلجنة عرفها لهم࣌', NULL, 507, 'local:warsh-text.json'),
  ('warsh-47-8', 'warsh', 47, 8, 'يَٰٓأَيُّهَا ࡰ۬لذِينَ ءَامَنُوٓاْ إِن تَنصُرُواْ ࡲ۬للَّهَ يَنصُرْكُمْ وَيُثَبِّتَ ࡰقْدَامَكُمْ࣌', 'يأيها ࡰلذين ءامنوا إن تنصروا ࡲلله ينصركم ويثبت ࡰقدامكم࣌', NULL, 507, 'local:warsh-text.json'),
  ('warsh-47-9', 'warsh', 47, 9, 'وَالذِينَ كَفَرُواْ فَتَعْساࣰ لَّهُمْ وَأَضَلَّ أَعْمَٰلَهُمْ࣌', 'والذين كفروا فتعسا لهم وأضل أعملهم࣌', NULL, 507, 'local:warsh-text.json'),
  ('warsh-47-10', 'warsh', 47, 10, 'ذَٰلِكَ بِأَنَّهُمْ كَرِهُواْ مَآ أَنزَلَ ࡰ۬للَّهُ فَأَحْبَطَ أَعْمَٰلَهُمُۥٓ࣌', 'ذلك بأنهم كرهوا ما أنزل ࡰلله فأحبط أعملهم࣌', NULL, 507, 'local:warsh-text.json'),
  ('warsh-47-11', 'warsh', 47, 11, '۞ أَفَلَمْ يَسِيرُواْ فِے ࡴ۬لَارْضِ فَيَنظُرُواْ كَيْفَ كَانَ عَٰقِبَةُ ࡲ۬لذِينَ مِن قَبْلِهِمْ دَمَّرَ ࡰ۬للَّهُ عَلَيْهِمْ࣌ وَلِلْكٜـٰفِرِينَ أَمْثَٰلُهَا࣌', 'أفلم يسيروا فے ࡴلارض فينظروا كيف كان عقبة ࡲلذين من قبلهم دمر ࡰلله عليهم࣌ وللكفرين أمثلها࣌', NULL, 507, 'local:warsh-text.json'),
  ('warsh-47-12', 'warsh', 47, 12, 'ذَٰلِكَ بِأَنَّ ࡰ۬للَّهَ مَوْلَى ࡰ۬لذِينَ ءَامَنُواْ وَأَنَّ ࡰ۬لْكٜـٰفِرِينَ لَا مَوْلٜىٰ لَهُمُۥٓ࣌', 'ذلك بأن ࡰلله مولى ࡰلذين ءامنوا وأن ࡰلكفرين لا مولى لهم࣌', NULL, 507, 'local:warsh-text.json'),
  ('warsh-47-13', 'warsh', 47, 13, 'إِنَّ ࡰ۬للَّهَ يُدْخِلُ ࡲ۬لذِينَ ءَامَنُواْ وَعَمِلُواْ ࡲ۬لصَّٰلِحَٰتِ جَنَّٰتࣲ تَجْرِے مِن تَحْتِهَا ࡰ۬لَانْهَٰرُ࣌ وَالذِينَ كَفَرُواْ يَتَمَتَّعُونَ وَيَاكُلُونَ كَمَا تَاكُلُ ࡲ۬لَانْعَٰمُ وَالنَّارُ مَثْوىࣰ لَّهُمْ࣌', 'إن ࡰلله يدخل ࡲلذين ءامنوا وعملوا ࡲلصلحت جنت تجرے من تحتها ࡰلانهر࣌ والذين كفروا يتمتعون وياكلون كما تاكل ࡲلانعم والنار مثوى لهم࣌', NULL, 508, 'local:warsh-text.json'),
  ('warsh-47-14', 'warsh', 47, 14, 'وَكَأَيِّن مِّن قَرْيَةٍ هِيَ أَشَدُّ قُوَّةࣰ مِّن قَرْيَتِكَ ࡰ۬لتِےٓ أَخْرَجَتْكَ أَهْلَكْنَٰهُمْ فَلَا نَاصِرَ لَهُمُۥٓ࣌', 'وكأين من قرية هي أشد قوة من قريتك ࡰلتے أخرجتك أهلكنهم فلا ناصر لهم࣌', NULL, 508, 'local:warsh-text.json'),
  ('warsh-47-15', 'warsh', 47, 15, 'أَفَمَن كَانَ عَلَىٰ بَيِّنَةࣲ مِّن رَّبِّهِۦ كَمَن زُيِّنَ لَهُۥ سُوٓءُ عَمَلِهِۦ وَاتَّبَعُوٓاْ أَهْوَآءَهُم࣌', 'أفمن كان على بينة من ربه كمن زين له سوء عمله واتبعوا أهواءهم࣌', NULL, 508, 'local:warsh-text.json'),
  ('warsh-47-16', 'warsh', 47, 16, 'مَّثَلُ ࡲ۬لْجَنَّةِ ࡴ۬لتِے وُعِدَ ࡰ۬لْمُتَّقُونَ فِيهَآ أَنْهَٰرࣱ مِّن مَّآءٍ غَيْرِ ءَاسِنࣲ وَأَنْهَٰرࣱ مِّن لَّبَنࣲ لَّمْ يَتَغَيَّرْ طَعْمُهُۥ وَأَنْهَٰرࣱ مِّنْ خَمْرࣲ لَّذَّةࣲ لِّلشَّٰرِبِينَ وَأَنْهَٰرࣱ مِّنْ عَسَلࣲ مُّصَفّىࣰ࣌ وَلَهُمْ فِيهَا مِن كُلِّ ࡴ۬لثَّمَرَٰتِ وَمَغْفِرَةࣱ مِّن رَّبِّهِمْ كَمَنْ هُوَ خَٰلِدࣱ فِے ࡴ۬لنّٜارِ وَسُقُواْ مَآءً حَمِيماࣰ فَقَطَّعَ أَمْعَآءَهُمْ࣌', 'مثل ࡲلجنة ࡴلتے وعد ࡰلمتقون فيها أنهر من ماء غير ءاسن وأنهر من لبن لم يتغير طعمه وأنهر من خمر لذة للشربين وأنهر من عسل مصفى࣌ ولهم فيها من كل ࡴلثمرت ومغفرة من ربهم كمن هو خلد فے ࡴلنار وسقوا ماء حميما فقطع أمعاءهم࣌', NULL, 508, 'local:warsh-text.json'),
  ('warsh-47-17', 'warsh', 47, 17, 'وَمِنْهُم مَّنْ يَّسْتَمِعُ إِلَيْكَ حَتَّىٰٓ إِذَا خَرَجُواْ مِنْ عِندِكَ قَالُواْ لِلذِينَ أُوتُواْ ࡲ۬لْعِلْمَ مَاذَا قَالَ ءَانِفاً࣌ ࡳوْلَٰٓئِكَ ࡰ۬لذِينَ طَبَعَ ࡰ۬للَّهُ عَلَىٰ قُلُوبِهِمْ وَاتَّبَعُوٓاْ أَهْوَآءَهُمْ࣌', 'ومنهم من يستمع إليك حتى إذا خرجوا من عندك قالوا للذين أوتوا ࡲلعلم ماذا قال ءانفا࣌ ࡳولئك ࡰلذين طبع ࡰلله على قلوبهم واتبعوا أهواءهم࣌', NULL, 508, 'local:warsh-text.json'),
  ('warsh-47-18', 'warsh', 47, 18, 'وَالذِينَ ࡰٜهْتَدَوْاْ زَادَهُمْ هُدىࣰ وَءَاتٜيٰهُمْ تَقْوٜيٰهُمْ࣌', 'والذين ࡰهتدوا زادهم هدى وءاتيهم تقويهم࣌', NULL, 508, 'local:warsh-text.json'),
  ('warsh-47-19', 'warsh', 47, 19, 'فَهَلْ يَنظُرُونَ إِلَّا ࡰ۬لسَّاعَةَ أَن تَاتِيَهُم بَغْتَةࣰ فَقَدْ جَآءَ اشْرَاطُهَا࣌ فَأَنّٜىٰ لَهُمُۥٓ إِذَا جَآءَتْهُمْ ذِكْرٜيٰهُمْ࣌', 'فهل ينظرون إلا ࡰلساعة أن تاتيهم بغتة فقد جاء اشراطها࣌ فأنى لهم إذا جاءتهم ذكريهم࣌', NULL, 508, 'local:warsh-text.json'),
  ('warsh-47-20', 'warsh', 47, 20, 'فَاعْلَمَ ࡰنَّهُۥ لَآ إِلَٰهَ إِلَّا ࡰ۬للَّهُ وَاسْتَغْفِرْ لِذَنۢبِكَ وَلِلْمُومِنِينَ وَالْمُومِنَٰتِ࣌ وَاللَّهُ يَعْلَمُ مُتَقَلَّبَكُمْ وَمَثْوٜيٰكُمْ࣌', 'فاعلم ࡰنه لا إله إلا ࡰلله واستغفر لذنبك وللمومنين والمومنت࣌ والله يعلم متقلبكم ومثويكم࣌', NULL, 508, 'local:warsh-text.json'),
  ('warsh-47-21', 'warsh', 47, 21, '۞ وَيَقُولُ ࡲ۬لذِينَ ءَامَنُواْ لَوْلَا نُزِّلَتْ سُورَةࣱ࣌ فَإِذَآ أُنزِلَتْ سُورَةࣱ مُّحْكَمَةࣱ وَذُكِرَ فِيهَا ࡰ۬لْقِتَالُ رَأَيْتَ ࡰ۬لذِينَ فِے قُلُوبِهِم مَّرَضࣱ يَنظُرُونَ إِلَيْكَ نَظَرَ ࡰ۬لْمَغْشِيِّ عَلَيْهِ مِنَ ࡰ۬لْمَوْتِ࣌ فَأَوْلٜىٰ لَهُمْ࣌', 'ويقول ࡲلذين ءامنوا لولا نزلت سورة࣌ فإذا أنزلت سورة محكمة وذكر فيها ࡰلقتال رأيت ࡰلذين فے قلوبهم مرض ينظرون إليك نظر ࡰلمغشي عليه من ࡰلموت࣌ فأولى لهم࣌', NULL, 509, 'local:warsh-text.json'),
  ('warsh-47-22', 'warsh', 47, 22, 'طَاعَةࣱ وَقَوْلࣱ مَّعْرُوفࣱ࣌ فَإِذَا عَزَمَ ࡰ۬لَامْرُ فَلَوْ صَدَقُواْ ࡲ۬للَّهَ لَكَانَ خَيْراࣰ لَّهُمْ࣌', 'طاعة وقول معروف࣌ فإذا عزم ࡰلامر فلو صدقوا ࡲلله لكان خيرا لهم࣌', NULL, 509, 'local:warsh-text.json'),
  ('warsh-47-23', 'warsh', 47, 23, 'فَهَلْ عَسِيتُمُۥٓ إِن تَوَلَّيْتُمُۥٓ أَن تُفْسِدُواْ فِے ࡴ۬لَارْضِ وَتُقَطِّعُوٓاْ أَرْحَامَكُمُۥٓ࣌', 'فهل عسيتم إن توليتم أن تفسدوا فے ࡴلارض وتقطعوا أرحامكم࣌', NULL, 509, 'local:warsh-text.json'),
  ('warsh-47-24', 'warsh', 47, 24, 'أُوْلَٰٓئِكَ ࡰ۬لذِينَ لَعَنَهُمُ ࡲ۬للَّهُ فَأَصَمَّهُمْ وَأَعْمٜىٰٓ أَبْصَٰرَهُمُۥٓ࣌', 'أولئك ࡰلذين لعنهم ࡲلله فأصمهم وأعمى أبصرهم࣌', NULL, 509, 'local:warsh-text.json'),
  ('warsh-47-25', 'warsh', 47, 25, 'أَفَلَا يَتَدَبَّرُونَ ࡰ۬لْقُرْءَانَ أَمْ عَلَىٰ قُلُوبٍ ࡰقْفَالُهَآ࣌', 'أفلا يتدبرون ࡰلقرءان أم على قلوب ࡰقفالها࣌', NULL, 509, 'local:warsh-text.json'),
  ('warsh-47-26', 'warsh', 47, 26, 'إِنَّ ࡰ۬لذِينَ ࡰٜرْتَدُّواْ عَلَىٰٓ أَدْبٜـٰرِهِم مِّنۢ بَعْدِ مَا تَبَيَّنَ لَهُمُ ࡲ۬لْهُدَى ࡰ۬لشَّيْطَٰنُ سَوَّلَ لَهُمْ࣌ وَأَمْلٜىٰ لَهُمْ࣌', 'إن ࡰلذين ࡰرتدوا على أدبرهم من بعد ما تبين لهم ࡲلهدى ࡰلشيطن سول لهم࣌ وأملى لهم࣌', NULL, 509, 'local:warsh-text.json'),
  ('warsh-47-27', 'warsh', 47, 27, 'ذَٰلِكَ بِأَنَّهُمْ قَالُواْ لِلذِينَ كَرِهُواْ مَا نَزَّلَ ࡰ۬للَّهُ سَنُطِيعُكُمْ فِے بَعْضِ ࡴ۬لَامْرِ࣌ وَاللَّهُ يَعْلَمُ أَسْرَارَهُمْ࣌', 'ذلك بأنهم قالوا للذين كرهوا ما نزل ࡰلله سنطيعكم فے بعض ࡴلامر࣌ والله يعلم أسرارهم࣌', NULL, 509, 'local:warsh-text.json'),
  ('warsh-47-28', 'warsh', 47, 28, 'فَكَيْفَ إِذَا تَوَفَّتْهُمُ ࡲ۬لْمَلَٰٓئِكَةُ يَضْرِبُونَ وُجُوهَهُمْ وَأَدْبَٰرَهُمْ࣌', 'فكيف إذا توفتهم ࡲلملئكة يضربون وجوههم وأدبرهم࣌', NULL, 509, 'local:warsh-text.json'),
  ('warsh-47-29', 'warsh', 47, 29, 'ذَٰلِكَ بِأَنَّهُمُ ࡲٜتَّبَعُواْ مَآ أَسْخَطَ ࡰ۬للَّهَ وَكَرِهُواْ رِضْوَٰنَهُۥ فَأَحْبَطَ أَعْمَٰلَهُمُۥٓ࣌', 'ذلك بأنهم ࡲتبعوا ما أسخط ࡰلله وكرهوا رضونه فأحبط أعملهم࣌', NULL, 509, 'local:warsh-text.json'),
  ('warsh-47-30', 'warsh', 47, 30, 'أَمْ حَسِبَ ࡰ۬لذِينَ فِے قُلُوبِهِم مَّرَضٌ ࡰن لَّنْ يُّخْرِجَ ࡰ۬للَّهُ أَضْغَٰنَهُمْ࣌', 'أم حسب ࡰلذين فے قلوبهم مرض ࡰن لن يخرج ࡰلله أضغنهم࣌', NULL, 509, 'local:warsh-text.json'),
  ('warsh-47-31', 'warsh', 47, 31, 'وَلَوْ نَشَآءُ لَأَرَيْنَٰكَهُمْ فَلَعَرَفْتَهُم بِسِيمٜـٰهُمْ࣌ وَلَتَعْرِفَنَّهُمْ فِے لَحْنِ ࡴ۬لْقَوْلِ࣌ وَاللَّهُ يَعْلَمُ أَعْمَٰلَكُمْ࣌', 'ولو نشاء لأرينكهم فلعرفتهم بسيمهم࣌ ولتعرفنهم فے لحن ࡴلقول࣌ والله يعلم أعملكم࣌', NULL, 510, 'local:warsh-text.json'),
  ('warsh-47-32', 'warsh', 47, 32, 'وَلَنَبْلُوَنَّكُمْ حَتَّىٰ نَعْلَمَ ࡰ۬لْمُجَٰهِدِينَ مِنكُمْ وَالصَّٰبِرِينَ وَنَبْلُوَاْ أَخْبَارَكُمُۥٓ࣌', 'ولنبلونكم حتى نعلم ࡰلمجهدين منكم والصبرين ونبلوا أخباركم࣌', NULL, 510, 'local:warsh-text.json'),
  ('warsh-47-33', 'warsh', 47, 33, 'إِنَّ ࡰ۬لذِينَ كَفَرُواْ وَصَدُّواْ عَن سَبِيلِ ࡴ۬للَّهِ وَشَآقُّواْ ࡲ۬لرَّسُولَ مِنۢ بَعْدِ مَا تَبَيَّنَ لَهُمُ ࡲ۬لْهُدٜىٰ لَنْ يَّضُرُّواْ ࡲ۬للَّهَ شَيْـٔاࣰ࣌ وَسَيُحْبِطُ أَعْمَٰلَهُمْ࣌', 'إن ࡰلذين كفروا وصدوا عن سبيل ࡴلله وشاقوا ࡲلرسول من بعد ما تبين لهم ࡲلهدى لن يضروا ࡲلله شيا࣌ وسيحبط أعملهم࣌', NULL, 510, 'local:warsh-text.json'),
  ('warsh-47-34', 'warsh', 47, 34, '۞ يَٰٓأَيُّهَا ࡰ۬لذِينَ ءَامَنُوٓاْ أَطِيعُواْ ࡲ۬للَّهَ وَأَطِيعُواْ ࡲ۬لرَّسُولَ وَلَا تُبْطِلُوٓاْ أَعْمَٰلَكُمُۥٓ࣌', 'يأيها ࡰلذين ءامنوا أطيعوا ࡲلله وأطيعوا ࡲلرسول ولا تبطلوا أعملكم࣌', NULL, 510, 'local:warsh-text.json'),
  ('warsh-47-35', 'warsh', 47, 35, 'إِنَّ ࡰ۬لذِينَ كَفَرُواْ وَصَدُّواْ عَن سَبِيلِ ࡴ۬للَّهِ ثُمَّ مَاتُواْ وَهُمْ كُفَّارࣱ فَلَنْ يَّغْفِرَ ࡰ۬للَّهُ لَهُمْ࣌', 'إن ࡰلذين كفروا وصدوا عن سبيل ࡴلله ثم ماتوا وهم كفار فلن يغفر ࡰلله لهم࣌', NULL, 510, 'local:warsh-text.json'),
  ('warsh-47-36', 'warsh', 47, 36, 'فَلَا تَهِنُواْ وَتَدْعُوٓاْ إِلَى ࡰ۬لسَّلْمِ وَأَنتُمُ ࡲ۬لَاعْلَوْنَ وَاللَّهُ مَعَكُمْ࣌ وَلَنْ يَّتِرَكُمُۥٓ أَعْمَٰلَكُمُۥٓ࣌', 'فلا تهنوا وتدعوا إلى ࡰلسلم وأنتم ࡲلاعلون والله معكم࣌ ولن يتركم أعملكم࣌', NULL, 510, 'local:warsh-text.json'),
  ('warsh-47-37', 'warsh', 47, 37, 'إِنَّمَا ࡰ۬لْحَيَوٰةُ ࡲ۬لدُّنْيٜا لَعِبࣱ وَلَهْوࣱ࣌ وَإِن تُومِنُواْ وَتَتَّقُواْ يُوتِكُمُۥٓ أُجُورَكُمْ وَلَا يَسْـَٔلْكُمُۥٓ أَمْوَٰلَكُمُۥٓ࣌', 'إنما ࡰلحيوة ࡲلدنيا لعب ولهو࣌ وإن تومنوا وتتقوا يوتكم أجوركم ولا يسلكم أمولكم࣌', NULL, 510, 'local:warsh-text.json'),
  ('warsh-47-38', 'warsh', 47, 38, 'إِنْ يَّسْـَٔلْكُمُوهَا فَيُحْفِكُمْ تَبْخَلُواْ وَيُخْرِجَ ࡰضْغَٰنَكُمْ࣌', 'إن يسلكموها فيحفكم تبخلوا ويخرج ࡰضغنكم࣌', NULL, 510, 'local:warsh-text.json'),
  ('warsh-47-39', 'warsh', 47, 39, 'هَآنتُمْ هَٰٓؤُلَآءِ تُدْعَوْنَ لِتُنفِقُواْ فِے سَبِيلِ ࡴ۬للَّهِ فَمِنكُم مَّنْ يَّبْخَلُ࣌ وَمَنْ يَّبْخَلْ فَإِنَّمَا يَبْخَلُ عَن نَّفْسِهِۦ࣌ وَاللَّهُ ࡲ۬لْغَنِيُّ࣌ وَأَنتُمُ ࡲ۬لْفُقَرَآءُ࣌ وَإِن تَتَوَلَّوْاْ يَسْتَبْدِلْ قَوْماً غَيْرَكُمْ ثُمَّ لَا يَكُونُوٓاْ أَمْثَٰلَكُمُۥٓ࣌', 'هانتم هؤلاء تدعون لتنفقوا فے سبيل ࡴلله فمنكم من يبخل࣌ ومن يبخل فإنما يبخل عن نفسه࣌ والله ࡲلغني࣌ وأنتم ࡲلفقراء࣌ وإن تتولوا يستبدل قوما غيركم ثم لا يكونوا أمثلكم࣌', NULL, 510, 'local:warsh-text.json'),
  ('warsh-48-1', 'warsh', 48, 1, 'إِنَّا فَتَحْنَا لَكَ فَتْحاࣰ مُّبِيناࣰ', 'إنا فتحنا لك فتحا مبينا', NULL, 511, 'local:warsh-text.json'),
  ('warsh-48-2', 'warsh', 48, 2, 'لِّيَغْفِرَ لَكَ ࡰ۬للَّهُ مَا تَقَدَّمَ مِن ذَنۢبِكَ وَمَا تَأَخَّرَ وَيُتِمَّ نِعْمَتَهُۥ عَلَيْكَ وَيَهْدِيَكَ صِرَٰطاࣰ مُّسْتَقِيماࣰ', 'ليغفر لك ࡰلله ما تقدم من ذنبك وما تأخر ويتم نعمته عليك ويهديك صرطا مستقيما', NULL, 511, 'local:warsh-text.json'),
  ('warsh-48-3', 'warsh', 48, 3, 'وَيَنصُرَكَ ࡰ۬للَّهُ نَصْراً عَزِيزاً࣌', 'وينصرك ࡰلله نصرا عزيزا࣌', NULL, 511, 'local:warsh-text.json'),
  ('warsh-48-4', 'warsh', 48, 4, 'هُوَ ࡰ۬لذِےٓ أَنزَلَ ࡰ۬لسَّكِينَةَ فِے قُلُوبِ ࡴ۬لْمُومِنِينَ لِيَزْدَادُوٓاْ إِيمَٰناࣰ مَّعَ إِيمَٰنِهِمْ࣌ وَلِلهِ جُنُودُ ࡲ۬لسَّمَٰوَٰتِ وَالَارْضِ࣌ وَكَانَ ࡰ۬للَّهُ عَلِيماً حَكِيماࣰ', 'هو ࡰلذے أنزل ࡰلسكينة فے قلوب ࡴلمومنين ليزدادوا إيمنا مع إيمنهم࣌ ولله جنود ࡲلسموت والارض࣌ وكان ࡰلله عليما حكيما', NULL, 511, 'local:warsh-text.json'),
  ('warsh-48-5', 'warsh', 48, 5, 'لِّيُدْخِلَ ࡰ۬لْمُومِنِينَ وَالْمُومِنَٰتِ جَنَّٰتࣲ تَجْرِے مِن تَحْتِهَا ࡰ۬لَانْهَٰرُ خَٰلِدِينَ فِيهَا وَيُكَفِّرَ عَنْهُمْ سَيِّـَٔاتِهِمْ وَكَانَ ذَٰلِكَ عِندَ ࡰ۬للَّهِ فَوْزاً عَظِيماࣰ', 'ليدخل ࡰلمومنين والمومنت جنت تجرے من تحتها ࡰلانهر خلدين فيها ويكفر عنهم سياتهم وكان ذلك عند ࡰلله فوزا عظيما', NULL, 511, 'local:warsh-text.json'),
  ('warsh-48-6', 'warsh', 48, 6, 'وَيُعَذِّبَ ࡰ۬لْمُنَٰفِقِينَ وَالْمُنَٰفِقَٰتِ وَالْمُشْرِكِينَ وَالْمُشْرِكَٰتِ ࡴ۬لظَّآنِّينَ بِاللَّهِ ظَنَّ ࡰ۬لسَّوْءِ࣌ عَلَيْهِمْ دَآئِرَةُ ࡲ۬لسَّوْءِ࣌ وَغَضِبَ ࡰ۬للَّهُ عَلَيْهِمْ وَلَعَنَهُمْ وَأَعَدَّ لَهُمْ جَهَنَّمَ࣌ وَسَآءَتْ مَصِيراࣰ࣌', 'ويعذب ࡰلمنفقين والمنفقت والمشركين والمشركت ࡴلظانين بالله ظن ࡰلسوء࣌ عليهم دائرة ࡲلسوء࣌ وغضب ࡰلله عليهم ولعنهم وأعد لهم جهنم࣌ وساءت مصيرا࣌', NULL, 511, 'local:warsh-text.json'),
  ('warsh-48-7', 'warsh', 48, 7, 'وَلِلهِ جُنُودُ ࡲ۬لسَّمَٰوَٰتِ وَالَارْضِ࣌ وَكَانَ ࡰ۬للَّهُ عَزِيزاً حَكِيماً࣌', 'ولله جنود ࡲلسموت والارض࣌ وكان ࡰلله عزيزا حكيما࣌', NULL, 511, 'local:warsh-text.json'),
  ('warsh-48-8', 'warsh', 48, 8, '۞ ࡴنَّآ أَرْسَلْنَٰكَ شَٰهِداࣰ وَمُبَشِّراࣰ وَنَذِيراࣰ', 'ࡴنا أرسلنك شهدا ومبشرا ونذيرا', NULL, 511, 'local:warsh-text.json'),
  ('warsh-48-9', 'warsh', 48, 9, 'لِّتُومِنُواْ بِاللَّهِ وَرَسُولِهِۦ وَتُعَزِّرُوهُ وَتُوَقِّرُوهُ وَتُسَبِّحُوهُ بُكْرَةࣰ وَأَصِيلاً࣌', 'لتومنوا بالله ورسوله وتعزروه وتوقروه وتسبحوه بكرة وأصيلا࣌', NULL, 511, 'local:warsh-text.json'),
  ('warsh-48-10', 'warsh', 48, 10, 'ࡴنَّ ࡰ۬لذِينَ يُبَايِعُونَكَ إِنَّمَا يُبَايِعُونَ ࡰ۬للَّهَ࣌ يَدُ ࡲ۬للَّهِ فَوْقَ أَيْدِيهِمْ࣌ فَمَن نَّكَثَ فَإِنَّمَا يَنكُثُ عَلَىٰ نَفْسِهِۦ࣌ وَمَنَ ࡰوْفٜىٰ بِمَا عَٰهَدَ عَلَيْهِ ࡴ۬للَّهَ فَسَنُوتِيهِ أَجْراً عَظِيماࣰ࣌', 'ࡴن ࡰلذين يبايعونك إنما يبايعون ࡰلله࣌ يد ࡲلله فوق أيديهم࣌ فمن نكث فإنما ينكث على نفسه࣌ ومن ࡰوفى بما عهد عليه ࡴلله فسنوتيه أجرا عظيما࣌', NULL, 512, 'local:warsh-text.json'),
  ('warsh-48-11', 'warsh', 48, 11, 'سَيَقُولُ لَكَ ࡰ۬لْمُخَلَّفُونَ مِنَ ࡰ۬لَاعْرَابِ شَغَلَتْنَآ أَمْوَٰلُنَا وَأَهْلُونَا فَاسْتَغْفِرْ لَنَا࣌ يَقُولُونَ بِأَلْسِنَتِهِم مَّا لَيْسَ فِے قُلُوبِهِمْ࣌ قُلْ فَمَنْ يَّمْلِكُ لَكُم مِّنَ ࡰ۬للَّهِ شَيْـٔاً ࡴنَ ࡰرَادَ بِكُمْ ضَرّاً ࡰوَ ࡰرَادَ بِكُمْ نَفْعاَۢ࣌ بَلْ كَانَ ࡰ۬للَّهُ بِمَا تَعْمَلُونَ خَبِيراَۢ࣌', 'سيقول لك ࡰلمخلفون من ࡰلاعراب شغلتنا أمولنا وأهلونا فاستغفر لنا࣌ يقولون بألسنتهم ما ليس فے قلوبهم࣌ قل فمن يملك لكم من ࡰلله شيا ࡴن ࡰراد بكم ضرا ࡰو ࡰراد بكم نفعا࣌ بل كان ࡰلله بما تعملون خبيرا࣌', NULL, 512, 'local:warsh-text.json'),
  ('warsh-48-12', 'warsh', 48, 12, 'بَلْ ظَنَنتُمُۥٓ أَن لَّنْ يَّنقَلِبَ ࡰ۬لرَّسُولُ وَالْمُومِنُونَ إِلَىٰٓ أَهْلِيهِمُۥٓ أَبَداࣰ وَزُيِّنَ ذَٰلِكَ فِے قُلُوبِكُمْ وَظَنَنتُمْ ظَنَّ ࡰ۬لسَّوْءِ وَكُنتُمْ قَوْماَۢ بُوراࣰ࣌', 'بل ظننتم أن لن ينقلب ࡰلرسول والمومنون إلى أهليهم أبدا وزين ذلك فے قلوبكم وظننتم ظن ࡰلسوء وكنتم قوما بورا࣌', NULL, 512, 'local:warsh-text.json'),
  ('warsh-48-13', 'warsh', 48, 13, 'وَمَن لَّمْ يُومِنۢ بِاللَّهِ وَرَسُولِهِۦ فَإِنَّآ أَعْتَدْنَا لِلْكٜـٰفِرِينَ سَعِيراࣰ࣌', 'ومن لم يومن بالله ورسوله فإنا أعتدنا للكفرين سعيرا࣌', NULL, 512, 'local:warsh-text.json'),
  ('warsh-48-14', 'warsh', 48, 14, 'وَلِلهِ مُلْكُ ࡲ۬لسَّمَٰوَٰتِ وَالَارْضِ࣌ يَغْفِرُ لِمَنْ يَّشَآءُ وَيُعَذِّبُ مَنْ يَّشَآءُ࣌ وَكَانَ ࡰ۬للَّهُ غَفُوراࣰ رَّحِيماࣰ࣌', 'ولله ملك ࡲلسموت والارض࣌ يغفر لمن يشاء ويعذب من يشاء࣌ وكان ࡰلله غفورا رحيما࣌', NULL, 512, 'local:warsh-text.json'),
  ('warsh-48-15', 'warsh', 48, 15, 'سَيَقُولُ ࡲ۬لْمُخَلَّفُونَ إِذَا ࡰٜنطَلَقْتُمُۥٓ إِلَىٰ مَغَانِمَ لِتَاخُذُوهَا ذَرُونَا نَتَّبِعْكُمْ࣌ يُرِيدُونَ أَنْ يُّبَدِّلُواْ كَلَٰمَ ࡰ۬للَّهِ࣌ قُل لَّن تَتَّبِعُونَا࣌ كَذَٰلِكُمْ قَالَ ࡰ۬للَّهُ مِن قَبْلُ࣌ فَسَيَقُولُونَ بَلْ تَحْسُدُونَنَا࣌ بَلْ كَانُواْ لَا يَفْقَهُونَ إِلَّا قَلِيلاࣰ࣌', 'سيقول ࡲلمخلفون إذا ࡰنطلقتم إلى مغانم لتاخذوها ذرونا نتبعكم࣌ يريدون أن يبدلوا كلم ࡰلله࣌ قل لن تتبعونا࣌ كذلكم قال ࡰلله من قبل࣌ فسيقولون بل تحسدوننا࣌ بل كانوا لا يفقهون إلا قليلا࣌', NULL, 512, 'local:warsh-text.json'),
  ('warsh-48-16', 'warsh', 48, 16, 'قُل لِّلْمُخَلَّفِينَ مِنَ ࡰ۬لَاعْرَابِ سَتُدْعَوْنَ إِلَىٰ قَوْمٍ ࡳوْلِے بَأْسࣲ شَدِيدࣲ تُقَٰتِلُونَهُمُۥٓ أَوْ يُسْلِمُونَ࣌ فَإِن تُطِيعُواْ يُوتِكُمُ ࡲ۬للَّهُ أَجْراً حَسَناࣰ࣌ وَإِن تَتَوَلَّوْاْ كَمَا تَوَلَّيْتُم مِّن قَبْلُ يُعَذِّبْكُمْ عَذَاباً ࡰلِيماࣰ࣌', 'قل للمخلفين من ࡰلاعراب ستدعون إلى قوم ࡳولے بأس شديد تقتلونهم أو يسلمون࣌ فإن تطيعوا يوتكم ࡲلله أجرا حسنا࣌ وإن تتولوا كما توليتم من قبل يعذبكم عذابا ࡰليما࣌', NULL, 513, 'local:warsh-text.json'),
  ('warsh-48-17', 'warsh', 48, 17, 'لَّيْسَ عَلَى ࡰ۬لَاعْمٜىٰ حَرَجࣱ وَلَا عَلَى ࡰ۬لَاعْرَجِ حَرَجࣱ وَلَا عَلَى ࡰ۬لْمَرِيضِ حَرَجࣱ࣌ وَمَنْ يُّطِعِ ࡴ۬للَّهَ وَرَسُولَهُۥ نُدْخِلْهُ جَنَّٰتࣲ تَجْرِے مِن تَحْتِهَا ࡰ۬لَانْهَٰرُ࣌ وَمَنْ يَّتَوَلَّ نُعَذِّبْهُ عَذَاباً ࡰلِيماࣰ࣌', 'ليس على ࡰلاعمى حرج ولا على ࡰلاعرج حرج ولا على ࡰلمريض حرج࣌ ومن يطع ࡴلله ورسوله ندخله جنت تجرے من تحتها ࡰلانهر࣌ ومن يتول نعذبه عذابا ࡰليما࣌', NULL, 513, 'local:warsh-text.json'),
  ('warsh-48-18', 'warsh', 48, 18, '۞ لَّقَدْ رَضِيَ ࡰ۬للَّهُ عَنِ ࡴ۬لْمُومِنِينَ إِذْ يُبَايِعُونَكَ تَحْتَ ࡰ۬لشَّجَرَةِ فَعَلِمَ مَا فِے قُلُوبِهِمْ فَأَنزَلَ ࡰ۬لسَّكِينَةَ عَلَيْهِمْ وَأَثَٰبَهُمْ فَتْحاࣰ قَرِيباࣰ', 'لقد رضي ࡰلله عن ࡴلمومنين إذ يبايعونك تحت ࡰلشجرة فعلم ما فے قلوبهم فأنزل ࡰلسكينة عليهم وأثبهم فتحا قريبا', NULL, 513, 'local:warsh-text.json'),
  ('warsh-48-19', 'warsh', 48, 19, 'وَمَغَانِمَ كَثِيرَةࣰ يَاخُذُونَهَا࣌ وَكَانَ ࡰ۬للَّهُ عَزِيزاً حَكِيماࣰ࣌', 'ومغانم كثيرة ياخذونها࣌ وكان ࡰلله عزيزا حكيما࣌', NULL, 513, 'local:warsh-text.json'),
  ('warsh-48-20', 'warsh', 48, 20, 'وَعَدَكُمُ ࡲ۬للَّهُ مَغَانِمَ كَثِيرَةࣰ تَاخُذُونَهَا فَعَجَّلَ لَكُمْ هَٰذِهِۦ وَكَفَّ أَيْدِيَ ࡰ۬لنَّاسِ عَنكُمْ࣌ وَلِتَكُونَ ءَايَةࣰ لِّلْمُومِنِينَ وَيَهْدِيَكُمْ صِرَٰطاࣰ مُّسْتَقِيماࣰ࣌', 'وعدكم ࡲلله مغانم كثيرة تاخذونها فعجل لكم هذه وكف أيدي ࡰلناس عنكم࣌ ولتكون ءاية للمومنين ويهديكم صرطا مستقيما࣌', NULL, 513, 'local:warsh-text.json'),
  ('warsh-48-21', 'warsh', 48, 21, 'وَأُخْرٜىٰ لَمْ تَقْدِرُواْ عَلَيْهَا قَدَ ࡰحَاطَ ࡰ۬للَّهُ بِهَا࣌ وَكَانَ ࡰ۬للَّهُ عَلَىٰ كُلِّ شَےْءࣲ قَدِيراࣰ࣌', 'وأخرى لم تقدروا عليها قد ࡰحاط ࡰلله بها࣌ وكان ࡰلله على كل شےء قديرا࣌', NULL, 513, 'local:warsh-text.json'),
  ('warsh-48-22', 'warsh', 48, 22, 'وَلَوْ قَٰتَلَكُمُ ࡲ۬لذِينَ كَفَرُواْ لَوَلَّوُاْ ࡲ۬لَادْبَٰرَ ثُمَّ لَا يَجِدُونَ وَلِيّاࣰ وَلَا نَصِيراࣰ࣌', 'ولو قتلكم ࡲلذين كفروا لولوا ࡲلادبر ثم لا يجدون وليا ولا نصيرا࣌', NULL, 513, 'local:warsh-text.json'),
  ('warsh-48-23', 'warsh', 48, 23, 'سُنَّةَ ࡰ۬للَّهِ ࡴ۬لتِے قَدْ خَلَتْ مِن قَبْلُ࣌ وَلَن تَجِدَ لِسُنَّةِ ࡴ۬للَّهِ تَبْدِيلاࣰ࣌', 'سنة ࡰلله ࡴلتے قد خلت من قبل࣌ ولن تجد لسنة ࡴلله تبديلا࣌', NULL, 513, 'local:warsh-text.json'),
  ('warsh-48-24', 'warsh', 48, 24, 'وَهُوَ ࡰ۬لذِے كَفَّ أَيْدِيَهُمْ عَنكُمْ وَأَيْدِيَكُمْ عَنْهُم بِبَطْنِ مَكَّةَ مِنۢ بَعْدِ أَنَ ࡰظْفَرَكُمْ عَلَيْهِمْ࣌ وَكَانَ ࡰ۬للَّهُ بِمَا تَعْمَلُونَ بَصِيراً࣌', 'وهو ࡰلذے كف أيديهم عنكم وأيديكم عنهم ببطن مكة من بعد أن ࡰظفركم عليهم࣌ وكان ࡰلله بما تعملون بصيرا࣌', NULL, 514, 'local:warsh-text.json'),
  ('warsh-48-25', 'warsh', 48, 25, 'هُمُ ࡲ۬لذِينَ كَفَرُواْ وَصَدُّوكُمْ عَنِ ࡴ۬لْمَسْجِدِ ࡴ۬لْحَرَامِ وَالْهَدْيَ مَعْكُوفاً ࡰنْ يَّبْلُغَ مَحِلَّهُۥ࣌ وَلَوْلَا رِجَالࣱ مُّومِنُونَ وَنِسَآءࣱ مُّومِنَٰتࣱ لَّمْ تَعْلَمُوهُمُۥٓ أَن تَطَـُٔوهُمْ فَتُصِيبَكُم مِّنْهُم مَّعَرَّةُۢ بِغَيْرِ عِلْمࣲ لِّيُدْخِلَ ࡰ۬للَّهُ فِے رَحْمَتِهِۦ مَنْ يَّشَآءُ࣌ لَوْ تَزَيَّلُواْ لَعَذَّبْنَا ࡰ۬لذِينَ كَفَرُواْ مِنْهُمْ عَذَاباً ࡰلِيماً࣌', 'هم ࡲلذين كفروا وصدوكم عن ࡴلمسجد ࡴلحرام والهدي معكوفا ࡰن يبلغ محله࣌ ولولا رجال مومنون ونساء مومنت لم تعلموهم أن تطوهم فتصيبكم منهم معرة بغير علم ليدخل ࡰلله فے رحمته من يشاء࣌ لو تزيلوا لعذبنا ࡰلذين كفروا منهم عذابا ࡰليما࣌', NULL, 514, 'local:warsh-text.json'),
  ('warsh-48-26', 'warsh', 48, 26, '۞ ࡴذْ جَعَلَ ࡰ۬لذِينَ كَفَرُواْ فِے قُلُوبِهِمُ ࡲ۬لْحَمِيَّةَ حَمِيَّةَ ࡰ۬لْجَٰهِلِيَّةِ࣌ فَأَنزَلَ ࡰ۬للَّهُ سَكِينَتَهُۥ عَلَىٰ رَسُولِهِۦ وَعَلَى ࡰ۬لْمُومِنِينَ وَأَلْزَمَهُمْ كَلِمَةَ ࡰ۬لتَّقْوٜىٰ وَكَانُوٓاْ أَحَقَّ بِهَا وَأَهْلَهَا࣌ وَكَانَ ࡰ۬للَّهُ بِكُلِّ شَےْءٍ عَلِيماࣰ࣌', 'ࡴذ جعل ࡰلذين كفروا فے قلوبهم ࡲلحمية حمية ࡰلجهلية࣌ فأنزل ࡰلله سكينته على رسوله وعلى ࡰلمومنين وألزمهم كلمة ࡰلتقوى وكانوا أحق بها وأهلها࣌ وكان ࡰلله بكل شےء عليما࣌', NULL, 514, 'local:warsh-text.json'),
  ('warsh-48-27', 'warsh', 48, 27, 'لَّقَدْ صَدَقَ ࡰ۬للَّهُ رَسُولَهُ ࡲ۬لرُّءْيٜا بِالْحَقِّ لَتَدْخُلُنَّ ࡰ۬لْمَسْجِدَ ࡰ۬لْحَرَامَ إِن شَآءَ ࡰ۬للَّهُ ءَامِنِينَ مُحَلِّقِينَ رُءُوسَكُمْ وَمُقَصِّرِينَ لَا تَخَافُونَ࣌ فَعَلِمَ مَا لَمْ تَعْلَمُواْ فَجَعَلَ مِن دُونِ ذَٰلِكَ فَتْحاࣰ قَرِيباً࣌', 'لقد صدق ࡰلله رسوله ࡲلرءيا بالحق لتدخلن ࡰلمسجد ࡰلحرام إن شاء ࡰلله ءامنين محلقين رءوسكم ومقصرين لا تخافون࣌ فعلم ما لم تعلموا فجعل من دون ذلك فتحا قريبا࣌', NULL, 514, 'local:warsh-text.json'),
  ('warsh-48-28', 'warsh', 48, 28, 'هُوَ ࡰ۬لذِےٓ أَرْسَلَ رَسُولَهُۥ بِالْهُدٜىٰ وَدِينِ ࡴ۬لْحَقِّ لِيُظْهِرَهُۥ عَلَى ࡰ۬لدِّينِ كُلِّهِۦ࣌ وَكَفٜىٰ بِاللَّهِ شَهِيداࣰ࣌', 'هو ࡰلذے أرسل رسوله بالهدى ودين ࡴلحق ليظهره على ࡰلدين كله࣌ وكفى بالله شهيدا࣌', NULL, 514, 'local:warsh-text.json'),
  ('warsh-48-29', 'warsh', 48, 29, 'مُّحَمَّدࣱ رَّسُولُ ࡲ۬للَّهِ࣌ وَالذِينَ مَعَهُۥٓ أَشِدَّآءُ عَلَى ࡰ۬لْكُفّٜارِ رُحَمَآءُ بَيْنَهُمْ࣌ تَرٜيٰهُمْ رُكَّعاࣰ سُجَّداࣰ يَبْتَغُونَ فَضْلاࣰ مِّنَ ࡰ۬للَّهِ وَرِضْوَٰناࣰ࣌ سِيمٜاهُمْ فِے وُجُوهِهِم مِّنَ ࡰثَرِ ࡴ۬لسُّجُودِ࣌ ذَٰلِكَ مَثَلُهُمْ فِے ࡴ۬لتَّوْرٜيٰةِ࣌ وَمَثَلُهُمْ فِے ࡴ۬لِانجِيلِ كَزَرْعٍ ࡰخْرَجَ شَطْـَٔهُۥ فَـَٔازَرَهُۥ فَاسْتَغْلَظَ فَاسْتَوٜىٰ عَلَىٰ سُوقِهِۦ يُعْجِبُ ࡲ۬لزُّرَّاعَ لِيَغِيظَ بِهِمُ ࡲ۬لْكُفَّارَ࣌ وَعَدَ ࡰ۬للَّهُ ࡲ۬لذِينَ ءَامَنُواْ وَعَمِلُواْ ࡲ۬لصَّٰلِحَٰتِ مِنْهُم مَّغْفِرَةࣰ وَأَجْراً عَظِيماࣰ࣌', 'محمد رسول ࡲلله࣌ والذين معه أشداء على ࡰلكفار رحماء بينهم࣌ تريهم ركعا سجدا يبتغون فضلا من ࡰلله ورضونا࣌ سيماهم فے وجوههم من ࡰثر ࡴلسجود࣌ ذلك مثلهم فے ࡴلتورية࣌ ومثلهم فے ࡴلانجيل كزرع ࡰخرج شطه فازره فاستغلظ فاستوى على سوقه يعجب ࡲلزراع ليغيظ بهم ࡲلكفار࣌ وعد ࡰلله ࡲلذين ءامنوا وعملوا ࡲلصلحت منهم مغفرة وأجرا عظيما࣌', NULL, 515, 'local:warsh-text.json'),
  ('warsh-49-1', 'warsh', 49, 1, 'يَٰٓأَيُّهَا ࡰ۬لذِينَ ءَامَنُواْ لَا تُقَدِّمُواْ بَيْنَ يَدَيِ ࡴ۬للَّهِ وَرَسُولِهِۦ࣌ وَاتَّقُواْ ࡲ۬للَّهَ࣌ إِنَّ ࡰ۬للَّهَ سَمِيعٌ عَلِيمࣱ࣌', 'يأيها ࡰلذين ءامنوا لا تقدموا بين يدي ࡴلله ورسوله࣌ واتقوا ࡲلله࣌ إن ࡰلله سميع عليم࣌', NULL, 515, 'local:warsh-text.json'),
  ('warsh-49-2', 'warsh', 49, 2, 'يَٰٓأَيُّهَا ࡰ۬لذِينَ ءَامَنُواْ لَا تَرْفَعُوٓاْ أَصْوَٰتَكُمْ فَوْقَ صَوْتِ ࡴ۬لنَّبِےٓءِ وَلَا تَجْهَرُواْ لَهُۥ بِالْقَوْلِ كَجَهْرِ بَعْضِكُمْ لِبَعْضٍ ࡰن تَحْبَطَ أَعْمَٰلُكُمْ وَأَنتُمْ لَا تَشْعُرُونَ࣌', 'يأيها ࡰلذين ءامنوا لا ترفعوا أصوتكم فوق صوت ࡴلنبےء ولا تجهروا له بالقول كجهر بعضكم لبعض ࡰن تحبط أعملكم وأنتم لا تشعرون࣌', NULL, 515, 'local:warsh-text.json'),
  ('warsh-49-3', 'warsh', 49, 3, 'إِنَّ ࡰ۬لذِينَ يَغُضُّونَ أَصْوَٰتَهُمْ عِندَ رَسُولِ ࡴ۬للَّهِ أُوْلَٰٓئِكَ ࡰ۬لذِينَ ࡰٜمْتَحَنَ ࡰ۬للَّهُ قُلُوبَهُمْ لِلتَّقْوٜىٰ࣌ لَهُم مَّغْفِرَةࣱ وَأَجْرٌ عَظِيمٌ࣌', 'إن ࡰلذين يغضون أصوتهم عند رسول ࡴلله أولئك ࡰلذين ࡰمتحن ࡰلله قلوبهم للتقوى࣌ لهم مغفرة وأجر عظيم࣌', NULL, 515, 'local:warsh-text.json'),
  ('warsh-49-4', 'warsh', 49, 4, 'ࡴنَّ ࡰ۬لذِينَ يُنَادُونَكَ مِنْ وَّرَآءِ ࡴ۬لْحُجُرَٰتِ أَكْثَرُهُمْ لَا يَعْقِلُونَ࣌', 'ࡴن ࡰلذين ينادونك من وراء ࡴلحجرت أكثرهم لا يعقلون࣌', NULL, 515, 'local:warsh-text.json'),
  ('warsh-49-5', 'warsh', 49, 5, 'وَلَوَ ࡰنَّهُمْ صَبَرُواْ حَتَّىٰ تَخْرُجَ إِلَيْهِمْ لَكَانَ خَيْراࣰ لَّهُمْ࣌ وَاللَّهُ غَفُورࣱ رَّحِيمࣱ࣌', 'ولو ࡰنهم صبروا حتى تخرج إليهم لكان خيرا لهم࣌ والله غفور رحيم࣌', NULL, 516, 'local:warsh-text.json'),
  ('warsh-49-6', 'warsh', 49, 6, 'يَٰٓأَيُّهَا ࡰ۬لذِينَ ءَامَنُوٓاْ إِن جَآءَكُمْ فَاسِقُۢ بِنَبَإࣲ فَتَبَيَّنُوٓاْ أَن تُصِيبُواْ قَوْماَۢ بِجَهَٰلَةࣲ فَتُصْبِحُواْ عَلَىٰ مَا فَعَلْتُمْ نَٰدِمِينَ࣌', 'يأيها ࡰلذين ءامنوا إن جاءكم فاسق بنبإ فتبينوا أن تصيبوا قوما بجهلة فتصبحوا على ما فعلتم ندمين࣌', NULL, 516, 'local:warsh-text.json'),
  ('warsh-49-7', 'warsh', 49, 7, 'وَاعْلَمُوٓاْ أَنَّ فِيكُمْ رَسُولَ ࡰ۬للَّهِ لَوْ يُطِيعُكُمْ فِے كَثِيرࣲ مِّنَ ࡰ۬لَامْرِ لَعَنِتُّمْ࣌ وَلَٰكِنَّ ࡰ۬للَّهَ حَبَّبَ إِلَيْكُمُ ࡲ۬لِايمَٰنَ وَزَيَّنَهُۥ فِے قُلُوبِكُمْ وَكَرَّهَ إِلَيْكُمُ ࡲ۬لْكُفْرَ وَالْفُسُوقَ وَالْعِصْيَانَ࣌ أُوْلَٰٓئِكَ هُمُ ࡲ۬لرَّٰشِدُونَ', 'واعلموا أن فيكم رسول ࡰلله لو يطيعكم فے كثير من ࡰلامر لعنتم࣌ ولكن ࡰلله حبب إليكم ࡲلايمن وزينه فے قلوبكم وكره إليكم ࡲلكفر والفسوق والعصيان࣌ أولئك هم ࡲلرشدون', NULL, 516, 'local:warsh-text.json'),
  ('warsh-49-8', 'warsh', 49, 8, 'فَضْلاࣰ مِّنَ ࡰ۬للَّهِ وَنِعْمَةࣰ࣌ وَاللَّهُ عَلِيمٌ حَكِيمࣱ࣌', 'فضلا من ࡰلله ونعمة࣌ والله عليم حكيم࣌', NULL, 516, 'local:warsh-text.json'),
  ('warsh-49-9', 'warsh', 49, 9, '۞ وَإِن طَآئِفَتَٰنِ مِنَ ࡰ۬لْمُومِنِينَ ࡰٜقْتَتَلُواْ فَأَصْلِحُواْ بَيْنَهُمَا࣌ فَإِنۢ بَغَتِ ࡴحْدٜيٰهُمَا عَلَى ࡰ۬لُاخْرٜىٰ فَقَٰتِلُواْ ࡲ۬لتِے تَبْغِے حَتَّىٰ تَفِےٓءَ ࡹلَىٰٓ أَمْرِ ࡴ۬للَّهِ࣌ فَإِن فَآءَتْ فَأَصْلِحُواْ بَيْنَهُمَا بِالْعَدْلِ وَأَقْسِطُوٓاْ࣌ إِنَّ ࡰ۬للَّهَ يُحِبُّ ࡲ۬لْمُقْسِطِينَ࣌', 'وإن طائفتن من ࡰلمومنين ࡰقتتلوا فأصلحوا بينهما࣌ فإن بغت ࡴحديهما على ࡰلاخرى فقتلوا ࡲلتے تبغے حتى تفےء ࡹلى أمر ࡴلله࣌ فإن فاءت فأصلحوا بينهما بالعدل وأقسطوا࣌ إن ࡰلله يحب ࡲلمقسطين࣌', NULL, 516, 'local:warsh-text.json'),
  ('warsh-49-10', 'warsh', 49, 10, 'إِنَّمَا ࡰ۬لْمُومِنُونَ إِخْوَةࣱ فَأَصْلِحُواْ بَيْنَ أَخَوَيْكُمْ࣌ وَاتَّقُواْ ࡲ۬للَّهَ لَعَلَّكُمْ تُرْحَمُونَ࣌', 'إنما ࡰلمومنون إخوة فأصلحوا بين أخويكم࣌ واتقوا ࡲلله لعلكم ترحمون࣌', NULL, 516, 'local:warsh-text.json'),
  ('warsh-49-11', 'warsh', 49, 11, 'يَٰٓأَيُّهَا ࡰ۬لذِينَ ءَامَنُواْ لَا يَسْخَرْ قَوْمࣱ مِّن قَوْمٍ عَسٜىٰٓ أَنْ يَّكُونُواْ خَيْراࣰ مِّنْهُمْ وَلَا نِسَآءࣱ مِّن نِّسَآءٍ عَسٜىٰٓ أَنْ يَّكُنَّ خَيْراࣰ مِّنْهُنَّ࣌ وَلَا تَلْمِزُوٓاْ أَنفُسَكُمْ وَلَا تَنَابَزُواْ بِالَالْقَٰبِ࣌ بِيسَ ࡰ۬لِاسْمُ ࡲ۬لْفُسُوقُ بَعْدَ ࡰ۬لِايمَٰنِ࣌ وَمَن لَّمْ يَتُبْ فَأُوْلَٰٓئِكَ هُمُ ࡲ۬لظَّٰلِمُونَ࣌', 'يأيها ࡰلذين ءامنوا لا يسخر قوم من قوم عسى أن يكونوا خيرا منهم ولا نساء من نساء عسى أن يكن خيرا منهن࣌ ولا تلمزوا أنفسكم ولا تنابزوا بالالقب࣌ بيس ࡰلاسم ࡲلفسوق بعد ࡰلايمن࣌ ومن لم يتب فأولئك هم ࡲلظلمون࣌', NULL, 516, 'local:warsh-text.json'),
  ('warsh-49-12', 'warsh', 49, 12, 'يَٰٓأَيُّهَا ࡰ۬لذِينَ ءَامَنُواْ ࡲٜجْتَنِبُواْ كَثِيراࣰ مِّنَ ࡰ۬لظَّنِّ࣌ إِنَّ بَعْضَ ࡰ۬لظَّنِّ إِثْمࣱ࣌ وَلَا تَجَسَّسُواْ࣌ وَلَا يَغْتَب بَّعْضُكُم بَعْضاً࣌ ࡰيُحِبُّ أَحَدُكُمُۥٓ أَنْ يَّاكُلَ لَحْمَ أَخِيهِ مَيِّتاࣰ فَكَرِهْتُمُوهُ࣌ وَاتَّقُواْ ࡲ۬للَّهَ࣌ إِنَّ ࡰ۬للَّهَ تَوَّابࣱ رَّحِيمࣱ࣌', 'يأيها ࡰلذين ءامنوا ࡲجتنبوا كثيرا من ࡰلظن࣌ إن بعض ࡰلظن إثم࣌ ولا تجسسوا࣌ ولا يغتب بعضكم بعضا࣌ ࡰيحب أحدكم أن ياكل لحم أخيه ميتا فكرهتموه࣌ واتقوا ࡲلله࣌ إن ࡰلله تواب رحيم࣌', NULL, 517, 'local:warsh-text.json'),
  ('warsh-49-13', 'warsh', 49, 13, 'يَٰٓأَيُّهَا ࡰ۬لنَّاسُ إِنَّا خَلَقْنَٰكُم مِّن ذَكَرࣲ وَأُنثٜىٰ وَجَعَلْنَٰكُمْ شُعُوباࣰ وَقَبَآئِلَ لِتَعَارَفُوٓاْ࣌ إِنَّ أَكْرَمَكُمْ عِندَ ࡰ۬للَّهِ أَتْقٜيٰكُمُۥٓ࣌ إِنَّ ࡰ۬للَّهَ عَلِيمٌ خَبِيرࣱ࣌', 'يأيها ࡰلناس إنا خلقنكم من ذكر وأنثى وجعلنكم شعوبا وقبائل لتعارفوا࣌ إن أكرمكم عند ࡰلله أتقيكم࣌ إن ࡰلله عليم خبير࣌', NULL, 517, 'local:warsh-text.json'),
  ('warsh-49-14', 'warsh', 49, 14, '۞ قَالَتِ ࡴ۬لَاعْرَابُ ءَامَنَّا قُل لَّمْ تُومِنُواْ وَلَٰكِن قُولُوٓاْ أَسْلَمْنَا وَلَمَّا يَدْخُلِ ࡴ۬لِايمَٰنُ فِے قُلُوبِكُمْ࣌ وَإِن تُطِيعُواْ ࡲ۬للَّهَ وَرَسُولَهُۥ لَا يَلِتْكُم مِّنَ ࡰعْمَٰلِكُمْ شَيْـٔاً࣌ ࡴنَّ ࡰ۬للَّهَ غَفُورࣱ رَّحِيمٌ࣌', 'قالت ࡴلاعراب ءامنا قل لم تومنوا ولكن قولوا أسلمنا ولما يدخل ࡴلايمن فے قلوبكم࣌ وإن تطيعوا ࡲلله ورسوله لا يلتكم من ࡰعملكم شيا࣌ ࡴن ࡰلله غفور رحيم࣌', NULL, 517, 'local:warsh-text.json'),
  ('warsh-49-15', 'warsh', 49, 15, 'ࡴنَّمَا ࡰ۬لْمُومِنُونَ ࡰ۬لذِينَ ءَامَنُواْ بِاللَّهِ وَرَسُولِهِۦ ثُمَّ لَمْ يَرْتَابُواْ وَجَٰهَدُواْ بِأَمْوَٰلِهِمْ وَأَنفُسِهِمْ فِے سَبِيلِ ࡴ۬للَّهِ࣌ أُوْلَٰٓئِكَ هُمُ ࡲ۬لصَّٰدِقُونَ࣌', 'ࡴنما ࡰلمومنون ࡰلذين ءامنوا بالله ورسوله ثم لم يرتابوا وجهدوا بأمولهم وأنفسهم فے سبيل ࡴلله࣌ أولئك هم ࡲلصدقون࣌', NULL, 517, 'local:warsh-text.json'),
  ('warsh-49-16', 'warsh', 49, 16, 'قُلَ ࡰتُعَلِّمُونَ ࡰ۬للَّهَ بِدِينِكُمْ وَاللَّهُ يَعْلَمُ مَا فِے ࡴ۬لسَّمَٰوَٰتِ وَمَا فِے ࡴ۬لَارْضِ࣌ وَاللَّهُ بِكُلِّ شَےْءٍ عَلِيمࣱ࣌', 'قل ࡰتعلمون ࡰلله بدينكم والله يعلم ما فے ࡴلسموت وما فے ࡴلارض࣌ والله بكل شےء عليم࣌', NULL, 517, 'local:warsh-text.json'),
  ('warsh-49-17', 'warsh', 49, 17, 'يَمُنُّونَ عَلَيْكَ أَنَ ࡰسْلَمُواْ࣌ قُل لَّا تَمُنُّواْ عَلَيَّ إِسْلَٰمَكُم࣌ بَلِ ࡴ۬للَّهُ يَمُنُّ عَلَيْكُمُۥٓ أَنْ هَدٜيٰكُمْ لِلِايمَٰنِ إِن كُنتُمْ صَٰدِقِينَ࣌', 'يمنون عليك أن ࡰسلموا࣌ قل لا تمنوا علي إسلمكم࣌ بل ࡴلله يمن عليكم أن هديكم للايمن إن كنتم صدقين࣌', NULL, 517, 'local:warsh-text.json'),
  ('warsh-49-18', 'warsh', 49, 18, 'إِنَّ ࡰ۬للَّهَ يَعْلَمُ غَيْبَ ࡰ۬لسَّمَٰوَٰتِ وَالَارْضِ࣌ وَاللَّهُ بَصِيرُۢ بِمَا تَعْمَلُونَ࣌', 'إن ࡰلله يعلم غيب ࡰلسموت والارض࣌ والله بصير بما تعملون࣌', NULL, 517, 'local:warsh-text.json'),
  ('warsh-50-1', 'warsh', 50, 1, 'قَٓ࣌ وَالْقُرْءَانِ ࡴ۬لْمَجِيدِ', 'ق࣌ والقرءان ࡴلمجيد', NULL, 518, 'local:warsh-text.json'),
  ('warsh-50-2', 'warsh', 50, 2, 'بَلْ عَجِبُوٓاْ أَن جَآءَهُم مُّنذِرࣱ مِّنْهُمْ فَقَالَ ࡰ۬لْكَٰفِرُونَ هَٰذَا شَےْءٌ عَجِيبٌ', 'بل عجبوا أن جاءهم منذر منهم فقال ࡰلكفرون هذا شےء عجيب', NULL, 518, 'local:warsh-text.json'),
  ('warsh-50-3', 'warsh', 50, 3, 'ࡰࢇذَا مِتْنَا وَكُنَّا تُرَاباࣰ ذَٰلِكَ رَجْعُۢ بَعِيدࣱ࣌', 'ࡰࢇذا متنا وكنا ترابا ذلك رجع بعيد࣌', NULL, 518, 'local:warsh-text.json'),
  ('warsh-50-4', 'warsh', 50, 4, 'قَدْ عَلِمْنَا مَا تَنقُصُ ࡲ۬لَارْضُ مِنْهُمْ وَعِندَنَا كِتَٰبٌ حَفِيظُۢ࣌', 'قد علمنا ما تنقص ࡲلارض منهم وعندنا كتب حفيظ࣌', NULL, 518, 'local:warsh-text.json'),
  ('warsh-50-5', 'warsh', 50, 5, 'بَلْ كَذَّبُواْ بِالْحَقِّ لَمَّا جَآءَهُمْ فَهُمْ فِےٓ أَمْرࣲ مَّرِيجٍ࣌', 'بل كذبوا بالحق لما جاءهم فهم فے أمر مريج࣌', NULL, 518, 'local:warsh-text.json'),
  ('warsh-50-6', 'warsh', 50, 6, 'ࡰفَلَمْ يَنظُرُوٓاْ إِلَى ࡰ۬لسَّمَآءِ فَوْقَهُمْ كَيْفَ بَنَيْنَٰهَا وَزَيَّنَّٰهَا وَمَا لَهَا مِن فُرُوجࣲ࣌', 'ࡰفلم ينظروا إلى ࡰلسماء فوقهم كيف بنينها وزينها وما لها من فروج࣌', NULL, 518, 'local:warsh-text.json'),
  ('warsh-50-7', 'warsh', 50, 7, 'وَالَارْضَ مَدَدْنَٰهَا وَأَلْقَيْنَا فِيهَا رَوَٰسِيَ وَأَنۢبَتْنَا فِيهَا مِن كُلِّ زَوْجِۢ بَهِيجࣲ', 'والارض مددنها وألقينا فيها روسي وأنبتنا فيها من كل زوج بهيج', NULL, 518, 'local:warsh-text.json'),
  ('warsh-50-8', 'warsh', 50, 8, 'تَبْصِرَةࣰ وَذِكْرٜىٰ لِكُلِّ عَبْدࣲ مُّنِيبࣲ࣌', 'تبصرة وذكرى لكل عبد منيب࣌', NULL, 518, 'local:warsh-text.json'),
  ('warsh-50-9', 'warsh', 50, 9, '۞ وَنَزَّلْنَا مِنَ ࡰ۬لسَّمَآءِ مَآءࣰ مُّبَٰرَكاࣰ فَأَنۢبَتْنَا بِهِۦ جَنَّٰتࣲ وَحَبَّ ࡰ۬لْحَصِيدِ', 'ونزلنا من ࡰلسماء ماء مبركا فأنبتنا به جنت وحب ࡰلحصيد', NULL, 518, 'local:warsh-text.json'),
  ('warsh-50-10', 'warsh', 50, 10, 'وَالنَّخْلَ بَاسِقَٰتࣲ لَّهَا طَلْعࣱ نَّضِيدࣱ', 'والنخل باسقت لها طلع نضيد', NULL, 518, 'local:warsh-text.json'),
  ('warsh-50-11', 'warsh', 50, 11, 'رِّزْقاࣰ لِّلْعِبَادِ࣌ وَأَحْيَيْنَا بِهِۦ بَلْدَةࣰ مَّيْتاࣰ࣌ كَذَٰلِكَ ࡰ۬لْخُرُوجُ࣌', 'رزقا للعباد࣌ وأحيينا به بلدة ميتا࣌ كذلك ࡰلخروج࣌', NULL, 518, 'local:warsh-text.json'),
  ('warsh-50-12', 'warsh', 50, 12, 'كَذَّبَتْ قَبْلَهُمْ قَوْمُ نُوحࣲ وَأَصْحَٰبُ ࡲ۬لرَّسِّ وَثَمُودُ', 'كذبت قبلهم قوم نوح وأصحب ࡲلرس وثمود', NULL, 518, 'local:warsh-text.json'),
  ('warsh-50-13', 'warsh', 50, 13, 'وَعَادࣱ وَفِرْعَوْنُ وَإِخْوَٰنُ لُوطࣲ', 'وعاد وفرعون وإخون لوط', NULL, 518, 'local:warsh-text.json'),
  ('warsh-50-14', 'warsh', 50, 14, 'وَأَصْحَٰبُ ࡲ۬لَايْكَةِ وَقَوْمُ تُبَّعࣲ࣌ كُلࣱّ كَذَّبَ ࡰ۬لرُّسُلَ فَحَقَّ وَعِيدِۦٓ࣌', 'وأصحب ࡲلايكة وقوم تبع࣌ كل كذب ࡰلرسل فحق وعيد࣌', NULL, 518, 'local:warsh-text.json'),
  ('warsh-50-15', 'warsh', 50, 15, 'أَفَعَيِينَا بِالْخَلْقِ ࡴ۬لَاوَّلِ࣌ بَلْ هُمْ فِے لَبْسࣲ مِّنْ خَلْقࣲ جَدِيدࣲ࣌', 'أفعيينا بالخلق ࡴلاول࣌ بل هم فے لبس من خلق جديد࣌', NULL, 518, 'local:warsh-text.json'),
  ('warsh-50-16', 'warsh', 50, 16, 'وَلَقَدْ خَلَقْنَا ࡰ۬لِانسَٰنَ وَنَعْلَمُ مَا تُوَسْوِسُ بِهِۦ نَفْسُهُۥ وَنَحْنُ أَقْرَبُ إِلَيْهِ مِنْ حَبْلِ ࡴ۬لْوَرِيدِ࣌', 'ولقد خلقنا ࡰلانسن ونعلم ما توسوس به نفسه ونحن أقرب إليه من حبل ࡴلوريد࣌', NULL, 519, 'local:warsh-text.json'),
  ('warsh-50-17', 'warsh', 50, 17, 'إِذْ يَتَلَقَّى ࡰ۬لْمُتَلَقِّيَٰنِ عَنِ ࡴ۬لْيَمِينِ وَعَنِ ࡴ۬لشِّمَالِ قَعِيدࣱ࣌', 'إذ يتلقى ࡰلمتلقين عن ࡴليمين وعن ࡴلشمال قعيد࣌', NULL, 519, 'local:warsh-text.json'),
  ('warsh-50-18', 'warsh', 50, 18, 'مَّا يَلْفِظُ مِن قَوْلٍ ࡴلَّا لَدَيْهِ رَقِيبٌ عَتِيدࣱ࣌', 'ما يلفظ من قول ࡴلا لديه رقيب عتيد࣌', NULL, 519, 'local:warsh-text.json'),
  ('warsh-50-19', 'warsh', 50, 19, 'وَجَآءَتْ سَكْرَةُ ࡲ۬لْمَوْتِ بِالْحَقِّ࣌ ذَٰلِكَ مَا كُنتَ مِنْهُ تَحِيدُ࣌', 'وجاءت سكرة ࡲلموت بالحق࣌ ذلك ما كنت منه تحيد࣌', NULL, 519, 'local:warsh-text.json'),
  ('warsh-50-20', 'warsh', 50, 20, 'وَنُفِخَ فِے ࡴ۬لصُّورِ࣌ ذَٰلِكَ يَوْمُ ࡲ۬لْوَعِيدِ࣌', 'ونفخ فے ࡴلصور࣌ ذلك يوم ࡲلوعيد࣌', NULL, 519, 'local:warsh-text.json'),
  ('warsh-50-21', 'warsh', 50, 21, 'وَجَآءَتْ كُلُّ نَفْسࣲ مَّعَهَا سَآئِقࣱ وَشَهِيدࣱ࣌', 'وجاءت كل نفس معها سائق وشهيد࣌', NULL, 519, 'local:warsh-text.json'),
  ('warsh-50-22', 'warsh', 50, 22, 'لَّقَدْ كُنتَ فِے غَفْلَةࣲ مِّنْ هَٰذَا فَكَشَفْنَا عَنكَ غِطَآءَكَ فَبَصَرُكَ ࡰ۬لْيَوْمَ حَدِيدࣱ࣌', 'لقد كنت فے غفلة من هذا فكشفنا عنك غطاءك فبصرك ࡰليوم حديد࣌', NULL, 519, 'local:warsh-text.json'),
  ('warsh-50-23', 'warsh', 50, 23, 'وَقَالَ قَرِينُهُۥ هَٰذَا مَا لَدَيَّ عَتِيدٌ࣌', 'وقال قرينه هذا ما لدي عتيد࣌', NULL, 519, 'local:warsh-text.json'),
  ('warsh-50-24', 'warsh', 50, 24, 'ࡰلْقِيَا فِے جَهَنَّمَ كُلَّ كَفّٜارٍ عَنِيدࣲ', 'ࡰلقيا فے جهنم كل كفار عنيد', NULL, 519, 'local:warsh-text.json'),
  ('warsh-50-25', 'warsh', 50, 25, 'مَّنَّاعࣲ لِّلْخَيْرِ مُعْتَدࣲ مُّرِيبٍ', 'مناع للخير معتد مريب', NULL, 519, 'local:warsh-text.json'),
  ('warsh-50-26', 'warsh', 50, 26, 'ࡴ۬لذِے جَعَلَ مَعَ ࡰ۬للَّهِ إِلَٰهاً اٰخَرَ فَأَلْقِيَٰهُ فِے ࡴ۬لْعَذَابِ ࡴ۬لشَّدِيدِ࣌', 'ࡴلذے جعل مع ࡰلله إلها اخر فألقيه فے ࡴلعذاب ࡴلشديد࣌', NULL, 519, 'local:warsh-text.json'),
  ('warsh-50-27', 'warsh', 50, 27, '۞ قَالَ قَرِينُهُۥ رَبَّنَا مَآ أَطْغَيْتُهُۥ وَلَٰكِن كَانَ فِے ضَلَٰلِۢ بَعِيدࣲ࣌', 'قال قرينه ربنا ما أطغيته ولكن كان فے ضلل بعيد࣌', NULL, 519, 'local:warsh-text.json'),
  ('warsh-50-28', 'warsh', 50, 28, 'قَالَ لَا تَخْتَصِمُواْ لَدَيَّ وَقَدْ قَدَّمْتُ إِلَيْكُم بِالْوَعِيدِ࣌', 'قال لا تختصموا لدي وقد قدمت إليكم بالوعيد࣌', NULL, 519, 'local:warsh-text.json'),
  ('warsh-50-29', 'warsh', 50, 29, 'مَا يُبَدَّلُ ࡲ۬لْقَوْلُ لَدَيَّ وَمَآ أَنَا بِظَلَّٰمࣲ لِّلْعَبِيدِ࣌', 'ما يبدل ࡲلقول لدي وما أنا بظلم للعبيد࣌', NULL, 519, 'local:warsh-text.json'),
  ('warsh-50-30', 'warsh', 50, 30, 'يَوْمَ يَقُولُ لِجَهَنَّمَ هَلِ ࡴٜمْتَلَأْتِ وَتَقُولُ هَلْ مِن مَّزِيدࣲ࣌', 'يوم يقول لجهنم هل ࡴمتلأت وتقول هل من مزيد࣌', NULL, 519, 'local:warsh-text.json'),
  ('warsh-50-31', 'warsh', 50, 31, 'وَأُزْلِفَتِ ࡴ۬لْجَنَّةُ لِلْمُتَّقِينَ غَيْرَ بَعِيدٍ࣌', 'وأزلفت ࡴلجنة للمتقين غير بعيد࣌', NULL, 519, 'local:warsh-text.json'),
  ('warsh-50-32', 'warsh', 50, 32, 'هَٰذَا مَا تُوعَدُونَ لِكُلِّ أَوَّابٍ حَفِيظࣲ࣌', 'هذا ما توعدون لكل أواب حفيظ࣌', NULL, 519, 'local:warsh-text.json'),
  ('warsh-50-33', 'warsh', 50, 33, 'مَّنْ خَشِيَ ࡰ۬لرَّحْمَٰنَ بِالْغَيْبِ وَجَآءَ بِقَلْبࣲ مُّنِيبٍ', 'من خشي ࡰلرحمن بالغيب وجاء بقلب منيب', NULL, 519, 'local:warsh-text.json'),
  ('warsh-50-34', 'warsh', 50, 34, 'ࡲ࢈دْخُلُوهَا بِسَلَٰمࣲ࣌ ذَٰلِكَ يَوْمُ ࡲ۬لْخُلُودِ࣌', 'ࡲ࢈دخلوها بسلم࣌ ذلك يوم ࡲلخلود࣌', NULL, 519, 'local:warsh-text.json'),
  ('warsh-50-35', 'warsh', 50, 35, 'لَهُم مَّا يَشَآءُونَ فِيهَا࣌ وَلَدَيْنَا مَزِيدࣱ࣌', 'لهم ما يشاءون فيها࣌ ولدينا مزيد࣌', NULL, 519, 'local:warsh-text.json'),
  ('warsh-50-36', 'warsh', 50, 36, 'وَكَمَ ࡰهْلَكْنَا قَبْلَهُم مِّن قَرْنٍ هُمُۥٓ أَشَدُّ مِنْهُم بَطْشاࣰ فَنَقَّبُواْ فِے ࡴ۬لْبِلَٰدِ࣌ هَلْ مِن مَّحِيصٍ࣌', 'وكم ࡰهلكنا قبلهم من قرن هم أشد منهم بطشا فنقبوا فے ࡴلبلد࣌ هل من محيص࣌', NULL, 520, 'local:warsh-text.json'),
  ('warsh-50-37', 'warsh', 50, 37, 'ࡴنَّ فِے ذَٰلِكَ لَذِكْرٜىٰ لِمَن كَانَ لَهُۥ قَلْبٌ ࡰوَ ࡰلْقَى ࡰ۬لسَّمْعَ وَهُوَ شَهِيدࣱ࣌', 'ࡴن فے ذلك لذكرى لمن كان له قلب ࡰو ࡰلقى ࡰلسمع وهو شهيد࣌', NULL, 520, 'local:warsh-text.json'),
  ('warsh-50-38', 'warsh', 50, 38, 'وَلَقَدْ خَلَقْنَا ࡰ۬لسَّمَٰوَٰتِ وَالَارْضَ وَمَا بَيْنَهُمَا فِے سِتَّةِ أَيَّامࣲ وَمَا مَسَّنَا مِن لُّغُوبࣲ࣌', 'ولقد خلقنا ࡰلسموت والارض وما بينهما فے ستة أيام وما مسنا من لغوب࣌', NULL, 520, 'local:warsh-text.json'),
  ('warsh-50-39', 'warsh', 50, 39, 'فَاصْبِرْ عَلَىٰ مَا يَقُولُونَ࣌ وَسَبِّحْ بِحَمْدِ رَبِّكَ قَبْلَ طُلُوعِ ࡴ۬لشَّمْسِ وَقَبْلَ ࡰ۬لْغُرُوبِ࣌', 'فاصبر على ما يقولون࣌ وسبح بحمد ربك قبل طلوع ࡴلشمس وقبل ࡰلغروب࣌', NULL, 520, 'local:warsh-text.json'),
  ('warsh-50-40', 'warsh', 50, 40, 'وَمِنَ ࡰ۬ليْلِ فَسَبِّحْهُ وَإِدْبَٰرَ ࡰ۬لسُّجُودِ࣌', 'ومن ࡰليل فسبحه وإدبر ࡰلسجود࣌', NULL, 520, 'local:warsh-text.json'),
  ('warsh-50-41', 'warsh', 50, 41, 'وَاسْتَمِعْ يَوْمَ يُنَادِ ࡴ۬لْمُنَادِۦ مِن مَّكَانࣲ قَرِيبࣲ', 'واستمع يوم يناد ࡴلمناد من مكان قريب', NULL, 520, 'local:warsh-text.json'),
  ('warsh-50-42', 'warsh', 50, 42, 'يَوْمَ يَسْمَعُونَ ࡰ۬لصَّيْحَةَ بِالْحَقِّ࣌ ذَٰلِكَ يَوْمُ ࡲ۬لْخُرُوجِ࣌', 'يوم يسمعون ࡰلصيحة بالحق࣌ ذلك يوم ࡲلخروج࣌', NULL, 520, 'local:warsh-text.json'),
  ('warsh-50-43', 'warsh', 50, 43, 'إِنَّا نَحْنُ نُحْيِۦ وَنُمِيتُ وَإِلَيْنَا ࡰ۬لْمَصِيرُ࣌', 'إنا نحن نحي ونميت وإلينا ࡰلمصير࣌', NULL, 520, 'local:warsh-text.json'),
  ('warsh-50-44', 'warsh', 50, 44, 'يَوْمَ تَشَّقَّقُ ࡲ۬لَارْضُ عَنْهُمْ سِرَاعاࣰ࣌ ذَٰلِكَ حَشْرٌ عَلَيْنَا يَسِيرࣱ࣌', 'يوم تشقق ࡲلارض عنهم سراعا࣌ ذلك حشر علينا يسير࣌', NULL, 520, 'local:warsh-text.json'),
  ('warsh-50-45', 'warsh', 50, 45, 'نَّحْنُ أَعْلَمُ بِمَا يَقُولُونَ࣌ وَمَآ أَنتَ عَلَيْهِم بِجَبّٜارࣲ࣌ فَذَكِّرْ بِالْقُرْءَانِ مَنْ يَّخَافُ وَعِيدِۦ࣌', 'نحن أعلم بما يقولون࣌ وما أنت عليهم بجبار࣌ فذكر بالقرءان من يخاف وعيد࣌', NULL, 520, 'local:warsh-text.json'),
  ('warsh-51-1', 'warsh', 51, 1, 'وَالذَّٰرِيَٰتِ ذَرْواࣰ', 'والذريت ذروا', NULL, 520, 'local:warsh-text.json'),
  ('warsh-51-2', 'warsh', 51, 2, 'فَالْحَٰمِلَٰتِ وِقْراࣰ', 'فالحملت وقرا', NULL, 520, 'local:warsh-text.json'),
  ('warsh-51-3', 'warsh', 51, 3, 'فَالْجَٰرِيَٰتِ يُسْراࣰ', 'فالجريت يسرا', NULL, 520, 'local:warsh-text.json'),
  ('warsh-51-4', 'warsh', 51, 4, 'فَالْمُقَسِّمَٰتِ أَمْراً', 'فالمقسمت أمرا', NULL, 520, 'local:warsh-text.json'),
  ('warsh-51-5', 'warsh', 51, 5, 'ࡴنَّمَا تُوعَدُونَ لَصَادِقࣱ', 'ࡴنما توعدون لصادق', NULL, 520, 'local:warsh-text.json'),
  ('warsh-51-6', 'warsh', 51, 6, 'وَإِنَّ ࡰ۬لدِّينَ لَوَٰقِعࣱ࣌', 'وإن ࡰلدين لوقع࣌', NULL, 520, 'local:warsh-text.json'),
  ('warsh-51-7', 'warsh', 51, 7, 'وَالسَّمَآءِ ذَاتِ ࡴ۬لْحُبُكِ', 'والسماء ذات ࡴلحبك', NULL, 521, 'local:warsh-text.json'),
  ('warsh-51-8', 'warsh', 51, 8, 'إِنَّكُمْ لَفِے قَوْلࣲ مُّخْتَلِفࣲ', 'إنكم لفے قول مختلف', NULL, 521, 'local:warsh-text.json'),
  ('warsh-51-9', 'warsh', 51, 9, 'يُوفَكُ عَنْهُ مَنُ ࡳفِكَ࣌', 'يوفك عنه من ࡳفك࣌', NULL, 521, 'local:warsh-text.json'),
  ('warsh-51-10', 'warsh', 51, 10, 'قُتِلَ ࡰ۬لْخَرَّٰصُونَ', 'قتل ࡰلخرصون', NULL, 521, 'local:warsh-text.json'),
  ('warsh-51-11', 'warsh', 51, 11, 'ࡰ۬لذِينَ هُمْ فِے غَمْرَةࣲ سَاهُونَ࣌', 'ࡰلذين هم فے غمرة ساهون࣌', NULL, 521, 'local:warsh-text.json'),
  ('warsh-51-12', 'warsh', 51, 12, 'يَسْـَٔلُونَ أَيَّانَ يَوْمُ ࡲ۬لدِّينِ', 'يسلون أيان يوم ࡲلدين', NULL, 521, 'local:warsh-text.json'),
  ('warsh-51-13', 'warsh', 51, 13, 'يَوْمَ هُمْ عَلَى ࡰ۬لنّٜارِ يُفْتَنُونَ࣌', 'يوم هم على ࡰلنار يفتنون࣌', NULL, 521, 'local:warsh-text.json'),
  ('warsh-51-14', 'warsh', 51, 14, 'ذُوقُواْ فِتْنَتَكُمْ࣌ هَٰذَا ࡰ۬لذِے كُنتُم بِهِۦ تَسْتَعْجِلُونَ࣌', 'ذوقوا فتنتكم࣌ هذا ࡰلذے كنتم به تستعجلون࣌', NULL, 521, 'local:warsh-text.json'),
  ('warsh-51-15', 'warsh', 51, 15, 'إِنَّ ࡰ۬لْمُتَّقِينَ فِے جَنَّٰتࣲ وَعُيُونٍ', 'إن ࡰلمتقين فے جنت وعيون', NULL, 521, 'local:warsh-text.json'),
  ('warsh-51-16', 'warsh', 51, 16, 'اٰخِذِينَ مَآ ءَاتٜيٰهُمْ رَبُّهُمُۥٓ࣌ إِنَّهُمْ كَانُواْ قَبْلَ ذَٰلِكَ مُحْسِنِينَ࣌', 'اخذين ما ءاتيهم ربهم࣌ إنهم كانوا قبل ذلك محسنين࣌', NULL, 521, 'local:warsh-text.json'),
  ('warsh-51-17', 'warsh', 51, 17, 'كَانُواْ قَلِيلاࣰ࣌ مِّنَ ࡰ۬ليْلِ مَا يَهْجَعُونَ࣌', 'كانوا قليلا࣌ من ࡰليل ما يهجعون࣌', NULL, 521, 'local:warsh-text.json'),
  ('warsh-51-18', 'warsh', 51, 18, 'وَبِالَاسْحٜارِ هُمْ يَسْتَغْفِرُونَ࣌', 'وبالاسحار هم يستغفرون࣌', NULL, 521, 'local:warsh-text.json'),
  ('warsh-51-19', 'warsh', 51, 19, 'وَفِےٓ أَمْوَٰلِهِمْ حَقࣱّ لِّلسَّآئِلِ وَالْمَحْرُومِ࣌', 'وفے أمولهم حق للسائل والمحروم࣌', NULL, 521, 'local:warsh-text.json'),
  ('warsh-51-20', 'warsh', 51, 20, 'وَفِے ࡴ۬لَارْضِ ءَايَٰتࣱ لِّلْمُوقِنِينَ࣌', 'وفے ࡴلارض ءايت للموقنين࣌', NULL, 521, 'local:warsh-text.json'),
  ('warsh-51-21', 'warsh', 51, 21, 'وَفِےٓ أَنفُسِكُمُۥٓ࣌ أَفَلَا تُبْصِرُونَ࣌', 'وفے أنفسكم࣌ أفلا تبصرون࣌', NULL, 521, 'local:warsh-text.json'),
  ('warsh-51-22', 'warsh', 51, 22, 'وَفِے ࡴ۬لسَّمَآءِ رِزْقُكُمْ࣌ وَمَا تُوعَدُونَ', 'وفے ࡴلسماء رزقكم࣌ وما توعدون', NULL, 521, 'local:warsh-text.json'),
  ('warsh-51-23', 'warsh', 51, 23, 'فَوَرَبِّ ࡴ۬لسَّمَآءِ وَالَارْضِ إِنَّهُۥ لَحَقࣱّ مِّثْلَ مَآ أَنَّكُمْ تَنطِقُونَ࣌', 'فورب ࡴلسماء والارض إنه لحق مثل ما أنكم تنطقون࣌', NULL, 521, 'local:warsh-text.json'),
  ('warsh-51-24', 'warsh', 51, 24, 'هَلَ ࡰتٜيٰكَ حَدِيثُ ضَيْفِ إِبْرَٰهِيمَ ࡰ۬لْمُكْرَمِينَ', 'هل ࡰتيك حديث ضيف إبرهيم ࡰلمكرمين', NULL, 521, 'local:warsh-text.json'),
  ('warsh-51-25', 'warsh', 51, 25, 'إِذْ دَخَلُواْ عَلَيْهِ فَقَالُواْ سَلَٰماࣰ࣌ قَالَ سَلَٰمࣱ࣌ قَوْمࣱ مُّنكَرُونَ࣌', 'إذ دخلوا عليه فقالوا سلما࣌ قال سلم࣌ قوم منكرون࣌', NULL, 521, 'local:warsh-text.json'),
  ('warsh-51-26', 'warsh', 51, 26, 'فَرَاغَ إِلَىٰٓ أَهْلِهِۦ فَجَآءَ بِعِجْلࣲ سَمِينࣲ', 'فراغ إلى أهله فجاء بعجل سمين', NULL, 521, 'local:warsh-text.json'),
  ('warsh-51-27', 'warsh', 51, 27, 'فَقَرَّبَهُۥٓ إِلَيْهِمْ قَالَ أَلَا تَاكُلُونَ࣌', 'فقربه إليهم قال ألا تاكلون࣌', NULL, 521, 'local:warsh-text.json'),
  ('warsh-51-28', 'warsh', 51, 28, 'فَأَوْجَسَ مِنْهُمْ خِيفَةࣰ࣌ قَالُواْ لَا تَخَفْ࣌ وَبَشَّرُوهُ بِغُلَٰمٍ عَلِيمࣲ࣌', 'فأوجس منهم خيفة࣌ قالوا لا تخف࣌ وبشروه بغلم عليم࣌', NULL, 521, 'local:warsh-text.json'),
  ('warsh-51-29', 'warsh', 51, 29, 'فَأَقْبَلَتِ ࡴٜمْرَأَتُهُۥ فِے صَرَّةࣲ فَصَكَّتْ وَجْهَهَا وَقَالَتْ عَجُوزٌ عَقِيمࣱ࣌', 'فأقبلت ࡴمرأته فے صرة فصكت وجهها وقالت عجوز عقيم࣌', NULL, 521, 'local:warsh-text.json'),
  ('warsh-51-30', 'warsh', 51, 30, 'قَالُواْ كَذَٰلِكِ قَالَ رَبُّكِ࣌ إِنَّهُۥ هُوَ ࡰ۬لْحَكِيمُ ࡲ۬لْعَلِيمُ࣌', 'قالوا كذلك قال ربك࣌ إنه هو ࡰلحكيم ࡲلعليم࣌', NULL, 521, 'local:warsh-text.json'),
  ('warsh-51-31', 'warsh', 51, 31, '۞ قَالَ فَمَا خَطْبُكُمُۥٓ أَيُّهَا ࡰ۬لْمُرْسَلُونَ࣌', 'قال فما خطبكم أيها ࡰلمرسلون࣌', NULL, 522, 'local:warsh-text.json'),
  ('warsh-51-32', 'warsh', 51, 32, 'قَالُوٓاْ إِنَّآ أُرْسِلْنَآ إِلَىٰ قَوْمࣲ مُّجْرِمِينَ', 'قالوا إنا أرسلنا إلى قوم مجرمين', NULL, 522, 'local:warsh-text.json'),
  ('warsh-51-33', 'warsh', 51, 33, 'لِنُرْسِلَ عَلَيْهِمْ حِجَارَةࣰ مِّن طِينࣲ', 'لنرسل عليهم حجارة من طين', NULL, 522, 'local:warsh-text.json'),
  ('warsh-51-34', 'warsh', 51, 34, 'مُّسَوَّمَةً عِندَ رَبِّكَ لِلْمُسْرِفِينَ࣌', 'مسومة عند ربك للمسرفين࣌', NULL, 522, 'local:warsh-text.json'),
  ('warsh-51-35', 'warsh', 51, 35, 'فَأَخْرَجْنَا مَن كَانَ فِيهَا مِنَ ࡰ۬لْمُومِنِينَ', 'فأخرجنا من كان فيها من ࡰلمومنين', NULL, 522, 'local:warsh-text.json'),
  ('warsh-51-36', 'warsh', 51, 36, 'فَمَا وَجَدْنَا فِيهَا غَيْرَ بَيْتࣲ مِّنَ ࡰ۬لْمُسْلِمِينَ', 'فما وجدنا فيها غير بيت من ࡰلمسلمين', NULL, 522, 'local:warsh-text.json'),
  ('warsh-51-37', 'warsh', 51, 37, 'وَتَرَكْنَا فِيهَآ ءَايَةࣰ لِّلذِينَ يَخَافُونَ ࡰ۬لْعَذَابَ ࡰ۬لَالِيمَ࣌', 'وتركنا فيها ءاية للذين يخافون ࡰلعذاب ࡰلاليم࣌', NULL, 522, 'local:warsh-text.json'),
  ('warsh-51-38', 'warsh', 51, 38, 'وَفِے مُوسٜىٰٓ إِذَ ࡰرْسَلْنَٰهُ إِلَىٰ فِرْعَوْنَ بِسُلْطَٰنࣲ مُّبِينࣲ', 'وفے موسى إذ ࡰرسلنه إلى فرعون بسلطن مبين', NULL, 522, 'local:warsh-text.json'),
  ('warsh-51-39', 'warsh', 51, 39, 'فَتَوَلّٜىٰ بِرُكْنِهِۦ وَقَالَ سَٰحِرٌ ࡰوْ مَجْنُونࣱ࣌', 'فتولى بركنه وقال سحر ࡰو مجنون࣌', NULL, 522, 'local:warsh-text.json'),
  ('warsh-51-40', 'warsh', 51, 40, 'فَأَخَذْنَٰهُ وَجُنُودَهُۥ فَنَبَذْنَٰهُمْ فِے ࡴ۬لْيَمِّ وَهُوَ مُلِيمࣱ࣌', 'فأخذنه وجنوده فنبذنهم فے ࡴليم وهو مليم࣌', NULL, 522, 'local:warsh-text.json'),
  ('warsh-51-41', 'warsh', 51, 41, 'وَفِے عَادٍ ࡴذَ ࡰرْسَلْنَا عَلَيْهِمُ ࡲ۬لرِّيحَ ࡰ۬لْعَقِيمَ', 'وفے عاد ࡴذ ࡰرسلنا عليهم ࡲلريح ࡰلعقيم', NULL, 522, 'local:warsh-text.json'),
  ('warsh-51-42', 'warsh', 51, 42, 'مَا تَذَرُ مِن شَےْءٍ ࡰتَتْ عَلَيْهِ إِلَّا جَعَلَتْهُ كَالرَّمِيمِ࣌', 'ما تذر من شےء ࡰتت عليه إلا جعلته كالرميم࣌', NULL, 522, 'local:warsh-text.json'),
  ('warsh-51-43', 'warsh', 51, 43, 'وَفِے ثَمُودَ إِذْ قِيلَ لَهُمْ تَمَتَّعُواْ حَتَّىٰ حِينࣲ', 'وفے ثمود إذ قيل لهم تمتعوا حتى حين', NULL, 522, 'local:warsh-text.json'),
  ('warsh-51-44', 'warsh', 51, 44, 'فَعَتَوْاْ عَنَ ࡰمْرِ رَبِّهِمْ فَأَخَذَتْهُمُ ࡲ۬لصَّٰعِقَةُ وَهُمْ يَنظُرُونَ࣌', 'فعتوا عن ࡰمر ربهم فأخذتهم ࡲلصعقة وهم ينظرون࣌', NULL, 522, 'local:warsh-text.json'),
  ('warsh-51-45', 'warsh', 51, 45, 'فَمَا ࡰٜسْتَطَٰعُواْ مِن قِيَامࣲ وَمَا كَانُواْ مُنتَصِرِينَ࣌', 'فما ࡰستطعوا من قيام وما كانوا منتصرين࣌', NULL, 522, 'local:warsh-text.json'),
  ('warsh-51-46', 'warsh', 51, 46, 'وَقَوْمَ نُوحࣲ مِّن قَبْلُ࣌ إِنَّهُمْ كَانُواْ قَوْماࣰ فَٰسِقِينَ࣌', 'وقوم نوح من قبل࣌ إنهم كانوا قوما فسقين࣌', NULL, 522, 'local:warsh-text.json'),
  ('warsh-51-47', 'warsh', 51, 47, 'وَالسَّمَآءَ بَنَيْنَٰهَا بِأَيَيْدࣲ࣌ وَإِنَّا لَمُوسِعُونَ࣌', 'والسماء بنينها بأييد࣌ وإنا لموسعون࣌', NULL, 522, 'local:warsh-text.json'),
  ('warsh-51-48', 'warsh', 51, 48, 'وَالَارْضَ فَرَشْنَٰهَا࣌ فَنِعْمَ ࡰ۬لْمَٰهِدُونَ࣌', 'والارض فرشنها࣌ فنعم ࡰلمهدون࣌', NULL, 522, 'local:warsh-text.json'),
  ('warsh-51-49', 'warsh', 51, 49, 'وَمِن كُلِّ شَےْءٍ خَلَقْنَا زَوْجَيْنِ لَعَلَّكُمْ تَذَّكَّرُونَ࣌', 'ومن كل شےء خلقنا زوجين لعلكم تذكرون࣌', NULL, 522, 'local:warsh-text.json'),
  ('warsh-51-50', 'warsh', 51, 50, 'فَفِرُّوٓاْ إِلَى ࡰ۬للَّهِ إِنِّے لَكُم مِّنْهُ نَذِيرࣱ مُّبِينࣱ࣌', 'ففروا إلى ࡰلله إنے لكم منه نذير مبين࣌', NULL, 522, 'local:warsh-text.json'),
  ('warsh-51-51', 'warsh', 51, 51, 'وَلَا تَجْعَلُواْ مَعَ ࡰ۬للَّهِ إِلَٰهاً اٰخَرَ إِنِّے لَكُم مِّنْهُ نَذِيرࣱ مُّبِينࣱ࣌', 'ولا تجعلوا مع ࡰلله إلها اخر إنے لكم منه نذير مبين࣌', NULL, 522, 'local:warsh-text.json'),
  ('warsh-51-52', 'warsh', 51, 52, 'كَذَٰلِكَ࣌ مَآ أَتَى ࡰ۬لذِينَ مِن قَبْلِهِم مِّن رَّسُولٍ ࡴلَّا قَالُواْ سَاحِرٌ ࡰوْ مَجْنُونٌ࣌', 'كذلك࣌ ما أتى ࡰلذين من قبلهم من رسول ࡴلا قالوا ساحر ࡰو مجنون࣌', NULL, 523, 'local:warsh-text.json'),
  ('warsh-51-53', 'warsh', 51, 53, 'ࡰتَوَاصَوْاْ بِهِۦ࣌ بَلْ هُمْ قَوْمࣱ طَاغُونَ࣌', 'ࡰتواصوا به࣌ بل هم قوم طاغون࣌', NULL, 523, 'local:warsh-text.json'),
  ('warsh-51-54', 'warsh', 51, 54, 'فَتَوَلَّ عَنْهُمْ فَمَآ أَنتَ بِمَلُومࣲ', 'فتول عنهم فما أنت بملوم', NULL, 523, 'local:warsh-text.json'),
  ('warsh-51-55', 'warsh', 51, 55, 'وَذَكِّرْ࣌ فَإِنَّ ࡰ۬لذِّكْرٜىٰ تَنفَعُ ࡲ۬لْمُومِنِينَ࣌', 'وذكر࣌ فإن ࡰلذكرى تنفع ࡲلمومنين࣌', NULL, 523, 'local:warsh-text.json'),
  ('warsh-51-56', 'warsh', 51, 56, '۞ وَمَا خَلَقْتُ ࡲ۬لْجِنَّ وَالِانسَ إِلَّا لِيَعْبُدُونِ࣌', 'وما خلقت ࡲلجن والانس إلا ليعبدون࣌', NULL, 523, 'local:warsh-text.json'),
  ('warsh-51-57', 'warsh', 51, 57, 'مَآ أُرِيدُ مِنْهُم مِّن رِّزْقࣲ وَمَآ أُرِيدُ أَنْ يُّطْعِمُونِ࣌', 'ما أريد منهم من رزق وما أريد أن يطعمون࣌', NULL, 523, 'local:warsh-text.json'),
  ('warsh-51-58', 'warsh', 51, 58, 'إِنَّ ࡰ۬للَّهَ هُوَ ࡰ۬لرَّزَّاقُ ذُو ࡲ۬لْقُوَّةِ ࡴ۬لْمَتِينُ࣌', 'إن ࡰلله هو ࡰلرزاق ذو ࡲلقوة ࡴلمتين࣌', NULL, 523, 'local:warsh-text.json'),
  ('warsh-51-59', 'warsh', 51, 59, 'فَإِنَّ لِلذِينَ ظَلَمُواْ ذَنُوباࣰ مِّثْلَ ذَنُوبِ أَصْحَٰبِهِمْ فَلَا يَسْتَعْجِلُونِ࣌', 'فإن للذين ظلموا ذنوبا مثل ذنوب أصحبهم فلا يستعجلون࣌', NULL, 523, 'local:warsh-text.json'),
  ('warsh-51-60', 'warsh', 51, 60, 'فَوَيْلࣱ لِّلذِينَ كَفَرُواْ مِنْ يَّوْمِهِمُ ࡲ۬لذِے يُوعَدُونَ࣌', 'فويل للذين كفروا من يومهم ࡲلذے يوعدون࣌', NULL, 523, 'local:warsh-text.json'),
  ('warsh-52-1', 'warsh', 52, 1, 'وَالطُّورِ وَكِتَٰبࣲ مَّسْطُورࣲ', 'والطور وكتب مسطور', NULL, 523, 'local:warsh-text.json'),
  ('warsh-52-2', 'warsh', 52, 2, 'فِے رَقࣲّ مَّنشُورࣲ', 'فے رق منشور', NULL, 523, 'local:warsh-text.json'),
  ('warsh-52-3', 'warsh', 52, 3, 'وَالْبَيْتِ ࡴ۬لْمَعْمُورِ', 'والبيت ࡴلمعمور', NULL, 523, 'local:warsh-text.json'),
  ('warsh-52-4', 'warsh', 52, 4, 'وَالسَّقْفِ ࡴ۬لْمَرْفُوعِ', 'والسقف ࡴلمرفوع', NULL, 523, 'local:warsh-text.json'),
  ('warsh-52-5', 'warsh', 52, 5, 'وَالْبَحْرِ ࡴ۬لْمَسْجُورِ', 'والبحر ࡴلمسجور', NULL, 523, 'local:warsh-text.json'),
  ('warsh-52-6', 'warsh', 52, 6, 'إِنَّ عَذَابَ رَبِّكَ لَوَٰقِعࣱ࣌', 'إن عذاب ربك لوقع࣌', NULL, 523, 'local:warsh-text.json'),
  ('warsh-52-7', 'warsh', 52, 7, 'مَّا لَهُۥ مِن دَافِعࣲ࣌', 'ما له من دافع࣌', NULL, 523, 'local:warsh-text.json'),
  ('warsh-52-8', 'warsh', 52, 8, 'يَوْمَ تَمُورُ ࡲ۬لسَّمَآءُ مَوْراࣰ', 'يوم تمور ࡲلسماء مورا', NULL, 523, 'local:warsh-text.json'),
  ('warsh-52-9', 'warsh', 52, 9, 'وَتَسِيرُ ࡲ۬لْجِبَالُ سَيْراࣰ࣌', 'وتسير ࡲلجبال سيرا࣌', NULL, 523, 'local:warsh-text.json'),
  ('warsh-52-10', 'warsh', 52, 10, 'فَوَيْلࣱ يَوْمَئِذࣲ لِّلْمُكَذِّبِينَ', 'فويل يومئذ للمكذبين', NULL, 523, 'local:warsh-text.json'),
  ('warsh-52-11', 'warsh', 52, 11, 'ࡰ۬لذِينَ هُمْ فِے خَوْضࣲ يَلْعَبُونَ࣌', 'ࡰلذين هم فے خوض يلعبون࣌', NULL, 523, 'local:warsh-text.json'),
  ('warsh-52-12', 'warsh', 52, 12, 'يَوْمَ يُدَعُّونَ إِلَىٰ نٜارِ جَهَنَّمَ دَعّاً࣌ هَٰذِهِ ࡴ۬لنَّارُ ࡲ۬لتِے كُنتُم بِهَا تُكَذِّبُونَ࣌', 'يوم يدعون إلى نار جهنم دعا࣌ هذه ࡴلنار ࡲلتے كنتم بها تكذبون࣌', NULL, 523, 'local:warsh-text.json'),
  ('warsh-52-13', 'warsh', 52, 13, 'أَفَسِحْرٌ هَٰذَآ أَمَ ࡰنتُمْ لَا تُبْصِرُونَ࣌', 'أفسحر هذا أم ࡰنتم لا تبصرون࣌', NULL, 524, 'local:warsh-text.json'),
  ('warsh-52-14', 'warsh', 52, 14, 'ࡰٜصْلَوْهَا فَاصْبِرُوٓاْ أَوْ لَا تَصْبِرُواْ سَوَآءٌ عَلَيْكُمُۥٓ࣌ إِنَّمَا تُجْزَوْنَ مَا كُنتُمْ تَعْمَلُونَ࣌', 'ࡰصلوها فاصبروا أو لا تصبروا سواء عليكم࣌ إنما تجزون ما كنتم تعملون࣌', NULL, 524, 'local:warsh-text.json'),
  ('warsh-52-15', 'warsh', 52, 15, 'إِنَّ ࡰ۬لْمُتَّقِينَ فِے جَنَّٰتࣲ وَنَعِيمࣲ', 'إن ࡰلمتقين فے جنت ونعيم', NULL, 524, 'local:warsh-text.json'),
  ('warsh-52-16', 'warsh', 52, 16, 'فَٰكِهِينَ بِمَآ ءَاتٜيٰهُمْ رَبُّهُمْ࣌ وَوَقٜيٰهُمْ رَبُّهُمْ عَذَابَ ࡰ۬لْجَحِيمِ࣌', 'فكهين بما ءاتيهم ربهم࣌ ووقيهم ربهم عذاب ࡰلجحيم࣌', NULL, 524, 'local:warsh-text.json'),
  ('warsh-52-17', 'warsh', 52, 17, 'كُلُواْ وَاشْرَبُواْ هَنِيٓـٔاَۢ بِمَا كُنتُمْ تَعْمَلُونَ', 'كلوا واشربوا هنيا بما كنتم تعملون', NULL, 524, 'local:warsh-text.json'),
  ('warsh-52-18', 'warsh', 52, 18, 'مُتَّكِـِٕينَ عَلَىٰ سُرُرࣲ مَّصْفُوفَةࣲ وَزَوَّجْنَٰهُم بِحُورٍ عِينࣲ࣌', 'متكين على سرر مصفوفة وزوجنهم بحور عين࣌', NULL, 524, 'local:warsh-text.json'),
  ('warsh-52-19', 'warsh', 52, 19, 'وَالذِينَ ءَامَنُواْ وَاتَّبَعَتْهُمْ ذُرِّيَّتُهُم بِإِيمَٰنٍ ࡰلْحَقْنَا بِهِمْ ذُرِّيَّٰتِهِمْ وَمَآ أَلَتْنَٰهُم مِّنْ عَمَلِهِم مِّن شَےْءࣲ࣌ كُلُّ ࡲٜمْرِےِٕۢ بِمَا كَسَبَ رَهِينࣱ࣌', 'والذين ءامنوا واتبعتهم ذريتهم بإيمن ࡰلحقنا بهم ذريتهم وما ألتنهم من عملهم من شےء࣌ كل ࡲمرے بما كسب رهين࣌', NULL, 524, 'local:warsh-text.json'),
  ('warsh-52-20', 'warsh', 52, 20, 'وَأَمْدَدْنَٰهُم بِفَٰكِهَةࣲ وَلَحْمࣲ مِّمَّا يَشْتَهُونَ', 'وأمددنهم بفكهة ولحم مما يشتهون', NULL, 524, 'local:warsh-text.json'),
  ('warsh-52-21', 'warsh', 52, 21, 'يَتَنَٰزَعُونَ فِيهَا كَأْساࣰ لَّا لَغْوࣱ فِيهَا وَلَا تَاثِيمࣱ࣌', 'يتنزعون فيها كأسا لا لغو فيها ولا تاثيم࣌', NULL, 524, 'local:warsh-text.json'),
  ('warsh-52-22', 'warsh', 52, 22, '۞ وَيَطُوفُ عَلَيْهِمْ غِلْمَانࣱ لَّهُمْ كَأَنَّهُمْ لُؤْلُؤࣱ مَّكْنُونࣱ࣌', 'ويطوف عليهم غلمان لهم كأنهم لؤلؤ مكنون࣌', NULL, 524, 'local:warsh-text.json'),
  ('warsh-52-23', 'warsh', 52, 23, 'وَأَقْبَلَ بَعْضُهُمْ عَلَىٰ بَعْضࣲ يَتَسَآءَلُونَ࣌', 'وأقبل بعضهم على بعض يتساءلون࣌', NULL, 524, 'local:warsh-text.json'),
  ('warsh-52-24', 'warsh', 52, 24, 'قَالُوٓاْ إِنَّا كُنَّا قَبْلُ فِےٓ أَهْلِنَا مُشْفِقِينَ', 'قالوا إنا كنا قبل فے أهلنا مشفقين', NULL, 524, 'local:warsh-text.json'),
  ('warsh-52-25', 'warsh', 52, 25, 'فَمَنَّ ࡰ۬للَّهُ عَلَيْنَا وَوَقٜيٰنَا عَذَابَ ࡰ۬لسَّمُومِ࣌', 'فمن ࡰلله علينا ووقينا عذاب ࡰلسموم࣌', NULL, 524, 'local:warsh-text.json'),
  ('warsh-52-26', 'warsh', 52, 26, 'إِنَّا كُنَّا مِن قَبْلُ نَدْعُوهُ أَنَّهُۥ هُوَ ࡰ۬لْبَرُّ ࡲ۬لرَّحِيمُ࣌', 'إنا كنا من قبل ندعوه أنه هو ࡰلبر ࡲلرحيم࣌', NULL, 524, 'local:warsh-text.json'),
  ('warsh-52-27', 'warsh', 52, 27, 'فَذَكِّرْ فَمَآ أَنتَ بِنِعْمَتِ رَبِّكَ بِكَاهِنࣲ وَلَا مَجْنُونٍ࣌', 'فذكر فما أنت بنعمت ربك بكاهن ولا مجنون࣌', NULL, 524, 'local:warsh-text.json'),
  ('warsh-52-28', 'warsh', 52, 28, 'ࡰمْ يَقُولُونَ شَاعِرࣱ نَّتَرَبَّصُ بِهِۦ رَيْبَ ࡰ۬لْمَنُونِ࣌', 'ࡰم يقولون شاعر نتربص به ريب ࡰلمنون࣌', NULL, 524, 'local:warsh-text.json'),
  ('warsh-52-29', 'warsh', 52, 29, 'قُلْ تَرَبَّصُواْ࣌ فَإِنِّے مَعَكُم مِّنَ ࡰ۬لْمُتَرَبِّصِينَ࣌', 'قل تربصوا࣌ فإنے معكم من ࡰلمتربصين࣌', NULL, 524, 'local:warsh-text.json'),
  ('warsh-52-30', 'warsh', 52, 30, 'أَمْ تَامُرُهُمُۥٓ أَحْلَٰمُهُم بِهَٰذَآ أَمْ هُمْ قَوْمࣱ طَاغُونَ࣌', 'أم تامرهم أحلمهم بهذا أم هم قوم طاغون࣌', NULL, 525, 'local:warsh-text.json'),
  ('warsh-52-31', 'warsh', 52, 31, 'أَمْ يَقُولُونَ تَقَوَّلَهُۥ࣌ بَل لَّا يُومِنُونَ࣌', 'أم يقولون تقوله࣌ بل لا يومنون࣌', NULL, 525, 'local:warsh-text.json'),
  ('warsh-52-32', 'warsh', 52, 32, 'فَلْيَاتُواْ بِحَدِيثࣲ مِّثْلِهِۦٓ إِن كَانُواْ صَٰدِقِينَ࣌', 'فلياتوا بحديث مثله إن كانوا صدقين࣌', NULL, 525, 'local:warsh-text.json'),
  ('warsh-52-33', 'warsh', 52, 33, 'أَمْ خُلِقُواْ مِنْ غَيْرِ شَےْءٍ ࡰمْ هُمُ ࡲ۬لْخَٰلِقُونَ࣌', 'أم خلقوا من غير شےء ࡰم هم ࡲلخلقون࣌', NULL, 525, 'local:warsh-text.json'),
  ('warsh-52-34', 'warsh', 52, 34, 'أَمْ خَلَقُواْ ࡲ۬لسَّمَٰوَٰتِ وَالَارْضَ࣌ بَل لَّا يُوقِنُونَ࣌', 'أم خلقوا ࡲلسموت والارض࣌ بل لا يوقنون࣌', NULL, 525, 'local:warsh-text.json'),
  ('warsh-52-35', 'warsh', 52, 35, 'أَمْ عِندَهُمْ خَزَآئِنُ رَبِّكَ أَمْ هُمُ ࡲ۬لْمُصَيْطِرُونَ࣌', 'أم عندهم خزائن ربك أم هم ࡲلمصيطرون࣌', NULL, 525, 'local:warsh-text.json'),
  ('warsh-52-36', 'warsh', 52, 36, 'أَمْ لَهُمْ سُلَّمࣱ يَسْتَمِعُونَ فِيهِ࣌ فَلْيَاتِ مُسْتَمِعُهُم بِسُلْطَٰنࣲ مُّبِينٍ࣌', 'أم لهم سلم يستمعون فيه࣌ فليات مستمعهم بسلطن مبين࣌', NULL, 525, 'local:warsh-text.json'),
  ('warsh-52-37', 'warsh', 52, 37, 'ࡰمْ لَهُ ࡲ۬لْبَنَٰتُ وَلَكُمُ ࡲ۬لْبَنُونَ࣌', 'ࡰم له ࡲلبنت ولكم ࡲلبنون࣌', NULL, 525, 'local:warsh-text.json'),
  ('warsh-52-38', 'warsh', 52, 38, 'أَمْ تَسْـَٔلُهُمُۥٓ أَجْراࣰ فَهُم مِّن مَّغْرَمࣲ مُّثْقَلُونَ࣌', 'أم تسلهم أجرا فهم من مغرم مثقلون࣌', NULL, 525, 'local:warsh-text.json'),
  ('warsh-52-39', 'warsh', 52, 39, 'أَمْ عِندَهُمُ ࡲ۬لْغَيْبُ فَهُمْ يَكْتُبُونَ࣌', 'أم عندهم ࡲلغيب فهم يكتبون࣌', NULL, 525, 'local:warsh-text.json'),
  ('warsh-52-40', 'warsh', 52, 40, 'أَمْ يُرِيدُونَ كَيْداࣰ࣌ فَالذِينَ كَفَرُواْ هُمُ ࡲ۬لْمَكِيدُونَ࣌', 'أم يريدون كيدا࣌ فالذين كفروا هم ࡲلمكيدون࣌', NULL, 525, 'local:warsh-text.json'),
  ('warsh-52-41', 'warsh', 52, 41, 'أَمْ لَهُمُۥٓ إِلَٰهٌ غَيْرُ ࡲ۬للَّهِ࣌ سُبْحَٰنَ ࡰ۬للَّهِ عَمَّا يُشْرِكُونَ࣌', 'أم لهم إله غير ࡲلله࣌ سبحن ࡰلله عما يشركون࣌', NULL, 525, 'local:warsh-text.json'),
  ('warsh-52-42', 'warsh', 52, 42, '۞ وَإِنْ يَّرَوْاْ كِسْفاࣰ مِّنَ ࡰ۬لسَّمَآءِ سَاقِطاࣰ يَقُولُواْ سَحَابࣱ مَّرْكُومࣱ࣌', 'وإن يروا كسفا من ࡰلسماء ساقطا يقولوا سحاب مركوم࣌', NULL, 525, 'local:warsh-text.json'),
  ('warsh-52-43', 'warsh', 52, 43, 'فَذَرْهُمْ حَتَّىٰ يُلَٰقُواْ يَوْمَهُمُ ࡲ۬لذِے فِيهِ يَصْعَقُونَ', 'فذرهم حتى يلقوا يومهم ࡲلذے فيه يصعقون', NULL, 525, 'local:warsh-text.json'),
  ('warsh-52-44', 'warsh', 52, 44, 'يَوْمَ لَا يُغْنِے عَنْهُمْ كَيْدُهُمْ شَيْـٔاࣰ وَلَا هُمْ يُنصَرُونَ࣌', 'يوم لا يغنے عنهم كيدهم شيا ولا هم ينصرون࣌', NULL, 525, 'local:warsh-text.json'),
  ('warsh-52-45', 'warsh', 52, 45, 'وَإِنَّ لِلذِينَ ظَلَمُواْ عَذَاباࣰ دُونَ ذَٰلِكَ࣌ وَلَٰكِنَّ أَكْثَرَهُمْ لَا يَعْلَمُونَ࣌', 'وإن للذين ظلموا عذابا دون ذلك࣌ ولكن أكثرهم لا يعلمون࣌', NULL, 525, 'local:warsh-text.json'),
  ('warsh-52-46', 'warsh', 52, 46, 'وَاصْبِرْ لِحُكْمِ رَبِّكَ فَإِنَّكَ بِأَعْيُنِنَا࣌ وَسَبِّحْ بِحَمْدِ رَبِّكَ حِينَ تَقُومُ࣌', 'واصبر لحكم ربك فإنك بأعيننا࣌ وسبح بحمد ربك حين تقوم࣌', NULL, 525, 'local:warsh-text.json'),
  ('warsh-52-47', 'warsh', 52, 47, 'وَمِنَ ࡰ۬ليْلِ فَسَبِّحْهُ وَإِدْبَٰرَ ࡰ۬لنُّجُومِ࣌', 'ومن ࡰليل فسبحه وإدبر ࡰلنجوم࣌', NULL, 525, 'local:warsh-text.json'),
  ('warsh-53-1', 'warsh', 53, 1, 'وَالنَّجْمِ إِذَا هَوٜىٰ', 'والنجم إذا هوى', NULL, 526, 'local:warsh-text.json'),
  ('warsh-53-2', 'warsh', 53, 2, 'مَا ضَلَّ صَٰحِبُكُمْ وَمَا غَوٜىٰ', 'ما ضل صحبكم وما غوى', NULL, 526, 'local:warsh-text.json'),
  ('warsh-53-3', 'warsh', 53, 3, 'وَمَا يَنطِقُ عَنِ ࡴ۬لْهَوٜىٰٓ', 'وما ينطق عن ࡴلهوى', NULL, 526, 'local:warsh-text.json'),
  ('warsh-53-4', 'warsh', 53, 4, 'إِنْ هُوَ إِلَّا وَحْيࣱ يُوحٜىٰ࣌', 'إن هو إلا وحي يوحى࣌', NULL, 526, 'local:warsh-text.json'),
  ('warsh-53-5', 'warsh', 53, 5, 'عَلَّمَهُۥ شَدِيدُ ࡲ۬لْقُوٜىٰ', 'علمه شديد ࡲلقوى', NULL, 526, 'local:warsh-text.json'),
  ('warsh-53-6', 'warsh', 53, 6, 'ذُو مِرَّةࣲ࣌ فَاسْتَوٜىٰ', 'ذو مرة࣌ فاستوى', NULL, 526, 'local:warsh-text.json'),
  ('warsh-53-7', 'warsh', 53, 7, 'وَهُوَ بِالُافُقِ ࡴ۬لَاعْلٜىٰ࣌', 'وهو بالافق ࡴلاعلى࣌', NULL, 526, 'local:warsh-text.json'),
  ('warsh-53-8', 'warsh', 53, 8, 'ثُمَّ دَنَا فَتَدَلّٜىٰ', 'ثم دنا فتدلى', NULL, 526, 'local:warsh-text.json'),
  ('warsh-53-9', 'warsh', 53, 9, 'فَكَانَ قَابَ قَوْسَيْنِ أَوَ ࡰدْنٜىٰ࣌', 'فكان قاب قوسين أو ࡰدنى࣌', NULL, 526, 'local:warsh-text.json'),
  ('warsh-53-10', 'warsh', 53, 10, 'فَأَوْحٜىٰٓ إِلَىٰ عَبْدِهِۦ مَآ أَوْحٜىٰ࣌', 'فأوحى إلى عبده ما أوحى࣌', NULL, 526, 'local:warsh-text.json'),
  ('warsh-53-11', 'warsh', 53, 11, 'مَا كَذَبَ ࡰ۬لْفُؤَادُ مَا رٜأٜىٰٓ࣌', 'ما كذب ࡰلفؤاد ما رأى࣌', NULL, 526, 'local:warsh-text.json'),
  ('warsh-53-12', 'warsh', 53, 12, 'أَفَتُمَٰرُونَهُۥ عَلَىٰ مَا يَرٜىٰ࣌', 'أفتمرونه على ما يرى࣌', NULL, 526, 'local:warsh-text.json'),
  ('warsh-53-13', 'warsh', 53, 13, 'وَلَقَدْ رٜءٜاهُ نَزْلَةً ࡳخْرٜىٰ', 'ولقد رءاه نزلة ࡳخرى', NULL, 526, 'local:warsh-text.json'),
  ('warsh-53-14', 'warsh', 53, 14, 'عِندَ سِدْرَةِ ࡴ۬لْمُنتَهٜىٰ', 'عند سدرة ࡴلمنتهى', NULL, 526, 'local:warsh-text.json'),
  ('warsh-53-15', 'warsh', 53, 15, 'عِندَهَا جَنَّةُ ࡲ۬لْمَأْوٜىٰٓ', 'عندها جنة ࡲلمأوى', NULL, 526, 'local:warsh-text.json'),
  ('warsh-53-16', 'warsh', 53, 16, 'إِذْ يَغْشَى ࡰ۬لسِّدْرَةَ مَا يَغْشٜىٰ࣌', 'إذ يغشى ࡰلسدرة ما يغشى࣌', NULL, 526, 'local:warsh-text.json'),
  ('warsh-53-17', 'warsh', 53, 17, 'مَا زَاغَ ࡰ۬لْبَصَرُ وَمَا طَغٜىٰ࣌', 'ما زاغ ࡰلبصر وما طغى࣌', NULL, 526, 'local:warsh-text.json'),
  ('warsh-53-18', 'warsh', 53, 18, 'لَقَدْ رٜأٜىٰ مِنَ اٰيَٰتِ رَبِّهِ ࡴ۬لْكُبْرٜىٰٓ࣌', 'لقد رأى من ايت ربه ࡴلكبرى࣌', NULL, 526, 'local:warsh-text.json'),
  ('warsh-53-19', 'warsh', 53, 19, 'أَفَرَٰٓيْتُمُ ࡲ۬للَّٰتَ وَالْعُزّٜىٰ', 'أفريتم ࡲللت والعزى', NULL, 526, 'local:warsh-text.json'),
  ('warsh-53-20', 'warsh', 53, 20, 'وَمَنَوٰةَ ࡰ۬لثَّالِثَةَ ࡰ۬لُاخْرٜىٰٓ', 'ومنوة ࡰلثالثة ࡰلاخرى', NULL, 526, 'local:warsh-text.json'),
  ('warsh-53-21', 'warsh', 53, 21, 'أَلَكُمُ ࡲ۬لذَّكَرُ وَلَهُ ࡲ۬لُانثٜىٰ࣌', 'ألكم ࡲلذكر وله ࡲلانثى࣌', NULL, 526, 'local:warsh-text.json'),
  ('warsh-53-22', 'warsh', 53, 22, 'تِلْكَ إِذاࣰ قِسْمَةࣱ ضِيزٜىٰٓ࣌', 'تلك إذا قسمة ضيزى࣌', NULL, 526, 'local:warsh-text.json'),
  ('warsh-53-23', 'warsh', 53, 23, 'إِنْ هِيَ إِلَّآ أَسْمَآءࣱ سَمَّيْتُمُوهَآ أَنتُمْ وَءَابَآؤُكُم مَّآ أَنزَلَ ࡰ۬للَّهُ بِهَا مِن سُلْطَٰنٍ࣌ ࡴنْ يَّتَّبِعُونَ إِلَّا ࡰ۬لظَّنَّ وَمَا تَهْوَى ࡰ۬لَانفُسُ࣌ وَلَقَدْ جَآءَهُم مِّن رَّبِّهِمُ ࡲ۬لْهُدٜىٰٓ࣌', 'إن هي إلا أسماء سميتموها أنتم وءاباؤكم ما أنزل ࡰلله بها من سلطن࣌ ࡴن يتبعون إلا ࡰلظن وما تهوى ࡰلانفس࣌ ولقد جاءهم من ربهم ࡲلهدى࣌', NULL, 526, 'local:warsh-text.json'),
  ('warsh-53-24', 'warsh', 53, 24, 'أَمْ لِلِانسَٰنِ مَا تَمَنّٜىٰ࣌', 'أم للانسن ما تمنى࣌', NULL, 526, 'local:warsh-text.json'),
  ('warsh-53-25', 'warsh', 53, 25, 'فَلِلهِ ࡴ۬لَاخِرَةُ وَالُاولٜىٰ࣌', 'فلله ࡴلاخرة والاولى࣌', NULL, 526, 'local:warsh-text.json'),
  ('warsh-53-26', 'warsh', 53, 26, '۞ وَكَم مِّن مَّلَكࣲ فِے ࡴ۬لسَّمَٰوَٰتِ لَا تُغْنِے شَفَٰعَتُهُمْ شَيْـٔاً ࡴلَّا مِنۢ بَعْدِ أَنْ يَّاذَنَ ࡰ۬للَّهُ لِمَنْ يَّشَآءُ وَيَرْضٜىٰٓ࣌', 'وكم من ملك فے ࡴلسموت لا تغنے شفعتهم شيا ࡴلا من بعد أن ياذن ࡰلله لمن يشاء ويرضى࣌', NULL, 526, 'local:warsh-text.json'),
  ('warsh-53-27', 'warsh', 53, 27, 'إِنَّ ࡰ۬لذِينَ لَا يُومِنُونَ بِالَاخِرَةِ لَيُسَمُّونَ ࡰ۬لْمَلَٰٓئِكَةَ تَسْمِيَةَ ࡰ۬لُانثٜىٰ࣌', 'إن ࡰلذين لا يومنون بالاخرة ليسمون ࡰلملئكة تسمية ࡰلانثى࣌', NULL, 527, 'local:warsh-text.json'),
  ('warsh-53-28', 'warsh', 53, 28, 'وَمَا لَهُم بِهِۦ مِنْ عِلْمٍ࣌ ࡴنْ يَّتَّبِعُونَ إِلَّا ࡰ۬لظَّنَّ࣌ وَإِنَّ ࡰ۬لظَّنَّ لَا يُغْنِے مِنَ ࡰ۬لْحَقِّ شَيْـٔاࣰ࣌ فَأَعْرِضْ عَن مَّن تَوَلّٜىٰ عَن ذِكْرِنَا وَلَمْ يُرِدِ ࡴلَّا ࡰ۬لْحَيَوٰةَ ࡰ۬لدُّنْيٜا࣌', 'وما لهم به من علم࣌ ࡴن يتبعون إلا ࡰلظن࣌ وإن ࡰلظن لا يغنے من ࡰلحق شيا࣌ فأعرض عن من تولى عن ذكرنا ولم يرد ࡴلا ࡰلحيوة ࡰلدنيا࣌', NULL, 527, 'local:warsh-text.json'),
  ('warsh-53-29', 'warsh', 53, 29, 'ذَٰلِكَ مَبْلَغُهُم مِّنَ ࡰ۬لْعِلْمِ࣌ إِنَّ رَبَّكَ هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِۦ࣌ وَهُوَ أَعْلَمُ بِمَنِ ࡴٜهْتَدٜىٰ࣌', 'ذلك مبلغهم من ࡰلعلم࣌ إن ربك هو أعلم بمن ضل عن سبيله࣌ وهو أعلم بمن ࡴهتدى࣌', NULL, 527, 'local:warsh-text.json'),
  ('warsh-53-30', 'warsh', 53, 30, 'وَلِلهِ مَا فِے ࡴ۬لسَّمَٰوَٰتِ وَمَا فِے ࡴ۬لَارْضِ لِيَجْزِيَ ࡰ۬لذِينَ أَسَٰٓـُٔواْ بِمَا عَمِلُواْ وَيَجْزِيَ ࡰ۬لذِينَ أَحْسَنُواْ بِالْحُسْنَى࣌', 'ولله ما فے ࡴلسموت وما فے ࡴلارض ليجزي ࡰلذين أسوا بما عملوا ويجزي ࡰلذين أحسنوا بالحسنى࣌', NULL, 527, 'local:warsh-text.json'),
  ('warsh-53-31', 'warsh', 53, 31, 'ࡰ۬لذِينَ يَجْتَنِبُونَ كَبَٰٓئِرَ ࡰ۬لِاثْمِ وَالْفَوَٰحِشَ إِلَّا ࡰ۬للَّمَمَ࣌ إِنَّ رَبَّكَ وَٰسِعُ ࡲ۬لْمَغْفِرَةِ࣌ هُوَ أَعْلَمُ بِكُمُۥٓ إِذَ ࡰنشَأَكُم مِّنَ ࡰ۬لَارْضِ وَإِذَ ࡰنتُمُۥٓ أَجِنَّةࣱ فِے بُطُونِ أُمَّهَٰتِكُمْ࣌ فَلَا تُزَكُّوٓاْ أَنفُسَكُمْ࣌ هُوَ أَعْلَمُ بِمَنِ ࡴٜتَّقٜىٰٓ࣌', 'ࡰلذين يجتنبون كبئر ࡰلاثم والفوحش إلا ࡰللمم࣌ إن ربك وسع ࡲلمغفرة࣌ هو أعلم بكم إذ ࡰنشأكم من ࡰلارض وإذ ࡰنتم أجنة فے بطون أمهتكم࣌ فلا تزكوا أنفسكم࣌ هو أعلم بمن ࡴتقى࣌', NULL, 527, 'local:warsh-text.json'),
  ('warsh-53-32', 'warsh', 53, 32, 'أَفَرَٰٓيْتَ ࡰ۬لذِے تَوَلّٜىٰ', 'أفريت ࡰلذے تولى', NULL, 527, 'local:warsh-text.json'),
  ('warsh-53-33', 'warsh', 53, 33, 'وَأَعْطٜىٰ قَلِيلاࣰ وَأَكْدٜىٰٓ', 'وأعطى قليلا وأكدى', NULL, 527, 'local:warsh-text.json'),
  ('warsh-53-34', 'warsh', 53, 34, 'أَعِندَهُۥ عِلْمُ ࡲ۬لْغَيْبِ فَهُوَ يَرٜىٰٓ࣌', 'أعنده علم ࡲلغيب فهو يرى࣌', NULL, 527, 'local:warsh-text.json'),
  ('warsh-53-35', 'warsh', 53, 35, 'أَمْ لَمْ يُنَبَّأْ بِمَا فِے صُحُفِ مُوسٜىٰ', 'أم لم ينبأ بما فے صحف موسى', NULL, 527, 'local:warsh-text.json'),
  ('warsh-53-36', 'warsh', 53, 36, 'وَإِبْرَٰهِيمَ ࡰ۬لذِے وَفّٜىٰٓ', 'وإبرهيم ࡰلذے وفى', NULL, 527, 'local:warsh-text.json'),
  ('warsh-53-37', 'warsh', 53, 37, 'أَلَّا تَزِرُ وَازِرَةࣱ وِزْرَ أُخْرٜىٰ࣌', 'ألا تزر وازرة وزر أخرى࣌', NULL, 527, 'local:warsh-text.json'),
  ('warsh-53-38', 'warsh', 53, 38, 'وَأَن لَّيْسَ لِلِانسَٰنِ إِلَّا مَا سَعٜىٰ࣌', 'وأن ليس للانسن إلا ما سعى࣌', NULL, 527, 'local:warsh-text.json')
insert into public.ayahs (id, riwayah, surah_number, ayah_number, text, simple_text, juz, page, source) values
  ('warsh-53-39', 'warsh', 53, 39, 'وَأَنَّ سَعْيَهُۥ سَوْفَ يُرٜىٰ࣌', 'وأن سعيه سوف يرى࣌', NULL, 527, 'local:warsh-text.json'),
  ('warsh-53-40', 'warsh', 53, 40, 'ثُمَّ يُجْزٜيٰهُ ࡲ۬لْجَزَآءَ ࡰ۬لَاوْفٜىٰ࣌', 'ثم يجزيه ࡲلجزاء ࡰلاوفى࣌', NULL, 527, 'local:warsh-text.json'),
  ('warsh-53-41', 'warsh', 53, 41, 'وَأَنَّ إِلَىٰ رَبِّكَ ࡰ۬لْمُنتَهٜىٰ࣌', 'وأن إلى ربك ࡰلمنتهى࣌', NULL, 527, 'local:warsh-text.json'),
  ('warsh-53-42', 'warsh', 53, 42, 'وَأَنَّهُۥ هُوَ أَضْحَكَ وَأَبْكٜىٰ࣌', 'وأنه هو أضحك وأبكى࣌', NULL, 527, 'local:warsh-text.json'),
  ('warsh-53-43', 'warsh', 53, 43, 'وَأَنَّهُۥ هُوَ أَمَاتَ وَأَحْيٜا࣌', 'وأنه هو أمات وأحيا࣌', NULL, 527, 'local:warsh-text.json'),
  ('warsh-53-44', 'warsh', 53, 44, 'وَأَنَّهُۥ خَلَقَ ࡰ۬لزَّوْجَيْنِ ࡴ۬لذَّكَرَ وَالُانثٜىٰ', 'وأنه خلق ࡰلزوجين ࡴلذكر والانثى', NULL, 528, 'local:warsh-text.json'),
  ('warsh-53-45', 'warsh', 53, 45, 'مِن نُّطْفَةٍ ࡴذَا تُمْنٜىٰ࣌', 'من نطفة ࡴذا تمنى࣌', NULL, 528, 'local:warsh-text.json'),
  ('warsh-53-46', 'warsh', 53, 46, '۞ وَأَنَّ عَلَيْهِ ࡴ۬لنَّشْأَةَ ࡰ۬لُاخْرٜىٰ࣌', 'وأن عليه ࡴلنشأة ࡰلاخرى࣌', NULL, 528, 'local:warsh-text.json'),
  ('warsh-53-47', 'warsh', 53, 47, 'وَأَنَّهُۥ هُوَ أَغْنٜىٰ وَأَقْنٜىٰ࣌', 'وأنه هو أغنى وأقنى࣌', NULL, 528, 'local:warsh-text.json'),
  ('warsh-53-48', 'warsh', 53, 48, 'وَأَنَّهُۥ هُوَ رَبُّ ࡲ۬لشِّعْرٜىٰ࣌', 'وأنه هو رب ࡲلشعرى࣌', NULL, 528, 'local:warsh-text.json'),
  ('warsh-53-49', 'warsh', 53, 49, 'وَأَنَّهُۥٓ أَهْلَكَ عَاداࣰ ࡰ۬لُّاولٜىٰ', 'وأنه أهلك عادا ࡰلاولى', NULL, 528, 'local:warsh-text.json'),
  ('warsh-53-50', 'warsh', 53, 50, 'وَثَمُوداࣰ فَمَآ أَبْقٜىٰ', 'وثمودا فما أبقى', NULL, 528, 'local:warsh-text.json'),
  ('warsh-53-51', 'warsh', 53, 51, 'وَقَوْمَ نُوحࣲ مِّن قَبْلُ࣌ إِنَّهُمْ كَانُواْ هُمُۥٓ أَظْلَمَ وَأَطْغٜىٰ࣌', 'وقوم نوح من قبل࣌ إنهم كانوا هم أظلم وأطغى࣌', NULL, 528, 'local:warsh-text.json'),
  ('warsh-53-52', 'warsh', 53, 52, 'وَالْمُوتَفِكَةَ أَهْوٜىٰ࣌', 'والموتفكة أهوى࣌', NULL, 528, 'local:warsh-text.json'),
  ('warsh-53-53', 'warsh', 53, 53, 'فَغَشّٜيٰهَا مَا غَشّٜىٰ࣌', 'فغشيها ما غشى࣌', NULL, 528, 'local:warsh-text.json'),
  ('warsh-53-54', 'warsh', 53, 54, 'فَبِأَيِّ ءَالَآءِ رَبِّكَ تَتَمَارٜىٰ࣌', 'فبأي ءالاء ربك تتمارى࣌', NULL, 528, 'local:warsh-text.json'),
  ('warsh-53-55', 'warsh', 53, 55, 'هَٰذَا نَذِيرࣱ مِّنَ ࡰ۬لنُّذُرِ ࡴ۬لُاولٜىٰٓ࣌', 'هذا نذير من ࡰلنذر ࡴلاولى࣌', NULL, 528, 'local:warsh-text.json'),
  ('warsh-53-56', 'warsh', 53, 56, 'أَزِفَتِ ࡴ۬لَازِفَةُ࣌', 'أزفت ࡴلازفة࣌', NULL, 528, 'local:warsh-text.json'),
  ('warsh-53-57', 'warsh', 53, 57, 'لَيْسَ لَهَا مِن دُونِ ࡴ۬للَّهِ كَاشِفَةٌ࣌', 'ليس لها من دون ࡴلله كاشفة࣌', NULL, 528, 'local:warsh-text.json'),
  ('warsh-53-58', 'warsh', 53, 58, 'ࡰفَمِنْ هَٰذَا ࡰ۬لْحَدِيثِ تَعْجَبُونَ', 'ࡰفمن هذا ࡰلحديث تعجبون', NULL, 528, 'local:warsh-text.json'),
  ('warsh-53-59', 'warsh', 53, 59, 'وَتَضْحَكُونَ وَلَا تَبْكُونَ', 'وتضحكون ولا تبكون', NULL, 528, 'local:warsh-text.json'),
  ('warsh-53-60', 'warsh', 53, 60, 'وَأَنتُمْ سَٰمِدُونَ࣌', 'وأنتم سمدون࣌', NULL, 528, 'local:warsh-text.json'),
  ('warsh-53-61', 'warsh', 53, 61, 'فَاسْجُدُواْ لِلهِ وَاعْبُدُواْ࣌', 'فاسجدوا لله واعبدوا࣌', NULL, 528, 'local:warsh-text.json'),
  ('warsh-54-1', 'warsh', 54, 1, 'ࡲٜقْتَرَبَتِ ࡴ۬لسَّاعَةُ وَانشَقَّ ࡰ۬لْقَمَرُ࣌', 'ࡲقتربت ࡴلساعة وانشق ࡰلقمر࣌', NULL, 528, 'local:warsh-text.json'),
  ('warsh-54-2', 'warsh', 54, 2, 'وَإِنْ يَّرَوَاْ اٰيَةࣰ يُعْرِضُواْ وَيَقُولُواْ سِحْرࣱ مُّسْتَمِرࣱّ࣌', 'وإن يروا اية يعرضوا ويقولوا سحر مستمر࣌', NULL, 528, 'local:warsh-text.json'),
  ('warsh-54-3', 'warsh', 54, 3, 'وَكَذَّبُواْ وَاتَّبَعُوٓاْ أَهْوَآءَهُمْ࣌ وَكُلُّ أَمْرࣲ مُّسْتَقِرࣱّ࣌', 'وكذبوا واتبعوا أهواءهم࣌ وكل أمر مستقر࣌', NULL, 528, 'local:warsh-text.json'),
  ('warsh-54-4', 'warsh', 54, 4, 'وَلَقَدْ جَآءَهُم مِّنَ ࡰ۬لَانۢبَآءِ مَا فِيهِ مُزْدَجَرٌ࣌', 'ولقد جاءهم من ࡰلانباء ما فيه مزدجر࣌', NULL, 528, 'local:warsh-text.json'),
  ('warsh-54-5', 'warsh', 54, 5, 'حِكْمَةُۢ بَٰلِغَةࣱ࣌ فَمَا تُغْنِ ࡴ۬لنُّذُرُ࣌', 'حكمة بلغة࣌ فما تغن ࡴلنذر࣌', NULL, 528, 'local:warsh-text.json'),
  ('warsh-54-6', 'warsh', 54, 6, 'فَتَوَلَّ عَنْهُمْ࣌ يَوْمَ يَدْعُ ࡲ۬لدَّاعِۦٓ إِلَىٰ شَےْءࣲ نُّكُرٍ', 'فتول عنهم࣌ يوم يدع ࡲلداع إلى شےء نكر', NULL, 528, 'local:warsh-text.json'),
  ('warsh-54-7', 'warsh', 54, 7, 'خُشَّعاً ࡰبْصَٰرُهُمْ يَخْرُجُونَ مِنَ ࡰ۬لَاجْدَاثِ كَأَنَّهُمْ جَرَادࣱ مُّنتَشِرࣱ', 'خشعا ࡰبصرهم يخرجون من ࡰلاجداث كأنهم جراد منتشر', NULL, 529, 'local:warsh-text.json'),
  ('warsh-54-8', 'warsh', 54, 8, 'مُّهْطِعِينَ إِلَى ࡰ۬لدَّاعِۦ࣌ يَقُولُ ࡲ۬لْكَٰفِرُونَ هَٰذَا يَوْمٌ عَسِرࣱ࣌', 'مهطعين إلى ࡰلداع࣌ يقول ࡲلكفرون هذا يوم عسر࣌', NULL, 529, 'local:warsh-text.json'),
  ('warsh-54-9', 'warsh', 54, 9, 'كَذَّبَتْ قَبْلَهُمْ قَوْمُ نُوحࣲ فَكَذَّبُواْ عَبْدَنَا وَقَالُواْ مَجْنُونࣱ وَازْدُجِرَ࣌', 'كذبت قبلهم قوم نوح فكذبوا عبدنا وقالوا مجنون وازدجر࣌', NULL, 529, 'local:warsh-text.json'),
  ('warsh-54-10', 'warsh', 54, 10, '۞ فَدَعَا رَبَّهُۥٓ أَنِّے مَغْلُوبࣱ فَانتَصِرْ࣌', 'فدعا ربه أنے مغلوب فانتصر࣌', NULL, 529, 'local:warsh-text.json'),
  ('warsh-54-11', 'warsh', 54, 11, 'فَفَتَحْنَآ أَبْوَٰبَ ࡰ۬لسَّمَآءِ بِمَآءࣲ مُّنْهَمِرࣲ࣌', 'ففتحنا أبوب ࡰلسماء بماء منهمر࣌', NULL, 529, 'local:warsh-text.json'),
  ('warsh-54-12', 'warsh', 54, 12, 'وَفَجَّرْنَا ࡰ۬لَارْضَ عُيُوناࣰ فَالْتَقَى ࡰ۬لْمَآءُ عَلَىٰٓ أَمْرࣲ قَدْ قُدِرَ࣌', 'وفجرنا ࡰلارض عيونا فالتقى ࡰلماء على أمر قد قدر࣌', NULL, 529, 'local:warsh-text.json'),
  ('warsh-54-13', 'warsh', 54, 13, 'وَحَمَلْنَٰهُ عَلَىٰ ذَاتِ أَلْوَٰحࣲ وَدُسُرࣲ࣌', 'وحملنه على ذات ألوح ودسر࣌', NULL, 529, 'local:warsh-text.json'),
  ('warsh-54-14', 'warsh', 54, 14, 'تَجْرِے بِأَعْيُنِنَا جَزَآءࣰ لِّمَن كَانَ كُفِرَ࣌', 'تجرے بأعيننا جزاء لمن كان كفر࣌', NULL, 529, 'local:warsh-text.json'),
  ('warsh-54-15', 'warsh', 54, 15, 'وَلَقَد تَّرَكْنَٰهَآ ءَايَةࣰ فَهَلْ مِن مُّدَّكِرࣲ࣌', 'ولقد تركنها ءاية فهل من مدكر࣌', NULL, 529, 'local:warsh-text.json'),
  ('warsh-54-16', 'warsh', 54, 16, 'فَكَيْفَ كَانَ عَذَابِے وَنُذُرِۦ࣌', 'فكيف كان عذابے ونذر࣌', NULL, 529, 'local:warsh-text.json'),
  ('warsh-54-17', 'warsh', 54, 17, 'وَلَقَدْ يَسَّرْنَا ࡰ۬لْقُرْءَانَ لِلذِّكْرِ فَهَلْ مِن مُّدَّكِرࣲ࣌', 'ولقد يسرنا ࡰلقرءان للذكر فهل من مدكر࣌', NULL, 529, 'local:warsh-text.json'),
  ('warsh-54-18', 'warsh', 54, 18, 'كَذَّبَتْ عَادࣱ فَكَيْفَ كَانَ عَذَابِے وَنُذُرِۦٓ࣌', 'كذبت عاد فكيف كان عذابے ونذر࣌', NULL, 529, 'local:warsh-text.json'),
  ('warsh-54-19', 'warsh', 54, 19, 'إِنَّآ أَرْسَلْنَا عَلَيْهِمْ رِيحاࣰ صَرْصَراࣰ فِے يَوْمِ نَحْسࣲ مُّسْتَمِرࣲّ', 'إنا أرسلنا عليهم ريحا صرصرا فے يوم نحس مستمر', NULL, 529, 'local:warsh-text.json'),
  ('warsh-54-20', 'warsh', 54, 20, 'تَنزِعُ ࡲ۬لنَّاسَ كَأَنَّهُمُۥٓ أَعْجَازُ نَخْلࣲ مُّنقَعِرࣲ࣌', 'تنزع ࡲلناس كأنهم أعجاز نخل منقعر࣌', NULL, 529, 'local:warsh-text.json'),
  ('warsh-54-21', 'warsh', 54, 21, 'فَكَيْفَ كَانَ عَذَابِے وَنُذُرِۦ࣌', 'فكيف كان عذابے ونذر࣌', NULL, 529, 'local:warsh-text.json'),
  ('warsh-54-22', 'warsh', 54, 22, 'وَلَقَدْ يَسَّرْنَا ࡰ۬لْقُرْءَانَ لِلذِّكْرِ فَهَلْ مِن مُّدَّكِرࣲ࣌', 'ولقد يسرنا ࡰلقرءان للذكر فهل من مدكر࣌', NULL, 529, 'local:warsh-text.json'),
  ('warsh-54-23', 'warsh', 54, 23, 'كَذَّبَتْ ثَمُودُ بِالنُّذُرِ࣌', 'كذبت ثمود بالنذر࣌', NULL, 529, 'local:warsh-text.json'),
  ('warsh-54-24', 'warsh', 54, 24, 'فَقَالُوٓاْ أَبَشَراࣰ مِّنَّا وَٰحِداࣰ نَّتَّبِعُهُۥٓ إِنَّآ إِذاࣰ لَّفِے ضَلَٰلࣲ وَسُعُرٍ', 'فقالوا أبشرا منا وحدا نتبعه إنا إذا لفے ضلل وسعر', NULL, 529, 'local:warsh-text.json'),
  ('warsh-54-25', 'warsh', 54, 25, 'ࡰࢇلْقِيَ ࡰ۬لذِّكْرُ عَلَيْهِ مِنۢ بَيْنِنَا بَلْ هُوَ كَذَّابٌ ࡰشِرࣱ࣌', 'ࡰࢇلقي ࡰلذكر عليه من بيننا بل هو كذاب ࡰشر࣌', NULL, 529, 'local:warsh-text.json'),
  ('warsh-54-26', 'warsh', 54, 26, 'سَيَعْلَمُونَ غَداࣰ مَّنِ ࡴ۬لْكَذَّابُ ࡲ۬لَاشِرُ࣌', 'سيعلمون غدا من ࡴلكذاب ࡲلاشر࣌', NULL, 529, 'local:warsh-text.json'),
  ('warsh-54-27', 'warsh', 54, 27, 'إِنَّا مُرْسِلُواْ ࡲ۬لنَّاقَةِ فِتْنَةࣰ لَّهُمْ فَارْتَقِبْهُمْ وَاصْطَبِرْ࣌', 'إنا مرسلوا ࡲلناقة فتنة لهم فارتقبهم واصطبر࣌', NULL, 529, 'local:warsh-text.json'),
  ('warsh-54-28', 'warsh', 54, 28, 'وَنَبِّئْهُمُۥٓ أَنَّ ࡰ۬لْمَآءَ قِسْمَةُۢ بَيْنَهُمْ࣌ كُلُّ شِرْبࣲ مُّحْتَضَرࣱ࣌', 'ونبئهم أن ࡰلماء قسمة بينهم࣌ كل شرب محتضر࣌', NULL, 530, 'local:warsh-text.json'),
  ('warsh-54-29', 'warsh', 54, 29, 'فَنَادَوْاْ صَٰحِبَهُمْ فَتَعَاطٜىٰ فَعَقَرَ࣌', 'فنادوا صحبهم فتعاطى فعقر࣌', NULL, 530, 'local:warsh-text.json'),
  ('warsh-54-30', 'warsh', 54, 30, 'فَكَيْفَ كَانَ عَذَابِے وَنُذُرِۦٓ࣌', 'فكيف كان عذابے ونذر࣌', NULL, 530, 'local:warsh-text.json'),
  ('warsh-54-31', 'warsh', 54, 31, 'إِنَّآ أَرْسَلْنَا عَلَيْهِمْ صَيْحَةࣰ وَٰحِدَةࣰ فَكَانُواْ كَهَشِيمِ ࡴ۬لْمُحْتَظِرِ࣌', 'إنا أرسلنا عليهم صيحة وحدة فكانوا كهشيم ࡴلمحتظر࣌', NULL, 530, 'local:warsh-text.json'),
  ('warsh-54-32', 'warsh', 54, 32, 'وَلَقَدْ يَسَّرْنَا ࡰ۬لْقُرْءَانَ لِلذِّكْرِ فَهَلْ مِن مُّدَّكِرࣲ࣌', 'ولقد يسرنا ࡰلقرءان للذكر فهل من مدكر࣌', NULL, 530, 'local:warsh-text.json'),
  ('warsh-54-33', 'warsh', 54, 33, 'كَذَّبَتْ قَوْمُ لُوطِۢ بِالنُّذُرِ࣌', 'كذبت قوم لوط بالنذر࣌', NULL, 530, 'local:warsh-text.json'),
  ('warsh-54-34', 'warsh', 54, 34, 'إِنَّآ أَرْسَلْنَا عَلَيْهِمْ حَاصِباً ࡴلَّآ ءَالَ لُوطࣲ نَّجَّيْنَٰهُم بِسَحَرࣲ࣌', 'إنا أرسلنا عليهم حاصبا ࡴلا ءال لوط نجينهم بسحر࣌', NULL, 530, 'local:warsh-text.json'),
  ('warsh-54-35', 'warsh', 54, 35, 'نِّعْمَةࣰ مِّنْ عِندِنَا࣌ كَذَٰلِكَ نَجْزِے مَن شَكَرَ࣌', 'نعمة من عندنا࣌ كذلك نجزے من شكر࣌', NULL, 530, 'local:warsh-text.json'),
  ('warsh-54-36', 'warsh', 54, 36, 'وَلَقَدَ ࡰنذَرَهُم بَطْشَتَنَا فَتَمَارَوْاْ بِالنُّذُرِ࣌', 'ولقد ࡰنذرهم بطشتنا فتماروا بالنذر࣌', NULL, 530, 'local:warsh-text.json'),
  ('warsh-54-37', 'warsh', 54, 37, '۞ وَلَقَدْ رَٰوَدُوهُ عَن ضَيْفِهِۦ فَطَمَسْنَآ أَعْيُنَهُمْ فَذُوقُواْ عَذَابِے وَنُذُرِۦ࣌', 'ولقد رودوه عن ضيفه فطمسنا أعينهم فذوقوا عذابے ونذر࣌', NULL, 530, 'local:warsh-text.json'),
  ('warsh-54-38', 'warsh', 54, 38, 'وَلَقَدْ صَبَّحَهُم بُكْرَةً عَذَابࣱ مُّسْتَقِرࣱّ࣌', 'ولقد صبحهم بكرة عذاب مستقر࣌', NULL, 530, 'local:warsh-text.json'),
  ('warsh-54-39', 'warsh', 54, 39, 'فَذُوقُواْ عَذَابِے وَنُذُرِۦ࣌', 'فذوقوا عذابے ونذر࣌', NULL, 530, 'local:warsh-text.json'),
  ('warsh-54-40', 'warsh', 54, 40, 'وَلَقَدْ يَسَّرْنَا ࡰ۬لْقُرْءَانَ لِلذِّكْرِ فَهَلْ مِن مُّدَّكِرࣲ࣌', 'ولقد يسرنا ࡰلقرءان للذكر فهل من مدكر࣌', NULL, 530, 'local:warsh-text.json'),
  ('warsh-54-41', 'warsh', 54, 41, 'وَلَقَدْ جَآءَ ࢇالَ فِرْعَوْنَ ࡰ۬لنُّذُرُ࣌', 'ولقد جاء ࢇال فرعون ࡰلنذر࣌', NULL, 530, 'local:warsh-text.json'),
  ('warsh-54-42', 'warsh', 54, 42, 'كَذَّبُواْ بِـَٔايَٰتِنَا كُلِّهَا فَأَخَذْنَٰهُمُۥٓ أَخْذَ عَزِيزࣲ مُّقْتَدِرٍ࣌', 'كذبوا بايتنا كلها فأخذنهم أخذ عزيز مقتدر࣌', NULL, 530, 'local:warsh-text.json'),
  ('warsh-54-43', 'warsh', 54, 43, 'ࡰكُفَّارُكُمْ خَيْرࣱ مِّنُ ࡳوْلَٰٓئِكُمُۥٓ أَمْ لَكُم بَرَآءَةࣱ فِے ࡴ۬لزُّبُرِ࣌', 'ࡰكفاركم خير من ࡳولئكم أم لكم براءة فے ࡴلزبر࣌', NULL, 530, 'local:warsh-text.json'),
  ('warsh-54-44', 'warsh', 54, 44, 'أَمْ يَقُولُونَ نَحْنُ جَمِيعࣱ مُّنتَصِرࣱ࣌', 'أم يقولون نحن جميع منتصر࣌', NULL, 530, 'local:warsh-text.json'),
  ('warsh-54-45', 'warsh', 54, 45, 'سَيُهْزَمُ ࡲ۬لْجَمْعُ وَيُوَلُّونَ ࡰ۬لدُّبُرَ࣌', 'سيهزم ࡲلجمع ويولون ࡰلدبر࣌', NULL, 530, 'local:warsh-text.json'),
  ('warsh-54-46', 'warsh', 54, 46, 'بَلِ ࡴ۬لسَّاعَةُ مَوْعِدُهُمْ࣌ وَالسَّاعَةُ أَدْهٜىٰ وَأَمَرُّ࣌', 'بل ࡴلساعة موعدهم࣌ والساعة أدهى وأمر࣌', NULL, 530, 'local:warsh-text.json'),
  ('warsh-54-47', 'warsh', 54, 47, 'إِنَّ ࡰ۬لْمُجْرِمِينَ فِے ضَلَٰلࣲ وَسُعُرࣲ', 'إن ࡰلمجرمين فے ضلل وسعر', NULL, 530, 'local:warsh-text.json'),
  ('warsh-54-48', 'warsh', 54, 48, 'يَوْمَ يُسْحَبُونَ فِے ࡴ۬لنّٜارِ عَلَىٰ وُجُوهِهِمْ ذُوقُواْ مَسَّ سَقَرَ࣌', 'يوم يسحبون فے ࡴلنار على وجوههم ذوقوا مس سقر࣌', NULL, 530, 'local:warsh-text.json'),
  ('warsh-54-49', 'warsh', 54, 49, 'إِنَّا كُلَّ شَےْءٍ خَلَقْنَٰهُ بِقَدَرࣲ࣌', 'إنا كل شےء خلقنه بقدر࣌', NULL, 530, 'local:warsh-text.json'),
  ('warsh-54-50', 'warsh', 54, 50, 'وَمَآ أَمْرُنَآ إِلَّا وَٰحِدَةࣱ كَلَمْحِۢ بِالْبَصَرِ࣌', 'وما أمرنا إلا وحدة كلمح بالبصر࣌', NULL, 531, 'local:warsh-text.json'),
  ('warsh-54-51', 'warsh', 54, 51, 'وَلَقَدَ ࡰهْلَكْنَآ أَشْيَاعَكُمْ فَهَلْ مِن مُّدَّكِرࣲ࣌', 'ولقد ࡰهلكنا أشياعكم فهل من مدكر࣌', NULL, 531, 'local:warsh-text.json'),
  ('warsh-54-52', 'warsh', 54, 52, 'وَكُلُّ شَےْءࣲ فَعَلُوهُ فِے ࡴ۬لزُّبُرِ࣌', 'وكل شےء فعلوه فے ࡴلزبر࣌', NULL, 531, 'local:warsh-text.json'),
  ('warsh-54-53', 'warsh', 54, 53, 'وَكُلُّ صَغِيرࣲ وَكَبِيرࣲ مُّسْتَطَرٌ࣌', 'وكل صغير وكبير مستطر࣌', NULL, 531, 'local:warsh-text.json'),
  ('warsh-54-54', 'warsh', 54, 54, 'ࡴنَّ ࡰ۬لْمُتَّقِينَ فِے جَنَّٰتࣲ وَنَهَرࣲ', 'ࡴن ࡰلمتقين فے جنت ونهر', NULL, 531, 'local:warsh-text.json'),
  ('warsh-54-55', 'warsh', 54, 55, 'فِے مَقْعَدِ صِدْقٍ عِندَ مَلِيكࣲ مُّقْتَدِرٍ࣌', 'فے مقعد صدق عند مليك مقتدر࣌', NULL, 531, 'local:warsh-text.json'),
  ('warsh-55-1', 'warsh', 55, 1, 'ࡴ۬لرَّحْمَٰنُ عَلَّمَ ࡰ۬لْقُرْءَانَ࣌', 'ࡴلرحمن علم ࡰلقرءان࣌', NULL, 531, 'local:warsh-text.json'),
  ('warsh-55-2', 'warsh', 55, 2, 'خَلَقَ ࡰ۬لِانسَٰنَ عَلَّمَهُ ࡲ۬لْبَيَانَ࣌', 'خلق ࡰلانسن علمه ࡲلبيان࣌', NULL, 531, 'local:warsh-text.json'),
  ('warsh-55-3', 'warsh', 55, 3, 'ࡰ۬لشَّمْسُ وَالْقَمَرُ بِحُسْبَانࣲ࣌', 'ࡰلشمس والقمر بحسبان࣌', NULL, 531, 'local:warsh-text.json'),
  ('warsh-55-4', 'warsh', 55, 4, 'وَالنَّجْمُ وَالشَّجَرُ يَسْجُدَٰنِ࣌', 'والنجم والشجر يسجدن࣌', NULL, 531, 'local:warsh-text.json'),
  ('warsh-55-5', 'warsh', 55, 5, 'وَالسَّمَآءَ رَفَعَهَا وَوَضَعَ ࡰ۬لْمِيزَانَ', 'والسماء رفعها ووضع ࡰلميزان', NULL, 531, 'local:warsh-text.json'),
  ('warsh-55-6', 'warsh', 55, 6, 'أَلَّا تَطْغَوْاْ فِے ࡴ۬لْمِيزَانِ', 'ألا تطغوا فے ࡴلميزان', NULL, 531, 'local:warsh-text.json'),
  ('warsh-55-7', 'warsh', 55, 7, 'وَأَقِيمُواْ ࡲ۬لْوَزْنَ بِالْقِسْطِ وَلَا تُخْسِرُواْ ࡲ۬لْمِيزَانَ࣌', 'وأقيموا ࡲلوزن بالقسط ولا تخسروا ࡲلميزان࣌', NULL, 531, 'local:warsh-text.json'),
  ('warsh-55-8', 'warsh', 55, 8, 'وَالَارْضَ وَضَعَهَا لِلَانَامِ', 'والارض وضعها للانام', NULL, 531, 'local:warsh-text.json'),
  ('warsh-55-9', 'warsh', 55, 9, 'فِيهَا فَٰكِهَةࣱ وَالنَّخْلُ ذَاتُ ࡲ۬لَاكْمَامِ', 'فيها فكهة والنخل ذات ࡲلاكمام', NULL, 531, 'local:warsh-text.json'),
  ('warsh-55-10', 'warsh', 55, 10, 'وَالْحَبُّ ذُو ࡲ۬لْعَصْفِ وَالرَّيْحَانُ࣌', 'والحب ذو ࡲلعصف والريحان࣌', NULL, 531, 'local:warsh-text.json'),
  ('warsh-55-11', 'warsh', 55, 11, 'فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ࣌', 'فبأي ءالاء ربكما تكذبان࣌', NULL, 531, 'local:warsh-text.json'),
  ('warsh-55-12', 'warsh', 55, 12, 'خَلَقَ ࡰ۬لِانسَٰنَ مِن صَلْصَٰلࣲ كَالْفَخّٜارِ', 'خلق ࡰلانسن من صلصل كالفخار', NULL, 531, 'local:warsh-text.json'),
  ('warsh-55-13', 'warsh', 55, 13, 'وَخَلَقَ ࡰ۬لْجَآنَّ مِن مَّارِجࣲ مِّن نّٜارࣲ࣌', 'وخلق ࡰلجان من مارج من نار࣌', NULL, 531, 'local:warsh-text.json'),
  ('warsh-55-14', 'warsh', 55, 14, 'فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ࣌', 'فبأي ءالاء ربكما تكذبان࣌', NULL, 531, 'local:warsh-text.json'),
  ('warsh-55-15', 'warsh', 55, 15, 'رَبُّ ࡲ۬لْمَشْرِقَيْنِ وَرَبُّ ࡲ۬لْمَغْرِبَيْنِ࣌', 'رب ࡲلمشرقين ورب ࡲلمغربين࣌', NULL, 531, 'local:warsh-text.json'),
  ('warsh-55-16', 'warsh', 55, 16, 'فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ࣌', 'فبأي ءالاء ربكما تكذبان࣌', NULL, 531, 'local:warsh-text.json'),
  ('warsh-55-17', 'warsh', 55, 17, 'مَرَجَ ࡰ۬لْبَحْرَيْنِ يَلْتَقِيَٰنِ', 'مرج ࡰلبحرين يلتقين', NULL, 532, 'local:warsh-text.json'),
  ('warsh-55-18', 'warsh', 55, 18, 'بَيْنَهُمَا بَرْزَخࣱ لَّا يَبْغِيَٰنِ࣌', 'بينهما برزخ لا يبغين࣌', NULL, 532, 'local:warsh-text.json'),
  ('warsh-55-19', 'warsh', 55, 19, 'فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ࣌', 'فبأي ءالاء ربكما تكذبان࣌', NULL, 532, 'local:warsh-text.json'),
  ('warsh-55-20', 'warsh', 55, 20, 'يُخْرَجُ مِنْهُمَا ࡰ۬للُّؤْلُؤُاْ وَالْمَرْجَانُ࣌', 'يخرج منهما ࡰللؤلؤا والمرجان࣌', NULL, 532, 'local:warsh-text.json'),
  ('warsh-55-21', 'warsh', 55, 21, 'فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ࣌', 'فبأي ءالاء ربكما تكذبان࣌', NULL, 532, 'local:warsh-text.json'),
  ('warsh-55-22', 'warsh', 55, 22, 'وَلَهُ ࡲ۬لْجَوَارِ ࡴ۬لْمُنشَأَٰتُ فِے ࡴ۬لْبَحْرِ كَالَاعْلَٰمِ࣌', 'وله ࡲلجوار ࡴلمنشأت فے ࡴلبحر كالاعلم࣌', NULL, 532, 'local:warsh-text.json'),
  ('warsh-55-23', 'warsh', 55, 23, 'فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ࣌', 'فبأي ءالاء ربكما تكذبان࣌', NULL, 532, 'local:warsh-text.json'),
  ('warsh-55-24', 'warsh', 55, 24, 'كُلُّ مَنْ عَلَيْهَا فَانࣲ', 'كل من عليها فان', NULL, 532, 'local:warsh-text.json'),
  ('warsh-55-25', 'warsh', 55, 25, 'وَيَبْقٜىٰ وَجْهُ رَبِّكَ ذُو ࡲ۬لْجَلَٰلِ وَالِاكْرَامِ࣌', 'ويبقى وجه ربك ذو ࡲلجلل والاكرام࣌', NULL, 532, 'local:warsh-text.json'),
  ('warsh-55-26', 'warsh', 55, 26, 'فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ࣌', 'فبأي ءالاء ربكما تكذبان࣌', NULL, 532, 'local:warsh-text.json'),
  ('warsh-55-27', 'warsh', 55, 27, 'يَسْـَٔلُهُۥ مَن فِے ࡴ۬لسَّمَٰوَٰتِ وَالَارْضِ كُلَّ يَوْمٍ هُوَ فِے شَأْنࣲ࣌', 'يسله من فے ࡴلسموت والارض كل يوم هو فے شأن࣌', NULL, 532, 'local:warsh-text.json'),
  ('warsh-55-28', 'warsh', 55, 28, 'فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ࣌', 'فبأي ءالاء ربكما تكذبان࣌', NULL, 532, 'local:warsh-text.json'),
  ('warsh-55-29', 'warsh', 55, 29, 'سَنَفْرُغُ لَكُمُۥٓ أَيُّهَ ࡰ۬لثَّقَلَٰنِ࣌', 'سنفرغ لكم أيه ࡰلثقلن࣌', NULL, 532, 'local:warsh-text.json'),
  ('warsh-55-30', 'warsh', 55, 30, 'فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ࣌', 'فبأي ءالاء ربكما تكذبان࣌', NULL, 532, 'local:warsh-text.json'),
  ('warsh-55-31', 'warsh', 55, 31, 'يَٰمَعْشَرَ ࡰ۬لْجِنِّ وَالِانسِ إِنِ ࡴٜسْتَطَعْتُمُۥٓ أَن تَنفُذُواْ مِنَ ࡰقْطٜارِ ࡴ۬لسَّمَٰوَٰتِ وَالَارْضِ فَانفُذُواْ࣌ لَا تَنفُذُونَ إِلَّا بِسُلْطَٰنࣲ࣌', 'يمعشر ࡰلجن والانس إن ࡴستطعتم أن تنفذوا من ࡰقطار ࡴلسموت والارض فانفذوا࣌ لا تنفذون إلا بسلطن࣌', NULL, 532, 'local:warsh-text.json'),
  ('warsh-55-32', 'warsh', 55, 32, 'فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ࣌', 'فبأي ءالاء ربكما تكذبان࣌', NULL, 532, 'local:warsh-text.json'),
  ('warsh-55-33', 'warsh', 55, 33, 'يُرْسَلُ عَلَيْكُمَا شُوَاظࣱ مِّن نّٜارࣲ', 'يرسل عليكما شواظ من نار', NULL, 532, 'local:warsh-text.json'),
  ('warsh-55-34', 'warsh', 55, 34, 'وَنُحَاسࣱ فَلَا تَنتَصِرَٰنِ࣌', 'ونحاس فلا تنتصرن࣌', NULL, 532, 'local:warsh-text.json'),
  ('warsh-55-35', 'warsh', 55, 35, 'فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ࣌', 'فبأي ءالاء ربكما تكذبان࣌', NULL, 532, 'local:warsh-text.json'),
  ('warsh-55-36', 'warsh', 55, 36, 'فَإِذَا ࡰٜنشَقَّتِ ࡴ۬لسَّمَآءُ فَكَانَتْ وَرْدَةࣰ كَالدِّهَانِ', 'فإذا ࡰنشقت ࡴلسماء فكانت وردة كالدهان', NULL, 532, 'local:warsh-text.json'),
  ('warsh-55-37', 'warsh', 55, 37, 'فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ', 'فبأي ءالاء ربكما تكذبان', NULL, 532, 'local:warsh-text.json'),
  ('warsh-55-38', 'warsh', 55, 38, 'فَيَوْمَئِذࣲ لَّا يُسْـَٔلُ عَن ذَنۢبِهِۦٓ إِنسࣱ وَلَا جَآنࣱّ࣌', 'فيومئذ لا يسل عن ذنبه إنس ولا جان࣌', NULL, 532, 'local:warsh-text.json'),
  ('warsh-55-39', 'warsh', 55, 39, 'فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ࣌', 'فبأي ءالاء ربكما تكذبان࣌', NULL, 532, 'local:warsh-text.json'),
  ('warsh-55-40', 'warsh', 55, 40, '۞ يُعْرَفُ ࡲ۬لْمُجْرِمُونَ بِسِيمٜـٰهُمْ فَيُوخَذُ بِالنَّوَٰصِے وَالَاقْدَامِ࣌', 'يعرف ࡲلمجرمون بسيمهم فيوخذ بالنوصے والاقدام࣌', NULL, 532, 'local:warsh-text.json'),
  ('warsh-55-41', 'warsh', 55, 41, 'فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ࣌', 'فبأي ءالاء ربكما تكذبان࣌', NULL, 533, 'local:warsh-text.json'),
  ('warsh-55-42', 'warsh', 55, 42, 'هَٰذِهِۦ جَهَنَّمُ ࡲ۬لتِے يُكَذِّبُ بِهَا ࡰ۬لْمُجْرِمُونَ', 'هذه جهنم ࡲلتے يكذب بها ࡰلمجرمون', NULL, 533, 'local:warsh-text.json'),
  ('warsh-55-43', 'warsh', 55, 43, 'يَطُوفُونَ بَيْنَهَا وَبَيْنَ حَمِيمٍ اٰنࣲ࣌', 'يطوفون بينها وبين حميم ان࣌', NULL, 533, 'local:warsh-text.json'),
  ('warsh-55-44', 'warsh', 55, 44, 'فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ࣌', 'فبأي ءالاء ربكما تكذبان࣌', NULL, 533, 'local:warsh-text.json'),
  ('warsh-55-45', 'warsh', 55, 45, 'وَلِمَنْ خَافَ مَقَامَ رَبِّهِۦ جَنَّتَٰنِ', 'ولمن خاف مقام ربه جنتن', NULL, 533, 'local:warsh-text.json'),
  ('warsh-55-46', 'warsh', 55, 46, 'فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ', 'فبأي ءالاء ربكما تكذبان', NULL, 533, 'local:warsh-text.json'),
  ('warsh-55-47', 'warsh', 55, 47, 'ذَوَاتَآ أَفْنَانࣲ࣌', 'ذواتا أفنان࣌', NULL, 533, 'local:warsh-text.json'),
  ('warsh-55-48', 'warsh', 55, 48, 'فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ࣌', 'فبأي ءالاء ربكما تكذبان࣌', NULL, 533, 'local:warsh-text.json'),
  ('warsh-55-49', 'warsh', 55, 49, 'فِيهِمَا عَيْنَٰنِ تَجْرِيَٰنِ࣌', 'فيهما عينن تجرين࣌', NULL, 533, 'local:warsh-text.json'),
  ('warsh-55-50', 'warsh', 55, 50, 'فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ࣌', 'فبأي ءالاء ربكما تكذبان࣌', NULL, 533, 'local:warsh-text.json'),
  ('warsh-55-51', 'warsh', 55, 51, 'فِيهِمَا مِن كُلِّ فَٰكِهَةࣲ زَوْجَٰنِ࣌', 'فيهما من كل فكهة زوجن࣌', NULL, 533, 'local:warsh-text.json'),
