  ('warsh-55-55', 'warsh', 55, 55, 'فِيهِنَّ قَٰصِرَٰتُ ࡲ۬لطَّرْفِ لَمْ يَطْمِثْهُنَّ إِنسࣱ قَبْلَهُمْ وَلَا جَآنࣱّ࣌', 'فيهن قصرت ࡲلطرف لم يطمثهن إنس قبلهم ولا جان࣌', NULL, 533, 'local:warsh-text.json'),
  ('warsh-55-56', 'warsh', 55, 56, 'فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ࣌', 'فبأي ءالاء ربكما تكذبان࣌', NULL, 533, 'local:warsh-text.json'),
  ('warsh-55-57', 'warsh', 55, 57, 'كَأَنَّهُنَّ ࡰ۬لْيَاقُوتُ وَالْمَرْجَانُ࣌', 'كأنهن ࡰلياقوت والمرجان࣌', NULL, 533, 'local:warsh-text.json'),
  ('warsh-55-58', 'warsh', 55, 58, 'فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ࣌', 'فبأي ءالاء ربكما تكذبان࣌', NULL, 533, 'local:warsh-text.json'),
  ('warsh-55-59', 'warsh', 55, 59, 'هَلْ جَزَآءُ ࡲ۬لِاحْسَٰنِ إِلَّا ࡰ۬لِاحْسَٰنُ࣌', 'هل جزاء ࡲلاحسن إلا ࡰلاحسن࣌', NULL, 533, 'local:warsh-text.json'),
