  ('warsh-55-73', 'warsh', 55, 73, 'لَمْ يَطْمِثْهُنَّ إِنسࣱ قَبْلَهُمْ وَلَا جَآنࣱّ࣌', 'لم يطمثهن إنس قبلهم ولا جان࣌', NULL, 534, 'local:warsh-text.json'),
  ('warsh-55-74', 'warsh', 55, 74, 'فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ࣌', 'فبأي ءالاء ربكما تكذبان࣌', NULL, 534, 'local:warsh-text.json'),
  ('warsh-55-75', 'warsh', 55, 75, 'مُتَّكِـِٕينَ عَلَىٰ رَفْرَفٍ خُضْرࣲ وَعَبْقَرِيٍّ حِسَانࣲ࣌', 'متكين على رفرف خضر وعبقري حسان࣌', NULL, 534, 'local:warsh-text.json'),
  ('warsh-55-76', 'warsh', 55, 76, 'فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ࣌', 'فبأي ءالاء ربكما تكذبان࣌', NULL, 534, 'local:warsh-text.json'),
  ('warsh-55-77', 'warsh', 55, 77, 'تَبَٰرَكَ ࡰٜسْمُ رَبِّكَ ذِے ࡴ۬لْجَلَٰلِ وَالِاكْرَامِ࣌', 'تبرك ࡰسم ربك ذے ࡴلجلل والاكرام࣌', NULL, 534, 'local:warsh-text.json'),
  ('warsh-56-1', 'warsh', 56, 1, 'إِذَا وَقَعَتِ ࡴ۬لْوَاقِعَةُ', 'إذا وقعت ࡴلواقعة', NULL, 534, 'local:warsh-text.json'),
  ('warsh-56-2', 'warsh', 56, 2, 'لَيْسَ لِوَقْعَتِهَا كَٰذِبَةٌ࣌', 'ليس لوقعتها كذبة࣌', NULL, 534, 'local:warsh-text.json'),
  ('warsh-56-3', 'warsh', 56, 3, 'خَافِضَةࣱ رَّافِعَةٌ', 'خافضة رافعة', NULL, 534, 'local:warsh-text.json'),
  ('warsh-56-4', 'warsh', 56, 4, 'ࡴذَا رُجَّتِ ࡴ۬لَارْضُ رَجّاࣰ', 'ࡴذا رجت ࡴلارض رجا', NULL, 534, 'local:warsh-text.json'),
  ('warsh-56-5', 'warsh', 56, 5, 'وَبُسَّتِ ࡴ۬لْجِبَالُ بَسّاࣰ', 'وبست ࡴلجبال بسا', NULL, 534, 'local:warsh-text.json'),
  ('warsh-56-6', 'warsh', 56, 6, 'فَكَانَتْ هَبَآءࣰ مُّنۢبَثّاࣰ', 'فكانت هباء منبثا', NULL, 534, 'local:warsh-text.json'),
  ('warsh-56-7', 'warsh', 56, 7, 'وَكُنتُمُۥٓ أَزْوَٰجاࣰ ثَلَٰثَةࣰ࣌', 'وكنتم أزوجا ثلثة࣌', NULL, 534, 'local:warsh-text.json'),
  ('warsh-56-8', 'warsh', 56, 8, 'فَأَصْحَٰبُ ࡲ۬لْمَيْمَنَةِ', 'فأصحب ࡲلميمنة', NULL, 534, 'local:warsh-text.json'),
  ('warsh-56-9', 'warsh', 56, 9, 'مَآ أَصْحَٰبُ ࡲ۬لْمَيْمَنَةِ࣌', 'ما أصحب ࡲلميمنة࣌', NULL, 534, 'local:warsh-text.json'),
  ('warsh-56-10', 'warsh', 56, 10, 'وَأَصْحَٰبُ ࡲ۬لْمَشْـَٔمَةِ', 'وأصحب ࡲلمشمة', NULL, 534, 'local:warsh-text.json'),
  ('warsh-56-11', 'warsh', 56, 11, 'مَآ أَصْحَٰبُ ࡲ۬لْمَشْـَٔمَةِ࣌', 'ما أصحب ࡲلمشمة࣌', NULL, 534, 'local:warsh-text.json'),
  ('warsh-56-12', 'warsh', 56, 12, 'وَالسَّٰبِقُونَ ࡰ۬لسَّٰبِقُونَ࣌', 'والسبقون ࡰلسبقون࣌', NULL, 534, 'local:warsh-text.json'),
  ('warsh-56-13', 'warsh', 56, 13, 'أُوْلَٰٓئِكَ ࡰ۬لْمُقَرَّبُونَ', 'أولئك ࡰلمقربون', NULL, 534, 'local:warsh-text.json'),
  ('warsh-56-14', 'warsh', 56, 14, 'فِے جَنَّٰتِ ࡴ۬لنَّعِيمِ࣌', 'فے جنت ࡴلنعيم࣌', NULL, 534, 'local:warsh-text.json'),
  ('warsh-56-15', 'warsh', 56, 15, 'ثُلَّةࣱ مِّنَ ࡰ۬لَاوَّلِينَ', 'ثلة من ࡰلاولين', NULL, 534, 'local:warsh-text.json'),
  ('warsh-56-16', 'warsh', 56, 16, 'وَقَلِيلࣱ مِّنَ ࡰ۬لَاخِرِينَ', 'وقليل من ࡰلاخرين', NULL, 534, 'local:warsh-text.json'),
  ('warsh-56-17', 'warsh', 56, 17, 'عَلَىٰ سُرُرࣲ مَّوْضُونَةࣲ', 'على سرر موضونة', NULL, 534, 'local:warsh-text.json'),
  ('warsh-56-18', 'warsh', 56, 18, 'مُّتَّكِـِٕينَ عَلَيْهَا مُتَقَٰبِلِينَ࣌', 'متكين عليها متقبلين࣌', NULL, 534, 'local:warsh-text.json'),
  ('warsh-56-19', 'warsh', 56, 19, 'يَطُوفُ عَلَيْهِمْ وِلْدَٰنࣱ مُّخَلَّدُونَ', 'يطوف عليهم ولدن مخلدون', NULL, 535, 'local:warsh-text.json'),
  ('warsh-56-20', 'warsh', 56, 20, 'بِأَكْوَابࣲ وَأَبَارِيقَ', 'بأكواب وأباريق', NULL, 535, 'local:warsh-text.json'),
  ('warsh-56-21', 'warsh', 56, 21, 'وَكَأْسࣲ مِّن مَّعِينࣲ', 'وكأس من معين', NULL, 535, 'local:warsh-text.json'),
  ('warsh-56-22', 'warsh', 56, 22, 'لَّا يُصَدَّعُونَ عَنْهَا وَلَا يُنزَفُونَ', 'لا يصدعون عنها ولا ينزفون', NULL, 535, 'local:warsh-text.json'),
  ('warsh-56-23', 'warsh', 56, 23, 'وَفَٰكِهَةࣲ مِّمَّا يَتَخَيَّرُونَ', 'وفكهة مما يتخيرون', NULL, 535, 'local:warsh-text.json'),
  ('warsh-56-24', 'warsh', 56, 24, 'وَلَحْمِ طَيْرࣲ مِّمَّا يَشْتَهُونَ࣌', 'ولحم طير مما يشتهون࣌', NULL, 535, 'local:warsh-text.json'),
  ('warsh-56-25', 'warsh', 56, 25, 'وَحُورٌ عِينࣱ كَأَمْثَٰلِ ࡴ۬للُّؤْلُوِٕ ࡴ۬لْمَكْنُونِ', 'وحور عين كأمثل ࡴللؤلو ࡴلمكنون', NULL, 535, 'local:warsh-text.json'),
  ('warsh-56-26', 'warsh', 56, 26, 'جَزَآءَۢ بِمَا كَانُواْ يَعْمَلُونَ࣌', 'جزاء بما كانوا يعملون࣌', NULL, 535, 'local:warsh-text.json'),
  ('warsh-56-27', 'warsh', 56, 27, 'لَا يَسْمَعُونَ فِيهَا لَغْواࣰ وَلَا تَاثِيماً࣌', 'لا يسمعون فيها لغوا ولا تاثيما࣌', NULL, 535, 'local:warsh-text.json'),
  ('warsh-56-28', 'warsh', 56, 28, 'ࡴلَّا قِيلاࣰ سَلَٰماࣰ سَلَٰماࣰ࣌', 'ࡴلا قيلا سلما سلما࣌', NULL, 535, 'local:warsh-text.json'),
  ('warsh-56-29', 'warsh', 56, 29, 'وَأَصْحَٰبُ ࡲ۬لْيَمِينِ مَآ أَصْحَٰبُ ࡲ۬لْيَمِينِ࣌', 'وأصحب ࡲليمين ما أصحب ࡲليمين࣌', NULL, 535, 'local:warsh-text.json'),
  ('warsh-56-30', 'warsh', 56, 30, 'فِے سِدْرࣲ مَّخْضُودࣲ', 'فے سدر مخضود', NULL, 535, 'local:warsh-text.json'),
  ('warsh-56-31', 'warsh', 56, 31, 'وَطَلْحࣲ مَّنضُودࣲ', 'وطلح منضود', NULL, 535, 'local:warsh-text.json'),
  ('warsh-56-32', 'warsh', 56, 32, 'وَظِلࣲّ مَّمْدُودࣲ', 'وظل ممدود', NULL, 535, 'local:warsh-text.json'),
  ('warsh-56-33', 'warsh', 56, 33, 'وَمَآءࣲ مَّسْكُوبࣲ', 'وماء مسكوب', NULL, 535, 'local:warsh-text.json'),
  ('warsh-56-34', 'warsh', 56, 34, 'وَفَٰكِهَةࣲ كَثِيرَةࣲ', 'وفكهة كثيرة', NULL, 535, 'local:warsh-text.json'),
  ('warsh-56-35', 'warsh', 56, 35, 'لَّا مَقْطُوعَةࣲ وَلَا مَمْنُوعَةࣲ', 'لا مقطوعة ولا ممنوعة', NULL, 535, 'local:warsh-text.json'),
  ('warsh-56-36', 'warsh', 56, 36, 'وَفُرُشࣲ مَّرْفُوعَةٍ࣌', 'وفرش مرفوعة࣌', NULL, 535, 'local:warsh-text.json'),
  ('warsh-56-37', 'warsh', 56, 37, 'ࡴنَّآ أَنشَأْنَٰهُنَّ إِنشَآءࣰ', 'ࡴنا أنشأنهن إنشاء', NULL, 535, 'local:warsh-text.json'),
  ('warsh-56-38', 'warsh', 56, 38, 'فَجَعَلْنَٰهُنَّ أَبْكَاراً', 'فجعلنهن أبكارا', NULL, 535, 'local:warsh-text.json'),
  ('warsh-56-39', 'warsh', 56, 39, 'عُرُباً ࡰتْرَاباࣰ', 'عربا ࡰترابا', NULL, 535, 'local:warsh-text.json'),
  ('warsh-56-40', 'warsh', 56, 40, 'لِّأَصْحَٰبِ ࡴ۬لْيَمِينِ࣌', 'لأصحب ࡴليمين࣌', NULL, 535, 'local:warsh-text.json'),
  ('warsh-56-41', 'warsh', 56, 41, 'ثُلَّةࣱ مِّنَ ࡰ۬لَاوَّلِينَ', 'ثلة من ࡰلاولين', NULL, 535, 'local:warsh-text.json'),
  ('warsh-56-42', 'warsh', 56, 42, 'وَثُلَّةࣱ مِّنَ ࡰ۬لَاخِرِينَ࣌', 'وثلة من ࡰلاخرين࣌', NULL, 535, 'local:warsh-text.json'),
  ('warsh-56-43', 'warsh', 56, 43, 'وَأَصْحَٰبُ ࡲ۬لشِّمَالِ', 'وأصحب ࡲلشمال', NULL, 535, 'local:warsh-text.json'),
  ('warsh-56-44', 'warsh', 56, 44, 'مَآ أَصْحَٰبُ ࡲ۬لشِّمَالِ࣌', 'ما أصحب ࡲلشمال࣌', NULL, 535, 'local:warsh-text.json'),
  ('warsh-56-45', 'warsh', 56, 45, 'فِے سَمُومࣲ وَحَمِيمࣲ', 'فے سموم وحميم', NULL, 535, 'local:warsh-text.json'),
  ('warsh-56-46', 'warsh', 56, 46, 'وَظِلࣲّ مِّنْ يَّحْمُومࣲ', 'وظل من يحموم', NULL, 535, 'local:warsh-text.json'),
  ('warsh-56-47', 'warsh', 56, 47, 'لَّا بَارِدࣲ وَلَا كَرِيمٍ࣌', 'لا بارد ولا كريم࣌', NULL, 535, 'local:warsh-text.json'),
  ('warsh-56-48', 'warsh', 56, 48, 'ࡴنَّهُمْ كَانُواْ قَبْلَ ذَٰلِكَ مُتْرَفِينَ࣌', 'ࡴنهم كانوا قبل ذلك مترفين࣌', NULL, 535, 'local:warsh-text.json'),
  ('warsh-56-49', 'warsh', 56, 49, 'وَكَانُواْ يُصِرُّونَ عَلَى ࡰ۬لْحِنثِ ࡴ۬لْعَظِيمِ࣌', 'وكانوا يصرون على ࡰلحنث ࡴلعظيم࣌', NULL, 535, 'local:warsh-text.json'),
  ('warsh-56-50', 'warsh', 56, 50, 'وَكَانُواْ يَقُولُونَ أَئِذَا مِتْنَا وَكُنَّا تُرَاباࣰ وَعِظَٰماً ࡴنَّا لَمَبْعُوثُونَ', 'وكانوا يقولون أئذا متنا وكنا ترابا وعظما ࡴنا لمبعوثون', NULL, 535, 'local:warsh-text.json'),
  ('warsh-56-51', 'warsh', 56, 51, 'أَوَءَابَآؤُنَا ࡰ۬لَاوَّلُونَ࣌', 'أوءاباؤنا ࡰلاولون࣌', NULL, 535, 'local:warsh-text.json'),
  ('warsh-56-52', 'warsh', 56, 52, '۞ قُلِ ࡴنَّ ࡰ۬لَاوَّلِينَ وَالَاخِرِينَ لَمَجْمُوعُونَ', 'قل ࡴن ࡰلاولين والاخرين لمجموعون', NULL, 535, 'local:warsh-text.json'),
  ('warsh-56-53', 'warsh', 56, 53, 'إِلَىٰ مِيقَٰتِ يَوْمࣲ مَّعْلُومࣲ࣌', 'إلى ميقت يوم معلوم࣌', NULL, 535, 'local:warsh-text.json'),
  ('warsh-56-54', 'warsh', 56, 54, 'ثُمَّ إِنَّكُمُۥٓ أَيُّهَا ࡰ۬لضَّآلُّونَ ࡰ۬لْمُكَذِّبُونَ', 'ثم إنكم أيها ࡰلضالون ࡰلمكذبون', NULL, 536, 'local:warsh-text.json'),
  ('warsh-56-55', 'warsh', 56, 55, 'لَأٓكِلُونَ مِن شَجَرࣲ مِّن زَقُّومࣲ', 'لأكلون من شجر من زقوم', NULL, 536, 'local:warsh-text.json'),
  ('warsh-56-56', 'warsh', 56, 56, 'فَمَالِـُٔونَ مِنْهَا ࡰ۬لْبُطُونَ', 'فمالون منها ࡰلبطون', NULL, 536, 'local:warsh-text.json'),
  ('warsh-56-57', 'warsh', 56, 57, 'فَشَٰرِبُونَ عَلَيْهِ مِنَ ࡰ۬لْحَمِيمِ', 'فشربون عليه من ࡰلحميم', NULL, 536, 'local:warsh-text.json'),
  ('warsh-56-58', 'warsh', 56, 58, 'فَشَٰرِبُونَ شُرْبَ ࡰ۬لْهِيمِ࣌', 'فشربون شرب ࡰلهيم࣌', NULL, 536, 'local:warsh-text.json'),
  ('warsh-56-59', 'warsh', 56, 59, 'هَٰذَا نُزُلُهُمْ يَوْمَ ࡰ۬لدِّينِ࣌', 'هذا نزلهم يوم ࡰلدين࣌', NULL, 536, 'local:warsh-text.json'),
  ('warsh-56-60', 'warsh', 56, 60, 'نَحْنُ خَلَقْنَٰكُمْ࣌ فَلَوْلَا تُصَدِّقُونَ࣌', 'نحن خلقنكم࣌ فلولا تصدقون࣌', NULL, 536, 'local:warsh-text.json'),
  ('warsh-56-61', 'warsh', 56, 61, 'أَفَرَٰٓيْتُم مَّا تُمْنُونَ', 'أفريتم ما تمنون', NULL, 536, 'local:warsh-text.json'),
  ('warsh-56-62', 'warsh', 56, 62, 'ءَآنتُمْ تَخْلُقُونَهُۥٓ أَمْ نَحْنُ ࡲ۬لْخَٰلِقُونَ࣌', 'ءانتم تخلقونه أم نحن ࡲلخلقون࣌', NULL, 536, 'local:warsh-text.json'),
  ('warsh-56-63', 'warsh', 56, 63, 'نَحْنُ قَدَّرْنَا بَيْنَكُمُ ࡲ۬لْمَوْتَ وَمَا نَحْنُ بِمَسْبُوقِينَ', 'نحن قدرنا بينكم ࡲلموت وما نحن بمسبوقين', NULL, 536, 'local:warsh-text.json'),
  ('warsh-56-64', 'warsh', 56, 64, 'عَلَىٰٓ أَن نُّبَدِّلَ أَمْثَٰلَكُمْ وَنُنشِئَكُمْ فِے مَا لَا تَعْلَمُونَ࣌', 'على أن نبدل أمثلكم وننشئكم فے ما لا تعلمون࣌', NULL, 536, 'local:warsh-text.json'),
  ('warsh-56-65', 'warsh', 56, 65, 'وَلَقَدْ عَلِمْتُمُ ࡲ۬لنَّشْأَةَ ࡰ۬لُاولٜىٰ࣌ فَلَوْلَا تَذَّكَّرُونَ࣌', 'ولقد علمتم ࡲلنشأة ࡰلاولى࣌ فلولا تذكرون࣌', NULL, 536, 'local:warsh-text.json'),
  ('warsh-56-66', 'warsh', 56, 66, 'أَفَرَٰٓيْتُم مَّا تَحْرُثُونَ', 'أفريتم ما تحرثون', NULL, 536, 'local:warsh-text.json'),
  ('warsh-56-67', 'warsh', 56, 67, 'ءَآنتُمْ تَزْرَعُونَهُۥٓ أَمْ نَحْنُ ࡲ۬لزَّٰرِعُونَ࣌', 'ءانتم تزرعونه أم نحن ࡲلزرعون࣌', NULL, 536, 'local:warsh-text.json'),
  ('warsh-56-68', 'warsh', 56, 68, 'لَوْ نَشَآءُ لَجَعَلْنَٰهُ حُطَٰماࣰ فَظَلْتُمْ تَفَكَّهُونَ', 'لو نشاء لجعلنه حطما فظلتم تفكهون', NULL, 536, 'local:warsh-text.json'),
  ('warsh-56-69', 'warsh', 56, 69, 'إِنَّا لَمُغْرَمُونَ', 'إنا لمغرمون', NULL, 536, 'local:warsh-text.json'),
  ('warsh-56-70', 'warsh', 56, 70, 'بَلْ نَحْنُ مَحْرُومُونَ࣌', 'بل نحن محرومون࣌', NULL, 536, 'local:warsh-text.json'),
  ('warsh-56-71', 'warsh', 56, 71, 'أَفَرَٰٓيْتُمُ ࡲ۬لْمَآءَ ࡰ۬لذِے تَشْرَبُونَ', 'أفريتم ࡲلماء ࡰلذے تشربون', NULL, 536, 'local:warsh-text.json'),
  ('warsh-56-72', 'warsh', 56, 72, 'ءَآنتُمُۥٓ أَنزَلْتُمُوهُ مِنَ ࡰ۬لْمُزْنِ أَمْ نَحْنُ ࡲ۬لْمُنزِلُونَ࣌', 'ءانتم أنزلتموه من ࡰلمزن أم نحن ࡲلمنزلون࣌', NULL, 536, 'local:warsh-text.json'),
  ('warsh-56-73', 'warsh', 56, 73, 'لَوْ نَشَآءُ جَعَلْنَٰهُ أُجَاجاࣰ࣌ فَلَوْلَا تَشْكُرُونَ࣌', 'لو نشاء جعلنه أجاجا࣌ فلولا تشكرون࣌', NULL, 536, 'local:warsh-text.json'),
  ('warsh-56-74', 'warsh', 56, 74, 'أَفَرَٰٓيْتُمُ ࡲ۬لنَّارَ ࡰ۬لتِے تُورُونَ', 'أفريتم ࡲلنار ࡰلتے تورون', NULL, 536, 'local:warsh-text.json'),
  ('warsh-56-75', 'warsh', 56, 75, 'ءَآنتُمُۥٓ أَنشَأْتُمْ شَجَرَتَهَآ أَمْ نَحْنُ ࡲ۬لْمُنشِـُٔونَ࣌', 'ءانتم أنشأتم شجرتها أم نحن ࡲلمنشون࣌', NULL, 536, 'local:warsh-text.json'),
  ('warsh-56-76', 'warsh', 56, 76, 'نَحْنُ جَعَلْنَٰهَا تَذْكِرَةࣰ وَمَتَٰعاࣰ لِّلْمُقْوِينَ࣌', 'نحن جعلنها تذكرة ومتعا للمقوين࣌', NULL, 536, 'local:warsh-text.json'),
  ('warsh-56-77', 'warsh', 56, 77, 'فَسَبِّحْ بِاسْمِ رَبِّكَ ࡰ۬لْعَظِيمِ࣌', 'فسبح باسم ربك ࡰلعظيم࣌', NULL, 536, 'local:warsh-text.json'),
  ('warsh-56-78', 'warsh', 56, 78, '۞ فَلَآ أُقْسِمُ بِمَوَٰقِعِ ࡴ۬لنُّجُومِ', 'فلا أقسم بموقع ࡴلنجوم', NULL, 536, 'local:warsh-text.json'),
  ('warsh-56-79', 'warsh', 56, 79, 'وَإِنَّهُۥ لَقَسَمࣱ لَّوْ تَعْلَمُونَ عَظِيمٌ', 'وإنه لقسم لو تعلمون عظيم', NULL, 536, 'local:warsh-text.json'),
  ('warsh-56-80', 'warsh', 56, 80, 'ࡴنَّهُۥ لَقُرْءَانࣱ كَرِيمࣱ', 'ࡴنه لقرءان كريم', NULL, 537, 'local:warsh-text.json'),
  ('warsh-56-81', 'warsh', 56, 81, 'فِے كِتَٰبࣲ مَّكْنُونࣲ', 'فے كتب مكنون', NULL, 537, 'local:warsh-text.json'),
  ('warsh-56-82', 'warsh', 56, 82, 'لَّا يَمَسُّهُۥٓ إِلَّا ࡰ۬لْمُطَهَّرُونَ࣌', 'لا يمسه إلا ࡰلمطهرون࣌', NULL, 537, 'local:warsh-text.json'),
  ('warsh-56-83', 'warsh', 56, 83, 'تَنزِيلࣱ مِّن رَّبِّ ࡴ۬لْعَٰلَمِينَ࣌', 'تنزيل من رب ࡴلعلمين࣌', NULL, 537, 'local:warsh-text.json'),
  ('warsh-56-84', 'warsh', 56, 84, 'أَفَبِهَٰذَا ࡰ۬لْحَدِيثِ أَنتُم مُّدْهِنُونَ', 'أفبهذا ࡰلحديث أنتم مدهنون', NULL, 537, 'local:warsh-text.json'),
  ('warsh-56-85', 'warsh', 56, 85, 'وَتَجْعَلُونَ رِزْقَكُمُۥٓ أَنَّكُمْ تُكَذِّبُونَ࣌', 'وتجعلون رزقكم أنكم تكذبون࣌', NULL, 537, 'local:warsh-text.json'),
  ('warsh-56-86', 'warsh', 56, 86, 'فَلَوْلَآ إِذَا بَلَغَتِ ࡴ۬لْحُلْقُومَ', 'فلولا إذا بلغت ࡴلحلقوم', NULL, 537, 'local:warsh-text.json'),
  ('warsh-56-87', 'warsh', 56, 87, 'وَأَنتُمْ حِينَئِذࣲ تَنظُرُونَ', 'وأنتم حينئذ تنظرون', NULL, 537, 'local:warsh-text.json'),
  ('warsh-56-88', 'warsh', 56, 88, 'وَنَحْنُ أَقْرَبُ إِلَيْهِ مِنكُمْ وَلَٰكِن لَّا تُبْصِرُونَ', 'ونحن أقرب إليه منكم ولكن لا تبصرون', NULL, 537, 'local:warsh-text.json'),
  ('warsh-56-89', 'warsh', 56, 89, 'فَلَوْلَآ إِن كُنتُمْ غَيْرَ مَدِينِينَ', 'فلولا إن كنتم غير مدينين', NULL, 537, 'local:warsh-text.json'),
  ('warsh-56-90', 'warsh', 56, 90, 'تَرْجِعُونَهَآ إِن كُنتُمْ صَٰدِقِينَ࣌', 'ترجعونها إن كنتم صدقين࣌', NULL, 537, 'local:warsh-text.json'),
  ('warsh-56-91', 'warsh', 56, 91, 'فَأَمَّآ إِن كَانَ مِنَ ࡰ۬لْمُقَرَّبِينَ', 'فأما إن كان من ࡰلمقربين', NULL, 537, 'local:warsh-text.json'),
  ('warsh-56-92', 'warsh', 56, 92, 'فَرَوْحࣱ وَرَيْحَانࣱ وَجَنَّتُ نَعِيمࣲ࣌', 'فروح وريحان وجنت نعيم࣌', NULL, 537, 'local:warsh-text.json'),
  ('warsh-56-93', 'warsh', 56, 93, 'وَأَمَّآ إِن كَانَ مِنَ ࡰصْحَٰبِ ࡴ۬لْيَمِينِ', 'وأما إن كان من ࡰصحب ࡴليمين', NULL, 537, 'local:warsh-text.json'),
  ('warsh-56-94', 'warsh', 56, 94, 'فَسَلَٰمࣱ لَّكَ مِنَ ࡰصْحَٰبِ ࡴ۬لْيَمِينِ࣌', 'فسلم لك من ࡰصحب ࡴليمين࣌', NULL, 537, 'local:warsh-text.json'),
  ('warsh-56-95', 'warsh', 56, 95, 'وَأَمَّآ إِن كَانَ مِنَ ࡰ۬لْمُكَذِّبِينَ ࡰ۬لضَّآلِّينَ', 'وأما إن كان من ࡰلمكذبين ࡰلضالين', NULL, 537, 'local:warsh-text.json'),
  ('warsh-56-96', 'warsh', 56, 96, 'فَنُزُلࣱ مِّنْ حَمِيمࣲ', 'فنزل من حميم', NULL, 537, 'local:warsh-text.json'),
  ('warsh-56-97', 'warsh', 56, 97, 'وَتَصْلِيَةُ جَحِيمٍ࣌', 'وتصلية جحيم࣌', NULL, 537, 'local:warsh-text.json'),
  ('warsh-56-98', 'warsh', 56, 98, 'ࡴنَّ هَٰذَا لَهُوَ حَقُّ ࡲ۬لْيَقِينِ࣌', 'ࡴن هذا لهو حق ࡲليقين࣌', NULL, 537, 'local:warsh-text.json'),
  ('warsh-56-99', 'warsh', 56, 99, 'فَسَبِّحْ بِاسْمِ رَبِّكَ ࡰ۬لْعَظِيمِ࣌', 'فسبح باسم ربك ࡰلعظيم࣌', NULL, 537, 'local:warsh-text.json'),
  ('warsh-57-1', 'warsh', 57, 1, 'سَبَّحَ لِلهِ مَا فِے ࡴ۬لسَّمَٰوَٰتِ وَالَارْضِ࣌ وَهُوَ ࡰ۬لْعَزِيزُ ࡲ۬لْحَكِيمُ࣌', 'سبح لله ما فے ࡴلسموت والارض࣌ وهو ࡰلعزيز ࡲلحكيم࣌', NULL, 537, 'local:warsh-text.json'),
  ('warsh-57-2', 'warsh', 57, 2, 'لَهُۥ مُلْكُ ࡲ۬لسَّمَٰوَٰتِ وَالَارْضِ يُحْيِۦ وَيُمِيتُ࣌ وَهُوَ عَلَىٰ كُلِّ شَےْءࣲ قَدِيرٌ࣌', 'له ملك ࡲلسموت والارض يحي ويميت࣌ وهو على كل شےء قدير࣌', NULL, 537, 'local:warsh-text.json'),
  ('warsh-57-3', 'warsh', 57, 3, 'هُوَ ࡰ۬لَاوَّلُ وَالَاخِرُ وَالظَّٰهِرُ وَالْبَاطِنُ࣌ وَهُوَ بِكُلِّ شَےْءٍ عَلِيمٌ࣌', 'هو ࡰلاول والاخر والظهر والباطن࣌ وهو بكل شےء عليم࣌', NULL, 537, 'local:warsh-text.json'),
  ('warsh-57-4', 'warsh', 57, 4, 'هُوَ ࡰ۬لذِے خَلَقَ ࡰ۬لسَّمَٰوَٰتِ وَالَارْضَ فِے سِتَّةِ أَيَّامࣲ ثُمَّ ࡰٜسْتَوٜىٰ عَلَى ࡰ۬لْعَرْشِ࣌ يَعْلَمُ مَا يَلِجُ فِے ࡴ۬لَارْضِ وَمَا يَخْرُجُ مِنْهَا وَمَا يَنزِلُ مِنَ ࡰ۬لسَّمَآءِ وَمَا يَعْرُجُ فِيهَا࣌ وَهُوَ مَعَكُمُۥٓ أَيْنَ مَا كُنتُمْ࣌ وَاللَّهُ بِمَا تَعْمَلُونَ بَصِيرࣱ࣌', 'هو ࡰلذے خلق ࡰلسموت والارض فے ستة أيام ثم ࡰستوى على ࡰلعرش࣌ يعلم ما يلج فے ࡴلارض وما يخرج منها وما ينزل من ࡰلسماء وما يعرج فيها࣌ وهو معكم أين ما كنتم࣌ والله بما تعملون بصير࣌', NULL, 538, 'local:warsh-text.json'),
  ('warsh-57-5', 'warsh', 57, 5, 'لَّهُۥ مُلْكُ ࡲ۬لسَّمَٰوَٰتِ وَالَارْضِ࣌ وَإِلَى ࡰ۬للَّهِ تُرْجَعُ ࡲ۬لُامُورُ࣌', 'له ملك ࡲلسموت والارض࣌ وإلى ࡰلله ترجع ࡲلامور࣌', NULL, 538, 'local:warsh-text.json'),
  ('warsh-57-6', 'warsh', 57, 6, 'يُولِجُ ࡲ۬ليْلَ فِے ࡴ۬لنَّهٜارِ وَيُولِجُ ࡲ۬لنَّهَارَ فِے ࡴ۬ليْلِ࣌ وَهُوَ عَلِيمُۢ بِذَاتِ ࡴ۬لصُّدُورِ࣌', 'يولج ࡲليل فے ࡴلنهار ويولج ࡲلنهار فے ࡴليل࣌ وهو عليم بذات ࡴلصدور࣌', NULL, 538, 'local:warsh-text.json'),
  ('warsh-57-7', 'warsh', 57, 7, '۞ ءَامِنُواْ بِاللَّهِ وَرَسُولِهِۦ وَأَنفِقُواْ مِمَّا جَعَلَكُم مُّسْتَخْلَفِينَ فِيهِ࣌ فَالذِينَ ءَامَنُواْ مِنكُمْ وَأَنفَقُواْ لَهُمُۥٓ أَجْرࣱ كَبِيرࣱ࣌', 'ءامنوا بالله ورسوله وأنفقوا مما جعلكم مستخلفين فيه࣌ فالذين ءامنوا منكم وأنفقوا لهم أجر كبير࣌', NULL, 538, 'local:warsh-text.json'),
  ('warsh-57-8', 'warsh', 57, 8, 'وَمَا لَكُمْ لَا تُومِنُونَ بِاللَّهِ وَالرَّسُولُ يَدْعُوكُمْ لِتُومِنُواْ بِرَبِّكُمْ وَقَدَ ࡰخَذَ مِيثَٰقَكُمُۥٓ إِن كُنتُم مُّومِنِينَ࣌', 'وما لكم لا تومنون بالله والرسول يدعوكم لتومنوا بربكم وقد ࡰخذ ميثقكم إن كنتم مومنين࣌', NULL, 538, 'local:warsh-text.json'),
  ('warsh-57-9', 'warsh', 57, 9, 'هُوَ ࡰ۬لذِے يُنَزِّلُ عَلَىٰ عَبْدِهِۦٓ ءَايَٰتِۢ بَيِّنَٰتࣲ لِّيُخْرِجَكُم مِّنَ ࡰ۬لظُّلُمَٰتِ إِلَى ࡰ۬لنُّورِ࣌ وَإِنَّ ࡰ۬للَّهَ بِكُمْ لَرَءُوفࣱ رَّحِيمࣱ࣌', 'هو ࡰلذے ينزل على عبده ءايت بينت ليخرجكم من ࡰلظلمت إلى ࡰلنور࣌ وإن ࡰلله بكم لرءوف رحيم࣌', NULL, 538, 'local:warsh-text.json'),
  ('warsh-57-10', 'warsh', 57, 10, 'وَمَا لَكُمُۥٓ أَلَّا تُنفِقُواْ فِے سَبِيلِ ࡴ۬للَّهِ وَلِلهِ مِيرَٰثُ ࡲ۬لسَّمَٰوَٰتِ وَالَارْضِ࣌ لَا يَسْتَوِے مِنكُم مَّنَ ࡰنفَقَ مِن قَبْلِ ࡴ۬لْفَتْحِ وَقَٰتَلَ࣌ أُوْلَٰٓئِكَ أَعْظَمُ دَرَجَةࣰ مِّنَ ࡰ۬لذِينَ أَنفَقُواْ مِنۢ بَعْدُ وَقَٰتَلُواْ࣌ وَكُلّاࣰ وَعَدَ ࡰ۬للَّهُ ࡲ۬لْحُسْنٜىٰ࣌ وَاللَّهُ بِمَا تَعْمَلُونَ خَبِيرࣱ࣌', 'وما لكم ألا تنفقوا فے سبيل ࡴلله ولله ميرث ࡲلسموت والارض࣌ لا يستوے منكم من ࡰنفق من قبل ࡴلفتح وقتل࣌ أولئك أعظم درجة من ࡰلذين أنفقوا من بعد وقتلوا࣌ وكلا وعد ࡰلله ࡲلحسنى࣌ والله بما تعملون خبير࣌', NULL, 538, 'local:warsh-text.json'),
  ('warsh-57-11', 'warsh', 57, 11, 'مَّن ذَا ࡰ۬لذِے يُقْرِضُ ࡲ۬للَّهَ قَرْضاً حَسَناࣰ فَيُضَٰعِفُهُۥ لَهُۥ وَلَهُۥٓ أَجْرࣱ كَرِيمࣱ࣌', 'من ذا ࡰلذے يقرض ࡲلله قرضا حسنا فيضعفه له وله أجر كريم࣌', NULL, 538, 'local:warsh-text.json'),
  ('warsh-57-12', 'warsh', 57, 12, 'يَوْمَ تَرَى ࡰ۬لْمُومِنِينَ وَالْمُومِنَٰتِ يَسْعٜىٰ نُورُهُم بَيْنَ أَيْدِيهِمْ وَبِأَيْمَٰنِهِم࣌ بُشْرٜيٰكُمُ ࡲ۬لْيَوْمَ جَنَّٰتࣱ تَجْرِے مِن تَحْتِهَا ࡰ۬لَانْهَٰرُ خَٰلِدِينَ فِيهَا࣌ ذَٰلِكَ هُوَ ࡰ۬لْفَوْزُ ࡲ۬لْعَظِيمُ࣌', 'يوم ترى ࡰلمومنين والمومنت يسعى نورهم بين أيديهم وبأيمنهم࣌ بشريكم ࡲليوم جنت تجرے من تحتها ࡰلانهر خلدين فيها࣌ ذلك هو ࡰلفوز ࡲلعظيم࣌', NULL, 539, 'local:warsh-text.json'),
  ('warsh-57-13', 'warsh', 57, 13, 'يَوْمَ يَقُولُ ࡲ۬لْمُنَٰفِقُونَ وَالْمُنَٰفِقَٰتُ لِلذِينَ ءَامَنُواْ ࡲ࢈نظُرُونَا نَقْتَبِسْ مِن نُّورِكُمْ قِيلَ ࡰٜرْجِعُواْ وَرَآءَكُمْ فَالْتَمِسُواْ نُوراࣰ࣌ فَضُرِبَ بَيْنَهُم بِسُورࣲ لَّهُۥ بَابُۢ بَاطِنُهُۥ فِيهِ ࡴ۬لرَّحْمَةُ وَظَٰهِرُهُۥ مِن قِبَلِهِ ࡴ۬لْعَذَابُ࣌ يُنَادُونَهُمُۥٓ أَلَمْ نَكُن مَّعَكُمْ࣌ قَالُواْ بَلٜىٰ وَلَٰكِنَّكُمْ فَتَنتُمُۥٓ أَنفُسَكُمْ وَتَرَبَّصْتُمْ وَارْتَبْتُمْ وَغَرَّتْكُمُ ࡲ۬لَامَانِيُّ حَتَّىٰ جَآءَ امْرُ ࡲ۬للَّهِ وَغَرَّكُم بِاللَّهِ ࡴ۬لْغَرُورُ࣌', 'يوم يقول ࡲلمنفقون والمنفقت للذين ءامنوا ࡲ࢈نظرونا نقتبس من نوركم قيل ࡰرجعوا وراءكم فالتمسوا نورا࣌ فضرب بينهم بسور له باب باطنه فيه ࡴلرحمة وظهره من قبله ࡴلعذاب࣌ ينادونهم ألم نكن معكم࣌ قالوا بلى ولكنكم فتنتم أنفسكم وتربصتم وارتبتم وغرتكم ࡲلاماني حتى جاء امر ࡲلله وغركم بالله ࡴلغرور࣌', NULL, 539, 'local:warsh-text.json'),
  ('warsh-57-14', 'warsh', 57, 14, 'فَالْيَوْمَ لَا يُوخَذُ مِنكُمْ فِدْيَةࣱ وَلَا مِنَ ࡰ۬لذِينَ كَفَرُواْ مَأْوٜيٰكُمُ ࡲ۬لنَّارُ هِيَ مَوْلٜيٰكُمْ࣌ وَبِيسَ ࡰ۬لْمَصِيرُ࣌', 'فاليوم لا يوخذ منكم فدية ولا من ࡰلذين كفروا مأويكم ࡲلنار هي موليكم࣌ وبيس ࡰلمصير࣌', NULL, 539, 'local:warsh-text.json'),
  ('warsh-57-15', 'warsh', 57, 15, '۞ أَلَمْ يَانِ لِلذِينَ ءَامَنُوٓاْ أَن تَخْشَعَ قُلُوبُهُمْ لِذِكْرِ ࡴ۬للَّهِ وَمَا نَزَلَ مِنَ ࡰ۬لْحَقِّ࣌ وَلَا يَكُونُواْ كَالذِينَ أُوتُواْ ࡲ۬لْكِتَٰبَ مِن قَبْلُ فَطَالَ عَلَيْهِمُ ࡲ۬لَامَدُ فَقَسَتْ قُلُوبُهُمْ࣌ وَكَثِيرࣱ مِّنْهُمْ فَٰسِقُونَ࣌', 'ألم يان للذين ءامنوا أن تخشع قلوبهم لذكر ࡴلله وما نزل من ࡰلحق࣌ ولا يكونوا كالذين أوتوا ࡲلكتب من قبل فطال عليهم ࡲلامد فقست قلوبهم࣌ وكثير منهم فسقون࣌', NULL, 539, 'local:warsh-text.json'),
  ('warsh-57-16', 'warsh', 57, 16, 'ࡰٜعْلَمُوٓاْ أَنَّ ࡰ۬للَّهَ يُحْيِ ࡴ۬لَارْضَ بَعْدَ مَوْتِهَا࣌ قَدْ بَيَّنَّا لَكُمُ ࡲ۬لَايَٰتِ لَعَلَّكُمْ تَعْقِلُونَ࣌', 'ࡰعلموا أن ࡰلله يحي ࡴلارض بعد موتها࣌ قد بينا لكم ࡲلايت لعلكم تعقلون࣌', NULL, 539, 'local:warsh-text.json'),
  ('warsh-57-17', 'warsh', 57, 17, 'إِنَّ ࡰ۬لْمُصَّدِّقِينَ وَالْمُصَّدِّقَٰتِ وَأَقْرَضُواْ ࡲ۬للَّهَ قَرْضاً حَسَناࣰ يُضَٰعَفُ لَهُمْ وَلَهُمُۥٓ أَجْرࣱ كَرِيمࣱ࣌', 'إن ࡰلمصدقين والمصدقت وأقرضوا ࡲلله قرضا حسنا يضعف لهم ولهم أجر كريم࣌', NULL, 539, 'local:warsh-text.json'),
  ('warsh-57-18', 'warsh', 57, 18, 'وَالذِينَ ءَامَنُواْ بِاللَّهِ وَرُسُلِهِۦٓ أُوْلَٰٓئِكَ هُمُ ࡲ۬لصِّدِّيقُونَ࣌ وَالشُّهَدَآءُ عِندَ رَبِّهِمْ࣌ لَهُمُۥٓ أَجْرُهُمْ وَنُورُهُمْ࣌ وَالذِينَ كَفَرُواْ وَكَذَّبُواْ بِـَٔايَٰتِنَآ أُوْلَٰٓئِكَ أَصْحَٰبُ ࡲ۬لْجَحِيمِ࣌', 'والذين ءامنوا بالله ورسله أولئك هم ࡲلصديقون࣌ والشهداء عند ربهم࣌ لهم أجرهم ونورهم࣌ والذين كفروا وكذبوا بايتنا أولئك أصحب ࡲلجحيم࣌', NULL, 540, 'local:warsh-text.json'),
  ('warsh-57-19', 'warsh', 57, 19, 'ࡴٜعْلَمُوٓاْ أَنَّمَا ࡰ۬لْحَيَوٰةُ ࡲ۬لدُّنْيٜا لَعِبࣱ وَلَهْوࣱ وَزِينَةࣱ وَتَفَاخُرُۢ بَيْنَكُمْ وَتَكَاثُرࣱ فِے ࡴ۬لَامْوَٰلِ وَالَاوْلَٰدِ كَمَثَلِ غَيْثٍ ࡰعْجَبَ ࡰ۬لْكُفَّارَ نَبَاتُهُۥ ثُمَّ يَهِيجُ فَتَرٜيٰهُ مُصْفَرّاࣰ ثُمَّ يَكُونُ حُطَٰماࣰ࣌ وَفِے ࡴ۬لَاخِرَةِ عَذَابࣱ شَدِيدࣱ وَمَغْفِرَةࣱ مِّنَ ࡰ۬للَّهِ وَرِضْوَٰنࣱ࣌ وَمَا ࡰ۬لْحَيَوٰةُ ࡲ۬لدُّنْيٜآ إِلَّا مَتَٰعُ ࡲ۬لْغُرُورِ࣌', 'ࡴعلموا أنما ࡰلحيوة ࡲلدنيا لعب ولهو وزينة وتفاخر بينكم وتكاثر فے ࡴلامول والاولد كمثل غيث ࡰعجب ࡰلكفار نباته ثم يهيج فتريه مصفرا ثم يكون حطما࣌ وفے ࡴلاخرة عذاب شديد ومغفرة من ࡰلله ورضون࣌ وما ࡰلحيوة ࡲلدنيا إلا متع ࡲلغرور࣌', NULL, 540, 'local:warsh-text.json'),
  ('warsh-57-20', 'warsh', 57, 20, 'سَابِقُوٓاْ إِلَىٰ مَغْفِرَةࣲ مِّن رَّبِّكُمْ وَجَنَّةٍ عَرْضُهَا كَعَرْضِ ࡴ۬لسَّمَآءِ وَالَارْضِ أُعِدَّتْ لِلذِينَ ءَامَنُواْ بِاللَّهِ وَرُسُلِهِۦ࣌ ذَٰلِكَ فَضْلُ ࡲ۬للَّهِ يُوتِيهِ مَنْ يَّشَآءُ࣌ وَاللَّهُ ذُو ࡲ۬لْفَضْلِ ࡴ۬لْعَظِيمِ࣌', 'سابقوا إلى مغفرة من ربكم وجنة عرضها كعرض ࡴلسماء والارض أعدت للذين ءامنوا بالله ورسله࣌ ذلك فضل ࡲلله يوتيه من يشاء࣌ والله ذو ࡲلفضل ࡴلعظيم࣌', NULL, 540, 'local:warsh-text.json'),
  ('warsh-57-21', 'warsh', 57, 21, '۞ مَآ أَصَابَ مِن مُّصِيبَةࣲ فِے ࡴ۬لَارْضِ وَلَا فِےٓ أَنفُسِكُمُۥٓ إِلَّا فِے كِتَٰبࣲ مِّن قَبْلِ أَن نَّبْرَأَهَآ࣌ إِنَّ ذَٰلِكَ عَلَى ࡰ۬للَّهِ يَسِيرࣱ', 'ما أصاب من مصيبة فے ࡴلارض ولا فے أنفسكم إلا فے كتب من قبل أن نبرأها࣌ إن ذلك على ࡰلله يسير', NULL, 540, 'local:warsh-text.json'),
  ('warsh-57-22', 'warsh', 57, 22, 'لِّكَيْلَا تَاسَوْاْ عَلَىٰ مَا فَاتَكُمْ وَلَا تَفْرَحُواْ بِمَآ ءَاتٜيٰكُمْ࣌ وَاللَّهُ لَا يُحِبُّ كُلَّ مُخْتَالࣲ فَخُورٍ࣌', 'لكيلا تاسوا على ما فاتكم ولا تفرحوا بما ءاتيكم࣌ والله لا يحب كل مختال فخور࣌', NULL, 540, 'local:warsh-text.json'),
  ('warsh-57-23', 'warsh', 57, 23, 'ࡴ۬لذِينَ يَبْخَلُونَ وَيَامُرُونَ ࡰ۬لنَّاسَ بِالْبُخْلِ࣌ وَمَنْ يَّتَوَلَّ فَإِنَّ ࡰ۬للَّهَ ࡰ۬لْغَنِيُّ ࡲ۬لْحَمِيدُ࣌', 'ࡴلذين يبخلون ويامرون ࡰلناس بالبخل࣌ ومن يتول فإن ࡰلله ࡰلغني ࡲلحميد࣌', NULL, 540, 'local:warsh-text.json'),
  ('warsh-57-24', 'warsh', 57, 24, 'لَقَدَ ࡰرْسَلْنَا رُسُلَنَا بِالْبَيِّنَٰتِ وَأَنزَلْنَا مَعَهُمُ ࡲ۬لْكِتَٰبَ وَالْمِيزَانَ لِيَقُومَ ࡰ۬لنَّاسُ بِالْقِسْطِ࣌ وَأَنزَلْنَا ࡰ۬لْحَدِيدَ فِيهِ بَأْسࣱ شَدِيدࣱ وَمَنَٰفِعُ لِلنَّاسِ࣌ وَلِيَعْلَمَ ࡰ۬للَّهُ مَنْ يَّنصُرُهُۥ وَرُسُلَهُۥ بِالْغَيْبِ࣌ إِنَّ ࡰ۬للَّهَ قَوِيٌّ عَزِيزࣱ࣌', 'لقد ࡰرسلنا رسلنا بالبينت وأنزلنا معهم ࡲلكتب والميزان ليقوم ࡰلناس بالقسط࣌ وأنزلنا ࡰلحديد فيه بأس شديد ومنفع للناس࣌ وليعلم ࡰلله من ينصره ورسله بالغيب࣌ إن ࡰلله قوي عزيز࣌', NULL, 541, 'local:warsh-text.json'),
  ('warsh-57-25', 'warsh', 57, 25, 'وَلَقَدَ ࡰرْسَلْنَا نُوحاࣰ وَإِبْرَٰهِيمَ وَجَعَلْنَا فِے ذُرِّيَّتِهِمَا ࡰ۬لنُّبُوٓءَةَ وَالْكِتَٰبَ࣌ فَمِنْهُم مُّهْتَدࣲ࣌ وَكَثِيرࣱ مِّنْهُمْ فَٰسِقُونَ࣌', 'ولقد ࡰرسلنا نوحا وإبرهيم وجعلنا فے ذريتهما ࡰلنبوءة والكتب࣌ فمنهم مهتد࣌ وكثير منهم فسقون࣌', NULL, 541, 'local:warsh-text.json'),
  ('warsh-57-26', 'warsh', 57, 26, 'ثُمَّ قَفَّيْنَا عَلَىٰٓ ءَاثٜـٰرِهِم بِرُسُلِنَا وَقَفَّيْنَا بِعِيسَى ࡰٜبْنِ مَرْيَمَ وَءَاتَيْنَٰهُ ࡲ۬لِانجِيلَ࣌ وَجَعَلْنَا فِے قُلُوبِ ࡴ۬لذِينَ ࡰٜتَّبَعُوهُ رَأْفَةࣰ وَرَحْمَةࣰ وَرَهْبَانِيَّةً ࡴٜبْتَدَعُوهَا مَا كَتَبْنَٰهَا عَلَيْهِمُۥٓ إِلَّا ࡰٜبْتِغَآءَ رِضْوَٰنِ ࡴ۬للَّهِ࣌ فَمَا رَعَوْهَا حَقَّ رِعَايَتِهَا࣌ فَـَٔاتَيْنَا ࡰ۬لذِينَ ءَامَنُواْ مِنْهُمُۥٓ أَجْرَهُمْ࣌ وَكَثِيرࣱ مِّنْهُمْ فَٰسِقُونَ࣌', 'ثم قفينا على ءاثرهم برسلنا وقفينا بعيسى ࡰبن مريم وءاتينه ࡲلانجيل࣌ وجعلنا فے قلوب ࡴلذين ࡰتبعوه رأفة ورحمة ورهبانية ࡴبتدعوها ما كتبنها عليهم إلا ࡰبتغاء رضون ࡴلله࣌ فما رعوها حق رعايتها࣌ فاتينا ࡰلذين ءامنوا منهم أجرهم࣌ وكثير منهم فسقون࣌', NULL, 541, 'local:warsh-text.json'),
  ('warsh-57-27', 'warsh', 57, 27, 'يَٰٓأَيُّهَا ࡰ۬لذِينَ ءَامَنُواْ ࡲٜتَّقُواْ ࡲ۬للَّهَ وَءَامِنُواْ بِرَسُولِهِۦ يُوتِكُمْ كِفْلَيْنِ مِن رَّحْمَتِهِۦ وَيَجْعَل لَّكُمْ نُوراࣰ تَمْشُونَ بِهِۦ وَيَغْفِرْ لَكُمْ࣌ وَاللَّهُ غَفُورࣱ رَّحِيمࣱ', 'يأيها ࡰلذين ءامنوا ࡲتقوا ࡲلله وءامنوا برسوله يوتكم كفلين من رحمته ويجعل لكم نورا تمشون به ويغفر لكم࣌ والله غفور رحيم', NULL, 541, 'local:warsh-text.json'),
  ('warsh-57-28', 'warsh', 57, 28, 'لِّيَ۬لَّا يَعْلَمَ أَهْلُ ࡲ۬لْكِتَٰبِ أَلَّا يَقْدِرُونَ عَلَىٰ شَےْءࣲ مِّن فَضْلِ ࡴ۬للَّهِ وَأَنَّ ࡰ۬لْفَضْلَ بِيَدِ ࡴ۬للَّهِ يُوتِيهِ مَنْ يَّشَآءُ࣌ وَاللَّهُ ذُو ࡲ۬لْفَضْلِ ࡴ۬لْعَظِيمِ࣌', 'ليلا يعلم أهل ࡲلكتب ألا يقدرون على شےء من فضل ࡴلله وأن ࡰلفضل بيد ࡴلله يوتيه من يشاء࣌ والله ذو ࡲلفضل ࡴلعظيم࣌', NULL, 541, 'local:warsh-text.json'),
  ('warsh-58-1', 'warsh', 58, 1, 'قَدْ سَمِعَ ࡰ۬للَّهُ قَوْلَ ࡰ۬لتِے تُجَٰدِلُكَ فِے زَوْجِهَا وَتَشْتَكِےٓ إِلَى ࡰ۬للَّهِ وَاللَّهُ يَسْمَعُ تَحَاوُرَكُمَآ࣌ إِنَّ ࡰ۬للَّهَ سَمِيعُۢ بَصِيرٌ࣌', 'قد سمع ࡰلله قول ࡰلتے تجدلك فے زوجها وتشتكے إلى ࡰلله والله يسمع تحاوركما࣌ إن ࡰلله سميع بصير࣌', NULL, 542, 'local:warsh-text.json'),
  ('warsh-58-2', 'warsh', 58, 2, 'ࡴ۬لذِينَ يَظَّهَّرُونَ مِنكُم مِّن نِّسَآئِهِم مَّا هُنَّ أُمَّهَٰتِهِمُۥٓ࣌ إِنُ ࡳمَّهَٰتُهُمُۥٓ إِلَّا ࡰ۬لٜےْ وَلَدْنَهُمْ࣌ وَإِنَّهُمْ لَيَقُولُونَ مُنكَراࣰ مِّنَ ࡰ۬لْقَوْلِ وَزُوراࣰ࣌ وَإِنَّ ࡰ۬للَّهَ لَعَفُوٌّ غَفُورࣱ࣌', 'ࡴلذين يظهرون منكم من نسائهم ما هن أمهتهم࣌ إن ࡳمهتهم إلا ࡰلے ولدنهم࣌ وإنهم ليقولون منكرا من ࡰلقول وزورا࣌ وإن ࡰلله لعفو غفور࣌', NULL, 542, 'local:warsh-text.json'),
  ('warsh-58-3', 'warsh', 58, 3, 'وَالذِينَ يَظَّهَّرُونَ مِن نِّسَآئِهِمْ ثُمَّ يَعُودُونَ لِمَا قَالُواْ فَتَحْرِيرُ رَقَبَةࣲ مِّن قَبْلِ أَنْ يَّتَمَآسَّا࣌ ذَٰلِكُمْ تُوعَظُونَ بِهِۦ࣌ وَاللَّهُ بِمَا تَعْمَلُونَ خَبِيرࣱ࣌', 'والذين يظهرون من نسائهم ثم يعودون لما قالوا فتحرير رقبة من قبل أن يتماسا࣌ ذلكم توعظون به࣌ والله بما تعملون خبير࣌', NULL, 542, 'local:warsh-text.json'),
  ('warsh-58-4', 'warsh', 58, 4, 'فَمَن لَّمْ يَجِدْ فَصِيَامُ شَهْرَيْنِ مُتَتَابِعَيْنِ مِن قَبْلِ أَنْ يَّتَمَآسَّا࣌ فَمَن لَّمْ يَسْتَطِعْ فَإِطْعَامُ سِتِّينَ مِسْكِيناࣰ࣌ ذَٰلِكَ لِتُومِنُواْ بِاللَّهِ وَرَسُولِهِۦ࣌ وَتِلْكَ حُدُودُ ࡲ۬للَّهِ࣌ وَلِلْكٜـٰفِرِينَ عَذَابٌ ࡰلِيمٌ࣌', 'فمن لم يجد فصيام شهرين متتابعين من قبل أن يتماسا࣌ فمن لم يستطع فإطعام ستين مسكينا࣌ ذلك لتومنوا بالله ورسوله࣌ وتلك حدود ࡲلله࣌ وللكفرين عذاب ࡰليم࣌', NULL, 542, 'local:warsh-text.json'),
  ('warsh-58-5', 'warsh', 58, 5, 'ࡴنَّ ࡰ۬لذِينَ يُحَآدُّونَ ࡰ۬للَّهَ وَرَسُولَهُۥ كُبِتُواْ كَمَا كُبِتَ ࡰ۬لذِينَ مِن قَبْلِهِمْ࣌ وَقَدَ ࡰنزَلْنَآ ءَايَٰتِۢ بَيِّنَٰتࣲ࣌ وَلِلْكٜـٰفِرِينَ عَذَابࣱ مُّهِينࣱ࣌', 'ࡴن ࡰلذين يحادون ࡰلله ورسوله كبتوا كما كبت ࡰلذين من قبلهم࣌ وقد ࡰنزلنا ءايت بينت࣌ وللكفرين عذاب مهين࣌', NULL, 542, 'local:warsh-text.json'),
  ('warsh-58-6', 'warsh', 58, 6, 'يَوْمَ يَبْعَثُهُمُ ࡲ۬للَّهُ جَمِيعاࣰ فَيُنَبِّئُهُم بِمَا عَمِلُوٓاْ࣌ أَحْصٜيٰهُ ࡲ۬للَّهُ وَنَسُوهُ࣌ وَاللَّهُ عَلَىٰ كُلِّ شَےْءࣲ شَهِيدٌ࣌', 'يوم يبعثهم ࡲلله جميعا فينبئهم بما عملوا࣌ أحصيه ࡲلله ونسوه࣌ والله على كل شےء شهيد࣌', NULL, 542, 'local:warsh-text.json'),
  ('warsh-58-7', 'warsh', 58, 7, 'ࡰلَمْ تَرَ أَنَّ ࡰ۬للَّهَ يَعْلَمُ مَا فِے ࡴ۬لسَّمَٰوَٰتِ وَمَا فِے ࡴ۬لَارْضِ࣌ مَا يَكُونُ مِن نَّجْوٜىٰ ثَلَٰثَةٍ ࡴلَّا هُوَ رَابِعُهُمْ وَلَا خَمْسَةٍ ࡴلَّا هُوَ سَادِسُهُمْ وَلَآ أَدْنٜىٰ مِن ذَٰلِكَ وَلَآ أَكْثَرَ إِلَّا هُوَ مَعَهُمُۥٓ أَيْنَ مَا كَانُواْ࣌ ثُمَّ يُنَبِّئُهُم بِمَا عَمِلُواْ يَوْمَ ࡰ۬لْقِيَٰمَةِ࣌ إِنَّ ࡰ۬للَّهَ بِكُلِّ شَےْءٍ عَلِيمٌ࣌', 'ࡰلم تر أن ࡰلله يعلم ما فے ࡴلسموت وما فے ࡴلارض࣌ ما يكون من نجوى ثلثة ࡴلا هو رابعهم ولا خمسة ࡴلا هو سادسهم ولا أدنى من ذلك ولا أكثر إلا هو معهم أين ما كانوا࣌ ثم ينبئهم بما عملوا يوم ࡰلقيمة࣌ إن ࡰلله بكل شےء عليم࣌', NULL, 543, 'local:warsh-text.json'),
  ('warsh-58-8', 'warsh', 58, 8, '۞ ࡰلَمْ تَرَ إِلَى ࡰ۬لذِينَ نُهُواْ عَنِ ࡴ۬لنَّجْوٜىٰ ثُمَّ يَعُودُونَ لِمَا نُهُواْ عَنْهُ وَيَتَنَٰجَوْنَ بِالِاثْمِ وَالْعُدْوَٰنِ وَمَعْصِيَتِ ࡴ۬لرَّسُولِ࣌ وَإِذَا جَآءُوكَ حَيَّوْكَ بِمَا لَمْ يُحَيِّكَ بِهِ ࡴ۬للَّهُ وَيَقُولُونَ فِےٓ أَنفُسِهِمْ لَوْلَا يُعَذِّبُنَا ࡰ۬للَّهُ بِمَا نَقُولُ࣌ حَسْبُهُمْ جَهَنَّمُ࣌ يَصْلَوْنَهَا࣌ فَبِيسَ ࡰ۬لْمَصِيرُ࣌', 'ࡰلم تر إلى ࡰلذين نهوا عن ࡴلنجوى ثم يعودون لما نهوا عنه ويتنجون بالاثم والعدون ومعصيت ࡴلرسول࣌ وإذا جاءوك حيوك بما لم يحيك به ࡴلله ويقولون فے أنفسهم لولا يعذبنا ࡰلله بما نقول࣌ حسبهم جهنم࣌ يصلونها࣌ فبيس ࡰلمصير࣌', NULL, 543, 'local:warsh-text.json'),
  ('warsh-58-9', 'warsh', 58, 9, 'يَٰٓأَيُّهَا ࡰ۬لذِينَ ءَامَنُوٓاْ إِذَا تَنَٰجَيْتُمْ فَلَا تَتَنَٰجَوْاْ بِالِاثْمِ وَالْعُدْوَٰنِ وَمَعْصِيَتِ ࡴ۬لرَّسُولِ࣌ وَتَنَٰجَوْاْ بِالْبِرِّ وَالتَّقْوٜىٰ࣌ وَاتَّقُواْ ࡲ۬للَّهَ ࡰ۬لذِےٓ إِلَيْهِ تُحْشَرُونَ࣌', 'يأيها ࡰلذين ءامنوا إذا تنجيتم فلا تتنجوا بالاثم والعدون ومعصيت ࡴلرسول࣌ وتنجوا بالبر والتقوى࣌ واتقوا ࡲلله ࡰلذے إليه تحشرون࣌', NULL, 543, 'local:warsh-text.json'),
  ('warsh-58-10', 'warsh', 58, 10, 'إِنَّمَا ࡰ۬لنَّجْوٜىٰ مِنَ ࡰ۬لشَّيْطَٰنِ لِيُحْزِنَ ࡰ۬لذِينَ ءَامَنُواْ وَلَيْسَ بِضَآرِّهِمْ شَيْـٔاً ࡴلَّا بِإِذْنِ ࡴ۬للَّهِ࣌ وَعَلَى ࡰ۬للَّهِ فَلْيَتَوَكَّلِ ࡴ۬لْمُومِنُونَ࣌', 'إنما ࡰلنجوى من ࡰلشيطن ليحزن ࡰلذين ءامنوا وليس بضارهم شيا ࡴلا بإذن ࡴلله࣌ وعلى ࡰلله فليتوكل ࡴلمومنون࣌', NULL, 543, 'local:warsh-text.json'),
  ('warsh-58-11', 'warsh', 58, 11, 'يَٰٓأَيُّهَا ࡰ۬لذِينَ ءَامَنُوٓاْ إِذَا قِيلَ لَكُمْ تَفَسَّحُواْ فِے ࡴ۬لْمَجْلِسِ فَافْسَحُواْ يَفْسَحِ ࡴ۬للَّهُ لَكُمْ࣌ وَإِذَا قِيلَ ࡸَنشُزُواْ فَانشُزُواْ يَرْفَعِ ࡴ۬للَّهُ ࡲ۬لذِينَ ءَامَنُواْ مِنكُمْ وَالذِينَ أُوتُواْ ࡲ۬لْعِلْمَ دَرَجَٰتࣲ࣌ وَاللَّهُ بِمَا تَعْمَلُونَ خَبِيرࣱ࣌', 'يأيها ࡰلذين ءامنوا إذا قيل لكم تفسحوا فے ࡴلمجلس فافسحوا يفسح ࡴلله لكم࣌ وإذا قيل ࡸنشزوا فانشزوا يرفع ࡴلله ࡲلذين ءامنوا منكم والذين أوتوا ࡲلعلم درجت࣌ والله بما تعملون خبير࣌', NULL, 543, 'local:warsh-text.json'),
  ('warsh-58-12', 'warsh', 58, 12, 'يَٰٓأَيُّهَا ࡰ۬لذِينَ ءَامَنُوٓاْ إِذَا نَٰجَيْتُمُ ࡲ۬لرَّسُولَ فَقَدِّمُواْ بَيْنَ يَدَےْ نَجْوٜيٰكُمْ صَدَقَةࣰ࣌ ذَٰلِكَ خَيْرࣱ لَّكُمْ وَأَطْهَرُ࣌ فَإِن لَّمْ تَجِدُواْ فَإِنَّ ࡰ۬للَّهَ غَفُورࣱ رَّحِيمٌ࣌', 'يأيها ࡰلذين ءامنوا إذا نجيتم ࡲلرسول فقدموا بين يدے نجويكم صدقة࣌ ذلك خير لكم وأطهر࣌ فإن لم تجدوا فإن ࡰلله غفور رحيم࣌', NULL, 544, 'local:warsh-text.json'),
  ('warsh-58-13', 'warsh', 58, 13, 'آٓشْفَقْتُمُۥٓ أَن تُقَدِّمُواْ بَيْنَ يَدَےْ نَجْوٜيٰكُمْ صَدَقَٰتࣲ࣌ فَإِذْ لَمْ تَفْعَلُواْ وَتَابَ ࡰ۬للَّهُ عَلَيْكُمْ فَأَقِيمُواْ ࡲ۬لصَّلَوٰةَ وَءَاتُواْ ࡲ۬لزَّكَوٰةَ࣌ وَأَطِيعُواْ ࡲ۬للَّهَ وَرَسُولَهُۥ࣌ وَاللَّهُ خَبِيرُۢ بِمَا تَعْمَلُونَ࣌', 'آشفقتم أن تقدموا بين يدے نجويكم صدقت࣌ فإذ لم تفعلوا وتاب ࡰلله عليكم فأقيموا ࡲلصلوة وءاتوا ࡲلزكوة࣌ وأطيعوا ࡲلله ورسوله࣌ والله خبير بما تعملون࣌', NULL, 544, 'local:warsh-text.json'),
  ('warsh-58-14', 'warsh', 58, 14, '۞ أَلَمْ تَرَ إِلَى ࡰ۬لذِينَ تَوَلَّوْاْ قَوْماً غَضِبَ ࡰ۬للَّهُ عَلَيْهِم مَّا هُم مِّنكُمْ وَلَا مِنْهُمْ وَيَحْلِفُونَ عَلَى ࡰ۬لْكَذِبِ وَهُمْ يَعْلَمُونَ࣌', 'ألم تر إلى ࡰلذين تولوا قوما غضب ࡰلله عليهم ما هم منكم ولا منهم ويحلفون على ࡰلكذب وهم يعلمون࣌', NULL, 544, 'local:warsh-text.json'),
  ('warsh-58-15', 'warsh', 58, 15, 'أَعَدَّ ࡰ۬للَّهُ لَهُمْ عَذَاباࣰ شَدِيداً࣌ ࡴنَّهُمْ سَآءَ مَا كَانُواْ يَعْمَلُونَ࣌', 'أعد ࡰلله لهم عذابا شديدا࣌ ࡴنهم ساء ما كانوا يعملون࣌', NULL, 544, 'local:warsh-text.json'),
  ('warsh-58-16', 'warsh', 58, 16, 'ࡰٜتَّخَذُوٓاْ أَيْمَٰنَهُمْ جُنَّةࣰ فَصَدُّواْ عَن سَبِيلِ ࡴ۬للَّهِ فَلَهُمْ عَذَابࣱ مُّهِينࣱ࣌', 'ࡰتخذوا أيمنهم جنة فصدوا عن سبيل ࡴلله فلهم عذاب مهين࣌', NULL, 544, 'local:warsh-text.json'),
  ('warsh-58-17', 'warsh', 58, 17, 'لَّن تُغْنِيَ عَنْهُمُۥٓ أَمْوَٰلُهُمْ وَلَآ أَوْلَٰدُهُم مِّنَ ࡰ۬للَّهِ شَيْـٔاً࣌ ࡳوْلَٰٓئِكَ أَصْحَٰبُ ࡲ۬لنّٜارِ هُمْ فِيهَا خَٰلِدُونَ࣌', 'لن تغني عنهم أمولهم ولا أولدهم من ࡰلله شيا࣌ ࡳولئك أصحب ࡲلنار هم فيها خلدون࣌', NULL, 544, 'local:warsh-text.json'),
  ('warsh-58-18', 'warsh', 58, 18, 'يَوْمَ يَبْعَثُهُمُ ࡲ۬للَّهُ جَمِيعاࣰ فَيَحْلِفُونَ لَهُۥ كَمَا يَحْلِفُونَ لَكُمْ وَيَحْسِبُونَ أَنَّهُمْ عَلَىٰ شَےْءٍ࣌ ࡰلَآ إِنَّهُمْ هُمُ ࡲ۬لْكَٰذِبُونَ࣌', 'يوم يبعثهم ࡲلله جميعا فيحلفون له كما يحلفون لكم ويحسبون أنهم على شےء࣌ ࡰلا إنهم هم ࡲلكذبون࣌', NULL, 544, 'local:warsh-text.json'),
  ('warsh-58-19', 'warsh', 58, 19, 'ࡰٜسْتَحْوَذَ عَلَيْهِمُ ࡲ۬لشَّيْطَٰنُ فَأَنسٜيٰهُمْ ذِكْرَ ࡰ۬للَّهِ࣌ أُوْلَٰٓئِكَ حِزْبُ ࡲ۬لشَّيْطَٰنِ࣌ أَلَآ إِنَّ حِزْبَ ࡰ۬لشَّيْطَٰنِ هُمُ ࡲ۬لْخَٰسِرُونَ࣌', 'ࡰستحوذ عليهم ࡲلشيطن فأنسيهم ذكر ࡰلله࣌ أولئك حزب ࡲلشيطن࣌ ألا إن حزب ࡰلشيطن هم ࡲلخسرون࣌', NULL, 544, 'local:warsh-text.json'),
  ('warsh-58-20', 'warsh', 58, 20, 'إِنَّ ࡰ۬لذِينَ يُحَآدُّونَ ࡰ۬للَّهَ وَرَسُولَهُۥٓ أُوْلَٰٓئِكَ فِے ࡴ۬لَاذَلِّينَ࣌ كَتَبَ ࡰ۬للَّهُ لَأَغْلِبَنَّ أَنَا وَرُسُلِيَ࣌ إِنَّ ࡰ۬للَّهَ قَوِيٌّ عَزِيزࣱ࣌', 'إن ࡰلذين يحادون ࡰلله ورسوله أولئك فے ࡴلاذلين࣌ كتب ࡰلله لأغلبن أنا ورسلي࣌ إن ࡰلله قوي عزيز࣌', NULL, 544, 'local:warsh-text.json'),
  ('warsh-58-21', 'warsh', 58, 21, 'لَّا تَجِدُ قَوْماࣰ يُومِنُونَ بِاللَّهِ وَالْيَوْمِ ࡴ۬لَاخِرِ يُوَآدُّونَ مَنْ حَآدَّ ࡰ۬للَّهَ وَرَسُولَهُۥ وَلَوْ كَانُوٓاْ ءَابَآءَهُمُۥٓ أَوَ ࡰبْنَآءَهُمُۥٓ أَوِ ࡴخْوَٰنَهُمُۥٓ أَوْ عَشِيرَتَهُمُۥٓ࣌ أُوْلَٰٓئِكَ كَتَبَ فِے قُلُوبِهِمُ ࡲ۬لِايمَٰنَ وَأَيَّدَهُم بِرُوحࣲ مِّنْهُ وَيُدْخِلُهُمْ جَنَّٰتࣲ تَجْرِے مِن تَحْتِهَا ࡰ۬لَانْهَٰرُ خَٰلِدِينَ فِيهَا࣌ رَضِيَ ࡰ۬للَّهُ عَنْهُمْ وَرَضُواْ عَنْهُ࣌ أُوْلَٰٓئِكَ حِزْبُ ࡲ۬للَّهِ࣌ أَلَآ إِنَّ حِزْبَ ࡰ۬للَّهِ هُمُ ࡲ۬لْمُفْلِحُونَ࣌', 'لا تجد قوما يومنون بالله واليوم ࡴلاخر يوادون من حاد ࡰلله ورسوله ولو كانوا ءاباءهم أو ࡰبناءهم أو ࡴخونهم أو عشيرتهم࣌ أولئك كتب فے قلوبهم ࡲلايمن وأيدهم بروح منه ويدخلهم جنت تجرے من تحتها ࡰلانهر خلدين فيها࣌ رضي ࡰلله عنهم ورضوا عنه࣌ أولئك حزب ࡲلله࣌ ألا إن حزب ࡰلله هم ࡲلمفلحون࣌', NULL, 545, 'local:warsh-text.json'),
  ('warsh-59-1', 'warsh', 59, 1, 'سَبَّحَ لِلهِ مَا فِے ࡴ۬لسَّمَٰوَٰتِ وَمَا فِے ࡴ۬لَارْضِ࣌ وَهُوَ ࡰ۬لْعَزِيزُ ࡲ۬لْحَكِيمُ࣌', 'سبح لله ما فے ࡴلسموت وما فے ࡴلارض࣌ وهو ࡰلعزيز ࡲلحكيم࣌', NULL, 545, 'local:warsh-text.json'),
  ('warsh-59-2', 'warsh', 59, 2, 'هُوَ ࡰ۬لذِےٓ أَخْرَجَ ࡰ۬لذِينَ كَفَرُواْ مِنَ ࡰهْلِ ࡴ۬لْكِتَٰبِ مِن دِيٜـٰرِهِمْ لِأَوَّلِ ࡴ۬لْحَشْرِ࣌ مَا ظَنَنتُمُۥٓ أَنْ يَّخْرُجُواْ࣌ وَظَنُّوٓاْ أَنَّهُم مَّانِعَتُهُمْ حُصُونُهُم مِّنَ ࡰ۬للَّهِ࣌ فَأَتٜيٰهُمُ ࡲ۬للَّهُ مِنْ حَيْثُ لَمْ يَحْتَسِبُواْ࣌ ۞ وَقَذَفَ فِے قُلُوبِهِمُ ࡲ۬لرُّعْبَ࣌ يُخْرِبُونَ بُيُوتَهُم بِأَيْدِيهِمْ وَأَيْدِے ࡴ۬لْمُومِنِينَ࣌ فَاعْتَبِرُواْ يَٰٓأُوْلِے ࡴ۬لَابْصٜـٰرِ࣌', 'هو ࡰلذے أخرج ࡰلذين كفروا من ࡰهل ࡴلكتب من ديرهم لأول ࡴلحشر࣌ ما ظننتم أن يخرجوا࣌ وظنوا أنهم مانعتهم حصونهم من ࡰلله࣌ فأتيهم ࡲلله من حيث لم يحتسبوا࣌  وقذف فے قلوبهم ࡲلرعب࣌ يخربون بيوتهم بأيديهم وأيدے ࡴلمومنين࣌ فاعتبروا يأولے ࡴلابصر࣌', NULL, 545, 'local:warsh-text.json'),
  ('warsh-59-3', 'warsh', 59, 3, 'وَلَوْلَآ أَن كَتَبَ ࡰ۬للَّهُ عَلَيْهِمُ ࡲ۬لْجَلَآءَ لَعَذَّبَهُمْ فِے ࡴ۬لدُّنْيٜا࣌ وَلَهُمْ فِے ࡴ۬لَاخِرَةِ عَذَابُ ࡲ۬لنّٜارِ࣌', 'ولولا أن كتب ࡰلله عليهم ࡲلجلاء لعذبهم فے ࡴلدنيا࣌ ولهم فے ࡴلاخرة عذاب ࡲلنار࣌', NULL, 545, 'local:warsh-text.json'),
  ('warsh-59-4', 'warsh', 59, 4, 'ذَٰلِكَ بِأَنَّهُمْ شَآقُّواْ ࡲ۬للَّهَ وَرَسُولَهُۥ࣌ وَمَنْ يُّشَآقِّ ࡴ۬للَّهَ فَإِنَّ ࡰ۬للَّهَ شَدِيدُ ࡲ۬لْعِقَابِ࣌', 'ذلك بأنهم شاقوا ࡲلله ورسوله࣌ ومن يشاق ࡴلله فإن ࡰلله شديد ࡲلعقاب࣌', NULL, 546, 'local:warsh-text.json'),
  ('warsh-59-5', 'warsh', 59, 5, 'مَا قَطَعْتُم مِّن لِّينَةٍ ࡰوْ تَرَكْتُمُوهَا قَآئِمَةً عَلَىٰٓ أُصُولِهَا فَبِإِذْنِ ࡴ۬للَّهِ وَلِيُخْزِيَ ࡰ۬لْفَٰسِقِينَ࣌', 'ما قطعتم من لينة ࡰو تركتموها قائمة على أصولها فبإذن ࡴلله وليخزي ࡰلفسقين࣌', NULL, 546, 'local:warsh-text.json'),
  ('warsh-59-6', 'warsh', 59, 6, 'وَمَآ أَفَآءَ ࡰ۬للَّهُ عَلَىٰ رَسُولِهِۦ مِنْهُمْ فَمَآ أَوْجَفْتُمْ عَلَيْهِ مِنْ خَيْلࣲ وَلَا رِكَابࣲ࣌ وَلَٰكِنَّ ࡰ۬للَّهَ يُسَلِّطُ رُسُلَهُۥ عَلَىٰ مَنْ يَّشَآءُ࣌ وَاللَّهُ عَلَىٰ كُلِّ شَےْءࣲ قَدِيرࣱ࣌', 'وما أفاء ࡰلله على رسوله منهم فما أوجفتم عليه من خيل ولا ركاب࣌ ولكن ࡰلله يسلط رسله على من يشاء࣌ والله على كل شےء قدير࣌', NULL, 546, 'local:warsh-text.json'),
  ('warsh-59-7', 'warsh', 59, 7, 'مَّآ أَفَآءَ ࡰ۬للَّهُ عَلَىٰ رَسُولِهِۦ مِنَ ࡰهْلِ ࡴ۬لْقُرٜىٰ فَلِلهِ وَلِلرَّسُولِ وَلِذِے ࡴ۬لْقُرْبٜىٰ وَالْيَتَٰمٜىٰ وَالْمَسَٰكِينِ وَابْنِ ࡴ۬لسَّبِيلِ كَےْ لَا يَكُونَ دُولَةَۢ بَيْنَ ࡰ۬لَاغْنِيَآءِ مِنكُمْ࣌ وَمَآ ءَاتٜيٰكُمُ ࡲ۬لرَّسُولُ فَخُذُوهُ࣌ وَمَا نَهٜيٰكُمْ عَنْهُ فَانتَهُواْ࣌ وَاتَّقُواْ ࡲ۬للَّهَ࣌ إِنَّ ࡰ۬للَّهَ شَدِيدُ ࡲ۬لْعِقَابِ࣌', 'ما أفاء ࡰلله على رسوله من ࡰهل ࡴلقرى فلله وللرسول ولذے ࡴلقربى واليتمى والمسكين وابن ࡴلسبيل كے لا يكون دولة بين ࡰلاغنياء منكم࣌ وما ءاتيكم ࡲلرسول فخذوه࣌ وما نهيكم عنه فانتهوا࣌ واتقوا ࡲلله࣌ إن ࡰلله شديد ࡲلعقاب࣌', NULL, 546, 'local:warsh-text.json'),
  ('warsh-59-8', 'warsh', 59, 8, 'لِلْفُقَرَآءِ ࡴ۬لْمُهَٰجِرِينَ ࡰ۬لذِينَ أُخْرِجُواْ مِن دِيٜـٰرِهِمْ وَأَمْوَٰلِهِمْ يَبْتَغُونَ فَضْلاࣰ مِّنَ ࡰ۬للَّهِ وَرِضْوَٰناࣰ وَيَنصُرُونَ ࡰ۬للَّهَ وَرَسُولَهُۥٓ࣌ أُوْلَٰٓئِكَ هُمُ ࡲ۬لصَّٰدِقُونَ࣌', 'للفقراء ࡴلمهجرين ࡰلذين أخرجوا من ديرهم وأمولهم يبتغون فضلا من ࡰلله ورضونا وينصرون ࡰلله ورسوله࣌ أولئك هم ࡲلصدقون࣌', NULL, 546, 'local:warsh-text.json'),
  ('warsh-59-9', 'warsh', 59, 9, 'وَالذِينَ تَبَوَّءُو ࡲ۬لدَّارَ وَالِايمَٰنَ مِن قَبْلِهِمْ يُحِبُّونَ مَنْ هَاجَرَ إِلَيْهِمْ وَلَا يَجِدُونَ فِے صُدُورِهِمْ حَاجَةࣰ مِّمَّآ أُوتُواْ وَيُوثِرُونَ عَلَىٰٓ أَنفُسِهِمْ وَلَوْ كَانَ بِهِمْ خَصَاصَةࣱ࣌ وَمَنْ يُّوقَ شُحَّ نَفْسِهِۦ فَأُوْلَٰٓئِكَ هُمُ ࡲ۬لْمُفْلِحُونَ࣌', 'والذين تبوءو ࡲلدار والايمن من قبلهم يحبون من هاجر إليهم ولا يجدون فے صدورهم حاجة مما أوتوا ويوثرون على أنفسهم ولو كان بهم خصاصة࣌ ومن يوق شح نفسه فأولئك هم ࡲلمفلحون࣌', NULL, 546, 'local:warsh-text.json'),
  ('warsh-59-10', 'warsh', 59, 10, 'وَالذِينَ جَآءُو مِنۢ بَعْدِهِمْ يَقُولُونَ رَبَّنَا ࡰٜغْفِرْ لَنَا وَلِإِخْوَٰنِنَا ࡰ۬لذِينَ سَبَقُونَا بِالِايمَٰنِ وَلَا تَجْعَلْ فِے قُلُوبِنَا غِلّاࣰ لِّلذِينَ ءَامَنُواْ࣌ رَبَّنَآ إِنَّكَ رَءُوفࣱ رَّحِيمٌ࣌', 'والذين جاءو من بعدهم يقولون ربنا ࡰغفر لنا ولإخوننا ࡰلذين سبقونا بالايمن ولا تجعل فے قلوبنا غلا للذين ءامنوا࣌ ربنا إنك رءوف رحيم࣌', NULL, 547, 'local:warsh-text.json'),
  ('warsh-59-11', 'warsh', 59, 11, '۞ ࡰلَمْ تَرَ إِلَى ࡰ۬لذِينَ نَافَقُواْ يَقُولُونَ لِإِخْوَٰنِهِمُ ࡲ۬لذِينَ كَفَرُواْ مِنَ ࡰهْلِ ࡴ۬لْكِتَٰبِ لَئِنُ ࡳخْرِجْتُمْ لَنَخْرُجَنَّ مَعَكُمْ وَلَا نُطِيعُ فِيكُمُۥٓ أَحَداً ࡰبَداࣰ وَإِن قُوتِلْتُمْ لَنَنصُرَنَّكُمْ࣌ وَاللَّهُ يَشْهَدُ إِنَّهُمْ لَكَٰذِبُونَ࣌', 'ࡰلم تر إلى ࡰلذين نافقوا يقولون لإخونهم ࡲلذين كفروا من ࡰهل ࡴلكتب لئن ࡳخرجتم لنخرجن معكم ولا نطيع فيكم أحدا ࡰبدا وإن قوتلتم لننصرنكم࣌ والله يشهد إنهم لكذبون࣌', NULL, 547, 'local:warsh-text.json'),
  ('warsh-59-12', 'warsh', 59, 12, 'لَئِنُ ࡳخْرِجُواْ لَا يَخْرُجُونَ مَعَهُمْ࣌ وَلَئِن قُوتِلُواْ لَا يَنصُرُونَهُمْ࣌ وَلَئِن نَّصَرُوهُمْ لَيُوَلُّنَّ ࡰ۬لَادْبَٰرَ ثُمَّ لَا يُنصَرُونَ࣌', 'لئن ࡳخرجوا لا يخرجون معهم࣌ ولئن قوتلوا لا ينصرونهم࣌ ولئن نصروهم ليولن ࡰلادبر ثم لا ينصرون࣌', NULL, 547, 'local:warsh-text.json'),
  ('warsh-59-13', 'warsh', 59, 13, 'لَأَنتُمُۥٓ أَشَدُّ رَهْبَةࣰ فِے صُدُورِهِم مِّنَ ࡰ۬للَّهِ࣌ ذَٰلِكَ بِأَنَّهُمْ قَوْمࣱ لَّا يَفْقَهُونَ࣌', 'لأنتم أشد رهبة فے صدورهم من ࡰلله࣌ ذلك بأنهم قوم لا يفقهون࣌', NULL, 547, 'local:warsh-text.json'),
  ('warsh-59-14', 'warsh', 59, 14, 'لَا يُقَٰتِلُونَكُمْ جَمِيعاً ࡴلَّا فِے قُرىࣰ مُّحَصَّنَةٍ ࡰوْ مِنْ وَّرَآءِ جُدُرِۢ࣌ بَأْسُهُم بَيْنَهُمْ شَدِيدࣱ࣌ تَحْسِبُهُمْ جَمِيعاࣰ وَقُلُوبُهُمْ شَتّٜىٰ࣌ ذَٰلِكَ بِأَنَّهُمْ قَوْمࣱ لَّا يَعْقِلُونَ࣌', 'لا يقتلونكم جميعا ࡴلا فے قرى محصنة ࡰو من وراء جدر࣌ بأسهم بينهم شديد࣌ تحسبهم جميعا وقلوبهم شتى࣌ ذلك بأنهم قوم لا يعقلون࣌', NULL, 547, 'local:warsh-text.json'),
  ('warsh-59-15', 'warsh', 59, 15, 'كَمَثَلِ ࡴ۬لذِينَ مِن قَبْلِهِمْ قَرِيباࣰ࣌ ذَاقُواْ وَبَالَ أَمْرِهِمْ࣌ وَلَهُمْ عَذَابٌ ࡰلِيمࣱ࣌', 'كمثل ࡴلذين من قبلهم قريبا࣌ ذاقوا وبال أمرهم࣌ ولهم عذاب ࡰليم࣌', NULL, 547, 'local:warsh-text.json'),
  ('warsh-59-16', 'warsh', 59, 16, 'كَمَثَلِ ࡴ۬لشَّيْطَٰنِ إِذْ قَالَ لِلِانسَٰنِ ࡴ࢈كْفُرْ فَلَمَّا كَفَرَ قَالَ إِنِّے بَرِےٓءࣱ مِّنكَ إِنِّيَ أَخَافُ ࡲ۬للَّهَ رَبَّ ࡰ۬لْعَٰلَمِينَ࣌', 'كمثل ࡴلشيطن إذ قال للانسن ࡴ࢈كفر فلما كفر قال إنے برےء منك إني أخاف ࡲلله رب ࡰلعلمين࣌', NULL, 547, 'local:warsh-text.json'),
  ('warsh-59-17', 'warsh', 59, 17, 'فَكَانَ عَٰقِبَتَهُمَآ أَنَّهُمَا فِے ࡴ۬لنّٜارِ خَالِدَيْنِ فِيهَا࣌ وَذَٰلِكَ جَزَٰٓؤُاْ ࡲ۬لظَّٰلِمِينَ࣌', 'فكان عقبتهما أنهما فے ࡴلنار خالدين فيها࣌ وذلك جزؤا ࡲلظلمين࣌', NULL, 548, 'local:warsh-text.json'),
  ('warsh-59-18', 'warsh', 59, 18, 'يَٰٓأَيُّهَا ࡰ۬لذِينَ ءَامَنُواْ ࡲٜتَّقُواْ ࡲ۬للَّهَ وَلْتَنظُرْ نَفْسࣱ مَّا قَدَّمَتْ لِغَدࣲ࣌ وَاتَّقُواْ ࡲ۬للَّهَ࣌ إِنَّ ࡰ۬للَّهَ خَبِيرُۢ بِمَا تَعْمَلُونَ࣌', 'يأيها ࡰلذين ءامنوا ࡲتقوا ࡲلله ولتنظر نفس ما قدمت لغد࣌ واتقوا ࡲلله࣌ إن ࡰلله خبير بما تعملون࣌', NULL, 548, 'local:warsh-text.json'),
  ('warsh-59-19', 'warsh', 59, 19, 'وَلَا تَكُونُواْ كَالذِينَ نَسُواْ ࡲ۬للَّهَ فَأَنسٜيٰهُمُۥٓ أَنفُسَهُمُۥٓ࣌ أُوْلَٰٓئِكَ هُمُ ࡲ۬لْفَٰسِقُونَ࣌', 'ولا تكونوا كالذين نسوا ࡲلله فأنسيهم أنفسهم࣌ أولئك هم ࡲلفسقون࣌', NULL, 548, 'local:warsh-text.json'),
  ('warsh-59-20', 'warsh', 59, 20, 'لَا يَسْتَوِےٓ أَصْحَٰبُ ࡲ۬لنّٜارِ وَأَصْحَٰبُ ࡲ۬لْجَنَّةِ࣌ أَصْحَٰبُ ࡲ۬لْجَنَّةِ هُمُ ࡲ۬لْفَآئِزُونَ࣌', 'لا يستوے أصحب ࡲلنار وأصحب ࡲلجنة࣌ أصحب ࡲلجنة هم ࡲلفائزون࣌', NULL, 548, 'local:warsh-text.json'),
  ('warsh-59-21', 'warsh', 59, 21, 'لَوَ ࡰنزَلْنَا هَٰذَا ࡰ۬لْقُرْءَانَ عَلَىٰ جَبَلࣲ لَّرَأَيْتَهُۥ خَٰشِعاࣰ مُّتَصَدِّعاࣰ مِّنْ خَشْيَةِ ࡴ۬للَّهِ࣌ وَتِلْكَ ࡰ۬لَامْثَٰلُ نَضْرِبُهَا لِلنَّاسِ لَعَلَّهُمْ يَتَفَكَّرُونَ࣌', 'لو ࡰنزلنا هذا ࡰلقرءان على جبل لرأيته خشعا متصدعا من خشية ࡴلله࣌ وتلك ࡰلامثل نضربها للناس لعلهم يتفكرون࣌', NULL, 548, 'local:warsh-text.json'),
  ('warsh-59-22', 'warsh', 59, 22, 'هُوَ ࡰ۬للَّهُ ࡲ۬لذِے لَآ إِلَٰهَ إِلَّا هُوَ࣌ عَٰلِمُ ࡲ۬لْغَيْبِ وَالشَّهَٰدَةِ࣌ هُوَ ࡰ۬لرَّحْمَٰنُ ࡲ۬لرَّحِيمُ࣌', 'هو ࡰلله ࡲلذے لا إله إلا هو࣌ علم ࡲلغيب والشهدة࣌ هو ࡰلرحمن ࡲلرحيم࣌', NULL, 548, 'local:warsh-text.json'),
  ('warsh-59-23', 'warsh', 59, 23, 'هُوَ ࡰ۬للَّهُ ࡲ۬لذِے لَآ إِلَٰهَ إِلَّا هُوَ ࡰ۬لْمَلِكُ ࡲ۬لْقُدُّوسُ ࡲ۬لسَّلَٰمُ ࡲ۬لْمُومِنُ ࡲ۬لْمُهَيْمِنُ ࡲ۬لْعَزِيزُ ࡲ۬لْجَبَّارُ ࡲ۬لْمُتَكَبِّرُ࣌ سُبْحَٰنَ ࡰ۬للَّهِ عَمَّا يُشْرِكُونَ࣌', 'هو ࡰلله ࡲلذے لا إله إلا هو ࡰلملك ࡲلقدوس ࡲلسلم ࡲلمومن ࡲلمهيمن ࡲلعزيز ࡲلجبار ࡲلمتكبر࣌ سبحن ࡰلله عما يشركون࣌', NULL, 548, 'local:warsh-text.json'),
  ('warsh-59-24', 'warsh', 59, 24, 'هُوَ ࡰ۬للَّهُ ࡲ۬لْخَٰلِقُ ࡲ۬لْبَارِۓُ ࡲ۬لْمُصَوِّرُ࣌ لَهُ ࡲ۬لَاسْمَآءُ ࡲ۬لْحُسْنٜىٰ࣌ يُسَبِّحُ لَهُۥ مَا فِے ࡴ۬لسَّمَٰوَٰتِ وَالَارْضِ࣌ وَهُوَ ࡰ۬لْعَزِيزُ ࡲ۬لْحَكِيمُ࣌', 'هو ࡰلله ࡲلخلق ࡲلبارے ࡲلمصور࣌ له ࡲلاسماء ࡲلحسنى࣌ يسبح له ما فے ࡴلسموت والارض࣌ وهو ࡰلعزيز ࡲلحكيم࣌', NULL, 548, 'local:warsh-text.json'),
  ('warsh-60-1', 'warsh', 60, 1, 'يَٰٓأَيُّهَا ࡰ۬لذِينَ ءَامَنُواْ لَا تَتَّخِذُواْ عَدُوِّے وَعَدُوَّكُمُۥٓ أَوْلِيَآءَ࣌ تُلْقُونَ إِلَيْهِم بِالْمَوَدَّةِ وَقَدْ كَفَرُواْ بِمَا جَآءَكُم مِّنَ ࡰ۬لْحَقِّ࣌ يُخْرِجُونَ ࡰ۬لرَّسُولَ وَإِيَّاكُمُۥٓ أَن تُومِنُواْ بِاللَّهِ رَبِّكُمُۥٓ࣌ إِن كُنتُمْ خَرَجْتُمْ جِهَٰداࣰ فِے سَبِيلِے وَابْتِغَآءَ مَرْضَاتِے تُسِرُّونَ إِلَيْهِم بِالْمَوَدَّةِ وَأَنَآ أَعْلَمُ بِمَآ أَخْفَيْتُمْ وَمَآ أَعْلَنتُمْ࣌ وَمَنْ يَّفْعَلْهُ مِنكُمْ فَقَد ضَّلَّ سَوَآءَ ࡰ۬لسَّبِيلِ࣌', 'يأيها ࡰلذين ءامنوا لا تتخذوا عدوے وعدوكم أولياء࣌ تلقون إليهم بالمودة وقد كفروا بما جاءكم من ࡰلحق࣌ يخرجون ࡰلرسول وإياكم أن تومنوا بالله ربكم࣌ إن كنتم خرجتم جهدا فے سبيلے وابتغاء مرضاتے تسرون إليهم بالمودة وأنا أعلم بما أخفيتم وما أعلنتم࣌ ومن يفعله منكم فقد ضل سواء ࡰلسبيل࣌', NULL, 549, 'local:warsh-text.json'),
  ('warsh-60-2', 'warsh', 60, 2, 'إِنْ يَّثْقَفُوكُمْ يَكُونُواْ لَكُمُۥٓ أَعْدَآءࣰ وَيَبْسُطُوٓاْ إِلَيْكُمُۥٓ أَيْدِيَهُمْ وَأَلْسِنَتَهُم بِالسُّوٓءِ࣌ وَوَدُّواْ لَوْ تَكْفُرُونَ࣌', 'إن يثقفوكم يكونوا لكم أعداء ويبسطوا إليكم أيديهم وألسنتهم بالسوء࣌ وودوا لو تكفرون࣌', NULL, 549, 'local:warsh-text.json'),
  ('warsh-60-3', 'warsh', 60, 3, 'لَن تَنفَعَكُمُۥٓ أَرْحَامُكُمْ وَلَآ أَوْلَٰدُكُمْ࣌ يَوْمَ ࡰ۬لْقِيَٰمَةِ يُفْصَلُ بَيْنَكُمْ࣌ وَاللَّهُ بِمَا تَعْمَلُونَ بَصِيرࣱ࣌', 'لن تنفعكم أرحامكم ولا أولدكم࣌ يوم ࡰلقيمة يفصل بينكم࣌ والله بما تعملون بصير࣌', NULL, 549, 'local:warsh-text.json'),
  ('warsh-60-4', 'warsh', 60, 4, 'قَدْ كَانَتْ لَكُمُۥٓ إِسْوَةٌ حَسَنَةࣱ فِےٓ إِبْرَٰهِيمَ وَالذِينَ مَعَهُۥٓ إِذْ قَالُواْ لِقَوْمِهِمُۥٓ إِنَّا بُرَءَٰٓؤُاْ مِنكُمْ وَمِمَّا تَعْبُدُونَ مِن دُونِ ࡴ۬للَّهِ كَفَرْنَا بِكُمْ وَبَدَا بَيْنَنَا وَبَيْنَكُمُ ࡲ۬لْعَدَٰوَةُ وَالْبَغْضَآءُ ࡶَبَداً حَتَّىٰ تُومِنُواْ بِاللَّهِ وَحْدَهُۥٓ إِلَّا قَوْلَ إِبْرَٰهِيمَ لِأَبِيهِ لَأَسْتَغْفِرَنَّ لَكَ وَمَآ أَمْلِكُ لَكَ مِنَ ࡰ۬للَّهِ مِن شَےْءࣲ࣌ رَّبَّنَا عَلَيْكَ تَوَكَّلْنَا وَإِلَيْكَ أَنَبْنَا وَإِلَيْكَ ࡰ۬لْمَصِيرُ࣌', 'قد كانت لكم إسوة حسنة فے إبرهيم والذين معه إذ قالوا لقومهم إنا برءؤا منكم ومما تعبدون من دون ࡴلله كفرنا بكم وبدا بيننا وبينكم ࡲلعدوة والبغضاء ࡶبدا حتى تومنوا بالله وحده إلا قول إبرهيم لأبيه لأستغفرن لك وما أملك لك من ࡰلله من شےء࣌ ربنا عليك توكلنا وإليك أنبنا وإليك ࡰلمصير࣌', NULL, 549, 'local:warsh-text.json'),
  ('warsh-60-5', 'warsh', 60, 5, 'رَبَّنَا لَا تَجْعَلْنَا فِتْنَةࣰ لِّلذِينَ كَفَرُواْ࣌ وَاغْفِرْ لَنَا رَبَّنَآ࣌ إِنَّكَ أَنتَ ࡰ۬لْعَزِيزُ ࡲ۬لْحَكِيمُ࣌', 'ربنا لا تجعلنا فتنة للذين كفروا࣌ واغفر لنا ربنا࣌ إنك أنت ࡰلعزيز ࡲلحكيم࣌', NULL, 549, 'local:warsh-text.json'),
  ('warsh-60-6', 'warsh', 60, 6, 'لَقَدْ كَانَ لَكُمْ فِيهِمُۥٓ إِسْوَةٌ حَسَنَةࣱ لِّمَن كَانَ يَرْجُواْ ࡲ۬للَّهَ وَالْيَوْمَ ࡰ۬لَاخِرَ࣌ وَمَنْ يَّتَوَلَّ فَإِنَّ ࡰ۬للَّهَ هُوَ ࡰ۬لْغَنِيُّ ࡲ۬لْحَمِيدُ࣌', 'لقد كان لكم فيهم إسوة حسنة لمن كان يرجوا ࡲلله واليوم ࡰلاخر࣌ ومن يتول فإن ࡰلله هو ࡰلغني ࡲلحميد࣌', NULL, 550, 'local:warsh-text.json'),
  ('warsh-60-7', 'warsh', 60, 7, '۞ عَسَى ࡰ۬للَّهُ أَنْ يَّجْعَلَ بَيْنَكُمْ وَبَيْنَ ࡰ۬لذِينَ عَادَيْتُم مِّنْهُم مَّوَدَّةࣰ࣌ وَاللَّهُ قَدِيرࣱ࣌ وَاللَّهُ غَفُورࣱ رَّحِيمࣱ࣌', 'عسى ࡰلله أن يجعل بينكم وبين ࡰلذين عاديتم منهم مودة࣌ والله قدير࣌ والله غفور رحيم࣌', NULL, 550, 'local:warsh-text.json'),
  ('warsh-60-8', 'warsh', 60, 8, 'لَّا يَنْهٜيٰكُمُ ࡲ۬للَّهُ عَنِ ࡴ۬لذِينَ لَمْ يُقَٰتِلُوكُمْ فِے ࡴ۬لدِّينِ وَلَمْ يُخْرِجُوكُم مِّن دِيٜـٰرِكُمُۥٓ أَن تَبَرُّوهُمْ وَتُقْسِطُوٓاْ إِلَيْهِمُۥٓ࣌ إِنَّ ࡰ۬للَّهَ يُحِبُّ ࡲ۬لْمُقْسِطِينَ࣌', 'لا ينهيكم ࡲلله عن ࡴلذين لم يقتلوكم فے ࡴلدين ولم يخرجوكم من ديركم أن تبروهم وتقسطوا إليهم࣌ إن ࡰلله يحب ࡲلمقسطين࣌', NULL, 550, 'local:warsh-text.json'),
  ('warsh-60-9', 'warsh', 60, 9, 'إِنَّمَا يَنْهٜيٰكُمُ ࡲ۬للَّهُ عَنِ ࡴ۬لذِينَ قَٰتَلُوكُمْ فِے ࡴ۬لدِّينِ وَأَخْرَجُوكُم مِّن دِيٜـٰرِكُمْ وَظَٰهَرُواْ عَلَىٰٓ إِخْرَاجِكُمُۥٓ أَن تَوَلَّوْهُمْ࣌ وَمَنْ يَّتَوَلَّهُمْ فَأُوْلَٰٓئِكَ هُمُ ࡲ۬لظَّٰلِمُونَ࣌', 'إنما ينهيكم ࡲلله عن ࡴلذين قتلوكم فے ࡴلدين وأخرجوكم من ديركم وظهروا على إخراجكم أن تولوهم࣌ ومن يتولهم فأولئك هم ࡲلظلمون࣌', NULL, 550, 'local:warsh-text.json'),
  ('warsh-60-10', 'warsh', 60, 10, 'يَٰٓأَيُّهَا ࡰ۬لذِينَ ءَامَنُوٓاْ إِذَا جَآءَكُمُ ࡲ۬لْمُومِنَٰتُ مُهَٰجِرَٰتࣲ فَامْتَحِنُوهُنَّ࣌ ࡰ۬للَّهُ أَعْلَمُ بِإِيمَٰنِهِنَّ࣌ فَإِنْ عَلِمْتُمُوهُنَّ مُومِنَٰتࣲ فَلَا تَرْجِعُوهُنَّ إِلَى ࡰ۬لْكُفّٜارِ࣌ لَا هُنَّ حِلࣱّ لَّهُمْ وَلَا هُمْ يَحِلُّونَ لَهُنَّ࣌ وَءَاتُوهُم مَّآ أَنفَقُواْ࣌ وَلَا جُنَاحَ عَلَيْكُمُۥٓ أَن تَنكِحُوهُنَّ إِذَآ ءَاتَيْتُمُوهُنَّ أُجُورَهُنَّ࣌ وَلَا تُمْسِكُواْ بِعِصَمِ ࡴ۬لْكَوَافِرِ࣌ وَسْـَٔلُواْ مَآ أَنفَقْتُمْ وَلْيَسْـَٔلُواْ مَآ أَنفَقُواْ࣌ ذَٰلِكُمْ حُكْمُ ࡲ۬للَّهِ يَحْكُمُ بَيْنَكُمْ࣌ وَاللَّهُ عَلِيمٌ حَكِيمࣱ࣌', 'يأيها ࡰلذين ءامنوا إذا جاءكم ࡲلمومنت مهجرت فامتحنوهن࣌ ࡰلله أعلم بإيمنهن࣌ فإن علمتموهن مومنت فلا ترجعوهن إلى ࡰلكفار࣌ لا هن حل لهم ولا هم يحلون لهن࣌ وءاتوهم ما أنفقوا࣌ ولا جناح عليكم أن تنكحوهن إذا ءاتيتموهن أجورهن࣌ ولا تمسكوا بعصم ࡴلكوافر࣌ وسلوا ما أنفقتم وليسلوا ما أنفقوا࣌ ذلكم حكم ࡲلله يحكم بينكم࣌ والله عليم حكيم࣌', NULL, 550, 'local:warsh-text.json'),
  ('warsh-60-11', 'warsh', 60, 11, 'وَإِن فَاتَكُمْ شَےْءࣱ مِّنَ ࡰزْوَٰجِكُمُۥٓ إِلَى ࡰ۬لْكُفّٜارِ فَعَاقَبْتُمْ فَـَٔاتُواْ ࡲ۬لذِينَ ذَهَبَتَ ࡰزْوَٰجُهُم مِّثْلَ مَآ أَنفَقُواْ࣌ وَاتَّقُواْ ࡲ۬للَّهَ ࡰ۬لذِےٓ أَنتُم بِهِۦ مُومِنُونَ࣌', 'وإن فاتكم شےء من ࡰزوجكم إلى ࡰلكفار فعاقبتم فاتوا ࡲلذين ذهبت ࡰزوجهم مثل ما أنفقوا࣌ واتقوا ࡲلله ࡰلذے أنتم به مومنون࣌', NULL, 550, 'local:warsh-text.json'),
  ('warsh-60-12', 'warsh', 60, 12, 'يَٰٓأَيُّهَا‏ ࡰ۬لنَّبِےٓءُ ࡹِذَا جَآءَكَ ࡰ۬لْمُومِنَٰتُ يُبَايِعْنَكَ عَلَىٰٓ أَن لَّا يُشْرِكْنَ بِاللَّهِ شَيْـٔاࣰ وَلَا يَسْرِقْنَ وَلَا يَزْنِينَ وَلَا يَقْتُلْنَ أَوْلَٰدَهُنَّ وَلَا يَاتِينَ بِبُهْتَٰنࣲ يَفْتَرِينَهُۥ بَيْنَ أَيْدِيهِنَّ وَأَرْجُلِهِنَّ وَلَا يَعْصِينَكَ فِے مَعْرُوفࣲ فَبَايِعْهُنَّ وَاسْتَغْفِرْ لَهُنَّ ࡰ۬للَّهَ࣌ إِنَّ ࡰ۬للَّهَ غَفُورࣱ رَّحِيمࣱ࣌', 'يأيها‏ ࡰلنبےء ࡹذا جاءك ࡰلمومنت يبايعنك على أن لا يشركن بالله شيا ولا يسرقن ولا يزنين ولا يقتلن أولدهن ولا ياتين ببهتن يفترينه بين أيديهن وأرجلهن ولا يعصينك فے معروف فبايعهن واستغفر لهن ࡰلله࣌ إن ࡰلله غفور رحيم࣌', NULL, 551, 'local:warsh-text.json'),
  ('warsh-60-13', 'warsh', 60, 13, 'يَٰٓأَيُّهَا ࡰ۬لذِينَ ءَامَنُواْ لَا تَتَوَلَّوْاْ قَوْماً غَضِبَ ࡰ۬للَّهُ عَلَيْهِمْ قَدْ يَئِسُواْ مِنَ ࡰ۬لَاخِرَةِ كَمَا يَئِسَ ࡰ۬لْكُفَّارُ مِنَ ࡰصْحَٰبِ ࡴ۬لْقُبُورِ࣌', 'يأيها ࡰلذين ءامنوا لا تتولوا قوما غضب ࡰلله عليهم قد يئسوا من ࡰلاخرة كما يئس ࡰلكفار من ࡰصحب ࡴلقبور࣌', NULL, 551, 'local:warsh-text.json'),
  ('warsh-61-1', 'warsh', 61, 1, 'سَبَّحَ لِلهِ مَا فِے ࡴ۬لسَّمَٰوَٰتِ وَمَا فِے ࡴ۬لَارْضِ࣌ وَهُوَ ࡰ۬لْعَزِيزُ ࡲ۬لْحَكِيمُ࣌', 'سبح لله ما فے ࡴلسموت وما فے ࡴلارض࣌ وهو ࡰلعزيز ࡲلحكيم࣌', NULL, 551, 'local:warsh-text.json'),
  ('warsh-61-2', 'warsh', 61, 2, 'يَٰٓأَيُّهَا ࡰ۬لذِينَ ءَامَنُواْ لِمَ تَقُولُونَ مَا لَا تَفْعَلُونَ࣌', 'يأيها ࡰلذين ءامنوا لم تقولون ما لا تفعلون࣌', NULL, 551, 'local:warsh-text.json'),
  ('warsh-61-3', 'warsh', 61, 3, 'كَبُرَ مَقْتاً عِندَ ࡰ۬للَّهِ أَن تَقُولُواْ مَا لَا تَفْعَلُونَ࣌', 'كبر مقتا عند ࡰلله أن تقولوا ما لا تفعلون࣌', NULL, 551, 'local:warsh-text.json'),
  ('warsh-61-4', 'warsh', 61, 4, 'إِنَّ ࡰ۬للَّهَ يُحِبُّ ࡲ۬لذِينَ يُقَٰتِلُونَ فِے سَبِيلِهِۦ صَفّاࣰ كَأَنَّهُم بُنْيَٰنࣱ مَّرْصُوصࣱ࣌', 'إن ࡰلله يحب ࡲلذين يقتلون فے سبيله صفا كأنهم بنين مرصوص࣌', NULL, 551, 'local:warsh-text.json'),
  ('warsh-61-5', 'warsh', 61, 5, 'وَإِذْ قَالَ مُوسٜىٰ لِقَوْمِهِۦ يَٰقَوْمِ لِمَ تُوذُونَنِے وَقَد تَّعْلَمُونَ أَنِّے رَسُولُ ࡲ۬للَّهِ إِلَيْكُمْ࣌ فَلَمَّا زَاغُوٓاْ أَزَاغَ ࡰ۬للَّهُ قُلُوبَهُمْ࣌ وَاللَّهُ لَا يَهْدِے ࡴ۬لْقَوْمَ ࡰ۬لْفَٰسِقِينَ࣌', 'وإذ قال موسى لقومه يقوم لم توذوننے وقد تعلمون أنے رسول ࡲلله إليكم࣌ فلما زاغوا أزاغ ࡰلله قلوبهم࣌ والله لا يهدے ࡴلقوم ࡰلفسقين࣌', NULL, 551, 'local:warsh-text.json'),
  ('warsh-61-6', 'warsh', 61, 6, 'وَإِذْ قَالَ عِيسَى ࡰٜبْنُ مَرْيَمَ يَٰبَنِےٓ إِسْرَآءِيلَ إِنِّے رَسُولُ ࡲ۬للَّهِ إِلَيْكُم مُّصَدِّقاࣰ لِّمَا بَيْنَ يَدَيَّ مِنَ ࡰ۬لتَّوْرٜيٰةِ وَمُبَشِّراَۢ بِرَسُولࣲ يَاتِے مِنۢ بَعْدِيَ ࡰٜسْمُهُۥٓ أَحْمَدُ࣌ فَلَمَّا جَآءَهُم بِالْبَيِّنَٰتِ قَالُواْ هَٰذَا سِحْرࣱ مُّبِينࣱ࣌', 'وإذ قال عيسى ࡰبن مريم يبنے إسراءيل إنے رسول ࡲلله إليكم مصدقا لما بين يدي من ࡰلتورية ومبشرا برسول ياتے من بعدي ࡰسمه أحمد࣌ فلما جاءهم بالبينت قالوا هذا سحر مبين࣌', NULL, 552, 'local:warsh-text.json'),
  ('warsh-61-7', 'warsh', 61, 7, 'وَمَنَ ࡰظْلَمُ مِمَّنِ ࡴٜفْتَرٜىٰ عَلَى ࡰ۬للَّهِ ࡴ۬لْكَذِبَ وَهُوَ يُدْعٜىٰٓ إِلَى ࡰ۬لِاسْلَٰمِ࣌ وَاللَّهُ لَا يَهْدِے ࡴ۬لْقَوْمَ ࡰ۬لظَّٰلِمِينَ࣌', 'ومن ࡰظلم ممن ࡴفترى على ࡰلله ࡴلكذب وهو يدعى إلى ࡰلاسلم࣌ والله لا يهدے ࡴلقوم ࡰلظلمين࣌', NULL, 552, 'local:warsh-text.json'),
  ('warsh-61-8', 'warsh', 61, 8, 'يُرِيدُونَ لِيُطْفِـُٔواْ نُورَ ࡰ۬للَّهِ بِأَفْوَٰهِهِمْ وَاللَّهُ مُتِمࣱّ نُّورَهُۥ وَلَوْ كَرِهَ ࡰ۬لْكَٰفِرُونَ࣌', 'يريدون ليطفوا نور ࡰلله بأفوههم والله متم نوره ولو كره ࡰلكفرون࣌', NULL, 552, 'local:warsh-text.json'),
  ('warsh-61-9', 'warsh', 61, 9, 'هُوَ ࡰ۬لذِےٓ أَرْسَلَ رَسُولَهُۥ بِالْهُدٜىٰ وَدِينِ ࡴ۬لْحَقِّ لِيُظْهِرَهُۥ عَلَى ࡰ۬لدِّينِ كُلِّهِۦ وَلَوْ كَرِهَ ࡰ۬لْمُشْرِكُونَ࣌', 'هو ࡰلذے أرسل رسوله بالهدى ودين ࡴلحق ليظهره على ࡰلدين كله ولو كره ࡰلمشركون࣌', NULL, 552, 'local:warsh-text.json'),
  ('warsh-61-10', 'warsh', 61, 10, 'يَٰٓأَيُّهَا ࡰ۬لذِينَ ءَامَنُواْ هَلَ ࡰدُلُّكُمْ عَلَىٰ تِجَٰرَةࣲ تُنجِيكُم مِّنْ عَذَابٍ ࡰلِيمࣲ', 'يأيها ࡰلذين ءامنوا هل ࡰدلكم على تجرة تنجيكم من عذاب ࡰليم', NULL, 552, 'local:warsh-text.json'),
  ('warsh-61-11', 'warsh', 61, 11, 'تُومِنُونَ بِاللَّهِ وَرَسُولِهِۦ وَتُجَٰهِدُونَ فِے سَبِيلِ ࡴ۬للَّهِ بِأَمْوَٰلِكُمْ وَأَنفُسِكُمْ ذَٰلِكُمْ خَيْرࣱ لَّكُمُۥٓ إِن كُنتُمْ تَعْلَمُونَ', 'تومنون بالله ورسوله وتجهدون فے سبيل ࡴلله بأمولكم وأنفسكم ذلكم خير لكم إن كنتم تعلمون', NULL, 552, 'local:warsh-text.json'),
  ('warsh-61-12', 'warsh', 61, 12, 'يَغْفِرْ لَكُمْ ذُنُوبَكُمْ وَيُدْخِلْكُمْ جَنَّٰتࣲ تَجْرِے مِن تَحْتِهَا ࡰ۬لَانْهَٰرُ وَمَسَٰكِنَ طَيِّبَةࣰ فِے جَنَّٰتِ عَدْنࣲ࣌ ذَٰلِكَ ࡰ۬لْفَوْزُ ࡲ۬لْعَظِيمُ࣌', 'يغفر لكم ذنوبكم ويدخلكم جنت تجرے من تحتها ࡰلانهر ومسكن طيبة فے جنت عدن࣌ ذلك ࡰلفوز ࡲلعظيم࣌', NULL, 552, 'local:warsh-text.json'),
  ('warsh-61-13', 'warsh', 61, 13, 'وَأُخْرٜىٰ تُحِبُّونَهَا نَصْرࣱ مِّنَ ࡰ۬للَّهِ وَفَتْحࣱ قَرِيبࣱ࣌ وَبَشِّرِ ࡴ۬لْمُومِنِينَ࣌', 'وأخرى تحبونها نصر من ࡰلله وفتح قريب࣌ وبشر ࡴلمومنين࣌', NULL, 552, 'local:warsh-text.json'),
  ('warsh-61-14', 'warsh', 61, 14, 'يَٰٓأَيُّهَا ࡰ۬لذِينَ ءَامَنُواْ كُونُوٓاْ أَنصَاراࣰ لِّلهِ كَمَا قَالَ عِيسَى ࡰٜبْنُ مَرْيَمَ لِلْحَوَارِيِّۑنَ مَنَ ࡰنصَارِيَ إِلَى ࡰ۬للَّهِ࣌ قَالَ ࡰ۬لْحَوَارِيُّونَ نَحْنُ أَنصَارُ ࡲ۬للَّهِ࣌ فَـَٔامَنَت طَّآئِفَةࣱ مِّنۢ بَنِےٓ إِسْرَآءِيلَ وَكَفَرَت طَّآئِفَةࣱ࣌ فَأَيَّدْنَا ࡰ۬لذِينَ ءَامَنُواْ عَلَىٰ عَدُوِّهِمْ فَأَصْبَحُواْ ظَٰهِرِينَ࣌', 'يأيها ࡰلذين ءامنوا كونوا أنصارا لله كما قال عيسى ࡰبن مريم للحواريۑن من ࡰنصاري إلى ࡰلله࣌ قال ࡰلحواريون نحن أنصار ࡲلله࣌ فامنت طائفة من بنے إسراءيل وكفرت طائفة࣌ فأيدنا ࡰلذين ءامنوا على عدوهم فأصبحوا ظهرين࣌', NULL, 552, 'local:warsh-text.json'),
  ('warsh-62-1', 'warsh', 62, 1, 'يُسَبِّحُ لِلهِ مَا فِے ࡴ۬لسَّمَٰوَٰتِ وَمَا فِے ࡴ۬لَارْضِ ࡴ۬لْمَلِكِ ࡴ۬لْقُدُّوسِ ࡴ۬لْعَزِيزِ ࡴ۬لْحَكِيمِ࣌', 'يسبح لله ما فے ࡴلسموت وما فے ࡴلارض ࡴلملك ࡴلقدوس ࡴلعزيز ࡴلحكيم࣌', NULL, 553, 'local:warsh-text.json'),
  ('warsh-62-2', 'warsh', 62, 2, 'هُوَ ࡰ۬لذِے بَعَثَ فِے ࡴ۬لُامِّيِّۑنَ رَسُولاࣰ مِّنْهُمْ يَتْلُواْ عَلَيْهِمُۥٓ ءَايَٰتِهِۦ وَيُزَكِّيهِمْ وَيُعَلِّمُهُمُ ࡲ۬لْكِتَٰبَ وَالْحِكْمَةَ وَإِن كَانُواْ مِن قَبْلُ لَفِے ضَلَٰلࣲ مُّبِينࣲ', 'هو ࡰلذے بعث فے ࡴلاميۑن رسولا منهم يتلوا عليهم ءايته ويزكيهم ويعلمهم ࡲلكتب والحكمة وإن كانوا من قبل لفے ضلل مبين', NULL, 553, 'local:warsh-text.json'),
  ('warsh-62-3', 'warsh', 62, 3, 'وَءَاخَرِينَ مِنْهُمْ لَمَّا يَلْحَقُواْ بِهِمْ࣌ وَهُوَ ࡰ۬لْعَزِيزُ ࡲ۬لْحَكِيمُ࣌', 'وءاخرين منهم لما يلحقوا بهم࣌ وهو ࡰلعزيز ࡲلحكيم࣌', NULL, 553, 'local:warsh-text.json'),
  ('warsh-62-4', 'warsh', 62, 4, 'ذَٰلِكَ فَضْلُ ࡲ۬للَّهِ يُوتِيهِ مَنْ يَّشَآءُ࣌ وَاللَّهُ ذُو ࡲ۬لْفَضْلِ ࡴ۬لْعَظِيمِ࣌', 'ذلك فضل ࡲلله يوتيه من يشاء࣌ والله ذو ࡲلفضل ࡴلعظيم࣌', NULL, 553, 'local:warsh-text.json'),
  ('warsh-62-5', 'warsh', 62, 5, 'مَثَلُ ࡲ۬لذِينَ حُمِّلُواْ ࡲ۬لتَّوْرٜيٰةَ ثُمَّ لَمْ يَحْمِلُوهَا كَمَثَلِ ࡴ۬لْحِمٜارِ يَحْمِلُ أَسْفَاراَۢ࣌ بِيسَ مَثَلُ ࡲ۬لْقَوْمِ ࡴ۬لذِينَ كَذَّبُواْ بِـَٔايَٰتِ ࡴ۬للَّهِ࣌ وَاللَّهُ لَا يَهْدِے ࡴ۬لْقَوْمَ ࡰ۬لظَّٰلِمِينَ࣌', 'مثل ࡲلذين حملوا ࡲلتورية ثم لم يحملوها كمثل ࡴلحمار يحمل أسفارا࣌ بيس مثل ࡲلقوم ࡴلذين كذبوا بايت ࡴلله࣌ والله لا يهدے ࡴلقوم ࡰلظلمين࣌', NULL, 553, 'local:warsh-text.json'),
  ('warsh-62-6', 'warsh', 62, 6, 'قُلْ يَٰٓأَيُّهَا ࡰ۬لذِينَ هَادُوٓاْ إِن زَعَمْتُمُۥٓ أَنَّكُمُۥٓ أَوْلِيَآءُ لِلهِ مِن دُونِ ࡴ۬لنَّاسِ فَتَمَنَّوُاْ ࡲ۬لْمَوْتَ إِن كُنتُمْ صَٰدِقِينَ࣌', 'قل يأيها ࡰلذين هادوا إن زعمتم أنكم أولياء لله من دون ࡴلناس فتمنوا ࡲلموت إن كنتم صدقين࣌', NULL, 553, 'local:warsh-text.json'),
  ('warsh-62-7', 'warsh', 62, 7, 'وَلَا يَتَمَنَّوْنَهُۥٓ أَبَداَۢ بِمَا قَدَّمَتَ ࡰيْدِيهِمْ࣌ وَاللَّهُ عَلِيمُۢ بِالظَّٰلِمِينَ࣌', 'ولا يتمنونه أبدا بما قدمت ࡰيديهم࣌ والله عليم بالظلمين࣌', NULL, 553, 'local:warsh-text.json'),
  ('warsh-62-8', 'warsh', 62, 8, 'قُلِ ࡴنَّ ࡰ۬لْمَوْتَ ࡰ۬لذِے تَفِرُّونَ مِنْهُ فَإِنَّهُۥ مُلَٰقِيكُمْ ثُمَّ تُرَدُّونَ إِلَىٰ عَٰلِمِ ࡴ۬لْغَيْبِ وَالشَّهَٰدَةِ فَيُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ࣌', 'قل ࡴن ࡰلموت ࡰلذے تفرون منه فإنه ملقيكم ثم تردون إلى علم ࡴلغيب والشهدة فينبئكم بما كنتم تعملون࣌', NULL, 553, 'local:warsh-text.json'),
  ('warsh-62-9', 'warsh', 62, 9, 'يَٰٓأَيُّهَا ࡰ۬لذِينَ ءَامَنُوٓاْ إِذَا نُودِيَ لِلصَّلَوٰةِ مِنْ يَّوْمِ ࡴ۬لْجُمُعَةِ فَاسْعَوِاْ ࡴلَىٰ ذِكْرِ ࡴ۬للَّهِ وَذَرُواْ ࡲ۬لْبَيْعَ࣌ ذَٰلِكُمْ خَيْرࣱ لَّكُمُۥٓ إِن كُنتُمْ تَعْلَمُونَ࣌', 'يأيها ࡰلذين ءامنوا إذا نودي للصلوة من يوم ࡴلجمعة فاسعوا ࡴلى ذكر ࡴلله وذروا ࡲلبيع࣌ ذلكم خير لكم إن كنتم تعلمون࣌', NULL, 554, 'local:warsh-text.json'),
  ('warsh-62-10', 'warsh', 62, 10, 'فَإِذَا قُضِيَتِ ࡴ۬لصَّلَوٰةُ فَانتَشِرُواْ فِے ࡴ۬لَارْضِ وَابْتَغُواْ مِن فَضْلِ ࡴ۬للَّهِ وَاذْكُرُواْ ࡲ۬للَّهَ كَثِيراࣰ لَّعَلَّكُمْ تُفْلِحُونَ࣌', 'فإذا قضيت ࡴلصلوة فانتشروا فے ࡴلارض وابتغوا من فضل ࡴلله واذكروا ࡲلله كثيرا لعلكم تفلحون࣌', NULL, 554, 'local:warsh-text.json'),
  ('warsh-62-11', 'warsh', 62, 11, 'وَإِذَا رَأَوْاْ تِجَٰرَةً ࡰوْ لَهْواً ࡴٜنفَضُّوٓاْ إِلَيْهَا وَتَرَكُوكَ قَآئِماࣰ࣌ قُلْ مَا عِندَ ࡰ۬للَّهِ خَيْرࣱ مِّنَ ࡰ۬للَّهْوِ وَمِنَ ࡰ۬لتِّجَٰرَةِ࣌ وَاللَّهُ خَيْرُ ࡲ۬لرَّٰزِقِينَ࣌', 'وإذا رأوا تجرة ࡰو لهوا ࡴنفضوا إليها وتركوك قائما࣌ قل ما عند ࡰلله خير من ࡰللهو ومن ࡰلتجرة࣌ والله خير ࡲلرزقين࣌', NULL, 554, 'local:warsh-text.json'),
  ('warsh-63-1', 'warsh', 63, 1, 'إِذَا جَآءَكَ ࡰ۬لْمُنَٰفِقُونَ قَالُواْ نَشْهَدُ إِنَّكَ لَرَسُولُ ࡲ۬للَّهِ࣌ وَاللَّهُ يَعْلَمُ إِنَّكَ لَرَسُولُهُۥ࣌ وَاللَّهُ يَشْهَدُ إِنَّ ࡰ۬لْمُنَٰفِقِينَ لَكَٰذِبُونَ࣌', 'إذا جاءك ࡰلمنفقون قالوا نشهد إنك لرسول ࡲلله࣌ والله يعلم إنك لرسوله࣌ والله يشهد إن ࡰلمنفقين لكذبون࣌', NULL, 554, 'local:warsh-text.json'),
  ('warsh-63-2', 'warsh', 63, 2, 'ࡰٜتَّخَذُوٓاْ أَيْمَٰنَهُمْ جُنَّةࣰ فَصَدُّواْ عَن سَبِيلِ ࡴ۬للَّهِ࣌ إِنَّهُمْ سَآءَ مَا كَانُواْ يَعْمَلُونَ࣌', 'ࡰتخذوا أيمنهم جنة فصدوا عن سبيل ࡴلله࣌ إنهم ساء ما كانوا يعملون࣌', NULL, 554, 'local:warsh-text.json'),
  ('warsh-63-3', 'warsh', 63, 3, 'ذَٰلِكَ بِأَنَّهُمُۥٓ ءَامَنُواْ ثُمَّ كَفَرُواْ فَطُبِعَ عَلَىٰ قُلُوبِهِمْ فَهُمْ لَا يَفْقَهُونَ࣌', 'ذلك بأنهم ءامنوا ثم كفروا فطبع على قلوبهم فهم لا يفقهون࣌', NULL, 554, 'local:warsh-text.json'),
  ('warsh-63-4', 'warsh', 63, 4, 'وَإِذَا رَأَيْتَهُمْ تُعْجِبُكَ أَجْسَامُهُمْ࣌ وَإِنْ يَّقُولُواْ تَسْمَعْ لِقَوْلِهِمْ كَأَنَّهُمْ خُشُبࣱ مُّسَنَّدَةࣱ࣌ يَحْسِبُونَ كُلَّ صَيْحَةٍ عَلَيْهِمْ࣌ هُمُ ࡲ۬لْعَدُوُّ࣌ فَاحْذَرْهُمْ࣌ قَٰتَلَهُمُ ࡲ۬للَّهُ࣌ أَنّٜىٰ يُوفَكُونَ࣌', 'وإذا رأيتهم تعجبك أجسامهم࣌ وإن يقولوا تسمع لقولهم كأنهم خشب مسندة࣌ يحسبون كل صيحة عليهم࣌ هم ࡲلعدو࣌ فاحذرهم࣌ قتلهم ࡲلله࣌ أنى يوفكون࣌', NULL, 554, 'local:warsh-text.json'),
  ('warsh-63-5', 'warsh', 63, 5, 'وَإِذَا قِيلَ لَهُمْ تَعَالَوْاْ يَسْتَغْفِرْ لَكُمْ رَسُولُ ࡲ۬للَّهِ لَوَوْاْ رُءُوسَهُمْ وَرَأَيْتَهُمْ يَصُدُّونَ وَهُم مُّسْتَكْبِرُونَ࣌', 'وإذا قيل لهم تعالوا يستغفر لكم رسول ࡲلله لووا رءوسهم ورأيتهم يصدون وهم مستكبرون࣌', NULL, 555, 'local:warsh-text.json'),
  ('warsh-63-6', 'warsh', 63, 6, 'سَوَآءٌ عَلَيْهِمُۥٓ أَسْتَغْفَرْتَ لَهُمُۥٓ أَمْ لَمْ تَسْتَغْفِرْ لَهُمْ࣌ لَنْ يَّغْفِرَ ࡰ۬للَّهُ لَهُمُۥٓ࣌ إِنَّ ࡰ۬للَّهَ لَا يَهْدِے ࡴ۬لْقَوْمَ ࡰ۬لْفَٰسِقِينَ࣌', 'سواء عليهم أستغفرت لهم أم لم تستغفر لهم࣌ لن يغفر ࡰلله لهم࣌ إن ࡰلله لا يهدے ࡴلقوم ࡰلفسقين࣌', NULL, 555, 'local:warsh-text.json'),
  ('warsh-63-7', 'warsh', 63, 7, 'هُمُ ࡲ۬لذِينَ يَقُولُونَ لَا تُنفِقُواْ عَلَىٰ مَنْ عِندَ رَسُولِ ࡴ۬للَّهِ حَتَّىٰ يَنفَضُّواْ࣌ وَلِلهِ خَزَآئِنُ ࡲ۬لسَّمَٰوَٰتِ وَالَارْضِ࣌ وَلَٰكِنَّ ࡰ۬لْمُنَٰفِقِينَ لَا يَفْقَهُونَ࣌', 'هم ࡲلذين يقولون لا تنفقوا على من عند رسول ࡴلله حتى ينفضوا࣌ ولله خزائن ࡲلسموت والارض࣌ ولكن ࡰلمنفقين لا يفقهون࣌', NULL, 555, 'local:warsh-text.json'),
  ('warsh-63-8', 'warsh', 63, 8, 'يَقُولُونَ لَئِن رَّجَعْنَآ إِلَى ࡰ۬لْمَدِينَةِ لَيُخْرِجَنَّ ࡰ۬لَاعَزُّ مِنْهَا ࡰ۬لَاذَلَّ࣌ وَلِلهِ ࡴ۬لْعِزَّةُ وَلِرَسُولِهِۦ وَلِلْمُومِنِينَ࣌ وَلَٰكِنَّ ࡰ۬لْمُنَٰفِقِينَ لَا يَعْلَمُونَ࣌', 'يقولون لئن رجعنا إلى ࡰلمدينة ليخرجن ࡰلاعز منها ࡰلاذل࣌ ولله ࡴلعزة ولرسوله وللمومنين࣌ ولكن ࡰلمنفقين لا يعلمون࣌', NULL, 555, 'local:warsh-text.json'),
  ('warsh-63-9', 'warsh', 63, 9, '۞ يَٰٓأَيُّهَا ࡰ۬لذِينَ ءَامَنُواْ لَا تُلْهِكُمُۥٓ أَمْوَٰلُكُمْ وَلَآ أَوْلَٰدُكُمْ عَن ذِكْرِ ࡴ۬للَّهِ࣌ وَمَنْ يَّفْعَلْ ذَٰلِكَ فَأُوْلَٰٓئِكَ هُمُ ࡲ۬لْخَٰسِرُونَ࣌', 'يأيها ࡰلذين ءامنوا لا تلهكم أمولكم ولا أولدكم عن ذكر ࡴلله࣌ ومن يفعل ذلك فأولئك هم ࡲلخسرون࣌', NULL, 555, 'local:warsh-text.json'),
  ('warsh-63-10', 'warsh', 63, 10, 'وَأَنفِقُواْ مِن مَّا رَزَقْنَٰكُم مِّن قَبْلِ أَنْ يَّاتِيَ أَحَدَكُمُ ࡲ۬لْمَوْتُ فَيَقُولَ رَبِّ لَوْلَآ أَخَّرْتَنِےٓ إِلَىٰٓ أَجَلࣲ قَرِيبࣲ فَأَصَّدَّقَ وَأَكُن مِّنَ ࡰ۬لصَّٰلِحِينَ࣌', 'وأنفقوا من ما رزقنكم من قبل أن ياتي أحدكم ࡲلموت فيقول رب لولا أخرتنے إلى أجل قريب فأصدق وأكن من ࡰلصلحين࣌', NULL, 555, 'local:warsh-text.json'),
  ('warsh-63-11', 'warsh', 63, 11, 'وَلَنْ يُّوَ۬خِّرَ ࡰ۬للَّهُ نَفْساً ࡴذَا جَآءَ اجَلُهَا࣌ وَاللَّهُ خَبِيرُۢ بِمَا تَعْمَلُونَ࣌', 'ولن يوخر ࡰلله نفسا ࡴذا جاء اجلها࣌ والله خبير بما تعملون࣌', NULL, 555, 'local:warsh-text.json'),
  ('warsh-64-1', 'warsh', 64, 1, 'يُسَبِّحُ لِلهِ مَا فِے ࡴ۬لسَّمَٰوَٰتِ وَمَا فِے ࡴ۬لَارْضِ࣌ لَهُ ࡲ۬لْمُلْكُ وَلَهُ ࡲ۬لْحَمْدُ࣌ وَهُوَ عَلَىٰ كُلِّ شَےْءࣲ قَدِيرٌ࣌', 'يسبح لله ما فے ࡴلسموت وما فے ࡴلارض࣌ له ࡲلملك وله ࡲلحمد࣌ وهو على كل شےء قدير࣌', NULL, 556, 'local:warsh-text.json'),
  ('warsh-64-2', 'warsh', 64, 2, 'هُوَ ࡰ۬لذِے خَلَقَكُمْ فَمِنكُمْ كَافِرࣱ وَمِنكُم مُّومِنࣱ࣌ وَاللَّهُ بِمَا تَعْمَلُونَ بَصِيرٌ࣌', 'هو ࡰلذے خلقكم فمنكم كافر ومنكم مومن࣌ والله بما تعملون بصير࣌', NULL, 556, 'local:warsh-text.json'),
  ('warsh-64-3', 'warsh', 64, 3, 'خَلَقَ ࡰ۬لسَّمَٰوَٰتِ وَالَارْضَ بِالْحَقِّ وَصَوَّرَكُمْ فَأَحْسَنَ صُوَرَكُمْ࣌ وَإِلَيْهِ ࡴ۬لْمَصِيرُ࣌', 'خلق ࡰلسموت والارض بالحق وصوركم فأحسن صوركم࣌ وإليه ࡴلمصير࣌', NULL, 556, 'local:warsh-text.json'),
  ('warsh-64-4', 'warsh', 64, 4, 'يَعْلَمُ مَا فِے ࡴ۬لسَّمَٰوَٰتِ وَالَارْضِ وَيَعْلَمُ مَا تُسِرُّونَ وَمَا تُعْلِنُونَ࣌ وَاللَّهُ عَلِيمُۢ بِذَاتِ ࡴ۬لصُّدُورِ࣌', 'يعلم ما فے ࡴلسموت والارض ويعلم ما تسرون وما تعلنون࣌ والله عليم بذات ࡴلصدور࣌', NULL, 556, 'local:warsh-text.json'),
  ('warsh-64-5', 'warsh', 64, 5, 'أَلَمْ يَاتِكُمْ نَبَؤُاْ ࡲ۬لذِينَ كَفَرُواْ مِن قَبْلُ فَذَاقُواْ وَبَالَ أَمْرِهِمْ وَلَهُمْ عَذَابٌ ࡰلِيمࣱ࣌', 'ألم ياتكم نبؤا ࡲلذين كفروا من قبل فذاقوا وبال أمرهم ولهم عذاب ࡰليم࣌', NULL, 556, 'local:warsh-text.json'),
  ('warsh-64-6', 'warsh', 64, 6, 'ذَٰلِكَ بِأَنَّهُۥ كَانَت تَّاتِيهِمْ رُسُلُهُم بِالْبَيِّنَٰتِ فَقَالُوٓاْ أَبَشَرࣱ يَهْدُونَنَا࣌ فَكَفَرُواْ وَتَوَلَّواْ وَّاسْتَغْنَى ࡰ۬للَّهُ࣌ وَاللَّهُ غَنِيٌّ حَمِيدࣱ࣌', 'ذلك بأنه كانت تاتيهم رسلهم بالبينت فقالوا أبشر يهدوننا࣌ فكفروا وتولوا واستغنى ࡰلله࣌ والله غني حميد࣌', NULL, 556, 'local:warsh-text.json'),
  ('warsh-64-7', 'warsh', 64, 7, '۞ زَعَمَ ࡰ۬لذِينَ كَفَرُوٓاْ أَن لَّنْ يُّبْعَثُواْ࣌ قُلْ بَلٜىٰ وَرَبِّے لَتُبْعَثُنَّ ثُمَّ لَتُنَبَّؤُنَّ بِمَا عَمِلْتُمْ࣌ وَذَٰلِكَ عَلَى ࡰ۬للَّهِ يَسِيرࣱ࣌', 'زعم ࡰلذين كفروا أن لن يبعثوا࣌ قل بلى وربے لتبعثن ثم لتنبؤن بما عملتم࣌ وذلك على ࡰلله يسير࣌', NULL, 556, 'local:warsh-text.json'),
  ('warsh-64-8', 'warsh', 64, 8, 'فَـَٔامِنُواْ بِاللَّهِ وَرَسُولِهِۦ وَالنُّورِ ࡴ۬لذِےٓ أَنزَلْنَا࣌ وَاللَّهُ بِمَا تَعْمَلُونَ خَبِيرࣱ࣌', 'فامنوا بالله ورسوله والنور ࡴلذے أنزلنا࣌ والله بما تعملون خبير࣌', NULL, 556, 'local:warsh-text.json'),
  ('warsh-64-9', 'warsh', 64, 9, 'يَوْمَ يَجْمَعُكُمْ لِيَوْمِ ࡴ۬لْجَمْعِ ذَٰلِكَ يَوْمُ ࡲ۬لتَّغَابُنِ࣌ وَمَنْ يُّومِنۢ بِاللَّهِ وَيَعْمَلْ صَٰلِحاࣰ نُّكَفِّرْ عَنْهُ سَيِّـَٔاتِهِۦ وَنُدْخِلْهُ جَنَّٰتࣲ تَجْرِے مِن تَحْتِهَا ࡰ۬لَانْهَٰرُ خَٰلِدِينَ فِيهَآ أَبَداࣰ࣌ ذَٰلِكَ ࡰ۬لْفَوْزُ ࡲ۬لْعَظِيمُ࣌', 'يوم يجمعكم ليوم ࡴلجمع ذلك يوم ࡲلتغابن࣌ ومن يومن بالله ويعمل صلحا نكفر عنه سياته وندخله جنت تجرے من تحتها ࡰلانهر خلدين فيها أبدا࣌ ذلك ࡰلفوز ࡲلعظيم࣌', NULL, 556, 'local:warsh-text.json'),
  ('warsh-64-10', 'warsh', 64, 10, 'وَالذِينَ كَفَرُواْ وَكَذَّبُواْ بِـَٔايَٰتِنَآ أُوْلَٰٓئِكَ أَصْحَٰبُ ࡲ۬لنّٜارِ خَٰلِدِينَ فِيهَا࣌ وَبِيسَ ࡰ۬لْمَصِيرُ࣌', 'والذين كفروا وكذبوا بايتنا أولئك أصحب ࡲلنار خلدين فيها࣌ وبيس ࡰلمصير࣌', NULL, 557, 'local:warsh-text.json'),
  ('warsh-64-11', 'warsh', 64, 11, 'مَآ أَصَابَ مِن مُّصِيبَةٍ ࡴلَّا بِإِذْنِ ࡴ۬للَّهِ࣌ وَمَنْ يُّومِنۢ بِاللَّهِ يَهْدِ قَلْبَهُۥ࣌ وَاللَّهُ بِكُلِّ شَےْءٍ عَلِيمࣱ࣌', 'ما أصاب من مصيبة ࡴلا بإذن ࡴلله࣌ ومن يومن بالله يهد قلبه࣌ والله بكل شےء عليم࣌', NULL, 557, 'local:warsh-text.json'),
  ('warsh-64-12', 'warsh', 64, 12, 'وَأَطِيعُواْ ࡲ۬للَّهَ وَأَطِيعُواْ ࡲ۬لرَّسُولَ࣌ فَإِن تَوَلَّيْتُمْ فَإِنَّمَا عَلَىٰ رَسُولِنَا ࡰ۬لْبَلَٰغُ ࡲ۬لْمُبِينُ࣌', 'وأطيعوا ࡲلله وأطيعوا ࡲلرسول࣌ فإن توليتم فإنما على رسولنا ࡰلبلغ ࡲلمبين࣌', NULL, 557, 'local:warsh-text.json'),
  ('warsh-64-13', 'warsh', 64, 13, 'ࡲ۬للَّهُ لَآ إِلَٰهَ إِلَّا هُوَ࣌ وَعَلَى ࡰ۬للَّهِ فَلْيَتَوَكَّلِ ࡴ۬لْمُومِنُونَ࣌', 'ࡲلله لا إله إلا هو࣌ وعلى ࡰلله فليتوكل ࡴلمومنون࣌', NULL, 557, 'local:warsh-text.json'),
  ('warsh-64-14', 'warsh', 64, 14, 'يَٰٓأَيُّهَا ࡰ۬لذِينَ ءَامَنُوٓاْ إِنَّ مِنَ ࡰزْوَٰجِكُمْ وَأَوْلَٰدِكُمْ عَدُوّاࣰ لَّكُمْ فَاحْذَرُوهُمْ࣌ وَإِن تَعْفُواْ وَتَصْفَحُواْ وَتَغْفِرُواْ فَإِنَّ ࡰ۬للَّهَ غَفُورࣱ رَّحِيمٌ࣌', 'يأيها ࡰلذين ءامنوا إن من ࡰزوجكم وأولدكم عدوا لكم فاحذروهم࣌ وإن تعفوا وتصفحوا وتغفروا فإن ࡰلله غفور رحيم࣌', NULL, 557, 'local:warsh-text.json'),
  ('warsh-64-15', 'warsh', 64, 15, 'ࡴنَّمَآ أَمْوَٰلُكُمْ وَأَوْلَٰدُكُمْ فِتْنَةࣱ࣌ وَاللَّهُ عِندَهُۥٓ أَجْرٌ عَظِيمࣱ࣌', 'ࡴنما أمولكم وأولدكم فتنة࣌ والله عنده أجر عظيم࣌', NULL, 557, 'local:warsh-text.json'),
  ('warsh-64-16', 'warsh', 64, 16, 'فَاتَّقُواْ ࡲ۬للَّهَ مَا ࡰٜسْتَطَعْتُمْ وَاسْمَعُواْ وَأَطِيعُواْ وَأَنفِقُواْ خَيْراࣰ لِّأَنفُسِكُمْ࣌ وَمَنْ يُّوقَ شُحَّ نَفْسِهِۦ فَأُوْلَٰٓئِكَ هُمُ ࡲ۬لْمُفْلِحُونَ࣌', 'فاتقوا ࡲلله ما ࡰستطعتم واسمعوا وأطيعوا وأنفقوا خيرا لأنفسكم࣌ ومن يوق شح نفسه فأولئك هم ࡲلمفلحون࣌', NULL, 557, 'local:warsh-text.json'),
  ('warsh-64-17', 'warsh', 64, 17, 'إِن تُقْرِضُواْ ࡲ۬للَّهَ قَرْضاً حَسَناࣰ يُضَٰعِفْهُ لَكُمْ وَيَغْفِرْ لَكُمْ࣌ وَاللَّهُ شَكُورٌ حَلِيمٌ࣌', 'إن تقرضوا ࡲلله قرضا حسنا يضعفه لكم ويغفر لكم࣌ والله شكور حليم࣌', NULL, 557, 'local:warsh-text.json'),
  ('warsh-64-18', 'warsh', 64, 18, 'عَٰلِمُ ࡲ۬لْغَيْبِ وَالشَّهَٰدَةِ࣌ ࡴ۬لْعَزِيزُ ࡲ۬لْحَكِيمُ࣌', 'علم ࡲلغيب والشهدة࣌ ࡴلعزيز ࡲلحكيم࣌', NULL, 557, 'local:warsh-text.json'),
  ('warsh-65-1', 'warsh', 65, 1, 'يَٰٓأَيُّهَا‏ ࡰ۬لنَّبِےٓءُ ࡹِذَا طَلَّقْتُمُ ࡲ۬لنِّسَآءَ فَطَلِّقُوهُنَّ لِعِدَّتِهِنَّ وَأَحْصُواْ ࡲ۬لْعِدَّةَ࣌ وَاتَّقُواْ ࡲ۬للَّهَ رَبَّكُمْ࣌ لَا تُخْرِجُوهُنَّ مِنۢ بُيُوتِهِنَّ࣌ وَلَا يَخْرُجْنَ إِلَّآ أَنْ يَّاتِينَ بِفَٰحِشَةࣲ مُّبَيِّنَةࣲ࣌ وَتِلْكَ حُدُودُ ࡲ۬للَّهِ࣌ وَمَنْ يَّتَعَدَّ حُدُودَ ࡰ۬للَّهِ فَقَد ظَّلَمَ نَفْسَهُۥ࣌ لَا تَدْرِے لَعَلَّ ࡰ۬للَّهَ يُحْدِثُ بَعْدَ ذَٰلِكَ أَمْراࣰ࣌', 'يأيها‏ ࡰلنبےء ࡹذا طلقتم ࡲلنساء فطلقوهن لعدتهن وأحصوا ࡲلعدة࣌ واتقوا ࡲلله ربكم࣌ لا تخرجوهن من بيوتهن࣌ ولا يخرجن إلا أن ياتين بفحشة مبينة࣌ وتلك حدود ࡲلله࣌ ومن يتعد حدود ࡰلله فقد ظلم نفسه࣌ لا تدرے لعل ࡰلله يحدث بعد ذلك أمرا࣌', NULL, 558, 'local:warsh-text.json'),
  ('warsh-65-2', 'warsh', 65, 2, 'فَإِذَا بَلَغْنَ أَجَلَهُنَّ فَأَمْسِكُوهُنَّ بِمَعْرُوفٍ ࡰوْ فَارِقُوهُنَّ بِمَعْرُوفࣲ࣌ وَأَشْهِدُواْ ذَوَےْ عَدْلࣲ مِّنكُمْ࣌ وَأَقِيمُواْ ࡲ۬لشَّهَٰدَةَ لِلهِ࣌ ذَٰلِكُمْ يُوعَظُ بِهِۦ مَن كَانَ يُومِنُ بِاللَّهِ وَالْيَوْمِ ࡴ۬لَاخِرِ࣌ وَمَنْ يَّتَّقِ ࡴ۬للَّهَ يَجْعَل لَّهُۥ مَخْرَجاࣰ', 'فإذا بلغن أجلهن فأمسكوهن بمعروف ࡰو فارقوهن بمعروف࣌ وأشهدوا ذوے عدل منكم࣌ وأقيموا ࡲلشهدة لله࣌ ذلكم يوعظ به من كان يومن بالله واليوم ࡴلاخر࣌ ومن يتق ࡴلله يجعل له مخرجا', NULL, 558, 'local:warsh-text.json'),
  ('warsh-65-3', 'warsh', 65, 3, 'وَيَرْزُقْهُ مِنْ حَيْثُ لَا يَحْتَسِبُ࣌ وَمَنْ يَّتَوَكَّلْ عَلَى ࡰ۬للَّهِ فَهُوَ حَسْبُهُۥٓ࣌ إِنَّ ࡰ۬للَّهَ بَٰلِغٌ ࡰمْرَهُۥ࣌ قَدْ جَعَلَ ࡰ۬للَّهُ لِكُلِّ شَےْءࣲ قَدْراࣰ࣌', 'ويرزقه من حيث لا يحتسب࣌ ومن يتوكل على ࡰلله فهو حسبه࣌ إن ࡰلله بلغ ࡰمره࣌ قد جعل ࡰلله لكل شےء قدرا࣌', NULL, 558, 'local:warsh-text.json'),
  ('warsh-65-4', 'warsh', 65, 4, 'وَالٜےْ يَئِسْنَ مِنَ ࡰ۬لْمَحِيضِ مِن نِّسَآئِكُمُۥٓ إِنِ ࡴٜرْتَبْتُمْ فَعِدَّتُهُنَّ ثَلَٰثَةُ أَشْهُرࣲ وَالٜےْ لَمْ يَحِضْنَ࣌ وَأُوْلَٰتُ ࡲ۬لَاحْمَالِ أَجَلُهُنَّ أَنْ يَّضَعْنَ حَمْلَهُنَّ࣌ وَمَنْ يَّتَّقِ ࡴ۬للَّهَ يَجْعَل لَّهُۥ مِنَ ࡰمْرِهِۦ يُسْراࣰ࣌', 'والے يئسن من ࡰلمحيض من نسائكم إن ࡴرتبتم فعدتهن ثلثة أشهر والے لم يحضن࣌ وأولت ࡲلاحمال أجلهن أن يضعن حملهن࣌ ومن يتق ࡴلله يجعل له من ࡰمره يسرا࣌', NULL, 558, 'local:warsh-text.json'),
  ('warsh-65-5', 'warsh', 65, 5, 'ذَٰلِكَ أَمْرُ ࡲ۬للَّهِ أَنزَلَهُۥٓ إِلَيْكُمْ࣌ وَمَنْ يَّتَّقِ ࡴ۬للَّهَ يُكَفِّرْ عَنْهُ سَيِّـَٔاتِهِۦ وَيُعْظِمْ لَهُۥٓ أَجْراً࣌', 'ذلك أمر ࡲلله أنزله إليكم࣌ ومن يتق ࡴلله يكفر عنه سياته ويعظم له أجرا࣌', NULL, 558, 'local:warsh-text.json'),
  ('warsh-65-6', 'warsh', 65, 6, 'ࡰسْكِنُوهُنَّ مِنْ حَيْثُ سَكَنتُم مِّنْ وُّجْدِكُمْ࣌ وَلَا تُضَآرُّوهُنَّ لِتُضَيِّقُواْ عَلَيْهِنَّ࣌ وَإِن كُنَّ أُوْلَٰتِ حَمْلࣲ فَأَنفِقُواْ عَلَيْهِنَّ حَتَّىٰ يَضَعْنَ حَمْلَهُنَّ࣌ فَإِنَ ࡰرْضَعْنَ لَكُمْ فَـَٔاتُوهُنَّ أُجُورَهُنَّ وَاتَمِرُواْ بَيْنَكُم بِمَعْرُوفࣲ࣌ ۞ وَإِن تَعَاسَرْتُمْ فَسَتُرْضِعُ لَهُۥٓ أُخْرٜىٰ࣌', 'ࡰسكنوهن من حيث سكنتم من وجدكم࣌ ولا تضاروهن لتضيقوا عليهن࣌ وإن كن أولت حمل فأنفقوا عليهن حتى يضعن حملهن࣌ فإن ࡰرضعن لكم فاتوهن أجورهن واتمروا بينكم بمعروف࣌  وإن تعاسرتم فسترضع له أخرى࣌', NULL, 559, 'local:warsh-text.json')
insert into public.ayahs (id, riwayah, surah_number, ayah_number, text, simple_text, juz, page, source) values
  ('warsh-65-7', 'warsh', 65, 7, 'لِيُنفِقْ ذُو سَعَةࣲ مِّن سَعَتِهِۦ࣌ وَمَن قُدِرَ عَلَيْهِ رِزْقُهُۥ فَلْيُنفِقْ مِمَّآ ءَاتٜيٰهُ ࡲ۬للَّهُ࣌ لَا يُكَلِّفُ ࡲ۬للَّهُ نَفْساً ࡴلَّا مَآ ءَاتٜيٰهَا࣌ سَيَجْعَلُ ࡲ۬للَّهُ بَعْدَ عُسْرࣲ يُسْراࣰ࣌', 'لينفق ذو سعة من سعته࣌ ومن قدر عليه رزقه فلينفق مما ءاتيه ࡲلله࣌ لا يكلف ࡲلله نفسا ࡴلا ما ءاتيها࣌ سيجعل ࡲلله بعد عسر يسرا࣌', NULL, 559, 'local:warsh-text.json'),
  ('warsh-65-8', 'warsh', 65, 8, 'وَكَأَيِّن مِّن قَرْيَةٍ عَتَتْ عَنَ ࡰمْرِ رَبِّهَا وَرُسُلِهِۦ فَحَاسَبْنَٰهَا حِسَاباࣰ شَدِيداࣰ وَعَذَّبْنَٰهَا عَذَاباࣰ نُّكُراࣰ', 'وكأين من قرية عتت عن ࡰمر ربها ورسله فحاسبنها حسابا شديدا وعذبنها عذابا نكرا', NULL, 559, 'local:warsh-text.json'),
  ('warsh-65-9', 'warsh', 65, 9, 'فَذَاقَتْ وَبَالَ أَمْرِهَا࣌ وَكَانَ عَٰقِبَةُ أَمْرِهَا خُسْراً࣌', 'فذاقت وبال أمرها࣌ وكان عقبة أمرها خسرا࣌', NULL, 559, 'local:warsh-text.json'),
  ('warsh-65-10', 'warsh', 65, 10, 'ࡰعَدَّ ࡰ۬للَّهُ لَهُمْ عَذَاباࣰ شَدِيداࣰ࣌ فَاتَّقُواْ ࡲ۬للَّهَ يَٰٓأُوْلِے ࡴ۬لَالْبَٰبِ࣌ ࡴ۬لذِينَ ءَامَنُواْ قَدَ ࡰنزَلَ ࡰ۬للَّهُ إِلَيْكُمْ ذِكْراࣰ࣌', 'ࡰعد ࡰلله لهم عذابا شديدا࣌ فاتقوا ࡲلله يأولے ࡴلالبب࣌ ࡴلذين ءامنوا قد ࡰنزل ࡰلله إليكم ذكرا࣌', NULL, 559, 'local:warsh-text.json'),
  ('warsh-65-11', 'warsh', 65, 11, 'رَّسُولاࣰ يَتْلُواْ عَلَيْكُمُۥٓ ءَايَٰتِ ࡴ۬للَّهِ مُبَيَّنَٰتࣲ لِّيُخْرِجَ ࡰ۬لذِينَ ءَامَنُواْ وَعَمِلُواْ ࡲ۬لصَّٰلِحَٰتِ مِنَ ࡰ۬لظُّلُمَٰتِ إِلَى ࡰ۬لنُّورِ࣌ وَمَنْ يُّومِنۢ بِاللَّهِ وَيَعْمَلْ صَٰلِحاࣰ نُّدْخِلْهُ جَنَّٰتࣲ تَجْرِے مِن تَحْتِهَا ࡰ۬لَانْهَٰرُ خَٰلِدِينَ فِيهَآ أَبَداࣰ قَدَ ࡰحْسَنَ ࡰ۬للَّهُ لَهُۥ رِزْقاً࣌', 'رسولا يتلوا عليكم ءايت ࡴلله مبينت ليخرج ࡰلذين ءامنوا وعملوا ࡲلصلحت من ࡰلظلمت إلى ࡰلنور࣌ ومن يومن بالله ويعمل صلحا ندخله جنت تجرے من تحتها ࡰلانهر خلدين فيها أبدا قد ࡰحسن ࡰلله له رزقا࣌', NULL, 559, 'local:warsh-text.json'),
  ('warsh-65-12', 'warsh', 65, 12, 'ࡴ۬للَّهُ ࡲ۬لذِے خَلَقَ سَبْعَ سَمَٰوَٰتࣲ وَمِنَ ࡰ۬لَارْضِ مِثْلَهُنَّ࣌ يَتَنَزَّلُ ࡲ۬لَامْرُ بَيْنَهُنَّ لِتَعْلَمُوٓاْ أَنَّ ࡰ۬للَّهَ عَلَىٰ كُلِّ شَےْءࣲ قَدِيرࣱ وَأَنَّ ࡰ۬للَّهَ قَدَ ࡰحَاطَ بِكُلِّ شَےْءٍ عِلْماࣰ࣌', 'ࡴلله ࡲلذے خلق سبع سموت ومن ࡰلارض مثلهن࣌ يتنزل ࡲلامر بينهن لتعلموا أن ࡰلله على كل شےء قدير وأن ࡰلله قد ࡰحاط بكل شےء علما࣌', NULL, 559, 'local:warsh-text.json'),
  ('warsh-66-1', 'warsh', 66, 1, 'يَٰٓأَيُّهَا‏ ࡰ۬لنَّبِےٓءُ لِمَ تُحَرِّمُ مَآ أَحَلَّ ࡰ۬للَّهُ لَكَ تَبْتَغِے مَرْضَاتَ أَزْوَٰجِكَ࣌ وَاللَّهُ غَفُورࣱ رَّحِيمࣱ࣌', 'يأيها‏ ࡰلنبےء لم تحرم ما أحل ࡰلله لك تبتغے مرضات أزوجك࣌ والله غفور رحيم࣌', NULL, 560, 'local:warsh-text.json'),
  ('warsh-66-2', 'warsh', 66, 2, 'قَدْ فَرَضَ ࡰ۬للَّهُ لَكُمْ تَحِلَّةَ أَيْمَٰنِكُمْ࣌ وَاللَّهُ مَوْلٜيٰكُمْ࣌ وَهُوَ ࡰ۬لْعَلِيمُ ࡲ۬لْحَكِيمُ࣌', 'قد فرض ࡰلله لكم تحلة أيمنكم࣌ والله موليكم࣌ وهو ࡰلعليم ࡲلحكيم࣌', NULL, 560, 'local:warsh-text.json'),
  ('warsh-66-3', 'warsh', 66, 3, 'وَإِذَ ࡰسَرَّ‏ ࡰ۬لنَّبِےٓءُ ࡹِلَىٰ بَعْضِ أَزْوَٰجِهِۦ حَدِيثاࣰ࣌ فَلَمَّا نَبَّأَتْ بِهِۦ وَأَظْهَرَهُ ࡲ۬للَّهُ عَلَيْهِ عَرَّفَ بَعْضَهُۥ وَأَعْرَضَ عَنۢ بَعْضࣲ࣌ فَلَمَّا نَبَّأَهَا بِهِۦ قَالَتْ مَنَ ࡰنۢبَأَكَ هَٰذَا قَالَ نَبَّأَنِيَ ࡰ۬لْعَلِيمُ ࡲ۬لْخَبِيرُ࣌', 'وإذ ࡰسر‏ ࡰلنبےء ࡹلى بعض أزوجه حديثا࣌ فلما نبأت به وأظهره ࡲلله عليه عرف بعضه وأعرض عن بعض࣌ فلما نبأها به قالت من ࡰنبأك هذا قال نبأني ࡰلعليم ࡲلخبير࣌', NULL, 560, 'local:warsh-text.json'),
  ('warsh-66-4', 'warsh', 66, 4, 'إِن تَتُوبَآ إِلَى ࡰ۬للَّهِ فَقَدْ صَغَتْ قُلُوبُكُمَا࣌ وَإِن تَظَّٰهَرَا عَلَيْهِ فَإِنَّ ࡰ۬للَّهَ هُوَ مَوْلٜيٰهُ وَجِبْرِيلُ وَصَٰلِحُ ࡲ۬لْمُومِنِينَ࣌ وَالْمَلَٰٓئِكَةُ بَعْدَ ذَٰلِكَ ظَهِيرٌ࣌', 'إن تتوبا إلى ࡰلله فقد صغت قلوبكما࣌ وإن تظهرا عليه فإن ࡰلله هو موليه وجبريل وصلح ࡲلمومنين࣌ والملئكة بعد ذلك ظهير࣌', NULL, 560, 'local:warsh-text.json'),
  ('warsh-66-5', 'warsh', 66, 5, 'عَسٜىٰ رَبُّهُۥٓ إِن طَلَّقَكُنَّ أَنْ يُّبَدِّلَهُۥٓ أَزْوَٰجاً خَيْراࣰ مِّنكُنَّ مُسْلِمَٰتࣲ مُّومِنَٰتࣲ قَٰنِتَٰتࣲ تَٰٓئِبَٰتٍ عَٰبِدَٰتࣲ سَٰٓئِحَٰتࣲ ثَيِّبَٰتࣲ وَأَبْكَاراࣰ࣌', 'عسى ربه إن طلقكن أن يبدله أزوجا خيرا منكن مسلمت مومنت قنتت تئبت عبدت سئحت ثيبت وأبكارا࣌', NULL, 560, 'local:warsh-text.json'),
  ('warsh-66-6', 'warsh', 66, 6, 'يَٰٓأَيُّهَا ࡰ۬لذِينَ ءَامَنُواْ قُوٓاْ أَنفُسَكُمْ وَأَهْلِيكُمْ نَاراࣰ وَقُودُهَا ࡰ۬لنَّاسُ وَالْحِجَارَةُ عَلَيْهَا مَلَٰٓئِكَةٌ غِلَٰظࣱ شِدَادࣱ لَّا يَعْصُونَ ࡰ۬للَّهَ مَآ أَمَرَهُمْ وَيَفْعَلُونَ مَا يُومَرُونَ࣌', 'يأيها ࡰلذين ءامنوا قوا أنفسكم وأهليكم نارا وقودها ࡰلناس والحجارة عليها ملئكة غلظ شداد لا يعصون ࡰلله ما أمرهم ويفعلون ما يومرون࣌', NULL, 560, 'local:warsh-text.json'),
  ('warsh-66-7', 'warsh', 66, 7, 'يَٰٓأَيُّهَا ࡰ۬لذِينَ كَفَرُواْ لَا تَعْتَذِرُواْ ࡲ۬لْيَوْمَ إِنَّمَا تُجْزَوْنَ مَا كُنتُمْ تَعْمَلُونَ࣌', 'يأيها ࡰلذين كفروا لا تعتذروا ࡲليوم إنما تجزون ما كنتم تعملون࣌', NULL, 560, 'local:warsh-text.json'),
  ('warsh-66-8', 'warsh', 66, 8, '۞ يَٰٓأَيُّهَا ࡰ۬لذِينَ ءَامَنُواْ تُوبُوٓاْ إِلَى ࡰ۬للَّهِ تَوْبَةࣰ نَّصُوحاً عَسٜىٰ رَبُّكُمُۥٓ أَنْ يُّكَفِّرَ عَنكُمْ سَيِّـَٔاتِكُمْ وَيُدْخِلَكُمْ جَنَّٰتࣲ تَجْرِے مِن تَحْتِهَا ࡰ۬لَانْهَٰرُ يَوْمَ لَا يُخْزِے ࡴ۬للَّهُ ࡲ۬لنَّبِےٓءَ وَالذِينَ ءَامَنُواْ مَعَهُۥ نُورُهُمْ يَسْعٜىٰ بَيْنَ أَيْدِيهِمْ وَبِأَيْمَٰنِهِمْ࣌ يَقُولُونَ رَبَّنَآ أَتْمِمْ لَنَا نُورَنَا وَاغْفِرْ لَنَآ࣌ إِنَّكَ عَلَىٰ كُلِّ شَےْءࣲ قَدِيرࣱ࣌', 'يأيها ࡰلذين ءامنوا توبوا إلى ࡰلله توبة نصوحا عسى ربكم أن يكفر عنكم سياتكم ويدخلكم جنت تجرے من تحتها ࡰلانهر يوم لا يخزے ࡴلله ࡲلنبےء والذين ءامنوا معه نورهم يسعى بين أيديهم وبأيمنهم࣌ يقولون ربنا أتمم لنا نورنا واغفر لنا࣌ إنك على كل شےء قدير࣌', NULL, 561, 'local:warsh-text.json'),
  ('warsh-66-9', 'warsh', 66, 9, 'يَٰٓأَيُّهَا‏ ࡰ۬لنَّبِےٓءُ جَٰهِدِ ࡴ۬لْكُفَّارَ وَالْمُنَٰفِقِينَ وَاغْلُظْ عَلَيْهِمْ࣌ وَمَأْوٜيٰهُمْ جَهَنَّمُ࣌ وَبِيسَ ࡰ۬لْمَصِيرُ࣌', 'يأيها‏ ࡰلنبےء جهد ࡴلكفار والمنفقين واغلظ عليهم࣌ ومأويهم جهنم࣌ وبيس ࡰلمصير࣌', NULL, 561, 'local:warsh-text.json'),
  ('warsh-66-10', 'warsh', 66, 10, 'ضَرَبَ ࡰ۬للَّهُ مَثَلاࣰ لِّلذِينَ كَفَرُواْ ࡲٜمْرَأَتَ نُوحࣲ وَامْرَأَتَ لُوطࣲ࣌ كَانَتَا تَحْتَ عَبْدَيْنِ مِنْ عِبَادِنَا صَالِحَيْنِ فَخَانَتَٰهُمَا فَلَمْ يُغْنِيَا عَنْهُمَا مِنَ ࡰ۬للَّهِ شَيْـٔاࣰ࣌ وَقِيلَ ࡸَدْخُلَا ࡰ۬لنَّارَ مَعَ ࡰ۬لدَّٰخِلِينَ࣌', 'ضرب ࡰلله مثلا للذين كفروا ࡲمرأت نوح وامرأت لوط࣌ كانتا تحت عبدين من عبادنا صالحين فخانتهما فلم يغنيا عنهما من ࡰلله شيا࣌ وقيل ࡸدخلا ࡰلنار مع ࡰلدخلين࣌', NULL, 561, 'local:warsh-text.json'),
  ('warsh-66-11', 'warsh', 66, 11, 'وَضَرَبَ ࡰ۬للَّهُ مَثَلاࣰ لِّلذِينَ ءَامَنُواْ ࡲٜمْرَأَتَ فِرْعَوْنَ إِذْ قَالَتْ رَبِّ ࡴٜبْنِ لِے عِندَكَ بَيْتاࣰ فِے ࡴ۬لْجَنَّةِ وَنَجِّنِے مِن فِرْعَوْنَ وَعَمَلِهِۦ وَنَجِّنِے مِنَ ࡰ۬لْقَوْمِ ࡴ۬لظَّٰلِمِينَ࣌', 'وضرب ࡰلله مثلا للذين ءامنوا ࡲمرأت فرعون إذ قالت رب ࡴبن لے عندك بيتا فے ࡴلجنة ونجنے من فرعون وعمله ونجنے من ࡰلقوم ࡴلظلمين࣌', NULL, 561, 'local:warsh-text.json'),
  ('warsh-66-12', 'warsh', 66, 12, 'وَمَرْيَمَ ࡰٜبْنَتَ عِمْرَٰنَ ࡰ۬لتِےٓ أَحْصَنَتْ فَرْجَهَا فَنَفَخْنَا فِيهِ مِن رُّوحِنَا وَصَدَّقَتْ بِكَلِمَٰتِ رَبِّهَا وَكِتَٰبِهِۦ وَكَانَتْ مِنَ ࡰ۬لْقَٰنِتِينَ࣌', 'ومريم ࡰبنت عمرن ࡰلتے أحصنت فرجها فنفخنا فيه من روحنا وصدقت بكلمت ربها وكتبه وكانت من ࡰلقنتين࣌', NULL, 561, 'local:warsh-text.json'),
  ('warsh-67-1', 'warsh', 67, 1, 'تَبَٰرَكَ ࡰ۬لذِے بِيَدِهِ ࡴ۬لْمُلْكُ وَهُوَ عَلَىٰ كُلِّ شَےْءࣲ قَدِيرٌ࣌', 'تبرك ࡰلذے بيده ࡴلملك وهو على كل شےء قدير࣌', NULL, 562, 'local:warsh-text.json'),
  ('warsh-67-2', 'warsh', 67, 2, 'ࡴ۬لذِے خَلَقَ ࡰ۬لْمَوْتَ وَالْحَيَوٰةَ لِيَبْلُوَكُمُۥٓ أَيُّكُمُۥٓ أَحْسَنُ عَمَلاࣰ࣌ وَهُوَ ࡰ۬لْعَزِيزُ ࡲ۬لْغَفُورُ࣌', 'ࡴلذے خلق ࡰلموت والحيوة ليبلوكم أيكم أحسن عملا࣌ وهو ࡰلعزيز ࡲلغفور࣌', NULL, 562, 'local:warsh-text.json'),
  ('warsh-67-3', 'warsh', 67, 3, 'ࡲ۬لذِے خَلَقَ سَبْعَ سَمَٰوَٰتࣲ طِبَاقاࣰ࣌ مَّا تَرٜىٰ فِے خَلْقِ ࡴ۬لرَّحْمَٰنِ مِن تَفَٰوُتࣲ࣌ فَارْجِعِ ࡴ۬لْبَصَرَ هَلْ تَرٜىٰ مِن فُطُورࣲ࣌', 'ࡲلذے خلق سبع سموت طباقا࣌ ما ترى فے خلق ࡴلرحمن من تفوت࣌ فارجع ࡴلبصر هل ترى من فطور࣌', NULL, 562, 'local:warsh-text.json'),
  ('warsh-67-4', 'warsh', 67, 4, 'ثُمَّ ࡰٜرْجِعِ ࡴ۬لْبَصَرَ كَرَّتَيْنِ يَنقَلِبِ ࡴلَيْكَ ࡰ۬لْبَصَرُ خَاسِئاࣰ وَهُوَ حَسِيرࣱ࣌', 'ثم ࡰرجع ࡴلبصر كرتين ينقلب ࡴليك ࡰلبصر خاسئا وهو حسير࣌', NULL, 562, 'local:warsh-text.json'),
  ('warsh-67-5', 'warsh', 67, 5, 'وَلَقَدْ زَيَّنَّا ࡰ۬لسَّمَآءَ ࡰ۬لدُّنْيٜا بِمَصَٰبِيحَ وَجَعَلْنَٰهَا رُجُوماࣰ لِّلشَّيَٰطِينِ وَأَعْتَدْنَا لَهُمْ عَذَابَ ࡰ۬لسَّعِيرِ࣌', 'ولقد زينا ࡰلسماء ࡰلدنيا بمصبيح وجعلنها رجوما للشيطين وأعتدنا لهم عذاب ࡰلسعير࣌', NULL, 562, 'local:warsh-text.json'),
  ('warsh-67-6', 'warsh', 67, 6, 'وَلِلذِينَ كَفَرُواْ بِرَبِّهِمْ عَذَابُ جَهَنَّمَ࣌ وَبِيسَ ࡰ۬لْمَصِيرُ࣌', 'وللذين كفروا بربهم عذاب جهنم࣌ وبيس ࡰلمصير࣌', NULL, 562, 'local:warsh-text.json'),
  ('warsh-67-7', 'warsh', 67, 7, 'إِذَآ أُلْقُواْ فِيهَا سَمِعُواْ لَهَا شَهِيقاࣰ وَهِيَ تَفُورُ', 'إذا ألقوا فيها سمعوا لها شهيقا وهي تفور', NULL, 562, 'local:warsh-text.json'),
  ('warsh-67-8', 'warsh', 67, 8, 'تَكَادُ تَمَيَّزُ مِنَ ࡰ۬لْغَيْظِ࣌ كُلَّمَآ أُلْقِيَ فِيهَا فَوْجࣱ سَأَلَهُمْ خَزَنَتُهَآ أَلَمْ يَاتِكُمْ نَذِيرࣱ࣌', 'تكاد تميز من ࡰلغيظ࣌ كلما ألقي فيها فوج سألهم خزنتها ألم ياتكم نذير࣌', NULL, 562, 'local:warsh-text.json'),
  ('warsh-67-9', 'warsh', 67, 9, 'قَالُواْ بَلٜىٰ قَدْ جَآءَنَا نَذِيرࣱ', 'قالوا بلى قد جاءنا نذير', NULL, 562, 'local:warsh-text.json'),
  ('warsh-67-10', 'warsh', 67, 10, 'فَكَذَّبْنَا وَقُلْنَا مَا نَزَّلَ ࡰ۬للَّهُ مِن شَےْءٍ ࡴنَ ࡰنتُمُۥٓ إِلَّا فِے ضَلَٰلࣲ كَبِيرࣲ࣌', 'فكذبنا وقلنا ما نزل ࡰلله من شےء ࡴن ࡰنتم إلا فے ضلل كبير࣌', NULL, 562, 'local:warsh-text.json'),
  ('warsh-67-11', 'warsh', 67, 11, 'وَقَالُواْ لَوْ كُنَّا نَسْمَعُ أَوْ نَعْقِلُ مَا كُنَّا فِےٓ أَصْحَٰبِ ࡴ۬لسَّعِيرِ࣌', 'وقالوا لو كنا نسمع أو نعقل ما كنا فے أصحب ࡴلسعير࣌', NULL, 562, 'local:warsh-text.json'),
  ('warsh-67-12', 'warsh', 67, 12, 'فَاعْتَرَفُواْ بِذَنۢبِهِمْ࣌ فَسُحْقاࣰ لِّأَصْحَٰبِ ࡴ۬لسَّعِيرِ࣌', 'فاعترفوا بذنبهم࣌ فسحقا لأصحب ࡴلسعير࣌', NULL, 562, 'local:warsh-text.json'),
  ('warsh-67-13', 'warsh', 67, 13, 'إِنَّ ࡰ۬لذِينَ يَخْشَوْنَ رَبَّهُم بِالْغَيْبِ لَهُم مَّغْفِرَةࣱ وَأَجْرࣱ كَبِيرࣱ࣌', 'إن ࡰلذين يخشون ربهم بالغيب لهم مغفرة وأجر كبير࣌', NULL, 562, 'local:warsh-text.json'),
  ('warsh-67-14', 'warsh', 67, 14, 'وَأَسِرُّواْ قَوْلَكُمُۥٓ أَوِ ࡴٜجْهَرُواْ بِهِۦٓ࣌ إِنَّهُۥ عَلِيمُۢ بِذَاتِ ࡴ۬لصُّدُورِ࣌', 'وأسروا قولكم أو ࡴجهروا به࣌ إنه عليم بذات ࡴلصدور࣌', NULL, 563, 'local:warsh-text.json'),
  ('warsh-67-15', 'warsh', 67, 15, 'أَلَا يَعْلَمُ مَنْ خَلَقَ وَهُوَ ࡰ۬للَّطِيفُ ࡲ۬لْخَبِيرُ࣌', 'ألا يعلم من خلق وهو ࡰللطيف ࡲلخبير࣌', NULL, 563, 'local:warsh-text.json'),
  ('warsh-67-16', 'warsh', 67, 16, 'هُوَ ࡰ۬لذِے جَعَلَ لَكُمُ ࡲ۬لَارْضَ ذَلُولاࣰ فَامْشُواْ فِے مَنَاكِبِهَا وَكُلُواْ مِن رِّزْقِهِۦ࣌ وَإِلَيْهِ ࡴ۬لنُّشُورُ࣌', 'هو ࡰلذے جعل لكم ࡲلارض ذلولا فامشوا فے مناكبها وكلوا من رزقه࣌ وإليه ࡴلنشور࣌', NULL, 563, 'local:warsh-text.json'),
  ('warsh-67-17', 'warsh', 67, 17, 'ءَامِنتُم مَّن فِے ࡴ۬لسَّمَآءِ ࡶَنْ يَّخْسِفَ بِكُمُ ࡲ۬لَارْضَ فَإِذَا هِيَ تَمُورُ࣌', 'ءامنتم من فے ࡴلسماء ࡶن يخسف بكم ࡲلارض فإذا هي تمور࣌', NULL, 563, 'local:warsh-text.json'),
  ('warsh-67-18', 'warsh', 67, 18, 'أَمَ ࡰمِنتُم مَّن فِے ࡴ۬لسَّمَآءِ ࡶَنْ يُّرْسِلَ عَلَيْكُمْ حَاصِباࣰ࣌ فَسَتَعْلَمُونَ كَيْفَ نَذِيرِۦ࣌', 'أم ࡰمنتم من فے ࡴلسماء ࡶن يرسل عليكم حاصبا࣌ فستعلمون كيف نذير࣌', NULL, 563, 'local:warsh-text.json'),
  ('warsh-67-19', 'warsh', 67, 19, 'وَلَقَدْ كَذَّبَ ࡰ۬لذِينَ مِن قَبْلِهِمْ࣌ فَكَيْفَ كَانَ نَكِيرِۦٓ࣌', 'ولقد كذب ࡰلذين من قبلهم࣌ فكيف كان نكير࣌', NULL, 563, 'local:warsh-text.json'),
  ('warsh-67-20', 'warsh', 67, 20, '۞ أَوَلَمْ يَرَوِاْ ࡴلَى ࡰ۬لطَّيْرِ فَوْقَهُمْ صَٰٓفَّٰتࣲ وَيَقْبِضْنَ࣌ مَا يُمْسِكُهُنَّ إِلَّا ࡰ۬لرَّحْمَٰنُ࣌ إِنَّهُۥ بِكُلِّ شَےْءِۢ بَصِيرٌ࣌', 'أولم يروا ࡴلى ࡰلطير فوقهم صفت ويقبضن࣌ ما يمسكهن إلا ࡰلرحمن࣌ إنه بكل شےء بصير࣌', NULL, 563, 'local:warsh-text.json'),
  ('warsh-67-21', 'warsh', 67, 21, 'ࡰمَّنْ هَٰذَا ࡰ۬لذِے هُوَ جُندࣱ لَّكُمْ يَنصُرُكُم مِّن دُونِ ࡴ۬لرَّحْمَٰنِ࣌ إِنِ ࡴ۬لْكَٰفِرُونَ إِلَّا فِے غُرُورٍ࣌', 'ࡰمن هذا ࡰلذے هو جند لكم ينصركم من دون ࡴلرحمن࣌ إن ࡴلكفرون إلا فے غرور࣌', NULL, 563, 'local:warsh-text.json'),
  ('warsh-67-22', 'warsh', 67, 22, 'ࡰمَّنْ هَٰذَا ࡰ۬لذِے يَرْزُقُكُمُۥٓ إِنَ ࡰمْسَكَ رِزْقَهُۥ࣌ بَل لَّجُّواْ فِے عُتُوࣲّ وَنُفُورٍ࣌', 'ࡰمن هذا ࡰلذے يرزقكم إن ࡰمسك رزقه࣌ بل لجوا فے عتو ونفور࣌', NULL, 563, 'local:warsh-text.json'),
  ('warsh-67-23', 'warsh', 67, 23, 'ࡰفَمَنْ يَّمْشِے مُكِبّاً عَلَىٰ وَجْهِهِۦٓ أَهْدٜىٰٓ أَمَّنْ يَّمْشِے سَوِيّاً عَلَىٰ صِرَٰطࣲ مُّسْتَقِيمࣲ࣌', 'ࡰفمن يمشے مكبا على وجهه أهدى أمن يمشے سويا على صرط مستقيم࣌', NULL, 563, 'local:warsh-text.json'),
  ('warsh-67-24', 'warsh', 67, 24, 'قُلْ هُوَ ࡰ۬لذِےٓ أَنشَأَكُمْ وَجَعَلَ لَكُمُ ࡲ۬لسَّمْعَ وَالَابْصَٰرَ وَالَافْـِٕدَةَ࣌ قَلِيلاࣰ مَّا تَشْكُرُونَ࣌', 'قل هو ࡰلذے أنشأكم وجعل لكم ࡲلسمع والابصر والافدة࣌ قليلا ما تشكرون࣌', NULL, 563, 'local:warsh-text.json'),
  ('warsh-67-25', 'warsh', 67, 25, 'قُلْ هُوَ ࡰ۬لذِے ذَرَأَكُمْ فِے ࡴ۬لَارْضِ وَإِلَيْهِ تُحْشَرُونَ࣌', 'قل هو ࡰلذے ذرأكم فے ࡴلارض وإليه تحشرون࣌', NULL, 563, 'local:warsh-text.json'),
  ('warsh-67-26', 'warsh', 67, 26, 'وَيَقُولُونَ مَتٜىٰ هَٰذَا ࡰ۬لْوَعْدُ إِن كُنتُمْ صَٰدِقِينَ࣌', 'ويقولون متى هذا ࡰلوعد إن كنتم صدقين࣌', NULL, 563, 'local:warsh-text.json'),
  ('warsh-67-27', 'warsh', 67, 27, 'قُلِ ࡴنَّمَا ࡰ۬لْعِلْمُ عِندَ ࡰ۬للَّهِ وَإِنَّمَآ أَنَا نَذِيرࣱ مُّبِينࣱ࣌', 'قل ࡴنما ࡰلعلم عند ࡰلله وإنما أنا نذير مبين࣌', NULL, 563, 'local:warsh-text.json'),
  ('warsh-67-28', 'warsh', 67, 28, 'فَلَمَّا رَأَوْهُ زُلْفَةࣰ س۬يٓـَٔتْ وُجُوهُ ࡲ۬لذِينَ كَفَرُواْ وَقِيلَ هَٰذَا ࡰ۬لذِے كُنتُم بِهِۦ تَدَّعُونَ࣌', 'فلما رأوه زلفة سيت وجوه ࡲلذين كفروا وقيل هذا ࡰلذے كنتم به تدعون࣌', NULL, 564, 'local:warsh-text.json'),
  ('warsh-67-29', 'warsh', 67, 29, 'قُلَ ࡰرَٰٓيْتُمُۥٓ إِنَ ࡰهْلَكَنِيَ ࡰ۬للَّهُ وَمَن مَّعِيَ أَوْ رَحِمَنَا فَمَنْ يُّجِيرُ ࡲ۬لْكٜـٰفِرِينَ مِنْ عَذَابٍ ࡰلِيمࣲ࣌', 'قل ࡰريتم إن ࡰهلكني ࡰلله ومن معي أو رحمنا فمن يجير ࡲلكفرين من عذاب ࡰليم࣌', NULL, 564, 'local:warsh-text.json'),
  ('warsh-67-30', 'warsh', 67, 30, 'قُلْ هُوَ ࡰ۬لرَّحْمَٰنُ ءَامَنَّا بِهِۦ وَعَلَيْهِ تَوَكَّلْنَا࣌ فَسَتَعْلَمُونَ مَنْ هُوَ فِے ضَلَٰلࣲ مُّبِينࣲ࣌', 'قل هو ࡰلرحمن ءامنا به وعليه توكلنا࣌ فستعلمون من هو فے ضلل مبين࣌', NULL, 564, 'local:warsh-text.json'),
  ('warsh-67-31', 'warsh', 67, 31, 'قُلَ ࡰرَٰٓيْتُمُۥٓ إِنَ ࡰصْبَحَ مَآؤُكُمْ غَوْراࣰ فَمَنْ يَّاتِيكُم بِمَآءࣲ مَّعِينࣲ࣌', 'قل ࡰريتم إن ࡰصبح ماؤكم غورا فمن ياتيكم بماء معين࣌', NULL, 564, 'local:warsh-text.json'),
  ('warsh-68-1', 'warsh', 68, 1, 'نُّٓ࣌ وَالْقَلَمِ وَمَا يَسْطُرُونَ', 'ن࣌ والقلم وما يسطرون', NULL, 564, 'local:warsh-text.json'),
  ('warsh-68-2', 'warsh', 68, 2, 'مَآ أَنتَ بِنِعْمَةِ رَبِّكَ بِمَجْنُونࣲ', 'ما أنت بنعمة ربك بمجنون', NULL, 564, 'local:warsh-text.json'),
  ('warsh-68-3', 'warsh', 68, 3, 'وَإِنَّ لَكَ لَأَجْراً غَيْرَ مَمْنُونࣲ', 'وإن لك لأجرا غير ممنون', NULL, 564, 'local:warsh-text.json'),
  ('warsh-68-4', 'warsh', 68, 4, 'وَإِنَّكَ لَعَلَىٰ خُلُقٍ عَظِيمࣲ࣌', 'وإنك لعلى خلق عظيم࣌', NULL, 564, 'local:warsh-text.json'),
  ('warsh-68-5', 'warsh', 68, 5, 'فَسَتُبْصِرُ وَيُبْصِرُونَ', 'فستبصر ويبصرون', NULL, 564, 'local:warsh-text.json'),
  ('warsh-68-6', 'warsh', 68, 6, 'بِأَييِّكُمُ ࡲ۬لْمَفْتُونُ࣌', 'بأييكم ࡲلمفتون࣌', NULL, 564, 'local:warsh-text.json'),
  ('warsh-68-7', 'warsh', 68, 7, 'إِنَّ رَبَّكَ هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِۦ࣌ وَهُوَ أَعْلَمُ بِالْمُهْتَدِينَ࣌', 'إن ربك هو أعلم بمن ضل عن سبيله࣌ وهو أعلم بالمهتدين࣌', NULL, 564, 'local:warsh-text.json'),
  ('warsh-68-8', 'warsh', 68, 8, 'فَلَا تُطِعِ ࡴ۬لْمُكَذِّبِينَ࣌', 'فلا تطع ࡴلمكذبين࣌', NULL, 564, 'local:warsh-text.json'),
  ('warsh-68-9', 'warsh', 68, 9, 'وَدُّواْ لَوْ تُدْهِنُ فَيُدْهِنُونَ࣌', 'ودوا لو تدهن فيدهنون࣌', NULL, 564, 'local:warsh-text.json'),
  ('warsh-68-10', 'warsh', 68, 10, 'وَلَا تُطِعْ كُلَّ حَلَّٰفࣲ مَّهِينٍ', 'ولا تطع كل حلف مهين', NULL, 564, 'local:warsh-text.json'),
  ('warsh-68-11', 'warsh', 68, 11, 'هَمَّازࣲ مَّشَّآءِۢ بِنَمِيمࣲ', 'هماز مشاء بنميم', NULL, 564, 'local:warsh-text.json'),
  ('warsh-68-12', 'warsh', 68, 12, 'مَّنَّاعࣲ لِّلْخَيْرِ مُعْتَدٍ ࡰثِيمٍ', 'مناع للخير معتد ࡰثيم', NULL, 564, 'local:warsh-text.json'),
  ('warsh-68-13', 'warsh', 68, 13, 'عُتُلِّۢ بَعْدَ ذَٰلِكَ زَنِيمٍ', 'عتل بعد ذلك زنيم', NULL, 564, 'local:warsh-text.json'),
  ('warsh-68-14', 'warsh', 68, 14, 'ࡰن كَانَ ذَا مَالࣲ وَبَنِينَ', 'ࡰن كان ذا مال وبنين', NULL, 564, 'local:warsh-text.json'),
  ('warsh-68-15', 'warsh', 68, 15, 'إِذَا تُتْلٜىٰ عَلَيْهِ ءَايَٰتُنَا قَالَ أَسَٰطِيرُ ࡲ۬لَاوَّلِينَ࣌', 'إذا تتلى عليه ءايتنا قال أسطير ࡲلاولين࣌', NULL, 564, 'local:warsh-text.json'),
  ('warsh-68-16', 'warsh', 68, 16, 'سَنَسِمُهُۥ عَلَى ࡰ۬لْخُرْطُومِ࣌', 'سنسمه على ࡰلخرطوم࣌', NULL, 564, 'local:warsh-text.json'),
  ('warsh-68-17', 'warsh', 68, 17, 'إِنَّا بَلَوْنَٰهُمْ كَمَا بَلَوْنَآ أَصْحَٰبَ ࡰ۬لْجَنَّةِ إِذَ ࡰقْسَمُواْ لَيَصْرِمُنَّهَا مُصْبِحِينَ', 'إنا بلونهم كما بلونا أصحب ࡰلجنة إذ ࡰقسموا ليصرمنها مصبحين', NULL, 565, 'local:warsh-text.json'),
  ('warsh-68-18', 'warsh', 68, 18, 'وَلَا يَسْتَثْنُونَ࣌', 'ولا يستثنون࣌', NULL, 565, 'local:warsh-text.json'),
  ('warsh-68-19', 'warsh', 68, 19, '۞ فَطَافَ عَلَيْهَا طَآئِفࣱ مِّن رَّبِّكَ وَهُمْ نَآئِمُونَ', 'فطاف عليها طائف من ربك وهم نائمون', NULL, 565, 'local:warsh-text.json'),
  ('warsh-68-20', 'warsh', 68, 20, 'فَأَصْبَحَتْ كَالصَّرِيمِ࣌', 'فأصبحت كالصريم࣌', NULL, 565, 'local:warsh-text.json'),
  ('warsh-68-21', 'warsh', 68, 21, 'فَتَنَادَوْاْ مُصْبِحِينَ', 'فتنادوا مصبحين', NULL, 565, 'local:warsh-text.json'),
  ('warsh-68-22', 'warsh', 68, 22, 'أَنُ ࡲ࢈غْدُواْ عَلَىٰ حَرْثِكُمُۥٓ إِن كُنتُمْ صَٰرِمِينَ࣌', 'أن ࡲ࢈غدوا على حرثكم إن كنتم صرمين࣌', NULL, 565, 'local:warsh-text.json'),
  ('warsh-68-23', 'warsh', 68, 23, 'فَانطَلَقُواْ وَهُمْ يَتَخَٰفَتُونَ', 'فانطلقوا وهم يتخفتون', NULL, 565, 'local:warsh-text.json'),
  ('warsh-68-24', 'warsh', 68, 24, 'أَن لَّا يَدْخُلَنَّهَا ࡰ۬لْيَوْمَ عَلَيْكُم مِّسْكِينࣱ࣌', 'أن لا يدخلنها ࡰليوم عليكم مسكين࣌', NULL, 565, 'local:warsh-text.json'),
  ('warsh-68-25', 'warsh', 68, 25, 'وَغَدَوْاْ عَلَىٰ حَرْدࣲ قَٰدِرِينَ࣌', 'وغدوا على حرد قدرين࣌', NULL, 565, 'local:warsh-text.json'),
  ('warsh-68-26', 'warsh', 68, 26, 'فَلَمَّا رَأَوْهَا قَالُوٓاْ إِنَّا لَضَآلُّونَ', 'فلما رأوها قالوا إنا لضالون', NULL, 565, 'local:warsh-text.json'),
  ('warsh-68-27', 'warsh', 68, 27, 'بَلْ نَحْنُ مَحْرُومُونَ࣌', 'بل نحن محرومون࣌', NULL, 565, 'local:warsh-text.json'),
  ('warsh-68-28', 'warsh', 68, 28, 'قَالَ أَوْسَطُهُمُۥٓ أَلَمَ ࡰقُل لَّكُمْ لَوْلَا تُسَبِّحُونَ࣌', 'قال أوسطهم ألم ࡰقل لكم لولا تسبحون࣌', NULL, 565, 'local:warsh-text.json'),
  ('warsh-68-29', 'warsh', 68, 29, 'قَالُواْ سُبْحَٰنَ رَبِّنَآ إِنَّا كُنَّا ظَٰلِمِينَ࣌', 'قالوا سبحن ربنا إنا كنا ظلمين࣌', NULL, 565, 'local:warsh-text.json'),
  ('warsh-68-30', 'warsh', 68, 30, 'فَأَقْبَلَ بَعْضُهُمْ عَلَىٰ بَعْضࣲ يَتَلَٰوَمُونَ࣌', 'فأقبل بعضهم على بعض يتلومون࣌', NULL, 565, 'local:warsh-text.json'),
  ('warsh-68-31', 'warsh', 68, 31, 'قَالُواْ يَٰوَيْلَنَآ إِنَّا كُنَّا طَٰغِينَ', 'قالوا يويلنا إنا كنا طغين', NULL, 565, 'local:warsh-text.json'),
  ('warsh-68-32', 'warsh', 68, 32, 'عَسٜىٰ رَبُّنَآ أَنْ يُّبَدِّلَنَا خَيْراࣰ مِّنْهَآ إِنَّآ إِلَىٰ رَبِّنَا رَٰغِبُونَ࣌', 'عسى ربنا أن يبدلنا خيرا منها إنا إلى ربنا رغبون࣌', NULL, 565, 'local:warsh-text.json'),
  ('warsh-68-33', 'warsh', 68, 33, 'كَذَٰلِكَ ࡰ۬لْعَذَابُ࣌ وَلَعَذَابُ ࡲ۬لَاخِرَةِ أَكْبَرُ لَوْ كَانُواْ يَعْلَمُونَ࣌', 'كذلك ࡰلعذاب࣌ ولعذاب ࡲلاخرة أكبر لو كانوا يعلمون࣌', NULL, 565, 'local:warsh-text.json'),
  ('warsh-68-34', 'warsh', 68, 34, 'إِنَّ لِلْمُتَّقِينَ عِندَ رَبِّهِمْ جَنَّٰتِ ࡴ۬لنَّعِيمِ࣌', 'إن للمتقين عند ربهم جنت ࡴلنعيم࣌', NULL, 565, 'local:warsh-text.json'),
  ('warsh-68-35', 'warsh', 68, 35, 'أَفَنَجْعَلُ ࡲ۬لْمُسْلِمِينَ كَالْمُجْرِمِينَ࣌', 'أفنجعل ࡲلمسلمين كالمجرمين࣌', NULL, 565, 'local:warsh-text.json'),
  ('warsh-68-36', 'warsh', 68, 36, 'مَا لَكُمْ࣌ كَيْفَ تَحْكُمُونَ࣌', 'ما لكم࣌ كيف تحكمون࣌', NULL, 565, 'local:warsh-text.json'),
  ('warsh-68-37', 'warsh', 68, 37, 'أَمْ لَكُمْ كِتَٰبࣱ فِيهِ تَدْرُسُونَ', 'أم لكم كتب فيه تدرسون', NULL, 565, 'local:warsh-text.json'),
  ('warsh-68-38', 'warsh', 68, 38, 'إِنَّ لَكُمْ فِيهِ لَمَا تَخَيَّرُونَ࣌', 'إن لكم فيه لما تخيرون࣌', NULL, 565, 'local:warsh-text.json'),
  ('warsh-68-39', 'warsh', 68, 39, 'أَمْ لَكُمُۥٓ أَيْمَٰنٌ عَلَيْنَا بَٰلِغَةٌ ࡴلَىٰ يَوْمِ ࡴ۬لْقِيَٰمَةِ إِنَّ لَكُمْ لَمَا تَحْكُمُونَ࣌', 'أم لكم أيمن علينا بلغة ࡴلى يوم ࡴلقيمة إن لكم لما تحكمون࣌', NULL, 565, 'local:warsh-text.json'),
  ('warsh-68-40', 'warsh', 68, 40, 'سَلْهُمُۥٓ أَيُّهُم بِذَٰلِكَ زَعِيمٌ࣌', 'سلهم أيهم بذلك زعيم࣌', NULL, 565, 'local:warsh-text.json'),
  ('warsh-68-41', 'warsh', 68, 41, 'ࡰمْ لَهُمْ شُرَكَآءُ فَلْيَاتُواْ بِشُرَكَآئِهِمُۥٓ إِن كَانُواْ صَٰدِقِينَ࣌', 'ࡰم لهم شركاء فلياتوا بشركائهم إن كانوا صدقين࣌', NULL, 565, 'local:warsh-text.json'),
  ('warsh-68-42', 'warsh', 68, 42, 'يَوْمَ يُكْشَفُ عَن سَاقࣲ وَيُدْعَوْنَ إِلَى ࡰ۬لسُّجُودِ فَلَا يَسْتَطِيعُونَ࣌', 'يوم يكشف عن ساق ويدعون إلى ࡰلسجود فلا يستطيعون࣌', NULL, 565, 'local:warsh-text.json'),
  ('warsh-68-43', 'warsh', 68, 43, 'خَٰشِعَةً ࡰبْصَٰرُهُمْ تَرْهَقُهُمْ ذِلَّةࣱ࣌ وَقَدْ كَانُواْ يُدْعَوْنَ إِلَى ࡰ۬لسُّجُودِ وَهُمْ سَٰلِمُونَ࣌', 'خشعة ࡰبصرهم ترهقهم ذلة࣌ وقد كانوا يدعون إلى ࡰلسجود وهم سلمون࣌', NULL, 566, 'local:warsh-text.json'),
  ('warsh-68-44', 'warsh', 68, 44, 'فَذَرْنِے وَمَنْ يُّكَذِّبُ بِهَٰذَا ࡰ۬لْحَدِيثِ࣌ سَنَسْتَدْرِجُهُم مِّنْ حَيْثُ لَا يَعْلَمُونَ', 'فذرنے ومن يكذب بهذا ࡰلحديث࣌ سنستدرجهم من حيث لا يعلمون', NULL, 566, 'local:warsh-text.json'),
  ('warsh-68-45', 'warsh', 68, 45, 'وَأُمْلِے لَهُمُۥٓ࣌ إِنَّ كَيْدِے مَتِينٌ࣌', 'وأملے لهم࣌ إن كيدے متين࣌', NULL, 566, 'local:warsh-text.json'),
  ('warsh-68-46', 'warsh', 68, 46, 'ࡰمْ تَسْـَٔلُهُمُۥٓ أَجْراࣰ فَهُم مِّن مَّغْرَمࣲ مُّثْقَلُونَ࣌', 'ࡰم تسلهم أجرا فهم من مغرم مثقلون࣌', NULL, 566, 'local:warsh-text.json'),
  ('warsh-68-47', 'warsh', 68, 47, 'أَمْ عِندَهُمُ ࡲ۬لْغَيْبُ فَهُمْ يَكْتُبُونَ࣌', 'أم عندهم ࡲلغيب فهم يكتبون࣌', NULL, 566, 'local:warsh-text.json'),
  ('warsh-68-48', 'warsh', 68, 48, '۞ فَاصْبِرْ لِحُكْمِ رَبِّكَ وَلَا تَكُن كَصَٰحِبِ ࡴ۬لْحُوتِ إِذْ نَادٜىٰ وَهُوَ مَكْظُومࣱ࣌', 'فاصبر لحكم ربك ولا تكن كصحب ࡴلحوت إذ نادى وهو مكظوم࣌', NULL, 566, 'local:warsh-text.json'),
  ('warsh-68-49', 'warsh', 68, 49, 'لَّوْلَآ أَن تَدَٰرَكَهُۥ نِعْمَةࣱ مِّن رَّبِّهِۦ لَنُبِذَ بِالْعَرَآءِ وَهُوَ مَذْمُومࣱ࣌', 'لولا أن تدركه نعمة من ربه لنبذ بالعراء وهو مذموم࣌', NULL, 566, 'local:warsh-text.json'),
  ('warsh-68-50', 'warsh', 68, 50, 'فَاجْتَبٜـٰهُ رَبُّهُۥ فَجَعَلَهُۥ مِنَ ࡰ۬لصَّٰلِحِينَ࣌', 'فاجتبه ربه فجعله من ࡰلصلحين࣌', NULL, 566, 'local:warsh-text.json'),
  ('warsh-68-51', 'warsh', 68, 51, 'وَإِنْ يَّكَادُ ࡲ۬لذِينَ كَفَرُواْ لَيَزْلِقُونَكَ بِأَبْصٜـٰرِهِمْ لَمَّا سَمِعُواْ ࡲ۬لذِّكْرَ وَيَقُولُونَ إِنَّهُۥ لَمَجْنُونࣱ࣌', 'وإن يكاد ࡲلذين كفروا ليزلقونك بأبصرهم لما سمعوا ࡲلذكر ويقولون إنه لمجنون࣌', NULL, 566, 'local:warsh-text.json'),
  ('warsh-68-52', 'warsh', 68, 52, 'وَمَا هُوَ إِلَّا ذِكْرࣱ لِّلْعَٰلَمِينَ࣌', 'وما هو إلا ذكر للعلمين࣌', NULL, 566, 'local:warsh-text.json'),
  ('warsh-69-1', 'warsh', 69, 1, 'ࡰ۬لْحَآقَّةُ مَا ࡰ۬لْحَآقَّةُ࣌', 'ࡰلحاقة ما ࡰلحاقة࣌', NULL, 566, 'local:warsh-text.json'),
  ('warsh-69-2', 'warsh', 69, 2, 'وَمَآ أَدْرٜيٰكَ مَا ࡰ۬لْحَآقَّةُ࣌', 'وما أدريك ما ࡰلحاقة࣌', NULL, 566, 'local:warsh-text.json'),
  ('warsh-69-3', 'warsh', 69, 3, 'كَذَّبَتْ ثَمُودُ وَعَادُۢ بِالْقَارِعَةِ࣌', 'كذبت ثمود وعاد بالقارعة࣌', NULL, 566, 'local:warsh-text.json'),
  ('warsh-69-4', 'warsh', 69, 4, 'فَأَمَّا ثَمُودُ فَأُهْلِكُواْ بِالطَّاغِيَةِ࣌', 'فأما ثمود فأهلكوا بالطاغية࣌', NULL, 566, 'local:warsh-text.json'),
  ('warsh-69-5', 'warsh', 69, 5, 'وَأَمَّا عَادࣱ فَأُهْلِكُواْ بِرِيحࣲ صَرْصَرٍ عَاتِيَةࣲ', 'وأما عاد فأهلكوا بريح صرصر عاتية', NULL, 566, 'local:warsh-text.json'),
  ('warsh-69-6', 'warsh', 69, 6, 'سَخَّرَهَا عَلَيْهِمْ سَبْعَ لَيَالࣲ وَثَمَٰنِيَةَ أَيَّامٍ حُسُوماࣰ࣌ فَتَرَى ࡰ۬لْقَوْمَ فِيهَا صَرْعٜىٰ كَأَنَّهُمُۥٓ أَعْجَازُ نَخْلٍ خَاوِيَةࣲ࣌', 'سخرها عليهم سبع ليال وثمنية أيام حسوما࣌ فترى ࡰلقوم فيها صرعى كأنهم أعجاز نخل خاوية࣌', NULL, 566, 'local:warsh-text.json'),
  ('warsh-69-7', 'warsh', 69, 7, 'فَهَلْ تَرٜىٰ لَهُم مِّنۢ بَاقِيَةࣲ࣌', 'فهل ترى لهم من باقية࣌', NULL, 566, 'local:warsh-text.json'),
  ('warsh-69-8', 'warsh', 69, 8, 'وَجَآءَ فِرْعَوْنُ وَمَن قَبْلَهُۥ وَالْمُوتَفِكَٰتُ بِالْخَاطِئَةِ', 'وجاء فرعون ومن قبله والموتفكت بالخاطئة', NULL, 567, 'local:warsh-text.json'),
  ('warsh-69-9', 'warsh', 69, 9, 'فَعَصَوْاْ رَسُولَ رَبِّهِمْ فَأَخَذَهُمُۥٓ أَخْذَةࣰ رَّابِيَةً࣌', 'فعصوا رسول ربهم فأخذهم أخذة رابية࣌', NULL, 567, 'local:warsh-text.json'),
  ('warsh-69-10', 'warsh', 69, 10, 'ࡴنَّا لَمَّا طَغَا ࡰ۬لْمَآءُ حَمَلْنَٰكُمْ فِے ࡴ۬لْجَارِيَةِ', 'ࡴنا لما طغا ࡰلماء حملنكم فے ࡴلجارية', NULL, 567, 'local:warsh-text.json'),
  ('warsh-69-11', 'warsh', 69, 11, 'لِنَجْعَلَهَا لَكُمْ تَذْكِرَةࣰ وَتَعِيَهَآ أُذْنࣱ وَٰعِيَةࣱ࣌', 'لنجعلها لكم تذكرة وتعيها أذن وعية࣌', NULL, 567, 'local:warsh-text.json'),
  ('warsh-69-12', 'warsh', 69, 12, 'فَإِذَا نُفِخَ فِے ࡴ۬لصُّورِ نَفْخَةࣱ وَٰحِدَةࣱ', 'فإذا نفخ فے ࡴلصور نفخة وحدة', NULL, 567, 'local:warsh-text.json'),
  ('warsh-69-13', 'warsh', 69, 13, 'وَحُمِلَتِ ࡴ۬لَارْضُ وَالْجِبَالُ فَدُكَّتَا دَكَّةࣰ وَٰحِدَةࣰ', 'وحملت ࡴلارض والجبال فدكتا دكة وحدة', NULL, 567, 'local:warsh-text.json'),
  ('warsh-69-14', 'warsh', 69, 14, 'فَيَوْمَئِذࣲ وَقَعَتِ ࡴ۬لْوَاقِعَةُ', 'فيومئذ وقعت ࡴلواقعة', NULL, 567, 'local:warsh-text.json'),
  ('warsh-69-15', 'warsh', 69, 15, 'وَانشَقَّتِ ࡴ۬لسَّمَآءُ فَهِيَ يَوْمَئِذࣲ وَاهِيَةࣱ', 'وانشقت ࡴلسماء فهي يومئذ واهية', NULL, 567, 'local:warsh-text.json'),
  ('warsh-69-16', 'warsh', 69, 16, 'وَالْمَلَكُ عَلَىٰٓ أَرْجَآئِهَا࣌ وَيَحْمِلُ عَرْشَ رَبِّكَ فَوْقَهُمْ يَوْمَئِذࣲ ثَمَٰنِيَةࣱ', 'والملك على أرجائها࣌ ويحمل عرش ربك فوقهم يومئذ ثمنية', NULL, 567, 'local:warsh-text.json'),
  ('warsh-69-17', 'warsh', 69, 17, 'يَوْمَئِذࣲ تُعْرَضُونَ لَا تَخْفٜىٰ مِنكُمْ خَافِيَةࣱ࣌', 'يومئذ تعرضون لا تخفى منكم خافية࣌', NULL, 567, 'local:warsh-text.json'),
  ('warsh-69-18', 'warsh', 69, 18, '۞ فَأَمَّا مَنُ ࡳوتِيَ كِتَٰبَهُۥ بِيَمِينِهِۦ فَيَقُولُ هَآؤُمُ ࡲٜقْرَءُواْ كِتَٰبِيَهْ࣌', 'فأما من ࡳوتي كتبه بيمينه فيقول هاؤم ࡲقرءوا كتبيه࣌', NULL, 567, 'local:warsh-text.json'),
  ('warsh-69-19', 'warsh', 69, 19, 'إِنِّے ظَنَنتُ أَنِّے مُلَٰقٍ حِسَابِيَهْ࣌', 'إنے ظننت أنے ملق حسابيه࣌', NULL, 567, 'local:warsh-text.json'),
  ('warsh-69-20', 'warsh', 69, 20, 'فَهُوَ فِے عِيشَةࣲ رَّاضِيَةࣲ', 'فهو فے عيشة راضية', NULL, 567, 'local:warsh-text.json'),
  ('warsh-69-21', 'warsh', 69, 21, 'فِے جَنَّةٍ عَالِيَةࣲ', 'فے جنة عالية', NULL, 567, 'local:warsh-text.json'),
  ('warsh-69-22', 'warsh', 69, 22, 'قُطُوفُهَا دَانِيَةࣱ࣌', 'قطوفها دانية࣌', NULL, 567, 'local:warsh-text.json'),
  ('warsh-69-23', 'warsh', 69, 23, 'كُلُواْ وَاشْرَبُواْ࣌ هَنِيٓـٔاَۢ بِمَآ أَسْلَفْتُمْ فِے ࡴ۬لَايَّامِ ࡴ۬لْخَالِيَةِ࣌', 'كلوا واشربوا࣌ هنيا بما أسلفتم فے ࡴلايام ࡴلخالية࣌', NULL, 567, 'local:warsh-text.json'),
  ('warsh-69-24', 'warsh', 69, 24, 'وَأَمَّا مَنُ ࡳوتِيَ كِتَٰبَهُۥ بِشِمَالِهِۦ', 'وأما من ࡳوتي كتبه بشماله', NULL, 567, 'local:warsh-text.json'),
  ('warsh-69-25', 'warsh', 69, 25, 'فَيَقُولُ يَٰلَيْتَنِے لَمُ ࡳوتَ كِتَٰبِيَهْ࣌', 'فيقول يليتنے لم ࡳوت كتبيه࣌', NULL, 567, 'local:warsh-text.json'),
  ('warsh-69-26', 'warsh', 69, 26, 'وَلَمَ ࡰدْرِ مَا حِسَابِيَهْ࣌', 'ولم ࡰدر ما حسابيه࣌', NULL, 567, 'local:warsh-text.json'),
  ('warsh-69-27', 'warsh', 69, 27, 'يَٰلَيْتَهَا كَانَتِ ࡴ۬لْقَاضِيَةَ', 'يليتها كانت ࡴلقاضية', NULL, 567, 'local:warsh-text.json'),
  ('warsh-69-28', 'warsh', 69, 28, 'مَآ أَغْنٜىٰ عَنِّے مَالِيَه࣌', 'ما أغنى عنے ماليه࣌', NULL, 567, 'local:warsh-text.json'),
  ('warsh-69-29', 'warsh', 69, 29, 'هَّلَكَ عَنِّے سُلْطَٰنِيَهْ࣌', 'هلك عنے سلطنيه࣌', NULL, 567, 'local:warsh-text.json'),
  ('warsh-69-30', 'warsh', 69, 30, 'خُذُوهُ فَغُلُّوهُ', 'خذوه فغلوه', NULL, 567, 'local:warsh-text.json'),
  ('warsh-69-31', 'warsh', 69, 31, 'ثُمَّ ࡰ۬لْجَحِيمَ صَلُّوهُ', 'ثم ࡰلجحيم صلوه', NULL, 567, 'local:warsh-text.json'),
  ('warsh-69-32', 'warsh', 69, 32, 'ثُمَّ فِے سِلْسِلَةࣲ ذَرْعُهَا سَبْعُونَ ذِرَاعاࣰ فَاسْلُكُوهُ࣌', 'ثم فے سلسلة ذرعها سبعون ذراعا فاسلكوه࣌', NULL, 567, 'local:warsh-text.json'),
  ('warsh-69-33', 'warsh', 69, 33, 'إِنَّهُۥ كَانَ لَا يُومِنُ بِاللَّهِ ࡴ۬لْعَظِيمِ', 'إنه كان لا يومن بالله ࡴلعظيم', NULL, 567, 'local:warsh-text.json'),
  ('warsh-69-34', 'warsh', 69, 34, 'وَلَا يَحُضُّ عَلَىٰ طَعَامِ ࡴ۬لْمِسْكِينِ࣌', 'ولا يحض على طعام ࡴلمسكين࣌', NULL, 567, 'local:warsh-text.json'),
  ('warsh-69-35', 'warsh', 69, 35, 'فَلَيْسَ لَهُ ࡲ۬لْيَوْمَ هَٰهُنَا حَمِيمࣱ', 'فليس له ࡲليوم ههنا حميم', NULL, 567, 'local:warsh-text.json'),
  ('warsh-69-36', 'warsh', 69, 36, 'وَلَا طَعَامٌ ࡴلَّا مِنْ غِسْلِينࣲ', 'ولا طعام ࡴلا من غسلين', NULL, 568, 'local:warsh-text.json'),
  ('warsh-69-37', 'warsh', 69, 37, 'لَّا يَاكُلُهُۥٓ إِلَّا ࡰ۬لْخَٰطِـُٔونَ࣌', 'لا ياكله إلا ࡰلخطون࣌', NULL, 568, 'local:warsh-text.json'),
  ('warsh-69-38', 'warsh', 69, 38, 'فَلَآ أُقْسِمُ بِمَا تُبْصِرُونَ', 'فلا أقسم بما تبصرون', NULL, 568, 'local:warsh-text.json'),
  ('warsh-69-39', 'warsh', 69, 39, 'وَمَا لَا تُبْصِرُونَ', 'وما لا تبصرون', NULL, 568, 'local:warsh-text.json'),
  ('warsh-69-40', 'warsh', 69, 40, 'إِنَّهُۥ لَقَوْلُ رَسُولࣲ كَرِيمࣲ', 'إنه لقول رسول كريم', NULL, 568, 'local:warsh-text.json'),
  ('warsh-69-41', 'warsh', 69, 41, 'وَمَا هُوَ بِقَوْلِ شَاعِرࣲ قَلِيلاࣰ مَّا تُومِنُونَ', 'وما هو بقول شاعر قليلا ما تومنون', NULL, 568, 'local:warsh-text.json'),
  ('warsh-69-42', 'warsh', 69, 42, 'وَلَا بِقَوْلِ كَاهِنࣲ࣌ قَلِيلاࣰ مَّا تَذَّكَّرُونَ࣌', 'ولا بقول كاهن࣌ قليلا ما تذكرون࣌', NULL, 568, 'local:warsh-text.json'),
  ('warsh-69-43', 'warsh', 69, 43, 'تَنزِيلࣱ مِّن رَّبِّ ࡴ۬لْعَٰلَمِينَ࣌', 'تنزيل من رب ࡴلعلمين࣌', NULL, 568, 'local:warsh-text.json'),
  ('warsh-69-44', 'warsh', 69, 44, 'وَلَوْ تَقَوَّلَ عَلَيْنَا بَعْضَ ࡰ۬لَاقَاوِيلِ', 'ولو تقول علينا بعض ࡰلاقاويل', NULL, 568, 'local:warsh-text.json'),
  ('warsh-69-45', 'warsh', 69, 45, 'لَأَخَذْنَا مِنْهُ بِالْيَمِينِ', 'لأخذنا منه باليمين', NULL, 568, 'local:warsh-text.json'),
  ('warsh-69-46', 'warsh', 69, 46, 'ثُمَّ لَقَطَعْنَا مِنْهُ ࡲ۬لْوَتِينَ', 'ثم لقطعنا منه ࡲلوتين', NULL, 568, 'local:warsh-text.json'),
  ('warsh-69-47', 'warsh', 69, 47, 'فَمَا مِنكُم مِّنَ ࡰحَدٍ عَنْهُ حَٰجِزِينَ࣌', 'فما منكم من ࡰحد عنه حجزين࣌', NULL, 568, 'local:warsh-text.json'),
  ('warsh-69-48', 'warsh', 69, 48, 'وَإِنَّهُۥ لَتَذْكِرَةࣱ لِّلْمُتَّقِينَ࣌', 'وإنه لتذكرة للمتقين࣌', NULL, 568, 'local:warsh-text.json'),
  ('warsh-69-49', 'warsh', 69, 49, 'وَإِنَّا لَنَعْلَمُ أَنَّ مِنكُم مُّكَذِّبِينَ࣌', 'وإنا لنعلم أن منكم مكذبين࣌', NULL, 568, 'local:warsh-text.json'),
  ('warsh-69-50', 'warsh', 69, 50, 'وَإِنَّهُۥ لَحَسْرَةٌ عَلَى ࡰ۬لْكٜـٰفِرِينَ࣌', 'وإنه لحسرة على ࡰلكفرين࣌', NULL, 568, 'local:warsh-text.json'),
  ('warsh-69-51', 'warsh', 69, 51, 'وَإِنَّهُۥ لَحَقُّ ࡲ۬لْيَقِينِ࣌', 'وإنه لحق ࡲليقين࣌', NULL, 568, 'local:warsh-text.json'),
  ('warsh-69-52', 'warsh', 69, 52, 'فَسَبِّحْ بِاسْمِ رَبِّكَ ࡰ۬لْعَظِيمِ࣌', 'فسبح باسم ربك ࡰلعظيم࣌', NULL, 568, 'local:warsh-text.json'),
  ('warsh-70-1', 'warsh', 70, 1, 'سَالَ سَآئِلُۢ بِعَذَابࣲ وَاقِعࣲ', 'سال سائل بعذاب واقع', NULL, 568, 'local:warsh-text.json'),
  ('warsh-70-2', 'warsh', 70, 2, 'لِّلْكٜـٰفِرِينَ لَيْسَ لَهُۥ دَافِعࣱ', 'للكفرين ليس له دافع', NULL, 568, 'local:warsh-text.json'),
  ('warsh-70-3', 'warsh', 70, 3, 'مِّنَ ࡰ۬للَّهِ ذِے ࡴ۬لْمَعَارِجِ࣌', 'من ࡰلله ذے ࡴلمعارج࣌', NULL, 568, 'local:warsh-text.json'),
  ('warsh-70-4', 'warsh', 70, 4, 'تَعْرُجُ ࡲ۬لْمَلَٰٓئِكَةُ وَالرُّوحُ إِلَيْهِ فِے يَوْمࣲ كَانَ مِقْدَارُهُۥ خَمْسِينَ أَلْفَ سَنَةࣲ࣌', 'تعرج ࡲلملئكة والروح إليه فے يوم كان مقداره خمسين ألف سنة࣌', NULL, 568, 'local:warsh-text.json'),
  ('warsh-70-5', 'warsh', 70, 5, 'فَاصْبِرْ صَبْراࣰ جَمِيلاً࣌', 'فاصبر صبرا جميلا࣌', NULL, 568, 'local:warsh-text.json'),
  ('warsh-70-6', 'warsh', 70, 6, 'ࡴنَّهُمْ يَرَوْنَهُۥ بَعِيداࣰ', 'ࡴنهم يرونه بعيدا', NULL, 568, 'local:warsh-text.json'),
  ('warsh-70-7', 'warsh', 70, 7, 'وَنَرٜيٰهُ قَرِيباࣰ࣌', 'ونريه قريبا࣌', NULL, 568, 'local:warsh-text.json'),
  ('warsh-70-8', 'warsh', 70, 8, 'يَوْمَ تَكُونُ ࡲ۬لسَّمَآءُ كَالْمُهْلِ', 'يوم تكون ࡲلسماء كالمهل', NULL, 568, 'local:warsh-text.json'),
  ('warsh-70-9', 'warsh', 70, 9, 'وَتَكُونُ ࡲ۬لْجِبَالُ كَالْعِهْنِ', 'وتكون ࡲلجبال كالعهن', NULL, 568, 'local:warsh-text.json'),
  ('warsh-70-10', 'warsh', 70, 10, 'وَلَا يَسْـَٔلُ حَمِيمٌ حَمِيماࣰ', 'ولا يسل حميم حميما', NULL, 568, 'local:warsh-text.json'),
  ('warsh-70-11', 'warsh', 70, 11, 'يُبَصَّرُونَهُمْ࣌ يَوَدُّ ࡲ۬لْمُجْرِمُ لَوْ يَفْتَدِے مِنْ عَذَابِ يَوْمَئِذِۢ بِبَنِيهِ', 'يبصرونهم࣌ يود ࡲلمجرم لو يفتدے من عذاب يومئذ ببنيه', NULL, 569, 'local:warsh-text.json'),
  ('warsh-70-12', 'warsh', 70, 12, 'وَصَٰحِبَتِهِۦ وَأَخِيهِ', 'وصحبته وأخيه', NULL, 569, 'local:warsh-text.json'),
  ('warsh-70-13', 'warsh', 70, 13, 'وَفَصِيلَتِهِ ࡴ۬لتِے تُـْٔوِيهِ', 'وفصيلته ࡴلتے تويه', NULL, 569, 'local:warsh-text.json'),
  ('warsh-70-14', 'warsh', 70, 14, 'وَمَن فِے ࡴ۬لَارْضِ جَمِيعاࣰ ثُمَّ يُنجِيهِ', 'ومن فے ࡴلارض جميعا ثم ينجيه', NULL, 569, 'local:warsh-text.json'),
  ('warsh-70-15', 'warsh', 70, 15, 'كَلَّآ࣌ إِنَّهَا لَظٜىٰ', 'كلا࣌ إنها لظى', NULL, 569, 'local:warsh-text.json'),
  ('warsh-70-16', 'warsh', 70, 16, 'نَزَّاعَةࣱ لِّلشَّوٜىٰ', 'نزاعة للشوى', NULL, 569, 'local:warsh-text.json'),
  ('warsh-70-17', 'warsh', 70, 17, 'تَدْعُواْ مَنَ ࡰدْبَرَ وَتَوَلّٜىٰ', 'تدعوا من ࡰدبر وتولى', NULL, 569, 'local:warsh-text.json'),
  ('warsh-70-18', 'warsh', 70, 18, 'وَجَمَعَ فَأَوْعٜىٰٓ࣌', 'وجمع فأوعى࣌', NULL, 569, 'local:warsh-text.json'),
  ('warsh-70-19', 'warsh', 70, 19, 'إِنَّ ࡰ۬لِانسَٰنَ خُلِقَ هَلُوعاً', 'إن ࡰلانسن خلق هلوعا', NULL, 569, 'local:warsh-text.json'),
  ('warsh-70-20', 'warsh', 70, 20, 'ࡴذَا مَسَّهُ ࡲ۬لشَّرُّ جَزُوعاࣰ', 'ࡴذا مسه ࡲلشر جزوعا', NULL, 569, 'local:warsh-text.json'),
  ('warsh-70-21', 'warsh', 70, 21, 'وَإِذَا مَسَّهُ ࡲ۬لْخَيْرُ مَنُوعاً', 'وإذا مسه ࡲلخير منوعا', NULL, 569, 'local:warsh-text.json'),
  ('warsh-70-22', 'warsh', 70, 22, 'ࡴلَّا ࡰ۬لْمُصَلِّينَ', 'ࡴلا ࡰلمصلين', NULL, 569, 'local:warsh-text.json'),
  ('warsh-70-23', 'warsh', 70, 23, 'ࡰ۬لذِينَ هُمْ عَلَىٰ صَلَاتِهِمْ دَآئِمُونَ࣌', 'ࡰلذين هم على صلاتهم دائمون࣌', NULL, 569, 'local:warsh-text.json'),
  ('warsh-70-24', 'warsh', 70, 24, 'وَالذِينَ فِےٓ أَمْوَٰلِهِمْ حَقࣱّ مَّعْلُومࣱ', 'والذين فے أمولهم حق معلوم', NULL, 569, 'local:warsh-text.json'),
  ('warsh-70-25', 'warsh', 70, 25, 'لِّلسَّآئِلِ وَالْمَحْرُومِ࣌', 'للسائل والمحروم࣌', NULL, 569, 'local:warsh-text.json'),
  ('warsh-70-26', 'warsh', 70, 26, 'وَالذِينَ يُصَدِّقُونَ بِيَوْمِ ࡴ۬لدِّينِ࣌', 'والذين يصدقون بيوم ࡴلدين࣌', NULL, 569, 'local:warsh-text.json'),
  ('warsh-70-27', 'warsh', 70, 27, 'وَالذِينَ هُم مِّنْ عَذَابِ رَبِّهِم مُّشْفِقُونَ', 'والذين هم من عذاب ربهم مشفقون', NULL, 569, 'local:warsh-text.json'),
  ('warsh-70-28', 'warsh', 70, 28, 'إِنَّ عَذَابَ رَبِّهِمْ غَيْرُ مَامُونࣲ࣌', 'إن عذاب ربهم غير مامون࣌', NULL, 569, 'local:warsh-text.json'),
  ('warsh-70-29', 'warsh', 70, 29, 'وَالذِينَ هُمْ لِفُرُوجِهِمْ حَٰفِظُونَ', 'والذين هم لفروجهم حفظون', NULL, 569, 'local:warsh-text.json'),
  ('warsh-70-30', 'warsh', 70, 30, 'إِلَّا عَلَىٰٓ أَزْوَٰجِهِمُۥٓ أَوْ مَا مَلَكَتَ ࡰيْمَٰنُهُمْ فَإِنَّهُمْ غَيْرُ مَلُومِينَ࣌', 'إلا على أزوجهم أو ما ملكت ࡰيمنهم فإنهم غير ملومين࣌', NULL, 569, 'local:warsh-text.json'),
  ('warsh-70-31', 'warsh', 70, 31, 'فَمَنِ ࡴٜبْتَغٜىٰ وَرَآءَ ذَٰلِكَ فَأُوْلَٰٓئِكَ هُمُ ࡲ۬لْعَادُونَ࣌', 'فمن ࡴبتغى وراء ذلك فأولئك هم ࡲلعادون࣌', NULL, 569, 'local:warsh-text.json'),
  ('warsh-70-32', 'warsh', 70, 32, 'وَالذِينَ هُمْ لِأَمَٰنَٰتِهِمْ وَعَهْدِهِمْ رَٰعُونَ࣌', 'والذين هم لأمنتهم وعهدهم رعون࣌', NULL, 569, 'local:warsh-text.json'),
  ('warsh-70-33', 'warsh', 70, 33, 'وَالذِينَ هُم بِشَهَٰدَتِهِمْ قَآئِمُونَ࣌', 'والذين هم بشهدتهم قائمون࣌', NULL, 569, 'local:warsh-text.json'),
  ('warsh-70-34', 'warsh', 70, 34, 'وَالذِينَ هُمْ عَلَىٰ صَلَاتِهِمْ يُحَافِظُونَ', 'والذين هم على صلاتهم يحافظون', NULL, 569, 'local:warsh-text.json'),
  ('warsh-70-35', 'warsh', 70, 35, 'أُوْلَٰٓئِكَ فِے جَنَّٰتࣲ مُّكْرَمُونَ࣌', 'أولئك فے جنت مكرمون࣌', NULL, 569, 'local:warsh-text.json'),
  ('warsh-70-36', 'warsh', 70, 36, 'فَمَالِ ࡴ۬لذِينَ كَفَرُواْ قِبَلَكَ مُهْطِعِينَ', 'فمال ࡴلذين كفروا قبلك مهطعين', NULL, 569, 'local:warsh-text.json'),
  ('warsh-70-37', 'warsh', 70, 37, 'عَنِ ࡴ۬لْيَمِينِ وَعَنِ ࡴ۬لشِّمَالِ عِزِينَ࣌', 'عن ࡴليمين وعن ࡴلشمال عزين࣌', NULL, 569, 'local:warsh-text.json'),
  ('warsh-70-38', 'warsh', 70, 38, 'أَيَطْمَعُ كُلُّ ࡲٜمْرِےࣲٕ مِّنْهُمُۥٓ أَنْ يُّدْخَلَ جَنَّةَ نَعِيمࣲ', 'أيطمع كل ࡲمرے منهم أن يدخل جنة نعيم', NULL, 569, 'local:warsh-text.json'),
  ('warsh-70-39', 'warsh', 70, 39, 'كَلَّآ࣌ إِنَّا خَلَقْنَٰهُم مِّمَّا يَعْلَمُونَ࣌', 'كلا࣌ إنا خلقنهم مما يعلمون࣌', NULL, 569, 'local:warsh-text.json'),
  ('warsh-70-40', 'warsh', 70, 40, '۞ فَلَآ أُقْسِمُ بِرَبِّ ࡴ۬لْمَشَٰرِقِ وَالْمَغَٰرِبِ إِنَّا لَقَٰدِرُونَ', 'فلا أقسم برب ࡴلمشرق والمغرب إنا لقدرون', NULL, 569, 'local:warsh-text.json'),
  ('warsh-70-41', 'warsh', 70, 41, 'عَلَىٰٓ أَن نُّبَدِّلَ خَيْراࣰ مِّنْهُمْ وَمَا نَحْنُ بِمَسْبُوقِينَ࣌', 'على أن نبدل خيرا منهم وما نحن بمسبوقين࣌', NULL, 570, 'local:warsh-text.json'),
  ('warsh-70-42', 'warsh', 70, 42, 'فَذَرْهُمْ يَخُوضُواْ وَيَلْعَبُواْ حَتَّىٰ يُلَٰقُواْ يَوْمَهُمُ ࡲ۬لذِے يُوعَدُونَ', 'فذرهم يخوضوا ويلعبوا حتى يلقوا يومهم ࡲلذے يوعدون', NULL, 570, 'local:warsh-text.json'),
  ('warsh-70-43', 'warsh', 70, 43, 'يَوْمَ يَخْرُجُونَ مِنَ ࡰ۬لَاجْدَاثِ سِرَاعاࣰ كَأَنَّهُمُۥٓ إِلَىٰ نَصْبࣲ يُوفِضُونَ', 'يوم يخرجون من ࡰلاجداث سراعا كأنهم إلى نصب يوفضون', NULL, 570, 'local:warsh-text.json'),
  ('warsh-70-44', 'warsh', 70, 44, 'خَٰشِعَةً ࡰبْصَٰرُهُمْ تَرْهَقُهُمْ ذِلَّةࣱ࣌ ذَٰلِكَ ࡰ۬لْيَوْمُ ࡲ۬لذِے كَانُواْ يُوعَدُونَ࣌', 'خشعة ࡰبصرهم ترهقهم ذلة࣌ ذلك ࡰليوم ࡲلذے كانوا يوعدون࣌', NULL, 570, 'local:warsh-text.json'),
  ('warsh-71-1', 'warsh', 71, 1, 'إِنَّآ أَرْسَلْنَا نُوحاً ࡴلَىٰ قَوْمِهِۦٓ أَنَ ࡰنذِرْ قَوْمَكَ مِن قَبْلِ أَنْ يَّاتِيَهُمْ عَذَابٌ ࡰلِيمࣱ࣌', 'إنا أرسلنا نوحا ࡴلى قومه أن ࡰنذر قومك من قبل أن ياتيهم عذاب ࡰليم࣌', NULL, 570, 'local:warsh-text.json'),
  ('warsh-71-2', 'warsh', 71, 2, 'قَالَ يَٰقَوْمِ إِنِّے لَكُمْ نَذِيرࣱ مُّبِينٌ', 'قال يقوم إنے لكم نذير مبين', NULL, 570, 'local:warsh-text.json'),
  ('warsh-71-3', 'warsh', 71, 3, 'ࡰنُ ࡲ࢈عْبُدُواْ ࡲ۬للَّهَ وَاتَّقُوهُ وَأَطِيعُونِ', 'ࡰن ࡲ࢈عبدوا ࡲلله واتقوه وأطيعون', NULL, 570, 'local:warsh-text.json'),
  ('warsh-71-4', 'warsh', 71, 4, 'يَغْفِرْ لَكُم مِّن ذُنُوبِكُمْ وَيُوَ۬خِّرْكُمُۥٓ إِلَىٰٓ أَجَلࣲ مُّسَمّىً࣌ ࡴنَّ أَجَلَ ࡰ۬للَّهِ إِذَا جَآءَ لَا يُوَ۬خَّرُ لَوْ كُنتُمْ تَعْلَمُونَ࣌', 'يغفر لكم من ذنوبكم ويوخركم إلى أجل مسمى࣌ ࡴن أجل ࡰلله إذا جاء لا يوخر لو كنتم تعلمون࣌', NULL, 570, 'local:warsh-text.json'),
  ('warsh-71-5', 'warsh', 71, 5, 'قَالَ رَبِّ إِنِّے دَعَوْتُ قَوْمِے لَيْلاࣰ وَنَهَاراࣰ', 'قال رب إنے دعوت قومے ليلا ونهارا', NULL, 570, 'local:warsh-text.json'),
  ('warsh-71-6', 'warsh', 71, 6, 'فَلَمْ يَزِدْهُمْ دُعَآءِيَ إِلَّا فِرَاراࣰ࣌', 'فلم يزدهم دعاءي إلا فرارا࣌', NULL, 570, 'local:warsh-text.json'),
  ('warsh-71-7', 'warsh', 71, 7, 'وَإِنِّے كُلَّمَا دَعَوْتُهُمْ لِتَغْفِرَ لَهُمْ جَعَلُوٓاْ أَصَٰبِعَهُمْ فِےٓ ءَاذَانِهِمْ وَاسْتَغْشَوْاْ ثِيَابَهُمْ وَأَصَرُّواْ وَاسْتَكْبَرُواْ ࡲٜسْتِكْبَاراࣰ࣌', 'وإنے كلما دعوتهم لتغفر لهم جعلوا أصبعهم فے ءاذانهم واستغشوا ثيابهم وأصروا واستكبروا ࡲستكبارا࣌', NULL, 570, 'local:warsh-text.json'),
  ('warsh-71-8', 'warsh', 71, 8, 'ثُمَّ إِنِّے دَعَوْتُهُمْ جِهَاراࣰ࣌', 'ثم إنے دعوتهم جهارا࣌', NULL, 570, 'local:warsh-text.json'),
  ('warsh-71-9', 'warsh', 71, 9, 'ثُمَّ إِنِّيَ أَعْلَنتُ لَهُمْ وَأَسْرَرْتُ لَهُمُۥٓ إِسْرَاراࣰ', 'ثم إني أعلنت لهم وأسررت لهم إسرارا', NULL, 570, 'local:warsh-text.json'),
  ('warsh-71-10', 'warsh', 71, 10, 'فَقُلْتُ ࡲٜسْتَغْفِرُواْ رَبَّكُمُۥٓ إِنَّهُۥ كَانَ غَفَّاراࣰ', 'فقلت ࡲستغفروا ربكم إنه كان غفارا', NULL, 570, 'local:warsh-text.json'),
  ('warsh-71-11', 'warsh', 71, 11, 'يُرْسِلِ ࡴ۬لسَّمَآءَ عَلَيْكُم مِّدْرَاراࣰ', 'يرسل ࡴلسماء عليكم مدرارا', NULL, 571, 'local:warsh-text.json'),
  ('warsh-71-12', 'warsh', 71, 12, 'وَيُمْدِدْكُم بِأَمْوَٰلࣲ وَبَنِينَ وَيَجْعَل لَّكُمْ جَنَّٰتࣲ وَيَجْعَل لَّكُمُۥٓ أَنْهَٰراࣰ࣌', 'ويمددكم بأمول وبنين ويجعل لكم جنت ويجعل لكم أنهرا࣌', NULL, 571, 'local:warsh-text.json'),
  ('warsh-71-13', 'warsh', 71, 13, 'مَّا لَكُمْ لَا تَرْجُونَ لِلهِ وَقَاراࣰ', 'ما لكم لا ترجون لله وقارا', NULL, 571, 'local:warsh-text.json'),
  ('warsh-71-14', 'warsh', 71, 14, 'وَقَدْ خَلَقَكُمُۥٓ أَطْوَاراً࣌', 'وقد خلقكم أطوارا࣌', NULL, 571, 'local:warsh-text.json'),
  ('warsh-71-15', 'warsh', 71, 15, '۞ ࡰلَمْ تَرَوْاْ كَيْفَ خَلَقَ ࡰ۬للَّهُ سَبْعَ سَمَٰوَٰتࣲ طِبَاقاࣰ', 'ࡰلم تروا كيف خلق ࡰلله سبع سموت طباقا', NULL, 571, 'local:warsh-text.json'),
  ('warsh-71-16', 'warsh', 71, 16, 'وَجَعَلَ ࡰ۬لْقَمَرَ فِيهِنَّ نُوراࣰ وَجَعَلَ ࡰ۬لشَّمْسَ سِرَاجاࣰ࣌', 'وجعل ࡰلقمر فيهن نورا وجعل ࡰلشمس سراجا࣌', NULL, 571, 'local:warsh-text.json'),
  ('warsh-71-17', 'warsh', 71, 17, 'وَاللَّهُ أَنۢبَتَكُم مِّنَ ࡰ۬لَارْضِ نَبَاتاࣰ', 'والله أنبتكم من ࡰلارض نباتا', NULL, 571, 'local:warsh-text.json'),
  ('warsh-71-18', 'warsh', 71, 18, 'ثُمَّ يُعِيدُكُمْ فِيهَا وَيُخْرِجُكُمُۥٓ إِخْرَاجاࣰ࣌', 'ثم يعيدكم فيها ويخرجكم إخراجا࣌', NULL, 571, 'local:warsh-text.json'),
  ('warsh-71-19', 'warsh', 71, 19, 'وَاللَّهُ جَعَلَ لَكُمُ ࡲ۬لَارْضَ بِسَاطاࣰ', 'والله جعل لكم ࡲلارض بساطا', NULL, 571, 'local:warsh-text.json'),
  ('warsh-71-20', 'warsh', 71, 20, 'لِّتَسْلُكُواْ مِنْهَا سُبُلاࣰ فِجَاجاࣰ࣌', 'لتسلكوا منها سبلا فجاجا࣌', NULL, 571, 'local:warsh-text.json'),
  ('warsh-71-21', 'warsh', 71, 21, 'قَالَ نُوحࣱ رَّبِّ إِنَّهُمْ عَصَوْنِے وَاتَّبَعُواْ مَن لَّمْ يَزِدْهُ مَالُهُۥ وَوَلَدُهُۥٓ إِلَّا خَسَاراࣰ', 'قال نوح رب إنهم عصونے واتبعوا من لم يزده ماله وولده إلا خسارا', NULL, 571, 'local:warsh-text.json'),
  ('warsh-71-22', 'warsh', 71, 22, 'وَمَكَرُواْ مَكْراࣰ كُبَّاراࣰ࣌', 'ومكروا مكرا كبارا࣌', NULL, 571, 'local:warsh-text.json'),
  ('warsh-71-23', 'warsh', 71, 23, 'وَقَالُواْ لَا تَذَرُنَّ ءَالِهَتَكُمْ وَلَا تَذَرُنَّ وُدّاࣰ وَلَا سُوَاعاࣰ', 'وقالوا لا تذرن ءالهتكم ولا تذرن ودا ولا سواعا', NULL, 571, 'local:warsh-text.json'),
  ('warsh-71-24', 'warsh', 71, 24, 'وَلَا يَغُوثَ وَيَعُوقَ وَنَسْراࣰ࣌', 'ولا يغوث ويعوق ونسرا࣌', NULL, 571, 'local:warsh-text.json'),
  ('warsh-71-25', 'warsh', 71, 25, 'وَقَدَ ࡰضَلُّواْ كَثِيراࣰ࣌ وَلَا تَزِدِ ࡴ۬لظَّٰلِمِينَ إِلَّا ضَلَٰلاࣰ࣌', 'وقد ࡰضلوا كثيرا࣌ ولا تزد ࡴلظلمين إلا ضللا࣌', NULL, 571, 'local:warsh-text.json'),
  ('warsh-71-26', 'warsh', 71, 26, 'مِّمَّا خَطِيٓـَٰٔتِهِمُۥٓ أُغْرِقُواْ فَأُدْخِلُواْ نَاراࣰ', 'مما خطيتهم أغرقوا فأدخلوا نارا', NULL, 571, 'local:warsh-text.json'),
  ('warsh-71-27', 'warsh', 71, 27, 'فَلَمْ يَجِدُواْ لَهُم مِّن دُونِ ࡴ۬للَّهِ أَنصَاراࣰ࣌', 'فلم يجدوا لهم من دون ࡴلله أنصارا࣌', NULL, 571, 'local:warsh-text.json'),
  ('warsh-71-28', 'warsh', 71, 28, 'وَقَالَ نُوحࣱ رَّبِّ لَا تَذَرْ عَلَى ࡰ۬لَارْضِ مِنَ ࡰ۬لْكٜـٰفِرِينَ دَيَّاراً࣌', 'وقال نوح رب لا تذر على ࡰلارض من ࡰلكفرين ديارا࣌', NULL, 571, 'local:warsh-text.json'),
  ('warsh-71-29', 'warsh', 71, 29, 'ࡴنَّكَ إِن تَذَرْهُمْ يُضِلُّواْ عِبَادَكَ وَلَا يَلِدُوٓاْ إِلَّا فَاجِراࣰ كَفَّاراࣰ࣌', 'ࡴنك إن تذرهم يضلوا عبادك ولا يلدوا إلا فاجرا كفارا࣌', NULL, 571, 'local:warsh-text.json'),
  ('warsh-71-30', 'warsh', 71, 30, 'رَّبِّ ࡴٜغْفِرْ لِے وَلِوَٰلِدَيَّ وَلِمَن دَخَلَ بَيْتِے مُومِناࣰ وَلِلْمُومِنِينَ وَالْمُومِنَٰتِ࣌ وَلَا تَزِدِ ࡴ۬لظَّٰلِمِينَ إِلَّا تَبَاراࣰ࣌', 'رب ࡴغفر لے ولولدي ولمن دخل بيتے مومنا وللمومنين والمومنت࣌ ولا تزد ࡴلظلمين إلا تبارا࣌', NULL, 571, 'local:warsh-text.json'),
  ('warsh-72-1', 'warsh', 72, 1, 'قُلُ ࡳوحِيَ إِلَيَّ أَنَّهُ ࡲٜسْتَمَعَ نَفَرࣱ مِّنَ ࡰ۬لْجِنِّ فَقَالُوٓاْ إِنَّا سَمِعْنَا قُرْءَاناً عَجَباࣰ', 'قل ࡳوحي إلي أنه ࡲستمع نفر من ࡰلجن فقالوا إنا سمعنا قرءانا عجبا', NULL, 572, 'local:warsh-text.json'),
  ('warsh-72-2', 'warsh', 72, 2, 'يَهْدِےٓ إِلَى ࡰ۬لرُّشْدِ فَـَٔامَنَّا بِهِۦ وَلَن نُّشْرِكَ بِرَبِّنَآ أَحَداࣰ࣌', 'يهدے إلى ࡰلرشد فامنا به ولن نشرك بربنا أحدا࣌', NULL, 572, 'local:warsh-text.json'),
  ('warsh-72-3', 'warsh', 72, 3, 'وَإِنَّهُۥ تَعَٰلٜىٰ جَدُّ رَبِّنَا مَا ࡰٜتَّخَذَ صَٰحِبَةࣰ وَلَا وَلَداࣰ࣌', 'وإنه تعلى جد ربنا ما ࡰتخذ صحبة ولا ولدا࣌', NULL, 572, 'local:warsh-text.json'),
  ('warsh-72-4', 'warsh', 72, 4, 'وَإِنَّهُۥ كَانَ يَقُولُ سَفِيهُنَا عَلَى ࡰ۬للَّهِ شَطَطاࣰ࣌', 'وإنه كان يقول سفيهنا على ࡰلله شططا࣌', NULL, 572, 'local:warsh-text.json'),
  ('warsh-72-5', 'warsh', 72, 5, 'وَإِنَّا ظَنَنَّآ أَن لَّن تَقُولَ ࡰ۬لِانسُ وَالْجِنُّ عَلَى ࡰ۬للَّهِ كَذِباࣰ࣌', 'وإنا ظننا أن لن تقول ࡰلانس والجن على ࡰلله كذبا࣌', NULL, 572, 'local:warsh-text.json'),
  ('warsh-72-6', 'warsh', 72, 6, 'وَإِنَّهُۥ كَانَ رِجَالࣱ مِّنَ ࡰ۬لِانسِ يَعُوذُونَ بِرِجَالࣲ مِّنَ ࡰ۬لْجِنِّ فَزَادُوهُمْ رَهَقاࣰ࣌', 'وإنه كان رجال من ࡰلانس يعوذون برجال من ࡰلجن فزادوهم رهقا࣌', NULL, 572, 'local:warsh-text.json'),
  ('warsh-72-7', 'warsh', 72, 7, 'وَإِنَّهُمْ ظَنُّواْ كَمَا ظَنَنتُمُۥٓ أَن لَّنْ يَّبْعَثَ ࡰ۬للَّهُ أَحَداࣰ࣌', 'وإنهم ظنوا كما ظننتم أن لن يبعث ࡰلله أحدا࣌', NULL, 572, 'local:warsh-text.json'),
  ('warsh-72-8', 'warsh', 72, 8, 'وَإِنَّا لَمَسْنَا ࡰ۬لسَّمَآءَ فَوَجَدْنَٰهَا مُلِئَتْ حَرَساࣰ شَدِيداࣰ وَشُهُباࣰ࣌', 'وإنا لمسنا ࡰلسماء فوجدنها ملئت حرسا شديدا وشهبا࣌', NULL, 572, 'local:warsh-text.json'),
  ('warsh-72-9', 'warsh', 72, 9, 'وَإِنَّا كُنَّا نَقْعُدُ مِنْهَا مَقَٰعِدَ لِلسَّمْعِ فَمَنْ يَّسْتَمِعِ ࡴ۬لَانَ يَجِدْ لَهُۥ شِهَاباࣰ رَّصَداࣰ࣌', 'وإنا كنا نقعد منها مقعد للسمع فمن يستمع ࡴلان يجد له شهابا رصدا࣌', NULL, 572, 'local:warsh-text.json'),
  ('warsh-72-10', 'warsh', 72, 10, 'وَإِنَّا لَا نَدْرِےٓ أَشَرٌّ ࡳرِيدَ بِمَن فِے ࡴ۬لَارْضِ أَمَ ࡰرَادَ بِهِمْ رَبُّهُمْ رَشَداࣰ࣌', 'وإنا لا ندرے أشر ࡳريد بمن فے ࡴلارض أم ࡰراد بهم ربهم رشدا࣌', NULL, 572, 'local:warsh-text.json'),
  ('warsh-72-11', 'warsh', 72, 11, 'وَإِنَّا مِنَّا ࡰ۬لصَّٰلِحُونَ وَمِنَّا دُونَ ذَٰلِكَ࣌ كُنَّا طَرَآئِقَ قِدَداࣰ࣌', 'وإنا منا ࡰلصلحون ومنا دون ذلك࣌ كنا طرائق قددا࣌', NULL, 572, 'local:warsh-text.json'),
  ('warsh-72-12', 'warsh', 72, 12, 'وَإِنَّا ظَنَنَّآ أَن لَّن نُّعْجِزَ ࡰ۬للَّهَ فِے ࡴ۬لَارْضِ وَلَن نُّعْجِزَهُۥ هَرَباࣰ࣌', 'وإنا ظننا أن لن نعجز ࡰلله فے ࡴلارض ولن نعجزه هربا࣌', NULL, 572, 'local:warsh-text.json'),
  ('warsh-72-13', 'warsh', 72, 13, 'وَإِنَّا لَمَّا سَمِعْنَا ࡰ۬لْهُدٜىٰٓ ءَامَنَّا بِهِۦ࣌ فَمَنْ يُّومِنۢ بِرَبِّهِۦ فَلَا يَخَافُ بَخْساࣰ وَلَا رَهَقاࣰ࣌', 'وإنا لما سمعنا ࡰلهدى ءامنا به࣌ فمن يومن بربه فلا يخاف بخسا ولا رهقا࣌', NULL, 572, 'local:warsh-text.json'),
  ('warsh-72-14', 'warsh', 72, 14, 'وَإِنَّا مِنَّا ࡰ۬لْمُسْلِمُونَ وَمِنَّا ࡰ۬لْقَٰسِطُونَ࣌ فَمَنَ ࡰسْلَمَ فَأُوْلَٰٓئِكَ تَحَرَّوْاْ رَشَداࣰ࣌', 'وإنا منا ࡰلمسلمون ومنا ࡰلقسطون࣌ فمن ࡰسلم فأولئك تحروا رشدا࣌', NULL, 573, 'local:warsh-text.json'),
  ('warsh-72-15', 'warsh', 72, 15, 'وَأَمَّا ࡰ۬لْقَٰسِطُونَ فَكَانُواْ لِجَهَنَّمَ حَطَباࣰ࣌', 'وأما ࡰلقسطون فكانوا لجهنم حطبا࣌', NULL, 573, 'local:warsh-text.json'),
  ('warsh-72-16', 'warsh', 72, 16, 'وَأَن لَّوِ ࡴٜسْتَقَٰمُواْ عَلَى ࡰ۬لطَّرِيقَةِ لَأَسْقَيْنَٰهُم مَّآءً غَدَقاࣰ', 'وأن لو ࡴستقموا على ࡰلطريقة لأسقينهم ماء غدقا', NULL, 573, 'local:warsh-text.json'),
  ('warsh-72-17', 'warsh', 72, 17, 'لِّنَفْتِنَهُمْ فِيهِ࣌ وَمَنْ يُّعْرِضْ عَن ذِكْرِ رَبِّهِۦ نَسْلُكْهُ عَذَاباࣰ صَعَداࣰ࣌', 'لنفتنهم فيه࣌ ومن يعرض عن ذكر ربه نسلكه عذابا صعدا࣌', NULL, 573, 'local:warsh-text.json'),
  ('warsh-72-18', 'warsh', 72, 18, 'وَأَنَّ ࡰ۬لْمَسَٰجِدَ لِلهِ فَلَا تَدْعُواْ مَعَ ࡰ۬للَّهِ أَحَداࣰ࣌', 'وأن ࡰلمسجد لله فلا تدعوا مع ࡰلله أحدا࣌', NULL, 573, 'local:warsh-text.json'),
  ('warsh-72-19', 'warsh', 72, 19, 'وَإِنَّهُۥ لَمَّا قَامَ عَبْدُ ࡲ۬للَّهِ يَدْعُوهُ كَادُواْ يَكُونُونَ عَلَيْهِ لِبَداࣰ࣌', 'وإنه لما قام عبد ࡲلله يدعوه كادوا يكونون عليه لبدا࣌', NULL, 573, 'local:warsh-text.json'),
  ('warsh-72-20', 'warsh', 72, 20, 'قَالَ إِنَّمَآ أَدْعُواْ رَبِّے وَلَآ أُشْرِكُ بِهِۦٓ أَحَداࣰ࣌', 'قال إنما أدعوا ربے ولا أشرك به أحدا࣌', NULL, 573, 'local:warsh-text.json'),
  ('warsh-72-21', 'warsh', 72, 21, 'قُلِ ࡴنِّے لَآ أَمْلِكُ لَكُمْ ضَرّاࣰ وَلَا رَشَداࣰ࣌', 'قل ࡴنے لا أملك لكم ضرا ولا رشدا࣌', NULL, 573, 'local:warsh-text.json'),
  ('warsh-72-22', 'warsh', 72, 22, 'قُلِ ࡴنِّے لَنْ يُّجِيرَنِے مِنَ ࡰ۬للَّهِ أَحَدࣱ وَلَنَ ࡰجِدَ مِن دُونِهِۦ مُلْتَحَداً', 'قل ࡴنے لن يجيرنے من ࡰلله أحد ولن ࡰجد من دونه ملتحدا', NULL, 573, 'local:warsh-text.json'),
  ('warsh-72-23', 'warsh', 72, 23, 'ࡴلَّا بَلَٰغاࣰ مِّنَ ࡰ۬للَّهِ وَرِسَٰلَٰتِهِۦ࣌ ۞ وَمَنْ يَّعْصِ ࡴ۬للَّهَ وَرَسُولَهُۥ فَإِنَّ لَهُۥ نَارَ جَهَنَّمَ خَٰلِدِينَ فِيهَآ أَبَداً࣌', 'ࡴلا بلغا من ࡰلله ورسلته࣌  ومن يعص ࡴلله ورسوله فإن له نار جهنم خلدين فيها أبدا࣌', NULL, 573, 'local:warsh-text.json'),
  ('warsh-72-24', 'warsh', 72, 24, 'حَتَّىٰٓ إِذَا رَأَوْاْ مَا يُوعَدُونَ فَسَيَعْلَمُونَ مَنَ ࡰضْعَفُ نَاصِراࣰ وَأَقَلُّ عَدَداࣰ࣌', 'حتى إذا رأوا ما يوعدون فسيعلمون من ࡰضعف ناصرا وأقل عددا࣌', NULL, 573, 'local:warsh-text.json'),
  ('warsh-72-25', 'warsh', 72, 25, 'قُلِ ࡴنَ ࡰدْرِےٓ أَقَرِيبࣱ مَّا تُوعَدُونَ أَمْ يَجْعَلُ لَهُۥ رَبِّيَ أَمَداً࣌', 'قل ࡴن ࡰدرے أقريب ما توعدون أم يجعل له ربي أمدا࣌', NULL, 573, 'local:warsh-text.json'),
  ('warsh-72-26', 'warsh', 72, 26, 'عَٰلِمُ ࡲ۬لْغَيْبِ فَلَا يُظْهِرُ عَلَىٰ غَيْبِهِۦٓ أَحَداً', 'علم ࡲلغيب فلا يظهر على غيبه أحدا', NULL, 573, 'local:warsh-text.json'),
  ('warsh-72-27', 'warsh', 72, 27, 'ࡴلَّا مَنِ ࡴٜرْتَضٜىٰ مِن رَّسُولࣲ فَإِنَّهُۥ يَسْلُكُ مِنۢ بَيْنِ يَدَيْهِ وَمِنْ خَلْفِهِۦ رَصَداࣰ', 'ࡴلا من ࡴرتضى من رسول فإنه يسلك من بين يديه ومن خلفه رصدا', NULL, 573, 'local:warsh-text.json'),
  ('warsh-72-28', 'warsh', 72, 28, 'لِّيَعْلَمَ أَن قَدَ ࡰبْلَغُواْ رِسَٰلَٰتِ رَبِّهِمْ وَأَحَاطَ بِمَا لَدَيْهِمْ وَأَحْصٜىٰ كُلَّ شَےْءٍ عَدَداࣰ࣌', 'ليعلم أن قد ࡰبلغوا رسلت ربهم وأحاط بما لديهم وأحصى كل شےء عددا࣌', NULL, 573, 'local:warsh-text.json'),
  ('warsh-73-1', 'warsh', 73, 1, 'يَٰٓأَيُّهَا ࡰ۬لْمُزَّمِّلُ قُمِ ࡴ۬ليْلَ إِلَّا قَلِيلاࣰ', 'يأيها ࡰلمزمل قم ࡴليل إلا قليلا', NULL, 574, 'local:warsh-text.json'),
  ('warsh-73-2', 'warsh', 73, 2, 'نِّصْفَهُۥٓ أَوُ ࡲ࢈نقُصْ مِنْهُ قَلِيلاً', 'نصفه أو ࡲ࢈نقص منه قليلا', NULL, 574, 'local:warsh-text.json'),
  ('warsh-73-3', 'warsh', 73, 3, 'ࡰوْ زِدْ عَلَيْهِ وَرَتِّلِ ࡴ۬لْقُرْءَانَ تَرْتِيلاً࣌', 'ࡰو زد عليه ورتل ࡴلقرءان ترتيلا࣌', NULL, 574, 'local:warsh-text.json'),
  ('warsh-73-4', 'warsh', 73, 4, 'ࡴنَّا سَنُلْقِے عَلَيْكَ قَوْلاࣰ ثَقِيلاً࣌', 'ࡴنا سنلقے عليك قولا ثقيلا࣌', NULL, 574, 'local:warsh-text.json'),
  ('warsh-73-5', 'warsh', 73, 5, 'ࡴنَّ نَاشِئَةَ ࡰ۬ليْلِ هِيَ أَشَدُّ وَطْـٔاࣰ وَأَقْوَمُ قِيلاً࣌', 'ࡴن ناشئة ࡰليل هي أشد وطا وأقوم قيلا࣌', NULL, 574, 'local:warsh-text.json'),
  ('warsh-73-6', 'warsh', 73, 6, 'ࡴنَّ لَكَ فِے ࡴ۬لنَّهٜارِ سَبْحاࣰ طَوِيلاࣰ࣌', 'ࡴن لك فے ࡴلنهار سبحا طويلا࣌', NULL, 574, 'local:warsh-text.json'),
  ('warsh-73-7', 'warsh', 73, 7, 'وَاذْكُرِ ࡴٜسْمَ رَبِّكَ وَتَبَتَّلِ ࡴلَيْهِ تَبْتِيلاࣰ࣌', 'واذكر ࡴسم ربك وتبتل ࡴليه تبتيلا࣌', NULL, 574, 'local:warsh-text.json'),
  ('warsh-73-8', 'warsh', 73, 8, 'رَّبُّ ࡲ۬لْمَشْرِقِ وَالْمَغْرِبِ࣌ لَآ إِلَٰهَ إِلَّا هُوَ࣌ فَاتَّخِذْهُ وَكِيلاࣰ࣌', 'رب ࡲلمشرق والمغرب࣌ لا إله إلا هو࣌ فاتخذه وكيلا࣌', NULL, 574, 'local:warsh-text.json'),
  ('warsh-73-9', 'warsh', 73, 9, 'وَاصْبِرْ عَلَىٰ مَا يَقُولُونَ࣌ وَاهْجُرْهُمْ هَجْراࣰ جَمِيلاࣰ࣌', 'واصبر على ما يقولون࣌ واهجرهم هجرا جميلا࣌', NULL, 574, 'local:warsh-text.json'),
  ('warsh-73-10', 'warsh', 73, 10, 'وَذَرْنِے وَالْمُكَذِّبِينَ أُوْلِے ࡴ۬لنَّعْمَةِ وَمَهِّلْهُمْ قَلِيلاً࣌', 'وذرنے والمكذبين أولے ࡴلنعمة ومهلهم قليلا࣌', NULL, 574, 'local:warsh-text.json'),
  ('warsh-73-11', 'warsh', 73, 11, 'ࡴنَّ لَدَيْنَآ أَنكَالاࣰ وَجَحِيماࣰ', 'ࡴن لدينا أنكالا وجحيما', NULL, 574, 'local:warsh-text.json'),
  ('warsh-73-12', 'warsh', 73, 12, 'وَطَعَاماࣰ ذَا غُصَّةࣲ وَعَذَاباً ࡰلِيماࣰ', 'وطعاما ذا غصة وعذابا ࡰليما', NULL, 574, 'local:warsh-text.json'),
  ('warsh-73-13', 'warsh', 73, 13, 'يَوْمَ تَرْجُفُ ࡲ۬لَارْضُ وَالْجِبَالُ وَكَانَتِ ࡴ۬لْجِبَالُ كَثِيباࣰ مَّهِيلاً࣌', 'يوم ترجف ࡲلارض والجبال وكانت ࡴلجبال كثيبا مهيلا࣌', NULL, 574, 'local:warsh-text.json'),
  ('warsh-73-14', 'warsh', 73, 14, 'ࡴنَّآ أَرْسَلْنَآ إِلَيْكُمْ رَسُولاࣰ شَٰهِداً عَلَيْكُمْ كَمَآ أَرْسَلْنَآ إِلَىٰ فِرْعَوْنَ رَسُولاࣰ', 'ࡴنا أرسلنا إليكم رسولا شهدا عليكم كما أرسلنا إلى فرعون رسولا', NULL, 574, 'local:warsh-text.json'),
  ('warsh-73-15', 'warsh', 73, 15, 'فَعَصٜىٰ فِرْعَوْنُ ࡲ۬لرَّسُولَ فَأَخَذْنَٰهُ أَخْذاࣰ وَبِيلاࣰ࣌', 'فعصى فرعون ࡲلرسول فأخذنه أخذا وبيلا࣌', NULL, 574, 'local:warsh-text.json'),
  ('warsh-73-16', 'warsh', 73, 16, 'فَكَيْفَ تَتَّقُونَ إِن كَفَرْتُمْ يَوْماࣰ يَجْعَلُ ࡲ۬لْوِلْدَٰنَ شِيباً ࡴ۬لسَّمَآءُ مُنفَطِرُۢ بِهِۦ࣌ كَانَ وَعْدُهُۥ مَفْعُولاً࣌', 'فكيف تتقون إن كفرتم يوما يجعل ࡲلولدن شيبا ࡴلسماء منفطر به࣌ كان وعده مفعولا࣌', NULL, 574, 'local:warsh-text.json'),
  ('warsh-73-17', 'warsh', 73, 17, 'ࡴنَّ هَٰذِهِۦ تَذْكِرَةࣱ࣌ فَمَن شَآءَ ࡰٜتَّخَذَ إِلَىٰ رَبِّهِۦ سَبِيلاً࣌', 'ࡴن هذه تذكرة࣌ فمن شاء ࡰتخذ إلى ربه سبيلا࣌', NULL, 574, 'local:warsh-text.json'),
  ('warsh-73-18', 'warsh', 73, 18, '۞ ࡴنَّ رَبَّكَ يَعْلَمُ أَنَّكَ تَقُومُ أَدْنٜىٰ مِن ثُلُثَيِ ࡴ۬ليْلِ وَنِصْفِهِۦ وَثُلُثِهِۦ وَطَآئِفَةࣱ مِّنَ ࡰ۬لذِينَ مَعَكَ࣌ وَاللَّهُ يُقَدِّرُ ࡲ۬ليْلَ وَالنَّهَارَ࣌ عَلِمَ أَن لَّن تُحْصُوهُ فَتَابَ عَلَيْكُمْ࣌ فَاقْرَءُواْ مَا تَيَسَّرَ مِنَ ࡰ۬لْقُرْءَانِ࣌ عَلِمَ أَن سَيَكُونُ مِنكُم مَّرْضٜىٰ وَءَاخَرُونَ يَضْرِبُونَ فِے ࡴ۬لَارْضِ يَبْتَغُونَ مِن فَضْلِ ࡴ۬للَّهِ وَءَاخَرُونَ يُقَٰتِلُونَ فِے سَبِيلِ ࡴ۬للَّهِ࣌ فَاقْرَءُواْ مَا تَيَسَّرَ مِنْهُ࣌ وَأَقِيمُواْ ࡲ۬لصَّلَوٰةَ وَءَاتُواْ ࡲ۬لزَّكَوٰةَ࣌ وَأَقْرِضُواْ ࡲ۬للَّهَ قَرْضاً حَسَناࣰ࣌ وَمَا تُقَدِّمُواْ لِأَنفُسِكُم مِّنْ خَيْرࣲ تَجِدُوهُ عِندَ ࡰ۬للَّهِ هُوَ خَيْراࣰ وَأَعْظَمَ أَجْراࣰ࣌ وَاسْتَغْفِرُواْ ࡲ۬للَّهَ࣌ إِنَّ ࡰ۬للَّهَ غَفُورࣱ رَّحِيمࣱ࣌', 'ࡴن ربك يعلم أنك تقوم أدنى من ثلثي ࡴليل ونصفه وثلثه وطائفة من ࡰلذين معك࣌ والله يقدر ࡲليل والنهار࣌ علم أن لن تحصوه فتاب عليكم࣌ فاقرءوا ما تيسر من ࡰلقرءان࣌ علم أن سيكون منكم مرضى وءاخرون يضربون فے ࡴلارض يبتغون من فضل ࡴلله وءاخرون يقتلون فے سبيل ࡴلله࣌ فاقرءوا ما تيسر منه࣌ وأقيموا ࡲلصلوة وءاتوا ࡲلزكوة࣌ وأقرضوا ࡲلله قرضا حسنا࣌ وما تقدموا لأنفسكم من خير تجدوه عند ࡰلله هو خيرا وأعظم أجرا࣌ واستغفروا ࡲلله࣌ إن ࡰلله غفور رحيم࣌', NULL, 575, 'local:warsh-text.json'),
  ('warsh-74-1', 'warsh', 74, 1, 'يَٰٓأَيُّهَا ࡰ۬لْمُدَّثِّرُ', 'يأيها ࡰلمدثر', NULL, 575, 'local:warsh-text.json'),
  ('warsh-74-2', 'warsh', 74, 2, 'قُمْ فَأَنذِرْ࣌', 'قم فأنذر࣌', NULL, 575, 'local:warsh-text.json'),
  ('warsh-74-3', 'warsh', 74, 3, 'وَرَبَّكَ فَكَبِّرْ࣌', 'وربك فكبر࣌', NULL, 575, 'local:warsh-text.json'),
  ('warsh-74-4', 'warsh', 74, 4, 'وَثِيَابَكَ فَطَهِّرْ࣌', 'وثيابك فطهر࣌', NULL, 575, 'local:warsh-text.json'),
  ('warsh-74-5', 'warsh', 74, 5, 'وَالرِّجْزَ فَاهْجُرْ࣌', 'والرجز فاهجر࣌', NULL, 575, 'local:warsh-text.json'),
  ('warsh-74-6', 'warsh', 74, 6, 'وَلَا تَمْنُن تَسْتَكْثِرُ࣌', 'ولا تمنن تستكثر࣌', NULL, 575, 'local:warsh-text.json'),
  ('warsh-74-7', 'warsh', 74, 7, 'وَلِرَبِّكَ فَاصْبِرْ࣌', 'ولربك فاصبر࣌', NULL, 575, 'local:warsh-text.json'),
  ('warsh-74-8', 'warsh', 74, 8, 'فَإِذَا نُقِرَ فِے ࡴ۬لنَّاقُورِ', 'فإذا نقر فے ࡴلناقور', NULL, 575, 'local:warsh-text.json'),
  ('warsh-74-9', 'warsh', 74, 9, 'فَذَٰلِكَ يَوْمَئِذࣲ يَوْمٌ عَسِيرٌ', 'فذلك يومئذ يوم عسير', NULL, 575, 'local:warsh-text.json'),
  ('warsh-74-10', 'warsh', 74, 10, 'عَلَى ࡰ۬لْكٜـٰفِرِينَ غَيْرُ يَسِيرࣲ࣌', 'على ࡰلكفرين غير يسير࣌', NULL, 575, 'local:warsh-text.json'),
  ('warsh-74-11', 'warsh', 74, 11, 'ذَرْنِے وَمَنْ خَلَقْتُ وَحِيداࣰ', 'ذرنے ومن خلقت وحيدا', NULL, 575, 'local:warsh-text.json'),
  ('warsh-74-12', 'warsh', 74, 12, 'وَجَعَلْتُ لَهُۥ مَالاࣰ مَّمْدُوداࣰ', 'وجعلت له مالا ممدودا', NULL, 575, 'local:warsh-text.json'),
  ('warsh-74-13', 'warsh', 74, 13, 'وَبَنِينَ شُهُوداࣰ', 'وبنين شهودا', NULL, 575, 'local:warsh-text.json'),
  ('warsh-74-14', 'warsh', 74, 14, 'وَمَهَّدتُّ لَهُۥ تَمْهِيداࣰ', 'ومهدت له تمهيدا', NULL, 575, 'local:warsh-text.json'),
  ('warsh-74-15', 'warsh', 74, 15, 'ثُمَّ يَطْمَعُ أَنَ ࡰزِيدَ', 'ثم يطمع أن ࡰزيد', NULL, 575, 'local:warsh-text.json'),
  ('warsh-74-16', 'warsh', 74, 16, 'كَلَّآ࣌ إِنَّهُۥ كَانَ لِأٓيَٰتِنَا عَنِيداࣰ࣌', 'كلا࣌ إنه كان لأيتنا عنيدا࣌', NULL, 575, 'local:warsh-text.json'),
  ('warsh-74-17', 'warsh', 74, 17, 'سَأُرْهِقُهُۥ صَعُوداً࣌', 'سأرهقه صعودا࣌', NULL, 575, 'local:warsh-text.json'),
  ('warsh-74-18', 'warsh', 74, 18, 'ࡴنَّهُۥ فَكَّرَ وَقَدَّرَ', 'ࡴنه فكر وقدر', NULL, 575, 'local:warsh-text.json'),
  ('warsh-74-19', 'warsh', 74, 19, 'فَقُتِلَ كَيْفَ قَدَّرَ', 'فقتل كيف قدر', NULL, 576, 'local:warsh-text.json'),
  ('warsh-74-20', 'warsh', 74, 20, 'ثُمَّ قُتِلَ كَيْفَ قَدَّرَ', 'ثم قتل كيف قدر', NULL, 576, 'local:warsh-text.json'),
  ('warsh-74-21', 'warsh', 74, 21, 'ثُمَّ نَظَرَ', 'ثم نظر', NULL, 576, 'local:warsh-text.json'),
  ('warsh-74-22', 'warsh', 74, 22, 'ثُمَّ عَبَسَ وَبَسَرَ', 'ثم عبس وبسر', NULL, 576, 'local:warsh-text.json'),
  ('warsh-74-23', 'warsh', 74, 23, 'ثُمَّ أَدْبَرَ وَاسْتَكْبَرَ', 'ثم أدبر واستكبر', NULL, 576, 'local:warsh-text.json'),
  ('warsh-74-24', 'warsh', 74, 24, 'فَقَالَ إِنْ هَٰذَآ إِلَّا سِحْرࣱ يُوثَرُ', 'فقال إن هذا إلا سحر يوثر', NULL, 576, 'local:warsh-text.json'),
  ('warsh-74-25', 'warsh', 74, 25, 'إِنْ هَٰذَآ إِلَّا قَوْلُ ࡲ۬لْبَشَرِ࣌', 'إن هذا إلا قول ࡲلبشر࣌', NULL, 576, 'local:warsh-text.json'),
  ('warsh-74-26', 'warsh', 74, 26, 'سَأُصْلِيهِ سَقَرَ࣌', 'سأصليه سقر࣌', NULL, 576, 'local:warsh-text.json'),
  ('warsh-74-27', 'warsh', 74, 27, 'وَمَآ أَدْرٜيٰكَ مَا سَقَرُ࣌', 'وما أدريك ما سقر࣌', NULL, 576, 'local:warsh-text.json'),
  ('warsh-74-28', 'warsh', 74, 28, 'لَا تُبْقِے وَلَا تَذَرُ࣌', 'لا تبقے ولا تذر࣌', NULL, 576, 'local:warsh-text.json'),
  ('warsh-74-29', 'warsh', 74, 29, 'لَوَّاحَةࣱ لِّلْبَشَرِ࣌', 'لواحة للبشر࣌', NULL, 576, 'local:warsh-text.json'),
  ('warsh-74-30', 'warsh', 74, 30, 'عَلَيْهَا تِسْعَةَ عَشَرَ࣌', 'عليها تسعة عشر࣌', NULL, 576, 'local:warsh-text.json'),
  ('warsh-74-31', 'warsh', 74, 31, '۞ وَمَا جَعَلْنَآ أَصْحَٰبَ ࡰ۬لنّٜارِ إِلَّا مَلَٰٓئِكَةࣰ࣌ وَمَا جَعَلْنَا عِدَّتَهُمُۥٓ إِلَّا فِتْنَةࣰ لِّلذِينَ كَفَرُواْ لِيَسْتَيْقِنَ ࡰ۬لذِينَ أُوتُواْ ࡲ۬لْكِتَٰبَ وَيَزْدَادَ ࡰ۬لذِينَ ءَامَنُوٓاْ إِيمَٰناࣰ وَلَا يَرْتَابَ ࡰ۬لذِينَ أُوتُواْ ࡲ۬لْكِتَٰبَ وَالْمُومِنُونَ وَلِيَقُولَ ࡰ۬لذِينَ فِے قُلُوبِهِم مَّرَضࣱ وَالْكَٰفِرُونَ مَاذَآ أَرَادَ ࡰ۬للَّهُ بِهَٰذَا مَثَلاࣰ࣌ كَذَٰلِكَ يُضِلُّ ࡲ۬للَّهُ مَنْ يَّشَآءُ وَيَهْدِے مَنْ يَّشَآءُ࣌ وَمَا يَعْلَمُ جُنُودَ رَبِّكَ إِلَّا هُوَ࣌ وَمَا هِيَ إِلَّا ذِكْرٜىٰ لِلْبَشَرِ࣌', 'وما جعلنا أصحب ࡰلنار إلا ملئكة࣌ وما جعلنا عدتهم إلا فتنة للذين كفروا ليستيقن ࡰلذين أوتوا ࡲلكتب ويزداد ࡰلذين ءامنوا إيمنا ولا يرتاب ࡰلذين أوتوا ࡲلكتب والمومنون وليقول ࡰلذين فے قلوبهم مرض والكفرون ماذا أراد ࡰلله بهذا مثلا࣌ كذلك يضل ࡲلله من يشاء ويهدے من يشاء࣌ وما يعلم جنود ربك إلا هو࣌ وما هي إلا ذكرى للبشر࣌', NULL, 576, 'local:warsh-text.json'),
  ('warsh-74-32', 'warsh', 74, 32, 'كَلَّا وَالْقَمَرِ', 'كلا والقمر', NULL, 576, 'local:warsh-text.json'),
  ('warsh-74-33', 'warsh', 74, 33, 'وَاليْلِ إِذَ ࡰدْبَرَ', 'واليل إذ ࡰدبر', NULL, 576, 'local:warsh-text.json'),
  ('warsh-74-34', 'warsh', 74, 34, 'وَالصُّبْحِ إِذَآ أَسْفَرَ', 'والصبح إذا أسفر', NULL, 576, 'local:warsh-text.json'),
  ('warsh-74-35', 'warsh', 74, 35, 'إِنَّهَا لَإِحْدَى ࡰ۬لْكُبَرِ', 'إنها لإحدى ࡰلكبر', NULL, 576, 'local:warsh-text.json'),
  ('warsh-74-36', 'warsh', 74, 36, 'نَذِيراࣰ لِّلْبَشَرِ', 'نذيرا للبشر', NULL, 576, 'local:warsh-text.json'),
  ('warsh-74-37', 'warsh', 74, 37, 'لِمَن شَآءَ مِنكُمُۥٓ أَنْ يَّتَقَدَّمَ أَوْ يَتَأَخَّرَ࣌', 'لمن شاء منكم أن يتقدم أو يتأخر࣌', NULL, 576, 'local:warsh-text.json'),
  ('warsh-74-38', 'warsh', 74, 38, 'كُلُّ نَفْسِۢ بِمَا كَسَبَتْ رَهِينَةٌ', 'كل نفس بما كسبت رهينة', NULL, 576, 'local:warsh-text.json'),
  ('warsh-74-39', 'warsh', 74, 39, 'ࡴلَّآ أَصْحَٰبَ ࡰ۬لْيَمِينِ࣌', 'ࡴلا أصحب ࡰليمين࣌', NULL, 576, 'local:warsh-text.json'),
  ('warsh-74-40', 'warsh', 74, 40, 'فِے جَنَّٰتࣲ يَتَسَآءَلُونَ عَنِ ࡴ۬لْمُجْرِمِينَ', 'فے جنت يتساءلون عن ࡴلمجرمين', NULL, 576, 'local:warsh-text.json'),
  ('warsh-74-41', 'warsh', 74, 41, 'مَا سَلَكَكُمْ فِے سَقَرَ࣌', 'ما سلككم فے سقر࣌', NULL, 576, 'local:warsh-text.json'),
  ('warsh-74-42', 'warsh', 74, 42, 'قَالُواْ لَمْ نَكُ مِنَ ࡰ۬لْمُصَلِّينَ', 'قالوا لم نك من ࡰلمصلين', NULL, 576, 'local:warsh-text.json'),
  ('warsh-74-43', 'warsh', 74, 43, 'وَلَمْ نَكُ نُطْعِمُ ࡲ۬لْمِسْكِينَ', 'ولم نك نطعم ࡲلمسكين', NULL, 576, 'local:warsh-text.json'),
  ('warsh-74-44', 'warsh', 74, 44, 'وَكُنَّا نَخُوضُ مَعَ ࡰ۬لْخَآئِضِينَ', 'وكنا نخوض مع ࡰلخائضين', NULL, 576, 'local:warsh-text.json'),
  ('warsh-74-45', 'warsh', 74, 45, 'وَكُنَّا نُكَذِّبُ بِيَوْمِ ࡴ۬لدِّينِ', 'وكنا نكذب بيوم ࡴلدين', NULL, 576, 'local:warsh-text.json'),
  ('warsh-74-46', 'warsh', 74, 46, 'حَتَّىٰٓ أَتٜيٰنَا ࡰ۬لْيَقِينُ࣌', 'حتى أتينا ࡰليقين࣌', NULL, 576, 'local:warsh-text.json'),
  ('warsh-74-47', 'warsh', 74, 47, 'فَمَا تَنفَعُهُمْ شَفَٰعَةُ ࡲ۬لشَّٰفِعِينَ࣌', 'فما تنفعهم شفعة ࡲلشفعين࣌', NULL, 577, 'local:warsh-text.json'),
  ('warsh-74-48', 'warsh', 74, 48, 'فَمَا لَهُمْ عَنِ ࡴ۬لتَّذْكِرَةِ مُعْرِضِينَ', 'فما لهم عن ࡴلتذكرة معرضين', NULL, 577, 'local:warsh-text.json'),
  ('warsh-74-49', 'warsh', 74, 49, 'كَأَنَّهُمْ حُمُرࣱ مُّسْتَنفَرَةࣱ', 'كأنهم حمر مستنفرة', NULL, 577, 'local:warsh-text.json'),
  ('warsh-74-50', 'warsh', 74, 50, 'فَرَّتْ مِن قَسْوَرَةِۢ࣌', 'فرت من قسورة࣌', NULL, 577, 'local:warsh-text.json'),
  ('warsh-74-51', 'warsh', 74, 51, 'بَلْ يُرِيدُ كُلُّ ࡲٜمْرِےࣲٕ مِّنْهُمُۥٓ أَنْ يُّوتٜىٰ صُحُفاࣰ مُّنَشَّرَةࣰ࣌', 'بل يريد كل ࡲمرے منهم أن يوتى صحفا منشرة࣌', NULL, 577, 'local:warsh-text.json'),
  ('warsh-74-52', 'warsh', 74, 52, 'كَلَّا بَل لَّا يَخَافُونَ ࡰ۬لَاخِرَةَ࣌', 'كلا بل لا يخافون ࡰلاخرة࣌', NULL, 577, 'local:warsh-text.json'),
  ('warsh-74-53', 'warsh', 74, 53, 'كَلَّآ إِنَّهُۥ تَذْكِرَةࣱ࣌', 'كلا إنه تذكرة࣌', NULL, 577, 'local:warsh-text.json'),
  ('warsh-74-54', 'warsh', 74, 54, 'فَمَن شَآءَ ذَكَرَهُۥ࣌', 'فمن شاء ذكره࣌', NULL, 577, 'local:warsh-text.json'),
  ('warsh-74-55', 'warsh', 74, 55, 'وَمَا تَذْكُرُونَ إِلَّآ أَنْ يَّشَآءَ ࡰ۬للَّهُ࣌ هُوَ أَهْلُ ࡲ۬لتَّقْوٜىٰ وَأَهْلُ ࡲ۬لْمَغْفِرَةِ࣌', 'وما تذكرون إلا أن يشاء ࡰلله࣌ هو أهل ࡲلتقوى وأهل ࡲلمغفرة࣌', NULL, 577, 'local:warsh-text.json'),
  ('warsh-75-1', 'warsh', 75, 1, 'لَآ أُقْسِمُ بِيَوْمِ ࡴ۬لْقِيَٰمَةِ', 'لا أقسم بيوم ࡴلقيمة', NULL, 577, 'local:warsh-text.json'),
  ('warsh-75-2', 'warsh', 75, 2, 'وَلَآ أُقْسِمُ بِالنَّفْسِ ࡴ۬للَّوَّامَةِ࣌', 'ولا أقسم بالنفس ࡴللوامة࣌', NULL, 577, 'local:warsh-text.json'),
  ('warsh-75-3', 'warsh', 75, 3, 'أَيَحْسِبُ ࡲ۬لِانسَٰنُ أَلَّن نَّجْمَعَ عِظَامَهُۥ', 'أيحسب ࡲلانسن ألن نجمع عظامه', NULL, 577, 'local:warsh-text.json'),
  ('warsh-75-4', 'warsh', 75, 4, 'بَلٜىٰ࣌ قَٰدِرِينَ عَلَىٰٓ أَن نُّسَوِّيَ بَنَانَهُۥ࣌', 'بلى࣌ قدرين على أن نسوي بنانه࣌', NULL, 577, 'local:warsh-text.json'),
  ('warsh-75-5', 'warsh', 75, 5, 'بَلْ يُرِيدُ ࡲ۬لِانسَٰنُ لِيَفْجُرَ أَمَامَهُۥ࣌', 'بل يريد ࡲلانسن ليفجر أمامه࣌', NULL, 577, 'local:warsh-text.json'),
  ('warsh-75-6', 'warsh', 75, 6, 'يَسْـَٔلُ أَيَّانَ يَوْمُ ࡲ۬لْقِيَٰمَةِ࣌', 'يسل أيان يوم ࡲلقيمة࣌', NULL, 577, 'local:warsh-text.json'),
  ('warsh-75-7', 'warsh', 75, 7, 'فَإِذَا بَرَقَ ࡰ۬لْبَصَرُ', 'فإذا برق ࡰلبصر', NULL, 577, 'local:warsh-text.json'),
  ('warsh-75-8', 'warsh', 75, 8, 'وَخَسَفَ ࡰ۬لْقَمَرُ', 'وخسف ࡰلقمر', NULL, 577, 'local:warsh-text.json'),
  ('warsh-75-9', 'warsh', 75, 9, 'وَجُمِعَ ࡰ۬لشَّمْسُ وَالْقَمَرُ', 'وجمع ࡰلشمس والقمر', NULL, 577, 'local:warsh-text.json'),
  ('warsh-75-10', 'warsh', 75, 10, 'يَقُولُ ࡲ۬لِانسَٰنُ يَوْمَئِذٍ ࡰيْنَ ࡰ۬لْمَفَرُّ࣌', 'يقول ࡲلانسن يومئذ ࡰين ࡰلمفر࣌', NULL, 577, 'local:warsh-text.json'),
  ('warsh-75-11', 'warsh', 75, 11, 'كَلَّا لَا وَزَرَ࣌', 'كلا لا وزر࣌', NULL, 577, 'local:warsh-text.json'),
  ('warsh-75-12', 'warsh', 75, 12, 'إِلَىٰ رَبِّكَ يَوْمَئِذٍ ࡴ۬لْمُسْتَقَرُّ࣌', 'إلى ربك يومئذ ࡴلمستقر࣌', NULL, 577, 'local:warsh-text.json'),
  ('warsh-75-13', 'warsh', 75, 13, 'يُنَبَّؤُاْ ࡲ۬لِانسَٰنُ يَوْمَئِذِۢ بِمَا قَدَّمَ وَأَخَّرَ࣌', 'ينبؤا ࡲلانسن يومئذ بما قدم وأخر࣌', NULL, 577, 'local:warsh-text.json'),
  ('warsh-75-14', 'warsh', 75, 14, 'بَلِ ࡴ۬لِانسَٰنُ عَلَىٰ نَفْسِهِۦ بَصِيرَةࣱ', 'بل ࡴلانسن على نفسه بصيرة', NULL, 577, 'local:warsh-text.json'),
  ('warsh-75-15', 'warsh', 75, 15, 'وَلَوَ ࡰلْقٜىٰ مَعَاذِيرَهُۥ࣌', 'ولو ࡰلقى معاذيره࣌', NULL, 577, 'local:warsh-text.json'),
  ('warsh-75-16', 'warsh', 75, 16, 'لَا تُحَرِّكْ بِهِۦ لِسَانَكَ لِتَعْجَلَ بِهِۦٓ࣌ إِنَّ عَلَيْنَا جَمْعَهُۥ وَقُرْءَانَهُۥ࣌', 'لا تحرك به لسانك لتعجل به࣌ إن علينا جمعه وقرءانه࣌', NULL, 577, 'local:warsh-text.json'),
  ('warsh-75-17', 'warsh', 75, 17, 'فَإِذَا قَرَأْنَٰهُ فَاتَّبِعْ قُرْءَانَهُۥ', 'فإذا قرأنه فاتبع قرءانه', NULL, 577, 'local:warsh-text.json'),
  ('warsh-75-18', 'warsh', 75, 18, 'ثُمَّ إِنَّ عَلَيْنَا بَيَانَهُۥ࣌', 'ثم إن علينا بيانه࣌', NULL, 577, 'local:warsh-text.json'),
  ('warsh-75-19', 'warsh', 75, 19, 'كَلَّا بَلْ تُحِبُّونَ ࡰ۬لْعَاجِلَةَ', 'كلا بل تحبون ࡰلعاجلة', NULL, 578, 'local:warsh-text.json'),
  ('warsh-75-20', 'warsh', 75, 20, 'وَتَذَرُونَ ࡰ۬لَاخِرَةَ࣌', 'وتذرون ࡰلاخرة࣌', NULL, 578, 'local:warsh-text.json'),
  ('warsh-75-21', 'warsh', 75, 21, 'وُجُوهࣱ يَوْمَئِذࣲ نَّاضِرَةٌ', 'وجوه يومئذ ناضرة', NULL, 578, 'local:warsh-text.json'),
  ('warsh-75-22', 'warsh', 75, 22, 'ࡴلَىٰ رَبِّهَا نَاظِرَةࣱ࣌', 'ࡴلى ربها ناظرة࣌', NULL, 578, 'local:warsh-text.json'),
  ('warsh-75-23', 'warsh', 75, 23, 'وَوُجُوهࣱ يَوْمَئِذِۢ بَاسِرَةࣱ', 'ووجوه يومئذ باسرة', NULL, 578, 'local:warsh-text.json'),
  ('warsh-75-24', 'warsh', 75, 24, 'تَظُنُّ أَنْ يُّفْعَلَ بِهَا فَاقِرَةࣱ࣌', 'تظن أن يفعل بها فاقرة࣌', NULL, 578, 'local:warsh-text.json'),
  ('warsh-75-25', 'warsh', 75, 25, 'كَلَّآ إِذَا بَلَغَتِ ࡴ۬لتَّرَاقِيَ', 'كلا إذا بلغت ࡴلتراقي', NULL, 578, 'local:warsh-text.json'),
  ('warsh-75-26', 'warsh', 75, 26, 'وَقِيلَ مَن رَّاقࣲ', 'وقيل من راق', NULL, 578, 'local:warsh-text.json'),
  ('warsh-75-27', 'warsh', 75, 27, 'وَظَنَّ أَنَّهُ ࡲ۬لْفِرَاقُ', 'وظن أنه ࡲلفراق', NULL, 578, 'local:warsh-text.json'),
  ('warsh-75-28', 'warsh', 75, 28, 'وَالْتَفَّتِ ࡴ۬لسَّاقُ بِالسَّاقِ', 'والتفت ࡴلساق بالساق', NULL, 578, 'local:warsh-text.json'),
  ('warsh-75-29', 'warsh', 75, 29, 'إِلَىٰ رَبِّكَ يَوْمَئِذٍ ࡴ۬لْمَسَاقُ࣌', 'إلى ربك يومئذ ࡴلمساق࣌', NULL, 578, 'local:warsh-text.json'),
  ('warsh-75-30', 'warsh', 75, 30, 'فَلَا صَدَّقَ وَلَا صَلّٜىٰ࣌', 'فلا صدق ولا صلى࣌', NULL, 578, 'local:warsh-text.json'),
  ('warsh-75-31', 'warsh', 75, 31, 'وَلَٰكِن كَذَّبَ وَتَوَلّٜىٰ࣌', 'ولكن كذب وتولى࣌', NULL, 578, 'local:warsh-text.json'),
  ('warsh-75-32', 'warsh', 75, 32, 'ثُمَّ ذَهَبَ إِلَىٰٓ أَهْلِهِۦ يَتَمَطّٜىٰٓ࣌', 'ثم ذهب إلى أهله يتمطى࣌', NULL, 578, 'local:warsh-text.json'),
  ('warsh-75-33', 'warsh', 75, 33, 'أَوْلٜىٰ لَكَ فَأَوْلٜىٰ', 'أولى لك فأولى', NULL, 578, 'local:warsh-text.json'),
  ('warsh-75-34', 'warsh', 75, 34, 'ثُمَّ أَوْلٜىٰ لَكَ فَأَوْلٜىٰٓ࣌', 'ثم أولى لك فأولى࣌', NULL, 578, 'local:warsh-text.json'),
  ('warsh-75-35', 'warsh', 75, 35, 'أَيَحْسِبُ ࡲ۬لِانسَٰنُ أَنْ يُّتْرَكَ سُدىً࣌', 'أيحسب ࡲلانسن أن يترك سدى࣌', NULL, 578, 'local:warsh-text.json'),
  ('warsh-75-36', 'warsh', 75, 36, 'ࡰلَمْ يَكُ نُطْفَةࣰ مِّن مَّنِيࣲّ تُمْنٜىٰ', 'ࡰلم يك نطفة من مني تمنى', NULL, 578, 'local:warsh-text.json'),
  ('warsh-75-37', 'warsh', 75, 37, 'ثُمَّ كَانَ عَلَقَةࣰ فَخَلَقَ فَسَوّٜىٰ', 'ثم كان علقة فخلق فسوى', NULL, 578, 'local:warsh-text.json'),
  ('warsh-75-38', 'warsh', 75, 38, 'فَجَعَلَ مِنْهُ ࡲ۬لزَّوْجَيْنِ ࡴ۬لذَّكَرَ وَالُانثٜىٰٓ࣌', 'فجعل منه ࡲلزوجين ࡴلذكر والانثى࣌', NULL, 578, 'local:warsh-text.json'),
  ('warsh-75-39', 'warsh', 75, 39, 'أَلَيْسَ ذَٰلِكَ بِقَٰدِرٍ عَلَىٰٓ أَنْ يُّحْۑِيَ ࡰ۬لْمَوْتٜىٰ࣌', 'أليس ذلك بقدر على أن يحۑي ࡰلموتى࣌', NULL, 578, 'local:warsh-text.json'),
  ('warsh-76-1', 'warsh', 76, 1, 'هَلَ ࡰتٜىٰ عَلَى ࡰ۬لِانسَٰنِ حِينࣱ مِّنَ ࡰ۬لدَّهْرِ لَمْ يَكُن شَيْـٔاࣰ مَّذْكُوراً࣌', 'هل ࡰتى على ࡰلانسن حين من ࡰلدهر لم يكن شيا مذكورا࣌', NULL, 578, 'local:warsh-text.json'),
  ('warsh-76-2', 'warsh', 76, 2, 'ࡴنَّا خَلَقْنَا ࡰ۬لِانسَٰنَ مِن نُّطْفَةٍ ࡰمْشَاجࣲ نَّبْتَلِيهِ فَجَعَلْنَٰهُ سَمِيعاَۢ بَصِيراً࣌', 'ࡴنا خلقنا ࡰلانسن من نطفة ࡰمشاج نبتليه فجعلنه سميعا بصيرا࣌', NULL, 578, 'local:warsh-text.json'),
  ('warsh-76-3', 'warsh', 76, 3, 'ࡴنَّا هَدَيْنَٰهُ ࡲ۬لسَّبِيلَ إِمَّا شَاكِراࣰ وَإِمَّا كَفُوراً࣌', 'ࡴنا هدينه ࡲلسبيل إما شاكرا وإما كفورا࣌', NULL, 578, 'local:warsh-text.json'),
  ('warsh-76-4', 'warsh', 76, 4, 'ࡴنَّآ أَعْتَدْنَا لِلْكٜـٰفِرِينَ سَلَٰسِلاࣰ وَأَغْلَٰلاࣰ وَسَعِيراً࣌', 'ࡴنا أعتدنا للكفرين سلسلا وأغللا وسعيرا࣌', NULL, 578, 'local:warsh-text.json'),
  ('warsh-76-5', 'warsh', 76, 5, 'ࡴنَّ ࡰ۬لَابْرَارَ يَشْرَبُونَ مِن كَأْسࣲ كَانَ مِزَاجُهَا كَافُوراً', 'ࡴن ࡰلابرار يشربون من كأس كان مزاجها كافورا', NULL, 578, 'local:warsh-text.json'),
  ('warsh-76-6', 'warsh', 76, 6, 'عَيْناࣰ يَشْرَبُ بِهَا عِبَادُ ࡲ۬للَّهِ يُفَجِّرُونَهَا تَفْجِيراࣰ࣌', 'عينا يشرب بها عباد ࡲلله يفجرونها تفجيرا࣌', NULL, 579, 'local:warsh-text.json'),
  ('warsh-76-7', 'warsh', 76, 7, 'يُوفُونَ بِالنَّذْرِ وَيَخَافُونَ يَوْماࣰ كَانَ شَرُّهُۥ مُسْتَطِيراࣰ࣌', 'يوفون بالنذر ويخافون يوما كان شره مستطيرا࣌', NULL, 579, 'local:warsh-text.json'),
  ('warsh-76-8', 'warsh', 76, 8, 'وَيُطْعِمُونَ ࡰ۬لطَّعَامَ عَلَىٰ حُبِّهِۦ مِسْكِيناࣰ وَيَتِيماࣰ وَأَسِيراً', 'ويطعمون ࡰلطعام على حبه مسكينا ويتيما وأسيرا', NULL, 579, 'local:warsh-text.json'),
  ('warsh-76-9', 'warsh', 76, 9, 'ࡴنَّمَا نُطْعِمُكُمْ لِوَجْهِ ࡴ۬للَّهِ࣌ لَا نُرِيدُ مِنكُمْ جَزَآءࣰ وَلَا شُكُوراً࣌', 'ࡴنما نطعمكم لوجه ࡴلله࣌ لا نريد منكم جزاء ولا شكورا࣌', NULL, 579, 'local:warsh-text.json'),
  ('warsh-76-10', 'warsh', 76, 10, 'ࡴنَّا نَخَافُ مِن رَّبِّنَا يَوْماً عَبُوساࣰ قَمْطَرِيراࣰ࣌', 'ࡴنا نخاف من ربنا يوما عبوسا قمطريرا࣌', NULL, 579, 'local:warsh-text.json'),
  ('warsh-76-11', 'warsh', 76, 11, 'فَوَقٜيٰهُمُ ࡲ۬للَّهُ شَرَّ ذَٰلِكَ ࡰ۬لْيَوْمِ وَلَقّٜيٰهُمْ نَضْرَةࣰ وَسُرُوراࣰ࣌', 'فوقيهم ࡲلله شر ذلك ࡰليوم ولقيهم نضرة وسرورا࣌', NULL, 579, 'local:warsh-text.json'),
  ('warsh-76-12', 'warsh', 76, 12, 'وَجَزٜيٰهُم بِمَا صَبَرُواْ جَنَّةࣰ وَحَرِيراࣰ', 'وجزيهم بما صبروا جنة وحريرا', NULL, 579, 'local:warsh-text.json'),
  ('warsh-76-13', 'warsh', 76, 13, 'مُّتَّكِـِٕينَ فِيهَا عَلَى ࡰ۬لَارَآئِكِ لَا يَرَوْنَ فِيهَا شَمْساࣰ وَلَا زَمْهَرِيراࣰ', 'متكين فيها على ࡰلارائك لا يرون فيها شمسا ولا زمهريرا', NULL, 579, 'local:warsh-text.json'),
  ('warsh-76-14', 'warsh', 76, 14, 'وَدَانِيَةً عَلَيْهِمْ ظِلَٰلُهَا وَذُلِّلَتْ قُطُوفُهَا تَذْلِيلاࣰ࣌', 'ودانية عليهم ظللها وذللت قطوفها تذليلا࣌', NULL, 579, 'local:warsh-text.json'),
  ('warsh-76-15', 'warsh', 76, 15, 'وَيُطَافُ عَلَيْهِم بِـَٔانِيَةࣲ مِّن فِضَّةࣲ وَأَكْوَابࣲ كَانَتْ قَوَارِيراࣰ࣌', 'ويطاف عليهم بانية من فضة وأكواب كانت قواريرا࣌', NULL, 579, 'local:warsh-text.json'),
  ('warsh-76-16', 'warsh', 76, 16, 'قَوَارِيراࣰ مِّن فِضَّةࣲ قَدَّرُوهَا تَقْدِيراࣰ࣌', 'قواريرا من فضة قدروها تقديرا࣌', NULL, 579, 'local:warsh-text.json'),
  ('warsh-76-17', 'warsh', 76, 17, 'وَيُسْقَوْنَ فِيهَا كَأْساࣰ كَانَ مِزَاجُهَا زَنجَبِيلاً', 'ويسقون فيها كأسا كان مزاجها زنجبيلا', NULL, 579, 'local:warsh-text.json'),
  ('warsh-76-18', 'warsh', 76, 18, 'عَيْناࣰ فِيهَا تُسَمّٜىٰ سَلْسَبِيلاࣰ࣌', 'عينا فيها تسمى سلسبيلا࣌', NULL, 579, 'local:warsh-text.json'),
  ('warsh-76-19', 'warsh', 76, 19, '۞ وَيَطُوفُ عَلَيْهِمْ وِلْدَٰنࣱ مُّخَلَّدُونَ إِذَا رَأَيْتَهُمْ حَسِبْتَهُمْ لُؤْلُؤاࣰ مَّنثُوراࣰ࣌', 'ويطوف عليهم ولدن مخلدون إذا رأيتهم حسبتهم لؤلؤا منثورا࣌', NULL, 579, 'local:warsh-text.json'),
  ('warsh-76-20', 'warsh', 76, 20, 'وَإِذَا رَأَيْتَ ثَمَّ رَأَيْتَ نَعِيماࣰ وَمُلْكاࣰ كَبِيراً', 'وإذا رأيت ثم رأيت نعيما وملكا كبيرا', NULL, 579, 'local:warsh-text.json'),
  ('warsh-76-21', 'warsh', 76, 21, 'عَٰلِيهِمْ ثِيَابُ سُندُسٍ خُضْرࣱ وَإِسْتَبْرَقࣱ࣌ وَحُلُّوٓاْ أَسَاوِرَ مِن فِضَّةࣲ࣌ وَسَقٜيٰهُمْ رَبُّهُمْ شَرَاباࣰ طَهُوراً࣌', 'عليهم ثياب سندس خضر وإستبرق࣌ وحلوا أساور من فضة࣌ وسقيهم ربهم شرابا طهورا࣌', NULL, 579, 'local:warsh-text.json'),
  ('warsh-76-22', 'warsh', 76, 22, 'ࡴنَّ هَٰذَا كَانَ لَكُمْ جَزَآءࣰ وَكَانَ سَعْيُكُم مَّشْكُوراً࣌', 'ࡴن هذا كان لكم جزاء وكان سعيكم مشكورا࣌', NULL, 579, 'local:warsh-text.json'),
  ('warsh-76-23', 'warsh', 76, 23, 'ࡴنَّا نَحْنُ نَزَّلْنَا عَلَيْكَ ࡰ۬لْقُرْءَانَ تَنزِيلاࣰ࣌', 'ࡴنا نحن نزلنا عليك ࡰلقرءان تنزيلا࣌', NULL, 579, 'local:warsh-text.json'),
  ('warsh-76-24', 'warsh', 76, 24, 'فَاصْبِرْ لِحُكْمِ رَبِّكَ وَلَا تُطِعْ مِنْهُمُۥٓ ءَاثِماً ࡰوْ كَفُوراࣰ࣌', 'فاصبر لحكم ربك ولا تطع منهم ءاثما ࡰو كفورا࣌', NULL, 579, 'local:warsh-text.json'),
  ('warsh-76-25', 'warsh', 76, 25, 'وَاذْكُرِ ࡴٜسْمَ رَبِّكَ بُكْرَةࣰ وَأَصِيلاࣰ࣌', 'واذكر ࡴسم ربك بكرة وأصيلا࣌', NULL, 579, 'local:warsh-text.json'),
  ('warsh-76-26', 'warsh', 76, 26, 'وَمِنَ ࡰ۬ليْلِ فَاسْجُدْ لَهُۥ وَسَبِّحْهُ لَيْلاࣰ طَوِيلاً࣌', 'ومن ࡰليل فاسجد له وسبحه ليلا طويلا࣌', NULL, 580, 'local:warsh-text.json'),
  ('warsh-76-27', 'warsh', 76, 27, 'ࡴنَّ هَٰٓؤُلَآءِ يُحِبُّونَ ࡰ۬لْعَاجِلَةَ وَيَذَرُونَ وَرَآءَهُمْ يَوْماࣰ ثَقِيلاࣰ࣌', 'ࡴن هؤلاء يحبون ࡰلعاجلة ويذرون وراءهم يوما ثقيلا࣌', NULL, 580, 'local:warsh-text.json'),
  ('warsh-76-28', 'warsh', 76, 28, 'نَّحْنُ خَلَقْنَٰهُمْ وَشَدَدْنَآ أَسْرَهُمْ وَإِذَا شِئْنَا بَدَّلْنَآ أَمْثَٰلَهُمْ تَبْدِيلاً࣌', 'نحن خلقنهم وشددنا أسرهم وإذا شئنا بدلنا أمثلهم تبديلا࣌', NULL, 580, 'local:warsh-text.json'),
  ('warsh-76-29', 'warsh', 76, 29, 'ࡴنَّ هَٰذِهِۦ تَذْكِرَةࣱ࣌ فَمَن شَآءَ ࡰٜتَّخَذَ إِلَىٰ رَبِّهِۦ سَبِيلاࣰ࣌', 'ࡴن هذه تذكرة࣌ فمن شاء ࡰتخذ إلى ربه سبيلا࣌', NULL, 580, 'local:warsh-text.json'),
  ('warsh-76-30', 'warsh', 76, 30, 'وَمَا تَشَآءُونَ إِلَّآ أَنْ يَّشَآءَ ࡰ۬للَّهُ࣌ إِنَّ ࡰ۬للَّهَ كَانَ عَلِيماً حَكِيماࣰ࣌', 'وما تشاءون إلا أن يشاء ࡰلله࣌ إن ࡰلله كان عليما حكيما࣌', NULL, 580, 'local:warsh-text.json'),
  ('warsh-76-31', 'warsh', 76, 31, 'يُدْخِلُ مَنْ يَّشَآءُ فِے رَحْمَتِهِۦ࣌ وَالظَّٰلِمِينَ أَعَدَّ لَهُمْ عَذَاباً ࡰلِيماࣰ࣌', 'يدخل من يشاء فے رحمته࣌ والظلمين أعد لهم عذابا ࡰليما࣌', NULL, 580, 'local:warsh-text.json'),
  ('warsh-77-1', 'warsh', 77, 1, 'وَالْمُرْسَلَٰتِ عُرْفاࣰ', 'والمرسلت عرفا', NULL, 580, 'local:warsh-text.json'),
  ('warsh-77-2', 'warsh', 77, 2, 'فَالْعَٰصِفَٰتِ عَصْفاࣰ', 'فالعصفت عصفا', NULL, 580, 'local:warsh-text.json')
insert into public.ayahs (id, riwayah, surah_number, ayah_number, text, simple_text, juz, page, source) values
  ('warsh-77-3', 'warsh', 77, 3, 'وَالنَّٰشِرَٰتِ نَشْراࣰ', 'والنشرت نشرا', NULL, 580, 'local:warsh-text.json'),
  ('warsh-77-4', 'warsh', 77, 4, 'فَالْفَٰرِقَٰتِ فَرْقاࣰ', 'فالفرقت فرقا', NULL, 580, 'local:warsh-text.json'),
  ('warsh-77-5', 'warsh', 77, 5, 'فَالْمُلْقِيَٰتِ ذِكْراً', 'فالملقيت ذكرا', NULL, 580, 'local:warsh-text.json'),
  ('warsh-77-6', 'warsh', 77, 6, 'عُذْراً ࡰوْ نُذُراً', 'عذرا ࡰو نذرا', NULL, 580, 'local:warsh-text.json'),
  ('warsh-77-7', 'warsh', 77, 7, 'ࡴنَّمَا تُوعَدُونَ لَوَٰقِعࣱ࣌', 'ࡴنما توعدون لوقع࣌', NULL, 580, 'local:warsh-text.json'),
  ('warsh-77-8', 'warsh', 77, 8, 'فَإِذَا ࡰ۬لنُّجُومُ طُمِسَتْ', 'فإذا ࡰلنجوم طمست', NULL, 580, 'local:warsh-text.json'),
  ('warsh-77-9', 'warsh', 77, 9, 'وَإِذَا ࡰ۬لسَّمَآءُ فُرِجَتْ', 'وإذا ࡰلسماء فرجت', NULL, 580, 'local:warsh-text.json'),
  ('warsh-77-10', 'warsh', 77, 10, 'وَإِذَا ࡰ۬لْجِبَالُ نُسِفَتْ', 'وإذا ࡰلجبال نسفت', NULL, 580, 'local:warsh-text.json'),
  ('warsh-77-11', 'warsh', 77, 11, 'وَإِذَا ࡰ۬لرُّسُلُ أُقِّتَتْ', 'وإذا ࡰلرسل أقتت', NULL, 580, 'local:warsh-text.json'),
  ('warsh-77-12', 'warsh', 77, 12, 'لِأَيِّ يَوْمٍ ࡳجِّلَتْ', 'لأي يوم ࡳجلت', NULL, 580, 'local:warsh-text.json'),
  ('warsh-77-13', 'warsh', 77, 13, 'لِيَوْمِ ࡴ۬لْفَصْلِ࣌', 'ليوم ࡴلفصل࣌', NULL, 580, 'local:warsh-text.json'),
  ('warsh-77-14', 'warsh', 77, 14, 'وَمَآ أَدْرٜيٰكَ مَا يَوْمُ ࡲ۬لْفَصْلِ࣌', 'وما أدريك ما يوم ࡲلفصل࣌', NULL, 580, 'local:warsh-text.json'),
  ('warsh-77-15', 'warsh', 77, 15, 'وَيْلࣱ يَوْمَئِذࣲ لِّلْمُكَذِّبِينَ࣌', 'ويل يومئذ للمكذبين࣌', NULL, 580, 'local:warsh-text.json'),
  ('warsh-77-16', 'warsh', 77, 16, '۞ أَلَمْ نُهْلِكِ ࡴ۬لَاوَّلِينَ࣌', 'ألم نهلك ࡴلاولين࣌', NULL, 580, 'local:warsh-text.json'),
  ('warsh-77-17', 'warsh', 77, 17, 'ثُمَّ نُتْبِعُهُمُ ࡲ۬لَاخِرِينَ࣌', 'ثم نتبعهم ࡲلاخرين࣌', NULL, 580, 'local:warsh-text.json'),
  ('warsh-77-18', 'warsh', 77, 18, 'كَذَٰلِكَ نَفْعَلُ بِالْمُجْرِمِينَ࣌', 'كذلك نفعل بالمجرمين࣌', NULL, 580, 'local:warsh-text.json'),
  ('warsh-77-19', 'warsh', 77, 19, 'وَيْلࣱ يَوْمَئِذࣲ لِّلْمُكَذِّبِينَ࣌', 'ويل يومئذ للمكذبين࣌', NULL, 580, 'local:warsh-text.json'),
  ('warsh-77-20', 'warsh', 77, 20, 'أَلَمْ نَخْلُقكُّم مِّن مَّآءࣲ مَّهِينࣲ', 'ألم نخلقكم من ماء مهين', NULL, 581, 'local:warsh-text.json'),
  ('warsh-77-21', 'warsh', 77, 21, 'فَجَعَلْنَٰهُ فِے قَرٜارࣲ مَّكِينٍ', 'فجعلنه فے قرار مكين', NULL, 581, 'local:warsh-text.json'),
  ('warsh-77-22', 'warsh', 77, 22, 'ࡴلَىٰ قَدَرࣲ مَّعْلُومࣲ', 'ࡴلى قدر معلوم', NULL, 581, 'local:warsh-text.json'),
  ('warsh-77-23', 'warsh', 77, 23, 'فَقَدَّرْنَا࣌ فَنِعْمَ ࡰ۬لْقَٰدِرُونَ࣌', 'فقدرنا࣌ فنعم ࡰلقدرون࣌', NULL, 581, 'local:warsh-text.json'),
  ('warsh-77-24', 'warsh', 77, 24, 'وَيْلࣱ يَوْمَئِذࣲ لِّلْمُكَذِّبِينَ࣌', 'ويل يومئذ للمكذبين࣌', NULL, 581, 'local:warsh-text.json'),
  ('warsh-77-25', 'warsh', 77, 25, 'أَلَمْ نَجْعَلِ ࡴ۬لَارْضَ كِفَاتاً', 'ألم نجعل ࡴلارض كفاتا', NULL, 581, 'local:warsh-text.json'),
  ('warsh-77-26', 'warsh', 77, 26, 'ࡰحْيَآءࣰ وَأَمْوَٰتاࣰ', 'ࡰحياء وأموتا', NULL, 581, 'local:warsh-text.json'),
  ('warsh-77-27', 'warsh', 77, 27, 'وَجَعَلْنَا فِيهَا رَوَٰسِيَ شَٰمِخَٰتࣲ وَأَسْقَيْنَٰكُم مَّآءࣰ فُرَاتاࣰ࣌', 'وجعلنا فيها روسي شمخت وأسقينكم ماء فراتا࣌', NULL, 581, 'local:warsh-text.json'),
  ('warsh-77-28', 'warsh', 77, 28, 'وَيْلࣱ يَوْمَئِذࣲ لِّلْمُكَذِّبِينَ࣌', 'ويل يومئذ للمكذبين࣌', NULL, 581, 'local:warsh-text.json'),
  ('warsh-77-29', 'warsh', 77, 29, 'ࡰٜنطَلِقُوٓاْ إِلَىٰ مَا كُنتُم بِهِۦ تُكَذِّبُونَ', 'ࡰنطلقوا إلى ما كنتم به تكذبون', NULL, 581, 'local:warsh-text.json'),
  ('warsh-77-30', 'warsh', 77, 30, 'ࡰٜنطَلِقُوٓاْ إِلَىٰ ظِلࣲّ ذِے ثَلَٰثِ شُعَبࣲ', 'ࡰنطلقوا إلى ظل ذے ثلث شعب', NULL, 581, 'local:warsh-text.json'),
  ('warsh-77-31', 'warsh', 77, 31, 'لَّا ظَلِيلࣲ وَلَا يُغْنِے مِنَ ࡰ۬للَّهَبِ࣌', 'لا ظليل ولا يغنے من ࡰللهب࣌', NULL, 581, 'local:warsh-text.json'),
  ('warsh-77-32', 'warsh', 77, 32, 'إِنَّهَا تَرْمِے بِشَرَرࣲ كَالْقَصْرِ', 'إنها ترمے بشرر كالقصر', NULL, 581, 'local:warsh-text.json'),
  ('warsh-77-33', 'warsh', 77, 33, 'كَأَنَّهُۥ جِمَٰلَٰتࣱ صُفْرࣱ࣌', 'كأنه جملت صفر࣌', NULL, 581, 'local:warsh-text.json'),
  ('warsh-77-34', 'warsh', 77, 34, 'وَيْلࣱ يَوْمَئِذࣲ لِّلْمُكَذِّبِينَ࣌', 'ويل يومئذ للمكذبين࣌', NULL, 581, 'local:warsh-text.json'),
  ('warsh-77-35', 'warsh', 77, 35, 'هَٰذَا يَوْمُ لَا يَنطِقُونَ', 'هذا يوم لا ينطقون', NULL, 581, 'local:warsh-text.json'),
  ('warsh-77-36', 'warsh', 77, 36, 'وَلَا يُوذَنُ لَهُمْ فَيَعْتَذِرُونَ࣌', 'ولا يوذن لهم فيعتذرون࣌', NULL, 581, 'local:warsh-text.json'),
  ('warsh-77-37', 'warsh', 77, 37, 'وَيْلࣱ يَوْمَئِذࣲ لِّلْمُكَذِّبِينَ࣌', 'ويل يومئذ للمكذبين࣌', NULL, 581, 'local:warsh-text.json'),
  ('warsh-77-38', 'warsh', 77, 38, 'هَٰذَا يَوْمُ ࡲ۬لْفَصْلِ جَمَعْنَٰكُمْ وَالَاوَّلِينَ', 'هذا يوم ࡲلفصل جمعنكم والاولين', NULL, 581, 'local:warsh-text.json'),
  ('warsh-77-39', 'warsh', 77, 39, 'فَإِن كَانَ لَكُمْ كَيْدࣱ فَكِيدُونِ࣌', 'فإن كان لكم كيد فكيدون࣌', NULL, 581, 'local:warsh-text.json'),
  ('warsh-77-40', 'warsh', 77, 40, 'وَيْلࣱ يَوْمَئِذࣲ لِّلْمُكَذِّبِينَ࣌', 'ويل يومئذ للمكذبين࣌', NULL, 581, 'local:warsh-text.json'),
  ('warsh-77-41', 'warsh', 77, 41, 'إِنَّ ࡰ۬لْمُتَّقِينَ فِے ظِلَٰلࣲ وَعُيُونࣲ', 'إن ࡰلمتقين فے ظلل وعيون', NULL, 581, 'local:warsh-text.json'),
  ('warsh-77-42', 'warsh', 77, 42, 'وَفَوَٰكِهَ مِمَّا يَشْتَهُونَ࣌', 'وفوكه مما يشتهون࣌', NULL, 581, 'local:warsh-text.json'),
  ('warsh-77-43', 'warsh', 77, 43, 'كُلُواْ وَاشْرَبُواْ࣌ هَنِيٓـٔاَۢ بِمَا كُنتُمْ تَعْمَلُونَ࣌', 'كلوا واشربوا࣌ هنيا بما كنتم تعملون࣌', NULL, 581, 'local:warsh-text.json'),
  ('warsh-77-44', 'warsh', 77, 44, 'إِنَّا كَذَٰلِكَ نَجْزِے ࡴ۬لْمُحْسِنِينَ࣌', 'إنا كذلك نجزے ࡴلمحسنين࣌', NULL, 581, 'local:warsh-text.json'),
  ('warsh-77-45', 'warsh', 77, 45, 'وَيْلࣱ يَوْمَئِذࣲ لِّلْمُكَذِّبِينَ࣌', 'ويل يومئذ للمكذبين࣌', NULL, 581, 'local:warsh-text.json'),
  ('warsh-77-46', 'warsh', 77, 46, 'كُلُواْ وَتَمَتَّعُواْ قَلِيلاً ࡴنَّكُم مُّجْرِمُونَ࣌', 'كلوا وتمتعوا قليلا ࡴنكم مجرمون࣌', NULL, 581, 'local:warsh-text.json'),
  ('warsh-77-47', 'warsh', 77, 47, 'وَيْلࣱ يَوْمَئِذࣲ لِّلْمُكَذِّبِينَ࣌', 'ويل يومئذ للمكذبين࣌', NULL, 581, 'local:warsh-text.json'),
  ('warsh-77-48', 'warsh', 77, 48, 'وَإِذَا قِيلَ لَهُمُ ࡲٜرْكَعُواْ لَا يَرْكَعُونَ࣌', 'وإذا قيل لهم ࡲركعوا لا يركعون࣌', NULL, 581, 'local:warsh-text.json'),
  ('warsh-77-49', 'warsh', 77, 49, 'وَيْلࣱ يَوْمَئِذࣲ لِّلْمُكَذِّبِينَ࣌', 'ويل يومئذ للمكذبين࣌', NULL, 581, 'local:warsh-text.json'),
  ('warsh-77-50', 'warsh', 77, 50, 'فَبِأَيِّ حَدِيثِۢ بَعْدَهُۥ يُومِنُونَ࣌', 'فبأي حديث بعده يومنون࣌', NULL, 581, 'local:warsh-text.json'),
  ('warsh-78-1', 'warsh', 78, 1, 'عَمَّ࣌ يَتَسَآءَلُونَ', 'عم࣌ يتساءلون', NULL, 582, 'local:warsh-text.json'),
  ('warsh-78-2', 'warsh', 78, 2, 'عَنِ ࡴ۬لنَّبَإِ ࡴ۬لْعَظِيمِ', 'عن ࡴلنبإ ࡴلعظيم', NULL, 582, 'local:warsh-text.json'),
  ('warsh-78-3', 'warsh', 78, 3, 'ࡴ۬لذِے هُمْ فِيهِ مُخْتَلِفُونَ࣌', 'ࡴلذے هم فيه مختلفون࣌', NULL, 582, 'local:warsh-text.json'),
  ('warsh-78-4', 'warsh', 78, 4, 'كَلَّا سَيَعْلَمُونَ', 'كلا سيعلمون', NULL, 582, 'local:warsh-text.json'),
  ('warsh-78-5', 'warsh', 78, 5, 'ثُمَّ كَلَّا سَيَعْلَمُونَ࣌', 'ثم كلا سيعلمون࣌', NULL, 582, 'local:warsh-text.json'),
  ('warsh-78-6', 'warsh', 78, 6, 'أَلَمْ نَجْعَلِ ࡴ۬لَارْضَ مِهَٰداࣰ', 'ألم نجعل ࡴلارض مهدا', NULL, 582, 'local:warsh-text.json'),
  ('warsh-78-7', 'warsh', 78, 7, 'وَالْجِبَالَ أَوْتَاداࣰ', 'والجبال أوتادا', NULL, 582, 'local:warsh-text.json'),
  ('warsh-78-8', 'warsh', 78, 8, 'وَخَلَقْنَٰكُمُۥٓ أَزْوَٰجاࣰ', 'وخلقنكم أزوجا', NULL, 582, 'local:warsh-text.json'),
  ('warsh-78-9', 'warsh', 78, 9, 'وَجَعَلْنَا نَوْمَكُمْ سُبَاتاࣰ', 'وجعلنا نومكم سباتا', NULL, 582, 'local:warsh-text.json'),
  ('warsh-78-10', 'warsh', 78, 10, 'وَجَعَلْنَا ࡰ۬ليْلَ لِبَاساࣰ', 'وجعلنا ࡰليل لباسا', NULL, 582, 'local:warsh-text.json'),
  ('warsh-78-11', 'warsh', 78, 11, 'وَجَعَلْنَا ࡰ۬لنَّهَارَ مَعَاشاࣰ', 'وجعلنا ࡰلنهار معاشا', NULL, 582, 'local:warsh-text.json'),
  ('warsh-78-12', 'warsh', 78, 12, 'وَبَنَيْنَا فَوْقَكُمْ سَبْعاࣰ شِدَاداࣰ', 'وبنينا فوقكم سبعا شدادا', NULL, 582, 'local:warsh-text.json'),
  ('warsh-78-13', 'warsh', 78, 13, 'وَجَعَلْنَا سِرَاجاࣰ وَهَّاجاࣰ', 'وجعلنا سراجا وهاجا', NULL, 582, 'local:warsh-text.json'),
  ('warsh-78-14', 'warsh', 78, 14, 'وَأَنزَلْنَا مِنَ ࡰ۬لْمُعْصِرَٰتِ مَآءࣰ ثَجَّاجاࣰ', 'وأنزلنا من ࡰلمعصرت ماء ثجاجا', NULL, 582, 'local:warsh-text.json'),
  ('warsh-78-15', 'warsh', 78, 15, 'لِّنُخْرِجَ بِهِۦ حَبّاࣰ وَنَبَاتاࣰ', 'لنخرج به حبا ونباتا', NULL, 582, 'local:warsh-text.json'),
  ('warsh-78-16', 'warsh', 78, 16, 'وَجَنَّٰتٍ ࡰلْفَافاً࣌', 'وجنت ࡰلفافا࣌', NULL, 582, 'local:warsh-text.json'),
  ('warsh-78-17', 'warsh', 78, 17, 'ࡴنَّ يَوْمَ ࡰ۬لْفَصْلِ كَانَ مِيقَٰتاࣰ', 'ࡴن يوم ࡰلفصل كان ميقتا', NULL, 582, 'local:warsh-text.json'),
  ('warsh-78-18', 'warsh', 78, 18, 'يَوْمَ يُنفَخُ فِے ࡴ۬لصُّورِ فَتَاتُونَ أَفْوَاجاࣰ', 'يوم ينفخ فے ࡴلصور فتاتون أفواجا', NULL, 582, 'local:warsh-text.json'),
  ('warsh-78-19', 'warsh', 78, 19, 'وَفُتِّحَتِ ࡴ۬لسَّمَآءُ فَكَانَتَ ࡰبْوَٰباࣰ', 'وفتحت ࡴلسماء فكانت ࡰبوبا', NULL, 582, 'local:warsh-text.json'),
  ('warsh-78-20', 'warsh', 78, 20, 'وَسُيِّرَتِ ࡴ۬لْجِبَالُ فَكَانَتْ سَرَاباً࣌', 'وسيرت ࡴلجبال فكانت سرابا࣌', NULL, 582, 'local:warsh-text.json'),
  ('warsh-78-21', 'warsh', 78, 21, 'ࡴنَّ جَهَنَّمَ كَانَتْ مِرْصَاداࣰ', 'ࡴن جهنم كانت مرصادا', NULL, 582, 'local:warsh-text.json'),
  ('warsh-78-22', 'warsh', 78, 22, 'لِّلطَّٰغِينَ مَـَٔاباࣰ', 'للطغين مابا', NULL, 582, 'local:warsh-text.json'),
  ('warsh-78-23', 'warsh', 78, 23, 'لَّٰبِثِينَ فِيهَآ أَحْقَاباࣰ࣌', 'لبثين فيها أحقابا࣌', NULL, 582, 'local:warsh-text.json'),
  ('warsh-78-24', 'warsh', 78, 24, 'لَّا يَذُوقُونَ فِيهَا بَرْداࣰ وَلَا شَرَاباً', 'لا يذوقون فيها بردا ولا شرابا', NULL, 582, 'local:warsh-text.json'),
  ('warsh-78-25', 'warsh', 78, 25, 'ࡴلَّا حَمِيماࣰ وَغَسَاقاࣰ', 'ࡴلا حميما وغساقا', NULL, 582, 'local:warsh-text.json'),
  ('warsh-78-26', 'warsh', 78, 26, 'جَزَآءࣰ وِفَاقاً࣌', 'جزاء وفاقا࣌', NULL, 582, 'local:warsh-text.json'),
  ('warsh-78-27', 'warsh', 78, 27, 'ࡴنَّهُمْ كَانُواْ لَا يَرْجُونَ حِسَاباࣰ', 'ࡴنهم كانوا لا يرجون حسابا', NULL, 582, 'local:warsh-text.json'),
  ('warsh-78-28', 'warsh', 78, 28, 'وَكَذَّبُواْ بِـَٔايَٰتِنَا كِذَّاباࣰ࣌', 'وكذبوا بايتنا كذابا࣌', NULL, 582, 'local:warsh-text.json'),
  ('warsh-78-29', 'warsh', 78, 29, 'وَكُلَّ شَےْءٍ ࡰحْصَيْنَٰهُ كِتَٰباࣰ࣌', 'وكل شےء ࡰحصينه كتبا࣌', NULL, 582, 'local:warsh-text.json'),
  ('warsh-78-30', 'warsh', 78, 30, 'فَذُوقُواْ فَلَن نَّزِيدَكُمُۥٓ إِلَّا عَذَاباً࣌', 'فذوقوا فلن نزيدكم إلا عذابا࣌', NULL, 582, 'local:warsh-text.json'),
  ('warsh-78-31', 'warsh', 78, 31, 'ࡴنَّ لِلْمُتَّقِينَ مَفَازاً', 'ࡴن للمتقين مفازا', NULL, 583, 'local:warsh-text.json'),
  ('warsh-78-32', 'warsh', 78, 32, 'حَدَآئِقَ وَأَعْنَٰباࣰ', 'حدائق وأعنبا', NULL, 583, 'local:warsh-text.json'),
  ('warsh-78-33', 'warsh', 78, 33, 'وَكَوَاعِبَ أَتْرَاباࣰ', 'وكواعب أترابا', NULL, 583, 'local:warsh-text.json'),
  ('warsh-78-34', 'warsh', 78, 34, 'وَكَأْساࣰ دِهَاقاࣰ', 'وكأسا دهاقا', NULL, 583, 'local:warsh-text.json'),
  ('warsh-78-35', 'warsh', 78, 35, 'لَّا يَسْمَعُونَ فِيهَا لَغْواࣰ وَلَا كِذَّاباࣰ࣌', 'لا يسمعون فيها لغوا ولا كذابا࣌', NULL, 583, 'local:warsh-text.json'),
  ('warsh-78-36', 'warsh', 78, 36, 'جَزَآءࣰ مِّن رَّبِّكَ عَطَآءً حِسَاباࣰ࣌', 'جزاء من ربك عطاء حسابا࣌', NULL, 583, 'local:warsh-text.json'),
  ('warsh-78-37', 'warsh', 78, 37, 'رَّبُّ ࡲ۬لسَّمَٰوَٰتِ وَالَارْضِ وَمَا بَيْنَهُمَا࣌ ࡰ۬لرَّحْمَٰنُ لَا يَمْلِكُونَ مِنْهُ خِطَاباࣰ࣌', 'رب ࡲلسموت والارض وما بينهما࣌ ࡰلرحمن لا يملكون منه خطابا࣌', NULL, 583, 'local:warsh-text.json'),
  ('warsh-78-38', 'warsh', 78, 38, 'يَوْمَ يَقُومُ ࡲ۬لرُّوحُ وَالْمَلَٰٓئِكَةُ صَفّاࣰ لَّا يَتَكَلَّمُونَ إِلَّا مَنَ ࡰذِنَ لَهُ ࡲ۬لرَّحْمَٰنُ وَقَالَ صَوَاباࣰ࣌', 'يوم يقوم ࡲلروح والملئكة صفا لا يتكلمون إلا من ࡰذن له ࡲلرحمن وقال صوابا࣌', NULL, 583, 'local:warsh-text.json'),
  ('warsh-78-39', 'warsh', 78, 39, 'ذَٰلِكَ ࡰ۬لْيَوْمُ ࡲ۬لْحَقُّ࣌ فَمَن شَآءَ ࡰٜتَّخَذَ إِلَىٰ رَبِّهِۦ مَـَٔاباً࣌', 'ذلك ࡰليوم ࡲلحق࣌ فمن شاء ࡰتخذ إلى ربه مابا࣌', NULL, 583, 'local:warsh-text.json'),
  ('warsh-78-40', 'warsh', 78, 40, 'ࡴنَّآ أَنذَرْنَٰكُمْ عَذَاباࣰ قَرِيباࣰ يَوْمَ يَنظُرُ ࡲ۬لْمَرْءُ مَا قَدَّمَتْ يَدَٰهُ وَيَقُولُ ࡲ۬لْكَافِرُ يَٰلَيْتَنِے كُنتُ تُرَٰباࣰ࣌', 'ࡴنا أنذرنكم عذابا قريبا يوم ينظر ࡲلمرء ما قدمت يده ويقول ࡲلكافر يليتنے كنت تربا࣌', NULL, 583, 'local:warsh-text.json'),
  ('warsh-79-1', 'warsh', 79, 1, 'وَالنَّٰزِعَٰتِ غَرْقاࣰ', 'والنزعت غرقا', NULL, 583, 'local:warsh-text.json'),
  ('warsh-79-2', 'warsh', 79, 2, 'وَالنَّٰشِطَٰتِ نَشْطاࣰ', 'والنشطت نشطا', NULL, 583, 'local:warsh-text.json'),
  ('warsh-79-3', 'warsh', 79, 3, 'وَالسَّٰبِحَٰتِ سَبْحاࣰ', 'والسبحت سبحا', NULL, 583, 'local:warsh-text.json'),
  ('warsh-79-4', 'warsh', 79, 4, 'فَالسَّٰبِقَٰتِ سَبْقاࣰ', 'فالسبقت سبقا', NULL, 583, 'local:warsh-text.json'),
  ('warsh-79-5', 'warsh', 79, 5, 'فَالْمُدَبِّرَٰتِ أَمْراࣰ', 'فالمدبرت أمرا', NULL, 583, 'local:warsh-text.json'),
  ('warsh-79-6', 'warsh', 79, 6, 'يَوْمَ تَرْجُفُ ࡲ۬لرَّاجِفَةُ', 'يوم ترجف ࡲلراجفة', NULL, 583, 'local:warsh-text.json'),
  ('warsh-79-7', 'warsh', 79, 7, 'تَتْبَعُهَا ࡰ۬لرَّادِفَةُ࣌', 'تتبعها ࡰلرادفة࣌', NULL, 583, 'local:warsh-text.json'),
  ('warsh-79-8', 'warsh', 79, 8, 'قُلُوبࣱ يَوْمَئِذࣲ وَاجِفَةٌ', 'قلوب يومئذ واجفة', NULL, 583, 'local:warsh-text.json'),
  ('warsh-79-9', 'warsh', 79, 9, 'ࡰبْصَٰرُهَا خَٰشِعَةࣱ࣌', 'ࡰبصرها خشعة࣌', NULL, 583, 'local:warsh-text.json'),
  ('warsh-79-10', 'warsh', 79, 10, 'يَقُولُونَ أَࢇنَّا لَمَرْدُودُونَ فِے ࡴ۬لْحَافِرَةِ', 'يقولون أࢇنا لمردودون فے ࡴلحافرة', NULL, 583, 'local:warsh-text.json'),
  ('warsh-79-11', 'warsh', 79, 11, 'إِذَا كُنَّا عِظَٰماࣰ نَّخِرَةࣰ࣌', 'إذا كنا عظما نخرة࣌', NULL, 583, 'local:warsh-text.json'),
  ('warsh-79-12', 'warsh', 79, 12, 'قَالُواْ تِلْكَ إِذاࣰ كَرَّةٌ خَاسِرَةࣱ', 'قالوا تلك إذا كرة خاسرة', NULL, 583, 'local:warsh-text.json'),
  ('warsh-79-13', 'warsh', 79, 13, 'فَإِنَّمَا هِيَ زَجْرَةࣱ وَٰحِدَةࣱ', 'فإنما هي زجرة وحدة', NULL, 583, 'local:warsh-text.json'),
  ('warsh-79-14', 'warsh', 79, 14, 'فَإِذَا هُم بِالسَّاهِرَةِ࣌', 'فإذا هم بالساهرة࣌', NULL, 583, 'local:warsh-text.json'),
  ('warsh-79-15', 'warsh', 79, 15, 'هَلَ ࡰتٜيٰكَ حَدِيثُ مُوسٜىٰٓ', 'هل ࡰتيك حديث موسى', NULL, 583, 'local:warsh-text.json'),
  ('warsh-79-16', 'warsh', 79, 16, 'إِذْ نَادٜيٰهُ رَبُّهُۥ بِالْوَادِ ࡴ۬لْمُقَدَّسِ طُوَى࣌', 'إذ ناديه ربه بالواد ࡴلمقدس طوى࣌', NULL, 583, 'local:warsh-text.json'),
  ('warsh-79-17', 'warsh', 79, 17, 'ࡰٜذْهَبِ ࡴلَىٰ فِرْعَوْنَ إِنَّهُۥ طَغٜىٰ', 'ࡰذهب ࡴلى فرعون إنه طغى', NULL, 584, 'local:warsh-text.json'),
  ('warsh-79-18', 'warsh', 79, 18, 'فَقُلْ هَل لَّكَ إِلَىٰٓ أَن تَزَّكّٜىٰ', 'فقل هل لك إلى أن تزكى', NULL, 584, 'local:warsh-text.json'),
  ('warsh-79-19', 'warsh', 79, 19, 'وَأَهْدِيَكَ إِلَىٰ رَبِّكَ فَتَخْشٜىٰ࣌', 'وأهديك إلى ربك فتخشى࣌', NULL, 584, 'local:warsh-text.json'),
  ('warsh-79-20', 'warsh', 79, 20, 'فَأَرٜيٰهُ ࡲ۬لَايَةَ ࡰ۬لْكُبْرٜىٰ', 'فأريه ࡲلاية ࡰلكبرى', NULL, 584, 'local:warsh-text.json'),
  ('warsh-79-21', 'warsh', 79, 21, 'فَكَذَّبَ وَعَصٜىٰ', 'فكذب وعصى', NULL, 584, 'local:warsh-text.json'),
  ('warsh-79-22', 'warsh', 79, 22, 'ثُمَّ أَدْبَرَ يَسْعٜىٰ', 'ثم أدبر يسعى', NULL, 584, 'local:warsh-text.json'),
  ('warsh-79-23', 'warsh', 79, 23, 'فَحَشَرَ فَنَادٜىٰ', 'فحشر فنادى', NULL, 584, 'local:warsh-text.json'),
  ('warsh-79-24', 'warsh', 79, 24, 'فَقَالَ أَنَا رَبُّكُمُ ࡲ۬لَاعْلٜىٰ', 'فقال أنا ربكم ࡲلاعلى', NULL, 584, 'local:warsh-text.json'),
  ('warsh-79-25', 'warsh', 79, 25, 'فَأَخَذَهُ ࡲ۬للَّهُ نَكَالَ ࡰ۬لَاخِرَةِ وَالُاولٜىٰٓ࣌', 'فأخذه ࡲلله نكال ࡰلاخرة والاولى࣌', NULL, 584, 'local:warsh-text.json'),
  ('warsh-79-26', 'warsh', 79, 26, 'إِنَّ فِے ذَٰلِكَ لَعِبْرَةࣰ لِّمَنْ يَّخْشٜىٰٓ࣌', 'إن فے ذلك لعبرة لمن يخشى࣌', NULL, 584, 'local:warsh-text.json'),
  ('warsh-79-27', 'warsh', 79, 27, 'ءَآنتُمُۥٓ أَشَدُّ خَلْقاً ࡰمِ ࡴ۬لسَّمَآءُ࣌ بَنَيٰهَا', 'ءانتم أشد خلقا ࡰم ࡴلسماء࣌ بنيها', NULL, 584, 'local:warsh-text.json'),
  ('warsh-79-28', 'warsh', 79, 28, 'رَفَعَ سَمْكَهَا فَسَوَّيٰهَا', 'رفع سمكها فسويها', NULL, 584, 'local:warsh-text.json'),
  ('warsh-79-29', 'warsh', 79, 29, 'وَأَغْطَشَ لَيْلَهَا وَأَخْرَجَ ضُحَيٰهَا࣌', 'وأغطش ليلها وأخرج ضحيها࣌', NULL, 584, 'local:warsh-text.json'),
  ('warsh-79-30', 'warsh', 79, 30, 'وَالَارْضَ بَعْدَ ذَٰلِكَ دَحَيٰهَآ', 'والارض بعد ذلك دحيها', NULL, 584, 'local:warsh-text.json'),
  ('warsh-79-31', 'warsh', 79, 31, 'أَخْرَجَ مِنْهَا مَآءَهَا وَمَرْعَيٰهَا', 'أخرج منها ماءها ومرعيها', NULL, 584, 'local:warsh-text.json'),
  ('warsh-79-32', 'warsh', 79, 32, 'وَالْجِبَالَ أَرْسَيٰهَا', 'والجبال أرسيها', NULL, 584, 'local:warsh-text.json'),
  ('warsh-79-33', 'warsh', 79, 33, 'مَتَٰعاࣰ لَّكُمْ وَلِأَنْعَٰمِكُمْ࣌', 'متعا لكم ولأنعمكم࣌', NULL, 584, 'local:warsh-text.json'),
  ('warsh-79-34', 'warsh', 79, 34, 'فَإِذَا جَآءَتِ ࡴ۬لطَّآمَّةُ ࡲ۬لْكُبْرٜىٰ', 'فإذا جاءت ࡴلطامة ࡲلكبرى', NULL, 584, 'local:warsh-text.json'),
  ('warsh-79-35', 'warsh', 79, 35, 'يَوْمَ يَتَذَكَّرُ ࡲ۬لِانسَٰنُ مَا سَعٜىٰ', 'يوم يتذكر ࡲلانسن ما سعى', NULL, 584, 'local:warsh-text.json'),
  ('warsh-79-36', 'warsh', 79, 36, 'وَبُرِّزَتِ ࡴ۬لْجَحِيمُ لِمَنْ يَّرٜىٰ࣌', 'وبرزت ࡴلجحيم لمن يرى࣌', NULL, 584, 'local:warsh-text.json'),
  ('warsh-79-37', 'warsh', 79, 37, 'فَأَمَّا مَن طَغٜىٰ وَءَاثَرَ ࡰ۬لْحَيَوٰةَ ࡰ۬لدُّنْيٜا', 'فأما من طغى وءاثر ࡰلحيوة ࡰلدنيا', NULL, 584, 'local:warsh-text.json'),
  ('warsh-79-38', 'warsh', 79, 38, 'فَإِنَّ ࡰ۬لْجَحِيمَ هِيَ ࡰ۬لْمَأْوٜىٰ࣌', 'فإن ࡰلجحيم هي ࡰلمأوى࣌', NULL, 584, 'local:warsh-text.json'),
  ('warsh-79-39', 'warsh', 79, 39, 'وَأَمَّا مَنْ خَافَ مَقَامَ رَبِّهِۦ وَنَهَى ࡰ۬لنَّفْسَ عَنِ ࡴ۬لْهَوٜىٰ', 'وأما من خاف مقام ربه ونهى ࡰلنفس عن ࡴلهوى', NULL, 584, 'local:warsh-text.json'),
  ('warsh-79-40', 'warsh', 79, 40, 'فَإِنَّ ࡰ۬لْجَنَّةَ هِيَ ࡰ۬لْمَأْوٜىٰ࣌', 'فإن ࡰلجنة هي ࡰلمأوى࣌', NULL, 584, 'local:warsh-text.json'),
  ('warsh-79-41', 'warsh', 79, 41, '۞ يَسْـَٔلُونَكَ عَنِ ࡴ۬لسَّاعَةِ أَيَّانَ مُرْسَيٰهَا࣌', 'يسلونك عن ࡴلساعة أيان مرسيها࣌', NULL, 584, 'local:warsh-text.json'),
  ('warsh-79-42', 'warsh', 79, 42, 'فِيمَ أَنتَ مِن ذِكْرٜيٰهَآ࣌', 'فيم أنت من ذكريها࣌', NULL, 584, 'local:warsh-text.json'),
  ('warsh-79-43', 'warsh', 79, 43, 'إِلَىٰ رَبِّكَ مُنتَهَيٰهَآ࣌', 'إلى ربك منتهيها࣌', NULL, 584, 'local:warsh-text.json'),
  ('warsh-79-44', 'warsh', 79, 44, 'إِنَّمَآ أَنتَ مُنذِرُ مَنْ يَّخْشَيٰهَا࣌', 'إنما أنت منذر من يخشيها࣌', NULL, 584, 'local:warsh-text.json'),
  ('warsh-79-45', 'warsh', 79, 45, 'كَأَنَّهُمْ يَوْمَ يَرَوْنَهَا لَمْ يَلْبَثُوٓاْ إِلَّا عَشِيَّةً ࡰوْ ضُحَيٰهَا࣌', 'كأنهم يوم يرونها لم يلبثوا إلا عشية ࡰو ضحيها࣌', NULL, 584, 'local:warsh-text.json'),
  ('warsh-80-1', 'warsh', 80, 1, 'عَبَسَ وَتَوَلّٜىٰٓ', 'عبس وتولى', NULL, 585, 'local:warsh-text.json'),
  ('warsh-80-2', 'warsh', 80, 2, 'أَن جَآءَهُ ࡲ۬لَاعْمٜىٰ࣌', 'أن جاءه ࡲلاعمى࣌', NULL, 585, 'local:warsh-text.json'),
  ('warsh-80-3', 'warsh', 80, 3, 'وَمَا يُدْرِيكَ࣌ لَعَلَّهُۥ يَزَّكّٜىٰٓ', 'وما يدريك࣌ لعله يزكى', NULL, 585, 'local:warsh-text.json'),
  ('warsh-80-4', 'warsh', 80, 4, 'أَوْ يَذَّكَّرُ فَتَنفَعُهُ ࡲ۬لذِّكْرٜىٰٓ࣌', 'أو يذكر فتنفعه ࡲلذكرى࣌', NULL, 585, 'local:warsh-text.json'),
  ('warsh-80-5', 'warsh', 80, 5, 'أَمَّا مَنِ ࡴٜسْتَغْنٜىٰ', 'أما من ࡴستغنى', NULL, 585, 'local:warsh-text.json'),
  ('warsh-80-6', 'warsh', 80, 6, 'فَأَنتَ لَهُۥ تَصَّدّٜىٰ', 'فأنت له تصدى', NULL, 585, 'local:warsh-text.json'),
  ('warsh-80-7', 'warsh', 80, 7, 'وَمَا عَلَيْكَ أَلَّا يَزَّكّٜىٰ࣌', 'وما عليك ألا يزكى࣌', NULL, 585, 'local:warsh-text.json'),
  ('warsh-80-8', 'warsh', 80, 8, 'وَأَمَّا مَن جَآءَكَ يَسْعٜىٰ', 'وأما من جاءك يسعى', NULL, 585, 'local:warsh-text.json'),
  ('warsh-80-9', 'warsh', 80, 9, 'وَهُوَ يَخْشٜىٰ', 'وهو يخشى', NULL, 585, 'local:warsh-text.json'),
  ('warsh-80-10', 'warsh', 80, 10, 'فَأَنتَ عَنْهُ تَلَهّٜىٰ', 'فأنت عنه تلهى', NULL, 585, 'local:warsh-text.json'),
  ('warsh-80-11', 'warsh', 80, 11, 'كَلَّآ࣌ إِنَّهَا تَذْكِرَةࣱ࣌', 'كلا࣌ إنها تذكرة࣌', NULL, 585, 'local:warsh-text.json'),
  ('warsh-80-12', 'warsh', 80, 12, 'فَمَن شَآءَ ذَكَرَهُۥ', 'فمن شاء ذكره', NULL, 585, 'local:warsh-text.json'),
  ('warsh-80-13', 'warsh', 80, 13, 'فِے صُحُفࣲ مُّكَرَّمَةࣲ', 'فے صحف مكرمة', NULL, 585, 'local:warsh-text.json'),
  ('warsh-80-14', 'warsh', 80, 14, 'مَّرْفُوعَةࣲ مُّطَهَّرَةِۢ', 'مرفوعة مطهرة', NULL, 585, 'local:warsh-text.json'),
  ('warsh-80-15', 'warsh', 80, 15, 'بِأَيْدِے سَفَرَةࣲ', 'بأيدے سفرة', NULL, 585, 'local:warsh-text.json'),
  ('warsh-80-16', 'warsh', 80, 16, 'كِرَامِۢ بَرَرَةࣲ࣌', 'كرام بررة࣌', NULL, 585, 'local:warsh-text.json'),
  ('warsh-80-17', 'warsh', 80, 17, 'قُتِلَ ࡰ۬لِانسَٰنُ مَآ أَكْفَرَهُۥ࣌', 'قتل ࡰلانسن ما أكفره࣌', NULL, 585, 'local:warsh-text.json'),
  ('warsh-80-18', 'warsh', 80, 18, 'مِنَ ࡰيِّ شَےْءٍ خَلَقَهُۥ࣌', 'من ࡰي شےء خلقه࣌', NULL, 585, 'local:warsh-text.json'),
  ('warsh-80-19', 'warsh', 80, 19, 'مِن نُّطْفَةٍ خَلَقَهُۥ فَقَدَّرَهُۥ', 'من نطفة خلقه فقدره', NULL, 585, 'local:warsh-text.json'),
  ('warsh-80-20', 'warsh', 80, 20, 'ثُمَّ ࡰ۬لسَّبِيلَ يَسَّرَهُۥ', 'ثم ࡰلسبيل يسره', NULL, 585, 'local:warsh-text.json'),
  ('warsh-80-21', 'warsh', 80, 21, 'ثُمَّ أَمَاتَهُۥ فَأَقْبَرَهُۥ࣌', 'ثم أماته فأقبره࣌', NULL, 585, 'local:warsh-text.json'),
  ('warsh-80-22', 'warsh', 80, 22, 'ثُمَّ إِذَا شَآءَ انشَرَهُۥ࣌', 'ثم إذا شاء انشره࣌', NULL, 585, 'local:warsh-text.json'),
  ('warsh-80-23', 'warsh', 80, 23, 'كَلَّا لَمَّا يَقْضِ مَآ أَمَرَهُۥ࣌', 'كلا لما يقض ما أمره࣌', NULL, 585, 'local:warsh-text.json'),
  ('warsh-80-24', 'warsh', 80, 24, 'فَلْيَنظُرِ ࡴ۬لِانسَٰنُ إِلَىٰ طَعَامِهِۦٓ࣌', 'فلينظر ࡴلانسن إلى طعامه࣌', NULL, 585, 'local:warsh-text.json'),
  ('warsh-80-25', 'warsh', 80, 25, 'إِنَّا صَبَبْنَا ࡰ۬لْمَآءَ صَبّاࣰ', 'إنا صببنا ࡰلماء صبا', NULL, 585, 'local:warsh-text.json'),
  ('warsh-80-26', 'warsh', 80, 26, 'ثُمَّ شَقَقْنَا ࡰ۬لَارْضَ شَقّاࣰ', 'ثم شققنا ࡰلارض شقا', NULL, 585, 'local:warsh-text.json'),
  ('warsh-80-27', 'warsh', 80, 27, 'فَأَنۢبَتْنَا فِيهَا حَبّاࣰ', 'فأنبتنا فيها حبا', NULL, 585, 'local:warsh-text.json'),
  ('warsh-80-28', 'warsh', 80, 28, 'وَعِنَباࣰ وَقَضْباࣰ', 'وعنبا وقضبا', NULL, 585, 'local:warsh-text.json'),
  ('warsh-80-29', 'warsh', 80, 29, 'وَزَيْتُوناࣰ وَنَخْلاࣰ', 'وزيتونا ونخلا', NULL, 585, 'local:warsh-text.json'),
  ('warsh-80-30', 'warsh', 80, 30, 'وَحَدَآئِقَ غُلْباࣰ', 'وحدائق غلبا', NULL, 585, 'local:warsh-text.json'),
  ('warsh-80-31', 'warsh', 80, 31, 'وَفَٰكِهَةࣰ وَأَبّاࣰ', 'وفكهة وأبا', NULL, 585, 'local:warsh-text.json'),
  ('warsh-80-32', 'warsh', 80, 32, 'مَّتَٰعاࣰ لَّكُمْ وَلِأَنْعَٰمِكُمْ࣌', 'متعا لكم ولأنعمكم࣌', NULL, 585, 'local:warsh-text.json'),
  ('warsh-80-33', 'warsh', 80, 33, 'فَإِذَا جَآءَتِ ࡴ۬لصَّآخَّةُ', 'فإذا جاءت ࡴلصاخة', NULL, 585, 'local:warsh-text.json'),
  ('warsh-80-34', 'warsh', 80, 34, 'يَوْمَ يَفِرُّ ࡲ۬لْمَرْءُ مِنَ ࡰخِيهِ', 'يوم يفر ࡲلمرء من ࡰخيه', NULL, 585, 'local:warsh-text.json'),
  ('warsh-80-35', 'warsh', 80, 35, 'وَأُمِّهِۦ وَأَبِيهِ', 'وأمه وأبيه', NULL, 585, 'local:warsh-text.json'),
  ('warsh-80-36', 'warsh', 80, 36, 'وَصَٰحِبَتِهِۦ وَبَنِيهِ࣌', 'وصحبته وبنيه࣌', NULL, 585, 'local:warsh-text.json'),
  ('warsh-80-37', 'warsh', 80, 37, 'لِكُلِّ ࡴٜمْرِےࣲٕ مِّنْهُمْ يَوْمَئِذࣲ شَأْنࣱ يُغْنِيهِ࣌', 'لكل ࡴمرے منهم يومئذ شأن يغنيه࣌', NULL, 585, 'local:warsh-text.json'),
  ('warsh-80-38', 'warsh', 80, 38, 'وُجُوهࣱ يَوْمَئِذࣲ مُّسْفِرَةࣱ', 'وجوه يومئذ مسفرة', NULL, 585, 'local:warsh-text.json'),
  ('warsh-80-39', 'warsh', 80, 39, 'ضَاحِكَةࣱ مُّسْتَبْشِرَةࣱ࣌', 'ضاحكة مستبشرة࣌', NULL, 585, 'local:warsh-text.json'),
  ('warsh-80-40', 'warsh', 80, 40, 'وَوُجُوهࣱ يَوْمَئِذٍ عَلَيْهَا غَبَرَةࣱ', 'ووجوه يومئذ عليها غبرة', NULL, 585, 'local:warsh-text.json'),
  ('warsh-80-41', 'warsh', 80, 41, 'تَرْهَقُهَا قَتَرَةٌ࣌', 'ترهقها قترة࣌', NULL, 586, 'local:warsh-text.json'),
  ('warsh-80-42', 'warsh', 80, 42, 'ࡳوْلَٰٓئِكَ هُمُ ࡲ۬لْكَفَرَةُ ࡲ۬لْفَجَرَةُ࣌', 'ࡳولئك هم ࡲلكفرة ࡲلفجرة࣌', NULL, 586, 'local:warsh-text.json'),
  ('warsh-81-1', 'warsh', 81, 1, 'إِذَا ࡰ۬لشَّمْسُ كُوِّرَتْ', 'إذا ࡰلشمس كورت', NULL, 586, 'local:warsh-text.json'),
  ('warsh-81-2', 'warsh', 81, 2, 'وَإِذَا ࡰ۬لنُّجُومُ ࡲٜنكَدَرَتْ', 'وإذا ࡰلنجوم ࡲنكدرت', NULL, 586, 'local:warsh-text.json'),
  ('warsh-81-3', 'warsh', 81, 3, 'وَإِذَا ࡰ۬لْجِبَالُ سُيِّرَتْ', 'وإذا ࡰلجبال سيرت', NULL, 586, 'local:warsh-text.json'),
  ('warsh-81-4', 'warsh', 81, 4, 'وَإِذَا ࡰ۬لْعِشَارُ عُطِّلَتْ', 'وإذا ࡰلعشار عطلت', NULL, 586, 'local:warsh-text.json'),
  ('warsh-81-5', 'warsh', 81, 5, 'وَإِذَا ࡰ۬لْوُحُوشُ حُشِرَتْ', 'وإذا ࡰلوحوش حشرت', NULL, 586, 'local:warsh-text.json'),
  ('warsh-81-6', 'warsh', 81, 6, 'وَإِذَا ࡰ۬لْبِحَارُ سُجِّرَتْ', 'وإذا ࡰلبحار سجرت', NULL, 586, 'local:warsh-text.json'),
  ('warsh-81-7', 'warsh', 81, 7, 'وَإِذَا ࡰ۬لنُّفُوسُ زُوِّجَتْ', 'وإذا ࡰلنفوس زوجت', NULL, 586, 'local:warsh-text.json'),
  ('warsh-81-8', 'warsh', 81, 8, 'وَإِذَا ࡰ۬لْمَوْءُۥدَةُ سُئِلَتْ', 'وإذا ࡰلموءدة سئلت', NULL, 586, 'local:warsh-text.json'),
  ('warsh-81-9', 'warsh', 81, 9, 'بِأَيِّ ذَنۢبࣲ قُتِلَتْ', 'بأي ذنب قتلت', NULL, 586, 'local:warsh-text.json'),
  ('warsh-81-10', 'warsh', 81, 10, 'وَإِذَا ࡰ۬لصُّحُفُ نُشِرَتْ', 'وإذا ࡰلصحف نشرت', NULL, 586, 'local:warsh-text.json'),
  ('warsh-81-11', 'warsh', 81, 11, 'وَإِذَا ࡰ۬لسَّمَآءُ كُشِطَتْ', 'وإذا ࡰلسماء كشطت', NULL, 586, 'local:warsh-text.json'),
  ('warsh-81-12', 'warsh', 81, 12, 'وَإِذَا ࡰ۬لْجَحِيمُ سُعِّرَتْ', 'وإذا ࡰلجحيم سعرت', NULL, 586, 'local:warsh-text.json'),
  ('warsh-81-13', 'warsh', 81, 13, 'وَإِذَا ࡰ۬لْجَنَّةُ أُزْلِفَتْ', 'وإذا ࡰلجنة أزلفت', NULL, 586, 'local:warsh-text.json'),
  ('warsh-81-14', 'warsh', 81, 14, 'عَلِمَتْ نَفْسࣱ مَّآ أَحْضَرَتْ࣌', 'علمت نفس ما أحضرت࣌', NULL, 586, 'local:warsh-text.json'),
  ('warsh-81-15', 'warsh', 81, 15, 'فَلَآ أُقْسِمُ بِالْخُنَّسِ', 'فلا أقسم بالخنس', NULL, 586, 'local:warsh-text.json'),
  ('warsh-81-16', 'warsh', 81, 16, 'ࡴ۬لْجَوَارِ ࡴ۬لْكُنَّسِ', 'ࡴلجوار ࡴلكنس', NULL, 586, 'local:warsh-text.json'),
  ('warsh-81-17', 'warsh', 81, 17, 'وَاليْلِ إِذَا عَسْعَسَ', 'واليل إذا عسعس', NULL, 586, 'local:warsh-text.json'),
  ('warsh-81-18', 'warsh', 81, 18, 'وَالصُّبْحِ إِذَا تَنَفَّسَ', 'والصبح إذا تنفس', NULL, 586, 'local:warsh-text.json'),
  ('warsh-81-19', 'warsh', 81, 19, 'إِنَّهُۥ لَقَوْلُ رَسُولࣲ كَرِيمࣲ', 'إنه لقول رسول كريم', NULL, 586, 'local:warsh-text.json'),
  ('warsh-81-20', 'warsh', 81, 20, 'ذِے قُوَّةٍ عِندَ ذِے ࡴ۬لْعَرْشِ مَكِينࣲ', 'ذے قوة عند ذے ࡴلعرش مكين', NULL, 586, 'local:warsh-text.json'),
  ('warsh-81-21', 'warsh', 81, 21, 'مُّطَاعࣲ ثَمَّ أَمِينࣲ࣌', 'مطاع ثم أمين࣌', NULL, 586, 'local:warsh-text.json'),
  ('warsh-81-22', 'warsh', 81, 22, 'وَمَا صَٰحِبُكُم بِمَجْنُونࣲ࣌', 'وما صحبكم بمجنون࣌', NULL, 586, 'local:warsh-text.json'),
  ('warsh-81-23', 'warsh', 81, 23, 'وَلَقَدْ رٜءٜاهُ بِالُافُقِ ࡴ۬لْمُبِينِ࣌', 'ولقد رءاه بالافق ࡴلمبين࣌', NULL, 586, 'local:warsh-text.json'),
  ('warsh-81-24', 'warsh', 81, 24, 'وَمَا هُوَ عَلَى ࡰ۬لْغَيْبِ بِضَنِينࣲ࣌', 'وما هو على ࡰلغيب بضنين࣌', NULL, 586, 'local:warsh-text.json'),
  ('warsh-81-25', 'warsh', 81, 25, 'وَمَا هُوَ بِقَوْلِ شَيْطَٰنࣲ رَّجِيمࣲ', 'وما هو بقول شيطن رجيم', NULL, 586, 'local:warsh-text.json'),
  ('warsh-81-26', 'warsh', 81, 26, 'فَأَيْنَ تَذْهَبُونَ࣌', 'فأين تذهبون࣌', NULL, 586, 'local:warsh-text.json'),
  ('warsh-81-27', 'warsh', 81, 27, 'إِنْ هُوَ إِلَّا ذِكْرࣱ لِّلْعَٰلَمِينَ', 'إن هو إلا ذكر للعلمين', NULL, 586, 'local:warsh-text.json'),
  ('warsh-81-28', 'warsh', 81, 28, 'لِمَن شَآءَ مِنكُمُۥٓ أَنْ يَّسْتَقِيمَ࣌', 'لمن شاء منكم أن يستقيم࣌', NULL, 586, 'local:warsh-text.json'),
  ('warsh-81-29', 'warsh', 81, 29, 'وَمَا تَشَآءُونَ إِلَّآ أَنْ يَّشَآءَ ࡰ۬للَّهُ رَبُّ ࡲ۬لْعَٰلَمِينَ࣌', 'وما تشاءون إلا أن يشاء ࡰلله رب ࡲلعلمين࣌', NULL, 586, 'local:warsh-text.json'),
  ('warsh-82-1', 'warsh', 82, 1, 'إِذَا ࡰ۬لسَّمَآءُ ࡲٜنفَطَرَتْ', 'إذا ࡰلسماء ࡲنفطرت', NULL, 587, 'local:warsh-text.json'),
  ('warsh-82-2', 'warsh', 82, 2, 'وَإِذَا ࡰ۬لْكَوَاكِبُ ࡲٜنتَثَرَتْ', 'وإذا ࡰلكواكب ࡲنتثرت', NULL, 587, 'local:warsh-text.json'),
  ('warsh-82-3', 'warsh', 82, 3, 'وَإِذَا ࡰ۬لْبِحَارُ فُجِّرَتْ', 'وإذا ࡰلبحار فجرت', NULL, 587, 'local:warsh-text.json'),
  ('warsh-82-4', 'warsh', 82, 4, 'وَإِذَا ࡰ۬لْقُبُورُ بُعْثِرَتْ', 'وإذا ࡰلقبور بعثرت', NULL, 587, 'local:warsh-text.json'),
  ('warsh-82-5', 'warsh', 82, 5, 'عَلِمَتْ نَفْسࣱ مَّا قَدَّمَتْ وَأَخَّرَتْ࣌', 'علمت نفس ما قدمت وأخرت࣌', NULL, 587, 'local:warsh-text.json'),
  ('warsh-82-6', 'warsh', 82, 6, 'يَٰٓأَيُّهَا ࡰ۬لِانسَٰنُ مَا غَرَّكَ بِرَبِّكَ ࡰ۬لْكَرِيمِ', 'يأيها ࡰلانسن ما غرك بربك ࡰلكريم', NULL, 587, 'local:warsh-text.json'),
  ('warsh-82-7', 'warsh', 82, 7, 'ࡴ۬لذِے خَلَقَكَ فَسَوّٜيٰكَ فَعَدَّلَكَ', 'ࡴلذے خلقك فسويك فعدلك', NULL, 587, 'local:warsh-text.json'),
  ('warsh-82-8', 'warsh', 82, 8, 'فِےٓ أَيِّ صُورَةࣲ مَّا شَآءَ رَكَّبَكَ࣌', 'فے أي صورة ما شاء ركبك࣌', NULL, 587, 'local:warsh-text.json'),
  ('warsh-82-9', 'warsh', 82, 9, 'كَلَّا بَلْ تُكَذِّبُونَ بِالدِّينِ', 'كلا بل تكذبون بالدين', NULL, 587, 'local:warsh-text.json'),
  ('warsh-82-10', 'warsh', 82, 10, 'وَإِنَّ عَلَيْكُمْ لَحَٰفِظِينَ', 'وإن عليكم لحفظين', NULL, 587, 'local:warsh-text.json'),
  ('warsh-82-11', 'warsh', 82, 11, 'كِرَاماࣰ كَٰتِبِينَ', 'كراما كتبين', NULL, 587, 'local:warsh-text.json'),
  ('warsh-82-12', 'warsh', 82, 12, 'يَعْلَمُونَ مَا تَفْعَلُونَ࣌', 'يعلمون ما تفعلون࣌', NULL, 587, 'local:warsh-text.json'),
  ('warsh-82-13', 'warsh', 82, 13, 'إِنَّ ࡰ۬لَابْرَارَ لَفِے نَعِيمࣲ࣌', 'إن ࡰلابرار لفے نعيم࣌', NULL, 587, 'local:warsh-text.json'),
  ('warsh-82-14', 'warsh', 82, 14, 'وَإِنَّ ࡰ۬لْفُجَّارَ لَفِے جَحِيمࣲ', 'وإن ࡰلفجار لفے جحيم', NULL, 587, 'local:warsh-text.json'),
  ('warsh-82-15', 'warsh', 82, 15, 'يَصْلَوْنَهَا يَوْمَ ࡰ۬لدِّينِ', 'يصلونها يوم ࡰلدين', NULL, 587, 'local:warsh-text.json'),
  ('warsh-82-16', 'warsh', 82, 16, 'وَمَا هُمْ عَنْهَا بِغَآئِبِينَ࣌', 'وما هم عنها بغائبين࣌', NULL, 587, 'local:warsh-text.json'),
  ('warsh-82-17', 'warsh', 82, 17, 'وَمَآ أَدْرٜيٰكَ مَا يَوْمُ ࡲ۬لدِّينِ', 'وما أدريك ما يوم ࡲلدين', NULL, 587, 'local:warsh-text.json'),
  ('warsh-82-18', 'warsh', 82, 18, 'ثُمَّ مَآ أَدْرٜيٰكَ مَا يَوْمُ ࡲ۬لدِّينِ࣌', 'ثم ما أدريك ما يوم ࡲلدين࣌', NULL, 587, 'local:warsh-text.json'),
  ('warsh-82-19', 'warsh', 82, 19, 'يَوْمَ لَا تَمْلِكُ نَفْسࣱ لِّنَفْسࣲ شَيْـٔاࣰ࣌ وَالَامْرُ يَوْمَئِذࣲ لِّلهِ࣌', 'يوم لا تملك نفس لنفس شيا࣌ والامر يومئذ لله࣌', NULL, 587, 'local:warsh-text.json'),
  ('warsh-83-1', 'warsh', 83, 1, 'وَيْلࣱ لِّلْمُطَفِّفِينَ', 'ويل للمطففين', NULL, 587, 'local:warsh-text.json'),
  ('warsh-83-2', 'warsh', 83, 2, 'ࡰ۬لذِينَ إِذَا ࡰٜكْتَالُواْ عَلَى ࡰ۬لنَّاسِ يَسْتَوْفُونَ', 'ࡰلذين إذا ࡰكتالوا على ࡰلناس يستوفون', NULL, 587, 'local:warsh-text.json'),
  ('warsh-83-3', 'warsh', 83, 3, 'وَإِذَا كَالُوهُمُۥٓ أَو وَّزَنُوهُمْ يُخْسِرُونَ࣌', 'وإذا كالوهم أو وزنوهم يخسرون࣌', NULL, 587, 'local:warsh-text.json'),
  ('warsh-83-4', 'warsh', 83, 4, 'أَلَا يَظُنُّ أُوْلَٰٓئِكَ أَنَّهُم مَّبْعُوثُونَ', 'ألا يظن أولئك أنهم مبعوثون', NULL, 587, 'local:warsh-text.json'),
  ('warsh-83-5', 'warsh', 83, 5, 'لِيَوْمٍ عَظِيمࣲ', 'ليوم عظيم', NULL, 588, 'local:warsh-text.json'),
  ('warsh-83-6', 'warsh', 83, 6, 'يَوْمَ يَقُومُ ࡲ۬لنَّاسُ لِرَبِّ ࡴ۬لْعَٰلَمِينَ࣌', 'يوم يقوم ࡲلناس لرب ࡴلعلمين࣌', NULL, 588, 'local:warsh-text.json'),
  ('warsh-83-7', 'warsh', 83, 7, 'كَلَّآ إِنَّ كِتَٰبَ ࡰ۬لْفُجّٜارِ لَفِے سِجِّينࣲ࣌', 'كلا إن كتب ࡰلفجار لفے سجين࣌', NULL, 588, 'local:warsh-text.json'),
  ('warsh-83-8', 'warsh', 83, 8, 'وَمَآ أَدْرٜيٰكَ مَا سِجِّينࣱ', 'وما أدريك ما سجين', NULL, 588, 'local:warsh-text.json'),
  ('warsh-83-9', 'warsh', 83, 9, 'كِتَٰبࣱ مَّرْقُومࣱ࣌', 'كتب مرقوم࣌', NULL, 588, 'local:warsh-text.json'),
  ('warsh-83-10', 'warsh', 83, 10, 'وَيْلࣱ يَوْمَئِذࣲ لِّلْمُكَذِّبِينَ', 'ويل يومئذ للمكذبين', NULL, 588, 'local:warsh-text.json'),
  ('warsh-83-11', 'warsh', 83, 11, 'ࡰ۬لذِينَ يُكَذِّبُونَ بِيَوْمِ ࡴ۬لدِّينِ࣌', 'ࡰلذين يكذبون بيوم ࡴلدين࣌', NULL, 588, 'local:warsh-text.json'),
  ('warsh-83-12', 'warsh', 83, 12, 'وَمَا يُكَذِّبُ بِهِۦٓ إِلَّا كُلُّ مُعْتَدٍ ࡰثِيمٍ', 'وما يكذب به إلا كل معتد ࡰثيم', NULL, 588, 'local:warsh-text.json'),
  ('warsh-83-13', 'warsh', 83, 13, 'ࡴذَا تُتْلٜىٰ عَلَيْهِ ءَايَٰتُنَا قَالَ أَسَٰطِيرُ ࡲ۬لَاوَّلِينَ࣌', 'ࡴذا تتلى عليه ءايتنا قال أسطير ࡲلاولين࣌', NULL, 588, 'local:warsh-text.json'),
  ('warsh-83-14', 'warsh', 83, 14, '۞ كَلَّا بَل رَّانَ عَلَىٰ قُلُوبِهِم مَّا كَانُواْ يَكْسِبُونَ࣌', 'كلا بل ران على قلوبهم ما كانوا يكسبون࣌', NULL, 588, 'local:warsh-text.json'),
  ('warsh-83-15', 'warsh', 83, 15, 'كَلَّآ إِنَّهُمْ عَن رَّبِّهِمْ يَوْمَئِذࣲ لَّمَحْجُوبُونَ࣌', 'كلا إنهم عن ربهم يومئذ لمحجوبون࣌', NULL, 588, 'local:warsh-text.json'),
  ('warsh-83-16', 'warsh', 83, 16, 'ثُمَّ إِنَّهُمْ لَصَالُواْ ࡲ۬لْجَحِيمِ࣌', 'ثم إنهم لصالوا ࡲلجحيم࣌', NULL, 588, 'local:warsh-text.json'),
  ('warsh-83-17', 'warsh', 83, 17, 'ثُمَّ يُقَالُ هَٰذَا ࡰ۬لذِے كُنتُم بِهِۦ تُكَذِّبُونَ࣌', 'ثم يقال هذا ࡰلذے كنتم به تكذبون࣌', NULL, 588, 'local:warsh-text.json'),
  ('warsh-83-18', 'warsh', 83, 18, 'كَلَّآ إِنَّ كِتَٰبَ ࡰ۬لَابْرٜارِ لَفِے عِلِّيِّينَ࣌', 'كلا إن كتب ࡰلابرار لفے عليين࣌', NULL, 588, 'local:warsh-text.json'),
  ('warsh-83-19', 'warsh', 83, 19, 'وَمَآ أَدْرٜيٰكَ مَا عِلِّيُّونَ', 'وما أدريك ما عليون', NULL, 588, 'local:warsh-text.json'),
  ('warsh-83-20', 'warsh', 83, 20, 'كِتَٰبࣱ مَّرْقُومࣱ', 'كتب مرقوم', NULL, 588, 'local:warsh-text.json'),
  ('warsh-83-21', 'warsh', 83, 21, 'يَشْهَدُهُ ࡲ۬لْمُقَرَّبُونَ࣌', 'يشهده ࡲلمقربون࣌', NULL, 588, 'local:warsh-text.json'),
  ('warsh-83-22', 'warsh', 83, 22, 'إِنَّ ࡰ۬لَابْرَارَ لَفِے نَعِيمٍ', 'إن ࡰلابرار لفے نعيم', NULL, 588, 'local:warsh-text.json'),
  ('warsh-83-23', 'warsh', 83, 23, 'عَلَى ࡰ۬لَارَآئِكِ يَنظُرُونَ', 'على ࡰلارائك ينظرون', NULL, 588, 'local:warsh-text.json'),
  ('warsh-83-24', 'warsh', 83, 24, 'تَعْرِفُ فِے وُجُوهِهِمْ نَضْرَةَ ࡰ۬لنَّعِيمِ', 'تعرف فے وجوههم نضرة ࡰلنعيم', NULL, 588, 'local:warsh-text.json'),
  ('warsh-83-25', 'warsh', 83, 25, 'يُسْقَوْنَ مِن رَّحِيقࣲ مَّخْتُومٍ', 'يسقون من رحيق مختوم', NULL, 588, 'local:warsh-text.json'),
  ('warsh-83-26', 'warsh', 83, 26, 'خِتَٰمُهُۥ مِسْكࣱ࣌ وَفِے ذَٰلِكَ فَلْيَتَنَافَسِ ࡴ۬لْمُتَنَٰفِسُونَ࣌', 'ختمه مسك࣌ وفے ذلك فليتنافس ࡴلمتنفسون࣌', NULL, 588, 'local:warsh-text.json'),
  ('warsh-83-27', 'warsh', 83, 27, 'وَمِزَاجُهُۥ مِن تَسْنِيمٍ', 'ومزاجه من تسنيم', NULL, 588, 'local:warsh-text.json'),
  ('warsh-83-28', 'warsh', 83, 28, 'عَيْناࣰ يَشْرَبُ بِهَا ࡰ۬لْمُقَرَّبُونَ࣌', 'عينا يشرب بها ࡰلمقربون࣌', NULL, 588, 'local:warsh-text.json'),
  ('warsh-83-29', 'warsh', 83, 29, 'إِنَّ ࡰ۬لذِينَ أَجْرَمُواْ كَانُواْ مِنَ ࡰ۬لذِينَ ءَامَنُواْ يَضْحَكُونَ', 'إن ࡰلذين أجرموا كانوا من ࡰلذين ءامنوا يضحكون', NULL, 588, 'local:warsh-text.json'),
  ('warsh-83-30', 'warsh', 83, 30, 'وَإِذَا مَرُّواْ بِهِمْ يَتَغَامَزُونَ', 'وإذا مروا بهم يتغامزون', NULL, 588, 'local:warsh-text.json'),
  ('warsh-83-31', 'warsh', 83, 31, 'وَإِذَا ࡰٜنقَلَبُوٓاْ إِلَىٰٓ أَهْلِهِمُ ࡲٜنقَلَبُواْ فَٰكِهِينَ', 'وإذا ࡰنقلبوا إلى أهلهم ࡲنقلبوا فكهين', NULL, 588, 'local:warsh-text.json'),
  ('warsh-83-32', 'warsh', 83, 32, 'وَإِذَا رَأَوْهُمْ قَالُوٓاْ إِنَّ هَٰٓؤُلَآءِ لَضَآلُّونَ', 'وإذا رأوهم قالوا إن هؤلاء لضالون', NULL, 588, 'local:warsh-text.json'),
  ('warsh-83-33', 'warsh', 83, 33, 'وَمَآ أُرْسِلُواْ عَلَيْهِمْ حَٰفِظِينَ࣌', 'وما أرسلوا عليهم حفظين࣌', NULL, 588, 'local:warsh-text.json'),
  ('warsh-83-34', 'warsh', 83, 34, 'فَالْيَوْمَ ࡰ۬لذِينَ ءَامَنُواْ مِنَ ࡰ۬لْكُفّٜارِ يَضْحَكُونَ', 'فاليوم ࡰلذين ءامنوا من ࡰلكفار يضحكون', NULL, 589, 'local:warsh-text.json'),
  ('warsh-83-35', 'warsh', 83, 35, 'عَلَى ࡰ۬لَارَآئِكِ࣌ يَنظُرُونَ', 'على ࡰلارائك࣌ ينظرون', NULL, 589, 'local:warsh-text.json'),
  ('warsh-83-36', 'warsh', 83, 36, 'هَلْ ثُوِّبَ ࡰ۬لْكُفَّارُ مَا كَانُواْ يَفْعَلُونَ࣌', 'هل ثوب ࡰلكفار ما كانوا يفعلون࣌', NULL, 589, 'local:warsh-text.json'),
  ('warsh-84-1', 'warsh', 84, 1, 'إِذَا ࡰ۬لسَّمَآءُ ࡲٜنشَقَّتْ', 'إذا ࡰلسماء ࡲنشقت', NULL, 589, 'local:warsh-text.json'),
  ('warsh-84-2', 'warsh', 84, 2, 'وَأَذِنَتْ لِرَبِّهَا وَحُقَّتْ', 'وأذنت لربها وحقت', NULL, 589, 'local:warsh-text.json'),
  ('warsh-84-3', 'warsh', 84, 3, 'وَإِذَا ࡰ۬لَارْضُ مُدَّتْ', 'وإذا ࡰلارض مدت', NULL, 589, 'local:warsh-text.json'),
  ('warsh-84-4', 'warsh', 84, 4, 'وَأَلْقَتْ مَا فِيهَا وَتَخَلَّتْ', 'وألقت ما فيها وتخلت', NULL, 589, 'local:warsh-text.json'),
  ('warsh-84-5', 'warsh', 84, 5, 'وَأَذِنَتْ لِرَبِّهَا وَحُقَّتْ࣌', 'وأذنت لربها وحقت࣌', NULL, 589, 'local:warsh-text.json'),
  ('warsh-84-6', 'warsh', 84, 6, 'يَٰٓأَيُّهَا ࡰ۬لِانسَٰنُ إِنَّكَ كَادِحٌ ࡴلَىٰ رَبِّكَ كَدْحاࣰ فَمُلَٰقِيهِ࣌', 'يأيها ࡰلانسن إنك كادح ࡴلى ربك كدحا فملقيه࣌', NULL, 589, 'local:warsh-text.json'),
  ('warsh-84-7', 'warsh', 84, 7, 'فَأَمَّا مَنُ ࡳوتِيَ كِتَٰبَهُۥ بِيَمِينِهِۦ', 'فأما من ࡳوتي كتبه بيمينه', NULL, 589, 'local:warsh-text.json'),
  ('warsh-84-8', 'warsh', 84, 8, 'فَسَوْفَ يُحَاسَبُ حِسَاباࣰ يَسِيراࣰ', 'فسوف يحاسب حسابا يسيرا', NULL, 589, 'local:warsh-text.json'),
  ('warsh-84-9', 'warsh', 84, 9, 'وَيَنقَلِبُ إِلَىٰٓ أَهْلِهِۦ مَسْرُوراࣰ࣌', 'وينقلب إلى أهله مسرورا࣌', NULL, 589, 'local:warsh-text.json'),
  ('warsh-84-10', 'warsh', 84, 10, 'وَأَمَّا مَنُ ࡳوتِيَ كِتَٰبَهُۥ وَرَآءَ ظَهْرِهِۦ', 'وأما من ࡳوتي كتبه وراء ظهره', NULL, 589, 'local:warsh-text.json'),
  ('warsh-84-11', 'warsh', 84, 11, 'فَسَوْفَ يَدْعُواْ ثُبُوراࣰ', 'فسوف يدعوا ثبورا', NULL, 589, 'local:warsh-text.json'),
  ('warsh-84-12', 'warsh', 84, 12, 'وَيُصَلَّىٰ سَعِيراً࣌', 'ويصلى سعيرا࣌', NULL, 589, 'local:warsh-text.json'),
  ('warsh-84-13', 'warsh', 84, 13, 'ࡴنَّهُۥ كَانَ فِےٓ أَهْلِهِۦ مَسْرُوراً࣌', 'ࡴنه كان فے أهله مسرورا࣌', NULL, 589, 'local:warsh-text.json'),
  ('warsh-84-14', 'warsh', 84, 14, 'ࡴنَّهُۥ ظَنَّ أَن لَّنْ يَّحُورَ', 'ࡴنه ظن أن لن يحور', NULL, 589, 'local:warsh-text.json'),
  ('warsh-84-15', 'warsh', 84, 15, 'بَلٜىٰٓ࣌ إِنَّ رَبَّهُۥ كَانَ بِهِۦ بَصِيراࣰ࣌', 'بلى࣌ إن ربه كان به بصيرا࣌', NULL, 589, 'local:warsh-text.json'),
  ('warsh-84-16', 'warsh', 84, 16, '۞ فَلَآ أُقْسِمُ بِالشَّفَقِ', 'فلا أقسم بالشفق', NULL, 589, 'local:warsh-text.json'),
  ('warsh-84-17', 'warsh', 84, 17, 'وَاليْلِ وَمَا وَسَقَ', 'واليل وما وسق', NULL, 589, 'local:warsh-text.json'),
  ('warsh-84-18', 'warsh', 84, 18, 'وَالْقَمَرِ إِذَا ࡰٜتَّسَقَ', 'والقمر إذا ࡰتسق', NULL, 589, 'local:warsh-text.json'),
  ('warsh-84-19', 'warsh', 84, 19, 'لَتَرْكَبُنَّ طَبَقاً عَن طَبَقࣲ࣌', 'لتركبن طبقا عن طبق࣌', NULL, 589, 'local:warsh-text.json'),
  ('warsh-84-20', 'warsh', 84, 20, 'فَمَا لَهُمْ لَا يُومِنُونَ', 'فما لهم لا يومنون', NULL, 589, 'local:warsh-text.json'),
  ('warsh-84-21', 'warsh', 84, 21, 'وَإِذَا قُرِۓَ عَلَيْهِمُ ࡲ۬لْقُرْءَانُ لَا يَسْجُدُونَ࣌۩', 'وإذا قرے عليهم ࡲلقرءان لا يسجدون࣌', NULL, 589, 'local:warsh-text.json'),
  ('warsh-84-22', 'warsh', 84, 22, 'بَلِ ࡴ۬لذِينَ كَفَرُواْ يُكَذِّبُونَ', 'بل ࡴلذين كفروا يكذبون', NULL, 589, 'local:warsh-text.json'),
  ('warsh-84-23', 'warsh', 84, 23, 'وَاللَّهُ أَعْلَمُ بِمَا يُوعُونَ࣌', 'والله أعلم بما يوعون࣌', NULL, 589, 'local:warsh-text.json'),
  ('warsh-84-24', 'warsh', 84, 24, 'فَبَشِّرْهُم بِعَذَابٍ ࡰلِيمٍ࣌', 'فبشرهم بعذاب ࡰليم࣌', NULL, 589, 'local:warsh-text.json'),
  ('warsh-84-25', 'warsh', 84, 25, 'ࡴلَّا ࡰ۬لذِينَ ءَامَنُواْ وَعَمِلُواْ ࡲ۬لصَّٰلِحَٰتِ لَهُمُۥٓ أَجْرٌ غَيْرُ مَمْنُونࣲ࣌', 'ࡴلا ࡰلذين ءامنوا وعملوا ࡲلصلحت لهم أجر غير ممنون࣌', NULL, 590, 'local:warsh-text.json'),
  ('warsh-85-1', 'warsh', 85, 1, 'وَالسَّمَآءِ ذَاتِ ࡴ۬لْبُرُوجِ', 'والسماء ذات ࡴلبروج', NULL, 590, 'local:warsh-text.json'),
  ('warsh-85-2', 'warsh', 85, 2, 'وَالْيَوْمِ ࡴ۬لْمَوْعُودِ', 'واليوم ࡴلموعود', NULL, 590, 'local:warsh-text.json'),
  ('warsh-85-3', 'warsh', 85, 3, 'وَشَاهِدࣲ وَمَشْهُودࣲ', 'وشاهد ومشهود', NULL, 590, 'local:warsh-text.json'),
  ('warsh-85-4', 'warsh', 85, 4, 'قُتِلَ أَصْحَٰبُ ࡲ۬لُاخْدُودِ', 'قتل أصحب ࡲلاخدود', NULL, 590, 'local:warsh-text.json'),
  ('warsh-85-5', 'warsh', 85, 5, 'ࡴ۬لنّٜارِ ذَاتِ ࡴ۬لْوَقُودِ', 'ࡴلنار ذات ࡴلوقود', NULL, 590, 'local:warsh-text.json'),
  ('warsh-85-6', 'warsh', 85, 6, 'إِذْ هُمْ عَلَيْهَا قُعُودࣱ', 'إذ هم عليها قعود', NULL, 590, 'local:warsh-text.json'),
  ('warsh-85-7', 'warsh', 85, 7, 'وَهُمْ عَلَىٰ مَا يَفْعَلُونَ بِالْمُومِنِينَ شُهُودࣱ࣌', 'وهم على ما يفعلون بالمومنين شهود࣌', NULL, 590, 'local:warsh-text.json'),
  ('warsh-85-8', 'warsh', 85, 8, 'وَمَا نَقَمُواْ مِنْهُمُۥٓ إِلَّآ أَنْ يُّومِنُواْ بِاللَّهِ ࡴ۬لْعَزِيزِ ࡴ۬لْحَمِيدِ', 'وما نقموا منهم إلا أن يومنوا بالله ࡴلعزيز ࡴلحميد', NULL, 590, 'local:warsh-text.json'),
  ('warsh-85-9', 'warsh', 85, 9, 'ࡴ۬لذِے لَهُۥ مُلْكُ ࡲ۬لسَّمَٰوَٰتِ وَالَارْضِ࣌ وَاللَّهُ عَلَىٰ كُلِّ شَےْءࣲ شَهِيدٌ࣌', 'ࡴلذے له ملك ࡲلسموت والارض࣌ والله على كل شےء شهيد࣌', NULL, 590, 'local:warsh-text.json'),
  ('warsh-85-10', 'warsh', 85, 10, 'ࡴنَّ ࡰ۬لذِينَ فَتَنُواْ ࡲ۬لْمُومِنِينَ وَالْمُومِنَٰتِ ثُمَّ لَمْ يَتُوبُواْ فَلَهُمْ عَذَابُ جَهَنَّمَ وَلَهُمْ عَذَابُ ࡲ۬لْحَرِيقِ࣌', 'ࡴن ࡰلذين فتنوا ࡲلمومنين والمومنت ثم لم يتوبوا فلهم عذاب جهنم ولهم عذاب ࡲلحريق࣌', NULL, 590, 'local:warsh-text.json'),
  ('warsh-85-11', 'warsh', 85, 11, 'إِنَّ ࡰ۬لذِينَ ءَامَنُواْ وَعَمِلُواْ ࡲ۬لصَّٰلِحَٰتِ لَهُمْ جَنَّٰتࣱ تَجْرِے مِن تَحْتِهَا ࡰ۬لَانْهَٰرُ࣌ ذَٰلِكَ ࡰ۬لْفَوْزُ ࡲ۬لْكَبِيرُ࣌', 'إن ࡰلذين ءامنوا وعملوا ࡲلصلحت لهم جنت تجرے من تحتها ࡰلانهر࣌ ذلك ࡰلفوز ࡲلكبير࣌', NULL, 590, 'local:warsh-text.json'),
  ('warsh-85-12', 'warsh', 85, 12, '۞ إِنَّ بَطْشَ رَبِّكَ لَشَدِيدٌ࣌', 'إن بطش ربك لشديد࣌', NULL, 590, 'local:warsh-text.json'),
  ('warsh-85-13', 'warsh', 85, 13, 'ࡴنَّهُۥ هُوَ يُبْدِۓُ وَيُعِيدُ࣌', 'ࡴنه هو يبدے ويعيد࣌', NULL, 590, 'local:warsh-text.json'),
  ('warsh-85-14', 'warsh', 85, 14, 'وَهُوَ ࡰ۬لْغَفُورُ ࡲ۬لْوَدُودُ', 'وهو ࡰلغفور ࡲلودود', NULL, 590, 'local:warsh-text.json'),
  ('warsh-85-15', 'warsh', 85, 15, 'ذُو ࡲ۬لْعَرْشِ࣌ ࡴ۬لْمَجِيدُ', 'ذو ࡲلعرش࣌ ࡴلمجيد', NULL, 590, 'local:warsh-text.json'),
  ('warsh-85-16', 'warsh', 85, 16, 'فَعَّالࣱ لِّمَا يُرِيدُ࣌', 'فعال لما يريد࣌', NULL, 590, 'local:warsh-text.json'),
  ('warsh-85-17', 'warsh', 85, 17, 'هَلَ ࡰتٜيٰكَ حَدِيثُ ࡲ۬لْجُنُودِ', 'هل ࡰتيك حديث ࡲلجنود', NULL, 590, 'local:warsh-text.json'),
  ('warsh-85-18', 'warsh', 85, 18, 'فِرْعَوْنَ وَثَمُودَ࣌', 'فرعون وثمود࣌', NULL, 590, 'local:warsh-text.json'),
  ('warsh-85-19', 'warsh', 85, 19, 'بَلِ ࡴ۬لذِينَ كَفَرُواْ فِے تَكْذِيبࣲ', 'بل ࡴلذين كفروا فے تكذيب', NULL, 590, 'local:warsh-text.json'),
  ('warsh-85-20', 'warsh', 85, 20, 'وَاللَّهُ مِنْ وَّرَآئِهِم مُّحِيطُۢ࣌', 'والله من ورائهم محيط࣌', NULL, 590, 'local:warsh-text.json'),
  ('warsh-85-21', 'warsh', 85, 21, 'بَلْ هُوَ قُرْءَانࣱ مَّجِيدࣱ', 'بل هو قرءان مجيد', NULL, 590, 'local:warsh-text.json'),
  ('warsh-85-22', 'warsh', 85, 22, 'فِے لَوْحࣲ مَّحْفُوظࣱ࣌', 'فے لوح محفوظ࣌', NULL, 590, 'local:warsh-text.json'),
  ('warsh-86-1', 'warsh', 86, 1, 'وَالسَّمَآءِ وَالطَّارِقِ', 'والسماء والطارق', NULL, 591, 'local:warsh-text.json'),
  ('warsh-86-2', 'warsh', 86, 2, 'وَمَآ أَدْرٜيٰكَ مَا ࡰ۬لطَّارِقُ', 'وما أدريك ما ࡰلطارق', NULL, 591, 'local:warsh-text.json'),
  ('warsh-86-3', 'warsh', 86, 3, 'ࡲ۬لنَّجْمُ ࡲ۬لثَّاقِبُ', 'ࡲلنجم ࡲلثاقب', NULL, 591, 'local:warsh-text.json'),
  ('warsh-86-4', 'warsh', 86, 4, 'إِن كُلُّ نَفْسࣲ لَّمَا عَلَيْهَا حَافِظࣱ࣌', 'إن كل نفس لما عليها حافظ࣌', NULL, 591, 'local:warsh-text.json'),
  ('warsh-86-5', 'warsh', 86, 5, 'فَلْيَنظُرِ ࡴ۬لِانسَٰنُ مِمَّ خُلِقَ࣌', 'فلينظر ࡴلانسن مم خلق࣌', NULL, 591, 'local:warsh-text.json'),
  ('warsh-86-6', 'warsh', 86, 6, 'خُلِقَ مِن مَّآءࣲ دَافِقࣲ', 'خلق من ماء دافق', NULL, 591, 'local:warsh-text.json'),
  ('warsh-86-7', 'warsh', 86, 7, 'يَخْرُجُ مِنۢ بَيْنِ ࡴ۬لصُّلْبِ وَالتَّرَآئِبِ࣌', 'يخرج من بين ࡴلصلب والترائب࣌', NULL, 591, 'local:warsh-text.json'),
  ('warsh-86-8', 'warsh', 86, 8, 'إِنَّهُۥ عَلَىٰ رَجْعِهِۦ لَقَادِرࣱ', 'إنه على رجعه لقادر', NULL, 591, 'local:warsh-text.json'),
  ('warsh-86-9', 'warsh', 86, 9, 'يَوْمَ تُبْلَى ࡰ۬لسَّرَآئِرُ', 'يوم تبلى ࡰلسرائر', NULL, 591, 'local:warsh-text.json'),
  ('warsh-86-10', 'warsh', 86, 10, 'فَمَا لَهُۥ مِن قُوَّةࣲ وَلَا نَاصِرࣲ࣌', 'فما له من قوة ولا ناصر࣌', NULL, 591, 'local:warsh-text.json'),
  ('warsh-86-11', 'warsh', 86, 11, 'وَالسَّمَآءِ ذَاتِ ࡴ۬لرَّجْعِ', 'والسماء ذات ࡴلرجع', NULL, 591, 'local:warsh-text.json'),
  ('warsh-86-12', 'warsh', 86, 12, 'وَالَارْضِ ذَاتِ ࡴ۬لصَّدْعِ', 'والارض ذات ࡴلصدع', NULL, 591, 'local:warsh-text.json'),
  ('warsh-86-13', 'warsh', 86, 13, 'إِنَّهُۥ لَقَوْلࣱ فَصْلࣱ', 'إنه لقول فصل', NULL, 591, 'local:warsh-text.json'),
  ('warsh-86-14', 'warsh', 86, 14, 'وَمَا هُوَ بِالْهَزْلِ࣌', 'وما هو بالهزل࣌', NULL, 591, 'local:warsh-text.json'),
  ('warsh-86-15', 'warsh', 86, 15, 'إِنَّهُمْ يَكِيدُونَ كَيْداࣰ', 'إنهم يكيدون كيدا', NULL, 591, 'local:warsh-text.json'),
  ('warsh-86-16', 'warsh', 86, 16, 'وَأَكِيدُ كَيْداࣰ࣌', 'وأكيد كيدا࣌', NULL, 591, 'local:warsh-text.json'),
  ('warsh-86-17', 'warsh', 86, 17, 'فَمَهِّلِ ࡴ۬لْكٜـٰفِرِينَ أَمْهِلْهُمْ رُوَيْداࣰ࣌', 'فمهل ࡴلكفرين أمهلهم رويدا࣌', NULL, 591, 'local:warsh-text.json'),
  ('warsh-87-1', 'warsh', 87, 1, 'سَبِّحِ ࡴٜسْمَ رَبِّكَ ࡰ۬لَاعْلَي', 'سبح ࡴسم ربك ࡰلاعلي', NULL, 591, 'local:warsh-text.json'),
  ('warsh-87-2', 'warsh', 87, 2, 'ࡰ۬لذِے خَلَقَ فَسَوّٜىٰ', 'ࡰلذے خلق فسوى', NULL, 591, 'local:warsh-text.json'),
  ('warsh-87-3', 'warsh', 87, 3, 'وَالذِے قَدَّرَ فَهَدٜىٰ', 'والذے قدر فهدى', NULL, 591, 'local:warsh-text.json'),
  ('warsh-87-4', 'warsh', 87, 4, 'وَالذِےٓ أَخْرَجَ ࡰ۬لْمَرْعٜىٰ', 'والذے أخرج ࡰلمرعى', NULL, 591, 'local:warsh-text.json'),
  ('warsh-87-5', 'warsh', 87, 5, 'فَجَعَلَهُۥ غُثَآءً ࡰحْوٜىٰ࣌', 'فجعله غثاء ࡰحوى࣌', NULL, 591, 'local:warsh-text.json'),
  ('warsh-87-6', 'warsh', 87, 6, 'سَنُقْرِئُكَ فَلَا تَنسٜىٰٓ', 'سنقرئك فلا تنسى', NULL, 591, 'local:warsh-text.json'),
  ('warsh-87-7', 'warsh', 87, 7, 'إِلَّا مَا شَآءَ ࡰ۬للَّهُ࣌ إِنَّهُۥ يَعْلَمُ ࡲ۬لْجَهْرَ وَمَا يَخْفٜىٰ࣌', 'إلا ما شاء ࡰلله࣌ إنه يعلم ࡲلجهر وما يخفى࣌', NULL, 591, 'local:warsh-text.json'),
  ('warsh-87-8', 'warsh', 87, 8, 'وَنُيَسِّرُكَ لِلْيُسْرٜىٰ࣌', 'ونيسرك لليسرى࣌', NULL, 591, 'local:warsh-text.json'),
  ('warsh-87-9', 'warsh', 87, 9, 'فَذَكِّرِ ࡴن نَّفَعَتِ ࡴ۬لذِّكْرٜىٰ࣌', 'فذكر ࡴن نفعت ࡴلذكرى࣌', NULL, 591, 'local:warsh-text.json'),
  ('warsh-87-10', 'warsh', 87, 10, 'سَيَذَّكَّرُ مَنْ يَّخْشٜىٰ', 'سيذكر من يخشى', NULL, 591, 'local:warsh-text.json'),
  ('warsh-87-11', 'warsh', 87, 11, 'وَيَتَجَنَّبُهَا ࡰ۬لَاشْقَي', 'ويتجنبها ࡰلاشقي', NULL, 592, 'local:warsh-text.json'),
  ('warsh-87-12', 'warsh', 87, 12, 'ࡰ۬لذِے يَصْلَى ࡰ۬لنَّارَ ࡰ۬لْكُبْرٜىٰ', 'ࡰلذے يصلى ࡰلنار ࡰلكبرى', NULL, 592, 'local:warsh-text.json'),
  ('warsh-87-13', 'warsh', 87, 13, 'ثُمَّ لَا يَمُوتُ فِيهَا وَلَا يَحْيٜىٰ࣌', 'ثم لا يموت فيها ولا يحيى࣌', NULL, 592, 'local:warsh-text.json'),
  ('warsh-87-14', 'warsh', 87, 14, 'قَدَ ࡰفْلَحَ مَن تَزَكّٜىٰ', 'قد ࡰفلح من تزكى', NULL, 592, 'local:warsh-text.json'),
  ('warsh-87-15', 'warsh', 87, 15, 'وَذَكَرَ ࡰٜسْمَ رَبِّهِۦ فَصَلّٜىٰ࣌', 'وذكر ࡰسم ربه فصلى࣌', NULL, 592, 'local:warsh-text.json'),
  ('warsh-87-16', 'warsh', 87, 16, 'بَلْ تُوثِرُونَ ࡰ۬لْحَيَوٰةَ ࡰ۬لدُّنْيٜا', 'بل توثرون ࡰلحيوة ࡰلدنيا', NULL, 592, 'local:warsh-text.json'),
  ('warsh-87-17', 'warsh', 87, 17, 'وَالَاخِرَةُ خَيْرࣱ وَأَبْقٜىٰٓ࣌', 'والاخرة خير وأبقى࣌', NULL, 592, 'local:warsh-text.json'),
  ('warsh-87-18', 'warsh', 87, 18, 'إِنَّ هَٰذَا لَفِے ࡴ۬لصُّحُفِ ࡴ۬لُاولٜىٰ', 'إن هذا لفے ࡴلصحف ࡴلاولى', NULL, 592, 'local:warsh-text.json'),
  ('warsh-87-19', 'warsh', 87, 19, 'صُحُفِ إِبْرَٰهِيمَ وَمُوسٜىٰ࣌', 'صحف إبرهيم وموسى࣌', NULL, 592, 'local:warsh-text.json'),
  ('warsh-88-1', 'warsh', 88, 1, 'هَلَ ࡰتٜيٰكَ حَدِيثُ ࡲ۬لْغَٰشِيَةِ࣌', 'هل ࡰتيك حديث ࡲلغشية࣌', NULL, 592, 'local:warsh-text.json'),
  ('warsh-88-2', 'warsh', 88, 2, 'وُجُوهࣱ يَوْمَئِذٍ خَٰشِعَةٌ', 'وجوه يومئذ خشعة', NULL, 592, 'local:warsh-text.json'),
  ('warsh-88-3', 'warsh', 88, 3, 'عَامِلَةࣱ نَّاصِبَةࣱ', 'عاملة ناصبة', NULL, 592, 'local:warsh-text.json'),
  ('warsh-88-4', 'warsh', 88, 4, 'تَصْلَىٰ نَاراً حَامِيَةࣰ', 'تصلى نارا حامية', NULL, 592, 'local:warsh-text.json'),
  ('warsh-88-5', 'warsh', 88, 5, 'تُسْقٜىٰ مِنْ عَيْنٍ اٰنِيَةࣲ࣌', 'تسقى من عين انية࣌', NULL, 592, 'local:warsh-text.json'),
  ('warsh-88-6', 'warsh', 88, 6, 'لَّيْسَ لَهُمْ طَعَامٌ ࡴلَّا مِن ضَرِيعࣲ', 'ليس لهم طعام ࡴلا من ضريع', NULL, 592, 'local:warsh-text.json'),
  ('warsh-88-7', 'warsh', 88, 7, 'لَّا يُسْمِنُ وَلَا يُغْنِے مِن جُوعࣲ࣌', 'لا يسمن ولا يغنے من جوع࣌', NULL, 592, 'local:warsh-text.json'),
  ('warsh-88-8', 'warsh', 88, 8, 'وُجُوهࣱ يَوْمَئِذࣲ نَّاعِمَةࣱ', 'وجوه يومئذ ناعمة', NULL, 592, 'local:warsh-text.json'),
  ('warsh-88-9', 'warsh', 88, 9, 'لِّسَعْيِهَا رَاضِيَةࣱ', 'لسعيها راضية', NULL, 592, 'local:warsh-text.json'),
  ('warsh-88-10', 'warsh', 88, 10, 'فِے جَنَّةٍ عَالِيَةࣲ', 'فے جنة عالية', NULL, 592, 'local:warsh-text.json'),
  ('warsh-88-11', 'warsh', 88, 11, 'لَّا تُسْمَعُ فِيهَا لَٰغِيَةࣱ࣌', 'لا تسمع فيها لغية࣌', NULL, 592, 'local:warsh-text.json'),
  ('warsh-88-12', 'warsh', 88, 12, 'فِيهَا عَيْنࣱ جَارِيَةࣱ࣌', 'فيها عين جارية࣌', NULL, 592, 'local:warsh-text.json'),
  ('warsh-88-13', 'warsh', 88, 13, 'فِيهَا سُرُرࣱ مَّرْفُوعَةࣱ', 'فيها سرر مرفوعة', NULL, 592, 'local:warsh-text.json'),
  ('warsh-88-14', 'warsh', 88, 14, 'وَأَكْوَابࣱ مَّوْضُوعَةࣱ', 'وأكواب موضوعة', NULL, 592, 'local:warsh-text.json'),
  ('warsh-88-15', 'warsh', 88, 15, 'وَنَمَارِقُ مَصْفُوفَةࣱ', 'ونمارق مصفوفة', NULL, 592, 'local:warsh-text.json'),
  ('warsh-88-16', 'warsh', 88, 16, 'وَزَرَابِيُّ مَبْثُوثَةٌ࣌', 'وزرابي مبثوثة࣌', NULL, 592, 'local:warsh-text.json'),
  ('warsh-88-17', 'warsh', 88, 17, '۞ ࡰفَلَا يَنظُرُونَ إِلَى ࡰ۬لِابِلِ كَيْفَ خُلِقَتْ', 'ࡰفلا ينظرون إلى ࡰلابل كيف خلقت', NULL, 592, 'local:warsh-text.json'),
  ('warsh-88-18', 'warsh', 88, 18, 'وَإِلَى ࡰ۬لسَّمَآءِ كَيْفَ رُفِعَتْ', 'وإلى ࡰلسماء كيف رفعت', NULL, 592, 'local:warsh-text.json'),
  ('warsh-88-19', 'warsh', 88, 19, 'وَإِلَى ࡰ۬لْجِبَالِ كَيْفَ نُصِبَتْ', 'وإلى ࡰلجبال كيف نصبت', NULL, 592, 'local:warsh-text.json'),
  ('warsh-88-20', 'warsh', 88, 20, 'وَإِلَى ࡰ۬لَارْضِ كَيْفَ سُطِحَتْ࣌', 'وإلى ࡰلارض كيف سطحت࣌', NULL, 592, 'local:warsh-text.json'),
  ('warsh-88-21', 'warsh', 88, 21, 'فَذَكِّرِ ࡴنَّمَآ أَنتَ مُذَكِّرࣱ࣌', 'فذكر ࡴنما أنت مذكر࣌', NULL, 592, 'local:warsh-text.json'),
  ('warsh-88-22', 'warsh', 88, 22, 'لَّسْتَ عَلَيْهِم بِمُصَيْطِرٍ࣌', 'لست عليهم بمصيطر࣌', NULL, 592, 'local:warsh-text.json'),
  ('warsh-88-23', 'warsh', 88, 23, 'ࡴلَّا مَن تَوَلّٜىٰ وَكَفَرَ', 'ࡴلا من تولى وكفر', NULL, 593, 'local:warsh-text.json'),
  ('warsh-88-24', 'warsh', 88, 24, 'فَيُعَذِّبُهُ ࡲ۬للَّهُ ࡲ۬لْعَذَابَ ࡰ۬لَاكْبَرَ࣌', 'فيعذبه ࡲلله ࡲلعذاب ࡰلاكبر࣌', NULL, 593, 'local:warsh-text.json'),
  ('warsh-88-25', 'warsh', 88, 25, 'إِنَّ إِلَيْنَآ إِيَابَهُمْ', 'إن إلينا إيابهم', NULL, 593, 'local:warsh-text.json'),
  ('warsh-88-26', 'warsh', 88, 26, 'ثُمَّ إِنَّ عَلَيْنَا حِسَابَهُمْ࣌', 'ثم إن علينا حسابهم࣌', NULL, 593, 'local:warsh-text.json'),
  ('warsh-89-1', 'warsh', 89, 1, 'وَالْفَجْرِ', 'والفجر', NULL, 593, 'local:warsh-text.json'),
  ('warsh-89-2', 'warsh', 89, 2, 'وَلَيَالٍ عَشْرࣲ', 'وليال عشر', NULL, 593, 'local:warsh-text.json'),
  ('warsh-89-3', 'warsh', 89, 3, 'وَالشَّفْعِ وَالْوَتْرِ', 'والشفع والوتر', NULL, 593, 'local:warsh-text.json'),
  ('warsh-89-4', 'warsh', 89, 4, 'وَاليْلِ إِذَا يَسْرِۦ', 'واليل إذا يسر', NULL, 593, 'local:warsh-text.json'),
  ('warsh-89-5', 'warsh', 89, 5, 'هَلْ فِے ذَٰلِكَ قَسَمࣱ لِّذِے حِجْرٍ࣌', 'هل فے ذلك قسم لذے حجر࣌', NULL, 593, 'local:warsh-text.json'),
  ('warsh-89-6', 'warsh', 89, 6, 'ࡰلَمْ تَرَ كَيْفَ فَعَلَ رَبُّكَ بِعَادٍ', 'ࡰلم تر كيف فعل ربك بعاد', NULL, 593, 'local:warsh-text.json'),
  ('warsh-89-7', 'warsh', 89, 7, 'ࡴرَمَ ذَاتِ ࡴ۬لْعِمَادِ', 'ࡴرم ذات ࡴلعماد', NULL, 593, 'local:warsh-text.json'),
  ('warsh-89-8', 'warsh', 89, 8, 'ࡴ۬لتِے لَمْ يُخْلَقْ مِثْلُهَا فِے ࡴ۬لْبِلَٰدِ', 'ࡴلتے لم يخلق مثلها فے ࡴلبلد', NULL, 593, 'local:warsh-text.json'),
  ('warsh-89-9', 'warsh', 89, 9, 'وَثَمُودَ ࡰ۬لذِينَ جَابُواْ ࡲ۬لصَّخْرَ بِالْوَادِۦ', 'وثمود ࡰلذين جابوا ࡲلصخر بالواد', NULL, 593, 'local:warsh-text.json'),
  ('warsh-89-10', 'warsh', 89, 10, 'وَفِرْعَوْنَ ذِے ࡴ۬لَاوْتَادِ', 'وفرعون ذے ࡴلاوتاد', NULL, 593, 'local:warsh-text.json'),
  ('warsh-89-11', 'warsh', 89, 11, 'ࡴ۬لذِينَ طَغَوْاْ فِے ࡴ۬لْبِلَٰدِ', 'ࡴلذين طغوا فے ࡴلبلد', NULL, 593, 'local:warsh-text.json'),
  ('warsh-89-12', 'warsh', 89, 12, 'فَأَكْثَرُواْ فِيهَا ࡰ۬لْفَسَادَ', 'فأكثروا فيها ࡰلفساد', NULL, 593, 'local:warsh-text.json'),
  ('warsh-89-13', 'warsh', 89, 13, 'فَصَبَّ عَلَيْهِمْ رَبُّكَ سَوْطَ عَذَابٍ࣌', 'فصب عليهم ربك سوط عذاب࣌', NULL, 593, 'local:warsh-text.json'),
  ('warsh-89-14', 'warsh', 89, 14, 'ࡴنَّ رَبَّكَ لَبِالْمِرْصَادِ࣌', 'ࡴن ربك لبالمرصاد࣌', NULL, 593, 'local:warsh-text.json'),
  ('warsh-89-15', 'warsh', 89, 15, 'فَأَمَّا ࡰ۬لِانسَٰنُ إِذَا مَا ࡰٜبْتَلٜيٰهُ رَبُّهُۥ فَأَكْرَمَهُۥ وَنَعَّمَهُۥ', 'فأما ࡰلانسن إذا ما ࡰبتليه ربه فأكرمه ونعمه', NULL, 593, 'local:warsh-text.json'),
  ('warsh-89-16', 'warsh', 89, 16, 'فَيَقُولُ رَبِّيَ أَكْرَمَنِۦ࣌', 'فيقول ربي أكرمن࣌', NULL, 593, 'local:warsh-text.json'),
  ('warsh-89-17', 'warsh', 89, 17, 'وَأَمَّآ إِذَا مَا ࡰٜبْتَلٜيٰهُ فَقَدَرَ عَلَيْهِ رِزْقَهُۥ', 'وأما إذا ما ࡰبتليه فقدر عليه رزقه', NULL, 593, 'local:warsh-text.json'),
  ('warsh-89-18', 'warsh', 89, 18, 'فَيَقُولُ رَبِّيَ أَهَٰنَنِۦ', 'فيقول ربي أهنن', NULL, 593, 'local:warsh-text.json'),
  ('warsh-89-19', 'warsh', 89, 19, 'كَلَّا࣌ بَل لَّا تُكْرِمُونَ ࡰ۬لْيَتِيمَ', 'كلا࣌ بل لا تكرمون ࡰليتيم', NULL, 593, 'local:warsh-text.json'),
  ('warsh-89-20', 'warsh', 89, 20, 'وَلَا تَحُضُّونَ عَلَىٰ طَعَامِ ࡴ۬لْمِسْكِينِ', 'ولا تحضون على طعام ࡴلمسكين', NULL, 593, 'local:warsh-text.json'),
  ('warsh-89-21', 'warsh', 89, 21, 'وَتَاكُلُونَ ࡰ۬لتُّرَاثَ أَكْلاࣰ لَّمّاࣰ', 'وتاكلون ࡰلتراث أكلا لما', NULL, 593, 'local:warsh-text.json'),
  ('warsh-89-22', 'warsh', 89, 22, 'وَتُحِبُّونَ ࡰ۬لْمَالَ حُبّاࣰ جَمّاࣰ', 'وتحبون ࡰلمال حبا جما', NULL, 593, 'local:warsh-text.json'),
  ('warsh-89-23', 'warsh', 89, 23, 'كَلَّآ࣌ إِذَا دُكَّتِ ࡴ۬لَارْضُ دَكّاࣰ دَكّاࣰ', 'كلا࣌ إذا دكت ࡴلارض دكا دكا', NULL, 593, 'local:warsh-text.json'),
  ('warsh-89-24', 'warsh', 89, 24, 'وَجَآءَ رَبُّكَ وَالْمَلَكُ صَفّاࣰ صَفّاࣰ', 'وجاء ربك والملك صفا صفا', NULL, 593, 'local:warsh-text.json'),
  ('warsh-89-25', 'warsh', 89, 25, 'وَجِےٓءَ يَوْمَئِذِۢ بِجَهَنَّمَ', 'وجےء يومئذ بجهنم', NULL, 594, 'local:warsh-text.json'),
  ('warsh-89-26', 'warsh', 89, 26, 'يَوْمَئِذࣲ يَتَذَكَّرُ ࡲ۬لِانسَٰنُ وَأَنّٜىٰ لَهُ ࡲ۬لذِّكْرٜىٰ࣌', 'يومئذ يتذكر ࡲلانسن وأنى له ࡲلذكرى࣌', NULL, 594, 'local:warsh-text.json'),
  ('warsh-89-27', 'warsh', 89, 27, 'يَقُولُ يَٰلَيْتَنِے قَدَّمْتُ لِحَيَاتِے࣌', 'يقول يليتنے قدمت لحياتے࣌', NULL, 594, 'local:warsh-text.json'),
  ('warsh-89-28', 'warsh', 89, 28, 'فَيَوْمَئِذࣲ لَّا يُعَذِّبُ عَذَابَهُۥٓ أَحَدࣱ', 'فيومئذ لا يعذب عذابه أحد', NULL, 594, 'local:warsh-text.json'),
  ('warsh-89-29', 'warsh', 89, 29, 'وَلَا يُوثِقُ وَثَاقَهُۥٓ أَحَدࣱ࣌', 'ولا يوثق وثاقه أحد࣌', NULL, 594, 'local:warsh-text.json'),
  ('warsh-89-30', 'warsh', 89, 30, 'يَٰٓأَيَّتُهَا ࡰ۬لنَّفْسُ ࡲ۬لْمُطْمَئِنَّةُ', 'يأيتها ࡰلنفس ࡲلمطمئنة', NULL, 594, 'local:warsh-text.json'),
  ('warsh-89-31', 'warsh', 89, 31, 'ࡲٜرْجِعِےٓ إِلَىٰ رَبِّكِ رَاضِيَةࣰ مَّرْضِيَّةࣰ', 'ࡲرجعے إلى ربك راضية مرضية', NULL, 594, 'local:warsh-text.json'),
  ('warsh-89-32', 'warsh', 89, 32, 'فَادْخُلِے فِے عِبَٰدِے وَادْخُلِے جَنَّتِے࣌', 'فادخلے فے عبدے وادخلے جنتے࣌', NULL, 594, 'local:warsh-text.json')
insert into public.ayahs (id, riwayah, surah_number, ayah_number, text, simple_text, juz, page, source) values
  ('warsh-90-1', 'warsh', 90, 1, 'لَآ أُقْسِمُ بِهَٰذَا ࡰ۬لْبَلَدِ', 'لا أقسم بهذا ࡰلبلد', NULL, 594, 'local:warsh-text.json'),
  ('warsh-90-2', 'warsh', 90, 2, 'وَأَنتَ حِلُّۢ بِهَٰذَا ࡰ۬لْبَلَدِ', 'وأنت حل بهذا ࡰلبلد', NULL, 594, 'local:warsh-text.json'),
  ('warsh-90-3', 'warsh', 90, 3, 'وَوَالِدࣲ وَمَا وَلَدَ', 'ووالد وما ولد', NULL, 594, 'local:warsh-text.json'),
  ('warsh-90-4', 'warsh', 90, 4, 'لَقَدْ خَلَقْنَا ࡰ۬لِانسَٰنَ فِے كَبَدٍ࣌', 'لقد خلقنا ࡰلانسن فے كبد࣌', NULL, 594, 'local:warsh-text.json'),
  ('warsh-90-5', 'warsh', 90, 5, 'ࡰيَحْسِبُ أَن لَّنْ يَّقْدِرَ عَلَيْهِ أَحَدࣱ', 'ࡰيحسب أن لن يقدر عليه أحد', NULL, 594, 'local:warsh-text.json'),
  ('warsh-90-6', 'warsh', 90, 6, 'يَقُولُ أَهْلَكْتُ مَالاࣰ لُّبَداً࣌', 'يقول أهلكت مالا لبدا࣌', NULL, 594, 'local:warsh-text.json'),
  ('warsh-90-7', 'warsh', 90, 7, 'ࡰيَحْسِبُ أَن لَّمْ يَرَهُۥٓ أَحَدٌ࣌', 'ࡰيحسب أن لم يره أحد࣌', NULL, 594, 'local:warsh-text.json'),
  ('warsh-90-8', 'warsh', 90, 8, 'ࡰلَمْ نَجْعَل لَّهُۥ عَيْنَيْنِ', 'ࡰلم نجعل له عينين', NULL, 594, 'local:warsh-text.json'),
  ('warsh-90-9', 'warsh', 90, 9, 'وَلِسَاناࣰ وَشَفَتَيْنِ', 'ولسانا وشفتين', NULL, 594, 'local:warsh-text.json'),
  ('warsh-90-10', 'warsh', 90, 10, 'وَهَدَيْنَٰهُ ࡲ۬لنَّجْدَيْنِ࣌', 'وهدينه ࡲلنجدين࣌', NULL, 594, 'local:warsh-text.json'),
  ('warsh-90-11', 'warsh', 90, 11, 'فَلَا ࡰٜقْتَحَمَ ࡰ۬لْعَقَبَةَ࣌', 'فلا ࡰقتحم ࡰلعقبة࣌', NULL, 594, 'local:warsh-text.json'),
  ('warsh-90-12', 'warsh', 90, 12, 'وَمَآ أَدْرٜيٰكَ مَا ࡰ۬لْعَقَبَةُ࣌', 'وما أدريك ما ࡰلعقبة࣌', NULL, 594, 'local:warsh-text.json'),
  ('warsh-90-13', 'warsh', 90, 13, 'فَكُّ رَقَبَةٍ', 'فك رقبة', NULL, 594, 'local:warsh-text.json'),
  ('warsh-90-14', 'warsh', 90, 14, 'ࡰوِ ࡴطْعَامࣱ فِے يَوْمࣲ ذِے مَسْغَبَةࣲ', 'ࡰو ࡴطعام فے يوم ذے مسغبة', NULL, 594, 'local:warsh-text.json'),
  ('warsh-90-15', 'warsh', 90, 15, 'يَتِيماࣰ ذَا مَقْرَبَةٍ', 'يتيما ذا مقربة', NULL, 594, 'local:warsh-text.json'),
  ('warsh-90-16', 'warsh', 90, 16, 'ࡰوْ مِسْكِيناࣰ ذَا مَتْرَبَةࣲ࣌', 'ࡰو مسكينا ذا متربة࣌', NULL, 594, 'local:warsh-text.json'),
  ('warsh-90-17', 'warsh', 90, 17, 'ثُمَّ كَانَ مِنَ ࡰ۬لذِينَ ءَامَنُواْ وَتَوَاصَوْاْ بِالصَّبْرِ وَتَوَاصَوْاْ بِالْمَرْحَمَةِ࣌', 'ثم كان من ࡰلذين ءامنوا وتواصوا بالصبر وتواصوا بالمرحمة࣌', NULL, 594, 'local:warsh-text.json'),
  ('warsh-90-18', 'warsh', 90, 18, 'أُوْلَٰٓئِكَ أَصْحَٰبُ ࡲ۬لْمَيْمَنَةِ࣌', 'أولئك أصحب ࡲلميمنة࣌', NULL, 594, 'local:warsh-text.json'),
  ('warsh-90-19', 'warsh', 90, 19, 'وَالذِينَ كَفَرُواْ بِـَٔايَٰتِنَا هُمُۥٓ أَصْحَٰبُ ࡲ۬لْمَشْـَٔمَةِ࣌', 'والذين كفروا بايتنا هم أصحب ࡲلمشمة࣌', NULL, 595, 'local:warsh-text.json'),
  ('warsh-90-20', 'warsh', 90, 20, 'عَلَيْهِمْ نَارࣱ مُّوصَدَةࣱ࣌', 'عليهم نار موصدة࣌', NULL, 595, 'local:warsh-text.json'),
  ('warsh-91-1', 'warsh', 91, 1, 'وَالشَّمْسِ وَضُحَيٰهَا', 'والشمس وضحيها', NULL, 595, 'local:warsh-text.json'),
  ('warsh-91-2', 'warsh', 91, 2, 'وَالْقَمَرِ إِذَا تَلَيٰهَا', 'والقمر إذا تليها', NULL, 595, 'local:warsh-text.json'),
  ('warsh-91-3', 'warsh', 91, 3, 'وَالنَّهٜارِ إِذَا جَلَّيٰهَا', 'والنهار إذا جليها', NULL, 595, 'local:warsh-text.json'),
  ('warsh-91-4', 'warsh', 91, 4, 'وَاليْلِ إِذَا يَغْشَيٰهَا', 'واليل إذا يغشيها', NULL, 595, 'local:warsh-text.json'),
  ('warsh-91-5', 'warsh', 91, 5, 'وَالسَّمَآءِ وَمَا بَنَيٰهَا', 'والسماء وما بنيها', NULL, 595, 'local:warsh-text.json'),
  ('warsh-91-6', 'warsh', 91, 6, 'وَالَارْضِ وَمَا طَحَيٰهَا', 'والارض وما طحيها', NULL, 595, 'local:warsh-text.json'),
  ('warsh-91-7', 'warsh', 91, 7, 'وَنَفْسࣲ وَمَا سَوَّيٰهَا', 'ونفس وما سويها', NULL, 595, 'local:warsh-text.json'),
  ('warsh-91-8', 'warsh', 91, 8, 'فَأَلْهَمَهَا فُجُورَهَا وَتَقْوَيٰهَا', 'فألهمها فجورها وتقويها', NULL, 595, 'local:warsh-text.json'),
  ('warsh-91-9', 'warsh', 91, 9, 'قَدَ ࡰفْلَحَ مَن زَكَّيٰهَا', 'قد ࡰفلح من زكيها', NULL, 595, 'local:warsh-text.json'),
  ('warsh-91-10', 'warsh', 91, 10, 'وَقَدْ خَابَ مَن دَسَّيٰهَا࣌', 'وقد خاب من دسيها࣌', NULL, 595, 'local:warsh-text.json'),
  ('warsh-91-11', 'warsh', 91, 11, 'كَذَّبَتْ ثَمُودُ بِطَغْوَيٰهَآ', 'كذبت ثمود بطغويها', NULL, 595, 'local:warsh-text.json'),
  ('warsh-91-12', 'warsh', 91, 12, 'إِذِ ࡴٜنۢبَعَثَ أَشْقَيٰهَا', 'إذ ࡴنبعث أشقيها', NULL, 595, 'local:warsh-text.json'),
  ('warsh-91-13', 'warsh', 91, 13, 'فَقَالَ لَهُمْ رَسُولُ ࡲ۬للَّهِ نَاقَةَ ࡰ۬للَّهِ وَسُقْيَاهَا', 'فقال لهم رسول ࡲلله ناقة ࡰلله وسقياها', NULL, 595, 'local:warsh-text.json'),
  ('warsh-91-14', 'warsh', 91, 14, 'فَكَذَّبُوهُ فَعَقَرُوهَا فَدَمْدَمَ عَلَيْهِمْ رَبُّهُم بِذَنۢبِهِمْ فَسَوَّيٰهَا࣌', 'فكذبوه فعقروها فدمدم عليهم ربهم بذنبهم فسويها࣌', NULL, 595, 'local:warsh-text.json'),
  ('warsh-91-15', 'warsh', 91, 15, 'فَلَا يَخَافُ عُقْبَٰهَا࣌', 'فلا يخاف عقبها࣌', NULL, 595, 'local:warsh-text.json'),
  ('warsh-92-1', 'warsh', 92, 1, 'وَاليْلِ إِذَا يَغْشٜىٰ', 'واليل إذا يغشى', NULL, 595, 'local:warsh-text.json'),
  ('warsh-92-2', 'warsh', 92, 2, 'وَالنَّهٜارِ إِذَا تَجَلّٜىٰ', 'والنهار إذا تجلى', NULL, 595, 'local:warsh-text.json'),
  ('warsh-92-3', 'warsh', 92, 3, 'وَمَا خَلَقَ ࡰ۬لذَّكَرَ وَالُانثٜىٰٓ', 'وما خلق ࡰلذكر والانثى', NULL, 595, 'local:warsh-text.json'),
  ('warsh-92-4', 'warsh', 92, 4, 'إِنَّ سَعْيَكُمْ لَشَتّٜىٰ࣌', 'إن سعيكم لشتى࣌', NULL, 595, 'local:warsh-text.json'),
  ('warsh-92-5', 'warsh', 92, 5, 'فَأَمَّا مَنَ ࡰعْطٜىٰ وَاتَّقٜىٰ', 'فأما من ࡰعطى واتقى', NULL, 595, 'local:warsh-text.json'),
  ('warsh-92-6', 'warsh', 92, 6, 'وَصَدَّقَ بِالْحُسْنٜىٰ', 'وصدق بالحسنى', NULL, 595, 'local:warsh-text.json'),
  ('warsh-92-7', 'warsh', 92, 7, 'فَسَنُيَسِّرُهُۥ لِلْيُسْرٜىٰ࣌', 'فسنيسره لليسرى࣌', NULL, 595, 'local:warsh-text.json'),
  ('warsh-92-8', 'warsh', 92, 8, 'وَأَمَّا مَنۢ بَخِلَ وَاسْتَغْنٜىٰ', 'وأما من بخل واستغنى', NULL, 595, 'local:warsh-text.json'),
  ('warsh-92-9', 'warsh', 92, 9, 'وَكَذَّبَ بِالْحُسْنٜىٰ', 'وكذب بالحسنى', NULL, 595, 'local:warsh-text.json'),
  ('warsh-92-10', 'warsh', 92, 10, 'فَسَنُيَسِّرُهُۥ لِلْعُسْرٜىٰ࣌', 'فسنيسره للعسرى࣌', NULL, 596, 'local:warsh-text.json'),
  ('warsh-92-11', 'warsh', 92, 11, 'وَمَا يُغْنِے عَنْهُ مَالُهُۥٓ إِذَا تَرَدّٜىٰٓ࣌', 'وما يغنے عنه ماله إذا تردى࣌', NULL, 596, 'local:warsh-text.json'),
  ('warsh-92-12', 'warsh', 92, 12, 'إِنَّ عَلَيْنَا لَلْهُدٜىٰ', 'إن علينا للهدى', NULL, 596, 'local:warsh-text.json'),
  ('warsh-92-13', 'warsh', 92, 13, 'وَإِنَّ لَنَا لَلَاخِرَةَ وَالُاولٜىٰ࣌', 'وإن لنا للاخرة والاولى࣌', NULL, 596, 'local:warsh-text.json'),
  ('warsh-92-14', 'warsh', 92, 14, 'فَأَنذَرْتُكُمْ نَاراࣰ تَلَظّٜىٰ', 'فأنذرتكم نارا تلظى', NULL, 596, 'local:warsh-text.json'),
  ('warsh-92-15', 'warsh', 92, 15, 'لَا يَصْلَيٰهَآ إِلَّا ࡰ۬لَاشْقَي', 'لا يصليها إلا ࡰلاشقي', NULL, 596, 'local:warsh-text.json'),
  ('warsh-92-16', 'warsh', 92, 16, 'ࡰ۬لذِے كَذَّبَ وَتَوَلّٜىٰ࣌', 'ࡰلذے كذب وتولى࣌', NULL, 596, 'local:warsh-text.json'),
  ('warsh-92-17', 'warsh', 92, 17, 'وَسَيُجَنَّبُهَا ࡰ۬لَاتْقَي', 'وسيجنبها ࡰلاتقي', NULL, 596, 'local:warsh-text.json'),
  ('warsh-92-18', 'warsh', 92, 18, 'ࡰ۬لذِے يُوتِے مَالَهُۥ يَتَزَكّٜىٰ࣌', 'ࡰلذے يوتے ماله يتزكى࣌', NULL, 596, 'local:warsh-text.json'),
  ('warsh-92-19', 'warsh', 92, 19, 'وَمَا لِأَحَدٍ عِندَهُۥ مِن نِّعْمَةࣲ تُجْزٜىٰٓ', 'وما لأحد عنده من نعمة تجزى', NULL, 596, 'local:warsh-text.json'),
  ('warsh-92-20', 'warsh', 92, 20, 'إِلَّا ࡰٜبْتِغَآءَ وَجْهِ رَبِّهِ ࡴ۬لَاعْلٜىٰ࣌', 'إلا ࡰبتغاء وجه ربه ࡴلاعلى࣌', NULL, 596, 'local:warsh-text.json'),
  ('warsh-92-21', 'warsh', 92, 21, 'وَلَسَوْفَ يَرْضٜىٰ࣌', 'ولسوف يرضى࣌', NULL, 596, 'local:warsh-text.json'),
  ('warsh-93-1', 'warsh', 93, 1, 'وَالضُّحٜىٰ', 'والضحى', NULL, 596, 'local:warsh-text.json'),
  ('warsh-93-2', 'warsh', 93, 2, 'وَاليْلِ إِذَا سَجٜىٰ', 'واليل إذا سجى', NULL, 596, 'local:warsh-text.json'),
  ('warsh-93-3', 'warsh', 93, 3, 'مَا وَدَّعَكَ رَبُّكَ وَمَا قَلٜىٰ࣌', 'ما ودعك ربك وما قلى࣌', NULL, 596, 'local:warsh-text.json'),
  ('warsh-93-4', 'warsh', 93, 4, 'وَلَلَاخِرَةُ خَيْرࣱ لَّكَ مِنَ ࡰ۬لُاولٜىٰ࣌', 'وللاخرة خير لك من ࡰلاولى࣌', NULL, 596, 'local:warsh-text.json'),
  ('warsh-93-5', 'warsh', 93, 5, 'وَلَسَوْفَ يُعْطِيكَ رَبُّكَ فَتَرْضٜىٰٓ࣌', 'ولسوف يعطيك ربك فترضى࣌', NULL, 596, 'local:warsh-text.json'),
  ('warsh-93-6', 'warsh', 93, 6, 'أَلَمْ يَجِدْكَ يَتِيماࣰ فَـَٔاوٜىٰ', 'ألم يجدك يتيما فاوى', NULL, 596, 'local:warsh-text.json'),
  ('warsh-93-7', 'warsh', 93, 7, 'وَوَجَدَكَ ضَآلّاࣰ فَهَدٜىٰ', 'ووجدك ضالا فهدى', NULL, 596, 'local:warsh-text.json'),
  ('warsh-93-8', 'warsh', 93, 8, 'وَوَجَدَكَ عَآئِلاࣰ فَأَغْنٜىٰ࣌', 'ووجدك عائلا فأغنى࣌', NULL, 596, 'local:warsh-text.json'),
  ('warsh-93-9', 'warsh', 93, 9, 'فَأَمَّا ࡰ۬لْيَتِيمَ فَلَا تَقْهَرْ࣌', 'فأما ࡰليتيم فلا تقهر࣌', NULL, 596, 'local:warsh-text.json'),
  ('warsh-93-10', 'warsh', 93, 10, 'وَأَمَّا ࡰ۬لسَّآئِلَ فَلَا تَنْهَرْ࣌', 'وأما ࡰلسائل فلا تنهر࣌', NULL, 596, 'local:warsh-text.json'),
  ('warsh-93-11', 'warsh', 93, 11, 'وَأَمَّا بِنِعْمَةِ رَبِّكَ فَحَدِّثَ࣌', 'وأما بنعمة ربك فحدث࣌', NULL, 596, 'local:warsh-text.json'),
  ('warsh-94-1', 'warsh', 94, 1, 'ࡰلَمْ نَشْرَحْ لَكَ صَدْرَكَ', 'ࡰلم نشرح لك صدرك', NULL, 596, 'local:warsh-text.json'),
  ('warsh-94-2', 'warsh', 94, 2, 'وَوَضَعْنَا عَنكَ وِزْرَكَ', 'ووضعنا عنك وزرك', NULL, 596, 'local:warsh-text.json'),
  ('warsh-94-3', 'warsh', 94, 3, 'ࡰ۬لذِےٓ أَنقَضَ ظَهْرَكَ', 'ࡰلذے أنقض ظهرك', NULL, 597, 'local:warsh-text.json'),
  ('warsh-94-4', 'warsh', 94, 4, 'وَرَفَعْنَا لَكَ ذِكْرَكَ࣌', 'ورفعنا لك ذكرك࣌', NULL, 597, 'local:warsh-text.json'),
  ('warsh-94-5', 'warsh', 94, 5, 'فَإِنَّ مَعَ ࡰ۬لْعُسْرِ يُسْراً', 'فإن مع ࡰلعسر يسرا', NULL, 597, 'local:warsh-text.json'),
  ('warsh-94-6', 'warsh', 94, 6, 'ࡴنَّ مَعَ ࡰ۬لْعُسْرِ يُسْراࣰ࣌', 'ࡴن مع ࡰلعسر يسرا࣌', NULL, 597, 'local:warsh-text.json'),
  ('warsh-94-7', 'warsh', 94, 7, 'فَإِذَا فَرَغْتَ فَانصَبْ', 'فإذا فرغت فانصب', NULL, 597, 'local:warsh-text.json'),
  ('warsh-94-8', 'warsh', 94, 8, 'وَإِلَىٰ رَبِّكَ فَارْغَبْ࣌', 'وإلى ربك فارغب࣌', NULL, 597, 'local:warsh-text.json'),
  ('warsh-95-1', 'warsh', 95, 1, 'وَالتِّينِ وَالزَّيْتُونِ', 'والتين والزيتون', NULL, 597, 'local:warsh-text.json'),
  ('warsh-95-2', 'warsh', 95, 2, 'وَطُورِ سِينِينَ', 'وطور سينين', NULL, 597, 'local:warsh-text.json'),
  ('warsh-95-3', 'warsh', 95, 3, 'وَهَٰذَا ࡰ۬لْبَلَدِ ࡴ۬لَامِينِ', 'وهذا ࡰلبلد ࡴلامين', NULL, 597, 'local:warsh-text.json'),
  ('warsh-95-4', 'warsh', 95, 4, 'لَقَدْ خَلَقْنَا ࡰ۬لِانسَٰنَ فِےٓ أَحْسَنِ تَقْوِيمࣲ', 'لقد خلقنا ࡰلانسن فے أحسن تقويم', NULL, 597, 'local:warsh-text.json'),
  ('warsh-95-5', 'warsh', 95, 5, 'ثُمَّ رَدَدْنَٰهُ أَسْفَلَ سَٰفِلِينَ', 'ثم رددنه أسفل سفلين', NULL, 597, 'local:warsh-text.json'),
  ('warsh-95-6', 'warsh', 95, 6, 'إِلَّا ࡰ۬لذِينَ ءَامَنُواْ وَعَمِلُواْ ࡲ۬لصَّٰلِحَٰتِ فَلَهُمُۥٓ أَجْرٌ غَيْرُ مَمْنُونࣲ࣌', 'إلا ࡰلذين ءامنوا وعملوا ࡲلصلحت فلهم أجر غير ممنون࣌', NULL, 597, 'local:warsh-text.json'),
  ('warsh-95-7', 'warsh', 95, 7, 'فَمَا يُكَذِّبُكَ بَعْدُ بِالدِّينِ࣌', 'فما يكذبك بعد بالدين࣌', NULL, 597, 'local:warsh-text.json'),
  ('warsh-95-8', 'warsh', 95, 8, 'أَلَيْسَ ࡰ۬للَّهُ بِأَحْكَمِ ࡴ۬لْحَٰكِمِينَ࣌', 'أليس ࡰلله بأحكم ࡴلحكمين࣌', NULL, 597, 'local:warsh-text.json'),
  ('warsh-96-1', 'warsh', 96, 1, 'ࡰٜقْرَأْ بِاسْمِ رَبِّكَ ࡰ۬لذِے خَلَقَ࣌', 'ࡰقرأ باسم ربك ࡰلذے خلق࣌', NULL, 597, 'local:warsh-text.json'),
  ('warsh-96-2', 'warsh', 96, 2, 'خَلَقَ ࡰ۬لِانسَٰنَ مِنْ عَلَقٍ࣌', 'خلق ࡰلانسن من علق࣌', NULL, 597, 'local:warsh-text.json'),
  ('warsh-96-3', 'warsh', 96, 3, 'ࡴٜقْرَأْ وَرَبُّكَ ࡰ۬لَاكْرَمُ', 'ࡴقرأ وربك ࡰلاكرم', NULL, 597, 'local:warsh-text.json'),
  ('warsh-96-4', 'warsh', 96, 4, 'ࡲ۬لذِے عَلَّمَ بِالْقَلَمِ', 'ࡲلذے علم بالقلم', NULL, 597, 'local:warsh-text.json'),
  ('warsh-96-5', 'warsh', 96, 5, 'عَلَّمَ ࡰ۬لِانسَٰنَ مَا لَمْ يَعْلَمْ࣌', 'علم ࡰلانسن ما لم يعلم࣌', NULL, 597, 'local:warsh-text.json'),
  ('warsh-96-6', 'warsh', 96, 6, 'كَلَّآ إِنَّ ࡰ۬لِانسَٰنَ لَيَطْغٜىٰٓ', 'كلا إن ࡰلانسن ليطغى', NULL, 597, 'local:warsh-text.json'),
  ('warsh-96-7', 'warsh', 96, 7, 'أَن رّٜءٜاهُ ࡲٜسْتَغْنٜىٰٓ࣌', 'أن رءاه ࡲستغنى࣌', NULL, 597, 'local:warsh-text.json'),
  ('warsh-96-8', 'warsh', 96, 8, 'إِنَّ إِلَىٰ رَبِّكَ ࡰ۬لرُّجْعٜىٰٓ࣌', 'إن إلى ربك ࡰلرجعى࣌', NULL, 597, 'local:warsh-text.json'),
  ('warsh-96-9', 'warsh', 96, 9, 'أَرَٰٓيْتَ ࡰ۬لذِے يَنْهٜىٰ', 'أريت ࡰلذے ينهى', NULL, 597, 'local:warsh-text.json'),
  ('warsh-96-10', 'warsh', 96, 10, 'عَبْداً ࡴذَا صَلّٜىٰٓ࣌', 'عبدا ࡴذا صلى࣌', NULL, 597, 'local:warsh-text.json'),
  ('warsh-96-11', 'warsh', 96, 11, 'أَرَٰٓيْتَ إِن كَانَ عَلَى ࡰ۬لْهُدٜىٰٓ', 'أريت إن كان على ࡰلهدى', NULL, 597, 'local:warsh-text.json'),
  ('warsh-96-12', 'warsh', 96, 12, 'أَوَ ࡰمَرَ بِالتَّقْوٜىٰٓ࣌', 'أو ࡰمر بالتقوى࣌', NULL, 597, 'local:warsh-text.json'),
  ('warsh-96-13', 'warsh', 96, 13, 'أَرَٰٓيْتَ إِن كَذَّبَ وَتَوَلّٜىٰٓ', 'أريت إن كذب وتولى', NULL, 598, 'local:warsh-text.json'),
  ('warsh-96-14', 'warsh', 96, 14, 'أَلَمْ يَعْلَم بِأَنَّ ࡰ۬للَّهَ يَرٜىٰ࣌', 'ألم يعلم بأن ࡰلله يرى࣌', NULL, 598, 'local:warsh-text.json'),
  ('warsh-96-15', 'warsh', 96, 15, 'كَلَّا لَئِن لَّمْ يَنتَهِ', 'كلا لئن لم ينته', NULL, 598, 'local:warsh-text.json'),
  ('warsh-96-16', 'warsh', 96, 16, 'لَنَسْفَعاَۢ بِالنَّاصِيَةِ', 'لنسفعا بالناصية', NULL, 598, 'local:warsh-text.json'),
  ('warsh-96-17', 'warsh', 96, 17, 'نَاصِيَةࣲ كَٰذِبَةٍ خَاطِئَةࣲ࣌', 'ناصية كذبة خاطئة࣌', NULL, 598, 'local:warsh-text.json'),
  ('warsh-96-18', 'warsh', 96, 18, 'فَلْيَدْعُ نَادِيَهُۥ', 'فليدع ناديه', NULL, 598, 'local:warsh-text.json'),
  ('warsh-96-19', 'warsh', 96, 19, 'سَنَدْعُ ࡲ۬لزَّبَانِيَةَ࣌', 'سندع ࡲلزبانية࣌', NULL, 598, 'local:warsh-text.json'),
  ('warsh-96-20', 'warsh', 96, 20, 'كَلَّا لَا تُطِعْهُ وَاسْجُدْ وَاقْتَرِبِ࣌۩', 'كلا لا تطعه واسجد واقترب࣌', NULL, 598, 'local:warsh-text.json'),
  ('warsh-97-1', 'warsh', 97, 1, 'ࡴنَّآ أَنزَلْنَٰهُ فِے لَيْلَةِ ࡴ۬لْقَدْرِ࣌', 'ࡴنا أنزلنه فے ليلة ࡴلقدر࣌', NULL, 598, 'local:warsh-text.json'),
  ('warsh-97-2', 'warsh', 97, 2, 'وَمَآ أَدْرٜيٰكَ مَا لَيْلَةُ ࡲ۬لْقَدْرِ࣌', 'وما أدريك ما ليلة ࡲلقدر࣌', NULL, 598, 'local:warsh-text.json'),
  ('warsh-97-3', 'warsh', 97, 3, 'لَيْلَةُ ࡲ۬لْقَدْرِ خَيْرࣱ مِّنَ ࡰلْفِ شَهْرࣲ࣌', 'ليلة ࡲلقدر خير من ࡰلف شهر࣌', NULL, 598, 'local:warsh-text.json'),
  ('warsh-97-4', 'warsh', 97, 4, 'تَنَزَّلُ ࡲ۬لْمَلَٰٓئِكَةُ وَالرُّوحُ فِيهَا بِإِذْنِ رَبِّهِم مِّن كُلِّ أَمْرࣲ࣌', 'تنزل ࡲلملئكة والروح فيها بإذن ربهم من كل أمر࣌', NULL, 598, 'local:warsh-text.json'),
  ('warsh-97-5', 'warsh', 97, 5, 'سَلَٰمٌ هِيَ حَتَّىٰ مَطْلَعِ ࡴ۬لْفَجْرِ࣌', 'سلم هي حتى مطلع ࡴلفجر࣌', NULL, 598, 'local:warsh-text.json'),
  ('warsh-98-1', 'warsh', 98, 1, 'لَمْ يَكُنِ ࡴ۬لذِينَ كَفَرُواْ مِنَ ࡰهْلِ ࡴ۬لْكِتَٰبِ وَالْمُشْرِكِينَ مُنفَكِّينَ حَتَّىٰ تَاتِيَهُمُ ࡲ۬لْبَيِّنَةُ࣌', 'لم يكن ࡴلذين كفروا من ࡰهل ࡴلكتب والمشركين منفكين حتى تاتيهم ࡲلبينة࣌', NULL, 598, 'local:warsh-text.json'),
  ('warsh-98-2', 'warsh', 98, 2, 'رَسُولࣱ مِّنَ ࡰ۬للَّهِ يَتْلُواْ صُحُفاࣰ مُّطَهَّرَةࣰ', 'رسول من ࡰلله يتلوا صحفا مطهرة', NULL, 598, 'local:warsh-text.json'),
  ('warsh-98-3', 'warsh', 98, 3, 'فِيهَا كُتُبࣱ قَيِّمَةࣱ࣌', 'فيها كتب قيمة࣌', NULL, 598, 'local:warsh-text.json'),
  ('warsh-98-4', 'warsh', 98, 4, 'وَمَا تَفَرَّقَ ࡰ۬لذِينَ أُوتُواْ ࡲ۬لْكِتَٰبَ إِلَّا مِنۢ بَعْدِ مَا جَآءَتْهُمُ ࡲ۬لْبَيِّنَةُ࣌', 'وما تفرق ࡰلذين أوتوا ࡲلكتب إلا من بعد ما جاءتهم ࡲلبينة࣌', NULL, 598, 'local:warsh-text.json'),
  ('warsh-98-5', 'warsh', 98, 5, 'وَمَآ أُمِرُوٓاْ إِلَّا لِيَعْبُدُواْ ࡲ۬للَّهَ مُخْلِصِينَ لَهُ ࡲ۬لدِّينَ حُنَفَآءَ وَيُقِيمُواْ ࡲ۬لصَّلَوٰةَ وَيُوتُواْ ࡲ۬لزَّكَوٰةَ࣌ وَذَٰلِكَ دِينُ ࡲ۬لْقَيِّمَةِ࣌', 'وما أمروا إلا ليعبدوا ࡲلله مخلصين له ࡲلدين حنفاء ويقيموا ࡲلصلوة ويوتوا ࡲلزكوة࣌ وذلك دين ࡲلقيمة࣌', NULL, 598, 'local:warsh-text.json'),
  ('warsh-98-6', 'warsh', 98, 6, 'إِنَّ ࡰ۬لذِينَ كَفَرُواْ مِنَ ࡰهْلِ ࡴ۬لْكِتَٰبِ وَالْمُشْرِكِينَ فِے نٜارِ جَهَنَّمَ خَٰلِدِينَ فِيهَآ࣌ أُوْلَٰٓئِكَ هُمْ شَرُّ ࡲ۬لْبَرِيٓـَٔةِ࣌', 'إن ࡰلذين كفروا من ࡰهل ࡴلكتب والمشركين فے نار جهنم خلدين فيها࣌ أولئك هم شر ࡲلبرية࣌', NULL, 599, 'local:warsh-text.json'),
  ('warsh-98-7', 'warsh', 98, 7, 'إِنَّ ࡰ۬لذِينَ ءَامَنُواْ وَعَمِلُواْ ࡲ۬لصَّٰلِحَٰتِ أُوْلَٰٓئِكَ هُمْ خَيْرُ ࡲ۬لْبَرِيٓـَٔةِ࣌', 'إن ࡰلذين ءامنوا وعملوا ࡲلصلحت أولئك هم خير ࡲلبرية࣌', NULL, 599, 'local:warsh-text.json'),
  ('warsh-98-8', 'warsh', 98, 8, 'جَزَآؤُهُمْ عِندَ رَبِّهِمْ جَنَّٰتُ عَدْنࣲ تَجْرِے مِن تَحْتِهَا ࡰ۬لَانْهَٰرُ خَٰلِدِينَ فِيهَآ أَبَداࣰ࣌ رَّضِيَ ࡰ۬للَّهُ عَنْهُمْ وَرَضُواْ عَنْهُ࣌ ذَٰلِكَ لِمَنْ خَشِيَ رَبَّهُۥٓ࣌', 'جزاؤهم عند ربهم جنت عدن تجرے من تحتها ࡰلانهر خلدين فيها أبدا࣌ رضي ࡰلله عنهم ورضوا عنه࣌ ذلك لمن خشي ربه࣌', NULL, 599, 'local:warsh-text.json'),
  ('warsh-99-1', 'warsh', 99, 1, 'إِذَا زُلْزِلَتِ ࡴ۬لَارْضُ زِلْزَالَهَا', 'إذا زلزلت ࡴلارض زلزالها', NULL, 599, 'local:warsh-text.json'),
  ('warsh-99-2', 'warsh', 99, 2, 'وَأَخْرَجَتِ ࡴ۬لَارْضُ أَثْقَالَهَا', 'وأخرجت ࡴلارض أثقالها', NULL, 599, 'local:warsh-text.json'),
  ('warsh-99-3', 'warsh', 99, 3, 'وَقَالَ ࡰ۬لِانسَٰنُ مَا لَهَا', 'وقال ࡰلانسن ما لها', NULL, 599, 'local:warsh-text.json'),
  ('warsh-99-4', 'warsh', 99, 4, 'يَوْمَئِذࣲ تُحَدِّثُ أَخْبَارَهَا', 'يومئذ تحدث أخبارها', NULL, 599, 'local:warsh-text.json'),
  ('warsh-99-5', 'warsh', 99, 5, 'بِأَنَّ رَبَّكَ أَوْحٜىٰ لَهَا࣌', 'بأن ربك أوحى لها࣌', NULL, 599, 'local:warsh-text.json'),
  ('warsh-99-6', 'warsh', 99, 6, 'يَوْمَئِذࣲ يَصْدُرُ ࡲ۬لنَّاسُ أَشْتَاتاࣰ', 'يومئذ يصدر ࡲلناس أشتاتا', NULL, 599, 'local:warsh-text.json'),
  ('warsh-99-7', 'warsh', 99, 7, 'لِّيُرَوَاْ ࡰعْمَٰلَهُمْ࣌', 'ليروا ࡰعملهم࣌', NULL, 599, 'local:warsh-text.json'),
  ('warsh-99-8', 'warsh', 99, 8, 'فَمَنْ يَّعْمَلْ مِثْقَالَ ذَرَّةٍ خَيْراࣰ يَرَهُۥ࣌', 'فمن يعمل مثقال ذرة خيرا يره࣌', NULL, 599, 'local:warsh-text.json'),
  ('warsh-99-9', 'warsh', 99, 9, 'وَمَنْ يَّعْمَلْ مِثْقَالَ ذَرَّةࣲ شَرّاࣰ يَرَهُۥ࣌', 'ومن يعمل مثقال ذرة شرا يره࣌', NULL, 599, 'local:warsh-text.json'),
  ('warsh-100-1', 'warsh', 100, 1, 'وَالْعَٰدِيَٰتِ ضَبْحاࣰ', 'والعديت ضبحا', NULL, 599, 'local:warsh-text.json'),
  ('warsh-100-2', 'warsh', 100, 2, 'فَالْمُورِيَٰتِ قَدْحاࣰ', 'فالموريت قدحا', NULL, 599, 'local:warsh-text.json'),
  ('warsh-100-3', 'warsh', 100, 3, 'فَالْمُغِيرَٰتِ صُبْحاࣰ', 'فالمغيرت صبحا', NULL, 599, 'local:warsh-text.json'),
  ('warsh-100-4', 'warsh', 100, 4, 'فَأَثَرْنَ بِهِۦ نَقْعاࣰ', 'فأثرن به نقعا', NULL, 599, 'local:warsh-text.json'),
  ('warsh-100-5', 'warsh', 100, 5, 'فَوَسَطْنَ بِهِۦ جَمْعاً', 'فوسطن به جمعا', NULL, 599, 'local:warsh-text.json'),
  ('warsh-100-6', 'warsh', 100, 6, 'ࡴنَّ ࡰ۬لِانسَٰنَ لِرَبِّهِۦ لَكَنُودࣱ', 'ࡴن ࡰلانسن لربه لكنود', NULL, 600, 'local:warsh-text.json'),
  ('warsh-100-7', 'warsh', 100, 7, 'وَإِنَّهُۥ عَلَىٰ ذَٰلِكَ لَشَهِيدࣱ', 'وإنه على ذلك لشهيد', NULL, 600, 'local:warsh-text.json'),
  ('warsh-100-8', 'warsh', 100, 8, 'وَإِنَّهُۥ لِحُبِّ ࡴ۬لْخَيْرِ لَشَدِيدٌ࣌', 'وإنه لحب ࡴلخير لشديد࣌', NULL, 600, 'local:warsh-text.json'),
  ('warsh-100-9', 'warsh', 100, 9, '۞ ࡰفَلَا يَعْلَمُ إِذَا بُعْثِرَ مَا فِے ࡴ۬لْقُبُورِ', 'ࡰفلا يعلم إذا بعثر ما فے ࡴلقبور', NULL, 600, 'local:warsh-text.json'),
  ('warsh-100-10', 'warsh', 100, 10, 'وَحُصِّلَ مَا فِے ࡴ۬لصُّدُورِ', 'وحصل ما فے ࡴلصدور', NULL, 600, 'local:warsh-text.json'),
  ('warsh-100-11', 'warsh', 100, 11, 'إِنَّ رَبَّهُم بِهِمْ يَوْمَئِذࣲ لَّخَبِيرٌ࣌', 'إن ربهم بهم يومئذ لخبير࣌', NULL, 600, 'local:warsh-text.json'),
  ('warsh-101-1', 'warsh', 101, 1, 'ࡴ۬لْقَارِعَةُ مَا ࡰ۬لْقَارِعَةُ࣌', 'ࡴلقارعة ما ࡰلقارعة࣌', NULL, 600, 'local:warsh-text.json'),
  ('warsh-101-2', 'warsh', 101, 2, 'وَمَآ أَدْرٜيٰكَ مَا ࡰ۬لْقَارِعَةُ࣌', 'وما أدريك ما ࡰلقارعة࣌', NULL, 600, 'local:warsh-text.json'),
  ('warsh-101-3', 'warsh', 101, 3, 'يَوْمَ يَكُونُ ࡲ۬لنَّاسُ كَالْفَرَاشِ ࡴ۬لْمَبْثُوثِ', 'يوم يكون ࡲلناس كالفراش ࡴلمبثوث', NULL, 600, 'local:warsh-text.json'),
  ('warsh-101-4', 'warsh', 101, 4, 'وَتَكُونُ ࡲ۬لْجِبَالُ كَالْعِهْنِ ࡴ۬لْمَنفُوشِ࣌', 'وتكون ࡲلجبال كالعهن ࡴلمنفوش࣌', NULL, 600, 'local:warsh-text.json'),
  ('warsh-101-5', 'warsh', 101, 5, 'فَأَمَّا مَن ثَقُلَتْ مَوَٰزِينُهُۥ', 'فأما من ثقلت موزينه', NULL, 600, 'local:warsh-text.json'),
  ('warsh-101-6', 'warsh', 101, 6, 'فَهُوَ فِے عِيشَةࣲ رَّاضِيَةࣲ࣌', 'فهو فے عيشة راضية࣌', NULL, 600, 'local:warsh-text.json'),
  ('warsh-101-7', 'warsh', 101, 7, 'وَأَمَّا مَنْ خَفَّتْ مَوَٰزِينُهُۥ', 'وأما من خفت موزينه', NULL, 600, 'local:warsh-text.json'),
  ('warsh-101-8', 'warsh', 101, 8, 'فَأُمُّهُۥ هَاوِيَةࣱ࣌', 'فأمه هاوية࣌', NULL, 600, 'local:warsh-text.json'),
  ('warsh-101-9', 'warsh', 101, 9, 'وَمَآ أَدْرٜيٰكَ مَا هِيَهْ࣌', 'وما أدريك ما هيه࣌', NULL, 600, 'local:warsh-text.json'),
  ('warsh-101-10', 'warsh', 101, 10, 'نَارٌ حَامِيَةٌ࣌', 'نار حامية࣌', NULL, 600, 'local:warsh-text.json'),
  ('warsh-102-1', 'warsh', 102, 1, 'ࡰلْهٜيٰكُمُ ࡲ۬لتَّكَاثُرُ', 'ࡰلهيكم ࡲلتكاثر', NULL, 600, 'local:warsh-text.json'),
  ('warsh-102-2', 'warsh', 102, 2, 'حَتَّىٰ زُرْتُمُ ࡲ۬لْمَقَابِرَ࣌', 'حتى زرتم ࡲلمقابر࣌', NULL, 600, 'local:warsh-text.json'),
  ('warsh-102-3', 'warsh', 102, 3, 'كَلَّا سَوْفَ تَعْلَمُونَ', 'كلا سوف تعلمون', NULL, 600, 'local:warsh-text.json'),
  ('warsh-102-4', 'warsh', 102, 4, 'ثُمَّ كَلَّا سَوْفَ تَعْلَمُونَ࣌', 'ثم كلا سوف تعلمون࣌', NULL, 600, 'local:warsh-text.json'),
  ('warsh-102-5', 'warsh', 102, 5, 'كَلَّا لَوْ تَعْلَمُونَ عِلْمَ ࡰ۬لْيَقِينِ࣌', 'كلا لو تعلمون علم ࡰليقين࣌', NULL, 600, 'local:warsh-text.json'),
  ('warsh-102-6', 'warsh', 102, 6, 'لَتَرَوُنَّ ࡰ۬لْجَحِيمَ', 'لترون ࡰلجحيم', NULL, 600, 'local:warsh-text.json'),
  ('warsh-102-7', 'warsh', 102, 7, 'ثُمَّ لَتَرَوُنَّهَا عَيْنَ ࡰ۬لْيَقِينِ', 'ثم لترونها عين ࡰليقين', NULL, 600, 'local:warsh-text.json'),
  ('warsh-102-8', 'warsh', 102, 8, 'ثُمَّ لَتُسْـَٔلُنَّ يَوْمَئِذٍ عَنِ ࡴ۬لنَّعِيمِ࣌', 'ثم لتسلن يومئذ عن ࡴلنعيم࣌', NULL, 600, 'local:warsh-text.json'),
  ('warsh-103-1', 'warsh', 103, 1, 'وَالْعَصْرِ إِنَّ ࡰ۬لِانسَٰنَ لَفِے خُسْرٍ', 'والعصر إن ࡰلانسن لفے خسر', NULL, 601, 'local:warsh-text.json'),
  ('warsh-103-2', 'warsh', 103, 2, 'ࡴلَّا ࡰ۬لذِينَ ءَامَنُواْ وَعَمِلُواْ ࡲ۬لصَّٰلِحَٰتِ وَتَوَاصَوْاْ بِالْحَقِّ', 'ࡴلا ࡰلذين ءامنوا وعملوا ࡲلصلحت وتواصوا بالحق', NULL, 601, 'local:warsh-text.json'),
  ('warsh-103-3', 'warsh', 103, 3, 'وَتَوَاصَوْاْ بِالصَّبْرِ࣌', 'وتواصوا بالصبر࣌', NULL, 601, 'local:warsh-text.json'),
  ('warsh-104-1', 'warsh', 104, 1, 'وَيْلࣱ لِّكُلِّ هُمَزَةࣲ لُّمَزَةٍ', 'ويل لكل همزة لمزة', NULL, 601, 'local:warsh-text.json'),
  ('warsh-104-2', 'warsh', 104, 2, 'ࡴ۬لذِے جَمَعَ مَالاࣰ وَعَدَّدَهُۥ', 'ࡴلذے جمع مالا وعدده', NULL, 601, 'local:warsh-text.json'),
  ('warsh-104-3', 'warsh', 104, 3, 'يَحْسِبُ أَنَّ مَالَهُۥٓ أَخْلَدَهُۥ', 'يحسب أن ماله أخلده', NULL, 601, 'local:warsh-text.json'),
  ('warsh-104-4', 'warsh', 104, 4, 'كَلَّا࣌ لَيُنۢبَذَنَّ فِے ࡴ۬لْحُطَمَةِ࣌', 'كلا࣌ لينبذن فے ࡴلحطمة࣌', NULL, 601, 'local:warsh-text.json'),
  ('warsh-104-5', 'warsh', 104, 5, 'وَمَآ أَدْرٜيٰكَ مَا ࡰ۬لْحُطَمَةُ࣌', 'وما أدريك ما ࡰلحطمة࣌', NULL, 601, 'local:warsh-text.json'),
  ('warsh-104-6', 'warsh', 104, 6, 'نَارُ ࡲ۬للَّهِ ࡴ۬لْمُوقَدَةُ', 'نار ࡲلله ࡴلموقدة', NULL, 601, 'local:warsh-text.json'),
  ('warsh-104-7', 'warsh', 104, 7, 'ࡲ۬لتِے تَطَّلِعُ عَلَى ࡰ۬لَافْـِٕدَةِ࣌', 'ࡲلتے تطلع على ࡰلافدة࣌', NULL, 601, 'local:warsh-text.json'),
  ('warsh-104-8', 'warsh', 104, 8, 'إِنَّهَا عَلَيْهِم مُّوصَدَةࣱ', 'إنها عليهم موصدة', NULL, 601, 'local:warsh-text.json'),
  ('warsh-104-9', 'warsh', 104, 9, 'فِے عَمَدࣲ مُّمَدَّدَةٍ࣌', 'فے عمد ممددة࣌', NULL, 601, 'local:warsh-text.json'),
  ('warsh-105-1', 'warsh', 105, 1, 'ࡰلَمْ تَرَ كَيْفَ فَعَلَ رَبُّكَ بِأَصْحَٰبِ ࡴ۬لْفِيلِ࣌', 'ࡰلم تر كيف فعل ربك بأصحب ࡴلفيل࣌', NULL, 601, 'local:warsh-text.json'),
  ('warsh-105-2', 'warsh', 105, 2, 'أَلَمْ يَجْعَلْ كَيْدَهُمْ فِے تَضْلِيلࣲ', 'ألم يجعل كيدهم فے تضليل', NULL, 601, 'local:warsh-text.json'),
  ('warsh-105-3', 'warsh', 105, 3, 'وَأَرْسَلَ عَلَيْهِمْ طَيْراً ࡰبَابِيلَ', 'وأرسل عليهم طيرا ࡰبابيل', NULL, 601, 'local:warsh-text.json'),
  ('warsh-105-4', 'warsh', 105, 4, 'تَرْمِيهِم بِحِجَارَةࣲ مِّن سِجِّيلࣲ', 'ترميهم بحجارة من سجيل', NULL, 601, 'local:warsh-text.json'),
  ('warsh-105-5', 'warsh', 105, 5, 'فَجَعَلَهُمْ كَعَصْفࣲ مَّاكُولࣲ࣌', 'فجعلهم كعصف ماكول࣌', NULL, 601, 'local:warsh-text.json'),
  ('warsh-106-1', 'warsh', 106, 1, 'لِّإِيلَٰفِ قُرَيْشٍ', 'لإيلف قريش', NULL, 602, 'local:warsh-text.json'),
  ('warsh-106-2', 'warsh', 106, 2, 'ࡴيلَٰفِهِمْ رِحْلَةَ ࡰ۬لشِّتَآءِ وَالصَّيْفِ࣌', 'ࡴيلفهم رحلة ࡰلشتاء والصيف࣌', NULL, 602, 'local:warsh-text.json'),
  ('warsh-106-3', 'warsh', 106, 3, 'فَلْيَعْبُدُواْ رَبَّ هَٰذَا ࡰ۬لْبَيْتِ', 'فليعبدوا رب هذا ࡰلبيت', NULL, 602, 'local:warsh-text.json'),
  ('warsh-106-4', 'warsh', 106, 4, 'ࡴ۬لذِےٓ أَطْعَمَهُم مِّن جُوعࣲ', 'ࡴلذے أطعمهم من جوع', NULL, 602, 'local:warsh-text.json'),
  ('warsh-106-5', 'warsh', 106, 5, 'وَءَامَنَهُم مِّنْ خَوْفٍ࣌', 'وءامنهم من خوف࣌', NULL, 602, 'local:warsh-text.json'),
  ('warsh-107-1', 'warsh', 107, 1, 'ࡰرَٰٓيْتَ ࡰ۬لذِے يُكَذِّبُ بِالدِّينِ', 'ࡰريت ࡰلذے يكذب بالدين', NULL, 602, 'local:warsh-text.json'),
  ('warsh-107-2', 'warsh', 107, 2, 'فَذَٰلِكَ ࡰ۬لذِے يَدُعُّ ࡲ۬لْيَتِيمَ', 'فذلك ࡰلذے يدع ࡲليتيم', NULL, 602, 'local:warsh-text.json'),
  ('warsh-107-3', 'warsh', 107, 3, 'وَلَا يَحُضُّ عَلَىٰ طَعَامِ ࡴ۬لْمِسْكِينِ࣌', 'ولا يحض على طعام ࡴلمسكين࣌', NULL, 602, 'local:warsh-text.json'),
  ('warsh-107-4', 'warsh', 107, 4, 'فَوَيْلࣱ لِّلْمُصَلِّينَ', 'فويل للمصلين', NULL, 602, 'local:warsh-text.json'),
  ('warsh-107-5', 'warsh', 107, 5, 'ࡰ۬لذِينَ هُمْ عَن صَلَاتِهِمْ سَاهُونَ', 'ࡰلذين هم عن صلاتهم ساهون', NULL, 602, 'local:warsh-text.json'),
  ('warsh-107-6', 'warsh', 107, 6, 'ࡰ۬لذِينَ هُمْ يُرَآءُونَ وَيَمْنَعُونَ ࡰ۬لْمَاعُونَ࣌', 'ࡰلذين هم يراءون ويمنعون ࡰلماعون࣌', NULL, 602, 'local:warsh-text.json'),
  ('warsh-108-1', 'warsh', 108, 1, 'إِنَّآ أَعْطَيْنَٰكَ ࡰ۬لْكَوْثَرَ', 'إنا أعطينك ࡰلكوثر', NULL, 602, 'local:warsh-text.json'),
  ('warsh-108-2', 'warsh', 108, 2, 'فَصَلِّ لِرَبِّكَ وَانْحَرِ࣌', 'فصل لربك وانحر࣌', NULL, 602, 'local:warsh-text.json'),
  ('warsh-108-3', 'warsh', 108, 3, 'ࡴنَّ شَانِئَكَ هُوَ ࡰ۬لَابْتَرُ࣌', 'ࡴن شانئك هو ࡰلابتر࣌', NULL, 602, 'local:warsh-text.json'),
  ('warsh-109-1', 'warsh', 109, 1, 'قُلْ يَٰٓأَيُّهَا ࡰ۬لْكَٰفِرُونَ', 'قل يأيها ࡰلكفرون', NULL, 603, 'local:warsh-text.json'),
  ('warsh-109-2', 'warsh', 109, 2, 'لَآ أَعْبُدُ مَا تَعْبُدُونَ', 'لا أعبد ما تعبدون', NULL, 603, 'local:warsh-text.json'),
  ('warsh-109-3', 'warsh', 109, 3, 'وَلَآ أَنتُمْ عَٰبِدُونَ مَآ أَعْبُدُ࣌', 'ولا أنتم عبدون ما أعبد࣌', NULL, 603, 'local:warsh-text.json'),
  ('warsh-109-4', 'warsh', 109, 4, 'وَلَآ أَنَا عَابِدࣱ مَّا عَبَدتُّمْ', 'ولا أنا عابد ما عبدتم', NULL, 603, 'local:warsh-text.json'),
  ('warsh-109-5', 'warsh', 109, 5, 'وَلَآ أَنتُمْ عَٰبِدُونَ مَآ أَعْبُدُ࣌', 'ولا أنتم عبدون ما أعبد࣌', NULL, 603, 'local:warsh-text.json'),
  ('warsh-109-6', 'warsh', 109, 6, 'لَكُمْ دِينُكُمْ وَلِيَ دِينِ࣌', 'لكم دينكم ولي دين࣌', NULL, 603, 'local:warsh-text.json'),
  ('warsh-110-1', 'warsh', 110, 1, 'إِذَا جَآءَ نَصْرُ ࡲ۬للَّهِ وَالْفَتْحُ', 'إذا جاء نصر ࡲلله والفتح', NULL, 603, 'local:warsh-text.json'),
  ('warsh-110-2', 'warsh', 110, 2, 'وَرَأَيْتَ ࡰ۬لنَّاسَ يَدْخُلُونَ فِے دِينِ ࡴ۬للَّهِ أَفْوَاجاࣰ', 'ورأيت ࡰلناس يدخلون فے دين ࡴلله أفواجا', NULL, 603, 'local:warsh-text.json'),
  ('warsh-110-3', 'warsh', 110, 3, 'فَسَبِّحْ بِحَمْدِ رَبِّكَ وَاسْتَغْفِرْهُ࣌ إِنَّهُۥ كَانَ تَوَّاباࣰ࣌', 'فسبح بحمد ربك واستغفره࣌ إنه كان توابا࣌', NULL, 603, 'local:warsh-text.json'),
  ('warsh-111-1', 'warsh', 111, 1, 'تَبَّتْ يَدَآ أَبِے لَهَبࣲ وَتَبَّ࣌', 'تبت يدا أبے لهب وتب࣌', NULL, 603, 'local:warsh-text.json'),
  ('warsh-111-2', 'warsh', 111, 2, 'مَآ أَغْنٜىٰ عَنْهُ مَالُهُۥ وَمَا كَسَبَ࣌', 'ما أغنى عنه ماله وما كسب࣌', NULL, 603, 'local:warsh-text.json'),
  ('warsh-111-3', 'warsh', 111, 3, 'سَيَصْلَىٰ نَاراࣰ ذَاتَ لَهَبࣲ', 'سيصلى نارا ذات لهب', NULL, 603, 'local:warsh-text.json'),
  ('warsh-111-4', 'warsh', 111, 4, 'وَامْرَأَتُهُۥ࣌ حَمَّالَةُ ࡲ۬لْحَطَبِ', 'وامرأته࣌ حمالة ࡲلحطب', NULL, 603, 'local:warsh-text.json'),
  ('warsh-111-5', 'warsh', 111, 5, 'فِے جِيدِهَا حَبْلࣱ مِّن مَّسَدࣲ࣌', 'فے جيدها حبل من مسد࣌', NULL, 603, 'local:warsh-text.json'),
  ('warsh-112-1', 'warsh', 112, 1, 'قُلْ هُوَ ࡰ۬للَّهُ أَحَدٌ࣌', 'قل هو ࡰلله أحد࣌', NULL, 604, 'local:warsh-text.json'),
  ('warsh-112-2', 'warsh', 112, 2, 'ࡴ۬للَّهُ ࡲ۬لصَّمَدُ࣌', 'ࡴلله ࡲلصمد࣌', NULL, 604, 'local:warsh-text.json'),
  ('warsh-112-3', 'warsh', 112, 3, 'لَمْ يَلِدْ وَلَمْ يُولَدْ࣌', 'لم يلد ولم يولد࣌', NULL, 604, 'local:warsh-text.json'),
  ('warsh-112-4', 'warsh', 112, 4, 'وَلَمْ يَكُن لَّهُۥ كُفُؤاً ࡰحَدࣱ࣌', 'ولم يكن له كفؤا ࡰحد࣌', NULL, 604, 'local:warsh-text.json'),
  ('warsh-113-1', 'warsh', 113, 1, 'قُلَ ࡰعُوذُ بِرَبِّ ࡴ۬لْفَلَقِ', 'قل ࡰعوذ برب ࡴلفلق', NULL, 604, 'local:warsh-text.json'),
  ('warsh-113-2', 'warsh', 113, 2, 'مِن شَرِّ مَا خَلَقَ', 'من شر ما خلق', NULL, 604, 'local:warsh-text.json'),
  ('warsh-113-3', 'warsh', 113, 3, 'وَمِن شَرِّ غَاسِقٍ ࡴذَا وَقَبَ', 'ومن شر غاسق ࡴذا وقب', NULL, 604, 'local:warsh-text.json'),
  ('warsh-113-4', 'warsh', 113, 4, 'وَمِن شَرِّ ࡴ۬لنَّفَّٰثَٰتِ فِے ࡴ۬لْعُقَدِ', 'ومن شر ࡴلنفثت فے ࡴلعقد', NULL, 604, 'local:warsh-text.json'),
  ('warsh-113-5', 'warsh', 113, 5, 'وَمِن شَرِّ حَاسِدٍ ࡴذَا حَسَدَ࣌', 'ومن شر حاسد ࡴذا حسد࣌', NULL, 604, 'local:warsh-text.json'),
  ('warsh-114-1', 'warsh', 114, 1, 'قُلَ ࡰعُوذُ بِرَبِّ ࡴ۬لنَّاسِ', 'قل ࡰعوذ برب ࡴلناس', NULL, 604, 'local:warsh-text.json'),
  ('warsh-114-2', 'warsh', 114, 2, 'مَلِكِ ࡴ۬لنَّاسِ', 'ملك ࡴلناس', NULL, 604, 'local:warsh-text.json'),
  ('warsh-114-3', 'warsh', 114, 3, 'إِلَٰهِ ࡴ۬لنَّاسِ', 'إله ࡴلناس', NULL, 604, 'local:warsh-text.json'),
  ('warsh-114-4', 'warsh', 114, 4, 'مِن شَرِّ ࡴ۬لْوَسْوَاسِ ࡴ۬لْخَنَّاسِ', 'من شر ࡴلوسواس ࡴلخناس', NULL, 604, 'local:warsh-text.json'),
  ('warsh-114-5', 'warsh', 114, 5, 'ࡴ۬لذِے يُوَسْوِسُ فِے صُدُورِ ࡴ۬لنَّاسِ', 'ࡴلذے يوسوس فے صدور ࡴلناس', NULL, 604, 'local:warsh-text.json'),
  ('warsh-114-6', 'warsh', 114, 6, 'مِنَ ࡰ۬لْجِنَّةِ وَالنَّاسِ࣌', 'من ࡰلجنة والناس࣌', NULL, 604, 'local:warsh-text.json')
insert into public.ayahs (id, riwayah, surah_number, ayah_number, text, simple_text, juz, page, source) values
  ('hafs-1-1', 'hafs', 1, 1, '﻿بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ', 'بسم الله الرحمن الرحيم', NULL, 1, 'local:hafs-text.json'),
  ('hafs-1-2', 'hafs', 1, 2, 'ٱلْحَمْدُ لِلَّهِ رَبِّ ٱلْعَٰلَمِينَ', 'الحمد لله رب العلمين', NULL, 1, 'local:hafs-text.json'),
  ('hafs-1-3', 'hafs', 1, 3, 'ٱلرَّحْمَٰنِ ٱلرَّحِيمِ', 'الرحمن الرحيم', NULL, 1, 'local:hafs-text.json'),
  ('hafs-1-4', 'hafs', 1, 4, 'مَٰلِكِ يَوْمِ ٱلدِّينِ', 'ملك يوم الدين', NULL, 1, 'local:hafs-text.json'),
  ('hafs-1-5', 'hafs', 1, 5, 'إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ', 'إياك نعبد وإياك نستعين', NULL, 1, 'local:hafs-text.json'),
  ('hafs-1-6', 'hafs', 1, 6, 'ٱهْدِنَا ٱلصِّرَٰطَ ٱلْمُسْتَقِيمَ', 'اهدنا الصرط المستقيم', NULL, 1, 'local:hafs-text.json'),
  ('hafs-1-7', 'hafs', 1, 7, 'صِرَٰطَ ٱلَّذِينَ أَنْعَمْتَ عَلَيْهِمْ غَيْرِ ٱلْمَغْضُوبِ عَلَيْهِمْ وَلَا ٱلضَّآلِّينَ', 'صرط الذين أنعمت عليهم غير المغضوب عليهم ولا الضالين', NULL, 1, 'local:hafs-text.json'),
  ('hafs-2-1', 'hafs', 2, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ الٓمٓ', 'بسم الله الرحمن الرحيم الم', NULL, 2, 'local:hafs-text.json'),
  ('hafs-2-2', 'hafs', 2, 2, 'ذَٰلِكَ ٱلْكِتَٰبُ لَا رَيْبَ ۛ فِيهِ ۛ هُدًۭى لِّلْمُتَّقِينَ', 'ذلك الكتب لا ريب  فيه  هدى للمتقين', NULL, 2, 'local:hafs-text.json'),
  ('hafs-2-3', 'hafs', 2, 3, 'ٱلَّذِينَ يُؤْمِنُونَ بِٱلْغَيْبِ وَيُقِيمُونَ ٱلصَّلَوٰةَ وَمِمَّا رَزَقْنَٰهُمْ يُنفِقُونَ', 'الذين يؤمنون بالغيب ويقيمون الصلوة ومما رزقنهم ينفقون', NULL, 2, 'local:hafs-text.json'),
  ('hafs-2-4', 'hafs', 2, 4, 'وَٱلَّذِينَ يُؤْمِنُونَ بِمَآ أُنزِلَ إِلَيْكَ وَمَآ أُنزِلَ مِن قَبْلِكَ وَبِٱلْءَاخِرَةِ هُمْ يُوقِنُونَ', 'والذين يؤمنون بما أنزل إليك وما أنزل من قبلك وبالءاخرة هم يوقنون', NULL, 2, 'local:hafs-text.json'),
  ('hafs-2-5', 'hafs', 2, 5, 'أُو۟لَٰٓئِكَ عَلَىٰ هُدًۭى مِّن رَّبِّهِمْ ۖ وَأُو۟لَٰٓئِكَ هُمُ ٱلْمُفْلِحُونَ', 'أولئك على هدى من ربهم  وأولئك هم المفلحون', NULL, 2, 'local:hafs-text.json'),
  ('hafs-2-6', 'hafs', 2, 6, 'إِنَّ ٱلَّذِينَ كَفَرُوا۟ سَوَآءٌ عَلَيْهِمْ ءَأَنذَرْتَهُمْ أَمْ لَمْ تُنذِرْهُمْ لَا يُؤْمِنُونَ', 'إن الذين كفروا سواء عليهم ءأنذرتهم أم لم تنذرهم لا يؤمنون', NULL, 3, 'local:hafs-text.json'),
  ('hafs-2-7', 'hafs', 2, 7, 'خَتَمَ ٱللَّهُ عَلَىٰ قُلُوبِهِمْ وَعَلَىٰ سَمْعِهِمْ ۖ وَعَلَىٰٓ أَبْصَٰرِهِمْ غِشَٰوَةٌۭ ۖ وَلَهُمْ عَذَابٌ عَظِيمٌۭ', 'ختم الله على قلوبهم وعلى سمعهم  وعلى أبصرهم غشوة  ولهم عذاب عظيم', NULL, 3, 'local:hafs-text.json'),
  ('hafs-2-8', 'hafs', 2, 8, 'وَمِنَ ٱلنَّاسِ مَن يَقُولُ ءَامَنَّا بِٱللَّهِ وَبِٱلْيَوْمِ ٱلْءَاخِرِ وَمَا هُم بِمُؤْمِنِينَ', 'ومن الناس من يقول ءامنا بالله وباليوم الءاخر وما هم بمؤمنين', NULL, 3, 'local:hafs-text.json'),
  ('hafs-2-9', 'hafs', 2, 9, 'يُخَٰدِعُونَ ٱللَّهَ وَٱلَّذِينَ ءَامَنُوا۟ وَمَا يَخْدَعُونَ إِلَّآ أَنفُسَهُمْ وَمَا يَشْعُرُونَ', 'يخدعون الله والذين ءامنوا وما يخدعون إلا أنفسهم وما يشعرون', NULL, 3, 'local:hafs-text.json'),
  ('hafs-2-10', 'hafs', 2, 10, 'فِى قُلُوبِهِم مَّرَضٌۭ فَزَادَهُمُ ٱللَّهُ مَرَضًۭا ۖ وَلَهُمْ عَذَابٌ أَلِيمٌۢ بِمَا كَانُوا۟ يَكْذِبُونَ', 'فى قلوبهم مرض فزادهم الله مرضا  ولهم عذاب أليم بما كانوا يكذبون', NULL, 3, 'local:hafs-text.json'),
  ('hafs-2-11', 'hafs', 2, 11, 'وَإِذَا قِيلَ لَهُمْ لَا تُفْسِدُوا۟ فِى ٱلْأَرْضِ قَالُوٓا۟ إِنَّمَا نَحْنُ مُصْلِحُونَ', 'وإذا قيل لهم لا تفسدوا فى الأرض قالوا إنما نحن مصلحون', NULL, 3, 'local:hafs-text.json'),
  ('hafs-2-12', 'hafs', 2, 12, 'أَلَآ إِنَّهُمْ هُمُ ٱلْمُفْسِدُونَ وَلَٰكِن لَّا يَشْعُرُونَ', 'ألا إنهم هم المفسدون ولكن لا يشعرون', NULL, 3, 'local:hafs-text.json'),
  ('hafs-2-13', 'hafs', 2, 13, 'وَإِذَا قِيلَ لَهُمْ ءَامِنُوا۟ كَمَآ ءَامَنَ ٱلنَّاسُ قَالُوٓا۟ أَنُؤْمِنُ كَمَآ ءَامَنَ ٱلسُّفَهَآءُ ۗ أَلَآ إِنَّهُمْ هُمُ ٱلسُّفَهَآءُ وَلَٰكِن لَّا يَعْلَمُونَ', 'وإذا قيل لهم ءامنوا كما ءامن الناس قالوا أنؤمن كما ءامن السفهاء  ألا إنهم هم السفهاء ولكن لا يعلمون', NULL, 3, 'local:hafs-text.json'),
  ('hafs-2-14', 'hafs', 2, 14, 'وَإِذَا لَقُوا۟ ٱلَّذِينَ ءَامَنُوا۟ قَالُوٓا۟ ءَامَنَّا وَإِذَا خَلَوْا۟ إِلَىٰ شَيَٰطِينِهِمْ قَالُوٓا۟ إِنَّا مَعَكُمْ إِنَّمَا نَحْنُ مُسْتَهْزِءُونَ', 'وإذا لقوا الذين ءامنوا قالوا ءامنا وإذا خلوا إلى شيطينهم قالوا إنا معكم إنما نحن مستهزءون', NULL, 3, 'local:hafs-text.json'),
  ('hafs-2-15', 'hafs', 2, 15, 'ٱللَّهُ يَسْتَهْزِئُ بِهِمْ وَيَمُدُّهُمْ فِى طُغْيَٰنِهِمْ يَعْمَهُونَ', 'الله يستهزئ بهم ويمدهم فى طغينهم يعمهون', NULL, 3, 'local:hafs-text.json'),
  ('hafs-2-16', 'hafs', 2, 16, 'أُو۟لَٰٓئِكَ ٱلَّذِينَ ٱشْتَرَوُا۟ ٱلضَّلَٰلَةَ بِٱلْهُدَىٰ فَمَا رَبِحَت تِّجَٰرَتُهُمْ وَمَا كَانُوا۟ مُهْتَدِينَ', 'أولئك الذين اشتروا الضللة بالهدى فما ربحت تجرتهم وما كانوا مهتدين', NULL, 3, 'local:hafs-text.json'),
  ('hafs-2-17', 'hafs', 2, 17, 'مَثَلُهُمْ كَمَثَلِ ٱلَّذِى ٱسْتَوْقَدَ نَارًۭا فَلَمَّآ أَضَآءَتْ مَا حَوْلَهُۥ ذَهَبَ ٱللَّهُ بِنُورِهِمْ وَتَرَكَهُمْ فِى ظُلُمَٰتٍۢ لَّا يُبْصِرُونَ', 'مثلهم كمثل الذى استوقد نارا فلما أضاءت ما حوله ذهب الله بنورهم وتركهم فى ظلمت لا يبصرون', NULL, 4, 'local:hafs-text.json'),
  ('hafs-2-18', 'hafs', 2, 18, 'صُمٌّۢ بُكْمٌ عُمْىٌۭ فَهُمْ لَا يَرْجِعُونَ', 'صم بكم عمى فهم لا يرجعون', NULL, 4, 'local:hafs-text.json'),
  ('hafs-2-19', 'hafs', 2, 19, 'أَوْ كَصَيِّبٍۢ مِّنَ ٱلسَّمَآءِ فِيهِ ظُلُمَٰتٌۭ وَرَعْدٌۭ وَبَرْقٌۭ يَجْعَلُونَ أَصَٰبِعَهُمْ فِىٓ ءَاذَانِهِم مِّنَ ٱلصَّوَٰعِقِ حَذَرَ ٱلْمَوْتِ ۚ وَٱللَّهُ مُحِيطٌۢ بِٱلْكَٰفِرِينَ', 'أو كصيب من السماء فيه ظلمت ورعد وبرق يجعلون أصبعهم فى ءاذانهم من الصوعق حذر الموت  والله محيط بالكفرين', NULL, 4, 'local:hafs-text.json'),
  ('hafs-2-20', 'hafs', 2, 20, 'يَكَادُ ٱلْبَرْقُ يَخْطَفُ أَبْصَٰرَهُمْ ۖ كُلَّمَآ أَضَآءَ لَهُم مَّشَوْا۟ فِيهِ وَإِذَآ أَظْلَمَ عَلَيْهِمْ قَامُوا۟ ۚ وَلَوْ شَآءَ ٱللَّهُ لَذَهَبَ بِسَمْعِهِمْ وَأَبْصَٰرِهِمْ ۚ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَىْءٍۢ قَدِيرٌۭ', 'يكاد البرق يخطف أبصرهم  كلما أضاء لهم مشوا فيه وإذا أظلم عليهم قاموا  ولو شاء الله لذهب بسمعهم وأبصرهم  إن الله على كل شىء قدير', NULL, 4, 'local:hafs-text.json'),
  ('hafs-2-21', 'hafs', 2, 21, 'يَٰٓأَيُّهَا ٱلنَّاسُ ٱعْبُدُوا۟ رَبَّكُمُ ٱلَّذِى خَلَقَكُمْ وَٱلَّذِينَ مِن قَبْلِكُمْ لَعَلَّكُمْ تَتَّقُونَ', 'يأيها الناس اعبدوا ربكم الذى خلقكم والذين من قبلكم لعلكم تتقون', NULL, 4, 'local:hafs-text.json'),
  ('hafs-2-22', 'hafs', 2, 22, 'ٱلَّذِى جَعَلَ لَكُمُ ٱلْأَرْضَ فِرَٰشًۭا وَٱلسَّمَآءَ بِنَآءًۭ وَأَنزَلَ مِنَ ٱلسَّمَآءِ مَآءًۭ فَأَخْرَجَ بِهِۦ مِنَ ٱلثَّمَرَٰتِ رِزْقًۭا لَّكُمْ ۖ فَلَا تَجْعَلُوا۟ لِلَّهِ أَندَادًۭا وَأَنتُمْ تَعْلَمُونَ', 'الذى جعل لكم الأرض فرشا والسماء بناء وأنزل من السماء ماء فأخرج به من الثمرت رزقا لكم  فلا تجعلوا لله أندادا وأنتم تعلمون', NULL, 4, 'local:hafs-text.json'),
  ('hafs-2-23', 'hafs', 2, 23, 'وَإِن كُنتُمْ فِى رَيْبٍۢ مِّمَّا نَزَّلْنَا عَلَىٰ عَبْدِنَا فَأْتُوا۟ بِسُورَةٍۢ مِّن مِّثْلِهِۦ وَٱدْعُوا۟ شُهَدَآءَكُم مِّن دُونِ ٱللَّهِ إِن كُنتُمْ صَٰدِقِينَ', 'وإن كنتم فى ريب مما نزلنا على عبدنا فأتوا بسورة من مثله وادعوا شهداءكم من دون الله إن كنتم صدقين', NULL, 4, 'local:hafs-text.json'),
  ('hafs-2-24', 'hafs', 2, 24, 'فَإِن لَّمْ تَفْعَلُوا۟ وَلَن تَفْعَلُوا۟ فَٱتَّقُوا۟ ٱلنَّارَ ٱلَّتِى وَقُودُهَا ٱلنَّاسُ وَٱلْحِجَارَةُ ۖ أُعِدَّتْ لِلْكَٰفِرِينَ', 'فإن لم تفعلوا ولن تفعلوا فاتقوا النار التى وقودها الناس والحجارة  أعدت للكفرين', NULL, 4, 'local:hafs-text.json'),
  ('hafs-2-25', 'hafs', 2, 25, 'وَبَشِّرِ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ أَنَّ لَهُمْ جَنَّٰتٍۢ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ ۖ كُلَّمَا رُزِقُوا۟ مِنْهَا مِن ثَمَرَةٍۢ رِّزْقًۭا ۙ قَالُوا۟ هَٰذَا ٱلَّذِى رُزِقْنَا مِن قَبْلُ ۖ وَأُتُوا۟ بِهِۦ مُتَشَٰبِهًۭا ۖ وَلَهُمْ فِيهَآ أَزْوَٰجٌۭ مُّطَهَّرَةٌۭ ۖ وَهُمْ فِيهَا خَٰلِدُونَ', 'وبشر الذين ءامنوا وعملوا الصلحت أن لهم جنت تجرى من تحتها الأنهر  كلما رزقوا منها من ثمرة رزقا  قالوا هذا الذى رزقنا من قبل  وأتوا به متشبها  ولهم فيها أزوج مطهرة  وهم فيها خلدون', NULL, 5, 'local:hafs-text.json'),
  ('hafs-2-26', 'hafs', 2, 26, '۞ إِنَّ ٱللَّهَ لَا يَسْتَحْىِۦٓ أَن يَضْرِبَ مَثَلًۭا مَّا بَعُوضَةًۭ فَمَا فَوْقَهَا ۚ فَأَمَّا ٱلَّذِينَ ءَامَنُوا۟ فَيَعْلَمُونَ أَنَّهُ ٱلْحَقُّ مِن رَّبِّهِمْ ۖ وَأَمَّا ٱلَّذِينَ كَفَرُوا۟ فَيَقُولُونَ مَاذَآ أَرَادَ ٱللَّهُ بِهَٰذَا مَثَلًۭا ۘ يُضِلُّ بِهِۦ كَثِيرًۭا وَيَهْدِى بِهِۦ كَثِيرًۭا ۚ وَمَا يُضِلُّ بِهِۦٓ إِلَّا ٱلْفَٰسِقِينَ', 'إن الله لا يستحى أن يضرب مثلا ما بعوضة فما فوقها  فأما الذين ءامنوا فيعلمون أنه الحق من ربهم  وأما الذين كفروا فيقولون ماذا أراد الله بهذا مثلا  يضل به كثيرا ويهدى به كثيرا  وما يضل به إلا الفسقين', NULL, 5, 'local:hafs-text.json'),
  ('hafs-2-27', 'hafs', 2, 27, 'ٱلَّذِينَ يَنقُضُونَ عَهْدَ ٱللَّهِ مِنۢ بَعْدِ مِيثَٰقِهِۦ وَيَقْطَعُونَ مَآ أَمَرَ ٱللَّهُ بِهِۦٓ أَن يُوصَلَ وَيُفْسِدُونَ فِى ٱلْأَرْضِ ۚ أُو۟لَٰٓئِكَ هُمُ ٱلْخَٰسِرُونَ', 'الذين ينقضون عهد الله من بعد ميثقه ويقطعون ما أمر الله به أن يوصل ويفسدون فى الأرض  أولئك هم الخسرون', NULL, 5, 'local:hafs-text.json'),
  ('hafs-2-28', 'hafs', 2, 28, 'كَيْفَ تَكْفُرُونَ بِٱللَّهِ وَكُنتُمْ أَمْوَٰتًۭا فَأَحْيَٰكُمْ ۖ ثُمَّ يُمِيتُكُمْ ثُمَّ يُحْيِيكُمْ ثُمَّ إِلَيْهِ تُرْجَعُونَ', 'كيف تكفرون بالله وكنتم أموتا فأحيكم  ثم يميتكم ثم يحييكم ثم إليه ترجعون', NULL, 5, 'local:hafs-text.json'),
  ('hafs-2-29', 'hafs', 2, 29, 'هُوَ ٱلَّذِى خَلَقَ لَكُم مَّا فِى ٱلْأَرْضِ جَمِيعًۭا ثُمَّ ٱسْتَوَىٰٓ إِلَى ٱلسَّمَآءِ فَسَوَّىٰهُنَّ سَبْعَ سَمَٰوَٰتٍۢ ۚ وَهُوَ بِكُلِّ شَىْءٍ عَلِيمٌۭ', 'هو الذى خلق لكم ما فى الأرض جميعا ثم استوى إلى السماء فسوىهن سبع سموت  وهو بكل شىء عليم', NULL, 5, 'local:hafs-text.json'),
  ('hafs-2-30', 'hafs', 2, 30, 'وَإِذْ قَالَ رَبُّكَ لِلْمَلَٰٓئِكَةِ إِنِّى جَاعِلٌۭ فِى ٱلْأَرْضِ خَلِيفَةًۭ ۖ قَالُوٓا۟ أَتَجْعَلُ فِيهَا مَن يُفْسِدُ فِيهَا وَيَسْفِكُ ٱلدِّمَآءَ وَنَحْنُ نُسَبِّحُ بِحَمْدِكَ وَنُقَدِّسُ لَكَ ۖ قَالَ إِنِّىٓ أَعْلَمُ مَا لَا تَعْلَمُونَ', 'وإذ قال ربك للملئكة إنى جاعل فى الأرض خليفة  قالوا أتجعل فيها من يفسد فيها ويسفك الدماء ونحن نسبح بحمدك ونقدس لك  قال إنى أعلم ما لا تعلمون', NULL, 6, 'local:hafs-text.json'),
  ('hafs-2-31', 'hafs', 2, 31, 'وَعَلَّمَ ءَادَمَ ٱلْأَسْمَآءَ كُلَّهَا ثُمَّ عَرَضَهُمْ عَلَى ٱلْمَلَٰٓئِكَةِ فَقَالَ أَنۢبِـُٔونِى بِأَسْمَآءِ هَٰٓؤُلَآءِ إِن كُنتُمْ صَٰدِقِينَ', 'وعلم ءادم الأسماء كلها ثم عرضهم على الملئكة فقال أنبونى بأسماء هؤلاء إن كنتم صدقين', NULL, 6, 'local:hafs-text.json'),
  ('hafs-2-32', 'hafs', 2, 32, 'قَالُوا۟ سُبْحَٰنَكَ لَا عِلْمَ لَنَآ إِلَّا مَا عَلَّمْتَنَآ ۖ إِنَّكَ أَنتَ ٱلْعَلِيمُ ٱلْحَكِيمُ', 'قالوا سبحنك لا علم لنا إلا ما علمتنا  إنك أنت العليم الحكيم', NULL, 6, 'local:hafs-text.json'),
  ('hafs-2-33', 'hafs', 2, 33, 'قَالَ يَٰٓـَٔادَمُ أَنۢبِئْهُم بِأَسْمَآئِهِمْ ۖ فَلَمَّآ أَنۢبَأَهُم بِأَسْمَآئِهِمْ قَالَ أَلَمْ أَقُل لَّكُمْ إِنِّىٓ أَعْلَمُ غَيْبَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَأَعْلَمُ مَا تُبْدُونَ وَمَا كُنتُمْ تَكْتُمُونَ', 'قال يادم أنبئهم بأسمائهم  فلما أنبأهم بأسمائهم قال ألم أقل لكم إنى أعلم غيب السموت والأرض وأعلم ما تبدون وما كنتم تكتمون', NULL, 6, 'local:hafs-text.json'),
  ('hafs-2-34', 'hafs', 2, 34, 'وَإِذْ قُلْنَا لِلْمَلَٰٓئِكَةِ ٱسْجُدُوا۟ لِءَادَمَ فَسَجَدُوٓا۟ إِلَّآ إِبْلِيسَ أَبَىٰ وَٱسْتَكْبَرَ وَكَانَ مِنَ ٱلْكَٰفِرِينَ', 'وإذ قلنا للملئكة اسجدوا لءادم فسجدوا إلا إبليس أبى واستكبر وكان من الكفرين', NULL, 6, 'local:hafs-text.json'),
  ('hafs-2-35', 'hafs', 2, 35, 'وَقُلْنَا يَٰٓـَٔادَمُ ٱسْكُنْ أَنتَ وَزَوْجُكَ ٱلْجَنَّةَ وَكُلَا مِنْهَا رَغَدًا حَيْثُ شِئْتُمَا وَلَا تَقْرَبَا هَٰذِهِ ٱلشَّجَرَةَ فَتَكُونَا مِنَ ٱلظَّٰلِمِينَ', 'وقلنا يادم اسكن أنت وزوجك الجنة وكلا منها رغدا حيث شئتما ولا تقربا هذه الشجرة فتكونا من الظلمين', NULL, 6, 'local:hafs-text.json'),
  ('hafs-2-36', 'hafs', 2, 36, 'فَأَزَلَّهُمَا ٱلشَّيْطَٰنُ عَنْهَا فَأَخْرَجَهُمَا مِمَّا كَانَا فِيهِ ۖ وَقُلْنَا ٱهْبِطُوا۟ بَعْضُكُمْ لِبَعْضٍ عَدُوٌّۭ ۖ وَلَكُمْ فِى ٱلْأَرْضِ مُسْتَقَرٌّۭ وَمَتَٰعٌ إِلَىٰ حِينٍۢ', 'فأزلهما الشيطن عنها فأخرجهما مما كانا فيه  وقلنا اهبطوا بعضكم لبعض عدو  ولكم فى الأرض مستقر ومتع إلى حين', NULL, 6, 'local:hafs-text.json'),
  ('hafs-2-37', 'hafs', 2, 37, 'فَتَلَقَّىٰٓ ءَادَمُ مِن رَّبِّهِۦ كَلِمَٰتٍۢ فَتَابَ عَلَيْهِ ۚ إِنَّهُۥ هُوَ ٱلتَّوَّابُ ٱلرَّحِيمُ', 'فتلقى ءادم من ربه كلمت فتاب عليه  إنه هو التواب الرحيم', NULL, 6, 'local:hafs-text.json'),
  ('hafs-2-38', 'hafs', 2, 38, 'قُلْنَا ٱهْبِطُوا۟ مِنْهَا جَمِيعًۭا ۖ فَإِمَّا يَأْتِيَنَّكُم مِّنِّى هُدًۭى فَمَن تَبِعَ هُدَاىَ فَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ', 'قلنا اهبطوا منها جميعا  فإما يأتينكم منى هدى فمن تبع هداى فلا خوف عليهم ولا هم يحزنون', NULL, 7, 'local:hafs-text.json'),
  ('hafs-2-39', 'hafs', 2, 39, 'وَٱلَّذِينَ كَفَرُوا۟ وَكَذَّبُوا۟ بِـَٔايَٰتِنَآ أُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلنَّارِ ۖ هُمْ فِيهَا خَٰلِدُونَ', 'والذين كفروا وكذبوا بايتنا أولئك أصحب النار  هم فيها خلدون', NULL, 7, 'local:hafs-text.json'),
  ('hafs-2-40', 'hafs', 2, 40, 'يَٰبَنِىٓ إِسْرَٰٓءِيلَ ٱذْكُرُوا۟ نِعْمَتِىَ ٱلَّتِىٓ أَنْعَمْتُ عَلَيْكُمْ وَأَوْفُوا۟ بِعَهْدِىٓ أُوفِ بِعَهْدِكُمْ وَإِيَّٰىَ فَٱرْهَبُونِ', 'يبنى إسرءيل اذكروا نعمتى التى أنعمت عليكم وأوفوا بعهدى أوف بعهدكم وإيى فارهبون', NULL, 7, 'local:hafs-text.json'),
  ('hafs-2-41', 'hafs', 2, 41, 'وَءَامِنُوا۟ بِمَآ أَنزَلْتُ مُصَدِّقًۭا لِّمَا مَعَكُمْ وَلَا تَكُونُوٓا۟ أَوَّلَ كَافِرٍۭ بِهِۦ ۖ وَلَا تَشْتَرُوا۟ بِـَٔايَٰتِى ثَمَنًۭا قَلِيلًۭا وَإِيَّٰىَ فَٱتَّقُونِ', 'وءامنوا بما أنزلت مصدقا لما معكم ولا تكونوا أول كافر به  ولا تشتروا بايتى ثمنا قليلا وإيى فاتقون', NULL, 7, 'local:hafs-text.json'),
  ('hafs-2-42', 'hafs', 2, 42, 'وَلَا تَلْبِسُوا۟ ٱلْحَقَّ بِٱلْبَٰطِلِ وَتَكْتُمُوا۟ ٱلْحَقَّ وَأَنتُمْ تَعْلَمُونَ', 'ولا تلبسوا الحق بالبطل وتكتموا الحق وأنتم تعلمون', NULL, 7, 'local:hafs-text.json'),
  ('hafs-2-43', 'hafs', 2, 43, 'وَأَقِيمُوا۟ ٱلصَّلَوٰةَ وَءَاتُوا۟ ٱلزَّكَوٰةَ وَٱرْكَعُوا۟ مَعَ ٱلرَّٰكِعِينَ', 'وأقيموا الصلوة وءاتوا الزكوة واركعوا مع الركعين', NULL, 7, 'local:hafs-text.json'),
  ('hafs-2-44', 'hafs', 2, 44, '۞ أَتَأْمُرُونَ ٱلنَّاسَ بِٱلْبِرِّ وَتَنسَوْنَ أَنفُسَكُمْ وَأَنتُمْ تَتْلُونَ ٱلْكِتَٰبَ ۚ أَفَلَا تَعْقِلُونَ', 'أتأمرون الناس بالبر وتنسون أنفسكم وأنتم تتلون الكتب  أفلا تعقلون', NULL, 7, 'local:hafs-text.json'),
  ('hafs-2-45', 'hafs', 2, 45, 'وَٱسْتَعِينُوا۟ بِٱلصَّبْرِ وَٱلصَّلَوٰةِ ۚ وَإِنَّهَا لَكَبِيرَةٌ إِلَّا عَلَى ٱلْخَٰشِعِينَ', 'واستعينوا بالصبر والصلوة  وإنها لكبيرة إلا على الخشعين', NULL, 7, 'local:hafs-text.json'),
  ('hafs-2-46', 'hafs', 2, 46, 'ٱلَّذِينَ يَظُنُّونَ أَنَّهُم مُّلَٰقُوا۟ رَبِّهِمْ وَأَنَّهُمْ إِلَيْهِ رَٰجِعُونَ', 'الذين يظنون أنهم ملقوا ربهم وأنهم إليه رجعون', NULL, 7, 'local:hafs-text.json'),
  ('hafs-2-47', 'hafs', 2, 47, 'يَٰبَنِىٓ إِسْرَٰٓءِيلَ ٱذْكُرُوا۟ نِعْمَتِىَ ٱلَّتِىٓ أَنْعَمْتُ عَلَيْكُمْ وَأَنِّى فَضَّلْتُكُمْ عَلَى ٱلْعَٰلَمِينَ', 'يبنى إسرءيل اذكروا نعمتى التى أنعمت عليكم وأنى فضلتكم على العلمين', NULL, 7, 'local:hafs-text.json'),
  ('hafs-2-48', 'hafs', 2, 48, 'وَٱتَّقُوا۟ يَوْمًۭا لَّا تَجْزِى نَفْسٌ عَن نَّفْسٍۢ شَيْـًۭٔا وَلَا يُقْبَلُ مِنْهَا شَفَٰعَةٌۭ وَلَا يُؤْخَذُ مِنْهَا عَدْلٌۭ وَلَا هُمْ يُنصَرُونَ', 'واتقوا يوما لا تجزى نفس عن نفس شيا ولا يقبل منها شفعة ولا يؤخذ منها عدل ولا هم ينصرون', NULL, 7, 'local:hafs-text.json'),
  ('hafs-2-49', 'hafs', 2, 49, 'وَإِذْ نَجَّيْنَٰكُم مِّنْ ءَالِ فِرْعَوْنَ يَسُومُونَكُمْ سُوٓءَ ٱلْعَذَابِ يُذَبِّحُونَ أَبْنَآءَكُمْ وَيَسْتَحْيُونَ نِسَآءَكُمْ ۚ وَفِى ذَٰلِكُم بَلَآءٌۭ مِّن رَّبِّكُمْ عَظِيمٌۭ', 'وإذ نجينكم من ءال فرعون يسومونكم سوء العذاب يذبحون أبناءكم ويستحيون نساءكم  وفى ذلكم بلاء من ربكم عظيم', NULL, 8, 'local:hafs-text.json'),
  ('hafs-2-50', 'hafs', 2, 50, 'وَإِذْ فَرَقْنَا بِكُمُ ٱلْبَحْرَ فَأَنجَيْنَٰكُمْ وَأَغْرَقْنَآ ءَالَ فِرْعَوْنَ وَأَنتُمْ تَنظُرُونَ', 'وإذ فرقنا بكم البحر فأنجينكم وأغرقنا ءال فرعون وأنتم تنظرون', NULL, 8, 'local:hafs-text.json'),
  ('hafs-2-51', 'hafs', 2, 51, 'وَإِذْ وَٰعَدْنَا مُوسَىٰٓ أَرْبَعِينَ لَيْلَةًۭ ثُمَّ ٱتَّخَذْتُمُ ٱلْعِجْلَ مِنۢ بَعْدِهِۦ وَأَنتُمْ ظَٰلِمُونَ', 'وإذ وعدنا موسى أربعين ليلة ثم اتخذتم العجل من بعده وأنتم ظلمون', NULL, 8, 'local:hafs-text.json'),
  ('hafs-2-52', 'hafs', 2, 52, 'ثُمَّ عَفَوْنَا عَنكُم مِّنۢ بَعْدِ ذَٰلِكَ لَعَلَّكُمْ تَشْكُرُونَ', 'ثم عفونا عنكم من بعد ذلك لعلكم تشكرون', NULL, 8, 'local:hafs-text.json'),
  ('hafs-2-53', 'hafs', 2, 53, 'وَإِذْ ءَاتَيْنَا مُوسَى ٱلْكِتَٰبَ وَٱلْفُرْقَانَ لَعَلَّكُمْ تَهْتَدُونَ', 'وإذ ءاتينا موسى الكتب والفرقان لعلكم تهتدون', NULL, 8, 'local:hafs-text.json'),
  ('hafs-2-54', 'hafs', 2, 54, 'وَإِذْ قَالَ مُوسَىٰ لِقَوْمِهِۦ يَٰقَوْمِ إِنَّكُمْ ظَلَمْتُمْ أَنفُسَكُم بِٱتِّخَاذِكُمُ ٱلْعِجْلَ فَتُوبُوٓا۟ إِلَىٰ بَارِئِكُمْ فَٱقْتُلُوٓا۟ أَنفُسَكُمْ ذَٰلِكُمْ خَيْرٌۭ لَّكُمْ عِندَ بَارِئِكُمْ فَتَابَ عَلَيْكُمْ ۚ إِنَّهُۥ هُوَ ٱلتَّوَّابُ ٱلرَّحِيمُ', 'وإذ قال موسى لقومه يقوم إنكم ظلمتم أنفسكم باتخاذكم العجل فتوبوا إلى بارئكم فاقتلوا أنفسكم ذلكم خير لكم عند بارئكم فتاب عليكم  إنه هو التواب الرحيم', NULL, 8, 'local:hafs-text.json'),
  ('hafs-2-55', 'hafs', 2, 55, 'وَإِذْ قُلْتُمْ يَٰمُوسَىٰ لَن نُّؤْمِنَ لَكَ حَتَّىٰ نَرَى ٱللَّهَ جَهْرَةًۭ فَأَخَذَتْكُمُ ٱلصَّٰعِقَةُ وَأَنتُمْ تَنظُرُونَ', 'وإذ قلتم يموسى لن نؤمن لك حتى نرى الله جهرة فأخذتكم الصعقة وأنتم تنظرون', NULL, 8, 'local:hafs-text.json'),
  ('hafs-2-56', 'hafs', 2, 56, 'ثُمَّ بَعَثْنَٰكُم مِّنۢ بَعْدِ مَوْتِكُمْ لَعَلَّكُمْ تَشْكُرُونَ', 'ثم بعثنكم من بعد موتكم لعلكم تشكرون', NULL, 8, 'local:hafs-text.json'),
  ('hafs-2-57', 'hafs', 2, 57, 'وَظَلَّلْنَا عَلَيْكُمُ ٱلْغَمَامَ وَأَنزَلْنَا عَلَيْكُمُ ٱلْمَنَّ وَٱلسَّلْوَىٰ ۖ كُلُوا۟ مِن طَيِّبَٰتِ مَا رَزَقْنَٰكُمْ ۖ وَمَا ظَلَمُونَا وَلَٰكِن كَانُوٓا۟ أَنفُسَهُمْ يَظْلِمُونَ', 'وظللنا عليكم الغمام وأنزلنا عليكم المن والسلوى  كلوا من طيبت ما رزقنكم  وما ظلمونا ولكن كانوا أنفسهم يظلمون', NULL, 8, 'local:hafs-text.json'),
  ('hafs-2-58', 'hafs', 2, 58, 'وَإِذْ قُلْنَا ٱدْخُلُوا۟ هَٰذِهِ ٱلْقَرْيَةَ فَكُلُوا۟ مِنْهَا حَيْثُ شِئْتُمْ رَغَدًۭا وَٱدْخُلُوا۟ ٱلْبَابَ سُجَّدًۭا وَقُولُوا۟ حِطَّةٌۭ نَّغْفِرْ لَكُمْ خَطَٰيَٰكُمْ ۚ وَسَنَزِيدُ ٱلْمُحْسِنِينَ', 'وإذ قلنا ادخلوا هذه القرية فكلوا منها حيث شئتم رغدا وادخلوا الباب سجدا وقولوا حطة نغفر لكم خطيكم  وسنزيد المحسنين', NULL, 9, 'local:hafs-text.json'),
  ('hafs-2-59', 'hafs', 2, 59, 'فَبَدَّلَ ٱلَّذِينَ ظَلَمُوا۟ قَوْلًا غَيْرَ ٱلَّذِى قِيلَ لَهُمْ فَأَنزَلْنَا عَلَى ٱلَّذِينَ ظَلَمُوا۟ رِجْزًۭا مِّنَ ٱلسَّمَآءِ بِمَا كَانُوا۟ يَفْسُقُونَ', 'فبدل الذين ظلموا قولا غير الذى قيل لهم فأنزلنا على الذين ظلموا رجزا من السماء بما كانوا يفسقون', NULL, 9, 'local:hafs-text.json'),
  ('hafs-2-60', 'hafs', 2, 60, '۞ وَإِذِ ٱسْتَسْقَىٰ مُوسَىٰ لِقَوْمِهِۦ فَقُلْنَا ٱضْرِب بِّعَصَاكَ ٱلْحَجَرَ ۖ فَٱنفَجَرَتْ مِنْهُ ٱثْنَتَا عَشْرَةَ عَيْنًۭا ۖ قَدْ عَلِمَ كُلُّ أُنَاسٍۢ مَّشْرَبَهُمْ ۖ كُلُوا۟ وَٱشْرَبُوا۟ مِن رِّزْقِ ٱللَّهِ وَلَا تَعْثَوْا۟ فِى ٱلْأَرْضِ مُفْسِدِينَ', 'وإذ استسقى موسى لقومه فقلنا اضرب بعصاك الحجر  فانفجرت منه اثنتا عشرة عينا  قد علم كل أناس مشربهم  كلوا واشربوا من رزق الله ولا تعثوا فى الأرض مفسدين', NULL, 9, 'local:hafs-text.json'),
  ('hafs-2-61', 'hafs', 2, 61, 'وَإِذْ قُلْتُمْ يَٰمُوسَىٰ لَن نَّصْبِرَ عَلَىٰ طَعَامٍۢ وَٰحِدٍۢ فَٱدْعُ لَنَا رَبَّكَ يُخْرِجْ لَنَا مِمَّا تُنۢبِتُ ٱلْأَرْضُ مِنۢ بَقْلِهَا وَقِثَّآئِهَا وَفُومِهَا وَعَدَسِهَا وَبَصَلِهَا ۖ قَالَ أَتَسْتَبْدِلُونَ ٱلَّذِى هُوَ أَدْنَىٰ بِٱلَّذِى هُوَ خَيْرٌ ۚ ٱهْبِطُوا۟ مِصْرًۭا فَإِنَّ لَكُم مَّا سَأَلْتُمْ ۗ وَضُرِبَتْ عَلَيْهِمُ ٱلذِّلَّةُ وَٱلْمَسْكَنَةُ وَبَآءُو بِغَضَبٍۢ مِّنَ ٱللَّهِ ۗ ذَٰلِكَ بِأَنَّهُمْ كَانُوا۟ يَكْفُرُونَ بِـَٔايَٰتِ ٱللَّهِ وَيَقْتُلُونَ ٱلنَّبِيِّۦنَ بِغَيْرِ ٱلْحَقِّ ۗ ذَٰلِكَ بِمَا عَصَوا۟ وَّكَانُوا۟ يَعْتَدُونَ', 'وإذ قلتم يموسى لن نصبر على طعام وحد فادع لنا ربك يخرج لنا مما تنبت الأرض من بقلها وقثائها وفومها وعدسها وبصلها  قال أتستبدلون الذى هو أدنى بالذى هو خير  اهبطوا مصرا فإن لكم ما سألتم  وضربت عليهم الذلة والمسكنة وباءو بغضب من الله  ذلك بأنهم كانوا يكفرون بايت الله ويقتلون النبين بغير الحق  ذلك بما عصوا وكانوا يعتدون', NULL, 9, 'local:hafs-text.json'),
  ('hafs-2-62', 'hafs', 2, 62, 'إِنَّ ٱلَّذِينَ ءَامَنُوا۟ وَٱلَّذِينَ هَادُوا۟ وَٱلنَّصَٰرَىٰ وَٱلصَّٰبِـِٔينَ مَنْ ءَامَنَ بِٱللَّهِ وَٱلْيَوْمِ ٱلْءَاخِرِ وَعَمِلَ صَٰلِحًۭا فَلَهُمْ أَجْرُهُمْ عِندَ رَبِّهِمْ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ', 'إن الذين ءامنوا والذين هادوا والنصرى والصبين من ءامن بالله واليوم الءاخر وعمل صلحا فلهم أجرهم عند ربهم ولا خوف عليهم ولا هم يحزنون', NULL, 10, 'local:hafs-text.json'),
  ('hafs-2-63', 'hafs', 2, 63, 'وَإِذْ أَخَذْنَا مِيثَٰقَكُمْ وَرَفَعْنَا فَوْقَكُمُ ٱلطُّورَ خُذُوا۟ مَآ ءَاتَيْنَٰكُم بِقُوَّةٍۢ وَٱذْكُرُوا۟ مَا فِيهِ لَعَلَّكُمْ تَتَّقُونَ', 'وإذ أخذنا ميثقكم ورفعنا فوقكم الطور خذوا ما ءاتينكم بقوة واذكروا ما فيه لعلكم تتقون', NULL, 10, 'local:hafs-text.json'),
  ('hafs-2-64', 'hafs', 2, 64, 'ثُمَّ تَوَلَّيْتُم مِّنۢ بَعْدِ ذَٰلِكَ ۖ فَلَوْلَا فَضْلُ ٱللَّهِ عَلَيْكُمْ وَرَحْمَتُهُۥ لَكُنتُم مِّنَ ٱلْخَٰسِرِينَ', 'ثم توليتم من بعد ذلك  فلولا فضل الله عليكم ورحمته لكنتم من الخسرين', NULL, 10, 'local:hafs-text.json'),
  ('hafs-2-65', 'hafs', 2, 65, 'وَلَقَدْ عَلِمْتُمُ ٱلَّذِينَ ٱعْتَدَوْا۟ مِنكُمْ فِى ٱلسَّبْتِ فَقُلْنَا لَهُمْ كُونُوا۟ قِرَدَةً خَٰسِـِٔينَ', 'ولقد علمتم الذين اعتدوا منكم فى السبت فقلنا لهم كونوا قردة خسين', NULL, 10, 'local:hafs-text.json'),
  ('hafs-2-66', 'hafs', 2, 66, 'فَجَعَلْنَٰهَا نَكَٰلًۭا لِّمَا بَيْنَ يَدَيْهَا وَمَا خَلْفَهَا وَمَوْعِظَةًۭ لِّلْمُتَّقِينَ', 'فجعلنها نكلا لما بين يديها وما خلفها وموعظة للمتقين', NULL, 10, 'local:hafs-text.json'),
  ('hafs-2-67', 'hafs', 2, 67, 'وَإِذْ قَالَ مُوسَىٰ لِقَوْمِهِۦٓ إِنَّ ٱللَّهَ يَأْمُرُكُمْ أَن تَذْبَحُوا۟ بَقَرَةًۭ ۖ قَالُوٓا۟ أَتَتَّخِذُنَا هُزُوًۭا ۖ قَالَ أَعُوذُ بِٱللَّهِ أَنْ أَكُونَ مِنَ ٱلْجَٰهِلِينَ', 'وإذ قال موسى لقومه إن الله يأمركم أن تذبحوا بقرة  قالوا أتتخذنا هزوا  قال أعوذ بالله أن أكون من الجهلين', NULL, 10, 'local:hafs-text.json'),
  ('hafs-2-68', 'hafs', 2, 68, 'قَالُوا۟ ٱدْعُ لَنَا رَبَّكَ يُبَيِّن لَّنَا مَا هِىَ ۚ قَالَ إِنَّهُۥ يَقُولُ إِنَّهَا بَقَرَةٌۭ لَّا فَارِضٌۭ وَلَا بِكْرٌ عَوَانٌۢ بَيْنَ ذَٰلِكَ ۖ فَٱفْعَلُوا۟ مَا تُؤْمَرُونَ', 'قالوا ادع لنا ربك يبين لنا ما هى  قال إنه يقول إنها بقرة لا فارض ولا بكر عوان بين ذلك  فافعلوا ما تؤمرون', NULL, 10, 'local:hafs-text.json'),
  ('hafs-2-69', 'hafs', 2, 69, 'قَالُوا۟ ٱدْعُ لَنَا رَبَّكَ يُبَيِّن لَّنَا مَا لَوْنُهَا ۚ قَالَ إِنَّهُۥ يَقُولُ إِنَّهَا بَقَرَةٌۭ صَفْرَآءُ فَاقِعٌۭ لَّوْنُهَا تَسُرُّ ٱلنَّٰظِرِينَ', 'قالوا ادع لنا ربك يبين لنا ما لونها  قال إنه يقول إنها بقرة صفراء فاقع لونها تسر النظرين', NULL, 10, 'local:hafs-text.json'),
  ('hafs-2-70', 'hafs', 2, 70, 'قَالُوا۟ ٱدْعُ لَنَا رَبَّكَ يُبَيِّن لَّنَا مَا هِىَ إِنَّ ٱلْبَقَرَ تَشَٰبَهَ عَلَيْنَا وَإِنَّآ إِن شَآءَ ٱللَّهُ لَمُهْتَدُونَ', 'قالوا ادع لنا ربك يبين لنا ما هى إن البقر تشبه علينا وإنا إن شاء الله لمهتدون', NULL, 11, 'local:hafs-text.json'),
  ('hafs-2-71', 'hafs', 2, 71, 'قَالَ إِنَّهُۥ يَقُولُ إِنَّهَا بَقَرَةٌۭ لَّا ذَلُولٌۭ تُثِيرُ ٱلْأَرْضَ وَلَا تَسْقِى ٱلْحَرْثَ مُسَلَّمَةٌۭ لَّا شِيَةَ فِيهَا ۚ قَالُوا۟ ٱلْـَٰٔنَ جِئْتَ بِٱلْحَقِّ ۚ فَذَبَحُوهَا وَمَا كَادُوا۟ يَفْعَلُونَ', 'قال إنه يقول إنها بقرة لا ذلول تثير الأرض ولا تسقى الحرث مسلمة لا شية فيها  قالوا الن جئت بالحق  فذبحوها وما كادوا يفعلون', NULL, 11, 'local:hafs-text.json'),
  ('hafs-2-72', 'hafs', 2, 72, 'وَإِذْ قَتَلْتُمْ نَفْسًۭا فَٱدَّٰرَْٰٔتُمْ فِيهَا ۖ وَٱللَّهُ مُخْرِجٌۭ مَّا كُنتُمْ تَكْتُمُونَ', 'وإذ قتلتم نفسا فادرتم فيها  والله مخرج ما كنتم تكتمون', NULL, 11, 'local:hafs-text.json'),
  ('hafs-2-73', 'hafs', 2, 73, 'فَقُلْنَا ٱضْرِبُوهُ بِبَعْضِهَا ۚ كَذَٰلِكَ يُحْىِ ٱللَّهُ ٱلْمَوْتَىٰ وَيُرِيكُمْ ءَايَٰتِهِۦ لَعَلَّكُمْ تَعْقِلُونَ', 'فقلنا اضربوه ببعضها  كذلك يحى الله الموتى ويريكم ءايته لعلكم تعقلون', NULL, 11, 'local:hafs-text.json'),
  ('hafs-2-74', 'hafs', 2, 74, 'ثُمَّ قَسَتْ قُلُوبُكُم مِّنۢ بَعْدِ ذَٰلِكَ فَهِىَ كَٱلْحِجَارَةِ أَوْ أَشَدُّ قَسْوَةًۭ ۚ وَإِنَّ مِنَ ٱلْحِجَارَةِ لَمَا يَتَفَجَّرُ مِنْهُ ٱلْأَنْهَٰرُ ۚ وَإِنَّ مِنْهَا لَمَا يَشَّقَّقُ فَيَخْرُجُ مِنْهُ ٱلْمَآءُ ۚ وَإِنَّ مِنْهَا لَمَا يَهْبِطُ مِنْ خَشْيَةِ ٱللَّهِ ۗ وَمَا ٱللَّهُ بِغَٰفِلٍ عَمَّا تَعْمَلُونَ', 'ثم قست قلوبكم من بعد ذلك فهى كالحجارة أو أشد قسوة  وإن من الحجارة لما يتفجر منه الأنهر  وإن منها لما يشقق فيخرج منه الماء  وإن منها لما يهبط من خشية الله  وما الله بغفل عما تعملون', NULL, 11, 'local:hafs-text.json'),
  ('hafs-2-75', 'hafs', 2, 75, '۞ أَفَتَطْمَعُونَ أَن يُؤْمِنُوا۟ لَكُمْ وَقَدْ كَانَ فَرِيقٌۭ مِّنْهُمْ يَسْمَعُونَ كَلَٰمَ ٱللَّهِ ثُمَّ يُحَرِّفُونَهُۥ مِنۢ بَعْدِ مَا عَقَلُوهُ وَهُمْ يَعْلَمُونَ', 'أفتطمعون أن يؤمنوا لكم وقد كان فريق منهم يسمعون كلم الله ثم يحرفونه من بعد ما عقلوه وهم يعلمون', NULL, 11, 'local:hafs-text.json'),
  ('hafs-2-76', 'hafs', 2, 76, 'وَإِذَا لَقُوا۟ ٱلَّذِينَ ءَامَنُوا۟ قَالُوٓا۟ ءَامَنَّا وَإِذَا خَلَا بَعْضُهُمْ إِلَىٰ بَعْضٍۢ قَالُوٓا۟ أَتُحَدِّثُونَهُم بِمَا فَتَحَ ٱللَّهُ عَلَيْكُمْ لِيُحَآجُّوكُم بِهِۦ عِندَ رَبِّكُمْ ۚ أَفَلَا تَعْقِلُونَ', 'وإذا لقوا الذين ءامنوا قالوا ءامنا وإذا خلا بعضهم إلى بعض قالوا أتحدثونهم بما فتح الله عليكم ليحاجوكم به عند ربكم  أفلا تعقلون', NULL, 11, 'local:hafs-text.json'),
  ('hafs-2-77', 'hafs', 2, 77, 'أَوَلَا يَعْلَمُونَ أَنَّ ٱللَّهَ يَعْلَمُ مَا يُسِرُّونَ وَمَا يُعْلِنُونَ', 'أولا يعلمون أن الله يعلم ما يسرون وما يعلنون', NULL, 12, 'local:hafs-text.json'),
  ('hafs-2-78', 'hafs', 2, 78, 'وَمِنْهُمْ أُمِّيُّونَ لَا يَعْلَمُونَ ٱلْكِتَٰبَ إِلَّآ أَمَانِىَّ وَإِنْ هُمْ إِلَّا يَظُنُّونَ', 'ومنهم أميون لا يعلمون الكتب إلا أمانى وإن هم إلا يظنون', NULL, 12, 'local:hafs-text.json'),
  ('hafs-2-79', 'hafs', 2, 79, 'فَوَيْلٌۭ لِّلَّذِينَ يَكْتُبُونَ ٱلْكِتَٰبَ بِأَيْدِيهِمْ ثُمَّ يَقُولُونَ هَٰذَا مِنْ عِندِ ٱللَّهِ لِيَشْتَرُوا۟ بِهِۦ ثَمَنًۭا قَلِيلًۭا ۖ فَوَيْلٌۭ لَّهُم مِّمَّا كَتَبَتْ أَيْدِيهِمْ وَوَيْلٌۭ لَّهُم مِّمَّا يَكْسِبُونَ', 'فويل للذين يكتبون الكتب بأيديهم ثم يقولون هذا من عند الله ليشتروا به ثمنا قليلا  فويل لهم مما كتبت أيديهم وويل لهم مما يكسبون', NULL, 12, 'local:hafs-text.json'),
  ('hafs-2-80', 'hafs', 2, 80, 'وَقَالُوا۟ لَن تَمَسَّنَا ٱلنَّارُ إِلَّآ أَيَّامًۭا مَّعْدُودَةًۭ ۚ قُلْ أَتَّخَذْتُمْ عِندَ ٱللَّهِ عَهْدًۭا فَلَن يُخْلِفَ ٱللَّهُ عَهْدَهُۥٓ ۖ أَمْ تَقُولُونَ عَلَى ٱللَّهِ مَا لَا تَعْلَمُونَ', 'وقالوا لن تمسنا النار إلا أياما معدودة  قل أتخذتم عند الله عهدا فلن يخلف الله عهده  أم تقولون على الله ما لا تعلمون', NULL, 12, 'local:hafs-text.json'),
  ('hafs-2-81', 'hafs', 2, 81, 'بَلَىٰ مَن كَسَبَ سَيِّئَةًۭ وَأَحَٰطَتْ بِهِۦ خَطِيٓـَٔتُهُۥ فَأُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلنَّارِ ۖ هُمْ فِيهَا خَٰلِدُونَ', 'بلى من كسب سيئة وأحطت به خطيته فأولئك أصحب النار  هم فيها خلدون', NULL, 12, 'local:hafs-text.json'),
  ('hafs-2-82', 'hafs', 2, 82, 'وَٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ أُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلْجَنَّةِ ۖ هُمْ فِيهَا خَٰلِدُونَ', 'والذين ءامنوا وعملوا الصلحت أولئك أصحب الجنة  هم فيها خلدون', NULL, 12, 'local:hafs-text.json'),
  ('hafs-2-83', 'hafs', 2, 83, 'وَإِذْ أَخَذْنَا مِيثَٰقَ بَنِىٓ إِسْرَٰٓءِيلَ لَا تَعْبُدُونَ إِلَّا ٱللَّهَ وَبِٱلْوَٰلِدَيْنِ إِحْسَانًۭا وَذِى ٱلْقُرْبَىٰ وَٱلْيَتَٰمَىٰ وَٱلْمَسَٰكِينِ وَقُولُوا۟ لِلنَّاسِ حُسْنًۭا وَأَقِيمُوا۟ ٱلصَّلَوٰةَ وَءَاتُوا۟ ٱلزَّكَوٰةَ ثُمَّ تَوَلَّيْتُمْ إِلَّا قَلِيلًۭا مِّنكُمْ وَأَنتُم مُّعْرِضُونَ', 'وإذ أخذنا ميثق بنى إسرءيل لا تعبدون إلا الله وبالولدين إحسانا وذى القربى واليتمى والمسكين وقولوا للناس حسنا وأقيموا الصلوة وءاتوا الزكوة ثم توليتم إلا قليلا منكم وأنتم معرضون', NULL, 12, 'local:hafs-text.json'),
  ('hafs-2-84', 'hafs', 2, 84, 'وَإِذْ أَخَذْنَا مِيثَٰقَكُمْ لَا تَسْفِكُونَ دِمَآءَكُمْ وَلَا تُخْرِجُونَ أَنفُسَكُم مِّن دِيَٰرِكُمْ ثُمَّ أَقْرَرْتُمْ وَأَنتُمْ تَشْهَدُونَ', 'وإذ أخذنا ميثقكم لا تسفكون دماءكم ولا تخرجون أنفسكم من ديركم ثم أقررتم وأنتم تشهدون', NULL, 13, 'local:hafs-text.json'),
  ('hafs-2-85', 'hafs', 2, 85, 'ثُمَّ أَنتُمْ هَٰٓؤُلَآءِ تَقْتُلُونَ أَنفُسَكُمْ وَتُخْرِجُونَ فَرِيقًۭا مِّنكُم مِّن دِيَٰرِهِمْ تَظَٰهَرُونَ عَلَيْهِم بِٱلْإِثْمِ وَٱلْعُدْوَٰنِ وَإِن يَأْتُوكُمْ أُسَٰرَىٰ تُفَٰدُوهُمْ وَهُوَ مُحَرَّمٌ عَلَيْكُمْ إِخْرَاجُهُمْ ۚ أَفَتُؤْمِنُونَ بِبَعْضِ ٱلْكِتَٰبِ وَتَكْفُرُونَ بِبَعْضٍۢ ۚ فَمَا جَزَآءُ مَن يَفْعَلُ ذَٰلِكَ مِنكُمْ إِلَّا خِزْىٌۭ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا ۖ وَيَوْمَ ٱلْقِيَٰمَةِ يُرَدُّونَ إِلَىٰٓ أَشَدِّ ٱلْعَذَابِ ۗ وَمَا ٱللَّهُ بِغَٰفِلٍ عَمَّا تَعْمَلُونَ', 'ثم أنتم هؤلاء تقتلون أنفسكم وتخرجون فريقا منكم من ديرهم تظهرون عليهم بالإثم والعدون وإن يأتوكم أسرى تفدوهم وهو محرم عليكم إخراجهم  أفتؤمنون ببعض الكتب وتكفرون ببعض  فما جزاء من يفعل ذلك منكم إلا خزى فى الحيوة الدنيا  ويوم القيمة يردون إلى أشد العذاب  وما الله بغفل عما تعملون', NULL, 13, 'local:hafs-text.json'),
  ('hafs-2-86', 'hafs', 2, 86, 'أُو۟لَٰٓئِكَ ٱلَّذِينَ ٱشْتَرَوُا۟ ٱلْحَيَوٰةَ ٱلدُّنْيَا بِٱلْءَاخِرَةِ ۖ فَلَا يُخَفَّفُ عَنْهُمُ ٱلْعَذَابُ وَلَا هُمْ يُنصَرُونَ', 'أولئك الذين اشتروا الحيوة الدنيا بالءاخرة  فلا يخفف عنهم العذاب ولا هم ينصرون', NULL, 13, 'local:hafs-text.json'),
  ('hafs-2-87', 'hafs', 2, 87, 'وَلَقَدْ ءَاتَيْنَا مُوسَى ٱلْكِتَٰبَ وَقَفَّيْنَا مِنۢ بَعْدِهِۦ بِٱلرُّسُلِ ۖ وَءَاتَيْنَا عِيسَى ٱبْنَ مَرْيَمَ ٱلْبَيِّنَٰتِ وَأَيَّدْنَٰهُ بِرُوحِ ٱلْقُدُسِ ۗ أَفَكُلَّمَا جَآءَكُمْ رَسُولٌۢ بِمَا لَا تَهْوَىٰٓ أَنفُسُكُمُ ٱسْتَكْبَرْتُمْ فَفَرِيقًۭا كَذَّبْتُمْ وَفَرِيقًۭا تَقْتُلُونَ', 'ولقد ءاتينا موسى الكتب وقفينا من بعده بالرسل  وءاتينا عيسى ابن مريم البينت وأيدنه بروح القدس  أفكلما جاءكم رسول بما لا تهوى أنفسكم استكبرتم ففريقا كذبتم وفريقا تقتلون', NULL, 13, 'local:hafs-text.json'),
  ('hafs-2-88', 'hafs', 2, 88, 'وَقَالُوا۟ قُلُوبُنَا غُلْفٌۢ ۚ بَل لَّعَنَهُمُ ٱللَّهُ بِكُفْرِهِمْ فَقَلِيلًۭا مَّا يُؤْمِنُونَ', 'وقالوا قلوبنا غلف  بل لعنهم الله بكفرهم فقليلا ما يؤمنون', NULL, 13, 'local:hafs-text.json'),
  ('hafs-2-89', 'hafs', 2, 89, 'وَلَمَّا جَآءَهُمْ كِتَٰبٌۭ مِّنْ عِندِ ٱللَّهِ مُصَدِّقٌۭ لِّمَا مَعَهُمْ وَكَانُوا۟ مِن قَبْلُ يَسْتَفْتِحُونَ عَلَى ٱلَّذِينَ كَفَرُوا۟ فَلَمَّا جَآءَهُم مَّا عَرَفُوا۟ كَفَرُوا۟ بِهِۦ ۚ فَلَعْنَةُ ٱللَّهِ عَلَى ٱلْكَٰفِرِينَ', 'ولما جاءهم كتب من عند الله مصدق لما معهم وكانوا من قبل يستفتحون على الذين كفروا فلما جاءهم ما عرفوا كفروا به  فلعنة الله على الكفرين', NULL, 14, 'local:hafs-text.json'),
  ('hafs-2-90', 'hafs', 2, 90, 'بِئْسَمَا ٱشْتَرَوْا۟ بِهِۦٓ أَنفُسَهُمْ أَن يَكْفُرُوا۟ بِمَآ أَنزَلَ ٱللَّهُ بَغْيًا أَن يُنَزِّلَ ٱللَّهُ مِن فَضْلِهِۦ عَلَىٰ مَن يَشَآءُ مِنْ عِبَادِهِۦ ۖ فَبَآءُو بِغَضَبٍ عَلَىٰ غَضَبٍۢ ۚ وَلِلْكَٰفِرِينَ عَذَابٌۭ مُّهِينٌۭ', 'بئسما اشتروا به أنفسهم أن يكفروا بما أنزل الله بغيا أن ينزل الله من فضله على من يشاء من عباده  فباءو بغضب على غضب  وللكفرين عذاب مهين', NULL, 14, 'local:hafs-text.json'),
  ('hafs-2-91', 'hafs', 2, 91, 'وَإِذَا قِيلَ لَهُمْ ءَامِنُوا۟ بِمَآ أَنزَلَ ٱللَّهُ قَالُوا۟ نُؤْمِنُ بِمَآ أُنزِلَ عَلَيْنَا وَيَكْفُرُونَ بِمَا وَرَآءَهُۥ وَهُوَ ٱلْحَقُّ مُصَدِّقًۭا لِّمَا مَعَهُمْ ۗ قُلْ فَلِمَ تَقْتُلُونَ أَنۢبِيَآءَ ٱللَّهِ مِن قَبْلُ إِن كُنتُم مُّؤْمِنِينَ', 'وإذا قيل لهم ءامنوا بما أنزل الله قالوا نؤمن بما أنزل علينا ويكفرون بما وراءه وهو الحق مصدقا لما معهم  قل فلم تقتلون أنبياء الله من قبل إن كنتم مؤمنين', NULL, 14, 'local:hafs-text.json'),
  ('hafs-2-92', 'hafs', 2, 92, '۞ وَلَقَدْ جَآءَكُم مُّوسَىٰ بِٱلْبَيِّنَٰتِ ثُمَّ ٱتَّخَذْتُمُ ٱلْعِجْلَ مِنۢ بَعْدِهِۦ وَأَنتُمْ ظَٰلِمُونَ', 'ولقد جاءكم موسى بالبينت ثم اتخذتم العجل من بعده وأنتم ظلمون', NULL, 14, 'local:hafs-text.json'),
  ('hafs-2-93', 'hafs', 2, 93, 'وَإِذْ أَخَذْنَا مِيثَٰقَكُمْ وَرَفَعْنَا فَوْقَكُمُ ٱلطُّورَ خُذُوا۟ مَآ ءَاتَيْنَٰكُم بِقُوَّةٍۢ وَٱسْمَعُوا۟ ۖ قَالُوا۟ سَمِعْنَا وَعَصَيْنَا وَأُشْرِبُوا۟ فِى قُلُوبِهِمُ ٱلْعِجْلَ بِكُفْرِهِمْ ۚ قُلْ بِئْسَمَا يَأْمُرُكُم بِهِۦٓ إِيمَٰنُكُمْ إِن كُنتُم مُّؤْمِنِينَ', 'وإذ أخذنا ميثقكم ورفعنا فوقكم الطور خذوا ما ءاتينكم بقوة واسمعوا  قالوا سمعنا وعصينا وأشربوا فى قلوبهم العجل بكفرهم  قل بئسما يأمركم به إيمنكم إن كنتم مؤمنين', NULL, 14, 'local:hafs-text.json'),
  ('hafs-2-94', 'hafs', 2, 94, 'قُلْ إِن كَانَتْ لَكُمُ ٱلدَّارُ ٱلْءَاخِرَةُ عِندَ ٱللَّهِ خَالِصَةًۭ مِّن دُونِ ٱلنَّاسِ فَتَمَنَّوُا۟ ٱلْمَوْتَ إِن كُنتُمْ صَٰدِقِينَ', 'قل إن كانت لكم الدار الءاخرة عند الله خالصة من دون الناس فتمنوا الموت إن كنتم صدقين', NULL, 15, 'local:hafs-text.json'),
  ('hafs-2-95', 'hafs', 2, 95, 'وَلَن يَتَمَنَّوْهُ أَبَدًۢا بِمَا قَدَّمَتْ أَيْدِيهِمْ ۗ وَٱللَّهُ عَلِيمٌۢ بِٱلظَّٰلِمِينَ', 'ولن يتمنوه أبدا بما قدمت أيديهم  والله عليم بالظلمين', NULL, 15, 'local:hafs-text.json'),
  ('hafs-2-96', 'hafs', 2, 96, 'وَلَتَجِدَنَّهُمْ أَحْرَصَ ٱلنَّاسِ عَلَىٰ حَيَوٰةٍۢ وَمِنَ ٱلَّذِينَ أَشْرَكُوا۟ ۚ يَوَدُّ أَحَدُهُمْ لَوْ يُعَمَّرُ أَلْفَ سَنَةٍۢ وَمَا هُوَ بِمُزَحْزِحِهِۦ مِنَ ٱلْعَذَابِ أَن يُعَمَّرَ ۗ وَٱللَّهُ بَصِيرٌۢ بِمَا يَعْمَلُونَ', 'ولتجدنهم أحرص الناس على حيوة ومن الذين أشركوا  يود أحدهم لو يعمر ألف سنة وما هو بمزحزحه من العذاب أن يعمر  والله بصير بما يعملون', NULL, 15, 'local:hafs-text.json'),
  ('hafs-2-97', 'hafs', 2, 97, 'قُلْ مَن كَانَ عَدُوًّۭا لِّجِبْرِيلَ فَإِنَّهُۥ نَزَّلَهُۥ عَلَىٰ قَلْبِكَ بِإِذْنِ ٱللَّهِ مُصَدِّقًۭا لِّمَا بَيْنَ يَدَيْهِ وَهُدًۭى وَبُشْرَىٰ لِلْمُؤْمِنِينَ', 'قل من كان عدوا لجبريل فإنه نزله على قلبك بإذن الله مصدقا لما بين يديه وهدى وبشرى للمؤمنين', NULL, 15, 'local:hafs-text.json'),
  ('hafs-2-98', 'hafs', 2, 98, 'مَن كَانَ عَدُوًّۭا لِّلَّهِ وَمَلَٰٓئِكَتِهِۦ وَرُسُلِهِۦ وَجِبْرِيلَ وَمِيكَىٰلَ فَإِنَّ ٱللَّهَ عَدُوٌّۭ لِّلْكَٰفِرِينَ', 'من كان عدوا لله وملئكته ورسله وجبريل وميكىل فإن الله عدو للكفرين', NULL, 15, 'local:hafs-text.json'),
  ('hafs-2-99', 'hafs', 2, 99, 'وَلَقَدْ أَنزَلْنَآ إِلَيْكَ ءَايَٰتٍۭ بَيِّنَٰتٍۢ ۖ وَمَا يَكْفُرُ بِهَآ إِلَّا ٱلْفَٰسِقُونَ', 'ولقد أنزلنا إليك ءايت بينت  وما يكفر بها إلا الفسقون', NULL, 15, 'local:hafs-text.json'),
  ('hafs-2-100', 'hafs', 2, 100, 'أَوَكُلَّمَا عَٰهَدُوا۟ عَهْدًۭا نَّبَذَهُۥ فَرِيقٌۭ مِّنْهُم ۚ بَلْ أَكْثَرُهُمْ لَا يُؤْمِنُونَ', 'أوكلما عهدوا عهدا نبذه فريق منهم  بل أكثرهم لا يؤمنون', NULL, 15, 'local:hafs-text.json'),
  ('hafs-2-101', 'hafs', 2, 101, 'وَلَمَّا جَآءَهُمْ رَسُولٌۭ مِّنْ عِندِ ٱللَّهِ مُصَدِّقٌۭ لِّمَا مَعَهُمْ نَبَذَ فَرِيقٌۭ مِّنَ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَٰبَ كِتَٰبَ ٱللَّهِ وَرَآءَ ظُهُورِهِمْ كَأَنَّهُمْ لَا يَعْلَمُونَ', 'ولما جاءهم رسول من عند الله مصدق لما معهم نبذ فريق من الذين أوتوا الكتب كتب الله وراء ظهورهم كأنهم لا يعلمون', NULL, 15, 'local:hafs-text.json'),
  ('hafs-2-102', 'hafs', 2, 102, 'وَٱتَّبَعُوا۟ مَا تَتْلُوا۟ ٱلشَّيَٰطِينُ عَلَىٰ مُلْكِ سُلَيْمَٰنَ ۖ وَمَا كَفَرَ سُلَيْمَٰنُ وَلَٰكِنَّ ٱلشَّيَٰطِينَ كَفَرُوا۟ يُعَلِّمُونَ ٱلنَّاسَ ٱلسِّحْرَ وَمَآ أُنزِلَ عَلَى ٱلْمَلَكَيْنِ بِبَابِلَ هَٰرُوتَ وَمَٰرُوتَ ۚ وَمَا يُعَلِّمَانِ مِنْ أَحَدٍ حَتَّىٰ يَقُولَآ إِنَّمَا نَحْنُ فِتْنَةٌۭ فَلَا تَكْفُرْ ۖ فَيَتَعَلَّمُونَ مِنْهُمَا مَا يُفَرِّقُونَ بِهِۦ بَيْنَ ٱلْمَرْءِ وَزَوْجِهِۦ ۚ وَمَا هُم بِضَآرِّينَ بِهِۦ مِنْ أَحَدٍ إِلَّا بِإِذْنِ ٱللَّهِ ۚ وَيَتَعَلَّمُونَ مَا يَضُرُّهُمْ وَلَا يَنفَعُهُمْ ۚ وَلَقَدْ عَلِمُوا۟ لَمَنِ ٱشْتَرَىٰهُ مَا لَهُۥ فِى ٱلْءَاخِرَةِ مِنْ خَلَٰقٍۢ ۚ وَلَبِئْسَ مَا شَرَوْا۟ بِهِۦٓ أَنفُسَهُمْ ۚ لَوْ كَانُوا۟ يَعْلَمُونَ', 'واتبعوا ما تتلوا الشيطين على ملك سليمن  وما كفر سليمن ولكن الشيطين كفروا يعلمون الناس السحر وما أنزل على الملكين ببابل هروت ومروت  وما يعلمان من أحد حتى يقولا إنما نحن فتنة فلا تكفر  فيتعلمون منهما ما يفرقون به بين المرء وزوجه  وما هم بضارين به من أحد إلا بإذن الله  ويتعلمون ما يضرهم ولا ينفعهم  ولقد علموا لمن اشترىه ما له فى الءاخرة من خلق  ولبئس ما شروا به أنفسهم  لو كانوا يعلمون', NULL, 16, 'local:hafs-text.json'),
  ('hafs-2-103', 'hafs', 2, 103, 'وَلَوْ أَنَّهُمْ ءَامَنُوا۟ وَٱتَّقَوْا۟ لَمَثُوبَةٌۭ مِّنْ عِندِ ٱللَّهِ خَيْرٌۭ ۖ لَّوْ كَانُوا۟ يَعْلَمُونَ', 'ولو أنهم ءامنوا واتقوا لمثوبة من عند الله خير  لو كانوا يعلمون', NULL, 16, 'local:hafs-text.json'),
  ('hafs-2-104', 'hafs', 2, 104, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَقُولُوا۟ رَٰعِنَا وَقُولُوا۟ ٱنظُرْنَا وَٱسْمَعُوا۟ ۗ وَلِلْكَٰفِرِينَ عَذَابٌ أَلِيمٌۭ', 'يأيها الذين ءامنوا لا تقولوا رعنا وقولوا انظرنا واسمعوا  وللكفرين عذاب أليم', NULL, 16, 'local:hafs-text.json'),
  ('hafs-2-105', 'hafs', 2, 105, 'مَّا يَوَدُّ ٱلَّذِينَ كَفَرُوا۟ مِنْ أَهْلِ ٱلْكِتَٰبِ وَلَا ٱلْمُشْرِكِينَ أَن يُنَزَّلَ عَلَيْكُم مِّنْ خَيْرٍۢ مِّن رَّبِّكُمْ ۗ وَٱللَّهُ يَخْتَصُّ بِرَحْمَتِهِۦ مَن يَشَآءُ ۚ وَٱللَّهُ ذُو ٱلْفَضْلِ ٱلْعَظِيمِ', 'ما يود الذين كفروا من أهل الكتب ولا المشركين أن ينزل عليكم من خير من ربكم  والله يختص برحمته من يشاء  والله ذو الفضل العظيم', NULL, 16, 'local:hafs-text.json'),
  ('hafs-2-106', 'hafs', 2, 106, '۞ مَا نَنسَخْ مِنْ ءَايَةٍ أَوْ نُنسِهَا نَأْتِ بِخَيْرٍۢ مِّنْهَآ أَوْ مِثْلِهَآ ۗ أَلَمْ تَعْلَمْ أَنَّ ٱللَّهَ عَلَىٰ كُلِّ شَىْءٍۢ قَدِيرٌ', 'ما ننسخ من ءاية أو ننسها نأت بخير منها أو مثلها  ألم تعلم أن الله على كل شىء قدير', NULL, 17, 'local:hafs-text.json'),
  ('hafs-2-107', 'hafs', 2, 107, 'أَلَمْ تَعْلَمْ أَنَّ ٱللَّهَ لَهُۥ مُلْكُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ ۗ وَمَا لَكُم مِّن دُونِ ٱللَّهِ مِن وَلِىٍّۢ وَلَا نَصِيرٍ', 'ألم تعلم أن الله له ملك السموت والأرض  وما لكم من دون الله من ولى ولا نصير', NULL, 17, 'local:hafs-text.json'),
  ('hafs-2-108', 'hafs', 2, 108, 'أَمْ تُرِيدُونَ أَن تَسْـَٔلُوا۟ رَسُولَكُمْ كَمَا سُئِلَ مُوسَىٰ مِن قَبْلُ ۗ وَمَن يَتَبَدَّلِ ٱلْكُفْرَ بِٱلْإِيمَٰنِ فَقَدْ ضَلَّ سَوَآءَ ٱلسَّبِيلِ', 'أم تريدون أن تسلوا رسولكم كما سئل موسى من قبل  ومن يتبدل الكفر بالإيمن فقد ضل سواء السبيل', NULL, 17, 'local:hafs-text.json'),
  ('hafs-2-109', 'hafs', 2, 109, 'وَدَّ كَثِيرٌۭ مِّنْ أَهْلِ ٱلْكِتَٰبِ لَوْ يَرُدُّونَكُم مِّنۢ بَعْدِ إِيمَٰنِكُمْ كُفَّارًا حَسَدًۭا مِّنْ عِندِ أَنفُسِهِم مِّنۢ بَعْدِ مَا تَبَيَّنَ لَهُمُ ٱلْحَقُّ ۖ فَٱعْفُوا۟ وَٱصْفَحُوا۟ حَتَّىٰ يَأْتِىَ ٱللَّهُ بِأَمْرِهِۦٓ ۗ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَىْءٍۢ قَدِيرٌۭ', 'ود كثير من أهل الكتب لو يردونكم من بعد إيمنكم كفارا حسدا من عند أنفسهم من بعد ما تبين لهم الحق  فاعفوا واصفحوا حتى يأتى الله بأمره  إن الله على كل شىء قدير', NULL, 17, 'local:hafs-text.json'),
  ('hafs-2-110', 'hafs', 2, 110, 'وَأَقِيمُوا۟ ٱلصَّلَوٰةَ وَءَاتُوا۟ ٱلزَّكَوٰةَ ۚ وَمَا تُقَدِّمُوا۟ لِأَنفُسِكُم مِّنْ خَيْرٍۢ تَجِدُوهُ عِندَ ٱللَّهِ ۗ إِنَّ ٱللَّهَ بِمَا تَعْمَلُونَ بَصِيرٌۭ', 'وأقيموا الصلوة وءاتوا الزكوة  وما تقدموا لأنفسكم من خير تجدوه عند الله  إن الله بما تعملون بصير', NULL, 17, 'local:hafs-text.json'),
  ('hafs-2-111', 'hafs', 2, 111, 'وَقَالُوا۟ لَن يَدْخُلَ ٱلْجَنَّةَ إِلَّا مَن كَانَ هُودًا أَوْ نَصَٰرَىٰ ۗ تِلْكَ أَمَانِيُّهُمْ ۗ قُلْ هَاتُوا۟ بُرْهَٰنَكُمْ إِن كُنتُمْ صَٰدِقِينَ', 'وقالوا لن يدخل الجنة إلا من كان هودا أو نصرى  تلك أمانيهم  قل هاتوا برهنكم إن كنتم صدقين', NULL, 17, 'local:hafs-text.json'),
  ('hafs-2-112', 'hafs', 2, 112, 'بَلَىٰ مَنْ أَسْلَمَ وَجْهَهُۥ لِلَّهِ وَهُوَ مُحْسِنٌۭ فَلَهُۥٓ أَجْرُهُۥ عِندَ رَبِّهِۦ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ', 'بلى من أسلم وجهه لله وهو محسن فله أجره عند ربه ولا خوف عليهم ولا هم يحزنون', NULL, 17, 'local:hafs-text.json'),
  ('hafs-2-113', 'hafs', 2, 113, 'وَقَالَتِ ٱلْيَهُودُ لَيْسَتِ ٱلنَّصَٰرَىٰ عَلَىٰ شَىْءٍۢ وَقَالَتِ ٱلنَّصَٰرَىٰ لَيْسَتِ ٱلْيَهُودُ عَلَىٰ شَىْءٍۢ وَهُمْ يَتْلُونَ ٱلْكِتَٰبَ ۗ كَذَٰلِكَ قَالَ ٱلَّذِينَ لَا يَعْلَمُونَ مِثْلَ قَوْلِهِمْ ۚ فَٱللَّهُ يَحْكُمُ بَيْنَهُمْ يَوْمَ ٱلْقِيَٰمَةِ فِيمَا كَانُوا۟ فِيهِ يَخْتَلِفُونَ', 'وقالت اليهود ليست النصرى على شىء وقالت النصرى ليست اليهود على شىء وهم يتلون الكتب  كذلك قال الذين لا يعلمون مثل قولهم  فالله يحكم بينهم يوم القيمة فيما كانوا فيه يختلفون', NULL, 18, 'local:hafs-text.json'),
  ('hafs-2-114', 'hafs', 2, 114, 'وَمَنْ أَظْلَمُ مِمَّن مَّنَعَ مَسَٰجِدَ ٱللَّهِ أَن يُذْكَرَ فِيهَا ٱسْمُهُۥ وَسَعَىٰ فِى خَرَابِهَآ ۚ أُو۟لَٰٓئِكَ مَا كَانَ لَهُمْ أَن يَدْخُلُوهَآ إِلَّا خَآئِفِينَ ۚ لَهُمْ فِى ٱلدُّنْيَا خِزْىٌۭ وَلَهُمْ فِى ٱلْءَاخِرَةِ عَذَابٌ عَظِيمٌۭ', 'ومن أظلم ممن منع مسجد الله أن يذكر فيها اسمه وسعى فى خرابها  أولئك ما كان لهم أن يدخلوها إلا خائفين  لهم فى الدنيا خزى ولهم فى الءاخرة عذاب عظيم', NULL, 18, 'local:hafs-text.json'),
  ('hafs-2-115', 'hafs', 2, 115, 'وَلِلَّهِ ٱلْمَشْرِقُ وَٱلْمَغْرِبُ ۚ فَأَيْنَمَا تُوَلُّوا۟ فَثَمَّ وَجْهُ ٱللَّهِ ۚ إِنَّ ٱللَّهَ وَٰسِعٌ عَلِيمٌۭ', 'ولله المشرق والمغرب  فأينما تولوا فثم وجه الله  إن الله وسع عليم', NULL, 18, 'local:hafs-text.json'),
  ('hafs-2-116', 'hafs', 2, 116, 'وَقَالُوا۟ ٱتَّخَذَ ٱللَّهُ وَلَدًۭا ۗ سُبْحَٰنَهُۥ ۖ بَل لَّهُۥ مَا فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ ۖ كُلٌّۭ لَّهُۥ قَٰنِتُونَ', 'وقالوا اتخذ الله ولدا  سبحنه  بل له ما فى السموت والأرض  كل له قنتون', NULL, 18, 'local:hafs-text.json'),
  ('hafs-2-117', 'hafs', 2, 117, 'بَدِيعُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ ۖ وَإِذَا قَضَىٰٓ أَمْرًۭا فَإِنَّمَا يَقُولُ لَهُۥ كُن فَيَكُونُ', 'بديع السموت والأرض  وإذا قضى أمرا فإنما يقول له كن فيكون', NULL, 18, 'local:hafs-text.json'),
  ('hafs-2-118', 'hafs', 2, 118, 'وَقَالَ ٱلَّذِينَ لَا يَعْلَمُونَ لَوْلَا يُكَلِّمُنَا ٱللَّهُ أَوْ تَأْتِينَآ ءَايَةٌۭ ۗ كَذَٰلِكَ قَالَ ٱلَّذِينَ مِن قَبْلِهِم مِّثْلَ قَوْلِهِمْ ۘ تَشَٰبَهَتْ قُلُوبُهُمْ ۗ قَدْ بَيَّنَّا ٱلْءَايَٰتِ لِقَوْمٍۢ يُوقِنُونَ', 'وقال الذين لا يعلمون لولا يكلمنا الله أو تأتينا ءاية  كذلك قال الذين من قبلهم مثل قولهم  تشبهت قلوبهم  قد بينا الءايت لقوم يوقنون', NULL, 18, 'local:hafs-text.json'),
  ('hafs-2-119', 'hafs', 2, 119, 'إِنَّآ أَرْسَلْنَٰكَ بِٱلْحَقِّ بَشِيرًۭا وَنَذِيرًۭا ۖ وَلَا تُسْـَٔلُ عَنْ أَصْحَٰبِ ٱلْجَحِيمِ', 'إنا أرسلنك بالحق بشيرا ونذيرا  ولا تسل عن أصحب الجحيم', NULL, 18, 'local:hafs-text.json'),
  ('hafs-2-120', 'hafs', 2, 120, 'وَلَن تَرْضَىٰ عَنكَ ٱلْيَهُودُ وَلَا ٱلنَّصَٰرَىٰ حَتَّىٰ تَتَّبِعَ مِلَّتَهُمْ ۗ قُلْ إِنَّ هُدَى ٱللَّهِ هُوَ ٱلْهُدَىٰ ۗ وَلَئِنِ ٱتَّبَعْتَ أَهْوَآءَهُم بَعْدَ ٱلَّذِى جَآءَكَ مِنَ ٱلْعِلْمِ ۙ مَا لَكَ مِنَ ٱللَّهِ مِن وَلِىٍّۢ وَلَا نَصِيرٍ', 'ولن ترضى عنك اليهود ولا النصرى حتى تتبع ملتهم  قل إن هدى الله هو الهدى  ولئن اتبعت أهواءهم بعد الذى جاءك من العلم  ما لك من الله من ولى ولا نصير', NULL, 19, 'local:hafs-text.json'),
  ('hafs-2-121', 'hafs', 2, 121, 'ٱلَّذِينَ ءَاتَيْنَٰهُمُ ٱلْكِتَٰبَ يَتْلُونَهُۥ حَقَّ تِلَاوَتِهِۦٓ أُو۟لَٰٓئِكَ يُؤْمِنُونَ بِهِۦ ۗ وَمَن يَكْفُرْ بِهِۦ فَأُو۟لَٰٓئِكَ هُمُ ٱلْخَٰسِرُونَ', 'الذين ءاتينهم الكتب يتلونه حق تلاوته أولئك يؤمنون به  ومن يكفر به فأولئك هم الخسرون', NULL, 19, 'local:hafs-text.json'),
  ('hafs-2-122', 'hafs', 2, 122, 'يَٰبَنِىٓ إِسْرَٰٓءِيلَ ٱذْكُرُوا۟ نِعْمَتِىَ ٱلَّتِىٓ أَنْعَمْتُ عَلَيْكُمْ وَأَنِّى فَضَّلْتُكُمْ عَلَى ٱلْعَٰلَمِينَ', 'يبنى إسرءيل اذكروا نعمتى التى أنعمت عليكم وأنى فضلتكم على العلمين', NULL, 19, 'local:hafs-text.json'),
  ('hafs-2-123', 'hafs', 2, 123, 'وَٱتَّقُوا۟ يَوْمًۭا لَّا تَجْزِى نَفْسٌ عَن نَّفْسٍۢ شَيْـًۭٔا وَلَا يُقْبَلُ مِنْهَا عَدْلٌۭ وَلَا تَنفَعُهَا شَفَٰعَةٌۭ وَلَا هُمْ يُنصَرُونَ', 'واتقوا يوما لا تجزى نفس عن نفس شيا ولا يقبل منها عدل ولا تنفعها شفعة ولا هم ينصرون', NULL, 19, 'local:hafs-text.json'),
  ('hafs-2-124', 'hafs', 2, 124, '۞ وَإِذِ ٱبْتَلَىٰٓ إِبْرَٰهِۦمَ رَبُّهُۥ بِكَلِمَٰتٍۢ فَأَتَمَّهُنَّ ۖ قَالَ إِنِّى جَاعِلُكَ لِلنَّاسِ إِمَامًۭا ۖ قَالَ وَمِن ذُرِّيَّتِى ۖ قَالَ لَا يَنَالُ عَهْدِى ٱلظَّٰلِمِينَ', 'وإذ ابتلى إبرهم ربه بكلمت فأتمهن  قال إنى جاعلك للناس إماما  قال ومن ذريتى  قال لا ينال عهدى الظلمين', NULL, 19, 'local:hafs-text.json'),
  ('hafs-2-125', 'hafs', 2, 125, 'وَإِذْ جَعَلْنَا ٱلْبَيْتَ مَثَابَةًۭ لِّلنَّاسِ وَأَمْنًۭا وَٱتَّخِذُوا۟ مِن مَّقَامِ إِبْرَٰهِۦمَ مُصَلًّۭى ۖ وَعَهِدْنَآ إِلَىٰٓ إِبْرَٰهِۦمَ وَإِسْمَٰعِيلَ أَن طَهِّرَا بَيْتِىَ لِلطَّآئِفِينَ وَٱلْعَٰكِفِينَ وَٱلرُّكَّعِ ٱلسُّجُودِ', 'وإذ جعلنا البيت مثابة للناس وأمنا واتخذوا من مقام إبرهم مصلى  وعهدنا إلى إبرهم وإسمعيل أن طهرا بيتى للطائفين والعكفين والركع السجود', NULL, 19, 'local:hafs-text.json'),
  ('hafs-2-126', 'hafs', 2, 126, 'وَإِذْ قَالَ إِبْرَٰهِۦمُ رَبِّ ٱجْعَلْ هَٰذَا بَلَدًا ءَامِنًۭا وَٱرْزُقْ أَهْلَهُۥ مِنَ ٱلثَّمَرَٰتِ مَنْ ءَامَنَ مِنْهُم بِٱللَّهِ وَٱلْيَوْمِ ٱلْءَاخِرِ ۖ قَالَ وَمَن كَفَرَ فَأُمَتِّعُهُۥ قَلِيلًۭا ثُمَّ أَضْطَرُّهُۥٓ إِلَىٰ عَذَابِ ٱلنَّارِ ۖ وَبِئْسَ ٱلْمَصِيرُ', 'وإذ قال إبرهم رب اجعل هذا بلدا ءامنا وارزق أهله من الثمرت من ءامن منهم بالله واليوم الءاخر  قال ومن كفر فأمتعه قليلا ثم أضطره إلى عذاب النار  وبئس المصير', NULL, 19, 'local:hafs-text.json'),
  ('hafs-2-127', 'hafs', 2, 127, 'وَإِذْ يَرْفَعُ إِبْرَٰهِۦمُ ٱلْقَوَاعِدَ مِنَ ٱلْبَيْتِ وَإِسْمَٰعِيلُ رَبَّنَا تَقَبَّلْ مِنَّآ ۖ إِنَّكَ أَنتَ ٱلسَّمِيعُ ٱلْعَلِيمُ', 'وإذ يرفع إبرهم القواعد من البيت وإسمعيل ربنا تقبل منا  إنك أنت السميع العليم', NULL, 20, 'local:hafs-text.json'),
  ('hafs-2-128', 'hafs', 2, 128, 'رَبَّنَا وَٱجْعَلْنَا مُسْلِمَيْنِ لَكَ وَمِن ذُرِّيَّتِنَآ أُمَّةًۭ مُّسْلِمَةًۭ لَّكَ وَأَرِنَا مَنَاسِكَنَا وَتُبْ عَلَيْنَآ ۖ إِنَّكَ أَنتَ ٱلتَّوَّابُ ٱلرَّحِيمُ', 'ربنا واجعلنا مسلمين لك ومن ذريتنا أمة مسلمة لك وأرنا مناسكنا وتب علينا  إنك أنت التواب الرحيم', NULL, 20, 'local:hafs-text.json'),
  ('hafs-2-129', 'hafs', 2, 129, 'رَبَّنَا وَٱبْعَثْ فِيهِمْ رَسُولًۭا مِّنْهُمْ يَتْلُوا۟ عَلَيْهِمْ ءَايَٰتِكَ وَيُعَلِّمُهُمُ ٱلْكِتَٰبَ وَٱلْحِكْمَةَ وَيُزَكِّيهِمْ ۚ إِنَّكَ أَنتَ ٱلْعَزِيزُ ٱلْحَكِيمُ', 'ربنا وابعث فيهم رسولا منهم يتلوا عليهم ءايتك ويعلمهم الكتب والحكمة ويزكيهم  إنك أنت العزيز الحكيم', NULL, 20, 'local:hafs-text.json'),
  ('hafs-2-130', 'hafs', 2, 130, 'وَمَن يَرْغَبُ عَن مِّلَّةِ إِبْرَٰهِۦمَ إِلَّا مَن سَفِهَ نَفْسَهُۥ ۚ وَلَقَدِ ٱصْطَفَيْنَٰهُ فِى ٱلدُّنْيَا ۖ وَإِنَّهُۥ فِى ٱلْءَاخِرَةِ لَمِنَ ٱلصَّٰلِحِينَ', 'ومن يرغب عن ملة إبرهم إلا من سفه نفسه  ولقد اصطفينه فى الدنيا  وإنه فى الءاخرة لمن الصلحين', NULL, 20, 'local:hafs-text.json'),
  ('hafs-2-131', 'hafs', 2, 131, 'إِذْ قَالَ لَهُۥ رَبُّهُۥٓ أَسْلِمْ ۖ قَالَ أَسْلَمْتُ لِرَبِّ ٱلْعَٰلَمِينَ', 'إذ قال له ربه أسلم  قال أسلمت لرب العلمين', NULL, 20, 'local:hafs-text.json'),
  ('hafs-2-132', 'hafs', 2, 132, 'وَوَصَّىٰ بِهَآ إِبْرَٰهِۦمُ بَنِيهِ وَيَعْقُوبُ يَٰبَنِىَّ إِنَّ ٱللَّهَ ٱصْطَفَىٰ لَكُمُ ٱلدِّينَ فَلَا تَمُوتُنَّ إِلَّا وَأَنتُم مُّسْلِمُونَ', 'ووصى بها إبرهم بنيه ويعقوب يبنى إن الله اصطفى لكم الدين فلا تموتن إلا وأنتم مسلمون', NULL, 20, 'local:hafs-text.json'),
  ('hafs-2-133', 'hafs', 2, 133, 'أَمْ كُنتُمْ شُهَدَآءَ إِذْ حَضَرَ يَعْقُوبَ ٱلْمَوْتُ إِذْ قَالَ لِبَنِيهِ مَا تَعْبُدُونَ مِنۢ بَعْدِى قَالُوا۟ نَعْبُدُ إِلَٰهَكَ وَإِلَٰهَ ءَابَآئِكَ إِبْرَٰهِۦمَ وَإِسْمَٰعِيلَ وَإِسْحَٰقَ إِلَٰهًۭا وَٰحِدًۭا وَنَحْنُ لَهُۥ مُسْلِمُونَ', 'أم كنتم شهداء إذ حضر يعقوب الموت إذ قال لبنيه ما تعبدون من بعدى قالوا نعبد إلهك وإله ءابائك إبرهم وإسمعيل وإسحق إلها وحدا ونحن له مسلمون', NULL, 20, 'local:hafs-text.json'),
  ('hafs-2-134', 'hafs', 2, 134, 'تِلْكَ أُمَّةٌۭ قَدْ خَلَتْ ۖ لَهَا مَا كَسَبَتْ وَلَكُم مَّا كَسَبْتُمْ ۖ وَلَا تُسْـَٔلُونَ عَمَّا كَانُوا۟ يَعْمَلُونَ', 'تلك أمة قد خلت  لها ما كسبت ولكم ما كسبتم  ولا تسلون عما كانوا يعملون', NULL, 20, 'local:hafs-text.json'),
  ('hafs-2-135', 'hafs', 2, 135, 'وَقَالُوا۟ كُونُوا۟ هُودًا أَوْ نَصَٰرَىٰ تَهْتَدُوا۟ ۗ قُلْ بَلْ مِلَّةَ إِبْرَٰهِۦمَ حَنِيفًۭا ۖ وَمَا كَانَ مِنَ ٱلْمُشْرِكِينَ', 'وقالوا كونوا هودا أو نصرى تهتدوا  قل بل ملة إبرهم حنيفا  وما كان من المشركين', NULL, 21, 'local:hafs-text.json'),
  ('hafs-2-136', 'hafs', 2, 136, 'قُولُوٓا۟ ءَامَنَّا بِٱللَّهِ وَمَآ أُنزِلَ إِلَيْنَا وَمَآ أُنزِلَ إِلَىٰٓ إِبْرَٰهِۦمَ وَإِسْمَٰعِيلَ وَإِسْحَٰقَ وَيَعْقُوبَ وَٱلْأَسْبَاطِ وَمَآ أُوتِىَ مُوسَىٰ وَعِيسَىٰ وَمَآ أُوتِىَ ٱلنَّبِيُّونَ مِن رَّبِّهِمْ لَا نُفَرِّقُ بَيْنَ أَحَدٍۢ مِّنْهُمْ وَنَحْنُ لَهُۥ مُسْلِمُونَ', 'قولوا ءامنا بالله وما أنزل إلينا وما أنزل إلى إبرهم وإسمعيل وإسحق ويعقوب والأسباط وما أوتى موسى وعيسى وما أوتى النبيون من ربهم لا نفرق بين أحد منهم ونحن له مسلمون', NULL, 21, 'local:hafs-text.json'),
  ('hafs-2-137', 'hafs', 2, 137, 'فَإِنْ ءَامَنُوا۟ بِمِثْلِ مَآ ءَامَنتُم بِهِۦ فَقَدِ ٱهْتَدَوا۟ ۖ وَّإِن تَوَلَّوْا۟ فَإِنَّمَا هُمْ فِى شِقَاقٍۢ ۖ فَسَيَكْفِيكَهُمُ ٱللَّهُ ۚ وَهُوَ ٱلسَّمِيعُ ٱلْعَلِيمُ', 'فإن ءامنوا بمثل ما ءامنتم به فقد اهتدوا  وإن تولوا فإنما هم فى شقاق  فسيكفيكهم الله  وهو السميع العليم', NULL, 21, 'local:hafs-text.json'),
  ('hafs-2-138', 'hafs', 2, 138, 'صِبْغَةَ ٱللَّهِ ۖ وَمَنْ أَحْسَنُ مِنَ ٱللَّهِ صِبْغَةًۭ ۖ وَنَحْنُ لَهُۥ عَٰبِدُونَ', 'صبغة الله  ومن أحسن من الله صبغة  ونحن له عبدون', NULL, 21, 'local:hafs-text.json'),
  ('hafs-2-139', 'hafs', 2, 139, 'قُلْ أَتُحَآجُّونَنَا فِى ٱللَّهِ وَهُوَ رَبُّنَا وَرَبُّكُمْ وَلَنَآ أَعْمَٰلُنَا وَلَكُمْ أَعْمَٰلُكُمْ وَنَحْنُ لَهُۥ مُخْلِصُونَ', 'قل أتحاجوننا فى الله وهو ربنا وربكم ولنا أعملنا ولكم أعملكم ونحن له مخلصون', NULL, 21, 'local:hafs-text.json'),
  ('hafs-2-140', 'hafs', 2, 140, 'أَمْ تَقُولُونَ إِنَّ إِبْرَٰهِۦمَ وَإِسْمَٰعِيلَ وَإِسْحَٰقَ وَيَعْقُوبَ وَٱلْأَسْبَاطَ كَانُوا۟ هُودًا أَوْ نَصَٰرَىٰ ۗ قُلْ ءَأَنتُمْ أَعْلَمُ أَمِ ٱللَّهُ ۗ وَمَنْ أَظْلَمُ مِمَّن كَتَمَ شَهَٰدَةً عِندَهُۥ مِنَ ٱللَّهِ ۗ وَمَا ٱللَّهُ بِغَٰفِلٍ عَمَّا تَعْمَلُونَ', 'أم تقولون إن إبرهم وإسمعيل وإسحق ويعقوب والأسباط كانوا هودا أو نصرى  قل ءأنتم أعلم أم الله  ومن أظلم ممن كتم شهدة عنده من الله  وما الله بغفل عما تعملون', NULL, 21, 'local:hafs-text.json'),
  ('hafs-2-141', 'hafs', 2, 141, 'تِلْكَ أُمَّةٌۭ قَدْ خَلَتْ ۖ لَهَا مَا كَسَبَتْ وَلَكُم مَّا كَسَبْتُمْ ۖ وَلَا تُسْـَٔلُونَ عَمَّا كَانُوا۟ يَعْمَلُونَ', 'تلك أمة قد خلت  لها ما كسبت ولكم ما كسبتم  ولا تسلون عما كانوا يعملون', NULL, 21, 'local:hafs-text.json'),
  ('hafs-2-142', 'hafs', 2, 142, '۞ سَيَقُولُ ٱلسُّفَهَآءُ مِنَ ٱلنَّاسِ مَا وَلَّىٰهُمْ عَن قِبْلَتِهِمُ ٱلَّتِى كَانُوا۟ عَلَيْهَا ۚ قُل لِّلَّهِ ٱلْمَشْرِقُ وَٱلْمَغْرِبُ ۚ يَهْدِى مَن يَشَآءُ إِلَىٰ صِرَٰطٍۢ مُّسْتَقِيمٍۢ', 'سيقول السفهاء من الناس ما ولىهم عن قبلتهم التى كانوا عليها  قل لله المشرق والمغرب  يهدى من يشاء إلى صرط مستقيم', NULL, 22, 'local:hafs-text.json'),
  ('hafs-2-143', 'hafs', 2, 143, 'وَكَذَٰلِكَ جَعَلْنَٰكُمْ أُمَّةًۭ وَسَطًۭا لِّتَكُونُوا۟ شُهَدَآءَ عَلَى ٱلنَّاسِ وَيَكُونَ ٱلرَّسُولُ عَلَيْكُمْ شَهِيدًۭا ۗ وَمَا جَعَلْنَا ٱلْقِبْلَةَ ٱلَّتِى كُنتَ عَلَيْهَآ إِلَّا لِنَعْلَمَ مَن يَتَّبِعُ ٱلرَّسُولَ مِمَّن يَنقَلِبُ عَلَىٰ عَقِبَيْهِ ۚ وَإِن كَانَتْ لَكَبِيرَةً إِلَّا عَلَى ٱلَّذِينَ هَدَى ٱللَّهُ ۗ وَمَا كَانَ ٱللَّهُ لِيُضِيعَ إِيمَٰنَكُمْ ۚ إِنَّ ٱللَّهَ بِٱلنَّاسِ لَرَءُوفٌۭ رَّحِيمٌۭ', 'وكذلك جعلنكم أمة وسطا لتكونوا شهداء على الناس ويكون الرسول عليكم شهيدا  وما جعلنا القبلة التى كنت عليها إلا لنعلم من يتبع الرسول ممن ينقلب على عقبيه  وإن كانت لكبيرة إلا على الذين هدى الله  وما كان الله ليضيع إيمنكم  إن الله بالناس لرءوف رحيم', NULL, 22, 'local:hafs-text.json'),
  ('hafs-2-144', 'hafs', 2, 144, 'قَدْ نَرَىٰ تَقَلُّبَ وَجْهِكَ فِى ٱلسَّمَآءِ ۖ فَلَنُوَلِّيَنَّكَ قِبْلَةًۭ تَرْضَىٰهَا ۚ فَوَلِّ وَجْهَكَ شَطْرَ ٱلْمَسْجِدِ ٱلْحَرَامِ ۚ وَحَيْثُ مَا كُنتُمْ فَوَلُّوا۟ وُجُوهَكُمْ شَطْرَهُۥ ۗ وَإِنَّ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَٰبَ لَيَعْلَمُونَ أَنَّهُ ٱلْحَقُّ مِن رَّبِّهِمْ ۗ وَمَا ٱللَّهُ بِغَٰفِلٍ عَمَّا يَعْمَلُونَ', 'قد نرى تقلب وجهك فى السماء  فلنولينك قبلة ترضىها  فول وجهك شطر المسجد الحرام  وحيث ما كنتم فولوا وجوهكم شطره  وإن الذين أوتوا الكتب ليعلمون أنه الحق من ربهم  وما الله بغفل عما يعملون', NULL, 22, 'local:hafs-text.json'),
  ('hafs-2-145', 'hafs', 2, 145, 'وَلَئِنْ أَتَيْتَ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَٰبَ بِكُلِّ ءَايَةٍۢ مَّا تَبِعُوا۟ قِبْلَتَكَ ۚ وَمَآ أَنتَ بِتَابِعٍۢ قِبْلَتَهُمْ ۚ وَمَا بَعْضُهُم بِتَابِعٍۢ قِبْلَةَ بَعْضٍۢ ۚ وَلَئِنِ ٱتَّبَعْتَ أَهْوَآءَهُم مِّنۢ بَعْدِ مَا جَآءَكَ مِنَ ٱلْعِلْمِ ۙ إِنَّكَ إِذًۭا لَّمِنَ ٱلظَّٰلِمِينَ', 'ولئن أتيت الذين أوتوا الكتب بكل ءاية ما تبعوا قبلتك  وما أنت بتابع قبلتهم  وما بعضهم بتابع قبلة بعض  ولئن اتبعت أهواءهم من بعد ما جاءك من العلم  إنك إذا لمن الظلمين', NULL, 22, 'local:hafs-text.json'),
  ('hafs-2-146', 'hafs', 2, 146, 'ٱلَّذِينَ ءَاتَيْنَٰهُمُ ٱلْكِتَٰبَ يَعْرِفُونَهُۥ كَمَا يَعْرِفُونَ أَبْنَآءَهُمْ ۖ وَإِنَّ فَرِيقًۭا مِّنْهُمْ لَيَكْتُمُونَ ٱلْحَقَّ وَهُمْ يَعْلَمُونَ', 'الذين ءاتينهم الكتب يعرفونه كما يعرفون أبناءهم  وإن فريقا منهم ليكتمون الحق وهم يعلمون', NULL, 23, 'local:hafs-text.json'),
  ('hafs-2-147', 'hafs', 2, 147, 'ٱلْحَقُّ مِن رَّبِّكَ ۖ فَلَا تَكُونَنَّ مِنَ ٱلْمُمْتَرِينَ', 'الحق من ربك  فلا تكونن من الممترين', NULL, 23, 'local:hafs-text.json'),
  ('hafs-2-148', 'hafs', 2, 148, 'وَلِكُلٍّۢ وِجْهَةٌ هُوَ مُوَلِّيهَا ۖ فَٱسْتَبِقُوا۟ ٱلْخَيْرَٰتِ ۚ أَيْنَ مَا تَكُونُوا۟ يَأْتِ بِكُمُ ٱللَّهُ جَمِيعًا ۚ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَىْءٍۢ قَدِيرٌۭ', 'ولكل وجهة هو موليها  فاستبقوا الخيرت  أين ما تكونوا يأت بكم الله جميعا  إن الله على كل شىء قدير', NULL, 23, 'local:hafs-text.json'),
  ('hafs-2-149', 'hafs', 2, 149, 'وَمِنْ حَيْثُ خَرَجْتَ فَوَلِّ وَجْهَكَ شَطْرَ ٱلْمَسْجِدِ ٱلْحَرَامِ ۖ وَإِنَّهُۥ لَلْحَقُّ مِن رَّبِّكَ ۗ وَمَا ٱللَّهُ بِغَٰفِلٍ عَمَّا تَعْمَلُونَ', 'ومن حيث خرجت فول وجهك شطر المسجد الحرام  وإنه للحق من ربك  وما الله بغفل عما تعملون', NULL, 23, 'local:hafs-text.json'),
  ('hafs-2-150', 'hafs', 2, 150, 'وَمِنْ حَيْثُ خَرَجْتَ فَوَلِّ وَجْهَكَ شَطْرَ ٱلْمَسْجِدِ ٱلْحَرَامِ ۚ وَحَيْثُ مَا كُنتُمْ فَوَلُّوا۟ وُجُوهَكُمْ شَطْرَهُۥ لِئَلَّا يَكُونَ لِلنَّاسِ عَلَيْكُمْ حُجَّةٌ إِلَّا ٱلَّذِينَ ظَلَمُوا۟ مِنْهُمْ فَلَا تَخْشَوْهُمْ وَٱخْشَوْنِى وَلِأُتِمَّ نِعْمَتِى عَلَيْكُمْ وَلَعَلَّكُمْ تَهْتَدُونَ', 'ومن حيث خرجت فول وجهك شطر المسجد الحرام  وحيث ما كنتم فولوا وجوهكم شطره لئلا يكون للناس عليكم حجة إلا الذين ظلموا منهم فلا تخشوهم واخشونى ولأتم نعمتى عليكم ولعلكم تهتدون', NULL, 23, 'local:hafs-text.json'),
  ('hafs-2-151', 'hafs', 2, 151, 'كَمَآ أَرْسَلْنَا فِيكُمْ رَسُولًۭا مِّنكُمْ يَتْلُوا۟ عَلَيْكُمْ ءَايَٰتِنَا وَيُزَكِّيكُمْ وَيُعَلِّمُكُمُ ٱلْكِتَٰبَ وَٱلْحِكْمَةَ وَيُعَلِّمُكُم مَّا لَمْ تَكُونُوا۟ تَعْلَمُونَ', 'كما أرسلنا فيكم رسولا منكم يتلوا عليكم ءايتنا ويزكيكم ويعلمكم الكتب والحكمة ويعلمكم ما لم تكونوا تعلمون', NULL, 23, 'local:hafs-text.json'),
  ('hafs-2-152', 'hafs', 2, 152, 'فَٱذْكُرُونِىٓ أَذْكُرْكُمْ وَٱشْكُرُوا۟ لِى وَلَا تَكْفُرُونِ', 'فاذكرونى أذكركم واشكروا لى ولا تكفرون', NULL, 23, 'local:hafs-text.json'),
  ('hafs-2-153', 'hafs', 2, 153, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱسْتَعِينُوا۟ بِٱلصَّبْرِ وَٱلصَّلَوٰةِ ۚ إِنَّ ٱللَّهَ مَعَ ٱلصَّٰبِرِينَ', 'يأيها الذين ءامنوا استعينوا بالصبر والصلوة  إن الله مع الصبرين', NULL, 23, 'local:hafs-text.json'),
  ('hafs-2-154', 'hafs', 2, 154, 'وَلَا تَقُولُوا۟ لِمَن يُقْتَلُ فِى سَبِيلِ ٱللَّهِ أَمْوَٰتٌۢ ۚ بَلْ أَحْيَآءٌۭ وَلَٰكِن لَّا تَشْعُرُونَ', 'ولا تقولوا لمن يقتل فى سبيل الله أموت  بل أحياء ولكن لا تشعرون', NULL, 24, 'local:hafs-text.json'),
  ('hafs-2-155', 'hafs', 2, 155, 'وَلَنَبْلُوَنَّكُم بِشَىْءٍۢ مِّنَ ٱلْخَوْفِ وَٱلْجُوعِ وَنَقْصٍۢ مِّنَ ٱلْأَمْوَٰلِ وَٱلْأَنفُسِ وَٱلثَّمَرَٰتِ ۗ وَبَشِّرِ ٱلصَّٰبِرِينَ', 'ولنبلونكم بشىء من الخوف والجوع ونقص من الأمول والأنفس والثمرت  وبشر الصبرين', NULL, 24, 'local:hafs-text.json'),
  ('hafs-2-156', 'hafs', 2, 156, 'ٱلَّذِينَ إِذَآ أَصَٰبَتْهُم مُّصِيبَةٌۭ قَالُوٓا۟ إِنَّا لِلَّهِ وَإِنَّآ إِلَيْهِ رَٰجِعُونَ', 'الذين إذا أصبتهم مصيبة قالوا إنا لله وإنا إليه رجعون', NULL, 24, 'local:hafs-text.json'),
  ('hafs-2-157', 'hafs', 2, 157, 'أُو۟لَٰٓئِكَ عَلَيْهِمْ صَلَوَٰتٌۭ مِّن رَّبِّهِمْ وَرَحْمَةٌۭ ۖ وَأُو۟لَٰٓئِكَ هُمُ ٱلْمُهْتَدُونَ', 'أولئك عليهم صلوت من ربهم ورحمة  وأولئك هم المهتدون', NULL, 24, 'local:hafs-text.json'),
  ('hafs-2-158', 'hafs', 2, 158, '۞ إِنَّ ٱلصَّفَا وَٱلْمَرْوَةَ مِن شَعَآئِرِ ٱللَّهِ ۖ فَمَنْ حَجَّ ٱلْبَيْتَ أَوِ ٱعْتَمَرَ فَلَا جُنَاحَ عَلَيْهِ أَن يَطَّوَّفَ بِهِمَا ۚ وَمَن تَطَوَّعَ خَيْرًۭا فَإِنَّ ٱللَّهَ شَاكِرٌ عَلِيمٌ', 'إن الصفا والمروة من شعائر الله  فمن حج البيت أو اعتمر فلا جناح عليه أن يطوف بهما  ومن تطوع خيرا فإن الله شاكر عليم', NULL, 24, 'local:hafs-text.json'),
  ('hafs-2-159', 'hafs', 2, 159, 'إِنَّ ٱلَّذِينَ يَكْتُمُونَ مَآ أَنزَلْنَا مِنَ ٱلْبَيِّنَٰتِ وَٱلْهُدَىٰ مِنۢ بَعْدِ مَا بَيَّنَّٰهُ لِلنَّاسِ فِى ٱلْكِتَٰبِ ۙ أُو۟لَٰٓئِكَ يَلْعَنُهُمُ ٱللَّهُ وَيَلْعَنُهُمُ ٱللَّٰعِنُونَ', 'إن الذين يكتمون ما أنزلنا من البينت والهدى من بعد ما بينه للناس فى الكتب  أولئك يلعنهم الله ويلعنهم اللعنون', NULL, 24, 'local:hafs-text.json'),
  ('hafs-2-160', 'hafs', 2, 160, 'إِلَّا ٱلَّذِينَ تَابُوا۟ وَأَصْلَحُوا۟ وَبَيَّنُوا۟ فَأُو۟لَٰٓئِكَ أَتُوبُ عَلَيْهِمْ ۚ وَأَنَا ٱلتَّوَّابُ ٱلرَّحِيمُ', 'إلا الذين تابوا وأصلحوا وبينوا فأولئك أتوب عليهم  وأنا التواب الرحيم', NULL, 24, 'local:hafs-text.json'),
  ('hafs-2-161', 'hafs', 2, 161, 'إِنَّ ٱلَّذِينَ كَفَرُوا۟ وَمَاتُوا۟ وَهُمْ كُفَّارٌ أُو۟لَٰٓئِكَ عَلَيْهِمْ لَعْنَةُ ٱللَّهِ وَٱلْمَلَٰٓئِكَةِ وَٱلنَّاسِ أَجْمَعِينَ', 'إن الذين كفروا وماتوا وهم كفار أولئك عليهم لعنة الله والملئكة والناس أجمعين', NULL, 24, 'local:hafs-text.json'),
  ('hafs-2-162', 'hafs', 2, 162, 'خَٰلِدِينَ فِيهَا ۖ لَا يُخَفَّفُ عَنْهُمُ ٱلْعَذَابُ وَلَا هُمْ يُنظَرُونَ', 'خلدين فيها  لا يخفف عنهم العذاب ولا هم ينظرون', NULL, 24, 'local:hafs-text.json'),
  ('hafs-2-163', 'hafs', 2, 163, 'وَإِلَٰهُكُمْ إِلَٰهٌۭ وَٰحِدٌۭ ۖ لَّآ إِلَٰهَ إِلَّا هُوَ ٱلرَّحْمَٰنُ ٱلرَّحِيمُ', 'وإلهكم إله وحد  لا إله إلا هو الرحمن الرحيم', NULL, 24, 'local:hafs-text.json'),
  ('hafs-2-164', 'hafs', 2, 164, 'إِنَّ فِى خَلْقِ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَٱخْتِلَٰفِ ٱلَّيْلِ وَٱلنَّهَارِ وَٱلْفُلْكِ ٱلَّتِى تَجْرِى فِى ٱلْبَحْرِ بِمَا يَنفَعُ ٱلنَّاسَ وَمَآ أَنزَلَ ٱللَّهُ مِنَ ٱلسَّمَآءِ مِن مَّآءٍۢ فَأَحْيَا بِهِ ٱلْأَرْضَ بَعْدَ مَوْتِهَا وَبَثَّ فِيهَا مِن كُلِّ دَآبَّةٍۢ وَتَصْرِيفِ ٱلرِّيَٰحِ وَٱلسَّحَابِ ٱلْمُسَخَّرِ بَيْنَ ٱلسَّمَآءِ وَٱلْأَرْضِ لَءَايَٰتٍۢ لِّقَوْمٍۢ يَعْقِلُونَ', 'إن فى خلق السموت والأرض واختلف اليل والنهار والفلك التى تجرى فى البحر بما ينفع الناس وما أنزل الله من السماء من ماء فأحيا به الأرض بعد موتها وبث فيها من كل دابة وتصريف الريح والسحاب المسخر بين السماء والأرض لءايت لقوم يعقلون', NULL, 25, 'local:hafs-text.json'),
  ('hafs-2-165', 'hafs', 2, 165, 'وَمِنَ ٱلنَّاسِ مَن يَتَّخِذُ مِن دُونِ ٱللَّهِ أَندَادًۭا يُحِبُّونَهُمْ كَحُبِّ ٱللَّهِ ۖ وَٱلَّذِينَ ءَامَنُوٓا۟ أَشَدُّ حُبًّۭا لِّلَّهِ ۗ وَلَوْ يَرَى ٱلَّذِينَ ظَلَمُوٓا۟ إِذْ يَرَوْنَ ٱلْعَذَابَ أَنَّ ٱلْقُوَّةَ لِلَّهِ جَمِيعًۭا وَأَنَّ ٱللَّهَ شَدِيدُ ٱلْعَذَابِ', 'ومن الناس من يتخذ من دون الله أندادا يحبونهم كحب الله  والذين ءامنوا أشد حبا لله  ولو يرى الذين ظلموا إذ يرون العذاب أن القوة لله جميعا وأن الله شديد العذاب', NULL, 25, 'local:hafs-text.json'),
  ('hafs-2-166', 'hafs', 2, 166, 'إِذْ تَبَرَّأَ ٱلَّذِينَ ٱتُّبِعُوا۟ مِنَ ٱلَّذِينَ ٱتَّبَعُوا۟ وَرَأَوُا۟ ٱلْعَذَابَ وَتَقَطَّعَتْ بِهِمُ ٱلْأَسْبَابُ', 'إذ تبرأ الذين اتبعوا من الذين اتبعوا ورأوا العذاب وتقطعت بهم الأسباب', NULL, 25, 'local:hafs-text.json'),
  ('hafs-2-167', 'hafs', 2, 167, 'وَقَالَ ٱلَّذِينَ ٱتَّبَعُوا۟ لَوْ أَنَّ لَنَا كَرَّةًۭ فَنَتَبَرَّأَ مِنْهُمْ كَمَا تَبَرَّءُوا۟ مِنَّا ۗ كَذَٰلِكَ يُرِيهِمُ ٱللَّهُ أَعْمَٰلَهُمْ حَسَرَٰتٍ عَلَيْهِمْ ۖ وَمَا هُم بِخَٰرِجِينَ مِنَ ٱلنَّارِ', 'وقال الذين اتبعوا لو أن لنا كرة فنتبرأ منهم كما تبرءوا منا  كذلك يريهم الله أعملهم حسرت عليهم  وما هم بخرجين من النار', NULL, 25, 'local:hafs-text.json'),
  ('hafs-2-168', 'hafs', 2, 168, 'يَٰٓأَيُّهَا ٱلنَّاسُ كُلُوا۟ مِمَّا فِى ٱلْأَرْضِ حَلَٰلًۭا طَيِّبًۭا وَلَا تَتَّبِعُوا۟ خُطُوَٰتِ ٱلشَّيْطَٰنِ ۚ إِنَّهُۥ لَكُمْ عَدُوٌّۭ مُّبِينٌ', 'يأيها الناس كلوا مما فى الأرض حللا طيبا ولا تتبعوا خطوت الشيطن  إنه لكم عدو مبين', NULL, 25, 'local:hafs-text.json'),
  ('hafs-2-169', 'hafs', 2, 169, 'إِنَّمَا يَأْمُرُكُم بِٱلسُّوٓءِ وَٱلْفَحْشَآءِ وَأَن تَقُولُوا۟ عَلَى ٱللَّهِ مَا لَا تَعْلَمُونَ', 'إنما يأمركم بالسوء والفحشاء وأن تقولوا على الله ما لا تعلمون', NULL, 25, 'local:hafs-text.json'),
  ('hafs-2-170', 'hafs', 2, 170, 'وَإِذَا قِيلَ لَهُمُ ٱتَّبِعُوا۟ مَآ أَنزَلَ ٱللَّهُ قَالُوا۟ بَلْ نَتَّبِعُ مَآ أَلْفَيْنَا عَلَيْهِ ءَابَآءَنَآ ۗ أَوَلَوْ كَانَ ءَابَآؤُهُمْ لَا يَعْقِلُونَ شَيْـًۭٔا وَلَا يَهْتَدُونَ', 'وإذا قيل لهم اتبعوا ما أنزل الله قالوا بل نتبع ما ألفينا عليه ءاباءنا  أولو كان ءاباؤهم لا يعقلون شيا ولا يهتدون', NULL, 26, 'local:hafs-text.json'),
  ('hafs-2-171', 'hafs', 2, 171, 'وَمَثَلُ ٱلَّذِينَ كَفَرُوا۟ كَمَثَلِ ٱلَّذِى يَنْعِقُ بِمَا لَا يَسْمَعُ إِلَّا دُعَآءًۭ وَنِدَآءًۭ ۚ صُمٌّۢ بُكْمٌ عُمْىٌۭ فَهُمْ لَا يَعْقِلُونَ', 'ومثل الذين كفروا كمثل الذى ينعق بما لا يسمع إلا دعاء ونداء  صم بكم عمى فهم لا يعقلون', NULL, 26, 'local:hafs-text.json'),
  ('hafs-2-172', 'hafs', 2, 172, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ كُلُوا۟ مِن طَيِّبَٰتِ مَا رَزَقْنَٰكُمْ وَٱشْكُرُوا۟ لِلَّهِ إِن كُنتُمْ إِيَّاهُ تَعْبُدُونَ', 'يأيها الذين ءامنوا كلوا من طيبت ما رزقنكم واشكروا لله إن كنتم إياه تعبدون', NULL, 26, 'local:hafs-text.json'),
  ('hafs-2-173', 'hafs', 2, 173, 'إِنَّمَا حَرَّمَ عَلَيْكُمُ ٱلْمَيْتَةَ وَٱلدَّمَ وَلَحْمَ ٱلْخِنزِيرِ وَمَآ أُهِلَّ بِهِۦ لِغَيْرِ ٱللَّهِ ۖ فَمَنِ ٱضْطُرَّ غَيْرَ بَاغٍۢ وَلَا عَادٍۢ فَلَآ إِثْمَ عَلَيْهِ ۚ إِنَّ ٱللَّهَ غَفُورٌۭ رَّحِيمٌ', 'إنما حرم عليكم الميتة والدم ولحم الخنزير وما أهل به لغير الله  فمن اضطر غير باغ ولا عاد فلا إثم عليه  إن الله غفور رحيم', NULL, 26, 'local:hafs-text.json'),
  ('hafs-2-174', 'hafs', 2, 174, 'إِنَّ ٱلَّذِينَ يَكْتُمُونَ مَآ أَنزَلَ ٱللَّهُ مِنَ ٱلْكِتَٰبِ وَيَشْتَرُونَ بِهِۦ ثَمَنًۭا قَلِيلًا ۙ أُو۟لَٰٓئِكَ مَا يَأْكُلُونَ فِى بُطُونِهِمْ إِلَّا ٱلنَّارَ وَلَا يُكَلِّمُهُمُ ٱللَّهُ يَوْمَ ٱلْقِيَٰمَةِ وَلَا يُزَكِّيهِمْ وَلَهُمْ عَذَابٌ أَلِيمٌ', 'إن الذين يكتمون ما أنزل الله من الكتب ويشترون به ثمنا قليلا  أولئك ما يأكلون فى بطونهم إلا النار ولا يكلمهم الله يوم القيمة ولا يزكيهم ولهم عذاب أليم', NULL, 26, 'local:hafs-text.json'),
  ('hafs-2-175', 'hafs', 2, 175, 'أُو۟لَٰٓئِكَ ٱلَّذِينَ ٱشْتَرَوُا۟ ٱلضَّلَٰلَةَ بِٱلْهُدَىٰ وَٱلْعَذَابَ بِٱلْمَغْفِرَةِ ۚ فَمَآ أَصْبَرَهُمْ عَلَى ٱلنَّارِ', 'أولئك الذين اشتروا الضللة بالهدى والعذاب بالمغفرة  فما أصبرهم على النار', NULL, 26, 'local:hafs-text.json'),
  ('hafs-2-176', 'hafs', 2, 176, 'ذَٰلِكَ بِأَنَّ ٱللَّهَ نَزَّلَ ٱلْكِتَٰبَ بِٱلْحَقِّ ۗ وَإِنَّ ٱلَّذِينَ ٱخْتَلَفُوا۟ فِى ٱلْكِتَٰبِ لَفِى شِقَاقٍۭ بَعِيدٍۢ', 'ذلك بأن الله نزل الكتب بالحق  وإن الذين اختلفوا فى الكتب لفى شقاق بعيد', NULL, 26, 'local:hafs-text.json'),
  ('hafs-2-177', 'hafs', 2, 177, '۞ لَّيْسَ ٱلْبِرَّ أَن تُوَلُّوا۟ وُجُوهَكُمْ قِبَلَ ٱلْمَشْرِقِ وَٱلْمَغْرِبِ وَلَٰكِنَّ ٱلْبِرَّ مَنْ ءَامَنَ بِٱللَّهِ وَٱلْيَوْمِ ٱلْءَاخِرِ وَٱلْمَلَٰٓئِكَةِ وَٱلْكِتَٰبِ وَٱلنَّبِيِّۦنَ وَءَاتَى ٱلْمَالَ عَلَىٰ حُبِّهِۦ ذَوِى ٱلْقُرْبَىٰ وَٱلْيَتَٰمَىٰ وَٱلْمَسَٰكِينَ وَٱبْنَ ٱلسَّبِيلِ وَٱلسَّآئِلِينَ وَفِى ٱلرِّقَابِ وَأَقَامَ ٱلصَّلَوٰةَ وَءَاتَى ٱلزَّكَوٰةَ وَٱلْمُوفُونَ بِعَهْدِهِمْ إِذَا عَٰهَدُوا۟ ۖ وَٱلصَّٰبِرِينَ فِى ٱلْبَأْسَآءِ وَٱلضَّرَّآءِ وَحِينَ ٱلْبَأْسِ ۗ أُو۟لَٰٓئِكَ ٱلَّذِينَ صَدَقُوا۟ ۖ وَأُو۟لَٰٓئِكَ هُمُ ٱلْمُتَّقُونَ', 'ليس البر أن تولوا وجوهكم قبل المشرق والمغرب ولكن البر من ءامن بالله واليوم الءاخر والملئكة والكتب والنبين وءاتى المال على حبه ذوى القربى واليتمى والمسكين وابن السبيل والسائلين وفى الرقاب وأقام الصلوة وءاتى الزكوة والموفون بعهدهم إذا عهدوا  والصبرين فى البأساء والضراء وحين البأس  أولئك الذين صدقوا  وأولئك هم المتقون', NULL, 27, 'local:hafs-text.json'),
  ('hafs-2-178', 'hafs', 2, 178, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ كُتِبَ عَلَيْكُمُ ٱلْقِصَاصُ فِى ٱلْقَتْلَى ۖ ٱلْحُرُّ بِٱلْحُرِّ وَٱلْعَبْدُ بِٱلْعَبْدِ وَٱلْأُنثَىٰ بِٱلْأُنثَىٰ ۚ فَمَنْ عُفِىَ لَهُۥ مِنْ أَخِيهِ شَىْءٌۭ فَٱتِّبَاعٌۢ بِٱلْمَعْرُوفِ وَأَدَآءٌ إِلَيْهِ بِإِحْسَٰنٍۢ ۗ ذَٰلِكَ تَخْفِيفٌۭ مِّن رَّبِّكُمْ وَرَحْمَةٌۭ ۗ فَمَنِ ٱعْتَدَىٰ بَعْدَ ذَٰلِكَ فَلَهُۥ عَذَابٌ أَلِيمٌۭ', 'يأيها الذين ءامنوا كتب عليكم القصاص فى القتلى  الحر بالحر والعبد بالعبد والأنثى بالأنثى  فمن عفى له من أخيه شىء فاتباع بالمعروف وأداء إليه بإحسن  ذلك تخفيف من ربكم ورحمة  فمن اعتدى بعد ذلك فله عذاب أليم', NULL, 27, 'local:hafs-text.json'),
  ('hafs-2-179', 'hafs', 2, 179, 'وَلَكُمْ فِى ٱلْقِصَاصِ حَيَوٰةٌۭ يَٰٓأُو۟لِى ٱلْأَلْبَٰبِ لَعَلَّكُمْ تَتَّقُونَ', 'ولكم فى القصاص حيوة يأولى الألبب لعلكم تتقون', NULL, 27, 'local:hafs-text.json'),
  ('hafs-2-180', 'hafs', 2, 180, 'كُتِبَ عَلَيْكُمْ إِذَا حَضَرَ أَحَدَكُمُ ٱلْمَوْتُ إِن تَرَكَ خَيْرًا ٱلْوَصِيَّةُ لِلْوَٰلِدَيْنِ وَٱلْأَقْرَبِينَ بِٱلْمَعْرُوفِ ۖ حَقًّا عَلَى ٱلْمُتَّقِينَ', 'كتب عليكم إذا حضر أحدكم الموت إن ترك خيرا الوصية للولدين والأقربين بالمعروف  حقا على المتقين', NULL, 27, 'local:hafs-text.json'),
  ('hafs-2-181', 'hafs', 2, 181, 'فَمَنۢ بَدَّلَهُۥ بَعْدَمَا سَمِعَهُۥ فَإِنَّمَآ إِثْمُهُۥ عَلَى ٱلَّذِينَ يُبَدِّلُونَهُۥٓ ۚ إِنَّ ٱللَّهَ سَمِيعٌ عَلِيمٌۭ', 'فمن بدله بعدما سمعه فإنما إثمه على الذين يبدلونه  إن الله سميع عليم', NULL, 27, 'local:hafs-text.json'),
  ('hafs-2-182', 'hafs', 2, 182, 'فَمَنْ خَافَ مِن مُّوصٍۢ جَنَفًا أَوْ إِثْمًۭا فَأَصْلَحَ بَيْنَهُمْ فَلَآ إِثْمَ عَلَيْهِ ۚ إِنَّ ٱللَّهَ غَفُورٌۭ رَّحِيمٌۭ', 'فمن خاف من موص جنفا أو إثما فأصلح بينهم فلا إثم عليه  إن الله غفور رحيم', NULL, 28, 'local:hafs-text.json'),
  ('hafs-2-183', 'hafs', 2, 183, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ كُتِبَ عَلَيْكُمُ ٱلصِّيَامُ كَمَا كُتِبَ عَلَى ٱلَّذِينَ مِن قَبْلِكُمْ لَعَلَّكُمْ تَتَّقُونَ', 'يأيها الذين ءامنوا كتب عليكم الصيام كما كتب على الذين من قبلكم لعلكم تتقون', NULL, 28, 'local:hafs-text.json'),
  ('hafs-2-184', 'hafs', 2, 184, 'أَيَّامًۭا مَّعْدُودَٰتٍۢ ۚ فَمَن كَانَ مِنكُم مَّرِيضًا أَوْ عَلَىٰ سَفَرٍۢ فَعِدَّةٌۭ مِّنْ أَيَّامٍ أُخَرَ ۚ وَعَلَى ٱلَّذِينَ يُطِيقُونَهُۥ فِدْيَةٌۭ طَعَامُ مِسْكِينٍۢ ۖ فَمَن تَطَوَّعَ خَيْرًۭا فَهُوَ خَيْرٌۭ لَّهُۥ ۚ وَأَن تَصُومُوا۟ خَيْرٌۭ لَّكُمْ ۖ إِن كُنتُمْ تَعْلَمُونَ', 'أياما معدودت  فمن كان منكم مريضا أو على سفر فعدة من أيام أخر  وعلى الذين يطيقونه فدية طعام مسكين  فمن تطوع خيرا فهو خير له  وأن تصوموا خير لكم  إن كنتم تعلمون', NULL, 28, 'local:hafs-text.json'),
  ('hafs-2-185', 'hafs', 2, 185, 'شَهْرُ رَمَضَانَ ٱلَّذِىٓ أُنزِلَ فِيهِ ٱلْقُرْءَانُ هُدًۭى لِّلنَّاسِ وَبَيِّنَٰتٍۢ مِّنَ ٱلْهُدَىٰ وَٱلْفُرْقَانِ ۚ فَمَن شَهِدَ مِنكُمُ ٱلشَّهْرَ فَلْيَصُمْهُ ۖ وَمَن كَانَ مَرِيضًا أَوْ عَلَىٰ سَفَرٍۢ فَعِدَّةٌۭ مِّنْ أَيَّامٍ أُخَرَ ۗ يُرِيدُ ٱللَّهُ بِكُمُ ٱلْيُسْرَ وَلَا يُرِيدُ بِكُمُ ٱلْعُسْرَ وَلِتُكْمِلُوا۟ ٱلْعِدَّةَ وَلِتُكَبِّرُوا۟ ٱللَّهَ عَلَىٰ مَا هَدَىٰكُمْ وَلَعَلَّكُمْ تَشْكُرُونَ', 'شهر رمضان الذى أنزل فيه القرءان هدى للناس وبينت من الهدى والفرقان  فمن شهد منكم الشهر فليصمه  ومن كان مريضا أو على سفر فعدة من أيام أخر  يريد الله بكم اليسر ولا يريد بكم العسر ولتكملوا العدة ولتكبروا الله على ما هدىكم ولعلكم تشكرون', NULL, 28, 'local:hafs-text.json'),
  ('hafs-2-186', 'hafs', 2, 186, 'وَإِذَا سَأَلَكَ عِبَادِى عَنِّى فَإِنِّى قَرِيبٌ ۖ أُجِيبُ دَعْوَةَ ٱلدَّاعِ إِذَا دَعَانِ ۖ فَلْيَسْتَجِيبُوا۟ لِى وَلْيُؤْمِنُوا۟ بِى لَعَلَّهُمْ يَرْشُدُونَ', 'وإذا سألك عبادى عنى فإنى قريب  أجيب دعوة الداع إذا دعان  فليستجيبوا لى وليؤمنوا بى لعلهم يرشدون', NULL, 28, 'local:hafs-text.json'),
  ('hafs-2-187', 'hafs', 2, 187, 'أُحِلَّ لَكُمْ لَيْلَةَ ٱلصِّيَامِ ٱلرَّفَثُ إِلَىٰ نِسَآئِكُمْ ۚ هُنَّ لِبَاسٌۭ لَّكُمْ وَأَنتُمْ لِبَاسٌۭ لَّهُنَّ ۗ عَلِمَ ٱللَّهُ أَنَّكُمْ كُنتُمْ تَخْتَانُونَ أَنفُسَكُمْ فَتَابَ عَلَيْكُمْ وَعَفَا عَنكُمْ ۖ فَٱلْـَٰٔنَ بَٰشِرُوهُنَّ وَٱبْتَغُوا۟ مَا كَتَبَ ٱللَّهُ لَكُمْ ۚ وَكُلُوا۟ وَٱشْرَبُوا۟ حَتَّىٰ يَتَبَيَّنَ لَكُمُ ٱلْخَيْطُ ٱلْأَبْيَضُ مِنَ ٱلْخَيْطِ ٱلْأَسْوَدِ مِنَ ٱلْفَجْرِ ۖ ثُمَّ أَتِمُّوا۟ ٱلصِّيَامَ إِلَى ٱلَّيْلِ ۚ وَلَا تُبَٰشِرُوهُنَّ وَأَنتُمْ عَٰكِفُونَ فِى ٱلْمَسَٰجِدِ ۗ تِلْكَ حُدُودُ ٱللَّهِ فَلَا تَقْرَبُوهَا ۗ كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ ءَايَٰتِهِۦ لِلنَّاسِ لَعَلَّهُمْ يَتَّقُونَ', 'أحل لكم ليلة الصيام الرفث إلى نسائكم  هن لباس لكم وأنتم لباس لهن  علم الله أنكم كنتم تختانون أنفسكم فتاب عليكم وعفا عنكم  فالن بشروهن وابتغوا ما كتب الله لكم  وكلوا واشربوا حتى يتبين لكم الخيط الأبيض من الخيط الأسود من الفجر  ثم أتموا الصيام إلى اليل  ولا تبشروهن وأنتم عكفون فى المسجد  تلك حدود الله فلا تقربوها  كذلك يبين الله ءايته للناس لعلهم يتقون', NULL, 29, 'local:hafs-text.json'),
  ('hafs-2-188', 'hafs', 2, 188, 'وَلَا تَأْكُلُوٓا۟ أَمْوَٰلَكُم بَيْنَكُم بِٱلْبَٰطِلِ وَتُدْلُوا۟ بِهَآ إِلَى ٱلْحُكَّامِ لِتَأْكُلُوا۟ فَرِيقًۭا مِّنْ أَمْوَٰلِ ٱلنَّاسِ بِٱلْإِثْمِ وَأَنتُمْ تَعْلَمُونَ', 'ولا تأكلوا أمولكم بينكم بالبطل وتدلوا بها إلى الحكام لتأكلوا فريقا من أمول الناس بالإثم وأنتم تعلمون', NULL, 29, 'local:hafs-text.json'),
  ('hafs-2-189', 'hafs', 2, 189, '۞ يَسْـَٔلُونَكَ عَنِ ٱلْأَهِلَّةِ ۖ قُلْ هِىَ مَوَٰقِيتُ لِلنَّاسِ وَٱلْحَجِّ ۗ وَلَيْسَ ٱلْبِرُّ بِأَن تَأْتُوا۟ ٱلْبُيُوتَ مِن ظُهُورِهَا وَلَٰكِنَّ ٱلْبِرَّ مَنِ ٱتَّقَىٰ ۗ وَأْتُوا۟ ٱلْبُيُوتَ مِنْ أَبْوَٰبِهَا ۚ وَٱتَّقُوا۟ ٱللَّهَ لَعَلَّكُمْ تُفْلِحُونَ', 'يسلونك عن الأهلة  قل هى موقيت للناس والحج  وليس البر بأن تأتوا البيوت من ظهورها ولكن البر من اتقى  وأتوا البيوت من أبوبها  واتقوا الله لعلكم تفلحون', NULL, 29, 'local:hafs-text.json'),
  ('hafs-2-190', 'hafs', 2, 190, 'وَقَٰتِلُوا۟ فِى سَبِيلِ ٱللَّهِ ٱلَّذِينَ يُقَٰتِلُونَكُمْ وَلَا تَعْتَدُوٓا۟ ۚ إِنَّ ٱللَّهَ لَا يُحِبُّ ٱلْمُعْتَدِينَ', 'وقتلوا فى سبيل الله الذين يقتلونكم ولا تعتدوا  إن الله لا يحب المعتدين', NULL, 29, 'local:hafs-text.json'),
  ('hafs-2-191', 'hafs', 2, 191, 'وَٱقْتُلُوهُمْ حَيْثُ ثَقِفْتُمُوهُمْ وَأَخْرِجُوهُم مِّنْ حَيْثُ أَخْرَجُوكُمْ ۚ وَٱلْفِتْنَةُ أَشَدُّ مِنَ ٱلْقَتْلِ ۚ وَلَا تُقَٰتِلُوهُمْ عِندَ ٱلْمَسْجِدِ ٱلْحَرَامِ حَتَّىٰ يُقَٰتِلُوكُمْ فِيهِ ۖ فَإِن قَٰتَلُوكُمْ فَٱقْتُلُوهُمْ ۗ كَذَٰلِكَ جَزَآءُ ٱلْكَٰفِرِينَ', 'واقتلوهم حيث ثقفتموهم وأخرجوهم من حيث أخرجوكم  والفتنة أشد من القتل  ولا تقتلوهم عند المسجد الحرام حتى يقتلوكم فيه  فإن قتلوكم فاقتلوهم  كذلك جزاء الكفرين', NULL, 30, 'local:hafs-text.json'),
  ('hafs-2-192', 'hafs', 2, 192, 'فَإِنِ ٱنتَهَوْا۟ فَإِنَّ ٱللَّهَ غَفُورٌۭ رَّحِيمٌۭ', 'فإن انتهوا فإن الله غفور رحيم', NULL, 30, 'local:hafs-text.json'),
  ('hafs-2-193', 'hafs', 2, 193, 'وَقَٰتِلُوهُمْ حَتَّىٰ لَا تَكُونَ فِتْنَةٌۭ وَيَكُونَ ٱلدِّينُ لِلَّهِ ۖ فَإِنِ ٱنتَهَوْا۟ فَلَا عُدْوَٰنَ إِلَّا عَلَى ٱلظَّٰلِمِينَ', 'وقتلوهم حتى لا تكون فتنة ويكون الدين لله  فإن انتهوا فلا عدون إلا على الظلمين', NULL, 30, 'local:hafs-text.json'),
  ('hafs-2-194', 'hafs', 2, 194, 'ٱلشَّهْرُ ٱلْحَرَامُ بِٱلشَّهْرِ ٱلْحَرَامِ وَٱلْحُرُمَٰتُ قِصَاصٌۭ ۚ فَمَنِ ٱعْتَدَىٰ عَلَيْكُمْ فَٱعْتَدُوا۟ عَلَيْهِ بِمِثْلِ مَا ٱعْتَدَىٰ عَلَيْكُمْ ۚ وَٱتَّقُوا۟ ٱللَّهَ وَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ مَعَ ٱلْمُتَّقِينَ', 'الشهر الحرام بالشهر الحرام والحرمت قصاص  فمن اعتدى عليكم فاعتدوا عليه بمثل ما اعتدى عليكم  واتقوا الله واعلموا أن الله مع المتقين', NULL, 30, 'local:hafs-text.json'),
  ('hafs-2-195', 'hafs', 2, 195, 'وَأَنفِقُوا۟ فِى سَبِيلِ ٱللَّهِ وَلَا تُلْقُوا۟ بِأَيْدِيكُمْ إِلَى ٱلتَّهْلُكَةِ ۛ وَأَحْسِنُوٓا۟ ۛ إِنَّ ٱللَّهَ يُحِبُّ ٱلْمُحْسِنِينَ', 'وأنفقوا فى سبيل الله ولا تلقوا بأيديكم إلى التهلكة  وأحسنوا  إن الله يحب المحسنين', NULL, 30, 'local:hafs-text.json'),
  ('hafs-2-196', 'hafs', 2, 196, 'وَأَتِمُّوا۟ ٱلْحَجَّ وَٱلْعُمْرَةَ لِلَّهِ ۚ فَإِنْ أُحْصِرْتُمْ فَمَا ٱسْتَيْسَرَ مِنَ ٱلْهَدْىِ ۖ وَلَا تَحْلِقُوا۟ رُءُوسَكُمْ حَتَّىٰ يَبْلُغَ ٱلْهَدْىُ مَحِلَّهُۥ ۚ فَمَن كَانَ مِنكُم مَّرِيضًا أَوْ بِهِۦٓ أَذًۭى مِّن رَّأْسِهِۦ فَفِدْيَةٌۭ مِّن صِيَامٍ أَوْ صَدَقَةٍ أَوْ نُسُكٍۢ ۚ فَإِذَآ أَمِنتُمْ فَمَن تَمَتَّعَ بِٱلْعُمْرَةِ إِلَى ٱلْحَجِّ فَمَا ٱسْتَيْسَرَ مِنَ ٱلْهَدْىِ ۚ فَمَن لَّمْ يَجِدْ فَصِيَامُ ثَلَٰثَةِ أَيَّامٍۢ فِى ٱلْحَجِّ وَسَبْعَةٍ إِذَا رَجَعْتُمْ ۗ تِلْكَ عَشَرَةٌۭ كَامِلَةٌۭ ۗ ذَٰلِكَ لِمَن لَّمْ يَكُنْ أَهْلُهُۥ حَاضِرِى ٱلْمَسْجِدِ ٱلْحَرَامِ ۚ وَٱتَّقُوا۟ ٱللَّهَ وَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ شَدِيدُ ٱلْعِقَابِ', 'وأتموا الحج والعمرة لله  فإن أحصرتم فما استيسر من الهدى  ولا تحلقوا رءوسكم حتى يبلغ الهدى محله  فمن كان منكم مريضا أو به أذى من رأسه ففدية من صيام أو صدقة أو نسك  فإذا أمنتم فمن تمتع بالعمرة إلى الحج فما استيسر من الهدى  فمن لم يجد فصيام ثلثة أيام فى الحج وسبعة إذا رجعتم  تلك عشرة كاملة  ذلك لمن لم يكن أهله حاضرى المسجد الحرام  واتقوا الله واعلموا أن الله شديد العقاب', NULL, 30, 'local:hafs-text.json'),
  ('hafs-2-197', 'hafs', 2, 197, 'ٱلْحَجُّ أَشْهُرٌۭ مَّعْلُومَٰتٌۭ ۚ فَمَن فَرَضَ فِيهِنَّ ٱلْحَجَّ فَلَا رَفَثَ وَلَا فُسُوقَ وَلَا جِدَالَ فِى ٱلْحَجِّ ۗ وَمَا تَفْعَلُوا۟ مِنْ خَيْرٍۢ يَعْلَمْهُ ٱللَّهُ ۗ وَتَزَوَّدُوا۟ فَإِنَّ خَيْرَ ٱلزَّادِ ٱلتَّقْوَىٰ ۚ وَٱتَّقُونِ يَٰٓأُو۟لِى ٱلْأَلْبَٰبِ', 'الحج أشهر معلومت  فمن فرض فيهن الحج فلا رفث ولا فسوق ولا جدال فى الحج  وما تفعلوا من خير يعلمه الله  وتزودوا فإن خير الزاد التقوى  واتقون يأولى الألبب', NULL, 31, 'local:hafs-text.json'),
  ('hafs-2-198', 'hafs', 2, 198, 'لَيْسَ عَلَيْكُمْ جُنَاحٌ أَن تَبْتَغُوا۟ فَضْلًۭا مِّن رَّبِّكُمْ ۚ فَإِذَآ أَفَضْتُم مِّنْ عَرَفَٰتٍۢ فَٱذْكُرُوا۟ ٱللَّهَ عِندَ ٱلْمَشْعَرِ ٱلْحَرَامِ ۖ وَٱذْكُرُوهُ كَمَا هَدَىٰكُمْ وَإِن كُنتُم مِّن قَبْلِهِۦ لَمِنَ ٱلضَّآلِّينَ', 'ليس عليكم جناح أن تبتغوا فضلا من ربكم  فإذا أفضتم من عرفت فاذكروا الله عند المشعر الحرام  واذكروه كما هدىكم وإن كنتم من قبله لمن الضالين', NULL, 31, 'local:hafs-text.json'),
  ('hafs-2-199', 'hafs', 2, 199, 'ثُمَّ أَفِيضُوا۟ مِنْ حَيْثُ أَفَاضَ ٱلنَّاسُ وَٱسْتَغْفِرُوا۟ ٱللَّهَ ۚ إِنَّ ٱللَّهَ غَفُورٌۭ رَّحِيمٌۭ', 'ثم أفيضوا من حيث أفاض الناس واستغفروا الله  إن الله غفور رحيم', NULL, 31, 'local:hafs-text.json'),
  ('hafs-2-200', 'hafs', 2, 200, 'فَإِذَا قَضَيْتُم مَّنَٰسِكَكُمْ فَٱذْكُرُوا۟ ٱللَّهَ كَذِكْرِكُمْ ءَابَآءَكُمْ أَوْ أَشَدَّ ذِكْرًۭا ۗ فَمِنَ ٱلنَّاسِ مَن يَقُولُ رَبَّنَآ ءَاتِنَا فِى ٱلدُّنْيَا وَمَا لَهُۥ فِى ٱلْءَاخِرَةِ مِنْ خَلَٰقٍۢ', 'فإذا قضيتم منسككم فاذكروا الله كذكركم ءاباءكم أو أشد ذكرا  فمن الناس من يقول ربنا ءاتنا فى الدنيا وما له فى الءاخرة من خلق', NULL, 31, 'local:hafs-text.json'),
  ('hafs-2-201', 'hafs', 2, 201, 'وَمِنْهُم مَّن يَقُولُ رَبَّنَآ ءَاتِنَا فِى ٱلدُّنْيَا حَسَنَةًۭ وَفِى ٱلْءَاخِرَةِ حَسَنَةًۭ وَقِنَا عَذَابَ ٱلنَّارِ', 'ومنهم من يقول ربنا ءاتنا فى الدنيا حسنة وفى الءاخرة حسنة وقنا عذاب النار', NULL, 31, 'local:hafs-text.json'),
  ('hafs-2-202', 'hafs', 2, 202, 'أُو۟لَٰٓئِكَ لَهُمْ نَصِيبٌۭ مِّمَّا كَسَبُوا۟ ۚ وَٱللَّهُ سَرِيعُ ٱلْحِسَابِ', 'أولئك لهم نصيب مما كسبوا  والله سريع الحساب', NULL, 31, 'local:hafs-text.json'),
  ('hafs-2-203', 'hafs', 2, 203, '۞ وَٱذْكُرُوا۟ ٱللَّهَ فِىٓ أَيَّامٍۢ مَّعْدُودَٰتٍۢ ۚ فَمَن تَعَجَّلَ فِى يَوْمَيْنِ فَلَآ إِثْمَ عَلَيْهِ وَمَن تَأَخَّرَ فَلَآ إِثْمَ عَلَيْهِ ۚ لِمَنِ ٱتَّقَىٰ ۗ وَٱتَّقُوا۟ ٱللَّهَ وَٱعْلَمُوٓا۟ أَنَّكُمْ إِلَيْهِ تُحْشَرُونَ', 'واذكروا الله فى أيام معدودت  فمن تعجل فى يومين فلا إثم عليه ومن تأخر فلا إثم عليه  لمن اتقى  واتقوا الله واعلموا أنكم إليه تحشرون', NULL, 32, 'local:hafs-text.json'),
  ('hafs-2-204', 'hafs', 2, 204, 'وَمِنَ ٱلنَّاسِ مَن يُعْجِبُكَ قَوْلُهُۥ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا وَيُشْهِدُ ٱللَّهَ عَلَىٰ مَا فِى قَلْبِهِۦ وَهُوَ أَلَدُّ ٱلْخِصَامِ', 'ومن الناس من يعجبك قوله فى الحيوة الدنيا ويشهد الله على ما فى قلبه وهو ألد الخصام', NULL, 32, 'local:hafs-text.json'),
  ('hafs-2-205', 'hafs', 2, 205, 'وَإِذَا تَوَلَّىٰ سَعَىٰ فِى ٱلْأَرْضِ لِيُفْسِدَ فِيهَا وَيُهْلِكَ ٱلْحَرْثَ وَٱلنَّسْلَ ۗ وَٱللَّهُ لَا يُحِبُّ ٱلْفَسَادَ', 'وإذا تولى سعى فى الأرض ليفسد فيها ويهلك الحرث والنسل  والله لا يحب الفساد', NULL, 32, 'local:hafs-text.json'),
  ('hafs-2-206', 'hafs', 2, 206, 'وَإِذَا قِيلَ لَهُ ٱتَّقِ ٱللَّهَ أَخَذَتْهُ ٱلْعِزَّةُ بِٱلْإِثْمِ ۚ فَحَسْبُهُۥ جَهَنَّمُ ۚ وَلَبِئْسَ ٱلْمِهَادُ', 'وإذا قيل له اتق الله أخذته العزة بالإثم  فحسبه جهنم  ولبئس المهاد', NULL, 32, 'local:hafs-text.json'),
  ('hafs-2-207', 'hafs', 2, 207, 'وَمِنَ ٱلنَّاسِ مَن يَشْرِى نَفْسَهُ ٱبْتِغَآءَ مَرْضَاتِ ٱللَّهِ ۗ وَٱللَّهُ رَءُوفٌۢ بِٱلْعِبَادِ', 'ومن الناس من يشرى نفسه ابتغاء مرضات الله  والله رءوف بالعباد', NULL, 32, 'local:hafs-text.json'),
  ('hafs-2-208', 'hafs', 2, 208, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱدْخُلُوا۟ فِى ٱلسِّلْمِ كَآفَّةًۭ وَلَا تَتَّبِعُوا۟ خُطُوَٰتِ ٱلشَّيْطَٰنِ ۚ إِنَّهُۥ لَكُمْ عَدُوٌّۭ مُّبِينٌۭ', 'يأيها الذين ءامنوا ادخلوا فى السلم كافة ولا تتبعوا خطوت الشيطن  إنه لكم عدو مبين', NULL, 32, 'local:hafs-text.json'),
  ('hafs-2-209', 'hafs', 2, 209, 'فَإِن زَلَلْتُم مِّنۢ بَعْدِ مَا جَآءَتْكُمُ ٱلْبَيِّنَٰتُ فَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ عَزِيزٌ حَكِيمٌ', 'فإن زللتم من بعد ما جاءتكم البينت فاعلموا أن الله عزيز حكيم', NULL, 32, 'local:hafs-text.json'),
  ('hafs-2-210', 'hafs', 2, 210, 'هَلْ يَنظُرُونَ إِلَّآ أَن يَأْتِيَهُمُ ٱللَّهُ فِى ظُلَلٍۢ مِّنَ ٱلْغَمَامِ وَٱلْمَلَٰٓئِكَةُ وَقُضِىَ ٱلْأَمْرُ ۚ وَإِلَى ٱللَّهِ تُرْجَعُ ٱلْأُمُورُ', 'هل ينظرون إلا أن يأتيهم الله فى ظلل من الغمام والملئكة وقضى الأمر  وإلى الله ترجع الأمور', NULL, 32, 'local:hafs-text.json'),
  ('hafs-2-211', 'hafs', 2, 211, 'سَلْ بَنِىٓ إِسْرَٰٓءِيلَ كَمْ ءَاتَيْنَٰهُم مِّنْ ءَايَةٍۭ بَيِّنَةٍۢ ۗ وَمَن يُبَدِّلْ نِعْمَةَ ٱللَّهِ مِنۢ بَعْدِ مَا جَآءَتْهُ فَإِنَّ ٱللَّهَ شَدِيدُ ٱلْعِقَابِ', 'سل بنى إسرءيل كم ءاتينهم من ءاية بينة  ومن يبدل نعمة الله من بعد ما جاءته فإن الله شديد العقاب', NULL, 33, 'local:hafs-text.json'),
  ('hafs-2-212', 'hafs', 2, 212, 'زُيِّنَ لِلَّذِينَ كَفَرُوا۟ ٱلْحَيَوٰةُ ٱلدُّنْيَا وَيَسْخَرُونَ مِنَ ٱلَّذِينَ ءَامَنُوا۟ ۘ وَٱلَّذِينَ ٱتَّقَوْا۟ فَوْقَهُمْ يَوْمَ ٱلْقِيَٰمَةِ ۗ وَٱللَّهُ يَرْزُقُ مَن يَشَآءُ بِغَيْرِ حِسَابٍۢ', 'زين للذين كفروا الحيوة الدنيا ويسخرون من الذين ءامنوا  والذين اتقوا فوقهم يوم القيمة  والله يرزق من يشاء بغير حساب', NULL, 33, 'local:hafs-text.json'),
  ('hafs-2-213', 'hafs', 2, 213, 'كَانَ ٱلنَّاسُ أُمَّةًۭ وَٰحِدَةًۭ فَبَعَثَ ٱللَّهُ ٱلنَّبِيِّۦنَ مُبَشِّرِينَ وَمُنذِرِينَ وَأَنزَلَ مَعَهُمُ ٱلْكِتَٰبَ بِٱلْحَقِّ لِيَحْكُمَ بَيْنَ ٱلنَّاسِ فِيمَا ٱخْتَلَفُوا۟ فِيهِ ۚ وَمَا ٱخْتَلَفَ فِيهِ إِلَّا ٱلَّذِينَ أُوتُوهُ مِنۢ بَعْدِ مَا جَآءَتْهُمُ ٱلْبَيِّنَٰتُ بَغْيًۢا بَيْنَهُمْ ۖ فَهَدَى ٱللَّهُ ٱلَّذِينَ ءَامَنُوا۟ لِمَا ٱخْتَلَفُوا۟ فِيهِ مِنَ ٱلْحَقِّ بِإِذْنِهِۦ ۗ وَٱللَّهُ يَهْدِى مَن يَشَآءُ إِلَىٰ صِرَٰطٍۢ مُّسْتَقِيمٍ', 'كان الناس أمة وحدة فبعث الله النبين مبشرين ومنذرين وأنزل معهم الكتب بالحق ليحكم بين الناس فيما اختلفوا فيه  وما اختلف فيه إلا الذين أوتوه من بعد ما جاءتهم البينت بغيا بينهم  فهدى الله الذين ءامنوا لما اختلفوا فيه من الحق بإذنه  والله يهدى من يشاء إلى صرط مستقيم', NULL, 33, 'local:hafs-text.json'),
  ('hafs-2-214', 'hafs', 2, 214, 'أَمْ حَسِبْتُمْ أَن تَدْخُلُوا۟ ٱلْجَنَّةَ وَلَمَّا يَأْتِكُم مَّثَلُ ٱلَّذِينَ خَلَوْا۟ مِن قَبْلِكُم ۖ مَّسَّتْهُمُ ٱلْبَأْسَآءُ وَٱلضَّرَّآءُ وَزُلْزِلُوا۟ حَتَّىٰ يَقُولَ ٱلرَّسُولُ وَٱلَّذِينَ ءَامَنُوا۟ مَعَهُۥ مَتَىٰ نَصْرُ ٱللَّهِ ۗ أَلَآ إِنَّ نَصْرَ ٱللَّهِ قَرِيبٌۭ', 'أم حسبتم أن تدخلوا الجنة ولما يأتكم مثل الذين خلوا من قبلكم  مستهم البأساء والضراء وزلزلوا حتى يقول الرسول والذين ءامنوا معه متى نصر الله  ألا إن نصر الله قريب', NULL, 33, 'local:hafs-text.json'),
  ('hafs-2-215', 'hafs', 2, 215, 'يَسْـَٔلُونَكَ مَاذَا يُنفِقُونَ ۖ قُلْ مَآ أَنفَقْتُم مِّنْ خَيْرٍۢ فَلِلْوَٰلِدَيْنِ وَٱلْأَقْرَبِينَ وَٱلْيَتَٰمَىٰ وَٱلْمَسَٰكِينِ وَٱبْنِ ٱلسَّبِيلِ ۗ وَمَا تَفْعَلُوا۟ مِنْ خَيْرٍۢ فَإِنَّ ٱللَّهَ بِهِۦ عَلِيمٌۭ', 'يسلونك ماذا ينفقون  قل ما أنفقتم من خير فللولدين والأقربين واليتمى والمسكين وابن السبيل  وما تفعلوا من خير فإن الله به عليم', NULL, 33, 'local:hafs-text.json'),
  ('hafs-2-216', 'hafs', 2, 216, 'كُتِبَ عَلَيْكُمُ ٱلْقِتَالُ وَهُوَ كُرْهٌۭ لَّكُمْ ۖ وَعَسَىٰٓ أَن تَكْرَهُوا۟ شَيْـًۭٔا وَهُوَ خَيْرٌۭ لَّكُمْ ۖ وَعَسَىٰٓ أَن تُحِبُّوا۟ شَيْـًۭٔا وَهُوَ شَرٌّۭ لَّكُمْ ۗ وَٱللَّهُ يَعْلَمُ وَأَنتُمْ لَا تَعْلَمُونَ', 'كتب عليكم القتال وهو كره لكم  وعسى أن تكرهوا شيا وهو خير لكم  وعسى أن تحبوا شيا وهو شر لكم  والله يعلم وأنتم لا تعلمون', NULL, 34, 'local:hafs-text.json'),
  ('hafs-2-217', 'hafs', 2, 217, 'يَسْـَٔلُونَكَ عَنِ ٱلشَّهْرِ ٱلْحَرَامِ قِتَالٍۢ فِيهِ ۖ قُلْ قِتَالٌۭ فِيهِ كَبِيرٌۭ ۖ وَصَدٌّ عَن سَبِيلِ ٱللَّهِ وَكُفْرٌۢ بِهِۦ وَٱلْمَسْجِدِ ٱلْحَرَامِ وَإِخْرَاجُ أَهْلِهِۦ مِنْهُ أَكْبَرُ عِندَ ٱللَّهِ ۚ وَٱلْفِتْنَةُ أَكْبَرُ مِنَ ٱلْقَتْلِ ۗ وَلَا يَزَالُونَ يُقَٰتِلُونَكُمْ حَتَّىٰ يَرُدُّوكُمْ عَن دِينِكُمْ إِنِ ٱسْتَطَٰعُوا۟ ۚ وَمَن يَرْتَدِدْ مِنكُمْ عَن دِينِهِۦ فَيَمُتْ وَهُوَ كَافِرٌۭ فَأُو۟لَٰٓئِكَ حَبِطَتْ أَعْمَٰلُهُمْ فِى ٱلدُّنْيَا وَٱلْءَاخِرَةِ ۖ وَأُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلنَّارِ ۖ هُمْ فِيهَا خَٰلِدُونَ', 'يسلونك عن الشهر الحرام قتال فيه  قل قتال فيه كبير  وصد عن سبيل الله وكفر به والمسجد الحرام وإخراج أهله منه أكبر عند الله  والفتنة أكبر من القتل  ولا يزالون يقتلونكم حتى يردوكم عن دينكم إن استطعوا  ومن يرتدد منكم عن دينه فيمت وهو كافر فأولئك حبطت أعملهم فى الدنيا والءاخرة  وأولئك أصحب النار  هم فيها خلدون', NULL, 34, 'local:hafs-text.json'),
  ('hafs-2-218', 'hafs', 2, 218, 'إِنَّ ٱلَّذِينَ ءَامَنُوا۟ وَٱلَّذِينَ هَاجَرُوا۟ وَجَٰهَدُوا۟ فِى سَبِيلِ ٱللَّهِ أُو۟لَٰٓئِكَ يَرْجُونَ رَحْمَتَ ٱللَّهِ ۚ وَٱللَّهُ غَفُورٌۭ رَّحِيمٌۭ', 'إن الذين ءامنوا والذين هاجروا وجهدوا فى سبيل الله أولئك يرجون رحمت الله  والله غفور رحيم', NULL, 34, 'local:hafs-text.json'),
  ('hafs-2-219', 'hafs', 2, 219, '۞ يَسْـَٔلُونَكَ عَنِ ٱلْخَمْرِ وَٱلْمَيْسِرِ ۖ قُلْ فِيهِمَآ إِثْمٌۭ كَبِيرٌۭ وَمَنَٰفِعُ لِلنَّاسِ وَإِثْمُهُمَآ أَكْبَرُ مِن نَّفْعِهِمَا ۗ وَيَسْـَٔلُونَكَ مَاذَا يُنفِقُونَ قُلِ ٱلْعَفْوَ ۗ كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ لَكُمُ ٱلْءَايَٰتِ لَعَلَّكُمْ تَتَفَكَّرُونَ', 'يسلونك عن الخمر والميسر  قل فيهما إثم كبير ومنفع للناس وإثمهما أكبر من نفعهما  ويسلونك ماذا ينفقون قل العفو  كذلك يبين الله لكم الءايت لعلكم تتفكرون', NULL, 34, 'local:hafs-text.json'),
  ('hafs-2-220', 'hafs', 2, 220, 'فِى ٱلدُّنْيَا وَٱلْءَاخِرَةِ ۗ وَيَسْـَٔلُونَكَ عَنِ ٱلْيَتَٰمَىٰ ۖ قُلْ إِصْلَاحٌۭ لَّهُمْ خَيْرٌۭ ۖ وَإِن تُخَالِطُوهُمْ فَإِخْوَٰنُكُمْ ۚ وَٱللَّهُ يَعْلَمُ ٱلْمُفْسِدَ مِنَ ٱلْمُصْلِحِ ۚ وَلَوْ شَآءَ ٱللَّهُ لَأَعْنَتَكُمْ ۚ إِنَّ ٱللَّهَ عَزِيزٌ حَكِيمٌۭ', 'فى الدنيا والءاخرة  ويسلونك عن اليتمى  قل إصلاح لهم خير  وإن تخالطوهم فإخونكم  والله يعلم المفسد من المصلح  ولو شاء الله لأعنتكم  إن الله عزيز حكيم', NULL, 35, 'local:hafs-text.json'),
  ('hafs-2-221', 'hafs', 2, 221, 'وَلَا تَنكِحُوا۟ ٱلْمُشْرِكَٰتِ حَتَّىٰ يُؤْمِنَّ ۚ وَلَأَمَةٌۭ مُّؤْمِنَةٌ خَيْرٌۭ مِّن مُّشْرِكَةٍۢ وَلَوْ أَعْجَبَتْكُمْ ۗ وَلَا تُنكِحُوا۟ ٱلْمُشْرِكِينَ حَتَّىٰ يُؤْمِنُوا۟ ۚ وَلَعَبْدٌۭ مُّؤْمِنٌ خَيْرٌۭ مِّن مُّشْرِكٍۢ وَلَوْ أَعْجَبَكُمْ ۗ أُو۟لَٰٓئِكَ يَدْعُونَ إِلَى ٱلنَّارِ ۖ وَٱللَّهُ يَدْعُوٓا۟ إِلَى ٱلْجَنَّةِ وَٱلْمَغْفِرَةِ بِإِذْنِهِۦ ۖ وَيُبَيِّنُ ءَايَٰتِهِۦ لِلنَّاسِ لَعَلَّهُمْ يَتَذَكَّرُونَ', 'ولا تنكحوا المشركت حتى يؤمن  ولأمة مؤمنة خير من مشركة ولو أعجبتكم  ولا تنكحوا المشركين حتى يؤمنوا  ولعبد مؤمن خير من مشرك ولو أعجبكم  أولئك يدعون إلى النار  والله يدعوا إلى الجنة والمغفرة بإذنه  ويبين ءايته للناس لعلهم يتذكرون', NULL, 35, 'local:hafs-text.json'),
  ('hafs-2-222', 'hafs', 2, 222, 'وَيَسْـَٔلُونَكَ عَنِ ٱلْمَحِيضِ ۖ قُلْ هُوَ أَذًۭى فَٱعْتَزِلُوا۟ ٱلنِّسَآءَ فِى ٱلْمَحِيضِ ۖ وَلَا تَقْرَبُوهُنَّ حَتَّىٰ يَطْهُرْنَ ۖ فَإِذَا تَطَهَّرْنَ فَأْتُوهُنَّ مِنْ حَيْثُ أَمَرَكُمُ ٱللَّهُ ۚ إِنَّ ٱللَّهَ يُحِبُّ ٱلتَّوَّٰبِينَ وَيُحِبُّ ٱلْمُتَطَهِّرِينَ', 'ويسلونك عن المحيض  قل هو أذى فاعتزلوا النساء فى المحيض  ولا تقربوهن حتى يطهرن  فإذا تطهرن فأتوهن من حيث أمركم الله  إن الله يحب التوبين ويحب المتطهرين', NULL, 35, 'local:hafs-text.json'),
  ('hafs-2-223', 'hafs', 2, 223, 'نِسَآؤُكُمْ حَرْثٌۭ لَّكُمْ فَأْتُوا۟ حَرْثَكُمْ أَنَّىٰ شِئْتُمْ ۖ وَقَدِّمُوا۟ لِأَنفُسِكُمْ ۚ وَٱتَّقُوا۟ ٱللَّهَ وَٱعْلَمُوٓا۟ أَنَّكُم مُّلَٰقُوهُ ۗ وَبَشِّرِ ٱلْمُؤْمِنِينَ', 'نساؤكم حرث لكم فأتوا حرثكم أنى شئتم  وقدموا لأنفسكم  واتقوا الله واعلموا أنكم ملقوه  وبشر المؤمنين', NULL, 35, 'local:hafs-text.json'),
  ('hafs-2-224', 'hafs', 2, 224, 'وَلَا تَجْعَلُوا۟ ٱللَّهَ عُرْضَةًۭ لِّأَيْمَٰنِكُمْ أَن تَبَرُّوا۟ وَتَتَّقُوا۟ وَتُصْلِحُوا۟ بَيْنَ ٱلنَّاسِ ۗ وَٱللَّهُ سَمِيعٌ عَلِيمٌۭ', 'ولا تجعلوا الله عرضة لأيمنكم أن تبروا وتتقوا وتصلحوا بين الناس  والله سميع عليم', NULL, 35, 'local:hafs-text.json'),
  ('hafs-2-225', 'hafs', 2, 225, 'لَّا يُؤَاخِذُكُمُ ٱللَّهُ بِٱللَّغْوِ فِىٓ أَيْمَٰنِكُمْ وَلَٰكِن يُؤَاخِذُكُم بِمَا كَسَبَتْ قُلُوبُكُمْ ۗ وَٱللَّهُ غَفُورٌ حَلِيمٌۭ', 'لا يؤاخذكم الله باللغو فى أيمنكم ولكن يؤاخذكم بما كسبت قلوبكم  والله غفور حليم', NULL, 36, 'local:hafs-text.json'),
  ('hafs-2-226', 'hafs', 2, 226, 'لِّلَّذِينَ يُؤْلُونَ مِن نِّسَآئِهِمْ تَرَبُّصُ أَرْبَعَةِ أَشْهُرٍۢ ۖ فَإِن فَآءُو فَإِنَّ ٱللَّهَ غَفُورٌۭ رَّحِيمٌۭ', 'للذين يؤلون من نسائهم تربص أربعة أشهر  فإن فاءو فإن الله غفور رحيم', NULL, 36, 'local:hafs-text.json'),
  ('hafs-2-227', 'hafs', 2, 227, 'وَإِنْ عَزَمُوا۟ ٱلطَّلَٰقَ فَإِنَّ ٱللَّهَ سَمِيعٌ عَلِيمٌۭ', 'وإن عزموا الطلق فإن الله سميع عليم', NULL, 36, 'local:hafs-text.json'),
  ('hafs-2-228', 'hafs', 2, 228, 'وَٱلْمُطَلَّقَٰتُ يَتَرَبَّصْنَ بِأَنفُسِهِنَّ ثَلَٰثَةَ قُرُوٓءٍۢ ۚ وَلَا يَحِلُّ لَهُنَّ أَن يَكْتُمْنَ مَا خَلَقَ ٱللَّهُ فِىٓ أَرْحَامِهِنَّ إِن كُنَّ يُؤْمِنَّ بِٱللَّهِ وَٱلْيَوْمِ ٱلْءَاخِرِ ۚ وَبُعُولَتُهُنَّ أَحَقُّ بِرَدِّهِنَّ فِى ذَٰلِكَ إِنْ أَرَادُوٓا۟ إِصْلَٰحًۭا ۚ وَلَهُنَّ مِثْلُ ٱلَّذِى عَلَيْهِنَّ بِٱلْمَعْرُوفِ ۚ وَلِلرِّجَالِ عَلَيْهِنَّ دَرَجَةٌۭ ۗ وَٱللَّهُ عَزِيزٌ حَكِيمٌ', 'والمطلقت يتربصن بأنفسهن ثلثة قروء  ولا يحل لهن أن يكتمن ما خلق الله فى أرحامهن إن كن يؤمن بالله واليوم الءاخر  وبعولتهن أحق بردهن فى ذلك إن أرادوا إصلحا  ولهن مثل الذى عليهن بالمعروف  وللرجال عليهن درجة  والله عزيز حكيم', NULL, 36, 'local:hafs-text.json'),
  ('hafs-2-229', 'hafs', 2, 229, 'ٱلطَّلَٰقُ مَرَّتَانِ ۖ فَإِمْسَاكٌۢ بِمَعْرُوفٍ أَوْ تَسْرِيحٌۢ بِإِحْسَٰنٍۢ ۗ وَلَا يَحِلُّ لَكُمْ أَن تَأْخُذُوا۟ مِمَّآ ءَاتَيْتُمُوهُنَّ شَيْـًٔا إِلَّآ أَن يَخَافَآ أَلَّا يُقِيمَا حُدُودَ ٱللَّهِ ۖ فَإِنْ خِفْتُمْ أَلَّا يُقِيمَا حُدُودَ ٱللَّهِ فَلَا جُنَاحَ عَلَيْهِمَا فِيمَا ٱفْتَدَتْ بِهِۦ ۗ تِلْكَ حُدُودُ ٱللَّهِ فَلَا تَعْتَدُوهَا ۚ وَمَن يَتَعَدَّ حُدُودَ ٱللَّهِ فَأُو۟لَٰٓئِكَ هُمُ ٱلظَّٰلِمُونَ', 'الطلق مرتان  فإمساك بمعروف أو تسريح بإحسن  ولا يحل لكم أن تأخذوا مما ءاتيتموهن شيا إلا أن يخافا ألا يقيما حدود الله  فإن خفتم ألا يقيما حدود الله فلا جناح عليهما فيما افتدت به  تلك حدود الله فلا تعتدوها  ومن يتعد حدود الله فأولئك هم الظلمون', NULL, 36, 'local:hafs-text.json'),
  ('hafs-2-230', 'hafs', 2, 230, 'فَإِن طَلَّقَهَا فَلَا تَحِلُّ لَهُۥ مِنۢ بَعْدُ حَتَّىٰ تَنكِحَ زَوْجًا غَيْرَهُۥ ۗ فَإِن طَلَّقَهَا فَلَا جُنَاحَ عَلَيْهِمَآ أَن يَتَرَاجَعَآ إِن ظَنَّآ أَن يُقِيمَا حُدُودَ ٱللَّهِ ۗ وَتِلْكَ حُدُودُ ٱللَّهِ يُبَيِّنُهَا لِقَوْمٍۢ يَعْلَمُونَ', 'فإن طلقها فلا تحل له من بعد حتى تنكح زوجا غيره  فإن طلقها فلا جناح عليهما أن يتراجعا إن ظنا أن يقيما حدود الله  وتلك حدود الله يبينها لقوم يعلمون', NULL, 36, 'local:hafs-text.json'),
  ('hafs-2-231', 'hafs', 2, 231, 'وَإِذَا طَلَّقْتُمُ ٱلنِّسَآءَ فَبَلَغْنَ أَجَلَهُنَّ فَأَمْسِكُوهُنَّ بِمَعْرُوفٍ أَوْ سَرِّحُوهُنَّ بِمَعْرُوفٍۢ ۚ وَلَا تُمْسِكُوهُنَّ ضِرَارًۭا لِّتَعْتَدُوا۟ ۚ وَمَن يَفْعَلْ ذَٰلِكَ فَقَدْ ظَلَمَ نَفْسَهُۥ ۚ وَلَا تَتَّخِذُوٓا۟ ءَايَٰتِ ٱللَّهِ هُزُوًۭا ۚ وَٱذْكُرُوا۟ نِعْمَتَ ٱللَّهِ عَلَيْكُمْ وَمَآ أَنزَلَ عَلَيْكُم مِّنَ ٱلْكِتَٰبِ وَٱلْحِكْمَةِ يَعِظُكُم بِهِۦ ۚ وَٱتَّقُوا۟ ٱللَّهَ وَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ بِكُلِّ شَىْءٍ عَلِيمٌۭ', 'وإذا طلقتم النساء فبلغن أجلهن فأمسكوهن بمعروف أو سرحوهن بمعروف  ولا تمسكوهن ضرارا لتعتدوا  ومن يفعل ذلك فقد ظلم نفسه  ولا تتخذوا ءايت الله هزوا  واذكروا نعمت الله عليكم وما أنزل عليكم من الكتب والحكمة يعظكم به  واتقوا الله واعلموا أن الله بكل شىء عليم', NULL, 37, 'local:hafs-text.json'),
  ('hafs-2-232', 'hafs', 2, 232, 'وَإِذَا طَلَّقْتُمُ ٱلنِّسَآءَ فَبَلَغْنَ أَجَلَهُنَّ فَلَا تَعْضُلُوهُنَّ أَن يَنكِحْنَ أَزْوَٰجَهُنَّ إِذَا تَرَٰضَوْا۟ بَيْنَهُم بِٱلْمَعْرُوفِ ۗ ذَٰلِكَ يُوعَظُ بِهِۦ مَن كَانَ مِنكُمْ يُؤْمِنُ بِٱللَّهِ وَٱلْيَوْمِ ٱلْءَاخِرِ ۗ ذَٰلِكُمْ أَزْكَىٰ لَكُمْ وَأَطْهَرُ ۗ وَٱللَّهُ يَعْلَمُ وَأَنتُمْ لَا تَعْلَمُونَ', 'وإذا طلقتم النساء فبلغن أجلهن فلا تعضلوهن أن ينكحن أزوجهن إذا ترضوا بينهم بالمعروف  ذلك يوعظ به من كان منكم يؤمن بالله واليوم الءاخر  ذلكم أزكى لكم وأطهر  والله يعلم وأنتم لا تعلمون', NULL, 37, 'local:hafs-text.json'),
  ('hafs-2-233', 'hafs', 2, 233, '۞ وَٱلْوَٰلِدَٰتُ يُرْضِعْنَ أَوْلَٰدَهُنَّ حَوْلَيْنِ كَامِلَيْنِ ۖ لِمَنْ أَرَادَ أَن يُتِمَّ ٱلرَّضَاعَةَ ۚ وَعَلَى ٱلْمَوْلُودِ لَهُۥ رِزْقُهُنَّ وَكِسْوَتُهُنَّ بِٱلْمَعْرُوفِ ۚ لَا تُكَلَّفُ نَفْسٌ إِلَّا وُسْعَهَا ۚ لَا تُضَآرَّ وَٰلِدَةٌۢ بِوَلَدِهَا وَلَا مَوْلُودٌۭ لَّهُۥ بِوَلَدِهِۦ ۚ وَعَلَى ٱلْوَارِثِ مِثْلُ ذَٰلِكَ ۗ فَإِنْ أَرَادَا فِصَالًا عَن تَرَاضٍۢ مِّنْهُمَا وَتَشَاوُرٍۢ فَلَا جُنَاحَ عَلَيْهِمَا ۗ وَإِنْ أَرَدتُّمْ أَن تَسْتَرْضِعُوٓا۟ أَوْلَٰدَكُمْ فَلَا جُنَاحَ عَلَيْكُمْ إِذَا سَلَّمْتُم مَّآ ءَاتَيْتُم بِٱلْمَعْرُوفِ ۗ وَٱتَّقُوا۟ ٱللَّهَ وَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ بِمَا تَعْمَلُونَ بَصِيرٌۭ', 'والولدت يرضعن أولدهن حولين كاملين  لمن أراد أن يتم الرضاعة  وعلى المولود له رزقهن وكسوتهن بالمعروف  لا تكلف نفس إلا وسعها  لا تضار ولدة بولدها ولا مولود له بولده  وعلى الوارث مثل ذلك  فإن أرادا فصالا عن تراض منهما وتشاور فلا جناح عليهما  وإن أردتم أن تسترضعوا أولدكم فلا جناح عليكم إذا سلمتم ما ءاتيتم بالمعروف  واتقوا الله واعلموا أن الله بما تعملون بصير', NULL, 37, 'local:hafs-text.json'),
  ('hafs-2-234', 'hafs', 2, 234, 'وَٱلَّذِينَ يُتَوَفَّوْنَ مِنكُمْ وَيَذَرُونَ أَزْوَٰجًۭا يَتَرَبَّصْنَ بِأَنفُسِهِنَّ أَرْبَعَةَ أَشْهُرٍۢ وَعَشْرًۭا ۖ فَإِذَا بَلَغْنَ أَجَلَهُنَّ فَلَا جُنَاحَ عَلَيْكُمْ فِيمَا فَعَلْنَ فِىٓ أَنفُسِهِنَّ بِٱلْمَعْرُوفِ ۗ وَٱللَّهُ بِمَا تَعْمَلُونَ خَبِيرٌۭ', 'والذين يتوفون منكم ويذرون أزوجا يتربصن بأنفسهن أربعة أشهر وعشرا  فإذا بلغن أجلهن فلا جناح عليكم فيما فعلن فى أنفسهن بالمعروف  والله بما تعملون خبير', NULL, 38, 'local:hafs-text.json'),
  ('hafs-2-235', 'hafs', 2, 235, 'وَلَا جُنَاحَ عَلَيْكُمْ فِيمَا عَرَّضْتُم بِهِۦ مِنْ خِطْبَةِ ٱلنِّسَآءِ أَوْ أَكْنَنتُمْ فِىٓ أَنفُسِكُمْ ۚ عَلِمَ ٱللَّهُ أَنَّكُمْ سَتَذْكُرُونَهُنَّ وَلَٰكِن لَّا تُوَاعِدُوهُنَّ سِرًّا إِلَّآ أَن تَقُولُوا۟ قَوْلًۭا مَّعْرُوفًۭا ۚ وَلَا تَعْزِمُوا۟ عُقْدَةَ ٱلنِّكَاحِ حَتَّىٰ يَبْلُغَ ٱلْكِتَٰبُ أَجَلَهُۥ ۚ وَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ يَعْلَمُ مَا فِىٓ أَنفُسِكُمْ فَٱحْذَرُوهُ ۚ وَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ غَفُورٌ حَلِيمٌۭ', 'ولا جناح عليكم فيما عرضتم به من خطبة النساء أو أكننتم فى أنفسكم  علم الله أنكم ستذكرونهن ولكن لا تواعدوهن سرا إلا أن تقولوا قولا معروفا  ولا تعزموا عقدة النكاح حتى يبلغ الكتب أجله  واعلموا أن الله يعلم ما فى أنفسكم فاحذروه  واعلموا أن الله غفور حليم', NULL, 38, 'local:hafs-text.json'),
  ('hafs-2-236', 'hafs', 2, 236, 'لَّا جُنَاحَ عَلَيْكُمْ إِن طَلَّقْتُمُ ٱلنِّسَآءَ مَا لَمْ تَمَسُّوهُنَّ أَوْ تَفْرِضُوا۟ لَهُنَّ فَرِيضَةًۭ ۚ وَمَتِّعُوهُنَّ عَلَى ٱلْمُوسِعِ قَدَرُهُۥ وَعَلَى ٱلْمُقْتِرِ قَدَرُهُۥ مَتَٰعًۢا بِٱلْمَعْرُوفِ ۖ حَقًّا عَلَى ٱلْمُحْسِنِينَ', 'لا جناح عليكم إن طلقتم النساء ما لم تمسوهن أو تفرضوا لهن فريضة  ومتعوهن على الموسع قدره وعلى المقتر قدره متعا بالمعروف  حقا على المحسنين', NULL, 38, 'local:hafs-text.json'),
  ('hafs-2-237', 'hafs', 2, 237, 'وَإِن طَلَّقْتُمُوهُنَّ مِن قَبْلِ أَن تَمَسُّوهُنَّ وَقَدْ فَرَضْتُمْ لَهُنَّ فَرِيضَةًۭ فَنِصْفُ مَا فَرَضْتُمْ إِلَّآ أَن يَعْفُونَ أَوْ يَعْفُوَا۟ ٱلَّذِى بِيَدِهِۦ عُقْدَةُ ٱلنِّكَاحِ ۚ وَأَن تَعْفُوٓا۟ أَقْرَبُ لِلتَّقْوَىٰ ۚ وَلَا تَنسَوُا۟ ٱلْفَضْلَ بَيْنَكُمْ ۚ إِنَّ ٱللَّهَ بِمَا تَعْمَلُونَ بَصِيرٌ', 'وإن طلقتموهن من قبل أن تمسوهن وقد فرضتم لهن فريضة فنصف ما فرضتم إلا أن يعفون أو يعفوا الذى بيده عقدة النكاح  وأن تعفوا أقرب للتقوى  ولا تنسوا الفضل بينكم  إن الله بما تعملون بصير', NULL, 38, 'local:hafs-text.json'),
  ('hafs-2-238', 'hafs', 2, 238, 'حَٰفِظُوا۟ عَلَى ٱلصَّلَوَٰتِ وَٱلصَّلَوٰةِ ٱلْوُسْطَىٰ وَقُومُوا۟ لِلَّهِ قَٰنِتِينَ', 'حفظوا على الصلوت والصلوة الوسطى وقوموا لله قنتين', NULL, 39, 'local:hafs-text.json'),
  ('hafs-2-239', 'hafs', 2, 239, 'فَإِنْ خِفْتُمْ فَرِجَالًا أَوْ رُكْبَانًۭا ۖ فَإِذَآ أَمِنتُمْ فَٱذْكُرُوا۟ ٱللَّهَ كَمَا عَلَّمَكُم مَّا لَمْ تَكُونُوا۟ تَعْلَمُونَ', 'فإن خفتم فرجالا أو ركبانا  فإذا أمنتم فاذكروا الله كما علمكم ما لم تكونوا تعلمون', NULL, 39, 'local:hafs-text.json'),
  ('hafs-2-240', 'hafs', 2, 240, 'وَٱلَّذِينَ يُتَوَفَّوْنَ مِنكُمْ وَيَذَرُونَ أَزْوَٰجًۭا وَصِيَّةًۭ لِّأَزْوَٰجِهِم مَّتَٰعًا إِلَى ٱلْحَوْلِ غَيْرَ إِخْرَاجٍۢ ۚ فَإِنْ خَرَجْنَ فَلَا جُنَاحَ عَلَيْكُمْ فِى مَا فَعَلْنَ فِىٓ أَنفُسِهِنَّ مِن مَّعْرُوفٍۢ ۗ وَٱللَّهُ عَزِيزٌ حَكِيمٌۭ', 'والذين يتوفون منكم ويذرون أزوجا وصية لأزوجهم متعا إلى الحول غير إخراج  فإن خرجن فلا جناح عليكم فى ما فعلن فى أنفسهن من معروف  والله عزيز حكيم', NULL, 39, 'local:hafs-text.json'),
  ('hafs-2-241', 'hafs', 2, 241, 'وَلِلْمُطَلَّقَٰتِ مَتَٰعٌۢ بِٱلْمَعْرُوفِ ۖ حَقًّا عَلَى ٱلْمُتَّقِينَ', 'وللمطلقت متع بالمعروف  حقا على المتقين', NULL, 39, 'local:hafs-text.json'),
  ('hafs-2-242', 'hafs', 2, 242, 'كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ لَكُمْ ءَايَٰتِهِۦ لَعَلَّكُمْ تَعْقِلُونَ', 'كذلك يبين الله لكم ءايته لعلكم تعقلون', NULL, 39, 'local:hafs-text.json'),
  ('hafs-2-243', 'hafs', 2, 243, '۞ أَلَمْ تَرَ إِلَى ٱلَّذِينَ خَرَجُوا۟ مِن دِيَٰرِهِمْ وَهُمْ أُلُوفٌ حَذَرَ ٱلْمَوْتِ فَقَالَ لَهُمُ ٱللَّهُ مُوتُوا۟ ثُمَّ أَحْيَٰهُمْ ۚ إِنَّ ٱللَّهَ لَذُو فَضْلٍ عَلَى ٱلنَّاسِ وَلَٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يَشْكُرُونَ', 'ألم تر إلى الذين خرجوا من ديرهم وهم ألوف حذر الموت فقال لهم الله موتوا ثم أحيهم  إن الله لذو فضل على الناس ولكن أكثر الناس لا يشكرون', NULL, 39, 'local:hafs-text.json'),
  ('hafs-2-244', 'hafs', 2, 244, 'وَقَٰتِلُوا۟ فِى سَبِيلِ ٱللَّهِ وَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ سَمِيعٌ عَلِيمٌۭ', 'وقتلوا فى سبيل الله واعلموا أن الله سميع عليم', NULL, 39, 'local:hafs-text.json'),
  ('hafs-2-245', 'hafs', 2, 245, 'مَّن ذَا ٱلَّذِى يُقْرِضُ ٱللَّهَ قَرْضًا حَسَنًۭا فَيُضَٰعِفَهُۥ لَهُۥٓ أَضْعَافًۭا كَثِيرَةًۭ ۚ وَٱللَّهُ يَقْبِضُ وَيَبْصُۜطُ وَإِلَيْهِ تُرْجَعُونَ', 'من ذا الذى يقرض الله قرضا حسنا فيضعفه له أضعافا كثيرة  والله يقبض ويبصط وإليه ترجعون', NULL, 39, 'local:hafs-text.json'),
  ('hafs-2-246', 'hafs', 2, 246, 'أَلَمْ تَرَ إِلَى ٱلْمَلَإِ مِنۢ بَنِىٓ إِسْرَٰٓءِيلَ مِنۢ بَعْدِ مُوسَىٰٓ إِذْ قَالُوا۟ لِنَبِىٍّۢ لَّهُمُ ٱبْعَثْ لَنَا مَلِكًۭا نُّقَٰتِلْ فِى سَبِيلِ ٱللَّهِ ۖ قَالَ هَلْ عَسَيْتُمْ إِن كُتِبَ عَلَيْكُمُ ٱلْقِتَالُ أَلَّا تُقَٰتِلُوا۟ ۖ قَالُوا۟ وَمَا لَنَآ أَلَّا نُقَٰتِلَ فِى سَبِيلِ ٱللَّهِ وَقَدْ أُخْرِجْنَا مِن دِيَٰرِنَا وَأَبْنَآئِنَا ۖ فَلَمَّا كُتِبَ عَلَيْهِمُ ٱلْقِتَالُ تَوَلَّوْا۟ إِلَّا قَلِيلًۭا مِّنْهُمْ ۗ وَٱللَّهُ عَلِيمٌۢ بِٱلظَّٰلِمِينَ', 'ألم تر إلى الملإ من بنى إسرءيل من بعد موسى إذ قالوا لنبى لهم ابعث لنا ملكا نقتل فى سبيل الله  قال هل عسيتم إن كتب عليكم القتال ألا تقتلوا  قالوا وما لنا ألا نقتل فى سبيل الله وقد أخرجنا من ديرنا وأبنائنا  فلما كتب عليهم القتال تولوا إلا قليلا منهم  والله عليم بالظلمين', NULL, 40, 'local:hafs-text.json'),
  ('hafs-2-247', 'hafs', 2, 247, 'وَقَالَ لَهُمْ نَبِيُّهُمْ إِنَّ ٱللَّهَ قَدْ بَعَثَ لَكُمْ طَالُوتَ مَلِكًۭا ۚ قَالُوٓا۟ أَنَّىٰ يَكُونُ لَهُ ٱلْمُلْكُ عَلَيْنَا وَنَحْنُ أَحَقُّ بِٱلْمُلْكِ مِنْهُ وَلَمْ يُؤْتَ سَعَةًۭ مِّنَ ٱلْمَالِ ۚ قَالَ إِنَّ ٱللَّهَ ٱصْطَفَىٰهُ عَلَيْكُمْ وَزَادَهُۥ بَسْطَةًۭ فِى ٱلْعِلْمِ وَٱلْجِسْمِ ۖ وَٱللَّهُ يُؤْتِى مُلْكَهُۥ مَن يَشَآءُ ۚ وَٱللَّهُ وَٰسِعٌ عَلِيمٌۭ', 'وقال لهم نبيهم إن الله قد بعث لكم طالوت ملكا  قالوا أنى يكون له الملك علينا ونحن أحق بالملك منه ولم يؤت سعة من المال  قال إن الله اصطفىه عليكم وزاده بسطة فى العلم والجسم  والله يؤتى ملكه من يشاء  والله وسع عليم', NULL, 40, 'local:hafs-text.json'),
  ('hafs-2-248', 'hafs', 2, 248, 'وَقَالَ لَهُمْ نَبِيُّهُمْ إِنَّ ءَايَةَ مُلْكِهِۦٓ أَن يَأْتِيَكُمُ ٱلتَّابُوتُ فِيهِ سَكِينَةٌۭ مِّن رَّبِّكُمْ وَبَقِيَّةٌۭ مِّمَّا تَرَكَ ءَالُ مُوسَىٰ وَءَالُ هَٰرُونَ تَحْمِلُهُ ٱلْمَلَٰٓئِكَةُ ۚ إِنَّ فِى ذَٰلِكَ لَءَايَةًۭ لَّكُمْ إِن كُنتُم مُّؤْمِنِينَ', 'وقال لهم نبيهم إن ءاية ملكه أن يأتيكم التابوت فيه سكينة من ربكم وبقية مما ترك ءال موسى وءال هرون تحمله الملئكة  إن فى ذلك لءاية لكم إن كنتم مؤمنين', NULL, 40, 'local:hafs-text.json'),
  ('hafs-2-249', 'hafs', 2, 249, 'فَلَمَّا فَصَلَ طَالُوتُ بِٱلْجُنُودِ قَالَ إِنَّ ٱللَّهَ مُبْتَلِيكُم بِنَهَرٍۢ فَمَن شَرِبَ مِنْهُ فَلَيْسَ مِنِّى وَمَن لَّمْ يَطْعَمْهُ فَإِنَّهُۥ مِنِّىٓ إِلَّا مَنِ ٱغْتَرَفَ غُرْفَةًۢ بِيَدِهِۦ ۚ فَشَرِبُوا۟ مِنْهُ إِلَّا قَلِيلًۭا مِّنْهُمْ ۚ فَلَمَّا جَاوَزَهُۥ هُوَ وَٱلَّذِينَ ءَامَنُوا۟ مَعَهُۥ قَالُوا۟ لَا طَاقَةَ لَنَا ٱلْيَوْمَ بِجَالُوتَ وَجُنُودِهِۦ ۚ قَالَ ٱلَّذِينَ يَظُنُّونَ أَنَّهُم مُّلَٰقُوا۟ ٱللَّهِ كَم مِّن فِئَةٍۢ قَلِيلَةٍ غَلَبَتْ فِئَةًۭ كَثِيرَةًۢ بِإِذْنِ ٱللَّهِ ۗ وَٱللَّهُ مَعَ ٱلصَّٰبِرِينَ', 'فلما فصل طالوت بالجنود قال إن الله مبتليكم بنهر فمن شرب منه فليس منى ومن لم يطعمه فإنه منى إلا من اغترف غرفة بيده  فشربوا منه إلا قليلا منهم  فلما جاوزه هو والذين ءامنوا معه قالوا لا طاقة لنا اليوم بجالوت وجنوده  قال الذين يظنون أنهم ملقوا الله كم من فئة قليلة غلبت فئة كثيرة بإذن الله  والله مع الصبرين', NULL, 41, 'local:hafs-text.json'),
  ('hafs-2-250', 'hafs', 2, 250, 'وَلَمَّا بَرَزُوا۟ لِجَالُوتَ وَجُنُودِهِۦ قَالُوا۟ رَبَّنَآ أَفْرِغْ عَلَيْنَا صَبْرًۭا وَثَبِّتْ أَقْدَامَنَا وَٱنصُرْنَا عَلَى ٱلْقَوْمِ ٱلْكَٰفِرِينَ', 'ولما برزوا لجالوت وجنوده قالوا ربنا أفرغ علينا صبرا وثبت أقدامنا وانصرنا على القوم الكفرين', NULL, 41, 'local:hafs-text.json'),
  ('hafs-2-251', 'hafs', 2, 251, 'فَهَزَمُوهُم بِإِذْنِ ٱللَّهِ وَقَتَلَ دَاوُۥدُ جَالُوتَ وَءَاتَىٰهُ ٱللَّهُ ٱلْمُلْكَ وَٱلْحِكْمَةَ وَعَلَّمَهُۥ مِمَّا يَشَآءُ ۗ وَلَوْلَا دَفْعُ ٱللَّهِ ٱلنَّاسَ بَعْضَهُم بِبَعْضٍۢ لَّفَسَدَتِ ٱلْأَرْضُ وَلَٰكِنَّ ٱللَّهَ ذُو فَضْلٍ عَلَى ٱلْعَٰلَمِينَ', 'فهزموهم بإذن الله وقتل داود جالوت وءاتىه الله الملك والحكمة وعلمه مما يشاء  ولولا دفع الله الناس بعضهم ببعض لفسدت الأرض ولكن الله ذو فضل على العلمين', NULL, 41, 'local:hafs-text.json'),
  ('hafs-2-252', 'hafs', 2, 252, 'تِلْكَ ءَايَٰتُ ٱللَّهِ نَتْلُوهَا عَلَيْكَ بِٱلْحَقِّ ۚ وَإِنَّكَ لَمِنَ ٱلْمُرْسَلِينَ', 'تلك ءايت الله نتلوها عليك بالحق  وإنك لمن المرسلين', NULL, 41, 'local:hafs-text.json'),
  ('hafs-2-253', 'hafs', 2, 253, '۞ تِلْكَ ٱلرُّسُلُ فَضَّلْنَا بَعْضَهُمْ عَلَىٰ بَعْضٍۢ ۘ مِّنْهُم مَّن كَلَّمَ ٱللَّهُ ۖ وَرَفَعَ بَعْضَهُمْ دَرَجَٰتٍۢ ۚ وَءَاتَيْنَا عِيسَى ٱبْنَ مَرْيَمَ ٱلْبَيِّنَٰتِ وَأَيَّدْنَٰهُ بِرُوحِ ٱلْقُدُسِ ۗ وَلَوْ شَآءَ ٱللَّهُ مَا ٱقْتَتَلَ ٱلَّذِينَ مِنۢ بَعْدِهِم مِّنۢ بَعْدِ مَا جَآءَتْهُمُ ٱلْبَيِّنَٰتُ وَلَٰكِنِ ٱخْتَلَفُوا۟ فَمِنْهُم مَّنْ ءَامَنَ وَمِنْهُم مَّن كَفَرَ ۚ وَلَوْ شَآءَ ٱللَّهُ مَا ٱقْتَتَلُوا۟ وَلَٰكِنَّ ٱللَّهَ يَفْعَلُ مَا يُرِيدُ', 'تلك الرسل فضلنا بعضهم على بعض  منهم من كلم الله  ورفع بعضهم درجت  وءاتينا عيسى ابن مريم البينت وأيدنه بروح القدس  ولو شاء الله ما اقتتل الذين من بعدهم من بعد ما جاءتهم البينت ولكن اختلفوا فمنهم من ءامن ومنهم من كفر  ولو شاء الله ما اقتتلوا ولكن الله يفعل ما يريد', NULL, 42, 'local:hafs-text.json'),
  ('hafs-2-254', 'hafs', 2, 254, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ أَنفِقُوا۟ مِمَّا رَزَقْنَٰكُم مِّن قَبْلِ أَن يَأْتِىَ يَوْمٌۭ لَّا بَيْعٌۭ فِيهِ وَلَا خُلَّةٌۭ وَلَا شَفَٰعَةٌۭ ۗ وَٱلْكَٰفِرُونَ هُمُ ٱلظَّٰلِمُونَ', 'يأيها الذين ءامنوا أنفقوا مما رزقنكم من قبل أن يأتى يوم لا بيع فيه ولا خلة ولا شفعة  والكفرون هم الظلمون', NULL, 42, 'local:hafs-text.json'),
  ('hafs-2-255', 'hafs', 2, 255, 'ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَ ٱلْحَىُّ ٱلْقَيُّومُ ۚ لَا تَأْخُذُهُۥ سِنَةٌۭ وَلَا نَوْمٌۭ ۚ لَّهُۥ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ ۗ مَن ذَا ٱلَّذِى يَشْفَعُ عِندَهُۥٓ إِلَّا بِإِذْنِهِۦ ۚ يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ ۖ وَلَا يُحِيطُونَ بِشَىْءٍۢ مِّنْ عِلْمِهِۦٓ إِلَّا بِمَا شَآءَ ۚ وَسِعَ كُرْسِيُّهُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ ۖ وَلَا يَـُٔودُهُۥ حِفْظُهُمَا ۚ وَهُوَ ٱلْعَلِىُّ ٱلْعَظِيمُ', 'الله لا إله إلا هو الحى القيوم  لا تأخذه سنة ولا نوم  له ما فى السموت وما فى الأرض  من ذا الذى يشفع عنده إلا بإذنه  يعلم ما بين أيديهم وما خلفهم  ولا يحيطون بشىء من علمه إلا بما شاء  وسع كرسيه السموت والأرض  ولا يوده حفظهما  وهو العلى العظيم', NULL, 42, 'local:hafs-text.json'),
  ('hafs-2-256', 'hafs', 2, 256, 'لَآ إِكْرَاهَ فِى ٱلدِّينِ ۖ قَد تَّبَيَّنَ ٱلرُّشْدُ مِنَ ٱلْغَىِّ ۚ فَمَن يَكْفُرْ بِٱلطَّٰغُوتِ وَيُؤْمِنۢ بِٱللَّهِ فَقَدِ ٱسْتَمْسَكَ بِٱلْعُرْوَةِ ٱلْوُثْقَىٰ لَا ٱنفِصَامَ لَهَا ۗ وَٱللَّهُ سَمِيعٌ عَلِيمٌ', 'لا إكراه فى الدين  قد تبين الرشد من الغى  فمن يكفر بالطغوت ويؤمن بالله فقد استمسك بالعروة الوثقى لا انفصام لها  والله سميع عليم', NULL, 42, 'local:hafs-text.json'),
  ('hafs-2-257', 'hafs', 2, 257, 'ٱللَّهُ وَلِىُّ ٱلَّذِينَ ءَامَنُوا۟ يُخْرِجُهُم مِّنَ ٱلظُّلُمَٰتِ إِلَى ٱلنُّورِ ۖ وَٱلَّذِينَ كَفَرُوٓا۟ أَوْلِيَآؤُهُمُ ٱلطَّٰغُوتُ يُخْرِجُونَهُم مِّنَ ٱلنُّورِ إِلَى ٱلظُّلُمَٰتِ ۗ أُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلنَّارِ ۖ هُمْ فِيهَا خَٰلِدُونَ', 'الله ولى الذين ءامنوا يخرجهم من الظلمت إلى النور  والذين كفروا أولياؤهم الطغوت يخرجونهم من النور إلى الظلمت  أولئك أصحب النار  هم فيها خلدون', NULL, 43, 'local:hafs-text.json'),
  ('hafs-2-258', 'hafs', 2, 258, 'أَلَمْ تَرَ إِلَى ٱلَّذِى حَآجَّ إِبْرَٰهِۦمَ فِى رَبِّهِۦٓ أَنْ ءَاتَىٰهُ ٱللَّهُ ٱلْمُلْكَ إِذْ قَالَ إِبْرَٰهِۦمُ رَبِّىَ ٱلَّذِى يُحْىِۦ وَيُمِيتُ قَالَ أَنَا۠ أُحْىِۦ وَأُمِيتُ ۖ قَالَ إِبْرَٰهِۦمُ فَإِنَّ ٱللَّهَ يَأْتِى بِٱلشَّمْسِ مِنَ ٱلْمَشْرِقِ فَأْتِ بِهَا مِنَ ٱلْمَغْرِبِ فَبُهِتَ ٱلَّذِى كَفَرَ ۗ وَٱللَّهُ لَا يَهْدِى ٱلْقَوْمَ ٱلظَّٰلِمِينَ', 'ألم تر إلى الذى حاج إبرهم فى ربه أن ءاتىه الله الملك إذ قال إبرهم ربى الذى يحى ويميت قال أنا أحى وأميت  قال إبرهم فإن الله يأتى بالشمس من المشرق فأت بها من المغرب فبهت الذى كفر  والله لا يهدى القوم الظلمين', NULL, 43, 'local:hafs-text.json'),
  ('hafs-2-259', 'hafs', 2, 259, 'أَوْ كَٱلَّذِى مَرَّ عَلَىٰ قَرْيَةٍۢ وَهِىَ خَاوِيَةٌ عَلَىٰ عُرُوشِهَا قَالَ أَنَّىٰ يُحْىِۦ هَٰذِهِ ٱللَّهُ بَعْدَ مَوْتِهَا ۖ فَأَمَاتَهُ ٱللَّهُ مِا۟ئَةَ عَامٍۢ ثُمَّ بَعَثَهُۥ ۖ قَالَ كَمْ لَبِثْتَ ۖ قَالَ لَبِثْتُ يَوْمًا أَوْ بَعْضَ يَوْمٍۢ ۖ قَالَ بَل لَّبِثْتَ مِا۟ئَةَ عَامٍۢ فَٱنظُرْ إِلَىٰ طَعَامِكَ وَشَرَابِكَ لَمْ يَتَسَنَّهْ ۖ وَٱنظُرْ إِلَىٰ حِمَارِكَ وَلِنَجْعَلَكَ ءَايَةًۭ لِّلنَّاسِ ۖ وَٱنظُرْ إِلَى ٱلْعِظَامِ كَيْفَ نُنشِزُهَا ثُمَّ نَكْسُوهَا لَحْمًۭا ۚ فَلَمَّا تَبَيَّنَ لَهُۥ قَالَ أَعْلَمُ أَنَّ ٱللَّهَ عَلَىٰ كُلِّ شَىْءٍۢ قَدِيرٌۭ', 'أو كالذى مر على قرية وهى خاوية على عروشها قال أنى يحى هذه الله بعد موتها  فأماته الله مائة عام ثم بعثه  قال كم لبثت  قال لبثت يوما أو بعض يوم  قال بل لبثت مائة عام فانظر إلى طعامك وشرابك لم يتسنه  وانظر إلى حمارك ولنجعلك ءاية للناس  وانظر إلى العظام كيف ننشزها ثم نكسوها لحما  فلما تبين له قال أعلم أن الله على كل شىء قدير', NULL, 43, 'local:hafs-text.json'),
  ('hafs-2-260', 'hafs', 2, 260, 'وَإِذْ قَالَ إِبْرَٰهِۦمُ رَبِّ أَرِنِى كَيْفَ تُحْىِ ٱلْمَوْتَىٰ ۖ قَالَ أَوَلَمْ تُؤْمِن ۖ قَالَ بَلَىٰ وَلَٰكِن لِّيَطْمَئِنَّ قَلْبِى ۖ قَالَ فَخُذْ أَرْبَعَةًۭ مِّنَ ٱلطَّيْرِ فَصُرْهُنَّ إِلَيْكَ ثُمَّ ٱجْعَلْ عَلَىٰ كُلِّ جَبَلٍۢ مِّنْهُنَّ جُزْءًۭا ثُمَّ ٱدْعُهُنَّ يَأْتِينَكَ سَعْيًۭا ۚ وَٱعْلَمْ أَنَّ ٱللَّهَ عَزِيزٌ حَكِيمٌۭ', 'وإذ قال إبرهم رب أرنى كيف تحى الموتى  قال أولم تؤمن  قال بلى ولكن ليطمئن قلبى  قال فخذ أربعة من الطير فصرهن إليك ثم اجعل على كل جبل منهن جزءا ثم ادعهن يأتينك سعيا  واعلم أن الله عزيز حكيم', NULL, 44, 'local:hafs-text.json'),
  ('hafs-2-261', 'hafs', 2, 261, 'مَّثَلُ ٱلَّذِينَ يُنفِقُونَ أَمْوَٰلَهُمْ فِى سَبِيلِ ٱللَّهِ كَمَثَلِ حَبَّةٍ أَنۢبَتَتْ سَبْعَ سَنَابِلَ فِى كُلِّ سُنۢبُلَةٍۢ مِّا۟ئَةُ حَبَّةٍۢ ۗ وَٱللَّهُ يُضَٰعِفُ لِمَن يَشَآءُ ۗ وَٱللَّهُ وَٰسِعٌ عَلِيمٌ', 'مثل الذين ينفقون أمولهم فى سبيل الله كمثل حبة أنبتت سبع سنابل فى كل سنبلة مائة حبة  والله يضعف لمن يشاء  والله وسع عليم', NULL, 44, 'local:hafs-text.json'),
  ('hafs-2-262', 'hafs', 2, 262, 'ٱلَّذِينَ يُنفِقُونَ أَمْوَٰلَهُمْ فِى سَبِيلِ ٱللَّهِ ثُمَّ لَا يُتْبِعُونَ مَآ أَنفَقُوا۟ مَنًّۭا وَلَآ أَذًۭى ۙ لَّهُمْ أَجْرُهُمْ عِندَ رَبِّهِمْ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ', 'الذين ينفقون أمولهم فى سبيل الله ثم لا يتبعون ما أنفقوا منا ولا أذى  لهم أجرهم عند ربهم ولا خوف عليهم ولا هم يحزنون', NULL, 44, 'local:hafs-text.json'),
  ('hafs-2-263', 'hafs', 2, 263, '۞ قَوْلٌۭ مَّعْرُوفٌۭ وَمَغْفِرَةٌ خَيْرٌۭ مِّن صَدَقَةٍۢ يَتْبَعُهَآ أَذًۭى ۗ وَٱللَّهُ غَنِىٌّ حَلِيمٌۭ', 'قول معروف ومغفرة خير من صدقة يتبعها أذى  والله غنى حليم', NULL, 44, 'local:hafs-text.json'),
  ('hafs-2-264', 'hafs', 2, 264, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تُبْطِلُوا۟ صَدَقَٰتِكُم بِٱلْمَنِّ وَٱلْأَذَىٰ كَٱلَّذِى يُنفِقُ مَالَهُۥ رِئَآءَ ٱلنَّاسِ وَلَا يُؤْمِنُ بِٱللَّهِ وَٱلْيَوْمِ ٱلْءَاخِرِ ۖ فَمَثَلُهُۥ كَمَثَلِ صَفْوَانٍ عَلَيْهِ تُرَابٌۭ فَأَصَابَهُۥ وَابِلٌۭ فَتَرَكَهُۥ صَلْدًۭا ۖ لَّا يَقْدِرُونَ عَلَىٰ شَىْءٍۢ مِّمَّا كَسَبُوا۟ ۗ وَٱللَّهُ لَا يَهْدِى ٱلْقَوْمَ ٱلْكَٰفِرِينَ', 'يأيها الذين ءامنوا لا تبطلوا صدقتكم بالمن والأذى كالذى ينفق ماله رئاء الناس ولا يؤمن بالله واليوم الءاخر  فمثله كمثل صفوان عليه تراب فأصابه وابل فتركه صلدا  لا يقدرون على شىء مما كسبوا  والله لا يهدى القوم الكفرين', NULL, 44, 'local:hafs-text.json'),
  ('hafs-2-265', 'hafs', 2, 265, 'وَمَثَلُ ٱلَّذِينَ يُنفِقُونَ أَمْوَٰلَهُمُ ٱبْتِغَآءَ مَرْضَاتِ ٱللَّهِ وَتَثْبِيتًۭا مِّنْ أَنفُسِهِمْ كَمَثَلِ جَنَّةٍۭ بِرَبْوَةٍ أَصَابَهَا وَابِلٌۭ فَـَٔاتَتْ أُكُلَهَا ضِعْفَيْنِ فَإِن لَّمْ يُصِبْهَا وَابِلٌۭ فَطَلٌّۭ ۗ وَٱللَّهُ بِمَا تَعْمَلُونَ بَصِيرٌ', 'ومثل الذين ينفقون أمولهم ابتغاء مرضات الله وتثبيتا من أنفسهم كمثل جنة بربوة أصابها وابل فاتت أكلها ضعفين فإن لم يصبها وابل فطل  والله بما تعملون بصير', NULL, 45, 'local:hafs-text.json'),
  ('hafs-2-266', 'hafs', 2, 266, 'أَيَوَدُّ أَحَدُكُمْ أَن تَكُونَ لَهُۥ جَنَّةٌۭ مِّن نَّخِيلٍۢ وَأَعْنَابٍۢ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ لَهُۥ فِيهَا مِن كُلِّ ٱلثَّمَرَٰتِ وَأَصَابَهُ ٱلْكِبَرُ وَلَهُۥ ذُرِّيَّةٌۭ ضُعَفَآءُ فَأَصَابَهَآ إِعْصَارٌۭ فِيهِ نَارٌۭ فَٱحْتَرَقَتْ ۗ كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ لَكُمُ ٱلْءَايَٰتِ لَعَلَّكُمْ تَتَفَكَّرُونَ', 'أيود أحدكم أن تكون له جنة من نخيل وأعناب تجرى من تحتها الأنهر له فيها من كل الثمرت وأصابه الكبر وله ذرية ضعفاء فأصابها إعصار فيه نار فاحترقت  كذلك يبين الله لكم الءايت لعلكم تتفكرون', NULL, 45, 'local:hafs-text.json'),
  ('hafs-2-267', 'hafs', 2, 267, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ أَنفِقُوا۟ مِن طَيِّبَٰتِ مَا كَسَبْتُمْ وَمِمَّآ أَخْرَجْنَا لَكُم مِّنَ ٱلْأَرْضِ ۖ وَلَا تَيَمَّمُوا۟ ٱلْخَبِيثَ مِنْهُ تُنفِقُونَ وَلَسْتُم بِـَٔاخِذِيهِ إِلَّآ أَن تُغْمِضُوا۟ فِيهِ ۚ وَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ غَنِىٌّ حَمِيدٌ', 'يأيها الذين ءامنوا أنفقوا من طيبت ما كسبتم ومما أخرجنا لكم من الأرض  ولا تيمموا الخبيث منه تنفقون ولستم باخذيه إلا أن تغمضوا فيه  واعلموا أن الله غنى حميد', NULL, 45, 'local:hafs-text.json'),
  ('hafs-2-268', 'hafs', 2, 268, 'ٱلشَّيْطَٰنُ يَعِدُكُمُ ٱلْفَقْرَ وَيَأْمُرُكُم بِٱلْفَحْشَآءِ ۖ وَٱللَّهُ يَعِدُكُم مَّغْفِرَةًۭ مِّنْهُ وَفَضْلًۭا ۗ وَٱللَّهُ وَٰسِعٌ عَلِيمٌۭ', 'الشيطن يعدكم الفقر ويأمركم بالفحشاء  والله يعدكم مغفرة منه وفضلا  والله وسع عليم', NULL, 45, 'local:hafs-text.json'),
  ('hafs-2-269', 'hafs', 2, 269, 'يُؤْتِى ٱلْحِكْمَةَ مَن يَشَآءُ ۚ وَمَن يُؤْتَ ٱلْحِكْمَةَ فَقَدْ أُوتِىَ خَيْرًۭا كَثِيرًۭا ۗ وَمَا يَذَّكَّرُ إِلَّآ أُو۟لُوا۟ ٱلْأَلْبَٰبِ', 'يؤتى الحكمة من يشاء  ومن يؤت الحكمة فقد أوتى خيرا كثيرا  وما يذكر إلا أولوا الألبب', NULL, 45, 'local:hafs-text.json'),
  ('hafs-2-270', 'hafs', 2, 270, 'وَمَآ أَنفَقْتُم مِّن نَّفَقَةٍ أَوْ نَذَرْتُم مِّن نَّذْرٍۢ فَإِنَّ ٱللَّهَ يَعْلَمُهُۥ ۗ وَمَا لِلظَّٰلِمِينَ مِنْ أَنصَارٍ', 'وما أنفقتم من نفقة أو نذرتم من نذر فإن الله يعلمه  وما للظلمين من أنصار', NULL, 46, 'local:hafs-text.json'),
  ('hafs-2-271', 'hafs', 2, 271, 'إِن تُبْدُوا۟ ٱلصَّدَقَٰتِ فَنِعِمَّا هِىَ ۖ وَإِن تُخْفُوهَا وَتُؤْتُوهَا ٱلْفُقَرَآءَ فَهُوَ خَيْرٌۭ لَّكُمْ ۚ وَيُكَفِّرُ عَنكُم مِّن سَيِّـَٔاتِكُمْ ۗ وَٱللَّهُ بِمَا تَعْمَلُونَ خَبِيرٌۭ', 'إن تبدوا الصدقت فنعما هى  وإن تخفوها وتؤتوها الفقراء فهو خير لكم  ويكفر عنكم من سياتكم  والله بما تعملون خبير', NULL, 46, 'local:hafs-text.json'),
  ('hafs-2-272', 'hafs', 2, 272, '۞ لَّيْسَ عَلَيْكَ هُدَىٰهُمْ وَلَٰكِنَّ ٱللَّهَ يَهْدِى مَن يَشَآءُ ۗ وَمَا تُنفِقُوا۟ مِنْ خَيْرٍۢ فَلِأَنفُسِكُمْ ۚ وَمَا تُنفِقُونَ إِلَّا ٱبْتِغَآءَ وَجْهِ ٱللَّهِ ۚ وَمَا تُنفِقُوا۟ مِنْ خَيْرٍۢ يُوَفَّ إِلَيْكُمْ وَأَنتُمْ لَا تُظْلَمُونَ', 'ليس عليك هدىهم ولكن الله يهدى من يشاء  وما تنفقوا من خير فلأنفسكم  وما تنفقون إلا ابتغاء وجه الله  وما تنفقوا من خير يوف إليكم وأنتم لا تظلمون', NULL, 46, 'local:hafs-text.json'),
  ('hafs-2-273', 'hafs', 2, 273, 'لِلْفُقَرَآءِ ٱلَّذِينَ أُحْصِرُوا۟ فِى سَبِيلِ ٱللَّهِ لَا يَسْتَطِيعُونَ ضَرْبًۭا فِى ٱلْأَرْضِ يَحْسَبُهُمُ ٱلْجَاهِلُ أَغْنِيَآءَ مِنَ ٱلتَّعَفُّفِ تَعْرِفُهُم بِسِيمَٰهُمْ لَا يَسْـَٔلُونَ ٱلنَّاسَ إِلْحَافًۭا ۗ وَمَا تُنفِقُوا۟ مِنْ خَيْرٍۢ فَإِنَّ ٱللَّهَ بِهِۦ عَلِيمٌ', 'للفقراء الذين أحصروا فى سبيل الله لا يستطيعون ضربا فى الأرض يحسبهم الجاهل أغنياء من التعفف تعرفهم بسيمهم لا يسلون الناس إلحافا  وما تنفقوا من خير فإن الله به عليم', NULL, 46, 'local:hafs-text.json'),
  ('hafs-2-274', 'hafs', 2, 274, 'ٱلَّذِينَ يُنفِقُونَ أَمْوَٰلَهُم بِٱلَّيْلِ وَٱلنَّهَارِ سِرًّۭا وَعَلَانِيَةًۭ فَلَهُمْ أَجْرُهُمْ عِندَ رَبِّهِمْ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ', 'الذين ينفقون أمولهم باليل والنهار سرا وعلانية فلهم أجرهم عند ربهم ولا خوف عليهم ولا هم يحزنون', NULL, 46, 'local:hafs-text.json'),
  ('hafs-2-275', 'hafs', 2, 275, 'ٱلَّذِينَ يَأْكُلُونَ ٱلرِّبَوٰا۟ لَا يَقُومُونَ إِلَّا كَمَا يَقُومُ ٱلَّذِى يَتَخَبَّطُهُ ٱلشَّيْطَٰنُ مِنَ ٱلْمَسِّ ۚ ذَٰلِكَ بِأَنَّهُمْ قَالُوٓا۟ إِنَّمَا ٱلْبَيْعُ مِثْلُ ٱلرِّبَوٰا۟ ۗ وَأَحَلَّ ٱللَّهُ ٱلْبَيْعَ وَحَرَّمَ ٱلرِّبَوٰا۟ ۚ فَمَن جَآءَهُۥ مَوْعِظَةٌۭ مِّن رَّبِّهِۦ فَٱنتَهَىٰ فَلَهُۥ مَا سَلَفَ وَأَمْرُهُۥٓ إِلَى ٱللَّهِ ۖ وَمَنْ عَادَ فَأُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلنَّارِ ۖ هُمْ فِيهَا خَٰلِدُونَ', 'الذين يأكلون الربوا لا يقومون إلا كما يقوم الذى يتخبطه الشيطن من المس  ذلك بأنهم قالوا إنما البيع مثل الربوا  وأحل الله البيع وحرم الربوا  فمن جاءه موعظة من ربه فانتهى فله ما سلف وأمره إلى الله  ومن عاد فأولئك أصحب النار  هم فيها خلدون', NULL, 47, 'local:hafs-text.json'),
  ('hafs-2-276', 'hafs', 2, 276, 'يَمْحَقُ ٱللَّهُ ٱلرِّبَوٰا۟ وَيُرْبِى ٱلصَّدَقَٰتِ ۗ وَٱللَّهُ لَا يُحِبُّ كُلَّ كَفَّارٍ أَثِيمٍ', 'يمحق الله الربوا ويربى الصدقت  والله لا يحب كل كفار أثيم', NULL, 47, 'local:hafs-text.json'),
  ('hafs-2-277', 'hafs', 2, 277, 'إِنَّ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ وَأَقَامُوا۟ ٱلصَّلَوٰةَ وَءَاتَوُا۟ ٱلزَّكَوٰةَ لَهُمْ أَجْرُهُمْ عِندَ رَبِّهِمْ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ', 'إن الذين ءامنوا وعملوا الصلحت وأقاموا الصلوة وءاتوا الزكوة لهم أجرهم عند ربهم ولا خوف عليهم ولا هم يحزنون', NULL, 47, 'local:hafs-text.json'),
  ('hafs-2-278', 'hafs', 2, 278, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱتَّقُوا۟ ٱللَّهَ وَذَرُوا۟ مَا بَقِىَ مِنَ ٱلرِّبَوٰٓا۟ إِن كُنتُم مُّؤْمِنِينَ', 'يأيها الذين ءامنوا اتقوا الله وذروا ما بقى من الربوا إن كنتم مؤمنين', NULL, 47, 'local:hafs-text.json'),
  ('hafs-2-279', 'hafs', 2, 279, 'فَإِن لَّمْ تَفْعَلُوا۟ فَأْذَنُوا۟ بِحَرْبٍۢ مِّنَ ٱللَّهِ وَرَسُولِهِۦ ۖ وَإِن تُبْتُمْ فَلَكُمْ رُءُوسُ أَمْوَٰلِكُمْ لَا تَظْلِمُونَ وَلَا تُظْلَمُونَ', 'فإن لم تفعلوا فأذنوا بحرب من الله ورسوله  وإن تبتم فلكم رءوس أمولكم لا تظلمون ولا تظلمون', NULL, 47, 'local:hafs-text.json'),
  ('hafs-2-280', 'hafs', 2, 280, 'وَإِن كَانَ ذُو عُسْرَةٍۢ فَنَظِرَةٌ إِلَىٰ مَيْسَرَةٍۢ ۚ وَأَن تَصَدَّقُوا۟ خَيْرٌۭ لَّكُمْ ۖ إِن كُنتُمْ تَعْلَمُونَ', 'وإن كان ذو عسرة فنظرة إلى ميسرة  وأن تصدقوا خير لكم  إن كنتم تعلمون', NULL, 47, 'local:hafs-text.json'),
  ('hafs-2-281', 'hafs', 2, 281, 'وَٱتَّقُوا۟ يَوْمًۭا تُرْجَعُونَ فِيهِ إِلَى ٱللَّهِ ۖ ثُمَّ تُوَفَّىٰ كُلُّ نَفْسٍۢ مَّا كَسَبَتْ وَهُمْ لَا يُظْلَمُونَ', 'واتقوا يوما ترجعون فيه إلى الله  ثم توفى كل نفس ما كسبت وهم لا يظلمون', NULL, 47, 'local:hafs-text.json'),
  ('hafs-2-282', 'hafs', 2, 282, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِذَا تَدَايَنتُم بِدَيْنٍ إِلَىٰٓ أَجَلٍۢ مُّسَمًّۭى فَٱكْتُبُوهُ ۚ وَلْيَكْتُب بَّيْنَكُمْ كَاتِبٌۢ بِٱلْعَدْلِ ۚ وَلَا يَأْبَ كَاتِبٌ أَن يَكْتُبَ كَمَا عَلَّمَهُ ٱللَّهُ ۚ فَلْيَكْتُبْ وَلْيُمْلِلِ ٱلَّذِى عَلَيْهِ ٱلْحَقُّ وَلْيَتَّقِ ٱللَّهَ رَبَّهُۥ وَلَا يَبْخَسْ مِنْهُ شَيْـًۭٔا ۚ فَإِن كَانَ ٱلَّذِى عَلَيْهِ ٱلْحَقُّ سَفِيهًا أَوْ ضَعِيفًا أَوْ لَا يَسْتَطِيعُ أَن يُمِلَّ هُوَ فَلْيُمْلِلْ وَلِيُّهُۥ بِٱلْعَدْلِ ۚ وَٱسْتَشْهِدُوا۟ شَهِيدَيْنِ مِن رِّجَالِكُمْ ۖ فَإِن لَّمْ يَكُونَا رَجُلَيْنِ فَرَجُلٌۭ وَٱمْرَأَتَانِ مِمَّن تَرْضَوْنَ مِنَ ٱلشُّهَدَآءِ أَن تَضِلَّ إِحْدَىٰهُمَا فَتُذَكِّرَ إِحْدَىٰهُمَا ٱلْأُخْرَىٰ ۚ وَلَا يَأْبَ ٱلشُّهَدَآءُ إِذَا مَا دُعُوا۟ ۚ وَلَا تَسْـَٔمُوٓا۟ أَن تَكْتُبُوهُ صَغِيرًا أَوْ كَبِيرًا إِلَىٰٓ أَجَلِهِۦ ۚ ذَٰلِكُمْ أَقْسَطُ عِندَ ٱللَّهِ وَأَقْوَمُ لِلشَّهَٰدَةِ وَأَدْنَىٰٓ أَلَّا تَرْتَابُوٓا۟ ۖ إِلَّآ أَن تَكُونَ تِجَٰرَةً حَاضِرَةًۭ تُدِيرُونَهَا بَيْنَكُمْ فَلَيْسَ عَلَيْكُمْ جُنَاحٌ أَلَّا تَكْتُبُوهَا ۗ وَأَشْهِدُوٓا۟ إِذَا تَبَايَعْتُمْ ۚ وَلَا يُضَآرَّ كَاتِبٌۭ وَلَا شَهِيدٌۭ ۚ وَإِن تَفْعَلُوا۟ فَإِنَّهُۥ فُسُوقٌۢ بِكُمْ ۗ وَٱتَّقُوا۟ ٱللَّهَ ۖ وَيُعَلِّمُكُمُ ٱللَّهُ ۗ وَٱللَّهُ بِكُلِّ شَىْءٍ عَلِيمٌۭ', 'يأيها الذين ءامنوا إذا تداينتم بدين إلى أجل مسمى فاكتبوه  وليكتب بينكم كاتب بالعدل  ولا يأب كاتب أن يكتب كما علمه الله  فليكتب وليملل الذى عليه الحق وليتق الله ربه ولا يبخس منه شيا  فإن كان الذى عليه الحق سفيها أو ضعيفا أو لا يستطيع أن يمل هو فليملل وليه بالعدل  واستشهدوا شهيدين من رجالكم  فإن لم يكونا رجلين فرجل وامرأتان ممن ترضون من الشهداء أن تضل إحدىهما فتذكر إحدىهما الأخرى  ولا يأب الشهداء إذا ما دعوا  ولا تسموا أن تكتبوه صغيرا أو كبيرا إلى أجله  ذلكم أقسط عند الله وأقوم للشهدة وأدنى ألا ترتابوا  إلا أن تكون تجرة حاضرة تديرونها بينكم فليس عليكم جناح ألا تكتبوها  وأشهدوا إذا تبايعتم  ولا يضار كاتب ولا شهيد  وإن تفعلوا فإنه فسوق بكم  واتقوا الله  ويعلمكم الله  والله بكل شىء عليم', NULL, 48, 'local:hafs-text.json'),
  ('hafs-2-283', 'hafs', 2, 283, '۞ وَإِن كُنتُمْ عَلَىٰ سَفَرٍۢ وَلَمْ تَجِدُوا۟ كَاتِبًۭا فَرِهَٰنٌۭ مَّقْبُوضَةٌۭ ۖ فَإِنْ أَمِنَ بَعْضُكُم بَعْضًۭا فَلْيُؤَدِّ ٱلَّذِى ٱؤْتُمِنَ أَمَٰنَتَهُۥ وَلْيَتَّقِ ٱللَّهَ رَبَّهُۥ ۗ وَلَا تَكْتُمُوا۟ ٱلشَّهَٰدَةَ ۚ وَمَن يَكْتُمْهَا فَإِنَّهُۥٓ ءَاثِمٌۭ قَلْبُهُۥ ۗ وَٱللَّهُ بِمَا تَعْمَلُونَ عَلِيمٌۭ', 'وإن كنتم على سفر ولم تجدوا كاتبا فرهن مقبوضة  فإن أمن بعضكم بعضا فليؤد الذى اؤتمن أمنته وليتق الله ربه  ولا تكتموا الشهدة  ومن يكتمها فإنه ءاثم قلبه  والله بما تعملون عليم', NULL, 49, 'local:hafs-text.json'),
  ('hafs-2-284', 'hafs', 2, 284, 'لِّلَّهِ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ ۗ وَإِن تُبْدُوا۟ مَا فِىٓ أَنفُسِكُمْ أَوْ تُخْفُوهُ يُحَاسِبْكُم بِهِ ٱللَّهُ ۖ فَيَغْفِرُ لِمَن يَشَآءُ وَيُعَذِّبُ مَن يَشَآءُ ۗ وَٱللَّهُ عَلَىٰ كُلِّ شَىْءٍۢ قَدِيرٌ', 'لله ما فى السموت وما فى الأرض  وإن تبدوا ما فى أنفسكم أو تخفوه يحاسبكم به الله  فيغفر لمن يشاء ويعذب من يشاء  والله على كل شىء قدير', NULL, 49, 'local:hafs-text.json'),
  ('hafs-2-285', 'hafs', 2, 285, 'ءَامَنَ ٱلرَّسُولُ بِمَآ أُنزِلَ إِلَيْهِ مِن رَّبِّهِۦ وَٱلْمُؤْمِنُونَ ۚ كُلٌّ ءَامَنَ بِٱللَّهِ وَمَلَٰٓئِكَتِهِۦ وَكُتُبِهِۦ وَرُسُلِهِۦ لَا نُفَرِّقُ بَيْنَ أَحَدٍۢ مِّن رُّسُلِهِۦ ۚ وَقَالُوا۟ سَمِعْنَا وَأَطَعْنَا ۖ غُفْرَانَكَ رَبَّنَا وَإِلَيْكَ ٱلْمَصِيرُ', 'ءامن الرسول بما أنزل إليه من ربه والمؤمنون  كل ءامن بالله وملئكته وكتبه ورسله لا نفرق بين أحد من رسله  وقالوا سمعنا وأطعنا  غفرانك ربنا وإليك المصير', NULL, 49, 'local:hafs-text.json'),
  ('hafs-2-286', 'hafs', 2, 286, 'لَا يُكَلِّفُ ٱللَّهُ نَفْسًا إِلَّا وُسْعَهَا ۚ لَهَا مَا كَسَبَتْ وَعَلَيْهَا مَا ٱكْتَسَبَتْ ۗ رَبَّنَا لَا تُؤَاخِذْنَآ إِن نَّسِينَآ أَوْ أَخْطَأْنَا ۚ رَبَّنَا وَلَا تَحْمِلْ عَلَيْنَآ إِصْرًۭا كَمَا حَمَلْتَهُۥ عَلَى ٱلَّذِينَ مِن قَبْلِنَا ۚ رَبَّنَا وَلَا تُحَمِّلْنَا مَا لَا طَاقَةَ لَنَا بِهِۦ ۖ وَٱعْفُ عَنَّا وَٱغْفِرْ لَنَا وَٱرْحَمْنَآ ۚ أَنتَ مَوْلَىٰنَا فَٱنصُرْنَا عَلَى ٱلْقَوْمِ ٱلْكَٰفِرِينَ', 'لا يكلف الله نفسا إلا وسعها  لها ما كسبت وعليها ما اكتسبت  ربنا لا تؤاخذنا إن نسينا أو أخطأنا  ربنا ولا تحمل علينا إصرا كما حملته على الذين من قبلنا  ربنا ولا تحملنا ما لا طاقة لنا به  واعف عنا واغفر لنا وارحمنا  أنت مولىنا فانصرنا على القوم الكفرين', NULL, 49, 'local:hafs-text.json'),
  ('hafs-3-1', 'hafs', 3, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ الٓمٓ', 'بسم الله الرحمن الرحيم الم', NULL, 50, 'local:hafs-text.json'),
  ('hafs-3-2', 'hafs', 3, 2, 'ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَ ٱلْحَىُّ ٱلْقَيُّومُ', 'الله لا إله إلا هو الحى القيوم', NULL, 50, 'local:hafs-text.json'),
  ('hafs-3-3', 'hafs', 3, 3, 'نَزَّلَ عَلَيْكَ ٱلْكِتَٰبَ بِٱلْحَقِّ مُصَدِّقًۭا لِّمَا بَيْنَ يَدَيْهِ وَأَنزَلَ ٱلتَّوْرَىٰةَ وَٱلْإِنجِيلَ', 'نزل عليك الكتب بالحق مصدقا لما بين يديه وأنزل التورىة والإنجيل', NULL, 50, 'local:hafs-text.json'),
  ('hafs-3-4', 'hafs', 3, 4, 'مِن قَبْلُ هُدًۭى لِّلنَّاسِ وَأَنزَلَ ٱلْفُرْقَانَ ۗ إِنَّ ٱلَّذِينَ كَفَرُوا۟ بِـَٔايَٰتِ ٱللَّهِ لَهُمْ عَذَابٌۭ شَدِيدٌۭ ۗ وَٱللَّهُ عَزِيزٌۭ ذُو ٱنتِقَامٍ', 'من قبل هدى للناس وأنزل الفرقان  إن الذين كفروا بايت الله لهم عذاب شديد  والله عزيز ذو انتقام', NULL, 50, 'local:hafs-text.json'),
  ('hafs-3-5', 'hafs', 3, 5, 'إِنَّ ٱللَّهَ لَا يَخْفَىٰ عَلَيْهِ شَىْءٌۭ فِى ٱلْأَرْضِ وَلَا فِى ٱلسَّمَآءِ', 'إن الله لا يخفى عليه شىء فى الأرض ولا فى السماء', NULL, 50, 'local:hafs-text.json'),
  ('hafs-3-6', 'hafs', 3, 6, 'هُوَ ٱلَّذِى يُصَوِّرُكُمْ فِى ٱلْأَرْحَامِ كَيْفَ يَشَآءُ ۚ لَآ إِلَٰهَ إِلَّا هُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ', 'هو الذى يصوركم فى الأرحام كيف يشاء  لا إله إلا هو العزيز الحكيم', NULL, 50, 'local:hafs-text.json'),
  ('hafs-3-7', 'hafs', 3, 7, 'هُوَ ٱلَّذِىٓ أَنزَلَ عَلَيْكَ ٱلْكِتَٰبَ مِنْهُ ءَايَٰتٌۭ مُّحْكَمَٰتٌ هُنَّ أُمُّ ٱلْكِتَٰبِ وَأُخَرُ مُتَشَٰبِهَٰتٌۭ ۖ فَأَمَّا ٱلَّذِينَ فِى قُلُوبِهِمْ زَيْغٌۭ فَيَتَّبِعُونَ مَا تَشَٰبَهَ مِنْهُ ٱبْتِغَآءَ ٱلْفِتْنَةِ وَٱبْتِغَآءَ تَأْوِيلِهِۦ ۗ وَمَا يَعْلَمُ تَأْوِيلَهُۥٓ إِلَّا ٱللَّهُ ۗ وَٱلرَّٰسِخُونَ فِى ٱلْعِلْمِ يَقُولُونَ ءَامَنَّا بِهِۦ كُلٌّۭ مِّنْ عِندِ رَبِّنَا ۗ وَمَا يَذَّكَّرُ إِلَّآ أُو۟لُوا۟ ٱلْأَلْبَٰبِ', 'هو الذى أنزل عليك الكتب منه ءايت محكمت هن أم الكتب وأخر متشبهت  فأما الذين فى قلوبهم زيغ فيتبعون ما تشبه منه ابتغاء الفتنة وابتغاء تأويله  وما يعلم تأويله إلا الله  والرسخون فى العلم يقولون ءامنا به كل من عند ربنا  وما يذكر إلا أولوا الألبب', NULL, 50, 'local:hafs-text.json'),
  ('hafs-3-8', 'hafs', 3, 8, 'رَبَّنَا لَا تُزِغْ قُلُوبَنَا بَعْدَ إِذْ هَدَيْتَنَا وَهَبْ لَنَا مِن لَّدُنكَ رَحْمَةً ۚ إِنَّكَ أَنتَ ٱلْوَهَّابُ', 'ربنا لا تزغ قلوبنا بعد إذ هديتنا وهب لنا من لدنك رحمة  إنك أنت الوهاب', NULL, 50, 'local:hafs-text.json'),
  ('hafs-3-9', 'hafs', 3, 9, 'رَبَّنَآ إِنَّكَ جَامِعُ ٱلنَّاسِ لِيَوْمٍۢ لَّا رَيْبَ فِيهِ ۚ إِنَّ ٱللَّهَ لَا يُخْلِفُ ٱلْمِيعَادَ', 'ربنا إنك جامع الناس ليوم لا ريب فيه  إن الله لا يخلف الميعاد', NULL, 50, 'local:hafs-text.json'),
  ('hafs-3-10', 'hafs', 3, 10, 'إِنَّ ٱلَّذِينَ كَفَرُوا۟ لَن تُغْنِىَ عَنْهُمْ أَمْوَٰلُهُمْ وَلَآ أَوْلَٰدُهُم مِّنَ ٱللَّهِ شَيْـًۭٔا ۖ وَأُو۟لَٰٓئِكَ هُمْ وَقُودُ ٱلنَّارِ', 'إن الذين كفروا لن تغنى عنهم أمولهم ولا أولدهم من الله شيا  وأولئك هم وقود النار', NULL, 51, 'local:hafs-text.json'),
  ('hafs-3-11', 'hafs', 3, 11, 'كَدَأْبِ ءَالِ فِرْعَوْنَ وَٱلَّذِينَ مِن قَبْلِهِمْ ۚ كَذَّبُوا۟ بِـَٔايَٰتِنَا فَأَخَذَهُمُ ٱللَّهُ بِذُنُوبِهِمْ ۗ وَٱللَّهُ شَدِيدُ ٱلْعِقَابِ', 'كدأب ءال فرعون والذين من قبلهم  كذبوا بايتنا فأخذهم الله بذنوبهم  والله شديد العقاب', NULL, 51, 'local:hafs-text.json'),
  ('hafs-3-12', 'hafs', 3, 12, 'قُل لِّلَّذِينَ كَفَرُوا۟ سَتُغْلَبُونَ وَتُحْشَرُونَ إِلَىٰ جَهَنَّمَ ۚ وَبِئْسَ ٱلْمِهَادُ', 'قل للذين كفروا ستغلبون وتحشرون إلى جهنم  وبئس المهاد', NULL, 51, 'local:hafs-text.json'),
  ('hafs-3-13', 'hafs', 3, 13, 'قَدْ كَانَ لَكُمْ ءَايَةٌۭ فِى فِئَتَيْنِ ٱلْتَقَتَا ۖ فِئَةٌۭ تُقَٰتِلُ فِى سَبِيلِ ٱللَّهِ وَأُخْرَىٰ كَافِرَةٌۭ يَرَوْنَهُم مِّثْلَيْهِمْ رَأْىَ ٱلْعَيْنِ ۚ وَٱللَّهُ يُؤَيِّدُ بِنَصْرِهِۦ مَن يَشَآءُ ۗ إِنَّ فِى ذَٰلِكَ لَعِبْرَةًۭ لِّأُو۟لِى ٱلْأَبْصَٰرِ', 'قد كان لكم ءاية فى فئتين التقتا  فئة تقتل فى سبيل الله وأخرى كافرة يرونهم مثليهم رأى العين  والله يؤيد بنصره من يشاء  إن فى ذلك لعبرة لأولى الأبصر', NULL, 51, 'local:hafs-text.json'),
  ('hafs-3-14', 'hafs', 3, 14, 'زُيِّنَ لِلنَّاسِ حُبُّ ٱلشَّهَوَٰتِ مِنَ ٱلنِّسَآءِ وَٱلْبَنِينَ وَٱلْقَنَٰطِيرِ ٱلْمُقَنطَرَةِ مِنَ ٱلذَّهَبِ وَٱلْفِضَّةِ وَٱلْخَيْلِ ٱلْمُسَوَّمَةِ وَٱلْأَنْعَٰمِ وَٱلْحَرْثِ ۗ ذَٰلِكَ مَتَٰعُ ٱلْحَيَوٰةِ ٱلدُّنْيَا ۖ وَٱللَّهُ عِندَهُۥ حُسْنُ ٱلْمَـَٔابِ', 'زين للناس حب الشهوت من النساء والبنين والقنطير المقنطرة من الذهب والفضة والخيل المسومة والأنعم والحرث  ذلك متع الحيوة الدنيا  والله عنده حسن الماب', NULL, 51, 'local:hafs-text.json'),
  ('hafs-3-15', 'hafs', 3, 15, '۞ قُلْ أَؤُنَبِّئُكُم بِخَيْرٍۢ مِّن ذَٰلِكُمْ ۚ لِلَّذِينَ ٱتَّقَوْا۟ عِندَ رَبِّهِمْ جَنَّٰتٌۭ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ خَٰلِدِينَ فِيهَا وَأَزْوَٰجٌۭ مُّطَهَّرَةٌۭ وَرِضْوَٰنٌۭ مِّنَ ٱللَّهِ ۗ وَٱللَّهُ بَصِيرٌۢ بِٱلْعِبَادِ', 'قل أؤنبئكم بخير من ذلكم  للذين اتقوا عند ربهم جنت تجرى من تحتها الأنهر خلدين فيها وأزوج مطهرة ورضون من الله  والله بصير بالعباد', NULL, 51, 'local:hafs-text.json'),
  ('hafs-3-16', 'hafs', 3, 16, 'ٱلَّذِينَ يَقُولُونَ رَبَّنَآ إِنَّنَآ ءَامَنَّا فَٱغْفِرْ لَنَا ذُنُوبَنَا وَقِنَا عَذَابَ ٱلنَّارِ', 'الذين يقولون ربنا إننا ءامنا فاغفر لنا ذنوبنا وقنا عذاب النار', NULL, 52, 'local:hafs-text.json'),
  ('hafs-3-17', 'hafs', 3, 17, 'ٱلصَّٰبِرِينَ وَٱلصَّٰدِقِينَ وَٱلْقَٰنِتِينَ وَٱلْمُنفِقِينَ وَٱلْمُسْتَغْفِرِينَ بِٱلْأَسْحَارِ', 'الصبرين والصدقين والقنتين والمنفقين والمستغفرين بالأسحار', NULL, 52, 'local:hafs-text.json'),
  ('hafs-3-18', 'hafs', 3, 18, 'شَهِدَ ٱللَّهُ أَنَّهُۥ لَآ إِلَٰهَ إِلَّا هُوَ وَٱلْمَلَٰٓئِكَةُ وَأُو۟لُوا۟ ٱلْعِلْمِ قَآئِمًۢا بِٱلْقِسْطِ ۚ لَآ إِلَٰهَ إِلَّا هُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ', 'شهد الله أنه لا إله إلا هو والملئكة وأولوا العلم قائما بالقسط  لا إله إلا هو العزيز الحكيم', NULL, 52, 'local:hafs-text.json'),
  ('hafs-3-19', 'hafs', 3, 19, 'إِنَّ ٱلدِّينَ عِندَ ٱللَّهِ ٱلْإِسْلَٰمُ ۗ وَمَا ٱخْتَلَفَ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَٰبَ إِلَّا مِنۢ بَعْدِ مَا جَآءَهُمُ ٱلْعِلْمُ بَغْيًۢا بَيْنَهُمْ ۗ وَمَن يَكْفُرْ بِـَٔايَٰتِ ٱللَّهِ فَإِنَّ ٱللَّهَ سَرِيعُ ٱلْحِسَابِ', 'إن الدين عند الله الإسلم  وما اختلف الذين أوتوا الكتب إلا من بعد ما جاءهم العلم بغيا بينهم  ومن يكفر بايت الله فإن الله سريع الحساب', NULL, 52, 'local:hafs-text.json'),
  ('hafs-3-20', 'hafs', 3, 20, 'فَإِنْ حَآجُّوكَ فَقُلْ أَسْلَمْتُ وَجْهِىَ لِلَّهِ وَمَنِ ٱتَّبَعَنِ ۗ وَقُل لِّلَّذِينَ أُوتُوا۟ ٱلْكِتَٰبَ وَٱلْأُمِّيِّۦنَ ءَأَسْلَمْتُمْ ۚ فَإِنْ أَسْلَمُوا۟ فَقَدِ ٱهْتَدَوا۟ ۖ وَّإِن تَوَلَّوْا۟ فَإِنَّمَا عَلَيْكَ ٱلْبَلَٰغُ ۗ وَٱللَّهُ بَصِيرٌۢ بِٱلْعِبَادِ', 'فإن حاجوك فقل أسلمت وجهى لله ومن اتبعن  وقل للذين أوتوا الكتب والأمين ءأسلمتم  فإن أسلموا فقد اهتدوا  وإن تولوا فإنما عليك البلغ  والله بصير بالعباد', NULL, 52, 'local:hafs-text.json'),
  ('hafs-3-21', 'hafs', 3, 21, 'إِنَّ ٱلَّذِينَ يَكْفُرُونَ بِـَٔايَٰتِ ٱللَّهِ وَيَقْتُلُونَ ٱلنَّبِيِّۦنَ بِغَيْرِ حَقٍّۢ وَيَقْتُلُونَ ٱلَّذِينَ يَأْمُرُونَ بِٱلْقِسْطِ مِنَ ٱلنَّاسِ فَبَشِّرْهُم بِعَذَابٍ أَلِيمٍ', 'إن الذين يكفرون بايت الله ويقتلون النبين بغير حق ويقتلون الذين يأمرون بالقسط من الناس فبشرهم بعذاب أليم', NULL, 52, 'local:hafs-text.json'),
  ('hafs-3-22', 'hafs', 3, 22, 'أُو۟لَٰٓئِكَ ٱلَّذِينَ حَبِطَتْ أَعْمَٰلُهُمْ فِى ٱلدُّنْيَا وَٱلْءَاخِرَةِ وَمَا لَهُم مِّن نَّٰصِرِينَ', 'أولئك الذين حبطت أعملهم فى الدنيا والءاخرة وما لهم من نصرين', NULL, 52, 'local:hafs-text.json'),
  ('hafs-3-23', 'hafs', 3, 23, 'أَلَمْ تَرَ إِلَى ٱلَّذِينَ أُوتُوا۟ نَصِيبًۭا مِّنَ ٱلْكِتَٰبِ يُدْعَوْنَ إِلَىٰ كِتَٰبِ ٱللَّهِ لِيَحْكُمَ بَيْنَهُمْ ثُمَّ يَتَوَلَّىٰ فَرِيقٌۭ مِّنْهُمْ وَهُم مُّعْرِضُونَ', 'ألم تر إلى الذين أوتوا نصيبا من الكتب يدعون إلى كتب الله ليحكم بينهم ثم يتولى فريق منهم وهم معرضون', NULL, 53, 'local:hafs-text.json'),
  ('hafs-3-24', 'hafs', 3, 24, 'ذَٰلِكَ بِأَنَّهُمْ قَالُوا۟ لَن تَمَسَّنَا ٱلنَّارُ إِلَّآ أَيَّامًۭا مَّعْدُودَٰتٍۢ ۖ وَغَرَّهُمْ فِى دِينِهِم مَّا كَانُوا۟ يَفْتَرُونَ', 'ذلك بأنهم قالوا لن تمسنا النار إلا أياما معدودت  وغرهم فى دينهم ما كانوا يفترون', NULL, 53, 'local:hafs-text.json'),
  ('hafs-3-25', 'hafs', 3, 25, 'فَكَيْفَ إِذَا جَمَعْنَٰهُمْ لِيَوْمٍۢ لَّا رَيْبَ فِيهِ وَوُفِّيَتْ كُلُّ نَفْسٍۢ مَّا كَسَبَتْ وَهُمْ لَا يُظْلَمُونَ', 'فكيف إذا جمعنهم ليوم لا ريب فيه ووفيت كل نفس ما كسبت وهم لا يظلمون', NULL, 53, 'local:hafs-text.json'),
  ('hafs-3-26', 'hafs', 3, 26, 'قُلِ ٱللَّهُمَّ مَٰلِكَ ٱلْمُلْكِ تُؤْتِى ٱلْمُلْكَ مَن تَشَآءُ وَتَنزِعُ ٱلْمُلْكَ مِمَّن تَشَآءُ وَتُعِزُّ مَن تَشَآءُ وَتُذِلُّ مَن تَشَآءُ ۖ بِيَدِكَ ٱلْخَيْرُ ۖ إِنَّكَ عَلَىٰ كُلِّ شَىْءٍۢ قَدِيرٌۭ', 'قل اللهم ملك الملك تؤتى الملك من تشاء وتنزع الملك ممن تشاء وتعز من تشاء وتذل من تشاء  بيدك الخير  إنك على كل شىء قدير', NULL, 53, 'local:hafs-text.json'),
  ('hafs-3-27', 'hafs', 3, 27, 'تُولِجُ ٱلَّيْلَ فِى ٱلنَّهَارِ وَتُولِجُ ٱلنَّهَارَ فِى ٱلَّيْلِ ۖ وَتُخْرِجُ ٱلْحَىَّ مِنَ ٱلْمَيِّتِ وَتُخْرِجُ ٱلْمَيِّتَ مِنَ ٱلْحَىِّ ۖ وَتَرْزُقُ مَن تَشَآءُ بِغَيْرِ حِسَابٍۢ', 'تولج اليل فى النهار وتولج النهار فى اليل  وتخرج الحى من الميت وتخرج الميت من الحى  وترزق من تشاء بغير حساب', NULL, 53, 'local:hafs-text.json'),
  ('hafs-3-28', 'hafs', 3, 28, 'لَّا يَتَّخِذِ ٱلْمُؤْمِنُونَ ٱلْكَٰفِرِينَ أَوْلِيَآءَ مِن دُونِ ٱلْمُؤْمِنِينَ ۖ وَمَن يَفْعَلْ ذَٰلِكَ فَلَيْسَ مِنَ ٱللَّهِ فِى شَىْءٍ إِلَّآ أَن تَتَّقُوا۟ مِنْهُمْ تُقَىٰةًۭ ۗ وَيُحَذِّرُكُمُ ٱللَّهُ نَفْسَهُۥ ۗ وَإِلَى ٱللَّهِ ٱلْمَصِيرُ', 'لا يتخذ المؤمنون الكفرين أولياء من دون المؤمنين  ومن يفعل ذلك فليس من الله فى شىء إلا أن تتقوا منهم تقىة  ويحذركم الله نفسه  وإلى الله المصير', NULL, 53, 'local:hafs-text.json'),
  ('hafs-3-29', 'hafs', 3, 29, 'قُلْ إِن تُخْفُوا۟ مَا فِى صُدُورِكُمْ أَوْ تُبْدُوهُ يَعْلَمْهُ ٱللَّهُ ۗ وَيَعْلَمُ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ ۗ وَٱللَّهُ عَلَىٰ كُلِّ شَىْءٍۢ قَدِيرٌۭ', 'قل إن تخفوا ما فى صدوركم أو تبدوه يعلمه الله  ويعلم ما فى السموت وما فى الأرض  والله على كل شىء قدير', NULL, 53, 'local:hafs-text.json'),
  ('hafs-3-30', 'hafs', 3, 30, 'يَوْمَ تَجِدُ كُلُّ نَفْسٍۢ مَّا عَمِلَتْ مِنْ خَيْرٍۢ مُّحْضَرًۭا وَمَا عَمِلَتْ مِن سُوٓءٍۢ تَوَدُّ لَوْ أَنَّ بَيْنَهَا وَبَيْنَهُۥٓ أَمَدًۢا بَعِيدًۭا ۗ وَيُحَذِّرُكُمُ ٱللَّهُ نَفْسَهُۥ ۗ وَٱللَّهُ رَءُوفٌۢ بِٱلْعِبَادِ', 'يوم تجد كل نفس ما عملت من خير محضرا وما عملت من سوء تود لو أن بينها وبينه أمدا بعيدا  ويحذركم الله نفسه  والله رءوف بالعباد', NULL, 54, 'local:hafs-text.json'),
  ('hafs-3-31', 'hafs', 3, 31, 'قُلْ إِن كُنتُمْ تُحِبُّونَ ٱللَّهَ فَٱتَّبِعُونِى يُحْبِبْكُمُ ٱللَّهُ وَيَغْفِرْ لَكُمْ ذُنُوبَكُمْ ۗ وَٱللَّهُ غَفُورٌۭ رَّحِيمٌۭ', 'قل إن كنتم تحبون الله فاتبعونى يحببكم الله ويغفر لكم ذنوبكم  والله غفور رحيم', NULL, 54, 'local:hafs-text.json'),
  ('hafs-3-32', 'hafs', 3, 32, 'قُلْ أَطِيعُوا۟ ٱللَّهَ وَٱلرَّسُولَ ۖ فَإِن تَوَلَّوْا۟ فَإِنَّ ٱللَّهَ لَا يُحِبُّ ٱلْكَٰفِرِينَ', 'قل أطيعوا الله والرسول  فإن تولوا فإن الله لا يحب الكفرين', NULL, 54, 'local:hafs-text.json'),
  ('hafs-3-33', 'hafs', 3, 33, '۞ إِنَّ ٱللَّهَ ٱصْطَفَىٰٓ ءَادَمَ وَنُوحًۭا وَءَالَ إِبْرَٰهِيمَ وَءَالَ عِمْرَٰنَ عَلَى ٱلْعَٰلَمِينَ', 'إن الله اصطفى ءادم ونوحا وءال إبرهيم وءال عمرن على العلمين', NULL, 54, 'local:hafs-text.json'),
  ('hafs-3-34', 'hafs', 3, 34, 'ذُرِّيَّةًۢ بَعْضُهَا مِنۢ بَعْضٍۢ ۗ وَٱللَّهُ سَمِيعٌ عَلِيمٌ', 'ذرية بعضها من بعض  والله سميع عليم', NULL, 54, 'local:hafs-text.json'),
  ('hafs-3-35', 'hafs', 3, 35, 'إِذْ قَالَتِ ٱمْرَأَتُ عِمْرَٰنَ رَبِّ إِنِّى نَذَرْتُ لَكَ مَا فِى بَطْنِى مُحَرَّرًۭا فَتَقَبَّلْ مِنِّىٓ ۖ إِنَّكَ أَنتَ ٱلسَّمِيعُ ٱلْعَلِيمُ', 'إذ قالت امرأت عمرن رب إنى نذرت لك ما فى بطنى محررا فتقبل منى  إنك أنت السميع العليم', NULL, 54, 'local:hafs-text.json'),
  ('hafs-3-36', 'hafs', 3, 36, 'فَلَمَّا وَضَعَتْهَا قَالَتْ رَبِّ إِنِّى وَضَعْتُهَآ أُنثَىٰ وَٱللَّهُ أَعْلَمُ بِمَا وَضَعَتْ وَلَيْسَ ٱلذَّكَرُ كَٱلْأُنثَىٰ ۖ وَإِنِّى سَمَّيْتُهَا مَرْيَمَ وَإِنِّىٓ أُعِيذُهَا بِكَ وَذُرِّيَّتَهَا مِنَ ٱلشَّيْطَٰنِ ٱلرَّجِيمِ', 'فلما وضعتها قالت رب إنى وضعتها أنثى والله أعلم بما وضعت وليس الذكر كالأنثى  وإنى سميتها مريم وإنى أعيذها بك وذريتها من الشيطن الرجيم', NULL, 54, 'local:hafs-text.json'),
  ('hafs-3-37', 'hafs', 3, 37, 'فَتَقَبَّلَهَا رَبُّهَا بِقَبُولٍ حَسَنٍۢ وَأَنۢبَتَهَا نَبَاتًا حَسَنًۭا وَكَفَّلَهَا زَكَرِيَّا ۖ كُلَّمَا دَخَلَ عَلَيْهَا زَكَرِيَّا ٱلْمِحْرَابَ وَجَدَ عِندَهَا رِزْقًۭا ۖ قَالَ يَٰمَرْيَمُ أَنَّىٰ لَكِ هَٰذَا ۖ قَالَتْ هُوَ مِنْ عِندِ ٱللَّهِ ۖ إِنَّ ٱللَّهَ يَرْزُقُ مَن يَشَآءُ بِغَيْرِ حِسَابٍ', 'فتقبلها ربها بقبول حسن وأنبتها نباتا حسنا وكفلها زكريا  كلما دخل عليها زكريا المحراب وجد عندها رزقا  قال يمريم أنى لك هذا  قالت هو من عند الله  إن الله يرزق من يشاء بغير حساب', NULL, 54, 'local:hafs-text.json'),
  ('hafs-3-38', 'hafs', 3, 38, 'هُنَالِكَ دَعَا زَكَرِيَّا رَبَّهُۥ ۖ قَالَ رَبِّ هَبْ لِى مِن لَّدُنكَ ذُرِّيَّةًۭ طَيِّبَةً ۖ إِنَّكَ سَمِيعُ ٱلدُّعَآءِ', 'هنالك دعا زكريا ربه  قال رب هب لى من لدنك ذرية طيبة  إنك سميع الدعاء', NULL, 55, 'local:hafs-text.json'),
  ('hafs-3-39', 'hafs', 3, 39, 'فَنَادَتْهُ ٱلْمَلَٰٓئِكَةُ وَهُوَ قَآئِمٌۭ يُصَلِّى فِى ٱلْمِحْرَابِ أَنَّ ٱللَّهَ يُبَشِّرُكَ بِيَحْيَىٰ مُصَدِّقًۢا بِكَلِمَةٍۢ مِّنَ ٱللَّهِ وَسَيِّدًۭا وَحَصُورًۭا وَنَبِيًّۭا مِّنَ ٱلصَّٰلِحِينَ', 'فنادته الملئكة وهو قائم يصلى فى المحراب أن الله يبشرك بيحيى مصدقا بكلمة من الله وسيدا وحصورا ونبيا من الصلحين', NULL, 55, 'local:hafs-text.json'),
  ('hafs-3-40', 'hafs', 3, 40, 'قَالَ رَبِّ أَنَّىٰ يَكُونُ لِى غُلَٰمٌۭ وَقَدْ بَلَغَنِىَ ٱلْكِبَرُ وَٱمْرَأَتِى عَاقِرٌۭ ۖ قَالَ كَذَٰلِكَ ٱللَّهُ يَفْعَلُ مَا يَشَآءُ', 'قال رب أنى يكون لى غلم وقد بلغنى الكبر وامرأتى عاقر  قال كذلك الله يفعل ما يشاء', NULL, 55, 'local:hafs-text.json'),
  ('hafs-3-41', 'hafs', 3, 41, 'قَالَ رَبِّ ٱجْعَل لِّىٓ ءَايَةًۭ ۖ قَالَ ءَايَتُكَ أَلَّا تُكَلِّمَ ٱلنَّاسَ ثَلَٰثَةَ أَيَّامٍ إِلَّا رَمْزًۭا ۗ وَٱذْكُر رَّبَّكَ كَثِيرًۭا وَسَبِّحْ بِٱلْعَشِىِّ وَٱلْإِبْكَٰرِ', 'قال رب اجعل لى ءاية  قال ءايتك ألا تكلم الناس ثلثة أيام إلا رمزا  واذكر ربك كثيرا وسبح بالعشى والإبكر', NULL, 55, 'local:hafs-text.json'),
  ('hafs-3-42', 'hafs', 3, 42, 'وَإِذْ قَالَتِ ٱلْمَلَٰٓئِكَةُ يَٰمَرْيَمُ إِنَّ ٱللَّهَ ٱصْطَفَىٰكِ وَطَهَّرَكِ وَٱصْطَفَىٰكِ عَلَىٰ نِسَآءِ ٱلْعَٰلَمِينَ', 'وإذ قالت الملئكة يمريم إن الله اصطفىك وطهرك واصطفىك على نساء العلمين', NULL, 55, 'local:hafs-text.json'),
  ('hafs-3-43', 'hafs', 3, 43, 'يَٰمَرْيَمُ ٱقْنُتِى لِرَبِّكِ وَٱسْجُدِى وَٱرْكَعِى مَعَ ٱلرَّٰكِعِينَ', 'يمريم اقنتى لربك واسجدى واركعى مع الركعين', NULL, 55, 'local:hafs-text.json'),
  ('hafs-3-44', 'hafs', 3, 44, 'ذَٰلِكَ مِنْ أَنۢبَآءِ ٱلْغَيْبِ نُوحِيهِ إِلَيْكَ ۚ وَمَا كُنتَ لَدَيْهِمْ إِذْ يُلْقُونَ أَقْلَٰمَهُمْ أَيُّهُمْ يَكْفُلُ مَرْيَمَ وَمَا كُنتَ لَدَيْهِمْ إِذْ يَخْتَصِمُونَ', 'ذلك من أنباء الغيب نوحيه إليك  وما كنت لديهم إذ يلقون أقلمهم أيهم يكفل مريم وما كنت لديهم إذ يختصمون', NULL, 55, 'local:hafs-text.json'),
  ('hafs-3-45', 'hafs', 3, 45, 'إِذْ قَالَتِ ٱلْمَلَٰٓئِكَةُ يَٰمَرْيَمُ إِنَّ ٱللَّهَ يُبَشِّرُكِ بِكَلِمَةٍۢ مِّنْهُ ٱسْمُهُ ٱلْمَسِيحُ عِيسَى ٱبْنُ مَرْيَمَ وَجِيهًۭا فِى ٱلدُّنْيَا وَٱلْءَاخِرَةِ وَمِنَ ٱلْمُقَرَّبِينَ', 'إذ قالت الملئكة يمريم إن الله يبشرك بكلمة منه اسمه المسيح عيسى ابن مريم وجيها فى الدنيا والءاخرة ومن المقربين', NULL, 55, 'local:hafs-text.json'),
  ('hafs-3-46', 'hafs', 3, 46, 'وَيُكَلِّمُ ٱلنَّاسَ فِى ٱلْمَهْدِ وَكَهْلًۭا وَمِنَ ٱلصَّٰلِحِينَ', 'ويكلم الناس فى المهد وكهلا ومن الصلحين', NULL, 56, 'local:hafs-text.json'),
  ('hafs-3-47', 'hafs', 3, 47, 'قَالَتْ رَبِّ أَنَّىٰ يَكُونُ لِى وَلَدٌۭ وَلَمْ يَمْسَسْنِى بَشَرٌۭ ۖ قَالَ كَذَٰلِكِ ٱللَّهُ يَخْلُقُ مَا يَشَآءُ ۚ إِذَا قَضَىٰٓ أَمْرًۭا فَإِنَّمَا يَقُولُ لَهُۥ كُن فَيَكُونُ', 'قالت رب أنى يكون لى ولد ولم يمسسنى بشر  قال كذلك الله يخلق ما يشاء  إذا قضى أمرا فإنما يقول له كن فيكون', NULL, 56, 'local:hafs-text.json'),
  ('hafs-3-48', 'hafs', 3, 48, 'وَيُعَلِّمُهُ ٱلْكِتَٰبَ وَٱلْحِكْمَةَ وَٱلتَّوْرَىٰةَ وَٱلْإِنجِيلَ', 'ويعلمه الكتب والحكمة والتورىة والإنجيل', NULL, 56, 'local:hafs-text.json'),
  ('hafs-3-49', 'hafs', 3, 49, 'وَرَسُولًا إِلَىٰ بَنِىٓ إِسْرَٰٓءِيلَ أَنِّى قَدْ جِئْتُكُم بِـَٔايَةٍۢ مِّن رَّبِّكُمْ ۖ أَنِّىٓ أَخْلُقُ لَكُم مِّنَ ٱلطِّينِ كَهَيْـَٔةِ ٱلطَّيْرِ فَأَنفُخُ فِيهِ فَيَكُونُ طَيْرًۢا بِإِذْنِ ٱللَّهِ ۖ وَأُبْرِئُ ٱلْأَكْمَهَ وَٱلْأَبْرَصَ وَأُحْىِ ٱلْمَوْتَىٰ بِإِذْنِ ٱللَّهِ ۖ وَأُنَبِّئُكُم بِمَا تَأْكُلُونَ وَمَا تَدَّخِرُونَ فِى بُيُوتِكُمْ ۚ إِنَّ فِى ذَٰلِكَ لَءَايَةًۭ لَّكُمْ إِن كُنتُم مُّؤْمِنِينَ', 'ورسولا إلى بنى إسرءيل أنى قد جئتكم باية من ربكم  أنى أخلق لكم من الطين كهية الطير فأنفخ فيه فيكون طيرا بإذن الله  وأبرئ الأكمه والأبرص وأحى الموتى بإذن الله  وأنبئكم بما تأكلون وما تدخرون فى بيوتكم  إن فى ذلك لءاية لكم إن كنتم مؤمنين', NULL, 56, 'local:hafs-text.json'),
  ('hafs-3-50', 'hafs', 3, 50, 'وَمُصَدِّقًۭا لِّمَا بَيْنَ يَدَىَّ مِنَ ٱلتَّوْرَىٰةِ وَلِأُحِلَّ لَكُم بَعْضَ ٱلَّذِى حُرِّمَ عَلَيْكُمْ ۚ وَجِئْتُكُم بِـَٔايَةٍۢ مِّن رَّبِّكُمْ فَٱتَّقُوا۟ ٱللَّهَ وَأَطِيعُونِ', 'ومصدقا لما بين يدى من التورىة ولأحل لكم بعض الذى حرم عليكم  وجئتكم باية من ربكم فاتقوا الله وأطيعون', NULL, 56, 'local:hafs-text.json'),
  ('hafs-3-51', 'hafs', 3, 51, 'إِنَّ ٱللَّهَ رَبِّى وَرَبُّكُمْ فَٱعْبُدُوهُ ۗ هَٰذَا صِرَٰطٌۭ مُّسْتَقِيمٌۭ', 'إن الله ربى وربكم فاعبدوه  هذا صرط مستقيم', NULL, 56, 'local:hafs-text.json'),
  ('hafs-3-52', 'hafs', 3, 52, '۞ فَلَمَّآ أَحَسَّ عِيسَىٰ مِنْهُمُ ٱلْكُفْرَ قَالَ مَنْ أَنصَارِىٓ إِلَى ٱللَّهِ ۖ قَالَ ٱلْحَوَارِيُّونَ نَحْنُ أَنصَارُ ٱللَّهِ ءَامَنَّا بِٱللَّهِ وَٱشْهَدْ بِأَنَّا مُسْلِمُونَ', 'فلما أحس عيسى منهم الكفر قال من أنصارى إلى الله  قال الحواريون نحن أنصار الله ءامنا بالله واشهد بأنا مسلمون', NULL, 56, 'local:hafs-text.json'),
  ('hafs-3-53', 'hafs', 3, 53, 'رَبَّنَآ ءَامَنَّا بِمَآ أَنزَلْتَ وَٱتَّبَعْنَا ٱلرَّسُولَ فَٱكْتُبْنَا مَعَ ٱلشَّٰهِدِينَ', 'ربنا ءامنا بما أنزلت واتبعنا الرسول فاكتبنا مع الشهدين', NULL, 57, 'local:hafs-text.json'),
  ('hafs-3-54', 'hafs', 3, 54, 'وَمَكَرُوا۟ وَمَكَرَ ٱللَّهُ ۖ وَٱللَّهُ خَيْرُ ٱلْمَٰكِرِينَ', 'ومكروا ومكر الله  والله خير المكرين', NULL, 57, 'local:hafs-text.json'),
  ('hafs-3-55', 'hafs', 3, 55, 'إِذْ قَالَ ٱللَّهُ يَٰعِيسَىٰٓ إِنِّى مُتَوَفِّيكَ وَرَافِعُكَ إِلَىَّ وَمُطَهِّرُكَ مِنَ ٱلَّذِينَ كَفَرُوا۟ وَجَاعِلُ ٱلَّذِينَ ٱتَّبَعُوكَ فَوْقَ ٱلَّذِينَ كَفَرُوٓا۟ إِلَىٰ يَوْمِ ٱلْقِيَٰمَةِ ۖ ثُمَّ إِلَىَّ مَرْجِعُكُمْ فَأَحْكُمُ بَيْنَكُمْ فِيمَا كُنتُمْ فِيهِ تَخْتَلِفُونَ', 'إذ قال الله يعيسى إنى متوفيك ورافعك إلى ومطهرك من الذين كفروا وجاعل الذين اتبعوك فوق الذين كفروا إلى يوم القيمة  ثم إلى مرجعكم فأحكم بينكم فيما كنتم فيه تختلفون', NULL, 57, 'local:hafs-text.json'),
  ('hafs-3-56', 'hafs', 3, 56, 'فَأَمَّا ٱلَّذِينَ كَفَرُوا۟ فَأُعَذِّبُهُمْ عَذَابًۭا شَدِيدًۭا فِى ٱلدُّنْيَا وَٱلْءَاخِرَةِ وَمَا لَهُم مِّن نَّٰصِرِينَ', 'فأما الذين كفروا فأعذبهم عذابا شديدا فى الدنيا والءاخرة وما لهم من نصرين', NULL, 57, 'local:hafs-text.json'),
  ('hafs-3-57', 'hafs', 3, 57, 'وَأَمَّا ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ فَيُوَفِّيهِمْ أُجُورَهُمْ ۗ وَٱللَّهُ لَا يُحِبُّ ٱلظَّٰلِمِينَ', 'وأما الذين ءامنوا وعملوا الصلحت فيوفيهم أجورهم  والله لا يحب الظلمين', NULL, 57, 'local:hafs-text.json'),
  ('hafs-3-58', 'hafs', 3, 58, 'ذَٰلِكَ نَتْلُوهُ عَلَيْكَ مِنَ ٱلْءَايَٰتِ وَٱلذِّكْرِ ٱلْحَكِيمِ', 'ذلك نتلوه عليك من الءايت والذكر الحكيم', NULL, 57, 'local:hafs-text.json'),
  ('hafs-3-59', 'hafs', 3, 59, 'إِنَّ مَثَلَ عِيسَىٰ عِندَ ٱللَّهِ كَمَثَلِ ءَادَمَ ۖ خَلَقَهُۥ مِن تُرَابٍۢ ثُمَّ قَالَ لَهُۥ كُن فَيَكُونُ', 'إن مثل عيسى عند الله كمثل ءادم  خلقه من تراب ثم قال له كن فيكون', NULL, 57, 'local:hafs-text.json'),
  ('hafs-3-60', 'hafs', 3, 60, 'ٱلْحَقُّ مِن رَّبِّكَ فَلَا تَكُن مِّنَ ٱلْمُمْتَرِينَ', 'الحق من ربك فلا تكن من الممترين', NULL, 57, 'local:hafs-text.json'),
  ('hafs-3-61', 'hafs', 3, 61, 'فَمَنْ حَآجَّكَ فِيهِ مِنۢ بَعْدِ مَا جَآءَكَ مِنَ ٱلْعِلْمِ فَقُلْ تَعَالَوْا۟ نَدْعُ أَبْنَآءَنَا وَأَبْنَآءَكُمْ وَنِسَآءَنَا وَنِسَآءَكُمْ وَأَنفُسَنَا وَأَنفُسَكُمْ ثُمَّ نَبْتَهِلْ فَنَجْعَل لَّعْنَتَ ٱللَّهِ عَلَى ٱلْكَٰذِبِينَ', 'فمن حاجك فيه من بعد ما جاءك من العلم فقل تعالوا ندع أبناءنا وأبناءكم ونساءنا ونساءكم وأنفسنا وأنفسكم ثم نبتهل فنجعل لعنت الله على الكذبين', NULL, 57, 'local:hafs-text.json'),
  ('hafs-3-62', 'hafs', 3, 62, 'إِنَّ هَٰذَا لَهُوَ ٱلْقَصَصُ ٱلْحَقُّ ۚ وَمَا مِنْ إِلَٰهٍ إِلَّا ٱللَّهُ ۚ وَإِنَّ ٱللَّهَ لَهُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ', 'إن هذا لهو القصص الحق  وما من إله إلا الله  وإن الله لهو العزيز الحكيم', NULL, 58, 'local:hafs-text.json'),
  ('hafs-3-63', 'hafs', 3, 63, 'فَإِن تَوَلَّوْا۟ فَإِنَّ ٱللَّهَ عَلِيمٌۢ بِٱلْمُفْسِدِينَ', 'فإن تولوا فإن الله عليم بالمفسدين', NULL, 58, 'local:hafs-text.json'),
  ('hafs-3-64', 'hafs', 3, 64, 'قُلْ يَٰٓأَهْلَ ٱلْكِتَٰبِ تَعَالَوْا۟ إِلَىٰ كَلِمَةٍۢ سَوَآءٍۭ بَيْنَنَا وَبَيْنَكُمْ أَلَّا نَعْبُدَ إِلَّا ٱللَّهَ وَلَا نُشْرِكَ بِهِۦ شَيْـًۭٔا وَلَا يَتَّخِذَ بَعْضُنَا بَعْضًا أَرْبَابًۭا مِّن دُونِ ٱللَّهِ ۚ فَإِن تَوَلَّوْا۟ فَقُولُوا۟ ٱشْهَدُوا۟ بِأَنَّا مُسْلِمُونَ', 'قل يأهل الكتب تعالوا إلى كلمة سواء بيننا وبينكم ألا نعبد إلا الله ولا نشرك به شيا ولا يتخذ بعضنا بعضا أربابا من دون الله  فإن تولوا فقولوا اشهدوا بأنا مسلمون', NULL, 58, 'local:hafs-text.json'),
  ('hafs-3-65', 'hafs', 3, 65, 'يَٰٓأَهْلَ ٱلْكِتَٰبِ لِمَ تُحَآجُّونَ فِىٓ إِبْرَٰهِيمَ وَمَآ أُنزِلَتِ ٱلتَّوْرَىٰةُ وَٱلْإِنجِيلُ إِلَّا مِنۢ بَعْدِهِۦٓ ۚ أَفَلَا تَعْقِلُونَ', 'يأهل الكتب لم تحاجون فى إبرهيم وما أنزلت التورىة والإنجيل إلا من بعده  أفلا تعقلون', NULL, 58, 'local:hafs-text.json'),
  ('hafs-3-66', 'hafs', 3, 66, 'هَٰٓأَنتُمْ هَٰٓؤُلَآءِ حَٰجَجْتُمْ فِيمَا لَكُم بِهِۦ عِلْمٌۭ فَلِمَ تُحَآجُّونَ فِيمَا لَيْسَ لَكُم بِهِۦ عِلْمٌۭ ۚ وَٱللَّهُ يَعْلَمُ وَأَنتُمْ لَا تَعْلَمُونَ', 'هأنتم هؤلاء حججتم فيما لكم به علم فلم تحاجون فيما ليس لكم به علم  والله يعلم وأنتم لا تعلمون', NULL, 58, 'local:hafs-text.json'),
  ('hafs-3-67', 'hafs', 3, 67, 'مَا كَانَ إِبْرَٰهِيمُ يَهُودِيًّۭا وَلَا نَصْرَانِيًّۭا وَلَٰكِن كَانَ حَنِيفًۭا مُّسْلِمًۭا وَمَا كَانَ مِنَ ٱلْمُشْرِكِينَ', 'ما كان إبرهيم يهوديا ولا نصرانيا ولكن كان حنيفا مسلما وما كان من المشركين', NULL, 58, 'local:hafs-text.json'),
  ('hafs-3-68', 'hafs', 3, 68, 'إِنَّ أَوْلَى ٱلنَّاسِ بِإِبْرَٰهِيمَ لَلَّذِينَ ٱتَّبَعُوهُ وَهَٰذَا ٱلنَّبِىُّ وَٱلَّذِينَ ءَامَنُوا۟ ۗ وَٱللَّهُ وَلِىُّ ٱلْمُؤْمِنِينَ', 'إن أولى الناس بإبرهيم للذين اتبعوه وهذا النبى والذين ءامنوا  والله ولى المؤمنين', NULL, 58, 'local:hafs-text.json'),
  ('hafs-3-69', 'hafs', 3, 69, 'وَدَّت طَّآئِفَةٌۭ مِّنْ أَهْلِ ٱلْكِتَٰبِ لَوْ يُضِلُّونَكُمْ وَمَا يُضِلُّونَ إِلَّآ أَنفُسَهُمْ وَمَا يَشْعُرُونَ', 'ودت طائفة من أهل الكتب لو يضلونكم وما يضلون إلا أنفسهم وما يشعرون', NULL, 58, 'local:hafs-text.json'),
  ('hafs-3-70', 'hafs', 3, 70, 'يَٰٓأَهْلَ ٱلْكِتَٰبِ لِمَ تَكْفُرُونَ بِـَٔايَٰتِ ٱللَّهِ وَأَنتُمْ تَشْهَدُونَ', 'يأهل الكتب لم تكفرون بايت الله وأنتم تشهدون', NULL, 58, 'local:hafs-text.json'),
  ('hafs-3-71', 'hafs', 3, 71, 'يَٰٓأَهْلَ ٱلْكِتَٰبِ لِمَ تَلْبِسُونَ ٱلْحَقَّ بِٱلْبَٰطِلِ وَتَكْتُمُونَ ٱلْحَقَّ وَأَنتُمْ تَعْلَمُونَ', 'يأهل الكتب لم تلبسون الحق بالبطل وتكتمون الحق وأنتم تعلمون', NULL, 59, 'local:hafs-text.json'),
  ('hafs-3-72', 'hafs', 3, 72, 'وَقَالَت طَّآئِفَةٌۭ مِّنْ أَهْلِ ٱلْكِتَٰبِ ءَامِنُوا۟ بِٱلَّذِىٓ أُنزِلَ عَلَى ٱلَّذِينَ ءَامَنُوا۟ وَجْهَ ٱلنَّهَارِ وَٱكْفُرُوٓا۟ ءَاخِرَهُۥ لَعَلَّهُمْ يَرْجِعُونَ', 'وقالت طائفة من أهل الكتب ءامنوا بالذى أنزل على الذين ءامنوا وجه النهار واكفروا ءاخره لعلهم يرجعون', NULL, 59, 'local:hafs-text.json'),
  ('hafs-3-73', 'hafs', 3, 73, 'وَلَا تُؤْمِنُوٓا۟ إِلَّا لِمَن تَبِعَ دِينَكُمْ قُلْ إِنَّ ٱلْهُدَىٰ هُدَى ٱللَّهِ أَن يُؤْتَىٰٓ أَحَدٌۭ مِّثْلَ مَآ أُوتِيتُمْ أَوْ يُحَآجُّوكُمْ عِندَ رَبِّكُمْ ۗ قُلْ إِنَّ ٱلْفَضْلَ بِيَدِ ٱللَّهِ يُؤْتِيهِ مَن يَشَآءُ ۗ وَٱللَّهُ وَٰسِعٌ عَلِيمٌۭ', 'ولا تؤمنوا إلا لمن تبع دينكم قل إن الهدى هدى الله أن يؤتى أحد مثل ما أوتيتم أو يحاجوكم عند ربكم  قل إن الفضل بيد الله يؤتيه من يشاء  والله وسع عليم', NULL, 59, 'local:hafs-text.json'),
  ('hafs-3-74', 'hafs', 3, 74, 'يَخْتَصُّ بِرَحْمَتِهِۦ مَن يَشَآءُ ۗ وَٱللَّهُ ذُو ٱلْفَضْلِ ٱلْعَظِيمِ', 'يختص برحمته من يشاء  والله ذو الفضل العظيم', NULL, 59, 'local:hafs-text.json'),
  ('hafs-3-75', 'hafs', 3, 75, '۞ وَمِنْ أَهْلِ ٱلْكِتَٰبِ مَنْ إِن تَأْمَنْهُ بِقِنطَارٍۢ يُؤَدِّهِۦٓ إِلَيْكَ وَمِنْهُم مَّنْ إِن تَأْمَنْهُ بِدِينَارٍۢ لَّا يُؤَدِّهِۦٓ إِلَيْكَ إِلَّا مَا دُمْتَ عَلَيْهِ قَآئِمًۭا ۗ ذَٰلِكَ بِأَنَّهُمْ قَالُوا۟ لَيْسَ عَلَيْنَا فِى ٱلْأُمِّيِّۦنَ سَبِيلٌۭ وَيَقُولُونَ عَلَى ٱللَّهِ ٱلْكَذِبَ وَهُمْ يَعْلَمُونَ', 'ومن أهل الكتب من إن تأمنه بقنطار يؤده إليك ومنهم من إن تأمنه بدينار لا يؤده إليك إلا ما دمت عليه قائما  ذلك بأنهم قالوا ليس علينا فى الأمين سبيل ويقولون على الله الكذب وهم يعلمون', NULL, 59, 'local:hafs-text.json'),
  ('hafs-3-76', 'hafs', 3, 76, 'بَلَىٰ مَنْ أَوْفَىٰ بِعَهْدِهِۦ وَٱتَّقَىٰ فَإِنَّ ٱللَّهَ يُحِبُّ ٱلْمُتَّقِينَ', 'بلى من أوفى بعهده واتقى فإن الله يحب المتقين', NULL, 59, 'local:hafs-text.json'),
  ('hafs-3-77', 'hafs', 3, 77, 'إِنَّ ٱلَّذِينَ يَشْتَرُونَ بِعَهْدِ ٱللَّهِ وَأَيْمَٰنِهِمْ ثَمَنًۭا قَلِيلًا أُو۟لَٰٓئِكَ لَا خَلَٰقَ لَهُمْ فِى ٱلْءَاخِرَةِ وَلَا يُكَلِّمُهُمُ ٱللَّهُ وَلَا يَنظُرُ إِلَيْهِمْ يَوْمَ ٱلْقِيَٰمَةِ وَلَا يُزَكِّيهِمْ وَلَهُمْ عَذَابٌ أَلِيمٌۭ', 'إن الذين يشترون بعهد الله وأيمنهم ثمنا قليلا أولئك لا خلق لهم فى الءاخرة ولا يكلمهم الله ولا ينظر إليهم يوم القيمة ولا يزكيهم ولهم عذاب أليم', NULL, 59, 'local:hafs-text.json'),
  ('hafs-3-78', 'hafs', 3, 78, 'وَإِنَّ مِنْهُمْ لَفَرِيقًۭا يَلْوُۥنَ أَلْسِنَتَهُم بِٱلْكِتَٰبِ لِتَحْسَبُوهُ مِنَ ٱلْكِتَٰبِ وَمَا هُوَ مِنَ ٱلْكِتَٰبِ وَيَقُولُونَ هُوَ مِنْ عِندِ ٱللَّهِ وَمَا هُوَ مِنْ عِندِ ٱللَّهِ وَيَقُولُونَ عَلَى ٱللَّهِ ٱلْكَذِبَ وَهُمْ يَعْلَمُونَ', 'وإن منهم لفريقا يلون ألسنتهم بالكتب لتحسبوه من الكتب وما هو من الكتب ويقولون هو من عند الله وما هو من عند الله ويقولون على الله الكذب وهم يعلمون', NULL, 60, 'local:hafs-text.json'),
  ('hafs-3-79', 'hafs', 3, 79, 'مَا كَانَ لِبَشَرٍ أَن يُؤْتِيَهُ ٱللَّهُ ٱلْكِتَٰبَ وَٱلْحُكْمَ وَٱلنُّبُوَّةَ ثُمَّ يَقُولَ لِلنَّاسِ كُونُوا۟ عِبَادًۭا لِّى مِن دُونِ ٱللَّهِ وَلَٰكِن كُونُوا۟ رَبَّٰنِيِّۦنَ بِمَا كُنتُمْ تُعَلِّمُونَ ٱلْكِتَٰبَ وَبِمَا كُنتُمْ تَدْرُسُونَ', 'ما كان لبشر أن يؤتيه الله الكتب والحكم والنبوة ثم يقول للناس كونوا عبادا لى من دون الله ولكن كونوا ربنين بما كنتم تعلمون الكتب وبما كنتم تدرسون', NULL, 60, 'local:hafs-text.json'),
  ('hafs-3-80', 'hafs', 3, 80, 'وَلَا يَأْمُرَكُمْ أَن تَتَّخِذُوا۟ ٱلْمَلَٰٓئِكَةَ وَٱلنَّبِيِّۦنَ أَرْبَابًا ۗ أَيَأْمُرُكُم بِٱلْكُفْرِ بَعْدَ إِذْ أَنتُم مُّسْلِمُونَ', 'ولا يأمركم أن تتخذوا الملئكة والنبين أربابا  أيأمركم بالكفر بعد إذ أنتم مسلمون', NULL, 60, 'local:hafs-text.json'),
  ('hafs-3-81', 'hafs', 3, 81, 'وَإِذْ أَخَذَ ٱللَّهُ مِيثَٰقَ ٱلنَّبِيِّۦنَ لَمَآ ءَاتَيْتُكُم مِّن كِتَٰبٍۢ وَحِكْمَةٍۢ ثُمَّ جَآءَكُمْ رَسُولٌۭ مُّصَدِّقٌۭ لِّمَا مَعَكُمْ لَتُؤْمِنُنَّ بِهِۦ وَلَتَنصُرُنَّهُۥ ۚ قَالَ ءَأَقْرَرْتُمْ وَأَخَذْتُمْ عَلَىٰ ذَٰلِكُمْ إِصْرِى ۖ قَالُوٓا۟ أَقْرَرْنَا ۚ قَالَ فَٱشْهَدُوا۟ وَأَنَا۠ مَعَكُم مِّنَ ٱلشَّٰهِدِينَ', 'وإذ أخذ الله ميثق النبين لما ءاتيتكم من كتب وحكمة ثم جاءكم رسول مصدق لما معكم لتؤمنن به ولتنصرنه  قال ءأقررتم وأخذتم على ذلكم إصرى  قالوا أقررنا  قال فاشهدوا وأنا معكم من الشهدين', NULL, 60, 'local:hafs-text.json'),
  ('hafs-3-82', 'hafs', 3, 82, 'فَمَن تَوَلَّىٰ بَعْدَ ذَٰلِكَ فَأُو۟لَٰٓئِكَ هُمُ ٱلْفَٰسِقُونَ', 'فمن تولى بعد ذلك فأولئك هم الفسقون', NULL, 60, 'local:hafs-text.json'),
  ('hafs-3-83', 'hafs', 3, 83, 'أَفَغَيْرَ دِينِ ٱللَّهِ يَبْغُونَ وَلَهُۥٓ أَسْلَمَ مَن فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ طَوْعًۭا وَكَرْهًۭا وَإِلَيْهِ يُرْجَعُونَ', 'أفغير دين الله يبغون وله أسلم من فى السموت والأرض طوعا وكرها وإليه يرجعون', NULL, 60, 'local:hafs-text.json'),
  ('hafs-3-84', 'hafs', 3, 84, 'قُلْ ءَامَنَّا بِٱللَّهِ وَمَآ أُنزِلَ عَلَيْنَا وَمَآ أُنزِلَ عَلَىٰٓ إِبْرَٰهِيمَ وَإِسْمَٰعِيلَ وَإِسْحَٰقَ وَيَعْقُوبَ وَٱلْأَسْبَاطِ وَمَآ أُوتِىَ مُوسَىٰ وَعِيسَىٰ وَٱلنَّبِيُّونَ مِن رَّبِّهِمْ لَا نُفَرِّقُ بَيْنَ أَحَدٍۢ مِّنْهُمْ وَنَحْنُ لَهُۥ مُسْلِمُونَ', 'قل ءامنا بالله وما أنزل علينا وما أنزل على إبرهيم وإسمعيل وإسحق ويعقوب والأسباط وما أوتى موسى وعيسى والنبيون من ربهم لا نفرق بين أحد منهم ونحن له مسلمون', NULL, 61, 'local:hafs-text.json'),
  ('hafs-3-85', 'hafs', 3, 85, 'وَمَن يَبْتَغِ غَيْرَ ٱلْإِسْلَٰمِ دِينًۭا فَلَن يُقْبَلَ مِنْهُ وَهُوَ فِى ٱلْءَاخِرَةِ مِنَ ٱلْخَٰسِرِينَ', 'ومن يبتغ غير الإسلم دينا فلن يقبل منه وهو فى الءاخرة من الخسرين', NULL, 61, 'local:hafs-text.json'),
  ('hafs-3-86', 'hafs', 3, 86, 'كَيْفَ يَهْدِى ٱللَّهُ قَوْمًۭا كَفَرُوا۟ بَعْدَ إِيمَٰنِهِمْ وَشَهِدُوٓا۟ أَنَّ ٱلرَّسُولَ حَقٌّۭ وَجَآءَهُمُ ٱلْبَيِّنَٰتُ ۚ وَٱللَّهُ لَا يَهْدِى ٱلْقَوْمَ ٱلظَّٰلِمِينَ', 'كيف يهدى الله قوما كفروا بعد إيمنهم وشهدوا أن الرسول حق وجاءهم البينت  والله لا يهدى القوم الظلمين', NULL, 61, 'local:hafs-text.json'),
  ('hafs-3-87', 'hafs', 3, 87, 'أُو۟لَٰٓئِكَ جَزَآؤُهُمْ أَنَّ عَلَيْهِمْ لَعْنَةَ ٱللَّهِ وَٱلْمَلَٰٓئِكَةِ وَٱلنَّاسِ أَجْمَعِينَ', 'أولئك جزاؤهم أن عليهم لعنة الله والملئكة والناس أجمعين', NULL, 61, 'local:hafs-text.json'),
  ('hafs-3-88', 'hafs', 3, 88, 'خَٰلِدِينَ فِيهَا لَا يُخَفَّفُ عَنْهُمُ ٱلْعَذَابُ وَلَا هُمْ يُنظَرُونَ', 'خلدين فيها لا يخفف عنهم العذاب ولا هم ينظرون', NULL, 61, 'local:hafs-text.json'),
  ('hafs-3-89', 'hafs', 3, 89, 'إِلَّا ٱلَّذِينَ تَابُوا۟ مِنۢ بَعْدِ ذَٰلِكَ وَأَصْلَحُوا۟ فَإِنَّ ٱللَّهَ غَفُورٌۭ رَّحِيمٌ', 'إلا الذين تابوا من بعد ذلك وأصلحوا فإن الله غفور رحيم', NULL, 61, 'local:hafs-text.json'),
  ('hafs-3-90', 'hafs', 3, 90, 'إِنَّ ٱلَّذِينَ كَفَرُوا۟ بَعْدَ إِيمَٰنِهِمْ ثُمَّ ٱزْدَادُوا۟ كُفْرًۭا لَّن تُقْبَلَ تَوْبَتُهُمْ وَأُو۟لَٰٓئِكَ هُمُ ٱلضَّآلُّونَ', 'إن الذين كفروا بعد إيمنهم ثم ازدادوا كفرا لن تقبل توبتهم وأولئك هم الضالون', NULL, 61, 'local:hafs-text.json'),
  ('hafs-3-91', 'hafs', 3, 91, 'إِنَّ ٱلَّذِينَ كَفَرُوا۟ وَمَاتُوا۟ وَهُمْ كُفَّارٌۭ فَلَن يُقْبَلَ مِنْ أَحَدِهِم مِّلْءُ ٱلْأَرْضِ ذَهَبًۭا وَلَوِ ٱفْتَدَىٰ بِهِۦٓ ۗ أُو۟لَٰٓئِكَ لَهُمْ عَذَابٌ أَلِيمٌۭ وَمَا لَهُم مِّن نَّٰصِرِينَ', 'إن الذين كفروا وماتوا وهم كفار فلن يقبل من أحدهم ملء الأرض ذهبا ولو افتدى به  أولئك لهم عذاب أليم وما لهم من نصرين', NULL, 61, 'local:hafs-text.json'),
  ('hafs-3-92', 'hafs', 3, 92, 'لَن تَنَالُوا۟ ٱلْبِرَّ حَتَّىٰ تُنفِقُوا۟ مِمَّا تُحِبُّونَ ۚ وَمَا تُنفِقُوا۟ مِن شَىْءٍۢ فَإِنَّ ٱللَّهَ بِهِۦ عَلِيمٌۭ', 'لن تنالوا البر حتى تنفقوا مما تحبون  وما تنفقوا من شىء فإن الله به عليم', NULL, 62, 'local:hafs-text.json'),
  ('hafs-3-93', 'hafs', 3, 93, '۞ كُلُّ ٱلطَّعَامِ كَانَ حِلًّۭا لِّبَنِىٓ إِسْرَٰٓءِيلَ إِلَّا مَا حَرَّمَ إِسْرَٰٓءِيلُ عَلَىٰ نَفْسِهِۦ مِن قَبْلِ أَن تُنَزَّلَ ٱلتَّوْرَىٰةُ ۗ قُلْ فَأْتُوا۟ بِٱلتَّوْرَىٰةِ فَٱتْلُوهَآ إِن كُنتُمْ صَٰدِقِينَ', 'كل الطعام كان حلا لبنى إسرءيل إلا ما حرم إسرءيل على نفسه من قبل أن تنزل التورىة  قل فأتوا بالتورىة فاتلوها إن كنتم صدقين', NULL, 62, 'local:hafs-text.json'),
  ('hafs-3-94', 'hafs', 3, 94, 'فَمَنِ ٱفْتَرَىٰ عَلَى ٱللَّهِ ٱلْكَذِبَ مِنۢ بَعْدِ ذَٰلِكَ فَأُو۟لَٰٓئِكَ هُمُ ٱلظَّٰلِمُونَ', 'فمن افترى على الله الكذب من بعد ذلك فأولئك هم الظلمون', NULL, 62, 'local:hafs-text.json'),
  ('hafs-3-95', 'hafs', 3, 95, 'قُلْ صَدَقَ ٱللَّهُ ۗ فَٱتَّبِعُوا۟ مِلَّةَ إِبْرَٰهِيمَ حَنِيفًۭا وَمَا كَانَ مِنَ ٱلْمُشْرِكِينَ', 'قل صدق الله  فاتبعوا ملة إبرهيم حنيفا وما كان من المشركين', NULL, 62, 'local:hafs-text.json'),
  ('hafs-3-96', 'hafs', 3, 96, 'إِنَّ أَوَّلَ بَيْتٍۢ وُضِعَ لِلنَّاسِ لَلَّذِى بِبَكَّةَ مُبَارَكًۭا وَهُدًۭى لِّلْعَٰلَمِينَ', 'إن أول بيت وضع للناس للذى ببكة مباركا وهدى للعلمين', NULL, 62, 'local:hafs-text.json'),
  ('hafs-3-97', 'hafs', 3, 97, 'فِيهِ ءَايَٰتٌۢ بَيِّنَٰتٌۭ مَّقَامُ إِبْرَٰهِيمَ ۖ وَمَن دَخَلَهُۥ كَانَ ءَامِنًۭا ۗ وَلِلَّهِ عَلَى ٱلنَّاسِ حِجُّ ٱلْبَيْتِ مَنِ ٱسْتَطَاعَ إِلَيْهِ سَبِيلًۭا ۚ وَمَن كَفَرَ فَإِنَّ ٱللَّهَ غَنِىٌّ عَنِ ٱلْعَٰلَمِينَ', 'فيه ءايت بينت مقام إبرهيم  ومن دخله كان ءامنا  ولله على الناس حج البيت من استطاع إليه سبيلا  ومن كفر فإن الله غنى عن العلمين', NULL, 62, 'local:hafs-text.json'),
  ('hafs-3-98', 'hafs', 3, 98, 'قُلْ يَٰٓأَهْلَ ٱلْكِتَٰبِ لِمَ تَكْفُرُونَ بِـَٔايَٰتِ ٱللَّهِ وَٱللَّهُ شَهِيدٌ عَلَىٰ مَا تَعْمَلُونَ', 'قل يأهل الكتب لم تكفرون بايت الله والله شهيد على ما تعملون', NULL, 62, 'local:hafs-text.json'),
  ('hafs-3-99', 'hafs', 3, 99, 'قُلْ يَٰٓأَهْلَ ٱلْكِتَٰبِ لِمَ تَصُدُّونَ عَن سَبِيلِ ٱللَّهِ مَنْ ءَامَنَ تَبْغُونَهَا عِوَجًۭا وَأَنتُمْ شُهَدَآءُ ۗ وَمَا ٱللَّهُ بِغَٰفِلٍ عَمَّا تَعْمَلُونَ', 'قل يأهل الكتب لم تصدون عن سبيل الله من ءامن تبغونها عوجا وأنتم شهداء  وما الله بغفل عما تعملون', NULL, 62, 'local:hafs-text.json'),
  ('hafs-3-100', 'hafs', 3, 100, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِن تُطِيعُوا۟ فَرِيقًۭا مِّنَ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَٰبَ يَرُدُّوكُم بَعْدَ إِيمَٰنِكُمْ كَٰفِرِينَ', 'يأيها الذين ءامنوا إن تطيعوا فريقا من الذين أوتوا الكتب يردوكم بعد إيمنكم كفرين', NULL, 62, 'local:hafs-text.json'),
  ('hafs-3-101', 'hafs', 3, 101, 'وَكَيْفَ تَكْفُرُونَ وَأَنتُمْ تُتْلَىٰ عَلَيْكُمْ ءَايَٰتُ ٱللَّهِ وَفِيكُمْ رَسُولُهُۥ ۗ وَمَن يَعْتَصِم بِٱللَّهِ فَقَدْ هُدِىَ إِلَىٰ صِرَٰطٍۢ مُّسْتَقِيمٍۢ', 'وكيف تكفرون وأنتم تتلى عليكم ءايت الله وفيكم رسوله  ومن يعتصم بالله فقد هدى إلى صرط مستقيم', NULL, 63, 'local:hafs-text.json'),
  ('hafs-3-102', 'hafs', 3, 102, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱتَّقُوا۟ ٱللَّهَ حَقَّ تُقَاتِهِۦ وَلَا تَمُوتُنَّ إِلَّا وَأَنتُم مُّسْلِمُونَ', 'يأيها الذين ءامنوا اتقوا الله حق تقاته ولا تموتن إلا وأنتم مسلمون', NULL, 63, 'local:hafs-text.json'),
  ('hafs-3-103', 'hafs', 3, 103, 'وَٱعْتَصِمُوا۟ بِحَبْلِ ٱللَّهِ جَمِيعًۭا وَلَا تَفَرَّقُوا۟ ۚ وَٱذْكُرُوا۟ نِعْمَتَ ٱللَّهِ عَلَيْكُمْ إِذْ كُنتُمْ أَعْدَآءًۭ فَأَلَّفَ بَيْنَ قُلُوبِكُمْ فَأَصْبَحْتُم بِنِعْمَتِهِۦٓ إِخْوَٰنًۭا وَكُنتُمْ عَلَىٰ شَفَا حُفْرَةٍۢ مِّنَ ٱلنَّارِ فَأَنقَذَكُم مِّنْهَا ۗ كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ لَكُمْ ءَايَٰتِهِۦ لَعَلَّكُمْ تَهْتَدُونَ', 'واعتصموا بحبل الله جميعا ولا تفرقوا  واذكروا نعمت الله عليكم إذ كنتم أعداء فألف بين قلوبكم فأصبحتم بنعمته إخونا وكنتم على شفا حفرة من النار فأنقذكم منها  كذلك يبين الله لكم ءايته لعلكم تهتدون', NULL, 63, 'local:hafs-text.json'),
  ('hafs-3-104', 'hafs', 3, 104, 'وَلْتَكُن مِّنكُمْ أُمَّةٌۭ يَدْعُونَ إِلَى ٱلْخَيْرِ وَيَأْمُرُونَ بِٱلْمَعْرُوفِ وَيَنْهَوْنَ عَنِ ٱلْمُنكَرِ ۚ وَأُو۟لَٰٓئِكَ هُمُ ٱلْمُفْلِحُونَ', 'ولتكن منكم أمة يدعون إلى الخير ويأمرون بالمعروف وينهون عن المنكر  وأولئك هم المفلحون', NULL, 63, 'local:hafs-text.json'),
  ('hafs-3-105', 'hafs', 3, 105, 'وَلَا تَكُونُوا۟ كَٱلَّذِينَ تَفَرَّقُوا۟ وَٱخْتَلَفُوا۟ مِنۢ بَعْدِ مَا جَآءَهُمُ ٱلْبَيِّنَٰتُ ۚ وَأُو۟لَٰٓئِكَ لَهُمْ عَذَابٌ عَظِيمٌۭ', 'ولا تكونوا كالذين تفرقوا واختلفوا من بعد ما جاءهم البينت  وأولئك لهم عذاب عظيم', NULL, 63, 'local:hafs-text.json'),
  ('hafs-3-106', 'hafs', 3, 106, 'يَوْمَ تَبْيَضُّ وُجُوهٌۭ وَتَسْوَدُّ وُجُوهٌۭ ۚ فَأَمَّا ٱلَّذِينَ ٱسْوَدَّتْ وُجُوهُهُمْ أَكَفَرْتُم بَعْدَ إِيمَٰنِكُمْ فَذُوقُوا۟ ٱلْعَذَابَ بِمَا كُنتُمْ تَكْفُرُونَ', 'يوم تبيض وجوه وتسود وجوه  فأما الذين اسودت وجوههم أكفرتم بعد إيمنكم فذوقوا العذاب بما كنتم تكفرون', NULL, 63, 'local:hafs-text.json'),
  ('hafs-3-107', 'hafs', 3, 107, 'وَأَمَّا ٱلَّذِينَ ٱبْيَضَّتْ وُجُوهُهُمْ فَفِى رَحْمَةِ ٱللَّهِ هُمْ فِيهَا خَٰلِدُونَ', 'وأما الذين ابيضت وجوههم ففى رحمة الله هم فيها خلدون', NULL, 63, 'local:hafs-text.json')
insert into public.ayahs (id, riwayah, surah_number, ayah_number, text, simple_text, juz, page, source) values
  ('hafs-3-108', 'hafs', 3, 108, 'تِلْكَ ءَايَٰتُ ٱللَّهِ نَتْلُوهَا عَلَيْكَ بِٱلْحَقِّ ۗ وَمَا ٱللَّهُ يُرِيدُ ظُلْمًۭا لِّلْعَٰلَمِينَ', 'تلك ءايت الله نتلوها عليك بالحق  وما الله يريد ظلما للعلمين', NULL, 63, 'local:hafs-text.json'),
  ('hafs-3-109', 'hafs', 3, 109, 'وَلِلَّهِ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ ۚ وَإِلَى ٱللَّهِ تُرْجَعُ ٱلْأُمُورُ', 'ولله ما فى السموت وما فى الأرض  وإلى الله ترجع الأمور', NULL, 64, 'local:hafs-text.json'),
  ('hafs-3-110', 'hafs', 3, 110, 'كُنتُمْ خَيْرَ أُمَّةٍ أُخْرِجَتْ لِلنَّاسِ تَأْمُرُونَ بِٱلْمَعْرُوفِ وَتَنْهَوْنَ عَنِ ٱلْمُنكَرِ وَتُؤْمِنُونَ بِٱللَّهِ ۗ وَلَوْ ءَامَنَ أَهْلُ ٱلْكِتَٰبِ لَكَانَ خَيْرًۭا لَّهُم ۚ مِّنْهُمُ ٱلْمُؤْمِنُونَ وَأَكْثَرُهُمُ ٱلْفَٰسِقُونَ', 'كنتم خير أمة أخرجت للناس تأمرون بالمعروف وتنهون عن المنكر وتؤمنون بالله  ولو ءامن أهل الكتب لكان خيرا لهم  منهم المؤمنون وأكثرهم الفسقون', NULL, 64, 'local:hafs-text.json'),
  ('hafs-3-111', 'hafs', 3, 111, 'لَن يَضُرُّوكُمْ إِلَّآ أَذًۭى ۖ وَإِن يُقَٰتِلُوكُمْ يُوَلُّوكُمُ ٱلْأَدْبَارَ ثُمَّ لَا يُنصَرُونَ', 'لن يضروكم إلا أذى  وإن يقتلوكم يولوكم الأدبار ثم لا ينصرون', NULL, 64, 'local:hafs-text.json'),
  ('hafs-3-112', 'hafs', 3, 112, 'ضُرِبَتْ عَلَيْهِمُ ٱلذِّلَّةُ أَيْنَ مَا ثُقِفُوٓا۟ إِلَّا بِحَبْلٍۢ مِّنَ ٱللَّهِ وَحَبْلٍۢ مِّنَ ٱلنَّاسِ وَبَآءُو بِغَضَبٍۢ مِّنَ ٱللَّهِ وَضُرِبَتْ عَلَيْهِمُ ٱلْمَسْكَنَةُ ۚ ذَٰلِكَ بِأَنَّهُمْ كَانُوا۟ يَكْفُرُونَ بِـَٔايَٰتِ ٱللَّهِ وَيَقْتُلُونَ ٱلْأَنۢبِيَآءَ بِغَيْرِ حَقٍّۢ ۚ ذَٰلِكَ بِمَا عَصَوا۟ وَّكَانُوا۟ يَعْتَدُونَ', 'ضربت عليهم الذلة أين ما ثقفوا إلا بحبل من الله وحبل من الناس وباءو بغضب من الله وضربت عليهم المسكنة  ذلك بأنهم كانوا يكفرون بايت الله ويقتلون الأنبياء بغير حق  ذلك بما عصوا وكانوا يعتدون', NULL, 64, 'local:hafs-text.json'),
  ('hafs-3-113', 'hafs', 3, 113, '۞ لَيْسُوا۟ سَوَآءًۭ ۗ مِّنْ أَهْلِ ٱلْكِتَٰبِ أُمَّةٌۭ قَآئِمَةٌۭ يَتْلُونَ ءَايَٰتِ ٱللَّهِ ءَانَآءَ ٱلَّيْلِ وَهُمْ يَسْجُدُونَ', 'ليسوا سواء  من أهل الكتب أمة قائمة يتلون ءايت الله ءاناء اليل وهم يسجدون', NULL, 64, 'local:hafs-text.json'),
  ('hafs-3-114', 'hafs', 3, 114, 'يُؤْمِنُونَ بِٱللَّهِ وَٱلْيَوْمِ ٱلْءَاخِرِ وَيَأْمُرُونَ بِٱلْمَعْرُوفِ وَيَنْهَوْنَ عَنِ ٱلْمُنكَرِ وَيُسَٰرِعُونَ فِى ٱلْخَيْرَٰتِ وَأُو۟لَٰٓئِكَ مِنَ ٱلصَّٰلِحِينَ', 'يؤمنون بالله واليوم الءاخر ويأمرون بالمعروف وينهون عن المنكر ويسرعون فى الخيرت وأولئك من الصلحين', NULL, 64, 'local:hafs-text.json'),
  ('hafs-3-115', 'hafs', 3, 115, 'وَمَا يَفْعَلُوا۟ مِنْ خَيْرٍۢ فَلَن يُكْفَرُوهُ ۗ وَٱللَّهُ عَلِيمٌۢ بِٱلْمُتَّقِينَ', 'وما يفعلوا من خير فلن يكفروه  والله عليم بالمتقين', NULL, 64, 'local:hafs-text.json'),
  ('hafs-3-116', 'hafs', 3, 116, 'إِنَّ ٱلَّذِينَ كَفَرُوا۟ لَن تُغْنِىَ عَنْهُمْ أَمْوَٰلُهُمْ وَلَآ أَوْلَٰدُهُم مِّنَ ٱللَّهِ شَيْـًۭٔا ۖ وَأُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلنَّارِ ۚ هُمْ فِيهَا خَٰلِدُونَ', 'إن الذين كفروا لن تغنى عنهم أمولهم ولا أولدهم من الله شيا  وأولئك أصحب النار  هم فيها خلدون', NULL, 65, 'local:hafs-text.json'),
  ('hafs-3-117', 'hafs', 3, 117, 'مَثَلُ مَا يُنفِقُونَ فِى هَٰذِهِ ٱلْحَيَوٰةِ ٱلدُّنْيَا كَمَثَلِ رِيحٍۢ فِيهَا صِرٌّ أَصَابَتْ حَرْثَ قَوْمٍۢ ظَلَمُوٓا۟ أَنفُسَهُمْ فَأَهْلَكَتْهُ ۚ وَمَا ظَلَمَهُمُ ٱللَّهُ وَلَٰكِنْ أَنفُسَهُمْ يَظْلِمُونَ', 'مثل ما ينفقون فى هذه الحيوة الدنيا كمثل ريح فيها صر أصابت حرث قوم ظلموا أنفسهم فأهلكته  وما ظلمهم الله ولكن أنفسهم يظلمون', NULL, 65, 'local:hafs-text.json'),
  ('hafs-3-118', 'hafs', 3, 118, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَتَّخِذُوا۟ بِطَانَةًۭ مِّن دُونِكُمْ لَا يَأْلُونَكُمْ خَبَالًۭا وَدُّوا۟ مَا عَنِتُّمْ قَدْ بَدَتِ ٱلْبَغْضَآءُ مِنْ أَفْوَٰهِهِمْ وَمَا تُخْفِى صُدُورُهُمْ أَكْبَرُ ۚ قَدْ بَيَّنَّا لَكُمُ ٱلْءَايَٰتِ ۖ إِن كُنتُمْ تَعْقِلُونَ', 'يأيها الذين ءامنوا لا تتخذوا بطانة من دونكم لا يألونكم خبالا ودوا ما عنتم قد بدت البغضاء من أفوههم وما تخفى صدورهم أكبر  قد بينا لكم الءايت  إن كنتم تعقلون', NULL, 65, 'local:hafs-text.json'),
  ('hafs-3-119', 'hafs', 3, 119, 'هَٰٓأَنتُمْ أُو۟لَآءِ تُحِبُّونَهُمْ وَلَا يُحِبُّونَكُمْ وَتُؤْمِنُونَ بِٱلْكِتَٰبِ كُلِّهِۦ وَإِذَا لَقُوكُمْ قَالُوٓا۟ ءَامَنَّا وَإِذَا خَلَوْا۟ عَضُّوا۟ عَلَيْكُمُ ٱلْأَنَامِلَ مِنَ ٱلْغَيْظِ ۚ قُلْ مُوتُوا۟ بِغَيْظِكُمْ ۗ إِنَّ ٱللَّهَ عَلِيمٌۢ بِذَاتِ ٱلصُّدُورِ', 'هأنتم أولاء تحبونهم ولا يحبونكم وتؤمنون بالكتب كله وإذا لقوكم قالوا ءامنا وإذا خلوا عضوا عليكم الأنامل من الغيظ  قل موتوا بغيظكم  إن الله عليم بذات الصدور', NULL, 65, 'local:hafs-text.json'),
  ('hafs-3-120', 'hafs', 3, 120, 'إِن تَمْسَسْكُمْ حَسَنَةٌۭ تَسُؤْهُمْ وَإِن تُصِبْكُمْ سَيِّئَةٌۭ يَفْرَحُوا۟ بِهَا ۖ وَإِن تَصْبِرُوا۟ وَتَتَّقُوا۟ لَا يَضُرُّكُمْ كَيْدُهُمْ شَيْـًٔا ۗ إِنَّ ٱللَّهَ بِمَا يَعْمَلُونَ مُحِيطٌۭ', 'إن تمسسكم حسنة تسؤهم وإن تصبكم سيئة يفرحوا بها  وإن تصبروا وتتقوا لا يضركم كيدهم شيا  إن الله بما يعملون محيط', NULL, 65, 'local:hafs-text.json'),
  ('hafs-3-121', 'hafs', 3, 121, 'وَإِذْ غَدَوْتَ مِنْ أَهْلِكَ تُبَوِّئُ ٱلْمُؤْمِنِينَ مَقَٰعِدَ لِلْقِتَالِ ۗ وَٱللَّهُ سَمِيعٌ عَلِيمٌ', 'وإذ غدوت من أهلك تبوئ المؤمنين مقعد للقتال  والله سميع عليم', NULL, 65, 'local:hafs-text.json'),
  ('hafs-3-122', 'hafs', 3, 122, 'إِذْ هَمَّت طَّآئِفَتَانِ مِنكُمْ أَن تَفْشَلَا وَٱللَّهُ وَلِيُّهُمَا ۗ وَعَلَى ٱللَّهِ فَلْيَتَوَكَّلِ ٱلْمُؤْمِنُونَ', 'إذ همت طائفتان منكم أن تفشلا والله وليهما  وعلى الله فليتوكل المؤمنون', NULL, 66, 'local:hafs-text.json'),
  ('hafs-3-123', 'hafs', 3, 123, 'وَلَقَدْ نَصَرَكُمُ ٱللَّهُ بِبَدْرٍۢ وَأَنتُمْ أَذِلَّةٌۭ ۖ فَٱتَّقُوا۟ ٱللَّهَ لَعَلَّكُمْ تَشْكُرُونَ', 'ولقد نصركم الله ببدر وأنتم أذلة  فاتقوا الله لعلكم تشكرون', NULL, 66, 'local:hafs-text.json'),
  ('hafs-3-124', 'hafs', 3, 124, 'إِذْ تَقُولُ لِلْمُؤْمِنِينَ أَلَن يَكْفِيَكُمْ أَن يُمِدَّكُمْ رَبُّكُم بِثَلَٰثَةِ ءَالَٰفٍۢ مِّنَ ٱلْمَلَٰٓئِكَةِ مُنزَلِينَ', 'إذ تقول للمؤمنين ألن يكفيكم أن يمدكم ربكم بثلثة ءالف من الملئكة منزلين', NULL, 66, 'local:hafs-text.json'),
  ('hafs-3-125', 'hafs', 3, 125, 'بَلَىٰٓ ۚ إِن تَصْبِرُوا۟ وَتَتَّقُوا۟ وَيَأْتُوكُم مِّن فَوْرِهِمْ هَٰذَا يُمْدِدْكُمْ رَبُّكُم بِخَمْسَةِ ءَالَٰفٍۢ مِّنَ ٱلْمَلَٰٓئِكَةِ مُسَوِّمِينَ', 'بلى  إن تصبروا وتتقوا ويأتوكم من فورهم هذا يمددكم ربكم بخمسة ءالف من الملئكة مسومين', NULL, 66, 'local:hafs-text.json'),
  ('hafs-3-126', 'hafs', 3, 126, 'وَمَا جَعَلَهُ ٱللَّهُ إِلَّا بُشْرَىٰ لَكُمْ وَلِتَطْمَئِنَّ قُلُوبُكُم بِهِۦ ۗ وَمَا ٱلنَّصْرُ إِلَّا مِنْ عِندِ ٱللَّهِ ٱلْعَزِيزِ ٱلْحَكِيمِ', 'وما جعله الله إلا بشرى لكم ولتطمئن قلوبكم به  وما النصر إلا من عند الله العزيز الحكيم', NULL, 66, 'local:hafs-text.json'),
  ('hafs-3-127', 'hafs', 3, 127, 'لِيَقْطَعَ طَرَفًۭا مِّنَ ٱلَّذِينَ كَفَرُوٓا۟ أَوْ يَكْبِتَهُمْ فَيَنقَلِبُوا۟ خَآئِبِينَ', 'ليقطع طرفا من الذين كفروا أو يكبتهم فينقلبوا خائبين', NULL, 66, 'local:hafs-text.json'),
  ('hafs-3-128', 'hafs', 3, 128, 'لَيْسَ لَكَ مِنَ ٱلْأَمْرِ شَىْءٌ أَوْ يَتُوبَ عَلَيْهِمْ أَوْ يُعَذِّبَهُمْ فَإِنَّهُمْ ظَٰلِمُونَ', 'ليس لك من الأمر شىء أو يتوب عليهم أو يعذبهم فإنهم ظلمون', NULL, 66, 'local:hafs-text.json'),
  ('hafs-3-129', 'hafs', 3, 129, 'وَلِلَّهِ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ ۚ يَغْفِرُ لِمَن يَشَآءُ وَيُعَذِّبُ مَن يَشَآءُ ۚ وَٱللَّهُ غَفُورٌۭ رَّحِيمٌۭ', 'ولله ما فى السموت وما فى الأرض  يغفر لمن يشاء ويعذب من يشاء  والله غفور رحيم', NULL, 66, 'local:hafs-text.json'),
  ('hafs-3-130', 'hafs', 3, 130, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَأْكُلُوا۟ ٱلرِّبَوٰٓا۟ أَضْعَٰفًۭا مُّضَٰعَفَةًۭ ۖ وَٱتَّقُوا۟ ٱللَّهَ لَعَلَّكُمْ تُفْلِحُونَ', 'يأيها الذين ءامنوا لا تأكلوا الربوا أضعفا مضعفة  واتقوا الله لعلكم تفلحون', NULL, 66, 'local:hafs-text.json'),
  ('hafs-3-131', 'hafs', 3, 131, 'وَٱتَّقُوا۟ ٱلنَّارَ ٱلَّتِىٓ أُعِدَّتْ لِلْكَٰفِرِينَ', 'واتقوا النار التى أعدت للكفرين', NULL, 66, 'local:hafs-text.json'),
  ('hafs-3-132', 'hafs', 3, 132, 'وَأَطِيعُوا۟ ٱللَّهَ وَٱلرَّسُولَ لَعَلَّكُمْ تُرْحَمُونَ', 'وأطيعوا الله والرسول لعلكم ترحمون', NULL, 66, 'local:hafs-text.json'),
  ('hafs-3-133', 'hafs', 3, 133, '۞ وَسَارِعُوٓا۟ إِلَىٰ مَغْفِرَةٍۢ مِّن رَّبِّكُمْ وَجَنَّةٍ عَرْضُهَا ٱلسَّمَٰوَٰتُ وَٱلْأَرْضُ أُعِدَّتْ لِلْمُتَّقِينَ', 'وسارعوا إلى مغفرة من ربكم وجنة عرضها السموت والأرض أعدت للمتقين', NULL, 67, 'local:hafs-text.json'),
  ('hafs-3-134', 'hafs', 3, 134, 'ٱلَّذِينَ يُنفِقُونَ فِى ٱلسَّرَّآءِ وَٱلضَّرَّآءِ وَٱلْكَٰظِمِينَ ٱلْغَيْظَ وَٱلْعَافِينَ عَنِ ٱلنَّاسِ ۗ وَٱللَّهُ يُحِبُّ ٱلْمُحْسِنِينَ', 'الذين ينفقون فى السراء والضراء والكظمين الغيظ والعافين عن الناس  والله يحب المحسنين', NULL, 67, 'local:hafs-text.json'),
  ('hafs-3-135', 'hafs', 3, 135, 'وَٱلَّذِينَ إِذَا فَعَلُوا۟ فَٰحِشَةً أَوْ ظَلَمُوٓا۟ أَنفُسَهُمْ ذَكَرُوا۟ ٱللَّهَ فَٱسْتَغْفَرُوا۟ لِذُنُوبِهِمْ وَمَن يَغْفِرُ ٱلذُّنُوبَ إِلَّا ٱللَّهُ وَلَمْ يُصِرُّوا۟ عَلَىٰ مَا فَعَلُوا۟ وَهُمْ يَعْلَمُونَ', 'والذين إذا فعلوا فحشة أو ظلموا أنفسهم ذكروا الله فاستغفروا لذنوبهم ومن يغفر الذنوب إلا الله ولم يصروا على ما فعلوا وهم يعلمون', NULL, 67, 'local:hafs-text.json'),
  ('hafs-3-136', 'hafs', 3, 136, 'أُو۟لَٰٓئِكَ جَزَآؤُهُم مَّغْفِرَةٌۭ مِّن رَّبِّهِمْ وَجَنَّٰتٌۭ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ خَٰلِدِينَ فِيهَا ۚ وَنِعْمَ أَجْرُ ٱلْعَٰمِلِينَ', 'أولئك جزاؤهم مغفرة من ربهم وجنت تجرى من تحتها الأنهر خلدين فيها  ونعم أجر العملين', NULL, 67, 'local:hafs-text.json'),
  ('hafs-3-137', 'hafs', 3, 137, 'قَدْ خَلَتْ مِن قَبْلِكُمْ سُنَنٌۭ فَسِيرُوا۟ فِى ٱلْأَرْضِ فَٱنظُرُوا۟ كَيْفَ كَانَ عَٰقِبَةُ ٱلْمُكَذِّبِينَ', 'قد خلت من قبلكم سنن فسيروا فى الأرض فانظروا كيف كان عقبة المكذبين', NULL, 67, 'local:hafs-text.json'),
  ('hafs-3-138', 'hafs', 3, 138, 'هَٰذَا بَيَانٌۭ لِّلنَّاسِ وَهُدًۭى وَمَوْعِظَةٌۭ لِّلْمُتَّقِينَ', 'هذا بيان للناس وهدى وموعظة للمتقين', NULL, 67, 'local:hafs-text.json'),
  ('hafs-3-139', 'hafs', 3, 139, 'وَلَا تَهِنُوا۟ وَلَا تَحْزَنُوا۟ وَأَنتُمُ ٱلْأَعْلَوْنَ إِن كُنتُم مُّؤْمِنِينَ', 'ولا تهنوا ولا تحزنوا وأنتم الأعلون إن كنتم مؤمنين', NULL, 67, 'local:hafs-text.json'),
  ('hafs-3-140', 'hafs', 3, 140, 'إِن يَمْسَسْكُمْ قَرْحٌۭ فَقَدْ مَسَّ ٱلْقَوْمَ قَرْحٌۭ مِّثْلُهُۥ ۚ وَتِلْكَ ٱلْأَيَّامُ نُدَاوِلُهَا بَيْنَ ٱلنَّاسِ وَلِيَعْلَمَ ٱللَّهُ ٱلَّذِينَ ءَامَنُوا۟ وَيَتَّخِذَ مِنكُمْ شُهَدَآءَ ۗ وَٱللَّهُ لَا يُحِبُّ ٱلظَّٰلِمِينَ', 'إن يمسسكم قرح فقد مس القوم قرح مثله  وتلك الأيام نداولها بين الناس وليعلم الله الذين ءامنوا ويتخذ منكم شهداء  والله لا يحب الظلمين', NULL, 67, 'local:hafs-text.json'),
  ('hafs-3-141', 'hafs', 3, 141, 'وَلِيُمَحِّصَ ٱللَّهُ ٱلَّذِينَ ءَامَنُوا۟ وَيَمْحَقَ ٱلْكَٰفِرِينَ', 'وليمحص الله الذين ءامنوا ويمحق الكفرين', NULL, 68, 'local:hafs-text.json'),
  ('hafs-3-142', 'hafs', 3, 142, 'أَمْ حَسِبْتُمْ أَن تَدْخُلُوا۟ ٱلْجَنَّةَ وَلَمَّا يَعْلَمِ ٱللَّهُ ٱلَّذِينَ جَٰهَدُوا۟ مِنكُمْ وَيَعْلَمَ ٱلصَّٰبِرِينَ', 'أم حسبتم أن تدخلوا الجنة ولما يعلم الله الذين جهدوا منكم ويعلم الصبرين', NULL, 68, 'local:hafs-text.json'),
  ('hafs-3-143', 'hafs', 3, 143, 'وَلَقَدْ كُنتُمْ تَمَنَّوْنَ ٱلْمَوْتَ مِن قَبْلِ أَن تَلْقَوْهُ فَقَدْ رَأَيْتُمُوهُ وَأَنتُمْ تَنظُرُونَ', 'ولقد كنتم تمنون الموت من قبل أن تلقوه فقد رأيتموه وأنتم تنظرون', NULL, 68, 'local:hafs-text.json'),
  ('hafs-3-144', 'hafs', 3, 144, 'وَمَا مُحَمَّدٌ إِلَّا رَسُولٌۭ قَدْ خَلَتْ مِن قَبْلِهِ ٱلرُّسُلُ ۚ أَفَإِي۟ن مَّاتَ أَوْ قُتِلَ ٱنقَلَبْتُمْ عَلَىٰٓ أَعْقَٰبِكُمْ ۚ وَمَن يَنقَلِبْ عَلَىٰ عَقِبَيْهِ فَلَن يَضُرَّ ٱللَّهَ شَيْـًۭٔا ۗ وَسَيَجْزِى ٱللَّهُ ٱلشَّٰكِرِينَ', 'وما محمد إلا رسول قد خلت من قبله الرسل  أفإين مات أو قتل انقلبتم على أعقبكم  ومن ينقلب على عقبيه فلن يضر الله شيا  وسيجزى الله الشكرين', NULL, 68, 'local:hafs-text.json'),
  ('hafs-3-145', 'hafs', 3, 145, 'وَمَا كَانَ لِنَفْسٍ أَن تَمُوتَ إِلَّا بِإِذْنِ ٱللَّهِ كِتَٰبًۭا مُّؤَجَّلًۭا ۗ وَمَن يُرِدْ ثَوَابَ ٱلدُّنْيَا نُؤْتِهِۦ مِنْهَا وَمَن يُرِدْ ثَوَابَ ٱلْءَاخِرَةِ نُؤْتِهِۦ مِنْهَا ۚ وَسَنَجْزِى ٱلشَّٰكِرِينَ', 'وما كان لنفس أن تموت إلا بإذن الله كتبا مؤجلا  ومن يرد ثواب الدنيا نؤته منها ومن يرد ثواب الءاخرة نؤته منها  وسنجزى الشكرين', NULL, 68, 'local:hafs-text.json'),
  ('hafs-3-146', 'hafs', 3, 146, 'وَكَأَيِّن مِّن نَّبِىٍّۢ قَٰتَلَ مَعَهُۥ رِبِّيُّونَ كَثِيرٌۭ فَمَا وَهَنُوا۟ لِمَآ أَصَابَهُمْ فِى سَبِيلِ ٱللَّهِ وَمَا ضَعُفُوا۟ وَمَا ٱسْتَكَانُوا۟ ۗ وَٱللَّهُ يُحِبُّ ٱلصَّٰبِرِينَ', 'وكأين من نبى قتل معه ربيون كثير فما وهنوا لما أصابهم فى سبيل الله وما ضعفوا وما استكانوا  والله يحب الصبرين', NULL, 68, 'local:hafs-text.json'),
  ('hafs-3-147', 'hafs', 3, 147, 'وَمَا كَانَ قَوْلَهُمْ إِلَّآ أَن قَالُوا۟ رَبَّنَا ٱغْفِرْ لَنَا ذُنُوبَنَا وَإِسْرَافَنَا فِىٓ أَمْرِنَا وَثَبِّتْ أَقْدَامَنَا وَٱنصُرْنَا عَلَى ٱلْقَوْمِ ٱلْكَٰفِرِينَ', 'وما كان قولهم إلا أن قالوا ربنا اغفر لنا ذنوبنا وإسرافنا فى أمرنا وثبت أقدامنا وانصرنا على القوم الكفرين', NULL, 68, 'local:hafs-text.json'),
  ('hafs-3-148', 'hafs', 3, 148, 'فَـَٔاتَىٰهُمُ ٱللَّهُ ثَوَابَ ٱلدُّنْيَا وَحُسْنَ ثَوَابِ ٱلْءَاخِرَةِ ۗ وَٱللَّهُ يُحِبُّ ٱلْمُحْسِنِينَ', 'فاتىهم الله ثواب الدنيا وحسن ثواب الءاخرة  والله يحب المحسنين', NULL, 68, 'local:hafs-text.json'),
  ('hafs-3-149', 'hafs', 3, 149, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِن تُطِيعُوا۟ ٱلَّذِينَ كَفَرُوا۟ يَرُدُّوكُمْ عَلَىٰٓ أَعْقَٰبِكُمْ فَتَنقَلِبُوا۟ خَٰسِرِينَ', 'يأيها الذين ءامنوا إن تطيعوا الذين كفروا يردوكم على أعقبكم فتنقلبوا خسرين', NULL, 69, 'local:hafs-text.json'),
  ('hafs-3-150', 'hafs', 3, 150, 'بَلِ ٱللَّهُ مَوْلَىٰكُمْ ۖ وَهُوَ خَيْرُ ٱلنَّٰصِرِينَ', 'بل الله مولىكم  وهو خير النصرين', NULL, 69, 'local:hafs-text.json'),
  ('hafs-3-151', 'hafs', 3, 151, 'سَنُلْقِى فِى قُلُوبِ ٱلَّذِينَ كَفَرُوا۟ ٱلرُّعْبَ بِمَآ أَشْرَكُوا۟ بِٱللَّهِ مَا لَمْ يُنَزِّلْ بِهِۦ سُلْطَٰنًۭا ۖ وَمَأْوَىٰهُمُ ٱلنَّارُ ۚ وَبِئْسَ مَثْوَى ٱلظَّٰلِمِينَ', 'سنلقى فى قلوب الذين كفروا الرعب بما أشركوا بالله ما لم ينزل به سلطنا  ومأوىهم النار  وبئس مثوى الظلمين', NULL, 69, 'local:hafs-text.json'),
  ('hafs-3-152', 'hafs', 3, 152, 'وَلَقَدْ صَدَقَكُمُ ٱللَّهُ وَعْدَهُۥٓ إِذْ تَحُسُّونَهُم بِإِذْنِهِۦ ۖ حَتَّىٰٓ إِذَا فَشِلْتُمْ وَتَنَٰزَعْتُمْ فِى ٱلْأَمْرِ وَعَصَيْتُم مِّنۢ بَعْدِ مَآ أَرَىٰكُم مَّا تُحِبُّونَ ۚ مِنكُم مَّن يُرِيدُ ٱلدُّنْيَا وَمِنكُم مَّن يُرِيدُ ٱلْءَاخِرَةَ ۚ ثُمَّ صَرَفَكُمْ عَنْهُمْ لِيَبْتَلِيَكُمْ ۖ وَلَقَدْ عَفَا عَنكُمْ ۗ وَٱللَّهُ ذُو فَضْلٍ عَلَى ٱلْمُؤْمِنِينَ', 'ولقد صدقكم الله وعده إذ تحسونهم بإذنه  حتى إذا فشلتم وتنزعتم فى الأمر وعصيتم من بعد ما أرىكم ما تحبون  منكم من يريد الدنيا ومنكم من يريد الءاخرة  ثم صرفكم عنهم ليبتليكم  ولقد عفا عنكم  والله ذو فضل على المؤمنين', NULL, 69, 'local:hafs-text.json'),
  ('hafs-3-153', 'hafs', 3, 153, '۞ إِذْ تُصْعِدُونَ وَلَا تَلْوُۥنَ عَلَىٰٓ أَحَدٍۢ وَٱلرَّسُولُ يَدْعُوكُمْ فِىٓ أُخْرَىٰكُمْ فَأَثَٰبَكُمْ غَمًّۢا بِغَمٍّۢ لِّكَيْلَا تَحْزَنُوا۟ عَلَىٰ مَا فَاتَكُمْ وَلَا مَآ أَصَٰبَكُمْ ۗ وَٱللَّهُ خَبِيرٌۢ بِمَا تَعْمَلُونَ', 'إذ تصعدون ولا تلون على أحد والرسول يدعوكم فى أخرىكم فأثبكم غما بغم لكيلا تحزنوا على ما فاتكم ولا ما أصبكم  والله خبير بما تعملون', NULL, 69, 'local:hafs-text.json'),
  ('hafs-3-154', 'hafs', 3, 154, 'ثُمَّ أَنزَلَ عَلَيْكُم مِّنۢ بَعْدِ ٱلْغَمِّ أَمَنَةًۭ نُّعَاسًۭا يَغْشَىٰ طَآئِفَةًۭ مِّنكُمْ ۖ وَطَآئِفَةٌۭ قَدْ أَهَمَّتْهُمْ أَنفُسُهُمْ يَظُنُّونَ بِٱللَّهِ غَيْرَ ٱلْحَقِّ ظَنَّ ٱلْجَٰهِلِيَّةِ ۖ يَقُولُونَ هَل لَّنَا مِنَ ٱلْأَمْرِ مِن شَىْءٍۢ ۗ قُلْ إِنَّ ٱلْأَمْرَ كُلَّهُۥ لِلَّهِ ۗ يُخْفُونَ فِىٓ أَنفُسِهِم مَّا لَا يُبْدُونَ لَكَ ۖ يَقُولُونَ لَوْ كَانَ لَنَا مِنَ ٱلْأَمْرِ شَىْءٌۭ مَّا قُتِلْنَا هَٰهُنَا ۗ قُل لَّوْ كُنتُمْ فِى بُيُوتِكُمْ لَبَرَزَ ٱلَّذِينَ كُتِبَ عَلَيْهِمُ ٱلْقَتْلُ إِلَىٰ مَضَاجِعِهِمْ ۖ وَلِيَبْتَلِىَ ٱللَّهُ مَا فِى صُدُورِكُمْ وَلِيُمَحِّصَ مَا فِى قُلُوبِكُمْ ۗ وَٱللَّهُ عَلِيمٌۢ بِذَاتِ ٱلصُّدُورِ', 'ثم أنزل عليكم من بعد الغم أمنة نعاسا يغشى طائفة منكم  وطائفة قد أهمتهم أنفسهم يظنون بالله غير الحق ظن الجهلية  يقولون هل لنا من الأمر من شىء  قل إن الأمر كله لله  يخفون فى أنفسهم ما لا يبدون لك  يقولون لو كان لنا من الأمر شىء ما قتلنا ههنا  قل لو كنتم فى بيوتكم لبرز الذين كتب عليهم القتل إلى مضاجعهم  وليبتلى الله ما فى صدوركم وليمحص ما فى قلوبكم  والله عليم بذات الصدور', NULL, 70, 'local:hafs-text.json'),
  ('hafs-3-155', 'hafs', 3, 155, 'إِنَّ ٱلَّذِينَ تَوَلَّوْا۟ مِنكُمْ يَوْمَ ٱلْتَقَى ٱلْجَمْعَانِ إِنَّمَا ٱسْتَزَلَّهُمُ ٱلشَّيْطَٰنُ بِبَعْضِ مَا كَسَبُوا۟ ۖ وَلَقَدْ عَفَا ٱللَّهُ عَنْهُمْ ۗ إِنَّ ٱللَّهَ غَفُورٌ حَلِيمٌۭ', 'إن الذين تولوا منكم يوم التقى الجمعان إنما استزلهم الشيطن ببعض ما كسبوا  ولقد عفا الله عنهم  إن الله غفور حليم', NULL, 70, 'local:hafs-text.json'),
  ('hafs-3-156', 'hafs', 3, 156, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَكُونُوا۟ كَٱلَّذِينَ كَفَرُوا۟ وَقَالُوا۟ لِإِخْوَٰنِهِمْ إِذَا ضَرَبُوا۟ فِى ٱلْأَرْضِ أَوْ كَانُوا۟ غُزًّۭى لَّوْ كَانُوا۟ عِندَنَا مَا مَاتُوا۟ وَمَا قُتِلُوا۟ لِيَجْعَلَ ٱللَّهُ ذَٰلِكَ حَسْرَةًۭ فِى قُلُوبِهِمْ ۗ وَٱللَّهُ يُحْىِۦ وَيُمِيتُ ۗ وَٱللَّهُ بِمَا تَعْمَلُونَ بَصِيرٌۭ', 'يأيها الذين ءامنوا لا تكونوا كالذين كفروا وقالوا لإخونهم إذا ضربوا فى الأرض أو كانوا غزى لو كانوا عندنا ما ماتوا وما قتلوا ليجعل الله ذلك حسرة فى قلوبهم  والله يحى ويميت  والله بما تعملون بصير', NULL, 70, 'local:hafs-text.json'),
  ('hafs-3-157', 'hafs', 3, 157, 'وَلَئِن قُتِلْتُمْ فِى سَبِيلِ ٱللَّهِ أَوْ مُتُّمْ لَمَغْفِرَةٌۭ مِّنَ ٱللَّهِ وَرَحْمَةٌ خَيْرٌۭ مِّمَّا يَجْمَعُونَ', 'ولئن قتلتم فى سبيل الله أو متم لمغفرة من الله ورحمة خير مما يجمعون', NULL, 70, 'local:hafs-text.json'),
  ('hafs-3-158', 'hafs', 3, 158, 'وَلَئِن مُّتُّمْ أَوْ قُتِلْتُمْ لَإِلَى ٱللَّهِ تُحْشَرُونَ', 'ولئن متم أو قتلتم لإلى الله تحشرون', NULL, 71, 'local:hafs-text.json'),
  ('hafs-3-159', 'hafs', 3, 159, 'فَبِمَا رَحْمَةٍۢ مِّنَ ٱللَّهِ لِنتَ لَهُمْ ۖ وَلَوْ كُنتَ فَظًّا غَلِيظَ ٱلْقَلْبِ لَٱنفَضُّوا۟ مِنْ حَوْلِكَ ۖ فَٱعْفُ عَنْهُمْ وَٱسْتَغْفِرْ لَهُمْ وَشَاوِرْهُمْ فِى ٱلْأَمْرِ ۖ فَإِذَا عَزَمْتَ فَتَوَكَّلْ عَلَى ٱللَّهِ ۚ إِنَّ ٱللَّهَ يُحِبُّ ٱلْمُتَوَكِّلِينَ', 'فبما رحمة من الله لنت لهم  ولو كنت فظا غليظ القلب لانفضوا من حولك  فاعف عنهم واستغفر لهم وشاورهم فى الأمر  فإذا عزمت فتوكل على الله  إن الله يحب المتوكلين', NULL, 71, 'local:hafs-text.json'),
  ('hafs-3-160', 'hafs', 3, 160, 'إِن يَنصُرْكُمُ ٱللَّهُ فَلَا غَالِبَ لَكُمْ ۖ وَإِن يَخْذُلْكُمْ فَمَن ذَا ٱلَّذِى يَنصُرُكُم مِّنۢ بَعْدِهِۦ ۗ وَعَلَى ٱللَّهِ فَلْيَتَوَكَّلِ ٱلْمُؤْمِنُونَ', 'إن ينصركم الله فلا غالب لكم  وإن يخذلكم فمن ذا الذى ينصركم من بعده  وعلى الله فليتوكل المؤمنون', NULL, 71, 'local:hafs-text.json'),
  ('hafs-3-161', 'hafs', 3, 161, 'وَمَا كَانَ لِنَبِىٍّ أَن يَغُلَّ ۚ وَمَن يَغْلُلْ يَأْتِ بِمَا غَلَّ يَوْمَ ٱلْقِيَٰمَةِ ۚ ثُمَّ تُوَفَّىٰ كُلُّ نَفْسٍۢ مَّا كَسَبَتْ وَهُمْ لَا يُظْلَمُونَ', 'وما كان لنبى أن يغل  ومن يغلل يأت بما غل يوم القيمة  ثم توفى كل نفس ما كسبت وهم لا يظلمون', NULL, 71, 'local:hafs-text.json'),
  ('hafs-3-162', 'hafs', 3, 162, 'أَفَمَنِ ٱتَّبَعَ رِضْوَٰنَ ٱللَّهِ كَمَنۢ بَآءَ بِسَخَطٍۢ مِّنَ ٱللَّهِ وَمَأْوَىٰهُ جَهَنَّمُ ۚ وَبِئْسَ ٱلْمَصِيرُ', 'أفمن اتبع رضون الله كمن باء بسخط من الله ومأوىه جهنم  وبئس المصير', NULL, 71, 'local:hafs-text.json'),
  ('hafs-3-163', 'hafs', 3, 163, 'هُمْ دَرَجَٰتٌ عِندَ ٱللَّهِ ۗ وَٱللَّهُ بَصِيرٌۢ بِمَا يَعْمَلُونَ', 'هم درجت عند الله  والله بصير بما يعملون', NULL, 71, 'local:hafs-text.json'),
  ('hafs-3-164', 'hafs', 3, 164, 'لَقَدْ مَنَّ ٱللَّهُ عَلَى ٱلْمُؤْمِنِينَ إِذْ بَعَثَ فِيهِمْ رَسُولًۭا مِّنْ أَنفُسِهِمْ يَتْلُوا۟ عَلَيْهِمْ ءَايَٰتِهِۦ وَيُزَكِّيهِمْ وَيُعَلِّمُهُمُ ٱلْكِتَٰبَ وَٱلْحِكْمَةَ وَإِن كَانُوا۟ مِن قَبْلُ لَفِى ضَلَٰلٍۢ مُّبِينٍ', 'لقد من الله على المؤمنين إذ بعث فيهم رسولا من أنفسهم يتلوا عليهم ءايته ويزكيهم ويعلمهم الكتب والحكمة وإن كانوا من قبل لفى ضلل مبين', NULL, 71, 'local:hafs-text.json'),
  ('hafs-3-165', 'hafs', 3, 165, 'أَوَلَمَّآ أَصَٰبَتْكُم مُّصِيبَةٌۭ قَدْ أَصَبْتُم مِّثْلَيْهَا قُلْتُمْ أَنَّىٰ هَٰذَا ۖ قُلْ هُوَ مِنْ عِندِ أَنفُسِكُمْ ۗ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَىْءٍۢ قَدِيرٌۭ', 'أولما أصبتكم مصيبة قد أصبتم مثليها قلتم أنى هذا  قل هو من عند أنفسكم  إن الله على كل شىء قدير', NULL, 71, 'local:hafs-text.json'),
  ('hafs-3-166', 'hafs', 3, 166, 'وَمَآ أَصَٰبَكُمْ يَوْمَ ٱلْتَقَى ٱلْجَمْعَانِ فَبِإِذْنِ ٱللَّهِ وَلِيَعْلَمَ ٱلْمُؤْمِنِينَ', 'وما أصبكم يوم التقى الجمعان فبإذن الله وليعلم المؤمنين', NULL, 72, 'local:hafs-text.json'),
  ('hafs-3-167', 'hafs', 3, 167, 'وَلِيَعْلَمَ ٱلَّذِينَ نَافَقُوا۟ ۚ وَقِيلَ لَهُمْ تَعَالَوْا۟ قَٰتِلُوا۟ فِى سَبِيلِ ٱللَّهِ أَوِ ٱدْفَعُوا۟ ۖ قَالُوا۟ لَوْ نَعْلَمُ قِتَالًۭا لَّٱتَّبَعْنَٰكُمْ ۗ هُمْ لِلْكُفْرِ يَوْمَئِذٍ أَقْرَبُ مِنْهُمْ لِلْإِيمَٰنِ ۚ يَقُولُونَ بِأَفْوَٰهِهِم مَّا لَيْسَ فِى قُلُوبِهِمْ ۗ وَٱللَّهُ أَعْلَمُ بِمَا يَكْتُمُونَ', 'وليعلم الذين نافقوا  وقيل لهم تعالوا قتلوا فى سبيل الله أو ادفعوا  قالوا لو نعلم قتالا لاتبعنكم  هم للكفر يومئذ أقرب منهم للإيمن  يقولون بأفوههم ما ليس فى قلوبهم  والله أعلم بما يكتمون', NULL, 72, 'local:hafs-text.json'),
  ('hafs-3-168', 'hafs', 3, 168, 'ٱلَّذِينَ قَالُوا۟ لِإِخْوَٰنِهِمْ وَقَعَدُوا۟ لَوْ أَطَاعُونَا مَا قُتِلُوا۟ ۗ قُلْ فَٱدْرَءُوا۟ عَنْ أَنفُسِكُمُ ٱلْمَوْتَ إِن كُنتُمْ صَٰدِقِينَ', 'الذين قالوا لإخونهم وقعدوا لو أطاعونا ما قتلوا  قل فادرءوا عن أنفسكم الموت إن كنتم صدقين', NULL, 72, 'local:hafs-text.json'),
  ('hafs-3-169', 'hafs', 3, 169, 'وَلَا تَحْسَبَنَّ ٱلَّذِينَ قُتِلُوا۟ فِى سَبِيلِ ٱللَّهِ أَمْوَٰتًۢا ۚ بَلْ أَحْيَآءٌ عِندَ رَبِّهِمْ يُرْزَقُونَ', 'ولا تحسبن الذين قتلوا فى سبيل الله أموتا  بل أحياء عند ربهم يرزقون', NULL, 72, 'local:hafs-text.json'),
  ('hafs-3-170', 'hafs', 3, 170, 'فَرِحِينَ بِمَآ ءَاتَىٰهُمُ ٱللَّهُ مِن فَضْلِهِۦ وَيَسْتَبْشِرُونَ بِٱلَّذِينَ لَمْ يَلْحَقُوا۟ بِهِم مِّنْ خَلْفِهِمْ أَلَّا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ', 'فرحين بما ءاتىهم الله من فضله ويستبشرون بالذين لم يلحقوا بهم من خلفهم ألا خوف عليهم ولا هم يحزنون', NULL, 72, 'local:hafs-text.json'),
  ('hafs-3-171', 'hafs', 3, 171, '۞ يَسْتَبْشِرُونَ بِنِعْمَةٍۢ مِّنَ ٱللَّهِ وَفَضْلٍۢ وَأَنَّ ٱللَّهَ لَا يُضِيعُ أَجْرَ ٱلْمُؤْمِنِينَ', 'يستبشرون بنعمة من الله وفضل وأن الله لا يضيع أجر المؤمنين', NULL, 72, 'local:hafs-text.json'),
  ('hafs-3-172', 'hafs', 3, 172, 'ٱلَّذِينَ ٱسْتَجَابُوا۟ لِلَّهِ وَٱلرَّسُولِ مِنۢ بَعْدِ مَآ أَصَابَهُمُ ٱلْقَرْحُ ۚ لِلَّذِينَ أَحْسَنُوا۟ مِنْهُمْ وَٱتَّقَوْا۟ أَجْرٌ عَظِيمٌ', 'الذين استجابوا لله والرسول من بعد ما أصابهم القرح  للذين أحسنوا منهم واتقوا أجر عظيم', NULL, 72, 'local:hafs-text.json'),
  ('hafs-3-173', 'hafs', 3, 173, 'ٱلَّذِينَ قَالَ لَهُمُ ٱلنَّاسُ إِنَّ ٱلنَّاسَ قَدْ جَمَعُوا۟ لَكُمْ فَٱخْشَوْهُمْ فَزَادَهُمْ إِيمَٰنًۭا وَقَالُوا۟ حَسْبُنَا ٱللَّهُ وَنِعْمَ ٱلْوَكِيلُ', 'الذين قال لهم الناس إن الناس قد جمعوا لكم فاخشوهم فزادهم إيمنا وقالوا حسبنا الله ونعم الوكيل', NULL, 72, 'local:hafs-text.json'),
  ('hafs-3-174', 'hafs', 3, 174, 'فَٱنقَلَبُوا۟ بِنِعْمَةٍۢ مِّنَ ٱللَّهِ وَفَضْلٍۢ لَّمْ يَمْسَسْهُمْ سُوٓءٌۭ وَٱتَّبَعُوا۟ رِضْوَٰنَ ٱللَّهِ ۗ وَٱللَّهُ ذُو فَضْلٍ عَظِيمٍ', 'فانقلبوا بنعمة من الله وفضل لم يمسسهم سوء واتبعوا رضون الله  والله ذو فضل عظيم', NULL, 73, 'local:hafs-text.json'),
  ('hafs-3-175', 'hafs', 3, 175, 'إِنَّمَا ذَٰلِكُمُ ٱلشَّيْطَٰنُ يُخَوِّفُ أَوْلِيَآءَهُۥ فَلَا تَخَافُوهُمْ وَخَافُونِ إِن كُنتُم مُّؤْمِنِينَ', 'إنما ذلكم الشيطن يخوف أولياءه فلا تخافوهم وخافون إن كنتم مؤمنين', NULL, 73, 'local:hafs-text.json'),
  ('hafs-3-176', 'hafs', 3, 176, 'وَلَا يَحْزُنكَ ٱلَّذِينَ يُسَٰرِعُونَ فِى ٱلْكُفْرِ ۚ إِنَّهُمْ لَن يَضُرُّوا۟ ٱللَّهَ شَيْـًۭٔا ۗ يُرِيدُ ٱللَّهُ أَلَّا يَجْعَلَ لَهُمْ حَظًّۭا فِى ٱلْءَاخِرَةِ ۖ وَلَهُمْ عَذَابٌ عَظِيمٌ', 'ولا يحزنك الذين يسرعون فى الكفر  إنهم لن يضروا الله شيا  يريد الله ألا يجعل لهم حظا فى الءاخرة  ولهم عذاب عظيم', NULL, 73, 'local:hafs-text.json'),
  ('hafs-3-177', 'hafs', 3, 177, 'إِنَّ ٱلَّذِينَ ٱشْتَرَوُا۟ ٱلْكُفْرَ بِٱلْإِيمَٰنِ لَن يَضُرُّوا۟ ٱللَّهَ شَيْـًۭٔا وَلَهُمْ عَذَابٌ أَلِيمٌۭ', 'إن الذين اشتروا الكفر بالإيمن لن يضروا الله شيا ولهم عذاب أليم', NULL, 73, 'local:hafs-text.json'),
  ('hafs-3-178', 'hafs', 3, 178, 'وَلَا يَحْسَبَنَّ ٱلَّذِينَ كَفَرُوٓا۟ أَنَّمَا نُمْلِى لَهُمْ خَيْرٌۭ لِّأَنفُسِهِمْ ۚ إِنَّمَا نُمْلِى لَهُمْ لِيَزْدَادُوٓا۟ إِثْمًۭا ۚ وَلَهُمْ عَذَابٌۭ مُّهِينٌۭ', 'ولا يحسبن الذين كفروا أنما نملى لهم خير لأنفسهم  إنما نملى لهم ليزدادوا إثما  ولهم عذاب مهين', NULL, 73, 'local:hafs-text.json'),
  ('hafs-3-179', 'hafs', 3, 179, 'مَّا كَانَ ٱللَّهُ لِيَذَرَ ٱلْمُؤْمِنِينَ عَلَىٰ مَآ أَنتُمْ عَلَيْهِ حَتَّىٰ يَمِيزَ ٱلْخَبِيثَ مِنَ ٱلطَّيِّبِ ۗ وَمَا كَانَ ٱللَّهُ لِيُطْلِعَكُمْ عَلَى ٱلْغَيْبِ وَلَٰكِنَّ ٱللَّهَ يَجْتَبِى مِن رُّسُلِهِۦ مَن يَشَآءُ ۖ فَـَٔامِنُوا۟ بِٱللَّهِ وَرُسُلِهِۦ ۚ وَإِن تُؤْمِنُوا۟ وَتَتَّقُوا۟ فَلَكُمْ أَجْرٌ عَظِيمٌۭ', 'ما كان الله ليذر المؤمنين على ما أنتم عليه حتى يميز الخبيث من الطيب  وما كان الله ليطلعكم على الغيب ولكن الله يجتبى من رسله من يشاء  فامنوا بالله ورسله  وإن تؤمنوا وتتقوا فلكم أجر عظيم', NULL, 73, 'local:hafs-text.json'),
  ('hafs-3-180', 'hafs', 3, 180, 'وَلَا يَحْسَبَنَّ ٱلَّذِينَ يَبْخَلُونَ بِمَآ ءَاتَىٰهُمُ ٱللَّهُ مِن فَضْلِهِۦ هُوَ خَيْرًۭا لَّهُم ۖ بَلْ هُوَ شَرٌّۭ لَّهُمْ ۖ سَيُطَوَّقُونَ مَا بَخِلُوا۟ بِهِۦ يَوْمَ ٱلْقِيَٰمَةِ ۗ وَلِلَّهِ مِيرَٰثُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ ۗ وَٱللَّهُ بِمَا تَعْمَلُونَ خَبِيرٌۭ', 'ولا يحسبن الذين يبخلون بما ءاتىهم الله من فضله هو خيرا لهم  بل هو شر لهم  سيطوقون ما بخلوا به يوم القيمة  ولله ميرث السموت والأرض  والله بما تعملون خبير', NULL, 73, 'local:hafs-text.json'),
  ('hafs-3-181', 'hafs', 3, 181, 'لَّقَدْ سَمِعَ ٱللَّهُ قَوْلَ ٱلَّذِينَ قَالُوٓا۟ إِنَّ ٱللَّهَ فَقِيرٌۭ وَنَحْنُ أَغْنِيَآءُ ۘ سَنَكْتُبُ مَا قَالُوا۟ وَقَتْلَهُمُ ٱلْأَنۢبِيَآءَ بِغَيْرِ حَقٍّۢ وَنَقُولُ ذُوقُوا۟ عَذَابَ ٱلْحَرِيقِ', 'لقد سمع الله قول الذين قالوا إن الله فقير ونحن أغنياء  سنكتب ما قالوا وقتلهم الأنبياء بغير حق ونقول ذوقوا عذاب الحريق', NULL, 74, 'local:hafs-text.json'),
  ('hafs-3-182', 'hafs', 3, 182, 'ذَٰلِكَ بِمَا قَدَّمَتْ أَيْدِيكُمْ وَأَنَّ ٱللَّهَ لَيْسَ بِظَلَّامٍۢ لِّلْعَبِيدِ', 'ذلك بما قدمت أيديكم وأن الله ليس بظلام للعبيد', NULL, 74, 'local:hafs-text.json'),
  ('hafs-3-183', 'hafs', 3, 183, 'ٱلَّذِينَ قَالُوٓا۟ إِنَّ ٱللَّهَ عَهِدَ إِلَيْنَآ أَلَّا نُؤْمِنَ لِرَسُولٍ حَتَّىٰ يَأْتِيَنَا بِقُرْبَانٍۢ تَأْكُلُهُ ٱلنَّارُ ۗ قُلْ قَدْ جَآءَكُمْ رُسُلٌۭ مِّن قَبْلِى بِٱلْبَيِّنَٰتِ وَبِٱلَّذِى قُلْتُمْ فَلِمَ قَتَلْتُمُوهُمْ إِن كُنتُمْ صَٰدِقِينَ', 'الذين قالوا إن الله عهد إلينا ألا نؤمن لرسول حتى يأتينا بقربان تأكله النار  قل قد جاءكم رسل من قبلى بالبينت وبالذى قلتم فلم قتلتموهم إن كنتم صدقين', NULL, 74, 'local:hafs-text.json'),
  ('hafs-3-184', 'hafs', 3, 184, 'فَإِن كَذَّبُوكَ فَقَدْ كُذِّبَ رُسُلٌۭ مِّن قَبْلِكَ جَآءُو بِٱلْبَيِّنَٰتِ وَٱلزُّبُرِ وَٱلْكِتَٰبِ ٱلْمُنِيرِ', 'فإن كذبوك فقد كذب رسل من قبلك جاءو بالبينت والزبر والكتب المنير', NULL, 74, 'local:hafs-text.json'),
  ('hafs-3-185', 'hafs', 3, 185, 'كُلُّ نَفْسٍۢ ذَآئِقَةُ ٱلْمَوْتِ ۗ وَإِنَّمَا تُوَفَّوْنَ أُجُورَكُمْ يَوْمَ ٱلْقِيَٰمَةِ ۖ فَمَن زُحْزِحَ عَنِ ٱلنَّارِ وَأُدْخِلَ ٱلْجَنَّةَ فَقَدْ فَازَ ۗ وَمَا ٱلْحَيَوٰةُ ٱلدُّنْيَآ إِلَّا مَتَٰعُ ٱلْغُرُورِ', 'كل نفس ذائقة الموت  وإنما توفون أجوركم يوم القيمة  فمن زحزح عن النار وأدخل الجنة فقد فاز  وما الحيوة الدنيا إلا متع الغرور', NULL, 74, 'local:hafs-text.json'),
  ('hafs-3-186', 'hafs', 3, 186, '۞ لَتُبْلَوُنَّ فِىٓ أَمْوَٰلِكُمْ وَأَنفُسِكُمْ وَلَتَسْمَعُنَّ مِنَ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَٰبَ مِن قَبْلِكُمْ وَمِنَ ٱلَّذِينَ أَشْرَكُوٓا۟ أَذًۭى كَثِيرًۭا ۚ وَإِن تَصْبِرُوا۟ وَتَتَّقُوا۟ فَإِنَّ ذَٰلِكَ مِنْ عَزْمِ ٱلْأُمُورِ', 'لتبلون فى أمولكم وأنفسكم ولتسمعن من الذين أوتوا الكتب من قبلكم ومن الذين أشركوا أذى كثيرا  وإن تصبروا وتتقوا فإن ذلك من عزم الأمور', NULL, 74, 'local:hafs-text.json'),
  ('hafs-3-187', 'hafs', 3, 187, 'وَإِذْ أَخَذَ ٱللَّهُ مِيثَٰقَ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَٰبَ لَتُبَيِّنُنَّهُۥ لِلنَّاسِ وَلَا تَكْتُمُونَهُۥ فَنَبَذُوهُ وَرَآءَ ظُهُورِهِمْ وَٱشْتَرَوْا۟ بِهِۦ ثَمَنًۭا قَلِيلًۭا ۖ فَبِئْسَ مَا يَشْتَرُونَ', 'وإذ أخذ الله ميثق الذين أوتوا الكتب لتبيننه للناس ولا تكتمونه فنبذوه وراء ظهورهم واشتروا به ثمنا قليلا  فبئس ما يشترون', NULL, 75, 'local:hafs-text.json'),
  ('hafs-3-188', 'hafs', 3, 188, 'لَا تَحْسَبَنَّ ٱلَّذِينَ يَفْرَحُونَ بِمَآ أَتَوا۟ وَّيُحِبُّونَ أَن يُحْمَدُوا۟ بِمَا لَمْ يَفْعَلُوا۟ فَلَا تَحْسَبَنَّهُم بِمَفَازَةٍۢ مِّنَ ٱلْعَذَابِ ۖ وَلَهُمْ عَذَابٌ أَلِيمٌۭ', 'لا تحسبن الذين يفرحون بما أتوا ويحبون أن يحمدوا بما لم يفعلوا فلا تحسبنهم بمفازة من العذاب  ولهم عذاب أليم', NULL, 75, 'local:hafs-text.json'),
  ('hafs-3-189', 'hafs', 3, 189, 'وَلِلَّهِ مُلْكُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ ۗ وَٱللَّهُ عَلَىٰ كُلِّ شَىْءٍۢ قَدِيرٌ', 'ولله ملك السموت والأرض  والله على كل شىء قدير', NULL, 75, 'local:hafs-text.json'),
  ('hafs-3-190', 'hafs', 3, 190, 'إِنَّ فِى خَلْقِ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَٱخْتِلَٰفِ ٱلَّيْلِ وَٱلنَّهَارِ لَءَايَٰتٍۢ لِّأُو۟لِى ٱلْأَلْبَٰبِ', 'إن فى خلق السموت والأرض واختلف اليل والنهار لءايت لأولى الألبب', NULL, 75, 'local:hafs-text.json'),
  ('hafs-3-191', 'hafs', 3, 191, 'ٱلَّذِينَ يَذْكُرُونَ ٱللَّهَ قِيَٰمًۭا وَقُعُودًۭا وَعَلَىٰ جُنُوبِهِمْ وَيَتَفَكَّرُونَ فِى خَلْقِ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ رَبَّنَا مَا خَلَقْتَ هَٰذَا بَٰطِلًۭا سُبْحَٰنَكَ فَقِنَا عَذَابَ ٱلنَّارِ', 'الذين يذكرون الله قيما وقعودا وعلى جنوبهم ويتفكرون فى خلق السموت والأرض ربنا ما خلقت هذا بطلا سبحنك فقنا عذاب النار', NULL, 75, 'local:hafs-text.json'),
  ('hafs-3-192', 'hafs', 3, 192, 'رَبَّنَآ إِنَّكَ مَن تُدْخِلِ ٱلنَّارَ فَقَدْ أَخْزَيْتَهُۥ ۖ وَمَا لِلظَّٰلِمِينَ مِنْ أَنصَارٍۢ', 'ربنا إنك من تدخل النار فقد أخزيته  وما للظلمين من أنصار', NULL, 75, 'local:hafs-text.json'),
  ('hafs-3-193', 'hafs', 3, 193, 'رَّبَّنَآ إِنَّنَا سَمِعْنَا مُنَادِيًۭا يُنَادِى لِلْإِيمَٰنِ أَنْ ءَامِنُوا۟ بِرَبِّكُمْ فَـَٔامَنَّا ۚ رَبَّنَا فَٱغْفِرْ لَنَا ذُنُوبَنَا وَكَفِّرْ عَنَّا سَيِّـَٔاتِنَا وَتَوَفَّنَا مَعَ ٱلْأَبْرَارِ', 'ربنا إننا سمعنا مناديا ينادى للإيمن أن ءامنوا بربكم فامنا  ربنا فاغفر لنا ذنوبنا وكفر عنا سياتنا وتوفنا مع الأبرار', NULL, 75, 'local:hafs-text.json'),
  ('hafs-3-194', 'hafs', 3, 194, 'رَبَّنَا وَءَاتِنَا مَا وَعَدتَّنَا عَلَىٰ رُسُلِكَ وَلَا تُخْزِنَا يَوْمَ ٱلْقِيَٰمَةِ ۗ إِنَّكَ لَا تُخْلِفُ ٱلْمِيعَادَ', 'ربنا وءاتنا ما وعدتنا على رسلك ولا تخزنا يوم القيمة  إنك لا تخلف الميعاد', NULL, 75, 'local:hafs-text.json'),
  ('hafs-3-195', 'hafs', 3, 195, 'فَٱسْتَجَابَ لَهُمْ رَبُّهُمْ أَنِّى لَآ أُضِيعُ عَمَلَ عَٰمِلٍۢ مِّنكُم مِّن ذَكَرٍ أَوْ أُنثَىٰ ۖ بَعْضُكُم مِّنۢ بَعْضٍۢ ۖ فَٱلَّذِينَ هَاجَرُوا۟ وَأُخْرِجُوا۟ مِن دِيَٰرِهِمْ وَأُوذُوا۟ فِى سَبِيلِى وَقَٰتَلُوا۟ وَقُتِلُوا۟ لَأُكَفِّرَنَّ عَنْهُمْ سَيِّـَٔاتِهِمْ وَلَأُدْخِلَنَّهُمْ جَنَّٰتٍۢ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ ثَوَابًۭا مِّنْ عِندِ ٱللَّهِ ۗ وَٱللَّهُ عِندَهُۥ حُسْنُ ٱلثَّوَابِ', 'فاستجاب لهم ربهم أنى لا أضيع عمل عمل منكم من ذكر أو أنثى  بعضكم من بعض  فالذين هاجروا وأخرجوا من ديرهم وأوذوا فى سبيلى وقتلوا وقتلوا لأكفرن عنهم سياتهم ولأدخلنهم جنت تجرى من تحتها الأنهر ثوابا من عند الله  والله عنده حسن الثواب', NULL, 76, 'local:hafs-text.json'),
  ('hafs-3-196', 'hafs', 3, 196, 'لَا يَغُرَّنَّكَ تَقَلُّبُ ٱلَّذِينَ كَفَرُوا۟ فِى ٱلْبِلَٰدِ', 'لا يغرنك تقلب الذين كفروا فى البلد', NULL, 76, 'local:hafs-text.json'),
  ('hafs-3-197', 'hafs', 3, 197, 'مَتَٰعٌۭ قَلِيلٌۭ ثُمَّ مَأْوَىٰهُمْ جَهَنَّمُ ۚ وَبِئْسَ ٱلْمِهَادُ', 'متع قليل ثم مأوىهم جهنم  وبئس المهاد', NULL, 76, 'local:hafs-text.json'),
  ('hafs-3-198', 'hafs', 3, 198, 'لَٰكِنِ ٱلَّذِينَ ٱتَّقَوْا۟ رَبَّهُمْ لَهُمْ جَنَّٰتٌۭ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ خَٰلِدِينَ فِيهَا نُزُلًۭا مِّنْ عِندِ ٱللَّهِ ۗ وَمَا عِندَ ٱللَّهِ خَيْرٌۭ لِّلْأَبْرَارِ', 'لكن الذين اتقوا ربهم لهم جنت تجرى من تحتها الأنهر خلدين فيها نزلا من عند الله  وما عند الله خير للأبرار', NULL, 76, 'local:hafs-text.json'),
  ('hafs-3-199', 'hafs', 3, 199, 'وَإِنَّ مِنْ أَهْلِ ٱلْكِتَٰبِ لَمَن يُؤْمِنُ بِٱللَّهِ وَمَآ أُنزِلَ إِلَيْكُمْ وَمَآ أُنزِلَ إِلَيْهِمْ خَٰشِعِينَ لِلَّهِ لَا يَشْتَرُونَ بِـَٔايَٰتِ ٱللَّهِ ثَمَنًۭا قَلِيلًا ۗ أُو۟لَٰٓئِكَ لَهُمْ أَجْرُهُمْ عِندَ رَبِّهِمْ ۗ إِنَّ ٱللَّهَ سَرِيعُ ٱلْحِسَابِ', 'وإن من أهل الكتب لمن يؤمن بالله وما أنزل إليكم وما أنزل إليهم خشعين لله لا يشترون بايت الله ثمنا قليلا  أولئك لهم أجرهم عند ربهم  إن الله سريع الحساب', NULL, 76, 'local:hafs-text.json'),
  ('hafs-3-200', 'hafs', 3, 200, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱصْبِرُوا۟ وَصَابِرُوا۟ وَرَابِطُوا۟ وَٱتَّقُوا۟ ٱللَّهَ لَعَلَّكُمْ تُفْلِحُونَ', 'يأيها الذين ءامنوا اصبروا وصابروا ورابطوا واتقوا الله لعلكم تفلحون', NULL, 76, 'local:hafs-text.json'),
  ('hafs-4-1', 'hafs', 4, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ يَٰٓأَيُّهَا ٱلنَّاسُ ٱتَّقُوا۟ رَبَّكُمُ ٱلَّذِى خَلَقَكُم مِّن نَّفْسٍۢ وَٰحِدَةٍۢ وَخَلَقَ مِنْهَا زَوْجَهَا وَبَثَّ مِنْهُمَا رِجَالًۭا كَثِيرًۭا وَنِسَآءًۭ ۚ وَٱتَّقُوا۟ ٱللَّهَ ٱلَّذِى تَسَآءَلُونَ بِهِۦ وَٱلْأَرْحَامَ ۚ إِنَّ ٱللَّهَ كَانَ عَلَيْكُمْ رَقِيبًۭا', 'بسم الله الرحمن الرحيم يأيها الناس اتقوا ربكم الذى خلقكم من نفس وحدة وخلق منها زوجها وبث منهما رجالا كثيرا ونساء  واتقوا الله الذى تساءلون به والأرحام  إن الله كان عليكم رقيبا', NULL, 77, 'local:hafs-text.json'),
  ('hafs-4-2', 'hafs', 4, 2, 'وَءَاتُوا۟ ٱلْيَتَٰمَىٰٓ أَمْوَٰلَهُمْ ۖ وَلَا تَتَبَدَّلُوا۟ ٱلْخَبِيثَ بِٱلطَّيِّبِ ۖ وَلَا تَأْكُلُوٓا۟ أَمْوَٰلَهُمْ إِلَىٰٓ أَمْوَٰلِكُمْ ۚ إِنَّهُۥ كَانَ حُوبًۭا كَبِيرًۭا', 'وءاتوا اليتمى أمولهم  ولا تتبدلوا الخبيث بالطيب  ولا تأكلوا أمولهم إلى أمولكم  إنه كان حوبا كبيرا', NULL, 77, 'local:hafs-text.json'),
  ('hafs-4-3', 'hafs', 4, 3, 'وَإِنْ خِفْتُمْ أَلَّا تُقْسِطُوا۟ فِى ٱلْيَتَٰمَىٰ فَٱنكِحُوا۟ مَا طَابَ لَكُم مِّنَ ٱلنِّسَآءِ مَثْنَىٰ وَثُلَٰثَ وَرُبَٰعَ ۖ فَإِنْ خِفْتُمْ أَلَّا تَعْدِلُوا۟ فَوَٰحِدَةً أَوْ مَا مَلَكَتْ أَيْمَٰنُكُمْ ۚ ذَٰلِكَ أَدْنَىٰٓ أَلَّا تَعُولُوا۟', 'وإن خفتم ألا تقسطوا فى اليتمى فانكحوا ما طاب لكم من النساء مثنى وثلث وربع  فإن خفتم ألا تعدلوا فوحدة أو ما ملكت أيمنكم  ذلك أدنى ألا تعولوا', NULL, 77, 'local:hafs-text.json'),
  ('hafs-4-4', 'hafs', 4, 4, 'وَءَاتُوا۟ ٱلنِّسَآءَ صَدُقَٰتِهِنَّ نِحْلَةًۭ ۚ فَإِن طِبْنَ لَكُمْ عَن شَىْءٍۢ مِّنْهُ نَفْسًۭا فَكُلُوهُ هَنِيٓـًۭٔا مَّرِيٓـًۭٔا', 'وءاتوا النساء صدقتهن نحلة  فإن طبن لكم عن شىء منه نفسا فكلوه هنيا مريا', NULL, 77, 'local:hafs-text.json'),
  ('hafs-4-5', 'hafs', 4, 5, 'وَلَا تُؤْتُوا۟ ٱلسُّفَهَآءَ أَمْوَٰلَكُمُ ٱلَّتِى جَعَلَ ٱللَّهُ لَكُمْ قِيَٰمًۭا وَٱرْزُقُوهُمْ فِيهَا وَٱكْسُوهُمْ وَقُولُوا۟ لَهُمْ قَوْلًۭا مَّعْرُوفًۭا', 'ولا تؤتوا السفهاء أمولكم التى جعل الله لكم قيما وارزقوهم فيها واكسوهم وقولوا لهم قولا معروفا', NULL, 77, 'local:hafs-text.json'),
  ('hafs-4-6', 'hafs', 4, 6, 'وَٱبْتَلُوا۟ ٱلْيَتَٰمَىٰ حَتَّىٰٓ إِذَا بَلَغُوا۟ ٱلنِّكَاحَ فَإِنْ ءَانَسْتُم مِّنْهُمْ رُشْدًۭا فَٱدْفَعُوٓا۟ إِلَيْهِمْ أَمْوَٰلَهُمْ ۖ وَلَا تَأْكُلُوهَآ إِسْرَافًۭا وَبِدَارًا أَن يَكْبَرُوا۟ ۚ وَمَن كَانَ غَنِيًّۭا فَلْيَسْتَعْفِفْ ۖ وَمَن كَانَ فَقِيرًۭا فَلْيَأْكُلْ بِٱلْمَعْرُوفِ ۚ فَإِذَا دَفَعْتُمْ إِلَيْهِمْ أَمْوَٰلَهُمْ فَأَشْهِدُوا۟ عَلَيْهِمْ ۚ وَكَفَىٰ بِٱللَّهِ حَسِيبًۭا', 'وابتلوا اليتمى حتى إذا بلغوا النكاح فإن ءانستم منهم رشدا فادفعوا إليهم أمولهم  ولا تأكلوها إسرافا وبدارا أن يكبروا  ومن كان غنيا فليستعفف  ومن كان فقيرا فليأكل بالمعروف  فإذا دفعتم إليهم أمولهم فأشهدوا عليهم  وكفى بالله حسيبا', NULL, 77, 'local:hafs-text.json'),
  ('hafs-4-7', 'hafs', 4, 7, 'لِّلرِّجَالِ نَصِيبٌۭ مِّمَّا تَرَكَ ٱلْوَٰلِدَانِ وَٱلْأَقْرَبُونَ وَلِلنِّسَآءِ نَصِيبٌۭ مِّمَّا تَرَكَ ٱلْوَٰلِدَانِ وَٱلْأَقْرَبُونَ مِمَّا قَلَّ مِنْهُ أَوْ كَثُرَ ۚ نَصِيبًۭا مَّفْرُوضًۭا', 'للرجال نصيب مما ترك الولدان والأقربون وللنساء نصيب مما ترك الولدان والأقربون مما قل منه أو كثر  نصيبا مفروضا', NULL, 78, 'local:hafs-text.json'),
  ('hafs-4-8', 'hafs', 4, 8, 'وَإِذَا حَضَرَ ٱلْقِسْمَةَ أُو۟لُوا۟ ٱلْقُرْبَىٰ وَٱلْيَتَٰمَىٰ وَٱلْمَسَٰكِينُ فَٱرْزُقُوهُم مِّنْهُ وَقُولُوا۟ لَهُمْ قَوْلًۭا مَّعْرُوفًۭا', 'وإذا حضر القسمة أولوا القربى واليتمى والمسكين فارزقوهم منه وقولوا لهم قولا معروفا', NULL, 78, 'local:hafs-text.json'),
  ('hafs-4-9', 'hafs', 4, 9, 'وَلْيَخْشَ ٱلَّذِينَ لَوْ تَرَكُوا۟ مِنْ خَلْفِهِمْ ذُرِّيَّةًۭ ضِعَٰفًا خَافُوا۟ عَلَيْهِمْ فَلْيَتَّقُوا۟ ٱللَّهَ وَلْيَقُولُوا۟ قَوْلًۭا سَدِيدًا', 'وليخش الذين لو تركوا من خلفهم ذرية ضعفا خافوا عليهم فليتقوا الله وليقولوا قولا سديدا', NULL, 78, 'local:hafs-text.json'),
  ('hafs-4-10', 'hafs', 4, 10, 'إِنَّ ٱلَّذِينَ يَأْكُلُونَ أَمْوَٰلَ ٱلْيَتَٰمَىٰ ظُلْمًا إِنَّمَا يَأْكُلُونَ فِى بُطُونِهِمْ نَارًۭا ۖ وَسَيَصْلَوْنَ سَعِيرًۭا', 'إن الذين يأكلون أمول اليتمى ظلما إنما يأكلون فى بطونهم نارا  وسيصلون سعيرا', NULL, 78, 'local:hafs-text.json'),
  ('hafs-4-11', 'hafs', 4, 11, 'يُوصِيكُمُ ٱللَّهُ فِىٓ أَوْلَٰدِكُمْ ۖ لِلذَّكَرِ مِثْلُ حَظِّ ٱلْأُنثَيَيْنِ ۚ فَإِن كُنَّ نِسَآءًۭ فَوْقَ ٱثْنَتَيْنِ فَلَهُنَّ ثُلُثَا مَا تَرَكَ ۖ وَإِن كَانَتْ وَٰحِدَةًۭ فَلَهَا ٱلنِّصْفُ ۚ وَلِأَبَوَيْهِ لِكُلِّ وَٰحِدٍۢ مِّنْهُمَا ٱلسُّدُسُ مِمَّا تَرَكَ إِن كَانَ لَهُۥ وَلَدٌۭ ۚ فَإِن لَّمْ يَكُن لَّهُۥ وَلَدٌۭ وَوَرِثَهُۥٓ أَبَوَاهُ فَلِأُمِّهِ ٱلثُّلُثُ ۚ فَإِن كَانَ لَهُۥٓ إِخْوَةٌۭ فَلِأُمِّهِ ٱلسُّدُسُ ۚ مِنۢ بَعْدِ وَصِيَّةٍۢ يُوصِى بِهَآ أَوْ دَيْنٍ ۗ ءَابَآؤُكُمْ وَأَبْنَآؤُكُمْ لَا تَدْرُونَ أَيُّهُمْ أَقْرَبُ لَكُمْ نَفْعًۭا ۚ فَرِيضَةًۭ مِّنَ ٱللَّهِ ۗ إِنَّ ٱللَّهَ كَانَ عَلِيمًا حَكِيمًۭا', 'يوصيكم الله فى أولدكم  للذكر مثل حظ الأنثيين  فإن كن نساء فوق اثنتين فلهن ثلثا ما ترك  وإن كانت وحدة فلها النصف  ولأبويه لكل وحد منهما السدس مما ترك إن كان له ولد  فإن لم يكن له ولد وورثه أبواه فلأمه الثلث  فإن كان له إخوة فلأمه السدس  من بعد وصية يوصى بها أو دين  ءاباؤكم وأبناؤكم لا تدرون أيهم أقرب لكم نفعا  فريضة من الله  إن الله كان عليما حكيما', NULL, 78, 'local:hafs-text.json'),
  ('hafs-4-12', 'hafs', 4, 12, '۞ وَلَكُمْ نِصْفُ مَا تَرَكَ أَزْوَٰجُكُمْ إِن لَّمْ يَكُن لَّهُنَّ وَلَدٌۭ ۚ فَإِن كَانَ لَهُنَّ وَلَدٌۭ فَلَكُمُ ٱلرُّبُعُ مِمَّا تَرَكْنَ ۚ مِنۢ بَعْدِ وَصِيَّةٍۢ يُوصِينَ بِهَآ أَوْ دَيْنٍۢ ۚ وَلَهُنَّ ٱلرُّبُعُ مِمَّا تَرَكْتُمْ إِن لَّمْ يَكُن لَّكُمْ وَلَدٌۭ ۚ فَإِن كَانَ لَكُمْ وَلَدٌۭ فَلَهُنَّ ٱلثُّمُنُ مِمَّا تَرَكْتُم ۚ مِّنۢ بَعْدِ وَصِيَّةٍۢ تُوصُونَ بِهَآ أَوْ دَيْنٍۢ ۗ وَإِن كَانَ رَجُلٌۭ يُورَثُ كَلَٰلَةً أَوِ ٱمْرَأَةٌۭ وَلَهُۥٓ أَخٌ أَوْ أُخْتٌۭ فَلِكُلِّ وَٰحِدٍۢ مِّنْهُمَا ٱلسُّدُسُ ۚ فَإِن كَانُوٓا۟ أَكْثَرَ مِن ذَٰلِكَ فَهُمْ شُرَكَآءُ فِى ٱلثُّلُثِ ۚ مِنۢ بَعْدِ وَصِيَّةٍۢ يُوصَىٰ بِهَآ أَوْ دَيْنٍ غَيْرَ مُضَآرٍّۢ ۚ وَصِيَّةًۭ مِّنَ ٱللَّهِ ۗ وَٱللَّهُ عَلِيمٌ حَلِيمٌۭ', 'ولكم نصف ما ترك أزوجكم إن لم يكن لهن ولد  فإن كان لهن ولد فلكم الربع مما تركن  من بعد وصية يوصين بها أو دين  ولهن الربع مما تركتم إن لم يكن لكم ولد  فإن كان لكم ولد فلهن الثمن مما تركتم  من بعد وصية توصون بها أو دين  وإن كان رجل يورث كللة أو امرأة وله أخ أو أخت فلكل وحد منهما السدس  فإن كانوا أكثر من ذلك فهم شركاء فى الثلث  من بعد وصية يوصى بها أو دين غير مضار  وصية من الله  والله عليم حليم', NULL, 79, 'local:hafs-text.json'),
  ('hafs-4-13', 'hafs', 4, 13, 'تِلْكَ حُدُودُ ٱللَّهِ ۚ وَمَن يُطِعِ ٱللَّهَ وَرَسُولَهُۥ يُدْخِلْهُ جَنَّٰتٍۢ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ خَٰلِدِينَ فِيهَا ۚ وَذَٰلِكَ ٱلْفَوْزُ ٱلْعَظِيمُ', 'تلك حدود الله  ومن يطع الله ورسوله يدخله جنت تجرى من تحتها الأنهر خلدين فيها  وذلك الفوز العظيم', NULL, 79, 'local:hafs-text.json'),
  ('hafs-4-14', 'hafs', 4, 14, 'وَمَن يَعْصِ ٱللَّهَ وَرَسُولَهُۥ وَيَتَعَدَّ حُدُودَهُۥ يُدْخِلْهُ نَارًا خَٰلِدًۭا فِيهَا وَلَهُۥ عَذَابٌۭ مُّهِينٌۭ', 'ومن يعص الله ورسوله ويتعد حدوده يدخله نارا خلدا فيها وله عذاب مهين', NULL, 79, 'local:hafs-text.json'),
  ('hafs-4-15', 'hafs', 4, 15, 'وَٱلَّٰتِى يَأْتِينَ ٱلْفَٰحِشَةَ مِن نِّسَآئِكُمْ فَٱسْتَشْهِدُوا۟ عَلَيْهِنَّ أَرْبَعَةًۭ مِّنكُمْ ۖ فَإِن شَهِدُوا۟ فَأَمْسِكُوهُنَّ فِى ٱلْبُيُوتِ حَتَّىٰ يَتَوَفَّىٰهُنَّ ٱلْمَوْتُ أَوْ يَجْعَلَ ٱللَّهُ لَهُنَّ سَبِيلًۭا', 'والتى يأتين الفحشة من نسائكم فاستشهدوا عليهن أربعة منكم  فإن شهدوا فأمسكوهن فى البيوت حتى يتوفىهن الموت أو يجعل الله لهن سبيلا', NULL, 80, 'local:hafs-text.json'),
  ('hafs-4-16', 'hafs', 4, 16, 'وَٱلَّذَانِ يَأْتِيَٰنِهَا مِنكُمْ فَـَٔاذُوهُمَا ۖ فَإِن تَابَا وَأَصْلَحَا فَأَعْرِضُوا۟ عَنْهُمَآ ۗ إِنَّ ٱللَّهَ كَانَ تَوَّابًۭا رَّحِيمًا', 'والذان يأتينها منكم فاذوهما  فإن تابا وأصلحا فأعرضوا عنهما  إن الله كان توابا رحيما', NULL, 80, 'local:hafs-text.json'),
  ('hafs-4-17', 'hafs', 4, 17, 'إِنَّمَا ٱلتَّوْبَةُ عَلَى ٱللَّهِ لِلَّذِينَ يَعْمَلُونَ ٱلسُّوٓءَ بِجَهَٰلَةٍۢ ثُمَّ يَتُوبُونَ مِن قَرِيبٍۢ فَأُو۟لَٰٓئِكَ يَتُوبُ ٱللَّهُ عَلَيْهِمْ ۗ وَكَانَ ٱللَّهُ عَلِيمًا حَكِيمًۭا', 'إنما التوبة على الله للذين يعملون السوء بجهلة ثم يتوبون من قريب فأولئك يتوب الله عليهم  وكان الله عليما حكيما', NULL, 80, 'local:hafs-text.json'),
  ('hafs-4-18', 'hafs', 4, 18, 'وَلَيْسَتِ ٱلتَّوْبَةُ لِلَّذِينَ يَعْمَلُونَ ٱلسَّيِّـَٔاتِ حَتَّىٰٓ إِذَا حَضَرَ أَحَدَهُمُ ٱلْمَوْتُ قَالَ إِنِّى تُبْتُ ٱلْـَٰٔنَ وَلَا ٱلَّذِينَ يَمُوتُونَ وَهُمْ كُفَّارٌ ۚ أُو۟لَٰٓئِكَ أَعْتَدْنَا لَهُمْ عَذَابًا أَلِيمًۭا', 'وليست التوبة للذين يعملون السيات حتى إذا حضر أحدهم الموت قال إنى تبت الن ولا الذين يموتون وهم كفار  أولئك أعتدنا لهم عذابا أليما', NULL, 80, 'local:hafs-text.json'),
  ('hafs-4-19', 'hafs', 4, 19, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا يَحِلُّ لَكُمْ أَن تَرِثُوا۟ ٱلنِّسَآءَ كَرْهًۭا ۖ وَلَا تَعْضُلُوهُنَّ لِتَذْهَبُوا۟ بِبَعْضِ مَآ ءَاتَيْتُمُوهُنَّ إِلَّآ أَن يَأْتِينَ بِفَٰحِشَةٍۢ مُّبَيِّنَةٍۢ ۚ وَعَاشِرُوهُنَّ بِٱلْمَعْرُوفِ ۚ فَإِن كَرِهْتُمُوهُنَّ فَعَسَىٰٓ أَن تَكْرَهُوا۟ شَيْـًۭٔا وَيَجْعَلَ ٱللَّهُ فِيهِ خَيْرًۭا كَثِيرًۭا', 'يأيها الذين ءامنوا لا يحل لكم أن ترثوا النساء كرها  ولا تعضلوهن لتذهبوا ببعض ما ءاتيتموهن إلا أن يأتين بفحشة مبينة  وعاشروهن بالمعروف  فإن كرهتموهن فعسى أن تكرهوا شيا ويجعل الله فيه خيرا كثيرا', NULL, 80, 'local:hafs-text.json'),
  ('hafs-4-20', 'hafs', 4, 20, 'وَإِنْ أَرَدتُّمُ ٱسْتِبْدَالَ زَوْجٍۢ مَّكَانَ زَوْجٍۢ وَءَاتَيْتُمْ إِحْدَىٰهُنَّ قِنطَارًۭا فَلَا تَأْخُذُوا۟ مِنْهُ شَيْـًٔا ۚ أَتَأْخُذُونَهُۥ بُهْتَٰنًۭا وَإِثْمًۭا مُّبِينًۭا', 'وإن أردتم استبدال زوج مكان زوج وءاتيتم إحدىهن قنطارا فلا تأخذوا منه شيا  أتأخذونه بهتنا وإثما مبينا', NULL, 81, 'local:hafs-text.json'),
  ('hafs-4-21', 'hafs', 4, 21, 'وَكَيْفَ تَأْخُذُونَهُۥ وَقَدْ أَفْضَىٰ بَعْضُكُمْ إِلَىٰ بَعْضٍۢ وَأَخَذْنَ مِنكُم مِّيثَٰقًا غَلِيظًۭا', 'وكيف تأخذونه وقد أفضى بعضكم إلى بعض وأخذن منكم ميثقا غليظا', NULL, 81, 'local:hafs-text.json'),
  ('hafs-4-22', 'hafs', 4, 22, 'وَلَا تَنكِحُوا۟ مَا نَكَحَ ءَابَآؤُكُم مِّنَ ٱلنِّسَآءِ إِلَّا مَا قَدْ سَلَفَ ۚ إِنَّهُۥ كَانَ فَٰحِشَةًۭ وَمَقْتًۭا وَسَآءَ سَبِيلًا', 'ولا تنكحوا ما نكح ءاباؤكم من النساء إلا ما قد سلف  إنه كان فحشة ومقتا وساء سبيلا', NULL, 81, 'local:hafs-text.json'),
  ('hafs-4-23', 'hafs', 4, 23, 'حُرِّمَتْ عَلَيْكُمْ أُمَّهَٰتُكُمْ وَبَنَاتُكُمْ وَأَخَوَٰتُكُمْ وَعَمَّٰتُكُمْ وَخَٰلَٰتُكُمْ وَبَنَاتُ ٱلْأَخِ وَبَنَاتُ ٱلْأُخْتِ وَأُمَّهَٰتُكُمُ ٱلَّٰتِىٓ أَرْضَعْنَكُمْ وَأَخَوَٰتُكُم مِّنَ ٱلرَّضَٰعَةِ وَأُمَّهَٰتُ نِسَآئِكُمْ وَرَبَٰٓئِبُكُمُ ٱلَّٰتِى فِى حُجُورِكُم مِّن نِّسَآئِكُمُ ٱلَّٰتِى دَخَلْتُم بِهِنَّ فَإِن لَّمْ تَكُونُوا۟ دَخَلْتُم بِهِنَّ فَلَا جُنَاحَ عَلَيْكُمْ وَحَلَٰٓئِلُ أَبْنَآئِكُمُ ٱلَّذِينَ مِنْ أَصْلَٰبِكُمْ وَأَن تَجْمَعُوا۟ بَيْنَ ٱلْأُخْتَيْنِ إِلَّا مَا قَدْ سَلَفَ ۗ إِنَّ ٱللَّهَ كَانَ غَفُورًۭا رَّحِيمًۭا', 'حرمت عليكم أمهتكم وبناتكم وأخوتكم وعمتكم وخلتكم وبنات الأخ وبنات الأخت وأمهتكم التى أرضعنكم وأخوتكم من الرضعة وأمهت نسائكم وربئبكم التى فى حجوركم من نسائكم التى دخلتم بهن فإن لم تكونوا دخلتم بهن فلا جناح عليكم وحلئل أبنائكم الذين من أصلبكم وأن تجمعوا بين الأختين إلا ما قد سلف  إن الله كان غفورا رحيما', NULL, 81, 'local:hafs-text.json'),
  ('hafs-4-24', 'hafs', 4, 24, '۞ وَٱلْمُحْصَنَٰتُ مِنَ ٱلنِّسَآءِ إِلَّا مَا مَلَكَتْ أَيْمَٰنُكُمْ ۖ كِتَٰبَ ٱللَّهِ عَلَيْكُمْ ۚ وَأُحِلَّ لَكُم مَّا وَرَآءَ ذَٰلِكُمْ أَن تَبْتَغُوا۟ بِأَمْوَٰلِكُم مُّحْصِنِينَ غَيْرَ مُسَٰفِحِينَ ۚ فَمَا ٱسْتَمْتَعْتُم بِهِۦ مِنْهُنَّ فَـَٔاتُوهُنَّ أُجُورَهُنَّ فَرِيضَةًۭ ۚ وَلَا جُنَاحَ عَلَيْكُمْ فِيمَا تَرَٰضَيْتُم بِهِۦ مِنۢ بَعْدِ ٱلْفَرِيضَةِ ۚ إِنَّ ٱللَّهَ كَانَ عَلِيمًا حَكِيمًۭا', 'والمحصنت من النساء إلا ما ملكت أيمنكم  كتب الله عليكم  وأحل لكم ما وراء ذلكم أن تبتغوا بأمولكم محصنين غير مسفحين  فما استمتعتم به منهن فاتوهن أجورهن فريضة  ولا جناح عليكم فيما ترضيتم به من بعد الفريضة  إن الله كان عليما حكيما', NULL, 82, 'local:hafs-text.json'),
  ('hafs-4-25', 'hafs', 4, 25, 'وَمَن لَّمْ يَسْتَطِعْ مِنكُمْ طَوْلًا أَن يَنكِحَ ٱلْمُحْصَنَٰتِ ٱلْمُؤْمِنَٰتِ فَمِن مَّا مَلَكَتْ أَيْمَٰنُكُم مِّن فَتَيَٰتِكُمُ ٱلْمُؤْمِنَٰتِ ۚ وَٱللَّهُ أَعْلَمُ بِإِيمَٰنِكُم ۚ بَعْضُكُم مِّنۢ بَعْضٍۢ ۚ فَٱنكِحُوهُنَّ بِإِذْنِ أَهْلِهِنَّ وَءَاتُوهُنَّ أُجُورَهُنَّ بِٱلْمَعْرُوفِ مُحْصَنَٰتٍ غَيْرَ مُسَٰفِحَٰتٍۢ وَلَا مُتَّخِذَٰتِ أَخْدَانٍۢ ۚ فَإِذَآ أُحْصِنَّ فَإِنْ أَتَيْنَ بِفَٰحِشَةٍۢ فَعَلَيْهِنَّ نِصْفُ مَا عَلَى ٱلْمُحْصَنَٰتِ مِنَ ٱلْعَذَابِ ۚ ذَٰلِكَ لِمَنْ خَشِىَ ٱلْعَنَتَ مِنكُمْ ۚ وَأَن تَصْبِرُوا۟ خَيْرٌۭ لَّكُمْ ۗ وَٱللَّهُ غَفُورٌۭ رَّحِيمٌۭ', 'ومن لم يستطع منكم طولا أن ينكح المحصنت المؤمنت فمن ما ملكت أيمنكم من فتيتكم المؤمنت  والله أعلم بإيمنكم  بعضكم من بعض  فانكحوهن بإذن أهلهن وءاتوهن أجورهن بالمعروف محصنت غير مسفحت ولا متخذت أخدان  فإذا أحصن فإن أتين بفحشة فعليهن نصف ما على المحصنت من العذاب  ذلك لمن خشى العنت منكم  وأن تصبروا خير لكم  والله غفور رحيم', NULL, 82, 'local:hafs-text.json'),
  ('hafs-4-26', 'hafs', 4, 26, 'يُرِيدُ ٱللَّهُ لِيُبَيِّنَ لَكُمْ وَيَهْدِيَكُمْ سُنَنَ ٱلَّذِينَ مِن قَبْلِكُمْ وَيَتُوبَ عَلَيْكُمْ ۗ وَٱللَّهُ عَلِيمٌ حَكِيمٌۭ', 'يريد الله ليبين لكم ويهديكم سنن الذين من قبلكم ويتوب عليكم  والله عليم حكيم', NULL, 82, 'local:hafs-text.json'),
  ('hafs-4-27', 'hafs', 4, 27, 'وَٱللَّهُ يُرِيدُ أَن يَتُوبَ عَلَيْكُمْ وَيُرِيدُ ٱلَّذِينَ يَتَّبِعُونَ ٱلشَّهَوَٰتِ أَن تَمِيلُوا۟ مَيْلًا عَظِيمًۭا', 'والله يريد أن يتوب عليكم ويريد الذين يتبعون الشهوت أن تميلوا ميلا عظيما', NULL, 83, 'local:hafs-text.json'),
  ('hafs-4-28', 'hafs', 4, 28, 'يُرِيدُ ٱللَّهُ أَن يُخَفِّفَ عَنكُمْ ۚ وَخُلِقَ ٱلْإِنسَٰنُ ضَعِيفًۭا', 'يريد الله أن يخفف عنكم  وخلق الإنسن ضعيفا', NULL, 83, 'local:hafs-text.json'),
  ('hafs-4-29', 'hafs', 4, 29, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَأْكُلُوٓا۟ أَمْوَٰلَكُم بَيْنَكُم بِٱلْبَٰطِلِ إِلَّآ أَن تَكُونَ تِجَٰرَةً عَن تَرَاضٍۢ مِّنكُمْ ۚ وَلَا تَقْتُلُوٓا۟ أَنفُسَكُمْ ۚ إِنَّ ٱللَّهَ كَانَ بِكُمْ رَحِيمًۭا', 'يأيها الذين ءامنوا لا تأكلوا أمولكم بينكم بالبطل إلا أن تكون تجرة عن تراض منكم  ولا تقتلوا أنفسكم  إن الله كان بكم رحيما', NULL, 83, 'local:hafs-text.json'),
  ('hafs-4-30', 'hafs', 4, 30, 'وَمَن يَفْعَلْ ذَٰلِكَ عُدْوَٰنًۭا وَظُلْمًۭا فَسَوْفَ نُصْلِيهِ نَارًۭا ۚ وَكَانَ ذَٰلِكَ عَلَى ٱللَّهِ يَسِيرًا', 'ومن يفعل ذلك عدونا وظلما فسوف نصليه نارا  وكان ذلك على الله يسيرا', NULL, 83, 'local:hafs-text.json'),
  ('hafs-4-31', 'hafs', 4, 31, 'إِن تَجْتَنِبُوا۟ كَبَآئِرَ مَا تُنْهَوْنَ عَنْهُ نُكَفِّرْ عَنكُمْ سَيِّـَٔاتِكُمْ وَنُدْخِلْكُم مُّدْخَلًۭا كَرِيمًۭا', 'إن تجتنبوا كبائر ما تنهون عنه نكفر عنكم سياتكم وندخلكم مدخلا كريما', NULL, 83, 'local:hafs-text.json'),
  ('hafs-4-32', 'hafs', 4, 32, 'وَلَا تَتَمَنَّوْا۟ مَا فَضَّلَ ٱللَّهُ بِهِۦ بَعْضَكُمْ عَلَىٰ بَعْضٍۢ ۚ لِّلرِّجَالِ نَصِيبٌۭ مِّمَّا ٱكْتَسَبُوا۟ ۖ وَلِلنِّسَآءِ نَصِيبٌۭ مِّمَّا ٱكْتَسَبْنَ ۚ وَسْـَٔلُوا۟ ٱللَّهَ مِن فَضْلِهِۦٓ ۗ إِنَّ ٱللَّهَ كَانَ بِكُلِّ شَىْءٍ عَلِيمًۭا', 'ولا تتمنوا ما فضل الله به بعضكم على بعض  للرجال نصيب مما اكتسبوا  وللنساء نصيب مما اكتسبن  وسلوا الله من فضله  إن الله كان بكل شىء عليما', NULL, 83, 'local:hafs-text.json'),
  ('hafs-4-33', 'hafs', 4, 33, 'وَلِكُلٍّۢ جَعَلْنَا مَوَٰلِىَ مِمَّا تَرَكَ ٱلْوَٰلِدَانِ وَٱلْأَقْرَبُونَ ۚ وَٱلَّذِينَ عَقَدَتْ أَيْمَٰنُكُمْ فَـَٔاتُوهُمْ نَصِيبَهُمْ ۚ إِنَّ ٱللَّهَ كَانَ عَلَىٰ كُلِّ شَىْءٍۢ شَهِيدًا', 'ولكل جعلنا مولى مما ترك الولدان والأقربون  والذين عقدت أيمنكم فاتوهم نصيبهم  إن الله كان على كل شىء شهيدا', NULL, 83, 'local:hafs-text.json'),
  ('hafs-4-34', 'hafs', 4, 34, 'ٱلرِّجَالُ قَوَّٰمُونَ عَلَى ٱلنِّسَآءِ بِمَا فَضَّلَ ٱللَّهُ بَعْضَهُمْ عَلَىٰ بَعْضٍۢ وَبِمَآ أَنفَقُوا۟ مِنْ أَمْوَٰلِهِمْ ۚ فَٱلصَّٰلِحَٰتُ قَٰنِتَٰتٌ حَٰفِظَٰتٌۭ لِّلْغَيْبِ بِمَا حَفِظَ ٱللَّهُ ۚ وَٱلَّٰتِى تَخَافُونَ نُشُوزَهُنَّ فَعِظُوهُنَّ وَٱهْجُرُوهُنَّ فِى ٱلْمَضَاجِعِ وَٱضْرِبُوهُنَّ ۖ فَإِنْ أَطَعْنَكُمْ فَلَا تَبْغُوا۟ عَلَيْهِنَّ سَبِيلًا ۗ إِنَّ ٱللَّهَ كَانَ عَلِيًّۭا كَبِيرًۭا', 'الرجال قومون على النساء بما فضل الله بعضهم على بعض وبما أنفقوا من أمولهم  فالصلحت قنتت حفظت للغيب بما حفظ الله  والتى تخافون نشوزهن فعظوهن واهجروهن فى المضاجع واضربوهن  فإن أطعنكم فلا تبغوا عليهن سبيلا  إن الله كان عليا كبيرا', NULL, 84, 'local:hafs-text.json'),
  ('hafs-4-35', 'hafs', 4, 35, 'وَإِنْ خِفْتُمْ شِقَاقَ بَيْنِهِمَا فَٱبْعَثُوا۟ حَكَمًۭا مِّنْ أَهْلِهِۦ وَحَكَمًۭا مِّنْ أَهْلِهَآ إِن يُرِيدَآ إِصْلَٰحًۭا يُوَفِّقِ ٱللَّهُ بَيْنَهُمَآ ۗ إِنَّ ٱللَّهَ كَانَ عَلِيمًا خَبِيرًۭا', 'وإن خفتم شقاق بينهما فابعثوا حكما من أهله وحكما من أهلها إن يريدا إصلحا يوفق الله بينهما  إن الله كان عليما خبيرا', NULL, 84, 'local:hafs-text.json'),
  ('hafs-4-36', 'hafs', 4, 36, '۞ وَٱعْبُدُوا۟ ٱللَّهَ وَلَا تُشْرِكُوا۟ بِهِۦ شَيْـًۭٔا ۖ وَبِٱلْوَٰلِدَيْنِ إِحْسَٰنًۭا وَبِذِى ٱلْقُرْبَىٰ وَٱلْيَتَٰمَىٰ وَٱلْمَسَٰكِينِ وَٱلْجَارِ ذِى ٱلْقُرْبَىٰ وَٱلْجَارِ ٱلْجُنُبِ وَٱلصَّاحِبِ بِٱلْجَنۢبِ وَٱبْنِ ٱلسَّبِيلِ وَمَا مَلَكَتْ أَيْمَٰنُكُمْ ۗ إِنَّ ٱللَّهَ لَا يُحِبُّ مَن كَانَ مُخْتَالًۭا فَخُورًا', 'واعبدوا الله ولا تشركوا به شيا  وبالولدين إحسنا وبذى القربى واليتمى والمسكين والجار ذى القربى والجار الجنب والصاحب بالجنب وابن السبيل وما ملكت أيمنكم  إن الله لا يحب من كان مختالا فخورا', NULL, 84, 'local:hafs-text.json'),
  ('hafs-4-37', 'hafs', 4, 37, 'ٱلَّذِينَ يَبْخَلُونَ وَيَأْمُرُونَ ٱلنَّاسَ بِٱلْبُخْلِ وَيَكْتُمُونَ مَآ ءَاتَىٰهُمُ ٱللَّهُ مِن فَضْلِهِۦ ۗ وَأَعْتَدْنَا لِلْكَٰفِرِينَ عَذَابًۭا مُّهِينًۭا', 'الذين يبخلون ويأمرون الناس بالبخل ويكتمون ما ءاتىهم الله من فضله  وأعتدنا للكفرين عذابا مهينا', NULL, 84, 'local:hafs-text.json'),
  ('hafs-4-38', 'hafs', 4, 38, 'وَٱلَّذِينَ يُنفِقُونَ أَمْوَٰلَهُمْ رِئَآءَ ٱلنَّاسِ وَلَا يُؤْمِنُونَ بِٱللَّهِ وَلَا بِٱلْيَوْمِ ٱلْءَاخِرِ ۗ وَمَن يَكُنِ ٱلشَّيْطَٰنُ لَهُۥ قَرِينًۭا فَسَآءَ قَرِينًۭا', 'والذين ينفقون أمولهم رئاء الناس ولا يؤمنون بالله ولا باليوم الءاخر  ومن يكن الشيطن له قرينا فساء قرينا', NULL, 85, 'local:hafs-text.json'),
  ('hafs-4-39', 'hafs', 4, 39, 'وَمَاذَا عَلَيْهِمْ لَوْ ءَامَنُوا۟ بِٱللَّهِ وَٱلْيَوْمِ ٱلْءَاخِرِ وَأَنفَقُوا۟ مِمَّا رَزَقَهُمُ ٱللَّهُ ۚ وَكَانَ ٱللَّهُ بِهِمْ عَلِيمًا', 'وماذا عليهم لو ءامنوا بالله واليوم الءاخر وأنفقوا مما رزقهم الله  وكان الله بهم عليما', NULL, 85, 'local:hafs-text.json'),
  ('hafs-4-40', 'hafs', 4, 40, 'إِنَّ ٱللَّهَ لَا يَظْلِمُ مِثْقَالَ ذَرَّةٍۢ ۖ وَإِن تَكُ حَسَنَةًۭ يُضَٰعِفْهَا وَيُؤْتِ مِن لَّدُنْهُ أَجْرًا عَظِيمًۭا', 'إن الله لا يظلم مثقال ذرة  وإن تك حسنة يضعفها ويؤت من لدنه أجرا عظيما', NULL, 85, 'local:hafs-text.json'),
  ('hafs-4-41', 'hafs', 4, 41, 'فَكَيْفَ إِذَا جِئْنَا مِن كُلِّ أُمَّةٍۭ بِشَهِيدٍۢ وَجِئْنَا بِكَ عَلَىٰ هَٰٓؤُلَآءِ شَهِيدًۭا', 'فكيف إذا جئنا من كل أمة بشهيد وجئنا بك على هؤلاء شهيدا', NULL, 85, 'local:hafs-text.json'),
  ('hafs-4-42', 'hafs', 4, 42, 'يَوْمَئِذٍۢ يَوَدُّ ٱلَّذِينَ كَفَرُوا۟ وَعَصَوُا۟ ٱلرَّسُولَ لَوْ تُسَوَّىٰ بِهِمُ ٱلْأَرْضُ وَلَا يَكْتُمُونَ ٱللَّهَ حَدِيثًۭا', 'يومئذ يود الذين كفروا وعصوا الرسول لو تسوى بهم الأرض ولا يكتمون الله حديثا', NULL, 85, 'local:hafs-text.json'),
  ('hafs-4-43', 'hafs', 4, 43, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَقْرَبُوا۟ ٱلصَّلَوٰةَ وَأَنتُمْ سُكَٰرَىٰ حَتَّىٰ تَعْلَمُوا۟ مَا تَقُولُونَ وَلَا جُنُبًا إِلَّا عَابِرِى سَبِيلٍ حَتَّىٰ تَغْتَسِلُوا۟ ۚ وَإِن كُنتُم مَّرْضَىٰٓ أَوْ عَلَىٰ سَفَرٍ أَوْ جَآءَ أَحَدٌۭ مِّنكُم مِّنَ ٱلْغَآئِطِ أَوْ لَٰمَسْتُمُ ٱلنِّسَآءَ فَلَمْ تَجِدُوا۟ مَآءًۭ فَتَيَمَّمُوا۟ صَعِيدًۭا طَيِّبًۭا فَٱمْسَحُوا۟ بِوُجُوهِكُمْ وَأَيْدِيكُمْ ۗ إِنَّ ٱللَّهَ كَانَ عَفُوًّا غَفُورًا', 'يأيها الذين ءامنوا لا تقربوا الصلوة وأنتم سكرى حتى تعلموا ما تقولون ولا جنبا إلا عابرى سبيل حتى تغتسلوا  وإن كنتم مرضى أو على سفر أو جاء أحد منكم من الغائط أو لمستم النساء فلم تجدوا ماء فتيمموا صعيدا طيبا فامسحوا بوجوهكم وأيديكم  إن الله كان عفوا غفورا', NULL, 85, 'local:hafs-text.json'),
  ('hafs-4-44', 'hafs', 4, 44, 'أَلَمْ تَرَ إِلَى ٱلَّذِينَ أُوتُوا۟ نَصِيبًۭا مِّنَ ٱلْكِتَٰبِ يَشْتَرُونَ ٱلضَّلَٰلَةَ وَيُرِيدُونَ أَن تَضِلُّوا۟ ٱلسَّبِيلَ', 'ألم تر إلى الذين أوتوا نصيبا من الكتب يشترون الضللة ويريدون أن تضلوا السبيل', NULL, 85, 'local:hafs-text.json'),
  ('hafs-4-45', 'hafs', 4, 45, 'وَٱللَّهُ أَعْلَمُ بِأَعْدَآئِكُمْ ۚ وَكَفَىٰ بِٱللَّهِ وَلِيًّۭا وَكَفَىٰ بِٱللَّهِ نَصِيرًۭا', 'والله أعلم بأعدائكم  وكفى بالله وليا وكفى بالله نصيرا', NULL, 86, 'local:hafs-text.json'),
  ('hafs-4-46', 'hafs', 4, 46, 'مِّنَ ٱلَّذِينَ هَادُوا۟ يُحَرِّفُونَ ٱلْكَلِمَ عَن مَّوَاضِعِهِۦ وَيَقُولُونَ سَمِعْنَا وَعَصَيْنَا وَٱسْمَعْ غَيْرَ مُسْمَعٍۢ وَرَٰعِنَا لَيًّۢا بِأَلْسِنَتِهِمْ وَطَعْنًۭا فِى ٱلدِّينِ ۚ وَلَوْ أَنَّهُمْ قَالُوا۟ سَمِعْنَا وَأَطَعْنَا وَٱسْمَعْ وَٱنظُرْنَا لَكَانَ خَيْرًۭا لَّهُمْ وَأَقْوَمَ وَلَٰكِن لَّعَنَهُمُ ٱللَّهُ بِكُفْرِهِمْ فَلَا يُؤْمِنُونَ إِلَّا قَلِيلًۭا', 'من الذين هادوا يحرفون الكلم عن مواضعه ويقولون سمعنا وعصينا واسمع غير مسمع ورعنا ليا بألسنتهم وطعنا فى الدين  ولو أنهم قالوا سمعنا وأطعنا واسمع وانظرنا لكان خيرا لهم وأقوم ولكن لعنهم الله بكفرهم فلا يؤمنون إلا قليلا', NULL, 86, 'local:hafs-text.json'),
  ('hafs-4-47', 'hafs', 4, 47, 'يَٰٓأَيُّهَا ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَٰبَ ءَامِنُوا۟ بِمَا نَزَّلْنَا مُصَدِّقًۭا لِّمَا مَعَكُم مِّن قَبْلِ أَن نَّطْمِسَ وُجُوهًۭا فَنَرُدَّهَا عَلَىٰٓ أَدْبَارِهَآ أَوْ نَلْعَنَهُمْ كَمَا لَعَنَّآ أَصْحَٰبَ ٱلسَّبْتِ ۚ وَكَانَ أَمْرُ ٱللَّهِ مَفْعُولًا', 'يأيها الذين أوتوا الكتب ءامنوا بما نزلنا مصدقا لما معكم من قبل أن نطمس وجوها فنردها على أدبارها أو نلعنهم كما لعنا أصحب السبت  وكان أمر الله مفعولا', NULL, 86, 'local:hafs-text.json'),
  ('hafs-4-48', 'hafs', 4, 48, 'إِنَّ ٱللَّهَ لَا يَغْفِرُ أَن يُشْرَكَ بِهِۦ وَيَغْفِرُ مَا دُونَ ذَٰلِكَ لِمَن يَشَآءُ ۚ وَمَن يُشْرِكْ بِٱللَّهِ فَقَدِ ٱفْتَرَىٰٓ إِثْمًا عَظِيمًا', 'إن الله لا يغفر أن يشرك به ويغفر ما دون ذلك لمن يشاء  ومن يشرك بالله فقد افترى إثما عظيما', NULL, 86, 'local:hafs-text.json'),
  ('hafs-4-49', 'hafs', 4, 49, 'أَلَمْ تَرَ إِلَى ٱلَّذِينَ يُزَكُّونَ أَنفُسَهُم ۚ بَلِ ٱللَّهُ يُزَكِّى مَن يَشَآءُ وَلَا يُظْلَمُونَ فَتِيلًا', 'ألم تر إلى الذين يزكون أنفسهم  بل الله يزكى من يشاء ولا يظلمون فتيلا', NULL, 86, 'local:hafs-text.json'),
  ('hafs-4-50', 'hafs', 4, 50, 'ٱنظُرْ كَيْفَ يَفْتَرُونَ عَلَى ٱللَّهِ ٱلْكَذِبَ ۖ وَكَفَىٰ بِهِۦٓ إِثْمًۭا مُّبِينًا', 'انظر كيف يفترون على الله الكذب  وكفى به إثما مبينا', NULL, 86, 'local:hafs-text.json'),
  ('hafs-4-51', 'hafs', 4, 51, 'أَلَمْ تَرَ إِلَى ٱلَّذِينَ أُوتُوا۟ نَصِيبًۭا مِّنَ ٱلْكِتَٰبِ يُؤْمِنُونَ بِٱلْجِبْتِ وَٱلطَّٰغُوتِ وَيَقُولُونَ لِلَّذِينَ كَفَرُوا۟ هَٰٓؤُلَآءِ أَهْدَىٰ مِنَ ٱلَّذِينَ ءَامَنُوا۟ سَبِيلًا', 'ألم تر إلى الذين أوتوا نصيبا من الكتب يؤمنون بالجبت والطغوت ويقولون للذين كفروا هؤلاء أهدى من الذين ءامنوا سبيلا', NULL, 86, 'local:hafs-text.json'),
  ('hafs-4-52', 'hafs', 4, 52, 'أُو۟لَٰٓئِكَ ٱلَّذِينَ لَعَنَهُمُ ٱللَّهُ ۖ وَمَن يَلْعَنِ ٱللَّهُ فَلَن تَجِدَ لَهُۥ نَصِيرًا', 'أولئك الذين لعنهم الله  ومن يلعن الله فلن تجد له نصيرا', NULL, 87, 'local:hafs-text.json'),
  ('hafs-4-53', 'hafs', 4, 53, 'أَمْ لَهُمْ نَصِيبٌۭ مِّنَ ٱلْمُلْكِ فَإِذًۭا لَّا يُؤْتُونَ ٱلنَّاسَ نَقِيرًا', 'أم لهم نصيب من الملك فإذا لا يؤتون الناس نقيرا', NULL, 87, 'local:hafs-text.json'),
  ('hafs-4-54', 'hafs', 4, 54, 'أَمْ يَحْسُدُونَ ٱلنَّاسَ عَلَىٰ مَآ ءَاتَىٰهُمُ ٱللَّهُ مِن فَضْلِهِۦ ۖ فَقَدْ ءَاتَيْنَآ ءَالَ إِبْرَٰهِيمَ ٱلْكِتَٰبَ وَٱلْحِكْمَةَ وَءَاتَيْنَٰهُم مُّلْكًا عَظِيمًۭا', 'أم يحسدون الناس على ما ءاتىهم الله من فضله  فقد ءاتينا ءال إبرهيم الكتب والحكمة وءاتينهم ملكا عظيما', NULL, 87, 'local:hafs-text.json'),
  ('hafs-4-55', 'hafs', 4, 55, 'فَمِنْهُم مَّنْ ءَامَنَ بِهِۦ وَمِنْهُم مَّن صَدَّ عَنْهُ ۚ وَكَفَىٰ بِجَهَنَّمَ سَعِيرًا', 'فمنهم من ءامن به ومنهم من صد عنه  وكفى بجهنم سعيرا', NULL, 87, 'local:hafs-text.json'),
  ('hafs-4-56', 'hafs', 4, 56, 'إِنَّ ٱلَّذِينَ كَفَرُوا۟ بِـَٔايَٰتِنَا سَوْفَ نُصْلِيهِمْ نَارًۭا كُلَّمَا نَضِجَتْ جُلُودُهُم بَدَّلْنَٰهُمْ جُلُودًا غَيْرَهَا لِيَذُوقُوا۟ ٱلْعَذَابَ ۗ إِنَّ ٱللَّهَ كَانَ عَزِيزًا حَكِيمًۭا', 'إن الذين كفروا بايتنا سوف نصليهم نارا كلما نضجت جلودهم بدلنهم جلودا غيرها ليذوقوا العذاب  إن الله كان عزيزا حكيما', NULL, 87, 'local:hafs-text.json'),
  ('hafs-4-57', 'hafs', 4, 57, 'وَٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ سَنُدْخِلُهُمْ جَنَّٰتٍۢ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ خَٰلِدِينَ فِيهَآ أَبَدًۭا ۖ لَّهُمْ فِيهَآ أَزْوَٰجٌۭ مُّطَهَّرَةٌۭ ۖ وَنُدْخِلُهُمْ ظِلًّۭا ظَلِيلًا', 'والذين ءامنوا وعملوا الصلحت سندخلهم جنت تجرى من تحتها الأنهر خلدين فيها أبدا  لهم فيها أزوج مطهرة  وندخلهم ظلا ظليلا', NULL, 87, 'local:hafs-text.json'),
  ('hafs-4-58', 'hafs', 4, 58, '۞ إِنَّ ٱللَّهَ يَأْمُرُكُمْ أَن تُؤَدُّوا۟ ٱلْأَمَٰنَٰتِ إِلَىٰٓ أَهْلِهَا وَإِذَا حَكَمْتُم بَيْنَ ٱلنَّاسِ أَن تَحْكُمُوا۟ بِٱلْعَدْلِ ۚ إِنَّ ٱللَّهَ نِعِمَّا يَعِظُكُم بِهِۦٓ ۗ إِنَّ ٱللَّهَ كَانَ سَمِيعًۢا بَصِيرًۭا', 'إن الله يأمركم أن تؤدوا الأمنت إلى أهلها وإذا حكمتم بين الناس أن تحكموا بالعدل  إن الله نعما يعظكم به  إن الله كان سميعا بصيرا', NULL, 87, 'local:hafs-text.json'),
  ('hafs-4-59', 'hafs', 4, 59, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ أَطِيعُوا۟ ٱللَّهَ وَأَطِيعُوا۟ ٱلرَّسُولَ وَأُو۟لِى ٱلْأَمْرِ مِنكُمْ ۖ فَإِن تَنَٰزَعْتُمْ فِى شَىْءٍۢ فَرُدُّوهُ إِلَى ٱللَّهِ وَٱلرَّسُولِ إِن كُنتُمْ تُؤْمِنُونَ بِٱللَّهِ وَٱلْيَوْمِ ٱلْءَاخِرِ ۚ ذَٰلِكَ خَيْرٌۭ وَأَحْسَنُ تَأْوِيلًا', 'يأيها الذين ءامنوا أطيعوا الله وأطيعوا الرسول وأولى الأمر منكم  فإن تنزعتم فى شىء فردوه إلى الله والرسول إن كنتم تؤمنون بالله واليوم الءاخر  ذلك خير وأحسن تأويلا', NULL, 87, 'local:hafs-text.json'),
  ('hafs-4-60', 'hafs', 4, 60, 'أَلَمْ تَرَ إِلَى ٱلَّذِينَ يَزْعُمُونَ أَنَّهُمْ ءَامَنُوا۟ بِمَآ أُنزِلَ إِلَيْكَ وَمَآ أُنزِلَ مِن قَبْلِكَ يُرِيدُونَ أَن يَتَحَاكَمُوٓا۟ إِلَى ٱلطَّٰغُوتِ وَقَدْ أُمِرُوٓا۟ أَن يَكْفُرُوا۟ بِهِۦ وَيُرِيدُ ٱلشَّيْطَٰنُ أَن يُضِلَّهُمْ ضَلَٰلًۢا بَعِيدًۭا', 'ألم تر إلى الذين يزعمون أنهم ءامنوا بما أنزل إليك وما أنزل من قبلك يريدون أن يتحاكموا إلى الطغوت وقد أمروا أن يكفروا به ويريد الشيطن أن يضلهم ضللا بعيدا', NULL, 88, 'local:hafs-text.json'),
  ('hafs-4-61', 'hafs', 4, 61, 'وَإِذَا قِيلَ لَهُمْ تَعَالَوْا۟ إِلَىٰ مَآ أَنزَلَ ٱللَّهُ وَإِلَى ٱلرَّسُولِ رَأَيْتَ ٱلْمُنَٰفِقِينَ يَصُدُّونَ عَنكَ صُدُودًۭا', 'وإذا قيل لهم تعالوا إلى ما أنزل الله وإلى الرسول رأيت المنفقين يصدون عنك صدودا', NULL, 88, 'local:hafs-text.json'),
  ('hafs-4-62', 'hafs', 4, 62, 'فَكَيْفَ إِذَآ أَصَٰبَتْهُم مُّصِيبَةٌۢ بِمَا قَدَّمَتْ أَيْدِيهِمْ ثُمَّ جَآءُوكَ يَحْلِفُونَ بِٱللَّهِ إِنْ أَرَدْنَآ إِلَّآ إِحْسَٰنًۭا وَتَوْفِيقًا', 'فكيف إذا أصبتهم مصيبة بما قدمت أيديهم ثم جاءوك يحلفون بالله إن أردنا إلا إحسنا وتوفيقا', NULL, 88, 'local:hafs-text.json'),
  ('hafs-4-63', 'hafs', 4, 63, 'أُو۟لَٰٓئِكَ ٱلَّذِينَ يَعْلَمُ ٱللَّهُ مَا فِى قُلُوبِهِمْ فَأَعْرِضْ عَنْهُمْ وَعِظْهُمْ وَقُل لَّهُمْ فِىٓ أَنفُسِهِمْ قَوْلًۢا بَلِيغًۭا', 'أولئك الذين يعلم الله ما فى قلوبهم فأعرض عنهم وعظهم وقل لهم فى أنفسهم قولا بليغا', NULL, 88, 'local:hafs-text.json'),
  ('hafs-4-64', 'hafs', 4, 64, 'وَمَآ أَرْسَلْنَا مِن رَّسُولٍ إِلَّا لِيُطَاعَ بِإِذْنِ ٱللَّهِ ۚ وَلَوْ أَنَّهُمْ إِذ ظَّلَمُوٓا۟ أَنفُسَهُمْ جَآءُوكَ فَٱسْتَغْفَرُوا۟ ٱللَّهَ وَٱسْتَغْفَرَ لَهُمُ ٱلرَّسُولُ لَوَجَدُوا۟ ٱللَّهَ تَوَّابًۭا رَّحِيمًۭا', 'وما أرسلنا من رسول إلا ليطاع بإذن الله  ولو أنهم إذ ظلموا أنفسهم جاءوك فاستغفروا الله واستغفر لهم الرسول لوجدوا الله توابا رحيما', NULL, 88, 'local:hafs-text.json'),
  ('hafs-4-65', 'hafs', 4, 65, 'فَلَا وَرَبِّكَ لَا يُؤْمِنُونَ حَتَّىٰ يُحَكِّمُوكَ فِيمَا شَجَرَ بَيْنَهُمْ ثُمَّ لَا يَجِدُوا۟ فِىٓ أَنفُسِهِمْ حَرَجًۭا مِّمَّا قَضَيْتَ وَيُسَلِّمُوا۟ تَسْلِيمًۭا', 'فلا وربك لا يؤمنون حتى يحكموك فيما شجر بينهم ثم لا يجدوا فى أنفسهم حرجا مما قضيت ويسلموا تسليما', NULL, 88, 'local:hafs-text.json'),
  ('hafs-4-66', 'hafs', 4, 66, 'وَلَوْ أَنَّا كَتَبْنَا عَلَيْهِمْ أَنِ ٱقْتُلُوٓا۟ أَنفُسَكُمْ أَوِ ٱخْرُجُوا۟ مِن دِيَٰرِكُم مَّا فَعَلُوهُ إِلَّا قَلِيلٌۭ مِّنْهُمْ ۖ وَلَوْ أَنَّهُمْ فَعَلُوا۟ مَا يُوعَظُونَ بِهِۦ لَكَانَ خَيْرًۭا لَّهُمْ وَأَشَدَّ تَثْبِيتًۭا', 'ولو أنا كتبنا عليهم أن اقتلوا أنفسكم أو اخرجوا من ديركم ما فعلوه إلا قليل منهم  ولو أنهم فعلوا ما يوعظون به لكان خيرا لهم وأشد تثبيتا', NULL, 89, 'local:hafs-text.json'),
  ('hafs-4-67', 'hafs', 4, 67, 'وَإِذًۭا لَّءَاتَيْنَٰهُم مِّن لَّدُنَّآ أَجْرًا عَظِيمًۭا', 'وإذا لءاتينهم من لدنا أجرا عظيما', NULL, 89, 'local:hafs-text.json'),
  ('hafs-4-68', 'hafs', 4, 68, 'وَلَهَدَيْنَٰهُمْ صِرَٰطًۭا مُّسْتَقِيمًۭا', 'ولهدينهم صرطا مستقيما', NULL, 89, 'local:hafs-text.json'),
  ('hafs-4-69', 'hafs', 4, 69, 'وَمَن يُطِعِ ٱللَّهَ وَٱلرَّسُولَ فَأُو۟لَٰٓئِكَ مَعَ ٱلَّذِينَ أَنْعَمَ ٱللَّهُ عَلَيْهِم مِّنَ ٱلنَّبِيِّۦنَ وَٱلصِّدِّيقِينَ وَٱلشُّهَدَآءِ وَٱلصَّٰلِحِينَ ۚ وَحَسُنَ أُو۟لَٰٓئِكَ رَفِيقًۭا', 'ومن يطع الله والرسول فأولئك مع الذين أنعم الله عليهم من النبين والصديقين والشهداء والصلحين  وحسن أولئك رفيقا', NULL, 89, 'local:hafs-text.json'),
  ('hafs-4-70', 'hafs', 4, 70, 'ذَٰلِكَ ٱلْفَضْلُ مِنَ ٱللَّهِ ۚ وَكَفَىٰ بِٱللَّهِ عَلِيمًۭا', 'ذلك الفضل من الله  وكفى بالله عليما', NULL, 89, 'local:hafs-text.json'),
  ('hafs-4-71', 'hafs', 4, 71, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ خُذُوا۟ حِذْرَكُمْ فَٱنفِرُوا۟ ثُبَاتٍ أَوِ ٱنفِرُوا۟ جَمِيعًۭا', 'يأيها الذين ءامنوا خذوا حذركم فانفروا ثبات أو انفروا جميعا', NULL, 89, 'local:hafs-text.json'),
  ('hafs-4-72', 'hafs', 4, 72, 'وَإِنَّ مِنكُمْ لَمَن لَّيُبَطِّئَنَّ فَإِنْ أَصَٰبَتْكُم مُّصِيبَةٌۭ قَالَ قَدْ أَنْعَمَ ٱللَّهُ عَلَىَّ إِذْ لَمْ أَكُن مَّعَهُمْ شَهِيدًۭا', 'وإن منكم لمن ليبطئن فإن أصبتكم مصيبة قال قد أنعم الله على إذ لم أكن معهم شهيدا', NULL, 89, 'local:hafs-text.json'),
  ('hafs-4-73', 'hafs', 4, 73, 'وَلَئِنْ أَصَٰبَكُمْ فَضْلٌۭ مِّنَ ٱللَّهِ لَيَقُولَنَّ كَأَن لَّمْ تَكُنۢ بَيْنَكُمْ وَبَيْنَهُۥ مَوَدَّةٌۭ يَٰلَيْتَنِى كُنتُ مَعَهُمْ فَأَفُوزَ فَوْزًا عَظِيمًۭا', 'ولئن أصبكم فضل من الله ليقولن كأن لم تكن بينكم وبينه مودة يليتنى كنت معهم فأفوز فوزا عظيما', NULL, 89, 'local:hafs-text.json'),
  ('hafs-4-74', 'hafs', 4, 74, '۞ فَلْيُقَٰتِلْ فِى سَبِيلِ ٱللَّهِ ٱلَّذِينَ يَشْرُونَ ٱلْحَيَوٰةَ ٱلدُّنْيَا بِٱلْءَاخِرَةِ ۚ وَمَن يُقَٰتِلْ فِى سَبِيلِ ٱللَّهِ فَيُقْتَلْ أَوْ يَغْلِبْ فَسَوْفَ نُؤْتِيهِ أَجْرًا عَظِيمًۭا', 'فليقتل فى سبيل الله الذين يشرون الحيوة الدنيا بالءاخرة  ومن يقتل فى سبيل الله فيقتل أو يغلب فسوف نؤتيه أجرا عظيما', NULL, 89, 'local:hafs-text.json'),
  ('hafs-4-75', 'hafs', 4, 75, 'وَمَا لَكُمْ لَا تُقَٰتِلُونَ فِى سَبِيلِ ٱللَّهِ وَٱلْمُسْتَضْعَفِينَ مِنَ ٱلرِّجَالِ وَٱلنِّسَآءِ وَٱلْوِلْدَٰنِ ٱلَّذِينَ يَقُولُونَ رَبَّنَآ أَخْرِجْنَا مِنْ هَٰذِهِ ٱلْقَرْيَةِ ٱلظَّالِمِ أَهْلُهَا وَٱجْعَل لَّنَا مِن لَّدُنكَ وَلِيًّۭا وَٱجْعَل لَّنَا مِن لَّدُنكَ نَصِيرًا', 'وما لكم لا تقتلون فى سبيل الله والمستضعفين من الرجال والنساء والولدن الذين يقولون ربنا أخرجنا من هذه القرية الظالم أهلها واجعل لنا من لدنك وليا واجعل لنا من لدنك نصيرا', NULL, 90, 'local:hafs-text.json'),
  ('hafs-4-76', 'hafs', 4, 76, 'ٱلَّذِينَ ءَامَنُوا۟ يُقَٰتِلُونَ فِى سَبِيلِ ٱللَّهِ ۖ وَٱلَّذِينَ كَفَرُوا۟ يُقَٰتِلُونَ فِى سَبِيلِ ٱلطَّٰغُوتِ فَقَٰتِلُوٓا۟ أَوْلِيَآءَ ٱلشَّيْطَٰنِ ۖ إِنَّ كَيْدَ ٱلشَّيْطَٰنِ كَانَ ضَعِيفًا', 'الذين ءامنوا يقتلون فى سبيل الله  والذين كفروا يقتلون فى سبيل الطغوت فقتلوا أولياء الشيطن  إن كيد الشيطن كان ضعيفا', NULL, 90, 'local:hafs-text.json'),
  ('hafs-4-77', 'hafs', 4, 77, 'أَلَمْ تَرَ إِلَى ٱلَّذِينَ قِيلَ لَهُمْ كُفُّوٓا۟ أَيْدِيَكُمْ وَأَقِيمُوا۟ ٱلصَّلَوٰةَ وَءَاتُوا۟ ٱلزَّكَوٰةَ فَلَمَّا كُتِبَ عَلَيْهِمُ ٱلْقِتَالُ إِذَا فَرِيقٌۭ مِّنْهُمْ يَخْشَوْنَ ٱلنَّاسَ كَخَشْيَةِ ٱللَّهِ أَوْ أَشَدَّ خَشْيَةًۭ ۚ وَقَالُوا۟ رَبَّنَا لِمَ كَتَبْتَ عَلَيْنَا ٱلْقِتَالَ لَوْلَآ أَخَّرْتَنَآ إِلَىٰٓ أَجَلٍۢ قَرِيبٍۢ ۗ قُلْ مَتَٰعُ ٱلدُّنْيَا قَلِيلٌۭ وَٱلْءَاخِرَةُ خَيْرٌۭ لِّمَنِ ٱتَّقَىٰ وَلَا تُظْلَمُونَ فَتِيلًا', 'ألم تر إلى الذين قيل لهم كفوا أيديكم وأقيموا الصلوة وءاتوا الزكوة فلما كتب عليهم القتال إذا فريق منهم يخشون الناس كخشية الله أو أشد خشية  وقالوا ربنا لم كتبت علينا القتال لولا أخرتنا إلى أجل قريب  قل متع الدنيا قليل والءاخرة خير لمن اتقى ولا تظلمون فتيلا', NULL, 90, 'local:hafs-text.json'),
  ('hafs-4-78', 'hafs', 4, 78, 'أَيْنَمَا تَكُونُوا۟ يُدْرِككُّمُ ٱلْمَوْتُ وَلَوْ كُنتُمْ فِى بُرُوجٍۢ مُّشَيَّدَةٍۢ ۗ وَإِن تُصِبْهُمْ حَسَنَةٌۭ يَقُولُوا۟ هَٰذِهِۦ مِنْ عِندِ ٱللَّهِ ۖ وَإِن تُصِبْهُمْ سَيِّئَةٌۭ يَقُولُوا۟ هَٰذِهِۦ مِنْ عِندِكَ ۚ قُلْ كُلٌّۭ مِّنْ عِندِ ٱللَّهِ ۖ فَمَالِ هَٰٓؤُلَآءِ ٱلْقَوْمِ لَا يَكَادُونَ يَفْقَهُونَ حَدِيثًۭا', 'أينما تكونوا يدرككم الموت ولو كنتم فى بروج مشيدة  وإن تصبهم حسنة يقولوا هذه من عند الله  وإن تصبهم سيئة يقولوا هذه من عندك  قل كل من عند الله  فمال هؤلاء القوم لا يكادون يفقهون حديثا', NULL, 90, 'local:hafs-text.json'),
  ('hafs-4-79', 'hafs', 4, 79, 'مَّآ أَصَابَكَ مِنْ حَسَنَةٍۢ فَمِنَ ٱللَّهِ ۖ وَمَآ أَصَابَكَ مِن سَيِّئَةٍۢ فَمِن نَّفْسِكَ ۚ وَأَرْسَلْنَٰكَ لِلنَّاسِ رَسُولًۭا ۚ وَكَفَىٰ بِٱللَّهِ شَهِيدًۭا', 'ما أصابك من حسنة فمن الله  وما أصابك من سيئة فمن نفسك  وأرسلنك للناس رسولا  وكفى بالله شهيدا', NULL, 90, 'local:hafs-text.json'),
  ('hafs-4-80', 'hafs', 4, 80, 'مَّن يُطِعِ ٱلرَّسُولَ فَقَدْ أَطَاعَ ٱللَّهَ ۖ وَمَن تَوَلَّىٰ فَمَآ أَرْسَلْنَٰكَ عَلَيْهِمْ حَفِيظًۭا', 'من يطع الرسول فقد أطاع الله  ومن تولى فما أرسلنك عليهم حفيظا', NULL, 91, 'local:hafs-text.json'),
  ('hafs-4-81', 'hafs', 4, 81, 'وَيَقُولُونَ طَاعَةٌۭ فَإِذَا بَرَزُوا۟ مِنْ عِندِكَ بَيَّتَ طَآئِفَةٌۭ مِّنْهُمْ غَيْرَ ٱلَّذِى تَقُولُ ۖ وَٱللَّهُ يَكْتُبُ مَا يُبَيِّتُونَ ۖ فَأَعْرِضْ عَنْهُمْ وَتَوَكَّلْ عَلَى ٱللَّهِ ۚ وَكَفَىٰ بِٱللَّهِ وَكِيلًا', 'ويقولون طاعة فإذا برزوا من عندك بيت طائفة منهم غير الذى تقول  والله يكتب ما يبيتون  فأعرض عنهم وتوكل على الله  وكفى بالله وكيلا', NULL, 91, 'local:hafs-text.json'),
  ('hafs-4-82', 'hafs', 4, 82, 'أَفَلَا يَتَدَبَّرُونَ ٱلْقُرْءَانَ ۚ وَلَوْ كَانَ مِنْ عِندِ غَيْرِ ٱللَّهِ لَوَجَدُوا۟ فِيهِ ٱخْتِلَٰفًۭا كَثِيرًۭا', 'أفلا يتدبرون القرءان  ولو كان من عند غير الله لوجدوا فيه اختلفا كثيرا', NULL, 91, 'local:hafs-text.json'),
  ('hafs-4-83', 'hafs', 4, 83, 'وَإِذَا جَآءَهُمْ أَمْرٌۭ مِّنَ ٱلْأَمْنِ أَوِ ٱلْخَوْفِ أَذَاعُوا۟ بِهِۦ ۖ وَلَوْ رَدُّوهُ إِلَى ٱلرَّسُولِ وَإِلَىٰٓ أُو۟لِى ٱلْأَمْرِ مِنْهُمْ لَعَلِمَهُ ٱلَّذِينَ يَسْتَنۢبِطُونَهُۥ مِنْهُمْ ۗ وَلَوْلَا فَضْلُ ٱللَّهِ عَلَيْكُمْ وَرَحْمَتُهُۥ لَٱتَّبَعْتُمُ ٱلشَّيْطَٰنَ إِلَّا قَلِيلًۭا', 'وإذا جاءهم أمر من الأمن أو الخوف أذاعوا به  ولو ردوه إلى الرسول وإلى أولى الأمر منهم لعلمه الذين يستنبطونه منهم  ولولا فضل الله عليكم ورحمته لاتبعتم الشيطن إلا قليلا', NULL, 91, 'local:hafs-text.json'),
  ('hafs-4-84', 'hafs', 4, 84, 'فَقَٰتِلْ فِى سَبِيلِ ٱللَّهِ لَا تُكَلَّفُ إِلَّا نَفْسَكَ ۚ وَحَرِّضِ ٱلْمُؤْمِنِينَ ۖ عَسَى ٱللَّهُ أَن يَكُفَّ بَأْسَ ٱلَّذِينَ كَفَرُوا۟ ۚ وَٱللَّهُ أَشَدُّ بَأْسًۭا وَأَشَدُّ تَنكِيلًۭا', 'فقتل فى سبيل الله لا تكلف إلا نفسك  وحرض المؤمنين  عسى الله أن يكف بأس الذين كفروا  والله أشد بأسا وأشد تنكيلا', NULL, 91, 'local:hafs-text.json'),
  ('hafs-4-85', 'hafs', 4, 85, 'مَّن يَشْفَعْ شَفَٰعَةً حَسَنَةًۭ يَكُن لَّهُۥ نَصِيبٌۭ مِّنْهَا ۖ وَمَن يَشْفَعْ شَفَٰعَةًۭ سَيِّئَةًۭ يَكُن لَّهُۥ كِفْلٌۭ مِّنْهَا ۗ وَكَانَ ٱللَّهُ عَلَىٰ كُلِّ شَىْءٍۢ مُّقِيتًۭا', 'من يشفع شفعة حسنة يكن له نصيب منها  ومن يشفع شفعة سيئة يكن له كفل منها  وكان الله على كل شىء مقيتا', NULL, 91, 'local:hafs-text.json'),
  ('hafs-4-86', 'hafs', 4, 86, 'وَإِذَا حُيِّيتُم بِتَحِيَّةٍۢ فَحَيُّوا۟ بِأَحْسَنَ مِنْهَآ أَوْ رُدُّوهَآ ۗ إِنَّ ٱللَّهَ كَانَ عَلَىٰ كُلِّ شَىْءٍ حَسِيبًا', 'وإذا حييتم بتحية فحيوا بأحسن منها أو ردوها  إن الله كان على كل شىء حسيبا', NULL, 91, 'local:hafs-text.json'),
  ('hafs-4-87', 'hafs', 4, 87, 'ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَ ۚ لَيَجْمَعَنَّكُمْ إِلَىٰ يَوْمِ ٱلْقِيَٰمَةِ لَا رَيْبَ فِيهِ ۗ وَمَنْ أَصْدَقُ مِنَ ٱللَّهِ حَدِيثًۭا', 'الله لا إله إلا هو  ليجمعنكم إلى يوم القيمة لا ريب فيه  ومن أصدق من الله حديثا', NULL, 92, 'local:hafs-text.json'),
  ('hafs-4-88', 'hafs', 4, 88, '۞ فَمَا لَكُمْ فِى ٱلْمُنَٰفِقِينَ فِئَتَيْنِ وَٱللَّهُ أَرْكَسَهُم بِمَا كَسَبُوٓا۟ ۚ أَتُرِيدُونَ أَن تَهْدُوا۟ مَنْ أَضَلَّ ٱللَّهُ ۖ وَمَن يُضْلِلِ ٱللَّهُ فَلَن تَجِدَ لَهُۥ سَبِيلًۭا', 'فما لكم فى المنفقين فئتين والله أركسهم بما كسبوا  أتريدون أن تهدوا من أضل الله  ومن يضلل الله فلن تجد له سبيلا', NULL, 92, 'local:hafs-text.json'),
  ('hafs-4-89', 'hafs', 4, 89, 'وَدُّوا۟ لَوْ تَكْفُرُونَ كَمَا كَفَرُوا۟ فَتَكُونُونَ سَوَآءًۭ ۖ فَلَا تَتَّخِذُوا۟ مِنْهُمْ أَوْلِيَآءَ حَتَّىٰ يُهَاجِرُوا۟ فِى سَبِيلِ ٱللَّهِ ۚ فَإِن تَوَلَّوْا۟ فَخُذُوهُمْ وَٱقْتُلُوهُمْ حَيْثُ وَجَدتُّمُوهُمْ ۖ وَلَا تَتَّخِذُوا۟ مِنْهُمْ وَلِيًّۭا وَلَا نَصِيرًا', 'ودوا لو تكفرون كما كفروا فتكونون سواء  فلا تتخذوا منهم أولياء حتى يهاجروا فى سبيل الله  فإن تولوا فخذوهم واقتلوهم حيث وجدتموهم  ولا تتخذوا منهم وليا ولا نصيرا', NULL, 92, 'local:hafs-text.json'),
  ('hafs-4-90', 'hafs', 4, 90, 'إِلَّا ٱلَّذِينَ يَصِلُونَ إِلَىٰ قَوْمٍۭ بَيْنَكُمْ وَبَيْنَهُم مِّيثَٰقٌ أَوْ جَآءُوكُمْ حَصِرَتْ صُدُورُهُمْ أَن يُقَٰتِلُوكُمْ أَوْ يُقَٰتِلُوا۟ قَوْمَهُمْ ۚ وَلَوْ شَآءَ ٱللَّهُ لَسَلَّطَهُمْ عَلَيْكُمْ فَلَقَٰتَلُوكُمْ ۚ فَإِنِ ٱعْتَزَلُوكُمْ فَلَمْ يُقَٰتِلُوكُمْ وَأَلْقَوْا۟ إِلَيْكُمُ ٱلسَّلَمَ فَمَا جَعَلَ ٱللَّهُ لَكُمْ عَلَيْهِمْ سَبِيلًۭا', 'إلا الذين يصلون إلى قوم بينكم وبينهم ميثق أو جاءوكم حصرت صدورهم أن يقتلوكم أو يقتلوا قومهم  ولو شاء الله لسلطهم عليكم فلقتلوكم  فإن اعتزلوكم فلم يقتلوكم وألقوا إليكم السلم فما جعل الله لكم عليهم سبيلا', NULL, 92, 'local:hafs-text.json'),
  ('hafs-4-91', 'hafs', 4, 91, 'سَتَجِدُونَ ءَاخَرِينَ يُرِيدُونَ أَن يَأْمَنُوكُمْ وَيَأْمَنُوا۟ قَوْمَهُمْ كُلَّ مَا رُدُّوٓا۟ إِلَى ٱلْفِتْنَةِ أُرْكِسُوا۟ فِيهَا ۚ فَإِن لَّمْ يَعْتَزِلُوكُمْ وَيُلْقُوٓا۟ إِلَيْكُمُ ٱلسَّلَمَ وَيَكُفُّوٓا۟ أَيْدِيَهُمْ فَخُذُوهُمْ وَٱقْتُلُوهُمْ حَيْثُ ثَقِفْتُمُوهُمْ ۚ وَأُو۟لَٰٓئِكُمْ جَعَلْنَا لَكُمْ عَلَيْهِمْ سُلْطَٰنًۭا مُّبِينًۭا', 'ستجدون ءاخرين يريدون أن يأمنوكم ويأمنوا قومهم كل ما ردوا إلى الفتنة أركسوا فيها  فإن لم يعتزلوكم ويلقوا إليكم السلم ويكفوا أيديهم فخذوهم واقتلوهم حيث ثقفتموهم  وأولئكم جعلنا لكم عليهم سلطنا مبينا', NULL, 92, 'local:hafs-text.json'),
  ('hafs-4-92', 'hafs', 4, 92, 'وَمَا كَانَ لِمُؤْمِنٍ أَن يَقْتُلَ مُؤْمِنًا إِلَّا خَطَـًۭٔا ۚ وَمَن قَتَلَ مُؤْمِنًا خَطَـًۭٔا فَتَحْرِيرُ رَقَبَةٍۢ مُّؤْمِنَةٍۢ وَدِيَةٌۭ مُّسَلَّمَةٌ إِلَىٰٓ أَهْلِهِۦٓ إِلَّآ أَن يَصَّدَّقُوا۟ ۚ فَإِن كَانَ مِن قَوْمٍ عَدُوٍّۢ لَّكُمْ وَهُوَ مُؤْمِنٌۭ فَتَحْرِيرُ رَقَبَةٍۢ مُّؤْمِنَةٍۢ ۖ وَإِن كَانَ مِن قَوْمٍۭ بَيْنَكُمْ وَبَيْنَهُم مِّيثَٰقٌۭ فَدِيَةٌۭ مُّسَلَّمَةٌ إِلَىٰٓ أَهْلِهِۦ وَتَحْرِيرُ رَقَبَةٍۢ مُّؤْمِنَةٍۢ ۖ فَمَن لَّمْ يَجِدْ فَصِيَامُ شَهْرَيْنِ مُتَتَابِعَيْنِ تَوْبَةًۭ مِّنَ ٱللَّهِ ۗ وَكَانَ ٱللَّهُ عَلِيمًا حَكِيمًۭا', 'وما كان لمؤمن أن يقتل مؤمنا إلا خطا  ومن قتل مؤمنا خطا فتحرير رقبة مؤمنة ودية مسلمة إلى أهله إلا أن يصدقوا  فإن كان من قوم عدو لكم وهو مؤمن فتحرير رقبة مؤمنة  وإن كان من قوم بينكم وبينهم ميثق فدية مسلمة إلى أهله وتحرير رقبة مؤمنة  فمن لم يجد فصيام شهرين متتابعين توبة من الله  وكان الله عليما حكيما', NULL, 93, 'local:hafs-text.json'),
  ('hafs-4-93', 'hafs', 4, 93, 'وَمَن يَقْتُلْ مُؤْمِنًۭا مُّتَعَمِّدًۭا فَجَزَآؤُهُۥ جَهَنَّمُ خَٰلِدًۭا فِيهَا وَغَضِبَ ٱللَّهُ عَلَيْهِ وَلَعَنَهُۥ وَأَعَدَّ لَهُۥ عَذَابًا عَظِيمًۭا', 'ومن يقتل مؤمنا متعمدا فجزاؤه جهنم خلدا فيها وغضب الله عليه ولعنه وأعد له عذابا عظيما', NULL, 93, 'local:hafs-text.json'),
  ('hafs-4-94', 'hafs', 4, 94, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِذَا ضَرَبْتُمْ فِى سَبِيلِ ٱللَّهِ فَتَبَيَّنُوا۟ وَلَا تَقُولُوا۟ لِمَنْ أَلْقَىٰٓ إِلَيْكُمُ ٱلسَّلَٰمَ لَسْتَ مُؤْمِنًۭا تَبْتَغُونَ عَرَضَ ٱلْحَيَوٰةِ ٱلدُّنْيَا فَعِندَ ٱللَّهِ مَغَانِمُ كَثِيرَةٌۭ ۚ كَذَٰلِكَ كُنتُم مِّن قَبْلُ فَمَنَّ ٱللَّهُ عَلَيْكُمْ فَتَبَيَّنُوٓا۟ ۚ إِنَّ ٱللَّهَ كَانَ بِمَا تَعْمَلُونَ خَبِيرًۭا', 'يأيها الذين ءامنوا إذا ضربتم فى سبيل الله فتبينوا ولا تقولوا لمن ألقى إليكم السلم لست مؤمنا تبتغون عرض الحيوة الدنيا فعند الله مغانم كثيرة  كذلك كنتم من قبل فمن الله عليكم فتبينوا  إن الله كان بما تعملون خبيرا', NULL, 93, 'local:hafs-text.json'),
  ('hafs-4-95', 'hafs', 4, 95, 'لَّا يَسْتَوِى ٱلْقَٰعِدُونَ مِنَ ٱلْمُؤْمِنِينَ غَيْرُ أُو۟لِى ٱلضَّرَرِ وَٱلْمُجَٰهِدُونَ فِى سَبِيلِ ٱللَّهِ بِأَمْوَٰلِهِمْ وَأَنفُسِهِمْ ۚ فَضَّلَ ٱللَّهُ ٱلْمُجَٰهِدِينَ بِأَمْوَٰلِهِمْ وَأَنفُسِهِمْ عَلَى ٱلْقَٰعِدِينَ دَرَجَةًۭ ۚ وَكُلًّۭا وَعَدَ ٱللَّهُ ٱلْحُسْنَىٰ ۚ وَفَضَّلَ ٱللَّهُ ٱلْمُجَٰهِدِينَ عَلَى ٱلْقَٰعِدِينَ أَجْرًا عَظِيمًۭا', 'لا يستوى القعدون من المؤمنين غير أولى الضرر والمجهدون فى سبيل الله بأمولهم وأنفسهم  فضل الله المجهدين بأمولهم وأنفسهم على القعدين درجة  وكلا وعد الله الحسنى  وفضل الله المجهدين على القعدين أجرا عظيما', NULL, 94, 'local:hafs-text.json'),
  ('hafs-4-96', 'hafs', 4, 96, 'دَرَجَٰتٍۢ مِّنْهُ وَمَغْفِرَةًۭ وَرَحْمَةًۭ ۚ وَكَانَ ٱللَّهُ غَفُورًۭا رَّحِيمًا', 'درجت منه ومغفرة ورحمة  وكان الله غفورا رحيما', NULL, 94, 'local:hafs-text.json'),
  ('hafs-4-97', 'hafs', 4, 97, 'إِنَّ ٱلَّذِينَ تَوَفَّىٰهُمُ ٱلْمَلَٰٓئِكَةُ ظَالِمِىٓ أَنفُسِهِمْ قَالُوا۟ فِيمَ كُنتُمْ ۖ قَالُوا۟ كُنَّا مُسْتَضْعَفِينَ فِى ٱلْأَرْضِ ۚ قَالُوٓا۟ أَلَمْ تَكُنْ أَرْضُ ٱللَّهِ وَٰسِعَةًۭ فَتُهَاجِرُوا۟ فِيهَا ۚ فَأُو۟لَٰٓئِكَ مَأْوَىٰهُمْ جَهَنَّمُ ۖ وَسَآءَتْ مَصِيرًا', 'إن الذين توفىهم الملئكة ظالمى أنفسهم قالوا فيم كنتم  قالوا كنا مستضعفين فى الأرض  قالوا ألم تكن أرض الله وسعة فتهاجروا فيها  فأولئك مأوىهم جهنم  وساءت مصيرا', NULL, 94, 'local:hafs-text.json'),
  ('hafs-4-98', 'hafs', 4, 98, 'إِلَّا ٱلْمُسْتَضْعَفِينَ مِنَ ٱلرِّجَالِ وَٱلنِّسَآءِ وَٱلْوِلْدَٰنِ لَا يَسْتَطِيعُونَ حِيلَةًۭ وَلَا يَهْتَدُونَ سَبِيلًۭا', 'إلا المستضعفين من الرجال والنساء والولدن لا يستطيعون حيلة ولا يهتدون سبيلا', NULL, 94, 'local:hafs-text.json'),
  ('hafs-4-99', 'hafs', 4, 99, 'فَأُو۟لَٰٓئِكَ عَسَى ٱللَّهُ أَن يَعْفُوَ عَنْهُمْ ۚ وَكَانَ ٱللَّهُ عَفُوًّا غَفُورًۭا', 'فأولئك عسى الله أن يعفو عنهم  وكان الله عفوا غفورا', NULL, 94, 'local:hafs-text.json'),
  ('hafs-4-100', 'hafs', 4, 100, '۞ وَمَن يُهَاجِرْ فِى سَبِيلِ ٱللَّهِ يَجِدْ فِى ٱلْأَرْضِ مُرَٰغَمًۭا كَثِيرًۭا وَسَعَةًۭ ۚ وَمَن يَخْرُجْ مِنۢ بَيْتِهِۦ مُهَاجِرًا إِلَى ٱللَّهِ وَرَسُولِهِۦ ثُمَّ يُدْرِكْهُ ٱلْمَوْتُ فَقَدْ وَقَعَ أَجْرُهُۥ عَلَى ٱللَّهِ ۗ وَكَانَ ٱللَّهُ غَفُورًۭا رَّحِيمًۭا', 'ومن يهاجر فى سبيل الله يجد فى الأرض مرغما كثيرا وسعة  ومن يخرج من بيته مهاجرا إلى الله ورسوله ثم يدركه الموت فقد وقع أجره على الله  وكان الله غفورا رحيما', NULL, 94, 'local:hafs-text.json'),
  ('hafs-4-101', 'hafs', 4, 101, 'وَإِذَا ضَرَبْتُمْ فِى ٱلْأَرْضِ فَلَيْسَ عَلَيْكُمْ جُنَاحٌ أَن تَقْصُرُوا۟ مِنَ ٱلصَّلَوٰةِ إِنْ خِفْتُمْ أَن يَفْتِنَكُمُ ٱلَّذِينَ كَفَرُوٓا۟ ۚ إِنَّ ٱلْكَٰفِرِينَ كَانُوا۟ لَكُمْ عَدُوًّۭا مُّبِينًۭا', 'وإذا ضربتم فى الأرض فليس عليكم جناح أن تقصروا من الصلوة إن خفتم أن يفتنكم الذين كفروا  إن الكفرين كانوا لكم عدوا مبينا', NULL, 94, 'local:hafs-text.json'),
  ('hafs-4-102', 'hafs', 4, 102, 'وَإِذَا كُنتَ فِيهِمْ فَأَقَمْتَ لَهُمُ ٱلصَّلَوٰةَ فَلْتَقُمْ طَآئِفَةٌۭ مِّنْهُم مَّعَكَ وَلْيَأْخُذُوٓا۟ أَسْلِحَتَهُمْ فَإِذَا سَجَدُوا۟ فَلْيَكُونُوا۟ مِن وَرَآئِكُمْ وَلْتَأْتِ طَآئِفَةٌ أُخْرَىٰ لَمْ يُصَلُّوا۟ فَلْيُصَلُّوا۟ مَعَكَ وَلْيَأْخُذُوا۟ حِذْرَهُمْ وَأَسْلِحَتَهُمْ ۗ وَدَّ ٱلَّذِينَ كَفَرُوا۟ لَوْ تَغْفُلُونَ عَنْ أَسْلِحَتِكُمْ وَأَمْتِعَتِكُمْ فَيَمِيلُونَ عَلَيْكُم مَّيْلَةًۭ وَٰحِدَةًۭ ۚ وَلَا جُنَاحَ عَلَيْكُمْ إِن كَانَ بِكُمْ أَذًۭى مِّن مَّطَرٍ أَوْ كُنتُم مَّرْضَىٰٓ أَن تَضَعُوٓا۟ أَسْلِحَتَكُمْ ۖ وَخُذُوا۟ حِذْرَكُمْ ۗ إِنَّ ٱللَّهَ أَعَدَّ لِلْكَٰفِرِينَ عَذَابًۭا مُّهِينًۭا', 'وإذا كنت فيهم فأقمت لهم الصلوة فلتقم طائفة منهم معك وليأخذوا أسلحتهم فإذا سجدوا فليكونوا من ورائكم ولتأت طائفة أخرى لم يصلوا فليصلوا معك وليأخذوا حذرهم وأسلحتهم  ود الذين كفروا لو تغفلون عن أسلحتكم وأمتعتكم فيميلون عليكم ميلة وحدة  ولا جناح عليكم إن كان بكم أذى من مطر أو كنتم مرضى أن تضعوا أسلحتكم  وخذوا حذركم  إن الله أعد للكفرين عذابا مهينا', NULL, 95, 'local:hafs-text.json'),
  ('hafs-4-103', 'hafs', 4, 103, 'فَإِذَا قَضَيْتُمُ ٱلصَّلَوٰةَ فَٱذْكُرُوا۟ ٱللَّهَ قِيَٰمًۭا وَقُعُودًۭا وَعَلَىٰ جُنُوبِكُمْ ۚ فَإِذَا ٱطْمَأْنَنتُمْ فَأَقِيمُوا۟ ٱلصَّلَوٰةَ ۚ إِنَّ ٱلصَّلَوٰةَ كَانَتْ عَلَى ٱلْمُؤْمِنِينَ كِتَٰبًۭا مَّوْقُوتًۭا', 'فإذا قضيتم الصلوة فاذكروا الله قيما وقعودا وعلى جنوبكم  فإذا اطمأننتم فأقيموا الصلوة  إن الصلوة كانت على المؤمنين كتبا موقوتا', NULL, 95, 'local:hafs-text.json'),
  ('hafs-4-104', 'hafs', 4, 104, 'وَلَا تَهِنُوا۟ فِى ٱبْتِغَآءِ ٱلْقَوْمِ ۖ إِن تَكُونُوا۟ تَأْلَمُونَ فَإِنَّهُمْ يَأْلَمُونَ كَمَا تَأْلَمُونَ ۖ وَتَرْجُونَ مِنَ ٱللَّهِ مَا لَا يَرْجُونَ ۗ وَكَانَ ٱللَّهُ عَلِيمًا حَكِيمًا', 'ولا تهنوا فى ابتغاء القوم  إن تكونوا تألمون فإنهم يألمون كما تألمون  وترجون من الله ما لا يرجون  وكان الله عليما حكيما', NULL, 95, 'local:hafs-text.json'),
  ('hafs-4-105', 'hafs', 4, 105, 'إِنَّآ أَنزَلْنَآ إِلَيْكَ ٱلْكِتَٰبَ بِٱلْحَقِّ لِتَحْكُمَ بَيْنَ ٱلنَّاسِ بِمَآ أَرَىٰكَ ٱللَّهُ ۚ وَلَا تَكُن لِّلْخَآئِنِينَ خَصِيمًۭا', 'إنا أنزلنا إليك الكتب بالحق لتحكم بين الناس بما أرىك الله  ولا تكن للخائنين خصيما', NULL, 95, 'local:hafs-text.json'),
  ('hafs-4-106', 'hafs', 4, 106, 'وَٱسْتَغْفِرِ ٱللَّهَ ۖ إِنَّ ٱللَّهَ كَانَ غَفُورًۭا رَّحِيمًۭا', 'واستغفر الله  إن الله كان غفورا رحيما', NULL, 96, 'local:hafs-text.json'),
  ('hafs-4-107', 'hafs', 4, 107, 'وَلَا تُجَٰدِلْ عَنِ ٱلَّذِينَ يَخْتَانُونَ أَنفُسَهُمْ ۚ إِنَّ ٱللَّهَ لَا يُحِبُّ مَن كَانَ خَوَّانًا أَثِيمًۭا', 'ولا تجدل عن الذين يختانون أنفسهم  إن الله لا يحب من كان خوانا أثيما', NULL, 96, 'local:hafs-text.json'),
  ('hafs-4-108', 'hafs', 4, 108, 'يَسْتَخْفُونَ مِنَ ٱلنَّاسِ وَلَا يَسْتَخْفُونَ مِنَ ٱللَّهِ وَهُوَ مَعَهُمْ إِذْ يُبَيِّتُونَ مَا لَا يَرْضَىٰ مِنَ ٱلْقَوْلِ ۚ وَكَانَ ٱللَّهُ بِمَا يَعْمَلُونَ مُحِيطًا', 'يستخفون من الناس ولا يستخفون من الله وهو معهم إذ يبيتون ما لا يرضى من القول  وكان الله بما يعملون محيطا', NULL, 96, 'local:hafs-text.json'),
  ('hafs-4-109', 'hafs', 4, 109, 'هَٰٓأَنتُمْ هَٰٓؤُلَآءِ جَٰدَلْتُمْ عَنْهُمْ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا فَمَن يُجَٰدِلُ ٱللَّهَ عَنْهُمْ يَوْمَ ٱلْقِيَٰمَةِ أَم مَّن يَكُونُ عَلَيْهِمْ وَكِيلًۭا', 'هأنتم هؤلاء جدلتم عنهم فى الحيوة الدنيا فمن يجدل الله عنهم يوم القيمة أم من يكون عليهم وكيلا', NULL, 96, 'local:hafs-text.json'),
  ('hafs-4-110', 'hafs', 4, 110, 'وَمَن يَعْمَلْ سُوٓءًا أَوْ يَظْلِمْ نَفْسَهُۥ ثُمَّ يَسْتَغْفِرِ ٱللَّهَ يَجِدِ ٱللَّهَ غَفُورًۭا رَّحِيمًۭا', 'ومن يعمل سوءا أو يظلم نفسه ثم يستغفر الله يجد الله غفورا رحيما', NULL, 96, 'local:hafs-text.json'),
  ('hafs-4-111', 'hafs', 4, 111, 'وَمَن يَكْسِبْ إِثْمًۭا فَإِنَّمَا يَكْسِبُهُۥ عَلَىٰ نَفْسِهِۦ ۚ وَكَانَ ٱللَّهُ عَلِيمًا حَكِيمًۭا', 'ومن يكسب إثما فإنما يكسبه على نفسه  وكان الله عليما حكيما', NULL, 96, 'local:hafs-text.json'),
  ('hafs-4-112', 'hafs', 4, 112, 'وَمَن يَكْسِبْ خَطِيٓـَٔةً أَوْ إِثْمًۭا ثُمَّ يَرْمِ بِهِۦ بَرِيٓـًۭٔا فَقَدِ ٱحْتَمَلَ بُهْتَٰنًۭا وَإِثْمًۭا مُّبِينًۭا', 'ومن يكسب خطية أو إثما ثم يرم به بريا فقد احتمل بهتنا وإثما مبينا', NULL, 96, 'local:hafs-text.json'),
  ('hafs-4-113', 'hafs', 4, 113, 'وَلَوْلَا فَضْلُ ٱللَّهِ عَلَيْكَ وَرَحْمَتُهُۥ لَهَمَّت طَّآئِفَةٌۭ مِّنْهُمْ أَن يُضِلُّوكَ وَمَا يُضِلُّونَ إِلَّآ أَنفُسَهُمْ ۖ وَمَا يَضُرُّونَكَ مِن شَىْءٍۢ ۚ وَأَنزَلَ ٱللَّهُ عَلَيْكَ ٱلْكِتَٰبَ وَٱلْحِكْمَةَ وَعَلَّمَكَ مَا لَمْ تَكُن تَعْلَمُ ۚ وَكَانَ فَضْلُ ٱللَّهِ عَلَيْكَ عَظِيمًۭا', 'ولولا فضل الله عليك ورحمته لهمت طائفة منهم أن يضلوك وما يضلون إلا أنفسهم  وما يضرونك من شىء  وأنزل الله عليك الكتب والحكمة وعلمك ما لم تكن تعلم  وكان فضل الله عليك عظيما', NULL, 96, 'local:hafs-text.json'),
  ('hafs-4-114', 'hafs', 4, 114, '۞ لَّا خَيْرَ فِى كَثِيرٍۢ مِّن نَّجْوَىٰهُمْ إِلَّا مَنْ أَمَرَ بِصَدَقَةٍ أَوْ مَعْرُوفٍ أَوْ إِصْلَٰحٍۭ بَيْنَ ٱلنَّاسِ ۚ وَمَن يَفْعَلْ ذَٰلِكَ ٱبْتِغَآءَ مَرْضَاتِ ٱللَّهِ فَسَوْفَ نُؤْتِيهِ أَجْرًا عَظِيمًۭا', 'لا خير فى كثير من نجوىهم إلا من أمر بصدقة أو معروف أو إصلح بين الناس  ومن يفعل ذلك ابتغاء مرضات الله فسوف نؤتيه أجرا عظيما', NULL, 97, 'local:hafs-text.json'),
  ('hafs-4-115', 'hafs', 4, 115, 'وَمَن يُشَاقِقِ ٱلرَّسُولَ مِنۢ بَعْدِ مَا تَبَيَّنَ لَهُ ٱلْهُدَىٰ وَيَتَّبِعْ غَيْرَ سَبِيلِ ٱلْمُؤْمِنِينَ نُوَلِّهِۦ مَا تَوَلَّىٰ وَنُصْلِهِۦ جَهَنَّمَ ۖ وَسَآءَتْ مَصِيرًا', 'ومن يشاقق الرسول من بعد ما تبين له الهدى ويتبع غير سبيل المؤمنين نوله ما تولى ونصله جهنم  وساءت مصيرا', NULL, 97, 'local:hafs-text.json'),
  ('hafs-4-116', 'hafs', 4, 116, 'إِنَّ ٱللَّهَ لَا يَغْفِرُ أَن يُشْرَكَ بِهِۦ وَيَغْفِرُ مَا دُونَ ذَٰلِكَ لِمَن يَشَآءُ ۚ وَمَن يُشْرِكْ بِٱللَّهِ فَقَدْ ضَلَّ ضَلَٰلًۢا بَعِيدًا', 'إن الله لا يغفر أن يشرك به ويغفر ما دون ذلك لمن يشاء  ومن يشرك بالله فقد ضل ضللا بعيدا', NULL, 97, 'local:hafs-text.json'),
  ('hafs-4-117', 'hafs', 4, 117, 'إِن يَدْعُونَ مِن دُونِهِۦٓ إِلَّآ إِنَٰثًۭا وَإِن يَدْعُونَ إِلَّا شَيْطَٰنًۭا مَّرِيدًۭا', 'إن يدعون من دونه إلا إنثا وإن يدعون إلا شيطنا مريدا', NULL, 97, 'local:hafs-text.json'),
  ('hafs-4-118', 'hafs', 4, 118, 'لَّعَنَهُ ٱللَّهُ ۘ وَقَالَ لَأَتَّخِذَنَّ مِنْ عِبَادِكَ نَصِيبًۭا مَّفْرُوضًۭا', 'لعنه الله  وقال لأتخذن من عبادك نصيبا مفروضا', NULL, 97, 'local:hafs-text.json'),
  ('hafs-4-119', 'hafs', 4, 119, 'وَلَأُضِلَّنَّهُمْ وَلَأُمَنِّيَنَّهُمْ وَلَءَامُرَنَّهُمْ فَلَيُبَتِّكُنَّ ءَاذَانَ ٱلْأَنْعَٰمِ وَلَءَامُرَنَّهُمْ فَلَيُغَيِّرُنَّ خَلْقَ ٱللَّهِ ۚ وَمَن يَتَّخِذِ ٱلشَّيْطَٰنَ وَلِيًّۭا مِّن دُونِ ٱللَّهِ فَقَدْ خَسِرَ خُسْرَانًۭا مُّبِينًۭا', 'ولأضلنهم ولأمنينهم ولءامرنهم فليبتكن ءاذان الأنعم ولءامرنهم فليغيرن خلق الله  ومن يتخذ الشيطن وليا من دون الله فقد خسر خسرانا مبينا', NULL, 97, 'local:hafs-text.json'),
  ('hafs-4-120', 'hafs', 4, 120, 'يَعِدُهُمْ وَيُمَنِّيهِمْ ۖ وَمَا يَعِدُهُمُ ٱلشَّيْطَٰنُ إِلَّا غُرُورًا', 'يعدهم ويمنيهم  وما يعدهم الشيطن إلا غرورا', NULL, 97, 'local:hafs-text.json'),
  ('hafs-4-121', 'hafs', 4, 121, 'أُو۟لَٰٓئِكَ مَأْوَىٰهُمْ جَهَنَّمُ وَلَا يَجِدُونَ عَنْهَا مَحِيصًۭا', 'أولئك مأوىهم جهنم ولا يجدون عنها محيصا', NULL, 97, 'local:hafs-text.json'),
  ('hafs-4-122', 'hafs', 4, 122, 'وَٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ سَنُدْخِلُهُمْ جَنَّٰتٍۢ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ خَٰلِدِينَ فِيهَآ أَبَدًۭا ۖ وَعْدَ ٱللَّهِ حَقًّۭا ۚ وَمَنْ أَصْدَقُ مِنَ ٱللَّهِ قِيلًۭا', 'والذين ءامنوا وعملوا الصلحت سندخلهم جنت تجرى من تحتها الأنهر خلدين فيها أبدا  وعد الله حقا  ومن أصدق من الله قيلا', NULL, 98, 'local:hafs-text.json'),
  ('hafs-4-123', 'hafs', 4, 123, 'لَّيْسَ بِأَمَانِيِّكُمْ وَلَآ أَمَانِىِّ أَهْلِ ٱلْكِتَٰبِ ۗ مَن يَعْمَلْ سُوٓءًۭا يُجْزَ بِهِۦ وَلَا يَجِدْ لَهُۥ مِن دُونِ ٱللَّهِ وَلِيًّۭا وَلَا نَصِيرًۭا', 'ليس بأمانيكم ولا أمانى أهل الكتب  من يعمل سوءا يجز به ولا يجد له من دون الله وليا ولا نصيرا', NULL, 98, 'local:hafs-text.json'),
  ('hafs-4-124', 'hafs', 4, 124, 'وَمَن يَعْمَلْ مِنَ ٱلصَّٰلِحَٰتِ مِن ذَكَرٍ أَوْ أُنثَىٰ وَهُوَ مُؤْمِنٌۭ فَأُو۟لَٰٓئِكَ يَدْخُلُونَ ٱلْجَنَّةَ وَلَا يُظْلَمُونَ نَقِيرًۭا', 'ومن يعمل من الصلحت من ذكر أو أنثى وهو مؤمن فأولئك يدخلون الجنة ولا يظلمون نقيرا', NULL, 98, 'local:hafs-text.json'),
  ('hafs-4-125', 'hafs', 4, 125, 'وَمَنْ أَحْسَنُ دِينًۭا مِّمَّنْ أَسْلَمَ وَجْهَهُۥ لِلَّهِ وَهُوَ مُحْسِنٌۭ وَٱتَّبَعَ مِلَّةَ إِبْرَٰهِيمَ حَنِيفًۭا ۗ وَٱتَّخَذَ ٱللَّهُ إِبْرَٰهِيمَ خَلِيلًۭا', 'ومن أحسن دينا ممن أسلم وجهه لله وهو محسن واتبع ملة إبرهيم حنيفا  واتخذ الله إبرهيم خليلا', NULL, 98, 'local:hafs-text.json'),
  ('hafs-4-126', 'hafs', 4, 126, 'وَلِلَّهِ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ ۚ وَكَانَ ٱللَّهُ بِكُلِّ شَىْءٍۢ مُّحِيطًۭا', 'ولله ما فى السموت وما فى الأرض  وكان الله بكل شىء محيطا', NULL, 98, 'local:hafs-text.json'),
  ('hafs-4-127', 'hafs', 4, 127, 'وَيَسْتَفْتُونَكَ فِى ٱلنِّسَآءِ ۖ قُلِ ٱللَّهُ يُفْتِيكُمْ فِيهِنَّ وَمَا يُتْلَىٰ عَلَيْكُمْ فِى ٱلْكِتَٰبِ فِى يَتَٰمَى ٱلنِّسَآءِ ٱلَّٰتِى لَا تُؤْتُونَهُنَّ مَا كُتِبَ لَهُنَّ وَتَرْغَبُونَ أَن تَنكِحُوهُنَّ وَٱلْمُسْتَضْعَفِينَ مِنَ ٱلْوِلْدَٰنِ وَأَن تَقُومُوا۟ لِلْيَتَٰمَىٰ بِٱلْقِسْطِ ۚ وَمَا تَفْعَلُوا۟ مِنْ خَيْرٍۢ فَإِنَّ ٱللَّهَ كَانَ بِهِۦ عَلِيمًۭا', 'ويستفتونك فى النساء  قل الله يفتيكم فيهن وما يتلى عليكم فى الكتب فى يتمى النساء التى لا تؤتونهن ما كتب لهن وترغبون أن تنكحوهن والمستضعفين من الولدن وأن تقوموا لليتمى بالقسط  وما تفعلوا من خير فإن الله كان به عليما', NULL, 98, 'local:hafs-text.json'),
  ('hafs-4-128', 'hafs', 4, 128, 'وَإِنِ ٱمْرَأَةٌ خَافَتْ مِنۢ بَعْلِهَا نُشُوزًا أَوْ إِعْرَاضًۭا فَلَا جُنَاحَ عَلَيْهِمَآ أَن يُصْلِحَا بَيْنَهُمَا صُلْحًۭا ۚ وَٱلصُّلْحُ خَيْرٌۭ ۗ وَأُحْضِرَتِ ٱلْأَنفُسُ ٱلشُّحَّ ۚ وَإِن تُحْسِنُوا۟ وَتَتَّقُوا۟ فَإِنَّ ٱللَّهَ كَانَ بِمَا تَعْمَلُونَ خَبِيرًۭا', 'وإن امرأة خافت من بعلها نشوزا أو إعراضا فلا جناح عليهما أن يصلحا بينهما صلحا  والصلح خير  وأحضرت الأنفس الشح  وإن تحسنوا وتتقوا فإن الله كان بما تعملون خبيرا', NULL, 99, 'local:hafs-text.json'),
  ('hafs-4-129', 'hafs', 4, 129, 'وَلَن تَسْتَطِيعُوٓا۟ أَن تَعْدِلُوا۟ بَيْنَ ٱلنِّسَآءِ وَلَوْ حَرَصْتُمْ ۖ فَلَا تَمِيلُوا۟ كُلَّ ٱلْمَيْلِ فَتَذَرُوهَا كَٱلْمُعَلَّقَةِ ۚ وَإِن تُصْلِحُوا۟ وَتَتَّقُوا۟ فَإِنَّ ٱللَّهَ كَانَ غَفُورًۭا رَّحِيمًۭا', 'ولن تستطيعوا أن تعدلوا بين النساء ولو حرصتم  فلا تميلوا كل الميل فتذروها كالمعلقة  وإن تصلحوا وتتقوا فإن الله كان غفورا رحيما', NULL, 99, 'local:hafs-text.json'),
  ('hafs-4-130', 'hafs', 4, 130, 'وَإِن يَتَفَرَّقَا يُغْنِ ٱللَّهُ كُلًّۭا مِّن سَعَتِهِۦ ۚ وَكَانَ ٱللَّهُ وَٰسِعًا حَكِيمًۭا', 'وإن يتفرقا يغن الله كلا من سعته  وكان الله وسعا حكيما', NULL, 99, 'local:hafs-text.json'),
  ('hafs-4-131', 'hafs', 4, 131, 'وَلِلَّهِ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ ۗ وَلَقَدْ وَصَّيْنَا ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَٰبَ مِن قَبْلِكُمْ وَإِيَّاكُمْ أَنِ ٱتَّقُوا۟ ٱللَّهَ ۚ وَإِن تَكْفُرُوا۟ فَإِنَّ لِلَّهِ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ ۚ وَكَانَ ٱللَّهُ غَنِيًّا حَمِيدًۭا', 'ولله ما فى السموت وما فى الأرض  ولقد وصينا الذين أوتوا الكتب من قبلكم وإياكم أن اتقوا الله  وإن تكفروا فإن لله ما فى السموت وما فى الأرض  وكان الله غنيا حميدا', NULL, 99, 'local:hafs-text.json'),
  ('hafs-4-132', 'hafs', 4, 132, 'وَلِلَّهِ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ ۚ وَكَفَىٰ بِٱللَّهِ وَكِيلًا', 'ولله ما فى السموت وما فى الأرض  وكفى بالله وكيلا', NULL, 99, 'local:hafs-text.json'),
  ('hafs-4-133', 'hafs', 4, 133, 'إِن يَشَأْ يُذْهِبْكُمْ أَيُّهَا ٱلنَّاسُ وَيَأْتِ بِـَٔاخَرِينَ ۚ وَكَانَ ٱللَّهُ عَلَىٰ ذَٰلِكَ قَدِيرًۭا', 'إن يشأ يذهبكم أيها الناس ويأت باخرين  وكان الله على ذلك قديرا', NULL, 99, 'local:hafs-text.json'),
  ('hafs-4-134', 'hafs', 4, 134, 'مَّن كَانَ يُرِيدُ ثَوَابَ ٱلدُّنْيَا فَعِندَ ٱللَّهِ ثَوَابُ ٱلدُّنْيَا وَٱلْءَاخِرَةِ ۚ وَكَانَ ٱللَّهُ سَمِيعًۢا بَصِيرًۭا', 'من كان يريد ثواب الدنيا فعند الله ثواب الدنيا والءاخرة  وكان الله سميعا بصيرا', NULL, 99, 'local:hafs-text.json'),
  ('hafs-4-135', 'hafs', 4, 135, '۞ يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ كُونُوا۟ قَوَّٰمِينَ بِٱلْقِسْطِ شُهَدَآءَ لِلَّهِ وَلَوْ عَلَىٰٓ أَنفُسِكُمْ أَوِ ٱلْوَٰلِدَيْنِ وَٱلْأَقْرَبِينَ ۚ إِن يَكُنْ غَنِيًّا أَوْ فَقِيرًۭا فَٱللَّهُ أَوْلَىٰ بِهِمَا ۖ فَلَا تَتَّبِعُوا۟ ٱلْهَوَىٰٓ أَن تَعْدِلُوا۟ ۚ وَإِن تَلْوُۥٓا۟ أَوْ تُعْرِضُوا۟ فَإِنَّ ٱللَّهَ كَانَ بِمَا تَعْمَلُونَ خَبِيرًۭا', 'يأيها الذين ءامنوا كونوا قومين بالقسط شهداء لله ولو على أنفسكم أو الولدين والأقربين  إن يكن غنيا أو فقيرا فالله أولى بهما  فلا تتبعوا الهوى أن تعدلوا  وإن تلوا أو تعرضوا فإن الله كان بما تعملون خبيرا', NULL, 100, 'local:hafs-text.json'),
  ('hafs-4-136', 'hafs', 4, 136, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ ءَامِنُوا۟ بِٱللَّهِ وَرَسُولِهِۦ وَٱلْكِتَٰبِ ٱلَّذِى نَزَّلَ عَلَىٰ رَسُولِهِۦ وَٱلْكِتَٰبِ ٱلَّذِىٓ أَنزَلَ مِن قَبْلُ ۚ وَمَن يَكْفُرْ بِٱللَّهِ وَمَلَٰٓئِكَتِهِۦ وَكُتُبِهِۦ وَرُسُلِهِۦ وَٱلْيَوْمِ ٱلْءَاخِرِ فَقَدْ ضَلَّ ضَلَٰلًۢا بَعِيدًا', 'يأيها الذين ءامنوا ءامنوا بالله ورسوله والكتب الذى نزل على رسوله والكتب الذى أنزل من قبل  ومن يكفر بالله وملئكته وكتبه ورسله واليوم الءاخر فقد ضل ضللا بعيدا', NULL, 100, 'local:hafs-text.json'),
  ('hafs-4-137', 'hafs', 4, 137, 'إِنَّ ٱلَّذِينَ ءَامَنُوا۟ ثُمَّ كَفَرُوا۟ ثُمَّ ءَامَنُوا۟ ثُمَّ كَفَرُوا۟ ثُمَّ ٱزْدَادُوا۟ كُفْرًۭا لَّمْ يَكُنِ ٱللَّهُ لِيَغْفِرَ لَهُمْ وَلَا لِيَهْدِيَهُمْ سَبِيلًۢا', 'إن الذين ءامنوا ثم كفروا ثم ءامنوا ثم كفروا ثم ازدادوا كفرا لم يكن الله ليغفر لهم ولا ليهديهم سبيلا', NULL, 100, 'local:hafs-text.json'),
  ('hafs-4-138', 'hafs', 4, 138, 'بَشِّرِ ٱلْمُنَٰفِقِينَ بِأَنَّ لَهُمْ عَذَابًا أَلِيمًا', 'بشر المنفقين بأن لهم عذابا أليما', NULL, 100, 'local:hafs-text.json'),
  ('hafs-4-139', 'hafs', 4, 139, 'ٱلَّذِينَ يَتَّخِذُونَ ٱلْكَٰفِرِينَ أَوْلِيَآءَ مِن دُونِ ٱلْمُؤْمِنِينَ ۚ أَيَبْتَغُونَ عِندَهُمُ ٱلْعِزَّةَ فَإِنَّ ٱلْعِزَّةَ لِلَّهِ جَمِيعًۭا', 'الذين يتخذون الكفرين أولياء من دون المؤمنين  أيبتغون عندهم العزة فإن العزة لله جميعا', NULL, 100, 'local:hafs-text.json'),
  ('hafs-4-140', 'hafs', 4, 140, 'وَقَدْ نَزَّلَ عَلَيْكُمْ فِى ٱلْكِتَٰبِ أَنْ إِذَا سَمِعْتُمْ ءَايَٰتِ ٱللَّهِ يُكْفَرُ بِهَا وَيُسْتَهْزَأُ بِهَا فَلَا تَقْعُدُوا۟ مَعَهُمْ حَتَّىٰ يَخُوضُوا۟ فِى حَدِيثٍ غَيْرِهِۦٓ ۚ إِنَّكُمْ إِذًۭا مِّثْلُهُمْ ۗ إِنَّ ٱللَّهَ جَامِعُ ٱلْمُنَٰفِقِينَ وَٱلْكَٰفِرِينَ فِى جَهَنَّمَ جَمِيعًا', 'وقد نزل عليكم فى الكتب أن إذا سمعتم ءايت الله يكفر بها ويستهزأ بها فلا تقعدوا معهم حتى يخوضوا فى حديث غيره  إنكم إذا مثلهم  إن الله جامع المنفقين والكفرين فى جهنم جميعا', NULL, 100, 'local:hafs-text.json'),
  ('hafs-4-141', 'hafs', 4, 141, 'ٱلَّذِينَ يَتَرَبَّصُونَ بِكُمْ فَإِن كَانَ لَكُمْ فَتْحٌۭ مِّنَ ٱللَّهِ قَالُوٓا۟ أَلَمْ نَكُن مَّعَكُمْ وَإِن كَانَ لِلْكَٰفِرِينَ نَصِيبٌۭ قَالُوٓا۟ أَلَمْ نَسْتَحْوِذْ عَلَيْكُمْ وَنَمْنَعْكُم مِّنَ ٱلْمُؤْمِنِينَ ۚ فَٱللَّهُ يَحْكُمُ بَيْنَكُمْ يَوْمَ ٱلْقِيَٰمَةِ ۗ وَلَن يَجْعَلَ ٱللَّهُ لِلْكَٰفِرِينَ عَلَى ٱلْمُؤْمِنِينَ سَبِيلًا', 'الذين يتربصون بكم فإن كان لكم فتح من الله قالوا ألم نكن معكم وإن كان للكفرين نصيب قالوا ألم نستحوذ عليكم ونمنعكم من المؤمنين  فالله يحكم بينكم يوم القيمة  ولن يجعل الله للكفرين على المؤمنين سبيلا', NULL, 101, 'local:hafs-text.json'),
  ('hafs-4-142', 'hafs', 4, 142, 'إِنَّ ٱلْمُنَٰفِقِينَ يُخَٰدِعُونَ ٱللَّهَ وَهُوَ خَٰدِعُهُمْ وَإِذَا قَامُوٓا۟ إِلَى ٱلصَّلَوٰةِ قَامُوا۟ كُسَالَىٰ يُرَآءُونَ ٱلنَّاسَ وَلَا يَذْكُرُونَ ٱللَّهَ إِلَّا قَلِيلًۭا', 'إن المنفقين يخدعون الله وهو خدعهم وإذا قاموا إلى الصلوة قاموا كسالى يراءون الناس ولا يذكرون الله إلا قليلا', NULL, 101, 'local:hafs-text.json'),
  ('hafs-4-143', 'hafs', 4, 143, 'مُّذَبْذَبِينَ بَيْنَ ذَٰلِكَ لَآ إِلَىٰ هَٰٓؤُلَآءِ وَلَآ إِلَىٰ هَٰٓؤُلَآءِ ۚ وَمَن يُضْلِلِ ٱللَّهُ فَلَن تَجِدَ لَهُۥ سَبِيلًۭا', 'مذبذبين بين ذلك لا إلى هؤلاء ولا إلى هؤلاء  ومن يضلل الله فلن تجد له سبيلا', NULL, 101, 'local:hafs-text.json'),
  ('hafs-4-144', 'hafs', 4, 144, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَتَّخِذُوا۟ ٱلْكَٰفِرِينَ أَوْلِيَآءَ مِن دُونِ ٱلْمُؤْمِنِينَ ۚ أَتُرِيدُونَ أَن تَجْعَلُوا۟ لِلَّهِ عَلَيْكُمْ سُلْطَٰنًۭا مُّبِينًا', 'يأيها الذين ءامنوا لا تتخذوا الكفرين أولياء من دون المؤمنين  أتريدون أن تجعلوا لله عليكم سلطنا مبينا', NULL, 101, 'local:hafs-text.json'),
  ('hafs-4-145', 'hafs', 4, 145, 'إِنَّ ٱلْمُنَٰفِقِينَ فِى ٱلدَّرْكِ ٱلْأَسْفَلِ مِنَ ٱلنَّارِ وَلَن تَجِدَ لَهُمْ نَصِيرًا', 'إن المنفقين فى الدرك الأسفل من النار ولن تجد لهم نصيرا', NULL, 101, 'local:hafs-text.json'),
  ('hafs-4-146', 'hafs', 4, 146, 'إِلَّا ٱلَّذِينَ تَابُوا۟ وَأَصْلَحُوا۟ وَٱعْتَصَمُوا۟ بِٱللَّهِ وَأَخْلَصُوا۟ دِينَهُمْ لِلَّهِ فَأُو۟لَٰٓئِكَ مَعَ ٱلْمُؤْمِنِينَ ۖ وَسَوْفَ يُؤْتِ ٱللَّهُ ٱلْمُؤْمِنِينَ أَجْرًا عَظِيمًۭا', 'إلا الذين تابوا وأصلحوا واعتصموا بالله وأخلصوا دينهم لله فأولئك مع المؤمنين  وسوف يؤت الله المؤمنين أجرا عظيما', NULL, 101, 'local:hafs-text.json'),
  ('hafs-4-147', 'hafs', 4, 147, 'مَّا يَفْعَلُ ٱللَّهُ بِعَذَابِكُمْ إِن شَكَرْتُمْ وَءَامَنتُمْ ۚ وَكَانَ ٱللَّهُ شَاكِرًا عَلِيمًۭا', 'ما يفعل الله بعذابكم إن شكرتم وءامنتم  وكان الله شاكرا عليما', NULL, 101, 'local:hafs-text.json'),
  ('hafs-4-148', 'hafs', 4, 148, '۞ لَّا يُحِبُّ ٱللَّهُ ٱلْجَهْرَ بِٱلسُّوٓءِ مِنَ ٱلْقَوْلِ إِلَّا مَن ظُلِمَ ۚ وَكَانَ ٱللَّهُ سَمِيعًا عَلِيمًا', 'لا يحب الله الجهر بالسوء من القول إلا من ظلم  وكان الله سميعا عليما', NULL, 102, 'local:hafs-text.json'),
  ('hafs-4-149', 'hafs', 4, 149, 'إِن تُبْدُوا۟ خَيْرًا أَوْ تُخْفُوهُ أَوْ تَعْفُوا۟ عَن سُوٓءٍۢ فَإِنَّ ٱللَّهَ كَانَ عَفُوًّۭا قَدِيرًا', 'إن تبدوا خيرا أو تخفوه أو تعفوا عن سوء فإن الله كان عفوا قديرا', NULL, 102, 'local:hafs-text.json'),
  ('hafs-4-150', 'hafs', 4, 150, 'إِنَّ ٱلَّذِينَ يَكْفُرُونَ بِٱللَّهِ وَرُسُلِهِۦ وَيُرِيدُونَ أَن يُفَرِّقُوا۟ بَيْنَ ٱللَّهِ وَرُسُلِهِۦ وَيَقُولُونَ نُؤْمِنُ بِبَعْضٍۢ وَنَكْفُرُ بِبَعْضٍۢ وَيُرِيدُونَ أَن يَتَّخِذُوا۟ بَيْنَ ذَٰلِكَ سَبِيلًا', 'إن الذين يكفرون بالله ورسله ويريدون أن يفرقوا بين الله ورسله ويقولون نؤمن ببعض ونكفر ببعض ويريدون أن يتخذوا بين ذلك سبيلا', NULL, 102, 'local:hafs-text.json'),
  ('hafs-4-151', 'hafs', 4, 151, 'أُو۟لَٰٓئِكَ هُمُ ٱلْكَٰفِرُونَ حَقًّۭا ۚ وَأَعْتَدْنَا لِلْكَٰفِرِينَ عَذَابًۭا مُّهِينًۭا', 'أولئك هم الكفرون حقا  وأعتدنا للكفرين عذابا مهينا', NULL, 102, 'local:hafs-text.json'),
  ('hafs-4-152', 'hafs', 4, 152, 'وَٱلَّذِينَ ءَامَنُوا۟ بِٱللَّهِ وَرُسُلِهِۦ وَلَمْ يُفَرِّقُوا۟ بَيْنَ أَحَدٍۢ مِّنْهُمْ أُو۟لَٰٓئِكَ سَوْفَ يُؤْتِيهِمْ أُجُورَهُمْ ۗ وَكَانَ ٱللَّهُ غَفُورًۭا رَّحِيمًۭا', 'والذين ءامنوا بالله ورسله ولم يفرقوا بين أحد منهم أولئك سوف يؤتيهم أجورهم  وكان الله غفورا رحيما', NULL, 102, 'local:hafs-text.json'),
  ('hafs-4-153', 'hafs', 4, 153, 'يَسْـَٔلُكَ أَهْلُ ٱلْكِتَٰبِ أَن تُنَزِّلَ عَلَيْهِمْ كِتَٰبًۭا مِّنَ ٱلسَّمَآءِ ۚ فَقَدْ سَأَلُوا۟ مُوسَىٰٓ أَكْبَرَ مِن ذَٰلِكَ فَقَالُوٓا۟ أَرِنَا ٱللَّهَ جَهْرَةًۭ فَأَخَذَتْهُمُ ٱلصَّٰعِقَةُ بِظُلْمِهِمْ ۚ ثُمَّ ٱتَّخَذُوا۟ ٱلْعِجْلَ مِنۢ بَعْدِ مَا جَآءَتْهُمُ ٱلْبَيِّنَٰتُ فَعَفَوْنَا عَن ذَٰلِكَ ۚ وَءَاتَيْنَا مُوسَىٰ سُلْطَٰنًۭا مُّبِينًۭا', 'يسلك أهل الكتب أن تنزل عليهم كتبا من السماء  فقد سألوا موسى أكبر من ذلك فقالوا أرنا الله جهرة فأخذتهم الصعقة بظلمهم  ثم اتخذوا العجل من بعد ما جاءتهم البينت فعفونا عن ذلك  وءاتينا موسى سلطنا مبينا', NULL, 102, 'local:hafs-text.json'),
  ('hafs-4-154', 'hafs', 4, 154, 'وَرَفَعْنَا فَوْقَهُمُ ٱلطُّورَ بِمِيثَٰقِهِمْ وَقُلْنَا لَهُمُ ٱدْخُلُوا۟ ٱلْبَابَ سُجَّدًۭا وَقُلْنَا لَهُمْ لَا تَعْدُوا۟ فِى ٱلسَّبْتِ وَأَخَذْنَا مِنْهُم مِّيثَٰقًا غَلِيظًۭا', 'ورفعنا فوقهم الطور بميثقهم وقلنا لهم ادخلوا الباب سجدا وقلنا لهم لا تعدوا فى السبت وأخذنا منهم ميثقا غليظا', NULL, 102, 'local:hafs-text.json'),
  ('hafs-4-155', 'hafs', 4, 155, 'فَبِمَا نَقْضِهِم مِّيثَٰقَهُمْ وَكُفْرِهِم بِـَٔايَٰتِ ٱللَّهِ وَقَتْلِهِمُ ٱلْأَنۢبِيَآءَ بِغَيْرِ حَقٍّۢ وَقَوْلِهِمْ قُلُوبُنَا غُلْفٌۢ ۚ بَلْ طَبَعَ ٱللَّهُ عَلَيْهَا بِكُفْرِهِمْ فَلَا يُؤْمِنُونَ إِلَّا قَلِيلًۭا', 'فبما نقضهم ميثقهم وكفرهم بايت الله وقتلهم الأنبياء بغير حق وقولهم قلوبنا غلف  بل طبع الله عليها بكفرهم فلا يؤمنون إلا قليلا', NULL, 103, 'local:hafs-text.json'),
  ('hafs-4-156', 'hafs', 4, 156, 'وَبِكُفْرِهِمْ وَقَوْلِهِمْ عَلَىٰ مَرْيَمَ بُهْتَٰنًا عَظِيمًۭا', 'وبكفرهم وقولهم على مريم بهتنا عظيما', NULL, 103, 'local:hafs-text.json'),
  ('hafs-4-157', 'hafs', 4, 157, 'وَقَوْلِهِمْ إِنَّا قَتَلْنَا ٱلْمَسِيحَ عِيسَى ٱبْنَ مَرْيَمَ رَسُولَ ٱللَّهِ وَمَا قَتَلُوهُ وَمَا صَلَبُوهُ وَلَٰكِن شُبِّهَ لَهُمْ ۚ وَإِنَّ ٱلَّذِينَ ٱخْتَلَفُوا۟ فِيهِ لَفِى شَكٍّۢ مِّنْهُ ۚ مَا لَهُم بِهِۦ مِنْ عِلْمٍ إِلَّا ٱتِّبَاعَ ٱلظَّنِّ ۚ وَمَا قَتَلُوهُ يَقِينًۢا', 'وقولهم إنا قتلنا المسيح عيسى ابن مريم رسول الله وما قتلوه وما صلبوه ولكن شبه لهم  وإن الذين اختلفوا فيه لفى شك منه  ما لهم به من علم إلا اتباع الظن  وما قتلوه يقينا', NULL, 103, 'local:hafs-text.json'),
  ('hafs-4-158', 'hafs', 4, 158, 'بَل رَّفَعَهُ ٱللَّهُ إِلَيْهِ ۚ وَكَانَ ٱللَّهُ عَزِيزًا حَكِيمًۭا', 'بل رفعه الله إليه  وكان الله عزيزا حكيما', NULL, 103, 'local:hafs-text.json'),
  ('hafs-4-159', 'hafs', 4, 159, 'وَإِن مِّنْ أَهْلِ ٱلْكِتَٰبِ إِلَّا لَيُؤْمِنَنَّ بِهِۦ قَبْلَ مَوْتِهِۦ ۖ وَيَوْمَ ٱلْقِيَٰمَةِ يَكُونُ عَلَيْهِمْ شَهِيدًۭا', 'وإن من أهل الكتب إلا ليؤمنن به قبل موته  ويوم القيمة يكون عليهم شهيدا', NULL, 103, 'local:hafs-text.json'),
  ('hafs-4-160', 'hafs', 4, 160, 'فَبِظُلْمٍۢ مِّنَ ٱلَّذِينَ هَادُوا۟ حَرَّمْنَا عَلَيْهِمْ طَيِّبَٰتٍ أُحِلَّتْ لَهُمْ وَبِصَدِّهِمْ عَن سَبِيلِ ٱللَّهِ كَثِيرًۭا', 'فبظلم من الذين هادوا حرمنا عليهم طيبت أحلت لهم وبصدهم عن سبيل الله كثيرا', NULL, 103, 'local:hafs-text.json'),
  ('hafs-4-161', 'hafs', 4, 161, 'وَأَخْذِهِمُ ٱلرِّبَوٰا۟ وَقَدْ نُهُوا۟ عَنْهُ وَأَكْلِهِمْ أَمْوَٰلَ ٱلنَّاسِ بِٱلْبَٰطِلِ ۚ وَأَعْتَدْنَا لِلْكَٰفِرِينَ مِنْهُمْ عَذَابًا أَلِيمًۭا', 'وأخذهم الربوا وقد نهوا عنه وأكلهم أمول الناس بالبطل  وأعتدنا للكفرين منهم عذابا أليما', NULL, 103, 'local:hafs-text.json'),
  ('hafs-4-162', 'hafs', 4, 162, 'لَّٰكِنِ ٱلرَّٰسِخُونَ فِى ٱلْعِلْمِ مِنْهُمْ وَٱلْمُؤْمِنُونَ يُؤْمِنُونَ بِمَآ أُنزِلَ إِلَيْكَ وَمَآ أُنزِلَ مِن قَبْلِكَ ۚ وَٱلْمُقِيمِينَ ٱلصَّلَوٰةَ ۚ وَٱلْمُؤْتُونَ ٱلزَّكَوٰةَ وَٱلْمُؤْمِنُونَ بِٱللَّهِ وَٱلْيَوْمِ ٱلْءَاخِرِ أُو۟لَٰٓئِكَ سَنُؤْتِيهِمْ أَجْرًا عَظِيمًا', 'لكن الرسخون فى العلم منهم والمؤمنون يؤمنون بما أنزل إليك وما أنزل من قبلك  والمقيمين الصلوة  والمؤتون الزكوة والمؤمنون بالله واليوم الءاخر أولئك سنؤتيهم أجرا عظيما', NULL, 103, 'local:hafs-text.json'),
  ('hafs-4-163', 'hafs', 4, 163, '۞ إِنَّآ أَوْحَيْنَآ إِلَيْكَ كَمَآ أَوْحَيْنَآ إِلَىٰ نُوحٍۢ وَٱلنَّبِيِّۦنَ مِنۢ بَعْدِهِۦ ۚ وَأَوْحَيْنَآ إِلَىٰٓ إِبْرَٰهِيمَ وَإِسْمَٰعِيلَ وَإِسْحَٰقَ وَيَعْقُوبَ وَٱلْأَسْبَاطِ وَعِيسَىٰ وَأَيُّوبَ وَيُونُسَ وَهَٰرُونَ وَسُلَيْمَٰنَ ۚ وَءَاتَيْنَا دَاوُۥدَ زَبُورًۭا', 'إنا أوحينا إليك كما أوحينا إلى نوح والنبين من بعده  وأوحينا إلى إبرهيم وإسمعيل وإسحق ويعقوب والأسباط وعيسى وأيوب ويونس وهرون وسليمن  وءاتينا داود زبورا', NULL, 104, 'local:hafs-text.json'),
  ('hafs-4-164', 'hafs', 4, 164, 'وَرُسُلًۭا قَدْ قَصَصْنَٰهُمْ عَلَيْكَ مِن قَبْلُ وَرُسُلًۭا لَّمْ نَقْصُصْهُمْ عَلَيْكَ ۚ وَكَلَّمَ ٱللَّهُ مُوسَىٰ تَكْلِيمًۭا', 'ورسلا قد قصصنهم عليك من قبل ورسلا لم نقصصهم عليك  وكلم الله موسى تكليما', NULL, 104, 'local:hafs-text.json'),
  ('hafs-4-165', 'hafs', 4, 165, 'رُّسُلًۭا مُّبَشِّرِينَ وَمُنذِرِينَ لِئَلَّا يَكُونَ لِلنَّاسِ عَلَى ٱللَّهِ حُجَّةٌۢ بَعْدَ ٱلرُّسُلِ ۚ وَكَانَ ٱللَّهُ عَزِيزًا حَكِيمًۭا', 'رسلا مبشرين ومنذرين لئلا يكون للناس على الله حجة بعد الرسل  وكان الله عزيزا حكيما', NULL, 104, 'local:hafs-text.json'),
  ('hafs-4-166', 'hafs', 4, 166, 'لَّٰكِنِ ٱللَّهُ يَشْهَدُ بِمَآ أَنزَلَ إِلَيْكَ ۖ أَنزَلَهُۥ بِعِلْمِهِۦ ۖ وَٱلْمَلَٰٓئِكَةُ يَشْهَدُونَ ۚ وَكَفَىٰ بِٱللَّهِ شَهِيدًا', 'لكن الله يشهد بما أنزل إليك  أنزله بعلمه  والملئكة يشهدون  وكفى بالله شهيدا', NULL, 104, 'local:hafs-text.json'),
  ('hafs-4-167', 'hafs', 4, 167, 'إِنَّ ٱلَّذِينَ كَفَرُوا۟ وَصَدُّوا۟ عَن سَبِيلِ ٱللَّهِ قَدْ ضَلُّوا۟ ضَلَٰلًۢا بَعِيدًا', 'إن الذين كفروا وصدوا عن سبيل الله قد ضلوا ضللا بعيدا', NULL, 104, 'local:hafs-text.json'),
  ('hafs-4-168', 'hafs', 4, 168, 'إِنَّ ٱلَّذِينَ كَفَرُوا۟ وَظَلَمُوا۟ لَمْ يَكُنِ ٱللَّهُ لِيَغْفِرَ لَهُمْ وَلَا لِيَهْدِيَهُمْ طَرِيقًا', 'إن الذين كفروا وظلموا لم يكن الله ليغفر لهم ولا ليهديهم طريقا', NULL, 104, 'local:hafs-text.json'),
  ('hafs-4-169', 'hafs', 4, 169, 'إِلَّا طَرِيقَ جَهَنَّمَ خَٰلِدِينَ فِيهَآ أَبَدًۭا ۚ وَكَانَ ذَٰلِكَ عَلَى ٱللَّهِ يَسِيرًۭا', 'إلا طريق جهنم خلدين فيها أبدا  وكان ذلك على الله يسيرا', NULL, 104, 'local:hafs-text.json'),
  ('hafs-4-170', 'hafs', 4, 170, 'يَٰٓأَيُّهَا ٱلنَّاسُ قَدْ جَآءَكُمُ ٱلرَّسُولُ بِٱلْحَقِّ مِن رَّبِّكُمْ فَـَٔامِنُوا۟ خَيْرًۭا لَّكُمْ ۚ وَإِن تَكْفُرُوا۟ فَإِنَّ لِلَّهِ مَا فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ ۚ وَكَانَ ٱللَّهُ عَلِيمًا حَكِيمًۭا', 'يأيها الناس قد جاءكم الرسول بالحق من ربكم فامنوا خيرا لكم  وإن تكفروا فإن لله ما فى السموت والأرض  وكان الله عليما حكيما', NULL, 104, 'local:hafs-text.json'),
  ('hafs-4-171', 'hafs', 4, 171, 'يَٰٓأَهْلَ ٱلْكِتَٰبِ لَا تَغْلُوا۟ فِى دِينِكُمْ وَلَا تَقُولُوا۟ عَلَى ٱللَّهِ إِلَّا ٱلْحَقَّ ۚ إِنَّمَا ٱلْمَسِيحُ عِيسَى ٱبْنُ مَرْيَمَ رَسُولُ ٱللَّهِ وَكَلِمَتُهُۥٓ أَلْقَىٰهَآ إِلَىٰ مَرْيَمَ وَرُوحٌۭ مِّنْهُ ۖ فَـَٔامِنُوا۟ بِٱللَّهِ وَرُسُلِهِۦ ۖ وَلَا تَقُولُوا۟ ثَلَٰثَةٌ ۚ ٱنتَهُوا۟ خَيْرًۭا لَّكُمْ ۚ إِنَّمَا ٱللَّهُ إِلَٰهٌۭ وَٰحِدٌۭ ۖ سُبْحَٰنَهُۥٓ أَن يَكُونَ لَهُۥ وَلَدٌۭ ۘ لَّهُۥ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ ۗ وَكَفَىٰ بِٱللَّهِ وَكِيلًۭا', 'يأهل الكتب لا تغلوا فى دينكم ولا تقولوا على الله إلا الحق  إنما المسيح عيسى ابن مريم رسول الله وكلمته ألقىها إلى مريم وروح منه  فامنوا بالله ورسله  ولا تقولوا ثلثة  انتهوا خيرا لكم  إنما الله إله وحد  سبحنه أن يكون له ولد  له ما فى السموت وما فى الأرض  وكفى بالله وكيلا', NULL, 105, 'local:hafs-text.json'),
  ('hafs-4-172', 'hafs', 4, 172, 'لَّن يَسْتَنكِفَ ٱلْمَسِيحُ أَن يَكُونَ عَبْدًۭا لِّلَّهِ وَلَا ٱلْمَلَٰٓئِكَةُ ٱلْمُقَرَّبُونَ ۚ وَمَن يَسْتَنكِفْ عَنْ عِبَادَتِهِۦ وَيَسْتَكْبِرْ فَسَيَحْشُرُهُمْ إِلَيْهِ جَمِيعًۭا', 'لن يستنكف المسيح أن يكون عبدا لله ولا الملئكة المقربون  ومن يستنكف عن عبادته ويستكبر فسيحشرهم إليه جميعا', NULL, 105, 'local:hafs-text.json'),
  ('hafs-4-173', 'hafs', 4, 173, 'فَأَمَّا ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ فَيُوَفِّيهِمْ أُجُورَهُمْ وَيَزِيدُهُم مِّن فَضْلِهِۦ ۖ وَأَمَّا ٱلَّذِينَ ٱسْتَنكَفُوا۟ وَٱسْتَكْبَرُوا۟ فَيُعَذِّبُهُمْ عَذَابًا أَلِيمًۭا وَلَا يَجِدُونَ لَهُم مِّن دُونِ ٱللَّهِ وَلِيًّۭا وَلَا نَصِيرًۭا', 'فأما الذين ءامنوا وعملوا الصلحت فيوفيهم أجورهم ويزيدهم من فضله  وأما الذين استنكفوا واستكبروا فيعذبهم عذابا أليما ولا يجدون لهم من دون الله وليا ولا نصيرا', NULL, 105, 'local:hafs-text.json'),
  ('hafs-4-174', 'hafs', 4, 174, 'يَٰٓأَيُّهَا ٱلنَّاسُ قَدْ جَآءَكُم بُرْهَٰنٌۭ مِّن رَّبِّكُمْ وَأَنزَلْنَآ إِلَيْكُمْ نُورًۭا مُّبِينًۭا', 'يأيها الناس قد جاءكم برهن من ربكم وأنزلنا إليكم نورا مبينا', NULL, 105, 'local:hafs-text.json'),
  ('hafs-4-175', 'hafs', 4, 175, 'فَأَمَّا ٱلَّذِينَ ءَامَنُوا۟ بِٱللَّهِ وَٱعْتَصَمُوا۟ بِهِۦ فَسَيُدْخِلُهُمْ فِى رَحْمَةٍۢ مِّنْهُ وَفَضْلٍۢ وَيَهْدِيهِمْ إِلَيْهِ صِرَٰطًۭا مُّسْتَقِيمًۭا', 'فأما الذين ءامنوا بالله واعتصموا به فسيدخلهم فى رحمة منه وفضل ويهديهم إليه صرطا مستقيما', NULL, 105, 'local:hafs-text.json'),
  ('hafs-4-176', 'hafs', 4, 176, 'يَسْتَفْتُونَكَ قُلِ ٱللَّهُ يُفْتِيكُمْ فِى ٱلْكَلَٰلَةِ ۚ إِنِ ٱمْرُؤٌا۟ هَلَكَ لَيْسَ لَهُۥ وَلَدٌۭ وَلَهُۥٓ أُخْتٌۭ فَلَهَا نِصْفُ مَا تَرَكَ ۚ وَهُوَ يَرِثُهَآ إِن لَّمْ يَكُن لَّهَا وَلَدٌۭ ۚ فَإِن كَانَتَا ٱثْنَتَيْنِ فَلَهُمَا ٱلثُّلُثَانِ مِمَّا تَرَكَ ۚ وَإِن كَانُوٓا۟ إِخْوَةًۭ رِّجَالًۭا وَنِسَآءًۭ فَلِلذَّكَرِ مِثْلُ حَظِّ ٱلْأُنثَيَيْنِ ۗ يُبَيِّنُ ٱللَّهُ لَكُمْ أَن تَضِلُّوا۟ ۗ وَٱللَّهُ بِكُلِّ شَىْءٍ عَلِيمٌۢ', 'يستفتونك قل الله يفتيكم فى الكللة  إن امرؤا هلك ليس له ولد وله أخت فلها نصف ما ترك  وهو يرثها إن لم يكن لها ولد  فإن كانتا اثنتين فلهما الثلثان مما ترك  وإن كانوا إخوة رجالا ونساء فللذكر مثل حظ الأنثيين  يبين الله لكم أن تضلوا  والله بكل شىء عليم', NULL, 106, 'local:hafs-text.json'),
  ('hafs-5-1', 'hafs', 5, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ أَوْفُوا۟ بِٱلْعُقُودِ ۚ أُحِلَّتْ لَكُم بَهِيمَةُ ٱلْأَنْعَٰمِ إِلَّا مَا يُتْلَىٰ عَلَيْكُمْ غَيْرَ مُحِلِّى ٱلصَّيْدِ وَأَنتُمْ حُرُمٌ ۗ إِنَّ ٱللَّهَ يَحْكُمُ مَا يُرِيدُ', 'بسم الله الرحمن الرحيم يأيها الذين ءامنوا أوفوا بالعقود  أحلت لكم بهيمة الأنعم إلا ما يتلى عليكم غير محلى الصيد وأنتم حرم  إن الله يحكم ما يريد', NULL, 106, 'local:hafs-text.json'),
  ('hafs-5-2', 'hafs', 5, 2, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تُحِلُّوا۟ شَعَٰٓئِرَ ٱللَّهِ وَلَا ٱلشَّهْرَ ٱلْحَرَامَ وَلَا ٱلْهَدْىَ وَلَا ٱلْقَلَٰٓئِدَ وَلَآ ءَآمِّينَ ٱلْبَيْتَ ٱلْحَرَامَ يَبْتَغُونَ فَضْلًۭا مِّن رَّبِّهِمْ وَرِضْوَٰنًۭا ۚ وَإِذَا حَلَلْتُمْ فَٱصْطَادُوا۟ ۚ وَلَا يَجْرِمَنَّكُمْ شَنَـَٔانُ قَوْمٍ أَن صَدُّوكُمْ عَنِ ٱلْمَسْجِدِ ٱلْحَرَامِ أَن تَعْتَدُوا۟ ۘ وَتَعَاوَنُوا۟ عَلَى ٱلْبِرِّ وَٱلتَّقْوَىٰ ۖ وَلَا تَعَاوَنُوا۟ عَلَى ٱلْإِثْمِ وَٱلْعُدْوَٰنِ ۚ وَٱتَّقُوا۟ ٱللَّهَ ۖ إِنَّ ٱللَّهَ شَدِيدُ ٱلْعِقَابِ', 'يأيها الذين ءامنوا لا تحلوا شعئر الله ولا الشهر الحرام ولا الهدى ولا القلئد ولا ءامين البيت الحرام يبتغون فضلا من ربهم ورضونا  وإذا حللتم فاصطادوا  ولا يجرمنكم شنان قوم أن صدوكم عن المسجد الحرام أن تعتدوا  وتعاونوا على البر والتقوى  ولا تعاونوا على الإثم والعدون  واتقوا الله  إن الله شديد العقاب', NULL, 106, 'local:hafs-text.json'),
  ('hafs-5-3', 'hafs', 5, 3, 'حُرِّمَتْ عَلَيْكُمُ ٱلْمَيْتَةُ وَٱلدَّمُ وَلَحْمُ ٱلْخِنزِيرِ وَمَآ أُهِلَّ لِغَيْرِ ٱللَّهِ بِهِۦ وَٱلْمُنْخَنِقَةُ وَٱلْمَوْقُوذَةُ وَٱلْمُتَرَدِّيَةُ وَٱلنَّطِيحَةُ وَمَآ أَكَلَ ٱلسَّبُعُ إِلَّا مَا ذَكَّيْتُمْ وَمَا ذُبِحَ عَلَى ٱلنُّصُبِ وَأَن تَسْتَقْسِمُوا۟ بِٱلْأَزْلَٰمِ ۚ ذَٰلِكُمْ فِسْقٌ ۗ ٱلْيَوْمَ يَئِسَ ٱلَّذِينَ كَفَرُوا۟ مِن دِينِكُمْ فَلَا تَخْشَوْهُمْ وَٱخْشَوْنِ ۚ ٱلْيَوْمَ أَكْمَلْتُ لَكُمْ دِينَكُمْ وَأَتْمَمْتُ عَلَيْكُمْ نِعْمَتِى وَرَضِيتُ لَكُمُ ٱلْإِسْلَٰمَ دِينًۭا ۚ فَمَنِ ٱضْطُرَّ فِى مَخْمَصَةٍ غَيْرَ مُتَجَانِفٍۢ لِّإِثْمٍۢ ۙ فَإِنَّ ٱللَّهَ غَفُورٌۭ رَّحِيمٌۭ', 'حرمت عليكم الميتة والدم ولحم الخنزير وما أهل لغير الله به والمنخنقة والموقوذة والمتردية والنطيحة وما أكل السبع إلا ما ذكيتم وما ذبح على النصب وأن تستقسموا بالأزلم  ذلكم فسق  اليوم يئس الذين كفروا من دينكم فلا تخشوهم واخشون  اليوم أكملت لكم دينكم وأتممت عليكم نعمتى ورضيت لكم الإسلم دينا  فمن اضطر فى مخمصة غير متجانف لإثم  فإن الله غفور رحيم', NULL, 107, 'local:hafs-text.json'),
  ('hafs-5-4', 'hafs', 5, 4, 'يَسْـَٔلُونَكَ مَاذَآ أُحِلَّ لَهُمْ ۖ قُلْ أُحِلَّ لَكُمُ ٱلطَّيِّبَٰتُ ۙ وَمَا عَلَّمْتُم مِّنَ ٱلْجَوَارِحِ مُكَلِّبِينَ تُعَلِّمُونَهُنَّ مِمَّا عَلَّمَكُمُ ٱللَّهُ ۖ فَكُلُوا۟ مِمَّآ أَمْسَكْنَ عَلَيْكُمْ وَٱذْكُرُوا۟ ٱسْمَ ٱللَّهِ عَلَيْهِ ۖ وَٱتَّقُوا۟ ٱللَّهَ ۚ إِنَّ ٱللَّهَ سَرِيعُ ٱلْحِسَابِ', 'يسلونك ماذا أحل لهم  قل أحل لكم الطيبت  وما علمتم من الجوارح مكلبين تعلمونهن مما علمكم الله  فكلوا مما أمسكن عليكم واذكروا اسم الله عليه  واتقوا الله  إن الله سريع الحساب', NULL, 107, 'local:hafs-text.json'),
  ('hafs-5-5', 'hafs', 5, 5, 'ٱلْيَوْمَ أُحِلَّ لَكُمُ ٱلطَّيِّبَٰتُ ۖ وَطَعَامُ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَٰبَ حِلٌّۭ لَّكُمْ وَطَعَامُكُمْ حِلٌّۭ لَّهُمْ ۖ وَٱلْمُحْصَنَٰتُ مِنَ ٱلْمُؤْمِنَٰتِ وَٱلْمُحْصَنَٰتُ مِنَ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَٰبَ مِن قَبْلِكُمْ إِذَآ ءَاتَيْتُمُوهُنَّ أُجُورَهُنَّ مُحْصِنِينَ غَيْرَ مُسَٰفِحِينَ وَلَا مُتَّخِذِىٓ أَخْدَانٍۢ ۗ وَمَن يَكْفُرْ بِٱلْإِيمَٰنِ فَقَدْ حَبِطَ عَمَلُهُۥ وَهُوَ فِى ٱلْءَاخِرَةِ مِنَ ٱلْخَٰسِرِينَ', 'اليوم أحل لكم الطيبت  وطعام الذين أوتوا الكتب حل لكم وطعامكم حل لهم  والمحصنت من المؤمنت والمحصنت من الذين أوتوا الكتب من قبلكم إذا ءاتيتموهن أجورهن محصنين غير مسفحين ولا متخذى أخدان  ومن يكفر بالإيمن فقد حبط عمله وهو فى الءاخرة من الخسرين', NULL, 107, 'local:hafs-text.json'),
  ('hafs-5-6', 'hafs', 5, 6, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِذَا قُمْتُمْ إِلَى ٱلصَّلَوٰةِ فَٱغْسِلُوا۟ وُجُوهَكُمْ وَأَيْدِيَكُمْ إِلَى ٱلْمَرَافِقِ وَٱمْسَحُوا۟ بِرُءُوسِكُمْ وَأَرْجُلَكُمْ إِلَى ٱلْكَعْبَيْنِ ۚ وَإِن كُنتُمْ جُنُبًۭا فَٱطَّهَّرُوا۟ ۚ وَإِن كُنتُم مَّرْضَىٰٓ أَوْ عَلَىٰ سَفَرٍ أَوْ جَآءَ أَحَدٌۭ مِّنكُم مِّنَ ٱلْغَآئِطِ أَوْ لَٰمَسْتُمُ ٱلنِّسَآءَ فَلَمْ تَجِدُوا۟ مَآءًۭ فَتَيَمَّمُوا۟ صَعِيدًۭا طَيِّبًۭا فَٱمْسَحُوا۟ بِوُجُوهِكُمْ وَأَيْدِيكُم مِّنْهُ ۚ مَا يُرِيدُ ٱللَّهُ لِيَجْعَلَ عَلَيْكُم مِّنْ حَرَجٍۢ وَلَٰكِن يُرِيدُ لِيُطَهِّرَكُمْ وَلِيُتِمَّ نِعْمَتَهُۥ عَلَيْكُمْ لَعَلَّكُمْ تَشْكُرُونَ', 'يأيها الذين ءامنوا إذا قمتم إلى الصلوة فاغسلوا وجوهكم وأيديكم إلى المرافق وامسحوا برءوسكم وأرجلكم إلى الكعبين  وإن كنتم جنبا فاطهروا  وإن كنتم مرضى أو على سفر أو جاء أحد منكم من الغائط أو لمستم النساء فلم تجدوا ماء فتيمموا صعيدا طيبا فامسحوا بوجوهكم وأيديكم منه  ما يريد الله ليجعل عليكم من حرج ولكن يريد ليطهركم وليتم نعمته عليكم لعلكم تشكرون', NULL, 108, 'local:hafs-text.json'),
  ('hafs-5-7', 'hafs', 5, 7, 'وَٱذْكُرُوا۟ نِعْمَةَ ٱللَّهِ عَلَيْكُمْ وَمِيثَٰقَهُ ٱلَّذِى وَاثَقَكُم بِهِۦٓ إِذْ قُلْتُمْ سَمِعْنَا وَأَطَعْنَا ۖ وَٱتَّقُوا۟ ٱللَّهَ ۚ إِنَّ ٱللَّهَ عَلِيمٌۢ بِذَاتِ ٱلصُّدُورِ', 'واذكروا نعمة الله عليكم وميثقه الذى واثقكم به إذ قلتم سمعنا وأطعنا  واتقوا الله  إن الله عليم بذات الصدور', NULL, 108, 'local:hafs-text.json'),
  ('hafs-5-8', 'hafs', 5, 8, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ كُونُوا۟ قَوَّٰمِينَ لِلَّهِ شُهَدَآءَ بِٱلْقِسْطِ ۖ وَلَا يَجْرِمَنَّكُمْ شَنَـَٔانُ قَوْمٍ عَلَىٰٓ أَلَّا تَعْدِلُوا۟ ۚ ٱعْدِلُوا۟ هُوَ أَقْرَبُ لِلتَّقْوَىٰ ۖ وَٱتَّقُوا۟ ٱللَّهَ ۚ إِنَّ ٱللَّهَ خَبِيرٌۢ بِمَا تَعْمَلُونَ', 'يأيها الذين ءامنوا كونوا قومين لله شهداء بالقسط  ولا يجرمنكم شنان قوم على ألا تعدلوا  اعدلوا هو أقرب للتقوى  واتقوا الله  إن الله خبير بما تعملون', NULL, 108, 'local:hafs-text.json'),
  ('hafs-5-9', 'hafs', 5, 9, 'وَعَدَ ٱللَّهُ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ ۙ لَهُم مَّغْفِرَةٌۭ وَأَجْرٌ عَظِيمٌۭ', 'وعد الله الذين ءامنوا وعملوا الصلحت  لهم مغفرة وأجر عظيم', NULL, 108, 'local:hafs-text.json'),
  ('hafs-5-10', 'hafs', 5, 10, 'وَٱلَّذِينَ كَفَرُوا۟ وَكَذَّبُوا۟ بِـَٔايَٰتِنَآ أُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلْجَحِيمِ', 'والذين كفروا وكذبوا بايتنا أولئك أصحب الجحيم', NULL, 109, 'local:hafs-text.json'),
  ('hafs-5-11', 'hafs', 5, 11, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱذْكُرُوا۟ نِعْمَتَ ٱللَّهِ عَلَيْكُمْ إِذْ هَمَّ قَوْمٌ أَن يَبْسُطُوٓا۟ إِلَيْكُمْ أَيْدِيَهُمْ فَكَفَّ أَيْدِيَهُمْ عَنكُمْ ۖ وَٱتَّقُوا۟ ٱللَّهَ ۚ وَعَلَى ٱللَّهِ فَلْيَتَوَكَّلِ ٱلْمُؤْمِنُونَ', 'يأيها الذين ءامنوا اذكروا نعمت الله عليكم إذ هم قوم أن يبسطوا إليكم أيديهم فكف أيديهم عنكم  واتقوا الله  وعلى الله فليتوكل المؤمنون', NULL, 109, 'local:hafs-text.json'),
  ('hafs-5-12', 'hafs', 5, 12, '۞ وَلَقَدْ أَخَذَ ٱللَّهُ مِيثَٰقَ بَنِىٓ إِسْرَٰٓءِيلَ وَبَعَثْنَا مِنْهُمُ ٱثْنَىْ عَشَرَ نَقِيبًۭا ۖ وَقَالَ ٱللَّهُ إِنِّى مَعَكُمْ ۖ لَئِنْ أَقَمْتُمُ ٱلصَّلَوٰةَ وَءَاتَيْتُمُ ٱلزَّكَوٰةَ وَءَامَنتُم بِرُسُلِى وَعَزَّرْتُمُوهُمْ وَأَقْرَضْتُمُ ٱللَّهَ قَرْضًا حَسَنًۭا لَّأُكَفِّرَنَّ عَنكُمْ سَيِّـَٔاتِكُمْ وَلَأُدْخِلَنَّكُمْ جَنَّٰتٍۢ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ ۚ فَمَن كَفَرَ بَعْدَ ذَٰلِكَ مِنكُمْ فَقَدْ ضَلَّ سَوَآءَ ٱلسَّبِيلِ', 'ولقد أخذ الله ميثق بنى إسرءيل وبعثنا منهم اثنى عشر نقيبا  وقال الله إنى معكم  لئن أقمتم الصلوة وءاتيتم الزكوة وءامنتم برسلى وعزرتموهم وأقرضتم الله قرضا حسنا لأكفرن عنكم سياتكم ولأدخلنكم جنت تجرى من تحتها الأنهر  فمن كفر بعد ذلك منكم فقد ضل سواء السبيل', NULL, 109, 'local:hafs-text.json'),
  ('hafs-5-13', 'hafs', 5, 13, 'فَبِمَا نَقْضِهِم مِّيثَٰقَهُمْ لَعَنَّٰهُمْ وَجَعَلْنَا قُلُوبَهُمْ قَٰسِيَةًۭ ۖ يُحَرِّفُونَ ٱلْكَلِمَ عَن مَّوَاضِعِهِۦ ۙ وَنَسُوا۟ حَظًّۭا مِّمَّا ذُكِّرُوا۟ بِهِۦ ۚ وَلَا تَزَالُ تَطَّلِعُ عَلَىٰ خَآئِنَةٍۢ مِّنْهُمْ إِلَّا قَلِيلًۭا مِّنْهُمْ ۖ فَٱعْفُ عَنْهُمْ وَٱصْفَحْ ۚ إِنَّ ٱللَّهَ يُحِبُّ ٱلْمُحْسِنِينَ', 'فبما نقضهم ميثقهم لعنهم وجعلنا قلوبهم قسية  يحرفون الكلم عن مواضعه  ونسوا حظا مما ذكروا به  ولا تزال تطلع على خائنة منهم إلا قليلا منهم  فاعف عنهم واصفح  إن الله يحب المحسنين', NULL, 109, 'local:hafs-text.json'),
  ('hafs-5-14', 'hafs', 5, 14, 'وَمِنَ ٱلَّذِينَ قَالُوٓا۟ إِنَّا نَصَٰرَىٰٓ أَخَذْنَا مِيثَٰقَهُمْ فَنَسُوا۟ حَظًّۭا مِّمَّا ذُكِّرُوا۟ بِهِۦ فَأَغْرَيْنَا بَيْنَهُمُ ٱلْعَدَاوَةَ وَٱلْبَغْضَآءَ إِلَىٰ يَوْمِ ٱلْقِيَٰمَةِ ۚ وَسَوْفَ يُنَبِّئُهُمُ ٱللَّهُ بِمَا كَانُوا۟ يَصْنَعُونَ', 'ومن الذين قالوا إنا نصرى أخذنا ميثقهم فنسوا حظا مما ذكروا به فأغرينا بينهم العداوة والبغضاء إلى يوم القيمة  وسوف ينبئهم الله بما كانوا يصنعون', NULL, 110, 'local:hafs-text.json'),
  ('hafs-5-15', 'hafs', 5, 15, 'يَٰٓأَهْلَ ٱلْكِتَٰبِ قَدْ جَآءَكُمْ رَسُولُنَا يُبَيِّنُ لَكُمْ كَثِيرًۭا مِّمَّا كُنتُمْ تُخْفُونَ مِنَ ٱلْكِتَٰبِ وَيَعْفُوا۟ عَن كَثِيرٍۢ ۚ قَدْ جَآءَكُم مِّنَ ٱللَّهِ نُورٌۭ وَكِتَٰبٌۭ مُّبِينٌۭ', 'يأهل الكتب قد جاءكم رسولنا يبين لكم كثيرا مما كنتم تخفون من الكتب ويعفوا عن كثير  قد جاءكم من الله نور وكتب مبين', NULL, 110, 'local:hafs-text.json'),
  ('hafs-5-16', 'hafs', 5, 16, 'يَهْدِى بِهِ ٱللَّهُ مَنِ ٱتَّبَعَ رِضْوَٰنَهُۥ سُبُلَ ٱلسَّلَٰمِ وَيُخْرِجُهُم مِّنَ ٱلظُّلُمَٰتِ إِلَى ٱلنُّورِ بِإِذْنِهِۦ وَيَهْدِيهِمْ إِلَىٰ صِرَٰطٍۢ مُّسْتَقِيمٍۢ', 'يهدى به الله من اتبع رضونه سبل السلم ويخرجهم من الظلمت إلى النور بإذنه ويهديهم إلى صرط مستقيم', NULL, 110, 'local:hafs-text.json'),
  ('hafs-5-17', 'hafs', 5, 17, 'لَّقَدْ كَفَرَ ٱلَّذِينَ قَالُوٓا۟ إِنَّ ٱللَّهَ هُوَ ٱلْمَسِيحُ ٱبْنُ مَرْيَمَ ۚ قُلْ فَمَن يَمْلِكُ مِنَ ٱللَّهِ شَيْـًٔا إِنْ أَرَادَ أَن يُهْلِكَ ٱلْمَسِيحَ ٱبْنَ مَرْيَمَ وَأُمَّهُۥ وَمَن فِى ٱلْأَرْضِ جَمِيعًۭا ۗ وَلِلَّهِ مُلْكُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَمَا بَيْنَهُمَا ۚ يَخْلُقُ مَا يَشَآءُ ۚ وَٱللَّهُ عَلَىٰ كُلِّ شَىْءٍۢ قَدِيرٌۭ', 'لقد كفر الذين قالوا إن الله هو المسيح ابن مريم  قل فمن يملك من الله شيا إن أراد أن يهلك المسيح ابن مريم وأمه ومن فى الأرض جميعا  ولله ملك السموت والأرض وما بينهما  يخلق ما يشاء  والله على كل شىء قدير', NULL, 110, 'local:hafs-text.json'),
  ('hafs-5-18', 'hafs', 5, 18, 'وَقَالَتِ ٱلْيَهُودُ وَٱلنَّصَٰرَىٰ نَحْنُ أَبْنَٰٓؤُا۟ ٱللَّهِ وَأَحِبَّٰٓؤُهُۥ ۚ قُلْ فَلِمَ يُعَذِّبُكُم بِذُنُوبِكُم ۖ بَلْ أَنتُم بَشَرٌۭ مِّمَّنْ خَلَقَ ۚ يَغْفِرُ لِمَن يَشَآءُ وَيُعَذِّبُ مَن يَشَآءُ ۚ وَلِلَّهِ مُلْكُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَمَا بَيْنَهُمَا ۖ وَإِلَيْهِ ٱلْمَصِيرُ', 'وقالت اليهود والنصرى نحن أبنؤا الله وأحبؤه  قل فلم يعذبكم بذنوبكم  بل أنتم بشر ممن خلق  يغفر لمن يشاء ويعذب من يشاء  ولله ملك السموت والأرض وما بينهما  وإليه المصير', NULL, 111, 'local:hafs-text.json'),
  ('hafs-5-19', 'hafs', 5, 19, 'يَٰٓأَهْلَ ٱلْكِتَٰبِ قَدْ جَآءَكُمْ رَسُولُنَا يُبَيِّنُ لَكُمْ عَلَىٰ فَتْرَةٍۢ مِّنَ ٱلرُّسُلِ أَن تَقُولُوا۟ مَا جَآءَنَا مِنۢ بَشِيرٍۢ وَلَا نَذِيرٍۢ ۖ فَقَدْ جَآءَكُم بَشِيرٌۭ وَنَذِيرٌۭ ۗ وَٱللَّهُ عَلَىٰ كُلِّ شَىْءٍۢ قَدِيرٌۭ', 'يأهل الكتب قد جاءكم رسولنا يبين لكم على فترة من الرسل أن تقولوا ما جاءنا من بشير ولا نذير  فقد جاءكم بشير ونذير  والله على كل شىء قدير', NULL, 111, 'local:hafs-text.json'),
  ('hafs-5-20', 'hafs', 5, 20, 'وَإِذْ قَالَ مُوسَىٰ لِقَوْمِهِۦ يَٰقَوْمِ ٱذْكُرُوا۟ نِعْمَةَ ٱللَّهِ عَلَيْكُمْ إِذْ جَعَلَ فِيكُمْ أَنۢبِيَآءَ وَجَعَلَكُم مُّلُوكًۭا وَءَاتَىٰكُم مَّا لَمْ يُؤْتِ أَحَدًۭا مِّنَ ٱلْعَٰلَمِينَ', 'وإذ قال موسى لقومه يقوم اذكروا نعمة الله عليكم إذ جعل فيكم أنبياء وجعلكم ملوكا وءاتىكم ما لم يؤت أحدا من العلمين', NULL, 111, 'local:hafs-text.json'),
  ('hafs-5-21', 'hafs', 5, 21, 'يَٰقَوْمِ ٱدْخُلُوا۟ ٱلْأَرْضَ ٱلْمُقَدَّسَةَ ٱلَّتِى كَتَبَ ٱللَّهُ لَكُمْ وَلَا تَرْتَدُّوا۟ عَلَىٰٓ أَدْبَارِكُمْ فَتَنقَلِبُوا۟ خَٰسِرِينَ', 'يقوم ادخلوا الأرض المقدسة التى كتب الله لكم ولا ترتدوا على أدباركم فتنقلبوا خسرين', NULL, 111, 'local:hafs-text.json'),
  ('hafs-5-22', 'hafs', 5, 22, 'قَالُوا۟ يَٰمُوسَىٰٓ إِنَّ فِيهَا قَوْمًۭا جَبَّارِينَ وَإِنَّا لَن نَّدْخُلَهَا حَتَّىٰ يَخْرُجُوا۟ مِنْهَا فَإِن يَخْرُجُوا۟ مِنْهَا فَإِنَّا دَٰخِلُونَ', 'قالوا يموسى إن فيها قوما جبارين وإنا لن ندخلها حتى يخرجوا منها فإن يخرجوا منها فإنا دخلون', NULL, 111, 'local:hafs-text.json'),
  ('hafs-5-23', 'hafs', 5, 23, 'قَالَ رَجُلَانِ مِنَ ٱلَّذِينَ يَخَافُونَ أَنْعَمَ ٱللَّهُ عَلَيْهِمَا ٱدْخُلُوا۟ عَلَيْهِمُ ٱلْبَابَ فَإِذَا دَخَلْتُمُوهُ فَإِنَّكُمْ غَٰلِبُونَ ۚ وَعَلَى ٱللَّهِ فَتَوَكَّلُوٓا۟ إِن كُنتُم مُّؤْمِنِينَ', 'قال رجلان من الذين يخافون أنعم الله عليهما ادخلوا عليهم الباب فإذا دخلتموه فإنكم غلبون  وعلى الله فتوكلوا إن كنتم مؤمنين', NULL, 111, 'local:hafs-text.json'),
  ('hafs-5-24', 'hafs', 5, 24, 'قَالُوا۟ يَٰمُوسَىٰٓ إِنَّا لَن نَّدْخُلَهَآ أَبَدًۭا مَّا دَامُوا۟ فِيهَا ۖ فَٱذْهَبْ أَنتَ وَرَبُّكَ فَقَٰتِلَآ إِنَّا هَٰهُنَا قَٰعِدُونَ', 'قالوا يموسى إنا لن ندخلها أبدا ما داموا فيها  فاذهب أنت وربك فقتلا إنا ههنا قعدون', NULL, 112, 'local:hafs-text.json'),
  ('hafs-5-25', 'hafs', 5, 25, 'قَالَ رَبِّ إِنِّى لَآ أَمْلِكُ إِلَّا نَفْسِى وَأَخِى ۖ فَٱفْرُقْ بَيْنَنَا وَبَيْنَ ٱلْقَوْمِ ٱلْفَٰسِقِينَ', 'قال رب إنى لا أملك إلا نفسى وأخى  فافرق بيننا وبين القوم الفسقين', NULL, 112, 'local:hafs-text.json'),
  ('hafs-5-26', 'hafs', 5, 26, 'قَالَ فَإِنَّهَا مُحَرَّمَةٌ عَلَيْهِمْ ۛ أَرْبَعِينَ سَنَةًۭ ۛ يَتِيهُونَ فِى ٱلْأَرْضِ ۚ فَلَا تَأْسَ عَلَى ٱلْقَوْمِ ٱلْفَٰسِقِينَ', 'قال فإنها محرمة عليهم  أربعين سنة  يتيهون فى الأرض  فلا تأس على القوم الفسقين', NULL, 112, 'local:hafs-text.json'),
  ('hafs-5-27', 'hafs', 5, 27, '۞ وَٱتْلُ عَلَيْهِمْ نَبَأَ ٱبْنَىْ ءَادَمَ بِٱلْحَقِّ إِذْ قَرَّبَا قُرْبَانًۭا فَتُقُبِّلَ مِنْ أَحَدِهِمَا وَلَمْ يُتَقَبَّلْ مِنَ ٱلْءَاخَرِ قَالَ لَأَقْتُلَنَّكَ ۖ قَالَ إِنَّمَا يَتَقَبَّلُ ٱللَّهُ مِنَ ٱلْمُتَّقِينَ', 'واتل عليهم نبأ ابنى ءادم بالحق إذ قربا قربانا فتقبل من أحدهما ولم يتقبل من الءاخر قال لأقتلنك  قال إنما يتقبل الله من المتقين', NULL, 112, 'local:hafs-text.json'),
  ('hafs-5-28', 'hafs', 5, 28, 'لَئِنۢ بَسَطتَ إِلَىَّ يَدَكَ لِتَقْتُلَنِى مَآ أَنَا۠ بِبَاسِطٍۢ يَدِىَ إِلَيْكَ لِأَقْتُلَكَ ۖ إِنِّىٓ أَخَافُ ٱللَّهَ رَبَّ ٱلْعَٰلَمِينَ', 'لئن بسطت إلى يدك لتقتلنى ما أنا بباسط يدى إليك لأقتلك  إنى أخاف الله رب العلمين', NULL, 112, 'local:hafs-text.json'),
  ('hafs-5-29', 'hafs', 5, 29, 'إِنِّىٓ أُرِيدُ أَن تَبُوٓأَ بِإِثْمِى وَإِثْمِكَ فَتَكُونَ مِنْ أَصْحَٰبِ ٱلنَّارِ ۚ وَذَٰلِكَ جَزَٰٓؤُا۟ ٱلظَّٰلِمِينَ', 'إنى أريد أن تبوأ بإثمى وإثمك فتكون من أصحب النار  وذلك جزؤا الظلمين', NULL, 112, 'local:hafs-text.json'),
  ('hafs-5-30', 'hafs', 5, 30, 'فَطَوَّعَتْ لَهُۥ نَفْسُهُۥ قَتْلَ أَخِيهِ فَقَتَلَهُۥ فَأَصْبَحَ مِنَ ٱلْخَٰسِرِينَ', 'فطوعت له نفسه قتل أخيه فقتله فأصبح من الخسرين', NULL, 112, 'local:hafs-text.json'),
  ('hafs-5-31', 'hafs', 5, 31, 'فَبَعَثَ ٱللَّهُ غُرَابًۭا يَبْحَثُ فِى ٱلْأَرْضِ لِيُرِيَهُۥ كَيْفَ يُوَٰرِى سَوْءَةَ أَخِيهِ ۚ قَالَ يَٰوَيْلَتَىٰٓ أَعَجَزْتُ أَنْ أَكُونَ مِثْلَ هَٰذَا ٱلْغُرَابِ فَأُوَٰرِىَ سَوْءَةَ أَخِى ۖ فَأَصْبَحَ مِنَ ٱلنَّٰدِمِينَ', 'فبعث الله غرابا يبحث فى الأرض ليريه كيف يورى سوءة أخيه  قال يويلتى أعجزت أن أكون مثل هذا الغراب فأورى سوءة أخى  فأصبح من الندمين', NULL, 112, 'local:hafs-text.json'),
  ('hafs-5-32', 'hafs', 5, 32, 'مِنْ أَجْلِ ذَٰلِكَ كَتَبْنَا عَلَىٰ بَنِىٓ إِسْرَٰٓءِيلَ أَنَّهُۥ مَن قَتَلَ نَفْسًۢا بِغَيْرِ نَفْسٍ أَوْ فَسَادٍۢ فِى ٱلْأَرْضِ فَكَأَنَّمَا قَتَلَ ٱلنَّاسَ جَمِيعًۭا وَمَنْ أَحْيَاهَا فَكَأَنَّمَآ أَحْيَا ٱلنَّاسَ جَمِيعًۭا ۚ وَلَقَدْ جَآءَتْهُمْ رُسُلُنَا بِٱلْبَيِّنَٰتِ ثُمَّ إِنَّ كَثِيرًۭا مِّنْهُم بَعْدَ ذَٰلِكَ فِى ٱلْأَرْضِ لَمُسْرِفُونَ', 'من أجل ذلك كتبنا على بنى إسرءيل أنه من قتل نفسا بغير نفس أو فساد فى الأرض فكأنما قتل الناس جميعا ومن أحياها فكأنما أحيا الناس جميعا  ولقد جاءتهم رسلنا بالبينت ثم إن كثيرا منهم بعد ذلك فى الأرض لمسرفون', NULL, 113, 'local:hafs-text.json'),
  ('hafs-5-33', 'hafs', 5, 33, 'إِنَّمَا جَزَٰٓؤُا۟ ٱلَّذِينَ يُحَارِبُونَ ٱللَّهَ وَرَسُولَهُۥ وَيَسْعَوْنَ فِى ٱلْأَرْضِ فَسَادًا أَن يُقَتَّلُوٓا۟ أَوْ يُصَلَّبُوٓا۟ أَوْ تُقَطَّعَ أَيْدِيهِمْ وَأَرْجُلُهُم مِّنْ خِلَٰفٍ أَوْ يُنفَوْا۟ مِنَ ٱلْأَرْضِ ۚ ذَٰلِكَ لَهُمْ خِزْىٌۭ فِى ٱلدُّنْيَا ۖ وَلَهُمْ فِى ٱلْءَاخِرَةِ عَذَابٌ عَظِيمٌ', 'إنما جزؤا الذين يحاربون الله ورسوله ويسعون فى الأرض فسادا أن يقتلوا أو يصلبوا أو تقطع أيديهم وأرجلهم من خلف أو ينفوا من الأرض  ذلك لهم خزى فى الدنيا  ولهم فى الءاخرة عذاب عظيم', NULL, 113, 'local:hafs-text.json'),
  ('hafs-5-34', 'hafs', 5, 34, 'إِلَّا ٱلَّذِينَ تَابُوا۟ مِن قَبْلِ أَن تَقْدِرُوا۟ عَلَيْهِمْ ۖ فَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ غَفُورٌۭ رَّحِيمٌۭ', 'إلا الذين تابوا من قبل أن تقدروا عليهم  فاعلموا أن الله غفور رحيم', NULL, 113, 'local:hafs-text.json'),
  ('hafs-5-35', 'hafs', 5, 35, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱتَّقُوا۟ ٱللَّهَ وَٱبْتَغُوٓا۟ إِلَيْهِ ٱلْوَسِيلَةَ وَجَٰهِدُوا۟ فِى سَبِيلِهِۦ لَعَلَّكُمْ تُفْلِحُونَ', 'يأيها الذين ءامنوا اتقوا الله وابتغوا إليه الوسيلة وجهدوا فى سبيله لعلكم تفلحون', NULL, 113, 'local:hafs-text.json'),
  ('hafs-5-36', 'hafs', 5, 36, 'إِنَّ ٱلَّذِينَ كَفَرُوا۟ لَوْ أَنَّ لَهُم مَّا فِى ٱلْأَرْضِ جَمِيعًۭا وَمِثْلَهُۥ مَعَهُۥ لِيَفْتَدُوا۟ بِهِۦ مِنْ عَذَابِ يَوْمِ ٱلْقِيَٰمَةِ مَا تُقُبِّلَ مِنْهُمْ ۖ وَلَهُمْ عَذَابٌ أَلِيمٌۭ', 'إن الذين كفروا لو أن لهم ما فى الأرض جميعا ومثله معه ليفتدوا به من عذاب يوم القيمة ما تقبل منهم  ولهم عذاب أليم', NULL, 113, 'local:hafs-text.json'),
  ('hafs-5-37', 'hafs', 5, 37, 'يُرِيدُونَ أَن يَخْرُجُوا۟ مِنَ ٱلنَّارِ وَمَا هُم بِخَٰرِجِينَ مِنْهَا ۖ وَلَهُمْ عَذَابٌۭ مُّقِيمٌۭ', 'يريدون أن يخرجوا من النار وما هم بخرجين منها  ولهم عذاب مقيم', NULL, 114, 'local:hafs-text.json'),
  ('hafs-5-38', 'hafs', 5, 38, 'وَٱلسَّارِقُ وَٱلسَّارِقَةُ فَٱقْطَعُوٓا۟ أَيْدِيَهُمَا جَزَآءًۢ بِمَا كَسَبَا نَكَٰلًۭا مِّنَ ٱللَّهِ ۗ وَٱللَّهُ عَزِيزٌ حَكِيمٌۭ', 'والسارق والسارقة فاقطعوا أيديهما جزاء بما كسبا نكلا من الله  والله عزيز حكيم', NULL, 114, 'local:hafs-text.json'),
  ('hafs-5-39', 'hafs', 5, 39, 'فَمَن تَابَ مِنۢ بَعْدِ ظُلْمِهِۦ وَأَصْلَحَ فَإِنَّ ٱللَّهَ يَتُوبُ عَلَيْهِ ۗ إِنَّ ٱللَّهَ غَفُورٌۭ رَّحِيمٌ', 'فمن تاب من بعد ظلمه وأصلح فإن الله يتوب عليه  إن الله غفور رحيم', NULL, 114, 'local:hafs-text.json'),
  ('hafs-5-40', 'hafs', 5, 40, 'أَلَمْ تَعْلَمْ أَنَّ ٱللَّهَ لَهُۥ مُلْكُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ يُعَذِّبُ مَن يَشَآءُ وَيَغْفِرُ لِمَن يَشَآءُ ۗ وَٱللَّهُ عَلَىٰ كُلِّ شَىْءٍۢ قَدِيرٌۭ', 'ألم تعلم أن الله له ملك السموت والأرض يعذب من يشاء ويغفر لمن يشاء  والله على كل شىء قدير', NULL, 114, 'local:hafs-text.json'),
  ('hafs-5-41', 'hafs', 5, 41, '۞ يَٰٓأَيُّهَا ٱلرَّسُولُ لَا يَحْزُنكَ ٱلَّذِينَ يُسَٰرِعُونَ فِى ٱلْكُفْرِ مِنَ ٱلَّذِينَ قَالُوٓا۟ ءَامَنَّا بِأَفْوَٰهِهِمْ وَلَمْ تُؤْمِن قُلُوبُهُمْ ۛ وَمِنَ ٱلَّذِينَ هَادُوا۟ ۛ سَمَّٰعُونَ لِلْكَذِبِ سَمَّٰعُونَ لِقَوْمٍ ءَاخَرِينَ لَمْ يَأْتُوكَ ۖ يُحَرِّفُونَ ٱلْكَلِمَ مِنۢ بَعْدِ مَوَاضِعِهِۦ ۖ يَقُولُونَ إِنْ أُوتِيتُمْ هَٰذَا فَخُذُوهُ وَإِن لَّمْ تُؤْتَوْهُ فَٱحْذَرُوا۟ ۚ وَمَن يُرِدِ ٱللَّهُ فِتْنَتَهُۥ فَلَن تَمْلِكَ لَهُۥ مِنَ ٱللَّهِ شَيْـًٔا ۚ أُو۟لَٰٓئِكَ ٱلَّذِينَ لَمْ يُرِدِ ٱللَّهُ أَن يُطَهِّرَ قُلُوبَهُمْ ۚ لَهُمْ فِى ٱلدُّنْيَا خِزْىٌۭ ۖ وَلَهُمْ فِى ٱلْءَاخِرَةِ عَذَابٌ عَظِيمٌۭ', 'يأيها الرسول لا يحزنك الذين يسرعون فى الكفر من الذين قالوا ءامنا بأفوههم ولم تؤمن قلوبهم  ومن الذين هادوا  سمعون للكذب سمعون لقوم ءاخرين لم يأتوك  يحرفون الكلم من بعد مواضعه  يقولون إن أوتيتم هذا فخذوه وإن لم تؤتوه فاحذروا  ومن يرد الله فتنته فلن تملك له من الله شيا  أولئك الذين لم يرد الله أن يطهر قلوبهم  لهم فى الدنيا خزى  ولهم فى الءاخرة عذاب عظيم', NULL, 114, 'local:hafs-text.json'),
  ('hafs-5-42', 'hafs', 5, 42, 'سَمَّٰعُونَ لِلْكَذِبِ أَكَّٰلُونَ لِلسُّحْتِ ۚ فَإِن جَآءُوكَ فَٱحْكُم بَيْنَهُمْ أَوْ أَعْرِضْ عَنْهُمْ ۖ وَإِن تُعْرِضْ عَنْهُمْ فَلَن يَضُرُّوكَ شَيْـًۭٔا ۖ وَإِنْ حَكَمْتَ فَٱحْكُم بَيْنَهُم بِٱلْقِسْطِ ۚ إِنَّ ٱللَّهَ يُحِبُّ ٱلْمُقْسِطِينَ', 'سمعون للكذب أكلون للسحت  فإن جاءوك فاحكم بينهم أو أعرض عنهم  وإن تعرض عنهم فلن يضروك شيا  وإن حكمت فاحكم بينهم بالقسط  إن الله يحب المقسطين', NULL, 115, 'local:hafs-text.json'),
  ('hafs-5-43', 'hafs', 5, 43, 'وَكَيْفَ يُحَكِّمُونَكَ وَعِندَهُمُ ٱلتَّوْرَىٰةُ فِيهَا حُكْمُ ٱللَّهِ ثُمَّ يَتَوَلَّوْنَ مِنۢ بَعْدِ ذَٰلِكَ ۚ وَمَآ أُو۟لَٰٓئِكَ بِٱلْمُؤْمِنِينَ', 'وكيف يحكمونك وعندهم التورىة فيها حكم الله ثم يتولون من بعد ذلك  وما أولئك بالمؤمنين', NULL, 115, 'local:hafs-text.json'),
  ('hafs-5-44', 'hafs', 5, 44, 'إِنَّآ أَنزَلْنَا ٱلتَّوْرَىٰةَ فِيهَا هُدًۭى وَنُورٌۭ ۚ يَحْكُمُ بِهَا ٱلنَّبِيُّونَ ٱلَّذِينَ أَسْلَمُوا۟ لِلَّذِينَ هَادُوا۟ وَٱلرَّبَّٰنِيُّونَ وَٱلْأَحْبَارُ بِمَا ٱسْتُحْفِظُوا۟ مِن كِتَٰبِ ٱللَّهِ وَكَانُوا۟ عَلَيْهِ شُهَدَآءَ ۚ فَلَا تَخْشَوُا۟ ٱلنَّاسَ وَٱخْشَوْنِ وَلَا تَشْتَرُوا۟ بِـَٔايَٰتِى ثَمَنًۭا قَلِيلًۭا ۚ وَمَن لَّمْ يَحْكُم بِمَآ أَنزَلَ ٱللَّهُ فَأُو۟لَٰٓئِكَ هُمُ ٱلْكَٰفِرُونَ', 'إنا أنزلنا التورىة فيها هدى ونور  يحكم بها النبيون الذين أسلموا للذين هادوا والربنيون والأحبار بما استحفظوا من كتب الله وكانوا عليه شهداء  فلا تخشوا الناس واخشون ولا تشتروا بايتى ثمنا قليلا  ومن لم يحكم بما أنزل الله فأولئك هم الكفرون', NULL, 115, 'local:hafs-text.json'),
  ('hafs-5-45', 'hafs', 5, 45, 'وَكَتَبْنَا عَلَيْهِمْ فِيهَآ أَنَّ ٱلنَّفْسَ بِٱلنَّفْسِ وَٱلْعَيْنَ بِٱلْعَيْنِ وَٱلْأَنفَ بِٱلْأَنفِ وَٱلْأُذُنَ بِٱلْأُذُنِ وَٱلسِّنَّ بِٱلسِّنِّ وَٱلْجُرُوحَ قِصَاصٌۭ ۚ فَمَن تَصَدَّقَ بِهِۦ فَهُوَ كَفَّارَةٌۭ لَّهُۥ ۚ وَمَن لَّمْ يَحْكُم بِمَآ أَنزَلَ ٱللَّهُ فَأُو۟لَٰٓئِكَ هُمُ ٱلظَّٰلِمُونَ', 'وكتبنا عليهم فيها أن النفس بالنفس والعين بالعين والأنف بالأنف والأذن بالأذن والسن بالسن والجروح قصاص  فمن تصدق به فهو كفارة له  ومن لم يحكم بما أنزل الله فأولئك هم الظلمون', NULL, 115, 'local:hafs-text.json'),
  ('hafs-5-46', 'hafs', 5, 46, 'وَقَفَّيْنَا عَلَىٰٓ ءَاثَٰرِهِم بِعِيسَى ٱبْنِ مَرْيَمَ مُصَدِّقًۭا لِّمَا بَيْنَ يَدَيْهِ مِنَ ٱلتَّوْرَىٰةِ ۖ وَءَاتَيْنَٰهُ ٱلْإِنجِيلَ فِيهِ هُدًۭى وَنُورٌۭ وَمُصَدِّقًۭا لِّمَا بَيْنَ يَدَيْهِ مِنَ ٱلتَّوْرَىٰةِ وَهُدًۭى وَمَوْعِظَةًۭ لِّلْمُتَّقِينَ', 'وقفينا على ءاثرهم بعيسى ابن مريم مصدقا لما بين يديه من التورىة  وءاتينه الإنجيل فيه هدى ونور ومصدقا لما بين يديه من التورىة وهدى وموعظة للمتقين', NULL, 116, 'local:hafs-text.json'),
  ('hafs-5-47', 'hafs', 5, 47, 'وَلْيَحْكُمْ أَهْلُ ٱلْإِنجِيلِ بِمَآ أَنزَلَ ٱللَّهُ فِيهِ ۚ وَمَن لَّمْ يَحْكُم بِمَآ أَنزَلَ ٱللَّهُ فَأُو۟لَٰٓئِكَ هُمُ ٱلْفَٰسِقُونَ', 'وليحكم أهل الإنجيل بما أنزل الله فيه  ومن لم يحكم بما أنزل الله فأولئك هم الفسقون', NULL, 116, 'local:hafs-text.json'),
  ('hafs-5-48', 'hafs', 5, 48, 'وَأَنزَلْنَآ إِلَيْكَ ٱلْكِتَٰبَ بِٱلْحَقِّ مُصَدِّقًۭا لِّمَا بَيْنَ يَدَيْهِ مِنَ ٱلْكِتَٰبِ وَمُهَيْمِنًا عَلَيْهِ ۖ فَٱحْكُم بَيْنَهُم بِمَآ أَنزَلَ ٱللَّهُ ۖ وَلَا تَتَّبِعْ أَهْوَآءَهُمْ عَمَّا جَآءَكَ مِنَ ٱلْحَقِّ ۚ لِكُلٍّۢ جَعَلْنَا مِنكُمْ شِرْعَةًۭ وَمِنْهَاجًۭا ۚ وَلَوْ شَآءَ ٱللَّهُ لَجَعَلَكُمْ أُمَّةًۭ وَٰحِدَةًۭ وَلَٰكِن لِّيَبْلُوَكُمْ فِى مَآ ءَاتَىٰكُمْ ۖ فَٱسْتَبِقُوا۟ ٱلْخَيْرَٰتِ ۚ إِلَى ٱللَّهِ مَرْجِعُكُمْ جَمِيعًۭا فَيُنَبِّئُكُم بِمَا كُنتُمْ فِيهِ تَخْتَلِفُونَ', 'وأنزلنا إليك الكتب بالحق مصدقا لما بين يديه من الكتب ومهيمنا عليه  فاحكم بينهم بما أنزل الله  ولا تتبع أهواءهم عما جاءك من الحق  لكل جعلنا منكم شرعة ومنهاجا  ولو شاء الله لجعلكم أمة وحدة ولكن ليبلوكم فى ما ءاتىكم  فاستبقوا الخيرت  إلى الله مرجعكم جميعا فينبئكم بما كنتم فيه تختلفون', NULL, 116, 'local:hafs-text.json'),
  ('hafs-5-49', 'hafs', 5, 49, 'وَأَنِ ٱحْكُم بَيْنَهُم بِمَآ أَنزَلَ ٱللَّهُ وَلَا تَتَّبِعْ أَهْوَآءَهُمْ وَٱحْذَرْهُمْ أَن يَفْتِنُوكَ عَنۢ بَعْضِ مَآ أَنزَلَ ٱللَّهُ إِلَيْكَ ۖ فَإِن تَوَلَّوْا۟ فَٱعْلَمْ أَنَّمَا يُرِيدُ ٱللَّهُ أَن يُصِيبَهُم بِبَعْضِ ذُنُوبِهِمْ ۗ وَإِنَّ كَثِيرًۭا مِّنَ ٱلنَّاسِ لَفَٰسِقُونَ', 'وأن احكم بينهم بما أنزل الله ولا تتبع أهواءهم واحذرهم أن يفتنوك عن بعض ما أنزل الله إليك  فإن تولوا فاعلم أنما يريد الله أن يصيبهم ببعض ذنوبهم  وإن كثيرا من الناس لفسقون', NULL, 116, 'local:hafs-text.json'),
  ('hafs-5-50', 'hafs', 5, 50, 'أَفَحُكْمَ ٱلْجَٰهِلِيَّةِ يَبْغُونَ ۚ وَمَنْ أَحْسَنُ مِنَ ٱللَّهِ حُكْمًۭا لِّقَوْمٍۢ يُوقِنُونَ', 'أفحكم الجهلية يبغون  ومن أحسن من الله حكما لقوم يوقنون', NULL, 116, 'local:hafs-text.json'),
  ('hafs-5-51', 'hafs', 5, 51, '۞ يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَتَّخِذُوا۟ ٱلْيَهُودَ وَٱلنَّصَٰرَىٰٓ أَوْلِيَآءَ ۘ بَعْضُهُمْ أَوْلِيَآءُ بَعْضٍۢ ۚ وَمَن يَتَوَلَّهُم مِّنكُمْ فَإِنَّهُۥ مِنْهُمْ ۗ إِنَّ ٱللَّهَ لَا يَهْدِى ٱلْقَوْمَ ٱلظَّٰلِمِينَ', 'يأيها الذين ءامنوا لا تتخذوا اليهود والنصرى أولياء  بعضهم أولياء بعض  ومن يتولهم منكم فإنه منهم  إن الله لا يهدى القوم الظلمين', NULL, 117, 'local:hafs-text.json'),
  ('hafs-5-52', 'hafs', 5, 52, 'فَتَرَى ٱلَّذِينَ فِى قُلُوبِهِم مَّرَضٌۭ يُسَٰرِعُونَ فِيهِمْ يَقُولُونَ نَخْشَىٰٓ أَن تُصِيبَنَا دَآئِرَةٌۭ ۚ فَعَسَى ٱللَّهُ أَن يَأْتِىَ بِٱلْفَتْحِ أَوْ أَمْرٍۢ مِّنْ عِندِهِۦ فَيُصْبِحُوا۟ عَلَىٰ مَآ أَسَرُّوا۟ فِىٓ أَنفُسِهِمْ نَٰدِمِينَ', 'فترى الذين فى قلوبهم مرض يسرعون فيهم يقولون نخشى أن تصيبنا دائرة  فعسى الله أن يأتى بالفتح أو أمر من عنده فيصبحوا على ما أسروا فى أنفسهم ندمين', NULL, 117, 'local:hafs-text.json'),
  ('hafs-5-53', 'hafs', 5, 53, 'وَيَقُولُ ٱلَّذِينَ ءَامَنُوٓا۟ أَهَٰٓؤُلَآءِ ٱلَّذِينَ أَقْسَمُوا۟ بِٱللَّهِ جَهْدَ أَيْمَٰنِهِمْ ۙ إِنَّهُمْ لَمَعَكُمْ ۚ حَبِطَتْ أَعْمَٰلُهُمْ فَأَصْبَحُوا۟ خَٰسِرِينَ', 'ويقول الذين ءامنوا أهؤلاء الذين أقسموا بالله جهد أيمنهم  إنهم لمعكم  حبطت أعملهم فأصبحوا خسرين', NULL, 117, 'local:hafs-text.json'),
  ('hafs-5-54', 'hafs', 5, 54, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ مَن يَرْتَدَّ مِنكُمْ عَن دِينِهِۦ فَسَوْفَ يَأْتِى ٱللَّهُ بِقَوْمٍۢ يُحِبُّهُمْ وَيُحِبُّونَهُۥٓ أَذِلَّةٍ عَلَى ٱلْمُؤْمِنِينَ أَعِزَّةٍ عَلَى ٱلْكَٰفِرِينَ يُجَٰهِدُونَ فِى سَبِيلِ ٱللَّهِ وَلَا يَخَافُونَ لَوْمَةَ لَآئِمٍۢ ۚ ذَٰلِكَ فَضْلُ ٱللَّهِ يُؤْتِيهِ مَن يَشَآءُ ۚ وَٱللَّهُ وَٰسِعٌ عَلِيمٌ', 'يأيها الذين ءامنوا من يرتد منكم عن دينه فسوف يأتى الله بقوم يحبهم ويحبونه أذلة على المؤمنين أعزة على الكفرين يجهدون فى سبيل الله ولا يخافون لومة لائم  ذلك فضل الله يؤتيه من يشاء  والله وسع عليم', NULL, 117, 'local:hafs-text.json'),
  ('hafs-5-55', 'hafs', 5, 55, 'إِنَّمَا وَلِيُّكُمُ ٱللَّهُ وَرَسُولُهُۥ وَٱلَّذِينَ ءَامَنُوا۟ ٱلَّذِينَ يُقِيمُونَ ٱلصَّلَوٰةَ وَيُؤْتُونَ ٱلزَّكَوٰةَ وَهُمْ رَٰكِعُونَ', 'إنما وليكم الله ورسوله والذين ءامنوا الذين يقيمون الصلوة ويؤتون الزكوة وهم ركعون', NULL, 117, 'local:hafs-text.json'),
  ('hafs-5-56', 'hafs', 5, 56, 'وَمَن يَتَوَلَّ ٱللَّهَ وَرَسُولَهُۥ وَٱلَّذِينَ ءَامَنُوا۟ فَإِنَّ حِزْبَ ٱللَّهِ هُمُ ٱلْغَٰلِبُونَ', 'ومن يتول الله ورسوله والذين ءامنوا فإن حزب الله هم الغلبون', NULL, 117, 'local:hafs-text.json'),
  ('hafs-5-57', 'hafs', 5, 57, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَتَّخِذُوا۟ ٱلَّذِينَ ٱتَّخَذُوا۟ دِينَكُمْ هُزُوًۭا وَلَعِبًۭا مِّنَ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَٰبَ مِن قَبْلِكُمْ وَٱلْكُفَّارَ أَوْلِيَآءَ ۚ وَٱتَّقُوا۟ ٱللَّهَ إِن كُنتُم مُّؤْمِنِينَ', 'يأيها الذين ءامنوا لا تتخذوا الذين اتخذوا دينكم هزوا ولعبا من الذين أوتوا الكتب من قبلكم والكفار أولياء  واتقوا الله إن كنتم مؤمنين', NULL, 117, 'local:hafs-text.json'),
  ('hafs-5-58', 'hafs', 5, 58, 'وَإِذَا نَادَيْتُمْ إِلَى ٱلصَّلَوٰةِ ٱتَّخَذُوهَا هُزُوًۭا وَلَعِبًۭا ۚ ذَٰلِكَ بِأَنَّهُمْ قَوْمٌۭ لَّا يَعْقِلُونَ', 'وإذا ناديتم إلى الصلوة اتخذوها هزوا ولعبا  ذلك بأنهم قوم لا يعقلون', NULL, 118, 'local:hafs-text.json'),
  ('hafs-5-59', 'hafs', 5, 59, 'قُلْ يَٰٓأَهْلَ ٱلْكِتَٰبِ هَلْ تَنقِمُونَ مِنَّآ إِلَّآ أَنْ ءَامَنَّا بِٱللَّهِ وَمَآ أُنزِلَ إِلَيْنَا وَمَآ أُنزِلَ مِن قَبْلُ وَأَنَّ أَكْثَرَكُمْ فَٰسِقُونَ', 'قل يأهل الكتب هل تنقمون منا إلا أن ءامنا بالله وما أنزل إلينا وما أنزل من قبل وأن أكثركم فسقون', NULL, 118, 'local:hafs-text.json'),
  ('hafs-5-60', 'hafs', 5, 60, 'قُلْ هَلْ أُنَبِّئُكُم بِشَرٍّۢ مِّن ذَٰلِكَ مَثُوبَةً عِندَ ٱللَّهِ ۚ مَن لَّعَنَهُ ٱللَّهُ وَغَضِبَ عَلَيْهِ وَجَعَلَ مِنْهُمُ ٱلْقِرَدَةَ وَٱلْخَنَازِيرَ وَعَبَدَ ٱلطَّٰغُوتَ ۚ أُو۟لَٰٓئِكَ شَرٌّۭ مَّكَانًۭا وَأَضَلُّ عَن سَوَآءِ ٱلسَّبِيلِ', 'قل هل أنبئكم بشر من ذلك مثوبة عند الله  من لعنه الله وغضب عليه وجعل منهم القردة والخنازير وعبد الطغوت  أولئك شر مكانا وأضل عن سواء السبيل', NULL, 118, 'local:hafs-text.json'),
  ('hafs-5-61', 'hafs', 5, 61, 'وَإِذَا جَآءُوكُمْ قَالُوٓا۟ ءَامَنَّا وَقَد دَّخَلُوا۟ بِٱلْكُفْرِ وَهُمْ قَدْ خَرَجُوا۟ بِهِۦ ۚ وَٱللَّهُ أَعْلَمُ بِمَا كَانُوا۟ يَكْتُمُونَ', 'وإذا جاءوكم قالوا ءامنا وقد دخلوا بالكفر وهم قد خرجوا به  والله أعلم بما كانوا يكتمون', NULL, 118, 'local:hafs-text.json'),
  ('hafs-5-62', 'hafs', 5, 62, 'وَتَرَىٰ كَثِيرًۭا مِّنْهُمْ يُسَٰرِعُونَ فِى ٱلْإِثْمِ وَٱلْعُدْوَٰنِ وَأَكْلِهِمُ ٱلسُّحْتَ ۚ لَبِئْسَ مَا كَانُوا۟ يَعْمَلُونَ', 'وترى كثيرا منهم يسرعون فى الإثم والعدون وأكلهم السحت  لبئس ما كانوا يعملون', NULL, 118, 'local:hafs-text.json'),
  ('hafs-5-63', 'hafs', 5, 63, 'لَوْلَا يَنْهَىٰهُمُ ٱلرَّبَّٰنِيُّونَ وَٱلْأَحْبَارُ عَن قَوْلِهِمُ ٱلْإِثْمَ وَأَكْلِهِمُ ٱلسُّحْتَ ۚ لَبِئْسَ مَا كَانُوا۟ يَصْنَعُونَ', 'لولا ينهىهم الربنيون والأحبار عن قولهم الإثم وأكلهم السحت  لبئس ما كانوا يصنعون', NULL, 118, 'local:hafs-text.json'),
  ('hafs-5-64', 'hafs', 5, 64, 'وَقَالَتِ ٱلْيَهُودُ يَدُ ٱللَّهِ مَغْلُولَةٌ ۚ غُلَّتْ أَيْدِيهِمْ وَلُعِنُوا۟ بِمَا قَالُوا۟ ۘ بَلْ يَدَاهُ مَبْسُوطَتَانِ يُنفِقُ كَيْفَ يَشَآءُ ۚ وَلَيَزِيدَنَّ كَثِيرًۭا مِّنْهُم مَّآ أُنزِلَ إِلَيْكَ مِن رَّبِّكَ طُغْيَٰنًۭا وَكُفْرًۭا ۚ وَأَلْقَيْنَا بَيْنَهُمُ ٱلْعَدَٰوَةَ وَٱلْبَغْضَآءَ إِلَىٰ يَوْمِ ٱلْقِيَٰمَةِ ۚ كُلَّمَآ أَوْقَدُوا۟ نَارًۭا لِّلْحَرْبِ أَطْفَأَهَا ٱللَّهُ ۚ وَيَسْعَوْنَ فِى ٱلْأَرْضِ فَسَادًۭا ۚ وَٱللَّهُ لَا يُحِبُّ ٱلْمُفْسِدِينَ', 'وقالت اليهود يد الله مغلولة  غلت أيديهم ولعنوا بما قالوا  بل يداه مبسوطتان ينفق كيف يشاء  وليزيدن كثيرا منهم ما أنزل إليك من ربك طغينا وكفرا  وألقينا بينهم العدوة والبغضاء إلى يوم القيمة  كلما أوقدوا نارا للحرب أطفأها الله  ويسعون فى الأرض فسادا  والله لا يحب المفسدين', NULL, 118, 'local:hafs-text.json'),
  ('hafs-5-65', 'hafs', 5, 65, 'وَلَوْ أَنَّ أَهْلَ ٱلْكِتَٰبِ ءَامَنُوا۟ وَٱتَّقَوْا۟ لَكَفَّرْنَا عَنْهُمْ سَيِّـَٔاتِهِمْ وَلَأَدْخَلْنَٰهُمْ جَنَّٰتِ ٱلنَّعِيمِ', 'ولو أن أهل الكتب ءامنوا واتقوا لكفرنا عنهم سياتهم ولأدخلنهم جنت النعيم', NULL, 119, 'local:hafs-text.json'),
  ('hafs-5-66', 'hafs', 5, 66, 'وَلَوْ أَنَّهُمْ أَقَامُوا۟ ٱلتَّوْرَىٰةَ وَٱلْإِنجِيلَ وَمَآ أُنزِلَ إِلَيْهِم مِّن رَّبِّهِمْ لَأَكَلُوا۟ مِن فَوْقِهِمْ وَمِن تَحْتِ أَرْجُلِهِم ۚ مِّنْهُمْ أُمَّةٌۭ مُّقْتَصِدَةٌۭ ۖ وَكَثِيرٌۭ مِّنْهُمْ سَآءَ مَا يَعْمَلُونَ', 'ولو أنهم أقاموا التورىة والإنجيل وما أنزل إليهم من ربهم لأكلوا من فوقهم ومن تحت أرجلهم  منهم أمة مقتصدة  وكثير منهم ساء ما يعملون', NULL, 119, 'local:hafs-text.json'),
  ('hafs-5-67', 'hafs', 5, 67, '۞ يَٰٓأَيُّهَا ٱلرَّسُولُ بَلِّغْ مَآ أُنزِلَ إِلَيْكَ مِن رَّبِّكَ ۖ وَإِن لَّمْ تَفْعَلْ فَمَا بَلَّغْتَ رِسَالَتَهُۥ ۚ وَٱللَّهُ يَعْصِمُكَ مِنَ ٱلنَّاسِ ۗ إِنَّ ٱللَّهَ لَا يَهْدِى ٱلْقَوْمَ ٱلْكَٰفِرِينَ', 'يأيها الرسول بلغ ما أنزل إليك من ربك  وإن لم تفعل فما بلغت رسالته  والله يعصمك من الناس  إن الله لا يهدى القوم الكفرين', NULL, 119, 'local:hafs-text.json'),
  ('hafs-5-68', 'hafs', 5, 68, 'قُلْ يَٰٓأَهْلَ ٱلْكِتَٰبِ لَسْتُمْ عَلَىٰ شَىْءٍ حَتَّىٰ تُقِيمُوا۟ ٱلتَّوْرَىٰةَ وَٱلْإِنجِيلَ وَمَآ أُنزِلَ إِلَيْكُم مِّن رَّبِّكُمْ ۗ وَلَيَزِيدَنَّ كَثِيرًۭا مِّنْهُم مَّآ أُنزِلَ إِلَيْكَ مِن رَّبِّكَ طُغْيَٰنًۭا وَكُفْرًۭا ۖ فَلَا تَأْسَ عَلَى ٱلْقَوْمِ ٱلْكَٰفِرِينَ', 'قل يأهل الكتب لستم على شىء حتى تقيموا التورىة والإنجيل وما أنزل إليكم من ربكم  وليزيدن كثيرا منهم ما أنزل إليك من ربك طغينا وكفرا  فلا تأس على القوم الكفرين', NULL, 119, 'local:hafs-text.json'),
  ('hafs-5-69', 'hafs', 5, 69, 'إِنَّ ٱلَّذِينَ ءَامَنُوا۟ وَٱلَّذِينَ هَادُوا۟ وَٱلصَّٰبِـُٔونَ وَٱلنَّصَٰرَىٰ مَنْ ءَامَنَ بِٱللَّهِ وَٱلْيَوْمِ ٱلْءَاخِرِ وَعَمِلَ صَٰلِحًۭا فَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ', 'إن الذين ءامنوا والذين هادوا والصبون والنصرى من ءامن بالله واليوم الءاخر وعمل صلحا فلا خوف عليهم ولا هم يحزنون', NULL, 119, 'local:hafs-text.json'),
  ('hafs-5-70', 'hafs', 5, 70, 'لَقَدْ أَخَذْنَا مِيثَٰقَ بَنِىٓ إِسْرَٰٓءِيلَ وَأَرْسَلْنَآ إِلَيْهِمْ رُسُلًۭا ۖ كُلَّمَا جَآءَهُمْ رَسُولٌۢ بِمَا لَا تَهْوَىٰٓ أَنفُسُهُمْ فَرِيقًۭا كَذَّبُوا۟ وَفَرِيقًۭا يَقْتُلُونَ', 'لقد أخذنا ميثق بنى إسرءيل وأرسلنا إليهم رسلا  كلما جاءهم رسول بما لا تهوى أنفسهم فريقا كذبوا وفريقا يقتلون', NULL, 119, 'local:hafs-text.json'),
  ('hafs-5-71', 'hafs', 5, 71, 'وَحَسِبُوٓا۟ أَلَّا تَكُونَ فِتْنَةٌۭ فَعَمُوا۟ وَصَمُّوا۟ ثُمَّ تَابَ ٱللَّهُ عَلَيْهِمْ ثُمَّ عَمُوا۟ وَصَمُّوا۟ كَثِيرٌۭ مِّنْهُمْ ۚ وَٱللَّهُ بَصِيرٌۢ بِمَا يَعْمَلُونَ', 'وحسبوا ألا تكون فتنة فعموا وصموا ثم تاب الله عليهم ثم عموا وصموا كثير منهم  والله بصير بما يعملون', NULL, 120, 'local:hafs-text.json'),
  ('hafs-5-72', 'hafs', 5, 72, 'لَقَدْ كَفَرَ ٱلَّذِينَ قَالُوٓا۟ إِنَّ ٱللَّهَ هُوَ ٱلْمَسِيحُ ٱبْنُ مَرْيَمَ ۖ وَقَالَ ٱلْمَسِيحُ يَٰبَنِىٓ إِسْرَٰٓءِيلَ ٱعْبُدُوا۟ ٱللَّهَ رَبِّى وَرَبَّكُمْ ۖ إِنَّهُۥ مَن يُشْرِكْ بِٱللَّهِ فَقَدْ حَرَّمَ ٱللَّهُ عَلَيْهِ ٱلْجَنَّةَ وَمَأْوَىٰهُ ٱلنَّارُ ۖ وَمَا لِلظَّٰلِمِينَ مِنْ أَنصَارٍۢ', 'لقد كفر الذين قالوا إن الله هو المسيح ابن مريم  وقال المسيح يبنى إسرءيل اعبدوا الله ربى وربكم  إنه من يشرك بالله فقد حرم الله عليه الجنة ومأوىه النار  وما للظلمين من أنصار', NULL, 120, 'local:hafs-text.json'),
  ('hafs-5-73', 'hafs', 5, 73, 'لَّقَدْ كَفَرَ ٱلَّذِينَ قَالُوٓا۟ إِنَّ ٱللَّهَ ثَالِثُ ثَلَٰثَةٍۢ ۘ وَمَا مِنْ إِلَٰهٍ إِلَّآ إِلَٰهٌۭ وَٰحِدٌۭ ۚ وَإِن لَّمْ يَنتَهُوا۟ عَمَّا يَقُولُونَ لَيَمَسَّنَّ ٱلَّذِينَ كَفَرُوا۟ مِنْهُمْ عَذَابٌ أَلِيمٌ', 'لقد كفر الذين قالوا إن الله ثالث ثلثة  وما من إله إلا إله وحد  وإن لم ينتهوا عما يقولون ليمسن الذين كفروا منهم عذاب أليم', NULL, 120, 'local:hafs-text.json'),
  ('hafs-5-74', 'hafs', 5, 74, 'أَفَلَا يَتُوبُونَ إِلَى ٱللَّهِ وَيَسْتَغْفِرُونَهُۥ ۚ وَٱللَّهُ غَفُورٌۭ رَّحِيمٌۭ', 'أفلا يتوبون إلى الله ويستغفرونه  والله غفور رحيم', NULL, 120, 'local:hafs-text.json'),
  ('hafs-5-75', 'hafs', 5, 75, 'مَّا ٱلْمَسِيحُ ٱبْنُ مَرْيَمَ إِلَّا رَسُولٌۭ قَدْ خَلَتْ مِن قَبْلِهِ ٱلرُّسُلُ وَأُمُّهُۥ صِدِّيقَةٌۭ ۖ كَانَا يَأْكُلَانِ ٱلطَّعَامَ ۗ ٱنظُرْ كَيْفَ نُبَيِّنُ لَهُمُ ٱلْءَايَٰتِ ثُمَّ ٱنظُرْ أَنَّىٰ يُؤْفَكُونَ', 'ما المسيح ابن مريم إلا رسول قد خلت من قبله الرسل وأمه صديقة  كانا يأكلان الطعام  انظر كيف نبين لهم الءايت ثم انظر أنى يؤفكون', NULL, 120, 'local:hafs-text.json'),
  ('hafs-5-76', 'hafs', 5, 76, 'قُلْ أَتَعْبُدُونَ مِن دُونِ ٱللَّهِ مَا لَا يَمْلِكُ لَكُمْ ضَرًّۭا وَلَا نَفْعًۭا ۚ وَٱللَّهُ هُوَ ٱلسَّمِيعُ ٱلْعَلِيمُ', 'قل أتعبدون من دون الله ما لا يملك لكم ضرا ولا نفعا  والله هو السميع العليم', NULL, 120, 'local:hafs-text.json'),
  ('hafs-5-77', 'hafs', 5, 77, 'قُلْ يَٰٓأَهْلَ ٱلْكِتَٰبِ لَا تَغْلُوا۟ فِى دِينِكُمْ غَيْرَ ٱلْحَقِّ وَلَا تَتَّبِعُوٓا۟ أَهْوَآءَ قَوْمٍۢ قَدْ ضَلُّوا۟ مِن قَبْلُ وَأَضَلُّوا۟ كَثِيرًۭا وَضَلُّوا۟ عَن سَوَآءِ ٱلسَّبِيلِ', 'قل يأهل الكتب لا تغلوا فى دينكم غير الحق ولا تتبعوا أهواء قوم قد ضلوا من قبل وأضلوا كثيرا وضلوا عن سواء السبيل', NULL, 121, 'local:hafs-text.json'),
  ('hafs-5-78', 'hafs', 5, 78, 'لُعِنَ ٱلَّذِينَ كَفَرُوا۟ مِنۢ بَنِىٓ إِسْرَٰٓءِيلَ عَلَىٰ لِسَانِ دَاوُۥدَ وَعِيسَى ٱبْنِ مَرْيَمَ ۚ ذَٰلِكَ بِمَا عَصَوا۟ وَّكَانُوا۟ يَعْتَدُونَ', 'لعن الذين كفروا من بنى إسرءيل على لسان داود وعيسى ابن مريم  ذلك بما عصوا وكانوا يعتدون', NULL, 121, 'local:hafs-text.json'),
  ('hafs-5-79', 'hafs', 5, 79, 'كَانُوا۟ لَا يَتَنَاهَوْنَ عَن مُّنكَرٍۢ فَعَلُوهُ ۚ لَبِئْسَ مَا كَانُوا۟ يَفْعَلُونَ', 'كانوا لا يتناهون عن منكر فعلوه  لبئس ما كانوا يفعلون', NULL, 121, 'local:hafs-text.json'),
  ('hafs-5-80', 'hafs', 5, 80, 'تَرَىٰ كَثِيرًۭا مِّنْهُمْ يَتَوَلَّوْنَ ٱلَّذِينَ كَفَرُوا۟ ۚ لَبِئْسَ مَا قَدَّمَتْ لَهُمْ أَنفُسُهُمْ أَن سَخِطَ ٱللَّهُ عَلَيْهِمْ وَفِى ٱلْعَذَابِ هُمْ خَٰلِدُونَ', 'ترى كثيرا منهم يتولون الذين كفروا  لبئس ما قدمت لهم أنفسهم أن سخط الله عليهم وفى العذاب هم خلدون', NULL, 121, 'local:hafs-text.json'),
  ('hafs-5-81', 'hafs', 5, 81, 'وَلَوْ كَانُوا۟ يُؤْمِنُونَ بِٱللَّهِ وَٱلنَّبِىِّ وَمَآ أُنزِلَ إِلَيْهِ مَا ٱتَّخَذُوهُمْ أَوْلِيَآءَ وَلَٰكِنَّ كَثِيرًۭا مِّنْهُمْ فَٰسِقُونَ', 'ولو كانوا يؤمنون بالله والنبى وما أنزل إليه ما اتخذوهم أولياء ولكن كثيرا منهم فسقون', NULL, 121, 'local:hafs-text.json'),
  ('hafs-5-82', 'hafs', 5, 82, '۞ لَتَجِدَنَّ أَشَدَّ ٱلنَّاسِ عَدَٰوَةًۭ لِّلَّذِينَ ءَامَنُوا۟ ٱلْيَهُودَ وَٱلَّذِينَ أَشْرَكُوا۟ ۖ وَلَتَجِدَنَّ أَقْرَبَهُم مَّوَدَّةًۭ لِّلَّذِينَ ءَامَنُوا۟ ٱلَّذِينَ قَالُوٓا۟ إِنَّا نَصَٰرَىٰ ۚ ذَٰلِكَ بِأَنَّ مِنْهُمْ قِسِّيسِينَ وَرُهْبَانًۭا وَأَنَّهُمْ لَا يَسْتَكْبِرُونَ', 'لتجدن أشد الناس عدوة للذين ءامنوا اليهود والذين أشركوا  ولتجدن أقربهم مودة للذين ءامنوا الذين قالوا إنا نصرى  ذلك بأن منهم قسيسين ورهبانا وأنهم لا يستكبرون', NULL, 121, 'local:hafs-text.json'),
  ('hafs-5-83', 'hafs', 5, 83, 'وَإِذَا سَمِعُوا۟ مَآ أُنزِلَ إِلَى ٱلرَّسُولِ تَرَىٰٓ أَعْيُنَهُمْ تَفِيضُ مِنَ ٱلدَّمْعِ مِمَّا عَرَفُوا۟ مِنَ ٱلْحَقِّ ۖ يَقُولُونَ رَبَّنَآ ءَامَنَّا فَٱكْتُبْنَا مَعَ ٱلشَّٰهِدِينَ', 'وإذا سمعوا ما أنزل إلى الرسول ترى أعينهم تفيض من الدمع مما عرفوا من الحق  يقولون ربنا ءامنا فاكتبنا مع الشهدين', NULL, 122, 'local:hafs-text.json'),
  ('hafs-5-84', 'hafs', 5, 84, 'وَمَا لَنَا لَا نُؤْمِنُ بِٱللَّهِ وَمَا جَآءَنَا مِنَ ٱلْحَقِّ وَنَطْمَعُ أَن يُدْخِلَنَا رَبُّنَا مَعَ ٱلْقَوْمِ ٱلصَّٰلِحِينَ', 'وما لنا لا نؤمن بالله وما جاءنا من الحق ونطمع أن يدخلنا ربنا مع القوم الصلحين', NULL, 122, 'local:hafs-text.json'),
  ('hafs-5-85', 'hafs', 5, 85, 'فَأَثَٰبَهُمُ ٱللَّهُ بِمَا قَالُوا۟ جَنَّٰتٍۢ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ خَٰلِدِينَ فِيهَا ۚ وَذَٰلِكَ جَزَآءُ ٱلْمُحْسِنِينَ', 'فأثبهم الله بما قالوا جنت تجرى من تحتها الأنهر خلدين فيها  وذلك جزاء المحسنين', NULL, 122, 'local:hafs-text.json'),
  ('hafs-5-86', 'hafs', 5, 86, 'وَٱلَّذِينَ كَفَرُوا۟ وَكَذَّبُوا۟ بِـَٔايَٰتِنَآ أُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلْجَحِيمِ', 'والذين كفروا وكذبوا بايتنا أولئك أصحب الجحيم', NULL, 122, 'local:hafs-text.json'),
  ('hafs-5-87', 'hafs', 5, 87, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تُحَرِّمُوا۟ طَيِّبَٰتِ مَآ أَحَلَّ ٱللَّهُ لَكُمْ وَلَا تَعْتَدُوٓا۟ ۚ إِنَّ ٱللَّهَ لَا يُحِبُّ ٱلْمُعْتَدِينَ', 'يأيها الذين ءامنوا لا تحرموا طيبت ما أحل الله لكم ولا تعتدوا  إن الله لا يحب المعتدين', NULL, 122, 'local:hafs-text.json'),
  ('hafs-5-88', 'hafs', 5, 88, 'وَكُلُوا۟ مِمَّا رَزَقَكُمُ ٱللَّهُ حَلَٰلًۭا طَيِّبًۭا ۚ وَٱتَّقُوا۟ ٱللَّهَ ٱلَّذِىٓ أَنتُم بِهِۦ مُؤْمِنُونَ', 'وكلوا مما رزقكم الله حللا طيبا  واتقوا الله الذى أنتم به مؤمنون', NULL, 122, 'local:hafs-text.json'),
  ('hafs-5-89', 'hafs', 5, 89, 'لَا يُؤَاخِذُكُمُ ٱللَّهُ بِٱللَّغْوِ فِىٓ أَيْمَٰنِكُمْ وَلَٰكِن يُؤَاخِذُكُم بِمَا عَقَّدتُّمُ ٱلْأَيْمَٰنَ ۖ فَكَفَّٰرَتُهُۥٓ إِطْعَامُ عَشَرَةِ مَسَٰكِينَ مِنْ أَوْسَطِ مَا تُطْعِمُونَ أَهْلِيكُمْ أَوْ كِسْوَتُهُمْ أَوْ تَحْرِيرُ رَقَبَةٍۢ ۖ فَمَن لَّمْ يَجِدْ فَصِيَامُ ثَلَٰثَةِ أَيَّامٍۢ ۚ ذَٰلِكَ كَفَّٰرَةُ أَيْمَٰنِكُمْ إِذَا حَلَفْتُمْ ۚ وَٱحْفَظُوٓا۟ أَيْمَٰنَكُمْ ۚ كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ لَكُمْ ءَايَٰتِهِۦ لَعَلَّكُمْ تَشْكُرُونَ', 'لا يؤاخذكم الله باللغو فى أيمنكم ولكن يؤاخذكم بما عقدتم الأيمن  فكفرته إطعام عشرة مسكين من أوسط ما تطعمون أهليكم أو كسوتهم أو تحرير رقبة  فمن لم يجد فصيام ثلثة أيام  ذلك كفرة أيمنكم إذا حلفتم  واحفظوا أيمنكم  كذلك يبين الله لكم ءايته لعلكم تشكرون', NULL, 122, 'local:hafs-text.json'),
  ('hafs-5-90', 'hafs', 5, 90, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِنَّمَا ٱلْخَمْرُ وَٱلْمَيْسِرُ وَٱلْأَنصَابُ وَٱلْأَزْلَٰمُ رِجْسٌۭ مِّنْ عَمَلِ ٱلشَّيْطَٰنِ فَٱجْتَنِبُوهُ لَعَلَّكُمْ تُفْلِحُونَ', 'يأيها الذين ءامنوا إنما الخمر والميسر والأنصاب والأزلم رجس من عمل الشيطن فاجتنبوه لعلكم تفلحون', NULL, 123, 'local:hafs-text.json'),
  ('hafs-5-91', 'hafs', 5, 91, 'إِنَّمَا يُرِيدُ ٱلشَّيْطَٰنُ أَن يُوقِعَ بَيْنَكُمُ ٱلْعَدَٰوَةَ وَٱلْبَغْضَآءَ فِى ٱلْخَمْرِ وَٱلْمَيْسِرِ وَيَصُدَّكُمْ عَن ذِكْرِ ٱللَّهِ وَعَنِ ٱلصَّلَوٰةِ ۖ فَهَلْ أَنتُم مُّنتَهُونَ', 'إنما يريد الشيطن أن يوقع بينكم العدوة والبغضاء فى الخمر والميسر ويصدكم عن ذكر الله وعن الصلوة  فهل أنتم منتهون', NULL, 123, 'local:hafs-text.json'),
  ('hafs-5-92', 'hafs', 5, 92, 'وَأَطِيعُوا۟ ٱللَّهَ وَأَطِيعُوا۟ ٱلرَّسُولَ وَٱحْذَرُوا۟ ۚ فَإِن تَوَلَّيْتُمْ فَٱعْلَمُوٓا۟ أَنَّمَا عَلَىٰ رَسُولِنَا ٱلْبَلَٰغُ ٱلْمُبِينُ', 'وأطيعوا الله وأطيعوا الرسول واحذروا  فإن توليتم فاعلموا أنما على رسولنا البلغ المبين', NULL, 123, 'local:hafs-text.json'),
  ('hafs-5-93', 'hafs', 5, 93, 'لَيْسَ عَلَى ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ جُنَاحٌۭ فِيمَا طَعِمُوٓا۟ إِذَا مَا ٱتَّقَوا۟ وَّءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ ثُمَّ ٱتَّقَوا۟ وَّءَامَنُوا۟ ثُمَّ ٱتَّقَوا۟ وَّأَحْسَنُوا۟ ۗ وَٱللَّهُ يُحِبُّ ٱلْمُحْسِنِينَ', 'ليس على الذين ءامنوا وعملوا الصلحت جناح فيما طعموا إذا ما اتقوا وءامنوا وعملوا الصلحت ثم اتقوا وءامنوا ثم اتقوا وأحسنوا  والله يحب المحسنين', NULL, 123, 'local:hafs-text.json'),
  ('hafs-5-94', 'hafs', 5, 94, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَيَبْلُوَنَّكُمُ ٱللَّهُ بِشَىْءٍۢ مِّنَ ٱلصَّيْدِ تَنَالُهُۥٓ أَيْدِيكُمْ وَرِمَاحُكُمْ لِيَعْلَمَ ٱللَّهُ مَن يَخَافُهُۥ بِٱلْغَيْبِ ۚ فَمَنِ ٱعْتَدَىٰ بَعْدَ ذَٰلِكَ فَلَهُۥ عَذَابٌ أَلِيمٌۭ', 'يأيها الذين ءامنوا ليبلونكم الله بشىء من الصيد تناله أيديكم ورماحكم ليعلم الله من يخافه بالغيب  فمن اعتدى بعد ذلك فله عذاب أليم', NULL, 123, 'local:hafs-text.json'),
  ('hafs-5-95', 'hafs', 5, 95, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَقْتُلُوا۟ ٱلصَّيْدَ وَأَنتُمْ حُرُمٌۭ ۚ وَمَن قَتَلَهُۥ مِنكُم مُّتَعَمِّدًۭا فَجَزَآءٌۭ مِّثْلُ مَا قَتَلَ مِنَ ٱلنَّعَمِ يَحْكُمُ بِهِۦ ذَوَا عَدْلٍۢ مِّنكُمْ هَدْيًۢا بَٰلِغَ ٱلْكَعْبَةِ أَوْ كَفَّٰرَةٌۭ طَعَامُ مَسَٰكِينَ أَوْ عَدْلُ ذَٰلِكَ صِيَامًۭا لِّيَذُوقَ وَبَالَ أَمْرِهِۦ ۗ عَفَا ٱللَّهُ عَمَّا سَلَفَ ۚ وَمَنْ عَادَ فَيَنتَقِمُ ٱللَّهُ مِنْهُ ۗ وَٱللَّهُ عَزِيزٌۭ ذُو ٱنتِقَامٍ', 'يأيها الذين ءامنوا لا تقتلوا الصيد وأنتم حرم  ومن قتله منكم متعمدا فجزاء مثل ما قتل من النعم يحكم به ذوا عدل منكم هديا بلغ الكعبة أو كفرة طعام مسكين أو عدل ذلك صياما ليذوق وبال أمره  عفا الله عما سلف  ومن عاد فينتقم الله منه  والله عزيز ذو انتقام', NULL, 123, 'local:hafs-text.json'),
  ('hafs-5-96', 'hafs', 5, 96, 'أُحِلَّ لَكُمْ صَيْدُ ٱلْبَحْرِ وَطَعَامُهُۥ مَتَٰعًۭا لَّكُمْ وَلِلسَّيَّارَةِ ۖ وَحُرِّمَ عَلَيْكُمْ صَيْدُ ٱلْبَرِّ مَا دُمْتُمْ حُرُمًۭا ۗ وَٱتَّقُوا۟ ٱللَّهَ ٱلَّذِىٓ إِلَيْهِ تُحْشَرُونَ', 'أحل لكم صيد البحر وطعامه متعا لكم وللسيارة  وحرم عليكم صيد البر ما دمتم حرما  واتقوا الله الذى إليه تحشرون', NULL, 124, 'local:hafs-text.json'),
  ('hafs-5-97', 'hafs', 5, 97, '۞ جَعَلَ ٱللَّهُ ٱلْكَعْبَةَ ٱلْبَيْتَ ٱلْحَرَامَ قِيَٰمًۭا لِّلنَّاسِ وَٱلشَّهْرَ ٱلْحَرَامَ وَٱلْهَدْىَ وَٱلْقَلَٰٓئِدَ ۚ ذَٰلِكَ لِتَعْلَمُوٓا۟ أَنَّ ٱللَّهَ يَعْلَمُ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ وَأَنَّ ٱللَّهَ بِكُلِّ شَىْءٍ عَلِيمٌ', 'جعل الله الكعبة البيت الحرام قيما للناس والشهر الحرام والهدى والقلئد  ذلك لتعلموا أن الله يعلم ما فى السموت وما فى الأرض وأن الله بكل شىء عليم', NULL, 124, 'local:hafs-text.json'),
  ('hafs-5-98', 'hafs', 5, 98, 'ٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ شَدِيدُ ٱلْعِقَابِ وَأَنَّ ٱللَّهَ غَفُورٌۭ رَّحِيمٌۭ', 'اعلموا أن الله شديد العقاب وأن الله غفور رحيم', NULL, 124, 'local:hafs-text.json'),
  ('hafs-5-99', 'hafs', 5, 99, 'مَّا عَلَى ٱلرَّسُولِ إِلَّا ٱلْبَلَٰغُ ۗ وَٱللَّهُ يَعْلَمُ مَا تُبْدُونَ وَمَا تَكْتُمُونَ', 'ما على الرسول إلا البلغ  والله يعلم ما تبدون وما تكتمون', NULL, 124, 'local:hafs-text.json'),
  ('hafs-5-100', 'hafs', 5, 100, 'قُل لَّا يَسْتَوِى ٱلْخَبِيثُ وَٱلطَّيِّبُ وَلَوْ أَعْجَبَكَ كَثْرَةُ ٱلْخَبِيثِ ۚ فَٱتَّقُوا۟ ٱللَّهَ يَٰٓأُو۟لِى ٱلْأَلْبَٰبِ لَعَلَّكُمْ تُفْلِحُونَ', 'قل لا يستوى الخبيث والطيب ولو أعجبك كثرة الخبيث  فاتقوا الله يأولى الألبب لعلكم تفلحون', NULL, 124, 'local:hafs-text.json'),
  ('hafs-5-101', 'hafs', 5, 101, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَسْـَٔلُوا۟ عَنْ أَشْيَآءَ إِن تُبْدَ لَكُمْ تَسُؤْكُمْ وَإِن تَسْـَٔلُوا۟ عَنْهَا حِينَ يُنَزَّلُ ٱلْقُرْءَانُ تُبْدَ لَكُمْ عَفَا ٱللَّهُ عَنْهَا ۗ وَٱللَّهُ غَفُورٌ حَلِيمٌۭ', 'يأيها الذين ءامنوا لا تسلوا عن أشياء إن تبد لكم تسؤكم وإن تسلوا عنها حين ينزل القرءان تبد لكم عفا الله عنها  والله غفور حليم', NULL, 124, 'local:hafs-text.json'),
  ('hafs-5-102', 'hafs', 5, 102, 'قَدْ سَأَلَهَا قَوْمٌۭ مِّن قَبْلِكُمْ ثُمَّ أَصْبَحُوا۟ بِهَا كَٰفِرِينَ', 'قد سألها قوم من قبلكم ثم أصبحوا بها كفرين', NULL, 124, 'local:hafs-text.json'),
  ('hafs-5-103', 'hafs', 5, 103, 'مَا جَعَلَ ٱللَّهُ مِنۢ بَحِيرَةٍۢ وَلَا سَآئِبَةٍۢ وَلَا وَصِيلَةٍۢ وَلَا حَامٍۢ ۙ وَلَٰكِنَّ ٱلَّذِينَ كَفَرُوا۟ يَفْتَرُونَ عَلَى ٱللَّهِ ٱلْكَذِبَ ۖ وَأَكْثَرُهُمْ لَا يَعْقِلُونَ', 'ما جعل الله من بحيرة ولا سائبة ولا وصيلة ولا حام  ولكن الذين كفروا يفترون على الله الكذب  وأكثرهم لا يعقلون', NULL, 124, 'local:hafs-text.json'),
  ('hafs-5-104', 'hafs', 5, 104, 'وَإِذَا قِيلَ لَهُمْ تَعَالَوْا۟ إِلَىٰ مَآ أَنزَلَ ٱللَّهُ وَإِلَى ٱلرَّسُولِ قَالُوا۟ حَسْبُنَا مَا وَجَدْنَا عَلَيْهِ ءَابَآءَنَآ ۚ أَوَلَوْ كَانَ ءَابَآؤُهُمْ لَا يَعْلَمُونَ شَيْـًۭٔا وَلَا يَهْتَدُونَ', 'وإذا قيل لهم تعالوا إلى ما أنزل الله وإلى الرسول قالوا حسبنا ما وجدنا عليه ءاباءنا  أولو كان ءاباؤهم لا يعلمون شيا ولا يهتدون', NULL, 125, 'local:hafs-text.json'),
  ('hafs-5-105', 'hafs', 5, 105, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ عَلَيْكُمْ أَنفُسَكُمْ ۖ لَا يَضُرُّكُم مَّن ضَلَّ إِذَا ٱهْتَدَيْتُمْ ۚ إِلَى ٱللَّهِ مَرْجِعُكُمْ جَمِيعًۭا فَيُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ', 'يأيها الذين ءامنوا عليكم أنفسكم  لا يضركم من ضل إذا اهتديتم  إلى الله مرجعكم جميعا فينبئكم بما كنتم تعملون', NULL, 125, 'local:hafs-text.json'),
  ('hafs-5-106', 'hafs', 5, 106, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ شَهَٰدَةُ بَيْنِكُمْ إِذَا حَضَرَ أَحَدَكُمُ ٱلْمَوْتُ حِينَ ٱلْوَصِيَّةِ ٱثْنَانِ ذَوَا عَدْلٍۢ مِّنكُمْ أَوْ ءَاخَرَانِ مِنْ غَيْرِكُمْ إِنْ أَنتُمْ ضَرَبْتُمْ فِى ٱلْأَرْضِ فَأَصَٰبَتْكُم مُّصِيبَةُ ٱلْمَوْتِ ۚ تَحْبِسُونَهُمَا مِنۢ بَعْدِ ٱلصَّلَوٰةِ فَيُقْسِمَانِ بِٱللَّهِ إِنِ ٱرْتَبْتُمْ لَا نَشْتَرِى بِهِۦ ثَمَنًۭا وَلَوْ كَانَ ذَا قُرْبَىٰ ۙ وَلَا نَكْتُمُ شَهَٰدَةَ ٱللَّهِ إِنَّآ إِذًۭا لَّمِنَ ٱلْءَاثِمِينَ', 'يأيها الذين ءامنوا شهدة بينكم إذا حضر أحدكم الموت حين الوصية اثنان ذوا عدل منكم أو ءاخران من غيركم إن أنتم ضربتم فى الأرض فأصبتكم مصيبة الموت  تحبسونهما من بعد الصلوة فيقسمان بالله إن ارتبتم لا نشترى به ثمنا ولو كان ذا قربى  ولا نكتم شهدة الله إنا إذا لمن الءاثمين', NULL, 125, 'local:hafs-text.json'),
  ('hafs-5-107', 'hafs', 5, 107, 'فَإِنْ عُثِرَ عَلَىٰٓ أَنَّهُمَا ٱسْتَحَقَّآ إِثْمًۭا فَـَٔاخَرَانِ يَقُومَانِ مَقَامَهُمَا مِنَ ٱلَّذِينَ ٱسْتَحَقَّ عَلَيْهِمُ ٱلْأَوْلَيَٰنِ فَيُقْسِمَانِ بِٱللَّهِ لَشَهَٰدَتُنَآ أَحَقُّ مِن شَهَٰدَتِهِمَا وَمَا ٱعْتَدَيْنَآ إِنَّآ إِذًۭا لَّمِنَ ٱلظَّٰلِمِينَ', 'فإن عثر على أنهما استحقا إثما فاخران يقومان مقامهما من الذين استحق عليهم الأولين فيقسمان بالله لشهدتنا أحق من شهدتهما وما اعتدينا إنا إذا لمن الظلمين', NULL, 125, 'local:hafs-text.json'),
  ('hafs-5-108', 'hafs', 5, 108, 'ذَٰلِكَ أَدْنَىٰٓ أَن يَأْتُوا۟ بِٱلشَّهَٰدَةِ عَلَىٰ وَجْهِهَآ أَوْ يَخَافُوٓا۟ أَن تُرَدَّ أَيْمَٰنٌۢ بَعْدَ أَيْمَٰنِهِمْ ۗ وَٱتَّقُوا۟ ٱللَّهَ وَٱسْمَعُوا۟ ۗ وَٱللَّهُ لَا يَهْدِى ٱلْقَوْمَ ٱلْفَٰسِقِينَ', 'ذلك أدنى أن يأتوا بالشهدة على وجهها أو يخافوا أن ترد أيمن بعد أيمنهم  واتقوا الله واسمعوا  والله لا يهدى القوم الفسقين', NULL, 125, 'local:hafs-text.json'),
  ('hafs-5-109', 'hafs', 5, 109, '۞ يَوْمَ يَجْمَعُ ٱللَّهُ ٱلرُّسُلَ فَيَقُولُ مَاذَآ أُجِبْتُمْ ۖ قَالُوا۟ لَا عِلْمَ لَنَآ ۖ إِنَّكَ أَنتَ عَلَّٰمُ ٱلْغُيُوبِ', 'يوم يجمع الله الرسل فيقول ماذا أجبتم  قالوا لا علم لنا  إنك أنت علم الغيوب', NULL, 126, 'local:hafs-text.json'),
  ('hafs-5-110', 'hafs', 5, 110, 'إِذْ قَالَ ٱللَّهُ يَٰعِيسَى ٱبْنَ مَرْيَمَ ٱذْكُرْ نِعْمَتِى عَلَيْكَ وَعَلَىٰ وَٰلِدَتِكَ إِذْ أَيَّدتُّكَ بِرُوحِ ٱلْقُدُسِ تُكَلِّمُ ٱلنَّاسَ فِى ٱلْمَهْدِ وَكَهْلًۭا ۖ وَإِذْ عَلَّمْتُكَ ٱلْكِتَٰبَ وَٱلْحِكْمَةَ وَٱلتَّوْرَىٰةَ وَٱلْإِنجِيلَ ۖ وَإِذْ تَخْلُقُ مِنَ ٱلطِّينِ كَهَيْـَٔةِ ٱلطَّيْرِ بِإِذْنِى فَتَنفُخُ فِيهَا فَتَكُونُ طَيْرًۢا بِإِذْنِى ۖ وَتُبْرِئُ ٱلْأَكْمَهَ وَٱلْأَبْرَصَ بِإِذْنِى ۖ وَإِذْ تُخْرِجُ ٱلْمَوْتَىٰ بِإِذْنِى ۖ وَإِذْ كَفَفْتُ بَنِىٓ إِسْرَٰٓءِيلَ عَنكَ إِذْ جِئْتَهُم بِٱلْبَيِّنَٰتِ فَقَالَ ٱلَّذِينَ كَفَرُوا۟ مِنْهُمْ إِنْ هَٰذَآ إِلَّا سِحْرٌۭ مُّبِينٌۭ', 'إذ قال الله يعيسى ابن مريم اذكر نعمتى عليك وعلى ولدتك إذ أيدتك بروح القدس تكلم الناس فى المهد وكهلا  وإذ علمتك الكتب والحكمة والتورىة والإنجيل  وإذ تخلق من الطين كهية الطير بإذنى فتنفخ فيها فتكون طيرا بإذنى  وتبرئ الأكمه والأبرص بإذنى  وإذ تخرج الموتى بإذنى  وإذ كففت بنى إسرءيل عنك إذ جئتهم بالبينت فقال الذين كفروا منهم إن هذا إلا سحر مبين', NULL, 126, 'local:hafs-text.json'),
  ('hafs-5-111', 'hafs', 5, 111, 'وَإِذْ أَوْحَيْتُ إِلَى ٱلْحَوَارِيِّۦنَ أَنْ ءَامِنُوا۟ بِى وَبِرَسُولِى قَالُوٓا۟ ءَامَنَّا وَٱشْهَدْ بِأَنَّنَا مُسْلِمُونَ', 'وإذ أوحيت إلى الحوارين أن ءامنوا بى وبرسولى قالوا ءامنا واشهد بأننا مسلمون', NULL, 126, 'local:hafs-text.json'),
  ('hafs-5-112', 'hafs', 5, 112, 'إِذْ قَالَ ٱلْحَوَارِيُّونَ يَٰعِيسَى ٱبْنَ مَرْيَمَ هَلْ يَسْتَطِيعُ رَبُّكَ أَن يُنَزِّلَ عَلَيْنَا مَآئِدَةًۭ مِّنَ ٱلسَّمَآءِ ۖ قَالَ ٱتَّقُوا۟ ٱللَّهَ إِن كُنتُم مُّؤْمِنِينَ', 'إذ قال الحواريون يعيسى ابن مريم هل يستطيع ربك أن ينزل علينا مائدة من السماء  قال اتقوا الله إن كنتم مؤمنين', NULL, 126, 'local:hafs-text.json'),
  ('hafs-5-113', 'hafs', 5, 113, 'قَالُوا۟ نُرِيدُ أَن نَّأْكُلَ مِنْهَا وَتَطْمَئِنَّ قُلُوبُنَا وَنَعْلَمَ أَن قَدْ صَدَقْتَنَا وَنَكُونَ عَلَيْهَا مِنَ ٱلشَّٰهِدِينَ', 'قالوا نريد أن نأكل منها وتطمئن قلوبنا ونعلم أن قد صدقتنا ونكون عليها من الشهدين', NULL, 126, 'local:hafs-text.json'),
  ('hafs-5-114', 'hafs', 5, 114, 'قَالَ عِيسَى ٱبْنُ مَرْيَمَ ٱللَّهُمَّ رَبَّنَآ أَنزِلْ عَلَيْنَا مَآئِدَةًۭ مِّنَ ٱلسَّمَآءِ تَكُونُ لَنَا عِيدًۭا لِّأَوَّلِنَا وَءَاخِرِنَا وَءَايَةًۭ مِّنكَ ۖ وَٱرْزُقْنَا وَأَنتَ خَيْرُ ٱلرَّٰزِقِينَ', 'قال عيسى ابن مريم اللهم ربنا أنزل علينا مائدة من السماء تكون لنا عيدا لأولنا وءاخرنا وءاية منك  وارزقنا وأنت خير الرزقين', NULL, 127, 'local:hafs-text.json'),
  ('hafs-5-115', 'hafs', 5, 115, 'قَالَ ٱللَّهُ إِنِّى مُنَزِّلُهَا عَلَيْكُمْ ۖ فَمَن يَكْفُرْ بَعْدُ مِنكُمْ فَإِنِّىٓ أُعَذِّبُهُۥ عَذَابًۭا لَّآ أُعَذِّبُهُۥٓ أَحَدًۭا مِّنَ ٱلْعَٰلَمِينَ', 'قال الله إنى منزلها عليكم  فمن يكفر بعد منكم فإنى أعذبه عذابا لا أعذبه أحدا من العلمين', NULL, 127, 'local:hafs-text.json'),
  ('hafs-5-116', 'hafs', 5, 116, 'وَإِذْ قَالَ ٱللَّهُ يَٰعِيسَى ٱبْنَ مَرْيَمَ ءَأَنتَ قُلْتَ لِلنَّاسِ ٱتَّخِذُونِى وَأُمِّىَ إِلَٰهَيْنِ مِن دُونِ ٱللَّهِ ۖ قَالَ سُبْحَٰنَكَ مَا يَكُونُ لِىٓ أَنْ أَقُولَ مَا لَيْسَ لِى بِحَقٍّ ۚ إِن كُنتُ قُلْتُهُۥ فَقَدْ عَلِمْتَهُۥ ۚ تَعْلَمُ مَا فِى نَفْسِى وَلَآ أَعْلَمُ مَا فِى نَفْسِكَ ۚ إِنَّكَ أَنتَ عَلَّٰمُ ٱلْغُيُوبِ', 'وإذ قال الله يعيسى ابن مريم ءأنت قلت للناس اتخذونى وأمى إلهين من دون الله  قال سبحنك ما يكون لى أن أقول ما ليس لى بحق  إن كنت قلته فقد علمته  تعلم ما فى نفسى ولا أعلم ما فى نفسك  إنك أنت علم الغيوب', NULL, 127, 'local:hafs-text.json'),
  ('hafs-5-117', 'hafs', 5, 117, 'مَا قُلْتُ لَهُمْ إِلَّا مَآ أَمَرْتَنِى بِهِۦٓ أَنِ ٱعْبُدُوا۟ ٱللَّهَ رَبِّى وَرَبَّكُمْ ۚ وَكُنتُ عَلَيْهِمْ شَهِيدًۭا مَّا دُمْتُ فِيهِمْ ۖ فَلَمَّا تَوَفَّيْتَنِى كُنتَ أَنتَ ٱلرَّقِيبَ عَلَيْهِمْ ۚ وَأَنتَ عَلَىٰ كُلِّ شَىْءٍۢ شَهِيدٌ', 'ما قلت لهم إلا ما أمرتنى به أن اعبدوا الله ربى وربكم  وكنت عليهم شهيدا ما دمت فيهم  فلما توفيتنى كنت أنت الرقيب عليهم  وأنت على كل شىء شهيد', NULL, 127, 'local:hafs-text.json'),
  ('hafs-5-118', 'hafs', 5, 118, 'إِن تُعَذِّبْهُمْ فَإِنَّهُمْ عِبَادُكَ ۖ وَإِن تَغْفِرْ لَهُمْ فَإِنَّكَ أَنتَ ٱلْعَزِيزُ ٱلْحَكِيمُ', 'إن تعذبهم فإنهم عبادك  وإن تغفر لهم فإنك أنت العزيز الحكيم', NULL, 127, 'local:hafs-text.json'),
  ('hafs-5-119', 'hafs', 5, 119, 'قَالَ ٱللَّهُ هَٰذَا يَوْمُ يَنفَعُ ٱلصَّٰدِقِينَ صِدْقُهُمْ ۚ لَهُمْ جَنَّٰتٌۭ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ خَٰلِدِينَ فِيهَآ أَبَدًۭا ۚ رَّضِىَ ٱللَّهُ عَنْهُمْ وَرَضُوا۟ عَنْهُ ۚ ذَٰلِكَ ٱلْفَوْزُ ٱلْعَظِيمُ', 'قال الله هذا يوم ينفع الصدقين صدقهم  لهم جنت تجرى من تحتها الأنهر خلدين فيها أبدا  رضى الله عنهم ورضوا عنه  ذلك الفوز العظيم', NULL, 127, 'local:hafs-text.json'),
  ('hafs-5-120', 'hafs', 5, 120, 'لِلَّهِ مُلْكُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَمَا فِيهِنَّ ۚ وَهُوَ عَلَىٰ كُلِّ شَىْءٍۢ قَدِيرٌۢ', 'لله ملك السموت والأرض وما فيهن  وهو على كل شىء قدير', NULL, 127, 'local:hafs-text.json'),
  ('hafs-6-1', 'hafs', 6, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ ٱلْحَمْدُ لِلَّهِ ٱلَّذِى خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ وَجَعَلَ ٱلظُّلُمَٰتِ وَٱلنُّورَ ۖ ثُمَّ ٱلَّذِينَ كَفَرُوا۟ بِرَبِّهِمْ يَعْدِلُونَ', 'بسم الله الرحمن الرحيم الحمد لله الذى خلق السموت والأرض وجعل الظلمت والنور  ثم الذين كفروا بربهم يعدلون', NULL, 128, 'local:hafs-text.json'),
  ('hafs-6-2', 'hafs', 6, 2, 'هُوَ ٱلَّذِى خَلَقَكُم مِّن طِينٍۢ ثُمَّ قَضَىٰٓ أَجَلًۭا ۖ وَأَجَلٌۭ مُّسَمًّى عِندَهُۥ ۖ ثُمَّ أَنتُمْ تَمْتَرُونَ', 'هو الذى خلقكم من طين ثم قضى أجلا  وأجل مسمى عنده  ثم أنتم تمترون', NULL, 128, 'local:hafs-text.json'),
  ('hafs-6-3', 'hafs', 6, 3, 'وَهُوَ ٱللَّهُ فِى ٱلسَّمَٰوَٰتِ وَفِى ٱلْأَرْضِ ۖ يَعْلَمُ سِرَّكُمْ وَجَهْرَكُمْ وَيَعْلَمُ مَا تَكْسِبُونَ', 'وهو الله فى السموت وفى الأرض  يعلم سركم وجهركم ويعلم ما تكسبون', NULL, 128, 'local:hafs-text.json'),
  ('hafs-6-4', 'hafs', 6, 4, 'وَمَا تَأْتِيهِم مِّنْ ءَايَةٍۢ مِّنْ ءَايَٰتِ رَبِّهِمْ إِلَّا كَانُوا۟ عَنْهَا مُعْرِضِينَ', 'وما تأتيهم من ءاية من ءايت ربهم إلا كانوا عنها معرضين', NULL, 128, 'local:hafs-text.json'),
  ('hafs-6-5', 'hafs', 6, 5, 'فَقَدْ كَذَّبُوا۟ بِٱلْحَقِّ لَمَّا جَآءَهُمْ ۖ فَسَوْفَ يَأْتِيهِمْ أَنۢبَٰٓؤُا۟ مَا كَانُوا۟ بِهِۦ يَسْتَهْزِءُونَ', 'فقد كذبوا بالحق لما جاءهم  فسوف يأتيهم أنبؤا ما كانوا به يستهزءون', NULL, 128, 'local:hafs-text.json'),
  ('hafs-6-6', 'hafs', 6, 6, 'أَلَمْ يَرَوْا۟ كَمْ أَهْلَكْنَا مِن قَبْلِهِم مِّن قَرْنٍۢ مَّكَّنَّٰهُمْ فِى ٱلْأَرْضِ مَا لَمْ نُمَكِّن لَّكُمْ وَأَرْسَلْنَا ٱلسَّمَآءَ عَلَيْهِم مِّدْرَارًۭا وَجَعَلْنَا ٱلْأَنْهَٰرَ تَجْرِى مِن تَحْتِهِمْ فَأَهْلَكْنَٰهُم بِذُنُوبِهِمْ وَأَنشَأْنَا مِنۢ بَعْدِهِمْ قَرْنًا ءَاخَرِينَ', 'ألم يروا كم أهلكنا من قبلهم من قرن مكنهم فى الأرض ما لم نمكن لكم وأرسلنا السماء عليهم مدرارا وجعلنا الأنهر تجرى من تحتهم فأهلكنهم بذنوبهم وأنشأنا من بعدهم قرنا ءاخرين', NULL, 128, 'local:hafs-text.json'),
  ('hafs-6-7', 'hafs', 6, 7, 'وَلَوْ نَزَّلْنَا عَلَيْكَ كِتَٰبًۭا فِى قِرْطَاسٍۢ فَلَمَسُوهُ بِأَيْدِيهِمْ لَقَالَ ٱلَّذِينَ كَفَرُوٓا۟ إِنْ هَٰذَآ إِلَّا سِحْرٌۭ مُّبِينٌۭ', 'ولو نزلنا عليك كتبا فى قرطاس فلمسوه بأيديهم لقال الذين كفروا إن هذا إلا سحر مبين', NULL, 128, 'local:hafs-text.json'),
  ('hafs-6-8', 'hafs', 6, 8, 'وَقَالُوا۟ لَوْلَآ أُنزِلَ عَلَيْهِ مَلَكٌۭ ۖ وَلَوْ أَنزَلْنَا مَلَكًۭا لَّقُضِىَ ٱلْأَمْرُ ثُمَّ لَا يُنظَرُونَ', 'وقالوا لولا أنزل عليه ملك  ولو أنزلنا ملكا لقضى الأمر ثم لا ينظرون', NULL, 128, 'local:hafs-text.json'),
  ('hafs-6-9', 'hafs', 6, 9, 'وَلَوْ جَعَلْنَٰهُ مَلَكًۭا لَّجَعَلْنَٰهُ رَجُلًۭا وَلَلَبَسْنَا عَلَيْهِم مَّا يَلْبِسُونَ', 'ولو جعلنه ملكا لجعلنه رجلا وللبسنا عليهم ما يلبسون', NULL, 129, 'local:hafs-text.json'),
  ('hafs-6-10', 'hafs', 6, 10, 'وَلَقَدِ ٱسْتُهْزِئَ بِرُسُلٍۢ مِّن قَبْلِكَ فَحَاقَ بِٱلَّذِينَ سَخِرُوا۟ مِنْهُم مَّا كَانُوا۟ بِهِۦ يَسْتَهْزِءُونَ', 'ولقد استهزئ برسل من قبلك فحاق بالذين سخروا منهم ما كانوا به يستهزءون', NULL, 129, 'local:hafs-text.json'),
  ('hafs-6-11', 'hafs', 6, 11, 'قُلْ سِيرُوا۟ فِى ٱلْأَرْضِ ثُمَّ ٱنظُرُوا۟ كَيْفَ كَانَ عَٰقِبَةُ ٱلْمُكَذِّبِينَ', 'قل سيروا فى الأرض ثم انظروا كيف كان عقبة المكذبين', NULL, 129, 'local:hafs-text.json')
insert into public.ayahs (id, riwayah, surah_number, ayah_number, text, simple_text, juz, page, source) values
  ('hafs-6-12', 'hafs', 6, 12, 'قُل لِّمَن مَّا فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ ۖ قُل لِّلَّهِ ۚ كَتَبَ عَلَىٰ نَفْسِهِ ٱلرَّحْمَةَ ۚ لَيَجْمَعَنَّكُمْ إِلَىٰ يَوْمِ ٱلْقِيَٰمَةِ لَا رَيْبَ فِيهِ ۚ ٱلَّذِينَ خَسِرُوٓا۟ أَنفُسَهُمْ فَهُمْ لَا يُؤْمِنُونَ', 'قل لمن ما فى السموت والأرض  قل لله  كتب على نفسه الرحمة  ليجمعنكم إلى يوم القيمة لا ريب فيه  الذين خسروا أنفسهم فهم لا يؤمنون', NULL, 129, 'local:hafs-text.json'),
  ('hafs-6-13', 'hafs', 6, 13, '۞ وَلَهُۥ مَا سَكَنَ فِى ٱلَّيْلِ وَٱلنَّهَارِ ۚ وَهُوَ ٱلسَّمِيعُ ٱلْعَلِيمُ', 'وله ما سكن فى اليل والنهار  وهو السميع العليم', NULL, 129, 'local:hafs-text.json'),
  ('hafs-6-14', 'hafs', 6, 14, 'قُلْ أَغَيْرَ ٱللَّهِ أَتَّخِذُ وَلِيًّۭا فَاطِرِ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَهُوَ يُطْعِمُ وَلَا يُطْعَمُ ۗ قُلْ إِنِّىٓ أُمِرْتُ أَنْ أَكُونَ أَوَّلَ مَنْ أَسْلَمَ ۖ وَلَا تَكُونَنَّ مِنَ ٱلْمُشْرِكِينَ', 'قل أغير الله أتخذ وليا فاطر السموت والأرض وهو يطعم ولا يطعم  قل إنى أمرت أن أكون أول من أسلم  ولا تكونن من المشركين', NULL, 129, 'local:hafs-text.json'),
  ('hafs-6-15', 'hafs', 6, 15, 'قُلْ إِنِّىٓ أَخَافُ إِنْ عَصَيْتُ رَبِّى عَذَابَ يَوْمٍ عَظِيمٍۢ', 'قل إنى أخاف إن عصيت ربى عذاب يوم عظيم', NULL, 129, 'local:hafs-text.json'),
  ('hafs-6-16', 'hafs', 6, 16, 'مَّن يُصْرَفْ عَنْهُ يَوْمَئِذٍۢ فَقَدْ رَحِمَهُۥ ۚ وَذَٰلِكَ ٱلْفَوْزُ ٱلْمُبِينُ', 'من يصرف عنه يومئذ فقد رحمه  وذلك الفوز المبين', NULL, 129, 'local:hafs-text.json'),
  ('hafs-6-17', 'hafs', 6, 17, 'وَإِن يَمْسَسْكَ ٱللَّهُ بِضُرٍّۢ فَلَا كَاشِفَ لَهُۥٓ إِلَّا هُوَ ۖ وَإِن يَمْسَسْكَ بِخَيْرٍۢ فَهُوَ عَلَىٰ كُلِّ شَىْءٍۢ قَدِيرٌۭ', 'وإن يمسسك الله بضر فلا كاشف له إلا هو  وإن يمسسك بخير فهو على كل شىء قدير', NULL, 129, 'local:hafs-text.json'),
  ('hafs-6-18', 'hafs', 6, 18, 'وَهُوَ ٱلْقَاهِرُ فَوْقَ عِبَادِهِۦ ۚ وَهُوَ ٱلْحَكِيمُ ٱلْخَبِيرُ', 'وهو القاهر فوق عباده  وهو الحكيم الخبير', NULL, 129, 'local:hafs-text.json'),
  ('hafs-6-19', 'hafs', 6, 19, 'قُلْ أَىُّ شَىْءٍ أَكْبَرُ شَهَٰدَةًۭ ۖ قُلِ ٱللَّهُ ۖ شَهِيدٌۢ بَيْنِى وَبَيْنَكُمْ ۚ وَأُوحِىَ إِلَىَّ هَٰذَا ٱلْقُرْءَانُ لِأُنذِرَكُم بِهِۦ وَمَنۢ بَلَغَ ۚ أَئِنَّكُمْ لَتَشْهَدُونَ أَنَّ مَعَ ٱللَّهِ ءَالِهَةً أُخْرَىٰ ۚ قُل لَّآ أَشْهَدُ ۚ قُلْ إِنَّمَا هُوَ إِلَٰهٌۭ وَٰحِدٌۭ وَإِنَّنِى بَرِىٓءٌۭ مِّمَّا تُشْرِكُونَ', 'قل أى شىء أكبر شهدة  قل الله  شهيد بينى وبينكم  وأوحى إلى هذا القرءان لأنذركم به ومن بلغ  أئنكم لتشهدون أن مع الله ءالهة أخرى  قل لا أشهد  قل إنما هو إله وحد وإننى برىء مما تشركون', NULL, 130, 'local:hafs-text.json'),
  ('hafs-6-20', 'hafs', 6, 20, 'ٱلَّذِينَ ءَاتَيْنَٰهُمُ ٱلْكِتَٰبَ يَعْرِفُونَهُۥ كَمَا يَعْرِفُونَ أَبْنَآءَهُمُ ۘ ٱلَّذِينَ خَسِرُوٓا۟ أَنفُسَهُمْ فَهُمْ لَا يُؤْمِنُونَ', 'الذين ءاتينهم الكتب يعرفونه كما يعرفون أبناءهم  الذين خسروا أنفسهم فهم لا يؤمنون', NULL, 130, 'local:hafs-text.json'),
  ('hafs-6-21', 'hafs', 6, 21, 'وَمَنْ أَظْلَمُ مِمَّنِ ٱفْتَرَىٰ عَلَى ٱللَّهِ كَذِبًا أَوْ كَذَّبَ بِـَٔايَٰتِهِۦٓ ۗ إِنَّهُۥ لَا يُفْلِحُ ٱلظَّٰلِمُونَ', 'ومن أظلم ممن افترى على الله كذبا أو كذب بايته  إنه لا يفلح الظلمون', NULL, 130, 'local:hafs-text.json'),
  ('hafs-6-22', 'hafs', 6, 22, 'وَيَوْمَ نَحْشُرُهُمْ جَمِيعًۭا ثُمَّ نَقُولُ لِلَّذِينَ أَشْرَكُوٓا۟ أَيْنَ شُرَكَآؤُكُمُ ٱلَّذِينَ كُنتُمْ تَزْعُمُونَ', 'ويوم نحشرهم جميعا ثم نقول للذين أشركوا أين شركاؤكم الذين كنتم تزعمون', NULL, 130, 'local:hafs-text.json'),
  ('hafs-6-23', 'hafs', 6, 23, 'ثُمَّ لَمْ تَكُن فِتْنَتُهُمْ إِلَّآ أَن قَالُوا۟ وَٱللَّهِ رَبِّنَا مَا كُنَّا مُشْرِكِينَ', 'ثم لم تكن فتنتهم إلا أن قالوا والله ربنا ما كنا مشركين', NULL, 130, 'local:hafs-text.json'),
  ('hafs-6-24', 'hafs', 6, 24, 'ٱنظُرْ كَيْفَ كَذَبُوا۟ عَلَىٰٓ أَنفُسِهِمْ ۚ وَضَلَّ عَنْهُم مَّا كَانُوا۟ يَفْتَرُونَ', 'انظر كيف كذبوا على أنفسهم  وضل عنهم ما كانوا يفترون', NULL, 130, 'local:hafs-text.json'),
  ('hafs-6-25', 'hafs', 6, 25, 'وَمِنْهُم مَّن يَسْتَمِعُ إِلَيْكَ ۖ وَجَعَلْنَا عَلَىٰ قُلُوبِهِمْ أَكِنَّةً أَن يَفْقَهُوهُ وَفِىٓ ءَاذَانِهِمْ وَقْرًۭا ۚ وَإِن يَرَوْا۟ كُلَّ ءَايَةٍۢ لَّا يُؤْمِنُوا۟ بِهَا ۚ حَتَّىٰٓ إِذَا جَآءُوكَ يُجَٰدِلُونَكَ يَقُولُ ٱلَّذِينَ كَفَرُوٓا۟ إِنْ هَٰذَآ إِلَّآ أَسَٰطِيرُ ٱلْأَوَّلِينَ', 'ومنهم من يستمع إليك  وجعلنا على قلوبهم أكنة أن يفقهوه وفى ءاذانهم وقرا  وإن يروا كل ءاية لا يؤمنوا بها  حتى إذا جاءوك يجدلونك يقول الذين كفروا إن هذا إلا أسطير الأولين', NULL, 130, 'local:hafs-text.json'),
  ('hafs-6-26', 'hafs', 6, 26, 'وَهُمْ يَنْهَوْنَ عَنْهُ وَيَنْـَٔوْنَ عَنْهُ ۖ وَإِن يُهْلِكُونَ إِلَّآ أَنفُسَهُمْ وَمَا يَشْعُرُونَ', 'وهم ينهون عنه وينون عنه  وإن يهلكون إلا أنفسهم وما يشعرون', NULL, 130, 'local:hafs-text.json'),
  ('hafs-6-27', 'hafs', 6, 27, 'وَلَوْ تَرَىٰٓ إِذْ وُقِفُوا۟ عَلَى ٱلنَّارِ فَقَالُوا۟ يَٰلَيْتَنَا نُرَدُّ وَلَا نُكَذِّبَ بِـَٔايَٰتِ رَبِّنَا وَنَكُونَ مِنَ ٱلْمُؤْمِنِينَ', 'ولو ترى إذ وقفوا على النار فقالوا يليتنا نرد ولا نكذب بايت ربنا ونكون من المؤمنين', NULL, 130, 'local:hafs-text.json'),
  ('hafs-6-28', 'hafs', 6, 28, 'بَلْ بَدَا لَهُم مَّا كَانُوا۟ يُخْفُونَ مِن قَبْلُ ۖ وَلَوْ رُدُّوا۟ لَعَادُوا۟ لِمَا نُهُوا۟ عَنْهُ وَإِنَّهُمْ لَكَٰذِبُونَ', 'بل بدا لهم ما كانوا يخفون من قبل  ولو ردوا لعادوا لما نهوا عنه وإنهم لكذبون', NULL, 131, 'local:hafs-text.json'),
  ('hafs-6-29', 'hafs', 6, 29, 'وَقَالُوٓا۟ إِنْ هِىَ إِلَّا حَيَاتُنَا ٱلدُّنْيَا وَمَا نَحْنُ بِمَبْعُوثِينَ', 'وقالوا إن هى إلا حياتنا الدنيا وما نحن بمبعوثين', NULL, 131, 'local:hafs-text.json'),
  ('hafs-6-30', 'hafs', 6, 30, 'وَلَوْ تَرَىٰٓ إِذْ وُقِفُوا۟ عَلَىٰ رَبِّهِمْ ۚ قَالَ أَلَيْسَ هَٰذَا بِٱلْحَقِّ ۚ قَالُوا۟ بَلَىٰ وَرَبِّنَا ۚ قَالَ فَذُوقُوا۟ ٱلْعَذَابَ بِمَا كُنتُمْ تَكْفُرُونَ', 'ولو ترى إذ وقفوا على ربهم  قال أليس هذا بالحق  قالوا بلى وربنا  قال فذوقوا العذاب بما كنتم تكفرون', NULL, 131, 'local:hafs-text.json'),
  ('hafs-6-31', 'hafs', 6, 31, 'قَدْ خَسِرَ ٱلَّذِينَ كَذَّبُوا۟ بِلِقَآءِ ٱللَّهِ ۖ حَتَّىٰٓ إِذَا جَآءَتْهُمُ ٱلسَّاعَةُ بَغْتَةًۭ قَالُوا۟ يَٰحَسْرَتَنَا عَلَىٰ مَا فَرَّطْنَا فِيهَا وَهُمْ يَحْمِلُونَ أَوْزَارَهُمْ عَلَىٰ ظُهُورِهِمْ ۚ أَلَا سَآءَ مَا يَزِرُونَ', 'قد خسر الذين كذبوا بلقاء الله  حتى إذا جاءتهم الساعة بغتة قالوا يحسرتنا على ما فرطنا فيها وهم يحملون أوزارهم على ظهورهم  ألا ساء ما يزرون', NULL, 131, 'local:hafs-text.json'),
  ('hafs-6-32', 'hafs', 6, 32, 'وَمَا ٱلْحَيَوٰةُ ٱلدُّنْيَآ إِلَّا لَعِبٌۭ وَلَهْوٌۭ ۖ وَلَلدَّارُ ٱلْءَاخِرَةُ خَيْرٌۭ لِّلَّذِينَ يَتَّقُونَ ۗ أَفَلَا تَعْقِلُونَ', 'وما الحيوة الدنيا إلا لعب ولهو  وللدار الءاخرة خير للذين يتقون  أفلا تعقلون', NULL, 131, 'local:hafs-text.json'),
  ('hafs-6-33', 'hafs', 6, 33, 'قَدْ نَعْلَمُ إِنَّهُۥ لَيَحْزُنُكَ ٱلَّذِى يَقُولُونَ ۖ فَإِنَّهُمْ لَا يُكَذِّبُونَكَ وَلَٰكِنَّ ٱلظَّٰلِمِينَ بِـَٔايَٰتِ ٱللَّهِ يَجْحَدُونَ', 'قد نعلم إنه ليحزنك الذى يقولون  فإنهم لا يكذبونك ولكن الظلمين بايت الله يجحدون', NULL, 131, 'local:hafs-text.json'),
  ('hafs-6-34', 'hafs', 6, 34, 'وَلَقَدْ كُذِّبَتْ رُسُلٌۭ مِّن قَبْلِكَ فَصَبَرُوا۟ عَلَىٰ مَا كُذِّبُوا۟ وَأُوذُوا۟ حَتَّىٰٓ أَتَىٰهُمْ نَصْرُنَا ۚ وَلَا مُبَدِّلَ لِكَلِمَٰتِ ٱللَّهِ ۚ وَلَقَدْ جَآءَكَ مِن نَّبَإِى۟ ٱلْمُرْسَلِينَ', 'ولقد كذبت رسل من قبلك فصبروا على ما كذبوا وأوذوا حتى أتىهم نصرنا  ولا مبدل لكلمت الله  ولقد جاءك من نبإى المرسلين', NULL, 131, 'local:hafs-text.json'),
  ('hafs-6-35', 'hafs', 6, 35, 'وَإِن كَانَ كَبُرَ عَلَيْكَ إِعْرَاضُهُمْ فَإِنِ ٱسْتَطَعْتَ أَن تَبْتَغِىَ نَفَقًۭا فِى ٱلْأَرْضِ أَوْ سُلَّمًۭا فِى ٱلسَّمَآءِ فَتَأْتِيَهُم بِـَٔايَةٍۢ ۚ وَلَوْ شَآءَ ٱللَّهُ لَجَمَعَهُمْ عَلَى ٱلْهُدَىٰ ۚ فَلَا تَكُونَنَّ مِنَ ٱلْجَٰهِلِينَ', 'وإن كان كبر عليك إعراضهم فإن استطعت أن تبتغى نفقا فى الأرض أو سلما فى السماء فتأتيهم باية  ولو شاء الله لجمعهم على الهدى  فلا تكونن من الجهلين', NULL, 131, 'local:hafs-text.json'),
  ('hafs-6-36', 'hafs', 6, 36, '۞ إِنَّمَا يَسْتَجِيبُ ٱلَّذِينَ يَسْمَعُونَ ۘ وَٱلْمَوْتَىٰ يَبْعَثُهُمُ ٱللَّهُ ثُمَّ إِلَيْهِ يُرْجَعُونَ', 'إنما يستجيب الذين يسمعون  والموتى يبعثهم الله ثم إليه يرجعون', NULL, 132, 'local:hafs-text.json'),
  ('hafs-6-37', 'hafs', 6, 37, 'وَقَالُوا۟ لَوْلَا نُزِّلَ عَلَيْهِ ءَايَةٌۭ مِّن رَّبِّهِۦ ۚ قُلْ إِنَّ ٱللَّهَ قَادِرٌ عَلَىٰٓ أَن يُنَزِّلَ ءَايَةًۭ وَلَٰكِنَّ أَكْثَرَهُمْ لَا يَعْلَمُونَ', 'وقالوا لولا نزل عليه ءاية من ربه  قل إن الله قادر على أن ينزل ءاية ولكن أكثرهم لا يعلمون', NULL, 132, 'local:hafs-text.json'),
  ('hafs-6-38', 'hafs', 6, 38, 'وَمَا مِن دَآبَّةٍۢ فِى ٱلْأَرْضِ وَلَا طَٰٓئِرٍۢ يَطِيرُ بِجَنَاحَيْهِ إِلَّآ أُمَمٌ أَمْثَالُكُم ۚ مَّا فَرَّطْنَا فِى ٱلْكِتَٰبِ مِن شَىْءٍۢ ۚ ثُمَّ إِلَىٰ رَبِّهِمْ يُحْشَرُونَ', 'وما من دابة فى الأرض ولا طئر يطير بجناحيه إلا أمم أمثالكم  ما فرطنا فى الكتب من شىء  ثم إلى ربهم يحشرون', NULL, 132, 'local:hafs-text.json'),
  ('hafs-6-39', 'hafs', 6, 39, 'وَٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَٰتِنَا صُمٌّۭ وَبُكْمٌۭ فِى ٱلظُّلُمَٰتِ ۗ مَن يَشَإِ ٱللَّهُ يُضْلِلْهُ وَمَن يَشَأْ يَجْعَلْهُ عَلَىٰ صِرَٰطٍۢ مُّسْتَقِيمٍۢ', 'والذين كذبوا بايتنا صم وبكم فى الظلمت  من يشإ الله يضلله ومن يشأ يجعله على صرط مستقيم', NULL, 132, 'local:hafs-text.json'),
  ('hafs-6-40', 'hafs', 6, 40, 'قُلْ أَرَءَيْتَكُمْ إِنْ أَتَىٰكُمْ عَذَابُ ٱللَّهِ أَوْ أَتَتْكُمُ ٱلسَّاعَةُ أَغَيْرَ ٱللَّهِ تَدْعُونَ إِن كُنتُمْ صَٰدِقِينَ', 'قل أرءيتكم إن أتىكم عذاب الله أو أتتكم الساعة أغير الله تدعون إن كنتم صدقين', NULL, 132, 'local:hafs-text.json'),
  ('hafs-6-41', 'hafs', 6, 41, 'بَلْ إِيَّاهُ تَدْعُونَ فَيَكْشِفُ مَا تَدْعُونَ إِلَيْهِ إِن شَآءَ وَتَنسَوْنَ مَا تُشْرِكُونَ', 'بل إياه تدعون فيكشف ما تدعون إليه إن شاء وتنسون ما تشركون', NULL, 132, 'local:hafs-text.json'),
  ('hafs-6-42', 'hafs', 6, 42, 'وَلَقَدْ أَرْسَلْنَآ إِلَىٰٓ أُمَمٍۢ مِّن قَبْلِكَ فَأَخَذْنَٰهُم بِٱلْبَأْسَآءِ وَٱلضَّرَّآءِ لَعَلَّهُمْ يَتَضَرَّعُونَ', 'ولقد أرسلنا إلى أمم من قبلك فأخذنهم بالبأساء والضراء لعلهم يتضرعون', NULL, 132, 'local:hafs-text.json'),
  ('hafs-6-43', 'hafs', 6, 43, 'فَلَوْلَآ إِذْ جَآءَهُم بَأْسُنَا تَضَرَّعُوا۟ وَلَٰكِن قَسَتْ قُلُوبُهُمْ وَزَيَّنَ لَهُمُ ٱلشَّيْطَٰنُ مَا كَانُوا۟ يَعْمَلُونَ', 'فلولا إذ جاءهم بأسنا تضرعوا ولكن قست قلوبهم وزين لهم الشيطن ما كانوا يعملون', NULL, 132, 'local:hafs-text.json'),
  ('hafs-6-44', 'hafs', 6, 44, 'فَلَمَّا نَسُوا۟ مَا ذُكِّرُوا۟ بِهِۦ فَتَحْنَا عَلَيْهِمْ أَبْوَٰبَ كُلِّ شَىْءٍ حَتَّىٰٓ إِذَا فَرِحُوا۟ بِمَآ أُوتُوٓا۟ أَخَذْنَٰهُم بَغْتَةًۭ فَإِذَا هُم مُّبْلِسُونَ', 'فلما نسوا ما ذكروا به فتحنا عليهم أبوب كل شىء حتى إذا فرحوا بما أوتوا أخذنهم بغتة فإذا هم مبلسون', NULL, 132, 'local:hafs-text.json'),
  ('hafs-6-45', 'hafs', 6, 45, 'فَقُطِعَ دَابِرُ ٱلْقَوْمِ ٱلَّذِينَ ظَلَمُوا۟ ۚ وَٱلْحَمْدُ لِلَّهِ رَبِّ ٱلْعَٰلَمِينَ', 'فقطع دابر القوم الذين ظلموا  والحمد لله رب العلمين', NULL, 133, 'local:hafs-text.json'),
  ('hafs-6-46', 'hafs', 6, 46, 'قُلْ أَرَءَيْتُمْ إِنْ أَخَذَ ٱللَّهُ سَمْعَكُمْ وَأَبْصَٰرَكُمْ وَخَتَمَ عَلَىٰ قُلُوبِكُم مَّنْ إِلَٰهٌ غَيْرُ ٱللَّهِ يَأْتِيكُم بِهِ ۗ ٱنظُرْ كَيْفَ نُصَرِّفُ ٱلْءَايَٰتِ ثُمَّ هُمْ يَصْدِفُونَ', 'قل أرءيتم إن أخذ الله سمعكم وأبصركم وختم على قلوبكم من إله غير الله يأتيكم به  انظر كيف نصرف الءايت ثم هم يصدفون', NULL, 133, 'local:hafs-text.json'),
  ('hafs-6-47', 'hafs', 6, 47, 'قُلْ أَرَءَيْتَكُمْ إِنْ أَتَىٰكُمْ عَذَابُ ٱللَّهِ بَغْتَةً أَوْ جَهْرَةً هَلْ يُهْلَكُ إِلَّا ٱلْقَوْمُ ٱلظَّٰلِمُونَ', 'قل أرءيتكم إن أتىكم عذاب الله بغتة أو جهرة هل يهلك إلا القوم الظلمون', NULL, 133, 'local:hafs-text.json'),
  ('hafs-6-48', 'hafs', 6, 48, 'وَمَا نُرْسِلُ ٱلْمُرْسَلِينَ إِلَّا مُبَشِّرِينَ وَمُنذِرِينَ ۖ فَمَنْ ءَامَنَ وَأَصْلَحَ فَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ', 'وما نرسل المرسلين إلا مبشرين ومنذرين  فمن ءامن وأصلح فلا خوف عليهم ولا هم يحزنون', NULL, 133, 'local:hafs-text.json'),
  ('hafs-6-49', 'hafs', 6, 49, 'وَٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَٰتِنَا يَمَسُّهُمُ ٱلْعَذَابُ بِمَا كَانُوا۟ يَفْسُقُونَ', 'والذين كذبوا بايتنا يمسهم العذاب بما كانوا يفسقون', NULL, 133, 'local:hafs-text.json'),
  ('hafs-6-50', 'hafs', 6, 50, 'قُل لَّآ أَقُولُ لَكُمْ عِندِى خَزَآئِنُ ٱللَّهِ وَلَآ أَعْلَمُ ٱلْغَيْبَ وَلَآ أَقُولُ لَكُمْ إِنِّى مَلَكٌ ۖ إِنْ أَتَّبِعُ إِلَّا مَا يُوحَىٰٓ إِلَىَّ ۚ قُلْ هَلْ يَسْتَوِى ٱلْأَعْمَىٰ وَٱلْبَصِيرُ ۚ أَفَلَا تَتَفَكَّرُونَ', 'قل لا أقول لكم عندى خزائن الله ولا أعلم الغيب ولا أقول لكم إنى ملك  إن أتبع إلا ما يوحى إلى  قل هل يستوى الأعمى والبصير  أفلا تتفكرون', NULL, 133, 'local:hafs-text.json'),
  ('hafs-6-51', 'hafs', 6, 51, 'وَأَنذِرْ بِهِ ٱلَّذِينَ يَخَافُونَ أَن يُحْشَرُوٓا۟ إِلَىٰ رَبِّهِمْ ۙ لَيْسَ لَهُم مِّن دُونِهِۦ وَلِىٌّۭ وَلَا شَفِيعٌۭ لَّعَلَّهُمْ يَتَّقُونَ', 'وأنذر به الذين يخافون أن يحشروا إلى ربهم  ليس لهم من دونه ولى ولا شفيع لعلهم يتقون', NULL, 133, 'local:hafs-text.json'),
  ('hafs-6-52', 'hafs', 6, 52, 'وَلَا تَطْرُدِ ٱلَّذِينَ يَدْعُونَ رَبَّهُم بِٱلْغَدَوٰةِ وَٱلْعَشِىِّ يُرِيدُونَ وَجْهَهُۥ ۖ مَا عَلَيْكَ مِنْ حِسَابِهِم مِّن شَىْءٍۢ وَمَا مِنْ حِسَابِكَ عَلَيْهِم مِّن شَىْءٍۢ فَتَطْرُدَهُمْ فَتَكُونَ مِنَ ٱلظَّٰلِمِينَ', 'ولا تطرد الذين يدعون ربهم بالغدوة والعشى يريدون وجهه  ما عليك من حسابهم من شىء وما من حسابك عليهم من شىء فتطردهم فتكون من الظلمين', NULL, 133, 'local:hafs-text.json'),
  ('hafs-6-53', 'hafs', 6, 53, 'وَكَذَٰلِكَ فَتَنَّا بَعْضَهُم بِبَعْضٍۢ لِّيَقُولُوٓا۟ أَهَٰٓؤُلَآءِ مَنَّ ٱللَّهُ عَلَيْهِم مِّنۢ بَيْنِنَآ ۗ أَلَيْسَ ٱللَّهُ بِأَعْلَمَ بِٱلشَّٰكِرِينَ', 'وكذلك فتنا بعضهم ببعض ليقولوا أهؤلاء من الله عليهم من بيننا  أليس الله بأعلم بالشكرين', NULL, 134, 'local:hafs-text.json'),
  ('hafs-6-54', 'hafs', 6, 54, 'وَإِذَا جَآءَكَ ٱلَّذِينَ يُؤْمِنُونَ بِـَٔايَٰتِنَا فَقُلْ سَلَٰمٌ عَلَيْكُمْ ۖ كَتَبَ رَبُّكُمْ عَلَىٰ نَفْسِهِ ٱلرَّحْمَةَ ۖ أَنَّهُۥ مَنْ عَمِلَ مِنكُمْ سُوٓءًۢا بِجَهَٰلَةٍۢ ثُمَّ تَابَ مِنۢ بَعْدِهِۦ وَأَصْلَحَ فَأَنَّهُۥ غَفُورٌۭ رَّحِيمٌۭ', 'وإذا جاءك الذين يؤمنون بايتنا فقل سلم عليكم  كتب ربكم على نفسه الرحمة  أنه من عمل منكم سوءا بجهلة ثم تاب من بعده وأصلح فأنه غفور رحيم', NULL, 134, 'local:hafs-text.json'),
  ('hafs-6-55', 'hafs', 6, 55, 'وَكَذَٰلِكَ نُفَصِّلُ ٱلْءَايَٰتِ وَلِتَسْتَبِينَ سَبِيلُ ٱلْمُجْرِمِينَ', 'وكذلك نفصل الءايت ولتستبين سبيل المجرمين', NULL, 134, 'local:hafs-text.json'),
  ('hafs-6-56', 'hafs', 6, 56, 'قُلْ إِنِّى نُهِيتُ أَنْ أَعْبُدَ ٱلَّذِينَ تَدْعُونَ مِن دُونِ ٱللَّهِ ۚ قُل لَّآ أَتَّبِعُ أَهْوَآءَكُمْ ۙ قَدْ ضَلَلْتُ إِذًۭا وَمَآ أَنَا۠ مِنَ ٱلْمُهْتَدِينَ', 'قل إنى نهيت أن أعبد الذين تدعون من دون الله  قل لا أتبع أهواءكم  قد ضللت إذا وما أنا من المهتدين', NULL, 134, 'local:hafs-text.json'),
  ('hafs-6-57', 'hafs', 6, 57, 'قُلْ إِنِّى عَلَىٰ بَيِّنَةٍۢ مِّن رَّبِّى وَكَذَّبْتُم بِهِۦ ۚ مَا عِندِى مَا تَسْتَعْجِلُونَ بِهِۦٓ ۚ إِنِ ٱلْحُكْمُ إِلَّا لِلَّهِ ۖ يَقُصُّ ٱلْحَقَّ ۖ وَهُوَ خَيْرُ ٱلْفَٰصِلِينَ', 'قل إنى على بينة من ربى وكذبتم به  ما عندى ما تستعجلون به  إن الحكم إلا لله  يقص الحق  وهو خير الفصلين', NULL, 134, 'local:hafs-text.json'),
  ('hafs-6-58', 'hafs', 6, 58, 'قُل لَّوْ أَنَّ عِندِى مَا تَسْتَعْجِلُونَ بِهِۦ لَقُضِىَ ٱلْأَمْرُ بَيْنِى وَبَيْنَكُمْ ۗ وَٱللَّهُ أَعْلَمُ بِٱلظَّٰلِمِينَ', 'قل لو أن عندى ما تستعجلون به لقضى الأمر بينى وبينكم  والله أعلم بالظلمين', NULL, 134, 'local:hafs-text.json'),
  ('hafs-6-59', 'hafs', 6, 59, '۞ وَعِندَهُۥ مَفَاتِحُ ٱلْغَيْبِ لَا يَعْلَمُهَآ إِلَّا هُوَ ۚ وَيَعْلَمُ مَا فِى ٱلْبَرِّ وَٱلْبَحْرِ ۚ وَمَا تَسْقُطُ مِن وَرَقَةٍ إِلَّا يَعْلَمُهَا وَلَا حَبَّةٍۢ فِى ظُلُمَٰتِ ٱلْأَرْضِ وَلَا رَطْبٍۢ وَلَا يَابِسٍ إِلَّا فِى كِتَٰبٍۢ مُّبِينٍۢ', 'وعنده مفاتح الغيب لا يعلمها إلا هو  ويعلم ما فى البر والبحر  وما تسقط من ورقة إلا يعلمها ولا حبة فى ظلمت الأرض ولا رطب ولا يابس إلا فى كتب مبين', NULL, 134, 'local:hafs-text.json'),
  ('hafs-6-60', 'hafs', 6, 60, 'وَهُوَ ٱلَّذِى يَتَوَفَّىٰكُم بِٱلَّيْلِ وَيَعْلَمُ مَا جَرَحْتُم بِٱلنَّهَارِ ثُمَّ يَبْعَثُكُمْ فِيهِ لِيُقْضَىٰٓ أَجَلٌۭ مُّسَمًّۭى ۖ ثُمَّ إِلَيْهِ مَرْجِعُكُمْ ثُمَّ يُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ', 'وهو الذى يتوفىكم باليل ويعلم ما جرحتم بالنهار ثم يبعثكم فيه ليقضى أجل مسمى  ثم إليه مرجعكم ثم ينبئكم بما كنتم تعملون', NULL, 135, 'local:hafs-text.json'),
  ('hafs-6-61', 'hafs', 6, 61, 'وَهُوَ ٱلْقَاهِرُ فَوْقَ عِبَادِهِۦ ۖ وَيُرْسِلُ عَلَيْكُمْ حَفَظَةً حَتَّىٰٓ إِذَا جَآءَ أَحَدَكُمُ ٱلْمَوْتُ تَوَفَّتْهُ رُسُلُنَا وَهُمْ لَا يُفَرِّطُونَ', 'وهو القاهر فوق عباده  ويرسل عليكم حفظة حتى إذا جاء أحدكم الموت توفته رسلنا وهم لا يفرطون', NULL, 135, 'local:hafs-text.json'),
  ('hafs-6-62', 'hafs', 6, 62, 'ثُمَّ رُدُّوٓا۟ إِلَى ٱللَّهِ مَوْلَىٰهُمُ ٱلْحَقِّ ۚ أَلَا لَهُ ٱلْحُكْمُ وَهُوَ أَسْرَعُ ٱلْحَٰسِبِينَ', 'ثم ردوا إلى الله مولىهم الحق  ألا له الحكم وهو أسرع الحسبين', NULL, 135, 'local:hafs-text.json'),
  ('hafs-6-63', 'hafs', 6, 63, 'قُلْ مَن يُنَجِّيكُم مِّن ظُلُمَٰتِ ٱلْبَرِّ وَٱلْبَحْرِ تَدْعُونَهُۥ تَضَرُّعًۭا وَخُفْيَةًۭ لَّئِنْ أَنجَىٰنَا مِنْ هَٰذِهِۦ لَنَكُونَنَّ مِنَ ٱلشَّٰكِرِينَ', 'قل من ينجيكم من ظلمت البر والبحر تدعونه تضرعا وخفية لئن أنجىنا من هذه لنكونن من الشكرين', NULL, 135, 'local:hafs-text.json'),
  ('hafs-6-64', 'hafs', 6, 64, 'قُلِ ٱللَّهُ يُنَجِّيكُم مِّنْهَا وَمِن كُلِّ كَرْبٍۢ ثُمَّ أَنتُمْ تُشْرِكُونَ', 'قل الله ينجيكم منها ومن كل كرب ثم أنتم تشركون', NULL, 135, 'local:hafs-text.json'),
  ('hafs-6-65', 'hafs', 6, 65, 'قُلْ هُوَ ٱلْقَادِرُ عَلَىٰٓ أَن يَبْعَثَ عَلَيْكُمْ عَذَابًۭا مِّن فَوْقِكُمْ أَوْ مِن تَحْتِ أَرْجُلِكُمْ أَوْ يَلْبِسَكُمْ شِيَعًۭا وَيُذِيقَ بَعْضَكُم بَأْسَ بَعْضٍ ۗ ٱنظُرْ كَيْفَ نُصَرِّفُ ٱلْءَايَٰتِ لَعَلَّهُمْ يَفْقَهُونَ', 'قل هو القادر على أن يبعث عليكم عذابا من فوقكم أو من تحت أرجلكم أو يلبسكم شيعا ويذيق بعضكم بأس بعض  انظر كيف نصرف الءايت لعلهم يفقهون', NULL, 135, 'local:hafs-text.json'),
  ('hafs-6-66', 'hafs', 6, 66, 'وَكَذَّبَ بِهِۦ قَوْمُكَ وَهُوَ ٱلْحَقُّ ۚ قُل لَّسْتُ عَلَيْكُم بِوَكِيلٍۢ', 'وكذب به قومك وهو الحق  قل لست عليكم بوكيل', NULL, 135, 'local:hafs-text.json'),
  ('hafs-6-67', 'hafs', 6, 67, 'لِّكُلِّ نَبَإٍۢ مُّسْتَقَرٌّۭ ۚ وَسَوْفَ تَعْلَمُونَ', 'لكل نبإ مستقر  وسوف تعلمون', NULL, 135, 'local:hafs-text.json'),
  ('hafs-6-68', 'hafs', 6, 68, 'وَإِذَا رَأَيْتَ ٱلَّذِينَ يَخُوضُونَ فِىٓ ءَايَٰتِنَا فَأَعْرِضْ عَنْهُمْ حَتَّىٰ يَخُوضُوا۟ فِى حَدِيثٍ غَيْرِهِۦ ۚ وَإِمَّا يُنسِيَنَّكَ ٱلشَّيْطَٰنُ فَلَا تَقْعُدْ بَعْدَ ٱلذِّكْرَىٰ مَعَ ٱلْقَوْمِ ٱلظَّٰلِمِينَ', 'وإذا رأيت الذين يخوضون فى ءايتنا فأعرض عنهم حتى يخوضوا فى حديث غيره  وإما ينسينك الشيطن فلا تقعد بعد الذكرى مع القوم الظلمين', NULL, 135, 'local:hafs-text.json'),
  ('hafs-6-69', 'hafs', 6, 69, 'وَمَا عَلَى ٱلَّذِينَ يَتَّقُونَ مِنْ حِسَابِهِم مِّن شَىْءٍۢ وَلَٰكِن ذِكْرَىٰ لَعَلَّهُمْ يَتَّقُونَ', 'وما على الذين يتقون من حسابهم من شىء ولكن ذكرى لعلهم يتقون', NULL, 136, 'local:hafs-text.json'),
  ('hafs-6-70', 'hafs', 6, 70, 'وَذَرِ ٱلَّذِينَ ٱتَّخَذُوا۟ دِينَهُمْ لَعِبًۭا وَلَهْوًۭا وَغَرَّتْهُمُ ٱلْحَيَوٰةُ ٱلدُّنْيَا ۚ وَذَكِّرْ بِهِۦٓ أَن تُبْسَلَ نَفْسٌۢ بِمَا كَسَبَتْ لَيْسَ لَهَا مِن دُونِ ٱللَّهِ وَلِىٌّۭ وَلَا شَفِيعٌۭ وَإِن تَعْدِلْ كُلَّ عَدْلٍۢ لَّا يُؤْخَذْ مِنْهَآ ۗ أُو۟لَٰٓئِكَ ٱلَّذِينَ أُبْسِلُوا۟ بِمَا كَسَبُوا۟ ۖ لَهُمْ شَرَابٌۭ مِّنْ حَمِيمٍۢ وَعَذَابٌ أَلِيمٌۢ بِمَا كَانُوا۟ يَكْفُرُونَ', 'وذر الذين اتخذوا دينهم لعبا ولهوا وغرتهم الحيوة الدنيا  وذكر به أن تبسل نفس بما كسبت ليس لها من دون الله ولى ولا شفيع وإن تعدل كل عدل لا يؤخذ منها  أولئك الذين أبسلوا بما كسبوا  لهم شراب من حميم وعذاب أليم بما كانوا يكفرون', NULL, 136, 'local:hafs-text.json'),
  ('hafs-6-71', 'hafs', 6, 71, 'قُلْ أَنَدْعُوا۟ مِن دُونِ ٱللَّهِ مَا لَا يَنفَعُنَا وَلَا يَضُرُّنَا وَنُرَدُّ عَلَىٰٓ أَعْقَابِنَا بَعْدَ إِذْ هَدَىٰنَا ٱللَّهُ كَٱلَّذِى ٱسْتَهْوَتْهُ ٱلشَّيَٰطِينُ فِى ٱلْأَرْضِ حَيْرَانَ لَهُۥٓ أَصْحَٰبٌۭ يَدْعُونَهُۥٓ إِلَى ٱلْهُدَى ٱئْتِنَا ۗ قُلْ إِنَّ هُدَى ٱللَّهِ هُوَ ٱلْهُدَىٰ ۖ وَأُمِرْنَا لِنُسْلِمَ لِرَبِّ ٱلْعَٰلَمِينَ', 'قل أندعوا من دون الله ما لا ينفعنا ولا يضرنا ونرد على أعقابنا بعد إذ هدىنا الله كالذى استهوته الشيطين فى الأرض حيران له أصحب يدعونه إلى الهدى ائتنا  قل إن هدى الله هو الهدى  وأمرنا لنسلم لرب العلمين', NULL, 136, 'local:hafs-text.json'),
  ('hafs-6-72', 'hafs', 6, 72, 'وَأَنْ أَقِيمُوا۟ ٱلصَّلَوٰةَ وَٱتَّقُوهُ ۚ وَهُوَ ٱلَّذِىٓ إِلَيْهِ تُحْشَرُونَ', 'وأن أقيموا الصلوة واتقوه  وهو الذى إليه تحشرون', NULL, 136, 'local:hafs-text.json'),
  ('hafs-6-73', 'hafs', 6, 73, 'وَهُوَ ٱلَّذِى خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ بِٱلْحَقِّ ۖ وَيَوْمَ يَقُولُ كُن فَيَكُونُ ۚ قَوْلُهُ ٱلْحَقُّ ۚ وَلَهُ ٱلْمُلْكُ يَوْمَ يُنفَخُ فِى ٱلصُّورِ ۚ عَٰلِمُ ٱلْغَيْبِ وَٱلشَّهَٰدَةِ ۚ وَهُوَ ٱلْحَكِيمُ ٱلْخَبِيرُ', 'وهو الذى خلق السموت والأرض بالحق  ويوم يقول كن فيكون  قوله الحق  وله الملك يوم ينفخ فى الصور  علم الغيب والشهدة  وهو الحكيم الخبير', NULL, 136, 'local:hafs-text.json'),
  ('hafs-6-74', 'hafs', 6, 74, '۞ وَإِذْ قَالَ إِبْرَٰهِيمُ لِأَبِيهِ ءَازَرَ أَتَتَّخِذُ أَصْنَامًا ءَالِهَةً ۖ إِنِّىٓ أَرَىٰكَ وَقَوْمَكَ فِى ضَلَٰلٍۢ مُّبِينٍۢ', 'وإذ قال إبرهيم لأبيه ءازر أتتخذ أصناما ءالهة  إنى أرىك وقومك فى ضلل مبين', NULL, 137, 'local:hafs-text.json'),
  ('hafs-6-75', 'hafs', 6, 75, 'وَكَذَٰلِكَ نُرِىٓ إِبْرَٰهِيمَ مَلَكُوتَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَلِيَكُونَ مِنَ ٱلْمُوقِنِينَ', 'وكذلك نرى إبرهيم ملكوت السموت والأرض وليكون من الموقنين', NULL, 137, 'local:hafs-text.json'),
  ('hafs-6-76', 'hafs', 6, 76, 'فَلَمَّا جَنَّ عَلَيْهِ ٱلَّيْلُ رَءَا كَوْكَبًۭا ۖ قَالَ هَٰذَا رَبِّى ۖ فَلَمَّآ أَفَلَ قَالَ لَآ أُحِبُّ ٱلْءَافِلِينَ', 'فلما جن عليه اليل رءا كوكبا  قال هذا ربى  فلما أفل قال لا أحب الءافلين', NULL, 137, 'local:hafs-text.json'),
  ('hafs-6-77', 'hafs', 6, 77, 'فَلَمَّا رَءَا ٱلْقَمَرَ بَازِغًۭا قَالَ هَٰذَا رَبِّى ۖ فَلَمَّآ أَفَلَ قَالَ لَئِن لَّمْ يَهْدِنِى رَبِّى لَأَكُونَنَّ مِنَ ٱلْقَوْمِ ٱلضَّآلِّينَ', 'فلما رءا القمر بازغا قال هذا ربى  فلما أفل قال لئن لم يهدنى ربى لأكونن من القوم الضالين', NULL, 137, 'local:hafs-text.json'),
  ('hafs-6-78', 'hafs', 6, 78, 'فَلَمَّا رَءَا ٱلشَّمْسَ بَازِغَةًۭ قَالَ هَٰذَا رَبِّى هَٰذَآ أَكْبَرُ ۖ فَلَمَّآ أَفَلَتْ قَالَ يَٰقَوْمِ إِنِّى بَرِىٓءٌۭ مِّمَّا تُشْرِكُونَ', 'فلما رءا الشمس بازغة قال هذا ربى هذا أكبر  فلما أفلت قال يقوم إنى برىء مما تشركون', NULL, 137, 'local:hafs-text.json'),
  ('hafs-6-79', 'hafs', 6, 79, 'إِنِّى وَجَّهْتُ وَجْهِىَ لِلَّذِى فَطَرَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ حَنِيفًۭا ۖ وَمَآ أَنَا۠ مِنَ ٱلْمُشْرِكِينَ', 'إنى وجهت وجهى للذى فطر السموت والأرض حنيفا  وما أنا من المشركين', NULL, 137, 'local:hafs-text.json'),
  ('hafs-6-80', 'hafs', 6, 80, 'وَحَآجَّهُۥ قَوْمُهُۥ ۚ قَالَ أَتُحَٰٓجُّوٓنِّى فِى ٱللَّهِ وَقَدْ هَدَىٰنِ ۚ وَلَآ أَخَافُ مَا تُشْرِكُونَ بِهِۦٓ إِلَّآ أَن يَشَآءَ رَبِّى شَيْـًۭٔا ۗ وَسِعَ رَبِّى كُلَّ شَىْءٍ عِلْمًا ۗ أَفَلَا تَتَذَكَّرُونَ', 'وحاجه قومه  قال أتحجونى فى الله وقد هدىن  ولا أخاف ما تشركون به إلا أن يشاء ربى شيا  وسع ربى كل شىء علما  أفلا تتذكرون', NULL, 137, 'local:hafs-text.json'),
  ('hafs-6-81', 'hafs', 6, 81, 'وَكَيْفَ أَخَافُ مَآ أَشْرَكْتُمْ وَلَا تَخَافُونَ أَنَّكُمْ أَشْرَكْتُم بِٱللَّهِ مَا لَمْ يُنَزِّلْ بِهِۦ عَلَيْكُمْ سُلْطَٰنًۭا ۚ فَأَىُّ ٱلْفَرِيقَيْنِ أَحَقُّ بِٱلْأَمْنِ ۖ إِن كُنتُمْ تَعْلَمُونَ', 'وكيف أخاف ما أشركتم ولا تخافون أنكم أشركتم بالله ما لم ينزل به عليكم سلطنا  فأى الفريقين أحق بالأمن  إن كنتم تعلمون', NULL, 137, 'local:hafs-text.json'),
  ('hafs-6-82', 'hafs', 6, 82, 'ٱلَّذِينَ ءَامَنُوا۟ وَلَمْ يَلْبِسُوٓا۟ إِيمَٰنَهُم بِظُلْمٍ أُو۟لَٰٓئِكَ لَهُمُ ٱلْأَمْنُ وَهُم مُّهْتَدُونَ', 'الذين ءامنوا ولم يلبسوا إيمنهم بظلم أولئك لهم الأمن وهم مهتدون', NULL, 138, 'local:hafs-text.json'),
  ('hafs-6-83', 'hafs', 6, 83, 'وَتِلْكَ حُجَّتُنَآ ءَاتَيْنَٰهَآ إِبْرَٰهِيمَ عَلَىٰ قَوْمِهِۦ ۚ نَرْفَعُ دَرَجَٰتٍۢ مَّن نَّشَآءُ ۗ إِنَّ رَبَّكَ حَكِيمٌ عَلِيمٌۭ', 'وتلك حجتنا ءاتينها إبرهيم على قومه  نرفع درجت من نشاء  إن ربك حكيم عليم', NULL, 138, 'local:hafs-text.json'),
  ('hafs-6-84', 'hafs', 6, 84, 'وَوَهَبْنَا لَهُۥٓ إِسْحَٰقَ وَيَعْقُوبَ ۚ كُلًّا هَدَيْنَا ۚ وَنُوحًا هَدَيْنَا مِن قَبْلُ ۖ وَمِن ذُرِّيَّتِهِۦ دَاوُۥدَ وَسُلَيْمَٰنَ وَأَيُّوبَ وَيُوسُفَ وَمُوسَىٰ وَهَٰرُونَ ۚ وَكَذَٰلِكَ نَجْزِى ٱلْمُحْسِنِينَ', 'ووهبنا له إسحق ويعقوب  كلا هدينا  ونوحا هدينا من قبل  ومن ذريته داود وسليمن وأيوب ويوسف وموسى وهرون  وكذلك نجزى المحسنين', NULL, 138, 'local:hafs-text.json'),
  ('hafs-6-85', 'hafs', 6, 85, 'وَزَكَرِيَّا وَيَحْيَىٰ وَعِيسَىٰ وَإِلْيَاسَ ۖ كُلٌّۭ مِّنَ ٱلصَّٰلِحِينَ', 'وزكريا ويحيى وعيسى وإلياس  كل من الصلحين', NULL, 138, 'local:hafs-text.json'),
  ('hafs-6-86', 'hafs', 6, 86, 'وَإِسْمَٰعِيلَ وَٱلْيَسَعَ وَيُونُسَ وَلُوطًۭا ۚ وَكُلًّۭا فَضَّلْنَا عَلَى ٱلْعَٰلَمِينَ', 'وإسمعيل واليسع ويونس ولوطا  وكلا فضلنا على العلمين', NULL, 138, 'local:hafs-text.json'),
  ('hafs-6-87', 'hafs', 6, 87, 'وَمِنْ ءَابَآئِهِمْ وَذُرِّيَّٰتِهِمْ وَإِخْوَٰنِهِمْ ۖ وَٱجْتَبَيْنَٰهُمْ وَهَدَيْنَٰهُمْ إِلَىٰ صِرَٰطٍۢ مُّسْتَقِيمٍۢ', 'ومن ءابائهم وذريتهم وإخونهم  واجتبينهم وهدينهم إلى صرط مستقيم', NULL, 138, 'local:hafs-text.json'),
  ('hafs-6-88', 'hafs', 6, 88, 'ذَٰلِكَ هُدَى ٱللَّهِ يَهْدِى بِهِۦ مَن يَشَآءُ مِنْ عِبَادِهِۦ ۚ وَلَوْ أَشْرَكُوا۟ لَحَبِطَ عَنْهُم مَّا كَانُوا۟ يَعْمَلُونَ', 'ذلك هدى الله يهدى به من يشاء من عباده  ولو أشركوا لحبط عنهم ما كانوا يعملون', NULL, 138, 'local:hafs-text.json'),
  ('hafs-6-89', 'hafs', 6, 89, 'أُو۟لَٰٓئِكَ ٱلَّذِينَ ءَاتَيْنَٰهُمُ ٱلْكِتَٰبَ وَٱلْحُكْمَ وَٱلنُّبُوَّةَ ۚ فَإِن يَكْفُرْ بِهَا هَٰٓؤُلَآءِ فَقَدْ وَكَّلْنَا بِهَا قَوْمًۭا لَّيْسُوا۟ بِهَا بِكَٰفِرِينَ', 'أولئك الذين ءاتينهم الكتب والحكم والنبوة  فإن يكفر بها هؤلاء فقد وكلنا بها قوما ليسوا بها بكفرين', NULL, 138, 'local:hafs-text.json'),
  ('hafs-6-90', 'hafs', 6, 90, 'أُو۟لَٰٓئِكَ ٱلَّذِينَ هَدَى ٱللَّهُ ۖ فَبِهُدَىٰهُمُ ٱقْتَدِهْ ۗ قُل لَّآ أَسْـَٔلُكُمْ عَلَيْهِ أَجْرًا ۖ إِنْ هُوَ إِلَّا ذِكْرَىٰ لِلْعَٰلَمِينَ', 'أولئك الذين هدى الله  فبهدىهم اقتده  قل لا أسلكم عليه أجرا  إن هو إلا ذكرى للعلمين', NULL, 138, 'local:hafs-text.json'),
  ('hafs-6-91', 'hafs', 6, 91, 'وَمَا قَدَرُوا۟ ٱللَّهَ حَقَّ قَدْرِهِۦٓ إِذْ قَالُوا۟ مَآ أَنزَلَ ٱللَّهُ عَلَىٰ بَشَرٍۢ مِّن شَىْءٍۢ ۗ قُلْ مَنْ أَنزَلَ ٱلْكِتَٰبَ ٱلَّذِى جَآءَ بِهِۦ مُوسَىٰ نُورًۭا وَهُدًۭى لِّلنَّاسِ ۖ تَجْعَلُونَهُۥ قَرَاطِيسَ تُبْدُونَهَا وَتُخْفُونَ كَثِيرًۭا ۖ وَعُلِّمْتُم مَّا لَمْ تَعْلَمُوٓا۟ أَنتُمْ وَلَآ ءَابَآؤُكُمْ ۖ قُلِ ٱللَّهُ ۖ ثُمَّ ذَرْهُمْ فِى خَوْضِهِمْ يَلْعَبُونَ', 'وما قدروا الله حق قدره إذ قالوا ما أنزل الله على بشر من شىء  قل من أنزل الكتب الذى جاء به موسى نورا وهدى للناس  تجعلونه قراطيس تبدونها وتخفون كثيرا  وعلمتم ما لم تعلموا أنتم ولا ءاباؤكم  قل الله  ثم ذرهم فى خوضهم يلعبون', NULL, 139, 'local:hafs-text.json'),
  ('hafs-6-92', 'hafs', 6, 92, 'وَهَٰذَا كِتَٰبٌ أَنزَلْنَٰهُ مُبَارَكٌۭ مُّصَدِّقُ ٱلَّذِى بَيْنَ يَدَيْهِ وَلِتُنذِرَ أُمَّ ٱلْقُرَىٰ وَمَنْ حَوْلَهَا ۚ وَٱلَّذِينَ يُؤْمِنُونَ بِٱلْءَاخِرَةِ يُؤْمِنُونَ بِهِۦ ۖ وَهُمْ عَلَىٰ صَلَاتِهِمْ يُحَافِظُونَ', 'وهذا كتب أنزلنه مبارك مصدق الذى بين يديه ولتنذر أم القرى ومن حولها  والذين يؤمنون بالءاخرة يؤمنون به  وهم على صلاتهم يحافظون', NULL, 139, 'local:hafs-text.json'),
  ('hafs-6-93', 'hafs', 6, 93, 'وَمَنْ أَظْلَمُ مِمَّنِ ٱفْتَرَىٰ عَلَى ٱللَّهِ كَذِبًا أَوْ قَالَ أُوحِىَ إِلَىَّ وَلَمْ يُوحَ إِلَيْهِ شَىْءٌۭ وَمَن قَالَ سَأُنزِلُ مِثْلَ مَآ أَنزَلَ ٱللَّهُ ۗ وَلَوْ تَرَىٰٓ إِذِ ٱلظَّٰلِمُونَ فِى غَمَرَٰتِ ٱلْمَوْتِ وَٱلْمَلَٰٓئِكَةُ بَاسِطُوٓا۟ أَيْدِيهِمْ أَخْرِجُوٓا۟ أَنفُسَكُمُ ۖ ٱلْيَوْمَ تُجْزَوْنَ عَذَابَ ٱلْهُونِ بِمَا كُنتُمْ تَقُولُونَ عَلَى ٱللَّهِ غَيْرَ ٱلْحَقِّ وَكُنتُمْ عَنْ ءَايَٰتِهِۦ تَسْتَكْبِرُونَ', 'ومن أظلم ممن افترى على الله كذبا أو قال أوحى إلى ولم يوح إليه شىء ومن قال سأنزل مثل ما أنزل الله  ولو ترى إذ الظلمون فى غمرت الموت والملئكة باسطوا أيديهم أخرجوا أنفسكم  اليوم تجزون عذاب الهون بما كنتم تقولون على الله غير الحق وكنتم عن ءايته تستكبرون', NULL, 139, 'local:hafs-text.json'),
  ('hafs-6-94', 'hafs', 6, 94, 'وَلَقَدْ جِئْتُمُونَا فُرَٰدَىٰ كَمَا خَلَقْنَٰكُمْ أَوَّلَ مَرَّةٍۢ وَتَرَكْتُم مَّا خَوَّلْنَٰكُمْ وَرَآءَ ظُهُورِكُمْ ۖ وَمَا نَرَىٰ مَعَكُمْ شُفَعَآءَكُمُ ٱلَّذِينَ زَعَمْتُمْ أَنَّهُمْ فِيكُمْ شُرَكَٰٓؤُا۟ ۚ لَقَد تَّقَطَّعَ بَيْنَكُمْ وَضَلَّ عَنكُم مَّا كُنتُمْ تَزْعُمُونَ', 'ولقد جئتمونا فردى كما خلقنكم أول مرة وتركتم ما خولنكم وراء ظهوركم  وما نرى معكم شفعاءكم الذين زعمتم أنهم فيكم شركؤا  لقد تقطع بينكم وضل عنكم ما كنتم تزعمون', NULL, 139, 'local:hafs-text.json'),
  ('hafs-6-95', 'hafs', 6, 95, '۞ إِنَّ ٱللَّهَ فَالِقُ ٱلْحَبِّ وَٱلنَّوَىٰ ۖ يُخْرِجُ ٱلْحَىَّ مِنَ ٱلْمَيِّتِ وَمُخْرِجُ ٱلْمَيِّتِ مِنَ ٱلْحَىِّ ۚ ذَٰلِكُمُ ٱللَّهُ ۖ فَأَنَّىٰ تُؤْفَكُونَ', 'إن الله فالق الحب والنوى  يخرج الحى من الميت ومخرج الميت من الحى  ذلكم الله  فأنى تؤفكون', NULL, 140, 'local:hafs-text.json'),
  ('hafs-6-96', 'hafs', 6, 96, 'فَالِقُ ٱلْإِصْبَاحِ وَجَعَلَ ٱلَّيْلَ سَكَنًۭا وَٱلشَّمْسَ وَٱلْقَمَرَ حُسْبَانًۭا ۚ ذَٰلِكَ تَقْدِيرُ ٱلْعَزِيزِ ٱلْعَلِيمِ', 'فالق الإصباح وجعل اليل سكنا والشمس والقمر حسبانا  ذلك تقدير العزيز العليم', NULL, 140, 'local:hafs-text.json'),
  ('hafs-6-97', 'hafs', 6, 97, 'وَهُوَ ٱلَّذِى جَعَلَ لَكُمُ ٱلنُّجُومَ لِتَهْتَدُوا۟ بِهَا فِى ظُلُمَٰتِ ٱلْبَرِّ وَٱلْبَحْرِ ۗ قَدْ فَصَّلْنَا ٱلْءَايَٰتِ لِقَوْمٍۢ يَعْلَمُونَ', 'وهو الذى جعل لكم النجوم لتهتدوا بها فى ظلمت البر والبحر  قد فصلنا الءايت لقوم يعلمون', NULL, 140, 'local:hafs-text.json'),
  ('hafs-6-98', 'hafs', 6, 98, 'وَهُوَ ٱلَّذِىٓ أَنشَأَكُم مِّن نَّفْسٍۢ وَٰحِدَةٍۢ فَمُسْتَقَرٌّۭ وَمُسْتَوْدَعٌۭ ۗ قَدْ فَصَّلْنَا ٱلْءَايَٰتِ لِقَوْمٍۢ يَفْقَهُونَ', 'وهو الذى أنشأكم من نفس وحدة فمستقر ومستودع  قد فصلنا الءايت لقوم يفقهون', NULL, 140, 'local:hafs-text.json'),
  ('hafs-6-99', 'hafs', 6, 99, 'وَهُوَ ٱلَّذِىٓ أَنزَلَ مِنَ ٱلسَّمَآءِ مَآءًۭ فَأَخْرَجْنَا بِهِۦ نَبَاتَ كُلِّ شَىْءٍۢ فَأَخْرَجْنَا مِنْهُ خَضِرًۭا نُّخْرِجُ مِنْهُ حَبًّۭا مُّتَرَاكِبًۭا وَمِنَ ٱلنَّخْلِ مِن طَلْعِهَا قِنْوَانٌۭ دَانِيَةٌۭ وَجَنَّٰتٍۢ مِّنْ أَعْنَابٍۢ وَٱلزَّيْتُونَ وَٱلرُّمَّانَ مُشْتَبِهًۭا وَغَيْرَ مُتَشَٰبِهٍ ۗ ٱنظُرُوٓا۟ إِلَىٰ ثَمَرِهِۦٓ إِذَآ أَثْمَرَ وَيَنْعِهِۦٓ ۚ إِنَّ فِى ذَٰلِكُمْ لَءَايَٰتٍۢ لِّقَوْمٍۢ يُؤْمِنُونَ', 'وهو الذى أنزل من السماء ماء فأخرجنا به نبات كل شىء فأخرجنا منه خضرا نخرج منه حبا متراكبا ومن النخل من طلعها قنوان دانية وجنت من أعناب والزيتون والرمان مشتبها وغير متشبه  انظروا إلى ثمره إذا أثمر وينعه  إن فى ذلكم لءايت لقوم يؤمنون', NULL, 140, 'local:hafs-text.json'),
  ('hafs-6-100', 'hafs', 6, 100, 'وَجَعَلُوا۟ لِلَّهِ شُرَكَآءَ ٱلْجِنَّ وَخَلَقَهُمْ ۖ وَخَرَقُوا۟ لَهُۥ بَنِينَ وَبَنَٰتٍۭ بِغَيْرِ عِلْمٍۢ ۚ سُبْحَٰنَهُۥ وَتَعَٰلَىٰ عَمَّا يَصِفُونَ', 'وجعلوا لله شركاء الجن وخلقهم  وخرقوا له بنين وبنت بغير علم  سبحنه وتعلى عما يصفون', NULL, 140, 'local:hafs-text.json'),
  ('hafs-6-101', 'hafs', 6, 101, 'بَدِيعُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ ۖ أَنَّىٰ يَكُونُ لَهُۥ وَلَدٌۭ وَلَمْ تَكُن لَّهُۥ صَٰحِبَةٌۭ ۖ وَخَلَقَ كُلَّ شَىْءٍۢ ۖ وَهُوَ بِكُلِّ شَىْءٍ عَلِيمٌۭ', 'بديع السموت والأرض  أنى يكون له ولد ولم تكن له صحبة  وخلق كل شىء  وهو بكل شىء عليم', NULL, 140, 'local:hafs-text.json'),
  ('hafs-6-102', 'hafs', 6, 102, 'ذَٰلِكُمُ ٱللَّهُ رَبُّكُمْ ۖ لَآ إِلَٰهَ إِلَّا هُوَ ۖ خَٰلِقُ كُلِّ شَىْءٍۢ فَٱعْبُدُوهُ ۚ وَهُوَ عَلَىٰ كُلِّ شَىْءٍۢ وَكِيلٌۭ', 'ذلكم الله ربكم  لا إله إلا هو  خلق كل شىء فاعبدوه  وهو على كل شىء وكيل', NULL, 141, 'local:hafs-text.json'),
  ('hafs-6-103', 'hafs', 6, 103, 'لَّا تُدْرِكُهُ ٱلْأَبْصَٰرُ وَهُوَ يُدْرِكُ ٱلْأَبْصَٰرَ ۖ وَهُوَ ٱللَّطِيفُ ٱلْخَبِيرُ', 'لا تدركه الأبصر وهو يدرك الأبصر  وهو اللطيف الخبير', NULL, 141, 'local:hafs-text.json'),
  ('hafs-6-104', 'hafs', 6, 104, 'قَدْ جَآءَكُم بَصَآئِرُ مِن رَّبِّكُمْ ۖ فَمَنْ أَبْصَرَ فَلِنَفْسِهِۦ ۖ وَمَنْ عَمِىَ فَعَلَيْهَا ۚ وَمَآ أَنَا۠ عَلَيْكُم بِحَفِيظٍۢ', 'قد جاءكم بصائر من ربكم  فمن أبصر فلنفسه  ومن عمى فعليها  وما أنا عليكم بحفيظ', NULL, 141, 'local:hafs-text.json'),
  ('hafs-6-105', 'hafs', 6, 105, 'وَكَذَٰلِكَ نُصَرِّفُ ٱلْءَايَٰتِ وَلِيَقُولُوا۟ دَرَسْتَ وَلِنُبَيِّنَهُۥ لِقَوْمٍۢ يَعْلَمُونَ', 'وكذلك نصرف الءايت وليقولوا درست ولنبينه لقوم يعلمون', NULL, 141, 'local:hafs-text.json'),
  ('hafs-6-106', 'hafs', 6, 106, 'ٱتَّبِعْ مَآ أُوحِىَ إِلَيْكَ مِن رَّبِّكَ ۖ لَآ إِلَٰهَ إِلَّا هُوَ ۖ وَأَعْرِضْ عَنِ ٱلْمُشْرِكِينَ', 'اتبع ما أوحى إليك من ربك  لا إله إلا هو  وأعرض عن المشركين', NULL, 141, 'local:hafs-text.json'),
  ('hafs-6-107', 'hafs', 6, 107, 'وَلَوْ شَآءَ ٱللَّهُ مَآ أَشْرَكُوا۟ ۗ وَمَا جَعَلْنَٰكَ عَلَيْهِمْ حَفِيظًۭا ۖ وَمَآ أَنتَ عَلَيْهِم بِوَكِيلٍۢ', 'ولو شاء الله ما أشركوا  وما جعلنك عليهم حفيظا  وما أنت عليهم بوكيل', NULL, 141, 'local:hafs-text.json'),
  ('hafs-6-108', 'hafs', 6, 108, 'وَلَا تَسُبُّوا۟ ٱلَّذِينَ يَدْعُونَ مِن دُونِ ٱللَّهِ فَيَسُبُّوا۟ ٱللَّهَ عَدْوًۢا بِغَيْرِ عِلْمٍۢ ۗ كَذَٰلِكَ زَيَّنَّا لِكُلِّ أُمَّةٍ عَمَلَهُمْ ثُمَّ إِلَىٰ رَبِّهِم مَّرْجِعُهُمْ فَيُنَبِّئُهُم بِمَا كَانُوا۟ يَعْمَلُونَ', 'ولا تسبوا الذين يدعون من دون الله فيسبوا الله عدوا بغير علم  كذلك زينا لكل أمة عملهم ثم إلى ربهم مرجعهم فينبئهم بما كانوا يعملون', NULL, 141, 'local:hafs-text.json'),
  ('hafs-6-109', 'hafs', 6, 109, 'وَأَقْسَمُوا۟ بِٱللَّهِ جَهْدَ أَيْمَٰنِهِمْ لَئِن جَآءَتْهُمْ ءَايَةٌۭ لَّيُؤْمِنُنَّ بِهَا ۚ قُلْ إِنَّمَا ٱلْءَايَٰتُ عِندَ ٱللَّهِ ۖ وَمَا يُشْعِرُكُمْ أَنَّهَآ إِذَا جَآءَتْ لَا يُؤْمِنُونَ', 'وأقسموا بالله جهد أيمنهم لئن جاءتهم ءاية ليؤمنن بها  قل إنما الءايت عند الله  وما يشعركم أنها إذا جاءت لا يؤمنون', NULL, 141, 'local:hafs-text.json'),
  ('hafs-6-110', 'hafs', 6, 110, 'وَنُقَلِّبُ أَفْـِٔدَتَهُمْ وَأَبْصَٰرَهُمْ كَمَا لَمْ يُؤْمِنُوا۟ بِهِۦٓ أَوَّلَ مَرَّةٍۢ وَنَذَرُهُمْ فِى طُغْيَٰنِهِمْ يَعْمَهُونَ', 'ونقلب أفدتهم وأبصرهم كما لم يؤمنوا به أول مرة ونذرهم فى طغينهم يعمهون', NULL, 141, 'local:hafs-text.json'),
  ('hafs-6-111', 'hafs', 6, 111, '۞ وَلَوْ أَنَّنَا نَزَّلْنَآ إِلَيْهِمُ ٱلْمَلَٰٓئِكَةَ وَكَلَّمَهُمُ ٱلْمَوْتَىٰ وَحَشَرْنَا عَلَيْهِمْ كُلَّ شَىْءٍۢ قُبُلًۭا مَّا كَانُوا۟ لِيُؤْمِنُوٓا۟ إِلَّآ أَن يَشَآءَ ٱللَّهُ وَلَٰكِنَّ أَكْثَرَهُمْ يَجْهَلُونَ', 'ولو أننا نزلنا إليهم الملئكة وكلمهم الموتى وحشرنا عليهم كل شىء قبلا ما كانوا ليؤمنوا إلا أن يشاء الله ولكن أكثرهم يجهلون', NULL, 142, 'local:hafs-text.json'),
  ('hafs-6-112', 'hafs', 6, 112, 'وَكَذَٰلِكَ جَعَلْنَا لِكُلِّ نَبِىٍّ عَدُوًّۭا شَيَٰطِينَ ٱلْإِنسِ وَٱلْجِنِّ يُوحِى بَعْضُهُمْ إِلَىٰ بَعْضٍۢ زُخْرُفَ ٱلْقَوْلِ غُرُورًۭا ۚ وَلَوْ شَآءَ رَبُّكَ مَا فَعَلُوهُ ۖ فَذَرْهُمْ وَمَا يَفْتَرُونَ', 'وكذلك جعلنا لكل نبى عدوا شيطين الإنس والجن يوحى بعضهم إلى بعض زخرف القول غرورا  ولو شاء ربك ما فعلوه  فذرهم وما يفترون', NULL, 142, 'local:hafs-text.json'),
  ('hafs-6-113', 'hafs', 6, 113, 'وَلِتَصْغَىٰٓ إِلَيْهِ أَفْـِٔدَةُ ٱلَّذِينَ لَا يُؤْمِنُونَ بِٱلْءَاخِرَةِ وَلِيَرْضَوْهُ وَلِيَقْتَرِفُوا۟ مَا هُم مُّقْتَرِفُونَ', 'ولتصغى إليه أفدة الذين لا يؤمنون بالءاخرة وليرضوه وليقترفوا ما هم مقترفون', NULL, 142, 'local:hafs-text.json'),
  ('hafs-6-114', 'hafs', 6, 114, 'أَفَغَيْرَ ٱللَّهِ أَبْتَغِى حَكَمًۭا وَهُوَ ٱلَّذِىٓ أَنزَلَ إِلَيْكُمُ ٱلْكِتَٰبَ مُفَصَّلًۭا ۚ وَٱلَّذِينَ ءَاتَيْنَٰهُمُ ٱلْكِتَٰبَ يَعْلَمُونَ أَنَّهُۥ مُنَزَّلٌۭ مِّن رَّبِّكَ بِٱلْحَقِّ ۖ فَلَا تَكُونَنَّ مِنَ ٱلْمُمْتَرِينَ', 'أفغير الله أبتغى حكما وهو الذى أنزل إليكم الكتب مفصلا  والذين ءاتينهم الكتب يعلمون أنه منزل من ربك بالحق  فلا تكونن من الممترين', NULL, 142, 'local:hafs-text.json'),
  ('hafs-6-115', 'hafs', 6, 115, 'وَتَمَّتْ كَلِمَتُ رَبِّكَ صِدْقًۭا وَعَدْلًۭا ۚ لَّا مُبَدِّلَ لِكَلِمَٰتِهِۦ ۚ وَهُوَ ٱلسَّمِيعُ ٱلْعَلِيمُ', 'وتمت كلمت ربك صدقا وعدلا  لا مبدل لكلمته  وهو السميع العليم', NULL, 142, 'local:hafs-text.json'),
  ('hafs-6-116', 'hafs', 6, 116, 'وَإِن تُطِعْ أَكْثَرَ مَن فِى ٱلْأَرْضِ يُضِلُّوكَ عَن سَبِيلِ ٱللَّهِ ۚ إِن يَتَّبِعُونَ إِلَّا ٱلظَّنَّ وَإِنْ هُمْ إِلَّا يَخْرُصُونَ', 'وإن تطع أكثر من فى الأرض يضلوك عن سبيل الله  إن يتبعون إلا الظن وإن هم إلا يخرصون', NULL, 142, 'local:hafs-text.json'),
  ('hafs-6-117', 'hafs', 6, 117, 'إِنَّ رَبَّكَ هُوَ أَعْلَمُ مَن يَضِلُّ عَن سَبِيلِهِۦ ۖ وَهُوَ أَعْلَمُ بِٱلْمُهْتَدِينَ', 'إن ربك هو أعلم من يضل عن سبيله  وهو أعلم بالمهتدين', NULL, 142, 'local:hafs-text.json'),
  ('hafs-6-118', 'hafs', 6, 118, 'فَكُلُوا۟ مِمَّا ذُكِرَ ٱسْمُ ٱللَّهِ عَلَيْهِ إِن كُنتُم بِـَٔايَٰتِهِۦ مُؤْمِنِينَ', 'فكلوا مما ذكر اسم الله عليه إن كنتم بايته مؤمنين', NULL, 142, 'local:hafs-text.json'),
  ('hafs-6-119', 'hafs', 6, 119, 'وَمَا لَكُمْ أَلَّا تَأْكُلُوا۟ مِمَّا ذُكِرَ ٱسْمُ ٱللَّهِ عَلَيْهِ وَقَدْ فَصَّلَ لَكُم مَّا حَرَّمَ عَلَيْكُمْ إِلَّا مَا ٱضْطُرِرْتُمْ إِلَيْهِ ۗ وَإِنَّ كَثِيرًۭا لَّيُضِلُّونَ بِأَهْوَآئِهِم بِغَيْرِ عِلْمٍ ۗ إِنَّ رَبَّكَ هُوَ أَعْلَمُ بِٱلْمُعْتَدِينَ', 'وما لكم ألا تأكلوا مما ذكر اسم الله عليه وقد فصل لكم ما حرم عليكم إلا ما اضطررتم إليه  وإن كثيرا ليضلون بأهوائهم بغير علم  إن ربك هو أعلم بالمعتدين', NULL, 143, 'local:hafs-text.json'),
  ('hafs-6-120', 'hafs', 6, 120, 'وَذَرُوا۟ ظَٰهِرَ ٱلْإِثْمِ وَبَاطِنَهُۥٓ ۚ إِنَّ ٱلَّذِينَ يَكْسِبُونَ ٱلْإِثْمَ سَيُجْزَوْنَ بِمَا كَانُوا۟ يَقْتَرِفُونَ', 'وذروا ظهر الإثم وباطنه  إن الذين يكسبون الإثم سيجزون بما كانوا يقترفون', NULL, 143, 'local:hafs-text.json'),
  ('hafs-6-121', 'hafs', 6, 121, 'وَلَا تَأْكُلُوا۟ مِمَّا لَمْ يُذْكَرِ ٱسْمُ ٱللَّهِ عَلَيْهِ وَإِنَّهُۥ لَفِسْقٌۭ ۗ وَإِنَّ ٱلشَّيَٰطِينَ لَيُوحُونَ إِلَىٰٓ أَوْلِيَآئِهِمْ لِيُجَٰدِلُوكُمْ ۖ وَإِنْ أَطَعْتُمُوهُمْ إِنَّكُمْ لَمُشْرِكُونَ', 'ولا تأكلوا مما لم يذكر اسم الله عليه وإنه لفسق  وإن الشيطين ليوحون إلى أوليائهم ليجدلوكم  وإن أطعتموهم إنكم لمشركون', NULL, 143, 'local:hafs-text.json'),
  ('hafs-6-122', 'hafs', 6, 122, 'أَوَمَن كَانَ مَيْتًۭا فَأَحْيَيْنَٰهُ وَجَعَلْنَا لَهُۥ نُورًۭا يَمْشِى بِهِۦ فِى ٱلنَّاسِ كَمَن مَّثَلُهُۥ فِى ٱلظُّلُمَٰتِ لَيْسَ بِخَارِجٍۢ مِّنْهَا ۚ كَذَٰلِكَ زُيِّنَ لِلْكَٰفِرِينَ مَا كَانُوا۟ يَعْمَلُونَ', 'أومن كان ميتا فأحيينه وجعلنا له نورا يمشى به فى الناس كمن مثله فى الظلمت ليس بخارج منها  كذلك زين للكفرين ما كانوا يعملون', NULL, 143, 'local:hafs-text.json'),
  ('hafs-6-123', 'hafs', 6, 123, 'وَكَذَٰلِكَ جَعَلْنَا فِى كُلِّ قَرْيَةٍ أَكَٰبِرَ مُجْرِمِيهَا لِيَمْكُرُوا۟ فِيهَا ۖ وَمَا يَمْكُرُونَ إِلَّا بِأَنفُسِهِمْ وَمَا يَشْعُرُونَ', 'وكذلك جعلنا فى كل قرية أكبر مجرميها ليمكروا فيها  وما يمكرون إلا بأنفسهم وما يشعرون', NULL, 143, 'local:hafs-text.json'),
  ('hafs-6-124', 'hafs', 6, 124, 'وَإِذَا جَآءَتْهُمْ ءَايَةٌۭ قَالُوا۟ لَن نُّؤْمِنَ حَتَّىٰ نُؤْتَىٰ مِثْلَ مَآ أُوتِىَ رُسُلُ ٱللَّهِ ۘ ٱللَّهُ أَعْلَمُ حَيْثُ يَجْعَلُ رِسَالَتَهُۥ ۗ سَيُصِيبُ ٱلَّذِينَ أَجْرَمُوا۟ صَغَارٌ عِندَ ٱللَّهِ وَعَذَابٌۭ شَدِيدٌۢ بِمَا كَانُوا۟ يَمْكُرُونَ', 'وإذا جاءتهم ءاية قالوا لن نؤمن حتى نؤتى مثل ما أوتى رسل الله  الله أعلم حيث يجعل رسالته  سيصيب الذين أجرموا صغار عند الله وعذاب شديد بما كانوا يمكرون', NULL, 143, 'local:hafs-text.json'),
  ('hafs-6-125', 'hafs', 6, 125, 'فَمَن يُرِدِ ٱللَّهُ أَن يَهْدِيَهُۥ يَشْرَحْ صَدْرَهُۥ لِلْإِسْلَٰمِ ۖ وَمَن يُرِدْ أَن يُضِلَّهُۥ يَجْعَلْ صَدْرَهُۥ ضَيِّقًا حَرَجًۭا كَأَنَّمَا يَصَّعَّدُ فِى ٱلسَّمَآءِ ۚ كَذَٰلِكَ يَجْعَلُ ٱللَّهُ ٱلرِّجْسَ عَلَى ٱلَّذِينَ لَا يُؤْمِنُونَ', 'فمن يرد الله أن يهديه يشرح صدره للإسلم  ومن يرد أن يضله يجعل صدره ضيقا حرجا كأنما يصعد فى السماء  كذلك يجعل الله الرجس على الذين لا يؤمنون', NULL, 144, 'local:hafs-text.json'),
  ('hafs-6-126', 'hafs', 6, 126, 'وَهَٰذَا صِرَٰطُ رَبِّكَ مُسْتَقِيمًۭا ۗ قَدْ فَصَّلْنَا ٱلْءَايَٰتِ لِقَوْمٍۢ يَذَّكَّرُونَ', 'وهذا صرط ربك مستقيما  قد فصلنا الءايت لقوم يذكرون', NULL, 144, 'local:hafs-text.json'),
  ('hafs-6-127', 'hafs', 6, 127, '۞ لَهُمْ دَارُ ٱلسَّلَٰمِ عِندَ رَبِّهِمْ ۖ وَهُوَ وَلِيُّهُم بِمَا كَانُوا۟ يَعْمَلُونَ', 'لهم دار السلم عند ربهم  وهو وليهم بما كانوا يعملون', NULL, 144, 'local:hafs-text.json'),
  ('hafs-6-128', 'hafs', 6, 128, 'وَيَوْمَ يَحْشُرُهُمْ جَمِيعًۭا يَٰمَعْشَرَ ٱلْجِنِّ قَدِ ٱسْتَكْثَرْتُم مِّنَ ٱلْإِنسِ ۖ وَقَالَ أَوْلِيَآؤُهُم مِّنَ ٱلْإِنسِ رَبَّنَا ٱسْتَمْتَعَ بَعْضُنَا بِبَعْضٍۢ وَبَلَغْنَآ أَجَلَنَا ٱلَّذِىٓ أَجَّلْتَ لَنَا ۚ قَالَ ٱلنَّارُ مَثْوَىٰكُمْ خَٰلِدِينَ فِيهَآ إِلَّا مَا شَآءَ ٱللَّهُ ۗ إِنَّ رَبَّكَ حَكِيمٌ عَلِيمٌۭ', 'ويوم يحشرهم جميعا يمعشر الجن قد استكثرتم من الإنس  وقال أولياؤهم من الإنس ربنا استمتع بعضنا ببعض وبلغنا أجلنا الذى أجلت لنا  قال النار مثوىكم خلدين فيها إلا ما شاء الله  إن ربك حكيم عليم', NULL, 144, 'local:hafs-text.json'),
  ('hafs-6-129', 'hafs', 6, 129, 'وَكَذَٰلِكَ نُوَلِّى بَعْضَ ٱلظَّٰلِمِينَ بَعْضًۢا بِمَا كَانُوا۟ يَكْسِبُونَ', 'وكذلك نولى بعض الظلمين بعضا بما كانوا يكسبون', NULL, 144, 'local:hafs-text.json'),
  ('hafs-6-130', 'hafs', 6, 130, 'يَٰمَعْشَرَ ٱلْجِنِّ وَٱلْإِنسِ أَلَمْ يَأْتِكُمْ رُسُلٌۭ مِّنكُمْ يَقُصُّونَ عَلَيْكُمْ ءَايَٰتِى وَيُنذِرُونَكُمْ لِقَآءَ يَوْمِكُمْ هَٰذَا ۚ قَالُوا۟ شَهِدْنَا عَلَىٰٓ أَنفُسِنَا ۖ وَغَرَّتْهُمُ ٱلْحَيَوٰةُ ٱلدُّنْيَا وَشَهِدُوا۟ عَلَىٰٓ أَنفُسِهِمْ أَنَّهُمْ كَانُوا۟ كَٰفِرِينَ', 'يمعشر الجن والإنس ألم يأتكم رسل منكم يقصون عليكم ءايتى وينذرونكم لقاء يومكم هذا  قالوا شهدنا على أنفسنا  وغرتهم الحيوة الدنيا وشهدوا على أنفسهم أنهم كانوا كفرين', NULL, 144, 'local:hafs-text.json'),
  ('hafs-6-131', 'hafs', 6, 131, 'ذَٰلِكَ أَن لَّمْ يَكُن رَّبُّكَ مُهْلِكَ ٱلْقُرَىٰ بِظُلْمٍۢ وَأَهْلُهَا غَٰفِلُونَ', 'ذلك أن لم يكن ربك مهلك القرى بظلم وأهلها غفلون', NULL, 144, 'local:hafs-text.json'),
  ('hafs-6-132', 'hafs', 6, 132, 'وَلِكُلٍّۢ دَرَجَٰتٌۭ مِّمَّا عَمِلُوا۟ ۚ وَمَا رَبُّكَ بِغَٰفِلٍ عَمَّا يَعْمَلُونَ', 'ولكل درجت مما عملوا  وما ربك بغفل عما يعملون', NULL, 145, 'local:hafs-text.json'),
  ('hafs-6-133', 'hafs', 6, 133, 'وَرَبُّكَ ٱلْغَنِىُّ ذُو ٱلرَّحْمَةِ ۚ إِن يَشَأْ يُذْهِبْكُمْ وَيَسْتَخْلِفْ مِنۢ بَعْدِكُم مَّا يَشَآءُ كَمَآ أَنشَأَكُم مِّن ذُرِّيَّةِ قَوْمٍ ءَاخَرِينَ', 'وربك الغنى ذو الرحمة  إن يشأ يذهبكم ويستخلف من بعدكم ما يشاء كما أنشأكم من ذرية قوم ءاخرين', NULL, 145, 'local:hafs-text.json'),
  ('hafs-6-134', 'hafs', 6, 134, 'إِنَّ مَا تُوعَدُونَ لَءَاتٍۢ ۖ وَمَآ أَنتُم بِمُعْجِزِينَ', 'إن ما توعدون لءات  وما أنتم بمعجزين', NULL, 145, 'local:hafs-text.json'),
  ('hafs-6-135', 'hafs', 6, 135, 'قُلْ يَٰقَوْمِ ٱعْمَلُوا۟ عَلَىٰ مَكَانَتِكُمْ إِنِّى عَامِلٌۭ ۖ فَسَوْفَ تَعْلَمُونَ مَن تَكُونُ لَهُۥ عَٰقِبَةُ ٱلدَّارِ ۗ إِنَّهُۥ لَا يُفْلِحُ ٱلظَّٰلِمُونَ', 'قل يقوم اعملوا على مكانتكم إنى عامل  فسوف تعلمون من تكون له عقبة الدار  إنه لا يفلح الظلمون', NULL, 145, 'local:hafs-text.json'),
  ('hafs-6-136', 'hafs', 6, 136, 'وَجَعَلُوا۟ لِلَّهِ مِمَّا ذَرَأَ مِنَ ٱلْحَرْثِ وَٱلْأَنْعَٰمِ نَصِيبًۭا فَقَالُوا۟ هَٰذَا لِلَّهِ بِزَعْمِهِمْ وَهَٰذَا لِشُرَكَآئِنَا ۖ فَمَا كَانَ لِشُرَكَآئِهِمْ فَلَا يَصِلُ إِلَى ٱللَّهِ ۖ وَمَا كَانَ لِلَّهِ فَهُوَ يَصِلُ إِلَىٰ شُرَكَآئِهِمْ ۗ سَآءَ مَا يَحْكُمُونَ', 'وجعلوا لله مما ذرأ من الحرث والأنعم نصيبا فقالوا هذا لله بزعمهم وهذا لشركائنا  فما كان لشركائهم فلا يصل إلى الله  وما كان لله فهو يصل إلى شركائهم  ساء ما يحكمون', NULL, 145, 'local:hafs-text.json'),
  ('hafs-6-137', 'hafs', 6, 137, 'وَكَذَٰلِكَ زَيَّنَ لِكَثِيرٍۢ مِّنَ ٱلْمُشْرِكِينَ قَتْلَ أَوْلَٰدِهِمْ شُرَكَآؤُهُمْ لِيُرْدُوهُمْ وَلِيَلْبِسُوا۟ عَلَيْهِمْ دِينَهُمْ ۖ وَلَوْ شَآءَ ٱللَّهُ مَا فَعَلُوهُ ۖ فَذَرْهُمْ وَمَا يَفْتَرُونَ', 'وكذلك زين لكثير من المشركين قتل أولدهم شركاؤهم ليردوهم وليلبسوا عليهم دينهم  ولو شاء الله ما فعلوه  فذرهم وما يفترون', NULL, 145, 'local:hafs-text.json'),
  ('hafs-6-138', 'hafs', 6, 138, 'وَقَالُوا۟ هَٰذِهِۦٓ أَنْعَٰمٌۭ وَحَرْثٌ حِجْرٌۭ لَّا يَطْعَمُهَآ إِلَّا مَن نَّشَآءُ بِزَعْمِهِمْ وَأَنْعَٰمٌ حُرِّمَتْ ظُهُورُهَا وَأَنْعَٰمٌۭ لَّا يَذْكُرُونَ ٱسْمَ ٱللَّهِ عَلَيْهَا ٱفْتِرَآءً عَلَيْهِ ۚ سَيَجْزِيهِم بِمَا كَانُوا۟ يَفْتَرُونَ', 'وقالوا هذه أنعم وحرث حجر لا يطعمها إلا من نشاء بزعمهم وأنعم حرمت ظهورها وأنعم لا يذكرون اسم الله عليها افتراء عليه  سيجزيهم بما كانوا يفترون', NULL, 146, 'local:hafs-text.json'),
  ('hafs-6-139', 'hafs', 6, 139, 'وَقَالُوا۟ مَا فِى بُطُونِ هَٰذِهِ ٱلْأَنْعَٰمِ خَالِصَةٌۭ لِّذُكُورِنَا وَمُحَرَّمٌ عَلَىٰٓ أَزْوَٰجِنَا ۖ وَإِن يَكُن مَّيْتَةًۭ فَهُمْ فِيهِ شُرَكَآءُ ۚ سَيَجْزِيهِمْ وَصْفَهُمْ ۚ إِنَّهُۥ حَكِيمٌ عَلِيمٌۭ', 'وقالوا ما فى بطون هذه الأنعم خالصة لذكورنا ومحرم على أزوجنا  وإن يكن ميتة فهم فيه شركاء  سيجزيهم وصفهم  إنه حكيم عليم', NULL, 146, 'local:hafs-text.json'),
  ('hafs-6-140', 'hafs', 6, 140, 'قَدْ خَسِرَ ٱلَّذِينَ قَتَلُوٓا۟ أَوْلَٰدَهُمْ سَفَهًۢا بِغَيْرِ عِلْمٍۢ وَحَرَّمُوا۟ مَا رَزَقَهُمُ ٱللَّهُ ٱفْتِرَآءً عَلَى ٱللَّهِ ۚ قَدْ ضَلُّوا۟ وَمَا كَانُوا۟ مُهْتَدِينَ', 'قد خسر الذين قتلوا أولدهم سفها بغير علم وحرموا ما رزقهم الله افتراء على الله  قد ضلوا وما كانوا مهتدين', NULL, 146, 'local:hafs-text.json'),
  ('hafs-6-141', 'hafs', 6, 141, '۞ وَهُوَ ٱلَّذِىٓ أَنشَأَ جَنَّٰتٍۢ مَّعْرُوشَٰتٍۢ وَغَيْرَ مَعْرُوشَٰتٍۢ وَٱلنَّخْلَ وَٱلزَّرْعَ مُخْتَلِفًا أُكُلُهُۥ وَٱلزَّيْتُونَ وَٱلرُّمَّانَ مُتَشَٰبِهًۭا وَغَيْرَ مُتَشَٰبِهٍۢ ۚ كُلُوا۟ مِن ثَمَرِهِۦٓ إِذَآ أَثْمَرَ وَءَاتُوا۟ حَقَّهُۥ يَوْمَ حَصَادِهِۦ ۖ وَلَا تُسْرِفُوٓا۟ ۚ إِنَّهُۥ لَا يُحِبُّ ٱلْمُسْرِفِينَ', 'وهو الذى أنشأ جنت معروشت وغير معروشت والنخل والزرع مختلفا أكله والزيتون والرمان متشبها وغير متشبه  كلوا من ثمره إذا أثمر وءاتوا حقه يوم حصاده  ولا تسرفوا  إنه لا يحب المسرفين', NULL, 146, 'local:hafs-text.json'),
  ('hafs-6-142', 'hafs', 6, 142, 'وَمِنَ ٱلْأَنْعَٰمِ حَمُولَةًۭ وَفَرْشًۭا ۚ كُلُوا۟ مِمَّا رَزَقَكُمُ ٱللَّهُ وَلَا تَتَّبِعُوا۟ خُطُوَٰتِ ٱلشَّيْطَٰنِ ۚ إِنَّهُۥ لَكُمْ عَدُوٌّۭ مُّبِينٌۭ', 'ومن الأنعم حمولة وفرشا  كلوا مما رزقكم الله ولا تتبعوا خطوت الشيطن  إنه لكم عدو مبين', NULL, 146, 'local:hafs-text.json'),
  ('hafs-6-143', 'hafs', 6, 143, 'ثَمَٰنِيَةَ أَزْوَٰجٍۢ ۖ مِّنَ ٱلضَّأْنِ ٱثْنَيْنِ وَمِنَ ٱلْمَعْزِ ٱثْنَيْنِ ۗ قُلْ ءَآلذَّكَرَيْنِ حَرَّمَ أَمِ ٱلْأُنثَيَيْنِ أَمَّا ٱشْتَمَلَتْ عَلَيْهِ أَرْحَامُ ٱلْأُنثَيَيْنِ ۖ نَبِّـُٔونِى بِعِلْمٍ إِن كُنتُمْ صَٰدِقِينَ', 'ثمنية أزوج  من الضأن اثنين ومن المعز اثنين  قل ءالذكرين حرم أم الأنثيين أما اشتملت عليه أرحام الأنثيين  نبونى بعلم إن كنتم صدقين', NULL, 147, 'local:hafs-text.json'),
  ('hafs-6-144', 'hafs', 6, 144, 'وَمِنَ ٱلْإِبِلِ ٱثْنَيْنِ وَمِنَ ٱلْبَقَرِ ٱثْنَيْنِ ۗ قُلْ ءَآلذَّكَرَيْنِ حَرَّمَ أَمِ ٱلْأُنثَيَيْنِ أَمَّا ٱشْتَمَلَتْ عَلَيْهِ أَرْحَامُ ٱلْأُنثَيَيْنِ ۖ أَمْ كُنتُمْ شُهَدَآءَ إِذْ وَصَّىٰكُمُ ٱللَّهُ بِهَٰذَا ۚ فَمَنْ أَظْلَمُ مِمَّنِ ٱفْتَرَىٰ عَلَى ٱللَّهِ كَذِبًۭا لِّيُضِلَّ ٱلنَّاسَ بِغَيْرِ عِلْمٍ ۗ إِنَّ ٱللَّهَ لَا يَهْدِى ٱلْقَوْمَ ٱلظَّٰلِمِينَ', 'ومن الإبل اثنين ومن البقر اثنين  قل ءالذكرين حرم أم الأنثيين أما اشتملت عليه أرحام الأنثيين  أم كنتم شهداء إذ وصىكم الله بهذا  فمن أظلم ممن افترى على الله كذبا ليضل الناس بغير علم  إن الله لا يهدى القوم الظلمين', NULL, 147, 'local:hafs-text.json'),
  ('hafs-6-145', 'hafs', 6, 145, 'قُل لَّآ أَجِدُ فِى مَآ أُوحِىَ إِلَىَّ مُحَرَّمًا عَلَىٰ طَاعِمٍۢ يَطْعَمُهُۥٓ إِلَّآ أَن يَكُونَ مَيْتَةً أَوْ دَمًۭا مَّسْفُوحًا أَوْ لَحْمَ خِنزِيرٍۢ فَإِنَّهُۥ رِجْسٌ أَوْ فِسْقًا أُهِلَّ لِغَيْرِ ٱللَّهِ بِهِۦ ۚ فَمَنِ ٱضْطُرَّ غَيْرَ بَاغٍۢ وَلَا عَادٍۢ فَإِنَّ رَبَّكَ غَفُورٌۭ رَّحِيمٌۭ', 'قل لا أجد فى ما أوحى إلى محرما على طاعم يطعمه إلا أن يكون ميتة أو دما مسفوحا أو لحم خنزير فإنه رجس أو فسقا أهل لغير الله به  فمن اضطر غير باغ ولا عاد فإن ربك غفور رحيم', NULL, 147, 'local:hafs-text.json'),
  ('hafs-6-146', 'hafs', 6, 146, 'وَعَلَى ٱلَّذِينَ هَادُوا۟ حَرَّمْنَا كُلَّ ذِى ظُفُرٍۢ ۖ وَمِنَ ٱلْبَقَرِ وَٱلْغَنَمِ حَرَّمْنَا عَلَيْهِمْ شُحُومَهُمَآ إِلَّا مَا حَمَلَتْ ظُهُورُهُمَآ أَوِ ٱلْحَوَايَآ أَوْ مَا ٱخْتَلَطَ بِعَظْمٍۢ ۚ ذَٰلِكَ جَزَيْنَٰهُم بِبَغْيِهِمْ ۖ وَإِنَّا لَصَٰدِقُونَ', 'وعلى الذين هادوا حرمنا كل ذى ظفر  ومن البقر والغنم حرمنا عليهم شحومهما إلا ما حملت ظهورهما أو الحوايا أو ما اختلط بعظم  ذلك جزينهم ببغيهم  وإنا لصدقون', NULL, 147, 'local:hafs-text.json'),
  ('hafs-6-147', 'hafs', 6, 147, 'فَإِن كَذَّبُوكَ فَقُل رَّبُّكُمْ ذُو رَحْمَةٍۢ وَٰسِعَةٍۢ وَلَا يُرَدُّ بَأْسُهُۥ عَنِ ٱلْقَوْمِ ٱلْمُجْرِمِينَ', 'فإن كذبوك فقل ربكم ذو رحمة وسعة ولا يرد بأسه عن القوم المجرمين', NULL, 148, 'local:hafs-text.json'),
  ('hafs-6-148', 'hafs', 6, 148, 'سَيَقُولُ ٱلَّذِينَ أَشْرَكُوا۟ لَوْ شَآءَ ٱللَّهُ مَآ أَشْرَكْنَا وَلَآ ءَابَآؤُنَا وَلَا حَرَّمْنَا مِن شَىْءٍۢ ۚ كَذَٰلِكَ كَذَّبَ ٱلَّذِينَ مِن قَبْلِهِمْ حَتَّىٰ ذَاقُوا۟ بَأْسَنَا ۗ قُلْ هَلْ عِندَكُم مِّنْ عِلْمٍۢ فَتُخْرِجُوهُ لَنَآ ۖ إِن تَتَّبِعُونَ إِلَّا ٱلظَّنَّ وَإِنْ أَنتُمْ إِلَّا تَخْرُصُونَ', 'سيقول الذين أشركوا لو شاء الله ما أشركنا ولا ءاباؤنا ولا حرمنا من شىء  كذلك كذب الذين من قبلهم حتى ذاقوا بأسنا  قل هل عندكم من علم فتخرجوه لنا  إن تتبعون إلا الظن وإن أنتم إلا تخرصون', NULL, 148, 'local:hafs-text.json'),
  ('hafs-6-149', 'hafs', 6, 149, 'قُلْ فَلِلَّهِ ٱلْحُجَّةُ ٱلْبَٰلِغَةُ ۖ فَلَوْ شَآءَ لَهَدَىٰكُمْ أَجْمَعِينَ', 'قل فلله الحجة البلغة  فلو شاء لهدىكم أجمعين', NULL, 148, 'local:hafs-text.json'),
  ('hafs-6-150', 'hafs', 6, 150, 'قُلْ هَلُمَّ شُهَدَآءَكُمُ ٱلَّذِينَ يَشْهَدُونَ أَنَّ ٱللَّهَ حَرَّمَ هَٰذَا ۖ فَإِن شَهِدُوا۟ فَلَا تَشْهَدْ مَعَهُمْ ۚ وَلَا تَتَّبِعْ أَهْوَآءَ ٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَٰتِنَا وَٱلَّذِينَ لَا يُؤْمِنُونَ بِٱلْءَاخِرَةِ وَهُم بِرَبِّهِمْ يَعْدِلُونَ', 'قل هلم شهداءكم الذين يشهدون أن الله حرم هذا  فإن شهدوا فلا تشهد معهم  ولا تتبع أهواء الذين كذبوا بايتنا والذين لا يؤمنون بالءاخرة وهم بربهم يعدلون', NULL, 148, 'local:hafs-text.json'),
  ('hafs-6-151', 'hafs', 6, 151, '۞ قُلْ تَعَالَوْا۟ أَتْلُ مَا حَرَّمَ رَبُّكُمْ عَلَيْكُمْ ۖ أَلَّا تُشْرِكُوا۟ بِهِۦ شَيْـًۭٔا ۖ وَبِٱلْوَٰلِدَيْنِ إِحْسَٰنًۭا ۖ وَلَا تَقْتُلُوٓا۟ أَوْلَٰدَكُم مِّنْ إِمْلَٰقٍۢ ۖ نَّحْنُ نَرْزُقُكُمْ وَإِيَّاهُمْ ۖ وَلَا تَقْرَبُوا۟ ٱلْفَوَٰحِشَ مَا ظَهَرَ مِنْهَا وَمَا بَطَنَ ۖ وَلَا تَقْتُلُوا۟ ٱلنَّفْسَ ٱلَّتِى حَرَّمَ ٱللَّهُ إِلَّا بِٱلْحَقِّ ۚ ذَٰلِكُمْ وَصَّىٰكُم بِهِۦ لَعَلَّكُمْ تَعْقِلُونَ', 'قل تعالوا أتل ما حرم ربكم عليكم  ألا تشركوا به شيا  وبالولدين إحسنا  ولا تقتلوا أولدكم من إملق  نحن نرزقكم وإياهم  ولا تقربوا الفوحش ما ظهر منها وما بطن  ولا تقتلوا النفس التى حرم الله إلا بالحق  ذلكم وصىكم به لعلكم تعقلون', NULL, 148, 'local:hafs-text.json'),
  ('hafs-6-152', 'hafs', 6, 152, 'وَلَا تَقْرَبُوا۟ مَالَ ٱلْيَتِيمِ إِلَّا بِٱلَّتِى هِىَ أَحْسَنُ حَتَّىٰ يَبْلُغَ أَشُدَّهُۥ ۖ وَأَوْفُوا۟ ٱلْكَيْلَ وَٱلْمِيزَانَ بِٱلْقِسْطِ ۖ لَا نُكَلِّفُ نَفْسًا إِلَّا وُسْعَهَا ۖ وَإِذَا قُلْتُمْ فَٱعْدِلُوا۟ وَلَوْ كَانَ ذَا قُرْبَىٰ ۖ وَبِعَهْدِ ٱللَّهِ أَوْفُوا۟ ۚ ذَٰلِكُمْ وَصَّىٰكُم بِهِۦ لَعَلَّكُمْ تَذَكَّرُونَ', 'ولا تقربوا مال اليتيم إلا بالتى هى أحسن حتى يبلغ أشده  وأوفوا الكيل والميزان بالقسط  لا نكلف نفسا إلا وسعها  وإذا قلتم فاعدلوا ولو كان ذا قربى  وبعهد الله أوفوا  ذلكم وصىكم به لعلكم تذكرون', NULL, 149, 'local:hafs-text.json'),
  ('hafs-6-153', 'hafs', 6, 153, 'وَأَنَّ هَٰذَا صِرَٰطِى مُسْتَقِيمًۭا فَٱتَّبِعُوهُ ۖ وَلَا تَتَّبِعُوا۟ ٱلسُّبُلَ فَتَفَرَّقَ بِكُمْ عَن سَبِيلِهِۦ ۚ ذَٰلِكُمْ وَصَّىٰكُم بِهِۦ لَعَلَّكُمْ تَتَّقُونَ', 'وأن هذا صرطى مستقيما فاتبعوه  ولا تتبعوا السبل فتفرق بكم عن سبيله  ذلكم وصىكم به لعلكم تتقون', NULL, 149, 'local:hafs-text.json'),
  ('hafs-6-154', 'hafs', 6, 154, 'ثُمَّ ءَاتَيْنَا مُوسَى ٱلْكِتَٰبَ تَمَامًا عَلَى ٱلَّذِىٓ أَحْسَنَ وَتَفْصِيلًۭا لِّكُلِّ شَىْءٍۢ وَهُدًۭى وَرَحْمَةًۭ لَّعَلَّهُم بِلِقَآءِ رَبِّهِمْ يُؤْمِنُونَ', 'ثم ءاتينا موسى الكتب تماما على الذى أحسن وتفصيلا لكل شىء وهدى ورحمة لعلهم بلقاء ربهم يؤمنون', NULL, 149, 'local:hafs-text.json'),
  ('hafs-6-155', 'hafs', 6, 155, 'وَهَٰذَا كِتَٰبٌ أَنزَلْنَٰهُ مُبَارَكٌۭ فَٱتَّبِعُوهُ وَٱتَّقُوا۟ لَعَلَّكُمْ تُرْحَمُونَ', 'وهذا كتب أنزلنه مبارك فاتبعوه واتقوا لعلكم ترحمون', NULL, 149, 'local:hafs-text.json'),
  ('hafs-6-156', 'hafs', 6, 156, 'أَن تَقُولُوٓا۟ إِنَّمَآ أُنزِلَ ٱلْكِتَٰبُ عَلَىٰ طَآئِفَتَيْنِ مِن قَبْلِنَا وَإِن كُنَّا عَن دِرَاسَتِهِمْ لَغَٰفِلِينَ', 'أن تقولوا إنما أنزل الكتب على طائفتين من قبلنا وإن كنا عن دراستهم لغفلين', NULL, 149, 'local:hafs-text.json'),
  ('hafs-6-157', 'hafs', 6, 157, 'أَوْ تَقُولُوا۟ لَوْ أَنَّآ أُنزِلَ عَلَيْنَا ٱلْكِتَٰبُ لَكُنَّآ أَهْدَىٰ مِنْهُمْ ۚ فَقَدْ جَآءَكُم بَيِّنَةٌۭ مِّن رَّبِّكُمْ وَهُدًۭى وَرَحْمَةٌۭ ۚ فَمَنْ أَظْلَمُ مِمَّن كَذَّبَ بِـَٔايَٰتِ ٱللَّهِ وَصَدَفَ عَنْهَا ۗ سَنَجْزِى ٱلَّذِينَ يَصْدِفُونَ عَنْ ءَايَٰتِنَا سُوٓءَ ٱلْعَذَابِ بِمَا كَانُوا۟ يَصْدِفُونَ', 'أو تقولوا لو أنا أنزل علينا الكتب لكنا أهدى منهم  فقد جاءكم بينة من ربكم وهدى ورحمة  فمن أظلم ممن كذب بايت الله وصدف عنها  سنجزى الذين يصدفون عن ءايتنا سوء العذاب بما كانوا يصدفون', NULL, 149, 'local:hafs-text.json'),
  ('hafs-6-158', 'hafs', 6, 158, 'هَلْ يَنظُرُونَ إِلَّآ أَن تَأْتِيَهُمُ ٱلْمَلَٰٓئِكَةُ أَوْ يَأْتِىَ رَبُّكَ أَوْ يَأْتِىَ بَعْضُ ءَايَٰتِ رَبِّكَ ۗ يَوْمَ يَأْتِى بَعْضُ ءَايَٰتِ رَبِّكَ لَا يَنفَعُ نَفْسًا إِيمَٰنُهَا لَمْ تَكُنْ ءَامَنَتْ مِن قَبْلُ أَوْ كَسَبَتْ فِىٓ إِيمَٰنِهَا خَيْرًۭا ۗ قُلِ ٱنتَظِرُوٓا۟ إِنَّا مُنتَظِرُونَ', 'هل ينظرون إلا أن تأتيهم الملئكة أو يأتى ربك أو يأتى بعض ءايت ربك  يوم يأتى بعض ءايت ربك لا ينفع نفسا إيمنها لم تكن ءامنت من قبل أو كسبت فى إيمنها خيرا  قل انتظروا إنا منتظرون', NULL, 150, 'local:hafs-text.json'),
  ('hafs-6-159', 'hafs', 6, 159, 'إِنَّ ٱلَّذِينَ فَرَّقُوا۟ دِينَهُمْ وَكَانُوا۟ شِيَعًۭا لَّسْتَ مِنْهُمْ فِى شَىْءٍ ۚ إِنَّمَآ أَمْرُهُمْ إِلَى ٱللَّهِ ثُمَّ يُنَبِّئُهُم بِمَا كَانُوا۟ يَفْعَلُونَ', 'إن الذين فرقوا دينهم وكانوا شيعا لست منهم فى شىء  إنما أمرهم إلى الله ثم ينبئهم بما كانوا يفعلون', NULL, 150, 'local:hafs-text.json'),
  ('hafs-6-160', 'hafs', 6, 160, 'مَن جَآءَ بِٱلْحَسَنَةِ فَلَهُۥ عَشْرُ أَمْثَالِهَا ۖ وَمَن جَآءَ بِٱلسَّيِّئَةِ فَلَا يُجْزَىٰٓ إِلَّا مِثْلَهَا وَهُمْ لَا يُظْلَمُونَ', 'من جاء بالحسنة فله عشر أمثالها  ومن جاء بالسيئة فلا يجزى إلا مثلها وهم لا يظلمون', NULL, 150, 'local:hafs-text.json'),
  ('hafs-6-161', 'hafs', 6, 161, 'قُلْ إِنَّنِى هَدَىٰنِى رَبِّىٓ إِلَىٰ صِرَٰطٍۢ مُّسْتَقِيمٍۢ دِينًۭا قِيَمًۭا مِّلَّةَ إِبْرَٰهِيمَ حَنِيفًۭا ۚ وَمَا كَانَ مِنَ ٱلْمُشْرِكِينَ', 'قل إننى هدىنى ربى إلى صرط مستقيم دينا قيما ملة إبرهيم حنيفا  وما كان من المشركين', NULL, 150, 'local:hafs-text.json'),
  ('hafs-6-162', 'hafs', 6, 162, 'قُلْ إِنَّ صَلَاتِى وَنُسُكِى وَمَحْيَاىَ وَمَمَاتِى لِلَّهِ رَبِّ ٱلْعَٰلَمِينَ', 'قل إن صلاتى ونسكى ومحياى ومماتى لله رب العلمين', NULL, 150, 'local:hafs-text.json'),
  ('hafs-6-163', 'hafs', 6, 163, 'لَا شَرِيكَ لَهُۥ ۖ وَبِذَٰلِكَ أُمِرْتُ وَأَنَا۠ أَوَّلُ ٱلْمُسْلِمِينَ', 'لا شريك له  وبذلك أمرت وأنا أول المسلمين', NULL, 150, 'local:hafs-text.json'),
  ('hafs-6-164', 'hafs', 6, 164, 'قُلْ أَغَيْرَ ٱللَّهِ أَبْغِى رَبًّۭا وَهُوَ رَبُّ كُلِّ شَىْءٍۢ ۚ وَلَا تَكْسِبُ كُلُّ نَفْسٍ إِلَّا عَلَيْهَا ۚ وَلَا تَزِرُ وَازِرَةٌۭ وِزْرَ أُخْرَىٰ ۚ ثُمَّ إِلَىٰ رَبِّكُم مَّرْجِعُكُمْ فَيُنَبِّئُكُم بِمَا كُنتُمْ فِيهِ تَخْتَلِفُونَ', 'قل أغير الله أبغى ربا وهو رب كل شىء  ولا تكسب كل نفس إلا عليها  ولا تزر وازرة وزر أخرى  ثم إلى ربكم مرجعكم فينبئكم بما كنتم فيه تختلفون', NULL, 150, 'local:hafs-text.json'),
  ('hafs-6-165', 'hafs', 6, 165, 'وَهُوَ ٱلَّذِى جَعَلَكُمْ خَلَٰٓئِفَ ٱلْأَرْضِ وَرَفَعَ بَعْضَكُمْ فَوْقَ بَعْضٍۢ دَرَجَٰتٍۢ لِّيَبْلُوَكُمْ فِى مَآ ءَاتَىٰكُمْ ۗ إِنَّ رَبَّكَ سَرِيعُ ٱلْعِقَابِ وَإِنَّهُۥ لَغَفُورٌۭ رَّحِيمٌۢ', 'وهو الذى جعلكم خلئف الأرض ورفع بعضكم فوق بعض درجت ليبلوكم فى ما ءاتىكم  إن ربك سريع العقاب وإنه لغفور رحيم', NULL, 150, 'local:hafs-text.json'),
  ('hafs-7-1', 'hafs', 7, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ الٓمٓصٓ', 'بسم الله الرحمن الرحيم المص', NULL, 151, 'local:hafs-text.json'),
  ('hafs-7-2', 'hafs', 7, 2, 'كِتَٰبٌ أُنزِلَ إِلَيْكَ فَلَا يَكُن فِى صَدْرِكَ حَرَجٌۭ مِّنْهُ لِتُنذِرَ بِهِۦ وَذِكْرَىٰ لِلْمُؤْمِنِينَ', 'كتب أنزل إليك فلا يكن فى صدرك حرج منه لتنذر به وذكرى للمؤمنين', NULL, 151, 'local:hafs-text.json'),
  ('hafs-7-3', 'hafs', 7, 3, 'ٱتَّبِعُوا۟ مَآ أُنزِلَ إِلَيْكُم مِّن رَّبِّكُمْ وَلَا تَتَّبِعُوا۟ مِن دُونِهِۦٓ أَوْلِيَآءَ ۗ قَلِيلًۭا مَّا تَذَكَّرُونَ', 'اتبعوا ما أنزل إليكم من ربكم ولا تتبعوا من دونه أولياء  قليلا ما تذكرون', NULL, 151, 'local:hafs-text.json'),
  ('hafs-7-4', 'hafs', 7, 4, 'وَكَم مِّن قَرْيَةٍ أَهْلَكْنَٰهَا فَجَآءَهَا بَأْسُنَا بَيَٰتًا أَوْ هُمْ قَآئِلُونَ', 'وكم من قرية أهلكنها فجاءها بأسنا بيتا أو هم قائلون', NULL, 151, 'local:hafs-text.json'),
  ('hafs-7-5', 'hafs', 7, 5, 'فَمَا كَانَ دَعْوَىٰهُمْ إِذْ جَآءَهُم بَأْسُنَآ إِلَّآ أَن قَالُوٓا۟ إِنَّا كُنَّا ظَٰلِمِينَ', 'فما كان دعوىهم إذ جاءهم بأسنا إلا أن قالوا إنا كنا ظلمين', NULL, 151, 'local:hafs-text.json'),
  ('hafs-7-6', 'hafs', 7, 6, 'فَلَنَسْـَٔلَنَّ ٱلَّذِينَ أُرْسِلَ إِلَيْهِمْ وَلَنَسْـَٔلَنَّ ٱلْمُرْسَلِينَ', 'فلنسلن الذين أرسل إليهم ولنسلن المرسلين', NULL, 151, 'local:hafs-text.json'),
  ('hafs-7-7', 'hafs', 7, 7, 'فَلَنَقُصَّنَّ عَلَيْهِم بِعِلْمٍۢ ۖ وَمَا كُنَّا غَآئِبِينَ', 'فلنقصن عليهم بعلم  وما كنا غائبين', NULL, 151, 'local:hafs-text.json'),
  ('hafs-7-8', 'hafs', 7, 8, 'وَٱلْوَزْنُ يَوْمَئِذٍ ٱلْحَقُّ ۚ فَمَن ثَقُلَتْ مَوَٰزِينُهُۥ فَأُو۟لَٰٓئِكَ هُمُ ٱلْمُفْلِحُونَ', 'والوزن يومئذ الحق  فمن ثقلت موزينه فأولئك هم المفلحون', NULL, 151, 'local:hafs-text.json'),
  ('hafs-7-9', 'hafs', 7, 9, 'وَمَنْ خَفَّتْ مَوَٰزِينُهُۥ فَأُو۟لَٰٓئِكَ ٱلَّذِينَ خَسِرُوٓا۟ أَنفُسَهُم بِمَا كَانُوا۟ بِـَٔايَٰتِنَا يَظْلِمُونَ', 'ومن خفت موزينه فأولئك الذين خسروا أنفسهم بما كانوا بايتنا يظلمون', NULL, 151, 'local:hafs-text.json'),
  ('hafs-7-10', 'hafs', 7, 10, 'وَلَقَدْ مَكَّنَّٰكُمْ فِى ٱلْأَرْضِ وَجَعَلْنَا لَكُمْ فِيهَا مَعَٰيِشَ ۗ قَلِيلًۭا مَّا تَشْكُرُونَ', 'ولقد مكنكم فى الأرض وجعلنا لكم فيها معيش  قليلا ما تشكرون', NULL, 151, 'local:hafs-text.json'),
  ('hafs-7-11', 'hafs', 7, 11, 'وَلَقَدْ خَلَقْنَٰكُمْ ثُمَّ صَوَّرْنَٰكُمْ ثُمَّ قُلْنَا لِلْمَلَٰٓئِكَةِ ٱسْجُدُوا۟ لِءَادَمَ فَسَجَدُوٓا۟ إِلَّآ إِبْلِيسَ لَمْ يَكُن مِّنَ ٱلسَّٰجِدِينَ', 'ولقد خلقنكم ثم صورنكم ثم قلنا للملئكة اسجدوا لءادم فسجدوا إلا إبليس لم يكن من السجدين', NULL, 151, 'local:hafs-text.json'),
  ('hafs-7-12', 'hafs', 7, 12, 'قَالَ مَا مَنَعَكَ أَلَّا تَسْجُدَ إِذْ أَمَرْتُكَ ۖ قَالَ أَنَا۠ خَيْرٌۭ مِّنْهُ خَلَقْتَنِى مِن نَّارٍۢ وَخَلَقْتَهُۥ مِن طِينٍۢ', 'قال ما منعك ألا تسجد إذ أمرتك  قال أنا خير منه خلقتنى من نار وخلقته من طين', NULL, 152, 'local:hafs-text.json'),
  ('hafs-7-13', 'hafs', 7, 13, 'قَالَ فَٱهْبِطْ مِنْهَا فَمَا يَكُونُ لَكَ أَن تَتَكَبَّرَ فِيهَا فَٱخْرُجْ إِنَّكَ مِنَ ٱلصَّٰغِرِينَ', 'قال فاهبط منها فما يكون لك أن تتكبر فيها فاخرج إنك من الصغرين', NULL, 152, 'local:hafs-text.json'),
  ('hafs-7-14', 'hafs', 7, 14, 'قَالَ أَنظِرْنِىٓ إِلَىٰ يَوْمِ يُبْعَثُونَ', 'قال أنظرنى إلى يوم يبعثون', NULL, 152, 'local:hafs-text.json'),
  ('hafs-7-15', 'hafs', 7, 15, 'قَالَ إِنَّكَ مِنَ ٱلْمُنظَرِينَ', 'قال إنك من المنظرين', NULL, 152, 'local:hafs-text.json'),
  ('hafs-7-16', 'hafs', 7, 16, 'قَالَ فَبِمَآ أَغْوَيْتَنِى لَأَقْعُدَنَّ لَهُمْ صِرَٰطَكَ ٱلْمُسْتَقِيمَ', 'قال فبما أغويتنى لأقعدن لهم صرطك المستقيم', NULL, 152, 'local:hafs-text.json'),
  ('hafs-7-17', 'hafs', 7, 17, 'ثُمَّ لَءَاتِيَنَّهُم مِّنۢ بَيْنِ أَيْدِيهِمْ وَمِنْ خَلْفِهِمْ وَعَنْ أَيْمَٰنِهِمْ وَعَن شَمَآئِلِهِمْ ۖ وَلَا تَجِدُ أَكْثَرَهُمْ شَٰكِرِينَ', 'ثم لءاتينهم من بين أيديهم ومن خلفهم وعن أيمنهم وعن شمائلهم  ولا تجد أكثرهم شكرين', NULL, 152, 'local:hafs-text.json'),
  ('hafs-7-18', 'hafs', 7, 18, 'قَالَ ٱخْرُجْ مِنْهَا مَذْءُومًۭا مَّدْحُورًۭا ۖ لَّمَن تَبِعَكَ مِنْهُمْ لَأَمْلَأَنَّ جَهَنَّمَ مِنكُمْ أَجْمَعِينَ', 'قال اخرج منها مذءوما مدحورا  لمن تبعك منهم لأملأن جهنم منكم أجمعين', NULL, 152, 'local:hafs-text.json'),
  ('hafs-7-19', 'hafs', 7, 19, 'وَيَٰٓـَٔادَمُ ٱسْكُنْ أَنتَ وَزَوْجُكَ ٱلْجَنَّةَ فَكُلَا مِنْ حَيْثُ شِئْتُمَا وَلَا تَقْرَبَا هَٰذِهِ ٱلشَّجَرَةَ فَتَكُونَا مِنَ ٱلظَّٰلِمِينَ', 'ويادم اسكن أنت وزوجك الجنة فكلا من حيث شئتما ولا تقربا هذه الشجرة فتكونا من الظلمين', NULL, 152, 'local:hafs-text.json'),
  ('hafs-7-20', 'hafs', 7, 20, 'فَوَسْوَسَ لَهُمَا ٱلشَّيْطَٰنُ لِيُبْدِىَ لَهُمَا مَا وُۥرِىَ عَنْهُمَا مِن سَوْءَٰتِهِمَا وَقَالَ مَا نَهَىٰكُمَا رَبُّكُمَا عَنْ هَٰذِهِ ٱلشَّجَرَةِ إِلَّآ أَن تَكُونَا مَلَكَيْنِ أَوْ تَكُونَا مِنَ ٱلْخَٰلِدِينَ', 'فوسوس لهما الشيطن ليبدى لهما ما ورى عنهما من سوءتهما وقال ما نهىكما ربكما عن هذه الشجرة إلا أن تكونا ملكين أو تكونا من الخلدين', NULL, 152, 'local:hafs-text.json'),
  ('hafs-7-21', 'hafs', 7, 21, 'وَقَاسَمَهُمَآ إِنِّى لَكُمَا لَمِنَ ٱلنَّٰصِحِينَ', 'وقاسمهما إنى لكما لمن النصحين', NULL, 152, 'local:hafs-text.json'),
  ('hafs-7-22', 'hafs', 7, 22, 'فَدَلَّىٰهُمَا بِغُرُورٍۢ ۚ فَلَمَّا ذَاقَا ٱلشَّجَرَةَ بَدَتْ لَهُمَا سَوْءَٰتُهُمَا وَطَفِقَا يَخْصِفَانِ عَلَيْهِمَا مِن وَرَقِ ٱلْجَنَّةِ ۖ وَنَادَىٰهُمَا رَبُّهُمَآ أَلَمْ أَنْهَكُمَا عَن تِلْكُمَا ٱلشَّجَرَةِ وَأَقُل لَّكُمَآ إِنَّ ٱلشَّيْطَٰنَ لَكُمَا عَدُوٌّۭ مُّبِينٌۭ', 'فدلىهما بغرور  فلما ذاقا الشجرة بدت لهما سوءتهما وطفقا يخصفان عليهما من ورق الجنة  ونادىهما ربهما ألم أنهكما عن تلكما الشجرة وأقل لكما إن الشيطن لكما عدو مبين', NULL, 152, 'local:hafs-text.json'),
  ('hafs-7-23', 'hafs', 7, 23, 'قَالَا رَبَّنَا ظَلَمْنَآ أَنفُسَنَا وَإِن لَّمْ تَغْفِرْ لَنَا وَتَرْحَمْنَا لَنَكُونَنَّ مِنَ ٱلْخَٰسِرِينَ', 'قالا ربنا ظلمنا أنفسنا وإن لم تغفر لنا وترحمنا لنكونن من الخسرين', NULL, 153, 'local:hafs-text.json'),
  ('hafs-7-24', 'hafs', 7, 24, 'قَالَ ٱهْبِطُوا۟ بَعْضُكُمْ لِبَعْضٍ عَدُوٌّۭ ۖ وَلَكُمْ فِى ٱلْأَرْضِ مُسْتَقَرٌّۭ وَمَتَٰعٌ إِلَىٰ حِينٍۢ', 'قال اهبطوا بعضكم لبعض عدو  ولكم فى الأرض مستقر ومتع إلى حين', NULL, 153, 'local:hafs-text.json'),
  ('hafs-7-25', 'hafs', 7, 25, 'قَالَ فِيهَا تَحْيَوْنَ وَفِيهَا تَمُوتُونَ وَمِنْهَا تُخْرَجُونَ', 'قال فيها تحيون وفيها تموتون ومنها تخرجون', NULL, 153, 'local:hafs-text.json'),
  ('hafs-7-26', 'hafs', 7, 26, 'يَٰبَنِىٓ ءَادَمَ قَدْ أَنزَلْنَا عَلَيْكُمْ لِبَاسًۭا يُوَٰرِى سَوْءَٰتِكُمْ وَرِيشًۭا ۖ وَلِبَاسُ ٱلتَّقْوَىٰ ذَٰلِكَ خَيْرٌۭ ۚ ذَٰلِكَ مِنْ ءَايَٰتِ ٱللَّهِ لَعَلَّهُمْ يَذَّكَّرُونَ', 'يبنى ءادم قد أنزلنا عليكم لباسا يورى سوءتكم وريشا  ولباس التقوى ذلك خير  ذلك من ءايت الله لعلهم يذكرون', NULL, 153, 'local:hafs-text.json'),
  ('hafs-7-27', 'hafs', 7, 27, 'يَٰبَنِىٓ ءَادَمَ لَا يَفْتِنَنَّكُمُ ٱلشَّيْطَٰنُ كَمَآ أَخْرَجَ أَبَوَيْكُم مِّنَ ٱلْجَنَّةِ يَنزِعُ عَنْهُمَا لِبَاسَهُمَا لِيُرِيَهُمَا سَوْءَٰتِهِمَآ ۗ إِنَّهُۥ يَرَىٰكُمْ هُوَ وَقَبِيلُهُۥ مِنْ حَيْثُ لَا تَرَوْنَهُمْ ۗ إِنَّا جَعَلْنَا ٱلشَّيَٰطِينَ أَوْلِيَآءَ لِلَّذِينَ لَا يُؤْمِنُونَ', 'يبنى ءادم لا يفتننكم الشيطن كما أخرج أبويكم من الجنة ينزع عنهما لباسهما ليريهما سوءتهما  إنه يرىكم هو وقبيله من حيث لا ترونهم  إنا جعلنا الشيطين أولياء للذين لا يؤمنون', NULL, 153, 'local:hafs-text.json'),
  ('hafs-7-28', 'hafs', 7, 28, 'وَإِذَا فَعَلُوا۟ فَٰحِشَةًۭ قَالُوا۟ وَجَدْنَا عَلَيْهَآ ءَابَآءَنَا وَٱللَّهُ أَمَرَنَا بِهَا ۗ قُلْ إِنَّ ٱللَّهَ لَا يَأْمُرُ بِٱلْفَحْشَآءِ ۖ أَتَقُولُونَ عَلَى ٱللَّهِ مَا لَا تَعْلَمُونَ', 'وإذا فعلوا فحشة قالوا وجدنا عليها ءاباءنا والله أمرنا بها  قل إن الله لا يأمر بالفحشاء  أتقولون على الله ما لا تعلمون', NULL, 153, 'local:hafs-text.json'),
  ('hafs-7-29', 'hafs', 7, 29, 'قُلْ أَمَرَ رَبِّى بِٱلْقِسْطِ ۖ وَأَقِيمُوا۟ وُجُوهَكُمْ عِندَ كُلِّ مَسْجِدٍۢ وَٱدْعُوهُ مُخْلِصِينَ لَهُ ٱلدِّينَ ۚ كَمَا بَدَأَكُمْ تَعُودُونَ', 'قل أمر ربى بالقسط  وأقيموا وجوهكم عند كل مسجد وادعوه مخلصين له الدين  كما بدأكم تعودون', NULL, 153, 'local:hafs-text.json'),
  ('hafs-7-30', 'hafs', 7, 30, 'فَرِيقًا هَدَىٰ وَفَرِيقًا حَقَّ عَلَيْهِمُ ٱلضَّلَٰلَةُ ۗ إِنَّهُمُ ٱتَّخَذُوا۟ ٱلشَّيَٰطِينَ أَوْلِيَآءَ مِن دُونِ ٱللَّهِ وَيَحْسَبُونَ أَنَّهُم مُّهْتَدُونَ', 'فريقا هدى وفريقا حق عليهم الضللة  إنهم اتخذوا الشيطين أولياء من دون الله ويحسبون أنهم مهتدون', NULL, 153, 'local:hafs-text.json'),
  ('hafs-7-31', 'hafs', 7, 31, '۞ يَٰبَنِىٓ ءَادَمَ خُذُوا۟ زِينَتَكُمْ عِندَ كُلِّ مَسْجِدٍۢ وَكُلُوا۟ وَٱشْرَبُوا۟ وَلَا تُسْرِفُوٓا۟ ۚ إِنَّهُۥ لَا يُحِبُّ ٱلْمُسْرِفِينَ', 'يبنى ءادم خذوا زينتكم عند كل مسجد وكلوا واشربوا ولا تسرفوا  إنه لا يحب المسرفين', NULL, 154, 'local:hafs-text.json'),
  ('hafs-7-32', 'hafs', 7, 32, 'قُلْ مَنْ حَرَّمَ زِينَةَ ٱللَّهِ ٱلَّتِىٓ أَخْرَجَ لِعِبَادِهِۦ وَٱلطَّيِّبَٰتِ مِنَ ٱلرِّزْقِ ۚ قُلْ هِىَ لِلَّذِينَ ءَامَنُوا۟ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا خَالِصَةًۭ يَوْمَ ٱلْقِيَٰمَةِ ۗ كَذَٰلِكَ نُفَصِّلُ ٱلْءَايَٰتِ لِقَوْمٍۢ يَعْلَمُونَ', 'قل من حرم زينة الله التى أخرج لعباده والطيبت من الرزق  قل هى للذين ءامنوا فى الحيوة الدنيا خالصة يوم القيمة  كذلك نفصل الءايت لقوم يعلمون', NULL, 154, 'local:hafs-text.json'),
  ('hafs-7-33', 'hafs', 7, 33, 'قُلْ إِنَّمَا حَرَّمَ رَبِّىَ ٱلْفَوَٰحِشَ مَا ظَهَرَ مِنْهَا وَمَا بَطَنَ وَٱلْإِثْمَ وَٱلْبَغْىَ بِغَيْرِ ٱلْحَقِّ وَأَن تُشْرِكُوا۟ بِٱللَّهِ مَا لَمْ يُنَزِّلْ بِهِۦ سُلْطَٰنًۭا وَأَن تَقُولُوا۟ عَلَى ٱللَّهِ مَا لَا تَعْلَمُونَ', 'قل إنما حرم ربى الفوحش ما ظهر منها وما بطن والإثم والبغى بغير الحق وأن تشركوا بالله ما لم ينزل به سلطنا وأن تقولوا على الله ما لا تعلمون', NULL, 154, 'local:hafs-text.json'),
  ('hafs-7-34', 'hafs', 7, 34, 'وَلِكُلِّ أُمَّةٍ أَجَلٌۭ ۖ فَإِذَا جَآءَ أَجَلُهُمْ لَا يَسْتَأْخِرُونَ سَاعَةًۭ ۖ وَلَا يَسْتَقْدِمُونَ', 'ولكل أمة أجل  فإذا جاء أجلهم لا يستأخرون ساعة  ولا يستقدمون', NULL, 154, 'local:hafs-text.json'),
  ('hafs-7-35', 'hafs', 7, 35, 'يَٰبَنِىٓ ءَادَمَ إِمَّا يَأْتِيَنَّكُمْ رُسُلٌۭ مِّنكُمْ يَقُصُّونَ عَلَيْكُمْ ءَايَٰتِى ۙ فَمَنِ ٱتَّقَىٰ وَأَصْلَحَ فَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ', 'يبنى ءادم إما يأتينكم رسل منكم يقصون عليكم ءايتى  فمن اتقى وأصلح فلا خوف عليهم ولا هم يحزنون', NULL, 154, 'local:hafs-text.json'),
  ('hafs-7-36', 'hafs', 7, 36, 'وَٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَٰتِنَا وَٱسْتَكْبَرُوا۟ عَنْهَآ أُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلنَّارِ ۖ هُمْ فِيهَا خَٰلِدُونَ', 'والذين كذبوا بايتنا واستكبروا عنها أولئك أصحب النار  هم فيها خلدون', NULL, 154, 'local:hafs-text.json'),
  ('hafs-7-37', 'hafs', 7, 37, 'فَمَنْ أَظْلَمُ مِمَّنِ ٱفْتَرَىٰ عَلَى ٱللَّهِ كَذِبًا أَوْ كَذَّبَ بِـَٔايَٰتِهِۦٓ ۚ أُو۟لَٰٓئِكَ يَنَالُهُمْ نَصِيبُهُم مِّنَ ٱلْكِتَٰبِ ۖ حَتَّىٰٓ إِذَا جَآءَتْهُمْ رُسُلُنَا يَتَوَفَّوْنَهُمْ قَالُوٓا۟ أَيْنَ مَا كُنتُمْ تَدْعُونَ مِن دُونِ ٱللَّهِ ۖ قَالُوا۟ ضَلُّوا۟ عَنَّا وَشَهِدُوا۟ عَلَىٰٓ أَنفُسِهِمْ أَنَّهُمْ كَانُوا۟ كَٰفِرِينَ', 'فمن أظلم ممن افترى على الله كذبا أو كذب بايته  أولئك ينالهم نصيبهم من الكتب  حتى إذا جاءتهم رسلنا يتوفونهم قالوا أين ما كنتم تدعون من دون الله  قالوا ضلوا عنا وشهدوا على أنفسهم أنهم كانوا كفرين', NULL, 154, 'local:hafs-text.json'),
  ('hafs-7-38', 'hafs', 7, 38, 'قَالَ ٱدْخُلُوا۟ فِىٓ أُمَمٍۢ قَدْ خَلَتْ مِن قَبْلِكُم مِّنَ ٱلْجِنِّ وَٱلْإِنسِ فِى ٱلنَّارِ ۖ كُلَّمَا دَخَلَتْ أُمَّةٌۭ لَّعَنَتْ أُخْتَهَا ۖ حَتَّىٰٓ إِذَا ٱدَّارَكُوا۟ فِيهَا جَمِيعًۭا قَالَتْ أُخْرَىٰهُمْ لِأُولَىٰهُمْ رَبَّنَا هَٰٓؤُلَآءِ أَضَلُّونَا فَـَٔاتِهِمْ عَذَابًۭا ضِعْفًۭا مِّنَ ٱلنَّارِ ۖ قَالَ لِكُلٍّۢ ضِعْفٌۭ وَلَٰكِن لَّا تَعْلَمُونَ', 'قال ادخلوا فى أمم قد خلت من قبلكم من الجن والإنس فى النار  كلما دخلت أمة لعنت أختها  حتى إذا اداركوا فيها جميعا قالت أخرىهم لأولىهم ربنا هؤلاء أضلونا فاتهم عذابا ضعفا من النار  قال لكل ضعف ولكن لا تعلمون', NULL, 155, 'local:hafs-text.json'),
  ('hafs-7-39', 'hafs', 7, 39, 'وَقَالَتْ أُولَىٰهُمْ لِأُخْرَىٰهُمْ فَمَا كَانَ لَكُمْ عَلَيْنَا مِن فَضْلٍۢ فَذُوقُوا۟ ٱلْعَذَابَ بِمَا كُنتُمْ تَكْسِبُونَ', 'وقالت أولىهم لأخرىهم فما كان لكم علينا من فضل فذوقوا العذاب بما كنتم تكسبون', NULL, 155, 'local:hafs-text.json'),
  ('hafs-7-40', 'hafs', 7, 40, 'إِنَّ ٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَٰتِنَا وَٱسْتَكْبَرُوا۟ عَنْهَا لَا تُفَتَّحُ لَهُمْ أَبْوَٰبُ ٱلسَّمَآءِ وَلَا يَدْخُلُونَ ٱلْجَنَّةَ حَتَّىٰ يَلِجَ ٱلْجَمَلُ فِى سَمِّ ٱلْخِيَاطِ ۚ وَكَذَٰلِكَ نَجْزِى ٱلْمُجْرِمِينَ', 'إن الذين كذبوا بايتنا واستكبروا عنها لا تفتح لهم أبوب السماء ولا يدخلون الجنة حتى يلج الجمل فى سم الخياط  وكذلك نجزى المجرمين', NULL, 155, 'local:hafs-text.json'),
  ('hafs-7-41', 'hafs', 7, 41, 'لَهُم مِّن جَهَنَّمَ مِهَادٌۭ وَمِن فَوْقِهِمْ غَوَاشٍۢ ۚ وَكَذَٰلِكَ نَجْزِى ٱلظَّٰلِمِينَ', 'لهم من جهنم مهاد ومن فوقهم غواش  وكذلك نجزى الظلمين', NULL, 155, 'local:hafs-text.json'),
  ('hafs-7-42', 'hafs', 7, 42, 'وَٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ لَا نُكَلِّفُ نَفْسًا إِلَّا وُسْعَهَآ أُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلْجَنَّةِ ۖ هُمْ فِيهَا خَٰلِدُونَ', 'والذين ءامنوا وعملوا الصلحت لا نكلف نفسا إلا وسعها أولئك أصحب الجنة  هم فيها خلدون', NULL, 155, 'local:hafs-text.json'),
  ('hafs-7-43', 'hafs', 7, 43, 'وَنَزَعْنَا مَا فِى صُدُورِهِم مِّنْ غِلٍّۢ تَجْرِى مِن تَحْتِهِمُ ٱلْأَنْهَٰرُ ۖ وَقَالُوا۟ ٱلْحَمْدُ لِلَّهِ ٱلَّذِى هَدَىٰنَا لِهَٰذَا وَمَا كُنَّا لِنَهْتَدِىَ لَوْلَآ أَنْ هَدَىٰنَا ٱللَّهُ ۖ لَقَدْ جَآءَتْ رُسُلُ رَبِّنَا بِٱلْحَقِّ ۖ وَنُودُوٓا۟ أَن تِلْكُمُ ٱلْجَنَّةُ أُورِثْتُمُوهَا بِمَا كُنتُمْ تَعْمَلُونَ', 'ونزعنا ما فى صدورهم من غل تجرى من تحتهم الأنهر  وقالوا الحمد لله الذى هدىنا لهذا وما كنا لنهتدى لولا أن هدىنا الله  لقد جاءت رسل ربنا بالحق  ونودوا أن تلكم الجنة أورثتموها بما كنتم تعملون', NULL, 155, 'local:hafs-text.json'),
  ('hafs-7-44', 'hafs', 7, 44, 'وَنَادَىٰٓ أَصْحَٰبُ ٱلْجَنَّةِ أَصْحَٰبَ ٱلنَّارِ أَن قَدْ وَجَدْنَا مَا وَعَدَنَا رَبُّنَا حَقًّۭا فَهَلْ وَجَدتُّم مَّا وَعَدَ رَبُّكُمْ حَقًّۭا ۖ قَالُوا۟ نَعَمْ ۚ فَأَذَّنَ مُؤَذِّنٌۢ بَيْنَهُمْ أَن لَّعْنَةُ ٱللَّهِ عَلَى ٱلظَّٰلِمِينَ', 'ونادى أصحب الجنة أصحب النار أن قد وجدنا ما وعدنا ربنا حقا فهل وجدتم ما وعد ربكم حقا  قالوا نعم  فأذن مؤذن بينهم أن لعنة الله على الظلمين', NULL, 156, 'local:hafs-text.json'),
  ('hafs-7-45', 'hafs', 7, 45, 'ٱلَّذِينَ يَصُدُّونَ عَن سَبِيلِ ٱللَّهِ وَيَبْغُونَهَا عِوَجًۭا وَهُم بِٱلْءَاخِرَةِ كَٰفِرُونَ', 'الذين يصدون عن سبيل الله ويبغونها عوجا وهم بالءاخرة كفرون', NULL, 156, 'local:hafs-text.json'),
  ('hafs-7-46', 'hafs', 7, 46, 'وَبَيْنَهُمَا حِجَابٌۭ ۚ وَعَلَى ٱلْأَعْرَافِ رِجَالٌۭ يَعْرِفُونَ كُلًّۢا بِسِيمَىٰهُمْ ۚ وَنَادَوْا۟ أَصْحَٰبَ ٱلْجَنَّةِ أَن سَلَٰمٌ عَلَيْكُمْ ۚ لَمْ يَدْخُلُوهَا وَهُمْ يَطْمَعُونَ', 'وبينهما حجاب  وعلى الأعراف رجال يعرفون كلا بسيمىهم  ونادوا أصحب الجنة أن سلم عليكم  لم يدخلوها وهم يطمعون', NULL, 156, 'local:hafs-text.json'),
  ('hafs-7-47', 'hafs', 7, 47, '۞ وَإِذَا صُرِفَتْ أَبْصَٰرُهُمْ تِلْقَآءَ أَصْحَٰبِ ٱلنَّارِ قَالُوا۟ رَبَّنَا لَا تَجْعَلْنَا مَعَ ٱلْقَوْمِ ٱلظَّٰلِمِينَ', 'وإذا صرفت أبصرهم تلقاء أصحب النار قالوا ربنا لا تجعلنا مع القوم الظلمين', NULL, 156, 'local:hafs-text.json'),
  ('hafs-7-48', 'hafs', 7, 48, 'وَنَادَىٰٓ أَصْحَٰبُ ٱلْأَعْرَافِ رِجَالًۭا يَعْرِفُونَهُم بِسِيمَىٰهُمْ قَالُوا۟ مَآ أَغْنَىٰ عَنكُمْ جَمْعُكُمْ وَمَا كُنتُمْ تَسْتَكْبِرُونَ', 'ونادى أصحب الأعراف رجالا يعرفونهم بسيمىهم قالوا ما أغنى عنكم جمعكم وما كنتم تستكبرون', NULL, 156, 'local:hafs-text.json'),
  ('hafs-7-49', 'hafs', 7, 49, 'أَهَٰٓؤُلَآءِ ٱلَّذِينَ أَقْسَمْتُمْ لَا يَنَالُهُمُ ٱللَّهُ بِرَحْمَةٍ ۚ ٱدْخُلُوا۟ ٱلْجَنَّةَ لَا خَوْفٌ عَلَيْكُمْ وَلَآ أَنتُمْ تَحْزَنُونَ', 'أهؤلاء الذين أقسمتم لا ينالهم الله برحمة  ادخلوا الجنة لا خوف عليكم ولا أنتم تحزنون', NULL, 156, 'local:hafs-text.json'),
  ('hafs-7-50', 'hafs', 7, 50, 'وَنَادَىٰٓ أَصْحَٰبُ ٱلنَّارِ أَصْحَٰبَ ٱلْجَنَّةِ أَنْ أَفِيضُوا۟ عَلَيْنَا مِنَ ٱلْمَآءِ أَوْ مِمَّا رَزَقَكُمُ ٱللَّهُ ۚ قَالُوٓا۟ إِنَّ ٱللَّهَ حَرَّمَهُمَا عَلَى ٱلْكَٰفِرِينَ', 'ونادى أصحب النار أصحب الجنة أن أفيضوا علينا من الماء أو مما رزقكم الله  قالوا إن الله حرمهما على الكفرين', NULL, 156, 'local:hafs-text.json'),
  ('hafs-7-51', 'hafs', 7, 51, 'ٱلَّذِينَ ٱتَّخَذُوا۟ دِينَهُمْ لَهْوًۭا وَلَعِبًۭا وَغَرَّتْهُمُ ٱلْحَيَوٰةُ ٱلدُّنْيَا ۚ فَٱلْيَوْمَ نَنسَىٰهُمْ كَمَا نَسُوا۟ لِقَآءَ يَوْمِهِمْ هَٰذَا وَمَا كَانُوا۟ بِـَٔايَٰتِنَا يَجْحَدُونَ', 'الذين اتخذوا دينهم لهوا ولعبا وغرتهم الحيوة الدنيا  فاليوم ننسىهم كما نسوا لقاء يومهم هذا وما كانوا بايتنا يجحدون', NULL, 156, 'local:hafs-text.json'),
  ('hafs-7-52', 'hafs', 7, 52, 'وَلَقَدْ جِئْنَٰهُم بِكِتَٰبٍۢ فَصَّلْنَٰهُ عَلَىٰ عِلْمٍ هُدًۭى وَرَحْمَةًۭ لِّقَوْمٍۢ يُؤْمِنُونَ', 'ولقد جئنهم بكتب فصلنه على علم هدى ورحمة لقوم يؤمنون', NULL, 157, 'local:hafs-text.json'),
  ('hafs-7-53', 'hafs', 7, 53, 'هَلْ يَنظُرُونَ إِلَّا تَأْوِيلَهُۥ ۚ يَوْمَ يَأْتِى تَأْوِيلُهُۥ يَقُولُ ٱلَّذِينَ نَسُوهُ مِن قَبْلُ قَدْ جَآءَتْ رُسُلُ رَبِّنَا بِٱلْحَقِّ فَهَل لَّنَا مِن شُفَعَآءَ فَيَشْفَعُوا۟ لَنَآ أَوْ نُرَدُّ فَنَعْمَلَ غَيْرَ ٱلَّذِى كُنَّا نَعْمَلُ ۚ قَدْ خَسِرُوٓا۟ أَنفُسَهُمْ وَضَلَّ عَنْهُم مَّا كَانُوا۟ يَفْتَرُونَ', 'هل ينظرون إلا تأويله  يوم يأتى تأويله يقول الذين نسوه من قبل قد جاءت رسل ربنا بالحق فهل لنا من شفعاء فيشفعوا لنا أو نرد فنعمل غير الذى كنا نعمل  قد خسروا أنفسهم وضل عنهم ما كانوا يفترون', NULL, 157, 'local:hafs-text.json'),
  ('hafs-7-54', 'hafs', 7, 54, 'إِنَّ رَبَّكُمُ ٱللَّهُ ٱلَّذِى خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ فِى سِتَّةِ أَيَّامٍۢ ثُمَّ ٱسْتَوَىٰ عَلَى ٱلْعَرْشِ يُغْشِى ٱلَّيْلَ ٱلنَّهَارَ يَطْلُبُهُۥ حَثِيثًۭا وَٱلشَّمْسَ وَٱلْقَمَرَ وَٱلنُّجُومَ مُسَخَّرَٰتٍۭ بِأَمْرِهِۦٓ ۗ أَلَا لَهُ ٱلْخَلْقُ وَٱلْأَمْرُ ۗ تَبَارَكَ ٱللَّهُ رَبُّ ٱلْعَٰلَمِينَ', 'إن ربكم الله الذى خلق السموت والأرض فى ستة أيام ثم استوى على العرش يغشى اليل النهار يطلبه حثيثا والشمس والقمر والنجوم مسخرت بأمره  ألا له الخلق والأمر  تبارك الله رب العلمين', NULL, 157, 'local:hafs-text.json'),
  ('hafs-7-55', 'hafs', 7, 55, 'ٱدْعُوا۟ رَبَّكُمْ تَضَرُّعًۭا وَخُفْيَةً ۚ إِنَّهُۥ لَا يُحِبُّ ٱلْمُعْتَدِينَ', 'ادعوا ربكم تضرعا وخفية  إنه لا يحب المعتدين', NULL, 157, 'local:hafs-text.json'),
  ('hafs-7-56', 'hafs', 7, 56, 'وَلَا تُفْسِدُوا۟ فِى ٱلْأَرْضِ بَعْدَ إِصْلَٰحِهَا وَٱدْعُوهُ خَوْفًۭا وَطَمَعًا ۚ إِنَّ رَحْمَتَ ٱللَّهِ قَرِيبٌۭ مِّنَ ٱلْمُحْسِنِينَ', 'ولا تفسدوا فى الأرض بعد إصلحها وادعوه خوفا وطمعا  إن رحمت الله قريب من المحسنين', NULL, 157, 'local:hafs-text.json'),
  ('hafs-7-57', 'hafs', 7, 57, 'وَهُوَ ٱلَّذِى يُرْسِلُ ٱلرِّيَٰحَ بُشْرًۢا بَيْنَ يَدَىْ رَحْمَتِهِۦ ۖ حَتَّىٰٓ إِذَآ أَقَلَّتْ سَحَابًۭا ثِقَالًۭا سُقْنَٰهُ لِبَلَدٍۢ مَّيِّتٍۢ فَأَنزَلْنَا بِهِ ٱلْمَآءَ فَأَخْرَجْنَا بِهِۦ مِن كُلِّ ٱلثَّمَرَٰتِ ۚ كَذَٰلِكَ نُخْرِجُ ٱلْمَوْتَىٰ لَعَلَّكُمْ تَذَكَّرُونَ', 'وهو الذى يرسل الريح بشرا بين يدى رحمته  حتى إذا أقلت سحابا ثقالا سقنه لبلد ميت فأنزلنا به الماء فأخرجنا به من كل الثمرت  كذلك نخرج الموتى لعلكم تذكرون', NULL, 157, 'local:hafs-text.json'),
  ('hafs-7-58', 'hafs', 7, 58, 'وَٱلْبَلَدُ ٱلطَّيِّبُ يَخْرُجُ نَبَاتُهُۥ بِإِذْنِ رَبِّهِۦ ۖ وَٱلَّذِى خَبُثَ لَا يَخْرُجُ إِلَّا نَكِدًۭا ۚ كَذَٰلِكَ نُصَرِّفُ ٱلْءَايَٰتِ لِقَوْمٍۢ يَشْكُرُونَ', 'والبلد الطيب يخرج نباته بإذن ربه  والذى خبث لا يخرج إلا نكدا  كذلك نصرف الءايت لقوم يشكرون', NULL, 158, 'local:hafs-text.json'),
  ('hafs-7-59', 'hafs', 7, 59, 'لَقَدْ أَرْسَلْنَا نُوحًا إِلَىٰ قَوْمِهِۦ فَقَالَ يَٰقَوْمِ ٱعْبُدُوا۟ ٱللَّهَ مَا لَكُم مِّنْ إِلَٰهٍ غَيْرُهُۥٓ إِنِّىٓ أَخَافُ عَلَيْكُمْ عَذَابَ يَوْمٍ عَظِيمٍۢ', 'لقد أرسلنا نوحا إلى قومه فقال يقوم اعبدوا الله ما لكم من إله غيره إنى أخاف عليكم عذاب يوم عظيم', NULL, 158, 'local:hafs-text.json'),
  ('hafs-7-60', 'hafs', 7, 60, 'قَالَ ٱلْمَلَأُ مِن قَوْمِهِۦٓ إِنَّا لَنَرَىٰكَ فِى ضَلَٰلٍۢ مُّبِينٍۢ', 'قال الملأ من قومه إنا لنرىك فى ضلل مبين', NULL, 158, 'local:hafs-text.json'),
  ('hafs-7-61', 'hafs', 7, 61, 'قَالَ يَٰقَوْمِ لَيْسَ بِى ضَلَٰلَةٌۭ وَلَٰكِنِّى رَسُولٌۭ مِّن رَّبِّ ٱلْعَٰلَمِينَ', 'قال يقوم ليس بى ضللة ولكنى رسول من رب العلمين', NULL, 158, 'local:hafs-text.json'),
  ('hafs-7-62', 'hafs', 7, 62, 'أُبَلِّغُكُمْ رِسَٰلَٰتِ رَبِّى وَأَنصَحُ لَكُمْ وَأَعْلَمُ مِنَ ٱللَّهِ مَا لَا تَعْلَمُونَ', 'أبلغكم رسلت ربى وأنصح لكم وأعلم من الله ما لا تعلمون', NULL, 158, 'local:hafs-text.json'),
  ('hafs-7-63', 'hafs', 7, 63, 'أَوَعَجِبْتُمْ أَن جَآءَكُمْ ذِكْرٌۭ مِّن رَّبِّكُمْ عَلَىٰ رَجُلٍۢ مِّنكُمْ لِيُنذِرَكُمْ وَلِتَتَّقُوا۟ وَلَعَلَّكُمْ تُرْحَمُونَ', 'أوعجبتم أن جاءكم ذكر من ربكم على رجل منكم لينذركم ولتتقوا ولعلكم ترحمون', NULL, 158, 'local:hafs-text.json'),
  ('hafs-7-64', 'hafs', 7, 64, 'فَكَذَّبُوهُ فَأَنجَيْنَٰهُ وَٱلَّذِينَ مَعَهُۥ فِى ٱلْفُلْكِ وَأَغْرَقْنَا ٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَٰتِنَآ ۚ إِنَّهُمْ كَانُوا۟ قَوْمًا عَمِينَ', 'فكذبوه فأنجينه والذين معه فى الفلك وأغرقنا الذين كذبوا بايتنا  إنهم كانوا قوما عمين', NULL, 158, 'local:hafs-text.json'),
  ('hafs-7-65', 'hafs', 7, 65, '۞ وَإِلَىٰ عَادٍ أَخَاهُمْ هُودًۭا ۗ قَالَ يَٰقَوْمِ ٱعْبُدُوا۟ ٱللَّهَ مَا لَكُم مِّنْ إِلَٰهٍ غَيْرُهُۥٓ ۚ أَفَلَا تَتَّقُونَ', 'وإلى عاد أخاهم هودا  قال يقوم اعبدوا الله ما لكم من إله غيره  أفلا تتقون', NULL, 158, 'local:hafs-text.json'),
  ('hafs-7-66', 'hafs', 7, 66, 'قَالَ ٱلْمَلَأُ ٱلَّذِينَ كَفَرُوا۟ مِن قَوْمِهِۦٓ إِنَّا لَنَرَىٰكَ فِى سَفَاهَةٍۢ وَإِنَّا لَنَظُنُّكَ مِنَ ٱلْكَٰذِبِينَ', 'قال الملأ الذين كفروا من قومه إنا لنرىك فى سفاهة وإنا لنظنك من الكذبين', NULL, 158, 'local:hafs-text.json'),
  ('hafs-7-67', 'hafs', 7, 67, 'قَالَ يَٰقَوْمِ لَيْسَ بِى سَفَاهَةٌۭ وَلَٰكِنِّى رَسُولٌۭ مِّن رَّبِّ ٱلْعَٰلَمِينَ', 'قال يقوم ليس بى سفاهة ولكنى رسول من رب العلمين', NULL, 158, 'local:hafs-text.json'),
  ('hafs-7-68', 'hafs', 7, 68, 'أُبَلِّغُكُمْ رِسَٰلَٰتِ رَبِّى وَأَنَا۠ لَكُمْ نَاصِحٌ أَمِينٌ', 'أبلغكم رسلت ربى وأنا لكم ناصح أمين', NULL, 159, 'local:hafs-text.json'),
  ('hafs-7-69', 'hafs', 7, 69, 'أَوَعَجِبْتُمْ أَن جَآءَكُمْ ذِكْرٌۭ مِّن رَّبِّكُمْ عَلَىٰ رَجُلٍۢ مِّنكُمْ لِيُنذِرَكُمْ ۚ وَٱذْكُرُوٓا۟ إِذْ جَعَلَكُمْ خُلَفَآءَ مِنۢ بَعْدِ قَوْمِ نُوحٍۢ وَزَادَكُمْ فِى ٱلْخَلْقِ بَصْۜطَةًۭ ۖ فَٱذْكُرُوٓا۟ ءَالَآءَ ٱللَّهِ لَعَلَّكُمْ تُفْلِحُونَ', 'أوعجبتم أن جاءكم ذكر من ربكم على رجل منكم لينذركم  واذكروا إذ جعلكم خلفاء من بعد قوم نوح وزادكم فى الخلق بصطة  فاذكروا ءالاء الله لعلكم تفلحون', NULL, 159, 'local:hafs-text.json'),
  ('hafs-7-70', 'hafs', 7, 70, 'قَالُوٓا۟ أَجِئْتَنَا لِنَعْبُدَ ٱللَّهَ وَحْدَهُۥ وَنَذَرَ مَا كَانَ يَعْبُدُ ءَابَآؤُنَا ۖ فَأْتِنَا بِمَا تَعِدُنَآ إِن كُنتَ مِنَ ٱلصَّٰدِقِينَ', 'قالوا أجئتنا لنعبد الله وحده ونذر ما كان يعبد ءاباؤنا  فأتنا بما تعدنا إن كنت من الصدقين', NULL, 159, 'local:hafs-text.json'),
  ('hafs-7-71', 'hafs', 7, 71, 'قَالَ قَدْ وَقَعَ عَلَيْكُم مِّن رَّبِّكُمْ رِجْسٌۭ وَغَضَبٌ ۖ أَتُجَٰدِلُونَنِى فِىٓ أَسْمَآءٍۢ سَمَّيْتُمُوهَآ أَنتُمْ وَءَابَآؤُكُم مَّا نَزَّلَ ٱللَّهُ بِهَا مِن سُلْطَٰنٍۢ ۚ فَٱنتَظِرُوٓا۟ إِنِّى مَعَكُم مِّنَ ٱلْمُنتَظِرِينَ', 'قال قد وقع عليكم من ربكم رجس وغضب  أتجدلوننى فى أسماء سميتموها أنتم وءاباؤكم ما نزل الله بها من سلطن  فانتظروا إنى معكم من المنتظرين', NULL, 159, 'local:hafs-text.json'),
  ('hafs-7-72', 'hafs', 7, 72, 'فَأَنجَيْنَٰهُ وَٱلَّذِينَ مَعَهُۥ بِرَحْمَةٍۢ مِّنَّا وَقَطَعْنَا دَابِرَ ٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَٰتِنَا ۖ وَمَا كَانُوا۟ مُؤْمِنِينَ', 'فأنجينه والذين معه برحمة منا وقطعنا دابر الذين كذبوا بايتنا  وما كانوا مؤمنين', NULL, 159, 'local:hafs-text.json'),
  ('hafs-7-73', 'hafs', 7, 73, 'وَإِلَىٰ ثَمُودَ أَخَاهُمْ صَٰلِحًۭا ۗ قَالَ يَٰقَوْمِ ٱعْبُدُوا۟ ٱللَّهَ مَا لَكُم مِّنْ إِلَٰهٍ غَيْرُهُۥ ۖ قَدْ جَآءَتْكُم بَيِّنَةٌۭ مِّن رَّبِّكُمْ ۖ هَٰذِهِۦ نَاقَةُ ٱللَّهِ لَكُمْ ءَايَةًۭ ۖ فَذَرُوهَا تَأْكُلْ فِىٓ أَرْضِ ٱللَّهِ ۖ وَلَا تَمَسُّوهَا بِسُوٓءٍۢ فَيَأْخُذَكُمْ عَذَابٌ أَلِيمٌۭ', 'وإلى ثمود أخاهم صلحا  قال يقوم اعبدوا الله ما لكم من إله غيره  قد جاءتكم بينة من ربكم  هذه ناقة الله لكم ءاية  فذروها تأكل فى أرض الله  ولا تمسوها بسوء فيأخذكم عذاب أليم', NULL, 159, 'local:hafs-text.json'),
  ('hafs-7-74', 'hafs', 7, 74, 'وَٱذْكُرُوٓا۟ إِذْ جَعَلَكُمْ خُلَفَآءَ مِنۢ بَعْدِ عَادٍۢ وَبَوَّأَكُمْ فِى ٱلْأَرْضِ تَتَّخِذُونَ مِن سُهُولِهَا قُصُورًۭا وَتَنْحِتُونَ ٱلْجِبَالَ بُيُوتًۭا ۖ فَٱذْكُرُوٓا۟ ءَالَآءَ ٱللَّهِ وَلَا تَعْثَوْا۟ فِى ٱلْأَرْضِ مُفْسِدِينَ', 'واذكروا إذ جعلكم خلفاء من بعد عاد وبوأكم فى الأرض تتخذون من سهولها قصورا وتنحتون الجبال بيوتا  فاذكروا ءالاء الله ولا تعثوا فى الأرض مفسدين', NULL, 160, 'local:hafs-text.json'),
  ('hafs-7-75', 'hafs', 7, 75, 'قَالَ ٱلْمَلَأُ ٱلَّذِينَ ٱسْتَكْبَرُوا۟ مِن قَوْمِهِۦ لِلَّذِينَ ٱسْتُضْعِفُوا۟ لِمَنْ ءَامَنَ مِنْهُمْ أَتَعْلَمُونَ أَنَّ صَٰلِحًۭا مُّرْسَلٌۭ مِّن رَّبِّهِۦ ۚ قَالُوٓا۟ إِنَّا بِمَآ أُرْسِلَ بِهِۦ مُؤْمِنُونَ', 'قال الملأ الذين استكبروا من قومه للذين استضعفوا لمن ءامن منهم أتعلمون أن صلحا مرسل من ربه  قالوا إنا بما أرسل به مؤمنون', NULL, 160, 'local:hafs-text.json'),
  ('hafs-7-76', 'hafs', 7, 76, 'قَالَ ٱلَّذِينَ ٱسْتَكْبَرُوٓا۟ إِنَّا بِٱلَّذِىٓ ءَامَنتُم بِهِۦ كَٰفِرُونَ', 'قال الذين استكبروا إنا بالذى ءامنتم به كفرون', NULL, 160, 'local:hafs-text.json'),
  ('hafs-7-77', 'hafs', 7, 77, 'فَعَقَرُوا۟ ٱلنَّاقَةَ وَعَتَوْا۟ عَنْ أَمْرِ رَبِّهِمْ وَقَالُوا۟ يَٰصَٰلِحُ ٱئْتِنَا بِمَا تَعِدُنَآ إِن كُنتَ مِنَ ٱلْمُرْسَلِينَ', 'فعقروا الناقة وعتوا عن أمر ربهم وقالوا يصلح ائتنا بما تعدنا إن كنت من المرسلين', NULL, 160, 'local:hafs-text.json'),
  ('hafs-7-78', 'hafs', 7, 78, 'فَأَخَذَتْهُمُ ٱلرَّجْفَةُ فَأَصْبَحُوا۟ فِى دَارِهِمْ جَٰثِمِينَ', 'فأخذتهم الرجفة فأصبحوا فى دارهم جثمين', NULL, 160, 'local:hafs-text.json'),
  ('hafs-7-79', 'hafs', 7, 79, 'فَتَوَلَّىٰ عَنْهُمْ وَقَالَ يَٰقَوْمِ لَقَدْ أَبْلَغْتُكُمْ رِسَالَةَ رَبِّى وَنَصَحْتُ لَكُمْ وَلَٰكِن لَّا تُحِبُّونَ ٱلنَّٰصِحِينَ', 'فتولى عنهم وقال يقوم لقد أبلغتكم رسالة ربى ونصحت لكم ولكن لا تحبون النصحين', NULL, 160, 'local:hafs-text.json'),
  ('hafs-7-80', 'hafs', 7, 80, 'وَلُوطًا إِذْ قَالَ لِقَوْمِهِۦٓ أَتَأْتُونَ ٱلْفَٰحِشَةَ مَا سَبَقَكُم بِهَا مِنْ أَحَدٍۢ مِّنَ ٱلْعَٰلَمِينَ', 'ولوطا إذ قال لقومه أتأتون الفحشة ما سبقكم بها من أحد من العلمين', NULL, 160, 'local:hafs-text.json'),
  ('hafs-7-81', 'hafs', 7, 81, 'إِنَّكُمْ لَتَأْتُونَ ٱلرِّجَالَ شَهْوَةًۭ مِّن دُونِ ٱلنِّسَآءِ ۚ بَلْ أَنتُمْ قَوْمٌۭ مُّسْرِفُونَ', 'إنكم لتأتون الرجال شهوة من دون النساء  بل أنتم قوم مسرفون', NULL, 160, 'local:hafs-text.json'),
  ('hafs-7-82', 'hafs', 7, 82, 'وَمَا كَانَ جَوَابَ قَوْمِهِۦٓ إِلَّآ أَن قَالُوٓا۟ أَخْرِجُوهُم مِّن قَرْيَتِكُمْ ۖ إِنَّهُمْ أُنَاسٌۭ يَتَطَهَّرُونَ', 'وما كان جواب قومه إلا أن قالوا أخرجوهم من قريتكم  إنهم أناس يتطهرون', NULL, 161, 'local:hafs-text.json'),
  ('hafs-7-83', 'hafs', 7, 83, 'فَأَنجَيْنَٰهُ وَأَهْلَهُۥٓ إِلَّا ٱمْرَأَتَهُۥ كَانَتْ مِنَ ٱلْغَٰبِرِينَ', 'فأنجينه وأهله إلا امرأته كانت من الغبرين', NULL, 161, 'local:hafs-text.json'),
  ('hafs-7-84', 'hafs', 7, 84, 'وَأَمْطَرْنَا عَلَيْهِم مَّطَرًۭا ۖ فَٱنظُرْ كَيْفَ كَانَ عَٰقِبَةُ ٱلْمُجْرِمِينَ', 'وأمطرنا عليهم مطرا  فانظر كيف كان عقبة المجرمين', NULL, 161, 'local:hafs-text.json'),
  ('hafs-7-85', 'hafs', 7, 85, 'وَإِلَىٰ مَدْيَنَ أَخَاهُمْ شُعَيْبًۭا ۗ قَالَ يَٰقَوْمِ ٱعْبُدُوا۟ ٱللَّهَ مَا لَكُم مِّنْ إِلَٰهٍ غَيْرُهُۥ ۖ قَدْ جَآءَتْكُم بَيِّنَةٌۭ مِّن رَّبِّكُمْ ۖ فَأَوْفُوا۟ ٱلْكَيْلَ وَٱلْمِيزَانَ وَلَا تَبْخَسُوا۟ ٱلنَّاسَ أَشْيَآءَهُمْ وَلَا تُفْسِدُوا۟ فِى ٱلْأَرْضِ بَعْدَ إِصْلَٰحِهَا ۚ ذَٰلِكُمْ خَيْرٌۭ لَّكُمْ إِن كُنتُم مُّؤْمِنِينَ', 'وإلى مدين أخاهم شعيبا  قال يقوم اعبدوا الله ما لكم من إله غيره  قد جاءتكم بينة من ربكم  فأوفوا الكيل والميزان ولا تبخسوا الناس أشياءهم ولا تفسدوا فى الأرض بعد إصلحها  ذلكم خير لكم إن كنتم مؤمنين', NULL, 161, 'local:hafs-text.json'),
  ('hafs-7-86', 'hafs', 7, 86, 'وَلَا تَقْعُدُوا۟ بِكُلِّ صِرَٰطٍۢ تُوعِدُونَ وَتَصُدُّونَ عَن سَبِيلِ ٱللَّهِ مَنْ ءَامَنَ بِهِۦ وَتَبْغُونَهَا عِوَجًۭا ۚ وَٱذْكُرُوٓا۟ إِذْ كُنتُمْ قَلِيلًۭا فَكَثَّرَكُمْ ۖ وَٱنظُرُوا۟ كَيْفَ كَانَ عَٰقِبَةُ ٱلْمُفْسِدِينَ', 'ولا تقعدوا بكل صرط توعدون وتصدون عن سبيل الله من ءامن به وتبغونها عوجا  واذكروا إذ كنتم قليلا فكثركم  وانظروا كيف كان عقبة المفسدين', NULL, 161, 'local:hafs-text.json'),
  ('hafs-7-87', 'hafs', 7, 87, 'وَإِن كَانَ طَآئِفَةٌۭ مِّنكُمْ ءَامَنُوا۟ بِٱلَّذِىٓ أُرْسِلْتُ بِهِۦ وَطَآئِفَةٌۭ لَّمْ يُؤْمِنُوا۟ فَٱصْبِرُوا۟ حَتَّىٰ يَحْكُمَ ٱللَّهُ بَيْنَنَا ۚ وَهُوَ خَيْرُ ٱلْحَٰكِمِينَ', 'وإن كان طائفة منكم ءامنوا بالذى أرسلت به وطائفة لم يؤمنوا فاصبروا حتى يحكم الله بيننا  وهو خير الحكمين', NULL, 161, 'local:hafs-text.json'),
  ('hafs-7-88', 'hafs', 7, 88, '۞ قَالَ ٱلْمَلَأُ ٱلَّذِينَ ٱسْتَكْبَرُوا۟ مِن قَوْمِهِۦ لَنُخْرِجَنَّكَ يَٰشُعَيْبُ وَٱلَّذِينَ ءَامَنُوا۟ مَعَكَ مِن قَرْيَتِنَآ أَوْ لَتَعُودُنَّ فِى مِلَّتِنَا ۚ قَالَ أَوَلَوْ كُنَّا كَٰرِهِينَ', 'قال الملأ الذين استكبروا من قومه لنخرجنك يشعيب والذين ءامنوا معك من قريتنا أو لتعودن فى ملتنا  قال أولو كنا كرهين', NULL, 162, 'local:hafs-text.json'),
  ('hafs-7-89', 'hafs', 7, 89, 'قَدِ ٱفْتَرَيْنَا عَلَى ٱللَّهِ كَذِبًا إِنْ عُدْنَا فِى مِلَّتِكُم بَعْدَ إِذْ نَجَّىٰنَا ٱللَّهُ مِنْهَا ۚ وَمَا يَكُونُ لَنَآ أَن نَّعُودَ فِيهَآ إِلَّآ أَن يَشَآءَ ٱللَّهُ رَبُّنَا ۚ وَسِعَ رَبُّنَا كُلَّ شَىْءٍ عِلْمًا ۚ عَلَى ٱللَّهِ تَوَكَّلْنَا ۚ رَبَّنَا ٱفْتَحْ بَيْنَنَا وَبَيْنَ قَوْمِنَا بِٱلْحَقِّ وَأَنتَ خَيْرُ ٱلْفَٰتِحِينَ', 'قد افترينا على الله كذبا إن عدنا فى ملتكم بعد إذ نجىنا الله منها  وما يكون لنا أن نعود فيها إلا أن يشاء الله ربنا  وسع ربنا كل شىء علما  على الله توكلنا  ربنا افتح بيننا وبين قومنا بالحق وأنت خير الفتحين', NULL, 162, 'local:hafs-text.json'),
  ('hafs-7-90', 'hafs', 7, 90, 'وَقَالَ ٱلْمَلَأُ ٱلَّذِينَ كَفَرُوا۟ مِن قَوْمِهِۦ لَئِنِ ٱتَّبَعْتُمْ شُعَيْبًا إِنَّكُمْ إِذًۭا لَّخَٰسِرُونَ', 'وقال الملأ الذين كفروا من قومه لئن اتبعتم شعيبا إنكم إذا لخسرون', NULL, 162, 'local:hafs-text.json'),
  ('hafs-7-91', 'hafs', 7, 91, 'فَأَخَذَتْهُمُ ٱلرَّجْفَةُ فَأَصْبَحُوا۟ فِى دَارِهِمْ جَٰثِمِينَ', 'فأخذتهم الرجفة فأصبحوا فى دارهم جثمين', NULL, 162, 'local:hafs-text.json'),
  ('hafs-7-92', 'hafs', 7, 92, 'ٱلَّذِينَ كَذَّبُوا۟ شُعَيْبًۭا كَأَن لَّمْ يَغْنَوْا۟ فِيهَا ۚ ٱلَّذِينَ كَذَّبُوا۟ شُعَيْبًۭا كَانُوا۟ هُمُ ٱلْخَٰسِرِينَ', 'الذين كذبوا شعيبا كأن لم يغنوا فيها  الذين كذبوا شعيبا كانوا هم الخسرين', NULL, 162, 'local:hafs-text.json'),
  ('hafs-7-93', 'hafs', 7, 93, 'فَتَوَلَّىٰ عَنْهُمْ وَقَالَ يَٰقَوْمِ لَقَدْ أَبْلَغْتُكُمْ رِسَٰلَٰتِ رَبِّى وَنَصَحْتُ لَكُمْ ۖ فَكَيْفَ ءَاسَىٰ عَلَىٰ قَوْمٍۢ كَٰفِرِينَ', 'فتولى عنهم وقال يقوم لقد أبلغتكم رسلت ربى ونصحت لكم  فكيف ءاسى على قوم كفرين', NULL, 162, 'local:hafs-text.json'),
  ('hafs-7-94', 'hafs', 7, 94, 'وَمَآ أَرْسَلْنَا فِى قَرْيَةٍۢ مِّن نَّبِىٍّ إِلَّآ أَخَذْنَآ أَهْلَهَا بِٱلْبَأْسَآءِ وَٱلضَّرَّآءِ لَعَلَّهُمْ يَضَّرَّعُونَ', 'وما أرسلنا فى قرية من نبى إلا أخذنا أهلها بالبأساء والضراء لعلهم يضرعون', NULL, 162, 'local:hafs-text.json'),
  ('hafs-7-95', 'hafs', 7, 95, 'ثُمَّ بَدَّلْنَا مَكَانَ ٱلسَّيِّئَةِ ٱلْحَسَنَةَ حَتَّىٰ عَفَوا۟ وَّقَالُوا۟ قَدْ مَسَّ ءَابَآءَنَا ٱلضَّرَّآءُ وَٱلسَّرَّآءُ فَأَخَذْنَٰهُم بَغْتَةًۭ وَهُمْ لَا يَشْعُرُونَ', 'ثم بدلنا مكان السيئة الحسنة حتى عفوا وقالوا قد مس ءاباءنا الضراء والسراء فأخذنهم بغتة وهم لا يشعرون', NULL, 162, 'local:hafs-text.json'),
  ('hafs-7-96', 'hafs', 7, 96, 'وَلَوْ أَنَّ أَهْلَ ٱلْقُرَىٰٓ ءَامَنُوا۟ وَٱتَّقَوْا۟ لَفَتَحْنَا عَلَيْهِم بَرَكَٰتٍۢ مِّنَ ٱلسَّمَآءِ وَٱلْأَرْضِ وَلَٰكِن كَذَّبُوا۟ فَأَخَذْنَٰهُم بِمَا كَانُوا۟ يَكْسِبُونَ', 'ولو أن أهل القرى ءامنوا واتقوا لفتحنا عليهم بركت من السماء والأرض ولكن كذبوا فأخذنهم بما كانوا يكسبون', NULL, 163, 'local:hafs-text.json'),
  ('hafs-7-97', 'hafs', 7, 97, 'أَفَأَمِنَ أَهْلُ ٱلْقُرَىٰٓ أَن يَأْتِيَهُم بَأْسُنَا بَيَٰتًۭا وَهُمْ نَآئِمُونَ', 'أفأمن أهل القرى أن يأتيهم بأسنا بيتا وهم نائمون', NULL, 163, 'local:hafs-text.json'),
  ('hafs-7-98', 'hafs', 7, 98, 'أَوَأَمِنَ أَهْلُ ٱلْقُرَىٰٓ أَن يَأْتِيَهُم بَأْسُنَا ضُحًۭى وَهُمْ يَلْعَبُونَ', 'أوأمن أهل القرى أن يأتيهم بأسنا ضحى وهم يلعبون', NULL, 163, 'local:hafs-text.json'),
  ('hafs-7-99', 'hafs', 7, 99, 'أَفَأَمِنُوا۟ مَكْرَ ٱللَّهِ ۚ فَلَا يَأْمَنُ مَكْرَ ٱللَّهِ إِلَّا ٱلْقَوْمُ ٱلْخَٰسِرُونَ', 'أفأمنوا مكر الله  فلا يأمن مكر الله إلا القوم الخسرون', NULL, 163, 'local:hafs-text.json'),
  ('hafs-7-100', 'hafs', 7, 100, 'أَوَلَمْ يَهْدِ لِلَّذِينَ يَرِثُونَ ٱلْأَرْضَ مِنۢ بَعْدِ أَهْلِهَآ أَن لَّوْ نَشَآءُ أَصَبْنَٰهُم بِذُنُوبِهِمْ ۚ وَنَطْبَعُ عَلَىٰ قُلُوبِهِمْ فَهُمْ لَا يَسْمَعُونَ', 'أولم يهد للذين يرثون الأرض من بعد أهلها أن لو نشاء أصبنهم بذنوبهم  ونطبع على قلوبهم فهم لا يسمعون', NULL, 163, 'local:hafs-text.json'),
  ('hafs-7-101', 'hafs', 7, 101, 'تِلْكَ ٱلْقُرَىٰ نَقُصُّ عَلَيْكَ مِنْ أَنۢبَآئِهَا ۚ وَلَقَدْ جَآءَتْهُمْ رُسُلُهُم بِٱلْبَيِّنَٰتِ فَمَا كَانُوا۟ لِيُؤْمِنُوا۟ بِمَا كَذَّبُوا۟ مِن قَبْلُ ۚ كَذَٰلِكَ يَطْبَعُ ٱللَّهُ عَلَىٰ قُلُوبِ ٱلْكَٰفِرِينَ', 'تلك القرى نقص عليك من أنبائها  ولقد جاءتهم رسلهم بالبينت فما كانوا ليؤمنوا بما كذبوا من قبل  كذلك يطبع الله على قلوب الكفرين', NULL, 163, 'local:hafs-text.json'),
  ('hafs-7-102', 'hafs', 7, 102, 'وَمَا وَجَدْنَا لِأَكْثَرِهِم مِّنْ عَهْدٍۢ ۖ وَإِن وَجَدْنَآ أَكْثَرَهُمْ لَفَٰسِقِينَ', 'وما وجدنا لأكثرهم من عهد  وإن وجدنا أكثرهم لفسقين', NULL, 163, 'local:hafs-text.json'),
  ('hafs-7-103', 'hafs', 7, 103, 'ثُمَّ بَعَثْنَا مِنۢ بَعْدِهِم مُّوسَىٰ بِـَٔايَٰتِنَآ إِلَىٰ فِرْعَوْنَ وَمَلَإِي۟هِۦ فَظَلَمُوا۟ بِهَا ۖ فَٱنظُرْ كَيْفَ كَانَ عَٰقِبَةُ ٱلْمُفْسِدِينَ', 'ثم بعثنا من بعدهم موسى بايتنا إلى فرعون وملإيه فظلموا بها  فانظر كيف كان عقبة المفسدين', NULL, 163, 'local:hafs-text.json'),
  ('hafs-7-104', 'hafs', 7, 104, 'وَقَالَ مُوسَىٰ يَٰفِرْعَوْنُ إِنِّى رَسُولٌۭ مِّن رَّبِّ ٱلْعَٰلَمِينَ', 'وقال موسى يفرعون إنى رسول من رب العلمين', NULL, 163, 'local:hafs-text.json'),
  ('hafs-7-105', 'hafs', 7, 105, 'حَقِيقٌ عَلَىٰٓ أَن لَّآ أَقُولَ عَلَى ٱللَّهِ إِلَّا ٱلْحَقَّ ۚ قَدْ جِئْتُكُم بِبَيِّنَةٍۢ مِّن رَّبِّكُمْ فَأَرْسِلْ مَعِىَ بَنِىٓ إِسْرَٰٓءِيلَ', 'حقيق على أن لا أقول على الله إلا الحق  قد جئتكم ببينة من ربكم فأرسل معى بنى إسرءيل', NULL, 164, 'local:hafs-text.json'),
  ('hafs-7-106', 'hafs', 7, 106, 'قَالَ إِن كُنتَ جِئْتَ بِـَٔايَةٍۢ فَأْتِ بِهَآ إِن كُنتَ مِنَ ٱلصَّٰدِقِينَ', 'قال إن كنت جئت باية فأت بها إن كنت من الصدقين', NULL, 164, 'local:hafs-text.json'),
  ('hafs-7-107', 'hafs', 7, 107, 'فَأَلْقَىٰ عَصَاهُ فَإِذَا هِىَ ثُعْبَانٌۭ مُّبِينٌۭ', 'فألقى عصاه فإذا هى ثعبان مبين', NULL, 164, 'local:hafs-text.json'),
  ('hafs-7-108', 'hafs', 7, 108, 'وَنَزَعَ يَدَهُۥ فَإِذَا هِىَ بَيْضَآءُ لِلنَّٰظِرِينَ', 'ونزع يده فإذا هى بيضاء للنظرين', NULL, 164, 'local:hafs-text.json'),
  ('hafs-7-109', 'hafs', 7, 109, 'قَالَ ٱلْمَلَأُ مِن قَوْمِ فِرْعَوْنَ إِنَّ هَٰذَا لَسَٰحِرٌ عَلِيمٌۭ', 'قال الملأ من قوم فرعون إن هذا لسحر عليم', NULL, 164, 'local:hafs-text.json'),
  ('hafs-7-110', 'hafs', 7, 110, 'يُرِيدُ أَن يُخْرِجَكُم مِّنْ أَرْضِكُمْ ۖ فَمَاذَا تَأْمُرُونَ', 'يريد أن يخرجكم من أرضكم  فماذا تأمرون', NULL, 164, 'local:hafs-text.json'),
  ('hafs-7-111', 'hafs', 7, 111, 'قَالُوٓا۟ أَرْجِهْ وَأَخَاهُ وَأَرْسِلْ فِى ٱلْمَدَآئِنِ حَٰشِرِينَ', 'قالوا أرجه وأخاه وأرسل فى المدائن حشرين', NULL, 164, 'local:hafs-text.json'),
  ('hafs-7-112', 'hafs', 7, 112, 'يَأْتُوكَ بِكُلِّ سَٰحِرٍ عَلِيمٍۢ', 'يأتوك بكل سحر عليم', NULL, 164, 'local:hafs-text.json'),
  ('hafs-7-113', 'hafs', 7, 113, 'وَجَآءَ ٱلسَّحَرَةُ فِرْعَوْنَ قَالُوٓا۟ إِنَّ لَنَا لَأَجْرًا إِن كُنَّا نَحْنُ ٱلْغَٰلِبِينَ', 'وجاء السحرة فرعون قالوا إن لنا لأجرا إن كنا نحن الغلبين', NULL, 164, 'local:hafs-text.json'),
  ('hafs-7-114', 'hafs', 7, 114, 'قَالَ نَعَمْ وَإِنَّكُمْ لَمِنَ ٱلْمُقَرَّبِينَ', 'قال نعم وإنكم لمن المقربين', NULL, 164, 'local:hafs-text.json'),
  ('hafs-7-115', 'hafs', 7, 115, 'قَالُوا۟ يَٰمُوسَىٰٓ إِمَّآ أَن تُلْقِىَ وَإِمَّآ أَن نَّكُونَ نَحْنُ ٱلْمُلْقِينَ', 'قالوا يموسى إما أن تلقى وإما أن نكون نحن الملقين', NULL, 164, 'local:hafs-text.json'),
  ('hafs-7-116', 'hafs', 7, 116, 'قَالَ أَلْقُوا۟ ۖ فَلَمَّآ أَلْقَوْا۟ سَحَرُوٓا۟ أَعْيُنَ ٱلنَّاسِ وَٱسْتَرْهَبُوهُمْ وَجَآءُو بِسِحْرٍ عَظِيمٍۢ', 'قال ألقوا  فلما ألقوا سحروا أعين الناس واسترهبوهم وجاءو بسحر عظيم', NULL, 164, 'local:hafs-text.json'),
  ('hafs-7-117', 'hafs', 7, 117, '۞ وَأَوْحَيْنَآ إِلَىٰ مُوسَىٰٓ أَنْ أَلْقِ عَصَاكَ ۖ فَإِذَا هِىَ تَلْقَفُ مَا يَأْفِكُونَ', 'وأوحينا إلى موسى أن ألق عصاك  فإذا هى تلقف ما يأفكون', NULL, 164, 'local:hafs-text.json'),
  ('hafs-7-118', 'hafs', 7, 118, 'فَوَقَعَ ٱلْحَقُّ وَبَطَلَ مَا كَانُوا۟ يَعْمَلُونَ', 'فوقع الحق وبطل ما كانوا يعملون', NULL, 164, 'local:hafs-text.json'),
  ('hafs-7-119', 'hafs', 7, 119, 'فَغُلِبُوا۟ هُنَالِكَ وَٱنقَلَبُوا۟ صَٰغِرِينَ', 'فغلبوا هنالك وانقلبوا صغرين', NULL, 164, 'local:hafs-text.json'),
  ('hafs-7-120', 'hafs', 7, 120, 'وَأُلْقِىَ ٱلسَّحَرَةُ سَٰجِدِينَ', 'وألقى السحرة سجدين', NULL, 164, 'local:hafs-text.json'),
  ('hafs-7-121', 'hafs', 7, 121, 'قَالُوٓا۟ ءَامَنَّا بِرَبِّ ٱلْعَٰلَمِينَ', 'قالوا ءامنا برب العلمين', NULL, 165, 'local:hafs-text.json'),
  ('hafs-7-122', 'hafs', 7, 122, 'رَبِّ مُوسَىٰ وَهَٰرُونَ', 'رب موسى وهرون', NULL, 165, 'local:hafs-text.json'),
  ('hafs-7-123', 'hafs', 7, 123, 'قَالَ فِرْعَوْنُ ءَامَنتُم بِهِۦ قَبْلَ أَنْ ءَاذَنَ لَكُمْ ۖ إِنَّ هَٰذَا لَمَكْرٌۭ مَّكَرْتُمُوهُ فِى ٱلْمَدِينَةِ لِتُخْرِجُوا۟ مِنْهَآ أَهْلَهَا ۖ فَسَوْفَ تَعْلَمُونَ', 'قال فرعون ءامنتم به قبل أن ءاذن لكم  إن هذا لمكر مكرتموه فى المدينة لتخرجوا منها أهلها  فسوف تعلمون', NULL, 165, 'local:hafs-text.json'),
  ('hafs-7-124', 'hafs', 7, 124, 'لَأُقَطِّعَنَّ أَيْدِيَكُمْ وَأَرْجُلَكُم مِّنْ خِلَٰفٍۢ ثُمَّ لَأُصَلِّبَنَّكُمْ أَجْمَعِينَ', 'لأقطعن أيديكم وأرجلكم من خلف ثم لأصلبنكم أجمعين', NULL, 165, 'local:hafs-text.json'),
  ('hafs-7-125', 'hafs', 7, 125, 'قَالُوٓا۟ إِنَّآ إِلَىٰ رَبِّنَا مُنقَلِبُونَ', 'قالوا إنا إلى ربنا منقلبون', NULL, 165, 'local:hafs-text.json'),
  ('hafs-7-126', 'hafs', 7, 126, 'وَمَا تَنقِمُ مِنَّآ إِلَّآ أَنْ ءَامَنَّا بِـَٔايَٰتِ رَبِّنَا لَمَّا جَآءَتْنَا ۚ رَبَّنَآ أَفْرِغْ عَلَيْنَا صَبْرًۭا وَتَوَفَّنَا مُسْلِمِينَ', 'وما تنقم منا إلا أن ءامنا بايت ربنا لما جاءتنا  ربنا أفرغ علينا صبرا وتوفنا مسلمين', NULL, 165, 'local:hafs-text.json'),
  ('hafs-7-127', 'hafs', 7, 127, 'وَقَالَ ٱلْمَلَأُ مِن قَوْمِ فِرْعَوْنَ أَتَذَرُ مُوسَىٰ وَقَوْمَهُۥ لِيُفْسِدُوا۟ فِى ٱلْأَرْضِ وَيَذَرَكَ وَءَالِهَتَكَ ۚ قَالَ سَنُقَتِّلُ أَبْنَآءَهُمْ وَنَسْتَحْىِۦ نِسَآءَهُمْ وَإِنَّا فَوْقَهُمْ قَٰهِرُونَ', 'وقال الملأ من قوم فرعون أتذر موسى وقومه ليفسدوا فى الأرض ويذرك وءالهتك  قال سنقتل أبناءهم ونستحى نساءهم وإنا فوقهم قهرون', NULL, 165, 'local:hafs-text.json'),
  ('hafs-7-128', 'hafs', 7, 128, 'قَالَ مُوسَىٰ لِقَوْمِهِ ٱسْتَعِينُوا۟ بِٱللَّهِ وَٱصْبِرُوٓا۟ ۖ إِنَّ ٱلْأَرْضَ لِلَّهِ يُورِثُهَا مَن يَشَآءُ مِنْ عِبَادِهِۦ ۖ وَٱلْعَٰقِبَةُ لِلْمُتَّقِينَ', 'قال موسى لقومه استعينوا بالله واصبروا  إن الأرض لله يورثها من يشاء من عباده  والعقبة للمتقين', NULL, 165, 'local:hafs-text.json'),
  ('hafs-7-129', 'hafs', 7, 129, 'قَالُوٓا۟ أُوذِينَا مِن قَبْلِ أَن تَأْتِيَنَا وَمِنۢ بَعْدِ مَا جِئْتَنَا ۚ قَالَ عَسَىٰ رَبُّكُمْ أَن يُهْلِكَ عَدُوَّكُمْ وَيَسْتَخْلِفَكُمْ فِى ٱلْأَرْضِ فَيَنظُرَ كَيْفَ تَعْمَلُونَ', 'قالوا أوذينا من قبل أن تأتينا ومن بعد ما جئتنا  قال عسى ربكم أن يهلك عدوكم ويستخلفكم فى الأرض فينظر كيف تعملون', NULL, 165, 'local:hafs-text.json'),
  ('hafs-7-130', 'hafs', 7, 130, 'وَلَقَدْ أَخَذْنَآ ءَالَ فِرْعَوْنَ بِٱلسِّنِينَ وَنَقْصٍۢ مِّنَ ٱلثَّمَرَٰتِ لَعَلَّهُمْ يَذَّكَّرُونَ', 'ولقد أخذنا ءال فرعون بالسنين ونقص من الثمرت لعلهم يذكرون', NULL, 165, 'local:hafs-text.json'),
  ('hafs-7-131', 'hafs', 7, 131, 'فَإِذَا جَآءَتْهُمُ ٱلْحَسَنَةُ قَالُوا۟ لَنَا هَٰذِهِۦ ۖ وَإِن تُصِبْهُمْ سَيِّئَةٌۭ يَطَّيَّرُوا۟ بِمُوسَىٰ وَمَن مَّعَهُۥٓ ۗ أَلَآ إِنَّمَا طَٰٓئِرُهُمْ عِندَ ٱللَّهِ وَلَٰكِنَّ أَكْثَرَهُمْ لَا يَعْلَمُونَ', 'فإذا جاءتهم الحسنة قالوا لنا هذه  وإن تصبهم سيئة يطيروا بموسى ومن معه  ألا إنما طئرهم عند الله ولكن أكثرهم لا يعلمون', NULL, 166, 'local:hafs-text.json'),
  ('hafs-7-132', 'hafs', 7, 132, 'وَقَالُوا۟ مَهْمَا تَأْتِنَا بِهِۦ مِنْ ءَايَةٍۢ لِّتَسْحَرَنَا بِهَا فَمَا نَحْنُ لَكَ بِمُؤْمِنِينَ', 'وقالوا مهما تأتنا به من ءاية لتسحرنا بها فما نحن لك بمؤمنين', NULL, 166, 'local:hafs-text.json'),
  ('hafs-7-133', 'hafs', 7, 133, 'فَأَرْسَلْنَا عَلَيْهِمُ ٱلطُّوفَانَ وَٱلْجَرَادَ وَٱلْقُمَّلَ وَٱلضَّفَادِعَ وَٱلدَّمَ ءَايَٰتٍۢ مُّفَصَّلَٰتٍۢ فَٱسْتَكْبَرُوا۟ وَكَانُوا۟ قَوْمًۭا مُّجْرِمِينَ', 'فأرسلنا عليهم الطوفان والجراد والقمل والضفادع والدم ءايت مفصلت فاستكبروا وكانوا قوما مجرمين', NULL, 166, 'local:hafs-text.json'),
  ('hafs-7-134', 'hafs', 7, 134, 'وَلَمَّا وَقَعَ عَلَيْهِمُ ٱلرِّجْزُ قَالُوا۟ يَٰمُوسَى ٱدْعُ لَنَا رَبَّكَ بِمَا عَهِدَ عِندَكَ ۖ لَئِن كَشَفْتَ عَنَّا ٱلرِّجْزَ لَنُؤْمِنَنَّ لَكَ وَلَنُرْسِلَنَّ مَعَكَ بَنِىٓ إِسْرَٰٓءِيلَ', 'ولما وقع عليهم الرجز قالوا يموسى ادع لنا ربك بما عهد عندك  لئن كشفت عنا الرجز لنؤمنن لك ولنرسلن معك بنى إسرءيل', NULL, 166, 'local:hafs-text.json'),
  ('hafs-7-135', 'hafs', 7, 135, 'فَلَمَّا كَشَفْنَا عَنْهُمُ ٱلرِّجْزَ إِلَىٰٓ أَجَلٍ هُم بَٰلِغُوهُ إِذَا هُمْ يَنكُثُونَ', 'فلما كشفنا عنهم الرجز إلى أجل هم بلغوه إذا هم ينكثون', NULL, 166, 'local:hafs-text.json'),
  ('hafs-7-136', 'hafs', 7, 136, 'فَٱنتَقَمْنَا مِنْهُمْ فَأَغْرَقْنَٰهُمْ فِى ٱلْيَمِّ بِأَنَّهُمْ كَذَّبُوا۟ بِـَٔايَٰتِنَا وَكَانُوا۟ عَنْهَا غَٰفِلِينَ', 'فانتقمنا منهم فأغرقنهم فى اليم بأنهم كذبوا بايتنا وكانوا عنها غفلين', NULL, 166, 'local:hafs-text.json'),
  ('hafs-7-137', 'hafs', 7, 137, 'وَأَوْرَثْنَا ٱلْقَوْمَ ٱلَّذِينَ كَانُوا۟ يُسْتَضْعَفُونَ مَشَٰرِقَ ٱلْأَرْضِ وَمَغَٰرِبَهَا ٱلَّتِى بَٰرَكْنَا فِيهَا ۖ وَتَمَّتْ كَلِمَتُ رَبِّكَ ٱلْحُسْنَىٰ عَلَىٰ بَنِىٓ إِسْرَٰٓءِيلَ بِمَا صَبَرُوا۟ ۖ وَدَمَّرْنَا مَا كَانَ يَصْنَعُ فِرْعَوْنُ وَقَوْمُهُۥ وَمَا كَانُوا۟ يَعْرِشُونَ', 'وأورثنا القوم الذين كانوا يستضعفون مشرق الأرض ومغربها التى بركنا فيها  وتمت كلمت ربك الحسنى على بنى إسرءيل بما صبروا  ودمرنا ما كان يصنع فرعون وقومه وما كانوا يعرشون', NULL, 166, 'local:hafs-text.json'),
  ('hafs-7-138', 'hafs', 7, 138, 'وَجَٰوَزْنَا بِبَنِىٓ إِسْرَٰٓءِيلَ ٱلْبَحْرَ فَأَتَوْا۟ عَلَىٰ قَوْمٍۢ يَعْكُفُونَ عَلَىٰٓ أَصْنَامٍۢ لَّهُمْ ۚ قَالُوا۟ يَٰمُوسَى ٱجْعَل لَّنَآ إِلَٰهًۭا كَمَا لَهُمْ ءَالِهَةٌۭ ۚ قَالَ إِنَّكُمْ قَوْمٌۭ تَجْهَلُونَ', 'وجوزنا ببنى إسرءيل البحر فأتوا على قوم يعكفون على أصنام لهم  قالوا يموسى اجعل لنا إلها كما لهم ءالهة  قال إنكم قوم تجهلون', NULL, 167, 'local:hafs-text.json'),
  ('hafs-7-139', 'hafs', 7, 139, 'إِنَّ هَٰٓؤُلَآءِ مُتَبَّرٌۭ مَّا هُمْ فِيهِ وَبَٰطِلٌۭ مَّا كَانُوا۟ يَعْمَلُونَ', 'إن هؤلاء متبر ما هم فيه وبطل ما كانوا يعملون', NULL, 167, 'local:hafs-text.json'),
  ('hafs-7-140', 'hafs', 7, 140, 'قَالَ أَغَيْرَ ٱللَّهِ أَبْغِيكُمْ إِلَٰهًۭا وَهُوَ فَضَّلَكُمْ عَلَى ٱلْعَٰلَمِينَ', 'قال أغير الله أبغيكم إلها وهو فضلكم على العلمين', NULL, 167, 'local:hafs-text.json'),
  ('hafs-7-141', 'hafs', 7, 141, 'وَإِذْ أَنجَيْنَٰكُم مِّنْ ءَالِ فِرْعَوْنَ يَسُومُونَكُمْ سُوٓءَ ٱلْعَذَابِ ۖ يُقَتِّلُونَ أَبْنَآءَكُمْ وَيَسْتَحْيُونَ نِسَآءَكُمْ ۚ وَفِى ذَٰلِكُم بَلَآءٌۭ مِّن رَّبِّكُمْ عَظِيمٌۭ', 'وإذ أنجينكم من ءال فرعون يسومونكم سوء العذاب  يقتلون أبناءكم ويستحيون نساءكم  وفى ذلكم بلاء من ربكم عظيم', NULL, 167, 'local:hafs-text.json'),
  ('hafs-7-142', 'hafs', 7, 142, '۞ وَوَٰعَدْنَا مُوسَىٰ ثَلَٰثِينَ لَيْلَةًۭ وَأَتْمَمْنَٰهَا بِعَشْرٍۢ فَتَمَّ مِيقَٰتُ رَبِّهِۦٓ أَرْبَعِينَ لَيْلَةًۭ ۚ وَقَالَ مُوسَىٰ لِأَخِيهِ هَٰرُونَ ٱخْلُفْنِى فِى قَوْمِى وَأَصْلِحْ وَلَا تَتَّبِعْ سَبِيلَ ٱلْمُفْسِدِينَ', 'ووعدنا موسى ثلثين ليلة وأتممنها بعشر فتم ميقت ربه أربعين ليلة  وقال موسى لأخيه هرون اخلفنى فى قومى وأصلح ولا تتبع سبيل المفسدين', NULL, 167, 'local:hafs-text.json'),
  ('hafs-7-143', 'hafs', 7, 143, 'وَلَمَّا جَآءَ مُوسَىٰ لِمِيقَٰتِنَا وَكَلَّمَهُۥ رَبُّهُۥ قَالَ رَبِّ أَرِنِىٓ أَنظُرْ إِلَيْكَ ۚ قَالَ لَن تَرَىٰنِى وَلَٰكِنِ ٱنظُرْ إِلَى ٱلْجَبَلِ فَإِنِ ٱسْتَقَرَّ مَكَانَهُۥ فَسَوْفَ تَرَىٰنِى ۚ فَلَمَّا تَجَلَّىٰ رَبُّهُۥ لِلْجَبَلِ جَعَلَهُۥ دَكًّۭا وَخَرَّ مُوسَىٰ صَعِقًۭا ۚ فَلَمَّآ أَفَاقَ قَالَ سُبْحَٰنَكَ تُبْتُ إِلَيْكَ وَأَنَا۠ أَوَّلُ ٱلْمُؤْمِنِينَ', 'ولما جاء موسى لميقتنا وكلمه ربه قال رب أرنى أنظر إليك  قال لن ترىنى ولكن انظر إلى الجبل فإن استقر مكانه فسوف ترىنى  فلما تجلى ربه للجبل جعله دكا وخر موسى صعقا  فلما أفاق قال سبحنك تبت إليك وأنا أول المؤمنين', NULL, 167, 'local:hafs-text.json'),
  ('hafs-7-144', 'hafs', 7, 144, 'قَالَ يَٰمُوسَىٰٓ إِنِّى ٱصْطَفَيْتُكَ عَلَى ٱلنَّاسِ بِرِسَٰلَٰتِى وَبِكَلَٰمِى فَخُذْ مَآ ءَاتَيْتُكَ وَكُن مِّنَ ٱلشَّٰكِرِينَ', 'قال يموسى إنى اصطفيتك على الناس برسلتى وبكلمى فخذ ما ءاتيتك وكن من الشكرين', NULL, 168, 'local:hafs-text.json'),
  ('hafs-7-145', 'hafs', 7, 145, 'وَكَتَبْنَا لَهُۥ فِى ٱلْأَلْوَاحِ مِن كُلِّ شَىْءٍۢ مَّوْعِظَةًۭ وَتَفْصِيلًۭا لِّكُلِّ شَىْءٍۢ فَخُذْهَا بِقُوَّةٍۢ وَأْمُرْ قَوْمَكَ يَأْخُذُوا۟ بِأَحْسَنِهَا ۚ سَأُو۟رِيكُمْ دَارَ ٱلْفَٰسِقِينَ', 'وكتبنا له فى الألواح من كل شىء موعظة وتفصيلا لكل شىء فخذها بقوة وأمر قومك يأخذوا بأحسنها  سأوريكم دار الفسقين', NULL, 168, 'local:hafs-text.json'),
  ('hafs-7-146', 'hafs', 7, 146, 'سَأَصْرِفُ عَنْ ءَايَٰتِىَ ٱلَّذِينَ يَتَكَبَّرُونَ فِى ٱلْأَرْضِ بِغَيْرِ ٱلْحَقِّ وَإِن يَرَوْا۟ كُلَّ ءَايَةٍۢ لَّا يُؤْمِنُوا۟ بِهَا وَإِن يَرَوْا۟ سَبِيلَ ٱلرُّشْدِ لَا يَتَّخِذُوهُ سَبِيلًۭا وَإِن يَرَوْا۟ سَبِيلَ ٱلْغَىِّ يَتَّخِذُوهُ سَبِيلًۭا ۚ ذَٰلِكَ بِأَنَّهُمْ كَذَّبُوا۟ بِـَٔايَٰتِنَا وَكَانُوا۟ عَنْهَا غَٰفِلِينَ', 'سأصرف عن ءايتى الذين يتكبرون فى الأرض بغير الحق وإن يروا كل ءاية لا يؤمنوا بها وإن يروا سبيل الرشد لا يتخذوه سبيلا وإن يروا سبيل الغى يتخذوه سبيلا  ذلك بأنهم كذبوا بايتنا وكانوا عنها غفلين', NULL, 168, 'local:hafs-text.json'),
  ('hafs-7-147', 'hafs', 7, 147, 'وَٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَٰتِنَا وَلِقَآءِ ٱلْءَاخِرَةِ حَبِطَتْ أَعْمَٰلُهُمْ ۚ هَلْ يُجْزَوْنَ إِلَّا مَا كَانُوا۟ يَعْمَلُونَ', 'والذين كذبوا بايتنا ولقاء الءاخرة حبطت أعملهم  هل يجزون إلا ما كانوا يعملون', NULL, 168, 'local:hafs-text.json'),
  ('hafs-7-148', 'hafs', 7, 148, 'وَٱتَّخَذَ قَوْمُ مُوسَىٰ مِنۢ بَعْدِهِۦ مِنْ حُلِيِّهِمْ عِجْلًۭا جَسَدًۭا لَّهُۥ خُوَارٌ ۚ أَلَمْ يَرَوْا۟ أَنَّهُۥ لَا يُكَلِّمُهُمْ وَلَا يَهْدِيهِمْ سَبِيلًا ۘ ٱتَّخَذُوهُ وَكَانُوا۟ ظَٰلِمِينَ', 'واتخذ قوم موسى من بعده من حليهم عجلا جسدا له خوار  ألم يروا أنه لا يكلمهم ولا يهديهم سبيلا  اتخذوه وكانوا ظلمين', NULL, 168, 'local:hafs-text.json'),
  ('hafs-7-149', 'hafs', 7, 149, 'وَلَمَّا سُقِطَ فِىٓ أَيْدِيهِمْ وَرَأَوْا۟ أَنَّهُمْ قَدْ ضَلُّوا۟ قَالُوا۟ لَئِن لَّمْ يَرْحَمْنَا رَبُّنَا وَيَغْفِرْ لَنَا لَنَكُونَنَّ مِنَ ٱلْخَٰسِرِينَ', 'ولما سقط فى أيديهم ورأوا أنهم قد ضلوا قالوا لئن لم يرحمنا ربنا ويغفر لنا لنكونن من الخسرين', NULL, 168, 'local:hafs-text.json'),
  ('hafs-7-150', 'hafs', 7, 150, 'وَلَمَّا رَجَعَ مُوسَىٰٓ إِلَىٰ قَوْمِهِۦ غَضْبَٰنَ أَسِفًۭا قَالَ بِئْسَمَا خَلَفْتُمُونِى مِنۢ بَعْدِىٓ ۖ أَعَجِلْتُمْ أَمْرَ رَبِّكُمْ ۖ وَأَلْقَى ٱلْأَلْوَاحَ وَأَخَذَ بِرَأْسِ أَخِيهِ يَجُرُّهُۥٓ إِلَيْهِ ۚ قَالَ ٱبْنَ أُمَّ إِنَّ ٱلْقَوْمَ ٱسْتَضْعَفُونِى وَكَادُوا۟ يَقْتُلُونَنِى فَلَا تُشْمِتْ بِىَ ٱلْأَعْدَآءَ وَلَا تَجْعَلْنِى مَعَ ٱلْقَوْمِ ٱلظَّٰلِمِينَ', 'ولما رجع موسى إلى قومه غضبن أسفا قال بئسما خلفتمونى من بعدى  أعجلتم أمر ربكم  وألقى الألواح وأخذ برأس أخيه يجره إليه  قال ابن أم إن القوم استضعفونى وكادوا يقتلوننى فلا تشمت بى الأعداء ولا تجعلنى مع القوم الظلمين', NULL, 169, 'local:hafs-text.json'),
  ('hafs-7-151', 'hafs', 7, 151, 'قَالَ رَبِّ ٱغْفِرْ لِى وَلِأَخِى وَأَدْخِلْنَا فِى رَحْمَتِكَ ۖ وَأَنتَ أَرْحَمُ ٱلرَّٰحِمِينَ', 'قال رب اغفر لى ولأخى وأدخلنا فى رحمتك  وأنت أرحم الرحمين', NULL, 169, 'local:hafs-text.json'),
  ('hafs-7-152', 'hafs', 7, 152, 'إِنَّ ٱلَّذِينَ ٱتَّخَذُوا۟ ٱلْعِجْلَ سَيَنَالُهُمْ غَضَبٌۭ مِّن رَّبِّهِمْ وَذِلَّةٌۭ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا ۚ وَكَذَٰلِكَ نَجْزِى ٱلْمُفْتَرِينَ', 'إن الذين اتخذوا العجل سينالهم غضب من ربهم وذلة فى الحيوة الدنيا  وكذلك نجزى المفترين', NULL, 169, 'local:hafs-text.json'),
  ('hafs-7-153', 'hafs', 7, 153, 'وَٱلَّذِينَ عَمِلُوا۟ ٱلسَّيِّـَٔاتِ ثُمَّ تَابُوا۟ مِنۢ بَعْدِهَا وَءَامَنُوٓا۟ إِنَّ رَبَّكَ مِنۢ بَعْدِهَا لَغَفُورٌۭ رَّحِيمٌۭ', 'والذين عملوا السيات ثم تابوا من بعدها وءامنوا إن ربك من بعدها لغفور رحيم', NULL, 169, 'local:hafs-text.json'),
  ('hafs-7-154', 'hafs', 7, 154, 'وَلَمَّا سَكَتَ عَن مُّوسَى ٱلْغَضَبُ أَخَذَ ٱلْأَلْوَاحَ ۖ وَفِى نُسْخَتِهَا هُدًۭى وَرَحْمَةٌۭ لِّلَّذِينَ هُمْ لِرَبِّهِمْ يَرْهَبُونَ', 'ولما سكت عن موسى الغضب أخذ الألواح  وفى نسختها هدى ورحمة للذين هم لربهم يرهبون', NULL, 169, 'local:hafs-text.json'),
  ('hafs-7-155', 'hafs', 7, 155, 'وَٱخْتَارَ مُوسَىٰ قَوْمَهُۥ سَبْعِينَ رَجُلًۭا لِّمِيقَٰتِنَا ۖ فَلَمَّآ أَخَذَتْهُمُ ٱلرَّجْفَةُ قَالَ رَبِّ لَوْ شِئْتَ أَهْلَكْتَهُم مِّن قَبْلُ وَإِيَّٰىَ ۖ أَتُهْلِكُنَا بِمَا فَعَلَ ٱلسُّفَهَآءُ مِنَّآ ۖ إِنْ هِىَ إِلَّا فِتْنَتُكَ تُضِلُّ بِهَا مَن تَشَآءُ وَتَهْدِى مَن تَشَآءُ ۖ أَنتَ وَلِيُّنَا فَٱغْفِرْ لَنَا وَٱرْحَمْنَا ۖ وَأَنتَ خَيْرُ ٱلْغَٰفِرِينَ', 'واختار موسى قومه سبعين رجلا لميقتنا  فلما أخذتهم الرجفة قال رب لو شئت أهلكتهم من قبل وإيى  أتهلكنا بما فعل السفهاء منا  إن هى إلا فتنتك تضل بها من تشاء وتهدى من تشاء  أنت ولينا فاغفر لنا وارحمنا  وأنت خير الغفرين', NULL, 169, 'local:hafs-text.json'),
  ('hafs-7-156', 'hafs', 7, 156, '۞ وَٱكْتُبْ لَنَا فِى هَٰذِهِ ٱلدُّنْيَا حَسَنَةًۭ وَفِى ٱلْءَاخِرَةِ إِنَّا هُدْنَآ إِلَيْكَ ۚ قَالَ عَذَابِىٓ أُصِيبُ بِهِۦ مَنْ أَشَآءُ ۖ وَرَحْمَتِى وَسِعَتْ كُلَّ شَىْءٍۢ ۚ فَسَأَكْتُبُهَا لِلَّذِينَ يَتَّقُونَ وَيُؤْتُونَ ٱلزَّكَوٰةَ وَٱلَّذِينَ هُم بِـَٔايَٰتِنَا يُؤْمِنُونَ', 'واكتب لنا فى هذه الدنيا حسنة وفى الءاخرة إنا هدنا إليك  قال عذابى أصيب به من أشاء  ورحمتى وسعت كل شىء  فسأكتبها للذين يتقون ويؤتون الزكوة والذين هم بايتنا يؤمنون', NULL, 170, 'local:hafs-text.json'),
  ('hafs-7-157', 'hafs', 7, 157, 'ٱلَّذِينَ يَتَّبِعُونَ ٱلرَّسُولَ ٱلنَّبِىَّ ٱلْأُمِّىَّ ٱلَّذِى يَجِدُونَهُۥ مَكْتُوبًا عِندَهُمْ فِى ٱلتَّوْرَىٰةِ وَٱلْإِنجِيلِ يَأْمُرُهُم بِٱلْمَعْرُوفِ وَيَنْهَىٰهُمْ عَنِ ٱلْمُنكَرِ وَيُحِلُّ لَهُمُ ٱلطَّيِّبَٰتِ وَيُحَرِّمُ عَلَيْهِمُ ٱلْخَبَٰٓئِثَ وَيَضَعُ عَنْهُمْ إِصْرَهُمْ وَٱلْأَغْلَٰلَ ٱلَّتِى كَانَتْ عَلَيْهِمْ ۚ فَٱلَّذِينَ ءَامَنُوا۟ بِهِۦ وَعَزَّرُوهُ وَنَصَرُوهُ وَٱتَّبَعُوا۟ ٱلنُّورَ ٱلَّذِىٓ أُنزِلَ مَعَهُۥٓ ۙ أُو۟لَٰٓئِكَ هُمُ ٱلْمُفْلِحُونَ', 'الذين يتبعون الرسول النبى الأمى الذى يجدونه مكتوبا عندهم فى التورىة والإنجيل يأمرهم بالمعروف وينهىهم عن المنكر ويحل لهم الطيبت ويحرم عليهم الخبئث ويضع عنهم إصرهم والأغلل التى كانت عليهم  فالذين ءامنوا به وعزروه ونصروه واتبعوا النور الذى أنزل معه  أولئك هم المفلحون', NULL, 170, 'local:hafs-text.json'),
  ('hafs-7-158', 'hafs', 7, 158, 'قُلْ يَٰٓأَيُّهَا ٱلنَّاسُ إِنِّى رَسُولُ ٱللَّهِ إِلَيْكُمْ جَمِيعًا ٱلَّذِى لَهُۥ مُلْكُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ ۖ لَآ إِلَٰهَ إِلَّا هُوَ يُحْىِۦ وَيُمِيتُ ۖ فَـَٔامِنُوا۟ بِٱللَّهِ وَرَسُولِهِ ٱلنَّبِىِّ ٱلْأُمِّىِّ ٱلَّذِى يُؤْمِنُ بِٱللَّهِ وَكَلِمَٰتِهِۦ وَٱتَّبِعُوهُ لَعَلَّكُمْ تَهْتَدُونَ', 'قل يأيها الناس إنى رسول الله إليكم جميعا الذى له ملك السموت والأرض  لا إله إلا هو يحى ويميت  فامنوا بالله ورسوله النبى الأمى الذى يؤمن بالله وكلمته واتبعوه لعلكم تهتدون', NULL, 170, 'local:hafs-text.json'),
  ('hafs-7-159', 'hafs', 7, 159, 'وَمِن قَوْمِ مُوسَىٰٓ أُمَّةٌۭ يَهْدُونَ بِٱلْحَقِّ وَبِهِۦ يَعْدِلُونَ', 'ومن قوم موسى أمة يهدون بالحق وبه يعدلون', NULL, 170, 'local:hafs-text.json'),
  ('hafs-7-160', 'hafs', 7, 160, 'وَقَطَّعْنَٰهُمُ ٱثْنَتَىْ عَشْرَةَ أَسْبَاطًا أُمَمًۭا ۚ وَأَوْحَيْنَآ إِلَىٰ مُوسَىٰٓ إِذِ ٱسْتَسْقَىٰهُ قَوْمُهُۥٓ أَنِ ٱضْرِب بِّعَصَاكَ ٱلْحَجَرَ ۖ فَٱنۢبَجَسَتْ مِنْهُ ٱثْنَتَا عَشْرَةَ عَيْنًۭا ۖ قَدْ عَلِمَ كُلُّ أُنَاسٍۢ مَّشْرَبَهُمْ ۚ وَظَلَّلْنَا عَلَيْهِمُ ٱلْغَمَٰمَ وَأَنزَلْنَا عَلَيْهِمُ ٱلْمَنَّ وَٱلسَّلْوَىٰ ۖ كُلُوا۟ مِن طَيِّبَٰتِ مَا رَزَقْنَٰكُمْ ۚ وَمَا ظَلَمُونَا وَلَٰكِن كَانُوٓا۟ أَنفُسَهُمْ يَظْلِمُونَ', 'وقطعنهم اثنتى عشرة أسباطا أمما  وأوحينا إلى موسى إذ استسقىه قومه أن اضرب بعصاك الحجر  فانبجست منه اثنتا عشرة عينا  قد علم كل أناس مشربهم  وظللنا عليهم الغمم وأنزلنا عليهم المن والسلوى  كلوا من طيبت ما رزقنكم  وما ظلمونا ولكن كانوا أنفسهم يظلمون', NULL, 171, 'local:hafs-text.json'),
  ('hafs-7-161', 'hafs', 7, 161, 'وَإِذْ قِيلَ لَهُمُ ٱسْكُنُوا۟ هَٰذِهِ ٱلْقَرْيَةَ وَكُلُوا۟ مِنْهَا حَيْثُ شِئْتُمْ وَقُولُوا۟ حِطَّةٌۭ وَٱدْخُلُوا۟ ٱلْبَابَ سُجَّدًۭا نَّغْفِرْ لَكُمْ خَطِيٓـَٰٔتِكُمْ ۚ سَنَزِيدُ ٱلْمُحْسِنِينَ', 'وإذ قيل لهم اسكنوا هذه القرية وكلوا منها حيث شئتم وقولوا حطة وادخلوا الباب سجدا نغفر لكم خطيتكم  سنزيد المحسنين', NULL, 171, 'local:hafs-text.json'),
  ('hafs-7-162', 'hafs', 7, 162, 'فَبَدَّلَ ٱلَّذِينَ ظَلَمُوا۟ مِنْهُمْ قَوْلًا غَيْرَ ٱلَّذِى قِيلَ لَهُمْ فَأَرْسَلْنَا عَلَيْهِمْ رِجْزًۭا مِّنَ ٱلسَّمَآءِ بِمَا كَانُوا۟ يَظْلِمُونَ', 'فبدل الذين ظلموا منهم قولا غير الذى قيل لهم فأرسلنا عليهم رجزا من السماء بما كانوا يظلمون', NULL, 171, 'local:hafs-text.json'),
  ('hafs-7-163', 'hafs', 7, 163, 'وَسْـَٔلْهُمْ عَنِ ٱلْقَرْيَةِ ٱلَّتِى كَانَتْ حَاضِرَةَ ٱلْبَحْرِ إِذْ يَعْدُونَ فِى ٱلسَّبْتِ إِذْ تَأْتِيهِمْ حِيتَانُهُمْ يَوْمَ سَبْتِهِمْ شُرَّعًۭا وَيَوْمَ لَا يَسْبِتُونَ ۙ لَا تَأْتِيهِمْ ۚ كَذَٰلِكَ نَبْلُوهُم بِمَا كَانُوا۟ يَفْسُقُونَ', 'وسلهم عن القرية التى كانت حاضرة البحر إذ يعدون فى السبت إذ تأتيهم حيتانهم يوم سبتهم شرعا ويوم لا يسبتون  لا تأتيهم  كذلك نبلوهم بما كانوا يفسقون', NULL, 171, 'local:hafs-text.json'),
  ('hafs-7-164', 'hafs', 7, 164, 'وَإِذْ قَالَتْ أُمَّةٌۭ مِّنْهُمْ لِمَ تَعِظُونَ قَوْمًا ۙ ٱللَّهُ مُهْلِكُهُمْ أَوْ مُعَذِّبُهُمْ عَذَابًۭا شَدِيدًۭا ۖ قَالُوا۟ مَعْذِرَةً إِلَىٰ رَبِّكُمْ وَلَعَلَّهُمْ يَتَّقُونَ', 'وإذ قالت أمة منهم لم تعظون قوما  الله مهلكهم أو معذبهم عذابا شديدا  قالوا معذرة إلى ربكم ولعلهم يتقون', NULL, 172, 'local:hafs-text.json'),
  ('hafs-7-165', 'hafs', 7, 165, 'فَلَمَّا نَسُوا۟ مَا ذُكِّرُوا۟ بِهِۦٓ أَنجَيْنَا ٱلَّذِينَ يَنْهَوْنَ عَنِ ٱلسُّوٓءِ وَأَخَذْنَا ٱلَّذِينَ ظَلَمُوا۟ بِعَذَابٍۭ بَـِٔيسٍۭ بِمَا كَانُوا۟ يَفْسُقُونَ', 'فلما نسوا ما ذكروا به أنجينا الذين ينهون عن السوء وأخذنا الذين ظلموا بعذاب بيس بما كانوا يفسقون', NULL, 172, 'local:hafs-text.json'),
  ('hafs-7-166', 'hafs', 7, 166, 'فَلَمَّا عَتَوْا۟ عَن مَّا نُهُوا۟ عَنْهُ قُلْنَا لَهُمْ كُونُوا۟ قِرَدَةً خَٰسِـِٔينَ', 'فلما عتوا عن ما نهوا عنه قلنا لهم كونوا قردة خسين', NULL, 172, 'local:hafs-text.json'),
  ('hafs-7-167', 'hafs', 7, 167, 'وَإِذْ تَأَذَّنَ رَبُّكَ لَيَبْعَثَنَّ عَلَيْهِمْ إِلَىٰ يَوْمِ ٱلْقِيَٰمَةِ مَن يَسُومُهُمْ سُوٓءَ ٱلْعَذَابِ ۗ إِنَّ رَبَّكَ لَسَرِيعُ ٱلْعِقَابِ ۖ وَإِنَّهُۥ لَغَفُورٌۭ رَّحِيمٌۭ', 'وإذ تأذن ربك ليبعثن عليهم إلى يوم القيمة من يسومهم سوء العذاب  إن ربك لسريع العقاب  وإنه لغفور رحيم', NULL, 172, 'local:hafs-text.json'),
  ('hafs-7-168', 'hafs', 7, 168, 'وَقَطَّعْنَٰهُمْ فِى ٱلْأَرْضِ أُمَمًۭا ۖ مِّنْهُمُ ٱلصَّٰلِحُونَ وَمِنْهُمْ دُونَ ذَٰلِكَ ۖ وَبَلَوْنَٰهُم بِٱلْحَسَنَٰتِ وَٱلسَّيِّـَٔاتِ لَعَلَّهُمْ يَرْجِعُونَ', 'وقطعنهم فى الأرض أمما  منهم الصلحون ومنهم دون ذلك  وبلونهم بالحسنت والسيات لعلهم يرجعون', NULL, 172, 'local:hafs-text.json'),
  ('hafs-7-169', 'hafs', 7, 169, 'فَخَلَفَ مِنۢ بَعْدِهِمْ خَلْفٌۭ وَرِثُوا۟ ٱلْكِتَٰبَ يَأْخُذُونَ عَرَضَ هَٰذَا ٱلْأَدْنَىٰ وَيَقُولُونَ سَيُغْفَرُ لَنَا وَإِن يَأْتِهِمْ عَرَضٌۭ مِّثْلُهُۥ يَأْخُذُوهُ ۚ أَلَمْ يُؤْخَذْ عَلَيْهِم مِّيثَٰقُ ٱلْكِتَٰبِ أَن لَّا يَقُولُوا۟ عَلَى ٱللَّهِ إِلَّا ٱلْحَقَّ وَدَرَسُوا۟ مَا فِيهِ ۗ وَٱلدَّارُ ٱلْءَاخِرَةُ خَيْرٌۭ لِّلَّذِينَ يَتَّقُونَ ۗ أَفَلَا تَعْقِلُونَ', 'فخلف من بعدهم خلف ورثوا الكتب يأخذون عرض هذا الأدنى ويقولون سيغفر لنا وإن يأتهم عرض مثله يأخذوه  ألم يؤخذ عليهم ميثق الكتب أن لا يقولوا على الله إلا الحق ودرسوا ما فيه  والدار الءاخرة خير للذين يتقون  أفلا تعقلون', NULL, 172, 'local:hafs-text.json'),
  ('hafs-7-170', 'hafs', 7, 170, 'وَٱلَّذِينَ يُمَسِّكُونَ بِٱلْكِتَٰبِ وَأَقَامُوا۟ ٱلصَّلَوٰةَ إِنَّا لَا نُضِيعُ أَجْرَ ٱلْمُصْلِحِينَ', 'والذين يمسكون بالكتب وأقاموا الصلوة إنا لا نضيع أجر المصلحين', NULL, 172, 'local:hafs-text.json'),
  ('hafs-7-171', 'hafs', 7, 171, '۞ وَإِذْ نَتَقْنَا ٱلْجَبَلَ فَوْقَهُمْ كَأَنَّهُۥ ظُلَّةٌۭ وَظَنُّوٓا۟ أَنَّهُۥ وَاقِعٌۢ بِهِمْ خُذُوا۟ مَآ ءَاتَيْنَٰكُم بِقُوَّةٍۢ وَٱذْكُرُوا۟ مَا فِيهِ لَعَلَّكُمْ تَتَّقُونَ', 'وإذ نتقنا الجبل فوقهم كأنه ظلة وظنوا أنه واقع بهم خذوا ما ءاتينكم بقوة واذكروا ما فيه لعلكم تتقون', NULL, 173, 'local:hafs-text.json'),
  ('hafs-7-172', 'hafs', 7, 172, 'وَإِذْ أَخَذَ رَبُّكَ مِنۢ بَنِىٓ ءَادَمَ مِن ظُهُورِهِمْ ذُرِّيَّتَهُمْ وَأَشْهَدَهُمْ عَلَىٰٓ أَنفُسِهِمْ أَلَسْتُ بِرَبِّكُمْ ۖ قَالُوا۟ بَلَىٰ ۛ شَهِدْنَآ ۛ أَن تَقُولُوا۟ يَوْمَ ٱلْقِيَٰمَةِ إِنَّا كُنَّا عَنْ هَٰذَا غَٰفِلِينَ', 'وإذ أخذ ربك من بنى ءادم من ظهورهم ذريتهم وأشهدهم على أنفسهم ألست بربكم  قالوا بلى  شهدنا  أن تقولوا يوم القيمة إنا كنا عن هذا غفلين', NULL, 173, 'local:hafs-text.json'),
  ('hafs-7-173', 'hafs', 7, 173, 'أَوْ تَقُولُوٓا۟ إِنَّمَآ أَشْرَكَ ءَابَآؤُنَا مِن قَبْلُ وَكُنَّا ذُرِّيَّةًۭ مِّنۢ بَعْدِهِمْ ۖ أَفَتُهْلِكُنَا بِمَا فَعَلَ ٱلْمُبْطِلُونَ', 'أو تقولوا إنما أشرك ءاباؤنا من قبل وكنا ذرية من بعدهم  أفتهلكنا بما فعل المبطلون', NULL, 173, 'local:hafs-text.json'),
  ('hafs-7-174', 'hafs', 7, 174, 'وَكَذَٰلِكَ نُفَصِّلُ ٱلْءَايَٰتِ وَلَعَلَّهُمْ يَرْجِعُونَ', 'وكذلك نفصل الءايت ولعلهم يرجعون', NULL, 173, 'local:hafs-text.json'),
  ('hafs-7-175', 'hafs', 7, 175, 'وَٱتْلُ عَلَيْهِمْ نَبَأَ ٱلَّذِىٓ ءَاتَيْنَٰهُ ءَايَٰتِنَا فَٱنسَلَخَ مِنْهَا فَأَتْبَعَهُ ٱلشَّيْطَٰنُ فَكَانَ مِنَ ٱلْغَاوِينَ', 'واتل عليهم نبأ الذى ءاتينه ءايتنا فانسلخ منها فأتبعه الشيطن فكان من الغاوين', NULL, 173, 'local:hafs-text.json'),
  ('hafs-7-176', 'hafs', 7, 176, 'وَلَوْ شِئْنَا لَرَفَعْنَٰهُ بِهَا وَلَٰكِنَّهُۥٓ أَخْلَدَ إِلَى ٱلْأَرْضِ وَٱتَّبَعَ هَوَىٰهُ ۚ فَمَثَلُهُۥ كَمَثَلِ ٱلْكَلْبِ إِن تَحْمِلْ عَلَيْهِ يَلْهَثْ أَوْ تَتْرُكْهُ يَلْهَث ۚ ذَّٰلِكَ مَثَلُ ٱلْقَوْمِ ٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَٰتِنَا ۚ فَٱقْصُصِ ٱلْقَصَصَ لَعَلَّهُمْ يَتَفَكَّرُونَ', 'ولو شئنا لرفعنه بها ولكنه أخلد إلى الأرض واتبع هوىه  فمثله كمثل الكلب إن تحمل عليه يلهث أو تتركه يلهث  ذلك مثل القوم الذين كذبوا بايتنا  فاقصص القصص لعلهم يتفكرون', NULL, 173, 'local:hafs-text.json'),
  ('hafs-7-177', 'hafs', 7, 177, 'سَآءَ مَثَلًا ٱلْقَوْمُ ٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَٰتِنَا وَأَنفُسَهُمْ كَانُوا۟ يَظْلِمُونَ', 'ساء مثلا القوم الذين كذبوا بايتنا وأنفسهم كانوا يظلمون', NULL, 173, 'local:hafs-text.json'),
  ('hafs-7-178', 'hafs', 7, 178, 'مَن يَهْدِ ٱللَّهُ فَهُوَ ٱلْمُهْتَدِى ۖ وَمَن يُضْلِلْ فَأُو۟لَٰٓئِكَ هُمُ ٱلْخَٰسِرُونَ', 'من يهد الله فهو المهتدى  ومن يضلل فأولئك هم الخسرون', NULL, 173, 'local:hafs-text.json'),
  ('hafs-7-179', 'hafs', 7, 179, 'وَلَقَدْ ذَرَأْنَا لِجَهَنَّمَ كَثِيرًۭا مِّنَ ٱلْجِنِّ وَٱلْإِنسِ ۖ لَهُمْ قُلُوبٌۭ لَّا يَفْقَهُونَ بِهَا وَلَهُمْ أَعْيُنٌۭ لَّا يُبْصِرُونَ بِهَا وَلَهُمْ ءَاذَانٌۭ لَّا يَسْمَعُونَ بِهَآ ۚ أُو۟لَٰٓئِكَ كَٱلْأَنْعَٰمِ بَلْ هُمْ أَضَلُّ ۚ أُو۟لَٰٓئِكَ هُمُ ٱلْغَٰفِلُونَ', 'ولقد ذرأنا لجهنم كثيرا من الجن والإنس  لهم قلوب لا يفقهون بها ولهم أعين لا يبصرون بها ولهم ءاذان لا يسمعون بها  أولئك كالأنعم بل هم أضل  أولئك هم الغفلون', NULL, 174, 'local:hafs-text.json'),
  ('hafs-7-180', 'hafs', 7, 180, 'وَلِلَّهِ ٱلْأَسْمَآءُ ٱلْحُسْنَىٰ فَٱدْعُوهُ بِهَا ۖ وَذَرُوا۟ ٱلَّذِينَ يُلْحِدُونَ فِىٓ أَسْمَٰٓئِهِۦ ۚ سَيُجْزَوْنَ مَا كَانُوا۟ يَعْمَلُونَ', 'ولله الأسماء الحسنى فادعوه بها  وذروا الذين يلحدون فى أسمئه  سيجزون ما كانوا يعملون', NULL, 174, 'local:hafs-text.json'),
  ('hafs-7-181', 'hafs', 7, 181, 'وَمِمَّنْ خَلَقْنَآ أُمَّةٌۭ يَهْدُونَ بِٱلْحَقِّ وَبِهِۦ يَعْدِلُونَ', 'وممن خلقنا أمة يهدون بالحق وبه يعدلون', NULL, 174, 'local:hafs-text.json'),
  ('hafs-7-182', 'hafs', 7, 182, 'وَٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَٰتِنَا سَنَسْتَدْرِجُهُم مِّنْ حَيْثُ لَا يَعْلَمُونَ', 'والذين كذبوا بايتنا سنستدرجهم من حيث لا يعلمون', NULL, 174, 'local:hafs-text.json'),
  ('hafs-7-183', 'hafs', 7, 183, 'وَأُمْلِى لَهُمْ ۚ إِنَّ كَيْدِى مَتِينٌ', 'وأملى لهم  إن كيدى متين', NULL, 174, 'local:hafs-text.json'),
  ('hafs-7-184', 'hafs', 7, 184, 'أَوَلَمْ يَتَفَكَّرُوا۟ ۗ مَا بِصَاحِبِهِم مِّن جِنَّةٍ ۚ إِنْ هُوَ إِلَّا نَذِيرٌۭ مُّبِينٌ', 'أولم يتفكروا  ما بصاحبهم من جنة  إن هو إلا نذير مبين', NULL, 174, 'local:hafs-text.json'),
  ('hafs-7-185', 'hafs', 7, 185, 'أَوَلَمْ يَنظُرُوا۟ فِى مَلَكُوتِ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَمَا خَلَقَ ٱللَّهُ مِن شَىْءٍۢ وَأَنْ عَسَىٰٓ أَن يَكُونَ قَدِ ٱقْتَرَبَ أَجَلُهُمْ ۖ فَبِأَىِّ حَدِيثٍۭ بَعْدَهُۥ يُؤْمِنُونَ', 'أولم ينظروا فى ملكوت السموت والأرض وما خلق الله من شىء وأن عسى أن يكون قد اقترب أجلهم  فبأى حديث بعده يؤمنون', NULL, 174, 'local:hafs-text.json'),
  ('hafs-7-186', 'hafs', 7, 186, 'مَن يُضْلِلِ ٱللَّهُ فَلَا هَادِىَ لَهُۥ ۚ وَيَذَرُهُمْ فِى طُغْيَٰنِهِمْ يَعْمَهُونَ', 'من يضلل الله فلا هادى له  ويذرهم فى طغينهم يعمهون', NULL, 174, 'local:hafs-text.json'),
  ('hafs-7-187', 'hafs', 7, 187, 'يَسْـَٔلُونَكَ عَنِ ٱلسَّاعَةِ أَيَّانَ مُرْسَىٰهَا ۖ قُلْ إِنَّمَا عِلْمُهَا عِندَ رَبِّى ۖ لَا يُجَلِّيهَا لِوَقْتِهَآ إِلَّا هُوَ ۚ ثَقُلَتْ فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ ۚ لَا تَأْتِيكُمْ إِلَّا بَغْتَةًۭ ۗ يَسْـَٔلُونَكَ كَأَنَّكَ حَفِىٌّ عَنْهَا ۖ قُلْ إِنَّمَا عِلْمُهَا عِندَ ٱللَّهِ وَلَٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يَعْلَمُونَ', 'يسلونك عن الساعة أيان مرسىها  قل إنما علمها عند ربى  لا يجليها لوقتها إلا هو  ثقلت فى السموت والأرض  لا تأتيكم إلا بغتة  يسلونك كأنك حفى عنها  قل إنما علمها عند الله ولكن أكثر الناس لا يعلمون', NULL, 174, 'local:hafs-text.json'),
  ('hafs-7-188', 'hafs', 7, 188, 'قُل لَّآ أَمْلِكُ لِنَفْسِى نَفْعًۭا وَلَا ضَرًّا إِلَّا مَا شَآءَ ٱللَّهُ ۚ وَلَوْ كُنتُ أَعْلَمُ ٱلْغَيْبَ لَٱسْتَكْثَرْتُ مِنَ ٱلْخَيْرِ وَمَا مَسَّنِىَ ٱلسُّوٓءُ ۚ إِنْ أَنَا۠ إِلَّا نَذِيرٌۭ وَبَشِيرٌۭ لِّقَوْمٍۢ يُؤْمِنُونَ', 'قل لا أملك لنفسى نفعا ولا ضرا إلا ما شاء الله  ولو كنت أعلم الغيب لاستكثرت من الخير وما مسنى السوء  إن أنا إلا نذير وبشير لقوم يؤمنون', NULL, 175, 'local:hafs-text.json'),
  ('hafs-7-189', 'hafs', 7, 189, '۞ هُوَ ٱلَّذِى خَلَقَكُم مِّن نَّفْسٍۢ وَٰحِدَةٍۢ وَجَعَلَ مِنْهَا زَوْجَهَا لِيَسْكُنَ إِلَيْهَا ۖ فَلَمَّا تَغَشَّىٰهَا حَمَلَتْ حَمْلًا خَفِيفًۭا فَمَرَّتْ بِهِۦ ۖ فَلَمَّآ أَثْقَلَت دَّعَوَا ٱللَّهَ رَبَّهُمَا لَئِنْ ءَاتَيْتَنَا صَٰلِحًۭا لَّنَكُونَنَّ مِنَ ٱلشَّٰكِرِينَ', 'هو الذى خلقكم من نفس وحدة وجعل منها زوجها ليسكن إليها  فلما تغشىها حملت حملا خفيفا فمرت به  فلما أثقلت دعوا الله ربهما لئن ءاتيتنا صلحا لنكونن من الشكرين', NULL, 175, 'local:hafs-text.json'),
  ('hafs-7-190', 'hafs', 7, 190, 'فَلَمَّآ ءَاتَىٰهُمَا صَٰلِحًۭا جَعَلَا لَهُۥ شُرَكَآءَ فِيمَآ ءَاتَىٰهُمَا ۚ فَتَعَٰلَى ٱللَّهُ عَمَّا يُشْرِكُونَ', 'فلما ءاتىهما صلحا جعلا له شركاء فيما ءاتىهما  فتعلى الله عما يشركون', NULL, 175, 'local:hafs-text.json'),
  ('hafs-7-191', 'hafs', 7, 191, 'أَيُشْرِكُونَ مَا لَا يَخْلُقُ شَيْـًۭٔا وَهُمْ يُخْلَقُونَ', 'أيشركون ما لا يخلق شيا وهم يخلقون', NULL, 175, 'local:hafs-text.json'),
  ('hafs-7-192', 'hafs', 7, 192, 'وَلَا يَسْتَطِيعُونَ لَهُمْ نَصْرًۭا وَلَآ أَنفُسَهُمْ يَنصُرُونَ', 'ولا يستطيعون لهم نصرا ولا أنفسهم ينصرون', NULL, 175, 'local:hafs-text.json'),
  ('hafs-7-193', 'hafs', 7, 193, 'وَإِن تَدْعُوهُمْ إِلَى ٱلْهُدَىٰ لَا يَتَّبِعُوكُمْ ۚ سَوَآءٌ عَلَيْكُمْ أَدَعَوْتُمُوهُمْ أَمْ أَنتُمْ صَٰمِتُونَ', 'وإن تدعوهم إلى الهدى لا يتبعوكم  سواء عليكم أدعوتموهم أم أنتم صمتون', NULL, 175, 'local:hafs-text.json'),
  ('hafs-7-194', 'hafs', 7, 194, 'إِنَّ ٱلَّذِينَ تَدْعُونَ مِن دُونِ ٱللَّهِ عِبَادٌ أَمْثَالُكُمْ ۖ فَٱدْعُوهُمْ فَلْيَسْتَجِيبُوا۟ لَكُمْ إِن كُنتُمْ صَٰدِقِينَ', 'إن الذين تدعون من دون الله عباد أمثالكم  فادعوهم فليستجيبوا لكم إن كنتم صدقين', NULL, 175, 'local:hafs-text.json'),
  ('hafs-7-195', 'hafs', 7, 195, 'أَلَهُمْ أَرْجُلٌۭ يَمْشُونَ بِهَآ ۖ أَمْ لَهُمْ أَيْدٍۢ يَبْطِشُونَ بِهَآ ۖ أَمْ لَهُمْ أَعْيُنٌۭ يُبْصِرُونَ بِهَآ ۖ أَمْ لَهُمْ ءَاذَانٌۭ يَسْمَعُونَ بِهَا ۗ قُلِ ٱدْعُوا۟ شُرَكَآءَكُمْ ثُمَّ كِيدُونِ فَلَا تُنظِرُونِ', 'ألهم أرجل يمشون بها  أم لهم أيد يبطشون بها  أم لهم أعين يبصرون بها  أم لهم ءاذان يسمعون بها  قل ادعوا شركاءكم ثم كيدون فلا تنظرون', NULL, 175, 'local:hafs-text.json'),
  ('hafs-7-196', 'hafs', 7, 196, 'إِنَّ وَلِۦِّىَ ٱللَّهُ ٱلَّذِى نَزَّلَ ٱلْكِتَٰبَ ۖ وَهُوَ يَتَوَلَّى ٱلصَّٰلِحِينَ', 'إن ولى الله الذى نزل الكتب  وهو يتولى الصلحين', NULL, 176, 'local:hafs-text.json'),
  ('hafs-7-197', 'hafs', 7, 197, 'وَٱلَّذِينَ تَدْعُونَ مِن دُونِهِۦ لَا يَسْتَطِيعُونَ نَصْرَكُمْ وَلَآ أَنفُسَهُمْ يَنصُرُونَ', 'والذين تدعون من دونه لا يستطيعون نصركم ولا أنفسهم ينصرون', NULL, 176, 'local:hafs-text.json'),
  ('hafs-7-198', 'hafs', 7, 198, 'وَإِن تَدْعُوهُمْ إِلَى ٱلْهُدَىٰ لَا يَسْمَعُوا۟ ۖ وَتَرَىٰهُمْ يَنظُرُونَ إِلَيْكَ وَهُمْ لَا يُبْصِرُونَ', 'وإن تدعوهم إلى الهدى لا يسمعوا  وترىهم ينظرون إليك وهم لا يبصرون', NULL, 176, 'local:hafs-text.json'),
  ('hafs-7-199', 'hafs', 7, 199, 'خُذِ ٱلْعَفْوَ وَأْمُرْ بِٱلْعُرْفِ وَأَعْرِضْ عَنِ ٱلْجَٰهِلِينَ', 'خذ العفو وأمر بالعرف وأعرض عن الجهلين', NULL, 176, 'local:hafs-text.json'),
  ('hafs-7-200', 'hafs', 7, 200, 'وَإِمَّا يَنزَغَنَّكَ مِنَ ٱلشَّيْطَٰنِ نَزْغٌۭ فَٱسْتَعِذْ بِٱللَّهِ ۚ إِنَّهُۥ سَمِيعٌ عَلِيمٌ', 'وإما ينزغنك من الشيطن نزغ فاستعذ بالله  إنه سميع عليم', NULL, 176, 'local:hafs-text.json'),
  ('hafs-7-201', 'hafs', 7, 201, 'إِنَّ ٱلَّذِينَ ٱتَّقَوْا۟ إِذَا مَسَّهُمْ طَٰٓئِفٌۭ مِّنَ ٱلشَّيْطَٰنِ تَذَكَّرُوا۟ فَإِذَا هُم مُّبْصِرُونَ', 'إن الذين اتقوا إذا مسهم طئف من الشيطن تذكروا فإذا هم مبصرون', NULL, 176, 'local:hafs-text.json'),
  ('hafs-7-202', 'hafs', 7, 202, 'وَإِخْوَٰنُهُمْ يَمُدُّونَهُمْ فِى ٱلْغَىِّ ثُمَّ لَا يُقْصِرُونَ', 'وإخونهم يمدونهم فى الغى ثم لا يقصرون', NULL, 176, 'local:hafs-text.json'),
  ('hafs-7-203', 'hafs', 7, 203, 'وَإِذَا لَمْ تَأْتِهِم بِـَٔايَةٍۢ قَالُوا۟ لَوْلَا ٱجْتَبَيْتَهَا ۚ قُلْ إِنَّمَآ أَتَّبِعُ مَا يُوحَىٰٓ إِلَىَّ مِن رَّبِّى ۚ هَٰذَا بَصَآئِرُ مِن رَّبِّكُمْ وَهُدًۭى وَرَحْمَةٌۭ لِّقَوْمٍۢ يُؤْمِنُونَ', 'وإذا لم تأتهم باية قالوا لولا اجتبيتها  قل إنما أتبع ما يوحى إلى من ربى  هذا بصائر من ربكم وهدى ورحمة لقوم يؤمنون', NULL, 176, 'local:hafs-text.json'),
  ('hafs-7-204', 'hafs', 7, 204, 'وَإِذَا قُرِئَ ٱلْقُرْءَانُ فَٱسْتَمِعُوا۟ لَهُۥ وَأَنصِتُوا۟ لَعَلَّكُمْ تُرْحَمُونَ', 'وإذا قرئ القرءان فاستمعوا له وأنصتوا لعلكم ترحمون', NULL, 176, 'local:hafs-text.json'),
  ('hafs-7-205', 'hafs', 7, 205, 'وَٱذْكُر رَّبَّكَ فِى نَفْسِكَ تَضَرُّعًۭا وَخِيفَةًۭ وَدُونَ ٱلْجَهْرِ مِنَ ٱلْقَوْلِ بِٱلْغُدُوِّ وَٱلْءَاصَالِ وَلَا تَكُن مِّنَ ٱلْغَٰفِلِينَ', 'واذكر ربك فى نفسك تضرعا وخيفة ودون الجهر من القول بالغدو والءاصال ولا تكن من الغفلين', NULL, 176, 'local:hafs-text.json'),
  ('hafs-7-206', 'hafs', 7, 206, 'إِنَّ ٱلَّذِينَ عِندَ رَبِّكَ لَا يَسْتَكْبِرُونَ عَنْ عِبَادَتِهِۦ وَيُسَبِّحُونَهُۥ وَلَهُۥ يَسْجُدُونَ ۩', 'إن الذين عند ربك لا يستكبرون عن عبادته ويسبحونه وله يسجدون', NULL, 176, 'local:hafs-text.json'),
  ('hafs-8-1', 'hafs', 8, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ يَسْـَٔلُونَكَ عَنِ ٱلْأَنفَالِ ۖ قُلِ ٱلْأَنفَالُ لِلَّهِ وَٱلرَّسُولِ ۖ فَٱتَّقُوا۟ ٱللَّهَ وَأَصْلِحُوا۟ ذَاتَ بَيْنِكُمْ ۖ وَأَطِيعُوا۟ ٱللَّهَ وَرَسُولَهُۥٓ إِن كُنتُم مُّؤْمِنِينَ', 'بسم الله الرحمن الرحيم يسلونك عن الأنفال  قل الأنفال لله والرسول  فاتقوا الله وأصلحوا ذات بينكم  وأطيعوا الله ورسوله إن كنتم مؤمنين', NULL, 177, 'local:hafs-text.json'),
  ('hafs-8-2', 'hafs', 8, 2, 'إِنَّمَا ٱلْمُؤْمِنُونَ ٱلَّذِينَ إِذَا ذُكِرَ ٱللَّهُ وَجِلَتْ قُلُوبُهُمْ وَإِذَا تُلِيَتْ عَلَيْهِمْ ءَايَٰتُهُۥ زَادَتْهُمْ إِيمَٰنًۭا وَعَلَىٰ رَبِّهِمْ يَتَوَكَّلُونَ', 'إنما المؤمنون الذين إذا ذكر الله وجلت قلوبهم وإذا تليت عليهم ءايته زادتهم إيمنا وعلى ربهم يتوكلون', NULL, 177, 'local:hafs-text.json'),
  ('hafs-8-3', 'hafs', 8, 3, 'ٱلَّذِينَ يُقِيمُونَ ٱلصَّلَوٰةَ وَمِمَّا رَزَقْنَٰهُمْ يُنفِقُونَ', 'الذين يقيمون الصلوة ومما رزقنهم ينفقون', NULL, 177, 'local:hafs-text.json'),
  ('hafs-8-4', 'hafs', 8, 4, 'أُو۟لَٰٓئِكَ هُمُ ٱلْمُؤْمِنُونَ حَقًّۭا ۚ لَّهُمْ دَرَجَٰتٌ عِندَ رَبِّهِمْ وَمَغْفِرَةٌۭ وَرِزْقٌۭ كَرِيمٌۭ', 'أولئك هم المؤمنون حقا  لهم درجت عند ربهم ومغفرة ورزق كريم', NULL, 177, 'local:hafs-text.json'),
  ('hafs-8-5', 'hafs', 8, 5, 'كَمَآ أَخْرَجَكَ رَبُّكَ مِنۢ بَيْتِكَ بِٱلْحَقِّ وَإِنَّ فَرِيقًۭا مِّنَ ٱلْمُؤْمِنِينَ لَكَٰرِهُونَ', 'كما أخرجك ربك من بيتك بالحق وإن فريقا من المؤمنين لكرهون', NULL, 177, 'local:hafs-text.json'),
  ('hafs-8-6', 'hafs', 8, 6, 'يُجَٰدِلُونَكَ فِى ٱلْحَقِّ بَعْدَمَا تَبَيَّنَ كَأَنَّمَا يُسَاقُونَ إِلَى ٱلْمَوْتِ وَهُمْ يَنظُرُونَ', 'يجدلونك فى الحق بعدما تبين كأنما يساقون إلى الموت وهم ينظرون', NULL, 177, 'local:hafs-text.json'),
  ('hafs-8-7', 'hafs', 8, 7, 'وَإِذْ يَعِدُكُمُ ٱللَّهُ إِحْدَى ٱلطَّآئِفَتَيْنِ أَنَّهَا لَكُمْ وَتَوَدُّونَ أَنَّ غَيْرَ ذَاتِ ٱلشَّوْكَةِ تَكُونُ لَكُمْ وَيُرِيدُ ٱللَّهُ أَن يُحِقَّ ٱلْحَقَّ بِكَلِمَٰتِهِۦ وَيَقْطَعَ دَابِرَ ٱلْكَٰفِرِينَ', 'وإذ يعدكم الله إحدى الطائفتين أنها لكم وتودون أن غير ذات الشوكة تكون لكم ويريد الله أن يحق الحق بكلمته ويقطع دابر الكفرين', NULL, 177, 'local:hafs-text.json'),
  ('hafs-8-8', 'hafs', 8, 8, 'لِيُحِقَّ ٱلْحَقَّ وَيُبْطِلَ ٱلْبَٰطِلَ وَلَوْ كَرِهَ ٱلْمُجْرِمُونَ', 'ليحق الحق ويبطل البطل ولو كره المجرمون', NULL, 177, 'local:hafs-text.json'),
  ('hafs-8-9', 'hafs', 8, 9, 'إِذْ تَسْتَغِيثُونَ رَبَّكُمْ فَٱسْتَجَابَ لَكُمْ أَنِّى مُمِدُّكُم بِأَلْفٍۢ مِّنَ ٱلْمَلَٰٓئِكَةِ مُرْدِفِينَ', 'إذ تستغيثون ربكم فاستجاب لكم أنى ممدكم بألف من الملئكة مردفين', NULL, 178, 'local:hafs-text.json'),
  ('hafs-8-10', 'hafs', 8, 10, 'وَمَا جَعَلَهُ ٱللَّهُ إِلَّا بُشْرَىٰ وَلِتَطْمَئِنَّ بِهِۦ قُلُوبُكُمْ ۚ وَمَا ٱلنَّصْرُ إِلَّا مِنْ عِندِ ٱللَّهِ ۚ إِنَّ ٱللَّهَ عَزِيزٌ حَكِيمٌ', 'وما جعله الله إلا بشرى ولتطمئن به قلوبكم  وما النصر إلا من عند الله  إن الله عزيز حكيم', NULL, 178, 'local:hafs-text.json'),
  ('hafs-8-11', 'hafs', 8, 11, 'إِذْ يُغَشِّيكُمُ ٱلنُّعَاسَ أَمَنَةًۭ مِّنْهُ وَيُنَزِّلُ عَلَيْكُم مِّنَ ٱلسَّمَآءِ مَآءًۭ لِّيُطَهِّرَكُم بِهِۦ وَيُذْهِبَ عَنكُمْ رِجْزَ ٱلشَّيْطَٰنِ وَلِيَرْبِطَ عَلَىٰ قُلُوبِكُمْ وَيُثَبِّتَ بِهِ ٱلْأَقْدَامَ', 'إذ يغشيكم النعاس أمنة منه وينزل عليكم من السماء ماء ليطهركم به ويذهب عنكم رجز الشيطن وليربط على قلوبكم ويثبت به الأقدام', NULL, 178, 'local:hafs-text.json'),
  ('hafs-8-12', 'hafs', 8, 12, 'إِذْ يُوحِى رَبُّكَ إِلَى ٱلْمَلَٰٓئِكَةِ أَنِّى مَعَكُمْ فَثَبِّتُوا۟ ٱلَّذِينَ ءَامَنُوا۟ ۚ سَأُلْقِى فِى قُلُوبِ ٱلَّذِينَ كَفَرُوا۟ ٱلرُّعْبَ فَٱضْرِبُوا۟ فَوْقَ ٱلْأَعْنَاقِ وَٱضْرِبُوا۟ مِنْهُمْ كُلَّ بَنَانٍۢ', 'إذ يوحى ربك إلى الملئكة أنى معكم فثبتوا الذين ءامنوا  سألقى فى قلوب الذين كفروا الرعب فاضربوا فوق الأعناق واضربوا منهم كل بنان', NULL, 178, 'local:hafs-text.json'),
  ('hafs-8-13', 'hafs', 8, 13, 'ذَٰلِكَ بِأَنَّهُمْ شَآقُّوا۟ ٱللَّهَ وَرَسُولَهُۥ ۚ وَمَن يُشَاقِقِ ٱللَّهَ وَرَسُولَهُۥ فَإِنَّ ٱللَّهَ شَدِيدُ ٱلْعِقَابِ', 'ذلك بأنهم شاقوا الله ورسوله  ومن يشاقق الله ورسوله فإن الله شديد العقاب', NULL, 178, 'local:hafs-text.json'),
  ('hafs-8-14', 'hafs', 8, 14, 'ذَٰلِكُمْ فَذُوقُوهُ وَأَنَّ لِلْكَٰفِرِينَ عَذَابَ ٱلنَّارِ', 'ذلكم فذوقوه وأن للكفرين عذاب النار', NULL, 178, 'local:hafs-text.json'),
  ('hafs-8-15', 'hafs', 8, 15, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِذَا لَقِيتُمُ ٱلَّذِينَ كَفَرُوا۟ زَحْفًۭا فَلَا تُوَلُّوهُمُ ٱلْأَدْبَارَ', 'يأيها الذين ءامنوا إذا لقيتم الذين كفروا زحفا فلا تولوهم الأدبار', NULL, 178, 'local:hafs-text.json'),
  ('hafs-8-16', 'hafs', 8, 16, 'وَمَن يُوَلِّهِمْ يَوْمَئِذٍۢ دُبُرَهُۥٓ إِلَّا مُتَحَرِّفًۭا لِّقِتَالٍ أَوْ مُتَحَيِّزًا إِلَىٰ فِئَةٍۢ فَقَدْ بَآءَ بِغَضَبٍۢ مِّنَ ٱللَّهِ وَمَأْوَىٰهُ جَهَنَّمُ ۖ وَبِئْسَ ٱلْمَصِيرُ', 'ومن يولهم يومئذ دبره إلا متحرفا لقتال أو متحيزا إلى فئة فقد باء بغضب من الله ومأوىه جهنم  وبئس المصير', NULL, 178, 'local:hafs-text.json'),
  ('hafs-8-17', 'hafs', 8, 17, 'فَلَمْ تَقْتُلُوهُمْ وَلَٰكِنَّ ٱللَّهَ قَتَلَهُمْ ۚ وَمَا رَمَيْتَ إِذْ رَمَيْتَ وَلَٰكِنَّ ٱللَّهَ رَمَىٰ ۚ وَلِيُبْلِىَ ٱلْمُؤْمِنِينَ مِنْهُ بَلَآءً حَسَنًا ۚ إِنَّ ٱللَّهَ سَمِيعٌ عَلِيمٌۭ', 'فلم تقتلوهم ولكن الله قتلهم  وما رميت إذ رميت ولكن الله رمى  وليبلى المؤمنين منه بلاء حسنا  إن الله سميع عليم', NULL, 179, 'local:hafs-text.json'),
  ('hafs-8-18', 'hafs', 8, 18, 'ذَٰلِكُمْ وَأَنَّ ٱللَّهَ مُوهِنُ كَيْدِ ٱلْكَٰفِرِينَ', 'ذلكم وأن الله موهن كيد الكفرين', NULL, 179, 'local:hafs-text.json'),
  ('hafs-8-19', 'hafs', 8, 19, 'إِن تَسْتَفْتِحُوا۟ فَقَدْ جَآءَكُمُ ٱلْفَتْحُ ۖ وَإِن تَنتَهُوا۟ فَهُوَ خَيْرٌۭ لَّكُمْ ۖ وَإِن تَعُودُوا۟ نَعُدْ وَلَن تُغْنِىَ عَنكُمْ فِئَتُكُمْ شَيْـًۭٔا وَلَوْ كَثُرَتْ وَأَنَّ ٱللَّهَ مَعَ ٱلْمُؤْمِنِينَ', 'إن تستفتحوا فقد جاءكم الفتح  وإن تنتهوا فهو خير لكم  وإن تعودوا نعد ولن تغنى عنكم فئتكم شيا ولو كثرت وأن الله مع المؤمنين', NULL, 179, 'local:hafs-text.json'),
  ('hafs-8-20', 'hafs', 8, 20, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ أَطِيعُوا۟ ٱللَّهَ وَرَسُولَهُۥ وَلَا تَوَلَّوْا۟ عَنْهُ وَأَنتُمْ تَسْمَعُونَ', 'يأيها الذين ءامنوا أطيعوا الله ورسوله ولا تولوا عنه وأنتم تسمعون', NULL, 179, 'local:hafs-text.json'),
  ('hafs-8-21', 'hafs', 8, 21, 'وَلَا تَكُونُوا۟ كَٱلَّذِينَ قَالُوا۟ سَمِعْنَا وَهُمْ لَا يَسْمَعُونَ', 'ولا تكونوا كالذين قالوا سمعنا وهم لا يسمعون', NULL, 179, 'local:hafs-text.json'),
  ('hafs-8-22', 'hafs', 8, 22, '۞ إِنَّ شَرَّ ٱلدَّوَآبِّ عِندَ ٱللَّهِ ٱلصُّمُّ ٱلْبُكْمُ ٱلَّذِينَ لَا يَعْقِلُونَ', 'إن شر الدواب عند الله الصم البكم الذين لا يعقلون', NULL, 179, 'local:hafs-text.json'),
  ('hafs-8-23', 'hafs', 8, 23, 'وَلَوْ عَلِمَ ٱللَّهُ فِيهِمْ خَيْرًۭا لَّأَسْمَعَهُمْ ۖ وَلَوْ أَسْمَعَهُمْ لَتَوَلَّوا۟ وَّهُم مُّعْرِضُونَ', 'ولو علم الله فيهم خيرا لأسمعهم  ولو أسمعهم لتولوا وهم معرضون', NULL, 179, 'local:hafs-text.json'),
  ('hafs-8-24', 'hafs', 8, 24, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱسْتَجِيبُوا۟ لِلَّهِ وَلِلرَّسُولِ إِذَا دَعَاكُمْ لِمَا يُحْيِيكُمْ ۖ وَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ يَحُولُ بَيْنَ ٱلْمَرْءِ وَقَلْبِهِۦ وَأَنَّهُۥٓ إِلَيْهِ تُحْشَرُونَ', 'يأيها الذين ءامنوا استجيبوا لله وللرسول إذا دعاكم لما يحييكم  واعلموا أن الله يحول بين المرء وقلبه وأنه إليه تحشرون', NULL, 179, 'local:hafs-text.json'),
  ('hafs-8-25', 'hafs', 8, 25, 'وَٱتَّقُوا۟ فِتْنَةًۭ لَّا تُصِيبَنَّ ٱلَّذِينَ ظَلَمُوا۟ مِنكُمْ خَآصَّةًۭ ۖ وَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ شَدِيدُ ٱلْعِقَابِ', 'واتقوا فتنة لا تصيبن الذين ظلموا منكم خاصة  واعلموا أن الله شديد العقاب', NULL, 179, 'local:hafs-text.json'),
  ('hafs-8-26', 'hafs', 8, 26, 'وَٱذْكُرُوٓا۟ إِذْ أَنتُمْ قَلِيلٌۭ مُّسْتَضْعَفُونَ فِى ٱلْأَرْضِ تَخَافُونَ أَن يَتَخَطَّفَكُمُ ٱلنَّاسُ فَـَٔاوَىٰكُمْ وَأَيَّدَكُم بِنَصْرِهِۦ وَرَزَقَكُم مِّنَ ٱلطَّيِّبَٰتِ لَعَلَّكُمْ تَشْكُرُونَ', 'واذكروا إذ أنتم قليل مستضعفون فى الأرض تخافون أن يتخطفكم الناس فاوىكم وأيدكم بنصره ورزقكم من الطيبت لعلكم تشكرون', NULL, 180, 'local:hafs-text.json'),
  ('hafs-8-27', 'hafs', 8, 27, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَخُونُوا۟ ٱللَّهَ وَٱلرَّسُولَ وَتَخُونُوٓا۟ أَمَٰنَٰتِكُمْ وَأَنتُمْ تَعْلَمُونَ', 'يأيها الذين ءامنوا لا تخونوا الله والرسول وتخونوا أمنتكم وأنتم تعلمون', NULL, 180, 'local:hafs-text.json'),
  ('hafs-8-28', 'hafs', 8, 28, 'وَٱعْلَمُوٓا۟ أَنَّمَآ أَمْوَٰلُكُمْ وَأَوْلَٰدُكُمْ فِتْنَةٌۭ وَأَنَّ ٱللَّهَ عِندَهُۥٓ أَجْرٌ عَظِيمٌۭ', 'واعلموا أنما أمولكم وأولدكم فتنة وأن الله عنده أجر عظيم', NULL, 180, 'local:hafs-text.json'),
  ('hafs-8-29', 'hafs', 8, 29, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِن تَتَّقُوا۟ ٱللَّهَ يَجْعَل لَّكُمْ فُرْقَانًۭا وَيُكَفِّرْ عَنكُمْ سَيِّـَٔاتِكُمْ وَيَغْفِرْ لَكُمْ ۗ وَٱللَّهُ ذُو ٱلْفَضْلِ ٱلْعَظِيمِ', 'يأيها الذين ءامنوا إن تتقوا الله يجعل لكم فرقانا ويكفر عنكم سياتكم ويغفر لكم  والله ذو الفضل العظيم', NULL, 180, 'local:hafs-text.json'),
  ('hafs-8-30', 'hafs', 8, 30, 'وَإِذْ يَمْكُرُ بِكَ ٱلَّذِينَ كَفَرُوا۟ لِيُثْبِتُوكَ أَوْ يَقْتُلُوكَ أَوْ يُخْرِجُوكَ ۚ وَيَمْكُرُونَ وَيَمْكُرُ ٱللَّهُ ۖ وَٱللَّهُ خَيْرُ ٱلْمَٰكِرِينَ', 'وإذ يمكر بك الذين كفروا ليثبتوك أو يقتلوك أو يخرجوك  ويمكرون ويمكر الله  والله خير المكرين', NULL, 180, 'local:hafs-text.json'),
  ('hafs-8-31', 'hafs', 8, 31, 'وَإِذَا تُتْلَىٰ عَلَيْهِمْ ءَايَٰتُنَا قَالُوا۟ قَدْ سَمِعْنَا لَوْ نَشَآءُ لَقُلْنَا مِثْلَ هَٰذَآ ۙ إِنْ هَٰذَآ إِلَّآ أَسَٰطِيرُ ٱلْأَوَّلِينَ', 'وإذا تتلى عليهم ءايتنا قالوا قد سمعنا لو نشاء لقلنا مثل هذا  إن هذا إلا أسطير الأولين', NULL, 180, 'local:hafs-text.json'),
  ('hafs-8-32', 'hafs', 8, 32, 'وَإِذْ قَالُوا۟ ٱللَّهُمَّ إِن كَانَ هَٰذَا هُوَ ٱلْحَقَّ مِنْ عِندِكَ فَأَمْطِرْ عَلَيْنَا حِجَارَةًۭ مِّنَ ٱلسَّمَآءِ أَوِ ٱئْتِنَا بِعَذَابٍ أَلِيمٍۢ', 'وإذ قالوا اللهم إن كان هذا هو الحق من عندك فأمطر علينا حجارة من السماء أو ائتنا بعذاب أليم', NULL, 180, 'local:hafs-text.json'),
  ('hafs-8-33', 'hafs', 8, 33, 'وَمَا كَانَ ٱللَّهُ لِيُعَذِّبَهُمْ وَأَنتَ فِيهِمْ ۚ وَمَا كَانَ ٱللَّهُ مُعَذِّبَهُمْ وَهُمْ يَسْتَغْفِرُونَ', 'وما كان الله ليعذبهم وأنت فيهم  وما كان الله معذبهم وهم يستغفرون', NULL, 180, 'local:hafs-text.json'),
  ('hafs-8-34', 'hafs', 8, 34, 'وَمَا لَهُمْ أَلَّا يُعَذِّبَهُمُ ٱللَّهُ وَهُمْ يَصُدُّونَ عَنِ ٱلْمَسْجِدِ ٱلْحَرَامِ وَمَا كَانُوٓا۟ أَوْلِيَآءَهُۥٓ ۚ إِنْ أَوْلِيَآؤُهُۥٓ إِلَّا ٱلْمُتَّقُونَ وَلَٰكِنَّ أَكْثَرَهُمْ لَا يَعْلَمُونَ', 'وما لهم ألا يعذبهم الله وهم يصدون عن المسجد الحرام وما كانوا أولياءه  إن أولياؤه إلا المتقون ولكن أكثرهم لا يعلمون', NULL, 181, 'local:hafs-text.json'),
  ('hafs-8-35', 'hafs', 8, 35, 'وَمَا كَانَ صَلَاتُهُمْ عِندَ ٱلْبَيْتِ إِلَّا مُكَآءًۭ وَتَصْدِيَةًۭ ۚ فَذُوقُوا۟ ٱلْعَذَابَ بِمَا كُنتُمْ تَكْفُرُونَ', 'وما كان صلاتهم عند البيت إلا مكاء وتصدية  فذوقوا العذاب بما كنتم تكفرون', NULL, 181, 'local:hafs-text.json'),
  ('hafs-8-36', 'hafs', 8, 36, 'إِنَّ ٱلَّذِينَ كَفَرُوا۟ يُنفِقُونَ أَمْوَٰلَهُمْ لِيَصُدُّوا۟ عَن سَبِيلِ ٱللَّهِ ۚ فَسَيُنفِقُونَهَا ثُمَّ تَكُونُ عَلَيْهِمْ حَسْرَةًۭ ثُمَّ يُغْلَبُونَ ۗ وَٱلَّذِينَ كَفَرُوٓا۟ إِلَىٰ جَهَنَّمَ يُحْشَرُونَ', 'إن الذين كفروا ينفقون أمولهم ليصدوا عن سبيل الله  فسينفقونها ثم تكون عليهم حسرة ثم يغلبون  والذين كفروا إلى جهنم يحشرون', NULL, 181, 'local:hafs-text.json'),
  ('hafs-8-37', 'hafs', 8, 37, 'لِيَمِيزَ ٱللَّهُ ٱلْخَبِيثَ مِنَ ٱلطَّيِّبِ وَيَجْعَلَ ٱلْخَبِيثَ بَعْضَهُۥ عَلَىٰ بَعْضٍۢ فَيَرْكُمَهُۥ جَمِيعًۭا فَيَجْعَلَهُۥ فِى جَهَنَّمَ ۚ أُو۟لَٰٓئِكَ هُمُ ٱلْخَٰسِرُونَ', 'ليميز الله الخبيث من الطيب ويجعل الخبيث بعضه على بعض فيركمه جميعا فيجعله فى جهنم  أولئك هم الخسرون', NULL, 181, 'local:hafs-text.json'),
  ('hafs-8-38', 'hafs', 8, 38, 'قُل لِّلَّذِينَ كَفَرُوٓا۟ إِن يَنتَهُوا۟ يُغْفَرْ لَهُم مَّا قَدْ سَلَفَ وَإِن يَعُودُوا۟ فَقَدْ مَضَتْ سُنَّتُ ٱلْأَوَّلِينَ', 'قل للذين كفروا إن ينتهوا يغفر لهم ما قد سلف وإن يعودوا فقد مضت سنت الأولين', NULL, 181, 'local:hafs-text.json'),
  ('hafs-8-39', 'hafs', 8, 39, 'وَقَٰتِلُوهُمْ حَتَّىٰ لَا تَكُونَ فِتْنَةٌۭ وَيَكُونَ ٱلدِّينُ كُلُّهُۥ لِلَّهِ ۚ فَإِنِ ٱنتَهَوْا۟ فَإِنَّ ٱللَّهَ بِمَا يَعْمَلُونَ بَصِيرٌۭ', 'وقتلوهم حتى لا تكون فتنة ويكون الدين كله لله  فإن انتهوا فإن الله بما يعملون بصير', NULL, 181, 'local:hafs-text.json'),
  ('hafs-8-40', 'hafs', 8, 40, 'وَإِن تَوَلَّوْا۟ فَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ مَوْلَىٰكُمْ ۚ نِعْمَ ٱلْمَوْلَىٰ وَنِعْمَ ٱلنَّصِيرُ', 'وإن تولوا فاعلموا أن الله مولىكم  نعم المولى ونعم النصير', NULL, 181, 'local:hafs-text.json')
insert into public.ayahs (id, riwayah, surah_number, ayah_number, text, simple_text, juz, page, source) values
  ('hafs-8-41', 'hafs', 8, 41, '۞ وَٱعْلَمُوٓا۟ أَنَّمَا غَنِمْتُم مِّن شَىْءٍۢ فَأَنَّ لِلَّهِ خُمُسَهُۥ وَلِلرَّسُولِ وَلِذِى ٱلْقُرْبَىٰ وَٱلْيَتَٰمَىٰ وَٱلْمَسَٰكِينِ وَٱبْنِ ٱلسَّبِيلِ إِن كُنتُمْ ءَامَنتُم بِٱللَّهِ وَمَآ أَنزَلْنَا عَلَىٰ عَبْدِنَا يَوْمَ ٱلْفُرْقَانِ يَوْمَ ٱلْتَقَى ٱلْجَمْعَانِ ۗ وَٱللَّهُ عَلَىٰ كُلِّ شَىْءٍۢ قَدِيرٌ', 'واعلموا أنما غنمتم من شىء فأن لله خمسه وللرسول ولذى القربى واليتمى والمسكين وابن السبيل إن كنتم ءامنتم بالله وما أنزلنا على عبدنا يوم الفرقان يوم التقى الجمعان  والله على كل شىء قدير', NULL, 182, 'local:hafs-text.json'),
  ('hafs-8-42', 'hafs', 8, 42, 'إِذْ أَنتُم بِٱلْعُدْوَةِ ٱلدُّنْيَا وَهُم بِٱلْعُدْوَةِ ٱلْقُصْوَىٰ وَٱلرَّكْبُ أَسْفَلَ مِنكُمْ ۚ وَلَوْ تَوَاعَدتُّمْ لَٱخْتَلَفْتُمْ فِى ٱلْمِيعَٰدِ ۙ وَلَٰكِن لِّيَقْضِىَ ٱللَّهُ أَمْرًۭا كَانَ مَفْعُولًۭا لِّيَهْلِكَ مَنْ هَلَكَ عَنۢ بَيِّنَةٍۢ وَيَحْيَىٰ مَنْ حَىَّ عَنۢ بَيِّنَةٍۢ ۗ وَإِنَّ ٱللَّهَ لَسَمِيعٌ عَلِيمٌ', 'إذ أنتم بالعدوة الدنيا وهم بالعدوة القصوى والركب أسفل منكم  ولو تواعدتم لاختلفتم فى الميعد  ولكن ليقضى الله أمرا كان مفعولا ليهلك من هلك عن بينة ويحيى من حى عن بينة  وإن الله لسميع عليم', NULL, 182, 'local:hafs-text.json'),
  ('hafs-8-43', 'hafs', 8, 43, 'إِذْ يُرِيكَهُمُ ٱللَّهُ فِى مَنَامِكَ قَلِيلًۭا ۖ وَلَوْ أَرَىٰكَهُمْ كَثِيرًۭا لَّفَشِلْتُمْ وَلَتَنَٰزَعْتُمْ فِى ٱلْأَمْرِ وَلَٰكِنَّ ٱللَّهَ سَلَّمَ ۗ إِنَّهُۥ عَلِيمٌۢ بِذَاتِ ٱلصُّدُورِ', 'إذ يريكهم الله فى منامك قليلا  ولو أرىكهم كثيرا لفشلتم ولتنزعتم فى الأمر ولكن الله سلم  إنه عليم بذات الصدور', NULL, 182, 'local:hafs-text.json'),
  ('hafs-8-44', 'hafs', 8, 44, 'وَإِذْ يُرِيكُمُوهُمْ إِذِ ٱلْتَقَيْتُمْ فِىٓ أَعْيُنِكُمْ قَلِيلًۭا وَيُقَلِّلُكُمْ فِىٓ أَعْيُنِهِمْ لِيَقْضِىَ ٱللَّهُ أَمْرًۭا كَانَ مَفْعُولًۭا ۗ وَإِلَى ٱللَّهِ تُرْجَعُ ٱلْأُمُورُ', 'وإذ يريكموهم إذ التقيتم فى أعينكم قليلا ويقللكم فى أعينهم ليقضى الله أمرا كان مفعولا  وإلى الله ترجع الأمور', NULL, 182, 'local:hafs-text.json'),
  ('hafs-8-45', 'hafs', 8, 45, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِذَا لَقِيتُمْ فِئَةًۭ فَٱثْبُتُوا۟ وَٱذْكُرُوا۟ ٱللَّهَ كَثِيرًۭا لَّعَلَّكُمْ تُفْلِحُونَ', 'يأيها الذين ءامنوا إذا لقيتم فئة فاثبتوا واذكروا الله كثيرا لعلكم تفلحون', NULL, 182, 'local:hafs-text.json'),
  ('hafs-8-46', 'hafs', 8, 46, 'وَأَطِيعُوا۟ ٱللَّهَ وَرَسُولَهُۥ وَلَا تَنَٰزَعُوا۟ فَتَفْشَلُوا۟ وَتَذْهَبَ رِيحُكُمْ ۖ وَٱصْبِرُوٓا۟ ۚ إِنَّ ٱللَّهَ مَعَ ٱلصَّٰبِرِينَ', 'وأطيعوا الله ورسوله ولا تنزعوا فتفشلوا وتذهب ريحكم  واصبروا  إن الله مع الصبرين', NULL, 183, 'local:hafs-text.json'),
  ('hafs-8-47', 'hafs', 8, 47, 'وَلَا تَكُونُوا۟ كَٱلَّذِينَ خَرَجُوا۟ مِن دِيَٰرِهِم بَطَرًۭا وَرِئَآءَ ٱلنَّاسِ وَيَصُدُّونَ عَن سَبِيلِ ٱللَّهِ ۚ وَٱللَّهُ بِمَا يَعْمَلُونَ مُحِيطٌۭ', 'ولا تكونوا كالذين خرجوا من ديرهم بطرا ورئاء الناس ويصدون عن سبيل الله  والله بما يعملون محيط', NULL, 183, 'local:hafs-text.json'),
  ('hafs-8-48', 'hafs', 8, 48, 'وَإِذْ زَيَّنَ لَهُمُ ٱلشَّيْطَٰنُ أَعْمَٰلَهُمْ وَقَالَ لَا غَالِبَ لَكُمُ ٱلْيَوْمَ مِنَ ٱلنَّاسِ وَإِنِّى جَارٌۭ لَّكُمْ ۖ فَلَمَّا تَرَآءَتِ ٱلْفِئَتَانِ نَكَصَ عَلَىٰ عَقِبَيْهِ وَقَالَ إِنِّى بَرِىٓءٌۭ مِّنكُمْ إِنِّىٓ أَرَىٰ مَا لَا تَرَوْنَ إِنِّىٓ أَخَافُ ٱللَّهَ ۚ وَٱللَّهُ شَدِيدُ ٱلْعِقَابِ', 'وإذ زين لهم الشيطن أعملهم وقال لا غالب لكم اليوم من الناس وإنى جار لكم  فلما تراءت الفئتان نكص على عقبيه وقال إنى برىء منكم إنى أرى ما لا ترون إنى أخاف الله  والله شديد العقاب', NULL, 183, 'local:hafs-text.json'),
  ('hafs-8-49', 'hafs', 8, 49, 'إِذْ يَقُولُ ٱلْمُنَٰفِقُونَ وَٱلَّذِينَ فِى قُلُوبِهِم مَّرَضٌ غَرَّ هَٰٓؤُلَآءِ دِينُهُمْ ۗ وَمَن يَتَوَكَّلْ عَلَى ٱللَّهِ فَإِنَّ ٱللَّهَ عَزِيزٌ حَكِيمٌۭ', 'إذ يقول المنفقون والذين فى قلوبهم مرض غر هؤلاء دينهم  ومن يتوكل على الله فإن الله عزيز حكيم', NULL, 183, 'local:hafs-text.json'),
  ('hafs-8-50', 'hafs', 8, 50, 'وَلَوْ تَرَىٰٓ إِذْ يَتَوَفَّى ٱلَّذِينَ كَفَرُوا۟ ۙ ٱلْمَلَٰٓئِكَةُ يَضْرِبُونَ وُجُوهَهُمْ وَأَدْبَٰرَهُمْ وَذُوقُوا۟ عَذَابَ ٱلْحَرِيقِ', 'ولو ترى إذ يتوفى الذين كفروا  الملئكة يضربون وجوههم وأدبرهم وذوقوا عذاب الحريق', NULL, 183, 'local:hafs-text.json'),
  ('hafs-8-51', 'hafs', 8, 51, 'ذَٰلِكَ بِمَا قَدَّمَتْ أَيْدِيكُمْ وَأَنَّ ٱللَّهَ لَيْسَ بِظَلَّٰمٍۢ لِّلْعَبِيدِ', 'ذلك بما قدمت أيديكم وأن الله ليس بظلم للعبيد', NULL, 183, 'local:hafs-text.json'),
  ('hafs-8-52', 'hafs', 8, 52, 'كَدَأْبِ ءَالِ فِرْعَوْنَ ۙ وَٱلَّذِينَ مِن قَبْلِهِمْ ۚ كَفَرُوا۟ بِـَٔايَٰتِ ٱللَّهِ فَأَخَذَهُمُ ٱللَّهُ بِذُنُوبِهِمْ ۗ إِنَّ ٱللَّهَ قَوِىٌّۭ شَدِيدُ ٱلْعِقَابِ', 'كدأب ءال فرعون  والذين من قبلهم  كفروا بايت الله فأخذهم الله بذنوبهم  إن الله قوى شديد العقاب', NULL, 183, 'local:hafs-text.json'),
  ('hafs-8-53', 'hafs', 8, 53, 'ذَٰلِكَ بِأَنَّ ٱللَّهَ لَمْ يَكُ مُغَيِّرًۭا نِّعْمَةً أَنْعَمَهَا عَلَىٰ قَوْمٍ حَتَّىٰ يُغَيِّرُوا۟ مَا بِأَنفُسِهِمْ ۙ وَأَنَّ ٱللَّهَ سَمِيعٌ عَلِيمٌۭ', 'ذلك بأن الله لم يك مغيرا نعمة أنعمها على قوم حتى يغيروا ما بأنفسهم  وأن الله سميع عليم', NULL, 184, 'local:hafs-text.json'),
  ('hafs-8-54', 'hafs', 8, 54, 'كَدَأْبِ ءَالِ فِرْعَوْنَ ۙ وَٱلَّذِينَ مِن قَبْلِهِمْ ۚ كَذَّبُوا۟ بِـَٔايَٰتِ رَبِّهِمْ فَأَهْلَكْنَٰهُم بِذُنُوبِهِمْ وَأَغْرَقْنَآ ءَالَ فِرْعَوْنَ ۚ وَكُلٌّۭ كَانُوا۟ ظَٰلِمِينَ', 'كدأب ءال فرعون  والذين من قبلهم  كذبوا بايت ربهم فأهلكنهم بذنوبهم وأغرقنا ءال فرعون  وكل كانوا ظلمين', NULL, 184, 'local:hafs-text.json'),
  ('hafs-8-55', 'hafs', 8, 55, 'إِنَّ شَرَّ ٱلدَّوَآبِّ عِندَ ٱللَّهِ ٱلَّذِينَ كَفَرُوا۟ فَهُمْ لَا يُؤْمِنُونَ', 'إن شر الدواب عند الله الذين كفروا فهم لا يؤمنون', NULL, 184, 'local:hafs-text.json'),
  ('hafs-8-56', 'hafs', 8, 56, 'ٱلَّذِينَ عَٰهَدتَّ مِنْهُمْ ثُمَّ يَنقُضُونَ عَهْدَهُمْ فِى كُلِّ مَرَّةٍۢ وَهُمْ لَا يَتَّقُونَ', 'الذين عهدت منهم ثم ينقضون عهدهم فى كل مرة وهم لا يتقون', NULL, 184, 'local:hafs-text.json'),
  ('hafs-8-57', 'hafs', 8, 57, 'فَإِمَّا تَثْقَفَنَّهُمْ فِى ٱلْحَرْبِ فَشَرِّدْ بِهِم مَّنْ خَلْفَهُمْ لَعَلَّهُمْ يَذَّكَّرُونَ', 'فإما تثقفنهم فى الحرب فشرد بهم من خلفهم لعلهم يذكرون', NULL, 184, 'local:hafs-text.json'),
  ('hafs-8-58', 'hafs', 8, 58, 'وَإِمَّا تَخَافَنَّ مِن قَوْمٍ خِيَانَةًۭ فَٱنۢبِذْ إِلَيْهِمْ عَلَىٰ سَوَآءٍ ۚ إِنَّ ٱللَّهَ لَا يُحِبُّ ٱلْخَآئِنِينَ', 'وإما تخافن من قوم خيانة فانبذ إليهم على سواء  إن الله لا يحب الخائنين', NULL, 184, 'local:hafs-text.json'),
  ('hafs-8-59', 'hafs', 8, 59, 'وَلَا يَحْسَبَنَّ ٱلَّذِينَ كَفَرُوا۟ سَبَقُوٓا۟ ۚ إِنَّهُمْ لَا يُعْجِزُونَ', 'ولا يحسبن الذين كفروا سبقوا  إنهم لا يعجزون', NULL, 184, 'local:hafs-text.json'),
  ('hafs-8-60', 'hafs', 8, 60, 'وَأَعِدُّوا۟ لَهُم مَّا ٱسْتَطَعْتُم مِّن قُوَّةٍۢ وَمِن رِّبَاطِ ٱلْخَيْلِ تُرْهِبُونَ بِهِۦ عَدُوَّ ٱللَّهِ وَعَدُوَّكُمْ وَءَاخَرِينَ مِن دُونِهِمْ لَا تَعْلَمُونَهُمُ ٱللَّهُ يَعْلَمُهُمْ ۚ وَمَا تُنفِقُوا۟ مِن شَىْءٍۢ فِى سَبِيلِ ٱللَّهِ يُوَفَّ إِلَيْكُمْ وَأَنتُمْ لَا تُظْلَمُونَ', 'وأعدوا لهم ما استطعتم من قوة ومن رباط الخيل ترهبون به عدو الله وعدوكم وءاخرين من دونهم لا تعلمونهم الله يعلمهم  وما تنفقوا من شىء فى سبيل الله يوف إليكم وأنتم لا تظلمون', NULL, 184, 'local:hafs-text.json'),
  ('hafs-8-61', 'hafs', 8, 61, '۞ وَإِن جَنَحُوا۟ لِلسَّلْمِ فَٱجْنَحْ لَهَا وَتَوَكَّلْ عَلَى ٱللَّهِ ۚ إِنَّهُۥ هُوَ ٱلسَّمِيعُ ٱلْعَلِيمُ', 'وإن جنحوا للسلم فاجنح لها وتوكل على الله  إنه هو السميع العليم', NULL, 184, 'local:hafs-text.json'),
  ('hafs-8-62', 'hafs', 8, 62, 'وَإِن يُرِيدُوٓا۟ أَن يَخْدَعُوكَ فَإِنَّ حَسْبَكَ ٱللَّهُ ۚ هُوَ ٱلَّذِىٓ أَيَّدَكَ بِنَصْرِهِۦ وَبِٱلْمُؤْمِنِينَ', 'وإن يريدوا أن يخدعوك فإن حسبك الله  هو الذى أيدك بنصره وبالمؤمنين', NULL, 185, 'local:hafs-text.json'),
  ('hafs-8-63', 'hafs', 8, 63, 'وَأَلَّفَ بَيْنَ قُلُوبِهِمْ ۚ لَوْ أَنفَقْتَ مَا فِى ٱلْأَرْضِ جَمِيعًۭا مَّآ أَلَّفْتَ بَيْنَ قُلُوبِهِمْ وَلَٰكِنَّ ٱللَّهَ أَلَّفَ بَيْنَهُمْ ۚ إِنَّهُۥ عَزِيزٌ حَكِيمٌۭ', 'وألف بين قلوبهم  لو أنفقت ما فى الأرض جميعا ما ألفت بين قلوبهم ولكن الله ألف بينهم  إنه عزيز حكيم', NULL, 185, 'local:hafs-text.json'),
  ('hafs-8-64', 'hafs', 8, 64, 'يَٰٓأَيُّهَا ٱلنَّبِىُّ حَسْبُكَ ٱللَّهُ وَمَنِ ٱتَّبَعَكَ مِنَ ٱلْمُؤْمِنِينَ', 'يأيها النبى حسبك الله ومن اتبعك من المؤمنين', NULL, 185, 'local:hafs-text.json'),
  ('hafs-8-65', 'hafs', 8, 65, 'يَٰٓأَيُّهَا ٱلنَّبِىُّ حَرِّضِ ٱلْمُؤْمِنِينَ عَلَى ٱلْقِتَالِ ۚ إِن يَكُن مِّنكُمْ عِشْرُونَ صَٰبِرُونَ يَغْلِبُوا۟ مِا۟ئَتَيْنِ ۚ وَإِن يَكُن مِّنكُم مِّا۟ئَةٌۭ يَغْلِبُوٓا۟ أَلْفًۭا مِّنَ ٱلَّذِينَ كَفَرُوا۟ بِأَنَّهُمْ قَوْمٌۭ لَّا يَفْقَهُونَ', 'يأيها النبى حرض المؤمنين على القتال  إن يكن منكم عشرون صبرون يغلبوا مائتين  وإن يكن منكم مائة يغلبوا ألفا من الذين كفروا بأنهم قوم لا يفقهون', NULL, 185, 'local:hafs-text.json'),
  ('hafs-8-66', 'hafs', 8, 66, 'ٱلْـَٰٔنَ خَفَّفَ ٱللَّهُ عَنكُمْ وَعَلِمَ أَنَّ فِيكُمْ ضَعْفًۭا ۚ فَإِن يَكُن مِّنكُم مِّا۟ئَةٌۭ صَابِرَةٌۭ يَغْلِبُوا۟ مِا۟ئَتَيْنِ ۚ وَإِن يَكُن مِّنكُمْ أَلْفٌۭ يَغْلِبُوٓا۟ أَلْفَيْنِ بِإِذْنِ ٱللَّهِ ۗ وَٱللَّهُ مَعَ ٱلصَّٰبِرِينَ', 'الن خفف الله عنكم وعلم أن فيكم ضعفا  فإن يكن منكم مائة صابرة يغلبوا مائتين  وإن يكن منكم ألف يغلبوا ألفين بإذن الله  والله مع الصبرين', NULL, 185, 'local:hafs-text.json'),
  ('hafs-8-67', 'hafs', 8, 67, 'مَا كَانَ لِنَبِىٍّ أَن يَكُونَ لَهُۥٓ أَسْرَىٰ حَتَّىٰ يُثْخِنَ فِى ٱلْأَرْضِ ۚ تُرِيدُونَ عَرَضَ ٱلدُّنْيَا وَٱللَّهُ يُرِيدُ ٱلْءَاخِرَةَ ۗ وَٱللَّهُ عَزِيزٌ حَكِيمٌۭ', 'ما كان لنبى أن يكون له أسرى حتى يثخن فى الأرض  تريدون عرض الدنيا والله يريد الءاخرة  والله عزيز حكيم', NULL, 185, 'local:hafs-text.json'),
  ('hafs-8-68', 'hafs', 8, 68, 'لَّوْلَا كِتَٰبٌۭ مِّنَ ٱللَّهِ سَبَقَ لَمَسَّكُمْ فِيمَآ أَخَذْتُمْ عَذَابٌ عَظِيمٌۭ', 'لولا كتب من الله سبق لمسكم فيما أخذتم عذاب عظيم', NULL, 185, 'local:hafs-text.json'),
  ('hafs-8-69', 'hafs', 8, 69, 'فَكُلُوا۟ مِمَّا غَنِمْتُمْ حَلَٰلًۭا طَيِّبًۭا ۚ وَٱتَّقُوا۟ ٱللَّهَ ۚ إِنَّ ٱللَّهَ غَفُورٌۭ رَّحِيمٌۭ', 'فكلوا مما غنمتم حللا طيبا  واتقوا الله  إن الله غفور رحيم', NULL, 185, 'local:hafs-text.json'),
  ('hafs-8-70', 'hafs', 8, 70, 'يَٰٓأَيُّهَا ٱلنَّبِىُّ قُل لِّمَن فِىٓ أَيْدِيكُم مِّنَ ٱلْأَسْرَىٰٓ إِن يَعْلَمِ ٱللَّهُ فِى قُلُوبِكُمْ خَيْرًۭا يُؤْتِكُمْ خَيْرًۭا مِّمَّآ أُخِذَ مِنكُمْ وَيَغْفِرْ لَكُمْ ۗ وَٱللَّهُ غَفُورٌۭ رَّحِيمٌۭ', 'يأيها النبى قل لمن فى أيديكم من الأسرى إن يعلم الله فى قلوبكم خيرا يؤتكم خيرا مما أخذ منكم ويغفر لكم  والله غفور رحيم', NULL, 186, 'local:hafs-text.json'),
  ('hafs-8-71', 'hafs', 8, 71, 'وَإِن يُرِيدُوا۟ خِيَانَتَكَ فَقَدْ خَانُوا۟ ٱللَّهَ مِن قَبْلُ فَأَمْكَنَ مِنْهُمْ ۗ وَٱللَّهُ عَلِيمٌ حَكِيمٌ', 'وإن يريدوا خيانتك فقد خانوا الله من قبل فأمكن منهم  والله عليم حكيم', NULL, 186, 'local:hafs-text.json'),
  ('hafs-8-72', 'hafs', 8, 72, 'إِنَّ ٱلَّذِينَ ءَامَنُوا۟ وَهَاجَرُوا۟ وَجَٰهَدُوا۟ بِأَمْوَٰلِهِمْ وَأَنفُسِهِمْ فِى سَبِيلِ ٱللَّهِ وَٱلَّذِينَ ءَاوَوا۟ وَّنَصَرُوٓا۟ أُو۟لَٰٓئِكَ بَعْضُهُمْ أَوْلِيَآءُ بَعْضٍۢ ۚ وَٱلَّذِينَ ءَامَنُوا۟ وَلَمْ يُهَاجِرُوا۟ مَا لَكُم مِّن وَلَٰيَتِهِم مِّن شَىْءٍ حَتَّىٰ يُهَاجِرُوا۟ ۚ وَإِنِ ٱسْتَنصَرُوكُمْ فِى ٱلدِّينِ فَعَلَيْكُمُ ٱلنَّصْرُ إِلَّا عَلَىٰ قَوْمٍۭ بَيْنَكُمْ وَبَيْنَهُم مِّيثَٰقٌۭ ۗ وَٱللَّهُ بِمَا تَعْمَلُونَ بَصِيرٌۭ', 'إن الذين ءامنوا وهاجروا وجهدوا بأمولهم وأنفسهم فى سبيل الله والذين ءاووا ونصروا أولئك بعضهم أولياء بعض  والذين ءامنوا ولم يهاجروا ما لكم من وليتهم من شىء حتى يهاجروا  وإن استنصروكم فى الدين فعليكم النصر إلا على قوم بينكم وبينهم ميثق  والله بما تعملون بصير', NULL, 186, 'local:hafs-text.json'),
  ('hafs-8-73', 'hafs', 8, 73, 'وَٱلَّذِينَ كَفَرُوا۟ بَعْضُهُمْ أَوْلِيَآءُ بَعْضٍ ۚ إِلَّا تَفْعَلُوهُ تَكُن فِتْنَةٌۭ فِى ٱلْأَرْضِ وَفَسَادٌۭ كَبِيرٌۭ', 'والذين كفروا بعضهم أولياء بعض  إلا تفعلوه تكن فتنة فى الأرض وفساد كبير', NULL, 186, 'local:hafs-text.json'),
  ('hafs-8-74', 'hafs', 8, 74, 'وَٱلَّذِينَ ءَامَنُوا۟ وَهَاجَرُوا۟ وَجَٰهَدُوا۟ فِى سَبِيلِ ٱللَّهِ وَٱلَّذِينَ ءَاوَوا۟ وَّنَصَرُوٓا۟ أُو۟لَٰٓئِكَ هُمُ ٱلْمُؤْمِنُونَ حَقًّۭا ۚ لَّهُم مَّغْفِرَةٌۭ وَرِزْقٌۭ كَرِيمٌۭ', 'والذين ءامنوا وهاجروا وجهدوا فى سبيل الله والذين ءاووا ونصروا أولئك هم المؤمنون حقا  لهم مغفرة ورزق كريم', NULL, 186, 'local:hafs-text.json'),
  ('hafs-8-75', 'hafs', 8, 75, 'وَٱلَّذِينَ ءَامَنُوا۟ مِنۢ بَعْدُ وَهَاجَرُوا۟ وَجَٰهَدُوا۟ مَعَكُمْ فَأُو۟لَٰٓئِكَ مِنكُمْ ۚ وَأُو۟لُوا۟ ٱلْأَرْحَامِ بَعْضُهُمْ أَوْلَىٰ بِبَعْضٍۢ فِى كِتَٰبِ ٱللَّهِ ۗ إِنَّ ٱللَّهَ بِكُلِّ شَىْءٍ عَلِيمٌۢ', 'والذين ءامنوا من بعد وهاجروا وجهدوا معكم فأولئك منكم  وأولوا الأرحام بعضهم أولى ببعض فى كتب الله  إن الله بكل شىء عليم', NULL, 186, 'local:hafs-text.json'),
  ('hafs-9-1', 'hafs', 9, 1, 'بَرَآءَةٌۭ مِّنَ ٱللَّهِ وَرَسُولِهِۦٓ إِلَى ٱلَّذِينَ عَٰهَدتُّم مِّنَ ٱلْمُشْرِكِينَ', 'براءة من الله ورسوله إلى الذين عهدتم من المشركين', NULL, 187, 'local:hafs-text.json'),
  ('hafs-9-2', 'hafs', 9, 2, 'فَسِيحُوا۟ فِى ٱلْأَرْضِ أَرْبَعَةَ أَشْهُرٍۢ وَٱعْلَمُوٓا۟ أَنَّكُمْ غَيْرُ مُعْجِزِى ٱللَّهِ ۙ وَأَنَّ ٱللَّهَ مُخْزِى ٱلْكَٰفِرِينَ', 'فسيحوا فى الأرض أربعة أشهر واعلموا أنكم غير معجزى الله  وأن الله مخزى الكفرين', NULL, 187, 'local:hafs-text.json'),
  ('hafs-9-3', 'hafs', 9, 3, 'وَأَذَٰنٌۭ مِّنَ ٱللَّهِ وَرَسُولِهِۦٓ إِلَى ٱلنَّاسِ يَوْمَ ٱلْحَجِّ ٱلْأَكْبَرِ أَنَّ ٱللَّهَ بَرِىٓءٌۭ مِّنَ ٱلْمُشْرِكِينَ ۙ وَرَسُولُهُۥ ۚ فَإِن تُبْتُمْ فَهُوَ خَيْرٌۭ لَّكُمْ ۖ وَإِن تَوَلَّيْتُمْ فَٱعْلَمُوٓا۟ أَنَّكُمْ غَيْرُ مُعْجِزِى ٱللَّهِ ۗ وَبَشِّرِ ٱلَّذِينَ كَفَرُوا۟ بِعَذَابٍ أَلِيمٍ', 'وأذن من الله ورسوله إلى الناس يوم الحج الأكبر أن الله برىء من المشركين  ورسوله  فإن تبتم فهو خير لكم  وإن توليتم فاعلموا أنكم غير معجزى الله  وبشر الذين كفروا بعذاب أليم', NULL, 187, 'local:hafs-text.json'),
  ('hafs-9-4', 'hafs', 9, 4, 'إِلَّا ٱلَّذِينَ عَٰهَدتُّم مِّنَ ٱلْمُشْرِكِينَ ثُمَّ لَمْ يَنقُصُوكُمْ شَيْـًۭٔا وَلَمْ يُظَٰهِرُوا۟ عَلَيْكُمْ أَحَدًۭا فَأَتِمُّوٓا۟ إِلَيْهِمْ عَهْدَهُمْ إِلَىٰ مُدَّتِهِمْ ۚ إِنَّ ٱللَّهَ يُحِبُّ ٱلْمُتَّقِينَ', 'إلا الذين عهدتم من المشركين ثم لم ينقصوكم شيا ولم يظهروا عليكم أحدا فأتموا إليهم عهدهم إلى مدتهم  إن الله يحب المتقين', NULL, 187, 'local:hafs-text.json'),
  ('hafs-9-5', 'hafs', 9, 5, 'فَإِذَا ٱنسَلَخَ ٱلْأَشْهُرُ ٱلْحُرُمُ فَٱقْتُلُوا۟ ٱلْمُشْرِكِينَ حَيْثُ وَجَدتُّمُوهُمْ وَخُذُوهُمْ وَٱحْصُرُوهُمْ وَٱقْعُدُوا۟ لَهُمْ كُلَّ مَرْصَدٍۢ ۚ فَإِن تَابُوا۟ وَأَقَامُوا۟ ٱلصَّلَوٰةَ وَءَاتَوُا۟ ٱلزَّكَوٰةَ فَخَلُّوا۟ سَبِيلَهُمْ ۚ إِنَّ ٱللَّهَ غَفُورٌۭ رَّحِيمٌۭ', 'فإذا انسلخ الأشهر الحرم فاقتلوا المشركين حيث وجدتموهم وخذوهم واحصروهم واقعدوا لهم كل مرصد  فإن تابوا وأقاموا الصلوة وءاتوا الزكوة فخلوا سبيلهم  إن الله غفور رحيم', NULL, 187, 'local:hafs-text.json'),
  ('hafs-9-6', 'hafs', 9, 6, 'وَإِنْ أَحَدٌۭ مِّنَ ٱلْمُشْرِكِينَ ٱسْتَجَارَكَ فَأَجِرْهُ حَتَّىٰ يَسْمَعَ كَلَٰمَ ٱللَّهِ ثُمَّ أَبْلِغْهُ مَأْمَنَهُۥ ۚ ذَٰلِكَ بِأَنَّهُمْ قَوْمٌۭ لَّا يَعْلَمُونَ', 'وإن أحد من المشركين استجارك فأجره حتى يسمع كلم الله ثم أبلغه مأمنه  ذلك بأنهم قوم لا يعلمون', NULL, 187, 'local:hafs-text.json'),
  ('hafs-9-7', 'hafs', 9, 7, 'كَيْفَ يَكُونُ لِلْمُشْرِكِينَ عَهْدٌ عِندَ ٱللَّهِ وَعِندَ رَسُولِهِۦٓ إِلَّا ٱلَّذِينَ عَٰهَدتُّمْ عِندَ ٱلْمَسْجِدِ ٱلْحَرَامِ ۖ فَمَا ٱسْتَقَٰمُوا۟ لَكُمْ فَٱسْتَقِيمُوا۟ لَهُمْ ۚ إِنَّ ٱللَّهَ يُحِبُّ ٱلْمُتَّقِينَ', 'كيف يكون للمشركين عهد عند الله وعند رسوله إلا الذين عهدتم عند المسجد الحرام  فما استقموا لكم فاستقيموا لهم  إن الله يحب المتقين', NULL, 188, 'local:hafs-text.json'),
  ('hafs-9-8', 'hafs', 9, 8, 'كَيْفَ وَإِن يَظْهَرُوا۟ عَلَيْكُمْ لَا يَرْقُبُوا۟ فِيكُمْ إِلًّۭا وَلَا ذِمَّةًۭ ۚ يُرْضُونَكُم بِأَفْوَٰهِهِمْ وَتَأْبَىٰ قُلُوبُهُمْ وَأَكْثَرُهُمْ فَٰسِقُونَ', 'كيف وإن يظهروا عليكم لا يرقبوا فيكم إلا ولا ذمة  يرضونكم بأفوههم وتأبى قلوبهم وأكثرهم فسقون', NULL, 188, 'local:hafs-text.json'),
  ('hafs-9-9', 'hafs', 9, 9, 'ٱشْتَرَوْا۟ بِـَٔايَٰتِ ٱللَّهِ ثَمَنًۭا قَلِيلًۭا فَصَدُّوا۟ عَن سَبِيلِهِۦٓ ۚ إِنَّهُمْ سَآءَ مَا كَانُوا۟ يَعْمَلُونَ', 'اشتروا بايت الله ثمنا قليلا فصدوا عن سبيله  إنهم ساء ما كانوا يعملون', NULL, 188, 'local:hafs-text.json'),
  ('hafs-9-10', 'hafs', 9, 10, 'لَا يَرْقُبُونَ فِى مُؤْمِنٍ إِلًّۭا وَلَا ذِمَّةًۭ ۚ وَأُو۟لَٰٓئِكَ هُمُ ٱلْمُعْتَدُونَ', 'لا يرقبون فى مؤمن إلا ولا ذمة  وأولئك هم المعتدون', NULL, 188, 'local:hafs-text.json'),
  ('hafs-9-11', 'hafs', 9, 11, 'فَإِن تَابُوا۟ وَأَقَامُوا۟ ٱلصَّلَوٰةَ وَءَاتَوُا۟ ٱلزَّكَوٰةَ فَإِخْوَٰنُكُمْ فِى ٱلدِّينِ ۗ وَنُفَصِّلُ ٱلْءَايَٰتِ لِقَوْمٍۢ يَعْلَمُونَ', 'فإن تابوا وأقاموا الصلوة وءاتوا الزكوة فإخونكم فى الدين  ونفصل الءايت لقوم يعلمون', NULL, 188, 'local:hafs-text.json'),
  ('hafs-9-12', 'hafs', 9, 12, 'وَإِن نَّكَثُوٓا۟ أَيْمَٰنَهُم مِّنۢ بَعْدِ عَهْدِهِمْ وَطَعَنُوا۟ فِى دِينِكُمْ فَقَٰتِلُوٓا۟ أَئِمَّةَ ٱلْكُفْرِ ۙ إِنَّهُمْ لَآ أَيْمَٰنَ لَهُمْ لَعَلَّهُمْ يَنتَهُونَ', 'وإن نكثوا أيمنهم من بعد عهدهم وطعنوا فى دينكم فقتلوا أئمة الكفر  إنهم لا أيمن لهم لعلهم ينتهون', NULL, 188, 'local:hafs-text.json'),
  ('hafs-9-13', 'hafs', 9, 13, 'أَلَا تُقَٰتِلُونَ قَوْمًۭا نَّكَثُوٓا۟ أَيْمَٰنَهُمْ وَهَمُّوا۟ بِإِخْرَاجِ ٱلرَّسُولِ وَهُم بَدَءُوكُمْ أَوَّلَ مَرَّةٍ ۚ أَتَخْشَوْنَهُمْ ۚ فَٱللَّهُ أَحَقُّ أَن تَخْشَوْهُ إِن كُنتُم مُّؤْمِنِينَ', 'ألا تقتلون قوما نكثوا أيمنهم وهموا بإخراج الرسول وهم بدءوكم أول مرة  أتخشونهم  فالله أحق أن تخشوه إن كنتم مؤمنين', NULL, 188, 'local:hafs-text.json'),
  ('hafs-9-14', 'hafs', 9, 14, 'قَٰتِلُوهُمْ يُعَذِّبْهُمُ ٱللَّهُ بِأَيْدِيكُمْ وَيُخْزِهِمْ وَيَنصُرْكُمْ عَلَيْهِمْ وَيَشْفِ صُدُورَ قَوْمٍۢ مُّؤْمِنِينَ', 'قتلوهم يعذبهم الله بأيديكم ويخزهم وينصركم عليهم ويشف صدور قوم مؤمنين', NULL, 189, 'local:hafs-text.json'),
  ('hafs-9-15', 'hafs', 9, 15, 'وَيُذْهِبْ غَيْظَ قُلُوبِهِمْ ۗ وَيَتُوبُ ٱللَّهُ عَلَىٰ مَن يَشَآءُ ۗ وَٱللَّهُ عَلِيمٌ حَكِيمٌ', 'ويذهب غيظ قلوبهم  ويتوب الله على من يشاء  والله عليم حكيم', NULL, 189, 'local:hafs-text.json'),
  ('hafs-9-16', 'hafs', 9, 16, 'أَمْ حَسِبْتُمْ أَن تُتْرَكُوا۟ وَلَمَّا يَعْلَمِ ٱللَّهُ ٱلَّذِينَ جَٰهَدُوا۟ مِنكُمْ وَلَمْ يَتَّخِذُوا۟ مِن دُونِ ٱللَّهِ وَلَا رَسُولِهِۦ وَلَا ٱلْمُؤْمِنِينَ وَلِيجَةًۭ ۚ وَٱللَّهُ خَبِيرٌۢ بِمَا تَعْمَلُونَ', 'أم حسبتم أن تتركوا ولما يعلم الله الذين جهدوا منكم ولم يتخذوا من دون الله ولا رسوله ولا المؤمنين وليجة  والله خبير بما تعملون', NULL, 189, 'local:hafs-text.json'),
  ('hafs-9-17', 'hafs', 9, 17, 'مَا كَانَ لِلْمُشْرِكِينَ أَن يَعْمُرُوا۟ مَسَٰجِدَ ٱللَّهِ شَٰهِدِينَ عَلَىٰٓ أَنفُسِهِم بِٱلْكُفْرِ ۚ أُو۟لَٰٓئِكَ حَبِطَتْ أَعْمَٰلُهُمْ وَفِى ٱلنَّارِ هُمْ خَٰلِدُونَ', 'ما كان للمشركين أن يعمروا مسجد الله شهدين على أنفسهم بالكفر  أولئك حبطت أعملهم وفى النار هم خلدون', NULL, 189, 'local:hafs-text.json'),
  ('hafs-9-18', 'hafs', 9, 18, 'إِنَّمَا يَعْمُرُ مَسَٰجِدَ ٱللَّهِ مَنْ ءَامَنَ بِٱللَّهِ وَٱلْيَوْمِ ٱلْءَاخِرِ وَأَقَامَ ٱلصَّلَوٰةَ وَءَاتَى ٱلزَّكَوٰةَ وَلَمْ يَخْشَ إِلَّا ٱللَّهَ ۖ فَعَسَىٰٓ أُو۟لَٰٓئِكَ أَن يَكُونُوا۟ مِنَ ٱلْمُهْتَدِينَ', 'إنما يعمر مسجد الله من ءامن بالله واليوم الءاخر وأقام الصلوة وءاتى الزكوة ولم يخش إلا الله  فعسى أولئك أن يكونوا من المهتدين', NULL, 189, 'local:hafs-text.json'),
  ('hafs-9-19', 'hafs', 9, 19, '۞ أَجَعَلْتُمْ سِقَايَةَ ٱلْحَآجِّ وَعِمَارَةَ ٱلْمَسْجِدِ ٱلْحَرَامِ كَمَنْ ءَامَنَ بِٱللَّهِ وَٱلْيَوْمِ ٱلْءَاخِرِ وَجَٰهَدَ فِى سَبِيلِ ٱللَّهِ ۚ لَا يَسْتَوُۥنَ عِندَ ٱللَّهِ ۗ وَٱللَّهُ لَا يَهْدِى ٱلْقَوْمَ ٱلظَّٰلِمِينَ', 'أجعلتم سقاية الحاج وعمارة المسجد الحرام كمن ءامن بالله واليوم الءاخر وجهد فى سبيل الله  لا يستون عند الله  والله لا يهدى القوم الظلمين', NULL, 189, 'local:hafs-text.json'),
  ('hafs-9-20', 'hafs', 9, 20, 'ٱلَّذِينَ ءَامَنُوا۟ وَهَاجَرُوا۟ وَجَٰهَدُوا۟ فِى سَبِيلِ ٱللَّهِ بِأَمْوَٰلِهِمْ وَأَنفُسِهِمْ أَعْظَمُ دَرَجَةً عِندَ ٱللَّهِ ۚ وَأُو۟لَٰٓئِكَ هُمُ ٱلْفَآئِزُونَ', 'الذين ءامنوا وهاجروا وجهدوا فى سبيل الله بأمولهم وأنفسهم أعظم درجة عند الله  وأولئك هم الفائزون', NULL, 189, 'local:hafs-text.json'),
  ('hafs-9-21', 'hafs', 9, 21, 'يُبَشِّرُهُمْ رَبُّهُم بِرَحْمَةٍۢ مِّنْهُ وَرِضْوَٰنٍۢ وَجَنَّٰتٍۢ لَّهُمْ فِيهَا نَعِيمٌۭ مُّقِيمٌ', 'يبشرهم ربهم برحمة منه ورضون وجنت لهم فيها نعيم مقيم', NULL, 190, 'local:hafs-text.json'),
  ('hafs-9-22', 'hafs', 9, 22, 'خَٰلِدِينَ فِيهَآ أَبَدًا ۚ إِنَّ ٱللَّهَ عِندَهُۥٓ أَجْرٌ عَظِيمٌۭ', 'خلدين فيها أبدا  إن الله عنده أجر عظيم', NULL, 190, 'local:hafs-text.json'),
  ('hafs-9-23', 'hafs', 9, 23, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَتَّخِذُوٓا۟ ءَابَآءَكُمْ وَإِخْوَٰنَكُمْ أَوْلِيَآءَ إِنِ ٱسْتَحَبُّوا۟ ٱلْكُفْرَ عَلَى ٱلْإِيمَٰنِ ۚ وَمَن يَتَوَلَّهُم مِّنكُمْ فَأُو۟لَٰٓئِكَ هُمُ ٱلظَّٰلِمُونَ', 'يأيها الذين ءامنوا لا تتخذوا ءاباءكم وإخونكم أولياء إن استحبوا الكفر على الإيمن  ومن يتولهم منكم فأولئك هم الظلمون', NULL, 190, 'local:hafs-text.json'),
  ('hafs-9-24', 'hafs', 9, 24, 'قُلْ إِن كَانَ ءَابَآؤُكُمْ وَأَبْنَآؤُكُمْ وَإِخْوَٰنُكُمْ وَأَزْوَٰجُكُمْ وَعَشِيرَتُكُمْ وَأَمْوَٰلٌ ٱقْتَرَفْتُمُوهَا وَتِجَٰرَةٌۭ تَخْشَوْنَ كَسَادَهَا وَمَسَٰكِنُ تَرْضَوْنَهَآ أَحَبَّ إِلَيْكُم مِّنَ ٱللَّهِ وَرَسُولِهِۦ وَجِهَادٍۢ فِى سَبِيلِهِۦ فَتَرَبَّصُوا۟ حَتَّىٰ يَأْتِىَ ٱللَّهُ بِأَمْرِهِۦ ۗ وَٱللَّهُ لَا يَهْدِى ٱلْقَوْمَ ٱلْفَٰسِقِينَ', 'قل إن كان ءاباؤكم وأبناؤكم وإخونكم وأزوجكم وعشيرتكم وأمول اقترفتموها وتجرة تخشون كسادها ومسكن ترضونها أحب إليكم من الله ورسوله وجهاد فى سبيله فتربصوا حتى يأتى الله بأمره  والله لا يهدى القوم الفسقين', NULL, 190, 'local:hafs-text.json'),
  ('hafs-9-25', 'hafs', 9, 25, 'لَقَدْ نَصَرَكُمُ ٱللَّهُ فِى مَوَاطِنَ كَثِيرَةٍۢ ۙ وَيَوْمَ حُنَيْنٍ ۙ إِذْ أَعْجَبَتْكُمْ كَثْرَتُكُمْ فَلَمْ تُغْنِ عَنكُمْ شَيْـًۭٔا وَضَاقَتْ عَلَيْكُمُ ٱلْأَرْضُ بِمَا رَحُبَتْ ثُمَّ وَلَّيْتُم مُّدْبِرِينَ', 'لقد نصركم الله فى مواطن كثيرة  ويوم حنين  إذ أعجبتكم كثرتكم فلم تغن عنكم شيا وضاقت عليكم الأرض بما رحبت ثم وليتم مدبرين', NULL, 190, 'local:hafs-text.json'),
  ('hafs-9-26', 'hafs', 9, 26, 'ثُمَّ أَنزَلَ ٱللَّهُ سَكِينَتَهُۥ عَلَىٰ رَسُولِهِۦ وَعَلَى ٱلْمُؤْمِنِينَ وَأَنزَلَ جُنُودًۭا لَّمْ تَرَوْهَا وَعَذَّبَ ٱلَّذِينَ كَفَرُوا۟ ۚ وَذَٰلِكَ جَزَآءُ ٱلْكَٰفِرِينَ', 'ثم أنزل الله سكينته على رسوله وعلى المؤمنين وأنزل جنودا لم تروها وعذب الذين كفروا  وذلك جزاء الكفرين', NULL, 190, 'local:hafs-text.json'),
  ('hafs-9-27', 'hafs', 9, 27, 'ثُمَّ يَتُوبُ ٱللَّهُ مِنۢ بَعْدِ ذَٰلِكَ عَلَىٰ مَن يَشَآءُ ۗ وَٱللَّهُ غَفُورٌۭ رَّحِيمٌۭ', 'ثم يتوب الله من بعد ذلك على من يشاء  والله غفور رحيم', NULL, 191, 'local:hafs-text.json'),
  ('hafs-9-28', 'hafs', 9, 28, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِنَّمَا ٱلْمُشْرِكُونَ نَجَسٌۭ فَلَا يَقْرَبُوا۟ ٱلْمَسْجِدَ ٱلْحَرَامَ بَعْدَ عَامِهِمْ هَٰذَا ۚ وَإِنْ خِفْتُمْ عَيْلَةًۭ فَسَوْفَ يُغْنِيكُمُ ٱللَّهُ مِن فَضْلِهِۦٓ إِن شَآءَ ۚ إِنَّ ٱللَّهَ عَلِيمٌ حَكِيمٌۭ', 'يأيها الذين ءامنوا إنما المشركون نجس فلا يقربوا المسجد الحرام بعد عامهم هذا  وإن خفتم عيلة فسوف يغنيكم الله من فضله إن شاء  إن الله عليم حكيم', NULL, 191, 'local:hafs-text.json'),
  ('hafs-9-29', 'hafs', 9, 29, 'قَٰتِلُوا۟ ٱلَّذِينَ لَا يُؤْمِنُونَ بِٱللَّهِ وَلَا بِٱلْيَوْمِ ٱلْءَاخِرِ وَلَا يُحَرِّمُونَ مَا حَرَّمَ ٱللَّهُ وَرَسُولُهُۥ وَلَا يَدِينُونَ دِينَ ٱلْحَقِّ مِنَ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَٰبَ حَتَّىٰ يُعْطُوا۟ ٱلْجِزْيَةَ عَن يَدٍۢ وَهُمْ صَٰغِرُونَ', 'قتلوا الذين لا يؤمنون بالله ولا باليوم الءاخر ولا يحرمون ما حرم الله ورسوله ولا يدينون دين الحق من الذين أوتوا الكتب حتى يعطوا الجزية عن يد وهم صغرون', NULL, 191, 'local:hafs-text.json'),
  ('hafs-9-30', 'hafs', 9, 30, 'وَقَالَتِ ٱلْيَهُودُ عُزَيْرٌ ٱبْنُ ٱللَّهِ وَقَالَتِ ٱلنَّصَٰرَى ٱلْمَسِيحُ ٱبْنُ ٱللَّهِ ۖ ذَٰلِكَ قَوْلُهُم بِأَفْوَٰهِهِمْ ۖ يُضَٰهِـُٔونَ قَوْلَ ٱلَّذِينَ كَفَرُوا۟ مِن قَبْلُ ۚ قَٰتَلَهُمُ ٱللَّهُ ۚ أَنَّىٰ يُؤْفَكُونَ', 'وقالت اليهود عزير ابن الله وقالت النصرى المسيح ابن الله  ذلك قولهم بأفوههم  يضهون قول الذين كفروا من قبل  قتلهم الله  أنى يؤفكون', NULL, 191, 'local:hafs-text.json'),
  ('hafs-9-31', 'hafs', 9, 31, 'ٱتَّخَذُوٓا۟ أَحْبَارَهُمْ وَرُهْبَٰنَهُمْ أَرْبَابًۭا مِّن دُونِ ٱللَّهِ وَٱلْمَسِيحَ ٱبْنَ مَرْيَمَ وَمَآ أُمِرُوٓا۟ إِلَّا لِيَعْبُدُوٓا۟ إِلَٰهًۭا وَٰحِدًۭا ۖ لَّآ إِلَٰهَ إِلَّا هُوَ ۚ سُبْحَٰنَهُۥ عَمَّا يُشْرِكُونَ', 'اتخذوا أحبارهم ورهبنهم أربابا من دون الله والمسيح ابن مريم وما أمروا إلا ليعبدوا إلها وحدا  لا إله إلا هو  سبحنه عما يشركون', NULL, 191, 'local:hafs-text.json'),
  ('hafs-9-32', 'hafs', 9, 32, 'يُرِيدُونَ أَن يُطْفِـُٔوا۟ نُورَ ٱللَّهِ بِأَفْوَٰهِهِمْ وَيَأْبَى ٱللَّهُ إِلَّآ أَن يُتِمَّ نُورَهُۥ وَلَوْ كَرِهَ ٱلْكَٰفِرُونَ', 'يريدون أن يطفوا نور الله بأفوههم ويأبى الله إلا أن يتم نوره ولو كره الكفرون', NULL, 192, 'local:hafs-text.json'),
  ('hafs-9-33', 'hafs', 9, 33, 'هُوَ ٱلَّذِىٓ أَرْسَلَ رَسُولَهُۥ بِٱلْهُدَىٰ وَدِينِ ٱلْحَقِّ لِيُظْهِرَهُۥ عَلَى ٱلدِّينِ كُلِّهِۦ وَلَوْ كَرِهَ ٱلْمُشْرِكُونَ', 'هو الذى أرسل رسوله بالهدى ودين الحق ليظهره على الدين كله ولو كره المشركون', NULL, 192, 'local:hafs-text.json'),
  ('hafs-9-34', 'hafs', 9, 34, '۞ يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِنَّ كَثِيرًۭا مِّنَ ٱلْأَحْبَارِ وَٱلرُّهْبَانِ لَيَأْكُلُونَ أَمْوَٰلَ ٱلنَّاسِ بِٱلْبَٰطِلِ وَيَصُدُّونَ عَن سَبِيلِ ٱللَّهِ ۗ وَٱلَّذِينَ يَكْنِزُونَ ٱلذَّهَبَ وَٱلْفِضَّةَ وَلَا يُنفِقُونَهَا فِى سَبِيلِ ٱللَّهِ فَبَشِّرْهُم بِعَذَابٍ أَلِيمٍۢ', 'يأيها الذين ءامنوا إن كثيرا من الأحبار والرهبان ليأكلون أمول الناس بالبطل ويصدون عن سبيل الله  والذين يكنزون الذهب والفضة ولا ينفقونها فى سبيل الله فبشرهم بعذاب أليم', NULL, 192, 'local:hafs-text.json'),
  ('hafs-9-35', 'hafs', 9, 35, 'يَوْمَ يُحْمَىٰ عَلَيْهَا فِى نَارِ جَهَنَّمَ فَتُكْوَىٰ بِهَا جِبَاهُهُمْ وَجُنُوبُهُمْ وَظُهُورُهُمْ ۖ هَٰذَا مَا كَنَزْتُمْ لِأَنفُسِكُمْ فَذُوقُوا۟ مَا كُنتُمْ تَكْنِزُونَ', 'يوم يحمى عليها فى نار جهنم فتكوى بها جباههم وجنوبهم وظهورهم  هذا ما كنزتم لأنفسكم فذوقوا ما كنتم تكنزون', NULL, 192, 'local:hafs-text.json'),
  ('hafs-9-36', 'hafs', 9, 36, 'إِنَّ عِدَّةَ ٱلشُّهُورِ عِندَ ٱللَّهِ ٱثْنَا عَشَرَ شَهْرًۭا فِى كِتَٰبِ ٱللَّهِ يَوْمَ خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ مِنْهَآ أَرْبَعَةٌ حُرُمٌۭ ۚ ذَٰلِكَ ٱلدِّينُ ٱلْقَيِّمُ ۚ فَلَا تَظْلِمُوا۟ فِيهِنَّ أَنفُسَكُمْ ۚ وَقَٰتِلُوا۟ ٱلْمُشْرِكِينَ كَآفَّةًۭ كَمَا يُقَٰتِلُونَكُمْ كَآفَّةًۭ ۚ وَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ مَعَ ٱلْمُتَّقِينَ', 'إن عدة الشهور عند الله اثنا عشر شهرا فى كتب الله يوم خلق السموت والأرض منها أربعة حرم  ذلك الدين القيم  فلا تظلموا فيهن أنفسكم  وقتلوا المشركين كافة كما يقتلونكم كافة  واعلموا أن الله مع المتقين', NULL, 192, 'local:hafs-text.json'),
  ('hafs-9-37', 'hafs', 9, 37, 'إِنَّمَا ٱلنَّسِىٓءُ زِيَادَةٌۭ فِى ٱلْكُفْرِ ۖ يُضَلُّ بِهِ ٱلَّذِينَ كَفَرُوا۟ يُحِلُّونَهُۥ عَامًۭا وَيُحَرِّمُونَهُۥ عَامًۭا لِّيُوَاطِـُٔوا۟ عِدَّةَ مَا حَرَّمَ ٱللَّهُ فَيُحِلُّوا۟ مَا حَرَّمَ ٱللَّهُ ۚ زُيِّنَ لَهُمْ سُوٓءُ أَعْمَٰلِهِمْ ۗ وَٱللَّهُ لَا يَهْدِى ٱلْقَوْمَ ٱلْكَٰفِرِينَ', 'إنما النسىء زيادة فى الكفر  يضل به الذين كفروا يحلونه عاما ويحرمونه عاما ليواطوا عدة ما حرم الله فيحلوا ما حرم الله  زين لهم سوء أعملهم  والله لا يهدى القوم الكفرين', NULL, 193, 'local:hafs-text.json'),
  ('hafs-9-38', 'hafs', 9, 38, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ مَا لَكُمْ إِذَا قِيلَ لَكُمُ ٱنفِرُوا۟ فِى سَبِيلِ ٱللَّهِ ٱثَّاقَلْتُمْ إِلَى ٱلْأَرْضِ ۚ أَرَضِيتُم بِٱلْحَيَوٰةِ ٱلدُّنْيَا مِنَ ٱلْءَاخِرَةِ ۚ فَمَا مَتَٰعُ ٱلْحَيَوٰةِ ٱلدُّنْيَا فِى ٱلْءَاخِرَةِ إِلَّا قَلِيلٌ', 'يأيها الذين ءامنوا ما لكم إذا قيل لكم انفروا فى سبيل الله اثاقلتم إلى الأرض  أرضيتم بالحيوة الدنيا من الءاخرة  فما متع الحيوة الدنيا فى الءاخرة إلا قليل', NULL, 193, 'local:hafs-text.json'),
  ('hafs-9-39', 'hafs', 9, 39, 'إِلَّا تَنفِرُوا۟ يُعَذِّبْكُمْ عَذَابًا أَلِيمًۭا وَيَسْتَبْدِلْ قَوْمًا غَيْرَكُمْ وَلَا تَضُرُّوهُ شَيْـًۭٔا ۗ وَٱللَّهُ عَلَىٰ كُلِّ شَىْءٍۢ قَدِيرٌ', 'إلا تنفروا يعذبكم عذابا أليما ويستبدل قوما غيركم ولا تضروه شيا  والله على كل شىء قدير', NULL, 193, 'local:hafs-text.json'),
  ('hafs-9-40', 'hafs', 9, 40, 'إِلَّا تَنصُرُوهُ فَقَدْ نَصَرَهُ ٱللَّهُ إِذْ أَخْرَجَهُ ٱلَّذِينَ كَفَرُوا۟ ثَانِىَ ٱثْنَيْنِ إِذْ هُمَا فِى ٱلْغَارِ إِذْ يَقُولُ لِصَٰحِبِهِۦ لَا تَحْزَنْ إِنَّ ٱللَّهَ مَعَنَا ۖ فَأَنزَلَ ٱللَّهُ سَكِينَتَهُۥ عَلَيْهِ وَأَيَّدَهُۥ بِجُنُودٍۢ لَّمْ تَرَوْهَا وَجَعَلَ كَلِمَةَ ٱلَّذِينَ كَفَرُوا۟ ٱلسُّفْلَىٰ ۗ وَكَلِمَةُ ٱللَّهِ هِىَ ٱلْعُلْيَا ۗ وَٱللَّهُ عَزِيزٌ حَكِيمٌ', 'إلا تنصروه فقد نصره الله إذ أخرجه الذين كفروا ثانى اثنين إذ هما فى الغار إذ يقول لصحبه لا تحزن إن الله معنا  فأنزل الله سكينته عليه وأيده بجنود لم تروها وجعل كلمة الذين كفروا السفلى  وكلمة الله هى العليا  والله عزيز حكيم', NULL, 193, 'local:hafs-text.json'),
  ('hafs-9-41', 'hafs', 9, 41, 'ٱنفِرُوا۟ خِفَافًۭا وَثِقَالًۭا وَجَٰهِدُوا۟ بِأَمْوَٰلِكُمْ وَأَنفُسِكُمْ فِى سَبِيلِ ٱللَّهِ ۚ ذَٰلِكُمْ خَيْرٌۭ لَّكُمْ إِن كُنتُمْ تَعْلَمُونَ', 'انفروا خفافا وثقالا وجهدوا بأمولكم وأنفسكم فى سبيل الله  ذلكم خير لكم إن كنتم تعلمون', NULL, 194, 'local:hafs-text.json'),
  ('hafs-9-42', 'hafs', 9, 42, 'لَوْ كَانَ عَرَضًۭا قَرِيبًۭا وَسَفَرًۭا قَاصِدًۭا لَّٱتَّبَعُوكَ وَلَٰكِنۢ بَعُدَتْ عَلَيْهِمُ ٱلشُّقَّةُ ۚ وَسَيَحْلِفُونَ بِٱللَّهِ لَوِ ٱسْتَطَعْنَا لَخَرَجْنَا مَعَكُمْ يُهْلِكُونَ أَنفُسَهُمْ وَٱللَّهُ يَعْلَمُ إِنَّهُمْ لَكَٰذِبُونَ', 'لو كان عرضا قريبا وسفرا قاصدا لاتبعوك ولكن بعدت عليهم الشقة  وسيحلفون بالله لو استطعنا لخرجنا معكم يهلكون أنفسهم والله يعلم إنهم لكذبون', NULL, 194, 'local:hafs-text.json'),
  ('hafs-9-43', 'hafs', 9, 43, 'عَفَا ٱللَّهُ عَنكَ لِمَ أَذِنتَ لَهُمْ حَتَّىٰ يَتَبَيَّنَ لَكَ ٱلَّذِينَ صَدَقُوا۟ وَتَعْلَمَ ٱلْكَٰذِبِينَ', 'عفا الله عنك لم أذنت لهم حتى يتبين لك الذين صدقوا وتعلم الكذبين', NULL, 194, 'local:hafs-text.json'),
  ('hafs-9-44', 'hafs', 9, 44, 'لَا يَسْتَـْٔذِنُكَ ٱلَّذِينَ يُؤْمِنُونَ بِٱللَّهِ وَٱلْيَوْمِ ٱلْءَاخِرِ أَن يُجَٰهِدُوا۟ بِأَمْوَٰلِهِمْ وَأَنفُسِهِمْ ۗ وَٱللَّهُ عَلِيمٌۢ بِٱلْمُتَّقِينَ', 'لا يستذنك الذين يؤمنون بالله واليوم الءاخر أن يجهدوا بأمولهم وأنفسهم  والله عليم بالمتقين', NULL, 194, 'local:hafs-text.json'),
  ('hafs-9-45', 'hafs', 9, 45, 'إِنَّمَا يَسْتَـْٔذِنُكَ ٱلَّذِينَ لَا يُؤْمِنُونَ بِٱللَّهِ وَٱلْيَوْمِ ٱلْءَاخِرِ وَٱرْتَابَتْ قُلُوبُهُمْ فَهُمْ فِى رَيْبِهِمْ يَتَرَدَّدُونَ', 'إنما يستذنك الذين لا يؤمنون بالله واليوم الءاخر وارتابت قلوبهم فهم فى ريبهم يترددون', NULL, 194, 'local:hafs-text.json'),
  ('hafs-9-46', 'hafs', 9, 46, '۞ وَلَوْ أَرَادُوا۟ ٱلْخُرُوجَ لَأَعَدُّوا۟ لَهُۥ عُدَّةًۭ وَلَٰكِن كَرِهَ ٱللَّهُ ٱنۢبِعَاثَهُمْ فَثَبَّطَهُمْ وَقِيلَ ٱقْعُدُوا۟ مَعَ ٱلْقَٰعِدِينَ', 'ولو أرادوا الخروج لأعدوا له عدة ولكن كره الله انبعاثهم فثبطهم وقيل اقعدوا مع القعدين', NULL, 194, 'local:hafs-text.json'),
  ('hafs-9-47', 'hafs', 9, 47, 'لَوْ خَرَجُوا۟ فِيكُم مَّا زَادُوكُمْ إِلَّا خَبَالًۭا وَلَأَوْضَعُوا۟ خِلَٰلَكُمْ يَبْغُونَكُمُ ٱلْفِتْنَةَ وَفِيكُمْ سَمَّٰعُونَ لَهُمْ ۗ وَٱللَّهُ عَلِيمٌۢ بِٱلظَّٰلِمِينَ', 'لو خرجوا فيكم ما زادوكم إلا خبالا ولأوضعوا خللكم يبغونكم الفتنة وفيكم سمعون لهم  والله عليم بالظلمين', NULL, 194, 'local:hafs-text.json'),
  ('hafs-9-48', 'hafs', 9, 48, 'لَقَدِ ٱبْتَغَوُا۟ ٱلْفِتْنَةَ مِن قَبْلُ وَقَلَّبُوا۟ لَكَ ٱلْأُمُورَ حَتَّىٰ جَآءَ ٱلْحَقُّ وَظَهَرَ أَمْرُ ٱللَّهِ وَهُمْ كَٰرِهُونَ', 'لقد ابتغوا الفتنة من قبل وقلبوا لك الأمور حتى جاء الحق وظهر أمر الله وهم كرهون', NULL, 195, 'local:hafs-text.json'),
  ('hafs-9-49', 'hafs', 9, 49, 'وَمِنْهُم مَّن يَقُولُ ٱئْذَن لِّى وَلَا تَفْتِنِّىٓ ۚ أَلَا فِى ٱلْفِتْنَةِ سَقَطُوا۟ ۗ وَإِنَّ جَهَنَّمَ لَمُحِيطَةٌۢ بِٱلْكَٰفِرِينَ', 'ومنهم من يقول ائذن لى ولا تفتنى  ألا فى الفتنة سقطوا  وإن جهنم لمحيطة بالكفرين', NULL, 195, 'local:hafs-text.json'),
  ('hafs-9-50', 'hafs', 9, 50, 'إِن تُصِبْكَ حَسَنَةٌۭ تَسُؤْهُمْ ۖ وَإِن تُصِبْكَ مُصِيبَةٌۭ يَقُولُوا۟ قَدْ أَخَذْنَآ أَمْرَنَا مِن قَبْلُ وَيَتَوَلَّوا۟ وَّهُمْ فَرِحُونَ', 'إن تصبك حسنة تسؤهم  وإن تصبك مصيبة يقولوا قد أخذنا أمرنا من قبل ويتولوا وهم فرحون', NULL, 195, 'local:hafs-text.json'),
  ('hafs-9-51', 'hafs', 9, 51, 'قُل لَّن يُصِيبَنَآ إِلَّا مَا كَتَبَ ٱللَّهُ لَنَا هُوَ مَوْلَىٰنَا ۚ وَعَلَى ٱللَّهِ فَلْيَتَوَكَّلِ ٱلْمُؤْمِنُونَ', 'قل لن يصيبنا إلا ما كتب الله لنا هو مولىنا  وعلى الله فليتوكل المؤمنون', NULL, 195, 'local:hafs-text.json'),
  ('hafs-9-52', 'hafs', 9, 52, 'قُلْ هَلْ تَرَبَّصُونَ بِنَآ إِلَّآ إِحْدَى ٱلْحُسْنَيَيْنِ ۖ وَنَحْنُ نَتَرَبَّصُ بِكُمْ أَن يُصِيبَكُمُ ٱللَّهُ بِعَذَابٍۢ مِّنْ عِندِهِۦٓ أَوْ بِأَيْدِينَا ۖ فَتَرَبَّصُوٓا۟ إِنَّا مَعَكُم مُّتَرَبِّصُونَ', 'قل هل تربصون بنا إلا إحدى الحسنيين  ونحن نتربص بكم أن يصيبكم الله بعذاب من عنده أو بأيدينا  فتربصوا إنا معكم متربصون', NULL, 195, 'local:hafs-text.json'),
  ('hafs-9-53', 'hafs', 9, 53, 'قُلْ أَنفِقُوا۟ طَوْعًا أَوْ كَرْهًۭا لَّن يُتَقَبَّلَ مِنكُمْ ۖ إِنَّكُمْ كُنتُمْ قَوْمًۭا فَٰسِقِينَ', 'قل أنفقوا طوعا أو كرها لن يتقبل منكم  إنكم كنتم قوما فسقين', NULL, 195, 'local:hafs-text.json'),
  ('hafs-9-54', 'hafs', 9, 54, 'وَمَا مَنَعَهُمْ أَن تُقْبَلَ مِنْهُمْ نَفَقَٰتُهُمْ إِلَّآ أَنَّهُمْ كَفَرُوا۟ بِٱللَّهِ وَبِرَسُولِهِۦ وَلَا يَأْتُونَ ٱلصَّلَوٰةَ إِلَّا وَهُمْ كُسَالَىٰ وَلَا يُنفِقُونَ إِلَّا وَهُمْ كَٰرِهُونَ', 'وما منعهم أن تقبل منهم نفقتهم إلا أنهم كفروا بالله وبرسوله ولا يأتون الصلوة إلا وهم كسالى ولا ينفقون إلا وهم كرهون', NULL, 195, 'local:hafs-text.json'),
  ('hafs-9-55', 'hafs', 9, 55, 'فَلَا تُعْجِبْكَ أَمْوَٰلُهُمْ وَلَآ أَوْلَٰدُهُمْ ۚ إِنَّمَا يُرِيدُ ٱللَّهُ لِيُعَذِّبَهُم بِهَا فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا وَتَزْهَقَ أَنفُسُهُمْ وَهُمْ كَٰفِرُونَ', 'فلا تعجبك أمولهم ولا أولدهم  إنما يريد الله ليعذبهم بها فى الحيوة الدنيا وتزهق أنفسهم وهم كفرون', NULL, 196, 'local:hafs-text.json'),
  ('hafs-9-56', 'hafs', 9, 56, 'وَيَحْلِفُونَ بِٱللَّهِ إِنَّهُمْ لَمِنكُمْ وَمَا هُم مِّنكُمْ وَلَٰكِنَّهُمْ قَوْمٌۭ يَفْرَقُونَ', 'ويحلفون بالله إنهم لمنكم وما هم منكم ولكنهم قوم يفرقون', NULL, 196, 'local:hafs-text.json'),
  ('hafs-9-57', 'hafs', 9, 57, 'لَوْ يَجِدُونَ مَلْجَـًٔا أَوْ مَغَٰرَٰتٍ أَوْ مُدَّخَلًۭا لَّوَلَّوْا۟ إِلَيْهِ وَهُمْ يَجْمَحُونَ', 'لو يجدون ملجا أو مغرت أو مدخلا لولوا إليه وهم يجمحون', NULL, 196, 'local:hafs-text.json'),
  ('hafs-9-58', 'hafs', 9, 58, 'وَمِنْهُم مَّن يَلْمِزُكَ فِى ٱلصَّدَقَٰتِ فَإِنْ أُعْطُوا۟ مِنْهَا رَضُوا۟ وَإِن لَّمْ يُعْطَوْا۟ مِنْهَآ إِذَا هُمْ يَسْخَطُونَ', 'ومنهم من يلمزك فى الصدقت فإن أعطوا منها رضوا وإن لم يعطوا منها إذا هم يسخطون', NULL, 196, 'local:hafs-text.json'),
  ('hafs-9-59', 'hafs', 9, 59, 'وَلَوْ أَنَّهُمْ رَضُوا۟ مَآ ءَاتَىٰهُمُ ٱللَّهُ وَرَسُولُهُۥ وَقَالُوا۟ حَسْبُنَا ٱللَّهُ سَيُؤْتِينَا ٱللَّهُ مِن فَضْلِهِۦ وَرَسُولُهُۥٓ إِنَّآ إِلَى ٱللَّهِ رَٰغِبُونَ', 'ولو أنهم رضوا ما ءاتىهم الله ورسوله وقالوا حسبنا الله سيؤتينا الله من فضله ورسوله إنا إلى الله رغبون', NULL, 196, 'local:hafs-text.json'),
  ('hafs-9-60', 'hafs', 9, 60, '۞ إِنَّمَا ٱلصَّدَقَٰتُ لِلْفُقَرَآءِ وَٱلْمَسَٰكِينِ وَٱلْعَٰمِلِينَ عَلَيْهَا وَٱلْمُؤَلَّفَةِ قُلُوبُهُمْ وَفِى ٱلرِّقَابِ وَٱلْغَٰرِمِينَ وَفِى سَبِيلِ ٱللَّهِ وَٱبْنِ ٱلسَّبِيلِ ۖ فَرِيضَةًۭ مِّنَ ٱللَّهِ ۗ وَٱللَّهُ عَلِيمٌ حَكِيمٌۭ', 'إنما الصدقت للفقراء والمسكين والعملين عليها والمؤلفة قلوبهم وفى الرقاب والغرمين وفى سبيل الله وابن السبيل  فريضة من الله  والله عليم حكيم', NULL, 196, 'local:hafs-text.json'),
  ('hafs-9-61', 'hafs', 9, 61, 'وَمِنْهُمُ ٱلَّذِينَ يُؤْذُونَ ٱلنَّبِىَّ وَيَقُولُونَ هُوَ أُذُنٌۭ ۚ قُلْ أُذُنُ خَيْرٍۢ لَّكُمْ يُؤْمِنُ بِٱللَّهِ وَيُؤْمِنُ لِلْمُؤْمِنِينَ وَرَحْمَةٌۭ لِّلَّذِينَ ءَامَنُوا۟ مِنكُمْ ۚ وَٱلَّذِينَ يُؤْذُونَ رَسُولَ ٱللَّهِ لَهُمْ عَذَابٌ أَلِيمٌۭ', 'ومنهم الذين يؤذون النبى ويقولون هو أذن  قل أذن خير لكم يؤمن بالله ويؤمن للمؤمنين ورحمة للذين ءامنوا منكم  والذين يؤذون رسول الله لهم عذاب أليم', NULL, 196, 'local:hafs-text.json'),
  ('hafs-9-62', 'hafs', 9, 62, 'يَحْلِفُونَ بِٱللَّهِ لَكُمْ لِيُرْضُوكُمْ وَٱللَّهُ وَرَسُولُهُۥٓ أَحَقُّ أَن يُرْضُوهُ إِن كَانُوا۟ مُؤْمِنِينَ', 'يحلفون بالله لكم ليرضوكم والله ورسوله أحق أن يرضوه إن كانوا مؤمنين', NULL, 197, 'local:hafs-text.json'),
  ('hafs-9-63', 'hafs', 9, 63, 'أَلَمْ يَعْلَمُوٓا۟ أَنَّهُۥ مَن يُحَادِدِ ٱللَّهَ وَرَسُولَهُۥ فَأَنَّ لَهُۥ نَارَ جَهَنَّمَ خَٰلِدًۭا فِيهَا ۚ ذَٰلِكَ ٱلْخِزْىُ ٱلْعَظِيمُ', 'ألم يعلموا أنه من يحادد الله ورسوله فأن له نار جهنم خلدا فيها  ذلك الخزى العظيم', NULL, 197, 'local:hafs-text.json'),
  ('hafs-9-64', 'hafs', 9, 64, 'يَحْذَرُ ٱلْمُنَٰفِقُونَ أَن تُنَزَّلَ عَلَيْهِمْ سُورَةٌۭ تُنَبِّئُهُم بِمَا فِى قُلُوبِهِمْ ۚ قُلِ ٱسْتَهْزِءُوٓا۟ إِنَّ ٱللَّهَ مُخْرِجٌۭ مَّا تَحْذَرُونَ', 'يحذر المنفقون أن تنزل عليهم سورة تنبئهم بما فى قلوبهم  قل استهزءوا إن الله مخرج ما تحذرون', NULL, 197, 'local:hafs-text.json'),
  ('hafs-9-65', 'hafs', 9, 65, 'وَلَئِن سَأَلْتَهُمْ لَيَقُولُنَّ إِنَّمَا كُنَّا نَخُوضُ وَنَلْعَبُ ۚ قُلْ أَبِٱللَّهِ وَءَايَٰتِهِۦ وَرَسُولِهِۦ كُنتُمْ تَسْتَهْزِءُونَ', 'ولئن سألتهم ليقولن إنما كنا نخوض ونلعب  قل أبالله وءايته ورسوله كنتم تستهزءون', NULL, 197, 'local:hafs-text.json'),
  ('hafs-9-66', 'hafs', 9, 66, 'لَا تَعْتَذِرُوا۟ قَدْ كَفَرْتُم بَعْدَ إِيمَٰنِكُمْ ۚ إِن نَّعْفُ عَن طَآئِفَةٍۢ مِّنكُمْ نُعَذِّبْ طَآئِفَةًۢ بِأَنَّهُمْ كَانُوا۟ مُجْرِمِينَ', 'لا تعتذروا قد كفرتم بعد إيمنكم  إن نعف عن طائفة منكم نعذب طائفة بأنهم كانوا مجرمين', NULL, 197, 'local:hafs-text.json'),
  ('hafs-9-67', 'hafs', 9, 67, 'ٱلْمُنَٰفِقُونَ وَٱلْمُنَٰفِقَٰتُ بَعْضُهُم مِّنۢ بَعْضٍۢ ۚ يَأْمُرُونَ بِٱلْمُنكَرِ وَيَنْهَوْنَ عَنِ ٱلْمَعْرُوفِ وَيَقْبِضُونَ أَيْدِيَهُمْ ۚ نَسُوا۟ ٱللَّهَ فَنَسِيَهُمْ ۗ إِنَّ ٱلْمُنَٰفِقِينَ هُمُ ٱلْفَٰسِقُونَ', 'المنفقون والمنفقت بعضهم من بعض  يأمرون بالمنكر وينهون عن المعروف ويقبضون أيديهم  نسوا الله فنسيهم  إن المنفقين هم الفسقون', NULL, 197, 'local:hafs-text.json'),
  ('hafs-9-68', 'hafs', 9, 68, 'وَعَدَ ٱللَّهُ ٱلْمُنَٰفِقِينَ وَٱلْمُنَٰفِقَٰتِ وَٱلْكُفَّارَ نَارَ جَهَنَّمَ خَٰلِدِينَ فِيهَا ۚ هِىَ حَسْبُهُمْ ۚ وَلَعَنَهُمُ ٱللَّهُ ۖ وَلَهُمْ عَذَابٌۭ مُّقِيمٌۭ', 'وعد الله المنفقين والمنفقت والكفار نار جهنم خلدين فيها  هى حسبهم  ولعنهم الله  ولهم عذاب مقيم', NULL, 197, 'local:hafs-text.json'),
  ('hafs-9-69', 'hafs', 9, 69, 'كَٱلَّذِينَ مِن قَبْلِكُمْ كَانُوٓا۟ أَشَدَّ مِنكُمْ قُوَّةًۭ وَأَكْثَرَ أَمْوَٰلًۭا وَأَوْلَٰدًۭا فَٱسْتَمْتَعُوا۟ بِخَلَٰقِهِمْ فَٱسْتَمْتَعْتُم بِخَلَٰقِكُمْ كَمَا ٱسْتَمْتَعَ ٱلَّذِينَ مِن قَبْلِكُم بِخَلَٰقِهِمْ وَخُضْتُمْ كَٱلَّذِى خَاضُوٓا۟ ۚ أُو۟لَٰٓئِكَ حَبِطَتْ أَعْمَٰلُهُمْ فِى ٱلدُّنْيَا وَٱلْءَاخِرَةِ ۖ وَأُو۟لَٰٓئِكَ هُمُ ٱلْخَٰسِرُونَ', 'كالذين من قبلكم كانوا أشد منكم قوة وأكثر أمولا وأولدا فاستمتعوا بخلقهم فاستمتعتم بخلقكم كما استمتع الذين من قبلكم بخلقهم وخضتم كالذى خاضوا  أولئك حبطت أعملهم فى الدنيا والءاخرة  وأولئك هم الخسرون', NULL, 198, 'local:hafs-text.json'),
  ('hafs-9-70', 'hafs', 9, 70, 'أَلَمْ يَأْتِهِمْ نَبَأُ ٱلَّذِينَ مِن قَبْلِهِمْ قَوْمِ نُوحٍۢ وَعَادٍۢ وَثَمُودَ وَقَوْمِ إِبْرَٰهِيمَ وَأَصْحَٰبِ مَدْيَنَ وَٱلْمُؤْتَفِكَٰتِ ۚ أَتَتْهُمْ رُسُلُهُم بِٱلْبَيِّنَٰتِ ۖ فَمَا كَانَ ٱللَّهُ لِيَظْلِمَهُمْ وَلَٰكِن كَانُوٓا۟ أَنفُسَهُمْ يَظْلِمُونَ', 'ألم يأتهم نبأ الذين من قبلهم قوم نوح وعاد وثمود وقوم إبرهيم وأصحب مدين والمؤتفكت  أتتهم رسلهم بالبينت  فما كان الله ليظلمهم ولكن كانوا أنفسهم يظلمون', NULL, 198, 'local:hafs-text.json'),
  ('hafs-9-71', 'hafs', 9, 71, 'وَٱلْمُؤْمِنُونَ وَٱلْمُؤْمِنَٰتُ بَعْضُهُمْ أَوْلِيَآءُ بَعْضٍۢ ۚ يَأْمُرُونَ بِٱلْمَعْرُوفِ وَيَنْهَوْنَ عَنِ ٱلْمُنكَرِ وَيُقِيمُونَ ٱلصَّلَوٰةَ وَيُؤْتُونَ ٱلزَّكَوٰةَ وَيُطِيعُونَ ٱللَّهَ وَرَسُولَهُۥٓ ۚ أُو۟لَٰٓئِكَ سَيَرْحَمُهُمُ ٱللَّهُ ۗ إِنَّ ٱللَّهَ عَزِيزٌ حَكِيمٌۭ', 'والمؤمنون والمؤمنت بعضهم أولياء بعض  يأمرون بالمعروف وينهون عن المنكر ويقيمون الصلوة ويؤتون الزكوة ويطيعون الله ورسوله  أولئك سيرحمهم الله  إن الله عزيز حكيم', NULL, 198, 'local:hafs-text.json'),
  ('hafs-9-72', 'hafs', 9, 72, 'وَعَدَ ٱللَّهُ ٱلْمُؤْمِنِينَ وَٱلْمُؤْمِنَٰتِ جَنَّٰتٍۢ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ خَٰلِدِينَ فِيهَا وَمَسَٰكِنَ طَيِّبَةًۭ فِى جَنَّٰتِ عَدْنٍۢ ۚ وَرِضْوَٰنٌۭ مِّنَ ٱللَّهِ أَكْبَرُ ۚ ذَٰلِكَ هُوَ ٱلْفَوْزُ ٱلْعَظِيمُ', 'وعد الله المؤمنين والمؤمنت جنت تجرى من تحتها الأنهر خلدين فيها ومسكن طيبة فى جنت عدن  ورضون من الله أكبر  ذلك هو الفوز العظيم', NULL, 198, 'local:hafs-text.json'),
  ('hafs-9-73', 'hafs', 9, 73, 'يَٰٓأَيُّهَا ٱلنَّبِىُّ جَٰهِدِ ٱلْكُفَّارَ وَٱلْمُنَٰفِقِينَ وَٱغْلُظْ عَلَيْهِمْ ۚ وَمَأْوَىٰهُمْ جَهَنَّمُ ۖ وَبِئْسَ ٱلْمَصِيرُ', 'يأيها النبى جهد الكفار والمنفقين واغلظ عليهم  ومأوىهم جهنم  وبئس المصير', NULL, 199, 'local:hafs-text.json'),
  ('hafs-9-74', 'hafs', 9, 74, 'يَحْلِفُونَ بِٱللَّهِ مَا قَالُوا۟ وَلَقَدْ قَالُوا۟ كَلِمَةَ ٱلْكُفْرِ وَكَفَرُوا۟ بَعْدَ إِسْلَٰمِهِمْ وَهَمُّوا۟ بِمَا لَمْ يَنَالُوا۟ ۚ وَمَا نَقَمُوٓا۟ إِلَّآ أَنْ أَغْنَىٰهُمُ ٱللَّهُ وَرَسُولُهُۥ مِن فَضْلِهِۦ ۚ فَإِن يَتُوبُوا۟ يَكُ خَيْرًۭا لَّهُمْ ۖ وَإِن يَتَوَلَّوْا۟ يُعَذِّبْهُمُ ٱللَّهُ عَذَابًا أَلِيمًۭا فِى ٱلدُّنْيَا وَٱلْءَاخِرَةِ ۚ وَمَا لَهُمْ فِى ٱلْأَرْضِ مِن وَلِىٍّۢ وَلَا نَصِيرٍۢ', 'يحلفون بالله ما قالوا ولقد قالوا كلمة الكفر وكفروا بعد إسلمهم وهموا بما لم ينالوا  وما نقموا إلا أن أغنىهم الله ورسوله من فضله  فإن يتوبوا يك خيرا لهم  وإن يتولوا يعذبهم الله عذابا أليما فى الدنيا والءاخرة  وما لهم فى الأرض من ولى ولا نصير', NULL, 199, 'local:hafs-text.json'),
  ('hafs-9-75', 'hafs', 9, 75, '۞ وَمِنْهُم مَّنْ عَٰهَدَ ٱللَّهَ لَئِنْ ءَاتَىٰنَا مِن فَضْلِهِۦ لَنَصَّدَّقَنَّ وَلَنَكُونَنَّ مِنَ ٱلصَّٰلِحِينَ', 'ومنهم من عهد الله لئن ءاتىنا من فضله لنصدقن ولنكونن من الصلحين', NULL, 199, 'local:hafs-text.json'),
  ('hafs-9-76', 'hafs', 9, 76, 'فَلَمَّآ ءَاتَىٰهُم مِّن فَضْلِهِۦ بَخِلُوا۟ بِهِۦ وَتَوَلَّوا۟ وَّهُم مُّعْرِضُونَ', 'فلما ءاتىهم من فضله بخلوا به وتولوا وهم معرضون', NULL, 199, 'local:hafs-text.json'),
  ('hafs-9-77', 'hafs', 9, 77, 'فَأَعْقَبَهُمْ نِفَاقًۭا فِى قُلُوبِهِمْ إِلَىٰ يَوْمِ يَلْقَوْنَهُۥ بِمَآ أَخْلَفُوا۟ ٱللَّهَ مَا وَعَدُوهُ وَبِمَا كَانُوا۟ يَكْذِبُونَ', 'فأعقبهم نفاقا فى قلوبهم إلى يوم يلقونه بما أخلفوا الله ما وعدوه وبما كانوا يكذبون', NULL, 199, 'local:hafs-text.json'),
  ('hafs-9-78', 'hafs', 9, 78, 'أَلَمْ يَعْلَمُوٓا۟ أَنَّ ٱللَّهَ يَعْلَمُ سِرَّهُمْ وَنَجْوَىٰهُمْ وَأَنَّ ٱللَّهَ عَلَّٰمُ ٱلْغُيُوبِ', 'ألم يعلموا أن الله يعلم سرهم ونجوىهم وأن الله علم الغيوب', NULL, 199, 'local:hafs-text.json'),
  ('hafs-9-79', 'hafs', 9, 79, 'ٱلَّذِينَ يَلْمِزُونَ ٱلْمُطَّوِّعِينَ مِنَ ٱلْمُؤْمِنِينَ فِى ٱلصَّدَقَٰتِ وَٱلَّذِينَ لَا يَجِدُونَ إِلَّا جُهْدَهُمْ فَيَسْخَرُونَ مِنْهُمْ ۙ سَخِرَ ٱللَّهُ مِنْهُمْ وَلَهُمْ عَذَابٌ أَلِيمٌ', 'الذين يلمزون المطوعين من المؤمنين فى الصدقت والذين لا يجدون إلا جهدهم فيسخرون منهم  سخر الله منهم ولهم عذاب أليم', NULL, 199, 'local:hafs-text.json'),
  ('hafs-9-80', 'hafs', 9, 80, 'ٱسْتَغْفِرْ لَهُمْ أَوْ لَا تَسْتَغْفِرْ لَهُمْ إِن تَسْتَغْفِرْ لَهُمْ سَبْعِينَ مَرَّةًۭ فَلَن يَغْفِرَ ٱللَّهُ لَهُمْ ۚ ذَٰلِكَ بِأَنَّهُمْ كَفَرُوا۟ بِٱللَّهِ وَرَسُولِهِۦ ۗ وَٱللَّهُ لَا يَهْدِى ٱلْقَوْمَ ٱلْفَٰسِقِينَ', 'استغفر لهم أو لا تستغفر لهم إن تستغفر لهم سبعين مرة فلن يغفر الله لهم  ذلك بأنهم كفروا بالله ورسوله  والله لا يهدى القوم الفسقين', NULL, 200, 'local:hafs-text.json'),
  ('hafs-9-81', 'hafs', 9, 81, 'فَرِحَ ٱلْمُخَلَّفُونَ بِمَقْعَدِهِمْ خِلَٰفَ رَسُولِ ٱللَّهِ وَكَرِهُوٓا۟ أَن يُجَٰهِدُوا۟ بِأَمْوَٰلِهِمْ وَأَنفُسِهِمْ فِى سَبِيلِ ٱللَّهِ وَقَالُوا۟ لَا تَنفِرُوا۟ فِى ٱلْحَرِّ ۗ قُلْ نَارُ جَهَنَّمَ أَشَدُّ حَرًّۭا ۚ لَّوْ كَانُوا۟ يَفْقَهُونَ', 'فرح المخلفون بمقعدهم خلف رسول الله وكرهوا أن يجهدوا بأمولهم وأنفسهم فى سبيل الله وقالوا لا تنفروا فى الحر  قل نار جهنم أشد حرا  لو كانوا يفقهون', NULL, 200, 'local:hafs-text.json'),
  ('hafs-9-82', 'hafs', 9, 82, 'فَلْيَضْحَكُوا۟ قَلِيلًۭا وَلْيَبْكُوا۟ كَثِيرًۭا جَزَآءًۢ بِمَا كَانُوا۟ يَكْسِبُونَ', 'فليضحكوا قليلا وليبكوا كثيرا جزاء بما كانوا يكسبون', NULL, 200, 'local:hafs-text.json'),
  ('hafs-9-83', 'hafs', 9, 83, 'فَإِن رَّجَعَكَ ٱللَّهُ إِلَىٰ طَآئِفَةٍۢ مِّنْهُمْ فَٱسْتَـْٔذَنُوكَ لِلْخُرُوجِ فَقُل لَّن تَخْرُجُوا۟ مَعِىَ أَبَدًۭا وَلَن تُقَٰتِلُوا۟ مَعِىَ عَدُوًّا ۖ إِنَّكُمْ رَضِيتُم بِٱلْقُعُودِ أَوَّلَ مَرَّةٍۢ فَٱقْعُدُوا۟ مَعَ ٱلْخَٰلِفِينَ', 'فإن رجعك الله إلى طائفة منهم فاستذنوك للخروج فقل لن تخرجوا معى أبدا ولن تقتلوا معى عدوا  إنكم رضيتم بالقعود أول مرة فاقعدوا مع الخلفين', NULL, 200, 'local:hafs-text.json'),
  ('hafs-9-84', 'hafs', 9, 84, 'وَلَا تُصَلِّ عَلَىٰٓ أَحَدٍۢ مِّنْهُم مَّاتَ أَبَدًۭا وَلَا تَقُمْ عَلَىٰ قَبْرِهِۦٓ ۖ إِنَّهُمْ كَفَرُوا۟ بِٱللَّهِ وَرَسُولِهِۦ وَمَاتُوا۟ وَهُمْ فَٰسِقُونَ', 'ولا تصل على أحد منهم مات أبدا ولا تقم على قبره  إنهم كفروا بالله ورسوله وماتوا وهم فسقون', NULL, 200, 'local:hafs-text.json'),
  ('hafs-9-85', 'hafs', 9, 85, 'وَلَا تُعْجِبْكَ أَمْوَٰلُهُمْ وَأَوْلَٰدُهُمْ ۚ إِنَّمَا يُرِيدُ ٱللَّهُ أَن يُعَذِّبَهُم بِهَا فِى ٱلدُّنْيَا وَتَزْهَقَ أَنفُسُهُمْ وَهُمْ كَٰفِرُونَ', 'ولا تعجبك أمولهم وأولدهم  إنما يريد الله أن يعذبهم بها فى الدنيا وتزهق أنفسهم وهم كفرون', NULL, 200, 'local:hafs-text.json'),
  ('hafs-9-86', 'hafs', 9, 86, 'وَإِذَآ أُنزِلَتْ سُورَةٌ أَنْ ءَامِنُوا۟ بِٱللَّهِ وَجَٰهِدُوا۟ مَعَ رَسُولِهِ ٱسْتَـْٔذَنَكَ أُو۟لُوا۟ ٱلطَّوْلِ مِنْهُمْ وَقَالُوا۟ ذَرْنَا نَكُن مَّعَ ٱلْقَٰعِدِينَ', 'وإذا أنزلت سورة أن ءامنوا بالله وجهدوا مع رسوله استذنك أولوا الطول منهم وقالوا ذرنا نكن مع القعدين', NULL, 200, 'local:hafs-text.json'),
  ('hafs-9-87', 'hafs', 9, 87, 'رَضُوا۟ بِأَن يَكُونُوا۟ مَعَ ٱلْخَوَالِفِ وَطُبِعَ عَلَىٰ قُلُوبِهِمْ فَهُمْ لَا يَفْقَهُونَ', 'رضوا بأن يكونوا مع الخوالف وطبع على قلوبهم فهم لا يفقهون', NULL, 201, 'local:hafs-text.json'),
  ('hafs-9-88', 'hafs', 9, 88, 'لَٰكِنِ ٱلرَّسُولُ وَٱلَّذِينَ ءَامَنُوا۟ مَعَهُۥ جَٰهَدُوا۟ بِأَمْوَٰلِهِمْ وَأَنفُسِهِمْ ۚ وَأُو۟لَٰٓئِكَ لَهُمُ ٱلْخَيْرَٰتُ ۖ وَأُو۟لَٰٓئِكَ هُمُ ٱلْمُفْلِحُونَ', 'لكن الرسول والذين ءامنوا معه جهدوا بأمولهم وأنفسهم  وأولئك لهم الخيرت  وأولئك هم المفلحون', NULL, 201, 'local:hafs-text.json'),
  ('hafs-9-89', 'hafs', 9, 89, 'أَعَدَّ ٱللَّهُ لَهُمْ جَنَّٰتٍۢ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ خَٰلِدِينَ فِيهَا ۚ ذَٰلِكَ ٱلْفَوْزُ ٱلْعَظِيمُ', 'أعد الله لهم جنت تجرى من تحتها الأنهر خلدين فيها  ذلك الفوز العظيم', NULL, 201, 'local:hafs-text.json'),
  ('hafs-9-90', 'hafs', 9, 90, 'وَجَآءَ ٱلْمُعَذِّرُونَ مِنَ ٱلْأَعْرَابِ لِيُؤْذَنَ لَهُمْ وَقَعَدَ ٱلَّذِينَ كَذَبُوا۟ ٱللَّهَ وَرَسُولَهُۥ ۚ سَيُصِيبُ ٱلَّذِينَ كَفَرُوا۟ مِنْهُمْ عَذَابٌ أَلِيمٌۭ', 'وجاء المعذرون من الأعراب ليؤذن لهم وقعد الذين كذبوا الله ورسوله  سيصيب الذين كفروا منهم عذاب أليم', NULL, 201, 'local:hafs-text.json'),
  ('hafs-9-91', 'hafs', 9, 91, 'لَّيْسَ عَلَى ٱلضُّعَفَآءِ وَلَا عَلَى ٱلْمَرْضَىٰ وَلَا عَلَى ٱلَّذِينَ لَا يَجِدُونَ مَا يُنفِقُونَ حَرَجٌ إِذَا نَصَحُوا۟ لِلَّهِ وَرَسُولِهِۦ ۚ مَا عَلَى ٱلْمُحْسِنِينَ مِن سَبِيلٍۢ ۚ وَٱللَّهُ غَفُورٌۭ رَّحِيمٌۭ', 'ليس على الضعفاء ولا على المرضى ولا على الذين لا يجدون ما ينفقون حرج إذا نصحوا لله ورسوله  ما على المحسنين من سبيل  والله غفور رحيم', NULL, 201, 'local:hafs-text.json'),
  ('hafs-9-92', 'hafs', 9, 92, 'وَلَا عَلَى ٱلَّذِينَ إِذَا مَآ أَتَوْكَ لِتَحْمِلَهُمْ قُلْتَ لَآ أَجِدُ مَآ أَحْمِلُكُمْ عَلَيْهِ تَوَلَّوا۟ وَّأَعْيُنُهُمْ تَفِيضُ مِنَ ٱلدَّمْعِ حَزَنًا أَلَّا يَجِدُوا۟ مَا يُنفِقُونَ', 'ولا على الذين إذا ما أتوك لتحملهم قلت لا أجد ما أحملكم عليه تولوا وأعينهم تفيض من الدمع حزنا ألا يجدوا ما ينفقون', NULL, 201, 'local:hafs-text.json'),
  ('hafs-9-93', 'hafs', 9, 93, '۞ إِنَّمَا ٱلسَّبِيلُ عَلَى ٱلَّذِينَ يَسْتَـْٔذِنُونَكَ وَهُمْ أَغْنِيَآءُ ۚ رَضُوا۟ بِأَن يَكُونُوا۟ مَعَ ٱلْخَوَالِفِ وَطَبَعَ ٱللَّهُ عَلَىٰ قُلُوبِهِمْ فَهُمْ لَا يَعْلَمُونَ', 'إنما السبيل على الذين يستذنونك وهم أغنياء  رضوا بأن يكونوا مع الخوالف وطبع الله على قلوبهم فهم لا يعلمون', NULL, 201, 'local:hafs-text.json'),
  ('hafs-9-94', 'hafs', 9, 94, 'يَعْتَذِرُونَ إِلَيْكُمْ إِذَا رَجَعْتُمْ إِلَيْهِمْ ۚ قُل لَّا تَعْتَذِرُوا۟ لَن نُّؤْمِنَ لَكُمْ قَدْ نَبَّأَنَا ٱللَّهُ مِنْ أَخْبَارِكُمْ ۚ وَسَيَرَى ٱللَّهُ عَمَلَكُمْ وَرَسُولُهُۥ ثُمَّ تُرَدُّونَ إِلَىٰ عَٰلِمِ ٱلْغَيْبِ وَٱلشَّهَٰدَةِ فَيُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ', 'يعتذرون إليكم إذا رجعتم إليهم  قل لا تعتذروا لن نؤمن لكم قد نبأنا الله من أخباركم  وسيرى الله عملكم ورسوله ثم تردون إلى علم الغيب والشهدة فينبئكم بما كنتم تعملون', NULL, 202, 'local:hafs-text.json'),
  ('hafs-9-95', 'hafs', 9, 95, 'سَيَحْلِفُونَ بِٱللَّهِ لَكُمْ إِذَا ٱنقَلَبْتُمْ إِلَيْهِمْ لِتُعْرِضُوا۟ عَنْهُمْ ۖ فَأَعْرِضُوا۟ عَنْهُمْ ۖ إِنَّهُمْ رِجْسٌۭ ۖ وَمَأْوَىٰهُمْ جَهَنَّمُ جَزَآءًۢ بِمَا كَانُوا۟ يَكْسِبُونَ', 'سيحلفون بالله لكم إذا انقلبتم إليهم لتعرضوا عنهم  فأعرضوا عنهم  إنهم رجس  ومأوىهم جهنم جزاء بما كانوا يكسبون', NULL, 202, 'local:hafs-text.json'),
  ('hafs-9-96', 'hafs', 9, 96, 'يَحْلِفُونَ لَكُمْ لِتَرْضَوْا۟ عَنْهُمْ ۖ فَإِن تَرْضَوْا۟ عَنْهُمْ فَإِنَّ ٱللَّهَ لَا يَرْضَىٰ عَنِ ٱلْقَوْمِ ٱلْفَٰسِقِينَ', 'يحلفون لكم لترضوا عنهم  فإن ترضوا عنهم فإن الله لا يرضى عن القوم الفسقين', NULL, 202, 'local:hafs-text.json'),
  ('hafs-9-97', 'hafs', 9, 97, 'ٱلْأَعْرَابُ أَشَدُّ كُفْرًۭا وَنِفَاقًۭا وَأَجْدَرُ أَلَّا يَعْلَمُوا۟ حُدُودَ مَآ أَنزَلَ ٱللَّهُ عَلَىٰ رَسُولِهِۦ ۗ وَٱللَّهُ عَلِيمٌ حَكِيمٌۭ', 'الأعراب أشد كفرا ونفاقا وأجدر ألا يعلموا حدود ما أنزل الله على رسوله  والله عليم حكيم', NULL, 202, 'local:hafs-text.json'),
  ('hafs-9-98', 'hafs', 9, 98, 'وَمِنَ ٱلْأَعْرَابِ مَن يَتَّخِذُ مَا يُنفِقُ مَغْرَمًۭا وَيَتَرَبَّصُ بِكُمُ ٱلدَّوَآئِرَ ۚ عَلَيْهِمْ دَآئِرَةُ ٱلسَّوْءِ ۗ وَٱللَّهُ سَمِيعٌ عَلِيمٌۭ', 'ومن الأعراب من يتخذ ما ينفق مغرما ويتربص بكم الدوائر  عليهم دائرة السوء  والله سميع عليم', NULL, 202, 'local:hafs-text.json'),
  ('hafs-9-99', 'hafs', 9, 99, 'وَمِنَ ٱلْأَعْرَابِ مَن يُؤْمِنُ بِٱللَّهِ وَٱلْيَوْمِ ٱلْءَاخِرِ وَيَتَّخِذُ مَا يُنفِقُ قُرُبَٰتٍ عِندَ ٱللَّهِ وَصَلَوَٰتِ ٱلرَّسُولِ ۚ أَلَآ إِنَّهَا قُرْبَةٌۭ لَّهُمْ ۚ سَيُدْخِلُهُمُ ٱللَّهُ فِى رَحْمَتِهِۦٓ ۗ إِنَّ ٱللَّهَ غَفُورٌۭ رَّحِيمٌۭ', 'ومن الأعراب من يؤمن بالله واليوم الءاخر ويتخذ ما ينفق قربت عند الله وصلوت الرسول  ألا إنها قربة لهم  سيدخلهم الله فى رحمته  إن الله غفور رحيم', NULL, 202, 'local:hafs-text.json'),
  ('hafs-9-100', 'hafs', 9, 100, 'وَٱلسَّٰبِقُونَ ٱلْأَوَّلُونَ مِنَ ٱلْمُهَٰجِرِينَ وَٱلْأَنصَارِ وَٱلَّذِينَ ٱتَّبَعُوهُم بِإِحْسَٰنٍۢ رَّضِىَ ٱللَّهُ عَنْهُمْ وَرَضُوا۟ عَنْهُ وَأَعَدَّ لَهُمْ جَنَّٰتٍۢ تَجْرِى تَحْتَهَا ٱلْأَنْهَٰرُ خَٰلِدِينَ فِيهَآ أَبَدًۭا ۚ ذَٰلِكَ ٱلْفَوْزُ ٱلْعَظِيمُ', 'والسبقون الأولون من المهجرين والأنصار والذين اتبعوهم بإحسن رضى الله عنهم ورضوا عنه وأعد لهم جنت تجرى تحتها الأنهر خلدين فيها أبدا  ذلك الفوز العظيم', NULL, 203, 'local:hafs-text.json'),
  ('hafs-9-101', 'hafs', 9, 101, 'وَمِمَّنْ حَوْلَكُم مِّنَ ٱلْأَعْرَابِ مُنَٰفِقُونَ ۖ وَمِنْ أَهْلِ ٱلْمَدِينَةِ ۖ مَرَدُوا۟ عَلَى ٱلنِّفَاقِ لَا تَعْلَمُهُمْ ۖ نَحْنُ نَعْلَمُهُمْ ۚ سَنُعَذِّبُهُم مَّرَّتَيْنِ ثُمَّ يُرَدُّونَ إِلَىٰ عَذَابٍ عَظِيمٍۢ', 'وممن حولكم من الأعراب منفقون  ومن أهل المدينة  مردوا على النفاق لا تعلمهم  نحن نعلمهم  سنعذبهم مرتين ثم يردون إلى عذاب عظيم', NULL, 203, 'local:hafs-text.json'),
  ('hafs-9-102', 'hafs', 9, 102, 'وَءَاخَرُونَ ٱعْتَرَفُوا۟ بِذُنُوبِهِمْ خَلَطُوا۟ عَمَلًۭا صَٰلِحًۭا وَءَاخَرَ سَيِّئًا عَسَى ٱللَّهُ أَن يَتُوبَ عَلَيْهِمْ ۚ إِنَّ ٱللَّهَ غَفُورٌۭ رَّحِيمٌ', 'وءاخرون اعترفوا بذنوبهم خلطوا عملا صلحا وءاخر سيئا عسى الله أن يتوب عليهم  إن الله غفور رحيم', NULL, 203, 'local:hafs-text.json'),
  ('hafs-9-103', 'hafs', 9, 103, 'خُذْ مِنْ أَمْوَٰلِهِمْ صَدَقَةًۭ تُطَهِّرُهُمْ وَتُزَكِّيهِم بِهَا وَصَلِّ عَلَيْهِمْ ۖ إِنَّ صَلَوٰتَكَ سَكَنٌۭ لَّهُمْ ۗ وَٱللَّهُ سَمِيعٌ عَلِيمٌ', 'خذ من أمولهم صدقة تطهرهم وتزكيهم بها وصل عليهم  إن صلوتك سكن لهم  والله سميع عليم', NULL, 203, 'local:hafs-text.json'),
  ('hafs-9-104', 'hafs', 9, 104, 'أَلَمْ يَعْلَمُوٓا۟ أَنَّ ٱللَّهَ هُوَ يَقْبَلُ ٱلتَّوْبَةَ عَنْ عِبَادِهِۦ وَيَأْخُذُ ٱلصَّدَقَٰتِ وَأَنَّ ٱللَّهَ هُوَ ٱلتَّوَّابُ ٱلرَّحِيمُ', 'ألم يعلموا أن الله هو يقبل التوبة عن عباده ويأخذ الصدقت وأن الله هو التواب الرحيم', NULL, 203, 'local:hafs-text.json'),
  ('hafs-9-105', 'hafs', 9, 105, 'وَقُلِ ٱعْمَلُوا۟ فَسَيَرَى ٱللَّهُ عَمَلَكُمْ وَرَسُولُهُۥ وَٱلْمُؤْمِنُونَ ۖ وَسَتُرَدُّونَ إِلَىٰ عَٰلِمِ ٱلْغَيْبِ وَٱلشَّهَٰدَةِ فَيُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ', 'وقل اعملوا فسيرى الله عملكم ورسوله والمؤمنون  وستردون إلى علم الغيب والشهدة فينبئكم بما كنتم تعملون', NULL, 203, 'local:hafs-text.json'),
  ('hafs-9-106', 'hafs', 9, 106, 'وَءَاخَرُونَ مُرْجَوْنَ لِأَمْرِ ٱللَّهِ إِمَّا يُعَذِّبُهُمْ وَإِمَّا يَتُوبُ عَلَيْهِمْ ۗ وَٱللَّهُ عَلِيمٌ حَكِيمٌۭ', 'وءاخرون مرجون لأمر الله إما يعذبهم وإما يتوب عليهم  والله عليم حكيم', NULL, 203, 'local:hafs-text.json'),
  ('hafs-9-107', 'hafs', 9, 107, 'وَٱلَّذِينَ ٱتَّخَذُوا۟ مَسْجِدًۭا ضِرَارًۭا وَكُفْرًۭا وَتَفْرِيقًۢا بَيْنَ ٱلْمُؤْمِنِينَ وَإِرْصَادًۭا لِّمَنْ حَارَبَ ٱللَّهَ وَرَسُولَهُۥ مِن قَبْلُ ۚ وَلَيَحْلِفُنَّ إِنْ أَرَدْنَآ إِلَّا ٱلْحُسْنَىٰ ۖ وَٱللَّهُ يَشْهَدُ إِنَّهُمْ لَكَٰذِبُونَ', 'والذين اتخذوا مسجدا ضرارا وكفرا وتفريقا بين المؤمنين وإرصادا لمن حارب الله ورسوله من قبل  وليحلفن إن أردنا إلا الحسنى  والله يشهد إنهم لكذبون', NULL, 204, 'local:hafs-text.json'),
  ('hafs-9-108', 'hafs', 9, 108, 'لَا تَقُمْ فِيهِ أَبَدًۭا ۚ لَّمَسْجِدٌ أُسِّسَ عَلَى ٱلتَّقْوَىٰ مِنْ أَوَّلِ يَوْمٍ أَحَقُّ أَن تَقُومَ فِيهِ ۚ فِيهِ رِجَالٌۭ يُحِبُّونَ أَن يَتَطَهَّرُوا۟ ۚ وَٱللَّهُ يُحِبُّ ٱلْمُطَّهِّرِينَ', 'لا تقم فيه أبدا  لمسجد أسس على التقوى من أول يوم أحق أن تقوم فيه  فيه رجال يحبون أن يتطهروا  والله يحب المطهرين', NULL, 204, 'local:hafs-text.json'),
  ('hafs-9-109', 'hafs', 9, 109, 'أَفَمَنْ أَسَّسَ بُنْيَٰنَهُۥ عَلَىٰ تَقْوَىٰ مِنَ ٱللَّهِ وَرِضْوَٰنٍ خَيْرٌ أَم مَّنْ أَسَّسَ بُنْيَٰنَهُۥ عَلَىٰ شَفَا جُرُفٍ هَارٍۢ فَٱنْهَارَ بِهِۦ فِى نَارِ جَهَنَّمَ ۗ وَٱللَّهُ لَا يَهْدِى ٱلْقَوْمَ ٱلظَّٰلِمِينَ', 'أفمن أسس بنينه على تقوى من الله ورضون خير أم من أسس بنينه على شفا جرف هار فانهار به فى نار جهنم  والله لا يهدى القوم الظلمين', NULL, 204, 'local:hafs-text.json'),
  ('hafs-9-110', 'hafs', 9, 110, 'لَا يَزَالُ بُنْيَٰنُهُمُ ٱلَّذِى بَنَوْا۟ رِيبَةًۭ فِى قُلُوبِهِمْ إِلَّآ أَن تَقَطَّعَ قُلُوبُهُمْ ۗ وَٱللَّهُ عَلِيمٌ حَكِيمٌ', 'لا يزال بنينهم الذى بنوا ريبة فى قلوبهم إلا أن تقطع قلوبهم  والله عليم حكيم', NULL, 204, 'local:hafs-text.json'),
  ('hafs-9-111', 'hafs', 9, 111, '۞ إِنَّ ٱللَّهَ ٱشْتَرَىٰ مِنَ ٱلْمُؤْمِنِينَ أَنفُسَهُمْ وَأَمْوَٰلَهُم بِأَنَّ لَهُمُ ٱلْجَنَّةَ ۚ يُقَٰتِلُونَ فِى سَبِيلِ ٱللَّهِ فَيَقْتُلُونَ وَيُقْتَلُونَ ۖ وَعْدًا عَلَيْهِ حَقًّۭا فِى ٱلتَّوْرَىٰةِ وَٱلْإِنجِيلِ وَٱلْقُرْءَانِ ۚ وَمَنْ أَوْفَىٰ بِعَهْدِهِۦ مِنَ ٱللَّهِ ۚ فَٱسْتَبْشِرُوا۟ بِبَيْعِكُمُ ٱلَّذِى بَايَعْتُم بِهِۦ ۚ وَذَٰلِكَ هُوَ ٱلْفَوْزُ ٱلْعَظِيمُ', 'إن الله اشترى من المؤمنين أنفسهم وأمولهم بأن لهم الجنة  يقتلون فى سبيل الله فيقتلون ويقتلون  وعدا عليه حقا فى التورىة والإنجيل والقرءان  ومن أوفى بعهده من الله  فاستبشروا ببيعكم الذى بايعتم به  وذلك هو الفوز العظيم', NULL, 204, 'local:hafs-text.json'),
  ('hafs-9-112', 'hafs', 9, 112, 'ٱلتَّٰٓئِبُونَ ٱلْعَٰبِدُونَ ٱلْحَٰمِدُونَ ٱلسَّٰٓئِحُونَ ٱلرَّٰكِعُونَ ٱلسَّٰجِدُونَ ٱلْءَامِرُونَ بِٱلْمَعْرُوفِ وَٱلنَّاهُونَ عَنِ ٱلْمُنكَرِ وَٱلْحَٰفِظُونَ لِحُدُودِ ٱللَّهِ ۗ وَبَشِّرِ ٱلْمُؤْمِنِينَ', 'التئبون العبدون الحمدون السئحون الركعون السجدون الءامرون بالمعروف والناهون عن المنكر والحفظون لحدود الله  وبشر المؤمنين', NULL, 205, 'local:hafs-text.json'),
  ('hafs-9-113', 'hafs', 9, 113, 'مَا كَانَ لِلنَّبِىِّ وَٱلَّذِينَ ءَامَنُوٓا۟ أَن يَسْتَغْفِرُوا۟ لِلْمُشْرِكِينَ وَلَوْ كَانُوٓا۟ أُو۟لِى قُرْبَىٰ مِنۢ بَعْدِ مَا تَبَيَّنَ لَهُمْ أَنَّهُمْ أَصْحَٰبُ ٱلْجَحِيمِ', 'ما كان للنبى والذين ءامنوا أن يستغفروا للمشركين ولو كانوا أولى قربى من بعد ما تبين لهم أنهم أصحب الجحيم', NULL, 205, 'local:hafs-text.json'),
  ('hafs-9-114', 'hafs', 9, 114, 'وَمَا كَانَ ٱسْتِغْفَارُ إِبْرَٰهِيمَ لِأَبِيهِ إِلَّا عَن مَّوْعِدَةٍۢ وَعَدَهَآ إِيَّاهُ فَلَمَّا تَبَيَّنَ لَهُۥٓ أَنَّهُۥ عَدُوٌّۭ لِّلَّهِ تَبَرَّأَ مِنْهُ ۚ إِنَّ إِبْرَٰهِيمَ لَأَوَّٰهٌ حَلِيمٌۭ', 'وما كان استغفار إبرهيم لأبيه إلا عن موعدة وعدها إياه فلما تبين له أنه عدو لله تبرأ منه  إن إبرهيم لأوه حليم', NULL, 205, 'local:hafs-text.json'),
  ('hafs-9-115', 'hafs', 9, 115, 'وَمَا كَانَ ٱللَّهُ لِيُضِلَّ قَوْمًۢا بَعْدَ إِذْ هَدَىٰهُمْ حَتَّىٰ يُبَيِّنَ لَهُم مَّا يَتَّقُونَ ۚ إِنَّ ٱللَّهَ بِكُلِّ شَىْءٍ عَلِيمٌ', 'وما كان الله ليضل قوما بعد إذ هدىهم حتى يبين لهم ما يتقون  إن الله بكل شىء عليم', NULL, 205, 'local:hafs-text.json'),
  ('hafs-9-116', 'hafs', 9, 116, 'إِنَّ ٱللَّهَ لَهُۥ مُلْكُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ ۖ يُحْىِۦ وَيُمِيتُ ۚ وَمَا لَكُم مِّن دُونِ ٱللَّهِ مِن وَلِىٍّۢ وَلَا نَصِيرٍۢ', 'إن الله له ملك السموت والأرض  يحى ويميت  وما لكم من دون الله من ولى ولا نصير', NULL, 205, 'local:hafs-text.json'),
  ('hafs-9-117', 'hafs', 9, 117, 'لَّقَد تَّابَ ٱللَّهُ عَلَى ٱلنَّبِىِّ وَٱلْمُهَٰجِرِينَ وَٱلْأَنصَارِ ٱلَّذِينَ ٱتَّبَعُوهُ فِى سَاعَةِ ٱلْعُسْرَةِ مِنۢ بَعْدِ مَا كَادَ يَزِيغُ قُلُوبُ فَرِيقٍۢ مِّنْهُمْ ثُمَّ تَابَ عَلَيْهِمْ ۚ إِنَّهُۥ بِهِمْ رَءُوفٌۭ رَّحِيمٌۭ', 'لقد تاب الله على النبى والمهجرين والأنصار الذين اتبعوه فى ساعة العسرة من بعد ما كاد يزيغ قلوب فريق منهم ثم تاب عليهم  إنه بهم رءوف رحيم', NULL, 205, 'local:hafs-text.json'),
  ('hafs-9-118', 'hafs', 9, 118, 'وَعَلَى ٱلثَّلَٰثَةِ ٱلَّذِينَ خُلِّفُوا۟ حَتَّىٰٓ إِذَا ضَاقَتْ عَلَيْهِمُ ٱلْأَرْضُ بِمَا رَحُبَتْ وَضَاقَتْ عَلَيْهِمْ أَنفُسُهُمْ وَظَنُّوٓا۟ أَن لَّا مَلْجَأَ مِنَ ٱللَّهِ إِلَّآ إِلَيْهِ ثُمَّ تَابَ عَلَيْهِمْ لِيَتُوبُوٓا۟ ۚ إِنَّ ٱللَّهَ هُوَ ٱلتَّوَّابُ ٱلرَّحِيمُ', 'وعلى الثلثة الذين خلفوا حتى إذا ضاقت عليهم الأرض بما رحبت وضاقت عليهم أنفسهم وظنوا أن لا ملجأ من الله إلا إليه ثم تاب عليهم ليتوبوا  إن الله هو التواب الرحيم', NULL, 206, 'local:hafs-text.json'),
  ('hafs-9-119', 'hafs', 9, 119, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱتَّقُوا۟ ٱللَّهَ وَكُونُوا۟ مَعَ ٱلصَّٰدِقِينَ', 'يأيها الذين ءامنوا اتقوا الله وكونوا مع الصدقين', NULL, 206, 'local:hafs-text.json'),
  ('hafs-9-120', 'hafs', 9, 120, 'مَا كَانَ لِأَهْلِ ٱلْمَدِينَةِ وَمَنْ حَوْلَهُم مِّنَ ٱلْأَعْرَابِ أَن يَتَخَلَّفُوا۟ عَن رَّسُولِ ٱللَّهِ وَلَا يَرْغَبُوا۟ بِأَنفُسِهِمْ عَن نَّفْسِهِۦ ۚ ذَٰلِكَ بِأَنَّهُمْ لَا يُصِيبُهُمْ ظَمَأٌۭ وَلَا نَصَبٌۭ وَلَا مَخْمَصَةٌۭ فِى سَبِيلِ ٱللَّهِ وَلَا يَطَـُٔونَ مَوْطِئًۭا يَغِيظُ ٱلْكُفَّارَ وَلَا يَنَالُونَ مِنْ عَدُوٍّۢ نَّيْلًا إِلَّا كُتِبَ لَهُم بِهِۦ عَمَلٌۭ صَٰلِحٌ ۚ إِنَّ ٱللَّهَ لَا يُضِيعُ أَجْرَ ٱلْمُحْسِنِينَ', 'ما كان لأهل المدينة ومن حولهم من الأعراب أن يتخلفوا عن رسول الله ولا يرغبوا بأنفسهم عن نفسه  ذلك بأنهم لا يصيبهم ظمأ ولا نصب ولا مخمصة فى سبيل الله ولا يطون موطئا يغيظ الكفار ولا ينالون من عدو نيلا إلا كتب لهم به عمل صلح  إن الله لا يضيع أجر المحسنين', NULL, 206, 'local:hafs-text.json'),
  ('hafs-9-121', 'hafs', 9, 121, 'وَلَا يُنفِقُونَ نَفَقَةًۭ صَغِيرَةًۭ وَلَا كَبِيرَةًۭ وَلَا يَقْطَعُونَ وَادِيًا إِلَّا كُتِبَ لَهُمْ لِيَجْزِيَهُمُ ٱللَّهُ أَحْسَنَ مَا كَانُوا۟ يَعْمَلُونَ', 'ولا ينفقون نفقة صغيرة ولا كبيرة ولا يقطعون واديا إلا كتب لهم ليجزيهم الله أحسن ما كانوا يعملون', NULL, 206, 'local:hafs-text.json'),
  ('hafs-9-122', 'hafs', 9, 122, '۞ وَمَا كَانَ ٱلْمُؤْمِنُونَ لِيَنفِرُوا۟ كَآفَّةًۭ ۚ فَلَوْلَا نَفَرَ مِن كُلِّ فِرْقَةٍۢ مِّنْهُمْ طَآئِفَةٌۭ لِّيَتَفَقَّهُوا۟ فِى ٱلدِّينِ وَلِيُنذِرُوا۟ قَوْمَهُمْ إِذَا رَجَعُوٓا۟ إِلَيْهِمْ لَعَلَّهُمْ يَحْذَرُونَ', 'وما كان المؤمنون لينفروا كافة  فلولا نفر من كل فرقة منهم طائفة ليتفقهوا فى الدين ولينذروا قومهم إذا رجعوا إليهم لعلهم يحذرون', NULL, 206, 'local:hafs-text.json'),
  ('hafs-9-123', 'hafs', 9, 123, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ قَٰتِلُوا۟ ٱلَّذِينَ يَلُونَكُم مِّنَ ٱلْكُفَّارِ وَلْيَجِدُوا۟ فِيكُمْ غِلْظَةًۭ ۚ وَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ مَعَ ٱلْمُتَّقِينَ', 'يأيها الذين ءامنوا قتلوا الذين يلونكم من الكفار وليجدوا فيكم غلظة  واعلموا أن الله مع المتقين', NULL, 207, 'local:hafs-text.json'),
  ('hafs-9-124', 'hafs', 9, 124, 'وَإِذَا مَآ أُنزِلَتْ سُورَةٌۭ فَمِنْهُم مَّن يَقُولُ أَيُّكُمْ زَادَتْهُ هَٰذِهِۦٓ إِيمَٰنًۭا ۚ فَأَمَّا ٱلَّذِينَ ءَامَنُوا۟ فَزَادَتْهُمْ إِيمَٰنًۭا وَهُمْ يَسْتَبْشِرُونَ', 'وإذا ما أنزلت سورة فمنهم من يقول أيكم زادته هذه إيمنا  فأما الذين ءامنوا فزادتهم إيمنا وهم يستبشرون', NULL, 207, 'local:hafs-text.json'),
  ('hafs-9-125', 'hafs', 9, 125, 'وَأَمَّا ٱلَّذِينَ فِى قُلُوبِهِم مَّرَضٌۭ فَزَادَتْهُمْ رِجْسًا إِلَىٰ رِجْسِهِمْ وَمَاتُوا۟ وَهُمْ كَٰفِرُونَ', 'وأما الذين فى قلوبهم مرض فزادتهم رجسا إلى رجسهم وماتوا وهم كفرون', NULL, 207, 'local:hafs-text.json'),
  ('hafs-9-126', 'hafs', 9, 126, 'أَوَلَا يَرَوْنَ أَنَّهُمْ يُفْتَنُونَ فِى كُلِّ عَامٍۢ مَّرَّةً أَوْ مَرَّتَيْنِ ثُمَّ لَا يَتُوبُونَ وَلَا هُمْ يَذَّكَّرُونَ', 'أولا يرون أنهم يفتنون فى كل عام مرة أو مرتين ثم لا يتوبون ولا هم يذكرون', NULL, 207, 'local:hafs-text.json'),
  ('hafs-9-127', 'hafs', 9, 127, 'وَإِذَا مَآ أُنزِلَتْ سُورَةٌۭ نَّظَرَ بَعْضُهُمْ إِلَىٰ بَعْضٍ هَلْ يَرَىٰكُم مِّنْ أَحَدٍۢ ثُمَّ ٱنصَرَفُوا۟ ۚ صَرَفَ ٱللَّهُ قُلُوبَهُم بِأَنَّهُمْ قَوْمٌۭ لَّا يَفْقَهُونَ', 'وإذا ما أنزلت سورة نظر بعضهم إلى بعض هل يرىكم من أحد ثم انصرفوا  صرف الله قلوبهم بأنهم قوم لا يفقهون', NULL, 207, 'local:hafs-text.json'),
  ('hafs-9-128', 'hafs', 9, 128, 'لَقَدْ جَآءَكُمْ رَسُولٌۭ مِّنْ أَنفُسِكُمْ عَزِيزٌ عَلَيْهِ مَا عَنِتُّمْ حَرِيصٌ عَلَيْكُم بِٱلْمُؤْمِنِينَ رَءُوفٌۭ رَّحِيمٌۭ', 'لقد جاءكم رسول من أنفسكم عزيز عليه ما عنتم حريص عليكم بالمؤمنين رءوف رحيم', NULL, 207, 'local:hafs-text.json'),
  ('hafs-9-129', 'hafs', 9, 129, 'فَإِن تَوَلَّوْا۟ فَقُلْ حَسْبِىَ ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَ ۖ عَلَيْهِ تَوَكَّلْتُ ۖ وَهُوَ رَبُّ ٱلْعَرْشِ ٱلْعَظِيمِ', 'فإن تولوا فقل حسبى الله لا إله إلا هو  عليه توكلت  وهو رب العرش العظيم', NULL, 207, 'local:hafs-text.json'),
  ('hafs-10-1', 'hafs', 10, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ الٓر ۚ تِلْكَ ءَايَٰتُ ٱلْكِتَٰبِ ٱلْحَكِيمِ', 'بسم الله الرحمن الرحيم الر  تلك ءايت الكتب الحكيم', NULL, 208, 'local:hafs-text.json'),
  ('hafs-10-2', 'hafs', 10, 2, 'أَكَانَ لِلنَّاسِ عَجَبًا أَنْ أَوْحَيْنَآ إِلَىٰ رَجُلٍۢ مِّنْهُمْ أَنْ أَنذِرِ ٱلنَّاسَ وَبَشِّرِ ٱلَّذِينَ ءَامَنُوٓا۟ أَنَّ لَهُمْ قَدَمَ صِدْقٍ عِندَ رَبِّهِمْ ۗ قَالَ ٱلْكَٰفِرُونَ إِنَّ هَٰذَا لَسَٰحِرٌۭ مُّبِينٌ', 'أكان للناس عجبا أن أوحينا إلى رجل منهم أن أنذر الناس وبشر الذين ءامنوا أن لهم قدم صدق عند ربهم  قال الكفرون إن هذا لسحر مبين', NULL, 208, 'local:hafs-text.json'),
  ('hafs-10-3', 'hafs', 10, 3, 'إِنَّ رَبَّكُمُ ٱللَّهُ ٱلَّذِى خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ فِى سِتَّةِ أَيَّامٍۢ ثُمَّ ٱسْتَوَىٰ عَلَى ٱلْعَرْشِ ۖ يُدَبِّرُ ٱلْأَمْرَ ۖ مَا مِن شَفِيعٍ إِلَّا مِنۢ بَعْدِ إِذْنِهِۦ ۚ ذَٰلِكُمُ ٱللَّهُ رَبُّكُمْ فَٱعْبُدُوهُ ۚ أَفَلَا تَذَكَّرُونَ', 'إن ربكم الله الذى خلق السموت والأرض فى ستة أيام ثم استوى على العرش  يدبر الأمر  ما من شفيع إلا من بعد إذنه  ذلكم الله ربكم فاعبدوه  أفلا تذكرون', NULL, 208, 'local:hafs-text.json'),
  ('hafs-10-4', 'hafs', 10, 4, 'إِلَيْهِ مَرْجِعُكُمْ جَمِيعًۭا ۖ وَعْدَ ٱللَّهِ حَقًّا ۚ إِنَّهُۥ يَبْدَؤُا۟ ٱلْخَلْقَ ثُمَّ يُعِيدُهُۥ لِيَجْزِىَ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ بِٱلْقِسْطِ ۚ وَٱلَّذِينَ كَفَرُوا۟ لَهُمْ شَرَابٌۭ مِّنْ حَمِيمٍۢ وَعَذَابٌ أَلِيمٌۢ بِمَا كَانُوا۟ يَكْفُرُونَ', 'إليه مرجعكم جميعا  وعد الله حقا  إنه يبدؤا الخلق ثم يعيده ليجزى الذين ءامنوا وعملوا الصلحت بالقسط  والذين كفروا لهم شراب من حميم وعذاب أليم بما كانوا يكفرون', NULL, 208, 'local:hafs-text.json'),
  ('hafs-10-5', 'hafs', 10, 5, 'هُوَ ٱلَّذِى جَعَلَ ٱلشَّمْسَ ضِيَآءًۭ وَٱلْقَمَرَ نُورًۭا وَقَدَّرَهُۥ مَنَازِلَ لِتَعْلَمُوا۟ عَدَدَ ٱلسِّنِينَ وَٱلْحِسَابَ ۚ مَا خَلَقَ ٱللَّهُ ذَٰلِكَ إِلَّا بِٱلْحَقِّ ۚ يُفَصِّلُ ٱلْءَايَٰتِ لِقَوْمٍۢ يَعْلَمُونَ', 'هو الذى جعل الشمس ضياء والقمر نورا وقدره منازل لتعلموا عدد السنين والحساب  ما خلق الله ذلك إلا بالحق  يفصل الءايت لقوم يعلمون', NULL, 208, 'local:hafs-text.json'),
  ('hafs-10-6', 'hafs', 10, 6, 'إِنَّ فِى ٱخْتِلَٰفِ ٱلَّيْلِ وَٱلنَّهَارِ وَمَا خَلَقَ ٱللَّهُ فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ لَءَايَٰتٍۢ لِّقَوْمٍۢ يَتَّقُونَ', 'إن فى اختلف اليل والنهار وما خلق الله فى السموت والأرض لءايت لقوم يتقون', NULL, 208, 'local:hafs-text.json'),
  ('hafs-10-7', 'hafs', 10, 7, 'إِنَّ ٱلَّذِينَ لَا يَرْجُونَ لِقَآءَنَا وَرَضُوا۟ بِٱلْحَيَوٰةِ ٱلدُّنْيَا وَٱطْمَأَنُّوا۟ بِهَا وَٱلَّذِينَ هُمْ عَنْ ءَايَٰتِنَا غَٰفِلُونَ', 'إن الذين لا يرجون لقاءنا ورضوا بالحيوة الدنيا واطمأنوا بها والذين هم عن ءايتنا غفلون', NULL, 209, 'local:hafs-text.json'),
  ('hafs-10-8', 'hafs', 10, 8, 'أُو۟لَٰٓئِكَ مَأْوَىٰهُمُ ٱلنَّارُ بِمَا كَانُوا۟ يَكْسِبُونَ', 'أولئك مأوىهم النار بما كانوا يكسبون', NULL, 209, 'local:hafs-text.json'),
  ('hafs-10-9', 'hafs', 10, 9, 'إِنَّ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ يَهْدِيهِمْ رَبُّهُم بِإِيمَٰنِهِمْ ۖ تَجْرِى مِن تَحْتِهِمُ ٱلْأَنْهَٰرُ فِى جَنَّٰتِ ٱلنَّعِيمِ', 'إن الذين ءامنوا وعملوا الصلحت يهديهم ربهم بإيمنهم  تجرى من تحتهم الأنهر فى جنت النعيم', NULL, 209, 'local:hafs-text.json'),
  ('hafs-10-10', 'hafs', 10, 10, 'دَعْوَىٰهُمْ فِيهَا سُبْحَٰنَكَ ٱللَّهُمَّ وَتَحِيَّتُهُمْ فِيهَا سَلَٰمٌۭ ۚ وَءَاخِرُ دَعْوَىٰهُمْ أَنِ ٱلْحَمْدُ لِلَّهِ رَبِّ ٱلْعَٰلَمِينَ', 'دعوىهم فيها سبحنك اللهم وتحيتهم فيها سلم  وءاخر دعوىهم أن الحمد لله رب العلمين', NULL, 209, 'local:hafs-text.json'),
  ('hafs-10-11', 'hafs', 10, 11, '۞ وَلَوْ يُعَجِّلُ ٱللَّهُ لِلنَّاسِ ٱلشَّرَّ ٱسْتِعْجَالَهُم بِٱلْخَيْرِ لَقُضِىَ إِلَيْهِمْ أَجَلُهُمْ ۖ فَنَذَرُ ٱلَّذِينَ لَا يَرْجُونَ لِقَآءَنَا فِى طُغْيَٰنِهِمْ يَعْمَهُونَ', 'ولو يعجل الله للناس الشر استعجالهم بالخير لقضى إليهم أجلهم  فنذر الذين لا يرجون لقاءنا فى طغينهم يعمهون', NULL, 209, 'local:hafs-text.json'),
  ('hafs-10-12', 'hafs', 10, 12, 'وَإِذَا مَسَّ ٱلْإِنسَٰنَ ٱلضُّرُّ دَعَانَا لِجَنۢبِهِۦٓ أَوْ قَاعِدًا أَوْ قَآئِمًۭا فَلَمَّا كَشَفْنَا عَنْهُ ضُرَّهُۥ مَرَّ كَأَن لَّمْ يَدْعُنَآ إِلَىٰ ضُرٍّۢ مَّسَّهُۥ ۚ كَذَٰلِكَ زُيِّنَ لِلْمُسْرِفِينَ مَا كَانُوا۟ يَعْمَلُونَ', 'وإذا مس الإنسن الضر دعانا لجنبه أو قاعدا أو قائما فلما كشفنا عنه ضره مر كأن لم يدعنا إلى ضر مسه  كذلك زين للمسرفين ما كانوا يعملون', NULL, 209, 'local:hafs-text.json'),
  ('hafs-10-13', 'hafs', 10, 13, 'وَلَقَدْ أَهْلَكْنَا ٱلْقُرُونَ مِن قَبْلِكُمْ لَمَّا ظَلَمُوا۟ ۙ وَجَآءَتْهُمْ رُسُلُهُم بِٱلْبَيِّنَٰتِ وَمَا كَانُوا۟ لِيُؤْمِنُوا۟ ۚ كَذَٰلِكَ نَجْزِى ٱلْقَوْمَ ٱلْمُجْرِمِينَ', 'ولقد أهلكنا القرون من قبلكم لما ظلموا  وجاءتهم رسلهم بالبينت وما كانوا ليؤمنوا  كذلك نجزى القوم المجرمين', NULL, 209, 'local:hafs-text.json'),
  ('hafs-10-14', 'hafs', 10, 14, 'ثُمَّ جَعَلْنَٰكُمْ خَلَٰٓئِفَ فِى ٱلْأَرْضِ مِنۢ بَعْدِهِمْ لِنَنظُرَ كَيْفَ تَعْمَلُونَ', 'ثم جعلنكم خلئف فى الأرض من بعدهم لننظر كيف تعملون', NULL, 209, 'local:hafs-text.json'),
  ('hafs-10-15', 'hafs', 10, 15, 'وَإِذَا تُتْلَىٰ عَلَيْهِمْ ءَايَاتُنَا بَيِّنَٰتٍۢ ۙ قَالَ ٱلَّذِينَ لَا يَرْجُونَ لِقَآءَنَا ٱئْتِ بِقُرْءَانٍ غَيْرِ هَٰذَآ أَوْ بَدِّلْهُ ۚ قُلْ مَا يَكُونُ لِىٓ أَنْ أُبَدِّلَهُۥ مِن تِلْقَآئِ نَفْسِىٓ ۖ إِنْ أَتَّبِعُ إِلَّا مَا يُوحَىٰٓ إِلَىَّ ۖ إِنِّىٓ أَخَافُ إِنْ عَصَيْتُ رَبِّى عَذَابَ يَوْمٍ عَظِيمٍۢ', 'وإذا تتلى عليهم ءاياتنا بينت  قال الذين لا يرجون لقاءنا ائت بقرءان غير هذا أو بدله  قل ما يكون لى أن أبدله من تلقائ نفسى  إن أتبع إلا ما يوحى إلى  إنى أخاف إن عصيت ربى عذاب يوم عظيم', NULL, 210, 'local:hafs-text.json'),
  ('hafs-10-16', 'hafs', 10, 16, 'قُل لَّوْ شَآءَ ٱللَّهُ مَا تَلَوْتُهُۥ عَلَيْكُمْ وَلَآ أَدْرَىٰكُم بِهِۦ ۖ فَقَدْ لَبِثْتُ فِيكُمْ عُمُرًۭا مِّن قَبْلِهِۦٓ ۚ أَفَلَا تَعْقِلُونَ', 'قل لو شاء الله ما تلوته عليكم ولا أدرىكم به  فقد لبثت فيكم عمرا من قبله  أفلا تعقلون', NULL, 210, 'local:hafs-text.json'),
  ('hafs-10-17', 'hafs', 10, 17, 'فَمَنْ أَظْلَمُ مِمَّنِ ٱفْتَرَىٰ عَلَى ٱللَّهِ كَذِبًا أَوْ كَذَّبَ بِـَٔايَٰتِهِۦٓ ۚ إِنَّهُۥ لَا يُفْلِحُ ٱلْمُجْرِمُونَ', 'فمن أظلم ممن افترى على الله كذبا أو كذب بايته  إنه لا يفلح المجرمون', NULL, 210, 'local:hafs-text.json'),
  ('hafs-10-18', 'hafs', 10, 18, 'وَيَعْبُدُونَ مِن دُونِ ٱللَّهِ مَا لَا يَضُرُّهُمْ وَلَا يَنفَعُهُمْ وَيَقُولُونَ هَٰٓؤُلَآءِ شُفَعَٰٓؤُنَا عِندَ ٱللَّهِ ۚ قُلْ أَتُنَبِّـُٔونَ ٱللَّهَ بِمَا لَا يَعْلَمُ فِى ٱلسَّمَٰوَٰتِ وَلَا فِى ٱلْأَرْضِ ۚ سُبْحَٰنَهُۥ وَتَعَٰلَىٰ عَمَّا يُشْرِكُونَ', 'ويعبدون من دون الله ما لا يضرهم ولا ينفعهم ويقولون هؤلاء شفعؤنا عند الله  قل أتنبون الله بما لا يعلم فى السموت ولا فى الأرض  سبحنه وتعلى عما يشركون', NULL, 210, 'local:hafs-text.json'),
  ('hafs-10-19', 'hafs', 10, 19, 'وَمَا كَانَ ٱلنَّاسُ إِلَّآ أُمَّةًۭ وَٰحِدَةًۭ فَٱخْتَلَفُوا۟ ۚ وَلَوْلَا كَلِمَةٌۭ سَبَقَتْ مِن رَّبِّكَ لَقُضِىَ بَيْنَهُمْ فِيمَا فِيهِ يَخْتَلِفُونَ', 'وما كان الناس إلا أمة وحدة فاختلفوا  ولولا كلمة سبقت من ربك لقضى بينهم فيما فيه يختلفون', NULL, 210, 'local:hafs-text.json'),
  ('hafs-10-20', 'hafs', 10, 20, 'وَيَقُولُونَ لَوْلَآ أُنزِلَ عَلَيْهِ ءَايَةٌۭ مِّن رَّبِّهِۦ ۖ فَقُلْ إِنَّمَا ٱلْغَيْبُ لِلَّهِ فَٱنتَظِرُوٓا۟ إِنِّى مَعَكُم مِّنَ ٱلْمُنتَظِرِينَ', 'ويقولون لولا أنزل عليه ءاية من ربه  فقل إنما الغيب لله فانتظروا إنى معكم من المنتظرين', NULL, 210, 'local:hafs-text.json'),
  ('hafs-10-21', 'hafs', 10, 21, 'وَإِذَآ أَذَقْنَا ٱلنَّاسَ رَحْمَةًۭ مِّنۢ بَعْدِ ضَرَّآءَ مَسَّتْهُمْ إِذَا لَهُم مَّكْرٌۭ فِىٓ ءَايَاتِنَا ۚ قُلِ ٱللَّهُ أَسْرَعُ مَكْرًا ۚ إِنَّ رُسُلَنَا يَكْتُبُونَ مَا تَمْكُرُونَ', 'وإذا أذقنا الناس رحمة من بعد ضراء مستهم إذا لهم مكر فى ءاياتنا  قل الله أسرع مكرا  إن رسلنا يكتبون ما تمكرون', NULL, 211, 'local:hafs-text.json'),
  ('hafs-10-22', 'hafs', 10, 22, 'هُوَ ٱلَّذِى يُسَيِّرُكُمْ فِى ٱلْبَرِّ وَٱلْبَحْرِ ۖ حَتَّىٰٓ إِذَا كُنتُمْ فِى ٱلْفُلْكِ وَجَرَيْنَ بِهِم بِرِيحٍۢ طَيِّبَةٍۢ وَفَرِحُوا۟ بِهَا جَآءَتْهَا رِيحٌ عَاصِفٌۭ وَجَآءَهُمُ ٱلْمَوْجُ مِن كُلِّ مَكَانٍۢ وَظَنُّوٓا۟ أَنَّهُمْ أُحِيطَ بِهِمْ ۙ دَعَوُا۟ ٱللَّهَ مُخْلِصِينَ لَهُ ٱلدِّينَ لَئِنْ أَنجَيْتَنَا مِنْ هَٰذِهِۦ لَنَكُونَنَّ مِنَ ٱلشَّٰكِرِينَ', 'هو الذى يسيركم فى البر والبحر  حتى إذا كنتم فى الفلك وجرين بهم بريح طيبة وفرحوا بها جاءتها ريح عاصف وجاءهم الموج من كل مكان وظنوا أنهم أحيط بهم  دعوا الله مخلصين له الدين لئن أنجيتنا من هذه لنكونن من الشكرين', NULL, 211, 'local:hafs-text.json'),
  ('hafs-10-23', 'hafs', 10, 23, 'فَلَمَّآ أَنجَىٰهُمْ إِذَا هُمْ يَبْغُونَ فِى ٱلْأَرْضِ بِغَيْرِ ٱلْحَقِّ ۗ يَٰٓأَيُّهَا ٱلنَّاسُ إِنَّمَا بَغْيُكُمْ عَلَىٰٓ أَنفُسِكُم ۖ مَّتَٰعَ ٱلْحَيَوٰةِ ٱلدُّنْيَا ۖ ثُمَّ إِلَيْنَا مَرْجِعُكُمْ فَنُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ', 'فلما أنجىهم إذا هم يبغون فى الأرض بغير الحق  يأيها الناس إنما بغيكم على أنفسكم  متع الحيوة الدنيا  ثم إلينا مرجعكم فننبئكم بما كنتم تعملون', NULL, 211, 'local:hafs-text.json'),
  ('hafs-10-24', 'hafs', 10, 24, 'إِنَّمَا مَثَلُ ٱلْحَيَوٰةِ ٱلدُّنْيَا كَمَآءٍ أَنزَلْنَٰهُ مِنَ ٱلسَّمَآءِ فَٱخْتَلَطَ بِهِۦ نَبَاتُ ٱلْأَرْضِ مِمَّا يَأْكُلُ ٱلنَّاسُ وَٱلْأَنْعَٰمُ حَتَّىٰٓ إِذَآ أَخَذَتِ ٱلْأَرْضُ زُخْرُفَهَا وَٱزَّيَّنَتْ وَظَنَّ أَهْلُهَآ أَنَّهُمْ قَٰدِرُونَ عَلَيْهَآ أَتَىٰهَآ أَمْرُنَا لَيْلًا أَوْ نَهَارًۭا فَجَعَلْنَٰهَا حَصِيدًۭا كَأَن لَّمْ تَغْنَ بِٱلْأَمْسِ ۚ كَذَٰلِكَ نُفَصِّلُ ٱلْءَايَٰتِ لِقَوْمٍۢ يَتَفَكَّرُونَ', 'إنما مثل الحيوة الدنيا كماء أنزلنه من السماء فاختلط به نبات الأرض مما يأكل الناس والأنعم حتى إذا أخذت الأرض زخرفها وازينت وظن أهلها أنهم قدرون عليها أتىها أمرنا ليلا أو نهارا فجعلنها حصيدا كأن لم تغن بالأمس  كذلك نفصل الءايت لقوم يتفكرون', NULL, 211, 'local:hafs-text.json'),
  ('hafs-10-25', 'hafs', 10, 25, 'وَٱللَّهُ يَدْعُوٓا۟ إِلَىٰ دَارِ ٱلسَّلَٰمِ وَيَهْدِى مَن يَشَآءُ إِلَىٰ صِرَٰطٍۢ مُّسْتَقِيمٍۢ', 'والله يدعوا إلى دار السلم ويهدى من يشاء إلى صرط مستقيم', NULL, 211, 'local:hafs-text.json'),
  ('hafs-10-26', 'hafs', 10, 26, '۞ لِّلَّذِينَ أَحْسَنُوا۟ ٱلْحُسْنَىٰ وَزِيَادَةٌۭ ۖ وَلَا يَرْهَقُ وُجُوهَهُمْ قَتَرٌۭ وَلَا ذِلَّةٌ ۚ أُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلْجَنَّةِ ۖ هُمْ فِيهَا خَٰلِدُونَ', 'للذين أحسنوا الحسنى وزيادة  ولا يرهق وجوههم قتر ولا ذلة  أولئك أصحب الجنة  هم فيها خلدون', NULL, 212, 'local:hafs-text.json'),
  ('hafs-10-27', 'hafs', 10, 27, 'وَٱلَّذِينَ كَسَبُوا۟ ٱلسَّيِّـَٔاتِ جَزَآءُ سَيِّئَةٍۭ بِمِثْلِهَا وَتَرْهَقُهُمْ ذِلَّةٌۭ ۖ مَّا لَهُم مِّنَ ٱللَّهِ مِنْ عَاصِمٍۢ ۖ كَأَنَّمَآ أُغْشِيَتْ وُجُوهُهُمْ قِطَعًۭا مِّنَ ٱلَّيْلِ مُظْلِمًا ۚ أُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلنَّارِ ۖ هُمْ فِيهَا خَٰلِدُونَ', 'والذين كسبوا السيات جزاء سيئة بمثلها وترهقهم ذلة  ما لهم من الله من عاصم  كأنما أغشيت وجوههم قطعا من اليل مظلما  أولئك أصحب النار  هم فيها خلدون', NULL, 212, 'local:hafs-text.json'),
  ('hafs-10-28', 'hafs', 10, 28, 'وَيَوْمَ نَحْشُرُهُمْ جَمِيعًۭا ثُمَّ نَقُولُ لِلَّذِينَ أَشْرَكُوا۟ مَكَانَكُمْ أَنتُمْ وَشُرَكَآؤُكُمْ ۚ فَزَيَّلْنَا بَيْنَهُمْ ۖ وَقَالَ شُرَكَآؤُهُم مَّا كُنتُمْ إِيَّانَا تَعْبُدُونَ', 'ويوم نحشرهم جميعا ثم نقول للذين أشركوا مكانكم أنتم وشركاؤكم  فزيلنا بينهم  وقال شركاؤهم ما كنتم إيانا تعبدون', NULL, 212, 'local:hafs-text.json'),
  ('hafs-10-29', 'hafs', 10, 29, 'فَكَفَىٰ بِٱللَّهِ شَهِيدًۢا بَيْنَنَا وَبَيْنَكُمْ إِن كُنَّا عَنْ عِبَادَتِكُمْ لَغَٰفِلِينَ', 'فكفى بالله شهيدا بيننا وبينكم إن كنا عن عبادتكم لغفلين', NULL, 212, 'local:hafs-text.json'),
  ('hafs-10-30', 'hafs', 10, 30, 'هُنَالِكَ تَبْلُوا۟ كُلُّ نَفْسٍۢ مَّآ أَسْلَفَتْ ۚ وَرُدُّوٓا۟ إِلَى ٱللَّهِ مَوْلَىٰهُمُ ٱلْحَقِّ ۖ وَضَلَّ عَنْهُم مَّا كَانُوا۟ يَفْتَرُونَ', 'هنالك تبلوا كل نفس ما أسلفت  وردوا إلى الله مولىهم الحق  وضل عنهم ما كانوا يفترون', NULL, 212, 'local:hafs-text.json'),
  ('hafs-10-31', 'hafs', 10, 31, 'قُلْ مَن يَرْزُقُكُم مِّنَ ٱلسَّمَآءِ وَٱلْأَرْضِ أَمَّن يَمْلِكُ ٱلسَّمْعَ وَٱلْأَبْصَٰرَ وَمَن يُخْرِجُ ٱلْحَىَّ مِنَ ٱلْمَيِّتِ وَيُخْرِجُ ٱلْمَيِّتَ مِنَ ٱلْحَىِّ وَمَن يُدَبِّرُ ٱلْأَمْرَ ۚ فَسَيَقُولُونَ ٱللَّهُ ۚ فَقُلْ أَفَلَا تَتَّقُونَ', 'قل من يرزقكم من السماء والأرض أمن يملك السمع والأبصر ومن يخرج الحى من الميت ويخرج الميت من الحى ومن يدبر الأمر  فسيقولون الله  فقل أفلا تتقون', NULL, 212, 'local:hafs-text.json'),
  ('hafs-10-32', 'hafs', 10, 32, 'فَذَٰلِكُمُ ٱللَّهُ رَبُّكُمُ ٱلْحَقُّ ۖ فَمَاذَا بَعْدَ ٱلْحَقِّ إِلَّا ٱلضَّلَٰلُ ۖ فَأَنَّىٰ تُصْرَفُونَ', 'فذلكم الله ربكم الحق  فماذا بعد الحق إلا الضلل  فأنى تصرفون', NULL, 212, 'local:hafs-text.json'),
  ('hafs-10-33', 'hafs', 10, 33, 'كَذَٰلِكَ حَقَّتْ كَلِمَتُ رَبِّكَ عَلَى ٱلَّذِينَ فَسَقُوٓا۟ أَنَّهُمْ لَا يُؤْمِنُونَ', 'كذلك حقت كلمت ربك على الذين فسقوا أنهم لا يؤمنون', NULL, 212, 'local:hafs-text.json'),
  ('hafs-10-34', 'hafs', 10, 34, 'قُلْ هَلْ مِن شُرَكَآئِكُم مَّن يَبْدَؤُا۟ ٱلْخَلْقَ ثُمَّ يُعِيدُهُۥ ۚ قُلِ ٱللَّهُ يَبْدَؤُا۟ ٱلْخَلْقَ ثُمَّ يُعِيدُهُۥ ۖ فَأَنَّىٰ تُؤْفَكُونَ', 'قل هل من شركائكم من يبدؤا الخلق ثم يعيده  قل الله يبدؤا الخلق ثم يعيده  فأنى تؤفكون', NULL, 213, 'local:hafs-text.json'),
  ('hafs-10-35', 'hafs', 10, 35, 'قُلْ هَلْ مِن شُرَكَآئِكُم مَّن يَهْدِىٓ إِلَى ٱلْحَقِّ ۚ قُلِ ٱللَّهُ يَهْدِى لِلْحَقِّ ۗ أَفَمَن يَهْدِىٓ إِلَى ٱلْحَقِّ أَحَقُّ أَن يُتَّبَعَ أَمَّن لَّا يَهِدِّىٓ إِلَّآ أَن يُهْدَىٰ ۖ فَمَا لَكُمْ كَيْفَ تَحْكُمُونَ', 'قل هل من شركائكم من يهدى إلى الحق  قل الله يهدى للحق  أفمن يهدى إلى الحق أحق أن يتبع أمن لا يهدى إلا أن يهدى  فما لكم كيف تحكمون', NULL, 213, 'local:hafs-text.json'),
  ('hafs-10-36', 'hafs', 10, 36, 'وَمَا يَتَّبِعُ أَكْثَرُهُمْ إِلَّا ظَنًّا ۚ إِنَّ ٱلظَّنَّ لَا يُغْنِى مِنَ ٱلْحَقِّ شَيْـًٔا ۚ إِنَّ ٱللَّهَ عَلِيمٌۢ بِمَا يَفْعَلُونَ', 'وما يتبع أكثرهم إلا ظنا  إن الظن لا يغنى من الحق شيا  إن الله عليم بما يفعلون', NULL, 213, 'local:hafs-text.json'),
  ('hafs-10-37', 'hafs', 10, 37, 'وَمَا كَانَ هَٰذَا ٱلْقُرْءَانُ أَن يُفْتَرَىٰ مِن دُونِ ٱللَّهِ وَلَٰكِن تَصْدِيقَ ٱلَّذِى بَيْنَ يَدَيْهِ وَتَفْصِيلَ ٱلْكِتَٰبِ لَا رَيْبَ فِيهِ مِن رَّبِّ ٱلْعَٰلَمِينَ', 'وما كان هذا القرءان أن يفترى من دون الله ولكن تصديق الذى بين يديه وتفصيل الكتب لا ريب فيه من رب العلمين', NULL, 213, 'local:hafs-text.json'),
  ('hafs-10-38', 'hafs', 10, 38, 'أَمْ يَقُولُونَ ٱفْتَرَىٰهُ ۖ قُلْ فَأْتُوا۟ بِسُورَةٍۢ مِّثْلِهِۦ وَٱدْعُوا۟ مَنِ ٱسْتَطَعْتُم مِّن دُونِ ٱللَّهِ إِن كُنتُمْ صَٰدِقِينَ', 'أم يقولون افترىه  قل فأتوا بسورة مثله وادعوا من استطعتم من دون الله إن كنتم صدقين', NULL, 213, 'local:hafs-text.json'),
  ('hafs-10-39', 'hafs', 10, 39, 'بَلْ كَذَّبُوا۟ بِمَا لَمْ يُحِيطُوا۟ بِعِلْمِهِۦ وَلَمَّا يَأْتِهِمْ تَأْوِيلُهُۥ ۚ كَذَٰلِكَ كَذَّبَ ٱلَّذِينَ مِن قَبْلِهِمْ ۖ فَٱنظُرْ كَيْفَ كَانَ عَٰقِبَةُ ٱلظَّٰلِمِينَ', 'بل كذبوا بما لم يحيطوا بعلمه ولما يأتهم تأويله  كذلك كذب الذين من قبلهم  فانظر كيف كان عقبة الظلمين', NULL, 213, 'local:hafs-text.json'),
  ('hafs-10-40', 'hafs', 10, 40, 'وَمِنْهُم مَّن يُؤْمِنُ بِهِۦ وَمِنْهُم مَّن لَّا يُؤْمِنُ بِهِۦ ۚ وَرَبُّكَ أَعْلَمُ بِٱلْمُفْسِدِينَ', 'ومنهم من يؤمن به ومنهم من لا يؤمن به  وربك أعلم بالمفسدين', NULL, 213, 'local:hafs-text.json'),
  ('hafs-10-41', 'hafs', 10, 41, 'وَإِن كَذَّبُوكَ فَقُل لِّى عَمَلِى وَلَكُمْ عَمَلُكُمْ ۖ أَنتُم بَرِيٓـُٔونَ مِمَّآ أَعْمَلُ وَأَنَا۠ بَرِىٓءٌۭ مِّمَّا تَعْمَلُونَ', 'وإن كذبوك فقل لى عملى ولكم عملكم  أنتم بريون مما أعمل وأنا برىء مما تعملون', NULL, 213, 'local:hafs-text.json'),
  ('hafs-10-42', 'hafs', 10, 42, 'وَمِنْهُم مَّن يَسْتَمِعُونَ إِلَيْكَ ۚ أَفَأَنتَ تُسْمِعُ ٱلصُّمَّ وَلَوْ كَانُوا۟ لَا يَعْقِلُونَ', 'ومنهم من يستمعون إليك  أفأنت تسمع الصم ولو كانوا لا يعقلون', NULL, 213, 'local:hafs-text.json'),
  ('hafs-10-43', 'hafs', 10, 43, 'وَمِنْهُم مَّن يَنظُرُ إِلَيْكَ ۚ أَفَأَنتَ تَهْدِى ٱلْعُمْىَ وَلَوْ كَانُوا۟ لَا يُبْصِرُونَ', 'ومنهم من ينظر إليك  أفأنت تهدى العمى ولو كانوا لا يبصرون', NULL, 214, 'local:hafs-text.json'),
  ('hafs-10-44', 'hafs', 10, 44, 'إِنَّ ٱللَّهَ لَا يَظْلِمُ ٱلنَّاسَ شَيْـًۭٔا وَلَٰكِنَّ ٱلنَّاسَ أَنفُسَهُمْ يَظْلِمُونَ', 'إن الله لا يظلم الناس شيا ولكن الناس أنفسهم يظلمون', NULL, 214, 'local:hafs-text.json'),
  ('hafs-10-45', 'hafs', 10, 45, 'وَيَوْمَ يَحْشُرُهُمْ كَأَن لَّمْ يَلْبَثُوٓا۟ إِلَّا سَاعَةًۭ مِّنَ ٱلنَّهَارِ يَتَعَارَفُونَ بَيْنَهُمْ ۚ قَدْ خَسِرَ ٱلَّذِينَ كَذَّبُوا۟ بِلِقَآءِ ٱللَّهِ وَمَا كَانُوا۟ مُهْتَدِينَ', 'ويوم يحشرهم كأن لم يلبثوا إلا ساعة من النهار يتعارفون بينهم  قد خسر الذين كذبوا بلقاء الله وما كانوا مهتدين', NULL, 214, 'local:hafs-text.json'),
  ('hafs-10-46', 'hafs', 10, 46, 'وَإِمَّا نُرِيَنَّكَ بَعْضَ ٱلَّذِى نَعِدُهُمْ أَوْ نَتَوَفَّيَنَّكَ فَإِلَيْنَا مَرْجِعُهُمْ ثُمَّ ٱللَّهُ شَهِيدٌ عَلَىٰ مَا يَفْعَلُونَ', 'وإما نرينك بعض الذى نعدهم أو نتوفينك فإلينا مرجعهم ثم الله شهيد على ما يفعلون', NULL, 214, 'local:hafs-text.json'),
  ('hafs-10-47', 'hafs', 10, 47, 'وَلِكُلِّ أُمَّةٍۢ رَّسُولٌۭ ۖ فَإِذَا جَآءَ رَسُولُهُمْ قُضِىَ بَيْنَهُم بِٱلْقِسْطِ وَهُمْ لَا يُظْلَمُونَ', 'ولكل أمة رسول  فإذا جاء رسولهم قضى بينهم بالقسط وهم لا يظلمون', NULL, 214, 'local:hafs-text.json'),
  ('hafs-10-48', 'hafs', 10, 48, 'وَيَقُولُونَ مَتَىٰ هَٰذَا ٱلْوَعْدُ إِن كُنتُمْ صَٰدِقِينَ', 'ويقولون متى هذا الوعد إن كنتم صدقين', NULL, 214, 'local:hafs-text.json'),
  ('hafs-10-49', 'hafs', 10, 49, 'قُل لَّآ أَمْلِكُ لِنَفْسِى ضَرًّۭا وَلَا نَفْعًا إِلَّا مَا شَآءَ ٱللَّهُ ۗ لِكُلِّ أُمَّةٍ أَجَلٌ ۚ إِذَا جَآءَ أَجَلُهُمْ فَلَا يَسْتَـْٔخِرُونَ سَاعَةًۭ ۖ وَلَا يَسْتَقْدِمُونَ', 'قل لا أملك لنفسى ضرا ولا نفعا إلا ما شاء الله  لكل أمة أجل  إذا جاء أجلهم فلا يستخرون ساعة  ولا يستقدمون', NULL, 214, 'local:hafs-text.json'),
  ('hafs-10-50', 'hafs', 10, 50, 'قُلْ أَرَءَيْتُمْ إِنْ أَتَىٰكُمْ عَذَابُهُۥ بَيَٰتًا أَوْ نَهَارًۭا مَّاذَا يَسْتَعْجِلُ مِنْهُ ٱلْمُجْرِمُونَ', 'قل أرءيتم إن أتىكم عذابه بيتا أو نهارا ماذا يستعجل منه المجرمون', NULL, 214, 'local:hafs-text.json'),
  ('hafs-10-51', 'hafs', 10, 51, 'أَثُمَّ إِذَا مَا وَقَعَ ءَامَنتُم بِهِۦٓ ۚ ءَآلْـَٰٔنَ وَقَدْ كُنتُم بِهِۦ تَسْتَعْجِلُونَ', 'أثم إذا ما وقع ءامنتم به  ءالن وقد كنتم به تستعجلون', NULL, 214, 'local:hafs-text.json'),
  ('hafs-10-52', 'hafs', 10, 52, 'ثُمَّ قِيلَ لِلَّذِينَ ظَلَمُوا۟ ذُوقُوا۟ عَذَابَ ٱلْخُلْدِ هَلْ تُجْزَوْنَ إِلَّا بِمَا كُنتُمْ تَكْسِبُونَ', 'ثم قيل للذين ظلموا ذوقوا عذاب الخلد هل تجزون إلا بما كنتم تكسبون', NULL, 214, 'local:hafs-text.json'),
  ('hafs-10-53', 'hafs', 10, 53, '۞ وَيَسْتَنۢبِـُٔونَكَ أَحَقٌّ هُوَ ۖ قُلْ إِى وَرَبِّىٓ إِنَّهُۥ لَحَقٌّۭ ۖ وَمَآ أَنتُم بِمُعْجِزِينَ', 'ويستنبونك أحق هو  قل إى وربى إنه لحق  وما أنتم بمعجزين', NULL, 214, 'local:hafs-text.json'),
  ('hafs-10-54', 'hafs', 10, 54, 'وَلَوْ أَنَّ لِكُلِّ نَفْسٍۢ ظَلَمَتْ مَا فِى ٱلْأَرْضِ لَٱفْتَدَتْ بِهِۦ ۗ وَأَسَرُّوا۟ ٱلنَّدَامَةَ لَمَّا رَأَوُا۟ ٱلْعَذَابَ ۖ وَقُضِىَ بَيْنَهُم بِٱلْقِسْطِ ۚ وَهُمْ لَا يُظْلَمُونَ', 'ولو أن لكل نفس ظلمت ما فى الأرض لافتدت به  وأسروا الندامة لما رأوا العذاب  وقضى بينهم بالقسط  وهم لا يظلمون', NULL, 215, 'local:hafs-text.json'),
  ('hafs-10-55', 'hafs', 10, 55, 'أَلَآ إِنَّ لِلَّهِ مَا فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ ۗ أَلَآ إِنَّ وَعْدَ ٱللَّهِ حَقٌّۭ وَلَٰكِنَّ أَكْثَرَهُمْ لَا يَعْلَمُونَ', 'ألا إن لله ما فى السموت والأرض  ألا إن وعد الله حق ولكن أكثرهم لا يعلمون', NULL, 215, 'local:hafs-text.json'),
  ('hafs-10-56', 'hafs', 10, 56, 'هُوَ يُحْىِۦ وَيُمِيتُ وَإِلَيْهِ تُرْجَعُونَ', 'هو يحى ويميت وإليه ترجعون', NULL, 215, 'local:hafs-text.json'),
  ('hafs-10-57', 'hafs', 10, 57, 'يَٰٓأَيُّهَا ٱلنَّاسُ قَدْ جَآءَتْكُم مَّوْعِظَةٌۭ مِّن رَّبِّكُمْ وَشِفَآءٌۭ لِّمَا فِى ٱلصُّدُورِ وَهُدًۭى وَرَحْمَةٌۭ لِّلْمُؤْمِنِينَ', 'يأيها الناس قد جاءتكم موعظة من ربكم وشفاء لما فى الصدور وهدى ورحمة للمؤمنين', NULL, 215, 'local:hafs-text.json'),
  ('hafs-10-58', 'hafs', 10, 58, 'قُلْ بِفَضْلِ ٱللَّهِ وَبِرَحْمَتِهِۦ فَبِذَٰلِكَ فَلْيَفْرَحُوا۟ هُوَ خَيْرٌۭ مِّمَّا يَجْمَعُونَ', 'قل بفضل الله وبرحمته فبذلك فليفرحوا هو خير مما يجمعون', NULL, 215, 'local:hafs-text.json'),
  ('hafs-10-59', 'hafs', 10, 59, 'قُلْ أَرَءَيْتُم مَّآ أَنزَلَ ٱللَّهُ لَكُم مِّن رِّزْقٍۢ فَجَعَلْتُم مِّنْهُ حَرَامًۭا وَحَلَٰلًۭا قُلْ ءَآللَّهُ أَذِنَ لَكُمْ ۖ أَمْ عَلَى ٱللَّهِ تَفْتَرُونَ', 'قل أرءيتم ما أنزل الله لكم من رزق فجعلتم منه حراما وحللا قل ءالله أذن لكم  أم على الله تفترون', NULL, 215, 'local:hafs-text.json'),
  ('hafs-10-60', 'hafs', 10, 60, 'وَمَا ظَنُّ ٱلَّذِينَ يَفْتَرُونَ عَلَى ٱللَّهِ ٱلْكَذِبَ يَوْمَ ٱلْقِيَٰمَةِ ۗ إِنَّ ٱللَّهَ لَذُو فَضْلٍ عَلَى ٱلنَّاسِ وَلَٰكِنَّ أَكْثَرَهُمْ لَا يَشْكُرُونَ', 'وما ظن الذين يفترون على الله الكذب يوم القيمة  إن الله لذو فضل على الناس ولكن أكثرهم لا يشكرون', NULL, 215, 'local:hafs-text.json'),
  ('hafs-10-61', 'hafs', 10, 61, 'وَمَا تَكُونُ فِى شَأْنٍۢ وَمَا تَتْلُوا۟ مِنْهُ مِن قُرْءَانٍۢ وَلَا تَعْمَلُونَ مِنْ عَمَلٍ إِلَّا كُنَّا عَلَيْكُمْ شُهُودًا إِذْ تُفِيضُونَ فِيهِ ۚ وَمَا يَعْزُبُ عَن رَّبِّكَ مِن مِّثْقَالِ ذَرَّةٍۢ فِى ٱلْأَرْضِ وَلَا فِى ٱلسَّمَآءِ وَلَآ أَصْغَرَ مِن ذَٰلِكَ وَلَآ أَكْبَرَ إِلَّا فِى كِتَٰبٍۢ مُّبِينٍ', 'وما تكون فى شأن وما تتلوا منه من قرءان ولا تعملون من عمل إلا كنا عليكم شهودا إذ تفيضون فيه  وما يعزب عن ربك من مثقال ذرة فى الأرض ولا فى السماء ولا أصغر من ذلك ولا أكبر إلا فى كتب مبين', NULL, 215, 'local:hafs-text.json'),
  ('hafs-10-62', 'hafs', 10, 62, 'أَلَآ إِنَّ أَوْلِيَآءَ ٱللَّهِ لَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ', 'ألا إن أولياء الله لا خوف عليهم ولا هم يحزنون', NULL, 216, 'local:hafs-text.json'),
  ('hafs-10-63', 'hafs', 10, 63, 'ٱلَّذِينَ ءَامَنُوا۟ وَكَانُوا۟ يَتَّقُونَ', 'الذين ءامنوا وكانوا يتقون', NULL, 216, 'local:hafs-text.json'),
  ('hafs-10-64', 'hafs', 10, 64, 'لَهُمُ ٱلْبُشْرَىٰ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا وَفِى ٱلْءَاخِرَةِ ۚ لَا تَبْدِيلَ لِكَلِمَٰتِ ٱللَّهِ ۚ ذَٰلِكَ هُوَ ٱلْفَوْزُ ٱلْعَظِيمُ', 'لهم البشرى فى الحيوة الدنيا وفى الءاخرة  لا تبديل لكلمت الله  ذلك هو الفوز العظيم', NULL, 216, 'local:hafs-text.json'),
  ('hafs-10-65', 'hafs', 10, 65, 'وَلَا يَحْزُنكَ قَوْلُهُمْ ۘ إِنَّ ٱلْعِزَّةَ لِلَّهِ جَمِيعًا ۚ هُوَ ٱلسَّمِيعُ ٱلْعَلِيمُ', 'ولا يحزنك قولهم  إن العزة لله جميعا  هو السميع العليم', NULL, 216, 'local:hafs-text.json'),
  ('hafs-10-66', 'hafs', 10, 66, 'أَلَآ إِنَّ لِلَّهِ مَن فِى ٱلسَّمَٰوَٰتِ وَمَن فِى ٱلْأَرْضِ ۗ وَمَا يَتَّبِعُ ٱلَّذِينَ يَدْعُونَ مِن دُونِ ٱللَّهِ شُرَكَآءَ ۚ إِن يَتَّبِعُونَ إِلَّا ٱلظَّنَّ وَإِنْ هُمْ إِلَّا يَخْرُصُونَ', 'ألا إن لله من فى السموت ومن فى الأرض  وما يتبع الذين يدعون من دون الله شركاء  إن يتبعون إلا الظن وإن هم إلا يخرصون', NULL, 216, 'local:hafs-text.json'),
  ('hafs-10-67', 'hafs', 10, 67, 'هُوَ ٱلَّذِى جَعَلَ لَكُمُ ٱلَّيْلَ لِتَسْكُنُوا۟ فِيهِ وَٱلنَّهَارَ مُبْصِرًا ۚ إِنَّ فِى ذَٰلِكَ لَءَايَٰتٍۢ لِّقَوْمٍۢ يَسْمَعُونَ', 'هو الذى جعل لكم اليل لتسكنوا فيه والنهار مبصرا  إن فى ذلك لءايت لقوم يسمعون', NULL, 216, 'local:hafs-text.json'),
  ('hafs-10-68', 'hafs', 10, 68, 'قَالُوا۟ ٱتَّخَذَ ٱللَّهُ وَلَدًۭا ۗ سُبْحَٰنَهُۥ ۖ هُوَ ٱلْغَنِىُّ ۖ لَهُۥ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ ۚ إِنْ عِندَكُم مِّن سُلْطَٰنٍۭ بِهَٰذَآ ۚ أَتَقُولُونَ عَلَى ٱللَّهِ مَا لَا تَعْلَمُونَ', 'قالوا اتخذ الله ولدا  سبحنه  هو الغنى  له ما فى السموت وما فى الأرض  إن عندكم من سلطن بهذا  أتقولون على الله ما لا تعلمون', NULL, 216, 'local:hafs-text.json'),
  ('hafs-10-69', 'hafs', 10, 69, 'قُلْ إِنَّ ٱلَّذِينَ يَفْتَرُونَ عَلَى ٱللَّهِ ٱلْكَذِبَ لَا يُفْلِحُونَ', 'قل إن الذين يفترون على الله الكذب لا يفلحون', NULL, 216, 'local:hafs-text.json'),
  ('hafs-10-70', 'hafs', 10, 70, 'مَتَٰعٌۭ فِى ٱلدُّنْيَا ثُمَّ إِلَيْنَا مَرْجِعُهُمْ ثُمَّ نُذِيقُهُمُ ٱلْعَذَابَ ٱلشَّدِيدَ بِمَا كَانُوا۟ يَكْفُرُونَ', 'متع فى الدنيا ثم إلينا مرجعهم ثم نذيقهم العذاب الشديد بما كانوا يكفرون', NULL, 216, 'local:hafs-text.json'),
  ('hafs-10-71', 'hafs', 10, 71, '۞ وَٱتْلُ عَلَيْهِمْ نَبَأَ نُوحٍ إِذْ قَالَ لِقَوْمِهِۦ يَٰقَوْمِ إِن كَانَ كَبُرَ عَلَيْكُم مَّقَامِى وَتَذْكِيرِى بِـَٔايَٰتِ ٱللَّهِ فَعَلَى ٱللَّهِ تَوَكَّلْتُ فَأَجْمِعُوٓا۟ أَمْرَكُمْ وَشُرَكَآءَكُمْ ثُمَّ لَا يَكُنْ أَمْرُكُمْ عَلَيْكُمْ غُمَّةًۭ ثُمَّ ٱقْضُوٓا۟ إِلَىَّ وَلَا تُنظِرُونِ', 'واتل عليهم نبأ نوح إذ قال لقومه يقوم إن كان كبر عليكم مقامى وتذكيرى بايت الله فعلى الله توكلت فأجمعوا أمركم وشركاءكم ثم لا يكن أمركم عليكم غمة ثم اقضوا إلى ولا تنظرون', NULL, 217, 'local:hafs-text.json'),
  ('hafs-10-72', 'hafs', 10, 72, 'فَإِن تَوَلَّيْتُمْ فَمَا سَأَلْتُكُم مِّنْ أَجْرٍ ۖ إِنْ أَجْرِىَ إِلَّا عَلَى ٱللَّهِ ۖ وَأُمِرْتُ أَنْ أَكُونَ مِنَ ٱلْمُسْلِمِينَ', 'فإن توليتم فما سألتكم من أجر  إن أجرى إلا على الله  وأمرت أن أكون من المسلمين', NULL, 217, 'local:hafs-text.json'),
  ('hafs-10-73', 'hafs', 10, 73, 'فَكَذَّبُوهُ فَنَجَّيْنَٰهُ وَمَن مَّعَهُۥ فِى ٱلْفُلْكِ وَجَعَلْنَٰهُمْ خَلَٰٓئِفَ وَأَغْرَقْنَا ٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَٰتِنَا ۖ فَٱنظُرْ كَيْفَ كَانَ عَٰقِبَةُ ٱلْمُنذَرِينَ', 'فكذبوه فنجينه ومن معه فى الفلك وجعلنهم خلئف وأغرقنا الذين كذبوا بايتنا  فانظر كيف كان عقبة المنذرين', NULL, 217, 'local:hafs-text.json'),
  ('hafs-10-74', 'hafs', 10, 74, 'ثُمَّ بَعَثْنَا مِنۢ بَعْدِهِۦ رُسُلًا إِلَىٰ قَوْمِهِمْ فَجَآءُوهُم بِٱلْبَيِّنَٰتِ فَمَا كَانُوا۟ لِيُؤْمِنُوا۟ بِمَا كَذَّبُوا۟ بِهِۦ مِن قَبْلُ ۚ كَذَٰلِكَ نَطْبَعُ عَلَىٰ قُلُوبِ ٱلْمُعْتَدِينَ', 'ثم بعثنا من بعده رسلا إلى قومهم فجاءوهم بالبينت فما كانوا ليؤمنوا بما كذبوا به من قبل  كذلك نطبع على قلوب المعتدين', NULL, 217, 'local:hafs-text.json'),
  ('hafs-10-75', 'hafs', 10, 75, 'ثُمَّ بَعَثْنَا مِنۢ بَعْدِهِم مُّوسَىٰ وَهَٰرُونَ إِلَىٰ فِرْعَوْنَ وَمَلَإِي۟هِۦ بِـَٔايَٰتِنَا فَٱسْتَكْبَرُوا۟ وَكَانُوا۟ قَوْمًۭا مُّجْرِمِينَ', 'ثم بعثنا من بعدهم موسى وهرون إلى فرعون وملإيه بايتنا فاستكبروا وكانوا قوما مجرمين', NULL, 217, 'local:hafs-text.json'),
  ('hafs-10-76', 'hafs', 10, 76, 'فَلَمَّا جَآءَهُمُ ٱلْحَقُّ مِنْ عِندِنَا قَالُوٓا۟ إِنَّ هَٰذَا لَسِحْرٌۭ مُّبِينٌۭ', 'فلما جاءهم الحق من عندنا قالوا إن هذا لسحر مبين', NULL, 217, 'local:hafs-text.json'),
  ('hafs-10-77', 'hafs', 10, 77, 'قَالَ مُوسَىٰٓ أَتَقُولُونَ لِلْحَقِّ لَمَّا جَآءَكُمْ ۖ أَسِحْرٌ هَٰذَا وَلَا يُفْلِحُ ٱلسَّٰحِرُونَ', 'قال موسى أتقولون للحق لما جاءكم  أسحر هذا ولا يفلح السحرون', NULL, 217, 'local:hafs-text.json'),
  ('hafs-10-78', 'hafs', 10, 78, 'قَالُوٓا۟ أَجِئْتَنَا لِتَلْفِتَنَا عَمَّا وَجَدْنَا عَلَيْهِ ءَابَآءَنَا وَتَكُونَ لَكُمَا ٱلْكِبْرِيَآءُ فِى ٱلْأَرْضِ وَمَا نَحْنُ لَكُمَا بِمُؤْمِنِينَ', 'قالوا أجئتنا لتلفتنا عما وجدنا عليه ءاباءنا وتكون لكما الكبرياء فى الأرض وما نحن لكما بمؤمنين', NULL, 217, 'local:hafs-text.json'),
  ('hafs-10-79', 'hafs', 10, 79, 'وَقَالَ فِرْعَوْنُ ٱئْتُونِى بِكُلِّ سَٰحِرٍ عَلِيمٍۢ', 'وقال فرعون ائتونى بكل سحر عليم', NULL, 218, 'local:hafs-text.json'),
  ('hafs-10-80', 'hafs', 10, 80, 'فَلَمَّا جَآءَ ٱلسَّحَرَةُ قَالَ لَهُم مُّوسَىٰٓ أَلْقُوا۟ مَآ أَنتُم مُّلْقُونَ', 'فلما جاء السحرة قال لهم موسى ألقوا ما أنتم ملقون', NULL, 218, 'local:hafs-text.json'),
  ('hafs-10-81', 'hafs', 10, 81, 'فَلَمَّآ أَلْقَوْا۟ قَالَ مُوسَىٰ مَا جِئْتُم بِهِ ٱلسِّحْرُ ۖ إِنَّ ٱللَّهَ سَيُبْطِلُهُۥٓ ۖ إِنَّ ٱللَّهَ لَا يُصْلِحُ عَمَلَ ٱلْمُفْسِدِينَ', 'فلما ألقوا قال موسى ما جئتم به السحر  إن الله سيبطله  إن الله لا يصلح عمل المفسدين', NULL, 218, 'local:hafs-text.json'),
  ('hafs-10-82', 'hafs', 10, 82, 'وَيُحِقُّ ٱللَّهُ ٱلْحَقَّ بِكَلِمَٰتِهِۦ وَلَوْ كَرِهَ ٱلْمُجْرِمُونَ', 'ويحق الله الحق بكلمته ولو كره المجرمون', NULL, 218, 'local:hafs-text.json'),
  ('hafs-10-83', 'hafs', 10, 83, 'فَمَآ ءَامَنَ لِمُوسَىٰٓ إِلَّا ذُرِّيَّةٌۭ مِّن قَوْمِهِۦ عَلَىٰ خَوْفٍۢ مِّن فِرْعَوْنَ وَمَلَإِي۟هِمْ أَن يَفْتِنَهُمْ ۚ وَإِنَّ فِرْعَوْنَ لَعَالٍۢ فِى ٱلْأَرْضِ وَإِنَّهُۥ لَمِنَ ٱلْمُسْرِفِينَ', 'فما ءامن لموسى إلا ذرية من قومه على خوف من فرعون وملإيهم أن يفتنهم  وإن فرعون لعال فى الأرض وإنه لمن المسرفين', NULL, 218, 'local:hafs-text.json'),
  ('hafs-10-84', 'hafs', 10, 84, 'وَقَالَ مُوسَىٰ يَٰقَوْمِ إِن كُنتُمْ ءَامَنتُم بِٱللَّهِ فَعَلَيْهِ تَوَكَّلُوٓا۟ إِن كُنتُم مُّسْلِمِينَ', 'وقال موسى يقوم إن كنتم ءامنتم بالله فعليه توكلوا إن كنتم مسلمين', NULL, 218, 'local:hafs-text.json'),
  ('hafs-10-85', 'hafs', 10, 85, 'فَقَالُوا۟ عَلَى ٱللَّهِ تَوَكَّلْنَا رَبَّنَا لَا تَجْعَلْنَا فِتْنَةًۭ لِّلْقَوْمِ ٱلظَّٰلِمِينَ', 'فقالوا على الله توكلنا ربنا لا تجعلنا فتنة للقوم الظلمين', NULL, 218, 'local:hafs-text.json'),
  ('hafs-10-86', 'hafs', 10, 86, 'وَنَجِّنَا بِرَحْمَتِكَ مِنَ ٱلْقَوْمِ ٱلْكَٰفِرِينَ', 'ونجنا برحمتك من القوم الكفرين', NULL, 218, 'local:hafs-text.json'),
  ('hafs-10-87', 'hafs', 10, 87, 'وَأَوْحَيْنَآ إِلَىٰ مُوسَىٰ وَأَخِيهِ أَن تَبَوَّءَا لِقَوْمِكُمَا بِمِصْرَ بُيُوتًۭا وَٱجْعَلُوا۟ بُيُوتَكُمْ قِبْلَةًۭ وَأَقِيمُوا۟ ٱلصَّلَوٰةَ ۗ وَبَشِّرِ ٱلْمُؤْمِنِينَ', 'وأوحينا إلى موسى وأخيه أن تبوءا لقومكما بمصر بيوتا واجعلوا بيوتكم قبلة وأقيموا الصلوة  وبشر المؤمنين', NULL, 218, 'local:hafs-text.json'),
  ('hafs-10-88', 'hafs', 10, 88, 'وَقَالَ مُوسَىٰ رَبَّنَآ إِنَّكَ ءَاتَيْتَ فِرْعَوْنَ وَمَلَأَهُۥ زِينَةًۭ وَأَمْوَٰلًۭا فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا رَبَّنَا لِيُضِلُّوا۟ عَن سَبِيلِكَ ۖ رَبَّنَا ٱطْمِسْ عَلَىٰٓ أَمْوَٰلِهِمْ وَٱشْدُدْ عَلَىٰ قُلُوبِهِمْ فَلَا يُؤْمِنُوا۟ حَتَّىٰ يَرَوُا۟ ٱلْعَذَابَ ٱلْأَلِيمَ', 'وقال موسى ربنا إنك ءاتيت فرعون وملأه زينة وأمولا فى الحيوة الدنيا ربنا ليضلوا عن سبيلك  ربنا اطمس على أمولهم واشدد على قلوبهم فلا يؤمنوا حتى يروا العذاب الأليم', NULL, 218, 'local:hafs-text.json'),
  ('hafs-10-89', 'hafs', 10, 89, 'قَالَ قَدْ أُجِيبَت دَّعْوَتُكُمَا فَٱسْتَقِيمَا وَلَا تَتَّبِعَآنِّ سَبِيلَ ٱلَّذِينَ لَا يَعْلَمُونَ', 'قال قد أجيبت دعوتكما فاستقيما ولا تتبعان سبيل الذين لا يعلمون', NULL, 219, 'local:hafs-text.json'),
  ('hafs-10-90', 'hafs', 10, 90, '۞ وَجَٰوَزْنَا بِبَنِىٓ إِسْرَٰٓءِيلَ ٱلْبَحْرَ فَأَتْبَعَهُمْ فِرْعَوْنُ وَجُنُودُهُۥ بَغْيًۭا وَعَدْوًا ۖ حَتَّىٰٓ إِذَآ أَدْرَكَهُ ٱلْغَرَقُ قَالَ ءَامَنتُ أَنَّهُۥ لَآ إِلَٰهَ إِلَّا ٱلَّذِىٓ ءَامَنَتْ بِهِۦ بَنُوٓا۟ إِسْرَٰٓءِيلَ وَأَنَا۠ مِنَ ٱلْمُسْلِمِينَ', 'وجوزنا ببنى إسرءيل البحر فأتبعهم فرعون وجنوده بغيا وعدوا  حتى إذا أدركه الغرق قال ءامنت أنه لا إله إلا الذى ءامنت به بنوا إسرءيل وأنا من المسلمين', NULL, 219, 'local:hafs-text.json'),
  ('hafs-10-91', 'hafs', 10, 91, 'ءَآلْـَٰٔنَ وَقَدْ عَصَيْتَ قَبْلُ وَكُنتَ مِنَ ٱلْمُفْسِدِينَ', 'ءالن وقد عصيت قبل وكنت من المفسدين', NULL, 219, 'local:hafs-text.json'),
  ('hafs-10-92', 'hafs', 10, 92, 'فَٱلْيَوْمَ نُنَجِّيكَ بِبَدَنِكَ لِتَكُونَ لِمَنْ خَلْفَكَ ءَايَةًۭ ۚ وَإِنَّ كَثِيرًۭا مِّنَ ٱلنَّاسِ عَنْ ءَايَٰتِنَا لَغَٰفِلُونَ', 'فاليوم ننجيك ببدنك لتكون لمن خلفك ءاية  وإن كثيرا من الناس عن ءايتنا لغفلون', NULL, 219, 'local:hafs-text.json'),
  ('hafs-10-93', 'hafs', 10, 93, 'وَلَقَدْ بَوَّأْنَا بَنِىٓ إِسْرَٰٓءِيلَ مُبَوَّأَ صِدْقٍۢ وَرَزَقْنَٰهُم مِّنَ ٱلطَّيِّبَٰتِ فَمَا ٱخْتَلَفُوا۟ حَتَّىٰ جَآءَهُمُ ٱلْعِلْمُ ۚ إِنَّ رَبَّكَ يَقْضِى بَيْنَهُمْ يَوْمَ ٱلْقِيَٰمَةِ فِيمَا كَانُوا۟ فِيهِ يَخْتَلِفُونَ', 'ولقد بوأنا بنى إسرءيل مبوأ صدق ورزقنهم من الطيبت فما اختلفوا حتى جاءهم العلم  إن ربك يقضى بينهم يوم القيمة فيما كانوا فيه يختلفون', NULL, 219, 'local:hafs-text.json'),
  ('hafs-10-94', 'hafs', 10, 94, 'فَإِن كُنتَ فِى شَكٍّۢ مِّمَّآ أَنزَلْنَآ إِلَيْكَ فَسْـَٔلِ ٱلَّذِينَ يَقْرَءُونَ ٱلْكِتَٰبَ مِن قَبْلِكَ ۚ لَقَدْ جَآءَكَ ٱلْحَقُّ مِن رَّبِّكَ فَلَا تَكُونَنَّ مِنَ ٱلْمُمْتَرِينَ', 'فإن كنت فى شك مما أنزلنا إليك فسل الذين يقرءون الكتب من قبلك  لقد جاءك الحق من ربك فلا تكونن من الممترين', NULL, 219, 'local:hafs-text.json'),
  ('hafs-10-95', 'hafs', 10, 95, 'وَلَا تَكُونَنَّ مِنَ ٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَٰتِ ٱللَّهِ فَتَكُونَ مِنَ ٱلْخَٰسِرِينَ', 'ولا تكونن من الذين كذبوا بايت الله فتكون من الخسرين', NULL, 219, 'local:hafs-text.json'),
  ('hafs-10-96', 'hafs', 10, 96, 'إِنَّ ٱلَّذِينَ حَقَّتْ عَلَيْهِمْ كَلِمَتُ رَبِّكَ لَا يُؤْمِنُونَ', 'إن الذين حقت عليهم كلمت ربك لا يؤمنون', NULL, 219, 'local:hafs-text.json'),
  ('hafs-10-97', 'hafs', 10, 97, 'وَلَوْ جَآءَتْهُمْ كُلُّ ءَايَةٍ حَتَّىٰ يَرَوُا۟ ٱلْعَذَابَ ٱلْأَلِيمَ', 'ولو جاءتهم كل ءاية حتى يروا العذاب الأليم', NULL, 219, 'local:hafs-text.json'),
  ('hafs-10-98', 'hafs', 10, 98, 'فَلَوْلَا كَانَتْ قَرْيَةٌ ءَامَنَتْ فَنَفَعَهَآ إِيمَٰنُهَآ إِلَّا قَوْمَ يُونُسَ لَمَّآ ءَامَنُوا۟ كَشَفْنَا عَنْهُمْ عَذَابَ ٱلْخِزْىِ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا وَمَتَّعْنَٰهُمْ إِلَىٰ حِينٍۢ', 'فلولا كانت قرية ءامنت فنفعها إيمنها إلا قوم يونس لما ءامنوا كشفنا عنهم عذاب الخزى فى الحيوة الدنيا ومتعنهم إلى حين', NULL, 220, 'local:hafs-text.json'),
  ('hafs-10-99', 'hafs', 10, 99, 'وَلَوْ شَآءَ رَبُّكَ لَءَامَنَ مَن فِى ٱلْأَرْضِ كُلُّهُمْ جَمِيعًا ۚ أَفَأَنتَ تُكْرِهُ ٱلنَّاسَ حَتَّىٰ يَكُونُوا۟ مُؤْمِنِينَ', 'ولو شاء ربك لءامن من فى الأرض كلهم جميعا  أفأنت تكره الناس حتى يكونوا مؤمنين', NULL, 220, 'local:hafs-text.json'),
  ('hafs-10-100', 'hafs', 10, 100, 'وَمَا كَانَ لِنَفْسٍ أَن تُؤْمِنَ إِلَّا بِإِذْنِ ٱللَّهِ ۚ وَيَجْعَلُ ٱلرِّجْسَ عَلَى ٱلَّذِينَ لَا يَعْقِلُونَ', 'وما كان لنفس أن تؤمن إلا بإذن الله  ويجعل الرجس على الذين لا يعقلون', NULL, 220, 'local:hafs-text.json'),
  ('hafs-10-101', 'hafs', 10, 101, 'قُلِ ٱنظُرُوا۟ مَاذَا فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ ۚ وَمَا تُغْنِى ٱلْءَايَٰتُ وَٱلنُّذُرُ عَن قَوْمٍۢ لَّا يُؤْمِنُونَ', 'قل انظروا ماذا فى السموت والأرض  وما تغنى الءايت والنذر عن قوم لا يؤمنون', NULL, 220, 'local:hafs-text.json'),
  ('hafs-10-102', 'hafs', 10, 102, 'فَهَلْ يَنتَظِرُونَ إِلَّا مِثْلَ أَيَّامِ ٱلَّذِينَ خَلَوْا۟ مِن قَبْلِهِمْ ۚ قُلْ فَٱنتَظِرُوٓا۟ إِنِّى مَعَكُم مِّنَ ٱلْمُنتَظِرِينَ', 'فهل ينتظرون إلا مثل أيام الذين خلوا من قبلهم  قل فانتظروا إنى معكم من المنتظرين', NULL, 220, 'local:hafs-text.json'),
  ('hafs-10-103', 'hafs', 10, 103, 'ثُمَّ نُنَجِّى رُسُلَنَا وَٱلَّذِينَ ءَامَنُوا۟ ۚ كَذَٰلِكَ حَقًّا عَلَيْنَا نُنجِ ٱلْمُؤْمِنِينَ', 'ثم ننجى رسلنا والذين ءامنوا  كذلك حقا علينا ننج المؤمنين', NULL, 220, 'local:hafs-text.json'),
  ('hafs-10-104', 'hafs', 10, 104, 'قُلْ يَٰٓأَيُّهَا ٱلنَّاسُ إِن كُنتُمْ فِى شَكٍّۢ مِّن دِينِى فَلَآ أَعْبُدُ ٱلَّذِينَ تَعْبُدُونَ مِن دُونِ ٱللَّهِ وَلَٰكِنْ أَعْبُدُ ٱللَّهَ ٱلَّذِى يَتَوَفَّىٰكُمْ ۖ وَأُمِرْتُ أَنْ أَكُونَ مِنَ ٱلْمُؤْمِنِينَ', 'قل يأيها الناس إن كنتم فى شك من دينى فلا أعبد الذين تعبدون من دون الله ولكن أعبد الله الذى يتوفىكم  وأمرت أن أكون من المؤمنين', NULL, 220, 'local:hafs-text.json'),
  ('hafs-10-105', 'hafs', 10, 105, 'وَأَنْ أَقِمْ وَجْهَكَ لِلدِّينِ حَنِيفًۭا وَلَا تَكُونَنَّ مِنَ ٱلْمُشْرِكِينَ', 'وأن أقم وجهك للدين حنيفا ولا تكونن من المشركين', NULL, 220, 'local:hafs-text.json'),
  ('hafs-10-106', 'hafs', 10, 106, 'وَلَا تَدْعُ مِن دُونِ ٱللَّهِ مَا لَا يَنفَعُكَ وَلَا يَضُرُّكَ ۖ فَإِن فَعَلْتَ فَإِنَّكَ إِذًۭا مِّنَ ٱلظَّٰلِمِينَ', 'ولا تدع من دون الله ما لا ينفعك ولا يضرك  فإن فعلت فإنك إذا من الظلمين', NULL, 220, 'local:hafs-text.json'),
  ('hafs-10-107', 'hafs', 10, 107, 'وَإِن يَمْسَسْكَ ٱللَّهُ بِضُرٍّۢ فَلَا كَاشِفَ لَهُۥٓ إِلَّا هُوَ ۖ وَإِن يُرِدْكَ بِخَيْرٍۢ فَلَا رَآدَّ لِفَضْلِهِۦ ۚ يُصِيبُ بِهِۦ مَن يَشَآءُ مِنْ عِبَادِهِۦ ۚ وَهُوَ ٱلْغَفُورُ ٱلرَّحِيمُ', 'وإن يمسسك الله بضر فلا كاشف له إلا هو  وإن يردك بخير فلا راد لفضله  يصيب به من يشاء من عباده  وهو الغفور الرحيم', NULL, 221, 'local:hafs-text.json'),
  ('hafs-10-108', 'hafs', 10, 108, 'قُلْ يَٰٓأَيُّهَا ٱلنَّاسُ قَدْ جَآءَكُمُ ٱلْحَقُّ مِن رَّبِّكُمْ ۖ فَمَنِ ٱهْتَدَىٰ فَإِنَّمَا يَهْتَدِى لِنَفْسِهِۦ ۖ وَمَن ضَلَّ فَإِنَّمَا يَضِلُّ عَلَيْهَا ۖ وَمَآ أَنَا۠ عَلَيْكُم بِوَكِيلٍۢ', 'قل يأيها الناس قد جاءكم الحق من ربكم  فمن اهتدى فإنما يهتدى لنفسه  ومن ضل فإنما يضل عليها  وما أنا عليكم بوكيل', NULL, 221, 'local:hafs-text.json'),
  ('hafs-10-109', 'hafs', 10, 109, 'وَٱتَّبِعْ مَا يُوحَىٰٓ إِلَيْكَ وَٱصْبِرْ حَتَّىٰ يَحْكُمَ ٱللَّهُ ۚ وَهُوَ خَيْرُ ٱلْحَٰكِمِينَ', 'واتبع ما يوحى إليك واصبر حتى يحكم الله  وهو خير الحكمين', NULL, 221, 'local:hafs-text.json'),
  ('hafs-11-1', 'hafs', 11, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ الٓر ۚ كِتَٰبٌ أُحْكِمَتْ ءَايَٰتُهُۥ ثُمَّ فُصِّلَتْ مِن لَّدُنْ حَكِيمٍ خَبِيرٍ', 'بسم الله الرحمن الرحيم الر  كتب أحكمت ءايته ثم فصلت من لدن حكيم خبير', NULL, 221, 'local:hafs-text.json'),
  ('hafs-11-2', 'hafs', 11, 2, 'أَلَّا تَعْبُدُوٓا۟ إِلَّا ٱللَّهَ ۚ إِنَّنِى لَكُم مِّنْهُ نَذِيرٌۭ وَبَشِيرٌۭ', 'ألا تعبدوا إلا الله  إننى لكم منه نذير وبشير', NULL, 221, 'local:hafs-text.json'),
  ('hafs-11-3', 'hafs', 11, 3, 'وَأَنِ ٱسْتَغْفِرُوا۟ رَبَّكُمْ ثُمَّ تُوبُوٓا۟ إِلَيْهِ يُمَتِّعْكُم مَّتَٰعًا حَسَنًا إِلَىٰٓ أَجَلٍۢ مُّسَمًّۭى وَيُؤْتِ كُلَّ ذِى فَضْلٍۢ فَضْلَهُۥ ۖ وَإِن تَوَلَّوْا۟ فَإِنِّىٓ أَخَافُ عَلَيْكُمْ عَذَابَ يَوْمٍۢ كَبِيرٍ', 'وأن استغفروا ربكم ثم توبوا إليه يمتعكم متعا حسنا إلى أجل مسمى ويؤت كل ذى فضل فضله  وإن تولوا فإنى أخاف عليكم عذاب يوم كبير', NULL, 221, 'local:hafs-text.json'),
  ('hafs-11-4', 'hafs', 11, 4, 'إِلَى ٱللَّهِ مَرْجِعُكُمْ ۖ وَهُوَ عَلَىٰ كُلِّ شَىْءٍۢ قَدِيرٌ', 'إلى الله مرجعكم  وهو على كل شىء قدير', NULL, 221, 'local:hafs-text.json'),
  ('hafs-11-5', 'hafs', 11, 5, 'أَلَآ إِنَّهُمْ يَثْنُونَ صُدُورَهُمْ لِيَسْتَخْفُوا۟ مِنْهُ ۚ أَلَا حِينَ يَسْتَغْشُونَ ثِيَابَهُمْ يَعْلَمُ مَا يُسِرُّونَ وَمَا يُعْلِنُونَ ۚ إِنَّهُۥ عَلِيمٌۢ بِذَاتِ ٱلصُّدُورِ', 'ألا إنهم يثنون صدورهم ليستخفوا منه  ألا حين يستغشون ثيابهم يعلم ما يسرون وما يعلنون  إنه عليم بذات الصدور', NULL, 221, 'local:hafs-text.json'),
  ('hafs-11-6', 'hafs', 11, 6, '۞ وَمَا مِن دَآبَّةٍۢ فِى ٱلْأَرْضِ إِلَّا عَلَى ٱللَّهِ رِزْقُهَا وَيَعْلَمُ مُسْتَقَرَّهَا وَمُسْتَوْدَعَهَا ۚ كُلٌّۭ فِى كِتَٰبٍۢ مُّبِينٍۢ', 'وما من دابة فى الأرض إلا على الله رزقها ويعلم مستقرها ومستودعها  كل فى كتب مبين', NULL, 222, 'local:hafs-text.json'),
  ('hafs-11-7', 'hafs', 11, 7, 'وَهُوَ ٱلَّذِى خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ فِى سِتَّةِ أَيَّامٍۢ وَكَانَ عَرْشُهُۥ عَلَى ٱلْمَآءِ لِيَبْلُوَكُمْ أَيُّكُمْ أَحْسَنُ عَمَلًۭا ۗ وَلَئِن قُلْتَ إِنَّكُم مَّبْعُوثُونَ مِنۢ بَعْدِ ٱلْمَوْتِ لَيَقُولَنَّ ٱلَّذِينَ كَفَرُوٓا۟ إِنْ هَٰذَآ إِلَّا سِحْرٌۭ مُّبِينٌۭ', 'وهو الذى خلق السموت والأرض فى ستة أيام وكان عرشه على الماء ليبلوكم أيكم أحسن عملا  ولئن قلت إنكم مبعوثون من بعد الموت ليقولن الذين كفروا إن هذا إلا سحر مبين', NULL, 222, 'local:hafs-text.json'),
  ('hafs-11-8', 'hafs', 11, 8, 'وَلَئِنْ أَخَّرْنَا عَنْهُمُ ٱلْعَذَابَ إِلَىٰٓ أُمَّةٍۢ مَّعْدُودَةٍۢ لَّيَقُولُنَّ مَا يَحْبِسُهُۥٓ ۗ أَلَا يَوْمَ يَأْتِيهِمْ لَيْسَ مَصْرُوفًا عَنْهُمْ وَحَاقَ بِهِم مَّا كَانُوا۟ بِهِۦ يَسْتَهْزِءُونَ', 'ولئن أخرنا عنهم العذاب إلى أمة معدودة ليقولن ما يحبسه  ألا يوم يأتيهم ليس مصروفا عنهم وحاق بهم ما كانوا به يستهزءون', NULL, 222, 'local:hafs-text.json'),
  ('hafs-11-9', 'hafs', 11, 9, 'وَلَئِنْ أَذَقْنَا ٱلْإِنسَٰنَ مِنَّا رَحْمَةًۭ ثُمَّ نَزَعْنَٰهَا مِنْهُ إِنَّهُۥ لَيَـُٔوسٌۭ كَفُورٌۭ', 'ولئن أذقنا الإنسن منا رحمة ثم نزعنها منه إنه ليوس كفور', NULL, 222, 'local:hafs-text.json'),
  ('hafs-11-10', 'hafs', 11, 10, 'وَلَئِنْ أَذَقْنَٰهُ نَعْمَآءَ بَعْدَ ضَرَّآءَ مَسَّتْهُ لَيَقُولَنَّ ذَهَبَ ٱلسَّيِّـَٔاتُ عَنِّىٓ ۚ إِنَّهُۥ لَفَرِحٌۭ فَخُورٌ', 'ولئن أذقنه نعماء بعد ضراء مسته ليقولن ذهب السيات عنى  إنه لفرح فخور', NULL, 222, 'local:hafs-text.json'),
  ('hafs-11-11', 'hafs', 11, 11, 'إِلَّا ٱلَّذِينَ صَبَرُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ أُو۟لَٰٓئِكَ لَهُم مَّغْفِرَةٌۭ وَأَجْرٌۭ كَبِيرٌۭ', 'إلا الذين صبروا وعملوا الصلحت أولئك لهم مغفرة وأجر كبير', NULL, 222, 'local:hafs-text.json'),
  ('hafs-11-12', 'hafs', 11, 12, 'فَلَعَلَّكَ تَارِكٌۢ بَعْضَ مَا يُوحَىٰٓ إِلَيْكَ وَضَآئِقٌۢ بِهِۦ صَدْرُكَ أَن يَقُولُوا۟ لَوْلَآ أُنزِلَ عَلَيْهِ كَنزٌ أَوْ جَآءَ مَعَهُۥ مَلَكٌ ۚ إِنَّمَآ أَنتَ نَذِيرٌۭ ۚ وَٱللَّهُ عَلَىٰ كُلِّ شَىْءٍۢ وَكِيلٌ', 'فلعلك تارك بعض ما يوحى إليك وضائق به صدرك أن يقولوا لولا أنزل عليه كنز أو جاء معه ملك  إنما أنت نذير  والله على كل شىء وكيل', NULL, 222, 'local:hafs-text.json'),
  ('hafs-11-13', 'hafs', 11, 13, 'أَمْ يَقُولُونَ ٱفْتَرَىٰهُ ۖ قُلْ فَأْتُوا۟ بِعَشْرِ سُوَرٍۢ مِّثْلِهِۦ مُفْتَرَيَٰتٍۢ وَٱدْعُوا۟ مَنِ ٱسْتَطَعْتُم مِّن دُونِ ٱللَّهِ إِن كُنتُمْ صَٰدِقِينَ', 'أم يقولون افترىه  قل فأتوا بعشر سور مثله مفتريت وادعوا من استطعتم من دون الله إن كنتم صدقين', NULL, 223, 'local:hafs-text.json'),
  ('hafs-11-14', 'hafs', 11, 14, 'فَإِلَّمْ يَسْتَجِيبُوا۟ لَكُمْ فَٱعْلَمُوٓا۟ أَنَّمَآ أُنزِلَ بِعِلْمِ ٱللَّهِ وَأَن لَّآ إِلَٰهَ إِلَّا هُوَ ۖ فَهَلْ أَنتُم مُّسْلِمُونَ', 'فإلم يستجيبوا لكم فاعلموا أنما أنزل بعلم الله وأن لا إله إلا هو  فهل أنتم مسلمون', NULL, 223, 'local:hafs-text.json'),
  ('hafs-11-15', 'hafs', 11, 15, 'مَن كَانَ يُرِيدُ ٱلْحَيَوٰةَ ٱلدُّنْيَا وَزِينَتَهَا نُوَفِّ إِلَيْهِمْ أَعْمَٰلَهُمْ فِيهَا وَهُمْ فِيهَا لَا يُبْخَسُونَ', 'من كان يريد الحيوة الدنيا وزينتها نوف إليهم أعملهم فيها وهم فيها لا يبخسون', NULL, 223, 'local:hafs-text.json'),
  ('hafs-11-16', 'hafs', 11, 16, 'أُو۟لَٰٓئِكَ ٱلَّذِينَ لَيْسَ لَهُمْ فِى ٱلْءَاخِرَةِ إِلَّا ٱلنَّارُ ۖ وَحَبِطَ مَا صَنَعُوا۟ فِيهَا وَبَٰطِلٌۭ مَّا كَانُوا۟ يَعْمَلُونَ', 'أولئك الذين ليس لهم فى الءاخرة إلا النار  وحبط ما صنعوا فيها وبطل ما كانوا يعملون', NULL, 223, 'local:hafs-text.json'),
  ('hafs-11-17', 'hafs', 11, 17, 'أَفَمَن كَانَ عَلَىٰ بَيِّنَةٍۢ مِّن رَّبِّهِۦ وَيَتْلُوهُ شَاهِدٌۭ مِّنْهُ وَمِن قَبْلِهِۦ كِتَٰبُ مُوسَىٰٓ إِمَامًۭا وَرَحْمَةً ۚ أُو۟لَٰٓئِكَ يُؤْمِنُونَ بِهِۦ ۚ وَمَن يَكْفُرْ بِهِۦ مِنَ ٱلْأَحْزَابِ فَٱلنَّارُ مَوْعِدُهُۥ ۚ فَلَا تَكُ فِى مِرْيَةٍۢ مِّنْهُ ۚ إِنَّهُ ٱلْحَقُّ مِن رَّبِّكَ وَلَٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يُؤْمِنُونَ', 'أفمن كان على بينة من ربه ويتلوه شاهد منه ومن قبله كتب موسى إماما ورحمة  أولئك يؤمنون به  ومن يكفر به من الأحزاب فالنار موعده  فلا تك فى مرية منه  إنه الحق من ربك ولكن أكثر الناس لا يؤمنون', NULL, 223, 'local:hafs-text.json'),
  ('hafs-11-18', 'hafs', 11, 18, 'وَمَنْ أَظْلَمُ مِمَّنِ ٱفْتَرَىٰ عَلَى ٱللَّهِ كَذِبًا ۚ أُو۟لَٰٓئِكَ يُعْرَضُونَ عَلَىٰ رَبِّهِمْ وَيَقُولُ ٱلْأَشْهَٰدُ هَٰٓؤُلَآءِ ٱلَّذِينَ كَذَبُوا۟ عَلَىٰ رَبِّهِمْ ۚ أَلَا لَعْنَةُ ٱللَّهِ عَلَى ٱلظَّٰلِمِينَ', 'ومن أظلم ممن افترى على الله كذبا  أولئك يعرضون على ربهم ويقول الأشهد هؤلاء الذين كذبوا على ربهم  ألا لعنة الله على الظلمين', NULL, 223, 'local:hafs-text.json'),
  ('hafs-11-19', 'hafs', 11, 19, 'ٱلَّذِينَ يَصُدُّونَ عَن سَبِيلِ ٱللَّهِ وَيَبْغُونَهَا عِوَجًۭا وَهُم بِٱلْءَاخِرَةِ هُمْ كَٰفِرُونَ', 'الذين يصدون عن سبيل الله ويبغونها عوجا وهم بالءاخرة هم كفرون', NULL, 223, 'local:hafs-text.json'),
  ('hafs-11-20', 'hafs', 11, 20, 'أُو۟لَٰٓئِكَ لَمْ يَكُونُوا۟ مُعْجِزِينَ فِى ٱلْأَرْضِ وَمَا كَانَ لَهُم مِّن دُونِ ٱللَّهِ مِنْ أَوْلِيَآءَ ۘ يُضَٰعَفُ لَهُمُ ٱلْعَذَابُ ۚ مَا كَانُوا۟ يَسْتَطِيعُونَ ٱلسَّمْعَ وَمَا كَانُوا۟ يُبْصِرُونَ', 'أولئك لم يكونوا معجزين فى الأرض وما كان لهم من دون الله من أولياء  يضعف لهم العذاب  ما كانوا يستطيعون السمع وما كانوا يبصرون', NULL, 224, 'local:hafs-text.json'),
  ('hafs-11-21', 'hafs', 11, 21, 'أُو۟لَٰٓئِكَ ٱلَّذِينَ خَسِرُوٓا۟ أَنفُسَهُمْ وَضَلَّ عَنْهُم مَّا كَانُوا۟ يَفْتَرُونَ', 'أولئك الذين خسروا أنفسهم وضل عنهم ما كانوا يفترون', NULL, 224, 'local:hafs-text.json'),
  ('hafs-11-22', 'hafs', 11, 22, 'لَا جَرَمَ أَنَّهُمْ فِى ٱلْءَاخِرَةِ هُمُ ٱلْأَخْسَرُونَ', 'لا جرم أنهم فى الءاخرة هم الأخسرون', NULL, 224, 'local:hafs-text.json'),
  ('hafs-11-23', 'hafs', 11, 23, 'إِنَّ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ وَأَخْبَتُوٓا۟ إِلَىٰ رَبِّهِمْ أُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلْجَنَّةِ ۖ هُمْ فِيهَا خَٰلِدُونَ', 'إن الذين ءامنوا وعملوا الصلحت وأخبتوا إلى ربهم أولئك أصحب الجنة  هم فيها خلدون', NULL, 224, 'local:hafs-text.json'),
  ('hafs-11-24', 'hafs', 11, 24, '۞ مَثَلُ ٱلْفَرِيقَيْنِ كَٱلْأَعْمَىٰ وَٱلْأَصَمِّ وَٱلْبَصِيرِ وَٱلسَّمِيعِ ۚ هَلْ يَسْتَوِيَانِ مَثَلًا ۚ أَفَلَا تَذَكَّرُونَ', 'مثل الفريقين كالأعمى والأصم والبصير والسميع  هل يستويان مثلا  أفلا تذكرون', NULL, 224, 'local:hafs-text.json'),
  ('hafs-11-25', 'hafs', 11, 25, 'وَلَقَدْ أَرْسَلْنَا نُوحًا إِلَىٰ قَوْمِهِۦٓ إِنِّى لَكُمْ نَذِيرٌۭ مُّبِينٌ', 'ولقد أرسلنا نوحا إلى قومه إنى لكم نذير مبين', NULL, 224, 'local:hafs-text.json'),
  ('hafs-11-26', 'hafs', 11, 26, 'أَن لَّا تَعْبُدُوٓا۟ إِلَّا ٱللَّهَ ۖ إِنِّىٓ أَخَافُ عَلَيْكُمْ عَذَابَ يَوْمٍ أَلِيمٍۢ', 'أن لا تعبدوا إلا الله  إنى أخاف عليكم عذاب يوم أليم', NULL, 224, 'local:hafs-text.json'),
  ('hafs-11-27', 'hafs', 11, 27, 'فَقَالَ ٱلْمَلَأُ ٱلَّذِينَ كَفَرُوا۟ مِن قَوْمِهِۦ مَا نَرَىٰكَ إِلَّا بَشَرًۭا مِّثْلَنَا وَمَا نَرَىٰكَ ٱتَّبَعَكَ إِلَّا ٱلَّذِينَ هُمْ أَرَاذِلُنَا بَادِىَ ٱلرَّأْىِ وَمَا نَرَىٰ لَكُمْ عَلَيْنَا مِن فَضْلٍۭ بَلْ نَظُنُّكُمْ كَٰذِبِينَ', 'فقال الملأ الذين كفروا من قومه ما نرىك إلا بشرا مثلنا وما نرىك اتبعك إلا الذين هم أراذلنا بادى الرأى وما نرى لكم علينا من فضل بل نظنكم كذبين', NULL, 224, 'local:hafs-text.json'),
  ('hafs-11-28', 'hafs', 11, 28, 'قَالَ يَٰقَوْمِ أَرَءَيْتُمْ إِن كُنتُ عَلَىٰ بَيِّنَةٍۢ مِّن رَّبِّى وَءَاتَىٰنِى رَحْمَةًۭ مِّنْ عِندِهِۦ فَعُمِّيَتْ عَلَيْكُمْ أَنُلْزِمُكُمُوهَا وَأَنتُمْ لَهَا كَٰرِهُونَ', 'قال يقوم أرءيتم إن كنت على بينة من ربى وءاتىنى رحمة من عنده فعميت عليكم أنلزمكموها وأنتم لها كرهون', NULL, 224, 'local:hafs-text.json'),
  ('hafs-11-29', 'hafs', 11, 29, 'وَيَٰقَوْمِ لَآ أَسْـَٔلُكُمْ عَلَيْهِ مَالًا ۖ إِنْ أَجْرِىَ إِلَّا عَلَى ٱللَّهِ ۚ وَمَآ أَنَا۠ بِطَارِدِ ٱلَّذِينَ ءَامَنُوٓا۟ ۚ إِنَّهُم مُّلَٰقُوا۟ رَبِّهِمْ وَلَٰكِنِّىٓ أَرَىٰكُمْ قَوْمًۭا تَجْهَلُونَ', 'ويقوم لا أسلكم عليه مالا  إن أجرى إلا على الله  وما أنا بطارد الذين ءامنوا  إنهم ملقوا ربهم ولكنى أرىكم قوما تجهلون', NULL, 225, 'local:hafs-text.json'),
  ('hafs-11-30', 'hafs', 11, 30, 'وَيَٰقَوْمِ مَن يَنصُرُنِى مِنَ ٱللَّهِ إِن طَرَدتُّهُمْ ۚ أَفَلَا تَذَكَّرُونَ', 'ويقوم من ينصرنى من الله إن طردتهم  أفلا تذكرون', NULL, 225, 'local:hafs-text.json'),
  ('hafs-11-31', 'hafs', 11, 31, 'وَلَآ أَقُولُ لَكُمْ عِندِى خَزَآئِنُ ٱللَّهِ وَلَآ أَعْلَمُ ٱلْغَيْبَ وَلَآ أَقُولُ إِنِّى مَلَكٌۭ وَلَآ أَقُولُ لِلَّذِينَ تَزْدَرِىٓ أَعْيُنُكُمْ لَن يُؤْتِيَهُمُ ٱللَّهُ خَيْرًا ۖ ٱللَّهُ أَعْلَمُ بِمَا فِىٓ أَنفُسِهِمْ ۖ إِنِّىٓ إِذًۭا لَّمِنَ ٱلظَّٰلِمِينَ', 'ولا أقول لكم عندى خزائن الله ولا أعلم الغيب ولا أقول إنى ملك ولا أقول للذين تزدرى أعينكم لن يؤتيهم الله خيرا  الله أعلم بما فى أنفسهم  إنى إذا لمن الظلمين', NULL, 225, 'local:hafs-text.json'),
  ('hafs-11-32', 'hafs', 11, 32, 'قَالُوا۟ يَٰنُوحُ قَدْ جَٰدَلْتَنَا فَأَكْثَرْتَ جِدَٰلَنَا فَأْتِنَا بِمَا تَعِدُنَآ إِن كُنتَ مِنَ ٱلصَّٰدِقِينَ', 'قالوا ينوح قد جدلتنا فأكثرت جدلنا فأتنا بما تعدنا إن كنت من الصدقين', NULL, 225, 'local:hafs-text.json'),
  ('hafs-11-33', 'hafs', 11, 33, 'قَالَ إِنَّمَا يَأْتِيكُم بِهِ ٱللَّهُ إِن شَآءَ وَمَآ أَنتُم بِمُعْجِزِينَ', 'قال إنما يأتيكم به الله إن شاء وما أنتم بمعجزين', NULL, 225, 'local:hafs-text.json'),
  ('hafs-11-34', 'hafs', 11, 34, 'وَلَا يَنفَعُكُمْ نُصْحِىٓ إِنْ أَرَدتُّ أَنْ أَنصَحَ لَكُمْ إِن كَانَ ٱللَّهُ يُرِيدُ أَن يُغْوِيَكُمْ ۚ هُوَ رَبُّكُمْ وَإِلَيْهِ تُرْجَعُونَ', 'ولا ينفعكم نصحى إن أردت أن أنصح لكم إن كان الله يريد أن يغويكم  هو ربكم وإليه ترجعون', NULL, 225, 'local:hafs-text.json'),
  ('hafs-11-35', 'hafs', 11, 35, 'أَمْ يَقُولُونَ ٱفْتَرَىٰهُ ۖ قُلْ إِنِ ٱفْتَرَيْتُهُۥ فَعَلَىَّ إِجْرَامِى وَأَنَا۠ بَرِىٓءٌۭ مِّمَّا تُجْرِمُونَ', 'أم يقولون افترىه  قل إن افتريته فعلى إجرامى وأنا برىء مما تجرمون', NULL, 225, 'local:hafs-text.json'),
  ('hafs-11-36', 'hafs', 11, 36, 'وَأُوحِىَ إِلَىٰ نُوحٍ أَنَّهُۥ لَن يُؤْمِنَ مِن قَوْمِكَ إِلَّا مَن قَدْ ءَامَنَ فَلَا تَبْتَئِسْ بِمَا كَانُوا۟ يَفْعَلُونَ', 'وأوحى إلى نوح أنه لن يؤمن من قومك إلا من قد ءامن فلا تبتئس بما كانوا يفعلون', NULL, 225, 'local:hafs-text.json'),
  ('hafs-11-37', 'hafs', 11, 37, 'وَٱصْنَعِ ٱلْفُلْكَ بِأَعْيُنِنَا وَوَحْيِنَا وَلَا تُخَٰطِبْنِى فِى ٱلَّذِينَ ظَلَمُوٓا۟ ۚ إِنَّهُم مُّغْرَقُونَ', 'واصنع الفلك بأعيننا ووحينا ولا تخطبنى فى الذين ظلموا  إنهم مغرقون', NULL, 225, 'local:hafs-text.json'),
  ('hafs-11-38', 'hafs', 11, 38, 'وَيَصْنَعُ ٱلْفُلْكَ وَكُلَّمَا مَرَّ عَلَيْهِ مَلَأٌۭ مِّن قَوْمِهِۦ سَخِرُوا۟ مِنْهُ ۚ قَالَ إِن تَسْخَرُوا۟ مِنَّا فَإِنَّا نَسْخَرُ مِنكُمْ كَمَا تَسْخَرُونَ', 'ويصنع الفلك وكلما مر عليه ملأ من قومه سخروا منه  قال إن تسخروا منا فإنا نسخر منكم كما تسخرون', NULL, 226, 'local:hafs-text.json'),
  ('hafs-11-39', 'hafs', 11, 39, 'فَسَوْفَ تَعْلَمُونَ مَن يَأْتِيهِ عَذَابٌۭ يُخْزِيهِ وَيَحِلُّ عَلَيْهِ عَذَابٌۭ مُّقِيمٌ', 'فسوف تعلمون من يأتيه عذاب يخزيه ويحل عليه عذاب مقيم', NULL, 226, 'local:hafs-text.json'),
  ('hafs-11-40', 'hafs', 11, 40, 'حَتَّىٰٓ إِذَا جَآءَ أَمْرُنَا وَفَارَ ٱلتَّنُّورُ قُلْنَا ٱحْمِلْ فِيهَا مِن كُلٍّۢ زَوْجَيْنِ ٱثْنَيْنِ وَأَهْلَكَ إِلَّا مَن سَبَقَ عَلَيْهِ ٱلْقَوْلُ وَمَنْ ءَامَنَ ۚ وَمَآ ءَامَنَ مَعَهُۥٓ إِلَّا قَلِيلٌۭ', 'حتى إذا جاء أمرنا وفار التنور قلنا احمل فيها من كل زوجين اثنين وأهلك إلا من سبق عليه القول ومن ءامن  وما ءامن معه إلا قليل', NULL, 226, 'local:hafs-text.json'),
  ('hafs-11-41', 'hafs', 11, 41, '۞ وَقَالَ ٱرْكَبُوا۟ فِيهَا بِسْمِ ٱللَّهِ مَجْر۪ىٰهَا وَمُرْسَىٰهَآ ۚ إِنَّ رَبِّى لَغَفُورٌۭ رَّحِيمٌۭ', 'وقال اركبوا فيها بسم الله مجرىها ومرسىها  إن ربى لغفور رحيم', NULL, 226, 'local:hafs-text.json'),
  ('hafs-11-42', 'hafs', 11, 42, 'وَهِىَ تَجْرِى بِهِمْ فِى مَوْجٍۢ كَٱلْجِبَالِ وَنَادَىٰ نُوحٌ ٱبْنَهُۥ وَكَانَ فِى مَعْزِلٍۢ يَٰبُنَىَّ ٱرْكَب مَّعَنَا وَلَا تَكُن مَّعَ ٱلْكَٰفِرِينَ', 'وهى تجرى بهم فى موج كالجبال ونادى نوح ابنه وكان فى معزل يبنى اركب معنا ولا تكن مع الكفرين', NULL, 226, 'local:hafs-text.json'),
  ('hafs-11-43', 'hafs', 11, 43, 'قَالَ سَـَٔاوِىٓ إِلَىٰ جَبَلٍۢ يَعْصِمُنِى مِنَ ٱلْمَآءِ ۚ قَالَ لَا عَاصِمَ ٱلْيَوْمَ مِنْ أَمْرِ ٱللَّهِ إِلَّا مَن رَّحِمَ ۚ وَحَالَ بَيْنَهُمَا ٱلْمَوْجُ فَكَانَ مِنَ ٱلْمُغْرَقِينَ', 'قال ساوى إلى جبل يعصمنى من الماء  قال لا عاصم اليوم من أمر الله إلا من رحم  وحال بينهما الموج فكان من المغرقين', NULL, 226, 'local:hafs-text.json'),
  ('hafs-11-44', 'hafs', 11, 44, 'وَقِيلَ يَٰٓأَرْضُ ٱبْلَعِى مَآءَكِ وَيَٰسَمَآءُ أَقْلِعِى وَغِيضَ ٱلْمَآءُ وَقُضِىَ ٱلْأَمْرُ وَٱسْتَوَتْ عَلَى ٱلْجُودِىِّ ۖ وَقِيلَ بُعْدًۭا لِّلْقَوْمِ ٱلظَّٰلِمِينَ', 'وقيل يأرض ابلعى ماءك ويسماء أقلعى وغيض الماء وقضى الأمر واستوت على الجودى  وقيل بعدا للقوم الظلمين', NULL, 226, 'local:hafs-text.json'),
  ('hafs-11-45', 'hafs', 11, 45, 'وَنَادَىٰ نُوحٌۭ رَّبَّهُۥ فَقَالَ رَبِّ إِنَّ ٱبْنِى مِنْ أَهْلِى وَإِنَّ وَعْدَكَ ٱلْحَقُّ وَأَنتَ أَحْكَمُ ٱلْحَٰكِمِينَ', 'ونادى نوح ربه فقال رب إن ابنى من أهلى وإن وعدك الحق وأنت أحكم الحكمين', NULL, 226, 'local:hafs-text.json'),
  ('hafs-11-46', 'hafs', 11, 46, 'قَالَ يَٰنُوحُ إِنَّهُۥ لَيْسَ مِنْ أَهْلِكَ ۖ إِنَّهُۥ عَمَلٌ غَيْرُ صَٰلِحٍۢ ۖ فَلَا تَسْـَٔلْنِ مَا لَيْسَ لَكَ بِهِۦ عِلْمٌ ۖ إِنِّىٓ أَعِظُكَ أَن تَكُونَ مِنَ ٱلْجَٰهِلِينَ', 'قال ينوح إنه ليس من أهلك  إنه عمل غير صلح  فلا تسلن ما ليس لك به علم  إنى أعظك أن تكون من الجهلين', NULL, 227, 'local:hafs-text.json'),
  ('hafs-11-47', 'hafs', 11, 47, 'قَالَ رَبِّ إِنِّىٓ أَعُوذُ بِكَ أَنْ أَسْـَٔلَكَ مَا لَيْسَ لِى بِهِۦ عِلْمٌۭ ۖ وَإِلَّا تَغْفِرْ لِى وَتَرْحَمْنِىٓ أَكُن مِّنَ ٱلْخَٰسِرِينَ', 'قال رب إنى أعوذ بك أن أسلك ما ليس لى به علم  وإلا تغفر لى وترحمنى أكن من الخسرين', NULL, 227, 'local:hafs-text.json'),
  ('hafs-11-48', 'hafs', 11, 48, 'قِيلَ يَٰنُوحُ ٱهْبِطْ بِسَلَٰمٍۢ مِّنَّا وَبَرَكَٰتٍ عَلَيْكَ وَعَلَىٰٓ أُمَمٍۢ مِّمَّن مَّعَكَ ۚ وَأُمَمٌۭ سَنُمَتِّعُهُمْ ثُمَّ يَمَسُّهُم مِّنَّا عَذَابٌ أَلِيمٌۭ', 'قيل ينوح اهبط بسلم منا وبركت عليك وعلى أمم ممن معك  وأمم سنمتعهم ثم يمسهم منا عذاب أليم', NULL, 227, 'local:hafs-text.json'),
  ('hafs-11-49', 'hafs', 11, 49, 'تِلْكَ مِنْ أَنۢبَآءِ ٱلْغَيْبِ نُوحِيهَآ إِلَيْكَ ۖ مَا كُنتَ تَعْلَمُهَآ أَنتَ وَلَا قَوْمُكَ مِن قَبْلِ هَٰذَا ۖ فَٱصْبِرْ ۖ إِنَّ ٱلْعَٰقِبَةَ لِلْمُتَّقِينَ', 'تلك من أنباء الغيب نوحيها إليك  ما كنت تعلمها أنت ولا قومك من قبل هذا  فاصبر  إن العقبة للمتقين', NULL, 227, 'local:hafs-text.json'),
  ('hafs-11-50', 'hafs', 11, 50, 'وَإِلَىٰ عَادٍ أَخَاهُمْ هُودًۭا ۚ قَالَ يَٰقَوْمِ ٱعْبُدُوا۟ ٱللَّهَ مَا لَكُم مِّنْ إِلَٰهٍ غَيْرُهُۥٓ ۖ إِنْ أَنتُمْ إِلَّا مُفْتَرُونَ', 'وإلى عاد أخاهم هودا  قال يقوم اعبدوا الله ما لكم من إله غيره  إن أنتم إلا مفترون', NULL, 227, 'local:hafs-text.json'),
  ('hafs-11-51', 'hafs', 11, 51, 'يَٰقَوْمِ لَآ أَسْـَٔلُكُمْ عَلَيْهِ أَجْرًا ۖ إِنْ أَجْرِىَ إِلَّا عَلَى ٱلَّذِى فَطَرَنِىٓ ۚ أَفَلَا تَعْقِلُونَ', 'يقوم لا أسلكم عليه أجرا  إن أجرى إلا على الذى فطرنى  أفلا تعقلون', NULL, 227, 'local:hafs-text.json'),
  ('hafs-11-52', 'hafs', 11, 52, 'وَيَٰقَوْمِ ٱسْتَغْفِرُوا۟ رَبَّكُمْ ثُمَّ تُوبُوٓا۟ إِلَيْهِ يُرْسِلِ ٱلسَّمَآءَ عَلَيْكُم مِّدْرَارًۭا وَيَزِدْكُمْ قُوَّةً إِلَىٰ قُوَّتِكُمْ وَلَا تَتَوَلَّوْا۟ مُجْرِمِينَ', 'ويقوم استغفروا ربكم ثم توبوا إليه يرسل السماء عليكم مدرارا ويزدكم قوة إلى قوتكم ولا تتولوا مجرمين', NULL, 227, 'local:hafs-text.json'),
  ('hafs-11-53', 'hafs', 11, 53, 'قَالُوا۟ يَٰهُودُ مَا جِئْتَنَا بِبَيِّنَةٍۢ وَمَا نَحْنُ بِتَارِكِىٓ ءَالِهَتِنَا عَن قَوْلِكَ وَمَا نَحْنُ لَكَ بِمُؤْمِنِينَ', 'قالوا يهود ما جئتنا ببينة وما نحن بتاركى ءالهتنا عن قولك وما نحن لك بمؤمنين', NULL, 227, 'local:hafs-text.json'),
  ('hafs-11-54', 'hafs', 11, 54, 'إِن نَّقُولُ إِلَّا ٱعْتَرَىٰكَ بَعْضُ ءَالِهَتِنَا بِسُوٓءٍۢ ۗ قَالَ إِنِّىٓ أُشْهِدُ ٱللَّهَ وَٱشْهَدُوٓا۟ أَنِّى بَرِىٓءٌۭ مِّمَّا تُشْرِكُونَ', 'إن نقول إلا اعترىك بعض ءالهتنا بسوء  قال إنى أشهد الله واشهدوا أنى برىء مما تشركون', NULL, 228, 'local:hafs-text.json'),
  ('hafs-11-55', 'hafs', 11, 55, 'مِن دُونِهِۦ ۖ فَكِيدُونِى جَمِيعًۭا ثُمَّ لَا تُنظِرُونِ', 'من دونه  فكيدونى جميعا ثم لا تنظرون', NULL, 228, 'local:hafs-text.json'),
  ('hafs-11-56', 'hafs', 11, 56, 'إِنِّى تَوَكَّلْتُ عَلَى ٱللَّهِ رَبِّى وَرَبِّكُم ۚ مَّا مِن دَآبَّةٍ إِلَّا هُوَ ءَاخِذٌۢ بِنَاصِيَتِهَآ ۚ إِنَّ رَبِّى عَلَىٰ صِرَٰطٍۢ مُّسْتَقِيمٍۢ', 'إنى توكلت على الله ربى وربكم  ما من دابة إلا هو ءاخذ بناصيتها  إن ربى على صرط مستقيم', NULL, 228, 'local:hafs-text.json'),
  ('hafs-11-57', 'hafs', 11, 57, 'فَإِن تَوَلَّوْا۟ فَقَدْ أَبْلَغْتُكُم مَّآ أُرْسِلْتُ بِهِۦٓ إِلَيْكُمْ ۚ وَيَسْتَخْلِفُ رَبِّى قَوْمًا غَيْرَكُمْ وَلَا تَضُرُّونَهُۥ شَيْـًٔا ۚ إِنَّ رَبِّى عَلَىٰ كُلِّ شَىْءٍ حَفِيظٌۭ', 'فإن تولوا فقد أبلغتكم ما أرسلت به إليكم  ويستخلف ربى قوما غيركم ولا تضرونه شيا  إن ربى على كل شىء حفيظ', NULL, 228, 'local:hafs-text.json'),
  ('hafs-11-58', 'hafs', 11, 58, 'وَلَمَّا جَآءَ أَمْرُنَا نَجَّيْنَا هُودًۭا وَٱلَّذِينَ ءَامَنُوا۟ مَعَهُۥ بِرَحْمَةٍۢ مِّنَّا وَنَجَّيْنَٰهُم مِّنْ عَذَابٍ غَلِيظٍۢ', 'ولما جاء أمرنا نجينا هودا والذين ءامنوا معه برحمة منا ونجينهم من عذاب غليظ', NULL, 228, 'local:hafs-text.json'),
  ('hafs-11-59', 'hafs', 11, 59, 'وَتِلْكَ عَادٌۭ ۖ جَحَدُوا۟ بِـَٔايَٰتِ رَبِّهِمْ وَعَصَوْا۟ رُسُلَهُۥ وَٱتَّبَعُوٓا۟ أَمْرَ كُلِّ جَبَّارٍ عَنِيدٍۢ', 'وتلك عاد  جحدوا بايت ربهم وعصوا رسله واتبعوا أمر كل جبار عنيد', NULL, 228, 'local:hafs-text.json'),
  ('hafs-11-60', 'hafs', 11, 60, 'وَأُتْبِعُوا۟ فِى هَٰذِهِ ٱلدُّنْيَا لَعْنَةًۭ وَيَوْمَ ٱلْقِيَٰمَةِ ۗ أَلَآ إِنَّ عَادًۭا كَفَرُوا۟ رَبَّهُمْ ۗ أَلَا بُعْدًۭا لِّعَادٍۢ قَوْمِ هُودٍۢ', 'وأتبعوا فى هذه الدنيا لعنة ويوم القيمة  ألا إن عادا كفروا ربهم  ألا بعدا لعاد قوم هود', NULL, 228, 'local:hafs-text.json'),
  ('hafs-11-61', 'hafs', 11, 61, '۞ وَإِلَىٰ ثَمُودَ أَخَاهُمْ صَٰلِحًۭا ۚ قَالَ يَٰقَوْمِ ٱعْبُدُوا۟ ٱللَّهَ مَا لَكُم مِّنْ إِلَٰهٍ غَيْرُهُۥ ۖ هُوَ أَنشَأَكُم مِّنَ ٱلْأَرْضِ وَٱسْتَعْمَرَكُمْ فِيهَا فَٱسْتَغْفِرُوهُ ثُمَّ تُوبُوٓا۟ إِلَيْهِ ۚ إِنَّ رَبِّى قَرِيبٌۭ مُّجِيبٌۭ', 'وإلى ثمود أخاهم صلحا  قال يقوم اعبدوا الله ما لكم من إله غيره  هو أنشأكم من الأرض واستعمركم فيها فاستغفروه ثم توبوا إليه  إن ربى قريب مجيب', NULL, 228, 'local:hafs-text.json'),
  ('hafs-11-62', 'hafs', 11, 62, 'قَالُوا۟ يَٰصَٰلِحُ قَدْ كُنتَ فِينَا مَرْجُوًّۭا قَبْلَ هَٰذَآ ۖ أَتَنْهَىٰنَآ أَن نَّعْبُدَ مَا يَعْبُدُ ءَابَآؤُنَا وَإِنَّنَا لَفِى شَكٍّۢ مِّمَّا تَدْعُونَآ إِلَيْهِ مُرِيبٍۢ', 'قالوا يصلح قد كنت فينا مرجوا قبل هذا  أتنهىنا أن نعبد ما يعبد ءاباؤنا وإننا لفى شك مما تدعونا إليه مريب', NULL, 228, 'local:hafs-text.json'),
  ('hafs-11-63', 'hafs', 11, 63, 'قَالَ يَٰقَوْمِ أَرَءَيْتُمْ إِن كُنتُ عَلَىٰ بَيِّنَةٍۢ مِّن رَّبِّى وَءَاتَىٰنِى مِنْهُ رَحْمَةًۭ فَمَن يَنصُرُنِى مِنَ ٱللَّهِ إِنْ عَصَيْتُهُۥ ۖ فَمَا تَزِيدُونَنِى غَيْرَ تَخْسِيرٍۢ', 'قال يقوم أرءيتم إن كنت على بينة من ربى وءاتىنى منه رحمة فمن ينصرنى من الله إن عصيته  فما تزيدوننى غير تخسير', NULL, 229, 'local:hafs-text.json'),
  ('hafs-11-64', 'hafs', 11, 64, 'وَيَٰقَوْمِ هَٰذِهِۦ نَاقَةُ ٱللَّهِ لَكُمْ ءَايَةًۭ فَذَرُوهَا تَأْكُلْ فِىٓ أَرْضِ ٱللَّهِ وَلَا تَمَسُّوهَا بِسُوٓءٍۢ فَيَأْخُذَكُمْ عَذَابٌۭ قَرِيبٌۭ', 'ويقوم هذه ناقة الله لكم ءاية فذروها تأكل فى أرض الله ولا تمسوها بسوء فيأخذكم عذاب قريب', NULL, 229, 'local:hafs-text.json'),
  ('hafs-11-65', 'hafs', 11, 65, 'فَعَقَرُوهَا فَقَالَ تَمَتَّعُوا۟ فِى دَارِكُمْ ثَلَٰثَةَ أَيَّامٍۢ ۖ ذَٰلِكَ وَعْدٌ غَيْرُ مَكْذُوبٍۢ', 'فعقروها فقال تمتعوا فى داركم ثلثة أيام  ذلك وعد غير مكذوب', NULL, 229, 'local:hafs-text.json'),
  ('hafs-11-66', 'hafs', 11, 66, 'فَلَمَّا جَآءَ أَمْرُنَا نَجَّيْنَا صَٰلِحًۭا وَٱلَّذِينَ ءَامَنُوا۟ مَعَهُۥ بِرَحْمَةٍۢ مِّنَّا وَمِنْ خِزْىِ يَوْمِئِذٍ ۗ إِنَّ رَبَّكَ هُوَ ٱلْقَوِىُّ ٱلْعَزِيزُ', 'فلما جاء أمرنا نجينا صلحا والذين ءامنوا معه برحمة منا ومن خزى يومئذ  إن ربك هو القوى العزيز', NULL, 229, 'local:hafs-text.json'),
  ('hafs-11-67', 'hafs', 11, 67, 'وَأَخَذَ ٱلَّذِينَ ظَلَمُوا۟ ٱلصَّيْحَةُ فَأَصْبَحُوا۟ فِى دِيَٰرِهِمْ جَٰثِمِينَ', 'وأخذ الذين ظلموا الصيحة فأصبحوا فى ديرهم جثمين', NULL, 229, 'local:hafs-text.json'),
  ('hafs-11-68', 'hafs', 11, 68, 'كَأَن لَّمْ يَغْنَوْا۟ فِيهَآ ۗ أَلَآ إِنَّ ثَمُودَا۟ كَفَرُوا۟ رَبَّهُمْ ۗ أَلَا بُعْدًۭا لِّثَمُودَ', 'كأن لم يغنوا فيها  ألا إن ثمودا كفروا ربهم  ألا بعدا لثمود', NULL, 229, 'local:hafs-text.json'),
  ('hafs-11-69', 'hafs', 11, 69, 'وَلَقَدْ جَآءَتْ رُسُلُنَآ إِبْرَٰهِيمَ بِٱلْبُشْرَىٰ قَالُوا۟ سَلَٰمًۭا ۖ قَالَ سَلَٰمٌۭ ۖ فَمَا لَبِثَ أَن جَآءَ بِعِجْلٍ حَنِيذٍۢ', 'ولقد جاءت رسلنا إبرهيم بالبشرى قالوا سلما  قال سلم  فما لبث أن جاء بعجل حنيذ', NULL, 229, 'local:hafs-text.json'),
  ('hafs-11-70', 'hafs', 11, 70, 'فَلَمَّا رَءَآ أَيْدِيَهُمْ لَا تَصِلُ إِلَيْهِ نَكِرَهُمْ وَأَوْجَسَ مِنْهُمْ خِيفَةًۭ ۚ قَالُوا۟ لَا تَخَفْ إِنَّآ أُرْسِلْنَآ إِلَىٰ قَوْمِ لُوطٍۢ', 'فلما رءا أيديهم لا تصل إليه نكرهم وأوجس منهم خيفة  قالوا لا تخف إنا أرسلنا إلى قوم لوط', NULL, 229, 'local:hafs-text.json'),
  ('hafs-11-71', 'hafs', 11, 71, 'وَٱمْرَأَتُهُۥ قَآئِمَةٌۭ فَضَحِكَتْ فَبَشَّرْنَٰهَا بِإِسْحَٰقَ وَمِن وَرَآءِ إِسْحَٰقَ يَعْقُوبَ', 'وامرأته قائمة فضحكت فبشرنها بإسحق ومن وراء إسحق يعقوب', NULL, 229, 'local:hafs-text.json'),
  ('hafs-11-72', 'hafs', 11, 72, 'قَالَتْ يَٰوَيْلَتَىٰٓ ءَأَلِدُ وَأَنَا۠ عَجُوزٌۭ وَهَٰذَا بَعْلِى شَيْخًا ۖ إِنَّ هَٰذَا لَشَىْءٌ عَجِيبٌۭ', 'قالت يويلتى ءألد وأنا عجوز وهذا بعلى شيخا  إن هذا لشىء عجيب', NULL, 230, 'local:hafs-text.json'),
  ('hafs-11-73', 'hafs', 11, 73, 'قَالُوٓا۟ أَتَعْجَبِينَ مِنْ أَمْرِ ٱللَّهِ ۖ رَحْمَتُ ٱللَّهِ وَبَرَكَٰتُهُۥ عَلَيْكُمْ أَهْلَ ٱلْبَيْتِ ۚ إِنَّهُۥ حَمِيدٌۭ مَّجِيدٌۭ', 'قالوا أتعجبين من أمر الله  رحمت الله وبركته عليكم أهل البيت  إنه حميد مجيد', NULL, 230, 'local:hafs-text.json'),
  ('hafs-11-74', 'hafs', 11, 74, 'فَلَمَّا ذَهَبَ عَنْ إِبْرَٰهِيمَ ٱلرَّوْعُ وَجَآءَتْهُ ٱلْبُشْرَىٰ يُجَٰدِلُنَا فِى قَوْمِ لُوطٍ', 'فلما ذهب عن إبرهيم الروع وجاءته البشرى يجدلنا فى قوم لوط', NULL, 230, 'local:hafs-text.json'),
  ('hafs-11-75', 'hafs', 11, 75, 'إِنَّ إِبْرَٰهِيمَ لَحَلِيمٌ أَوَّٰهٌۭ مُّنِيبٌۭ', 'إن إبرهيم لحليم أوه منيب', NULL, 230, 'local:hafs-text.json'),
  ('hafs-11-76', 'hafs', 11, 76, 'يَٰٓإِبْرَٰهِيمُ أَعْرِضْ عَنْ هَٰذَآ ۖ إِنَّهُۥ قَدْ جَآءَ أَمْرُ رَبِّكَ ۖ وَإِنَّهُمْ ءَاتِيهِمْ عَذَابٌ غَيْرُ مَرْدُودٍۢ', 'يإبرهيم أعرض عن هذا  إنه قد جاء أمر ربك  وإنهم ءاتيهم عذاب غير مردود', NULL, 230, 'local:hafs-text.json'),
  ('hafs-11-77', 'hafs', 11, 77, 'وَلَمَّا جَآءَتْ رُسُلُنَا لُوطًۭا سِىٓءَ بِهِمْ وَضَاقَ بِهِمْ ذَرْعًۭا وَقَالَ هَٰذَا يَوْمٌ عَصِيبٌۭ', 'ولما جاءت رسلنا لوطا سىء بهم وضاق بهم ذرعا وقال هذا يوم عصيب', NULL, 230, 'local:hafs-text.json'),
  ('hafs-11-78', 'hafs', 11, 78, 'وَجَآءَهُۥ قَوْمُهُۥ يُهْرَعُونَ إِلَيْهِ وَمِن قَبْلُ كَانُوا۟ يَعْمَلُونَ ٱلسَّيِّـَٔاتِ ۚ قَالَ يَٰقَوْمِ هَٰٓؤُلَآءِ بَنَاتِى هُنَّ أَطْهَرُ لَكُمْ ۖ فَٱتَّقُوا۟ ٱللَّهَ وَلَا تُخْزُونِ فِى ضَيْفِىٓ ۖ أَلَيْسَ مِنكُمْ رَجُلٌۭ رَّشِيدٌۭ', 'وجاءه قومه يهرعون إليه ومن قبل كانوا يعملون السيات  قال يقوم هؤلاء بناتى هن أطهر لكم  فاتقوا الله ولا تخزون فى ضيفى  أليس منكم رجل رشيد', NULL, 230, 'local:hafs-text.json'),
  ('hafs-11-79', 'hafs', 11, 79, 'قَالُوا۟ لَقَدْ عَلِمْتَ مَا لَنَا فِى بَنَاتِكَ مِنْ حَقٍّۢ وَإِنَّكَ لَتَعْلَمُ مَا نُرِيدُ', 'قالوا لقد علمت ما لنا فى بناتك من حق وإنك لتعلم ما نريد', NULL, 230, 'local:hafs-text.json'),
  ('hafs-11-80', 'hafs', 11, 80, 'قَالَ لَوْ أَنَّ لِى بِكُمْ قُوَّةً أَوْ ءَاوِىٓ إِلَىٰ رُكْنٍۢ شَدِيدٍۢ', 'قال لو أن لى بكم قوة أو ءاوى إلى ركن شديد', NULL, 230, 'local:hafs-text.json'),
  ('hafs-11-81', 'hafs', 11, 81, 'قَالُوا۟ يَٰلُوطُ إِنَّا رُسُلُ رَبِّكَ لَن يَصِلُوٓا۟ إِلَيْكَ ۖ فَأَسْرِ بِأَهْلِكَ بِقِطْعٍۢ مِّنَ ٱلَّيْلِ وَلَا يَلْتَفِتْ مِنكُمْ أَحَدٌ إِلَّا ٱمْرَأَتَكَ ۖ إِنَّهُۥ مُصِيبُهَا مَآ أَصَابَهُمْ ۚ إِنَّ مَوْعِدَهُمُ ٱلصُّبْحُ ۚ أَلَيْسَ ٱلصُّبْحُ بِقَرِيبٍۢ', 'قالوا يلوط إنا رسل ربك لن يصلوا إليك  فأسر بأهلك بقطع من اليل ولا يلتفت منكم أحد إلا امرأتك  إنه مصيبها ما أصابهم  إن موعدهم الصبح  أليس الصبح بقريب', NULL, 230, 'local:hafs-text.json'),
  ('hafs-11-82', 'hafs', 11, 82, 'فَلَمَّا جَآءَ أَمْرُنَا جَعَلْنَا عَٰلِيَهَا سَافِلَهَا وَأَمْطَرْنَا عَلَيْهَا حِجَارَةًۭ مِّن سِجِّيلٍۢ مَّنضُودٍۢ', 'فلما جاء أمرنا جعلنا عليها سافلها وأمطرنا عليها حجارة من سجيل منضود', NULL, 231, 'local:hafs-text.json'),
  ('hafs-11-83', 'hafs', 11, 83, 'مُّسَوَّمَةً عِندَ رَبِّكَ ۖ وَمَا هِىَ مِنَ ٱلظَّٰلِمِينَ بِبَعِيدٍۢ', 'مسومة عند ربك  وما هى من الظلمين ببعيد', NULL, 231, 'local:hafs-text.json'),
  ('hafs-11-84', 'hafs', 11, 84, '۞ وَإِلَىٰ مَدْيَنَ أَخَاهُمْ شُعَيْبًۭا ۚ قَالَ يَٰقَوْمِ ٱعْبُدُوا۟ ٱللَّهَ مَا لَكُم مِّنْ إِلَٰهٍ غَيْرُهُۥ ۖ وَلَا تَنقُصُوا۟ ٱلْمِكْيَالَ وَٱلْمِيزَانَ ۚ إِنِّىٓ أَرَىٰكُم بِخَيْرٍۢ وَإِنِّىٓ أَخَافُ عَلَيْكُمْ عَذَابَ يَوْمٍۢ مُّحِيطٍۢ', 'وإلى مدين أخاهم شعيبا  قال يقوم اعبدوا الله ما لكم من إله غيره  ولا تنقصوا المكيال والميزان  إنى أرىكم بخير وإنى أخاف عليكم عذاب يوم محيط', NULL, 231, 'local:hafs-text.json'),
  ('hafs-11-85', 'hafs', 11, 85, 'وَيَٰقَوْمِ أَوْفُوا۟ ٱلْمِكْيَالَ وَٱلْمِيزَانَ بِٱلْقِسْطِ ۖ وَلَا تَبْخَسُوا۟ ٱلنَّاسَ أَشْيَآءَهُمْ وَلَا تَعْثَوْا۟ فِى ٱلْأَرْضِ مُفْسِدِينَ', 'ويقوم أوفوا المكيال والميزان بالقسط  ولا تبخسوا الناس أشياءهم ولا تعثوا فى الأرض مفسدين', NULL, 231, 'local:hafs-text.json'),
  ('hafs-11-86', 'hafs', 11, 86, 'بَقِيَّتُ ٱللَّهِ خَيْرٌۭ لَّكُمْ إِن كُنتُم مُّؤْمِنِينَ ۚ وَمَآ أَنَا۠ عَلَيْكُم بِحَفِيظٍۢ', 'بقيت الله خير لكم إن كنتم مؤمنين  وما أنا عليكم بحفيظ', NULL, 231, 'local:hafs-text.json'),
  ('hafs-11-87', 'hafs', 11, 87, 'قَالُوا۟ يَٰشُعَيْبُ أَصَلَوٰتُكَ تَأْمُرُكَ أَن نَّتْرُكَ مَا يَعْبُدُ ءَابَآؤُنَآ أَوْ أَن نَّفْعَلَ فِىٓ أَمْوَٰلِنَا مَا نَشَٰٓؤُا۟ ۖ إِنَّكَ لَأَنتَ ٱلْحَلِيمُ ٱلرَّشِيدُ', 'قالوا يشعيب أصلوتك تأمرك أن نترك ما يعبد ءاباؤنا أو أن نفعل فى أمولنا ما نشؤا  إنك لأنت الحليم الرشيد', NULL, 231, 'local:hafs-text.json'),
  ('hafs-11-88', 'hafs', 11, 88, 'قَالَ يَٰقَوْمِ أَرَءَيْتُمْ إِن كُنتُ عَلَىٰ بَيِّنَةٍۢ مِّن رَّبِّى وَرَزَقَنِى مِنْهُ رِزْقًا حَسَنًۭا ۚ وَمَآ أُرِيدُ أَنْ أُخَالِفَكُمْ إِلَىٰ مَآ أَنْهَىٰكُمْ عَنْهُ ۚ إِنْ أُرِيدُ إِلَّا ٱلْإِصْلَٰحَ مَا ٱسْتَطَعْتُ ۚ وَمَا تَوْفِيقِىٓ إِلَّا بِٱللَّهِ ۚ عَلَيْهِ تَوَكَّلْتُ وَإِلَيْهِ أُنِيبُ', 'قال يقوم أرءيتم إن كنت على بينة من ربى ورزقنى منه رزقا حسنا  وما أريد أن أخالفكم إلى ما أنهىكم عنه  إن أريد إلا الإصلح ما استطعت  وما توفيقى إلا بالله  عليه توكلت وإليه أنيب', NULL, 231, 'local:hafs-text.json'),
  ('hafs-11-89', 'hafs', 11, 89, 'وَيَٰقَوْمِ لَا يَجْرِمَنَّكُمْ شِقَاقِىٓ أَن يُصِيبَكُم مِّثْلُ مَآ أَصَابَ قَوْمَ نُوحٍ أَوْ قَوْمَ هُودٍ أَوْ قَوْمَ صَٰلِحٍۢ ۚ وَمَا قَوْمُ لُوطٍۢ مِّنكُم بِبَعِيدٍۢ', 'ويقوم لا يجرمنكم شقاقى أن يصيبكم مثل ما أصاب قوم نوح أو قوم هود أو قوم صلح  وما قوم لوط منكم ببعيد', NULL, 232, 'local:hafs-text.json'),
  ('hafs-11-90', 'hafs', 11, 90, 'وَٱسْتَغْفِرُوا۟ رَبَّكُمْ ثُمَّ تُوبُوٓا۟ إِلَيْهِ ۚ إِنَّ رَبِّى رَحِيمٌۭ وَدُودٌۭ', 'واستغفروا ربكم ثم توبوا إليه  إن ربى رحيم ودود', NULL, 232, 'local:hafs-text.json'),
  ('hafs-11-91', 'hafs', 11, 91, 'قَالُوا۟ يَٰشُعَيْبُ مَا نَفْقَهُ كَثِيرًۭا مِّمَّا تَقُولُ وَإِنَّا لَنَرَىٰكَ فِينَا ضَعِيفًۭا ۖ وَلَوْلَا رَهْطُكَ لَرَجَمْنَٰكَ ۖ وَمَآ أَنتَ عَلَيْنَا بِعَزِيزٍۢ', 'قالوا يشعيب ما نفقه كثيرا مما تقول وإنا لنرىك فينا ضعيفا  ولولا رهطك لرجمنك  وما أنت علينا بعزيز', NULL, 232, 'local:hafs-text.json'),
  ('hafs-11-92', 'hafs', 11, 92, 'قَالَ يَٰقَوْمِ أَرَهْطِىٓ أَعَزُّ عَلَيْكُم مِّنَ ٱللَّهِ وَٱتَّخَذْتُمُوهُ وَرَآءَكُمْ ظِهْرِيًّا ۖ إِنَّ رَبِّى بِمَا تَعْمَلُونَ مُحِيطٌۭ', 'قال يقوم أرهطى أعز عليكم من الله واتخذتموه وراءكم ظهريا  إن ربى بما تعملون محيط', NULL, 232, 'local:hafs-text.json'),
  ('hafs-11-93', 'hafs', 11, 93, 'وَيَٰقَوْمِ ٱعْمَلُوا۟ عَلَىٰ مَكَانَتِكُمْ إِنِّى عَٰمِلٌۭ ۖ سَوْفَ تَعْلَمُونَ مَن يَأْتِيهِ عَذَابٌۭ يُخْزِيهِ وَمَنْ هُوَ كَٰذِبٌۭ ۖ وَٱرْتَقِبُوٓا۟ إِنِّى مَعَكُمْ رَقِيبٌۭ', 'ويقوم اعملوا على مكانتكم إنى عمل  سوف تعلمون من يأتيه عذاب يخزيه ومن هو كذب  وارتقبوا إنى معكم رقيب', NULL, 232, 'local:hafs-text.json'),
  ('hafs-11-94', 'hafs', 11, 94, 'وَلَمَّا جَآءَ أَمْرُنَا نَجَّيْنَا شُعَيْبًۭا وَٱلَّذِينَ ءَامَنُوا۟ مَعَهُۥ بِرَحْمَةٍۢ مِّنَّا وَأَخَذَتِ ٱلَّذِينَ ظَلَمُوا۟ ٱلصَّيْحَةُ فَأَصْبَحُوا۟ فِى دِيَٰرِهِمْ جَٰثِمِينَ', 'ولما جاء أمرنا نجينا شعيبا والذين ءامنوا معه برحمة منا وأخذت الذين ظلموا الصيحة فأصبحوا فى ديرهم جثمين', NULL, 232, 'local:hafs-text.json'),
  ('hafs-11-95', 'hafs', 11, 95, 'كَأَن لَّمْ يَغْنَوْا۟ فِيهَآ ۗ أَلَا بُعْدًۭا لِّمَدْيَنَ كَمَا بَعِدَتْ ثَمُودُ', 'كأن لم يغنوا فيها  ألا بعدا لمدين كما بعدت ثمود', NULL, 232, 'local:hafs-text.json'),
  ('hafs-11-96', 'hafs', 11, 96, 'وَلَقَدْ أَرْسَلْنَا مُوسَىٰ بِـَٔايَٰتِنَا وَسُلْطَٰنٍۢ مُّبِينٍ', 'ولقد أرسلنا موسى بايتنا وسلطن مبين', NULL, 232, 'local:hafs-text.json'),
  ('hafs-11-97', 'hafs', 11, 97, 'إِلَىٰ فِرْعَوْنَ وَمَلَإِي۟هِۦ فَٱتَّبَعُوٓا۟ أَمْرَ فِرْعَوْنَ ۖ وَمَآ أَمْرُ فِرْعَوْنَ بِرَشِيدٍۢ', 'إلى فرعون وملإيه فاتبعوا أمر فرعون  وما أمر فرعون برشيد', NULL, 232, 'local:hafs-text.json'),
  ('hafs-11-98', 'hafs', 11, 98, 'يَقْدُمُ قَوْمَهُۥ يَوْمَ ٱلْقِيَٰمَةِ فَأَوْرَدَهُمُ ٱلنَّارَ ۖ وَبِئْسَ ٱلْوِرْدُ ٱلْمَوْرُودُ', 'يقدم قومه يوم القيمة فأوردهم النار  وبئس الورد المورود', NULL, 233, 'local:hafs-text.json'),
  ('hafs-11-99', 'hafs', 11, 99, 'وَأُتْبِعُوا۟ فِى هَٰذِهِۦ لَعْنَةًۭ وَيَوْمَ ٱلْقِيَٰمَةِ ۚ بِئْسَ ٱلرِّفْدُ ٱلْمَرْفُودُ', 'وأتبعوا فى هذه لعنة ويوم القيمة  بئس الرفد المرفود', NULL, 233, 'local:hafs-text.json'),
  ('hafs-11-100', 'hafs', 11, 100, 'ذَٰلِكَ مِنْ أَنۢبَآءِ ٱلْقُرَىٰ نَقُصُّهُۥ عَلَيْكَ ۖ مِنْهَا قَآئِمٌۭ وَحَصِيدٌۭ', 'ذلك من أنباء القرى نقصه عليك  منها قائم وحصيد', NULL, 233, 'local:hafs-text.json'),
  ('hafs-11-101', 'hafs', 11, 101, 'وَمَا ظَلَمْنَٰهُمْ وَلَٰكِن ظَلَمُوٓا۟ أَنفُسَهُمْ ۖ فَمَآ أَغْنَتْ عَنْهُمْ ءَالِهَتُهُمُ ٱلَّتِى يَدْعُونَ مِن دُونِ ٱللَّهِ مِن شَىْءٍۢ لَّمَّا جَآءَ أَمْرُ رَبِّكَ ۖ وَمَا زَادُوهُمْ غَيْرَ تَتْبِيبٍۢ', 'وما ظلمنهم ولكن ظلموا أنفسهم  فما أغنت عنهم ءالهتهم التى يدعون من دون الله من شىء لما جاء أمر ربك  وما زادوهم غير تتبيب', NULL, 233, 'local:hafs-text.json'),
  ('hafs-11-102', 'hafs', 11, 102, 'وَكَذَٰلِكَ أَخْذُ رَبِّكَ إِذَآ أَخَذَ ٱلْقُرَىٰ وَهِىَ ظَٰلِمَةٌ ۚ إِنَّ أَخْذَهُۥٓ أَلِيمٌۭ شَدِيدٌ', 'وكذلك أخذ ربك إذا أخذ القرى وهى ظلمة  إن أخذه أليم شديد', NULL, 233, 'local:hafs-text.json'),
  ('hafs-11-103', 'hafs', 11, 103, 'إِنَّ فِى ذَٰلِكَ لَءَايَةًۭ لِّمَنْ خَافَ عَذَابَ ٱلْءَاخِرَةِ ۚ ذَٰلِكَ يَوْمٌۭ مَّجْمُوعٌۭ لَّهُ ٱلنَّاسُ وَذَٰلِكَ يَوْمٌۭ مَّشْهُودٌۭ', 'إن فى ذلك لءاية لمن خاف عذاب الءاخرة  ذلك يوم مجموع له الناس وذلك يوم مشهود', NULL, 233, 'local:hafs-text.json'),
  ('hafs-11-104', 'hafs', 11, 104, 'وَمَا نُؤَخِّرُهُۥٓ إِلَّا لِأَجَلٍۢ مَّعْدُودٍۢ', 'وما نؤخره إلا لأجل معدود', NULL, 233, 'local:hafs-text.json'),
  ('hafs-11-105', 'hafs', 11, 105, 'يَوْمَ يَأْتِ لَا تَكَلَّمُ نَفْسٌ إِلَّا بِإِذْنِهِۦ ۚ فَمِنْهُمْ شَقِىٌّۭ وَسَعِيدٌۭ', 'يوم يأت لا تكلم نفس إلا بإذنه  فمنهم شقى وسعيد', NULL, 233, 'local:hafs-text.json'),
  ('hafs-11-106', 'hafs', 11, 106, 'فَأَمَّا ٱلَّذِينَ شَقُوا۟ فَفِى ٱلنَّارِ لَهُمْ فِيهَا زَفِيرٌۭ وَشَهِيقٌ', 'فأما الذين شقوا ففى النار لهم فيها زفير وشهيق', NULL, 233, 'local:hafs-text.json'),
  ('hafs-11-107', 'hafs', 11, 107, 'خَٰلِدِينَ فِيهَا مَا دَامَتِ ٱلسَّمَٰوَٰتُ وَٱلْأَرْضُ إِلَّا مَا شَآءَ رَبُّكَ ۚ إِنَّ رَبَّكَ فَعَّالٌۭ لِّمَا يُرِيدُ', 'خلدين فيها ما دامت السموت والأرض إلا ما شاء ربك  إن ربك فعال لما يريد', NULL, 233, 'local:hafs-text.json'),
  ('hafs-11-108', 'hafs', 11, 108, '۞ وَأَمَّا ٱلَّذِينَ سُعِدُوا۟ فَفِى ٱلْجَنَّةِ خَٰلِدِينَ فِيهَا مَا دَامَتِ ٱلسَّمَٰوَٰتُ وَٱلْأَرْضُ إِلَّا مَا شَآءَ رَبُّكَ ۖ عَطَآءً غَيْرَ مَجْذُوذٍۢ', 'وأما الذين سعدوا ففى الجنة خلدين فيها ما دامت السموت والأرض إلا ما شاء ربك  عطاء غير مجذوذ', NULL, 233, 'local:hafs-text.json'),
  ('hafs-11-109', 'hafs', 11, 109, 'فَلَا تَكُ فِى مِرْيَةٍۢ مِّمَّا يَعْبُدُ هَٰٓؤُلَآءِ ۚ مَا يَعْبُدُونَ إِلَّا كَمَا يَعْبُدُ ءَابَآؤُهُم مِّن قَبْلُ ۚ وَإِنَّا لَمُوَفُّوهُمْ نَصِيبَهُمْ غَيْرَ مَنقُوصٍۢ', 'فلا تك فى مرية مما يعبد هؤلاء  ما يعبدون إلا كما يعبد ءاباؤهم من قبل  وإنا لموفوهم نصيبهم غير منقوص', NULL, 234, 'local:hafs-text.json'),
  ('hafs-11-110', 'hafs', 11, 110, 'وَلَقَدْ ءَاتَيْنَا مُوسَى ٱلْكِتَٰبَ فَٱخْتُلِفَ فِيهِ ۚ وَلَوْلَا كَلِمَةٌۭ سَبَقَتْ مِن رَّبِّكَ لَقُضِىَ بَيْنَهُمْ ۚ وَإِنَّهُمْ لَفِى شَكٍّۢ مِّنْهُ مُرِيبٍۢ', 'ولقد ءاتينا موسى الكتب فاختلف فيه  ولولا كلمة سبقت من ربك لقضى بينهم  وإنهم لفى شك منه مريب', NULL, 234, 'local:hafs-text.json'),
  ('hafs-11-111', 'hafs', 11, 111, 'وَإِنَّ كُلًّۭا لَّمَّا لَيُوَفِّيَنَّهُمْ رَبُّكَ أَعْمَٰلَهُمْ ۚ إِنَّهُۥ بِمَا يَعْمَلُونَ خَبِيرٌۭ', 'وإن كلا لما ليوفينهم ربك أعملهم  إنه بما يعملون خبير', NULL, 234, 'local:hafs-text.json'),
  ('hafs-11-112', 'hafs', 11, 112, 'فَٱسْتَقِمْ كَمَآ أُمِرْتَ وَمَن تَابَ مَعَكَ وَلَا تَطْغَوْا۟ ۚ إِنَّهُۥ بِمَا تَعْمَلُونَ بَصِيرٌۭ', 'فاستقم كما أمرت ومن تاب معك ولا تطغوا  إنه بما تعملون بصير', NULL, 234, 'local:hafs-text.json'),
  ('hafs-11-113', 'hafs', 11, 113, 'وَلَا تَرْكَنُوٓا۟ إِلَى ٱلَّذِينَ ظَلَمُوا۟ فَتَمَسَّكُمُ ٱلنَّارُ وَمَا لَكُم مِّن دُونِ ٱللَّهِ مِنْ أَوْلِيَآءَ ثُمَّ لَا تُنصَرُونَ', 'ولا تركنوا إلى الذين ظلموا فتمسكم النار وما لكم من دون الله من أولياء ثم لا تنصرون', NULL, 234, 'local:hafs-text.json'),
  ('hafs-11-114', 'hafs', 11, 114, 'وَأَقِمِ ٱلصَّلَوٰةَ طَرَفَىِ ٱلنَّهَارِ وَزُلَفًۭا مِّنَ ٱلَّيْلِ ۚ إِنَّ ٱلْحَسَنَٰتِ يُذْهِبْنَ ٱلسَّيِّـَٔاتِ ۚ ذَٰلِكَ ذِكْرَىٰ لِلذَّٰكِرِينَ', 'وأقم الصلوة طرفى النهار وزلفا من اليل  إن الحسنت يذهبن السيات  ذلك ذكرى للذكرين', NULL, 234, 'local:hafs-text.json'),
  ('hafs-11-115', 'hafs', 11, 115, 'وَٱصْبِرْ فَإِنَّ ٱللَّهَ لَا يُضِيعُ أَجْرَ ٱلْمُحْسِنِينَ', 'واصبر فإن الله لا يضيع أجر المحسنين', NULL, 234, 'local:hafs-text.json'),
  ('hafs-11-116', 'hafs', 11, 116, 'فَلَوْلَا كَانَ مِنَ ٱلْقُرُونِ مِن قَبْلِكُمْ أُو۟لُوا۟ بَقِيَّةٍۢ يَنْهَوْنَ عَنِ ٱلْفَسَادِ فِى ٱلْأَرْضِ إِلَّا قَلِيلًۭا مِّمَّنْ أَنجَيْنَا مِنْهُمْ ۗ وَٱتَّبَعَ ٱلَّذِينَ ظَلَمُوا۟ مَآ أُتْرِفُوا۟ فِيهِ وَكَانُوا۟ مُجْرِمِينَ', 'فلولا كان من القرون من قبلكم أولوا بقية ينهون عن الفساد فى الأرض إلا قليلا ممن أنجينا منهم  واتبع الذين ظلموا ما أترفوا فيه وكانوا مجرمين', NULL, 234, 'local:hafs-text.json'),
  ('hafs-11-117', 'hafs', 11, 117, 'وَمَا كَانَ رَبُّكَ لِيُهْلِكَ ٱلْقُرَىٰ بِظُلْمٍۢ وَأَهْلُهَا مُصْلِحُونَ', 'وما كان ربك ليهلك القرى بظلم وأهلها مصلحون', NULL, 234, 'local:hafs-text.json'),
  ('hafs-11-118', 'hafs', 11, 118, 'وَلَوْ شَآءَ رَبُّكَ لَجَعَلَ ٱلنَّاسَ أُمَّةًۭ وَٰحِدَةًۭ ۖ وَلَا يَزَالُونَ مُخْتَلِفِينَ', 'ولو شاء ربك لجعل الناس أمة وحدة  ولا يزالون مختلفين', NULL, 235, 'local:hafs-text.json'),
  ('hafs-11-119', 'hafs', 11, 119, 'إِلَّا مَن رَّحِمَ رَبُّكَ ۚ وَلِذَٰلِكَ خَلَقَهُمْ ۗ وَتَمَّتْ كَلِمَةُ رَبِّكَ لَأَمْلَأَنَّ جَهَنَّمَ مِنَ ٱلْجِنَّةِ وَٱلنَّاسِ أَجْمَعِينَ', 'إلا من رحم ربك  ولذلك خلقهم  وتمت كلمة ربك لأملأن جهنم من الجنة والناس أجمعين', NULL, 235, 'local:hafs-text.json'),
  ('hafs-11-120', 'hafs', 11, 120, 'وَكُلًّۭا نَّقُصُّ عَلَيْكَ مِنْ أَنۢبَآءِ ٱلرُّسُلِ مَا نُثَبِّتُ بِهِۦ فُؤَادَكَ ۚ وَجَآءَكَ فِى هَٰذِهِ ٱلْحَقُّ وَمَوْعِظَةٌۭ وَذِكْرَىٰ لِلْمُؤْمِنِينَ', 'وكلا نقص عليك من أنباء الرسل ما نثبت به فؤادك  وجاءك فى هذه الحق وموعظة وذكرى للمؤمنين', NULL, 235, 'local:hafs-text.json'),
  ('hafs-11-121', 'hafs', 11, 121, 'وَقُل لِّلَّذِينَ لَا يُؤْمِنُونَ ٱعْمَلُوا۟ عَلَىٰ مَكَانَتِكُمْ إِنَّا عَٰمِلُونَ', 'وقل للذين لا يؤمنون اعملوا على مكانتكم إنا عملون', NULL, 235, 'local:hafs-text.json'),
  ('hafs-11-122', 'hafs', 11, 122, 'وَٱنتَظِرُوٓا۟ إِنَّا مُنتَظِرُونَ', 'وانتظروا إنا منتظرون', NULL, 235, 'local:hafs-text.json'),
  ('hafs-11-123', 'hafs', 11, 123, 'وَلِلَّهِ غَيْبُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَإِلَيْهِ يُرْجَعُ ٱلْأَمْرُ كُلُّهُۥ فَٱعْبُدْهُ وَتَوَكَّلْ عَلَيْهِ ۚ وَمَا رَبُّكَ بِغَٰفِلٍ عَمَّا تَعْمَلُونَ', 'ولله غيب السموت والأرض وإليه يرجع الأمر كله فاعبده وتوكل عليه  وما ربك بغفل عما تعملون', NULL, 235, 'local:hafs-text.json'),
  ('hafs-12-1', 'hafs', 12, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ الٓر ۚ تِلْكَ ءَايَٰتُ ٱلْكِتَٰبِ ٱلْمُبِينِ', 'بسم الله الرحمن الرحيم الر  تلك ءايت الكتب المبين', NULL, 235, 'local:hafs-text.json'),
  ('hafs-12-2', 'hafs', 12, 2, 'إِنَّآ أَنزَلْنَٰهُ قُرْءَٰنًا عَرَبِيًّۭا لَّعَلَّكُمْ تَعْقِلُونَ', 'إنا أنزلنه قرءنا عربيا لعلكم تعقلون', NULL, 235, 'local:hafs-text.json'),
  ('hafs-12-3', 'hafs', 12, 3, 'نَحْنُ نَقُصُّ عَلَيْكَ أَحْسَنَ ٱلْقَصَصِ بِمَآ أَوْحَيْنَآ إِلَيْكَ هَٰذَا ٱلْقُرْءَانَ وَإِن كُنتَ مِن قَبْلِهِۦ لَمِنَ ٱلْغَٰفِلِينَ', 'نحن نقص عليك أحسن القصص بما أوحينا إليك هذا القرءان وإن كنت من قبله لمن الغفلين', NULL, 235, 'local:hafs-text.json'),
  ('hafs-12-4', 'hafs', 12, 4, 'إِذْ قَالَ يُوسُفُ لِأَبِيهِ يَٰٓأَبَتِ إِنِّى رَأَيْتُ أَحَدَ عَشَرَ كَوْكَبًۭا وَٱلشَّمْسَ وَٱلْقَمَرَ رَأَيْتُهُمْ لِى سَٰجِدِينَ', 'إذ قال يوسف لأبيه يأبت إنى رأيت أحد عشر كوكبا والشمس والقمر رأيتهم لى سجدين', NULL, 235, 'local:hafs-text.json')
insert into public.ayahs (id, riwayah, surah_number, ayah_number, text, simple_text, juz, page, source) values
  ('hafs-12-5', 'hafs', 12, 5, 'قَالَ يَٰبُنَىَّ لَا تَقْصُصْ رُءْيَاكَ عَلَىٰٓ إِخْوَتِكَ فَيَكِيدُوا۟ لَكَ كَيْدًا ۖ إِنَّ ٱلشَّيْطَٰنَ لِلْإِنسَٰنِ عَدُوٌّۭ مُّبِينٌۭ', 'قال يبنى لا تقصص رءياك على إخوتك فيكيدوا لك كيدا  إن الشيطن للإنسن عدو مبين', NULL, 236, 'local:hafs-text.json'),
  ('hafs-12-6', 'hafs', 12, 6, 'وَكَذَٰلِكَ يَجْتَبِيكَ رَبُّكَ وَيُعَلِّمُكَ مِن تَأْوِيلِ ٱلْأَحَادِيثِ وَيُتِمُّ نِعْمَتَهُۥ عَلَيْكَ وَعَلَىٰٓ ءَالِ يَعْقُوبَ كَمَآ أَتَمَّهَا عَلَىٰٓ أَبَوَيْكَ مِن قَبْلُ إِبْرَٰهِيمَ وَإِسْحَٰقَ ۚ إِنَّ رَبَّكَ عَلِيمٌ حَكِيمٌۭ', 'وكذلك يجتبيك ربك ويعلمك من تأويل الأحاديث ويتم نعمته عليك وعلى ءال يعقوب كما أتمها على أبويك من قبل إبرهيم وإسحق  إن ربك عليم حكيم', NULL, 236, 'local:hafs-text.json'),
  ('hafs-12-7', 'hafs', 12, 7, '۞ لَّقَدْ كَانَ فِى يُوسُفَ وَإِخْوَتِهِۦٓ ءَايَٰتٌۭ لِّلسَّآئِلِينَ', 'لقد كان فى يوسف وإخوته ءايت للسائلين', NULL, 236, 'local:hafs-text.json'),
  ('hafs-12-8', 'hafs', 12, 8, 'إِذْ قَالُوا۟ لَيُوسُفُ وَأَخُوهُ أَحَبُّ إِلَىٰٓ أَبِينَا مِنَّا وَنَحْنُ عُصْبَةٌ إِنَّ أَبَانَا لَفِى ضَلَٰلٍۢ مُّبِينٍ', 'إذ قالوا ليوسف وأخوه أحب إلى أبينا منا ونحن عصبة إن أبانا لفى ضلل مبين', NULL, 236, 'local:hafs-text.json'),
  ('hafs-12-9', 'hafs', 12, 9, 'ٱقْتُلُوا۟ يُوسُفَ أَوِ ٱطْرَحُوهُ أَرْضًۭا يَخْلُ لَكُمْ وَجْهُ أَبِيكُمْ وَتَكُونُوا۟ مِنۢ بَعْدِهِۦ قَوْمًۭا صَٰلِحِينَ', 'اقتلوا يوسف أو اطرحوه أرضا يخل لكم وجه أبيكم وتكونوا من بعده قوما صلحين', NULL, 236, 'local:hafs-text.json'),
  ('hafs-12-10', 'hafs', 12, 10, 'قَالَ قَآئِلٌۭ مِّنْهُمْ لَا تَقْتُلُوا۟ يُوسُفَ وَأَلْقُوهُ فِى غَيَٰبَتِ ٱلْجُبِّ يَلْتَقِطْهُ بَعْضُ ٱلسَّيَّارَةِ إِن كُنتُمْ فَٰعِلِينَ', 'قال قائل منهم لا تقتلوا يوسف وألقوه فى غيبت الجب يلتقطه بعض السيارة إن كنتم فعلين', NULL, 236, 'local:hafs-text.json'),
  ('hafs-12-11', 'hafs', 12, 11, 'قَالُوا۟ يَٰٓأَبَانَا مَا لَكَ لَا تَأْمَ۫نَّا عَلَىٰ يُوسُفَ وَإِنَّا لَهُۥ لَنَٰصِحُونَ', 'قالوا يأبانا ما لك لا تأمنا على يوسف وإنا له لنصحون', NULL, 236, 'local:hafs-text.json'),
  ('hafs-12-12', 'hafs', 12, 12, 'أَرْسِلْهُ مَعَنَا غَدًۭا يَرْتَعْ وَيَلْعَبْ وَإِنَّا لَهُۥ لَحَٰفِظُونَ', 'أرسله معنا غدا يرتع ويلعب وإنا له لحفظون', NULL, 236, 'local:hafs-text.json'),
  ('hafs-12-13', 'hafs', 12, 13, 'قَالَ إِنِّى لَيَحْزُنُنِىٓ أَن تَذْهَبُوا۟ بِهِۦ وَأَخَافُ أَن يَأْكُلَهُ ٱلذِّئْبُ وَأَنتُمْ عَنْهُ غَٰفِلُونَ', 'قال إنى ليحزننى أن تذهبوا به وأخاف أن يأكله الذئب وأنتم عنه غفلون', NULL, 236, 'local:hafs-text.json'),
  ('hafs-12-14', 'hafs', 12, 14, 'قَالُوا۟ لَئِنْ أَكَلَهُ ٱلذِّئْبُ وَنَحْنُ عُصْبَةٌ إِنَّآ إِذًۭا لَّخَٰسِرُونَ', 'قالوا لئن أكله الذئب ونحن عصبة إنا إذا لخسرون', NULL, 236, 'local:hafs-text.json'),
  ('hafs-12-15', 'hafs', 12, 15, 'فَلَمَّا ذَهَبُوا۟ بِهِۦ وَأَجْمَعُوٓا۟ أَن يَجْعَلُوهُ فِى غَيَٰبَتِ ٱلْجُبِّ ۚ وَأَوْحَيْنَآ إِلَيْهِ لَتُنَبِّئَنَّهُم بِأَمْرِهِمْ هَٰذَا وَهُمْ لَا يَشْعُرُونَ', 'فلما ذهبوا به وأجمعوا أن يجعلوه فى غيبت الجب  وأوحينا إليه لتنبئنهم بأمرهم هذا وهم لا يشعرون', NULL, 237, 'local:hafs-text.json'),
  ('hafs-12-16', 'hafs', 12, 16, 'وَجَآءُوٓ أَبَاهُمْ عِشَآءًۭ يَبْكُونَ', 'وجاءو أباهم عشاء يبكون', NULL, 237, 'local:hafs-text.json'),
  ('hafs-12-17', 'hafs', 12, 17, 'قَالُوا۟ يَٰٓأَبَانَآ إِنَّا ذَهَبْنَا نَسْتَبِقُ وَتَرَكْنَا يُوسُفَ عِندَ مَتَٰعِنَا فَأَكَلَهُ ٱلذِّئْبُ ۖ وَمَآ أَنتَ بِمُؤْمِنٍۢ لَّنَا وَلَوْ كُنَّا صَٰدِقِينَ', 'قالوا يأبانا إنا ذهبنا نستبق وتركنا يوسف عند متعنا فأكله الذئب  وما أنت بمؤمن لنا ولو كنا صدقين', NULL, 237, 'local:hafs-text.json'),
  ('hafs-12-18', 'hafs', 12, 18, 'وَجَآءُو عَلَىٰ قَمِيصِهِۦ بِدَمٍۢ كَذِبٍۢ ۚ قَالَ بَلْ سَوَّلَتْ لَكُمْ أَنفُسُكُمْ أَمْرًۭا ۖ فَصَبْرٌۭ جَمِيلٌۭ ۖ وَٱللَّهُ ٱلْمُسْتَعَانُ عَلَىٰ مَا تَصِفُونَ', 'وجاءو على قميصه بدم كذب  قال بل سولت لكم أنفسكم أمرا  فصبر جميل  والله المستعان على ما تصفون', NULL, 237, 'local:hafs-text.json'),
  ('hafs-12-19', 'hafs', 12, 19, 'وَجَآءَتْ سَيَّارَةٌۭ فَأَرْسَلُوا۟ وَارِدَهُمْ فَأَدْلَىٰ دَلْوَهُۥ ۖ قَالَ يَٰبُشْرَىٰ هَٰذَا غُلَٰمٌۭ ۚ وَأَسَرُّوهُ بِضَٰعَةًۭ ۚ وَٱللَّهُ عَلِيمٌۢ بِمَا يَعْمَلُونَ', 'وجاءت سيارة فأرسلوا واردهم فأدلى دلوه  قال يبشرى هذا غلم  وأسروه بضعة  والله عليم بما يعملون', NULL, 237, 'local:hafs-text.json'),
  ('hafs-12-20', 'hafs', 12, 20, 'وَشَرَوْهُ بِثَمَنٍۭ بَخْسٍۢ دَرَٰهِمَ مَعْدُودَةٍۢ وَكَانُوا۟ فِيهِ مِنَ ٱلزَّٰهِدِينَ', 'وشروه بثمن بخس درهم معدودة وكانوا فيه من الزهدين', NULL, 237, 'local:hafs-text.json'),
  ('hafs-12-21', 'hafs', 12, 21, 'وَقَالَ ٱلَّذِى ٱشْتَرَىٰهُ مِن مِّصْرَ لِٱمْرَأَتِهِۦٓ أَكْرِمِى مَثْوَىٰهُ عَسَىٰٓ أَن يَنفَعَنَآ أَوْ نَتَّخِذَهُۥ وَلَدًۭا ۚ وَكَذَٰلِكَ مَكَّنَّا لِيُوسُفَ فِى ٱلْأَرْضِ وَلِنُعَلِّمَهُۥ مِن تَأْوِيلِ ٱلْأَحَادِيثِ ۚ وَٱللَّهُ غَالِبٌ عَلَىٰٓ أَمْرِهِۦ وَلَٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يَعْلَمُونَ', 'وقال الذى اشترىه من مصر لامرأته أكرمى مثوىه عسى أن ينفعنا أو نتخذه ولدا  وكذلك مكنا ليوسف فى الأرض ولنعلمه من تأويل الأحاديث  والله غالب على أمره ولكن أكثر الناس لا يعلمون', NULL, 237, 'local:hafs-text.json'),
  ('hafs-12-22', 'hafs', 12, 22, 'وَلَمَّا بَلَغَ أَشُدَّهُۥٓ ءَاتَيْنَٰهُ حُكْمًۭا وَعِلْمًۭا ۚ وَكَذَٰلِكَ نَجْزِى ٱلْمُحْسِنِينَ', 'ولما بلغ أشده ءاتينه حكما وعلما  وكذلك نجزى المحسنين', NULL, 237, 'local:hafs-text.json'),
  ('hafs-12-23', 'hafs', 12, 23, 'وَرَٰوَدَتْهُ ٱلَّتِى هُوَ فِى بَيْتِهَا عَن نَّفْسِهِۦ وَغَلَّقَتِ ٱلْأَبْوَٰبَ وَقَالَتْ هَيْتَ لَكَ ۚ قَالَ مَعَاذَ ٱللَّهِ ۖ إِنَّهُۥ رَبِّىٓ أَحْسَنَ مَثْوَاىَ ۖ إِنَّهُۥ لَا يُفْلِحُ ٱلظَّٰلِمُونَ', 'ورودته التى هو فى بيتها عن نفسه وغلقت الأبوب وقالت هيت لك  قال معاذ الله  إنه ربى أحسن مثواى  إنه لا يفلح الظلمون', NULL, 238, 'local:hafs-text.json'),
  ('hafs-12-24', 'hafs', 12, 24, 'وَلَقَدْ هَمَّتْ بِهِۦ ۖ وَهَمَّ بِهَا لَوْلَآ أَن رَّءَا بُرْهَٰنَ رَبِّهِۦ ۚ كَذَٰلِكَ لِنَصْرِفَ عَنْهُ ٱلسُّوٓءَ وَٱلْفَحْشَآءَ ۚ إِنَّهُۥ مِنْ عِبَادِنَا ٱلْمُخْلَصِينَ', 'ولقد همت به  وهم بها لولا أن رءا برهن ربه  كذلك لنصرف عنه السوء والفحشاء  إنه من عبادنا المخلصين', NULL, 238, 'local:hafs-text.json'),
  ('hafs-12-25', 'hafs', 12, 25, 'وَٱسْتَبَقَا ٱلْبَابَ وَقَدَّتْ قَمِيصَهُۥ مِن دُبُرٍۢ وَأَلْفَيَا سَيِّدَهَا لَدَا ٱلْبَابِ ۚ قَالَتْ مَا جَزَآءُ مَنْ أَرَادَ بِأَهْلِكَ سُوٓءًا إِلَّآ أَن يُسْجَنَ أَوْ عَذَابٌ أَلِيمٌۭ', 'واستبقا الباب وقدت قميصه من دبر وألفيا سيدها لدا الباب  قالت ما جزاء من أراد بأهلك سوءا إلا أن يسجن أو عذاب أليم', NULL, 238, 'local:hafs-text.json'),
  ('hafs-12-26', 'hafs', 12, 26, 'قَالَ هِىَ رَٰوَدَتْنِى عَن نَّفْسِى ۚ وَشَهِدَ شَاهِدٌۭ مِّنْ أَهْلِهَآ إِن كَانَ قَمِيصُهُۥ قُدَّ مِن قُبُلٍۢ فَصَدَقَتْ وَهُوَ مِنَ ٱلْكَٰذِبِينَ', 'قال هى رودتنى عن نفسى  وشهد شاهد من أهلها إن كان قميصه قد من قبل فصدقت وهو من الكذبين', NULL, 238, 'local:hafs-text.json'),
  ('hafs-12-27', 'hafs', 12, 27, 'وَإِن كَانَ قَمِيصُهُۥ قُدَّ مِن دُبُرٍۢ فَكَذَبَتْ وَهُوَ مِنَ ٱلصَّٰدِقِينَ', 'وإن كان قميصه قد من دبر فكذبت وهو من الصدقين', NULL, 238, 'local:hafs-text.json'),
  ('hafs-12-28', 'hafs', 12, 28, 'فَلَمَّا رَءَا قَمِيصَهُۥ قُدَّ مِن دُبُرٍۢ قَالَ إِنَّهُۥ مِن كَيْدِكُنَّ ۖ إِنَّ كَيْدَكُنَّ عَظِيمٌۭ', 'فلما رءا قميصه قد من دبر قال إنه من كيدكن  إن كيدكن عظيم', NULL, 238, 'local:hafs-text.json'),
  ('hafs-12-29', 'hafs', 12, 29, 'يُوسُفُ أَعْرِضْ عَنْ هَٰذَا ۚ وَٱسْتَغْفِرِى لِذَنۢبِكِ ۖ إِنَّكِ كُنتِ مِنَ ٱلْخَاطِـِٔينَ', 'يوسف أعرض عن هذا  واستغفرى لذنبك  إنك كنت من الخاطين', NULL, 238, 'local:hafs-text.json'),
  ('hafs-12-30', 'hafs', 12, 30, '۞ وَقَالَ نِسْوَةٌۭ فِى ٱلْمَدِينَةِ ٱمْرَأَتُ ٱلْعَزِيزِ تُرَٰوِدُ فَتَىٰهَا عَن نَّفْسِهِۦ ۖ قَدْ شَغَفَهَا حُبًّا ۖ إِنَّا لَنَرَىٰهَا فِى ضَلَٰلٍۢ مُّبِينٍۢ', 'وقال نسوة فى المدينة امرأت العزيز ترود فتىها عن نفسه  قد شغفها حبا  إنا لنرىها فى ضلل مبين', NULL, 238, 'local:hafs-text.json'),
  ('hafs-12-31', 'hafs', 12, 31, 'فَلَمَّا سَمِعَتْ بِمَكْرِهِنَّ أَرْسَلَتْ إِلَيْهِنَّ وَأَعْتَدَتْ لَهُنَّ مُتَّكَـًۭٔا وَءَاتَتْ كُلَّ وَٰحِدَةٍۢ مِّنْهُنَّ سِكِّينًۭا وَقَالَتِ ٱخْرُجْ عَلَيْهِنَّ ۖ فَلَمَّا رَأَيْنَهُۥٓ أَكْبَرْنَهُۥ وَقَطَّعْنَ أَيْدِيَهُنَّ وَقُلْنَ حَٰشَ لِلَّهِ مَا هَٰذَا بَشَرًا إِنْ هَٰذَآ إِلَّا مَلَكٌۭ كَرِيمٌۭ', 'فلما سمعت بمكرهن أرسلت إليهن وأعتدت لهن متكا وءاتت كل وحدة منهن سكينا وقالت اخرج عليهن  فلما رأينه أكبرنه وقطعن أيديهن وقلن حش لله ما هذا بشرا إن هذا إلا ملك كريم', NULL, 239, 'local:hafs-text.json'),
  ('hafs-12-32', 'hafs', 12, 32, 'قَالَتْ فَذَٰلِكُنَّ ٱلَّذِى لُمْتُنَّنِى فِيهِ ۖ وَلَقَدْ رَٰوَدتُّهُۥ عَن نَّفْسِهِۦ فَٱسْتَعْصَمَ ۖ وَلَئِن لَّمْ يَفْعَلْ مَآ ءَامُرُهُۥ لَيُسْجَنَنَّ وَلَيَكُونًۭا مِّنَ ٱلصَّٰغِرِينَ', 'قالت فذلكن الذى لمتننى فيه  ولقد رودته عن نفسه فاستعصم  ولئن لم يفعل ما ءامره ليسجنن وليكونا من الصغرين', NULL, 239, 'local:hafs-text.json'),
  ('hafs-12-33', 'hafs', 12, 33, 'قَالَ رَبِّ ٱلسِّجْنُ أَحَبُّ إِلَىَّ مِمَّا يَدْعُونَنِىٓ إِلَيْهِ ۖ وَإِلَّا تَصْرِفْ عَنِّى كَيْدَهُنَّ أَصْبُ إِلَيْهِنَّ وَأَكُن مِّنَ ٱلْجَٰهِلِينَ', 'قال رب السجن أحب إلى مما يدعوننى إليه  وإلا تصرف عنى كيدهن أصب إليهن وأكن من الجهلين', NULL, 239, 'local:hafs-text.json'),
  ('hafs-12-34', 'hafs', 12, 34, 'فَٱسْتَجَابَ لَهُۥ رَبُّهُۥ فَصَرَفَ عَنْهُ كَيْدَهُنَّ ۚ إِنَّهُۥ هُوَ ٱلسَّمِيعُ ٱلْعَلِيمُ', 'فاستجاب له ربه فصرف عنه كيدهن  إنه هو السميع العليم', NULL, 239, 'local:hafs-text.json'),
  ('hafs-12-35', 'hafs', 12, 35, 'ثُمَّ بَدَا لَهُم مِّنۢ بَعْدِ مَا رَأَوُا۟ ٱلْءَايَٰتِ لَيَسْجُنُنَّهُۥ حَتَّىٰ حِينٍۢ', 'ثم بدا لهم من بعد ما رأوا الءايت ليسجننه حتى حين', NULL, 239, 'local:hafs-text.json'),
  ('hafs-12-36', 'hafs', 12, 36, 'وَدَخَلَ مَعَهُ ٱلسِّجْنَ فَتَيَانِ ۖ قَالَ أَحَدُهُمَآ إِنِّىٓ أَرَىٰنِىٓ أَعْصِرُ خَمْرًۭا ۖ وَقَالَ ٱلْءَاخَرُ إِنِّىٓ أَرَىٰنِىٓ أَحْمِلُ فَوْقَ رَأْسِى خُبْزًۭا تَأْكُلُ ٱلطَّيْرُ مِنْهُ ۖ نَبِّئْنَا بِتَأْوِيلِهِۦٓ ۖ إِنَّا نَرَىٰكَ مِنَ ٱلْمُحْسِنِينَ', 'ودخل معه السجن فتيان  قال أحدهما إنى أرىنى أعصر خمرا  وقال الءاخر إنى أرىنى أحمل فوق رأسى خبزا تأكل الطير منه  نبئنا بتأويله  إنا نرىك من المحسنين', NULL, 239, 'local:hafs-text.json'),
  ('hafs-12-37', 'hafs', 12, 37, 'قَالَ لَا يَأْتِيكُمَا طَعَامٌۭ تُرْزَقَانِهِۦٓ إِلَّا نَبَّأْتُكُمَا بِتَأْوِيلِهِۦ قَبْلَ أَن يَأْتِيَكُمَا ۚ ذَٰلِكُمَا مِمَّا عَلَّمَنِى رَبِّىٓ ۚ إِنِّى تَرَكْتُ مِلَّةَ قَوْمٍۢ لَّا يُؤْمِنُونَ بِٱللَّهِ وَهُم بِٱلْءَاخِرَةِ هُمْ كَٰفِرُونَ', 'قال لا يأتيكما طعام ترزقانه إلا نبأتكما بتأويله قبل أن يأتيكما  ذلكما مما علمنى ربى  إنى تركت ملة قوم لا يؤمنون بالله وهم بالءاخرة هم كفرون', NULL, 239, 'local:hafs-text.json'),
  ('hafs-12-38', 'hafs', 12, 38, 'وَٱتَّبَعْتُ مِلَّةَ ءَابَآءِىٓ إِبْرَٰهِيمَ وَإِسْحَٰقَ وَيَعْقُوبَ ۚ مَا كَانَ لَنَآ أَن نُّشْرِكَ بِٱللَّهِ مِن شَىْءٍۢ ۚ ذَٰلِكَ مِن فَضْلِ ٱللَّهِ عَلَيْنَا وَعَلَى ٱلنَّاسِ وَلَٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يَشْكُرُونَ', 'واتبعت ملة ءاباءى إبرهيم وإسحق ويعقوب  ما كان لنا أن نشرك بالله من شىء  ذلك من فضل الله علينا وعلى الناس ولكن أكثر الناس لا يشكرون', NULL, 240, 'local:hafs-text.json'),
  ('hafs-12-39', 'hafs', 12, 39, 'يَٰصَىٰحِبَىِ ٱلسِّجْنِ ءَأَرْبَابٌۭ مُّتَفَرِّقُونَ خَيْرٌ أَمِ ٱللَّهُ ٱلْوَٰحِدُ ٱلْقَهَّارُ', 'يصىحبى السجن ءأرباب متفرقون خير أم الله الوحد القهار', NULL, 240, 'local:hafs-text.json'),
  ('hafs-12-40', 'hafs', 12, 40, 'مَا تَعْبُدُونَ مِن دُونِهِۦٓ إِلَّآ أَسْمَآءًۭ سَمَّيْتُمُوهَآ أَنتُمْ وَءَابَآؤُكُم مَّآ أَنزَلَ ٱللَّهُ بِهَا مِن سُلْطَٰنٍ ۚ إِنِ ٱلْحُكْمُ إِلَّا لِلَّهِ ۚ أَمَرَ أَلَّا تَعْبُدُوٓا۟ إِلَّآ إِيَّاهُ ۚ ذَٰلِكَ ٱلدِّينُ ٱلْقَيِّمُ وَلَٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يَعْلَمُونَ', 'ما تعبدون من دونه إلا أسماء سميتموها أنتم وءاباؤكم ما أنزل الله بها من سلطن  إن الحكم إلا لله  أمر ألا تعبدوا إلا إياه  ذلك الدين القيم ولكن أكثر الناس لا يعلمون', NULL, 240, 'local:hafs-text.json'),
  ('hafs-12-41', 'hafs', 12, 41, 'يَٰصَىٰحِبَىِ ٱلسِّجْنِ أَمَّآ أَحَدُكُمَا فَيَسْقِى رَبَّهُۥ خَمْرًۭا ۖ وَأَمَّا ٱلْءَاخَرُ فَيُصْلَبُ فَتَأْكُلُ ٱلطَّيْرُ مِن رَّأْسِهِۦ ۚ قُضِىَ ٱلْأَمْرُ ٱلَّذِى فِيهِ تَسْتَفْتِيَانِ', 'يصىحبى السجن أما أحدكما فيسقى ربه خمرا  وأما الءاخر فيصلب فتأكل الطير من رأسه  قضى الأمر الذى فيه تستفتيان', NULL, 240, 'local:hafs-text.json'),
  ('hafs-12-42', 'hafs', 12, 42, 'وَقَالَ لِلَّذِى ظَنَّ أَنَّهُۥ نَاجٍۢ مِّنْهُمَا ٱذْكُرْنِى عِندَ رَبِّكَ فَأَنسَىٰهُ ٱلشَّيْطَٰنُ ذِكْرَ رَبِّهِۦ فَلَبِثَ فِى ٱلسِّجْنِ بِضْعَ سِنِينَ', 'وقال للذى ظن أنه ناج منهما اذكرنى عند ربك فأنسىه الشيطن ذكر ربه فلبث فى السجن بضع سنين', NULL, 240, 'local:hafs-text.json'),
  ('hafs-12-43', 'hafs', 12, 43, 'وَقَالَ ٱلْمَلِكُ إِنِّىٓ أَرَىٰ سَبْعَ بَقَرَٰتٍۢ سِمَانٍۢ يَأْكُلُهُنَّ سَبْعٌ عِجَافٌۭ وَسَبْعَ سُنۢبُلَٰتٍ خُضْرٍۢ وَأُخَرَ يَابِسَٰتٍۢ ۖ يَٰٓأَيُّهَا ٱلْمَلَأُ أَفْتُونِى فِى رُءْيَٰىَ إِن كُنتُمْ لِلرُّءْيَا تَعْبُرُونَ', 'وقال الملك إنى أرى سبع بقرت سمان يأكلهن سبع عجاف وسبع سنبلت خضر وأخر يابست  يأيها الملأ أفتونى فى رءيى إن كنتم للرءيا تعبرون', NULL, 240, 'local:hafs-text.json'),
  ('hafs-12-44', 'hafs', 12, 44, 'قَالُوٓا۟ أَضْغَٰثُ أَحْلَٰمٍۢ ۖ وَمَا نَحْنُ بِتَأْوِيلِ ٱلْأَحْلَٰمِ بِعَٰلِمِينَ', 'قالوا أضغث أحلم  وما نحن بتأويل الأحلم بعلمين', NULL, 241, 'local:hafs-text.json'),
  ('hafs-12-45', 'hafs', 12, 45, 'وَقَالَ ٱلَّذِى نَجَا مِنْهُمَا وَٱدَّكَرَ بَعْدَ أُمَّةٍ أَنَا۠ أُنَبِّئُكُم بِتَأْوِيلِهِۦ فَأَرْسِلُونِ', 'وقال الذى نجا منهما وادكر بعد أمة أنا أنبئكم بتأويله فأرسلون', NULL, 241, 'local:hafs-text.json'),
  ('hafs-12-46', 'hafs', 12, 46, 'يُوسُفُ أَيُّهَا ٱلصِّدِّيقُ أَفْتِنَا فِى سَبْعِ بَقَرَٰتٍۢ سِمَانٍۢ يَأْكُلُهُنَّ سَبْعٌ عِجَافٌۭ وَسَبْعِ سُنۢبُلَٰتٍ خُضْرٍۢ وَأُخَرَ يَابِسَٰتٍۢ لَّعَلِّىٓ أَرْجِعُ إِلَى ٱلنَّاسِ لَعَلَّهُمْ يَعْلَمُونَ', 'يوسف أيها الصديق أفتنا فى سبع بقرت سمان يأكلهن سبع عجاف وسبع سنبلت خضر وأخر يابست لعلى أرجع إلى الناس لعلهم يعلمون', NULL, 241, 'local:hafs-text.json'),
  ('hafs-12-47', 'hafs', 12, 47, 'قَالَ تَزْرَعُونَ سَبْعَ سِنِينَ دَأَبًۭا فَمَا حَصَدتُّمْ فَذَرُوهُ فِى سُنۢبُلِهِۦٓ إِلَّا قَلِيلًۭا مِّمَّا تَأْكُلُونَ', 'قال تزرعون سبع سنين دأبا فما حصدتم فذروه فى سنبله إلا قليلا مما تأكلون', NULL, 241, 'local:hafs-text.json'),
  ('hafs-12-48', 'hafs', 12, 48, 'ثُمَّ يَأْتِى مِنۢ بَعْدِ ذَٰلِكَ سَبْعٌۭ شِدَادٌۭ يَأْكُلْنَ مَا قَدَّمْتُمْ لَهُنَّ إِلَّا قَلِيلًۭا مِّمَّا تُحْصِنُونَ', 'ثم يأتى من بعد ذلك سبع شداد يأكلن ما قدمتم لهن إلا قليلا مما تحصنون', NULL, 241, 'local:hafs-text.json'),
  ('hafs-12-49', 'hafs', 12, 49, 'ثُمَّ يَأْتِى مِنۢ بَعْدِ ذَٰلِكَ عَامٌۭ فِيهِ يُغَاثُ ٱلنَّاسُ وَفِيهِ يَعْصِرُونَ', 'ثم يأتى من بعد ذلك عام فيه يغاث الناس وفيه يعصرون', NULL, 241, 'local:hafs-text.json'),
  ('hafs-12-50', 'hafs', 12, 50, 'وَقَالَ ٱلْمَلِكُ ٱئْتُونِى بِهِۦ ۖ فَلَمَّا جَآءَهُ ٱلرَّسُولُ قَالَ ٱرْجِعْ إِلَىٰ رَبِّكَ فَسْـَٔلْهُ مَا بَالُ ٱلنِّسْوَةِ ٱلَّٰتِى قَطَّعْنَ أَيْدِيَهُنَّ ۚ إِنَّ رَبِّى بِكَيْدِهِنَّ عَلِيمٌۭ', 'وقال الملك ائتونى به  فلما جاءه الرسول قال ارجع إلى ربك فسله ما بال النسوة التى قطعن أيديهن  إن ربى بكيدهن عليم', NULL, 241, 'local:hafs-text.json'),
  ('hafs-12-51', 'hafs', 12, 51, 'قَالَ مَا خَطْبُكُنَّ إِذْ رَٰوَدتُّنَّ يُوسُفَ عَن نَّفْسِهِۦ ۚ قُلْنَ حَٰشَ لِلَّهِ مَا عَلِمْنَا عَلَيْهِ مِن سُوٓءٍۢ ۚ قَالَتِ ٱمْرَأَتُ ٱلْعَزِيزِ ٱلْـَٰٔنَ حَصْحَصَ ٱلْحَقُّ أَنَا۠ رَٰوَدتُّهُۥ عَن نَّفْسِهِۦ وَإِنَّهُۥ لَمِنَ ٱلصَّٰدِقِينَ', 'قال ما خطبكن إذ رودتن يوسف عن نفسه  قلن حش لله ما علمنا عليه من سوء  قالت امرأت العزيز الن حصحص الحق أنا رودته عن نفسه وإنه لمن الصدقين', NULL, 241, 'local:hafs-text.json'),
  ('hafs-12-52', 'hafs', 12, 52, 'ذَٰلِكَ لِيَعْلَمَ أَنِّى لَمْ أَخُنْهُ بِٱلْغَيْبِ وَأَنَّ ٱللَّهَ لَا يَهْدِى كَيْدَ ٱلْخَآئِنِينَ', 'ذلك ليعلم أنى لم أخنه بالغيب وأن الله لا يهدى كيد الخائنين', NULL, 241, 'local:hafs-text.json'),
  ('hafs-12-53', 'hafs', 12, 53, '۞ وَمَآ أُبَرِّئُ نَفْسِىٓ ۚ إِنَّ ٱلنَّفْسَ لَأَمَّارَةٌۢ بِٱلسُّوٓءِ إِلَّا مَا رَحِمَ رَبِّىٓ ۚ إِنَّ رَبِّى غَفُورٌۭ رَّحِيمٌۭ', 'وما أبرئ نفسى  إن النفس لأمارة بالسوء إلا ما رحم ربى  إن ربى غفور رحيم', NULL, 242, 'local:hafs-text.json'),
  ('hafs-12-54', 'hafs', 12, 54, 'وَقَالَ ٱلْمَلِكُ ٱئْتُونِى بِهِۦٓ أَسْتَخْلِصْهُ لِنَفْسِى ۖ فَلَمَّا كَلَّمَهُۥ قَالَ إِنَّكَ ٱلْيَوْمَ لَدَيْنَا مَكِينٌ أَمِينٌۭ', 'وقال الملك ائتونى به أستخلصه لنفسى  فلما كلمه قال إنك اليوم لدينا مكين أمين', NULL, 242, 'local:hafs-text.json'),
  ('hafs-12-55', 'hafs', 12, 55, 'قَالَ ٱجْعَلْنِى عَلَىٰ خَزَآئِنِ ٱلْأَرْضِ ۖ إِنِّى حَفِيظٌ عَلِيمٌۭ', 'قال اجعلنى على خزائن الأرض  إنى حفيظ عليم', NULL, 242, 'local:hafs-text.json'),
  ('hafs-12-56', 'hafs', 12, 56, 'وَكَذَٰلِكَ مَكَّنَّا لِيُوسُفَ فِى ٱلْأَرْضِ يَتَبَوَّأُ مِنْهَا حَيْثُ يَشَآءُ ۚ نُصِيبُ بِرَحْمَتِنَا مَن نَّشَآءُ ۖ وَلَا نُضِيعُ أَجْرَ ٱلْمُحْسِنِينَ', 'وكذلك مكنا ليوسف فى الأرض يتبوأ منها حيث يشاء  نصيب برحمتنا من نشاء  ولا نضيع أجر المحسنين', NULL, 242, 'local:hafs-text.json'),
  ('hafs-12-57', 'hafs', 12, 57, 'وَلَأَجْرُ ٱلْءَاخِرَةِ خَيْرٌۭ لِّلَّذِينَ ءَامَنُوا۟ وَكَانُوا۟ يَتَّقُونَ', 'ولأجر الءاخرة خير للذين ءامنوا وكانوا يتقون', NULL, 242, 'local:hafs-text.json'),
  ('hafs-12-58', 'hafs', 12, 58, 'وَجَآءَ إِخْوَةُ يُوسُفَ فَدَخَلُوا۟ عَلَيْهِ فَعَرَفَهُمْ وَهُمْ لَهُۥ مُنكِرُونَ', 'وجاء إخوة يوسف فدخلوا عليه فعرفهم وهم له منكرون', NULL, 242, 'local:hafs-text.json'),
  ('hafs-12-59', 'hafs', 12, 59, 'وَلَمَّا جَهَّزَهُم بِجَهَازِهِمْ قَالَ ٱئْتُونِى بِأَخٍۢ لَّكُم مِّنْ أَبِيكُمْ ۚ أَلَا تَرَوْنَ أَنِّىٓ أُوفِى ٱلْكَيْلَ وَأَنَا۠ خَيْرُ ٱلْمُنزِلِينَ', 'ولما جهزهم بجهازهم قال ائتونى بأخ لكم من أبيكم  ألا ترون أنى أوفى الكيل وأنا خير المنزلين', NULL, 242, 'local:hafs-text.json'),
  ('hafs-12-60', 'hafs', 12, 60, 'فَإِن لَّمْ تَأْتُونِى بِهِۦ فَلَا كَيْلَ لَكُمْ عِندِى وَلَا تَقْرَبُونِ', 'فإن لم تأتونى به فلا كيل لكم عندى ولا تقربون', NULL, 242, 'local:hafs-text.json'),
  ('hafs-12-61', 'hafs', 12, 61, 'قَالُوا۟ سَنُرَٰوِدُ عَنْهُ أَبَاهُ وَإِنَّا لَفَٰعِلُونَ', 'قالوا سنرود عنه أباه وإنا لفعلون', NULL, 242, 'local:hafs-text.json'),
  ('hafs-12-62', 'hafs', 12, 62, 'وَقَالَ لِفِتْيَٰنِهِ ٱجْعَلُوا۟ بِضَٰعَتَهُمْ فِى رِحَالِهِمْ لَعَلَّهُمْ يَعْرِفُونَهَآ إِذَا ٱنقَلَبُوٓا۟ إِلَىٰٓ أَهْلِهِمْ لَعَلَّهُمْ يَرْجِعُونَ', 'وقال لفتينه اجعلوا بضعتهم فى رحالهم لعلهم يعرفونها إذا انقلبوا إلى أهلهم لعلهم يرجعون', NULL, 242, 'local:hafs-text.json'),
  ('hafs-12-63', 'hafs', 12, 63, 'فَلَمَّا رَجَعُوٓا۟ إِلَىٰٓ أَبِيهِمْ قَالُوا۟ يَٰٓأَبَانَا مُنِعَ مِنَّا ٱلْكَيْلُ فَأَرْسِلْ مَعَنَآ أَخَانَا نَكْتَلْ وَإِنَّا لَهُۥ لَحَٰفِظُونَ', 'فلما رجعوا إلى أبيهم قالوا يأبانا منع منا الكيل فأرسل معنا أخانا نكتل وإنا له لحفظون', NULL, 242, 'local:hafs-text.json'),
  ('hafs-12-64', 'hafs', 12, 64, 'قَالَ هَلْ ءَامَنُكُمْ عَلَيْهِ إِلَّا كَمَآ أَمِنتُكُمْ عَلَىٰٓ أَخِيهِ مِن قَبْلُ ۖ فَٱللَّهُ خَيْرٌ حَٰفِظًۭا ۖ وَهُوَ أَرْحَمُ ٱلرَّٰحِمِينَ', 'قال هل ءامنكم عليه إلا كما أمنتكم على أخيه من قبل  فالله خير حفظا  وهو أرحم الرحمين', NULL, 243, 'local:hafs-text.json'),
  ('hafs-12-65', 'hafs', 12, 65, 'وَلَمَّا فَتَحُوا۟ مَتَٰعَهُمْ وَجَدُوا۟ بِضَٰعَتَهُمْ رُدَّتْ إِلَيْهِمْ ۖ قَالُوا۟ يَٰٓأَبَانَا مَا نَبْغِى ۖ هَٰذِهِۦ بِضَٰعَتُنَا رُدَّتْ إِلَيْنَا ۖ وَنَمِيرُ أَهْلَنَا وَنَحْفَظُ أَخَانَا وَنَزْدَادُ كَيْلَ بَعِيرٍۢ ۖ ذَٰلِكَ كَيْلٌۭ يَسِيرٌۭ', 'ولما فتحوا متعهم وجدوا بضعتهم ردت إليهم  قالوا يأبانا ما نبغى  هذه بضعتنا ردت إلينا  ونمير أهلنا ونحفظ أخانا ونزداد كيل بعير  ذلك كيل يسير', NULL, 243, 'local:hafs-text.json'),
  ('hafs-12-66', 'hafs', 12, 66, 'قَالَ لَنْ أُرْسِلَهُۥ مَعَكُمْ حَتَّىٰ تُؤْتُونِ مَوْثِقًۭا مِّنَ ٱللَّهِ لَتَأْتُنَّنِى بِهِۦٓ إِلَّآ أَن يُحَاطَ بِكُمْ ۖ فَلَمَّآ ءَاتَوْهُ مَوْثِقَهُمْ قَالَ ٱللَّهُ عَلَىٰ مَا نَقُولُ وَكِيلٌۭ', 'قال لن أرسله معكم حتى تؤتون موثقا من الله لتأتننى به إلا أن يحاط بكم  فلما ءاتوه موثقهم قال الله على ما نقول وكيل', NULL, 243, 'local:hafs-text.json'),
  ('hafs-12-67', 'hafs', 12, 67, 'وَقَالَ يَٰبَنِىَّ لَا تَدْخُلُوا۟ مِنۢ بَابٍۢ وَٰحِدٍۢ وَٱدْخُلُوا۟ مِنْ أَبْوَٰبٍۢ مُّتَفَرِّقَةٍۢ ۖ وَمَآ أُغْنِى عَنكُم مِّنَ ٱللَّهِ مِن شَىْءٍ ۖ إِنِ ٱلْحُكْمُ إِلَّا لِلَّهِ ۖ عَلَيْهِ تَوَكَّلْتُ ۖ وَعَلَيْهِ فَلْيَتَوَكَّلِ ٱلْمُتَوَكِّلُونَ', 'وقال يبنى لا تدخلوا من باب وحد وادخلوا من أبوب متفرقة  وما أغنى عنكم من الله من شىء  إن الحكم إلا لله  عليه توكلت  وعليه فليتوكل المتوكلون', NULL, 243, 'local:hafs-text.json'),
  ('hafs-12-68', 'hafs', 12, 68, 'وَلَمَّا دَخَلُوا۟ مِنْ حَيْثُ أَمَرَهُمْ أَبُوهُم مَّا كَانَ يُغْنِى عَنْهُم مِّنَ ٱللَّهِ مِن شَىْءٍ إِلَّا حَاجَةًۭ فِى نَفْسِ يَعْقُوبَ قَضَىٰهَا ۚ وَإِنَّهُۥ لَذُو عِلْمٍۢ لِّمَا عَلَّمْنَٰهُ وَلَٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يَعْلَمُونَ', 'ولما دخلوا من حيث أمرهم أبوهم ما كان يغنى عنهم من الله من شىء إلا حاجة فى نفس يعقوب قضىها  وإنه لذو علم لما علمنه ولكن أكثر الناس لا يعلمون', NULL, 243, 'local:hafs-text.json'),
  ('hafs-12-69', 'hafs', 12, 69, 'وَلَمَّا دَخَلُوا۟ عَلَىٰ يُوسُفَ ءَاوَىٰٓ إِلَيْهِ أَخَاهُ ۖ قَالَ إِنِّىٓ أَنَا۠ أَخُوكَ فَلَا تَبْتَئِسْ بِمَا كَانُوا۟ يَعْمَلُونَ', 'ولما دخلوا على يوسف ءاوى إليه أخاه  قال إنى أنا أخوك فلا تبتئس بما كانوا يعملون', NULL, 243, 'local:hafs-text.json'),
  ('hafs-12-70', 'hafs', 12, 70, 'فَلَمَّا جَهَّزَهُم بِجَهَازِهِمْ جَعَلَ ٱلسِّقَايَةَ فِى رَحْلِ أَخِيهِ ثُمَّ أَذَّنَ مُؤَذِّنٌ أَيَّتُهَا ٱلْعِيرُ إِنَّكُمْ لَسَٰرِقُونَ', 'فلما جهزهم بجهازهم جعل السقاية فى رحل أخيه ثم أذن مؤذن أيتها العير إنكم لسرقون', NULL, 244, 'local:hafs-text.json'),
  ('hafs-12-71', 'hafs', 12, 71, 'قَالُوا۟ وَأَقْبَلُوا۟ عَلَيْهِم مَّاذَا تَفْقِدُونَ', 'قالوا وأقبلوا عليهم ماذا تفقدون', NULL, 244, 'local:hafs-text.json'),
  ('hafs-12-72', 'hafs', 12, 72, 'قَالُوا۟ نَفْقِدُ صُوَاعَ ٱلْمَلِكِ وَلِمَن جَآءَ بِهِۦ حِمْلُ بَعِيرٍۢ وَأَنَا۠ بِهِۦ زَعِيمٌۭ', 'قالوا نفقد صواع الملك ولمن جاء به حمل بعير وأنا به زعيم', NULL, 244, 'local:hafs-text.json'),
  ('hafs-12-73', 'hafs', 12, 73, 'قَالُوا۟ تَٱللَّهِ لَقَدْ عَلِمْتُم مَّا جِئْنَا لِنُفْسِدَ فِى ٱلْأَرْضِ وَمَا كُنَّا سَٰرِقِينَ', 'قالوا تالله لقد علمتم ما جئنا لنفسد فى الأرض وما كنا سرقين', NULL, 244, 'local:hafs-text.json'),
  ('hafs-12-74', 'hafs', 12, 74, 'قَالُوا۟ فَمَا جَزَٰٓؤُهُۥٓ إِن كُنتُمْ كَٰذِبِينَ', 'قالوا فما جزؤه إن كنتم كذبين', NULL, 244, 'local:hafs-text.json'),
  ('hafs-12-75', 'hafs', 12, 75, 'قَالُوا۟ جَزَٰٓؤُهُۥ مَن وُجِدَ فِى رَحْلِهِۦ فَهُوَ جَزَٰٓؤُهُۥ ۚ كَذَٰلِكَ نَجْزِى ٱلظَّٰلِمِينَ', 'قالوا جزؤه من وجد فى رحله فهو جزؤه  كذلك نجزى الظلمين', NULL, 244, 'local:hafs-text.json'),
  ('hafs-12-76', 'hafs', 12, 76, 'فَبَدَأَ بِأَوْعِيَتِهِمْ قَبْلَ وِعَآءِ أَخِيهِ ثُمَّ ٱسْتَخْرَجَهَا مِن وِعَآءِ أَخِيهِ ۚ كَذَٰلِكَ كِدْنَا لِيُوسُفَ ۖ مَا كَانَ لِيَأْخُذَ أَخَاهُ فِى دِينِ ٱلْمَلِكِ إِلَّآ أَن يَشَآءَ ٱللَّهُ ۚ نَرْفَعُ دَرَجَٰتٍۢ مَّن نَّشَآءُ ۗ وَفَوْقَ كُلِّ ذِى عِلْمٍ عَلِيمٌۭ', 'فبدأ بأوعيتهم قبل وعاء أخيه ثم استخرجها من وعاء أخيه  كذلك كدنا ليوسف  ما كان ليأخذ أخاه فى دين الملك إلا أن يشاء الله  نرفع درجت من نشاء  وفوق كل ذى علم عليم', NULL, 244, 'local:hafs-text.json'),
  ('hafs-12-77', 'hafs', 12, 77, '۞ قَالُوٓا۟ إِن يَسْرِقْ فَقَدْ سَرَقَ أَخٌۭ لَّهُۥ مِن قَبْلُ ۚ فَأَسَرَّهَا يُوسُفُ فِى نَفْسِهِۦ وَلَمْ يُبْدِهَا لَهُمْ ۚ قَالَ أَنتُمْ شَرٌّۭ مَّكَانًۭا ۖ وَٱللَّهُ أَعْلَمُ بِمَا تَصِفُونَ', 'قالوا إن يسرق فقد سرق أخ له من قبل  فأسرها يوسف فى نفسه ولم يبدها لهم  قال أنتم شر مكانا  والله أعلم بما تصفون', NULL, 244, 'local:hafs-text.json'),
  ('hafs-12-78', 'hafs', 12, 78, 'قَالُوا۟ يَٰٓأَيُّهَا ٱلْعَزِيزُ إِنَّ لَهُۥٓ أَبًۭا شَيْخًۭا كَبِيرًۭا فَخُذْ أَحَدَنَا مَكَانَهُۥٓ ۖ إِنَّا نَرَىٰكَ مِنَ ٱلْمُحْسِنِينَ', 'قالوا يأيها العزيز إن له أبا شيخا كبيرا فخذ أحدنا مكانه  إنا نرىك من المحسنين', NULL, 244, 'local:hafs-text.json'),
  ('hafs-12-79', 'hafs', 12, 79, 'قَالَ مَعَاذَ ٱللَّهِ أَن نَّأْخُذَ إِلَّا مَن وَجَدْنَا مَتَٰعَنَا عِندَهُۥٓ إِنَّآ إِذًۭا لَّظَٰلِمُونَ', 'قال معاذ الله أن نأخذ إلا من وجدنا متعنا عنده إنا إذا لظلمون', NULL, 245, 'local:hafs-text.json'),
  ('hafs-12-80', 'hafs', 12, 80, 'فَلَمَّا ٱسْتَيْـَٔسُوا۟ مِنْهُ خَلَصُوا۟ نَجِيًّۭا ۖ قَالَ كَبِيرُهُمْ أَلَمْ تَعْلَمُوٓا۟ أَنَّ أَبَاكُمْ قَدْ أَخَذَ عَلَيْكُم مَّوْثِقًۭا مِّنَ ٱللَّهِ وَمِن قَبْلُ مَا فَرَّطتُمْ فِى يُوسُفَ ۖ فَلَنْ أَبْرَحَ ٱلْأَرْضَ حَتَّىٰ يَأْذَنَ لِىٓ أَبِىٓ أَوْ يَحْكُمَ ٱللَّهُ لِى ۖ وَهُوَ خَيْرُ ٱلْحَٰكِمِينَ', 'فلما استيسوا منه خلصوا نجيا  قال كبيرهم ألم تعلموا أن أباكم قد أخذ عليكم موثقا من الله ومن قبل ما فرطتم فى يوسف  فلن أبرح الأرض حتى يأذن لى أبى أو يحكم الله لى  وهو خير الحكمين', NULL, 245, 'local:hafs-text.json'),
  ('hafs-12-81', 'hafs', 12, 81, 'ٱرْجِعُوٓا۟ إِلَىٰٓ أَبِيكُمْ فَقُولُوا۟ يَٰٓأَبَانَآ إِنَّ ٱبْنَكَ سَرَقَ وَمَا شَهِدْنَآ إِلَّا بِمَا عَلِمْنَا وَمَا كُنَّا لِلْغَيْبِ حَٰفِظِينَ', 'ارجعوا إلى أبيكم فقولوا يأبانا إن ابنك سرق وما شهدنا إلا بما علمنا وما كنا للغيب حفظين', NULL, 245, 'local:hafs-text.json'),
  ('hafs-12-82', 'hafs', 12, 82, 'وَسْـَٔلِ ٱلْقَرْيَةَ ٱلَّتِى كُنَّا فِيهَا وَٱلْعِيرَ ٱلَّتِىٓ أَقْبَلْنَا فِيهَا ۖ وَإِنَّا لَصَٰدِقُونَ', 'وسل القرية التى كنا فيها والعير التى أقبلنا فيها  وإنا لصدقون', NULL, 245, 'local:hafs-text.json'),
  ('hafs-12-83', 'hafs', 12, 83, 'قَالَ بَلْ سَوَّلَتْ لَكُمْ أَنفُسُكُمْ أَمْرًۭا ۖ فَصَبْرٌۭ جَمِيلٌ ۖ عَسَى ٱللَّهُ أَن يَأْتِيَنِى بِهِمْ جَمِيعًا ۚ إِنَّهُۥ هُوَ ٱلْعَلِيمُ ٱلْحَكِيمُ', 'قال بل سولت لكم أنفسكم أمرا  فصبر جميل  عسى الله أن يأتينى بهم جميعا  إنه هو العليم الحكيم', NULL, 245, 'local:hafs-text.json'),
  ('hafs-12-84', 'hafs', 12, 84, 'وَتَوَلَّىٰ عَنْهُمْ وَقَالَ يَٰٓأَسَفَىٰ عَلَىٰ يُوسُفَ وَٱبْيَضَّتْ عَيْنَاهُ مِنَ ٱلْحُزْنِ فَهُوَ كَظِيمٌۭ', 'وتولى عنهم وقال يأسفى على يوسف وابيضت عيناه من الحزن فهو كظيم', NULL, 245, 'local:hafs-text.json'),
  ('hafs-12-85', 'hafs', 12, 85, 'قَالُوا۟ تَٱللَّهِ تَفْتَؤُا۟ تَذْكُرُ يُوسُفَ حَتَّىٰ تَكُونَ حَرَضًا أَوْ تَكُونَ مِنَ ٱلْهَٰلِكِينَ', 'قالوا تالله تفتؤا تذكر يوسف حتى تكون حرضا أو تكون من الهلكين', NULL, 245, 'local:hafs-text.json'),
  ('hafs-12-86', 'hafs', 12, 86, 'قَالَ إِنَّمَآ أَشْكُوا۟ بَثِّى وَحُزْنِىٓ إِلَى ٱللَّهِ وَأَعْلَمُ مِنَ ٱللَّهِ مَا لَا تَعْلَمُونَ', 'قال إنما أشكوا بثى وحزنى إلى الله وأعلم من الله ما لا تعلمون', NULL, 245, 'local:hafs-text.json'),
  ('hafs-12-87', 'hafs', 12, 87, 'يَٰبَنِىَّ ٱذْهَبُوا۟ فَتَحَسَّسُوا۟ مِن يُوسُفَ وَأَخِيهِ وَلَا تَا۟يْـَٔسُوا۟ مِن رَّوْحِ ٱللَّهِ ۖ إِنَّهُۥ لَا يَا۟يْـَٔسُ مِن رَّوْحِ ٱللَّهِ إِلَّا ٱلْقَوْمُ ٱلْكَٰفِرُونَ', 'يبنى اذهبوا فتحسسوا من يوسف وأخيه ولا تايسوا من روح الله  إنه لا يايس من روح الله إلا القوم الكفرون', NULL, 246, 'local:hafs-text.json'),
  ('hafs-12-88', 'hafs', 12, 88, 'فَلَمَّا دَخَلُوا۟ عَلَيْهِ قَالُوا۟ يَٰٓأَيُّهَا ٱلْعَزِيزُ مَسَّنَا وَأَهْلَنَا ٱلضُّرُّ وَجِئْنَا بِبِضَٰعَةٍۢ مُّزْجَىٰةٍۢ فَأَوْفِ لَنَا ٱلْكَيْلَ وَتَصَدَّقْ عَلَيْنَآ ۖ إِنَّ ٱللَّهَ يَجْزِى ٱلْمُتَصَدِّقِينَ', 'فلما دخلوا عليه قالوا يأيها العزيز مسنا وأهلنا الضر وجئنا ببضعة مزجىة فأوف لنا الكيل وتصدق علينا  إن الله يجزى المتصدقين', NULL, 246, 'local:hafs-text.json'),
  ('hafs-12-89', 'hafs', 12, 89, 'قَالَ هَلْ عَلِمْتُم مَّا فَعَلْتُم بِيُوسُفَ وَأَخِيهِ إِذْ أَنتُمْ جَٰهِلُونَ', 'قال هل علمتم ما فعلتم بيوسف وأخيه إذ أنتم جهلون', NULL, 246, 'local:hafs-text.json'),
  ('hafs-12-90', 'hafs', 12, 90, 'قَالُوٓا۟ أَءِنَّكَ لَأَنتَ يُوسُفُ ۖ قَالَ أَنَا۠ يُوسُفُ وَهَٰذَآ أَخِى ۖ قَدْ مَنَّ ٱللَّهُ عَلَيْنَآ ۖ إِنَّهُۥ مَن يَتَّقِ وَيَصْبِرْ فَإِنَّ ٱللَّهَ لَا يُضِيعُ أَجْرَ ٱلْمُحْسِنِينَ', 'قالوا أءنك لأنت يوسف  قال أنا يوسف وهذا أخى  قد من الله علينا  إنه من يتق ويصبر فإن الله لا يضيع أجر المحسنين', NULL, 246, 'local:hafs-text.json'),
  ('hafs-12-91', 'hafs', 12, 91, 'قَالُوا۟ تَٱللَّهِ لَقَدْ ءَاثَرَكَ ٱللَّهُ عَلَيْنَا وَإِن كُنَّا لَخَٰطِـِٔينَ', 'قالوا تالله لقد ءاثرك الله علينا وإن كنا لخطين', NULL, 246, 'local:hafs-text.json'),
  ('hafs-12-92', 'hafs', 12, 92, 'قَالَ لَا تَثْرِيبَ عَلَيْكُمُ ٱلْيَوْمَ ۖ يَغْفِرُ ٱللَّهُ لَكُمْ ۖ وَهُوَ أَرْحَمُ ٱلرَّٰحِمِينَ', 'قال لا تثريب عليكم اليوم  يغفر الله لكم  وهو أرحم الرحمين', NULL, 246, 'local:hafs-text.json'),
  ('hafs-12-93', 'hafs', 12, 93, 'ٱذْهَبُوا۟ بِقَمِيصِى هَٰذَا فَأَلْقُوهُ عَلَىٰ وَجْهِ أَبِى يَأْتِ بَصِيرًۭا وَأْتُونِى بِأَهْلِكُمْ أَجْمَعِينَ', 'اذهبوا بقميصى هذا فألقوه على وجه أبى يأت بصيرا وأتونى بأهلكم أجمعين', NULL, 246, 'local:hafs-text.json'),
  ('hafs-12-94', 'hafs', 12, 94, 'وَلَمَّا فَصَلَتِ ٱلْعِيرُ قَالَ أَبُوهُمْ إِنِّى لَأَجِدُ رِيحَ يُوسُفَ ۖ لَوْلَآ أَن تُفَنِّدُونِ', 'ولما فصلت العير قال أبوهم إنى لأجد ريح يوسف  لولا أن تفندون', NULL, 246, 'local:hafs-text.json'),
  ('hafs-12-95', 'hafs', 12, 95, 'قَالُوا۟ تَٱللَّهِ إِنَّكَ لَفِى ضَلَٰلِكَ ٱلْقَدِيمِ', 'قالوا تالله إنك لفى ضللك القديم', NULL, 246, 'local:hafs-text.json'),
  ('hafs-12-96', 'hafs', 12, 96, 'فَلَمَّآ أَن جَآءَ ٱلْبَشِيرُ أَلْقَىٰهُ عَلَىٰ وَجْهِهِۦ فَٱرْتَدَّ بَصِيرًۭا ۖ قَالَ أَلَمْ أَقُل لَّكُمْ إِنِّىٓ أَعْلَمُ مِنَ ٱللَّهِ مَا لَا تَعْلَمُونَ', 'فلما أن جاء البشير ألقىه على وجهه فارتد بصيرا  قال ألم أقل لكم إنى أعلم من الله ما لا تعلمون', NULL, 247, 'local:hafs-text.json'),
  ('hafs-12-97', 'hafs', 12, 97, 'قَالُوا۟ يَٰٓأَبَانَا ٱسْتَغْفِرْ لَنَا ذُنُوبَنَآ إِنَّا كُنَّا خَٰطِـِٔينَ', 'قالوا يأبانا استغفر لنا ذنوبنا إنا كنا خطين', NULL, 247, 'local:hafs-text.json'),
  ('hafs-12-98', 'hafs', 12, 98, 'قَالَ سَوْفَ أَسْتَغْفِرُ لَكُمْ رَبِّىٓ ۖ إِنَّهُۥ هُوَ ٱلْغَفُورُ ٱلرَّحِيمُ', 'قال سوف أستغفر لكم ربى  إنه هو الغفور الرحيم', NULL, 247, 'local:hafs-text.json'),
  ('hafs-12-99', 'hafs', 12, 99, 'فَلَمَّا دَخَلُوا۟ عَلَىٰ يُوسُفَ ءَاوَىٰٓ إِلَيْهِ أَبَوَيْهِ وَقَالَ ٱدْخُلُوا۟ مِصْرَ إِن شَآءَ ٱللَّهُ ءَامِنِينَ', 'فلما دخلوا على يوسف ءاوى إليه أبويه وقال ادخلوا مصر إن شاء الله ءامنين', NULL, 247, 'local:hafs-text.json'),
  ('hafs-12-100', 'hafs', 12, 100, 'وَرَفَعَ أَبَوَيْهِ عَلَى ٱلْعَرْشِ وَخَرُّوا۟ لَهُۥ سُجَّدًۭا ۖ وَقَالَ يَٰٓأَبَتِ هَٰذَا تَأْوِيلُ رُءْيَٰىَ مِن قَبْلُ قَدْ جَعَلَهَا رَبِّى حَقًّۭا ۖ وَقَدْ أَحْسَنَ بِىٓ إِذْ أَخْرَجَنِى مِنَ ٱلسِّجْنِ وَجَآءَ بِكُم مِّنَ ٱلْبَدْوِ مِنۢ بَعْدِ أَن نَّزَغَ ٱلشَّيْطَٰنُ بَيْنِى وَبَيْنَ إِخْوَتِىٓ ۚ إِنَّ رَبِّى لَطِيفٌۭ لِّمَا يَشَآءُ ۚ إِنَّهُۥ هُوَ ٱلْعَلِيمُ ٱلْحَكِيمُ', 'ورفع أبويه على العرش وخروا له سجدا  وقال يأبت هذا تأويل رءيى من قبل قد جعلها ربى حقا  وقد أحسن بى إذ أخرجنى من السجن وجاء بكم من البدو من بعد أن نزغ الشيطن بينى وبين إخوتى  إن ربى لطيف لما يشاء  إنه هو العليم الحكيم', NULL, 247, 'local:hafs-text.json'),
  ('hafs-12-101', 'hafs', 12, 101, '۞ رَبِّ قَدْ ءَاتَيْتَنِى مِنَ ٱلْمُلْكِ وَعَلَّمْتَنِى مِن تَأْوِيلِ ٱلْأَحَادِيثِ ۚ فَاطِرَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ أَنتَ وَلِىِّۦ فِى ٱلدُّنْيَا وَٱلْءَاخِرَةِ ۖ تَوَفَّنِى مُسْلِمًۭا وَأَلْحِقْنِى بِٱلصَّٰلِحِينَ', 'رب قد ءاتيتنى من الملك وعلمتنى من تأويل الأحاديث  فاطر السموت والأرض أنت ولى فى الدنيا والءاخرة  توفنى مسلما وألحقنى بالصلحين', NULL, 247, 'local:hafs-text.json'),
  ('hafs-12-102', 'hafs', 12, 102, 'ذَٰلِكَ مِنْ أَنۢبَآءِ ٱلْغَيْبِ نُوحِيهِ إِلَيْكَ ۖ وَمَا كُنتَ لَدَيْهِمْ إِذْ أَجْمَعُوٓا۟ أَمْرَهُمْ وَهُمْ يَمْكُرُونَ', 'ذلك من أنباء الغيب نوحيه إليك  وما كنت لديهم إذ أجمعوا أمرهم وهم يمكرون', NULL, 247, 'local:hafs-text.json'),
  ('hafs-12-103', 'hafs', 12, 103, 'وَمَآ أَكْثَرُ ٱلنَّاسِ وَلَوْ حَرَصْتَ بِمُؤْمِنِينَ', 'وما أكثر الناس ولو حرصت بمؤمنين', NULL, 247, 'local:hafs-text.json'),
  ('hafs-12-104', 'hafs', 12, 104, 'وَمَا تَسْـَٔلُهُمْ عَلَيْهِ مِنْ أَجْرٍ ۚ إِنْ هُوَ إِلَّا ذِكْرٌۭ لِّلْعَٰلَمِينَ', 'وما تسلهم عليه من أجر  إن هو إلا ذكر للعلمين', NULL, 248, 'local:hafs-text.json'),
  ('hafs-12-105', 'hafs', 12, 105, 'وَكَأَيِّن مِّنْ ءَايَةٍۢ فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ يَمُرُّونَ عَلَيْهَا وَهُمْ عَنْهَا مُعْرِضُونَ', 'وكأين من ءاية فى السموت والأرض يمرون عليها وهم عنها معرضون', NULL, 248, 'local:hafs-text.json'),
  ('hafs-12-106', 'hafs', 12, 106, 'وَمَا يُؤْمِنُ أَكْثَرُهُم بِٱللَّهِ إِلَّا وَهُم مُّشْرِكُونَ', 'وما يؤمن أكثرهم بالله إلا وهم مشركون', NULL, 248, 'local:hafs-text.json'),
  ('hafs-12-107', 'hafs', 12, 107, 'أَفَأَمِنُوٓا۟ أَن تَأْتِيَهُمْ غَٰشِيَةٌۭ مِّنْ عَذَابِ ٱللَّهِ أَوْ تَأْتِيَهُمُ ٱلسَّاعَةُ بَغْتَةًۭ وَهُمْ لَا يَشْعُرُونَ', 'أفأمنوا أن تأتيهم غشية من عذاب الله أو تأتيهم الساعة بغتة وهم لا يشعرون', NULL, 248, 'local:hafs-text.json'),
  ('hafs-12-108', 'hafs', 12, 108, 'قُلْ هَٰذِهِۦ سَبِيلِىٓ أَدْعُوٓا۟ إِلَى ٱللَّهِ ۚ عَلَىٰ بَصِيرَةٍ أَنَا۠ وَمَنِ ٱتَّبَعَنِى ۖ وَسُبْحَٰنَ ٱللَّهِ وَمَآ أَنَا۠ مِنَ ٱلْمُشْرِكِينَ', 'قل هذه سبيلى أدعوا إلى الله  على بصيرة أنا ومن اتبعنى  وسبحن الله وما أنا من المشركين', NULL, 248, 'local:hafs-text.json'),
  ('hafs-12-109', 'hafs', 12, 109, 'وَمَآ أَرْسَلْنَا مِن قَبْلِكَ إِلَّا رِجَالًۭا نُّوحِىٓ إِلَيْهِم مِّنْ أَهْلِ ٱلْقُرَىٰٓ ۗ أَفَلَمْ يَسِيرُوا۟ فِى ٱلْأَرْضِ فَيَنظُرُوا۟ كَيْفَ كَانَ عَٰقِبَةُ ٱلَّذِينَ مِن قَبْلِهِمْ ۗ وَلَدَارُ ٱلْءَاخِرَةِ خَيْرٌۭ لِّلَّذِينَ ٱتَّقَوْا۟ ۗ أَفَلَا تَعْقِلُونَ', 'وما أرسلنا من قبلك إلا رجالا نوحى إليهم من أهل القرى  أفلم يسيروا فى الأرض فينظروا كيف كان عقبة الذين من قبلهم  ولدار الءاخرة خير للذين اتقوا  أفلا تعقلون', NULL, 248, 'local:hafs-text.json'),
  ('hafs-12-110', 'hafs', 12, 110, 'حَتَّىٰٓ إِذَا ٱسْتَيْـَٔسَ ٱلرُّسُلُ وَظَنُّوٓا۟ أَنَّهُمْ قَدْ كُذِبُوا۟ جَآءَهُمْ نَصْرُنَا فَنُجِّىَ مَن نَّشَآءُ ۖ وَلَا يُرَدُّ بَأْسُنَا عَنِ ٱلْقَوْمِ ٱلْمُجْرِمِينَ', 'حتى إذا استيس الرسل وظنوا أنهم قد كذبوا جاءهم نصرنا فنجى من نشاء  ولا يرد بأسنا عن القوم المجرمين', NULL, 248, 'local:hafs-text.json'),
  ('hafs-12-111', 'hafs', 12, 111, 'لَقَدْ كَانَ فِى قَصَصِهِمْ عِبْرَةٌۭ لِّأُو۟لِى ٱلْأَلْبَٰبِ ۗ مَا كَانَ حَدِيثًۭا يُفْتَرَىٰ وَلَٰكِن تَصْدِيقَ ٱلَّذِى بَيْنَ يَدَيْهِ وَتَفْصِيلَ كُلِّ شَىْءٍۢ وَهُدًۭى وَرَحْمَةًۭ لِّقَوْمٍۢ يُؤْمِنُونَ', 'لقد كان فى قصصهم عبرة لأولى الألبب  ما كان حديثا يفترى ولكن تصديق الذى بين يديه وتفصيل كل شىء وهدى ورحمة لقوم يؤمنون', NULL, 248, 'local:hafs-text.json'),
  ('hafs-13-1', 'hafs', 13, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ الٓمٓر ۚ تِلْكَ ءَايَٰتُ ٱلْكِتَٰبِ ۗ وَٱلَّذِىٓ أُنزِلَ إِلَيْكَ مِن رَّبِّكَ ٱلْحَقُّ وَلَٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يُؤْمِنُونَ', 'بسم الله الرحمن الرحيم المر  تلك ءايت الكتب  والذى أنزل إليك من ربك الحق ولكن أكثر الناس لا يؤمنون', NULL, 249, 'local:hafs-text.json'),
  ('hafs-13-2', 'hafs', 13, 2, 'ٱللَّهُ ٱلَّذِى رَفَعَ ٱلسَّمَٰوَٰتِ بِغَيْرِ عَمَدٍۢ تَرَوْنَهَا ۖ ثُمَّ ٱسْتَوَىٰ عَلَى ٱلْعَرْشِ ۖ وَسَخَّرَ ٱلشَّمْسَ وَٱلْقَمَرَ ۖ كُلٌّۭ يَجْرِى لِأَجَلٍۢ مُّسَمًّۭى ۚ يُدَبِّرُ ٱلْأَمْرَ يُفَصِّلُ ٱلْءَايَٰتِ لَعَلَّكُم بِلِقَآءِ رَبِّكُمْ تُوقِنُونَ', 'الله الذى رفع السموت بغير عمد ترونها  ثم استوى على العرش  وسخر الشمس والقمر  كل يجرى لأجل مسمى  يدبر الأمر يفصل الءايت لعلكم بلقاء ربكم توقنون', NULL, 249, 'local:hafs-text.json'),
  ('hafs-13-3', 'hafs', 13, 3, 'وَهُوَ ٱلَّذِى مَدَّ ٱلْأَرْضَ وَجَعَلَ فِيهَا رَوَٰسِىَ وَأَنْهَٰرًۭا ۖ وَمِن كُلِّ ٱلثَّمَرَٰتِ جَعَلَ فِيهَا زَوْجَيْنِ ٱثْنَيْنِ ۖ يُغْشِى ٱلَّيْلَ ٱلنَّهَارَ ۚ إِنَّ فِى ذَٰلِكَ لَءَايَٰتٍۢ لِّقَوْمٍۢ يَتَفَكَّرُونَ', 'وهو الذى مد الأرض وجعل فيها روسى وأنهرا  ومن كل الثمرت جعل فيها زوجين اثنين  يغشى اليل النهار  إن فى ذلك لءايت لقوم يتفكرون', NULL, 249, 'local:hafs-text.json'),
  ('hafs-13-4', 'hafs', 13, 4, 'وَفِى ٱلْأَرْضِ قِطَعٌۭ مُّتَجَٰوِرَٰتٌۭ وَجَنَّٰتٌۭ مِّنْ أَعْنَٰبٍۢ وَزَرْعٌۭ وَنَخِيلٌۭ صِنْوَانٌۭ وَغَيْرُ صِنْوَانٍۢ يُسْقَىٰ بِمَآءٍۢ وَٰحِدٍۢ وَنُفَضِّلُ بَعْضَهَا عَلَىٰ بَعْضٍۢ فِى ٱلْأُكُلِ ۚ إِنَّ فِى ذَٰلِكَ لَءَايَٰتٍۢ لِّقَوْمٍۢ يَعْقِلُونَ', 'وفى الأرض قطع متجورت وجنت من أعنب وزرع ونخيل صنوان وغير صنوان يسقى بماء وحد ونفضل بعضها على بعض فى الأكل  إن فى ذلك لءايت لقوم يعقلون', NULL, 249, 'local:hafs-text.json'),
  ('hafs-13-5', 'hafs', 13, 5, '۞ وَإِن تَعْجَبْ فَعَجَبٌۭ قَوْلُهُمْ أَءِذَا كُنَّا تُرَٰبًا أَءِنَّا لَفِى خَلْقٍۢ جَدِيدٍ ۗ أُو۟لَٰٓئِكَ ٱلَّذِينَ كَفَرُوا۟ بِرَبِّهِمْ ۖ وَأُو۟لَٰٓئِكَ ٱلْأَغْلَٰلُ فِىٓ أَعْنَاقِهِمْ ۖ وَأُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلنَّارِ ۖ هُمْ فِيهَا خَٰلِدُونَ', 'وإن تعجب فعجب قولهم أءذا كنا تربا أءنا لفى خلق جديد  أولئك الذين كفروا بربهم  وأولئك الأغلل فى أعناقهم  وأولئك أصحب النار  هم فيها خلدون', NULL, 249, 'local:hafs-text.json'),
  ('hafs-13-6', 'hafs', 13, 6, 'وَيَسْتَعْجِلُونَكَ بِٱلسَّيِّئَةِ قَبْلَ ٱلْحَسَنَةِ وَقَدْ خَلَتْ مِن قَبْلِهِمُ ٱلْمَثُلَٰتُ ۗ وَإِنَّ رَبَّكَ لَذُو مَغْفِرَةٍۢ لِّلنَّاسِ عَلَىٰ ظُلْمِهِمْ ۖ وَإِنَّ رَبَّكَ لَشَدِيدُ ٱلْعِقَابِ', 'ويستعجلونك بالسيئة قبل الحسنة وقد خلت من قبلهم المثلت  وإن ربك لذو مغفرة للناس على ظلمهم  وإن ربك لشديد العقاب', NULL, 250, 'local:hafs-text.json'),
  ('hafs-13-7', 'hafs', 13, 7, 'وَيَقُولُ ٱلَّذِينَ كَفَرُوا۟ لَوْلَآ أُنزِلَ عَلَيْهِ ءَايَةٌۭ مِّن رَّبِّهِۦٓ ۗ إِنَّمَآ أَنتَ مُنذِرٌۭ ۖ وَلِكُلِّ قَوْمٍ هَادٍ', 'ويقول الذين كفروا لولا أنزل عليه ءاية من ربه  إنما أنت منذر  ولكل قوم هاد', NULL, 250, 'local:hafs-text.json'),
  ('hafs-13-8', 'hafs', 13, 8, 'ٱللَّهُ يَعْلَمُ مَا تَحْمِلُ كُلُّ أُنثَىٰ وَمَا تَغِيضُ ٱلْأَرْحَامُ وَمَا تَزْدَادُ ۖ وَكُلُّ شَىْءٍ عِندَهُۥ بِمِقْدَارٍ', 'الله يعلم ما تحمل كل أنثى وما تغيض الأرحام وما تزداد  وكل شىء عنده بمقدار', NULL, 250, 'local:hafs-text.json'),
  ('hafs-13-9', 'hafs', 13, 9, 'عَٰلِمُ ٱلْغَيْبِ وَٱلشَّهَٰدَةِ ٱلْكَبِيرُ ٱلْمُتَعَالِ', 'علم الغيب والشهدة الكبير المتعال', NULL, 250, 'local:hafs-text.json'),
  ('hafs-13-10', 'hafs', 13, 10, 'سَوَآءٌۭ مِّنكُم مَّنْ أَسَرَّ ٱلْقَوْلَ وَمَن جَهَرَ بِهِۦ وَمَنْ هُوَ مُسْتَخْفٍۭ بِٱلَّيْلِ وَسَارِبٌۢ بِٱلنَّهَارِ', 'سواء منكم من أسر القول ومن جهر به ومن هو مستخف باليل وسارب بالنهار', NULL, 250, 'local:hafs-text.json'),
  ('hafs-13-11', 'hafs', 13, 11, 'لَهُۥ مُعَقِّبَٰتٌۭ مِّنۢ بَيْنِ يَدَيْهِ وَمِنْ خَلْفِهِۦ يَحْفَظُونَهُۥ مِنْ أَمْرِ ٱللَّهِ ۗ إِنَّ ٱللَّهَ لَا يُغَيِّرُ مَا بِقَوْمٍ حَتَّىٰ يُغَيِّرُوا۟ مَا بِأَنفُسِهِمْ ۗ وَإِذَآ أَرَادَ ٱللَّهُ بِقَوْمٍۢ سُوٓءًۭا فَلَا مَرَدَّ لَهُۥ ۚ وَمَا لَهُم مِّن دُونِهِۦ مِن وَالٍ', 'له معقبت من بين يديه ومن خلفه يحفظونه من أمر الله  إن الله لا يغير ما بقوم حتى يغيروا ما بأنفسهم  وإذا أراد الله بقوم سوءا فلا مرد له  وما لهم من دونه من وال', NULL, 250, 'local:hafs-text.json'),
  ('hafs-13-12', 'hafs', 13, 12, 'هُوَ ٱلَّذِى يُرِيكُمُ ٱلْبَرْقَ خَوْفًۭا وَطَمَعًۭا وَيُنشِئُ ٱلسَّحَابَ ٱلثِّقَالَ', 'هو الذى يريكم البرق خوفا وطمعا وينشئ السحاب الثقال', NULL, 250, 'local:hafs-text.json'),
  ('hafs-13-13', 'hafs', 13, 13, 'وَيُسَبِّحُ ٱلرَّعْدُ بِحَمْدِهِۦ وَٱلْمَلَٰٓئِكَةُ مِنْ خِيفَتِهِۦ وَيُرْسِلُ ٱلصَّوَٰعِقَ فَيُصِيبُ بِهَا مَن يَشَآءُ وَهُمْ يُجَٰدِلُونَ فِى ٱللَّهِ وَهُوَ شَدِيدُ ٱلْمِحَالِ', 'ويسبح الرعد بحمده والملئكة من خيفته ويرسل الصوعق فيصيب بها من يشاء وهم يجدلون فى الله وهو شديد المحال', NULL, 250, 'local:hafs-text.json'),
  ('hafs-13-14', 'hafs', 13, 14, 'لَهُۥ دَعْوَةُ ٱلْحَقِّ ۖ وَٱلَّذِينَ يَدْعُونَ مِن دُونِهِۦ لَا يَسْتَجِيبُونَ لَهُم بِشَىْءٍ إِلَّا كَبَٰسِطِ كَفَّيْهِ إِلَى ٱلْمَآءِ لِيَبْلُغَ فَاهُ وَمَا هُوَ بِبَٰلِغِهِۦ ۚ وَمَا دُعَآءُ ٱلْكَٰفِرِينَ إِلَّا فِى ضَلَٰلٍۢ', 'له دعوة الحق  والذين يدعون من دونه لا يستجيبون لهم بشىء إلا كبسط كفيه إلى الماء ليبلغ فاه وما هو ببلغه  وما دعاء الكفرين إلا فى ضلل', NULL, 251, 'local:hafs-text.json'),
  ('hafs-13-15', 'hafs', 13, 15, 'وَلِلَّهِ يَسْجُدُ مَن فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ طَوْعًۭا وَكَرْهًۭا وَظِلَٰلُهُم بِٱلْغُدُوِّ وَٱلْءَاصَالِ ۩', 'ولله يسجد من فى السموت والأرض طوعا وكرها وظللهم بالغدو والءاصال', NULL, 251, 'local:hafs-text.json'),
  ('hafs-13-16', 'hafs', 13, 16, 'قُلْ مَن رَّبُّ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ قُلِ ٱللَّهُ ۚ قُلْ أَفَٱتَّخَذْتُم مِّن دُونِهِۦٓ أَوْلِيَآءَ لَا يَمْلِكُونَ لِأَنفُسِهِمْ نَفْعًۭا وَلَا ضَرًّۭا ۚ قُلْ هَلْ يَسْتَوِى ٱلْأَعْمَىٰ وَٱلْبَصِيرُ أَمْ هَلْ تَسْتَوِى ٱلظُّلُمَٰتُ وَٱلنُّورُ ۗ أَمْ جَعَلُوا۟ لِلَّهِ شُرَكَآءَ خَلَقُوا۟ كَخَلْقِهِۦ فَتَشَٰبَهَ ٱلْخَلْقُ عَلَيْهِمْ ۚ قُلِ ٱللَّهُ خَٰلِقُ كُلِّ شَىْءٍۢ وَهُوَ ٱلْوَٰحِدُ ٱلْقَهَّٰرُ', 'قل من رب السموت والأرض قل الله  قل أفاتخذتم من دونه أولياء لا يملكون لأنفسهم نفعا ولا ضرا  قل هل يستوى الأعمى والبصير أم هل تستوى الظلمت والنور  أم جعلوا لله شركاء خلقوا كخلقه فتشبه الخلق عليهم  قل الله خلق كل شىء وهو الوحد القهر', NULL, 251, 'local:hafs-text.json'),
  ('hafs-13-17', 'hafs', 13, 17, 'أَنزَلَ مِنَ ٱلسَّمَآءِ مَآءًۭ فَسَالَتْ أَوْدِيَةٌۢ بِقَدَرِهَا فَٱحْتَمَلَ ٱلسَّيْلُ زَبَدًۭا رَّابِيًۭا ۚ وَمِمَّا يُوقِدُونَ عَلَيْهِ فِى ٱلنَّارِ ٱبْتِغَآءَ حِلْيَةٍ أَوْ مَتَٰعٍۢ زَبَدٌۭ مِّثْلُهُۥ ۚ كَذَٰلِكَ يَضْرِبُ ٱللَّهُ ٱلْحَقَّ وَٱلْبَٰطِلَ ۚ فَأَمَّا ٱلزَّبَدُ فَيَذْهَبُ جُفَآءًۭ ۖ وَأَمَّا مَا يَنفَعُ ٱلنَّاسَ فَيَمْكُثُ فِى ٱلْأَرْضِ ۚ كَذَٰلِكَ يَضْرِبُ ٱللَّهُ ٱلْأَمْثَالَ', 'أنزل من السماء ماء فسالت أودية بقدرها فاحتمل السيل زبدا رابيا  ومما يوقدون عليه فى النار ابتغاء حلية أو متع زبد مثله  كذلك يضرب الله الحق والبطل  فأما الزبد فيذهب جفاء  وأما ما ينفع الناس فيمكث فى الأرض  كذلك يضرب الله الأمثال', NULL, 251, 'local:hafs-text.json'),
  ('hafs-13-18', 'hafs', 13, 18, 'لِلَّذِينَ ٱسْتَجَابُوا۟ لِرَبِّهِمُ ٱلْحُسْنَىٰ ۚ وَٱلَّذِينَ لَمْ يَسْتَجِيبُوا۟ لَهُۥ لَوْ أَنَّ لَهُم مَّا فِى ٱلْأَرْضِ جَمِيعًۭا وَمِثْلَهُۥ مَعَهُۥ لَٱفْتَدَوْا۟ بِهِۦٓ ۚ أُو۟لَٰٓئِكَ لَهُمْ سُوٓءُ ٱلْحِسَابِ وَمَأْوَىٰهُمْ جَهَنَّمُ ۖ وَبِئْسَ ٱلْمِهَادُ', 'للذين استجابوا لربهم الحسنى  والذين لم يستجيبوا له لو أن لهم ما فى الأرض جميعا ومثله معه لافتدوا به  أولئك لهم سوء الحساب ومأوىهم جهنم  وبئس المهاد', NULL, 251, 'local:hafs-text.json'),
  ('hafs-13-19', 'hafs', 13, 19, '۞ أَفَمَن يَعْلَمُ أَنَّمَآ أُنزِلَ إِلَيْكَ مِن رَّبِّكَ ٱلْحَقُّ كَمَنْ هُوَ أَعْمَىٰٓ ۚ إِنَّمَا يَتَذَكَّرُ أُو۟لُوا۟ ٱلْأَلْبَٰبِ', 'أفمن يعلم أنما أنزل إليك من ربك الحق كمن هو أعمى  إنما يتذكر أولوا الألبب', NULL, 252, 'local:hafs-text.json'),
  ('hafs-13-20', 'hafs', 13, 20, 'ٱلَّذِينَ يُوفُونَ بِعَهْدِ ٱللَّهِ وَلَا يَنقُضُونَ ٱلْمِيثَٰقَ', 'الذين يوفون بعهد الله ولا ينقضون الميثق', NULL, 252, 'local:hafs-text.json'),
  ('hafs-13-21', 'hafs', 13, 21, 'وَٱلَّذِينَ يَصِلُونَ مَآ أَمَرَ ٱللَّهُ بِهِۦٓ أَن يُوصَلَ وَيَخْشَوْنَ رَبَّهُمْ وَيَخَافُونَ سُوٓءَ ٱلْحِسَابِ', 'والذين يصلون ما أمر الله به أن يوصل ويخشون ربهم ويخافون سوء الحساب', NULL, 252, 'local:hafs-text.json'),
  ('hafs-13-22', 'hafs', 13, 22, 'وَٱلَّذِينَ صَبَرُوا۟ ٱبْتِغَآءَ وَجْهِ رَبِّهِمْ وَأَقَامُوا۟ ٱلصَّلَوٰةَ وَأَنفَقُوا۟ مِمَّا رَزَقْنَٰهُمْ سِرًّۭا وَعَلَانِيَةًۭ وَيَدْرَءُونَ بِٱلْحَسَنَةِ ٱلسَّيِّئَةَ أُو۟لَٰٓئِكَ لَهُمْ عُقْبَى ٱلدَّارِ', 'والذين صبروا ابتغاء وجه ربهم وأقاموا الصلوة وأنفقوا مما رزقنهم سرا وعلانية ويدرءون بالحسنة السيئة أولئك لهم عقبى الدار', NULL, 252, 'local:hafs-text.json'),
  ('hafs-13-23', 'hafs', 13, 23, 'جَنَّٰتُ عَدْنٍۢ يَدْخُلُونَهَا وَمَن صَلَحَ مِنْ ءَابَآئِهِمْ وَأَزْوَٰجِهِمْ وَذُرِّيَّٰتِهِمْ ۖ وَٱلْمَلَٰٓئِكَةُ يَدْخُلُونَ عَلَيْهِم مِّن كُلِّ بَابٍۢ', 'جنت عدن يدخلونها ومن صلح من ءابائهم وأزوجهم وذريتهم  والملئكة يدخلون عليهم من كل باب', NULL, 252, 'local:hafs-text.json'),
  ('hafs-13-24', 'hafs', 13, 24, 'سَلَٰمٌ عَلَيْكُم بِمَا صَبَرْتُمْ ۚ فَنِعْمَ عُقْبَى ٱلدَّارِ', 'سلم عليكم بما صبرتم  فنعم عقبى الدار', NULL, 252, 'local:hafs-text.json'),
  ('hafs-13-25', 'hafs', 13, 25, 'وَٱلَّذِينَ يَنقُضُونَ عَهْدَ ٱللَّهِ مِنۢ بَعْدِ مِيثَٰقِهِۦ وَيَقْطَعُونَ مَآ أَمَرَ ٱللَّهُ بِهِۦٓ أَن يُوصَلَ وَيُفْسِدُونَ فِى ٱلْأَرْضِ ۙ أُو۟لَٰٓئِكَ لَهُمُ ٱللَّعْنَةُ وَلَهُمْ سُوٓءُ ٱلدَّارِ', 'والذين ينقضون عهد الله من بعد ميثقه ويقطعون ما أمر الله به أن يوصل ويفسدون فى الأرض  أولئك لهم اللعنة ولهم سوء الدار', NULL, 252, 'local:hafs-text.json'),
  ('hafs-13-26', 'hafs', 13, 26, 'ٱللَّهُ يَبْسُطُ ٱلرِّزْقَ لِمَن يَشَآءُ وَيَقْدِرُ ۚ وَفَرِحُوا۟ بِٱلْحَيَوٰةِ ٱلدُّنْيَا وَمَا ٱلْحَيَوٰةُ ٱلدُّنْيَا فِى ٱلْءَاخِرَةِ إِلَّا مَتَٰعٌۭ', 'الله يبسط الرزق لمن يشاء ويقدر  وفرحوا بالحيوة الدنيا وما الحيوة الدنيا فى الءاخرة إلا متع', NULL, 252, 'local:hafs-text.json'),
  ('hafs-13-27', 'hafs', 13, 27, 'وَيَقُولُ ٱلَّذِينَ كَفَرُوا۟ لَوْلَآ أُنزِلَ عَلَيْهِ ءَايَةٌۭ مِّن رَّبِّهِۦ ۗ قُلْ إِنَّ ٱللَّهَ يُضِلُّ مَن يَشَآءُ وَيَهْدِىٓ إِلَيْهِ مَنْ أَنَابَ', 'ويقول الذين كفروا لولا أنزل عليه ءاية من ربه  قل إن الله يضل من يشاء ويهدى إليه من أناب', NULL, 252, 'local:hafs-text.json'),
  ('hafs-13-28', 'hafs', 13, 28, 'ٱلَّذِينَ ءَامَنُوا۟ وَتَطْمَئِنُّ قُلُوبُهُم بِذِكْرِ ٱللَّهِ ۗ أَلَا بِذِكْرِ ٱللَّهِ تَطْمَئِنُّ ٱلْقُلُوبُ', 'الذين ءامنوا وتطمئن قلوبهم بذكر الله  ألا بذكر الله تطمئن القلوب', NULL, 252, 'local:hafs-text.json'),
  ('hafs-13-29', 'hafs', 13, 29, 'ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ طُوبَىٰ لَهُمْ وَحُسْنُ مَـَٔابٍۢ', 'الذين ءامنوا وعملوا الصلحت طوبى لهم وحسن ماب', NULL, 253, 'local:hafs-text.json'),
  ('hafs-13-30', 'hafs', 13, 30, 'كَذَٰلِكَ أَرْسَلْنَٰكَ فِىٓ أُمَّةٍۢ قَدْ خَلَتْ مِن قَبْلِهَآ أُمَمٌۭ لِّتَتْلُوَا۟ عَلَيْهِمُ ٱلَّذِىٓ أَوْحَيْنَآ إِلَيْكَ وَهُمْ يَكْفُرُونَ بِٱلرَّحْمَٰنِ ۚ قُلْ هُوَ رَبِّى لَآ إِلَٰهَ إِلَّا هُوَ عَلَيْهِ تَوَكَّلْتُ وَإِلَيْهِ مَتَابِ', 'كذلك أرسلنك فى أمة قد خلت من قبلها أمم لتتلوا عليهم الذى أوحينا إليك وهم يكفرون بالرحمن  قل هو ربى لا إله إلا هو عليه توكلت وإليه متاب', NULL, 253, 'local:hafs-text.json'),
  ('hafs-13-31', 'hafs', 13, 31, 'وَلَوْ أَنَّ قُرْءَانًۭا سُيِّرَتْ بِهِ ٱلْجِبَالُ أَوْ قُطِّعَتْ بِهِ ٱلْأَرْضُ أَوْ كُلِّمَ بِهِ ٱلْمَوْتَىٰ ۗ بَل لِّلَّهِ ٱلْأَمْرُ جَمِيعًا ۗ أَفَلَمْ يَا۟يْـَٔسِ ٱلَّذِينَ ءَامَنُوٓا۟ أَن لَّوْ يَشَآءُ ٱللَّهُ لَهَدَى ٱلنَّاسَ جَمِيعًۭا ۗ وَلَا يَزَالُ ٱلَّذِينَ كَفَرُوا۟ تُصِيبُهُم بِمَا صَنَعُوا۟ قَارِعَةٌ أَوْ تَحُلُّ قَرِيبًۭا مِّن دَارِهِمْ حَتَّىٰ يَأْتِىَ وَعْدُ ٱللَّهِ ۚ إِنَّ ٱللَّهَ لَا يُخْلِفُ ٱلْمِيعَادَ', 'ولو أن قرءانا سيرت به الجبال أو قطعت به الأرض أو كلم به الموتى  بل لله الأمر جميعا  أفلم يايس الذين ءامنوا أن لو يشاء الله لهدى الناس جميعا  ولا يزال الذين كفروا تصيبهم بما صنعوا قارعة أو تحل قريبا من دارهم حتى يأتى وعد الله  إن الله لا يخلف الميعاد', NULL, 253, 'local:hafs-text.json'),
  ('hafs-13-32', 'hafs', 13, 32, 'وَلَقَدِ ٱسْتُهْزِئَ بِرُسُلٍۢ مِّن قَبْلِكَ فَأَمْلَيْتُ لِلَّذِينَ كَفَرُوا۟ ثُمَّ أَخَذْتُهُمْ ۖ فَكَيْفَ كَانَ عِقَابِ', 'ولقد استهزئ برسل من قبلك فأمليت للذين كفروا ثم أخذتهم  فكيف كان عقاب', NULL, 253, 'local:hafs-text.json'),
  ('hafs-13-33', 'hafs', 13, 33, 'أَفَمَنْ هُوَ قَآئِمٌ عَلَىٰ كُلِّ نَفْسٍۭ بِمَا كَسَبَتْ ۗ وَجَعَلُوا۟ لِلَّهِ شُرَكَآءَ قُلْ سَمُّوهُمْ ۚ أَمْ تُنَبِّـُٔونَهُۥ بِمَا لَا يَعْلَمُ فِى ٱلْأَرْضِ أَم بِظَٰهِرٍۢ مِّنَ ٱلْقَوْلِ ۗ بَلْ زُيِّنَ لِلَّذِينَ كَفَرُوا۟ مَكْرُهُمْ وَصُدُّوا۟ عَنِ ٱلسَّبِيلِ ۗ وَمَن يُضْلِلِ ٱللَّهُ فَمَا لَهُۥ مِنْ هَادٍۢ', 'أفمن هو قائم على كل نفس بما كسبت  وجعلوا لله شركاء قل سموهم  أم تنبونه بما لا يعلم فى الأرض أم بظهر من القول  بل زين للذين كفروا مكرهم وصدوا عن السبيل  ومن يضلل الله فما له من هاد', NULL, 253, 'local:hafs-text.json'),
  ('hafs-13-34', 'hafs', 13, 34, 'لَّهُمْ عَذَابٌۭ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا ۖ وَلَعَذَابُ ٱلْءَاخِرَةِ أَشَقُّ ۖ وَمَا لَهُم مِّنَ ٱللَّهِ مِن وَاقٍۢ', 'لهم عذاب فى الحيوة الدنيا  ولعذاب الءاخرة أشق  وما لهم من الله من واق', NULL, 253, 'local:hafs-text.json'),
  ('hafs-13-35', 'hafs', 13, 35, '۞ مَّثَلُ ٱلْجَنَّةِ ٱلَّتِى وُعِدَ ٱلْمُتَّقُونَ ۖ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ ۖ أُكُلُهَا دَآئِمٌۭ وَظِلُّهَا ۚ تِلْكَ عُقْبَى ٱلَّذِينَ ٱتَّقَوا۟ ۖ وَّعُقْبَى ٱلْكَٰفِرِينَ ٱلنَّارُ', 'مثل الجنة التى وعد المتقون  تجرى من تحتها الأنهر  أكلها دائم وظلها  تلك عقبى الذين اتقوا  وعقبى الكفرين النار', NULL, 254, 'local:hafs-text.json'),
  ('hafs-13-36', 'hafs', 13, 36, 'وَٱلَّذِينَ ءَاتَيْنَٰهُمُ ٱلْكِتَٰبَ يَفْرَحُونَ بِمَآ أُنزِلَ إِلَيْكَ ۖ وَمِنَ ٱلْأَحْزَابِ مَن يُنكِرُ بَعْضَهُۥ ۚ قُلْ إِنَّمَآ أُمِرْتُ أَنْ أَعْبُدَ ٱللَّهَ وَلَآ أُشْرِكَ بِهِۦٓ ۚ إِلَيْهِ أَدْعُوا۟ وَإِلَيْهِ مَـَٔابِ', 'والذين ءاتينهم الكتب يفرحون بما أنزل إليك  ومن الأحزاب من ينكر بعضه  قل إنما أمرت أن أعبد الله ولا أشرك به  إليه أدعوا وإليه ماب', NULL, 254, 'local:hafs-text.json'),
  ('hafs-13-37', 'hafs', 13, 37, 'وَكَذَٰلِكَ أَنزَلْنَٰهُ حُكْمًا عَرَبِيًّۭا ۚ وَلَئِنِ ٱتَّبَعْتَ أَهْوَآءَهُم بَعْدَمَا جَآءَكَ مِنَ ٱلْعِلْمِ مَا لَكَ مِنَ ٱللَّهِ مِن وَلِىٍّۢ وَلَا وَاقٍۢ', 'وكذلك أنزلنه حكما عربيا  ولئن اتبعت أهواءهم بعدما جاءك من العلم ما لك من الله من ولى ولا واق', NULL, 254, 'local:hafs-text.json'),
  ('hafs-13-38', 'hafs', 13, 38, 'وَلَقَدْ أَرْسَلْنَا رُسُلًۭا مِّن قَبْلِكَ وَجَعَلْنَا لَهُمْ أَزْوَٰجًۭا وَذُرِّيَّةًۭ ۚ وَمَا كَانَ لِرَسُولٍ أَن يَأْتِىَ بِـَٔايَةٍ إِلَّا بِإِذْنِ ٱللَّهِ ۗ لِكُلِّ أَجَلٍۢ كِتَابٌۭ', 'ولقد أرسلنا رسلا من قبلك وجعلنا لهم أزوجا وذرية  وما كان لرسول أن يأتى باية إلا بإذن الله  لكل أجل كتاب', NULL, 254, 'local:hafs-text.json'),
  ('hafs-13-39', 'hafs', 13, 39, 'يَمْحُوا۟ ٱللَّهُ مَا يَشَآءُ وَيُثْبِتُ ۖ وَعِندَهُۥٓ أُمُّ ٱلْكِتَٰبِ', 'يمحوا الله ما يشاء ويثبت  وعنده أم الكتب', NULL, 254, 'local:hafs-text.json'),
  ('hafs-13-40', 'hafs', 13, 40, 'وَإِن مَّا نُرِيَنَّكَ بَعْضَ ٱلَّذِى نَعِدُهُمْ أَوْ نَتَوَفَّيَنَّكَ فَإِنَّمَا عَلَيْكَ ٱلْبَلَٰغُ وَعَلَيْنَا ٱلْحِسَابُ', 'وإن ما نرينك بعض الذى نعدهم أو نتوفينك فإنما عليك البلغ وعلينا الحساب', NULL, 254, 'local:hafs-text.json'),
  ('hafs-13-41', 'hafs', 13, 41, 'أَوَلَمْ يَرَوْا۟ أَنَّا نَأْتِى ٱلْأَرْضَ نَنقُصُهَا مِنْ أَطْرَافِهَا ۚ وَٱللَّهُ يَحْكُمُ لَا مُعَقِّبَ لِحُكْمِهِۦ ۚ وَهُوَ سَرِيعُ ٱلْحِسَابِ', 'أولم يروا أنا نأتى الأرض ننقصها من أطرافها  والله يحكم لا معقب لحكمه  وهو سريع الحساب', NULL, 254, 'local:hafs-text.json'),
  ('hafs-13-42', 'hafs', 13, 42, 'وَقَدْ مَكَرَ ٱلَّذِينَ مِن قَبْلِهِمْ فَلِلَّهِ ٱلْمَكْرُ جَمِيعًۭا ۖ يَعْلَمُ مَا تَكْسِبُ كُلُّ نَفْسٍۢ ۗ وَسَيَعْلَمُ ٱلْكُفَّٰرُ لِمَنْ عُقْبَى ٱلدَّارِ', 'وقد مكر الذين من قبلهم فلله المكر جميعا  يعلم ما تكسب كل نفس  وسيعلم الكفر لمن عقبى الدار', NULL, 254, 'local:hafs-text.json'),
  ('hafs-13-43', 'hafs', 13, 43, 'وَيَقُولُ ٱلَّذِينَ كَفَرُوا۟ لَسْتَ مُرْسَلًۭا ۚ قُلْ كَفَىٰ بِٱللَّهِ شَهِيدًۢا بَيْنِى وَبَيْنَكُمْ وَمَنْ عِندَهُۥ عِلْمُ ٱلْكِتَٰبِ', 'ويقول الذين كفروا لست مرسلا  قل كفى بالله شهيدا بينى وبينكم ومن عنده علم الكتب', NULL, 255, 'local:hafs-text.json'),
  ('hafs-14-1', 'hafs', 14, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ الٓر ۚ كِتَٰبٌ أَنزَلْنَٰهُ إِلَيْكَ لِتُخْرِجَ ٱلنَّاسَ مِنَ ٱلظُّلُمَٰتِ إِلَى ٱلنُّورِ بِإِذْنِ رَبِّهِمْ إِلَىٰ صِرَٰطِ ٱلْعَزِيزِ ٱلْحَمِيدِ', 'بسم الله الرحمن الرحيم الر  كتب أنزلنه إليك لتخرج الناس من الظلمت إلى النور بإذن ربهم إلى صرط العزيز الحميد', NULL, 255, 'local:hafs-text.json'),
  ('hafs-14-2', 'hafs', 14, 2, 'ٱللَّهِ ٱلَّذِى لَهُۥ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ ۗ وَوَيْلٌۭ لِّلْكَٰفِرِينَ مِنْ عَذَابٍۢ شَدِيدٍ', 'الله الذى له ما فى السموت وما فى الأرض  وويل للكفرين من عذاب شديد', NULL, 255, 'local:hafs-text.json'),
  ('hafs-14-3', 'hafs', 14, 3, 'ٱلَّذِينَ يَسْتَحِبُّونَ ٱلْحَيَوٰةَ ٱلدُّنْيَا عَلَى ٱلْءَاخِرَةِ وَيَصُدُّونَ عَن سَبِيلِ ٱللَّهِ وَيَبْغُونَهَا عِوَجًا ۚ أُو۟لَٰٓئِكَ فِى ضَلَٰلٍۭ بَعِيدٍۢ', 'الذين يستحبون الحيوة الدنيا على الءاخرة ويصدون عن سبيل الله ويبغونها عوجا  أولئك فى ضلل بعيد', NULL, 255, 'local:hafs-text.json'),
  ('hafs-14-4', 'hafs', 14, 4, 'وَمَآ أَرْسَلْنَا مِن رَّسُولٍ إِلَّا بِلِسَانِ قَوْمِهِۦ لِيُبَيِّنَ لَهُمْ ۖ فَيُضِلُّ ٱللَّهُ مَن يَشَآءُ وَيَهْدِى مَن يَشَآءُ ۚ وَهُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ', 'وما أرسلنا من رسول إلا بلسان قومه ليبين لهم  فيضل الله من يشاء ويهدى من يشاء  وهو العزيز الحكيم', NULL, 255, 'local:hafs-text.json'),
  ('hafs-14-5', 'hafs', 14, 5, 'وَلَقَدْ أَرْسَلْنَا مُوسَىٰ بِـَٔايَٰتِنَآ أَنْ أَخْرِجْ قَوْمَكَ مِنَ ٱلظُّلُمَٰتِ إِلَى ٱلنُّورِ وَذَكِّرْهُم بِأَيَّىٰمِ ٱللَّهِ ۚ إِنَّ فِى ذَٰلِكَ لَءَايَٰتٍۢ لِّكُلِّ صَبَّارٍۢ شَكُورٍۢ', 'ولقد أرسلنا موسى بايتنا أن أخرج قومك من الظلمت إلى النور وذكرهم بأيىم الله  إن فى ذلك لءايت لكل صبار شكور', NULL, 255, 'local:hafs-text.json'),
  ('hafs-14-6', 'hafs', 14, 6, 'وَإِذْ قَالَ مُوسَىٰ لِقَوْمِهِ ٱذْكُرُوا۟ نِعْمَةَ ٱللَّهِ عَلَيْكُمْ إِذْ أَنجَىٰكُم مِّنْ ءَالِ فِرْعَوْنَ يَسُومُونَكُمْ سُوٓءَ ٱلْعَذَابِ وَيُذَبِّحُونَ أَبْنَآءَكُمْ وَيَسْتَحْيُونَ نِسَآءَكُمْ ۚ وَفِى ذَٰلِكُم بَلَآءٌۭ مِّن رَّبِّكُمْ عَظِيمٌۭ', 'وإذ قال موسى لقومه اذكروا نعمة الله عليكم إذ أنجىكم من ءال فرعون يسومونكم سوء العذاب ويذبحون أبناءكم ويستحيون نساءكم  وفى ذلكم بلاء من ربكم عظيم', NULL, 256, 'local:hafs-text.json'),
  ('hafs-14-7', 'hafs', 14, 7, 'وَإِذْ تَأَذَّنَ رَبُّكُمْ لَئِن شَكَرْتُمْ لَأَزِيدَنَّكُمْ ۖ وَلَئِن كَفَرْتُمْ إِنَّ عَذَابِى لَشَدِيدٌۭ', 'وإذ تأذن ربكم لئن شكرتم لأزيدنكم  ولئن كفرتم إن عذابى لشديد', NULL, 256, 'local:hafs-text.json'),
  ('hafs-14-8', 'hafs', 14, 8, 'وَقَالَ مُوسَىٰٓ إِن تَكْفُرُوٓا۟ أَنتُمْ وَمَن فِى ٱلْأَرْضِ جَمِيعًۭا فَإِنَّ ٱللَّهَ لَغَنِىٌّ حَمِيدٌ', 'وقال موسى إن تكفروا أنتم ومن فى الأرض جميعا فإن الله لغنى حميد', NULL, 256, 'local:hafs-text.json'),
  ('hafs-14-9', 'hafs', 14, 9, 'أَلَمْ يَأْتِكُمْ نَبَؤُا۟ ٱلَّذِينَ مِن قَبْلِكُمْ قَوْمِ نُوحٍۢ وَعَادٍۢ وَثَمُودَ ۛ وَٱلَّذِينَ مِنۢ بَعْدِهِمْ ۛ لَا يَعْلَمُهُمْ إِلَّا ٱللَّهُ ۚ جَآءَتْهُمْ رُسُلُهُم بِٱلْبَيِّنَٰتِ فَرَدُّوٓا۟ أَيْدِيَهُمْ فِىٓ أَفْوَٰهِهِمْ وَقَالُوٓا۟ إِنَّا كَفَرْنَا بِمَآ أُرْسِلْتُم بِهِۦ وَإِنَّا لَفِى شَكٍّۢ مِّمَّا تَدْعُونَنَآ إِلَيْهِ مُرِيبٍۢ', 'ألم يأتكم نبؤا الذين من قبلكم قوم نوح وعاد وثمود  والذين من بعدهم  لا يعلمهم إلا الله  جاءتهم رسلهم بالبينت فردوا أيديهم فى أفوههم وقالوا إنا كفرنا بما أرسلتم به وإنا لفى شك مما تدعوننا إليه مريب', NULL, 256, 'local:hafs-text.json'),
  ('hafs-14-10', 'hafs', 14, 10, '۞ قَالَتْ رُسُلُهُمْ أَفِى ٱللَّهِ شَكٌّۭ فَاطِرِ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ ۖ يَدْعُوكُمْ لِيَغْفِرَ لَكُم مِّن ذُنُوبِكُمْ وَيُؤَخِّرَكُمْ إِلَىٰٓ أَجَلٍۢ مُّسَمًّۭى ۚ قَالُوٓا۟ إِنْ أَنتُمْ إِلَّا بَشَرٌۭ مِّثْلُنَا تُرِيدُونَ أَن تَصُدُّونَا عَمَّا كَانَ يَعْبُدُ ءَابَآؤُنَا فَأْتُونَا بِسُلْطَٰنٍۢ مُّبِينٍۢ', 'قالت رسلهم أفى الله شك فاطر السموت والأرض  يدعوكم ليغفر لكم من ذنوبكم ويؤخركم إلى أجل مسمى  قالوا إن أنتم إلا بشر مثلنا تريدون أن تصدونا عما كان يعبد ءاباؤنا فأتونا بسلطن مبين', NULL, 256, 'local:hafs-text.json'),
  ('hafs-14-11', 'hafs', 14, 11, 'قَالَتْ لَهُمْ رُسُلُهُمْ إِن نَّحْنُ إِلَّا بَشَرٌۭ مِّثْلُكُمْ وَلَٰكِنَّ ٱللَّهَ يَمُنُّ عَلَىٰ مَن يَشَآءُ مِنْ عِبَادِهِۦ ۖ وَمَا كَانَ لَنَآ أَن نَّأْتِيَكُم بِسُلْطَٰنٍ إِلَّا بِإِذْنِ ٱللَّهِ ۚ وَعَلَى ٱللَّهِ فَلْيَتَوَكَّلِ ٱلْمُؤْمِنُونَ', 'قالت لهم رسلهم إن نحن إلا بشر مثلكم ولكن الله يمن على من يشاء من عباده  وما كان لنا أن نأتيكم بسلطن إلا بإذن الله  وعلى الله فليتوكل المؤمنون', NULL, 257, 'local:hafs-text.json'),
  ('hafs-14-12', 'hafs', 14, 12, 'وَمَا لَنَآ أَلَّا نَتَوَكَّلَ عَلَى ٱللَّهِ وَقَدْ هَدَىٰنَا سُبُلَنَا ۚ وَلَنَصْبِرَنَّ عَلَىٰ مَآ ءَاذَيْتُمُونَا ۚ وَعَلَى ٱللَّهِ فَلْيَتَوَكَّلِ ٱلْمُتَوَكِّلُونَ', 'وما لنا ألا نتوكل على الله وقد هدىنا سبلنا  ولنصبرن على ما ءاذيتمونا  وعلى الله فليتوكل المتوكلون', NULL, 257, 'local:hafs-text.json'),
  ('hafs-14-13', 'hafs', 14, 13, 'وَقَالَ ٱلَّذِينَ كَفَرُوا۟ لِرُسُلِهِمْ لَنُخْرِجَنَّكُم مِّنْ أَرْضِنَآ أَوْ لَتَعُودُنَّ فِى مِلَّتِنَا ۖ فَأَوْحَىٰٓ إِلَيْهِمْ رَبُّهُمْ لَنُهْلِكَنَّ ٱلظَّٰلِمِينَ', 'وقال الذين كفروا لرسلهم لنخرجنكم من أرضنا أو لتعودن فى ملتنا  فأوحى إليهم ربهم لنهلكن الظلمين', NULL, 257, 'local:hafs-text.json'),
  ('hafs-14-14', 'hafs', 14, 14, 'وَلَنُسْكِنَنَّكُمُ ٱلْأَرْضَ مِنۢ بَعْدِهِمْ ۚ ذَٰلِكَ لِمَنْ خَافَ مَقَامِى وَخَافَ وَعِيدِ', 'ولنسكننكم الأرض من بعدهم  ذلك لمن خاف مقامى وخاف وعيد', NULL, 257, 'local:hafs-text.json'),
  ('hafs-14-15', 'hafs', 14, 15, 'وَٱسْتَفْتَحُوا۟ وَخَابَ كُلُّ جَبَّارٍ عَنِيدٍۢ', 'واستفتحوا وخاب كل جبار عنيد', NULL, 257, 'local:hafs-text.json'),
  ('hafs-14-16', 'hafs', 14, 16, 'مِّن وَرَآئِهِۦ جَهَنَّمُ وَيُسْقَىٰ مِن مَّآءٍۢ صَدِيدٍۢ', 'من ورائه جهنم ويسقى من ماء صديد', NULL, 257, 'local:hafs-text.json'),
  ('hafs-14-17', 'hafs', 14, 17, 'يَتَجَرَّعُهُۥ وَلَا يَكَادُ يُسِيغُهُۥ وَيَأْتِيهِ ٱلْمَوْتُ مِن كُلِّ مَكَانٍۢ وَمَا هُوَ بِمَيِّتٍۢ ۖ وَمِن وَرَآئِهِۦ عَذَابٌ غَلِيظٌۭ', 'يتجرعه ولا يكاد يسيغه ويأتيه الموت من كل مكان وما هو بميت  ومن ورائه عذاب غليظ', NULL, 257, 'local:hafs-text.json'),
  ('hafs-14-18', 'hafs', 14, 18, 'مَّثَلُ ٱلَّذِينَ كَفَرُوا۟ بِرَبِّهِمْ ۖ أَعْمَٰلُهُمْ كَرَمَادٍ ٱشْتَدَّتْ بِهِ ٱلرِّيحُ فِى يَوْمٍ عَاصِفٍۢ ۖ لَّا يَقْدِرُونَ مِمَّا كَسَبُوا۟ عَلَىٰ شَىْءٍۢ ۚ ذَٰلِكَ هُوَ ٱلضَّلَٰلُ ٱلْبَعِيدُ', 'مثل الذين كفروا بربهم  أعملهم كرماد اشتدت به الريح فى يوم عاصف  لا يقدرون مما كسبوا على شىء  ذلك هو الضلل البعيد', NULL, 257, 'local:hafs-text.json'),
  ('hafs-14-19', 'hafs', 14, 19, 'أَلَمْ تَرَ أَنَّ ٱللَّهَ خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ بِٱلْحَقِّ ۚ إِن يَشَأْ يُذْهِبْكُمْ وَيَأْتِ بِخَلْقٍۢ جَدِيدٍۢ', 'ألم تر أن الله خلق السموت والأرض بالحق  إن يشأ يذهبكم ويأت بخلق جديد', NULL, 258, 'local:hafs-text.json'),
  ('hafs-14-20', 'hafs', 14, 20, 'وَمَا ذَٰلِكَ عَلَى ٱللَّهِ بِعَزِيزٍۢ', 'وما ذلك على الله بعزيز', NULL, 258, 'local:hafs-text.json'),
  ('hafs-14-21', 'hafs', 14, 21, 'وَبَرَزُوا۟ لِلَّهِ جَمِيعًۭا فَقَالَ ٱلضُّعَفَٰٓؤُا۟ لِلَّذِينَ ٱسْتَكْبَرُوٓا۟ إِنَّا كُنَّا لَكُمْ تَبَعًۭا فَهَلْ أَنتُم مُّغْنُونَ عَنَّا مِنْ عَذَابِ ٱللَّهِ مِن شَىْءٍۢ ۚ قَالُوا۟ لَوْ هَدَىٰنَا ٱللَّهُ لَهَدَيْنَٰكُمْ ۖ سَوَآءٌ عَلَيْنَآ أَجَزِعْنَآ أَمْ صَبَرْنَا مَا لَنَا مِن مَّحِيصٍۢ', 'وبرزوا لله جميعا فقال الضعفؤا للذين استكبروا إنا كنا لكم تبعا فهل أنتم مغنون عنا من عذاب الله من شىء  قالوا لو هدىنا الله لهدينكم  سواء علينا أجزعنا أم صبرنا ما لنا من محيص', NULL, 258, 'local:hafs-text.json'),
  ('hafs-14-22', 'hafs', 14, 22, 'وَقَالَ ٱلشَّيْطَٰنُ لَمَّا قُضِىَ ٱلْأَمْرُ إِنَّ ٱللَّهَ وَعَدَكُمْ وَعْدَ ٱلْحَقِّ وَوَعَدتُّكُمْ فَأَخْلَفْتُكُمْ ۖ وَمَا كَانَ لِىَ عَلَيْكُم مِّن سُلْطَٰنٍ إِلَّآ أَن دَعَوْتُكُمْ فَٱسْتَجَبْتُمْ لِى ۖ فَلَا تَلُومُونِى وَلُومُوٓا۟ أَنفُسَكُم ۖ مَّآ أَنَا۠ بِمُصْرِخِكُمْ وَمَآ أَنتُم بِمُصْرِخِىَّ ۖ إِنِّى كَفَرْتُ بِمَآ أَشْرَكْتُمُونِ مِن قَبْلُ ۗ إِنَّ ٱلظَّٰلِمِينَ لَهُمْ عَذَابٌ أَلِيمٌۭ', 'وقال الشيطن لما قضى الأمر إن الله وعدكم وعد الحق ووعدتكم فأخلفتكم  وما كان لى عليكم من سلطن إلا أن دعوتكم فاستجبتم لى  فلا تلومونى ولوموا أنفسكم  ما أنا بمصرخكم وما أنتم بمصرخى  إنى كفرت بما أشركتمون من قبل  إن الظلمين لهم عذاب أليم', NULL, 258, 'local:hafs-text.json'),
  ('hafs-14-23', 'hafs', 14, 23, 'وَأُدْخِلَ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ جَنَّٰتٍۢ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ خَٰلِدِينَ فِيهَا بِإِذْنِ رَبِّهِمْ ۖ تَحِيَّتُهُمْ فِيهَا سَلَٰمٌ', 'وأدخل الذين ءامنوا وعملوا الصلحت جنت تجرى من تحتها الأنهر خلدين فيها بإذن ربهم  تحيتهم فيها سلم', NULL, 258, 'local:hafs-text.json'),
  ('hafs-14-24', 'hafs', 14, 24, 'أَلَمْ تَرَ كَيْفَ ضَرَبَ ٱللَّهُ مَثَلًۭا كَلِمَةًۭ طَيِّبَةًۭ كَشَجَرَةٍۢ طَيِّبَةٍ أَصْلُهَا ثَابِتٌۭ وَفَرْعُهَا فِى ٱلسَّمَآءِ', 'ألم تر كيف ضرب الله مثلا كلمة طيبة كشجرة طيبة أصلها ثابت وفرعها فى السماء', NULL, 258, 'local:hafs-text.json'),
  ('hafs-14-25', 'hafs', 14, 25, 'تُؤْتِىٓ أُكُلَهَا كُلَّ حِينٍۭ بِإِذْنِ رَبِّهَا ۗ وَيَضْرِبُ ٱللَّهُ ٱلْأَمْثَالَ لِلنَّاسِ لَعَلَّهُمْ يَتَذَكَّرُونَ', 'تؤتى أكلها كل حين بإذن ربها  ويضرب الله الأمثال للناس لعلهم يتذكرون', NULL, 259, 'local:hafs-text.json'),
  ('hafs-14-26', 'hafs', 14, 26, 'وَمَثَلُ كَلِمَةٍ خَبِيثَةٍۢ كَشَجَرَةٍ خَبِيثَةٍ ٱجْتُثَّتْ مِن فَوْقِ ٱلْأَرْضِ مَا لَهَا مِن قَرَارٍۢ', 'ومثل كلمة خبيثة كشجرة خبيثة اجتثت من فوق الأرض ما لها من قرار', NULL, 259, 'local:hafs-text.json'),
  ('hafs-14-27', 'hafs', 14, 27, 'يُثَبِّتُ ٱللَّهُ ٱلَّذِينَ ءَامَنُوا۟ بِٱلْقَوْلِ ٱلثَّابِتِ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا وَفِى ٱلْءَاخِرَةِ ۖ وَيُضِلُّ ٱللَّهُ ٱلظَّٰلِمِينَ ۚ وَيَفْعَلُ ٱللَّهُ مَا يَشَآءُ', 'يثبت الله الذين ءامنوا بالقول الثابت فى الحيوة الدنيا وفى الءاخرة  ويضل الله الظلمين  ويفعل الله ما يشاء', NULL, 259, 'local:hafs-text.json'),
  ('hafs-14-28', 'hafs', 14, 28, '۞ أَلَمْ تَرَ إِلَى ٱلَّذِينَ بَدَّلُوا۟ نِعْمَتَ ٱللَّهِ كُفْرًۭا وَأَحَلُّوا۟ قَوْمَهُمْ دَارَ ٱلْبَوَارِ', 'ألم تر إلى الذين بدلوا نعمت الله كفرا وأحلوا قومهم دار البوار', NULL, 259, 'local:hafs-text.json'),
  ('hafs-14-29', 'hafs', 14, 29, 'جَهَنَّمَ يَصْلَوْنَهَا ۖ وَبِئْسَ ٱلْقَرَارُ', 'جهنم يصلونها  وبئس القرار', NULL, 259, 'local:hafs-text.json'),
  ('hafs-14-30', 'hafs', 14, 30, 'وَجَعَلُوا۟ لِلَّهِ أَندَادًۭا لِّيُضِلُّوا۟ عَن سَبِيلِهِۦ ۗ قُلْ تَمَتَّعُوا۟ فَإِنَّ مَصِيرَكُمْ إِلَى ٱلنَّارِ', 'وجعلوا لله أندادا ليضلوا عن سبيله  قل تمتعوا فإن مصيركم إلى النار', NULL, 259, 'local:hafs-text.json'),
  ('hafs-14-31', 'hafs', 14, 31, 'قُل لِّعِبَادِىَ ٱلَّذِينَ ءَامَنُوا۟ يُقِيمُوا۟ ٱلصَّلَوٰةَ وَيُنفِقُوا۟ مِمَّا رَزَقْنَٰهُمْ سِرًّۭا وَعَلَانِيَةًۭ مِّن قَبْلِ أَن يَأْتِىَ يَوْمٌۭ لَّا بَيْعٌۭ فِيهِ وَلَا خِلَٰلٌ', 'قل لعبادى الذين ءامنوا يقيموا الصلوة وينفقوا مما رزقنهم سرا وعلانية من قبل أن يأتى يوم لا بيع فيه ولا خلل', NULL, 259, 'local:hafs-text.json'),
  ('hafs-14-32', 'hafs', 14, 32, 'ٱللَّهُ ٱلَّذِى خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ وَأَنزَلَ مِنَ ٱلسَّمَآءِ مَآءًۭ فَأَخْرَجَ بِهِۦ مِنَ ٱلثَّمَرَٰتِ رِزْقًۭا لَّكُمْ ۖ وَسَخَّرَ لَكُمُ ٱلْفُلْكَ لِتَجْرِىَ فِى ٱلْبَحْرِ بِأَمْرِهِۦ ۖ وَسَخَّرَ لَكُمُ ٱلْأَنْهَٰرَ', 'الله الذى خلق السموت والأرض وأنزل من السماء ماء فأخرج به من الثمرت رزقا لكم  وسخر لكم الفلك لتجرى فى البحر بأمره  وسخر لكم الأنهر', NULL, 259, 'local:hafs-text.json'),
  ('hafs-14-33', 'hafs', 14, 33, 'وَسَخَّرَ لَكُمُ ٱلشَّمْسَ وَٱلْقَمَرَ دَآئِبَيْنِ ۖ وَسَخَّرَ لَكُمُ ٱلَّيْلَ وَٱلنَّهَارَ', 'وسخر لكم الشمس والقمر دائبين  وسخر لكم اليل والنهار', NULL, 259, 'local:hafs-text.json'),
  ('hafs-14-34', 'hafs', 14, 34, 'وَءَاتَىٰكُم مِّن كُلِّ مَا سَأَلْتُمُوهُ ۚ وَإِن تَعُدُّوا۟ نِعْمَتَ ٱللَّهِ لَا تُحْصُوهَآ ۗ إِنَّ ٱلْإِنسَٰنَ لَظَلُومٌۭ كَفَّارٌۭ', 'وءاتىكم من كل ما سألتموه  وإن تعدوا نعمت الله لا تحصوها  إن الإنسن لظلوم كفار', NULL, 260, 'local:hafs-text.json'),
  ('hafs-14-35', 'hafs', 14, 35, 'وَإِذْ قَالَ إِبْرَٰهِيمُ رَبِّ ٱجْعَلْ هَٰذَا ٱلْبَلَدَ ءَامِنًۭا وَٱجْنُبْنِى وَبَنِىَّ أَن نَّعْبُدَ ٱلْأَصْنَامَ', 'وإذ قال إبرهيم رب اجعل هذا البلد ءامنا واجنبنى وبنى أن نعبد الأصنام', NULL, 260, 'local:hafs-text.json'),
  ('hafs-14-36', 'hafs', 14, 36, 'رَبِّ إِنَّهُنَّ أَضْلَلْنَ كَثِيرًۭا مِّنَ ٱلنَّاسِ ۖ فَمَن تَبِعَنِى فَإِنَّهُۥ مِنِّى ۖ وَمَنْ عَصَانِى فَإِنَّكَ غَفُورٌۭ رَّحِيمٌۭ', 'رب إنهن أضللن كثيرا من الناس  فمن تبعنى فإنه منى  ومن عصانى فإنك غفور رحيم', NULL, 260, 'local:hafs-text.json'),
  ('hafs-14-37', 'hafs', 14, 37, 'رَّبَّنَآ إِنِّىٓ أَسْكَنتُ مِن ذُرِّيَّتِى بِوَادٍ غَيْرِ ذِى زَرْعٍ عِندَ بَيْتِكَ ٱلْمُحَرَّمِ رَبَّنَا لِيُقِيمُوا۟ ٱلصَّلَوٰةَ فَٱجْعَلْ أَفْـِٔدَةًۭ مِّنَ ٱلنَّاسِ تَهْوِىٓ إِلَيْهِمْ وَٱرْزُقْهُم مِّنَ ٱلثَّمَرَٰتِ لَعَلَّهُمْ يَشْكُرُونَ', 'ربنا إنى أسكنت من ذريتى بواد غير ذى زرع عند بيتك المحرم ربنا ليقيموا الصلوة فاجعل أفدة من الناس تهوى إليهم وارزقهم من الثمرت لعلهم يشكرون', NULL, 260, 'local:hafs-text.json'),
  ('hafs-14-38', 'hafs', 14, 38, 'رَبَّنَآ إِنَّكَ تَعْلَمُ مَا نُخْفِى وَمَا نُعْلِنُ ۗ وَمَا يَخْفَىٰ عَلَى ٱللَّهِ مِن شَىْءٍۢ فِى ٱلْأَرْضِ وَلَا فِى ٱلسَّمَآءِ', 'ربنا إنك تعلم ما نخفى وما نعلن  وما يخفى على الله من شىء فى الأرض ولا فى السماء', NULL, 260, 'local:hafs-text.json'),
  ('hafs-14-39', 'hafs', 14, 39, 'ٱلْحَمْدُ لِلَّهِ ٱلَّذِى وَهَبَ لِى عَلَى ٱلْكِبَرِ إِسْمَٰعِيلَ وَإِسْحَٰقَ ۚ إِنَّ رَبِّى لَسَمِيعُ ٱلدُّعَآءِ', 'الحمد لله الذى وهب لى على الكبر إسمعيل وإسحق  إن ربى لسميع الدعاء', NULL, 260, 'local:hafs-text.json'),
  ('hafs-14-40', 'hafs', 14, 40, 'رَبِّ ٱجْعَلْنِى مُقِيمَ ٱلصَّلَوٰةِ وَمِن ذُرِّيَّتِى ۚ رَبَّنَا وَتَقَبَّلْ دُعَآءِ', 'رب اجعلنى مقيم الصلوة ومن ذريتى  ربنا وتقبل دعاء', NULL, 260, 'local:hafs-text.json'),
  ('hafs-14-41', 'hafs', 14, 41, 'رَبَّنَا ٱغْفِرْ لِى وَلِوَٰلِدَىَّ وَلِلْمُؤْمِنِينَ يَوْمَ يَقُومُ ٱلْحِسَابُ', 'ربنا اغفر لى ولولدى وللمؤمنين يوم يقوم الحساب', NULL, 260, 'local:hafs-text.json'),
  ('hafs-14-42', 'hafs', 14, 42, 'وَلَا تَحْسَبَنَّ ٱللَّهَ غَٰفِلًا عَمَّا يَعْمَلُ ٱلظَّٰلِمُونَ ۚ إِنَّمَا يُؤَخِّرُهُمْ لِيَوْمٍۢ تَشْخَصُ فِيهِ ٱلْأَبْصَٰرُ', 'ولا تحسبن الله غفلا عما يعمل الظلمون  إنما يؤخرهم ليوم تشخص فيه الأبصر', NULL, 260, 'local:hafs-text.json'),
  ('hafs-14-43', 'hafs', 14, 43, 'مُهْطِعِينَ مُقْنِعِى رُءُوسِهِمْ لَا يَرْتَدُّ إِلَيْهِمْ طَرْفُهُمْ ۖ وَأَفْـِٔدَتُهُمْ هَوَآءٌۭ', 'مهطعين مقنعى رءوسهم لا يرتد إليهم طرفهم  وأفدتهم هواء', NULL, 261, 'local:hafs-text.json'),
  ('hafs-14-44', 'hafs', 14, 44, 'وَأَنذِرِ ٱلنَّاسَ يَوْمَ يَأْتِيهِمُ ٱلْعَذَابُ فَيَقُولُ ٱلَّذِينَ ظَلَمُوا۟ رَبَّنَآ أَخِّرْنَآ إِلَىٰٓ أَجَلٍۢ قَرِيبٍۢ نُّجِبْ دَعْوَتَكَ وَنَتَّبِعِ ٱلرُّسُلَ ۗ أَوَلَمْ تَكُونُوٓا۟ أَقْسَمْتُم مِّن قَبْلُ مَا لَكُم مِّن زَوَالٍۢ', 'وأنذر الناس يوم يأتيهم العذاب فيقول الذين ظلموا ربنا أخرنا إلى أجل قريب نجب دعوتك ونتبع الرسل  أولم تكونوا أقسمتم من قبل ما لكم من زوال', NULL, 261, 'local:hafs-text.json'),
  ('hafs-14-45', 'hafs', 14, 45, 'وَسَكَنتُمْ فِى مَسَٰكِنِ ٱلَّذِينَ ظَلَمُوٓا۟ أَنفُسَهُمْ وَتَبَيَّنَ لَكُمْ كَيْفَ فَعَلْنَا بِهِمْ وَضَرَبْنَا لَكُمُ ٱلْأَمْثَالَ', 'وسكنتم فى مسكن الذين ظلموا أنفسهم وتبين لكم كيف فعلنا بهم وضربنا لكم الأمثال', NULL, 261, 'local:hafs-text.json'),
  ('hafs-14-46', 'hafs', 14, 46, 'وَقَدْ مَكَرُوا۟ مَكْرَهُمْ وَعِندَ ٱللَّهِ مَكْرُهُمْ وَإِن كَانَ مَكْرُهُمْ لِتَزُولَ مِنْهُ ٱلْجِبَالُ', 'وقد مكروا مكرهم وعند الله مكرهم وإن كان مكرهم لتزول منه الجبال', NULL, 261, 'local:hafs-text.json'),
  ('hafs-14-47', 'hafs', 14, 47, 'فَلَا تَحْسَبَنَّ ٱللَّهَ مُخْلِفَ وَعْدِهِۦ رُسُلَهُۥٓ ۗ إِنَّ ٱللَّهَ عَزِيزٌۭ ذُو ٱنتِقَامٍۢ', 'فلا تحسبن الله مخلف وعده رسله  إن الله عزيز ذو انتقام', NULL, 261, 'local:hafs-text.json'),
  ('hafs-14-48', 'hafs', 14, 48, 'يَوْمَ تُبَدَّلُ ٱلْأَرْضُ غَيْرَ ٱلْأَرْضِ وَٱلسَّمَٰوَٰتُ ۖ وَبَرَزُوا۟ لِلَّهِ ٱلْوَٰحِدِ ٱلْقَهَّارِ', 'يوم تبدل الأرض غير الأرض والسموت  وبرزوا لله الوحد القهار', NULL, 261, 'local:hafs-text.json'),
  ('hafs-14-49', 'hafs', 14, 49, 'وَتَرَى ٱلْمُجْرِمِينَ يَوْمَئِذٍۢ مُّقَرَّنِينَ فِى ٱلْأَصْفَادِ', 'وترى المجرمين يومئذ مقرنين فى الأصفاد', NULL, 261, 'local:hafs-text.json'),
  ('hafs-14-50', 'hafs', 14, 50, 'سَرَابِيلُهُم مِّن قَطِرَانٍۢ وَتَغْشَىٰ وُجُوهَهُمُ ٱلنَّارُ', 'سرابيلهم من قطران وتغشى وجوههم النار', NULL, 261, 'local:hafs-text.json'),
  ('hafs-14-51', 'hafs', 14, 51, 'لِيَجْزِىَ ٱللَّهُ كُلَّ نَفْسٍۢ مَّا كَسَبَتْ ۚ إِنَّ ٱللَّهَ سَرِيعُ ٱلْحِسَابِ', 'ليجزى الله كل نفس ما كسبت  إن الله سريع الحساب', NULL, 261, 'local:hafs-text.json'),
  ('hafs-14-52', 'hafs', 14, 52, 'هَٰذَا بَلَٰغٌۭ لِّلنَّاسِ وَلِيُنذَرُوا۟ بِهِۦ وَلِيَعْلَمُوٓا۟ أَنَّمَا هُوَ إِلَٰهٌۭ وَٰحِدٌۭ وَلِيَذَّكَّرَ أُو۟لُوا۟ ٱلْأَلْبَٰبِ', 'هذا بلغ للناس ولينذروا به وليعلموا أنما هو إله وحد وليذكر أولوا الألبب', NULL, 261, 'local:hafs-text.json'),
  ('hafs-15-1', 'hafs', 15, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ الٓر ۚ تِلْكَ ءَايَٰتُ ٱلْكِتَٰبِ وَقُرْءَانٍۢ مُّبِينٍۢ', 'بسم الله الرحمن الرحيم الر  تلك ءايت الكتب وقرءان مبين', NULL, 262, 'local:hafs-text.json'),
  ('hafs-15-2', 'hafs', 15, 2, 'رُّبَمَا يَوَدُّ ٱلَّذِينَ كَفَرُوا۟ لَوْ كَانُوا۟ مُسْلِمِينَ', 'ربما يود الذين كفروا لو كانوا مسلمين', NULL, 262, 'local:hafs-text.json'),
  ('hafs-15-3', 'hafs', 15, 3, 'ذَرْهُمْ يَأْكُلُوا۟ وَيَتَمَتَّعُوا۟ وَيُلْهِهِمُ ٱلْأَمَلُ ۖ فَسَوْفَ يَعْلَمُونَ', 'ذرهم يأكلوا ويتمتعوا ويلههم الأمل  فسوف يعلمون', NULL, 262, 'local:hafs-text.json'),
  ('hafs-15-4', 'hafs', 15, 4, 'وَمَآ أَهْلَكْنَا مِن قَرْيَةٍ إِلَّا وَلَهَا كِتَابٌۭ مَّعْلُومٌۭ', 'وما أهلكنا من قرية إلا ولها كتاب معلوم', NULL, 262, 'local:hafs-text.json'),
  ('hafs-15-5', 'hafs', 15, 5, 'مَّا تَسْبِقُ مِنْ أُمَّةٍ أَجَلَهَا وَمَا يَسْتَـْٔخِرُونَ', 'ما تسبق من أمة أجلها وما يستخرون', NULL, 262, 'local:hafs-text.json'),
  ('hafs-15-6', 'hafs', 15, 6, 'وَقَالُوا۟ يَٰٓأَيُّهَا ٱلَّذِى نُزِّلَ عَلَيْهِ ٱلذِّكْرُ إِنَّكَ لَمَجْنُونٌۭ', 'وقالوا يأيها الذى نزل عليه الذكر إنك لمجنون', NULL, 262, 'local:hafs-text.json'),
  ('hafs-15-7', 'hafs', 15, 7, 'لَّوْ مَا تَأْتِينَا بِٱلْمَلَٰٓئِكَةِ إِن كُنتَ مِنَ ٱلصَّٰدِقِينَ', 'لو ما تأتينا بالملئكة إن كنت من الصدقين', NULL, 262, 'local:hafs-text.json'),
  ('hafs-15-8', 'hafs', 15, 8, 'مَا نُنَزِّلُ ٱلْمَلَٰٓئِكَةَ إِلَّا بِٱلْحَقِّ وَمَا كَانُوٓا۟ إِذًۭا مُّنظَرِينَ', 'ما ننزل الملئكة إلا بالحق وما كانوا إذا منظرين', NULL, 262, 'local:hafs-text.json'),
  ('hafs-15-9', 'hafs', 15, 9, 'إِنَّا نَحْنُ نَزَّلْنَا ٱلذِّكْرَ وَإِنَّا لَهُۥ لَحَٰفِظُونَ', 'إنا نحن نزلنا الذكر وإنا له لحفظون', NULL, 262, 'local:hafs-text.json'),
  ('hafs-15-10', 'hafs', 15, 10, 'وَلَقَدْ أَرْسَلْنَا مِن قَبْلِكَ فِى شِيَعِ ٱلْأَوَّلِينَ', 'ولقد أرسلنا من قبلك فى شيع الأولين', NULL, 262, 'local:hafs-text.json'),
  ('hafs-15-11', 'hafs', 15, 11, 'وَمَا يَأْتِيهِم مِّن رَّسُولٍ إِلَّا كَانُوا۟ بِهِۦ يَسْتَهْزِءُونَ', 'وما يأتيهم من رسول إلا كانوا به يستهزءون', NULL, 262, 'local:hafs-text.json'),
  ('hafs-15-12', 'hafs', 15, 12, 'كَذَٰلِكَ نَسْلُكُهُۥ فِى قُلُوبِ ٱلْمُجْرِمِينَ', 'كذلك نسلكه فى قلوب المجرمين', NULL, 262, 'local:hafs-text.json'),
  ('hafs-15-13', 'hafs', 15, 13, 'لَا يُؤْمِنُونَ بِهِۦ ۖ وَقَدْ خَلَتْ سُنَّةُ ٱلْأَوَّلِينَ', 'لا يؤمنون به  وقد خلت سنة الأولين', NULL, 262, 'local:hafs-text.json'),
  ('hafs-15-14', 'hafs', 15, 14, 'وَلَوْ فَتَحْنَا عَلَيْهِم بَابًۭا مِّنَ ٱلسَّمَآءِ فَظَلُّوا۟ فِيهِ يَعْرُجُونَ', 'ولو فتحنا عليهم بابا من السماء فظلوا فيه يعرجون', NULL, 262, 'local:hafs-text.json'),
  ('hafs-15-15', 'hafs', 15, 15, 'لَقَالُوٓا۟ إِنَّمَا سُكِّرَتْ أَبْصَٰرُنَا بَلْ نَحْنُ قَوْمٌۭ مَّسْحُورُونَ', 'لقالوا إنما سكرت أبصرنا بل نحن قوم مسحورون', NULL, 262, 'local:hafs-text.json'),
  ('hafs-15-16', 'hafs', 15, 16, 'وَلَقَدْ جَعَلْنَا فِى ٱلسَّمَآءِ بُرُوجًۭا وَزَيَّنَّٰهَا لِلنَّٰظِرِينَ', 'ولقد جعلنا فى السماء بروجا وزينها للنظرين', NULL, 263, 'local:hafs-text.json'),
  ('hafs-15-17', 'hafs', 15, 17, 'وَحَفِظْنَٰهَا مِن كُلِّ شَيْطَٰنٍۢ رَّجِيمٍ', 'وحفظنها من كل شيطن رجيم', NULL, 263, 'local:hafs-text.json'),
  ('hafs-15-18', 'hafs', 15, 18, 'إِلَّا مَنِ ٱسْتَرَقَ ٱلسَّمْعَ فَأَتْبَعَهُۥ شِهَابٌۭ مُّبِينٌۭ', 'إلا من استرق السمع فأتبعه شهاب مبين', NULL, 263, 'local:hafs-text.json'),
  ('hafs-15-19', 'hafs', 15, 19, 'وَٱلْأَرْضَ مَدَدْنَٰهَا وَأَلْقَيْنَا فِيهَا رَوَٰسِىَ وَأَنۢبَتْنَا فِيهَا مِن كُلِّ شَىْءٍۢ مَّوْزُونٍۢ', 'والأرض مددنها وألقينا فيها روسى وأنبتنا فيها من كل شىء موزون', NULL, 263, 'local:hafs-text.json'),
  ('hafs-15-20', 'hafs', 15, 20, 'وَجَعَلْنَا لَكُمْ فِيهَا مَعَٰيِشَ وَمَن لَّسْتُمْ لَهُۥ بِرَٰزِقِينَ', 'وجعلنا لكم فيها معيش ومن لستم له برزقين', NULL, 263, 'local:hafs-text.json'),
  ('hafs-15-21', 'hafs', 15, 21, 'وَإِن مِّن شَىْءٍ إِلَّا عِندَنَا خَزَآئِنُهُۥ وَمَا نُنَزِّلُهُۥٓ إِلَّا بِقَدَرٍۢ مَّعْلُومٍۢ', 'وإن من شىء إلا عندنا خزائنه وما ننزله إلا بقدر معلوم', NULL, 263, 'local:hafs-text.json'),
  ('hafs-15-22', 'hafs', 15, 22, 'وَأَرْسَلْنَا ٱلرِّيَٰحَ لَوَٰقِحَ فَأَنزَلْنَا مِنَ ٱلسَّمَآءِ مَآءًۭ فَأَسْقَيْنَٰكُمُوهُ وَمَآ أَنتُمْ لَهُۥ بِخَٰزِنِينَ', 'وأرسلنا الريح لوقح فأنزلنا من السماء ماء فأسقينكموه وما أنتم له بخزنين', NULL, 263, 'local:hafs-text.json'),
  ('hafs-15-23', 'hafs', 15, 23, 'وَإِنَّا لَنَحْنُ نُحْىِۦ وَنُمِيتُ وَنَحْنُ ٱلْوَٰرِثُونَ', 'وإنا لنحن نحى ونميت ونحن الورثون', NULL, 263, 'local:hafs-text.json'),
  ('hafs-15-24', 'hafs', 15, 24, 'وَلَقَدْ عَلِمْنَا ٱلْمُسْتَقْدِمِينَ مِنكُمْ وَلَقَدْ عَلِمْنَا ٱلْمُسْتَـْٔخِرِينَ', 'ولقد علمنا المستقدمين منكم ولقد علمنا المستخرين', NULL, 263, 'local:hafs-text.json'),
  ('hafs-15-25', 'hafs', 15, 25, 'وَإِنَّ رَبَّكَ هُوَ يَحْشُرُهُمْ ۚ إِنَّهُۥ حَكِيمٌ عَلِيمٌۭ', 'وإن ربك هو يحشرهم  إنه حكيم عليم', NULL, 263, 'local:hafs-text.json'),
  ('hafs-15-26', 'hafs', 15, 26, 'وَلَقَدْ خَلَقْنَا ٱلْإِنسَٰنَ مِن صَلْصَٰلٍۢ مِّنْ حَمَإٍۢ مَّسْنُونٍۢ', 'ولقد خلقنا الإنسن من صلصل من حمإ مسنون', NULL, 263, 'local:hafs-text.json'),
  ('hafs-15-27', 'hafs', 15, 27, 'وَٱلْجَآنَّ خَلَقْنَٰهُ مِن قَبْلُ مِن نَّارِ ٱلسَّمُومِ', 'والجان خلقنه من قبل من نار السموم', NULL, 263, 'local:hafs-text.json'),
  ('hafs-15-28', 'hafs', 15, 28, 'وَإِذْ قَالَ رَبُّكَ لِلْمَلَٰٓئِكَةِ إِنِّى خَٰلِقٌۢ بَشَرًۭا مِّن صَلْصَٰلٍۢ مِّنْ حَمَإٍۢ مَّسْنُونٍۢ', 'وإذ قال ربك للملئكة إنى خلق بشرا من صلصل من حمإ مسنون', NULL, 263, 'local:hafs-text.json'),
  ('hafs-15-29', 'hafs', 15, 29, 'فَإِذَا سَوَّيْتُهُۥ وَنَفَخْتُ فِيهِ مِن رُّوحِى فَقَعُوا۟ لَهُۥ سَٰجِدِينَ', 'فإذا سويته ونفخت فيه من روحى فقعوا له سجدين', NULL, 263, 'local:hafs-text.json'),
  ('hafs-15-30', 'hafs', 15, 30, 'فَسَجَدَ ٱلْمَلَٰٓئِكَةُ كُلُّهُمْ أَجْمَعُونَ', 'فسجد الملئكة كلهم أجمعون', NULL, 263, 'local:hafs-text.json'),
  ('hafs-15-31', 'hafs', 15, 31, 'إِلَّآ إِبْلِيسَ أَبَىٰٓ أَن يَكُونَ مَعَ ٱلسَّٰجِدِينَ', 'إلا إبليس أبى أن يكون مع السجدين', NULL, 263, 'local:hafs-text.json'),
  ('hafs-15-32', 'hafs', 15, 32, 'قَالَ يَٰٓإِبْلِيسُ مَا لَكَ أَلَّا تَكُونَ مَعَ ٱلسَّٰجِدِينَ', 'قال يإبليس ما لك ألا تكون مع السجدين', NULL, 264, 'local:hafs-text.json'),
  ('hafs-15-33', 'hafs', 15, 33, 'قَالَ لَمْ أَكُن لِّأَسْجُدَ لِبَشَرٍ خَلَقْتَهُۥ مِن صَلْصَٰلٍۢ مِّنْ حَمَإٍۢ مَّسْنُونٍۢ', 'قال لم أكن لأسجد لبشر خلقته من صلصل من حمإ مسنون', NULL, 264, 'local:hafs-text.json'),
  ('hafs-15-34', 'hafs', 15, 34, 'قَالَ فَٱخْرُجْ مِنْهَا فَإِنَّكَ رَجِيمٌۭ', 'قال فاخرج منها فإنك رجيم', NULL, 264, 'local:hafs-text.json'),
  ('hafs-15-35', 'hafs', 15, 35, 'وَإِنَّ عَلَيْكَ ٱللَّعْنَةَ إِلَىٰ يَوْمِ ٱلدِّينِ', 'وإن عليك اللعنة إلى يوم الدين', NULL, 264, 'local:hafs-text.json'),
  ('hafs-15-36', 'hafs', 15, 36, 'قَالَ رَبِّ فَأَنظِرْنِىٓ إِلَىٰ يَوْمِ يُبْعَثُونَ', 'قال رب فأنظرنى إلى يوم يبعثون', NULL, 264, 'local:hafs-text.json'),
  ('hafs-15-37', 'hafs', 15, 37, 'قَالَ فَإِنَّكَ مِنَ ٱلْمُنظَرِينَ', 'قال فإنك من المنظرين', NULL, 264, 'local:hafs-text.json'),
  ('hafs-15-38', 'hafs', 15, 38, 'إِلَىٰ يَوْمِ ٱلْوَقْتِ ٱلْمَعْلُومِ', 'إلى يوم الوقت المعلوم', NULL, 264, 'local:hafs-text.json'),
  ('hafs-15-39', 'hafs', 15, 39, 'قَالَ رَبِّ بِمَآ أَغْوَيْتَنِى لَأُزَيِّنَنَّ لَهُمْ فِى ٱلْأَرْضِ وَلَأُغْوِيَنَّهُمْ أَجْمَعِينَ', 'قال رب بما أغويتنى لأزينن لهم فى الأرض ولأغوينهم أجمعين', NULL, 264, 'local:hafs-text.json'),
  ('hafs-15-40', 'hafs', 15, 40, 'إِلَّا عِبَادَكَ مِنْهُمُ ٱلْمُخْلَصِينَ', 'إلا عبادك منهم المخلصين', NULL, 264, 'local:hafs-text.json'),
  ('hafs-15-41', 'hafs', 15, 41, 'قَالَ هَٰذَا صِرَٰطٌ عَلَىَّ مُسْتَقِيمٌ', 'قال هذا صرط على مستقيم', NULL, 264, 'local:hafs-text.json'),
  ('hafs-15-42', 'hafs', 15, 42, 'إِنَّ عِبَادِى لَيْسَ لَكَ عَلَيْهِمْ سُلْطَٰنٌ إِلَّا مَنِ ٱتَّبَعَكَ مِنَ ٱلْغَاوِينَ', 'إن عبادى ليس لك عليهم سلطن إلا من اتبعك من الغاوين', NULL, 264, 'local:hafs-text.json'),
  ('hafs-15-43', 'hafs', 15, 43, 'وَإِنَّ جَهَنَّمَ لَمَوْعِدُهُمْ أَجْمَعِينَ', 'وإن جهنم لموعدهم أجمعين', NULL, 264, 'local:hafs-text.json'),
  ('hafs-15-44', 'hafs', 15, 44, 'لَهَا سَبْعَةُ أَبْوَٰبٍۢ لِّكُلِّ بَابٍۢ مِّنْهُمْ جُزْءٌۭ مَّقْسُومٌ', 'لها سبعة أبوب لكل باب منهم جزء مقسوم', NULL, 264, 'local:hafs-text.json'),
  ('hafs-15-45', 'hafs', 15, 45, 'إِنَّ ٱلْمُتَّقِينَ فِى جَنَّٰتٍۢ وَعُيُونٍ', 'إن المتقين فى جنت وعيون', NULL, 264, 'local:hafs-text.json'),
  ('hafs-15-46', 'hafs', 15, 46, 'ٱدْخُلُوهَا بِسَلَٰمٍ ءَامِنِينَ', 'ادخلوها بسلم ءامنين', NULL, 264, 'local:hafs-text.json'),
  ('hafs-15-47', 'hafs', 15, 47, 'وَنَزَعْنَا مَا فِى صُدُورِهِم مِّنْ غِلٍّ إِخْوَٰنًا عَلَىٰ سُرُرٍۢ مُّتَقَٰبِلِينَ', 'ونزعنا ما فى صدورهم من غل إخونا على سرر متقبلين', NULL, 264, 'local:hafs-text.json'),
  ('hafs-15-48', 'hafs', 15, 48, 'لَا يَمَسُّهُمْ فِيهَا نَصَبٌۭ وَمَا هُم مِّنْهَا بِمُخْرَجِينَ', 'لا يمسهم فيها نصب وما هم منها بمخرجين', NULL, 264, 'local:hafs-text.json'),
  ('hafs-15-49', 'hafs', 15, 49, '۞ نَبِّئْ عِبَادِىٓ أَنِّىٓ أَنَا ٱلْغَفُورُ ٱلرَّحِيمُ', 'نبئ عبادى أنى أنا الغفور الرحيم', NULL, 264, 'local:hafs-text.json'),
  ('hafs-15-50', 'hafs', 15, 50, 'وَأَنَّ عَذَابِى هُوَ ٱلْعَذَابُ ٱلْأَلِيمُ', 'وأن عذابى هو العذاب الأليم', NULL, 264, 'local:hafs-text.json'),
  ('hafs-15-51', 'hafs', 15, 51, 'وَنَبِّئْهُمْ عَن ضَيْفِ إِبْرَٰهِيمَ', 'ونبئهم عن ضيف إبرهيم', NULL, 264, 'local:hafs-text.json'),
  ('hafs-15-52', 'hafs', 15, 52, 'إِذْ دَخَلُوا۟ عَلَيْهِ فَقَالُوا۟ سَلَٰمًۭا قَالَ إِنَّا مِنكُمْ وَجِلُونَ', 'إذ دخلوا عليه فقالوا سلما قال إنا منكم وجلون', NULL, 265, 'local:hafs-text.json'),
  ('hafs-15-53', 'hafs', 15, 53, 'قَالُوا۟ لَا تَوْجَلْ إِنَّا نُبَشِّرُكَ بِغُلَٰمٍ عَلِيمٍۢ', 'قالوا لا توجل إنا نبشرك بغلم عليم', NULL, 265, 'local:hafs-text.json'),
  ('hafs-15-54', 'hafs', 15, 54, 'قَالَ أَبَشَّرْتُمُونِى عَلَىٰٓ أَن مَّسَّنِىَ ٱلْكِبَرُ فَبِمَ تُبَشِّرُونَ', 'قال أبشرتمونى على أن مسنى الكبر فبم تبشرون', NULL, 265, 'local:hafs-text.json'),
  ('hafs-15-55', 'hafs', 15, 55, 'قَالُوا۟ بَشَّرْنَٰكَ بِٱلْحَقِّ فَلَا تَكُن مِّنَ ٱلْقَٰنِطِينَ', 'قالوا بشرنك بالحق فلا تكن من القنطين', NULL, 265, 'local:hafs-text.json'),
  ('hafs-15-56', 'hafs', 15, 56, 'قَالَ وَمَن يَقْنَطُ مِن رَّحْمَةِ رَبِّهِۦٓ إِلَّا ٱلضَّآلُّونَ', 'قال ومن يقنط من رحمة ربه إلا الضالون', NULL, 265, 'local:hafs-text.json'),
  ('hafs-15-57', 'hafs', 15, 57, 'قَالَ فَمَا خَطْبُكُمْ أَيُّهَا ٱلْمُرْسَلُونَ', 'قال فما خطبكم أيها المرسلون', NULL, 265, 'local:hafs-text.json'),
  ('hafs-15-58', 'hafs', 15, 58, 'قَالُوٓا۟ إِنَّآ أُرْسِلْنَآ إِلَىٰ قَوْمٍۢ مُّجْرِمِينَ', 'قالوا إنا أرسلنا إلى قوم مجرمين', NULL, 265, 'local:hafs-text.json'),
  ('hafs-15-59', 'hafs', 15, 59, 'إِلَّآ ءَالَ لُوطٍ إِنَّا لَمُنَجُّوهُمْ أَجْمَعِينَ', 'إلا ءال لوط إنا لمنجوهم أجمعين', NULL, 265, 'local:hafs-text.json'),
  ('hafs-15-60', 'hafs', 15, 60, 'إِلَّا ٱمْرَأَتَهُۥ قَدَّرْنَآ ۙ إِنَّهَا لَمِنَ ٱلْغَٰبِرِينَ', 'إلا امرأته قدرنا  إنها لمن الغبرين', NULL, 265, 'local:hafs-text.json'),
  ('hafs-15-61', 'hafs', 15, 61, 'فَلَمَّا جَآءَ ءَالَ لُوطٍ ٱلْمُرْسَلُونَ', 'فلما جاء ءال لوط المرسلون', NULL, 265, 'local:hafs-text.json'),
  ('hafs-15-62', 'hafs', 15, 62, 'قَالَ إِنَّكُمْ قَوْمٌۭ مُّنكَرُونَ', 'قال إنكم قوم منكرون', NULL, 265, 'local:hafs-text.json'),
  ('hafs-15-63', 'hafs', 15, 63, 'قَالُوا۟ بَلْ جِئْنَٰكَ بِمَا كَانُوا۟ فِيهِ يَمْتَرُونَ', 'قالوا بل جئنك بما كانوا فيه يمترون', NULL, 265, 'local:hafs-text.json'),
  ('hafs-15-64', 'hafs', 15, 64, 'وَأَتَيْنَٰكَ بِٱلْحَقِّ وَإِنَّا لَصَٰدِقُونَ', 'وأتينك بالحق وإنا لصدقون', NULL, 265, 'local:hafs-text.json'),
  ('hafs-15-65', 'hafs', 15, 65, 'فَأَسْرِ بِأَهْلِكَ بِقِطْعٍۢ مِّنَ ٱلَّيْلِ وَٱتَّبِعْ أَدْبَٰرَهُمْ وَلَا يَلْتَفِتْ مِنكُمْ أَحَدٌۭ وَٱمْضُوا۟ حَيْثُ تُؤْمَرُونَ', 'فأسر بأهلك بقطع من اليل واتبع أدبرهم ولا يلتفت منكم أحد وامضوا حيث تؤمرون', NULL, 265, 'local:hafs-text.json'),
  ('hafs-15-66', 'hafs', 15, 66, 'وَقَضَيْنَآ إِلَيْهِ ذَٰلِكَ ٱلْأَمْرَ أَنَّ دَابِرَ هَٰٓؤُلَآءِ مَقْطُوعٌۭ مُّصْبِحِينَ', 'وقضينا إليه ذلك الأمر أن دابر هؤلاء مقطوع مصبحين', NULL, 265, 'local:hafs-text.json'),
  ('hafs-15-67', 'hafs', 15, 67, 'وَجَآءَ أَهْلُ ٱلْمَدِينَةِ يَسْتَبْشِرُونَ', 'وجاء أهل المدينة يستبشرون', NULL, 265, 'local:hafs-text.json'),
  ('hafs-15-68', 'hafs', 15, 68, 'قَالَ إِنَّ هَٰٓؤُلَآءِ ضَيْفِى فَلَا تَفْضَحُونِ', 'قال إن هؤلاء ضيفى فلا تفضحون', NULL, 265, 'local:hafs-text.json'),
  ('hafs-15-69', 'hafs', 15, 69, 'وَٱتَّقُوا۟ ٱللَّهَ وَلَا تُخْزُونِ', 'واتقوا الله ولا تخزون', NULL, 265, 'local:hafs-text.json'),
  ('hafs-15-70', 'hafs', 15, 70, 'قَالُوٓا۟ أَوَلَمْ نَنْهَكَ عَنِ ٱلْعَٰلَمِينَ', 'قالوا أولم ننهك عن العلمين', NULL, 265, 'local:hafs-text.json'),
  ('hafs-15-71', 'hafs', 15, 71, 'قَالَ هَٰٓؤُلَآءِ بَنَاتِىٓ إِن كُنتُمْ فَٰعِلِينَ', 'قال هؤلاء بناتى إن كنتم فعلين', NULL, 266, 'local:hafs-text.json'),
  ('hafs-15-72', 'hafs', 15, 72, 'لَعَمْرُكَ إِنَّهُمْ لَفِى سَكْرَتِهِمْ يَعْمَهُونَ', 'لعمرك إنهم لفى سكرتهم يعمهون', NULL, 266, 'local:hafs-text.json'),
  ('hafs-15-73', 'hafs', 15, 73, 'فَأَخَذَتْهُمُ ٱلصَّيْحَةُ مُشْرِقِينَ', 'فأخذتهم الصيحة مشرقين', NULL, 266, 'local:hafs-text.json'),
  ('hafs-15-74', 'hafs', 15, 74, 'فَجَعَلْنَا عَٰلِيَهَا سَافِلَهَا وَأَمْطَرْنَا عَلَيْهِمْ حِجَارَةًۭ مِّن سِجِّيلٍ', 'فجعلنا عليها سافلها وأمطرنا عليهم حجارة من سجيل', NULL, 266, 'local:hafs-text.json'),
  ('hafs-15-75', 'hafs', 15, 75, 'إِنَّ فِى ذَٰلِكَ لَءَايَٰتٍۢ لِّلْمُتَوَسِّمِينَ', 'إن فى ذلك لءايت للمتوسمين', NULL, 266, 'local:hafs-text.json'),
  ('hafs-15-76', 'hafs', 15, 76, 'وَإِنَّهَا لَبِسَبِيلٍۢ مُّقِيمٍ', 'وإنها لبسبيل مقيم', NULL, 266, 'local:hafs-text.json'),
  ('hafs-15-77', 'hafs', 15, 77, 'إِنَّ فِى ذَٰلِكَ لَءَايَةًۭ لِّلْمُؤْمِنِينَ', 'إن فى ذلك لءاية للمؤمنين', NULL, 266, 'local:hafs-text.json'),
  ('hafs-15-78', 'hafs', 15, 78, 'وَإِن كَانَ أَصْحَٰبُ ٱلْأَيْكَةِ لَظَٰلِمِينَ', 'وإن كان أصحب الأيكة لظلمين', NULL, 266, 'local:hafs-text.json'),
  ('hafs-15-79', 'hafs', 15, 79, 'فَٱنتَقَمْنَا مِنْهُمْ وَإِنَّهُمَا لَبِإِمَامٍۢ مُّبِينٍۢ', 'فانتقمنا منهم وإنهما لبإمام مبين', NULL, 266, 'local:hafs-text.json'),
  ('hafs-15-80', 'hafs', 15, 80, 'وَلَقَدْ كَذَّبَ أَصْحَٰبُ ٱلْحِجْرِ ٱلْمُرْسَلِينَ', 'ولقد كذب أصحب الحجر المرسلين', NULL, 266, 'local:hafs-text.json'),
  ('hafs-15-81', 'hafs', 15, 81, 'وَءَاتَيْنَٰهُمْ ءَايَٰتِنَا فَكَانُوا۟ عَنْهَا مُعْرِضِينَ', 'وءاتينهم ءايتنا فكانوا عنها معرضين', NULL, 266, 'local:hafs-text.json'),
  ('hafs-15-82', 'hafs', 15, 82, 'وَكَانُوا۟ يَنْحِتُونَ مِنَ ٱلْجِبَالِ بُيُوتًا ءَامِنِينَ', 'وكانوا ينحتون من الجبال بيوتا ءامنين', NULL, 266, 'local:hafs-text.json'),
  ('hafs-15-83', 'hafs', 15, 83, 'فَأَخَذَتْهُمُ ٱلصَّيْحَةُ مُصْبِحِينَ', 'فأخذتهم الصيحة مصبحين', NULL, 266, 'local:hafs-text.json'),
  ('hafs-15-84', 'hafs', 15, 84, 'فَمَآ أَغْنَىٰ عَنْهُم مَّا كَانُوا۟ يَكْسِبُونَ', 'فما أغنى عنهم ما كانوا يكسبون', NULL, 266, 'local:hafs-text.json'),
  ('hafs-15-85', 'hafs', 15, 85, 'وَمَا خَلَقْنَا ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ وَمَا بَيْنَهُمَآ إِلَّا بِٱلْحَقِّ ۗ وَإِنَّ ٱلسَّاعَةَ لَءَاتِيَةٌۭ ۖ فَٱصْفَحِ ٱلصَّفْحَ ٱلْجَمِيلَ', 'وما خلقنا السموت والأرض وما بينهما إلا بالحق  وإن الساعة لءاتية  فاصفح الصفح الجميل', NULL, 266, 'local:hafs-text.json'),
  ('hafs-15-86', 'hafs', 15, 86, 'إِنَّ رَبَّكَ هُوَ ٱلْخَلَّٰقُ ٱلْعَلِيمُ', 'إن ربك هو الخلق العليم', NULL, 266, 'local:hafs-text.json'),
  ('hafs-15-87', 'hafs', 15, 87, 'وَلَقَدْ ءَاتَيْنَٰكَ سَبْعًۭا مِّنَ ٱلْمَثَانِى وَٱلْقُرْءَانَ ٱلْعَظِيمَ', 'ولقد ءاتينك سبعا من المثانى والقرءان العظيم', NULL, 266, 'local:hafs-text.json'),
  ('hafs-15-88', 'hafs', 15, 88, 'لَا تَمُدَّنَّ عَيْنَيْكَ إِلَىٰ مَا مَتَّعْنَا بِهِۦٓ أَزْوَٰجًۭا مِّنْهُمْ وَلَا تَحْزَنْ عَلَيْهِمْ وَٱخْفِضْ جَنَاحَكَ لِلْمُؤْمِنِينَ', 'لا تمدن عينيك إلى ما متعنا به أزوجا منهم ولا تحزن عليهم واخفض جناحك للمؤمنين', NULL, 266, 'local:hafs-text.json'),
  ('hafs-15-89', 'hafs', 15, 89, 'وَقُلْ إِنِّىٓ أَنَا ٱلنَّذِيرُ ٱلْمُبِينُ', 'وقل إنى أنا النذير المبين', NULL, 266, 'local:hafs-text.json'),
  ('hafs-15-90', 'hafs', 15, 90, 'كَمَآ أَنزَلْنَا عَلَى ٱلْمُقْتَسِمِينَ', 'كما أنزلنا على المقتسمين', NULL, 266, 'local:hafs-text.json'),
  ('hafs-15-91', 'hafs', 15, 91, 'ٱلَّذِينَ جَعَلُوا۟ ٱلْقُرْءَانَ عِضِينَ', 'الذين جعلوا القرءان عضين', NULL, 267, 'local:hafs-text.json'),
  ('hafs-15-92', 'hafs', 15, 92, 'فَوَرَبِّكَ لَنَسْـَٔلَنَّهُمْ أَجْمَعِينَ', 'فوربك لنسلنهم أجمعين', NULL, 267, 'local:hafs-text.json'),
  ('hafs-15-93', 'hafs', 15, 93, 'عَمَّا كَانُوا۟ يَعْمَلُونَ', 'عما كانوا يعملون', NULL, 267, 'local:hafs-text.json'),
  ('hafs-15-94', 'hafs', 15, 94, 'فَٱصْدَعْ بِمَا تُؤْمَرُ وَأَعْرِضْ عَنِ ٱلْمُشْرِكِينَ', 'فاصدع بما تؤمر وأعرض عن المشركين', NULL, 267, 'local:hafs-text.json'),
  ('hafs-15-95', 'hafs', 15, 95, 'إِنَّا كَفَيْنَٰكَ ٱلْمُسْتَهْزِءِينَ', 'إنا كفينك المستهزءين', NULL, 267, 'local:hafs-text.json'),
  ('hafs-15-96', 'hafs', 15, 96, 'ٱلَّذِينَ يَجْعَلُونَ مَعَ ٱللَّهِ إِلَٰهًا ءَاخَرَ ۚ فَسَوْفَ يَعْلَمُونَ', 'الذين يجعلون مع الله إلها ءاخر  فسوف يعلمون', NULL, 267, 'local:hafs-text.json'),
  ('hafs-15-97', 'hafs', 15, 97, 'وَلَقَدْ نَعْلَمُ أَنَّكَ يَضِيقُ صَدْرُكَ بِمَا يَقُولُونَ', 'ولقد نعلم أنك يضيق صدرك بما يقولون', NULL, 267, 'local:hafs-text.json'),
  ('hafs-15-98', 'hafs', 15, 98, 'فَسَبِّحْ بِحَمْدِ رَبِّكَ وَكُن مِّنَ ٱلسَّٰجِدِينَ', 'فسبح بحمد ربك وكن من السجدين', NULL, 267, 'local:hafs-text.json'),
  ('hafs-15-99', 'hafs', 15, 99, 'وَٱعْبُدْ رَبَّكَ حَتَّىٰ يَأْتِيَكَ ٱلْيَقِينُ', 'واعبد ربك حتى يأتيك اليقين', NULL, 267, 'local:hafs-text.json'),
  ('hafs-16-1', 'hafs', 16, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ أَتَىٰٓ أَمْرُ ٱللَّهِ فَلَا تَسْتَعْجِلُوهُ ۚ سُبْحَٰنَهُۥ وَتَعَٰلَىٰ عَمَّا يُشْرِكُونَ', 'بسم الله الرحمن الرحيم أتى أمر الله فلا تستعجلوه  سبحنه وتعلى عما يشركون', NULL, 267, 'local:hafs-text.json'),
  ('hafs-16-2', 'hafs', 16, 2, 'يُنَزِّلُ ٱلْمَلَٰٓئِكَةَ بِٱلرُّوحِ مِنْ أَمْرِهِۦ عَلَىٰ مَن يَشَآءُ مِنْ عِبَادِهِۦٓ أَنْ أَنذِرُوٓا۟ أَنَّهُۥ لَآ إِلَٰهَ إِلَّآ أَنَا۠ فَٱتَّقُونِ', 'ينزل الملئكة بالروح من أمره على من يشاء من عباده أن أنذروا أنه لا إله إلا أنا فاتقون', NULL, 267, 'local:hafs-text.json'),
  ('hafs-16-3', 'hafs', 16, 3, 'خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ بِٱلْحَقِّ ۚ تَعَٰلَىٰ عَمَّا يُشْرِكُونَ', 'خلق السموت والأرض بالحق  تعلى عما يشركون', NULL, 267, 'local:hafs-text.json'),
  ('hafs-16-4', 'hafs', 16, 4, 'خَلَقَ ٱلْإِنسَٰنَ مِن نُّطْفَةٍۢ فَإِذَا هُوَ خَصِيمٌۭ مُّبِينٌۭ', 'خلق الإنسن من نطفة فإذا هو خصيم مبين', NULL, 267, 'local:hafs-text.json'),
  ('hafs-16-5', 'hafs', 16, 5, 'وَٱلْأَنْعَٰمَ خَلَقَهَا ۗ لَكُمْ فِيهَا دِفْءٌۭ وَمَنَٰفِعُ وَمِنْهَا تَأْكُلُونَ', 'والأنعم خلقها  لكم فيها دفء ومنفع ومنها تأكلون', NULL, 267, 'local:hafs-text.json'),
  ('hafs-16-6', 'hafs', 16, 6, 'وَلَكُمْ فِيهَا جَمَالٌ حِينَ تُرِيحُونَ وَحِينَ تَسْرَحُونَ', 'ولكم فيها جمال حين تريحون وحين تسرحون', NULL, 267, 'local:hafs-text.json'),
  ('hafs-16-7', 'hafs', 16, 7, 'وَتَحْمِلُ أَثْقَالَكُمْ إِلَىٰ بَلَدٍۢ لَّمْ تَكُونُوا۟ بَٰلِغِيهِ إِلَّا بِشِقِّ ٱلْأَنفُسِ ۚ إِنَّ رَبَّكُمْ لَرَءُوفٌۭ رَّحِيمٌۭ', 'وتحمل أثقالكم إلى بلد لم تكونوا بلغيه إلا بشق الأنفس  إن ربكم لرءوف رحيم', NULL, 268, 'local:hafs-text.json'),
  ('hafs-16-8', 'hafs', 16, 8, 'وَٱلْخَيْلَ وَٱلْبِغَالَ وَٱلْحَمِيرَ لِتَرْكَبُوهَا وَزِينَةًۭ ۚ وَيَخْلُقُ مَا لَا تَعْلَمُونَ', 'والخيل والبغال والحمير لتركبوها وزينة  ويخلق ما لا تعلمون', NULL, 268, 'local:hafs-text.json'),
  ('hafs-16-9', 'hafs', 16, 9, 'وَعَلَى ٱللَّهِ قَصْدُ ٱلسَّبِيلِ وَمِنْهَا جَآئِرٌۭ ۚ وَلَوْ شَآءَ لَهَدَىٰكُمْ أَجْمَعِينَ', 'وعلى الله قصد السبيل ومنها جائر  ولو شاء لهدىكم أجمعين', NULL, 268, 'local:hafs-text.json'),
  ('hafs-16-10', 'hafs', 16, 10, 'هُوَ ٱلَّذِىٓ أَنزَلَ مِنَ ٱلسَّمَآءِ مَآءًۭ ۖ لَّكُم مِّنْهُ شَرَابٌۭ وَمِنْهُ شَجَرٌۭ فِيهِ تُسِيمُونَ', 'هو الذى أنزل من السماء ماء  لكم منه شراب ومنه شجر فيه تسيمون', NULL, 268, 'local:hafs-text.json'),
  ('hafs-16-11', 'hafs', 16, 11, 'يُنۢبِتُ لَكُم بِهِ ٱلزَّرْعَ وَٱلزَّيْتُونَ وَٱلنَّخِيلَ وَٱلْأَعْنَٰبَ وَمِن كُلِّ ٱلثَّمَرَٰتِ ۗ إِنَّ فِى ذَٰلِكَ لَءَايَةًۭ لِّقَوْمٍۢ يَتَفَكَّرُونَ', 'ينبت لكم به الزرع والزيتون والنخيل والأعنب ومن كل الثمرت  إن فى ذلك لءاية لقوم يتفكرون', NULL, 268, 'local:hafs-text.json'),
  ('hafs-16-12', 'hafs', 16, 12, 'وَسَخَّرَ لَكُمُ ٱلَّيْلَ وَٱلنَّهَارَ وَٱلشَّمْسَ وَٱلْقَمَرَ ۖ وَٱلنُّجُومُ مُسَخَّرَٰتٌۢ بِأَمْرِهِۦٓ ۗ إِنَّ فِى ذَٰلِكَ لَءَايَٰتٍۢ لِّقَوْمٍۢ يَعْقِلُونَ', 'وسخر لكم اليل والنهار والشمس والقمر  والنجوم مسخرت بأمره  إن فى ذلك لءايت لقوم يعقلون', NULL, 268, 'local:hafs-text.json'),
  ('hafs-16-13', 'hafs', 16, 13, 'وَمَا ذَرَأَ لَكُمْ فِى ٱلْأَرْضِ مُخْتَلِفًا أَلْوَٰنُهُۥٓ ۗ إِنَّ فِى ذَٰلِكَ لَءَايَةًۭ لِّقَوْمٍۢ يَذَّكَّرُونَ', 'وما ذرأ لكم فى الأرض مختلفا ألونه  إن فى ذلك لءاية لقوم يذكرون', NULL, 268, 'local:hafs-text.json'),
  ('hafs-16-14', 'hafs', 16, 14, 'وَهُوَ ٱلَّذِى سَخَّرَ ٱلْبَحْرَ لِتَأْكُلُوا۟ مِنْهُ لَحْمًۭا طَرِيًّۭا وَتَسْتَخْرِجُوا۟ مِنْهُ حِلْيَةًۭ تَلْبَسُونَهَا وَتَرَى ٱلْفُلْكَ مَوَاخِرَ فِيهِ وَلِتَبْتَغُوا۟ مِن فَضْلِهِۦ وَلَعَلَّكُمْ تَشْكُرُونَ', 'وهو الذى سخر البحر لتأكلوا منه لحما طريا وتستخرجوا منه حلية تلبسونها وترى الفلك مواخر فيه ولتبتغوا من فضله ولعلكم تشكرون', NULL, 268, 'local:hafs-text.json'),
  ('hafs-16-15', 'hafs', 16, 15, 'وَأَلْقَىٰ فِى ٱلْأَرْضِ رَوَٰسِىَ أَن تَمِيدَ بِكُمْ وَأَنْهَٰرًۭا وَسُبُلًۭا لَّعَلَّكُمْ تَهْتَدُونَ', 'وألقى فى الأرض روسى أن تميد بكم وأنهرا وسبلا لعلكم تهتدون', NULL, 269, 'local:hafs-text.json'),
  ('hafs-16-16', 'hafs', 16, 16, 'وَعَلَٰمَٰتٍۢ ۚ وَبِٱلنَّجْمِ هُمْ يَهْتَدُونَ', 'وعلمت  وبالنجم هم يهتدون', NULL, 269, 'local:hafs-text.json'),
  ('hafs-16-17', 'hafs', 16, 17, 'أَفَمَن يَخْلُقُ كَمَن لَّا يَخْلُقُ ۗ أَفَلَا تَذَكَّرُونَ', 'أفمن يخلق كمن لا يخلق  أفلا تذكرون', NULL, 269, 'local:hafs-text.json'),
  ('hafs-16-18', 'hafs', 16, 18, 'وَإِن تَعُدُّوا۟ نِعْمَةَ ٱللَّهِ لَا تُحْصُوهَآ ۗ إِنَّ ٱللَّهَ لَغَفُورٌۭ رَّحِيمٌۭ', 'وإن تعدوا نعمة الله لا تحصوها  إن الله لغفور رحيم', NULL, 269, 'local:hafs-text.json'),
  ('hafs-16-19', 'hafs', 16, 19, 'وَٱللَّهُ يَعْلَمُ مَا تُسِرُّونَ وَمَا تُعْلِنُونَ', 'والله يعلم ما تسرون وما تعلنون', NULL, 269, 'local:hafs-text.json'),
  ('hafs-16-20', 'hafs', 16, 20, 'وَٱلَّذِينَ يَدْعُونَ مِن دُونِ ٱللَّهِ لَا يَخْلُقُونَ شَيْـًۭٔا وَهُمْ يُخْلَقُونَ', 'والذين يدعون من دون الله لا يخلقون شيا وهم يخلقون', NULL, 269, 'local:hafs-text.json'),
  ('hafs-16-21', 'hafs', 16, 21, 'أَمْوَٰتٌ غَيْرُ أَحْيَآءٍۢ ۖ وَمَا يَشْعُرُونَ أَيَّانَ يُبْعَثُونَ', 'أموت غير أحياء  وما يشعرون أيان يبعثون', NULL, 269, 'local:hafs-text.json'),
  ('hafs-16-22', 'hafs', 16, 22, 'إِلَٰهُكُمْ إِلَٰهٌۭ وَٰحِدٌۭ ۚ فَٱلَّذِينَ لَا يُؤْمِنُونَ بِٱلْءَاخِرَةِ قُلُوبُهُم مُّنكِرَةٌۭ وَهُم مُّسْتَكْبِرُونَ', 'إلهكم إله وحد  فالذين لا يؤمنون بالءاخرة قلوبهم منكرة وهم مستكبرون', NULL, 269, 'local:hafs-text.json'),
  ('hafs-16-23', 'hafs', 16, 23, 'لَا جَرَمَ أَنَّ ٱللَّهَ يَعْلَمُ مَا يُسِرُّونَ وَمَا يُعْلِنُونَ ۚ إِنَّهُۥ لَا يُحِبُّ ٱلْمُسْتَكْبِرِينَ', 'لا جرم أن الله يعلم ما يسرون وما يعلنون  إنه لا يحب المستكبرين', NULL, 269, 'local:hafs-text.json'),
  ('hafs-16-24', 'hafs', 16, 24, 'وَإِذَا قِيلَ لَهُم مَّاذَآ أَنزَلَ رَبُّكُمْ ۙ قَالُوٓا۟ أَسَٰطِيرُ ٱلْأَوَّلِينَ', 'وإذا قيل لهم ماذا أنزل ربكم  قالوا أسطير الأولين', NULL, 269, 'local:hafs-text.json'),
  ('hafs-16-25', 'hafs', 16, 25, 'لِيَحْمِلُوٓا۟ أَوْزَارَهُمْ كَامِلَةًۭ يَوْمَ ٱلْقِيَٰمَةِ ۙ وَمِنْ أَوْزَارِ ٱلَّذِينَ يُضِلُّونَهُم بِغَيْرِ عِلْمٍ ۗ أَلَا سَآءَ مَا يَزِرُونَ', 'ليحملوا أوزارهم كاملة يوم القيمة  ومن أوزار الذين يضلونهم بغير علم  ألا ساء ما يزرون', NULL, 269, 'local:hafs-text.json'),
  ('hafs-16-26', 'hafs', 16, 26, 'قَدْ مَكَرَ ٱلَّذِينَ مِن قَبْلِهِمْ فَأَتَى ٱللَّهُ بُنْيَٰنَهُم مِّنَ ٱلْقَوَاعِدِ فَخَرَّ عَلَيْهِمُ ٱلسَّقْفُ مِن فَوْقِهِمْ وَأَتَىٰهُمُ ٱلْعَذَابُ مِنْ حَيْثُ لَا يَشْعُرُونَ', 'قد مكر الذين من قبلهم فأتى الله بنينهم من القواعد فخر عليهم السقف من فوقهم وأتىهم العذاب من حيث لا يشعرون', NULL, 269, 'local:hafs-text.json'),
  ('hafs-16-27', 'hafs', 16, 27, 'ثُمَّ يَوْمَ ٱلْقِيَٰمَةِ يُخْزِيهِمْ وَيَقُولُ أَيْنَ شُرَكَآءِىَ ٱلَّذِينَ كُنتُمْ تُشَٰٓقُّونَ فِيهِمْ ۚ قَالَ ٱلَّذِينَ أُوتُوا۟ ٱلْعِلْمَ إِنَّ ٱلْخِزْىَ ٱلْيَوْمَ وَٱلسُّوٓءَ عَلَى ٱلْكَٰفِرِينَ', 'ثم يوم القيمة يخزيهم ويقول أين شركاءى الذين كنتم تشقون فيهم  قال الذين أوتوا العلم إن الخزى اليوم والسوء على الكفرين', NULL, 270, 'local:hafs-text.json'),
  ('hafs-16-28', 'hafs', 16, 28, 'ٱلَّذِينَ تَتَوَفَّىٰهُمُ ٱلْمَلَٰٓئِكَةُ ظَالِمِىٓ أَنفُسِهِمْ ۖ فَأَلْقَوُا۟ ٱلسَّلَمَ مَا كُنَّا نَعْمَلُ مِن سُوٓءٍۭ ۚ بَلَىٰٓ إِنَّ ٱللَّهَ عَلِيمٌۢ بِمَا كُنتُمْ تَعْمَلُونَ', 'الذين تتوفىهم الملئكة ظالمى أنفسهم  فألقوا السلم ما كنا نعمل من سوء  بلى إن الله عليم بما كنتم تعملون', NULL, 270, 'local:hafs-text.json'),
  ('hafs-16-29', 'hafs', 16, 29, 'فَٱدْخُلُوٓا۟ أَبْوَٰبَ جَهَنَّمَ خَٰلِدِينَ فِيهَا ۖ فَلَبِئْسَ مَثْوَى ٱلْمُتَكَبِّرِينَ', 'فادخلوا أبوب جهنم خلدين فيها  فلبئس مثوى المتكبرين', NULL, 270, 'local:hafs-text.json'),
  ('hafs-16-30', 'hafs', 16, 30, '۞ وَقِيلَ لِلَّذِينَ ٱتَّقَوْا۟ مَاذَآ أَنزَلَ رَبُّكُمْ ۚ قَالُوا۟ خَيْرًۭا ۗ لِّلَّذِينَ أَحْسَنُوا۟ فِى هَٰذِهِ ٱلدُّنْيَا حَسَنَةٌۭ ۚ وَلَدَارُ ٱلْءَاخِرَةِ خَيْرٌۭ ۚ وَلَنِعْمَ دَارُ ٱلْمُتَّقِينَ', 'وقيل للذين اتقوا ماذا أنزل ربكم  قالوا خيرا  للذين أحسنوا فى هذه الدنيا حسنة  ولدار الءاخرة خير  ولنعم دار المتقين', NULL, 270, 'local:hafs-text.json'),
  ('hafs-16-31', 'hafs', 16, 31, 'جَنَّٰتُ عَدْنٍۢ يَدْخُلُونَهَا تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ ۖ لَهُمْ فِيهَا مَا يَشَآءُونَ ۚ كَذَٰلِكَ يَجْزِى ٱللَّهُ ٱلْمُتَّقِينَ', 'جنت عدن يدخلونها تجرى من تحتها الأنهر  لهم فيها ما يشاءون  كذلك يجزى الله المتقين', NULL, 270, 'local:hafs-text.json'),
  ('hafs-16-32', 'hafs', 16, 32, 'ٱلَّذِينَ تَتَوَفَّىٰهُمُ ٱلْمَلَٰٓئِكَةُ طَيِّبِينَ ۙ يَقُولُونَ سَلَٰمٌ عَلَيْكُمُ ٱدْخُلُوا۟ ٱلْجَنَّةَ بِمَا كُنتُمْ تَعْمَلُونَ', 'الذين تتوفىهم الملئكة طيبين  يقولون سلم عليكم ادخلوا الجنة بما كنتم تعملون', NULL, 270, 'local:hafs-text.json'),
  ('hafs-16-33', 'hafs', 16, 33, 'هَلْ يَنظُرُونَ إِلَّآ أَن تَأْتِيَهُمُ ٱلْمَلَٰٓئِكَةُ أَوْ يَأْتِىَ أَمْرُ رَبِّكَ ۚ كَذَٰلِكَ فَعَلَ ٱلَّذِينَ مِن قَبْلِهِمْ ۚ وَمَا ظَلَمَهُمُ ٱللَّهُ وَلَٰكِن كَانُوٓا۟ أَنفُسَهُمْ يَظْلِمُونَ', 'هل ينظرون إلا أن تأتيهم الملئكة أو يأتى أمر ربك  كذلك فعل الذين من قبلهم  وما ظلمهم الله ولكن كانوا أنفسهم يظلمون', NULL, 270, 'local:hafs-text.json'),
  ('hafs-16-34', 'hafs', 16, 34, 'فَأَصَابَهُمْ سَيِّـَٔاتُ مَا عَمِلُوا۟ وَحَاقَ بِهِم مَّا كَانُوا۟ بِهِۦ يَسْتَهْزِءُونَ', 'فأصابهم سيات ما عملوا وحاق بهم ما كانوا به يستهزءون', NULL, 270, 'local:hafs-text.json'),
  ('hafs-16-35', 'hafs', 16, 35, 'وَقَالَ ٱلَّذِينَ أَشْرَكُوا۟ لَوْ شَآءَ ٱللَّهُ مَا عَبَدْنَا مِن دُونِهِۦ مِن شَىْءٍۢ نَّحْنُ وَلَآ ءَابَآؤُنَا وَلَا حَرَّمْنَا مِن دُونِهِۦ مِن شَىْءٍۢ ۚ كَذَٰلِكَ فَعَلَ ٱلَّذِينَ مِن قَبْلِهِمْ ۚ فَهَلْ عَلَى ٱلرُّسُلِ إِلَّا ٱلْبَلَٰغُ ٱلْمُبِينُ', 'وقال الذين أشركوا لو شاء الله ما عبدنا من دونه من شىء نحن ولا ءاباؤنا ولا حرمنا من دونه من شىء  كذلك فعل الذين من قبلهم  فهل على الرسل إلا البلغ المبين', NULL, 271, 'local:hafs-text.json'),
  ('hafs-16-36', 'hafs', 16, 36, 'وَلَقَدْ بَعَثْنَا فِى كُلِّ أُمَّةٍۢ رَّسُولًا أَنِ ٱعْبُدُوا۟ ٱللَّهَ وَٱجْتَنِبُوا۟ ٱلطَّٰغُوتَ ۖ فَمِنْهُم مَّنْ هَدَى ٱللَّهُ وَمِنْهُم مَّنْ حَقَّتْ عَلَيْهِ ٱلضَّلَٰلَةُ ۚ فَسِيرُوا۟ فِى ٱلْأَرْضِ فَٱنظُرُوا۟ كَيْفَ كَانَ عَٰقِبَةُ ٱلْمُكَذِّبِينَ', 'ولقد بعثنا فى كل أمة رسولا أن اعبدوا الله واجتنبوا الطغوت  فمنهم من هدى الله ومنهم من حقت عليه الضللة  فسيروا فى الأرض فانظروا كيف كان عقبة المكذبين', NULL, 271, 'local:hafs-text.json'),
  ('hafs-16-37', 'hafs', 16, 37, 'إِن تَحْرِصْ عَلَىٰ هُدَىٰهُمْ فَإِنَّ ٱللَّهَ لَا يَهْدِى مَن يُضِلُّ ۖ وَمَا لَهُم مِّن نَّٰصِرِينَ', 'إن تحرص على هدىهم فإن الله لا يهدى من يضل  وما لهم من نصرين', NULL, 271, 'local:hafs-text.json'),
  ('hafs-16-38', 'hafs', 16, 38, 'وَأَقْسَمُوا۟ بِٱللَّهِ جَهْدَ أَيْمَٰنِهِمْ ۙ لَا يَبْعَثُ ٱللَّهُ مَن يَمُوتُ ۚ بَلَىٰ وَعْدًا عَلَيْهِ حَقًّۭا وَلَٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يَعْلَمُونَ', 'وأقسموا بالله جهد أيمنهم  لا يبعث الله من يموت  بلى وعدا عليه حقا ولكن أكثر الناس لا يعلمون', NULL, 271, 'local:hafs-text.json'),
  ('hafs-16-39', 'hafs', 16, 39, 'لِيُبَيِّنَ لَهُمُ ٱلَّذِى يَخْتَلِفُونَ فِيهِ وَلِيَعْلَمَ ٱلَّذِينَ كَفَرُوٓا۟ أَنَّهُمْ كَانُوا۟ كَٰذِبِينَ', 'ليبين لهم الذى يختلفون فيه وليعلم الذين كفروا أنهم كانوا كذبين', NULL, 271, 'local:hafs-text.json'),
  ('hafs-16-40', 'hafs', 16, 40, 'إِنَّمَا قَوْلُنَا لِشَىْءٍ إِذَآ أَرَدْنَٰهُ أَن نَّقُولَ لَهُۥ كُن فَيَكُونُ', 'إنما قولنا لشىء إذا أردنه أن نقول له كن فيكون', NULL, 271, 'local:hafs-text.json'),
  ('hafs-16-41', 'hafs', 16, 41, 'وَٱلَّذِينَ هَاجَرُوا۟ فِى ٱللَّهِ مِنۢ بَعْدِ مَا ظُلِمُوا۟ لَنُبَوِّئَنَّهُمْ فِى ٱلدُّنْيَا حَسَنَةًۭ ۖ وَلَأَجْرُ ٱلْءَاخِرَةِ أَكْبَرُ ۚ لَوْ كَانُوا۟ يَعْلَمُونَ', 'والذين هاجروا فى الله من بعد ما ظلموا لنبوئنهم فى الدنيا حسنة  ولأجر الءاخرة أكبر  لو كانوا يعلمون', NULL, 271, 'local:hafs-text.json'),
  ('hafs-16-42', 'hafs', 16, 42, 'ٱلَّذِينَ صَبَرُوا۟ وَعَلَىٰ رَبِّهِمْ يَتَوَكَّلُونَ', 'الذين صبروا وعلى ربهم يتوكلون', NULL, 271, 'local:hafs-text.json'),
  ('hafs-16-43', 'hafs', 16, 43, 'وَمَآ أَرْسَلْنَا مِن قَبْلِكَ إِلَّا رِجَالًۭا نُّوحِىٓ إِلَيْهِمْ ۚ فَسْـَٔلُوٓا۟ أَهْلَ ٱلذِّكْرِ إِن كُنتُمْ لَا تَعْلَمُونَ', 'وما أرسلنا من قبلك إلا رجالا نوحى إليهم  فسلوا أهل الذكر إن كنتم لا تعلمون', NULL, 272, 'local:hafs-text.json'),
  ('hafs-16-44', 'hafs', 16, 44, 'بِٱلْبَيِّنَٰتِ وَٱلزُّبُرِ ۗ وَأَنزَلْنَآ إِلَيْكَ ٱلذِّكْرَ لِتُبَيِّنَ لِلنَّاسِ مَا نُزِّلَ إِلَيْهِمْ وَلَعَلَّهُمْ يَتَفَكَّرُونَ', 'بالبينت والزبر  وأنزلنا إليك الذكر لتبين للناس ما نزل إليهم ولعلهم يتفكرون', NULL, 272, 'local:hafs-text.json'),
  ('hafs-16-45', 'hafs', 16, 45, 'أَفَأَمِنَ ٱلَّذِينَ مَكَرُوا۟ ٱلسَّيِّـَٔاتِ أَن يَخْسِفَ ٱللَّهُ بِهِمُ ٱلْأَرْضَ أَوْ يَأْتِيَهُمُ ٱلْعَذَابُ مِنْ حَيْثُ لَا يَشْعُرُونَ', 'أفأمن الذين مكروا السيات أن يخسف الله بهم الأرض أو يأتيهم العذاب من حيث لا يشعرون', NULL, 272, 'local:hafs-text.json'),
  ('hafs-16-46', 'hafs', 16, 46, 'أَوْ يَأْخُذَهُمْ فِى تَقَلُّبِهِمْ فَمَا هُم بِمُعْجِزِينَ', 'أو يأخذهم فى تقلبهم فما هم بمعجزين', NULL, 272, 'local:hafs-text.json'),
  ('hafs-16-47', 'hafs', 16, 47, 'أَوْ يَأْخُذَهُمْ عَلَىٰ تَخَوُّفٍۢ فَإِنَّ رَبَّكُمْ لَرَءُوفٌۭ رَّحِيمٌ', 'أو يأخذهم على تخوف فإن ربكم لرءوف رحيم', NULL, 272, 'local:hafs-text.json'),
  ('hafs-16-48', 'hafs', 16, 48, 'أَوَلَمْ يَرَوْا۟ إِلَىٰ مَا خَلَقَ ٱللَّهُ مِن شَىْءٍۢ يَتَفَيَّؤُا۟ ظِلَٰلُهُۥ عَنِ ٱلْيَمِينِ وَٱلشَّمَآئِلِ سُجَّدًۭا لِّلَّهِ وَهُمْ دَٰخِرُونَ', 'أولم يروا إلى ما خلق الله من شىء يتفيؤا ظلله عن اليمين والشمائل سجدا لله وهم دخرون', NULL, 272, 'local:hafs-text.json'),
  ('hafs-16-49', 'hafs', 16, 49, 'وَلِلَّهِ يَسْجُدُ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ مِن دَآبَّةٍۢ وَٱلْمَلَٰٓئِكَةُ وَهُمْ لَا يَسْتَكْبِرُونَ', 'ولله يسجد ما فى السموت وما فى الأرض من دابة والملئكة وهم لا يستكبرون', NULL, 272, 'local:hafs-text.json'),
  ('hafs-16-50', 'hafs', 16, 50, 'يَخَافُونَ رَبَّهُم مِّن فَوْقِهِمْ وَيَفْعَلُونَ مَا يُؤْمَرُونَ ۩', 'يخافون ربهم من فوقهم ويفعلون ما يؤمرون', NULL, 272, 'local:hafs-text.json'),
  ('hafs-16-51', 'hafs', 16, 51, '۞ وَقَالَ ٱللَّهُ لَا تَتَّخِذُوٓا۟ إِلَٰهَيْنِ ٱثْنَيْنِ ۖ إِنَّمَا هُوَ إِلَٰهٌۭ وَٰحِدٌۭ ۖ فَإِيَّٰىَ فَٱرْهَبُونِ', 'وقال الله لا تتخذوا إلهين اثنين  إنما هو إله وحد  فإيى فارهبون', NULL, 272, 'local:hafs-text.json'),
  ('hafs-16-52', 'hafs', 16, 52, 'وَلَهُۥ مَا فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَلَهُ ٱلدِّينُ وَاصِبًا ۚ أَفَغَيْرَ ٱللَّهِ تَتَّقُونَ', 'وله ما فى السموت والأرض وله الدين واصبا  أفغير الله تتقون', NULL, 272, 'local:hafs-text.json'),
  ('hafs-16-53', 'hafs', 16, 53, 'وَمَا بِكُم مِّن نِّعْمَةٍۢ فَمِنَ ٱللَّهِ ۖ ثُمَّ إِذَا مَسَّكُمُ ٱلضُّرُّ فَإِلَيْهِ تَجْـَٔرُونَ', 'وما بكم من نعمة فمن الله  ثم إذا مسكم الضر فإليه تجرون', NULL, 272, 'local:hafs-text.json'),
  ('hafs-16-54', 'hafs', 16, 54, 'ثُمَّ إِذَا كَشَفَ ٱلضُّرَّ عَنكُمْ إِذَا فَرِيقٌۭ مِّنكُم بِرَبِّهِمْ يُشْرِكُونَ', 'ثم إذا كشف الضر عنكم إذا فريق منكم بربهم يشركون', NULL, 272, 'local:hafs-text.json'),
  ('hafs-16-55', 'hafs', 16, 55, 'لِيَكْفُرُوا۟ بِمَآ ءَاتَيْنَٰهُمْ ۚ فَتَمَتَّعُوا۟ ۖ فَسَوْفَ تَعْلَمُونَ', 'ليكفروا بما ءاتينهم  فتمتعوا  فسوف تعلمون', NULL, 273, 'local:hafs-text.json'),
  ('hafs-16-56', 'hafs', 16, 56, 'وَيَجْعَلُونَ لِمَا لَا يَعْلَمُونَ نَصِيبًۭا مِّمَّا رَزَقْنَٰهُمْ ۗ تَٱللَّهِ لَتُسْـَٔلُنَّ عَمَّا كُنتُمْ تَفْتَرُونَ', 'ويجعلون لما لا يعلمون نصيبا مما رزقنهم  تالله لتسلن عما كنتم تفترون', NULL, 273, 'local:hafs-text.json'),
  ('hafs-16-57', 'hafs', 16, 57, 'وَيَجْعَلُونَ لِلَّهِ ٱلْبَنَٰتِ سُبْحَٰنَهُۥ ۙ وَلَهُم مَّا يَشْتَهُونَ', 'ويجعلون لله البنت سبحنه  ولهم ما يشتهون', NULL, 273, 'local:hafs-text.json'),
  ('hafs-16-58', 'hafs', 16, 58, 'وَإِذَا بُشِّرَ أَحَدُهُم بِٱلْأُنثَىٰ ظَلَّ وَجْهُهُۥ مُسْوَدًّۭا وَهُوَ كَظِيمٌۭ', 'وإذا بشر أحدهم بالأنثى ظل وجهه مسودا وهو كظيم', NULL, 273, 'local:hafs-text.json'),
  ('hafs-16-59', 'hafs', 16, 59, 'يَتَوَٰرَىٰ مِنَ ٱلْقَوْمِ مِن سُوٓءِ مَا بُشِّرَ بِهِۦٓ ۚ أَيُمْسِكُهُۥ عَلَىٰ هُونٍ أَمْ يَدُسُّهُۥ فِى ٱلتُّرَابِ ۗ أَلَا سَآءَ مَا يَحْكُمُونَ', 'يتورى من القوم من سوء ما بشر به  أيمسكه على هون أم يدسه فى التراب  ألا ساء ما يحكمون', NULL, 273, 'local:hafs-text.json'),
  ('hafs-16-60', 'hafs', 16, 60, 'لِلَّذِينَ لَا يُؤْمِنُونَ بِٱلْءَاخِرَةِ مَثَلُ ٱلسَّوْءِ ۖ وَلِلَّهِ ٱلْمَثَلُ ٱلْأَعْلَىٰ ۚ وَهُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ', 'للذين لا يؤمنون بالءاخرة مثل السوء  ولله المثل الأعلى  وهو العزيز الحكيم', NULL, 273, 'local:hafs-text.json'),
  ('hafs-16-61', 'hafs', 16, 61, 'وَلَوْ يُؤَاخِذُ ٱللَّهُ ٱلنَّاسَ بِظُلْمِهِم مَّا تَرَكَ عَلَيْهَا مِن دَآبَّةٍۢ وَلَٰكِن يُؤَخِّرُهُمْ إِلَىٰٓ أَجَلٍۢ مُّسَمًّۭى ۖ فَإِذَا جَآءَ أَجَلُهُمْ لَا يَسْتَـْٔخِرُونَ سَاعَةًۭ ۖ وَلَا يَسْتَقْدِمُونَ', 'ولو يؤاخذ الله الناس بظلمهم ما ترك عليها من دابة ولكن يؤخرهم إلى أجل مسمى  فإذا جاء أجلهم لا يستخرون ساعة  ولا يستقدمون', NULL, 273, 'local:hafs-text.json'),
  ('hafs-16-62', 'hafs', 16, 62, 'وَيَجْعَلُونَ لِلَّهِ مَا يَكْرَهُونَ وَتَصِفُ أَلْسِنَتُهُمُ ٱلْكَذِبَ أَنَّ لَهُمُ ٱلْحُسْنَىٰ ۖ لَا جَرَمَ أَنَّ لَهُمُ ٱلنَّارَ وَأَنَّهُم مُّفْرَطُونَ', 'ويجعلون لله ما يكرهون وتصف ألسنتهم الكذب أن لهم الحسنى  لا جرم أن لهم النار وأنهم مفرطون', NULL, 273, 'local:hafs-text.json'),
  ('hafs-16-63', 'hafs', 16, 63, 'تَٱللَّهِ لَقَدْ أَرْسَلْنَآ إِلَىٰٓ أُمَمٍۢ مِّن قَبْلِكَ فَزَيَّنَ لَهُمُ ٱلشَّيْطَٰنُ أَعْمَٰلَهُمْ فَهُوَ وَلِيُّهُمُ ٱلْيَوْمَ وَلَهُمْ عَذَابٌ أَلِيمٌۭ', 'تالله لقد أرسلنا إلى أمم من قبلك فزين لهم الشيطن أعملهم فهو وليهم اليوم ولهم عذاب أليم', NULL, 273, 'local:hafs-text.json'),
  ('hafs-16-64', 'hafs', 16, 64, 'وَمَآ أَنزَلْنَا عَلَيْكَ ٱلْكِتَٰبَ إِلَّا لِتُبَيِّنَ لَهُمُ ٱلَّذِى ٱخْتَلَفُوا۟ فِيهِ ۙ وَهُدًۭى وَرَحْمَةًۭ لِّقَوْمٍۢ يُؤْمِنُونَ', 'وما أنزلنا عليك الكتب إلا لتبين لهم الذى اختلفوا فيه  وهدى ورحمة لقوم يؤمنون', NULL, 273, 'local:hafs-text.json'),
  ('hafs-16-65', 'hafs', 16, 65, 'وَٱللَّهُ أَنزَلَ مِنَ ٱلسَّمَآءِ مَآءًۭ فَأَحْيَا بِهِ ٱلْأَرْضَ بَعْدَ مَوْتِهَآ ۚ إِنَّ فِى ذَٰلِكَ لَءَايَةًۭ لِّقَوْمٍۢ يَسْمَعُونَ', 'والله أنزل من السماء ماء فأحيا به الأرض بعد موتها  إن فى ذلك لءاية لقوم يسمعون', NULL, 274, 'local:hafs-text.json'),
  ('hafs-16-66', 'hafs', 16, 66, 'وَإِنَّ لَكُمْ فِى ٱلْأَنْعَٰمِ لَعِبْرَةًۭ ۖ نُّسْقِيكُم مِّمَّا فِى بُطُونِهِۦ مِنۢ بَيْنِ فَرْثٍۢ وَدَمٍۢ لَّبَنًا خَالِصًۭا سَآئِغًۭا لِّلشَّٰرِبِينَ', 'وإن لكم فى الأنعم لعبرة  نسقيكم مما فى بطونه من بين فرث ودم لبنا خالصا سائغا للشربين', NULL, 274, 'local:hafs-text.json'),
  ('hafs-16-67', 'hafs', 16, 67, 'وَمِن ثَمَرَٰتِ ٱلنَّخِيلِ وَٱلْأَعْنَٰبِ تَتَّخِذُونَ مِنْهُ سَكَرًۭا وَرِزْقًا حَسَنًا ۗ إِنَّ فِى ذَٰلِكَ لَءَايَةًۭ لِّقَوْمٍۢ يَعْقِلُونَ', 'ومن ثمرت النخيل والأعنب تتخذون منه سكرا ورزقا حسنا  إن فى ذلك لءاية لقوم يعقلون', NULL, 274, 'local:hafs-text.json'),
  ('hafs-16-68', 'hafs', 16, 68, 'وَأَوْحَىٰ رَبُّكَ إِلَى ٱلنَّحْلِ أَنِ ٱتَّخِذِى مِنَ ٱلْجِبَالِ بُيُوتًۭا وَمِنَ ٱلشَّجَرِ وَمِمَّا يَعْرِشُونَ', 'وأوحى ربك إلى النحل أن اتخذى من الجبال بيوتا ومن الشجر ومما يعرشون', NULL, 274, 'local:hafs-text.json'),
  ('hafs-16-69', 'hafs', 16, 69, 'ثُمَّ كُلِى مِن كُلِّ ٱلثَّمَرَٰتِ فَٱسْلُكِى سُبُلَ رَبِّكِ ذُلُلًۭا ۚ يَخْرُجُ مِنۢ بُطُونِهَا شَرَابٌۭ مُّخْتَلِفٌ أَلْوَٰنُهُۥ فِيهِ شِفَآءٌۭ لِّلنَّاسِ ۗ إِنَّ فِى ذَٰلِكَ لَءَايَةًۭ لِّقَوْمٍۢ يَتَفَكَّرُونَ', 'ثم كلى من كل الثمرت فاسلكى سبل ربك ذللا  يخرج من بطونها شراب مختلف ألونه فيه شفاء للناس  إن فى ذلك لءاية لقوم يتفكرون', NULL, 274, 'local:hafs-text.json'),
  ('hafs-16-70', 'hafs', 16, 70, 'وَٱللَّهُ خَلَقَكُمْ ثُمَّ يَتَوَفَّىٰكُمْ ۚ وَمِنكُم مَّن يُرَدُّ إِلَىٰٓ أَرْذَلِ ٱلْعُمُرِ لِكَىْ لَا يَعْلَمَ بَعْدَ عِلْمٍۢ شَيْـًٔا ۚ إِنَّ ٱللَّهَ عَلِيمٌۭ قَدِيرٌۭ', 'والله خلقكم ثم يتوفىكم  ومنكم من يرد إلى أرذل العمر لكى لا يعلم بعد علم شيا  إن الله عليم قدير', NULL, 274, 'local:hafs-text.json'),
  ('hafs-16-71', 'hafs', 16, 71, 'وَٱللَّهُ فَضَّلَ بَعْضَكُمْ عَلَىٰ بَعْضٍۢ فِى ٱلرِّزْقِ ۚ فَمَا ٱلَّذِينَ فُضِّلُوا۟ بِرَآدِّى رِزْقِهِمْ عَلَىٰ مَا مَلَكَتْ أَيْمَٰنُهُمْ فَهُمْ فِيهِ سَوَآءٌ ۚ أَفَبِنِعْمَةِ ٱللَّهِ يَجْحَدُونَ', 'والله فضل بعضكم على بعض فى الرزق  فما الذين فضلوا برادى رزقهم على ما ملكت أيمنهم فهم فيه سواء  أفبنعمة الله يجحدون', NULL, 274, 'local:hafs-text.json'),
  ('hafs-16-72', 'hafs', 16, 72, 'وَٱللَّهُ جَعَلَ لَكُم مِّنْ أَنفُسِكُمْ أَزْوَٰجًۭا وَجَعَلَ لَكُم مِّنْ أَزْوَٰجِكُم بَنِينَ وَحَفَدَةًۭ وَرَزَقَكُم مِّنَ ٱلطَّيِّبَٰتِ ۚ أَفَبِٱلْبَٰطِلِ يُؤْمِنُونَ وَبِنِعْمَتِ ٱللَّهِ هُمْ يَكْفُرُونَ', 'والله جعل لكم من أنفسكم أزوجا وجعل لكم من أزوجكم بنين وحفدة ورزقكم من الطيبت  أفبالبطل يؤمنون وبنعمت الله هم يكفرون', NULL, 274, 'local:hafs-text.json'),
  ('hafs-16-73', 'hafs', 16, 73, 'وَيَعْبُدُونَ مِن دُونِ ٱللَّهِ مَا لَا يَمْلِكُ لَهُمْ رِزْقًۭا مِّنَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ شَيْـًۭٔا وَلَا يَسْتَطِيعُونَ', 'ويعبدون من دون الله ما لا يملك لهم رزقا من السموت والأرض شيا ولا يستطيعون', NULL, 275, 'local:hafs-text.json'),
  ('hafs-16-74', 'hafs', 16, 74, 'فَلَا تَضْرِبُوا۟ لِلَّهِ ٱلْأَمْثَالَ ۚ إِنَّ ٱللَّهَ يَعْلَمُ وَأَنتُمْ لَا تَعْلَمُونَ', 'فلا تضربوا لله الأمثال  إن الله يعلم وأنتم لا تعلمون', NULL, 275, 'local:hafs-text.json'),
  ('hafs-16-75', 'hafs', 16, 75, '۞ ضَرَبَ ٱللَّهُ مَثَلًا عَبْدًۭا مَّمْلُوكًۭا لَّا يَقْدِرُ عَلَىٰ شَىْءٍۢ وَمَن رَّزَقْنَٰهُ مِنَّا رِزْقًا حَسَنًۭا فَهُوَ يُنفِقُ مِنْهُ سِرًّۭا وَجَهْرًا ۖ هَلْ يَسْتَوُۥنَ ۚ ٱلْحَمْدُ لِلَّهِ ۚ بَلْ أَكْثَرُهُمْ لَا يَعْلَمُونَ', 'ضرب الله مثلا عبدا مملوكا لا يقدر على شىء ومن رزقنه منا رزقا حسنا فهو ينفق منه سرا وجهرا  هل يستون  الحمد لله  بل أكثرهم لا يعلمون', NULL, 275, 'local:hafs-text.json'),
  ('hafs-16-76', 'hafs', 16, 76, 'وَضَرَبَ ٱللَّهُ مَثَلًۭا رَّجُلَيْنِ أَحَدُهُمَآ أَبْكَمُ لَا يَقْدِرُ عَلَىٰ شَىْءٍۢ وَهُوَ كَلٌّ عَلَىٰ مَوْلَىٰهُ أَيْنَمَا يُوَجِّههُّ لَا يَأْتِ بِخَيْرٍ ۖ هَلْ يَسْتَوِى هُوَ وَمَن يَأْمُرُ بِٱلْعَدْلِ ۙ وَهُوَ عَلَىٰ صِرَٰطٍۢ مُّسْتَقِيمٍۢ', 'وضرب الله مثلا رجلين أحدهما أبكم لا يقدر على شىء وهو كل على مولىه أينما يوجهه لا يأت بخير  هل يستوى هو ومن يأمر بالعدل  وهو على صرط مستقيم', NULL, 275, 'local:hafs-text.json'),
  ('hafs-16-77', 'hafs', 16, 77, 'وَلِلَّهِ غَيْبُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ ۚ وَمَآ أَمْرُ ٱلسَّاعَةِ إِلَّا كَلَمْحِ ٱلْبَصَرِ أَوْ هُوَ أَقْرَبُ ۚ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَىْءٍۢ قَدِيرٌۭ', 'ولله غيب السموت والأرض  وما أمر الساعة إلا كلمح البصر أو هو أقرب  إن الله على كل شىء قدير', NULL, 275, 'local:hafs-text.json'),
  ('hafs-16-78', 'hafs', 16, 78, 'وَٱللَّهُ أَخْرَجَكُم مِّنۢ بُطُونِ أُمَّهَٰتِكُمْ لَا تَعْلَمُونَ شَيْـًۭٔا وَجَعَلَ لَكُمُ ٱلسَّمْعَ وَٱلْأَبْصَٰرَ وَٱلْأَفْـِٔدَةَ ۙ لَعَلَّكُمْ تَشْكُرُونَ', 'والله أخرجكم من بطون أمهتكم لا تعلمون شيا وجعل لكم السمع والأبصر والأفدة  لعلكم تشكرون', NULL, 275, 'local:hafs-text.json'),
  ('hafs-16-79', 'hafs', 16, 79, 'أَلَمْ يَرَوْا۟ إِلَى ٱلطَّيْرِ مُسَخَّرَٰتٍۢ فِى جَوِّ ٱلسَّمَآءِ مَا يُمْسِكُهُنَّ إِلَّا ٱللَّهُ ۗ إِنَّ فِى ذَٰلِكَ لَءَايَٰتٍۢ لِّقَوْمٍۢ يُؤْمِنُونَ', 'ألم يروا إلى الطير مسخرت فى جو السماء ما يمسكهن إلا الله  إن فى ذلك لءايت لقوم يؤمنون', NULL, 275, 'local:hafs-text.json'),
  ('hafs-16-80', 'hafs', 16, 80, 'وَٱللَّهُ جَعَلَ لَكُم مِّنۢ بُيُوتِكُمْ سَكَنًۭا وَجَعَلَ لَكُم مِّن جُلُودِ ٱلْأَنْعَٰمِ بُيُوتًۭا تَسْتَخِفُّونَهَا يَوْمَ ظَعْنِكُمْ وَيَوْمَ إِقَامَتِكُمْ ۙ وَمِنْ أَصْوَافِهَا وَأَوْبَارِهَا وَأَشْعَارِهَآ أَثَٰثًۭا وَمَتَٰعًا إِلَىٰ حِينٍۢ', 'والله جعل لكم من بيوتكم سكنا وجعل لكم من جلود الأنعم بيوتا تستخفونها يوم ظعنكم ويوم إقامتكم  ومن أصوافها وأوبارها وأشعارها أثثا ومتعا إلى حين', NULL, 276, 'local:hafs-text.json'),
  ('hafs-16-81', 'hafs', 16, 81, 'وَٱللَّهُ جَعَلَ لَكُم مِّمَّا خَلَقَ ظِلَٰلًۭا وَجَعَلَ لَكُم مِّنَ ٱلْجِبَالِ أَكْنَٰنًۭا وَجَعَلَ لَكُمْ سَرَٰبِيلَ تَقِيكُمُ ٱلْحَرَّ وَسَرَٰبِيلَ تَقِيكُم بَأْسَكُمْ ۚ كَذَٰلِكَ يُتِمُّ نِعْمَتَهُۥ عَلَيْكُمْ لَعَلَّكُمْ تُسْلِمُونَ', 'والله جعل لكم مما خلق ظللا وجعل لكم من الجبال أكننا وجعل لكم سربيل تقيكم الحر وسربيل تقيكم بأسكم  كذلك يتم نعمته عليكم لعلكم تسلمون', NULL, 276, 'local:hafs-text.json'),
  ('hafs-16-82', 'hafs', 16, 82, 'فَإِن تَوَلَّوْا۟ فَإِنَّمَا عَلَيْكَ ٱلْبَلَٰغُ ٱلْمُبِينُ', 'فإن تولوا فإنما عليك البلغ المبين', NULL, 276, 'local:hafs-text.json'),
  ('hafs-16-83', 'hafs', 16, 83, 'يَعْرِفُونَ نِعْمَتَ ٱللَّهِ ثُمَّ يُنكِرُونَهَا وَأَكْثَرُهُمُ ٱلْكَٰفِرُونَ', 'يعرفون نعمت الله ثم ينكرونها وأكثرهم الكفرون', NULL, 276, 'local:hafs-text.json'),
  ('hafs-16-84', 'hafs', 16, 84, 'وَيَوْمَ نَبْعَثُ مِن كُلِّ أُمَّةٍۢ شَهِيدًۭا ثُمَّ لَا يُؤْذَنُ لِلَّذِينَ كَفَرُوا۟ وَلَا هُمْ يُسْتَعْتَبُونَ', 'ويوم نبعث من كل أمة شهيدا ثم لا يؤذن للذين كفروا ولا هم يستعتبون', NULL, 276, 'local:hafs-text.json'),
  ('hafs-16-85', 'hafs', 16, 85, 'وَإِذَا رَءَا ٱلَّذِينَ ظَلَمُوا۟ ٱلْعَذَابَ فَلَا يُخَفَّفُ عَنْهُمْ وَلَا هُمْ يُنظَرُونَ', 'وإذا رءا الذين ظلموا العذاب فلا يخفف عنهم ولا هم ينظرون', NULL, 276, 'local:hafs-text.json'),
  ('hafs-16-86', 'hafs', 16, 86, 'وَإِذَا رَءَا ٱلَّذِينَ أَشْرَكُوا۟ شُرَكَآءَهُمْ قَالُوا۟ رَبَّنَا هَٰٓؤُلَآءِ شُرَكَآؤُنَا ٱلَّذِينَ كُنَّا نَدْعُوا۟ مِن دُونِكَ ۖ فَأَلْقَوْا۟ إِلَيْهِمُ ٱلْقَوْلَ إِنَّكُمْ لَكَٰذِبُونَ', 'وإذا رءا الذين أشركوا شركاءهم قالوا ربنا هؤلاء شركاؤنا الذين كنا ندعوا من دونك  فألقوا إليهم القول إنكم لكذبون', NULL, 276, 'local:hafs-text.json'),
  ('hafs-16-87', 'hafs', 16, 87, 'وَأَلْقَوْا۟ إِلَى ٱللَّهِ يَوْمَئِذٍ ٱلسَّلَمَ ۖ وَضَلَّ عَنْهُم مَّا كَانُوا۟ يَفْتَرُونَ', 'وألقوا إلى الله يومئذ السلم  وضل عنهم ما كانوا يفترون', NULL, 276, 'local:hafs-text.json'),
  ('hafs-16-88', 'hafs', 16, 88, 'ٱلَّذِينَ كَفَرُوا۟ وَصَدُّوا۟ عَن سَبِيلِ ٱللَّهِ زِدْنَٰهُمْ عَذَابًۭا فَوْقَ ٱلْعَذَابِ بِمَا كَانُوا۟ يُفْسِدُونَ', 'الذين كفروا وصدوا عن سبيل الله زدنهم عذابا فوق العذاب بما كانوا يفسدون', NULL, 277, 'local:hafs-text.json'),
  ('hafs-16-89', 'hafs', 16, 89, 'وَيَوْمَ نَبْعَثُ فِى كُلِّ أُمَّةٍۢ شَهِيدًا عَلَيْهِم مِّنْ أَنفُسِهِمْ ۖ وَجِئْنَا بِكَ شَهِيدًا عَلَىٰ هَٰٓؤُلَآءِ ۚ وَنَزَّلْنَا عَلَيْكَ ٱلْكِتَٰبَ تِبْيَٰنًۭا لِّكُلِّ شَىْءٍۢ وَهُدًۭى وَرَحْمَةًۭ وَبُشْرَىٰ لِلْمُسْلِمِينَ', 'ويوم نبعث فى كل أمة شهيدا عليهم من أنفسهم  وجئنا بك شهيدا على هؤلاء  ونزلنا عليك الكتب تبينا لكل شىء وهدى ورحمة وبشرى للمسلمين', NULL, 277, 'local:hafs-text.json'),
  ('hafs-16-90', 'hafs', 16, 90, '۞ إِنَّ ٱللَّهَ يَأْمُرُ بِٱلْعَدْلِ وَٱلْإِحْسَٰنِ وَإِيتَآئِ ذِى ٱلْقُرْبَىٰ وَيَنْهَىٰ عَنِ ٱلْفَحْشَآءِ وَٱلْمُنكَرِ وَٱلْبَغْىِ ۚ يَعِظُكُمْ لَعَلَّكُمْ تَذَكَّرُونَ', 'إن الله يأمر بالعدل والإحسن وإيتائ ذى القربى وينهى عن الفحشاء والمنكر والبغى  يعظكم لعلكم تذكرون', NULL, 277, 'local:hafs-text.json'),
  ('hafs-16-91', 'hafs', 16, 91, 'وَأَوْفُوا۟ بِعَهْدِ ٱللَّهِ إِذَا عَٰهَدتُّمْ وَلَا تَنقُضُوا۟ ٱلْأَيْمَٰنَ بَعْدَ تَوْكِيدِهَا وَقَدْ جَعَلْتُمُ ٱللَّهَ عَلَيْكُمْ كَفِيلًا ۚ إِنَّ ٱللَّهَ يَعْلَمُ مَا تَفْعَلُونَ', 'وأوفوا بعهد الله إذا عهدتم ولا تنقضوا الأيمن بعد توكيدها وقد جعلتم الله عليكم كفيلا  إن الله يعلم ما تفعلون', NULL, 277, 'local:hafs-text.json'),
  ('hafs-16-92', 'hafs', 16, 92, 'وَلَا تَكُونُوا۟ كَٱلَّتِى نَقَضَتْ غَزْلَهَا مِنۢ بَعْدِ قُوَّةٍ أَنكَٰثًۭا تَتَّخِذُونَ أَيْمَٰنَكُمْ دَخَلًۢا بَيْنَكُمْ أَن تَكُونَ أُمَّةٌ هِىَ أَرْبَىٰ مِنْ أُمَّةٍ ۚ إِنَّمَا يَبْلُوكُمُ ٱللَّهُ بِهِۦ ۚ وَلَيُبَيِّنَنَّ لَكُمْ يَوْمَ ٱلْقِيَٰمَةِ مَا كُنتُمْ فِيهِ تَخْتَلِفُونَ', 'ولا تكونوا كالتى نقضت غزلها من بعد قوة أنكثا تتخذون أيمنكم دخلا بينكم أن تكون أمة هى أربى من أمة  إنما يبلوكم الله به  وليبينن لكم يوم القيمة ما كنتم فيه تختلفون', NULL, 277, 'local:hafs-text.json'),
  ('hafs-16-93', 'hafs', 16, 93, 'وَلَوْ شَآءَ ٱللَّهُ لَجَعَلَكُمْ أُمَّةًۭ وَٰحِدَةًۭ وَلَٰكِن يُضِلُّ مَن يَشَآءُ وَيَهْدِى مَن يَشَآءُ ۚ وَلَتُسْـَٔلُنَّ عَمَّا كُنتُمْ تَعْمَلُونَ', 'ولو شاء الله لجعلكم أمة وحدة ولكن يضل من يشاء ويهدى من يشاء  ولتسلن عما كنتم تعملون', NULL, 277, 'local:hafs-text.json'),
  ('hafs-16-94', 'hafs', 16, 94, 'وَلَا تَتَّخِذُوٓا۟ أَيْمَٰنَكُمْ دَخَلًۢا بَيْنَكُمْ فَتَزِلَّ قَدَمٌۢ بَعْدَ ثُبُوتِهَا وَتَذُوقُوا۟ ٱلسُّوٓءَ بِمَا صَدَدتُّمْ عَن سَبِيلِ ٱللَّهِ ۖ وَلَكُمْ عَذَابٌ عَظِيمٌۭ', 'ولا تتخذوا أيمنكم دخلا بينكم فتزل قدم بعد ثبوتها وتذوقوا السوء بما صددتم عن سبيل الله  ولكم عذاب عظيم', NULL, 278, 'local:hafs-text.json'),
  ('hafs-16-95', 'hafs', 16, 95, 'وَلَا تَشْتَرُوا۟ بِعَهْدِ ٱللَّهِ ثَمَنًۭا قَلِيلًا ۚ إِنَّمَا عِندَ ٱللَّهِ هُوَ خَيْرٌۭ لَّكُمْ إِن كُنتُمْ تَعْلَمُونَ', 'ولا تشتروا بعهد الله ثمنا قليلا  إنما عند الله هو خير لكم إن كنتم تعلمون', NULL, 278, 'local:hafs-text.json'),
  ('hafs-16-96', 'hafs', 16, 96, 'مَا عِندَكُمْ يَنفَدُ ۖ وَمَا عِندَ ٱللَّهِ بَاقٍۢ ۗ وَلَنَجْزِيَنَّ ٱلَّذِينَ صَبَرُوٓا۟ أَجْرَهُم بِأَحْسَنِ مَا كَانُوا۟ يَعْمَلُونَ', 'ما عندكم ينفد  وما عند الله باق  ولنجزين الذين صبروا أجرهم بأحسن ما كانوا يعملون', NULL, 278, 'local:hafs-text.json'),
  ('hafs-16-97', 'hafs', 16, 97, 'مَنْ عَمِلَ صَٰلِحًۭا مِّن ذَكَرٍ أَوْ أُنثَىٰ وَهُوَ مُؤْمِنٌۭ فَلَنُحْيِيَنَّهُۥ حَيَوٰةًۭ طَيِّبَةًۭ ۖ وَلَنَجْزِيَنَّهُمْ أَجْرَهُم بِأَحْسَنِ مَا كَانُوا۟ يَعْمَلُونَ', 'من عمل صلحا من ذكر أو أنثى وهو مؤمن فلنحيينه حيوة طيبة  ولنجزينهم أجرهم بأحسن ما كانوا يعملون', NULL, 278, 'local:hafs-text.json'),
  ('hafs-16-98', 'hafs', 16, 98, 'فَإِذَا قَرَأْتَ ٱلْقُرْءَانَ فَٱسْتَعِذْ بِٱللَّهِ مِنَ ٱلشَّيْطَٰنِ ٱلرَّجِيمِ', 'فإذا قرأت القرءان فاستعذ بالله من الشيطن الرجيم', NULL, 278, 'local:hafs-text.json'),
  ('hafs-16-99', 'hafs', 16, 99, 'إِنَّهُۥ لَيْسَ لَهُۥ سُلْطَٰنٌ عَلَى ٱلَّذِينَ ءَامَنُوا۟ وَعَلَىٰ رَبِّهِمْ يَتَوَكَّلُونَ', 'إنه ليس له سلطن على الذين ءامنوا وعلى ربهم يتوكلون', NULL, 278, 'local:hafs-text.json')
insert into public.ayahs (id, riwayah, surah_number, ayah_number, text, simple_text, juz, page, source) values
  ('hafs-16-100', 'hafs', 16, 100, 'إِنَّمَا سُلْطَٰنُهُۥ عَلَى ٱلَّذِينَ يَتَوَلَّوْنَهُۥ وَٱلَّذِينَ هُم بِهِۦ مُشْرِكُونَ', 'إنما سلطنه على الذين يتولونه والذين هم به مشركون', NULL, 278, 'local:hafs-text.json'),
  ('hafs-16-101', 'hafs', 16, 101, 'وَإِذَا بَدَّلْنَآ ءَايَةًۭ مَّكَانَ ءَايَةٍۢ ۙ وَٱللَّهُ أَعْلَمُ بِمَا يُنَزِّلُ قَالُوٓا۟ إِنَّمَآ أَنتَ مُفْتَرٍۭ ۚ بَلْ أَكْثَرُهُمْ لَا يَعْلَمُونَ', 'وإذا بدلنا ءاية مكان ءاية  والله أعلم بما ينزل قالوا إنما أنت مفتر  بل أكثرهم لا يعلمون', NULL, 278, 'local:hafs-text.json'),
  ('hafs-16-102', 'hafs', 16, 102, 'قُلْ نَزَّلَهُۥ رُوحُ ٱلْقُدُسِ مِن رَّبِّكَ بِٱلْحَقِّ لِيُثَبِّتَ ٱلَّذِينَ ءَامَنُوا۟ وَهُدًۭى وَبُشْرَىٰ لِلْمُسْلِمِينَ', 'قل نزله روح القدس من ربك بالحق ليثبت الذين ءامنوا وهدى وبشرى للمسلمين', NULL, 278, 'local:hafs-text.json'),
  ('hafs-16-103', 'hafs', 16, 103, 'وَلَقَدْ نَعْلَمُ أَنَّهُمْ يَقُولُونَ إِنَّمَا يُعَلِّمُهُۥ بَشَرٌۭ ۗ لِّسَانُ ٱلَّذِى يُلْحِدُونَ إِلَيْهِ أَعْجَمِىٌّۭ وَهَٰذَا لِسَانٌ عَرَبِىٌّۭ مُّبِينٌ', 'ولقد نعلم أنهم يقولون إنما يعلمه بشر  لسان الذى يلحدون إليه أعجمى وهذا لسان عربى مبين', NULL, 279, 'local:hafs-text.json'),
  ('hafs-16-104', 'hafs', 16, 104, 'إِنَّ ٱلَّذِينَ لَا يُؤْمِنُونَ بِـَٔايَٰتِ ٱللَّهِ لَا يَهْدِيهِمُ ٱللَّهُ وَلَهُمْ عَذَابٌ أَلِيمٌ', 'إن الذين لا يؤمنون بايت الله لا يهديهم الله ولهم عذاب أليم', NULL, 279, 'local:hafs-text.json'),
  ('hafs-16-105', 'hafs', 16, 105, 'إِنَّمَا يَفْتَرِى ٱلْكَذِبَ ٱلَّذِينَ لَا يُؤْمِنُونَ بِـَٔايَٰتِ ٱللَّهِ ۖ وَأُو۟لَٰٓئِكَ هُمُ ٱلْكَٰذِبُونَ', 'إنما يفترى الكذب الذين لا يؤمنون بايت الله  وأولئك هم الكذبون', NULL, 279, 'local:hafs-text.json'),
  ('hafs-16-106', 'hafs', 16, 106, 'مَن كَفَرَ بِٱللَّهِ مِنۢ بَعْدِ إِيمَٰنِهِۦٓ إِلَّا مَنْ أُكْرِهَ وَقَلْبُهُۥ مُطْمَئِنٌّۢ بِٱلْإِيمَٰنِ وَلَٰكِن مَّن شَرَحَ بِٱلْكُفْرِ صَدْرًۭا فَعَلَيْهِمْ غَضَبٌۭ مِّنَ ٱللَّهِ وَلَهُمْ عَذَابٌ عَظِيمٌۭ', 'من كفر بالله من بعد إيمنه إلا من أكره وقلبه مطمئن بالإيمن ولكن من شرح بالكفر صدرا فعليهم غضب من الله ولهم عذاب عظيم', NULL, 279, 'local:hafs-text.json'),
  ('hafs-16-107', 'hafs', 16, 107, 'ذَٰلِكَ بِأَنَّهُمُ ٱسْتَحَبُّوا۟ ٱلْحَيَوٰةَ ٱلدُّنْيَا عَلَى ٱلْءَاخِرَةِ وَأَنَّ ٱللَّهَ لَا يَهْدِى ٱلْقَوْمَ ٱلْكَٰفِرِينَ', 'ذلك بأنهم استحبوا الحيوة الدنيا على الءاخرة وأن الله لا يهدى القوم الكفرين', NULL, 279, 'local:hafs-text.json'),
  ('hafs-16-108', 'hafs', 16, 108, 'أُو۟لَٰٓئِكَ ٱلَّذِينَ طَبَعَ ٱللَّهُ عَلَىٰ قُلُوبِهِمْ وَسَمْعِهِمْ وَأَبْصَٰرِهِمْ ۖ وَأُو۟لَٰٓئِكَ هُمُ ٱلْغَٰفِلُونَ', 'أولئك الذين طبع الله على قلوبهم وسمعهم وأبصرهم  وأولئك هم الغفلون', NULL, 279, 'local:hafs-text.json'),
  ('hafs-16-109', 'hafs', 16, 109, 'لَا جَرَمَ أَنَّهُمْ فِى ٱلْءَاخِرَةِ هُمُ ٱلْخَٰسِرُونَ', 'لا جرم أنهم فى الءاخرة هم الخسرون', NULL, 279, 'local:hafs-text.json'),
  ('hafs-16-110', 'hafs', 16, 110, 'ثُمَّ إِنَّ رَبَّكَ لِلَّذِينَ هَاجَرُوا۟ مِنۢ بَعْدِ مَا فُتِنُوا۟ ثُمَّ جَٰهَدُوا۟ وَصَبَرُوٓا۟ إِنَّ رَبَّكَ مِنۢ بَعْدِهَا لَغَفُورٌۭ رَّحِيمٌۭ', 'ثم إن ربك للذين هاجروا من بعد ما فتنوا ثم جهدوا وصبروا إن ربك من بعدها لغفور رحيم', NULL, 279, 'local:hafs-text.json'),
  ('hafs-16-111', 'hafs', 16, 111, '۞ يَوْمَ تَأْتِى كُلُّ نَفْسٍۢ تُجَٰدِلُ عَن نَّفْسِهَا وَتُوَفَّىٰ كُلُّ نَفْسٍۢ مَّا عَمِلَتْ وَهُمْ لَا يُظْلَمُونَ', 'يوم تأتى كل نفس تجدل عن نفسها وتوفى كل نفس ما عملت وهم لا يظلمون', NULL, 280, 'local:hafs-text.json'),
  ('hafs-16-112', 'hafs', 16, 112, 'وَضَرَبَ ٱللَّهُ مَثَلًۭا قَرْيَةًۭ كَانَتْ ءَامِنَةًۭ مُّطْمَئِنَّةًۭ يَأْتِيهَا رِزْقُهَا رَغَدًۭا مِّن كُلِّ مَكَانٍۢ فَكَفَرَتْ بِأَنْعُمِ ٱللَّهِ فَأَذَٰقَهَا ٱللَّهُ لِبَاسَ ٱلْجُوعِ وَٱلْخَوْفِ بِمَا كَانُوا۟ يَصْنَعُونَ', 'وضرب الله مثلا قرية كانت ءامنة مطمئنة يأتيها رزقها رغدا من كل مكان فكفرت بأنعم الله فأذقها الله لباس الجوع والخوف بما كانوا يصنعون', NULL, 280, 'local:hafs-text.json'),
  ('hafs-16-113', 'hafs', 16, 113, 'وَلَقَدْ جَآءَهُمْ رَسُولٌۭ مِّنْهُمْ فَكَذَّبُوهُ فَأَخَذَهُمُ ٱلْعَذَابُ وَهُمْ ظَٰلِمُونَ', 'ولقد جاءهم رسول منهم فكذبوه فأخذهم العذاب وهم ظلمون', NULL, 280, 'local:hafs-text.json'),
  ('hafs-16-114', 'hafs', 16, 114, 'فَكُلُوا۟ مِمَّا رَزَقَكُمُ ٱللَّهُ حَلَٰلًۭا طَيِّبًۭا وَٱشْكُرُوا۟ نِعْمَتَ ٱللَّهِ إِن كُنتُمْ إِيَّاهُ تَعْبُدُونَ', 'فكلوا مما رزقكم الله حللا طيبا واشكروا نعمت الله إن كنتم إياه تعبدون', NULL, 280, 'local:hafs-text.json'),
  ('hafs-16-115', 'hafs', 16, 115, 'إِنَّمَا حَرَّمَ عَلَيْكُمُ ٱلْمَيْتَةَ وَٱلدَّمَ وَلَحْمَ ٱلْخِنزِيرِ وَمَآ أُهِلَّ لِغَيْرِ ٱللَّهِ بِهِۦ ۖ فَمَنِ ٱضْطُرَّ غَيْرَ بَاغٍۢ وَلَا عَادٍۢ فَإِنَّ ٱللَّهَ غَفُورٌۭ رَّحِيمٌۭ', 'إنما حرم عليكم الميتة والدم ولحم الخنزير وما أهل لغير الله به  فمن اضطر غير باغ ولا عاد فإن الله غفور رحيم', NULL, 280, 'local:hafs-text.json'),
  ('hafs-16-116', 'hafs', 16, 116, 'وَلَا تَقُولُوا۟ لِمَا تَصِفُ أَلْسِنَتُكُمُ ٱلْكَذِبَ هَٰذَا حَلَٰلٌۭ وَهَٰذَا حَرَامٌۭ لِّتَفْتَرُوا۟ عَلَى ٱللَّهِ ٱلْكَذِبَ ۚ إِنَّ ٱلَّذِينَ يَفْتَرُونَ عَلَى ٱللَّهِ ٱلْكَذِبَ لَا يُفْلِحُونَ', 'ولا تقولوا لما تصف ألسنتكم الكذب هذا حلل وهذا حرام لتفتروا على الله الكذب  إن الذين يفترون على الله الكذب لا يفلحون', NULL, 280, 'local:hafs-text.json'),
  ('hafs-16-117', 'hafs', 16, 117, 'مَتَٰعٌۭ قَلِيلٌۭ وَلَهُمْ عَذَابٌ أَلِيمٌۭ', 'متع قليل ولهم عذاب أليم', NULL, 280, 'local:hafs-text.json'),
  ('hafs-16-118', 'hafs', 16, 118, 'وَعَلَى ٱلَّذِينَ هَادُوا۟ حَرَّمْنَا مَا قَصَصْنَا عَلَيْكَ مِن قَبْلُ ۖ وَمَا ظَلَمْنَٰهُمْ وَلَٰكِن كَانُوٓا۟ أَنفُسَهُمْ يَظْلِمُونَ', 'وعلى الذين هادوا حرمنا ما قصصنا عليك من قبل  وما ظلمنهم ولكن كانوا أنفسهم يظلمون', NULL, 280, 'local:hafs-text.json'),
  ('hafs-16-119', 'hafs', 16, 119, 'ثُمَّ إِنَّ رَبَّكَ لِلَّذِينَ عَمِلُوا۟ ٱلسُّوٓءَ بِجَهَٰلَةٍۢ ثُمَّ تَابُوا۟ مِنۢ بَعْدِ ذَٰلِكَ وَأَصْلَحُوٓا۟ إِنَّ رَبَّكَ مِنۢ بَعْدِهَا لَغَفُورٌۭ رَّحِيمٌ', 'ثم إن ربك للذين عملوا السوء بجهلة ثم تابوا من بعد ذلك وأصلحوا إن ربك من بعدها لغفور رحيم', NULL, 281, 'local:hafs-text.json'),
  ('hafs-16-120', 'hafs', 16, 120, 'إِنَّ إِبْرَٰهِيمَ كَانَ أُمَّةًۭ قَانِتًۭا لِّلَّهِ حَنِيفًۭا وَلَمْ يَكُ مِنَ ٱلْمُشْرِكِينَ', 'إن إبرهيم كان أمة قانتا لله حنيفا ولم يك من المشركين', NULL, 281, 'local:hafs-text.json'),
  ('hafs-16-121', 'hafs', 16, 121, 'شَاكِرًۭا لِّأَنْعُمِهِ ۚ ٱجْتَبَىٰهُ وَهَدَىٰهُ إِلَىٰ صِرَٰطٍۢ مُّسْتَقِيمٍۢ', 'شاكرا لأنعمه  اجتبىه وهدىه إلى صرط مستقيم', NULL, 281, 'local:hafs-text.json'),
  ('hafs-16-122', 'hafs', 16, 122, 'وَءَاتَيْنَٰهُ فِى ٱلدُّنْيَا حَسَنَةًۭ ۖ وَإِنَّهُۥ فِى ٱلْءَاخِرَةِ لَمِنَ ٱلصَّٰلِحِينَ', 'وءاتينه فى الدنيا حسنة  وإنه فى الءاخرة لمن الصلحين', NULL, 281, 'local:hafs-text.json'),
  ('hafs-16-123', 'hafs', 16, 123, 'ثُمَّ أَوْحَيْنَآ إِلَيْكَ أَنِ ٱتَّبِعْ مِلَّةَ إِبْرَٰهِيمَ حَنِيفًۭا ۖ وَمَا كَانَ مِنَ ٱلْمُشْرِكِينَ', 'ثم أوحينا إليك أن اتبع ملة إبرهيم حنيفا  وما كان من المشركين', NULL, 281, 'local:hafs-text.json'),
  ('hafs-16-124', 'hafs', 16, 124, 'إِنَّمَا جُعِلَ ٱلسَّبْتُ عَلَى ٱلَّذِينَ ٱخْتَلَفُوا۟ فِيهِ ۚ وَإِنَّ رَبَّكَ لَيَحْكُمُ بَيْنَهُمْ يَوْمَ ٱلْقِيَٰمَةِ فِيمَا كَانُوا۟ فِيهِ يَخْتَلِفُونَ', 'إنما جعل السبت على الذين اختلفوا فيه  وإن ربك ليحكم بينهم يوم القيمة فيما كانوا فيه يختلفون', NULL, 281, 'local:hafs-text.json'),
  ('hafs-16-125', 'hafs', 16, 125, 'ٱدْعُ إِلَىٰ سَبِيلِ رَبِّكَ بِٱلْحِكْمَةِ وَٱلْمَوْعِظَةِ ٱلْحَسَنَةِ ۖ وَجَٰدِلْهُم بِٱلَّتِى هِىَ أَحْسَنُ ۚ إِنَّ رَبَّكَ هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِۦ ۖ وَهُوَ أَعْلَمُ بِٱلْمُهْتَدِينَ', 'ادع إلى سبيل ربك بالحكمة والموعظة الحسنة  وجدلهم بالتى هى أحسن  إن ربك هو أعلم بمن ضل عن سبيله  وهو أعلم بالمهتدين', NULL, 281, 'local:hafs-text.json'),
  ('hafs-16-126', 'hafs', 16, 126, 'وَإِنْ عَاقَبْتُمْ فَعَاقِبُوا۟ بِمِثْلِ مَا عُوقِبْتُم بِهِۦ ۖ وَلَئِن صَبَرْتُمْ لَهُوَ خَيْرٌۭ لِّلصَّٰبِرِينَ', 'وإن عاقبتم فعاقبوا بمثل ما عوقبتم به  ولئن صبرتم لهو خير للصبرين', NULL, 281, 'local:hafs-text.json'),
  ('hafs-16-127', 'hafs', 16, 127, 'وَٱصْبِرْ وَمَا صَبْرُكَ إِلَّا بِٱللَّهِ ۚ وَلَا تَحْزَنْ عَلَيْهِمْ وَلَا تَكُ فِى ضَيْقٍۢ مِّمَّا يَمْكُرُونَ', 'واصبر وما صبرك إلا بالله  ولا تحزن عليهم ولا تك فى ضيق مما يمكرون', NULL, 281, 'local:hafs-text.json'),
  ('hafs-16-128', 'hafs', 16, 128, 'إِنَّ ٱللَّهَ مَعَ ٱلَّذِينَ ٱتَّقَوا۟ وَّٱلَّذِينَ هُم مُّحْسِنُونَ', 'إن الله مع الذين اتقوا والذين هم محسنون', NULL, 281, 'local:hafs-text.json'),
  ('hafs-17-1', 'hafs', 17, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ سُبْحَٰنَ ٱلَّذِىٓ أَسْرَىٰ بِعَبْدِهِۦ لَيْلًۭا مِّنَ ٱلْمَسْجِدِ ٱلْحَرَامِ إِلَى ٱلْمَسْجِدِ ٱلْأَقْصَا ٱلَّذِى بَٰرَكْنَا حَوْلَهُۥ لِنُرِيَهُۥ مِنْ ءَايَٰتِنَآ ۚ إِنَّهُۥ هُوَ ٱلسَّمِيعُ ٱلْبَصِيرُ', 'بسم الله الرحمن الرحيم سبحن الذى أسرى بعبده ليلا من المسجد الحرام إلى المسجد الأقصا الذى بركنا حوله لنريه من ءايتنا  إنه هو السميع البصير', NULL, 282, 'local:hafs-text.json'),
  ('hafs-17-2', 'hafs', 17, 2, 'وَءَاتَيْنَا مُوسَى ٱلْكِتَٰبَ وَجَعَلْنَٰهُ هُدًۭى لِّبَنِىٓ إِسْرَٰٓءِيلَ أَلَّا تَتَّخِذُوا۟ مِن دُونِى وَكِيلًۭا', 'وءاتينا موسى الكتب وجعلنه هدى لبنى إسرءيل ألا تتخذوا من دونى وكيلا', NULL, 282, 'local:hafs-text.json'),
  ('hafs-17-3', 'hafs', 17, 3, 'ذُرِّيَّةَ مَنْ حَمَلْنَا مَعَ نُوحٍ ۚ إِنَّهُۥ كَانَ عَبْدًۭا شَكُورًۭا', 'ذرية من حملنا مع نوح  إنه كان عبدا شكورا', NULL, 282, 'local:hafs-text.json'),
  ('hafs-17-4', 'hafs', 17, 4, 'وَقَضَيْنَآ إِلَىٰ بَنِىٓ إِسْرَٰٓءِيلَ فِى ٱلْكِتَٰبِ لَتُفْسِدُنَّ فِى ٱلْأَرْضِ مَرَّتَيْنِ وَلَتَعْلُنَّ عُلُوًّۭا كَبِيرًۭا', 'وقضينا إلى بنى إسرءيل فى الكتب لتفسدن فى الأرض مرتين ولتعلن علوا كبيرا', NULL, 282, 'local:hafs-text.json'),
  ('hafs-17-5', 'hafs', 17, 5, 'فَإِذَا جَآءَ وَعْدُ أُولَىٰهُمَا بَعَثْنَا عَلَيْكُمْ عِبَادًۭا لَّنَآ أُو۟لِى بَأْسٍۢ شَدِيدٍۢ فَجَاسُوا۟ خِلَٰلَ ٱلدِّيَارِ ۚ وَكَانَ وَعْدًۭا مَّفْعُولًۭا', 'فإذا جاء وعد أولىهما بعثنا عليكم عبادا لنا أولى بأس شديد فجاسوا خلل الديار  وكان وعدا مفعولا', NULL, 282, 'local:hafs-text.json'),
  ('hafs-17-6', 'hafs', 17, 6, 'ثُمَّ رَدَدْنَا لَكُمُ ٱلْكَرَّةَ عَلَيْهِمْ وَأَمْدَدْنَٰكُم بِأَمْوَٰلٍۢ وَبَنِينَ وَجَعَلْنَٰكُمْ أَكْثَرَ نَفِيرًا', 'ثم رددنا لكم الكرة عليهم وأمددنكم بأمول وبنين وجعلنكم أكثر نفيرا', NULL, 282, 'local:hafs-text.json'),
  ('hafs-17-7', 'hafs', 17, 7, 'إِنْ أَحْسَنتُمْ أَحْسَنتُمْ لِأَنفُسِكُمْ ۖ وَإِنْ أَسَأْتُمْ فَلَهَا ۚ فَإِذَا جَآءَ وَعْدُ ٱلْءَاخِرَةِ لِيَسُۥٓـُٔوا۟ وُجُوهَكُمْ وَلِيَدْخُلُوا۟ ٱلْمَسْجِدَ كَمَا دَخَلُوهُ أَوَّلَ مَرَّةٍۢ وَلِيُتَبِّرُوا۟ مَا عَلَوْا۟ تَتْبِيرًا', 'إن أحسنتم أحسنتم لأنفسكم  وإن أسأتم فلها  فإذا جاء وعد الءاخرة ليسوا وجوهكم وليدخلوا المسجد كما دخلوه أول مرة وليتبروا ما علوا تتبيرا', NULL, 282, 'local:hafs-text.json'),
  ('hafs-17-8', 'hafs', 17, 8, 'عَسَىٰ رَبُّكُمْ أَن يَرْحَمَكُمْ ۚ وَإِنْ عُدتُّمْ عُدْنَا ۘ وَجَعَلْنَا جَهَنَّمَ لِلْكَٰفِرِينَ حَصِيرًا', 'عسى ربكم أن يرحمكم  وإن عدتم عدنا  وجعلنا جهنم للكفرين حصيرا', NULL, 283, 'local:hafs-text.json'),
  ('hafs-17-9', 'hafs', 17, 9, 'إِنَّ هَٰذَا ٱلْقُرْءَانَ يَهْدِى لِلَّتِى هِىَ أَقْوَمُ وَيُبَشِّرُ ٱلْمُؤْمِنِينَ ٱلَّذِينَ يَعْمَلُونَ ٱلصَّٰلِحَٰتِ أَنَّ لَهُمْ أَجْرًۭا كَبِيرًۭا', 'إن هذا القرءان يهدى للتى هى أقوم ويبشر المؤمنين الذين يعملون الصلحت أن لهم أجرا كبيرا', NULL, 283, 'local:hafs-text.json'),
  ('hafs-17-10', 'hafs', 17, 10, 'وَأَنَّ ٱلَّذِينَ لَا يُؤْمِنُونَ بِٱلْءَاخِرَةِ أَعْتَدْنَا لَهُمْ عَذَابًا أَلِيمًۭا', 'وأن الذين لا يؤمنون بالءاخرة أعتدنا لهم عذابا أليما', NULL, 283, 'local:hafs-text.json'),
  ('hafs-17-11', 'hafs', 17, 11, 'وَيَدْعُ ٱلْإِنسَٰنُ بِٱلشَّرِّ دُعَآءَهُۥ بِٱلْخَيْرِ ۖ وَكَانَ ٱلْإِنسَٰنُ عَجُولًۭا', 'ويدع الإنسن بالشر دعاءه بالخير  وكان الإنسن عجولا', NULL, 283, 'local:hafs-text.json'),
  ('hafs-17-12', 'hafs', 17, 12, 'وَجَعَلْنَا ٱلَّيْلَ وَٱلنَّهَارَ ءَايَتَيْنِ ۖ فَمَحَوْنَآ ءَايَةَ ٱلَّيْلِ وَجَعَلْنَآ ءَايَةَ ٱلنَّهَارِ مُبْصِرَةًۭ لِّتَبْتَغُوا۟ فَضْلًۭا مِّن رَّبِّكُمْ وَلِتَعْلَمُوا۟ عَدَدَ ٱلسِّنِينَ وَٱلْحِسَابَ ۚ وَكُلَّ شَىْءٍۢ فَصَّلْنَٰهُ تَفْصِيلًۭا', 'وجعلنا اليل والنهار ءايتين  فمحونا ءاية اليل وجعلنا ءاية النهار مبصرة لتبتغوا فضلا من ربكم ولتعلموا عدد السنين والحساب  وكل شىء فصلنه تفصيلا', NULL, 283, 'local:hafs-text.json'),
  ('hafs-17-13', 'hafs', 17, 13, 'وَكُلَّ إِنسَٰنٍ أَلْزَمْنَٰهُ طَٰٓئِرَهُۥ فِى عُنُقِهِۦ ۖ وَنُخْرِجُ لَهُۥ يَوْمَ ٱلْقِيَٰمَةِ كِتَٰبًۭا يَلْقَىٰهُ مَنشُورًا', 'وكل إنسن ألزمنه طئره فى عنقه  ونخرج له يوم القيمة كتبا يلقىه منشورا', NULL, 283, 'local:hafs-text.json'),
  ('hafs-17-14', 'hafs', 17, 14, 'ٱقْرَأْ كِتَٰبَكَ كَفَىٰ بِنَفْسِكَ ٱلْيَوْمَ عَلَيْكَ حَسِيبًۭا', 'اقرأ كتبك كفى بنفسك اليوم عليك حسيبا', NULL, 283, 'local:hafs-text.json'),
  ('hafs-17-15', 'hafs', 17, 15, 'مَّنِ ٱهْتَدَىٰ فَإِنَّمَا يَهْتَدِى لِنَفْسِهِۦ ۖ وَمَن ضَلَّ فَإِنَّمَا يَضِلُّ عَلَيْهَا ۚ وَلَا تَزِرُ وَازِرَةٌۭ وِزْرَ أُخْرَىٰ ۗ وَمَا كُنَّا مُعَذِّبِينَ حَتَّىٰ نَبْعَثَ رَسُولًۭا', 'من اهتدى فإنما يهتدى لنفسه  ومن ضل فإنما يضل عليها  ولا تزر وازرة وزر أخرى  وما كنا معذبين حتى نبعث رسولا', NULL, 283, 'local:hafs-text.json'),
  ('hafs-17-16', 'hafs', 17, 16, 'وَإِذَآ أَرَدْنَآ أَن نُّهْلِكَ قَرْيَةً أَمَرْنَا مُتْرَفِيهَا فَفَسَقُوا۟ فِيهَا فَحَقَّ عَلَيْهَا ٱلْقَوْلُ فَدَمَّرْنَٰهَا تَدْمِيرًۭا', 'وإذا أردنا أن نهلك قرية أمرنا مترفيها ففسقوا فيها فحق عليها القول فدمرنها تدميرا', NULL, 283, 'local:hafs-text.json'),
  ('hafs-17-17', 'hafs', 17, 17, 'وَكَمْ أَهْلَكْنَا مِنَ ٱلْقُرُونِ مِنۢ بَعْدِ نُوحٍۢ ۗ وَكَفَىٰ بِرَبِّكَ بِذُنُوبِ عِبَادِهِۦ خَبِيرًۢا بَصِيرًۭا', 'وكم أهلكنا من القرون من بعد نوح  وكفى بربك بذنوب عباده خبيرا بصيرا', NULL, 283, 'local:hafs-text.json'),
  ('hafs-17-18', 'hafs', 17, 18, 'مَّن كَانَ يُرِيدُ ٱلْعَاجِلَةَ عَجَّلْنَا لَهُۥ فِيهَا مَا نَشَآءُ لِمَن نُّرِيدُ ثُمَّ جَعَلْنَا لَهُۥ جَهَنَّمَ يَصْلَىٰهَا مَذْمُومًۭا مَّدْحُورًۭا', 'من كان يريد العاجلة عجلنا له فيها ما نشاء لمن نريد ثم جعلنا له جهنم يصلىها مذموما مدحورا', NULL, 284, 'local:hafs-text.json'),
  ('hafs-17-19', 'hafs', 17, 19, 'وَمَنْ أَرَادَ ٱلْءَاخِرَةَ وَسَعَىٰ لَهَا سَعْيَهَا وَهُوَ مُؤْمِنٌۭ فَأُو۟لَٰٓئِكَ كَانَ سَعْيُهُم مَّشْكُورًۭا', 'ومن أراد الءاخرة وسعى لها سعيها وهو مؤمن فأولئك كان سعيهم مشكورا', NULL, 284, 'local:hafs-text.json'),
  ('hafs-17-20', 'hafs', 17, 20, 'كُلًّۭا نُّمِدُّ هَٰٓؤُلَآءِ وَهَٰٓؤُلَآءِ مِنْ عَطَآءِ رَبِّكَ ۚ وَمَا كَانَ عَطَآءُ رَبِّكَ مَحْظُورًا', 'كلا نمد هؤلاء وهؤلاء من عطاء ربك  وما كان عطاء ربك محظورا', NULL, 284, 'local:hafs-text.json'),
  ('hafs-17-21', 'hafs', 17, 21, 'ٱنظُرْ كَيْفَ فَضَّلْنَا بَعْضَهُمْ عَلَىٰ بَعْضٍۢ ۚ وَلَلْءَاخِرَةُ أَكْبَرُ دَرَجَٰتٍۢ وَأَكْبَرُ تَفْضِيلًۭا', 'انظر كيف فضلنا بعضهم على بعض  وللءاخرة أكبر درجت وأكبر تفضيلا', NULL, 284, 'local:hafs-text.json'),
  ('hafs-17-22', 'hafs', 17, 22, 'لَّا تَجْعَلْ مَعَ ٱللَّهِ إِلَٰهًا ءَاخَرَ فَتَقْعُدَ مَذْمُومًۭا مَّخْذُولًۭا', 'لا تجعل مع الله إلها ءاخر فتقعد مذموما مخذولا', NULL, 284, 'local:hafs-text.json'),
  ('hafs-17-23', 'hafs', 17, 23, '۞ وَقَضَىٰ رَبُّكَ أَلَّا تَعْبُدُوٓا۟ إِلَّآ إِيَّاهُ وَبِٱلْوَٰلِدَيْنِ إِحْسَٰنًا ۚ إِمَّا يَبْلُغَنَّ عِندَكَ ٱلْكِبَرَ أَحَدُهُمَآ أَوْ كِلَاهُمَا فَلَا تَقُل لَّهُمَآ أُفٍّۢ وَلَا تَنْهَرْهُمَا وَقُل لَّهُمَا قَوْلًۭا كَرِيمًۭا', 'وقضى ربك ألا تعبدوا إلا إياه وبالولدين إحسنا  إما يبلغن عندك الكبر أحدهما أو كلاهما فلا تقل لهما أف ولا تنهرهما وقل لهما قولا كريما', NULL, 284, 'local:hafs-text.json'),
  ('hafs-17-24', 'hafs', 17, 24, 'وَٱخْفِضْ لَهُمَا جَنَاحَ ٱلذُّلِّ مِنَ ٱلرَّحْمَةِ وَقُل رَّبِّ ٱرْحَمْهُمَا كَمَا رَبَّيَانِى صَغِيرًۭا', 'واخفض لهما جناح الذل من الرحمة وقل رب ارحمهما كما ربيانى صغيرا', NULL, 284, 'local:hafs-text.json'),
  ('hafs-17-25', 'hafs', 17, 25, 'رَّبُّكُمْ أَعْلَمُ بِمَا فِى نُفُوسِكُمْ ۚ إِن تَكُونُوا۟ صَٰلِحِينَ فَإِنَّهُۥ كَانَ لِلْأَوَّٰبِينَ غَفُورًۭا', 'ربكم أعلم بما فى نفوسكم  إن تكونوا صلحين فإنه كان للأوبين غفورا', NULL, 284, 'local:hafs-text.json'),
  ('hafs-17-26', 'hafs', 17, 26, 'وَءَاتِ ذَا ٱلْقُرْبَىٰ حَقَّهُۥ وَٱلْمِسْكِينَ وَٱبْنَ ٱلسَّبِيلِ وَلَا تُبَذِّرْ تَبْذِيرًا', 'وءات ذا القربى حقه والمسكين وابن السبيل ولا تبذر تبذيرا', NULL, 284, 'local:hafs-text.json'),
  ('hafs-17-27', 'hafs', 17, 27, 'إِنَّ ٱلْمُبَذِّرِينَ كَانُوٓا۟ إِخْوَٰنَ ٱلشَّيَٰطِينِ ۖ وَكَانَ ٱلشَّيْطَٰنُ لِرَبِّهِۦ كَفُورًۭا', 'إن المبذرين كانوا إخون الشيطين  وكان الشيطن لربه كفورا', NULL, 284, 'local:hafs-text.json'),
  ('hafs-17-28', 'hafs', 17, 28, 'وَإِمَّا تُعْرِضَنَّ عَنْهُمُ ٱبْتِغَآءَ رَحْمَةٍۢ مِّن رَّبِّكَ تَرْجُوهَا فَقُل لَّهُمْ قَوْلًۭا مَّيْسُورًۭا', 'وإما تعرضن عنهم ابتغاء رحمة من ربك ترجوها فقل لهم قولا ميسورا', NULL, 285, 'local:hafs-text.json'),
  ('hafs-17-29', 'hafs', 17, 29, 'وَلَا تَجْعَلْ يَدَكَ مَغْلُولَةً إِلَىٰ عُنُقِكَ وَلَا تَبْسُطْهَا كُلَّ ٱلْبَسْطِ فَتَقْعُدَ مَلُومًۭا مَّحْسُورًا', 'ولا تجعل يدك مغلولة إلى عنقك ولا تبسطها كل البسط فتقعد ملوما محسورا', NULL, 285, 'local:hafs-text.json'),
  ('hafs-17-30', 'hafs', 17, 30, 'إِنَّ رَبَّكَ يَبْسُطُ ٱلرِّزْقَ لِمَن يَشَآءُ وَيَقْدِرُ ۚ إِنَّهُۥ كَانَ بِعِبَادِهِۦ خَبِيرًۢا بَصِيرًۭا', 'إن ربك يبسط الرزق لمن يشاء ويقدر  إنه كان بعباده خبيرا بصيرا', NULL, 285, 'local:hafs-text.json'),
  ('hafs-17-31', 'hafs', 17, 31, 'وَلَا تَقْتُلُوٓا۟ أَوْلَٰدَكُمْ خَشْيَةَ إِمْلَٰقٍۢ ۖ نَّحْنُ نَرْزُقُهُمْ وَإِيَّاكُمْ ۚ إِنَّ قَتْلَهُمْ كَانَ خِطْـًۭٔا كَبِيرًۭا', 'ولا تقتلوا أولدكم خشية إملق  نحن نرزقهم وإياكم  إن قتلهم كان خطا كبيرا', NULL, 285, 'local:hafs-text.json'),
  ('hafs-17-32', 'hafs', 17, 32, 'وَلَا تَقْرَبُوا۟ ٱلزِّنَىٰٓ ۖ إِنَّهُۥ كَانَ فَٰحِشَةًۭ وَسَآءَ سَبِيلًۭا', 'ولا تقربوا الزنى  إنه كان فحشة وساء سبيلا', NULL, 285, 'local:hafs-text.json'),
  ('hafs-17-33', 'hafs', 17, 33, 'وَلَا تَقْتُلُوا۟ ٱلنَّفْسَ ٱلَّتِى حَرَّمَ ٱللَّهُ إِلَّا بِٱلْحَقِّ ۗ وَمَن قُتِلَ مَظْلُومًۭا فَقَدْ جَعَلْنَا لِوَلِيِّهِۦ سُلْطَٰنًۭا فَلَا يُسْرِف فِّى ٱلْقَتْلِ ۖ إِنَّهُۥ كَانَ مَنصُورًۭا', 'ولا تقتلوا النفس التى حرم الله إلا بالحق  ومن قتل مظلوما فقد جعلنا لوليه سلطنا فلا يسرف فى القتل  إنه كان منصورا', NULL, 285, 'local:hafs-text.json'),
  ('hafs-17-34', 'hafs', 17, 34, 'وَلَا تَقْرَبُوا۟ مَالَ ٱلْيَتِيمِ إِلَّا بِٱلَّتِى هِىَ أَحْسَنُ حَتَّىٰ يَبْلُغَ أَشُدَّهُۥ ۚ وَأَوْفُوا۟ بِٱلْعَهْدِ ۖ إِنَّ ٱلْعَهْدَ كَانَ مَسْـُٔولًۭا', 'ولا تقربوا مال اليتيم إلا بالتى هى أحسن حتى يبلغ أشده  وأوفوا بالعهد  إن العهد كان مسولا', NULL, 285, 'local:hafs-text.json'),
  ('hafs-17-35', 'hafs', 17, 35, 'وَأَوْفُوا۟ ٱلْكَيْلَ إِذَا كِلْتُمْ وَزِنُوا۟ بِٱلْقِسْطَاسِ ٱلْمُسْتَقِيمِ ۚ ذَٰلِكَ خَيْرٌۭ وَأَحْسَنُ تَأْوِيلًۭا', 'وأوفوا الكيل إذا كلتم وزنوا بالقسطاس المستقيم  ذلك خير وأحسن تأويلا', NULL, 285, 'local:hafs-text.json'),
  ('hafs-17-36', 'hafs', 17, 36, 'وَلَا تَقْفُ مَا لَيْسَ لَكَ بِهِۦ عِلْمٌ ۚ إِنَّ ٱلسَّمْعَ وَٱلْبَصَرَ وَٱلْفُؤَادَ كُلُّ أُو۟لَٰٓئِكَ كَانَ عَنْهُ مَسْـُٔولًۭا', 'ولا تقف ما ليس لك به علم  إن السمع والبصر والفؤاد كل أولئك كان عنه مسولا', NULL, 285, 'local:hafs-text.json'),
  ('hafs-17-37', 'hafs', 17, 37, 'وَلَا تَمْشِ فِى ٱلْأَرْضِ مَرَحًا ۖ إِنَّكَ لَن تَخْرِقَ ٱلْأَرْضَ وَلَن تَبْلُغَ ٱلْجِبَالَ طُولًۭا', 'ولا تمش فى الأرض مرحا  إنك لن تخرق الأرض ولن تبلغ الجبال طولا', NULL, 285, 'local:hafs-text.json'),
  ('hafs-17-38', 'hafs', 17, 38, 'كُلُّ ذَٰلِكَ كَانَ سَيِّئُهُۥ عِندَ رَبِّكَ مَكْرُوهًۭا', 'كل ذلك كان سيئه عند ربك مكروها', NULL, 285, 'local:hafs-text.json'),
  ('hafs-17-39', 'hafs', 17, 39, 'ذَٰلِكَ مِمَّآ أَوْحَىٰٓ إِلَيْكَ رَبُّكَ مِنَ ٱلْحِكْمَةِ ۗ وَلَا تَجْعَلْ مَعَ ٱللَّهِ إِلَٰهًا ءَاخَرَ فَتُلْقَىٰ فِى جَهَنَّمَ مَلُومًۭا مَّدْحُورًا', 'ذلك مما أوحى إليك ربك من الحكمة  ولا تجعل مع الله إلها ءاخر فتلقى فى جهنم ملوما مدحورا', NULL, 286, 'local:hafs-text.json'),
  ('hafs-17-40', 'hafs', 17, 40, 'أَفَأَصْفَىٰكُمْ رَبُّكُم بِٱلْبَنِينَ وَٱتَّخَذَ مِنَ ٱلْمَلَٰٓئِكَةِ إِنَٰثًا ۚ إِنَّكُمْ لَتَقُولُونَ قَوْلًا عَظِيمًۭا', 'أفأصفىكم ربكم بالبنين واتخذ من الملئكة إنثا  إنكم لتقولون قولا عظيما', NULL, 286, 'local:hafs-text.json'),
  ('hafs-17-41', 'hafs', 17, 41, 'وَلَقَدْ صَرَّفْنَا فِى هَٰذَا ٱلْقُرْءَانِ لِيَذَّكَّرُوا۟ وَمَا يَزِيدُهُمْ إِلَّا نُفُورًۭا', 'ولقد صرفنا فى هذا القرءان ليذكروا وما يزيدهم إلا نفورا', NULL, 286, 'local:hafs-text.json'),
  ('hafs-17-42', 'hafs', 17, 42, 'قُل لَّوْ كَانَ مَعَهُۥٓ ءَالِهَةٌۭ كَمَا يَقُولُونَ إِذًۭا لَّٱبْتَغَوْا۟ إِلَىٰ ذِى ٱلْعَرْشِ سَبِيلًۭا', 'قل لو كان معه ءالهة كما يقولون إذا لابتغوا إلى ذى العرش سبيلا', NULL, 286, 'local:hafs-text.json'),
  ('hafs-17-43', 'hafs', 17, 43, 'سُبْحَٰنَهُۥ وَتَعَٰلَىٰ عَمَّا يَقُولُونَ عُلُوًّۭا كَبِيرًۭا', 'سبحنه وتعلى عما يقولون علوا كبيرا', NULL, 286, 'local:hafs-text.json'),
  ('hafs-17-44', 'hafs', 17, 44, 'تُسَبِّحُ لَهُ ٱلسَّمَٰوَٰتُ ٱلسَّبْعُ وَٱلْأَرْضُ وَمَن فِيهِنَّ ۚ وَإِن مِّن شَىْءٍ إِلَّا يُسَبِّحُ بِحَمْدِهِۦ وَلَٰكِن لَّا تَفْقَهُونَ تَسْبِيحَهُمْ ۗ إِنَّهُۥ كَانَ حَلِيمًا غَفُورًۭا', 'تسبح له السموت السبع والأرض ومن فيهن  وإن من شىء إلا يسبح بحمده ولكن لا تفقهون تسبيحهم  إنه كان حليما غفورا', NULL, 286, 'local:hafs-text.json'),
  ('hafs-17-45', 'hafs', 17, 45, 'وَإِذَا قَرَأْتَ ٱلْقُرْءَانَ جَعَلْنَا بَيْنَكَ وَبَيْنَ ٱلَّذِينَ لَا يُؤْمِنُونَ بِٱلْءَاخِرَةِ حِجَابًۭا مَّسْتُورًۭا', 'وإذا قرأت القرءان جعلنا بينك وبين الذين لا يؤمنون بالءاخرة حجابا مستورا', NULL, 286, 'local:hafs-text.json'),
  ('hafs-17-46', 'hafs', 17, 46, 'وَجَعَلْنَا عَلَىٰ قُلُوبِهِمْ أَكِنَّةً أَن يَفْقَهُوهُ وَفِىٓ ءَاذَانِهِمْ وَقْرًۭا ۚ وَإِذَا ذَكَرْتَ رَبَّكَ فِى ٱلْقُرْءَانِ وَحْدَهُۥ وَلَّوْا۟ عَلَىٰٓ أَدْبَٰرِهِمْ نُفُورًۭا', 'وجعلنا على قلوبهم أكنة أن يفقهوه وفى ءاذانهم وقرا  وإذا ذكرت ربك فى القرءان وحده ولوا على أدبرهم نفورا', NULL, 286, 'local:hafs-text.json'),
  ('hafs-17-47', 'hafs', 17, 47, 'نَّحْنُ أَعْلَمُ بِمَا يَسْتَمِعُونَ بِهِۦٓ إِذْ يَسْتَمِعُونَ إِلَيْكَ وَإِذْ هُمْ نَجْوَىٰٓ إِذْ يَقُولُ ٱلظَّٰلِمُونَ إِن تَتَّبِعُونَ إِلَّا رَجُلًۭا مَّسْحُورًا', 'نحن أعلم بما يستمعون به إذ يستمعون إليك وإذ هم نجوى إذ يقول الظلمون إن تتبعون إلا رجلا مسحورا', NULL, 286, 'local:hafs-text.json'),
  ('hafs-17-48', 'hafs', 17, 48, 'ٱنظُرْ كَيْفَ ضَرَبُوا۟ لَكَ ٱلْأَمْثَالَ فَضَلُّوا۟ فَلَا يَسْتَطِيعُونَ سَبِيلًۭا', 'انظر كيف ضربوا لك الأمثال فضلوا فلا يستطيعون سبيلا', NULL, 286, 'local:hafs-text.json'),
  ('hafs-17-49', 'hafs', 17, 49, 'وَقَالُوٓا۟ أَءِذَا كُنَّا عِظَٰمًۭا وَرُفَٰتًا أَءِنَّا لَمَبْعُوثُونَ خَلْقًۭا جَدِيدًۭا', 'وقالوا أءذا كنا عظما ورفتا أءنا لمبعوثون خلقا جديدا', NULL, 286, 'local:hafs-text.json'),
  ('hafs-17-50', 'hafs', 17, 50, '۞ قُلْ كُونُوا۟ حِجَارَةً أَوْ حَدِيدًا', 'قل كونوا حجارة أو حديدا', NULL, 287, 'local:hafs-text.json'),
  ('hafs-17-51', 'hafs', 17, 51, 'أَوْ خَلْقًۭا مِّمَّا يَكْبُرُ فِى صُدُورِكُمْ ۚ فَسَيَقُولُونَ مَن يُعِيدُنَا ۖ قُلِ ٱلَّذِى فَطَرَكُمْ أَوَّلَ مَرَّةٍۢ ۚ فَسَيُنْغِضُونَ إِلَيْكَ رُءُوسَهُمْ وَيَقُولُونَ مَتَىٰ هُوَ ۖ قُلْ عَسَىٰٓ أَن يَكُونَ قَرِيبًۭا', 'أو خلقا مما يكبر فى صدوركم  فسيقولون من يعيدنا  قل الذى فطركم أول مرة  فسينغضون إليك رءوسهم ويقولون متى هو  قل عسى أن يكون قريبا', NULL, 287, 'local:hafs-text.json'),
  ('hafs-17-52', 'hafs', 17, 52, 'يَوْمَ يَدْعُوكُمْ فَتَسْتَجِيبُونَ بِحَمْدِهِۦ وَتَظُنُّونَ إِن لَّبِثْتُمْ إِلَّا قَلِيلًۭا', 'يوم يدعوكم فتستجيبون بحمده وتظنون إن لبثتم إلا قليلا', NULL, 287, 'local:hafs-text.json'),
  ('hafs-17-53', 'hafs', 17, 53, 'وَقُل لِّعِبَادِى يَقُولُوا۟ ٱلَّتِى هِىَ أَحْسَنُ ۚ إِنَّ ٱلشَّيْطَٰنَ يَنزَغُ بَيْنَهُمْ ۚ إِنَّ ٱلشَّيْطَٰنَ كَانَ لِلْإِنسَٰنِ عَدُوًّۭا مُّبِينًۭا', 'وقل لعبادى يقولوا التى هى أحسن  إن الشيطن ينزغ بينهم  إن الشيطن كان للإنسن عدوا مبينا', NULL, 287, 'local:hafs-text.json'),
  ('hafs-17-54', 'hafs', 17, 54, 'رَّبُّكُمْ أَعْلَمُ بِكُمْ ۖ إِن يَشَأْ يَرْحَمْكُمْ أَوْ إِن يَشَأْ يُعَذِّبْكُمْ ۚ وَمَآ أَرْسَلْنَٰكَ عَلَيْهِمْ وَكِيلًۭا', 'ربكم أعلم بكم  إن يشأ يرحمكم أو إن يشأ يعذبكم  وما أرسلنك عليهم وكيلا', NULL, 287, 'local:hafs-text.json'),
  ('hafs-17-55', 'hafs', 17, 55, 'وَرَبُّكَ أَعْلَمُ بِمَن فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ ۗ وَلَقَدْ فَضَّلْنَا بَعْضَ ٱلنَّبِيِّۦنَ عَلَىٰ بَعْضٍۢ ۖ وَءَاتَيْنَا دَاوُۥدَ زَبُورًۭا', 'وربك أعلم بمن فى السموت والأرض  ولقد فضلنا بعض النبين على بعض  وءاتينا داود زبورا', NULL, 287, 'local:hafs-text.json'),
  ('hafs-17-56', 'hafs', 17, 56, 'قُلِ ٱدْعُوا۟ ٱلَّذِينَ زَعَمْتُم مِّن دُونِهِۦ فَلَا يَمْلِكُونَ كَشْفَ ٱلضُّرِّ عَنكُمْ وَلَا تَحْوِيلًا', 'قل ادعوا الذين زعمتم من دونه فلا يملكون كشف الضر عنكم ولا تحويلا', NULL, 287, 'local:hafs-text.json'),
  ('hafs-17-57', 'hafs', 17, 57, 'أُو۟لَٰٓئِكَ ٱلَّذِينَ يَدْعُونَ يَبْتَغُونَ إِلَىٰ رَبِّهِمُ ٱلْوَسِيلَةَ أَيُّهُمْ أَقْرَبُ وَيَرْجُونَ رَحْمَتَهُۥ وَيَخَافُونَ عَذَابَهُۥٓ ۚ إِنَّ عَذَابَ رَبِّكَ كَانَ مَحْذُورًۭا', 'أولئك الذين يدعون يبتغون إلى ربهم الوسيلة أيهم أقرب ويرجون رحمته ويخافون عذابه  إن عذاب ربك كان محذورا', NULL, 287, 'local:hafs-text.json'),
  ('hafs-17-58', 'hafs', 17, 58, 'وَإِن مِّن قَرْيَةٍ إِلَّا نَحْنُ مُهْلِكُوهَا قَبْلَ يَوْمِ ٱلْقِيَٰمَةِ أَوْ مُعَذِّبُوهَا عَذَابًۭا شَدِيدًۭا ۚ كَانَ ذَٰلِكَ فِى ٱلْكِتَٰبِ مَسْطُورًۭا', 'وإن من قرية إلا نحن مهلكوها قبل يوم القيمة أو معذبوها عذابا شديدا  كان ذلك فى الكتب مسطورا', NULL, 287, 'local:hafs-text.json'),
  ('hafs-17-59', 'hafs', 17, 59, 'وَمَا مَنَعَنَآ أَن نُّرْسِلَ بِٱلْءَايَٰتِ إِلَّآ أَن كَذَّبَ بِهَا ٱلْأَوَّلُونَ ۚ وَءَاتَيْنَا ثَمُودَ ٱلنَّاقَةَ مُبْصِرَةًۭ فَظَلَمُوا۟ بِهَا ۚ وَمَا نُرْسِلُ بِٱلْءَايَٰتِ إِلَّا تَخْوِيفًۭا', 'وما منعنا أن نرسل بالءايت إلا أن كذب بها الأولون  وءاتينا ثمود الناقة مبصرة فظلموا بها  وما نرسل بالءايت إلا تخويفا', NULL, 288, 'local:hafs-text.json'),
  ('hafs-17-60', 'hafs', 17, 60, 'وَإِذْ قُلْنَا لَكَ إِنَّ رَبَّكَ أَحَاطَ بِٱلنَّاسِ ۚ وَمَا جَعَلْنَا ٱلرُّءْيَا ٱلَّتِىٓ أَرَيْنَٰكَ إِلَّا فِتْنَةًۭ لِّلنَّاسِ وَٱلشَّجَرَةَ ٱلْمَلْعُونَةَ فِى ٱلْقُرْءَانِ ۚ وَنُخَوِّفُهُمْ فَمَا يَزِيدُهُمْ إِلَّا طُغْيَٰنًۭا كَبِيرًۭا', 'وإذ قلنا لك إن ربك أحاط بالناس  وما جعلنا الرءيا التى أرينك إلا فتنة للناس والشجرة الملعونة فى القرءان  ونخوفهم فما يزيدهم إلا طغينا كبيرا', NULL, 288, 'local:hafs-text.json'),
  ('hafs-17-61', 'hafs', 17, 61, 'وَإِذْ قُلْنَا لِلْمَلَٰٓئِكَةِ ٱسْجُدُوا۟ لِءَادَمَ فَسَجَدُوٓا۟ إِلَّآ إِبْلِيسَ قَالَ ءَأَسْجُدُ لِمَنْ خَلَقْتَ طِينًۭا', 'وإذ قلنا للملئكة اسجدوا لءادم فسجدوا إلا إبليس قال ءأسجد لمن خلقت طينا', NULL, 288, 'local:hafs-text.json'),
  ('hafs-17-62', 'hafs', 17, 62, 'قَالَ أَرَءَيْتَكَ هَٰذَا ٱلَّذِى كَرَّمْتَ عَلَىَّ لَئِنْ أَخَّرْتَنِ إِلَىٰ يَوْمِ ٱلْقِيَٰمَةِ لَأَحْتَنِكَنَّ ذُرِّيَّتَهُۥٓ إِلَّا قَلِيلًۭا', 'قال أرءيتك هذا الذى كرمت على لئن أخرتن إلى يوم القيمة لأحتنكن ذريته إلا قليلا', NULL, 288, 'local:hafs-text.json'),
  ('hafs-17-63', 'hafs', 17, 63, 'قَالَ ٱذْهَبْ فَمَن تَبِعَكَ مِنْهُمْ فَإِنَّ جَهَنَّمَ جَزَآؤُكُمْ جَزَآءًۭ مَّوْفُورًۭا', 'قال اذهب فمن تبعك منهم فإن جهنم جزاؤكم جزاء موفورا', NULL, 288, 'local:hafs-text.json'),
  ('hafs-17-64', 'hafs', 17, 64, 'وَٱسْتَفْزِزْ مَنِ ٱسْتَطَعْتَ مِنْهُم بِصَوْتِكَ وَأَجْلِبْ عَلَيْهِم بِخَيْلِكَ وَرَجِلِكَ وَشَارِكْهُمْ فِى ٱلْأَمْوَٰلِ وَٱلْأَوْلَٰدِ وَعِدْهُمْ ۚ وَمَا يَعِدُهُمُ ٱلشَّيْطَٰنُ إِلَّا غُرُورًا', 'واستفزز من استطعت منهم بصوتك وأجلب عليهم بخيلك ورجلك وشاركهم فى الأمول والأولد وعدهم  وما يعدهم الشيطن إلا غرورا', NULL, 288, 'local:hafs-text.json'),
  ('hafs-17-65', 'hafs', 17, 65, 'إِنَّ عِبَادِى لَيْسَ لَكَ عَلَيْهِمْ سُلْطَٰنٌۭ ۚ وَكَفَىٰ بِرَبِّكَ وَكِيلًۭا', 'إن عبادى ليس لك عليهم سلطن  وكفى بربك وكيلا', NULL, 288, 'local:hafs-text.json'),
  ('hafs-17-66', 'hafs', 17, 66, 'رَّبُّكُمُ ٱلَّذِى يُزْجِى لَكُمُ ٱلْفُلْكَ فِى ٱلْبَحْرِ لِتَبْتَغُوا۟ مِن فَضْلِهِۦٓ ۚ إِنَّهُۥ كَانَ بِكُمْ رَحِيمًۭا', 'ربكم الذى يزجى لكم الفلك فى البحر لتبتغوا من فضله  إنه كان بكم رحيما', NULL, 288, 'local:hafs-text.json'),
  ('hafs-17-67', 'hafs', 17, 67, 'وَإِذَا مَسَّكُمُ ٱلضُّرُّ فِى ٱلْبَحْرِ ضَلَّ مَن تَدْعُونَ إِلَّآ إِيَّاهُ ۖ فَلَمَّا نَجَّىٰكُمْ إِلَى ٱلْبَرِّ أَعْرَضْتُمْ ۚ وَكَانَ ٱلْإِنسَٰنُ كَفُورًا', 'وإذا مسكم الضر فى البحر ضل من تدعون إلا إياه  فلما نجىكم إلى البر أعرضتم  وكان الإنسن كفورا', NULL, 289, 'local:hafs-text.json'),
  ('hafs-17-68', 'hafs', 17, 68, 'أَفَأَمِنتُمْ أَن يَخْسِفَ بِكُمْ جَانِبَ ٱلْبَرِّ أَوْ يُرْسِلَ عَلَيْكُمْ حَاصِبًۭا ثُمَّ لَا تَجِدُوا۟ لَكُمْ وَكِيلًا', 'أفأمنتم أن يخسف بكم جانب البر أو يرسل عليكم حاصبا ثم لا تجدوا لكم وكيلا', NULL, 289, 'local:hafs-text.json'),
  ('hafs-17-69', 'hafs', 17, 69, 'أَمْ أَمِنتُمْ أَن يُعِيدَكُمْ فِيهِ تَارَةً أُخْرَىٰ فَيُرْسِلَ عَلَيْكُمْ قَاصِفًۭا مِّنَ ٱلرِّيحِ فَيُغْرِقَكُم بِمَا كَفَرْتُمْ ۙ ثُمَّ لَا تَجِدُوا۟ لَكُمْ عَلَيْنَا بِهِۦ تَبِيعًۭا', 'أم أمنتم أن يعيدكم فيه تارة أخرى فيرسل عليكم قاصفا من الريح فيغرقكم بما كفرتم  ثم لا تجدوا لكم علينا به تبيعا', NULL, 289, 'local:hafs-text.json'),
  ('hafs-17-70', 'hafs', 17, 70, '۞ وَلَقَدْ كَرَّمْنَا بَنِىٓ ءَادَمَ وَحَمَلْنَٰهُمْ فِى ٱلْبَرِّ وَٱلْبَحْرِ وَرَزَقْنَٰهُم مِّنَ ٱلطَّيِّبَٰتِ وَفَضَّلْنَٰهُمْ عَلَىٰ كَثِيرٍۢ مِّمَّنْ خَلَقْنَا تَفْضِيلًۭا', 'ولقد كرمنا بنى ءادم وحملنهم فى البر والبحر ورزقنهم من الطيبت وفضلنهم على كثير ممن خلقنا تفضيلا', NULL, 289, 'local:hafs-text.json'),
  ('hafs-17-71', 'hafs', 17, 71, 'يَوْمَ نَدْعُوا۟ كُلَّ أُنَاسٍۭ بِإِمَٰمِهِمْ ۖ فَمَنْ أُوتِىَ كِتَٰبَهُۥ بِيَمِينِهِۦ فَأُو۟لَٰٓئِكَ يَقْرَءُونَ كِتَٰبَهُمْ وَلَا يُظْلَمُونَ فَتِيلًۭا', 'يوم ندعوا كل أناس بإممهم  فمن أوتى كتبه بيمينه فأولئك يقرءون كتبهم ولا يظلمون فتيلا', NULL, 289, 'local:hafs-text.json'),
  ('hafs-17-72', 'hafs', 17, 72, 'وَمَن كَانَ فِى هَٰذِهِۦٓ أَعْمَىٰ فَهُوَ فِى ٱلْءَاخِرَةِ أَعْمَىٰ وَأَضَلُّ سَبِيلًۭا', 'ومن كان فى هذه أعمى فهو فى الءاخرة أعمى وأضل سبيلا', NULL, 289, 'local:hafs-text.json'),
  ('hafs-17-73', 'hafs', 17, 73, 'وَإِن كَادُوا۟ لَيَفْتِنُونَكَ عَنِ ٱلَّذِىٓ أَوْحَيْنَآ إِلَيْكَ لِتَفْتَرِىَ عَلَيْنَا غَيْرَهُۥ ۖ وَإِذًۭا لَّٱتَّخَذُوكَ خَلِيلًۭا', 'وإن كادوا ليفتنونك عن الذى أوحينا إليك لتفترى علينا غيره  وإذا لاتخذوك خليلا', NULL, 289, 'local:hafs-text.json'),
  ('hafs-17-74', 'hafs', 17, 74, 'وَلَوْلَآ أَن ثَبَّتْنَٰكَ لَقَدْ كِدتَّ تَرْكَنُ إِلَيْهِمْ شَيْـًۭٔا قَلِيلًا', 'ولولا أن ثبتنك لقد كدت تركن إليهم شيا قليلا', NULL, 289, 'local:hafs-text.json'),
  ('hafs-17-75', 'hafs', 17, 75, 'إِذًۭا لَّأَذَقْنَٰكَ ضِعْفَ ٱلْحَيَوٰةِ وَضِعْفَ ٱلْمَمَاتِ ثُمَّ لَا تَجِدُ لَكَ عَلَيْنَا نَصِيرًۭا', 'إذا لأذقنك ضعف الحيوة وضعف الممات ثم لا تجد لك علينا نصيرا', NULL, 289, 'local:hafs-text.json'),
  ('hafs-17-76', 'hafs', 17, 76, 'وَإِن كَادُوا۟ لَيَسْتَفِزُّونَكَ مِنَ ٱلْأَرْضِ لِيُخْرِجُوكَ مِنْهَا ۖ وَإِذًۭا لَّا يَلْبَثُونَ خِلَٰفَكَ إِلَّا قَلِيلًۭا', 'وإن كادوا ليستفزونك من الأرض ليخرجوك منها  وإذا لا يلبثون خلفك إلا قليلا', NULL, 290, 'local:hafs-text.json'),
  ('hafs-17-77', 'hafs', 17, 77, 'سُنَّةَ مَن قَدْ أَرْسَلْنَا قَبْلَكَ مِن رُّسُلِنَا ۖ وَلَا تَجِدُ لِسُنَّتِنَا تَحْوِيلًا', 'سنة من قد أرسلنا قبلك من رسلنا  ولا تجد لسنتنا تحويلا', NULL, 290, 'local:hafs-text.json'),
  ('hafs-17-78', 'hafs', 17, 78, 'أَقِمِ ٱلصَّلَوٰةَ لِدُلُوكِ ٱلشَّمْسِ إِلَىٰ غَسَقِ ٱلَّيْلِ وَقُرْءَانَ ٱلْفَجْرِ ۖ إِنَّ قُرْءَانَ ٱلْفَجْرِ كَانَ مَشْهُودًۭا', 'أقم الصلوة لدلوك الشمس إلى غسق اليل وقرءان الفجر  إن قرءان الفجر كان مشهودا', NULL, 290, 'local:hafs-text.json'),
  ('hafs-17-79', 'hafs', 17, 79, 'وَمِنَ ٱلَّيْلِ فَتَهَجَّدْ بِهِۦ نَافِلَةًۭ لَّكَ عَسَىٰٓ أَن يَبْعَثَكَ رَبُّكَ مَقَامًۭا مَّحْمُودًۭا', 'ومن اليل فتهجد به نافلة لك عسى أن يبعثك ربك مقاما محمودا', NULL, 290, 'local:hafs-text.json'),
  ('hafs-17-80', 'hafs', 17, 80, 'وَقُل رَّبِّ أَدْخِلْنِى مُدْخَلَ صِدْقٍۢ وَأَخْرِجْنِى مُخْرَجَ صِدْقٍۢ وَٱجْعَل لِّى مِن لَّدُنكَ سُلْطَٰنًۭا نَّصِيرًۭا', 'وقل رب أدخلنى مدخل صدق وأخرجنى مخرج صدق واجعل لى من لدنك سلطنا نصيرا', NULL, 290, 'local:hafs-text.json'),
  ('hafs-17-81', 'hafs', 17, 81, 'وَقُلْ جَآءَ ٱلْحَقُّ وَزَهَقَ ٱلْبَٰطِلُ ۚ إِنَّ ٱلْبَٰطِلَ كَانَ زَهُوقًۭا', 'وقل جاء الحق وزهق البطل  إن البطل كان زهوقا', NULL, 290, 'local:hafs-text.json'),
  ('hafs-17-82', 'hafs', 17, 82, 'وَنُنَزِّلُ مِنَ ٱلْقُرْءَانِ مَا هُوَ شِفَآءٌۭ وَرَحْمَةٌۭ لِّلْمُؤْمِنِينَ ۙ وَلَا يَزِيدُ ٱلظَّٰلِمِينَ إِلَّا خَسَارًۭا', 'وننزل من القرءان ما هو شفاء ورحمة للمؤمنين  ولا يزيد الظلمين إلا خسارا', NULL, 290, 'local:hafs-text.json'),
  ('hafs-17-83', 'hafs', 17, 83, 'وَإِذَآ أَنْعَمْنَا عَلَى ٱلْإِنسَٰنِ أَعْرَضَ وَنَـَٔا بِجَانِبِهِۦ ۖ وَإِذَا مَسَّهُ ٱلشَّرُّ كَانَ يَـُٔوسًۭا', 'وإذا أنعمنا على الإنسن أعرض ونا بجانبه  وإذا مسه الشر كان يوسا', NULL, 290, 'local:hafs-text.json'),
  ('hafs-17-84', 'hafs', 17, 84, 'قُلْ كُلٌّۭ يَعْمَلُ عَلَىٰ شَاكِلَتِهِۦ فَرَبُّكُمْ أَعْلَمُ بِمَنْ هُوَ أَهْدَىٰ سَبِيلًۭا', 'قل كل يعمل على شاكلته فربكم أعلم بمن هو أهدى سبيلا', NULL, 290, 'local:hafs-text.json'),
  ('hafs-17-85', 'hafs', 17, 85, 'وَيَسْـَٔلُونَكَ عَنِ ٱلرُّوحِ ۖ قُلِ ٱلرُّوحُ مِنْ أَمْرِ رَبِّى وَمَآ أُوتِيتُم مِّنَ ٱلْعِلْمِ إِلَّا قَلِيلًۭا', 'ويسلونك عن الروح  قل الروح من أمر ربى وما أوتيتم من العلم إلا قليلا', NULL, 290, 'local:hafs-text.json'),
  ('hafs-17-86', 'hafs', 17, 86, 'وَلَئِن شِئْنَا لَنَذْهَبَنَّ بِٱلَّذِىٓ أَوْحَيْنَآ إِلَيْكَ ثُمَّ لَا تَجِدُ لَكَ بِهِۦ عَلَيْنَا وَكِيلًا', 'ولئن شئنا لنذهبن بالذى أوحينا إليك ثم لا تجد لك به علينا وكيلا', NULL, 290, 'local:hafs-text.json'),
  ('hafs-17-87', 'hafs', 17, 87, 'إِلَّا رَحْمَةًۭ مِّن رَّبِّكَ ۚ إِنَّ فَضْلَهُۥ كَانَ عَلَيْكَ كَبِيرًۭا', 'إلا رحمة من ربك  إن فضله كان عليك كبيرا', NULL, 291, 'local:hafs-text.json'),
  ('hafs-17-88', 'hafs', 17, 88, 'قُل لَّئِنِ ٱجْتَمَعَتِ ٱلْإِنسُ وَٱلْجِنُّ عَلَىٰٓ أَن يَأْتُوا۟ بِمِثْلِ هَٰذَا ٱلْقُرْءَانِ لَا يَأْتُونَ بِمِثْلِهِۦ وَلَوْ كَانَ بَعْضُهُمْ لِبَعْضٍۢ ظَهِيرًۭا', 'قل لئن اجتمعت الإنس والجن على أن يأتوا بمثل هذا القرءان لا يأتون بمثله ولو كان بعضهم لبعض ظهيرا', NULL, 291, 'local:hafs-text.json'),
  ('hafs-17-89', 'hafs', 17, 89, 'وَلَقَدْ صَرَّفْنَا لِلنَّاسِ فِى هَٰذَا ٱلْقُرْءَانِ مِن كُلِّ مَثَلٍۢ فَأَبَىٰٓ أَكْثَرُ ٱلنَّاسِ إِلَّا كُفُورًۭا', 'ولقد صرفنا للناس فى هذا القرءان من كل مثل فأبى أكثر الناس إلا كفورا', NULL, 291, 'local:hafs-text.json'),
  ('hafs-17-90', 'hafs', 17, 90, 'وَقَالُوا۟ لَن نُّؤْمِنَ لَكَ حَتَّىٰ تَفْجُرَ لَنَا مِنَ ٱلْأَرْضِ يَنۢبُوعًا', 'وقالوا لن نؤمن لك حتى تفجر لنا من الأرض ينبوعا', NULL, 291, 'local:hafs-text.json'),
  ('hafs-17-91', 'hafs', 17, 91, 'أَوْ تَكُونَ لَكَ جَنَّةٌۭ مِّن نَّخِيلٍۢ وَعِنَبٍۢ فَتُفَجِّرَ ٱلْأَنْهَٰرَ خِلَٰلَهَا تَفْجِيرًا', 'أو تكون لك جنة من نخيل وعنب فتفجر الأنهر خللها تفجيرا', NULL, 291, 'local:hafs-text.json'),
  ('hafs-17-92', 'hafs', 17, 92, 'أَوْ تُسْقِطَ ٱلسَّمَآءَ كَمَا زَعَمْتَ عَلَيْنَا كِسَفًا أَوْ تَأْتِىَ بِٱللَّهِ وَٱلْمَلَٰٓئِكَةِ قَبِيلًا', 'أو تسقط السماء كما زعمت علينا كسفا أو تأتى بالله والملئكة قبيلا', NULL, 291, 'local:hafs-text.json'),
  ('hafs-17-93', 'hafs', 17, 93, 'أَوْ يَكُونَ لَكَ بَيْتٌۭ مِّن زُخْرُفٍ أَوْ تَرْقَىٰ فِى ٱلسَّمَآءِ وَلَن نُّؤْمِنَ لِرُقِيِّكَ حَتَّىٰ تُنَزِّلَ عَلَيْنَا كِتَٰبًۭا نَّقْرَؤُهُۥ ۗ قُلْ سُبْحَانَ رَبِّى هَلْ كُنتُ إِلَّا بَشَرًۭا رَّسُولًۭا', 'أو يكون لك بيت من زخرف أو ترقى فى السماء ولن نؤمن لرقيك حتى تنزل علينا كتبا نقرؤه  قل سبحان ربى هل كنت إلا بشرا رسولا', NULL, 291, 'local:hafs-text.json'),
  ('hafs-17-94', 'hafs', 17, 94, 'وَمَا مَنَعَ ٱلنَّاسَ أَن يُؤْمِنُوٓا۟ إِذْ جَآءَهُمُ ٱلْهُدَىٰٓ إِلَّآ أَن قَالُوٓا۟ أَبَعَثَ ٱللَّهُ بَشَرًۭا رَّسُولًۭا', 'وما منع الناس أن يؤمنوا إذ جاءهم الهدى إلا أن قالوا أبعث الله بشرا رسولا', NULL, 291, 'local:hafs-text.json'),
  ('hafs-17-95', 'hafs', 17, 95, 'قُل لَّوْ كَانَ فِى ٱلْأَرْضِ مَلَٰٓئِكَةٌۭ يَمْشُونَ مُطْمَئِنِّينَ لَنَزَّلْنَا عَلَيْهِم مِّنَ ٱلسَّمَآءِ مَلَكًۭا رَّسُولًۭا', 'قل لو كان فى الأرض ملئكة يمشون مطمئنين لنزلنا عليهم من السماء ملكا رسولا', NULL, 291, 'local:hafs-text.json'),
  ('hafs-17-96', 'hafs', 17, 96, 'قُلْ كَفَىٰ بِٱللَّهِ شَهِيدًۢا بَيْنِى وَبَيْنَكُمْ ۚ إِنَّهُۥ كَانَ بِعِبَادِهِۦ خَبِيرًۢا بَصِيرًۭا', 'قل كفى بالله شهيدا بينى وبينكم  إنه كان بعباده خبيرا بصيرا', NULL, 291, 'local:hafs-text.json'),
  ('hafs-17-97', 'hafs', 17, 97, 'وَمَن يَهْدِ ٱللَّهُ فَهُوَ ٱلْمُهْتَدِ ۖ وَمَن يُضْلِلْ فَلَن تَجِدَ لَهُمْ أَوْلِيَآءَ مِن دُونِهِۦ ۖ وَنَحْشُرُهُمْ يَوْمَ ٱلْقِيَٰمَةِ عَلَىٰ وُجُوهِهِمْ عُمْيًۭا وَبُكْمًۭا وَصُمًّۭا ۖ مَّأْوَىٰهُمْ جَهَنَّمُ ۖ كُلَّمَا خَبَتْ زِدْنَٰهُمْ سَعِيرًۭا', 'ومن يهد الله فهو المهتد  ومن يضلل فلن تجد لهم أولياء من دونه  ونحشرهم يوم القيمة على وجوههم عميا وبكما وصما  مأوىهم جهنم  كلما خبت زدنهم سعيرا', NULL, 292, 'local:hafs-text.json'),
  ('hafs-17-98', 'hafs', 17, 98, 'ذَٰلِكَ جَزَآؤُهُم بِأَنَّهُمْ كَفَرُوا۟ بِـَٔايَٰتِنَا وَقَالُوٓا۟ أَءِذَا كُنَّا عِظَٰمًۭا وَرُفَٰتًا أَءِنَّا لَمَبْعُوثُونَ خَلْقًۭا جَدِيدًا', 'ذلك جزاؤهم بأنهم كفروا بايتنا وقالوا أءذا كنا عظما ورفتا أءنا لمبعوثون خلقا جديدا', NULL, 292, 'local:hafs-text.json'),
  ('hafs-17-99', 'hafs', 17, 99, '۞ أَوَلَمْ يَرَوْا۟ أَنَّ ٱللَّهَ ٱلَّذِى خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ قَادِرٌ عَلَىٰٓ أَن يَخْلُقَ مِثْلَهُمْ وَجَعَلَ لَهُمْ أَجَلًۭا لَّا رَيْبَ فِيهِ فَأَبَى ٱلظَّٰلِمُونَ إِلَّا كُفُورًۭا', 'أولم يروا أن الله الذى خلق السموت والأرض قادر على أن يخلق مثلهم وجعل لهم أجلا لا ريب فيه فأبى الظلمون إلا كفورا', NULL, 292, 'local:hafs-text.json'),
  ('hafs-17-100', 'hafs', 17, 100, 'قُل لَّوْ أَنتُمْ تَمْلِكُونَ خَزَآئِنَ رَحْمَةِ رَبِّىٓ إِذًۭا لَّأَمْسَكْتُمْ خَشْيَةَ ٱلْإِنفَاقِ ۚ وَكَانَ ٱلْإِنسَٰنُ قَتُورًۭا', 'قل لو أنتم تملكون خزائن رحمة ربى إذا لأمسكتم خشية الإنفاق  وكان الإنسن قتورا', NULL, 292, 'local:hafs-text.json'),
  ('hafs-17-101', 'hafs', 17, 101, 'وَلَقَدْ ءَاتَيْنَا مُوسَىٰ تِسْعَ ءَايَٰتٍۭ بَيِّنَٰتٍۢ ۖ فَسْـَٔلْ بَنِىٓ إِسْرَٰٓءِيلَ إِذْ جَآءَهُمْ فَقَالَ لَهُۥ فِرْعَوْنُ إِنِّى لَأَظُنُّكَ يَٰمُوسَىٰ مَسْحُورًۭا', 'ولقد ءاتينا موسى تسع ءايت بينت  فسل بنى إسرءيل إذ جاءهم فقال له فرعون إنى لأظنك يموسى مسحورا', NULL, 292, 'local:hafs-text.json'),
  ('hafs-17-102', 'hafs', 17, 102, 'قَالَ لَقَدْ عَلِمْتَ مَآ أَنزَلَ هَٰٓؤُلَآءِ إِلَّا رَبُّ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ بَصَآئِرَ وَإِنِّى لَأَظُنُّكَ يَٰفِرْعَوْنُ مَثْبُورًۭا', 'قال لقد علمت ما أنزل هؤلاء إلا رب السموت والأرض بصائر وإنى لأظنك يفرعون مثبورا', NULL, 292, 'local:hafs-text.json'),
  ('hafs-17-103', 'hafs', 17, 103, 'فَأَرَادَ أَن يَسْتَفِزَّهُم مِّنَ ٱلْأَرْضِ فَأَغْرَقْنَٰهُ وَمَن مَّعَهُۥ جَمِيعًۭا', 'فأراد أن يستفزهم من الأرض فأغرقنه ومن معه جميعا', NULL, 292, 'local:hafs-text.json'),
  ('hafs-17-104', 'hafs', 17, 104, 'وَقُلْنَا مِنۢ بَعْدِهِۦ لِبَنِىٓ إِسْرَٰٓءِيلَ ٱسْكُنُوا۟ ٱلْأَرْضَ فَإِذَا جَآءَ وَعْدُ ٱلْءَاخِرَةِ جِئْنَا بِكُمْ لَفِيفًۭا', 'وقلنا من بعده لبنى إسرءيل اسكنوا الأرض فإذا جاء وعد الءاخرة جئنا بكم لفيفا', NULL, 292, 'local:hafs-text.json'),
  ('hafs-17-105', 'hafs', 17, 105, 'وَبِٱلْحَقِّ أَنزَلْنَٰهُ وَبِٱلْحَقِّ نَزَلَ ۗ وَمَآ أَرْسَلْنَٰكَ إِلَّا مُبَشِّرًۭا وَنَذِيرًۭا', 'وبالحق أنزلنه وبالحق نزل  وما أرسلنك إلا مبشرا ونذيرا', NULL, 293, 'local:hafs-text.json'),
  ('hafs-17-106', 'hafs', 17, 106, 'وَقُرْءَانًۭا فَرَقْنَٰهُ لِتَقْرَأَهُۥ عَلَى ٱلنَّاسِ عَلَىٰ مُكْثٍۢ وَنَزَّلْنَٰهُ تَنزِيلًۭا', 'وقرءانا فرقنه لتقرأه على الناس على مكث ونزلنه تنزيلا', NULL, 293, 'local:hafs-text.json'),
  ('hafs-17-107', 'hafs', 17, 107, 'قُلْ ءَامِنُوا۟ بِهِۦٓ أَوْ لَا تُؤْمِنُوٓا۟ ۚ إِنَّ ٱلَّذِينَ أُوتُوا۟ ٱلْعِلْمَ مِن قَبْلِهِۦٓ إِذَا يُتْلَىٰ عَلَيْهِمْ يَخِرُّونَ لِلْأَذْقَانِ سُجَّدًۭا', 'قل ءامنوا به أو لا تؤمنوا  إن الذين أوتوا العلم من قبله إذا يتلى عليهم يخرون للأذقان سجدا', NULL, 293, 'local:hafs-text.json'),
  ('hafs-17-108', 'hafs', 17, 108, 'وَيَقُولُونَ سُبْحَٰنَ رَبِّنَآ إِن كَانَ وَعْدُ رَبِّنَا لَمَفْعُولًۭا', 'ويقولون سبحن ربنا إن كان وعد ربنا لمفعولا', NULL, 293, 'local:hafs-text.json'),
  ('hafs-17-109', 'hafs', 17, 109, 'وَيَخِرُّونَ لِلْأَذْقَانِ يَبْكُونَ وَيَزِيدُهُمْ خُشُوعًۭا ۩', 'ويخرون للأذقان يبكون ويزيدهم خشوعا', NULL, 293, 'local:hafs-text.json'),
  ('hafs-17-110', 'hafs', 17, 110, 'قُلِ ٱدْعُوا۟ ٱللَّهَ أَوِ ٱدْعُوا۟ ٱلرَّحْمَٰنَ ۖ أَيًّۭا مَّا تَدْعُوا۟ فَلَهُ ٱلْأَسْمَآءُ ٱلْحُسْنَىٰ ۚ وَلَا تَجْهَرْ بِصَلَاتِكَ وَلَا تُخَافِتْ بِهَا وَٱبْتَغِ بَيْنَ ذَٰلِكَ سَبِيلًۭا', 'قل ادعوا الله أو ادعوا الرحمن  أيا ما تدعوا فله الأسماء الحسنى  ولا تجهر بصلاتك ولا تخافت بها وابتغ بين ذلك سبيلا', NULL, 293, 'local:hafs-text.json'),
  ('hafs-17-111', 'hafs', 17, 111, 'وَقُلِ ٱلْحَمْدُ لِلَّهِ ٱلَّذِى لَمْ يَتَّخِذْ وَلَدًۭا وَلَمْ يَكُن لَّهُۥ شَرِيكٌۭ فِى ٱلْمُلْكِ وَلَمْ يَكُن لَّهُۥ وَلِىٌّۭ مِّنَ ٱلذُّلِّ ۖ وَكَبِّرْهُ تَكْبِيرًۢا', 'وقل الحمد لله الذى لم يتخذ ولدا ولم يكن له شريك فى الملك ولم يكن له ولى من الذل  وكبره تكبيرا', NULL, 293, 'local:hafs-text.json'),
  ('hafs-18-1', 'hafs', 18, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ ٱلْحَمْدُ لِلَّهِ ٱلَّذِىٓ أَنزَلَ عَلَىٰ عَبْدِهِ ٱلْكِتَٰبَ وَلَمْ يَجْعَل لَّهُۥ عِوَجَا ۜ', 'بسم الله الرحمن الرحيم الحمد لله الذى أنزل على عبده الكتب ولم يجعل له عوجا', NULL, 293, 'local:hafs-text.json'),
  ('hafs-18-2', 'hafs', 18, 2, 'قَيِّمًۭا لِّيُنذِرَ بَأْسًۭا شَدِيدًۭا مِّن لَّدُنْهُ وَيُبَشِّرَ ٱلْمُؤْمِنِينَ ٱلَّذِينَ يَعْمَلُونَ ٱلصَّٰلِحَٰتِ أَنَّ لَهُمْ أَجْرًا حَسَنًۭا', 'قيما لينذر بأسا شديدا من لدنه ويبشر المؤمنين الذين يعملون الصلحت أن لهم أجرا حسنا', NULL, 293, 'local:hafs-text.json'),
  ('hafs-18-3', 'hafs', 18, 3, 'مَّٰكِثِينَ فِيهِ أَبَدًۭا', 'مكثين فيه أبدا', NULL, 293, 'local:hafs-text.json'),
  ('hafs-18-4', 'hafs', 18, 4, 'وَيُنذِرَ ٱلَّذِينَ قَالُوا۟ ٱتَّخَذَ ٱللَّهُ وَلَدًۭا', 'وينذر الذين قالوا اتخذ الله ولدا', NULL, 293, 'local:hafs-text.json'),
  ('hafs-18-5', 'hafs', 18, 5, 'مَّا لَهُم بِهِۦ مِنْ عِلْمٍۢ وَلَا لِءَابَآئِهِمْ ۚ كَبُرَتْ كَلِمَةًۭ تَخْرُجُ مِنْ أَفْوَٰهِهِمْ ۚ إِن يَقُولُونَ إِلَّا كَذِبًۭا', 'ما لهم به من علم ولا لءابائهم  كبرت كلمة تخرج من أفوههم  إن يقولون إلا كذبا', NULL, 294, 'local:hafs-text.json'),
  ('hafs-18-6', 'hafs', 18, 6, 'فَلَعَلَّكَ بَٰخِعٌۭ نَّفْسَكَ عَلَىٰٓ ءَاثَٰرِهِمْ إِن لَّمْ يُؤْمِنُوا۟ بِهَٰذَا ٱلْحَدِيثِ أَسَفًا', 'فلعلك بخع نفسك على ءاثرهم إن لم يؤمنوا بهذا الحديث أسفا', NULL, 294, 'local:hafs-text.json'),
  ('hafs-18-7', 'hafs', 18, 7, 'إِنَّا جَعَلْنَا مَا عَلَى ٱلْأَرْضِ زِينَةًۭ لَّهَا لِنَبْلُوَهُمْ أَيُّهُمْ أَحْسَنُ عَمَلًۭا', 'إنا جعلنا ما على الأرض زينة لها لنبلوهم أيهم أحسن عملا', NULL, 294, 'local:hafs-text.json'),
  ('hafs-18-8', 'hafs', 18, 8, 'وَإِنَّا لَجَٰعِلُونَ مَا عَلَيْهَا صَعِيدًۭا جُرُزًا', 'وإنا لجعلون ما عليها صعيدا جرزا', NULL, 294, 'local:hafs-text.json'),
  ('hafs-18-9', 'hafs', 18, 9, 'أَمْ حَسِبْتَ أَنَّ أَصْحَٰبَ ٱلْكَهْفِ وَٱلرَّقِيمِ كَانُوا۟ مِنْ ءَايَٰتِنَا عَجَبًا', 'أم حسبت أن أصحب الكهف والرقيم كانوا من ءايتنا عجبا', NULL, 294, 'local:hafs-text.json'),
  ('hafs-18-10', 'hafs', 18, 10, 'إِذْ أَوَى ٱلْفِتْيَةُ إِلَى ٱلْكَهْفِ فَقَالُوا۟ رَبَّنَآ ءَاتِنَا مِن لَّدُنكَ رَحْمَةًۭ وَهَيِّئْ لَنَا مِنْ أَمْرِنَا رَشَدًۭا', 'إذ أوى الفتية إلى الكهف فقالوا ربنا ءاتنا من لدنك رحمة وهيئ لنا من أمرنا رشدا', NULL, 294, 'local:hafs-text.json'),
  ('hafs-18-11', 'hafs', 18, 11, 'فَضَرَبْنَا عَلَىٰٓ ءَاذَانِهِمْ فِى ٱلْكَهْفِ سِنِينَ عَدَدًۭا', 'فضربنا على ءاذانهم فى الكهف سنين عددا', NULL, 294, 'local:hafs-text.json'),
  ('hafs-18-12', 'hafs', 18, 12, 'ثُمَّ بَعَثْنَٰهُمْ لِنَعْلَمَ أَىُّ ٱلْحِزْبَيْنِ أَحْصَىٰ لِمَا لَبِثُوٓا۟ أَمَدًۭا', 'ثم بعثنهم لنعلم أى الحزبين أحصى لما لبثوا أمدا', NULL, 294, 'local:hafs-text.json'),
  ('hafs-18-13', 'hafs', 18, 13, 'نَّحْنُ نَقُصُّ عَلَيْكَ نَبَأَهُم بِٱلْحَقِّ ۚ إِنَّهُمْ فِتْيَةٌ ءَامَنُوا۟ بِرَبِّهِمْ وَزِدْنَٰهُمْ هُدًۭى', 'نحن نقص عليك نبأهم بالحق  إنهم فتية ءامنوا بربهم وزدنهم هدى', NULL, 294, 'local:hafs-text.json'),
  ('hafs-18-14', 'hafs', 18, 14, 'وَرَبَطْنَا عَلَىٰ قُلُوبِهِمْ إِذْ قَامُوا۟ فَقَالُوا۟ رَبُّنَا رَبُّ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ لَن نَّدْعُوَا۟ مِن دُونِهِۦٓ إِلَٰهًۭا ۖ لَّقَدْ قُلْنَآ إِذًۭا شَطَطًا', 'وربطنا على قلوبهم إذ قاموا فقالوا ربنا رب السموت والأرض لن ندعوا من دونه إلها  لقد قلنا إذا شططا', NULL, 294, 'local:hafs-text.json'),
  ('hafs-18-15', 'hafs', 18, 15, 'هَٰٓؤُلَآءِ قَوْمُنَا ٱتَّخَذُوا۟ مِن دُونِهِۦٓ ءَالِهَةًۭ ۖ لَّوْلَا يَأْتُونَ عَلَيْهِم بِسُلْطَٰنٍۭ بَيِّنٍۢ ۖ فَمَنْ أَظْلَمُ مِمَّنِ ٱفْتَرَىٰ عَلَى ٱللَّهِ كَذِبًۭا', 'هؤلاء قومنا اتخذوا من دونه ءالهة  لولا يأتون عليهم بسلطن بين  فمن أظلم ممن افترى على الله كذبا', NULL, 294, 'local:hafs-text.json'),
  ('hafs-18-16', 'hafs', 18, 16, 'وَإِذِ ٱعْتَزَلْتُمُوهُمْ وَمَا يَعْبُدُونَ إِلَّا ٱللَّهَ فَأْوُۥٓا۟ إِلَى ٱلْكَهْفِ يَنشُرْ لَكُمْ رَبُّكُم مِّن رَّحْمَتِهِۦ وَيُهَيِّئْ لَكُم مِّنْ أَمْرِكُم مِّرْفَقًۭا', 'وإذ اعتزلتموهم وما يعبدون إلا الله فأوا إلى الكهف ينشر لكم ربكم من رحمته ويهيئ لكم من أمركم مرفقا', NULL, 295, 'local:hafs-text.json'),
  ('hafs-18-17', 'hafs', 18, 17, '۞ وَتَرَى ٱلشَّمْسَ إِذَا طَلَعَت تَّزَٰوَرُ عَن كَهْفِهِمْ ذَاتَ ٱلْيَمِينِ وَإِذَا غَرَبَت تَّقْرِضُهُمْ ذَاتَ ٱلشِّمَالِ وَهُمْ فِى فَجْوَةٍۢ مِّنْهُ ۚ ذَٰلِكَ مِنْ ءَايَٰتِ ٱللَّهِ ۗ مَن يَهْدِ ٱللَّهُ فَهُوَ ٱلْمُهْتَدِ ۖ وَمَن يُضْلِلْ فَلَن تَجِدَ لَهُۥ وَلِيًّۭا مُّرْشِدًۭا', 'وترى الشمس إذا طلعت تزور عن كهفهم ذات اليمين وإذا غربت تقرضهم ذات الشمال وهم فى فجوة منه  ذلك من ءايت الله  من يهد الله فهو المهتد  ومن يضلل فلن تجد له وليا مرشدا', NULL, 295, 'local:hafs-text.json'),
  ('hafs-18-18', 'hafs', 18, 18, 'وَتَحْسَبُهُمْ أَيْقَاظًۭا وَهُمْ رُقُودٌۭ ۚ وَنُقَلِّبُهُمْ ذَاتَ ٱلْيَمِينِ وَذَاتَ ٱلشِّمَالِ ۖ وَكَلْبُهُم بَٰسِطٌۭ ذِرَاعَيْهِ بِٱلْوَصِيدِ ۚ لَوِ ٱطَّلَعْتَ عَلَيْهِمْ لَوَلَّيْتَ مِنْهُمْ فِرَارًۭا وَلَمُلِئْتَ مِنْهُمْ رُعْبًۭا', 'وتحسبهم أيقاظا وهم رقود  ونقلبهم ذات اليمين وذات الشمال  وكلبهم بسط ذراعيه بالوصيد  لو اطلعت عليهم لوليت منهم فرارا ولملئت منهم رعبا', NULL, 295, 'local:hafs-text.json'),
  ('hafs-18-19', 'hafs', 18, 19, 'وَكَذَٰلِكَ بَعَثْنَٰهُمْ لِيَتَسَآءَلُوا۟ بَيْنَهُمْ ۚ قَالَ قَآئِلٌۭ مِّنْهُمْ كَمْ لَبِثْتُمْ ۖ قَالُوا۟ لَبِثْنَا يَوْمًا أَوْ بَعْضَ يَوْمٍۢ ۚ قَالُوا۟ رَبُّكُمْ أَعْلَمُ بِمَا لَبِثْتُمْ فَٱبْعَثُوٓا۟ أَحَدَكُم بِوَرِقِكُمْ هَٰذِهِۦٓ إِلَى ٱلْمَدِينَةِ فَلْيَنظُرْ أَيُّهَآ أَزْكَىٰ طَعَامًۭا فَلْيَأْتِكُم بِرِزْقٍۢ مِّنْهُ وَلْيَتَلَطَّفْ وَلَا يُشْعِرَنَّ بِكُمْ أَحَدًا', 'وكذلك بعثنهم ليتساءلوا بينهم  قال قائل منهم كم لبثتم  قالوا لبثنا يوما أو بعض يوم  قالوا ربكم أعلم بما لبثتم فابعثوا أحدكم بورقكم هذه إلى المدينة فلينظر أيها أزكى طعاما فليأتكم برزق منه وليتلطف ولا يشعرن بكم أحدا', NULL, 295, 'local:hafs-text.json'),
  ('hafs-18-20', 'hafs', 18, 20, 'إِنَّهُمْ إِن يَظْهَرُوا۟ عَلَيْكُمْ يَرْجُمُوكُمْ أَوْ يُعِيدُوكُمْ فِى مِلَّتِهِمْ وَلَن تُفْلِحُوٓا۟ إِذًا أَبَدًۭا', 'إنهم إن يظهروا عليكم يرجموكم أو يعيدوكم فى ملتهم ولن تفلحوا إذا أبدا', NULL, 295, 'local:hafs-text.json'),
  ('hafs-18-21', 'hafs', 18, 21, 'وَكَذَٰلِكَ أَعْثَرْنَا عَلَيْهِمْ لِيَعْلَمُوٓا۟ أَنَّ وَعْدَ ٱللَّهِ حَقٌّۭ وَأَنَّ ٱلسَّاعَةَ لَا رَيْبَ فِيهَآ إِذْ يَتَنَٰزَعُونَ بَيْنَهُمْ أَمْرَهُمْ ۖ فَقَالُوا۟ ٱبْنُوا۟ عَلَيْهِم بُنْيَٰنًۭا ۖ رَّبُّهُمْ أَعْلَمُ بِهِمْ ۚ قَالَ ٱلَّذِينَ غَلَبُوا۟ عَلَىٰٓ أَمْرِهِمْ لَنَتَّخِذَنَّ عَلَيْهِم مَّسْجِدًۭا', 'وكذلك أعثرنا عليهم ليعلموا أن وعد الله حق وأن الساعة لا ريب فيها إذ يتنزعون بينهم أمرهم  فقالوا ابنوا عليهم بنينا  ربهم أعلم بهم  قال الذين غلبوا على أمرهم لنتخذن عليهم مسجدا', NULL, 296, 'local:hafs-text.json'),
  ('hafs-18-22', 'hafs', 18, 22, 'سَيَقُولُونَ ثَلَٰثَةٌۭ رَّابِعُهُمْ كَلْبُهُمْ وَيَقُولُونَ خَمْسَةٌۭ سَادِسُهُمْ كَلْبُهُمْ رَجْمًۢا بِٱلْغَيْبِ ۖ وَيَقُولُونَ سَبْعَةٌۭ وَثَامِنُهُمْ كَلْبُهُمْ ۚ قُل رَّبِّىٓ أَعْلَمُ بِعِدَّتِهِم مَّا يَعْلَمُهُمْ إِلَّا قَلِيلٌۭ ۗ فَلَا تُمَارِ فِيهِمْ إِلَّا مِرَآءًۭ ظَٰهِرًۭا وَلَا تَسْتَفْتِ فِيهِم مِّنْهُمْ أَحَدًۭا', 'سيقولون ثلثة رابعهم كلبهم ويقولون خمسة سادسهم كلبهم رجما بالغيب  ويقولون سبعة وثامنهم كلبهم  قل ربى أعلم بعدتهم ما يعلمهم إلا قليل  فلا تمار فيهم إلا مراء ظهرا ولا تستفت فيهم منهم أحدا', NULL, 296, 'local:hafs-text.json'),
  ('hafs-18-23', 'hafs', 18, 23, 'وَلَا تَقُولَنَّ لِشَا۟ىْءٍ إِنِّى فَاعِلٌۭ ذَٰلِكَ غَدًا', 'ولا تقولن لشاىء إنى فاعل ذلك غدا', NULL, 296, 'local:hafs-text.json'),
  ('hafs-18-24', 'hafs', 18, 24, 'إِلَّآ أَن يَشَآءَ ٱللَّهُ ۚ وَٱذْكُر رَّبَّكَ إِذَا نَسِيتَ وَقُلْ عَسَىٰٓ أَن يَهْدِيَنِ رَبِّى لِأَقْرَبَ مِنْ هَٰذَا رَشَدًۭا', 'إلا أن يشاء الله  واذكر ربك إذا نسيت وقل عسى أن يهدين ربى لأقرب من هذا رشدا', NULL, 296, 'local:hafs-text.json'),
  ('hafs-18-25', 'hafs', 18, 25, 'وَلَبِثُوا۟ فِى كَهْفِهِمْ ثَلَٰثَ مِا۟ئَةٍۢ سِنِينَ وَٱزْدَادُوا۟ تِسْعًۭا', 'ولبثوا فى كهفهم ثلث مائة سنين وازدادوا تسعا', NULL, 296, 'local:hafs-text.json'),
  ('hafs-18-26', 'hafs', 18, 26, 'قُلِ ٱللَّهُ أَعْلَمُ بِمَا لَبِثُوا۟ ۖ لَهُۥ غَيْبُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ ۖ أَبْصِرْ بِهِۦ وَأَسْمِعْ ۚ مَا لَهُم مِّن دُونِهِۦ مِن وَلِىٍّۢ وَلَا يُشْرِكُ فِى حُكْمِهِۦٓ أَحَدًۭا', 'قل الله أعلم بما لبثوا  له غيب السموت والأرض  أبصر به وأسمع  ما لهم من دونه من ولى ولا يشرك فى حكمه أحدا', NULL, 296, 'local:hafs-text.json'),
  ('hafs-18-27', 'hafs', 18, 27, 'وَٱتْلُ مَآ أُوحِىَ إِلَيْكَ مِن كِتَابِ رَبِّكَ ۖ لَا مُبَدِّلَ لِكَلِمَٰتِهِۦ وَلَن تَجِدَ مِن دُونِهِۦ مُلْتَحَدًۭا', 'واتل ما أوحى إليك من كتاب ربك  لا مبدل لكلمته ولن تجد من دونه ملتحدا', NULL, 296, 'local:hafs-text.json'),
  ('hafs-18-28', 'hafs', 18, 28, 'وَٱصْبِرْ نَفْسَكَ مَعَ ٱلَّذِينَ يَدْعُونَ رَبَّهُم بِٱلْغَدَوٰةِ وَٱلْعَشِىِّ يُرِيدُونَ وَجْهَهُۥ ۖ وَلَا تَعْدُ عَيْنَاكَ عَنْهُمْ تُرِيدُ زِينَةَ ٱلْحَيَوٰةِ ٱلدُّنْيَا ۖ وَلَا تُطِعْ مَنْ أَغْفَلْنَا قَلْبَهُۥ عَن ذِكْرِنَا وَٱتَّبَعَ هَوَىٰهُ وَكَانَ أَمْرُهُۥ فُرُطًۭا', 'واصبر نفسك مع الذين يدعون ربهم بالغدوة والعشى يريدون وجهه  ولا تعد عيناك عنهم تريد زينة الحيوة الدنيا  ولا تطع من أغفلنا قلبه عن ذكرنا واتبع هوىه وكان أمره فرطا', NULL, 297, 'local:hafs-text.json'),
  ('hafs-18-29', 'hafs', 18, 29, 'وَقُلِ ٱلْحَقُّ مِن رَّبِّكُمْ ۖ فَمَن شَآءَ فَلْيُؤْمِن وَمَن شَآءَ فَلْيَكْفُرْ ۚ إِنَّآ أَعْتَدْنَا لِلظَّٰلِمِينَ نَارًا أَحَاطَ بِهِمْ سُرَادِقُهَا ۚ وَإِن يَسْتَغِيثُوا۟ يُغَاثُوا۟ بِمَآءٍۢ كَٱلْمُهْلِ يَشْوِى ٱلْوُجُوهَ ۚ بِئْسَ ٱلشَّرَابُ وَسَآءَتْ مُرْتَفَقًا', 'وقل الحق من ربكم  فمن شاء فليؤمن ومن شاء فليكفر  إنا أعتدنا للظلمين نارا أحاط بهم سرادقها  وإن يستغيثوا يغاثوا بماء كالمهل يشوى الوجوه  بئس الشراب وساءت مرتفقا', NULL, 297, 'local:hafs-text.json'),
  ('hafs-18-30', 'hafs', 18, 30, 'إِنَّ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ إِنَّا لَا نُضِيعُ أَجْرَ مَنْ أَحْسَنَ عَمَلًا', 'إن الذين ءامنوا وعملوا الصلحت إنا لا نضيع أجر من أحسن عملا', NULL, 297, 'local:hafs-text.json'),
  ('hafs-18-31', 'hafs', 18, 31, 'أُو۟لَٰٓئِكَ لَهُمْ جَنَّٰتُ عَدْنٍۢ تَجْرِى مِن تَحْتِهِمُ ٱلْأَنْهَٰرُ يُحَلَّوْنَ فِيهَا مِنْ أَسَاوِرَ مِن ذَهَبٍۢ وَيَلْبَسُونَ ثِيَابًا خُضْرًۭا مِّن سُندُسٍۢ وَإِسْتَبْرَقٍۢ مُّتَّكِـِٔينَ فِيهَا عَلَى ٱلْأَرَآئِكِ ۚ نِعْمَ ٱلثَّوَابُ وَحَسُنَتْ مُرْتَفَقًۭا', 'أولئك لهم جنت عدن تجرى من تحتهم الأنهر يحلون فيها من أساور من ذهب ويلبسون ثيابا خضرا من سندس وإستبرق متكين فيها على الأرائك  نعم الثواب وحسنت مرتفقا', NULL, 297, 'local:hafs-text.json'),
  ('hafs-18-32', 'hafs', 18, 32, '۞ وَٱضْرِبْ لَهُم مَّثَلًۭا رَّجُلَيْنِ جَعَلْنَا لِأَحَدِهِمَا جَنَّتَيْنِ مِنْ أَعْنَٰبٍۢ وَحَفَفْنَٰهُمَا بِنَخْلٍۢ وَجَعَلْنَا بَيْنَهُمَا زَرْعًۭا', 'واضرب لهم مثلا رجلين جعلنا لأحدهما جنتين من أعنب وحففنهما بنخل وجعلنا بينهما زرعا', NULL, 297, 'local:hafs-text.json'),
  ('hafs-18-33', 'hafs', 18, 33, 'كِلْتَا ٱلْجَنَّتَيْنِ ءَاتَتْ أُكُلَهَا وَلَمْ تَظْلِم مِّنْهُ شَيْـًۭٔا ۚ وَفَجَّرْنَا خِلَٰلَهُمَا نَهَرًۭا', 'كلتا الجنتين ءاتت أكلها ولم تظلم منه شيا  وفجرنا خللهما نهرا', NULL, 297, 'local:hafs-text.json'),
  ('hafs-18-34', 'hafs', 18, 34, 'وَكَانَ لَهُۥ ثَمَرٌۭ فَقَالَ لِصَٰحِبِهِۦ وَهُوَ يُحَاوِرُهُۥٓ أَنَا۠ أَكْثَرُ مِنكَ مَالًۭا وَأَعَزُّ نَفَرًۭا', 'وكان له ثمر فقال لصحبه وهو يحاوره أنا أكثر منك مالا وأعز نفرا', NULL, 297, 'local:hafs-text.json'),
  ('hafs-18-35', 'hafs', 18, 35, 'وَدَخَلَ جَنَّتَهُۥ وَهُوَ ظَالِمٌۭ لِّنَفْسِهِۦ قَالَ مَآ أَظُنُّ أَن تَبِيدَ هَٰذِهِۦٓ أَبَدًۭا', 'ودخل جنته وهو ظالم لنفسه قال ما أظن أن تبيد هذه أبدا', NULL, 298, 'local:hafs-text.json'),
  ('hafs-18-36', 'hafs', 18, 36, 'وَمَآ أَظُنُّ ٱلسَّاعَةَ قَآئِمَةًۭ وَلَئِن رُّدِدتُّ إِلَىٰ رَبِّى لَأَجِدَنَّ خَيْرًۭا مِّنْهَا مُنقَلَبًۭا', 'وما أظن الساعة قائمة ولئن رددت إلى ربى لأجدن خيرا منها منقلبا', NULL, 298, 'local:hafs-text.json'),
  ('hafs-18-37', 'hafs', 18, 37, 'قَالَ لَهُۥ صَاحِبُهُۥ وَهُوَ يُحَاوِرُهُۥٓ أَكَفَرْتَ بِٱلَّذِى خَلَقَكَ مِن تُرَابٍۢ ثُمَّ مِن نُّطْفَةٍۢ ثُمَّ سَوَّىٰكَ رَجُلًۭا', 'قال له صاحبه وهو يحاوره أكفرت بالذى خلقك من تراب ثم من نطفة ثم سوىك رجلا', NULL, 298, 'local:hafs-text.json'),
  ('hafs-18-38', 'hafs', 18, 38, 'لَّٰكِنَّا۠ هُوَ ٱللَّهُ رَبِّى وَلَآ أُشْرِكُ بِرَبِّىٓ أَحَدًۭا', 'لكنا هو الله ربى ولا أشرك بربى أحدا', NULL, 298, 'local:hafs-text.json'),
  ('hafs-18-39', 'hafs', 18, 39, 'وَلَوْلَآ إِذْ دَخَلْتَ جَنَّتَكَ قُلْتَ مَا شَآءَ ٱللَّهُ لَا قُوَّةَ إِلَّا بِٱللَّهِ ۚ إِن تَرَنِ أَنَا۠ أَقَلَّ مِنكَ مَالًۭا وَوَلَدًۭا', 'ولولا إذ دخلت جنتك قلت ما شاء الله لا قوة إلا بالله  إن ترن أنا أقل منك مالا وولدا', NULL, 298, 'local:hafs-text.json'),
  ('hafs-18-40', 'hafs', 18, 40, 'فَعَسَىٰ رَبِّىٓ أَن يُؤْتِيَنِ خَيْرًۭا مِّن جَنَّتِكَ وَيُرْسِلَ عَلَيْهَا حُسْبَانًۭا مِّنَ ٱلسَّمَآءِ فَتُصْبِحَ صَعِيدًۭا زَلَقًا', 'فعسى ربى أن يؤتين خيرا من جنتك ويرسل عليها حسبانا من السماء فتصبح صعيدا زلقا', NULL, 298, 'local:hafs-text.json'),
  ('hafs-18-41', 'hafs', 18, 41, 'أَوْ يُصْبِحَ مَآؤُهَا غَوْرًۭا فَلَن تَسْتَطِيعَ لَهُۥ طَلَبًۭا', 'أو يصبح ماؤها غورا فلن تستطيع له طلبا', NULL, 298, 'local:hafs-text.json'),
  ('hafs-18-42', 'hafs', 18, 42, 'وَأُحِيطَ بِثَمَرِهِۦ فَأَصْبَحَ يُقَلِّبُ كَفَّيْهِ عَلَىٰ مَآ أَنفَقَ فِيهَا وَهِىَ خَاوِيَةٌ عَلَىٰ عُرُوشِهَا وَيَقُولُ يَٰلَيْتَنِى لَمْ أُشْرِكْ بِرَبِّىٓ أَحَدًۭا', 'وأحيط بثمره فأصبح يقلب كفيه على ما أنفق فيها وهى خاوية على عروشها ويقول يليتنى لم أشرك بربى أحدا', NULL, 298, 'local:hafs-text.json'),
  ('hafs-18-43', 'hafs', 18, 43, 'وَلَمْ تَكُن لَّهُۥ فِئَةٌۭ يَنصُرُونَهُۥ مِن دُونِ ٱللَّهِ وَمَا كَانَ مُنتَصِرًا', 'ولم تكن له فئة ينصرونه من دون الله وما كان منتصرا', NULL, 298, 'local:hafs-text.json'),
  ('hafs-18-44', 'hafs', 18, 44, 'هُنَالِكَ ٱلْوَلَٰيَةُ لِلَّهِ ٱلْحَقِّ ۚ هُوَ خَيْرٌۭ ثَوَابًۭا وَخَيْرٌ عُقْبًۭا', 'هنالك الولية لله الحق  هو خير ثوابا وخير عقبا', NULL, 298, 'local:hafs-text.json'),
  ('hafs-18-45', 'hafs', 18, 45, 'وَٱضْرِبْ لَهُم مَّثَلَ ٱلْحَيَوٰةِ ٱلدُّنْيَا كَمَآءٍ أَنزَلْنَٰهُ مِنَ ٱلسَّمَآءِ فَٱخْتَلَطَ بِهِۦ نَبَاتُ ٱلْأَرْضِ فَأَصْبَحَ هَشِيمًۭا تَذْرُوهُ ٱلرِّيَٰحُ ۗ وَكَانَ ٱللَّهُ عَلَىٰ كُلِّ شَىْءٍۢ مُّقْتَدِرًا', 'واضرب لهم مثل الحيوة الدنيا كماء أنزلنه من السماء فاختلط به نبات الأرض فأصبح هشيما تذروه الريح  وكان الله على كل شىء مقتدرا', NULL, 298, 'local:hafs-text.json'),
  ('hafs-18-46', 'hafs', 18, 46, 'ٱلْمَالُ وَٱلْبَنُونَ زِينَةُ ٱلْحَيَوٰةِ ٱلدُّنْيَا ۖ وَٱلْبَٰقِيَٰتُ ٱلصَّٰلِحَٰتُ خَيْرٌ عِندَ رَبِّكَ ثَوَابًۭا وَخَيْرٌ أَمَلًۭا', 'المال والبنون زينة الحيوة الدنيا  والبقيت الصلحت خير عند ربك ثوابا وخير أملا', NULL, 299, 'local:hafs-text.json'),
  ('hafs-18-47', 'hafs', 18, 47, 'وَيَوْمَ نُسَيِّرُ ٱلْجِبَالَ وَتَرَى ٱلْأَرْضَ بَارِزَةًۭ وَحَشَرْنَٰهُمْ فَلَمْ نُغَادِرْ مِنْهُمْ أَحَدًۭا', 'ويوم نسير الجبال وترى الأرض بارزة وحشرنهم فلم نغادر منهم أحدا', NULL, 299, 'local:hafs-text.json'),
  ('hafs-18-48', 'hafs', 18, 48, 'وَعُرِضُوا۟ عَلَىٰ رَبِّكَ صَفًّۭا لَّقَدْ جِئْتُمُونَا كَمَا خَلَقْنَٰكُمْ أَوَّلَ مَرَّةٍۭ ۚ بَلْ زَعَمْتُمْ أَلَّن نَّجْعَلَ لَكُم مَّوْعِدًۭا', 'وعرضوا على ربك صفا لقد جئتمونا كما خلقنكم أول مرة  بل زعمتم ألن نجعل لكم موعدا', NULL, 299, 'local:hafs-text.json'),
  ('hafs-18-49', 'hafs', 18, 49, 'وَوُضِعَ ٱلْكِتَٰبُ فَتَرَى ٱلْمُجْرِمِينَ مُشْفِقِينَ مِمَّا فِيهِ وَيَقُولُونَ يَٰوَيْلَتَنَا مَالِ هَٰذَا ٱلْكِتَٰبِ لَا يُغَادِرُ صَغِيرَةًۭ وَلَا كَبِيرَةً إِلَّآ أَحْصَىٰهَا ۚ وَوَجَدُوا۟ مَا عَمِلُوا۟ حَاضِرًۭا ۗ وَلَا يَظْلِمُ رَبُّكَ أَحَدًۭا', 'ووضع الكتب فترى المجرمين مشفقين مما فيه ويقولون يويلتنا مال هذا الكتب لا يغادر صغيرة ولا كبيرة إلا أحصىها  ووجدوا ما عملوا حاضرا  ولا يظلم ربك أحدا', NULL, 299, 'local:hafs-text.json'),
  ('hafs-18-50', 'hafs', 18, 50, 'وَإِذْ قُلْنَا لِلْمَلَٰٓئِكَةِ ٱسْجُدُوا۟ لِءَادَمَ فَسَجَدُوٓا۟ إِلَّآ إِبْلِيسَ كَانَ مِنَ ٱلْجِنِّ فَفَسَقَ عَنْ أَمْرِ رَبِّهِۦٓ ۗ أَفَتَتَّخِذُونَهُۥ وَذُرِّيَّتَهُۥٓ أَوْلِيَآءَ مِن دُونِى وَهُمْ لَكُمْ عَدُوٌّۢ ۚ بِئْسَ لِلظَّٰلِمِينَ بَدَلًۭا', 'وإذ قلنا للملئكة اسجدوا لءادم فسجدوا إلا إبليس كان من الجن ففسق عن أمر ربه  أفتتخذونه وذريته أولياء من دونى وهم لكم عدو  بئس للظلمين بدلا', NULL, 299, 'local:hafs-text.json'),
  ('hafs-18-51', 'hafs', 18, 51, '۞ مَّآ أَشْهَدتُّهُمْ خَلْقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَلَا خَلْقَ أَنفُسِهِمْ وَمَا كُنتُ مُتَّخِذَ ٱلْمُضِلِّينَ عَضُدًۭا', 'ما أشهدتهم خلق السموت والأرض ولا خلق أنفسهم وما كنت متخذ المضلين عضدا', NULL, 299, 'local:hafs-text.json'),
  ('hafs-18-52', 'hafs', 18, 52, 'وَيَوْمَ يَقُولُ نَادُوا۟ شُرَكَآءِىَ ٱلَّذِينَ زَعَمْتُمْ فَدَعَوْهُمْ فَلَمْ يَسْتَجِيبُوا۟ لَهُمْ وَجَعَلْنَا بَيْنَهُم مَّوْبِقًۭا', 'ويوم يقول نادوا شركاءى الذين زعمتم فدعوهم فلم يستجيبوا لهم وجعلنا بينهم موبقا', NULL, 299, 'local:hafs-text.json'),
  ('hafs-18-53', 'hafs', 18, 53, 'وَرَءَا ٱلْمُجْرِمُونَ ٱلنَّارَ فَظَنُّوٓا۟ أَنَّهُم مُّوَاقِعُوهَا وَلَمْ يَجِدُوا۟ عَنْهَا مَصْرِفًۭا', 'ورءا المجرمون النار فظنوا أنهم مواقعوها ولم يجدوا عنها مصرفا', NULL, 299, 'local:hafs-text.json'),
  ('hafs-18-54', 'hafs', 18, 54, 'وَلَقَدْ صَرَّفْنَا فِى هَٰذَا ٱلْقُرْءَانِ لِلنَّاسِ مِن كُلِّ مَثَلٍۢ ۚ وَكَانَ ٱلْإِنسَٰنُ أَكْثَرَ شَىْءٍۢ جَدَلًۭا', 'ولقد صرفنا فى هذا القرءان للناس من كل مثل  وكان الإنسن أكثر شىء جدلا', NULL, 300, 'local:hafs-text.json'),
  ('hafs-18-55', 'hafs', 18, 55, 'وَمَا مَنَعَ ٱلنَّاسَ أَن يُؤْمِنُوٓا۟ إِذْ جَآءَهُمُ ٱلْهُدَىٰ وَيَسْتَغْفِرُوا۟ رَبَّهُمْ إِلَّآ أَن تَأْتِيَهُمْ سُنَّةُ ٱلْأَوَّلِينَ أَوْ يَأْتِيَهُمُ ٱلْعَذَابُ قُبُلًۭا', 'وما منع الناس أن يؤمنوا إذ جاءهم الهدى ويستغفروا ربهم إلا أن تأتيهم سنة الأولين أو يأتيهم العذاب قبلا', NULL, 300, 'local:hafs-text.json'),
  ('hafs-18-56', 'hafs', 18, 56, 'وَمَا نُرْسِلُ ٱلْمُرْسَلِينَ إِلَّا مُبَشِّرِينَ وَمُنذِرِينَ ۚ وَيُجَٰدِلُ ٱلَّذِينَ كَفَرُوا۟ بِٱلْبَٰطِلِ لِيُدْحِضُوا۟ بِهِ ٱلْحَقَّ ۖ وَٱتَّخَذُوٓا۟ ءَايَٰتِى وَمَآ أُنذِرُوا۟ هُزُوًۭا', 'وما نرسل المرسلين إلا مبشرين ومنذرين  ويجدل الذين كفروا بالبطل ليدحضوا به الحق  واتخذوا ءايتى وما أنذروا هزوا', NULL, 300, 'local:hafs-text.json'),
  ('hafs-18-57', 'hafs', 18, 57, 'وَمَنْ أَظْلَمُ مِمَّن ذُكِّرَ بِـَٔايَٰتِ رَبِّهِۦ فَأَعْرَضَ عَنْهَا وَنَسِىَ مَا قَدَّمَتْ يَدَاهُ ۚ إِنَّا جَعَلْنَا عَلَىٰ قُلُوبِهِمْ أَكِنَّةً أَن يَفْقَهُوهُ وَفِىٓ ءَاذَانِهِمْ وَقْرًۭا ۖ وَإِن تَدْعُهُمْ إِلَى ٱلْهُدَىٰ فَلَن يَهْتَدُوٓا۟ إِذًا أَبَدًۭا', 'ومن أظلم ممن ذكر بايت ربه فأعرض عنها ونسى ما قدمت يداه  إنا جعلنا على قلوبهم أكنة أن يفقهوه وفى ءاذانهم وقرا  وإن تدعهم إلى الهدى فلن يهتدوا إذا أبدا', NULL, 300, 'local:hafs-text.json'),
  ('hafs-18-58', 'hafs', 18, 58, 'وَرَبُّكَ ٱلْغَفُورُ ذُو ٱلرَّحْمَةِ ۖ لَوْ يُؤَاخِذُهُم بِمَا كَسَبُوا۟ لَعَجَّلَ لَهُمُ ٱلْعَذَابَ ۚ بَل لَّهُم مَّوْعِدٌۭ لَّن يَجِدُوا۟ مِن دُونِهِۦ مَوْئِلًۭا', 'وربك الغفور ذو الرحمة  لو يؤاخذهم بما كسبوا لعجل لهم العذاب  بل لهم موعد لن يجدوا من دونه موئلا', NULL, 300, 'local:hafs-text.json'),
  ('hafs-18-59', 'hafs', 18, 59, 'وَتِلْكَ ٱلْقُرَىٰٓ أَهْلَكْنَٰهُمْ لَمَّا ظَلَمُوا۟ وَجَعَلْنَا لِمَهْلِكِهِم مَّوْعِدًۭا', 'وتلك القرى أهلكنهم لما ظلموا وجعلنا لمهلكهم موعدا', NULL, 300, 'local:hafs-text.json'),
  ('hafs-18-60', 'hafs', 18, 60, 'وَإِذْ قَالَ مُوسَىٰ لِفَتَىٰهُ لَآ أَبْرَحُ حَتَّىٰٓ أَبْلُغَ مَجْمَعَ ٱلْبَحْرَيْنِ أَوْ أَمْضِىَ حُقُبًۭا', 'وإذ قال موسى لفتىه لا أبرح حتى أبلغ مجمع البحرين أو أمضى حقبا', NULL, 300, 'local:hafs-text.json'),
  ('hafs-18-61', 'hafs', 18, 61, 'فَلَمَّا بَلَغَا مَجْمَعَ بَيْنِهِمَا نَسِيَا حُوتَهُمَا فَٱتَّخَذَ سَبِيلَهُۥ فِى ٱلْبَحْرِ سَرَبًۭا', 'فلما بلغا مجمع بينهما نسيا حوتهما فاتخذ سبيله فى البحر سربا', NULL, 300, 'local:hafs-text.json'),
  ('hafs-18-62', 'hafs', 18, 62, 'فَلَمَّا جَاوَزَا قَالَ لِفَتَىٰهُ ءَاتِنَا غَدَآءَنَا لَقَدْ لَقِينَا مِن سَفَرِنَا هَٰذَا نَصَبًۭا', 'فلما جاوزا قال لفتىه ءاتنا غداءنا لقد لقينا من سفرنا هذا نصبا', NULL, 301, 'local:hafs-text.json'),
  ('hafs-18-63', 'hafs', 18, 63, 'قَالَ أَرَءَيْتَ إِذْ أَوَيْنَآ إِلَى ٱلصَّخْرَةِ فَإِنِّى نَسِيتُ ٱلْحُوتَ وَمَآ أَنسَىٰنِيهُ إِلَّا ٱلشَّيْطَٰنُ أَنْ أَذْكُرَهُۥ ۚ وَٱتَّخَذَ سَبِيلَهُۥ فِى ٱلْبَحْرِ عَجَبًۭا', 'قال أرءيت إذ أوينا إلى الصخرة فإنى نسيت الحوت وما أنسىنيه إلا الشيطن أن أذكره  واتخذ سبيله فى البحر عجبا', NULL, 301, 'local:hafs-text.json'),
  ('hafs-18-64', 'hafs', 18, 64, 'قَالَ ذَٰلِكَ مَا كُنَّا نَبْغِ ۚ فَٱرْتَدَّا عَلَىٰٓ ءَاثَارِهِمَا قَصَصًۭا', 'قال ذلك ما كنا نبغ  فارتدا على ءاثارهما قصصا', NULL, 301, 'local:hafs-text.json'),
  ('hafs-18-65', 'hafs', 18, 65, 'فَوَجَدَا عَبْدًۭا مِّنْ عِبَادِنَآ ءَاتَيْنَٰهُ رَحْمَةًۭ مِّنْ عِندِنَا وَعَلَّمْنَٰهُ مِن لَّدُنَّا عِلْمًۭا', 'فوجدا عبدا من عبادنا ءاتينه رحمة من عندنا وعلمنه من لدنا علما', NULL, 301, 'local:hafs-text.json'),
  ('hafs-18-66', 'hafs', 18, 66, 'قَالَ لَهُۥ مُوسَىٰ هَلْ أَتَّبِعُكَ عَلَىٰٓ أَن تُعَلِّمَنِ مِمَّا عُلِّمْتَ رُشْدًۭا', 'قال له موسى هل أتبعك على أن تعلمن مما علمت رشدا', NULL, 301, 'local:hafs-text.json'),
  ('hafs-18-67', 'hafs', 18, 67, 'قَالَ إِنَّكَ لَن تَسْتَطِيعَ مَعِىَ صَبْرًۭا', 'قال إنك لن تستطيع معى صبرا', NULL, 301, 'local:hafs-text.json'),
  ('hafs-18-68', 'hafs', 18, 68, 'وَكَيْفَ تَصْبِرُ عَلَىٰ مَا لَمْ تُحِطْ بِهِۦ خُبْرًۭا', 'وكيف تصبر على ما لم تحط به خبرا', NULL, 301, 'local:hafs-text.json'),
  ('hafs-18-69', 'hafs', 18, 69, 'قَالَ سَتَجِدُنِىٓ إِن شَآءَ ٱللَّهُ صَابِرًۭا وَلَآ أَعْصِى لَكَ أَمْرًۭا', 'قال ستجدنى إن شاء الله صابرا ولا أعصى لك أمرا', NULL, 301, 'local:hafs-text.json'),
  ('hafs-18-70', 'hafs', 18, 70, 'قَالَ فَإِنِ ٱتَّبَعْتَنِى فَلَا تَسْـَٔلْنِى عَن شَىْءٍ حَتَّىٰٓ أُحْدِثَ لَكَ مِنْهُ ذِكْرًۭا', 'قال فإن اتبعتنى فلا تسلنى عن شىء حتى أحدث لك منه ذكرا', NULL, 301, 'local:hafs-text.json'),
  ('hafs-18-71', 'hafs', 18, 71, 'فَٱنطَلَقَا حَتَّىٰٓ إِذَا رَكِبَا فِى ٱلسَّفِينَةِ خَرَقَهَا ۖ قَالَ أَخَرَقْتَهَا لِتُغْرِقَ أَهْلَهَا لَقَدْ جِئْتَ شَيْـًٔا إِمْرًۭا', 'فانطلقا حتى إذا ركبا فى السفينة خرقها  قال أخرقتها لتغرق أهلها لقد جئت شيا إمرا', NULL, 301, 'local:hafs-text.json'),
  ('hafs-18-72', 'hafs', 18, 72, 'قَالَ أَلَمْ أَقُلْ إِنَّكَ لَن تَسْتَطِيعَ مَعِىَ صَبْرًۭا', 'قال ألم أقل إنك لن تستطيع معى صبرا', NULL, 301, 'local:hafs-text.json'),
  ('hafs-18-73', 'hafs', 18, 73, 'قَالَ لَا تُؤَاخِذْنِى بِمَا نَسِيتُ وَلَا تُرْهِقْنِى مِنْ أَمْرِى عُسْرًۭا', 'قال لا تؤاخذنى بما نسيت ولا ترهقنى من أمرى عسرا', NULL, 301, 'local:hafs-text.json'),
  ('hafs-18-74', 'hafs', 18, 74, 'فَٱنطَلَقَا حَتَّىٰٓ إِذَا لَقِيَا غُلَٰمًۭا فَقَتَلَهُۥ قَالَ أَقَتَلْتَ نَفْسًۭا زَكِيَّةًۢ بِغَيْرِ نَفْسٍۢ لَّقَدْ جِئْتَ شَيْـًۭٔا نُّكْرًۭا', 'فانطلقا حتى إذا لقيا غلما فقتله قال أقتلت نفسا زكية بغير نفس لقد جئت شيا نكرا', NULL, 301, 'local:hafs-text.json'),
  ('hafs-18-75', 'hafs', 18, 75, '۞ قَالَ أَلَمْ أَقُل لَّكَ إِنَّكَ لَن تَسْتَطِيعَ مَعِىَ صَبْرًۭا', 'قال ألم أقل لك إنك لن تستطيع معى صبرا', NULL, 302, 'local:hafs-text.json'),
  ('hafs-18-76', 'hafs', 18, 76, 'قَالَ إِن سَأَلْتُكَ عَن شَىْءٍۭ بَعْدَهَا فَلَا تُصَٰحِبْنِى ۖ قَدْ بَلَغْتَ مِن لَّدُنِّى عُذْرًۭا', 'قال إن سألتك عن شىء بعدها فلا تصحبنى  قد بلغت من لدنى عذرا', NULL, 302, 'local:hafs-text.json'),
  ('hafs-18-77', 'hafs', 18, 77, 'فَٱنطَلَقَا حَتَّىٰٓ إِذَآ أَتَيَآ أَهْلَ قَرْيَةٍ ٱسْتَطْعَمَآ أَهْلَهَا فَأَبَوْا۟ أَن يُضَيِّفُوهُمَا فَوَجَدَا فِيهَا جِدَارًۭا يُرِيدُ أَن يَنقَضَّ فَأَقَامَهُۥ ۖ قَالَ لَوْ شِئْتَ لَتَّخَذْتَ عَلَيْهِ أَجْرًۭا', 'فانطلقا حتى إذا أتيا أهل قرية استطعما أهلها فأبوا أن يضيفوهما فوجدا فيها جدارا يريد أن ينقض فأقامه  قال لو شئت لتخذت عليه أجرا', NULL, 302, 'local:hafs-text.json'),
  ('hafs-18-78', 'hafs', 18, 78, 'قَالَ هَٰذَا فِرَاقُ بَيْنِى وَبَيْنِكَ ۚ سَأُنَبِّئُكَ بِتَأْوِيلِ مَا لَمْ تَسْتَطِع عَّلَيْهِ صَبْرًا', 'قال هذا فراق بينى وبينك  سأنبئك بتأويل ما لم تستطع عليه صبرا', NULL, 302, 'local:hafs-text.json'),
  ('hafs-18-79', 'hafs', 18, 79, 'أَمَّا ٱلسَّفِينَةُ فَكَانَتْ لِمَسَٰكِينَ يَعْمَلُونَ فِى ٱلْبَحْرِ فَأَرَدتُّ أَنْ أَعِيبَهَا وَكَانَ وَرَآءَهُم مَّلِكٌۭ يَأْخُذُ كُلَّ سَفِينَةٍ غَصْبًۭا', 'أما السفينة فكانت لمسكين يعملون فى البحر فأردت أن أعيبها وكان وراءهم ملك يأخذ كل سفينة غصبا', NULL, 302, 'local:hafs-text.json'),
  ('hafs-18-80', 'hafs', 18, 80, 'وَأَمَّا ٱلْغُلَٰمُ فَكَانَ أَبَوَاهُ مُؤْمِنَيْنِ فَخَشِينَآ أَن يُرْهِقَهُمَا طُغْيَٰنًۭا وَكُفْرًۭا', 'وأما الغلم فكان أبواه مؤمنين فخشينا أن يرهقهما طغينا وكفرا', NULL, 302, 'local:hafs-text.json'),
  ('hafs-18-81', 'hafs', 18, 81, 'فَأَرَدْنَآ أَن يُبْدِلَهُمَا رَبُّهُمَا خَيْرًۭا مِّنْهُ زَكَوٰةًۭ وَأَقْرَبَ رُحْمًۭا', 'فأردنا أن يبدلهما ربهما خيرا منه زكوة وأقرب رحما', NULL, 302, 'local:hafs-text.json'),
  ('hafs-18-82', 'hafs', 18, 82, 'وَأَمَّا ٱلْجِدَارُ فَكَانَ لِغُلَٰمَيْنِ يَتِيمَيْنِ فِى ٱلْمَدِينَةِ وَكَانَ تَحْتَهُۥ كَنزٌۭ لَّهُمَا وَكَانَ أَبُوهُمَا صَٰلِحًۭا فَأَرَادَ رَبُّكَ أَن يَبْلُغَآ أَشُدَّهُمَا وَيَسْتَخْرِجَا كَنزَهُمَا رَحْمَةًۭ مِّن رَّبِّكَ ۚ وَمَا فَعَلْتُهُۥ عَنْ أَمْرِى ۚ ذَٰلِكَ تَأْوِيلُ مَا لَمْ تَسْطِع عَّلَيْهِ صَبْرًۭا', 'وأما الجدار فكان لغلمين يتيمين فى المدينة وكان تحته كنز لهما وكان أبوهما صلحا فأراد ربك أن يبلغا أشدهما ويستخرجا كنزهما رحمة من ربك  وما فعلته عن أمرى  ذلك تأويل ما لم تسطع عليه صبرا', NULL, 302, 'local:hafs-text.json'),
  ('hafs-18-83', 'hafs', 18, 83, 'وَيَسْـَٔلُونَكَ عَن ذِى ٱلْقَرْنَيْنِ ۖ قُلْ سَأَتْلُوا۟ عَلَيْكُم مِّنْهُ ذِكْرًا', 'ويسلونك عن ذى القرنين  قل سأتلوا عليكم منه ذكرا', NULL, 302, 'local:hafs-text.json'),
  ('hafs-18-84', 'hafs', 18, 84, 'إِنَّا مَكَّنَّا لَهُۥ فِى ٱلْأَرْضِ وَءَاتَيْنَٰهُ مِن كُلِّ شَىْءٍۢ سَبَبًۭا', 'إنا مكنا له فى الأرض وءاتينه من كل شىء سببا', NULL, 303, 'local:hafs-text.json'),
  ('hafs-18-85', 'hafs', 18, 85, 'فَأَتْبَعَ سَبَبًا', 'فأتبع سببا', NULL, 303, 'local:hafs-text.json'),
  ('hafs-18-86', 'hafs', 18, 86, 'حَتَّىٰٓ إِذَا بَلَغَ مَغْرِبَ ٱلشَّمْسِ وَجَدَهَا تَغْرُبُ فِى عَيْنٍ حَمِئَةٍۢ وَوَجَدَ عِندَهَا قَوْمًۭا ۗ قُلْنَا يَٰذَا ٱلْقَرْنَيْنِ إِمَّآ أَن تُعَذِّبَ وَإِمَّآ أَن تَتَّخِذَ فِيهِمْ حُسْنًۭا', 'حتى إذا بلغ مغرب الشمس وجدها تغرب فى عين حمئة ووجد عندها قوما  قلنا يذا القرنين إما أن تعذب وإما أن تتخذ فيهم حسنا', NULL, 303, 'local:hafs-text.json'),
  ('hafs-18-87', 'hafs', 18, 87, 'قَالَ أَمَّا مَن ظَلَمَ فَسَوْفَ نُعَذِّبُهُۥ ثُمَّ يُرَدُّ إِلَىٰ رَبِّهِۦ فَيُعَذِّبُهُۥ عَذَابًۭا نُّكْرًۭا', 'قال أما من ظلم فسوف نعذبه ثم يرد إلى ربه فيعذبه عذابا نكرا', NULL, 303, 'local:hafs-text.json'),
  ('hafs-18-88', 'hafs', 18, 88, 'وَأَمَّا مَنْ ءَامَنَ وَعَمِلَ صَٰلِحًۭا فَلَهُۥ جَزَآءً ٱلْحُسْنَىٰ ۖ وَسَنَقُولُ لَهُۥ مِنْ أَمْرِنَا يُسْرًۭا', 'وأما من ءامن وعمل صلحا فله جزاء الحسنى  وسنقول له من أمرنا يسرا', NULL, 303, 'local:hafs-text.json'),
  ('hafs-18-89', 'hafs', 18, 89, 'ثُمَّ أَتْبَعَ سَبَبًا', 'ثم أتبع سببا', NULL, 303, 'local:hafs-text.json'),
  ('hafs-18-90', 'hafs', 18, 90, 'حَتَّىٰٓ إِذَا بَلَغَ مَطْلِعَ ٱلشَّمْسِ وَجَدَهَا تَطْلُعُ عَلَىٰ قَوْمٍۢ لَّمْ نَجْعَل لَّهُم مِّن دُونِهَا سِتْرًۭا', 'حتى إذا بلغ مطلع الشمس وجدها تطلع على قوم لم نجعل لهم من دونها سترا', NULL, 303, 'local:hafs-text.json'),
  ('hafs-18-91', 'hafs', 18, 91, 'كَذَٰلِكَ وَقَدْ أَحَطْنَا بِمَا لَدَيْهِ خُبْرًۭا', 'كذلك وقد أحطنا بما لديه خبرا', NULL, 303, 'local:hafs-text.json'),
  ('hafs-18-92', 'hafs', 18, 92, 'ثُمَّ أَتْبَعَ سَبَبًا', 'ثم أتبع سببا', NULL, 303, 'local:hafs-text.json'),
  ('hafs-18-93', 'hafs', 18, 93, 'حَتَّىٰٓ إِذَا بَلَغَ بَيْنَ ٱلسَّدَّيْنِ وَجَدَ مِن دُونِهِمَا قَوْمًۭا لَّا يَكَادُونَ يَفْقَهُونَ قَوْلًۭا', 'حتى إذا بلغ بين السدين وجد من دونهما قوما لا يكادون يفقهون قولا', NULL, 303, 'local:hafs-text.json'),
  ('hafs-18-94', 'hafs', 18, 94, 'قَالُوا۟ يَٰذَا ٱلْقَرْنَيْنِ إِنَّ يَأْجُوجَ وَمَأْجُوجَ مُفْسِدُونَ فِى ٱلْأَرْضِ فَهَلْ نَجْعَلُ لَكَ خَرْجًا عَلَىٰٓ أَن تَجْعَلَ بَيْنَنَا وَبَيْنَهُمْ سَدًّۭا', 'قالوا يذا القرنين إن يأجوج ومأجوج مفسدون فى الأرض فهل نجعل لك خرجا على أن تجعل بيننا وبينهم سدا', NULL, 303, 'local:hafs-text.json'),
  ('hafs-18-95', 'hafs', 18, 95, 'قَالَ مَا مَكَّنِّى فِيهِ رَبِّى خَيْرٌۭ فَأَعِينُونِى بِقُوَّةٍ أَجْعَلْ بَيْنَكُمْ وَبَيْنَهُمْ رَدْمًا', 'قال ما مكنى فيه ربى خير فأعينونى بقوة أجعل بينكم وبينهم ردما', NULL, 303, 'local:hafs-text.json'),
  ('hafs-18-96', 'hafs', 18, 96, 'ءَاتُونِى زُبَرَ ٱلْحَدِيدِ ۖ حَتَّىٰٓ إِذَا سَاوَىٰ بَيْنَ ٱلصَّدَفَيْنِ قَالَ ٱنفُخُوا۟ ۖ حَتَّىٰٓ إِذَا جَعَلَهُۥ نَارًۭا قَالَ ءَاتُونِىٓ أُفْرِغْ عَلَيْهِ قِطْرًۭا', 'ءاتونى زبر الحديد  حتى إذا ساوى بين الصدفين قال انفخوا  حتى إذا جعله نارا قال ءاتونى أفرغ عليه قطرا', NULL, 303, 'local:hafs-text.json'),
  ('hafs-18-97', 'hafs', 18, 97, 'فَمَا ٱسْطَٰعُوٓا۟ أَن يَظْهَرُوهُ وَمَا ٱسْتَطَٰعُوا۟ لَهُۥ نَقْبًۭا', 'فما اسطعوا أن يظهروه وما استطعوا له نقبا', NULL, 303, 'local:hafs-text.json'),
  ('hafs-18-98', 'hafs', 18, 98, 'قَالَ هَٰذَا رَحْمَةٌۭ مِّن رَّبِّى ۖ فَإِذَا جَآءَ وَعْدُ رَبِّى جَعَلَهُۥ دَكَّآءَ ۖ وَكَانَ وَعْدُ رَبِّى حَقًّۭا', 'قال هذا رحمة من ربى  فإذا جاء وعد ربى جعله دكاء  وكان وعد ربى حقا', NULL, 304, 'local:hafs-text.json'),
  ('hafs-18-99', 'hafs', 18, 99, '۞ وَتَرَكْنَا بَعْضَهُمْ يَوْمَئِذٍۢ يَمُوجُ فِى بَعْضٍۢ ۖ وَنُفِخَ فِى ٱلصُّورِ فَجَمَعْنَٰهُمْ جَمْعًۭا', 'وتركنا بعضهم يومئذ يموج فى بعض  ونفخ فى الصور فجمعنهم جمعا', NULL, 304, 'local:hafs-text.json'),
  ('hafs-18-100', 'hafs', 18, 100, 'وَعَرَضْنَا جَهَنَّمَ يَوْمَئِذٍۢ لِّلْكَٰفِرِينَ عَرْضًا', 'وعرضنا جهنم يومئذ للكفرين عرضا', NULL, 304, 'local:hafs-text.json'),
  ('hafs-18-101', 'hafs', 18, 101, 'ٱلَّذِينَ كَانَتْ أَعْيُنُهُمْ فِى غِطَآءٍ عَن ذِكْرِى وَكَانُوا۟ لَا يَسْتَطِيعُونَ سَمْعًا', 'الذين كانت أعينهم فى غطاء عن ذكرى وكانوا لا يستطيعون سمعا', NULL, 304, 'local:hafs-text.json'),
  ('hafs-18-102', 'hafs', 18, 102, 'أَفَحَسِبَ ٱلَّذِينَ كَفَرُوٓا۟ أَن يَتَّخِذُوا۟ عِبَادِى مِن دُونِىٓ أَوْلِيَآءَ ۚ إِنَّآ أَعْتَدْنَا جَهَنَّمَ لِلْكَٰفِرِينَ نُزُلًۭا', 'أفحسب الذين كفروا أن يتخذوا عبادى من دونى أولياء  إنا أعتدنا جهنم للكفرين نزلا', NULL, 304, 'local:hafs-text.json'),
  ('hafs-18-103', 'hafs', 18, 103, 'قُلْ هَلْ نُنَبِّئُكُم بِٱلْأَخْسَرِينَ أَعْمَٰلًا', 'قل هل ننبئكم بالأخسرين أعملا', NULL, 304, 'local:hafs-text.json'),
  ('hafs-18-104', 'hafs', 18, 104, 'ٱلَّذِينَ ضَلَّ سَعْيُهُمْ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا وَهُمْ يَحْسَبُونَ أَنَّهُمْ يُحْسِنُونَ صُنْعًا', 'الذين ضل سعيهم فى الحيوة الدنيا وهم يحسبون أنهم يحسنون صنعا', NULL, 304, 'local:hafs-text.json'),
  ('hafs-18-105', 'hafs', 18, 105, 'أُو۟لَٰٓئِكَ ٱلَّذِينَ كَفَرُوا۟ بِـَٔايَٰتِ رَبِّهِمْ وَلِقَآئِهِۦ فَحَبِطَتْ أَعْمَٰلُهُمْ فَلَا نُقِيمُ لَهُمْ يَوْمَ ٱلْقِيَٰمَةِ وَزْنًۭا', 'أولئك الذين كفروا بايت ربهم ولقائه فحبطت أعملهم فلا نقيم لهم يوم القيمة وزنا', NULL, 304, 'local:hafs-text.json'),
  ('hafs-18-106', 'hafs', 18, 106, 'ذَٰلِكَ جَزَآؤُهُمْ جَهَنَّمُ بِمَا كَفَرُوا۟ وَٱتَّخَذُوٓا۟ ءَايَٰتِى وَرُسُلِى هُزُوًا', 'ذلك جزاؤهم جهنم بما كفروا واتخذوا ءايتى ورسلى هزوا', NULL, 304, 'local:hafs-text.json'),
  ('hafs-18-107', 'hafs', 18, 107, 'إِنَّ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ كَانَتْ لَهُمْ جَنَّٰتُ ٱلْفِرْدَوْسِ نُزُلًا', 'إن الذين ءامنوا وعملوا الصلحت كانت لهم جنت الفردوس نزلا', NULL, 304, 'local:hafs-text.json'),
  ('hafs-18-108', 'hafs', 18, 108, 'خَٰلِدِينَ فِيهَا لَا يَبْغُونَ عَنْهَا حِوَلًۭا', 'خلدين فيها لا يبغون عنها حولا', NULL, 304, 'local:hafs-text.json'),
  ('hafs-18-109', 'hafs', 18, 109, 'قُل لَّوْ كَانَ ٱلْبَحْرُ مِدَادًۭا لِّكَلِمَٰتِ رَبِّى لَنَفِدَ ٱلْبَحْرُ قَبْلَ أَن تَنفَدَ كَلِمَٰتُ رَبِّى وَلَوْ جِئْنَا بِمِثْلِهِۦ مَدَدًۭا', 'قل لو كان البحر مدادا لكلمت ربى لنفد البحر قبل أن تنفد كلمت ربى ولو جئنا بمثله مددا', NULL, 304, 'local:hafs-text.json'),
  ('hafs-18-110', 'hafs', 18, 110, 'قُلْ إِنَّمَآ أَنَا۠ بَشَرٌۭ مِّثْلُكُمْ يُوحَىٰٓ إِلَىَّ أَنَّمَآ إِلَٰهُكُمْ إِلَٰهٌۭ وَٰحِدٌۭ ۖ فَمَن كَانَ يَرْجُوا۟ لِقَآءَ رَبِّهِۦ فَلْيَعْمَلْ عَمَلًۭا صَٰلِحًۭا وَلَا يُشْرِكْ بِعِبَادَةِ رَبِّهِۦٓ أَحَدًۢا', 'قل إنما أنا بشر مثلكم يوحى إلى أنما إلهكم إله وحد  فمن كان يرجوا لقاء ربه فليعمل عملا صلحا ولا يشرك بعبادة ربه أحدا', NULL, 304, 'local:hafs-text.json'),
  ('hafs-19-1', 'hafs', 19, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ كٓهيعٓصٓ', 'بسم الله الرحمن الرحيم كهيعص', NULL, 305, 'local:hafs-text.json'),
  ('hafs-19-2', 'hafs', 19, 2, 'ذِكْرُ رَحْمَتِ رَبِّكَ عَبْدَهُۥ زَكَرِيَّآ', 'ذكر رحمت ربك عبده زكريا', NULL, 305, 'local:hafs-text.json'),
  ('hafs-19-3', 'hafs', 19, 3, 'إِذْ نَادَىٰ رَبَّهُۥ نِدَآءً خَفِيًّۭا', 'إذ نادى ربه نداء خفيا', NULL, 305, 'local:hafs-text.json'),
  ('hafs-19-4', 'hafs', 19, 4, 'قَالَ رَبِّ إِنِّى وَهَنَ ٱلْعَظْمُ مِنِّى وَٱشْتَعَلَ ٱلرَّأْسُ شَيْبًۭا وَلَمْ أَكُنۢ بِدُعَآئِكَ رَبِّ شَقِيًّۭا', 'قال رب إنى وهن العظم منى واشتعل الرأس شيبا ولم أكن بدعائك رب شقيا', NULL, 305, 'local:hafs-text.json'),
  ('hafs-19-5', 'hafs', 19, 5, 'وَإِنِّى خِفْتُ ٱلْمَوَٰلِىَ مِن وَرَآءِى وَكَانَتِ ٱمْرَأَتِى عَاقِرًۭا فَهَبْ لِى مِن لَّدُنكَ وَلِيًّۭا', 'وإنى خفت المولى من وراءى وكانت امرأتى عاقرا فهب لى من لدنك وليا', NULL, 305, 'local:hafs-text.json'),
  ('hafs-19-6', 'hafs', 19, 6, 'يَرِثُنِى وَيَرِثُ مِنْ ءَالِ يَعْقُوبَ ۖ وَٱجْعَلْهُ رَبِّ رَضِيًّۭا', 'يرثنى ويرث من ءال يعقوب  واجعله رب رضيا', NULL, 305, 'local:hafs-text.json'),
  ('hafs-19-7', 'hafs', 19, 7, 'يَٰزَكَرِيَّآ إِنَّا نُبَشِّرُكَ بِغُلَٰمٍ ٱسْمُهُۥ يَحْيَىٰ لَمْ نَجْعَل لَّهُۥ مِن قَبْلُ سَمِيًّۭا', 'يزكريا إنا نبشرك بغلم اسمه يحيى لم نجعل له من قبل سميا', NULL, 305, 'local:hafs-text.json'),
  ('hafs-19-8', 'hafs', 19, 8, 'قَالَ رَبِّ أَنَّىٰ يَكُونُ لِى غُلَٰمٌۭ وَكَانَتِ ٱمْرَأَتِى عَاقِرًۭا وَقَدْ بَلَغْتُ مِنَ ٱلْكِبَرِ عِتِيًّۭا', 'قال رب أنى يكون لى غلم وكانت امرأتى عاقرا وقد بلغت من الكبر عتيا', NULL, 305, 'local:hafs-text.json'),
  ('hafs-19-9', 'hafs', 19, 9, 'قَالَ كَذَٰلِكَ قَالَ رَبُّكَ هُوَ عَلَىَّ هَيِّنٌۭ وَقَدْ خَلَقْتُكَ مِن قَبْلُ وَلَمْ تَكُ شَيْـًۭٔا', 'قال كذلك قال ربك هو على هين وقد خلقتك من قبل ولم تك شيا', NULL, 305, 'local:hafs-text.json'),
  ('hafs-19-10', 'hafs', 19, 10, 'قَالَ رَبِّ ٱجْعَل لِّىٓ ءَايَةًۭ ۚ قَالَ ءَايَتُكَ أَلَّا تُكَلِّمَ ٱلنَّاسَ ثَلَٰثَ لَيَالٍۢ سَوِيًّۭا', 'قال رب اجعل لى ءاية  قال ءايتك ألا تكلم الناس ثلث ليال سويا', NULL, 305, 'local:hafs-text.json'),
  ('hafs-19-11', 'hafs', 19, 11, 'فَخَرَجَ عَلَىٰ قَوْمِهِۦ مِنَ ٱلْمِحْرَابِ فَأَوْحَىٰٓ إِلَيْهِمْ أَن سَبِّحُوا۟ بُكْرَةًۭ وَعَشِيًّۭا', 'فخرج على قومه من المحراب فأوحى إليهم أن سبحوا بكرة وعشيا', NULL, 305, 'local:hafs-text.json'),
  ('hafs-19-12', 'hafs', 19, 12, 'يَٰيَحْيَىٰ خُذِ ٱلْكِتَٰبَ بِقُوَّةٍۢ ۖ وَءَاتَيْنَٰهُ ٱلْحُكْمَ صَبِيًّۭا', 'ييحيى خذ الكتب بقوة  وءاتينه الحكم صبيا', NULL, 306, 'local:hafs-text.json'),
  ('hafs-19-13', 'hafs', 19, 13, 'وَحَنَانًۭا مِّن لَّدُنَّا وَزَكَوٰةًۭ ۖ وَكَانَ تَقِيًّۭا', 'وحنانا من لدنا وزكوة  وكان تقيا', NULL, 306, 'local:hafs-text.json'),
  ('hafs-19-14', 'hafs', 19, 14, 'وَبَرًّۢا بِوَٰلِدَيْهِ وَلَمْ يَكُن جَبَّارًا عَصِيًّۭا', 'وبرا بولديه ولم يكن جبارا عصيا', NULL, 306, 'local:hafs-text.json'),
  ('hafs-19-15', 'hafs', 19, 15, 'وَسَلَٰمٌ عَلَيْهِ يَوْمَ وُلِدَ وَيَوْمَ يَمُوتُ وَيَوْمَ يُبْعَثُ حَيًّۭا', 'وسلم عليه يوم ولد ويوم يموت ويوم يبعث حيا', NULL, 306, 'local:hafs-text.json'),
  ('hafs-19-16', 'hafs', 19, 16, 'وَٱذْكُرْ فِى ٱلْكِتَٰبِ مَرْيَمَ إِذِ ٱنتَبَذَتْ مِنْ أَهْلِهَا مَكَانًۭا شَرْقِيًّۭا', 'واذكر فى الكتب مريم إذ انتبذت من أهلها مكانا شرقيا', NULL, 306, 'local:hafs-text.json'),
  ('hafs-19-17', 'hafs', 19, 17, 'فَٱتَّخَذَتْ مِن دُونِهِمْ حِجَابًۭا فَأَرْسَلْنَآ إِلَيْهَا رُوحَنَا فَتَمَثَّلَ لَهَا بَشَرًۭا سَوِيًّۭا', 'فاتخذت من دونهم حجابا فأرسلنا إليها روحنا فتمثل لها بشرا سويا', NULL, 306, 'local:hafs-text.json'),
  ('hafs-19-18', 'hafs', 19, 18, 'قَالَتْ إِنِّىٓ أَعُوذُ بِٱلرَّحْمَٰنِ مِنكَ إِن كُنتَ تَقِيًّۭا', 'قالت إنى أعوذ بالرحمن منك إن كنت تقيا', NULL, 306, 'local:hafs-text.json'),
  ('hafs-19-19', 'hafs', 19, 19, 'قَالَ إِنَّمَآ أَنَا۠ رَسُولُ رَبِّكِ لِأَهَبَ لَكِ غُلَٰمًۭا زَكِيًّۭا', 'قال إنما أنا رسول ربك لأهب لك غلما زكيا', NULL, 306, 'local:hafs-text.json'),
  ('hafs-19-20', 'hafs', 19, 20, 'قَالَتْ أَنَّىٰ يَكُونُ لِى غُلَٰمٌۭ وَلَمْ يَمْسَسْنِى بَشَرٌۭ وَلَمْ أَكُ بَغِيًّۭا', 'قالت أنى يكون لى غلم ولم يمسسنى بشر ولم أك بغيا', NULL, 306, 'local:hafs-text.json'),
  ('hafs-19-21', 'hafs', 19, 21, 'قَالَ كَذَٰلِكِ قَالَ رَبُّكِ هُوَ عَلَىَّ هَيِّنٌۭ ۖ وَلِنَجْعَلَهُۥٓ ءَايَةًۭ لِّلنَّاسِ وَرَحْمَةًۭ مِّنَّا ۚ وَكَانَ أَمْرًۭا مَّقْضِيًّۭا', 'قال كذلك قال ربك هو على هين  ولنجعله ءاية للناس ورحمة منا  وكان أمرا مقضيا', NULL, 306, 'local:hafs-text.json'),
  ('hafs-19-22', 'hafs', 19, 22, '۞ فَحَمَلَتْهُ فَٱنتَبَذَتْ بِهِۦ مَكَانًۭا قَصِيًّۭا', 'فحملته فانتبذت به مكانا قصيا', NULL, 306, 'local:hafs-text.json'),
  ('hafs-19-23', 'hafs', 19, 23, 'فَأَجَآءَهَا ٱلْمَخَاضُ إِلَىٰ جِذْعِ ٱلنَّخْلَةِ قَالَتْ يَٰلَيْتَنِى مِتُّ قَبْلَ هَٰذَا وَكُنتُ نَسْيًۭا مَّنسِيًّۭا', 'فأجاءها المخاض إلى جذع النخلة قالت يليتنى مت قبل هذا وكنت نسيا منسيا', NULL, 306, 'local:hafs-text.json'),
  ('hafs-19-24', 'hafs', 19, 24, 'فَنَادَىٰهَا مِن تَحْتِهَآ أَلَّا تَحْزَنِى قَدْ جَعَلَ رَبُّكِ تَحْتَكِ سَرِيًّۭا', 'فنادىها من تحتها ألا تحزنى قد جعل ربك تحتك سريا', NULL, 306, 'local:hafs-text.json'),
  ('hafs-19-25', 'hafs', 19, 25, 'وَهُزِّىٓ إِلَيْكِ بِجِذْعِ ٱلنَّخْلَةِ تُسَٰقِطْ عَلَيْكِ رُطَبًۭا جَنِيًّۭا', 'وهزى إليك بجذع النخلة تسقط عليك رطبا جنيا', NULL, 306, 'local:hafs-text.json'),
  ('hafs-19-26', 'hafs', 19, 26, 'فَكُلِى وَٱشْرَبِى وَقَرِّى عَيْنًۭا ۖ فَإِمَّا تَرَيِنَّ مِنَ ٱلْبَشَرِ أَحَدًۭا فَقُولِىٓ إِنِّى نَذَرْتُ لِلرَّحْمَٰنِ صَوْمًۭا فَلَنْ أُكَلِّمَ ٱلْيَوْمَ إِنسِيًّۭا', 'فكلى واشربى وقرى عينا  فإما ترين من البشر أحدا فقولى إنى نذرت للرحمن صوما فلن أكلم اليوم إنسيا', NULL, 307, 'local:hafs-text.json'),
  ('hafs-19-27', 'hafs', 19, 27, 'فَأَتَتْ بِهِۦ قَوْمَهَا تَحْمِلُهُۥ ۖ قَالُوا۟ يَٰمَرْيَمُ لَقَدْ جِئْتِ شَيْـًۭٔا فَرِيًّۭا', 'فأتت به قومها تحمله  قالوا يمريم لقد جئت شيا فريا', NULL, 307, 'local:hafs-text.json'),
  ('hafs-19-28', 'hafs', 19, 28, 'يَٰٓأُخْتَ هَٰرُونَ مَا كَانَ أَبُوكِ ٱمْرَأَ سَوْءٍۢ وَمَا كَانَتْ أُمُّكِ بَغِيًّۭا', 'يأخت هرون ما كان أبوك امرأ سوء وما كانت أمك بغيا', NULL, 307, 'local:hafs-text.json'),
  ('hafs-19-29', 'hafs', 19, 29, 'فَأَشَارَتْ إِلَيْهِ ۖ قَالُوا۟ كَيْفَ نُكَلِّمُ مَن كَانَ فِى ٱلْمَهْدِ صَبِيًّۭا', 'فأشارت إليه  قالوا كيف نكلم من كان فى المهد صبيا', NULL, 307, 'local:hafs-text.json'),
  ('hafs-19-30', 'hafs', 19, 30, 'قَالَ إِنِّى عَبْدُ ٱللَّهِ ءَاتَىٰنِىَ ٱلْكِتَٰبَ وَجَعَلَنِى نَبِيًّۭا', 'قال إنى عبد الله ءاتىنى الكتب وجعلنى نبيا', NULL, 307, 'local:hafs-text.json'),
  ('hafs-19-31', 'hafs', 19, 31, 'وَجَعَلَنِى مُبَارَكًا أَيْنَ مَا كُنتُ وَأَوْصَٰنِى بِٱلصَّلَوٰةِ وَٱلزَّكَوٰةِ مَا دُمْتُ حَيًّۭا', 'وجعلنى مباركا أين ما كنت وأوصنى بالصلوة والزكوة ما دمت حيا', NULL, 307, 'local:hafs-text.json'),
  ('hafs-19-32', 'hafs', 19, 32, 'وَبَرًّۢا بِوَٰلِدَتِى وَلَمْ يَجْعَلْنِى جَبَّارًۭا شَقِيًّۭا', 'وبرا بولدتى ولم يجعلنى جبارا شقيا', NULL, 307, 'local:hafs-text.json'),
  ('hafs-19-33', 'hafs', 19, 33, 'وَٱلسَّلَٰمُ عَلَىَّ يَوْمَ وُلِدتُّ وَيَوْمَ أَمُوتُ وَيَوْمَ أُبْعَثُ حَيًّۭا', 'والسلم على يوم ولدت ويوم أموت ويوم أبعث حيا', NULL, 307, 'local:hafs-text.json'),
  ('hafs-19-34', 'hafs', 19, 34, 'ذَٰلِكَ عِيسَى ٱبْنُ مَرْيَمَ ۚ قَوْلَ ٱلْحَقِّ ٱلَّذِى فِيهِ يَمْتَرُونَ', 'ذلك عيسى ابن مريم  قول الحق الذى فيه يمترون', NULL, 307, 'local:hafs-text.json'),
  ('hafs-19-35', 'hafs', 19, 35, 'مَا كَانَ لِلَّهِ أَن يَتَّخِذَ مِن وَلَدٍۢ ۖ سُبْحَٰنَهُۥٓ ۚ إِذَا قَضَىٰٓ أَمْرًۭا فَإِنَّمَا يَقُولُ لَهُۥ كُن فَيَكُونُ', 'ما كان لله أن يتخذ من ولد  سبحنه  إذا قضى أمرا فإنما يقول له كن فيكون', NULL, 307, 'local:hafs-text.json'),
  ('hafs-19-36', 'hafs', 19, 36, 'وَإِنَّ ٱللَّهَ رَبِّى وَرَبُّكُمْ فَٱعْبُدُوهُ ۚ هَٰذَا صِرَٰطٌۭ مُّسْتَقِيمٌۭ', 'وإن الله ربى وربكم فاعبدوه  هذا صرط مستقيم', NULL, 307, 'local:hafs-text.json'),
  ('hafs-19-37', 'hafs', 19, 37, 'فَٱخْتَلَفَ ٱلْأَحْزَابُ مِنۢ بَيْنِهِمْ ۖ فَوَيْلٌۭ لِّلَّذِينَ كَفَرُوا۟ مِن مَّشْهَدِ يَوْمٍ عَظِيمٍ', 'فاختلف الأحزاب من بينهم  فويل للذين كفروا من مشهد يوم عظيم', NULL, 307, 'local:hafs-text.json'),
  ('hafs-19-38', 'hafs', 19, 38, 'أَسْمِعْ بِهِمْ وَأَبْصِرْ يَوْمَ يَأْتُونَنَا ۖ لَٰكِنِ ٱلظَّٰلِمُونَ ٱلْيَوْمَ فِى ضَلَٰلٍۢ مُّبِينٍۢ', 'أسمع بهم وأبصر يوم يأتوننا  لكن الظلمون اليوم فى ضلل مبين', NULL, 307, 'local:hafs-text.json'),
  ('hafs-19-39', 'hafs', 19, 39, 'وَأَنذِرْهُمْ يَوْمَ ٱلْحَسْرَةِ إِذْ قُضِىَ ٱلْأَمْرُ وَهُمْ فِى غَفْلَةٍۢ وَهُمْ لَا يُؤْمِنُونَ', 'وأنذرهم يوم الحسرة إذ قضى الأمر وهم فى غفلة وهم لا يؤمنون', NULL, 308, 'local:hafs-text.json'),
  ('hafs-19-40', 'hafs', 19, 40, 'إِنَّا نَحْنُ نَرِثُ ٱلْأَرْضَ وَمَنْ عَلَيْهَا وَإِلَيْنَا يُرْجَعُونَ', 'إنا نحن نرث الأرض ومن عليها وإلينا يرجعون', NULL, 308, 'local:hafs-text.json'),
  ('hafs-19-41', 'hafs', 19, 41, 'وَٱذْكُرْ فِى ٱلْكِتَٰبِ إِبْرَٰهِيمَ ۚ إِنَّهُۥ كَانَ صِدِّيقًۭا نَّبِيًّا', 'واذكر فى الكتب إبرهيم  إنه كان صديقا نبيا', NULL, 308, 'local:hafs-text.json'),
  ('hafs-19-42', 'hafs', 19, 42, 'إِذْ قَالَ لِأَبِيهِ يَٰٓأَبَتِ لِمَ تَعْبُدُ مَا لَا يَسْمَعُ وَلَا يُبْصِرُ وَلَا يُغْنِى عَنكَ شَيْـًۭٔا', 'إذ قال لأبيه يأبت لم تعبد ما لا يسمع ولا يبصر ولا يغنى عنك شيا', NULL, 308, 'local:hafs-text.json'),
  ('hafs-19-43', 'hafs', 19, 43, 'يَٰٓأَبَتِ إِنِّى قَدْ جَآءَنِى مِنَ ٱلْعِلْمِ مَا لَمْ يَأْتِكَ فَٱتَّبِعْنِىٓ أَهْدِكَ صِرَٰطًۭا سَوِيًّۭا', 'يأبت إنى قد جاءنى من العلم ما لم يأتك فاتبعنى أهدك صرطا سويا', NULL, 308, 'local:hafs-text.json'),
  ('hafs-19-44', 'hafs', 19, 44, 'يَٰٓأَبَتِ لَا تَعْبُدِ ٱلشَّيْطَٰنَ ۖ إِنَّ ٱلشَّيْطَٰنَ كَانَ لِلرَّحْمَٰنِ عَصِيًّۭا', 'يأبت لا تعبد الشيطن  إن الشيطن كان للرحمن عصيا', NULL, 308, 'local:hafs-text.json'),
  ('hafs-19-45', 'hafs', 19, 45, 'يَٰٓأَبَتِ إِنِّىٓ أَخَافُ أَن يَمَسَّكَ عَذَابٌۭ مِّنَ ٱلرَّحْمَٰنِ فَتَكُونَ لِلشَّيْطَٰنِ وَلِيًّۭا', 'يأبت إنى أخاف أن يمسك عذاب من الرحمن فتكون للشيطن وليا', NULL, 308, 'local:hafs-text.json'),
  ('hafs-19-46', 'hafs', 19, 46, 'قَالَ أَرَاغِبٌ أَنتَ عَنْ ءَالِهَتِى يَٰٓإِبْرَٰهِيمُ ۖ لَئِن لَّمْ تَنتَهِ لَأَرْجُمَنَّكَ ۖ وَٱهْجُرْنِى مَلِيًّۭا', 'قال أراغب أنت عن ءالهتى يإبرهيم  لئن لم تنته لأرجمنك  واهجرنى مليا', NULL, 308, 'local:hafs-text.json'),
  ('hafs-19-47', 'hafs', 19, 47, 'قَالَ سَلَٰمٌ عَلَيْكَ ۖ سَأَسْتَغْفِرُ لَكَ رَبِّىٓ ۖ إِنَّهُۥ كَانَ بِى حَفِيًّۭا', 'قال سلم عليك  سأستغفر لك ربى  إنه كان بى حفيا', NULL, 308, 'local:hafs-text.json'),
  ('hafs-19-48', 'hafs', 19, 48, 'وَأَعْتَزِلُكُمْ وَمَا تَدْعُونَ مِن دُونِ ٱللَّهِ وَأَدْعُوا۟ رَبِّى عَسَىٰٓ أَلَّآ أَكُونَ بِدُعَآءِ رَبِّى شَقِيًّۭا', 'وأعتزلكم وما تدعون من دون الله وأدعوا ربى عسى ألا أكون بدعاء ربى شقيا', NULL, 308, 'local:hafs-text.json'),
  ('hafs-19-49', 'hafs', 19, 49, 'فَلَمَّا ٱعْتَزَلَهُمْ وَمَا يَعْبُدُونَ مِن دُونِ ٱللَّهِ وَهَبْنَا لَهُۥٓ إِسْحَٰقَ وَيَعْقُوبَ ۖ وَكُلًّۭا جَعَلْنَا نَبِيًّۭا', 'فلما اعتزلهم وما يعبدون من دون الله وهبنا له إسحق ويعقوب  وكلا جعلنا نبيا', NULL, 308, 'local:hafs-text.json'),
  ('hafs-19-50', 'hafs', 19, 50, 'وَوَهَبْنَا لَهُم مِّن رَّحْمَتِنَا وَجَعَلْنَا لَهُمْ لِسَانَ صِدْقٍ عَلِيًّۭا', 'ووهبنا لهم من رحمتنا وجعلنا لهم لسان صدق عليا', NULL, 308, 'local:hafs-text.json'),
  ('hafs-19-51', 'hafs', 19, 51, 'وَٱذْكُرْ فِى ٱلْكِتَٰبِ مُوسَىٰٓ ۚ إِنَّهُۥ كَانَ مُخْلَصًۭا وَكَانَ رَسُولًۭا نَّبِيًّۭا', 'واذكر فى الكتب موسى  إنه كان مخلصا وكان رسولا نبيا', NULL, 308, 'local:hafs-text.json'),
  ('hafs-19-52', 'hafs', 19, 52, 'وَنَٰدَيْنَٰهُ مِن جَانِبِ ٱلطُّورِ ٱلْأَيْمَنِ وَقَرَّبْنَٰهُ نَجِيًّۭا', 'وندينه من جانب الطور الأيمن وقربنه نجيا', NULL, 309, 'local:hafs-text.json'),
  ('hafs-19-53', 'hafs', 19, 53, 'وَوَهَبْنَا لَهُۥ مِن رَّحْمَتِنَآ أَخَاهُ هَٰرُونَ نَبِيًّۭا', 'ووهبنا له من رحمتنا أخاه هرون نبيا', NULL, 309, 'local:hafs-text.json'),
  ('hafs-19-54', 'hafs', 19, 54, 'وَٱذْكُرْ فِى ٱلْكِتَٰبِ إِسْمَٰعِيلَ ۚ إِنَّهُۥ كَانَ صَادِقَ ٱلْوَعْدِ وَكَانَ رَسُولًۭا نَّبِيًّۭا', 'واذكر فى الكتب إسمعيل  إنه كان صادق الوعد وكان رسولا نبيا', NULL, 309, 'local:hafs-text.json'),
  ('hafs-19-55', 'hafs', 19, 55, 'وَكَانَ يَأْمُرُ أَهْلَهُۥ بِٱلصَّلَوٰةِ وَٱلزَّكَوٰةِ وَكَانَ عِندَ رَبِّهِۦ مَرْضِيًّۭا', 'وكان يأمر أهله بالصلوة والزكوة وكان عند ربه مرضيا', NULL, 309, 'local:hafs-text.json'),
  ('hafs-19-56', 'hafs', 19, 56, 'وَٱذْكُرْ فِى ٱلْكِتَٰبِ إِدْرِيسَ ۚ إِنَّهُۥ كَانَ صِدِّيقًۭا نَّبِيًّۭا', 'واذكر فى الكتب إدريس  إنه كان صديقا نبيا', NULL, 309, 'local:hafs-text.json'),
  ('hafs-19-57', 'hafs', 19, 57, 'وَرَفَعْنَٰهُ مَكَانًا عَلِيًّا', 'ورفعنه مكانا عليا', NULL, 309, 'local:hafs-text.json'),
  ('hafs-19-58', 'hafs', 19, 58, 'أُو۟لَٰٓئِكَ ٱلَّذِينَ أَنْعَمَ ٱللَّهُ عَلَيْهِم مِّنَ ٱلنَّبِيِّۦنَ مِن ذُرِّيَّةِ ءَادَمَ وَمِمَّنْ حَمَلْنَا مَعَ نُوحٍۢ وَمِن ذُرِّيَّةِ إِبْرَٰهِيمَ وَإِسْرَٰٓءِيلَ وَمِمَّنْ هَدَيْنَا وَٱجْتَبَيْنَآ ۚ إِذَا تُتْلَىٰ عَلَيْهِمْ ءَايَٰتُ ٱلرَّحْمَٰنِ خَرُّوا۟ سُجَّدًۭا وَبُكِيًّۭا ۩', 'أولئك الذين أنعم الله عليهم من النبين من ذرية ءادم وممن حملنا مع نوح ومن ذرية إبرهيم وإسرءيل وممن هدينا واجتبينا  إذا تتلى عليهم ءايت الرحمن خروا سجدا وبكيا', NULL, 309, 'local:hafs-text.json'),
  ('hafs-19-59', 'hafs', 19, 59, '۞ فَخَلَفَ مِنۢ بَعْدِهِمْ خَلْفٌ أَضَاعُوا۟ ٱلصَّلَوٰةَ وَٱتَّبَعُوا۟ ٱلشَّهَوَٰتِ ۖ فَسَوْفَ يَلْقَوْنَ غَيًّا', 'فخلف من بعدهم خلف أضاعوا الصلوة واتبعوا الشهوت  فسوف يلقون غيا', NULL, 309, 'local:hafs-text.json'),
  ('hafs-19-60', 'hafs', 19, 60, 'إِلَّا مَن تَابَ وَءَامَنَ وَعَمِلَ صَٰلِحًۭا فَأُو۟لَٰٓئِكَ يَدْخُلُونَ ٱلْجَنَّةَ وَلَا يُظْلَمُونَ شَيْـًۭٔا', 'إلا من تاب وءامن وعمل صلحا فأولئك يدخلون الجنة ولا يظلمون شيا', NULL, 309, 'local:hafs-text.json'),
  ('hafs-19-61', 'hafs', 19, 61, 'جَنَّٰتِ عَدْنٍ ٱلَّتِى وَعَدَ ٱلرَّحْمَٰنُ عِبَادَهُۥ بِٱلْغَيْبِ ۚ إِنَّهُۥ كَانَ وَعْدُهُۥ مَأْتِيًّۭا', 'جنت عدن التى وعد الرحمن عباده بالغيب  إنه كان وعده مأتيا', NULL, 309, 'local:hafs-text.json'),
  ('hafs-19-62', 'hafs', 19, 62, 'لَّا يَسْمَعُونَ فِيهَا لَغْوًا إِلَّا سَلَٰمًۭا ۖ وَلَهُمْ رِزْقُهُمْ فِيهَا بُكْرَةًۭ وَعَشِيًّۭا', 'لا يسمعون فيها لغوا إلا سلما  ولهم رزقهم فيها بكرة وعشيا', NULL, 309, 'local:hafs-text.json'),
  ('hafs-19-63', 'hafs', 19, 63, 'تِلْكَ ٱلْجَنَّةُ ٱلَّتِى نُورِثُ مِنْ عِبَادِنَا مَن كَانَ تَقِيًّۭا', 'تلك الجنة التى نورث من عبادنا من كان تقيا', NULL, 309, 'local:hafs-text.json'),
  ('hafs-19-64', 'hafs', 19, 64, 'وَمَا نَتَنَزَّلُ إِلَّا بِأَمْرِ رَبِّكَ ۖ لَهُۥ مَا بَيْنَ أَيْدِينَا وَمَا خَلْفَنَا وَمَا بَيْنَ ذَٰلِكَ ۚ وَمَا كَانَ رَبُّكَ نَسِيًّۭا', 'وما نتنزل إلا بأمر ربك  له ما بين أيدينا وما خلفنا وما بين ذلك  وما كان ربك نسيا', NULL, 309, 'local:hafs-text.json'),
  ('hafs-19-65', 'hafs', 19, 65, 'رَّبُّ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَمَا بَيْنَهُمَا فَٱعْبُدْهُ وَٱصْطَبِرْ لِعِبَٰدَتِهِۦ ۚ هَلْ تَعْلَمُ لَهُۥ سَمِيًّۭا', 'رب السموت والأرض وما بينهما فاعبده واصطبر لعبدته  هل تعلم له سميا', NULL, 310, 'local:hafs-text.json'),
  ('hafs-19-66', 'hafs', 19, 66, 'وَيَقُولُ ٱلْإِنسَٰنُ أَءِذَا مَا مِتُّ لَسَوْفَ أُخْرَجُ حَيًّا', 'ويقول الإنسن أءذا ما مت لسوف أخرج حيا', NULL, 310, 'local:hafs-text.json'),
  ('hafs-19-67', 'hafs', 19, 67, 'أَوَلَا يَذْكُرُ ٱلْإِنسَٰنُ أَنَّا خَلَقْنَٰهُ مِن قَبْلُ وَلَمْ يَكُ شَيْـًۭٔا', 'أولا يذكر الإنسن أنا خلقنه من قبل ولم يك شيا', NULL, 310, 'local:hafs-text.json'),
  ('hafs-19-68', 'hafs', 19, 68, 'فَوَرَبِّكَ لَنَحْشُرَنَّهُمْ وَٱلشَّيَٰطِينَ ثُمَّ لَنُحْضِرَنَّهُمْ حَوْلَ جَهَنَّمَ جِثِيًّۭا', 'فوربك لنحشرنهم والشيطين ثم لنحضرنهم حول جهنم جثيا', NULL, 310, 'local:hafs-text.json'),
  ('hafs-19-69', 'hafs', 19, 69, 'ثُمَّ لَنَنزِعَنَّ مِن كُلِّ شِيعَةٍ أَيُّهُمْ أَشَدُّ عَلَى ٱلرَّحْمَٰنِ عِتِيًّۭا', 'ثم لننزعن من كل شيعة أيهم أشد على الرحمن عتيا', NULL, 310, 'local:hafs-text.json'),
  ('hafs-19-70', 'hafs', 19, 70, 'ثُمَّ لَنَحْنُ أَعْلَمُ بِٱلَّذِينَ هُمْ أَوْلَىٰ بِهَا صِلِيًّۭا', 'ثم لنحن أعلم بالذين هم أولى بها صليا', NULL, 310, 'local:hafs-text.json'),
  ('hafs-19-71', 'hafs', 19, 71, 'وَإِن مِّنكُمْ إِلَّا وَارِدُهَا ۚ كَانَ عَلَىٰ رَبِّكَ حَتْمًۭا مَّقْضِيًّۭا', 'وإن منكم إلا واردها  كان على ربك حتما مقضيا', NULL, 310, 'local:hafs-text.json'),
  ('hafs-19-72', 'hafs', 19, 72, 'ثُمَّ نُنَجِّى ٱلَّذِينَ ٱتَّقَوا۟ وَّنَذَرُ ٱلظَّٰلِمِينَ فِيهَا جِثِيًّۭا', 'ثم ننجى الذين اتقوا ونذر الظلمين فيها جثيا', NULL, 310, 'local:hafs-text.json'),
  ('hafs-19-73', 'hafs', 19, 73, 'وَإِذَا تُتْلَىٰ عَلَيْهِمْ ءَايَٰتُنَا بَيِّنَٰتٍۢ قَالَ ٱلَّذِينَ كَفَرُوا۟ لِلَّذِينَ ءَامَنُوٓا۟ أَىُّ ٱلْفَرِيقَيْنِ خَيْرٌۭ مَّقَامًۭا وَأَحْسَنُ نَدِيًّۭا', 'وإذا تتلى عليهم ءايتنا بينت قال الذين كفروا للذين ءامنوا أى الفريقين خير مقاما وأحسن نديا', NULL, 310, 'local:hafs-text.json'),
  ('hafs-19-74', 'hafs', 19, 74, 'وَكَمْ أَهْلَكْنَا قَبْلَهُم مِّن قَرْنٍ هُمْ أَحْسَنُ أَثَٰثًۭا وَرِءْيًۭا', 'وكم أهلكنا قبلهم من قرن هم أحسن أثثا ورءيا', NULL, 310, 'local:hafs-text.json'),
  ('hafs-19-75', 'hafs', 19, 75, 'قُلْ مَن كَانَ فِى ٱلضَّلَٰلَةِ فَلْيَمْدُدْ لَهُ ٱلرَّحْمَٰنُ مَدًّا ۚ حَتَّىٰٓ إِذَا رَأَوْا۟ مَا يُوعَدُونَ إِمَّا ٱلْعَذَابَ وَإِمَّا ٱلسَّاعَةَ فَسَيَعْلَمُونَ مَنْ هُوَ شَرٌّۭ مَّكَانًۭا وَأَضْعَفُ جُندًۭا', 'قل من كان فى الضللة فليمدد له الرحمن مدا  حتى إذا رأوا ما يوعدون إما العذاب وإما الساعة فسيعلمون من هو شر مكانا وأضعف جندا', NULL, 310, 'local:hafs-text.json'),
  ('hafs-19-76', 'hafs', 19, 76, 'وَيَزِيدُ ٱللَّهُ ٱلَّذِينَ ٱهْتَدَوْا۟ هُدًۭى ۗ وَٱلْبَٰقِيَٰتُ ٱلصَّٰلِحَٰتُ خَيْرٌ عِندَ رَبِّكَ ثَوَابًۭا وَخَيْرٌۭ مَّرَدًّا', 'ويزيد الله الذين اهتدوا هدى  والبقيت الصلحت خير عند ربك ثوابا وخير مردا', NULL, 310, 'local:hafs-text.json'),
  ('hafs-19-77', 'hafs', 19, 77, 'أَفَرَءَيْتَ ٱلَّذِى كَفَرَ بِـَٔايَٰتِنَا وَقَالَ لَأُوتَيَنَّ مَالًۭا وَوَلَدًا', 'أفرءيت الذى كفر بايتنا وقال لأوتين مالا وولدا', NULL, 311, 'local:hafs-text.json'),
  ('hafs-19-78', 'hafs', 19, 78, 'أَطَّلَعَ ٱلْغَيْبَ أَمِ ٱتَّخَذَ عِندَ ٱلرَّحْمَٰنِ عَهْدًۭا', 'أطلع الغيب أم اتخذ عند الرحمن عهدا', NULL, 311, 'local:hafs-text.json'),
  ('hafs-19-79', 'hafs', 19, 79, 'كَلَّا ۚ سَنَكْتُبُ مَا يَقُولُ وَنَمُدُّ لَهُۥ مِنَ ٱلْعَذَابِ مَدًّۭا', 'كلا  سنكتب ما يقول ونمد له من العذاب مدا', NULL, 311, 'local:hafs-text.json'),
  ('hafs-19-80', 'hafs', 19, 80, 'وَنَرِثُهُۥ مَا يَقُولُ وَيَأْتِينَا فَرْدًۭا', 'ونرثه ما يقول ويأتينا فردا', NULL, 311, 'local:hafs-text.json'),
  ('hafs-19-81', 'hafs', 19, 81, 'وَٱتَّخَذُوا۟ مِن دُونِ ٱللَّهِ ءَالِهَةًۭ لِّيَكُونُوا۟ لَهُمْ عِزًّۭا', 'واتخذوا من دون الله ءالهة ليكونوا لهم عزا', NULL, 311, 'local:hafs-text.json'),
  ('hafs-19-82', 'hafs', 19, 82, 'كَلَّا ۚ سَيَكْفُرُونَ بِعِبَادَتِهِمْ وَيَكُونُونَ عَلَيْهِمْ ضِدًّا', 'كلا  سيكفرون بعبادتهم ويكونون عليهم ضدا', NULL, 311, 'local:hafs-text.json'),
  ('hafs-19-83', 'hafs', 19, 83, 'أَلَمْ تَرَ أَنَّآ أَرْسَلْنَا ٱلشَّيَٰطِينَ عَلَى ٱلْكَٰفِرِينَ تَؤُزُّهُمْ أَزًّۭا', 'ألم تر أنا أرسلنا الشيطين على الكفرين تؤزهم أزا', NULL, 311, 'local:hafs-text.json'),
  ('hafs-19-84', 'hafs', 19, 84, 'فَلَا تَعْجَلْ عَلَيْهِمْ ۖ إِنَّمَا نَعُدُّ لَهُمْ عَدًّۭا', 'فلا تعجل عليهم  إنما نعد لهم عدا', NULL, 311, 'local:hafs-text.json'),
  ('hafs-19-85', 'hafs', 19, 85, 'يَوْمَ نَحْشُرُ ٱلْمُتَّقِينَ إِلَى ٱلرَّحْمَٰنِ وَفْدًۭا', 'يوم نحشر المتقين إلى الرحمن وفدا', NULL, 311, 'local:hafs-text.json'),
  ('hafs-19-86', 'hafs', 19, 86, 'وَنَسُوقُ ٱلْمُجْرِمِينَ إِلَىٰ جَهَنَّمَ وِرْدًۭا', 'ونسوق المجرمين إلى جهنم وردا', NULL, 311, 'local:hafs-text.json'),
  ('hafs-19-87', 'hafs', 19, 87, 'لَّا يَمْلِكُونَ ٱلشَّفَٰعَةَ إِلَّا مَنِ ٱتَّخَذَ عِندَ ٱلرَّحْمَٰنِ عَهْدًۭا', 'لا يملكون الشفعة إلا من اتخذ عند الرحمن عهدا', NULL, 311, 'local:hafs-text.json'),
  ('hafs-19-88', 'hafs', 19, 88, 'وَقَالُوا۟ ٱتَّخَذَ ٱلرَّحْمَٰنُ وَلَدًۭا', 'وقالوا اتخذ الرحمن ولدا', NULL, 311, 'local:hafs-text.json'),
  ('hafs-19-89', 'hafs', 19, 89, 'لَّقَدْ جِئْتُمْ شَيْـًٔا إِدًّۭا', 'لقد جئتم شيا إدا', NULL, 311, 'local:hafs-text.json'),
  ('hafs-19-90', 'hafs', 19, 90, 'تَكَادُ ٱلسَّمَٰوَٰتُ يَتَفَطَّرْنَ مِنْهُ وَتَنشَقُّ ٱلْأَرْضُ وَتَخِرُّ ٱلْجِبَالُ هَدًّا', 'تكاد السموت يتفطرن منه وتنشق الأرض وتخر الجبال هدا', NULL, 311, 'local:hafs-text.json'),
  ('hafs-19-91', 'hafs', 19, 91, 'أَن دَعَوْا۟ لِلرَّحْمَٰنِ وَلَدًۭا', 'أن دعوا للرحمن ولدا', NULL, 311, 'local:hafs-text.json'),
  ('hafs-19-92', 'hafs', 19, 92, 'وَمَا يَنۢبَغِى لِلرَّحْمَٰنِ أَن يَتَّخِذَ وَلَدًا', 'وما ينبغى للرحمن أن يتخذ ولدا', NULL, 311, 'local:hafs-text.json'),
  ('hafs-19-93', 'hafs', 19, 93, 'إِن كُلُّ مَن فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ إِلَّآ ءَاتِى ٱلرَّحْمَٰنِ عَبْدًۭا', 'إن كل من فى السموت والأرض إلا ءاتى الرحمن عبدا', NULL, 311, 'local:hafs-text.json'),
  ('hafs-19-94', 'hafs', 19, 94, 'لَّقَدْ أَحْصَىٰهُمْ وَعَدَّهُمْ عَدًّۭا', 'لقد أحصىهم وعدهم عدا', NULL, 311, 'local:hafs-text.json'),
  ('hafs-19-95', 'hafs', 19, 95, 'وَكُلُّهُمْ ءَاتِيهِ يَوْمَ ٱلْقِيَٰمَةِ فَرْدًا', 'وكلهم ءاتيه يوم القيمة فردا', NULL, 311, 'local:hafs-text.json'),
  ('hafs-19-96', 'hafs', 19, 96, 'إِنَّ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ سَيَجْعَلُ لَهُمُ ٱلرَّحْمَٰنُ وُدًّۭا', 'إن الذين ءامنوا وعملوا الصلحت سيجعل لهم الرحمن ودا', NULL, 312, 'local:hafs-text.json'),
  ('hafs-19-97', 'hafs', 19, 97, 'فَإِنَّمَا يَسَّرْنَٰهُ بِلِسَانِكَ لِتُبَشِّرَ بِهِ ٱلْمُتَّقِينَ وَتُنذِرَ بِهِۦ قَوْمًۭا لُّدًّۭا', 'فإنما يسرنه بلسانك لتبشر به المتقين وتنذر به قوما لدا', NULL, 312, 'local:hafs-text.json'),
  ('hafs-19-98', 'hafs', 19, 98, 'وَكَمْ أَهْلَكْنَا قَبْلَهُم مِّن قَرْنٍ هَلْ تُحِسُّ مِنْهُم مِّنْ أَحَدٍ أَوْ تَسْمَعُ لَهُمْ رِكْزًۢا', 'وكم أهلكنا قبلهم من قرن هل تحس منهم من أحد أو تسمع لهم ركزا', NULL, 312, 'local:hafs-text.json'),
  ('hafs-20-1', 'hafs', 20, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ طه', 'بسم الله الرحمن الرحيم طه', NULL, 312, 'local:hafs-text.json'),
  ('hafs-20-2', 'hafs', 20, 2, 'مَآ أَنزَلْنَا عَلَيْكَ ٱلْقُرْءَانَ لِتَشْقَىٰٓ', 'ما أنزلنا عليك القرءان لتشقى', NULL, 312, 'local:hafs-text.json'),
  ('hafs-20-3', 'hafs', 20, 3, 'إِلَّا تَذْكِرَةًۭ لِّمَن يَخْشَىٰ', 'إلا تذكرة لمن يخشى', NULL, 312, 'local:hafs-text.json'),
  ('hafs-20-4', 'hafs', 20, 4, 'تَنزِيلًۭا مِّمَّنْ خَلَقَ ٱلْأَرْضَ وَٱلسَّمَٰوَٰتِ ٱلْعُلَى', 'تنزيلا ممن خلق الأرض والسموت العلى', NULL, 312, 'local:hafs-text.json'),
  ('hafs-20-5', 'hafs', 20, 5, 'ٱلرَّحْمَٰنُ عَلَى ٱلْعَرْشِ ٱسْتَوَىٰ', 'الرحمن على العرش استوى', NULL, 312, 'local:hafs-text.json'),
  ('hafs-20-6', 'hafs', 20, 6, 'لَهُۥ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ وَمَا بَيْنَهُمَا وَمَا تَحْتَ ٱلثَّرَىٰ', 'له ما فى السموت وما فى الأرض وما بينهما وما تحت الثرى', NULL, 312, 'local:hafs-text.json'),
  ('hafs-20-7', 'hafs', 20, 7, 'وَإِن تَجْهَرْ بِٱلْقَوْلِ فَإِنَّهُۥ يَعْلَمُ ٱلسِّرَّ وَأَخْفَى', 'وإن تجهر بالقول فإنه يعلم السر وأخفى', NULL, 312, 'local:hafs-text.json'),
  ('hafs-20-8', 'hafs', 20, 8, 'ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَ ۖ لَهُ ٱلْأَسْمَآءُ ٱلْحُسْنَىٰ', 'الله لا إله إلا هو  له الأسماء الحسنى', NULL, 312, 'local:hafs-text.json'),
  ('hafs-20-9', 'hafs', 20, 9, 'وَهَلْ أَتَىٰكَ حَدِيثُ مُوسَىٰٓ', 'وهل أتىك حديث موسى', NULL, 312, 'local:hafs-text.json'),
  ('hafs-20-10', 'hafs', 20, 10, 'إِذْ رَءَا نَارًۭا فَقَالَ لِأَهْلِهِ ٱمْكُثُوٓا۟ إِنِّىٓ ءَانَسْتُ نَارًۭا لَّعَلِّىٓ ءَاتِيكُم مِّنْهَا بِقَبَسٍ أَوْ أَجِدُ عَلَى ٱلنَّارِ هُدًۭى', 'إذ رءا نارا فقال لأهله امكثوا إنى ءانست نارا لعلى ءاتيكم منها بقبس أو أجد على النار هدى', NULL, 312, 'local:hafs-text.json'),
  ('hafs-20-11', 'hafs', 20, 11, 'فَلَمَّآ أَتَىٰهَا نُودِىَ يَٰمُوسَىٰٓ', 'فلما أتىها نودى يموسى', NULL, 312, 'local:hafs-text.json'),
  ('hafs-20-12', 'hafs', 20, 12, 'إِنِّىٓ أَنَا۠ رَبُّكَ فَٱخْلَعْ نَعْلَيْكَ ۖ إِنَّكَ بِٱلْوَادِ ٱلْمُقَدَّسِ طُوًۭى', 'إنى أنا ربك فاخلع نعليك  إنك بالواد المقدس طوى', NULL, 312, 'local:hafs-text.json'),
  ('hafs-20-13', 'hafs', 20, 13, 'وَأَنَا ٱخْتَرْتُكَ فَٱسْتَمِعْ لِمَا يُوحَىٰٓ', 'وأنا اخترتك فاستمع لما يوحى', NULL, 313, 'local:hafs-text.json'),
  ('hafs-20-14', 'hafs', 20, 14, 'إِنَّنِىٓ أَنَا ٱللَّهُ لَآ إِلَٰهَ إِلَّآ أَنَا۠ فَٱعْبُدْنِى وَأَقِمِ ٱلصَّلَوٰةَ لِذِكْرِىٓ', 'إننى أنا الله لا إله إلا أنا فاعبدنى وأقم الصلوة لذكرى', NULL, 313, 'local:hafs-text.json'),
  ('hafs-20-15', 'hafs', 20, 15, 'إِنَّ ٱلسَّاعَةَ ءَاتِيَةٌ أَكَادُ أُخْفِيهَا لِتُجْزَىٰ كُلُّ نَفْسٍۭ بِمَا تَسْعَىٰ', 'إن الساعة ءاتية أكاد أخفيها لتجزى كل نفس بما تسعى', NULL, 313, 'local:hafs-text.json'),
  ('hafs-20-16', 'hafs', 20, 16, 'فَلَا يَصُدَّنَّكَ عَنْهَا مَن لَّا يُؤْمِنُ بِهَا وَٱتَّبَعَ هَوَىٰهُ فَتَرْدَىٰ', 'فلا يصدنك عنها من لا يؤمن بها واتبع هوىه فتردى', NULL, 313, 'local:hafs-text.json'),
  ('hafs-20-17', 'hafs', 20, 17, 'وَمَا تِلْكَ بِيَمِينِكَ يَٰمُوسَىٰ', 'وما تلك بيمينك يموسى', NULL, 313, 'local:hafs-text.json'),
  ('hafs-20-18', 'hafs', 20, 18, 'قَالَ هِىَ عَصَاىَ أَتَوَكَّؤُا۟ عَلَيْهَا وَأَهُشُّ بِهَا عَلَىٰ غَنَمِى وَلِىَ فِيهَا مَـَٔارِبُ أُخْرَىٰ', 'قال هى عصاى أتوكؤا عليها وأهش بها على غنمى ولى فيها مارب أخرى', NULL, 313, 'local:hafs-text.json'),
  ('hafs-20-19', 'hafs', 20, 19, 'قَالَ أَلْقِهَا يَٰمُوسَىٰ', 'قال ألقها يموسى', NULL, 313, 'local:hafs-text.json'),
  ('hafs-20-20', 'hafs', 20, 20, 'فَأَلْقَىٰهَا فَإِذَا هِىَ حَيَّةٌۭ تَسْعَىٰ', 'فألقىها فإذا هى حية تسعى', NULL, 313, 'local:hafs-text.json'),
  ('hafs-20-21', 'hafs', 20, 21, 'قَالَ خُذْهَا وَلَا تَخَفْ ۖ سَنُعِيدُهَا سِيرَتَهَا ٱلْأُولَىٰ', 'قال خذها ولا تخف  سنعيدها سيرتها الأولى', NULL, 313, 'local:hafs-text.json'),
  ('hafs-20-22', 'hafs', 20, 22, 'وَٱضْمُمْ يَدَكَ إِلَىٰ جَنَاحِكَ تَخْرُجْ بَيْضَآءَ مِنْ غَيْرِ سُوٓءٍ ءَايَةً أُخْرَىٰ', 'واضمم يدك إلى جناحك تخرج بيضاء من غير سوء ءاية أخرى', NULL, 313, 'local:hafs-text.json'),
  ('hafs-20-23', 'hafs', 20, 23, 'لِنُرِيَكَ مِنْ ءَايَٰتِنَا ٱلْكُبْرَى', 'لنريك من ءايتنا الكبرى', NULL, 313, 'local:hafs-text.json'),
  ('hafs-20-24', 'hafs', 20, 24, 'ٱذْهَبْ إِلَىٰ فِرْعَوْنَ إِنَّهُۥ طَغَىٰ', 'اذهب إلى فرعون إنه طغى', NULL, 313, 'local:hafs-text.json'),
  ('hafs-20-25', 'hafs', 20, 25, 'قَالَ رَبِّ ٱشْرَحْ لِى صَدْرِى', 'قال رب اشرح لى صدرى', NULL, 313, 'local:hafs-text.json'),
  ('hafs-20-26', 'hafs', 20, 26, 'وَيَسِّرْ لِىٓ أَمْرِى', 'ويسر لى أمرى', NULL, 313, 'local:hafs-text.json'),
  ('hafs-20-27', 'hafs', 20, 27, 'وَٱحْلُلْ عُقْدَةًۭ مِّن لِّسَانِى', 'واحلل عقدة من لسانى', NULL, 313, 'local:hafs-text.json'),
  ('hafs-20-28', 'hafs', 20, 28, 'يَفْقَهُوا۟ قَوْلِى', 'يفقهوا قولى', NULL, 313, 'local:hafs-text.json'),
  ('hafs-20-29', 'hafs', 20, 29, 'وَٱجْعَل لِّى وَزِيرًۭا مِّنْ أَهْلِى', 'واجعل لى وزيرا من أهلى', NULL, 313, 'local:hafs-text.json'),
  ('hafs-20-30', 'hafs', 20, 30, 'هَٰرُونَ أَخِى', 'هرون أخى', NULL, 313, 'local:hafs-text.json'),
  ('hafs-20-31', 'hafs', 20, 31, 'ٱشْدُدْ بِهِۦٓ أَزْرِى', 'اشدد به أزرى', NULL, 313, 'local:hafs-text.json'),
  ('hafs-20-32', 'hafs', 20, 32, 'وَأَشْرِكْهُ فِىٓ أَمْرِى', 'وأشركه فى أمرى', NULL, 313, 'local:hafs-text.json'),
  ('hafs-20-33', 'hafs', 20, 33, 'كَىْ نُسَبِّحَكَ كَثِيرًۭا', 'كى نسبحك كثيرا', NULL, 313, 'local:hafs-text.json'),
  ('hafs-20-34', 'hafs', 20, 34, 'وَنَذْكُرَكَ كَثِيرًا', 'ونذكرك كثيرا', NULL, 313, 'local:hafs-text.json'),
  ('hafs-20-35', 'hafs', 20, 35, 'إِنَّكَ كُنتَ بِنَا بَصِيرًۭا', 'إنك كنت بنا بصيرا', NULL, 313, 'local:hafs-text.json'),
  ('hafs-20-36', 'hafs', 20, 36, 'قَالَ قَدْ أُوتِيتَ سُؤْلَكَ يَٰمُوسَىٰ', 'قال قد أوتيت سؤلك يموسى', NULL, 313, 'local:hafs-text.json'),
  ('hafs-20-37', 'hafs', 20, 37, 'وَلَقَدْ مَنَنَّا عَلَيْكَ مَرَّةً أُخْرَىٰٓ', 'ولقد مننا عليك مرة أخرى', NULL, 313, 'local:hafs-text.json'),
  ('hafs-20-38', 'hafs', 20, 38, 'إِذْ أَوْحَيْنَآ إِلَىٰٓ أُمِّكَ مَا يُوحَىٰٓ', 'إذ أوحينا إلى أمك ما يوحى', NULL, 314, 'local:hafs-text.json'),
  ('hafs-20-39', 'hafs', 20, 39, 'أَنِ ٱقْذِفِيهِ فِى ٱلتَّابُوتِ فَٱقْذِفِيهِ فِى ٱلْيَمِّ فَلْيُلْقِهِ ٱلْيَمُّ بِٱلسَّاحِلِ يَأْخُذْهُ عَدُوٌّۭ لِّى وَعَدُوٌّۭ لَّهُۥ ۚ وَأَلْقَيْتُ عَلَيْكَ مَحَبَّةًۭ مِّنِّى وَلِتُصْنَعَ عَلَىٰ عَيْنِىٓ', 'أن اقذفيه فى التابوت فاقذفيه فى اليم فليلقه اليم بالساحل يأخذه عدو لى وعدو له  وألقيت عليك محبة منى ولتصنع على عينى', NULL, 314, 'local:hafs-text.json'),
  ('hafs-20-40', 'hafs', 20, 40, 'إِذْ تَمْشِىٓ أُخْتُكَ فَتَقُولُ هَلْ أَدُلُّكُمْ عَلَىٰ مَن يَكْفُلُهُۥ ۖ فَرَجَعْنَٰكَ إِلَىٰٓ أُمِّكَ كَىْ تَقَرَّ عَيْنُهَا وَلَا تَحْزَنَ ۚ وَقَتَلْتَ نَفْسًۭا فَنَجَّيْنَٰكَ مِنَ ٱلْغَمِّ وَفَتَنَّٰكَ فُتُونًۭا ۚ فَلَبِثْتَ سِنِينَ فِىٓ أَهْلِ مَدْيَنَ ثُمَّ جِئْتَ عَلَىٰ قَدَرٍۢ يَٰمُوسَىٰ', 'إذ تمشى أختك فتقول هل أدلكم على من يكفله  فرجعنك إلى أمك كى تقر عينها ولا تحزن  وقتلت نفسا فنجينك من الغم وفتنك فتونا  فلبثت سنين فى أهل مدين ثم جئت على قدر يموسى', NULL, 314, 'local:hafs-text.json'),
  ('hafs-20-41', 'hafs', 20, 41, 'وَٱصْطَنَعْتُكَ لِنَفْسِى', 'واصطنعتك لنفسى', NULL, 314, 'local:hafs-text.json'),
  ('hafs-20-42', 'hafs', 20, 42, 'ٱذْهَبْ أَنتَ وَأَخُوكَ بِـَٔايَٰتِى وَلَا تَنِيَا فِى ذِكْرِى', 'اذهب أنت وأخوك بايتى ولا تنيا فى ذكرى', NULL, 314, 'local:hafs-text.json'),
  ('hafs-20-43', 'hafs', 20, 43, 'ٱذْهَبَآ إِلَىٰ فِرْعَوْنَ إِنَّهُۥ طَغَىٰ', 'اذهبا إلى فرعون إنه طغى', NULL, 314, 'local:hafs-text.json'),
  ('hafs-20-44', 'hafs', 20, 44, 'فَقُولَا لَهُۥ قَوْلًۭا لَّيِّنًۭا لَّعَلَّهُۥ يَتَذَكَّرُ أَوْ يَخْشَىٰ', 'فقولا له قولا لينا لعله يتذكر أو يخشى', NULL, 314, 'local:hafs-text.json'),
  ('hafs-20-45', 'hafs', 20, 45, 'قَالَا رَبَّنَآ إِنَّنَا نَخَافُ أَن يَفْرُطَ عَلَيْنَآ أَوْ أَن يَطْغَىٰ', 'قالا ربنا إننا نخاف أن يفرط علينا أو أن يطغى', NULL, 314, 'local:hafs-text.json'),
  ('hafs-20-46', 'hafs', 20, 46, 'قَالَ لَا تَخَافَآ ۖ إِنَّنِى مَعَكُمَآ أَسْمَعُ وَأَرَىٰ', 'قال لا تخافا  إننى معكما أسمع وأرى', NULL, 314, 'local:hafs-text.json'),
  ('hafs-20-47', 'hafs', 20, 47, 'فَأْتِيَاهُ فَقُولَآ إِنَّا رَسُولَا رَبِّكَ فَأَرْسِلْ مَعَنَا بَنِىٓ إِسْرَٰٓءِيلَ وَلَا تُعَذِّبْهُمْ ۖ قَدْ جِئْنَٰكَ بِـَٔايَةٍۢ مِّن رَّبِّكَ ۖ وَٱلسَّلَٰمُ عَلَىٰ مَنِ ٱتَّبَعَ ٱلْهُدَىٰٓ', 'فأتياه فقولا إنا رسولا ربك فأرسل معنا بنى إسرءيل ولا تعذبهم  قد جئنك باية من ربك  والسلم على من اتبع الهدى', NULL, 314, 'local:hafs-text.json'),
  ('hafs-20-48', 'hafs', 20, 48, 'إِنَّا قَدْ أُوحِىَ إِلَيْنَآ أَنَّ ٱلْعَذَابَ عَلَىٰ مَن كَذَّبَ وَتَوَلَّىٰ', 'إنا قد أوحى إلينا أن العذاب على من كذب وتولى', NULL, 314, 'local:hafs-text.json'),
  ('hafs-20-49', 'hafs', 20, 49, 'قَالَ فَمَن رَّبُّكُمَا يَٰمُوسَىٰ', 'قال فمن ربكما يموسى', NULL, 314, 'local:hafs-text.json'),
  ('hafs-20-50', 'hafs', 20, 50, 'قَالَ رَبُّنَا ٱلَّذِىٓ أَعْطَىٰ كُلَّ شَىْءٍ خَلْقَهُۥ ثُمَّ هَدَىٰ', 'قال ربنا الذى أعطى كل شىء خلقه ثم هدى', NULL, 314, 'local:hafs-text.json'),
  ('hafs-20-51', 'hafs', 20, 51, 'قَالَ فَمَا بَالُ ٱلْقُرُونِ ٱلْأُولَىٰ', 'قال فما بال القرون الأولى', NULL, 314, 'local:hafs-text.json'),
  ('hafs-20-52', 'hafs', 20, 52, 'قَالَ عِلْمُهَا عِندَ رَبِّى فِى كِتَٰبٍۢ ۖ لَّا يَضِلُّ رَبِّى وَلَا يَنسَى', 'قال علمها عند ربى فى كتب  لا يضل ربى ولا ينسى', NULL, 315, 'local:hafs-text.json')
insert into public.ayahs (id, riwayah, surah_number, ayah_number, text, simple_text, juz, page, source) values
  ('hafs-20-53', 'hafs', 20, 53, 'ٱلَّذِى جَعَلَ لَكُمُ ٱلْأَرْضَ مَهْدًۭا وَسَلَكَ لَكُمْ فِيهَا سُبُلًۭا وَأَنزَلَ مِنَ ٱلسَّمَآءِ مَآءًۭ فَأَخْرَجْنَا بِهِۦٓ أَزْوَٰجًۭا مِّن نَّبَاتٍۢ شَتَّىٰ', 'الذى جعل لكم الأرض مهدا وسلك لكم فيها سبلا وأنزل من السماء ماء فأخرجنا به أزوجا من نبات شتى', NULL, 315, 'local:hafs-text.json'),
  ('hafs-20-54', 'hafs', 20, 54, 'كُلُوا۟ وَٱرْعَوْا۟ أَنْعَٰمَكُمْ ۗ إِنَّ فِى ذَٰلِكَ لَءَايَٰتٍۢ لِّأُو۟لِى ٱلنُّهَىٰ', 'كلوا وارعوا أنعمكم  إن فى ذلك لءايت لأولى النهى', NULL, 315, 'local:hafs-text.json'),
  ('hafs-20-55', 'hafs', 20, 55, '۞ مِنْهَا خَلَقْنَٰكُمْ وَفِيهَا نُعِيدُكُمْ وَمِنْهَا نُخْرِجُكُمْ تَارَةً أُخْرَىٰ', 'منها خلقنكم وفيها نعيدكم ومنها نخرجكم تارة أخرى', NULL, 315, 'local:hafs-text.json'),
  ('hafs-20-56', 'hafs', 20, 56, 'وَلَقَدْ أَرَيْنَٰهُ ءَايَٰتِنَا كُلَّهَا فَكَذَّبَ وَأَبَىٰ', 'ولقد أرينه ءايتنا كلها فكذب وأبى', NULL, 315, 'local:hafs-text.json'),
  ('hafs-20-57', 'hafs', 20, 57, 'قَالَ أَجِئْتَنَا لِتُخْرِجَنَا مِنْ أَرْضِنَا بِسِحْرِكَ يَٰمُوسَىٰ', 'قال أجئتنا لتخرجنا من أرضنا بسحرك يموسى', NULL, 315, 'local:hafs-text.json'),
  ('hafs-20-58', 'hafs', 20, 58, 'فَلَنَأْتِيَنَّكَ بِسِحْرٍۢ مِّثْلِهِۦ فَٱجْعَلْ بَيْنَنَا وَبَيْنَكَ مَوْعِدًۭا لَّا نُخْلِفُهُۥ نَحْنُ وَلَآ أَنتَ مَكَانًۭا سُوًۭى', 'فلنأتينك بسحر مثله فاجعل بيننا وبينك موعدا لا نخلفه نحن ولا أنت مكانا سوى', NULL, 315, 'local:hafs-text.json'),
  ('hafs-20-59', 'hafs', 20, 59, 'قَالَ مَوْعِدُكُمْ يَوْمُ ٱلزِّينَةِ وَأَن يُحْشَرَ ٱلنَّاسُ ضُحًۭى', 'قال موعدكم يوم الزينة وأن يحشر الناس ضحى', NULL, 315, 'local:hafs-text.json'),
  ('hafs-20-60', 'hafs', 20, 60, 'فَتَوَلَّىٰ فِرْعَوْنُ فَجَمَعَ كَيْدَهُۥ ثُمَّ أَتَىٰ', 'فتولى فرعون فجمع كيده ثم أتى', NULL, 315, 'local:hafs-text.json'),
  ('hafs-20-61', 'hafs', 20, 61, 'قَالَ لَهُم مُّوسَىٰ وَيْلَكُمْ لَا تَفْتَرُوا۟ عَلَى ٱللَّهِ كَذِبًۭا فَيُسْحِتَكُم بِعَذَابٍۢ ۖ وَقَدْ خَابَ مَنِ ٱفْتَرَىٰ', 'قال لهم موسى ويلكم لا تفتروا على الله كذبا فيسحتكم بعذاب  وقد خاب من افترى', NULL, 315, 'local:hafs-text.json'),
  ('hafs-20-62', 'hafs', 20, 62, 'فَتَنَٰزَعُوٓا۟ أَمْرَهُم بَيْنَهُمْ وَأَسَرُّوا۟ ٱلنَّجْوَىٰ', 'فتنزعوا أمرهم بينهم وأسروا النجوى', NULL, 315, 'local:hafs-text.json'),
  ('hafs-20-63', 'hafs', 20, 63, 'قَالُوٓا۟ إِنْ هَٰذَٰنِ لَسَٰحِرَٰنِ يُرِيدَانِ أَن يُخْرِجَاكُم مِّنْ أَرْضِكُم بِسِحْرِهِمَا وَيَذْهَبَا بِطَرِيقَتِكُمُ ٱلْمُثْلَىٰ', 'قالوا إن هذن لسحرن يريدان أن يخرجاكم من أرضكم بسحرهما ويذهبا بطريقتكم المثلى', NULL, 315, 'local:hafs-text.json'),
  ('hafs-20-64', 'hafs', 20, 64, 'فَأَجْمِعُوا۟ كَيْدَكُمْ ثُمَّ ٱئْتُوا۟ صَفًّۭا ۚ وَقَدْ أَفْلَحَ ٱلْيَوْمَ مَنِ ٱسْتَعْلَىٰ', 'فأجمعوا كيدكم ثم ائتوا صفا  وقد أفلح اليوم من استعلى', NULL, 315, 'local:hafs-text.json'),
  ('hafs-20-65', 'hafs', 20, 65, 'قَالُوا۟ يَٰمُوسَىٰٓ إِمَّآ أَن تُلْقِىَ وَإِمَّآ أَن نَّكُونَ أَوَّلَ مَنْ أَلْقَىٰ', 'قالوا يموسى إما أن تلقى وإما أن نكون أول من ألقى', NULL, 316, 'local:hafs-text.json'),
  ('hafs-20-66', 'hafs', 20, 66, 'قَالَ بَلْ أَلْقُوا۟ ۖ فَإِذَا حِبَالُهُمْ وَعِصِيُّهُمْ يُخَيَّلُ إِلَيْهِ مِن سِحْرِهِمْ أَنَّهَا تَسْعَىٰ', 'قال بل ألقوا  فإذا حبالهم وعصيهم يخيل إليه من سحرهم أنها تسعى', NULL, 316, 'local:hafs-text.json'),
  ('hafs-20-67', 'hafs', 20, 67, 'فَأَوْجَسَ فِى نَفْسِهِۦ خِيفَةًۭ مُّوسَىٰ', 'فأوجس فى نفسه خيفة موسى', NULL, 316, 'local:hafs-text.json'),
  ('hafs-20-68', 'hafs', 20, 68, 'قُلْنَا لَا تَخَفْ إِنَّكَ أَنتَ ٱلْأَعْلَىٰ', 'قلنا لا تخف إنك أنت الأعلى', NULL, 316, 'local:hafs-text.json'),
  ('hafs-20-69', 'hafs', 20, 69, 'وَأَلْقِ مَا فِى يَمِينِكَ تَلْقَفْ مَا صَنَعُوٓا۟ ۖ إِنَّمَا صَنَعُوا۟ كَيْدُ سَٰحِرٍۢ ۖ وَلَا يُفْلِحُ ٱلسَّاحِرُ حَيْثُ أَتَىٰ', 'وألق ما فى يمينك تلقف ما صنعوا  إنما صنعوا كيد سحر  ولا يفلح الساحر حيث أتى', NULL, 316, 'local:hafs-text.json'),
  ('hafs-20-70', 'hafs', 20, 70, 'فَأُلْقِىَ ٱلسَّحَرَةُ سُجَّدًۭا قَالُوٓا۟ ءَامَنَّا بِرَبِّ هَٰرُونَ وَمُوسَىٰ', 'فألقى السحرة سجدا قالوا ءامنا برب هرون وموسى', NULL, 316, 'local:hafs-text.json'),
  ('hafs-20-71', 'hafs', 20, 71, 'قَالَ ءَامَنتُمْ لَهُۥ قَبْلَ أَنْ ءَاذَنَ لَكُمْ ۖ إِنَّهُۥ لَكَبِيرُكُمُ ٱلَّذِى عَلَّمَكُمُ ٱلسِّحْرَ ۖ فَلَأُقَطِّعَنَّ أَيْدِيَكُمْ وَأَرْجُلَكُم مِّنْ خِلَٰفٍۢ وَلَأُصَلِّبَنَّكُمْ فِى جُذُوعِ ٱلنَّخْلِ وَلَتَعْلَمُنَّ أَيُّنَآ أَشَدُّ عَذَابًۭا وَأَبْقَىٰ', 'قال ءامنتم له قبل أن ءاذن لكم  إنه لكبيركم الذى علمكم السحر  فلأقطعن أيديكم وأرجلكم من خلف ولأصلبنكم فى جذوع النخل ولتعلمن أينا أشد عذابا وأبقى', NULL, 316, 'local:hafs-text.json'),
  ('hafs-20-72', 'hafs', 20, 72, 'قَالُوا۟ لَن نُّؤْثِرَكَ عَلَىٰ مَا جَآءَنَا مِنَ ٱلْبَيِّنَٰتِ وَٱلَّذِى فَطَرَنَا ۖ فَٱقْضِ مَآ أَنتَ قَاضٍ ۖ إِنَّمَا تَقْضِى هَٰذِهِ ٱلْحَيَوٰةَ ٱلدُّنْيَآ', 'قالوا لن نؤثرك على ما جاءنا من البينت والذى فطرنا  فاقض ما أنت قاض  إنما تقضى هذه الحيوة الدنيا', NULL, 316, 'local:hafs-text.json'),
  ('hafs-20-73', 'hafs', 20, 73, 'إِنَّآ ءَامَنَّا بِرَبِّنَا لِيَغْفِرَ لَنَا خَطَٰيَٰنَا وَمَآ أَكْرَهْتَنَا عَلَيْهِ مِنَ ٱلسِّحْرِ ۗ وَٱللَّهُ خَيْرٌۭ وَأَبْقَىٰٓ', 'إنا ءامنا بربنا ليغفر لنا خطينا وما أكرهتنا عليه من السحر  والله خير وأبقى', NULL, 316, 'local:hafs-text.json'),
  ('hafs-20-74', 'hafs', 20, 74, 'إِنَّهُۥ مَن يَأْتِ رَبَّهُۥ مُجْرِمًۭا فَإِنَّ لَهُۥ جَهَنَّمَ لَا يَمُوتُ فِيهَا وَلَا يَحْيَىٰ', 'إنه من يأت ربه مجرما فإن له جهنم لا يموت فيها ولا يحيى', NULL, 316, 'local:hafs-text.json'),
  ('hafs-20-75', 'hafs', 20, 75, 'وَمَن يَأْتِهِۦ مُؤْمِنًۭا قَدْ عَمِلَ ٱلصَّٰلِحَٰتِ فَأُو۟لَٰٓئِكَ لَهُمُ ٱلدَّرَجَٰتُ ٱلْعُلَىٰ', 'ومن يأته مؤمنا قد عمل الصلحت فأولئك لهم الدرجت العلى', NULL, 316, 'local:hafs-text.json'),
  ('hafs-20-76', 'hafs', 20, 76, 'جَنَّٰتُ عَدْنٍۢ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ خَٰلِدِينَ فِيهَا ۚ وَذَٰلِكَ جَزَآءُ مَن تَزَكَّىٰ', 'جنت عدن تجرى من تحتها الأنهر خلدين فيها  وذلك جزاء من تزكى', NULL, 316, 'local:hafs-text.json'),
  ('hafs-20-77', 'hafs', 20, 77, 'وَلَقَدْ أَوْحَيْنَآ إِلَىٰ مُوسَىٰٓ أَنْ أَسْرِ بِعِبَادِى فَٱضْرِبْ لَهُمْ طَرِيقًۭا فِى ٱلْبَحْرِ يَبَسًۭا لَّا تَخَٰفُ دَرَكًۭا وَلَا تَخْشَىٰ', 'ولقد أوحينا إلى موسى أن أسر بعبادى فاضرب لهم طريقا فى البحر يبسا لا تخف دركا ولا تخشى', NULL, 317, 'local:hafs-text.json'),
  ('hafs-20-78', 'hafs', 20, 78, 'فَأَتْبَعَهُمْ فِرْعَوْنُ بِجُنُودِهِۦ فَغَشِيَهُم مِّنَ ٱلْيَمِّ مَا غَشِيَهُمْ', 'فأتبعهم فرعون بجنوده فغشيهم من اليم ما غشيهم', NULL, 317, 'local:hafs-text.json'),
  ('hafs-20-79', 'hafs', 20, 79, 'وَأَضَلَّ فِرْعَوْنُ قَوْمَهُۥ وَمَا هَدَىٰ', 'وأضل فرعون قومه وما هدى', NULL, 317, 'local:hafs-text.json'),
  ('hafs-20-80', 'hafs', 20, 80, 'يَٰبَنِىٓ إِسْرَٰٓءِيلَ قَدْ أَنجَيْنَٰكُم مِّنْ عَدُوِّكُمْ وَوَٰعَدْنَٰكُمْ جَانِبَ ٱلطُّورِ ٱلْأَيْمَنَ وَنَزَّلْنَا عَلَيْكُمُ ٱلْمَنَّ وَٱلسَّلْوَىٰ', 'يبنى إسرءيل قد أنجينكم من عدوكم ووعدنكم جانب الطور الأيمن ونزلنا عليكم المن والسلوى', NULL, 317, 'local:hafs-text.json'),
  ('hafs-20-81', 'hafs', 20, 81, 'كُلُوا۟ مِن طَيِّبَٰتِ مَا رَزَقْنَٰكُمْ وَلَا تَطْغَوْا۟ فِيهِ فَيَحِلَّ عَلَيْكُمْ غَضَبِى ۖ وَمَن يَحْلِلْ عَلَيْهِ غَضَبِى فَقَدْ هَوَىٰ', 'كلوا من طيبت ما رزقنكم ولا تطغوا فيه فيحل عليكم غضبى  ومن يحلل عليه غضبى فقد هوى', NULL, 317, 'local:hafs-text.json'),
  ('hafs-20-82', 'hafs', 20, 82, 'وَإِنِّى لَغَفَّارٌۭ لِّمَن تَابَ وَءَامَنَ وَعَمِلَ صَٰلِحًۭا ثُمَّ ٱهْتَدَىٰ', 'وإنى لغفار لمن تاب وءامن وعمل صلحا ثم اهتدى', NULL, 317, 'local:hafs-text.json'),
  ('hafs-20-83', 'hafs', 20, 83, '۞ وَمَآ أَعْجَلَكَ عَن قَوْمِكَ يَٰمُوسَىٰ', 'وما أعجلك عن قومك يموسى', NULL, 317, 'local:hafs-text.json'),
  ('hafs-20-84', 'hafs', 20, 84, 'قَالَ هُمْ أُو۟لَآءِ عَلَىٰٓ أَثَرِى وَعَجِلْتُ إِلَيْكَ رَبِّ لِتَرْضَىٰ', 'قال هم أولاء على أثرى وعجلت إليك رب لترضى', NULL, 317, 'local:hafs-text.json'),
  ('hafs-20-85', 'hafs', 20, 85, 'قَالَ فَإِنَّا قَدْ فَتَنَّا قَوْمَكَ مِنۢ بَعْدِكَ وَأَضَلَّهُمُ ٱلسَّامِرِىُّ', 'قال فإنا قد فتنا قومك من بعدك وأضلهم السامرى', NULL, 317, 'local:hafs-text.json'),
  ('hafs-20-86', 'hafs', 20, 86, 'فَرَجَعَ مُوسَىٰٓ إِلَىٰ قَوْمِهِۦ غَضْبَٰنَ أَسِفًۭا ۚ قَالَ يَٰقَوْمِ أَلَمْ يَعِدْكُمْ رَبُّكُمْ وَعْدًا حَسَنًا ۚ أَفَطَالَ عَلَيْكُمُ ٱلْعَهْدُ أَمْ أَرَدتُّمْ أَن يَحِلَّ عَلَيْكُمْ غَضَبٌۭ مِّن رَّبِّكُمْ فَأَخْلَفْتُم مَّوْعِدِى', 'فرجع موسى إلى قومه غضبن أسفا  قال يقوم ألم يعدكم ربكم وعدا حسنا  أفطال عليكم العهد أم أردتم أن يحل عليكم غضب من ربكم فأخلفتم موعدى', NULL, 317, 'local:hafs-text.json'),
  ('hafs-20-87', 'hafs', 20, 87, 'قَالُوا۟ مَآ أَخْلَفْنَا مَوْعِدَكَ بِمَلْكِنَا وَلَٰكِنَّا حُمِّلْنَآ أَوْزَارًۭا مِّن زِينَةِ ٱلْقَوْمِ فَقَذَفْنَٰهَا فَكَذَٰلِكَ أَلْقَى ٱلسَّامِرِىُّ', 'قالوا ما أخلفنا موعدك بملكنا ولكنا حملنا أوزارا من زينة القوم فقذفنها فكذلك ألقى السامرى', NULL, 317, 'local:hafs-text.json'),
  ('hafs-20-88', 'hafs', 20, 88, 'فَأَخْرَجَ لَهُمْ عِجْلًۭا جَسَدًۭا لَّهُۥ خُوَارٌۭ فَقَالُوا۟ هَٰذَآ إِلَٰهُكُمْ وَإِلَٰهُ مُوسَىٰ فَنَسِىَ', 'فأخرج لهم عجلا جسدا له خوار فقالوا هذا إلهكم وإله موسى فنسى', NULL, 318, 'local:hafs-text.json'),
  ('hafs-20-89', 'hafs', 20, 89, 'أَفَلَا يَرَوْنَ أَلَّا يَرْجِعُ إِلَيْهِمْ قَوْلًۭا وَلَا يَمْلِكُ لَهُمْ ضَرًّۭا وَلَا نَفْعًۭا', 'أفلا يرون ألا يرجع إليهم قولا ولا يملك لهم ضرا ولا نفعا', NULL, 318, 'local:hafs-text.json'),
  ('hafs-20-90', 'hafs', 20, 90, 'وَلَقَدْ قَالَ لَهُمْ هَٰرُونُ مِن قَبْلُ يَٰقَوْمِ إِنَّمَا فُتِنتُم بِهِۦ ۖ وَإِنَّ رَبَّكُمُ ٱلرَّحْمَٰنُ فَٱتَّبِعُونِى وَأَطِيعُوٓا۟ أَمْرِى', 'ولقد قال لهم هرون من قبل يقوم إنما فتنتم به  وإن ربكم الرحمن فاتبعونى وأطيعوا أمرى', NULL, 318, 'local:hafs-text.json'),
  ('hafs-20-91', 'hafs', 20, 91, 'قَالُوا۟ لَن نَّبْرَحَ عَلَيْهِ عَٰكِفِينَ حَتَّىٰ يَرْجِعَ إِلَيْنَا مُوسَىٰ', 'قالوا لن نبرح عليه عكفين حتى يرجع إلينا موسى', NULL, 318, 'local:hafs-text.json'),
  ('hafs-20-92', 'hafs', 20, 92, 'قَالَ يَٰهَٰرُونُ مَا مَنَعَكَ إِذْ رَأَيْتَهُمْ ضَلُّوٓا۟', 'قال يهرون ما منعك إذ رأيتهم ضلوا', NULL, 318, 'local:hafs-text.json'),
  ('hafs-20-93', 'hafs', 20, 93, 'أَلَّا تَتَّبِعَنِ ۖ أَفَعَصَيْتَ أَمْرِى', 'ألا تتبعن  أفعصيت أمرى', NULL, 318, 'local:hafs-text.json'),
  ('hafs-20-94', 'hafs', 20, 94, 'قَالَ يَبْنَؤُمَّ لَا تَأْخُذْ بِلِحْيَتِى وَلَا بِرَأْسِىٓ ۖ إِنِّى خَشِيتُ أَن تَقُولَ فَرَّقْتَ بَيْنَ بَنِىٓ إِسْرَٰٓءِيلَ وَلَمْ تَرْقُبْ قَوْلِى', 'قال يبنؤم لا تأخذ بلحيتى ولا برأسى  إنى خشيت أن تقول فرقت بين بنى إسرءيل ولم ترقب قولى', NULL, 318, 'local:hafs-text.json'),
  ('hafs-20-95', 'hafs', 20, 95, 'قَالَ فَمَا خَطْبُكَ يَٰسَٰمِرِىُّ', 'قال فما خطبك يسمرى', NULL, 318, 'local:hafs-text.json'),
  ('hafs-20-96', 'hafs', 20, 96, 'قَالَ بَصُرْتُ بِمَا لَمْ يَبْصُرُوا۟ بِهِۦ فَقَبَضْتُ قَبْضَةًۭ مِّنْ أَثَرِ ٱلرَّسُولِ فَنَبَذْتُهَا وَكَذَٰلِكَ سَوَّلَتْ لِى نَفْسِى', 'قال بصرت بما لم يبصروا به فقبضت قبضة من أثر الرسول فنبذتها وكذلك سولت لى نفسى', NULL, 318, 'local:hafs-text.json'),
  ('hafs-20-97', 'hafs', 20, 97, 'قَالَ فَٱذْهَبْ فَإِنَّ لَكَ فِى ٱلْحَيَوٰةِ أَن تَقُولَ لَا مِسَاسَ ۖ وَإِنَّ لَكَ مَوْعِدًۭا لَّن تُخْلَفَهُۥ ۖ وَٱنظُرْ إِلَىٰٓ إِلَٰهِكَ ٱلَّذِى ظَلْتَ عَلَيْهِ عَاكِفًۭا ۖ لَّنُحَرِّقَنَّهُۥ ثُمَّ لَنَنسِفَنَّهُۥ فِى ٱلْيَمِّ نَسْفًا', 'قال فاذهب فإن لك فى الحيوة أن تقول لا مساس  وإن لك موعدا لن تخلفه  وانظر إلى إلهك الذى ظلت عليه عاكفا  لنحرقنه ثم لننسفنه فى اليم نسفا', NULL, 318, 'local:hafs-text.json'),
  ('hafs-20-98', 'hafs', 20, 98, 'إِنَّمَآ إِلَٰهُكُمُ ٱللَّهُ ٱلَّذِى لَآ إِلَٰهَ إِلَّا هُوَ ۚ وَسِعَ كُلَّ شَىْءٍ عِلْمًۭا', 'إنما إلهكم الله الذى لا إله إلا هو  وسع كل شىء علما', NULL, 318, 'local:hafs-text.json'),
  ('hafs-20-99', 'hafs', 20, 99, 'كَذَٰلِكَ نَقُصُّ عَلَيْكَ مِنْ أَنۢبَآءِ مَا قَدْ سَبَقَ ۚ وَقَدْ ءَاتَيْنَٰكَ مِن لَّدُنَّا ذِكْرًۭا', 'كذلك نقص عليك من أنباء ما قد سبق  وقد ءاتينك من لدنا ذكرا', NULL, 319, 'local:hafs-text.json'),
  ('hafs-20-100', 'hafs', 20, 100, 'مَّنْ أَعْرَضَ عَنْهُ فَإِنَّهُۥ يَحْمِلُ يَوْمَ ٱلْقِيَٰمَةِ وِزْرًا', 'من أعرض عنه فإنه يحمل يوم القيمة وزرا', NULL, 319, 'local:hafs-text.json'),
  ('hafs-20-101', 'hafs', 20, 101, 'خَٰلِدِينَ فِيهِ ۖ وَسَآءَ لَهُمْ يَوْمَ ٱلْقِيَٰمَةِ حِمْلًۭا', 'خلدين فيه  وساء لهم يوم القيمة حملا', NULL, 319, 'local:hafs-text.json'),
  ('hafs-20-102', 'hafs', 20, 102, 'يَوْمَ يُنفَخُ فِى ٱلصُّورِ ۚ وَنَحْشُرُ ٱلْمُجْرِمِينَ يَوْمَئِذٍۢ زُرْقًۭا', 'يوم ينفخ فى الصور  ونحشر المجرمين يومئذ زرقا', NULL, 319, 'local:hafs-text.json'),
  ('hafs-20-103', 'hafs', 20, 103, 'يَتَخَٰفَتُونَ بَيْنَهُمْ إِن لَّبِثْتُمْ إِلَّا عَشْرًۭا', 'يتخفتون بينهم إن لبثتم إلا عشرا', NULL, 319, 'local:hafs-text.json'),
  ('hafs-20-104', 'hafs', 20, 104, 'نَّحْنُ أَعْلَمُ بِمَا يَقُولُونَ إِذْ يَقُولُ أَمْثَلُهُمْ طَرِيقَةً إِن لَّبِثْتُمْ إِلَّا يَوْمًۭا', 'نحن أعلم بما يقولون إذ يقول أمثلهم طريقة إن لبثتم إلا يوما', NULL, 319, 'local:hafs-text.json'),
  ('hafs-20-105', 'hafs', 20, 105, 'وَيَسْـَٔلُونَكَ عَنِ ٱلْجِبَالِ فَقُلْ يَنسِفُهَا رَبِّى نَسْفًۭا', 'ويسلونك عن الجبال فقل ينسفها ربى نسفا', NULL, 319, 'local:hafs-text.json'),
  ('hafs-20-106', 'hafs', 20, 106, 'فَيَذَرُهَا قَاعًۭا صَفْصَفًۭا', 'فيذرها قاعا صفصفا', NULL, 319, 'local:hafs-text.json'),
  ('hafs-20-107', 'hafs', 20, 107, 'لَّا تَرَىٰ فِيهَا عِوَجًۭا وَلَآ أَمْتًۭا', 'لا ترى فيها عوجا ولا أمتا', NULL, 319, 'local:hafs-text.json'),
  ('hafs-20-108', 'hafs', 20, 108, 'يَوْمَئِذٍۢ يَتَّبِعُونَ ٱلدَّاعِىَ لَا عِوَجَ لَهُۥ ۖ وَخَشَعَتِ ٱلْأَصْوَاتُ لِلرَّحْمَٰنِ فَلَا تَسْمَعُ إِلَّا هَمْسًۭا', 'يومئذ يتبعون الداعى لا عوج له  وخشعت الأصوات للرحمن فلا تسمع إلا همسا', NULL, 319, 'local:hafs-text.json'),
  ('hafs-20-109', 'hafs', 20, 109, 'يَوْمَئِذٍۢ لَّا تَنفَعُ ٱلشَّفَٰعَةُ إِلَّا مَنْ أَذِنَ لَهُ ٱلرَّحْمَٰنُ وَرَضِىَ لَهُۥ قَوْلًۭا', 'يومئذ لا تنفع الشفعة إلا من أذن له الرحمن ورضى له قولا', NULL, 319, 'local:hafs-text.json'),
  ('hafs-20-110', 'hafs', 20, 110, 'يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ وَلَا يُحِيطُونَ بِهِۦ عِلْمًۭا', 'يعلم ما بين أيديهم وما خلفهم ولا يحيطون به علما', NULL, 319, 'local:hafs-text.json'),
  ('hafs-20-111', 'hafs', 20, 111, '۞ وَعَنَتِ ٱلْوُجُوهُ لِلْحَىِّ ٱلْقَيُّومِ ۖ وَقَدْ خَابَ مَنْ حَمَلَ ظُلْمًۭا', 'وعنت الوجوه للحى القيوم  وقد خاب من حمل ظلما', NULL, 319, 'local:hafs-text.json'),
  ('hafs-20-112', 'hafs', 20, 112, 'وَمَن يَعْمَلْ مِنَ ٱلصَّٰلِحَٰتِ وَهُوَ مُؤْمِنٌۭ فَلَا يَخَافُ ظُلْمًۭا وَلَا هَضْمًۭا', 'ومن يعمل من الصلحت وهو مؤمن فلا يخاف ظلما ولا هضما', NULL, 319, 'local:hafs-text.json'),
  ('hafs-20-113', 'hafs', 20, 113, 'وَكَذَٰلِكَ أَنزَلْنَٰهُ قُرْءَانًا عَرَبِيًّۭا وَصَرَّفْنَا فِيهِ مِنَ ٱلْوَعِيدِ لَعَلَّهُمْ يَتَّقُونَ أَوْ يُحْدِثُ لَهُمْ ذِكْرًۭا', 'وكذلك أنزلنه قرءانا عربيا وصرفنا فيه من الوعيد لعلهم يتقون أو يحدث لهم ذكرا', NULL, 319, 'local:hafs-text.json'),
  ('hafs-20-114', 'hafs', 20, 114, 'فَتَعَٰلَى ٱللَّهُ ٱلْمَلِكُ ٱلْحَقُّ ۗ وَلَا تَعْجَلْ بِٱلْقُرْءَانِ مِن قَبْلِ أَن يُقْضَىٰٓ إِلَيْكَ وَحْيُهُۥ ۖ وَقُل رَّبِّ زِدْنِى عِلْمًۭا', 'فتعلى الله الملك الحق  ولا تعجل بالقرءان من قبل أن يقضى إليك وحيه  وقل رب زدنى علما', NULL, 320, 'local:hafs-text.json'),
  ('hafs-20-115', 'hafs', 20, 115, 'وَلَقَدْ عَهِدْنَآ إِلَىٰٓ ءَادَمَ مِن قَبْلُ فَنَسِىَ وَلَمْ نَجِدْ لَهُۥ عَزْمًۭا', 'ولقد عهدنا إلى ءادم من قبل فنسى ولم نجد له عزما', NULL, 320, 'local:hafs-text.json'),
  ('hafs-20-116', 'hafs', 20, 116, 'وَإِذْ قُلْنَا لِلْمَلَٰٓئِكَةِ ٱسْجُدُوا۟ لِءَادَمَ فَسَجَدُوٓا۟ إِلَّآ إِبْلِيسَ أَبَىٰ', 'وإذ قلنا للملئكة اسجدوا لءادم فسجدوا إلا إبليس أبى', NULL, 320, 'local:hafs-text.json'),
  ('hafs-20-117', 'hafs', 20, 117, 'فَقُلْنَا يَٰٓـَٔادَمُ إِنَّ هَٰذَا عَدُوٌّۭ لَّكَ وَلِزَوْجِكَ فَلَا يُخْرِجَنَّكُمَا مِنَ ٱلْجَنَّةِ فَتَشْقَىٰٓ', 'فقلنا يادم إن هذا عدو لك ولزوجك فلا يخرجنكما من الجنة فتشقى', NULL, 320, 'local:hafs-text.json'),
  ('hafs-20-118', 'hafs', 20, 118, 'إِنَّ لَكَ أَلَّا تَجُوعَ فِيهَا وَلَا تَعْرَىٰ', 'إن لك ألا تجوع فيها ولا تعرى', NULL, 320, 'local:hafs-text.json'),
  ('hafs-20-119', 'hafs', 20, 119, 'وَأَنَّكَ لَا تَظْمَؤُا۟ فِيهَا وَلَا تَضْحَىٰ', 'وأنك لا تظمؤا فيها ولا تضحى', NULL, 320, 'local:hafs-text.json'),
  ('hafs-20-120', 'hafs', 20, 120, 'فَوَسْوَسَ إِلَيْهِ ٱلشَّيْطَٰنُ قَالَ يَٰٓـَٔادَمُ هَلْ أَدُلُّكَ عَلَىٰ شَجَرَةِ ٱلْخُلْدِ وَمُلْكٍۢ لَّا يَبْلَىٰ', 'فوسوس إليه الشيطن قال يادم هل أدلك على شجرة الخلد وملك لا يبلى', NULL, 320, 'local:hafs-text.json'),
  ('hafs-20-121', 'hafs', 20, 121, 'فَأَكَلَا مِنْهَا فَبَدَتْ لَهُمَا سَوْءَٰتُهُمَا وَطَفِقَا يَخْصِفَانِ عَلَيْهِمَا مِن وَرَقِ ٱلْجَنَّةِ ۚ وَعَصَىٰٓ ءَادَمُ رَبَّهُۥ فَغَوَىٰ', 'فأكلا منها فبدت لهما سوءتهما وطفقا يخصفان عليهما من ورق الجنة  وعصى ءادم ربه فغوى', NULL, 320, 'local:hafs-text.json'),
  ('hafs-20-122', 'hafs', 20, 122, 'ثُمَّ ٱجْتَبَٰهُ رَبُّهُۥ فَتَابَ عَلَيْهِ وَهَدَىٰ', 'ثم اجتبه ربه فتاب عليه وهدى', NULL, 320, 'local:hafs-text.json'),
  ('hafs-20-123', 'hafs', 20, 123, 'قَالَ ٱهْبِطَا مِنْهَا جَمِيعًۢا ۖ بَعْضُكُمْ لِبَعْضٍ عَدُوٌّۭ ۖ فَإِمَّا يَأْتِيَنَّكُم مِّنِّى هُدًۭى فَمَنِ ٱتَّبَعَ هُدَاىَ فَلَا يَضِلُّ وَلَا يَشْقَىٰ', 'قال اهبطا منها جميعا  بعضكم لبعض عدو  فإما يأتينكم منى هدى فمن اتبع هداى فلا يضل ولا يشقى', NULL, 320, 'local:hafs-text.json'),
  ('hafs-20-124', 'hafs', 20, 124, 'وَمَنْ أَعْرَضَ عَن ذِكْرِى فَإِنَّ لَهُۥ مَعِيشَةًۭ ضَنكًۭا وَنَحْشُرُهُۥ يَوْمَ ٱلْقِيَٰمَةِ أَعْمَىٰ', 'ومن أعرض عن ذكرى فإن له معيشة ضنكا ونحشره يوم القيمة أعمى', NULL, 320, 'local:hafs-text.json'),
  ('hafs-20-125', 'hafs', 20, 125, 'قَالَ رَبِّ لِمَ حَشَرْتَنِىٓ أَعْمَىٰ وَقَدْ كُنتُ بَصِيرًۭا', 'قال رب لم حشرتنى أعمى وقد كنت بصيرا', NULL, 320, 'local:hafs-text.json'),
  ('hafs-20-126', 'hafs', 20, 126, 'قَالَ كَذَٰلِكَ أَتَتْكَ ءَايَٰتُنَا فَنَسِيتَهَا ۖ وَكَذَٰلِكَ ٱلْيَوْمَ تُنسَىٰ', 'قال كذلك أتتك ءايتنا فنسيتها  وكذلك اليوم تنسى', NULL, 321, 'local:hafs-text.json'),
  ('hafs-20-127', 'hafs', 20, 127, 'وَكَذَٰلِكَ نَجْزِى مَنْ أَسْرَفَ وَلَمْ يُؤْمِنۢ بِـَٔايَٰتِ رَبِّهِۦ ۚ وَلَعَذَابُ ٱلْءَاخِرَةِ أَشَدُّ وَأَبْقَىٰٓ', 'وكذلك نجزى من أسرف ولم يؤمن بايت ربه  ولعذاب الءاخرة أشد وأبقى', NULL, 321, 'local:hafs-text.json'),
  ('hafs-20-128', 'hafs', 20, 128, 'أَفَلَمْ يَهْدِ لَهُمْ كَمْ أَهْلَكْنَا قَبْلَهُم مِّنَ ٱلْقُرُونِ يَمْشُونَ فِى مَسَٰكِنِهِمْ ۗ إِنَّ فِى ذَٰلِكَ لَءَايَٰتٍۢ لِّأُو۟لِى ٱلنُّهَىٰ', 'أفلم يهد لهم كم أهلكنا قبلهم من القرون يمشون فى مسكنهم  إن فى ذلك لءايت لأولى النهى', NULL, 321, 'local:hafs-text.json'),
  ('hafs-20-129', 'hafs', 20, 129, 'وَلَوْلَا كَلِمَةٌۭ سَبَقَتْ مِن رَّبِّكَ لَكَانَ لِزَامًۭا وَأَجَلٌۭ مُّسَمًّۭى', 'ولولا كلمة سبقت من ربك لكان لزاما وأجل مسمى', NULL, 321, 'local:hafs-text.json'),
  ('hafs-20-130', 'hafs', 20, 130, 'فَٱصْبِرْ عَلَىٰ مَا يَقُولُونَ وَسَبِّحْ بِحَمْدِ رَبِّكَ قَبْلَ طُلُوعِ ٱلشَّمْسِ وَقَبْلَ غُرُوبِهَا ۖ وَمِنْ ءَانَآئِ ٱلَّيْلِ فَسَبِّحْ وَأَطْرَافَ ٱلنَّهَارِ لَعَلَّكَ تَرْضَىٰ', 'فاصبر على ما يقولون وسبح بحمد ربك قبل طلوع الشمس وقبل غروبها  ومن ءانائ اليل فسبح وأطراف النهار لعلك ترضى', NULL, 321, 'local:hafs-text.json'),
  ('hafs-20-131', 'hafs', 20, 131, 'وَلَا تَمُدَّنَّ عَيْنَيْكَ إِلَىٰ مَا مَتَّعْنَا بِهِۦٓ أَزْوَٰجًۭا مِّنْهُمْ زَهْرَةَ ٱلْحَيَوٰةِ ٱلدُّنْيَا لِنَفْتِنَهُمْ فِيهِ ۚ وَرِزْقُ رَبِّكَ خَيْرٌۭ وَأَبْقَىٰ', 'ولا تمدن عينيك إلى ما متعنا به أزوجا منهم زهرة الحيوة الدنيا لنفتنهم فيه  ورزق ربك خير وأبقى', NULL, 321, 'local:hafs-text.json'),
  ('hafs-20-132', 'hafs', 20, 132, 'وَأْمُرْ أَهْلَكَ بِٱلصَّلَوٰةِ وَٱصْطَبِرْ عَلَيْهَا ۖ لَا نَسْـَٔلُكَ رِزْقًۭا ۖ نَّحْنُ نَرْزُقُكَ ۗ وَٱلْعَٰقِبَةُ لِلتَّقْوَىٰ', 'وأمر أهلك بالصلوة واصطبر عليها  لا نسلك رزقا  نحن نرزقك  والعقبة للتقوى', NULL, 321, 'local:hafs-text.json'),
  ('hafs-20-133', 'hafs', 20, 133, 'وَقَالُوا۟ لَوْلَا يَأْتِينَا بِـَٔايَةٍۢ مِّن رَّبِّهِۦٓ ۚ أَوَلَمْ تَأْتِهِم بَيِّنَةُ مَا فِى ٱلصُّحُفِ ٱلْأُولَىٰ', 'وقالوا لولا يأتينا باية من ربه  أولم تأتهم بينة ما فى الصحف الأولى', NULL, 321, 'local:hafs-text.json'),
  ('hafs-20-134', 'hafs', 20, 134, 'وَلَوْ أَنَّآ أَهْلَكْنَٰهُم بِعَذَابٍۢ مِّن قَبْلِهِۦ لَقَالُوا۟ رَبَّنَا لَوْلَآ أَرْسَلْتَ إِلَيْنَا رَسُولًۭا فَنَتَّبِعَ ءَايَٰتِكَ مِن قَبْلِ أَن نَّذِلَّ وَنَخْزَىٰ', 'ولو أنا أهلكنهم بعذاب من قبله لقالوا ربنا لولا أرسلت إلينا رسولا فنتبع ءايتك من قبل أن نذل ونخزى', NULL, 321, 'local:hafs-text.json'),
  ('hafs-20-135', 'hafs', 20, 135, 'قُلْ كُلٌّۭ مُّتَرَبِّصٌۭ فَتَرَبَّصُوا۟ ۖ فَسَتَعْلَمُونَ مَنْ أَصْحَٰبُ ٱلصِّرَٰطِ ٱلسَّوِىِّ وَمَنِ ٱهْتَدَىٰ', 'قل كل متربص فتربصوا  فستعلمون من أصحب الصرط السوى ومن اهتدى', NULL, 321, 'local:hafs-text.json'),
  ('hafs-21-1', 'hafs', 21, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ ٱقْتَرَبَ لِلنَّاسِ حِسَابُهُمْ وَهُمْ فِى غَفْلَةٍۢ مُّعْرِضُونَ', 'بسم الله الرحمن الرحيم اقترب للناس حسابهم وهم فى غفلة معرضون', NULL, 322, 'local:hafs-text.json'),
  ('hafs-21-2', 'hafs', 21, 2, 'مَا يَأْتِيهِم مِّن ذِكْرٍۢ مِّن رَّبِّهِم مُّحْدَثٍ إِلَّا ٱسْتَمَعُوهُ وَهُمْ يَلْعَبُونَ', 'ما يأتيهم من ذكر من ربهم محدث إلا استمعوه وهم يلعبون', NULL, 322, 'local:hafs-text.json'),
  ('hafs-21-3', 'hafs', 21, 3, 'لَاهِيَةًۭ قُلُوبُهُمْ ۗ وَأَسَرُّوا۟ ٱلنَّجْوَى ٱلَّذِينَ ظَلَمُوا۟ هَلْ هَٰذَآ إِلَّا بَشَرٌۭ مِّثْلُكُمْ ۖ أَفَتَأْتُونَ ٱلسِّحْرَ وَأَنتُمْ تُبْصِرُونَ', 'لاهية قلوبهم  وأسروا النجوى الذين ظلموا هل هذا إلا بشر مثلكم  أفتأتون السحر وأنتم تبصرون', NULL, 322, 'local:hafs-text.json'),
  ('hafs-21-4', 'hafs', 21, 4, 'قَالَ رَبِّى يَعْلَمُ ٱلْقَوْلَ فِى ٱلسَّمَآءِ وَٱلْأَرْضِ ۖ وَهُوَ ٱلسَّمِيعُ ٱلْعَلِيمُ', 'قال ربى يعلم القول فى السماء والأرض  وهو السميع العليم', NULL, 322, 'local:hafs-text.json'),
  ('hafs-21-5', 'hafs', 21, 5, 'بَلْ قَالُوٓا۟ أَضْغَٰثُ أَحْلَٰمٍۭ بَلِ ٱفْتَرَىٰهُ بَلْ هُوَ شَاعِرٌۭ فَلْيَأْتِنَا بِـَٔايَةٍۢ كَمَآ أُرْسِلَ ٱلْأَوَّلُونَ', 'بل قالوا أضغث أحلم بل افترىه بل هو شاعر فليأتنا باية كما أرسل الأولون', NULL, 322, 'local:hafs-text.json'),
  ('hafs-21-6', 'hafs', 21, 6, 'مَآ ءَامَنَتْ قَبْلَهُم مِّن قَرْيَةٍ أَهْلَكْنَٰهَآ ۖ أَفَهُمْ يُؤْمِنُونَ', 'ما ءامنت قبلهم من قرية أهلكنها  أفهم يؤمنون', NULL, 322, 'local:hafs-text.json'),
  ('hafs-21-7', 'hafs', 21, 7, 'وَمَآ أَرْسَلْنَا قَبْلَكَ إِلَّا رِجَالًۭا نُّوحِىٓ إِلَيْهِمْ ۖ فَسْـَٔلُوٓا۟ أَهْلَ ٱلذِّكْرِ إِن كُنتُمْ لَا تَعْلَمُونَ', 'وما أرسلنا قبلك إلا رجالا نوحى إليهم  فسلوا أهل الذكر إن كنتم لا تعلمون', NULL, 322, 'local:hafs-text.json'),
  ('hafs-21-8', 'hafs', 21, 8, 'وَمَا جَعَلْنَٰهُمْ جَسَدًۭا لَّا يَأْكُلُونَ ٱلطَّعَامَ وَمَا كَانُوا۟ خَٰلِدِينَ', 'وما جعلنهم جسدا لا يأكلون الطعام وما كانوا خلدين', NULL, 322, 'local:hafs-text.json'),
  ('hafs-21-9', 'hafs', 21, 9, 'ثُمَّ صَدَقْنَٰهُمُ ٱلْوَعْدَ فَأَنجَيْنَٰهُمْ وَمَن نَّشَآءُ وَأَهْلَكْنَا ٱلْمُسْرِفِينَ', 'ثم صدقنهم الوعد فأنجينهم ومن نشاء وأهلكنا المسرفين', NULL, 322, 'local:hafs-text.json'),
  ('hafs-21-10', 'hafs', 21, 10, 'لَقَدْ أَنزَلْنَآ إِلَيْكُمْ كِتَٰبًۭا فِيهِ ذِكْرُكُمْ ۖ أَفَلَا تَعْقِلُونَ', 'لقد أنزلنا إليكم كتبا فيه ذكركم  أفلا تعقلون', NULL, 322, 'local:hafs-text.json'),
  ('hafs-21-11', 'hafs', 21, 11, 'وَكَمْ قَصَمْنَا مِن قَرْيَةٍۢ كَانَتْ ظَالِمَةًۭ وَأَنشَأْنَا بَعْدَهَا قَوْمًا ءَاخَرِينَ', 'وكم قصمنا من قرية كانت ظالمة وأنشأنا بعدها قوما ءاخرين', NULL, 323, 'local:hafs-text.json'),
  ('hafs-21-12', 'hafs', 21, 12, 'فَلَمَّآ أَحَسُّوا۟ بَأْسَنَآ إِذَا هُم مِّنْهَا يَرْكُضُونَ', 'فلما أحسوا بأسنا إذا هم منها يركضون', NULL, 323, 'local:hafs-text.json'),
  ('hafs-21-13', 'hafs', 21, 13, 'لَا تَرْكُضُوا۟ وَٱرْجِعُوٓا۟ إِلَىٰ مَآ أُتْرِفْتُمْ فِيهِ وَمَسَٰكِنِكُمْ لَعَلَّكُمْ تُسْـَٔلُونَ', 'لا تركضوا وارجعوا إلى ما أترفتم فيه ومسكنكم لعلكم تسلون', NULL, 323, 'local:hafs-text.json'),
  ('hafs-21-14', 'hafs', 21, 14, 'قَالُوا۟ يَٰوَيْلَنَآ إِنَّا كُنَّا ظَٰلِمِينَ', 'قالوا يويلنا إنا كنا ظلمين', NULL, 323, 'local:hafs-text.json'),
  ('hafs-21-15', 'hafs', 21, 15, 'فَمَا زَالَت تِّلْكَ دَعْوَىٰهُمْ حَتَّىٰ جَعَلْنَٰهُمْ حَصِيدًا خَٰمِدِينَ', 'فما زالت تلك دعوىهم حتى جعلنهم حصيدا خمدين', NULL, 323, 'local:hafs-text.json'),
  ('hafs-21-16', 'hafs', 21, 16, 'وَمَا خَلَقْنَا ٱلسَّمَآءَ وَٱلْأَرْضَ وَمَا بَيْنَهُمَا لَٰعِبِينَ', 'وما خلقنا السماء والأرض وما بينهما لعبين', NULL, 323, 'local:hafs-text.json'),
  ('hafs-21-17', 'hafs', 21, 17, 'لَوْ أَرَدْنَآ أَن نَّتَّخِذَ لَهْوًۭا لَّٱتَّخَذْنَٰهُ مِن لَّدُنَّآ إِن كُنَّا فَٰعِلِينَ', 'لو أردنا أن نتخذ لهوا لاتخذنه من لدنا إن كنا فعلين', NULL, 323, 'local:hafs-text.json'),
  ('hafs-21-18', 'hafs', 21, 18, 'بَلْ نَقْذِفُ بِٱلْحَقِّ عَلَى ٱلْبَٰطِلِ فَيَدْمَغُهُۥ فَإِذَا هُوَ زَاهِقٌۭ ۚ وَلَكُمُ ٱلْوَيْلُ مِمَّا تَصِفُونَ', 'بل نقذف بالحق على البطل فيدمغه فإذا هو زاهق  ولكم الويل مما تصفون', NULL, 323, 'local:hafs-text.json'),
  ('hafs-21-19', 'hafs', 21, 19, 'وَلَهُۥ مَن فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ ۚ وَمَنْ عِندَهُۥ لَا يَسْتَكْبِرُونَ عَنْ عِبَادَتِهِۦ وَلَا يَسْتَحْسِرُونَ', 'وله من فى السموت والأرض  ومن عنده لا يستكبرون عن عبادته ولا يستحسرون', NULL, 323, 'local:hafs-text.json'),
  ('hafs-21-20', 'hafs', 21, 20, 'يُسَبِّحُونَ ٱلَّيْلَ وَٱلنَّهَارَ لَا يَفْتُرُونَ', 'يسبحون اليل والنهار لا يفترون', NULL, 323, 'local:hafs-text.json'),
  ('hafs-21-21', 'hafs', 21, 21, 'أَمِ ٱتَّخَذُوٓا۟ ءَالِهَةًۭ مِّنَ ٱلْأَرْضِ هُمْ يُنشِرُونَ', 'أم اتخذوا ءالهة من الأرض هم ينشرون', NULL, 323, 'local:hafs-text.json'),
  ('hafs-21-22', 'hafs', 21, 22, 'لَوْ كَانَ فِيهِمَآ ءَالِهَةٌ إِلَّا ٱللَّهُ لَفَسَدَتَا ۚ فَسُبْحَٰنَ ٱللَّهِ رَبِّ ٱلْعَرْشِ عَمَّا يَصِفُونَ', 'لو كان فيهما ءالهة إلا الله لفسدتا  فسبحن الله رب العرش عما يصفون', NULL, 323, 'local:hafs-text.json'),
  ('hafs-21-23', 'hafs', 21, 23, 'لَا يُسْـَٔلُ عَمَّا يَفْعَلُ وَهُمْ يُسْـَٔلُونَ', 'لا يسل عما يفعل وهم يسلون', NULL, 323, 'local:hafs-text.json'),
  ('hafs-21-24', 'hafs', 21, 24, 'أَمِ ٱتَّخَذُوا۟ مِن دُونِهِۦٓ ءَالِهَةًۭ ۖ قُلْ هَاتُوا۟ بُرْهَٰنَكُمْ ۖ هَٰذَا ذِكْرُ مَن مَّعِىَ وَذِكْرُ مَن قَبْلِى ۗ بَلْ أَكْثَرُهُمْ لَا يَعْلَمُونَ ٱلْحَقَّ ۖ فَهُم مُّعْرِضُونَ', 'أم اتخذوا من دونه ءالهة  قل هاتوا برهنكم  هذا ذكر من معى وذكر من قبلى  بل أكثرهم لا يعلمون الحق  فهم معرضون', NULL, 323, 'local:hafs-text.json'),
  ('hafs-21-25', 'hafs', 21, 25, 'وَمَآ أَرْسَلْنَا مِن قَبْلِكَ مِن رَّسُولٍ إِلَّا نُوحِىٓ إِلَيْهِ أَنَّهُۥ لَآ إِلَٰهَ إِلَّآ أَنَا۠ فَٱعْبُدُونِ', 'وما أرسلنا من قبلك من رسول إلا نوحى إليه أنه لا إله إلا أنا فاعبدون', NULL, 324, 'local:hafs-text.json'),
  ('hafs-21-26', 'hafs', 21, 26, 'وَقَالُوا۟ ٱتَّخَذَ ٱلرَّحْمَٰنُ وَلَدًۭا ۗ سُبْحَٰنَهُۥ ۚ بَلْ عِبَادٌۭ مُّكْرَمُونَ', 'وقالوا اتخذ الرحمن ولدا  سبحنه  بل عباد مكرمون', NULL, 324, 'local:hafs-text.json'),
  ('hafs-21-27', 'hafs', 21, 27, 'لَا يَسْبِقُونَهُۥ بِٱلْقَوْلِ وَهُم بِأَمْرِهِۦ يَعْمَلُونَ', 'لا يسبقونه بالقول وهم بأمره يعملون', NULL, 324, 'local:hafs-text.json'),
  ('hafs-21-28', 'hafs', 21, 28, 'يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ وَلَا يَشْفَعُونَ إِلَّا لِمَنِ ٱرْتَضَىٰ وَهُم مِّنْ خَشْيَتِهِۦ مُشْفِقُونَ', 'يعلم ما بين أيديهم وما خلفهم ولا يشفعون إلا لمن ارتضى وهم من خشيته مشفقون', NULL, 324, 'local:hafs-text.json'),
  ('hafs-21-29', 'hafs', 21, 29, '۞ وَمَن يَقُلْ مِنْهُمْ إِنِّىٓ إِلَٰهٌۭ مِّن دُونِهِۦ فَذَٰلِكَ نَجْزِيهِ جَهَنَّمَ ۚ كَذَٰلِكَ نَجْزِى ٱلظَّٰلِمِينَ', 'ومن يقل منهم إنى إله من دونه فذلك نجزيه جهنم  كذلك نجزى الظلمين', NULL, 324, 'local:hafs-text.json'),
  ('hafs-21-30', 'hafs', 21, 30, 'أَوَلَمْ يَرَ ٱلَّذِينَ كَفَرُوٓا۟ أَنَّ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ كَانَتَا رَتْقًۭا فَفَتَقْنَٰهُمَا ۖ وَجَعَلْنَا مِنَ ٱلْمَآءِ كُلَّ شَىْءٍ حَىٍّ ۖ أَفَلَا يُؤْمِنُونَ', 'أولم ير الذين كفروا أن السموت والأرض كانتا رتقا ففتقنهما  وجعلنا من الماء كل شىء حى  أفلا يؤمنون', NULL, 324, 'local:hafs-text.json'),
  ('hafs-21-31', 'hafs', 21, 31, 'وَجَعَلْنَا فِى ٱلْأَرْضِ رَوَٰسِىَ أَن تَمِيدَ بِهِمْ وَجَعَلْنَا فِيهَا فِجَاجًۭا سُبُلًۭا لَّعَلَّهُمْ يَهْتَدُونَ', 'وجعلنا فى الأرض روسى أن تميد بهم وجعلنا فيها فجاجا سبلا لعلهم يهتدون', NULL, 324, 'local:hafs-text.json'),
  ('hafs-21-32', 'hafs', 21, 32, 'وَجَعَلْنَا ٱلسَّمَآءَ سَقْفًۭا مَّحْفُوظًۭا ۖ وَهُمْ عَنْ ءَايَٰتِهَا مُعْرِضُونَ', 'وجعلنا السماء سقفا محفوظا  وهم عن ءايتها معرضون', NULL, 324, 'local:hafs-text.json'),
  ('hafs-21-33', 'hafs', 21, 33, 'وَهُوَ ٱلَّذِى خَلَقَ ٱلَّيْلَ وَٱلنَّهَارَ وَٱلشَّمْسَ وَٱلْقَمَرَ ۖ كُلٌّۭ فِى فَلَكٍۢ يَسْبَحُونَ', 'وهو الذى خلق اليل والنهار والشمس والقمر  كل فى فلك يسبحون', NULL, 324, 'local:hafs-text.json'),
  ('hafs-21-34', 'hafs', 21, 34, 'وَمَا جَعَلْنَا لِبَشَرٍۢ مِّن قَبْلِكَ ٱلْخُلْدَ ۖ أَفَإِي۟ن مِّتَّ فَهُمُ ٱلْخَٰلِدُونَ', 'وما جعلنا لبشر من قبلك الخلد  أفإين مت فهم الخلدون', NULL, 324, 'local:hafs-text.json'),
  ('hafs-21-35', 'hafs', 21, 35, 'كُلُّ نَفْسٍۢ ذَآئِقَةُ ٱلْمَوْتِ ۗ وَنَبْلُوكُم بِٱلشَّرِّ وَٱلْخَيْرِ فِتْنَةًۭ ۖ وَإِلَيْنَا تُرْجَعُونَ', 'كل نفس ذائقة الموت  ونبلوكم بالشر والخير فتنة  وإلينا ترجعون', NULL, 324, 'local:hafs-text.json'),
  ('hafs-21-36', 'hafs', 21, 36, 'وَإِذَا رَءَاكَ ٱلَّذِينَ كَفَرُوٓا۟ إِن يَتَّخِذُونَكَ إِلَّا هُزُوًا أَهَٰذَا ٱلَّذِى يَذْكُرُ ءَالِهَتَكُمْ وَهُم بِذِكْرِ ٱلرَّحْمَٰنِ هُمْ كَٰفِرُونَ', 'وإذا رءاك الذين كفروا إن يتخذونك إلا هزوا أهذا الذى يذكر ءالهتكم وهم بذكر الرحمن هم كفرون', NULL, 325, 'local:hafs-text.json'),
  ('hafs-21-37', 'hafs', 21, 37, 'خُلِقَ ٱلْإِنسَٰنُ مِنْ عَجَلٍۢ ۚ سَأُو۟رِيكُمْ ءَايَٰتِى فَلَا تَسْتَعْجِلُونِ', 'خلق الإنسن من عجل  سأوريكم ءايتى فلا تستعجلون', NULL, 325, 'local:hafs-text.json'),
  ('hafs-21-38', 'hafs', 21, 38, 'وَيَقُولُونَ مَتَىٰ هَٰذَا ٱلْوَعْدُ إِن كُنتُمْ صَٰدِقِينَ', 'ويقولون متى هذا الوعد إن كنتم صدقين', NULL, 325, 'local:hafs-text.json'),
  ('hafs-21-39', 'hafs', 21, 39, 'لَوْ يَعْلَمُ ٱلَّذِينَ كَفَرُوا۟ حِينَ لَا يَكُفُّونَ عَن وُجُوهِهِمُ ٱلنَّارَ وَلَا عَن ظُهُورِهِمْ وَلَا هُمْ يُنصَرُونَ', 'لو يعلم الذين كفروا حين لا يكفون عن وجوههم النار ولا عن ظهورهم ولا هم ينصرون', NULL, 325, 'local:hafs-text.json'),
  ('hafs-21-40', 'hafs', 21, 40, 'بَلْ تَأْتِيهِم بَغْتَةًۭ فَتَبْهَتُهُمْ فَلَا يَسْتَطِيعُونَ رَدَّهَا وَلَا هُمْ يُنظَرُونَ', 'بل تأتيهم بغتة فتبهتهم فلا يستطيعون ردها ولا هم ينظرون', NULL, 325, 'local:hafs-text.json'),
  ('hafs-21-41', 'hafs', 21, 41, 'وَلَقَدِ ٱسْتُهْزِئَ بِرُسُلٍۢ مِّن قَبْلِكَ فَحَاقَ بِٱلَّذِينَ سَخِرُوا۟ مِنْهُم مَّا كَانُوا۟ بِهِۦ يَسْتَهْزِءُونَ', 'ولقد استهزئ برسل من قبلك فحاق بالذين سخروا منهم ما كانوا به يستهزءون', NULL, 325, 'local:hafs-text.json'),
  ('hafs-21-42', 'hafs', 21, 42, 'قُلْ مَن يَكْلَؤُكُم بِٱلَّيْلِ وَٱلنَّهَارِ مِنَ ٱلرَّحْمَٰنِ ۗ بَلْ هُمْ عَن ذِكْرِ رَبِّهِم مُّعْرِضُونَ', 'قل من يكلؤكم باليل والنهار من الرحمن  بل هم عن ذكر ربهم معرضون', NULL, 325, 'local:hafs-text.json'),
  ('hafs-21-43', 'hafs', 21, 43, 'أَمْ لَهُمْ ءَالِهَةٌۭ تَمْنَعُهُم مِّن دُونِنَا ۚ لَا يَسْتَطِيعُونَ نَصْرَ أَنفُسِهِمْ وَلَا هُم مِّنَّا يُصْحَبُونَ', 'أم لهم ءالهة تمنعهم من دوننا  لا يستطيعون نصر أنفسهم ولا هم منا يصحبون', NULL, 325, 'local:hafs-text.json'),
  ('hafs-21-44', 'hafs', 21, 44, 'بَلْ مَتَّعْنَا هَٰٓؤُلَآءِ وَءَابَآءَهُمْ حَتَّىٰ طَالَ عَلَيْهِمُ ٱلْعُمُرُ ۗ أَفَلَا يَرَوْنَ أَنَّا نَأْتِى ٱلْأَرْضَ نَنقُصُهَا مِنْ أَطْرَافِهَآ ۚ أَفَهُمُ ٱلْغَٰلِبُونَ', 'بل متعنا هؤلاء وءاباءهم حتى طال عليهم العمر  أفلا يرون أنا نأتى الأرض ننقصها من أطرافها  أفهم الغلبون', NULL, 325, 'local:hafs-text.json'),
  ('hafs-21-45', 'hafs', 21, 45, 'قُلْ إِنَّمَآ أُنذِرُكُم بِٱلْوَحْىِ ۚ وَلَا يَسْمَعُ ٱلصُّمُّ ٱلدُّعَآءَ إِذَا مَا يُنذَرُونَ', 'قل إنما أنذركم بالوحى  ولا يسمع الصم الدعاء إذا ما ينذرون', NULL, 326, 'local:hafs-text.json'),
  ('hafs-21-46', 'hafs', 21, 46, 'وَلَئِن مَّسَّتْهُمْ نَفْحَةٌۭ مِّنْ عَذَابِ رَبِّكَ لَيَقُولُنَّ يَٰوَيْلَنَآ إِنَّا كُنَّا ظَٰلِمِينَ', 'ولئن مستهم نفحة من عذاب ربك ليقولن يويلنا إنا كنا ظلمين', NULL, 326, 'local:hafs-text.json'),
  ('hafs-21-47', 'hafs', 21, 47, 'وَنَضَعُ ٱلْمَوَٰزِينَ ٱلْقِسْطَ لِيَوْمِ ٱلْقِيَٰمَةِ فَلَا تُظْلَمُ نَفْسٌۭ شَيْـًۭٔا ۖ وَإِن كَانَ مِثْقَالَ حَبَّةٍۢ مِّنْ خَرْدَلٍ أَتَيْنَا بِهَا ۗ وَكَفَىٰ بِنَا حَٰسِبِينَ', 'ونضع الموزين القسط ليوم القيمة فلا تظلم نفس شيا  وإن كان مثقال حبة من خردل أتينا بها  وكفى بنا حسبين', NULL, 326, 'local:hafs-text.json'),
  ('hafs-21-48', 'hafs', 21, 48, 'وَلَقَدْ ءَاتَيْنَا مُوسَىٰ وَهَٰرُونَ ٱلْفُرْقَانَ وَضِيَآءًۭ وَذِكْرًۭا لِّلْمُتَّقِينَ', 'ولقد ءاتينا موسى وهرون الفرقان وضياء وذكرا للمتقين', NULL, 326, 'local:hafs-text.json'),
  ('hafs-21-49', 'hafs', 21, 49, 'ٱلَّذِينَ يَخْشَوْنَ رَبَّهُم بِٱلْغَيْبِ وَهُم مِّنَ ٱلسَّاعَةِ مُشْفِقُونَ', 'الذين يخشون ربهم بالغيب وهم من الساعة مشفقون', NULL, 326, 'local:hafs-text.json'),
  ('hafs-21-50', 'hafs', 21, 50, 'وَهَٰذَا ذِكْرٌۭ مُّبَارَكٌ أَنزَلْنَٰهُ ۚ أَفَأَنتُمْ لَهُۥ مُنكِرُونَ', 'وهذا ذكر مبارك أنزلنه  أفأنتم له منكرون', NULL, 326, 'local:hafs-text.json'),
  ('hafs-21-51', 'hafs', 21, 51, '۞ وَلَقَدْ ءَاتَيْنَآ إِبْرَٰهِيمَ رُشْدَهُۥ مِن قَبْلُ وَكُنَّا بِهِۦ عَٰلِمِينَ', 'ولقد ءاتينا إبرهيم رشده من قبل وكنا به علمين', NULL, 326, 'local:hafs-text.json'),
  ('hafs-21-52', 'hafs', 21, 52, 'إِذْ قَالَ لِأَبِيهِ وَقَوْمِهِۦ مَا هَٰذِهِ ٱلتَّمَاثِيلُ ٱلَّتِىٓ أَنتُمْ لَهَا عَٰكِفُونَ', 'إذ قال لأبيه وقومه ما هذه التماثيل التى أنتم لها عكفون', NULL, 326, 'local:hafs-text.json'),
  ('hafs-21-53', 'hafs', 21, 53, 'قَالُوا۟ وَجَدْنَآ ءَابَآءَنَا لَهَا عَٰبِدِينَ', 'قالوا وجدنا ءاباءنا لها عبدين', NULL, 326, 'local:hafs-text.json'),
  ('hafs-21-54', 'hafs', 21, 54, 'قَالَ لَقَدْ كُنتُمْ أَنتُمْ وَءَابَآؤُكُمْ فِى ضَلَٰلٍۢ مُّبِينٍۢ', 'قال لقد كنتم أنتم وءاباؤكم فى ضلل مبين', NULL, 326, 'local:hafs-text.json'),
  ('hafs-21-55', 'hafs', 21, 55, 'قَالُوٓا۟ أَجِئْتَنَا بِٱلْحَقِّ أَمْ أَنتَ مِنَ ٱللَّٰعِبِينَ', 'قالوا أجئتنا بالحق أم أنت من اللعبين', NULL, 326, 'local:hafs-text.json'),
  ('hafs-21-56', 'hafs', 21, 56, 'قَالَ بَل رَّبُّكُمْ رَبُّ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ ٱلَّذِى فَطَرَهُنَّ وَأَنَا۠ عَلَىٰ ذَٰلِكُم مِّنَ ٱلشَّٰهِدِينَ', 'قال بل ربكم رب السموت والأرض الذى فطرهن وأنا على ذلكم من الشهدين', NULL, 326, 'local:hafs-text.json'),
  ('hafs-21-57', 'hafs', 21, 57, 'وَتَٱللَّهِ لَأَكِيدَنَّ أَصْنَٰمَكُم بَعْدَ أَن تُوَلُّوا۟ مُدْبِرِينَ', 'وتالله لأكيدن أصنمكم بعد أن تولوا مدبرين', NULL, 326, 'local:hafs-text.json'),
  ('hafs-21-58', 'hafs', 21, 58, 'فَجَعَلَهُمْ جُذَٰذًا إِلَّا كَبِيرًۭا لَّهُمْ لَعَلَّهُمْ إِلَيْهِ يَرْجِعُونَ', 'فجعلهم جذذا إلا كبيرا لهم لعلهم إليه يرجعون', NULL, 327, 'local:hafs-text.json'),
  ('hafs-21-59', 'hafs', 21, 59, 'قَالُوا۟ مَن فَعَلَ هَٰذَا بِـَٔالِهَتِنَآ إِنَّهُۥ لَمِنَ ٱلظَّٰلِمِينَ', 'قالوا من فعل هذا بالهتنا إنه لمن الظلمين', NULL, 327, 'local:hafs-text.json'),
  ('hafs-21-60', 'hafs', 21, 60, 'قَالُوا۟ سَمِعْنَا فَتًۭى يَذْكُرُهُمْ يُقَالُ لَهُۥٓ إِبْرَٰهِيمُ', 'قالوا سمعنا فتى يذكرهم يقال له إبرهيم', NULL, 327, 'local:hafs-text.json'),
  ('hafs-21-61', 'hafs', 21, 61, 'قَالُوا۟ فَأْتُوا۟ بِهِۦ عَلَىٰٓ أَعْيُنِ ٱلنَّاسِ لَعَلَّهُمْ يَشْهَدُونَ', 'قالوا فأتوا به على أعين الناس لعلهم يشهدون', NULL, 327, 'local:hafs-text.json'),
  ('hafs-21-62', 'hafs', 21, 62, 'قَالُوٓا۟ ءَأَنتَ فَعَلْتَ هَٰذَا بِـَٔالِهَتِنَا يَٰٓإِبْرَٰهِيمُ', 'قالوا ءأنت فعلت هذا بالهتنا يإبرهيم', NULL, 327, 'local:hafs-text.json'),
  ('hafs-21-63', 'hafs', 21, 63, 'قَالَ بَلْ فَعَلَهُۥ كَبِيرُهُمْ هَٰذَا فَسْـَٔلُوهُمْ إِن كَانُوا۟ يَنطِقُونَ', 'قال بل فعله كبيرهم هذا فسلوهم إن كانوا ينطقون', NULL, 327, 'local:hafs-text.json'),
  ('hafs-21-64', 'hafs', 21, 64, 'فَرَجَعُوٓا۟ إِلَىٰٓ أَنفُسِهِمْ فَقَالُوٓا۟ إِنَّكُمْ أَنتُمُ ٱلظَّٰلِمُونَ', 'فرجعوا إلى أنفسهم فقالوا إنكم أنتم الظلمون', NULL, 327, 'local:hafs-text.json'),
  ('hafs-21-65', 'hafs', 21, 65, 'ثُمَّ نُكِسُوا۟ عَلَىٰ رُءُوسِهِمْ لَقَدْ عَلِمْتَ مَا هَٰٓؤُلَآءِ يَنطِقُونَ', 'ثم نكسوا على رءوسهم لقد علمت ما هؤلاء ينطقون', NULL, 327, 'local:hafs-text.json'),
  ('hafs-21-66', 'hafs', 21, 66, 'قَالَ أَفَتَعْبُدُونَ مِن دُونِ ٱللَّهِ مَا لَا يَنفَعُكُمْ شَيْـًۭٔا وَلَا يَضُرُّكُمْ', 'قال أفتعبدون من دون الله ما لا ينفعكم شيا ولا يضركم', NULL, 327, 'local:hafs-text.json'),
  ('hafs-21-67', 'hafs', 21, 67, 'أُفٍّۢ لَّكُمْ وَلِمَا تَعْبُدُونَ مِن دُونِ ٱللَّهِ ۖ أَفَلَا تَعْقِلُونَ', 'أف لكم ولما تعبدون من دون الله  أفلا تعقلون', NULL, 327, 'local:hafs-text.json'),
  ('hafs-21-68', 'hafs', 21, 68, 'قَالُوا۟ حَرِّقُوهُ وَٱنصُرُوٓا۟ ءَالِهَتَكُمْ إِن كُنتُمْ فَٰعِلِينَ', 'قالوا حرقوه وانصروا ءالهتكم إن كنتم فعلين', NULL, 327, 'local:hafs-text.json'),
  ('hafs-21-69', 'hafs', 21, 69, 'قُلْنَا يَٰنَارُ كُونِى بَرْدًۭا وَسَلَٰمًا عَلَىٰٓ إِبْرَٰهِيمَ', 'قلنا ينار كونى بردا وسلما على إبرهيم', NULL, 327, 'local:hafs-text.json'),
  ('hafs-21-70', 'hafs', 21, 70, 'وَأَرَادُوا۟ بِهِۦ كَيْدًۭا فَجَعَلْنَٰهُمُ ٱلْأَخْسَرِينَ', 'وأرادوا به كيدا فجعلنهم الأخسرين', NULL, 327, 'local:hafs-text.json'),
  ('hafs-21-71', 'hafs', 21, 71, 'وَنَجَّيْنَٰهُ وَلُوطًا إِلَى ٱلْأَرْضِ ٱلَّتِى بَٰرَكْنَا فِيهَا لِلْعَٰلَمِينَ', 'ونجينه ولوطا إلى الأرض التى بركنا فيها للعلمين', NULL, 327, 'local:hafs-text.json'),
  ('hafs-21-72', 'hafs', 21, 72, 'وَوَهَبْنَا لَهُۥٓ إِسْحَٰقَ وَيَعْقُوبَ نَافِلَةًۭ ۖ وَكُلًّۭا جَعَلْنَا صَٰلِحِينَ', 'ووهبنا له إسحق ويعقوب نافلة  وكلا جعلنا صلحين', NULL, 327, 'local:hafs-text.json'),
  ('hafs-21-73', 'hafs', 21, 73, 'وَجَعَلْنَٰهُمْ أَئِمَّةًۭ يَهْدُونَ بِأَمْرِنَا وَأَوْحَيْنَآ إِلَيْهِمْ فِعْلَ ٱلْخَيْرَٰتِ وَإِقَامَ ٱلصَّلَوٰةِ وَإِيتَآءَ ٱلزَّكَوٰةِ ۖ وَكَانُوا۟ لَنَا عَٰبِدِينَ', 'وجعلنهم أئمة يهدون بأمرنا وأوحينا إليهم فعل الخيرت وإقام الصلوة وإيتاء الزكوة  وكانوا لنا عبدين', NULL, 328, 'local:hafs-text.json'),
  ('hafs-21-74', 'hafs', 21, 74, 'وَلُوطًا ءَاتَيْنَٰهُ حُكْمًۭا وَعِلْمًۭا وَنَجَّيْنَٰهُ مِنَ ٱلْقَرْيَةِ ٱلَّتِى كَانَت تَّعْمَلُ ٱلْخَبَٰٓئِثَ ۗ إِنَّهُمْ كَانُوا۟ قَوْمَ سَوْءٍۢ فَٰسِقِينَ', 'ولوطا ءاتينه حكما وعلما ونجينه من القرية التى كانت تعمل الخبئث  إنهم كانوا قوم سوء فسقين', NULL, 328, 'local:hafs-text.json'),
  ('hafs-21-75', 'hafs', 21, 75, 'وَأَدْخَلْنَٰهُ فِى رَحْمَتِنَآ ۖ إِنَّهُۥ مِنَ ٱلصَّٰلِحِينَ', 'وأدخلنه فى رحمتنا  إنه من الصلحين', NULL, 328, 'local:hafs-text.json'),
  ('hafs-21-76', 'hafs', 21, 76, 'وَنُوحًا إِذْ نَادَىٰ مِن قَبْلُ فَٱسْتَجَبْنَا لَهُۥ فَنَجَّيْنَٰهُ وَأَهْلَهُۥ مِنَ ٱلْكَرْبِ ٱلْعَظِيمِ', 'ونوحا إذ نادى من قبل فاستجبنا له فنجينه وأهله من الكرب العظيم', NULL, 328, 'local:hafs-text.json'),
  ('hafs-21-77', 'hafs', 21, 77, 'وَنَصَرْنَٰهُ مِنَ ٱلْقَوْمِ ٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَٰتِنَآ ۚ إِنَّهُمْ كَانُوا۟ قَوْمَ سَوْءٍۢ فَأَغْرَقْنَٰهُمْ أَجْمَعِينَ', 'ونصرنه من القوم الذين كذبوا بايتنا  إنهم كانوا قوم سوء فأغرقنهم أجمعين', NULL, 328, 'local:hafs-text.json'),
  ('hafs-21-78', 'hafs', 21, 78, 'وَدَاوُۥدَ وَسُلَيْمَٰنَ إِذْ يَحْكُمَانِ فِى ٱلْحَرْثِ إِذْ نَفَشَتْ فِيهِ غَنَمُ ٱلْقَوْمِ وَكُنَّا لِحُكْمِهِمْ شَٰهِدِينَ', 'وداود وسليمن إذ يحكمان فى الحرث إذ نفشت فيه غنم القوم وكنا لحكمهم شهدين', NULL, 328, 'local:hafs-text.json'),
  ('hafs-21-79', 'hafs', 21, 79, 'فَفَهَّمْنَٰهَا سُلَيْمَٰنَ ۚ وَكُلًّا ءَاتَيْنَا حُكْمًۭا وَعِلْمًۭا ۚ وَسَخَّرْنَا مَعَ دَاوُۥدَ ٱلْجِبَالَ يُسَبِّحْنَ وَٱلطَّيْرَ ۚ وَكُنَّا فَٰعِلِينَ', 'ففهمنها سليمن  وكلا ءاتينا حكما وعلما  وسخرنا مع داود الجبال يسبحن والطير  وكنا فعلين', NULL, 328, 'local:hafs-text.json'),
  ('hafs-21-80', 'hafs', 21, 80, 'وَعَلَّمْنَٰهُ صَنْعَةَ لَبُوسٍۢ لَّكُمْ لِتُحْصِنَكُم مِّنۢ بَأْسِكُمْ ۖ فَهَلْ أَنتُمْ شَٰكِرُونَ', 'وعلمنه صنعة لبوس لكم لتحصنكم من بأسكم  فهل أنتم شكرون', NULL, 328, 'local:hafs-text.json'),
  ('hafs-21-81', 'hafs', 21, 81, 'وَلِسُلَيْمَٰنَ ٱلرِّيحَ عَاصِفَةًۭ تَجْرِى بِأَمْرِهِۦٓ إِلَى ٱلْأَرْضِ ٱلَّتِى بَٰرَكْنَا فِيهَا ۚ وَكُنَّا بِكُلِّ شَىْءٍ عَٰلِمِينَ', 'ولسليمن الريح عاصفة تجرى بأمره إلى الأرض التى بركنا فيها  وكنا بكل شىء علمين', NULL, 328, 'local:hafs-text.json'),
  ('hafs-21-82', 'hafs', 21, 82, 'وَمِنَ ٱلشَّيَٰطِينِ مَن يَغُوصُونَ لَهُۥ وَيَعْمَلُونَ عَمَلًۭا دُونَ ذَٰلِكَ ۖ وَكُنَّا لَهُمْ حَٰفِظِينَ', 'ومن الشيطين من يغوصون له ويعملون عملا دون ذلك  وكنا لهم حفظين', NULL, 329, 'local:hafs-text.json'),
  ('hafs-21-83', 'hafs', 21, 83, '۞ وَأَيُّوبَ إِذْ نَادَىٰ رَبَّهُۥٓ أَنِّى مَسَّنِىَ ٱلضُّرُّ وَأَنتَ أَرْحَمُ ٱلرَّٰحِمِينَ', 'وأيوب إذ نادى ربه أنى مسنى الضر وأنت أرحم الرحمين', NULL, 329, 'local:hafs-text.json'),
  ('hafs-21-84', 'hafs', 21, 84, 'فَٱسْتَجَبْنَا لَهُۥ فَكَشَفْنَا مَا بِهِۦ مِن ضُرٍّۢ ۖ وَءَاتَيْنَٰهُ أَهْلَهُۥ وَمِثْلَهُم مَّعَهُمْ رَحْمَةًۭ مِّنْ عِندِنَا وَذِكْرَىٰ لِلْعَٰبِدِينَ', 'فاستجبنا له فكشفنا ما به من ضر  وءاتينه أهله ومثلهم معهم رحمة من عندنا وذكرى للعبدين', NULL, 329, 'local:hafs-text.json'),
  ('hafs-21-85', 'hafs', 21, 85, 'وَإِسْمَٰعِيلَ وَإِدْرِيسَ وَذَا ٱلْكِفْلِ ۖ كُلٌّۭ مِّنَ ٱلصَّٰبِرِينَ', 'وإسمعيل وإدريس وذا الكفل  كل من الصبرين', NULL, 329, 'local:hafs-text.json'),
  ('hafs-21-86', 'hafs', 21, 86, 'وَأَدْخَلْنَٰهُمْ فِى رَحْمَتِنَآ ۖ إِنَّهُم مِّنَ ٱلصَّٰلِحِينَ', 'وأدخلنهم فى رحمتنا  إنهم من الصلحين', NULL, 329, 'local:hafs-text.json'),
  ('hafs-21-87', 'hafs', 21, 87, 'وَذَا ٱلنُّونِ إِذ ذَّهَبَ مُغَٰضِبًۭا فَظَنَّ أَن لَّن نَّقْدِرَ عَلَيْهِ فَنَادَىٰ فِى ٱلظُّلُمَٰتِ أَن لَّآ إِلَٰهَ إِلَّآ أَنتَ سُبْحَٰنَكَ إِنِّى كُنتُ مِنَ ٱلظَّٰلِمِينَ', 'وذا النون إذ ذهب مغضبا فظن أن لن نقدر عليه فنادى فى الظلمت أن لا إله إلا أنت سبحنك إنى كنت من الظلمين', NULL, 329, 'local:hafs-text.json'),
  ('hafs-21-88', 'hafs', 21, 88, 'فَٱسْتَجَبْنَا لَهُۥ وَنَجَّيْنَٰهُ مِنَ ٱلْغَمِّ ۚ وَكَذَٰلِكَ نُۨجِى ٱلْمُؤْمِنِينَ', 'فاستجبنا له ونجينه من الغم  وكذلك نجى المؤمنين', NULL, 329, 'local:hafs-text.json'),
  ('hafs-21-89', 'hafs', 21, 89, 'وَزَكَرِيَّآ إِذْ نَادَىٰ رَبَّهُۥ رَبِّ لَا تَذَرْنِى فَرْدًۭا وَأَنتَ خَيْرُ ٱلْوَٰرِثِينَ', 'وزكريا إذ نادى ربه رب لا تذرنى فردا وأنت خير الورثين', NULL, 329, 'local:hafs-text.json'),
  ('hafs-21-90', 'hafs', 21, 90, 'فَٱسْتَجَبْنَا لَهُۥ وَوَهَبْنَا لَهُۥ يَحْيَىٰ وَأَصْلَحْنَا لَهُۥ زَوْجَهُۥٓ ۚ إِنَّهُمْ كَانُوا۟ يُسَٰرِعُونَ فِى ٱلْخَيْرَٰتِ وَيَدْعُونَنَا رَغَبًۭا وَرَهَبًۭا ۖ وَكَانُوا۟ لَنَا خَٰشِعِينَ', 'فاستجبنا له ووهبنا له يحيى وأصلحنا له زوجه  إنهم كانوا يسرعون فى الخيرت ويدعوننا رغبا ورهبا  وكانوا لنا خشعين', NULL, 329, 'local:hafs-text.json'),
  ('hafs-21-91', 'hafs', 21, 91, 'وَٱلَّتِىٓ أَحْصَنَتْ فَرْجَهَا فَنَفَخْنَا فِيهَا مِن رُّوحِنَا وَجَعَلْنَٰهَا وَٱبْنَهَآ ءَايَةًۭ لِّلْعَٰلَمِينَ', 'والتى أحصنت فرجها فنفخنا فيها من روحنا وجعلنها وابنها ءاية للعلمين', NULL, 330, 'local:hafs-text.json'),
  ('hafs-21-92', 'hafs', 21, 92, 'إِنَّ هَٰذِهِۦٓ أُمَّتُكُمْ أُمَّةًۭ وَٰحِدَةًۭ وَأَنَا۠ رَبُّكُمْ فَٱعْبُدُونِ', 'إن هذه أمتكم أمة وحدة وأنا ربكم فاعبدون', NULL, 330, 'local:hafs-text.json'),
  ('hafs-21-93', 'hafs', 21, 93, 'وَتَقَطَّعُوٓا۟ أَمْرَهُم بَيْنَهُمْ ۖ كُلٌّ إِلَيْنَا رَٰجِعُونَ', 'وتقطعوا أمرهم بينهم  كل إلينا رجعون', NULL, 330, 'local:hafs-text.json'),
  ('hafs-21-94', 'hafs', 21, 94, 'فَمَن يَعْمَلْ مِنَ ٱلصَّٰلِحَٰتِ وَهُوَ مُؤْمِنٌۭ فَلَا كُفْرَانَ لِسَعْيِهِۦ وَإِنَّا لَهُۥ كَٰتِبُونَ', 'فمن يعمل من الصلحت وهو مؤمن فلا كفران لسعيه وإنا له كتبون', NULL, 330, 'local:hafs-text.json'),
  ('hafs-21-95', 'hafs', 21, 95, 'وَحَرَٰمٌ عَلَىٰ قَرْيَةٍ أَهْلَكْنَٰهَآ أَنَّهُمْ لَا يَرْجِعُونَ', 'وحرم على قرية أهلكنها أنهم لا يرجعون', NULL, 330, 'local:hafs-text.json'),
  ('hafs-21-96', 'hafs', 21, 96, 'حَتَّىٰٓ إِذَا فُتِحَتْ يَأْجُوجُ وَمَأْجُوجُ وَهُم مِّن كُلِّ حَدَبٍۢ يَنسِلُونَ', 'حتى إذا فتحت يأجوج ومأجوج وهم من كل حدب ينسلون', NULL, 330, 'local:hafs-text.json'),
  ('hafs-21-97', 'hafs', 21, 97, 'وَٱقْتَرَبَ ٱلْوَعْدُ ٱلْحَقُّ فَإِذَا هِىَ شَٰخِصَةٌ أَبْصَٰرُ ٱلَّذِينَ كَفَرُوا۟ يَٰوَيْلَنَا قَدْ كُنَّا فِى غَفْلَةٍۢ مِّنْ هَٰذَا بَلْ كُنَّا ظَٰلِمِينَ', 'واقترب الوعد الحق فإذا هى شخصة أبصر الذين كفروا يويلنا قد كنا فى غفلة من هذا بل كنا ظلمين', NULL, 330, 'local:hafs-text.json'),
  ('hafs-21-98', 'hafs', 21, 98, 'إِنَّكُمْ وَمَا تَعْبُدُونَ مِن دُونِ ٱللَّهِ حَصَبُ جَهَنَّمَ أَنتُمْ لَهَا وَٰرِدُونَ', 'إنكم وما تعبدون من دون الله حصب جهنم أنتم لها وردون', NULL, 330, 'local:hafs-text.json'),
  ('hafs-21-99', 'hafs', 21, 99, 'لَوْ كَانَ هَٰٓؤُلَآءِ ءَالِهَةًۭ مَّا وَرَدُوهَا ۖ وَكُلٌّۭ فِيهَا خَٰلِدُونَ', 'لو كان هؤلاء ءالهة ما وردوها  وكل فيها خلدون', NULL, 330, 'local:hafs-text.json'),
  ('hafs-21-100', 'hafs', 21, 100, 'لَهُمْ فِيهَا زَفِيرٌۭ وَهُمْ فِيهَا لَا يَسْمَعُونَ', 'لهم فيها زفير وهم فيها لا يسمعون', NULL, 330, 'local:hafs-text.json'),
  ('hafs-21-101', 'hafs', 21, 101, 'إِنَّ ٱلَّذِينَ سَبَقَتْ لَهُم مِّنَّا ٱلْحُسْنَىٰٓ أُو۟لَٰٓئِكَ عَنْهَا مُبْعَدُونَ', 'إن الذين سبقت لهم منا الحسنى أولئك عنها مبعدون', NULL, 330, 'local:hafs-text.json'),
  ('hafs-21-102', 'hafs', 21, 102, 'لَا يَسْمَعُونَ حَسِيسَهَا ۖ وَهُمْ فِى مَا ٱشْتَهَتْ أَنفُسُهُمْ خَٰلِدُونَ', 'لا يسمعون حسيسها  وهم فى ما اشتهت أنفسهم خلدون', NULL, 331, 'local:hafs-text.json'),
  ('hafs-21-103', 'hafs', 21, 103, 'لَا يَحْزُنُهُمُ ٱلْفَزَعُ ٱلْأَكْبَرُ وَتَتَلَقَّىٰهُمُ ٱلْمَلَٰٓئِكَةُ هَٰذَا يَوْمُكُمُ ٱلَّذِى كُنتُمْ تُوعَدُونَ', 'لا يحزنهم الفزع الأكبر وتتلقىهم الملئكة هذا يومكم الذى كنتم توعدون', NULL, 331, 'local:hafs-text.json'),
  ('hafs-21-104', 'hafs', 21, 104, 'يَوْمَ نَطْوِى ٱلسَّمَآءَ كَطَىِّ ٱلسِّجِلِّ لِلْكُتُبِ ۚ كَمَا بَدَأْنَآ أَوَّلَ خَلْقٍۢ نُّعِيدُهُۥ ۚ وَعْدًا عَلَيْنَآ ۚ إِنَّا كُنَّا فَٰعِلِينَ', 'يوم نطوى السماء كطى السجل للكتب  كما بدأنا أول خلق نعيده  وعدا علينا  إنا كنا فعلين', NULL, 331, 'local:hafs-text.json'),
  ('hafs-21-105', 'hafs', 21, 105, 'وَلَقَدْ كَتَبْنَا فِى ٱلزَّبُورِ مِنۢ بَعْدِ ٱلذِّكْرِ أَنَّ ٱلْأَرْضَ يَرِثُهَا عِبَادِىَ ٱلصَّٰلِحُونَ', 'ولقد كتبنا فى الزبور من بعد الذكر أن الأرض يرثها عبادى الصلحون', NULL, 331, 'local:hafs-text.json'),
  ('hafs-21-106', 'hafs', 21, 106, 'إِنَّ فِى هَٰذَا لَبَلَٰغًۭا لِّقَوْمٍ عَٰبِدِينَ', 'إن فى هذا لبلغا لقوم عبدين', NULL, 331, 'local:hafs-text.json'),
  ('hafs-21-107', 'hafs', 21, 107, 'وَمَآ أَرْسَلْنَٰكَ إِلَّا رَحْمَةًۭ لِّلْعَٰلَمِينَ', 'وما أرسلنك إلا رحمة للعلمين', NULL, 331, 'local:hafs-text.json'),
  ('hafs-21-108', 'hafs', 21, 108, 'قُلْ إِنَّمَا يُوحَىٰٓ إِلَىَّ أَنَّمَآ إِلَٰهُكُمْ إِلَٰهٌۭ وَٰحِدٌۭ ۖ فَهَلْ أَنتُم مُّسْلِمُونَ', 'قل إنما يوحى إلى أنما إلهكم إله وحد  فهل أنتم مسلمون', NULL, 331, 'local:hafs-text.json'),
  ('hafs-21-109', 'hafs', 21, 109, 'فَإِن تَوَلَّوْا۟ فَقُلْ ءَاذَنتُكُمْ عَلَىٰ سَوَآءٍۢ ۖ وَإِنْ أَدْرِىٓ أَقَرِيبٌ أَم بَعِيدٌۭ مَّا تُوعَدُونَ', 'فإن تولوا فقل ءاذنتكم على سواء  وإن أدرى أقريب أم بعيد ما توعدون', NULL, 331, 'local:hafs-text.json'),
  ('hafs-21-110', 'hafs', 21, 110, 'إِنَّهُۥ يَعْلَمُ ٱلْجَهْرَ مِنَ ٱلْقَوْلِ وَيَعْلَمُ مَا تَكْتُمُونَ', 'إنه يعلم الجهر من القول ويعلم ما تكتمون', NULL, 331, 'local:hafs-text.json'),
  ('hafs-21-111', 'hafs', 21, 111, 'وَإِنْ أَدْرِى لَعَلَّهُۥ فِتْنَةٌۭ لَّكُمْ وَمَتَٰعٌ إِلَىٰ حِينٍۢ', 'وإن أدرى لعله فتنة لكم ومتع إلى حين', NULL, 331, 'local:hafs-text.json'),
  ('hafs-21-112', 'hafs', 21, 112, 'قَٰلَ رَبِّ ٱحْكُم بِٱلْحَقِّ ۗ وَرَبُّنَا ٱلرَّحْمَٰنُ ٱلْمُسْتَعَانُ عَلَىٰ مَا تَصِفُونَ', 'قل رب احكم بالحق  وربنا الرحمن المستعان على ما تصفون', NULL, 331, 'local:hafs-text.json'),
  ('hafs-22-1', 'hafs', 22, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ يَٰٓأَيُّهَا ٱلنَّاسُ ٱتَّقُوا۟ رَبَّكُمْ ۚ إِنَّ زَلْزَلَةَ ٱلسَّاعَةِ شَىْءٌ عَظِيمٌۭ', 'بسم الله الرحمن الرحيم يأيها الناس اتقوا ربكم  إن زلزلة الساعة شىء عظيم', NULL, 332, 'local:hafs-text.json'),
  ('hafs-22-2', 'hafs', 22, 2, 'يَوْمَ تَرَوْنَهَا تَذْهَلُ كُلُّ مُرْضِعَةٍ عَمَّآ أَرْضَعَتْ وَتَضَعُ كُلُّ ذَاتِ حَمْلٍ حَمْلَهَا وَتَرَى ٱلنَّاسَ سُكَٰرَىٰ وَمَا هُم بِسُكَٰرَىٰ وَلَٰكِنَّ عَذَابَ ٱللَّهِ شَدِيدٌۭ', 'يوم ترونها تذهل كل مرضعة عما أرضعت وتضع كل ذات حمل حملها وترى الناس سكرى وما هم بسكرى ولكن عذاب الله شديد', NULL, 332, 'local:hafs-text.json'),
  ('hafs-22-3', 'hafs', 22, 3, 'وَمِنَ ٱلنَّاسِ مَن يُجَٰدِلُ فِى ٱللَّهِ بِغَيْرِ عِلْمٍۢ وَيَتَّبِعُ كُلَّ شَيْطَٰنٍۢ مَّرِيدٍۢ', 'ومن الناس من يجدل فى الله بغير علم ويتبع كل شيطن مريد', NULL, 332, 'local:hafs-text.json'),
  ('hafs-22-4', 'hafs', 22, 4, 'كُتِبَ عَلَيْهِ أَنَّهُۥ مَن تَوَلَّاهُ فَأَنَّهُۥ يُضِلُّهُۥ وَيَهْدِيهِ إِلَىٰ عَذَابِ ٱلسَّعِيرِ', 'كتب عليه أنه من تولاه فأنه يضله ويهديه إلى عذاب السعير', NULL, 332, 'local:hafs-text.json'),
  ('hafs-22-5', 'hafs', 22, 5, 'يَٰٓأَيُّهَا ٱلنَّاسُ إِن كُنتُمْ فِى رَيْبٍۢ مِّنَ ٱلْبَعْثِ فَإِنَّا خَلَقْنَٰكُم مِّن تُرَابٍۢ ثُمَّ مِن نُّطْفَةٍۢ ثُمَّ مِنْ عَلَقَةٍۢ ثُمَّ مِن مُّضْغَةٍۢ مُّخَلَّقَةٍۢ وَغَيْرِ مُخَلَّقَةٍۢ لِّنُبَيِّنَ لَكُمْ ۚ وَنُقِرُّ فِى ٱلْأَرْحَامِ مَا نَشَآءُ إِلَىٰٓ أَجَلٍۢ مُّسَمًّۭى ثُمَّ نُخْرِجُكُمْ طِفْلًۭا ثُمَّ لِتَبْلُغُوٓا۟ أَشُدَّكُمْ ۖ وَمِنكُم مَّن يُتَوَفَّىٰ وَمِنكُم مَّن يُرَدُّ إِلَىٰٓ أَرْذَلِ ٱلْعُمُرِ لِكَيْلَا يَعْلَمَ مِنۢ بَعْدِ عِلْمٍۢ شَيْـًۭٔا ۚ وَتَرَى ٱلْأَرْضَ هَامِدَةًۭ فَإِذَآ أَنزَلْنَا عَلَيْهَا ٱلْمَآءَ ٱهْتَزَّتْ وَرَبَتْ وَأَنۢبَتَتْ مِن كُلِّ زَوْجٍۭ بَهِيجٍۢ', 'يأيها الناس إن كنتم فى ريب من البعث فإنا خلقنكم من تراب ثم من نطفة ثم من علقة ثم من مضغة مخلقة وغير مخلقة لنبين لكم  ونقر فى الأرحام ما نشاء إلى أجل مسمى ثم نخرجكم طفلا ثم لتبلغوا أشدكم  ومنكم من يتوفى ومنكم من يرد إلى أرذل العمر لكيلا يعلم من بعد علم شيا  وترى الأرض هامدة فإذا أنزلنا عليها الماء اهتزت وربت وأنبتت من كل زوج بهيج', NULL, 332, 'local:hafs-text.json'),
  ('hafs-22-6', 'hafs', 22, 6, 'ذَٰلِكَ بِأَنَّ ٱللَّهَ هُوَ ٱلْحَقُّ وَأَنَّهُۥ يُحْىِ ٱلْمَوْتَىٰ وَأَنَّهُۥ عَلَىٰ كُلِّ شَىْءٍۢ قَدِيرٌۭ', 'ذلك بأن الله هو الحق وأنه يحى الموتى وأنه على كل شىء قدير', NULL, 333, 'local:hafs-text.json'),
  ('hafs-22-7', 'hafs', 22, 7, 'وَأَنَّ ٱلسَّاعَةَ ءَاتِيَةٌۭ لَّا رَيْبَ فِيهَا وَأَنَّ ٱللَّهَ يَبْعَثُ مَن فِى ٱلْقُبُورِ', 'وأن الساعة ءاتية لا ريب فيها وأن الله يبعث من فى القبور', NULL, 333, 'local:hafs-text.json'),
  ('hafs-22-8', 'hafs', 22, 8, 'وَمِنَ ٱلنَّاسِ مَن يُجَٰدِلُ فِى ٱللَّهِ بِغَيْرِ عِلْمٍۢ وَلَا هُدًۭى وَلَا كِتَٰبٍۢ مُّنِيرٍۢ', 'ومن الناس من يجدل فى الله بغير علم ولا هدى ولا كتب منير', NULL, 333, 'local:hafs-text.json'),
  ('hafs-22-9', 'hafs', 22, 9, 'ثَانِىَ عِطْفِهِۦ لِيُضِلَّ عَن سَبِيلِ ٱللَّهِ ۖ لَهُۥ فِى ٱلدُّنْيَا خِزْىٌۭ ۖ وَنُذِيقُهُۥ يَوْمَ ٱلْقِيَٰمَةِ عَذَابَ ٱلْحَرِيقِ', 'ثانى عطفه ليضل عن سبيل الله  له فى الدنيا خزى  ونذيقه يوم القيمة عذاب الحريق', NULL, 333, 'local:hafs-text.json'),
  ('hafs-22-10', 'hafs', 22, 10, 'ذَٰلِكَ بِمَا قَدَّمَتْ يَدَاكَ وَأَنَّ ٱللَّهَ لَيْسَ بِظَلَّٰمٍۢ لِّلْعَبِيدِ', 'ذلك بما قدمت يداك وأن الله ليس بظلم للعبيد', NULL, 333, 'local:hafs-text.json'),
  ('hafs-22-11', 'hafs', 22, 11, 'وَمِنَ ٱلنَّاسِ مَن يَعْبُدُ ٱللَّهَ عَلَىٰ حَرْفٍۢ ۖ فَإِنْ أَصَابَهُۥ خَيْرٌ ٱطْمَأَنَّ بِهِۦ ۖ وَإِنْ أَصَابَتْهُ فِتْنَةٌ ٱنقَلَبَ عَلَىٰ وَجْهِهِۦ خَسِرَ ٱلدُّنْيَا وَٱلْءَاخِرَةَ ۚ ذَٰلِكَ هُوَ ٱلْخُسْرَانُ ٱلْمُبِينُ', 'ومن الناس من يعبد الله على حرف  فإن أصابه خير اطمأن به  وإن أصابته فتنة انقلب على وجهه خسر الدنيا والءاخرة  ذلك هو الخسران المبين', NULL, 333, 'local:hafs-text.json'),
  ('hafs-22-12', 'hafs', 22, 12, 'يَدْعُوا۟ مِن دُونِ ٱللَّهِ مَا لَا يَضُرُّهُۥ وَمَا لَا يَنفَعُهُۥ ۚ ذَٰلِكَ هُوَ ٱلضَّلَٰلُ ٱلْبَعِيدُ', 'يدعوا من دون الله ما لا يضره وما لا ينفعه  ذلك هو الضلل البعيد', NULL, 333, 'local:hafs-text.json'),
  ('hafs-22-13', 'hafs', 22, 13, 'يَدْعُوا۟ لَمَن ضَرُّهُۥٓ أَقْرَبُ مِن نَّفْعِهِۦ ۚ لَبِئْسَ ٱلْمَوْلَىٰ وَلَبِئْسَ ٱلْعَشِيرُ', 'يدعوا لمن ضره أقرب من نفعه  لبئس المولى ولبئس العشير', NULL, 333, 'local:hafs-text.json'),
  ('hafs-22-14', 'hafs', 22, 14, 'إِنَّ ٱللَّهَ يُدْخِلُ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ جَنَّٰتٍۢ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ ۚ إِنَّ ٱللَّهَ يَفْعَلُ مَا يُرِيدُ', 'إن الله يدخل الذين ءامنوا وعملوا الصلحت جنت تجرى من تحتها الأنهر  إن الله يفعل ما يريد', NULL, 333, 'local:hafs-text.json'),
  ('hafs-22-15', 'hafs', 22, 15, 'مَن كَانَ يَظُنُّ أَن لَّن يَنصُرَهُ ٱللَّهُ فِى ٱلدُّنْيَا وَٱلْءَاخِرَةِ فَلْيَمْدُدْ بِسَبَبٍ إِلَى ٱلسَّمَآءِ ثُمَّ لْيَقْطَعْ فَلْيَنظُرْ هَلْ يُذْهِبَنَّ كَيْدُهُۥ مَا يَغِيظُ', 'من كان يظن أن لن ينصره الله فى الدنيا والءاخرة فليمدد بسبب إلى السماء ثم ليقطع فلينظر هل يذهبن كيده ما يغيظ', NULL, 333, 'local:hafs-text.json'),
  ('hafs-22-16', 'hafs', 22, 16, 'وَكَذَٰلِكَ أَنزَلْنَٰهُ ءَايَٰتٍۭ بَيِّنَٰتٍۢ وَأَنَّ ٱللَّهَ يَهْدِى مَن يُرِيدُ', 'وكذلك أنزلنه ءايت بينت وأن الله يهدى من يريد', NULL, 334, 'local:hafs-text.json'),
  ('hafs-22-17', 'hafs', 22, 17, 'إِنَّ ٱلَّذِينَ ءَامَنُوا۟ وَٱلَّذِينَ هَادُوا۟ وَٱلصَّٰبِـِٔينَ وَٱلنَّصَٰرَىٰ وَٱلْمَجُوسَ وَٱلَّذِينَ أَشْرَكُوٓا۟ إِنَّ ٱللَّهَ يَفْصِلُ بَيْنَهُمْ يَوْمَ ٱلْقِيَٰمَةِ ۚ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَىْءٍۢ شَهِيدٌ', 'إن الذين ءامنوا والذين هادوا والصبين والنصرى والمجوس والذين أشركوا إن الله يفصل بينهم يوم القيمة  إن الله على كل شىء شهيد', NULL, 334, 'local:hafs-text.json'),
  ('hafs-22-18', 'hafs', 22, 18, 'أَلَمْ تَرَ أَنَّ ٱللَّهَ يَسْجُدُ لَهُۥ مَن فِى ٱلسَّمَٰوَٰتِ وَمَن فِى ٱلْأَرْضِ وَٱلشَّمْسُ وَٱلْقَمَرُ وَٱلنُّجُومُ وَٱلْجِبَالُ وَٱلشَّجَرُ وَٱلدَّوَآبُّ وَكَثِيرٌۭ مِّنَ ٱلنَّاسِ ۖ وَكَثِيرٌ حَقَّ عَلَيْهِ ٱلْعَذَابُ ۗ وَمَن يُهِنِ ٱللَّهُ فَمَا لَهُۥ مِن مُّكْرِمٍ ۚ إِنَّ ٱللَّهَ يَفْعَلُ مَا يَشَآءُ ۩', 'ألم تر أن الله يسجد له من فى السموت ومن فى الأرض والشمس والقمر والنجوم والجبال والشجر والدواب وكثير من الناس  وكثير حق عليه العذاب  ومن يهن الله فما له من مكرم  إن الله يفعل ما يشاء', NULL, 334, 'local:hafs-text.json'),
  ('hafs-22-19', 'hafs', 22, 19, '۞ هَٰذَانِ خَصْمَانِ ٱخْتَصَمُوا۟ فِى رَبِّهِمْ ۖ فَٱلَّذِينَ كَفَرُوا۟ قُطِّعَتْ لَهُمْ ثِيَابٌۭ مِّن نَّارٍۢ يُصَبُّ مِن فَوْقِ رُءُوسِهِمُ ٱلْحَمِيمُ', 'هذان خصمان اختصموا فى ربهم  فالذين كفروا قطعت لهم ثياب من نار يصب من فوق رءوسهم الحميم', NULL, 334, 'local:hafs-text.json'),
  ('hafs-22-20', 'hafs', 22, 20, 'يُصْهَرُ بِهِۦ مَا فِى بُطُونِهِمْ وَٱلْجُلُودُ', 'يصهر به ما فى بطونهم والجلود', NULL, 334, 'local:hafs-text.json'),
  ('hafs-22-21', 'hafs', 22, 21, 'وَلَهُم مَّقَٰمِعُ مِنْ حَدِيدٍۢ', 'ولهم مقمع من حديد', NULL, 334, 'local:hafs-text.json'),
  ('hafs-22-22', 'hafs', 22, 22, 'كُلَّمَآ أَرَادُوٓا۟ أَن يَخْرُجُوا۟ مِنْهَا مِنْ غَمٍّ أُعِيدُوا۟ فِيهَا وَذُوقُوا۟ عَذَابَ ٱلْحَرِيقِ', 'كلما أرادوا أن يخرجوا منها من غم أعيدوا فيها وذوقوا عذاب الحريق', NULL, 334, 'local:hafs-text.json'),
  ('hafs-22-23', 'hafs', 22, 23, 'إِنَّ ٱللَّهَ يُدْخِلُ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ جَنَّٰتٍۢ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ يُحَلَّوْنَ فِيهَا مِنْ أَسَاوِرَ مِن ذَهَبٍۢ وَلُؤْلُؤًۭا ۖ وَلِبَاسُهُمْ فِيهَا حَرِيرٌۭ', 'إن الله يدخل الذين ءامنوا وعملوا الصلحت جنت تجرى من تحتها الأنهر يحلون فيها من أساور من ذهب ولؤلؤا  ولباسهم فيها حرير', NULL, 334, 'local:hafs-text.json'),
  ('hafs-22-24', 'hafs', 22, 24, 'وَهُدُوٓا۟ إِلَى ٱلطَّيِّبِ مِنَ ٱلْقَوْلِ وَهُدُوٓا۟ إِلَىٰ صِرَٰطِ ٱلْحَمِيدِ', 'وهدوا إلى الطيب من القول وهدوا إلى صرط الحميد', NULL, 335, 'local:hafs-text.json'),
  ('hafs-22-25', 'hafs', 22, 25, 'إِنَّ ٱلَّذِينَ كَفَرُوا۟ وَيَصُدُّونَ عَن سَبِيلِ ٱللَّهِ وَٱلْمَسْجِدِ ٱلْحَرَامِ ٱلَّذِى جَعَلْنَٰهُ لِلنَّاسِ سَوَآءً ٱلْعَٰكِفُ فِيهِ وَٱلْبَادِ ۚ وَمَن يُرِدْ فِيهِ بِإِلْحَادٍۭ بِظُلْمٍۢ نُّذِقْهُ مِنْ عَذَابٍ أَلِيمٍۢ', 'إن الذين كفروا ويصدون عن سبيل الله والمسجد الحرام الذى جعلنه للناس سواء العكف فيه والباد  ومن يرد فيه بإلحاد بظلم نذقه من عذاب أليم', NULL, 335, 'local:hafs-text.json'),
  ('hafs-22-26', 'hafs', 22, 26, 'وَإِذْ بَوَّأْنَا لِإِبْرَٰهِيمَ مَكَانَ ٱلْبَيْتِ أَن لَّا تُشْرِكْ بِى شَيْـًۭٔا وَطَهِّرْ بَيْتِىَ لِلطَّآئِفِينَ وَٱلْقَآئِمِينَ وَٱلرُّكَّعِ ٱلسُّجُودِ', 'وإذ بوأنا لإبرهيم مكان البيت أن لا تشرك بى شيا وطهر بيتى للطائفين والقائمين والركع السجود', NULL, 335, 'local:hafs-text.json'),
  ('hafs-22-27', 'hafs', 22, 27, 'وَأَذِّن فِى ٱلنَّاسِ بِٱلْحَجِّ يَأْتُوكَ رِجَالًۭا وَعَلَىٰ كُلِّ ضَامِرٍۢ يَأْتِينَ مِن كُلِّ فَجٍّ عَمِيقٍۢ', 'وأذن فى الناس بالحج يأتوك رجالا وعلى كل ضامر يأتين من كل فج عميق', NULL, 335, 'local:hafs-text.json'),
  ('hafs-22-28', 'hafs', 22, 28, 'لِّيَشْهَدُوا۟ مَنَٰفِعَ لَهُمْ وَيَذْكُرُوا۟ ٱسْمَ ٱللَّهِ فِىٓ أَيَّامٍۢ مَّعْلُومَٰتٍ عَلَىٰ مَا رَزَقَهُم مِّنۢ بَهِيمَةِ ٱلْأَنْعَٰمِ ۖ فَكُلُوا۟ مِنْهَا وَأَطْعِمُوا۟ ٱلْبَآئِسَ ٱلْفَقِيرَ', 'ليشهدوا منفع لهم ويذكروا اسم الله فى أيام معلومت على ما رزقهم من بهيمة الأنعم  فكلوا منها وأطعموا البائس الفقير', NULL, 335, 'local:hafs-text.json'),
  ('hafs-22-29', 'hafs', 22, 29, 'ثُمَّ لْيَقْضُوا۟ تَفَثَهُمْ وَلْيُوفُوا۟ نُذُورَهُمْ وَلْيَطَّوَّفُوا۟ بِٱلْبَيْتِ ٱلْعَتِيقِ', 'ثم ليقضوا تفثهم وليوفوا نذورهم وليطوفوا بالبيت العتيق', NULL, 335, 'local:hafs-text.json'),
  ('hafs-22-30', 'hafs', 22, 30, 'ذَٰلِكَ وَمَن يُعَظِّمْ حُرُمَٰتِ ٱللَّهِ فَهُوَ خَيْرٌۭ لَّهُۥ عِندَ رَبِّهِۦ ۗ وَأُحِلَّتْ لَكُمُ ٱلْأَنْعَٰمُ إِلَّا مَا يُتْلَىٰ عَلَيْكُمْ ۖ فَٱجْتَنِبُوا۟ ٱلرِّجْسَ مِنَ ٱلْأَوْثَٰنِ وَٱجْتَنِبُوا۟ قَوْلَ ٱلزُّورِ', 'ذلك ومن يعظم حرمت الله فهو خير له عند ربه  وأحلت لكم الأنعم إلا ما يتلى عليكم  فاجتنبوا الرجس من الأوثن واجتنبوا قول الزور', NULL, 335, 'local:hafs-text.json'),
  ('hafs-22-31', 'hafs', 22, 31, 'حُنَفَآءَ لِلَّهِ غَيْرَ مُشْرِكِينَ بِهِۦ ۚ وَمَن يُشْرِكْ بِٱللَّهِ فَكَأَنَّمَا خَرَّ مِنَ ٱلسَّمَآءِ فَتَخْطَفُهُ ٱلطَّيْرُ أَوْ تَهْوِى بِهِ ٱلرِّيحُ فِى مَكَانٍۢ سَحِيقٍۢ', 'حنفاء لله غير مشركين به  ومن يشرك بالله فكأنما خر من السماء فتخطفه الطير أو تهوى به الريح فى مكان سحيق', NULL, 336, 'local:hafs-text.json'),
  ('hafs-22-32', 'hafs', 22, 32, 'ذَٰلِكَ وَمَن يُعَظِّمْ شَعَٰٓئِرَ ٱللَّهِ فَإِنَّهَا مِن تَقْوَى ٱلْقُلُوبِ', 'ذلك ومن يعظم شعئر الله فإنها من تقوى القلوب', NULL, 336, 'local:hafs-text.json'),
  ('hafs-22-33', 'hafs', 22, 33, 'لَكُمْ فِيهَا مَنَٰفِعُ إِلَىٰٓ أَجَلٍۢ مُّسَمًّۭى ثُمَّ مَحِلُّهَآ إِلَى ٱلْبَيْتِ ٱلْعَتِيقِ', 'لكم فيها منفع إلى أجل مسمى ثم محلها إلى البيت العتيق', NULL, 336, 'local:hafs-text.json'),
  ('hafs-22-34', 'hafs', 22, 34, 'وَلِكُلِّ أُمَّةٍۢ جَعَلْنَا مَنسَكًۭا لِّيَذْكُرُوا۟ ٱسْمَ ٱللَّهِ عَلَىٰ مَا رَزَقَهُم مِّنۢ بَهِيمَةِ ٱلْأَنْعَٰمِ ۗ فَإِلَٰهُكُمْ إِلَٰهٌۭ وَٰحِدٌۭ فَلَهُۥٓ أَسْلِمُوا۟ ۗ وَبَشِّرِ ٱلْمُخْبِتِينَ', 'ولكل أمة جعلنا منسكا ليذكروا اسم الله على ما رزقهم من بهيمة الأنعم  فإلهكم إله وحد فله أسلموا  وبشر المخبتين', NULL, 336, 'local:hafs-text.json'),
  ('hafs-22-35', 'hafs', 22, 35, 'ٱلَّذِينَ إِذَا ذُكِرَ ٱللَّهُ وَجِلَتْ قُلُوبُهُمْ وَٱلصَّٰبِرِينَ عَلَىٰ مَآ أَصَابَهُمْ وَٱلْمُقِيمِى ٱلصَّلَوٰةِ وَمِمَّا رَزَقْنَٰهُمْ يُنفِقُونَ', 'الذين إذا ذكر الله وجلت قلوبهم والصبرين على ما أصابهم والمقيمى الصلوة ومما رزقنهم ينفقون', NULL, 336, 'local:hafs-text.json'),
  ('hafs-22-36', 'hafs', 22, 36, 'وَٱلْبُدْنَ جَعَلْنَٰهَا لَكُم مِّن شَعَٰٓئِرِ ٱللَّهِ لَكُمْ فِيهَا خَيْرٌۭ ۖ فَٱذْكُرُوا۟ ٱسْمَ ٱللَّهِ عَلَيْهَا صَوَآفَّ ۖ فَإِذَا وَجَبَتْ جُنُوبُهَا فَكُلُوا۟ مِنْهَا وَأَطْعِمُوا۟ ٱلْقَانِعَ وَٱلْمُعْتَرَّ ۚ كَذَٰلِكَ سَخَّرْنَٰهَا لَكُمْ لَعَلَّكُمْ تَشْكُرُونَ', 'والبدن جعلنها لكم من شعئر الله لكم فيها خير  فاذكروا اسم الله عليها صواف  فإذا وجبت جنوبها فكلوا منها وأطعموا القانع والمعتر  كذلك سخرنها لكم لعلكم تشكرون', NULL, 336, 'local:hafs-text.json'),
  ('hafs-22-37', 'hafs', 22, 37, 'لَن يَنَالَ ٱللَّهَ لُحُومُهَا وَلَا دِمَآؤُهَا وَلَٰكِن يَنَالُهُ ٱلتَّقْوَىٰ مِنكُمْ ۚ كَذَٰلِكَ سَخَّرَهَا لَكُمْ لِتُكَبِّرُوا۟ ٱللَّهَ عَلَىٰ مَا هَدَىٰكُمْ ۗ وَبَشِّرِ ٱلْمُحْسِنِينَ', 'لن ينال الله لحومها ولا دماؤها ولكن يناله التقوى منكم  كذلك سخرها لكم لتكبروا الله على ما هدىكم  وبشر المحسنين', NULL, 336, 'local:hafs-text.json'),
  ('hafs-22-38', 'hafs', 22, 38, '۞ إِنَّ ٱللَّهَ يُدَٰفِعُ عَنِ ٱلَّذِينَ ءَامَنُوٓا۟ ۗ إِنَّ ٱللَّهَ لَا يُحِبُّ كُلَّ خَوَّانٍۢ كَفُورٍ', 'إن الله يدفع عن الذين ءامنوا  إن الله لا يحب كل خوان كفور', NULL, 336, 'local:hafs-text.json'),
  ('hafs-22-39', 'hafs', 22, 39, 'أُذِنَ لِلَّذِينَ يُقَٰتَلُونَ بِأَنَّهُمْ ظُلِمُوا۟ ۚ وَإِنَّ ٱللَّهَ عَلَىٰ نَصْرِهِمْ لَقَدِيرٌ', 'أذن للذين يقتلون بأنهم ظلموا  وإن الله على نصرهم لقدير', NULL, 337, 'local:hafs-text.json'),
  ('hafs-22-40', 'hafs', 22, 40, 'ٱلَّذِينَ أُخْرِجُوا۟ مِن دِيَٰرِهِم بِغَيْرِ حَقٍّ إِلَّآ أَن يَقُولُوا۟ رَبُّنَا ٱللَّهُ ۗ وَلَوْلَا دَفْعُ ٱللَّهِ ٱلنَّاسَ بَعْضَهُم بِبَعْضٍۢ لَّهُدِّمَتْ صَوَٰمِعُ وَبِيَعٌۭ وَصَلَوَٰتٌۭ وَمَسَٰجِدُ يُذْكَرُ فِيهَا ٱسْمُ ٱللَّهِ كَثِيرًۭا ۗ وَلَيَنصُرَنَّ ٱللَّهُ مَن يَنصُرُهُۥٓ ۗ إِنَّ ٱللَّهَ لَقَوِىٌّ عَزِيزٌ', 'الذين أخرجوا من ديرهم بغير حق إلا أن يقولوا ربنا الله  ولولا دفع الله الناس بعضهم ببعض لهدمت صومع وبيع وصلوت ومسجد يذكر فيها اسم الله كثيرا  ولينصرن الله من ينصره  إن الله لقوى عزيز', NULL, 337, 'local:hafs-text.json'),
  ('hafs-22-41', 'hafs', 22, 41, 'ٱلَّذِينَ إِن مَّكَّنَّٰهُمْ فِى ٱلْأَرْضِ أَقَامُوا۟ ٱلصَّلَوٰةَ وَءَاتَوُا۟ ٱلزَّكَوٰةَ وَأَمَرُوا۟ بِٱلْمَعْرُوفِ وَنَهَوْا۟ عَنِ ٱلْمُنكَرِ ۗ وَلِلَّهِ عَٰقِبَةُ ٱلْأُمُورِ', 'الذين إن مكنهم فى الأرض أقاموا الصلوة وءاتوا الزكوة وأمروا بالمعروف ونهوا عن المنكر  ولله عقبة الأمور', NULL, 337, 'local:hafs-text.json'),
  ('hafs-22-42', 'hafs', 22, 42, 'وَإِن يُكَذِّبُوكَ فَقَدْ كَذَّبَتْ قَبْلَهُمْ قَوْمُ نُوحٍۢ وَعَادٌۭ وَثَمُودُ', 'وإن يكذبوك فقد كذبت قبلهم قوم نوح وعاد وثمود', NULL, 337, 'local:hafs-text.json'),
  ('hafs-22-43', 'hafs', 22, 43, 'وَقَوْمُ إِبْرَٰهِيمَ وَقَوْمُ لُوطٍۢ', 'وقوم إبرهيم وقوم لوط', NULL, 337, 'local:hafs-text.json'),
  ('hafs-22-44', 'hafs', 22, 44, 'وَأَصْحَٰبُ مَدْيَنَ ۖ وَكُذِّبَ مُوسَىٰ فَأَمْلَيْتُ لِلْكَٰفِرِينَ ثُمَّ أَخَذْتُهُمْ ۖ فَكَيْفَ كَانَ نَكِيرِ', 'وأصحب مدين  وكذب موسى فأمليت للكفرين ثم أخذتهم  فكيف كان نكير', NULL, 337, 'local:hafs-text.json'),
  ('hafs-22-45', 'hafs', 22, 45, 'فَكَأَيِّن مِّن قَرْيَةٍ أَهْلَكْنَٰهَا وَهِىَ ظَالِمَةٌۭ فَهِىَ خَاوِيَةٌ عَلَىٰ عُرُوشِهَا وَبِئْرٍۢ مُّعَطَّلَةٍۢ وَقَصْرٍۢ مَّشِيدٍ', 'فكأين من قرية أهلكنها وهى ظالمة فهى خاوية على عروشها وبئر معطلة وقصر مشيد', NULL, 337, 'local:hafs-text.json'),
  ('hafs-22-46', 'hafs', 22, 46, 'أَفَلَمْ يَسِيرُوا۟ فِى ٱلْأَرْضِ فَتَكُونَ لَهُمْ قُلُوبٌۭ يَعْقِلُونَ بِهَآ أَوْ ءَاذَانٌۭ يَسْمَعُونَ بِهَا ۖ فَإِنَّهَا لَا تَعْمَى ٱلْأَبْصَٰرُ وَلَٰكِن تَعْمَى ٱلْقُلُوبُ ٱلَّتِى فِى ٱلصُّدُورِ', 'أفلم يسيروا فى الأرض فتكون لهم قلوب يعقلون بها أو ءاذان يسمعون بها  فإنها لا تعمى الأبصر ولكن تعمى القلوب التى فى الصدور', NULL, 337, 'local:hafs-text.json'),
  ('hafs-22-47', 'hafs', 22, 47, 'وَيَسْتَعْجِلُونَكَ بِٱلْعَذَابِ وَلَن يُخْلِفَ ٱللَّهُ وَعْدَهُۥ ۚ وَإِنَّ يَوْمًا عِندَ رَبِّكَ كَأَلْفِ سَنَةٍۢ مِّمَّا تَعُدُّونَ', 'ويستعجلونك بالعذاب ولن يخلف الله وعده  وإن يوما عند ربك كألف سنة مما تعدون', NULL, 338, 'local:hafs-text.json'),
  ('hafs-22-48', 'hafs', 22, 48, 'وَكَأَيِّن مِّن قَرْيَةٍ أَمْلَيْتُ لَهَا وَهِىَ ظَالِمَةٌۭ ثُمَّ أَخَذْتُهَا وَإِلَىَّ ٱلْمَصِيرُ', 'وكأين من قرية أمليت لها وهى ظالمة ثم أخذتها وإلى المصير', NULL, 338, 'local:hafs-text.json'),
  ('hafs-22-49', 'hafs', 22, 49, 'قُلْ يَٰٓأَيُّهَا ٱلنَّاسُ إِنَّمَآ أَنَا۠ لَكُمْ نَذِيرٌۭ مُّبِينٌۭ', 'قل يأيها الناس إنما أنا لكم نذير مبين', NULL, 338, 'local:hafs-text.json'),
  ('hafs-22-50', 'hafs', 22, 50, 'فَٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ لَهُم مَّغْفِرَةٌۭ وَرِزْقٌۭ كَرِيمٌۭ', 'فالذين ءامنوا وعملوا الصلحت لهم مغفرة ورزق كريم', NULL, 338, 'local:hafs-text.json'),
  ('hafs-22-51', 'hafs', 22, 51, 'وَٱلَّذِينَ سَعَوْا۟ فِىٓ ءَايَٰتِنَا مُعَٰجِزِينَ أُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلْجَحِيمِ', 'والذين سعوا فى ءايتنا معجزين أولئك أصحب الجحيم', NULL, 338, 'local:hafs-text.json'),
  ('hafs-22-52', 'hafs', 22, 52, 'وَمَآ أَرْسَلْنَا مِن قَبْلِكَ مِن رَّسُولٍۢ وَلَا نَبِىٍّ إِلَّآ إِذَا تَمَنَّىٰٓ أَلْقَى ٱلشَّيْطَٰنُ فِىٓ أُمْنِيَّتِهِۦ فَيَنسَخُ ٱللَّهُ مَا يُلْقِى ٱلشَّيْطَٰنُ ثُمَّ يُحْكِمُ ٱللَّهُ ءَايَٰتِهِۦ ۗ وَٱللَّهُ عَلِيمٌ حَكِيمٌۭ', 'وما أرسلنا من قبلك من رسول ولا نبى إلا إذا تمنى ألقى الشيطن فى أمنيته فينسخ الله ما يلقى الشيطن ثم يحكم الله ءايته  والله عليم حكيم', NULL, 338, 'local:hafs-text.json'),
  ('hafs-22-53', 'hafs', 22, 53, 'لِّيَجْعَلَ مَا يُلْقِى ٱلشَّيْطَٰنُ فِتْنَةًۭ لِّلَّذِينَ فِى قُلُوبِهِم مَّرَضٌۭ وَٱلْقَاسِيَةِ قُلُوبُهُمْ ۗ وَإِنَّ ٱلظَّٰلِمِينَ لَفِى شِقَاقٍۭ بَعِيدٍۢ', 'ليجعل ما يلقى الشيطن فتنة للذين فى قلوبهم مرض والقاسية قلوبهم  وإن الظلمين لفى شقاق بعيد', NULL, 338, 'local:hafs-text.json'),
  ('hafs-22-54', 'hafs', 22, 54, 'وَلِيَعْلَمَ ٱلَّذِينَ أُوتُوا۟ ٱلْعِلْمَ أَنَّهُ ٱلْحَقُّ مِن رَّبِّكَ فَيُؤْمِنُوا۟ بِهِۦ فَتُخْبِتَ لَهُۥ قُلُوبُهُمْ ۗ وَإِنَّ ٱللَّهَ لَهَادِ ٱلَّذِينَ ءَامَنُوٓا۟ إِلَىٰ صِرَٰطٍۢ مُّسْتَقِيمٍۢ', 'وليعلم الذين أوتوا العلم أنه الحق من ربك فيؤمنوا به فتخبت له قلوبهم  وإن الله لهاد الذين ءامنوا إلى صرط مستقيم', NULL, 338, 'local:hafs-text.json'),
  ('hafs-22-55', 'hafs', 22, 55, 'وَلَا يَزَالُ ٱلَّذِينَ كَفَرُوا۟ فِى مِرْيَةٍۢ مِّنْهُ حَتَّىٰ تَأْتِيَهُمُ ٱلسَّاعَةُ بَغْتَةً أَوْ يَأْتِيَهُمْ عَذَابُ يَوْمٍ عَقِيمٍ', 'ولا يزال الذين كفروا فى مرية منه حتى تأتيهم الساعة بغتة أو يأتيهم عذاب يوم عقيم', NULL, 338, 'local:hafs-text.json'),
  ('hafs-22-56', 'hafs', 22, 56, 'ٱلْمُلْكُ يَوْمَئِذٍۢ لِّلَّهِ يَحْكُمُ بَيْنَهُمْ ۚ فَٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ فِى جَنَّٰتِ ٱلنَّعِيمِ', 'الملك يومئذ لله يحكم بينهم  فالذين ءامنوا وعملوا الصلحت فى جنت النعيم', NULL, 339, 'local:hafs-text.json'),
  ('hafs-22-57', 'hafs', 22, 57, 'وَٱلَّذِينَ كَفَرُوا۟ وَكَذَّبُوا۟ بِـَٔايَٰتِنَا فَأُو۟لَٰٓئِكَ لَهُمْ عَذَابٌۭ مُّهِينٌۭ', 'والذين كفروا وكذبوا بايتنا فأولئك لهم عذاب مهين', NULL, 339, 'local:hafs-text.json'),
  ('hafs-22-58', 'hafs', 22, 58, 'وَٱلَّذِينَ هَاجَرُوا۟ فِى سَبِيلِ ٱللَّهِ ثُمَّ قُتِلُوٓا۟ أَوْ مَاتُوا۟ لَيَرْزُقَنَّهُمُ ٱللَّهُ رِزْقًا حَسَنًۭا ۚ وَإِنَّ ٱللَّهَ لَهُوَ خَيْرُ ٱلرَّٰزِقِينَ', 'والذين هاجروا فى سبيل الله ثم قتلوا أو ماتوا ليرزقنهم الله رزقا حسنا  وإن الله لهو خير الرزقين', NULL, 339, 'local:hafs-text.json'),
  ('hafs-22-59', 'hafs', 22, 59, 'لَيُدْخِلَنَّهُم مُّدْخَلًۭا يَرْضَوْنَهُۥ ۗ وَإِنَّ ٱللَّهَ لَعَلِيمٌ حَلِيمٌۭ', 'ليدخلنهم مدخلا يرضونه  وإن الله لعليم حليم', NULL, 339, 'local:hafs-text.json'),
  ('hafs-22-60', 'hafs', 22, 60, '۞ ذَٰلِكَ وَمَنْ عَاقَبَ بِمِثْلِ مَا عُوقِبَ بِهِۦ ثُمَّ بُغِىَ عَلَيْهِ لَيَنصُرَنَّهُ ٱللَّهُ ۗ إِنَّ ٱللَّهَ لَعَفُوٌّ غَفُورٌۭ', 'ذلك ومن عاقب بمثل ما عوقب به ثم بغى عليه لينصرنه الله  إن الله لعفو غفور', NULL, 339, 'local:hafs-text.json'),
  ('hafs-22-61', 'hafs', 22, 61, 'ذَٰلِكَ بِأَنَّ ٱللَّهَ يُولِجُ ٱلَّيْلَ فِى ٱلنَّهَارِ وَيُولِجُ ٱلنَّهَارَ فِى ٱلَّيْلِ وَأَنَّ ٱللَّهَ سَمِيعٌۢ بَصِيرٌۭ', 'ذلك بأن الله يولج اليل فى النهار ويولج النهار فى اليل وأن الله سميع بصير', NULL, 339, 'local:hafs-text.json'),
  ('hafs-22-62', 'hafs', 22, 62, 'ذَٰلِكَ بِأَنَّ ٱللَّهَ هُوَ ٱلْحَقُّ وَأَنَّ مَا يَدْعُونَ مِن دُونِهِۦ هُوَ ٱلْبَٰطِلُ وَأَنَّ ٱللَّهَ هُوَ ٱلْعَلِىُّ ٱلْكَبِيرُ', 'ذلك بأن الله هو الحق وأن ما يدعون من دونه هو البطل وأن الله هو العلى الكبير', NULL, 339, 'local:hafs-text.json'),
  ('hafs-22-63', 'hafs', 22, 63, 'أَلَمْ تَرَ أَنَّ ٱللَّهَ أَنزَلَ مِنَ ٱلسَّمَآءِ مَآءًۭ فَتُصْبِحُ ٱلْأَرْضُ مُخْضَرَّةً ۗ إِنَّ ٱللَّهَ لَطِيفٌ خَبِيرٌۭ', 'ألم تر أن الله أنزل من السماء ماء فتصبح الأرض مخضرة  إن الله لطيف خبير', NULL, 339, 'local:hafs-text.json'),
  ('hafs-22-64', 'hafs', 22, 64, 'لَّهُۥ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ ۗ وَإِنَّ ٱللَّهَ لَهُوَ ٱلْغَنِىُّ ٱلْحَمِيدُ', 'له ما فى السموت وما فى الأرض  وإن الله لهو الغنى الحميد', NULL, 339, 'local:hafs-text.json'),
  ('hafs-22-65', 'hafs', 22, 65, 'أَلَمْ تَرَ أَنَّ ٱللَّهَ سَخَّرَ لَكُم مَّا فِى ٱلْأَرْضِ وَٱلْفُلْكَ تَجْرِى فِى ٱلْبَحْرِ بِأَمْرِهِۦ وَيُمْسِكُ ٱلسَّمَآءَ أَن تَقَعَ عَلَى ٱلْأَرْضِ إِلَّا بِإِذْنِهِۦٓ ۗ إِنَّ ٱللَّهَ بِٱلنَّاسِ لَرَءُوفٌۭ رَّحِيمٌۭ', 'ألم تر أن الله سخر لكم ما فى الأرض والفلك تجرى فى البحر بأمره ويمسك السماء أن تقع على الأرض إلا بإذنه  إن الله بالناس لرءوف رحيم', NULL, 340, 'local:hafs-text.json'),
  ('hafs-22-66', 'hafs', 22, 66, 'وَهُوَ ٱلَّذِىٓ أَحْيَاكُمْ ثُمَّ يُمِيتُكُمْ ثُمَّ يُحْيِيكُمْ ۗ إِنَّ ٱلْإِنسَٰنَ لَكَفُورٌۭ', 'وهو الذى أحياكم ثم يميتكم ثم يحييكم  إن الإنسن لكفور', NULL, 340, 'local:hafs-text.json'),
  ('hafs-22-67', 'hafs', 22, 67, 'لِّكُلِّ أُمَّةٍۢ جَعَلْنَا مَنسَكًا هُمْ نَاسِكُوهُ ۖ فَلَا يُنَٰزِعُنَّكَ فِى ٱلْأَمْرِ ۚ وَٱدْعُ إِلَىٰ رَبِّكَ ۖ إِنَّكَ لَعَلَىٰ هُدًۭى مُّسْتَقِيمٍۢ', 'لكل أمة جعلنا منسكا هم ناسكوه  فلا ينزعنك فى الأمر  وادع إلى ربك  إنك لعلى هدى مستقيم', NULL, 340, 'local:hafs-text.json'),
  ('hafs-22-68', 'hafs', 22, 68, 'وَإِن جَٰدَلُوكَ فَقُلِ ٱللَّهُ أَعْلَمُ بِمَا تَعْمَلُونَ', 'وإن جدلوك فقل الله أعلم بما تعملون', NULL, 340, 'local:hafs-text.json'),
  ('hafs-22-69', 'hafs', 22, 69, 'ٱللَّهُ يَحْكُمُ بَيْنَكُمْ يَوْمَ ٱلْقِيَٰمَةِ فِيمَا كُنتُمْ فِيهِ تَخْتَلِفُونَ', 'الله يحكم بينكم يوم القيمة فيما كنتم فيه تختلفون', NULL, 340, 'local:hafs-text.json'),
  ('hafs-22-70', 'hafs', 22, 70, 'أَلَمْ تَعْلَمْ أَنَّ ٱللَّهَ يَعْلَمُ مَا فِى ٱلسَّمَآءِ وَٱلْأَرْضِ ۗ إِنَّ ذَٰلِكَ فِى كِتَٰبٍ ۚ إِنَّ ذَٰلِكَ عَلَى ٱللَّهِ يَسِيرٌۭ', 'ألم تعلم أن الله يعلم ما فى السماء والأرض  إن ذلك فى كتب  إن ذلك على الله يسير', NULL, 340, 'local:hafs-text.json'),
  ('hafs-22-71', 'hafs', 22, 71, 'وَيَعْبُدُونَ مِن دُونِ ٱللَّهِ مَا لَمْ يُنَزِّلْ بِهِۦ سُلْطَٰنًۭا وَمَا لَيْسَ لَهُم بِهِۦ عِلْمٌۭ ۗ وَمَا لِلظَّٰلِمِينَ مِن نَّصِيرٍۢ', 'ويعبدون من دون الله ما لم ينزل به سلطنا وما ليس لهم به علم  وما للظلمين من نصير', NULL, 340, 'local:hafs-text.json'),
  ('hafs-22-72', 'hafs', 22, 72, 'وَإِذَا تُتْلَىٰ عَلَيْهِمْ ءَايَٰتُنَا بَيِّنَٰتٍۢ تَعْرِفُ فِى وُجُوهِ ٱلَّذِينَ كَفَرُوا۟ ٱلْمُنكَرَ ۖ يَكَادُونَ يَسْطُونَ بِٱلَّذِينَ يَتْلُونَ عَلَيْهِمْ ءَايَٰتِنَا ۗ قُلْ أَفَأُنَبِّئُكُم بِشَرٍّۢ مِّن ذَٰلِكُمُ ۗ ٱلنَّارُ وَعَدَهَا ٱللَّهُ ٱلَّذِينَ كَفَرُوا۟ ۖ وَبِئْسَ ٱلْمَصِيرُ', 'وإذا تتلى عليهم ءايتنا بينت تعرف فى وجوه الذين كفروا المنكر  يكادون يسطون بالذين يتلون عليهم ءايتنا  قل أفأنبئكم بشر من ذلكم  النار وعدها الله الذين كفروا  وبئس المصير', NULL, 340, 'local:hafs-text.json'),
  ('hafs-22-73', 'hafs', 22, 73, 'يَٰٓأَيُّهَا ٱلنَّاسُ ضُرِبَ مَثَلٌۭ فَٱسْتَمِعُوا۟ لَهُۥٓ ۚ إِنَّ ٱلَّذِينَ تَدْعُونَ مِن دُونِ ٱللَّهِ لَن يَخْلُقُوا۟ ذُبَابًۭا وَلَوِ ٱجْتَمَعُوا۟ لَهُۥ ۖ وَإِن يَسْلُبْهُمُ ٱلذُّبَابُ شَيْـًۭٔا لَّا يَسْتَنقِذُوهُ مِنْهُ ۚ ضَعُفَ ٱلطَّالِبُ وَٱلْمَطْلُوبُ', 'يأيها الناس ضرب مثل فاستمعوا له  إن الذين تدعون من دون الله لن يخلقوا ذبابا ولو اجتمعوا له  وإن يسلبهم الذباب شيا لا يستنقذوه منه  ضعف الطالب والمطلوب', NULL, 341, 'local:hafs-text.json'),
  ('hafs-22-74', 'hafs', 22, 74, 'مَا قَدَرُوا۟ ٱللَّهَ حَقَّ قَدْرِهِۦٓ ۗ إِنَّ ٱللَّهَ لَقَوِىٌّ عَزِيزٌ', 'ما قدروا الله حق قدره  إن الله لقوى عزيز', NULL, 341, 'local:hafs-text.json'),
  ('hafs-22-75', 'hafs', 22, 75, 'ٱللَّهُ يَصْطَفِى مِنَ ٱلْمَلَٰٓئِكَةِ رُسُلًۭا وَمِنَ ٱلنَّاسِ ۚ إِنَّ ٱللَّهَ سَمِيعٌۢ بَصِيرٌۭ', 'الله يصطفى من الملئكة رسلا ومن الناس  إن الله سميع بصير', NULL, 341, 'local:hafs-text.json'),
  ('hafs-22-76', 'hafs', 22, 76, 'يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ ۗ وَإِلَى ٱللَّهِ تُرْجَعُ ٱلْأُمُورُ', 'يعلم ما بين أيديهم وما خلفهم  وإلى الله ترجع الأمور', NULL, 341, 'local:hafs-text.json'),
  ('hafs-22-77', 'hafs', 22, 77, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱرْكَعُوا۟ وَٱسْجُدُوا۟ وَٱعْبُدُوا۟ رَبَّكُمْ وَٱفْعَلُوا۟ ٱلْخَيْرَ لَعَلَّكُمْ تُفْلِحُونَ ۩', 'يأيها الذين ءامنوا اركعوا واسجدوا واعبدوا ربكم وافعلوا الخير لعلكم تفلحون', NULL, 341, 'local:hafs-text.json'),
  ('hafs-22-78', 'hafs', 22, 78, 'وَجَٰهِدُوا۟ فِى ٱللَّهِ حَقَّ جِهَادِهِۦ ۚ هُوَ ٱجْتَبَىٰكُمْ وَمَا جَعَلَ عَلَيْكُمْ فِى ٱلدِّينِ مِنْ حَرَجٍۢ ۚ مِّلَّةَ أَبِيكُمْ إِبْرَٰهِيمَ ۚ هُوَ سَمَّىٰكُمُ ٱلْمُسْلِمِينَ مِن قَبْلُ وَفِى هَٰذَا لِيَكُونَ ٱلرَّسُولُ شَهِيدًا عَلَيْكُمْ وَتَكُونُوا۟ شُهَدَآءَ عَلَى ٱلنَّاسِ ۚ فَأَقِيمُوا۟ ٱلصَّلَوٰةَ وَءَاتُوا۟ ٱلزَّكَوٰةَ وَٱعْتَصِمُوا۟ بِٱللَّهِ هُوَ مَوْلَىٰكُمْ ۖ فَنِعْمَ ٱلْمَوْلَىٰ وَنِعْمَ ٱلنَّصِيرُ', 'وجهدوا فى الله حق جهاده  هو اجتبىكم وما جعل عليكم فى الدين من حرج  ملة أبيكم إبرهيم  هو سمىكم المسلمين من قبل وفى هذا ليكون الرسول شهيدا عليكم وتكونوا شهداء على الناس  فأقيموا الصلوة وءاتوا الزكوة واعتصموا بالله هو مولىكم  فنعم المولى ونعم النصير', NULL, 341, 'local:hafs-text.json'),
  ('hafs-23-1', 'hafs', 23, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ قَدْ أَفْلَحَ ٱلْمُؤْمِنُونَ', 'بسم الله الرحمن الرحيم قد أفلح المؤمنون', NULL, 342, 'local:hafs-text.json'),
  ('hafs-23-2', 'hafs', 23, 2, 'ٱلَّذِينَ هُمْ فِى صَلَاتِهِمْ خَٰشِعُونَ', 'الذين هم فى صلاتهم خشعون', NULL, 342, 'local:hafs-text.json'),
  ('hafs-23-3', 'hafs', 23, 3, 'وَٱلَّذِينَ هُمْ عَنِ ٱللَّغْوِ مُعْرِضُونَ', 'والذين هم عن اللغو معرضون', NULL, 342, 'local:hafs-text.json'),
  ('hafs-23-4', 'hafs', 23, 4, 'وَٱلَّذِينَ هُمْ لِلزَّكَوٰةِ فَٰعِلُونَ', 'والذين هم للزكوة فعلون', NULL, 342, 'local:hafs-text.json'),
  ('hafs-23-5', 'hafs', 23, 5, 'وَٱلَّذِينَ هُمْ لِفُرُوجِهِمْ حَٰفِظُونَ', 'والذين هم لفروجهم حفظون', NULL, 342, 'local:hafs-text.json'),
  ('hafs-23-6', 'hafs', 23, 6, 'إِلَّا عَلَىٰٓ أَزْوَٰجِهِمْ أَوْ مَا مَلَكَتْ أَيْمَٰنُهُمْ فَإِنَّهُمْ غَيْرُ مَلُومِينَ', 'إلا على أزوجهم أو ما ملكت أيمنهم فإنهم غير ملومين', NULL, 342, 'local:hafs-text.json'),
  ('hafs-23-7', 'hafs', 23, 7, 'فَمَنِ ٱبْتَغَىٰ وَرَآءَ ذَٰلِكَ فَأُو۟لَٰٓئِكَ هُمُ ٱلْعَادُونَ', 'فمن ابتغى وراء ذلك فأولئك هم العادون', NULL, 342, 'local:hafs-text.json'),
  ('hafs-23-8', 'hafs', 23, 8, 'وَٱلَّذِينَ هُمْ لِأَمَٰنَٰتِهِمْ وَعَهْدِهِمْ رَٰعُونَ', 'والذين هم لأمنتهم وعهدهم رعون', NULL, 342, 'local:hafs-text.json'),
  ('hafs-23-9', 'hafs', 23, 9, 'وَٱلَّذِينَ هُمْ عَلَىٰ صَلَوَٰتِهِمْ يُحَافِظُونَ', 'والذين هم على صلوتهم يحافظون', NULL, 342, 'local:hafs-text.json'),
  ('hafs-23-10', 'hafs', 23, 10, 'أُو۟لَٰٓئِكَ هُمُ ٱلْوَٰرِثُونَ', 'أولئك هم الورثون', NULL, 342, 'local:hafs-text.json'),
  ('hafs-23-11', 'hafs', 23, 11, 'ٱلَّذِينَ يَرِثُونَ ٱلْفِرْدَوْسَ هُمْ فِيهَا خَٰلِدُونَ', 'الذين يرثون الفردوس هم فيها خلدون', NULL, 342, 'local:hafs-text.json'),
  ('hafs-23-12', 'hafs', 23, 12, 'وَلَقَدْ خَلَقْنَا ٱلْإِنسَٰنَ مِن سُلَٰلَةٍۢ مِّن طِينٍۢ', 'ولقد خلقنا الإنسن من سللة من طين', NULL, 342, 'local:hafs-text.json'),
  ('hafs-23-13', 'hafs', 23, 13, 'ثُمَّ جَعَلْنَٰهُ نُطْفَةًۭ فِى قَرَارٍۢ مَّكِينٍۢ', 'ثم جعلنه نطفة فى قرار مكين', NULL, 342, 'local:hafs-text.json'),
  ('hafs-23-14', 'hafs', 23, 14, 'ثُمَّ خَلَقْنَا ٱلنُّطْفَةَ عَلَقَةًۭ فَخَلَقْنَا ٱلْعَلَقَةَ مُضْغَةًۭ فَخَلَقْنَا ٱلْمُضْغَةَ عِظَٰمًۭا فَكَسَوْنَا ٱلْعِظَٰمَ لَحْمًۭا ثُمَّ أَنشَأْنَٰهُ خَلْقًا ءَاخَرَ ۚ فَتَبَارَكَ ٱللَّهُ أَحْسَنُ ٱلْخَٰلِقِينَ', 'ثم خلقنا النطفة علقة فخلقنا العلقة مضغة فخلقنا المضغة عظما فكسونا العظم لحما ثم أنشأنه خلقا ءاخر  فتبارك الله أحسن الخلقين', NULL, 342, 'local:hafs-text.json'),
  ('hafs-23-15', 'hafs', 23, 15, 'ثُمَّ إِنَّكُم بَعْدَ ذَٰلِكَ لَمَيِّتُونَ', 'ثم إنكم بعد ذلك لميتون', NULL, 342, 'local:hafs-text.json'),
  ('hafs-23-16', 'hafs', 23, 16, 'ثُمَّ إِنَّكُمْ يَوْمَ ٱلْقِيَٰمَةِ تُبْعَثُونَ', 'ثم إنكم يوم القيمة تبعثون', NULL, 342, 'local:hafs-text.json'),
  ('hafs-23-17', 'hafs', 23, 17, 'وَلَقَدْ خَلَقْنَا فَوْقَكُمْ سَبْعَ طَرَآئِقَ وَمَا كُنَّا عَنِ ٱلْخَلْقِ غَٰفِلِينَ', 'ولقد خلقنا فوقكم سبع طرائق وما كنا عن الخلق غفلين', NULL, 342, 'local:hafs-text.json'),
  ('hafs-23-18', 'hafs', 23, 18, 'وَأَنزَلْنَا مِنَ ٱلسَّمَآءِ مَآءًۢ بِقَدَرٍۢ فَأَسْكَنَّٰهُ فِى ٱلْأَرْضِ ۖ وَإِنَّا عَلَىٰ ذَهَابٍۭ بِهِۦ لَقَٰدِرُونَ', 'وأنزلنا من السماء ماء بقدر فأسكنه فى الأرض  وإنا على ذهاب به لقدرون', NULL, 343, 'local:hafs-text.json'),
  ('hafs-23-19', 'hafs', 23, 19, 'فَأَنشَأْنَا لَكُم بِهِۦ جَنَّٰتٍۢ مِّن نَّخِيلٍۢ وَأَعْنَٰبٍۢ لَّكُمْ فِيهَا فَوَٰكِهُ كَثِيرَةٌۭ وَمِنْهَا تَأْكُلُونَ', 'فأنشأنا لكم به جنت من نخيل وأعنب لكم فيها فوكه كثيرة ومنها تأكلون', NULL, 343, 'local:hafs-text.json'),
  ('hafs-23-20', 'hafs', 23, 20, 'وَشَجَرَةًۭ تَخْرُجُ مِن طُورِ سَيْنَآءَ تَنۢبُتُ بِٱلدُّهْنِ وَصِبْغٍۢ لِّلْءَاكِلِينَ', 'وشجرة تخرج من طور سيناء تنبت بالدهن وصبغ للءاكلين', NULL, 343, 'local:hafs-text.json'),
  ('hafs-23-21', 'hafs', 23, 21, 'وَإِنَّ لَكُمْ فِى ٱلْأَنْعَٰمِ لَعِبْرَةًۭ ۖ نُّسْقِيكُم مِّمَّا فِى بُطُونِهَا وَلَكُمْ فِيهَا مَنَٰفِعُ كَثِيرَةٌۭ وَمِنْهَا تَأْكُلُونَ', 'وإن لكم فى الأنعم لعبرة  نسقيكم مما فى بطونها ولكم فيها منفع كثيرة ومنها تأكلون', NULL, 343, 'local:hafs-text.json'),
  ('hafs-23-22', 'hafs', 23, 22, 'وَعَلَيْهَا وَعَلَى ٱلْفُلْكِ تُحْمَلُونَ', 'وعليها وعلى الفلك تحملون', NULL, 343, 'local:hafs-text.json'),
  ('hafs-23-23', 'hafs', 23, 23, 'وَلَقَدْ أَرْسَلْنَا نُوحًا إِلَىٰ قَوْمِهِۦ فَقَالَ يَٰقَوْمِ ٱعْبُدُوا۟ ٱللَّهَ مَا لَكُم مِّنْ إِلَٰهٍ غَيْرُهُۥٓ ۖ أَفَلَا تَتَّقُونَ', 'ولقد أرسلنا نوحا إلى قومه فقال يقوم اعبدوا الله ما لكم من إله غيره  أفلا تتقون', NULL, 343, 'local:hafs-text.json'),
  ('hafs-23-24', 'hafs', 23, 24, 'فَقَالَ ٱلْمَلَؤُا۟ ٱلَّذِينَ كَفَرُوا۟ مِن قَوْمِهِۦ مَا هَٰذَآ إِلَّا بَشَرٌۭ مِّثْلُكُمْ يُرِيدُ أَن يَتَفَضَّلَ عَلَيْكُمْ وَلَوْ شَآءَ ٱللَّهُ لَأَنزَلَ مَلَٰٓئِكَةًۭ مَّا سَمِعْنَا بِهَٰذَا فِىٓ ءَابَآئِنَا ٱلْأَوَّلِينَ', 'فقال الملؤا الذين كفروا من قومه ما هذا إلا بشر مثلكم يريد أن يتفضل عليكم ولو شاء الله لأنزل ملئكة ما سمعنا بهذا فى ءابائنا الأولين', NULL, 343, 'local:hafs-text.json'),
  ('hafs-23-25', 'hafs', 23, 25, 'إِنْ هُوَ إِلَّا رَجُلٌۢ بِهِۦ جِنَّةٌۭ فَتَرَبَّصُوا۟ بِهِۦ حَتَّىٰ حِينٍۢ', 'إن هو إلا رجل به جنة فتربصوا به حتى حين', NULL, 343, 'local:hafs-text.json'),
  ('hafs-23-26', 'hafs', 23, 26, 'قَالَ رَبِّ ٱنصُرْنِى بِمَا كَذَّبُونِ', 'قال رب انصرنى بما كذبون', NULL, 343, 'local:hafs-text.json'),
  ('hafs-23-27', 'hafs', 23, 27, 'فَأَوْحَيْنَآ إِلَيْهِ أَنِ ٱصْنَعِ ٱلْفُلْكَ بِأَعْيُنِنَا وَوَحْيِنَا فَإِذَا جَآءَ أَمْرُنَا وَفَارَ ٱلتَّنُّورُ ۙ فَٱسْلُكْ فِيهَا مِن كُلٍّۢ زَوْجَيْنِ ٱثْنَيْنِ وَأَهْلَكَ إِلَّا مَن سَبَقَ عَلَيْهِ ٱلْقَوْلُ مِنْهُمْ ۖ وَلَا تُخَٰطِبْنِى فِى ٱلَّذِينَ ظَلَمُوٓا۟ ۖ إِنَّهُم مُّغْرَقُونَ', 'فأوحينا إليه أن اصنع الفلك بأعيننا ووحينا فإذا جاء أمرنا وفار التنور  فاسلك فيها من كل زوجين اثنين وأهلك إلا من سبق عليه القول منهم  ولا تخطبنى فى الذين ظلموا  إنهم مغرقون', NULL, 343, 'local:hafs-text.json'),
  ('hafs-23-28', 'hafs', 23, 28, 'فَإِذَا ٱسْتَوَيْتَ أَنتَ وَمَن مَّعَكَ عَلَى ٱلْفُلْكِ فَقُلِ ٱلْحَمْدُ لِلَّهِ ٱلَّذِى نَجَّىٰنَا مِنَ ٱلْقَوْمِ ٱلظَّٰلِمِينَ', 'فإذا استويت أنت ومن معك على الفلك فقل الحمد لله الذى نجىنا من القوم الظلمين', NULL, 344, 'local:hafs-text.json'),
  ('hafs-23-29', 'hafs', 23, 29, 'وَقُل رَّبِّ أَنزِلْنِى مُنزَلًۭا مُّبَارَكًۭا وَأَنتَ خَيْرُ ٱلْمُنزِلِينَ', 'وقل رب أنزلنى منزلا مباركا وأنت خير المنزلين', NULL, 344, 'local:hafs-text.json'),
  ('hafs-23-30', 'hafs', 23, 30, 'إِنَّ فِى ذَٰلِكَ لَءَايَٰتٍۢ وَإِن كُنَّا لَمُبْتَلِينَ', 'إن فى ذلك لءايت وإن كنا لمبتلين', NULL, 344, 'local:hafs-text.json'),
  ('hafs-23-31', 'hafs', 23, 31, 'ثُمَّ أَنشَأْنَا مِنۢ بَعْدِهِمْ قَرْنًا ءَاخَرِينَ', 'ثم أنشأنا من بعدهم قرنا ءاخرين', NULL, 344, 'local:hafs-text.json'),
  ('hafs-23-32', 'hafs', 23, 32, 'فَأَرْسَلْنَا فِيهِمْ رَسُولًۭا مِّنْهُمْ أَنِ ٱعْبُدُوا۟ ٱللَّهَ مَا لَكُم مِّنْ إِلَٰهٍ غَيْرُهُۥٓ ۖ أَفَلَا تَتَّقُونَ', 'فأرسلنا فيهم رسولا منهم أن اعبدوا الله ما لكم من إله غيره  أفلا تتقون', NULL, 344, 'local:hafs-text.json'),
  ('hafs-23-33', 'hafs', 23, 33, 'وَقَالَ ٱلْمَلَأُ مِن قَوْمِهِ ٱلَّذِينَ كَفَرُوا۟ وَكَذَّبُوا۟ بِلِقَآءِ ٱلْءَاخِرَةِ وَأَتْرَفْنَٰهُمْ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا مَا هَٰذَآ إِلَّا بَشَرٌۭ مِّثْلُكُمْ يَأْكُلُ مِمَّا تَأْكُلُونَ مِنْهُ وَيَشْرَبُ مِمَّا تَشْرَبُونَ', 'وقال الملأ من قومه الذين كفروا وكذبوا بلقاء الءاخرة وأترفنهم فى الحيوة الدنيا ما هذا إلا بشر مثلكم يأكل مما تأكلون منه ويشرب مما تشربون', NULL, 344, 'local:hafs-text.json'),
  ('hafs-23-34', 'hafs', 23, 34, 'وَلَئِنْ أَطَعْتُم بَشَرًۭا مِّثْلَكُمْ إِنَّكُمْ إِذًۭا لَّخَٰسِرُونَ', 'ولئن أطعتم بشرا مثلكم إنكم إذا لخسرون', NULL, 344, 'local:hafs-text.json'),
  ('hafs-23-35', 'hafs', 23, 35, 'أَيَعِدُكُمْ أَنَّكُمْ إِذَا مِتُّمْ وَكُنتُمْ تُرَابًۭا وَعِظَٰمًا أَنَّكُم مُّخْرَجُونَ', 'أيعدكم أنكم إذا متم وكنتم ترابا وعظما أنكم مخرجون', NULL, 344, 'local:hafs-text.json'),
  ('hafs-23-36', 'hafs', 23, 36, '۞ هَيْهَاتَ هَيْهَاتَ لِمَا تُوعَدُونَ', 'هيهات هيهات لما توعدون', NULL, 344, 'local:hafs-text.json'),
  ('hafs-23-37', 'hafs', 23, 37, 'إِنْ هِىَ إِلَّا حَيَاتُنَا ٱلدُّنْيَا نَمُوتُ وَنَحْيَا وَمَا نَحْنُ بِمَبْعُوثِينَ', 'إن هى إلا حياتنا الدنيا نموت ونحيا وما نحن بمبعوثين', NULL, 344, 'local:hafs-text.json'),
  ('hafs-23-38', 'hafs', 23, 38, 'إِنْ هُوَ إِلَّا رَجُلٌ ٱفْتَرَىٰ عَلَى ٱللَّهِ كَذِبًۭا وَمَا نَحْنُ لَهُۥ بِمُؤْمِنِينَ', 'إن هو إلا رجل افترى على الله كذبا وما نحن له بمؤمنين', NULL, 344, 'local:hafs-text.json'),
  ('hafs-23-39', 'hafs', 23, 39, 'قَالَ رَبِّ ٱنصُرْنِى بِمَا كَذَّبُونِ', 'قال رب انصرنى بما كذبون', NULL, 344, 'local:hafs-text.json'),
  ('hafs-23-40', 'hafs', 23, 40, 'قَالَ عَمَّا قَلِيلٍۢ لَّيُصْبِحُنَّ نَٰدِمِينَ', 'قال عما قليل ليصبحن ندمين', NULL, 344, 'local:hafs-text.json'),
  ('hafs-23-41', 'hafs', 23, 41, 'فَأَخَذَتْهُمُ ٱلصَّيْحَةُ بِٱلْحَقِّ فَجَعَلْنَٰهُمْ غُثَآءًۭ ۚ فَبُعْدًۭا لِّلْقَوْمِ ٱلظَّٰلِمِينَ', 'فأخذتهم الصيحة بالحق فجعلنهم غثاء  فبعدا للقوم الظلمين', NULL, 344, 'local:hafs-text.json'),
  ('hafs-23-42', 'hafs', 23, 42, 'ثُمَّ أَنشَأْنَا مِنۢ بَعْدِهِمْ قُرُونًا ءَاخَرِينَ', 'ثم أنشأنا من بعدهم قرونا ءاخرين', NULL, 344, 'local:hafs-text.json'),
  ('hafs-23-43', 'hafs', 23, 43, 'مَا تَسْبِقُ مِنْ أُمَّةٍ أَجَلَهَا وَمَا يَسْتَـْٔخِرُونَ', 'ما تسبق من أمة أجلها وما يستخرون', NULL, 345, 'local:hafs-text.json'),
  ('hafs-23-44', 'hafs', 23, 44, 'ثُمَّ أَرْسَلْنَا رُسُلَنَا تَتْرَا ۖ كُلَّ مَا جَآءَ أُمَّةًۭ رَّسُولُهَا كَذَّبُوهُ ۚ فَأَتْبَعْنَا بَعْضَهُم بَعْضًۭا وَجَعَلْنَٰهُمْ أَحَادِيثَ ۚ فَبُعْدًۭا لِّقَوْمٍۢ لَّا يُؤْمِنُونَ', 'ثم أرسلنا رسلنا تترا  كل ما جاء أمة رسولها كذبوه  فأتبعنا بعضهم بعضا وجعلنهم أحاديث  فبعدا لقوم لا يؤمنون', NULL, 345, 'local:hafs-text.json'),
  ('hafs-23-45', 'hafs', 23, 45, 'ثُمَّ أَرْسَلْنَا مُوسَىٰ وَأَخَاهُ هَٰرُونَ بِـَٔايَٰتِنَا وَسُلْطَٰنٍۢ مُّبِينٍ', 'ثم أرسلنا موسى وأخاه هرون بايتنا وسلطن مبين', NULL, 345, 'local:hafs-text.json'),
  ('hafs-23-46', 'hafs', 23, 46, 'إِلَىٰ فِرْعَوْنَ وَمَلَإِي۟هِۦ فَٱسْتَكْبَرُوا۟ وَكَانُوا۟ قَوْمًا عَالِينَ', 'إلى فرعون وملإيه فاستكبروا وكانوا قوما عالين', NULL, 345, 'local:hafs-text.json'),
  ('hafs-23-47', 'hafs', 23, 47, 'فَقَالُوٓا۟ أَنُؤْمِنُ لِبَشَرَيْنِ مِثْلِنَا وَقَوْمُهُمَا لَنَا عَٰبِدُونَ', 'فقالوا أنؤمن لبشرين مثلنا وقومهما لنا عبدون', NULL, 345, 'local:hafs-text.json'),
  ('hafs-23-48', 'hafs', 23, 48, 'فَكَذَّبُوهُمَا فَكَانُوا۟ مِنَ ٱلْمُهْلَكِينَ', 'فكذبوهما فكانوا من المهلكين', NULL, 345, 'local:hafs-text.json'),
  ('hafs-23-49', 'hafs', 23, 49, 'وَلَقَدْ ءَاتَيْنَا مُوسَى ٱلْكِتَٰبَ لَعَلَّهُمْ يَهْتَدُونَ', 'ولقد ءاتينا موسى الكتب لعلهم يهتدون', NULL, 345, 'local:hafs-text.json'),
  ('hafs-23-50', 'hafs', 23, 50, 'وَجَعَلْنَا ٱبْنَ مَرْيَمَ وَأُمَّهُۥٓ ءَايَةًۭ وَءَاوَيْنَٰهُمَآ إِلَىٰ رَبْوَةٍۢ ذَاتِ قَرَارٍۢ وَمَعِينٍۢ', 'وجعلنا ابن مريم وأمه ءاية وءاوينهما إلى ربوة ذات قرار ومعين', NULL, 345, 'local:hafs-text.json'),
  ('hafs-23-51', 'hafs', 23, 51, 'يَٰٓأَيُّهَا ٱلرُّسُلُ كُلُوا۟ مِنَ ٱلطَّيِّبَٰتِ وَٱعْمَلُوا۟ صَٰلِحًا ۖ إِنِّى بِمَا تَعْمَلُونَ عَلِيمٌۭ', 'يأيها الرسل كلوا من الطيبت واعملوا صلحا  إنى بما تعملون عليم', NULL, 345, 'local:hafs-text.json'),
  ('hafs-23-52', 'hafs', 23, 52, 'وَإِنَّ هَٰذِهِۦٓ أُمَّتُكُمْ أُمَّةًۭ وَٰحِدَةًۭ وَأَنَا۠ رَبُّكُمْ فَٱتَّقُونِ', 'وإن هذه أمتكم أمة وحدة وأنا ربكم فاتقون', NULL, 345, 'local:hafs-text.json'),
  ('hafs-23-53', 'hafs', 23, 53, 'فَتَقَطَّعُوٓا۟ أَمْرَهُم بَيْنَهُمْ زُبُرًۭا ۖ كُلُّ حِزْبٍۭ بِمَا لَدَيْهِمْ فَرِحُونَ', 'فتقطعوا أمرهم بينهم زبرا  كل حزب بما لديهم فرحون', NULL, 345, 'local:hafs-text.json'),
  ('hafs-23-54', 'hafs', 23, 54, 'فَذَرْهُمْ فِى غَمْرَتِهِمْ حَتَّىٰ حِينٍ', 'فذرهم فى غمرتهم حتى حين', NULL, 345, 'local:hafs-text.json'),
  ('hafs-23-55', 'hafs', 23, 55, 'أَيَحْسَبُونَ أَنَّمَا نُمِدُّهُم بِهِۦ مِن مَّالٍۢ وَبَنِينَ', 'أيحسبون أنما نمدهم به من مال وبنين', NULL, 345, 'local:hafs-text.json'),
  ('hafs-23-56', 'hafs', 23, 56, 'نُسَارِعُ لَهُمْ فِى ٱلْخَيْرَٰتِ ۚ بَل لَّا يَشْعُرُونَ', 'نسارع لهم فى الخيرت  بل لا يشعرون', NULL, 345, 'local:hafs-text.json'),
  ('hafs-23-57', 'hafs', 23, 57, 'إِنَّ ٱلَّذِينَ هُم مِّنْ خَشْيَةِ رَبِّهِم مُّشْفِقُونَ', 'إن الذين هم من خشية ربهم مشفقون', NULL, 345, 'local:hafs-text.json'),
  ('hafs-23-58', 'hafs', 23, 58, 'وَٱلَّذِينَ هُم بِـَٔايَٰتِ رَبِّهِمْ يُؤْمِنُونَ', 'والذين هم بايت ربهم يؤمنون', NULL, 345, 'local:hafs-text.json'),
  ('hafs-23-59', 'hafs', 23, 59, 'وَٱلَّذِينَ هُم بِرَبِّهِمْ لَا يُشْرِكُونَ', 'والذين هم بربهم لا يشركون', NULL, 345, 'local:hafs-text.json'),
  ('hafs-23-60', 'hafs', 23, 60, 'وَٱلَّذِينَ يُؤْتُونَ مَآ ءَاتَوا۟ وَّقُلُوبُهُمْ وَجِلَةٌ أَنَّهُمْ إِلَىٰ رَبِّهِمْ رَٰجِعُونَ', 'والذين يؤتون ما ءاتوا وقلوبهم وجلة أنهم إلى ربهم رجعون', NULL, 346, 'local:hafs-text.json'),
  ('hafs-23-61', 'hafs', 23, 61, 'أُو۟لَٰٓئِكَ يُسَٰرِعُونَ فِى ٱلْخَيْرَٰتِ وَهُمْ لَهَا سَٰبِقُونَ', 'أولئك يسرعون فى الخيرت وهم لها سبقون', NULL, 346, 'local:hafs-text.json'),
  ('hafs-23-62', 'hafs', 23, 62, 'وَلَا نُكَلِّفُ نَفْسًا إِلَّا وُسْعَهَا ۖ وَلَدَيْنَا كِتَٰبٌۭ يَنطِقُ بِٱلْحَقِّ ۚ وَهُمْ لَا يُظْلَمُونَ', 'ولا نكلف نفسا إلا وسعها  ولدينا كتب ينطق بالحق  وهم لا يظلمون', NULL, 346, 'local:hafs-text.json'),
  ('hafs-23-63', 'hafs', 23, 63, 'بَلْ قُلُوبُهُمْ فِى غَمْرَةٍۢ مِّنْ هَٰذَا وَلَهُمْ أَعْمَٰلٌۭ مِّن دُونِ ذَٰلِكَ هُمْ لَهَا عَٰمِلُونَ', 'بل قلوبهم فى غمرة من هذا ولهم أعمل من دون ذلك هم لها عملون', NULL, 346, 'local:hafs-text.json'),
  ('hafs-23-64', 'hafs', 23, 64, 'حَتَّىٰٓ إِذَآ أَخَذْنَا مُتْرَفِيهِم بِٱلْعَذَابِ إِذَا هُمْ يَجْـَٔرُونَ', 'حتى إذا أخذنا مترفيهم بالعذاب إذا هم يجرون', NULL, 346, 'local:hafs-text.json'),
  ('hafs-23-65', 'hafs', 23, 65, 'لَا تَجْـَٔرُوا۟ ٱلْيَوْمَ ۖ إِنَّكُم مِّنَّا لَا تُنصَرُونَ', 'لا تجروا اليوم  إنكم منا لا تنصرون', NULL, 346, 'local:hafs-text.json'),
  ('hafs-23-66', 'hafs', 23, 66, 'قَدْ كَانَتْ ءَايَٰتِى تُتْلَىٰ عَلَيْكُمْ فَكُنتُمْ عَلَىٰٓ أَعْقَٰبِكُمْ تَنكِصُونَ', 'قد كانت ءايتى تتلى عليكم فكنتم على أعقبكم تنكصون', NULL, 346, 'local:hafs-text.json'),
  ('hafs-23-67', 'hafs', 23, 67, 'مُسْتَكْبِرِينَ بِهِۦ سَٰمِرًۭا تَهْجُرُونَ', 'مستكبرين به سمرا تهجرون', NULL, 346, 'local:hafs-text.json'),
  ('hafs-23-68', 'hafs', 23, 68, 'أَفَلَمْ يَدَّبَّرُوا۟ ٱلْقَوْلَ أَمْ جَآءَهُم مَّا لَمْ يَأْتِ ءَابَآءَهُمُ ٱلْأَوَّلِينَ', 'أفلم يدبروا القول أم جاءهم ما لم يأت ءاباءهم الأولين', NULL, 346, 'local:hafs-text.json'),
  ('hafs-23-69', 'hafs', 23, 69, 'أَمْ لَمْ يَعْرِفُوا۟ رَسُولَهُمْ فَهُمْ لَهُۥ مُنكِرُونَ', 'أم لم يعرفوا رسولهم فهم له منكرون', NULL, 346, 'local:hafs-text.json'),
  ('hafs-23-70', 'hafs', 23, 70, 'أَمْ يَقُولُونَ بِهِۦ جِنَّةٌۢ ۚ بَلْ جَآءَهُم بِٱلْحَقِّ وَأَكْثَرُهُمْ لِلْحَقِّ كَٰرِهُونَ', 'أم يقولون به جنة  بل جاءهم بالحق وأكثرهم للحق كرهون', NULL, 346, 'local:hafs-text.json'),
  ('hafs-23-71', 'hafs', 23, 71, 'وَلَوِ ٱتَّبَعَ ٱلْحَقُّ أَهْوَآءَهُمْ لَفَسَدَتِ ٱلسَّمَٰوَٰتُ وَٱلْأَرْضُ وَمَن فِيهِنَّ ۚ بَلْ أَتَيْنَٰهُم بِذِكْرِهِمْ فَهُمْ عَن ذِكْرِهِم مُّعْرِضُونَ', 'ولو اتبع الحق أهواءهم لفسدت السموت والأرض ومن فيهن  بل أتينهم بذكرهم فهم عن ذكرهم معرضون', NULL, 346, 'local:hafs-text.json'),
  ('hafs-23-72', 'hafs', 23, 72, 'أَمْ تَسْـَٔلُهُمْ خَرْجًۭا فَخَرَاجُ رَبِّكَ خَيْرٌۭ ۖ وَهُوَ خَيْرُ ٱلرَّٰزِقِينَ', 'أم تسلهم خرجا فخراج ربك خير  وهو خير الرزقين', NULL, 346, 'local:hafs-text.json'),
  ('hafs-23-73', 'hafs', 23, 73, 'وَإِنَّكَ لَتَدْعُوهُمْ إِلَىٰ صِرَٰطٍۢ مُّسْتَقِيمٍۢ', 'وإنك لتدعوهم إلى صرط مستقيم', NULL, 346, 'local:hafs-text.json'),
  ('hafs-23-74', 'hafs', 23, 74, 'وَإِنَّ ٱلَّذِينَ لَا يُؤْمِنُونَ بِٱلْءَاخِرَةِ عَنِ ٱلصِّرَٰطِ لَنَٰكِبُونَ', 'وإن الذين لا يؤمنون بالءاخرة عن الصرط لنكبون', NULL, 346, 'local:hafs-text.json'),
  ('hafs-23-75', 'hafs', 23, 75, '۞ وَلَوْ رَحِمْنَٰهُمْ وَكَشَفْنَا مَا بِهِم مِّن ضُرٍّۢ لَّلَجُّوا۟ فِى طُغْيَٰنِهِمْ يَعْمَهُونَ', 'ولو رحمنهم وكشفنا ما بهم من ضر للجوا فى طغينهم يعمهون', NULL, 347, 'local:hafs-text.json'),
  ('hafs-23-76', 'hafs', 23, 76, 'وَلَقَدْ أَخَذْنَٰهُم بِٱلْعَذَابِ فَمَا ٱسْتَكَانُوا۟ لِرَبِّهِمْ وَمَا يَتَضَرَّعُونَ', 'ولقد أخذنهم بالعذاب فما استكانوا لربهم وما يتضرعون', NULL, 347, 'local:hafs-text.json'),
  ('hafs-23-77', 'hafs', 23, 77, 'حَتَّىٰٓ إِذَا فَتَحْنَا عَلَيْهِم بَابًۭا ذَا عَذَابٍۢ شَدِيدٍ إِذَا هُمْ فِيهِ مُبْلِسُونَ', 'حتى إذا فتحنا عليهم بابا ذا عذاب شديد إذا هم فيه مبلسون', NULL, 347, 'local:hafs-text.json'),
  ('hafs-23-78', 'hafs', 23, 78, 'وَهُوَ ٱلَّذِىٓ أَنشَأَ لَكُمُ ٱلسَّمْعَ وَٱلْأَبْصَٰرَ وَٱلْأَفْـِٔدَةَ ۚ قَلِيلًۭا مَّا تَشْكُرُونَ', 'وهو الذى أنشأ لكم السمع والأبصر والأفدة  قليلا ما تشكرون', NULL, 347, 'local:hafs-text.json'),
  ('hafs-23-79', 'hafs', 23, 79, 'وَهُوَ ٱلَّذِى ذَرَأَكُمْ فِى ٱلْأَرْضِ وَإِلَيْهِ تُحْشَرُونَ', 'وهو الذى ذرأكم فى الأرض وإليه تحشرون', NULL, 347, 'local:hafs-text.json'),
  ('hafs-23-80', 'hafs', 23, 80, 'وَهُوَ ٱلَّذِى يُحْىِۦ وَيُمِيتُ وَلَهُ ٱخْتِلَٰفُ ٱلَّيْلِ وَٱلنَّهَارِ ۚ أَفَلَا تَعْقِلُونَ', 'وهو الذى يحى ويميت وله اختلف اليل والنهار  أفلا تعقلون', NULL, 347, 'local:hafs-text.json'),
  ('hafs-23-81', 'hafs', 23, 81, 'بَلْ قَالُوا۟ مِثْلَ مَا قَالَ ٱلْأَوَّلُونَ', 'بل قالوا مثل ما قال الأولون', NULL, 347, 'local:hafs-text.json'),
  ('hafs-23-82', 'hafs', 23, 82, 'قَالُوٓا۟ أَءِذَا مِتْنَا وَكُنَّا تُرَابًۭا وَعِظَٰمًا أَءِنَّا لَمَبْعُوثُونَ', 'قالوا أءذا متنا وكنا ترابا وعظما أءنا لمبعوثون', NULL, 347, 'local:hafs-text.json'),
  ('hafs-23-83', 'hafs', 23, 83, 'لَقَدْ وُعِدْنَا نَحْنُ وَءَابَآؤُنَا هَٰذَا مِن قَبْلُ إِنْ هَٰذَآ إِلَّآ أَسَٰطِيرُ ٱلْأَوَّلِينَ', 'لقد وعدنا نحن وءاباؤنا هذا من قبل إن هذا إلا أسطير الأولين', NULL, 347, 'local:hafs-text.json'),
  ('hafs-23-84', 'hafs', 23, 84, 'قُل لِّمَنِ ٱلْأَرْضُ وَمَن فِيهَآ إِن كُنتُمْ تَعْلَمُونَ', 'قل لمن الأرض ومن فيها إن كنتم تعلمون', NULL, 347, 'local:hafs-text.json'),
  ('hafs-23-85', 'hafs', 23, 85, 'سَيَقُولُونَ لِلَّهِ ۚ قُلْ أَفَلَا تَذَكَّرُونَ', 'سيقولون لله  قل أفلا تذكرون', NULL, 347, 'local:hafs-text.json'),
  ('hafs-23-86', 'hafs', 23, 86, 'قُلْ مَن رَّبُّ ٱلسَّمَٰوَٰتِ ٱلسَّبْعِ وَرَبُّ ٱلْعَرْشِ ٱلْعَظِيمِ', 'قل من رب السموت السبع ورب العرش العظيم', NULL, 347, 'local:hafs-text.json'),
  ('hafs-23-87', 'hafs', 23, 87, 'سَيَقُولُونَ لِلَّهِ ۚ قُلْ أَفَلَا تَتَّقُونَ', 'سيقولون لله  قل أفلا تتقون', NULL, 347, 'local:hafs-text.json'),
  ('hafs-23-88', 'hafs', 23, 88, 'قُلْ مَنۢ بِيَدِهِۦ مَلَكُوتُ كُلِّ شَىْءٍۢ وَهُوَ يُجِيرُ وَلَا يُجَارُ عَلَيْهِ إِن كُنتُمْ تَعْلَمُونَ', 'قل من بيده ملكوت كل شىء وهو يجير ولا يجار عليه إن كنتم تعلمون', NULL, 347, 'local:hafs-text.json'),
  ('hafs-23-89', 'hafs', 23, 89, 'سَيَقُولُونَ لِلَّهِ ۚ قُلْ فَأَنَّىٰ تُسْحَرُونَ', 'سيقولون لله  قل فأنى تسحرون', NULL, 347, 'local:hafs-text.json'),
  ('hafs-23-90', 'hafs', 23, 90, 'بَلْ أَتَيْنَٰهُم بِٱلْحَقِّ وَإِنَّهُمْ لَكَٰذِبُونَ', 'بل أتينهم بالحق وإنهم لكذبون', NULL, 348, 'local:hafs-text.json'),
  ('hafs-23-91', 'hafs', 23, 91, 'مَا ٱتَّخَذَ ٱللَّهُ مِن وَلَدٍۢ وَمَا كَانَ مَعَهُۥ مِنْ إِلَٰهٍ ۚ إِذًۭا لَّذَهَبَ كُلُّ إِلَٰهٍۭ بِمَا خَلَقَ وَلَعَلَا بَعْضُهُمْ عَلَىٰ بَعْضٍۢ ۚ سُبْحَٰنَ ٱللَّهِ عَمَّا يَصِفُونَ', 'ما اتخذ الله من ولد وما كان معه من إله  إذا لذهب كل إله بما خلق ولعلا بعضهم على بعض  سبحن الله عما يصفون', NULL, 348, 'local:hafs-text.json'),
  ('hafs-23-92', 'hafs', 23, 92, 'عَٰلِمِ ٱلْغَيْبِ وَٱلشَّهَٰدَةِ فَتَعَٰلَىٰ عَمَّا يُشْرِكُونَ', 'علم الغيب والشهدة فتعلى عما يشركون', NULL, 348, 'local:hafs-text.json'),
  ('hafs-23-93', 'hafs', 23, 93, 'قُل رَّبِّ إِمَّا تُرِيَنِّى مَا يُوعَدُونَ', 'قل رب إما ترينى ما يوعدون', NULL, 348, 'local:hafs-text.json'),
  ('hafs-23-94', 'hafs', 23, 94, 'رَبِّ فَلَا تَجْعَلْنِى فِى ٱلْقَوْمِ ٱلظَّٰلِمِينَ', 'رب فلا تجعلنى فى القوم الظلمين', NULL, 348, 'local:hafs-text.json'),
  ('hafs-23-95', 'hafs', 23, 95, 'وَإِنَّا عَلَىٰٓ أَن نُّرِيَكَ مَا نَعِدُهُمْ لَقَٰدِرُونَ', 'وإنا على أن نريك ما نعدهم لقدرون', NULL, 348, 'local:hafs-text.json'),
  ('hafs-23-96', 'hafs', 23, 96, 'ٱدْفَعْ بِٱلَّتِى هِىَ أَحْسَنُ ٱلسَّيِّئَةَ ۚ نَحْنُ أَعْلَمُ بِمَا يَصِفُونَ', 'ادفع بالتى هى أحسن السيئة  نحن أعلم بما يصفون', NULL, 348, 'local:hafs-text.json'),
  ('hafs-23-97', 'hafs', 23, 97, 'وَقُل رَّبِّ أَعُوذُ بِكَ مِنْ هَمَزَٰتِ ٱلشَّيَٰطِينِ', 'وقل رب أعوذ بك من همزت الشيطين', NULL, 348, 'local:hafs-text.json'),
  ('hafs-23-98', 'hafs', 23, 98, 'وَأَعُوذُ بِكَ رَبِّ أَن يَحْضُرُونِ', 'وأعوذ بك رب أن يحضرون', NULL, 348, 'local:hafs-text.json'),
  ('hafs-23-99', 'hafs', 23, 99, 'حَتَّىٰٓ إِذَا جَآءَ أَحَدَهُمُ ٱلْمَوْتُ قَالَ رَبِّ ٱرْجِعُونِ', 'حتى إذا جاء أحدهم الموت قال رب ارجعون', NULL, 348, 'local:hafs-text.json'),
  ('hafs-23-100', 'hafs', 23, 100, 'لَعَلِّىٓ أَعْمَلُ صَٰلِحًۭا فِيمَا تَرَكْتُ ۚ كَلَّآ ۚ إِنَّهَا كَلِمَةٌ هُوَ قَآئِلُهَا ۖ وَمِن وَرَآئِهِم بَرْزَخٌ إِلَىٰ يَوْمِ يُبْعَثُونَ', 'لعلى أعمل صلحا فيما تركت  كلا  إنها كلمة هو قائلها  ومن ورائهم برزخ إلى يوم يبعثون', NULL, 348, 'local:hafs-text.json'),
  ('hafs-23-101', 'hafs', 23, 101, 'فَإِذَا نُفِخَ فِى ٱلصُّورِ فَلَآ أَنسَابَ بَيْنَهُمْ يَوْمَئِذٍۢ وَلَا يَتَسَآءَلُونَ', 'فإذا نفخ فى الصور فلا أنساب بينهم يومئذ ولا يتساءلون', NULL, 348, 'local:hafs-text.json'),
  ('hafs-23-102', 'hafs', 23, 102, 'فَمَن ثَقُلَتْ مَوَٰزِينُهُۥ فَأُو۟لَٰٓئِكَ هُمُ ٱلْمُفْلِحُونَ', 'فمن ثقلت موزينه فأولئك هم المفلحون', NULL, 348, 'local:hafs-text.json'),
  ('hafs-23-103', 'hafs', 23, 103, 'وَمَنْ خَفَّتْ مَوَٰزِينُهُۥ فَأُو۟لَٰٓئِكَ ٱلَّذِينَ خَسِرُوٓا۟ أَنفُسَهُمْ فِى جَهَنَّمَ خَٰلِدُونَ', 'ومن خفت موزينه فأولئك الذين خسروا أنفسهم فى جهنم خلدون', NULL, 348, 'local:hafs-text.json'),
  ('hafs-23-104', 'hafs', 23, 104, 'تَلْفَحُ وُجُوهَهُمُ ٱلنَّارُ وَهُمْ فِيهَا كَٰلِحُونَ', 'تلفح وجوههم النار وهم فيها كلحون', NULL, 348, 'local:hafs-text.json'),
  ('hafs-23-105', 'hafs', 23, 105, 'أَلَمْ تَكُنْ ءَايَٰتِى تُتْلَىٰ عَلَيْكُمْ فَكُنتُم بِهَا تُكَذِّبُونَ', 'ألم تكن ءايتى تتلى عليكم فكنتم بها تكذبون', NULL, 349, 'local:hafs-text.json'),
  ('hafs-23-106', 'hafs', 23, 106, 'قَالُوا۟ رَبَّنَا غَلَبَتْ عَلَيْنَا شِقْوَتُنَا وَكُنَّا قَوْمًۭا ضَآلِّينَ', 'قالوا ربنا غلبت علينا شقوتنا وكنا قوما ضالين', NULL, 349, 'local:hafs-text.json'),
  ('hafs-23-107', 'hafs', 23, 107, 'رَبَّنَآ أَخْرِجْنَا مِنْهَا فَإِنْ عُدْنَا فَإِنَّا ظَٰلِمُونَ', 'ربنا أخرجنا منها فإن عدنا فإنا ظلمون', NULL, 349, 'local:hafs-text.json'),
  ('hafs-23-108', 'hafs', 23, 108, 'قَالَ ٱخْسَـُٔوا۟ فِيهَا وَلَا تُكَلِّمُونِ', 'قال اخسوا فيها ولا تكلمون', NULL, 349, 'local:hafs-text.json'),
  ('hafs-23-109', 'hafs', 23, 109, 'إِنَّهُۥ كَانَ فَرِيقٌۭ مِّنْ عِبَادِى يَقُولُونَ رَبَّنَآ ءَامَنَّا فَٱغْفِرْ لَنَا وَٱرْحَمْنَا وَأَنتَ خَيْرُ ٱلرَّٰحِمِينَ', 'إنه كان فريق من عبادى يقولون ربنا ءامنا فاغفر لنا وارحمنا وأنت خير الرحمين', NULL, 349, 'local:hafs-text.json'),
  ('hafs-23-110', 'hafs', 23, 110, 'فَٱتَّخَذْتُمُوهُمْ سِخْرِيًّا حَتَّىٰٓ أَنسَوْكُمْ ذِكْرِى وَكُنتُم مِّنْهُمْ تَضْحَكُونَ', 'فاتخذتموهم سخريا حتى أنسوكم ذكرى وكنتم منهم تضحكون', NULL, 349, 'local:hafs-text.json'),
  ('hafs-23-111', 'hafs', 23, 111, 'إِنِّى جَزَيْتُهُمُ ٱلْيَوْمَ بِمَا صَبَرُوٓا۟ أَنَّهُمْ هُمُ ٱلْفَآئِزُونَ', 'إنى جزيتهم اليوم بما صبروا أنهم هم الفائزون', NULL, 349, 'local:hafs-text.json'),
  ('hafs-23-112', 'hafs', 23, 112, 'قَٰلَ كَمْ لَبِثْتُمْ فِى ٱلْأَرْضِ عَدَدَ سِنِينَ', 'قل كم لبثتم فى الأرض عدد سنين', NULL, 349, 'local:hafs-text.json'),
  ('hafs-23-113', 'hafs', 23, 113, 'قَالُوا۟ لَبِثْنَا يَوْمًا أَوْ بَعْضَ يَوْمٍۢ فَسْـَٔلِ ٱلْعَآدِّينَ', 'قالوا لبثنا يوما أو بعض يوم فسل العادين', NULL, 349, 'local:hafs-text.json'),
  ('hafs-23-114', 'hafs', 23, 114, 'قَٰلَ إِن لَّبِثْتُمْ إِلَّا قَلِيلًۭا ۖ لَّوْ أَنَّكُمْ كُنتُمْ تَعْلَمُونَ', 'قل إن لبثتم إلا قليلا  لو أنكم كنتم تعلمون', NULL, 349, 'local:hafs-text.json'),
  ('hafs-23-115', 'hafs', 23, 115, 'أَفَحَسِبْتُمْ أَنَّمَا خَلَقْنَٰكُمْ عَبَثًۭا وَأَنَّكُمْ إِلَيْنَا لَا تُرْجَعُونَ', 'أفحسبتم أنما خلقنكم عبثا وأنكم إلينا لا ترجعون', NULL, 349, 'local:hafs-text.json'),
  ('hafs-23-116', 'hafs', 23, 116, 'فَتَعَٰلَى ٱللَّهُ ٱلْمَلِكُ ٱلْحَقُّ ۖ لَآ إِلَٰهَ إِلَّا هُوَ رَبُّ ٱلْعَرْشِ ٱلْكَرِيمِ', 'فتعلى الله الملك الحق  لا إله إلا هو رب العرش الكريم', NULL, 349, 'local:hafs-text.json'),
  ('hafs-23-117', 'hafs', 23, 117, 'وَمَن يَدْعُ مَعَ ٱللَّهِ إِلَٰهًا ءَاخَرَ لَا بُرْهَٰنَ لَهُۥ بِهِۦ فَإِنَّمَا حِسَابُهُۥ عِندَ رَبِّهِۦٓ ۚ إِنَّهُۥ لَا يُفْلِحُ ٱلْكَٰفِرُونَ', 'ومن يدع مع الله إلها ءاخر لا برهن له به فإنما حسابه عند ربه  إنه لا يفلح الكفرون', NULL, 349, 'local:hafs-text.json'),
  ('hafs-23-118', 'hafs', 23, 118, 'وَقُل رَّبِّ ٱغْفِرْ وَٱرْحَمْ وَأَنتَ خَيْرُ ٱلرَّٰحِمِينَ', 'وقل رب اغفر وارحم وأنت خير الرحمين', NULL, 349, 'local:hafs-text.json'),
  ('hafs-24-1', 'hafs', 24, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ سُورَةٌ أَنزَلْنَٰهَا وَفَرَضْنَٰهَا وَأَنزَلْنَا فِيهَآ ءَايَٰتٍۭ بَيِّنَٰتٍۢ لَّعَلَّكُمْ تَذَكَّرُونَ', 'بسم الله الرحمن الرحيم سورة أنزلنها وفرضنها وأنزلنا فيها ءايت بينت لعلكم تذكرون', NULL, 350, 'local:hafs-text.json'),
  ('hafs-24-2', 'hafs', 24, 2, 'ٱلزَّانِيَةُ وَٱلزَّانِى فَٱجْلِدُوا۟ كُلَّ وَٰحِدٍۢ مِّنْهُمَا مِا۟ئَةَ جَلْدَةٍۢ ۖ وَلَا تَأْخُذْكُم بِهِمَا رَأْفَةٌۭ فِى دِينِ ٱللَّهِ إِن كُنتُمْ تُؤْمِنُونَ بِٱللَّهِ وَٱلْيَوْمِ ٱلْءَاخِرِ ۖ وَلْيَشْهَدْ عَذَابَهُمَا طَآئِفَةٌۭ مِّنَ ٱلْمُؤْمِنِينَ', 'الزانية والزانى فاجلدوا كل وحد منهما مائة جلدة  ولا تأخذكم بهما رأفة فى دين الله إن كنتم تؤمنون بالله واليوم الءاخر  وليشهد عذابهما طائفة من المؤمنين', NULL, 350, 'local:hafs-text.json'),
  ('hafs-24-3', 'hafs', 24, 3, 'ٱلزَّانِى لَا يَنكِحُ إِلَّا زَانِيَةً أَوْ مُشْرِكَةًۭ وَٱلزَّانِيَةُ لَا يَنكِحُهَآ إِلَّا زَانٍ أَوْ مُشْرِكٌۭ ۚ وَحُرِّمَ ذَٰلِكَ عَلَى ٱلْمُؤْمِنِينَ', 'الزانى لا ينكح إلا زانية أو مشركة والزانية لا ينكحها إلا زان أو مشرك  وحرم ذلك على المؤمنين', NULL, 350, 'local:hafs-text.json'),
  ('hafs-24-4', 'hafs', 24, 4, 'وَٱلَّذِينَ يَرْمُونَ ٱلْمُحْصَنَٰتِ ثُمَّ لَمْ يَأْتُوا۟ بِأَرْبَعَةِ شُهَدَآءَ فَٱجْلِدُوهُمْ ثَمَٰنِينَ جَلْدَةًۭ وَلَا تَقْبَلُوا۟ لَهُمْ شَهَٰدَةً أَبَدًۭا ۚ وَأُو۟لَٰٓئِكَ هُمُ ٱلْفَٰسِقُونَ', 'والذين يرمون المحصنت ثم لم يأتوا بأربعة شهداء فاجلدوهم ثمنين جلدة ولا تقبلوا لهم شهدة أبدا  وأولئك هم الفسقون', NULL, 350, 'local:hafs-text.json'),
  ('hafs-24-5', 'hafs', 24, 5, 'إِلَّا ٱلَّذِينَ تَابُوا۟ مِنۢ بَعْدِ ذَٰلِكَ وَأَصْلَحُوا۟ فَإِنَّ ٱللَّهَ غَفُورٌۭ رَّحِيمٌۭ', 'إلا الذين تابوا من بعد ذلك وأصلحوا فإن الله غفور رحيم', NULL, 350, 'local:hafs-text.json'),
  ('hafs-24-6', 'hafs', 24, 6, 'وَٱلَّذِينَ يَرْمُونَ أَزْوَٰجَهُمْ وَلَمْ يَكُن لَّهُمْ شُهَدَآءُ إِلَّآ أَنفُسُهُمْ فَشَهَٰدَةُ أَحَدِهِمْ أَرْبَعُ شَهَٰدَٰتٍۭ بِٱللَّهِ ۙ إِنَّهُۥ لَمِنَ ٱلصَّٰدِقِينَ', 'والذين يرمون أزوجهم ولم يكن لهم شهداء إلا أنفسهم فشهدة أحدهم أربع شهدت بالله  إنه لمن الصدقين', NULL, 350, 'local:hafs-text.json'),
  ('hafs-24-7', 'hafs', 24, 7, 'وَٱلْخَٰمِسَةُ أَنَّ لَعْنَتَ ٱللَّهِ عَلَيْهِ إِن كَانَ مِنَ ٱلْكَٰذِبِينَ', 'والخمسة أن لعنت الله عليه إن كان من الكذبين', NULL, 350, 'local:hafs-text.json'),
  ('hafs-24-8', 'hafs', 24, 8, 'وَيَدْرَؤُا۟ عَنْهَا ٱلْعَذَابَ أَن تَشْهَدَ أَرْبَعَ شَهَٰدَٰتٍۭ بِٱللَّهِ ۙ إِنَّهُۥ لَمِنَ ٱلْكَٰذِبِينَ', 'ويدرؤا عنها العذاب أن تشهد أربع شهدت بالله  إنه لمن الكذبين', NULL, 350, 'local:hafs-text.json'),
  ('hafs-24-9', 'hafs', 24, 9, 'وَٱلْخَٰمِسَةَ أَنَّ غَضَبَ ٱللَّهِ عَلَيْهَآ إِن كَانَ مِنَ ٱلصَّٰدِقِينَ', 'والخمسة أن غضب الله عليها إن كان من الصدقين', NULL, 350, 'local:hafs-text.json')
insert into public.ayahs (id, riwayah, surah_number, ayah_number, text, simple_text, juz, page, source) values
  ('hafs-24-10', 'hafs', 24, 10, 'وَلَوْلَا فَضْلُ ٱللَّهِ عَلَيْكُمْ وَرَحْمَتُهُۥ وَأَنَّ ٱللَّهَ تَوَّابٌ حَكِيمٌ', 'ولولا فضل الله عليكم ورحمته وأن الله تواب حكيم', NULL, 350, 'local:hafs-text.json'),
  ('hafs-24-11', 'hafs', 24, 11, 'إِنَّ ٱلَّذِينَ جَآءُو بِٱلْإِفْكِ عُصْبَةٌۭ مِّنكُمْ ۚ لَا تَحْسَبُوهُ شَرًّۭا لَّكُم ۖ بَلْ هُوَ خَيْرٌۭ لَّكُمْ ۚ لِكُلِّ ٱمْرِئٍۢ مِّنْهُم مَّا ٱكْتَسَبَ مِنَ ٱلْإِثْمِ ۚ وَٱلَّذِى تَوَلَّىٰ كِبْرَهُۥ مِنْهُمْ لَهُۥ عَذَابٌ عَظِيمٌۭ', 'إن الذين جاءو بالإفك عصبة منكم  لا تحسبوه شرا لكم  بل هو خير لكم  لكل امرئ منهم ما اكتسب من الإثم  والذى تولى كبره منهم له عذاب عظيم', NULL, 351, 'local:hafs-text.json'),
  ('hafs-24-12', 'hafs', 24, 12, 'لَّوْلَآ إِذْ سَمِعْتُمُوهُ ظَنَّ ٱلْمُؤْمِنُونَ وَٱلْمُؤْمِنَٰتُ بِأَنفُسِهِمْ خَيْرًۭا وَقَالُوا۟ هَٰذَآ إِفْكٌۭ مُّبِينٌۭ', 'لولا إذ سمعتموه ظن المؤمنون والمؤمنت بأنفسهم خيرا وقالوا هذا إفك مبين', NULL, 351, 'local:hafs-text.json'),
  ('hafs-24-13', 'hafs', 24, 13, 'لَّوْلَا جَآءُو عَلَيْهِ بِأَرْبَعَةِ شُهَدَآءَ ۚ فَإِذْ لَمْ يَأْتُوا۟ بِٱلشُّهَدَآءِ فَأُو۟لَٰٓئِكَ عِندَ ٱللَّهِ هُمُ ٱلْكَٰذِبُونَ', 'لولا جاءو عليه بأربعة شهداء  فإذ لم يأتوا بالشهداء فأولئك عند الله هم الكذبون', NULL, 351, 'local:hafs-text.json'),
  ('hafs-24-14', 'hafs', 24, 14, 'وَلَوْلَا فَضْلُ ٱللَّهِ عَلَيْكُمْ وَرَحْمَتُهُۥ فِى ٱلدُّنْيَا وَٱلْءَاخِرَةِ لَمَسَّكُمْ فِى مَآ أَفَضْتُمْ فِيهِ عَذَابٌ عَظِيمٌ', 'ولولا فضل الله عليكم ورحمته فى الدنيا والءاخرة لمسكم فى ما أفضتم فيه عذاب عظيم', NULL, 351, 'local:hafs-text.json'),
  ('hafs-24-15', 'hafs', 24, 15, 'إِذْ تَلَقَّوْنَهُۥ بِأَلْسِنَتِكُمْ وَتَقُولُونَ بِأَفْوَاهِكُم مَّا لَيْسَ لَكُم بِهِۦ عِلْمٌۭ وَتَحْسَبُونَهُۥ هَيِّنًۭا وَهُوَ عِندَ ٱللَّهِ عَظِيمٌۭ', 'إذ تلقونه بألسنتكم وتقولون بأفواهكم ما ليس لكم به علم وتحسبونه هينا وهو عند الله عظيم', NULL, 351, 'local:hafs-text.json'),
  ('hafs-24-16', 'hafs', 24, 16, 'وَلَوْلَآ إِذْ سَمِعْتُمُوهُ قُلْتُم مَّا يَكُونُ لَنَآ أَن نَّتَكَلَّمَ بِهَٰذَا سُبْحَٰنَكَ هَٰذَا بُهْتَٰنٌ عَظِيمٌۭ', 'ولولا إذ سمعتموه قلتم ما يكون لنا أن نتكلم بهذا سبحنك هذا بهتن عظيم', NULL, 351, 'local:hafs-text.json'),
  ('hafs-24-17', 'hafs', 24, 17, 'يَعِظُكُمُ ٱللَّهُ أَن تَعُودُوا۟ لِمِثْلِهِۦٓ أَبَدًا إِن كُنتُم مُّؤْمِنِينَ', 'يعظكم الله أن تعودوا لمثله أبدا إن كنتم مؤمنين', NULL, 351, 'local:hafs-text.json'),
  ('hafs-24-18', 'hafs', 24, 18, 'وَيُبَيِّنُ ٱللَّهُ لَكُمُ ٱلْءَايَٰتِ ۚ وَٱللَّهُ عَلِيمٌ حَكِيمٌ', 'ويبين الله لكم الءايت  والله عليم حكيم', NULL, 351, 'local:hafs-text.json'),
  ('hafs-24-19', 'hafs', 24, 19, 'إِنَّ ٱلَّذِينَ يُحِبُّونَ أَن تَشِيعَ ٱلْفَٰحِشَةُ فِى ٱلَّذِينَ ءَامَنُوا۟ لَهُمْ عَذَابٌ أَلِيمٌۭ فِى ٱلدُّنْيَا وَٱلْءَاخِرَةِ ۚ وَٱللَّهُ يَعْلَمُ وَأَنتُمْ لَا تَعْلَمُونَ', 'إن الذين يحبون أن تشيع الفحشة فى الذين ءامنوا لهم عذاب أليم فى الدنيا والءاخرة  والله يعلم وأنتم لا تعلمون', NULL, 351, 'local:hafs-text.json'),
  ('hafs-24-20', 'hafs', 24, 20, 'وَلَوْلَا فَضْلُ ٱللَّهِ عَلَيْكُمْ وَرَحْمَتُهُۥ وَأَنَّ ٱللَّهَ رَءُوفٌۭ رَّحِيمٌۭ', 'ولولا فضل الله عليكم ورحمته وأن الله رءوف رحيم', NULL, 351, 'local:hafs-text.json'),
  ('hafs-24-21', 'hafs', 24, 21, '۞ يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَتَّبِعُوا۟ خُطُوَٰتِ ٱلشَّيْطَٰنِ ۚ وَمَن يَتَّبِعْ خُطُوَٰتِ ٱلشَّيْطَٰنِ فَإِنَّهُۥ يَأْمُرُ بِٱلْفَحْشَآءِ وَٱلْمُنكَرِ ۚ وَلَوْلَا فَضْلُ ٱللَّهِ عَلَيْكُمْ وَرَحْمَتُهُۥ مَا زَكَىٰ مِنكُم مِّنْ أَحَدٍ أَبَدًۭا وَلَٰكِنَّ ٱللَّهَ يُزَكِّى مَن يَشَآءُ ۗ وَٱللَّهُ سَمِيعٌ عَلِيمٌۭ', 'يأيها الذين ءامنوا لا تتبعوا خطوت الشيطن  ومن يتبع خطوت الشيطن فإنه يأمر بالفحشاء والمنكر  ولولا فضل الله عليكم ورحمته ما زكى منكم من أحد أبدا ولكن الله يزكى من يشاء  والله سميع عليم', NULL, 352, 'local:hafs-text.json'),
  ('hafs-24-22', 'hafs', 24, 22, 'وَلَا يَأْتَلِ أُو۟لُوا۟ ٱلْفَضْلِ مِنكُمْ وَٱلسَّعَةِ أَن يُؤْتُوٓا۟ أُو۟لِى ٱلْقُرْبَىٰ وَٱلْمَسَٰكِينَ وَٱلْمُهَٰجِرِينَ فِى سَبِيلِ ٱللَّهِ ۖ وَلْيَعْفُوا۟ وَلْيَصْفَحُوٓا۟ ۗ أَلَا تُحِبُّونَ أَن يَغْفِرَ ٱللَّهُ لَكُمْ ۗ وَٱللَّهُ غَفُورٌۭ رَّحِيمٌ', 'ولا يأتل أولوا الفضل منكم والسعة أن يؤتوا أولى القربى والمسكين والمهجرين فى سبيل الله  وليعفوا وليصفحوا  ألا تحبون أن يغفر الله لكم  والله غفور رحيم', NULL, 352, 'local:hafs-text.json'),
  ('hafs-24-23', 'hafs', 24, 23, 'إِنَّ ٱلَّذِينَ يَرْمُونَ ٱلْمُحْصَنَٰتِ ٱلْغَٰفِلَٰتِ ٱلْمُؤْمِنَٰتِ لُعِنُوا۟ فِى ٱلدُّنْيَا وَٱلْءَاخِرَةِ وَلَهُمْ عَذَابٌ عَظِيمٌۭ', 'إن الذين يرمون المحصنت الغفلت المؤمنت لعنوا فى الدنيا والءاخرة ولهم عذاب عظيم', NULL, 352, 'local:hafs-text.json'),
  ('hafs-24-24', 'hafs', 24, 24, 'يَوْمَ تَشْهَدُ عَلَيْهِمْ أَلْسِنَتُهُمْ وَأَيْدِيهِمْ وَأَرْجُلُهُم بِمَا كَانُوا۟ يَعْمَلُونَ', 'يوم تشهد عليهم ألسنتهم وأيديهم وأرجلهم بما كانوا يعملون', NULL, 352, 'local:hafs-text.json'),
  ('hafs-24-25', 'hafs', 24, 25, 'يَوْمَئِذٍۢ يُوَفِّيهِمُ ٱللَّهُ دِينَهُمُ ٱلْحَقَّ وَيَعْلَمُونَ أَنَّ ٱللَّهَ هُوَ ٱلْحَقُّ ٱلْمُبِينُ', 'يومئذ يوفيهم الله دينهم الحق ويعلمون أن الله هو الحق المبين', NULL, 352, 'local:hafs-text.json'),
  ('hafs-24-26', 'hafs', 24, 26, 'ٱلْخَبِيثَٰتُ لِلْخَبِيثِينَ وَٱلْخَبِيثُونَ لِلْخَبِيثَٰتِ ۖ وَٱلطَّيِّبَٰتُ لِلطَّيِّبِينَ وَٱلطَّيِّبُونَ لِلطَّيِّبَٰتِ ۚ أُو۟لَٰٓئِكَ مُبَرَّءُونَ مِمَّا يَقُولُونَ ۖ لَهُم مَّغْفِرَةٌۭ وَرِزْقٌۭ كَرِيمٌۭ', 'الخبيثت للخبيثين والخبيثون للخبيثت  والطيبت للطيبين والطيبون للطيبت  أولئك مبرءون مما يقولون  لهم مغفرة ورزق كريم', NULL, 352, 'local:hafs-text.json'),
  ('hafs-24-27', 'hafs', 24, 27, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَدْخُلُوا۟ بُيُوتًا غَيْرَ بُيُوتِكُمْ حَتَّىٰ تَسْتَأْنِسُوا۟ وَتُسَلِّمُوا۟ عَلَىٰٓ أَهْلِهَا ۚ ذَٰلِكُمْ خَيْرٌۭ لَّكُمْ لَعَلَّكُمْ تَذَكَّرُونَ', 'يأيها الذين ءامنوا لا تدخلوا بيوتا غير بيوتكم حتى تستأنسوا وتسلموا على أهلها  ذلكم خير لكم لعلكم تذكرون', NULL, 352, 'local:hafs-text.json'),
  ('hafs-24-28', 'hafs', 24, 28, 'فَإِن لَّمْ تَجِدُوا۟ فِيهَآ أَحَدًۭا فَلَا تَدْخُلُوهَا حَتَّىٰ يُؤْذَنَ لَكُمْ ۖ وَإِن قِيلَ لَكُمُ ٱرْجِعُوا۟ فَٱرْجِعُوا۟ ۖ هُوَ أَزْكَىٰ لَكُمْ ۚ وَٱللَّهُ بِمَا تَعْمَلُونَ عَلِيمٌۭ', 'فإن لم تجدوا فيها أحدا فلا تدخلوها حتى يؤذن لكم  وإن قيل لكم ارجعوا فارجعوا  هو أزكى لكم  والله بما تعملون عليم', NULL, 353, 'local:hafs-text.json'),
  ('hafs-24-29', 'hafs', 24, 29, 'لَّيْسَ عَلَيْكُمْ جُنَاحٌ أَن تَدْخُلُوا۟ بُيُوتًا غَيْرَ مَسْكُونَةٍۢ فِيهَا مَتَٰعٌۭ لَّكُمْ ۚ وَٱللَّهُ يَعْلَمُ مَا تُبْدُونَ وَمَا تَكْتُمُونَ', 'ليس عليكم جناح أن تدخلوا بيوتا غير مسكونة فيها متع لكم  والله يعلم ما تبدون وما تكتمون', NULL, 353, 'local:hafs-text.json'),
  ('hafs-24-30', 'hafs', 24, 30, 'قُل لِّلْمُؤْمِنِينَ يَغُضُّوا۟ مِنْ أَبْصَٰرِهِمْ وَيَحْفَظُوا۟ فُرُوجَهُمْ ۚ ذَٰلِكَ أَزْكَىٰ لَهُمْ ۗ إِنَّ ٱللَّهَ خَبِيرٌۢ بِمَا يَصْنَعُونَ', 'قل للمؤمنين يغضوا من أبصرهم ويحفظوا فروجهم  ذلك أزكى لهم  إن الله خبير بما يصنعون', NULL, 353, 'local:hafs-text.json'),
  ('hafs-24-31', 'hafs', 24, 31, 'وَقُل لِّلْمُؤْمِنَٰتِ يَغْضُضْنَ مِنْ أَبْصَٰرِهِنَّ وَيَحْفَظْنَ فُرُوجَهُنَّ وَلَا يُبْدِينَ زِينَتَهُنَّ إِلَّا مَا ظَهَرَ مِنْهَا ۖ وَلْيَضْرِبْنَ بِخُمُرِهِنَّ عَلَىٰ جُيُوبِهِنَّ ۖ وَلَا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ أَوْ ءَابَآئِهِنَّ أَوْ ءَابَآءِ بُعُولَتِهِنَّ أَوْ أَبْنَآئِهِنَّ أَوْ أَبْنَآءِ بُعُولَتِهِنَّ أَوْ إِخْوَٰنِهِنَّ أَوْ بَنِىٓ إِخْوَٰنِهِنَّ أَوْ بَنِىٓ أَخَوَٰتِهِنَّ أَوْ نِسَآئِهِنَّ أَوْ مَا مَلَكَتْ أَيْمَٰنُهُنَّ أَوِ ٱلتَّٰبِعِينَ غَيْرِ أُو۟لِى ٱلْإِرْبَةِ مِنَ ٱلرِّجَالِ أَوِ ٱلطِّفْلِ ٱلَّذِينَ لَمْ يَظْهَرُوا۟ عَلَىٰ عَوْرَٰتِ ٱلنِّسَآءِ ۖ وَلَا يَضْرِبْنَ بِأَرْجُلِهِنَّ لِيُعْلَمَ مَا يُخْفِينَ مِن زِينَتِهِنَّ ۚ وَتُوبُوٓا۟ إِلَى ٱللَّهِ جَمِيعًا أَيُّهَ ٱلْمُؤْمِنُونَ لَعَلَّكُمْ تُفْلِحُونَ', 'وقل للمؤمنت يغضضن من أبصرهن ويحفظن فروجهن ولا يبدين زينتهن إلا ما ظهر منها  وليضربن بخمرهن على جيوبهن  ولا يبدين زينتهن إلا لبعولتهن أو ءابائهن أو ءاباء بعولتهن أو أبنائهن أو أبناء بعولتهن أو إخونهن أو بنى إخونهن أو بنى أخوتهن أو نسائهن أو ما ملكت أيمنهن أو التبعين غير أولى الإربة من الرجال أو الطفل الذين لم يظهروا على عورت النساء  ولا يضربن بأرجلهن ليعلم ما يخفين من زينتهن  وتوبوا إلى الله جميعا أيه المؤمنون لعلكم تفلحون', NULL, 353, 'local:hafs-text.json'),
  ('hafs-24-32', 'hafs', 24, 32, 'وَأَنكِحُوا۟ ٱلْأَيَٰمَىٰ مِنكُمْ وَٱلصَّٰلِحِينَ مِنْ عِبَادِكُمْ وَإِمَآئِكُمْ ۚ إِن يَكُونُوا۟ فُقَرَآءَ يُغْنِهِمُ ٱللَّهُ مِن فَضْلِهِۦ ۗ وَٱللَّهُ وَٰسِعٌ عَلِيمٌۭ', 'وأنكحوا الأيمى منكم والصلحين من عبادكم وإمائكم  إن يكونوا فقراء يغنهم الله من فضله  والله وسع عليم', NULL, 354, 'local:hafs-text.json'),
  ('hafs-24-33', 'hafs', 24, 33, 'وَلْيَسْتَعْفِفِ ٱلَّذِينَ لَا يَجِدُونَ نِكَاحًا حَتَّىٰ يُغْنِيَهُمُ ٱللَّهُ مِن فَضْلِهِۦ ۗ وَٱلَّذِينَ يَبْتَغُونَ ٱلْكِتَٰبَ مِمَّا مَلَكَتْ أَيْمَٰنُكُمْ فَكَاتِبُوهُمْ إِنْ عَلِمْتُمْ فِيهِمْ خَيْرًۭا ۖ وَءَاتُوهُم مِّن مَّالِ ٱللَّهِ ٱلَّذِىٓ ءَاتَىٰكُمْ ۚ وَلَا تُكْرِهُوا۟ فَتَيَٰتِكُمْ عَلَى ٱلْبِغَآءِ إِنْ أَرَدْنَ تَحَصُّنًۭا لِّتَبْتَغُوا۟ عَرَضَ ٱلْحَيَوٰةِ ٱلدُّنْيَا ۚ وَمَن يُكْرِههُّنَّ فَإِنَّ ٱللَّهَ مِنۢ بَعْدِ إِكْرَٰهِهِنَّ غَفُورٌۭ رَّحِيمٌۭ', 'وليستعفف الذين لا يجدون نكاحا حتى يغنيهم الله من فضله  والذين يبتغون الكتب مما ملكت أيمنكم فكاتبوهم إن علمتم فيهم خيرا  وءاتوهم من مال الله الذى ءاتىكم  ولا تكرهوا فتيتكم على البغاء إن أردن تحصنا لتبتغوا عرض الحيوة الدنيا  ومن يكرههن فإن الله من بعد إكرههن غفور رحيم', NULL, 354, 'local:hafs-text.json'),
  ('hafs-24-34', 'hafs', 24, 34, 'وَلَقَدْ أَنزَلْنَآ إِلَيْكُمْ ءَايَٰتٍۢ مُّبَيِّنَٰتٍۢ وَمَثَلًۭا مِّنَ ٱلَّذِينَ خَلَوْا۟ مِن قَبْلِكُمْ وَمَوْعِظَةًۭ لِّلْمُتَّقِينَ', 'ولقد أنزلنا إليكم ءايت مبينت ومثلا من الذين خلوا من قبلكم وموعظة للمتقين', NULL, 354, 'local:hafs-text.json'),
  ('hafs-24-35', 'hafs', 24, 35, '۞ ٱللَّهُ نُورُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ ۚ مَثَلُ نُورِهِۦ كَمِشْكَوٰةٍۢ فِيهَا مِصْبَاحٌ ۖ ٱلْمِصْبَاحُ فِى زُجَاجَةٍ ۖ ٱلزُّجَاجَةُ كَأَنَّهَا كَوْكَبٌۭ دُرِّىٌّۭ يُوقَدُ مِن شَجَرَةٍۢ مُّبَٰرَكَةٍۢ زَيْتُونَةٍۢ لَّا شَرْقِيَّةٍۢ وَلَا غَرْبِيَّةٍۢ يَكَادُ زَيْتُهَا يُضِىٓءُ وَلَوْ لَمْ تَمْسَسْهُ نَارٌۭ ۚ نُّورٌ عَلَىٰ نُورٍۢ ۗ يَهْدِى ٱللَّهُ لِنُورِهِۦ مَن يَشَآءُ ۚ وَيَضْرِبُ ٱللَّهُ ٱلْأَمْثَٰلَ لِلنَّاسِ ۗ وَٱللَّهُ بِكُلِّ شَىْءٍ عَلِيمٌۭ', 'الله نور السموت والأرض  مثل نوره كمشكوة فيها مصباح  المصباح فى زجاجة  الزجاجة كأنها كوكب درى يوقد من شجرة مبركة زيتونة لا شرقية ولا غربية يكاد زيتها يضىء ولو لم تمسسه نار  نور على نور  يهدى الله لنوره من يشاء  ويضرب الله الأمثل للناس  والله بكل شىء عليم', NULL, 354, 'local:hafs-text.json'),
  ('hafs-24-36', 'hafs', 24, 36, 'فِى بُيُوتٍ أَذِنَ ٱللَّهُ أَن تُرْفَعَ وَيُذْكَرَ فِيهَا ٱسْمُهُۥ يُسَبِّحُ لَهُۥ فِيهَا بِٱلْغُدُوِّ وَٱلْءَاصَالِ', 'فى بيوت أذن الله أن ترفع ويذكر فيها اسمه يسبح له فيها بالغدو والءاصال', NULL, 354, 'local:hafs-text.json'),
  ('hafs-24-37', 'hafs', 24, 37, 'رِجَالٌۭ لَّا تُلْهِيهِمْ تِجَٰرَةٌۭ وَلَا بَيْعٌ عَن ذِكْرِ ٱللَّهِ وَإِقَامِ ٱلصَّلَوٰةِ وَإِيتَآءِ ٱلزَّكَوٰةِ ۙ يَخَافُونَ يَوْمًۭا تَتَقَلَّبُ فِيهِ ٱلْقُلُوبُ وَٱلْأَبْصَٰرُ', 'رجال لا تلهيهم تجرة ولا بيع عن ذكر الله وإقام الصلوة وإيتاء الزكوة  يخافون يوما تتقلب فيه القلوب والأبصر', NULL, 355, 'local:hafs-text.json'),
  ('hafs-24-38', 'hafs', 24, 38, 'لِيَجْزِيَهُمُ ٱللَّهُ أَحْسَنَ مَا عَمِلُوا۟ وَيَزِيدَهُم مِّن فَضْلِهِۦ ۗ وَٱللَّهُ يَرْزُقُ مَن يَشَآءُ بِغَيْرِ حِسَابٍۢ', 'ليجزيهم الله أحسن ما عملوا ويزيدهم من فضله  والله يرزق من يشاء بغير حساب', NULL, 355, 'local:hafs-text.json'),
  ('hafs-24-39', 'hafs', 24, 39, 'وَٱلَّذِينَ كَفَرُوٓا۟ أَعْمَٰلُهُمْ كَسَرَابٍۭ بِقِيعَةٍۢ يَحْسَبُهُ ٱلظَّمْـَٔانُ مَآءً حَتَّىٰٓ إِذَا جَآءَهُۥ لَمْ يَجِدْهُ شَيْـًۭٔا وَوَجَدَ ٱللَّهَ عِندَهُۥ فَوَفَّىٰهُ حِسَابَهُۥ ۗ وَٱللَّهُ سَرِيعُ ٱلْحِسَابِ', 'والذين كفروا أعملهم كسراب بقيعة يحسبه الظمان ماء حتى إذا جاءه لم يجده شيا ووجد الله عنده فوفىه حسابه  والله سريع الحساب', NULL, 355, 'local:hafs-text.json'),
  ('hafs-24-40', 'hafs', 24, 40, 'أَوْ كَظُلُمَٰتٍۢ فِى بَحْرٍۢ لُّجِّىٍّۢ يَغْشَىٰهُ مَوْجٌۭ مِّن فَوْقِهِۦ مَوْجٌۭ مِّن فَوْقِهِۦ سَحَابٌۭ ۚ ظُلُمَٰتٌۢ بَعْضُهَا فَوْقَ بَعْضٍ إِذَآ أَخْرَجَ يَدَهُۥ لَمْ يَكَدْ يَرَىٰهَا ۗ وَمَن لَّمْ يَجْعَلِ ٱللَّهُ لَهُۥ نُورًۭا فَمَا لَهُۥ مِن نُّورٍ', 'أو كظلمت فى بحر لجى يغشىه موج من فوقه موج من فوقه سحاب  ظلمت بعضها فوق بعض إذا أخرج يده لم يكد يرىها  ومن لم يجعل الله له نورا فما له من نور', NULL, 355, 'local:hafs-text.json'),
  ('hafs-24-41', 'hafs', 24, 41, 'أَلَمْ تَرَ أَنَّ ٱللَّهَ يُسَبِّحُ لَهُۥ مَن فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَٱلطَّيْرُ صَٰٓفَّٰتٍۢ ۖ كُلٌّۭ قَدْ عَلِمَ صَلَاتَهُۥ وَتَسْبِيحَهُۥ ۗ وَٱللَّهُ عَلِيمٌۢ بِمَا يَفْعَلُونَ', 'ألم تر أن الله يسبح له من فى السموت والأرض والطير صفت  كل قد علم صلاته وتسبيحه  والله عليم بما يفعلون', NULL, 355, 'local:hafs-text.json'),
  ('hafs-24-42', 'hafs', 24, 42, 'وَلِلَّهِ مُلْكُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ ۖ وَإِلَى ٱللَّهِ ٱلْمَصِيرُ', 'ولله ملك السموت والأرض  وإلى الله المصير', NULL, 355, 'local:hafs-text.json'),
  ('hafs-24-43', 'hafs', 24, 43, 'أَلَمْ تَرَ أَنَّ ٱللَّهَ يُزْجِى سَحَابًۭا ثُمَّ يُؤَلِّفُ بَيْنَهُۥ ثُمَّ يَجْعَلُهُۥ رُكَامًۭا فَتَرَى ٱلْوَدْقَ يَخْرُجُ مِنْ خِلَٰلِهِۦ وَيُنَزِّلُ مِنَ ٱلسَّمَآءِ مِن جِبَالٍۢ فِيهَا مِنۢ بَرَدٍۢ فَيُصِيبُ بِهِۦ مَن يَشَآءُ وَيَصْرِفُهُۥ عَن مَّن يَشَآءُ ۖ يَكَادُ سَنَا بَرْقِهِۦ يَذْهَبُ بِٱلْأَبْصَٰرِ', 'ألم تر أن الله يزجى سحابا ثم يؤلف بينه ثم يجعله ركاما فترى الودق يخرج من خلله وينزل من السماء من جبال فيها من برد فيصيب به من يشاء ويصرفه عن من يشاء  يكاد سنا برقه يذهب بالأبصر', NULL, 355, 'local:hafs-text.json'),
  ('hafs-24-44', 'hafs', 24, 44, 'يُقَلِّبُ ٱللَّهُ ٱلَّيْلَ وَٱلنَّهَارَ ۚ إِنَّ فِى ذَٰلِكَ لَعِبْرَةًۭ لِّأُو۟لِى ٱلْأَبْصَٰرِ', 'يقلب الله اليل والنهار  إن فى ذلك لعبرة لأولى الأبصر', NULL, 356, 'local:hafs-text.json'),
  ('hafs-24-45', 'hafs', 24, 45, 'وَٱللَّهُ خَلَقَ كُلَّ دَآبَّةٍۢ مِّن مَّآءٍۢ ۖ فَمِنْهُم مَّن يَمْشِى عَلَىٰ بَطْنِهِۦ وَمِنْهُم مَّن يَمْشِى عَلَىٰ رِجْلَيْنِ وَمِنْهُم مَّن يَمْشِى عَلَىٰٓ أَرْبَعٍۢ ۚ يَخْلُقُ ٱللَّهُ مَا يَشَآءُ ۚ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَىْءٍۢ قَدِيرٌۭ', 'والله خلق كل دابة من ماء  فمنهم من يمشى على بطنه ومنهم من يمشى على رجلين ومنهم من يمشى على أربع  يخلق الله ما يشاء  إن الله على كل شىء قدير', NULL, 356, 'local:hafs-text.json'),
  ('hafs-24-46', 'hafs', 24, 46, 'لَّقَدْ أَنزَلْنَآ ءَايَٰتٍۢ مُّبَيِّنَٰتٍۢ ۚ وَٱللَّهُ يَهْدِى مَن يَشَآءُ إِلَىٰ صِرَٰطٍۢ مُّسْتَقِيمٍۢ', 'لقد أنزلنا ءايت مبينت  والله يهدى من يشاء إلى صرط مستقيم', NULL, 356, 'local:hafs-text.json'),
  ('hafs-24-47', 'hafs', 24, 47, 'وَيَقُولُونَ ءَامَنَّا بِٱللَّهِ وَبِٱلرَّسُولِ وَأَطَعْنَا ثُمَّ يَتَوَلَّىٰ فَرِيقٌۭ مِّنْهُم مِّنۢ بَعْدِ ذَٰلِكَ ۚ وَمَآ أُو۟لَٰٓئِكَ بِٱلْمُؤْمِنِينَ', 'ويقولون ءامنا بالله وبالرسول وأطعنا ثم يتولى فريق منهم من بعد ذلك  وما أولئك بالمؤمنين', NULL, 356, 'local:hafs-text.json'),
  ('hafs-24-48', 'hafs', 24, 48, 'وَإِذَا دُعُوٓا۟ إِلَى ٱللَّهِ وَرَسُولِهِۦ لِيَحْكُمَ بَيْنَهُمْ إِذَا فَرِيقٌۭ مِّنْهُم مُّعْرِضُونَ', 'وإذا دعوا إلى الله ورسوله ليحكم بينهم إذا فريق منهم معرضون', NULL, 356, 'local:hafs-text.json'),
  ('hafs-24-49', 'hafs', 24, 49, 'وَإِن يَكُن لَّهُمُ ٱلْحَقُّ يَأْتُوٓا۟ إِلَيْهِ مُذْعِنِينَ', 'وإن يكن لهم الحق يأتوا إليه مذعنين', NULL, 356, 'local:hafs-text.json'),
  ('hafs-24-50', 'hafs', 24, 50, 'أَفِى قُلُوبِهِم مَّرَضٌ أَمِ ٱرْتَابُوٓا۟ أَمْ يَخَافُونَ أَن يَحِيفَ ٱللَّهُ عَلَيْهِمْ وَرَسُولُهُۥ ۚ بَلْ أُو۟لَٰٓئِكَ هُمُ ٱلظَّٰلِمُونَ', 'أفى قلوبهم مرض أم ارتابوا أم يخافون أن يحيف الله عليهم ورسوله  بل أولئك هم الظلمون', NULL, 356, 'local:hafs-text.json'),
  ('hafs-24-51', 'hafs', 24, 51, 'إِنَّمَا كَانَ قَوْلَ ٱلْمُؤْمِنِينَ إِذَا دُعُوٓا۟ إِلَى ٱللَّهِ وَرَسُولِهِۦ لِيَحْكُمَ بَيْنَهُمْ أَن يَقُولُوا۟ سَمِعْنَا وَأَطَعْنَا ۚ وَأُو۟لَٰٓئِكَ هُمُ ٱلْمُفْلِحُونَ', 'إنما كان قول المؤمنين إذا دعوا إلى الله ورسوله ليحكم بينهم أن يقولوا سمعنا وأطعنا  وأولئك هم المفلحون', NULL, 356, 'local:hafs-text.json'),
  ('hafs-24-52', 'hafs', 24, 52, 'وَمَن يُطِعِ ٱللَّهَ وَرَسُولَهُۥ وَيَخْشَ ٱللَّهَ وَيَتَّقْهِ فَأُو۟لَٰٓئِكَ هُمُ ٱلْفَآئِزُونَ', 'ومن يطع الله ورسوله ويخش الله ويتقه فأولئك هم الفائزون', NULL, 356, 'local:hafs-text.json'),
  ('hafs-24-53', 'hafs', 24, 53, '۞ وَأَقْسَمُوا۟ بِٱللَّهِ جَهْدَ أَيْمَٰنِهِمْ لَئِنْ أَمَرْتَهُمْ لَيَخْرُجُنَّ ۖ قُل لَّا تُقْسِمُوا۟ ۖ طَاعَةٌۭ مَّعْرُوفَةٌ ۚ إِنَّ ٱللَّهَ خَبِيرٌۢ بِمَا تَعْمَلُونَ', 'وأقسموا بالله جهد أيمنهم لئن أمرتهم ليخرجن  قل لا تقسموا  طاعة معروفة  إن الله خبير بما تعملون', NULL, 356, 'local:hafs-text.json'),
  ('hafs-24-54', 'hafs', 24, 54, 'قُلْ أَطِيعُوا۟ ٱللَّهَ وَأَطِيعُوا۟ ٱلرَّسُولَ ۖ فَإِن تَوَلَّوْا۟ فَإِنَّمَا عَلَيْهِ مَا حُمِّلَ وَعَلَيْكُم مَّا حُمِّلْتُمْ ۖ وَإِن تُطِيعُوهُ تَهْتَدُوا۟ ۚ وَمَا عَلَى ٱلرَّسُولِ إِلَّا ٱلْبَلَٰغُ ٱلْمُبِينُ', 'قل أطيعوا الله وأطيعوا الرسول  فإن تولوا فإنما عليه ما حمل وعليكم ما حملتم  وإن تطيعوه تهتدوا  وما على الرسول إلا البلغ المبين', NULL, 357, 'local:hafs-text.json'),
  ('hafs-24-55', 'hafs', 24, 55, 'وَعَدَ ٱللَّهُ ٱلَّذِينَ ءَامَنُوا۟ مِنكُمْ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ لَيَسْتَخْلِفَنَّهُمْ فِى ٱلْأَرْضِ كَمَا ٱسْتَخْلَفَ ٱلَّذِينَ مِن قَبْلِهِمْ وَلَيُمَكِّنَنَّ لَهُمْ دِينَهُمُ ٱلَّذِى ٱرْتَضَىٰ لَهُمْ وَلَيُبَدِّلَنَّهُم مِّنۢ بَعْدِ خَوْفِهِمْ أَمْنًۭا ۚ يَعْبُدُونَنِى لَا يُشْرِكُونَ بِى شَيْـًۭٔا ۚ وَمَن كَفَرَ بَعْدَ ذَٰلِكَ فَأُو۟لَٰٓئِكَ هُمُ ٱلْفَٰسِقُونَ', 'وعد الله الذين ءامنوا منكم وعملوا الصلحت ليستخلفنهم فى الأرض كما استخلف الذين من قبلهم وليمكنن لهم دينهم الذى ارتضى لهم وليبدلنهم من بعد خوفهم أمنا  يعبدوننى لا يشركون بى شيا  ومن كفر بعد ذلك فأولئك هم الفسقون', NULL, 357, 'local:hafs-text.json'),
  ('hafs-24-56', 'hafs', 24, 56, 'وَأَقِيمُوا۟ ٱلصَّلَوٰةَ وَءَاتُوا۟ ٱلزَّكَوٰةَ وَأَطِيعُوا۟ ٱلرَّسُولَ لَعَلَّكُمْ تُرْحَمُونَ', 'وأقيموا الصلوة وءاتوا الزكوة وأطيعوا الرسول لعلكم ترحمون', NULL, 357, 'local:hafs-text.json'),
  ('hafs-24-57', 'hafs', 24, 57, 'لَا تَحْسَبَنَّ ٱلَّذِينَ كَفَرُوا۟ مُعْجِزِينَ فِى ٱلْأَرْضِ ۚ وَمَأْوَىٰهُمُ ٱلنَّارُ ۖ وَلَبِئْسَ ٱلْمَصِيرُ', 'لا تحسبن الذين كفروا معجزين فى الأرض  ومأوىهم النار  ولبئس المصير', NULL, 357, 'local:hafs-text.json'),
  ('hafs-24-58', 'hafs', 24, 58, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لِيَسْتَـْٔذِنكُمُ ٱلَّذِينَ مَلَكَتْ أَيْمَٰنُكُمْ وَٱلَّذِينَ لَمْ يَبْلُغُوا۟ ٱلْحُلُمَ مِنكُمْ ثَلَٰثَ مَرَّٰتٍۢ ۚ مِّن قَبْلِ صَلَوٰةِ ٱلْفَجْرِ وَحِينَ تَضَعُونَ ثِيَابَكُم مِّنَ ٱلظَّهِيرَةِ وَمِنۢ بَعْدِ صَلَوٰةِ ٱلْعِشَآءِ ۚ ثَلَٰثُ عَوْرَٰتٍۢ لَّكُمْ ۚ لَيْسَ عَلَيْكُمْ وَلَا عَلَيْهِمْ جُنَاحٌۢ بَعْدَهُنَّ ۚ طَوَّٰفُونَ عَلَيْكُم بَعْضُكُمْ عَلَىٰ بَعْضٍۢ ۚ كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ لَكُمُ ٱلْءَايَٰتِ ۗ وَٱللَّهُ عَلِيمٌ حَكِيمٌۭ', 'يأيها الذين ءامنوا ليستذنكم الذين ملكت أيمنكم والذين لم يبلغوا الحلم منكم ثلث مرت  من قبل صلوة الفجر وحين تضعون ثيابكم من الظهيرة ومن بعد صلوة العشاء  ثلث عورت لكم  ليس عليكم ولا عليهم جناح بعدهن  طوفون عليكم بعضكم على بعض  كذلك يبين الله لكم الءايت  والله عليم حكيم', NULL, 357, 'local:hafs-text.json'),
  ('hafs-24-59', 'hafs', 24, 59, 'وَإِذَا بَلَغَ ٱلْأَطْفَٰلُ مِنكُمُ ٱلْحُلُمَ فَلْيَسْتَـْٔذِنُوا۟ كَمَا ٱسْتَـْٔذَنَ ٱلَّذِينَ مِن قَبْلِهِمْ ۚ كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ لَكُمْ ءَايَٰتِهِۦ ۗ وَٱللَّهُ عَلِيمٌ حَكِيمٌۭ', 'وإذا بلغ الأطفل منكم الحلم فليستذنوا كما استذن الذين من قبلهم  كذلك يبين الله لكم ءايته  والله عليم حكيم', NULL, 358, 'local:hafs-text.json'),
  ('hafs-24-60', 'hafs', 24, 60, 'وَٱلْقَوَٰعِدُ مِنَ ٱلنِّسَآءِ ٱلَّٰتِى لَا يَرْجُونَ نِكَاحًۭا فَلَيْسَ عَلَيْهِنَّ جُنَاحٌ أَن يَضَعْنَ ثِيَابَهُنَّ غَيْرَ مُتَبَرِّجَٰتٍۭ بِزِينَةٍۢ ۖ وَأَن يَسْتَعْفِفْنَ خَيْرٌۭ لَّهُنَّ ۗ وَٱللَّهُ سَمِيعٌ عَلِيمٌۭ', 'والقوعد من النساء التى لا يرجون نكاحا فليس عليهن جناح أن يضعن ثيابهن غير متبرجت بزينة  وأن يستعففن خير لهن  والله سميع عليم', NULL, 358, 'local:hafs-text.json'),
  ('hafs-24-61', 'hafs', 24, 61, 'لَّيْسَ عَلَى ٱلْأَعْمَىٰ حَرَجٌۭ وَلَا عَلَى ٱلْأَعْرَجِ حَرَجٌۭ وَلَا عَلَى ٱلْمَرِيضِ حَرَجٌۭ وَلَا عَلَىٰٓ أَنفُسِكُمْ أَن تَأْكُلُوا۟ مِنۢ بُيُوتِكُمْ أَوْ بُيُوتِ ءَابَآئِكُمْ أَوْ بُيُوتِ أُمَّهَٰتِكُمْ أَوْ بُيُوتِ إِخْوَٰنِكُمْ أَوْ بُيُوتِ أَخَوَٰتِكُمْ أَوْ بُيُوتِ أَعْمَٰمِكُمْ أَوْ بُيُوتِ عَمَّٰتِكُمْ أَوْ بُيُوتِ أَخْوَٰلِكُمْ أَوْ بُيُوتِ خَٰلَٰتِكُمْ أَوْ مَا مَلَكْتُم مَّفَاتِحَهُۥٓ أَوْ صَدِيقِكُمْ ۚ لَيْسَ عَلَيْكُمْ جُنَاحٌ أَن تَأْكُلُوا۟ جَمِيعًا أَوْ أَشْتَاتًۭا ۚ فَإِذَا دَخَلْتُم بُيُوتًۭا فَسَلِّمُوا۟ عَلَىٰٓ أَنفُسِكُمْ تَحِيَّةًۭ مِّنْ عِندِ ٱللَّهِ مُبَٰرَكَةًۭ طَيِّبَةًۭ ۚ كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ لَكُمُ ٱلْءَايَٰتِ لَعَلَّكُمْ تَعْقِلُونَ', 'ليس على الأعمى حرج ولا على الأعرج حرج ولا على المريض حرج ولا على أنفسكم أن تأكلوا من بيوتكم أو بيوت ءابائكم أو بيوت أمهتكم أو بيوت إخونكم أو بيوت أخوتكم أو بيوت أعممكم أو بيوت عمتكم أو بيوت أخولكم أو بيوت خلتكم أو ما ملكتم مفاتحه أو صديقكم  ليس عليكم جناح أن تأكلوا جميعا أو أشتاتا  فإذا دخلتم بيوتا فسلموا على أنفسكم تحية من عند الله مبركة طيبة  كذلك يبين الله لكم الءايت لعلكم تعقلون', NULL, 358, 'local:hafs-text.json'),
  ('hafs-24-62', 'hafs', 24, 62, 'إِنَّمَا ٱلْمُؤْمِنُونَ ٱلَّذِينَ ءَامَنُوا۟ بِٱللَّهِ وَرَسُولِهِۦ وَإِذَا كَانُوا۟ مَعَهُۥ عَلَىٰٓ أَمْرٍۢ جَامِعٍۢ لَّمْ يَذْهَبُوا۟ حَتَّىٰ يَسْتَـْٔذِنُوهُ ۚ إِنَّ ٱلَّذِينَ يَسْتَـْٔذِنُونَكَ أُو۟لَٰٓئِكَ ٱلَّذِينَ يُؤْمِنُونَ بِٱللَّهِ وَرَسُولِهِۦ ۚ فَإِذَا ٱسْتَـْٔذَنُوكَ لِبَعْضِ شَأْنِهِمْ فَأْذَن لِّمَن شِئْتَ مِنْهُمْ وَٱسْتَغْفِرْ لَهُمُ ٱللَّهَ ۚ إِنَّ ٱللَّهَ غَفُورٌۭ رَّحِيمٌۭ', 'إنما المؤمنون الذين ءامنوا بالله ورسوله وإذا كانوا معه على أمر جامع لم يذهبوا حتى يستذنوه  إن الذين يستذنونك أولئك الذين يؤمنون بالله ورسوله  فإذا استذنوك لبعض شأنهم فأذن لمن شئت منهم واستغفر لهم الله  إن الله غفور رحيم', NULL, 359, 'local:hafs-text.json'),
  ('hafs-24-63', 'hafs', 24, 63, 'لَّا تَجْعَلُوا۟ دُعَآءَ ٱلرَّسُولِ بَيْنَكُمْ كَدُعَآءِ بَعْضِكُم بَعْضًۭا ۚ قَدْ يَعْلَمُ ٱللَّهُ ٱلَّذِينَ يَتَسَلَّلُونَ مِنكُمْ لِوَاذًۭا ۚ فَلْيَحْذَرِ ٱلَّذِينَ يُخَالِفُونَ عَنْ أَمْرِهِۦٓ أَن تُصِيبَهُمْ فِتْنَةٌ أَوْ يُصِيبَهُمْ عَذَابٌ أَلِيمٌ', 'لا تجعلوا دعاء الرسول بينكم كدعاء بعضكم بعضا  قد يعلم الله الذين يتسللون منكم لواذا  فليحذر الذين يخالفون عن أمره أن تصيبهم فتنة أو يصيبهم عذاب أليم', NULL, 359, 'local:hafs-text.json'),
  ('hafs-24-64', 'hafs', 24, 64, 'أَلَآ إِنَّ لِلَّهِ مَا فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ ۖ قَدْ يَعْلَمُ مَآ أَنتُمْ عَلَيْهِ وَيَوْمَ يُرْجَعُونَ إِلَيْهِ فَيُنَبِّئُهُم بِمَا عَمِلُوا۟ ۗ وَٱللَّهُ بِكُلِّ شَىْءٍ عَلِيمٌۢ', 'ألا إن لله ما فى السموت والأرض  قد يعلم ما أنتم عليه ويوم يرجعون إليه فينبئهم بما عملوا  والله بكل شىء عليم', NULL, 359, 'local:hafs-text.json'),
  ('hafs-25-1', 'hafs', 25, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ تَبَارَكَ ٱلَّذِى نَزَّلَ ٱلْفُرْقَانَ عَلَىٰ عَبْدِهِۦ لِيَكُونَ لِلْعَٰلَمِينَ نَذِيرًا', 'بسم الله الرحمن الرحيم تبارك الذى نزل الفرقان على عبده ليكون للعلمين نذيرا', NULL, 359, 'local:hafs-text.json'),
  ('hafs-25-2', 'hafs', 25, 2, 'ٱلَّذِى لَهُۥ مُلْكُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَلَمْ يَتَّخِذْ وَلَدًۭا وَلَمْ يَكُن لَّهُۥ شَرِيكٌۭ فِى ٱلْمُلْكِ وَخَلَقَ كُلَّ شَىْءٍۢ فَقَدَّرَهُۥ تَقْدِيرًۭا', 'الذى له ملك السموت والأرض ولم يتخذ ولدا ولم يكن له شريك فى الملك وخلق كل شىء فقدره تقديرا', NULL, 359, 'local:hafs-text.json'),
  ('hafs-25-3', 'hafs', 25, 3, 'وَٱتَّخَذُوا۟ مِن دُونِهِۦٓ ءَالِهَةًۭ لَّا يَخْلُقُونَ شَيْـًۭٔا وَهُمْ يُخْلَقُونَ وَلَا يَمْلِكُونَ لِأَنفُسِهِمْ ضَرًّۭا وَلَا نَفْعًۭا وَلَا يَمْلِكُونَ مَوْتًۭا وَلَا حَيَوٰةًۭ وَلَا نُشُورًۭا', 'واتخذوا من دونه ءالهة لا يخلقون شيا وهم يخلقون ولا يملكون لأنفسهم ضرا ولا نفعا ولا يملكون موتا ولا حيوة ولا نشورا', NULL, 360, 'local:hafs-text.json'),
  ('hafs-25-4', 'hafs', 25, 4, 'وَقَالَ ٱلَّذِينَ كَفَرُوٓا۟ إِنْ هَٰذَآ إِلَّآ إِفْكٌ ٱفْتَرَىٰهُ وَأَعَانَهُۥ عَلَيْهِ قَوْمٌ ءَاخَرُونَ ۖ فَقَدْ جَآءُو ظُلْمًۭا وَزُورًۭا', 'وقال الذين كفروا إن هذا إلا إفك افترىه وأعانه عليه قوم ءاخرون  فقد جاءو ظلما وزورا', NULL, 360, 'local:hafs-text.json'),
  ('hafs-25-5', 'hafs', 25, 5, 'وَقَالُوٓا۟ أَسَٰطِيرُ ٱلْأَوَّلِينَ ٱكْتَتَبَهَا فَهِىَ تُمْلَىٰ عَلَيْهِ بُكْرَةًۭ وَأَصِيلًۭا', 'وقالوا أسطير الأولين اكتتبها فهى تملى عليه بكرة وأصيلا', NULL, 360, 'local:hafs-text.json'),
  ('hafs-25-6', 'hafs', 25, 6, 'قُلْ أَنزَلَهُ ٱلَّذِى يَعْلَمُ ٱلسِّرَّ فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ ۚ إِنَّهُۥ كَانَ غَفُورًۭا رَّحِيمًۭا', 'قل أنزله الذى يعلم السر فى السموت والأرض  إنه كان غفورا رحيما', NULL, 360, 'local:hafs-text.json'),
  ('hafs-25-7', 'hafs', 25, 7, 'وَقَالُوا۟ مَالِ هَٰذَا ٱلرَّسُولِ يَأْكُلُ ٱلطَّعَامَ وَيَمْشِى فِى ٱلْأَسْوَاقِ ۙ لَوْلَآ أُنزِلَ إِلَيْهِ مَلَكٌۭ فَيَكُونَ مَعَهُۥ نَذِيرًا', 'وقالوا مال هذا الرسول يأكل الطعام ويمشى فى الأسواق  لولا أنزل إليه ملك فيكون معه نذيرا', NULL, 360, 'local:hafs-text.json'),
  ('hafs-25-8', 'hafs', 25, 8, 'أَوْ يُلْقَىٰٓ إِلَيْهِ كَنزٌ أَوْ تَكُونُ لَهُۥ جَنَّةٌۭ يَأْكُلُ مِنْهَا ۚ وَقَالَ ٱلظَّٰلِمُونَ إِن تَتَّبِعُونَ إِلَّا رَجُلًۭا مَّسْحُورًا', 'أو يلقى إليه كنز أو تكون له جنة يأكل منها  وقال الظلمون إن تتبعون إلا رجلا مسحورا', NULL, 360, 'local:hafs-text.json'),
  ('hafs-25-9', 'hafs', 25, 9, 'ٱنظُرْ كَيْفَ ضَرَبُوا۟ لَكَ ٱلْأَمْثَٰلَ فَضَلُّوا۟ فَلَا يَسْتَطِيعُونَ سَبِيلًۭا', 'انظر كيف ضربوا لك الأمثل فضلوا فلا يستطيعون سبيلا', NULL, 360, 'local:hafs-text.json'),
  ('hafs-25-10', 'hafs', 25, 10, 'تَبَارَكَ ٱلَّذِىٓ إِن شَآءَ جَعَلَ لَكَ خَيْرًۭا مِّن ذَٰلِكَ جَنَّٰتٍۢ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ وَيَجْعَل لَّكَ قُصُورًۢا', 'تبارك الذى إن شاء جعل لك خيرا من ذلك جنت تجرى من تحتها الأنهر ويجعل لك قصورا', NULL, 360, 'local:hafs-text.json'),
  ('hafs-25-11', 'hafs', 25, 11, 'بَلْ كَذَّبُوا۟ بِٱلسَّاعَةِ ۖ وَأَعْتَدْنَا لِمَن كَذَّبَ بِٱلسَّاعَةِ سَعِيرًا', 'بل كذبوا بالساعة  وأعتدنا لمن كذب بالساعة سعيرا', NULL, 360, 'local:hafs-text.json'),
  ('hafs-25-12', 'hafs', 25, 12, 'إِذَا رَأَتْهُم مِّن مَّكَانٍۭ بَعِيدٍۢ سَمِعُوا۟ لَهَا تَغَيُّظًۭا وَزَفِيرًۭا', 'إذا رأتهم من مكان بعيد سمعوا لها تغيظا وزفيرا', NULL, 361, 'local:hafs-text.json'),
  ('hafs-25-13', 'hafs', 25, 13, 'وَإِذَآ أُلْقُوا۟ مِنْهَا مَكَانًۭا ضَيِّقًۭا مُّقَرَّنِينَ دَعَوْا۟ هُنَالِكَ ثُبُورًۭا', 'وإذا ألقوا منها مكانا ضيقا مقرنين دعوا هنالك ثبورا', NULL, 361, 'local:hafs-text.json'),
  ('hafs-25-14', 'hafs', 25, 14, 'لَّا تَدْعُوا۟ ٱلْيَوْمَ ثُبُورًۭا وَٰحِدًۭا وَٱدْعُوا۟ ثُبُورًۭا كَثِيرًۭا', 'لا تدعوا اليوم ثبورا وحدا وادعوا ثبورا كثيرا', NULL, 361, 'local:hafs-text.json'),
  ('hafs-25-15', 'hafs', 25, 15, 'قُلْ أَذَٰلِكَ خَيْرٌ أَمْ جَنَّةُ ٱلْخُلْدِ ٱلَّتِى وُعِدَ ٱلْمُتَّقُونَ ۚ كَانَتْ لَهُمْ جَزَآءًۭ وَمَصِيرًۭا', 'قل أذلك خير أم جنة الخلد التى وعد المتقون  كانت لهم جزاء ومصيرا', NULL, 361, 'local:hafs-text.json'),
  ('hafs-25-16', 'hafs', 25, 16, 'لَّهُمْ فِيهَا مَا يَشَآءُونَ خَٰلِدِينَ ۚ كَانَ عَلَىٰ رَبِّكَ وَعْدًۭا مَّسْـُٔولًۭا', 'لهم فيها ما يشاءون خلدين  كان على ربك وعدا مسولا', NULL, 361, 'local:hafs-text.json'),
  ('hafs-25-17', 'hafs', 25, 17, 'وَيَوْمَ يَحْشُرُهُمْ وَمَا يَعْبُدُونَ مِن دُونِ ٱللَّهِ فَيَقُولُ ءَأَنتُمْ أَضْلَلْتُمْ عِبَادِى هَٰٓؤُلَآءِ أَمْ هُمْ ضَلُّوا۟ ٱلسَّبِيلَ', 'ويوم يحشرهم وما يعبدون من دون الله فيقول ءأنتم أضللتم عبادى هؤلاء أم هم ضلوا السبيل', NULL, 361, 'local:hafs-text.json'),
  ('hafs-25-18', 'hafs', 25, 18, 'قَالُوا۟ سُبْحَٰنَكَ مَا كَانَ يَنۢبَغِى لَنَآ أَن نَّتَّخِذَ مِن دُونِكَ مِنْ أَوْلِيَآءَ وَلَٰكِن مَّتَّعْتَهُمْ وَءَابَآءَهُمْ حَتَّىٰ نَسُوا۟ ٱلذِّكْرَ وَكَانُوا۟ قَوْمًۢا بُورًۭا', 'قالوا سبحنك ما كان ينبغى لنا أن نتخذ من دونك من أولياء ولكن متعتهم وءاباءهم حتى نسوا الذكر وكانوا قوما بورا', NULL, 361, 'local:hafs-text.json'),
  ('hafs-25-19', 'hafs', 25, 19, 'فَقَدْ كَذَّبُوكُم بِمَا تَقُولُونَ فَمَا تَسْتَطِيعُونَ صَرْفًۭا وَلَا نَصْرًۭا ۚ وَمَن يَظْلِم مِّنكُمْ نُذِقْهُ عَذَابًۭا كَبِيرًۭا', 'فقد كذبوكم بما تقولون فما تستطيعون صرفا ولا نصرا  ومن يظلم منكم نذقه عذابا كبيرا', NULL, 361, 'local:hafs-text.json'),
  ('hafs-25-20', 'hafs', 25, 20, 'وَمَآ أَرْسَلْنَا قَبْلَكَ مِنَ ٱلْمُرْسَلِينَ إِلَّآ إِنَّهُمْ لَيَأْكُلُونَ ٱلطَّعَامَ وَيَمْشُونَ فِى ٱلْأَسْوَاقِ ۗ وَجَعَلْنَا بَعْضَكُمْ لِبَعْضٍۢ فِتْنَةً أَتَصْبِرُونَ ۗ وَكَانَ رَبُّكَ بَصِيرًۭا', 'وما أرسلنا قبلك من المرسلين إلا إنهم ليأكلون الطعام ويمشون فى الأسواق  وجعلنا بعضكم لبعض فتنة أتصبرون  وكان ربك بصيرا', NULL, 361, 'local:hafs-text.json'),
  ('hafs-25-21', 'hafs', 25, 21, '۞ وَقَالَ ٱلَّذِينَ لَا يَرْجُونَ لِقَآءَنَا لَوْلَآ أُنزِلَ عَلَيْنَا ٱلْمَلَٰٓئِكَةُ أَوْ نَرَىٰ رَبَّنَا ۗ لَقَدِ ٱسْتَكْبَرُوا۟ فِىٓ أَنفُسِهِمْ وَعَتَوْ عُتُوًّۭا كَبِيرًۭا', 'وقال الذين لا يرجون لقاءنا لولا أنزل علينا الملئكة أو نرى ربنا  لقد استكبروا فى أنفسهم وعتو عتوا كبيرا', NULL, 362, 'local:hafs-text.json'),
  ('hafs-25-22', 'hafs', 25, 22, 'يَوْمَ يَرَوْنَ ٱلْمَلَٰٓئِكَةَ لَا بُشْرَىٰ يَوْمَئِذٍۢ لِّلْمُجْرِمِينَ وَيَقُولُونَ حِجْرًۭا مَّحْجُورًۭا', 'يوم يرون الملئكة لا بشرى يومئذ للمجرمين ويقولون حجرا محجورا', NULL, 362, 'local:hafs-text.json'),
  ('hafs-25-23', 'hafs', 25, 23, 'وَقَدِمْنَآ إِلَىٰ مَا عَمِلُوا۟ مِنْ عَمَلٍۢ فَجَعَلْنَٰهُ هَبَآءًۭ مَّنثُورًا', 'وقدمنا إلى ما عملوا من عمل فجعلنه هباء منثورا', NULL, 362, 'local:hafs-text.json'),
  ('hafs-25-24', 'hafs', 25, 24, 'أَصْحَٰبُ ٱلْجَنَّةِ يَوْمَئِذٍ خَيْرٌۭ مُّسْتَقَرًّۭا وَأَحْسَنُ مَقِيلًۭا', 'أصحب الجنة يومئذ خير مستقرا وأحسن مقيلا', NULL, 362, 'local:hafs-text.json'),
  ('hafs-25-25', 'hafs', 25, 25, 'وَيَوْمَ تَشَقَّقُ ٱلسَّمَآءُ بِٱلْغَمَٰمِ وَنُزِّلَ ٱلْمَلَٰٓئِكَةُ تَنزِيلًا', 'ويوم تشقق السماء بالغمم ونزل الملئكة تنزيلا', NULL, 362, 'local:hafs-text.json'),
  ('hafs-25-26', 'hafs', 25, 26, 'ٱلْمُلْكُ يَوْمَئِذٍ ٱلْحَقُّ لِلرَّحْمَٰنِ ۚ وَكَانَ يَوْمًا عَلَى ٱلْكَٰفِرِينَ عَسِيرًۭا', 'الملك يومئذ الحق للرحمن  وكان يوما على الكفرين عسيرا', NULL, 362, 'local:hafs-text.json'),
  ('hafs-25-27', 'hafs', 25, 27, 'وَيَوْمَ يَعَضُّ ٱلظَّالِمُ عَلَىٰ يَدَيْهِ يَقُولُ يَٰلَيْتَنِى ٱتَّخَذْتُ مَعَ ٱلرَّسُولِ سَبِيلًۭا', 'ويوم يعض الظالم على يديه يقول يليتنى اتخذت مع الرسول سبيلا', NULL, 362, 'local:hafs-text.json'),
  ('hafs-25-28', 'hafs', 25, 28, 'يَٰوَيْلَتَىٰ لَيْتَنِى لَمْ أَتَّخِذْ فُلَانًا خَلِيلًۭا', 'يويلتى ليتنى لم أتخذ فلانا خليلا', NULL, 362, 'local:hafs-text.json'),
  ('hafs-25-29', 'hafs', 25, 29, 'لَّقَدْ أَضَلَّنِى عَنِ ٱلذِّكْرِ بَعْدَ إِذْ جَآءَنِى ۗ وَكَانَ ٱلشَّيْطَٰنُ لِلْإِنسَٰنِ خَذُولًۭا', 'لقد أضلنى عن الذكر بعد إذ جاءنى  وكان الشيطن للإنسن خذولا', NULL, 362, 'local:hafs-text.json'),
  ('hafs-25-30', 'hafs', 25, 30, 'وَقَالَ ٱلرَّسُولُ يَٰرَبِّ إِنَّ قَوْمِى ٱتَّخَذُوا۟ هَٰذَا ٱلْقُرْءَانَ مَهْجُورًۭا', 'وقال الرسول يرب إن قومى اتخذوا هذا القرءان مهجورا', NULL, 362, 'local:hafs-text.json'),
  ('hafs-25-31', 'hafs', 25, 31, 'وَكَذَٰلِكَ جَعَلْنَا لِكُلِّ نَبِىٍّ عَدُوًّۭا مِّنَ ٱلْمُجْرِمِينَ ۗ وَكَفَىٰ بِرَبِّكَ هَادِيًۭا وَنَصِيرًۭا', 'وكذلك جعلنا لكل نبى عدوا من المجرمين  وكفى بربك هاديا ونصيرا', NULL, 362, 'local:hafs-text.json'),
  ('hafs-25-32', 'hafs', 25, 32, 'وَقَالَ ٱلَّذِينَ كَفَرُوا۟ لَوْلَا نُزِّلَ عَلَيْهِ ٱلْقُرْءَانُ جُمْلَةًۭ وَٰحِدَةًۭ ۚ كَذَٰلِكَ لِنُثَبِّتَ بِهِۦ فُؤَادَكَ ۖ وَرَتَّلْنَٰهُ تَرْتِيلًۭا', 'وقال الذين كفروا لولا نزل عليه القرءان جملة وحدة  كذلك لنثبت به فؤادك  ورتلنه ترتيلا', NULL, 362, 'local:hafs-text.json'),
  ('hafs-25-33', 'hafs', 25, 33, 'وَلَا يَأْتُونَكَ بِمَثَلٍ إِلَّا جِئْنَٰكَ بِٱلْحَقِّ وَأَحْسَنَ تَفْسِيرًا', 'ولا يأتونك بمثل إلا جئنك بالحق وأحسن تفسيرا', NULL, 363, 'local:hafs-text.json'),
  ('hafs-25-34', 'hafs', 25, 34, 'ٱلَّذِينَ يُحْشَرُونَ عَلَىٰ وُجُوهِهِمْ إِلَىٰ جَهَنَّمَ أُو۟لَٰٓئِكَ شَرٌّۭ مَّكَانًۭا وَأَضَلُّ سَبِيلًۭا', 'الذين يحشرون على وجوههم إلى جهنم أولئك شر مكانا وأضل سبيلا', NULL, 363, 'local:hafs-text.json'),
  ('hafs-25-35', 'hafs', 25, 35, 'وَلَقَدْ ءَاتَيْنَا مُوسَى ٱلْكِتَٰبَ وَجَعَلْنَا مَعَهُۥٓ أَخَاهُ هَٰرُونَ وَزِيرًۭا', 'ولقد ءاتينا موسى الكتب وجعلنا معه أخاه هرون وزيرا', NULL, 363, 'local:hafs-text.json'),
  ('hafs-25-36', 'hafs', 25, 36, 'فَقُلْنَا ٱذْهَبَآ إِلَى ٱلْقَوْمِ ٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَٰتِنَا فَدَمَّرْنَٰهُمْ تَدْمِيرًۭا', 'فقلنا اذهبا إلى القوم الذين كذبوا بايتنا فدمرنهم تدميرا', NULL, 363, 'local:hafs-text.json'),
  ('hafs-25-37', 'hafs', 25, 37, 'وَقَوْمَ نُوحٍۢ لَّمَّا كَذَّبُوا۟ ٱلرُّسُلَ أَغْرَقْنَٰهُمْ وَجَعَلْنَٰهُمْ لِلنَّاسِ ءَايَةًۭ ۖ وَأَعْتَدْنَا لِلظَّٰلِمِينَ عَذَابًا أَلِيمًۭا', 'وقوم نوح لما كذبوا الرسل أغرقنهم وجعلنهم للناس ءاية  وأعتدنا للظلمين عذابا أليما', NULL, 363, 'local:hafs-text.json'),
  ('hafs-25-38', 'hafs', 25, 38, 'وَعَادًۭا وَثَمُودَا۟ وَأَصْحَٰبَ ٱلرَّسِّ وَقُرُونًۢا بَيْنَ ذَٰلِكَ كَثِيرًۭا', 'وعادا وثمودا وأصحب الرس وقرونا بين ذلك كثيرا', NULL, 363, 'local:hafs-text.json'),
  ('hafs-25-39', 'hafs', 25, 39, 'وَكُلًّۭا ضَرَبْنَا لَهُ ٱلْأَمْثَٰلَ ۖ وَكُلًّۭا تَبَّرْنَا تَتْبِيرًۭا', 'وكلا ضربنا له الأمثل  وكلا تبرنا تتبيرا', NULL, 363, 'local:hafs-text.json'),
  ('hafs-25-40', 'hafs', 25, 40, 'وَلَقَدْ أَتَوْا۟ عَلَى ٱلْقَرْيَةِ ٱلَّتِىٓ أُمْطِرَتْ مَطَرَ ٱلسَّوْءِ ۚ أَفَلَمْ يَكُونُوا۟ يَرَوْنَهَا ۚ بَلْ كَانُوا۟ لَا يَرْجُونَ نُشُورًۭا', 'ولقد أتوا على القرية التى أمطرت مطر السوء  أفلم يكونوا يرونها  بل كانوا لا يرجون نشورا', NULL, 363, 'local:hafs-text.json'),
  ('hafs-25-41', 'hafs', 25, 41, 'وَإِذَا رَأَوْكَ إِن يَتَّخِذُونَكَ إِلَّا هُزُوًا أَهَٰذَا ٱلَّذِى بَعَثَ ٱللَّهُ رَسُولًا', 'وإذا رأوك إن يتخذونك إلا هزوا أهذا الذى بعث الله رسولا', NULL, 363, 'local:hafs-text.json'),
  ('hafs-25-42', 'hafs', 25, 42, 'إِن كَادَ لَيُضِلُّنَا عَنْ ءَالِهَتِنَا لَوْلَآ أَن صَبَرْنَا عَلَيْهَا ۚ وَسَوْفَ يَعْلَمُونَ حِينَ يَرَوْنَ ٱلْعَذَابَ مَنْ أَضَلُّ سَبِيلًا', 'إن كاد ليضلنا عن ءالهتنا لولا أن صبرنا عليها  وسوف يعلمون حين يرون العذاب من أضل سبيلا', NULL, 363, 'local:hafs-text.json'),
  ('hafs-25-43', 'hafs', 25, 43, 'أَرَءَيْتَ مَنِ ٱتَّخَذَ إِلَٰهَهُۥ هَوَىٰهُ أَفَأَنتَ تَكُونُ عَلَيْهِ وَكِيلًا', 'أرءيت من اتخذ إلهه هوىه أفأنت تكون عليه وكيلا', NULL, 363, 'local:hafs-text.json'),
  ('hafs-25-44', 'hafs', 25, 44, 'أَمْ تَحْسَبُ أَنَّ أَكْثَرَهُمْ يَسْمَعُونَ أَوْ يَعْقِلُونَ ۚ إِنْ هُمْ إِلَّا كَٱلْأَنْعَٰمِ ۖ بَلْ هُمْ أَضَلُّ سَبِيلًا', 'أم تحسب أن أكثرهم يسمعون أو يعقلون  إن هم إلا كالأنعم  بل هم أضل سبيلا', NULL, 364, 'local:hafs-text.json'),
  ('hafs-25-45', 'hafs', 25, 45, 'أَلَمْ تَرَ إِلَىٰ رَبِّكَ كَيْفَ مَدَّ ٱلظِّلَّ وَلَوْ شَآءَ لَجَعَلَهُۥ سَاكِنًۭا ثُمَّ جَعَلْنَا ٱلشَّمْسَ عَلَيْهِ دَلِيلًۭا', 'ألم تر إلى ربك كيف مد الظل ولو شاء لجعله ساكنا ثم جعلنا الشمس عليه دليلا', NULL, 364, 'local:hafs-text.json'),
  ('hafs-25-46', 'hafs', 25, 46, 'ثُمَّ قَبَضْنَٰهُ إِلَيْنَا قَبْضًۭا يَسِيرًۭا', 'ثم قبضنه إلينا قبضا يسيرا', NULL, 364, 'local:hafs-text.json'),
  ('hafs-25-47', 'hafs', 25, 47, 'وَهُوَ ٱلَّذِى جَعَلَ لَكُمُ ٱلَّيْلَ لِبَاسًۭا وَٱلنَّوْمَ سُبَاتًۭا وَجَعَلَ ٱلنَّهَارَ نُشُورًۭا', 'وهو الذى جعل لكم اليل لباسا والنوم سباتا وجعل النهار نشورا', NULL, 364, 'local:hafs-text.json'),
  ('hafs-25-48', 'hafs', 25, 48, 'وَهُوَ ٱلَّذِىٓ أَرْسَلَ ٱلرِّيَٰحَ بُشْرًۢا بَيْنَ يَدَىْ رَحْمَتِهِۦ ۚ وَأَنزَلْنَا مِنَ ٱلسَّمَآءِ مَآءًۭ طَهُورًۭا', 'وهو الذى أرسل الريح بشرا بين يدى رحمته  وأنزلنا من السماء ماء طهورا', NULL, 364, 'local:hafs-text.json'),
  ('hafs-25-49', 'hafs', 25, 49, 'لِّنُحْۦِىَ بِهِۦ بَلْدَةًۭ مَّيْتًۭا وَنُسْقِيَهُۥ مِمَّا خَلَقْنَآ أَنْعَٰمًۭا وَأَنَاسِىَّ كَثِيرًۭا', 'لنحى به بلدة ميتا ونسقيه مما خلقنا أنعما وأناسى كثيرا', NULL, 364, 'local:hafs-text.json'),
  ('hafs-25-50', 'hafs', 25, 50, 'وَلَقَدْ صَرَّفْنَٰهُ بَيْنَهُمْ لِيَذَّكَّرُوا۟ فَأَبَىٰٓ أَكْثَرُ ٱلنَّاسِ إِلَّا كُفُورًۭا', 'ولقد صرفنه بينهم ليذكروا فأبى أكثر الناس إلا كفورا', NULL, 364, 'local:hafs-text.json'),
  ('hafs-25-51', 'hafs', 25, 51, 'وَلَوْ شِئْنَا لَبَعَثْنَا فِى كُلِّ قَرْيَةٍۢ نَّذِيرًۭا', 'ولو شئنا لبعثنا فى كل قرية نذيرا', NULL, 364, 'local:hafs-text.json'),
  ('hafs-25-52', 'hafs', 25, 52, 'فَلَا تُطِعِ ٱلْكَٰفِرِينَ وَجَٰهِدْهُم بِهِۦ جِهَادًۭا كَبِيرًۭا', 'فلا تطع الكفرين وجهدهم به جهادا كبيرا', NULL, 364, 'local:hafs-text.json'),
  ('hafs-25-53', 'hafs', 25, 53, '۞ وَهُوَ ٱلَّذِى مَرَجَ ٱلْبَحْرَيْنِ هَٰذَا عَذْبٌۭ فُرَاتٌۭ وَهَٰذَا مِلْحٌ أُجَاجٌۭ وَجَعَلَ بَيْنَهُمَا بَرْزَخًۭا وَحِجْرًۭا مَّحْجُورًۭا', 'وهو الذى مرج البحرين هذا عذب فرات وهذا ملح أجاج وجعل بينهما برزخا وحجرا محجورا', NULL, 364, 'local:hafs-text.json'),
  ('hafs-25-54', 'hafs', 25, 54, 'وَهُوَ ٱلَّذِى خَلَقَ مِنَ ٱلْمَآءِ بَشَرًۭا فَجَعَلَهُۥ نَسَبًۭا وَصِهْرًۭا ۗ وَكَانَ رَبُّكَ قَدِيرًۭا', 'وهو الذى خلق من الماء بشرا فجعله نسبا وصهرا  وكان ربك قديرا', NULL, 364, 'local:hafs-text.json'),
  ('hafs-25-55', 'hafs', 25, 55, 'وَيَعْبُدُونَ مِن دُونِ ٱللَّهِ مَا لَا يَنفَعُهُمْ وَلَا يَضُرُّهُمْ ۗ وَكَانَ ٱلْكَافِرُ عَلَىٰ رَبِّهِۦ ظَهِيرًۭا', 'ويعبدون من دون الله ما لا ينفعهم ولا يضرهم  وكان الكافر على ربه ظهيرا', NULL, 364, 'local:hafs-text.json'),
  ('hafs-25-56', 'hafs', 25, 56, 'وَمَآ أَرْسَلْنَٰكَ إِلَّا مُبَشِّرًۭا وَنَذِيرًۭا', 'وما أرسلنك إلا مبشرا ونذيرا', NULL, 365, 'local:hafs-text.json'),
  ('hafs-25-57', 'hafs', 25, 57, 'قُلْ مَآ أَسْـَٔلُكُمْ عَلَيْهِ مِنْ أَجْرٍ إِلَّا مَن شَآءَ أَن يَتَّخِذَ إِلَىٰ رَبِّهِۦ سَبِيلًۭا', 'قل ما أسلكم عليه من أجر إلا من شاء أن يتخذ إلى ربه سبيلا', NULL, 365, 'local:hafs-text.json'),
  ('hafs-25-58', 'hafs', 25, 58, 'وَتَوَكَّلْ عَلَى ٱلْحَىِّ ٱلَّذِى لَا يَمُوتُ وَسَبِّحْ بِحَمْدِهِۦ ۚ وَكَفَىٰ بِهِۦ بِذُنُوبِ عِبَادِهِۦ خَبِيرًا', 'وتوكل على الحى الذى لا يموت وسبح بحمده  وكفى به بذنوب عباده خبيرا', NULL, 365, 'local:hafs-text.json'),
  ('hafs-25-59', 'hafs', 25, 59, 'ٱلَّذِى خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ وَمَا بَيْنَهُمَا فِى سِتَّةِ أَيَّامٍۢ ثُمَّ ٱسْتَوَىٰ عَلَى ٱلْعَرْشِ ۚ ٱلرَّحْمَٰنُ فَسْـَٔلْ بِهِۦ خَبِيرًۭا', 'الذى خلق السموت والأرض وما بينهما فى ستة أيام ثم استوى على العرش  الرحمن فسل به خبيرا', NULL, 365, 'local:hafs-text.json'),
  ('hafs-25-60', 'hafs', 25, 60, 'وَإِذَا قِيلَ لَهُمُ ٱسْجُدُوا۟ لِلرَّحْمَٰنِ قَالُوا۟ وَمَا ٱلرَّحْمَٰنُ أَنَسْجُدُ لِمَا تَأْمُرُنَا وَزَادَهُمْ نُفُورًۭا ۩', 'وإذا قيل لهم اسجدوا للرحمن قالوا وما الرحمن أنسجد لما تأمرنا وزادهم نفورا', NULL, 365, 'local:hafs-text.json'),
  ('hafs-25-61', 'hafs', 25, 61, 'تَبَارَكَ ٱلَّذِى جَعَلَ فِى ٱلسَّمَآءِ بُرُوجًۭا وَجَعَلَ فِيهَا سِرَٰجًۭا وَقَمَرًۭا مُّنِيرًۭا', 'تبارك الذى جعل فى السماء بروجا وجعل فيها سرجا وقمرا منيرا', NULL, 365, 'local:hafs-text.json'),
  ('hafs-25-62', 'hafs', 25, 62, 'وَهُوَ ٱلَّذِى جَعَلَ ٱلَّيْلَ وَٱلنَّهَارَ خِلْفَةًۭ لِّمَنْ أَرَادَ أَن يَذَّكَّرَ أَوْ أَرَادَ شُكُورًۭا', 'وهو الذى جعل اليل والنهار خلفة لمن أراد أن يذكر أو أراد شكورا', NULL, 365, 'local:hafs-text.json'),
  ('hafs-25-63', 'hafs', 25, 63, 'وَعِبَادُ ٱلرَّحْمَٰنِ ٱلَّذِينَ يَمْشُونَ عَلَى ٱلْأَرْضِ هَوْنًۭا وَإِذَا خَاطَبَهُمُ ٱلْجَٰهِلُونَ قَالُوا۟ سَلَٰمًۭا', 'وعباد الرحمن الذين يمشون على الأرض هونا وإذا خاطبهم الجهلون قالوا سلما', NULL, 365, 'local:hafs-text.json'),
  ('hafs-25-64', 'hafs', 25, 64, 'وَٱلَّذِينَ يَبِيتُونَ لِرَبِّهِمْ سُجَّدًۭا وَقِيَٰمًۭا', 'والذين يبيتون لربهم سجدا وقيما', NULL, 365, 'local:hafs-text.json'),
  ('hafs-25-65', 'hafs', 25, 65, 'وَٱلَّذِينَ يَقُولُونَ رَبَّنَا ٱصْرِفْ عَنَّا عَذَابَ جَهَنَّمَ ۖ إِنَّ عَذَابَهَا كَانَ غَرَامًا', 'والذين يقولون ربنا اصرف عنا عذاب جهنم  إن عذابها كان غراما', NULL, 365, 'local:hafs-text.json'),
  ('hafs-25-66', 'hafs', 25, 66, 'إِنَّهَا سَآءَتْ مُسْتَقَرًّۭا وَمُقَامًۭا', 'إنها ساءت مستقرا ومقاما', NULL, 365, 'local:hafs-text.json'),
  ('hafs-25-67', 'hafs', 25, 67, 'وَٱلَّذِينَ إِذَآ أَنفَقُوا۟ لَمْ يُسْرِفُوا۟ وَلَمْ يَقْتُرُوا۟ وَكَانَ بَيْنَ ذَٰلِكَ قَوَامًۭا', 'والذين إذا أنفقوا لم يسرفوا ولم يقتروا وكان بين ذلك قواما', NULL, 365, 'local:hafs-text.json'),
  ('hafs-25-68', 'hafs', 25, 68, 'وَٱلَّذِينَ لَا يَدْعُونَ مَعَ ٱللَّهِ إِلَٰهًا ءَاخَرَ وَلَا يَقْتُلُونَ ٱلنَّفْسَ ٱلَّتِى حَرَّمَ ٱللَّهُ إِلَّا بِٱلْحَقِّ وَلَا يَزْنُونَ ۚ وَمَن يَفْعَلْ ذَٰلِكَ يَلْقَ أَثَامًۭا', 'والذين لا يدعون مع الله إلها ءاخر ولا يقتلون النفس التى حرم الله إلا بالحق ولا يزنون  ومن يفعل ذلك يلق أثاما', NULL, 366, 'local:hafs-text.json'),
  ('hafs-25-69', 'hafs', 25, 69, 'يُضَٰعَفْ لَهُ ٱلْعَذَابُ يَوْمَ ٱلْقِيَٰمَةِ وَيَخْلُدْ فِيهِۦ مُهَانًا', 'يضعف له العذاب يوم القيمة ويخلد فيه مهانا', NULL, 366, 'local:hafs-text.json'),
  ('hafs-25-70', 'hafs', 25, 70, 'إِلَّا مَن تَابَ وَءَامَنَ وَعَمِلَ عَمَلًۭا صَٰلِحًۭا فَأُو۟لَٰٓئِكَ يُبَدِّلُ ٱللَّهُ سَيِّـَٔاتِهِمْ حَسَنَٰتٍۢ ۗ وَكَانَ ٱللَّهُ غَفُورًۭا رَّحِيمًۭا', 'إلا من تاب وءامن وعمل عملا صلحا فأولئك يبدل الله سياتهم حسنت  وكان الله غفورا رحيما', NULL, 366, 'local:hafs-text.json'),
  ('hafs-25-71', 'hafs', 25, 71, 'وَمَن تَابَ وَعَمِلَ صَٰلِحًۭا فَإِنَّهُۥ يَتُوبُ إِلَى ٱللَّهِ مَتَابًۭا', 'ومن تاب وعمل صلحا فإنه يتوب إلى الله متابا', NULL, 366, 'local:hafs-text.json'),
  ('hafs-25-72', 'hafs', 25, 72, 'وَٱلَّذِينَ لَا يَشْهَدُونَ ٱلزُّورَ وَإِذَا مَرُّوا۟ بِٱللَّغْوِ مَرُّوا۟ كِرَامًۭا', 'والذين لا يشهدون الزور وإذا مروا باللغو مروا كراما', NULL, 366, 'local:hafs-text.json'),
  ('hafs-25-73', 'hafs', 25, 73, 'وَٱلَّذِينَ إِذَا ذُكِّرُوا۟ بِـَٔايَٰتِ رَبِّهِمْ لَمْ يَخِرُّوا۟ عَلَيْهَا صُمًّۭا وَعُمْيَانًۭا', 'والذين إذا ذكروا بايت ربهم لم يخروا عليها صما وعميانا', NULL, 366, 'local:hafs-text.json'),
  ('hafs-25-74', 'hafs', 25, 74, 'وَٱلَّذِينَ يَقُولُونَ رَبَّنَا هَبْ لَنَا مِنْ أَزْوَٰجِنَا وَذُرِّيَّٰتِنَا قُرَّةَ أَعْيُنٍۢ وَٱجْعَلْنَا لِلْمُتَّقِينَ إِمَامًا', 'والذين يقولون ربنا هب لنا من أزوجنا وذريتنا قرة أعين واجعلنا للمتقين إماما', NULL, 366, 'local:hafs-text.json'),
  ('hafs-25-75', 'hafs', 25, 75, 'أُو۟لَٰٓئِكَ يُجْزَوْنَ ٱلْغُرْفَةَ بِمَا صَبَرُوا۟ وَيُلَقَّوْنَ فِيهَا تَحِيَّةًۭ وَسَلَٰمًا', 'أولئك يجزون الغرفة بما صبروا ويلقون فيها تحية وسلما', NULL, 366, 'local:hafs-text.json'),
  ('hafs-25-76', 'hafs', 25, 76, 'خَٰلِدِينَ فِيهَا ۚ حَسُنَتْ مُسْتَقَرًّۭا وَمُقَامًۭا', 'خلدين فيها  حسنت مستقرا ومقاما', NULL, 366, 'local:hafs-text.json'),
  ('hafs-25-77', 'hafs', 25, 77, 'قُلْ مَا يَعْبَؤُا۟ بِكُمْ رَبِّى لَوْلَا دُعَآؤُكُمْ ۖ فَقَدْ كَذَّبْتُمْ فَسَوْفَ يَكُونُ لِزَامًۢا', 'قل ما يعبؤا بكم ربى لولا دعاؤكم  فقد كذبتم فسوف يكون لزاما', NULL, 366, 'local:hafs-text.json'),
  ('hafs-26-1', 'hafs', 26, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ طسٓمٓ', 'بسم الله الرحمن الرحيم طسم', NULL, 367, 'local:hafs-text.json'),
  ('hafs-26-2', 'hafs', 26, 2, 'تِلْكَ ءَايَٰتُ ٱلْكِتَٰبِ ٱلْمُبِينِ', 'تلك ءايت الكتب المبين', NULL, 367, 'local:hafs-text.json'),
  ('hafs-26-3', 'hafs', 26, 3, 'لَعَلَّكَ بَٰخِعٌۭ نَّفْسَكَ أَلَّا يَكُونُوا۟ مُؤْمِنِينَ', 'لعلك بخع نفسك ألا يكونوا مؤمنين', NULL, 367, 'local:hafs-text.json'),
  ('hafs-26-4', 'hafs', 26, 4, 'إِن نَّشَأْ نُنَزِّلْ عَلَيْهِم مِّنَ ٱلسَّمَآءِ ءَايَةًۭ فَظَلَّتْ أَعْنَٰقُهُمْ لَهَا خَٰضِعِينَ', 'إن نشأ ننزل عليهم من السماء ءاية فظلت أعنقهم لها خضعين', NULL, 367, 'local:hafs-text.json'),
  ('hafs-26-5', 'hafs', 26, 5, 'وَمَا يَأْتِيهِم مِّن ذِكْرٍۢ مِّنَ ٱلرَّحْمَٰنِ مُحْدَثٍ إِلَّا كَانُوا۟ عَنْهُ مُعْرِضِينَ', 'وما يأتيهم من ذكر من الرحمن محدث إلا كانوا عنه معرضين', NULL, 367, 'local:hafs-text.json'),
  ('hafs-26-6', 'hafs', 26, 6, 'فَقَدْ كَذَّبُوا۟ فَسَيَأْتِيهِمْ أَنۢبَٰٓؤُا۟ مَا كَانُوا۟ بِهِۦ يَسْتَهْزِءُونَ', 'فقد كذبوا فسيأتيهم أنبؤا ما كانوا به يستهزءون', NULL, 367, 'local:hafs-text.json'),
  ('hafs-26-7', 'hafs', 26, 7, 'أَوَلَمْ يَرَوْا۟ إِلَى ٱلْأَرْضِ كَمْ أَنۢبَتْنَا فِيهَا مِن كُلِّ زَوْجٍۢ كَرِيمٍ', 'أولم يروا إلى الأرض كم أنبتنا فيها من كل زوج كريم', NULL, 367, 'local:hafs-text.json'),
  ('hafs-26-8', 'hafs', 26, 8, 'إِنَّ فِى ذَٰلِكَ لَءَايَةًۭ ۖ وَمَا كَانَ أَكْثَرُهُم مُّؤْمِنِينَ', 'إن فى ذلك لءاية  وما كان أكثرهم مؤمنين', NULL, 367, 'local:hafs-text.json'),
  ('hafs-26-9', 'hafs', 26, 9, 'وَإِنَّ رَبَّكَ لَهُوَ ٱلْعَزِيزُ ٱلرَّحِيمُ', 'وإن ربك لهو العزيز الرحيم', NULL, 367, 'local:hafs-text.json'),
  ('hafs-26-10', 'hafs', 26, 10, 'وَإِذْ نَادَىٰ رَبُّكَ مُوسَىٰٓ أَنِ ٱئْتِ ٱلْقَوْمَ ٱلظَّٰلِمِينَ', 'وإذ نادى ربك موسى أن ائت القوم الظلمين', NULL, 367, 'local:hafs-text.json'),
  ('hafs-26-11', 'hafs', 26, 11, 'قَوْمَ فِرْعَوْنَ ۚ أَلَا يَتَّقُونَ', 'قوم فرعون  ألا يتقون', NULL, 367, 'local:hafs-text.json'),
  ('hafs-26-12', 'hafs', 26, 12, 'قَالَ رَبِّ إِنِّىٓ أَخَافُ أَن يُكَذِّبُونِ', 'قال رب إنى أخاف أن يكذبون', NULL, 367, 'local:hafs-text.json'),
  ('hafs-26-13', 'hafs', 26, 13, 'وَيَضِيقُ صَدْرِى وَلَا يَنطَلِقُ لِسَانِى فَأَرْسِلْ إِلَىٰ هَٰرُونَ', 'ويضيق صدرى ولا ينطلق لسانى فأرسل إلى هرون', NULL, 367, 'local:hafs-text.json'),
  ('hafs-26-14', 'hafs', 26, 14, 'وَلَهُمْ عَلَىَّ ذَنۢبٌۭ فَأَخَافُ أَن يَقْتُلُونِ', 'ولهم على ذنب فأخاف أن يقتلون', NULL, 367, 'local:hafs-text.json'),
  ('hafs-26-15', 'hafs', 26, 15, 'قَالَ كَلَّا ۖ فَٱذْهَبَا بِـَٔايَٰتِنَآ ۖ إِنَّا مَعَكُم مُّسْتَمِعُونَ', 'قال كلا  فاذهبا بايتنا  إنا معكم مستمعون', NULL, 367, 'local:hafs-text.json'),
  ('hafs-26-16', 'hafs', 26, 16, 'فَأْتِيَا فِرْعَوْنَ فَقُولَآ إِنَّا رَسُولُ رَبِّ ٱلْعَٰلَمِينَ', 'فأتيا فرعون فقولا إنا رسول رب العلمين', NULL, 367, 'local:hafs-text.json'),
  ('hafs-26-17', 'hafs', 26, 17, 'أَنْ أَرْسِلْ مَعَنَا بَنِىٓ إِسْرَٰٓءِيلَ', 'أن أرسل معنا بنى إسرءيل', NULL, 367, 'local:hafs-text.json'),
  ('hafs-26-18', 'hafs', 26, 18, 'قَالَ أَلَمْ نُرَبِّكَ فِينَا وَلِيدًۭا وَلَبِثْتَ فِينَا مِنْ عُمُرِكَ سِنِينَ', 'قال ألم نربك فينا وليدا ولبثت فينا من عمرك سنين', NULL, 367, 'local:hafs-text.json'),
  ('hafs-26-19', 'hafs', 26, 19, 'وَفَعَلْتَ فَعْلَتَكَ ٱلَّتِى فَعَلْتَ وَأَنتَ مِنَ ٱلْكَٰفِرِينَ', 'وفعلت فعلتك التى فعلت وأنت من الكفرين', NULL, 367, 'local:hafs-text.json'),
  ('hafs-26-20', 'hafs', 26, 20, 'قَالَ فَعَلْتُهَآ إِذًۭا وَأَنَا۠ مِنَ ٱلضَّآلِّينَ', 'قال فعلتها إذا وأنا من الضالين', NULL, 368, 'local:hafs-text.json'),
  ('hafs-26-21', 'hafs', 26, 21, 'فَفَرَرْتُ مِنكُمْ لَمَّا خِفْتُكُمْ فَوَهَبَ لِى رَبِّى حُكْمًۭا وَجَعَلَنِى مِنَ ٱلْمُرْسَلِينَ', 'ففررت منكم لما خفتكم فوهب لى ربى حكما وجعلنى من المرسلين', NULL, 368, 'local:hafs-text.json'),
  ('hafs-26-22', 'hafs', 26, 22, 'وَتِلْكَ نِعْمَةٌۭ تَمُنُّهَا عَلَىَّ أَنْ عَبَّدتَّ بَنِىٓ إِسْرَٰٓءِيلَ', 'وتلك نعمة تمنها على أن عبدت بنى إسرءيل', NULL, 368, 'local:hafs-text.json'),
  ('hafs-26-23', 'hafs', 26, 23, 'قَالَ فِرْعَوْنُ وَمَا رَبُّ ٱلْعَٰلَمِينَ', 'قال فرعون وما رب العلمين', NULL, 368, 'local:hafs-text.json'),
  ('hafs-26-24', 'hafs', 26, 24, 'قَالَ رَبُّ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَمَا بَيْنَهُمَآ ۖ إِن كُنتُم مُّوقِنِينَ', 'قال رب السموت والأرض وما بينهما  إن كنتم موقنين', NULL, 368, 'local:hafs-text.json'),
  ('hafs-26-25', 'hafs', 26, 25, 'قَالَ لِمَنْ حَوْلَهُۥٓ أَلَا تَسْتَمِعُونَ', 'قال لمن حوله ألا تستمعون', NULL, 368, 'local:hafs-text.json'),
  ('hafs-26-26', 'hafs', 26, 26, 'قَالَ رَبُّكُمْ وَرَبُّ ءَابَآئِكُمُ ٱلْأَوَّلِينَ', 'قال ربكم ورب ءابائكم الأولين', NULL, 368, 'local:hafs-text.json'),
  ('hafs-26-27', 'hafs', 26, 27, 'قَالَ إِنَّ رَسُولَكُمُ ٱلَّذِىٓ أُرْسِلَ إِلَيْكُمْ لَمَجْنُونٌۭ', 'قال إن رسولكم الذى أرسل إليكم لمجنون', NULL, 368, 'local:hafs-text.json'),
  ('hafs-26-28', 'hafs', 26, 28, 'قَالَ رَبُّ ٱلْمَشْرِقِ وَٱلْمَغْرِبِ وَمَا بَيْنَهُمَآ ۖ إِن كُنتُمْ تَعْقِلُونَ', 'قال رب المشرق والمغرب وما بينهما  إن كنتم تعقلون', NULL, 368, 'local:hafs-text.json'),
  ('hafs-26-29', 'hafs', 26, 29, 'قَالَ لَئِنِ ٱتَّخَذْتَ إِلَٰهًا غَيْرِى لَأَجْعَلَنَّكَ مِنَ ٱلْمَسْجُونِينَ', 'قال لئن اتخذت إلها غيرى لأجعلنك من المسجونين', NULL, 368, 'local:hafs-text.json'),
  ('hafs-26-30', 'hafs', 26, 30, 'قَالَ أَوَلَوْ جِئْتُكَ بِشَىْءٍۢ مُّبِينٍۢ', 'قال أولو جئتك بشىء مبين', NULL, 368, 'local:hafs-text.json'),
  ('hafs-26-31', 'hafs', 26, 31, 'قَالَ فَأْتِ بِهِۦٓ إِن كُنتَ مِنَ ٱلصَّٰدِقِينَ', 'قال فأت به إن كنت من الصدقين', NULL, 368, 'local:hafs-text.json'),
  ('hafs-26-32', 'hafs', 26, 32, 'فَأَلْقَىٰ عَصَاهُ فَإِذَا هِىَ ثُعْبَانٌۭ مُّبِينٌۭ', 'فألقى عصاه فإذا هى ثعبان مبين', NULL, 368, 'local:hafs-text.json'),
  ('hafs-26-33', 'hafs', 26, 33, 'وَنَزَعَ يَدَهُۥ فَإِذَا هِىَ بَيْضَآءُ لِلنَّٰظِرِينَ', 'ونزع يده فإذا هى بيضاء للنظرين', NULL, 368, 'local:hafs-text.json'),
  ('hafs-26-34', 'hafs', 26, 34, 'قَالَ لِلْمَلَإِ حَوْلَهُۥٓ إِنَّ هَٰذَا لَسَٰحِرٌ عَلِيمٌۭ', 'قال للملإ حوله إن هذا لسحر عليم', NULL, 368, 'local:hafs-text.json'),
  ('hafs-26-35', 'hafs', 26, 35, 'يُرِيدُ أَن يُخْرِجَكُم مِّنْ أَرْضِكُم بِسِحْرِهِۦ فَمَاذَا تَأْمُرُونَ', 'يريد أن يخرجكم من أرضكم بسحره فماذا تأمرون', NULL, 368, 'local:hafs-text.json'),
  ('hafs-26-36', 'hafs', 26, 36, 'قَالُوٓا۟ أَرْجِهْ وَأَخَاهُ وَٱبْعَثْ فِى ٱلْمَدَآئِنِ حَٰشِرِينَ', 'قالوا أرجه وأخاه وابعث فى المدائن حشرين', NULL, 368, 'local:hafs-text.json'),
  ('hafs-26-37', 'hafs', 26, 37, 'يَأْتُوكَ بِكُلِّ سَحَّارٍ عَلِيمٍۢ', 'يأتوك بكل سحار عليم', NULL, 368, 'local:hafs-text.json'),
  ('hafs-26-38', 'hafs', 26, 38, 'فَجُمِعَ ٱلسَّحَرَةُ لِمِيقَٰتِ يَوْمٍۢ مَّعْلُومٍۢ', 'فجمع السحرة لميقت يوم معلوم', NULL, 368, 'local:hafs-text.json'),
  ('hafs-26-39', 'hafs', 26, 39, 'وَقِيلَ لِلنَّاسِ هَلْ أَنتُم مُّجْتَمِعُونَ', 'وقيل للناس هل أنتم مجتمعون', NULL, 368, 'local:hafs-text.json'),
  ('hafs-26-40', 'hafs', 26, 40, 'لَعَلَّنَا نَتَّبِعُ ٱلسَّحَرَةَ إِن كَانُوا۟ هُمُ ٱلْغَٰلِبِينَ', 'لعلنا نتبع السحرة إن كانوا هم الغلبين', NULL, 369, 'local:hafs-text.json'),
  ('hafs-26-41', 'hafs', 26, 41, 'فَلَمَّا جَآءَ ٱلسَّحَرَةُ قَالُوا۟ لِفِرْعَوْنَ أَئِنَّ لَنَا لَأَجْرًا إِن كُنَّا نَحْنُ ٱلْغَٰلِبِينَ', 'فلما جاء السحرة قالوا لفرعون أئن لنا لأجرا إن كنا نحن الغلبين', NULL, 369, 'local:hafs-text.json'),
  ('hafs-26-42', 'hafs', 26, 42, 'قَالَ نَعَمْ وَإِنَّكُمْ إِذًۭا لَّمِنَ ٱلْمُقَرَّبِينَ', 'قال نعم وإنكم إذا لمن المقربين', NULL, 369, 'local:hafs-text.json'),
  ('hafs-26-43', 'hafs', 26, 43, 'قَالَ لَهُم مُّوسَىٰٓ أَلْقُوا۟ مَآ أَنتُم مُّلْقُونَ', 'قال لهم موسى ألقوا ما أنتم ملقون', NULL, 369, 'local:hafs-text.json'),
  ('hafs-26-44', 'hafs', 26, 44, 'فَأَلْقَوْا۟ حِبَالَهُمْ وَعِصِيَّهُمْ وَقَالُوا۟ بِعِزَّةِ فِرْعَوْنَ إِنَّا لَنَحْنُ ٱلْغَٰلِبُونَ', 'فألقوا حبالهم وعصيهم وقالوا بعزة فرعون إنا لنحن الغلبون', NULL, 369, 'local:hafs-text.json'),
  ('hafs-26-45', 'hafs', 26, 45, 'فَأَلْقَىٰ مُوسَىٰ عَصَاهُ فَإِذَا هِىَ تَلْقَفُ مَا يَأْفِكُونَ', 'فألقى موسى عصاه فإذا هى تلقف ما يأفكون', NULL, 369, 'local:hafs-text.json'),
  ('hafs-26-46', 'hafs', 26, 46, 'فَأُلْقِىَ ٱلسَّحَرَةُ سَٰجِدِينَ', 'فألقى السحرة سجدين', NULL, 369, 'local:hafs-text.json'),
  ('hafs-26-47', 'hafs', 26, 47, 'قَالُوٓا۟ ءَامَنَّا بِرَبِّ ٱلْعَٰلَمِينَ', 'قالوا ءامنا برب العلمين', NULL, 369, 'local:hafs-text.json'),
  ('hafs-26-48', 'hafs', 26, 48, 'رَبِّ مُوسَىٰ وَهَٰرُونَ', 'رب موسى وهرون', NULL, 369, 'local:hafs-text.json'),
  ('hafs-26-49', 'hafs', 26, 49, 'قَالَ ءَامَنتُمْ لَهُۥ قَبْلَ أَنْ ءَاذَنَ لَكُمْ ۖ إِنَّهُۥ لَكَبِيرُكُمُ ٱلَّذِى عَلَّمَكُمُ ٱلسِّحْرَ فَلَسَوْفَ تَعْلَمُونَ ۚ لَأُقَطِّعَنَّ أَيْدِيَكُمْ وَأَرْجُلَكُم مِّنْ خِلَٰفٍۢ وَلَأُصَلِّبَنَّكُمْ أَجْمَعِينَ', 'قال ءامنتم له قبل أن ءاذن لكم  إنه لكبيركم الذى علمكم السحر فلسوف تعلمون  لأقطعن أيديكم وأرجلكم من خلف ولأصلبنكم أجمعين', NULL, 369, 'local:hafs-text.json'),
  ('hafs-26-50', 'hafs', 26, 50, 'قَالُوا۟ لَا ضَيْرَ ۖ إِنَّآ إِلَىٰ رَبِّنَا مُنقَلِبُونَ', 'قالوا لا ضير  إنا إلى ربنا منقلبون', NULL, 369, 'local:hafs-text.json'),
  ('hafs-26-51', 'hafs', 26, 51, 'إِنَّا نَطْمَعُ أَن يَغْفِرَ لَنَا رَبُّنَا خَطَٰيَٰنَآ أَن كُنَّآ أَوَّلَ ٱلْمُؤْمِنِينَ', 'إنا نطمع أن يغفر لنا ربنا خطينا أن كنا أول المؤمنين', NULL, 369, 'local:hafs-text.json'),
  ('hafs-26-52', 'hafs', 26, 52, '۞ وَأَوْحَيْنَآ إِلَىٰ مُوسَىٰٓ أَنْ أَسْرِ بِعِبَادِىٓ إِنَّكُم مُّتَّبَعُونَ', 'وأوحينا إلى موسى أن أسر بعبادى إنكم متبعون', NULL, 369, 'local:hafs-text.json'),
  ('hafs-26-53', 'hafs', 26, 53, 'فَأَرْسَلَ فِرْعَوْنُ فِى ٱلْمَدَآئِنِ حَٰشِرِينَ', 'فأرسل فرعون فى المدائن حشرين', NULL, 369, 'local:hafs-text.json'),
  ('hafs-26-54', 'hafs', 26, 54, 'إِنَّ هَٰٓؤُلَآءِ لَشِرْذِمَةٌۭ قَلِيلُونَ', 'إن هؤلاء لشرذمة قليلون', NULL, 369, 'local:hafs-text.json'),
  ('hafs-26-55', 'hafs', 26, 55, 'وَإِنَّهُمْ لَنَا لَغَآئِظُونَ', 'وإنهم لنا لغائظون', NULL, 369, 'local:hafs-text.json'),
  ('hafs-26-56', 'hafs', 26, 56, 'وَإِنَّا لَجَمِيعٌ حَٰذِرُونَ', 'وإنا لجميع حذرون', NULL, 369, 'local:hafs-text.json'),
  ('hafs-26-57', 'hafs', 26, 57, 'فَأَخْرَجْنَٰهُم مِّن جَنَّٰتٍۢ وَعُيُونٍۢ', 'فأخرجنهم من جنت وعيون', NULL, 369, 'local:hafs-text.json'),
  ('hafs-26-58', 'hafs', 26, 58, 'وَكُنُوزٍۢ وَمَقَامٍۢ كَرِيمٍۢ', 'وكنوز ومقام كريم', NULL, 369, 'local:hafs-text.json'),
  ('hafs-26-59', 'hafs', 26, 59, 'كَذَٰلِكَ وَأَوْرَثْنَٰهَا بَنِىٓ إِسْرَٰٓءِيلَ', 'كذلك وأورثنها بنى إسرءيل', NULL, 369, 'local:hafs-text.json'),
  ('hafs-26-60', 'hafs', 26, 60, 'فَأَتْبَعُوهُم مُّشْرِقِينَ', 'فأتبعوهم مشرقين', NULL, 369, 'local:hafs-text.json'),
  ('hafs-26-61', 'hafs', 26, 61, 'فَلَمَّا تَرَٰٓءَا ٱلْجَمْعَانِ قَالَ أَصْحَٰبُ مُوسَىٰٓ إِنَّا لَمُدْرَكُونَ', 'فلما ترءا الجمعان قال أصحب موسى إنا لمدركون', NULL, 370, 'local:hafs-text.json'),
  ('hafs-26-62', 'hafs', 26, 62, 'قَالَ كَلَّآ ۖ إِنَّ مَعِىَ رَبِّى سَيَهْدِينِ', 'قال كلا  إن معى ربى سيهدين', NULL, 370, 'local:hafs-text.json'),
  ('hafs-26-63', 'hafs', 26, 63, 'فَأَوْحَيْنَآ إِلَىٰ مُوسَىٰٓ أَنِ ٱضْرِب بِّعَصَاكَ ٱلْبَحْرَ ۖ فَٱنفَلَقَ فَكَانَ كُلُّ فِرْقٍۢ كَٱلطَّوْدِ ٱلْعَظِيمِ', 'فأوحينا إلى موسى أن اضرب بعصاك البحر  فانفلق فكان كل فرق كالطود العظيم', NULL, 370, 'local:hafs-text.json'),
  ('hafs-26-64', 'hafs', 26, 64, 'وَأَزْلَفْنَا ثَمَّ ٱلْءَاخَرِينَ', 'وأزلفنا ثم الءاخرين', NULL, 370, 'local:hafs-text.json'),
  ('hafs-26-65', 'hafs', 26, 65, 'وَأَنجَيْنَا مُوسَىٰ وَمَن مَّعَهُۥٓ أَجْمَعِينَ', 'وأنجينا موسى ومن معه أجمعين', NULL, 370, 'local:hafs-text.json'),
  ('hafs-26-66', 'hafs', 26, 66, 'ثُمَّ أَغْرَقْنَا ٱلْءَاخَرِينَ', 'ثم أغرقنا الءاخرين', NULL, 370, 'local:hafs-text.json'),
  ('hafs-26-67', 'hafs', 26, 67, 'إِنَّ فِى ذَٰلِكَ لَءَايَةًۭ ۖ وَمَا كَانَ أَكْثَرُهُم مُّؤْمِنِينَ', 'إن فى ذلك لءاية  وما كان أكثرهم مؤمنين', NULL, 370, 'local:hafs-text.json'),
  ('hafs-26-68', 'hafs', 26, 68, 'وَإِنَّ رَبَّكَ لَهُوَ ٱلْعَزِيزُ ٱلرَّحِيمُ', 'وإن ربك لهو العزيز الرحيم', NULL, 370, 'local:hafs-text.json'),
  ('hafs-26-69', 'hafs', 26, 69, 'وَٱتْلُ عَلَيْهِمْ نَبَأَ إِبْرَٰهِيمَ', 'واتل عليهم نبأ إبرهيم', NULL, 370, 'local:hafs-text.json'),
  ('hafs-26-70', 'hafs', 26, 70, 'إِذْ قَالَ لِأَبِيهِ وَقَوْمِهِۦ مَا تَعْبُدُونَ', 'إذ قال لأبيه وقومه ما تعبدون', NULL, 370, 'local:hafs-text.json'),
  ('hafs-26-71', 'hafs', 26, 71, 'قَالُوا۟ نَعْبُدُ أَصْنَامًۭا فَنَظَلُّ لَهَا عَٰكِفِينَ', 'قالوا نعبد أصناما فنظل لها عكفين', NULL, 370, 'local:hafs-text.json'),
  ('hafs-26-72', 'hafs', 26, 72, 'قَالَ هَلْ يَسْمَعُونَكُمْ إِذْ تَدْعُونَ', 'قال هل يسمعونكم إذ تدعون', NULL, 370, 'local:hafs-text.json'),
  ('hafs-26-73', 'hafs', 26, 73, 'أَوْ يَنفَعُونَكُمْ أَوْ يَضُرُّونَ', 'أو ينفعونكم أو يضرون', NULL, 370, 'local:hafs-text.json'),
  ('hafs-26-74', 'hafs', 26, 74, 'قَالُوا۟ بَلْ وَجَدْنَآ ءَابَآءَنَا كَذَٰلِكَ يَفْعَلُونَ', 'قالوا بل وجدنا ءاباءنا كذلك يفعلون', NULL, 370, 'local:hafs-text.json'),
  ('hafs-26-75', 'hafs', 26, 75, 'قَالَ أَفَرَءَيْتُم مَّا كُنتُمْ تَعْبُدُونَ', 'قال أفرءيتم ما كنتم تعبدون', NULL, 370, 'local:hafs-text.json'),
  ('hafs-26-76', 'hafs', 26, 76, 'أَنتُمْ وَءَابَآؤُكُمُ ٱلْأَقْدَمُونَ', 'أنتم وءاباؤكم الأقدمون', NULL, 370, 'local:hafs-text.json'),
  ('hafs-26-77', 'hafs', 26, 77, 'فَإِنَّهُمْ عَدُوٌّۭ لِّىٓ إِلَّا رَبَّ ٱلْعَٰلَمِينَ', 'فإنهم عدو لى إلا رب العلمين', NULL, 370, 'local:hafs-text.json'),
  ('hafs-26-78', 'hafs', 26, 78, 'ٱلَّذِى خَلَقَنِى فَهُوَ يَهْدِينِ', 'الذى خلقنى فهو يهدين', NULL, 370, 'local:hafs-text.json'),
  ('hafs-26-79', 'hafs', 26, 79, 'وَٱلَّذِى هُوَ يُطْعِمُنِى وَيَسْقِينِ', 'والذى هو يطعمنى ويسقين', NULL, 370, 'local:hafs-text.json'),
  ('hafs-26-80', 'hafs', 26, 80, 'وَإِذَا مَرِضْتُ فَهُوَ يَشْفِينِ', 'وإذا مرضت فهو يشفين', NULL, 370, 'local:hafs-text.json'),
  ('hafs-26-81', 'hafs', 26, 81, 'وَٱلَّذِى يُمِيتُنِى ثُمَّ يُحْيِينِ', 'والذى يميتنى ثم يحيين', NULL, 370, 'local:hafs-text.json'),
  ('hafs-26-82', 'hafs', 26, 82, 'وَٱلَّذِىٓ أَطْمَعُ أَن يَغْفِرَ لِى خَطِيٓـَٔتِى يَوْمَ ٱلدِّينِ', 'والذى أطمع أن يغفر لى خطيتى يوم الدين', NULL, 370, 'local:hafs-text.json'),
  ('hafs-26-83', 'hafs', 26, 83, 'رَبِّ هَبْ لِى حُكْمًۭا وَأَلْحِقْنِى بِٱلصَّٰلِحِينَ', 'رب هب لى حكما وألحقنى بالصلحين', NULL, 370, 'local:hafs-text.json'),
  ('hafs-26-84', 'hafs', 26, 84, 'وَٱجْعَل لِّى لِسَانَ صِدْقٍۢ فِى ٱلْءَاخِرِينَ', 'واجعل لى لسان صدق فى الءاخرين', NULL, 371, 'local:hafs-text.json'),
  ('hafs-26-85', 'hafs', 26, 85, 'وَٱجْعَلْنِى مِن وَرَثَةِ جَنَّةِ ٱلنَّعِيمِ', 'واجعلنى من ورثة جنة النعيم', NULL, 371, 'local:hafs-text.json'),
  ('hafs-26-86', 'hafs', 26, 86, 'وَٱغْفِرْ لِأَبِىٓ إِنَّهُۥ كَانَ مِنَ ٱلضَّآلِّينَ', 'واغفر لأبى إنه كان من الضالين', NULL, 371, 'local:hafs-text.json'),
  ('hafs-26-87', 'hafs', 26, 87, 'وَلَا تُخْزِنِى يَوْمَ يُبْعَثُونَ', 'ولا تخزنى يوم يبعثون', NULL, 371, 'local:hafs-text.json'),
  ('hafs-26-88', 'hafs', 26, 88, 'يَوْمَ لَا يَنفَعُ مَالٌۭ وَلَا بَنُونَ', 'يوم لا ينفع مال ولا بنون', NULL, 371, 'local:hafs-text.json'),
  ('hafs-26-89', 'hafs', 26, 89, 'إِلَّا مَنْ أَتَى ٱللَّهَ بِقَلْبٍۢ سَلِيمٍۢ', 'إلا من أتى الله بقلب سليم', NULL, 371, 'local:hafs-text.json'),
  ('hafs-26-90', 'hafs', 26, 90, 'وَأُزْلِفَتِ ٱلْجَنَّةُ لِلْمُتَّقِينَ', 'وأزلفت الجنة للمتقين', NULL, 371, 'local:hafs-text.json'),
  ('hafs-26-91', 'hafs', 26, 91, 'وَبُرِّزَتِ ٱلْجَحِيمُ لِلْغَاوِينَ', 'وبرزت الجحيم للغاوين', NULL, 371, 'local:hafs-text.json'),
  ('hafs-26-92', 'hafs', 26, 92, 'وَقِيلَ لَهُمْ أَيْنَ مَا كُنتُمْ تَعْبُدُونَ', 'وقيل لهم أين ما كنتم تعبدون', NULL, 371, 'local:hafs-text.json'),
  ('hafs-26-93', 'hafs', 26, 93, 'مِن دُونِ ٱللَّهِ هَلْ يَنصُرُونَكُمْ أَوْ يَنتَصِرُونَ', 'من دون الله هل ينصرونكم أو ينتصرون', NULL, 371, 'local:hafs-text.json'),
  ('hafs-26-94', 'hafs', 26, 94, 'فَكُبْكِبُوا۟ فِيهَا هُمْ وَٱلْغَاوُۥنَ', 'فكبكبوا فيها هم والغاون', NULL, 371, 'local:hafs-text.json'),
  ('hafs-26-95', 'hafs', 26, 95, 'وَجُنُودُ إِبْلِيسَ أَجْمَعُونَ', 'وجنود إبليس أجمعون', NULL, 371, 'local:hafs-text.json'),
  ('hafs-26-96', 'hafs', 26, 96, 'قَالُوا۟ وَهُمْ فِيهَا يَخْتَصِمُونَ', 'قالوا وهم فيها يختصمون', NULL, 371, 'local:hafs-text.json'),
  ('hafs-26-97', 'hafs', 26, 97, 'تَٱللَّهِ إِن كُنَّا لَفِى ضَلَٰلٍۢ مُّبِينٍ', 'تالله إن كنا لفى ضلل مبين', NULL, 371, 'local:hafs-text.json'),
  ('hafs-26-98', 'hafs', 26, 98, 'إِذْ نُسَوِّيكُم بِرَبِّ ٱلْعَٰلَمِينَ', 'إذ نسويكم برب العلمين', NULL, 371, 'local:hafs-text.json'),
  ('hafs-26-99', 'hafs', 26, 99, 'وَمَآ أَضَلَّنَآ إِلَّا ٱلْمُجْرِمُونَ', 'وما أضلنا إلا المجرمون', NULL, 371, 'local:hafs-text.json'),
  ('hafs-26-100', 'hafs', 26, 100, 'فَمَا لَنَا مِن شَٰفِعِينَ', 'فما لنا من شفعين', NULL, 371, 'local:hafs-text.json'),
  ('hafs-26-101', 'hafs', 26, 101, 'وَلَا صَدِيقٍ حَمِيمٍۢ', 'ولا صديق حميم', NULL, 371, 'local:hafs-text.json'),
  ('hafs-26-102', 'hafs', 26, 102, 'فَلَوْ أَنَّ لَنَا كَرَّةًۭ فَنَكُونَ مِنَ ٱلْمُؤْمِنِينَ', 'فلو أن لنا كرة فنكون من المؤمنين', NULL, 371, 'local:hafs-text.json'),
  ('hafs-26-103', 'hafs', 26, 103, 'إِنَّ فِى ذَٰلِكَ لَءَايَةًۭ ۖ وَمَا كَانَ أَكْثَرُهُم مُّؤْمِنِينَ', 'إن فى ذلك لءاية  وما كان أكثرهم مؤمنين', NULL, 371, 'local:hafs-text.json'),
  ('hafs-26-104', 'hafs', 26, 104, 'وَإِنَّ رَبَّكَ لَهُوَ ٱلْعَزِيزُ ٱلرَّحِيمُ', 'وإن ربك لهو العزيز الرحيم', NULL, 371, 'local:hafs-text.json'),
  ('hafs-26-105', 'hafs', 26, 105, 'كَذَّبَتْ قَوْمُ نُوحٍ ٱلْمُرْسَلِينَ', 'كذبت قوم نوح المرسلين', NULL, 371, 'local:hafs-text.json'),
  ('hafs-26-106', 'hafs', 26, 106, 'إِذْ قَالَ لَهُمْ أَخُوهُمْ نُوحٌ أَلَا تَتَّقُونَ', 'إذ قال لهم أخوهم نوح ألا تتقون', NULL, 371, 'local:hafs-text.json'),
  ('hafs-26-107', 'hafs', 26, 107, 'إِنِّى لَكُمْ رَسُولٌ أَمِينٌۭ', 'إنى لكم رسول أمين', NULL, 371, 'local:hafs-text.json'),
  ('hafs-26-108', 'hafs', 26, 108, 'فَٱتَّقُوا۟ ٱللَّهَ وَأَطِيعُونِ', 'فاتقوا الله وأطيعون', NULL, 371, 'local:hafs-text.json'),
  ('hafs-26-109', 'hafs', 26, 109, 'وَمَآ أَسْـَٔلُكُمْ عَلَيْهِ مِنْ أَجْرٍ ۖ إِنْ أَجْرِىَ إِلَّا عَلَىٰ رَبِّ ٱلْعَٰلَمِينَ', 'وما أسلكم عليه من أجر  إن أجرى إلا على رب العلمين', NULL, 371, 'local:hafs-text.json'),
  ('hafs-26-110', 'hafs', 26, 110, 'فَٱتَّقُوا۟ ٱللَّهَ وَأَطِيعُونِ', 'فاتقوا الله وأطيعون', NULL, 371, 'local:hafs-text.json'),
  ('hafs-26-111', 'hafs', 26, 111, '۞ قَالُوٓا۟ أَنُؤْمِنُ لَكَ وَٱتَّبَعَكَ ٱلْأَرْذَلُونَ', 'قالوا أنؤمن لك واتبعك الأرذلون', NULL, 371, 'local:hafs-text.json'),
  ('hafs-26-112', 'hafs', 26, 112, 'قَالَ وَمَا عِلْمِى بِمَا كَانُوا۟ يَعْمَلُونَ', 'قال وما علمى بما كانوا يعملون', NULL, 372, 'local:hafs-text.json'),
  ('hafs-26-113', 'hafs', 26, 113, 'إِنْ حِسَابُهُمْ إِلَّا عَلَىٰ رَبِّى ۖ لَوْ تَشْعُرُونَ', 'إن حسابهم إلا على ربى  لو تشعرون', NULL, 372, 'local:hafs-text.json'),
  ('hafs-26-114', 'hafs', 26, 114, 'وَمَآ أَنَا۠ بِطَارِدِ ٱلْمُؤْمِنِينَ', 'وما أنا بطارد المؤمنين', NULL, 372, 'local:hafs-text.json'),
  ('hafs-26-115', 'hafs', 26, 115, 'إِنْ أَنَا۠ إِلَّا نَذِيرٌۭ مُّبِينٌۭ', 'إن أنا إلا نذير مبين', NULL, 372, 'local:hafs-text.json'),
  ('hafs-26-116', 'hafs', 26, 116, 'قَالُوا۟ لَئِن لَّمْ تَنتَهِ يَٰنُوحُ لَتَكُونَنَّ مِنَ ٱلْمَرْجُومِينَ', 'قالوا لئن لم تنته ينوح لتكونن من المرجومين', NULL, 372, 'local:hafs-text.json'),
  ('hafs-26-117', 'hafs', 26, 117, 'قَالَ رَبِّ إِنَّ قَوْمِى كَذَّبُونِ', 'قال رب إن قومى كذبون', NULL, 372, 'local:hafs-text.json'),
  ('hafs-26-118', 'hafs', 26, 118, 'فَٱفْتَحْ بَيْنِى وَبَيْنَهُمْ فَتْحًۭا وَنَجِّنِى وَمَن مَّعِىَ مِنَ ٱلْمُؤْمِنِينَ', 'فافتح بينى وبينهم فتحا ونجنى ومن معى من المؤمنين', NULL, 372, 'local:hafs-text.json'),
  ('hafs-26-119', 'hafs', 26, 119, 'فَأَنجَيْنَٰهُ وَمَن مَّعَهُۥ فِى ٱلْفُلْكِ ٱلْمَشْحُونِ', 'فأنجينه ومن معه فى الفلك المشحون', NULL, 372, 'local:hafs-text.json'),
  ('hafs-26-120', 'hafs', 26, 120, 'ثُمَّ أَغْرَقْنَا بَعْدُ ٱلْبَاقِينَ', 'ثم أغرقنا بعد الباقين', NULL, 372, 'local:hafs-text.json'),
  ('hafs-26-121', 'hafs', 26, 121, 'إِنَّ فِى ذَٰلِكَ لَءَايَةًۭ ۖ وَمَا كَانَ أَكْثَرُهُم مُّؤْمِنِينَ', 'إن فى ذلك لءاية  وما كان أكثرهم مؤمنين', NULL, 372, 'local:hafs-text.json'),
  ('hafs-26-122', 'hafs', 26, 122, 'وَإِنَّ رَبَّكَ لَهُوَ ٱلْعَزِيزُ ٱلرَّحِيمُ', 'وإن ربك لهو العزيز الرحيم', NULL, 372, 'local:hafs-text.json'),
  ('hafs-26-123', 'hafs', 26, 123, 'كَذَّبَتْ عَادٌ ٱلْمُرْسَلِينَ', 'كذبت عاد المرسلين', NULL, 372, 'local:hafs-text.json'),
  ('hafs-26-124', 'hafs', 26, 124, 'إِذْ قَالَ لَهُمْ أَخُوهُمْ هُودٌ أَلَا تَتَّقُونَ', 'إذ قال لهم أخوهم هود ألا تتقون', NULL, 372, 'local:hafs-text.json'),
