  ('hafs-26-189', 'hafs', 26, 189, 'فَكَذَّبُوهُ فَأَخَذَهُمْ عَذَابُ يَوْمِ ٱلظُّلَّةِ ۚ إِنَّهُۥ كَانَ عَذَابَ يَوْمٍ عَظِيمٍ', 'فكذبوه فأخذهم عذاب يوم الظلة  إنه كان عذاب يوم عظيم', NULL, 375, 'local:hafs-text.json'),
  ('hafs-26-190', 'hafs', 26, 190, 'إِنَّ فِى ذَٰلِكَ لَءَايَةًۭ ۖ وَمَا كَانَ أَكْثَرُهُم مُّؤْمِنِينَ', 'إن فى ذلك لءاية  وما كان أكثرهم مؤمنين', NULL, 375, 'local:hafs-text.json'),
  ('hafs-26-191', 'hafs', 26, 191, 'وَإِنَّ رَبَّكَ لَهُوَ ٱلْعَزِيزُ ٱلرَّحِيمُ', 'وإن ربك لهو العزيز الرحيم', NULL, 375, 'local:hafs-text.json'),
  ('hafs-26-192', 'hafs', 26, 192, 'وَإِنَّهُۥ لَتَنزِيلُ رَبِّ ٱلْعَٰلَمِينَ', 'وإنه لتنزيل رب العلمين', NULL, 375, 'local:hafs-text.json'),
  ('hafs-26-193', 'hafs', 26, 193, 'نَزَلَ بِهِ ٱلرُّوحُ ٱلْأَمِينُ', 'نزل به الروح الأمين', NULL, 375, 'local:hafs-text.json'),
  ('hafs-26-194', 'hafs', 26, 194, 'عَلَىٰ قَلْبِكَ لِتَكُونَ مِنَ ٱلْمُنذِرِينَ', 'على قلبك لتكون من المنذرين', NULL, 375, 'local:hafs-text.json'),
  ('hafs-26-195', 'hafs', 26, 195, 'بِلِسَانٍ عَرَبِىٍّۢ مُّبِينٍۢ', 'بلسان عربى مبين', NULL, 375, 'local:hafs-text.json'),
  ('hafs-26-196', 'hafs', 26, 196, 'وَإِنَّهُۥ لَفِى زُبُرِ ٱلْأَوَّلِينَ', 'وإنه لفى زبر الأولين', NULL, 375, 'local:hafs-text.json'),
  ('hafs-26-197', 'hafs', 26, 197, 'أَوَلَمْ يَكُن لَّهُمْ ءَايَةً أَن يَعْلَمَهُۥ عُلَمَٰٓؤُا۟ بَنِىٓ إِسْرَٰٓءِيلَ', 'أولم يكن لهم ءاية أن يعلمه علمؤا بنى إسرءيل', NULL, 375, 'local:hafs-text.json'),
  ('hafs-26-198', 'hafs', 26, 198, 'وَلَوْ نَزَّلْنَٰهُ عَلَىٰ بَعْضِ ٱلْأَعْجَمِينَ', 'ولو نزلنه على بعض الأعجمين', NULL, 375, 'local:hafs-text.json'),
  ('hafs-26-199', 'hafs', 26, 199, 'فَقَرَأَهُۥ عَلَيْهِم مَّا كَانُوا۟ بِهِۦ مُؤْمِنِينَ', 'فقرأه عليهم ما كانوا به مؤمنين', NULL, 375, 'local:hafs-text.json'),
  ('hafs-26-200', 'hafs', 26, 200, 'كَذَٰلِكَ سَلَكْنَٰهُ فِى قُلُوبِ ٱلْمُجْرِمِينَ', 'كذلك سلكنه فى قلوب المجرمين', NULL, 375, 'local:hafs-text.json'),
  ('hafs-26-201', 'hafs', 26, 201, 'لَا يُؤْمِنُونَ بِهِۦ حَتَّىٰ يَرَوُا۟ ٱلْعَذَابَ ٱلْأَلِيمَ', 'لا يؤمنون به حتى يروا العذاب الأليم', NULL, 375, 'local:hafs-text.json'),
  ('hafs-26-202', 'hafs', 26, 202, 'فَيَأْتِيَهُم بَغْتَةًۭ وَهُمْ لَا يَشْعُرُونَ', 'فيأتيهم بغتة وهم لا يشعرون', NULL, 375, 'local:hafs-text.json'),
  ('hafs-26-203', 'hafs', 26, 203, 'فَيَقُولُوا۟ هَلْ نَحْنُ مُنظَرُونَ', 'فيقولوا هل نحن منظرون', NULL, 375, 'local:hafs-text.json'),
  ('hafs-26-204', 'hafs', 26, 204, 'أَفَبِعَذَابِنَا يَسْتَعْجِلُونَ', 'أفبعذابنا يستعجلون', NULL, 375, 'local:hafs-text.json'),
  ('hafs-26-205', 'hafs', 26, 205, 'أَفَرَءَيْتَ إِن مَّتَّعْنَٰهُمْ سِنِينَ', 'أفرءيت إن متعنهم سنين', NULL, 375, 'local:hafs-text.json'),
  ('hafs-26-206', 'hafs', 26, 206, 'ثُمَّ جَآءَهُم مَّا كَانُوا۟ يُوعَدُونَ', 'ثم جاءهم ما كانوا يوعدون', NULL, 375, 'local:hafs-text.json'),
  ('hafs-26-207', 'hafs', 26, 207, 'مَآ أَغْنَىٰ عَنْهُم مَّا كَانُوا۟ يُمَتَّعُونَ', 'ما أغنى عنهم ما كانوا يمتعون', NULL, 376, 'local:hafs-text.json'),
  ('hafs-26-208', 'hafs', 26, 208, 'وَمَآ أَهْلَكْنَا مِن قَرْيَةٍ إِلَّا لَهَا مُنذِرُونَ', 'وما أهلكنا من قرية إلا لها منذرون', NULL, 376, 'local:hafs-text.json'),
  ('hafs-26-209', 'hafs', 26, 209, 'ذِكْرَىٰ وَمَا كُنَّا ظَٰلِمِينَ', 'ذكرى وما كنا ظلمين', NULL, 376, 'local:hafs-text.json'),
  ('hafs-26-210', 'hafs', 26, 210, 'وَمَا تَنَزَّلَتْ بِهِ ٱلشَّيَٰطِينُ', 'وما تنزلت به الشيطين', NULL, 376, 'local:hafs-text.json'),
  ('hafs-26-211', 'hafs', 26, 211, 'وَمَا يَنۢبَغِى لَهُمْ وَمَا يَسْتَطِيعُونَ', 'وما ينبغى لهم وما يستطيعون', NULL, 376, 'local:hafs-text.json'),
  ('hafs-26-212', 'hafs', 26, 212, 'إِنَّهُمْ عَنِ ٱلسَّمْعِ لَمَعْزُولُونَ', 'إنهم عن السمع لمعزولون', NULL, 376, 'local:hafs-text.json'),
  ('hafs-26-213', 'hafs', 26, 213, 'فَلَا تَدْعُ مَعَ ٱللَّهِ إِلَٰهًا ءَاخَرَ فَتَكُونَ مِنَ ٱلْمُعَذَّبِينَ', 'فلا تدع مع الله إلها ءاخر فتكون من المعذبين', NULL, 376, 'local:hafs-text.json'),
  ('hafs-26-214', 'hafs', 26, 214, 'وَأَنذِرْ عَشِيرَتَكَ ٱلْأَقْرَبِينَ', 'وأنذر عشيرتك الأقربين', NULL, 376, 'local:hafs-text.json'),
  ('hafs-26-215', 'hafs', 26, 215, 'وَٱخْفِضْ جَنَاحَكَ لِمَنِ ٱتَّبَعَكَ مِنَ ٱلْمُؤْمِنِينَ', 'واخفض جناحك لمن اتبعك من المؤمنين', NULL, 376, 'local:hafs-text.json'),
  ('hafs-26-216', 'hafs', 26, 216, 'فَإِنْ عَصَوْكَ فَقُلْ إِنِّى بَرِىٓءٌۭ مِّمَّا تَعْمَلُونَ', 'فإن عصوك فقل إنى برىء مما تعملون', NULL, 376, 'local:hafs-text.json'),
  ('hafs-26-217', 'hafs', 26, 217, 'وَتَوَكَّلْ عَلَى ٱلْعَزِيزِ ٱلرَّحِيمِ', 'وتوكل على العزيز الرحيم', NULL, 376, 'local:hafs-text.json'),
  ('hafs-26-218', 'hafs', 26, 218, 'ٱلَّذِى يَرَىٰكَ حِينَ تَقُومُ', 'الذى يرىك حين تقوم', NULL, 376, 'local:hafs-text.json'),
  ('hafs-26-219', 'hafs', 26, 219, 'وَتَقَلُّبَكَ فِى ٱلسَّٰجِدِينَ', 'وتقلبك فى السجدين', NULL, 376, 'local:hafs-text.json'),
  ('hafs-26-220', 'hafs', 26, 220, 'إِنَّهُۥ هُوَ ٱلسَّمِيعُ ٱلْعَلِيمُ', 'إنه هو السميع العليم', NULL, 376, 'local:hafs-text.json'),
  ('hafs-26-221', 'hafs', 26, 221, 'هَلْ أُنَبِّئُكُمْ عَلَىٰ مَن تَنَزَّلُ ٱلشَّيَٰطِينُ', 'هل أنبئكم على من تنزل الشيطين', NULL, 376, 'local:hafs-text.json'),
  ('hafs-26-222', 'hafs', 26, 222, 'تَنَزَّلُ عَلَىٰ كُلِّ أَفَّاكٍ أَثِيمٍۢ', 'تنزل على كل أفاك أثيم', NULL, 376, 'local:hafs-text.json'),
  ('hafs-26-223', 'hafs', 26, 223, 'يُلْقُونَ ٱلسَّمْعَ وَأَكْثَرُهُمْ كَٰذِبُونَ', 'يلقون السمع وأكثرهم كذبون', NULL, 376, 'local:hafs-text.json'),
  ('hafs-26-224', 'hafs', 26, 224, 'وَٱلشُّعَرَآءُ يَتَّبِعُهُمُ ٱلْغَاوُۥنَ', 'والشعراء يتبعهم الغاون', NULL, 376, 'local:hafs-text.json'),
  ('hafs-26-225', 'hafs', 26, 225, 'أَلَمْ تَرَ أَنَّهُمْ فِى كُلِّ وَادٍۢ يَهِيمُونَ', 'ألم تر أنهم فى كل واد يهيمون', NULL, 376, 'local:hafs-text.json'),
  ('hafs-26-226', 'hafs', 26, 226, 'وَأَنَّهُمْ يَقُولُونَ مَا لَا يَفْعَلُونَ', 'وأنهم يقولون ما لا يفعلون', NULL, 376, 'local:hafs-text.json'),
  ('hafs-26-227', 'hafs', 26, 227, 'إِلَّا ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ وَذَكَرُوا۟ ٱللَّهَ كَثِيرًۭا وَٱنتَصَرُوا۟ مِنۢ بَعْدِ مَا ظُلِمُوا۟ ۗ وَسَيَعْلَمُ ٱلَّذِينَ ظَلَمُوٓا۟ أَىَّ مُنقَلَبٍۢ يَنقَلِبُونَ', 'إلا الذين ءامنوا وعملوا الصلحت وذكروا الله كثيرا وانتصروا من بعد ما ظلموا  وسيعلم الذين ظلموا أى منقلب ينقلبون', NULL, 376, 'local:hafs-text.json'),
  ('hafs-27-1', 'hafs', 27, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ طسٓ ۚ تِلْكَ ءَايَٰتُ ٱلْقُرْءَانِ وَكِتَابٍۢ مُّبِينٍ', 'بسم الله الرحمن الرحيم طس  تلك ءايت القرءان وكتاب مبين', NULL, 377, 'local:hafs-text.json'),
  ('hafs-27-2', 'hafs', 27, 2, 'هُدًۭى وَبُشْرَىٰ لِلْمُؤْمِنِينَ', 'هدى وبشرى للمؤمنين', NULL, 377, 'local:hafs-text.json'),
  ('hafs-27-3', 'hafs', 27, 3, 'ٱلَّذِينَ يُقِيمُونَ ٱلصَّلَوٰةَ وَيُؤْتُونَ ٱلزَّكَوٰةَ وَهُم بِٱلْءَاخِرَةِ هُمْ يُوقِنُونَ', 'الذين يقيمون الصلوة ويؤتون الزكوة وهم بالءاخرة هم يوقنون', NULL, 377, 'local:hafs-text.json'),
  ('hafs-27-4', 'hafs', 27, 4, 'إِنَّ ٱلَّذِينَ لَا يُؤْمِنُونَ بِٱلْءَاخِرَةِ زَيَّنَّا لَهُمْ أَعْمَٰلَهُمْ فَهُمْ يَعْمَهُونَ', 'إن الذين لا يؤمنون بالءاخرة زينا لهم أعملهم فهم يعمهون', NULL, 377, 'local:hafs-text.json'),
  ('hafs-27-5', 'hafs', 27, 5, 'أُو۟لَٰٓئِكَ ٱلَّذِينَ لَهُمْ سُوٓءُ ٱلْعَذَابِ وَهُمْ فِى ٱلْءَاخِرَةِ هُمُ ٱلْأَخْسَرُونَ', 'أولئك الذين لهم سوء العذاب وهم فى الءاخرة هم الأخسرون', NULL, 377, 'local:hafs-text.json'),
  ('hafs-27-6', 'hafs', 27, 6, 'وَإِنَّكَ لَتُلَقَّى ٱلْقُرْءَانَ مِن لَّدُنْ حَكِيمٍ عَلِيمٍ', 'وإنك لتلقى القرءان من لدن حكيم عليم', NULL, 377, 'local:hafs-text.json'),
  ('hafs-27-7', 'hafs', 27, 7, 'إِذْ قَالَ مُوسَىٰ لِأَهْلِهِۦٓ إِنِّىٓ ءَانَسْتُ نَارًۭا سَـَٔاتِيكُم مِّنْهَا بِخَبَرٍ أَوْ ءَاتِيكُم بِشِهَابٍۢ قَبَسٍۢ لَّعَلَّكُمْ تَصْطَلُونَ', 'إذ قال موسى لأهله إنى ءانست نارا ساتيكم منها بخبر أو ءاتيكم بشهاب قبس لعلكم تصطلون', NULL, 377, 'local:hafs-text.json'),
  ('hafs-27-8', 'hafs', 27, 8, 'فَلَمَّا جَآءَهَا نُودِىَ أَنۢ بُورِكَ مَن فِى ٱلنَّارِ وَمَنْ حَوْلَهَا وَسُبْحَٰنَ ٱللَّهِ رَبِّ ٱلْعَٰلَمِينَ', 'فلما جاءها نودى أن بورك من فى النار ومن حولها وسبحن الله رب العلمين', NULL, 377, 'local:hafs-text.json'),
  ('hafs-27-9', 'hafs', 27, 9, 'يَٰمُوسَىٰٓ إِنَّهُۥٓ أَنَا ٱللَّهُ ٱلْعَزِيزُ ٱلْحَكِيمُ', 'يموسى إنه أنا الله العزيز الحكيم', NULL, 377, 'local:hafs-text.json'),
  ('hafs-27-10', 'hafs', 27, 10, 'وَأَلْقِ عَصَاكَ ۚ فَلَمَّا رَءَاهَا تَهْتَزُّ كَأَنَّهَا جَآنٌّۭ وَلَّىٰ مُدْبِرًۭا وَلَمْ يُعَقِّبْ ۚ يَٰمُوسَىٰ لَا تَخَفْ إِنِّى لَا يَخَافُ لَدَىَّ ٱلْمُرْسَلُونَ', 'وألق عصاك  فلما رءاها تهتز كأنها جان ولى مدبرا ولم يعقب  يموسى لا تخف إنى لا يخاف لدى المرسلون', NULL, 377, 'local:hafs-text.json'),
  ('hafs-27-11', 'hafs', 27, 11, 'إِلَّا مَن ظَلَمَ ثُمَّ بَدَّلَ حُسْنًۢا بَعْدَ سُوٓءٍۢ فَإِنِّى غَفُورٌۭ رَّحِيمٌۭ', 'إلا من ظلم ثم بدل حسنا بعد سوء فإنى غفور رحيم', NULL, 377, 'local:hafs-text.json'),
  ('hafs-27-12', 'hafs', 27, 12, 'وَأَدْخِلْ يَدَكَ فِى جَيْبِكَ تَخْرُجْ بَيْضَآءَ مِنْ غَيْرِ سُوٓءٍۢ ۖ فِى تِسْعِ ءَايَٰتٍ إِلَىٰ فِرْعَوْنَ وَقَوْمِهِۦٓ ۚ إِنَّهُمْ كَانُوا۟ قَوْمًۭا فَٰسِقِينَ', 'وأدخل يدك فى جيبك تخرج بيضاء من غير سوء  فى تسع ءايت إلى فرعون وقومه  إنهم كانوا قوما فسقين', NULL, 377, 'local:hafs-text.json'),
  ('hafs-27-13', 'hafs', 27, 13, 'فَلَمَّا جَآءَتْهُمْ ءَايَٰتُنَا مُبْصِرَةًۭ قَالُوا۟ هَٰذَا سِحْرٌۭ مُّبِينٌۭ', 'فلما جاءتهم ءايتنا مبصرة قالوا هذا سحر مبين', NULL, 377, 'local:hafs-text.json'),
  ('hafs-27-14', 'hafs', 27, 14, 'وَجَحَدُوا۟ بِهَا وَٱسْتَيْقَنَتْهَآ أَنفُسُهُمْ ظُلْمًۭا وَعُلُوًّۭا ۚ فَٱنظُرْ كَيْفَ كَانَ عَٰقِبَةُ ٱلْمُفْسِدِينَ', 'وجحدوا بها واستيقنتها أنفسهم ظلما وعلوا  فانظر كيف كان عقبة المفسدين', NULL, 378, 'local:hafs-text.json'),
  ('hafs-27-15', 'hafs', 27, 15, 'وَلَقَدْ ءَاتَيْنَا دَاوُۥدَ وَسُلَيْمَٰنَ عِلْمًۭا ۖ وَقَالَا ٱلْحَمْدُ لِلَّهِ ٱلَّذِى فَضَّلَنَا عَلَىٰ كَثِيرٍۢ مِّنْ عِبَادِهِ ٱلْمُؤْمِنِينَ', 'ولقد ءاتينا داود وسليمن علما  وقالا الحمد لله الذى فضلنا على كثير من عباده المؤمنين', NULL, 378, 'local:hafs-text.json'),
  ('hafs-27-16', 'hafs', 27, 16, 'وَوَرِثَ سُلَيْمَٰنُ دَاوُۥدَ ۖ وَقَالَ يَٰٓأَيُّهَا ٱلنَّاسُ عُلِّمْنَا مَنطِقَ ٱلطَّيْرِ وَأُوتِينَا مِن كُلِّ شَىْءٍ ۖ إِنَّ هَٰذَا لَهُوَ ٱلْفَضْلُ ٱلْمُبِينُ', 'وورث سليمن داود  وقال يأيها الناس علمنا منطق الطير وأوتينا من كل شىء  إن هذا لهو الفضل المبين', NULL, 378, 'local:hafs-text.json'),
  ('hafs-27-17', 'hafs', 27, 17, 'وَحُشِرَ لِسُلَيْمَٰنَ جُنُودُهُۥ مِنَ ٱلْجِنِّ وَٱلْإِنسِ وَٱلطَّيْرِ فَهُمْ يُوزَعُونَ', 'وحشر لسليمن جنوده من الجن والإنس والطير فهم يوزعون', NULL, 378, 'local:hafs-text.json'),
  ('hafs-27-18', 'hafs', 27, 18, 'حَتَّىٰٓ إِذَآ أَتَوْا۟ عَلَىٰ وَادِ ٱلنَّمْلِ قَالَتْ نَمْلَةٌۭ يَٰٓأَيُّهَا ٱلنَّمْلُ ٱدْخُلُوا۟ مَسَٰكِنَكُمْ لَا يَحْطِمَنَّكُمْ سُلَيْمَٰنُ وَجُنُودُهُۥ وَهُمْ لَا يَشْعُرُونَ', 'حتى إذا أتوا على واد النمل قالت نملة يأيها النمل ادخلوا مسكنكم لا يحطمنكم سليمن وجنوده وهم لا يشعرون', NULL, 378, 'local:hafs-text.json'),
  ('hafs-27-19', 'hafs', 27, 19, 'فَتَبَسَّمَ ضَاحِكًۭا مِّن قَوْلِهَا وَقَالَ رَبِّ أَوْزِعْنِىٓ أَنْ أَشْكُرَ نِعْمَتَكَ ٱلَّتِىٓ أَنْعَمْتَ عَلَىَّ وَعَلَىٰ وَٰلِدَىَّ وَأَنْ أَعْمَلَ صَٰلِحًۭا تَرْضَىٰهُ وَأَدْخِلْنِى بِرَحْمَتِكَ فِى عِبَادِكَ ٱلصَّٰلِحِينَ', 'فتبسم ضاحكا من قولها وقال رب أوزعنى أن أشكر نعمتك التى أنعمت على وعلى ولدى وأن أعمل صلحا ترضىه وأدخلنى برحمتك فى عبادك الصلحين', NULL, 378, 'local:hafs-text.json'),
  ('hafs-27-20', 'hafs', 27, 20, 'وَتَفَقَّدَ ٱلطَّيْرَ فَقَالَ مَا لِىَ لَآ أَرَى ٱلْهُدْهُدَ أَمْ كَانَ مِنَ ٱلْغَآئِبِينَ', 'وتفقد الطير فقال ما لى لا أرى الهدهد أم كان من الغائبين', NULL, 378, 'local:hafs-text.json'),
  ('hafs-27-21', 'hafs', 27, 21, 'لَأُعَذِّبَنَّهُۥ عَذَابًۭا شَدِيدًا أَوْ لَأَا۟ذْبَحَنَّهُۥٓ أَوْ لَيَأْتِيَنِّى بِسُلْطَٰنٍۢ مُّبِينٍۢ', 'لأعذبنه عذابا شديدا أو لأاذبحنه أو ليأتينى بسلطن مبين', NULL, 378, 'local:hafs-text.json'),
  ('hafs-27-22', 'hafs', 27, 22, 'فَمَكَثَ غَيْرَ بَعِيدٍۢ فَقَالَ أَحَطتُ بِمَا لَمْ تُحِطْ بِهِۦ وَجِئْتُكَ مِن سَبَإٍۭ بِنَبَإٍۢ يَقِينٍ', 'فمكث غير بعيد فقال أحطت بما لم تحط به وجئتك من سبإ بنبإ يقين', NULL, 378, 'local:hafs-text.json'),
  ('hafs-27-23', 'hafs', 27, 23, 'إِنِّى وَجَدتُّ ٱمْرَأَةًۭ تَمْلِكُهُمْ وَأُوتِيَتْ مِن كُلِّ شَىْءٍۢ وَلَهَا عَرْشٌ عَظِيمٌۭ', 'إنى وجدت امرأة تملكهم وأوتيت من كل شىء ولها عرش عظيم', NULL, 379, 'local:hafs-text.json'),
  ('hafs-27-24', 'hafs', 27, 24, 'وَجَدتُّهَا وَقَوْمَهَا يَسْجُدُونَ لِلشَّمْسِ مِن دُونِ ٱللَّهِ وَزَيَّنَ لَهُمُ ٱلشَّيْطَٰنُ أَعْمَٰلَهُمْ فَصَدَّهُمْ عَنِ ٱلسَّبِيلِ فَهُمْ لَا يَهْتَدُونَ', 'وجدتها وقومها يسجدون للشمس من دون الله وزين لهم الشيطن أعملهم فصدهم عن السبيل فهم لا يهتدون', NULL, 379, 'local:hafs-text.json'),
  ('hafs-27-25', 'hafs', 27, 25, 'أَلَّا يَسْجُدُوا۟ لِلَّهِ ٱلَّذِى يُخْرِجُ ٱلْخَبْءَ فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَيَعْلَمُ مَا تُخْفُونَ وَمَا تُعْلِنُونَ', 'ألا يسجدوا لله الذى يخرج الخبء فى السموت والأرض ويعلم ما تخفون وما تعلنون', NULL, 379, 'local:hafs-text.json'),
  ('hafs-27-26', 'hafs', 27, 26, 'ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَ رَبُّ ٱلْعَرْشِ ٱلْعَظِيمِ ۩', 'الله لا إله إلا هو رب العرش العظيم', NULL, 379, 'local:hafs-text.json'),
  ('hafs-27-27', 'hafs', 27, 27, '۞ قَالَ سَنَنظُرُ أَصَدَقْتَ أَمْ كُنتَ مِنَ ٱلْكَٰذِبِينَ', 'قال سننظر أصدقت أم كنت من الكذبين', NULL, 379, 'local:hafs-text.json'),
  ('hafs-27-28', 'hafs', 27, 28, 'ٱذْهَب بِّكِتَٰبِى هَٰذَا فَأَلْقِهْ إِلَيْهِمْ ثُمَّ تَوَلَّ عَنْهُمْ فَٱنظُرْ مَاذَا يَرْجِعُونَ', 'اذهب بكتبى هذا فألقه إليهم ثم تول عنهم فانظر ماذا يرجعون', NULL, 379, 'local:hafs-text.json'),
  ('hafs-27-29', 'hafs', 27, 29, 'قَالَتْ يَٰٓأَيُّهَا ٱلْمَلَؤُا۟ إِنِّىٓ أُلْقِىَ إِلَىَّ كِتَٰبٌۭ كَرِيمٌ', 'قالت يأيها الملؤا إنى ألقى إلى كتب كريم', NULL, 379, 'local:hafs-text.json'),
  ('hafs-27-30', 'hafs', 27, 30, 'إِنَّهُۥ مِن سُلَيْمَٰنَ وَإِنَّهُۥ بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ', 'إنه من سليمن وإنه بسم الله الرحمن الرحيم', NULL, 379, 'local:hafs-text.json'),
  ('hafs-27-31', 'hafs', 27, 31, 'أَلَّا تَعْلُوا۟ عَلَىَّ وَأْتُونِى مُسْلِمِينَ', 'ألا تعلوا على وأتونى مسلمين', NULL, 379, 'local:hafs-text.json'),
  ('hafs-27-32', 'hafs', 27, 32, 'قَالَتْ يَٰٓأَيُّهَا ٱلْمَلَؤُا۟ أَفْتُونِى فِىٓ أَمْرِى مَا كُنتُ قَاطِعَةً أَمْرًا حَتَّىٰ تَشْهَدُونِ', 'قالت يأيها الملؤا أفتونى فى أمرى ما كنت قاطعة أمرا حتى تشهدون', NULL, 379, 'local:hafs-text.json'),
  ('hafs-27-33', 'hafs', 27, 33, 'قَالُوا۟ نَحْنُ أُو۟لُوا۟ قُوَّةٍۢ وَأُو۟لُوا۟ بَأْسٍۢ شَدِيدٍۢ وَٱلْأَمْرُ إِلَيْكِ فَٱنظُرِى مَاذَا تَأْمُرِينَ', 'قالوا نحن أولوا قوة وأولوا بأس شديد والأمر إليك فانظرى ماذا تأمرين', NULL, 379, 'local:hafs-text.json'),
  ('hafs-27-34', 'hafs', 27, 34, 'قَالَتْ إِنَّ ٱلْمُلُوكَ إِذَا دَخَلُوا۟ قَرْيَةً أَفْسَدُوهَا وَجَعَلُوٓا۟ أَعِزَّةَ أَهْلِهَآ أَذِلَّةًۭ ۖ وَكَذَٰلِكَ يَفْعَلُونَ', 'قالت إن الملوك إذا دخلوا قرية أفسدوها وجعلوا أعزة أهلها أذلة  وكذلك يفعلون', NULL, 379, 'local:hafs-text.json'),
  ('hafs-27-35', 'hafs', 27, 35, 'وَإِنِّى مُرْسِلَةٌ إِلَيْهِم بِهَدِيَّةٍۢ فَنَاظِرَةٌۢ بِمَ يَرْجِعُ ٱلْمُرْسَلُونَ', 'وإنى مرسلة إليهم بهدية فناظرة بم يرجع المرسلون', NULL, 379, 'local:hafs-text.json'),
  ('hafs-27-36', 'hafs', 27, 36, 'فَلَمَّا جَآءَ سُلَيْمَٰنَ قَالَ أَتُمِدُّونَنِ بِمَالٍۢ فَمَآ ءَاتَىٰنِۦَ ٱللَّهُ خَيْرٌۭ مِّمَّآ ءَاتَىٰكُم بَلْ أَنتُم بِهَدِيَّتِكُمْ تَفْرَحُونَ', 'فلما جاء سليمن قال أتمدونن بمال فما ءاتىن الله خير مما ءاتىكم بل أنتم بهديتكم تفرحون', NULL, 380, 'local:hafs-text.json'),
  ('hafs-27-37', 'hafs', 27, 37, 'ٱرْجِعْ إِلَيْهِمْ فَلَنَأْتِيَنَّهُم بِجُنُودٍۢ لَّا قِبَلَ لَهُم بِهَا وَلَنُخْرِجَنَّهُم مِّنْهَآ أَذِلَّةًۭ وَهُمْ صَٰغِرُونَ', 'ارجع إليهم فلنأتينهم بجنود لا قبل لهم بها ولنخرجنهم منها أذلة وهم صغرون', NULL, 380, 'local:hafs-text.json'),
  ('hafs-27-38', 'hafs', 27, 38, 'قَالَ يَٰٓأَيُّهَا ٱلْمَلَؤُا۟ أَيُّكُمْ يَأْتِينِى بِعَرْشِهَا قَبْلَ أَن يَأْتُونِى مُسْلِمِينَ', 'قال يأيها الملؤا أيكم يأتينى بعرشها قبل أن يأتونى مسلمين', NULL, 380, 'local:hafs-text.json'),
  ('hafs-27-39', 'hafs', 27, 39, 'قَالَ عِفْرِيتٌۭ مِّنَ ٱلْجِنِّ أَنَا۠ ءَاتِيكَ بِهِۦ قَبْلَ أَن تَقُومَ مِن مَّقَامِكَ ۖ وَإِنِّى عَلَيْهِ لَقَوِىٌّ أَمِينٌۭ', 'قال عفريت من الجن أنا ءاتيك به قبل أن تقوم من مقامك  وإنى عليه لقوى أمين', NULL, 380, 'local:hafs-text.json'),
  ('hafs-27-40', 'hafs', 27, 40, 'قَالَ ٱلَّذِى عِندَهُۥ عِلْمٌۭ مِّنَ ٱلْكِتَٰبِ أَنَا۠ ءَاتِيكَ بِهِۦ قَبْلَ أَن يَرْتَدَّ إِلَيْكَ طَرْفُكَ ۚ فَلَمَّا رَءَاهُ مُسْتَقِرًّا عِندَهُۥ قَالَ هَٰذَا مِن فَضْلِ رَبِّى لِيَبْلُوَنِىٓ ءَأَشْكُرُ أَمْ أَكْفُرُ ۖ وَمَن شَكَرَ فَإِنَّمَا يَشْكُرُ لِنَفْسِهِۦ ۖ وَمَن كَفَرَ فَإِنَّ رَبِّى غَنِىٌّۭ كَرِيمٌۭ', 'قال الذى عنده علم من الكتب أنا ءاتيك به قبل أن يرتد إليك طرفك  فلما رءاه مستقرا عنده قال هذا من فضل ربى ليبلونى ءأشكر أم أكفر  ومن شكر فإنما يشكر لنفسه  ومن كفر فإن ربى غنى كريم', NULL, 380, 'local:hafs-text.json'),
  ('hafs-27-41', 'hafs', 27, 41, 'قَالَ نَكِّرُوا۟ لَهَا عَرْشَهَا نَنظُرْ أَتَهْتَدِىٓ أَمْ تَكُونُ مِنَ ٱلَّذِينَ لَا يَهْتَدُونَ', 'قال نكروا لها عرشها ننظر أتهتدى أم تكون من الذين لا يهتدون', NULL, 380, 'local:hafs-text.json')
insert into public.ayahs (id, riwayah, surah_number, ayah_number, text, simple_text, juz, page, source) values
  ('hafs-27-42', 'hafs', 27, 42, 'فَلَمَّا جَآءَتْ قِيلَ أَهَٰكَذَا عَرْشُكِ ۖ قَالَتْ كَأَنَّهُۥ هُوَ ۚ وَأُوتِينَا ٱلْعِلْمَ مِن قَبْلِهَا وَكُنَّا مُسْلِمِينَ', 'فلما جاءت قيل أهكذا عرشك  قالت كأنه هو  وأوتينا العلم من قبلها وكنا مسلمين', NULL, 380, 'local:hafs-text.json'),
  ('hafs-27-43', 'hafs', 27, 43, 'وَصَدَّهَا مَا كَانَت تَّعْبُدُ مِن دُونِ ٱللَّهِ ۖ إِنَّهَا كَانَتْ مِن قَوْمٍۢ كَٰفِرِينَ', 'وصدها ما كانت تعبد من دون الله  إنها كانت من قوم كفرين', NULL, 380, 'local:hafs-text.json'),
  ('hafs-27-44', 'hafs', 27, 44, 'قِيلَ لَهَا ٱدْخُلِى ٱلصَّرْحَ ۖ فَلَمَّا رَأَتْهُ حَسِبَتْهُ لُجَّةًۭ وَكَشَفَتْ عَن سَاقَيْهَا ۚ قَالَ إِنَّهُۥ صَرْحٌۭ مُّمَرَّدٌۭ مِّن قَوَارِيرَ ۗ قَالَتْ رَبِّ إِنِّى ظَلَمْتُ نَفْسِى وَأَسْلَمْتُ مَعَ سُلَيْمَٰنَ لِلَّهِ رَبِّ ٱلْعَٰلَمِينَ', 'قيل لها ادخلى الصرح  فلما رأته حسبته لجة وكشفت عن ساقيها  قال إنه صرح ممرد من قوارير  قالت رب إنى ظلمت نفسى وأسلمت مع سليمن لله رب العلمين', NULL, 380, 'local:hafs-text.json'),
  ('hafs-27-45', 'hafs', 27, 45, 'وَلَقَدْ أَرْسَلْنَآ إِلَىٰ ثَمُودَ أَخَاهُمْ صَٰلِحًا أَنِ ٱعْبُدُوا۟ ٱللَّهَ فَإِذَا هُمْ فَرِيقَانِ يَخْتَصِمُونَ', 'ولقد أرسلنا إلى ثمود أخاهم صلحا أن اعبدوا الله فإذا هم فريقان يختصمون', NULL, 381, 'local:hafs-text.json'),
  ('hafs-27-46', 'hafs', 27, 46, 'قَالَ يَٰقَوْمِ لِمَ تَسْتَعْجِلُونَ بِٱلسَّيِّئَةِ قَبْلَ ٱلْحَسَنَةِ ۖ لَوْلَا تَسْتَغْفِرُونَ ٱللَّهَ لَعَلَّكُمْ تُرْحَمُونَ', 'قال يقوم لم تستعجلون بالسيئة قبل الحسنة  لولا تستغفرون الله لعلكم ترحمون', NULL, 381, 'local:hafs-text.json'),
  ('hafs-27-47', 'hafs', 27, 47, 'قَالُوا۟ ٱطَّيَّرْنَا بِكَ وَبِمَن مَّعَكَ ۚ قَالَ طَٰٓئِرُكُمْ عِندَ ٱللَّهِ ۖ بَلْ أَنتُمْ قَوْمٌۭ تُفْتَنُونَ', 'قالوا اطيرنا بك وبمن معك  قال طئركم عند الله  بل أنتم قوم تفتنون', NULL, 381, 'local:hafs-text.json'),
  ('hafs-27-48', 'hafs', 27, 48, 'وَكَانَ فِى ٱلْمَدِينَةِ تِسْعَةُ رَهْطٍۢ يُفْسِدُونَ فِى ٱلْأَرْضِ وَلَا يُصْلِحُونَ', 'وكان فى المدينة تسعة رهط يفسدون فى الأرض ولا يصلحون', NULL, 381, 'local:hafs-text.json'),
  ('hafs-27-49', 'hafs', 27, 49, 'قَالُوا۟ تَقَاسَمُوا۟ بِٱللَّهِ لَنُبَيِّتَنَّهُۥ وَأَهْلَهُۥ ثُمَّ لَنَقُولَنَّ لِوَلِيِّهِۦ مَا شَهِدْنَا مَهْلِكَ أَهْلِهِۦ وَإِنَّا لَصَٰدِقُونَ', 'قالوا تقاسموا بالله لنبيتنه وأهله ثم لنقولن لوليه ما شهدنا مهلك أهله وإنا لصدقون', NULL, 381, 'local:hafs-text.json'),
  ('hafs-27-50', 'hafs', 27, 50, 'وَمَكَرُوا۟ مَكْرًۭا وَمَكَرْنَا مَكْرًۭا وَهُمْ لَا يَشْعُرُونَ', 'ومكروا مكرا ومكرنا مكرا وهم لا يشعرون', NULL, 381, 'local:hafs-text.json'),
  ('hafs-27-51', 'hafs', 27, 51, 'فَٱنظُرْ كَيْفَ كَانَ عَٰقِبَةُ مَكْرِهِمْ أَنَّا دَمَّرْنَٰهُمْ وَقَوْمَهُمْ أَجْمَعِينَ', 'فانظر كيف كان عقبة مكرهم أنا دمرنهم وقومهم أجمعين', NULL, 381, 'local:hafs-text.json'),
  ('hafs-27-52', 'hafs', 27, 52, 'فَتِلْكَ بُيُوتُهُمْ خَاوِيَةًۢ بِمَا ظَلَمُوٓا۟ ۗ إِنَّ فِى ذَٰلِكَ لَءَايَةًۭ لِّقَوْمٍۢ يَعْلَمُونَ', 'فتلك بيوتهم خاوية بما ظلموا  إن فى ذلك لءاية لقوم يعلمون', NULL, 381, 'local:hafs-text.json'),
  ('hafs-27-53', 'hafs', 27, 53, 'وَأَنجَيْنَا ٱلَّذِينَ ءَامَنُوا۟ وَكَانُوا۟ يَتَّقُونَ', 'وأنجينا الذين ءامنوا وكانوا يتقون', NULL, 381, 'local:hafs-text.json'),
  ('hafs-27-54', 'hafs', 27, 54, 'وَلُوطًا إِذْ قَالَ لِقَوْمِهِۦٓ أَتَأْتُونَ ٱلْفَٰحِشَةَ وَأَنتُمْ تُبْصِرُونَ', 'ولوطا إذ قال لقومه أتأتون الفحشة وأنتم تبصرون', NULL, 381, 'local:hafs-text.json'),
  ('hafs-27-55', 'hafs', 27, 55, 'أَئِنَّكُمْ لَتَأْتُونَ ٱلرِّجَالَ شَهْوَةًۭ مِّن دُونِ ٱلنِّسَآءِ ۚ بَلْ أَنتُمْ قَوْمٌۭ تَجْهَلُونَ', 'أئنكم لتأتون الرجال شهوة من دون النساء  بل أنتم قوم تجهلون', NULL, 381, 'local:hafs-text.json'),
  ('hafs-27-56', 'hafs', 27, 56, '۞ فَمَا كَانَ جَوَابَ قَوْمِهِۦٓ إِلَّآ أَن قَالُوٓا۟ أَخْرِجُوٓا۟ ءَالَ لُوطٍۢ مِّن قَرْيَتِكُمْ ۖ إِنَّهُمْ أُنَاسٌۭ يَتَطَهَّرُونَ', 'فما كان جواب قومه إلا أن قالوا أخرجوا ءال لوط من قريتكم  إنهم أناس يتطهرون', NULL, 382, 'local:hafs-text.json'),
  ('hafs-27-57', 'hafs', 27, 57, 'فَأَنجَيْنَٰهُ وَأَهْلَهُۥٓ إِلَّا ٱمْرَأَتَهُۥ قَدَّرْنَٰهَا مِنَ ٱلْغَٰبِرِينَ', 'فأنجينه وأهله إلا امرأته قدرنها من الغبرين', NULL, 382, 'local:hafs-text.json'),
  ('hafs-27-58', 'hafs', 27, 58, 'وَأَمْطَرْنَا عَلَيْهِم مَّطَرًۭا ۖ فَسَآءَ مَطَرُ ٱلْمُنذَرِينَ', 'وأمطرنا عليهم مطرا  فساء مطر المنذرين', NULL, 382, 'local:hafs-text.json'),
  ('hafs-27-59', 'hafs', 27, 59, 'قُلِ ٱلْحَمْدُ لِلَّهِ وَسَلَٰمٌ عَلَىٰ عِبَادِهِ ٱلَّذِينَ ٱصْطَفَىٰٓ ۗ ءَآللَّهُ خَيْرٌ أَمَّا يُشْرِكُونَ', 'قل الحمد لله وسلم على عباده الذين اصطفى  ءالله خير أما يشركون', NULL, 382, 'local:hafs-text.json'),
  ('hafs-27-60', 'hafs', 27, 60, 'أَمَّنْ خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ وَأَنزَلَ لَكُم مِّنَ ٱلسَّمَآءِ مَآءًۭ فَأَنۢبَتْنَا بِهِۦ حَدَآئِقَ ذَاتَ بَهْجَةٍۢ مَّا كَانَ لَكُمْ أَن تُنۢبِتُوا۟ شَجَرَهَآ ۗ أَءِلَٰهٌۭ مَّعَ ٱللَّهِ ۚ بَلْ هُمْ قَوْمٌۭ يَعْدِلُونَ', 'أمن خلق السموت والأرض وأنزل لكم من السماء ماء فأنبتنا به حدائق ذات بهجة ما كان لكم أن تنبتوا شجرها  أءله مع الله  بل هم قوم يعدلون', NULL, 382, 'local:hafs-text.json'),
  ('hafs-27-61', 'hafs', 27, 61, 'أَمَّن جَعَلَ ٱلْأَرْضَ قَرَارًۭا وَجَعَلَ خِلَٰلَهَآ أَنْهَٰرًۭا وَجَعَلَ لَهَا رَوَٰسِىَ وَجَعَلَ بَيْنَ ٱلْبَحْرَيْنِ حَاجِزًا ۗ أَءِلَٰهٌۭ مَّعَ ٱللَّهِ ۚ بَلْ أَكْثَرُهُمْ لَا يَعْلَمُونَ', 'أمن جعل الأرض قرارا وجعل خللها أنهرا وجعل لها روسى وجعل بين البحرين حاجزا  أءله مع الله  بل أكثرهم لا يعلمون', NULL, 382, 'local:hafs-text.json'),
  ('hafs-27-62', 'hafs', 27, 62, 'أَمَّن يُجِيبُ ٱلْمُضْطَرَّ إِذَا دَعَاهُ وَيَكْشِفُ ٱلسُّوٓءَ وَيَجْعَلُكُمْ خُلَفَآءَ ٱلْأَرْضِ ۗ أَءِلَٰهٌۭ مَّعَ ٱللَّهِ ۚ قَلِيلًۭا مَّا تَذَكَّرُونَ', 'أمن يجيب المضطر إذا دعاه ويكشف السوء ويجعلكم خلفاء الأرض  أءله مع الله  قليلا ما تذكرون', NULL, 382, 'local:hafs-text.json'),
  ('hafs-27-63', 'hafs', 27, 63, 'أَمَّن يَهْدِيكُمْ فِى ظُلُمَٰتِ ٱلْبَرِّ وَٱلْبَحْرِ وَمَن يُرْسِلُ ٱلرِّيَٰحَ بُشْرًۢا بَيْنَ يَدَىْ رَحْمَتِهِۦٓ ۗ أَءِلَٰهٌۭ مَّعَ ٱللَّهِ ۚ تَعَٰلَى ٱللَّهُ عَمَّا يُشْرِكُونَ', 'أمن يهديكم فى ظلمت البر والبحر ومن يرسل الريح بشرا بين يدى رحمته  أءله مع الله  تعلى الله عما يشركون', NULL, 382, 'local:hafs-text.json'),
  ('hafs-27-64', 'hafs', 27, 64, 'أَمَّن يَبْدَؤُا۟ ٱلْخَلْقَ ثُمَّ يُعِيدُهُۥ وَمَن يَرْزُقُكُم مِّنَ ٱلسَّمَآءِ وَٱلْأَرْضِ ۗ أَءِلَٰهٌۭ مَّعَ ٱللَّهِ ۚ قُلْ هَاتُوا۟ بُرْهَٰنَكُمْ إِن كُنتُمْ صَٰدِقِينَ', 'أمن يبدؤا الخلق ثم يعيده ومن يرزقكم من السماء والأرض  أءله مع الله  قل هاتوا برهنكم إن كنتم صدقين', NULL, 383, 'local:hafs-text.json'),
  ('hafs-27-65', 'hafs', 27, 65, 'قُل لَّا يَعْلَمُ مَن فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ ٱلْغَيْبَ إِلَّا ٱللَّهُ ۚ وَمَا يَشْعُرُونَ أَيَّانَ يُبْعَثُونَ', 'قل لا يعلم من فى السموت والأرض الغيب إلا الله  وما يشعرون أيان يبعثون', NULL, 383, 'local:hafs-text.json'),
  ('hafs-27-66', 'hafs', 27, 66, 'بَلِ ٱدَّٰرَكَ عِلْمُهُمْ فِى ٱلْءَاخِرَةِ ۚ بَلْ هُمْ فِى شَكٍّۢ مِّنْهَا ۖ بَلْ هُم مِّنْهَا عَمُونَ', 'بل ادرك علمهم فى الءاخرة  بل هم فى شك منها  بل هم منها عمون', NULL, 383, 'local:hafs-text.json'),
  ('hafs-27-67', 'hafs', 27, 67, 'وَقَالَ ٱلَّذِينَ كَفَرُوٓا۟ أَءِذَا كُنَّا تُرَٰبًۭا وَءَابَآؤُنَآ أَئِنَّا لَمُخْرَجُونَ', 'وقال الذين كفروا أءذا كنا تربا وءاباؤنا أئنا لمخرجون', NULL, 383, 'local:hafs-text.json'),
  ('hafs-27-68', 'hafs', 27, 68, 'لَقَدْ وُعِدْنَا هَٰذَا نَحْنُ وَءَابَآؤُنَا مِن قَبْلُ إِنْ هَٰذَآ إِلَّآ أَسَٰطِيرُ ٱلْأَوَّلِينَ', 'لقد وعدنا هذا نحن وءاباؤنا من قبل إن هذا إلا أسطير الأولين', NULL, 383, 'local:hafs-text.json'),
  ('hafs-27-69', 'hafs', 27, 69, 'قُلْ سِيرُوا۟ فِى ٱلْأَرْضِ فَٱنظُرُوا۟ كَيْفَ كَانَ عَٰقِبَةُ ٱلْمُجْرِمِينَ', 'قل سيروا فى الأرض فانظروا كيف كان عقبة المجرمين', NULL, 383, 'local:hafs-text.json'),
  ('hafs-27-70', 'hafs', 27, 70, 'وَلَا تَحْزَنْ عَلَيْهِمْ وَلَا تَكُن فِى ضَيْقٍۢ مِّمَّا يَمْكُرُونَ', 'ولا تحزن عليهم ولا تكن فى ضيق مما يمكرون', NULL, 383, 'local:hafs-text.json'),
  ('hafs-27-71', 'hafs', 27, 71, 'وَيَقُولُونَ مَتَىٰ هَٰذَا ٱلْوَعْدُ إِن كُنتُمْ صَٰدِقِينَ', 'ويقولون متى هذا الوعد إن كنتم صدقين', NULL, 383, 'local:hafs-text.json'),
  ('hafs-27-72', 'hafs', 27, 72, 'قُلْ عَسَىٰٓ أَن يَكُونَ رَدِفَ لَكُم بَعْضُ ٱلَّذِى تَسْتَعْجِلُونَ', 'قل عسى أن يكون ردف لكم بعض الذى تستعجلون', NULL, 383, 'local:hafs-text.json'),
  ('hafs-27-73', 'hafs', 27, 73, 'وَإِنَّ رَبَّكَ لَذُو فَضْلٍ عَلَى ٱلنَّاسِ وَلَٰكِنَّ أَكْثَرَهُمْ لَا يَشْكُرُونَ', 'وإن ربك لذو فضل على الناس ولكن أكثرهم لا يشكرون', NULL, 383, 'local:hafs-text.json'),
  ('hafs-27-74', 'hafs', 27, 74, 'وَإِنَّ رَبَّكَ لَيَعْلَمُ مَا تُكِنُّ صُدُورُهُمْ وَمَا يُعْلِنُونَ', 'وإن ربك ليعلم ما تكن صدورهم وما يعلنون', NULL, 383, 'local:hafs-text.json'),
  ('hafs-27-75', 'hafs', 27, 75, 'وَمَا مِنْ غَآئِبَةٍۢ فِى ٱلسَّمَآءِ وَٱلْأَرْضِ إِلَّا فِى كِتَٰبٍۢ مُّبِينٍ', 'وما من غائبة فى السماء والأرض إلا فى كتب مبين', NULL, 383, 'local:hafs-text.json'),
  ('hafs-27-76', 'hafs', 27, 76, 'إِنَّ هَٰذَا ٱلْقُرْءَانَ يَقُصُّ عَلَىٰ بَنِىٓ إِسْرَٰٓءِيلَ أَكْثَرَ ٱلَّذِى هُمْ فِيهِ يَخْتَلِفُونَ', 'إن هذا القرءان يقص على بنى إسرءيل أكثر الذى هم فيه يختلفون', NULL, 383, 'local:hafs-text.json'),
  ('hafs-27-77', 'hafs', 27, 77, 'وَإِنَّهُۥ لَهُدًۭى وَرَحْمَةٌۭ لِّلْمُؤْمِنِينَ', 'وإنه لهدى ورحمة للمؤمنين', NULL, 384, 'local:hafs-text.json'),
  ('hafs-27-78', 'hafs', 27, 78, 'إِنَّ رَبَّكَ يَقْضِى بَيْنَهُم بِحُكْمِهِۦ ۚ وَهُوَ ٱلْعَزِيزُ ٱلْعَلِيمُ', 'إن ربك يقضى بينهم بحكمه  وهو العزيز العليم', NULL, 384, 'local:hafs-text.json'),
  ('hafs-27-79', 'hafs', 27, 79, 'فَتَوَكَّلْ عَلَى ٱللَّهِ ۖ إِنَّكَ عَلَى ٱلْحَقِّ ٱلْمُبِينِ', 'فتوكل على الله  إنك على الحق المبين', NULL, 384, 'local:hafs-text.json'),
  ('hafs-27-80', 'hafs', 27, 80, 'إِنَّكَ لَا تُسْمِعُ ٱلْمَوْتَىٰ وَلَا تُسْمِعُ ٱلصُّمَّ ٱلدُّعَآءَ إِذَا وَلَّوْا۟ مُدْبِرِينَ', 'إنك لا تسمع الموتى ولا تسمع الصم الدعاء إذا ولوا مدبرين', NULL, 384, 'local:hafs-text.json'),
  ('hafs-27-81', 'hafs', 27, 81, 'وَمَآ أَنتَ بِهَٰدِى ٱلْعُمْىِ عَن ضَلَٰلَتِهِمْ ۖ إِن تُسْمِعُ إِلَّا مَن يُؤْمِنُ بِـَٔايَٰتِنَا فَهُم مُّسْلِمُونَ', 'وما أنت بهدى العمى عن ضللتهم  إن تسمع إلا من يؤمن بايتنا فهم مسلمون', NULL, 384, 'local:hafs-text.json'),
  ('hafs-27-82', 'hafs', 27, 82, '۞ وَإِذَا وَقَعَ ٱلْقَوْلُ عَلَيْهِمْ أَخْرَجْنَا لَهُمْ دَآبَّةًۭ مِّنَ ٱلْأَرْضِ تُكَلِّمُهُمْ أَنَّ ٱلنَّاسَ كَانُوا۟ بِـَٔايَٰتِنَا لَا يُوقِنُونَ', 'وإذا وقع القول عليهم أخرجنا لهم دابة من الأرض تكلمهم أن الناس كانوا بايتنا لا يوقنون', NULL, 384, 'local:hafs-text.json'),
  ('hafs-27-83', 'hafs', 27, 83, 'وَيَوْمَ نَحْشُرُ مِن كُلِّ أُمَّةٍۢ فَوْجًۭا مِّمَّن يُكَذِّبُ بِـَٔايَٰتِنَا فَهُمْ يُوزَعُونَ', 'ويوم نحشر من كل أمة فوجا ممن يكذب بايتنا فهم يوزعون', NULL, 384, 'local:hafs-text.json'),
  ('hafs-27-84', 'hafs', 27, 84, 'حَتَّىٰٓ إِذَا جَآءُو قَالَ أَكَذَّبْتُم بِـَٔايَٰتِى وَلَمْ تُحِيطُوا۟ بِهَا عِلْمًا أَمَّاذَا كُنتُمْ تَعْمَلُونَ', 'حتى إذا جاءو قال أكذبتم بايتى ولم تحيطوا بها علما أماذا كنتم تعملون', NULL, 384, 'local:hafs-text.json'),
  ('hafs-27-85', 'hafs', 27, 85, 'وَوَقَعَ ٱلْقَوْلُ عَلَيْهِم بِمَا ظَلَمُوا۟ فَهُمْ لَا يَنطِقُونَ', 'ووقع القول عليهم بما ظلموا فهم لا ينطقون', NULL, 384, 'local:hafs-text.json'),
  ('hafs-27-86', 'hafs', 27, 86, 'أَلَمْ يَرَوْا۟ أَنَّا جَعَلْنَا ٱلَّيْلَ لِيَسْكُنُوا۟ فِيهِ وَٱلنَّهَارَ مُبْصِرًا ۚ إِنَّ فِى ذَٰلِكَ لَءَايَٰتٍۢ لِّقَوْمٍۢ يُؤْمِنُونَ', 'ألم يروا أنا جعلنا اليل ليسكنوا فيه والنهار مبصرا  إن فى ذلك لءايت لقوم يؤمنون', NULL, 384, 'local:hafs-text.json'),
  ('hafs-27-87', 'hafs', 27, 87, 'وَيَوْمَ يُنفَخُ فِى ٱلصُّورِ فَفَزِعَ مَن فِى ٱلسَّمَٰوَٰتِ وَمَن فِى ٱلْأَرْضِ إِلَّا مَن شَآءَ ٱللَّهُ ۚ وَكُلٌّ أَتَوْهُ دَٰخِرِينَ', 'ويوم ينفخ فى الصور ففزع من فى السموت ومن فى الأرض إلا من شاء الله  وكل أتوه دخرين', NULL, 384, 'local:hafs-text.json'),
  ('hafs-27-88', 'hafs', 27, 88, 'وَتَرَى ٱلْجِبَالَ تَحْسَبُهَا جَامِدَةًۭ وَهِىَ تَمُرُّ مَرَّ ٱلسَّحَابِ ۚ صُنْعَ ٱللَّهِ ٱلَّذِىٓ أَتْقَنَ كُلَّ شَىْءٍ ۚ إِنَّهُۥ خَبِيرٌۢ بِمَا تَفْعَلُونَ', 'وترى الجبال تحسبها جامدة وهى تمر مر السحاب  صنع الله الذى أتقن كل شىء  إنه خبير بما تفعلون', NULL, 384, 'local:hafs-text.json'),
  ('hafs-27-89', 'hafs', 27, 89, 'مَن جَآءَ بِٱلْحَسَنَةِ فَلَهُۥ خَيْرٌۭ مِّنْهَا وَهُم مِّن فَزَعٍۢ يَوْمَئِذٍ ءَامِنُونَ', 'من جاء بالحسنة فله خير منها وهم من فزع يومئذ ءامنون', NULL, 385, 'local:hafs-text.json'),
  ('hafs-27-90', 'hafs', 27, 90, 'وَمَن جَآءَ بِٱلسَّيِّئَةِ فَكُبَّتْ وُجُوهُهُمْ فِى ٱلنَّارِ هَلْ تُجْزَوْنَ إِلَّا مَا كُنتُمْ تَعْمَلُونَ', 'ومن جاء بالسيئة فكبت وجوههم فى النار هل تجزون إلا ما كنتم تعملون', NULL, 385, 'local:hafs-text.json'),
  ('hafs-27-91', 'hafs', 27, 91, 'إِنَّمَآ أُمِرْتُ أَنْ أَعْبُدَ رَبَّ هَٰذِهِ ٱلْبَلْدَةِ ٱلَّذِى حَرَّمَهَا وَلَهُۥ كُلُّ شَىْءٍۢ ۖ وَأُمِرْتُ أَنْ أَكُونَ مِنَ ٱلْمُسْلِمِينَ', 'إنما أمرت أن أعبد رب هذه البلدة الذى حرمها وله كل شىء  وأمرت أن أكون من المسلمين', NULL, 385, 'local:hafs-text.json'),
  ('hafs-27-92', 'hafs', 27, 92, 'وَأَنْ أَتْلُوَا۟ ٱلْقُرْءَانَ ۖ فَمَنِ ٱهْتَدَىٰ فَإِنَّمَا يَهْتَدِى لِنَفْسِهِۦ ۖ وَمَن ضَلَّ فَقُلْ إِنَّمَآ أَنَا۠ مِنَ ٱلْمُنذِرِينَ', 'وأن أتلوا القرءان  فمن اهتدى فإنما يهتدى لنفسه  ومن ضل فقل إنما أنا من المنذرين', NULL, 385, 'local:hafs-text.json'),
  ('hafs-27-93', 'hafs', 27, 93, 'وَقُلِ ٱلْحَمْدُ لِلَّهِ سَيُرِيكُمْ ءَايَٰتِهِۦ فَتَعْرِفُونَهَا ۚ وَمَا رَبُّكَ بِغَٰفِلٍ عَمَّا تَعْمَلُونَ', 'وقل الحمد لله سيريكم ءايته فتعرفونها  وما ربك بغفل عما تعملون', NULL, 385, 'local:hafs-text.json'),
  ('hafs-28-1', 'hafs', 28, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ طسٓمٓ', 'بسم الله الرحمن الرحيم طسم', NULL, 385, 'local:hafs-text.json'),
  ('hafs-28-2', 'hafs', 28, 2, 'تِلْكَ ءَايَٰتُ ٱلْكِتَٰبِ ٱلْمُبِينِ', 'تلك ءايت الكتب المبين', NULL, 385, 'local:hafs-text.json'),
  ('hafs-28-3', 'hafs', 28, 3, 'نَتْلُوا۟ عَلَيْكَ مِن نَّبَإِ مُوسَىٰ وَفِرْعَوْنَ بِٱلْحَقِّ لِقَوْمٍۢ يُؤْمِنُونَ', 'نتلوا عليك من نبإ موسى وفرعون بالحق لقوم يؤمنون', NULL, 385, 'local:hafs-text.json'),
  ('hafs-28-4', 'hafs', 28, 4, 'إِنَّ فِرْعَوْنَ عَلَا فِى ٱلْأَرْضِ وَجَعَلَ أَهْلَهَا شِيَعًۭا يَسْتَضْعِفُ طَآئِفَةًۭ مِّنْهُمْ يُذَبِّحُ أَبْنَآءَهُمْ وَيَسْتَحْىِۦ نِسَآءَهُمْ ۚ إِنَّهُۥ كَانَ مِنَ ٱلْمُفْسِدِينَ', 'إن فرعون علا فى الأرض وجعل أهلها شيعا يستضعف طائفة منهم يذبح أبناءهم ويستحى نساءهم  إنه كان من المفسدين', NULL, 385, 'local:hafs-text.json'),
  ('hafs-28-5', 'hafs', 28, 5, 'وَنُرِيدُ أَن نَّمُنَّ عَلَى ٱلَّذِينَ ٱسْتُضْعِفُوا۟ فِى ٱلْأَرْضِ وَنَجْعَلَهُمْ أَئِمَّةًۭ وَنَجْعَلَهُمُ ٱلْوَٰرِثِينَ', 'ونريد أن نمن على الذين استضعفوا فى الأرض ونجعلهم أئمة ونجعلهم الورثين', NULL, 385, 'local:hafs-text.json'),
  ('hafs-28-6', 'hafs', 28, 6, 'وَنُمَكِّنَ لَهُمْ فِى ٱلْأَرْضِ وَنُرِىَ فِرْعَوْنَ وَهَٰمَٰنَ وَجُنُودَهُمَا مِنْهُم مَّا كَانُوا۟ يَحْذَرُونَ', 'ونمكن لهم فى الأرض ونرى فرعون وهمن وجنودهما منهم ما كانوا يحذرون', NULL, 386, 'local:hafs-text.json'),
  ('hafs-28-7', 'hafs', 28, 7, 'وَأَوْحَيْنَآ إِلَىٰٓ أُمِّ مُوسَىٰٓ أَنْ أَرْضِعِيهِ ۖ فَإِذَا خِفْتِ عَلَيْهِ فَأَلْقِيهِ فِى ٱلْيَمِّ وَلَا تَخَافِى وَلَا تَحْزَنِىٓ ۖ إِنَّا رَآدُّوهُ إِلَيْكِ وَجَاعِلُوهُ مِنَ ٱلْمُرْسَلِينَ', 'وأوحينا إلى أم موسى أن أرضعيه  فإذا خفت عليه فألقيه فى اليم ولا تخافى ولا تحزنى  إنا رادوه إليك وجاعلوه من المرسلين', NULL, 386, 'local:hafs-text.json'),
  ('hafs-28-8', 'hafs', 28, 8, 'فَٱلْتَقَطَهُۥٓ ءَالُ فِرْعَوْنَ لِيَكُونَ لَهُمْ عَدُوًّۭا وَحَزَنًا ۗ إِنَّ فِرْعَوْنَ وَهَٰمَٰنَ وَجُنُودَهُمَا كَانُوا۟ خَٰطِـِٔينَ', 'فالتقطه ءال فرعون ليكون لهم عدوا وحزنا  إن فرعون وهمن وجنودهما كانوا خطين', NULL, 386, 'local:hafs-text.json'),
  ('hafs-28-9', 'hafs', 28, 9, 'وَقَالَتِ ٱمْرَأَتُ فِرْعَوْنَ قُرَّتُ عَيْنٍۢ لِّى وَلَكَ ۖ لَا تَقْتُلُوهُ عَسَىٰٓ أَن يَنفَعَنَآ أَوْ نَتَّخِذَهُۥ وَلَدًۭا وَهُمْ لَا يَشْعُرُونَ', 'وقالت امرأت فرعون قرت عين لى ولك  لا تقتلوه عسى أن ينفعنا أو نتخذه ولدا وهم لا يشعرون', NULL, 386, 'local:hafs-text.json'),
  ('hafs-28-10', 'hafs', 28, 10, 'وَأَصْبَحَ فُؤَادُ أُمِّ مُوسَىٰ فَٰرِغًا ۖ إِن كَادَتْ لَتُبْدِى بِهِۦ لَوْلَآ أَن رَّبَطْنَا عَلَىٰ قَلْبِهَا لِتَكُونَ مِنَ ٱلْمُؤْمِنِينَ', 'وأصبح فؤاد أم موسى فرغا  إن كادت لتبدى به لولا أن ربطنا على قلبها لتكون من المؤمنين', NULL, 386, 'local:hafs-text.json'),
  ('hafs-28-11', 'hafs', 28, 11, 'وَقَالَتْ لِأُخْتِهِۦ قُصِّيهِ ۖ فَبَصُرَتْ بِهِۦ عَن جُنُبٍۢ وَهُمْ لَا يَشْعُرُونَ', 'وقالت لأخته قصيه  فبصرت به عن جنب وهم لا يشعرون', NULL, 386, 'local:hafs-text.json'),
  ('hafs-28-12', 'hafs', 28, 12, '۞ وَحَرَّمْنَا عَلَيْهِ ٱلْمَرَاضِعَ مِن قَبْلُ فَقَالَتْ هَلْ أَدُلُّكُمْ عَلَىٰٓ أَهْلِ بَيْتٍۢ يَكْفُلُونَهُۥ لَكُمْ وَهُمْ لَهُۥ نَٰصِحُونَ', 'وحرمنا عليه المراضع من قبل فقالت هل أدلكم على أهل بيت يكفلونه لكم وهم له نصحون', NULL, 386, 'local:hafs-text.json'),
  ('hafs-28-13', 'hafs', 28, 13, 'فَرَدَدْنَٰهُ إِلَىٰٓ أُمِّهِۦ كَىْ تَقَرَّ عَيْنُهَا وَلَا تَحْزَنَ وَلِتَعْلَمَ أَنَّ وَعْدَ ٱللَّهِ حَقٌّۭ وَلَٰكِنَّ أَكْثَرَهُمْ لَا يَعْلَمُونَ', 'فرددنه إلى أمه كى تقر عينها ولا تحزن ولتعلم أن وعد الله حق ولكن أكثرهم لا يعلمون', NULL, 386, 'local:hafs-text.json'),
  ('hafs-28-14', 'hafs', 28, 14, 'وَلَمَّا بَلَغَ أَشُدَّهُۥ وَٱسْتَوَىٰٓ ءَاتَيْنَٰهُ حُكْمًۭا وَعِلْمًۭا ۚ وَكَذَٰلِكَ نَجْزِى ٱلْمُحْسِنِينَ', 'ولما بلغ أشده واستوى ءاتينه حكما وعلما  وكذلك نجزى المحسنين', NULL, 387, 'local:hafs-text.json'),
  ('hafs-28-15', 'hafs', 28, 15, 'وَدَخَلَ ٱلْمَدِينَةَ عَلَىٰ حِينِ غَفْلَةٍۢ مِّنْ أَهْلِهَا فَوَجَدَ فِيهَا رَجُلَيْنِ يَقْتَتِلَانِ هَٰذَا مِن شِيعَتِهِۦ وَهَٰذَا مِنْ عَدُوِّهِۦ ۖ فَٱسْتَغَٰثَهُ ٱلَّذِى مِن شِيعَتِهِۦ عَلَى ٱلَّذِى مِنْ عَدُوِّهِۦ فَوَكَزَهُۥ مُوسَىٰ فَقَضَىٰ عَلَيْهِ ۖ قَالَ هَٰذَا مِنْ عَمَلِ ٱلشَّيْطَٰنِ ۖ إِنَّهُۥ عَدُوٌّۭ مُّضِلٌّۭ مُّبِينٌۭ', 'ودخل المدينة على حين غفلة من أهلها فوجد فيها رجلين يقتتلان هذا من شيعته وهذا من عدوه  فاستغثه الذى من شيعته على الذى من عدوه فوكزه موسى فقضى عليه  قال هذا من عمل الشيطن  إنه عدو مضل مبين', NULL, 387, 'local:hafs-text.json'),
  ('hafs-28-16', 'hafs', 28, 16, 'قَالَ رَبِّ إِنِّى ظَلَمْتُ نَفْسِى فَٱغْفِرْ لِى فَغَفَرَ لَهُۥٓ ۚ إِنَّهُۥ هُوَ ٱلْغَفُورُ ٱلرَّحِيمُ', 'قال رب إنى ظلمت نفسى فاغفر لى فغفر له  إنه هو الغفور الرحيم', NULL, 387, 'local:hafs-text.json'),
  ('hafs-28-17', 'hafs', 28, 17, 'قَالَ رَبِّ بِمَآ أَنْعَمْتَ عَلَىَّ فَلَنْ أَكُونَ ظَهِيرًۭا لِّلْمُجْرِمِينَ', 'قال رب بما أنعمت على فلن أكون ظهيرا للمجرمين', NULL, 387, 'local:hafs-text.json'),
  ('hafs-28-18', 'hafs', 28, 18, 'فَأَصْبَحَ فِى ٱلْمَدِينَةِ خَآئِفًۭا يَتَرَقَّبُ فَإِذَا ٱلَّذِى ٱسْتَنصَرَهُۥ بِٱلْأَمْسِ يَسْتَصْرِخُهُۥ ۚ قَالَ لَهُۥ مُوسَىٰٓ إِنَّكَ لَغَوِىٌّۭ مُّبِينٌۭ', 'فأصبح فى المدينة خائفا يترقب فإذا الذى استنصره بالأمس يستصرخه  قال له موسى إنك لغوى مبين', NULL, 387, 'local:hafs-text.json'),
  ('hafs-28-19', 'hafs', 28, 19, 'فَلَمَّآ أَنْ أَرَادَ أَن يَبْطِشَ بِٱلَّذِى هُوَ عَدُوٌّۭ لَّهُمَا قَالَ يَٰمُوسَىٰٓ أَتُرِيدُ أَن تَقْتُلَنِى كَمَا قَتَلْتَ نَفْسًۢا بِٱلْأَمْسِ ۖ إِن تُرِيدُ إِلَّآ أَن تَكُونَ جَبَّارًۭا فِى ٱلْأَرْضِ وَمَا تُرِيدُ أَن تَكُونَ مِنَ ٱلْمُصْلِحِينَ', 'فلما أن أراد أن يبطش بالذى هو عدو لهما قال يموسى أتريد أن تقتلنى كما قتلت نفسا بالأمس  إن تريد إلا أن تكون جبارا فى الأرض وما تريد أن تكون من المصلحين', NULL, 387, 'local:hafs-text.json'),
  ('hafs-28-20', 'hafs', 28, 20, 'وَجَآءَ رَجُلٌۭ مِّنْ أَقْصَا ٱلْمَدِينَةِ يَسْعَىٰ قَالَ يَٰمُوسَىٰٓ إِنَّ ٱلْمَلَأَ يَأْتَمِرُونَ بِكَ لِيَقْتُلُوكَ فَٱخْرُجْ إِنِّى لَكَ مِنَ ٱلنَّٰصِحِينَ', 'وجاء رجل من أقصا المدينة يسعى قال يموسى إن الملأ يأتمرون بك ليقتلوك فاخرج إنى لك من النصحين', NULL, 387, 'local:hafs-text.json'),
  ('hafs-28-21', 'hafs', 28, 21, 'فَخَرَجَ مِنْهَا خَآئِفًۭا يَتَرَقَّبُ ۖ قَالَ رَبِّ نَجِّنِى مِنَ ٱلْقَوْمِ ٱلظَّٰلِمِينَ', 'فخرج منها خائفا يترقب  قال رب نجنى من القوم الظلمين', NULL, 387, 'local:hafs-text.json'),
  ('hafs-28-22', 'hafs', 28, 22, 'وَلَمَّا تَوَجَّهَ تِلْقَآءَ مَدْيَنَ قَالَ عَسَىٰ رَبِّىٓ أَن يَهْدِيَنِى سَوَآءَ ٱلسَّبِيلِ', 'ولما توجه تلقاء مدين قال عسى ربى أن يهدينى سواء السبيل', NULL, 388, 'local:hafs-text.json'),
  ('hafs-28-23', 'hafs', 28, 23, 'وَلَمَّا وَرَدَ مَآءَ مَدْيَنَ وَجَدَ عَلَيْهِ أُمَّةًۭ مِّنَ ٱلنَّاسِ يَسْقُونَ وَوَجَدَ مِن دُونِهِمُ ٱمْرَأَتَيْنِ تَذُودَانِ ۖ قَالَ مَا خَطْبُكُمَا ۖ قَالَتَا لَا نَسْقِى حَتَّىٰ يُصْدِرَ ٱلرِّعَآءُ ۖ وَأَبُونَا شَيْخٌۭ كَبِيرٌۭ', 'ولما ورد ماء مدين وجد عليه أمة من الناس يسقون ووجد من دونهم امرأتين تذودان  قال ما خطبكما  قالتا لا نسقى حتى يصدر الرعاء  وأبونا شيخ كبير', NULL, 388, 'local:hafs-text.json'),
  ('hafs-28-24', 'hafs', 28, 24, 'فَسَقَىٰ لَهُمَا ثُمَّ تَوَلَّىٰٓ إِلَى ٱلظِّلِّ فَقَالَ رَبِّ إِنِّى لِمَآ أَنزَلْتَ إِلَىَّ مِنْ خَيْرٍۢ فَقِيرٌۭ', 'فسقى لهما ثم تولى إلى الظل فقال رب إنى لما أنزلت إلى من خير فقير', NULL, 388, 'local:hafs-text.json'),
  ('hafs-28-25', 'hafs', 28, 25, 'فَجَآءَتْهُ إِحْدَىٰهُمَا تَمْشِى عَلَى ٱسْتِحْيَآءٍۢ قَالَتْ إِنَّ أَبِى يَدْعُوكَ لِيَجْزِيَكَ أَجْرَ مَا سَقَيْتَ لَنَا ۚ فَلَمَّا جَآءَهُۥ وَقَصَّ عَلَيْهِ ٱلْقَصَصَ قَالَ لَا تَخَفْ ۖ نَجَوْتَ مِنَ ٱلْقَوْمِ ٱلظَّٰلِمِينَ', 'فجاءته إحدىهما تمشى على استحياء قالت إن أبى يدعوك ليجزيك أجر ما سقيت لنا  فلما جاءه وقص عليه القصص قال لا تخف  نجوت من القوم الظلمين', NULL, 388, 'local:hafs-text.json'),
  ('hafs-28-26', 'hafs', 28, 26, 'قَالَتْ إِحْدَىٰهُمَا يَٰٓأَبَتِ ٱسْتَـْٔجِرْهُ ۖ إِنَّ خَيْرَ مَنِ ٱسْتَـْٔجَرْتَ ٱلْقَوِىُّ ٱلْأَمِينُ', 'قالت إحدىهما يأبت استجره  إن خير من استجرت القوى الأمين', NULL, 388, 'local:hafs-text.json'),
  ('hafs-28-27', 'hafs', 28, 27, 'قَالَ إِنِّىٓ أُرِيدُ أَنْ أُنكِحَكَ إِحْدَى ٱبْنَتَىَّ هَٰتَيْنِ عَلَىٰٓ أَن تَأْجُرَنِى ثَمَٰنِىَ حِجَجٍۢ ۖ فَإِنْ أَتْمَمْتَ عَشْرًۭا فَمِنْ عِندِكَ ۖ وَمَآ أُرِيدُ أَنْ أَشُقَّ عَلَيْكَ ۚ سَتَجِدُنِىٓ إِن شَآءَ ٱللَّهُ مِنَ ٱلصَّٰلِحِينَ', 'قال إنى أريد أن أنكحك إحدى ابنتى هتين على أن تأجرنى ثمنى حجج  فإن أتممت عشرا فمن عندك  وما أريد أن أشق عليك  ستجدنى إن شاء الله من الصلحين', NULL, 388, 'local:hafs-text.json'),
  ('hafs-28-28', 'hafs', 28, 28, 'قَالَ ذَٰلِكَ بَيْنِى وَبَيْنَكَ ۖ أَيَّمَا ٱلْأَجَلَيْنِ قَضَيْتُ فَلَا عُدْوَٰنَ عَلَىَّ ۖ وَٱللَّهُ عَلَىٰ مَا نَقُولُ وَكِيلٌۭ', 'قال ذلك بينى وبينك  أيما الأجلين قضيت فلا عدون على  والله على ما نقول وكيل', NULL, 388, 'local:hafs-text.json'),
  ('hafs-28-29', 'hafs', 28, 29, '۞ فَلَمَّا قَضَىٰ مُوسَى ٱلْأَجَلَ وَسَارَ بِأَهْلِهِۦٓ ءَانَسَ مِن جَانِبِ ٱلطُّورِ نَارًۭا قَالَ لِأَهْلِهِ ٱمْكُثُوٓا۟ إِنِّىٓ ءَانَسْتُ نَارًۭا لَّعَلِّىٓ ءَاتِيكُم مِّنْهَا بِخَبَرٍ أَوْ جَذْوَةٍۢ مِّنَ ٱلنَّارِ لَعَلَّكُمْ تَصْطَلُونَ', 'فلما قضى موسى الأجل وسار بأهله ءانس من جانب الطور نارا قال لأهله امكثوا إنى ءانست نارا لعلى ءاتيكم منها بخبر أو جذوة من النار لعلكم تصطلون', NULL, 389, 'local:hafs-text.json'),
  ('hafs-28-30', 'hafs', 28, 30, 'فَلَمَّآ أَتَىٰهَا نُودِىَ مِن شَٰطِئِ ٱلْوَادِ ٱلْأَيْمَنِ فِى ٱلْبُقْعَةِ ٱلْمُبَٰرَكَةِ مِنَ ٱلشَّجَرَةِ أَن يَٰمُوسَىٰٓ إِنِّىٓ أَنَا ٱللَّهُ رَبُّ ٱلْعَٰلَمِينَ', 'فلما أتىها نودى من شطئ الواد الأيمن فى البقعة المبركة من الشجرة أن يموسى إنى أنا الله رب العلمين', NULL, 389, 'local:hafs-text.json'),
  ('hafs-28-31', 'hafs', 28, 31, 'وَأَنْ أَلْقِ عَصَاكَ ۖ فَلَمَّا رَءَاهَا تَهْتَزُّ كَأَنَّهَا جَآنٌّۭ وَلَّىٰ مُدْبِرًۭا وَلَمْ يُعَقِّبْ ۚ يَٰمُوسَىٰٓ أَقْبِلْ وَلَا تَخَفْ ۖ إِنَّكَ مِنَ ٱلْءَامِنِينَ', 'وأن ألق عصاك  فلما رءاها تهتز كأنها جان ولى مدبرا ولم يعقب  يموسى أقبل ولا تخف  إنك من الءامنين', NULL, 389, 'local:hafs-text.json'),
  ('hafs-28-32', 'hafs', 28, 32, 'ٱسْلُكْ يَدَكَ فِى جَيْبِكَ تَخْرُجْ بَيْضَآءَ مِنْ غَيْرِ سُوٓءٍۢ وَٱضْمُمْ إِلَيْكَ جَنَاحَكَ مِنَ ٱلرَّهْبِ ۖ فَذَٰنِكَ بُرْهَٰنَانِ مِن رَّبِّكَ إِلَىٰ فِرْعَوْنَ وَمَلَإِي۟هِۦٓ ۚ إِنَّهُمْ كَانُوا۟ قَوْمًۭا فَٰسِقِينَ', 'اسلك يدك فى جيبك تخرج بيضاء من غير سوء واضمم إليك جناحك من الرهب  فذنك برهنان من ربك إلى فرعون وملإيه  إنهم كانوا قوما فسقين', NULL, 389, 'local:hafs-text.json'),
  ('hafs-28-33', 'hafs', 28, 33, 'قَالَ رَبِّ إِنِّى قَتَلْتُ مِنْهُمْ نَفْسًۭا فَأَخَافُ أَن يَقْتُلُونِ', 'قال رب إنى قتلت منهم نفسا فأخاف أن يقتلون', NULL, 389, 'local:hafs-text.json'),
  ('hafs-28-34', 'hafs', 28, 34, 'وَأَخِى هَٰرُونُ هُوَ أَفْصَحُ مِنِّى لِسَانًۭا فَأَرْسِلْهُ مَعِىَ رِدْءًۭا يُصَدِّقُنِىٓ ۖ إِنِّىٓ أَخَافُ أَن يُكَذِّبُونِ', 'وأخى هرون هو أفصح منى لسانا فأرسله معى ردءا يصدقنى  إنى أخاف أن يكذبون', NULL, 389, 'local:hafs-text.json'),
  ('hafs-28-35', 'hafs', 28, 35, 'قَالَ سَنَشُدُّ عَضُدَكَ بِأَخِيكَ وَنَجْعَلُ لَكُمَا سُلْطَٰنًۭا فَلَا يَصِلُونَ إِلَيْكُمَا ۚ بِـَٔايَٰتِنَآ أَنتُمَا وَمَنِ ٱتَّبَعَكُمَا ٱلْغَٰلِبُونَ', 'قال سنشد عضدك بأخيك ونجعل لكما سلطنا فلا يصلون إليكما  بايتنا أنتما ومن اتبعكما الغلبون', NULL, 389, 'local:hafs-text.json'),
  ('hafs-28-36', 'hafs', 28, 36, 'فَلَمَّا جَآءَهُم مُّوسَىٰ بِـَٔايَٰتِنَا بَيِّنَٰتٍۢ قَالُوا۟ مَا هَٰذَآ إِلَّا سِحْرٌۭ مُّفْتَرًۭى وَمَا سَمِعْنَا بِهَٰذَا فِىٓ ءَابَآئِنَا ٱلْأَوَّلِينَ', 'فلما جاءهم موسى بايتنا بينت قالوا ما هذا إلا سحر مفترى وما سمعنا بهذا فى ءابائنا الأولين', NULL, 390, 'local:hafs-text.json'),
  ('hafs-28-37', 'hafs', 28, 37, 'وَقَالَ مُوسَىٰ رَبِّىٓ أَعْلَمُ بِمَن جَآءَ بِٱلْهُدَىٰ مِنْ عِندِهِۦ وَمَن تَكُونُ لَهُۥ عَٰقِبَةُ ٱلدَّارِ ۖ إِنَّهُۥ لَا يُفْلِحُ ٱلظَّٰلِمُونَ', 'وقال موسى ربى أعلم بمن جاء بالهدى من عنده ومن تكون له عقبة الدار  إنه لا يفلح الظلمون', NULL, 390, 'local:hafs-text.json'),
  ('hafs-28-38', 'hafs', 28, 38, 'وَقَالَ فِرْعَوْنُ يَٰٓأَيُّهَا ٱلْمَلَأُ مَا عَلِمْتُ لَكُم مِّنْ إِلَٰهٍ غَيْرِى فَأَوْقِدْ لِى يَٰهَٰمَٰنُ عَلَى ٱلطِّينِ فَٱجْعَل لِّى صَرْحًۭا لَّعَلِّىٓ أَطَّلِعُ إِلَىٰٓ إِلَٰهِ مُوسَىٰ وَإِنِّى لَأَظُنُّهُۥ مِنَ ٱلْكَٰذِبِينَ', 'وقال فرعون يأيها الملأ ما علمت لكم من إله غيرى فأوقد لى يهمن على الطين فاجعل لى صرحا لعلى أطلع إلى إله موسى وإنى لأظنه من الكذبين', NULL, 390, 'local:hafs-text.json'),
  ('hafs-28-39', 'hafs', 28, 39, 'وَٱسْتَكْبَرَ هُوَ وَجُنُودُهُۥ فِى ٱلْأَرْضِ بِغَيْرِ ٱلْحَقِّ وَظَنُّوٓا۟ أَنَّهُمْ إِلَيْنَا لَا يُرْجَعُونَ', 'واستكبر هو وجنوده فى الأرض بغير الحق وظنوا أنهم إلينا لا يرجعون', NULL, 390, 'local:hafs-text.json'),
  ('hafs-28-40', 'hafs', 28, 40, 'فَأَخَذْنَٰهُ وَجُنُودَهُۥ فَنَبَذْنَٰهُمْ فِى ٱلْيَمِّ ۖ فَٱنظُرْ كَيْفَ كَانَ عَٰقِبَةُ ٱلظَّٰلِمِينَ', 'فأخذنه وجنوده فنبذنهم فى اليم  فانظر كيف كان عقبة الظلمين', NULL, 390, 'local:hafs-text.json'),
  ('hafs-28-41', 'hafs', 28, 41, 'وَجَعَلْنَٰهُمْ أَئِمَّةًۭ يَدْعُونَ إِلَى ٱلنَّارِ ۖ وَيَوْمَ ٱلْقِيَٰمَةِ لَا يُنصَرُونَ', 'وجعلنهم أئمة يدعون إلى النار  ويوم القيمة لا ينصرون', NULL, 390, 'local:hafs-text.json'),
  ('hafs-28-42', 'hafs', 28, 42, 'وَأَتْبَعْنَٰهُمْ فِى هَٰذِهِ ٱلدُّنْيَا لَعْنَةًۭ ۖ وَيَوْمَ ٱلْقِيَٰمَةِ هُم مِّنَ ٱلْمَقْبُوحِينَ', 'وأتبعنهم فى هذه الدنيا لعنة  ويوم القيمة هم من المقبوحين', NULL, 390, 'local:hafs-text.json'),
  ('hafs-28-43', 'hafs', 28, 43, 'وَلَقَدْ ءَاتَيْنَا مُوسَى ٱلْكِتَٰبَ مِنۢ بَعْدِ مَآ أَهْلَكْنَا ٱلْقُرُونَ ٱلْأُولَىٰ بَصَآئِرَ لِلنَّاسِ وَهُدًۭى وَرَحْمَةًۭ لَّعَلَّهُمْ يَتَذَكَّرُونَ', 'ولقد ءاتينا موسى الكتب من بعد ما أهلكنا القرون الأولى بصائر للناس وهدى ورحمة لعلهم يتذكرون', NULL, 390, 'local:hafs-text.json'),
  ('hafs-28-44', 'hafs', 28, 44, 'وَمَا كُنتَ بِجَانِبِ ٱلْغَرْبِىِّ إِذْ قَضَيْنَآ إِلَىٰ مُوسَى ٱلْأَمْرَ وَمَا كُنتَ مِنَ ٱلشَّٰهِدِينَ', 'وما كنت بجانب الغربى إذ قضينا إلى موسى الأمر وما كنت من الشهدين', NULL, 391, 'local:hafs-text.json'),
  ('hafs-28-45', 'hafs', 28, 45, 'وَلَٰكِنَّآ أَنشَأْنَا قُرُونًۭا فَتَطَاوَلَ عَلَيْهِمُ ٱلْعُمُرُ ۚ وَمَا كُنتَ ثَاوِيًۭا فِىٓ أَهْلِ مَدْيَنَ تَتْلُوا۟ عَلَيْهِمْ ءَايَٰتِنَا وَلَٰكِنَّا كُنَّا مُرْسِلِينَ', 'ولكنا أنشأنا قرونا فتطاول عليهم العمر  وما كنت ثاويا فى أهل مدين تتلوا عليهم ءايتنا ولكنا كنا مرسلين', NULL, 391, 'local:hafs-text.json'),
  ('hafs-28-46', 'hafs', 28, 46, 'وَمَا كُنتَ بِجَانِبِ ٱلطُّورِ إِذْ نَادَيْنَا وَلَٰكِن رَّحْمَةًۭ مِّن رَّبِّكَ لِتُنذِرَ قَوْمًۭا مَّآ أَتَىٰهُم مِّن نَّذِيرٍۢ مِّن قَبْلِكَ لَعَلَّهُمْ يَتَذَكَّرُونَ', 'وما كنت بجانب الطور إذ نادينا ولكن رحمة من ربك لتنذر قوما ما أتىهم من نذير من قبلك لعلهم يتذكرون', NULL, 391, 'local:hafs-text.json'),
  ('hafs-28-47', 'hafs', 28, 47, 'وَلَوْلَآ أَن تُصِيبَهُم مُّصِيبَةٌۢ بِمَا قَدَّمَتْ أَيْدِيهِمْ فَيَقُولُوا۟ رَبَّنَا لَوْلَآ أَرْسَلْتَ إِلَيْنَا رَسُولًۭا فَنَتَّبِعَ ءَايَٰتِكَ وَنَكُونَ مِنَ ٱلْمُؤْمِنِينَ', 'ولولا أن تصيبهم مصيبة بما قدمت أيديهم فيقولوا ربنا لولا أرسلت إلينا رسولا فنتبع ءايتك ونكون من المؤمنين', NULL, 391, 'local:hafs-text.json'),
  ('hafs-28-48', 'hafs', 28, 48, 'فَلَمَّا جَآءَهُمُ ٱلْحَقُّ مِنْ عِندِنَا قَالُوا۟ لَوْلَآ أُوتِىَ مِثْلَ مَآ أُوتِىَ مُوسَىٰٓ ۚ أَوَلَمْ يَكْفُرُوا۟ بِمَآ أُوتِىَ مُوسَىٰ مِن قَبْلُ ۖ قَالُوا۟ سِحْرَانِ تَظَٰهَرَا وَقَالُوٓا۟ إِنَّا بِكُلٍّۢ كَٰفِرُونَ', 'فلما جاءهم الحق من عندنا قالوا لولا أوتى مثل ما أوتى موسى  أولم يكفروا بما أوتى موسى من قبل  قالوا سحران تظهرا وقالوا إنا بكل كفرون', NULL, 391, 'local:hafs-text.json'),
  ('hafs-28-49', 'hafs', 28, 49, 'قُلْ فَأْتُوا۟ بِكِتَٰبٍۢ مِّنْ عِندِ ٱللَّهِ هُوَ أَهْدَىٰ مِنْهُمَآ أَتَّبِعْهُ إِن كُنتُمْ صَٰدِقِينَ', 'قل فأتوا بكتب من عند الله هو أهدى منهما أتبعه إن كنتم صدقين', NULL, 391, 'local:hafs-text.json'),
  ('hafs-28-50', 'hafs', 28, 50, 'فَإِن لَّمْ يَسْتَجِيبُوا۟ لَكَ فَٱعْلَمْ أَنَّمَا يَتَّبِعُونَ أَهْوَآءَهُمْ ۚ وَمَنْ أَضَلُّ مِمَّنِ ٱتَّبَعَ هَوَىٰهُ بِغَيْرِ هُدًۭى مِّنَ ٱللَّهِ ۚ إِنَّ ٱللَّهَ لَا يَهْدِى ٱلْقَوْمَ ٱلظَّٰلِمِينَ', 'فإن لم يستجيبوا لك فاعلم أنما يتبعون أهواءهم  ومن أضل ممن اتبع هوىه بغير هدى من الله  إن الله لا يهدى القوم الظلمين', NULL, 391, 'local:hafs-text.json'),
  ('hafs-28-51', 'hafs', 28, 51, '۞ وَلَقَدْ وَصَّلْنَا لَهُمُ ٱلْقَوْلَ لَعَلَّهُمْ يَتَذَكَّرُونَ', 'ولقد وصلنا لهم القول لعلهم يتذكرون', NULL, 392, 'local:hafs-text.json'),
  ('hafs-28-52', 'hafs', 28, 52, 'ٱلَّذِينَ ءَاتَيْنَٰهُمُ ٱلْكِتَٰبَ مِن قَبْلِهِۦ هُم بِهِۦ يُؤْمِنُونَ', 'الذين ءاتينهم الكتب من قبله هم به يؤمنون', NULL, 392, 'local:hafs-text.json'),
  ('hafs-28-53', 'hafs', 28, 53, 'وَإِذَا يُتْلَىٰ عَلَيْهِمْ قَالُوٓا۟ ءَامَنَّا بِهِۦٓ إِنَّهُ ٱلْحَقُّ مِن رَّبِّنَآ إِنَّا كُنَّا مِن قَبْلِهِۦ مُسْلِمِينَ', 'وإذا يتلى عليهم قالوا ءامنا به إنه الحق من ربنا إنا كنا من قبله مسلمين', NULL, 392, 'local:hafs-text.json'),
  ('hafs-28-54', 'hafs', 28, 54, 'أُو۟لَٰٓئِكَ يُؤْتَوْنَ أَجْرَهُم مَّرَّتَيْنِ بِمَا صَبَرُوا۟ وَيَدْرَءُونَ بِٱلْحَسَنَةِ ٱلسَّيِّئَةَ وَمِمَّا رَزَقْنَٰهُمْ يُنفِقُونَ', 'أولئك يؤتون أجرهم مرتين بما صبروا ويدرءون بالحسنة السيئة ومما رزقنهم ينفقون', NULL, 392, 'local:hafs-text.json'),
  ('hafs-28-55', 'hafs', 28, 55, 'وَإِذَا سَمِعُوا۟ ٱللَّغْوَ أَعْرَضُوا۟ عَنْهُ وَقَالُوا۟ لَنَآ أَعْمَٰلُنَا وَلَكُمْ أَعْمَٰلُكُمْ سَلَٰمٌ عَلَيْكُمْ لَا نَبْتَغِى ٱلْجَٰهِلِينَ', 'وإذا سمعوا اللغو أعرضوا عنه وقالوا لنا أعملنا ولكم أعملكم سلم عليكم لا نبتغى الجهلين', NULL, 392, 'local:hafs-text.json'),
  ('hafs-28-56', 'hafs', 28, 56, 'إِنَّكَ لَا تَهْدِى مَنْ أَحْبَبْتَ وَلَٰكِنَّ ٱللَّهَ يَهْدِى مَن يَشَآءُ ۚ وَهُوَ أَعْلَمُ بِٱلْمُهْتَدِينَ', 'إنك لا تهدى من أحببت ولكن الله يهدى من يشاء  وهو أعلم بالمهتدين', NULL, 392, 'local:hafs-text.json'),
  ('hafs-28-57', 'hafs', 28, 57, 'وَقَالُوٓا۟ إِن نَّتَّبِعِ ٱلْهُدَىٰ مَعَكَ نُتَخَطَّفْ مِنْ أَرْضِنَآ ۚ أَوَلَمْ نُمَكِّن لَّهُمْ حَرَمًا ءَامِنًۭا يُجْبَىٰٓ إِلَيْهِ ثَمَرَٰتُ كُلِّ شَىْءٍۢ رِّزْقًۭا مِّن لَّدُنَّا وَلَٰكِنَّ أَكْثَرَهُمْ لَا يَعْلَمُونَ', 'وقالوا إن نتبع الهدى معك نتخطف من أرضنا  أولم نمكن لهم حرما ءامنا يجبى إليه ثمرت كل شىء رزقا من لدنا ولكن أكثرهم لا يعلمون', NULL, 392, 'local:hafs-text.json'),
  ('hafs-28-58', 'hafs', 28, 58, 'وَكَمْ أَهْلَكْنَا مِن قَرْيَةٍۭ بَطِرَتْ مَعِيشَتَهَا ۖ فَتِلْكَ مَسَٰكِنُهُمْ لَمْ تُسْكَن مِّنۢ بَعْدِهِمْ إِلَّا قَلِيلًۭا ۖ وَكُنَّا نَحْنُ ٱلْوَٰرِثِينَ', 'وكم أهلكنا من قرية بطرت معيشتها  فتلك مسكنهم لم تسكن من بعدهم إلا قليلا  وكنا نحن الورثين', NULL, 392, 'local:hafs-text.json'),
  ('hafs-28-59', 'hafs', 28, 59, 'وَمَا كَانَ رَبُّكَ مُهْلِكَ ٱلْقُرَىٰ حَتَّىٰ يَبْعَثَ فِىٓ أُمِّهَا رَسُولًۭا يَتْلُوا۟ عَلَيْهِمْ ءَايَٰتِنَا ۚ وَمَا كُنَّا مُهْلِكِى ٱلْقُرَىٰٓ إِلَّا وَأَهْلُهَا ظَٰلِمُونَ', 'وما كان ربك مهلك القرى حتى يبعث فى أمها رسولا يتلوا عليهم ءايتنا  وما كنا مهلكى القرى إلا وأهلها ظلمون', NULL, 392, 'local:hafs-text.json'),
  ('hafs-28-60', 'hafs', 28, 60, 'وَمَآ أُوتِيتُم مِّن شَىْءٍۢ فَمَتَٰعُ ٱلْحَيَوٰةِ ٱلدُّنْيَا وَزِينَتُهَا ۚ وَمَا عِندَ ٱللَّهِ خَيْرٌۭ وَأَبْقَىٰٓ ۚ أَفَلَا تَعْقِلُونَ', 'وما أوتيتم من شىء فمتع الحيوة الدنيا وزينتها  وما عند الله خير وأبقى  أفلا تعقلون', NULL, 393, 'local:hafs-text.json'),
  ('hafs-28-61', 'hafs', 28, 61, 'أَفَمَن وَعَدْنَٰهُ وَعْدًا حَسَنًۭا فَهُوَ لَٰقِيهِ كَمَن مَّتَّعْنَٰهُ مَتَٰعَ ٱلْحَيَوٰةِ ٱلدُّنْيَا ثُمَّ هُوَ يَوْمَ ٱلْقِيَٰمَةِ مِنَ ٱلْمُحْضَرِينَ', 'أفمن وعدنه وعدا حسنا فهو لقيه كمن متعنه متع الحيوة الدنيا ثم هو يوم القيمة من المحضرين', NULL, 393, 'local:hafs-text.json'),
  ('hafs-28-62', 'hafs', 28, 62, 'وَيَوْمَ يُنَادِيهِمْ فَيَقُولُ أَيْنَ شُرَكَآءِىَ ٱلَّذِينَ كُنتُمْ تَزْعُمُونَ', 'ويوم يناديهم فيقول أين شركاءى الذين كنتم تزعمون', NULL, 393, 'local:hafs-text.json'),
  ('hafs-28-63', 'hafs', 28, 63, 'قَالَ ٱلَّذِينَ حَقَّ عَلَيْهِمُ ٱلْقَوْلُ رَبَّنَا هَٰٓؤُلَآءِ ٱلَّذِينَ أَغْوَيْنَآ أَغْوَيْنَٰهُمْ كَمَا غَوَيْنَا ۖ تَبَرَّأْنَآ إِلَيْكَ ۖ مَا كَانُوٓا۟ إِيَّانَا يَعْبُدُونَ', 'قال الذين حق عليهم القول ربنا هؤلاء الذين أغوينا أغوينهم كما غوينا  تبرأنا إليك  ما كانوا إيانا يعبدون', NULL, 393, 'local:hafs-text.json'),
  ('hafs-28-64', 'hafs', 28, 64, 'وَقِيلَ ٱدْعُوا۟ شُرَكَآءَكُمْ فَدَعَوْهُمْ فَلَمْ يَسْتَجِيبُوا۟ لَهُمْ وَرَأَوُا۟ ٱلْعَذَابَ ۚ لَوْ أَنَّهُمْ كَانُوا۟ يَهْتَدُونَ', 'وقيل ادعوا شركاءكم فدعوهم فلم يستجيبوا لهم ورأوا العذاب  لو أنهم كانوا يهتدون', NULL, 393, 'local:hafs-text.json'),
  ('hafs-28-65', 'hafs', 28, 65, 'وَيَوْمَ يُنَادِيهِمْ فَيَقُولُ مَاذَآ أَجَبْتُمُ ٱلْمُرْسَلِينَ', 'ويوم يناديهم فيقول ماذا أجبتم المرسلين', NULL, 393, 'local:hafs-text.json'),
  ('hafs-28-66', 'hafs', 28, 66, 'فَعَمِيَتْ عَلَيْهِمُ ٱلْأَنۢبَآءُ يَوْمَئِذٍۢ فَهُمْ لَا يَتَسَآءَلُونَ', 'فعميت عليهم الأنباء يومئذ فهم لا يتساءلون', NULL, 393, 'local:hafs-text.json'),
  ('hafs-28-67', 'hafs', 28, 67, 'فَأَمَّا مَن تَابَ وَءَامَنَ وَعَمِلَ صَٰلِحًۭا فَعَسَىٰٓ أَن يَكُونَ مِنَ ٱلْمُفْلِحِينَ', 'فأما من تاب وءامن وعمل صلحا فعسى أن يكون من المفلحين', NULL, 393, 'local:hafs-text.json'),
  ('hafs-28-68', 'hafs', 28, 68, 'وَرَبُّكَ يَخْلُقُ مَا يَشَآءُ وَيَخْتَارُ ۗ مَا كَانَ لَهُمُ ٱلْخِيَرَةُ ۚ سُبْحَٰنَ ٱللَّهِ وَتَعَٰلَىٰ عَمَّا يُشْرِكُونَ', 'وربك يخلق ما يشاء ويختار  ما كان لهم الخيرة  سبحن الله وتعلى عما يشركون', NULL, 393, 'local:hafs-text.json'),
  ('hafs-28-69', 'hafs', 28, 69, 'وَرَبُّكَ يَعْلَمُ مَا تُكِنُّ صُدُورُهُمْ وَمَا يُعْلِنُونَ', 'وربك يعلم ما تكن صدورهم وما يعلنون', NULL, 393, 'local:hafs-text.json'),
  ('hafs-28-70', 'hafs', 28, 70, 'وَهُوَ ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَ ۖ لَهُ ٱلْحَمْدُ فِى ٱلْأُولَىٰ وَٱلْءَاخِرَةِ ۖ وَلَهُ ٱلْحُكْمُ وَإِلَيْهِ تُرْجَعُونَ', 'وهو الله لا إله إلا هو  له الحمد فى الأولى والءاخرة  وله الحكم وإليه ترجعون', NULL, 393, 'local:hafs-text.json'),
  ('hafs-28-71', 'hafs', 28, 71, 'قُلْ أَرَءَيْتُمْ إِن جَعَلَ ٱللَّهُ عَلَيْكُمُ ٱلَّيْلَ سَرْمَدًا إِلَىٰ يَوْمِ ٱلْقِيَٰمَةِ مَنْ إِلَٰهٌ غَيْرُ ٱللَّهِ يَأْتِيكُم بِضِيَآءٍ ۖ أَفَلَا تَسْمَعُونَ', 'قل أرءيتم إن جعل الله عليكم اليل سرمدا إلى يوم القيمة من إله غير الله يأتيكم بضياء  أفلا تسمعون', NULL, 394, 'local:hafs-text.json'),
  ('hafs-28-72', 'hafs', 28, 72, 'قُلْ أَرَءَيْتُمْ إِن جَعَلَ ٱللَّهُ عَلَيْكُمُ ٱلنَّهَارَ سَرْمَدًا إِلَىٰ يَوْمِ ٱلْقِيَٰمَةِ مَنْ إِلَٰهٌ غَيْرُ ٱللَّهِ يَأْتِيكُم بِلَيْلٍۢ تَسْكُنُونَ فِيهِ ۖ أَفَلَا تُبْصِرُونَ', 'قل أرءيتم إن جعل الله عليكم النهار سرمدا إلى يوم القيمة من إله غير الله يأتيكم بليل تسكنون فيه  أفلا تبصرون', NULL, 394, 'local:hafs-text.json'),
  ('hafs-28-73', 'hafs', 28, 73, 'وَمِن رَّحْمَتِهِۦ جَعَلَ لَكُمُ ٱلَّيْلَ وَٱلنَّهَارَ لِتَسْكُنُوا۟ فِيهِ وَلِتَبْتَغُوا۟ مِن فَضْلِهِۦ وَلَعَلَّكُمْ تَشْكُرُونَ', 'ومن رحمته جعل لكم اليل والنهار لتسكنوا فيه ولتبتغوا من فضله ولعلكم تشكرون', NULL, 394, 'local:hafs-text.json'),
  ('hafs-28-74', 'hafs', 28, 74, 'وَيَوْمَ يُنَادِيهِمْ فَيَقُولُ أَيْنَ شُرَكَآءِىَ ٱلَّذِينَ كُنتُمْ تَزْعُمُونَ', 'ويوم يناديهم فيقول أين شركاءى الذين كنتم تزعمون', NULL, 394, 'local:hafs-text.json'),
  ('hafs-28-75', 'hafs', 28, 75, 'وَنَزَعْنَا مِن كُلِّ أُمَّةٍۢ شَهِيدًۭا فَقُلْنَا هَاتُوا۟ بُرْهَٰنَكُمْ فَعَلِمُوٓا۟ أَنَّ ٱلْحَقَّ لِلَّهِ وَضَلَّ عَنْهُم مَّا كَانُوا۟ يَفْتَرُونَ', 'ونزعنا من كل أمة شهيدا فقلنا هاتوا برهنكم فعلموا أن الحق لله وضل عنهم ما كانوا يفترون', NULL, 394, 'local:hafs-text.json'),
  ('hafs-28-76', 'hafs', 28, 76, '۞ إِنَّ قَٰرُونَ كَانَ مِن قَوْمِ مُوسَىٰ فَبَغَىٰ عَلَيْهِمْ ۖ وَءَاتَيْنَٰهُ مِنَ ٱلْكُنُوزِ مَآ إِنَّ مَفَاتِحَهُۥ لَتَنُوٓأُ بِٱلْعُصْبَةِ أُو۟لِى ٱلْقُوَّةِ إِذْ قَالَ لَهُۥ قَوْمُهُۥ لَا تَفْرَحْ ۖ إِنَّ ٱللَّهَ لَا يُحِبُّ ٱلْفَرِحِينَ', 'إن قرون كان من قوم موسى فبغى عليهم  وءاتينه من الكنوز ما إن مفاتحه لتنوأ بالعصبة أولى القوة إذ قال له قومه لا تفرح  إن الله لا يحب الفرحين', NULL, 394, 'local:hafs-text.json'),
  ('hafs-28-77', 'hafs', 28, 77, 'وَٱبْتَغِ فِيمَآ ءَاتَىٰكَ ٱللَّهُ ٱلدَّارَ ٱلْءَاخِرَةَ ۖ وَلَا تَنسَ نَصِيبَكَ مِنَ ٱلدُّنْيَا ۖ وَأَحْسِن كَمَآ أَحْسَنَ ٱللَّهُ إِلَيْكَ ۖ وَلَا تَبْغِ ٱلْفَسَادَ فِى ٱلْأَرْضِ ۖ إِنَّ ٱللَّهَ لَا يُحِبُّ ٱلْمُفْسِدِينَ', 'وابتغ فيما ءاتىك الله الدار الءاخرة  ولا تنس نصيبك من الدنيا  وأحسن كما أحسن الله إليك  ولا تبغ الفساد فى الأرض  إن الله لا يحب المفسدين', NULL, 394, 'local:hafs-text.json'),
  ('hafs-28-78', 'hafs', 28, 78, 'قَالَ إِنَّمَآ أُوتِيتُهُۥ عَلَىٰ عِلْمٍ عِندِىٓ ۚ أَوَلَمْ يَعْلَمْ أَنَّ ٱللَّهَ قَدْ أَهْلَكَ مِن قَبْلِهِۦ مِنَ ٱلْقُرُونِ مَنْ هُوَ أَشَدُّ مِنْهُ قُوَّةًۭ وَأَكْثَرُ جَمْعًۭا ۚ وَلَا يُسْـَٔلُ عَن ذُنُوبِهِمُ ٱلْمُجْرِمُونَ', 'قال إنما أوتيته على علم عندى  أولم يعلم أن الله قد أهلك من قبله من القرون من هو أشد منه قوة وأكثر جمعا  ولا يسل عن ذنوبهم المجرمون', NULL, 395, 'local:hafs-text.json'),
  ('hafs-28-79', 'hafs', 28, 79, 'فَخَرَجَ عَلَىٰ قَوْمِهِۦ فِى زِينَتِهِۦ ۖ قَالَ ٱلَّذِينَ يُرِيدُونَ ٱلْحَيَوٰةَ ٱلدُّنْيَا يَٰلَيْتَ لَنَا مِثْلَ مَآ أُوتِىَ قَٰرُونُ إِنَّهُۥ لَذُو حَظٍّ عَظِيمٍۢ', 'فخرج على قومه فى زينته  قال الذين يريدون الحيوة الدنيا يليت لنا مثل ما أوتى قرون إنه لذو حظ عظيم', NULL, 395, 'local:hafs-text.json'),
  ('hafs-28-80', 'hafs', 28, 80, 'وَقَالَ ٱلَّذِينَ أُوتُوا۟ ٱلْعِلْمَ وَيْلَكُمْ ثَوَابُ ٱللَّهِ خَيْرٌۭ لِّمَنْ ءَامَنَ وَعَمِلَ صَٰلِحًۭا وَلَا يُلَقَّىٰهَآ إِلَّا ٱلصَّٰبِرُونَ', 'وقال الذين أوتوا العلم ويلكم ثواب الله خير لمن ءامن وعمل صلحا ولا يلقىها إلا الصبرون', NULL, 395, 'local:hafs-text.json'),
  ('hafs-28-81', 'hafs', 28, 81, 'فَخَسَفْنَا بِهِۦ وَبِدَارِهِ ٱلْأَرْضَ فَمَا كَانَ لَهُۥ مِن فِئَةٍۢ يَنصُرُونَهُۥ مِن دُونِ ٱللَّهِ وَمَا كَانَ مِنَ ٱلْمُنتَصِرِينَ', 'فخسفنا به وبداره الأرض فما كان له من فئة ينصرونه من دون الله وما كان من المنتصرين', NULL, 395, 'local:hafs-text.json'),
  ('hafs-28-82', 'hafs', 28, 82, 'وَأَصْبَحَ ٱلَّذِينَ تَمَنَّوْا۟ مَكَانَهُۥ بِٱلْأَمْسِ يَقُولُونَ وَيْكَأَنَّ ٱللَّهَ يَبْسُطُ ٱلرِّزْقَ لِمَن يَشَآءُ مِنْ عِبَادِهِۦ وَيَقْدِرُ ۖ لَوْلَآ أَن مَّنَّ ٱللَّهُ عَلَيْنَا لَخَسَفَ بِنَا ۖ وَيْكَأَنَّهُۥ لَا يُفْلِحُ ٱلْكَٰفِرُونَ', 'وأصبح الذين تمنوا مكانه بالأمس يقولون ويكأن الله يبسط الرزق لمن يشاء من عباده ويقدر  لولا أن من الله علينا لخسف بنا  ويكأنه لا يفلح الكفرون', NULL, 395, 'local:hafs-text.json'),
  ('hafs-28-83', 'hafs', 28, 83, 'تِلْكَ ٱلدَّارُ ٱلْءَاخِرَةُ نَجْعَلُهَا لِلَّذِينَ لَا يُرِيدُونَ عُلُوًّۭا فِى ٱلْأَرْضِ وَلَا فَسَادًۭا ۚ وَٱلْعَٰقِبَةُ لِلْمُتَّقِينَ', 'تلك الدار الءاخرة نجعلها للذين لا يريدون علوا فى الأرض ولا فسادا  والعقبة للمتقين', NULL, 395, 'local:hafs-text.json'),
  ('hafs-28-84', 'hafs', 28, 84, 'مَن جَآءَ بِٱلْحَسَنَةِ فَلَهُۥ خَيْرٌۭ مِّنْهَا ۖ وَمَن جَآءَ بِٱلسَّيِّئَةِ فَلَا يُجْزَى ٱلَّذِينَ عَمِلُوا۟ ٱلسَّيِّـَٔاتِ إِلَّا مَا كَانُوا۟ يَعْمَلُونَ', 'من جاء بالحسنة فله خير منها  ومن جاء بالسيئة فلا يجزى الذين عملوا السيات إلا ما كانوا يعملون', NULL, 395, 'local:hafs-text.json'),
  ('hafs-28-85', 'hafs', 28, 85, 'إِنَّ ٱلَّذِى فَرَضَ عَلَيْكَ ٱلْقُرْءَانَ لَرَآدُّكَ إِلَىٰ مَعَادٍۢ ۚ قُل رَّبِّىٓ أَعْلَمُ مَن جَآءَ بِٱلْهُدَىٰ وَمَنْ هُوَ فِى ضَلَٰلٍۢ مُّبِينٍۢ', 'إن الذى فرض عليك القرءان لرادك إلى معاد  قل ربى أعلم من جاء بالهدى ومن هو فى ضلل مبين', NULL, 396, 'local:hafs-text.json'),
  ('hafs-28-86', 'hafs', 28, 86, 'وَمَا كُنتَ تَرْجُوٓا۟ أَن يُلْقَىٰٓ إِلَيْكَ ٱلْكِتَٰبُ إِلَّا رَحْمَةًۭ مِّن رَّبِّكَ ۖ فَلَا تَكُونَنَّ ظَهِيرًۭا لِّلْكَٰفِرِينَ', 'وما كنت ترجوا أن يلقى إليك الكتب إلا رحمة من ربك  فلا تكونن ظهيرا للكفرين', NULL, 396, 'local:hafs-text.json'),
  ('hafs-28-87', 'hafs', 28, 87, 'وَلَا يَصُدُّنَّكَ عَنْ ءَايَٰتِ ٱللَّهِ بَعْدَ إِذْ أُنزِلَتْ إِلَيْكَ ۖ وَٱدْعُ إِلَىٰ رَبِّكَ ۖ وَلَا تَكُونَنَّ مِنَ ٱلْمُشْرِكِينَ', 'ولا يصدنك عن ءايت الله بعد إذ أنزلت إليك  وادع إلى ربك  ولا تكونن من المشركين', NULL, 396, 'local:hafs-text.json'),
  ('hafs-28-88', 'hafs', 28, 88, 'وَلَا تَدْعُ مَعَ ٱللَّهِ إِلَٰهًا ءَاخَرَ ۘ لَآ إِلَٰهَ إِلَّا هُوَ ۚ كُلُّ شَىْءٍ هَالِكٌ إِلَّا وَجْهَهُۥ ۚ لَهُ ٱلْحُكْمُ وَإِلَيْهِ تُرْجَعُونَ', 'ولا تدع مع الله إلها ءاخر  لا إله إلا هو  كل شىء هالك إلا وجهه  له الحكم وإليه ترجعون', NULL, 396, 'local:hafs-text.json'),
  ('hafs-29-1', 'hafs', 29, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ الٓمٓ', 'بسم الله الرحمن الرحيم الم', NULL, 396, 'local:hafs-text.json'),
  ('hafs-29-2', 'hafs', 29, 2, 'أَحَسِبَ ٱلنَّاسُ أَن يُتْرَكُوٓا۟ أَن يَقُولُوٓا۟ ءَامَنَّا وَهُمْ لَا يُفْتَنُونَ', 'أحسب الناس أن يتركوا أن يقولوا ءامنا وهم لا يفتنون', NULL, 396, 'local:hafs-text.json'),
  ('hafs-29-3', 'hafs', 29, 3, 'وَلَقَدْ فَتَنَّا ٱلَّذِينَ مِن قَبْلِهِمْ ۖ فَلَيَعْلَمَنَّ ٱللَّهُ ٱلَّذِينَ صَدَقُوا۟ وَلَيَعْلَمَنَّ ٱلْكَٰذِبِينَ', 'ولقد فتنا الذين من قبلهم  فليعلمن الله الذين صدقوا وليعلمن الكذبين', NULL, 396, 'local:hafs-text.json'),
  ('hafs-29-4', 'hafs', 29, 4, 'أَمْ حَسِبَ ٱلَّذِينَ يَعْمَلُونَ ٱلسَّيِّـَٔاتِ أَن يَسْبِقُونَا ۚ سَآءَ مَا يَحْكُمُونَ', 'أم حسب الذين يعملون السيات أن يسبقونا  ساء ما يحكمون', NULL, 396, 'local:hafs-text.json'),
  ('hafs-29-5', 'hafs', 29, 5, 'مَن كَانَ يَرْجُوا۟ لِقَآءَ ٱللَّهِ فَإِنَّ أَجَلَ ٱللَّهِ لَءَاتٍۢ ۚ وَهُوَ ٱلسَّمِيعُ ٱلْعَلِيمُ', 'من كان يرجوا لقاء الله فإن أجل الله لءات  وهو السميع العليم', NULL, 396, 'local:hafs-text.json'),
  ('hafs-29-6', 'hafs', 29, 6, 'وَمَن جَٰهَدَ فَإِنَّمَا يُجَٰهِدُ لِنَفْسِهِۦٓ ۚ إِنَّ ٱللَّهَ لَغَنِىٌّ عَنِ ٱلْعَٰلَمِينَ', 'ومن جهد فإنما يجهد لنفسه  إن الله لغنى عن العلمين', NULL, 396, 'local:hafs-text.json'),
  ('hafs-29-7', 'hafs', 29, 7, 'وَٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ لَنُكَفِّرَنَّ عَنْهُمْ سَيِّـَٔاتِهِمْ وَلَنَجْزِيَنَّهُمْ أَحْسَنَ ٱلَّذِى كَانُوا۟ يَعْمَلُونَ', 'والذين ءامنوا وعملوا الصلحت لنكفرن عنهم سياتهم ولنجزينهم أحسن الذى كانوا يعملون', NULL, 397, 'local:hafs-text.json'),
  ('hafs-29-8', 'hafs', 29, 8, 'وَوَصَّيْنَا ٱلْإِنسَٰنَ بِوَٰلِدَيْهِ حُسْنًۭا ۖ وَإِن جَٰهَدَاكَ لِتُشْرِكَ بِى مَا لَيْسَ لَكَ بِهِۦ عِلْمٌۭ فَلَا تُطِعْهُمَآ ۚ إِلَىَّ مَرْجِعُكُمْ فَأُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ', 'ووصينا الإنسن بولديه حسنا  وإن جهداك لتشرك بى ما ليس لك به علم فلا تطعهما  إلى مرجعكم فأنبئكم بما كنتم تعملون', NULL, 397, 'local:hafs-text.json'),
  ('hafs-29-9', 'hafs', 29, 9, 'وَٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ لَنُدْخِلَنَّهُمْ فِى ٱلصَّٰلِحِينَ', 'والذين ءامنوا وعملوا الصلحت لندخلنهم فى الصلحين', NULL, 397, 'local:hafs-text.json'),
  ('hafs-29-10', 'hafs', 29, 10, 'وَمِنَ ٱلنَّاسِ مَن يَقُولُ ءَامَنَّا بِٱللَّهِ فَإِذَآ أُوذِىَ فِى ٱللَّهِ جَعَلَ فِتْنَةَ ٱلنَّاسِ كَعَذَابِ ٱللَّهِ وَلَئِن جَآءَ نَصْرٌۭ مِّن رَّبِّكَ لَيَقُولُنَّ إِنَّا كُنَّا مَعَكُمْ ۚ أَوَلَيْسَ ٱللَّهُ بِأَعْلَمَ بِمَا فِى صُدُورِ ٱلْعَٰلَمِينَ', 'ومن الناس من يقول ءامنا بالله فإذا أوذى فى الله جعل فتنة الناس كعذاب الله ولئن جاء نصر من ربك ليقولن إنا كنا معكم  أوليس الله بأعلم بما فى صدور العلمين', NULL, 397, 'local:hafs-text.json'),
  ('hafs-29-11', 'hafs', 29, 11, 'وَلَيَعْلَمَنَّ ٱللَّهُ ٱلَّذِينَ ءَامَنُوا۟ وَلَيَعْلَمَنَّ ٱلْمُنَٰفِقِينَ', 'وليعلمن الله الذين ءامنوا وليعلمن المنفقين', NULL, 397, 'local:hafs-text.json'),
  ('hafs-29-12', 'hafs', 29, 12, 'وَقَالَ ٱلَّذِينَ كَفَرُوا۟ لِلَّذِينَ ءَامَنُوا۟ ٱتَّبِعُوا۟ سَبِيلَنَا وَلْنَحْمِلْ خَطَٰيَٰكُمْ وَمَا هُم بِحَٰمِلِينَ مِنْ خَطَٰيَٰهُم مِّن شَىْءٍ ۖ إِنَّهُمْ لَكَٰذِبُونَ', 'وقال الذين كفروا للذين ءامنوا اتبعوا سبيلنا ولنحمل خطيكم وما هم بحملين من خطيهم من شىء  إنهم لكذبون', NULL, 397, 'local:hafs-text.json'),
  ('hafs-29-13', 'hafs', 29, 13, 'وَلَيَحْمِلُنَّ أَثْقَالَهُمْ وَأَثْقَالًۭا مَّعَ أَثْقَالِهِمْ ۖ وَلَيُسْـَٔلُنَّ يَوْمَ ٱلْقِيَٰمَةِ عَمَّا كَانُوا۟ يَفْتَرُونَ', 'وليحملن أثقالهم وأثقالا مع أثقالهم  وليسلن يوم القيمة عما كانوا يفترون', NULL, 397, 'local:hafs-text.json'),
  ('hafs-29-14', 'hafs', 29, 14, 'وَلَقَدْ أَرْسَلْنَا نُوحًا إِلَىٰ قَوْمِهِۦ فَلَبِثَ فِيهِمْ أَلْفَ سَنَةٍ إِلَّا خَمْسِينَ عَامًۭا فَأَخَذَهُمُ ٱلطُّوفَانُ وَهُمْ ظَٰلِمُونَ', 'ولقد أرسلنا نوحا إلى قومه فلبث فيهم ألف سنة إلا خمسين عاما فأخذهم الطوفان وهم ظلمون', NULL, 397, 'local:hafs-text.json'),
  ('hafs-29-15', 'hafs', 29, 15, 'فَأَنجَيْنَٰهُ وَأَصْحَٰبَ ٱلسَّفِينَةِ وَجَعَلْنَٰهَآ ءَايَةًۭ لِّلْعَٰلَمِينَ', 'فأنجينه وأصحب السفينة وجعلنها ءاية للعلمين', NULL, 398, 'local:hafs-text.json'),
  ('hafs-29-16', 'hafs', 29, 16, 'وَإِبْرَٰهِيمَ إِذْ قَالَ لِقَوْمِهِ ٱعْبُدُوا۟ ٱللَّهَ وَٱتَّقُوهُ ۖ ذَٰلِكُمْ خَيْرٌۭ لَّكُمْ إِن كُنتُمْ تَعْلَمُونَ', 'وإبرهيم إذ قال لقومه اعبدوا الله واتقوه  ذلكم خير لكم إن كنتم تعلمون', NULL, 398, 'local:hafs-text.json'),
  ('hafs-29-17', 'hafs', 29, 17, 'إِنَّمَا تَعْبُدُونَ مِن دُونِ ٱللَّهِ أَوْثَٰنًۭا وَتَخْلُقُونَ إِفْكًا ۚ إِنَّ ٱلَّذِينَ تَعْبُدُونَ مِن دُونِ ٱللَّهِ لَا يَمْلِكُونَ لَكُمْ رِزْقًۭا فَٱبْتَغُوا۟ عِندَ ٱللَّهِ ٱلرِّزْقَ وَٱعْبُدُوهُ وَٱشْكُرُوا۟ لَهُۥٓ ۖ إِلَيْهِ تُرْجَعُونَ', 'إنما تعبدون من دون الله أوثنا وتخلقون إفكا  إن الذين تعبدون من دون الله لا يملكون لكم رزقا فابتغوا عند الله الرزق واعبدوه واشكروا له  إليه ترجعون', NULL, 398, 'local:hafs-text.json'),
  ('hafs-29-18', 'hafs', 29, 18, 'وَإِن تُكَذِّبُوا۟ فَقَدْ كَذَّبَ أُمَمٌۭ مِّن قَبْلِكُمْ ۖ وَمَا عَلَى ٱلرَّسُولِ إِلَّا ٱلْبَلَٰغُ ٱلْمُبِينُ', 'وإن تكذبوا فقد كذب أمم من قبلكم  وما على الرسول إلا البلغ المبين', NULL, 398, 'local:hafs-text.json'),
  ('hafs-29-19', 'hafs', 29, 19, 'أَوَلَمْ يَرَوْا۟ كَيْفَ يُبْدِئُ ٱللَّهُ ٱلْخَلْقَ ثُمَّ يُعِيدُهُۥٓ ۚ إِنَّ ذَٰلِكَ عَلَى ٱللَّهِ يَسِيرٌۭ', 'أولم يروا كيف يبدئ الله الخلق ثم يعيده  إن ذلك على الله يسير', NULL, 398, 'local:hafs-text.json'),
  ('hafs-29-20', 'hafs', 29, 20, 'قُلْ سِيرُوا۟ فِى ٱلْأَرْضِ فَٱنظُرُوا۟ كَيْفَ بَدَأَ ٱلْخَلْقَ ۚ ثُمَّ ٱللَّهُ يُنشِئُ ٱلنَّشْأَةَ ٱلْءَاخِرَةَ ۚ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَىْءٍۢ قَدِيرٌۭ', 'قل سيروا فى الأرض فانظروا كيف بدأ الخلق  ثم الله ينشئ النشأة الءاخرة  إن الله على كل شىء قدير', NULL, 398, 'local:hafs-text.json'),
  ('hafs-29-21', 'hafs', 29, 21, 'يُعَذِّبُ مَن يَشَآءُ وَيَرْحَمُ مَن يَشَآءُ ۖ وَإِلَيْهِ تُقْلَبُونَ', 'يعذب من يشاء ويرحم من يشاء  وإليه تقلبون', NULL, 398, 'local:hafs-text.json'),
  ('hafs-29-22', 'hafs', 29, 22, 'وَمَآ أَنتُم بِمُعْجِزِينَ فِى ٱلْأَرْضِ وَلَا فِى ٱلسَّمَآءِ ۖ وَمَا لَكُم مِّن دُونِ ٱللَّهِ مِن وَلِىٍّۢ وَلَا نَصِيرٍۢ', 'وما أنتم بمعجزين فى الأرض ولا فى السماء  وما لكم من دون الله من ولى ولا نصير', NULL, 398, 'local:hafs-text.json'),
  ('hafs-29-23', 'hafs', 29, 23, 'وَٱلَّذِينَ كَفَرُوا۟ بِـَٔايَٰتِ ٱللَّهِ وَلِقَآئِهِۦٓ أُو۟لَٰٓئِكَ يَئِسُوا۟ مِن رَّحْمَتِى وَأُو۟لَٰٓئِكَ لَهُمْ عَذَابٌ أَلِيمٌۭ', 'والذين كفروا بايت الله ولقائه أولئك يئسوا من رحمتى وأولئك لهم عذاب أليم', NULL, 398, 'local:hafs-text.json'),
  ('hafs-29-24', 'hafs', 29, 24, 'فَمَا كَانَ جَوَابَ قَوْمِهِۦٓ إِلَّآ أَن قَالُوا۟ ٱقْتُلُوهُ أَوْ حَرِّقُوهُ فَأَنجَىٰهُ ٱللَّهُ مِنَ ٱلنَّارِ ۚ إِنَّ فِى ذَٰلِكَ لَءَايَٰتٍۢ لِّقَوْمٍۢ يُؤْمِنُونَ', 'فما كان جواب قومه إلا أن قالوا اقتلوه أو حرقوه فأنجىه الله من النار  إن فى ذلك لءايت لقوم يؤمنون', NULL, 399, 'local:hafs-text.json'),
  ('hafs-29-25', 'hafs', 29, 25, 'وَقَالَ إِنَّمَا ٱتَّخَذْتُم مِّن دُونِ ٱللَّهِ أَوْثَٰنًۭا مَّوَدَّةَ بَيْنِكُمْ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا ۖ ثُمَّ يَوْمَ ٱلْقِيَٰمَةِ يَكْفُرُ بَعْضُكُم بِبَعْضٍۢ وَيَلْعَنُ بَعْضُكُم بَعْضًۭا وَمَأْوَىٰكُمُ ٱلنَّارُ وَمَا لَكُم مِّن نَّٰصِرِينَ', 'وقال إنما اتخذتم من دون الله أوثنا مودة بينكم فى الحيوة الدنيا  ثم يوم القيمة يكفر بعضكم ببعض ويلعن بعضكم بعضا ومأوىكم النار وما لكم من نصرين', NULL, 399, 'local:hafs-text.json'),
  ('hafs-29-26', 'hafs', 29, 26, '۞ فَـَٔامَنَ لَهُۥ لُوطٌۭ ۘ وَقَالَ إِنِّى مُهَاجِرٌ إِلَىٰ رَبِّىٓ ۖ إِنَّهُۥ هُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ', 'فامن له لوط  وقال إنى مهاجر إلى ربى  إنه هو العزيز الحكيم', NULL, 399, 'local:hafs-text.json'),
  ('hafs-29-27', 'hafs', 29, 27, 'وَوَهَبْنَا لَهُۥٓ إِسْحَٰقَ وَيَعْقُوبَ وَجَعَلْنَا فِى ذُرِّيَّتِهِ ٱلنُّبُوَّةَ وَٱلْكِتَٰبَ وَءَاتَيْنَٰهُ أَجْرَهُۥ فِى ٱلدُّنْيَا ۖ وَإِنَّهُۥ فِى ٱلْءَاخِرَةِ لَمِنَ ٱلصَّٰلِحِينَ', 'ووهبنا له إسحق ويعقوب وجعلنا فى ذريته النبوة والكتب وءاتينه أجره فى الدنيا  وإنه فى الءاخرة لمن الصلحين', NULL, 399, 'local:hafs-text.json'),
  ('hafs-29-28', 'hafs', 29, 28, 'وَلُوطًا إِذْ قَالَ لِقَوْمِهِۦٓ إِنَّكُمْ لَتَأْتُونَ ٱلْفَٰحِشَةَ مَا سَبَقَكُم بِهَا مِنْ أَحَدٍۢ مِّنَ ٱلْعَٰلَمِينَ', 'ولوطا إذ قال لقومه إنكم لتأتون الفحشة ما سبقكم بها من أحد من العلمين', NULL, 399, 'local:hafs-text.json'),
  ('hafs-29-29', 'hafs', 29, 29, 'أَئِنَّكُمْ لَتَأْتُونَ ٱلرِّجَالَ وَتَقْطَعُونَ ٱلسَّبِيلَ وَتَأْتُونَ فِى نَادِيكُمُ ٱلْمُنكَرَ ۖ فَمَا كَانَ جَوَابَ قَوْمِهِۦٓ إِلَّآ أَن قَالُوا۟ ٱئْتِنَا بِعَذَابِ ٱللَّهِ إِن كُنتَ مِنَ ٱلصَّٰدِقِينَ', 'أئنكم لتأتون الرجال وتقطعون السبيل وتأتون فى ناديكم المنكر  فما كان جواب قومه إلا أن قالوا ائتنا بعذاب الله إن كنت من الصدقين', NULL, 399, 'local:hafs-text.json'),
  ('hafs-29-30', 'hafs', 29, 30, 'قَالَ رَبِّ ٱنصُرْنِى عَلَى ٱلْقَوْمِ ٱلْمُفْسِدِينَ', 'قال رب انصرنى على القوم المفسدين', NULL, 399, 'local:hafs-text.json'),
  ('hafs-29-31', 'hafs', 29, 31, 'وَلَمَّا جَآءَتْ رُسُلُنَآ إِبْرَٰهِيمَ بِٱلْبُشْرَىٰ قَالُوٓا۟ إِنَّا مُهْلِكُوٓا۟ أَهْلِ هَٰذِهِ ٱلْقَرْيَةِ ۖ إِنَّ أَهْلَهَا كَانُوا۟ ظَٰلِمِينَ', 'ولما جاءت رسلنا إبرهيم بالبشرى قالوا إنا مهلكوا أهل هذه القرية  إن أهلها كانوا ظلمين', NULL, 400, 'local:hafs-text.json'),
  ('hafs-29-32', 'hafs', 29, 32, 'قَالَ إِنَّ فِيهَا لُوطًۭا ۚ قَالُوا۟ نَحْنُ أَعْلَمُ بِمَن فِيهَا ۖ لَنُنَجِّيَنَّهُۥ وَأَهْلَهُۥٓ إِلَّا ٱمْرَأَتَهُۥ كَانَتْ مِنَ ٱلْغَٰبِرِينَ', 'قال إن فيها لوطا  قالوا نحن أعلم بمن فيها  لننجينه وأهله إلا امرأته كانت من الغبرين', NULL, 400, 'local:hafs-text.json'),
  ('hafs-29-33', 'hafs', 29, 33, 'وَلَمَّآ أَن جَآءَتْ رُسُلُنَا لُوطًۭا سِىٓءَ بِهِمْ وَضَاقَ بِهِمْ ذَرْعًۭا وَقَالُوا۟ لَا تَخَفْ وَلَا تَحْزَنْ ۖ إِنَّا مُنَجُّوكَ وَأَهْلَكَ إِلَّا ٱمْرَأَتَكَ كَانَتْ مِنَ ٱلْغَٰبِرِينَ', 'ولما أن جاءت رسلنا لوطا سىء بهم وضاق بهم ذرعا وقالوا لا تخف ولا تحزن  إنا منجوك وأهلك إلا امرأتك كانت من الغبرين', NULL, 400, 'local:hafs-text.json'),
  ('hafs-29-34', 'hafs', 29, 34, 'إِنَّا مُنزِلُونَ عَلَىٰٓ أَهْلِ هَٰذِهِ ٱلْقَرْيَةِ رِجْزًۭا مِّنَ ٱلسَّمَآءِ بِمَا كَانُوا۟ يَفْسُقُونَ', 'إنا منزلون على أهل هذه القرية رجزا من السماء بما كانوا يفسقون', NULL, 400, 'local:hafs-text.json'),
  ('hafs-29-35', 'hafs', 29, 35, 'وَلَقَد تَّرَكْنَا مِنْهَآ ءَايَةًۢ بَيِّنَةًۭ لِّقَوْمٍۢ يَعْقِلُونَ', 'ولقد تركنا منها ءاية بينة لقوم يعقلون', NULL, 400, 'local:hafs-text.json'),
  ('hafs-29-36', 'hafs', 29, 36, 'وَإِلَىٰ مَدْيَنَ أَخَاهُمْ شُعَيْبًۭا فَقَالَ يَٰقَوْمِ ٱعْبُدُوا۟ ٱللَّهَ وَٱرْجُوا۟ ٱلْيَوْمَ ٱلْءَاخِرَ وَلَا تَعْثَوْا۟ فِى ٱلْأَرْضِ مُفْسِدِينَ', 'وإلى مدين أخاهم شعيبا فقال يقوم اعبدوا الله وارجوا اليوم الءاخر ولا تعثوا فى الأرض مفسدين', NULL, 400, 'local:hafs-text.json'),
  ('hafs-29-37', 'hafs', 29, 37, 'فَكَذَّبُوهُ فَأَخَذَتْهُمُ ٱلرَّجْفَةُ فَأَصْبَحُوا۟ فِى دَارِهِمْ جَٰثِمِينَ', 'فكذبوه فأخذتهم الرجفة فأصبحوا فى دارهم جثمين', NULL, 400, 'local:hafs-text.json'),
  ('hafs-29-38', 'hafs', 29, 38, 'وَعَادًۭا وَثَمُودَا۟ وَقَد تَّبَيَّنَ لَكُم مِّن مَّسَٰكِنِهِمْ ۖ وَزَيَّنَ لَهُمُ ٱلشَّيْطَٰنُ أَعْمَٰلَهُمْ فَصَدَّهُمْ عَنِ ٱلسَّبِيلِ وَكَانُوا۟ مُسْتَبْصِرِينَ', 'وعادا وثمودا وقد تبين لكم من مسكنهم  وزين لهم الشيطن أعملهم فصدهم عن السبيل وكانوا مستبصرين', NULL, 400, 'local:hafs-text.json'),
  ('hafs-29-39', 'hafs', 29, 39, 'وَقَٰرُونَ وَفِرْعَوْنَ وَهَٰمَٰنَ ۖ وَلَقَدْ جَآءَهُم مُّوسَىٰ بِٱلْبَيِّنَٰتِ فَٱسْتَكْبَرُوا۟ فِى ٱلْأَرْضِ وَمَا كَانُوا۟ سَٰبِقِينَ', 'وقرون وفرعون وهمن  ولقد جاءهم موسى بالبينت فاستكبروا فى الأرض وما كانوا سبقين', NULL, 401, 'local:hafs-text.json'),
  ('hafs-29-40', 'hafs', 29, 40, 'فَكُلًّا أَخَذْنَا بِذَنۢبِهِۦ ۖ فَمِنْهُم مَّنْ أَرْسَلْنَا عَلَيْهِ حَاصِبًۭا وَمِنْهُم مَّنْ أَخَذَتْهُ ٱلصَّيْحَةُ وَمِنْهُم مَّنْ خَسَفْنَا بِهِ ٱلْأَرْضَ وَمِنْهُم مَّنْ أَغْرَقْنَا ۚ وَمَا كَانَ ٱللَّهُ لِيَظْلِمَهُمْ وَلَٰكِن كَانُوٓا۟ أَنفُسَهُمْ يَظْلِمُونَ', 'فكلا أخذنا بذنبه  فمنهم من أرسلنا عليه حاصبا ومنهم من أخذته الصيحة ومنهم من خسفنا به الأرض ومنهم من أغرقنا  وما كان الله ليظلمهم ولكن كانوا أنفسهم يظلمون', NULL, 401, 'local:hafs-text.json'),
  ('hafs-29-41', 'hafs', 29, 41, 'مَثَلُ ٱلَّذِينَ ٱتَّخَذُوا۟ مِن دُونِ ٱللَّهِ أَوْلِيَآءَ كَمَثَلِ ٱلْعَنكَبُوتِ ٱتَّخَذَتْ بَيْتًۭا ۖ وَإِنَّ أَوْهَنَ ٱلْبُيُوتِ لَبَيْتُ ٱلْعَنكَبُوتِ ۖ لَوْ كَانُوا۟ يَعْلَمُونَ', 'مثل الذين اتخذوا من دون الله أولياء كمثل العنكبوت اتخذت بيتا  وإن أوهن البيوت لبيت العنكبوت  لو كانوا يعلمون', NULL, 401, 'local:hafs-text.json'),
  ('hafs-29-42', 'hafs', 29, 42, 'إِنَّ ٱللَّهَ يَعْلَمُ مَا يَدْعُونَ مِن دُونِهِۦ مِن شَىْءٍۢ ۚ وَهُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ', 'إن الله يعلم ما يدعون من دونه من شىء  وهو العزيز الحكيم', NULL, 401, 'local:hafs-text.json'),
  ('hafs-29-43', 'hafs', 29, 43, 'وَتِلْكَ ٱلْأَمْثَٰلُ نَضْرِبُهَا لِلنَّاسِ ۖ وَمَا يَعْقِلُهَآ إِلَّا ٱلْعَٰلِمُونَ', 'وتلك الأمثل نضربها للناس  وما يعقلها إلا العلمون', NULL, 401, 'local:hafs-text.json'),
  ('hafs-29-44', 'hafs', 29, 44, 'خَلَقَ ٱللَّهُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ بِٱلْحَقِّ ۚ إِنَّ فِى ذَٰلِكَ لَءَايَةًۭ لِّلْمُؤْمِنِينَ', 'خلق الله السموت والأرض بالحق  إن فى ذلك لءاية للمؤمنين', NULL, 401, 'local:hafs-text.json'),
  ('hafs-29-45', 'hafs', 29, 45, 'ٱتْلُ مَآ أُوحِىَ إِلَيْكَ مِنَ ٱلْكِتَٰبِ وَأَقِمِ ٱلصَّلَوٰةَ ۖ إِنَّ ٱلصَّلَوٰةَ تَنْهَىٰ عَنِ ٱلْفَحْشَآءِ وَٱلْمُنكَرِ ۗ وَلَذِكْرُ ٱللَّهِ أَكْبَرُ ۗ وَٱللَّهُ يَعْلَمُ مَا تَصْنَعُونَ', 'اتل ما أوحى إليك من الكتب وأقم الصلوة  إن الصلوة تنهى عن الفحشاء والمنكر  ولذكر الله أكبر  والله يعلم ما تصنعون', NULL, 401, 'local:hafs-text.json'),
  ('hafs-29-46', 'hafs', 29, 46, '۞ وَلَا تُجَٰدِلُوٓا۟ أَهْلَ ٱلْكِتَٰبِ إِلَّا بِٱلَّتِى هِىَ أَحْسَنُ إِلَّا ٱلَّذِينَ ظَلَمُوا۟ مِنْهُمْ ۖ وَقُولُوٓا۟ ءَامَنَّا بِٱلَّذِىٓ أُنزِلَ إِلَيْنَا وَأُنزِلَ إِلَيْكُمْ وَإِلَٰهُنَا وَإِلَٰهُكُمْ وَٰحِدٌۭ وَنَحْنُ لَهُۥ مُسْلِمُونَ', 'ولا تجدلوا أهل الكتب إلا بالتى هى أحسن إلا الذين ظلموا منهم  وقولوا ءامنا بالذى أنزل إلينا وأنزل إليكم وإلهنا وإلهكم وحد ونحن له مسلمون', NULL, 402, 'local:hafs-text.json'),
  ('hafs-29-47', 'hafs', 29, 47, 'وَكَذَٰلِكَ أَنزَلْنَآ إِلَيْكَ ٱلْكِتَٰبَ ۚ فَٱلَّذِينَ ءَاتَيْنَٰهُمُ ٱلْكِتَٰبَ يُؤْمِنُونَ بِهِۦ ۖ وَمِنْ هَٰٓؤُلَآءِ مَن يُؤْمِنُ بِهِۦ ۚ وَمَا يَجْحَدُ بِـَٔايَٰتِنَآ إِلَّا ٱلْكَٰفِرُونَ', 'وكذلك أنزلنا إليك الكتب  فالذين ءاتينهم الكتب يؤمنون به  ومن هؤلاء من يؤمن به  وما يجحد بايتنا إلا الكفرون', NULL, 402, 'local:hafs-text.json'),
  ('hafs-29-48', 'hafs', 29, 48, 'وَمَا كُنتَ تَتْلُوا۟ مِن قَبْلِهِۦ مِن كِتَٰبٍۢ وَلَا تَخُطُّهُۥ بِيَمِينِكَ ۖ إِذًۭا لَّٱرْتَابَ ٱلْمُبْطِلُونَ', 'وما كنت تتلوا من قبله من كتب ولا تخطه بيمينك  إذا لارتاب المبطلون', NULL, 402, 'local:hafs-text.json'),
  ('hafs-29-49', 'hafs', 29, 49, 'بَلْ هُوَ ءَايَٰتٌۢ بَيِّنَٰتٌۭ فِى صُدُورِ ٱلَّذِينَ أُوتُوا۟ ٱلْعِلْمَ ۚ وَمَا يَجْحَدُ بِـَٔايَٰتِنَآ إِلَّا ٱلظَّٰلِمُونَ', 'بل هو ءايت بينت فى صدور الذين أوتوا العلم  وما يجحد بايتنا إلا الظلمون', NULL, 402, 'local:hafs-text.json'),
  ('hafs-29-50', 'hafs', 29, 50, 'وَقَالُوا۟ لَوْلَآ أُنزِلَ عَلَيْهِ ءَايَٰتٌۭ مِّن رَّبِّهِۦ ۖ قُلْ إِنَّمَا ٱلْءَايَٰتُ عِندَ ٱللَّهِ وَإِنَّمَآ أَنَا۠ نَذِيرٌۭ مُّبِينٌ', 'وقالوا لولا أنزل عليه ءايت من ربه  قل إنما الءايت عند الله وإنما أنا نذير مبين', NULL, 402, 'local:hafs-text.json'),
  ('hafs-29-51', 'hafs', 29, 51, 'أَوَلَمْ يَكْفِهِمْ أَنَّآ أَنزَلْنَا عَلَيْكَ ٱلْكِتَٰبَ يُتْلَىٰ عَلَيْهِمْ ۚ إِنَّ فِى ذَٰلِكَ لَرَحْمَةًۭ وَذِكْرَىٰ لِقَوْمٍۢ يُؤْمِنُونَ', 'أولم يكفهم أنا أنزلنا عليك الكتب يتلى عليهم  إن فى ذلك لرحمة وذكرى لقوم يؤمنون', NULL, 402, 'local:hafs-text.json'),
  ('hafs-29-52', 'hafs', 29, 52, 'قُلْ كَفَىٰ بِٱللَّهِ بَيْنِى وَبَيْنَكُمْ شَهِيدًۭا ۖ يَعْلَمُ مَا فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ ۗ وَٱلَّذِينَ ءَامَنُوا۟ بِٱلْبَٰطِلِ وَكَفَرُوا۟ بِٱللَّهِ أُو۟لَٰٓئِكَ هُمُ ٱلْخَٰسِرُونَ', 'قل كفى بالله بينى وبينكم شهيدا  يعلم ما فى السموت والأرض  والذين ءامنوا بالبطل وكفروا بالله أولئك هم الخسرون', NULL, 402, 'local:hafs-text.json'),
  ('hafs-29-53', 'hafs', 29, 53, 'وَيَسْتَعْجِلُونَكَ بِٱلْعَذَابِ ۚ وَلَوْلَآ أَجَلٌۭ مُّسَمًّۭى لَّجَآءَهُمُ ٱلْعَذَابُ وَلَيَأْتِيَنَّهُم بَغْتَةًۭ وَهُمْ لَا يَشْعُرُونَ', 'ويستعجلونك بالعذاب  ولولا أجل مسمى لجاءهم العذاب وليأتينهم بغتة وهم لا يشعرون', NULL, 403, 'local:hafs-text.json'),
  ('hafs-29-54', 'hafs', 29, 54, 'يَسْتَعْجِلُونَكَ بِٱلْعَذَابِ وَإِنَّ جَهَنَّمَ لَمُحِيطَةٌۢ بِٱلْكَٰفِرِينَ', 'يستعجلونك بالعذاب وإن جهنم لمحيطة بالكفرين', NULL, 403, 'local:hafs-text.json'),
  ('hafs-29-55', 'hafs', 29, 55, 'يَوْمَ يَغْشَىٰهُمُ ٱلْعَذَابُ مِن فَوْقِهِمْ وَمِن تَحْتِ أَرْجُلِهِمْ وَيَقُولُ ذُوقُوا۟ مَا كُنتُمْ تَعْمَلُونَ', 'يوم يغشىهم العذاب من فوقهم ومن تحت أرجلهم ويقول ذوقوا ما كنتم تعملون', NULL, 403, 'local:hafs-text.json'),
  ('hafs-29-56', 'hafs', 29, 56, 'يَٰعِبَادِىَ ٱلَّذِينَ ءَامَنُوٓا۟ إِنَّ أَرْضِى وَٰسِعَةٌۭ فَإِيَّٰىَ فَٱعْبُدُونِ', 'يعبادى الذين ءامنوا إن أرضى وسعة فإيى فاعبدون', NULL, 403, 'local:hafs-text.json'),
  ('hafs-29-57', 'hafs', 29, 57, 'كُلُّ نَفْسٍۢ ذَآئِقَةُ ٱلْمَوْتِ ۖ ثُمَّ إِلَيْنَا تُرْجَعُونَ', 'كل نفس ذائقة الموت  ثم إلينا ترجعون', NULL, 403, 'local:hafs-text.json'),
  ('hafs-29-58', 'hafs', 29, 58, 'وَٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ لَنُبَوِّئَنَّهُم مِّنَ ٱلْجَنَّةِ غُرَفًۭا تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ خَٰلِدِينَ فِيهَا ۚ نِعْمَ أَجْرُ ٱلْعَٰمِلِينَ', 'والذين ءامنوا وعملوا الصلحت لنبوئنهم من الجنة غرفا تجرى من تحتها الأنهر خلدين فيها  نعم أجر العملين', NULL, 403, 'local:hafs-text.json'),
  ('hafs-29-59', 'hafs', 29, 59, 'ٱلَّذِينَ صَبَرُوا۟ وَعَلَىٰ رَبِّهِمْ يَتَوَكَّلُونَ', 'الذين صبروا وعلى ربهم يتوكلون', NULL, 403, 'local:hafs-text.json'),
  ('hafs-29-60', 'hafs', 29, 60, 'وَكَأَيِّن مِّن دَآبَّةٍۢ لَّا تَحْمِلُ رِزْقَهَا ٱللَّهُ يَرْزُقُهَا وَإِيَّاكُمْ ۚ وَهُوَ ٱلسَّمِيعُ ٱلْعَلِيمُ', 'وكأين من دابة لا تحمل رزقها الله يرزقها وإياكم  وهو السميع العليم', NULL, 403, 'local:hafs-text.json'),
  ('hafs-29-61', 'hafs', 29, 61, 'وَلَئِن سَأَلْتَهُم مَّنْ خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ وَسَخَّرَ ٱلشَّمْسَ وَٱلْقَمَرَ لَيَقُولُنَّ ٱللَّهُ ۖ فَأَنَّىٰ يُؤْفَكُونَ', 'ولئن سألتهم من خلق السموت والأرض وسخر الشمس والقمر ليقولن الله  فأنى يؤفكون', NULL, 403, 'local:hafs-text.json'),
  ('hafs-29-62', 'hafs', 29, 62, 'ٱللَّهُ يَبْسُطُ ٱلرِّزْقَ لِمَن يَشَآءُ مِنْ عِبَادِهِۦ وَيَقْدِرُ لَهُۥٓ ۚ إِنَّ ٱللَّهَ بِكُلِّ شَىْءٍ عَلِيمٌۭ', 'الله يبسط الرزق لمن يشاء من عباده ويقدر له  إن الله بكل شىء عليم', NULL, 403, 'local:hafs-text.json'),
  ('hafs-29-63', 'hafs', 29, 63, 'وَلَئِن سَأَلْتَهُم مَّن نَّزَّلَ مِنَ ٱلسَّمَآءِ مَآءًۭ فَأَحْيَا بِهِ ٱلْأَرْضَ مِنۢ بَعْدِ مَوْتِهَا لَيَقُولُنَّ ٱللَّهُ ۚ قُلِ ٱلْحَمْدُ لِلَّهِ ۚ بَلْ أَكْثَرُهُمْ لَا يَعْقِلُونَ', 'ولئن سألتهم من نزل من السماء ماء فأحيا به الأرض من بعد موتها ليقولن الله  قل الحمد لله  بل أكثرهم لا يعقلون', NULL, 403, 'local:hafs-text.json'),
  ('hafs-29-64', 'hafs', 29, 64, 'وَمَا هَٰذِهِ ٱلْحَيَوٰةُ ٱلدُّنْيَآ إِلَّا لَهْوٌۭ وَلَعِبٌۭ ۚ وَإِنَّ ٱلدَّارَ ٱلْءَاخِرَةَ لَهِىَ ٱلْحَيَوَانُ ۚ لَوْ كَانُوا۟ يَعْلَمُونَ', 'وما هذه الحيوة الدنيا إلا لهو ولعب  وإن الدار الءاخرة لهى الحيوان  لو كانوا يعلمون', NULL, 404, 'local:hafs-text.json'),
  ('hafs-29-65', 'hafs', 29, 65, 'فَإِذَا رَكِبُوا۟ فِى ٱلْفُلْكِ دَعَوُا۟ ٱللَّهَ مُخْلِصِينَ لَهُ ٱلدِّينَ فَلَمَّا نَجَّىٰهُمْ إِلَى ٱلْبَرِّ إِذَا هُمْ يُشْرِكُونَ', 'فإذا ركبوا فى الفلك دعوا الله مخلصين له الدين فلما نجىهم إلى البر إذا هم يشركون', NULL, 404, 'local:hafs-text.json'),
  ('hafs-29-66', 'hafs', 29, 66, 'لِيَكْفُرُوا۟ بِمَآ ءَاتَيْنَٰهُمْ وَلِيَتَمَتَّعُوا۟ ۖ فَسَوْفَ يَعْلَمُونَ', 'ليكفروا بما ءاتينهم وليتمتعوا  فسوف يعلمون', NULL, 404, 'local:hafs-text.json'),
  ('hafs-29-67', 'hafs', 29, 67, 'أَوَلَمْ يَرَوْا۟ أَنَّا جَعَلْنَا حَرَمًا ءَامِنًۭا وَيُتَخَطَّفُ ٱلنَّاسُ مِنْ حَوْلِهِمْ ۚ أَفَبِٱلْبَٰطِلِ يُؤْمِنُونَ وَبِنِعْمَةِ ٱللَّهِ يَكْفُرُونَ', 'أولم يروا أنا جعلنا حرما ءامنا ويتخطف الناس من حولهم  أفبالبطل يؤمنون وبنعمة الله يكفرون', NULL, 404, 'local:hafs-text.json'),
  ('hafs-29-68', 'hafs', 29, 68, 'وَمَنْ أَظْلَمُ مِمَّنِ ٱفْتَرَىٰ عَلَى ٱللَّهِ كَذِبًا أَوْ كَذَّبَ بِٱلْحَقِّ لَمَّا جَآءَهُۥٓ ۚ أَلَيْسَ فِى جَهَنَّمَ مَثْوًۭى لِّلْكَٰفِرِينَ', 'ومن أظلم ممن افترى على الله كذبا أو كذب بالحق لما جاءه  أليس فى جهنم مثوى للكفرين', NULL, 404, 'local:hafs-text.json'),
  ('hafs-29-69', 'hafs', 29, 69, 'وَٱلَّذِينَ جَٰهَدُوا۟ فِينَا لَنَهْدِيَنَّهُمْ سُبُلَنَا ۚ وَإِنَّ ٱللَّهَ لَمَعَ ٱلْمُحْسِنِينَ', 'والذين جهدوا فينا لنهدينهم سبلنا  وإن الله لمع المحسنين', NULL, 404, 'local:hafs-text.json'),
  ('hafs-30-1', 'hafs', 30, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ الٓمٓ', 'بسم الله الرحمن الرحيم الم', NULL, 404, 'local:hafs-text.json'),
  ('hafs-30-2', 'hafs', 30, 2, 'غُلِبَتِ ٱلرُّومُ', 'غلبت الروم', NULL, 404, 'local:hafs-text.json'),
  ('hafs-30-3', 'hafs', 30, 3, 'فِىٓ أَدْنَى ٱلْأَرْضِ وَهُم مِّنۢ بَعْدِ غَلَبِهِمْ سَيَغْلِبُونَ', 'فى أدنى الأرض وهم من بعد غلبهم سيغلبون', NULL, 404, 'local:hafs-text.json'),
  ('hafs-30-4', 'hafs', 30, 4, 'فِى بِضْعِ سِنِينَ ۗ لِلَّهِ ٱلْأَمْرُ مِن قَبْلُ وَمِنۢ بَعْدُ ۚ وَيَوْمَئِذٍۢ يَفْرَحُ ٱلْمُؤْمِنُونَ', 'فى بضع سنين  لله الأمر من قبل ومن بعد  ويومئذ يفرح المؤمنون', NULL, 404, 'local:hafs-text.json'),
  ('hafs-30-5', 'hafs', 30, 5, 'بِنَصْرِ ٱللَّهِ ۚ يَنصُرُ مَن يَشَآءُ ۖ وَهُوَ ٱلْعَزِيزُ ٱلرَّحِيمُ', 'بنصر الله  ينصر من يشاء  وهو العزيز الرحيم', NULL, 404, 'local:hafs-text.json'),
  ('hafs-30-6', 'hafs', 30, 6, 'وَعْدَ ٱللَّهِ ۖ لَا يُخْلِفُ ٱللَّهُ وَعْدَهُۥ وَلَٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يَعْلَمُونَ', 'وعد الله  لا يخلف الله وعده ولكن أكثر الناس لا يعلمون', NULL, 405, 'local:hafs-text.json'),
  ('hafs-30-7', 'hafs', 30, 7, 'يَعْلَمُونَ ظَٰهِرًۭا مِّنَ ٱلْحَيَوٰةِ ٱلدُّنْيَا وَهُمْ عَنِ ٱلْءَاخِرَةِ هُمْ غَٰفِلُونَ', 'يعلمون ظهرا من الحيوة الدنيا وهم عن الءاخرة هم غفلون', NULL, 405, 'local:hafs-text.json'),
  ('hafs-30-8', 'hafs', 30, 8, 'أَوَلَمْ يَتَفَكَّرُوا۟ فِىٓ أَنفُسِهِم ۗ مَّا خَلَقَ ٱللَّهُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ وَمَا بَيْنَهُمَآ إِلَّا بِٱلْحَقِّ وَأَجَلٍۢ مُّسَمًّۭى ۗ وَإِنَّ كَثِيرًۭا مِّنَ ٱلنَّاسِ بِلِقَآئِ رَبِّهِمْ لَكَٰفِرُونَ', 'أولم يتفكروا فى أنفسهم  ما خلق الله السموت والأرض وما بينهما إلا بالحق وأجل مسمى  وإن كثيرا من الناس بلقائ ربهم لكفرون', NULL, 405, 'local:hafs-text.json'),
  ('hafs-30-9', 'hafs', 30, 9, 'أَوَلَمْ يَسِيرُوا۟ فِى ٱلْأَرْضِ فَيَنظُرُوا۟ كَيْفَ كَانَ عَٰقِبَةُ ٱلَّذِينَ مِن قَبْلِهِمْ ۚ كَانُوٓا۟ أَشَدَّ مِنْهُمْ قُوَّةًۭ وَأَثَارُوا۟ ٱلْأَرْضَ وَعَمَرُوهَآ أَكْثَرَ مِمَّا عَمَرُوهَا وَجَآءَتْهُمْ رُسُلُهُم بِٱلْبَيِّنَٰتِ ۖ فَمَا كَانَ ٱللَّهُ لِيَظْلِمَهُمْ وَلَٰكِن كَانُوٓا۟ أَنفُسَهُمْ يَظْلِمُونَ', 'أولم يسيروا فى الأرض فينظروا كيف كان عقبة الذين من قبلهم  كانوا أشد منهم قوة وأثاروا الأرض وعمروها أكثر مما عمروها وجاءتهم رسلهم بالبينت  فما كان الله ليظلمهم ولكن كانوا أنفسهم يظلمون', NULL, 405, 'local:hafs-text.json'),
  ('hafs-30-10', 'hafs', 30, 10, 'ثُمَّ كَانَ عَٰقِبَةَ ٱلَّذِينَ أَسَٰٓـُٔوا۟ ٱلسُّوٓأَىٰٓ أَن كَذَّبُوا۟ بِـَٔايَٰتِ ٱللَّهِ وَكَانُوا۟ بِهَا يَسْتَهْزِءُونَ', 'ثم كان عقبة الذين أسوا السوأى أن كذبوا بايت الله وكانوا بها يستهزءون', NULL, 405, 'local:hafs-text.json'),
  ('hafs-30-11', 'hafs', 30, 11, 'ٱللَّهُ يَبْدَؤُا۟ ٱلْخَلْقَ ثُمَّ يُعِيدُهُۥ ثُمَّ إِلَيْهِ تُرْجَعُونَ', 'الله يبدؤا الخلق ثم يعيده ثم إليه ترجعون', NULL, 405, 'local:hafs-text.json'),
  ('hafs-30-12', 'hafs', 30, 12, 'وَيَوْمَ تَقُومُ ٱلسَّاعَةُ يُبْلِسُ ٱلْمُجْرِمُونَ', 'ويوم تقوم الساعة يبلس المجرمون', NULL, 405, 'local:hafs-text.json'),
  ('hafs-30-13', 'hafs', 30, 13, 'وَلَمْ يَكُن لَّهُم مِّن شُرَكَآئِهِمْ شُفَعَٰٓؤُا۟ وَكَانُوا۟ بِشُرَكَآئِهِمْ كَٰفِرِينَ', 'ولم يكن لهم من شركائهم شفعؤا وكانوا بشركائهم كفرين', NULL, 405, 'local:hafs-text.json'),
  ('hafs-30-14', 'hafs', 30, 14, 'وَيَوْمَ تَقُومُ ٱلسَّاعَةُ يَوْمَئِذٍۢ يَتَفَرَّقُونَ', 'ويوم تقوم الساعة يومئذ يتفرقون', NULL, 405, 'local:hafs-text.json'),
  ('hafs-30-15', 'hafs', 30, 15, 'فَأَمَّا ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ فَهُمْ فِى رَوْضَةٍۢ يُحْبَرُونَ', 'فأما الذين ءامنوا وعملوا الصلحت فهم فى روضة يحبرون', NULL, 405, 'local:hafs-text.json'),
  ('hafs-30-16', 'hafs', 30, 16, 'وَأَمَّا ٱلَّذِينَ كَفَرُوا۟ وَكَذَّبُوا۟ بِـَٔايَٰتِنَا وَلِقَآئِ ٱلْءَاخِرَةِ فَأُو۟لَٰٓئِكَ فِى ٱلْعَذَابِ مُحْضَرُونَ', 'وأما الذين كفروا وكذبوا بايتنا ولقائ الءاخرة فأولئك فى العذاب محضرون', NULL, 406, 'local:hafs-text.json'),
  ('hafs-30-17', 'hafs', 30, 17, 'فَسُبْحَٰنَ ٱللَّهِ حِينَ تُمْسُونَ وَحِينَ تُصْبِحُونَ', 'فسبحن الله حين تمسون وحين تصبحون', NULL, 406, 'local:hafs-text.json'),
  ('hafs-30-18', 'hafs', 30, 18, 'وَلَهُ ٱلْحَمْدُ فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَعَشِيًّۭا وَحِينَ تُظْهِرُونَ', 'وله الحمد فى السموت والأرض وعشيا وحين تظهرون', NULL, 406, 'local:hafs-text.json'),
  ('hafs-30-19', 'hafs', 30, 19, 'يُخْرِجُ ٱلْحَىَّ مِنَ ٱلْمَيِّتِ وَيُخْرِجُ ٱلْمَيِّتَ مِنَ ٱلْحَىِّ وَيُحْىِ ٱلْأَرْضَ بَعْدَ مَوْتِهَا ۚ وَكَذَٰلِكَ تُخْرَجُونَ', 'يخرج الحى من الميت ويخرج الميت من الحى ويحى الأرض بعد موتها  وكذلك تخرجون', NULL, 406, 'local:hafs-text.json'),
  ('hafs-30-20', 'hafs', 30, 20, 'وَمِنْ ءَايَٰتِهِۦٓ أَنْ خَلَقَكُم مِّن تُرَابٍۢ ثُمَّ إِذَآ أَنتُم بَشَرٌۭ تَنتَشِرُونَ', 'ومن ءايته أن خلقكم من تراب ثم إذا أنتم بشر تنتشرون', NULL, 406, 'local:hafs-text.json'),
  ('hafs-30-21', 'hafs', 30, 21, 'وَمِنْ ءَايَٰتِهِۦٓ أَنْ خَلَقَ لَكُم مِّنْ أَنفُسِكُمْ أَزْوَٰجًۭا لِّتَسْكُنُوٓا۟ إِلَيْهَا وَجَعَلَ بَيْنَكُم مَّوَدَّةًۭ وَرَحْمَةً ۚ إِنَّ فِى ذَٰلِكَ لَءَايَٰتٍۢ لِّقَوْمٍۢ يَتَفَكَّرُونَ', 'ومن ءايته أن خلق لكم من أنفسكم أزوجا لتسكنوا إليها وجعل بينكم مودة ورحمة  إن فى ذلك لءايت لقوم يتفكرون', NULL, 406, 'local:hafs-text.json'),
  ('hafs-30-22', 'hafs', 30, 22, 'وَمِنْ ءَايَٰتِهِۦ خَلْقُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَٱخْتِلَٰفُ أَلْسِنَتِكُمْ وَأَلْوَٰنِكُمْ ۚ إِنَّ فِى ذَٰلِكَ لَءَايَٰتٍۢ لِّلْعَٰلِمِينَ', 'ومن ءايته خلق السموت والأرض واختلف ألسنتكم وألونكم  إن فى ذلك لءايت للعلمين', NULL, 406, 'local:hafs-text.json'),
  ('hafs-30-23', 'hafs', 30, 23, 'وَمِنْ ءَايَٰتِهِۦ مَنَامُكُم بِٱلَّيْلِ وَٱلنَّهَارِ وَٱبْتِغَآؤُكُم مِّن فَضْلِهِۦٓ ۚ إِنَّ فِى ذَٰلِكَ لَءَايَٰتٍۢ لِّقَوْمٍۢ يَسْمَعُونَ', 'ومن ءايته منامكم باليل والنهار وابتغاؤكم من فضله  إن فى ذلك لءايت لقوم يسمعون', NULL, 406, 'local:hafs-text.json'),
  ('hafs-30-24', 'hafs', 30, 24, 'وَمِنْ ءَايَٰتِهِۦ يُرِيكُمُ ٱلْبَرْقَ خَوْفًۭا وَطَمَعًۭا وَيُنَزِّلُ مِنَ ٱلسَّمَآءِ مَآءًۭ فَيُحْىِۦ بِهِ ٱلْأَرْضَ بَعْدَ مَوْتِهَآ ۚ إِنَّ فِى ذَٰلِكَ لَءَايَٰتٍۢ لِّقَوْمٍۢ يَعْقِلُونَ', 'ومن ءايته يريكم البرق خوفا وطمعا وينزل من السماء ماء فيحى به الأرض بعد موتها  إن فى ذلك لءايت لقوم يعقلون', NULL, 406, 'local:hafs-text.json'),
  ('hafs-30-25', 'hafs', 30, 25, 'وَمِنْ ءَايَٰتِهِۦٓ أَن تَقُومَ ٱلسَّمَآءُ وَٱلْأَرْضُ بِأَمْرِهِۦ ۚ ثُمَّ إِذَا دَعَاكُمْ دَعْوَةًۭ مِّنَ ٱلْأَرْضِ إِذَآ أَنتُمْ تَخْرُجُونَ', 'ومن ءايته أن تقوم السماء والأرض بأمره  ثم إذا دعاكم دعوة من الأرض إذا أنتم تخرجون', NULL, 407, 'local:hafs-text.json'),
  ('hafs-30-26', 'hafs', 30, 26, 'وَلَهُۥ مَن فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ ۖ كُلٌّۭ لَّهُۥ قَٰنِتُونَ', 'وله من فى السموت والأرض  كل له قنتون', NULL, 407, 'local:hafs-text.json'),
  ('hafs-30-27', 'hafs', 30, 27, 'وَهُوَ ٱلَّذِى يَبْدَؤُا۟ ٱلْخَلْقَ ثُمَّ يُعِيدُهُۥ وَهُوَ أَهْوَنُ عَلَيْهِ ۚ وَلَهُ ٱلْمَثَلُ ٱلْأَعْلَىٰ فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ ۚ وَهُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ', 'وهو الذى يبدؤا الخلق ثم يعيده وهو أهون عليه  وله المثل الأعلى فى السموت والأرض  وهو العزيز الحكيم', NULL, 407, 'local:hafs-text.json'),
  ('hafs-30-28', 'hafs', 30, 28, 'ضَرَبَ لَكُم مَّثَلًۭا مِّنْ أَنفُسِكُمْ ۖ هَل لَّكُم مِّن مَّا مَلَكَتْ أَيْمَٰنُكُم مِّن شُرَكَآءَ فِى مَا رَزَقْنَٰكُمْ فَأَنتُمْ فِيهِ سَوَآءٌۭ تَخَافُونَهُمْ كَخِيفَتِكُمْ أَنفُسَكُمْ ۚ كَذَٰلِكَ نُفَصِّلُ ٱلْءَايَٰتِ لِقَوْمٍۢ يَعْقِلُونَ', 'ضرب لكم مثلا من أنفسكم  هل لكم من ما ملكت أيمنكم من شركاء فى ما رزقنكم فأنتم فيه سواء تخافونهم كخيفتكم أنفسكم  كذلك نفصل الءايت لقوم يعقلون', NULL, 407, 'local:hafs-text.json'),
  ('hafs-30-29', 'hafs', 30, 29, 'بَلِ ٱتَّبَعَ ٱلَّذِينَ ظَلَمُوٓا۟ أَهْوَآءَهُم بِغَيْرِ عِلْمٍۢ ۖ فَمَن يَهْدِى مَنْ أَضَلَّ ٱللَّهُ ۖ وَمَا لَهُم مِّن نَّٰصِرِينَ', 'بل اتبع الذين ظلموا أهواءهم بغير علم  فمن يهدى من أضل الله  وما لهم من نصرين', NULL, 407, 'local:hafs-text.json'),
  ('hafs-30-30', 'hafs', 30, 30, 'فَأَقِمْ وَجْهَكَ لِلدِّينِ حَنِيفًۭا ۚ فِطْرَتَ ٱللَّهِ ٱلَّتِى فَطَرَ ٱلنَّاسَ عَلَيْهَا ۚ لَا تَبْدِيلَ لِخَلْقِ ٱللَّهِ ۚ ذَٰلِكَ ٱلدِّينُ ٱلْقَيِّمُ وَلَٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يَعْلَمُونَ', 'فأقم وجهك للدين حنيفا  فطرت الله التى فطر الناس عليها  لا تبديل لخلق الله  ذلك الدين القيم ولكن أكثر الناس لا يعلمون', NULL, 407, 'local:hafs-text.json'),
  ('hafs-30-31', 'hafs', 30, 31, '۞ مُنِيبِينَ إِلَيْهِ وَٱتَّقُوهُ وَأَقِيمُوا۟ ٱلصَّلَوٰةَ وَلَا تَكُونُوا۟ مِنَ ٱلْمُشْرِكِينَ', 'منيبين إليه واتقوه وأقيموا الصلوة ولا تكونوا من المشركين', NULL, 407, 'local:hafs-text.json'),
  ('hafs-30-32', 'hafs', 30, 32, 'مِنَ ٱلَّذِينَ فَرَّقُوا۟ دِينَهُمْ وَكَانُوا۟ شِيَعًۭا ۖ كُلُّ حِزْبٍۭ بِمَا لَدَيْهِمْ فَرِحُونَ', 'من الذين فرقوا دينهم وكانوا شيعا  كل حزب بما لديهم فرحون', NULL, 407, 'local:hafs-text.json'),
  ('hafs-30-33', 'hafs', 30, 33, 'وَإِذَا مَسَّ ٱلنَّاسَ ضُرٌّۭ دَعَوْا۟ رَبَّهُم مُّنِيبِينَ إِلَيْهِ ثُمَّ إِذَآ أَذَاقَهُم مِّنْهُ رَحْمَةً إِذَا فَرِيقٌۭ مِّنْهُم بِرَبِّهِمْ يُشْرِكُونَ', 'وإذا مس الناس ضر دعوا ربهم منيبين إليه ثم إذا أذاقهم منه رحمة إذا فريق منهم بربهم يشركون', NULL, 408, 'local:hafs-text.json'),
  ('hafs-30-34', 'hafs', 30, 34, 'لِيَكْفُرُوا۟ بِمَآ ءَاتَيْنَٰهُمْ ۚ فَتَمَتَّعُوا۟ فَسَوْفَ تَعْلَمُونَ', 'ليكفروا بما ءاتينهم  فتمتعوا فسوف تعلمون', NULL, 408, 'local:hafs-text.json'),
  ('hafs-30-35', 'hafs', 30, 35, 'أَمْ أَنزَلْنَا عَلَيْهِمْ سُلْطَٰنًۭا فَهُوَ يَتَكَلَّمُ بِمَا كَانُوا۟ بِهِۦ يُشْرِكُونَ', 'أم أنزلنا عليهم سلطنا فهو يتكلم بما كانوا به يشركون', NULL, 408, 'local:hafs-text.json'),
  ('hafs-30-36', 'hafs', 30, 36, 'وَإِذَآ أَذَقْنَا ٱلنَّاسَ رَحْمَةًۭ فَرِحُوا۟ بِهَا ۖ وَإِن تُصِبْهُمْ سَيِّئَةٌۢ بِمَا قَدَّمَتْ أَيْدِيهِمْ إِذَا هُمْ يَقْنَطُونَ', 'وإذا أذقنا الناس رحمة فرحوا بها  وإن تصبهم سيئة بما قدمت أيديهم إذا هم يقنطون', NULL, 408, 'local:hafs-text.json'),
  ('hafs-30-37', 'hafs', 30, 37, 'أَوَلَمْ يَرَوْا۟ أَنَّ ٱللَّهَ يَبْسُطُ ٱلرِّزْقَ لِمَن يَشَآءُ وَيَقْدِرُ ۚ إِنَّ فِى ذَٰلِكَ لَءَايَٰتٍۢ لِّقَوْمٍۢ يُؤْمِنُونَ', 'أولم يروا أن الله يبسط الرزق لمن يشاء ويقدر  إن فى ذلك لءايت لقوم يؤمنون', NULL, 408, 'local:hafs-text.json'),
  ('hafs-30-38', 'hafs', 30, 38, 'فَـَٔاتِ ذَا ٱلْقُرْبَىٰ حَقَّهُۥ وَٱلْمِسْكِينَ وَٱبْنَ ٱلسَّبِيلِ ۚ ذَٰلِكَ خَيْرٌۭ لِّلَّذِينَ يُرِيدُونَ وَجْهَ ٱللَّهِ ۖ وَأُو۟لَٰٓئِكَ هُمُ ٱلْمُفْلِحُونَ', 'فات ذا القربى حقه والمسكين وابن السبيل  ذلك خير للذين يريدون وجه الله  وأولئك هم المفلحون', NULL, 408, 'local:hafs-text.json'),
  ('hafs-30-39', 'hafs', 30, 39, 'وَمَآ ءَاتَيْتُم مِّن رِّبًۭا لِّيَرْبُوَا۟ فِىٓ أَمْوَٰلِ ٱلنَّاسِ فَلَا يَرْبُوا۟ عِندَ ٱللَّهِ ۖ وَمَآ ءَاتَيْتُم مِّن زَكَوٰةٍۢ تُرِيدُونَ وَجْهَ ٱللَّهِ فَأُو۟لَٰٓئِكَ هُمُ ٱلْمُضْعِفُونَ', 'وما ءاتيتم من ربا ليربوا فى أمول الناس فلا يربوا عند الله  وما ءاتيتم من زكوة تريدون وجه الله فأولئك هم المضعفون', NULL, 408, 'local:hafs-text.json'),
  ('hafs-30-40', 'hafs', 30, 40, 'ٱللَّهُ ٱلَّذِى خَلَقَكُمْ ثُمَّ رَزَقَكُمْ ثُمَّ يُمِيتُكُمْ ثُمَّ يُحْيِيكُمْ ۖ هَلْ مِن شُرَكَآئِكُم مَّن يَفْعَلُ مِن ذَٰلِكُم مِّن شَىْءٍۢ ۚ سُبْحَٰنَهُۥ وَتَعَٰلَىٰ عَمَّا يُشْرِكُونَ', 'الله الذى خلقكم ثم رزقكم ثم يميتكم ثم يحييكم  هل من شركائكم من يفعل من ذلكم من شىء  سبحنه وتعلى عما يشركون', NULL, 408, 'local:hafs-text.json'),
  ('hafs-30-41', 'hafs', 30, 41, 'ظَهَرَ ٱلْفَسَادُ فِى ٱلْبَرِّ وَٱلْبَحْرِ بِمَا كَسَبَتْ أَيْدِى ٱلنَّاسِ لِيُذِيقَهُم بَعْضَ ٱلَّذِى عَمِلُوا۟ لَعَلَّهُمْ يَرْجِعُونَ', 'ظهر الفساد فى البر والبحر بما كسبت أيدى الناس ليذيقهم بعض الذى عملوا لعلهم يرجعون', NULL, 408, 'local:hafs-text.json'),
  ('hafs-30-42', 'hafs', 30, 42, 'قُلْ سِيرُوا۟ فِى ٱلْأَرْضِ فَٱنظُرُوا۟ كَيْفَ كَانَ عَٰقِبَةُ ٱلَّذِينَ مِن قَبْلُ ۚ كَانَ أَكْثَرُهُم مُّشْرِكِينَ', 'قل سيروا فى الأرض فانظروا كيف كان عقبة الذين من قبل  كان أكثرهم مشركين', NULL, 409, 'local:hafs-text.json'),
  ('hafs-30-43', 'hafs', 30, 43, 'فَأَقِمْ وَجْهَكَ لِلدِّينِ ٱلْقَيِّمِ مِن قَبْلِ أَن يَأْتِىَ يَوْمٌۭ لَّا مَرَدَّ لَهُۥ مِنَ ٱللَّهِ ۖ يَوْمَئِذٍۢ يَصَّدَّعُونَ', 'فأقم وجهك للدين القيم من قبل أن يأتى يوم لا مرد له من الله  يومئذ يصدعون', NULL, 409, 'local:hafs-text.json'),
  ('hafs-30-44', 'hafs', 30, 44, 'مَن كَفَرَ فَعَلَيْهِ كُفْرُهُۥ ۖ وَمَنْ عَمِلَ صَٰلِحًۭا فَلِأَنفُسِهِمْ يَمْهَدُونَ', 'من كفر فعليه كفره  ومن عمل صلحا فلأنفسهم يمهدون', NULL, 409, 'local:hafs-text.json'),
  ('hafs-30-45', 'hafs', 30, 45, 'لِيَجْزِىَ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ مِن فَضْلِهِۦٓ ۚ إِنَّهُۥ لَا يُحِبُّ ٱلْكَٰفِرِينَ', 'ليجزى الذين ءامنوا وعملوا الصلحت من فضله  إنه لا يحب الكفرين', NULL, 409, 'local:hafs-text.json'),
  ('hafs-30-46', 'hafs', 30, 46, 'وَمِنْ ءَايَٰتِهِۦٓ أَن يُرْسِلَ ٱلرِّيَاحَ مُبَشِّرَٰتٍۢ وَلِيُذِيقَكُم مِّن رَّحْمَتِهِۦ وَلِتَجْرِىَ ٱلْفُلْكُ بِأَمْرِهِۦ وَلِتَبْتَغُوا۟ مِن فَضْلِهِۦ وَلَعَلَّكُمْ تَشْكُرُونَ', 'ومن ءايته أن يرسل الرياح مبشرت وليذيقكم من رحمته ولتجرى الفلك بأمره ولتبتغوا من فضله ولعلكم تشكرون', NULL, 409, 'local:hafs-text.json'),
  ('hafs-30-47', 'hafs', 30, 47, 'وَلَقَدْ أَرْسَلْنَا مِن قَبْلِكَ رُسُلًا إِلَىٰ قَوْمِهِمْ فَجَآءُوهُم بِٱلْبَيِّنَٰتِ فَٱنتَقَمْنَا مِنَ ٱلَّذِينَ أَجْرَمُوا۟ ۖ وَكَانَ حَقًّا عَلَيْنَا نَصْرُ ٱلْمُؤْمِنِينَ', 'ولقد أرسلنا من قبلك رسلا إلى قومهم فجاءوهم بالبينت فانتقمنا من الذين أجرموا  وكان حقا علينا نصر المؤمنين', NULL, 409, 'local:hafs-text.json'),
  ('hafs-30-48', 'hafs', 30, 48, 'ٱللَّهُ ٱلَّذِى يُرْسِلُ ٱلرِّيَٰحَ فَتُثِيرُ سَحَابًۭا فَيَبْسُطُهُۥ فِى ٱلسَّمَآءِ كَيْفَ يَشَآءُ وَيَجْعَلُهُۥ كِسَفًۭا فَتَرَى ٱلْوَدْقَ يَخْرُجُ مِنْ خِلَٰلِهِۦ ۖ فَإِذَآ أَصَابَ بِهِۦ مَن يَشَآءُ مِنْ عِبَادِهِۦٓ إِذَا هُمْ يَسْتَبْشِرُونَ', 'الله الذى يرسل الريح فتثير سحابا فيبسطه فى السماء كيف يشاء ويجعله كسفا فترى الودق يخرج من خلله  فإذا أصاب به من يشاء من عباده إذا هم يستبشرون', NULL, 409, 'local:hafs-text.json'),
  ('hafs-30-49', 'hafs', 30, 49, 'وَإِن كَانُوا۟ مِن قَبْلِ أَن يُنَزَّلَ عَلَيْهِم مِّن قَبْلِهِۦ لَمُبْلِسِينَ', 'وإن كانوا من قبل أن ينزل عليهم من قبله لمبلسين', NULL, 409, 'local:hafs-text.json'),
  ('hafs-30-50', 'hafs', 30, 50, 'فَٱنظُرْ إِلَىٰٓ ءَاثَٰرِ رَحْمَتِ ٱللَّهِ كَيْفَ يُحْىِ ٱلْأَرْضَ بَعْدَ مَوْتِهَآ ۚ إِنَّ ذَٰلِكَ لَمُحْىِ ٱلْمَوْتَىٰ ۖ وَهُوَ عَلَىٰ كُلِّ شَىْءٍۢ قَدِيرٌۭ', 'فانظر إلى ءاثر رحمت الله كيف يحى الأرض بعد موتها  إن ذلك لمحى الموتى  وهو على كل شىء قدير', NULL, 409, 'local:hafs-text.json'),
  ('hafs-30-51', 'hafs', 30, 51, 'وَلَئِنْ أَرْسَلْنَا رِيحًۭا فَرَأَوْهُ مُصْفَرًّۭا لَّظَلُّوا۟ مِنۢ بَعْدِهِۦ يَكْفُرُونَ', 'ولئن أرسلنا ريحا فرأوه مصفرا لظلوا من بعده يكفرون', NULL, 410, 'local:hafs-text.json'),
  ('hafs-30-52', 'hafs', 30, 52, 'فَإِنَّكَ لَا تُسْمِعُ ٱلْمَوْتَىٰ وَلَا تُسْمِعُ ٱلصُّمَّ ٱلدُّعَآءَ إِذَا وَلَّوْا۟ مُدْبِرِينَ', 'فإنك لا تسمع الموتى ولا تسمع الصم الدعاء إذا ولوا مدبرين', NULL, 410, 'local:hafs-text.json'),
  ('hafs-30-53', 'hafs', 30, 53, 'وَمَآ أَنتَ بِهَٰدِ ٱلْعُمْىِ عَن ضَلَٰلَتِهِمْ ۖ إِن تُسْمِعُ إِلَّا مَن يُؤْمِنُ بِـَٔايَٰتِنَا فَهُم مُّسْلِمُونَ', 'وما أنت بهد العمى عن ضللتهم  إن تسمع إلا من يؤمن بايتنا فهم مسلمون', NULL, 410, 'local:hafs-text.json'),
  ('hafs-30-54', 'hafs', 30, 54, '۞ ٱللَّهُ ٱلَّذِى خَلَقَكُم مِّن ضَعْفٍۢ ثُمَّ جَعَلَ مِنۢ بَعْدِ ضَعْفٍۢ قُوَّةًۭ ثُمَّ جَعَلَ مِنۢ بَعْدِ قُوَّةٍۢ ضَعْفًۭا وَشَيْبَةًۭ ۚ يَخْلُقُ مَا يَشَآءُ ۖ وَهُوَ ٱلْعَلِيمُ ٱلْقَدِيرُ', 'الله الذى خلقكم من ضعف ثم جعل من بعد ضعف قوة ثم جعل من بعد قوة ضعفا وشيبة  يخلق ما يشاء  وهو العليم القدير', NULL, 410, 'local:hafs-text.json'),
  ('hafs-30-55', 'hafs', 30, 55, 'وَيَوْمَ تَقُومُ ٱلسَّاعَةُ يُقْسِمُ ٱلْمُجْرِمُونَ مَا لَبِثُوا۟ غَيْرَ سَاعَةٍۢ ۚ كَذَٰلِكَ كَانُوا۟ يُؤْفَكُونَ', 'ويوم تقوم الساعة يقسم المجرمون ما لبثوا غير ساعة  كذلك كانوا يؤفكون', NULL, 410, 'local:hafs-text.json'),
  ('hafs-30-56', 'hafs', 30, 56, 'وَقَالَ ٱلَّذِينَ أُوتُوا۟ ٱلْعِلْمَ وَٱلْإِيمَٰنَ لَقَدْ لَبِثْتُمْ فِى كِتَٰبِ ٱللَّهِ إِلَىٰ يَوْمِ ٱلْبَعْثِ ۖ فَهَٰذَا يَوْمُ ٱلْبَعْثِ وَلَٰكِنَّكُمْ كُنتُمْ لَا تَعْلَمُونَ', 'وقال الذين أوتوا العلم والإيمن لقد لبثتم فى كتب الله إلى يوم البعث  فهذا يوم البعث ولكنكم كنتم لا تعلمون', NULL, 410, 'local:hafs-text.json'),
  ('hafs-30-57', 'hafs', 30, 57, 'فَيَوْمَئِذٍۢ لَّا يَنفَعُ ٱلَّذِينَ ظَلَمُوا۟ مَعْذِرَتُهُمْ وَلَا هُمْ يُسْتَعْتَبُونَ', 'فيومئذ لا ينفع الذين ظلموا معذرتهم ولا هم يستعتبون', NULL, 410, 'local:hafs-text.json'),
  ('hafs-30-58', 'hafs', 30, 58, 'وَلَقَدْ ضَرَبْنَا لِلنَّاسِ فِى هَٰذَا ٱلْقُرْءَانِ مِن كُلِّ مَثَلٍۢ ۚ وَلَئِن جِئْتَهُم بِـَٔايَةٍۢ لَّيَقُولَنَّ ٱلَّذِينَ كَفَرُوٓا۟ إِنْ أَنتُمْ إِلَّا مُبْطِلُونَ', 'ولقد ضربنا للناس فى هذا القرءان من كل مثل  ولئن جئتهم باية ليقولن الذين كفروا إن أنتم إلا مبطلون', NULL, 410, 'local:hafs-text.json'),
  ('hafs-30-59', 'hafs', 30, 59, 'كَذَٰلِكَ يَطْبَعُ ٱللَّهُ عَلَىٰ قُلُوبِ ٱلَّذِينَ لَا يَعْلَمُونَ', 'كذلك يطبع الله على قلوب الذين لا يعلمون', NULL, 410, 'local:hafs-text.json'),
  ('hafs-30-60', 'hafs', 30, 60, 'فَٱصْبِرْ إِنَّ وَعْدَ ٱللَّهِ حَقٌّۭ ۖ وَلَا يَسْتَخِفَّنَّكَ ٱلَّذِينَ لَا يُوقِنُونَ', 'فاصبر إن وعد الله حق  ولا يستخفنك الذين لا يوقنون', NULL, 410, 'local:hafs-text.json'),
  ('hafs-31-1', 'hafs', 31, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ الٓمٓ', 'بسم الله الرحمن الرحيم الم', NULL, 411, 'local:hafs-text.json'),
  ('hafs-31-2', 'hafs', 31, 2, 'تِلْكَ ءَايَٰتُ ٱلْكِتَٰبِ ٱلْحَكِيمِ', 'تلك ءايت الكتب الحكيم', NULL, 411, 'local:hafs-text.json'),
  ('hafs-31-3', 'hafs', 31, 3, 'هُدًۭى وَرَحْمَةًۭ لِّلْمُحْسِنِينَ', 'هدى ورحمة للمحسنين', NULL, 411, 'local:hafs-text.json'),
  ('hafs-31-4', 'hafs', 31, 4, 'ٱلَّذِينَ يُقِيمُونَ ٱلصَّلَوٰةَ وَيُؤْتُونَ ٱلزَّكَوٰةَ وَهُم بِٱلْءَاخِرَةِ هُمْ يُوقِنُونَ', 'الذين يقيمون الصلوة ويؤتون الزكوة وهم بالءاخرة هم يوقنون', NULL, 411, 'local:hafs-text.json'),
  ('hafs-31-5', 'hafs', 31, 5, 'أُو۟لَٰٓئِكَ عَلَىٰ هُدًۭى مِّن رَّبِّهِمْ ۖ وَأُو۟لَٰٓئِكَ هُمُ ٱلْمُفْلِحُونَ', 'أولئك على هدى من ربهم  وأولئك هم المفلحون', NULL, 411, 'local:hafs-text.json'),
  ('hafs-31-6', 'hafs', 31, 6, 'وَمِنَ ٱلنَّاسِ مَن يَشْتَرِى لَهْوَ ٱلْحَدِيثِ لِيُضِلَّ عَن سَبِيلِ ٱللَّهِ بِغَيْرِ عِلْمٍۢ وَيَتَّخِذَهَا هُزُوًا ۚ أُو۟لَٰٓئِكَ لَهُمْ عَذَابٌۭ مُّهِينٌۭ', 'ومن الناس من يشترى لهو الحديث ليضل عن سبيل الله بغير علم ويتخذها هزوا  أولئك لهم عذاب مهين', NULL, 411, 'local:hafs-text.json'),
  ('hafs-31-7', 'hafs', 31, 7, 'وَإِذَا تُتْلَىٰ عَلَيْهِ ءَايَٰتُنَا وَلَّىٰ مُسْتَكْبِرًۭا كَأَن لَّمْ يَسْمَعْهَا كَأَنَّ فِىٓ أُذُنَيْهِ وَقْرًۭا ۖ فَبَشِّرْهُ بِعَذَابٍ أَلِيمٍ', 'وإذا تتلى عليه ءايتنا ولى مستكبرا كأن لم يسمعها كأن فى أذنيه وقرا  فبشره بعذاب أليم', NULL, 411, 'local:hafs-text.json'),
  ('hafs-31-8', 'hafs', 31, 8, 'إِنَّ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ لَهُمْ جَنَّٰتُ ٱلنَّعِيمِ', 'إن الذين ءامنوا وعملوا الصلحت لهم جنت النعيم', NULL, 411, 'local:hafs-text.json'),
  ('hafs-31-9', 'hafs', 31, 9, 'خَٰلِدِينَ فِيهَا ۖ وَعْدَ ٱللَّهِ حَقًّۭا ۚ وَهُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ', 'خلدين فيها  وعد الله حقا  وهو العزيز الحكيم', NULL, 411, 'local:hafs-text.json'),
  ('hafs-31-10', 'hafs', 31, 10, 'خَلَقَ ٱلسَّمَٰوَٰتِ بِغَيْرِ عَمَدٍۢ تَرَوْنَهَا ۖ وَأَلْقَىٰ فِى ٱلْأَرْضِ رَوَٰسِىَ أَن تَمِيدَ بِكُمْ وَبَثَّ فِيهَا مِن كُلِّ دَآبَّةٍۢ ۚ وَأَنزَلْنَا مِنَ ٱلسَّمَآءِ مَآءًۭ فَأَنۢبَتْنَا فِيهَا مِن كُلِّ زَوْجٍۢ كَرِيمٍ', 'خلق السموت بغير عمد ترونها  وألقى فى الأرض روسى أن تميد بكم وبث فيها من كل دابة  وأنزلنا من السماء ماء فأنبتنا فيها من كل زوج كريم', NULL, 411, 'local:hafs-text.json'),
  ('hafs-31-11', 'hafs', 31, 11, 'هَٰذَا خَلْقُ ٱللَّهِ فَأَرُونِى مَاذَا خَلَقَ ٱلَّذِينَ مِن دُونِهِۦ ۚ بَلِ ٱلظَّٰلِمُونَ فِى ضَلَٰلٍۢ مُّبِينٍۢ', 'هذا خلق الله فأرونى ماذا خلق الذين من دونه  بل الظلمون فى ضلل مبين', NULL, 411, 'local:hafs-text.json'),
  ('hafs-31-12', 'hafs', 31, 12, 'وَلَقَدْ ءَاتَيْنَا لُقْمَٰنَ ٱلْحِكْمَةَ أَنِ ٱشْكُرْ لِلَّهِ ۚ وَمَن يَشْكُرْ فَإِنَّمَا يَشْكُرُ لِنَفْسِهِۦ ۖ وَمَن كَفَرَ فَإِنَّ ٱللَّهَ غَنِىٌّ حَمِيدٌۭ', 'ولقد ءاتينا لقمن الحكمة أن اشكر لله  ومن يشكر فإنما يشكر لنفسه  ومن كفر فإن الله غنى حميد', NULL, 412, 'local:hafs-text.json'),
  ('hafs-31-13', 'hafs', 31, 13, 'وَإِذْ قَالَ لُقْمَٰنُ لِٱبْنِهِۦ وَهُوَ يَعِظُهُۥ يَٰبُنَىَّ لَا تُشْرِكْ بِٱللَّهِ ۖ إِنَّ ٱلشِّرْكَ لَظُلْمٌ عَظِيمٌۭ', 'وإذ قال لقمن لابنه وهو يعظه يبنى لا تشرك بالله  إن الشرك لظلم عظيم', NULL, 412, 'local:hafs-text.json'),
  ('hafs-31-14', 'hafs', 31, 14, 'وَوَصَّيْنَا ٱلْإِنسَٰنَ بِوَٰلِدَيْهِ حَمَلَتْهُ أُمُّهُۥ وَهْنًا عَلَىٰ وَهْنٍۢ وَفِصَٰلُهُۥ فِى عَامَيْنِ أَنِ ٱشْكُرْ لِى وَلِوَٰلِدَيْكَ إِلَىَّ ٱلْمَصِيرُ', 'ووصينا الإنسن بولديه حملته أمه وهنا على وهن وفصله فى عامين أن اشكر لى ولولديك إلى المصير', NULL, 412, 'local:hafs-text.json'),
  ('hafs-31-15', 'hafs', 31, 15, 'وَإِن جَٰهَدَاكَ عَلَىٰٓ أَن تُشْرِكَ بِى مَا لَيْسَ لَكَ بِهِۦ عِلْمٌۭ فَلَا تُطِعْهُمَا ۖ وَصَاحِبْهُمَا فِى ٱلدُّنْيَا مَعْرُوفًۭا ۖ وَٱتَّبِعْ سَبِيلَ مَنْ أَنَابَ إِلَىَّ ۚ ثُمَّ إِلَىَّ مَرْجِعُكُمْ فَأُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ', 'وإن جهداك على أن تشرك بى ما ليس لك به علم فلا تطعهما  وصاحبهما فى الدنيا معروفا  واتبع سبيل من أناب إلى  ثم إلى مرجعكم فأنبئكم بما كنتم تعملون', NULL, 412, 'local:hafs-text.json'),
  ('hafs-31-16', 'hafs', 31, 16, 'يَٰبُنَىَّ إِنَّهَآ إِن تَكُ مِثْقَالَ حَبَّةٍۢ مِّنْ خَرْدَلٍۢ فَتَكُن فِى صَخْرَةٍ أَوْ فِى ٱلسَّمَٰوَٰتِ أَوْ فِى ٱلْأَرْضِ يَأْتِ بِهَا ٱللَّهُ ۚ إِنَّ ٱللَّهَ لَطِيفٌ خَبِيرٌۭ', 'يبنى إنها إن تك مثقال حبة من خردل فتكن فى صخرة أو فى السموت أو فى الأرض يأت بها الله  إن الله لطيف خبير', NULL, 412, 'local:hafs-text.json'),
  ('hafs-31-17', 'hafs', 31, 17, 'يَٰبُنَىَّ أَقِمِ ٱلصَّلَوٰةَ وَأْمُرْ بِٱلْمَعْرُوفِ وَٱنْهَ عَنِ ٱلْمُنكَرِ وَٱصْبِرْ عَلَىٰ مَآ أَصَابَكَ ۖ إِنَّ ذَٰلِكَ مِنْ عَزْمِ ٱلْأُمُورِ', 'يبنى أقم الصلوة وأمر بالمعروف وانه عن المنكر واصبر على ما أصابك  إن ذلك من عزم الأمور', NULL, 412, 'local:hafs-text.json'),
  ('hafs-31-18', 'hafs', 31, 18, 'وَلَا تُصَعِّرْ خَدَّكَ لِلنَّاسِ وَلَا تَمْشِ فِى ٱلْأَرْضِ مَرَحًا ۖ إِنَّ ٱللَّهَ لَا يُحِبُّ كُلَّ مُخْتَالٍۢ فَخُورٍۢ', 'ولا تصعر خدك للناس ولا تمش فى الأرض مرحا  إن الله لا يحب كل مختال فخور', NULL, 412, 'local:hafs-text.json'),
  ('hafs-31-19', 'hafs', 31, 19, 'وَٱقْصِدْ فِى مَشْيِكَ وَٱغْضُضْ مِن صَوْتِكَ ۚ إِنَّ أَنكَرَ ٱلْأَصْوَٰتِ لَصَوْتُ ٱلْحَمِيرِ', 'واقصد فى مشيك واغضض من صوتك  إن أنكر الأصوت لصوت الحمير', NULL, 412, 'local:hafs-text.json'),
  ('hafs-31-20', 'hafs', 31, 20, 'أَلَمْ تَرَوْا۟ أَنَّ ٱللَّهَ سَخَّرَ لَكُم مَّا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ وَأَسْبَغَ عَلَيْكُمْ نِعَمَهُۥ ظَٰهِرَةًۭ وَبَاطِنَةًۭ ۗ وَمِنَ ٱلنَّاسِ مَن يُجَٰدِلُ فِى ٱللَّهِ بِغَيْرِ عِلْمٍۢ وَلَا هُدًۭى وَلَا كِتَٰبٍۢ مُّنِيرٍۢ', 'ألم تروا أن الله سخر لكم ما فى السموت وما فى الأرض وأسبغ عليكم نعمه ظهرة وباطنة  ومن الناس من يجدل فى الله بغير علم ولا هدى ولا كتب منير', NULL, 413, 'local:hafs-text.json'),
  ('hafs-31-21', 'hafs', 31, 21, 'وَإِذَا قِيلَ لَهُمُ ٱتَّبِعُوا۟ مَآ أَنزَلَ ٱللَّهُ قَالُوا۟ بَلْ نَتَّبِعُ مَا وَجَدْنَا عَلَيْهِ ءَابَآءَنَآ ۚ أَوَلَوْ كَانَ ٱلشَّيْطَٰنُ يَدْعُوهُمْ إِلَىٰ عَذَابِ ٱلسَّعِيرِ', 'وإذا قيل لهم اتبعوا ما أنزل الله قالوا بل نتبع ما وجدنا عليه ءاباءنا  أولو كان الشيطن يدعوهم إلى عذاب السعير', NULL, 413, 'local:hafs-text.json'),
  ('hafs-31-22', 'hafs', 31, 22, '۞ وَمَن يُسْلِمْ وَجْهَهُۥٓ إِلَى ٱللَّهِ وَهُوَ مُحْسِنٌۭ فَقَدِ ٱسْتَمْسَكَ بِٱلْعُرْوَةِ ٱلْوُثْقَىٰ ۗ وَإِلَى ٱللَّهِ عَٰقِبَةُ ٱلْأُمُورِ', 'ومن يسلم وجهه إلى الله وهو محسن فقد استمسك بالعروة الوثقى  وإلى الله عقبة الأمور', NULL, 413, 'local:hafs-text.json'),
  ('hafs-31-23', 'hafs', 31, 23, 'وَمَن كَفَرَ فَلَا يَحْزُنكَ كُفْرُهُۥٓ ۚ إِلَيْنَا مَرْجِعُهُمْ فَنُنَبِّئُهُم بِمَا عَمِلُوٓا۟ ۚ إِنَّ ٱللَّهَ عَلِيمٌۢ بِذَاتِ ٱلصُّدُورِ', 'ومن كفر فلا يحزنك كفره  إلينا مرجعهم فننبئهم بما عملوا  إن الله عليم بذات الصدور', NULL, 413, 'local:hafs-text.json'),
  ('hafs-31-24', 'hafs', 31, 24, 'نُمَتِّعُهُمْ قَلِيلًۭا ثُمَّ نَضْطَرُّهُمْ إِلَىٰ عَذَابٍ غَلِيظٍۢ', 'نمتعهم قليلا ثم نضطرهم إلى عذاب غليظ', NULL, 413, 'local:hafs-text.json'),
  ('hafs-31-25', 'hafs', 31, 25, 'وَلَئِن سَأَلْتَهُم مَّنْ خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ لَيَقُولُنَّ ٱللَّهُ ۚ قُلِ ٱلْحَمْدُ لِلَّهِ ۚ بَلْ أَكْثَرُهُمْ لَا يَعْلَمُونَ', 'ولئن سألتهم من خلق السموت والأرض ليقولن الله  قل الحمد لله  بل أكثرهم لا يعلمون', NULL, 413, 'local:hafs-text.json'),
  ('hafs-31-26', 'hafs', 31, 26, 'لِلَّهِ مَا فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ ۚ إِنَّ ٱللَّهَ هُوَ ٱلْغَنِىُّ ٱلْحَمِيدُ', 'لله ما فى السموت والأرض  إن الله هو الغنى الحميد', NULL, 413, 'local:hafs-text.json'),
  ('hafs-31-27', 'hafs', 31, 27, 'وَلَوْ أَنَّمَا فِى ٱلْأَرْضِ مِن شَجَرَةٍ أَقْلَٰمٌۭ وَٱلْبَحْرُ يَمُدُّهُۥ مِنۢ بَعْدِهِۦ سَبْعَةُ أَبْحُرٍۢ مَّا نَفِدَتْ كَلِمَٰتُ ٱللَّهِ ۗ إِنَّ ٱللَّهَ عَزِيزٌ حَكِيمٌۭ', 'ولو أنما فى الأرض من شجرة أقلم والبحر يمده من بعده سبعة أبحر ما نفدت كلمت الله  إن الله عزيز حكيم', NULL, 413, 'local:hafs-text.json'),
  ('hafs-31-28', 'hafs', 31, 28, 'مَّا خَلْقُكُمْ وَلَا بَعْثُكُمْ إِلَّا كَنَفْسٍۢ وَٰحِدَةٍ ۗ إِنَّ ٱللَّهَ سَمِيعٌۢ بَصِيرٌ', 'ما خلقكم ولا بعثكم إلا كنفس وحدة  إن الله سميع بصير', NULL, 413, 'local:hafs-text.json'),
  ('hafs-31-29', 'hafs', 31, 29, 'أَلَمْ تَرَ أَنَّ ٱللَّهَ يُولِجُ ٱلَّيْلَ فِى ٱلنَّهَارِ وَيُولِجُ ٱلنَّهَارَ فِى ٱلَّيْلِ وَسَخَّرَ ٱلشَّمْسَ وَٱلْقَمَرَ كُلٌّۭ يَجْرِىٓ إِلَىٰٓ أَجَلٍۢ مُّسَمًّۭى وَأَنَّ ٱللَّهَ بِمَا تَعْمَلُونَ خَبِيرٌۭ', 'ألم تر أن الله يولج اليل فى النهار ويولج النهار فى اليل وسخر الشمس والقمر كل يجرى إلى أجل مسمى وأن الله بما تعملون خبير', NULL, 414, 'local:hafs-text.json'),
  ('hafs-31-30', 'hafs', 31, 30, 'ذَٰلِكَ بِأَنَّ ٱللَّهَ هُوَ ٱلْحَقُّ وَأَنَّ مَا يَدْعُونَ مِن دُونِهِ ٱلْبَٰطِلُ وَأَنَّ ٱللَّهَ هُوَ ٱلْعَلِىُّ ٱلْكَبِيرُ', 'ذلك بأن الله هو الحق وأن ما يدعون من دونه البطل وأن الله هو العلى الكبير', NULL, 414, 'local:hafs-text.json'),
  ('hafs-31-31', 'hafs', 31, 31, 'أَلَمْ تَرَ أَنَّ ٱلْفُلْكَ تَجْرِى فِى ٱلْبَحْرِ بِنِعْمَتِ ٱللَّهِ لِيُرِيَكُم مِّنْ ءَايَٰتِهِۦٓ ۚ إِنَّ فِى ذَٰلِكَ لَءَايَٰتٍۢ لِّكُلِّ صَبَّارٍۢ شَكُورٍۢ', 'ألم تر أن الفلك تجرى فى البحر بنعمت الله ليريكم من ءايته  إن فى ذلك لءايت لكل صبار شكور', NULL, 414, 'local:hafs-text.json'),
  ('hafs-31-32', 'hafs', 31, 32, 'وَإِذَا غَشِيَهُم مَّوْجٌۭ كَٱلظُّلَلِ دَعَوُا۟ ٱللَّهَ مُخْلِصِينَ لَهُ ٱلدِّينَ فَلَمَّا نَجَّىٰهُمْ إِلَى ٱلْبَرِّ فَمِنْهُم مُّقْتَصِدٌۭ ۚ وَمَا يَجْحَدُ بِـَٔايَٰتِنَآ إِلَّا كُلُّ خَتَّارٍۢ كَفُورٍۢ', 'وإذا غشيهم موج كالظلل دعوا الله مخلصين له الدين فلما نجىهم إلى البر فمنهم مقتصد  وما يجحد بايتنا إلا كل ختار كفور', NULL, 414, 'local:hafs-text.json'),
  ('hafs-31-33', 'hafs', 31, 33, 'يَٰٓأَيُّهَا ٱلنَّاسُ ٱتَّقُوا۟ رَبَّكُمْ وَٱخْشَوْا۟ يَوْمًۭا لَّا يَجْزِى وَالِدٌ عَن وَلَدِهِۦ وَلَا مَوْلُودٌ هُوَ جَازٍ عَن وَالِدِهِۦ شَيْـًٔا ۚ إِنَّ وَعْدَ ٱللَّهِ حَقٌّۭ ۖ فَلَا تَغُرَّنَّكُمُ ٱلْحَيَوٰةُ ٱلدُّنْيَا وَلَا يَغُرَّنَّكُم بِٱللَّهِ ٱلْغَرُورُ', 'يأيها الناس اتقوا ربكم واخشوا يوما لا يجزى والد عن ولده ولا مولود هو جاز عن والده شيا  إن وعد الله حق  فلا تغرنكم الحيوة الدنيا ولا يغرنكم بالله الغرور', NULL, 414, 'local:hafs-text.json'),
  ('hafs-31-34', 'hafs', 31, 34, 'إِنَّ ٱللَّهَ عِندَهُۥ عِلْمُ ٱلسَّاعَةِ وَيُنَزِّلُ ٱلْغَيْثَ وَيَعْلَمُ مَا فِى ٱلْأَرْحَامِ ۖ وَمَا تَدْرِى نَفْسٌۭ مَّاذَا تَكْسِبُ غَدًۭا ۖ وَمَا تَدْرِى نَفْسٌۢ بِأَىِّ أَرْضٍۢ تَمُوتُ ۚ إِنَّ ٱللَّهَ عَلِيمٌ خَبِيرٌۢ', 'إن الله عنده علم الساعة وينزل الغيث ويعلم ما فى الأرحام  وما تدرى نفس ماذا تكسب غدا  وما تدرى نفس بأى أرض تموت  إن الله عليم خبير', NULL, 414, 'local:hafs-text.json'),
  ('hafs-32-1', 'hafs', 32, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ الٓمٓ', 'بسم الله الرحمن الرحيم الم', NULL, 415, 'local:hafs-text.json'),
  ('hafs-32-2', 'hafs', 32, 2, 'تَنزِيلُ ٱلْكِتَٰبِ لَا رَيْبَ فِيهِ مِن رَّبِّ ٱلْعَٰلَمِينَ', 'تنزيل الكتب لا ريب فيه من رب العلمين', NULL, 415, 'local:hafs-text.json'),
  ('hafs-32-3', 'hafs', 32, 3, 'أَمْ يَقُولُونَ ٱفْتَرَىٰهُ ۚ بَلْ هُوَ ٱلْحَقُّ مِن رَّبِّكَ لِتُنذِرَ قَوْمًۭا مَّآ أَتَىٰهُم مِّن نَّذِيرٍۢ مِّن قَبْلِكَ لَعَلَّهُمْ يَهْتَدُونَ', 'أم يقولون افترىه  بل هو الحق من ربك لتنذر قوما ما أتىهم من نذير من قبلك لعلهم يهتدون', NULL, 415, 'local:hafs-text.json'),
  ('hafs-32-4', 'hafs', 32, 4, 'ٱللَّهُ ٱلَّذِى خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ وَمَا بَيْنَهُمَا فِى سِتَّةِ أَيَّامٍۢ ثُمَّ ٱسْتَوَىٰ عَلَى ٱلْعَرْشِ ۖ مَا لَكُم مِّن دُونِهِۦ مِن وَلِىٍّۢ وَلَا شَفِيعٍ ۚ أَفَلَا تَتَذَكَّرُونَ', 'الله الذى خلق السموت والأرض وما بينهما فى ستة أيام ثم استوى على العرش  ما لكم من دونه من ولى ولا شفيع  أفلا تتذكرون', NULL, 415, 'local:hafs-text.json'),
  ('hafs-32-5', 'hafs', 32, 5, 'يُدَبِّرُ ٱلْأَمْرَ مِنَ ٱلسَّمَآءِ إِلَى ٱلْأَرْضِ ثُمَّ يَعْرُجُ إِلَيْهِ فِى يَوْمٍۢ كَانَ مِقْدَارُهُۥٓ أَلْفَ سَنَةٍۢ مِّمَّا تَعُدُّونَ', 'يدبر الأمر من السماء إلى الأرض ثم يعرج إليه فى يوم كان مقداره ألف سنة مما تعدون', NULL, 415, 'local:hafs-text.json'),
  ('hafs-32-6', 'hafs', 32, 6, 'ذَٰلِكَ عَٰلِمُ ٱلْغَيْبِ وَٱلشَّهَٰدَةِ ٱلْعَزِيزُ ٱلرَّحِيمُ', 'ذلك علم الغيب والشهدة العزيز الرحيم', NULL, 415, 'local:hafs-text.json'),
  ('hafs-32-7', 'hafs', 32, 7, 'ٱلَّذِىٓ أَحْسَنَ كُلَّ شَىْءٍ خَلَقَهُۥ ۖ وَبَدَأَ خَلْقَ ٱلْإِنسَٰنِ مِن طِينٍۢ', 'الذى أحسن كل شىء خلقه  وبدأ خلق الإنسن من طين', NULL, 415, 'local:hafs-text.json'),
  ('hafs-32-8', 'hafs', 32, 8, 'ثُمَّ جَعَلَ نَسْلَهُۥ مِن سُلَٰلَةٍۢ مِّن مَّآءٍۢ مَّهِينٍۢ', 'ثم جعل نسله من سللة من ماء مهين', NULL, 415, 'local:hafs-text.json'),
  ('hafs-32-9', 'hafs', 32, 9, 'ثُمَّ سَوَّىٰهُ وَنَفَخَ فِيهِ مِن رُّوحِهِۦ ۖ وَجَعَلَ لَكُمُ ٱلسَّمْعَ وَٱلْأَبْصَٰرَ وَٱلْأَفْـِٔدَةَ ۚ قَلِيلًۭا مَّا تَشْكُرُونَ', 'ثم سوىه ونفخ فيه من روحه  وجعل لكم السمع والأبصر والأفدة  قليلا ما تشكرون', NULL, 415, 'local:hafs-text.json'),
  ('hafs-32-10', 'hafs', 32, 10, 'وَقَالُوٓا۟ أَءِذَا ضَلَلْنَا فِى ٱلْأَرْضِ أَءِنَّا لَفِى خَلْقٍۢ جَدِيدٍۭ ۚ بَلْ هُم بِلِقَآءِ رَبِّهِمْ كَٰفِرُونَ', 'وقالوا أءذا ضللنا فى الأرض أءنا لفى خلق جديد  بل هم بلقاء ربهم كفرون', NULL, 415, 'local:hafs-text.json'),
  ('hafs-32-11', 'hafs', 32, 11, '۞ قُلْ يَتَوَفَّىٰكُم مَّلَكُ ٱلْمَوْتِ ٱلَّذِى وُكِّلَ بِكُمْ ثُمَّ إِلَىٰ رَبِّكُمْ تُرْجَعُونَ', 'قل يتوفىكم ملك الموت الذى وكل بكم ثم إلى ربكم ترجعون', NULL, 415, 'local:hafs-text.json'),
  ('hafs-32-12', 'hafs', 32, 12, 'وَلَوْ تَرَىٰٓ إِذِ ٱلْمُجْرِمُونَ نَاكِسُوا۟ رُءُوسِهِمْ عِندَ رَبِّهِمْ رَبَّنَآ أَبْصَرْنَا وَسَمِعْنَا فَٱرْجِعْنَا نَعْمَلْ صَٰلِحًا إِنَّا مُوقِنُونَ', 'ولو ترى إذ المجرمون ناكسوا رءوسهم عند ربهم ربنا أبصرنا وسمعنا فارجعنا نعمل صلحا إنا موقنون', NULL, 416, 'local:hafs-text.json'),
  ('hafs-32-13', 'hafs', 32, 13, 'وَلَوْ شِئْنَا لَءَاتَيْنَا كُلَّ نَفْسٍ هُدَىٰهَا وَلَٰكِنْ حَقَّ ٱلْقَوْلُ مِنِّى لَأَمْلَأَنَّ جَهَنَّمَ مِنَ ٱلْجِنَّةِ وَٱلنَّاسِ أَجْمَعِينَ', 'ولو شئنا لءاتينا كل نفس هدىها ولكن حق القول منى لأملأن جهنم من الجنة والناس أجمعين', NULL, 416, 'local:hafs-text.json'),
  ('hafs-32-14', 'hafs', 32, 14, 'فَذُوقُوا۟ بِمَا نَسِيتُمْ لِقَآءَ يَوْمِكُمْ هَٰذَآ إِنَّا نَسِينَٰكُمْ ۖ وَذُوقُوا۟ عَذَابَ ٱلْخُلْدِ بِمَا كُنتُمْ تَعْمَلُونَ', 'فذوقوا بما نسيتم لقاء يومكم هذا إنا نسينكم  وذوقوا عذاب الخلد بما كنتم تعملون', NULL, 416, 'local:hafs-text.json'),
  ('hafs-32-15', 'hafs', 32, 15, 'إِنَّمَا يُؤْمِنُ بِـَٔايَٰتِنَا ٱلَّذِينَ إِذَا ذُكِّرُوا۟ بِهَا خَرُّوا۟ سُجَّدًۭا وَسَبَّحُوا۟ بِحَمْدِ رَبِّهِمْ وَهُمْ لَا يَسْتَكْبِرُونَ ۩', 'إنما يؤمن بايتنا الذين إذا ذكروا بها خروا سجدا وسبحوا بحمد ربهم وهم لا يستكبرون', NULL, 416, 'local:hafs-text.json'),
  ('hafs-32-16', 'hafs', 32, 16, 'تَتَجَافَىٰ جُنُوبُهُمْ عَنِ ٱلْمَضَاجِعِ يَدْعُونَ رَبَّهُمْ خَوْفًۭا وَطَمَعًۭا وَمِمَّا رَزَقْنَٰهُمْ يُنفِقُونَ', 'تتجافى جنوبهم عن المضاجع يدعون ربهم خوفا وطمعا ومما رزقنهم ينفقون', NULL, 416, 'local:hafs-text.json'),
  ('hafs-32-17', 'hafs', 32, 17, 'فَلَا تَعْلَمُ نَفْسٌۭ مَّآ أُخْفِىَ لَهُم مِّن قُرَّةِ أَعْيُنٍۢ جَزَآءًۢ بِمَا كَانُوا۟ يَعْمَلُونَ', 'فلا تعلم نفس ما أخفى لهم من قرة أعين جزاء بما كانوا يعملون', NULL, 416, 'local:hafs-text.json'),
  ('hafs-32-18', 'hafs', 32, 18, 'أَفَمَن كَانَ مُؤْمِنًۭا كَمَن كَانَ فَاسِقًۭا ۚ لَّا يَسْتَوُۥنَ', 'أفمن كان مؤمنا كمن كان فاسقا  لا يستون', NULL, 416, 'local:hafs-text.json'),
  ('hafs-32-19', 'hafs', 32, 19, 'أَمَّا ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ فَلَهُمْ جَنَّٰتُ ٱلْمَأْوَىٰ نُزُلًۢا بِمَا كَانُوا۟ يَعْمَلُونَ', 'أما الذين ءامنوا وعملوا الصلحت فلهم جنت المأوى نزلا بما كانوا يعملون', NULL, 416, 'local:hafs-text.json'),
  ('hafs-32-20', 'hafs', 32, 20, 'وَأَمَّا ٱلَّذِينَ فَسَقُوا۟ فَمَأْوَىٰهُمُ ٱلنَّارُ ۖ كُلَّمَآ أَرَادُوٓا۟ أَن يَخْرُجُوا۟ مِنْهَآ أُعِيدُوا۟ فِيهَا وَقِيلَ لَهُمْ ذُوقُوا۟ عَذَابَ ٱلنَّارِ ٱلَّذِى كُنتُم بِهِۦ تُكَذِّبُونَ', 'وأما الذين فسقوا فمأوىهم النار  كلما أرادوا أن يخرجوا منها أعيدوا فيها وقيل لهم ذوقوا عذاب النار الذى كنتم به تكذبون', NULL, 416, 'local:hafs-text.json'),
  ('hafs-32-21', 'hafs', 32, 21, 'وَلَنُذِيقَنَّهُم مِّنَ ٱلْعَذَابِ ٱلْأَدْنَىٰ دُونَ ٱلْعَذَابِ ٱلْأَكْبَرِ لَعَلَّهُمْ يَرْجِعُونَ', 'ولنذيقنهم من العذاب الأدنى دون العذاب الأكبر لعلهم يرجعون', NULL, 417, 'local:hafs-text.json'),
  ('hafs-32-22', 'hafs', 32, 22, 'وَمَنْ أَظْلَمُ مِمَّن ذُكِّرَ بِـَٔايَٰتِ رَبِّهِۦ ثُمَّ أَعْرَضَ عَنْهَآ ۚ إِنَّا مِنَ ٱلْمُجْرِمِينَ مُنتَقِمُونَ', 'ومن أظلم ممن ذكر بايت ربه ثم أعرض عنها  إنا من المجرمين منتقمون', NULL, 417, 'local:hafs-text.json'),
  ('hafs-32-23', 'hafs', 32, 23, 'وَلَقَدْ ءَاتَيْنَا مُوسَى ٱلْكِتَٰبَ فَلَا تَكُن فِى مِرْيَةٍۢ مِّن لِّقَآئِهِۦ ۖ وَجَعَلْنَٰهُ هُدًۭى لِّبَنِىٓ إِسْرَٰٓءِيلَ', 'ولقد ءاتينا موسى الكتب فلا تكن فى مرية من لقائه  وجعلنه هدى لبنى إسرءيل', NULL, 417, 'local:hafs-text.json'),
  ('hafs-32-24', 'hafs', 32, 24, 'وَجَعَلْنَا مِنْهُمْ أَئِمَّةًۭ يَهْدُونَ بِأَمْرِنَا لَمَّا صَبَرُوا۟ ۖ وَكَانُوا۟ بِـَٔايَٰتِنَا يُوقِنُونَ', 'وجعلنا منهم أئمة يهدون بأمرنا لما صبروا  وكانوا بايتنا يوقنون', NULL, 417, 'local:hafs-text.json'),
  ('hafs-32-25', 'hafs', 32, 25, 'إِنَّ رَبَّكَ هُوَ يَفْصِلُ بَيْنَهُمْ يَوْمَ ٱلْقِيَٰمَةِ فِيمَا كَانُوا۟ فِيهِ يَخْتَلِفُونَ', 'إن ربك هو يفصل بينهم يوم القيمة فيما كانوا فيه يختلفون', NULL, 417, 'local:hafs-text.json'),
  ('hafs-32-26', 'hafs', 32, 26, 'أَوَلَمْ يَهْدِ لَهُمْ كَمْ أَهْلَكْنَا مِن قَبْلِهِم مِّنَ ٱلْقُرُونِ يَمْشُونَ فِى مَسَٰكِنِهِمْ ۚ إِنَّ فِى ذَٰلِكَ لَءَايَٰتٍ ۖ أَفَلَا يَسْمَعُونَ', 'أولم يهد لهم كم أهلكنا من قبلهم من القرون يمشون فى مسكنهم  إن فى ذلك لءايت  أفلا يسمعون', NULL, 417, 'local:hafs-text.json'),
  ('hafs-32-27', 'hafs', 32, 27, 'أَوَلَمْ يَرَوْا۟ أَنَّا نَسُوقُ ٱلْمَآءَ إِلَى ٱلْأَرْضِ ٱلْجُرُزِ فَنُخْرِجُ بِهِۦ زَرْعًۭا تَأْكُلُ مِنْهُ أَنْعَٰمُهُمْ وَأَنفُسُهُمْ ۖ أَفَلَا يُبْصِرُونَ', 'أولم يروا أنا نسوق الماء إلى الأرض الجرز فنخرج به زرعا تأكل منه أنعمهم وأنفسهم  أفلا يبصرون', NULL, 417, 'local:hafs-text.json'),
  ('hafs-32-28', 'hafs', 32, 28, 'وَيَقُولُونَ مَتَىٰ هَٰذَا ٱلْفَتْحُ إِن كُنتُمْ صَٰدِقِينَ', 'ويقولون متى هذا الفتح إن كنتم صدقين', NULL, 417, 'local:hafs-text.json'),
  ('hafs-32-29', 'hafs', 32, 29, 'قُلْ يَوْمَ ٱلْفَتْحِ لَا يَنفَعُ ٱلَّذِينَ كَفَرُوٓا۟ إِيمَٰنُهُمْ وَلَا هُمْ يُنظَرُونَ', 'قل يوم الفتح لا ينفع الذين كفروا إيمنهم ولا هم ينظرون', NULL, 417, 'local:hafs-text.json'),
  ('hafs-32-30', 'hafs', 32, 30, 'فَأَعْرِضْ عَنْهُمْ وَٱنتَظِرْ إِنَّهُم مُّنتَظِرُونَ', 'فأعرض عنهم وانتظر إنهم منتظرون', NULL, 417, 'local:hafs-text.json'),
  ('hafs-33-1', 'hafs', 33, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ يَٰٓأَيُّهَا ٱلنَّبِىُّ ٱتَّقِ ٱللَّهَ وَلَا تُطِعِ ٱلْكَٰفِرِينَ وَٱلْمُنَٰفِقِينَ ۗ إِنَّ ٱللَّهَ كَانَ عَلِيمًا حَكِيمًۭا', 'بسم الله الرحمن الرحيم يأيها النبى اتق الله ولا تطع الكفرين والمنفقين  إن الله كان عليما حكيما', NULL, 418, 'local:hafs-text.json'),
  ('hafs-33-2', 'hafs', 33, 2, 'وَٱتَّبِعْ مَا يُوحَىٰٓ إِلَيْكَ مِن رَّبِّكَ ۚ إِنَّ ٱللَّهَ كَانَ بِمَا تَعْمَلُونَ خَبِيرًۭا', 'واتبع ما يوحى إليك من ربك  إن الله كان بما تعملون خبيرا', NULL, 418, 'local:hafs-text.json'),
  ('hafs-33-3', 'hafs', 33, 3, 'وَتَوَكَّلْ عَلَى ٱللَّهِ ۚ وَكَفَىٰ بِٱللَّهِ وَكِيلًۭا', 'وتوكل على الله  وكفى بالله وكيلا', NULL, 418, 'local:hafs-text.json'),
  ('hafs-33-4', 'hafs', 33, 4, 'مَّا جَعَلَ ٱللَّهُ لِرَجُلٍۢ مِّن قَلْبَيْنِ فِى جَوْفِهِۦ ۚ وَمَا جَعَلَ أَزْوَٰجَكُمُ ٱلَّٰٓـِٔى تُظَٰهِرُونَ مِنْهُنَّ أُمَّهَٰتِكُمْ ۚ وَمَا جَعَلَ أَدْعِيَآءَكُمْ أَبْنَآءَكُمْ ۚ ذَٰلِكُمْ قَوْلُكُم بِأَفْوَٰهِكُمْ ۖ وَٱللَّهُ يَقُولُ ٱلْحَقَّ وَهُوَ يَهْدِى ٱلسَّبِيلَ', 'ما جعل الله لرجل من قلبين فى جوفه  وما جعل أزوجكم الى تظهرون منهن أمهتكم  وما جعل أدعياءكم أبناءكم  ذلكم قولكم بأفوهكم  والله يقول الحق وهو يهدى السبيل', NULL, 418, 'local:hafs-text.json'),
  ('hafs-33-5', 'hafs', 33, 5, 'ٱدْعُوهُمْ لِءَابَآئِهِمْ هُوَ أَقْسَطُ عِندَ ٱللَّهِ ۚ فَإِن لَّمْ تَعْلَمُوٓا۟ ءَابَآءَهُمْ فَإِخْوَٰنُكُمْ فِى ٱلدِّينِ وَمَوَٰلِيكُمْ ۚ وَلَيْسَ عَلَيْكُمْ جُنَاحٌۭ فِيمَآ أَخْطَأْتُم بِهِۦ وَلَٰكِن مَّا تَعَمَّدَتْ قُلُوبُكُمْ ۚ وَكَانَ ٱللَّهُ غَفُورًۭا رَّحِيمًا', 'ادعوهم لءابائهم هو أقسط عند الله  فإن لم تعلموا ءاباءهم فإخونكم فى الدين وموليكم  وليس عليكم جناح فيما أخطأتم به ولكن ما تعمدت قلوبكم  وكان الله غفورا رحيما', NULL, 418, 'local:hafs-text.json'),
  ('hafs-33-6', 'hafs', 33, 6, 'ٱلنَّبِىُّ أَوْلَىٰ بِٱلْمُؤْمِنِينَ مِنْ أَنفُسِهِمْ ۖ وَأَزْوَٰجُهُۥٓ أُمَّهَٰتُهُمْ ۗ وَأُو۟لُوا۟ ٱلْأَرْحَامِ بَعْضُهُمْ أَوْلَىٰ بِبَعْضٍۢ فِى كِتَٰبِ ٱللَّهِ مِنَ ٱلْمُؤْمِنِينَ وَٱلْمُهَٰجِرِينَ إِلَّآ أَن تَفْعَلُوٓا۟ إِلَىٰٓ أَوْلِيَآئِكُم مَّعْرُوفًۭا ۚ كَانَ ذَٰلِكَ فِى ٱلْكِتَٰبِ مَسْطُورًۭا', 'النبى أولى بالمؤمنين من أنفسهم  وأزوجه أمهتهم  وأولوا الأرحام بعضهم أولى ببعض فى كتب الله من المؤمنين والمهجرين إلا أن تفعلوا إلى أوليائكم معروفا  كان ذلك فى الكتب مسطورا', NULL, 418, 'local:hafs-text.json'),
  ('hafs-33-7', 'hafs', 33, 7, 'وَإِذْ أَخَذْنَا مِنَ ٱلنَّبِيِّۦنَ مِيثَٰقَهُمْ وَمِنكَ وَمِن نُّوحٍۢ وَإِبْرَٰهِيمَ وَمُوسَىٰ وَعِيسَى ٱبْنِ مَرْيَمَ ۖ وَأَخَذْنَا مِنْهُم مِّيثَٰقًا غَلِيظًۭا', 'وإذ أخذنا من النبين ميثقهم ومنك ومن نوح وإبرهيم وموسى وعيسى ابن مريم  وأخذنا منهم ميثقا غليظا', NULL, 419, 'local:hafs-text.json'),
  ('hafs-33-8', 'hafs', 33, 8, 'لِّيَسْـَٔلَ ٱلصَّٰدِقِينَ عَن صِدْقِهِمْ ۚ وَأَعَدَّ لِلْكَٰفِرِينَ عَذَابًا أَلِيمًۭا', 'ليسل الصدقين عن صدقهم  وأعد للكفرين عذابا أليما', NULL, 419, 'local:hafs-text.json'),
  ('hafs-33-9', 'hafs', 33, 9, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱذْكُرُوا۟ نِعْمَةَ ٱللَّهِ عَلَيْكُمْ إِذْ جَآءَتْكُمْ جُنُودٌۭ فَأَرْسَلْنَا عَلَيْهِمْ رِيحًۭا وَجُنُودًۭا لَّمْ تَرَوْهَا ۚ وَكَانَ ٱللَّهُ بِمَا تَعْمَلُونَ بَصِيرًا', 'يأيها الذين ءامنوا اذكروا نعمة الله عليكم إذ جاءتكم جنود فأرسلنا عليهم ريحا وجنودا لم تروها  وكان الله بما تعملون بصيرا', NULL, 419, 'local:hafs-text.json'),
  ('hafs-33-10', 'hafs', 33, 10, 'إِذْ جَآءُوكُم مِّن فَوْقِكُمْ وَمِنْ أَسْفَلَ مِنكُمْ وَإِذْ زَاغَتِ ٱلْأَبْصَٰرُ وَبَلَغَتِ ٱلْقُلُوبُ ٱلْحَنَاجِرَ وَتَظُنُّونَ بِٱللَّهِ ٱلظُّنُونَا۠', 'إذ جاءوكم من فوقكم ومن أسفل منكم وإذ زاغت الأبصر وبلغت القلوب الحناجر وتظنون بالله الظنونا', NULL, 419, 'local:hafs-text.json'),
  ('hafs-33-11', 'hafs', 33, 11, 'هُنَالِكَ ٱبْتُلِىَ ٱلْمُؤْمِنُونَ وَزُلْزِلُوا۟ زِلْزَالًۭا شَدِيدًۭا', 'هنالك ابتلى المؤمنون وزلزلوا زلزالا شديدا', NULL, 419, 'local:hafs-text.json'),
  ('hafs-33-12', 'hafs', 33, 12, 'وَإِذْ يَقُولُ ٱلْمُنَٰفِقُونَ وَٱلَّذِينَ فِى قُلُوبِهِم مَّرَضٌۭ مَّا وَعَدَنَا ٱللَّهُ وَرَسُولُهُۥٓ إِلَّا غُرُورًۭا', 'وإذ يقول المنفقون والذين فى قلوبهم مرض ما وعدنا الله ورسوله إلا غرورا', NULL, 419, 'local:hafs-text.json'),
  ('hafs-33-13', 'hafs', 33, 13, 'وَإِذْ قَالَت طَّآئِفَةٌۭ مِّنْهُمْ يَٰٓأَهْلَ يَثْرِبَ لَا مُقَامَ لَكُمْ فَٱرْجِعُوا۟ ۚ وَيَسْتَـْٔذِنُ فَرِيقٌۭ مِّنْهُمُ ٱلنَّبِىَّ يَقُولُونَ إِنَّ بُيُوتَنَا عَوْرَةٌۭ وَمَا هِىَ بِعَوْرَةٍ ۖ إِن يُرِيدُونَ إِلَّا فِرَارًۭا', 'وإذ قالت طائفة منهم يأهل يثرب لا مقام لكم فارجعوا  ويستذن فريق منهم النبى يقولون إن بيوتنا عورة وما هى بعورة  إن يريدون إلا فرارا', NULL, 419, 'local:hafs-text.json'),
  ('hafs-33-14', 'hafs', 33, 14, 'وَلَوْ دُخِلَتْ عَلَيْهِم مِّنْ أَقْطَارِهَا ثُمَّ سُئِلُوا۟ ٱلْفِتْنَةَ لَءَاتَوْهَا وَمَا تَلَبَّثُوا۟ بِهَآ إِلَّا يَسِيرًۭا', 'ولو دخلت عليهم من أقطارها ثم سئلوا الفتنة لءاتوها وما تلبثوا بها إلا يسيرا', NULL, 419, 'local:hafs-text.json'),
  ('hafs-33-15', 'hafs', 33, 15, 'وَلَقَدْ كَانُوا۟ عَٰهَدُوا۟ ٱللَّهَ مِن قَبْلُ لَا يُوَلُّونَ ٱلْأَدْبَٰرَ ۚ وَكَانَ عَهْدُ ٱللَّهِ مَسْـُٔولًۭا', 'ولقد كانوا عهدوا الله من قبل لا يولون الأدبر  وكان عهد الله مسولا', NULL, 419, 'local:hafs-text.json'),
  ('hafs-33-16', 'hafs', 33, 16, 'قُل لَّن يَنفَعَكُمُ ٱلْفِرَارُ إِن فَرَرْتُم مِّنَ ٱلْمَوْتِ أَوِ ٱلْقَتْلِ وَإِذًۭا لَّا تُمَتَّعُونَ إِلَّا قَلِيلًۭا', 'قل لن ينفعكم الفرار إن فررتم من الموت أو القتل وإذا لا تمتعون إلا قليلا', NULL, 420, 'local:hafs-text.json'),
  ('hafs-33-17', 'hafs', 33, 17, 'قُلْ مَن ذَا ٱلَّذِى يَعْصِمُكُم مِّنَ ٱللَّهِ إِنْ أَرَادَ بِكُمْ سُوٓءًا أَوْ أَرَادَ بِكُمْ رَحْمَةًۭ ۚ وَلَا يَجِدُونَ لَهُم مِّن دُونِ ٱللَّهِ وَلِيًّۭا وَلَا نَصِيرًۭا', 'قل من ذا الذى يعصمكم من الله إن أراد بكم سوءا أو أراد بكم رحمة  ولا يجدون لهم من دون الله وليا ولا نصيرا', NULL, 420, 'local:hafs-text.json'),
  ('hafs-33-18', 'hafs', 33, 18, '۞ قَدْ يَعْلَمُ ٱللَّهُ ٱلْمُعَوِّقِينَ مِنكُمْ وَٱلْقَآئِلِينَ لِإِخْوَٰنِهِمْ هَلُمَّ إِلَيْنَا ۖ وَلَا يَأْتُونَ ٱلْبَأْسَ إِلَّا قَلِيلًا', 'قد يعلم الله المعوقين منكم والقائلين لإخونهم هلم إلينا  ولا يأتون البأس إلا قليلا', NULL, 420, 'local:hafs-text.json'),
  ('hafs-33-19', 'hafs', 33, 19, 'أَشِحَّةً عَلَيْكُمْ ۖ فَإِذَا جَآءَ ٱلْخَوْفُ رَأَيْتَهُمْ يَنظُرُونَ إِلَيْكَ تَدُورُ أَعْيُنُهُمْ كَٱلَّذِى يُغْشَىٰ عَلَيْهِ مِنَ ٱلْمَوْتِ ۖ فَإِذَا ذَهَبَ ٱلْخَوْفُ سَلَقُوكُم بِأَلْسِنَةٍ حِدَادٍ أَشِحَّةً عَلَى ٱلْخَيْرِ ۚ أُو۟لَٰٓئِكَ لَمْ يُؤْمِنُوا۟ فَأَحْبَطَ ٱللَّهُ أَعْمَٰلَهُمْ ۚ وَكَانَ ذَٰلِكَ عَلَى ٱللَّهِ يَسِيرًۭا', 'أشحة عليكم  فإذا جاء الخوف رأيتهم ينظرون إليك تدور أعينهم كالذى يغشى عليه من الموت  فإذا ذهب الخوف سلقوكم بألسنة حداد أشحة على الخير  أولئك لم يؤمنوا فأحبط الله أعملهم  وكان ذلك على الله يسيرا', NULL, 420, 'local:hafs-text.json'),
  ('hafs-33-20', 'hafs', 33, 20, 'يَحْسَبُونَ ٱلْأَحْزَابَ لَمْ يَذْهَبُوا۟ ۖ وَإِن يَأْتِ ٱلْأَحْزَابُ يَوَدُّوا۟ لَوْ أَنَّهُم بَادُونَ فِى ٱلْأَعْرَابِ يَسْـَٔلُونَ عَنْ أَنۢبَآئِكُمْ ۖ وَلَوْ كَانُوا۟ فِيكُم مَّا قَٰتَلُوٓا۟ إِلَّا قَلِيلًۭا', 'يحسبون الأحزاب لم يذهبوا  وإن يأت الأحزاب يودوا لو أنهم بادون فى الأعراب يسلون عن أنبائكم  ولو كانوا فيكم ما قتلوا إلا قليلا', NULL, 420, 'local:hafs-text.json'),
  ('hafs-33-21', 'hafs', 33, 21, 'لَّقَدْ كَانَ لَكُمْ فِى رَسُولِ ٱللَّهِ أُسْوَةٌ حَسَنَةٌۭ لِّمَن كَانَ يَرْجُوا۟ ٱللَّهَ وَٱلْيَوْمَ ٱلْءَاخِرَ وَذَكَرَ ٱللَّهَ كَثِيرًۭا', 'لقد كان لكم فى رسول الله أسوة حسنة لمن كان يرجوا الله واليوم الءاخر وذكر الله كثيرا', NULL, 420, 'local:hafs-text.json'),
  ('hafs-33-22', 'hafs', 33, 22, 'وَلَمَّا رَءَا ٱلْمُؤْمِنُونَ ٱلْأَحْزَابَ قَالُوا۟ هَٰذَا مَا وَعَدَنَا ٱللَّهُ وَرَسُولُهُۥ وَصَدَقَ ٱللَّهُ وَرَسُولُهُۥ ۚ وَمَا زَادَهُمْ إِلَّآ إِيمَٰنًۭا وَتَسْلِيمًۭا', 'ولما رءا المؤمنون الأحزاب قالوا هذا ما وعدنا الله ورسوله وصدق الله ورسوله  وما زادهم إلا إيمنا وتسليما', NULL, 420, 'local:hafs-text.json'),
  ('hafs-33-23', 'hafs', 33, 23, 'مِّنَ ٱلْمُؤْمِنِينَ رِجَالٌۭ صَدَقُوا۟ مَا عَٰهَدُوا۟ ٱللَّهَ عَلَيْهِ ۖ فَمِنْهُم مَّن قَضَىٰ نَحْبَهُۥ وَمِنْهُم مَّن يَنتَظِرُ ۖ وَمَا بَدَّلُوا۟ تَبْدِيلًۭا', 'من المؤمنين رجال صدقوا ما عهدوا الله عليه  فمنهم من قضى نحبه ومنهم من ينتظر  وما بدلوا تبديلا', NULL, 421, 'local:hafs-text.json'),
  ('hafs-33-24', 'hafs', 33, 24, 'لِّيَجْزِىَ ٱللَّهُ ٱلصَّٰدِقِينَ بِصِدْقِهِمْ وَيُعَذِّبَ ٱلْمُنَٰفِقِينَ إِن شَآءَ أَوْ يَتُوبَ عَلَيْهِمْ ۚ إِنَّ ٱللَّهَ كَانَ غَفُورًۭا رَّحِيمًۭا', 'ليجزى الله الصدقين بصدقهم ويعذب المنفقين إن شاء أو يتوب عليهم  إن الله كان غفورا رحيما', NULL, 421, 'local:hafs-text.json'),
  ('hafs-33-25', 'hafs', 33, 25, 'وَرَدَّ ٱللَّهُ ٱلَّذِينَ كَفَرُوا۟ بِغَيْظِهِمْ لَمْ يَنَالُوا۟ خَيْرًۭا ۚ وَكَفَى ٱللَّهُ ٱلْمُؤْمِنِينَ ٱلْقِتَالَ ۚ وَكَانَ ٱللَّهُ قَوِيًّا عَزِيزًۭا', 'ورد الله الذين كفروا بغيظهم لم ينالوا خيرا  وكفى الله المؤمنين القتال  وكان الله قويا عزيزا', NULL, 421, 'local:hafs-text.json'),
  ('hafs-33-26', 'hafs', 33, 26, 'وَأَنزَلَ ٱلَّذِينَ ظَٰهَرُوهُم مِّنْ أَهْلِ ٱلْكِتَٰبِ مِن صَيَاصِيهِمْ وَقَذَفَ فِى قُلُوبِهِمُ ٱلرُّعْبَ فَرِيقًۭا تَقْتُلُونَ وَتَأْسِرُونَ فَرِيقًۭا', 'وأنزل الذين ظهروهم من أهل الكتب من صياصيهم وقذف فى قلوبهم الرعب فريقا تقتلون وتأسرون فريقا', NULL, 421, 'local:hafs-text.json'),
  ('hafs-33-27', 'hafs', 33, 27, 'وَأَوْرَثَكُمْ أَرْضَهُمْ وَدِيَٰرَهُمْ وَأَمْوَٰلَهُمْ وَأَرْضًۭا لَّمْ تَطَـُٔوهَا ۚ وَكَانَ ٱللَّهُ عَلَىٰ كُلِّ شَىْءٍۢ قَدِيرًۭا', 'وأورثكم أرضهم وديرهم وأمولهم وأرضا لم تطوها  وكان الله على كل شىء قديرا', NULL, 421, 'local:hafs-text.json'),
  ('hafs-33-28', 'hafs', 33, 28, 'يَٰٓأَيُّهَا ٱلنَّبِىُّ قُل لِّأَزْوَٰجِكَ إِن كُنتُنَّ تُرِدْنَ ٱلْحَيَوٰةَ ٱلدُّنْيَا وَزِينَتَهَا فَتَعَالَيْنَ أُمَتِّعْكُنَّ وَأُسَرِّحْكُنَّ سَرَاحًۭا جَمِيلًۭا', 'يأيها النبى قل لأزوجك إن كنتن تردن الحيوة الدنيا وزينتها فتعالين أمتعكن وأسرحكن سراحا جميلا', NULL, 421, 'local:hafs-text.json'),
  ('hafs-33-29', 'hafs', 33, 29, 'وَإِن كُنتُنَّ تُرِدْنَ ٱللَّهَ وَرَسُولَهُۥ وَٱلدَّارَ ٱلْءَاخِرَةَ فَإِنَّ ٱللَّهَ أَعَدَّ لِلْمُحْسِنَٰتِ مِنكُنَّ أَجْرًا عَظِيمًۭا', 'وإن كنتن تردن الله ورسوله والدار الءاخرة فإن الله أعد للمحسنت منكن أجرا عظيما', NULL, 421, 'local:hafs-text.json'),
  ('hafs-33-30', 'hafs', 33, 30, 'يَٰنِسَآءَ ٱلنَّبِىِّ مَن يَأْتِ مِنكُنَّ بِفَٰحِشَةٍۢ مُّبَيِّنَةٍۢ يُضَٰعَفْ لَهَا ٱلْعَذَابُ ضِعْفَيْنِ ۚ وَكَانَ ذَٰلِكَ عَلَى ٱللَّهِ يَسِيرًۭا', 'ينساء النبى من يأت منكن بفحشة مبينة يضعف لها العذاب ضعفين  وكان ذلك على الله يسيرا', NULL, 421, 'local:hafs-text.json'),
  ('hafs-33-31', 'hafs', 33, 31, '۞ وَمَن يَقْنُتْ مِنكُنَّ لِلَّهِ وَرَسُولِهِۦ وَتَعْمَلْ صَٰلِحًۭا نُّؤْتِهَآ أَجْرَهَا مَرَّتَيْنِ وَأَعْتَدْنَا لَهَا رِزْقًۭا كَرِيمًۭا', 'ومن يقنت منكن لله ورسوله وتعمل صلحا نؤتها أجرها مرتين وأعتدنا لها رزقا كريما', NULL, 422, 'local:hafs-text.json'),
  ('hafs-33-32', 'hafs', 33, 32, 'يَٰنِسَآءَ ٱلنَّبِىِّ لَسْتُنَّ كَأَحَدٍۢ مِّنَ ٱلنِّسَآءِ ۚ إِنِ ٱتَّقَيْتُنَّ فَلَا تَخْضَعْنَ بِٱلْقَوْلِ فَيَطْمَعَ ٱلَّذِى فِى قَلْبِهِۦ مَرَضٌۭ وَقُلْنَ قَوْلًۭا مَّعْرُوفًۭا', 'ينساء النبى لستن كأحد من النساء  إن اتقيتن فلا تخضعن بالقول فيطمع الذى فى قلبه مرض وقلن قولا معروفا', NULL, 422, 'local:hafs-text.json'),
  ('hafs-33-33', 'hafs', 33, 33, 'وَقَرْنَ فِى بُيُوتِكُنَّ وَلَا تَبَرَّجْنَ تَبَرُّجَ ٱلْجَٰهِلِيَّةِ ٱلْأُولَىٰ ۖ وَأَقِمْنَ ٱلصَّلَوٰةَ وَءَاتِينَ ٱلزَّكَوٰةَ وَأَطِعْنَ ٱللَّهَ وَرَسُولَهُۥٓ ۚ إِنَّمَا يُرِيدُ ٱللَّهُ لِيُذْهِبَ عَنكُمُ ٱلرِّجْسَ أَهْلَ ٱلْبَيْتِ وَيُطَهِّرَكُمْ تَطْهِيرًۭا', 'وقرن فى بيوتكن ولا تبرجن تبرج الجهلية الأولى  وأقمن الصلوة وءاتين الزكوة وأطعن الله ورسوله  إنما يريد الله ليذهب عنكم الرجس أهل البيت ويطهركم تطهيرا', NULL, 422, 'local:hafs-text.json'),
  ('hafs-33-34', 'hafs', 33, 34, 'وَٱذْكُرْنَ مَا يُتْلَىٰ فِى بُيُوتِكُنَّ مِنْ ءَايَٰتِ ٱللَّهِ وَٱلْحِكْمَةِ ۚ إِنَّ ٱللَّهَ كَانَ لَطِيفًا خَبِيرًا', 'واذكرن ما يتلى فى بيوتكن من ءايت الله والحكمة  إن الله كان لطيفا خبيرا', NULL, 422, 'local:hafs-text.json'),
  ('hafs-33-35', 'hafs', 33, 35, 'إِنَّ ٱلْمُسْلِمِينَ وَٱلْمُسْلِمَٰتِ وَٱلْمُؤْمِنِينَ وَٱلْمُؤْمِنَٰتِ وَٱلْقَٰنِتِينَ وَٱلْقَٰنِتَٰتِ وَٱلصَّٰدِقِينَ وَٱلصَّٰدِقَٰتِ وَٱلصَّٰبِرِينَ وَٱلصَّٰبِرَٰتِ وَٱلْخَٰشِعِينَ وَٱلْخَٰشِعَٰتِ وَٱلْمُتَصَدِّقِينَ وَٱلْمُتَصَدِّقَٰتِ وَٱلصَّٰٓئِمِينَ وَٱلصَّٰٓئِمَٰتِ وَٱلْحَٰفِظِينَ فُرُوجَهُمْ وَٱلْحَٰفِظَٰتِ وَٱلذَّٰكِرِينَ ٱللَّهَ كَثِيرًۭا وَٱلذَّٰكِرَٰتِ أَعَدَّ ٱللَّهُ لَهُم مَّغْفِرَةًۭ وَأَجْرًا عَظِيمًۭا', 'إن المسلمين والمسلمت والمؤمنين والمؤمنت والقنتين والقنتت والصدقين والصدقت والصبرين والصبرت والخشعين والخشعت والمتصدقين والمتصدقت والصئمين والصئمت والحفظين فروجهم والحفظت والذكرين الله كثيرا والذكرت أعد الله لهم مغفرة وأجرا عظيما', NULL, 422, 'local:hafs-text.json'),
  ('hafs-33-36', 'hafs', 33, 36, 'وَمَا كَانَ لِمُؤْمِنٍۢ وَلَا مُؤْمِنَةٍ إِذَا قَضَى ٱللَّهُ وَرَسُولُهُۥٓ أَمْرًا أَن يَكُونَ لَهُمُ ٱلْخِيَرَةُ مِنْ أَمْرِهِمْ ۗ وَمَن يَعْصِ ٱللَّهَ وَرَسُولَهُۥ فَقَدْ ضَلَّ ضَلَٰلًۭا مُّبِينًۭا', 'وما كان لمؤمن ولا مؤمنة إذا قضى الله ورسوله أمرا أن يكون لهم الخيرة من أمرهم  ومن يعص الله ورسوله فقد ضل ضللا مبينا', NULL, 423, 'local:hafs-text.json'),
  ('hafs-33-37', 'hafs', 33, 37, 'وَإِذْ تَقُولُ لِلَّذِىٓ أَنْعَمَ ٱللَّهُ عَلَيْهِ وَأَنْعَمْتَ عَلَيْهِ أَمْسِكْ عَلَيْكَ زَوْجَكَ وَٱتَّقِ ٱللَّهَ وَتُخْفِى فِى نَفْسِكَ مَا ٱللَّهُ مُبْدِيهِ وَتَخْشَى ٱلنَّاسَ وَٱللَّهُ أَحَقُّ أَن تَخْشَىٰهُ ۖ فَلَمَّا قَضَىٰ زَيْدٌۭ مِّنْهَا وَطَرًۭا زَوَّجْنَٰكَهَا لِكَىْ لَا يَكُونَ عَلَى ٱلْمُؤْمِنِينَ حَرَجٌۭ فِىٓ أَزْوَٰجِ أَدْعِيَآئِهِمْ إِذَا قَضَوْا۟ مِنْهُنَّ وَطَرًۭا ۚ وَكَانَ أَمْرُ ٱللَّهِ مَفْعُولًۭا', 'وإذ تقول للذى أنعم الله عليه وأنعمت عليه أمسك عليك زوجك واتق الله وتخفى فى نفسك ما الله مبديه وتخشى الناس والله أحق أن تخشىه  فلما قضى زيد منها وطرا زوجنكها لكى لا يكون على المؤمنين حرج فى أزوج أدعيائهم إذا قضوا منهن وطرا  وكان أمر الله مفعولا', NULL, 423, 'local:hafs-text.json'),
  ('hafs-33-38', 'hafs', 33, 38, 'مَّا كَانَ عَلَى ٱلنَّبِىِّ مِنْ حَرَجٍۢ فِيمَا فَرَضَ ٱللَّهُ لَهُۥ ۖ سُنَّةَ ٱللَّهِ فِى ٱلَّذِينَ خَلَوْا۟ مِن قَبْلُ ۚ وَكَانَ أَمْرُ ٱللَّهِ قَدَرًۭا مَّقْدُورًا', 'ما كان على النبى من حرج فيما فرض الله له  سنة الله فى الذين خلوا من قبل  وكان أمر الله قدرا مقدورا', NULL, 423, 'local:hafs-text.json'),
  ('hafs-33-39', 'hafs', 33, 39, 'ٱلَّذِينَ يُبَلِّغُونَ رِسَٰلَٰتِ ٱللَّهِ وَيَخْشَوْنَهُۥ وَلَا يَخْشَوْنَ أَحَدًا إِلَّا ٱللَّهَ ۗ وَكَفَىٰ بِٱللَّهِ حَسِيبًۭا', 'الذين يبلغون رسلت الله ويخشونه ولا يخشون أحدا إلا الله  وكفى بالله حسيبا', NULL, 423, 'local:hafs-text.json'),
  ('hafs-33-40', 'hafs', 33, 40, 'مَّا كَانَ مُحَمَّدٌ أَبَآ أَحَدٍۢ مِّن رِّجَالِكُمْ وَلَٰكِن رَّسُولَ ٱللَّهِ وَخَاتَمَ ٱلنَّبِيِّۦنَ ۗ وَكَانَ ٱللَّهُ بِكُلِّ شَىْءٍ عَلِيمًۭا', 'ما كان محمد أبا أحد من رجالكم ولكن رسول الله وخاتم النبين  وكان الله بكل شىء عليما', NULL, 423, 'local:hafs-text.json'),
  ('hafs-33-41', 'hafs', 33, 41, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱذْكُرُوا۟ ٱللَّهَ ذِكْرًۭا كَثِيرًۭا', 'يأيها الذين ءامنوا اذكروا الله ذكرا كثيرا', NULL, 423, 'local:hafs-text.json'),
  ('hafs-33-42', 'hafs', 33, 42, 'وَسَبِّحُوهُ بُكْرَةًۭ وَأَصِيلًا', 'وسبحوه بكرة وأصيلا', NULL, 423, 'local:hafs-text.json'),
  ('hafs-33-43', 'hafs', 33, 43, 'هُوَ ٱلَّذِى يُصَلِّى عَلَيْكُمْ وَمَلَٰٓئِكَتُهُۥ لِيُخْرِجَكُم مِّنَ ٱلظُّلُمَٰتِ إِلَى ٱلنُّورِ ۚ وَكَانَ بِٱلْمُؤْمِنِينَ رَحِيمًۭا', 'هو الذى يصلى عليكم وملئكته ليخرجكم من الظلمت إلى النور  وكان بالمؤمنين رحيما', NULL, 423, 'local:hafs-text.json'),
  ('hafs-33-44', 'hafs', 33, 44, 'تَحِيَّتُهُمْ يَوْمَ يَلْقَوْنَهُۥ سَلَٰمٌۭ ۚ وَأَعَدَّ لَهُمْ أَجْرًۭا كَرِيمًۭا', 'تحيتهم يوم يلقونه سلم  وأعد لهم أجرا كريما', NULL, 424, 'local:hafs-text.json'),
  ('hafs-33-45', 'hafs', 33, 45, 'يَٰٓأَيُّهَا ٱلنَّبِىُّ إِنَّآ أَرْسَلْنَٰكَ شَٰهِدًۭا وَمُبَشِّرًۭا وَنَذِيرًۭا', 'يأيها النبى إنا أرسلنك شهدا ومبشرا ونذيرا', NULL, 424, 'local:hafs-text.json'),
  ('hafs-33-46', 'hafs', 33, 46, 'وَدَاعِيًا إِلَى ٱللَّهِ بِإِذْنِهِۦ وَسِرَاجًۭا مُّنِيرًۭا', 'وداعيا إلى الله بإذنه وسراجا منيرا', NULL, 424, 'local:hafs-text.json'),
  ('hafs-33-47', 'hafs', 33, 47, 'وَبَشِّرِ ٱلْمُؤْمِنِينَ بِأَنَّ لَهُم مِّنَ ٱللَّهِ فَضْلًۭا كَبِيرًۭا', 'وبشر المؤمنين بأن لهم من الله فضلا كبيرا', NULL, 424, 'local:hafs-text.json'),
  ('hafs-33-48', 'hafs', 33, 48, 'وَلَا تُطِعِ ٱلْكَٰفِرِينَ وَٱلْمُنَٰفِقِينَ وَدَعْ أَذَىٰهُمْ وَتَوَكَّلْ عَلَى ٱللَّهِ ۚ وَكَفَىٰ بِٱللَّهِ وَكِيلًۭا', 'ولا تطع الكفرين والمنفقين ودع أذىهم وتوكل على الله  وكفى بالله وكيلا', NULL, 424, 'local:hafs-text.json'),
  ('hafs-33-49', 'hafs', 33, 49, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِذَا نَكَحْتُمُ ٱلْمُؤْمِنَٰتِ ثُمَّ طَلَّقْتُمُوهُنَّ مِن قَبْلِ أَن تَمَسُّوهُنَّ فَمَا لَكُمْ عَلَيْهِنَّ مِنْ عِدَّةٍۢ تَعْتَدُّونَهَا ۖ فَمَتِّعُوهُنَّ وَسَرِّحُوهُنَّ سَرَاحًۭا جَمِيلًۭا', 'يأيها الذين ءامنوا إذا نكحتم المؤمنت ثم طلقتموهن من قبل أن تمسوهن فما لكم عليهن من عدة تعتدونها  فمتعوهن وسرحوهن سراحا جميلا', NULL, 424, 'local:hafs-text.json'),
  ('hafs-33-50', 'hafs', 33, 50, 'يَٰٓأَيُّهَا ٱلنَّبِىُّ إِنَّآ أَحْلَلْنَا لَكَ أَزْوَٰجَكَ ٱلَّٰتِىٓ ءَاتَيْتَ أُجُورَهُنَّ وَمَا مَلَكَتْ يَمِينُكَ مِمَّآ أَفَآءَ ٱللَّهُ عَلَيْكَ وَبَنَاتِ عَمِّكَ وَبَنَاتِ عَمَّٰتِكَ وَبَنَاتِ خَالِكَ وَبَنَاتِ خَٰلَٰتِكَ ٱلَّٰتِى هَاجَرْنَ مَعَكَ وَٱمْرَأَةًۭ مُّؤْمِنَةً إِن وَهَبَتْ نَفْسَهَا لِلنَّبِىِّ إِنْ أَرَادَ ٱلنَّبِىُّ أَن يَسْتَنكِحَهَا خَالِصَةًۭ لَّكَ مِن دُونِ ٱلْمُؤْمِنِينَ ۗ قَدْ عَلِمْنَا مَا فَرَضْنَا عَلَيْهِمْ فِىٓ أَزْوَٰجِهِمْ وَمَا مَلَكَتْ أَيْمَٰنُهُمْ لِكَيْلَا يَكُونَ عَلَيْكَ حَرَجٌۭ ۗ وَكَانَ ٱللَّهُ غَفُورًۭا رَّحِيمًۭا', 'يأيها النبى إنا أحللنا لك أزوجك التى ءاتيت أجورهن وما ملكت يمينك مما أفاء الله عليك وبنات عمك وبنات عمتك وبنات خالك وبنات خلتك التى هاجرن معك وامرأة مؤمنة إن وهبت نفسها للنبى إن أراد النبى أن يستنكحها خالصة لك من دون المؤمنين  قد علمنا ما فرضنا عليهم فى أزوجهم وما ملكت أيمنهم لكيلا يكون عليك حرج  وكان الله غفورا رحيما', NULL, 424, 'local:hafs-text.json'),
  ('hafs-33-51', 'hafs', 33, 51, '۞ تُرْجِى مَن تَشَآءُ مِنْهُنَّ وَتُـْٔوِىٓ إِلَيْكَ مَن تَشَآءُ ۖ وَمَنِ ٱبْتَغَيْتَ مِمَّنْ عَزَلْتَ فَلَا جُنَاحَ عَلَيْكَ ۚ ذَٰلِكَ أَدْنَىٰٓ أَن تَقَرَّ أَعْيُنُهُنَّ وَلَا يَحْزَنَّ وَيَرْضَيْنَ بِمَآ ءَاتَيْتَهُنَّ كُلُّهُنَّ ۚ وَٱللَّهُ يَعْلَمُ مَا فِى قُلُوبِكُمْ ۚ وَكَانَ ٱللَّهُ عَلِيمًا حَلِيمًۭا', 'ترجى من تشاء منهن وتوى إليك من تشاء  ومن ابتغيت ممن عزلت فلا جناح عليك  ذلك أدنى أن تقر أعينهن ولا يحزن ويرضين بما ءاتيتهن كلهن  والله يعلم ما فى قلوبكم  وكان الله عليما حليما', NULL, 425, 'local:hafs-text.json'),
  ('hafs-33-52', 'hafs', 33, 52, 'لَّا يَحِلُّ لَكَ ٱلنِّسَآءُ مِنۢ بَعْدُ وَلَآ أَن تَبَدَّلَ بِهِنَّ مِنْ أَزْوَٰجٍۢ وَلَوْ أَعْجَبَكَ حُسْنُهُنَّ إِلَّا مَا مَلَكَتْ يَمِينُكَ ۗ وَكَانَ ٱللَّهُ عَلَىٰ كُلِّ شَىْءٍۢ رَّقِيبًۭا', 'لا يحل لك النساء من بعد ولا أن تبدل بهن من أزوج ولو أعجبك حسنهن إلا ما ملكت يمينك  وكان الله على كل شىء رقيبا', NULL, 425, 'local:hafs-text.json'),
  ('hafs-33-53', 'hafs', 33, 53, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَدْخُلُوا۟ بُيُوتَ ٱلنَّبِىِّ إِلَّآ أَن يُؤْذَنَ لَكُمْ إِلَىٰ طَعَامٍ غَيْرَ نَٰظِرِينَ إِنَىٰهُ وَلَٰكِنْ إِذَا دُعِيتُمْ فَٱدْخُلُوا۟ فَإِذَا طَعِمْتُمْ فَٱنتَشِرُوا۟ وَلَا مُسْتَـْٔنِسِينَ لِحَدِيثٍ ۚ إِنَّ ذَٰلِكُمْ كَانَ يُؤْذِى ٱلنَّبِىَّ فَيَسْتَحْىِۦ مِنكُمْ ۖ وَٱللَّهُ لَا يَسْتَحْىِۦ مِنَ ٱلْحَقِّ ۚ وَإِذَا سَأَلْتُمُوهُنَّ مَتَٰعًۭا فَسْـَٔلُوهُنَّ مِن وَرَآءِ حِجَابٍۢ ۚ ذَٰلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ ۚ وَمَا كَانَ لَكُمْ أَن تُؤْذُوا۟ رَسُولَ ٱللَّهِ وَلَآ أَن تَنكِحُوٓا۟ أَزْوَٰجَهُۥ مِنۢ بَعْدِهِۦٓ أَبَدًا ۚ إِنَّ ذَٰلِكُمْ كَانَ عِندَ ٱللَّهِ عَظِيمًا', 'يأيها الذين ءامنوا لا تدخلوا بيوت النبى إلا أن يؤذن لكم إلى طعام غير نظرين إنىه ولكن إذا دعيتم فادخلوا فإذا طعمتم فانتشروا ولا مستنسين لحديث  إن ذلكم كان يؤذى النبى فيستحى منكم  والله لا يستحى من الحق  وإذا سألتموهن متعا فسلوهن من وراء حجاب  ذلكم أطهر لقلوبكم وقلوبهن  وما كان لكم أن تؤذوا رسول الله ولا أن تنكحوا أزوجه من بعده أبدا  إن ذلكم كان عند الله عظيما', NULL, 425, 'local:hafs-text.json'),
  ('hafs-33-54', 'hafs', 33, 54, 'إِن تُبْدُوا۟ شَيْـًٔا أَوْ تُخْفُوهُ فَإِنَّ ٱللَّهَ كَانَ بِكُلِّ شَىْءٍ عَلِيمًۭا', 'إن تبدوا شيا أو تخفوه فإن الله كان بكل شىء عليما', NULL, 425, 'local:hafs-text.json'),
  ('hafs-33-55', 'hafs', 33, 55, 'لَّا جُنَاحَ عَلَيْهِنَّ فِىٓ ءَابَآئِهِنَّ وَلَآ أَبْنَآئِهِنَّ وَلَآ إِخْوَٰنِهِنَّ وَلَآ أَبْنَآءِ إِخْوَٰنِهِنَّ وَلَآ أَبْنَآءِ أَخَوَٰتِهِنَّ وَلَا نِسَآئِهِنَّ وَلَا مَا مَلَكَتْ أَيْمَٰنُهُنَّ ۗ وَٱتَّقِينَ ٱللَّهَ ۚ إِنَّ ٱللَّهَ كَانَ عَلَىٰ كُلِّ شَىْءٍۢ شَهِيدًا', 'لا جناح عليهن فى ءابائهن ولا أبنائهن ولا إخونهن ولا أبناء إخونهن ولا أبناء أخوتهن ولا نسائهن ولا ما ملكت أيمنهن  واتقين الله  إن الله كان على كل شىء شهيدا', NULL, 426, 'local:hafs-text.json'),
  ('hafs-33-56', 'hafs', 33, 56, 'إِنَّ ٱللَّهَ وَمَلَٰٓئِكَتَهُۥ يُصَلُّونَ عَلَى ٱلنَّبِىِّ ۚ يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ صَلُّوا۟ عَلَيْهِ وَسَلِّمُوا۟ تَسْلِيمًا', 'إن الله وملئكته يصلون على النبى  يأيها الذين ءامنوا صلوا عليه وسلموا تسليما', NULL, 426, 'local:hafs-text.json'),
  ('hafs-33-57', 'hafs', 33, 57, 'إِنَّ ٱلَّذِينَ يُؤْذُونَ ٱللَّهَ وَرَسُولَهُۥ لَعَنَهُمُ ٱللَّهُ فِى ٱلدُّنْيَا وَٱلْءَاخِرَةِ وَأَعَدَّ لَهُمْ عَذَابًۭا مُّهِينًۭا', 'إن الذين يؤذون الله ورسوله لعنهم الله فى الدنيا والءاخرة وأعد لهم عذابا مهينا', NULL, 426, 'local:hafs-text.json'),
  ('hafs-33-58', 'hafs', 33, 58, 'وَٱلَّذِينَ يُؤْذُونَ ٱلْمُؤْمِنِينَ وَٱلْمُؤْمِنَٰتِ بِغَيْرِ مَا ٱكْتَسَبُوا۟ فَقَدِ ٱحْتَمَلُوا۟ بُهْتَٰنًۭا وَإِثْمًۭا مُّبِينًۭا', 'والذين يؤذون المؤمنين والمؤمنت بغير ما اكتسبوا فقد احتملوا بهتنا وإثما مبينا', NULL, 426, 'local:hafs-text.json'),
  ('hafs-33-59', 'hafs', 33, 59, 'يَٰٓأَيُّهَا ٱلنَّبِىُّ قُل لِّأَزْوَٰجِكَ وَبَنَاتِكَ وَنِسَآءِ ٱلْمُؤْمِنِينَ يُدْنِينَ عَلَيْهِنَّ مِن جَلَٰبِيبِهِنَّ ۚ ذَٰلِكَ أَدْنَىٰٓ أَن يُعْرَفْنَ فَلَا يُؤْذَيْنَ ۗ وَكَانَ ٱللَّهُ غَفُورًۭا رَّحِيمًۭا', 'يأيها النبى قل لأزوجك وبناتك ونساء المؤمنين يدنين عليهن من جلبيبهن  ذلك أدنى أن يعرفن فلا يؤذين  وكان الله غفورا رحيما', NULL, 426, 'local:hafs-text.json'),
  ('hafs-33-60', 'hafs', 33, 60, '۞ لَّئِن لَّمْ يَنتَهِ ٱلْمُنَٰفِقُونَ وَٱلَّذِينَ فِى قُلُوبِهِم مَّرَضٌۭ وَٱلْمُرْجِفُونَ فِى ٱلْمَدِينَةِ لَنُغْرِيَنَّكَ بِهِمْ ثُمَّ لَا يُجَاوِرُونَكَ فِيهَآ إِلَّا قَلِيلًۭا', 'لئن لم ينته المنفقون والذين فى قلوبهم مرض والمرجفون فى المدينة لنغرينك بهم ثم لا يجاورونك فيها إلا قليلا', NULL, 426, 'local:hafs-text.json'),
  ('hafs-33-61', 'hafs', 33, 61, 'مَّلْعُونِينَ ۖ أَيْنَمَا ثُقِفُوٓا۟ أُخِذُوا۟ وَقُتِّلُوا۟ تَقْتِيلًۭا', 'ملعونين  أينما ثقفوا أخذوا وقتلوا تقتيلا', NULL, 426, 'local:hafs-text.json'),
  ('hafs-33-62', 'hafs', 33, 62, 'سُنَّةَ ٱللَّهِ فِى ٱلَّذِينَ خَلَوْا۟ مِن قَبْلُ ۖ وَلَن تَجِدَ لِسُنَّةِ ٱللَّهِ تَبْدِيلًۭا', 'سنة الله فى الذين خلوا من قبل  ولن تجد لسنة الله تبديلا', NULL, 426, 'local:hafs-text.json'),
  ('hafs-33-63', 'hafs', 33, 63, 'يَسْـَٔلُكَ ٱلنَّاسُ عَنِ ٱلسَّاعَةِ ۖ قُلْ إِنَّمَا عِلْمُهَا عِندَ ٱللَّهِ ۚ وَمَا يُدْرِيكَ لَعَلَّ ٱلسَّاعَةَ تَكُونُ قَرِيبًا', 'يسلك الناس عن الساعة  قل إنما علمها عند الله  وما يدريك لعل الساعة تكون قريبا', NULL, 427, 'local:hafs-text.json'),
  ('hafs-33-64', 'hafs', 33, 64, 'إِنَّ ٱللَّهَ لَعَنَ ٱلْكَٰفِرِينَ وَأَعَدَّ لَهُمْ سَعِيرًا', 'إن الله لعن الكفرين وأعد لهم سعيرا', NULL, 427, 'local:hafs-text.json'),
  ('hafs-33-65', 'hafs', 33, 65, 'خَٰلِدِينَ فِيهَآ أَبَدًۭا ۖ لَّا يَجِدُونَ وَلِيًّۭا وَلَا نَصِيرًۭا', 'خلدين فيها أبدا  لا يجدون وليا ولا نصيرا', NULL, 427, 'local:hafs-text.json'),
  ('hafs-33-66', 'hafs', 33, 66, 'يَوْمَ تُقَلَّبُ وُجُوهُهُمْ فِى ٱلنَّارِ يَقُولُونَ يَٰلَيْتَنَآ أَطَعْنَا ٱللَّهَ وَأَطَعْنَا ٱلرَّسُولَا۠', 'يوم تقلب وجوههم فى النار يقولون يليتنا أطعنا الله وأطعنا الرسولا', NULL, 427, 'local:hafs-text.json'),
  ('hafs-33-67', 'hafs', 33, 67, 'وَقَالُوا۟ رَبَّنَآ إِنَّآ أَطَعْنَا سَادَتَنَا وَكُبَرَآءَنَا فَأَضَلُّونَا ٱلسَّبِيلَا۠', 'وقالوا ربنا إنا أطعنا سادتنا وكبراءنا فأضلونا السبيلا', NULL, 427, 'local:hafs-text.json')
insert into public.ayahs (id, riwayah, surah_number, ayah_number, text, simple_text, juz, page, source) values
  ('hafs-33-68', 'hafs', 33, 68, 'رَبَّنَآ ءَاتِهِمْ ضِعْفَيْنِ مِنَ ٱلْعَذَابِ وَٱلْعَنْهُمْ لَعْنًۭا كَبِيرًۭا', 'ربنا ءاتهم ضعفين من العذاب والعنهم لعنا كبيرا', NULL, 427, 'local:hafs-text.json'),
  ('hafs-33-69', 'hafs', 33, 69, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَكُونُوا۟ كَٱلَّذِينَ ءَاذَوْا۟ مُوسَىٰ فَبَرَّأَهُ ٱللَّهُ مِمَّا قَالُوا۟ ۚ وَكَانَ عِندَ ٱللَّهِ وَجِيهًۭا', 'يأيها الذين ءامنوا لا تكونوا كالذين ءاذوا موسى فبرأه الله مما قالوا  وكان عند الله وجيها', NULL, 427, 'local:hafs-text.json'),
  ('hafs-33-70', 'hafs', 33, 70, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱتَّقُوا۟ ٱللَّهَ وَقُولُوا۟ قَوْلًۭا سَدِيدًۭا', 'يأيها الذين ءامنوا اتقوا الله وقولوا قولا سديدا', NULL, 427, 'local:hafs-text.json'),
  ('hafs-33-71', 'hafs', 33, 71, 'يُصْلِحْ لَكُمْ أَعْمَٰلَكُمْ وَيَغْفِرْ لَكُمْ ذُنُوبَكُمْ ۗ وَمَن يُطِعِ ٱللَّهَ وَرَسُولَهُۥ فَقَدْ فَازَ فَوْزًا عَظِيمًا', 'يصلح لكم أعملكم ويغفر لكم ذنوبكم  ومن يطع الله ورسوله فقد فاز فوزا عظيما', NULL, 427, 'local:hafs-text.json'),
  ('hafs-33-72', 'hafs', 33, 72, 'إِنَّا عَرَضْنَا ٱلْأَمَانَةَ عَلَى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَٱلْجِبَالِ فَأَبَيْنَ أَن يَحْمِلْنَهَا وَأَشْفَقْنَ مِنْهَا وَحَمَلَهَا ٱلْإِنسَٰنُ ۖ إِنَّهُۥ كَانَ ظَلُومًۭا جَهُولًۭا', 'إنا عرضنا الأمانة على السموت والأرض والجبال فأبين أن يحملنها وأشفقن منها وحملها الإنسن  إنه كان ظلوما جهولا', NULL, 427, 'local:hafs-text.json'),
  ('hafs-33-73', 'hafs', 33, 73, 'لِّيُعَذِّبَ ٱللَّهُ ٱلْمُنَٰفِقِينَ وَٱلْمُنَٰفِقَٰتِ وَٱلْمُشْرِكِينَ وَٱلْمُشْرِكَٰتِ وَيَتُوبَ ٱللَّهُ عَلَى ٱلْمُؤْمِنِينَ وَٱلْمُؤْمِنَٰتِ ۗ وَكَانَ ٱللَّهُ غَفُورًۭا رَّحِيمًۢا', 'ليعذب الله المنفقين والمنفقت والمشركين والمشركت ويتوب الله على المؤمنين والمؤمنت  وكان الله غفورا رحيما', NULL, 427, 'local:hafs-text.json'),
  ('hafs-34-1', 'hafs', 34, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ ٱلْحَمْدُ لِلَّهِ ٱلَّذِى لَهُۥ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ وَلَهُ ٱلْحَمْدُ فِى ٱلْءَاخِرَةِ ۚ وَهُوَ ٱلْحَكِيمُ ٱلْخَبِيرُ', 'بسم الله الرحمن الرحيم الحمد لله الذى له ما فى السموت وما فى الأرض وله الحمد فى الءاخرة  وهو الحكيم الخبير', NULL, 428, 'local:hafs-text.json'),
  ('hafs-34-2', 'hafs', 34, 2, 'يَعْلَمُ مَا يَلِجُ فِى ٱلْأَرْضِ وَمَا يَخْرُجُ مِنْهَا وَمَا يَنزِلُ مِنَ ٱلسَّمَآءِ وَمَا يَعْرُجُ فِيهَا ۚ وَهُوَ ٱلرَّحِيمُ ٱلْغَفُورُ', 'يعلم ما يلج فى الأرض وما يخرج منها وما ينزل من السماء وما يعرج فيها  وهو الرحيم الغفور', NULL, 428, 'local:hafs-text.json'),
  ('hafs-34-3', 'hafs', 34, 3, 'وَقَالَ ٱلَّذِينَ كَفَرُوا۟ لَا تَأْتِينَا ٱلسَّاعَةُ ۖ قُلْ بَلَىٰ وَرَبِّى لَتَأْتِيَنَّكُمْ عَٰلِمِ ٱلْغَيْبِ ۖ لَا يَعْزُبُ عَنْهُ مِثْقَالُ ذَرَّةٍۢ فِى ٱلسَّمَٰوَٰتِ وَلَا فِى ٱلْأَرْضِ وَلَآ أَصْغَرُ مِن ذَٰلِكَ وَلَآ أَكْبَرُ إِلَّا فِى كِتَٰبٍۢ مُّبِينٍۢ', 'وقال الذين كفروا لا تأتينا الساعة  قل بلى وربى لتأتينكم علم الغيب  لا يعزب عنه مثقال ذرة فى السموت ولا فى الأرض ولا أصغر من ذلك ولا أكبر إلا فى كتب مبين', NULL, 428, 'local:hafs-text.json'),
  ('hafs-34-4', 'hafs', 34, 4, 'لِّيَجْزِىَ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ ۚ أُو۟لَٰٓئِكَ لَهُم مَّغْفِرَةٌۭ وَرِزْقٌۭ كَرِيمٌۭ', 'ليجزى الذين ءامنوا وعملوا الصلحت  أولئك لهم مغفرة ورزق كريم', NULL, 428, 'local:hafs-text.json'),
  ('hafs-34-5', 'hafs', 34, 5, 'وَٱلَّذِينَ سَعَوْ فِىٓ ءَايَٰتِنَا مُعَٰجِزِينَ أُو۟لَٰٓئِكَ لَهُمْ عَذَابٌۭ مِّن رِّجْزٍ أَلِيمٌۭ', 'والذين سعو فى ءايتنا معجزين أولئك لهم عذاب من رجز أليم', NULL, 428, 'local:hafs-text.json'),
  ('hafs-34-6', 'hafs', 34, 6, 'وَيَرَى ٱلَّذِينَ أُوتُوا۟ ٱلْعِلْمَ ٱلَّذِىٓ أُنزِلَ إِلَيْكَ مِن رَّبِّكَ هُوَ ٱلْحَقَّ وَيَهْدِىٓ إِلَىٰ صِرَٰطِ ٱلْعَزِيزِ ٱلْحَمِيدِ', 'ويرى الذين أوتوا العلم الذى أنزل إليك من ربك هو الحق ويهدى إلى صرط العزيز الحميد', NULL, 428, 'local:hafs-text.json'),
  ('hafs-34-7', 'hafs', 34, 7, 'وَقَالَ ٱلَّذِينَ كَفَرُوا۟ هَلْ نَدُلُّكُمْ عَلَىٰ رَجُلٍۢ يُنَبِّئُكُمْ إِذَا مُزِّقْتُمْ كُلَّ مُمَزَّقٍ إِنَّكُمْ لَفِى خَلْقٍۢ جَدِيدٍ', 'وقال الذين كفروا هل ندلكم على رجل ينبئكم إذا مزقتم كل ممزق إنكم لفى خلق جديد', NULL, 428, 'local:hafs-text.json'),
  ('hafs-34-8', 'hafs', 34, 8, 'أَفْتَرَىٰ عَلَى ٱللَّهِ كَذِبًا أَم بِهِۦ جِنَّةٌۢ ۗ بَلِ ٱلَّذِينَ لَا يُؤْمِنُونَ بِٱلْءَاخِرَةِ فِى ٱلْعَذَابِ وَٱلضَّلَٰلِ ٱلْبَعِيدِ', 'أفترى على الله كذبا أم به جنة  بل الذين لا يؤمنون بالءاخرة فى العذاب والضلل البعيد', NULL, 429, 'local:hafs-text.json'),
  ('hafs-34-9', 'hafs', 34, 9, 'أَفَلَمْ يَرَوْا۟ إِلَىٰ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُم مِّنَ ٱلسَّمَآءِ وَٱلْأَرْضِ ۚ إِن نَّشَأْ نَخْسِفْ بِهِمُ ٱلْأَرْضَ أَوْ نُسْقِطْ عَلَيْهِمْ كِسَفًۭا مِّنَ ٱلسَّمَآءِ ۚ إِنَّ فِى ذَٰلِكَ لَءَايَةًۭ لِّكُلِّ عَبْدٍۢ مُّنِيبٍۢ', 'أفلم يروا إلى ما بين أيديهم وما خلفهم من السماء والأرض  إن نشأ نخسف بهم الأرض أو نسقط عليهم كسفا من السماء  إن فى ذلك لءاية لكل عبد منيب', NULL, 429, 'local:hafs-text.json'),
  ('hafs-34-10', 'hafs', 34, 10, '۞ وَلَقَدْ ءَاتَيْنَا دَاوُۥدَ مِنَّا فَضْلًۭا ۖ يَٰجِبَالُ أَوِّبِى مَعَهُۥ وَٱلطَّيْرَ ۖ وَأَلَنَّا لَهُ ٱلْحَدِيدَ', 'ولقد ءاتينا داود منا فضلا  يجبال أوبى معه والطير  وألنا له الحديد', NULL, 429, 'local:hafs-text.json'),
  ('hafs-34-11', 'hafs', 34, 11, 'أَنِ ٱعْمَلْ سَٰبِغَٰتٍۢ وَقَدِّرْ فِى ٱلسَّرْدِ ۖ وَٱعْمَلُوا۟ صَٰلِحًا ۖ إِنِّى بِمَا تَعْمَلُونَ بَصِيرٌۭ', 'أن اعمل سبغت وقدر فى السرد  واعملوا صلحا  إنى بما تعملون بصير', NULL, 429, 'local:hafs-text.json'),
  ('hafs-34-12', 'hafs', 34, 12, 'وَلِسُلَيْمَٰنَ ٱلرِّيحَ غُدُوُّهَا شَهْرٌۭ وَرَوَاحُهَا شَهْرٌۭ ۖ وَأَسَلْنَا لَهُۥ عَيْنَ ٱلْقِطْرِ ۖ وَمِنَ ٱلْجِنِّ مَن يَعْمَلُ بَيْنَ يَدَيْهِ بِإِذْنِ رَبِّهِۦ ۖ وَمَن يَزِغْ مِنْهُمْ عَنْ أَمْرِنَا نُذِقْهُ مِنْ عَذَابِ ٱلسَّعِيرِ', 'ولسليمن الريح غدوها شهر ورواحها شهر  وأسلنا له عين القطر  ومن الجن من يعمل بين يديه بإذن ربه  ومن يزغ منهم عن أمرنا نذقه من عذاب السعير', NULL, 429, 'local:hafs-text.json'),
  ('hafs-34-13', 'hafs', 34, 13, 'يَعْمَلُونَ لَهُۥ مَا يَشَآءُ مِن مَّحَٰرِيبَ وَتَمَٰثِيلَ وَجِفَانٍۢ كَٱلْجَوَابِ وَقُدُورٍۢ رَّاسِيَٰتٍ ۚ ٱعْمَلُوٓا۟ ءَالَ دَاوُۥدَ شُكْرًۭا ۚ وَقَلِيلٌۭ مِّنْ عِبَادِىَ ٱلشَّكُورُ', 'يعملون له ما يشاء من محريب وتمثيل وجفان كالجواب وقدور راسيت  اعملوا ءال داود شكرا  وقليل من عبادى الشكور', NULL, 429, 'local:hafs-text.json'),
  ('hafs-34-14', 'hafs', 34, 14, 'فَلَمَّا قَضَيْنَا عَلَيْهِ ٱلْمَوْتَ مَا دَلَّهُمْ عَلَىٰ مَوْتِهِۦٓ إِلَّا دَآبَّةُ ٱلْأَرْضِ تَأْكُلُ مِنسَأَتَهُۥ ۖ فَلَمَّا خَرَّ تَبَيَّنَتِ ٱلْجِنُّ أَن لَّوْ كَانُوا۟ يَعْلَمُونَ ٱلْغَيْبَ مَا لَبِثُوا۟ فِى ٱلْعَذَابِ ٱلْمُهِينِ', 'فلما قضينا عليه الموت ما دلهم على موته إلا دابة الأرض تأكل منسأته  فلما خر تبينت الجن أن لو كانوا يعلمون الغيب ما لبثوا فى العذاب المهين', NULL, 429, 'local:hafs-text.json'),
  ('hafs-34-15', 'hafs', 34, 15, 'لَقَدْ كَانَ لِسَبَإٍۢ فِى مَسْكَنِهِمْ ءَايَةٌۭ ۖ جَنَّتَانِ عَن يَمِينٍۢ وَشِمَالٍۢ ۖ كُلُوا۟ مِن رِّزْقِ رَبِّكُمْ وَٱشْكُرُوا۟ لَهُۥ ۚ بَلْدَةٌۭ طَيِّبَةٌۭ وَرَبٌّ غَفُورٌۭ', 'لقد كان لسبإ فى مسكنهم ءاية  جنتان عن يمين وشمال  كلوا من رزق ربكم واشكروا له  بلدة طيبة ورب غفور', NULL, 430, 'local:hafs-text.json'),
  ('hafs-34-16', 'hafs', 34, 16, 'فَأَعْرَضُوا۟ فَأَرْسَلْنَا عَلَيْهِمْ سَيْلَ ٱلْعَرِمِ وَبَدَّلْنَٰهُم بِجَنَّتَيْهِمْ جَنَّتَيْنِ ذَوَاتَىْ أُكُلٍ خَمْطٍۢ وَأَثْلٍۢ وَشَىْءٍۢ مِّن سِدْرٍۢ قَلِيلٍۢ', 'فأعرضوا فأرسلنا عليهم سيل العرم وبدلنهم بجنتيهم جنتين ذواتى أكل خمط وأثل وشىء من سدر قليل', NULL, 430, 'local:hafs-text.json'),
  ('hafs-34-17', 'hafs', 34, 17, 'ذَٰلِكَ جَزَيْنَٰهُم بِمَا كَفَرُوا۟ ۖ وَهَلْ نُجَٰزِىٓ إِلَّا ٱلْكَفُورَ', 'ذلك جزينهم بما كفروا  وهل نجزى إلا الكفور', NULL, 430, 'local:hafs-text.json'),
  ('hafs-34-18', 'hafs', 34, 18, 'وَجَعَلْنَا بَيْنَهُمْ وَبَيْنَ ٱلْقُرَى ٱلَّتِى بَٰرَكْنَا فِيهَا قُرًۭى ظَٰهِرَةًۭ وَقَدَّرْنَا فِيهَا ٱلسَّيْرَ ۖ سِيرُوا۟ فِيهَا لَيَالِىَ وَأَيَّامًا ءَامِنِينَ', 'وجعلنا بينهم وبين القرى التى بركنا فيها قرى ظهرة وقدرنا فيها السير  سيروا فيها ليالى وأياما ءامنين', NULL, 430, 'local:hafs-text.json'),
  ('hafs-34-19', 'hafs', 34, 19, 'فَقَالُوا۟ رَبَّنَا بَٰعِدْ بَيْنَ أَسْفَارِنَا وَظَلَمُوٓا۟ أَنفُسَهُمْ فَجَعَلْنَٰهُمْ أَحَادِيثَ وَمَزَّقْنَٰهُمْ كُلَّ مُمَزَّقٍ ۚ إِنَّ فِى ذَٰلِكَ لَءَايَٰتٍۢ لِّكُلِّ صَبَّارٍۢ شَكُورٍۢ', 'فقالوا ربنا بعد بين أسفارنا وظلموا أنفسهم فجعلنهم أحاديث ومزقنهم كل ممزق  إن فى ذلك لءايت لكل صبار شكور', NULL, 430, 'local:hafs-text.json'),
  ('hafs-34-20', 'hafs', 34, 20, 'وَلَقَدْ صَدَّقَ عَلَيْهِمْ إِبْلِيسُ ظَنَّهُۥ فَٱتَّبَعُوهُ إِلَّا فَرِيقًۭا مِّنَ ٱلْمُؤْمِنِينَ', 'ولقد صدق عليهم إبليس ظنه فاتبعوه إلا فريقا من المؤمنين', NULL, 430, 'local:hafs-text.json'),
  ('hafs-34-21', 'hafs', 34, 21, 'وَمَا كَانَ لَهُۥ عَلَيْهِم مِّن سُلْطَٰنٍ إِلَّا لِنَعْلَمَ مَن يُؤْمِنُ بِٱلْءَاخِرَةِ مِمَّنْ هُوَ مِنْهَا فِى شَكٍّۢ ۗ وَرَبُّكَ عَلَىٰ كُلِّ شَىْءٍ حَفِيظٌۭ', 'وما كان له عليهم من سلطن إلا لنعلم من يؤمن بالءاخرة ممن هو منها فى شك  وربك على كل شىء حفيظ', NULL, 430, 'local:hafs-text.json'),
  ('hafs-34-22', 'hafs', 34, 22, 'قُلِ ٱدْعُوا۟ ٱلَّذِينَ زَعَمْتُم مِّن دُونِ ٱللَّهِ ۖ لَا يَمْلِكُونَ مِثْقَالَ ذَرَّةٍۢ فِى ٱلسَّمَٰوَٰتِ وَلَا فِى ٱلْأَرْضِ وَمَا لَهُمْ فِيهِمَا مِن شِرْكٍۢ وَمَا لَهُۥ مِنْهُم مِّن ظَهِيرٍۢ', 'قل ادعوا الذين زعمتم من دون الله  لا يملكون مثقال ذرة فى السموت ولا فى الأرض وما لهم فيهما من شرك وما له منهم من ظهير', NULL, 430, 'local:hafs-text.json'),
  ('hafs-34-23', 'hafs', 34, 23, 'وَلَا تَنفَعُ ٱلشَّفَٰعَةُ عِندَهُۥٓ إِلَّا لِمَنْ أَذِنَ لَهُۥ ۚ حَتَّىٰٓ إِذَا فُزِّعَ عَن قُلُوبِهِمْ قَالُوا۟ مَاذَا قَالَ رَبُّكُمْ ۖ قَالُوا۟ ٱلْحَقَّ ۖ وَهُوَ ٱلْعَلِىُّ ٱلْكَبِيرُ', 'ولا تنفع الشفعة عنده إلا لمن أذن له  حتى إذا فزع عن قلوبهم قالوا ماذا قال ربكم  قالوا الحق  وهو العلى الكبير', NULL, 431, 'local:hafs-text.json'),
  ('hafs-34-24', 'hafs', 34, 24, '۞ قُلْ مَن يَرْزُقُكُم مِّنَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ ۖ قُلِ ٱللَّهُ ۖ وَإِنَّآ أَوْ إِيَّاكُمْ لَعَلَىٰ هُدًى أَوْ فِى ضَلَٰلٍۢ مُّبِينٍۢ', 'قل من يرزقكم من السموت والأرض  قل الله  وإنا أو إياكم لعلى هدى أو فى ضلل مبين', NULL, 431, 'local:hafs-text.json'),
  ('hafs-34-25', 'hafs', 34, 25, 'قُل لَّا تُسْـَٔلُونَ عَمَّآ أَجْرَمْنَا وَلَا نُسْـَٔلُ عَمَّا تَعْمَلُونَ', 'قل لا تسلون عما أجرمنا ولا نسل عما تعملون', NULL, 431, 'local:hafs-text.json'),
  ('hafs-34-26', 'hafs', 34, 26, 'قُلْ يَجْمَعُ بَيْنَنَا رَبُّنَا ثُمَّ يَفْتَحُ بَيْنَنَا بِٱلْحَقِّ وَهُوَ ٱلْفَتَّاحُ ٱلْعَلِيمُ', 'قل يجمع بيننا ربنا ثم يفتح بيننا بالحق وهو الفتاح العليم', NULL, 431, 'local:hafs-text.json'),
  ('hafs-34-27', 'hafs', 34, 27, 'قُلْ أَرُونِىَ ٱلَّذِينَ أَلْحَقْتُم بِهِۦ شُرَكَآءَ ۖ كَلَّا ۚ بَلْ هُوَ ٱللَّهُ ٱلْعَزِيزُ ٱلْحَكِيمُ', 'قل أرونى الذين ألحقتم به شركاء  كلا  بل هو الله العزيز الحكيم', NULL, 431, 'local:hafs-text.json'),
  ('hafs-34-28', 'hafs', 34, 28, 'وَمَآ أَرْسَلْنَٰكَ إِلَّا كَآفَّةًۭ لِّلنَّاسِ بَشِيرًۭا وَنَذِيرًۭا وَلَٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يَعْلَمُونَ', 'وما أرسلنك إلا كافة للناس بشيرا ونذيرا ولكن أكثر الناس لا يعلمون', NULL, 431, 'local:hafs-text.json'),
  ('hafs-34-29', 'hafs', 34, 29, 'وَيَقُولُونَ مَتَىٰ هَٰذَا ٱلْوَعْدُ إِن كُنتُمْ صَٰدِقِينَ', 'ويقولون متى هذا الوعد إن كنتم صدقين', NULL, 431, 'local:hafs-text.json'),
  ('hafs-34-30', 'hafs', 34, 30, 'قُل لَّكُم مِّيعَادُ يَوْمٍۢ لَّا تَسْتَـْٔخِرُونَ عَنْهُ سَاعَةًۭ وَلَا تَسْتَقْدِمُونَ', 'قل لكم ميعاد يوم لا تستخرون عنه ساعة ولا تستقدمون', NULL, 431, 'local:hafs-text.json'),
  ('hafs-34-31', 'hafs', 34, 31, 'وَقَالَ ٱلَّذِينَ كَفَرُوا۟ لَن نُّؤْمِنَ بِهَٰذَا ٱلْقُرْءَانِ وَلَا بِٱلَّذِى بَيْنَ يَدَيْهِ ۗ وَلَوْ تَرَىٰٓ إِذِ ٱلظَّٰلِمُونَ مَوْقُوفُونَ عِندَ رَبِّهِمْ يَرْجِعُ بَعْضُهُمْ إِلَىٰ بَعْضٍ ٱلْقَوْلَ يَقُولُ ٱلَّذِينَ ٱسْتُضْعِفُوا۟ لِلَّذِينَ ٱسْتَكْبَرُوا۟ لَوْلَآ أَنتُمْ لَكُنَّا مُؤْمِنِينَ', 'وقال الذين كفروا لن نؤمن بهذا القرءان ولا بالذى بين يديه  ولو ترى إذ الظلمون موقوفون عند ربهم يرجع بعضهم إلى بعض القول يقول الذين استضعفوا للذين استكبروا لولا أنتم لكنا مؤمنين', NULL, 431, 'local:hafs-text.json'),
  ('hafs-34-32', 'hafs', 34, 32, 'قَالَ ٱلَّذِينَ ٱسْتَكْبَرُوا۟ لِلَّذِينَ ٱسْتُضْعِفُوٓا۟ أَنَحْنُ صَدَدْنَٰكُمْ عَنِ ٱلْهُدَىٰ بَعْدَ إِذْ جَآءَكُم ۖ بَلْ كُنتُم مُّجْرِمِينَ', 'قال الذين استكبروا للذين استضعفوا أنحن صددنكم عن الهدى بعد إذ جاءكم  بل كنتم مجرمين', NULL, 432, 'local:hafs-text.json'),
  ('hafs-34-33', 'hafs', 34, 33, 'وَقَالَ ٱلَّذِينَ ٱسْتُضْعِفُوا۟ لِلَّذِينَ ٱسْتَكْبَرُوا۟ بَلْ مَكْرُ ٱلَّيْلِ وَٱلنَّهَارِ إِذْ تَأْمُرُونَنَآ أَن نَّكْفُرَ بِٱللَّهِ وَنَجْعَلَ لَهُۥٓ أَندَادًۭا ۚ وَأَسَرُّوا۟ ٱلنَّدَامَةَ لَمَّا رَأَوُا۟ ٱلْعَذَابَ وَجَعَلْنَا ٱلْأَغْلَٰلَ فِىٓ أَعْنَاقِ ٱلَّذِينَ كَفَرُوا۟ ۚ هَلْ يُجْزَوْنَ إِلَّا مَا كَانُوا۟ يَعْمَلُونَ', 'وقال الذين استضعفوا للذين استكبروا بل مكر اليل والنهار إذ تأمروننا أن نكفر بالله ونجعل له أندادا  وأسروا الندامة لما رأوا العذاب وجعلنا الأغلل فى أعناق الذين كفروا  هل يجزون إلا ما كانوا يعملون', NULL, 432, 'local:hafs-text.json'),
  ('hafs-34-34', 'hafs', 34, 34, 'وَمَآ أَرْسَلْنَا فِى قَرْيَةٍۢ مِّن نَّذِيرٍ إِلَّا قَالَ مُتْرَفُوهَآ إِنَّا بِمَآ أُرْسِلْتُم بِهِۦ كَٰفِرُونَ', 'وما أرسلنا فى قرية من نذير إلا قال مترفوها إنا بما أرسلتم به كفرون', NULL, 432, 'local:hafs-text.json'),
  ('hafs-34-35', 'hafs', 34, 35, 'وَقَالُوا۟ نَحْنُ أَكْثَرُ أَمْوَٰلًۭا وَأَوْلَٰدًۭا وَمَا نَحْنُ بِمُعَذَّبِينَ', 'وقالوا نحن أكثر أمولا وأولدا وما نحن بمعذبين', NULL, 432, 'local:hafs-text.json'),
  ('hafs-34-36', 'hafs', 34, 36, 'قُلْ إِنَّ رَبِّى يَبْسُطُ ٱلرِّزْقَ لِمَن يَشَآءُ وَيَقْدِرُ وَلَٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يَعْلَمُونَ', 'قل إن ربى يبسط الرزق لمن يشاء ويقدر ولكن أكثر الناس لا يعلمون', NULL, 432, 'local:hafs-text.json'),
  ('hafs-34-37', 'hafs', 34, 37, 'وَمَآ أَمْوَٰلُكُمْ وَلَآ أَوْلَٰدُكُم بِٱلَّتِى تُقَرِّبُكُمْ عِندَنَا زُلْفَىٰٓ إِلَّا مَنْ ءَامَنَ وَعَمِلَ صَٰلِحًۭا فَأُو۟لَٰٓئِكَ لَهُمْ جَزَآءُ ٱلضِّعْفِ بِمَا عَمِلُوا۟ وَهُمْ فِى ٱلْغُرُفَٰتِ ءَامِنُونَ', 'وما أمولكم ولا أولدكم بالتى تقربكم عندنا زلفى إلا من ءامن وعمل صلحا فأولئك لهم جزاء الضعف بما عملوا وهم فى الغرفت ءامنون', NULL, 432, 'local:hafs-text.json'),
  ('hafs-34-38', 'hafs', 34, 38, 'وَٱلَّذِينَ يَسْعَوْنَ فِىٓ ءَايَٰتِنَا مُعَٰجِزِينَ أُو۟لَٰٓئِكَ فِى ٱلْعَذَابِ مُحْضَرُونَ', 'والذين يسعون فى ءايتنا معجزين أولئك فى العذاب محضرون', NULL, 432, 'local:hafs-text.json'),
  ('hafs-34-39', 'hafs', 34, 39, 'قُلْ إِنَّ رَبِّى يَبْسُطُ ٱلرِّزْقَ لِمَن يَشَآءُ مِنْ عِبَادِهِۦ وَيَقْدِرُ لَهُۥ ۚ وَمَآ أَنفَقْتُم مِّن شَىْءٍۢ فَهُوَ يُخْلِفُهُۥ ۖ وَهُوَ خَيْرُ ٱلرَّٰزِقِينَ', 'قل إن ربى يبسط الرزق لمن يشاء من عباده ويقدر له  وما أنفقتم من شىء فهو يخلفه  وهو خير الرزقين', NULL, 432, 'local:hafs-text.json'),
  ('hafs-34-40', 'hafs', 34, 40, 'وَيَوْمَ يَحْشُرُهُمْ جَمِيعًۭا ثُمَّ يَقُولُ لِلْمَلَٰٓئِكَةِ أَهَٰٓؤُلَآءِ إِيَّاكُمْ كَانُوا۟ يَعْبُدُونَ', 'ويوم يحشرهم جميعا ثم يقول للملئكة أهؤلاء إياكم كانوا يعبدون', NULL, 433, 'local:hafs-text.json'),
  ('hafs-34-41', 'hafs', 34, 41, 'قَالُوا۟ سُبْحَٰنَكَ أَنتَ وَلِيُّنَا مِن دُونِهِم ۖ بَلْ كَانُوا۟ يَعْبُدُونَ ٱلْجِنَّ ۖ أَكْثَرُهُم بِهِم مُّؤْمِنُونَ', 'قالوا سبحنك أنت ولينا من دونهم  بل كانوا يعبدون الجن  أكثرهم بهم مؤمنون', NULL, 433, 'local:hafs-text.json'),
  ('hafs-34-42', 'hafs', 34, 42, 'فَٱلْيَوْمَ لَا يَمْلِكُ بَعْضُكُمْ لِبَعْضٍۢ نَّفْعًۭا وَلَا ضَرًّۭا وَنَقُولُ لِلَّذِينَ ظَلَمُوا۟ ذُوقُوا۟ عَذَابَ ٱلنَّارِ ٱلَّتِى كُنتُم بِهَا تُكَذِّبُونَ', 'فاليوم لا يملك بعضكم لبعض نفعا ولا ضرا ونقول للذين ظلموا ذوقوا عذاب النار التى كنتم بها تكذبون', NULL, 433, 'local:hafs-text.json'),
  ('hafs-34-43', 'hafs', 34, 43, 'وَإِذَا تُتْلَىٰ عَلَيْهِمْ ءَايَٰتُنَا بَيِّنَٰتٍۢ قَالُوا۟ مَا هَٰذَآ إِلَّا رَجُلٌۭ يُرِيدُ أَن يَصُدَّكُمْ عَمَّا كَانَ يَعْبُدُ ءَابَآؤُكُمْ وَقَالُوا۟ مَا هَٰذَآ إِلَّآ إِفْكٌۭ مُّفْتَرًۭى ۚ وَقَالَ ٱلَّذِينَ كَفَرُوا۟ لِلْحَقِّ لَمَّا جَآءَهُمْ إِنْ هَٰذَآ إِلَّا سِحْرٌۭ مُّبِينٌۭ', 'وإذا تتلى عليهم ءايتنا بينت قالوا ما هذا إلا رجل يريد أن يصدكم عما كان يعبد ءاباؤكم وقالوا ما هذا إلا إفك مفترى  وقال الذين كفروا للحق لما جاءهم إن هذا إلا سحر مبين', NULL, 433, 'local:hafs-text.json'),
  ('hafs-34-44', 'hafs', 34, 44, 'وَمَآ ءَاتَيْنَٰهُم مِّن كُتُبٍۢ يَدْرُسُونَهَا ۖ وَمَآ أَرْسَلْنَآ إِلَيْهِمْ قَبْلَكَ مِن نَّذِيرٍۢ', 'وما ءاتينهم من كتب يدرسونها  وما أرسلنا إليهم قبلك من نذير', NULL, 433, 'local:hafs-text.json'),
  ('hafs-34-45', 'hafs', 34, 45, 'وَكَذَّبَ ٱلَّذِينَ مِن قَبْلِهِمْ وَمَا بَلَغُوا۟ مِعْشَارَ مَآ ءَاتَيْنَٰهُمْ فَكَذَّبُوا۟ رُسُلِى ۖ فَكَيْفَ كَانَ نَكِيرِ', 'وكذب الذين من قبلهم وما بلغوا معشار ما ءاتينهم فكذبوا رسلى  فكيف كان نكير', NULL, 433, 'local:hafs-text.json'),
  ('hafs-34-46', 'hafs', 34, 46, '۞ قُلْ إِنَّمَآ أَعِظُكُم بِوَٰحِدَةٍ ۖ أَن تَقُومُوا۟ لِلَّهِ مَثْنَىٰ وَفُرَٰدَىٰ ثُمَّ تَتَفَكَّرُوا۟ ۚ مَا بِصَاحِبِكُم مِّن جِنَّةٍ ۚ إِنْ هُوَ إِلَّا نَذِيرٌۭ لَّكُم بَيْنَ يَدَىْ عَذَابٍۢ شَدِيدٍۢ', 'قل إنما أعظكم بوحدة  أن تقوموا لله مثنى وفردى ثم تتفكروا  ما بصاحبكم من جنة  إن هو إلا نذير لكم بين يدى عذاب شديد', NULL, 433, 'local:hafs-text.json'),
  ('hafs-34-47', 'hafs', 34, 47, 'قُلْ مَا سَأَلْتُكُم مِّنْ أَجْرٍۢ فَهُوَ لَكُمْ ۖ إِنْ أَجْرِىَ إِلَّا عَلَى ٱللَّهِ ۖ وَهُوَ عَلَىٰ كُلِّ شَىْءٍۢ شَهِيدٌۭ', 'قل ما سألتكم من أجر فهو لكم  إن أجرى إلا على الله  وهو على كل شىء شهيد', NULL, 433, 'local:hafs-text.json'),
  ('hafs-34-48', 'hafs', 34, 48, 'قُلْ إِنَّ رَبِّى يَقْذِفُ بِٱلْحَقِّ عَلَّٰمُ ٱلْغُيُوبِ', 'قل إن ربى يقذف بالحق علم الغيوب', NULL, 433, 'local:hafs-text.json'),
  ('hafs-34-49', 'hafs', 34, 49, 'قُلْ جَآءَ ٱلْحَقُّ وَمَا يُبْدِئُ ٱلْبَٰطِلُ وَمَا يُعِيدُ', 'قل جاء الحق وما يبدئ البطل وما يعيد', NULL, 434, 'local:hafs-text.json'),
  ('hafs-34-50', 'hafs', 34, 50, 'قُلْ إِن ضَلَلْتُ فَإِنَّمَآ أَضِلُّ عَلَىٰ نَفْسِى ۖ وَإِنِ ٱهْتَدَيْتُ فَبِمَا يُوحِىٓ إِلَىَّ رَبِّىٓ ۚ إِنَّهُۥ سَمِيعٌۭ قَرِيبٌۭ', 'قل إن ضللت فإنما أضل على نفسى  وإن اهتديت فبما يوحى إلى ربى  إنه سميع قريب', NULL, 434, 'local:hafs-text.json'),
  ('hafs-34-51', 'hafs', 34, 51, 'وَلَوْ تَرَىٰٓ إِذْ فَزِعُوا۟ فَلَا فَوْتَ وَأُخِذُوا۟ مِن مَّكَانٍۢ قَرِيبٍۢ', 'ولو ترى إذ فزعوا فلا فوت وأخذوا من مكان قريب', NULL, 434, 'local:hafs-text.json'),
  ('hafs-34-52', 'hafs', 34, 52, 'وَقَالُوٓا۟ ءَامَنَّا بِهِۦ وَأَنَّىٰ لَهُمُ ٱلتَّنَاوُشُ مِن مَّكَانٍۭ بَعِيدٍۢ', 'وقالوا ءامنا به وأنى لهم التناوش من مكان بعيد', NULL, 434, 'local:hafs-text.json'),
  ('hafs-34-53', 'hafs', 34, 53, 'وَقَدْ كَفَرُوا۟ بِهِۦ مِن قَبْلُ ۖ وَيَقْذِفُونَ بِٱلْغَيْبِ مِن مَّكَانٍۭ بَعِيدٍۢ', 'وقد كفروا به من قبل  ويقذفون بالغيب من مكان بعيد', NULL, 434, 'local:hafs-text.json'),
  ('hafs-34-54', 'hafs', 34, 54, 'وَحِيلَ بَيْنَهُمْ وَبَيْنَ مَا يَشْتَهُونَ كَمَا فُعِلَ بِأَشْيَاعِهِم مِّن قَبْلُ ۚ إِنَّهُمْ كَانُوا۟ فِى شَكٍّۢ مُّرِيبٍۭ', 'وحيل بينهم وبين ما يشتهون كما فعل بأشياعهم من قبل  إنهم كانوا فى شك مريب', NULL, 434, 'local:hafs-text.json'),
  ('hafs-35-1', 'hafs', 35, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ ٱلْحَمْدُ لِلَّهِ فَاطِرِ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ جَاعِلِ ٱلْمَلَٰٓئِكَةِ رُسُلًا أُو۟لِىٓ أَجْنِحَةٍۢ مَّثْنَىٰ وَثُلَٰثَ وَرُبَٰعَ ۚ يَزِيدُ فِى ٱلْخَلْقِ مَا يَشَآءُ ۚ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَىْءٍۢ قَدِيرٌۭ', 'بسم الله الرحمن الرحيم الحمد لله فاطر السموت والأرض جاعل الملئكة رسلا أولى أجنحة مثنى وثلث وربع  يزيد فى الخلق ما يشاء  إن الله على كل شىء قدير', NULL, 434, 'local:hafs-text.json'),
  ('hafs-35-2', 'hafs', 35, 2, 'مَّا يَفْتَحِ ٱللَّهُ لِلنَّاسِ مِن رَّحْمَةٍۢ فَلَا مُمْسِكَ لَهَا ۖ وَمَا يُمْسِكْ فَلَا مُرْسِلَ لَهُۥ مِنۢ بَعْدِهِۦ ۚ وَهُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ', 'ما يفتح الله للناس من رحمة فلا ممسك لها  وما يمسك فلا مرسل له من بعده  وهو العزيز الحكيم', NULL, 434, 'local:hafs-text.json'),
  ('hafs-35-3', 'hafs', 35, 3, 'يَٰٓأَيُّهَا ٱلنَّاسُ ٱذْكُرُوا۟ نِعْمَتَ ٱللَّهِ عَلَيْكُمْ ۚ هَلْ مِنْ خَٰلِقٍ غَيْرُ ٱللَّهِ يَرْزُقُكُم مِّنَ ٱلسَّمَآءِ وَٱلْأَرْضِ ۚ لَآ إِلَٰهَ إِلَّا هُوَ ۖ فَأَنَّىٰ تُؤْفَكُونَ', 'يأيها الناس اذكروا نعمت الله عليكم  هل من خلق غير الله يرزقكم من السماء والأرض  لا إله إلا هو  فأنى تؤفكون', NULL, 434, 'local:hafs-text.json'),
  ('hafs-35-4', 'hafs', 35, 4, 'وَإِن يُكَذِّبُوكَ فَقَدْ كُذِّبَتْ رُسُلٌۭ مِّن قَبْلِكَ ۚ وَإِلَى ٱللَّهِ تُرْجَعُ ٱلْأُمُورُ', 'وإن يكذبوك فقد كذبت رسل من قبلك  وإلى الله ترجع الأمور', NULL, 435, 'local:hafs-text.json'),
  ('hafs-35-5', 'hafs', 35, 5, 'يَٰٓأَيُّهَا ٱلنَّاسُ إِنَّ وَعْدَ ٱللَّهِ حَقٌّۭ ۖ فَلَا تَغُرَّنَّكُمُ ٱلْحَيَوٰةُ ٱلدُّنْيَا ۖ وَلَا يَغُرَّنَّكُم بِٱللَّهِ ٱلْغَرُورُ', 'يأيها الناس إن وعد الله حق  فلا تغرنكم الحيوة الدنيا  ولا يغرنكم بالله الغرور', NULL, 435, 'local:hafs-text.json'),
  ('hafs-35-6', 'hafs', 35, 6, 'إِنَّ ٱلشَّيْطَٰنَ لَكُمْ عَدُوٌّۭ فَٱتَّخِذُوهُ عَدُوًّا ۚ إِنَّمَا يَدْعُوا۟ حِزْبَهُۥ لِيَكُونُوا۟ مِنْ أَصْحَٰبِ ٱلسَّعِيرِ', 'إن الشيطن لكم عدو فاتخذوه عدوا  إنما يدعوا حزبه ليكونوا من أصحب السعير', NULL, 435, 'local:hafs-text.json'),
  ('hafs-35-7', 'hafs', 35, 7, 'ٱلَّذِينَ كَفَرُوا۟ لَهُمْ عَذَابٌۭ شَدِيدٌۭ ۖ وَٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ لَهُم مَّغْفِرَةٌۭ وَأَجْرٌۭ كَبِيرٌ', 'الذين كفروا لهم عذاب شديد  والذين ءامنوا وعملوا الصلحت لهم مغفرة وأجر كبير', NULL, 435, 'local:hafs-text.json'),
  ('hafs-35-8', 'hafs', 35, 8, 'أَفَمَن زُيِّنَ لَهُۥ سُوٓءُ عَمَلِهِۦ فَرَءَاهُ حَسَنًۭا ۖ فَإِنَّ ٱللَّهَ يُضِلُّ مَن يَشَآءُ وَيَهْدِى مَن يَشَآءُ ۖ فَلَا تَذْهَبْ نَفْسُكَ عَلَيْهِمْ حَسَرَٰتٍ ۚ إِنَّ ٱللَّهَ عَلِيمٌۢ بِمَا يَصْنَعُونَ', 'أفمن زين له سوء عمله فرءاه حسنا  فإن الله يضل من يشاء ويهدى من يشاء  فلا تذهب نفسك عليهم حسرت  إن الله عليم بما يصنعون', NULL, 435, 'local:hafs-text.json'),
  ('hafs-35-9', 'hafs', 35, 9, 'وَٱللَّهُ ٱلَّذِىٓ أَرْسَلَ ٱلرِّيَٰحَ فَتُثِيرُ سَحَابًۭا فَسُقْنَٰهُ إِلَىٰ بَلَدٍۢ مَّيِّتٍۢ فَأَحْيَيْنَا بِهِ ٱلْأَرْضَ بَعْدَ مَوْتِهَا ۚ كَذَٰلِكَ ٱلنُّشُورُ', 'والله الذى أرسل الريح فتثير سحابا فسقنه إلى بلد ميت فأحيينا به الأرض بعد موتها  كذلك النشور', NULL, 435, 'local:hafs-text.json'),
  ('hafs-35-10', 'hafs', 35, 10, 'مَن كَانَ يُرِيدُ ٱلْعِزَّةَ فَلِلَّهِ ٱلْعِزَّةُ جَمِيعًا ۚ إِلَيْهِ يَصْعَدُ ٱلْكَلِمُ ٱلطَّيِّبُ وَٱلْعَمَلُ ٱلصَّٰلِحُ يَرْفَعُهُۥ ۚ وَٱلَّذِينَ يَمْكُرُونَ ٱلسَّيِّـَٔاتِ لَهُمْ عَذَابٌۭ شَدِيدٌۭ ۖ وَمَكْرُ أُو۟لَٰٓئِكَ هُوَ يَبُورُ', 'من كان يريد العزة فلله العزة جميعا  إليه يصعد الكلم الطيب والعمل الصلح يرفعه  والذين يمكرون السيات لهم عذاب شديد  ومكر أولئك هو يبور', NULL, 435, 'local:hafs-text.json'),
  ('hafs-35-11', 'hafs', 35, 11, 'وَٱللَّهُ خَلَقَكُم مِّن تُرَابٍۢ ثُمَّ مِن نُّطْفَةٍۢ ثُمَّ جَعَلَكُمْ أَزْوَٰجًۭا ۚ وَمَا تَحْمِلُ مِنْ أُنثَىٰ وَلَا تَضَعُ إِلَّا بِعِلْمِهِۦ ۚ وَمَا يُعَمَّرُ مِن مُّعَمَّرٍۢ وَلَا يُنقَصُ مِنْ عُمُرِهِۦٓ إِلَّا فِى كِتَٰبٍ ۚ إِنَّ ذَٰلِكَ عَلَى ٱللَّهِ يَسِيرٌۭ', 'والله خلقكم من تراب ثم من نطفة ثم جعلكم أزوجا  وما تحمل من أنثى ولا تضع إلا بعلمه  وما يعمر من معمر ولا ينقص من عمره إلا فى كتب  إن ذلك على الله يسير', NULL, 435, 'local:hafs-text.json'),
  ('hafs-35-12', 'hafs', 35, 12, 'وَمَا يَسْتَوِى ٱلْبَحْرَانِ هَٰذَا عَذْبٌۭ فُرَاتٌۭ سَآئِغٌۭ شَرَابُهُۥ وَهَٰذَا مِلْحٌ أُجَاجٌۭ ۖ وَمِن كُلٍّۢ تَأْكُلُونَ لَحْمًۭا طَرِيًّۭا وَتَسْتَخْرِجُونَ حِلْيَةًۭ تَلْبَسُونَهَا ۖ وَتَرَى ٱلْفُلْكَ فِيهِ مَوَاخِرَ لِتَبْتَغُوا۟ مِن فَضْلِهِۦ وَلَعَلَّكُمْ تَشْكُرُونَ', 'وما يستوى البحران هذا عذب فرات سائغ شرابه وهذا ملح أجاج  ومن كل تأكلون لحما طريا وتستخرجون حلية تلبسونها  وترى الفلك فيه مواخر لتبتغوا من فضله ولعلكم تشكرون', NULL, 436, 'local:hafs-text.json'),
  ('hafs-35-13', 'hafs', 35, 13, 'يُولِجُ ٱلَّيْلَ فِى ٱلنَّهَارِ وَيُولِجُ ٱلنَّهَارَ فِى ٱلَّيْلِ وَسَخَّرَ ٱلشَّمْسَ وَٱلْقَمَرَ كُلٌّۭ يَجْرِى لِأَجَلٍۢ مُّسَمًّۭى ۚ ذَٰلِكُمُ ٱللَّهُ رَبُّكُمْ لَهُ ٱلْمُلْكُ ۚ وَٱلَّذِينَ تَدْعُونَ مِن دُونِهِۦ مَا يَمْلِكُونَ مِن قِطْمِيرٍ', 'يولج اليل فى النهار ويولج النهار فى اليل وسخر الشمس والقمر كل يجرى لأجل مسمى  ذلكم الله ربكم له الملك  والذين تدعون من دونه ما يملكون من قطمير', NULL, 436, 'local:hafs-text.json'),
  ('hafs-35-14', 'hafs', 35, 14, 'إِن تَدْعُوهُمْ لَا يَسْمَعُوا۟ دُعَآءَكُمْ وَلَوْ سَمِعُوا۟ مَا ٱسْتَجَابُوا۟ لَكُمْ ۖ وَيَوْمَ ٱلْقِيَٰمَةِ يَكْفُرُونَ بِشِرْكِكُمْ ۚ وَلَا يُنَبِّئُكَ مِثْلُ خَبِيرٍۢ', 'إن تدعوهم لا يسمعوا دعاءكم ولو سمعوا ما استجابوا لكم  ويوم القيمة يكفرون بشرككم  ولا ينبئك مثل خبير', NULL, 436, 'local:hafs-text.json'),
  ('hafs-35-15', 'hafs', 35, 15, '۞ يَٰٓأَيُّهَا ٱلنَّاسُ أَنتُمُ ٱلْفُقَرَآءُ إِلَى ٱللَّهِ ۖ وَٱللَّهُ هُوَ ٱلْغَنِىُّ ٱلْحَمِيدُ', 'يأيها الناس أنتم الفقراء إلى الله  والله هو الغنى الحميد', NULL, 436, 'local:hafs-text.json'),
  ('hafs-35-16', 'hafs', 35, 16, 'إِن يَشَأْ يُذْهِبْكُمْ وَيَأْتِ بِخَلْقٍۢ جَدِيدٍۢ', 'إن يشأ يذهبكم ويأت بخلق جديد', NULL, 436, 'local:hafs-text.json'),
  ('hafs-35-17', 'hafs', 35, 17, 'وَمَا ذَٰلِكَ عَلَى ٱللَّهِ بِعَزِيزٍۢ', 'وما ذلك على الله بعزيز', NULL, 436, 'local:hafs-text.json'),
  ('hafs-35-18', 'hafs', 35, 18, 'وَلَا تَزِرُ وَازِرَةٌۭ وِزْرَ أُخْرَىٰ ۚ وَإِن تَدْعُ مُثْقَلَةٌ إِلَىٰ حِمْلِهَا لَا يُحْمَلْ مِنْهُ شَىْءٌۭ وَلَوْ كَانَ ذَا قُرْبَىٰٓ ۗ إِنَّمَا تُنذِرُ ٱلَّذِينَ يَخْشَوْنَ رَبَّهُم بِٱلْغَيْبِ وَأَقَامُوا۟ ٱلصَّلَوٰةَ ۚ وَمَن تَزَكَّىٰ فَإِنَّمَا يَتَزَكَّىٰ لِنَفْسِهِۦ ۚ وَإِلَى ٱللَّهِ ٱلْمَصِيرُ', 'ولا تزر وازرة وزر أخرى  وإن تدع مثقلة إلى حملها لا يحمل منه شىء ولو كان ذا قربى  إنما تنذر الذين يخشون ربهم بالغيب وأقاموا الصلوة  ومن تزكى فإنما يتزكى لنفسه  وإلى الله المصير', NULL, 436, 'local:hafs-text.json'),
  ('hafs-35-19', 'hafs', 35, 19, 'وَمَا يَسْتَوِى ٱلْأَعْمَىٰ وَٱلْبَصِيرُ', 'وما يستوى الأعمى والبصير', NULL, 437, 'local:hafs-text.json'),
  ('hafs-35-20', 'hafs', 35, 20, 'وَلَا ٱلظُّلُمَٰتُ وَلَا ٱلنُّورُ', 'ولا الظلمت ولا النور', NULL, 437, 'local:hafs-text.json'),
  ('hafs-35-21', 'hafs', 35, 21, 'وَلَا ٱلظِّلُّ وَلَا ٱلْحَرُورُ', 'ولا الظل ولا الحرور', NULL, 437, 'local:hafs-text.json'),
  ('hafs-35-22', 'hafs', 35, 22, 'وَمَا يَسْتَوِى ٱلْأَحْيَآءُ وَلَا ٱلْأَمْوَٰتُ ۚ إِنَّ ٱللَّهَ يُسْمِعُ مَن يَشَآءُ ۖ وَمَآ أَنتَ بِمُسْمِعٍۢ مَّن فِى ٱلْقُبُورِ', 'وما يستوى الأحياء ولا الأموت  إن الله يسمع من يشاء  وما أنت بمسمع من فى القبور', NULL, 437, 'local:hafs-text.json'),
  ('hafs-35-23', 'hafs', 35, 23, 'إِنْ أَنتَ إِلَّا نَذِيرٌ', 'إن أنت إلا نذير', NULL, 437, 'local:hafs-text.json'),
  ('hafs-35-24', 'hafs', 35, 24, 'إِنَّآ أَرْسَلْنَٰكَ بِٱلْحَقِّ بَشِيرًۭا وَنَذِيرًۭا ۚ وَإِن مِّنْ أُمَّةٍ إِلَّا خَلَا فِيهَا نَذِيرٌۭ', 'إنا أرسلنك بالحق بشيرا ونذيرا  وإن من أمة إلا خلا فيها نذير', NULL, 437, 'local:hafs-text.json'),
  ('hafs-35-25', 'hafs', 35, 25, 'وَإِن يُكَذِّبُوكَ فَقَدْ كَذَّبَ ٱلَّذِينَ مِن قَبْلِهِمْ جَآءَتْهُمْ رُسُلُهُم بِٱلْبَيِّنَٰتِ وَبِٱلزُّبُرِ وَبِٱلْكِتَٰبِ ٱلْمُنِيرِ', 'وإن يكذبوك فقد كذب الذين من قبلهم جاءتهم رسلهم بالبينت وبالزبر وبالكتب المنير', NULL, 437, 'local:hafs-text.json'),
  ('hafs-35-26', 'hafs', 35, 26, 'ثُمَّ أَخَذْتُ ٱلَّذِينَ كَفَرُوا۟ ۖ فَكَيْفَ كَانَ نَكِيرِ', 'ثم أخذت الذين كفروا  فكيف كان نكير', NULL, 437, 'local:hafs-text.json'),
  ('hafs-35-27', 'hafs', 35, 27, 'أَلَمْ تَرَ أَنَّ ٱللَّهَ أَنزَلَ مِنَ ٱلسَّمَآءِ مَآءًۭ فَأَخْرَجْنَا بِهِۦ ثَمَرَٰتٍۢ مُّخْتَلِفًا أَلْوَٰنُهَا ۚ وَمِنَ ٱلْجِبَالِ جُدَدٌۢ بِيضٌۭ وَحُمْرٌۭ مُّخْتَلِفٌ أَلْوَٰنُهَا وَغَرَابِيبُ سُودٌۭ', 'ألم تر أن الله أنزل من السماء ماء فأخرجنا به ثمرت مختلفا ألونها  ومن الجبال جدد بيض وحمر مختلف ألونها وغرابيب سود', NULL, 437, 'local:hafs-text.json'),
  ('hafs-35-28', 'hafs', 35, 28, 'وَمِنَ ٱلنَّاسِ وَٱلدَّوَآبِّ وَٱلْأَنْعَٰمِ مُخْتَلِفٌ أَلْوَٰنُهُۥ كَذَٰلِكَ ۗ إِنَّمَا يَخْشَى ٱللَّهَ مِنْ عِبَادِهِ ٱلْعُلَمَٰٓؤُا۟ ۗ إِنَّ ٱللَّهَ عَزِيزٌ غَفُورٌ', 'ومن الناس والدواب والأنعم مختلف ألونه كذلك  إنما يخشى الله من عباده العلمؤا  إن الله عزيز غفور', NULL, 437, 'local:hafs-text.json'),
  ('hafs-35-29', 'hafs', 35, 29, 'إِنَّ ٱلَّذِينَ يَتْلُونَ كِتَٰبَ ٱللَّهِ وَأَقَامُوا۟ ٱلصَّلَوٰةَ وَأَنفَقُوا۟ مِمَّا رَزَقْنَٰهُمْ سِرًّۭا وَعَلَانِيَةًۭ يَرْجُونَ تِجَٰرَةًۭ لَّن تَبُورَ', 'إن الذين يتلون كتب الله وأقاموا الصلوة وأنفقوا مما رزقنهم سرا وعلانية يرجون تجرة لن تبور', NULL, 437, 'local:hafs-text.json'),
  ('hafs-35-30', 'hafs', 35, 30, 'لِيُوَفِّيَهُمْ أُجُورَهُمْ وَيَزِيدَهُم مِّن فَضْلِهِۦٓ ۚ إِنَّهُۥ غَفُورٌۭ شَكُورٌۭ', 'ليوفيهم أجورهم ويزيدهم من فضله  إنه غفور شكور', NULL, 437, 'local:hafs-text.json'),
  ('hafs-35-31', 'hafs', 35, 31, 'وَٱلَّذِىٓ أَوْحَيْنَآ إِلَيْكَ مِنَ ٱلْكِتَٰبِ هُوَ ٱلْحَقُّ مُصَدِّقًۭا لِّمَا بَيْنَ يَدَيْهِ ۗ إِنَّ ٱللَّهَ بِعِبَادِهِۦ لَخَبِيرٌۢ بَصِيرٌۭ', 'والذى أوحينا إليك من الكتب هو الحق مصدقا لما بين يديه  إن الله بعباده لخبير بصير', NULL, 438, 'local:hafs-text.json'),
  ('hafs-35-32', 'hafs', 35, 32, 'ثُمَّ أَوْرَثْنَا ٱلْكِتَٰبَ ٱلَّذِينَ ٱصْطَفَيْنَا مِنْ عِبَادِنَا ۖ فَمِنْهُمْ ظَالِمٌۭ لِّنَفْسِهِۦ وَمِنْهُم مُّقْتَصِدٌۭ وَمِنْهُمْ سَابِقٌۢ بِٱلْخَيْرَٰتِ بِإِذْنِ ٱللَّهِ ۚ ذَٰلِكَ هُوَ ٱلْفَضْلُ ٱلْكَبِيرُ', 'ثم أورثنا الكتب الذين اصطفينا من عبادنا  فمنهم ظالم لنفسه ومنهم مقتصد ومنهم سابق بالخيرت بإذن الله  ذلك هو الفضل الكبير', NULL, 438, 'local:hafs-text.json'),
  ('hafs-35-33', 'hafs', 35, 33, 'جَنَّٰتُ عَدْنٍۢ يَدْخُلُونَهَا يُحَلَّوْنَ فِيهَا مِنْ أَسَاوِرَ مِن ذَهَبٍۢ وَلُؤْلُؤًۭا ۖ وَلِبَاسُهُمْ فِيهَا حَرِيرٌۭ', 'جنت عدن يدخلونها يحلون فيها من أساور من ذهب ولؤلؤا  ولباسهم فيها حرير', NULL, 438, 'local:hafs-text.json'),
  ('hafs-35-34', 'hafs', 35, 34, 'وَقَالُوا۟ ٱلْحَمْدُ لِلَّهِ ٱلَّذِىٓ أَذْهَبَ عَنَّا ٱلْحَزَنَ ۖ إِنَّ رَبَّنَا لَغَفُورٌۭ شَكُورٌ', 'وقالوا الحمد لله الذى أذهب عنا الحزن  إن ربنا لغفور شكور', NULL, 438, 'local:hafs-text.json'),
  ('hafs-35-35', 'hafs', 35, 35, 'ٱلَّذِىٓ أَحَلَّنَا دَارَ ٱلْمُقَامَةِ مِن فَضْلِهِۦ لَا يَمَسُّنَا فِيهَا نَصَبٌۭ وَلَا يَمَسُّنَا فِيهَا لُغُوبٌۭ', 'الذى أحلنا دار المقامة من فضله لا يمسنا فيها نصب ولا يمسنا فيها لغوب', NULL, 438, 'local:hafs-text.json'),
  ('hafs-35-36', 'hafs', 35, 36, 'وَٱلَّذِينَ كَفَرُوا۟ لَهُمْ نَارُ جَهَنَّمَ لَا يُقْضَىٰ عَلَيْهِمْ فَيَمُوتُوا۟ وَلَا يُخَفَّفُ عَنْهُم مِّنْ عَذَابِهَا ۚ كَذَٰلِكَ نَجْزِى كُلَّ كَفُورٍۢ', 'والذين كفروا لهم نار جهنم لا يقضى عليهم فيموتوا ولا يخفف عنهم من عذابها  كذلك نجزى كل كفور', NULL, 438, 'local:hafs-text.json'),
  ('hafs-35-37', 'hafs', 35, 37, 'وَهُمْ يَصْطَرِخُونَ فِيهَا رَبَّنَآ أَخْرِجْنَا نَعْمَلْ صَٰلِحًا غَيْرَ ٱلَّذِى كُنَّا نَعْمَلُ ۚ أَوَلَمْ نُعَمِّرْكُم مَّا يَتَذَكَّرُ فِيهِ مَن تَذَكَّرَ وَجَآءَكُمُ ٱلنَّذِيرُ ۖ فَذُوقُوا۟ فَمَا لِلظَّٰلِمِينَ مِن نَّصِيرٍ', 'وهم يصطرخون فيها ربنا أخرجنا نعمل صلحا غير الذى كنا نعمل  أولم نعمركم ما يتذكر فيه من تذكر وجاءكم النذير  فذوقوا فما للظلمين من نصير', NULL, 438, 'local:hafs-text.json'),
  ('hafs-35-38', 'hafs', 35, 38, 'إِنَّ ٱللَّهَ عَٰلِمُ غَيْبِ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ ۚ إِنَّهُۥ عَلِيمٌۢ بِذَاتِ ٱلصُّدُورِ', 'إن الله علم غيب السموت والأرض  إنه عليم بذات الصدور', NULL, 438, 'local:hafs-text.json'),
  ('hafs-35-39', 'hafs', 35, 39, 'هُوَ ٱلَّذِى جَعَلَكُمْ خَلَٰٓئِفَ فِى ٱلْأَرْضِ ۚ فَمَن كَفَرَ فَعَلَيْهِ كُفْرُهُۥ ۖ وَلَا يَزِيدُ ٱلْكَٰفِرِينَ كُفْرُهُمْ عِندَ رَبِّهِمْ إِلَّا مَقْتًۭا ۖ وَلَا يَزِيدُ ٱلْكَٰفِرِينَ كُفْرُهُمْ إِلَّا خَسَارًۭا', 'هو الذى جعلكم خلئف فى الأرض  فمن كفر فعليه كفره  ولا يزيد الكفرين كفرهم عند ربهم إلا مقتا  ولا يزيد الكفرين كفرهم إلا خسارا', NULL, 439, 'local:hafs-text.json'),
  ('hafs-35-40', 'hafs', 35, 40, 'قُلْ أَرَءَيْتُمْ شُرَكَآءَكُمُ ٱلَّذِينَ تَدْعُونَ مِن دُونِ ٱللَّهِ أَرُونِى مَاذَا خَلَقُوا۟ مِنَ ٱلْأَرْضِ أَمْ لَهُمْ شِرْكٌۭ فِى ٱلسَّمَٰوَٰتِ أَمْ ءَاتَيْنَٰهُمْ كِتَٰبًۭا فَهُمْ عَلَىٰ بَيِّنَتٍۢ مِّنْهُ ۚ بَلْ إِن يَعِدُ ٱلظَّٰلِمُونَ بَعْضُهُم بَعْضًا إِلَّا غُرُورًا', 'قل أرءيتم شركاءكم الذين تدعون من دون الله أرونى ماذا خلقوا من الأرض أم لهم شرك فى السموت أم ءاتينهم كتبا فهم على بينت منه  بل إن يعد الظلمون بعضهم بعضا إلا غرورا', NULL, 439, 'local:hafs-text.json'),
  ('hafs-35-41', 'hafs', 35, 41, '۞ إِنَّ ٱللَّهَ يُمْسِكُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ أَن تَزُولَا ۚ وَلَئِن زَالَتَآ إِنْ أَمْسَكَهُمَا مِنْ أَحَدٍۢ مِّنۢ بَعْدِهِۦٓ ۚ إِنَّهُۥ كَانَ حَلِيمًا غَفُورًۭا', 'إن الله يمسك السموت والأرض أن تزولا  ولئن زالتا إن أمسكهما من أحد من بعده  إنه كان حليما غفورا', NULL, 439, 'local:hafs-text.json'),
  ('hafs-35-42', 'hafs', 35, 42, 'وَأَقْسَمُوا۟ بِٱللَّهِ جَهْدَ أَيْمَٰنِهِمْ لَئِن جَآءَهُمْ نَذِيرٌۭ لَّيَكُونُنَّ أَهْدَىٰ مِنْ إِحْدَى ٱلْأُمَمِ ۖ فَلَمَّا جَآءَهُمْ نَذِيرٌۭ مَّا زَادَهُمْ إِلَّا نُفُورًا', 'وأقسموا بالله جهد أيمنهم لئن جاءهم نذير ليكونن أهدى من إحدى الأمم  فلما جاءهم نذير ما زادهم إلا نفورا', NULL, 439, 'local:hafs-text.json'),
  ('hafs-35-43', 'hafs', 35, 43, 'ٱسْتِكْبَارًۭا فِى ٱلْأَرْضِ وَمَكْرَ ٱلسَّيِّئِ ۚ وَلَا يَحِيقُ ٱلْمَكْرُ ٱلسَّيِّئُ إِلَّا بِأَهْلِهِۦ ۚ فَهَلْ يَنظُرُونَ إِلَّا سُنَّتَ ٱلْأَوَّلِينَ ۚ فَلَن تَجِدَ لِسُنَّتِ ٱللَّهِ تَبْدِيلًۭا ۖ وَلَن تَجِدَ لِسُنَّتِ ٱللَّهِ تَحْوِيلًا', 'استكبارا فى الأرض ومكر السيئ  ولا يحيق المكر السيئ إلا بأهله  فهل ينظرون إلا سنت الأولين  فلن تجد لسنت الله تبديلا  ولن تجد لسنت الله تحويلا', NULL, 439, 'local:hafs-text.json'),
  ('hafs-35-44', 'hafs', 35, 44, 'أَوَلَمْ يَسِيرُوا۟ فِى ٱلْأَرْضِ فَيَنظُرُوا۟ كَيْفَ كَانَ عَٰقِبَةُ ٱلَّذِينَ مِن قَبْلِهِمْ وَكَانُوٓا۟ أَشَدَّ مِنْهُمْ قُوَّةًۭ ۚ وَمَا كَانَ ٱللَّهُ لِيُعْجِزَهُۥ مِن شَىْءٍۢ فِى ٱلسَّمَٰوَٰتِ وَلَا فِى ٱلْأَرْضِ ۚ إِنَّهُۥ كَانَ عَلِيمًۭا قَدِيرًۭا', 'أولم يسيروا فى الأرض فينظروا كيف كان عقبة الذين من قبلهم وكانوا أشد منهم قوة  وما كان الله ليعجزه من شىء فى السموت ولا فى الأرض  إنه كان عليما قديرا', NULL, 439, 'local:hafs-text.json'),
  ('hafs-35-45', 'hafs', 35, 45, 'وَلَوْ يُؤَاخِذُ ٱللَّهُ ٱلنَّاسَ بِمَا كَسَبُوا۟ مَا تَرَكَ عَلَىٰ ظَهْرِهَا مِن دَآبَّةٍۢ وَلَٰكِن يُؤَخِّرُهُمْ إِلَىٰٓ أَجَلٍۢ مُّسَمًّۭى ۖ فَإِذَا جَآءَ أَجَلُهُمْ فَإِنَّ ٱللَّهَ كَانَ بِعِبَادِهِۦ بَصِيرًۢا', 'ولو يؤاخذ الله الناس بما كسبوا ما ترك على ظهرها من دابة ولكن يؤخرهم إلى أجل مسمى  فإذا جاء أجلهم فإن الله كان بعباده بصيرا', NULL, 440, 'local:hafs-text.json'),
  ('hafs-36-1', 'hafs', 36, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ يسٓ', 'بسم الله الرحمن الرحيم يس', NULL, 440, 'local:hafs-text.json'),
  ('hafs-36-2', 'hafs', 36, 2, 'وَٱلْقُرْءَانِ ٱلْحَكِيمِ', 'والقرءان الحكيم', NULL, 440, 'local:hafs-text.json'),
  ('hafs-36-3', 'hafs', 36, 3, 'إِنَّكَ لَمِنَ ٱلْمُرْسَلِينَ', 'إنك لمن المرسلين', NULL, 440, 'local:hafs-text.json'),
  ('hafs-36-4', 'hafs', 36, 4, 'عَلَىٰ صِرَٰطٍۢ مُّسْتَقِيمٍۢ', 'على صرط مستقيم', NULL, 440, 'local:hafs-text.json'),
  ('hafs-36-5', 'hafs', 36, 5, 'تَنزِيلَ ٱلْعَزِيزِ ٱلرَّحِيمِ', 'تنزيل العزيز الرحيم', NULL, 440, 'local:hafs-text.json'),
  ('hafs-36-6', 'hafs', 36, 6, 'لِتُنذِرَ قَوْمًۭا مَّآ أُنذِرَ ءَابَآؤُهُمْ فَهُمْ غَٰفِلُونَ', 'لتنذر قوما ما أنذر ءاباؤهم فهم غفلون', NULL, 440, 'local:hafs-text.json'),
  ('hafs-36-7', 'hafs', 36, 7, 'لَقَدْ حَقَّ ٱلْقَوْلُ عَلَىٰٓ أَكْثَرِهِمْ فَهُمْ لَا يُؤْمِنُونَ', 'لقد حق القول على أكثرهم فهم لا يؤمنون', NULL, 440, 'local:hafs-text.json'),
  ('hafs-36-8', 'hafs', 36, 8, 'إِنَّا جَعَلْنَا فِىٓ أَعْنَٰقِهِمْ أَغْلَٰلًۭا فَهِىَ إِلَى ٱلْأَذْقَانِ فَهُم مُّقْمَحُونَ', 'إنا جعلنا فى أعنقهم أغللا فهى إلى الأذقان فهم مقمحون', NULL, 440, 'local:hafs-text.json'),
  ('hafs-36-9', 'hafs', 36, 9, 'وَجَعَلْنَا مِنۢ بَيْنِ أَيْدِيهِمْ سَدًّۭا وَمِنْ خَلْفِهِمْ سَدًّۭا فَأَغْشَيْنَٰهُمْ فَهُمْ لَا يُبْصِرُونَ', 'وجعلنا من بين أيديهم سدا ومن خلفهم سدا فأغشينهم فهم لا يبصرون', NULL, 440, 'local:hafs-text.json'),
  ('hafs-36-10', 'hafs', 36, 10, 'وَسَوَآءٌ عَلَيْهِمْ ءَأَنذَرْتَهُمْ أَمْ لَمْ تُنذِرْهُمْ لَا يُؤْمِنُونَ', 'وسواء عليهم ءأنذرتهم أم لم تنذرهم لا يؤمنون', NULL, 440, 'local:hafs-text.json'),
  ('hafs-36-11', 'hafs', 36, 11, 'إِنَّمَا تُنذِرُ مَنِ ٱتَّبَعَ ٱلذِّكْرَ وَخَشِىَ ٱلرَّحْمَٰنَ بِٱلْغَيْبِ ۖ فَبَشِّرْهُ بِمَغْفِرَةٍۢ وَأَجْرٍۢ كَرِيمٍ', 'إنما تنذر من اتبع الذكر وخشى الرحمن بالغيب  فبشره بمغفرة وأجر كريم', NULL, 440, 'local:hafs-text.json'),
  ('hafs-36-12', 'hafs', 36, 12, 'إِنَّا نَحْنُ نُحْىِ ٱلْمَوْتَىٰ وَنَكْتُبُ مَا قَدَّمُوا۟ وَءَاثَٰرَهُمْ ۚ وَكُلَّ شَىْءٍ أَحْصَيْنَٰهُ فِىٓ إِمَامٍۢ مُّبِينٍۢ', 'إنا نحن نحى الموتى ونكتب ما قدموا وءاثرهم  وكل شىء أحصينه فى إمام مبين', NULL, 440, 'local:hafs-text.json'),
  ('hafs-36-13', 'hafs', 36, 13, 'وَٱضْرِبْ لَهُم مَّثَلًا أَصْحَٰبَ ٱلْقَرْيَةِ إِذْ جَآءَهَا ٱلْمُرْسَلُونَ', 'واضرب لهم مثلا أصحب القرية إذ جاءها المرسلون', NULL, 441, 'local:hafs-text.json'),
  ('hafs-36-14', 'hafs', 36, 14, 'إِذْ أَرْسَلْنَآ إِلَيْهِمُ ٱثْنَيْنِ فَكَذَّبُوهُمَا فَعَزَّزْنَا بِثَالِثٍۢ فَقَالُوٓا۟ إِنَّآ إِلَيْكُم مُّرْسَلُونَ', 'إذ أرسلنا إليهم اثنين فكذبوهما فعززنا بثالث فقالوا إنا إليكم مرسلون', NULL, 441, 'local:hafs-text.json'),
  ('hafs-36-15', 'hafs', 36, 15, 'قَالُوا۟ مَآ أَنتُمْ إِلَّا بَشَرٌۭ مِّثْلُنَا وَمَآ أَنزَلَ ٱلرَّحْمَٰنُ مِن شَىْءٍ إِنْ أَنتُمْ إِلَّا تَكْذِبُونَ', 'قالوا ما أنتم إلا بشر مثلنا وما أنزل الرحمن من شىء إن أنتم إلا تكذبون', NULL, 441, 'local:hafs-text.json'),
  ('hafs-36-16', 'hafs', 36, 16, 'قَالُوا۟ رَبُّنَا يَعْلَمُ إِنَّآ إِلَيْكُمْ لَمُرْسَلُونَ', 'قالوا ربنا يعلم إنا إليكم لمرسلون', NULL, 441, 'local:hafs-text.json'),
  ('hafs-36-17', 'hafs', 36, 17, 'وَمَا عَلَيْنَآ إِلَّا ٱلْبَلَٰغُ ٱلْمُبِينُ', 'وما علينا إلا البلغ المبين', NULL, 441, 'local:hafs-text.json'),
  ('hafs-36-18', 'hafs', 36, 18, 'قَالُوٓا۟ إِنَّا تَطَيَّرْنَا بِكُمْ ۖ لَئِن لَّمْ تَنتَهُوا۟ لَنَرْجُمَنَّكُمْ وَلَيَمَسَّنَّكُم مِّنَّا عَذَابٌ أَلِيمٌۭ', 'قالوا إنا تطيرنا بكم  لئن لم تنتهوا لنرجمنكم وليمسنكم منا عذاب أليم', NULL, 441, 'local:hafs-text.json'),
  ('hafs-36-19', 'hafs', 36, 19, 'قَالُوا۟ طَٰٓئِرُكُم مَّعَكُمْ ۚ أَئِن ذُكِّرْتُم ۚ بَلْ أَنتُمْ قَوْمٌۭ مُّسْرِفُونَ', 'قالوا طئركم معكم  أئن ذكرتم  بل أنتم قوم مسرفون', NULL, 441, 'local:hafs-text.json'),
  ('hafs-36-20', 'hafs', 36, 20, 'وَجَآءَ مِنْ أَقْصَا ٱلْمَدِينَةِ رَجُلٌۭ يَسْعَىٰ قَالَ يَٰقَوْمِ ٱتَّبِعُوا۟ ٱلْمُرْسَلِينَ', 'وجاء من أقصا المدينة رجل يسعى قال يقوم اتبعوا المرسلين', NULL, 441, 'local:hafs-text.json'),
  ('hafs-36-21', 'hafs', 36, 21, 'ٱتَّبِعُوا۟ مَن لَّا يَسْـَٔلُكُمْ أَجْرًۭا وَهُم مُّهْتَدُونَ', 'اتبعوا من لا يسلكم أجرا وهم مهتدون', NULL, 441, 'local:hafs-text.json'),
  ('hafs-36-22', 'hafs', 36, 22, 'وَمَا لِىَ لَآ أَعْبُدُ ٱلَّذِى فَطَرَنِى وَإِلَيْهِ تُرْجَعُونَ', 'وما لى لا أعبد الذى فطرنى وإليه ترجعون', NULL, 441, 'local:hafs-text.json'),
  ('hafs-36-23', 'hafs', 36, 23, 'ءَأَتَّخِذُ مِن دُونِهِۦٓ ءَالِهَةً إِن يُرِدْنِ ٱلرَّحْمَٰنُ بِضُرٍّۢ لَّا تُغْنِ عَنِّى شَفَٰعَتُهُمْ شَيْـًۭٔا وَلَا يُنقِذُونِ', 'ءأتخذ من دونه ءالهة إن يردن الرحمن بضر لا تغن عنى شفعتهم شيا ولا ينقذون', NULL, 441, 'local:hafs-text.json'),
  ('hafs-36-24', 'hafs', 36, 24, 'إِنِّىٓ إِذًۭا لَّفِى ضَلَٰلٍۢ مُّبِينٍ', 'إنى إذا لفى ضلل مبين', NULL, 441, 'local:hafs-text.json'),
  ('hafs-36-25', 'hafs', 36, 25, 'إِنِّىٓ ءَامَنتُ بِرَبِّكُمْ فَٱسْمَعُونِ', 'إنى ءامنت بربكم فاسمعون', NULL, 441, 'local:hafs-text.json'),
  ('hafs-36-26', 'hafs', 36, 26, 'قِيلَ ٱدْخُلِ ٱلْجَنَّةَ ۖ قَالَ يَٰلَيْتَ قَوْمِى يَعْلَمُونَ', 'قيل ادخل الجنة  قال يليت قومى يعلمون', NULL, 441, 'local:hafs-text.json'),
  ('hafs-36-27', 'hafs', 36, 27, 'بِمَا غَفَرَ لِى رَبِّى وَجَعَلَنِى مِنَ ٱلْمُكْرَمِينَ', 'بما غفر لى ربى وجعلنى من المكرمين', NULL, 441, 'local:hafs-text.json'),
  ('hafs-36-28', 'hafs', 36, 28, '۞ وَمَآ أَنزَلْنَا عَلَىٰ قَوْمِهِۦ مِنۢ بَعْدِهِۦ مِن جُندٍۢ مِّنَ ٱلسَّمَآءِ وَمَا كُنَّا مُنزِلِينَ', 'وما أنزلنا على قومه من بعده من جند من السماء وما كنا منزلين', NULL, 442, 'local:hafs-text.json'),
  ('hafs-36-29', 'hafs', 36, 29, 'إِن كَانَتْ إِلَّا صَيْحَةًۭ وَٰحِدَةًۭ فَإِذَا هُمْ خَٰمِدُونَ', 'إن كانت إلا صيحة وحدة فإذا هم خمدون', NULL, 442, 'local:hafs-text.json'),
  ('hafs-36-30', 'hafs', 36, 30, 'يَٰحَسْرَةً عَلَى ٱلْعِبَادِ ۚ مَا يَأْتِيهِم مِّن رَّسُولٍ إِلَّا كَانُوا۟ بِهِۦ يَسْتَهْزِءُونَ', 'يحسرة على العباد  ما يأتيهم من رسول إلا كانوا به يستهزءون', NULL, 442, 'local:hafs-text.json'),
  ('hafs-36-31', 'hafs', 36, 31, 'أَلَمْ يَرَوْا۟ كَمْ أَهْلَكْنَا قَبْلَهُم مِّنَ ٱلْقُرُونِ أَنَّهُمْ إِلَيْهِمْ لَا يَرْجِعُونَ', 'ألم يروا كم أهلكنا قبلهم من القرون أنهم إليهم لا يرجعون', NULL, 442, 'local:hafs-text.json'),
  ('hafs-36-32', 'hafs', 36, 32, 'وَإِن كُلٌّۭ لَّمَّا جَمِيعٌۭ لَّدَيْنَا مُحْضَرُونَ', 'وإن كل لما جميع لدينا محضرون', NULL, 442, 'local:hafs-text.json'),
  ('hafs-36-33', 'hafs', 36, 33, 'وَءَايَةٌۭ لَّهُمُ ٱلْأَرْضُ ٱلْمَيْتَةُ أَحْيَيْنَٰهَا وَأَخْرَجْنَا مِنْهَا حَبًّۭا فَمِنْهُ يَأْكُلُونَ', 'وءاية لهم الأرض الميتة أحيينها وأخرجنا منها حبا فمنه يأكلون', NULL, 442, 'local:hafs-text.json'),
  ('hafs-36-34', 'hafs', 36, 34, 'وَجَعَلْنَا فِيهَا جَنَّٰتٍۢ مِّن نَّخِيلٍۢ وَأَعْنَٰبٍۢ وَفَجَّرْنَا فِيهَا مِنَ ٱلْعُيُونِ', 'وجعلنا فيها جنت من نخيل وأعنب وفجرنا فيها من العيون', NULL, 442, 'local:hafs-text.json'),
  ('hafs-36-35', 'hafs', 36, 35, 'لِيَأْكُلُوا۟ مِن ثَمَرِهِۦ وَمَا عَمِلَتْهُ أَيْدِيهِمْ ۖ أَفَلَا يَشْكُرُونَ', 'ليأكلوا من ثمره وما عملته أيديهم  أفلا يشكرون', NULL, 442, 'local:hafs-text.json'),
  ('hafs-36-36', 'hafs', 36, 36, 'سُبْحَٰنَ ٱلَّذِى خَلَقَ ٱلْأَزْوَٰجَ كُلَّهَا مِمَّا تُنۢبِتُ ٱلْأَرْضُ وَمِنْ أَنفُسِهِمْ وَمِمَّا لَا يَعْلَمُونَ', 'سبحن الذى خلق الأزوج كلها مما تنبت الأرض ومن أنفسهم ومما لا يعلمون', NULL, 442, 'local:hafs-text.json'),
  ('hafs-36-37', 'hafs', 36, 37, 'وَءَايَةٌۭ لَّهُمُ ٱلَّيْلُ نَسْلَخُ مِنْهُ ٱلنَّهَارَ فَإِذَا هُم مُّظْلِمُونَ', 'وءاية لهم اليل نسلخ منه النهار فإذا هم مظلمون', NULL, 442, 'local:hafs-text.json'),
  ('hafs-36-38', 'hafs', 36, 38, 'وَٱلشَّمْسُ تَجْرِى لِمُسْتَقَرٍّۢ لَّهَا ۚ ذَٰلِكَ تَقْدِيرُ ٱلْعَزِيزِ ٱلْعَلِيمِ', 'والشمس تجرى لمستقر لها  ذلك تقدير العزيز العليم', NULL, 442, 'local:hafs-text.json'),
  ('hafs-36-39', 'hafs', 36, 39, 'وَٱلْقَمَرَ قَدَّرْنَٰهُ مَنَازِلَ حَتَّىٰ عَادَ كَٱلْعُرْجُونِ ٱلْقَدِيمِ', 'والقمر قدرنه منازل حتى عاد كالعرجون القديم', NULL, 442, 'local:hafs-text.json'),
  ('hafs-36-40', 'hafs', 36, 40, 'لَا ٱلشَّمْسُ يَنۢبَغِى لَهَآ أَن تُدْرِكَ ٱلْقَمَرَ وَلَا ٱلَّيْلُ سَابِقُ ٱلنَّهَارِ ۚ وَكُلٌّۭ فِى فَلَكٍۢ يَسْبَحُونَ', 'لا الشمس ينبغى لها أن تدرك القمر ولا اليل سابق النهار  وكل فى فلك يسبحون', NULL, 442, 'local:hafs-text.json'),
  ('hafs-36-41', 'hafs', 36, 41, 'وَءَايَةٌۭ لَّهُمْ أَنَّا حَمَلْنَا ذُرِّيَّتَهُمْ فِى ٱلْفُلْكِ ٱلْمَشْحُونِ', 'وءاية لهم أنا حملنا ذريتهم فى الفلك المشحون', NULL, 443, 'local:hafs-text.json'),
  ('hafs-36-42', 'hafs', 36, 42, 'وَخَلَقْنَا لَهُم مِّن مِّثْلِهِۦ مَا يَرْكَبُونَ', 'وخلقنا لهم من مثله ما يركبون', NULL, 443, 'local:hafs-text.json'),
  ('hafs-36-43', 'hafs', 36, 43, 'وَإِن نَّشَأْ نُغْرِقْهُمْ فَلَا صَرِيخَ لَهُمْ وَلَا هُمْ يُنقَذُونَ', 'وإن نشأ نغرقهم فلا صريخ لهم ولا هم ينقذون', NULL, 443, 'local:hafs-text.json'),
  ('hafs-36-44', 'hafs', 36, 44, 'إِلَّا رَحْمَةًۭ مِّنَّا وَمَتَٰعًا إِلَىٰ حِينٍۢ', 'إلا رحمة منا ومتعا إلى حين', NULL, 443, 'local:hafs-text.json'),
  ('hafs-36-45', 'hafs', 36, 45, 'وَإِذَا قِيلَ لَهُمُ ٱتَّقُوا۟ مَا بَيْنَ أَيْدِيكُمْ وَمَا خَلْفَكُمْ لَعَلَّكُمْ تُرْحَمُونَ', 'وإذا قيل لهم اتقوا ما بين أيديكم وما خلفكم لعلكم ترحمون', NULL, 443, 'local:hafs-text.json'),
  ('hafs-36-46', 'hafs', 36, 46, 'وَمَا تَأْتِيهِم مِّنْ ءَايَةٍۢ مِّنْ ءَايَٰتِ رَبِّهِمْ إِلَّا كَانُوا۟ عَنْهَا مُعْرِضِينَ', 'وما تأتيهم من ءاية من ءايت ربهم إلا كانوا عنها معرضين', NULL, 443, 'local:hafs-text.json'),
  ('hafs-36-47', 'hafs', 36, 47, 'وَإِذَا قِيلَ لَهُمْ أَنفِقُوا۟ مِمَّا رَزَقَكُمُ ٱللَّهُ قَالَ ٱلَّذِينَ كَفَرُوا۟ لِلَّذِينَ ءَامَنُوٓا۟ أَنُطْعِمُ مَن لَّوْ يَشَآءُ ٱللَّهُ أَطْعَمَهُۥٓ إِنْ أَنتُمْ إِلَّا فِى ضَلَٰلٍۢ مُّبِينٍۢ', 'وإذا قيل لهم أنفقوا مما رزقكم الله قال الذين كفروا للذين ءامنوا أنطعم من لو يشاء الله أطعمه إن أنتم إلا فى ضلل مبين', NULL, 443, 'local:hafs-text.json'),
  ('hafs-36-48', 'hafs', 36, 48, 'وَيَقُولُونَ مَتَىٰ هَٰذَا ٱلْوَعْدُ إِن كُنتُمْ صَٰدِقِينَ', 'ويقولون متى هذا الوعد إن كنتم صدقين', NULL, 443, 'local:hafs-text.json'),
  ('hafs-36-49', 'hafs', 36, 49, 'مَا يَنظُرُونَ إِلَّا صَيْحَةًۭ وَٰحِدَةًۭ تَأْخُذُهُمْ وَهُمْ يَخِصِّمُونَ', 'ما ينظرون إلا صيحة وحدة تأخذهم وهم يخصمون', NULL, 443, 'local:hafs-text.json'),
  ('hafs-36-50', 'hafs', 36, 50, 'فَلَا يَسْتَطِيعُونَ تَوْصِيَةًۭ وَلَآ إِلَىٰٓ أَهْلِهِمْ يَرْجِعُونَ', 'فلا يستطيعون توصية ولا إلى أهلهم يرجعون', NULL, 443, 'local:hafs-text.json'),
  ('hafs-36-51', 'hafs', 36, 51, 'وَنُفِخَ فِى ٱلصُّورِ فَإِذَا هُم مِّنَ ٱلْأَجْدَاثِ إِلَىٰ رَبِّهِمْ يَنسِلُونَ', 'ونفخ فى الصور فإذا هم من الأجداث إلى ربهم ينسلون', NULL, 443, 'local:hafs-text.json'),
  ('hafs-36-52', 'hafs', 36, 52, 'قَالُوا۟ يَٰوَيْلَنَا مَنۢ بَعَثَنَا مِن مَّرْقَدِنَا ۜ ۗ هَٰذَا مَا وَعَدَ ٱلرَّحْمَٰنُ وَصَدَقَ ٱلْمُرْسَلُونَ', 'قالوا يويلنا من بعثنا من مرقدنا   هذا ما وعد الرحمن وصدق المرسلون', NULL, 443, 'local:hafs-text.json'),
  ('hafs-36-53', 'hafs', 36, 53, 'إِن كَانَتْ إِلَّا صَيْحَةًۭ وَٰحِدَةًۭ فَإِذَا هُمْ جَمِيعٌۭ لَّدَيْنَا مُحْضَرُونَ', 'إن كانت إلا صيحة وحدة فإذا هم جميع لدينا محضرون', NULL, 443, 'local:hafs-text.json'),
  ('hafs-36-54', 'hafs', 36, 54, 'فَٱلْيَوْمَ لَا تُظْلَمُ نَفْسٌۭ شَيْـًۭٔا وَلَا تُجْزَوْنَ إِلَّا مَا كُنتُمْ تَعْمَلُونَ', 'فاليوم لا تظلم نفس شيا ولا تجزون إلا ما كنتم تعملون', NULL, 443, 'local:hafs-text.json'),
  ('hafs-36-55', 'hafs', 36, 55, 'إِنَّ أَصْحَٰبَ ٱلْجَنَّةِ ٱلْيَوْمَ فِى شُغُلٍۢ فَٰكِهُونَ', 'إن أصحب الجنة اليوم فى شغل فكهون', NULL, 444, 'local:hafs-text.json'),
  ('hafs-36-56', 'hafs', 36, 56, 'هُمْ وَأَزْوَٰجُهُمْ فِى ظِلَٰلٍ عَلَى ٱلْأَرَآئِكِ مُتَّكِـُٔونَ', 'هم وأزوجهم فى ظلل على الأرائك متكون', NULL, 444, 'local:hafs-text.json'),
  ('hafs-36-57', 'hafs', 36, 57, 'لَهُمْ فِيهَا فَٰكِهَةٌۭ وَلَهُم مَّا يَدَّعُونَ', 'لهم فيها فكهة ولهم ما يدعون', NULL, 444, 'local:hafs-text.json'),
  ('hafs-36-58', 'hafs', 36, 58, 'سَلَٰمٌۭ قَوْلًۭا مِّن رَّبٍّۢ رَّحِيمٍۢ', 'سلم قولا من رب رحيم', NULL, 444, 'local:hafs-text.json'),
  ('hafs-36-59', 'hafs', 36, 59, 'وَٱمْتَٰزُوا۟ ٱلْيَوْمَ أَيُّهَا ٱلْمُجْرِمُونَ', 'وامتزوا اليوم أيها المجرمون', NULL, 444, 'local:hafs-text.json'),
  ('hafs-36-60', 'hafs', 36, 60, '۞ أَلَمْ أَعْهَدْ إِلَيْكُمْ يَٰبَنِىٓ ءَادَمَ أَن لَّا تَعْبُدُوا۟ ٱلشَّيْطَٰنَ ۖ إِنَّهُۥ لَكُمْ عَدُوٌّۭ مُّبِينٌۭ', 'ألم أعهد إليكم يبنى ءادم أن لا تعبدوا الشيطن  إنه لكم عدو مبين', NULL, 444, 'local:hafs-text.json'),
  ('hafs-36-61', 'hafs', 36, 61, 'وَأَنِ ٱعْبُدُونِى ۚ هَٰذَا صِرَٰطٌۭ مُّسْتَقِيمٌۭ', 'وأن اعبدونى  هذا صرط مستقيم', NULL, 444, 'local:hafs-text.json'),
  ('hafs-36-62', 'hafs', 36, 62, 'وَلَقَدْ أَضَلَّ مِنكُمْ جِبِلًّۭا كَثِيرًا ۖ أَفَلَمْ تَكُونُوا۟ تَعْقِلُونَ', 'ولقد أضل منكم جبلا كثيرا  أفلم تكونوا تعقلون', NULL, 444, 'local:hafs-text.json'),
  ('hafs-36-63', 'hafs', 36, 63, 'هَٰذِهِۦ جَهَنَّمُ ٱلَّتِى كُنتُمْ تُوعَدُونَ', 'هذه جهنم التى كنتم توعدون', NULL, 444, 'local:hafs-text.json'),
  ('hafs-36-64', 'hafs', 36, 64, 'ٱصْلَوْهَا ٱلْيَوْمَ بِمَا كُنتُمْ تَكْفُرُونَ', 'اصلوها اليوم بما كنتم تكفرون', NULL, 444, 'local:hafs-text.json'),
  ('hafs-36-65', 'hafs', 36, 65, 'ٱلْيَوْمَ نَخْتِمُ عَلَىٰٓ أَفْوَٰهِهِمْ وَتُكَلِّمُنَآ أَيْدِيهِمْ وَتَشْهَدُ أَرْجُلُهُم بِمَا كَانُوا۟ يَكْسِبُونَ', 'اليوم نختم على أفوههم وتكلمنا أيديهم وتشهد أرجلهم بما كانوا يكسبون', NULL, 444, 'local:hafs-text.json'),
  ('hafs-36-66', 'hafs', 36, 66, 'وَلَوْ نَشَآءُ لَطَمَسْنَا عَلَىٰٓ أَعْيُنِهِمْ فَٱسْتَبَقُوا۟ ٱلصِّرَٰطَ فَأَنَّىٰ يُبْصِرُونَ', 'ولو نشاء لطمسنا على أعينهم فاستبقوا الصرط فأنى يبصرون', NULL, 444, 'local:hafs-text.json'),
  ('hafs-36-67', 'hafs', 36, 67, 'وَلَوْ نَشَآءُ لَمَسَخْنَٰهُمْ عَلَىٰ مَكَانَتِهِمْ فَمَا ٱسْتَطَٰعُوا۟ مُضِيًّۭا وَلَا يَرْجِعُونَ', 'ولو نشاء لمسخنهم على مكانتهم فما استطعوا مضيا ولا يرجعون', NULL, 444, 'local:hafs-text.json'),
  ('hafs-36-68', 'hafs', 36, 68, 'وَمَن نُّعَمِّرْهُ نُنَكِّسْهُ فِى ٱلْخَلْقِ ۖ أَفَلَا يَعْقِلُونَ', 'ومن نعمره ننكسه فى الخلق  أفلا يعقلون', NULL, 444, 'local:hafs-text.json'),
  ('hafs-36-69', 'hafs', 36, 69, 'وَمَا عَلَّمْنَٰهُ ٱلشِّعْرَ وَمَا يَنۢبَغِى لَهُۥٓ ۚ إِنْ هُوَ إِلَّا ذِكْرٌۭ وَقُرْءَانٌۭ مُّبِينٌۭ', 'وما علمنه الشعر وما ينبغى له  إن هو إلا ذكر وقرءان مبين', NULL, 444, 'local:hafs-text.json'),
  ('hafs-36-70', 'hafs', 36, 70, 'لِّيُنذِرَ مَن كَانَ حَيًّۭا وَيَحِقَّ ٱلْقَوْلُ عَلَى ٱلْكَٰفِرِينَ', 'لينذر من كان حيا ويحق القول على الكفرين', NULL, 444, 'local:hafs-text.json'),
  ('hafs-36-71', 'hafs', 36, 71, 'أَوَلَمْ يَرَوْا۟ أَنَّا خَلَقْنَا لَهُم مِّمَّا عَمِلَتْ أَيْدِينَآ أَنْعَٰمًۭا فَهُمْ لَهَا مَٰلِكُونَ', 'أولم يروا أنا خلقنا لهم مما عملت أيدينا أنعما فهم لها ملكون', NULL, 445, 'local:hafs-text.json'),
  ('hafs-36-72', 'hafs', 36, 72, 'وَذَلَّلْنَٰهَا لَهُمْ فَمِنْهَا رَكُوبُهُمْ وَمِنْهَا يَأْكُلُونَ', 'وذللنها لهم فمنها ركوبهم ومنها يأكلون', NULL, 445, 'local:hafs-text.json'),
  ('hafs-36-73', 'hafs', 36, 73, 'وَلَهُمْ فِيهَا مَنَٰفِعُ وَمَشَارِبُ ۖ أَفَلَا يَشْكُرُونَ', 'ولهم فيها منفع ومشارب  أفلا يشكرون', NULL, 445, 'local:hafs-text.json'),
  ('hafs-36-74', 'hafs', 36, 74, 'وَٱتَّخَذُوا۟ مِن دُونِ ٱللَّهِ ءَالِهَةًۭ لَّعَلَّهُمْ يُنصَرُونَ', 'واتخذوا من دون الله ءالهة لعلهم ينصرون', NULL, 445, 'local:hafs-text.json'),
  ('hafs-36-75', 'hafs', 36, 75, 'لَا يَسْتَطِيعُونَ نَصْرَهُمْ وَهُمْ لَهُمْ جُندٌۭ مُّحْضَرُونَ', 'لا يستطيعون نصرهم وهم لهم جند محضرون', NULL, 445, 'local:hafs-text.json'),
  ('hafs-36-76', 'hafs', 36, 76, 'فَلَا يَحْزُنكَ قَوْلُهُمْ ۘ إِنَّا نَعْلَمُ مَا يُسِرُّونَ وَمَا يُعْلِنُونَ', 'فلا يحزنك قولهم  إنا نعلم ما يسرون وما يعلنون', NULL, 445, 'local:hafs-text.json'),
  ('hafs-36-77', 'hafs', 36, 77, 'أَوَلَمْ يَرَ ٱلْإِنسَٰنُ أَنَّا خَلَقْنَٰهُ مِن نُّطْفَةٍۢ فَإِذَا هُوَ خَصِيمٌۭ مُّبِينٌۭ', 'أولم ير الإنسن أنا خلقنه من نطفة فإذا هو خصيم مبين', NULL, 445, 'local:hafs-text.json'),
  ('hafs-36-78', 'hafs', 36, 78, 'وَضَرَبَ لَنَا مَثَلًۭا وَنَسِىَ خَلْقَهُۥ ۖ قَالَ مَن يُحْىِ ٱلْعِظَٰمَ وَهِىَ رَمِيمٌۭ', 'وضرب لنا مثلا ونسى خلقه  قال من يحى العظم وهى رميم', NULL, 445, 'local:hafs-text.json'),
  ('hafs-36-79', 'hafs', 36, 79, 'قُلْ يُحْيِيهَا ٱلَّذِىٓ أَنشَأَهَآ أَوَّلَ مَرَّةٍۢ ۖ وَهُوَ بِكُلِّ خَلْقٍ عَلِيمٌ', 'قل يحييها الذى أنشأها أول مرة  وهو بكل خلق عليم', NULL, 445, 'local:hafs-text.json'),
  ('hafs-36-80', 'hafs', 36, 80, 'ٱلَّذِى جَعَلَ لَكُم مِّنَ ٱلشَّجَرِ ٱلْأَخْضَرِ نَارًۭا فَإِذَآ أَنتُم مِّنْهُ تُوقِدُونَ', 'الذى جعل لكم من الشجر الأخضر نارا فإذا أنتم منه توقدون', NULL, 445, 'local:hafs-text.json'),
  ('hafs-36-81', 'hafs', 36, 81, 'أَوَلَيْسَ ٱلَّذِى خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ بِقَٰدِرٍ عَلَىٰٓ أَن يَخْلُقَ مِثْلَهُم ۚ بَلَىٰ وَهُوَ ٱلْخَلَّٰقُ ٱلْعَلِيمُ', 'أوليس الذى خلق السموت والأرض بقدر على أن يخلق مثلهم  بلى وهو الخلق العليم', NULL, 445, 'local:hafs-text.json'),
  ('hafs-36-82', 'hafs', 36, 82, 'إِنَّمَآ أَمْرُهُۥٓ إِذَآ أَرَادَ شَيْـًٔا أَن يَقُولَ لَهُۥ كُن فَيَكُونُ', 'إنما أمره إذا أراد شيا أن يقول له كن فيكون', NULL, 445, 'local:hafs-text.json'),
  ('hafs-36-83', 'hafs', 36, 83, 'فَسُبْحَٰنَ ٱلَّذِى بِيَدِهِۦ مَلَكُوتُ كُلِّ شَىْءٍۢ وَإِلَيْهِ تُرْجَعُونَ', 'فسبحن الذى بيده ملكوت كل شىء وإليه ترجعون', NULL, 445, 'local:hafs-text.json'),
  ('hafs-37-1', 'hafs', 37, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ وَٱلصَّٰٓفَّٰتِ صَفًّۭا', 'بسم الله الرحمن الرحيم والصفت صفا', NULL, 446, 'local:hafs-text.json'),
  ('hafs-37-2', 'hafs', 37, 2, 'فَٱلزَّٰجِرَٰتِ زَجْرًۭا', 'فالزجرت زجرا', NULL, 446, 'local:hafs-text.json'),
  ('hafs-37-3', 'hafs', 37, 3, 'فَٱلتَّٰلِيَٰتِ ذِكْرًا', 'فالتليت ذكرا', NULL, 446, 'local:hafs-text.json'),
  ('hafs-37-4', 'hafs', 37, 4, 'إِنَّ إِلَٰهَكُمْ لَوَٰحِدٌۭ', 'إن إلهكم لوحد', NULL, 446, 'local:hafs-text.json'),
  ('hafs-37-5', 'hafs', 37, 5, 'رَّبُّ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَمَا بَيْنَهُمَا وَرَبُّ ٱلْمَشَٰرِقِ', 'رب السموت والأرض وما بينهما ورب المشرق', NULL, 446, 'local:hafs-text.json'),
  ('hafs-37-6', 'hafs', 37, 6, 'إِنَّا زَيَّنَّا ٱلسَّمَآءَ ٱلدُّنْيَا بِزِينَةٍ ٱلْكَوَاكِبِ', 'إنا زينا السماء الدنيا بزينة الكواكب', NULL, 446, 'local:hafs-text.json'),
  ('hafs-37-7', 'hafs', 37, 7, 'وَحِفْظًۭا مِّن كُلِّ شَيْطَٰنٍۢ مَّارِدٍۢ', 'وحفظا من كل شيطن مارد', NULL, 446, 'local:hafs-text.json'),
  ('hafs-37-8', 'hafs', 37, 8, 'لَّا يَسَّمَّعُونَ إِلَى ٱلْمَلَإِ ٱلْأَعْلَىٰ وَيُقْذَفُونَ مِن كُلِّ جَانِبٍۢ', 'لا يسمعون إلى الملإ الأعلى ويقذفون من كل جانب', NULL, 446, 'local:hafs-text.json'),
  ('hafs-37-9', 'hafs', 37, 9, 'دُحُورًۭا ۖ وَلَهُمْ عَذَابٌۭ وَاصِبٌ', 'دحورا  ولهم عذاب واصب', NULL, 446, 'local:hafs-text.json'),
  ('hafs-37-10', 'hafs', 37, 10, 'إِلَّا مَنْ خَطِفَ ٱلْخَطْفَةَ فَأَتْبَعَهُۥ شِهَابٌۭ ثَاقِبٌۭ', 'إلا من خطف الخطفة فأتبعه شهاب ثاقب', NULL, 446, 'local:hafs-text.json'),
  ('hafs-37-11', 'hafs', 37, 11, 'فَٱسْتَفْتِهِمْ أَهُمْ أَشَدُّ خَلْقًا أَم مَّنْ خَلَقْنَآ ۚ إِنَّا خَلَقْنَٰهُم مِّن طِينٍۢ لَّازِبٍۭ', 'فاستفتهم أهم أشد خلقا أم من خلقنا  إنا خلقنهم من طين لازب', NULL, 446, 'local:hafs-text.json'),
  ('hafs-37-12', 'hafs', 37, 12, 'بَلْ عَجِبْتَ وَيَسْخَرُونَ', 'بل عجبت ويسخرون', NULL, 446, 'local:hafs-text.json'),
  ('hafs-37-13', 'hafs', 37, 13, 'وَإِذَا ذُكِّرُوا۟ لَا يَذْكُرُونَ', 'وإذا ذكروا لا يذكرون', NULL, 446, 'local:hafs-text.json'),
  ('hafs-37-14', 'hafs', 37, 14, 'وَإِذَا رَأَوْا۟ ءَايَةًۭ يَسْتَسْخِرُونَ', 'وإذا رأوا ءاية يستسخرون', NULL, 446, 'local:hafs-text.json'),
  ('hafs-37-15', 'hafs', 37, 15, 'وَقَالُوٓا۟ إِنْ هَٰذَآ إِلَّا سِحْرٌۭ مُّبِينٌ', 'وقالوا إن هذا إلا سحر مبين', NULL, 446, 'local:hafs-text.json'),
  ('hafs-37-16', 'hafs', 37, 16, 'أَءِذَا مِتْنَا وَكُنَّا تُرَابًۭا وَعِظَٰمًا أَءِنَّا لَمَبْعُوثُونَ', 'أءذا متنا وكنا ترابا وعظما أءنا لمبعوثون', NULL, 446, 'local:hafs-text.json'),
  ('hafs-37-17', 'hafs', 37, 17, 'أَوَءَابَآؤُنَا ٱلْأَوَّلُونَ', 'أوءاباؤنا الأولون', NULL, 446, 'local:hafs-text.json'),
  ('hafs-37-18', 'hafs', 37, 18, 'قُلْ نَعَمْ وَأَنتُمْ دَٰخِرُونَ', 'قل نعم وأنتم دخرون', NULL, 446, 'local:hafs-text.json'),
  ('hafs-37-19', 'hafs', 37, 19, 'فَإِنَّمَا هِىَ زَجْرَةٌۭ وَٰحِدَةٌۭ فَإِذَا هُمْ يَنظُرُونَ', 'فإنما هى زجرة وحدة فإذا هم ينظرون', NULL, 446, 'local:hafs-text.json'),
  ('hafs-37-20', 'hafs', 37, 20, 'وَقَالُوا۟ يَٰوَيْلَنَا هَٰذَا يَوْمُ ٱلدِّينِ', 'وقالوا يويلنا هذا يوم الدين', NULL, 446, 'local:hafs-text.json'),
  ('hafs-37-21', 'hafs', 37, 21, 'هَٰذَا يَوْمُ ٱلْفَصْلِ ٱلَّذِى كُنتُم بِهِۦ تُكَذِّبُونَ', 'هذا يوم الفصل الذى كنتم به تكذبون', NULL, 446, 'local:hafs-text.json'),
  ('hafs-37-22', 'hafs', 37, 22, '۞ ٱحْشُرُوا۟ ٱلَّذِينَ ظَلَمُوا۟ وَأَزْوَٰجَهُمْ وَمَا كَانُوا۟ يَعْبُدُونَ', 'احشروا الذين ظلموا وأزوجهم وما كانوا يعبدون', NULL, 446, 'local:hafs-text.json'),
  ('hafs-37-23', 'hafs', 37, 23, 'مِن دُونِ ٱللَّهِ فَٱهْدُوهُمْ إِلَىٰ صِرَٰطِ ٱلْجَحِيمِ', 'من دون الله فاهدوهم إلى صرط الجحيم', NULL, 446, 'local:hafs-text.json'),
  ('hafs-37-24', 'hafs', 37, 24, 'وَقِفُوهُمْ ۖ إِنَّهُم مَّسْـُٔولُونَ', 'وقفوهم  إنهم مسولون', NULL, 446, 'local:hafs-text.json'),
  ('hafs-37-25', 'hafs', 37, 25, 'مَا لَكُمْ لَا تَنَاصَرُونَ', 'ما لكم لا تناصرون', NULL, 447, 'local:hafs-text.json'),
  ('hafs-37-26', 'hafs', 37, 26, 'بَلْ هُمُ ٱلْيَوْمَ مُسْتَسْلِمُونَ', 'بل هم اليوم مستسلمون', NULL, 447, 'local:hafs-text.json'),
  ('hafs-37-27', 'hafs', 37, 27, 'وَأَقْبَلَ بَعْضُهُمْ عَلَىٰ بَعْضٍۢ يَتَسَآءَلُونَ', 'وأقبل بعضهم على بعض يتساءلون', NULL, 447, 'local:hafs-text.json'),
  ('hafs-37-28', 'hafs', 37, 28, 'قَالُوٓا۟ إِنَّكُمْ كُنتُمْ تَأْتُونَنَا عَنِ ٱلْيَمِينِ', 'قالوا إنكم كنتم تأتوننا عن اليمين', NULL, 447, 'local:hafs-text.json'),
  ('hafs-37-29', 'hafs', 37, 29, 'قَالُوا۟ بَل لَّمْ تَكُونُوا۟ مُؤْمِنِينَ', 'قالوا بل لم تكونوا مؤمنين', NULL, 447, 'local:hafs-text.json'),
  ('hafs-37-30', 'hafs', 37, 30, 'وَمَا كَانَ لَنَا عَلَيْكُم مِّن سُلْطَٰنٍۭ ۖ بَلْ كُنتُمْ قَوْمًۭا طَٰغِينَ', 'وما كان لنا عليكم من سلطن  بل كنتم قوما طغين', NULL, 447, 'local:hafs-text.json'),
  ('hafs-37-31', 'hafs', 37, 31, 'فَحَقَّ عَلَيْنَا قَوْلُ رَبِّنَآ ۖ إِنَّا لَذَآئِقُونَ', 'فحق علينا قول ربنا  إنا لذائقون', NULL, 447, 'local:hafs-text.json'),
  ('hafs-37-32', 'hafs', 37, 32, 'فَأَغْوَيْنَٰكُمْ إِنَّا كُنَّا غَٰوِينَ', 'فأغوينكم إنا كنا غوين', NULL, 447, 'local:hafs-text.json'),
  ('hafs-37-33', 'hafs', 37, 33, 'فَإِنَّهُمْ يَوْمَئِذٍۢ فِى ٱلْعَذَابِ مُشْتَرِكُونَ', 'فإنهم يومئذ فى العذاب مشتركون', NULL, 447, 'local:hafs-text.json'),
  ('hafs-37-34', 'hafs', 37, 34, 'إِنَّا كَذَٰلِكَ نَفْعَلُ بِٱلْمُجْرِمِينَ', 'إنا كذلك نفعل بالمجرمين', NULL, 447, 'local:hafs-text.json'),
  ('hafs-37-35', 'hafs', 37, 35, 'إِنَّهُمْ كَانُوٓا۟ إِذَا قِيلَ لَهُمْ لَآ إِلَٰهَ إِلَّا ٱللَّهُ يَسْتَكْبِرُونَ', 'إنهم كانوا إذا قيل لهم لا إله إلا الله يستكبرون', NULL, 447, 'local:hafs-text.json'),
  ('hafs-37-36', 'hafs', 37, 36, 'وَيَقُولُونَ أَئِنَّا لَتَارِكُوٓا۟ ءَالِهَتِنَا لِشَاعِرٍۢ مَّجْنُونٍۭ', 'ويقولون أئنا لتاركوا ءالهتنا لشاعر مجنون', NULL, 447, 'local:hafs-text.json'),
  ('hafs-37-37', 'hafs', 37, 37, 'بَلْ جَآءَ بِٱلْحَقِّ وَصَدَّقَ ٱلْمُرْسَلِينَ', 'بل جاء بالحق وصدق المرسلين', NULL, 447, 'local:hafs-text.json'),
  ('hafs-37-38', 'hafs', 37, 38, 'إِنَّكُمْ لَذَآئِقُوا۟ ٱلْعَذَابِ ٱلْأَلِيمِ', 'إنكم لذائقوا العذاب الأليم', NULL, 447, 'local:hafs-text.json'),
  ('hafs-37-39', 'hafs', 37, 39, 'وَمَا تُجْزَوْنَ إِلَّا مَا كُنتُمْ تَعْمَلُونَ', 'وما تجزون إلا ما كنتم تعملون', NULL, 447, 'local:hafs-text.json'),
  ('hafs-37-40', 'hafs', 37, 40, 'إِلَّا عِبَادَ ٱللَّهِ ٱلْمُخْلَصِينَ', 'إلا عباد الله المخلصين', NULL, 447, 'local:hafs-text.json'),
  ('hafs-37-41', 'hafs', 37, 41, 'أُو۟لَٰٓئِكَ لَهُمْ رِزْقٌۭ مَّعْلُومٌۭ', 'أولئك لهم رزق معلوم', NULL, 447, 'local:hafs-text.json'),
  ('hafs-37-42', 'hafs', 37, 42, 'فَوَٰكِهُ ۖ وَهُم مُّكْرَمُونَ', 'فوكه  وهم مكرمون', NULL, 447, 'local:hafs-text.json'),
  ('hafs-37-43', 'hafs', 37, 43, 'فِى جَنَّٰتِ ٱلنَّعِيمِ', 'فى جنت النعيم', NULL, 447, 'local:hafs-text.json'),
  ('hafs-37-44', 'hafs', 37, 44, 'عَلَىٰ سُرُرٍۢ مُّتَقَٰبِلِينَ', 'على سرر متقبلين', NULL, 447, 'local:hafs-text.json'),
  ('hafs-37-45', 'hafs', 37, 45, 'يُطَافُ عَلَيْهِم بِكَأْسٍۢ مِّن مَّعِينٍۭ', 'يطاف عليهم بكأس من معين', NULL, 447, 'local:hafs-text.json'),
  ('hafs-37-46', 'hafs', 37, 46, 'بَيْضَآءَ لَذَّةٍۢ لِّلشَّٰرِبِينَ', 'بيضاء لذة للشربين', NULL, 447, 'local:hafs-text.json'),
  ('hafs-37-47', 'hafs', 37, 47, 'لَا فِيهَا غَوْلٌۭ وَلَا هُمْ عَنْهَا يُنزَفُونَ', 'لا فيها غول ولا هم عنها ينزفون', NULL, 447, 'local:hafs-text.json'),
  ('hafs-37-48', 'hafs', 37, 48, 'وَعِندَهُمْ قَٰصِرَٰتُ ٱلطَّرْفِ عِينٌۭ', 'وعندهم قصرت الطرف عين', NULL, 447, 'local:hafs-text.json'),
  ('hafs-37-49', 'hafs', 37, 49, 'كَأَنَّهُنَّ بَيْضٌۭ مَّكْنُونٌۭ', 'كأنهن بيض مكنون', NULL, 447, 'local:hafs-text.json'),
  ('hafs-37-50', 'hafs', 37, 50, 'فَأَقْبَلَ بَعْضُهُمْ عَلَىٰ بَعْضٍۢ يَتَسَآءَلُونَ', 'فأقبل بعضهم على بعض يتساءلون', NULL, 447, 'local:hafs-text.json'),
  ('hafs-37-51', 'hafs', 37, 51, 'قَالَ قَآئِلٌۭ مِّنْهُمْ إِنِّى كَانَ لِى قَرِينٌۭ', 'قال قائل منهم إنى كان لى قرين', NULL, 447, 'local:hafs-text.json'),
  ('hafs-37-52', 'hafs', 37, 52, 'يَقُولُ أَءِنَّكَ لَمِنَ ٱلْمُصَدِّقِينَ', 'يقول أءنك لمن المصدقين', NULL, 448, 'local:hafs-text.json'),
  ('hafs-37-53', 'hafs', 37, 53, 'أَءِذَا مِتْنَا وَكُنَّا تُرَابًۭا وَعِظَٰمًا أَءِنَّا لَمَدِينُونَ', 'أءذا متنا وكنا ترابا وعظما أءنا لمدينون', NULL, 448, 'local:hafs-text.json'),
  ('hafs-37-54', 'hafs', 37, 54, 'قَالَ هَلْ أَنتُم مُّطَّلِعُونَ', 'قال هل أنتم مطلعون', NULL, 448, 'local:hafs-text.json'),
  ('hafs-37-55', 'hafs', 37, 55, 'فَٱطَّلَعَ فَرَءَاهُ فِى سَوَآءِ ٱلْجَحِيمِ', 'فاطلع فرءاه فى سواء الجحيم', NULL, 448, 'local:hafs-text.json'),
  ('hafs-37-56', 'hafs', 37, 56, 'قَالَ تَٱللَّهِ إِن كِدتَّ لَتُرْدِينِ', 'قال تالله إن كدت لتردين', NULL, 448, 'local:hafs-text.json'),
  ('hafs-37-57', 'hafs', 37, 57, 'وَلَوْلَا نِعْمَةُ رَبِّى لَكُنتُ مِنَ ٱلْمُحْضَرِينَ', 'ولولا نعمة ربى لكنت من المحضرين', NULL, 448, 'local:hafs-text.json'),
  ('hafs-37-58', 'hafs', 37, 58, 'أَفَمَا نَحْنُ بِمَيِّتِينَ', 'أفما نحن بميتين', NULL, 448, 'local:hafs-text.json'),
  ('hafs-37-59', 'hafs', 37, 59, 'إِلَّا مَوْتَتَنَا ٱلْأُولَىٰ وَمَا نَحْنُ بِمُعَذَّبِينَ', 'إلا موتتنا الأولى وما نحن بمعذبين', NULL, 448, 'local:hafs-text.json'),
  ('hafs-37-60', 'hafs', 37, 60, 'إِنَّ هَٰذَا لَهُوَ ٱلْفَوْزُ ٱلْعَظِيمُ', 'إن هذا لهو الفوز العظيم', NULL, 448, 'local:hafs-text.json'),
  ('hafs-37-61', 'hafs', 37, 61, 'لِمِثْلِ هَٰذَا فَلْيَعْمَلِ ٱلْعَٰمِلُونَ', 'لمثل هذا فليعمل العملون', NULL, 448, 'local:hafs-text.json'),
  ('hafs-37-62', 'hafs', 37, 62, 'أَذَٰلِكَ خَيْرٌۭ نُّزُلًا أَمْ شَجَرَةُ ٱلزَّقُّومِ', 'أذلك خير نزلا أم شجرة الزقوم', NULL, 448, 'local:hafs-text.json'),
  ('hafs-37-63', 'hafs', 37, 63, 'إِنَّا جَعَلْنَٰهَا فِتْنَةًۭ لِّلظَّٰلِمِينَ', 'إنا جعلنها فتنة للظلمين', NULL, 448, 'local:hafs-text.json'),
  ('hafs-37-64', 'hafs', 37, 64, 'إِنَّهَا شَجَرَةٌۭ تَخْرُجُ فِىٓ أَصْلِ ٱلْجَحِيمِ', 'إنها شجرة تخرج فى أصل الجحيم', NULL, 448, 'local:hafs-text.json'),
  ('hafs-37-65', 'hafs', 37, 65, 'طَلْعُهَا كَأَنَّهُۥ رُءُوسُ ٱلشَّيَٰطِينِ', 'طلعها كأنه رءوس الشيطين', NULL, 448, 'local:hafs-text.json'),
  ('hafs-37-66', 'hafs', 37, 66, 'فَإِنَّهُمْ لَءَاكِلُونَ مِنْهَا فَمَالِـُٔونَ مِنْهَا ٱلْبُطُونَ', 'فإنهم لءاكلون منها فمالون منها البطون', NULL, 448, 'local:hafs-text.json'),
  ('hafs-37-67', 'hafs', 37, 67, 'ثُمَّ إِنَّ لَهُمْ عَلَيْهَا لَشَوْبًۭا مِّنْ حَمِيمٍۢ', 'ثم إن لهم عليها لشوبا من حميم', NULL, 448, 'local:hafs-text.json'),
  ('hafs-37-68', 'hafs', 37, 68, 'ثُمَّ إِنَّ مَرْجِعَهُمْ لَإِلَى ٱلْجَحِيمِ', 'ثم إن مرجعهم لإلى الجحيم', NULL, 448, 'local:hafs-text.json'),
  ('hafs-37-69', 'hafs', 37, 69, 'إِنَّهُمْ أَلْفَوْا۟ ءَابَآءَهُمْ ضَآلِّينَ', 'إنهم ألفوا ءاباءهم ضالين', NULL, 448, 'local:hafs-text.json'),
  ('hafs-37-70', 'hafs', 37, 70, 'فَهُمْ عَلَىٰٓ ءَاثَٰرِهِمْ يُهْرَعُونَ', 'فهم على ءاثرهم يهرعون', NULL, 448, 'local:hafs-text.json'),
  ('hafs-37-71', 'hafs', 37, 71, 'وَلَقَدْ ضَلَّ قَبْلَهُمْ أَكْثَرُ ٱلْأَوَّلِينَ', 'ولقد ضل قبلهم أكثر الأولين', NULL, 448, 'local:hafs-text.json'),
  ('hafs-37-72', 'hafs', 37, 72, 'وَلَقَدْ أَرْسَلْنَا فِيهِم مُّنذِرِينَ', 'ولقد أرسلنا فيهم منذرين', NULL, 448, 'local:hafs-text.json'),
  ('hafs-37-73', 'hafs', 37, 73, 'فَٱنظُرْ كَيْفَ كَانَ عَٰقِبَةُ ٱلْمُنذَرِينَ', 'فانظر كيف كان عقبة المنذرين', NULL, 448, 'local:hafs-text.json'),
  ('hafs-37-74', 'hafs', 37, 74, 'إِلَّا عِبَادَ ٱللَّهِ ٱلْمُخْلَصِينَ', 'إلا عباد الله المخلصين', NULL, 448, 'local:hafs-text.json'),
  ('hafs-37-75', 'hafs', 37, 75, 'وَلَقَدْ نَادَىٰنَا نُوحٌۭ فَلَنِعْمَ ٱلْمُجِيبُونَ', 'ولقد نادىنا نوح فلنعم المجيبون', NULL, 448, 'local:hafs-text.json'),
  ('hafs-37-76', 'hafs', 37, 76, 'وَنَجَّيْنَٰهُ وَأَهْلَهُۥ مِنَ ٱلْكَرْبِ ٱلْعَظِيمِ', 'ونجينه وأهله من الكرب العظيم', NULL, 448, 'local:hafs-text.json'),
  ('hafs-37-77', 'hafs', 37, 77, 'وَجَعَلْنَا ذُرِّيَّتَهُۥ هُمُ ٱلْبَاقِينَ', 'وجعلنا ذريته هم الباقين', NULL, 449, 'local:hafs-text.json'),
  ('hafs-37-78', 'hafs', 37, 78, 'وَتَرَكْنَا عَلَيْهِ فِى ٱلْءَاخِرِينَ', 'وتركنا عليه فى الءاخرين', NULL, 449, 'local:hafs-text.json'),
  ('hafs-37-79', 'hafs', 37, 79, 'سَلَٰمٌ عَلَىٰ نُوحٍۢ فِى ٱلْعَٰلَمِينَ', 'سلم على نوح فى العلمين', NULL, 449, 'local:hafs-text.json'),
  ('hafs-37-80', 'hafs', 37, 80, 'إِنَّا كَذَٰلِكَ نَجْزِى ٱلْمُحْسِنِينَ', 'إنا كذلك نجزى المحسنين', NULL, 449, 'local:hafs-text.json'),
  ('hafs-37-81', 'hafs', 37, 81, 'إِنَّهُۥ مِنْ عِبَادِنَا ٱلْمُؤْمِنِينَ', 'إنه من عبادنا المؤمنين', NULL, 449, 'local:hafs-text.json'),
  ('hafs-37-82', 'hafs', 37, 82, 'ثُمَّ أَغْرَقْنَا ٱلْءَاخَرِينَ', 'ثم أغرقنا الءاخرين', NULL, 449, 'local:hafs-text.json'),
  ('hafs-37-83', 'hafs', 37, 83, '۞ وَإِنَّ مِن شِيعَتِهِۦ لَإِبْرَٰهِيمَ', 'وإن من شيعته لإبرهيم', NULL, 449, 'local:hafs-text.json'),
  ('hafs-37-84', 'hafs', 37, 84, 'إِذْ جَآءَ رَبَّهُۥ بِقَلْبٍۢ سَلِيمٍ', 'إذ جاء ربه بقلب سليم', NULL, 449, 'local:hafs-text.json'),
  ('hafs-37-85', 'hafs', 37, 85, 'إِذْ قَالَ لِأَبِيهِ وَقَوْمِهِۦ مَاذَا تَعْبُدُونَ', 'إذ قال لأبيه وقومه ماذا تعبدون', NULL, 449, 'local:hafs-text.json'),
  ('hafs-37-86', 'hafs', 37, 86, 'أَئِفْكًا ءَالِهَةًۭ دُونَ ٱللَّهِ تُرِيدُونَ', 'أئفكا ءالهة دون الله تريدون', NULL, 449, 'local:hafs-text.json'),
  ('hafs-37-87', 'hafs', 37, 87, 'فَمَا ظَنُّكُم بِرَبِّ ٱلْعَٰلَمِينَ', 'فما ظنكم برب العلمين', NULL, 449, 'local:hafs-text.json'),
  ('hafs-37-88', 'hafs', 37, 88, 'فَنَظَرَ نَظْرَةًۭ فِى ٱلنُّجُومِ', 'فنظر نظرة فى النجوم', NULL, 449, 'local:hafs-text.json'),
  ('hafs-37-89', 'hafs', 37, 89, 'فَقَالَ إِنِّى سَقِيمٌۭ', 'فقال إنى سقيم', NULL, 449, 'local:hafs-text.json'),
  ('hafs-37-90', 'hafs', 37, 90, 'فَتَوَلَّوْا۟ عَنْهُ مُدْبِرِينَ', 'فتولوا عنه مدبرين', NULL, 449, 'local:hafs-text.json'),
  ('hafs-37-91', 'hafs', 37, 91, 'فَرَاغَ إِلَىٰٓ ءَالِهَتِهِمْ فَقَالَ أَلَا تَأْكُلُونَ', 'فراغ إلى ءالهتهم فقال ألا تأكلون', NULL, 449, 'local:hafs-text.json'),
  ('hafs-37-92', 'hafs', 37, 92, 'مَا لَكُمْ لَا تَنطِقُونَ', 'ما لكم لا تنطقون', NULL, 449, 'local:hafs-text.json'),
  ('hafs-37-93', 'hafs', 37, 93, 'فَرَاغَ عَلَيْهِمْ ضَرْبًۢا بِٱلْيَمِينِ', 'فراغ عليهم ضربا باليمين', NULL, 449, 'local:hafs-text.json'),
  ('hafs-37-94', 'hafs', 37, 94, 'فَأَقْبَلُوٓا۟ إِلَيْهِ يَزِفُّونَ', 'فأقبلوا إليه يزفون', NULL, 449, 'local:hafs-text.json'),
  ('hafs-37-95', 'hafs', 37, 95, 'قَالَ أَتَعْبُدُونَ مَا تَنْحِتُونَ', 'قال أتعبدون ما تنحتون', NULL, 449, 'local:hafs-text.json'),
  ('hafs-37-96', 'hafs', 37, 96, 'وَٱللَّهُ خَلَقَكُمْ وَمَا تَعْمَلُونَ', 'والله خلقكم وما تعملون', NULL, 449, 'local:hafs-text.json'),
  ('hafs-37-97', 'hafs', 37, 97, 'قَالُوا۟ ٱبْنُوا۟ لَهُۥ بُنْيَٰنًۭا فَأَلْقُوهُ فِى ٱلْجَحِيمِ', 'قالوا ابنوا له بنينا فألقوه فى الجحيم', NULL, 449, 'local:hafs-text.json'),
  ('hafs-37-98', 'hafs', 37, 98, 'فَأَرَادُوا۟ بِهِۦ كَيْدًۭا فَجَعَلْنَٰهُمُ ٱلْأَسْفَلِينَ', 'فأرادوا به كيدا فجعلنهم الأسفلين', NULL, 449, 'local:hafs-text.json'),
  ('hafs-37-99', 'hafs', 37, 99, 'وَقَالَ إِنِّى ذَاهِبٌ إِلَىٰ رَبِّى سَيَهْدِينِ', 'وقال إنى ذاهب إلى ربى سيهدين', NULL, 449, 'local:hafs-text.json'),
  ('hafs-37-100', 'hafs', 37, 100, 'رَبِّ هَبْ لِى مِنَ ٱلصَّٰلِحِينَ', 'رب هب لى من الصلحين', NULL, 449, 'local:hafs-text.json'),
  ('hafs-37-101', 'hafs', 37, 101, 'فَبَشَّرْنَٰهُ بِغُلَٰمٍ حَلِيمٍۢ', 'فبشرنه بغلم حليم', NULL, 449, 'local:hafs-text.json'),
  ('hafs-37-102', 'hafs', 37, 102, 'فَلَمَّا بَلَغَ مَعَهُ ٱلسَّعْىَ قَالَ يَٰبُنَىَّ إِنِّىٓ أَرَىٰ فِى ٱلْمَنَامِ أَنِّىٓ أَذْبَحُكَ فَٱنظُرْ مَاذَا تَرَىٰ ۚ قَالَ يَٰٓأَبَتِ ٱفْعَلْ مَا تُؤْمَرُ ۖ سَتَجِدُنِىٓ إِن شَآءَ ٱللَّهُ مِنَ ٱلصَّٰبِرِينَ', 'فلما بلغ معه السعى قال يبنى إنى أرى فى المنام أنى أذبحك فانظر ماذا ترى  قال يأبت افعل ما تؤمر  ستجدنى إن شاء الله من الصبرين', NULL, 449, 'local:hafs-text.json'),
  ('hafs-37-103', 'hafs', 37, 103, 'فَلَمَّآ أَسْلَمَا وَتَلَّهُۥ لِلْجَبِينِ', 'فلما أسلما وتله للجبين', NULL, 450, 'local:hafs-text.json'),
  ('hafs-37-104', 'hafs', 37, 104, 'وَنَٰدَيْنَٰهُ أَن يَٰٓإِبْرَٰهِيمُ', 'وندينه أن يإبرهيم', NULL, 450, 'local:hafs-text.json'),
  ('hafs-37-105', 'hafs', 37, 105, 'قَدْ صَدَّقْتَ ٱلرُّءْيَآ ۚ إِنَّا كَذَٰلِكَ نَجْزِى ٱلْمُحْسِنِينَ', 'قد صدقت الرءيا  إنا كذلك نجزى المحسنين', NULL, 450, 'local:hafs-text.json'),
  ('hafs-37-106', 'hafs', 37, 106, 'إِنَّ هَٰذَا لَهُوَ ٱلْبَلَٰٓؤُا۟ ٱلْمُبِينُ', 'إن هذا لهو البلؤا المبين', NULL, 450, 'local:hafs-text.json'),
  ('hafs-37-107', 'hafs', 37, 107, 'وَفَدَيْنَٰهُ بِذِبْحٍ عَظِيمٍۢ', 'وفدينه بذبح عظيم', NULL, 450, 'local:hafs-text.json'),
  ('hafs-37-108', 'hafs', 37, 108, 'وَتَرَكْنَا عَلَيْهِ فِى ٱلْءَاخِرِينَ', 'وتركنا عليه فى الءاخرين', NULL, 450, 'local:hafs-text.json'),
  ('hafs-37-109', 'hafs', 37, 109, 'سَلَٰمٌ عَلَىٰٓ إِبْرَٰهِيمَ', 'سلم على إبرهيم', NULL, 450, 'local:hafs-text.json'),
  ('hafs-37-110', 'hafs', 37, 110, 'كَذَٰلِكَ نَجْزِى ٱلْمُحْسِنِينَ', 'كذلك نجزى المحسنين', NULL, 450, 'local:hafs-text.json'),
  ('hafs-37-111', 'hafs', 37, 111, 'إِنَّهُۥ مِنْ عِبَادِنَا ٱلْمُؤْمِنِينَ', 'إنه من عبادنا المؤمنين', NULL, 450, 'local:hafs-text.json'),
  ('hafs-37-112', 'hafs', 37, 112, 'وَبَشَّرْنَٰهُ بِإِسْحَٰقَ نَبِيًّۭا مِّنَ ٱلصَّٰلِحِينَ', 'وبشرنه بإسحق نبيا من الصلحين', NULL, 450, 'local:hafs-text.json'),
  ('hafs-37-113', 'hafs', 37, 113, 'وَبَٰرَكْنَا عَلَيْهِ وَعَلَىٰٓ إِسْحَٰقَ ۚ وَمِن ذُرِّيَّتِهِمَا مُحْسِنٌۭ وَظَالِمٌۭ لِّنَفْسِهِۦ مُبِينٌۭ', 'وبركنا عليه وعلى إسحق  ومن ذريتهما محسن وظالم لنفسه مبين', NULL, 450, 'local:hafs-text.json'),
  ('hafs-37-114', 'hafs', 37, 114, 'وَلَقَدْ مَنَنَّا عَلَىٰ مُوسَىٰ وَهَٰرُونَ', 'ولقد مننا على موسى وهرون', NULL, 450, 'local:hafs-text.json'),
  ('hafs-37-115', 'hafs', 37, 115, 'وَنَجَّيْنَٰهُمَا وَقَوْمَهُمَا مِنَ ٱلْكَرْبِ ٱلْعَظِيمِ', 'ونجينهما وقومهما من الكرب العظيم', NULL, 450, 'local:hafs-text.json'),
  ('hafs-37-116', 'hafs', 37, 116, 'وَنَصَرْنَٰهُمْ فَكَانُوا۟ هُمُ ٱلْغَٰلِبِينَ', 'ونصرنهم فكانوا هم الغلبين', NULL, 450, 'local:hafs-text.json'),
  ('hafs-37-117', 'hafs', 37, 117, 'وَءَاتَيْنَٰهُمَا ٱلْكِتَٰبَ ٱلْمُسْتَبِينَ', 'وءاتينهما الكتب المستبين', NULL, 450, 'local:hafs-text.json'),
  ('hafs-37-118', 'hafs', 37, 118, 'وَهَدَيْنَٰهُمَا ٱلصِّرَٰطَ ٱلْمُسْتَقِيمَ', 'وهدينهما الصرط المستقيم', NULL, 450, 'local:hafs-text.json'),
  ('hafs-37-119', 'hafs', 37, 119, 'وَتَرَكْنَا عَلَيْهِمَا فِى ٱلْءَاخِرِينَ', 'وتركنا عليهما فى الءاخرين', NULL, 450, 'local:hafs-text.json'),
  ('hafs-37-120', 'hafs', 37, 120, 'سَلَٰمٌ عَلَىٰ مُوسَىٰ وَهَٰرُونَ', 'سلم على موسى وهرون', NULL, 450, 'local:hafs-text.json'),
  ('hafs-37-121', 'hafs', 37, 121, 'إِنَّا كَذَٰلِكَ نَجْزِى ٱلْمُحْسِنِينَ', 'إنا كذلك نجزى المحسنين', NULL, 450, 'local:hafs-text.json'),
  ('hafs-37-122', 'hafs', 37, 122, 'إِنَّهُمَا مِنْ عِبَادِنَا ٱلْمُؤْمِنِينَ', 'إنهما من عبادنا المؤمنين', NULL, 450, 'local:hafs-text.json'),
  ('hafs-37-123', 'hafs', 37, 123, 'وَإِنَّ إِلْيَاسَ لَمِنَ ٱلْمُرْسَلِينَ', 'وإن إلياس لمن المرسلين', NULL, 450, 'local:hafs-text.json'),
  ('hafs-37-124', 'hafs', 37, 124, 'إِذْ قَالَ لِقَوْمِهِۦٓ أَلَا تَتَّقُونَ', 'إذ قال لقومه ألا تتقون', NULL, 450, 'local:hafs-text.json'),
  ('hafs-37-125', 'hafs', 37, 125, 'أَتَدْعُونَ بَعْلًۭا وَتَذَرُونَ أَحْسَنَ ٱلْخَٰلِقِينَ', 'أتدعون بعلا وتذرون أحسن الخلقين', NULL, 450, 'local:hafs-text.json'),
  ('hafs-37-126', 'hafs', 37, 126, 'ٱللَّهَ رَبَّكُمْ وَرَبَّ ءَابَآئِكُمُ ٱلْأَوَّلِينَ', 'الله ربكم ورب ءابائكم الأولين', NULL, 450, 'local:hafs-text.json'),
  ('hafs-37-127', 'hafs', 37, 127, 'فَكَذَّبُوهُ فَإِنَّهُمْ لَمُحْضَرُونَ', 'فكذبوه فإنهم لمحضرون', NULL, 451, 'local:hafs-text.json'),
  ('hafs-37-128', 'hafs', 37, 128, 'إِلَّا عِبَادَ ٱللَّهِ ٱلْمُخْلَصِينَ', 'إلا عباد الله المخلصين', NULL, 451, 'local:hafs-text.json'),
  ('hafs-37-129', 'hafs', 37, 129, 'وَتَرَكْنَا عَلَيْهِ فِى ٱلْءَاخِرِينَ', 'وتركنا عليه فى الءاخرين', NULL, 451, 'local:hafs-text.json'),
  ('hafs-37-130', 'hafs', 37, 130, 'سَلَٰمٌ عَلَىٰٓ إِلْ يَاسِينَ', 'سلم على إل ياسين', NULL, 451, 'local:hafs-text.json'),
  ('hafs-37-131', 'hafs', 37, 131, 'إِنَّا كَذَٰلِكَ نَجْزِى ٱلْمُحْسِنِينَ', 'إنا كذلك نجزى المحسنين', NULL, 451, 'local:hafs-text.json'),
  ('hafs-37-132', 'hafs', 37, 132, 'إِنَّهُۥ مِنْ عِبَادِنَا ٱلْمُؤْمِنِينَ', 'إنه من عبادنا المؤمنين', NULL, 451, 'local:hafs-text.json'),
  ('hafs-37-133', 'hafs', 37, 133, 'وَإِنَّ لُوطًۭا لَّمِنَ ٱلْمُرْسَلِينَ', 'وإن لوطا لمن المرسلين', NULL, 451, 'local:hafs-text.json'),
  ('hafs-37-134', 'hafs', 37, 134, 'إِذْ نَجَّيْنَٰهُ وَأَهْلَهُۥٓ أَجْمَعِينَ', 'إذ نجينه وأهله أجمعين', NULL, 451, 'local:hafs-text.json'),
  ('hafs-37-135', 'hafs', 37, 135, 'إِلَّا عَجُوزًۭا فِى ٱلْغَٰبِرِينَ', 'إلا عجوزا فى الغبرين', NULL, 451, 'local:hafs-text.json'),
  ('hafs-37-136', 'hafs', 37, 136, 'ثُمَّ دَمَّرْنَا ٱلْءَاخَرِينَ', 'ثم دمرنا الءاخرين', NULL, 451, 'local:hafs-text.json'),
  ('hafs-37-137', 'hafs', 37, 137, 'وَإِنَّكُمْ لَتَمُرُّونَ عَلَيْهِم مُّصْبِحِينَ', 'وإنكم لتمرون عليهم مصبحين', NULL, 451, 'local:hafs-text.json'),
  ('hafs-37-138', 'hafs', 37, 138, 'وَبِٱلَّيْلِ ۗ أَفَلَا تَعْقِلُونَ', 'وباليل  أفلا تعقلون', NULL, 451, 'local:hafs-text.json'),
  ('hafs-37-139', 'hafs', 37, 139, 'وَإِنَّ يُونُسَ لَمِنَ ٱلْمُرْسَلِينَ', 'وإن يونس لمن المرسلين', NULL, 451, 'local:hafs-text.json'),
  ('hafs-37-140', 'hafs', 37, 140, 'إِذْ أَبَقَ إِلَى ٱلْفُلْكِ ٱلْمَشْحُونِ', 'إذ أبق إلى الفلك المشحون', NULL, 451, 'local:hafs-text.json'),
  ('hafs-37-141', 'hafs', 37, 141, 'فَسَاهَمَ فَكَانَ مِنَ ٱلْمُدْحَضِينَ', 'فساهم فكان من المدحضين', NULL, 451, 'local:hafs-text.json'),
  ('hafs-37-142', 'hafs', 37, 142, 'فَٱلْتَقَمَهُ ٱلْحُوتُ وَهُوَ مُلِيمٌۭ', 'فالتقمه الحوت وهو مليم', NULL, 451, 'local:hafs-text.json'),
  ('hafs-37-143', 'hafs', 37, 143, 'فَلَوْلَآ أَنَّهُۥ كَانَ مِنَ ٱلْمُسَبِّحِينَ', 'فلولا أنه كان من المسبحين', NULL, 451, 'local:hafs-text.json'),
  ('hafs-37-144', 'hafs', 37, 144, 'لَلَبِثَ فِى بَطْنِهِۦٓ إِلَىٰ يَوْمِ يُبْعَثُونَ', 'للبث فى بطنه إلى يوم يبعثون', NULL, 451, 'local:hafs-text.json'),
  ('hafs-37-145', 'hafs', 37, 145, '۞ فَنَبَذْنَٰهُ بِٱلْعَرَآءِ وَهُوَ سَقِيمٌۭ', 'فنبذنه بالعراء وهو سقيم', NULL, 451, 'local:hafs-text.json'),
  ('hafs-37-146', 'hafs', 37, 146, 'وَأَنۢبَتْنَا عَلَيْهِ شَجَرَةًۭ مِّن يَقْطِينٍۢ', 'وأنبتنا عليه شجرة من يقطين', NULL, 451, 'local:hafs-text.json'),
  ('hafs-37-147', 'hafs', 37, 147, 'وَأَرْسَلْنَٰهُ إِلَىٰ مِا۟ئَةِ أَلْفٍ أَوْ يَزِيدُونَ', 'وأرسلنه إلى مائة ألف أو يزيدون', NULL, 451, 'local:hafs-text.json'),
  ('hafs-37-148', 'hafs', 37, 148, 'فَـَٔامَنُوا۟ فَمَتَّعْنَٰهُمْ إِلَىٰ حِينٍۢ', 'فامنوا فمتعنهم إلى حين', NULL, 451, 'local:hafs-text.json'),
  ('hafs-37-149', 'hafs', 37, 149, 'فَٱسْتَفْتِهِمْ أَلِرَبِّكَ ٱلْبَنَاتُ وَلَهُمُ ٱلْبَنُونَ', 'فاستفتهم ألربك البنات ولهم البنون', NULL, 451, 'local:hafs-text.json'),
  ('hafs-37-150', 'hafs', 37, 150, 'أَمْ خَلَقْنَا ٱلْمَلَٰٓئِكَةَ إِنَٰثًۭا وَهُمْ شَٰهِدُونَ', 'أم خلقنا الملئكة إنثا وهم شهدون', NULL, 451, 'local:hafs-text.json'),
  ('hafs-37-151', 'hafs', 37, 151, 'أَلَآ إِنَّهُم مِّنْ إِفْكِهِمْ لَيَقُولُونَ', 'ألا إنهم من إفكهم ليقولون', NULL, 451, 'local:hafs-text.json'),
  ('hafs-37-152', 'hafs', 37, 152, 'وَلَدَ ٱللَّهُ وَإِنَّهُمْ لَكَٰذِبُونَ', 'ولد الله وإنهم لكذبون', NULL, 451, 'local:hafs-text.json'),
  ('hafs-37-153', 'hafs', 37, 153, 'أَصْطَفَى ٱلْبَنَاتِ عَلَى ٱلْبَنِينَ', 'أصطفى البنات على البنين', NULL, 451, 'local:hafs-text.json'),
  ('hafs-37-154', 'hafs', 37, 154, 'مَا لَكُمْ كَيْفَ تَحْكُمُونَ', 'ما لكم كيف تحكمون', NULL, 452, 'local:hafs-text.json'),
