  ('hafs-37-156', 'hafs', 37, 156, 'أَمْ لَكُمْ سُلْطَٰنٌۭ مُّبِينٌۭ', 'أم لكم سلطن مبين', NULL, 452, 'local:hafs-text.json'),
  ('hafs-37-157', 'hafs', 37, 157, 'فَأْتُوا۟ بِكِتَٰبِكُمْ إِن كُنتُمْ صَٰدِقِينَ', 'فأتوا بكتبكم إن كنتم صدقين', NULL, 452, 'local:hafs-text.json'),
  ('hafs-37-158', 'hafs', 37, 158, 'وَجَعَلُوا۟ بَيْنَهُۥ وَبَيْنَ ٱلْجِنَّةِ نَسَبًۭا ۚ وَلَقَدْ عَلِمَتِ ٱلْجِنَّةُ إِنَّهُمْ لَمُحْضَرُونَ', 'وجعلوا بينه وبين الجنة نسبا  ولقد علمت الجنة إنهم لمحضرون', NULL, 452, 'local:hafs-text.json'),
  ('hafs-37-159', 'hafs', 37, 159, 'سُبْحَٰنَ ٱللَّهِ عَمَّا يَصِفُونَ', 'سبحن الله عما يصفون', NULL, 452, 'local:hafs-text.json'),
  ('hafs-37-160', 'hafs', 37, 160, 'إِلَّا عِبَادَ ٱللَّهِ ٱلْمُخْلَصِينَ', 'إلا عباد الله المخلصين', NULL, 452, 'local:hafs-text.json'),
  ('hafs-37-161', 'hafs', 37, 161, 'فَإِنَّكُمْ وَمَا تَعْبُدُونَ', 'فإنكم وما تعبدون', NULL, 452, 'local:hafs-text.json'),
  ('hafs-37-162', 'hafs', 37, 162, 'مَآ أَنتُمْ عَلَيْهِ بِفَٰتِنِينَ', 'ما أنتم عليه بفتنين', NULL, 452, 'local:hafs-text.json'),
  ('hafs-37-163', 'hafs', 37, 163, 'إِلَّا مَنْ هُوَ صَالِ ٱلْجَحِيمِ', 'إلا من هو صال الجحيم', NULL, 452, 'local:hafs-text.json'),
  ('hafs-37-164', 'hafs', 37, 164, 'وَمَا مِنَّآ إِلَّا لَهُۥ مَقَامٌۭ مَّعْلُومٌۭ', 'وما منا إلا له مقام معلوم', NULL, 452, 'local:hafs-text.json'),
  ('hafs-37-165', 'hafs', 37, 165, 'وَإِنَّا لَنَحْنُ ٱلصَّآفُّونَ', 'وإنا لنحن الصافون', NULL, 452, 'local:hafs-text.json'),
  ('hafs-37-166', 'hafs', 37, 166, 'وَإِنَّا لَنَحْنُ ٱلْمُسَبِّحُونَ', 'وإنا لنحن المسبحون', NULL, 452, 'local:hafs-text.json'),
  ('hafs-37-167', 'hafs', 37, 167, 'وَإِن كَانُوا۟ لَيَقُولُونَ', 'وإن كانوا ليقولون', NULL, 452, 'local:hafs-text.json'),
  ('hafs-37-168', 'hafs', 37, 168, 'لَوْ أَنَّ عِندَنَا ذِكْرًۭا مِّنَ ٱلْأَوَّلِينَ', 'لو أن عندنا ذكرا من الأولين', NULL, 452, 'local:hafs-text.json'),
  ('hafs-37-169', 'hafs', 37, 169, 'لَكُنَّا عِبَادَ ٱللَّهِ ٱلْمُخْلَصِينَ', 'لكنا عباد الله المخلصين', NULL, 452, 'local:hafs-text.json'),
  ('hafs-37-170', 'hafs', 37, 170, 'فَكَفَرُوا۟ بِهِۦ ۖ فَسَوْفَ يَعْلَمُونَ', 'فكفروا به  فسوف يعلمون', NULL, 452, 'local:hafs-text.json'),
  ('hafs-37-171', 'hafs', 37, 171, 'وَلَقَدْ سَبَقَتْ كَلِمَتُنَا لِعِبَادِنَا ٱلْمُرْسَلِينَ', 'ولقد سبقت كلمتنا لعبادنا المرسلين', NULL, 452, 'local:hafs-text.json'),
  ('hafs-37-172', 'hafs', 37, 172, 'إِنَّهُمْ لَهُمُ ٱلْمَنصُورُونَ', 'إنهم لهم المنصورون', NULL, 452, 'local:hafs-text.json'),
  ('hafs-37-173', 'hafs', 37, 173, 'وَإِنَّ جُندَنَا لَهُمُ ٱلْغَٰلِبُونَ', 'وإن جندنا لهم الغلبون', NULL, 452, 'local:hafs-text.json'),
  ('hafs-37-174', 'hafs', 37, 174, 'فَتَوَلَّ عَنْهُمْ حَتَّىٰ حِينٍۢ', 'فتول عنهم حتى حين', NULL, 452, 'local:hafs-text.json'),
  ('hafs-37-175', 'hafs', 37, 175, 'وَأَبْصِرْهُمْ فَسَوْفَ يُبْصِرُونَ', 'وأبصرهم فسوف يبصرون', NULL, 452, 'local:hafs-text.json'),
  ('hafs-37-176', 'hafs', 37, 176, 'أَفَبِعَذَابِنَا يَسْتَعْجِلُونَ', 'أفبعذابنا يستعجلون', NULL, 452, 'local:hafs-text.json'),
  ('hafs-37-177', 'hafs', 37, 177, 'فَإِذَا نَزَلَ بِسَاحَتِهِمْ فَسَآءَ صَبَاحُ ٱلْمُنذَرِينَ', 'فإذا نزل بساحتهم فساء صباح المنذرين', NULL, 452, 'local:hafs-text.json'),
  ('hafs-37-178', 'hafs', 37, 178, 'وَتَوَلَّ عَنْهُمْ حَتَّىٰ حِينٍۢ', 'وتول عنهم حتى حين', NULL, 452, 'local:hafs-text.json'),
  ('hafs-37-179', 'hafs', 37, 179, 'وَأَبْصِرْ فَسَوْفَ يُبْصِرُونَ', 'وأبصر فسوف يبصرون', NULL, 452, 'local:hafs-text.json'),
  ('hafs-37-180', 'hafs', 37, 180, 'سُبْحَٰنَ رَبِّكَ رَبِّ ٱلْعِزَّةِ عَمَّا يَصِفُونَ', 'سبحن ربك رب العزة عما يصفون', NULL, 452, 'local:hafs-text.json'),
  ('hafs-37-181', 'hafs', 37, 181, 'وَسَلَٰمٌ عَلَى ٱلْمُرْسَلِينَ', 'وسلم على المرسلين', NULL, 452, 'local:hafs-text.json'),
  ('hafs-37-182', 'hafs', 37, 182, 'وَٱلْحَمْدُ لِلَّهِ رَبِّ ٱلْعَٰلَمِينَ', 'والحمد لله رب العلمين', NULL, 452, 'local:hafs-text.json'),
  ('hafs-38-1', 'hafs', 38, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ صٓ ۚ وَٱلْقُرْءَانِ ذِى ٱلذِّكْرِ', 'بسم الله الرحمن الرحيم ص  والقرءان ذى الذكر', NULL, 453, 'local:hafs-text.json'),
  ('hafs-38-2', 'hafs', 38, 2, 'بَلِ ٱلَّذِينَ كَفَرُوا۟ فِى عِزَّةٍۢ وَشِقَاقٍۢ', 'بل الذين كفروا فى عزة وشقاق', NULL, 453, 'local:hafs-text.json'),
  ('hafs-38-3', 'hafs', 38, 3, 'كَمْ أَهْلَكْنَا مِن قَبْلِهِم مِّن قَرْنٍۢ فَنَادَوا۟ وَّلَاتَ حِينَ مَنَاصٍۢ', 'كم أهلكنا من قبلهم من قرن فنادوا ولات حين مناص', NULL, 453, 'local:hafs-text.json'),
  ('hafs-38-4', 'hafs', 38, 4, 'وَعَجِبُوٓا۟ أَن جَآءَهُم مُّنذِرٌۭ مِّنْهُمْ ۖ وَقَالَ ٱلْكَٰفِرُونَ هَٰذَا سَٰحِرٌۭ كَذَّابٌ', 'وعجبوا أن جاءهم منذر منهم  وقال الكفرون هذا سحر كذاب', NULL, 453, 'local:hafs-text.json'),
  ('hafs-38-5', 'hafs', 38, 5, 'أَجَعَلَ ٱلْءَالِهَةَ إِلَٰهًۭا وَٰحِدًا ۖ إِنَّ هَٰذَا لَشَىْءٌ عُجَابٌۭ', 'أجعل الءالهة إلها وحدا  إن هذا لشىء عجاب', NULL, 453, 'local:hafs-text.json'),
  ('hafs-38-6', 'hafs', 38, 6, 'وَٱنطَلَقَ ٱلْمَلَأُ مِنْهُمْ أَنِ ٱمْشُوا۟ وَٱصْبِرُوا۟ عَلَىٰٓ ءَالِهَتِكُمْ ۖ إِنَّ هَٰذَا لَشَىْءٌۭ يُرَادُ', 'وانطلق الملأ منهم أن امشوا واصبروا على ءالهتكم  إن هذا لشىء يراد', NULL, 453, 'local:hafs-text.json'),
  ('hafs-38-7', 'hafs', 38, 7, 'مَا سَمِعْنَا بِهَٰذَا فِى ٱلْمِلَّةِ ٱلْءَاخِرَةِ إِنْ هَٰذَآ إِلَّا ٱخْتِلَٰقٌ', 'ما سمعنا بهذا فى الملة الءاخرة إن هذا إلا اختلق', NULL, 453, 'local:hafs-text.json'),
  ('hafs-38-8', 'hafs', 38, 8, 'أَءُنزِلَ عَلَيْهِ ٱلذِّكْرُ مِنۢ بَيْنِنَا ۚ بَلْ هُمْ فِى شَكٍّۢ مِّن ذِكْرِى ۖ بَل لَّمَّا يَذُوقُوا۟ عَذَابِ', 'أءنزل عليه الذكر من بيننا  بل هم فى شك من ذكرى  بل لما يذوقوا عذاب', NULL, 453, 'local:hafs-text.json'),
  ('hafs-38-9', 'hafs', 38, 9, 'أَمْ عِندَهُمْ خَزَآئِنُ رَحْمَةِ رَبِّكَ ٱلْعَزِيزِ ٱلْوَهَّابِ', 'أم عندهم خزائن رحمة ربك العزيز الوهاب', NULL, 453, 'local:hafs-text.json'),
  ('hafs-38-10', 'hafs', 38, 10, 'أَمْ لَهُم مُّلْكُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَمَا بَيْنَهُمَا ۖ فَلْيَرْتَقُوا۟ فِى ٱلْأَسْبَٰبِ', 'أم لهم ملك السموت والأرض وما بينهما  فليرتقوا فى الأسبب', NULL, 453, 'local:hafs-text.json'),
  ('hafs-38-11', 'hafs', 38, 11, 'جُندٌۭ مَّا هُنَالِكَ مَهْزُومٌۭ مِّنَ ٱلْأَحْزَابِ', 'جند ما هنالك مهزوم من الأحزاب', NULL, 453, 'local:hafs-text.json'),
  ('hafs-38-12', 'hafs', 38, 12, 'كَذَّبَتْ قَبْلَهُمْ قَوْمُ نُوحٍۢ وَعَادٌۭ وَفِرْعَوْنُ ذُو ٱلْأَوْتَادِ', 'كذبت قبلهم قوم نوح وعاد وفرعون ذو الأوتاد', NULL, 453, 'local:hafs-text.json'),
  ('hafs-38-13', 'hafs', 38, 13, 'وَثَمُودُ وَقَوْمُ لُوطٍۢ وَأَصْحَٰبُ لْـَٔيْكَةِ ۚ أُو۟لَٰٓئِكَ ٱلْأَحْزَابُ', 'وثمود وقوم لوط وأصحب ليكة  أولئك الأحزاب', NULL, 453, 'local:hafs-text.json'),
  ('hafs-38-14', 'hafs', 38, 14, 'إِن كُلٌّ إِلَّا كَذَّبَ ٱلرُّسُلَ فَحَقَّ عِقَابِ', 'إن كل إلا كذب الرسل فحق عقاب', NULL, 453, 'local:hafs-text.json'),
  ('hafs-38-15', 'hafs', 38, 15, 'وَمَا يَنظُرُ هَٰٓؤُلَآءِ إِلَّا صَيْحَةًۭ وَٰحِدَةًۭ مَّا لَهَا مِن فَوَاقٍۢ', 'وما ينظر هؤلاء إلا صيحة وحدة ما لها من فواق', NULL, 453, 'local:hafs-text.json'),
  ('hafs-38-16', 'hafs', 38, 16, 'وَقَالُوا۟ رَبَّنَا عَجِّل لَّنَا قِطَّنَا قَبْلَ يَوْمِ ٱلْحِسَابِ', 'وقالوا ربنا عجل لنا قطنا قبل يوم الحساب', NULL, 453, 'local:hafs-text.json'),
  ('hafs-38-17', 'hafs', 38, 17, 'ٱصْبِرْ عَلَىٰ مَا يَقُولُونَ وَٱذْكُرْ عَبْدَنَا دَاوُۥدَ ذَا ٱلْأَيْدِ ۖ إِنَّهُۥٓ أَوَّابٌ', 'اصبر على ما يقولون واذكر عبدنا داود ذا الأيد  إنه أواب', NULL, 454, 'local:hafs-text.json'),
  ('hafs-38-18', 'hafs', 38, 18, 'إِنَّا سَخَّرْنَا ٱلْجِبَالَ مَعَهُۥ يُسَبِّحْنَ بِٱلْعَشِىِّ وَٱلْإِشْرَاقِ', 'إنا سخرنا الجبال معه يسبحن بالعشى والإشراق', NULL, 454, 'local:hafs-text.json'),
  ('hafs-38-19', 'hafs', 38, 19, 'وَٱلطَّيْرَ مَحْشُورَةًۭ ۖ كُلٌّۭ لَّهُۥٓ أَوَّابٌۭ', 'والطير محشورة  كل له أواب', NULL, 454, 'local:hafs-text.json'),
  ('hafs-38-20', 'hafs', 38, 20, 'وَشَدَدْنَا مُلْكَهُۥ وَءَاتَيْنَٰهُ ٱلْحِكْمَةَ وَفَصْلَ ٱلْخِطَابِ', 'وشددنا ملكه وءاتينه الحكمة وفصل الخطاب', NULL, 454, 'local:hafs-text.json'),
  ('hafs-38-21', 'hafs', 38, 21, '۞ وَهَلْ أَتَىٰكَ نَبَؤُا۟ ٱلْخَصْمِ إِذْ تَسَوَّرُوا۟ ٱلْمِحْرَابَ', 'وهل أتىك نبؤا الخصم إذ تسوروا المحراب', NULL, 454, 'local:hafs-text.json'),
  ('hafs-38-22', 'hafs', 38, 22, 'إِذْ دَخَلُوا۟ عَلَىٰ دَاوُۥدَ فَفَزِعَ مِنْهُمْ ۖ قَالُوا۟ لَا تَخَفْ ۖ خَصْمَانِ بَغَىٰ بَعْضُنَا عَلَىٰ بَعْضٍۢ فَٱحْكُم بَيْنَنَا بِٱلْحَقِّ وَلَا تُشْطِطْ وَٱهْدِنَآ إِلَىٰ سَوَآءِ ٱلصِّرَٰطِ', 'إذ دخلوا على داود ففزع منهم  قالوا لا تخف  خصمان بغى بعضنا على بعض فاحكم بيننا بالحق ولا تشطط واهدنا إلى سواء الصرط', NULL, 454, 'local:hafs-text.json'),
  ('hafs-38-23', 'hafs', 38, 23, 'إِنَّ هَٰذَآ أَخِى لَهُۥ تِسْعٌۭ وَتِسْعُونَ نَعْجَةًۭ وَلِىَ نَعْجَةٌۭ وَٰحِدَةٌۭ فَقَالَ أَكْفِلْنِيهَا وَعَزَّنِى فِى ٱلْخِطَابِ', 'إن هذا أخى له تسع وتسعون نعجة ولى نعجة وحدة فقال أكفلنيها وعزنى فى الخطاب', NULL, 454, 'local:hafs-text.json'),
  ('hafs-38-24', 'hafs', 38, 24, 'قَالَ لَقَدْ ظَلَمَكَ بِسُؤَالِ نَعْجَتِكَ إِلَىٰ نِعَاجِهِۦ ۖ وَإِنَّ كَثِيرًۭا مِّنَ ٱلْخُلَطَآءِ لَيَبْغِى بَعْضُهُمْ عَلَىٰ بَعْضٍ إِلَّا ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ وَقَلِيلٌۭ مَّا هُمْ ۗ وَظَنَّ دَاوُۥدُ أَنَّمَا فَتَنَّٰهُ فَٱسْتَغْفَرَ رَبَّهُۥ وَخَرَّ رَاكِعًۭا وَأَنَابَ ۩', 'قال لقد ظلمك بسؤال نعجتك إلى نعاجه  وإن كثيرا من الخلطاء ليبغى بعضهم على بعض إلا الذين ءامنوا وعملوا الصلحت وقليل ما هم  وظن داود أنما فتنه فاستغفر ربه وخر راكعا وأناب', NULL, 454, 'local:hafs-text.json'),
  ('hafs-38-25', 'hafs', 38, 25, 'فَغَفَرْنَا لَهُۥ ذَٰلِكَ ۖ وَإِنَّ لَهُۥ عِندَنَا لَزُلْفَىٰ وَحُسْنَ مَـَٔابٍۢ', 'فغفرنا له ذلك  وإن له عندنا لزلفى وحسن ماب', NULL, 454, 'local:hafs-text.json'),
  ('hafs-38-26', 'hafs', 38, 26, 'يَٰدَاوُۥدُ إِنَّا جَعَلْنَٰكَ خَلِيفَةًۭ فِى ٱلْأَرْضِ فَٱحْكُم بَيْنَ ٱلنَّاسِ بِٱلْحَقِّ وَلَا تَتَّبِعِ ٱلْهَوَىٰ فَيُضِلَّكَ عَن سَبِيلِ ٱللَّهِ ۚ إِنَّ ٱلَّذِينَ يَضِلُّونَ عَن سَبِيلِ ٱللَّهِ لَهُمْ عَذَابٌۭ شَدِيدٌۢ بِمَا نَسُوا۟ يَوْمَ ٱلْحِسَابِ', 'يداود إنا جعلنك خليفة فى الأرض فاحكم بين الناس بالحق ولا تتبع الهوى فيضلك عن سبيل الله  إن الذين يضلون عن سبيل الله لهم عذاب شديد بما نسوا يوم الحساب', NULL, 454, 'local:hafs-text.json'),
  ('hafs-38-27', 'hafs', 38, 27, 'وَمَا خَلَقْنَا ٱلسَّمَآءَ وَٱلْأَرْضَ وَمَا بَيْنَهُمَا بَٰطِلًۭا ۚ ذَٰلِكَ ظَنُّ ٱلَّذِينَ كَفَرُوا۟ ۚ فَوَيْلٌۭ لِّلَّذِينَ كَفَرُوا۟ مِنَ ٱلنَّارِ', 'وما خلقنا السماء والأرض وما بينهما بطلا  ذلك ظن الذين كفروا  فويل للذين كفروا من النار', NULL, 455, 'local:hafs-text.json'),
  ('hafs-38-28', 'hafs', 38, 28, 'أَمْ نَجْعَلُ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ كَٱلْمُفْسِدِينَ فِى ٱلْأَرْضِ أَمْ نَجْعَلُ ٱلْمُتَّقِينَ كَٱلْفُجَّارِ', 'أم نجعل الذين ءامنوا وعملوا الصلحت كالمفسدين فى الأرض أم نجعل المتقين كالفجار', NULL, 455, 'local:hafs-text.json'),
  ('hafs-38-29', 'hafs', 38, 29, 'كِتَٰبٌ أَنزَلْنَٰهُ إِلَيْكَ مُبَٰرَكٌۭ لِّيَدَّبَّرُوٓا۟ ءَايَٰتِهِۦ وَلِيَتَذَكَّرَ أُو۟لُوا۟ ٱلْأَلْبَٰبِ', 'كتب أنزلنه إليك مبرك ليدبروا ءايته وليتذكر أولوا الألبب', NULL, 455, 'local:hafs-text.json'),
  ('hafs-38-30', 'hafs', 38, 30, 'وَوَهَبْنَا لِدَاوُۥدَ سُلَيْمَٰنَ ۚ نِعْمَ ٱلْعَبْدُ ۖ إِنَّهُۥٓ أَوَّابٌ', 'ووهبنا لداود سليمن  نعم العبد  إنه أواب', NULL, 455, 'local:hafs-text.json')
insert into public.ayahs (id, riwayah, surah_number, ayah_number, text, simple_text, juz, page, source) values
  ('hafs-38-31', 'hafs', 38, 31, 'إِذْ عُرِضَ عَلَيْهِ بِٱلْعَشِىِّ ٱلصَّٰفِنَٰتُ ٱلْجِيَادُ', 'إذ عرض عليه بالعشى الصفنت الجياد', NULL, 455, 'local:hafs-text.json'),
  ('hafs-38-32', 'hafs', 38, 32, 'فَقَالَ إِنِّىٓ أَحْبَبْتُ حُبَّ ٱلْخَيْرِ عَن ذِكْرِ رَبِّى حَتَّىٰ تَوَارَتْ بِٱلْحِجَابِ', 'فقال إنى أحببت حب الخير عن ذكر ربى حتى توارت بالحجاب', NULL, 455, 'local:hafs-text.json'),
  ('hafs-38-33', 'hafs', 38, 33, 'رُدُّوهَا عَلَىَّ ۖ فَطَفِقَ مَسْحًۢا بِٱلسُّوقِ وَٱلْأَعْنَاقِ', 'ردوها على  فطفق مسحا بالسوق والأعناق', NULL, 455, 'local:hafs-text.json'),
  ('hafs-38-34', 'hafs', 38, 34, 'وَلَقَدْ فَتَنَّا سُلَيْمَٰنَ وَأَلْقَيْنَا عَلَىٰ كُرْسِيِّهِۦ جَسَدًۭا ثُمَّ أَنَابَ', 'ولقد فتنا سليمن وألقينا على كرسيه جسدا ثم أناب', NULL, 455, 'local:hafs-text.json'),
  ('hafs-38-35', 'hafs', 38, 35, 'قَالَ رَبِّ ٱغْفِرْ لِى وَهَبْ لِى مُلْكًۭا لَّا يَنۢبَغِى لِأَحَدٍۢ مِّنۢ بَعْدِىٓ ۖ إِنَّكَ أَنتَ ٱلْوَهَّابُ', 'قال رب اغفر لى وهب لى ملكا لا ينبغى لأحد من بعدى  إنك أنت الوهاب', NULL, 455, 'local:hafs-text.json'),
  ('hafs-38-36', 'hafs', 38, 36, 'فَسَخَّرْنَا لَهُ ٱلرِّيحَ تَجْرِى بِأَمْرِهِۦ رُخَآءً حَيْثُ أَصَابَ', 'فسخرنا له الريح تجرى بأمره رخاء حيث أصاب', NULL, 455, 'local:hafs-text.json'),
  ('hafs-38-37', 'hafs', 38, 37, 'وَٱلشَّيَٰطِينَ كُلَّ بَنَّآءٍۢ وَغَوَّاصٍۢ', 'والشيطين كل بناء وغواص', NULL, 455, 'local:hafs-text.json'),
  ('hafs-38-38', 'hafs', 38, 38, 'وَءَاخَرِينَ مُقَرَّنِينَ فِى ٱلْأَصْفَادِ', 'وءاخرين مقرنين فى الأصفاد', NULL, 455, 'local:hafs-text.json'),
  ('hafs-38-39', 'hafs', 38, 39, 'هَٰذَا عَطَآؤُنَا فَٱمْنُنْ أَوْ أَمْسِكْ بِغَيْرِ حِسَابٍۢ', 'هذا عطاؤنا فامنن أو أمسك بغير حساب', NULL, 455, 'local:hafs-text.json'),
  ('hafs-38-40', 'hafs', 38, 40, 'وَإِنَّ لَهُۥ عِندَنَا لَزُلْفَىٰ وَحُسْنَ مَـَٔابٍۢ', 'وإن له عندنا لزلفى وحسن ماب', NULL, 455, 'local:hafs-text.json'),
  ('hafs-38-41', 'hafs', 38, 41, 'وَٱذْكُرْ عَبْدَنَآ أَيُّوبَ إِذْ نَادَىٰ رَبَّهُۥٓ أَنِّى مَسَّنِىَ ٱلشَّيْطَٰنُ بِنُصْبٍۢ وَعَذَابٍ', 'واذكر عبدنا أيوب إذ نادى ربه أنى مسنى الشيطن بنصب وعذاب', NULL, 455, 'local:hafs-text.json'),
  ('hafs-38-42', 'hafs', 38, 42, 'ٱرْكُضْ بِرِجْلِكَ ۖ هَٰذَا مُغْتَسَلٌۢ بَارِدٌۭ وَشَرَابٌۭ', 'اركض برجلك  هذا مغتسل بارد وشراب', NULL, 455, 'local:hafs-text.json'),
  ('hafs-38-43', 'hafs', 38, 43, 'وَوَهَبْنَا لَهُۥٓ أَهْلَهُۥ وَمِثْلَهُم مَّعَهُمْ رَحْمَةًۭ مِّنَّا وَذِكْرَىٰ لِأُو۟لِى ٱلْأَلْبَٰبِ', 'ووهبنا له أهله ومثلهم معهم رحمة منا وذكرى لأولى الألبب', NULL, 456, 'local:hafs-text.json'),
  ('hafs-38-44', 'hafs', 38, 44, 'وَخُذْ بِيَدِكَ ضِغْثًۭا فَٱضْرِب بِّهِۦ وَلَا تَحْنَثْ ۗ إِنَّا وَجَدْنَٰهُ صَابِرًۭا ۚ نِّعْمَ ٱلْعَبْدُ ۖ إِنَّهُۥٓ أَوَّابٌۭ', 'وخذ بيدك ضغثا فاضرب به ولا تحنث  إنا وجدنه صابرا  نعم العبد  إنه أواب', NULL, 456, 'local:hafs-text.json'),
  ('hafs-38-45', 'hafs', 38, 45, 'وَٱذْكُرْ عِبَٰدَنَآ إِبْرَٰهِيمَ وَإِسْحَٰقَ وَيَعْقُوبَ أُو۟لِى ٱلْأَيْدِى وَٱلْأَبْصَٰرِ', 'واذكر عبدنا إبرهيم وإسحق ويعقوب أولى الأيدى والأبصر', NULL, 456, 'local:hafs-text.json'),
  ('hafs-38-46', 'hafs', 38, 46, 'إِنَّآ أَخْلَصْنَٰهُم بِخَالِصَةٍۢ ذِكْرَى ٱلدَّارِ', 'إنا أخلصنهم بخالصة ذكرى الدار', NULL, 456, 'local:hafs-text.json'),
  ('hafs-38-47', 'hafs', 38, 47, 'وَإِنَّهُمْ عِندَنَا لَمِنَ ٱلْمُصْطَفَيْنَ ٱلْأَخْيَارِ', 'وإنهم عندنا لمن المصطفين الأخيار', NULL, 456, 'local:hafs-text.json'),
  ('hafs-38-48', 'hafs', 38, 48, 'وَٱذْكُرْ إِسْمَٰعِيلَ وَٱلْيَسَعَ وَذَا ٱلْكِفْلِ ۖ وَكُلٌّۭ مِّنَ ٱلْأَخْيَارِ', 'واذكر إسمعيل واليسع وذا الكفل  وكل من الأخيار', NULL, 456, 'local:hafs-text.json'),
  ('hafs-38-49', 'hafs', 38, 49, 'هَٰذَا ذِكْرٌۭ ۚ وَإِنَّ لِلْمُتَّقِينَ لَحُسْنَ مَـَٔابٍۢ', 'هذا ذكر  وإن للمتقين لحسن ماب', NULL, 456, 'local:hafs-text.json'),
  ('hafs-38-50', 'hafs', 38, 50, 'جَنَّٰتِ عَدْنٍۢ مُّفَتَّحَةًۭ لَّهُمُ ٱلْأَبْوَٰبُ', 'جنت عدن مفتحة لهم الأبوب', NULL, 456, 'local:hafs-text.json'),
  ('hafs-38-51', 'hafs', 38, 51, 'مُتَّكِـِٔينَ فِيهَا يَدْعُونَ فِيهَا بِفَٰكِهَةٍۢ كَثِيرَةٍۢ وَشَرَابٍۢ', 'متكين فيها يدعون فيها بفكهة كثيرة وشراب', NULL, 456, 'local:hafs-text.json'),
  ('hafs-38-52', 'hafs', 38, 52, '۞ وَعِندَهُمْ قَٰصِرَٰتُ ٱلطَّرْفِ أَتْرَابٌ', 'وعندهم قصرت الطرف أتراب', NULL, 456, 'local:hafs-text.json'),
  ('hafs-38-53', 'hafs', 38, 53, 'هَٰذَا مَا تُوعَدُونَ لِيَوْمِ ٱلْحِسَابِ', 'هذا ما توعدون ليوم الحساب', NULL, 456, 'local:hafs-text.json'),
  ('hafs-38-54', 'hafs', 38, 54, 'إِنَّ هَٰذَا لَرِزْقُنَا مَا لَهُۥ مِن نَّفَادٍ', 'إن هذا لرزقنا ما له من نفاد', NULL, 456, 'local:hafs-text.json'),
  ('hafs-38-55', 'hafs', 38, 55, 'هَٰذَا ۚ وَإِنَّ لِلطَّٰغِينَ لَشَرَّ مَـَٔابٍۢ', 'هذا  وإن للطغين لشر ماب', NULL, 456, 'local:hafs-text.json'),
  ('hafs-38-56', 'hafs', 38, 56, 'جَهَنَّمَ يَصْلَوْنَهَا فَبِئْسَ ٱلْمِهَادُ', 'جهنم يصلونها فبئس المهاد', NULL, 456, 'local:hafs-text.json'),
  ('hafs-38-57', 'hafs', 38, 57, 'هَٰذَا فَلْيَذُوقُوهُ حَمِيمٌۭ وَغَسَّاقٌۭ', 'هذا فليذوقوه حميم وغساق', NULL, 456, 'local:hafs-text.json'),
  ('hafs-38-58', 'hafs', 38, 58, 'وَءَاخَرُ مِن شَكْلِهِۦٓ أَزْوَٰجٌ', 'وءاخر من شكله أزوج', NULL, 456, 'local:hafs-text.json'),
  ('hafs-38-59', 'hafs', 38, 59, 'هَٰذَا فَوْجٌۭ مُّقْتَحِمٌۭ مَّعَكُمْ ۖ لَا مَرْحَبًۢا بِهِمْ ۚ إِنَّهُمْ صَالُوا۟ ٱلنَّارِ', 'هذا فوج مقتحم معكم  لا مرحبا بهم  إنهم صالوا النار', NULL, 456, 'local:hafs-text.json'),
  ('hafs-38-60', 'hafs', 38, 60, 'قَالُوا۟ بَلْ أَنتُمْ لَا مَرْحَبًۢا بِكُمْ ۖ أَنتُمْ قَدَّمْتُمُوهُ لَنَا ۖ فَبِئْسَ ٱلْقَرَارُ', 'قالوا بل أنتم لا مرحبا بكم  أنتم قدمتموه لنا  فبئس القرار', NULL, 456, 'local:hafs-text.json'),
  ('hafs-38-61', 'hafs', 38, 61, 'قَالُوا۟ رَبَّنَا مَن قَدَّمَ لَنَا هَٰذَا فَزِدْهُ عَذَابًۭا ضِعْفًۭا فِى ٱلنَّارِ', 'قالوا ربنا من قدم لنا هذا فزده عذابا ضعفا فى النار', NULL, 456, 'local:hafs-text.json'),
  ('hafs-38-62', 'hafs', 38, 62, 'وَقَالُوا۟ مَا لَنَا لَا نَرَىٰ رِجَالًۭا كُنَّا نَعُدُّهُم مِّنَ ٱلْأَشْرَارِ', 'وقالوا ما لنا لا نرى رجالا كنا نعدهم من الأشرار', NULL, 457, 'local:hafs-text.json'),
  ('hafs-38-63', 'hafs', 38, 63, 'أَتَّخَذْنَٰهُمْ سِخْرِيًّا أَمْ زَاغَتْ عَنْهُمُ ٱلْأَبْصَٰرُ', 'أتخذنهم سخريا أم زاغت عنهم الأبصر', NULL, 457, 'local:hafs-text.json'),
  ('hafs-38-64', 'hafs', 38, 64, 'إِنَّ ذَٰلِكَ لَحَقٌّۭ تَخَاصُمُ أَهْلِ ٱلنَّارِ', 'إن ذلك لحق تخاصم أهل النار', NULL, 457, 'local:hafs-text.json'),
  ('hafs-38-65', 'hafs', 38, 65, 'قُلْ إِنَّمَآ أَنَا۠ مُنذِرٌۭ ۖ وَمَا مِنْ إِلَٰهٍ إِلَّا ٱللَّهُ ٱلْوَٰحِدُ ٱلْقَهَّارُ', 'قل إنما أنا منذر  وما من إله إلا الله الوحد القهار', NULL, 457, 'local:hafs-text.json'),
  ('hafs-38-66', 'hafs', 38, 66, 'رَبُّ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَمَا بَيْنَهُمَا ٱلْعَزِيزُ ٱلْغَفَّٰرُ', 'رب السموت والأرض وما بينهما العزيز الغفر', NULL, 457, 'local:hafs-text.json'),
  ('hafs-38-67', 'hafs', 38, 67, 'قُلْ هُوَ نَبَؤٌا۟ عَظِيمٌ', 'قل هو نبؤا عظيم', NULL, 457, 'local:hafs-text.json'),
  ('hafs-38-68', 'hafs', 38, 68, 'أَنتُمْ عَنْهُ مُعْرِضُونَ', 'أنتم عنه معرضون', NULL, 457, 'local:hafs-text.json'),
  ('hafs-38-69', 'hafs', 38, 69, 'مَا كَانَ لِىَ مِنْ عِلْمٍۭ بِٱلْمَلَإِ ٱلْأَعْلَىٰٓ إِذْ يَخْتَصِمُونَ', 'ما كان لى من علم بالملإ الأعلى إذ يختصمون', NULL, 457, 'local:hafs-text.json'),
  ('hafs-38-70', 'hafs', 38, 70, 'إِن يُوحَىٰٓ إِلَىَّ إِلَّآ أَنَّمَآ أَنَا۠ نَذِيرٌۭ مُّبِينٌ', 'إن يوحى إلى إلا أنما أنا نذير مبين', NULL, 457, 'local:hafs-text.json'),
  ('hafs-38-71', 'hafs', 38, 71, 'إِذْ قَالَ رَبُّكَ لِلْمَلَٰٓئِكَةِ إِنِّى خَٰلِقٌۢ بَشَرًۭا مِّن طِينٍۢ', 'إذ قال ربك للملئكة إنى خلق بشرا من طين', NULL, 457, 'local:hafs-text.json'),
  ('hafs-38-72', 'hafs', 38, 72, 'فَإِذَا سَوَّيْتُهُۥ وَنَفَخْتُ فِيهِ مِن رُّوحِى فَقَعُوا۟ لَهُۥ سَٰجِدِينَ', 'فإذا سويته ونفخت فيه من روحى فقعوا له سجدين', NULL, 457, 'local:hafs-text.json'),
  ('hafs-38-73', 'hafs', 38, 73, 'فَسَجَدَ ٱلْمَلَٰٓئِكَةُ كُلُّهُمْ أَجْمَعُونَ', 'فسجد الملئكة كلهم أجمعون', NULL, 457, 'local:hafs-text.json'),
  ('hafs-38-74', 'hafs', 38, 74, 'إِلَّآ إِبْلِيسَ ٱسْتَكْبَرَ وَكَانَ مِنَ ٱلْكَٰفِرِينَ', 'إلا إبليس استكبر وكان من الكفرين', NULL, 457, 'local:hafs-text.json'),
  ('hafs-38-75', 'hafs', 38, 75, 'قَالَ يَٰٓإِبْلِيسُ مَا مَنَعَكَ أَن تَسْجُدَ لِمَا خَلَقْتُ بِيَدَىَّ ۖ أَسْتَكْبَرْتَ أَمْ كُنتَ مِنَ ٱلْعَالِينَ', 'قال يإبليس ما منعك أن تسجد لما خلقت بيدى  أستكبرت أم كنت من العالين', NULL, 457, 'local:hafs-text.json'),
  ('hafs-38-76', 'hafs', 38, 76, 'قَالَ أَنَا۠ خَيْرٌۭ مِّنْهُ ۖ خَلَقْتَنِى مِن نَّارٍۢ وَخَلَقْتَهُۥ مِن طِينٍۢ', 'قال أنا خير منه  خلقتنى من نار وخلقته من طين', NULL, 457, 'local:hafs-text.json'),
  ('hafs-38-77', 'hafs', 38, 77, 'قَالَ فَٱخْرُجْ مِنْهَا فَإِنَّكَ رَجِيمٌۭ', 'قال فاخرج منها فإنك رجيم', NULL, 457, 'local:hafs-text.json'),
  ('hafs-38-78', 'hafs', 38, 78, 'وَإِنَّ عَلَيْكَ لَعْنَتِىٓ إِلَىٰ يَوْمِ ٱلدِّينِ', 'وإن عليك لعنتى إلى يوم الدين', NULL, 457, 'local:hafs-text.json'),
  ('hafs-38-79', 'hafs', 38, 79, 'قَالَ رَبِّ فَأَنظِرْنِىٓ إِلَىٰ يَوْمِ يُبْعَثُونَ', 'قال رب فأنظرنى إلى يوم يبعثون', NULL, 457, 'local:hafs-text.json'),
  ('hafs-38-80', 'hafs', 38, 80, 'قَالَ فَإِنَّكَ مِنَ ٱلْمُنظَرِينَ', 'قال فإنك من المنظرين', NULL, 457, 'local:hafs-text.json'),
  ('hafs-38-81', 'hafs', 38, 81, 'إِلَىٰ يَوْمِ ٱلْوَقْتِ ٱلْمَعْلُومِ', 'إلى يوم الوقت المعلوم', NULL, 457, 'local:hafs-text.json'),
  ('hafs-38-82', 'hafs', 38, 82, 'قَالَ فَبِعِزَّتِكَ لَأُغْوِيَنَّهُمْ أَجْمَعِينَ', 'قال فبعزتك لأغوينهم أجمعين', NULL, 457, 'local:hafs-text.json'),
  ('hafs-38-83', 'hafs', 38, 83, 'إِلَّا عِبَادَكَ مِنْهُمُ ٱلْمُخْلَصِينَ', 'إلا عبادك منهم المخلصين', NULL, 457, 'local:hafs-text.json'),
  ('hafs-38-84', 'hafs', 38, 84, 'قَالَ فَٱلْحَقُّ وَٱلْحَقَّ أَقُولُ', 'قال فالحق والحق أقول', NULL, 458, 'local:hafs-text.json'),
  ('hafs-38-85', 'hafs', 38, 85, 'لَأَمْلَأَنَّ جَهَنَّمَ مِنكَ وَمِمَّن تَبِعَكَ مِنْهُمْ أَجْمَعِينَ', 'لأملأن جهنم منك وممن تبعك منهم أجمعين', NULL, 458, 'local:hafs-text.json'),
  ('hafs-38-86', 'hafs', 38, 86, 'قُلْ مَآ أَسْـَٔلُكُمْ عَلَيْهِ مِنْ أَجْرٍۢ وَمَآ أَنَا۠ مِنَ ٱلْمُتَكَلِّفِينَ', 'قل ما أسلكم عليه من أجر وما أنا من المتكلفين', NULL, 458, 'local:hafs-text.json'),
  ('hafs-38-87', 'hafs', 38, 87, 'إِنْ هُوَ إِلَّا ذِكْرٌۭ لِّلْعَٰلَمِينَ', 'إن هو إلا ذكر للعلمين', NULL, 458, 'local:hafs-text.json'),
  ('hafs-38-88', 'hafs', 38, 88, 'وَلَتَعْلَمُنَّ نَبَأَهُۥ بَعْدَ حِينٍۭ', 'ولتعلمن نبأه بعد حين', NULL, 458, 'local:hafs-text.json'),
  ('hafs-39-1', 'hafs', 39, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ تَنزِيلُ ٱلْكِتَٰبِ مِنَ ٱللَّهِ ٱلْعَزِيزِ ٱلْحَكِيمِ', 'بسم الله الرحمن الرحيم تنزيل الكتب من الله العزيز الحكيم', NULL, 458, 'local:hafs-text.json'),
  ('hafs-39-2', 'hafs', 39, 2, 'إِنَّآ أَنزَلْنَآ إِلَيْكَ ٱلْكِتَٰبَ بِٱلْحَقِّ فَٱعْبُدِ ٱللَّهَ مُخْلِصًۭا لَّهُ ٱلدِّينَ', 'إنا أنزلنا إليك الكتب بالحق فاعبد الله مخلصا له الدين', NULL, 458, 'local:hafs-text.json'),
  ('hafs-39-3', 'hafs', 39, 3, 'أَلَا لِلَّهِ ٱلدِّينُ ٱلْخَالِصُ ۚ وَٱلَّذِينَ ٱتَّخَذُوا۟ مِن دُونِهِۦٓ أَوْلِيَآءَ مَا نَعْبُدُهُمْ إِلَّا لِيُقَرِّبُونَآ إِلَى ٱللَّهِ زُلْفَىٰٓ إِنَّ ٱللَّهَ يَحْكُمُ بَيْنَهُمْ فِى مَا هُمْ فِيهِ يَخْتَلِفُونَ ۗ إِنَّ ٱللَّهَ لَا يَهْدِى مَنْ هُوَ كَٰذِبٌۭ كَفَّارٌۭ', 'ألا لله الدين الخالص  والذين اتخذوا من دونه أولياء ما نعبدهم إلا ليقربونا إلى الله زلفى إن الله يحكم بينهم فى ما هم فيه يختلفون  إن الله لا يهدى من هو كذب كفار', NULL, 458, 'local:hafs-text.json'),
  ('hafs-39-4', 'hafs', 39, 4, 'لَّوْ أَرَادَ ٱللَّهُ أَن يَتَّخِذَ وَلَدًۭا لَّٱصْطَفَىٰ مِمَّا يَخْلُقُ مَا يَشَآءُ ۚ سُبْحَٰنَهُۥ ۖ هُوَ ٱللَّهُ ٱلْوَٰحِدُ ٱلْقَهَّارُ', 'لو أراد الله أن يتخذ ولدا لاصطفى مما يخلق ما يشاء  سبحنه  هو الله الوحد القهار', NULL, 458, 'local:hafs-text.json'),
  ('hafs-39-5', 'hafs', 39, 5, 'خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ بِٱلْحَقِّ ۖ يُكَوِّرُ ٱلَّيْلَ عَلَى ٱلنَّهَارِ وَيُكَوِّرُ ٱلنَّهَارَ عَلَى ٱلَّيْلِ ۖ وَسَخَّرَ ٱلشَّمْسَ وَٱلْقَمَرَ ۖ كُلٌّۭ يَجْرِى لِأَجَلٍۢ مُّسَمًّى ۗ أَلَا هُوَ ٱلْعَزِيزُ ٱلْغَفَّٰرُ', 'خلق السموت والأرض بالحق  يكور اليل على النهار ويكور النهار على اليل  وسخر الشمس والقمر  كل يجرى لأجل مسمى  ألا هو العزيز الغفر', NULL, 458, 'local:hafs-text.json'),
  ('hafs-39-6', 'hafs', 39, 6, 'خَلَقَكُم مِّن نَّفْسٍۢ وَٰحِدَةٍۢ ثُمَّ جَعَلَ مِنْهَا زَوْجَهَا وَأَنزَلَ لَكُم مِّنَ ٱلْأَنْعَٰمِ ثَمَٰنِيَةَ أَزْوَٰجٍۢ ۚ يَخْلُقُكُمْ فِى بُطُونِ أُمَّهَٰتِكُمْ خَلْقًۭا مِّنۢ بَعْدِ خَلْقٍۢ فِى ظُلُمَٰتٍۢ ثَلَٰثٍۢ ۚ ذَٰلِكُمُ ٱللَّهُ رَبُّكُمْ لَهُ ٱلْمُلْكُ ۖ لَآ إِلَٰهَ إِلَّا هُوَ ۖ فَأَنَّىٰ تُصْرَفُونَ', 'خلقكم من نفس وحدة ثم جعل منها زوجها وأنزل لكم من الأنعم ثمنية أزوج  يخلقكم فى بطون أمهتكم خلقا من بعد خلق فى ظلمت ثلث  ذلكم الله ربكم له الملك  لا إله إلا هو  فأنى تصرفون', NULL, 459, 'local:hafs-text.json'),
  ('hafs-39-7', 'hafs', 39, 7, 'إِن تَكْفُرُوا۟ فَإِنَّ ٱللَّهَ غَنِىٌّ عَنكُمْ ۖ وَلَا يَرْضَىٰ لِعِبَادِهِ ٱلْكُفْرَ ۖ وَإِن تَشْكُرُوا۟ يَرْضَهُ لَكُمْ ۗ وَلَا تَزِرُ وَازِرَةٌۭ وِزْرَ أُخْرَىٰ ۗ ثُمَّ إِلَىٰ رَبِّكُم مَّرْجِعُكُمْ فَيُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ ۚ إِنَّهُۥ عَلِيمٌۢ بِذَاتِ ٱلصُّدُورِ', 'إن تكفروا فإن الله غنى عنكم  ولا يرضى لعباده الكفر  وإن تشكروا يرضه لكم  ولا تزر وازرة وزر أخرى  ثم إلى ربكم مرجعكم فينبئكم بما كنتم تعملون  إنه عليم بذات الصدور', NULL, 459, 'local:hafs-text.json'),
  ('hafs-39-8', 'hafs', 39, 8, '۞ وَإِذَا مَسَّ ٱلْإِنسَٰنَ ضُرٌّۭ دَعَا رَبَّهُۥ مُنِيبًا إِلَيْهِ ثُمَّ إِذَا خَوَّلَهُۥ نِعْمَةًۭ مِّنْهُ نَسِىَ مَا كَانَ يَدْعُوٓا۟ إِلَيْهِ مِن قَبْلُ وَجَعَلَ لِلَّهِ أَندَادًۭا لِّيُضِلَّ عَن سَبِيلِهِۦ ۚ قُلْ تَمَتَّعْ بِكُفْرِكَ قَلِيلًا ۖ إِنَّكَ مِنْ أَصْحَٰبِ ٱلنَّارِ', 'وإذا مس الإنسن ضر دعا ربه منيبا إليه ثم إذا خوله نعمة منه نسى ما كان يدعوا إليه من قبل وجعل لله أندادا ليضل عن سبيله  قل تمتع بكفرك قليلا  إنك من أصحب النار', NULL, 459, 'local:hafs-text.json'),
  ('hafs-39-9', 'hafs', 39, 9, 'أَمَّنْ هُوَ قَٰنِتٌ ءَانَآءَ ٱلَّيْلِ سَاجِدًۭا وَقَآئِمًۭا يَحْذَرُ ٱلْءَاخِرَةَ وَيَرْجُوا۟ رَحْمَةَ رَبِّهِۦ ۗ قُلْ هَلْ يَسْتَوِى ٱلَّذِينَ يَعْلَمُونَ وَٱلَّذِينَ لَا يَعْلَمُونَ ۗ إِنَّمَا يَتَذَكَّرُ أُو۟لُوا۟ ٱلْأَلْبَٰبِ', 'أمن هو قنت ءاناء اليل ساجدا وقائما يحذر الءاخرة ويرجوا رحمة ربه  قل هل يستوى الذين يعلمون والذين لا يعلمون  إنما يتذكر أولوا الألبب', NULL, 459, 'local:hafs-text.json'),
  ('hafs-39-10', 'hafs', 39, 10, 'قُلْ يَٰعِبَادِ ٱلَّذِينَ ءَامَنُوا۟ ٱتَّقُوا۟ رَبَّكُمْ ۚ لِلَّذِينَ أَحْسَنُوا۟ فِى هَٰذِهِ ٱلدُّنْيَا حَسَنَةٌۭ ۗ وَأَرْضُ ٱللَّهِ وَٰسِعَةٌ ۗ إِنَّمَا يُوَفَّى ٱلصَّٰبِرُونَ أَجْرَهُم بِغَيْرِ حِسَابٍۢ', 'قل يعباد الذين ءامنوا اتقوا ربكم  للذين أحسنوا فى هذه الدنيا حسنة  وأرض الله وسعة  إنما يوفى الصبرون أجرهم بغير حساب', NULL, 459, 'local:hafs-text.json'),
  ('hafs-39-11', 'hafs', 39, 11, 'قُلْ إِنِّىٓ أُمِرْتُ أَنْ أَعْبُدَ ٱللَّهَ مُخْلِصًۭا لَّهُ ٱلدِّينَ', 'قل إنى أمرت أن أعبد الله مخلصا له الدين', NULL, 460, 'local:hafs-text.json'),
  ('hafs-39-12', 'hafs', 39, 12, 'وَأُمِرْتُ لِأَنْ أَكُونَ أَوَّلَ ٱلْمُسْلِمِينَ', 'وأمرت لأن أكون أول المسلمين', NULL, 460, 'local:hafs-text.json'),
  ('hafs-39-13', 'hafs', 39, 13, 'قُلْ إِنِّىٓ أَخَافُ إِنْ عَصَيْتُ رَبِّى عَذَابَ يَوْمٍ عَظِيمٍۢ', 'قل إنى أخاف إن عصيت ربى عذاب يوم عظيم', NULL, 460, 'local:hafs-text.json'),
  ('hafs-39-14', 'hafs', 39, 14, 'قُلِ ٱللَّهَ أَعْبُدُ مُخْلِصًۭا لَّهُۥ دِينِى', 'قل الله أعبد مخلصا له دينى', NULL, 460, 'local:hafs-text.json'),
  ('hafs-39-15', 'hafs', 39, 15, 'فَٱعْبُدُوا۟ مَا شِئْتُم مِّن دُونِهِۦ ۗ قُلْ إِنَّ ٱلْخَٰسِرِينَ ٱلَّذِينَ خَسِرُوٓا۟ أَنفُسَهُمْ وَأَهْلِيهِمْ يَوْمَ ٱلْقِيَٰمَةِ ۗ أَلَا ذَٰلِكَ هُوَ ٱلْخُسْرَانُ ٱلْمُبِينُ', 'فاعبدوا ما شئتم من دونه  قل إن الخسرين الذين خسروا أنفسهم وأهليهم يوم القيمة  ألا ذلك هو الخسران المبين', NULL, 460, 'local:hafs-text.json'),
  ('hafs-39-16', 'hafs', 39, 16, 'لَهُم مِّن فَوْقِهِمْ ظُلَلٌۭ مِّنَ ٱلنَّارِ وَمِن تَحْتِهِمْ ظُلَلٌۭ ۚ ذَٰلِكَ يُخَوِّفُ ٱللَّهُ بِهِۦ عِبَادَهُۥ ۚ يَٰعِبَادِ فَٱتَّقُونِ', 'لهم من فوقهم ظلل من النار ومن تحتهم ظلل  ذلك يخوف الله به عباده  يعباد فاتقون', NULL, 460, 'local:hafs-text.json'),
  ('hafs-39-17', 'hafs', 39, 17, 'وَٱلَّذِينَ ٱجْتَنَبُوا۟ ٱلطَّٰغُوتَ أَن يَعْبُدُوهَا وَأَنَابُوٓا۟ إِلَى ٱللَّهِ لَهُمُ ٱلْبُشْرَىٰ ۚ فَبَشِّرْ عِبَادِ', 'والذين اجتنبوا الطغوت أن يعبدوها وأنابوا إلى الله لهم البشرى  فبشر عباد', NULL, 460, 'local:hafs-text.json'),
  ('hafs-39-18', 'hafs', 39, 18, 'ٱلَّذِينَ يَسْتَمِعُونَ ٱلْقَوْلَ فَيَتَّبِعُونَ أَحْسَنَهُۥٓ ۚ أُو۟لَٰٓئِكَ ٱلَّذِينَ هَدَىٰهُمُ ٱللَّهُ ۖ وَأُو۟لَٰٓئِكَ هُمْ أُو۟لُوا۟ ٱلْأَلْبَٰبِ', 'الذين يستمعون القول فيتبعون أحسنه  أولئك الذين هدىهم الله  وأولئك هم أولوا الألبب', NULL, 460, 'local:hafs-text.json'),
  ('hafs-39-19', 'hafs', 39, 19, 'أَفَمَنْ حَقَّ عَلَيْهِ كَلِمَةُ ٱلْعَذَابِ أَفَأَنتَ تُنقِذُ مَن فِى ٱلنَّارِ', 'أفمن حق عليه كلمة العذاب أفأنت تنقذ من فى النار', NULL, 460, 'local:hafs-text.json'),
  ('hafs-39-20', 'hafs', 39, 20, 'لَٰكِنِ ٱلَّذِينَ ٱتَّقَوْا۟ رَبَّهُمْ لَهُمْ غُرَفٌۭ مِّن فَوْقِهَا غُرَفٌۭ مَّبْنِيَّةٌۭ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ ۖ وَعْدَ ٱللَّهِ ۖ لَا يُخْلِفُ ٱللَّهُ ٱلْمِيعَادَ', 'لكن الذين اتقوا ربهم لهم غرف من فوقها غرف مبنية تجرى من تحتها الأنهر  وعد الله  لا يخلف الله الميعاد', NULL, 460, 'local:hafs-text.json'),
  ('hafs-39-21', 'hafs', 39, 21, 'أَلَمْ تَرَ أَنَّ ٱللَّهَ أَنزَلَ مِنَ ٱلسَّمَآءِ مَآءًۭ فَسَلَكَهُۥ يَنَٰبِيعَ فِى ٱلْأَرْضِ ثُمَّ يُخْرِجُ بِهِۦ زَرْعًۭا مُّخْتَلِفًا أَلْوَٰنُهُۥ ثُمَّ يَهِيجُ فَتَرَىٰهُ مُصْفَرًّۭا ثُمَّ يَجْعَلُهُۥ حُطَٰمًا ۚ إِنَّ فِى ذَٰلِكَ لَذِكْرَىٰ لِأُو۟لِى ٱلْأَلْبَٰبِ', 'ألم تر أن الله أنزل من السماء ماء فسلكه ينبيع فى الأرض ثم يخرج به زرعا مختلفا ألونه ثم يهيج فترىه مصفرا ثم يجعله حطما  إن فى ذلك لذكرى لأولى الألبب', NULL, 460, 'local:hafs-text.json'),
  ('hafs-39-22', 'hafs', 39, 22, 'أَفَمَن شَرَحَ ٱللَّهُ صَدْرَهُۥ لِلْإِسْلَٰمِ فَهُوَ عَلَىٰ نُورٍۢ مِّن رَّبِّهِۦ ۚ فَوَيْلٌۭ لِّلْقَٰسِيَةِ قُلُوبُهُم مِّن ذِكْرِ ٱللَّهِ ۚ أُو۟لَٰٓئِكَ فِى ضَلَٰلٍۢ مُّبِينٍ', 'أفمن شرح الله صدره للإسلم فهو على نور من ربه  فويل للقسية قلوبهم من ذكر الله  أولئك فى ضلل مبين', NULL, 461, 'local:hafs-text.json'),
  ('hafs-39-23', 'hafs', 39, 23, 'ٱللَّهُ نَزَّلَ أَحْسَنَ ٱلْحَدِيثِ كِتَٰبًۭا مُّتَشَٰبِهًۭا مَّثَانِىَ تَقْشَعِرُّ مِنْهُ جُلُودُ ٱلَّذِينَ يَخْشَوْنَ رَبَّهُمْ ثُمَّ تَلِينُ جُلُودُهُمْ وَقُلُوبُهُمْ إِلَىٰ ذِكْرِ ٱللَّهِ ۚ ذَٰلِكَ هُدَى ٱللَّهِ يَهْدِى بِهِۦ مَن يَشَآءُ ۚ وَمَن يُضْلِلِ ٱللَّهُ فَمَا لَهُۥ مِنْ هَادٍ', 'الله نزل أحسن الحديث كتبا متشبها مثانى تقشعر منه جلود الذين يخشون ربهم ثم تلين جلودهم وقلوبهم إلى ذكر الله  ذلك هدى الله يهدى به من يشاء  ومن يضلل الله فما له من هاد', NULL, 461, 'local:hafs-text.json'),
  ('hafs-39-24', 'hafs', 39, 24, 'أَفَمَن يَتَّقِى بِوَجْهِهِۦ سُوٓءَ ٱلْعَذَابِ يَوْمَ ٱلْقِيَٰمَةِ ۚ وَقِيلَ لِلظَّٰلِمِينَ ذُوقُوا۟ مَا كُنتُمْ تَكْسِبُونَ', 'أفمن يتقى بوجهه سوء العذاب يوم القيمة  وقيل للظلمين ذوقوا ما كنتم تكسبون', NULL, 461, 'local:hafs-text.json'),
  ('hafs-39-25', 'hafs', 39, 25, 'كَذَّبَ ٱلَّذِينَ مِن قَبْلِهِمْ فَأَتَىٰهُمُ ٱلْعَذَابُ مِنْ حَيْثُ لَا يَشْعُرُونَ', 'كذب الذين من قبلهم فأتىهم العذاب من حيث لا يشعرون', NULL, 461, 'local:hafs-text.json'),
  ('hafs-39-26', 'hafs', 39, 26, 'فَأَذَاقَهُمُ ٱللَّهُ ٱلْخِزْىَ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا ۖ وَلَعَذَابُ ٱلْءَاخِرَةِ أَكْبَرُ ۚ لَوْ كَانُوا۟ يَعْلَمُونَ', 'فأذاقهم الله الخزى فى الحيوة الدنيا  ولعذاب الءاخرة أكبر  لو كانوا يعلمون', NULL, 461, 'local:hafs-text.json'),
  ('hafs-39-27', 'hafs', 39, 27, 'وَلَقَدْ ضَرَبْنَا لِلنَّاسِ فِى هَٰذَا ٱلْقُرْءَانِ مِن كُلِّ مَثَلٍۢ لَّعَلَّهُمْ يَتَذَكَّرُونَ', 'ولقد ضربنا للناس فى هذا القرءان من كل مثل لعلهم يتذكرون', NULL, 461, 'local:hafs-text.json'),
  ('hafs-39-28', 'hafs', 39, 28, 'قُرْءَانًا عَرَبِيًّا غَيْرَ ذِى عِوَجٍۢ لَّعَلَّهُمْ يَتَّقُونَ', 'قرءانا عربيا غير ذى عوج لعلهم يتقون', NULL, 461, 'local:hafs-text.json'),
  ('hafs-39-29', 'hafs', 39, 29, 'ضَرَبَ ٱللَّهُ مَثَلًۭا رَّجُلًۭا فِيهِ شُرَكَآءُ مُتَشَٰكِسُونَ وَرَجُلًۭا سَلَمًۭا لِّرَجُلٍ هَلْ يَسْتَوِيَانِ مَثَلًا ۚ ٱلْحَمْدُ لِلَّهِ ۚ بَلْ أَكْثَرُهُمْ لَا يَعْلَمُونَ', 'ضرب الله مثلا رجلا فيه شركاء متشكسون ورجلا سلما لرجل هل يستويان مثلا  الحمد لله  بل أكثرهم لا يعلمون', NULL, 461, 'local:hafs-text.json'),
  ('hafs-39-30', 'hafs', 39, 30, 'إِنَّكَ مَيِّتٌۭ وَإِنَّهُم مَّيِّتُونَ', 'إنك ميت وإنهم ميتون', NULL, 461, 'local:hafs-text.json'),
  ('hafs-39-31', 'hafs', 39, 31, 'ثُمَّ إِنَّكُمْ يَوْمَ ٱلْقِيَٰمَةِ عِندَ رَبِّكُمْ تَخْتَصِمُونَ', 'ثم إنكم يوم القيمة عند ربكم تختصمون', NULL, 461, 'local:hafs-text.json'),
  ('hafs-39-32', 'hafs', 39, 32, '۞ فَمَنْ أَظْلَمُ مِمَّن كَذَبَ عَلَى ٱللَّهِ وَكَذَّبَ بِٱلصِّدْقِ إِذْ جَآءَهُۥٓ ۚ أَلَيْسَ فِى جَهَنَّمَ مَثْوًۭى لِّلْكَٰفِرِينَ', 'فمن أظلم ممن كذب على الله وكذب بالصدق إذ جاءه  أليس فى جهنم مثوى للكفرين', NULL, 462, 'local:hafs-text.json'),
  ('hafs-39-33', 'hafs', 39, 33, 'وَٱلَّذِى جَآءَ بِٱلصِّدْقِ وَصَدَّقَ بِهِۦٓ ۙ أُو۟لَٰٓئِكَ هُمُ ٱلْمُتَّقُونَ', 'والذى جاء بالصدق وصدق به  أولئك هم المتقون', NULL, 462, 'local:hafs-text.json'),
  ('hafs-39-34', 'hafs', 39, 34, 'لَهُم مَّا يَشَآءُونَ عِندَ رَبِّهِمْ ۚ ذَٰلِكَ جَزَآءُ ٱلْمُحْسِنِينَ', 'لهم ما يشاءون عند ربهم  ذلك جزاء المحسنين', NULL, 462, 'local:hafs-text.json'),
  ('hafs-39-35', 'hafs', 39, 35, 'لِيُكَفِّرَ ٱللَّهُ عَنْهُمْ أَسْوَأَ ٱلَّذِى عَمِلُوا۟ وَيَجْزِيَهُمْ أَجْرَهُم بِأَحْسَنِ ٱلَّذِى كَانُوا۟ يَعْمَلُونَ', 'ليكفر الله عنهم أسوأ الذى عملوا ويجزيهم أجرهم بأحسن الذى كانوا يعملون', NULL, 462, 'local:hafs-text.json'),
  ('hafs-39-36', 'hafs', 39, 36, 'أَلَيْسَ ٱللَّهُ بِكَافٍ عَبْدَهُۥ ۖ وَيُخَوِّفُونَكَ بِٱلَّذِينَ مِن دُونِهِۦ ۚ وَمَن يُضْلِلِ ٱللَّهُ فَمَا لَهُۥ مِنْ هَادٍۢ', 'أليس الله بكاف عبده  ويخوفونك بالذين من دونه  ومن يضلل الله فما له من هاد', NULL, 462, 'local:hafs-text.json'),
  ('hafs-39-37', 'hafs', 39, 37, 'وَمَن يَهْدِ ٱللَّهُ فَمَا لَهُۥ مِن مُّضِلٍّ ۗ أَلَيْسَ ٱللَّهُ بِعَزِيزٍۢ ذِى ٱنتِقَامٍۢ', 'ومن يهد الله فما له من مضل  أليس الله بعزيز ذى انتقام', NULL, 462, 'local:hafs-text.json'),
  ('hafs-39-38', 'hafs', 39, 38, 'وَلَئِن سَأَلْتَهُم مَّنْ خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ لَيَقُولُنَّ ٱللَّهُ ۚ قُلْ أَفَرَءَيْتُم مَّا تَدْعُونَ مِن دُونِ ٱللَّهِ إِنْ أَرَادَنِىَ ٱللَّهُ بِضُرٍّ هَلْ هُنَّ كَٰشِفَٰتُ ضُرِّهِۦٓ أَوْ أَرَادَنِى بِرَحْمَةٍ هَلْ هُنَّ مُمْسِكَٰتُ رَحْمَتِهِۦ ۚ قُلْ حَسْبِىَ ٱللَّهُ ۖ عَلَيْهِ يَتَوَكَّلُ ٱلْمُتَوَكِّلُونَ', 'ولئن سألتهم من خلق السموت والأرض ليقولن الله  قل أفرءيتم ما تدعون من دون الله إن أرادنى الله بضر هل هن كشفت ضره أو أرادنى برحمة هل هن ممسكت رحمته  قل حسبى الله  عليه يتوكل المتوكلون', NULL, 462, 'local:hafs-text.json'),
  ('hafs-39-39', 'hafs', 39, 39, 'قُلْ يَٰقَوْمِ ٱعْمَلُوا۟ عَلَىٰ مَكَانَتِكُمْ إِنِّى عَٰمِلٌۭ ۖ فَسَوْفَ تَعْلَمُونَ', 'قل يقوم اعملوا على مكانتكم إنى عمل  فسوف تعلمون', NULL, 462, 'local:hafs-text.json'),
  ('hafs-39-40', 'hafs', 39, 40, 'مَن يَأْتِيهِ عَذَابٌۭ يُخْزِيهِ وَيَحِلُّ عَلَيْهِ عَذَابٌۭ مُّقِيمٌ', 'من يأتيه عذاب يخزيه ويحل عليه عذاب مقيم', NULL, 462, 'local:hafs-text.json'),
  ('hafs-39-41', 'hafs', 39, 41, 'إِنَّآ أَنزَلْنَا عَلَيْكَ ٱلْكِتَٰبَ لِلنَّاسِ بِٱلْحَقِّ ۖ فَمَنِ ٱهْتَدَىٰ فَلِنَفْسِهِۦ ۖ وَمَن ضَلَّ فَإِنَّمَا يَضِلُّ عَلَيْهَا ۖ وَمَآ أَنتَ عَلَيْهِم بِوَكِيلٍ', 'إنا أنزلنا عليك الكتب للناس بالحق  فمن اهتدى فلنفسه  ومن ضل فإنما يضل عليها  وما أنت عليهم بوكيل', NULL, 463, 'local:hafs-text.json'),
  ('hafs-39-42', 'hafs', 39, 42, 'ٱللَّهُ يَتَوَفَّى ٱلْأَنفُسَ حِينَ مَوْتِهَا وَٱلَّتِى لَمْ تَمُتْ فِى مَنَامِهَا ۖ فَيُمْسِكُ ٱلَّتِى قَضَىٰ عَلَيْهَا ٱلْمَوْتَ وَيُرْسِلُ ٱلْأُخْرَىٰٓ إِلَىٰٓ أَجَلٍۢ مُّسَمًّى ۚ إِنَّ فِى ذَٰلِكَ لَءَايَٰتٍۢ لِّقَوْمٍۢ يَتَفَكَّرُونَ', 'الله يتوفى الأنفس حين موتها والتى لم تمت فى منامها  فيمسك التى قضى عليها الموت ويرسل الأخرى إلى أجل مسمى  إن فى ذلك لءايت لقوم يتفكرون', NULL, 463, 'local:hafs-text.json'),
  ('hafs-39-43', 'hafs', 39, 43, 'أَمِ ٱتَّخَذُوا۟ مِن دُونِ ٱللَّهِ شُفَعَآءَ ۚ قُلْ أَوَلَوْ كَانُوا۟ لَا يَمْلِكُونَ شَيْـًۭٔا وَلَا يَعْقِلُونَ', 'أم اتخذوا من دون الله شفعاء  قل أولو كانوا لا يملكون شيا ولا يعقلون', NULL, 463, 'local:hafs-text.json'),
  ('hafs-39-44', 'hafs', 39, 44, 'قُل لِّلَّهِ ٱلشَّفَٰعَةُ جَمِيعًۭا ۖ لَّهُۥ مُلْكُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ ۖ ثُمَّ إِلَيْهِ تُرْجَعُونَ', 'قل لله الشفعة جميعا  له ملك السموت والأرض  ثم إليه ترجعون', NULL, 463, 'local:hafs-text.json'),
  ('hafs-39-45', 'hafs', 39, 45, 'وَإِذَا ذُكِرَ ٱللَّهُ وَحْدَهُ ٱشْمَأَزَّتْ قُلُوبُ ٱلَّذِينَ لَا يُؤْمِنُونَ بِٱلْءَاخِرَةِ ۖ وَإِذَا ذُكِرَ ٱلَّذِينَ مِن دُونِهِۦٓ إِذَا هُمْ يَسْتَبْشِرُونَ', 'وإذا ذكر الله وحده اشمأزت قلوب الذين لا يؤمنون بالءاخرة  وإذا ذكر الذين من دونه إذا هم يستبشرون', NULL, 463, 'local:hafs-text.json'),
  ('hafs-39-46', 'hafs', 39, 46, 'قُلِ ٱللَّهُمَّ فَاطِرَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ عَٰلِمَ ٱلْغَيْبِ وَٱلشَّهَٰدَةِ أَنتَ تَحْكُمُ بَيْنَ عِبَادِكَ فِى مَا كَانُوا۟ فِيهِ يَخْتَلِفُونَ', 'قل اللهم فاطر السموت والأرض علم الغيب والشهدة أنت تحكم بين عبادك فى ما كانوا فيه يختلفون', NULL, 463, 'local:hafs-text.json'),
  ('hafs-39-47', 'hafs', 39, 47, 'وَلَوْ أَنَّ لِلَّذِينَ ظَلَمُوا۟ مَا فِى ٱلْأَرْضِ جَمِيعًۭا وَمِثْلَهُۥ مَعَهُۥ لَٱفْتَدَوْا۟ بِهِۦ مِن سُوٓءِ ٱلْعَذَابِ يَوْمَ ٱلْقِيَٰمَةِ ۚ وَبَدَا لَهُم مِّنَ ٱللَّهِ مَا لَمْ يَكُونُوا۟ يَحْتَسِبُونَ', 'ولو أن للذين ظلموا ما فى الأرض جميعا ومثله معه لافتدوا به من سوء العذاب يوم القيمة  وبدا لهم من الله ما لم يكونوا يحتسبون', NULL, 463, 'local:hafs-text.json'),
  ('hafs-39-48', 'hafs', 39, 48, 'وَبَدَا لَهُمْ سَيِّـَٔاتُ مَا كَسَبُوا۟ وَحَاقَ بِهِم مَّا كَانُوا۟ بِهِۦ يَسْتَهْزِءُونَ', 'وبدا لهم سيات ما كسبوا وحاق بهم ما كانوا به يستهزءون', NULL, 464, 'local:hafs-text.json'),
  ('hafs-39-49', 'hafs', 39, 49, 'فَإِذَا مَسَّ ٱلْإِنسَٰنَ ضُرٌّۭ دَعَانَا ثُمَّ إِذَا خَوَّلْنَٰهُ نِعْمَةًۭ مِّنَّا قَالَ إِنَّمَآ أُوتِيتُهُۥ عَلَىٰ عِلْمٍۭ ۚ بَلْ هِىَ فِتْنَةٌۭ وَلَٰكِنَّ أَكْثَرَهُمْ لَا يَعْلَمُونَ', 'فإذا مس الإنسن ضر دعانا ثم إذا خولنه نعمة منا قال إنما أوتيته على علم  بل هى فتنة ولكن أكثرهم لا يعلمون', NULL, 464, 'local:hafs-text.json'),
  ('hafs-39-50', 'hafs', 39, 50, 'قَدْ قَالَهَا ٱلَّذِينَ مِن قَبْلِهِمْ فَمَآ أَغْنَىٰ عَنْهُم مَّا كَانُوا۟ يَكْسِبُونَ', 'قد قالها الذين من قبلهم فما أغنى عنهم ما كانوا يكسبون', NULL, 464, 'local:hafs-text.json'),
  ('hafs-39-51', 'hafs', 39, 51, 'فَأَصَابَهُمْ سَيِّـَٔاتُ مَا كَسَبُوا۟ ۚ وَٱلَّذِينَ ظَلَمُوا۟ مِنْ هَٰٓؤُلَآءِ سَيُصِيبُهُمْ سَيِّـَٔاتُ مَا كَسَبُوا۟ وَمَا هُم بِمُعْجِزِينَ', 'فأصابهم سيات ما كسبوا  والذين ظلموا من هؤلاء سيصيبهم سيات ما كسبوا وما هم بمعجزين', NULL, 464, 'local:hafs-text.json'),
  ('hafs-39-52', 'hafs', 39, 52, 'أَوَلَمْ يَعْلَمُوٓا۟ أَنَّ ٱللَّهَ يَبْسُطُ ٱلرِّزْقَ لِمَن يَشَآءُ وَيَقْدِرُ ۚ إِنَّ فِى ذَٰلِكَ لَءَايَٰتٍۢ لِّقَوْمٍۢ يُؤْمِنُونَ', 'أولم يعلموا أن الله يبسط الرزق لمن يشاء ويقدر  إن فى ذلك لءايت لقوم يؤمنون', NULL, 464, 'local:hafs-text.json'),
  ('hafs-39-53', 'hafs', 39, 53, '۞ قُلْ يَٰعِبَادِىَ ٱلَّذِينَ أَسْرَفُوا۟ عَلَىٰٓ أَنفُسِهِمْ لَا تَقْنَطُوا۟ مِن رَّحْمَةِ ٱللَّهِ ۚ إِنَّ ٱللَّهَ يَغْفِرُ ٱلذُّنُوبَ جَمِيعًا ۚ إِنَّهُۥ هُوَ ٱلْغَفُورُ ٱلرَّحِيمُ', 'قل يعبادى الذين أسرفوا على أنفسهم لا تقنطوا من رحمة الله  إن الله يغفر الذنوب جميعا  إنه هو الغفور الرحيم', NULL, 464, 'local:hafs-text.json'),
  ('hafs-39-54', 'hafs', 39, 54, 'وَأَنِيبُوٓا۟ إِلَىٰ رَبِّكُمْ وَأَسْلِمُوا۟ لَهُۥ مِن قَبْلِ أَن يَأْتِيَكُمُ ٱلْعَذَابُ ثُمَّ لَا تُنصَرُونَ', 'وأنيبوا إلى ربكم وأسلموا له من قبل أن يأتيكم العذاب ثم لا تنصرون', NULL, 464, 'local:hafs-text.json'),
  ('hafs-39-55', 'hafs', 39, 55, 'وَٱتَّبِعُوٓا۟ أَحْسَنَ مَآ أُنزِلَ إِلَيْكُم مِّن رَّبِّكُم مِّن قَبْلِ أَن يَأْتِيَكُمُ ٱلْعَذَابُ بَغْتَةًۭ وَأَنتُمْ لَا تَشْعُرُونَ', 'واتبعوا أحسن ما أنزل إليكم من ربكم من قبل أن يأتيكم العذاب بغتة وأنتم لا تشعرون', NULL, 464, 'local:hafs-text.json'),
  ('hafs-39-56', 'hafs', 39, 56, 'أَن تَقُولَ نَفْسٌۭ يَٰحَسْرَتَىٰ عَلَىٰ مَا فَرَّطتُ فِى جَنۢبِ ٱللَّهِ وَإِن كُنتُ لَمِنَ ٱلسَّٰخِرِينَ', 'أن تقول نفس يحسرتى على ما فرطت فى جنب الله وإن كنت لمن السخرين', NULL, 464, 'local:hafs-text.json'),
  ('hafs-39-57', 'hafs', 39, 57, 'أَوْ تَقُولَ لَوْ أَنَّ ٱللَّهَ هَدَىٰنِى لَكُنتُ مِنَ ٱلْمُتَّقِينَ', 'أو تقول لو أن الله هدىنى لكنت من المتقين', NULL, 465, 'local:hafs-text.json'),
  ('hafs-39-58', 'hafs', 39, 58, 'أَوْ تَقُولَ حِينَ تَرَى ٱلْعَذَابَ لَوْ أَنَّ لِى كَرَّةًۭ فَأَكُونَ مِنَ ٱلْمُحْسِنِينَ', 'أو تقول حين ترى العذاب لو أن لى كرة فأكون من المحسنين', NULL, 465, 'local:hafs-text.json'),
  ('hafs-39-59', 'hafs', 39, 59, 'بَلَىٰ قَدْ جَآءَتْكَ ءَايَٰتِى فَكَذَّبْتَ بِهَا وَٱسْتَكْبَرْتَ وَكُنتَ مِنَ ٱلْكَٰفِرِينَ', 'بلى قد جاءتك ءايتى فكذبت بها واستكبرت وكنت من الكفرين', NULL, 465, 'local:hafs-text.json'),
  ('hafs-39-60', 'hafs', 39, 60, 'وَيَوْمَ ٱلْقِيَٰمَةِ تَرَى ٱلَّذِينَ كَذَبُوا۟ عَلَى ٱللَّهِ وُجُوهُهُم مُّسْوَدَّةٌ ۚ أَلَيْسَ فِى جَهَنَّمَ مَثْوًۭى لِّلْمُتَكَبِّرِينَ', 'ويوم القيمة ترى الذين كذبوا على الله وجوههم مسودة  أليس فى جهنم مثوى للمتكبرين', NULL, 465, 'local:hafs-text.json'),
  ('hafs-39-61', 'hafs', 39, 61, 'وَيُنَجِّى ٱللَّهُ ٱلَّذِينَ ٱتَّقَوْا۟ بِمَفَازَتِهِمْ لَا يَمَسُّهُمُ ٱلسُّوٓءُ وَلَا هُمْ يَحْزَنُونَ', 'وينجى الله الذين اتقوا بمفازتهم لا يمسهم السوء ولا هم يحزنون', NULL, 465, 'local:hafs-text.json'),
  ('hafs-39-62', 'hafs', 39, 62, 'ٱللَّهُ خَٰلِقُ كُلِّ شَىْءٍۢ ۖ وَهُوَ عَلَىٰ كُلِّ شَىْءٍۢ وَكِيلٌۭ', 'الله خلق كل شىء  وهو على كل شىء وكيل', NULL, 465, 'local:hafs-text.json'),
  ('hafs-39-63', 'hafs', 39, 63, 'لَّهُۥ مَقَالِيدُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ ۗ وَٱلَّذِينَ كَفَرُوا۟ بِـَٔايَٰتِ ٱللَّهِ أُو۟لَٰٓئِكَ هُمُ ٱلْخَٰسِرُونَ', 'له مقاليد السموت والأرض  والذين كفروا بايت الله أولئك هم الخسرون', NULL, 465, 'local:hafs-text.json'),
  ('hafs-39-64', 'hafs', 39, 64, 'قُلْ أَفَغَيْرَ ٱللَّهِ تَأْمُرُوٓنِّىٓ أَعْبُدُ أَيُّهَا ٱلْجَٰهِلُونَ', 'قل أفغير الله تأمرونى أعبد أيها الجهلون', NULL, 465, 'local:hafs-text.json'),
  ('hafs-39-65', 'hafs', 39, 65, 'وَلَقَدْ أُوحِىَ إِلَيْكَ وَإِلَى ٱلَّذِينَ مِن قَبْلِكَ لَئِنْ أَشْرَكْتَ لَيَحْبَطَنَّ عَمَلُكَ وَلَتَكُونَنَّ مِنَ ٱلْخَٰسِرِينَ', 'ولقد أوحى إليك وإلى الذين من قبلك لئن أشركت ليحبطن عملك ولتكونن من الخسرين', NULL, 465, 'local:hafs-text.json'),
  ('hafs-39-66', 'hafs', 39, 66, 'بَلِ ٱللَّهَ فَٱعْبُدْ وَكُن مِّنَ ٱلشَّٰكِرِينَ', 'بل الله فاعبد وكن من الشكرين', NULL, 465, 'local:hafs-text.json'),
  ('hafs-39-67', 'hafs', 39, 67, 'وَمَا قَدَرُوا۟ ٱللَّهَ حَقَّ قَدْرِهِۦ وَٱلْأَرْضُ جَمِيعًۭا قَبْضَتُهُۥ يَوْمَ ٱلْقِيَٰمَةِ وَٱلسَّمَٰوَٰتُ مَطْوِيَّٰتٌۢ بِيَمِينِهِۦ ۚ سُبْحَٰنَهُۥ وَتَعَٰلَىٰ عَمَّا يُشْرِكُونَ', 'وما قدروا الله حق قدره والأرض جميعا قبضته يوم القيمة والسموت مطويت بيمينه  سبحنه وتعلى عما يشركون', NULL, 465, 'local:hafs-text.json'),
  ('hafs-39-68', 'hafs', 39, 68, 'وَنُفِخَ فِى ٱلصُّورِ فَصَعِقَ مَن فِى ٱلسَّمَٰوَٰتِ وَمَن فِى ٱلْأَرْضِ إِلَّا مَن شَآءَ ٱللَّهُ ۖ ثُمَّ نُفِخَ فِيهِ أُخْرَىٰ فَإِذَا هُمْ قِيَامٌۭ يَنظُرُونَ', 'ونفخ فى الصور فصعق من فى السموت ومن فى الأرض إلا من شاء الله  ثم نفخ فيه أخرى فإذا هم قيام ينظرون', NULL, 466, 'local:hafs-text.json'),
  ('hafs-39-69', 'hafs', 39, 69, 'وَأَشْرَقَتِ ٱلْأَرْضُ بِنُورِ رَبِّهَا وَوُضِعَ ٱلْكِتَٰبُ وَجِا۟ىٓءَ بِٱلنَّبِيِّۦنَ وَٱلشُّهَدَآءِ وَقُضِىَ بَيْنَهُم بِٱلْحَقِّ وَهُمْ لَا يُظْلَمُونَ', 'وأشرقت الأرض بنور ربها ووضع الكتب وجاىء بالنبين والشهداء وقضى بينهم بالحق وهم لا يظلمون', NULL, 466, 'local:hafs-text.json'),
  ('hafs-39-70', 'hafs', 39, 70, 'وَوُفِّيَتْ كُلُّ نَفْسٍۢ مَّا عَمِلَتْ وَهُوَ أَعْلَمُ بِمَا يَفْعَلُونَ', 'ووفيت كل نفس ما عملت وهو أعلم بما يفعلون', NULL, 466, 'local:hafs-text.json'),
  ('hafs-39-71', 'hafs', 39, 71, 'وَسِيقَ ٱلَّذِينَ كَفَرُوٓا۟ إِلَىٰ جَهَنَّمَ زُمَرًا ۖ حَتَّىٰٓ إِذَا جَآءُوهَا فُتِحَتْ أَبْوَٰبُهَا وَقَالَ لَهُمْ خَزَنَتُهَآ أَلَمْ يَأْتِكُمْ رُسُلٌۭ مِّنكُمْ يَتْلُونَ عَلَيْكُمْ ءَايَٰتِ رَبِّكُمْ وَيُنذِرُونَكُمْ لِقَآءَ يَوْمِكُمْ هَٰذَا ۚ قَالُوا۟ بَلَىٰ وَلَٰكِنْ حَقَّتْ كَلِمَةُ ٱلْعَذَابِ عَلَى ٱلْكَٰفِرِينَ', 'وسيق الذين كفروا إلى جهنم زمرا  حتى إذا جاءوها فتحت أبوبها وقال لهم خزنتها ألم يأتكم رسل منكم يتلون عليكم ءايت ربكم وينذرونكم لقاء يومكم هذا  قالوا بلى ولكن حقت كلمة العذاب على الكفرين', NULL, 466, 'local:hafs-text.json'),
  ('hafs-39-72', 'hafs', 39, 72, 'قِيلَ ٱدْخُلُوٓا۟ أَبْوَٰبَ جَهَنَّمَ خَٰلِدِينَ فِيهَا ۖ فَبِئْسَ مَثْوَى ٱلْمُتَكَبِّرِينَ', 'قيل ادخلوا أبوب جهنم خلدين فيها  فبئس مثوى المتكبرين', NULL, 466, 'local:hafs-text.json'),
  ('hafs-39-73', 'hafs', 39, 73, 'وَسِيقَ ٱلَّذِينَ ٱتَّقَوْا۟ رَبَّهُمْ إِلَى ٱلْجَنَّةِ زُمَرًا ۖ حَتَّىٰٓ إِذَا جَآءُوهَا وَفُتِحَتْ أَبْوَٰبُهَا وَقَالَ لَهُمْ خَزَنَتُهَا سَلَٰمٌ عَلَيْكُمْ طِبْتُمْ فَٱدْخُلُوهَا خَٰلِدِينَ', 'وسيق الذين اتقوا ربهم إلى الجنة زمرا  حتى إذا جاءوها وفتحت أبوبها وقال لهم خزنتها سلم عليكم طبتم فادخلوها خلدين', NULL, 466, 'local:hafs-text.json'),
  ('hafs-39-74', 'hafs', 39, 74, 'وَقَالُوا۟ ٱلْحَمْدُ لِلَّهِ ٱلَّذِى صَدَقَنَا وَعْدَهُۥ وَأَوْرَثَنَا ٱلْأَرْضَ نَتَبَوَّأُ مِنَ ٱلْجَنَّةِ حَيْثُ نَشَآءُ ۖ فَنِعْمَ أَجْرُ ٱلْعَٰمِلِينَ', 'وقالوا الحمد لله الذى صدقنا وعده وأورثنا الأرض نتبوأ من الجنة حيث نشاء  فنعم أجر العملين', NULL, 466, 'local:hafs-text.json'),
  ('hafs-39-75', 'hafs', 39, 75, 'وَتَرَى ٱلْمَلَٰٓئِكَةَ حَآفِّينَ مِنْ حَوْلِ ٱلْعَرْشِ يُسَبِّحُونَ بِحَمْدِ رَبِّهِمْ ۖ وَقُضِىَ بَيْنَهُم بِٱلْحَقِّ وَقِيلَ ٱلْحَمْدُ لِلَّهِ رَبِّ ٱلْعَٰلَمِينَ', 'وترى الملئكة حافين من حول العرش يسبحون بحمد ربهم  وقضى بينهم بالحق وقيل الحمد لله رب العلمين', NULL, 467, 'local:hafs-text.json'),
  ('hafs-40-1', 'hafs', 40, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ حمٓ', 'بسم الله الرحمن الرحيم حم', NULL, 467, 'local:hafs-text.json'),
  ('hafs-40-2', 'hafs', 40, 2, 'تَنزِيلُ ٱلْكِتَٰبِ مِنَ ٱللَّهِ ٱلْعَزِيزِ ٱلْعَلِيمِ', 'تنزيل الكتب من الله العزيز العليم', NULL, 467, 'local:hafs-text.json'),
  ('hafs-40-3', 'hafs', 40, 3, 'غَافِرِ ٱلذَّنۢبِ وَقَابِلِ ٱلتَّوْبِ شَدِيدِ ٱلْعِقَابِ ذِى ٱلطَّوْلِ ۖ لَآ إِلَٰهَ إِلَّا هُوَ ۖ إِلَيْهِ ٱلْمَصِيرُ', 'غافر الذنب وقابل التوب شديد العقاب ذى الطول  لا إله إلا هو  إليه المصير', NULL, 467, 'local:hafs-text.json'),
  ('hafs-40-4', 'hafs', 40, 4, 'مَا يُجَٰدِلُ فِىٓ ءَايَٰتِ ٱللَّهِ إِلَّا ٱلَّذِينَ كَفَرُوا۟ فَلَا يَغْرُرْكَ تَقَلُّبُهُمْ فِى ٱلْبِلَٰدِ', 'ما يجدل فى ءايت الله إلا الذين كفروا فلا يغررك تقلبهم فى البلد', NULL, 467, 'local:hafs-text.json'),
  ('hafs-40-5', 'hafs', 40, 5, 'كَذَّبَتْ قَبْلَهُمْ قَوْمُ نُوحٍۢ وَٱلْأَحْزَابُ مِنۢ بَعْدِهِمْ ۖ وَهَمَّتْ كُلُّ أُمَّةٍۭ بِرَسُولِهِمْ لِيَأْخُذُوهُ ۖ وَجَٰدَلُوا۟ بِٱلْبَٰطِلِ لِيُدْحِضُوا۟ بِهِ ٱلْحَقَّ فَأَخَذْتُهُمْ ۖ فَكَيْفَ كَانَ عِقَابِ', 'كذبت قبلهم قوم نوح والأحزاب من بعدهم  وهمت كل أمة برسولهم ليأخذوه  وجدلوا بالبطل ليدحضوا به الحق فأخذتهم  فكيف كان عقاب', NULL, 467, 'local:hafs-text.json'),
  ('hafs-40-6', 'hafs', 40, 6, 'وَكَذَٰلِكَ حَقَّتْ كَلِمَتُ رَبِّكَ عَلَى ٱلَّذِينَ كَفَرُوٓا۟ أَنَّهُمْ أَصْحَٰبُ ٱلنَّارِ', 'وكذلك حقت كلمت ربك على الذين كفروا أنهم أصحب النار', NULL, 467, 'local:hafs-text.json'),
  ('hafs-40-7', 'hafs', 40, 7, 'ٱلَّذِينَ يَحْمِلُونَ ٱلْعَرْشَ وَمَنْ حَوْلَهُۥ يُسَبِّحُونَ بِحَمْدِ رَبِّهِمْ وَيُؤْمِنُونَ بِهِۦ وَيَسْتَغْفِرُونَ لِلَّذِينَ ءَامَنُوا۟ رَبَّنَا وَسِعْتَ كُلَّ شَىْءٍۢ رَّحْمَةًۭ وَعِلْمًۭا فَٱغْفِرْ لِلَّذِينَ تَابُوا۟ وَٱتَّبَعُوا۟ سَبِيلَكَ وَقِهِمْ عَذَابَ ٱلْجَحِيمِ', 'الذين يحملون العرش ومن حوله يسبحون بحمد ربهم ويؤمنون به ويستغفرون للذين ءامنوا ربنا وسعت كل شىء رحمة وعلما فاغفر للذين تابوا واتبعوا سبيلك وقهم عذاب الجحيم', NULL, 467, 'local:hafs-text.json'),
  ('hafs-40-8', 'hafs', 40, 8, 'رَبَّنَا وَأَدْخِلْهُمْ جَنَّٰتِ عَدْنٍ ٱلَّتِى وَعَدتَّهُمْ وَمَن صَلَحَ مِنْ ءَابَآئِهِمْ وَأَزْوَٰجِهِمْ وَذُرِّيَّٰتِهِمْ ۚ إِنَّكَ أَنتَ ٱلْعَزِيزُ ٱلْحَكِيمُ', 'ربنا وأدخلهم جنت عدن التى وعدتهم ومن صلح من ءابائهم وأزوجهم وذريتهم  إنك أنت العزيز الحكيم', NULL, 468, 'local:hafs-text.json'),
  ('hafs-40-9', 'hafs', 40, 9, 'وَقِهِمُ ٱلسَّيِّـَٔاتِ ۚ وَمَن تَقِ ٱلسَّيِّـَٔاتِ يَوْمَئِذٍۢ فَقَدْ رَحِمْتَهُۥ ۚ وَذَٰلِكَ هُوَ ٱلْفَوْزُ ٱلْعَظِيمُ', 'وقهم السيات  ومن تق السيات يومئذ فقد رحمته  وذلك هو الفوز العظيم', NULL, 468, 'local:hafs-text.json'),
  ('hafs-40-10', 'hafs', 40, 10, 'إِنَّ ٱلَّذِينَ كَفَرُوا۟ يُنَادَوْنَ لَمَقْتُ ٱللَّهِ أَكْبَرُ مِن مَّقْتِكُمْ أَنفُسَكُمْ إِذْ تُدْعَوْنَ إِلَى ٱلْإِيمَٰنِ فَتَكْفُرُونَ', 'إن الذين كفروا ينادون لمقت الله أكبر من مقتكم أنفسكم إذ تدعون إلى الإيمن فتكفرون', NULL, 468, 'local:hafs-text.json'),
  ('hafs-40-11', 'hafs', 40, 11, 'قَالُوا۟ رَبَّنَآ أَمَتَّنَا ٱثْنَتَيْنِ وَأَحْيَيْتَنَا ٱثْنَتَيْنِ فَٱعْتَرَفْنَا بِذُنُوبِنَا فَهَلْ إِلَىٰ خُرُوجٍۢ مِّن سَبِيلٍۢ', 'قالوا ربنا أمتنا اثنتين وأحييتنا اثنتين فاعترفنا بذنوبنا فهل إلى خروج من سبيل', NULL, 468, 'local:hafs-text.json'),
  ('hafs-40-12', 'hafs', 40, 12, 'ذَٰلِكُم بِأَنَّهُۥٓ إِذَا دُعِىَ ٱللَّهُ وَحْدَهُۥ كَفَرْتُمْ ۖ وَإِن يُشْرَكْ بِهِۦ تُؤْمِنُوا۟ ۚ فَٱلْحُكْمُ لِلَّهِ ٱلْعَلِىِّ ٱلْكَبِيرِ', 'ذلكم بأنه إذا دعى الله وحده كفرتم  وإن يشرك به تؤمنوا  فالحكم لله العلى الكبير', NULL, 468, 'local:hafs-text.json'),
  ('hafs-40-13', 'hafs', 40, 13, 'هُوَ ٱلَّذِى يُرِيكُمْ ءَايَٰتِهِۦ وَيُنَزِّلُ لَكُم مِّنَ ٱلسَّمَآءِ رِزْقًۭا ۚ وَمَا يَتَذَكَّرُ إِلَّا مَن يُنِيبُ', 'هو الذى يريكم ءايته وينزل لكم من السماء رزقا  وما يتذكر إلا من ينيب', NULL, 468, 'local:hafs-text.json'),
  ('hafs-40-14', 'hafs', 40, 14, 'فَٱدْعُوا۟ ٱللَّهَ مُخْلِصِينَ لَهُ ٱلدِّينَ وَلَوْ كَرِهَ ٱلْكَٰفِرُونَ', 'فادعوا الله مخلصين له الدين ولو كره الكفرون', NULL, 468, 'local:hafs-text.json'),
  ('hafs-40-15', 'hafs', 40, 15, 'رَفِيعُ ٱلدَّرَجَٰتِ ذُو ٱلْعَرْشِ يُلْقِى ٱلرُّوحَ مِنْ أَمْرِهِۦ عَلَىٰ مَن يَشَآءُ مِنْ عِبَادِهِۦ لِيُنذِرَ يَوْمَ ٱلتَّلَاقِ', 'رفيع الدرجت ذو العرش يلقى الروح من أمره على من يشاء من عباده لينذر يوم التلاق', NULL, 468, 'local:hafs-text.json'),
  ('hafs-40-16', 'hafs', 40, 16, 'يَوْمَ هُم بَٰرِزُونَ ۖ لَا يَخْفَىٰ عَلَى ٱللَّهِ مِنْهُمْ شَىْءٌۭ ۚ لِّمَنِ ٱلْمُلْكُ ٱلْيَوْمَ ۖ لِلَّهِ ٱلْوَٰحِدِ ٱلْقَهَّارِ', 'يوم هم برزون  لا يخفى على الله منهم شىء  لمن الملك اليوم  لله الوحد القهار', NULL, 468, 'local:hafs-text.json'),
  ('hafs-40-17', 'hafs', 40, 17, 'ٱلْيَوْمَ تُجْزَىٰ كُلُّ نَفْسٍۭ بِمَا كَسَبَتْ ۚ لَا ظُلْمَ ٱلْيَوْمَ ۚ إِنَّ ٱللَّهَ سَرِيعُ ٱلْحِسَابِ', 'اليوم تجزى كل نفس بما كسبت  لا ظلم اليوم  إن الله سريع الحساب', NULL, 469, 'local:hafs-text.json'),
  ('hafs-40-18', 'hafs', 40, 18, 'وَأَنذِرْهُمْ يَوْمَ ٱلْءَازِفَةِ إِذِ ٱلْقُلُوبُ لَدَى ٱلْحَنَاجِرِ كَٰظِمِينَ ۚ مَا لِلظَّٰلِمِينَ مِنْ حَمِيمٍۢ وَلَا شَفِيعٍۢ يُطَاعُ', 'وأنذرهم يوم الءازفة إذ القلوب لدى الحناجر كظمين  ما للظلمين من حميم ولا شفيع يطاع', NULL, 469, 'local:hafs-text.json'),
  ('hafs-40-19', 'hafs', 40, 19, 'يَعْلَمُ خَآئِنَةَ ٱلْأَعْيُنِ وَمَا تُخْفِى ٱلصُّدُورُ', 'يعلم خائنة الأعين وما تخفى الصدور', NULL, 469, 'local:hafs-text.json'),
  ('hafs-40-20', 'hafs', 40, 20, 'وَٱللَّهُ يَقْضِى بِٱلْحَقِّ ۖ وَٱلَّذِينَ يَدْعُونَ مِن دُونِهِۦ لَا يَقْضُونَ بِشَىْءٍ ۗ إِنَّ ٱللَّهَ هُوَ ٱلسَّمِيعُ ٱلْبَصِيرُ', 'والله يقضى بالحق  والذين يدعون من دونه لا يقضون بشىء  إن الله هو السميع البصير', NULL, 469, 'local:hafs-text.json'),
  ('hafs-40-21', 'hafs', 40, 21, '۞ أَوَلَمْ يَسِيرُوا۟ فِى ٱلْأَرْضِ فَيَنظُرُوا۟ كَيْفَ كَانَ عَٰقِبَةُ ٱلَّذِينَ كَانُوا۟ مِن قَبْلِهِمْ ۚ كَانُوا۟ هُمْ أَشَدَّ مِنْهُمْ قُوَّةًۭ وَءَاثَارًۭا فِى ٱلْأَرْضِ فَأَخَذَهُمُ ٱللَّهُ بِذُنُوبِهِمْ وَمَا كَانَ لَهُم مِّنَ ٱللَّهِ مِن وَاقٍۢ', 'أولم يسيروا فى الأرض فينظروا كيف كان عقبة الذين كانوا من قبلهم  كانوا هم أشد منهم قوة وءاثارا فى الأرض فأخذهم الله بذنوبهم وما كان لهم من الله من واق', NULL, 469, 'local:hafs-text.json'),
  ('hafs-40-22', 'hafs', 40, 22, 'ذَٰلِكَ بِأَنَّهُمْ كَانَت تَّأْتِيهِمْ رُسُلُهُم بِٱلْبَيِّنَٰتِ فَكَفَرُوا۟ فَأَخَذَهُمُ ٱللَّهُ ۚ إِنَّهُۥ قَوِىٌّۭ شَدِيدُ ٱلْعِقَابِ', 'ذلك بأنهم كانت تأتيهم رسلهم بالبينت فكفروا فأخذهم الله  إنه قوى شديد العقاب', NULL, 469, 'local:hafs-text.json'),
  ('hafs-40-23', 'hafs', 40, 23, 'وَلَقَدْ أَرْسَلْنَا مُوسَىٰ بِـَٔايَٰتِنَا وَسُلْطَٰنٍۢ مُّبِينٍ', 'ولقد أرسلنا موسى بايتنا وسلطن مبين', NULL, 469, 'local:hafs-text.json'),
  ('hafs-40-24', 'hafs', 40, 24, 'إِلَىٰ فِرْعَوْنَ وَهَٰمَٰنَ وَقَٰرُونَ فَقَالُوا۟ سَٰحِرٌۭ كَذَّابٌۭ', 'إلى فرعون وهمن وقرون فقالوا سحر كذاب', NULL, 469, 'local:hafs-text.json'),
  ('hafs-40-25', 'hafs', 40, 25, 'فَلَمَّا جَآءَهُم بِٱلْحَقِّ مِنْ عِندِنَا قَالُوا۟ ٱقْتُلُوٓا۟ أَبْنَآءَ ٱلَّذِينَ ءَامَنُوا۟ مَعَهُۥ وَٱسْتَحْيُوا۟ نِسَآءَهُمْ ۚ وَمَا كَيْدُ ٱلْكَٰفِرِينَ إِلَّا فِى ضَلَٰلٍۢ', 'فلما جاءهم بالحق من عندنا قالوا اقتلوا أبناء الذين ءامنوا معه واستحيوا نساءهم  وما كيد الكفرين إلا فى ضلل', NULL, 469, 'local:hafs-text.json'),
  ('hafs-40-26', 'hafs', 40, 26, 'وَقَالَ فِرْعَوْنُ ذَرُونِىٓ أَقْتُلْ مُوسَىٰ وَلْيَدْعُ رَبَّهُۥٓ ۖ إِنِّىٓ أَخَافُ أَن يُبَدِّلَ دِينَكُمْ أَوْ أَن يُظْهِرَ فِى ٱلْأَرْضِ ٱلْفَسَادَ', 'وقال فرعون ذرونى أقتل موسى وليدع ربه  إنى أخاف أن يبدل دينكم أو أن يظهر فى الأرض الفساد', NULL, 470, 'local:hafs-text.json'),
  ('hafs-40-27', 'hafs', 40, 27, 'وَقَالَ مُوسَىٰٓ إِنِّى عُذْتُ بِرَبِّى وَرَبِّكُم مِّن كُلِّ مُتَكَبِّرٍۢ لَّا يُؤْمِنُ بِيَوْمِ ٱلْحِسَابِ', 'وقال موسى إنى عذت بربى وربكم من كل متكبر لا يؤمن بيوم الحساب', NULL, 470, 'local:hafs-text.json'),
  ('hafs-40-28', 'hafs', 40, 28, 'وَقَالَ رَجُلٌۭ مُّؤْمِنٌۭ مِّنْ ءَالِ فِرْعَوْنَ يَكْتُمُ إِيمَٰنَهُۥٓ أَتَقْتُلُونَ رَجُلًا أَن يَقُولَ رَبِّىَ ٱللَّهُ وَقَدْ جَآءَكُم بِٱلْبَيِّنَٰتِ مِن رَّبِّكُمْ ۖ وَإِن يَكُ كَٰذِبًۭا فَعَلَيْهِ كَذِبُهُۥ ۖ وَإِن يَكُ صَادِقًۭا يُصِبْكُم بَعْضُ ٱلَّذِى يَعِدُكُمْ ۖ إِنَّ ٱللَّهَ لَا يَهْدِى مَنْ هُوَ مُسْرِفٌۭ كَذَّابٌۭ', 'وقال رجل مؤمن من ءال فرعون يكتم إيمنه أتقتلون رجلا أن يقول ربى الله وقد جاءكم بالبينت من ربكم  وإن يك كذبا فعليه كذبه  وإن يك صادقا يصبكم بعض الذى يعدكم  إن الله لا يهدى من هو مسرف كذاب', NULL, 470, 'local:hafs-text.json'),
  ('hafs-40-29', 'hafs', 40, 29, 'يَٰقَوْمِ لَكُمُ ٱلْمُلْكُ ٱلْيَوْمَ ظَٰهِرِينَ فِى ٱلْأَرْضِ فَمَن يَنصُرُنَا مِنۢ بَأْسِ ٱللَّهِ إِن جَآءَنَا ۚ قَالَ فِرْعَوْنُ مَآ أُرِيكُمْ إِلَّا مَآ أَرَىٰ وَمَآ أَهْدِيكُمْ إِلَّا سَبِيلَ ٱلرَّشَادِ', 'يقوم لكم الملك اليوم ظهرين فى الأرض فمن ينصرنا من بأس الله إن جاءنا  قال فرعون ما أريكم إلا ما أرى وما أهديكم إلا سبيل الرشاد', NULL, 470, 'local:hafs-text.json'),
  ('hafs-40-30', 'hafs', 40, 30, 'وَقَالَ ٱلَّذِىٓ ءَامَنَ يَٰقَوْمِ إِنِّىٓ أَخَافُ عَلَيْكُم مِّثْلَ يَوْمِ ٱلْأَحْزَابِ', 'وقال الذى ءامن يقوم إنى أخاف عليكم مثل يوم الأحزاب', NULL, 470, 'local:hafs-text.json'),
  ('hafs-40-31', 'hafs', 40, 31, 'مِثْلَ دَأْبِ قَوْمِ نُوحٍۢ وَعَادٍۢ وَثَمُودَ وَٱلَّذِينَ مِنۢ بَعْدِهِمْ ۚ وَمَا ٱللَّهُ يُرِيدُ ظُلْمًۭا لِّلْعِبَادِ', 'مثل دأب قوم نوح وعاد وثمود والذين من بعدهم  وما الله يريد ظلما للعباد', NULL, 470, 'local:hafs-text.json'),
  ('hafs-40-32', 'hafs', 40, 32, 'وَيَٰقَوْمِ إِنِّىٓ أَخَافُ عَلَيْكُمْ يَوْمَ ٱلتَّنَادِ', 'ويقوم إنى أخاف عليكم يوم التناد', NULL, 470, 'local:hafs-text.json'),
  ('hafs-40-33', 'hafs', 40, 33, 'يَوْمَ تُوَلُّونَ مُدْبِرِينَ مَا لَكُم مِّنَ ٱللَّهِ مِنْ عَاصِمٍۢ ۗ وَمَن يُضْلِلِ ٱللَّهُ فَمَا لَهُۥ مِنْ هَادٍۢ', 'يوم تولون مدبرين ما لكم من الله من عاصم  ومن يضلل الله فما له من هاد', NULL, 470, 'local:hafs-text.json'),
  ('hafs-40-34', 'hafs', 40, 34, 'وَلَقَدْ جَآءَكُمْ يُوسُفُ مِن قَبْلُ بِٱلْبَيِّنَٰتِ فَمَا زِلْتُمْ فِى شَكٍّۢ مِّمَّا جَآءَكُم بِهِۦ ۖ حَتَّىٰٓ إِذَا هَلَكَ قُلْتُمْ لَن يَبْعَثَ ٱللَّهُ مِنۢ بَعْدِهِۦ رَسُولًۭا ۚ كَذَٰلِكَ يُضِلُّ ٱللَّهُ مَنْ هُوَ مُسْرِفٌۭ مُّرْتَابٌ', 'ولقد جاءكم يوسف من قبل بالبينت فما زلتم فى شك مما جاءكم به  حتى إذا هلك قلتم لن يبعث الله من بعده رسولا  كذلك يضل الله من هو مسرف مرتاب', NULL, 471, 'local:hafs-text.json'),
  ('hafs-40-35', 'hafs', 40, 35, 'ٱلَّذِينَ يُجَٰدِلُونَ فِىٓ ءَايَٰتِ ٱللَّهِ بِغَيْرِ سُلْطَٰنٍ أَتَىٰهُمْ ۖ كَبُرَ مَقْتًا عِندَ ٱللَّهِ وَعِندَ ٱلَّذِينَ ءَامَنُوا۟ ۚ كَذَٰلِكَ يَطْبَعُ ٱللَّهُ عَلَىٰ كُلِّ قَلْبِ مُتَكَبِّرٍۢ جَبَّارٍۢ', 'الذين يجدلون فى ءايت الله بغير سلطن أتىهم  كبر مقتا عند الله وعند الذين ءامنوا  كذلك يطبع الله على كل قلب متكبر جبار', NULL, 471, 'local:hafs-text.json'),
  ('hafs-40-36', 'hafs', 40, 36, 'وَقَالَ فِرْعَوْنُ يَٰهَٰمَٰنُ ٱبْنِ لِى صَرْحًۭا لَّعَلِّىٓ أَبْلُغُ ٱلْأَسْبَٰبَ', 'وقال فرعون يهمن ابن لى صرحا لعلى أبلغ الأسبب', NULL, 471, 'local:hafs-text.json'),
  ('hafs-40-37', 'hafs', 40, 37, 'أَسْبَٰبَ ٱلسَّمَٰوَٰتِ فَأَطَّلِعَ إِلَىٰٓ إِلَٰهِ مُوسَىٰ وَإِنِّى لَأَظُنُّهُۥ كَٰذِبًۭا ۚ وَكَذَٰلِكَ زُيِّنَ لِفِرْعَوْنَ سُوٓءُ عَمَلِهِۦ وَصُدَّ عَنِ ٱلسَّبِيلِ ۚ وَمَا كَيْدُ فِرْعَوْنَ إِلَّا فِى تَبَابٍۢ', 'أسبب السموت فأطلع إلى إله موسى وإنى لأظنه كذبا  وكذلك زين لفرعون سوء عمله وصد عن السبيل  وما كيد فرعون إلا فى تباب', NULL, 471, 'local:hafs-text.json'),
  ('hafs-40-38', 'hafs', 40, 38, 'وَقَالَ ٱلَّذِىٓ ءَامَنَ يَٰقَوْمِ ٱتَّبِعُونِ أَهْدِكُمْ سَبِيلَ ٱلرَّشَادِ', 'وقال الذى ءامن يقوم اتبعون أهدكم سبيل الرشاد', NULL, 471, 'local:hafs-text.json'),
  ('hafs-40-39', 'hafs', 40, 39, 'يَٰقَوْمِ إِنَّمَا هَٰذِهِ ٱلْحَيَوٰةُ ٱلدُّنْيَا مَتَٰعٌۭ وَإِنَّ ٱلْءَاخِرَةَ هِىَ دَارُ ٱلْقَرَارِ', 'يقوم إنما هذه الحيوة الدنيا متع وإن الءاخرة هى دار القرار', NULL, 471, 'local:hafs-text.json'),
  ('hafs-40-40', 'hafs', 40, 40, 'مَنْ عَمِلَ سَيِّئَةًۭ فَلَا يُجْزَىٰٓ إِلَّا مِثْلَهَا ۖ وَمَنْ عَمِلَ صَٰلِحًۭا مِّن ذَكَرٍ أَوْ أُنثَىٰ وَهُوَ مُؤْمِنٌۭ فَأُو۟لَٰٓئِكَ يَدْخُلُونَ ٱلْجَنَّةَ يُرْزَقُونَ فِيهَا بِغَيْرِ حِسَابٍۢ', 'من عمل سيئة فلا يجزى إلا مثلها  ومن عمل صلحا من ذكر أو أنثى وهو مؤمن فأولئك يدخلون الجنة يرزقون فيها بغير حساب', NULL, 471, 'local:hafs-text.json'),
  ('hafs-40-41', 'hafs', 40, 41, '۞ وَيَٰقَوْمِ مَا لِىٓ أَدْعُوكُمْ إِلَى ٱلنَّجَوٰةِ وَتَدْعُونَنِىٓ إِلَى ٱلنَّارِ', 'ويقوم ما لى أدعوكم إلى النجوة وتدعوننى إلى النار', NULL, 472, 'local:hafs-text.json'),
  ('hafs-40-42', 'hafs', 40, 42, 'تَدْعُونَنِى لِأَكْفُرَ بِٱللَّهِ وَأُشْرِكَ بِهِۦ مَا لَيْسَ لِى بِهِۦ عِلْمٌۭ وَأَنَا۠ أَدْعُوكُمْ إِلَى ٱلْعَزِيزِ ٱلْغَفَّٰرِ', 'تدعوننى لأكفر بالله وأشرك به ما ليس لى به علم وأنا أدعوكم إلى العزيز الغفر', NULL, 472, 'local:hafs-text.json'),
  ('hafs-40-43', 'hafs', 40, 43, 'لَا جَرَمَ أَنَّمَا تَدْعُونَنِىٓ إِلَيْهِ لَيْسَ لَهُۥ دَعْوَةٌۭ فِى ٱلدُّنْيَا وَلَا فِى ٱلْءَاخِرَةِ وَأَنَّ مَرَدَّنَآ إِلَى ٱللَّهِ وَأَنَّ ٱلْمُسْرِفِينَ هُمْ أَصْحَٰبُ ٱلنَّارِ', 'لا جرم أنما تدعوننى إليه ليس له دعوة فى الدنيا ولا فى الءاخرة وأن مردنا إلى الله وأن المسرفين هم أصحب النار', NULL, 472, 'local:hafs-text.json'),
  ('hafs-40-44', 'hafs', 40, 44, 'فَسَتَذْكُرُونَ مَآ أَقُولُ لَكُمْ ۚ وَأُفَوِّضُ أَمْرِىٓ إِلَى ٱللَّهِ ۚ إِنَّ ٱللَّهَ بَصِيرٌۢ بِٱلْعِبَادِ', 'فستذكرون ما أقول لكم  وأفوض أمرى إلى الله  إن الله بصير بالعباد', NULL, 472, 'local:hafs-text.json'),
  ('hafs-40-45', 'hafs', 40, 45, 'فَوَقَىٰهُ ٱللَّهُ سَيِّـَٔاتِ مَا مَكَرُوا۟ ۖ وَحَاقَ بِـَٔالِ فِرْعَوْنَ سُوٓءُ ٱلْعَذَابِ', 'فوقىه الله سيات ما مكروا  وحاق بال فرعون سوء العذاب', NULL, 472, 'local:hafs-text.json'),
  ('hafs-40-46', 'hafs', 40, 46, 'ٱلنَّارُ يُعْرَضُونَ عَلَيْهَا غُدُوًّۭا وَعَشِيًّۭا ۖ وَيَوْمَ تَقُومُ ٱلسَّاعَةُ أَدْخِلُوٓا۟ ءَالَ فِرْعَوْنَ أَشَدَّ ٱلْعَذَابِ', 'النار يعرضون عليها غدوا وعشيا  ويوم تقوم الساعة أدخلوا ءال فرعون أشد العذاب', NULL, 472, 'local:hafs-text.json'),
  ('hafs-40-47', 'hafs', 40, 47, 'وَإِذْ يَتَحَآجُّونَ فِى ٱلنَّارِ فَيَقُولُ ٱلضُّعَفَٰٓؤُا۟ لِلَّذِينَ ٱسْتَكْبَرُوٓا۟ إِنَّا كُنَّا لَكُمْ تَبَعًۭا فَهَلْ أَنتُم مُّغْنُونَ عَنَّا نَصِيبًۭا مِّنَ ٱلنَّارِ', 'وإذ يتحاجون فى النار فيقول الضعفؤا للذين استكبروا إنا كنا لكم تبعا فهل أنتم مغنون عنا نصيبا من النار', NULL, 472, 'local:hafs-text.json'),
  ('hafs-40-48', 'hafs', 40, 48, 'قَالَ ٱلَّذِينَ ٱسْتَكْبَرُوٓا۟ إِنَّا كُلٌّۭ فِيهَآ إِنَّ ٱللَّهَ قَدْ حَكَمَ بَيْنَ ٱلْعِبَادِ', 'قال الذين استكبروا إنا كل فيها إن الله قد حكم بين العباد', NULL, 472, 'local:hafs-text.json'),
  ('hafs-40-49', 'hafs', 40, 49, 'وَقَالَ ٱلَّذِينَ فِى ٱلنَّارِ لِخَزَنَةِ جَهَنَّمَ ٱدْعُوا۟ رَبَّكُمْ يُخَفِّفْ عَنَّا يَوْمًۭا مِّنَ ٱلْعَذَابِ', 'وقال الذين فى النار لخزنة جهنم ادعوا ربكم يخفف عنا يوما من العذاب', NULL, 472, 'local:hafs-text.json'),
  ('hafs-40-50', 'hafs', 40, 50, 'قَالُوٓا۟ أَوَلَمْ تَكُ تَأْتِيكُمْ رُسُلُكُم بِٱلْبَيِّنَٰتِ ۖ قَالُوا۟ بَلَىٰ ۚ قَالُوا۟ فَٱدْعُوا۟ ۗ وَمَا دُعَٰٓؤُا۟ ٱلْكَٰفِرِينَ إِلَّا فِى ضَلَٰلٍ', 'قالوا أولم تك تأتيكم رسلكم بالبينت  قالوا بلى  قالوا فادعوا  وما دعؤا الكفرين إلا فى ضلل', NULL, 473, 'local:hafs-text.json'),
  ('hafs-40-51', 'hafs', 40, 51, 'إِنَّا لَنَنصُرُ رُسُلَنَا وَٱلَّذِينَ ءَامَنُوا۟ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا وَيَوْمَ يَقُومُ ٱلْأَشْهَٰدُ', 'إنا لننصر رسلنا والذين ءامنوا فى الحيوة الدنيا ويوم يقوم الأشهد', NULL, 473, 'local:hafs-text.json'),
  ('hafs-40-52', 'hafs', 40, 52, 'يَوْمَ لَا يَنفَعُ ٱلظَّٰلِمِينَ مَعْذِرَتُهُمْ ۖ وَلَهُمُ ٱللَّعْنَةُ وَلَهُمْ سُوٓءُ ٱلدَّارِ', 'يوم لا ينفع الظلمين معذرتهم  ولهم اللعنة ولهم سوء الدار', NULL, 473, 'local:hafs-text.json'),
  ('hafs-40-53', 'hafs', 40, 53, 'وَلَقَدْ ءَاتَيْنَا مُوسَى ٱلْهُدَىٰ وَأَوْرَثْنَا بَنِىٓ إِسْرَٰٓءِيلَ ٱلْكِتَٰبَ', 'ولقد ءاتينا موسى الهدى وأورثنا بنى إسرءيل الكتب', NULL, 473, 'local:hafs-text.json'),
  ('hafs-40-54', 'hafs', 40, 54, 'هُدًۭى وَذِكْرَىٰ لِأُو۟لِى ٱلْأَلْبَٰبِ', 'هدى وذكرى لأولى الألبب', NULL, 473, 'local:hafs-text.json'),
  ('hafs-40-55', 'hafs', 40, 55, 'فَٱصْبِرْ إِنَّ وَعْدَ ٱللَّهِ حَقٌّۭ وَٱسْتَغْفِرْ لِذَنۢبِكَ وَسَبِّحْ بِحَمْدِ رَبِّكَ بِٱلْعَشِىِّ وَٱلْإِبْكَٰرِ', 'فاصبر إن وعد الله حق واستغفر لذنبك وسبح بحمد ربك بالعشى والإبكر', NULL, 473, 'local:hafs-text.json'),
  ('hafs-40-56', 'hafs', 40, 56, 'إِنَّ ٱلَّذِينَ يُجَٰدِلُونَ فِىٓ ءَايَٰتِ ٱللَّهِ بِغَيْرِ سُلْطَٰنٍ أَتَىٰهُمْ ۙ إِن فِى صُدُورِهِمْ إِلَّا كِبْرٌۭ مَّا هُم بِبَٰلِغِيهِ ۚ فَٱسْتَعِذْ بِٱللَّهِ ۖ إِنَّهُۥ هُوَ ٱلسَّمِيعُ ٱلْبَصِيرُ', 'إن الذين يجدلون فى ءايت الله بغير سلطن أتىهم  إن فى صدورهم إلا كبر ما هم ببلغيه  فاستعذ بالله  إنه هو السميع البصير', NULL, 473, 'local:hafs-text.json'),
  ('hafs-40-57', 'hafs', 40, 57, 'لَخَلْقُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ أَكْبَرُ مِنْ خَلْقِ ٱلنَّاسِ وَلَٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يَعْلَمُونَ', 'لخلق السموت والأرض أكبر من خلق الناس ولكن أكثر الناس لا يعلمون', NULL, 473, 'local:hafs-text.json'),
  ('hafs-40-58', 'hafs', 40, 58, 'وَمَا يَسْتَوِى ٱلْأَعْمَىٰ وَٱلْبَصِيرُ وَٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ وَلَا ٱلْمُسِىٓءُ ۚ قَلِيلًۭا مَّا تَتَذَكَّرُونَ', 'وما يستوى الأعمى والبصير والذين ءامنوا وعملوا الصلحت ولا المسىء  قليلا ما تتذكرون', NULL, 473, 'local:hafs-text.json'),
  ('hafs-40-59', 'hafs', 40, 59, 'إِنَّ ٱلسَّاعَةَ لَءَاتِيَةٌۭ لَّا رَيْبَ فِيهَا وَلَٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يُؤْمِنُونَ', 'إن الساعة لءاتية لا ريب فيها ولكن أكثر الناس لا يؤمنون', NULL, 474, 'local:hafs-text.json'),
  ('hafs-40-60', 'hafs', 40, 60, 'وَقَالَ رَبُّكُمُ ٱدْعُونِىٓ أَسْتَجِبْ لَكُمْ ۚ إِنَّ ٱلَّذِينَ يَسْتَكْبِرُونَ عَنْ عِبَادَتِى سَيَدْخُلُونَ جَهَنَّمَ دَاخِرِينَ', 'وقال ربكم ادعونى أستجب لكم  إن الذين يستكبرون عن عبادتى سيدخلون جهنم داخرين', NULL, 474, 'local:hafs-text.json'),
  ('hafs-40-61', 'hafs', 40, 61, 'ٱللَّهُ ٱلَّذِى جَعَلَ لَكُمُ ٱلَّيْلَ لِتَسْكُنُوا۟ فِيهِ وَٱلنَّهَارَ مُبْصِرًا ۚ إِنَّ ٱللَّهَ لَذُو فَضْلٍ عَلَى ٱلنَّاسِ وَلَٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يَشْكُرُونَ', 'الله الذى جعل لكم اليل لتسكنوا فيه والنهار مبصرا  إن الله لذو فضل على الناس ولكن أكثر الناس لا يشكرون', NULL, 474, 'local:hafs-text.json'),
  ('hafs-40-62', 'hafs', 40, 62, 'ذَٰلِكُمُ ٱللَّهُ رَبُّكُمْ خَٰلِقُ كُلِّ شَىْءٍۢ لَّآ إِلَٰهَ إِلَّا هُوَ ۖ فَأَنَّىٰ تُؤْفَكُونَ', 'ذلكم الله ربكم خلق كل شىء لا إله إلا هو  فأنى تؤفكون', NULL, 474, 'local:hafs-text.json'),
  ('hafs-40-63', 'hafs', 40, 63, 'كَذَٰلِكَ يُؤْفَكُ ٱلَّذِينَ كَانُوا۟ بِـَٔايَٰتِ ٱللَّهِ يَجْحَدُونَ', 'كذلك يؤفك الذين كانوا بايت الله يجحدون', NULL, 474, 'local:hafs-text.json'),
  ('hafs-40-64', 'hafs', 40, 64, 'ٱللَّهُ ٱلَّذِى جَعَلَ لَكُمُ ٱلْأَرْضَ قَرَارًۭا وَٱلسَّمَآءَ بِنَآءًۭ وَصَوَّرَكُمْ فَأَحْسَنَ صُوَرَكُمْ وَرَزَقَكُم مِّنَ ٱلطَّيِّبَٰتِ ۚ ذَٰلِكُمُ ٱللَّهُ رَبُّكُمْ ۖ فَتَبَارَكَ ٱللَّهُ رَبُّ ٱلْعَٰلَمِينَ', 'الله الذى جعل لكم الأرض قرارا والسماء بناء وصوركم فأحسن صوركم ورزقكم من الطيبت  ذلكم الله ربكم  فتبارك الله رب العلمين', NULL, 474, 'local:hafs-text.json'),
  ('hafs-40-65', 'hafs', 40, 65, 'هُوَ ٱلْحَىُّ لَآ إِلَٰهَ إِلَّا هُوَ فَٱدْعُوهُ مُخْلِصِينَ لَهُ ٱلدِّينَ ۗ ٱلْحَمْدُ لِلَّهِ رَبِّ ٱلْعَٰلَمِينَ', 'هو الحى لا إله إلا هو فادعوه مخلصين له الدين  الحمد لله رب العلمين', NULL, 474, 'local:hafs-text.json'),
  ('hafs-40-66', 'hafs', 40, 66, '۞ قُلْ إِنِّى نُهِيتُ أَنْ أَعْبُدَ ٱلَّذِينَ تَدْعُونَ مِن دُونِ ٱللَّهِ لَمَّا جَآءَنِىَ ٱلْبَيِّنَٰتُ مِن رَّبِّى وَأُمِرْتُ أَنْ أُسْلِمَ لِرَبِّ ٱلْعَٰلَمِينَ', 'قل إنى نهيت أن أعبد الذين تدعون من دون الله لما جاءنى البينت من ربى وأمرت أن أسلم لرب العلمين', NULL, 474, 'local:hafs-text.json'),
  ('hafs-40-67', 'hafs', 40, 67, 'هُوَ ٱلَّذِى خَلَقَكُم مِّن تُرَابٍۢ ثُمَّ مِن نُّطْفَةٍۢ ثُمَّ مِنْ عَلَقَةٍۢ ثُمَّ يُخْرِجُكُمْ طِفْلًۭا ثُمَّ لِتَبْلُغُوٓا۟ أَشُدَّكُمْ ثُمَّ لِتَكُونُوا۟ شُيُوخًۭا ۚ وَمِنكُم مَّن يُتَوَفَّىٰ مِن قَبْلُ ۖ وَلِتَبْلُغُوٓا۟ أَجَلًۭا مُّسَمًّۭى وَلَعَلَّكُمْ تَعْقِلُونَ', 'هو الذى خلقكم من تراب ثم من نطفة ثم من علقة ثم يخرجكم طفلا ثم لتبلغوا أشدكم ثم لتكونوا شيوخا  ومنكم من يتوفى من قبل  ولتبلغوا أجلا مسمى ولعلكم تعقلون', NULL, 475, 'local:hafs-text.json'),
  ('hafs-40-68', 'hafs', 40, 68, 'هُوَ ٱلَّذِى يُحْىِۦ وَيُمِيتُ ۖ فَإِذَا قَضَىٰٓ أَمْرًۭا فَإِنَّمَا يَقُولُ لَهُۥ كُن فَيَكُونُ', 'هو الذى يحى ويميت  فإذا قضى أمرا فإنما يقول له كن فيكون', NULL, 475, 'local:hafs-text.json'),
  ('hafs-40-69', 'hafs', 40, 69, 'أَلَمْ تَرَ إِلَى ٱلَّذِينَ يُجَٰدِلُونَ فِىٓ ءَايَٰتِ ٱللَّهِ أَنَّىٰ يُصْرَفُونَ', 'ألم تر إلى الذين يجدلون فى ءايت الله أنى يصرفون', NULL, 475, 'local:hafs-text.json'),
  ('hafs-40-70', 'hafs', 40, 70, 'ٱلَّذِينَ كَذَّبُوا۟ بِٱلْكِتَٰبِ وَبِمَآ أَرْسَلْنَا بِهِۦ رُسُلَنَا ۖ فَسَوْفَ يَعْلَمُونَ', 'الذين كذبوا بالكتب وبما أرسلنا به رسلنا  فسوف يعلمون', NULL, 475, 'local:hafs-text.json'),
  ('hafs-40-71', 'hafs', 40, 71, 'إِذِ ٱلْأَغْلَٰلُ فِىٓ أَعْنَٰقِهِمْ وَٱلسَّلَٰسِلُ يُسْحَبُونَ', 'إذ الأغلل فى أعنقهم والسلسل يسحبون', NULL, 475, 'local:hafs-text.json'),
  ('hafs-40-72', 'hafs', 40, 72, 'فِى ٱلْحَمِيمِ ثُمَّ فِى ٱلنَّارِ يُسْجَرُونَ', 'فى الحميم ثم فى النار يسجرون', NULL, 475, 'local:hafs-text.json'),
  ('hafs-40-73', 'hafs', 40, 73, 'ثُمَّ قِيلَ لَهُمْ أَيْنَ مَا كُنتُمْ تُشْرِكُونَ', 'ثم قيل لهم أين ما كنتم تشركون', NULL, 475, 'local:hafs-text.json'),
  ('hafs-40-74', 'hafs', 40, 74, 'مِن دُونِ ٱللَّهِ ۖ قَالُوا۟ ضَلُّوا۟ عَنَّا بَل لَّمْ نَكُن نَّدْعُوا۟ مِن قَبْلُ شَيْـًۭٔا ۚ كَذَٰلِكَ يُضِلُّ ٱللَّهُ ٱلْكَٰفِرِينَ', 'من دون الله  قالوا ضلوا عنا بل لم نكن ندعوا من قبل شيا  كذلك يضل الله الكفرين', NULL, 475, 'local:hafs-text.json'),
  ('hafs-40-75', 'hafs', 40, 75, 'ذَٰلِكُم بِمَا كُنتُمْ تَفْرَحُونَ فِى ٱلْأَرْضِ بِغَيْرِ ٱلْحَقِّ وَبِمَا كُنتُمْ تَمْرَحُونَ', 'ذلكم بما كنتم تفرحون فى الأرض بغير الحق وبما كنتم تمرحون', NULL, 475, 'local:hafs-text.json'),
  ('hafs-40-76', 'hafs', 40, 76, 'ٱدْخُلُوٓا۟ أَبْوَٰبَ جَهَنَّمَ خَٰلِدِينَ فِيهَا ۖ فَبِئْسَ مَثْوَى ٱلْمُتَكَبِّرِينَ', 'ادخلوا أبوب جهنم خلدين فيها  فبئس مثوى المتكبرين', NULL, 475, 'local:hafs-text.json'),
  ('hafs-40-77', 'hafs', 40, 77, 'فَٱصْبِرْ إِنَّ وَعْدَ ٱللَّهِ حَقٌّۭ ۚ فَإِمَّا نُرِيَنَّكَ بَعْضَ ٱلَّذِى نَعِدُهُمْ أَوْ نَتَوَفَّيَنَّكَ فَإِلَيْنَا يُرْجَعُونَ', 'فاصبر إن وعد الله حق  فإما نرينك بعض الذى نعدهم أو نتوفينك فإلينا يرجعون', NULL, 475, 'local:hafs-text.json'),
  ('hafs-40-78', 'hafs', 40, 78, 'وَلَقَدْ أَرْسَلْنَا رُسُلًۭا مِّن قَبْلِكَ مِنْهُم مَّن قَصَصْنَا عَلَيْكَ وَمِنْهُم مَّن لَّمْ نَقْصُصْ عَلَيْكَ ۗ وَمَا كَانَ لِرَسُولٍ أَن يَأْتِىَ بِـَٔايَةٍ إِلَّا بِإِذْنِ ٱللَّهِ ۚ فَإِذَا جَآءَ أَمْرُ ٱللَّهِ قُضِىَ بِٱلْحَقِّ وَخَسِرَ هُنَالِكَ ٱلْمُبْطِلُونَ', 'ولقد أرسلنا رسلا من قبلك منهم من قصصنا عليك ومنهم من لم نقصص عليك  وما كان لرسول أن يأتى باية إلا بإذن الله  فإذا جاء أمر الله قضى بالحق وخسر هنالك المبطلون', NULL, 476, 'local:hafs-text.json'),
  ('hafs-40-79', 'hafs', 40, 79, 'ٱللَّهُ ٱلَّذِى جَعَلَ لَكُمُ ٱلْأَنْعَٰمَ لِتَرْكَبُوا۟ مِنْهَا وَمِنْهَا تَأْكُلُونَ', 'الله الذى جعل لكم الأنعم لتركبوا منها ومنها تأكلون', NULL, 476, 'local:hafs-text.json'),
  ('hafs-40-80', 'hafs', 40, 80, 'وَلَكُمْ فِيهَا مَنَٰفِعُ وَلِتَبْلُغُوا۟ عَلَيْهَا حَاجَةًۭ فِى صُدُورِكُمْ وَعَلَيْهَا وَعَلَى ٱلْفُلْكِ تُحْمَلُونَ', 'ولكم فيها منفع ولتبلغوا عليها حاجة فى صدوركم وعليها وعلى الفلك تحملون', NULL, 476, 'local:hafs-text.json'),
  ('hafs-40-81', 'hafs', 40, 81, 'وَيُرِيكُمْ ءَايَٰتِهِۦ فَأَىَّ ءَايَٰتِ ٱللَّهِ تُنكِرُونَ', 'ويريكم ءايته فأى ءايت الله تنكرون', NULL, 476, 'local:hafs-text.json'),
  ('hafs-40-82', 'hafs', 40, 82, 'أَفَلَمْ يَسِيرُوا۟ فِى ٱلْأَرْضِ فَيَنظُرُوا۟ كَيْفَ كَانَ عَٰقِبَةُ ٱلَّذِينَ مِن قَبْلِهِمْ ۚ كَانُوٓا۟ أَكْثَرَ مِنْهُمْ وَأَشَدَّ قُوَّةًۭ وَءَاثَارًۭا فِى ٱلْأَرْضِ فَمَآ أَغْنَىٰ عَنْهُم مَّا كَانُوا۟ يَكْسِبُونَ', 'أفلم يسيروا فى الأرض فينظروا كيف كان عقبة الذين من قبلهم  كانوا أكثر منهم وأشد قوة وءاثارا فى الأرض فما أغنى عنهم ما كانوا يكسبون', NULL, 476, 'local:hafs-text.json'),
  ('hafs-40-83', 'hafs', 40, 83, 'فَلَمَّا جَآءَتْهُمْ رُسُلُهُم بِٱلْبَيِّنَٰتِ فَرِحُوا۟ بِمَا عِندَهُم مِّنَ ٱلْعِلْمِ وَحَاقَ بِهِم مَّا كَانُوا۟ بِهِۦ يَسْتَهْزِءُونَ', 'فلما جاءتهم رسلهم بالبينت فرحوا بما عندهم من العلم وحاق بهم ما كانوا به يستهزءون', NULL, 476, 'local:hafs-text.json'),
  ('hafs-40-84', 'hafs', 40, 84, 'فَلَمَّا رَأَوْا۟ بَأْسَنَا قَالُوٓا۟ ءَامَنَّا بِٱللَّهِ وَحْدَهُۥ وَكَفَرْنَا بِمَا كُنَّا بِهِۦ مُشْرِكِينَ', 'فلما رأوا بأسنا قالوا ءامنا بالله وحده وكفرنا بما كنا به مشركين', NULL, 476, 'local:hafs-text.json'),
  ('hafs-40-85', 'hafs', 40, 85, 'فَلَمْ يَكُ يَنفَعُهُمْ إِيمَٰنُهُمْ لَمَّا رَأَوْا۟ بَأْسَنَا ۖ سُنَّتَ ٱللَّهِ ٱلَّتِى قَدْ خَلَتْ فِى عِبَادِهِۦ ۖ وَخَسِرَ هُنَالِكَ ٱلْكَٰفِرُونَ', 'فلم يك ينفعهم إيمنهم لما رأوا بأسنا  سنت الله التى قد خلت فى عباده  وخسر هنالك الكفرون', NULL, 476, 'local:hafs-text.json'),
  ('hafs-41-1', 'hafs', 41, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ حمٓ', 'بسم الله الرحمن الرحيم حم', NULL, 477, 'local:hafs-text.json'),
  ('hafs-41-2', 'hafs', 41, 2, 'تَنزِيلٌۭ مِّنَ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ', 'تنزيل من الرحمن الرحيم', NULL, 477, 'local:hafs-text.json'),
  ('hafs-41-3', 'hafs', 41, 3, 'كِتَٰبٌۭ فُصِّلَتْ ءَايَٰتُهُۥ قُرْءَانًا عَرَبِيًّۭا لِّقَوْمٍۢ يَعْلَمُونَ', 'كتب فصلت ءايته قرءانا عربيا لقوم يعلمون', NULL, 477, 'local:hafs-text.json'),
  ('hafs-41-4', 'hafs', 41, 4, 'بَشِيرًۭا وَنَذِيرًۭا فَأَعْرَضَ أَكْثَرُهُمْ فَهُمْ لَا يَسْمَعُونَ', 'بشيرا ونذيرا فأعرض أكثرهم فهم لا يسمعون', NULL, 477, 'local:hafs-text.json'),
  ('hafs-41-5', 'hafs', 41, 5, 'وَقَالُوا۟ قُلُوبُنَا فِىٓ أَكِنَّةٍۢ مِّمَّا تَدْعُونَآ إِلَيْهِ وَفِىٓ ءَاذَانِنَا وَقْرٌۭ وَمِنۢ بَيْنِنَا وَبَيْنِكَ حِجَابٌۭ فَٱعْمَلْ إِنَّنَا عَٰمِلُونَ', 'وقالوا قلوبنا فى أكنة مما تدعونا إليه وفى ءاذاننا وقر ومن بيننا وبينك حجاب فاعمل إننا عملون', NULL, 477, 'local:hafs-text.json'),
  ('hafs-41-6', 'hafs', 41, 6, 'قُلْ إِنَّمَآ أَنَا۠ بَشَرٌۭ مِّثْلُكُمْ يُوحَىٰٓ إِلَىَّ أَنَّمَآ إِلَٰهُكُمْ إِلَٰهٌۭ وَٰحِدٌۭ فَٱسْتَقِيمُوٓا۟ إِلَيْهِ وَٱسْتَغْفِرُوهُ ۗ وَوَيْلٌۭ لِّلْمُشْرِكِينَ', 'قل إنما أنا بشر مثلكم يوحى إلى أنما إلهكم إله وحد فاستقيموا إليه واستغفروه  وويل للمشركين', NULL, 477, 'local:hafs-text.json'),
  ('hafs-41-7', 'hafs', 41, 7, 'ٱلَّذِينَ لَا يُؤْتُونَ ٱلزَّكَوٰةَ وَهُم بِٱلْءَاخِرَةِ هُمْ كَٰفِرُونَ', 'الذين لا يؤتون الزكوة وهم بالءاخرة هم كفرون', NULL, 477, 'local:hafs-text.json'),
  ('hafs-41-8', 'hafs', 41, 8, 'إِنَّ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ لَهُمْ أَجْرٌ غَيْرُ مَمْنُونٍۢ', 'إن الذين ءامنوا وعملوا الصلحت لهم أجر غير ممنون', NULL, 477, 'local:hafs-text.json'),
  ('hafs-41-9', 'hafs', 41, 9, '۞ قُلْ أَئِنَّكُمْ لَتَكْفُرُونَ بِٱلَّذِى خَلَقَ ٱلْأَرْضَ فِى يَوْمَيْنِ وَتَجْعَلُونَ لَهُۥٓ أَندَادًۭا ۚ ذَٰلِكَ رَبُّ ٱلْعَٰلَمِينَ', 'قل أئنكم لتكفرون بالذى خلق الأرض فى يومين وتجعلون له أندادا  ذلك رب العلمين', NULL, 477, 'local:hafs-text.json'),
  ('hafs-41-10', 'hafs', 41, 10, 'وَجَعَلَ فِيهَا رَوَٰسِىَ مِن فَوْقِهَا وَبَٰرَكَ فِيهَا وَقَدَّرَ فِيهَآ أَقْوَٰتَهَا فِىٓ أَرْبَعَةِ أَيَّامٍۢ سَوَآءًۭ لِّلسَّآئِلِينَ', 'وجعل فيها روسى من فوقها وبرك فيها وقدر فيها أقوتها فى أربعة أيام سواء للسائلين', NULL, 477, 'local:hafs-text.json'),
  ('hafs-41-11', 'hafs', 41, 11, 'ثُمَّ ٱسْتَوَىٰٓ إِلَى ٱلسَّمَآءِ وَهِىَ دُخَانٌۭ فَقَالَ لَهَا وَلِلْأَرْضِ ٱئْتِيَا طَوْعًا أَوْ كَرْهًۭا قَالَتَآ أَتَيْنَا طَآئِعِينَ', 'ثم استوى إلى السماء وهى دخان فقال لها وللأرض ائتيا طوعا أو كرها قالتا أتينا طائعين', NULL, 477, 'local:hafs-text.json'),
  ('hafs-41-12', 'hafs', 41, 12, 'فَقَضَىٰهُنَّ سَبْعَ سَمَٰوَاتٍۢ فِى يَوْمَيْنِ وَأَوْحَىٰ فِى كُلِّ سَمَآءٍ أَمْرَهَا ۚ وَزَيَّنَّا ٱلسَّمَآءَ ٱلدُّنْيَا بِمَصَٰبِيحَ وَحِفْظًۭا ۚ ذَٰلِكَ تَقْدِيرُ ٱلْعَزِيزِ ٱلْعَلِيمِ', 'فقضىهن سبع سموات فى يومين وأوحى فى كل سماء أمرها  وزينا السماء الدنيا بمصبيح وحفظا  ذلك تقدير العزيز العليم', NULL, 478, 'local:hafs-text.json'),
  ('hafs-41-13', 'hafs', 41, 13, 'فَإِنْ أَعْرَضُوا۟ فَقُلْ أَنذَرْتُكُمْ صَٰعِقَةًۭ مِّثْلَ صَٰعِقَةِ عَادٍۢ وَثَمُودَ', 'فإن أعرضوا فقل أنذرتكم صعقة مثل صعقة عاد وثمود', NULL, 478, 'local:hafs-text.json'),
  ('hafs-41-14', 'hafs', 41, 14, 'إِذْ جَآءَتْهُمُ ٱلرُّسُلُ مِنۢ بَيْنِ أَيْدِيهِمْ وَمِنْ خَلْفِهِمْ أَلَّا تَعْبُدُوٓا۟ إِلَّا ٱللَّهَ ۖ قَالُوا۟ لَوْ شَآءَ رَبُّنَا لَأَنزَلَ مَلَٰٓئِكَةًۭ فَإِنَّا بِمَآ أُرْسِلْتُم بِهِۦ كَٰفِرُونَ', 'إذ جاءتهم الرسل من بين أيديهم ومن خلفهم ألا تعبدوا إلا الله  قالوا لو شاء ربنا لأنزل ملئكة فإنا بما أرسلتم به كفرون', NULL, 478, 'local:hafs-text.json'),
  ('hafs-41-15', 'hafs', 41, 15, 'فَأَمَّا عَادٌۭ فَٱسْتَكْبَرُوا۟ فِى ٱلْأَرْضِ بِغَيْرِ ٱلْحَقِّ وَقَالُوا۟ مَنْ أَشَدُّ مِنَّا قُوَّةً ۖ أَوَلَمْ يَرَوْا۟ أَنَّ ٱللَّهَ ٱلَّذِى خَلَقَهُمْ هُوَ أَشَدُّ مِنْهُمْ قُوَّةًۭ ۖ وَكَانُوا۟ بِـَٔايَٰتِنَا يَجْحَدُونَ', 'فأما عاد فاستكبروا فى الأرض بغير الحق وقالوا من أشد منا قوة  أولم يروا أن الله الذى خلقهم هو أشد منهم قوة  وكانوا بايتنا يجحدون', NULL, 478, 'local:hafs-text.json'),
  ('hafs-41-16', 'hafs', 41, 16, 'فَأَرْسَلْنَا عَلَيْهِمْ رِيحًۭا صَرْصَرًۭا فِىٓ أَيَّامٍۢ نَّحِسَاتٍۢ لِّنُذِيقَهُمْ عَذَابَ ٱلْخِزْىِ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا ۖ وَلَعَذَابُ ٱلْءَاخِرَةِ أَخْزَىٰ ۖ وَهُمْ لَا يُنصَرُونَ', 'فأرسلنا عليهم ريحا صرصرا فى أيام نحسات لنذيقهم عذاب الخزى فى الحيوة الدنيا  ولعذاب الءاخرة أخزى  وهم لا ينصرون', NULL, 478, 'local:hafs-text.json'),
  ('hafs-41-17', 'hafs', 41, 17, 'وَأَمَّا ثَمُودُ فَهَدَيْنَٰهُمْ فَٱسْتَحَبُّوا۟ ٱلْعَمَىٰ عَلَى ٱلْهُدَىٰ فَأَخَذَتْهُمْ صَٰعِقَةُ ٱلْعَذَابِ ٱلْهُونِ بِمَا كَانُوا۟ يَكْسِبُونَ', 'وأما ثمود فهدينهم فاستحبوا العمى على الهدى فأخذتهم صعقة العذاب الهون بما كانوا يكسبون', NULL, 478, 'local:hafs-text.json'),
  ('hafs-41-18', 'hafs', 41, 18, 'وَنَجَّيْنَا ٱلَّذِينَ ءَامَنُوا۟ وَكَانُوا۟ يَتَّقُونَ', 'ونجينا الذين ءامنوا وكانوا يتقون', NULL, 478, 'local:hafs-text.json'),
  ('hafs-41-19', 'hafs', 41, 19, 'وَيَوْمَ يُحْشَرُ أَعْدَآءُ ٱللَّهِ إِلَى ٱلنَّارِ فَهُمْ يُوزَعُونَ', 'ويوم يحشر أعداء الله إلى النار فهم يوزعون', NULL, 478, 'local:hafs-text.json'),
  ('hafs-41-20', 'hafs', 41, 20, 'حَتَّىٰٓ إِذَا مَا جَآءُوهَا شَهِدَ عَلَيْهِمْ سَمْعُهُمْ وَأَبْصَٰرُهُمْ وَجُلُودُهُم بِمَا كَانُوا۟ يَعْمَلُونَ', 'حتى إذا ما جاءوها شهد عليهم سمعهم وأبصرهم وجلودهم بما كانوا يعملون', NULL, 478, 'local:hafs-text.json'),
  ('hafs-41-21', 'hafs', 41, 21, 'وَقَالُوا۟ لِجُلُودِهِمْ لِمَ شَهِدتُّمْ عَلَيْنَا ۖ قَالُوٓا۟ أَنطَقَنَا ٱللَّهُ ٱلَّذِىٓ أَنطَقَ كُلَّ شَىْءٍۢ وَهُوَ خَلَقَكُمْ أَوَّلَ مَرَّةٍۢ وَإِلَيْهِ تُرْجَعُونَ', 'وقالوا لجلودهم لم شهدتم علينا  قالوا أنطقنا الله الذى أنطق كل شىء وهو خلقكم أول مرة وإليه ترجعون', NULL, 479, 'local:hafs-text.json'),
  ('hafs-41-22', 'hafs', 41, 22, 'وَمَا كُنتُمْ تَسْتَتِرُونَ أَن يَشْهَدَ عَلَيْكُمْ سَمْعُكُمْ وَلَآ أَبْصَٰرُكُمْ وَلَا جُلُودُكُمْ وَلَٰكِن ظَنَنتُمْ أَنَّ ٱللَّهَ لَا يَعْلَمُ كَثِيرًۭا مِّمَّا تَعْمَلُونَ', 'وما كنتم تستترون أن يشهد عليكم سمعكم ولا أبصركم ولا جلودكم ولكن ظننتم أن الله لا يعلم كثيرا مما تعملون', NULL, 479, 'local:hafs-text.json'),
  ('hafs-41-23', 'hafs', 41, 23, 'وَذَٰلِكُمْ ظَنُّكُمُ ٱلَّذِى ظَنَنتُم بِرَبِّكُمْ أَرْدَىٰكُمْ فَأَصْبَحْتُم مِّنَ ٱلْخَٰسِرِينَ', 'وذلكم ظنكم الذى ظننتم بربكم أردىكم فأصبحتم من الخسرين', NULL, 479, 'local:hafs-text.json'),
  ('hafs-41-24', 'hafs', 41, 24, 'فَإِن يَصْبِرُوا۟ فَٱلنَّارُ مَثْوًۭى لَّهُمْ ۖ وَإِن يَسْتَعْتِبُوا۟ فَمَا هُم مِّنَ ٱلْمُعْتَبِينَ', 'فإن يصبروا فالنار مثوى لهم  وإن يستعتبوا فما هم من المعتبين', NULL, 479, 'local:hafs-text.json'),
  ('hafs-41-25', 'hafs', 41, 25, '۞ وَقَيَّضْنَا لَهُمْ قُرَنَآءَ فَزَيَّنُوا۟ لَهُم مَّا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ وَحَقَّ عَلَيْهِمُ ٱلْقَوْلُ فِىٓ أُمَمٍۢ قَدْ خَلَتْ مِن قَبْلِهِم مِّنَ ٱلْجِنِّ وَٱلْإِنسِ ۖ إِنَّهُمْ كَانُوا۟ خَٰسِرِينَ', 'وقيضنا لهم قرناء فزينوا لهم ما بين أيديهم وما خلفهم وحق عليهم القول فى أمم قد خلت من قبلهم من الجن والإنس  إنهم كانوا خسرين', NULL, 479, 'local:hafs-text.json'),
  ('hafs-41-26', 'hafs', 41, 26, 'وَقَالَ ٱلَّذِينَ كَفَرُوا۟ لَا تَسْمَعُوا۟ لِهَٰذَا ٱلْقُرْءَانِ وَٱلْغَوْا۟ فِيهِ لَعَلَّكُمْ تَغْلِبُونَ', 'وقال الذين كفروا لا تسمعوا لهذا القرءان والغوا فيه لعلكم تغلبون', NULL, 479, 'local:hafs-text.json'),
  ('hafs-41-27', 'hafs', 41, 27, 'فَلَنُذِيقَنَّ ٱلَّذِينَ كَفَرُوا۟ عَذَابًۭا شَدِيدًۭا وَلَنَجْزِيَنَّهُمْ أَسْوَأَ ٱلَّذِى كَانُوا۟ يَعْمَلُونَ', 'فلنذيقن الذين كفروا عذابا شديدا ولنجزينهم أسوأ الذى كانوا يعملون', NULL, 479, 'local:hafs-text.json'),
  ('hafs-41-28', 'hafs', 41, 28, 'ذَٰلِكَ جَزَآءُ أَعْدَآءِ ٱللَّهِ ٱلنَّارُ ۖ لَهُمْ فِيهَا دَارُ ٱلْخُلْدِ ۖ جَزَآءًۢ بِمَا كَانُوا۟ بِـَٔايَٰتِنَا يَجْحَدُونَ', 'ذلك جزاء أعداء الله النار  لهم فيها دار الخلد  جزاء بما كانوا بايتنا يجحدون', NULL, 479, 'local:hafs-text.json'),
  ('hafs-41-29', 'hafs', 41, 29, 'وَقَالَ ٱلَّذِينَ كَفَرُوا۟ رَبَّنَآ أَرِنَا ٱلَّذَيْنِ أَضَلَّانَا مِنَ ٱلْجِنِّ وَٱلْإِنسِ نَجْعَلْهُمَا تَحْتَ أَقْدَامِنَا لِيَكُونَا مِنَ ٱلْأَسْفَلِينَ', 'وقال الذين كفروا ربنا أرنا الذين أضلانا من الجن والإنس نجعلهما تحت أقدامنا ليكونا من الأسفلين', NULL, 479, 'local:hafs-text.json'),
  ('hafs-41-30', 'hafs', 41, 30, 'إِنَّ ٱلَّذِينَ قَالُوا۟ رَبُّنَا ٱللَّهُ ثُمَّ ٱسْتَقَٰمُوا۟ تَتَنَزَّلُ عَلَيْهِمُ ٱلْمَلَٰٓئِكَةُ أَلَّا تَخَافُوا۟ وَلَا تَحْزَنُوا۟ وَأَبْشِرُوا۟ بِٱلْجَنَّةِ ٱلَّتِى كُنتُمْ تُوعَدُونَ', 'إن الذين قالوا ربنا الله ثم استقموا تتنزل عليهم الملئكة ألا تخافوا ولا تحزنوا وأبشروا بالجنة التى كنتم توعدون', NULL, 480, 'local:hafs-text.json'),
  ('hafs-41-31', 'hafs', 41, 31, 'نَحْنُ أَوْلِيَآؤُكُمْ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا وَفِى ٱلْءَاخِرَةِ ۖ وَلَكُمْ فِيهَا مَا تَشْتَهِىٓ أَنفُسُكُمْ وَلَكُمْ فِيهَا مَا تَدَّعُونَ', 'نحن أولياؤكم فى الحيوة الدنيا وفى الءاخرة  ولكم فيها ما تشتهى أنفسكم ولكم فيها ما تدعون', NULL, 480, 'local:hafs-text.json'),
  ('hafs-41-32', 'hafs', 41, 32, 'نُزُلًۭا مِّنْ غَفُورٍۢ رَّحِيمٍۢ', 'نزلا من غفور رحيم', NULL, 480, 'local:hafs-text.json'),
  ('hafs-41-33', 'hafs', 41, 33, 'وَمَنْ أَحْسَنُ قَوْلًۭا مِّمَّن دَعَآ إِلَى ٱللَّهِ وَعَمِلَ صَٰلِحًۭا وَقَالَ إِنَّنِى مِنَ ٱلْمُسْلِمِينَ', 'ومن أحسن قولا ممن دعا إلى الله وعمل صلحا وقال إننى من المسلمين', NULL, 480, 'local:hafs-text.json'),
  ('hafs-41-34', 'hafs', 41, 34, 'وَلَا تَسْتَوِى ٱلْحَسَنَةُ وَلَا ٱلسَّيِّئَةُ ۚ ٱدْفَعْ بِٱلَّتِى هِىَ أَحْسَنُ فَإِذَا ٱلَّذِى بَيْنَكَ وَبَيْنَهُۥ عَدَٰوَةٌۭ كَأَنَّهُۥ وَلِىٌّ حَمِيمٌۭ', 'ولا تستوى الحسنة ولا السيئة  ادفع بالتى هى أحسن فإذا الذى بينك وبينه عدوة كأنه ولى حميم', NULL, 480, 'local:hafs-text.json'),
  ('hafs-41-35', 'hafs', 41, 35, 'وَمَا يُلَقَّىٰهَآ إِلَّا ٱلَّذِينَ صَبَرُوا۟ وَمَا يُلَقَّىٰهَآ إِلَّا ذُو حَظٍّ عَظِيمٍۢ', 'وما يلقىها إلا الذين صبروا وما يلقىها إلا ذو حظ عظيم', NULL, 480, 'local:hafs-text.json'),
  ('hafs-41-36', 'hafs', 41, 36, 'وَإِمَّا يَنزَغَنَّكَ مِنَ ٱلشَّيْطَٰنِ نَزْغٌۭ فَٱسْتَعِذْ بِٱللَّهِ ۖ إِنَّهُۥ هُوَ ٱلسَّمِيعُ ٱلْعَلِيمُ', 'وإما ينزغنك من الشيطن نزغ فاستعذ بالله  إنه هو السميع العليم', NULL, 480, 'local:hafs-text.json'),
  ('hafs-41-37', 'hafs', 41, 37, 'وَمِنْ ءَايَٰتِهِ ٱلَّيْلُ وَٱلنَّهَارُ وَٱلشَّمْسُ وَٱلْقَمَرُ ۚ لَا تَسْجُدُوا۟ لِلشَّمْسِ وَلَا لِلْقَمَرِ وَٱسْجُدُوا۟ لِلَّهِ ٱلَّذِى خَلَقَهُنَّ إِن كُنتُمْ إِيَّاهُ تَعْبُدُونَ', 'ومن ءايته اليل والنهار والشمس والقمر  لا تسجدوا للشمس ولا للقمر واسجدوا لله الذى خلقهن إن كنتم إياه تعبدون', NULL, 480, 'local:hafs-text.json'),
  ('hafs-41-38', 'hafs', 41, 38, 'فَإِنِ ٱسْتَكْبَرُوا۟ فَٱلَّذِينَ عِندَ رَبِّكَ يُسَبِّحُونَ لَهُۥ بِٱلَّيْلِ وَٱلنَّهَارِ وَهُمْ لَا يَسْـَٔمُونَ ۩', 'فإن استكبروا فالذين عند ربك يسبحون له باليل والنهار وهم لا يسمون', NULL, 480, 'local:hafs-text.json'),
  ('hafs-41-39', 'hafs', 41, 39, 'وَمِنْ ءَايَٰتِهِۦٓ أَنَّكَ تَرَى ٱلْأَرْضَ خَٰشِعَةًۭ فَإِذَآ أَنزَلْنَا عَلَيْهَا ٱلْمَآءَ ٱهْتَزَّتْ وَرَبَتْ ۚ إِنَّ ٱلَّذِىٓ أَحْيَاهَا لَمُحْىِ ٱلْمَوْتَىٰٓ ۚ إِنَّهُۥ عَلَىٰ كُلِّ شَىْءٍۢ قَدِيرٌ', 'ومن ءايته أنك ترى الأرض خشعة فإذا أنزلنا عليها الماء اهتزت وربت  إن الذى أحياها لمحى الموتى  إنه على كل شىء قدير', NULL, 481, 'local:hafs-text.json'),
  ('hafs-41-40', 'hafs', 41, 40, 'إِنَّ ٱلَّذِينَ يُلْحِدُونَ فِىٓ ءَايَٰتِنَا لَا يَخْفَوْنَ عَلَيْنَآ ۗ أَفَمَن يُلْقَىٰ فِى ٱلنَّارِ خَيْرٌ أَم مَّن يَأْتِىٓ ءَامِنًۭا يَوْمَ ٱلْقِيَٰمَةِ ۚ ٱعْمَلُوا۟ مَا شِئْتُمْ ۖ إِنَّهُۥ بِمَا تَعْمَلُونَ بَصِيرٌ', 'إن الذين يلحدون فى ءايتنا لا يخفون علينا  أفمن يلقى فى النار خير أم من يأتى ءامنا يوم القيمة  اعملوا ما شئتم  إنه بما تعملون بصير', NULL, 481, 'local:hafs-text.json'),
  ('hafs-41-41', 'hafs', 41, 41, 'إِنَّ ٱلَّذِينَ كَفَرُوا۟ بِٱلذِّكْرِ لَمَّا جَآءَهُمْ ۖ وَإِنَّهُۥ لَكِتَٰبٌ عَزِيزٌۭ', 'إن الذين كفروا بالذكر لما جاءهم  وإنه لكتب عزيز', NULL, 481, 'local:hafs-text.json'),
  ('hafs-41-42', 'hafs', 41, 42, 'لَّا يَأْتِيهِ ٱلْبَٰطِلُ مِنۢ بَيْنِ يَدَيْهِ وَلَا مِنْ خَلْفِهِۦ ۖ تَنزِيلٌۭ مِّنْ حَكِيمٍ حَمِيدٍۢ', 'لا يأتيه البطل من بين يديه ولا من خلفه  تنزيل من حكيم حميد', NULL, 481, 'local:hafs-text.json'),
  ('hafs-41-43', 'hafs', 41, 43, 'مَّا يُقَالُ لَكَ إِلَّا مَا قَدْ قِيلَ لِلرُّسُلِ مِن قَبْلِكَ ۚ إِنَّ رَبَّكَ لَذُو مَغْفِرَةٍۢ وَذُو عِقَابٍ أَلِيمٍۢ', 'ما يقال لك إلا ما قد قيل للرسل من قبلك  إن ربك لذو مغفرة وذو عقاب أليم', NULL, 481, 'local:hafs-text.json'),
  ('hafs-41-44', 'hafs', 41, 44, 'وَلَوْ جَعَلْنَٰهُ قُرْءَانًا أَعْجَمِيًّۭا لَّقَالُوا۟ لَوْلَا فُصِّلَتْ ءَايَٰتُهُۥٓ ۖ ءَا۬عْجَمِىٌّۭ وَعَرَبِىٌّۭ ۗ قُلْ هُوَ لِلَّذِينَ ءَامَنُوا۟ هُدًۭى وَشِفَآءٌۭ ۖ وَٱلَّذِينَ لَا يُؤْمِنُونَ فِىٓ ءَاذَانِهِمْ وَقْرٌۭ وَهُوَ عَلَيْهِمْ عَمًى ۚ أُو۟لَٰٓئِكَ يُنَادَوْنَ مِن مَّكَانٍۭ بَعِيدٍۢ', 'ولو جعلنه قرءانا أعجميا لقالوا لولا فصلت ءايته  ءاعجمى وعربى  قل هو للذين ءامنوا هدى وشفاء  والذين لا يؤمنون فى ءاذانهم وقر وهو عليهم عمى  أولئك ينادون من مكان بعيد', NULL, 481, 'local:hafs-text.json'),
  ('hafs-41-45', 'hafs', 41, 45, 'وَلَقَدْ ءَاتَيْنَا مُوسَى ٱلْكِتَٰبَ فَٱخْتُلِفَ فِيهِ ۗ وَلَوْلَا كَلِمَةٌۭ سَبَقَتْ مِن رَّبِّكَ لَقُضِىَ بَيْنَهُمْ ۚ وَإِنَّهُمْ لَفِى شَكٍّۢ مِّنْهُ مُرِيبٍۢ', 'ولقد ءاتينا موسى الكتب فاختلف فيه  ولولا كلمة سبقت من ربك لقضى بينهم  وإنهم لفى شك منه مريب', NULL, 481, 'local:hafs-text.json'),
  ('hafs-41-46', 'hafs', 41, 46, 'مَّنْ عَمِلَ صَٰلِحًۭا فَلِنَفْسِهِۦ ۖ وَمَنْ أَسَآءَ فَعَلَيْهَا ۗ وَمَا رَبُّكَ بِظَلَّٰمٍۢ لِّلْعَبِيدِ', 'من عمل صلحا فلنفسه  ومن أساء فعليها  وما ربك بظلم للعبيد', NULL, 481, 'local:hafs-text.json'),
  ('hafs-41-47', 'hafs', 41, 47, '۞ إِلَيْهِ يُرَدُّ عِلْمُ ٱلسَّاعَةِ ۚ وَمَا تَخْرُجُ مِن ثَمَرَٰتٍۢ مِّنْ أَكْمَامِهَا وَمَا تَحْمِلُ مِنْ أُنثَىٰ وَلَا تَضَعُ إِلَّا بِعِلْمِهِۦ ۚ وَيَوْمَ يُنَادِيهِمْ أَيْنَ شُرَكَآءِى قَالُوٓا۟ ءَاذَنَّٰكَ مَا مِنَّا مِن شَهِيدٍۢ', 'إليه يرد علم الساعة  وما تخرج من ثمرت من أكمامها وما تحمل من أنثى ولا تضع إلا بعلمه  ويوم يناديهم أين شركاءى قالوا ءاذنك ما منا من شهيد', NULL, 482, 'local:hafs-text.json'),
  ('hafs-41-48', 'hafs', 41, 48, 'وَضَلَّ عَنْهُم مَّا كَانُوا۟ يَدْعُونَ مِن قَبْلُ ۖ وَظَنُّوا۟ مَا لَهُم مِّن مَّحِيصٍۢ', 'وضل عنهم ما كانوا يدعون من قبل  وظنوا ما لهم من محيص', NULL, 482, 'local:hafs-text.json'),
  ('hafs-41-49', 'hafs', 41, 49, 'لَّا يَسْـَٔمُ ٱلْإِنسَٰنُ مِن دُعَآءِ ٱلْخَيْرِ وَإِن مَّسَّهُ ٱلشَّرُّ فَيَـُٔوسٌۭ قَنُوطٌۭ', 'لا يسم الإنسن من دعاء الخير وإن مسه الشر فيوس قنوط', NULL, 482, 'local:hafs-text.json'),
  ('hafs-41-50', 'hafs', 41, 50, 'وَلَئِنْ أَذَقْنَٰهُ رَحْمَةًۭ مِّنَّا مِنۢ بَعْدِ ضَرَّآءَ مَسَّتْهُ لَيَقُولَنَّ هَٰذَا لِى وَمَآ أَظُنُّ ٱلسَّاعَةَ قَآئِمَةًۭ وَلَئِن رُّجِعْتُ إِلَىٰ رَبِّىٓ إِنَّ لِى عِندَهُۥ لَلْحُسْنَىٰ ۚ فَلَنُنَبِّئَنَّ ٱلَّذِينَ كَفَرُوا۟ بِمَا عَمِلُوا۟ وَلَنُذِيقَنَّهُم مِّنْ عَذَابٍ غَلِيظٍۢ', 'ولئن أذقنه رحمة منا من بعد ضراء مسته ليقولن هذا لى وما أظن الساعة قائمة ولئن رجعت إلى ربى إن لى عنده للحسنى  فلننبئن الذين كفروا بما عملوا ولنذيقنهم من عذاب غليظ', NULL, 482, 'local:hafs-text.json'),
  ('hafs-41-51', 'hafs', 41, 51, 'وَإِذَآ أَنْعَمْنَا عَلَى ٱلْإِنسَٰنِ أَعْرَضَ وَنَـَٔا بِجَانِبِهِۦ وَإِذَا مَسَّهُ ٱلشَّرُّ فَذُو دُعَآءٍ عَرِيضٍۢ', 'وإذا أنعمنا على الإنسن أعرض ونا بجانبه وإذا مسه الشر فذو دعاء عريض', NULL, 482, 'local:hafs-text.json'),
  ('hafs-41-52', 'hafs', 41, 52, 'قُلْ أَرَءَيْتُمْ إِن كَانَ مِنْ عِندِ ٱللَّهِ ثُمَّ كَفَرْتُم بِهِۦ مَنْ أَضَلُّ مِمَّنْ هُوَ فِى شِقَاقٍۭ بَعِيدٍۢ', 'قل أرءيتم إن كان من عند الله ثم كفرتم به من أضل ممن هو فى شقاق بعيد', NULL, 482, 'local:hafs-text.json'),
  ('hafs-41-53', 'hafs', 41, 53, 'سَنُرِيهِمْ ءَايَٰتِنَا فِى ٱلْءَافَاقِ وَفِىٓ أَنفُسِهِمْ حَتَّىٰ يَتَبَيَّنَ لَهُمْ أَنَّهُ ٱلْحَقُّ ۗ أَوَلَمْ يَكْفِ بِرَبِّكَ أَنَّهُۥ عَلَىٰ كُلِّ شَىْءٍۢ شَهِيدٌ', 'سنريهم ءايتنا فى الءافاق وفى أنفسهم حتى يتبين لهم أنه الحق  أولم يكف بربك أنه على كل شىء شهيد', NULL, 482, 'local:hafs-text.json'),
  ('hafs-41-54', 'hafs', 41, 54, 'أَلَآ إِنَّهُمْ فِى مِرْيَةٍۢ مِّن لِّقَآءِ رَبِّهِمْ ۗ أَلَآ إِنَّهُۥ بِكُلِّ شَىْءٍۢ مُّحِيطٌۢ', 'ألا إنهم فى مرية من لقاء ربهم  ألا إنه بكل شىء محيط', NULL, 482, 'local:hafs-text.json'),
  ('hafs-42-1', 'hafs', 42, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ حمٓ', 'بسم الله الرحمن الرحيم حم', NULL, 483, 'local:hafs-text.json'),
  ('hafs-42-2', 'hafs', 42, 2, 'عٓسٓقٓ', 'عسق', NULL, 483, 'local:hafs-text.json'),
  ('hafs-42-3', 'hafs', 42, 3, 'كَذَٰلِكَ يُوحِىٓ إِلَيْكَ وَإِلَى ٱلَّذِينَ مِن قَبْلِكَ ٱللَّهُ ٱلْعَزِيزُ ٱلْحَكِيمُ', 'كذلك يوحى إليك وإلى الذين من قبلك الله العزيز الحكيم', NULL, 483, 'local:hafs-text.json'),
  ('hafs-42-4', 'hafs', 42, 4, 'لَهُۥ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ ۖ وَهُوَ ٱلْعَلِىُّ ٱلْعَظِيمُ', 'له ما فى السموت وما فى الأرض  وهو العلى العظيم', NULL, 483, 'local:hafs-text.json'),
  ('hafs-42-5', 'hafs', 42, 5, 'تَكَادُ ٱلسَّمَٰوَٰتُ يَتَفَطَّرْنَ مِن فَوْقِهِنَّ ۚ وَٱلْمَلَٰٓئِكَةُ يُسَبِّحُونَ بِحَمْدِ رَبِّهِمْ وَيَسْتَغْفِرُونَ لِمَن فِى ٱلْأَرْضِ ۗ أَلَآ إِنَّ ٱللَّهَ هُوَ ٱلْغَفُورُ ٱلرَّحِيمُ', 'تكاد السموت يتفطرن من فوقهن  والملئكة يسبحون بحمد ربهم ويستغفرون لمن فى الأرض  ألا إن الله هو الغفور الرحيم', NULL, 483, 'local:hafs-text.json'),
  ('hafs-42-6', 'hafs', 42, 6, 'وَٱلَّذِينَ ٱتَّخَذُوا۟ مِن دُونِهِۦٓ أَوْلِيَآءَ ٱللَّهُ حَفِيظٌ عَلَيْهِمْ وَمَآ أَنتَ عَلَيْهِم بِوَكِيلٍۢ', 'والذين اتخذوا من دونه أولياء الله حفيظ عليهم وما أنت عليهم بوكيل', NULL, 483, 'local:hafs-text.json'),
  ('hafs-42-7', 'hafs', 42, 7, 'وَكَذَٰلِكَ أَوْحَيْنَآ إِلَيْكَ قُرْءَانًا عَرَبِيًّۭا لِّتُنذِرَ أُمَّ ٱلْقُرَىٰ وَمَنْ حَوْلَهَا وَتُنذِرَ يَوْمَ ٱلْجَمْعِ لَا رَيْبَ فِيهِ ۚ فَرِيقٌۭ فِى ٱلْجَنَّةِ وَفَرِيقٌۭ فِى ٱلسَّعِيرِ', 'وكذلك أوحينا إليك قرءانا عربيا لتنذر أم القرى ومن حولها وتنذر يوم الجمع لا ريب فيه  فريق فى الجنة وفريق فى السعير', NULL, 483, 'local:hafs-text.json'),
  ('hafs-42-8', 'hafs', 42, 8, 'وَلَوْ شَآءَ ٱللَّهُ لَجَعَلَهُمْ أُمَّةًۭ وَٰحِدَةًۭ وَلَٰكِن يُدْخِلُ مَن يَشَآءُ فِى رَحْمَتِهِۦ ۚ وَٱلظَّٰلِمُونَ مَا لَهُم مِّن وَلِىٍّۢ وَلَا نَصِيرٍ', 'ولو شاء الله لجعلهم أمة وحدة ولكن يدخل من يشاء فى رحمته  والظلمون ما لهم من ولى ولا نصير', NULL, 483, 'local:hafs-text.json'),
  ('hafs-42-9', 'hafs', 42, 9, 'أَمِ ٱتَّخَذُوا۟ مِن دُونِهِۦٓ أَوْلِيَآءَ ۖ فَٱللَّهُ هُوَ ٱلْوَلِىُّ وَهُوَ يُحْىِ ٱلْمَوْتَىٰ وَهُوَ عَلَىٰ كُلِّ شَىْءٍۢ قَدِيرٌۭ', 'أم اتخذوا من دونه أولياء  فالله هو الولى وهو يحى الموتى وهو على كل شىء قدير', NULL, 483, 'local:hafs-text.json'),
  ('hafs-42-10', 'hafs', 42, 10, 'وَمَا ٱخْتَلَفْتُمْ فِيهِ مِن شَىْءٍۢ فَحُكْمُهُۥٓ إِلَى ٱللَّهِ ۚ ذَٰلِكُمُ ٱللَّهُ رَبِّى عَلَيْهِ تَوَكَّلْتُ وَإِلَيْهِ أُنِيبُ', 'وما اختلفتم فيه من شىء فحكمه إلى الله  ذلكم الله ربى عليه توكلت وإليه أنيب', NULL, 483, 'local:hafs-text.json'),
  ('hafs-42-11', 'hafs', 42, 11, 'فَاطِرُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ ۚ جَعَلَ لَكُم مِّنْ أَنفُسِكُمْ أَزْوَٰجًۭا وَمِنَ ٱلْأَنْعَٰمِ أَزْوَٰجًۭا ۖ يَذْرَؤُكُمْ فِيهِ ۚ لَيْسَ كَمِثْلِهِۦ شَىْءٌۭ ۖ وَهُوَ ٱلسَّمِيعُ ٱلْبَصِيرُ', 'فاطر السموت والأرض  جعل لكم من أنفسكم أزوجا ومن الأنعم أزوجا  يذرؤكم فيه  ليس كمثله شىء  وهو السميع البصير', NULL, 484, 'local:hafs-text.json'),
  ('hafs-42-12', 'hafs', 42, 12, 'لَهُۥ مَقَالِيدُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ ۖ يَبْسُطُ ٱلرِّزْقَ لِمَن يَشَآءُ وَيَقْدِرُ ۚ إِنَّهُۥ بِكُلِّ شَىْءٍ عَلِيمٌۭ', 'له مقاليد السموت والأرض  يبسط الرزق لمن يشاء ويقدر  إنه بكل شىء عليم', NULL, 484, 'local:hafs-text.json'),
  ('hafs-42-13', 'hafs', 42, 13, '۞ شَرَعَ لَكُم مِّنَ ٱلدِّينِ مَا وَصَّىٰ بِهِۦ نُوحًۭا وَٱلَّذِىٓ أَوْحَيْنَآ إِلَيْكَ وَمَا وَصَّيْنَا بِهِۦٓ إِبْرَٰهِيمَ وَمُوسَىٰ وَعِيسَىٰٓ ۖ أَنْ أَقِيمُوا۟ ٱلدِّينَ وَلَا تَتَفَرَّقُوا۟ فِيهِ ۚ كَبُرَ عَلَى ٱلْمُشْرِكِينَ مَا تَدْعُوهُمْ إِلَيْهِ ۚ ٱللَّهُ يَجْتَبِىٓ إِلَيْهِ مَن يَشَآءُ وَيَهْدِىٓ إِلَيْهِ مَن يُنِيبُ', 'شرع لكم من الدين ما وصى به نوحا والذى أوحينا إليك وما وصينا به إبرهيم وموسى وعيسى  أن أقيموا الدين ولا تتفرقوا فيه  كبر على المشركين ما تدعوهم إليه  الله يجتبى إليه من يشاء ويهدى إليه من ينيب', NULL, 484, 'local:hafs-text.json'),
  ('hafs-42-14', 'hafs', 42, 14, 'وَمَا تَفَرَّقُوٓا۟ إِلَّا مِنۢ بَعْدِ مَا جَآءَهُمُ ٱلْعِلْمُ بَغْيًۢا بَيْنَهُمْ ۚ وَلَوْلَا كَلِمَةٌۭ سَبَقَتْ مِن رَّبِّكَ إِلَىٰٓ أَجَلٍۢ مُّسَمًّۭى لَّقُضِىَ بَيْنَهُمْ ۚ وَإِنَّ ٱلَّذِينَ أُورِثُوا۟ ٱلْكِتَٰبَ مِنۢ بَعْدِهِمْ لَفِى شَكٍّۢ مِّنْهُ مُرِيبٍۢ', 'وما تفرقوا إلا من بعد ما جاءهم العلم بغيا بينهم  ولولا كلمة سبقت من ربك إلى أجل مسمى لقضى بينهم  وإن الذين أورثوا الكتب من بعدهم لفى شك منه مريب', NULL, 484, 'local:hafs-text.json'),
  ('hafs-42-15', 'hafs', 42, 15, 'فَلِذَٰلِكَ فَٱدْعُ ۖ وَٱسْتَقِمْ كَمَآ أُمِرْتَ ۖ وَلَا تَتَّبِعْ أَهْوَآءَهُمْ ۖ وَقُلْ ءَامَنتُ بِمَآ أَنزَلَ ٱللَّهُ مِن كِتَٰبٍۢ ۖ وَأُمِرْتُ لِأَعْدِلَ بَيْنَكُمُ ۖ ٱللَّهُ رَبُّنَا وَرَبُّكُمْ ۖ لَنَآ أَعْمَٰلُنَا وَلَكُمْ أَعْمَٰلُكُمْ ۖ لَا حُجَّةَ بَيْنَنَا وَبَيْنَكُمُ ۖ ٱللَّهُ يَجْمَعُ بَيْنَنَا ۖ وَإِلَيْهِ ٱلْمَصِيرُ', 'فلذلك فادع  واستقم كما أمرت  ولا تتبع أهواءهم  وقل ءامنت بما أنزل الله من كتب  وأمرت لأعدل بينكم  الله ربنا وربكم  لنا أعملنا ولكم أعملكم  لا حجة بيننا وبينكم  الله يجمع بيننا  وإليه المصير', NULL, 484, 'local:hafs-text.json'),
  ('hafs-42-16', 'hafs', 42, 16, 'وَٱلَّذِينَ يُحَآجُّونَ فِى ٱللَّهِ مِنۢ بَعْدِ مَا ٱسْتُجِيبَ لَهُۥ حُجَّتُهُمْ دَاحِضَةٌ عِندَ رَبِّهِمْ وَعَلَيْهِمْ غَضَبٌۭ وَلَهُمْ عَذَابٌۭ شَدِيدٌ', 'والذين يحاجون فى الله من بعد ما استجيب له حجتهم داحضة عند ربهم وعليهم غضب ولهم عذاب شديد', NULL, 485, 'local:hafs-text.json'),
  ('hafs-42-17', 'hafs', 42, 17, 'ٱللَّهُ ٱلَّذِىٓ أَنزَلَ ٱلْكِتَٰبَ بِٱلْحَقِّ وَٱلْمِيزَانَ ۗ وَمَا يُدْرِيكَ لَعَلَّ ٱلسَّاعَةَ قَرِيبٌۭ', 'الله الذى أنزل الكتب بالحق والميزان  وما يدريك لعل الساعة قريب', NULL, 485, 'local:hafs-text.json'),
  ('hafs-42-18', 'hafs', 42, 18, 'يَسْتَعْجِلُ بِهَا ٱلَّذِينَ لَا يُؤْمِنُونَ بِهَا ۖ وَٱلَّذِينَ ءَامَنُوا۟ مُشْفِقُونَ مِنْهَا وَيَعْلَمُونَ أَنَّهَا ٱلْحَقُّ ۗ أَلَآ إِنَّ ٱلَّذِينَ يُمَارُونَ فِى ٱلسَّاعَةِ لَفِى ضَلَٰلٍۭ بَعِيدٍ', 'يستعجل بها الذين لا يؤمنون بها  والذين ءامنوا مشفقون منها ويعلمون أنها الحق  ألا إن الذين يمارون فى الساعة لفى ضلل بعيد', NULL, 485, 'local:hafs-text.json'),
  ('hafs-42-19', 'hafs', 42, 19, 'ٱللَّهُ لَطِيفٌۢ بِعِبَادِهِۦ يَرْزُقُ مَن يَشَآءُ ۖ وَهُوَ ٱلْقَوِىُّ ٱلْعَزِيزُ', 'الله لطيف بعباده يرزق من يشاء  وهو القوى العزيز', NULL, 485, 'local:hafs-text.json'),
  ('hafs-42-20', 'hafs', 42, 20, 'مَن كَانَ يُرِيدُ حَرْثَ ٱلْءَاخِرَةِ نَزِدْ لَهُۥ فِى حَرْثِهِۦ ۖ وَمَن كَانَ يُرِيدُ حَرْثَ ٱلدُّنْيَا نُؤْتِهِۦ مِنْهَا وَمَا لَهُۥ فِى ٱلْءَاخِرَةِ مِن نَّصِيبٍ', 'من كان يريد حرث الءاخرة نزد له فى حرثه  ومن كان يريد حرث الدنيا نؤته منها وما له فى الءاخرة من نصيب', NULL, 485, 'local:hafs-text.json'),
  ('hafs-42-21', 'hafs', 42, 21, 'أَمْ لَهُمْ شُرَكَٰٓؤُا۟ شَرَعُوا۟ لَهُم مِّنَ ٱلدِّينِ مَا لَمْ يَأْذَنۢ بِهِ ٱللَّهُ ۚ وَلَوْلَا كَلِمَةُ ٱلْفَصْلِ لَقُضِىَ بَيْنَهُمْ ۗ وَإِنَّ ٱلظَّٰلِمِينَ لَهُمْ عَذَابٌ أَلِيمٌۭ', 'أم لهم شركؤا شرعوا لهم من الدين ما لم يأذن به الله  ولولا كلمة الفصل لقضى بينهم  وإن الظلمين لهم عذاب أليم', NULL, 485, 'local:hafs-text.json'),
  ('hafs-42-22', 'hafs', 42, 22, 'تَرَى ٱلظَّٰلِمِينَ مُشْفِقِينَ مِمَّا كَسَبُوا۟ وَهُوَ وَاقِعٌۢ بِهِمْ ۗ وَٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ فِى رَوْضَاتِ ٱلْجَنَّاتِ ۖ لَهُم مَّا يَشَآءُونَ عِندَ رَبِّهِمْ ۚ ذَٰلِكَ هُوَ ٱلْفَضْلُ ٱلْكَبِيرُ', 'ترى الظلمين مشفقين مما كسبوا وهو واقع بهم  والذين ءامنوا وعملوا الصلحت فى روضات الجنات  لهم ما يشاءون عند ربهم  ذلك هو الفضل الكبير', NULL, 485, 'local:hafs-text.json'),
  ('hafs-42-23', 'hafs', 42, 23, 'ذَٰلِكَ ٱلَّذِى يُبَشِّرُ ٱللَّهُ عِبَادَهُ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ ۗ قُل لَّآ أَسْـَٔلُكُمْ عَلَيْهِ أَجْرًا إِلَّا ٱلْمَوَدَّةَ فِى ٱلْقُرْبَىٰ ۗ وَمَن يَقْتَرِفْ حَسَنَةًۭ نَّزِدْ لَهُۥ فِيهَا حُسْنًا ۚ إِنَّ ٱللَّهَ غَفُورٌۭ شَكُورٌ', 'ذلك الذى يبشر الله عباده الذين ءامنوا وعملوا الصلحت  قل لا أسلكم عليه أجرا إلا المودة فى القربى  ومن يقترف حسنة نزد له فيها حسنا  إن الله غفور شكور', NULL, 486, 'local:hafs-text.json'),
  ('hafs-42-24', 'hafs', 42, 24, 'أَمْ يَقُولُونَ ٱفْتَرَىٰ عَلَى ٱللَّهِ كَذِبًۭا ۖ فَإِن يَشَإِ ٱللَّهُ يَخْتِمْ عَلَىٰ قَلْبِكَ ۗ وَيَمْحُ ٱللَّهُ ٱلْبَٰطِلَ وَيُحِقُّ ٱلْحَقَّ بِكَلِمَٰتِهِۦٓ ۚ إِنَّهُۥ عَلِيمٌۢ بِذَاتِ ٱلصُّدُورِ', 'أم يقولون افترى على الله كذبا  فإن يشإ الله يختم على قلبك  ويمح الله البطل ويحق الحق بكلمته  إنه عليم بذات الصدور', NULL, 486, 'local:hafs-text.json'),
  ('hafs-42-25', 'hafs', 42, 25, 'وَهُوَ ٱلَّذِى يَقْبَلُ ٱلتَّوْبَةَ عَنْ عِبَادِهِۦ وَيَعْفُوا۟ عَنِ ٱلسَّيِّـَٔاتِ وَيَعْلَمُ مَا تَفْعَلُونَ', 'وهو الذى يقبل التوبة عن عباده ويعفوا عن السيات ويعلم ما تفعلون', NULL, 486, 'local:hafs-text.json'),
  ('hafs-42-26', 'hafs', 42, 26, 'وَيَسْتَجِيبُ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ وَيَزِيدُهُم مِّن فَضْلِهِۦ ۚ وَٱلْكَٰفِرُونَ لَهُمْ عَذَابٌۭ شَدِيدٌۭ', 'ويستجيب الذين ءامنوا وعملوا الصلحت ويزيدهم من فضله  والكفرون لهم عذاب شديد', NULL, 486, 'local:hafs-text.json'),
  ('hafs-42-27', 'hafs', 42, 27, '۞ وَلَوْ بَسَطَ ٱللَّهُ ٱلرِّزْقَ لِعِبَادِهِۦ لَبَغَوْا۟ فِى ٱلْأَرْضِ وَلَٰكِن يُنَزِّلُ بِقَدَرٍۢ مَّا يَشَآءُ ۚ إِنَّهُۥ بِعِبَادِهِۦ خَبِيرٌۢ بَصِيرٌۭ', 'ولو بسط الله الرزق لعباده لبغوا فى الأرض ولكن ينزل بقدر ما يشاء  إنه بعباده خبير بصير', NULL, 486, 'local:hafs-text.json'),
  ('hafs-42-28', 'hafs', 42, 28, 'وَهُوَ ٱلَّذِى يُنَزِّلُ ٱلْغَيْثَ مِنۢ بَعْدِ مَا قَنَطُوا۟ وَيَنشُرُ رَحْمَتَهُۥ ۚ وَهُوَ ٱلْوَلِىُّ ٱلْحَمِيدُ', 'وهو الذى ينزل الغيث من بعد ما قنطوا وينشر رحمته  وهو الولى الحميد', NULL, 486, 'local:hafs-text.json'),
  ('hafs-42-29', 'hafs', 42, 29, 'وَمِنْ ءَايَٰتِهِۦ خَلْقُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَمَا بَثَّ فِيهِمَا مِن دَآبَّةٍۢ ۚ وَهُوَ عَلَىٰ جَمْعِهِمْ إِذَا يَشَآءُ قَدِيرٌۭ', 'ومن ءايته خلق السموت والأرض وما بث فيهما من دابة  وهو على جمعهم إذا يشاء قدير', NULL, 486, 'local:hafs-text.json'),
  ('hafs-42-30', 'hafs', 42, 30, 'وَمَآ أَصَٰبَكُم مِّن مُّصِيبَةٍۢ فَبِمَا كَسَبَتْ أَيْدِيكُمْ وَيَعْفُوا۟ عَن كَثِيرٍۢ', 'وما أصبكم من مصيبة فبما كسبت أيديكم ويعفوا عن كثير', NULL, 486, 'local:hafs-text.json'),
  ('hafs-42-31', 'hafs', 42, 31, 'وَمَآ أَنتُم بِمُعْجِزِينَ فِى ٱلْأَرْضِ ۖ وَمَا لَكُم مِّن دُونِ ٱللَّهِ مِن وَلِىٍّۢ وَلَا نَصِيرٍۢ', 'وما أنتم بمعجزين فى الأرض  وما لكم من دون الله من ولى ولا نصير', NULL, 486, 'local:hafs-text.json'),
  ('hafs-42-32', 'hafs', 42, 32, 'وَمِنْ ءَايَٰتِهِ ٱلْجَوَارِ فِى ٱلْبَحْرِ كَٱلْأَعْلَٰمِ', 'ومن ءايته الجوار فى البحر كالأعلم', NULL, 487, 'local:hafs-text.json'),
  ('hafs-42-33', 'hafs', 42, 33, 'إِن يَشَأْ يُسْكِنِ ٱلرِّيحَ فَيَظْلَلْنَ رَوَاكِدَ عَلَىٰ ظَهْرِهِۦٓ ۚ إِنَّ فِى ذَٰلِكَ لَءَايَٰتٍۢ لِّكُلِّ صَبَّارٍۢ شَكُورٍ', 'إن يشأ يسكن الريح فيظللن رواكد على ظهره  إن فى ذلك لءايت لكل صبار شكور', NULL, 487, 'local:hafs-text.json'),
  ('hafs-42-34', 'hafs', 42, 34, 'أَوْ يُوبِقْهُنَّ بِمَا كَسَبُوا۟ وَيَعْفُ عَن كَثِيرٍۢ', 'أو يوبقهن بما كسبوا ويعف عن كثير', NULL, 487, 'local:hafs-text.json'),
  ('hafs-42-35', 'hafs', 42, 35, 'وَيَعْلَمَ ٱلَّذِينَ يُجَٰدِلُونَ فِىٓ ءَايَٰتِنَا مَا لَهُم مِّن مَّحِيصٍۢ', 'ويعلم الذين يجدلون فى ءايتنا ما لهم من محيص', NULL, 487, 'local:hafs-text.json'),
  ('hafs-42-36', 'hafs', 42, 36, 'فَمَآ أُوتِيتُم مِّن شَىْءٍۢ فَمَتَٰعُ ٱلْحَيَوٰةِ ٱلدُّنْيَا ۖ وَمَا عِندَ ٱللَّهِ خَيْرٌۭ وَأَبْقَىٰ لِلَّذِينَ ءَامَنُوا۟ وَعَلَىٰ رَبِّهِمْ يَتَوَكَّلُونَ', 'فما أوتيتم من شىء فمتع الحيوة الدنيا  وما عند الله خير وأبقى للذين ءامنوا وعلى ربهم يتوكلون', NULL, 487, 'local:hafs-text.json'),
  ('hafs-42-37', 'hafs', 42, 37, 'وَٱلَّذِينَ يَجْتَنِبُونَ كَبَٰٓئِرَ ٱلْإِثْمِ وَٱلْفَوَٰحِشَ وَإِذَا مَا غَضِبُوا۟ هُمْ يَغْفِرُونَ', 'والذين يجتنبون كبئر الإثم والفوحش وإذا ما غضبوا هم يغفرون', NULL, 487, 'local:hafs-text.json'),
  ('hafs-42-38', 'hafs', 42, 38, 'وَٱلَّذِينَ ٱسْتَجَابُوا۟ لِرَبِّهِمْ وَأَقَامُوا۟ ٱلصَّلَوٰةَ وَأَمْرُهُمْ شُورَىٰ بَيْنَهُمْ وَمِمَّا رَزَقْنَٰهُمْ يُنفِقُونَ', 'والذين استجابوا لربهم وأقاموا الصلوة وأمرهم شورى بينهم ومما رزقنهم ينفقون', NULL, 487, 'local:hafs-text.json'),
  ('hafs-42-39', 'hafs', 42, 39, 'وَٱلَّذِينَ إِذَآ أَصَابَهُمُ ٱلْبَغْىُ هُمْ يَنتَصِرُونَ', 'والذين إذا أصابهم البغى هم ينتصرون', NULL, 487, 'local:hafs-text.json'),
  ('hafs-42-40', 'hafs', 42, 40, 'وَجَزَٰٓؤُا۟ سَيِّئَةٍۢ سَيِّئَةٌۭ مِّثْلُهَا ۖ فَمَنْ عَفَا وَأَصْلَحَ فَأَجْرُهُۥ عَلَى ٱللَّهِ ۚ إِنَّهُۥ لَا يُحِبُّ ٱلظَّٰلِمِينَ', 'وجزؤا سيئة سيئة مثلها  فمن عفا وأصلح فأجره على الله  إنه لا يحب الظلمين', NULL, 487, 'local:hafs-text.json'),
  ('hafs-42-41', 'hafs', 42, 41, 'وَلَمَنِ ٱنتَصَرَ بَعْدَ ظُلْمِهِۦ فَأُو۟لَٰٓئِكَ مَا عَلَيْهِم مِّن سَبِيلٍ', 'ولمن انتصر بعد ظلمه فأولئك ما عليهم من سبيل', NULL, 487, 'local:hafs-text.json'),
  ('hafs-42-42', 'hafs', 42, 42, 'إِنَّمَا ٱلسَّبِيلُ عَلَى ٱلَّذِينَ يَظْلِمُونَ ٱلنَّاسَ وَيَبْغُونَ فِى ٱلْأَرْضِ بِغَيْرِ ٱلْحَقِّ ۚ أُو۟لَٰٓئِكَ لَهُمْ عَذَابٌ أَلِيمٌۭ', 'إنما السبيل على الذين يظلمون الناس ويبغون فى الأرض بغير الحق  أولئك لهم عذاب أليم', NULL, 487, 'local:hafs-text.json'),
  ('hafs-42-43', 'hafs', 42, 43, 'وَلَمَن صَبَرَ وَغَفَرَ إِنَّ ذَٰلِكَ لَمِنْ عَزْمِ ٱلْأُمُورِ', 'ولمن صبر وغفر إن ذلك لمن عزم الأمور', NULL, 487, 'local:hafs-text.json'),
  ('hafs-42-44', 'hafs', 42, 44, 'وَمَن يُضْلِلِ ٱللَّهُ فَمَا لَهُۥ مِن وَلِىٍّۢ مِّنۢ بَعْدِهِۦ ۗ وَتَرَى ٱلظَّٰلِمِينَ لَمَّا رَأَوُا۟ ٱلْعَذَابَ يَقُولُونَ هَلْ إِلَىٰ مَرَدٍّۢ مِّن سَبِيلٍۢ', 'ومن يضلل الله فما له من ولى من بعده  وترى الظلمين لما رأوا العذاب يقولون هل إلى مرد من سبيل', NULL, 487, 'local:hafs-text.json'),
  ('hafs-42-45', 'hafs', 42, 45, 'وَتَرَىٰهُمْ يُعْرَضُونَ عَلَيْهَا خَٰشِعِينَ مِنَ ٱلذُّلِّ يَنظُرُونَ مِن طَرْفٍ خَفِىٍّۢ ۗ وَقَالَ ٱلَّذِينَ ءَامَنُوٓا۟ إِنَّ ٱلْخَٰسِرِينَ ٱلَّذِينَ خَسِرُوٓا۟ أَنفُسَهُمْ وَأَهْلِيهِمْ يَوْمَ ٱلْقِيَٰمَةِ ۗ أَلَآ إِنَّ ٱلظَّٰلِمِينَ فِى عَذَابٍۢ مُّقِيمٍۢ', 'وترىهم يعرضون عليها خشعين من الذل ينظرون من طرف خفى  وقال الذين ءامنوا إن الخسرين الذين خسروا أنفسهم وأهليهم يوم القيمة  ألا إن الظلمين فى عذاب مقيم', NULL, 488, 'local:hafs-text.json'),
  ('hafs-42-46', 'hafs', 42, 46, 'وَمَا كَانَ لَهُم مِّنْ أَوْلِيَآءَ يَنصُرُونَهُم مِّن دُونِ ٱللَّهِ ۗ وَمَن يُضْلِلِ ٱللَّهُ فَمَا لَهُۥ مِن سَبِيلٍ', 'وما كان لهم من أولياء ينصرونهم من دون الله  ومن يضلل الله فما له من سبيل', NULL, 488, 'local:hafs-text.json'),
  ('hafs-42-47', 'hafs', 42, 47, 'ٱسْتَجِيبُوا۟ لِرَبِّكُم مِّن قَبْلِ أَن يَأْتِىَ يَوْمٌۭ لَّا مَرَدَّ لَهُۥ مِنَ ٱللَّهِ ۚ مَا لَكُم مِّن مَّلْجَإٍۢ يَوْمَئِذٍۢ وَمَا لَكُم مِّن نَّكِيرٍۢ', 'استجيبوا لربكم من قبل أن يأتى يوم لا مرد له من الله  ما لكم من ملجإ يومئذ وما لكم من نكير', NULL, 488, 'local:hafs-text.json'),
  ('hafs-42-48', 'hafs', 42, 48, 'فَإِنْ أَعْرَضُوا۟ فَمَآ أَرْسَلْنَٰكَ عَلَيْهِمْ حَفِيظًا ۖ إِنْ عَلَيْكَ إِلَّا ٱلْبَلَٰغُ ۗ وَإِنَّآ إِذَآ أَذَقْنَا ٱلْإِنسَٰنَ مِنَّا رَحْمَةًۭ فَرِحَ بِهَا ۖ وَإِن تُصِبْهُمْ سَيِّئَةٌۢ بِمَا قَدَّمَتْ أَيْدِيهِمْ فَإِنَّ ٱلْإِنسَٰنَ كَفُورٌۭ', 'فإن أعرضوا فما أرسلنك عليهم حفيظا  إن عليك إلا البلغ  وإنا إذا أذقنا الإنسن منا رحمة فرح بها  وإن تصبهم سيئة بما قدمت أيديهم فإن الإنسن كفور', NULL, 488, 'local:hafs-text.json'),
  ('hafs-42-49', 'hafs', 42, 49, 'لِّلَّهِ مُلْكُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ ۚ يَخْلُقُ مَا يَشَآءُ ۚ يَهَبُ لِمَن يَشَآءُ إِنَٰثًۭا وَيَهَبُ لِمَن يَشَآءُ ٱلذُّكُورَ', 'لله ملك السموت والأرض  يخلق ما يشاء  يهب لمن يشاء إنثا ويهب لمن يشاء الذكور', NULL, 488, 'local:hafs-text.json'),
  ('hafs-42-50', 'hafs', 42, 50, 'أَوْ يُزَوِّجُهُمْ ذُكْرَانًۭا وَإِنَٰثًۭا ۖ وَيَجْعَلُ مَن يَشَآءُ عَقِيمًا ۚ إِنَّهُۥ عَلِيمٌۭ قَدِيرٌۭ', 'أو يزوجهم ذكرانا وإنثا  ويجعل من يشاء عقيما  إنه عليم قدير', NULL, 488, 'local:hafs-text.json'),
  ('hafs-42-51', 'hafs', 42, 51, '۞ وَمَا كَانَ لِبَشَرٍ أَن يُكَلِّمَهُ ٱللَّهُ إِلَّا وَحْيًا أَوْ مِن وَرَآئِ حِجَابٍ أَوْ يُرْسِلَ رَسُولًۭا فَيُوحِىَ بِإِذْنِهِۦ مَا يَشَآءُ ۚ إِنَّهُۥ عَلِىٌّ حَكِيمٌۭ', 'وما كان لبشر أن يكلمه الله إلا وحيا أو من ورائ حجاب أو يرسل رسولا فيوحى بإذنه ما يشاء  إنه على حكيم', NULL, 488, 'local:hafs-text.json'),
  ('hafs-42-52', 'hafs', 42, 52, 'وَكَذَٰلِكَ أَوْحَيْنَآ إِلَيْكَ رُوحًۭا مِّنْ أَمْرِنَا ۚ مَا كُنتَ تَدْرِى مَا ٱلْكِتَٰبُ وَلَا ٱلْإِيمَٰنُ وَلَٰكِن جَعَلْنَٰهُ نُورًۭا نَّهْدِى بِهِۦ مَن نَّشَآءُ مِنْ عِبَادِنَا ۚ وَإِنَّكَ لَتَهْدِىٓ إِلَىٰ صِرَٰطٍۢ مُّسْتَقِيمٍۢ', 'وكذلك أوحينا إليك روحا من أمرنا  ما كنت تدرى ما الكتب ولا الإيمن ولكن جعلنه نورا نهدى به من نشاء من عبادنا  وإنك لتهدى إلى صرط مستقيم', NULL, 489, 'local:hafs-text.json'),
  ('hafs-42-53', 'hafs', 42, 53, 'صِرَٰطِ ٱللَّهِ ٱلَّذِى لَهُۥ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ ۗ أَلَآ إِلَى ٱللَّهِ تَصِيرُ ٱلْأُمُورُ', 'صرط الله الذى له ما فى السموت وما فى الأرض  ألا إلى الله تصير الأمور', NULL, 489, 'local:hafs-text.json'),
  ('hafs-43-1', 'hafs', 43, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ حمٓ', 'بسم الله الرحمن الرحيم حم', NULL, 489, 'local:hafs-text.json'),
  ('hafs-43-2', 'hafs', 43, 2, 'وَٱلْكِتَٰبِ ٱلْمُبِينِ', 'والكتب المبين', NULL, 489, 'local:hafs-text.json'),
  ('hafs-43-3', 'hafs', 43, 3, 'إِنَّا جَعَلْنَٰهُ قُرْءَٰنًا عَرَبِيًّۭا لَّعَلَّكُمْ تَعْقِلُونَ', 'إنا جعلنه قرءنا عربيا لعلكم تعقلون', NULL, 489, 'local:hafs-text.json'),
  ('hafs-43-4', 'hafs', 43, 4, 'وَإِنَّهُۥ فِىٓ أُمِّ ٱلْكِتَٰبِ لَدَيْنَا لَعَلِىٌّ حَكِيمٌ', 'وإنه فى أم الكتب لدينا لعلى حكيم', NULL, 489, 'local:hafs-text.json'),
  ('hafs-43-5', 'hafs', 43, 5, 'أَفَنَضْرِبُ عَنكُمُ ٱلذِّكْرَ صَفْحًا أَن كُنتُمْ قَوْمًۭا مُّسْرِفِينَ', 'أفنضرب عنكم الذكر صفحا أن كنتم قوما مسرفين', NULL, 489, 'local:hafs-text.json'),
  ('hafs-43-6', 'hafs', 43, 6, 'وَكَمْ أَرْسَلْنَا مِن نَّبِىٍّۢ فِى ٱلْأَوَّلِينَ', 'وكم أرسلنا من نبى فى الأولين', NULL, 489, 'local:hafs-text.json'),
  ('hafs-43-7', 'hafs', 43, 7, 'وَمَا يَأْتِيهِم مِّن نَّبِىٍّ إِلَّا كَانُوا۟ بِهِۦ يَسْتَهْزِءُونَ', 'وما يأتيهم من نبى إلا كانوا به يستهزءون', NULL, 489, 'local:hafs-text.json'),
  ('hafs-43-8', 'hafs', 43, 8, 'فَأَهْلَكْنَآ أَشَدَّ مِنْهُم بَطْشًۭا وَمَضَىٰ مَثَلُ ٱلْأَوَّلِينَ', 'فأهلكنا أشد منهم بطشا ومضى مثل الأولين', NULL, 489, 'local:hafs-text.json'),
  ('hafs-43-9', 'hafs', 43, 9, 'وَلَئِن سَأَلْتَهُم مَّنْ خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ لَيَقُولُنَّ خَلَقَهُنَّ ٱلْعَزِيزُ ٱلْعَلِيمُ', 'ولئن سألتهم من خلق السموت والأرض ليقولن خلقهن العزيز العليم', NULL, 489, 'local:hafs-text.json'),
  ('hafs-43-10', 'hafs', 43, 10, 'ٱلَّذِى جَعَلَ لَكُمُ ٱلْأَرْضَ مَهْدًۭا وَجَعَلَ لَكُمْ فِيهَا سُبُلًۭا لَّعَلَّكُمْ تَهْتَدُونَ', 'الذى جعل لكم الأرض مهدا وجعل لكم فيها سبلا لعلكم تهتدون', NULL, 489, 'local:hafs-text.json'),
  ('hafs-43-11', 'hafs', 43, 11, 'وَٱلَّذِى نَزَّلَ مِنَ ٱلسَّمَآءِ مَآءًۢ بِقَدَرٍۢ فَأَنشَرْنَا بِهِۦ بَلْدَةًۭ مَّيْتًۭا ۚ كَذَٰلِكَ تُخْرَجُونَ', 'والذى نزل من السماء ماء بقدر فأنشرنا به بلدة ميتا  كذلك تخرجون', NULL, 490, 'local:hafs-text.json'),
  ('hafs-43-12', 'hafs', 43, 12, 'وَٱلَّذِى خَلَقَ ٱلْأَزْوَٰجَ كُلَّهَا وَجَعَلَ لَكُم مِّنَ ٱلْفُلْكِ وَٱلْأَنْعَٰمِ مَا تَرْكَبُونَ', 'والذى خلق الأزوج كلها وجعل لكم من الفلك والأنعم ما تركبون', NULL, 490, 'local:hafs-text.json'),
  ('hafs-43-13', 'hafs', 43, 13, 'لِتَسْتَوُۥا۟ عَلَىٰ ظُهُورِهِۦ ثُمَّ تَذْكُرُوا۟ نِعْمَةَ رَبِّكُمْ إِذَا ٱسْتَوَيْتُمْ عَلَيْهِ وَتَقُولُوا۟ سُبْحَٰنَ ٱلَّذِى سَخَّرَ لَنَا هَٰذَا وَمَا كُنَّا لَهُۥ مُقْرِنِينَ', 'لتستوا على ظهوره ثم تذكروا نعمة ربكم إذا استويتم عليه وتقولوا سبحن الذى سخر لنا هذا وما كنا له مقرنين', NULL, 490, 'local:hafs-text.json'),
  ('hafs-43-14', 'hafs', 43, 14, 'وَإِنَّآ إِلَىٰ رَبِّنَا لَمُنقَلِبُونَ', 'وإنا إلى ربنا لمنقلبون', NULL, 490, 'local:hafs-text.json'),
  ('hafs-43-15', 'hafs', 43, 15, 'وَجَعَلُوا۟ لَهُۥ مِنْ عِبَادِهِۦ جُزْءًا ۚ إِنَّ ٱلْإِنسَٰنَ لَكَفُورٌۭ مُّبِينٌ', 'وجعلوا له من عباده جزءا  إن الإنسن لكفور مبين', NULL, 490, 'local:hafs-text.json'),
  ('hafs-43-16', 'hafs', 43, 16, 'أَمِ ٱتَّخَذَ مِمَّا يَخْلُقُ بَنَاتٍۢ وَأَصْفَىٰكُم بِٱلْبَنِينَ', 'أم اتخذ مما يخلق بنات وأصفىكم بالبنين', NULL, 490, 'local:hafs-text.json'),
  ('hafs-43-17', 'hafs', 43, 17, 'وَإِذَا بُشِّرَ أَحَدُهُم بِمَا ضَرَبَ لِلرَّحْمَٰنِ مَثَلًۭا ظَلَّ وَجْهُهُۥ مُسْوَدًّۭا وَهُوَ كَظِيمٌ', 'وإذا بشر أحدهم بما ضرب للرحمن مثلا ظل وجهه مسودا وهو كظيم', NULL, 490, 'local:hafs-text.json'),
  ('hafs-43-18', 'hafs', 43, 18, 'أَوَمَن يُنَشَّؤُا۟ فِى ٱلْحِلْيَةِ وَهُوَ فِى ٱلْخِصَامِ غَيْرُ مُبِينٍۢ', 'أومن ينشؤا فى الحلية وهو فى الخصام غير مبين', NULL, 490, 'local:hafs-text.json'),
  ('hafs-43-19', 'hafs', 43, 19, 'وَجَعَلُوا۟ ٱلْمَلَٰٓئِكَةَ ٱلَّذِينَ هُمْ عِبَٰدُ ٱلرَّحْمَٰنِ إِنَٰثًا ۚ أَشَهِدُوا۟ خَلْقَهُمْ ۚ سَتُكْتَبُ شَهَٰدَتُهُمْ وَيُسْـَٔلُونَ', 'وجعلوا الملئكة الذين هم عبد الرحمن إنثا  أشهدوا خلقهم  ستكتب شهدتهم ويسلون', NULL, 490, 'local:hafs-text.json'),
  ('hafs-43-20', 'hafs', 43, 20, 'وَقَالُوا۟ لَوْ شَآءَ ٱلرَّحْمَٰنُ مَا عَبَدْنَٰهُم ۗ مَّا لَهُم بِذَٰلِكَ مِنْ عِلْمٍ ۖ إِنْ هُمْ إِلَّا يَخْرُصُونَ', 'وقالوا لو شاء الرحمن ما عبدنهم  ما لهم بذلك من علم  إن هم إلا يخرصون', NULL, 490, 'local:hafs-text.json'),
  ('hafs-43-21', 'hafs', 43, 21, 'أَمْ ءَاتَيْنَٰهُمْ كِتَٰبًۭا مِّن قَبْلِهِۦ فَهُم بِهِۦ مُسْتَمْسِكُونَ', 'أم ءاتينهم كتبا من قبله فهم به مستمسكون', NULL, 490, 'local:hafs-text.json'),
  ('hafs-43-22', 'hafs', 43, 22, 'بَلْ قَالُوٓا۟ إِنَّا وَجَدْنَآ ءَابَآءَنَا عَلَىٰٓ أُمَّةٍۢ وَإِنَّا عَلَىٰٓ ءَاثَٰرِهِم مُّهْتَدُونَ', 'بل قالوا إنا وجدنا ءاباءنا على أمة وإنا على ءاثرهم مهتدون', NULL, 490, 'local:hafs-text.json'),
  ('hafs-43-23', 'hafs', 43, 23, 'وَكَذَٰلِكَ مَآ أَرْسَلْنَا مِن قَبْلِكَ فِى قَرْيَةٍۢ مِّن نَّذِيرٍ إِلَّا قَالَ مُتْرَفُوهَآ إِنَّا وَجَدْنَآ ءَابَآءَنَا عَلَىٰٓ أُمَّةٍۢ وَإِنَّا عَلَىٰٓ ءَاثَٰرِهِم مُّقْتَدُونَ', 'وكذلك ما أرسلنا من قبلك فى قرية من نذير إلا قال مترفوها إنا وجدنا ءاباءنا على أمة وإنا على ءاثرهم مقتدون', NULL, 491, 'local:hafs-text.json'),
  ('hafs-43-24', 'hafs', 43, 24, '۞ قَٰلَ أَوَلَوْ جِئْتُكُم بِأَهْدَىٰ مِمَّا وَجَدتُّمْ عَلَيْهِ ءَابَآءَكُمْ ۖ قَالُوٓا۟ إِنَّا بِمَآ أُرْسِلْتُم بِهِۦ كَٰفِرُونَ', 'قل أولو جئتكم بأهدى مما وجدتم عليه ءاباءكم  قالوا إنا بما أرسلتم به كفرون', NULL, 491, 'local:hafs-text.json'),
  ('hafs-43-25', 'hafs', 43, 25, 'فَٱنتَقَمْنَا مِنْهُمْ ۖ فَٱنظُرْ كَيْفَ كَانَ عَٰقِبَةُ ٱلْمُكَذِّبِينَ', 'فانتقمنا منهم  فانظر كيف كان عقبة المكذبين', NULL, 491, 'local:hafs-text.json'),
  ('hafs-43-26', 'hafs', 43, 26, 'وَإِذْ قَالَ إِبْرَٰهِيمُ لِأَبِيهِ وَقَوْمِهِۦٓ إِنَّنِى بَرَآءٌۭ مِّمَّا تَعْبُدُونَ', 'وإذ قال إبرهيم لأبيه وقومه إننى براء مما تعبدون', NULL, 491, 'local:hafs-text.json'),
  ('hafs-43-27', 'hafs', 43, 27, 'إِلَّا ٱلَّذِى فَطَرَنِى فَإِنَّهُۥ سَيَهْدِينِ', 'إلا الذى فطرنى فإنه سيهدين', NULL, 491, 'local:hafs-text.json'),
  ('hafs-43-28', 'hafs', 43, 28, 'وَجَعَلَهَا كَلِمَةًۢ بَاقِيَةًۭ فِى عَقِبِهِۦ لَعَلَّهُمْ يَرْجِعُونَ', 'وجعلها كلمة باقية فى عقبه لعلهم يرجعون', NULL, 491, 'local:hafs-text.json'),
  ('hafs-43-29', 'hafs', 43, 29, 'بَلْ مَتَّعْتُ هَٰٓؤُلَآءِ وَءَابَآءَهُمْ حَتَّىٰ جَآءَهُمُ ٱلْحَقُّ وَرَسُولٌۭ مُّبِينٌۭ', 'بل متعت هؤلاء وءاباءهم حتى جاءهم الحق ورسول مبين', NULL, 491, 'local:hafs-text.json'),
  ('hafs-43-30', 'hafs', 43, 30, 'وَلَمَّا جَآءَهُمُ ٱلْحَقُّ قَالُوا۟ هَٰذَا سِحْرٌۭ وَإِنَّا بِهِۦ كَٰفِرُونَ', 'ولما جاءهم الحق قالوا هذا سحر وإنا به كفرون', NULL, 491, 'local:hafs-text.json'),
  ('hafs-43-31', 'hafs', 43, 31, 'وَقَالُوا۟ لَوْلَا نُزِّلَ هَٰذَا ٱلْقُرْءَانُ عَلَىٰ رَجُلٍۢ مِّنَ ٱلْقَرْيَتَيْنِ عَظِيمٍ', 'وقالوا لولا نزل هذا القرءان على رجل من القريتين عظيم', NULL, 491, 'local:hafs-text.json'),
  ('hafs-43-32', 'hafs', 43, 32, 'أَهُمْ يَقْسِمُونَ رَحْمَتَ رَبِّكَ ۚ نَحْنُ قَسَمْنَا بَيْنَهُم مَّعِيشَتَهُمْ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا ۚ وَرَفَعْنَا بَعْضَهُمْ فَوْقَ بَعْضٍۢ دَرَجَٰتٍۢ لِّيَتَّخِذَ بَعْضُهُم بَعْضًۭا سُخْرِيًّۭا ۗ وَرَحْمَتُ رَبِّكَ خَيْرٌۭ مِّمَّا يَجْمَعُونَ', 'أهم يقسمون رحمت ربك  نحن قسمنا بينهم معيشتهم فى الحيوة الدنيا  ورفعنا بعضهم فوق بعض درجت ليتخذ بعضهم بعضا سخريا  ورحمت ربك خير مما يجمعون', NULL, 491, 'local:hafs-text.json'),
  ('hafs-43-33', 'hafs', 43, 33, 'وَلَوْلَآ أَن يَكُونَ ٱلنَّاسُ أُمَّةًۭ وَٰحِدَةًۭ لَّجَعَلْنَا لِمَن يَكْفُرُ بِٱلرَّحْمَٰنِ لِبُيُوتِهِمْ سُقُفًۭا مِّن فِضَّةٍۢ وَمَعَارِجَ عَلَيْهَا يَظْهَرُونَ', 'ولولا أن يكون الناس أمة وحدة لجعلنا لمن يكفر بالرحمن لبيوتهم سقفا من فضة ومعارج عليها يظهرون', NULL, 491, 'local:hafs-text.json'),
  ('hafs-43-34', 'hafs', 43, 34, 'وَلِبُيُوتِهِمْ أَبْوَٰبًۭا وَسُرُرًا عَلَيْهَا يَتَّكِـُٔونَ', 'ولبيوتهم أبوبا وسررا عليها يتكون', NULL, 492, 'local:hafs-text.json'),
  ('hafs-43-35', 'hafs', 43, 35, 'وَزُخْرُفًۭا ۚ وَإِن كُلُّ ذَٰلِكَ لَمَّا مَتَٰعُ ٱلْحَيَوٰةِ ٱلدُّنْيَا ۚ وَٱلْءَاخِرَةُ عِندَ رَبِّكَ لِلْمُتَّقِينَ', 'وزخرفا  وإن كل ذلك لما متع الحيوة الدنيا  والءاخرة عند ربك للمتقين', NULL, 492, 'local:hafs-text.json'),
  ('hafs-43-36', 'hafs', 43, 36, 'وَمَن يَعْشُ عَن ذِكْرِ ٱلرَّحْمَٰنِ نُقَيِّضْ لَهُۥ شَيْطَٰنًۭا فَهُوَ لَهُۥ قَرِينٌۭ', 'ومن يعش عن ذكر الرحمن نقيض له شيطنا فهو له قرين', NULL, 492, 'local:hafs-text.json'),
  ('hafs-43-37', 'hafs', 43, 37, 'وَإِنَّهُمْ لَيَصُدُّونَهُمْ عَنِ ٱلسَّبِيلِ وَيَحْسَبُونَ أَنَّهُم مُّهْتَدُونَ', 'وإنهم ليصدونهم عن السبيل ويحسبون أنهم مهتدون', NULL, 492, 'local:hafs-text.json'),
  ('hafs-43-38', 'hafs', 43, 38, 'حَتَّىٰٓ إِذَا جَآءَنَا قَالَ يَٰلَيْتَ بَيْنِى وَبَيْنَكَ بُعْدَ ٱلْمَشْرِقَيْنِ فَبِئْسَ ٱلْقَرِينُ', 'حتى إذا جاءنا قال يليت بينى وبينك بعد المشرقين فبئس القرين', NULL, 492, 'local:hafs-text.json'),
  ('hafs-43-39', 'hafs', 43, 39, 'وَلَن يَنفَعَكُمُ ٱلْيَوْمَ إِذ ظَّلَمْتُمْ أَنَّكُمْ فِى ٱلْعَذَابِ مُشْتَرِكُونَ', 'ولن ينفعكم اليوم إذ ظلمتم أنكم فى العذاب مشتركون', NULL, 492, 'local:hafs-text.json'),
  ('hafs-43-40', 'hafs', 43, 40, 'أَفَأَنتَ تُسْمِعُ ٱلصُّمَّ أَوْ تَهْدِى ٱلْعُمْىَ وَمَن كَانَ فِى ضَلَٰلٍۢ مُّبِينٍۢ', 'أفأنت تسمع الصم أو تهدى العمى ومن كان فى ضلل مبين', NULL, 492, 'local:hafs-text.json'),
  ('hafs-43-41', 'hafs', 43, 41, 'فَإِمَّا نَذْهَبَنَّ بِكَ فَإِنَّا مِنْهُم مُّنتَقِمُونَ', 'فإما نذهبن بك فإنا منهم منتقمون', NULL, 492, 'local:hafs-text.json'),
  ('hafs-43-42', 'hafs', 43, 42, 'أَوْ نُرِيَنَّكَ ٱلَّذِى وَعَدْنَٰهُمْ فَإِنَّا عَلَيْهِم مُّقْتَدِرُونَ', 'أو نرينك الذى وعدنهم فإنا عليهم مقتدرون', NULL, 492, 'local:hafs-text.json'),
  ('hafs-43-43', 'hafs', 43, 43, 'فَٱسْتَمْسِكْ بِٱلَّذِىٓ أُوحِىَ إِلَيْكَ ۖ إِنَّكَ عَلَىٰ صِرَٰطٍۢ مُّسْتَقِيمٍۢ', 'فاستمسك بالذى أوحى إليك  إنك على صرط مستقيم', NULL, 492, 'local:hafs-text.json'),
  ('hafs-43-44', 'hafs', 43, 44, 'وَإِنَّهُۥ لَذِكْرٌۭ لَّكَ وَلِقَوْمِكَ ۖ وَسَوْفَ تُسْـَٔلُونَ', 'وإنه لذكر لك ولقومك  وسوف تسلون', NULL, 492, 'local:hafs-text.json'),
  ('hafs-43-45', 'hafs', 43, 45, 'وَسْـَٔلْ مَنْ أَرْسَلْنَا مِن قَبْلِكَ مِن رُّسُلِنَآ أَجَعَلْنَا مِن دُونِ ٱلرَّحْمَٰنِ ءَالِهَةًۭ يُعْبَدُونَ', 'وسل من أرسلنا من قبلك من رسلنا أجعلنا من دون الرحمن ءالهة يعبدون', NULL, 492, 'local:hafs-text.json'),
  ('hafs-43-46', 'hafs', 43, 46, 'وَلَقَدْ أَرْسَلْنَا مُوسَىٰ بِـَٔايَٰتِنَآ إِلَىٰ فِرْعَوْنَ وَمَلَإِي۟هِۦ فَقَالَ إِنِّى رَسُولُ رَبِّ ٱلْعَٰلَمِينَ', 'ولقد أرسلنا موسى بايتنا إلى فرعون وملإيه فقال إنى رسول رب العلمين', NULL, 492, 'local:hafs-text.json'),
  ('hafs-43-47', 'hafs', 43, 47, 'فَلَمَّا جَآءَهُم بِـَٔايَٰتِنَآ إِذَا هُم مِّنْهَا يَضْحَكُونَ', 'فلما جاءهم بايتنا إذا هم منها يضحكون', NULL, 492, 'local:hafs-text.json'),
  ('hafs-43-48', 'hafs', 43, 48, 'وَمَا نُرِيهِم مِّنْ ءَايَةٍ إِلَّا هِىَ أَكْبَرُ مِنْ أُخْتِهَا ۖ وَأَخَذْنَٰهُم بِٱلْعَذَابِ لَعَلَّهُمْ يَرْجِعُونَ', 'وما نريهم من ءاية إلا هى أكبر من أختها  وأخذنهم بالعذاب لعلهم يرجعون', NULL, 493, 'local:hafs-text.json'),
  ('hafs-43-49', 'hafs', 43, 49, 'وَقَالُوا۟ يَٰٓأَيُّهَ ٱلسَّاحِرُ ٱدْعُ لَنَا رَبَّكَ بِمَا عَهِدَ عِندَكَ إِنَّنَا لَمُهْتَدُونَ', 'وقالوا يأيه الساحر ادع لنا ربك بما عهد عندك إننا لمهتدون', NULL, 493, 'local:hafs-text.json'),
  ('hafs-43-50', 'hafs', 43, 50, 'فَلَمَّا كَشَفْنَا عَنْهُمُ ٱلْعَذَابَ إِذَا هُمْ يَنكُثُونَ', 'فلما كشفنا عنهم العذاب إذا هم ينكثون', NULL, 493, 'local:hafs-text.json'),
  ('hafs-43-51', 'hafs', 43, 51, 'وَنَادَىٰ فِرْعَوْنُ فِى قَوْمِهِۦ قَالَ يَٰقَوْمِ أَلَيْسَ لِى مُلْكُ مِصْرَ وَهَٰذِهِ ٱلْأَنْهَٰرُ تَجْرِى مِن تَحْتِىٓ ۖ أَفَلَا تُبْصِرُونَ', 'ونادى فرعون فى قومه قال يقوم أليس لى ملك مصر وهذه الأنهر تجرى من تحتى  أفلا تبصرون', NULL, 493, 'local:hafs-text.json'),
  ('hafs-43-52', 'hafs', 43, 52, 'أَمْ أَنَا۠ خَيْرٌۭ مِّنْ هَٰذَا ٱلَّذِى هُوَ مَهِينٌۭ وَلَا يَكَادُ يُبِينُ', 'أم أنا خير من هذا الذى هو مهين ولا يكاد يبين', NULL, 493, 'local:hafs-text.json'),
  ('hafs-43-53', 'hafs', 43, 53, 'فَلَوْلَآ أُلْقِىَ عَلَيْهِ أَسْوِرَةٌۭ مِّن ذَهَبٍ أَوْ جَآءَ مَعَهُ ٱلْمَلَٰٓئِكَةُ مُقْتَرِنِينَ', 'فلولا ألقى عليه أسورة من ذهب أو جاء معه الملئكة مقترنين', NULL, 493, 'local:hafs-text.json'),
  ('hafs-43-54', 'hafs', 43, 54, 'فَٱسْتَخَفَّ قَوْمَهُۥ فَأَطَاعُوهُ ۚ إِنَّهُمْ كَانُوا۟ قَوْمًۭا فَٰسِقِينَ', 'فاستخف قومه فأطاعوه  إنهم كانوا قوما فسقين', NULL, 493, 'local:hafs-text.json'),
  ('hafs-43-55', 'hafs', 43, 55, 'فَلَمَّآ ءَاسَفُونَا ٱنتَقَمْنَا مِنْهُمْ فَأَغْرَقْنَٰهُمْ أَجْمَعِينَ', 'فلما ءاسفونا انتقمنا منهم فأغرقنهم أجمعين', NULL, 493, 'local:hafs-text.json'),
  ('hafs-43-56', 'hafs', 43, 56, 'فَجَعَلْنَٰهُمْ سَلَفًۭا وَمَثَلًۭا لِّلْءَاخِرِينَ', 'فجعلنهم سلفا ومثلا للءاخرين', NULL, 493, 'local:hafs-text.json'),
  ('hafs-43-57', 'hafs', 43, 57, '۞ وَلَمَّا ضُرِبَ ٱبْنُ مَرْيَمَ مَثَلًا إِذَا قَوْمُكَ مِنْهُ يَصِدُّونَ', 'ولما ضرب ابن مريم مثلا إذا قومك منه يصدون', NULL, 493, 'local:hafs-text.json'),
  ('hafs-43-58', 'hafs', 43, 58, 'وَقَالُوٓا۟ ءَأَٰلِهَتُنَا خَيْرٌ أَمْ هُوَ ۚ مَا ضَرَبُوهُ لَكَ إِلَّا جَدَلًۢا ۚ بَلْ هُمْ قَوْمٌ خَصِمُونَ', 'وقالوا ءألهتنا خير أم هو  ما ضربوه لك إلا جدلا  بل هم قوم خصمون', NULL, 493, 'local:hafs-text.json'),
  ('hafs-43-59', 'hafs', 43, 59, 'إِنْ هُوَ إِلَّا عَبْدٌ أَنْعَمْنَا عَلَيْهِ وَجَعَلْنَٰهُ مَثَلًۭا لِّبَنِىٓ إِسْرَٰٓءِيلَ', 'إن هو إلا عبد أنعمنا عليه وجعلنه مثلا لبنى إسرءيل', NULL, 493, 'local:hafs-text.json'),
  ('hafs-43-60', 'hafs', 43, 60, 'وَلَوْ نَشَآءُ لَجَعَلْنَا مِنكُم مَّلَٰٓئِكَةًۭ فِى ٱلْأَرْضِ يَخْلُفُونَ', 'ولو نشاء لجعلنا منكم ملئكة فى الأرض يخلفون', NULL, 493, 'local:hafs-text.json'),
  ('hafs-43-61', 'hafs', 43, 61, 'وَإِنَّهُۥ لَعِلْمٌۭ لِّلسَّاعَةِ فَلَا تَمْتَرُنَّ بِهَا وَٱتَّبِعُونِ ۚ هَٰذَا صِرَٰطٌۭ مُّسْتَقِيمٌۭ', 'وإنه لعلم للساعة فلا تمترن بها واتبعون  هذا صرط مستقيم', NULL, 494, 'local:hafs-text.json'),
  ('hafs-43-62', 'hafs', 43, 62, 'وَلَا يَصُدَّنَّكُمُ ٱلشَّيْطَٰنُ ۖ إِنَّهُۥ لَكُمْ عَدُوٌّۭ مُّبِينٌۭ', 'ولا يصدنكم الشيطن  إنه لكم عدو مبين', NULL, 494, 'local:hafs-text.json'),
  ('hafs-43-63', 'hafs', 43, 63, 'وَلَمَّا جَآءَ عِيسَىٰ بِٱلْبَيِّنَٰتِ قَالَ قَدْ جِئْتُكُم بِٱلْحِكْمَةِ وَلِأُبَيِّنَ لَكُم بَعْضَ ٱلَّذِى تَخْتَلِفُونَ فِيهِ ۖ فَٱتَّقُوا۟ ٱللَّهَ وَأَطِيعُونِ', 'ولما جاء عيسى بالبينت قال قد جئتكم بالحكمة ولأبين لكم بعض الذى تختلفون فيه  فاتقوا الله وأطيعون', NULL, 494, 'local:hafs-text.json'),
  ('hafs-43-64', 'hafs', 43, 64, 'إِنَّ ٱللَّهَ هُوَ رَبِّى وَرَبُّكُمْ فَٱعْبُدُوهُ ۚ هَٰذَا صِرَٰطٌۭ مُّسْتَقِيمٌۭ', 'إن الله هو ربى وربكم فاعبدوه  هذا صرط مستقيم', NULL, 494, 'local:hafs-text.json'),
  ('hafs-43-65', 'hafs', 43, 65, 'فَٱخْتَلَفَ ٱلْأَحْزَابُ مِنۢ بَيْنِهِمْ ۖ فَوَيْلٌۭ لِّلَّذِينَ ظَلَمُوا۟ مِنْ عَذَابِ يَوْمٍ أَلِيمٍ', 'فاختلف الأحزاب من بينهم  فويل للذين ظلموا من عذاب يوم أليم', NULL, 494, 'local:hafs-text.json'),
  ('hafs-43-66', 'hafs', 43, 66, 'هَلْ يَنظُرُونَ إِلَّا ٱلسَّاعَةَ أَن تَأْتِيَهُم بَغْتَةًۭ وَهُمْ لَا يَشْعُرُونَ', 'هل ينظرون إلا الساعة أن تأتيهم بغتة وهم لا يشعرون', NULL, 494, 'local:hafs-text.json'),
  ('hafs-43-67', 'hafs', 43, 67, 'ٱلْأَخِلَّآءُ يَوْمَئِذٍۭ بَعْضُهُمْ لِبَعْضٍ عَدُوٌّ إِلَّا ٱلْمُتَّقِينَ', 'الأخلاء يومئذ بعضهم لبعض عدو إلا المتقين', NULL, 494, 'local:hafs-text.json'),
  ('hafs-43-68', 'hafs', 43, 68, 'يَٰعِبَادِ لَا خَوْفٌ عَلَيْكُمُ ٱلْيَوْمَ وَلَآ أَنتُمْ تَحْزَنُونَ', 'يعباد لا خوف عليكم اليوم ولا أنتم تحزنون', NULL, 494, 'local:hafs-text.json'),
  ('hafs-43-69', 'hafs', 43, 69, 'ٱلَّذِينَ ءَامَنُوا۟ بِـَٔايَٰتِنَا وَكَانُوا۟ مُسْلِمِينَ', 'الذين ءامنوا بايتنا وكانوا مسلمين', NULL, 494, 'local:hafs-text.json'),
  ('hafs-43-70', 'hafs', 43, 70, 'ٱدْخُلُوا۟ ٱلْجَنَّةَ أَنتُمْ وَأَزْوَٰجُكُمْ تُحْبَرُونَ', 'ادخلوا الجنة أنتم وأزوجكم تحبرون', NULL, 494, 'local:hafs-text.json'),
  ('hafs-43-71', 'hafs', 43, 71, 'يُطَافُ عَلَيْهِم بِصِحَافٍۢ مِّن ذَهَبٍۢ وَأَكْوَابٍۢ ۖ وَفِيهَا مَا تَشْتَهِيهِ ٱلْأَنفُسُ وَتَلَذُّ ٱلْأَعْيُنُ ۖ وَأَنتُمْ فِيهَا خَٰلِدُونَ', 'يطاف عليهم بصحاف من ذهب وأكواب  وفيها ما تشتهيه الأنفس وتلذ الأعين  وأنتم فيها خلدون', NULL, 494, 'local:hafs-text.json'),
  ('hafs-43-72', 'hafs', 43, 72, 'وَتِلْكَ ٱلْجَنَّةُ ٱلَّتِىٓ أُورِثْتُمُوهَا بِمَا كُنتُمْ تَعْمَلُونَ', 'وتلك الجنة التى أورثتموها بما كنتم تعملون', NULL, 494, 'local:hafs-text.json'),
  ('hafs-43-73', 'hafs', 43, 73, 'لَكُمْ فِيهَا فَٰكِهَةٌۭ كَثِيرَةٌۭ مِّنْهَا تَأْكُلُونَ', 'لكم فيها فكهة كثيرة منها تأكلون', NULL, 494, 'local:hafs-text.json'),
  ('hafs-43-74', 'hafs', 43, 74, 'إِنَّ ٱلْمُجْرِمِينَ فِى عَذَابِ جَهَنَّمَ خَٰلِدُونَ', 'إن المجرمين فى عذاب جهنم خلدون', NULL, 495, 'local:hafs-text.json'),
  ('hafs-43-75', 'hafs', 43, 75, 'لَا يُفَتَّرُ عَنْهُمْ وَهُمْ فِيهِ مُبْلِسُونَ', 'لا يفتر عنهم وهم فيه مبلسون', NULL, 495, 'local:hafs-text.json')
insert into public.ayahs (id, riwayah, surah_number, ayah_number, text, simple_text, juz, page, source) values
  ('hafs-43-76', 'hafs', 43, 76, 'وَمَا ظَلَمْنَٰهُمْ وَلَٰكِن كَانُوا۟ هُمُ ٱلظَّٰلِمِينَ', 'وما ظلمنهم ولكن كانوا هم الظلمين', NULL, 495, 'local:hafs-text.json'),
  ('hafs-43-77', 'hafs', 43, 77, 'وَنَادَوْا۟ يَٰمَٰلِكُ لِيَقْضِ عَلَيْنَا رَبُّكَ ۖ قَالَ إِنَّكُم مَّٰكِثُونَ', 'ونادوا يملك ليقض علينا ربك  قال إنكم مكثون', NULL, 495, 'local:hafs-text.json'),
  ('hafs-43-78', 'hafs', 43, 78, 'لَقَدْ جِئْنَٰكُم بِٱلْحَقِّ وَلَٰكِنَّ أَكْثَرَكُمْ لِلْحَقِّ كَٰرِهُونَ', 'لقد جئنكم بالحق ولكن أكثركم للحق كرهون', NULL, 495, 'local:hafs-text.json'),
  ('hafs-43-79', 'hafs', 43, 79, 'أَمْ أَبْرَمُوٓا۟ أَمْرًۭا فَإِنَّا مُبْرِمُونَ', 'أم أبرموا أمرا فإنا مبرمون', NULL, 495, 'local:hafs-text.json'),
  ('hafs-43-80', 'hafs', 43, 80, 'أَمْ يَحْسَبُونَ أَنَّا لَا نَسْمَعُ سِرَّهُمْ وَنَجْوَىٰهُم ۚ بَلَىٰ وَرُسُلُنَا لَدَيْهِمْ يَكْتُبُونَ', 'أم يحسبون أنا لا نسمع سرهم ونجوىهم  بلى ورسلنا لديهم يكتبون', NULL, 495, 'local:hafs-text.json'),
  ('hafs-43-81', 'hafs', 43, 81, 'قُلْ إِن كَانَ لِلرَّحْمَٰنِ وَلَدٌۭ فَأَنَا۠ أَوَّلُ ٱلْعَٰبِدِينَ', 'قل إن كان للرحمن ولد فأنا أول العبدين', NULL, 495, 'local:hafs-text.json'),
  ('hafs-43-82', 'hafs', 43, 82, 'سُبْحَٰنَ رَبِّ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ رَبِّ ٱلْعَرْشِ عَمَّا يَصِفُونَ', 'سبحن رب السموت والأرض رب العرش عما يصفون', NULL, 495, 'local:hafs-text.json'),
  ('hafs-43-83', 'hafs', 43, 83, 'فَذَرْهُمْ يَخُوضُوا۟ وَيَلْعَبُوا۟ حَتَّىٰ يُلَٰقُوا۟ يَوْمَهُمُ ٱلَّذِى يُوعَدُونَ', 'فذرهم يخوضوا ويلعبوا حتى يلقوا يومهم الذى يوعدون', NULL, 495, 'local:hafs-text.json'),
  ('hafs-43-84', 'hafs', 43, 84, 'وَهُوَ ٱلَّذِى فِى ٱلسَّمَآءِ إِلَٰهٌۭ وَفِى ٱلْأَرْضِ إِلَٰهٌۭ ۚ وَهُوَ ٱلْحَكِيمُ ٱلْعَلِيمُ', 'وهو الذى فى السماء إله وفى الأرض إله  وهو الحكيم العليم', NULL, 495, 'local:hafs-text.json'),
  ('hafs-43-85', 'hafs', 43, 85, 'وَتَبَارَكَ ٱلَّذِى لَهُۥ مُلْكُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَمَا بَيْنَهُمَا وَعِندَهُۥ عِلْمُ ٱلسَّاعَةِ وَإِلَيْهِ تُرْجَعُونَ', 'وتبارك الذى له ملك السموت والأرض وما بينهما وعنده علم الساعة وإليه ترجعون', NULL, 495, 'local:hafs-text.json'),
  ('hafs-43-86', 'hafs', 43, 86, 'وَلَا يَمْلِكُ ٱلَّذِينَ يَدْعُونَ مِن دُونِهِ ٱلشَّفَٰعَةَ إِلَّا مَن شَهِدَ بِٱلْحَقِّ وَهُمْ يَعْلَمُونَ', 'ولا يملك الذين يدعون من دونه الشفعة إلا من شهد بالحق وهم يعلمون', NULL, 495, 'local:hafs-text.json'),
  ('hafs-43-87', 'hafs', 43, 87, 'وَلَئِن سَأَلْتَهُم مَّنْ خَلَقَهُمْ لَيَقُولُنَّ ٱللَّهُ ۖ فَأَنَّىٰ يُؤْفَكُونَ', 'ولئن سألتهم من خلقهم ليقولن الله  فأنى يؤفكون', NULL, 495, 'local:hafs-text.json'),
  ('hafs-43-88', 'hafs', 43, 88, 'وَقِيلِهِۦ يَٰرَبِّ إِنَّ هَٰٓؤُلَآءِ قَوْمٌۭ لَّا يُؤْمِنُونَ', 'وقيله يرب إن هؤلاء قوم لا يؤمنون', NULL, 495, 'local:hafs-text.json'),
  ('hafs-43-89', 'hafs', 43, 89, 'فَٱصْفَحْ عَنْهُمْ وَقُلْ سَلَٰمٌۭ ۚ فَسَوْفَ يَعْلَمُونَ', 'فاصفح عنهم وقل سلم  فسوف يعلمون', NULL, 495, 'local:hafs-text.json'),
  ('hafs-44-1', 'hafs', 44, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ حمٓ', 'بسم الله الرحمن الرحيم حم', NULL, 496, 'local:hafs-text.json'),
  ('hafs-44-2', 'hafs', 44, 2, 'وَٱلْكِتَٰبِ ٱلْمُبِينِ', 'والكتب المبين', NULL, 496, 'local:hafs-text.json'),
  ('hafs-44-3', 'hafs', 44, 3, 'إِنَّآ أَنزَلْنَٰهُ فِى لَيْلَةٍۢ مُّبَٰرَكَةٍ ۚ إِنَّا كُنَّا مُنذِرِينَ', 'إنا أنزلنه فى ليلة مبركة  إنا كنا منذرين', NULL, 496, 'local:hafs-text.json'),
  ('hafs-44-4', 'hafs', 44, 4, 'فِيهَا يُفْرَقُ كُلُّ أَمْرٍ حَكِيمٍ', 'فيها يفرق كل أمر حكيم', NULL, 496, 'local:hafs-text.json'),
  ('hafs-44-5', 'hafs', 44, 5, 'أَمْرًۭا مِّنْ عِندِنَآ ۚ إِنَّا كُنَّا مُرْسِلِينَ', 'أمرا من عندنا  إنا كنا مرسلين', NULL, 496, 'local:hafs-text.json'),
  ('hafs-44-6', 'hafs', 44, 6, 'رَحْمَةًۭ مِّن رَّبِّكَ ۚ إِنَّهُۥ هُوَ ٱلسَّمِيعُ ٱلْعَلِيمُ', 'رحمة من ربك  إنه هو السميع العليم', NULL, 496, 'local:hafs-text.json'),
  ('hafs-44-7', 'hafs', 44, 7, 'رَبِّ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَمَا بَيْنَهُمَآ ۖ إِن كُنتُم مُّوقِنِينَ', 'رب السموت والأرض وما بينهما  إن كنتم موقنين', NULL, 496, 'local:hafs-text.json'),
  ('hafs-44-8', 'hafs', 44, 8, 'لَآ إِلَٰهَ إِلَّا هُوَ يُحْىِۦ وَيُمِيتُ ۖ رَبُّكُمْ وَرَبُّ ءَابَآئِكُمُ ٱلْأَوَّلِينَ', 'لا إله إلا هو يحى ويميت  ربكم ورب ءابائكم الأولين', NULL, 496, 'local:hafs-text.json'),
  ('hafs-44-9', 'hafs', 44, 9, 'بَلْ هُمْ فِى شَكٍّۢ يَلْعَبُونَ', 'بل هم فى شك يلعبون', NULL, 496, 'local:hafs-text.json'),
  ('hafs-44-10', 'hafs', 44, 10, 'فَٱرْتَقِبْ يَوْمَ تَأْتِى ٱلسَّمَآءُ بِدُخَانٍۢ مُّبِينٍۢ', 'فارتقب يوم تأتى السماء بدخان مبين', NULL, 496, 'local:hafs-text.json'),
  ('hafs-44-11', 'hafs', 44, 11, 'يَغْشَى ٱلنَّاسَ ۖ هَٰذَا عَذَابٌ أَلِيمٌۭ', 'يغشى الناس  هذا عذاب أليم', NULL, 496, 'local:hafs-text.json'),
  ('hafs-44-12', 'hafs', 44, 12, 'رَّبَّنَا ٱكْشِفْ عَنَّا ٱلْعَذَابَ إِنَّا مُؤْمِنُونَ', 'ربنا اكشف عنا العذاب إنا مؤمنون', NULL, 496, 'local:hafs-text.json'),
  ('hafs-44-13', 'hafs', 44, 13, 'أَنَّىٰ لَهُمُ ٱلذِّكْرَىٰ وَقَدْ جَآءَهُمْ رَسُولٌۭ مُّبِينٌۭ', 'أنى لهم الذكرى وقد جاءهم رسول مبين', NULL, 496, 'local:hafs-text.json'),
  ('hafs-44-14', 'hafs', 44, 14, 'ثُمَّ تَوَلَّوْا۟ عَنْهُ وَقَالُوا۟ مُعَلَّمٌۭ مَّجْنُونٌ', 'ثم تولوا عنه وقالوا معلم مجنون', NULL, 496, 'local:hafs-text.json'),
  ('hafs-44-15', 'hafs', 44, 15, 'إِنَّا كَاشِفُوا۟ ٱلْعَذَابِ قَلِيلًا ۚ إِنَّكُمْ عَآئِدُونَ', 'إنا كاشفوا العذاب قليلا  إنكم عائدون', NULL, 496, 'local:hafs-text.json'),
  ('hafs-44-16', 'hafs', 44, 16, 'يَوْمَ نَبْطِشُ ٱلْبَطْشَةَ ٱلْكُبْرَىٰٓ إِنَّا مُنتَقِمُونَ', 'يوم نبطش البطشة الكبرى إنا منتقمون', NULL, 496, 'local:hafs-text.json'),
  ('hafs-44-17', 'hafs', 44, 17, '۞ وَلَقَدْ فَتَنَّا قَبْلَهُمْ قَوْمَ فِرْعَوْنَ وَجَآءَهُمْ رَسُولٌۭ كَرِيمٌ', 'ولقد فتنا قبلهم قوم فرعون وجاءهم رسول كريم', NULL, 496, 'local:hafs-text.json'),
  ('hafs-44-18', 'hafs', 44, 18, 'أَنْ أَدُّوٓا۟ إِلَىَّ عِبَادَ ٱللَّهِ ۖ إِنِّى لَكُمْ رَسُولٌ أَمِينٌۭ', 'أن أدوا إلى عباد الله  إنى لكم رسول أمين', NULL, 496, 'local:hafs-text.json'),
  ('hafs-44-19', 'hafs', 44, 19, 'وَأَن لَّا تَعْلُوا۟ عَلَى ٱللَّهِ ۖ إِنِّىٓ ءَاتِيكُم بِسُلْطَٰنٍۢ مُّبِينٍۢ', 'وأن لا تعلوا على الله  إنى ءاتيكم بسلطن مبين', NULL, 497, 'local:hafs-text.json'),
  ('hafs-44-20', 'hafs', 44, 20, 'وَإِنِّى عُذْتُ بِرَبِّى وَرَبِّكُمْ أَن تَرْجُمُونِ', 'وإنى عذت بربى وربكم أن ترجمون', NULL, 497, 'local:hafs-text.json'),
  ('hafs-44-21', 'hafs', 44, 21, 'وَإِن لَّمْ تُؤْمِنُوا۟ لِى فَٱعْتَزِلُونِ', 'وإن لم تؤمنوا لى فاعتزلون', NULL, 497, 'local:hafs-text.json'),
  ('hafs-44-22', 'hafs', 44, 22, 'فَدَعَا رَبَّهُۥٓ أَنَّ هَٰٓؤُلَآءِ قَوْمٌۭ مُّجْرِمُونَ', 'فدعا ربه أن هؤلاء قوم مجرمون', NULL, 497, 'local:hafs-text.json'),
  ('hafs-44-23', 'hafs', 44, 23, 'فَأَسْرِ بِعِبَادِى لَيْلًا إِنَّكُم مُّتَّبَعُونَ', 'فأسر بعبادى ليلا إنكم متبعون', NULL, 497, 'local:hafs-text.json'),
  ('hafs-44-24', 'hafs', 44, 24, 'وَٱتْرُكِ ٱلْبَحْرَ رَهْوًا ۖ إِنَّهُمْ جُندٌۭ مُّغْرَقُونَ', 'واترك البحر رهوا  إنهم جند مغرقون', NULL, 497, 'local:hafs-text.json'),
  ('hafs-44-25', 'hafs', 44, 25, 'كَمْ تَرَكُوا۟ مِن جَنَّٰتٍۢ وَعُيُونٍۢ', 'كم تركوا من جنت وعيون', NULL, 497, 'local:hafs-text.json'),
  ('hafs-44-26', 'hafs', 44, 26, 'وَزُرُوعٍۢ وَمَقَامٍۢ كَرِيمٍۢ', 'وزروع ومقام كريم', NULL, 497, 'local:hafs-text.json'),
  ('hafs-44-27', 'hafs', 44, 27, 'وَنَعْمَةٍۢ كَانُوا۟ فِيهَا فَٰكِهِينَ', 'ونعمة كانوا فيها فكهين', NULL, 497, 'local:hafs-text.json'),
  ('hafs-44-28', 'hafs', 44, 28, 'كَذَٰلِكَ ۖ وَأَوْرَثْنَٰهَا قَوْمًا ءَاخَرِينَ', 'كذلك  وأورثنها قوما ءاخرين', NULL, 497, 'local:hafs-text.json'),
  ('hafs-44-29', 'hafs', 44, 29, 'فَمَا بَكَتْ عَلَيْهِمُ ٱلسَّمَآءُ وَٱلْأَرْضُ وَمَا كَانُوا۟ مُنظَرِينَ', 'فما بكت عليهم السماء والأرض وما كانوا منظرين', NULL, 497, 'local:hafs-text.json'),
  ('hafs-44-30', 'hafs', 44, 30, 'وَلَقَدْ نَجَّيْنَا بَنِىٓ إِسْرَٰٓءِيلَ مِنَ ٱلْعَذَابِ ٱلْمُهِينِ', 'ولقد نجينا بنى إسرءيل من العذاب المهين', NULL, 497, 'local:hafs-text.json'),
  ('hafs-44-31', 'hafs', 44, 31, 'مِن فِرْعَوْنَ ۚ إِنَّهُۥ كَانَ عَالِيًۭا مِّنَ ٱلْمُسْرِفِينَ', 'من فرعون  إنه كان عاليا من المسرفين', NULL, 497, 'local:hafs-text.json'),
  ('hafs-44-32', 'hafs', 44, 32, 'وَلَقَدِ ٱخْتَرْنَٰهُمْ عَلَىٰ عِلْمٍ عَلَى ٱلْعَٰلَمِينَ', 'ولقد اخترنهم على علم على العلمين', NULL, 497, 'local:hafs-text.json'),
  ('hafs-44-33', 'hafs', 44, 33, 'وَءَاتَيْنَٰهُم مِّنَ ٱلْءَايَٰتِ مَا فِيهِ بَلَٰٓؤٌۭا۟ مُّبِينٌ', 'وءاتينهم من الءايت ما فيه بلؤا مبين', NULL, 497, 'local:hafs-text.json'),
  ('hafs-44-34', 'hafs', 44, 34, 'إِنَّ هَٰٓؤُلَآءِ لَيَقُولُونَ', 'إن هؤلاء ليقولون', NULL, 497, 'local:hafs-text.json'),
  ('hafs-44-35', 'hafs', 44, 35, 'إِنْ هِىَ إِلَّا مَوْتَتُنَا ٱلْأُولَىٰ وَمَا نَحْنُ بِمُنشَرِينَ', 'إن هى إلا موتتنا الأولى وما نحن بمنشرين', NULL, 497, 'local:hafs-text.json'),
  ('hafs-44-36', 'hafs', 44, 36, 'فَأْتُوا۟ بِـَٔابَآئِنَآ إِن كُنتُمْ صَٰدِقِينَ', 'فأتوا بابائنا إن كنتم صدقين', NULL, 497, 'local:hafs-text.json'),
  ('hafs-44-37', 'hafs', 44, 37, 'أَهُمْ خَيْرٌ أَمْ قَوْمُ تُبَّعٍۢ وَٱلَّذِينَ مِن قَبْلِهِمْ ۚ أَهْلَكْنَٰهُمْ ۖ إِنَّهُمْ كَانُوا۟ مُجْرِمِينَ', 'أهم خير أم قوم تبع والذين من قبلهم  أهلكنهم  إنهم كانوا مجرمين', NULL, 497, 'local:hafs-text.json'),
  ('hafs-44-38', 'hafs', 44, 38, 'وَمَا خَلَقْنَا ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ وَمَا بَيْنَهُمَا لَٰعِبِينَ', 'وما خلقنا السموت والأرض وما بينهما لعبين', NULL, 497, 'local:hafs-text.json'),
  ('hafs-44-39', 'hafs', 44, 39, 'مَا خَلَقْنَٰهُمَآ إِلَّا بِٱلْحَقِّ وَلَٰكِنَّ أَكْثَرَهُمْ لَا يَعْلَمُونَ', 'ما خلقنهما إلا بالحق ولكن أكثرهم لا يعلمون', NULL, 497, 'local:hafs-text.json'),
  ('hafs-44-40', 'hafs', 44, 40, 'إِنَّ يَوْمَ ٱلْفَصْلِ مِيقَٰتُهُمْ أَجْمَعِينَ', 'إن يوم الفصل ميقتهم أجمعين', NULL, 498, 'local:hafs-text.json'),
  ('hafs-44-41', 'hafs', 44, 41, 'يَوْمَ لَا يُغْنِى مَوْلًى عَن مَّوْلًۭى شَيْـًۭٔا وَلَا هُمْ يُنصَرُونَ', 'يوم لا يغنى مولى عن مولى شيا ولا هم ينصرون', NULL, 498, 'local:hafs-text.json'),
  ('hafs-44-42', 'hafs', 44, 42, 'إِلَّا مَن رَّحِمَ ٱللَّهُ ۚ إِنَّهُۥ هُوَ ٱلْعَزِيزُ ٱلرَّحِيمُ', 'إلا من رحم الله  إنه هو العزيز الرحيم', NULL, 498, 'local:hafs-text.json'),
  ('hafs-44-43', 'hafs', 44, 43, 'إِنَّ شَجَرَتَ ٱلزَّقُّومِ', 'إن شجرت الزقوم', NULL, 498, 'local:hafs-text.json'),
  ('hafs-44-44', 'hafs', 44, 44, 'طَعَامُ ٱلْأَثِيمِ', 'طعام الأثيم', NULL, 498, 'local:hafs-text.json'),
  ('hafs-44-45', 'hafs', 44, 45, 'كَٱلْمُهْلِ يَغْلِى فِى ٱلْبُطُونِ', 'كالمهل يغلى فى البطون', NULL, 498, 'local:hafs-text.json'),
  ('hafs-44-46', 'hafs', 44, 46, 'كَغَلْىِ ٱلْحَمِيمِ', 'كغلى الحميم', NULL, 498, 'local:hafs-text.json'),
  ('hafs-44-47', 'hafs', 44, 47, 'خُذُوهُ فَٱعْتِلُوهُ إِلَىٰ سَوَآءِ ٱلْجَحِيمِ', 'خذوه فاعتلوه إلى سواء الجحيم', NULL, 498, 'local:hafs-text.json'),
  ('hafs-44-48', 'hafs', 44, 48, 'ثُمَّ صُبُّوا۟ فَوْقَ رَأْسِهِۦ مِنْ عَذَابِ ٱلْحَمِيمِ', 'ثم صبوا فوق رأسه من عذاب الحميم', NULL, 498, 'local:hafs-text.json'),
  ('hafs-44-49', 'hafs', 44, 49, 'ذُقْ إِنَّكَ أَنتَ ٱلْعَزِيزُ ٱلْكَرِيمُ', 'ذق إنك أنت العزيز الكريم', NULL, 498, 'local:hafs-text.json'),
  ('hafs-44-50', 'hafs', 44, 50, 'إِنَّ هَٰذَا مَا كُنتُم بِهِۦ تَمْتَرُونَ', 'إن هذا ما كنتم به تمترون', NULL, 498, 'local:hafs-text.json'),
  ('hafs-44-51', 'hafs', 44, 51, 'إِنَّ ٱلْمُتَّقِينَ فِى مَقَامٍ أَمِينٍۢ', 'إن المتقين فى مقام أمين', NULL, 498, 'local:hafs-text.json'),
  ('hafs-44-52', 'hafs', 44, 52, 'فِى جَنَّٰتٍۢ وَعُيُونٍۢ', 'فى جنت وعيون', NULL, 498, 'local:hafs-text.json'),
  ('hafs-44-53', 'hafs', 44, 53, 'يَلْبَسُونَ مِن سُندُسٍۢ وَإِسْتَبْرَقٍۢ مُّتَقَٰبِلِينَ', 'يلبسون من سندس وإستبرق متقبلين', NULL, 498, 'local:hafs-text.json'),
  ('hafs-44-54', 'hafs', 44, 54, 'كَذَٰلِكَ وَزَوَّجْنَٰهُم بِحُورٍ عِينٍۢ', 'كذلك وزوجنهم بحور عين', NULL, 498, 'local:hafs-text.json'),
  ('hafs-44-55', 'hafs', 44, 55, 'يَدْعُونَ فِيهَا بِكُلِّ فَٰكِهَةٍ ءَامِنِينَ', 'يدعون فيها بكل فكهة ءامنين', NULL, 498, 'local:hafs-text.json'),
  ('hafs-44-56', 'hafs', 44, 56, 'لَا يَذُوقُونَ فِيهَا ٱلْمَوْتَ إِلَّا ٱلْمَوْتَةَ ٱلْأُولَىٰ ۖ وَوَقَىٰهُمْ عَذَابَ ٱلْجَحِيمِ', 'لا يذوقون فيها الموت إلا الموتة الأولى  ووقىهم عذاب الجحيم', NULL, 498, 'local:hafs-text.json'),
  ('hafs-44-57', 'hafs', 44, 57, 'فَضْلًۭا مِّن رَّبِّكَ ۚ ذَٰلِكَ هُوَ ٱلْفَوْزُ ٱلْعَظِيمُ', 'فضلا من ربك  ذلك هو الفوز العظيم', NULL, 498, 'local:hafs-text.json'),
  ('hafs-44-58', 'hafs', 44, 58, 'فَإِنَّمَا يَسَّرْنَٰهُ بِلِسَانِكَ لَعَلَّهُمْ يَتَذَكَّرُونَ', 'فإنما يسرنه بلسانك لعلهم يتذكرون', NULL, 498, 'local:hafs-text.json'),
  ('hafs-44-59', 'hafs', 44, 59, 'فَٱرْتَقِبْ إِنَّهُم مُّرْتَقِبُونَ', 'فارتقب إنهم مرتقبون', NULL, 498, 'local:hafs-text.json'),
  ('hafs-45-1', 'hafs', 45, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ حمٓ', 'بسم الله الرحمن الرحيم حم', NULL, 499, 'local:hafs-text.json'),
  ('hafs-45-2', 'hafs', 45, 2, 'تَنزِيلُ ٱلْكِتَٰبِ مِنَ ٱللَّهِ ٱلْعَزِيزِ ٱلْحَكِيمِ', 'تنزيل الكتب من الله العزيز الحكيم', NULL, 499, 'local:hafs-text.json'),
  ('hafs-45-3', 'hafs', 45, 3, 'إِنَّ فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ لَءَايَٰتٍۢ لِّلْمُؤْمِنِينَ', 'إن فى السموت والأرض لءايت للمؤمنين', NULL, 499, 'local:hafs-text.json'),
  ('hafs-45-4', 'hafs', 45, 4, 'وَفِى خَلْقِكُمْ وَمَا يَبُثُّ مِن دَآبَّةٍ ءَايَٰتٌۭ لِّقَوْمٍۢ يُوقِنُونَ', 'وفى خلقكم وما يبث من دابة ءايت لقوم يوقنون', NULL, 499, 'local:hafs-text.json'),
  ('hafs-45-5', 'hafs', 45, 5, 'وَٱخْتِلَٰفِ ٱلَّيْلِ وَٱلنَّهَارِ وَمَآ أَنزَلَ ٱللَّهُ مِنَ ٱلسَّمَآءِ مِن رِّزْقٍۢ فَأَحْيَا بِهِ ٱلْأَرْضَ بَعْدَ مَوْتِهَا وَتَصْرِيفِ ٱلرِّيَٰحِ ءَايَٰتٌۭ لِّقَوْمٍۢ يَعْقِلُونَ', 'واختلف اليل والنهار وما أنزل الله من السماء من رزق فأحيا به الأرض بعد موتها وتصريف الريح ءايت لقوم يعقلون', NULL, 499, 'local:hafs-text.json'),
  ('hafs-45-6', 'hafs', 45, 6, 'تِلْكَ ءَايَٰتُ ٱللَّهِ نَتْلُوهَا عَلَيْكَ بِٱلْحَقِّ ۖ فَبِأَىِّ حَدِيثٍۭ بَعْدَ ٱللَّهِ وَءَايَٰتِهِۦ يُؤْمِنُونَ', 'تلك ءايت الله نتلوها عليك بالحق  فبأى حديث بعد الله وءايته يؤمنون', NULL, 499, 'local:hafs-text.json'),
  ('hafs-45-7', 'hafs', 45, 7, 'وَيْلٌۭ لِّكُلِّ أَفَّاكٍ أَثِيمٍۢ', 'ويل لكل أفاك أثيم', NULL, 499, 'local:hafs-text.json'),
  ('hafs-45-8', 'hafs', 45, 8, 'يَسْمَعُ ءَايَٰتِ ٱللَّهِ تُتْلَىٰ عَلَيْهِ ثُمَّ يُصِرُّ مُسْتَكْبِرًۭا كَأَن لَّمْ يَسْمَعْهَا ۖ فَبَشِّرْهُ بِعَذَابٍ أَلِيمٍۢ', 'يسمع ءايت الله تتلى عليه ثم يصر مستكبرا كأن لم يسمعها  فبشره بعذاب أليم', NULL, 499, 'local:hafs-text.json'),
  ('hafs-45-9', 'hafs', 45, 9, 'وَإِذَا عَلِمَ مِنْ ءَايَٰتِنَا شَيْـًٔا ٱتَّخَذَهَا هُزُوًا ۚ أُو۟لَٰٓئِكَ لَهُمْ عَذَابٌۭ مُّهِينٌۭ', 'وإذا علم من ءايتنا شيا اتخذها هزوا  أولئك لهم عذاب مهين', NULL, 499, 'local:hafs-text.json'),
  ('hafs-45-10', 'hafs', 45, 10, 'مِّن وَرَآئِهِمْ جَهَنَّمُ ۖ وَلَا يُغْنِى عَنْهُم مَّا كَسَبُوا۟ شَيْـًۭٔا وَلَا مَا ٱتَّخَذُوا۟ مِن دُونِ ٱللَّهِ أَوْلِيَآءَ ۖ وَلَهُمْ عَذَابٌ عَظِيمٌ', 'من ورائهم جهنم  ولا يغنى عنهم ما كسبوا شيا ولا ما اتخذوا من دون الله أولياء  ولهم عذاب عظيم', NULL, 499, 'local:hafs-text.json'),
  ('hafs-45-11', 'hafs', 45, 11, 'هَٰذَا هُدًۭى ۖ وَٱلَّذِينَ كَفَرُوا۟ بِـَٔايَٰتِ رَبِّهِمْ لَهُمْ عَذَابٌۭ مِّن رِّجْزٍ أَلِيمٌ', 'هذا هدى  والذين كفروا بايت ربهم لهم عذاب من رجز أليم', NULL, 499, 'local:hafs-text.json'),
  ('hafs-45-12', 'hafs', 45, 12, '۞ ٱللَّهُ ٱلَّذِى سَخَّرَ لَكُمُ ٱلْبَحْرَ لِتَجْرِىَ ٱلْفُلْكُ فِيهِ بِأَمْرِهِۦ وَلِتَبْتَغُوا۟ مِن فَضْلِهِۦ وَلَعَلَّكُمْ تَشْكُرُونَ', 'الله الذى سخر لكم البحر لتجرى الفلك فيه بأمره ولتبتغوا من فضله ولعلكم تشكرون', NULL, 499, 'local:hafs-text.json'),
  ('hafs-45-13', 'hafs', 45, 13, 'وَسَخَّرَ لَكُم مَّا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ جَمِيعًۭا مِّنْهُ ۚ إِنَّ فِى ذَٰلِكَ لَءَايَٰتٍۢ لِّقَوْمٍۢ يَتَفَكَّرُونَ', 'وسخر لكم ما فى السموت وما فى الأرض جميعا منه  إن فى ذلك لءايت لقوم يتفكرون', NULL, 499, 'local:hafs-text.json'),
  ('hafs-45-14', 'hafs', 45, 14, 'قُل لِّلَّذِينَ ءَامَنُوا۟ يَغْفِرُوا۟ لِلَّذِينَ لَا يَرْجُونَ أَيَّامَ ٱللَّهِ لِيَجْزِىَ قَوْمًۢا بِمَا كَانُوا۟ يَكْسِبُونَ', 'قل للذين ءامنوا يغفروا للذين لا يرجون أيام الله ليجزى قوما بما كانوا يكسبون', NULL, 500, 'local:hafs-text.json'),
  ('hafs-45-15', 'hafs', 45, 15, 'مَنْ عَمِلَ صَٰلِحًۭا فَلِنَفْسِهِۦ ۖ وَمَنْ أَسَآءَ فَعَلَيْهَا ۖ ثُمَّ إِلَىٰ رَبِّكُمْ تُرْجَعُونَ', 'من عمل صلحا فلنفسه  ومن أساء فعليها  ثم إلى ربكم ترجعون', NULL, 500, 'local:hafs-text.json'),
  ('hafs-45-16', 'hafs', 45, 16, 'وَلَقَدْ ءَاتَيْنَا بَنِىٓ إِسْرَٰٓءِيلَ ٱلْكِتَٰبَ وَٱلْحُكْمَ وَٱلنُّبُوَّةَ وَرَزَقْنَٰهُم مِّنَ ٱلطَّيِّبَٰتِ وَفَضَّلْنَٰهُمْ عَلَى ٱلْعَٰلَمِينَ', 'ولقد ءاتينا بنى إسرءيل الكتب والحكم والنبوة ورزقنهم من الطيبت وفضلنهم على العلمين', NULL, 500, 'local:hafs-text.json'),
  ('hafs-45-17', 'hafs', 45, 17, 'وَءَاتَيْنَٰهُم بَيِّنَٰتٍۢ مِّنَ ٱلْأَمْرِ ۖ فَمَا ٱخْتَلَفُوٓا۟ إِلَّا مِنۢ بَعْدِ مَا جَآءَهُمُ ٱلْعِلْمُ بَغْيًۢا بَيْنَهُمْ ۚ إِنَّ رَبَّكَ يَقْضِى بَيْنَهُمْ يَوْمَ ٱلْقِيَٰمَةِ فِيمَا كَانُوا۟ فِيهِ يَخْتَلِفُونَ', 'وءاتينهم بينت من الأمر  فما اختلفوا إلا من بعد ما جاءهم العلم بغيا بينهم  إن ربك يقضى بينهم يوم القيمة فيما كانوا فيه يختلفون', NULL, 500, 'local:hafs-text.json'),
  ('hafs-45-18', 'hafs', 45, 18, 'ثُمَّ جَعَلْنَٰكَ عَلَىٰ شَرِيعَةٍۢ مِّنَ ٱلْأَمْرِ فَٱتَّبِعْهَا وَلَا تَتَّبِعْ أَهْوَآءَ ٱلَّذِينَ لَا يَعْلَمُونَ', 'ثم جعلنك على شريعة من الأمر فاتبعها ولا تتبع أهواء الذين لا يعلمون', NULL, 500, 'local:hafs-text.json'),
  ('hafs-45-19', 'hafs', 45, 19, 'إِنَّهُمْ لَن يُغْنُوا۟ عَنكَ مِنَ ٱللَّهِ شَيْـًۭٔا ۚ وَإِنَّ ٱلظَّٰلِمِينَ بَعْضُهُمْ أَوْلِيَآءُ بَعْضٍۢ ۖ وَٱللَّهُ وَلِىُّ ٱلْمُتَّقِينَ', 'إنهم لن يغنوا عنك من الله شيا  وإن الظلمين بعضهم أولياء بعض  والله ولى المتقين', NULL, 500, 'local:hafs-text.json'),
  ('hafs-45-20', 'hafs', 45, 20, 'هَٰذَا بَصَٰٓئِرُ لِلنَّاسِ وَهُدًۭى وَرَحْمَةٌۭ لِّقَوْمٍۢ يُوقِنُونَ', 'هذا بصئر للناس وهدى ورحمة لقوم يوقنون', NULL, 500, 'local:hafs-text.json'),
  ('hafs-45-21', 'hafs', 45, 21, 'أَمْ حَسِبَ ٱلَّذِينَ ٱجْتَرَحُوا۟ ٱلسَّيِّـَٔاتِ أَن نَّجْعَلَهُمْ كَٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ سَوَآءًۭ مَّحْيَاهُمْ وَمَمَاتُهُمْ ۚ سَآءَ مَا يَحْكُمُونَ', 'أم حسب الذين اجترحوا السيات أن نجعلهم كالذين ءامنوا وعملوا الصلحت سواء محياهم ومماتهم  ساء ما يحكمون', NULL, 500, 'local:hafs-text.json'),
  ('hafs-45-22', 'hafs', 45, 22, 'وَخَلَقَ ٱللَّهُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ بِٱلْحَقِّ وَلِتُجْزَىٰ كُلُّ نَفْسٍۭ بِمَا كَسَبَتْ وَهُمْ لَا يُظْلَمُونَ', 'وخلق الله السموت والأرض بالحق ولتجزى كل نفس بما كسبت وهم لا يظلمون', NULL, 500, 'local:hafs-text.json'),
  ('hafs-45-23', 'hafs', 45, 23, 'أَفَرَءَيْتَ مَنِ ٱتَّخَذَ إِلَٰهَهُۥ هَوَىٰهُ وَأَضَلَّهُ ٱللَّهُ عَلَىٰ عِلْمٍۢ وَخَتَمَ عَلَىٰ سَمْعِهِۦ وَقَلْبِهِۦ وَجَعَلَ عَلَىٰ بَصَرِهِۦ غِشَٰوَةًۭ فَمَن يَهْدِيهِ مِنۢ بَعْدِ ٱللَّهِ ۚ أَفَلَا تَذَكَّرُونَ', 'أفرءيت من اتخذ إلهه هوىه وأضله الله على علم وختم على سمعه وقلبه وجعل على بصره غشوة فمن يهديه من بعد الله  أفلا تذكرون', NULL, 501, 'local:hafs-text.json'),
  ('hafs-45-24', 'hafs', 45, 24, 'وَقَالُوا۟ مَا هِىَ إِلَّا حَيَاتُنَا ٱلدُّنْيَا نَمُوتُ وَنَحْيَا وَمَا يُهْلِكُنَآ إِلَّا ٱلدَّهْرُ ۚ وَمَا لَهُم بِذَٰلِكَ مِنْ عِلْمٍ ۖ إِنْ هُمْ إِلَّا يَظُنُّونَ', 'وقالوا ما هى إلا حياتنا الدنيا نموت ونحيا وما يهلكنا إلا الدهر  وما لهم بذلك من علم  إن هم إلا يظنون', NULL, 501, 'local:hafs-text.json'),
  ('hafs-45-25', 'hafs', 45, 25, 'وَإِذَا تُتْلَىٰ عَلَيْهِمْ ءَايَٰتُنَا بَيِّنَٰتٍۢ مَّا كَانَ حُجَّتَهُمْ إِلَّآ أَن قَالُوا۟ ٱئْتُوا۟ بِـَٔابَآئِنَآ إِن كُنتُمْ صَٰدِقِينَ', 'وإذا تتلى عليهم ءايتنا بينت ما كان حجتهم إلا أن قالوا ائتوا بابائنا إن كنتم صدقين', NULL, 501, 'local:hafs-text.json'),
  ('hafs-45-26', 'hafs', 45, 26, 'قُلِ ٱللَّهُ يُحْيِيكُمْ ثُمَّ يُمِيتُكُمْ ثُمَّ يَجْمَعُكُمْ إِلَىٰ يَوْمِ ٱلْقِيَٰمَةِ لَا رَيْبَ فِيهِ وَلَٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يَعْلَمُونَ', 'قل الله يحييكم ثم يميتكم ثم يجمعكم إلى يوم القيمة لا ريب فيه ولكن أكثر الناس لا يعلمون', NULL, 501, 'local:hafs-text.json'),
  ('hafs-45-27', 'hafs', 45, 27, 'وَلِلَّهِ مُلْكُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ ۚ وَيَوْمَ تَقُومُ ٱلسَّاعَةُ يَوْمَئِذٍۢ يَخْسَرُ ٱلْمُبْطِلُونَ', 'ولله ملك السموت والأرض  ويوم تقوم الساعة يومئذ يخسر المبطلون', NULL, 501, 'local:hafs-text.json'),
  ('hafs-45-28', 'hafs', 45, 28, 'وَتَرَىٰ كُلَّ أُمَّةٍۢ جَاثِيَةًۭ ۚ كُلُّ أُمَّةٍۢ تُدْعَىٰٓ إِلَىٰ كِتَٰبِهَا ٱلْيَوْمَ تُجْزَوْنَ مَا كُنتُمْ تَعْمَلُونَ', 'وترى كل أمة جاثية  كل أمة تدعى إلى كتبها اليوم تجزون ما كنتم تعملون', NULL, 501, 'local:hafs-text.json'),
  ('hafs-45-29', 'hafs', 45, 29, 'هَٰذَا كِتَٰبُنَا يَنطِقُ عَلَيْكُم بِٱلْحَقِّ ۚ إِنَّا كُنَّا نَسْتَنسِخُ مَا كُنتُمْ تَعْمَلُونَ', 'هذا كتبنا ينطق عليكم بالحق  إنا كنا نستنسخ ما كنتم تعملون', NULL, 501, 'local:hafs-text.json'),
  ('hafs-45-30', 'hafs', 45, 30, 'فَأَمَّا ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ فَيُدْخِلُهُمْ رَبُّهُمْ فِى رَحْمَتِهِۦ ۚ ذَٰلِكَ هُوَ ٱلْفَوْزُ ٱلْمُبِينُ', 'فأما الذين ءامنوا وعملوا الصلحت فيدخلهم ربهم فى رحمته  ذلك هو الفوز المبين', NULL, 501, 'local:hafs-text.json'),
  ('hafs-45-31', 'hafs', 45, 31, 'وَأَمَّا ٱلَّذِينَ كَفَرُوٓا۟ أَفَلَمْ تَكُنْ ءَايَٰتِى تُتْلَىٰ عَلَيْكُمْ فَٱسْتَكْبَرْتُمْ وَكُنتُمْ قَوْمًۭا مُّجْرِمِينَ', 'وأما الذين كفروا أفلم تكن ءايتى تتلى عليكم فاستكبرتم وكنتم قوما مجرمين', NULL, 501, 'local:hafs-text.json'),
  ('hafs-45-32', 'hafs', 45, 32, 'وَإِذَا قِيلَ إِنَّ وَعْدَ ٱللَّهِ حَقٌّۭ وَٱلسَّاعَةُ لَا رَيْبَ فِيهَا قُلْتُم مَّا نَدْرِى مَا ٱلسَّاعَةُ إِن نَّظُنُّ إِلَّا ظَنًّۭا وَمَا نَحْنُ بِمُسْتَيْقِنِينَ', 'وإذا قيل إن وعد الله حق والساعة لا ريب فيها قلتم ما ندرى ما الساعة إن نظن إلا ظنا وما نحن بمستيقنين', NULL, 501, 'local:hafs-text.json'),
  ('hafs-45-33', 'hafs', 45, 33, 'وَبَدَا لَهُمْ سَيِّـَٔاتُ مَا عَمِلُوا۟ وَحَاقَ بِهِم مَّا كَانُوا۟ بِهِۦ يَسْتَهْزِءُونَ', 'وبدا لهم سيات ما عملوا وحاق بهم ما كانوا به يستهزءون', NULL, 502, 'local:hafs-text.json'),
  ('hafs-45-34', 'hafs', 45, 34, 'وَقِيلَ ٱلْيَوْمَ نَنسَىٰكُمْ كَمَا نَسِيتُمْ لِقَآءَ يَوْمِكُمْ هَٰذَا وَمَأْوَىٰكُمُ ٱلنَّارُ وَمَا لَكُم مِّن نَّٰصِرِينَ', 'وقيل اليوم ننسىكم كما نسيتم لقاء يومكم هذا ومأوىكم النار وما لكم من نصرين', NULL, 502, 'local:hafs-text.json'),
  ('hafs-45-35', 'hafs', 45, 35, 'ذَٰلِكُم بِأَنَّكُمُ ٱتَّخَذْتُمْ ءَايَٰتِ ٱللَّهِ هُزُوًۭا وَغَرَّتْكُمُ ٱلْحَيَوٰةُ ٱلدُّنْيَا ۚ فَٱلْيَوْمَ لَا يُخْرَجُونَ مِنْهَا وَلَا هُمْ يُسْتَعْتَبُونَ', 'ذلكم بأنكم اتخذتم ءايت الله هزوا وغرتكم الحيوة الدنيا  فاليوم لا يخرجون منها ولا هم يستعتبون', NULL, 502, 'local:hafs-text.json'),
  ('hafs-45-36', 'hafs', 45, 36, 'فَلِلَّهِ ٱلْحَمْدُ رَبِّ ٱلسَّمَٰوَٰتِ وَرَبِّ ٱلْأَرْضِ رَبِّ ٱلْعَٰلَمِينَ', 'فلله الحمد رب السموت ورب الأرض رب العلمين', NULL, 502, 'local:hafs-text.json'),
  ('hafs-45-37', 'hafs', 45, 37, 'وَلَهُ ٱلْكِبْرِيَآءُ فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ ۖ وَهُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ', 'وله الكبرياء فى السموت والأرض  وهو العزيز الحكيم', NULL, 502, 'local:hafs-text.json'),
  ('hafs-46-1', 'hafs', 46, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ حمٓ', 'بسم الله الرحمن الرحيم حم', NULL, 502, 'local:hafs-text.json'),
  ('hafs-46-2', 'hafs', 46, 2, 'تَنزِيلُ ٱلْكِتَٰبِ مِنَ ٱللَّهِ ٱلْعَزِيزِ ٱلْحَكِيمِ', 'تنزيل الكتب من الله العزيز الحكيم', NULL, 502, 'local:hafs-text.json'),
  ('hafs-46-3', 'hafs', 46, 3, 'مَا خَلَقْنَا ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ وَمَا بَيْنَهُمَآ إِلَّا بِٱلْحَقِّ وَأَجَلٍۢ مُّسَمًّۭى ۚ وَٱلَّذِينَ كَفَرُوا۟ عَمَّآ أُنذِرُوا۟ مُعْرِضُونَ', 'ما خلقنا السموت والأرض وما بينهما إلا بالحق وأجل مسمى  والذين كفروا عما أنذروا معرضون', NULL, 502, 'local:hafs-text.json'),
  ('hafs-46-4', 'hafs', 46, 4, 'قُلْ أَرَءَيْتُم مَّا تَدْعُونَ مِن دُونِ ٱللَّهِ أَرُونِى مَاذَا خَلَقُوا۟ مِنَ ٱلْأَرْضِ أَمْ لَهُمْ شِرْكٌۭ فِى ٱلسَّمَٰوَٰتِ ۖ ٱئْتُونِى بِكِتَٰبٍۢ مِّن قَبْلِ هَٰذَآ أَوْ أَثَٰرَةٍۢ مِّنْ عِلْمٍ إِن كُنتُمْ صَٰدِقِينَ', 'قل أرءيتم ما تدعون من دون الله أرونى ماذا خلقوا من الأرض أم لهم شرك فى السموت  ائتونى بكتب من قبل هذا أو أثرة من علم إن كنتم صدقين', NULL, 502, 'local:hafs-text.json'),
  ('hafs-46-5', 'hafs', 46, 5, 'وَمَنْ أَضَلُّ مِمَّن يَدْعُوا۟ مِن دُونِ ٱللَّهِ مَن لَّا يَسْتَجِيبُ لَهُۥٓ إِلَىٰ يَوْمِ ٱلْقِيَٰمَةِ وَهُمْ عَن دُعَآئِهِمْ غَٰفِلُونَ', 'ومن أضل ممن يدعوا من دون الله من لا يستجيب له إلى يوم القيمة وهم عن دعائهم غفلون', NULL, 502, 'local:hafs-text.json'),
  ('hafs-46-6', 'hafs', 46, 6, 'وَإِذَا حُشِرَ ٱلنَّاسُ كَانُوا۟ لَهُمْ أَعْدَآءًۭ وَكَانُوا۟ بِعِبَادَتِهِمْ كَٰفِرِينَ', 'وإذا حشر الناس كانوا لهم أعداء وكانوا بعبادتهم كفرين', NULL, 503, 'local:hafs-text.json'),
  ('hafs-46-7', 'hafs', 46, 7, 'وَإِذَا تُتْلَىٰ عَلَيْهِمْ ءَايَٰتُنَا بَيِّنَٰتٍۢ قَالَ ٱلَّذِينَ كَفَرُوا۟ لِلْحَقِّ لَمَّا جَآءَهُمْ هَٰذَا سِحْرٌۭ مُّبِينٌ', 'وإذا تتلى عليهم ءايتنا بينت قال الذين كفروا للحق لما جاءهم هذا سحر مبين', NULL, 503, 'local:hafs-text.json'),
  ('hafs-46-8', 'hafs', 46, 8, 'أَمْ يَقُولُونَ ٱفْتَرَىٰهُ ۖ قُلْ إِنِ ٱفْتَرَيْتُهُۥ فَلَا تَمْلِكُونَ لِى مِنَ ٱللَّهِ شَيْـًٔا ۖ هُوَ أَعْلَمُ بِمَا تُفِيضُونَ فِيهِ ۖ كَفَىٰ بِهِۦ شَهِيدًۢا بَيْنِى وَبَيْنَكُمْ ۖ وَهُوَ ٱلْغَفُورُ ٱلرَّحِيمُ', 'أم يقولون افترىه  قل إن افتريته فلا تملكون لى من الله شيا  هو أعلم بما تفيضون فيه  كفى به شهيدا بينى وبينكم  وهو الغفور الرحيم', NULL, 503, 'local:hafs-text.json'),
  ('hafs-46-9', 'hafs', 46, 9, 'قُلْ مَا كُنتُ بِدْعًۭا مِّنَ ٱلرُّسُلِ وَمَآ أَدْرِى مَا يُفْعَلُ بِى وَلَا بِكُمْ ۖ إِنْ أَتَّبِعُ إِلَّا مَا يُوحَىٰٓ إِلَىَّ وَمَآ أَنَا۠ إِلَّا نَذِيرٌۭ مُّبِينٌۭ', 'قل ما كنت بدعا من الرسل وما أدرى ما يفعل بى ولا بكم  إن أتبع إلا ما يوحى إلى وما أنا إلا نذير مبين', NULL, 503, 'local:hafs-text.json'),
  ('hafs-46-10', 'hafs', 46, 10, 'قُلْ أَرَءَيْتُمْ إِن كَانَ مِنْ عِندِ ٱللَّهِ وَكَفَرْتُم بِهِۦ وَشَهِدَ شَاهِدٌۭ مِّنۢ بَنِىٓ إِسْرَٰٓءِيلَ عَلَىٰ مِثْلِهِۦ فَـَٔامَنَ وَٱسْتَكْبَرْتُمْ ۖ إِنَّ ٱللَّهَ لَا يَهْدِى ٱلْقَوْمَ ٱلظَّٰلِمِينَ', 'قل أرءيتم إن كان من عند الله وكفرتم به وشهد شاهد من بنى إسرءيل على مثله فامن واستكبرتم  إن الله لا يهدى القوم الظلمين', NULL, 503, 'local:hafs-text.json'),
  ('hafs-46-11', 'hafs', 46, 11, 'وَقَالَ ٱلَّذِينَ كَفَرُوا۟ لِلَّذِينَ ءَامَنُوا۟ لَوْ كَانَ خَيْرًۭا مَّا سَبَقُونَآ إِلَيْهِ ۚ وَإِذْ لَمْ يَهْتَدُوا۟ بِهِۦ فَسَيَقُولُونَ هَٰذَآ إِفْكٌۭ قَدِيمٌۭ', 'وقال الذين كفروا للذين ءامنوا لو كان خيرا ما سبقونا إليه  وإذ لم يهتدوا به فسيقولون هذا إفك قديم', NULL, 503, 'local:hafs-text.json'),
  ('hafs-46-12', 'hafs', 46, 12, 'وَمِن قَبْلِهِۦ كِتَٰبُ مُوسَىٰٓ إِمَامًۭا وَرَحْمَةًۭ ۚ وَهَٰذَا كِتَٰبٌۭ مُّصَدِّقٌۭ لِّسَانًا عَرَبِيًّۭا لِّيُنذِرَ ٱلَّذِينَ ظَلَمُوا۟ وَبُشْرَىٰ لِلْمُحْسِنِينَ', 'ومن قبله كتب موسى إماما ورحمة  وهذا كتب مصدق لسانا عربيا لينذر الذين ظلموا وبشرى للمحسنين', NULL, 503, 'local:hafs-text.json'),
  ('hafs-46-13', 'hafs', 46, 13, 'إِنَّ ٱلَّذِينَ قَالُوا۟ رَبُّنَا ٱللَّهُ ثُمَّ ٱسْتَقَٰمُوا۟ فَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ', 'إن الذين قالوا ربنا الله ثم استقموا فلا خوف عليهم ولا هم يحزنون', NULL, 503, 'local:hafs-text.json'),
  ('hafs-46-14', 'hafs', 46, 14, 'أُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلْجَنَّةِ خَٰلِدِينَ فِيهَا جَزَآءًۢ بِمَا كَانُوا۟ يَعْمَلُونَ', 'أولئك أصحب الجنة خلدين فيها جزاء بما كانوا يعملون', NULL, 503, 'local:hafs-text.json'),
  ('hafs-46-15', 'hafs', 46, 15, 'وَوَصَّيْنَا ٱلْإِنسَٰنَ بِوَٰلِدَيْهِ إِحْسَٰنًا ۖ حَمَلَتْهُ أُمُّهُۥ كُرْهًۭا وَوَضَعَتْهُ كُرْهًۭا ۖ وَحَمْلُهُۥ وَفِصَٰلُهُۥ ثَلَٰثُونَ شَهْرًا ۚ حَتَّىٰٓ إِذَا بَلَغَ أَشُدَّهُۥ وَبَلَغَ أَرْبَعِينَ سَنَةًۭ قَالَ رَبِّ أَوْزِعْنِىٓ أَنْ أَشْكُرَ نِعْمَتَكَ ٱلَّتِىٓ أَنْعَمْتَ عَلَىَّ وَعَلَىٰ وَٰلِدَىَّ وَأَنْ أَعْمَلَ صَٰلِحًۭا تَرْضَىٰهُ وَأَصْلِحْ لِى فِى ذُرِّيَّتِىٓ ۖ إِنِّى تُبْتُ إِلَيْكَ وَإِنِّى مِنَ ٱلْمُسْلِمِينَ', 'ووصينا الإنسن بولديه إحسنا  حملته أمه كرها ووضعته كرها  وحمله وفصله ثلثون شهرا  حتى إذا بلغ أشده وبلغ أربعين سنة قال رب أوزعنى أن أشكر نعمتك التى أنعمت على وعلى ولدى وأن أعمل صلحا ترضىه وأصلح لى فى ذريتى  إنى تبت إليك وإنى من المسلمين', NULL, 504, 'local:hafs-text.json'),
  ('hafs-46-16', 'hafs', 46, 16, 'أُو۟لَٰٓئِكَ ٱلَّذِينَ نَتَقَبَّلُ عَنْهُمْ أَحْسَنَ مَا عَمِلُوا۟ وَنَتَجَاوَزُ عَن سَيِّـَٔاتِهِمْ فِىٓ أَصْحَٰبِ ٱلْجَنَّةِ ۖ وَعْدَ ٱلصِّدْقِ ٱلَّذِى كَانُوا۟ يُوعَدُونَ', 'أولئك الذين نتقبل عنهم أحسن ما عملوا ونتجاوز عن سياتهم فى أصحب الجنة  وعد الصدق الذى كانوا يوعدون', NULL, 504, 'local:hafs-text.json'),
  ('hafs-46-17', 'hafs', 46, 17, 'وَٱلَّذِى قَالَ لِوَٰلِدَيْهِ أُفٍّۢ لَّكُمَآ أَتَعِدَانِنِىٓ أَنْ أُخْرَجَ وَقَدْ خَلَتِ ٱلْقُرُونُ مِن قَبْلِى وَهُمَا يَسْتَغِيثَانِ ٱللَّهَ وَيْلَكَ ءَامِنْ إِنَّ وَعْدَ ٱللَّهِ حَقٌّۭ فَيَقُولُ مَا هَٰذَآ إِلَّآ أَسَٰطِيرُ ٱلْأَوَّلِينَ', 'والذى قال لولديه أف لكما أتعداننى أن أخرج وقد خلت القرون من قبلى وهما يستغيثان الله ويلك ءامن إن وعد الله حق فيقول ما هذا إلا أسطير الأولين', NULL, 504, 'local:hafs-text.json'),
  ('hafs-46-18', 'hafs', 46, 18, 'أُو۟لَٰٓئِكَ ٱلَّذِينَ حَقَّ عَلَيْهِمُ ٱلْقَوْلُ فِىٓ أُمَمٍۢ قَدْ خَلَتْ مِن قَبْلِهِم مِّنَ ٱلْجِنِّ وَٱلْإِنسِ ۖ إِنَّهُمْ كَانُوا۟ خَٰسِرِينَ', 'أولئك الذين حق عليهم القول فى أمم قد خلت من قبلهم من الجن والإنس  إنهم كانوا خسرين', NULL, 504, 'local:hafs-text.json'),
  ('hafs-46-19', 'hafs', 46, 19, 'وَلِكُلٍّۢ دَرَجَٰتٌۭ مِّمَّا عَمِلُوا۟ ۖ وَلِيُوَفِّيَهُمْ أَعْمَٰلَهُمْ وَهُمْ لَا يُظْلَمُونَ', 'ولكل درجت مما عملوا  وليوفيهم أعملهم وهم لا يظلمون', NULL, 504, 'local:hafs-text.json'),
  ('hafs-46-20', 'hafs', 46, 20, 'وَيَوْمَ يُعْرَضُ ٱلَّذِينَ كَفَرُوا۟ عَلَى ٱلنَّارِ أَذْهَبْتُمْ طَيِّبَٰتِكُمْ فِى حَيَاتِكُمُ ٱلدُّنْيَا وَٱسْتَمْتَعْتُم بِهَا فَٱلْيَوْمَ تُجْزَوْنَ عَذَابَ ٱلْهُونِ بِمَا كُنتُمْ تَسْتَكْبِرُونَ فِى ٱلْأَرْضِ بِغَيْرِ ٱلْحَقِّ وَبِمَا كُنتُمْ تَفْسُقُونَ', 'ويوم يعرض الذين كفروا على النار أذهبتم طيبتكم فى حياتكم الدنيا واستمتعتم بها فاليوم تجزون عذاب الهون بما كنتم تستكبرون فى الأرض بغير الحق وبما كنتم تفسقون', NULL, 504, 'local:hafs-text.json'),
  ('hafs-46-21', 'hafs', 46, 21, '۞ وَٱذْكُرْ أَخَا عَادٍ إِذْ أَنذَرَ قَوْمَهُۥ بِٱلْأَحْقَافِ وَقَدْ خَلَتِ ٱلنُّذُرُ مِنۢ بَيْنِ يَدَيْهِ وَمِنْ خَلْفِهِۦٓ أَلَّا تَعْبُدُوٓا۟ إِلَّا ٱللَّهَ إِنِّىٓ أَخَافُ عَلَيْكُمْ عَذَابَ يَوْمٍ عَظِيمٍۢ', 'واذكر أخا عاد إذ أنذر قومه بالأحقاف وقد خلت النذر من بين يديه ومن خلفه ألا تعبدوا إلا الله إنى أخاف عليكم عذاب يوم عظيم', NULL, 505, 'local:hafs-text.json'),
  ('hafs-46-22', 'hafs', 46, 22, 'قَالُوٓا۟ أَجِئْتَنَا لِتَأْفِكَنَا عَنْ ءَالِهَتِنَا فَأْتِنَا بِمَا تَعِدُنَآ إِن كُنتَ مِنَ ٱلصَّٰدِقِينَ', 'قالوا أجئتنا لتأفكنا عن ءالهتنا فأتنا بما تعدنا إن كنت من الصدقين', NULL, 505, 'local:hafs-text.json'),
  ('hafs-46-23', 'hafs', 46, 23, 'قَالَ إِنَّمَا ٱلْعِلْمُ عِندَ ٱللَّهِ وَأُبَلِّغُكُم مَّآ أُرْسِلْتُ بِهِۦ وَلَٰكِنِّىٓ أَرَىٰكُمْ قَوْمًۭا تَجْهَلُونَ', 'قال إنما العلم عند الله وأبلغكم ما أرسلت به ولكنى أرىكم قوما تجهلون', NULL, 505, 'local:hafs-text.json'),
  ('hafs-46-24', 'hafs', 46, 24, 'فَلَمَّا رَأَوْهُ عَارِضًۭا مُّسْتَقْبِلَ أَوْدِيَتِهِمْ قَالُوا۟ هَٰذَا عَارِضٌۭ مُّمْطِرُنَا ۚ بَلْ هُوَ مَا ٱسْتَعْجَلْتُم بِهِۦ ۖ رِيحٌۭ فِيهَا عَذَابٌ أَلِيمٌۭ', 'فلما رأوه عارضا مستقبل أوديتهم قالوا هذا عارض ممطرنا  بل هو ما استعجلتم به  ريح فيها عذاب أليم', NULL, 505, 'local:hafs-text.json'),
  ('hafs-46-25', 'hafs', 46, 25, 'تُدَمِّرُ كُلَّ شَىْءٍۭ بِأَمْرِ رَبِّهَا فَأَصْبَحُوا۟ لَا يُرَىٰٓ إِلَّا مَسَٰكِنُهُمْ ۚ كَذَٰلِكَ نَجْزِى ٱلْقَوْمَ ٱلْمُجْرِمِينَ', 'تدمر كل شىء بأمر ربها فأصبحوا لا يرى إلا مسكنهم  كذلك نجزى القوم المجرمين', NULL, 505, 'local:hafs-text.json'),
  ('hafs-46-26', 'hafs', 46, 26, 'وَلَقَدْ مَكَّنَّٰهُمْ فِيمَآ إِن مَّكَّنَّٰكُمْ فِيهِ وَجَعَلْنَا لَهُمْ سَمْعًۭا وَأَبْصَٰرًۭا وَأَفْـِٔدَةًۭ فَمَآ أَغْنَىٰ عَنْهُمْ سَمْعُهُمْ وَلَآ أَبْصَٰرُهُمْ وَلَآ أَفْـِٔدَتُهُم مِّن شَىْءٍ إِذْ كَانُوا۟ يَجْحَدُونَ بِـَٔايَٰتِ ٱللَّهِ وَحَاقَ بِهِم مَّا كَانُوا۟ بِهِۦ يَسْتَهْزِءُونَ', 'ولقد مكنهم فيما إن مكنكم فيه وجعلنا لهم سمعا وأبصرا وأفدة فما أغنى عنهم سمعهم ولا أبصرهم ولا أفدتهم من شىء إذ كانوا يجحدون بايت الله وحاق بهم ما كانوا به يستهزءون', NULL, 505, 'local:hafs-text.json'),
  ('hafs-46-27', 'hafs', 46, 27, 'وَلَقَدْ أَهْلَكْنَا مَا حَوْلَكُم مِّنَ ٱلْقُرَىٰ وَصَرَّفْنَا ٱلْءَايَٰتِ لَعَلَّهُمْ يَرْجِعُونَ', 'ولقد أهلكنا ما حولكم من القرى وصرفنا الءايت لعلهم يرجعون', NULL, 505, 'local:hafs-text.json'),
  ('hafs-46-28', 'hafs', 46, 28, 'فَلَوْلَا نَصَرَهُمُ ٱلَّذِينَ ٱتَّخَذُوا۟ مِن دُونِ ٱللَّهِ قُرْبَانًا ءَالِهَةًۢ ۖ بَلْ ضَلُّوا۟ عَنْهُمْ ۚ وَذَٰلِكَ إِفْكُهُمْ وَمَا كَانُوا۟ يَفْتَرُونَ', 'فلولا نصرهم الذين اتخذوا من دون الله قربانا ءالهة  بل ضلوا عنهم  وذلك إفكهم وما كانوا يفترون', NULL, 505, 'local:hafs-text.json'),
  ('hafs-46-29', 'hafs', 46, 29, 'وَإِذْ صَرَفْنَآ إِلَيْكَ نَفَرًۭا مِّنَ ٱلْجِنِّ يَسْتَمِعُونَ ٱلْقُرْءَانَ فَلَمَّا حَضَرُوهُ قَالُوٓا۟ أَنصِتُوا۟ ۖ فَلَمَّا قُضِىَ وَلَّوْا۟ إِلَىٰ قَوْمِهِم مُّنذِرِينَ', 'وإذ صرفنا إليك نفرا من الجن يستمعون القرءان فلما حضروه قالوا أنصتوا  فلما قضى ولوا إلى قومهم منذرين', NULL, 506, 'local:hafs-text.json'),
  ('hafs-46-30', 'hafs', 46, 30, 'قَالُوا۟ يَٰقَوْمَنَآ إِنَّا سَمِعْنَا كِتَٰبًا أُنزِلَ مِنۢ بَعْدِ مُوسَىٰ مُصَدِّقًۭا لِّمَا بَيْنَ يَدَيْهِ يَهْدِىٓ إِلَى ٱلْحَقِّ وَإِلَىٰ طَرِيقٍۢ مُّسْتَقِيمٍۢ', 'قالوا يقومنا إنا سمعنا كتبا أنزل من بعد موسى مصدقا لما بين يديه يهدى إلى الحق وإلى طريق مستقيم', NULL, 506, 'local:hafs-text.json'),
  ('hafs-46-31', 'hafs', 46, 31, 'يَٰقَوْمَنَآ أَجِيبُوا۟ دَاعِىَ ٱللَّهِ وَءَامِنُوا۟ بِهِۦ يَغْفِرْ لَكُم مِّن ذُنُوبِكُمْ وَيُجِرْكُم مِّنْ عَذَابٍ أَلِيمٍۢ', 'يقومنا أجيبوا داعى الله وءامنوا به يغفر لكم من ذنوبكم ويجركم من عذاب أليم', NULL, 506, 'local:hafs-text.json'),
  ('hafs-46-32', 'hafs', 46, 32, 'وَمَن لَّا يُجِبْ دَاعِىَ ٱللَّهِ فَلَيْسَ بِمُعْجِزٍۢ فِى ٱلْأَرْضِ وَلَيْسَ لَهُۥ مِن دُونِهِۦٓ أَوْلِيَآءُ ۚ أُو۟لَٰٓئِكَ فِى ضَلَٰلٍۢ مُّبِينٍ', 'ومن لا يجب داعى الله فليس بمعجز فى الأرض وليس له من دونه أولياء  أولئك فى ضلل مبين', NULL, 506, 'local:hafs-text.json'),
  ('hafs-46-33', 'hafs', 46, 33, 'أَوَلَمْ يَرَوْا۟ أَنَّ ٱللَّهَ ٱلَّذِى خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ وَلَمْ يَعْىَ بِخَلْقِهِنَّ بِقَٰدِرٍ عَلَىٰٓ أَن يُحْۦِىَ ٱلْمَوْتَىٰ ۚ بَلَىٰٓ إِنَّهُۥ عَلَىٰ كُلِّ شَىْءٍۢ قَدِيرٌۭ', 'أولم يروا أن الله الذى خلق السموت والأرض ولم يعى بخلقهن بقدر على أن يحى الموتى  بلى إنه على كل شىء قدير', NULL, 506, 'local:hafs-text.json'),
  ('hafs-46-34', 'hafs', 46, 34, 'وَيَوْمَ يُعْرَضُ ٱلَّذِينَ كَفَرُوا۟ عَلَى ٱلنَّارِ أَلَيْسَ هَٰذَا بِٱلْحَقِّ ۖ قَالُوا۟ بَلَىٰ وَرَبِّنَا ۚ قَالَ فَذُوقُوا۟ ٱلْعَذَابَ بِمَا كُنتُمْ تَكْفُرُونَ', 'ويوم يعرض الذين كفروا على النار أليس هذا بالحق  قالوا بلى وربنا  قال فذوقوا العذاب بما كنتم تكفرون', NULL, 506, 'local:hafs-text.json'),
  ('hafs-46-35', 'hafs', 46, 35, 'فَٱصْبِرْ كَمَا صَبَرَ أُو۟لُوا۟ ٱلْعَزْمِ مِنَ ٱلرُّسُلِ وَلَا تَسْتَعْجِل لَّهُمْ ۚ كَأَنَّهُمْ يَوْمَ يَرَوْنَ مَا يُوعَدُونَ لَمْ يَلْبَثُوٓا۟ إِلَّا سَاعَةًۭ مِّن نَّهَارٍۭ ۚ بَلَٰغٌۭ ۚ فَهَلْ يُهْلَكُ إِلَّا ٱلْقَوْمُ ٱلْفَٰسِقُونَ', 'فاصبر كما صبر أولوا العزم من الرسل ولا تستعجل لهم  كأنهم يوم يرون ما يوعدون لم يلبثوا إلا ساعة من نهار  بلغ  فهل يهلك إلا القوم الفسقون', NULL, 506, 'local:hafs-text.json'),
  ('hafs-47-1', 'hafs', 47, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ ٱلَّذِينَ كَفَرُوا۟ وَصَدُّوا۟ عَن سَبِيلِ ٱللَّهِ أَضَلَّ أَعْمَٰلَهُمْ', 'بسم الله الرحمن الرحيم الذين كفروا وصدوا عن سبيل الله أضل أعملهم', NULL, 507, 'local:hafs-text.json'),
  ('hafs-47-2', 'hafs', 47, 2, 'وَٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ وَءَامَنُوا۟ بِمَا نُزِّلَ عَلَىٰ مُحَمَّدٍۢ وَهُوَ ٱلْحَقُّ مِن رَّبِّهِمْ ۙ كَفَّرَ عَنْهُمْ سَيِّـَٔاتِهِمْ وَأَصْلَحَ بَالَهُمْ', 'والذين ءامنوا وعملوا الصلحت وءامنوا بما نزل على محمد وهو الحق من ربهم  كفر عنهم سياتهم وأصلح بالهم', NULL, 507, 'local:hafs-text.json'),
  ('hafs-47-3', 'hafs', 47, 3, 'ذَٰلِكَ بِأَنَّ ٱلَّذِينَ كَفَرُوا۟ ٱتَّبَعُوا۟ ٱلْبَٰطِلَ وَأَنَّ ٱلَّذِينَ ءَامَنُوا۟ ٱتَّبَعُوا۟ ٱلْحَقَّ مِن رَّبِّهِمْ ۚ كَذَٰلِكَ يَضْرِبُ ٱللَّهُ لِلنَّاسِ أَمْثَٰلَهُمْ', 'ذلك بأن الذين كفروا اتبعوا البطل وأن الذين ءامنوا اتبعوا الحق من ربهم  كذلك يضرب الله للناس أمثلهم', NULL, 507, 'local:hafs-text.json'),
  ('hafs-47-4', 'hafs', 47, 4, 'فَإِذَا لَقِيتُمُ ٱلَّذِينَ كَفَرُوا۟ فَضَرْبَ ٱلرِّقَابِ حَتَّىٰٓ إِذَآ أَثْخَنتُمُوهُمْ فَشُدُّوا۟ ٱلْوَثَاقَ فَإِمَّا مَنًّۢا بَعْدُ وَإِمَّا فِدَآءً حَتَّىٰ تَضَعَ ٱلْحَرْبُ أَوْزَارَهَا ۚ ذَٰلِكَ وَلَوْ يَشَآءُ ٱللَّهُ لَٱنتَصَرَ مِنْهُمْ وَلَٰكِن لِّيَبْلُوَا۟ بَعْضَكُم بِبَعْضٍۢ ۗ وَٱلَّذِينَ قُتِلُوا۟ فِى سَبِيلِ ٱللَّهِ فَلَن يُضِلَّ أَعْمَٰلَهُمْ', 'فإذا لقيتم الذين كفروا فضرب الرقاب حتى إذا أثخنتموهم فشدوا الوثاق فإما منا بعد وإما فداء حتى تضع الحرب أوزارها  ذلك ولو يشاء الله لانتصر منهم ولكن ليبلوا بعضكم ببعض  والذين قتلوا فى سبيل الله فلن يضل أعملهم', NULL, 507, 'local:hafs-text.json'),
  ('hafs-47-5', 'hafs', 47, 5, 'سَيَهْدِيهِمْ وَيُصْلِحُ بَالَهُمْ', 'سيهديهم ويصلح بالهم', NULL, 507, 'local:hafs-text.json'),
  ('hafs-47-6', 'hafs', 47, 6, 'وَيُدْخِلُهُمُ ٱلْجَنَّةَ عَرَّفَهَا لَهُمْ', 'ويدخلهم الجنة عرفها لهم', NULL, 507, 'local:hafs-text.json'),
  ('hafs-47-7', 'hafs', 47, 7, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِن تَنصُرُوا۟ ٱللَّهَ يَنصُرْكُمْ وَيُثَبِّتْ أَقْدَامَكُمْ', 'يأيها الذين ءامنوا إن تنصروا الله ينصركم ويثبت أقدامكم', NULL, 507, 'local:hafs-text.json'),
  ('hafs-47-8', 'hafs', 47, 8, 'وَٱلَّذِينَ كَفَرُوا۟ فَتَعْسًۭا لَّهُمْ وَأَضَلَّ أَعْمَٰلَهُمْ', 'والذين كفروا فتعسا لهم وأضل أعملهم', NULL, 507, 'local:hafs-text.json'),
  ('hafs-47-9', 'hafs', 47, 9, 'ذَٰلِكَ بِأَنَّهُمْ كَرِهُوا۟ مَآ أَنزَلَ ٱللَّهُ فَأَحْبَطَ أَعْمَٰلَهُمْ', 'ذلك بأنهم كرهوا ما أنزل الله فأحبط أعملهم', NULL, 507, 'local:hafs-text.json'),
  ('hafs-47-10', 'hafs', 47, 10, '۞ أَفَلَمْ يَسِيرُوا۟ فِى ٱلْأَرْضِ فَيَنظُرُوا۟ كَيْفَ كَانَ عَٰقِبَةُ ٱلَّذِينَ مِن قَبْلِهِمْ ۚ دَمَّرَ ٱللَّهُ عَلَيْهِمْ ۖ وَلِلْكَٰفِرِينَ أَمْثَٰلُهَا', 'أفلم يسيروا فى الأرض فينظروا كيف كان عقبة الذين من قبلهم  دمر الله عليهم  وللكفرين أمثلها', NULL, 507, 'local:hafs-text.json'),
  ('hafs-47-11', 'hafs', 47, 11, 'ذَٰلِكَ بِأَنَّ ٱللَّهَ مَوْلَى ٱلَّذِينَ ءَامَنُوا۟ وَأَنَّ ٱلْكَٰفِرِينَ لَا مَوْلَىٰ لَهُمْ', 'ذلك بأن الله مولى الذين ءامنوا وأن الكفرين لا مولى لهم', NULL, 507, 'local:hafs-text.json'),
  ('hafs-47-12', 'hafs', 47, 12, 'إِنَّ ٱللَّهَ يُدْخِلُ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ جَنَّٰتٍۢ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ ۖ وَٱلَّذِينَ كَفَرُوا۟ يَتَمَتَّعُونَ وَيَأْكُلُونَ كَمَا تَأْكُلُ ٱلْأَنْعَٰمُ وَٱلنَّارُ مَثْوًۭى لَّهُمْ', 'إن الله يدخل الذين ءامنوا وعملوا الصلحت جنت تجرى من تحتها الأنهر  والذين كفروا يتمتعون ويأكلون كما تأكل الأنعم والنار مثوى لهم', NULL, 508, 'local:hafs-text.json'),
  ('hafs-47-13', 'hafs', 47, 13, 'وَكَأَيِّن مِّن قَرْيَةٍ هِىَ أَشَدُّ قُوَّةًۭ مِّن قَرْيَتِكَ ٱلَّتِىٓ أَخْرَجَتْكَ أَهْلَكْنَٰهُمْ فَلَا نَاصِرَ لَهُمْ', 'وكأين من قرية هى أشد قوة من قريتك التى أخرجتك أهلكنهم فلا ناصر لهم', NULL, 508, 'local:hafs-text.json'),
  ('hafs-47-14', 'hafs', 47, 14, 'أَفَمَن كَانَ عَلَىٰ بَيِّنَةٍۢ مِّن رَّبِّهِۦ كَمَن زُيِّنَ لَهُۥ سُوٓءُ عَمَلِهِۦ وَٱتَّبَعُوٓا۟ أَهْوَآءَهُم', 'أفمن كان على بينة من ربه كمن زين له سوء عمله واتبعوا أهواءهم', NULL, 508, 'local:hafs-text.json'),
  ('hafs-47-15', 'hafs', 47, 15, 'مَّثَلُ ٱلْجَنَّةِ ٱلَّتِى وُعِدَ ٱلْمُتَّقُونَ ۖ فِيهَآ أَنْهَٰرٌۭ مِّن مَّآءٍ غَيْرِ ءَاسِنٍۢ وَأَنْهَٰرٌۭ مِّن لَّبَنٍۢ لَّمْ يَتَغَيَّرْ طَعْمُهُۥ وَأَنْهَٰرٌۭ مِّنْ خَمْرٍۢ لَّذَّةٍۢ لِّلشَّٰرِبِينَ وَأَنْهَٰرٌۭ مِّنْ عَسَلٍۢ مُّصَفًّۭى ۖ وَلَهُمْ فِيهَا مِن كُلِّ ٱلثَّمَرَٰتِ وَمَغْفِرَةٌۭ مِّن رَّبِّهِمْ ۖ كَمَنْ هُوَ خَٰلِدٌۭ فِى ٱلنَّارِ وَسُقُوا۟ مَآءً حَمِيمًۭا فَقَطَّعَ أَمْعَآءَهُمْ', 'مثل الجنة التى وعد المتقون  فيها أنهر من ماء غير ءاسن وأنهر من لبن لم يتغير طعمه وأنهر من خمر لذة للشربين وأنهر من عسل مصفى  ولهم فيها من كل الثمرت ومغفرة من ربهم  كمن هو خلد فى النار وسقوا ماء حميما فقطع أمعاءهم', NULL, 508, 'local:hafs-text.json'),
  ('hafs-47-16', 'hafs', 47, 16, 'وَمِنْهُم مَّن يَسْتَمِعُ إِلَيْكَ حَتَّىٰٓ إِذَا خَرَجُوا۟ مِنْ عِندِكَ قَالُوا۟ لِلَّذِينَ أُوتُوا۟ ٱلْعِلْمَ مَاذَا قَالَ ءَانِفًا ۚ أُو۟لَٰٓئِكَ ٱلَّذِينَ طَبَعَ ٱللَّهُ عَلَىٰ قُلُوبِهِمْ وَٱتَّبَعُوٓا۟ أَهْوَآءَهُمْ', 'ومنهم من يستمع إليك حتى إذا خرجوا من عندك قالوا للذين أوتوا العلم ماذا قال ءانفا  أولئك الذين طبع الله على قلوبهم واتبعوا أهواءهم', NULL, 508, 'local:hafs-text.json'),
  ('hafs-47-17', 'hafs', 47, 17, 'وَٱلَّذِينَ ٱهْتَدَوْا۟ زَادَهُمْ هُدًۭى وَءَاتَىٰهُمْ تَقْوَىٰهُمْ', 'والذين اهتدوا زادهم هدى وءاتىهم تقوىهم', NULL, 508, 'local:hafs-text.json'),
  ('hafs-47-18', 'hafs', 47, 18, 'فَهَلْ يَنظُرُونَ إِلَّا ٱلسَّاعَةَ أَن تَأْتِيَهُم بَغْتَةًۭ ۖ فَقَدْ جَآءَ أَشْرَاطُهَا ۚ فَأَنَّىٰ لَهُمْ إِذَا جَآءَتْهُمْ ذِكْرَىٰهُمْ', 'فهل ينظرون إلا الساعة أن تأتيهم بغتة  فقد جاء أشراطها  فأنى لهم إذا جاءتهم ذكرىهم', NULL, 508, 'local:hafs-text.json'),
  ('hafs-47-19', 'hafs', 47, 19, 'فَٱعْلَمْ أَنَّهُۥ لَآ إِلَٰهَ إِلَّا ٱللَّهُ وَٱسْتَغْفِرْ لِذَنۢبِكَ وَلِلْمُؤْمِنِينَ وَٱلْمُؤْمِنَٰتِ ۗ وَٱللَّهُ يَعْلَمُ مُتَقَلَّبَكُمْ وَمَثْوَىٰكُمْ', 'فاعلم أنه لا إله إلا الله واستغفر لذنبك وللمؤمنين والمؤمنت  والله يعلم متقلبكم ومثوىكم', NULL, 508, 'local:hafs-text.json'),
  ('hafs-47-20', 'hafs', 47, 20, 'وَيَقُولُ ٱلَّذِينَ ءَامَنُوا۟ لَوْلَا نُزِّلَتْ سُورَةٌۭ ۖ فَإِذَآ أُنزِلَتْ سُورَةٌۭ مُّحْكَمَةٌۭ وَذُكِرَ فِيهَا ٱلْقِتَالُ ۙ رَأَيْتَ ٱلَّذِينَ فِى قُلُوبِهِم مَّرَضٌۭ يَنظُرُونَ إِلَيْكَ نَظَرَ ٱلْمَغْشِىِّ عَلَيْهِ مِنَ ٱلْمَوْتِ ۖ فَأَوْلَىٰ لَهُمْ', 'ويقول الذين ءامنوا لولا نزلت سورة  فإذا أنزلت سورة محكمة وذكر فيها القتال  رأيت الذين فى قلوبهم مرض ينظرون إليك نظر المغشى عليه من الموت  فأولى لهم', NULL, 509, 'local:hafs-text.json'),
  ('hafs-47-21', 'hafs', 47, 21, 'طَاعَةٌۭ وَقَوْلٌۭ مَّعْرُوفٌۭ ۚ فَإِذَا عَزَمَ ٱلْأَمْرُ فَلَوْ صَدَقُوا۟ ٱللَّهَ لَكَانَ خَيْرًۭا لَّهُمْ', 'طاعة وقول معروف  فإذا عزم الأمر فلو صدقوا الله لكان خيرا لهم', NULL, 509, 'local:hafs-text.json'),
  ('hafs-47-22', 'hafs', 47, 22, 'فَهَلْ عَسَيْتُمْ إِن تَوَلَّيْتُمْ أَن تُفْسِدُوا۟ فِى ٱلْأَرْضِ وَتُقَطِّعُوٓا۟ أَرْحَامَكُمْ', 'فهل عسيتم إن توليتم أن تفسدوا فى الأرض وتقطعوا أرحامكم', NULL, 509, 'local:hafs-text.json'),
  ('hafs-47-23', 'hafs', 47, 23, 'أُو۟لَٰٓئِكَ ٱلَّذِينَ لَعَنَهُمُ ٱللَّهُ فَأَصَمَّهُمْ وَأَعْمَىٰٓ أَبْصَٰرَهُمْ', 'أولئك الذين لعنهم الله فأصمهم وأعمى أبصرهم', NULL, 509, 'local:hafs-text.json'),
  ('hafs-47-24', 'hafs', 47, 24, 'أَفَلَا يَتَدَبَّرُونَ ٱلْقُرْءَانَ أَمْ عَلَىٰ قُلُوبٍ أَقْفَالُهَآ', 'أفلا يتدبرون القرءان أم على قلوب أقفالها', NULL, 509, 'local:hafs-text.json'),
  ('hafs-47-25', 'hafs', 47, 25, 'إِنَّ ٱلَّذِينَ ٱرْتَدُّوا۟ عَلَىٰٓ أَدْبَٰرِهِم مِّنۢ بَعْدِ مَا تَبَيَّنَ لَهُمُ ٱلْهُدَى ۙ ٱلشَّيْطَٰنُ سَوَّلَ لَهُمْ وَأَمْلَىٰ لَهُمْ', 'إن الذين ارتدوا على أدبرهم من بعد ما تبين لهم الهدى  الشيطن سول لهم وأملى لهم', NULL, 509, 'local:hafs-text.json'),
  ('hafs-47-26', 'hafs', 47, 26, 'ذَٰلِكَ بِأَنَّهُمْ قَالُوا۟ لِلَّذِينَ كَرِهُوا۟ مَا نَزَّلَ ٱللَّهُ سَنُطِيعُكُمْ فِى بَعْضِ ٱلْأَمْرِ ۖ وَٱللَّهُ يَعْلَمُ إِسْرَارَهُمْ', 'ذلك بأنهم قالوا للذين كرهوا ما نزل الله سنطيعكم فى بعض الأمر  والله يعلم إسرارهم', NULL, 509, 'local:hafs-text.json'),
  ('hafs-47-27', 'hafs', 47, 27, 'فَكَيْفَ إِذَا تَوَفَّتْهُمُ ٱلْمَلَٰٓئِكَةُ يَضْرِبُونَ وُجُوهَهُمْ وَأَدْبَٰرَهُمْ', 'فكيف إذا توفتهم الملئكة يضربون وجوههم وأدبرهم', NULL, 509, 'local:hafs-text.json'),
  ('hafs-47-28', 'hafs', 47, 28, 'ذَٰلِكَ بِأَنَّهُمُ ٱتَّبَعُوا۟ مَآ أَسْخَطَ ٱللَّهَ وَكَرِهُوا۟ رِضْوَٰنَهُۥ فَأَحْبَطَ أَعْمَٰلَهُمْ', 'ذلك بأنهم اتبعوا ما أسخط الله وكرهوا رضونه فأحبط أعملهم', NULL, 509, 'local:hafs-text.json'),
  ('hafs-47-29', 'hafs', 47, 29, 'أَمْ حَسِبَ ٱلَّذِينَ فِى قُلُوبِهِم مَّرَضٌ أَن لَّن يُخْرِجَ ٱللَّهُ أَضْغَٰنَهُمْ', 'أم حسب الذين فى قلوبهم مرض أن لن يخرج الله أضغنهم', NULL, 509, 'local:hafs-text.json'),
  ('hafs-47-30', 'hafs', 47, 30, 'وَلَوْ نَشَآءُ لَأَرَيْنَٰكَهُمْ فَلَعَرَفْتَهُم بِسِيمَٰهُمْ ۚ وَلَتَعْرِفَنَّهُمْ فِى لَحْنِ ٱلْقَوْلِ ۚ وَٱللَّهُ يَعْلَمُ أَعْمَٰلَكُمْ', 'ولو نشاء لأرينكهم فلعرفتهم بسيمهم  ولتعرفنهم فى لحن القول  والله يعلم أعملكم', NULL, 510, 'local:hafs-text.json'),
  ('hafs-47-31', 'hafs', 47, 31, 'وَلَنَبْلُوَنَّكُمْ حَتَّىٰ نَعْلَمَ ٱلْمُجَٰهِدِينَ مِنكُمْ وَٱلصَّٰبِرِينَ وَنَبْلُوَا۟ أَخْبَارَكُمْ', 'ولنبلونكم حتى نعلم المجهدين منكم والصبرين ونبلوا أخباركم', NULL, 510, 'local:hafs-text.json'),
  ('hafs-47-32', 'hafs', 47, 32, 'إِنَّ ٱلَّذِينَ كَفَرُوا۟ وَصَدُّوا۟ عَن سَبِيلِ ٱللَّهِ وَشَآقُّوا۟ ٱلرَّسُولَ مِنۢ بَعْدِ مَا تَبَيَّنَ لَهُمُ ٱلْهُدَىٰ لَن يَضُرُّوا۟ ٱللَّهَ شَيْـًۭٔا وَسَيُحْبِطُ أَعْمَٰلَهُمْ', 'إن الذين كفروا وصدوا عن سبيل الله وشاقوا الرسول من بعد ما تبين لهم الهدى لن يضروا الله شيا وسيحبط أعملهم', NULL, 510, 'local:hafs-text.json'),
  ('hafs-47-33', 'hafs', 47, 33, '۞ يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ أَطِيعُوا۟ ٱللَّهَ وَأَطِيعُوا۟ ٱلرَّسُولَ وَلَا تُبْطِلُوٓا۟ أَعْمَٰلَكُمْ', 'يأيها الذين ءامنوا أطيعوا الله وأطيعوا الرسول ولا تبطلوا أعملكم', NULL, 510, 'local:hafs-text.json'),
  ('hafs-47-34', 'hafs', 47, 34, 'إِنَّ ٱلَّذِينَ كَفَرُوا۟ وَصَدُّوا۟ عَن سَبِيلِ ٱللَّهِ ثُمَّ مَاتُوا۟ وَهُمْ كُفَّارٌۭ فَلَن يَغْفِرَ ٱللَّهُ لَهُمْ', 'إن الذين كفروا وصدوا عن سبيل الله ثم ماتوا وهم كفار فلن يغفر الله لهم', NULL, 510, 'local:hafs-text.json'),
  ('hafs-47-35', 'hafs', 47, 35, 'فَلَا تَهِنُوا۟ وَتَدْعُوٓا۟ إِلَى ٱلسَّلْمِ وَأَنتُمُ ٱلْأَعْلَوْنَ وَٱللَّهُ مَعَكُمْ وَلَن يَتِرَكُمْ أَعْمَٰلَكُمْ', 'فلا تهنوا وتدعوا إلى السلم وأنتم الأعلون والله معكم ولن يتركم أعملكم', NULL, 510, 'local:hafs-text.json'),
  ('hafs-47-36', 'hafs', 47, 36, 'إِنَّمَا ٱلْحَيَوٰةُ ٱلدُّنْيَا لَعِبٌۭ وَلَهْوٌۭ ۚ وَإِن تُؤْمِنُوا۟ وَتَتَّقُوا۟ يُؤْتِكُمْ أُجُورَكُمْ وَلَا يَسْـَٔلْكُمْ أَمْوَٰلَكُمْ', 'إنما الحيوة الدنيا لعب ولهو  وإن تؤمنوا وتتقوا يؤتكم أجوركم ولا يسلكم أمولكم', NULL, 510, 'local:hafs-text.json'),
  ('hafs-47-37', 'hafs', 47, 37, 'إِن يَسْـَٔلْكُمُوهَا فَيُحْفِكُمْ تَبْخَلُوا۟ وَيُخْرِجْ أَضْغَٰنَكُمْ', 'إن يسلكموها فيحفكم تبخلوا ويخرج أضغنكم', NULL, 510, 'local:hafs-text.json'),
  ('hafs-47-38', 'hafs', 47, 38, 'هَٰٓأَنتُمْ هَٰٓؤُلَآءِ تُدْعَوْنَ لِتُنفِقُوا۟ فِى سَبِيلِ ٱللَّهِ فَمِنكُم مَّن يَبْخَلُ ۖ وَمَن يَبْخَلْ فَإِنَّمَا يَبْخَلُ عَن نَّفْسِهِۦ ۚ وَٱللَّهُ ٱلْغَنِىُّ وَأَنتُمُ ٱلْفُقَرَآءُ ۚ وَإِن تَتَوَلَّوْا۟ يَسْتَبْدِلْ قَوْمًا غَيْرَكُمْ ثُمَّ لَا يَكُونُوٓا۟ أَمْثَٰلَكُم', 'هأنتم هؤلاء تدعون لتنفقوا فى سبيل الله فمنكم من يبخل  ومن يبخل فإنما يبخل عن نفسه  والله الغنى وأنتم الفقراء  وإن تتولوا يستبدل قوما غيركم ثم لا يكونوا أمثلكم', NULL, 510, 'local:hafs-text.json'),
  ('hafs-48-1', 'hafs', 48, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ إِنَّا فَتَحْنَا لَكَ فَتْحًۭا مُّبِينًۭا', 'بسم الله الرحمن الرحيم إنا فتحنا لك فتحا مبينا', NULL, 511, 'local:hafs-text.json'),
  ('hafs-48-2', 'hafs', 48, 2, 'لِّيَغْفِرَ لَكَ ٱللَّهُ مَا تَقَدَّمَ مِن ذَنۢبِكَ وَمَا تَأَخَّرَ وَيُتِمَّ نِعْمَتَهُۥ عَلَيْكَ وَيَهْدِيَكَ صِرَٰطًۭا مُّسْتَقِيمًۭا', 'ليغفر لك الله ما تقدم من ذنبك وما تأخر ويتم نعمته عليك ويهديك صرطا مستقيما', NULL, 511, 'local:hafs-text.json'),
  ('hafs-48-3', 'hafs', 48, 3, 'وَيَنصُرَكَ ٱللَّهُ نَصْرًا عَزِيزًا', 'وينصرك الله نصرا عزيزا', NULL, 511, 'local:hafs-text.json'),
  ('hafs-48-4', 'hafs', 48, 4, 'هُوَ ٱلَّذِىٓ أَنزَلَ ٱلسَّكِينَةَ فِى قُلُوبِ ٱلْمُؤْمِنِينَ لِيَزْدَادُوٓا۟ إِيمَٰنًۭا مَّعَ إِيمَٰنِهِمْ ۗ وَلِلَّهِ جُنُودُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ ۚ وَكَانَ ٱللَّهُ عَلِيمًا حَكِيمًۭا', 'هو الذى أنزل السكينة فى قلوب المؤمنين ليزدادوا إيمنا مع إيمنهم  ولله جنود السموت والأرض  وكان الله عليما حكيما', NULL, 511, 'local:hafs-text.json'),
  ('hafs-48-5', 'hafs', 48, 5, 'لِّيُدْخِلَ ٱلْمُؤْمِنِينَ وَٱلْمُؤْمِنَٰتِ جَنَّٰتٍۢ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ خَٰلِدِينَ فِيهَا وَيُكَفِّرَ عَنْهُمْ سَيِّـَٔاتِهِمْ ۚ وَكَانَ ذَٰلِكَ عِندَ ٱللَّهِ فَوْزًا عَظِيمًۭا', 'ليدخل المؤمنين والمؤمنت جنت تجرى من تحتها الأنهر خلدين فيها ويكفر عنهم سياتهم  وكان ذلك عند الله فوزا عظيما', NULL, 511, 'local:hafs-text.json'),
  ('hafs-48-6', 'hafs', 48, 6, 'وَيُعَذِّبَ ٱلْمُنَٰفِقِينَ وَٱلْمُنَٰفِقَٰتِ وَٱلْمُشْرِكِينَ وَٱلْمُشْرِكَٰتِ ٱلظَّآنِّينَ بِٱللَّهِ ظَنَّ ٱلسَّوْءِ ۚ عَلَيْهِمْ دَآئِرَةُ ٱلسَّوْءِ ۖ وَغَضِبَ ٱللَّهُ عَلَيْهِمْ وَلَعَنَهُمْ وَأَعَدَّ لَهُمْ جَهَنَّمَ ۖ وَسَآءَتْ مَصِيرًۭا', 'ويعذب المنفقين والمنفقت والمشركين والمشركت الظانين بالله ظن السوء  عليهم دائرة السوء  وغضب الله عليهم ولعنهم وأعد لهم جهنم  وساءت مصيرا', NULL, 511, 'local:hafs-text.json'),
  ('hafs-48-7', 'hafs', 48, 7, 'وَلِلَّهِ جُنُودُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ ۚ وَكَانَ ٱللَّهُ عَزِيزًا حَكِيمًا', 'ولله جنود السموت والأرض  وكان الله عزيزا حكيما', NULL, 511, 'local:hafs-text.json'),
  ('hafs-48-8', 'hafs', 48, 8, 'إِنَّآ أَرْسَلْنَٰكَ شَٰهِدًۭا وَمُبَشِّرًۭا وَنَذِيرًۭا', 'إنا أرسلنك شهدا ومبشرا ونذيرا', NULL, 511, 'local:hafs-text.json'),
  ('hafs-48-9', 'hafs', 48, 9, 'لِّتُؤْمِنُوا۟ بِٱللَّهِ وَرَسُولِهِۦ وَتُعَزِّرُوهُ وَتُوَقِّرُوهُ وَتُسَبِّحُوهُ بُكْرَةًۭ وَأَصِيلًا', 'لتؤمنوا بالله ورسوله وتعزروه وتوقروه وتسبحوه بكرة وأصيلا', NULL, 511, 'local:hafs-text.json'),
  ('hafs-48-10', 'hafs', 48, 10, 'إِنَّ ٱلَّذِينَ يُبَايِعُونَكَ إِنَّمَا يُبَايِعُونَ ٱللَّهَ يَدُ ٱللَّهِ فَوْقَ أَيْدِيهِمْ ۚ فَمَن نَّكَثَ فَإِنَّمَا يَنكُثُ عَلَىٰ نَفْسِهِۦ ۖ وَمَنْ أَوْفَىٰ بِمَا عَٰهَدَ عَلَيْهُ ٱللَّهَ فَسَيُؤْتِيهِ أَجْرًا عَظِيمًۭا', 'إن الذين يبايعونك إنما يبايعون الله يد الله فوق أيديهم  فمن نكث فإنما ينكث على نفسه  ومن أوفى بما عهد عليه الله فسيؤتيه أجرا عظيما', NULL, 512, 'local:hafs-text.json'),
  ('hafs-48-11', 'hafs', 48, 11, 'سَيَقُولُ لَكَ ٱلْمُخَلَّفُونَ مِنَ ٱلْأَعْرَابِ شَغَلَتْنَآ أَمْوَٰلُنَا وَأَهْلُونَا فَٱسْتَغْفِرْ لَنَا ۚ يَقُولُونَ بِأَلْسِنَتِهِم مَّا لَيْسَ فِى قُلُوبِهِمْ ۚ قُلْ فَمَن يَمْلِكُ لَكُم مِّنَ ٱللَّهِ شَيْـًٔا إِنْ أَرَادَ بِكُمْ ضَرًّا أَوْ أَرَادَ بِكُمْ نَفْعًۢا ۚ بَلْ كَانَ ٱللَّهُ بِمَا تَعْمَلُونَ خَبِيرًۢا', 'سيقول لك المخلفون من الأعراب شغلتنا أمولنا وأهلونا فاستغفر لنا  يقولون بألسنتهم ما ليس فى قلوبهم  قل فمن يملك لكم من الله شيا إن أراد بكم ضرا أو أراد بكم نفعا  بل كان الله بما تعملون خبيرا', NULL, 512, 'local:hafs-text.json'),
  ('hafs-48-12', 'hafs', 48, 12, 'بَلْ ظَنَنتُمْ أَن لَّن يَنقَلِبَ ٱلرَّسُولُ وَٱلْمُؤْمِنُونَ إِلَىٰٓ أَهْلِيهِمْ أَبَدًۭا وَزُيِّنَ ذَٰلِكَ فِى قُلُوبِكُمْ وَظَنَنتُمْ ظَنَّ ٱلسَّوْءِ وَكُنتُمْ قَوْمًۢا بُورًۭا', 'بل ظننتم أن لن ينقلب الرسول والمؤمنون إلى أهليهم أبدا وزين ذلك فى قلوبكم وظننتم ظن السوء وكنتم قوما بورا', NULL, 512, 'local:hafs-text.json'),
  ('hafs-48-13', 'hafs', 48, 13, 'وَمَن لَّمْ يُؤْمِنۢ بِٱللَّهِ وَرَسُولِهِۦ فَإِنَّآ أَعْتَدْنَا لِلْكَٰفِرِينَ سَعِيرًۭا', 'ومن لم يؤمن بالله ورسوله فإنا أعتدنا للكفرين سعيرا', NULL, 512, 'local:hafs-text.json'),
  ('hafs-48-14', 'hafs', 48, 14, 'وَلِلَّهِ مُلْكُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ ۚ يَغْفِرُ لِمَن يَشَآءُ وَيُعَذِّبُ مَن يَشَآءُ ۚ وَكَانَ ٱللَّهُ غَفُورًۭا رَّحِيمًۭا', 'ولله ملك السموت والأرض  يغفر لمن يشاء ويعذب من يشاء  وكان الله غفورا رحيما', NULL, 512, 'local:hafs-text.json'),
  ('hafs-48-15', 'hafs', 48, 15, 'سَيَقُولُ ٱلْمُخَلَّفُونَ إِذَا ٱنطَلَقْتُمْ إِلَىٰ مَغَانِمَ لِتَأْخُذُوهَا ذَرُونَا نَتَّبِعْكُمْ ۖ يُرِيدُونَ أَن يُبَدِّلُوا۟ كَلَٰمَ ٱللَّهِ ۚ قُل لَّن تَتَّبِعُونَا كَذَٰلِكُمْ قَالَ ٱللَّهُ مِن قَبْلُ ۖ فَسَيَقُولُونَ بَلْ تَحْسُدُونَنَا ۚ بَلْ كَانُوا۟ لَا يَفْقَهُونَ إِلَّا قَلِيلًۭا', 'سيقول المخلفون إذا انطلقتم إلى مغانم لتأخذوها ذرونا نتبعكم  يريدون أن يبدلوا كلم الله  قل لن تتبعونا كذلكم قال الله من قبل  فسيقولون بل تحسدوننا  بل كانوا لا يفقهون إلا قليلا', NULL, 512, 'local:hafs-text.json'),
  ('hafs-48-16', 'hafs', 48, 16, 'قُل لِّلْمُخَلَّفِينَ مِنَ ٱلْأَعْرَابِ سَتُدْعَوْنَ إِلَىٰ قَوْمٍ أُو۟لِى بَأْسٍۢ شَدِيدٍۢ تُقَٰتِلُونَهُمْ أَوْ يُسْلِمُونَ ۖ فَإِن تُطِيعُوا۟ يُؤْتِكُمُ ٱللَّهُ أَجْرًا حَسَنًۭا ۖ وَإِن تَتَوَلَّوْا۟ كَمَا تَوَلَّيْتُم مِّن قَبْلُ يُعَذِّبْكُمْ عَذَابًا أَلِيمًۭا', 'قل للمخلفين من الأعراب ستدعون إلى قوم أولى بأس شديد تقتلونهم أو يسلمون  فإن تطيعوا يؤتكم الله أجرا حسنا  وإن تتولوا كما توليتم من قبل يعذبكم عذابا أليما', NULL, 513, 'local:hafs-text.json'),
  ('hafs-48-17', 'hafs', 48, 17, 'لَّيْسَ عَلَى ٱلْأَعْمَىٰ حَرَجٌۭ وَلَا عَلَى ٱلْأَعْرَجِ حَرَجٌۭ وَلَا عَلَى ٱلْمَرِيضِ حَرَجٌۭ ۗ وَمَن يُطِعِ ٱللَّهَ وَرَسُولَهُۥ يُدْخِلْهُ جَنَّٰتٍۢ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ ۖ وَمَن يَتَوَلَّ يُعَذِّبْهُ عَذَابًا أَلِيمًۭا', 'ليس على الأعمى حرج ولا على الأعرج حرج ولا على المريض حرج  ومن يطع الله ورسوله يدخله جنت تجرى من تحتها الأنهر  ومن يتول يعذبه عذابا أليما', NULL, 513, 'local:hafs-text.json'),
  ('hafs-48-18', 'hafs', 48, 18, '۞ لَّقَدْ رَضِىَ ٱللَّهُ عَنِ ٱلْمُؤْمِنِينَ إِذْ يُبَايِعُونَكَ تَحْتَ ٱلشَّجَرَةِ فَعَلِمَ مَا فِى قُلُوبِهِمْ فَأَنزَلَ ٱلسَّكِينَةَ عَلَيْهِمْ وَأَثَٰبَهُمْ فَتْحًۭا قَرِيبًۭا', 'لقد رضى الله عن المؤمنين إذ يبايعونك تحت الشجرة فعلم ما فى قلوبهم فأنزل السكينة عليهم وأثبهم فتحا قريبا', NULL, 513, 'local:hafs-text.json'),
  ('hafs-48-19', 'hafs', 48, 19, 'وَمَغَانِمَ كَثِيرَةًۭ يَأْخُذُونَهَا ۗ وَكَانَ ٱللَّهُ عَزِيزًا حَكِيمًۭا', 'ومغانم كثيرة يأخذونها  وكان الله عزيزا حكيما', NULL, 513, 'local:hafs-text.json'),
  ('hafs-48-20', 'hafs', 48, 20, 'وَعَدَكُمُ ٱللَّهُ مَغَانِمَ كَثِيرَةًۭ تَأْخُذُونَهَا فَعَجَّلَ لَكُمْ هَٰذِهِۦ وَكَفَّ أَيْدِىَ ٱلنَّاسِ عَنكُمْ وَلِتَكُونَ ءَايَةًۭ لِّلْمُؤْمِنِينَ وَيَهْدِيَكُمْ صِرَٰطًۭا مُّسْتَقِيمًۭا', 'وعدكم الله مغانم كثيرة تأخذونها فعجل لكم هذه وكف أيدى الناس عنكم ولتكون ءاية للمؤمنين ويهديكم صرطا مستقيما', NULL, 513, 'local:hafs-text.json'),
  ('hafs-48-21', 'hafs', 48, 21, 'وَأُخْرَىٰ لَمْ تَقْدِرُوا۟ عَلَيْهَا قَدْ أَحَاطَ ٱللَّهُ بِهَا ۚ وَكَانَ ٱللَّهُ عَلَىٰ كُلِّ شَىْءٍۢ قَدِيرًۭا', 'وأخرى لم تقدروا عليها قد أحاط الله بها  وكان الله على كل شىء قديرا', NULL, 513, 'local:hafs-text.json'),
  ('hafs-48-22', 'hafs', 48, 22, 'وَلَوْ قَٰتَلَكُمُ ٱلَّذِينَ كَفَرُوا۟ لَوَلَّوُا۟ ٱلْأَدْبَٰرَ ثُمَّ لَا يَجِدُونَ وَلِيًّۭا وَلَا نَصِيرًۭا', 'ولو قتلكم الذين كفروا لولوا الأدبر ثم لا يجدون وليا ولا نصيرا', NULL, 513, 'local:hafs-text.json'),
  ('hafs-48-23', 'hafs', 48, 23, 'سُنَّةَ ٱللَّهِ ٱلَّتِى قَدْ خَلَتْ مِن قَبْلُ ۖ وَلَن تَجِدَ لِسُنَّةِ ٱللَّهِ تَبْدِيلًۭا', 'سنة الله التى قد خلت من قبل  ولن تجد لسنة الله تبديلا', NULL, 513, 'local:hafs-text.json'),
  ('hafs-48-24', 'hafs', 48, 24, 'وَهُوَ ٱلَّذِى كَفَّ أَيْدِيَهُمْ عَنكُمْ وَأَيْدِيَكُمْ عَنْهُم بِبَطْنِ مَكَّةَ مِنۢ بَعْدِ أَنْ أَظْفَرَكُمْ عَلَيْهِمْ ۚ وَكَانَ ٱللَّهُ بِمَا تَعْمَلُونَ بَصِيرًا', 'وهو الذى كف أيديهم عنكم وأيديكم عنهم ببطن مكة من بعد أن أظفركم عليهم  وكان الله بما تعملون بصيرا', NULL, 514, 'local:hafs-text.json'),
  ('hafs-48-25', 'hafs', 48, 25, 'هُمُ ٱلَّذِينَ كَفَرُوا۟ وَصَدُّوكُمْ عَنِ ٱلْمَسْجِدِ ٱلْحَرَامِ وَٱلْهَدْىَ مَعْكُوفًا أَن يَبْلُغَ مَحِلَّهُۥ ۚ وَلَوْلَا رِجَالٌۭ مُّؤْمِنُونَ وَنِسَآءٌۭ مُّؤْمِنَٰتٌۭ لَّمْ تَعْلَمُوهُمْ أَن تَطَـُٔوهُمْ فَتُصِيبَكُم مِّنْهُم مَّعَرَّةٌۢ بِغَيْرِ عِلْمٍۢ ۖ لِّيُدْخِلَ ٱللَّهُ فِى رَحْمَتِهِۦ مَن يَشَآءُ ۚ لَوْ تَزَيَّلُوا۟ لَعَذَّبْنَا ٱلَّذِينَ كَفَرُوا۟ مِنْهُمْ عَذَابًا أَلِيمًا', 'هم الذين كفروا وصدوكم عن المسجد الحرام والهدى معكوفا أن يبلغ محله  ولولا رجال مؤمنون ونساء مؤمنت لم تعلموهم أن تطوهم فتصيبكم منهم معرة بغير علم  ليدخل الله فى رحمته من يشاء  لو تزيلوا لعذبنا الذين كفروا منهم عذابا أليما', NULL, 514, 'local:hafs-text.json'),
  ('hafs-48-26', 'hafs', 48, 26, 'إِذْ جَعَلَ ٱلَّذِينَ كَفَرُوا۟ فِى قُلُوبِهِمُ ٱلْحَمِيَّةَ حَمِيَّةَ ٱلْجَٰهِلِيَّةِ فَأَنزَلَ ٱللَّهُ سَكِينَتَهُۥ عَلَىٰ رَسُولِهِۦ وَعَلَى ٱلْمُؤْمِنِينَ وَأَلْزَمَهُمْ كَلِمَةَ ٱلتَّقْوَىٰ وَكَانُوٓا۟ أَحَقَّ بِهَا وَأَهْلَهَا ۚ وَكَانَ ٱللَّهُ بِكُلِّ شَىْءٍ عَلِيمًۭا', 'إذ جعل الذين كفروا فى قلوبهم الحمية حمية الجهلية فأنزل الله سكينته على رسوله وعلى المؤمنين وألزمهم كلمة التقوى وكانوا أحق بها وأهلها  وكان الله بكل شىء عليما', NULL, 514, 'local:hafs-text.json'),
  ('hafs-48-27', 'hafs', 48, 27, 'لَّقَدْ صَدَقَ ٱللَّهُ رَسُولَهُ ٱلرُّءْيَا بِٱلْحَقِّ ۖ لَتَدْخُلُنَّ ٱلْمَسْجِدَ ٱلْحَرَامَ إِن شَآءَ ٱللَّهُ ءَامِنِينَ مُحَلِّقِينَ رُءُوسَكُمْ وَمُقَصِّرِينَ لَا تَخَافُونَ ۖ فَعَلِمَ مَا لَمْ تَعْلَمُوا۟ فَجَعَلَ مِن دُونِ ذَٰلِكَ فَتْحًۭا قَرِيبًا', 'لقد صدق الله رسوله الرءيا بالحق  لتدخلن المسجد الحرام إن شاء الله ءامنين محلقين رءوسكم ومقصرين لا تخافون  فعلم ما لم تعلموا فجعل من دون ذلك فتحا قريبا', NULL, 514, 'local:hafs-text.json'),
  ('hafs-48-28', 'hafs', 48, 28, 'هُوَ ٱلَّذِىٓ أَرْسَلَ رَسُولَهُۥ بِٱلْهُدَىٰ وَدِينِ ٱلْحَقِّ لِيُظْهِرَهُۥ عَلَى ٱلدِّينِ كُلِّهِۦ ۚ وَكَفَىٰ بِٱللَّهِ شَهِيدًۭا', 'هو الذى أرسل رسوله بالهدى ودين الحق ليظهره على الدين كله  وكفى بالله شهيدا', NULL, 514, 'local:hafs-text.json'),
  ('hafs-48-29', 'hafs', 48, 29, 'مُّحَمَّدٌۭ رَّسُولُ ٱللَّهِ ۚ وَٱلَّذِينَ مَعَهُۥٓ أَشِدَّآءُ عَلَى ٱلْكُفَّارِ رُحَمَآءُ بَيْنَهُمْ ۖ تَرَىٰهُمْ رُكَّعًۭا سُجَّدًۭا يَبْتَغُونَ فَضْلًۭا مِّنَ ٱللَّهِ وَرِضْوَٰنًۭا ۖ سِيمَاهُمْ فِى وُجُوهِهِم مِّنْ أَثَرِ ٱلسُّجُودِ ۚ ذَٰلِكَ مَثَلُهُمْ فِى ٱلتَّوْرَىٰةِ ۚ وَمَثَلُهُمْ فِى ٱلْإِنجِيلِ كَزَرْعٍ أَخْرَجَ شَطْـَٔهُۥ فَـَٔازَرَهُۥ فَٱسْتَغْلَظَ فَٱسْتَوَىٰ عَلَىٰ سُوقِهِۦ يُعْجِبُ ٱلزُّرَّاعَ لِيَغِيظَ بِهِمُ ٱلْكُفَّارَ ۗ وَعَدَ ٱللَّهُ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ مِنْهُم مَّغْفِرَةًۭ وَأَجْرًا عَظِيمًۢا', 'محمد رسول الله  والذين معه أشداء على الكفار رحماء بينهم  ترىهم ركعا سجدا يبتغون فضلا من الله ورضونا  سيماهم فى وجوههم من أثر السجود  ذلك مثلهم فى التورىة  ومثلهم فى الإنجيل كزرع أخرج شطه فازره فاستغلظ فاستوى على سوقه يعجب الزراع ليغيظ بهم الكفار  وعد الله الذين ءامنوا وعملوا الصلحت منهم مغفرة وأجرا عظيما', NULL, 515, 'local:hafs-text.json'),
  ('hafs-49-1', 'hafs', 49, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تُقَدِّمُوا۟ بَيْنَ يَدَىِ ٱللَّهِ وَرَسُولِهِۦ ۖ وَٱتَّقُوا۟ ٱللَّهَ ۚ إِنَّ ٱللَّهَ سَمِيعٌ عَلِيمٌۭ', 'بسم الله الرحمن الرحيم يأيها الذين ءامنوا لا تقدموا بين يدى الله ورسوله  واتقوا الله  إن الله سميع عليم', NULL, 515, 'local:hafs-text.json'),
  ('hafs-49-2', 'hafs', 49, 2, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَرْفَعُوٓا۟ أَصْوَٰتَكُمْ فَوْقَ صَوْتِ ٱلنَّبِىِّ وَلَا تَجْهَرُوا۟ لَهُۥ بِٱلْقَوْلِ كَجَهْرِ بَعْضِكُمْ لِبَعْضٍ أَن تَحْبَطَ أَعْمَٰلُكُمْ وَأَنتُمْ لَا تَشْعُرُونَ', 'يأيها الذين ءامنوا لا ترفعوا أصوتكم فوق صوت النبى ولا تجهروا له بالقول كجهر بعضكم لبعض أن تحبط أعملكم وأنتم لا تشعرون', NULL, 515, 'local:hafs-text.json'),
  ('hafs-49-3', 'hafs', 49, 3, 'إِنَّ ٱلَّذِينَ يَغُضُّونَ أَصْوَٰتَهُمْ عِندَ رَسُولِ ٱللَّهِ أُو۟لَٰٓئِكَ ٱلَّذِينَ ٱمْتَحَنَ ٱللَّهُ قُلُوبَهُمْ لِلتَّقْوَىٰ ۚ لَهُم مَّغْفِرَةٌۭ وَأَجْرٌ عَظِيمٌ', 'إن الذين يغضون أصوتهم عند رسول الله أولئك الذين امتحن الله قلوبهم للتقوى  لهم مغفرة وأجر عظيم', NULL, 515, 'local:hafs-text.json'),
  ('hafs-49-4', 'hafs', 49, 4, 'إِنَّ ٱلَّذِينَ يُنَادُونَكَ مِن وَرَآءِ ٱلْحُجُرَٰتِ أَكْثَرُهُمْ لَا يَعْقِلُونَ', 'إن الذين ينادونك من وراء الحجرت أكثرهم لا يعقلون', NULL, 515, 'local:hafs-text.json'),
  ('hafs-49-5', 'hafs', 49, 5, 'وَلَوْ أَنَّهُمْ صَبَرُوا۟ حَتَّىٰ تَخْرُجَ إِلَيْهِمْ لَكَانَ خَيْرًۭا لَّهُمْ ۚ وَٱللَّهُ غَفُورٌۭ رَّحِيمٌۭ', 'ولو أنهم صبروا حتى تخرج إليهم لكان خيرا لهم  والله غفور رحيم', NULL, 516, 'local:hafs-text.json'),
  ('hafs-49-6', 'hafs', 49, 6, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِن جَآءَكُمْ فَاسِقٌۢ بِنَبَإٍۢ فَتَبَيَّنُوٓا۟ أَن تُصِيبُوا۟ قَوْمًۢا بِجَهَٰلَةٍۢ فَتُصْبِحُوا۟ عَلَىٰ مَا فَعَلْتُمْ نَٰدِمِينَ', 'يأيها الذين ءامنوا إن جاءكم فاسق بنبإ فتبينوا أن تصيبوا قوما بجهلة فتصبحوا على ما فعلتم ندمين', NULL, 516, 'local:hafs-text.json'),
  ('hafs-49-7', 'hafs', 49, 7, 'وَٱعْلَمُوٓا۟ أَنَّ فِيكُمْ رَسُولَ ٱللَّهِ ۚ لَوْ يُطِيعُكُمْ فِى كَثِيرٍۢ مِّنَ ٱلْأَمْرِ لَعَنِتُّمْ وَلَٰكِنَّ ٱللَّهَ حَبَّبَ إِلَيْكُمُ ٱلْإِيمَٰنَ وَزَيَّنَهُۥ فِى قُلُوبِكُمْ وَكَرَّهَ إِلَيْكُمُ ٱلْكُفْرَ وَٱلْفُسُوقَ وَٱلْعِصْيَانَ ۚ أُو۟لَٰٓئِكَ هُمُ ٱلرَّٰشِدُونَ', 'واعلموا أن فيكم رسول الله  لو يطيعكم فى كثير من الأمر لعنتم ولكن الله حبب إليكم الإيمن وزينه فى قلوبكم وكره إليكم الكفر والفسوق والعصيان  أولئك هم الرشدون', NULL, 516, 'local:hafs-text.json'),
  ('hafs-49-8', 'hafs', 49, 8, 'فَضْلًۭا مِّنَ ٱللَّهِ وَنِعْمَةًۭ ۚ وَٱللَّهُ عَلِيمٌ حَكِيمٌۭ', 'فضلا من الله ونعمة  والله عليم حكيم', NULL, 516, 'local:hafs-text.json'),
  ('hafs-49-9', 'hafs', 49, 9, 'وَإِن طَآئِفَتَانِ مِنَ ٱلْمُؤْمِنِينَ ٱقْتَتَلُوا۟ فَأَصْلِحُوا۟ بَيْنَهُمَا ۖ فَإِنۢ بَغَتْ إِحْدَىٰهُمَا عَلَى ٱلْأُخْرَىٰ فَقَٰتِلُوا۟ ٱلَّتِى تَبْغِى حَتَّىٰ تَفِىٓءَ إِلَىٰٓ أَمْرِ ٱللَّهِ ۚ فَإِن فَآءَتْ فَأَصْلِحُوا۟ بَيْنَهُمَا بِٱلْعَدْلِ وَأَقْسِطُوٓا۟ ۖ إِنَّ ٱللَّهَ يُحِبُّ ٱلْمُقْسِطِينَ', 'وإن طائفتان من المؤمنين اقتتلوا فأصلحوا بينهما  فإن بغت إحدىهما على الأخرى فقتلوا التى تبغى حتى تفىء إلى أمر الله  فإن فاءت فأصلحوا بينهما بالعدل وأقسطوا  إن الله يحب المقسطين', NULL, 516, 'local:hafs-text.json'),
  ('hafs-49-10', 'hafs', 49, 10, 'إِنَّمَا ٱلْمُؤْمِنُونَ إِخْوَةٌۭ فَأَصْلِحُوا۟ بَيْنَ أَخَوَيْكُمْ ۚ وَٱتَّقُوا۟ ٱللَّهَ لَعَلَّكُمْ تُرْحَمُونَ', 'إنما المؤمنون إخوة فأصلحوا بين أخويكم  واتقوا الله لعلكم ترحمون', NULL, 516, 'local:hafs-text.json'),
  ('hafs-49-11', 'hafs', 49, 11, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا يَسْخَرْ قَوْمٌۭ مِّن قَوْمٍ عَسَىٰٓ أَن يَكُونُوا۟ خَيْرًۭا مِّنْهُمْ وَلَا نِسَآءٌۭ مِّن نِّسَآءٍ عَسَىٰٓ أَن يَكُنَّ خَيْرًۭا مِّنْهُنَّ ۖ وَلَا تَلْمِزُوٓا۟ أَنفُسَكُمْ وَلَا تَنَابَزُوا۟ بِٱلْأَلْقَٰبِ ۖ بِئْسَ ٱلِٱسْمُ ٱلْفُسُوقُ بَعْدَ ٱلْإِيمَٰنِ ۚ وَمَن لَّمْ يَتُبْ فَأُو۟لَٰٓئِكَ هُمُ ٱلظَّٰلِمُونَ', 'يأيها الذين ءامنوا لا يسخر قوم من قوم عسى أن يكونوا خيرا منهم ولا نساء من نساء عسى أن يكن خيرا منهن  ولا تلمزوا أنفسكم ولا تنابزوا بالألقب  بئس الاسم الفسوق بعد الإيمن  ومن لم يتب فأولئك هم الظلمون', NULL, 516, 'local:hafs-text.json'),
  ('hafs-49-12', 'hafs', 49, 12, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱجْتَنِبُوا۟ كَثِيرًۭا مِّنَ ٱلظَّنِّ إِنَّ بَعْضَ ٱلظَّنِّ إِثْمٌۭ ۖ وَلَا تَجَسَّسُوا۟ وَلَا يَغْتَب بَّعْضُكُم بَعْضًا ۚ أَيُحِبُّ أَحَدُكُمْ أَن يَأْكُلَ لَحْمَ أَخِيهِ مَيْتًۭا فَكَرِهْتُمُوهُ ۚ وَٱتَّقُوا۟ ٱللَّهَ ۚ إِنَّ ٱللَّهَ تَوَّابٌۭ رَّحِيمٌۭ', 'يأيها الذين ءامنوا اجتنبوا كثيرا من الظن إن بعض الظن إثم  ولا تجسسوا ولا يغتب بعضكم بعضا  أيحب أحدكم أن يأكل لحم أخيه ميتا فكرهتموه  واتقوا الله  إن الله تواب رحيم', NULL, 517, 'local:hafs-text.json'),
  ('hafs-49-13', 'hafs', 49, 13, 'يَٰٓأَيُّهَا ٱلنَّاسُ إِنَّا خَلَقْنَٰكُم مِّن ذَكَرٍۢ وَأُنثَىٰ وَجَعَلْنَٰكُمْ شُعُوبًۭا وَقَبَآئِلَ لِتَعَارَفُوٓا۟ ۚ إِنَّ أَكْرَمَكُمْ عِندَ ٱللَّهِ أَتْقَىٰكُمْ ۚ إِنَّ ٱللَّهَ عَلِيمٌ خَبِيرٌۭ', 'يأيها الناس إنا خلقنكم من ذكر وأنثى وجعلنكم شعوبا وقبائل لتعارفوا  إن أكرمكم عند الله أتقىكم  إن الله عليم خبير', NULL, 517, 'local:hafs-text.json'),
  ('hafs-49-14', 'hafs', 49, 14, '۞ قَالَتِ ٱلْأَعْرَابُ ءَامَنَّا ۖ قُل لَّمْ تُؤْمِنُوا۟ وَلَٰكِن قُولُوٓا۟ أَسْلَمْنَا وَلَمَّا يَدْخُلِ ٱلْإِيمَٰنُ فِى قُلُوبِكُمْ ۖ وَإِن تُطِيعُوا۟ ٱللَّهَ وَرَسُولَهُۥ لَا يَلِتْكُم مِّنْ أَعْمَٰلِكُمْ شَيْـًٔا ۚ إِنَّ ٱللَّهَ غَفُورٌۭ رَّحِيمٌ', 'قالت الأعراب ءامنا  قل لم تؤمنوا ولكن قولوا أسلمنا ولما يدخل الإيمن فى قلوبكم  وإن تطيعوا الله ورسوله لا يلتكم من أعملكم شيا  إن الله غفور رحيم', NULL, 517, 'local:hafs-text.json'),
  ('hafs-49-15', 'hafs', 49, 15, 'إِنَّمَا ٱلْمُؤْمِنُونَ ٱلَّذِينَ ءَامَنُوا۟ بِٱللَّهِ وَرَسُولِهِۦ ثُمَّ لَمْ يَرْتَابُوا۟ وَجَٰهَدُوا۟ بِأَمْوَٰلِهِمْ وَأَنفُسِهِمْ فِى سَبِيلِ ٱللَّهِ ۚ أُو۟لَٰٓئِكَ هُمُ ٱلصَّٰدِقُونَ', 'إنما المؤمنون الذين ءامنوا بالله ورسوله ثم لم يرتابوا وجهدوا بأمولهم وأنفسهم فى سبيل الله  أولئك هم الصدقون', NULL, 517, 'local:hafs-text.json'),
  ('hafs-49-16', 'hafs', 49, 16, 'قُلْ أَتُعَلِّمُونَ ٱللَّهَ بِدِينِكُمْ وَٱللَّهُ يَعْلَمُ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ ۚ وَٱللَّهُ بِكُلِّ شَىْءٍ عَلِيمٌۭ', 'قل أتعلمون الله بدينكم والله يعلم ما فى السموت وما فى الأرض  والله بكل شىء عليم', NULL, 517, 'local:hafs-text.json'),
  ('hafs-49-17', 'hafs', 49, 17, 'يَمُنُّونَ عَلَيْكَ أَنْ أَسْلَمُوا۟ ۖ قُل لَّا تَمُنُّوا۟ عَلَىَّ إِسْلَٰمَكُم ۖ بَلِ ٱللَّهُ يَمُنُّ عَلَيْكُمْ أَنْ هَدَىٰكُمْ لِلْإِيمَٰنِ إِن كُنتُمْ صَٰدِقِينَ', 'يمنون عليك أن أسلموا  قل لا تمنوا على إسلمكم  بل الله يمن عليكم أن هدىكم للإيمن إن كنتم صدقين', NULL, 517, 'local:hafs-text.json'),
  ('hafs-49-18', 'hafs', 49, 18, 'إِنَّ ٱللَّهَ يَعْلَمُ غَيْبَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ ۚ وَٱللَّهُ بَصِيرٌۢ بِمَا تَعْمَلُونَ', 'إن الله يعلم غيب السموت والأرض  والله بصير بما تعملون', NULL, 517, 'local:hafs-text.json'),
  ('hafs-50-1', 'hafs', 50, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ قٓ ۚ وَٱلْقُرْءَانِ ٱلْمَجِيدِ', 'بسم الله الرحمن الرحيم ق  والقرءان المجيد', NULL, 518, 'local:hafs-text.json'),
  ('hafs-50-2', 'hafs', 50, 2, 'بَلْ عَجِبُوٓا۟ أَن جَآءَهُم مُّنذِرٌۭ مِّنْهُمْ فَقَالَ ٱلْكَٰفِرُونَ هَٰذَا شَىْءٌ عَجِيبٌ', 'بل عجبوا أن جاءهم منذر منهم فقال الكفرون هذا شىء عجيب', NULL, 518, 'local:hafs-text.json'),
  ('hafs-50-3', 'hafs', 50, 3, 'أَءِذَا مِتْنَا وَكُنَّا تُرَابًۭا ۖ ذَٰلِكَ رَجْعٌۢ بَعِيدٌۭ', 'أءذا متنا وكنا ترابا  ذلك رجع بعيد', NULL, 518, 'local:hafs-text.json'),
  ('hafs-50-4', 'hafs', 50, 4, 'قَدْ عَلِمْنَا مَا تَنقُصُ ٱلْأَرْضُ مِنْهُمْ ۖ وَعِندَنَا كِتَٰبٌ حَفِيظٌۢ', 'قد علمنا ما تنقص الأرض منهم  وعندنا كتب حفيظ', NULL, 518, 'local:hafs-text.json'),
  ('hafs-50-5', 'hafs', 50, 5, 'بَلْ كَذَّبُوا۟ بِٱلْحَقِّ لَمَّا جَآءَهُمْ فَهُمْ فِىٓ أَمْرٍۢ مَّرِيجٍ', 'بل كذبوا بالحق لما جاءهم فهم فى أمر مريج', NULL, 518, 'local:hafs-text.json'),
  ('hafs-50-6', 'hafs', 50, 6, 'أَفَلَمْ يَنظُرُوٓا۟ إِلَى ٱلسَّمَآءِ فَوْقَهُمْ كَيْفَ بَنَيْنَٰهَا وَزَيَّنَّٰهَا وَمَا لَهَا مِن فُرُوجٍۢ', 'أفلم ينظروا إلى السماء فوقهم كيف بنينها وزينها وما لها من فروج', NULL, 518, 'local:hafs-text.json'),
  ('hafs-50-7', 'hafs', 50, 7, 'وَٱلْأَرْضَ مَدَدْنَٰهَا وَأَلْقَيْنَا فِيهَا رَوَٰسِىَ وَأَنۢبَتْنَا فِيهَا مِن كُلِّ زَوْجٍۭ بَهِيجٍۢ', 'والأرض مددنها وألقينا فيها روسى وأنبتنا فيها من كل زوج بهيج', NULL, 518, 'local:hafs-text.json'),
  ('hafs-50-8', 'hafs', 50, 8, 'تَبْصِرَةًۭ وَذِكْرَىٰ لِكُلِّ عَبْدٍۢ مُّنِيبٍۢ', 'تبصرة وذكرى لكل عبد منيب', NULL, 518, 'local:hafs-text.json'),
  ('hafs-50-9', 'hafs', 50, 9, 'وَنَزَّلْنَا مِنَ ٱلسَّمَآءِ مَآءًۭ مُّبَٰرَكًۭا فَأَنۢبَتْنَا بِهِۦ جَنَّٰتٍۢ وَحَبَّ ٱلْحَصِيدِ', 'ونزلنا من السماء ماء مبركا فأنبتنا به جنت وحب الحصيد', NULL, 518, 'local:hafs-text.json'),
  ('hafs-50-10', 'hafs', 50, 10, 'وَٱلنَّخْلَ بَاسِقَٰتٍۢ لَّهَا طَلْعٌۭ نَّضِيدٌۭ', 'والنخل باسقت لها طلع نضيد', NULL, 518, 'local:hafs-text.json'),
  ('hafs-50-11', 'hafs', 50, 11, 'رِّزْقًۭا لِّلْعِبَادِ ۖ وَأَحْيَيْنَا بِهِۦ بَلْدَةًۭ مَّيْتًۭا ۚ كَذَٰلِكَ ٱلْخُرُوجُ', 'رزقا للعباد  وأحيينا به بلدة ميتا  كذلك الخروج', NULL, 518, 'local:hafs-text.json'),
  ('hafs-50-12', 'hafs', 50, 12, 'كَذَّبَتْ قَبْلَهُمْ قَوْمُ نُوحٍۢ وَأَصْحَٰبُ ٱلرَّسِّ وَثَمُودُ', 'كذبت قبلهم قوم نوح وأصحب الرس وثمود', NULL, 518, 'local:hafs-text.json'),
  ('hafs-50-13', 'hafs', 50, 13, 'وَعَادٌۭ وَفِرْعَوْنُ وَإِخْوَٰنُ لُوطٍۢ', 'وعاد وفرعون وإخون لوط', NULL, 518, 'local:hafs-text.json'),
  ('hafs-50-14', 'hafs', 50, 14, 'وَأَصْحَٰبُ ٱلْأَيْكَةِ وَقَوْمُ تُبَّعٍۢ ۚ كُلٌّۭ كَذَّبَ ٱلرُّسُلَ فَحَقَّ وَعِيدِ', 'وأصحب الأيكة وقوم تبع  كل كذب الرسل فحق وعيد', NULL, 518, 'local:hafs-text.json'),
  ('hafs-50-15', 'hafs', 50, 15, 'أَفَعَيِينَا بِٱلْخَلْقِ ٱلْأَوَّلِ ۚ بَلْ هُمْ فِى لَبْسٍۢ مِّنْ خَلْقٍۢ جَدِيدٍۢ', 'أفعيينا بالخلق الأول  بل هم فى لبس من خلق جديد', NULL, 518, 'local:hafs-text.json'),
  ('hafs-50-16', 'hafs', 50, 16, 'وَلَقَدْ خَلَقْنَا ٱلْإِنسَٰنَ وَنَعْلَمُ مَا تُوَسْوِسُ بِهِۦ نَفْسُهُۥ ۖ وَنَحْنُ أَقْرَبُ إِلَيْهِ مِنْ حَبْلِ ٱلْوَرِيدِ', 'ولقد خلقنا الإنسن ونعلم ما توسوس به نفسه  ونحن أقرب إليه من حبل الوريد', NULL, 519, 'local:hafs-text.json'),
  ('hafs-50-17', 'hafs', 50, 17, 'إِذْ يَتَلَقَّى ٱلْمُتَلَقِّيَانِ عَنِ ٱلْيَمِينِ وَعَنِ ٱلشِّمَالِ قَعِيدٌۭ', 'إذ يتلقى المتلقيان عن اليمين وعن الشمال قعيد', NULL, 519, 'local:hafs-text.json'),
  ('hafs-50-18', 'hafs', 50, 18, 'مَّا يَلْفِظُ مِن قَوْلٍ إِلَّا لَدَيْهِ رَقِيبٌ عَتِيدٌۭ', 'ما يلفظ من قول إلا لديه رقيب عتيد', NULL, 519, 'local:hafs-text.json'),
  ('hafs-50-19', 'hafs', 50, 19, 'وَجَآءَتْ سَكْرَةُ ٱلْمَوْتِ بِٱلْحَقِّ ۖ ذَٰلِكَ مَا كُنتَ مِنْهُ تَحِيدُ', 'وجاءت سكرة الموت بالحق  ذلك ما كنت منه تحيد', NULL, 519, 'local:hafs-text.json'),
  ('hafs-50-20', 'hafs', 50, 20, 'وَنُفِخَ فِى ٱلصُّورِ ۚ ذَٰلِكَ يَوْمُ ٱلْوَعِيدِ', 'ونفخ فى الصور  ذلك يوم الوعيد', NULL, 519, 'local:hafs-text.json'),
  ('hafs-50-21', 'hafs', 50, 21, 'وَجَآءَتْ كُلُّ نَفْسٍۢ مَّعَهَا سَآئِقٌۭ وَشَهِيدٌۭ', 'وجاءت كل نفس معها سائق وشهيد', NULL, 519, 'local:hafs-text.json'),
  ('hafs-50-22', 'hafs', 50, 22, 'لَّقَدْ كُنتَ فِى غَفْلَةٍۢ مِّنْ هَٰذَا فَكَشَفْنَا عَنكَ غِطَآءَكَ فَبَصَرُكَ ٱلْيَوْمَ حَدِيدٌۭ', 'لقد كنت فى غفلة من هذا فكشفنا عنك غطاءك فبصرك اليوم حديد', NULL, 519, 'local:hafs-text.json'),
  ('hafs-50-23', 'hafs', 50, 23, 'وَقَالَ قَرِينُهُۥ هَٰذَا مَا لَدَىَّ عَتِيدٌ', 'وقال قرينه هذا ما لدى عتيد', NULL, 519, 'local:hafs-text.json'),
  ('hafs-50-24', 'hafs', 50, 24, 'أَلْقِيَا فِى جَهَنَّمَ كُلَّ كَفَّارٍ عَنِيدٍۢ', 'ألقيا فى جهنم كل كفار عنيد', NULL, 519, 'local:hafs-text.json'),
  ('hafs-50-25', 'hafs', 50, 25, 'مَّنَّاعٍۢ لِّلْخَيْرِ مُعْتَدٍۢ مُّرِيبٍ', 'مناع للخير معتد مريب', NULL, 519, 'local:hafs-text.json'),
  ('hafs-50-26', 'hafs', 50, 26, 'ٱلَّذِى جَعَلَ مَعَ ٱللَّهِ إِلَٰهًا ءَاخَرَ فَأَلْقِيَاهُ فِى ٱلْعَذَابِ ٱلشَّدِيدِ', 'الذى جعل مع الله إلها ءاخر فألقياه فى العذاب الشديد', NULL, 519, 'local:hafs-text.json'),
  ('hafs-50-27', 'hafs', 50, 27, '۞ قَالَ قَرِينُهُۥ رَبَّنَا مَآ أَطْغَيْتُهُۥ وَلَٰكِن كَانَ فِى ضَلَٰلٍۭ بَعِيدٍۢ', 'قال قرينه ربنا ما أطغيته ولكن كان فى ضلل بعيد', NULL, 519, 'local:hafs-text.json'),
  ('hafs-50-28', 'hafs', 50, 28, 'قَالَ لَا تَخْتَصِمُوا۟ لَدَىَّ وَقَدْ قَدَّمْتُ إِلَيْكُم بِٱلْوَعِيدِ', 'قال لا تختصموا لدى وقد قدمت إليكم بالوعيد', NULL, 519, 'local:hafs-text.json'),
  ('hafs-50-29', 'hafs', 50, 29, 'مَا يُبَدَّلُ ٱلْقَوْلُ لَدَىَّ وَمَآ أَنَا۠ بِظَلَّٰمٍۢ لِّلْعَبِيدِ', 'ما يبدل القول لدى وما أنا بظلم للعبيد', NULL, 519, 'local:hafs-text.json'),
  ('hafs-50-30', 'hafs', 50, 30, 'يَوْمَ نَقُولُ لِجَهَنَّمَ هَلِ ٱمْتَلَأْتِ وَتَقُولُ هَلْ مِن مَّزِيدٍۢ', 'يوم نقول لجهنم هل امتلأت وتقول هل من مزيد', NULL, 519, 'local:hafs-text.json'),
  ('hafs-50-31', 'hafs', 50, 31, 'وَأُزْلِفَتِ ٱلْجَنَّةُ لِلْمُتَّقِينَ غَيْرَ بَعِيدٍ', 'وأزلفت الجنة للمتقين غير بعيد', NULL, 519, 'local:hafs-text.json'),
  ('hafs-50-32', 'hafs', 50, 32, 'هَٰذَا مَا تُوعَدُونَ لِكُلِّ أَوَّابٍ حَفِيظٍۢ', 'هذا ما توعدون لكل أواب حفيظ', NULL, 519, 'local:hafs-text.json'),
  ('hafs-50-33', 'hafs', 50, 33, 'مَّنْ خَشِىَ ٱلرَّحْمَٰنَ بِٱلْغَيْبِ وَجَآءَ بِقَلْبٍۢ مُّنِيبٍ', 'من خشى الرحمن بالغيب وجاء بقلب منيب', NULL, 519, 'local:hafs-text.json'),
  ('hafs-50-34', 'hafs', 50, 34, 'ٱدْخُلُوهَا بِسَلَٰمٍۢ ۖ ذَٰلِكَ يَوْمُ ٱلْخُلُودِ', 'ادخلوها بسلم  ذلك يوم الخلود', NULL, 519, 'local:hafs-text.json'),
  ('hafs-50-35', 'hafs', 50, 35, 'لَهُم مَّا يَشَآءُونَ فِيهَا وَلَدَيْنَا مَزِيدٌۭ', 'لهم ما يشاءون فيها ولدينا مزيد', NULL, 519, 'local:hafs-text.json'),
  ('hafs-50-36', 'hafs', 50, 36, 'وَكَمْ أَهْلَكْنَا قَبْلَهُم مِّن قَرْنٍ هُمْ أَشَدُّ مِنْهُم بَطْشًۭا فَنَقَّبُوا۟ فِى ٱلْبِلَٰدِ هَلْ مِن مَّحِيصٍ', 'وكم أهلكنا قبلهم من قرن هم أشد منهم بطشا فنقبوا فى البلد هل من محيص', NULL, 520, 'local:hafs-text.json'),
  ('hafs-50-37', 'hafs', 50, 37, 'إِنَّ فِى ذَٰلِكَ لَذِكْرَىٰ لِمَن كَانَ لَهُۥ قَلْبٌ أَوْ أَلْقَى ٱلسَّمْعَ وَهُوَ شَهِيدٌۭ', 'إن فى ذلك لذكرى لمن كان له قلب أو ألقى السمع وهو شهيد', NULL, 520, 'local:hafs-text.json'),
  ('hafs-50-38', 'hafs', 50, 38, 'وَلَقَدْ خَلَقْنَا ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ وَمَا بَيْنَهُمَا فِى سِتَّةِ أَيَّامٍۢ وَمَا مَسَّنَا مِن لُّغُوبٍۢ', 'ولقد خلقنا السموت والأرض وما بينهما فى ستة أيام وما مسنا من لغوب', NULL, 520, 'local:hafs-text.json'),
  ('hafs-50-39', 'hafs', 50, 39, 'فَٱصْبِرْ عَلَىٰ مَا يَقُولُونَ وَسَبِّحْ بِحَمْدِ رَبِّكَ قَبْلَ طُلُوعِ ٱلشَّمْسِ وَقَبْلَ ٱلْغُرُوبِ', 'فاصبر على ما يقولون وسبح بحمد ربك قبل طلوع الشمس وقبل الغروب', NULL, 520, 'local:hafs-text.json'),
  ('hafs-50-40', 'hafs', 50, 40, 'وَمِنَ ٱلَّيْلِ فَسَبِّحْهُ وَأَدْبَٰرَ ٱلسُّجُودِ', 'ومن اليل فسبحه وأدبر السجود', NULL, 520, 'local:hafs-text.json'),
  ('hafs-50-41', 'hafs', 50, 41, 'وَٱسْتَمِعْ يَوْمَ يُنَادِ ٱلْمُنَادِ مِن مَّكَانٍۢ قَرِيبٍۢ', 'واستمع يوم يناد المناد من مكان قريب', NULL, 520, 'local:hafs-text.json'),
  ('hafs-50-42', 'hafs', 50, 42, 'يَوْمَ يَسْمَعُونَ ٱلصَّيْحَةَ بِٱلْحَقِّ ۚ ذَٰلِكَ يَوْمُ ٱلْخُرُوجِ', 'يوم يسمعون الصيحة بالحق  ذلك يوم الخروج', NULL, 520, 'local:hafs-text.json'),
  ('hafs-50-43', 'hafs', 50, 43, 'إِنَّا نَحْنُ نُحْىِۦ وَنُمِيتُ وَإِلَيْنَا ٱلْمَصِيرُ', 'إنا نحن نحى ونميت وإلينا المصير', NULL, 520, 'local:hafs-text.json'),
  ('hafs-50-44', 'hafs', 50, 44, 'يَوْمَ تَشَقَّقُ ٱلْأَرْضُ عَنْهُمْ سِرَاعًۭا ۚ ذَٰلِكَ حَشْرٌ عَلَيْنَا يَسِيرٌۭ', 'يوم تشقق الأرض عنهم سراعا  ذلك حشر علينا يسير', NULL, 520, 'local:hafs-text.json'),
  ('hafs-50-45', 'hafs', 50, 45, 'نَّحْنُ أَعْلَمُ بِمَا يَقُولُونَ ۖ وَمَآ أَنتَ عَلَيْهِم بِجَبَّارٍۢ ۖ فَذَكِّرْ بِٱلْقُرْءَانِ مَن يَخَافُ وَعِيدِ', 'نحن أعلم بما يقولون  وما أنت عليهم بجبار  فذكر بالقرءان من يخاف وعيد', NULL, 520, 'local:hafs-text.json'),
  ('hafs-51-1', 'hafs', 51, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ وَٱلذَّٰرِيَٰتِ ذَرْوًۭا', 'بسم الله الرحمن الرحيم والذريت ذروا', NULL, 520, 'local:hafs-text.json'),
  ('hafs-51-2', 'hafs', 51, 2, 'فَٱلْحَٰمِلَٰتِ وِقْرًۭا', 'فالحملت وقرا', NULL, 520, 'local:hafs-text.json'),
  ('hafs-51-3', 'hafs', 51, 3, 'فَٱلْجَٰرِيَٰتِ يُسْرًۭا', 'فالجريت يسرا', NULL, 520, 'local:hafs-text.json'),
  ('hafs-51-4', 'hafs', 51, 4, 'فَٱلْمُقَسِّمَٰتِ أَمْرًا', 'فالمقسمت أمرا', NULL, 520, 'local:hafs-text.json'),
  ('hafs-51-5', 'hafs', 51, 5, 'إِنَّمَا تُوعَدُونَ لَصَادِقٌۭ', 'إنما توعدون لصادق', NULL, 520, 'local:hafs-text.json'),
  ('hafs-51-6', 'hafs', 51, 6, 'وَإِنَّ ٱلدِّينَ لَوَٰقِعٌۭ', 'وإن الدين لوقع', NULL, 520, 'local:hafs-text.json'),
  ('hafs-51-7', 'hafs', 51, 7, 'وَٱلسَّمَآءِ ذَاتِ ٱلْحُبُكِ', 'والسماء ذات الحبك', NULL, 521, 'local:hafs-text.json'),
  ('hafs-51-8', 'hafs', 51, 8, 'إِنَّكُمْ لَفِى قَوْلٍۢ مُّخْتَلِفٍۢ', 'إنكم لفى قول مختلف', NULL, 521, 'local:hafs-text.json'),
  ('hafs-51-9', 'hafs', 51, 9, 'يُؤْفَكُ عَنْهُ مَنْ أُفِكَ', 'يؤفك عنه من أفك', NULL, 521, 'local:hafs-text.json'),
  ('hafs-51-10', 'hafs', 51, 10, 'قُتِلَ ٱلْخَرَّٰصُونَ', 'قتل الخرصون', NULL, 521, 'local:hafs-text.json'),
  ('hafs-51-11', 'hafs', 51, 11, 'ٱلَّذِينَ هُمْ فِى غَمْرَةٍۢ سَاهُونَ', 'الذين هم فى غمرة ساهون', NULL, 521, 'local:hafs-text.json'),
  ('hafs-51-12', 'hafs', 51, 12, 'يَسْـَٔلُونَ أَيَّانَ يَوْمُ ٱلدِّينِ', 'يسلون أيان يوم الدين', NULL, 521, 'local:hafs-text.json'),
  ('hafs-51-13', 'hafs', 51, 13, 'يَوْمَ هُمْ عَلَى ٱلنَّارِ يُفْتَنُونَ', 'يوم هم على النار يفتنون', NULL, 521, 'local:hafs-text.json'),
  ('hafs-51-14', 'hafs', 51, 14, 'ذُوقُوا۟ فِتْنَتَكُمْ هَٰذَا ٱلَّذِى كُنتُم بِهِۦ تَسْتَعْجِلُونَ', 'ذوقوا فتنتكم هذا الذى كنتم به تستعجلون', NULL, 521, 'local:hafs-text.json'),
  ('hafs-51-15', 'hafs', 51, 15, 'إِنَّ ٱلْمُتَّقِينَ فِى جَنَّٰتٍۢ وَعُيُونٍ', 'إن المتقين فى جنت وعيون', NULL, 521, 'local:hafs-text.json'),
  ('hafs-51-16', 'hafs', 51, 16, 'ءَاخِذِينَ مَآ ءَاتَىٰهُمْ رَبُّهُمْ ۚ إِنَّهُمْ كَانُوا۟ قَبْلَ ذَٰلِكَ مُحْسِنِينَ', 'ءاخذين ما ءاتىهم ربهم  إنهم كانوا قبل ذلك محسنين', NULL, 521, 'local:hafs-text.json'),
  ('hafs-51-17', 'hafs', 51, 17, 'كَانُوا۟ قَلِيلًۭا مِّنَ ٱلَّيْلِ مَا يَهْجَعُونَ', 'كانوا قليلا من اليل ما يهجعون', NULL, 521, 'local:hafs-text.json'),
  ('hafs-51-18', 'hafs', 51, 18, 'وَبِٱلْأَسْحَارِ هُمْ يَسْتَغْفِرُونَ', 'وبالأسحار هم يستغفرون', NULL, 521, 'local:hafs-text.json'),
  ('hafs-51-19', 'hafs', 51, 19, 'وَفِىٓ أَمْوَٰلِهِمْ حَقٌّۭ لِّلسَّآئِلِ وَٱلْمَحْرُومِ', 'وفى أمولهم حق للسائل والمحروم', NULL, 521, 'local:hafs-text.json'),
  ('hafs-51-20', 'hafs', 51, 20, 'وَفِى ٱلْأَرْضِ ءَايَٰتٌۭ لِّلْمُوقِنِينَ', 'وفى الأرض ءايت للموقنين', NULL, 521, 'local:hafs-text.json'),
  ('hafs-51-21', 'hafs', 51, 21, 'وَفِىٓ أَنفُسِكُمْ ۚ أَفَلَا تُبْصِرُونَ', 'وفى أنفسكم  أفلا تبصرون', NULL, 521, 'local:hafs-text.json'),
  ('hafs-51-22', 'hafs', 51, 22, 'وَفِى ٱلسَّمَآءِ رِزْقُكُمْ وَمَا تُوعَدُونَ', 'وفى السماء رزقكم وما توعدون', NULL, 521, 'local:hafs-text.json'),
  ('hafs-51-23', 'hafs', 51, 23, 'فَوَرَبِّ ٱلسَّمَآءِ وَٱلْأَرْضِ إِنَّهُۥ لَحَقٌّۭ مِّثْلَ مَآ أَنَّكُمْ تَنطِقُونَ', 'فورب السماء والأرض إنه لحق مثل ما أنكم تنطقون', NULL, 521, 'local:hafs-text.json'),
  ('hafs-51-24', 'hafs', 51, 24, 'هَلْ أَتَىٰكَ حَدِيثُ ضَيْفِ إِبْرَٰهِيمَ ٱلْمُكْرَمِينَ', 'هل أتىك حديث ضيف إبرهيم المكرمين', NULL, 521, 'local:hafs-text.json'),
  ('hafs-51-25', 'hafs', 51, 25, 'إِذْ دَخَلُوا۟ عَلَيْهِ فَقَالُوا۟ سَلَٰمًۭا ۖ قَالَ سَلَٰمٌۭ قَوْمٌۭ مُّنكَرُونَ', 'إذ دخلوا عليه فقالوا سلما  قال سلم قوم منكرون', NULL, 521, 'local:hafs-text.json'),
  ('hafs-51-26', 'hafs', 51, 26, 'فَرَاغَ إِلَىٰٓ أَهْلِهِۦ فَجَآءَ بِعِجْلٍۢ سَمِينٍۢ', 'فراغ إلى أهله فجاء بعجل سمين', NULL, 521, 'local:hafs-text.json'),
  ('hafs-51-27', 'hafs', 51, 27, 'فَقَرَّبَهُۥٓ إِلَيْهِمْ قَالَ أَلَا تَأْكُلُونَ', 'فقربه إليهم قال ألا تأكلون', NULL, 521, 'local:hafs-text.json'),
  ('hafs-51-28', 'hafs', 51, 28, 'فَأَوْجَسَ مِنْهُمْ خِيفَةًۭ ۖ قَالُوا۟ لَا تَخَفْ ۖ وَبَشَّرُوهُ بِغُلَٰمٍ عَلِيمٍۢ', 'فأوجس منهم خيفة  قالوا لا تخف  وبشروه بغلم عليم', NULL, 521, 'local:hafs-text.json'),
  ('hafs-51-29', 'hafs', 51, 29, 'فَأَقْبَلَتِ ٱمْرَأَتُهُۥ فِى صَرَّةٍۢ فَصَكَّتْ وَجْهَهَا وَقَالَتْ عَجُوزٌ عَقِيمٌۭ', 'فأقبلت امرأته فى صرة فصكت وجهها وقالت عجوز عقيم', NULL, 521, 'local:hafs-text.json'),
  ('hafs-51-30', 'hafs', 51, 30, 'قَالُوا۟ كَذَٰلِكِ قَالَ رَبُّكِ ۖ إِنَّهُۥ هُوَ ٱلْحَكِيمُ ٱلْعَلِيمُ', 'قالوا كذلك قال ربك  إنه هو الحكيم العليم', NULL, 521, 'local:hafs-text.json'),
  ('hafs-51-31', 'hafs', 51, 31, '۞ قَالَ فَمَا خَطْبُكُمْ أَيُّهَا ٱلْمُرْسَلُونَ', 'قال فما خطبكم أيها المرسلون', NULL, 522, 'local:hafs-text.json'),
  ('hafs-51-32', 'hafs', 51, 32, 'قَالُوٓا۟ إِنَّآ أُرْسِلْنَآ إِلَىٰ قَوْمٍۢ مُّجْرِمِينَ', 'قالوا إنا أرسلنا إلى قوم مجرمين', NULL, 522, 'local:hafs-text.json'),
  ('hafs-51-33', 'hafs', 51, 33, 'لِنُرْسِلَ عَلَيْهِمْ حِجَارَةًۭ مِّن طِينٍۢ', 'لنرسل عليهم حجارة من طين', NULL, 522, 'local:hafs-text.json'),
  ('hafs-51-34', 'hafs', 51, 34, 'مُّسَوَّمَةً عِندَ رَبِّكَ لِلْمُسْرِفِينَ', 'مسومة عند ربك للمسرفين', NULL, 522, 'local:hafs-text.json'),
  ('hafs-51-35', 'hafs', 51, 35, 'فَأَخْرَجْنَا مَن كَانَ فِيهَا مِنَ ٱلْمُؤْمِنِينَ', 'فأخرجنا من كان فيها من المؤمنين', NULL, 522, 'local:hafs-text.json'),
  ('hafs-51-36', 'hafs', 51, 36, 'فَمَا وَجَدْنَا فِيهَا غَيْرَ بَيْتٍۢ مِّنَ ٱلْمُسْلِمِينَ', 'فما وجدنا فيها غير بيت من المسلمين', NULL, 522, 'local:hafs-text.json'),
  ('hafs-51-37', 'hafs', 51, 37, 'وَتَرَكْنَا فِيهَآ ءَايَةًۭ لِّلَّذِينَ يَخَافُونَ ٱلْعَذَابَ ٱلْأَلِيمَ', 'وتركنا فيها ءاية للذين يخافون العذاب الأليم', NULL, 522, 'local:hafs-text.json'),
  ('hafs-51-38', 'hafs', 51, 38, 'وَفِى مُوسَىٰٓ إِذْ أَرْسَلْنَٰهُ إِلَىٰ فِرْعَوْنَ بِسُلْطَٰنٍۢ مُّبِينٍۢ', 'وفى موسى إذ أرسلنه إلى فرعون بسلطن مبين', NULL, 522, 'local:hafs-text.json'),
  ('hafs-51-39', 'hafs', 51, 39, 'فَتَوَلَّىٰ بِرُكْنِهِۦ وَقَالَ سَٰحِرٌ أَوْ مَجْنُونٌۭ', 'فتولى بركنه وقال سحر أو مجنون', NULL, 522, 'local:hafs-text.json'),
  ('hafs-51-40', 'hafs', 51, 40, 'فَأَخَذْنَٰهُ وَجُنُودَهُۥ فَنَبَذْنَٰهُمْ فِى ٱلْيَمِّ وَهُوَ مُلِيمٌۭ', 'فأخذنه وجنوده فنبذنهم فى اليم وهو مليم', NULL, 522, 'local:hafs-text.json'),
  ('hafs-51-41', 'hafs', 51, 41, 'وَفِى عَادٍ إِذْ أَرْسَلْنَا عَلَيْهِمُ ٱلرِّيحَ ٱلْعَقِيمَ', 'وفى عاد إذ أرسلنا عليهم الريح العقيم', NULL, 522, 'local:hafs-text.json'),
  ('hafs-51-42', 'hafs', 51, 42, 'مَا تَذَرُ مِن شَىْءٍ أَتَتْ عَلَيْهِ إِلَّا جَعَلَتْهُ كَٱلرَّمِيمِ', 'ما تذر من شىء أتت عليه إلا جعلته كالرميم', NULL, 522, 'local:hafs-text.json'),
  ('hafs-51-43', 'hafs', 51, 43, 'وَفِى ثَمُودَ إِذْ قِيلَ لَهُمْ تَمَتَّعُوا۟ حَتَّىٰ حِينٍۢ', 'وفى ثمود إذ قيل لهم تمتعوا حتى حين', NULL, 522, 'local:hafs-text.json'),
  ('hafs-51-44', 'hafs', 51, 44, 'فَعَتَوْا۟ عَنْ أَمْرِ رَبِّهِمْ فَأَخَذَتْهُمُ ٱلصَّٰعِقَةُ وَهُمْ يَنظُرُونَ', 'فعتوا عن أمر ربهم فأخذتهم الصعقة وهم ينظرون', NULL, 522, 'local:hafs-text.json'),
  ('hafs-51-45', 'hafs', 51, 45, 'فَمَا ٱسْتَطَٰعُوا۟ مِن قِيَامٍۢ وَمَا كَانُوا۟ مُنتَصِرِينَ', 'فما استطعوا من قيام وما كانوا منتصرين', NULL, 522, 'local:hafs-text.json'),
  ('hafs-51-46', 'hafs', 51, 46, 'وَقَوْمَ نُوحٍۢ مِّن قَبْلُ ۖ إِنَّهُمْ كَانُوا۟ قَوْمًۭا فَٰسِقِينَ', 'وقوم نوح من قبل  إنهم كانوا قوما فسقين', NULL, 522, 'local:hafs-text.json'),
  ('hafs-51-47', 'hafs', 51, 47, 'وَٱلسَّمَآءَ بَنَيْنَٰهَا بِأَيْي۟دٍۢ وَإِنَّا لَمُوسِعُونَ', 'والسماء بنينها بأييد وإنا لموسعون', NULL, 522, 'local:hafs-text.json'),
  ('hafs-51-48', 'hafs', 51, 48, 'وَٱلْأَرْضَ فَرَشْنَٰهَا فَنِعْمَ ٱلْمَٰهِدُونَ', 'والأرض فرشنها فنعم المهدون', NULL, 522, 'local:hafs-text.json'),
  ('hafs-51-49', 'hafs', 51, 49, 'وَمِن كُلِّ شَىْءٍ خَلَقْنَا زَوْجَيْنِ لَعَلَّكُمْ تَذَكَّرُونَ', 'ومن كل شىء خلقنا زوجين لعلكم تذكرون', NULL, 522, 'local:hafs-text.json'),
  ('hafs-51-50', 'hafs', 51, 50, 'فَفِرُّوٓا۟ إِلَى ٱللَّهِ ۖ إِنِّى لَكُم مِّنْهُ نَذِيرٌۭ مُّبِينٌۭ', 'ففروا إلى الله  إنى لكم منه نذير مبين', NULL, 522, 'local:hafs-text.json'),
  ('hafs-51-51', 'hafs', 51, 51, 'وَلَا تَجْعَلُوا۟ مَعَ ٱللَّهِ إِلَٰهًا ءَاخَرَ ۖ إِنِّى لَكُم مِّنْهُ نَذِيرٌۭ مُّبِينٌۭ', 'ولا تجعلوا مع الله إلها ءاخر  إنى لكم منه نذير مبين', NULL, 522, 'local:hafs-text.json'),
  ('hafs-51-52', 'hafs', 51, 52, 'كَذَٰلِكَ مَآ أَتَى ٱلَّذِينَ مِن قَبْلِهِم مِّن رَّسُولٍ إِلَّا قَالُوا۟ سَاحِرٌ أَوْ مَجْنُونٌ', 'كذلك ما أتى الذين من قبلهم من رسول إلا قالوا ساحر أو مجنون', NULL, 523, 'local:hafs-text.json'),
  ('hafs-51-53', 'hafs', 51, 53, 'أَتَوَاصَوْا۟ بِهِۦ ۚ بَلْ هُمْ قَوْمٌۭ طَاغُونَ', 'أتواصوا به  بل هم قوم طاغون', NULL, 523, 'local:hafs-text.json'),
  ('hafs-51-54', 'hafs', 51, 54, 'فَتَوَلَّ عَنْهُمْ فَمَآ أَنتَ بِمَلُومٍۢ', 'فتول عنهم فما أنت بملوم', NULL, 523, 'local:hafs-text.json'),
  ('hafs-51-55', 'hafs', 51, 55, 'وَذَكِّرْ فَإِنَّ ٱلذِّكْرَىٰ تَنفَعُ ٱلْمُؤْمِنِينَ', 'وذكر فإن الذكرى تنفع المؤمنين', NULL, 523, 'local:hafs-text.json'),
  ('hafs-51-56', 'hafs', 51, 56, 'وَمَا خَلَقْتُ ٱلْجِنَّ وَٱلْإِنسَ إِلَّا لِيَعْبُدُونِ', 'وما خلقت الجن والإنس إلا ليعبدون', NULL, 523, 'local:hafs-text.json'),
  ('hafs-51-57', 'hafs', 51, 57, 'مَآ أُرِيدُ مِنْهُم مِّن رِّزْقٍۢ وَمَآ أُرِيدُ أَن يُطْعِمُونِ', 'ما أريد منهم من رزق وما أريد أن يطعمون', NULL, 523, 'local:hafs-text.json'),
  ('hafs-51-58', 'hafs', 51, 58, 'إِنَّ ٱللَّهَ هُوَ ٱلرَّزَّاقُ ذُو ٱلْقُوَّةِ ٱلْمَتِينُ', 'إن الله هو الرزاق ذو القوة المتين', NULL, 523, 'local:hafs-text.json'),
  ('hafs-51-59', 'hafs', 51, 59, 'فَإِنَّ لِلَّذِينَ ظَلَمُوا۟ ذَنُوبًۭا مِّثْلَ ذَنُوبِ أَصْحَٰبِهِمْ فَلَا يَسْتَعْجِلُونِ', 'فإن للذين ظلموا ذنوبا مثل ذنوب أصحبهم فلا يستعجلون', NULL, 523, 'local:hafs-text.json'),
  ('hafs-51-60', 'hafs', 51, 60, 'فَوَيْلٌۭ لِّلَّذِينَ كَفَرُوا۟ مِن يَوْمِهِمُ ٱلَّذِى يُوعَدُونَ', 'فويل للذين كفروا من يومهم الذى يوعدون', NULL, 523, 'local:hafs-text.json'),
  ('hafs-52-1', 'hafs', 52, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ وَٱلطُّورِ', 'بسم الله الرحمن الرحيم والطور', NULL, 523, 'local:hafs-text.json'),
  ('hafs-52-2', 'hafs', 52, 2, 'وَكِتَٰبٍۢ مَّسْطُورٍۢ', 'وكتب مسطور', NULL, 523, 'local:hafs-text.json'),
  ('hafs-52-3', 'hafs', 52, 3, 'فِى رَقٍّۢ مَّنشُورٍۢ', 'فى رق منشور', NULL, 523, 'local:hafs-text.json'),
  ('hafs-52-4', 'hafs', 52, 4, 'وَٱلْبَيْتِ ٱلْمَعْمُورِ', 'والبيت المعمور', NULL, 523, 'local:hafs-text.json'),
  ('hafs-52-5', 'hafs', 52, 5, 'وَٱلسَّقْفِ ٱلْمَرْفُوعِ', 'والسقف المرفوع', NULL, 523, 'local:hafs-text.json'),
  ('hafs-52-6', 'hafs', 52, 6, 'وَٱلْبَحْرِ ٱلْمَسْجُورِ', 'والبحر المسجور', NULL, 523, 'local:hafs-text.json'),
  ('hafs-52-7', 'hafs', 52, 7, 'إِنَّ عَذَابَ رَبِّكَ لَوَٰقِعٌۭ', 'إن عذاب ربك لوقع', NULL, 523, 'local:hafs-text.json'),
  ('hafs-52-8', 'hafs', 52, 8, 'مَّا لَهُۥ مِن دَافِعٍۢ', 'ما له من دافع', NULL, 523, 'local:hafs-text.json'),
  ('hafs-52-9', 'hafs', 52, 9, 'يَوْمَ تَمُورُ ٱلسَّمَآءُ مَوْرًۭا', 'يوم تمور السماء مورا', NULL, 523, 'local:hafs-text.json'),
  ('hafs-52-10', 'hafs', 52, 10, 'وَتَسِيرُ ٱلْجِبَالُ سَيْرًۭا', 'وتسير الجبال سيرا', NULL, 523, 'local:hafs-text.json'),
  ('hafs-52-11', 'hafs', 52, 11, 'فَوَيْلٌۭ يَوْمَئِذٍۢ لِّلْمُكَذِّبِينَ', 'فويل يومئذ للمكذبين', NULL, 523, 'local:hafs-text.json'),
  ('hafs-52-12', 'hafs', 52, 12, 'ٱلَّذِينَ هُمْ فِى خَوْضٍۢ يَلْعَبُونَ', 'الذين هم فى خوض يلعبون', NULL, 523, 'local:hafs-text.json'),
  ('hafs-52-13', 'hafs', 52, 13, 'يَوْمَ يُدَعُّونَ إِلَىٰ نَارِ جَهَنَّمَ دَعًّا', 'يوم يدعون إلى نار جهنم دعا', NULL, 523, 'local:hafs-text.json'),
  ('hafs-52-14', 'hafs', 52, 14, 'هَٰذِهِ ٱلنَّارُ ٱلَّتِى كُنتُم بِهَا تُكَذِّبُونَ', 'هذه النار التى كنتم بها تكذبون', NULL, 523, 'local:hafs-text.json'),
  ('hafs-52-15', 'hafs', 52, 15, 'أَفَسِحْرٌ هَٰذَآ أَمْ أَنتُمْ لَا تُبْصِرُونَ', 'أفسحر هذا أم أنتم لا تبصرون', NULL, 524, 'local:hafs-text.json'),
  ('hafs-52-16', 'hafs', 52, 16, 'ٱصْلَوْهَا فَٱصْبِرُوٓا۟ أَوْ لَا تَصْبِرُوا۟ سَوَآءٌ عَلَيْكُمْ ۖ إِنَّمَا تُجْزَوْنَ مَا كُنتُمْ تَعْمَلُونَ', 'اصلوها فاصبروا أو لا تصبروا سواء عليكم  إنما تجزون ما كنتم تعملون', NULL, 524, 'local:hafs-text.json'),
  ('hafs-52-17', 'hafs', 52, 17, 'إِنَّ ٱلْمُتَّقِينَ فِى جَنَّٰتٍۢ وَنَعِيمٍۢ', 'إن المتقين فى جنت ونعيم', NULL, 524, 'local:hafs-text.json'),
  ('hafs-52-18', 'hafs', 52, 18, 'فَٰكِهِينَ بِمَآ ءَاتَىٰهُمْ رَبُّهُمْ وَوَقَىٰهُمْ رَبُّهُمْ عَذَابَ ٱلْجَحِيمِ', 'فكهين بما ءاتىهم ربهم ووقىهم ربهم عذاب الجحيم', NULL, 524, 'local:hafs-text.json'),
  ('hafs-52-19', 'hafs', 52, 19, 'كُلُوا۟ وَٱشْرَبُوا۟ هَنِيٓـًٔۢا بِمَا كُنتُمْ تَعْمَلُونَ', 'كلوا واشربوا هنيا بما كنتم تعملون', NULL, 524, 'local:hafs-text.json'),
  ('hafs-52-20', 'hafs', 52, 20, 'مُتَّكِـِٔينَ عَلَىٰ سُرُرٍۢ مَّصْفُوفَةٍۢ ۖ وَزَوَّجْنَٰهُم بِحُورٍ عِينٍۢ', 'متكين على سرر مصفوفة  وزوجنهم بحور عين', NULL, 524, 'local:hafs-text.json'),
  ('hafs-52-21', 'hafs', 52, 21, 'وَٱلَّذِينَ ءَامَنُوا۟ وَٱتَّبَعَتْهُمْ ذُرِّيَّتُهُم بِإِيمَٰنٍ أَلْحَقْنَا بِهِمْ ذُرِّيَّتَهُمْ وَمَآ أَلَتْنَٰهُم مِّنْ عَمَلِهِم مِّن شَىْءٍۢ ۚ كُلُّ ٱمْرِئٍۭ بِمَا كَسَبَ رَهِينٌۭ', 'والذين ءامنوا واتبعتهم ذريتهم بإيمن ألحقنا بهم ذريتهم وما ألتنهم من عملهم من شىء  كل امرئ بما كسب رهين', NULL, 524, 'local:hafs-text.json'),
  ('hafs-52-22', 'hafs', 52, 22, 'وَأَمْدَدْنَٰهُم بِفَٰكِهَةٍۢ وَلَحْمٍۢ مِّمَّا يَشْتَهُونَ', 'وأمددنهم بفكهة ولحم مما يشتهون', NULL, 524, 'local:hafs-text.json'),
  ('hafs-52-23', 'hafs', 52, 23, 'يَتَنَٰزَعُونَ فِيهَا كَأْسًۭا لَّا لَغْوٌۭ فِيهَا وَلَا تَأْثِيمٌۭ', 'يتنزعون فيها كأسا لا لغو فيها ولا تأثيم', NULL, 524, 'local:hafs-text.json'),
  ('hafs-52-24', 'hafs', 52, 24, '۞ وَيَطُوفُ عَلَيْهِمْ غِلْمَانٌۭ لَّهُمْ كَأَنَّهُمْ لُؤْلُؤٌۭ مَّكْنُونٌۭ', 'ويطوف عليهم غلمان لهم كأنهم لؤلؤ مكنون', NULL, 524, 'local:hafs-text.json'),
  ('hafs-52-25', 'hafs', 52, 25, 'وَأَقْبَلَ بَعْضُهُمْ عَلَىٰ بَعْضٍۢ يَتَسَآءَلُونَ', 'وأقبل بعضهم على بعض يتساءلون', NULL, 524, 'local:hafs-text.json'),
  ('hafs-52-26', 'hafs', 52, 26, 'قَالُوٓا۟ إِنَّا كُنَّا قَبْلُ فِىٓ أَهْلِنَا مُشْفِقِينَ', 'قالوا إنا كنا قبل فى أهلنا مشفقين', NULL, 524, 'local:hafs-text.json'),
  ('hafs-52-27', 'hafs', 52, 27, 'فَمَنَّ ٱللَّهُ عَلَيْنَا وَوَقَىٰنَا عَذَابَ ٱلسَّمُومِ', 'فمن الله علينا ووقىنا عذاب السموم', NULL, 524, 'local:hafs-text.json'),
  ('hafs-52-28', 'hafs', 52, 28, 'إِنَّا كُنَّا مِن قَبْلُ نَدْعُوهُ ۖ إِنَّهُۥ هُوَ ٱلْبَرُّ ٱلرَّحِيمُ', 'إنا كنا من قبل ندعوه  إنه هو البر الرحيم', NULL, 524, 'local:hafs-text.json'),
  ('hafs-52-29', 'hafs', 52, 29, 'فَذَكِّرْ فَمَآ أَنتَ بِنِعْمَتِ رَبِّكَ بِكَاهِنٍۢ وَلَا مَجْنُونٍ', 'فذكر فما أنت بنعمت ربك بكاهن ولا مجنون', NULL, 524, 'local:hafs-text.json'),
  ('hafs-52-30', 'hafs', 52, 30, 'أَمْ يَقُولُونَ شَاعِرٌۭ نَّتَرَبَّصُ بِهِۦ رَيْبَ ٱلْمَنُونِ', 'أم يقولون شاعر نتربص به ريب المنون', NULL, 524, 'local:hafs-text.json'),
  ('hafs-52-31', 'hafs', 52, 31, 'قُلْ تَرَبَّصُوا۟ فَإِنِّى مَعَكُم مِّنَ ٱلْمُتَرَبِّصِينَ', 'قل تربصوا فإنى معكم من المتربصين', NULL, 524, 'local:hafs-text.json'),
  ('hafs-52-32', 'hafs', 52, 32, 'أَمْ تَأْمُرُهُمْ أَحْلَٰمُهُم بِهَٰذَآ ۚ أَمْ هُمْ قَوْمٌۭ طَاغُونَ', 'أم تأمرهم أحلمهم بهذا  أم هم قوم طاغون', NULL, 525, 'local:hafs-text.json'),
  ('hafs-52-33', 'hafs', 52, 33, 'أَمْ يَقُولُونَ تَقَوَّلَهُۥ ۚ بَل لَّا يُؤْمِنُونَ', 'أم يقولون تقوله  بل لا يؤمنون', NULL, 525, 'local:hafs-text.json'),
  ('hafs-52-34', 'hafs', 52, 34, 'فَلْيَأْتُوا۟ بِحَدِيثٍۢ مِّثْلِهِۦٓ إِن كَانُوا۟ صَٰدِقِينَ', 'فليأتوا بحديث مثله إن كانوا صدقين', NULL, 525, 'local:hafs-text.json'),
  ('hafs-52-35', 'hafs', 52, 35, 'أَمْ خُلِقُوا۟ مِنْ غَيْرِ شَىْءٍ أَمْ هُمُ ٱلْخَٰلِقُونَ', 'أم خلقوا من غير شىء أم هم الخلقون', NULL, 525, 'local:hafs-text.json'),
  ('hafs-52-36', 'hafs', 52, 36, 'أَمْ خَلَقُوا۟ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ ۚ بَل لَّا يُوقِنُونَ', 'أم خلقوا السموت والأرض  بل لا يوقنون', NULL, 525, 'local:hafs-text.json'),
  ('hafs-52-37', 'hafs', 52, 37, 'أَمْ عِندَهُمْ خَزَآئِنُ رَبِّكَ أَمْ هُمُ ٱلْمُصَۣيْطِرُونَ', 'أم عندهم خزائن ربك أم هم المصيطرون', NULL, 525, 'local:hafs-text.json'),
  ('hafs-52-38', 'hafs', 52, 38, 'أَمْ لَهُمْ سُلَّمٌۭ يَسْتَمِعُونَ فِيهِ ۖ فَلْيَأْتِ مُسْتَمِعُهُم بِسُلْطَٰنٍۢ مُّبِينٍ', 'أم لهم سلم يستمعون فيه  فليأت مستمعهم بسلطن مبين', NULL, 525, 'local:hafs-text.json'),
  ('hafs-52-39', 'hafs', 52, 39, 'أَمْ لَهُ ٱلْبَنَٰتُ وَلَكُمُ ٱلْبَنُونَ', 'أم له البنت ولكم البنون', NULL, 525, 'local:hafs-text.json'),
  ('hafs-52-40', 'hafs', 52, 40, 'أَمْ تَسْـَٔلُهُمْ أَجْرًۭا فَهُم مِّن مَّغْرَمٍۢ مُّثْقَلُونَ', 'أم تسلهم أجرا فهم من مغرم مثقلون', NULL, 525, 'local:hafs-text.json'),
  ('hafs-52-41', 'hafs', 52, 41, 'أَمْ عِندَهُمُ ٱلْغَيْبُ فَهُمْ يَكْتُبُونَ', 'أم عندهم الغيب فهم يكتبون', NULL, 525, 'local:hafs-text.json'),
  ('hafs-52-42', 'hafs', 52, 42, 'أَمْ يُرِيدُونَ كَيْدًۭا ۖ فَٱلَّذِينَ كَفَرُوا۟ هُمُ ٱلْمَكِيدُونَ', 'أم يريدون كيدا  فالذين كفروا هم المكيدون', NULL, 525, 'local:hafs-text.json'),
  ('hafs-52-43', 'hafs', 52, 43, 'أَمْ لَهُمْ إِلَٰهٌ غَيْرُ ٱللَّهِ ۚ سُبْحَٰنَ ٱللَّهِ عَمَّا يُشْرِكُونَ', 'أم لهم إله غير الله  سبحن الله عما يشركون', NULL, 525, 'local:hafs-text.json'),
  ('hafs-52-44', 'hafs', 52, 44, 'وَإِن يَرَوْا۟ كِسْفًۭا مِّنَ ٱلسَّمَآءِ سَاقِطًۭا يَقُولُوا۟ سَحَابٌۭ مَّرْكُومٌۭ', 'وإن يروا كسفا من السماء ساقطا يقولوا سحاب مركوم', NULL, 525, 'local:hafs-text.json'),
  ('hafs-52-45', 'hafs', 52, 45, 'فَذَرْهُمْ حَتَّىٰ يُلَٰقُوا۟ يَوْمَهُمُ ٱلَّذِى فِيهِ يُصْعَقُونَ', 'فذرهم حتى يلقوا يومهم الذى فيه يصعقون', NULL, 525, 'local:hafs-text.json'),
  ('hafs-52-46', 'hafs', 52, 46, 'يَوْمَ لَا يُغْنِى عَنْهُمْ كَيْدُهُمْ شَيْـًۭٔا وَلَا هُمْ يُنصَرُونَ', 'يوم لا يغنى عنهم كيدهم شيا ولا هم ينصرون', NULL, 525, 'local:hafs-text.json'),
  ('hafs-52-47', 'hafs', 52, 47, 'وَإِنَّ لِلَّذِينَ ظَلَمُوا۟ عَذَابًۭا دُونَ ذَٰلِكَ وَلَٰكِنَّ أَكْثَرَهُمْ لَا يَعْلَمُونَ', 'وإن للذين ظلموا عذابا دون ذلك ولكن أكثرهم لا يعلمون', NULL, 525, 'local:hafs-text.json'),
  ('hafs-52-48', 'hafs', 52, 48, 'وَٱصْبِرْ لِحُكْمِ رَبِّكَ فَإِنَّكَ بِأَعْيُنِنَا ۖ وَسَبِّحْ بِحَمْدِ رَبِّكَ حِينَ تَقُومُ', 'واصبر لحكم ربك فإنك بأعيننا  وسبح بحمد ربك حين تقوم', NULL, 525, 'local:hafs-text.json'),
  ('hafs-52-49', 'hafs', 52, 49, 'وَمِنَ ٱلَّيْلِ فَسَبِّحْهُ وَإِدْبَٰرَ ٱلنُّجُومِ', 'ومن اليل فسبحه وإدبر النجوم', NULL, 525, 'local:hafs-text.json'),
  ('hafs-53-1', 'hafs', 53, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ وَٱلنَّجْمِ إِذَا هَوَىٰ', 'بسم الله الرحمن الرحيم والنجم إذا هوى', NULL, 526, 'local:hafs-text.json'),
  ('hafs-53-2', 'hafs', 53, 2, 'مَا ضَلَّ صَاحِبُكُمْ وَمَا غَوَىٰ', 'ما ضل صاحبكم وما غوى', NULL, 526, 'local:hafs-text.json'),
  ('hafs-53-3', 'hafs', 53, 3, 'وَمَا يَنطِقُ عَنِ ٱلْهَوَىٰٓ', 'وما ينطق عن الهوى', NULL, 526, 'local:hafs-text.json'),
  ('hafs-53-4', 'hafs', 53, 4, 'إِنْ هُوَ إِلَّا وَحْىٌۭ يُوحَىٰ', 'إن هو إلا وحى يوحى', NULL, 526, 'local:hafs-text.json'),
  ('hafs-53-5', 'hafs', 53, 5, 'عَلَّمَهُۥ شَدِيدُ ٱلْقُوَىٰ', 'علمه شديد القوى', NULL, 526, 'local:hafs-text.json'),
  ('hafs-53-6', 'hafs', 53, 6, 'ذُو مِرَّةٍۢ فَٱسْتَوَىٰ', 'ذو مرة فاستوى', NULL, 526, 'local:hafs-text.json'),
  ('hafs-53-7', 'hafs', 53, 7, 'وَهُوَ بِٱلْأُفُقِ ٱلْأَعْلَىٰ', 'وهو بالأفق الأعلى', NULL, 526, 'local:hafs-text.json'),
  ('hafs-53-8', 'hafs', 53, 8, 'ثُمَّ دَنَا فَتَدَلَّىٰ', 'ثم دنا فتدلى', NULL, 526, 'local:hafs-text.json'),
  ('hafs-53-9', 'hafs', 53, 9, 'فَكَانَ قَابَ قَوْسَيْنِ أَوْ أَدْنَىٰ', 'فكان قاب قوسين أو أدنى', NULL, 526, 'local:hafs-text.json'),
  ('hafs-53-10', 'hafs', 53, 10, 'فَأَوْحَىٰٓ إِلَىٰ عَبْدِهِۦ مَآ أَوْحَىٰ', 'فأوحى إلى عبده ما أوحى', NULL, 526, 'local:hafs-text.json'),
  ('hafs-53-11', 'hafs', 53, 11, 'مَا كَذَبَ ٱلْفُؤَادُ مَا رَأَىٰٓ', 'ما كذب الفؤاد ما رأى', NULL, 526, 'local:hafs-text.json'),
  ('hafs-53-12', 'hafs', 53, 12, 'أَفَتُمَٰرُونَهُۥ عَلَىٰ مَا يَرَىٰ', 'أفتمرونه على ما يرى', NULL, 526, 'local:hafs-text.json'),
  ('hafs-53-13', 'hafs', 53, 13, 'وَلَقَدْ رَءَاهُ نَزْلَةً أُخْرَىٰ', 'ولقد رءاه نزلة أخرى', NULL, 526, 'local:hafs-text.json'),
  ('hafs-53-14', 'hafs', 53, 14, 'عِندَ سِدْرَةِ ٱلْمُنتَهَىٰ', 'عند سدرة المنتهى', NULL, 526, 'local:hafs-text.json'),
  ('hafs-53-15', 'hafs', 53, 15, 'عِندَهَا جَنَّةُ ٱلْمَأْوَىٰٓ', 'عندها جنة المأوى', NULL, 526, 'local:hafs-text.json'),
  ('hafs-53-16', 'hafs', 53, 16, 'إِذْ يَغْشَى ٱلسِّدْرَةَ مَا يَغْشَىٰ', 'إذ يغشى السدرة ما يغشى', NULL, 526, 'local:hafs-text.json')
insert into public.ayahs (id, riwayah, surah_number, ayah_number, text, simple_text, juz, page, source) values
  ('hafs-53-17', 'hafs', 53, 17, 'مَا زَاغَ ٱلْبَصَرُ وَمَا طَغَىٰ', 'ما زاغ البصر وما طغى', NULL, 526, 'local:hafs-text.json'),
  ('hafs-53-18', 'hafs', 53, 18, 'لَقَدْ رَأَىٰ مِنْ ءَايَٰتِ رَبِّهِ ٱلْكُبْرَىٰٓ', 'لقد رأى من ءايت ربه الكبرى', NULL, 526, 'local:hafs-text.json'),
  ('hafs-53-19', 'hafs', 53, 19, 'أَفَرَءَيْتُمُ ٱللَّٰتَ وَٱلْعُزَّىٰ', 'أفرءيتم اللت والعزى', NULL, 526, 'local:hafs-text.json'),
  ('hafs-53-20', 'hafs', 53, 20, 'وَمَنَوٰةَ ٱلثَّالِثَةَ ٱلْأُخْرَىٰٓ', 'ومنوة الثالثة الأخرى', NULL, 526, 'local:hafs-text.json'),
  ('hafs-53-21', 'hafs', 53, 21, 'أَلَكُمُ ٱلذَّكَرُ وَلَهُ ٱلْأُنثَىٰ', 'ألكم الذكر وله الأنثى', NULL, 526, 'local:hafs-text.json'),
  ('hafs-53-22', 'hafs', 53, 22, 'تِلْكَ إِذًۭا قِسْمَةٌۭ ضِيزَىٰٓ', 'تلك إذا قسمة ضيزى', NULL, 526, 'local:hafs-text.json'),
  ('hafs-53-23', 'hafs', 53, 23, 'إِنْ هِىَ إِلَّآ أَسْمَآءٌۭ سَمَّيْتُمُوهَآ أَنتُمْ وَءَابَآؤُكُم مَّآ أَنزَلَ ٱللَّهُ بِهَا مِن سُلْطَٰنٍ ۚ إِن يَتَّبِعُونَ إِلَّا ٱلظَّنَّ وَمَا تَهْوَى ٱلْأَنفُسُ ۖ وَلَقَدْ جَآءَهُم مِّن رَّبِّهِمُ ٱلْهُدَىٰٓ', 'إن هى إلا أسماء سميتموها أنتم وءاباؤكم ما أنزل الله بها من سلطن  إن يتبعون إلا الظن وما تهوى الأنفس  ولقد جاءهم من ربهم الهدى', NULL, 526, 'local:hafs-text.json'),
  ('hafs-53-24', 'hafs', 53, 24, 'أَمْ لِلْإِنسَٰنِ مَا تَمَنَّىٰ', 'أم للإنسن ما تمنى', NULL, 526, 'local:hafs-text.json'),
  ('hafs-53-25', 'hafs', 53, 25, 'فَلِلَّهِ ٱلْءَاخِرَةُ وَٱلْأُولَىٰ', 'فلله الءاخرة والأولى', NULL, 526, 'local:hafs-text.json'),
  ('hafs-53-26', 'hafs', 53, 26, '۞ وَكَم مِّن مَّلَكٍۢ فِى ٱلسَّمَٰوَٰتِ لَا تُغْنِى شَفَٰعَتُهُمْ شَيْـًٔا إِلَّا مِنۢ بَعْدِ أَن يَأْذَنَ ٱللَّهُ لِمَن يَشَآءُ وَيَرْضَىٰٓ', 'وكم من ملك فى السموت لا تغنى شفعتهم شيا إلا من بعد أن يأذن الله لمن يشاء ويرضى', NULL, 526, 'local:hafs-text.json'),
  ('hafs-53-27', 'hafs', 53, 27, 'إِنَّ ٱلَّذِينَ لَا يُؤْمِنُونَ بِٱلْءَاخِرَةِ لَيُسَمُّونَ ٱلْمَلَٰٓئِكَةَ تَسْمِيَةَ ٱلْأُنثَىٰ', 'إن الذين لا يؤمنون بالءاخرة ليسمون الملئكة تسمية الأنثى', NULL, 527, 'local:hafs-text.json'),
  ('hafs-53-28', 'hafs', 53, 28, 'وَمَا لَهُم بِهِۦ مِنْ عِلْمٍ ۖ إِن يَتَّبِعُونَ إِلَّا ٱلظَّنَّ ۖ وَإِنَّ ٱلظَّنَّ لَا يُغْنِى مِنَ ٱلْحَقِّ شَيْـًۭٔا', 'وما لهم به من علم  إن يتبعون إلا الظن  وإن الظن لا يغنى من الحق شيا', NULL, 527, 'local:hafs-text.json'),
  ('hafs-53-29', 'hafs', 53, 29, 'فَأَعْرِضْ عَن مَّن تَوَلَّىٰ عَن ذِكْرِنَا وَلَمْ يُرِدْ إِلَّا ٱلْحَيَوٰةَ ٱلدُّنْيَا', 'فأعرض عن من تولى عن ذكرنا ولم يرد إلا الحيوة الدنيا', NULL, 527, 'local:hafs-text.json'),
  ('hafs-53-30', 'hafs', 53, 30, 'ذَٰلِكَ مَبْلَغُهُم مِّنَ ٱلْعِلْمِ ۚ إِنَّ رَبَّكَ هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِۦ وَهُوَ أَعْلَمُ بِمَنِ ٱهْتَدَىٰ', 'ذلك مبلغهم من العلم  إن ربك هو أعلم بمن ضل عن سبيله وهو أعلم بمن اهتدى', NULL, 527, 'local:hafs-text.json'),
  ('hafs-53-31', 'hafs', 53, 31, 'وَلِلَّهِ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ لِيَجْزِىَ ٱلَّذِينَ أَسَٰٓـُٔوا۟ بِمَا عَمِلُوا۟ وَيَجْزِىَ ٱلَّذِينَ أَحْسَنُوا۟ بِٱلْحُسْنَى', 'ولله ما فى السموت وما فى الأرض ليجزى الذين أسوا بما عملوا ويجزى الذين أحسنوا بالحسنى', NULL, 527, 'local:hafs-text.json'),
  ('hafs-53-32', 'hafs', 53, 32, 'ٱلَّذِينَ يَجْتَنِبُونَ كَبَٰٓئِرَ ٱلْإِثْمِ وَٱلْفَوَٰحِشَ إِلَّا ٱللَّمَمَ ۚ إِنَّ رَبَّكَ وَٰسِعُ ٱلْمَغْفِرَةِ ۚ هُوَ أَعْلَمُ بِكُمْ إِذْ أَنشَأَكُم مِّنَ ٱلْأَرْضِ وَإِذْ أَنتُمْ أَجِنَّةٌۭ فِى بُطُونِ أُمَّهَٰتِكُمْ ۖ فَلَا تُزَكُّوٓا۟ أَنفُسَكُمْ ۖ هُوَ أَعْلَمُ بِمَنِ ٱتَّقَىٰٓ', 'الذين يجتنبون كبئر الإثم والفوحش إلا اللمم  إن ربك وسع المغفرة  هو أعلم بكم إذ أنشأكم من الأرض وإذ أنتم أجنة فى بطون أمهتكم  فلا تزكوا أنفسكم  هو أعلم بمن اتقى', NULL, 527, 'local:hafs-text.json'),
  ('hafs-53-33', 'hafs', 53, 33, 'أَفَرَءَيْتَ ٱلَّذِى تَوَلَّىٰ', 'أفرءيت الذى تولى', NULL, 527, 'local:hafs-text.json'),
  ('hafs-53-34', 'hafs', 53, 34, 'وَأَعْطَىٰ قَلِيلًۭا وَأَكْدَىٰٓ', 'وأعطى قليلا وأكدى', NULL, 527, 'local:hafs-text.json'),
  ('hafs-53-35', 'hafs', 53, 35, 'أَعِندَهُۥ عِلْمُ ٱلْغَيْبِ فَهُوَ يَرَىٰٓ', 'أعنده علم الغيب فهو يرى', NULL, 527, 'local:hafs-text.json'),
  ('hafs-53-36', 'hafs', 53, 36, 'أَمْ لَمْ يُنَبَّأْ بِمَا فِى صُحُفِ مُوسَىٰ', 'أم لم ينبأ بما فى صحف موسى', NULL, 527, 'local:hafs-text.json'),
  ('hafs-53-37', 'hafs', 53, 37, 'وَإِبْرَٰهِيمَ ٱلَّذِى وَفَّىٰٓ', 'وإبرهيم الذى وفى', NULL, 527, 'local:hafs-text.json'),
  ('hafs-53-38', 'hafs', 53, 38, 'أَلَّا تَزِرُ وَازِرَةٌۭ وِزْرَ أُخْرَىٰ', 'ألا تزر وازرة وزر أخرى', NULL, 527, 'local:hafs-text.json'),
  ('hafs-53-39', 'hafs', 53, 39, 'وَأَن لَّيْسَ لِلْإِنسَٰنِ إِلَّا مَا سَعَىٰ', 'وأن ليس للإنسن إلا ما سعى', NULL, 527, 'local:hafs-text.json'),
  ('hafs-53-40', 'hafs', 53, 40, 'وَأَنَّ سَعْيَهُۥ سَوْفَ يُرَىٰ', 'وأن سعيه سوف يرى', NULL, 527, 'local:hafs-text.json'),
  ('hafs-53-41', 'hafs', 53, 41, 'ثُمَّ يُجْزَىٰهُ ٱلْجَزَآءَ ٱلْأَوْفَىٰ', 'ثم يجزىه الجزاء الأوفى', NULL, 527, 'local:hafs-text.json'),
  ('hafs-53-42', 'hafs', 53, 42, 'وَأَنَّ إِلَىٰ رَبِّكَ ٱلْمُنتَهَىٰ', 'وأن إلى ربك المنتهى', NULL, 527, 'local:hafs-text.json'),
  ('hafs-53-43', 'hafs', 53, 43, 'وَأَنَّهُۥ هُوَ أَضْحَكَ وَأَبْكَىٰ', 'وأنه هو أضحك وأبكى', NULL, 527, 'local:hafs-text.json'),
  ('hafs-53-44', 'hafs', 53, 44, 'وَأَنَّهُۥ هُوَ أَمَاتَ وَأَحْيَا', 'وأنه هو أمات وأحيا', NULL, 527, 'local:hafs-text.json'),
  ('hafs-53-45', 'hafs', 53, 45, 'وَأَنَّهُۥ خَلَقَ ٱلزَّوْجَيْنِ ٱلذَّكَرَ وَٱلْأُنثَىٰ', 'وأنه خلق الزوجين الذكر والأنثى', NULL, 528, 'local:hafs-text.json'),
  ('hafs-53-46', 'hafs', 53, 46, 'مِن نُّطْفَةٍ إِذَا تُمْنَىٰ', 'من نطفة إذا تمنى', NULL, 528, 'local:hafs-text.json'),
  ('hafs-53-47', 'hafs', 53, 47, 'وَأَنَّ عَلَيْهِ ٱلنَّشْأَةَ ٱلْأُخْرَىٰ', 'وأن عليه النشأة الأخرى', NULL, 528, 'local:hafs-text.json'),
  ('hafs-53-48', 'hafs', 53, 48, 'وَأَنَّهُۥ هُوَ أَغْنَىٰ وَأَقْنَىٰ', 'وأنه هو أغنى وأقنى', NULL, 528, 'local:hafs-text.json'),
  ('hafs-53-49', 'hafs', 53, 49, 'وَأَنَّهُۥ هُوَ رَبُّ ٱلشِّعْرَىٰ', 'وأنه هو رب الشعرى', NULL, 528, 'local:hafs-text.json'),
  ('hafs-53-50', 'hafs', 53, 50, 'وَأَنَّهُۥٓ أَهْلَكَ عَادًا ٱلْأُولَىٰ', 'وأنه أهلك عادا الأولى', NULL, 528, 'local:hafs-text.json'),
  ('hafs-53-51', 'hafs', 53, 51, 'وَثَمُودَا۟ فَمَآ أَبْقَىٰ', 'وثمودا فما أبقى', NULL, 528, 'local:hafs-text.json'),
  ('hafs-53-52', 'hafs', 53, 52, 'وَقَوْمَ نُوحٍۢ مِّن قَبْلُ ۖ إِنَّهُمْ كَانُوا۟ هُمْ أَظْلَمَ وَأَطْغَىٰ', 'وقوم نوح من قبل  إنهم كانوا هم أظلم وأطغى', NULL, 528, 'local:hafs-text.json'),
  ('hafs-53-53', 'hafs', 53, 53, 'وَٱلْمُؤْتَفِكَةَ أَهْوَىٰ', 'والمؤتفكة أهوى', NULL, 528, 'local:hafs-text.json'),
  ('hafs-53-54', 'hafs', 53, 54, 'فَغَشَّىٰهَا مَا غَشَّىٰ', 'فغشىها ما غشى', NULL, 528, 'local:hafs-text.json'),
  ('hafs-53-55', 'hafs', 53, 55, 'فَبِأَىِّ ءَالَآءِ رَبِّكَ تَتَمَارَىٰ', 'فبأى ءالاء ربك تتمارى', NULL, 528, 'local:hafs-text.json'),
  ('hafs-53-56', 'hafs', 53, 56, 'هَٰذَا نَذِيرٌۭ مِّنَ ٱلنُّذُرِ ٱلْأُولَىٰٓ', 'هذا نذير من النذر الأولى', NULL, 528, 'local:hafs-text.json'),
  ('hafs-53-57', 'hafs', 53, 57, 'أَزِفَتِ ٱلْءَازِفَةُ', 'أزفت الءازفة', NULL, 528, 'local:hafs-text.json'),
  ('hafs-53-58', 'hafs', 53, 58, 'لَيْسَ لَهَا مِن دُونِ ٱللَّهِ كَاشِفَةٌ', 'ليس لها من دون الله كاشفة', NULL, 528, 'local:hafs-text.json'),
  ('hafs-53-59', 'hafs', 53, 59, 'أَفَمِنْ هَٰذَا ٱلْحَدِيثِ تَعْجَبُونَ', 'أفمن هذا الحديث تعجبون', NULL, 528, 'local:hafs-text.json'),
  ('hafs-53-60', 'hafs', 53, 60, 'وَتَضْحَكُونَ وَلَا تَبْكُونَ', 'وتضحكون ولا تبكون', NULL, 528, 'local:hafs-text.json'),
  ('hafs-53-61', 'hafs', 53, 61, 'وَأَنتُمْ سَٰمِدُونَ', 'وأنتم سمدون', NULL, 528, 'local:hafs-text.json'),
  ('hafs-53-62', 'hafs', 53, 62, 'فَٱسْجُدُوا۟ لِلَّهِ وَٱعْبُدُوا۟ ۩', 'فاسجدوا لله واعبدوا', NULL, 528, 'local:hafs-text.json'),
  ('hafs-54-1', 'hafs', 54, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ ٱقْتَرَبَتِ ٱلسَّاعَةُ وَٱنشَقَّ ٱلْقَمَرُ', 'بسم الله الرحمن الرحيم اقتربت الساعة وانشق القمر', NULL, 528, 'local:hafs-text.json'),
  ('hafs-54-2', 'hafs', 54, 2, 'وَإِن يَرَوْا۟ ءَايَةًۭ يُعْرِضُوا۟ وَيَقُولُوا۟ سِحْرٌۭ مُّسْتَمِرٌّۭ', 'وإن يروا ءاية يعرضوا ويقولوا سحر مستمر', NULL, 528, 'local:hafs-text.json'),
  ('hafs-54-3', 'hafs', 54, 3, 'وَكَذَّبُوا۟ وَٱتَّبَعُوٓا۟ أَهْوَآءَهُمْ ۚ وَكُلُّ أَمْرٍۢ مُّسْتَقِرٌّۭ', 'وكذبوا واتبعوا أهواءهم  وكل أمر مستقر', NULL, 528, 'local:hafs-text.json'),
  ('hafs-54-4', 'hafs', 54, 4, 'وَلَقَدْ جَآءَهُم مِّنَ ٱلْأَنۢبَآءِ مَا فِيهِ مُزْدَجَرٌ', 'ولقد جاءهم من الأنباء ما فيه مزدجر', NULL, 528, 'local:hafs-text.json'),
  ('hafs-54-5', 'hafs', 54, 5, 'حِكْمَةٌۢ بَٰلِغَةٌۭ ۖ فَمَا تُغْنِ ٱلنُّذُرُ', 'حكمة بلغة  فما تغن النذر', NULL, 528, 'local:hafs-text.json'),
  ('hafs-54-6', 'hafs', 54, 6, 'فَتَوَلَّ عَنْهُمْ ۘ يَوْمَ يَدْعُ ٱلدَّاعِ إِلَىٰ شَىْءٍۢ نُّكُرٍ', 'فتول عنهم  يوم يدع الداع إلى شىء نكر', NULL, 528, 'local:hafs-text.json'),
  ('hafs-54-7', 'hafs', 54, 7, 'خُشَّعًا أَبْصَٰرُهُمْ يَخْرُجُونَ مِنَ ٱلْأَجْدَاثِ كَأَنَّهُمْ جَرَادٌۭ مُّنتَشِرٌۭ', 'خشعا أبصرهم يخرجون من الأجداث كأنهم جراد منتشر', NULL, 529, 'local:hafs-text.json'),
  ('hafs-54-8', 'hafs', 54, 8, 'مُّهْطِعِينَ إِلَى ٱلدَّاعِ ۖ يَقُولُ ٱلْكَٰفِرُونَ هَٰذَا يَوْمٌ عَسِرٌۭ', 'مهطعين إلى الداع  يقول الكفرون هذا يوم عسر', NULL, 529, 'local:hafs-text.json'),
  ('hafs-54-9', 'hafs', 54, 9, '۞ كَذَّبَتْ قَبْلَهُمْ قَوْمُ نُوحٍۢ فَكَذَّبُوا۟ عَبْدَنَا وَقَالُوا۟ مَجْنُونٌۭ وَٱزْدُجِرَ', 'كذبت قبلهم قوم نوح فكذبوا عبدنا وقالوا مجنون وازدجر', NULL, 529, 'local:hafs-text.json'),
  ('hafs-54-10', 'hafs', 54, 10, 'فَدَعَا رَبَّهُۥٓ أَنِّى مَغْلُوبٌۭ فَٱنتَصِرْ', 'فدعا ربه أنى مغلوب فانتصر', NULL, 529, 'local:hafs-text.json'),
  ('hafs-54-11', 'hafs', 54, 11, 'فَفَتَحْنَآ أَبْوَٰبَ ٱلسَّمَآءِ بِمَآءٍۢ مُّنْهَمِرٍۢ', 'ففتحنا أبوب السماء بماء منهمر', NULL, 529, 'local:hafs-text.json'),
  ('hafs-54-12', 'hafs', 54, 12, 'وَفَجَّرْنَا ٱلْأَرْضَ عُيُونًۭا فَٱلْتَقَى ٱلْمَآءُ عَلَىٰٓ أَمْرٍۢ قَدْ قُدِرَ', 'وفجرنا الأرض عيونا فالتقى الماء على أمر قد قدر', NULL, 529, 'local:hafs-text.json'),
  ('hafs-54-13', 'hafs', 54, 13, 'وَحَمَلْنَٰهُ عَلَىٰ ذَاتِ أَلْوَٰحٍۢ وَدُسُرٍۢ', 'وحملنه على ذات ألوح ودسر', NULL, 529, 'local:hafs-text.json'),
  ('hafs-54-14', 'hafs', 54, 14, 'تَجْرِى بِأَعْيُنِنَا جَزَآءًۭ لِّمَن كَانَ كُفِرَ', 'تجرى بأعيننا جزاء لمن كان كفر', NULL, 529, 'local:hafs-text.json'),
  ('hafs-54-15', 'hafs', 54, 15, 'وَلَقَد تَّرَكْنَٰهَآ ءَايَةًۭ فَهَلْ مِن مُّدَّكِرٍۢ', 'ولقد تركنها ءاية فهل من مدكر', NULL, 529, 'local:hafs-text.json'),
  ('hafs-54-16', 'hafs', 54, 16, 'فَكَيْفَ كَانَ عَذَابِى وَنُذُرِ', 'فكيف كان عذابى ونذر', NULL, 529, 'local:hafs-text.json'),
  ('hafs-54-17', 'hafs', 54, 17, 'وَلَقَدْ يَسَّرْنَا ٱلْقُرْءَانَ لِلذِّكْرِ فَهَلْ مِن مُّدَّكِرٍۢ', 'ولقد يسرنا القرءان للذكر فهل من مدكر', NULL, 529, 'local:hafs-text.json'),
  ('hafs-54-18', 'hafs', 54, 18, 'كَذَّبَتْ عَادٌۭ فَكَيْفَ كَانَ عَذَابِى وَنُذُرِ', 'كذبت عاد فكيف كان عذابى ونذر', NULL, 529, 'local:hafs-text.json'),
  ('hafs-54-19', 'hafs', 54, 19, 'إِنَّآ أَرْسَلْنَا عَلَيْهِمْ رِيحًۭا صَرْصَرًۭا فِى يَوْمِ نَحْسٍۢ مُّسْتَمِرٍّۢ', 'إنا أرسلنا عليهم ريحا صرصرا فى يوم نحس مستمر', NULL, 529, 'local:hafs-text.json'),
  ('hafs-54-20', 'hafs', 54, 20, 'تَنزِعُ ٱلنَّاسَ كَأَنَّهُمْ أَعْجَازُ نَخْلٍۢ مُّنقَعِرٍۢ', 'تنزع الناس كأنهم أعجاز نخل منقعر', NULL, 529, 'local:hafs-text.json'),
  ('hafs-54-21', 'hafs', 54, 21, 'فَكَيْفَ كَانَ عَذَابِى وَنُذُرِ', 'فكيف كان عذابى ونذر', NULL, 529, 'local:hafs-text.json'),
  ('hafs-54-22', 'hafs', 54, 22, 'وَلَقَدْ يَسَّرْنَا ٱلْقُرْءَانَ لِلذِّكْرِ فَهَلْ مِن مُّدَّكِرٍۢ', 'ولقد يسرنا القرءان للذكر فهل من مدكر', NULL, 529, 'local:hafs-text.json'),
  ('hafs-54-23', 'hafs', 54, 23, 'كَذَّبَتْ ثَمُودُ بِٱلنُّذُرِ', 'كذبت ثمود بالنذر', NULL, 529, 'local:hafs-text.json'),
  ('hafs-54-24', 'hafs', 54, 24, 'فَقَالُوٓا۟ أَبَشَرًۭا مِّنَّا وَٰحِدًۭا نَّتَّبِعُهُۥٓ إِنَّآ إِذًۭا لَّفِى ضَلَٰلٍۢ وَسُعُرٍ', 'فقالوا أبشرا منا وحدا نتبعه إنا إذا لفى ضلل وسعر', NULL, 529, 'local:hafs-text.json'),
  ('hafs-54-25', 'hafs', 54, 25, 'أَءُلْقِىَ ٱلذِّكْرُ عَلَيْهِ مِنۢ بَيْنِنَا بَلْ هُوَ كَذَّابٌ أَشِرٌۭ', 'أءلقى الذكر عليه من بيننا بل هو كذاب أشر', NULL, 529, 'local:hafs-text.json'),
  ('hafs-54-26', 'hafs', 54, 26, 'سَيَعْلَمُونَ غَدًۭا مَّنِ ٱلْكَذَّابُ ٱلْأَشِرُ', 'سيعلمون غدا من الكذاب الأشر', NULL, 529, 'local:hafs-text.json'),
  ('hafs-54-27', 'hafs', 54, 27, 'إِنَّا مُرْسِلُوا۟ ٱلنَّاقَةِ فِتْنَةًۭ لَّهُمْ فَٱرْتَقِبْهُمْ وَٱصْطَبِرْ', 'إنا مرسلوا الناقة فتنة لهم فارتقبهم واصطبر', NULL, 529, 'local:hafs-text.json'),
  ('hafs-54-28', 'hafs', 54, 28, 'وَنَبِّئْهُمْ أَنَّ ٱلْمَآءَ قِسْمَةٌۢ بَيْنَهُمْ ۖ كُلُّ شِرْبٍۢ مُّحْتَضَرٌۭ', 'ونبئهم أن الماء قسمة بينهم  كل شرب محتضر', NULL, 530, 'local:hafs-text.json'),
  ('hafs-54-29', 'hafs', 54, 29, 'فَنَادَوْا۟ صَاحِبَهُمْ فَتَعَاطَىٰ فَعَقَرَ', 'فنادوا صاحبهم فتعاطى فعقر', NULL, 530, 'local:hafs-text.json'),
  ('hafs-54-30', 'hafs', 54, 30, 'فَكَيْفَ كَانَ عَذَابِى وَنُذُرِ', 'فكيف كان عذابى ونذر', NULL, 530, 'local:hafs-text.json'),
  ('hafs-54-31', 'hafs', 54, 31, 'إِنَّآ أَرْسَلْنَا عَلَيْهِمْ صَيْحَةًۭ وَٰحِدَةًۭ فَكَانُوا۟ كَهَشِيمِ ٱلْمُحْتَظِرِ', 'إنا أرسلنا عليهم صيحة وحدة فكانوا كهشيم المحتظر', NULL, 530, 'local:hafs-text.json'),
  ('hafs-54-32', 'hafs', 54, 32, 'وَلَقَدْ يَسَّرْنَا ٱلْقُرْءَانَ لِلذِّكْرِ فَهَلْ مِن مُّدَّكِرٍۢ', 'ولقد يسرنا القرءان للذكر فهل من مدكر', NULL, 530, 'local:hafs-text.json'),
  ('hafs-54-33', 'hafs', 54, 33, 'كَذَّبَتْ قَوْمُ لُوطٍۭ بِٱلنُّذُرِ', 'كذبت قوم لوط بالنذر', NULL, 530, 'local:hafs-text.json'),
  ('hafs-54-34', 'hafs', 54, 34, 'إِنَّآ أَرْسَلْنَا عَلَيْهِمْ حَاصِبًا إِلَّآ ءَالَ لُوطٍۢ ۖ نَّجَّيْنَٰهُم بِسَحَرٍۢ', 'إنا أرسلنا عليهم حاصبا إلا ءال لوط  نجينهم بسحر', NULL, 530, 'local:hafs-text.json'),
  ('hafs-54-35', 'hafs', 54, 35, 'نِّعْمَةًۭ مِّنْ عِندِنَا ۚ كَذَٰلِكَ نَجْزِى مَن شَكَرَ', 'نعمة من عندنا  كذلك نجزى من شكر', NULL, 530, 'local:hafs-text.json'),
  ('hafs-54-36', 'hafs', 54, 36, 'وَلَقَدْ أَنذَرَهُم بَطْشَتَنَا فَتَمَارَوْا۟ بِٱلنُّذُرِ', 'ولقد أنذرهم بطشتنا فتماروا بالنذر', NULL, 530, 'local:hafs-text.json'),
  ('hafs-54-37', 'hafs', 54, 37, 'وَلَقَدْ رَٰوَدُوهُ عَن ضَيْفِهِۦ فَطَمَسْنَآ أَعْيُنَهُمْ فَذُوقُوا۟ عَذَابِى وَنُذُرِ', 'ولقد رودوه عن ضيفه فطمسنا أعينهم فذوقوا عذابى ونذر', NULL, 530, 'local:hafs-text.json'),
  ('hafs-54-38', 'hafs', 54, 38, 'وَلَقَدْ صَبَّحَهُم بُكْرَةً عَذَابٌۭ مُّسْتَقِرٌّۭ', 'ولقد صبحهم بكرة عذاب مستقر', NULL, 530, 'local:hafs-text.json'),
  ('hafs-54-39', 'hafs', 54, 39, 'فَذُوقُوا۟ عَذَابِى وَنُذُرِ', 'فذوقوا عذابى ونذر', NULL, 530, 'local:hafs-text.json'),
  ('hafs-54-40', 'hafs', 54, 40, 'وَلَقَدْ يَسَّرْنَا ٱلْقُرْءَانَ لِلذِّكْرِ فَهَلْ مِن مُّدَّكِرٍۢ', 'ولقد يسرنا القرءان للذكر فهل من مدكر', NULL, 530, 'local:hafs-text.json'),
  ('hafs-54-41', 'hafs', 54, 41, 'وَلَقَدْ جَآءَ ءَالَ فِرْعَوْنَ ٱلنُّذُرُ', 'ولقد جاء ءال فرعون النذر', NULL, 530, 'local:hafs-text.json'),
  ('hafs-54-42', 'hafs', 54, 42, 'كَذَّبُوا۟ بِـَٔايَٰتِنَا كُلِّهَا فَأَخَذْنَٰهُمْ أَخْذَ عَزِيزٍۢ مُّقْتَدِرٍ', 'كذبوا بايتنا كلها فأخذنهم أخذ عزيز مقتدر', NULL, 530, 'local:hafs-text.json'),
  ('hafs-54-43', 'hafs', 54, 43, 'أَكُفَّارُكُمْ خَيْرٌۭ مِّنْ أُو۟لَٰٓئِكُمْ أَمْ لَكُم بَرَآءَةٌۭ فِى ٱلزُّبُرِ', 'أكفاركم خير من أولئكم أم لكم براءة فى الزبر', NULL, 530, 'local:hafs-text.json'),
  ('hafs-54-44', 'hafs', 54, 44, 'أَمْ يَقُولُونَ نَحْنُ جَمِيعٌۭ مُّنتَصِرٌۭ', 'أم يقولون نحن جميع منتصر', NULL, 530, 'local:hafs-text.json'),
  ('hafs-54-45', 'hafs', 54, 45, 'سَيُهْزَمُ ٱلْجَمْعُ وَيُوَلُّونَ ٱلدُّبُرَ', 'سيهزم الجمع ويولون الدبر', NULL, 530, 'local:hafs-text.json'),
  ('hafs-54-46', 'hafs', 54, 46, 'بَلِ ٱلسَّاعَةُ مَوْعِدُهُمْ وَٱلسَّاعَةُ أَدْهَىٰ وَأَمَرُّ', 'بل الساعة موعدهم والساعة أدهى وأمر', NULL, 530, 'local:hafs-text.json'),
  ('hafs-54-47', 'hafs', 54, 47, 'إِنَّ ٱلْمُجْرِمِينَ فِى ضَلَٰلٍۢ وَسُعُرٍۢ', 'إن المجرمين فى ضلل وسعر', NULL, 530, 'local:hafs-text.json'),
  ('hafs-54-48', 'hafs', 54, 48, 'يَوْمَ يُسْحَبُونَ فِى ٱلنَّارِ عَلَىٰ وُجُوهِهِمْ ذُوقُوا۟ مَسَّ سَقَرَ', 'يوم يسحبون فى النار على وجوههم ذوقوا مس سقر', NULL, 530, 'local:hafs-text.json'),
  ('hafs-54-49', 'hafs', 54, 49, 'إِنَّا كُلَّ شَىْءٍ خَلَقْنَٰهُ بِقَدَرٍۢ', 'إنا كل شىء خلقنه بقدر', NULL, 530, 'local:hafs-text.json'),
  ('hafs-54-50', 'hafs', 54, 50, 'وَمَآ أَمْرُنَآ إِلَّا وَٰحِدَةٌۭ كَلَمْحٍۭ بِٱلْبَصَرِ', 'وما أمرنا إلا وحدة كلمح بالبصر', NULL, 531, 'local:hafs-text.json'),
  ('hafs-54-51', 'hafs', 54, 51, 'وَلَقَدْ أَهْلَكْنَآ أَشْيَاعَكُمْ فَهَلْ مِن مُّدَّكِرٍۢ', 'ولقد أهلكنا أشياعكم فهل من مدكر', NULL, 531, 'local:hafs-text.json'),
  ('hafs-54-52', 'hafs', 54, 52, 'وَكُلُّ شَىْءٍۢ فَعَلُوهُ فِى ٱلزُّبُرِ', 'وكل شىء فعلوه فى الزبر', NULL, 531, 'local:hafs-text.json'),
  ('hafs-54-53', 'hafs', 54, 53, 'وَكُلُّ صَغِيرٍۢ وَكَبِيرٍۢ مُّسْتَطَرٌ', 'وكل صغير وكبير مستطر', NULL, 531, 'local:hafs-text.json'),
  ('hafs-54-54', 'hafs', 54, 54, 'إِنَّ ٱلْمُتَّقِينَ فِى جَنَّٰتٍۢ وَنَهَرٍۢ', 'إن المتقين فى جنت ونهر', NULL, 531, 'local:hafs-text.json'),
  ('hafs-54-55', 'hafs', 54, 55, 'فِى مَقْعَدِ صِدْقٍ عِندَ مَلِيكٍۢ مُّقْتَدِرٍۭ', 'فى مقعد صدق عند مليك مقتدر', NULL, 531, 'local:hafs-text.json'),
  ('hafs-55-1', 'hafs', 55, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ ٱلرَّحْمَٰنُ', 'بسم الله الرحمن الرحيم الرحمن', NULL, 531, 'local:hafs-text.json'),
  ('hafs-55-2', 'hafs', 55, 2, 'عَلَّمَ ٱلْقُرْءَانَ', 'علم القرءان', NULL, 531, 'local:hafs-text.json'),
  ('hafs-55-3', 'hafs', 55, 3, 'خَلَقَ ٱلْإِنسَٰنَ', 'خلق الإنسن', NULL, 531, 'local:hafs-text.json'),
  ('hafs-55-4', 'hafs', 55, 4, 'عَلَّمَهُ ٱلْبَيَانَ', 'علمه البيان', NULL, 531, 'local:hafs-text.json'),
  ('hafs-55-5', 'hafs', 55, 5, 'ٱلشَّمْسُ وَٱلْقَمَرُ بِحُسْبَانٍۢ', 'الشمس والقمر بحسبان', NULL, 531, 'local:hafs-text.json'),
  ('hafs-55-6', 'hafs', 55, 6, 'وَٱلنَّجْمُ وَٱلشَّجَرُ يَسْجُدَانِ', 'والنجم والشجر يسجدان', NULL, 531, 'local:hafs-text.json'),
  ('hafs-55-7', 'hafs', 55, 7, 'وَٱلسَّمَآءَ رَفَعَهَا وَوَضَعَ ٱلْمِيزَانَ', 'والسماء رفعها ووضع الميزان', NULL, 531, 'local:hafs-text.json'),
  ('hafs-55-8', 'hafs', 55, 8, 'أَلَّا تَطْغَوْا۟ فِى ٱلْمِيزَانِ', 'ألا تطغوا فى الميزان', NULL, 531, 'local:hafs-text.json'),
  ('hafs-55-9', 'hafs', 55, 9, 'وَأَقِيمُوا۟ ٱلْوَزْنَ بِٱلْقِسْطِ وَلَا تُخْسِرُوا۟ ٱلْمِيزَانَ', 'وأقيموا الوزن بالقسط ولا تخسروا الميزان', NULL, 531, 'local:hafs-text.json'),
  ('hafs-55-10', 'hafs', 55, 10, 'وَٱلْأَرْضَ وَضَعَهَا لِلْأَنَامِ', 'والأرض وضعها للأنام', NULL, 531, 'local:hafs-text.json'),
  ('hafs-55-11', 'hafs', 55, 11, 'فِيهَا فَٰكِهَةٌۭ وَٱلنَّخْلُ ذَاتُ ٱلْأَكْمَامِ', 'فيها فكهة والنخل ذات الأكمام', NULL, 531, 'local:hafs-text.json'),
  ('hafs-55-12', 'hafs', 55, 12, 'وَٱلْحَبُّ ذُو ٱلْعَصْفِ وَٱلرَّيْحَانُ', 'والحب ذو العصف والريحان', NULL, 531, 'local:hafs-text.json'),
  ('hafs-55-13', 'hafs', 55, 13, 'فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ', 'فبأى ءالاء ربكما تكذبان', NULL, 531, 'local:hafs-text.json'),
  ('hafs-55-14', 'hafs', 55, 14, 'خَلَقَ ٱلْإِنسَٰنَ مِن صَلْصَٰلٍۢ كَٱلْفَخَّارِ', 'خلق الإنسن من صلصل كالفخار', NULL, 531, 'local:hafs-text.json'),
  ('hafs-55-15', 'hafs', 55, 15, 'وَخَلَقَ ٱلْجَآنَّ مِن مَّارِجٍۢ مِّن نَّارٍۢ', 'وخلق الجان من مارج من نار', NULL, 531, 'local:hafs-text.json'),
  ('hafs-55-16', 'hafs', 55, 16, 'فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ', 'فبأى ءالاء ربكما تكذبان', NULL, 531, 'local:hafs-text.json'),
  ('hafs-55-17', 'hafs', 55, 17, 'رَبُّ ٱلْمَشْرِقَيْنِ وَرَبُّ ٱلْمَغْرِبَيْنِ', 'رب المشرقين ورب المغربين', NULL, 532, 'local:hafs-text.json'),
  ('hafs-55-18', 'hafs', 55, 18, 'فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ', 'فبأى ءالاء ربكما تكذبان', NULL, 532, 'local:hafs-text.json'),
  ('hafs-55-19', 'hafs', 55, 19, 'مَرَجَ ٱلْبَحْرَيْنِ يَلْتَقِيَانِ', 'مرج البحرين يلتقيان', NULL, 532, 'local:hafs-text.json'),
  ('hafs-55-20', 'hafs', 55, 20, 'بَيْنَهُمَا بَرْزَخٌۭ لَّا يَبْغِيَانِ', 'بينهما برزخ لا يبغيان', NULL, 532, 'local:hafs-text.json'),
  ('hafs-55-21', 'hafs', 55, 21, 'فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ', 'فبأى ءالاء ربكما تكذبان', NULL, 532, 'local:hafs-text.json'),
  ('hafs-55-22', 'hafs', 55, 22, 'يَخْرُجُ مِنْهُمَا ٱللُّؤْلُؤُ وَٱلْمَرْجَانُ', 'يخرج منهما اللؤلؤ والمرجان', NULL, 532, 'local:hafs-text.json'),
  ('hafs-55-23', 'hafs', 55, 23, 'فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ', 'فبأى ءالاء ربكما تكذبان', NULL, 532, 'local:hafs-text.json'),
  ('hafs-55-24', 'hafs', 55, 24, 'وَلَهُ ٱلْجَوَارِ ٱلْمُنشَـَٔاتُ فِى ٱلْبَحْرِ كَٱلْأَعْلَٰمِ', 'وله الجوار المنشات فى البحر كالأعلم', NULL, 532, 'local:hafs-text.json'),
  ('hafs-55-25', 'hafs', 55, 25, 'فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ', 'فبأى ءالاء ربكما تكذبان', NULL, 532, 'local:hafs-text.json'),
  ('hafs-55-26', 'hafs', 55, 26, 'كُلُّ مَنْ عَلَيْهَا فَانٍۢ', 'كل من عليها فان', NULL, 532, 'local:hafs-text.json'),
  ('hafs-55-27', 'hafs', 55, 27, 'وَيَبْقَىٰ وَجْهُ رَبِّكَ ذُو ٱلْجَلَٰلِ وَٱلْإِكْرَامِ', 'ويبقى وجه ربك ذو الجلل والإكرام', NULL, 532, 'local:hafs-text.json'),
  ('hafs-55-28', 'hafs', 55, 28, 'فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ', 'فبأى ءالاء ربكما تكذبان', NULL, 532, 'local:hafs-text.json'),
  ('hafs-55-29', 'hafs', 55, 29, 'يَسْـَٔلُهُۥ مَن فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ ۚ كُلَّ يَوْمٍ هُوَ فِى شَأْنٍۢ', 'يسله من فى السموت والأرض  كل يوم هو فى شأن', NULL, 532, 'local:hafs-text.json'),
  ('hafs-55-30', 'hafs', 55, 30, 'فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ', 'فبأى ءالاء ربكما تكذبان', NULL, 532, 'local:hafs-text.json'),
  ('hafs-55-31', 'hafs', 55, 31, 'سَنَفْرُغُ لَكُمْ أَيُّهَ ٱلثَّقَلَانِ', 'سنفرغ لكم أيه الثقلان', NULL, 532, 'local:hafs-text.json'),
  ('hafs-55-32', 'hafs', 55, 32, 'فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ', 'فبأى ءالاء ربكما تكذبان', NULL, 532, 'local:hafs-text.json'),
