  ('hafs-56-27', 'hafs', 56, 27, 'وَأَصْحَٰبُ ٱلْيَمِينِ مَآ أَصْحَٰبُ ٱلْيَمِينِ', 'وأصحب اليمين ما أصحب اليمين', NULL, 535, 'local:hafs-text.json'),
  ('hafs-56-28', 'hafs', 56, 28, 'فِى سِدْرٍۢ مَّخْضُودٍۢ', 'فى سدر مخضود', NULL, 535, 'local:hafs-text.json'),
  ('hafs-56-29', 'hafs', 56, 29, 'وَطَلْحٍۢ مَّنضُودٍۢ', 'وطلح منضود', NULL, 535, 'local:hafs-text.json'),
  ('hafs-56-30', 'hafs', 56, 30, 'وَظِلٍّۢ مَّمْدُودٍۢ', 'وظل ممدود', NULL, 535, 'local:hafs-text.json'),
  ('hafs-56-31', 'hafs', 56, 31, 'وَمَآءٍۢ مَّسْكُوبٍۢ', 'وماء مسكوب', NULL, 535, 'local:hafs-text.json'),
  ('hafs-56-32', 'hafs', 56, 32, 'وَفَٰكِهَةٍۢ كَثِيرَةٍۢ', 'وفكهة كثيرة', NULL, 535, 'local:hafs-text.json'),
  ('hafs-56-33', 'hafs', 56, 33, 'لَّا مَقْطُوعَةٍۢ وَلَا مَمْنُوعَةٍۢ', 'لا مقطوعة ولا ممنوعة', NULL, 535, 'local:hafs-text.json'),
  ('hafs-56-34', 'hafs', 56, 34, 'وَفُرُشٍۢ مَّرْفُوعَةٍ', 'وفرش مرفوعة', NULL, 535, 'local:hafs-text.json'),
  ('hafs-56-35', 'hafs', 56, 35, 'إِنَّآ أَنشَأْنَٰهُنَّ إِنشَآءًۭ', 'إنا أنشأنهن إنشاء', NULL, 535, 'local:hafs-text.json'),
  ('hafs-56-36', 'hafs', 56, 36, 'فَجَعَلْنَٰهُنَّ أَبْكَارًا', 'فجعلنهن أبكارا', NULL, 535, 'local:hafs-text.json'),
  ('hafs-56-37', 'hafs', 56, 37, 'عُرُبًا أَتْرَابًۭا', 'عربا أترابا', NULL, 535, 'local:hafs-text.json'),
  ('hafs-56-38', 'hafs', 56, 38, 'لِّأَصْحَٰبِ ٱلْيَمِينِ', 'لأصحب اليمين', NULL, 535, 'local:hafs-text.json'),
  ('hafs-56-39', 'hafs', 56, 39, 'ثُلَّةٌۭ مِّنَ ٱلْأَوَّلِينَ', 'ثلة من الأولين', NULL, 535, 'local:hafs-text.json'),
  ('hafs-56-40', 'hafs', 56, 40, 'وَثُلَّةٌۭ مِّنَ ٱلْءَاخِرِينَ', 'وثلة من الءاخرين', NULL, 535, 'local:hafs-text.json'),
  ('hafs-56-41', 'hafs', 56, 41, 'وَأَصْحَٰبُ ٱلشِّمَالِ مَآ أَصْحَٰبُ ٱلشِّمَالِ', 'وأصحب الشمال ما أصحب الشمال', NULL, 535, 'local:hafs-text.json'),
  ('hafs-56-42', 'hafs', 56, 42, 'فِى سَمُومٍۢ وَحَمِيمٍۢ', 'فى سموم وحميم', NULL, 535, 'local:hafs-text.json'),
  ('hafs-56-43', 'hafs', 56, 43, 'وَظِلٍّۢ مِّن يَحْمُومٍۢ', 'وظل من يحموم', NULL, 535, 'local:hafs-text.json'),
  ('hafs-56-44', 'hafs', 56, 44, 'لَّا بَارِدٍۢ وَلَا كَرِيمٍ', 'لا بارد ولا كريم', NULL, 535, 'local:hafs-text.json'),
  ('hafs-56-45', 'hafs', 56, 45, 'إِنَّهُمْ كَانُوا۟ قَبْلَ ذَٰلِكَ مُتْرَفِينَ', 'إنهم كانوا قبل ذلك مترفين', NULL, 535, 'local:hafs-text.json'),
  ('hafs-56-46', 'hafs', 56, 46, 'وَكَانُوا۟ يُصِرُّونَ عَلَى ٱلْحِنثِ ٱلْعَظِيمِ', 'وكانوا يصرون على الحنث العظيم', NULL, 535, 'local:hafs-text.json'),
  ('hafs-56-47', 'hafs', 56, 47, 'وَكَانُوا۟ يَقُولُونَ أَئِذَا مِتْنَا وَكُنَّا تُرَابًۭا وَعِظَٰمًا أَءِنَّا لَمَبْعُوثُونَ', 'وكانوا يقولون أئذا متنا وكنا ترابا وعظما أءنا لمبعوثون', NULL, 535, 'local:hafs-text.json'),
  ('hafs-56-48', 'hafs', 56, 48, 'أَوَءَابَآؤُنَا ٱلْأَوَّلُونَ', 'أوءاباؤنا الأولون', NULL, 535, 'local:hafs-text.json'),
  ('hafs-56-49', 'hafs', 56, 49, 'قُلْ إِنَّ ٱلْأَوَّلِينَ وَٱلْءَاخِرِينَ', 'قل إن الأولين والءاخرين', NULL, 535, 'local:hafs-text.json'),
  ('hafs-56-50', 'hafs', 56, 50, 'لَمَجْمُوعُونَ إِلَىٰ مِيقَٰتِ يَوْمٍۢ مَّعْلُومٍۢ', 'لمجموعون إلى ميقت يوم معلوم', NULL, 535, 'local:hafs-text.json'),
  ('hafs-56-51', 'hafs', 56, 51, 'ثُمَّ إِنَّكُمْ أَيُّهَا ٱلضَّآلُّونَ ٱلْمُكَذِّبُونَ', 'ثم إنكم أيها الضالون المكذبون', NULL, 536, 'local:hafs-text.json'),
  ('hafs-56-52', 'hafs', 56, 52, 'لَءَاكِلُونَ مِن شَجَرٍۢ مِّن زَقُّومٍۢ', 'لءاكلون من شجر من زقوم', NULL, 536, 'local:hafs-text.json'),
  ('hafs-56-53', 'hafs', 56, 53, 'فَمَالِـُٔونَ مِنْهَا ٱلْبُطُونَ', 'فمالون منها البطون', NULL, 536, 'local:hafs-text.json'),
  ('hafs-56-54', 'hafs', 56, 54, 'فَشَٰرِبُونَ عَلَيْهِ مِنَ ٱلْحَمِيمِ', 'فشربون عليه من الحميم', NULL, 536, 'local:hafs-text.json'),
  ('hafs-56-55', 'hafs', 56, 55, 'فَشَٰرِبُونَ شُرْبَ ٱلْهِيمِ', 'فشربون شرب الهيم', NULL, 536, 'local:hafs-text.json'),
  ('hafs-56-56', 'hafs', 56, 56, 'هَٰذَا نُزُلُهُمْ يَوْمَ ٱلدِّينِ', 'هذا نزلهم يوم الدين', NULL, 536, 'local:hafs-text.json'),
  ('hafs-56-57', 'hafs', 56, 57, 'نَحْنُ خَلَقْنَٰكُمْ فَلَوْلَا تُصَدِّقُونَ', 'نحن خلقنكم فلولا تصدقون', NULL, 536, 'local:hafs-text.json'),
  ('hafs-56-58', 'hafs', 56, 58, 'أَفَرَءَيْتُم مَّا تُمْنُونَ', 'أفرءيتم ما تمنون', NULL, 536, 'local:hafs-text.json'),
  ('hafs-56-59', 'hafs', 56, 59, 'ءَأَنتُمْ تَخْلُقُونَهُۥٓ أَمْ نَحْنُ ٱلْخَٰلِقُونَ', 'ءأنتم تخلقونه أم نحن الخلقون', NULL, 536, 'local:hafs-text.json'),
  ('hafs-56-60', 'hafs', 56, 60, 'نَحْنُ قَدَّرْنَا بَيْنَكُمُ ٱلْمَوْتَ وَمَا نَحْنُ بِمَسْبُوقِينَ', 'نحن قدرنا بينكم الموت وما نحن بمسبوقين', NULL, 536, 'local:hafs-text.json'),
  ('hafs-56-61', 'hafs', 56, 61, 'عَلَىٰٓ أَن نُّبَدِّلَ أَمْثَٰلَكُمْ وَنُنشِئَكُمْ فِى مَا لَا تَعْلَمُونَ', 'على أن نبدل أمثلكم وننشئكم فى ما لا تعلمون', NULL, 536, 'local:hafs-text.json'),
  ('hafs-56-62', 'hafs', 56, 62, 'وَلَقَدْ عَلِمْتُمُ ٱلنَّشْأَةَ ٱلْأُولَىٰ فَلَوْلَا تَذَكَّرُونَ', 'ولقد علمتم النشأة الأولى فلولا تذكرون', NULL, 536, 'local:hafs-text.json'),
  ('hafs-56-63', 'hafs', 56, 63, 'أَفَرَءَيْتُم مَّا تَحْرُثُونَ', 'أفرءيتم ما تحرثون', NULL, 536, 'local:hafs-text.json'),
  ('hafs-56-64', 'hafs', 56, 64, 'ءَأَنتُمْ تَزْرَعُونَهُۥٓ أَمْ نَحْنُ ٱلزَّٰرِعُونَ', 'ءأنتم تزرعونه أم نحن الزرعون', NULL, 536, 'local:hafs-text.json'),
  ('hafs-56-65', 'hafs', 56, 65, 'لَوْ نَشَآءُ لَجَعَلْنَٰهُ حُطَٰمًۭا فَظَلْتُمْ تَفَكَّهُونَ', 'لو نشاء لجعلنه حطما فظلتم تفكهون', NULL, 536, 'local:hafs-text.json'),
  ('hafs-56-66', 'hafs', 56, 66, 'إِنَّا لَمُغْرَمُونَ', 'إنا لمغرمون', NULL, 536, 'local:hafs-text.json'),
  ('hafs-56-67', 'hafs', 56, 67, 'بَلْ نَحْنُ مَحْرُومُونَ', 'بل نحن محرومون', NULL, 536, 'local:hafs-text.json'),
  ('hafs-56-68', 'hafs', 56, 68, 'أَفَرَءَيْتُمُ ٱلْمَآءَ ٱلَّذِى تَشْرَبُونَ', 'أفرءيتم الماء الذى تشربون', NULL, 536, 'local:hafs-text.json'),
  ('hafs-56-69', 'hafs', 56, 69, 'ءَأَنتُمْ أَنزَلْتُمُوهُ مِنَ ٱلْمُزْنِ أَمْ نَحْنُ ٱلْمُنزِلُونَ', 'ءأنتم أنزلتموه من المزن أم نحن المنزلون', NULL, 536, 'local:hafs-text.json'),
  ('hafs-56-70', 'hafs', 56, 70, 'لَوْ نَشَآءُ جَعَلْنَٰهُ أُجَاجًۭا فَلَوْلَا تَشْكُرُونَ', 'لو نشاء جعلنه أجاجا فلولا تشكرون', NULL, 536, 'local:hafs-text.json'),
  ('hafs-56-71', 'hafs', 56, 71, 'أَفَرَءَيْتُمُ ٱلنَّارَ ٱلَّتِى تُورُونَ', 'أفرءيتم النار التى تورون', NULL, 536, 'local:hafs-text.json'),
  ('hafs-56-72', 'hafs', 56, 72, 'ءَأَنتُمْ أَنشَأْتُمْ شَجَرَتَهَآ أَمْ نَحْنُ ٱلْمُنشِـُٔونَ', 'ءأنتم أنشأتم شجرتها أم نحن المنشون', NULL, 536, 'local:hafs-text.json'),
  ('hafs-56-73', 'hafs', 56, 73, 'نَحْنُ جَعَلْنَٰهَا تَذْكِرَةًۭ وَمَتَٰعًۭا لِّلْمُقْوِينَ', 'نحن جعلنها تذكرة ومتعا للمقوين', NULL, 536, 'local:hafs-text.json'),
  ('hafs-56-74', 'hafs', 56, 74, 'فَسَبِّحْ بِٱسْمِ رَبِّكَ ٱلْعَظِيمِ', 'فسبح باسم ربك العظيم', NULL, 536, 'local:hafs-text.json'),
  ('hafs-56-75', 'hafs', 56, 75, '۞ فَلَآ أُقْسِمُ بِمَوَٰقِعِ ٱلنُّجُومِ', 'فلا أقسم بموقع النجوم', NULL, 536, 'local:hafs-text.json'),
  ('hafs-56-76', 'hafs', 56, 76, 'وَإِنَّهُۥ لَقَسَمٌۭ لَّوْ تَعْلَمُونَ عَظِيمٌ', 'وإنه لقسم لو تعلمون عظيم', NULL, 536, 'local:hafs-text.json'),
  ('hafs-56-77', 'hafs', 56, 77, 'إِنَّهُۥ لَقُرْءَانٌۭ كَرِيمٌۭ', 'إنه لقرءان كريم', NULL, 537, 'local:hafs-text.json'),
  ('hafs-56-78', 'hafs', 56, 78, 'فِى كِتَٰبٍۢ مَّكْنُونٍۢ', 'فى كتب مكنون', NULL, 537, 'local:hafs-text.json'),
  ('hafs-56-79', 'hafs', 56, 79, 'لَّا يَمَسُّهُۥٓ إِلَّا ٱلْمُطَهَّرُونَ', 'لا يمسه إلا المطهرون', NULL, 537, 'local:hafs-text.json'),
  ('hafs-56-80', 'hafs', 56, 80, 'تَنزِيلٌۭ مِّن رَّبِّ ٱلْعَٰلَمِينَ', 'تنزيل من رب العلمين', NULL, 537, 'local:hafs-text.json'),
  ('hafs-56-81', 'hafs', 56, 81, 'أَفَبِهَٰذَا ٱلْحَدِيثِ أَنتُم مُّدْهِنُونَ', 'أفبهذا الحديث أنتم مدهنون', NULL, 537, 'local:hafs-text.json'),
  ('hafs-56-82', 'hafs', 56, 82, 'وَتَجْعَلُونَ رِزْقَكُمْ أَنَّكُمْ تُكَذِّبُونَ', 'وتجعلون رزقكم أنكم تكذبون', NULL, 537, 'local:hafs-text.json'),
  ('hafs-56-83', 'hafs', 56, 83, 'فَلَوْلَآ إِذَا بَلَغَتِ ٱلْحُلْقُومَ', 'فلولا إذا بلغت الحلقوم', NULL, 537, 'local:hafs-text.json'),
  ('hafs-56-84', 'hafs', 56, 84, 'وَأَنتُمْ حِينَئِذٍۢ تَنظُرُونَ', 'وأنتم حينئذ تنظرون', NULL, 537, 'local:hafs-text.json'),
  ('hafs-56-85', 'hafs', 56, 85, 'وَنَحْنُ أَقْرَبُ إِلَيْهِ مِنكُمْ وَلَٰكِن لَّا تُبْصِرُونَ', 'ونحن أقرب إليه منكم ولكن لا تبصرون', NULL, 537, 'local:hafs-text.json'),
  ('hafs-56-86', 'hafs', 56, 86, 'فَلَوْلَآ إِن كُنتُمْ غَيْرَ مَدِينِينَ', 'فلولا إن كنتم غير مدينين', NULL, 537, 'local:hafs-text.json'),
  ('hafs-56-87', 'hafs', 56, 87, 'تَرْجِعُونَهَآ إِن كُنتُمْ صَٰدِقِينَ', 'ترجعونها إن كنتم صدقين', NULL, 537, 'local:hafs-text.json'),
  ('hafs-56-88', 'hafs', 56, 88, 'فَأَمَّآ إِن كَانَ مِنَ ٱلْمُقَرَّبِينَ', 'فأما إن كان من المقربين', NULL, 537, 'local:hafs-text.json'),
  ('hafs-56-89', 'hafs', 56, 89, 'فَرَوْحٌۭ وَرَيْحَانٌۭ وَجَنَّتُ نَعِيمٍۢ', 'فروح وريحان وجنت نعيم', NULL, 537, 'local:hafs-text.json'),
  ('hafs-56-90', 'hafs', 56, 90, 'وَأَمَّآ إِن كَانَ مِنْ أَصْحَٰبِ ٱلْيَمِينِ', 'وأما إن كان من أصحب اليمين', NULL, 537, 'local:hafs-text.json'),
  ('hafs-56-91', 'hafs', 56, 91, 'فَسَلَٰمٌۭ لَّكَ مِنْ أَصْحَٰبِ ٱلْيَمِينِ', 'فسلم لك من أصحب اليمين', NULL, 537, 'local:hafs-text.json'),
  ('hafs-56-92', 'hafs', 56, 92, 'وَأَمَّآ إِن كَانَ مِنَ ٱلْمُكَذِّبِينَ ٱلضَّآلِّينَ', 'وأما إن كان من المكذبين الضالين', NULL, 537, 'local:hafs-text.json'),
  ('hafs-56-93', 'hafs', 56, 93, 'فَنُزُلٌۭ مِّنْ حَمِيمٍۢ', 'فنزل من حميم', NULL, 537, 'local:hafs-text.json'),
  ('hafs-56-94', 'hafs', 56, 94, 'وَتَصْلِيَةُ جَحِيمٍ', 'وتصلية جحيم', NULL, 537, 'local:hafs-text.json'),
  ('hafs-56-95', 'hafs', 56, 95, 'إِنَّ هَٰذَا لَهُوَ حَقُّ ٱلْيَقِينِ', 'إن هذا لهو حق اليقين', NULL, 537, 'local:hafs-text.json'),
  ('hafs-56-96', 'hafs', 56, 96, 'فَسَبِّحْ بِٱسْمِ رَبِّكَ ٱلْعَظِيمِ', 'فسبح باسم ربك العظيم', NULL, 537, 'local:hafs-text.json'),
  ('hafs-57-1', 'hafs', 57, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ سَبَّحَ لِلَّهِ مَا فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ ۖ وَهُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ', 'بسم الله الرحمن الرحيم سبح لله ما فى السموت والأرض  وهو العزيز الحكيم', NULL, 537, 'local:hafs-text.json'),
  ('hafs-57-2', 'hafs', 57, 2, 'لَهُۥ مُلْكُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ ۖ يُحْىِۦ وَيُمِيتُ ۖ وَهُوَ عَلَىٰ كُلِّ شَىْءٍۢ قَدِيرٌ', 'له ملك السموت والأرض  يحى ويميت  وهو على كل شىء قدير', NULL, 537, 'local:hafs-text.json'),
  ('hafs-57-3', 'hafs', 57, 3, 'هُوَ ٱلْأَوَّلُ وَٱلْءَاخِرُ وَٱلظَّٰهِرُ وَٱلْبَاطِنُ ۖ وَهُوَ بِكُلِّ شَىْءٍ عَلِيمٌ', 'هو الأول والءاخر والظهر والباطن  وهو بكل شىء عليم', NULL, 537, 'local:hafs-text.json'),
  ('hafs-57-4', 'hafs', 57, 4, 'هُوَ ٱلَّذِى خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ فِى سِتَّةِ أَيَّامٍۢ ثُمَّ ٱسْتَوَىٰ عَلَى ٱلْعَرْشِ ۚ يَعْلَمُ مَا يَلِجُ فِى ٱلْأَرْضِ وَمَا يَخْرُجُ مِنْهَا وَمَا يَنزِلُ مِنَ ٱلسَّمَآءِ وَمَا يَعْرُجُ فِيهَا ۖ وَهُوَ مَعَكُمْ أَيْنَ مَا كُنتُمْ ۚ وَٱللَّهُ بِمَا تَعْمَلُونَ بَصِيرٌۭ', 'هو الذى خلق السموت والأرض فى ستة أيام ثم استوى على العرش  يعلم ما يلج فى الأرض وما يخرج منها وما ينزل من السماء وما يعرج فيها  وهو معكم أين ما كنتم  والله بما تعملون بصير', NULL, 538, 'local:hafs-text.json'),
  ('hafs-57-5', 'hafs', 57, 5, 'لَّهُۥ مُلْكُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ ۚ وَإِلَى ٱللَّهِ تُرْجَعُ ٱلْأُمُورُ', 'له ملك السموت والأرض  وإلى الله ترجع الأمور', NULL, 538, 'local:hafs-text.json'),
  ('hafs-57-6', 'hafs', 57, 6, 'يُولِجُ ٱلَّيْلَ فِى ٱلنَّهَارِ وَيُولِجُ ٱلنَّهَارَ فِى ٱلَّيْلِ ۚ وَهُوَ عَلِيمٌۢ بِذَاتِ ٱلصُّدُورِ', 'يولج اليل فى النهار ويولج النهار فى اليل  وهو عليم بذات الصدور', NULL, 538, 'local:hafs-text.json'),
  ('hafs-57-7', 'hafs', 57, 7, 'ءَامِنُوا۟ بِٱللَّهِ وَرَسُولِهِۦ وَأَنفِقُوا۟ مِمَّا جَعَلَكُم مُّسْتَخْلَفِينَ فِيهِ ۖ فَٱلَّذِينَ ءَامَنُوا۟ مِنكُمْ وَأَنفَقُوا۟ لَهُمْ أَجْرٌۭ كَبِيرٌۭ', 'ءامنوا بالله ورسوله وأنفقوا مما جعلكم مستخلفين فيه  فالذين ءامنوا منكم وأنفقوا لهم أجر كبير', NULL, 538, 'local:hafs-text.json'),
  ('hafs-57-8', 'hafs', 57, 8, 'وَمَا لَكُمْ لَا تُؤْمِنُونَ بِٱللَّهِ ۙ وَٱلرَّسُولُ يَدْعُوكُمْ لِتُؤْمِنُوا۟ بِرَبِّكُمْ وَقَدْ أَخَذَ مِيثَٰقَكُمْ إِن كُنتُم مُّؤْمِنِينَ', 'وما لكم لا تؤمنون بالله  والرسول يدعوكم لتؤمنوا بربكم وقد أخذ ميثقكم إن كنتم مؤمنين', NULL, 538, 'local:hafs-text.json'),
  ('hafs-57-9', 'hafs', 57, 9, 'هُوَ ٱلَّذِى يُنَزِّلُ عَلَىٰ عَبْدِهِۦٓ ءَايَٰتٍۭ بَيِّنَٰتٍۢ لِّيُخْرِجَكُم مِّنَ ٱلظُّلُمَٰتِ إِلَى ٱلنُّورِ ۚ وَإِنَّ ٱللَّهَ بِكُمْ لَرَءُوفٌۭ رَّحِيمٌۭ', 'هو الذى ينزل على عبده ءايت بينت ليخرجكم من الظلمت إلى النور  وإن الله بكم لرءوف رحيم', NULL, 538, 'local:hafs-text.json'),
  ('hafs-57-10', 'hafs', 57, 10, 'وَمَا لَكُمْ أَلَّا تُنفِقُوا۟ فِى سَبِيلِ ٱللَّهِ وَلِلَّهِ مِيرَٰثُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ ۚ لَا يَسْتَوِى مِنكُم مَّنْ أَنفَقَ مِن قَبْلِ ٱلْفَتْحِ وَقَٰتَلَ ۚ أُو۟لَٰٓئِكَ أَعْظَمُ دَرَجَةًۭ مِّنَ ٱلَّذِينَ أَنفَقُوا۟ مِنۢ بَعْدُ وَقَٰتَلُوا۟ ۚ وَكُلًّۭا وَعَدَ ٱللَّهُ ٱلْحُسْنَىٰ ۚ وَٱللَّهُ بِمَا تَعْمَلُونَ خَبِيرٌۭ', 'وما لكم ألا تنفقوا فى سبيل الله ولله ميرث السموت والأرض  لا يستوى منكم من أنفق من قبل الفتح وقتل  أولئك أعظم درجة من الذين أنفقوا من بعد وقتلوا  وكلا وعد الله الحسنى  والله بما تعملون خبير', NULL, 538, 'local:hafs-text.json'),
  ('hafs-57-11', 'hafs', 57, 11, 'مَّن ذَا ٱلَّذِى يُقْرِضُ ٱللَّهَ قَرْضًا حَسَنًۭا فَيُضَٰعِفَهُۥ لَهُۥ وَلَهُۥٓ أَجْرٌۭ كَرِيمٌۭ', 'من ذا الذى يقرض الله قرضا حسنا فيضعفه له وله أجر كريم', NULL, 538, 'local:hafs-text.json'),
  ('hafs-57-12', 'hafs', 57, 12, 'يَوْمَ تَرَى ٱلْمُؤْمِنِينَ وَٱلْمُؤْمِنَٰتِ يَسْعَىٰ نُورُهُم بَيْنَ أَيْدِيهِمْ وَبِأَيْمَٰنِهِم بُشْرَىٰكُمُ ٱلْيَوْمَ جَنَّٰتٌۭ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ خَٰلِدِينَ فِيهَا ۚ ذَٰلِكَ هُوَ ٱلْفَوْزُ ٱلْعَظِيمُ', 'يوم ترى المؤمنين والمؤمنت يسعى نورهم بين أيديهم وبأيمنهم بشرىكم اليوم جنت تجرى من تحتها الأنهر خلدين فيها  ذلك هو الفوز العظيم', NULL, 539, 'local:hafs-text.json'),
  ('hafs-57-13', 'hafs', 57, 13, 'يَوْمَ يَقُولُ ٱلْمُنَٰفِقُونَ وَٱلْمُنَٰفِقَٰتُ لِلَّذِينَ ءَامَنُوا۟ ٱنظُرُونَا نَقْتَبِسْ مِن نُّورِكُمْ قِيلَ ٱرْجِعُوا۟ وَرَآءَكُمْ فَٱلْتَمِسُوا۟ نُورًۭا فَضُرِبَ بَيْنَهُم بِسُورٍۢ لَّهُۥ بَابٌۢ بَاطِنُهُۥ فِيهِ ٱلرَّحْمَةُ وَظَٰهِرُهُۥ مِن قِبَلِهِ ٱلْعَذَابُ', 'يوم يقول المنفقون والمنفقت للذين ءامنوا انظرونا نقتبس من نوركم قيل ارجعوا وراءكم فالتمسوا نورا فضرب بينهم بسور له باب باطنه فيه الرحمة وظهره من قبله العذاب', NULL, 539, 'local:hafs-text.json'),
  ('hafs-57-14', 'hafs', 57, 14, 'يُنَادُونَهُمْ أَلَمْ نَكُن مَّعَكُمْ ۖ قَالُوا۟ بَلَىٰ وَلَٰكِنَّكُمْ فَتَنتُمْ أَنفُسَكُمْ وَتَرَبَّصْتُمْ وَٱرْتَبْتُمْ وَغَرَّتْكُمُ ٱلْأَمَانِىُّ حَتَّىٰ جَآءَ أَمْرُ ٱللَّهِ وَغَرَّكُم بِٱللَّهِ ٱلْغَرُورُ', 'ينادونهم ألم نكن معكم  قالوا بلى ولكنكم فتنتم أنفسكم وتربصتم وارتبتم وغرتكم الأمانى حتى جاء أمر الله وغركم بالله الغرور', NULL, 539, 'local:hafs-text.json'),
  ('hafs-57-15', 'hafs', 57, 15, 'فَٱلْيَوْمَ لَا يُؤْخَذُ مِنكُمْ فِدْيَةٌۭ وَلَا مِنَ ٱلَّذِينَ كَفَرُوا۟ ۚ مَأْوَىٰكُمُ ٱلنَّارُ ۖ هِىَ مَوْلَىٰكُمْ ۖ وَبِئْسَ ٱلْمَصِيرُ', 'فاليوم لا يؤخذ منكم فدية ولا من الذين كفروا  مأوىكم النار  هى مولىكم  وبئس المصير', NULL, 539, 'local:hafs-text.json'),
  ('hafs-57-16', 'hafs', 57, 16, '۞ أَلَمْ يَأْنِ لِلَّذِينَ ءَامَنُوٓا۟ أَن تَخْشَعَ قُلُوبُهُمْ لِذِكْرِ ٱللَّهِ وَمَا نَزَلَ مِنَ ٱلْحَقِّ وَلَا يَكُونُوا۟ كَٱلَّذِينَ أُوتُوا۟ ٱلْكِتَٰبَ مِن قَبْلُ فَطَالَ عَلَيْهِمُ ٱلْأَمَدُ فَقَسَتْ قُلُوبُهُمْ ۖ وَكَثِيرٌۭ مِّنْهُمْ فَٰسِقُونَ', 'ألم يأن للذين ءامنوا أن تخشع قلوبهم لذكر الله وما نزل من الحق ولا يكونوا كالذين أوتوا الكتب من قبل فطال عليهم الأمد فقست قلوبهم  وكثير منهم فسقون', NULL, 539, 'local:hafs-text.json'),
  ('hafs-57-17', 'hafs', 57, 17, 'ٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ يُحْىِ ٱلْأَرْضَ بَعْدَ مَوْتِهَا ۚ قَدْ بَيَّنَّا لَكُمُ ٱلْءَايَٰتِ لَعَلَّكُمْ تَعْقِلُونَ', 'اعلموا أن الله يحى الأرض بعد موتها  قد بينا لكم الءايت لعلكم تعقلون', NULL, 539, 'local:hafs-text.json'),
  ('hafs-57-18', 'hafs', 57, 18, 'إِنَّ ٱلْمُصَّدِّقِينَ وَٱلْمُصَّدِّقَٰتِ وَأَقْرَضُوا۟ ٱللَّهَ قَرْضًا حَسَنًۭا يُضَٰعَفُ لَهُمْ وَلَهُمْ أَجْرٌۭ كَرِيمٌۭ', 'إن المصدقين والمصدقت وأقرضوا الله قرضا حسنا يضعف لهم ولهم أجر كريم', NULL, 539, 'local:hafs-text.json'),
  ('hafs-57-19', 'hafs', 57, 19, 'وَٱلَّذِينَ ءَامَنُوا۟ بِٱللَّهِ وَرُسُلِهِۦٓ أُو۟لَٰٓئِكَ هُمُ ٱلصِّدِّيقُونَ ۖ وَٱلشُّهَدَآءُ عِندَ رَبِّهِمْ لَهُمْ أَجْرُهُمْ وَنُورُهُمْ ۖ وَٱلَّذِينَ كَفَرُوا۟ وَكَذَّبُوا۟ بِـَٔايَٰتِنَآ أُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلْجَحِيمِ', 'والذين ءامنوا بالله ورسله أولئك هم الصديقون  والشهداء عند ربهم لهم أجرهم ونورهم  والذين كفروا وكذبوا بايتنا أولئك أصحب الجحيم', NULL, 540, 'local:hafs-text.json'),
  ('hafs-57-20', 'hafs', 57, 20, 'ٱعْلَمُوٓا۟ أَنَّمَا ٱلْحَيَوٰةُ ٱلدُّنْيَا لَعِبٌۭ وَلَهْوٌۭ وَزِينَةٌۭ وَتَفَاخُرٌۢ بَيْنَكُمْ وَتَكَاثُرٌۭ فِى ٱلْأَمْوَٰلِ وَٱلْأَوْلَٰدِ ۖ كَمَثَلِ غَيْثٍ أَعْجَبَ ٱلْكُفَّارَ نَبَاتُهُۥ ثُمَّ يَهِيجُ فَتَرَىٰهُ مُصْفَرًّۭا ثُمَّ يَكُونُ حُطَٰمًۭا ۖ وَفِى ٱلْءَاخِرَةِ عَذَابٌۭ شَدِيدٌۭ وَمَغْفِرَةٌۭ مِّنَ ٱللَّهِ وَرِضْوَٰنٌۭ ۚ وَمَا ٱلْحَيَوٰةُ ٱلدُّنْيَآ إِلَّا مَتَٰعُ ٱلْغُرُورِ', 'اعلموا أنما الحيوة الدنيا لعب ولهو وزينة وتفاخر بينكم وتكاثر فى الأمول والأولد  كمثل غيث أعجب الكفار نباته ثم يهيج فترىه مصفرا ثم يكون حطما  وفى الءاخرة عذاب شديد ومغفرة من الله ورضون  وما الحيوة الدنيا إلا متع الغرور', NULL, 540, 'local:hafs-text.json'),
  ('hafs-57-21', 'hafs', 57, 21, 'سَابِقُوٓا۟ إِلَىٰ مَغْفِرَةٍۢ مِّن رَّبِّكُمْ وَجَنَّةٍ عَرْضُهَا كَعَرْضِ ٱلسَّمَآءِ وَٱلْأَرْضِ أُعِدَّتْ لِلَّذِينَ ءَامَنُوا۟ بِٱللَّهِ وَرُسُلِهِۦ ۚ ذَٰلِكَ فَضْلُ ٱللَّهِ يُؤْتِيهِ مَن يَشَآءُ ۚ وَٱللَّهُ ذُو ٱلْفَضْلِ ٱلْعَظِيمِ', 'سابقوا إلى مغفرة من ربكم وجنة عرضها كعرض السماء والأرض أعدت للذين ءامنوا بالله ورسله  ذلك فضل الله يؤتيه من يشاء  والله ذو الفضل العظيم', NULL, 540, 'local:hafs-text.json'),
  ('hafs-57-22', 'hafs', 57, 22, 'مَآ أَصَابَ مِن مُّصِيبَةٍۢ فِى ٱلْأَرْضِ وَلَا فِىٓ أَنفُسِكُمْ إِلَّا فِى كِتَٰبٍۢ مِّن قَبْلِ أَن نَّبْرَأَهَآ ۚ إِنَّ ذَٰلِكَ عَلَى ٱللَّهِ يَسِيرٌۭ', 'ما أصاب من مصيبة فى الأرض ولا فى أنفسكم إلا فى كتب من قبل أن نبرأها  إن ذلك على الله يسير', NULL, 540, 'local:hafs-text.json'),
  ('hafs-57-23', 'hafs', 57, 23, 'لِّكَيْلَا تَأْسَوْا۟ عَلَىٰ مَا فَاتَكُمْ وَلَا تَفْرَحُوا۟ بِمَآ ءَاتَىٰكُمْ ۗ وَٱللَّهُ لَا يُحِبُّ كُلَّ مُخْتَالٍۢ فَخُورٍ', 'لكيلا تأسوا على ما فاتكم ولا تفرحوا بما ءاتىكم  والله لا يحب كل مختال فخور', NULL, 540, 'local:hafs-text.json'),
  ('hafs-57-24', 'hafs', 57, 24, 'ٱلَّذِينَ يَبْخَلُونَ وَيَأْمُرُونَ ٱلنَّاسَ بِٱلْبُخْلِ ۗ وَمَن يَتَوَلَّ فَإِنَّ ٱللَّهَ هُوَ ٱلْغَنِىُّ ٱلْحَمِيدُ', 'الذين يبخلون ويأمرون الناس بالبخل  ومن يتول فإن الله هو الغنى الحميد', NULL, 540, 'local:hafs-text.json'),
  ('hafs-57-25', 'hafs', 57, 25, 'لَقَدْ أَرْسَلْنَا رُسُلَنَا بِٱلْبَيِّنَٰتِ وَأَنزَلْنَا مَعَهُمُ ٱلْكِتَٰبَ وَٱلْمِيزَانَ لِيَقُومَ ٱلنَّاسُ بِٱلْقِسْطِ ۖ وَأَنزَلْنَا ٱلْحَدِيدَ فِيهِ بَأْسٌۭ شَدِيدٌۭ وَمَنَٰفِعُ لِلنَّاسِ وَلِيَعْلَمَ ٱللَّهُ مَن يَنصُرُهُۥ وَرُسُلَهُۥ بِٱلْغَيْبِ ۚ إِنَّ ٱللَّهَ قَوِىٌّ عَزِيزٌۭ', 'لقد أرسلنا رسلنا بالبينت وأنزلنا معهم الكتب والميزان ليقوم الناس بالقسط  وأنزلنا الحديد فيه بأس شديد ومنفع للناس وليعلم الله من ينصره ورسله بالغيب  إن الله قوى عزيز', NULL, 541, 'local:hafs-text.json'),
  ('hafs-57-26', 'hafs', 57, 26, 'وَلَقَدْ أَرْسَلْنَا نُوحًۭا وَإِبْرَٰهِيمَ وَجَعَلْنَا فِى ذُرِّيَّتِهِمَا ٱلنُّبُوَّةَ وَٱلْكِتَٰبَ ۖ فَمِنْهُم مُّهْتَدٍۢ ۖ وَكَثِيرٌۭ مِّنْهُمْ فَٰسِقُونَ', 'ولقد أرسلنا نوحا وإبرهيم وجعلنا فى ذريتهما النبوة والكتب  فمنهم مهتد  وكثير منهم فسقون', NULL, 541, 'local:hafs-text.json'),
  ('hafs-57-27', 'hafs', 57, 27, 'ثُمَّ قَفَّيْنَا عَلَىٰٓ ءَاثَٰرِهِم بِرُسُلِنَا وَقَفَّيْنَا بِعِيسَى ٱبْنِ مَرْيَمَ وَءَاتَيْنَٰهُ ٱلْإِنجِيلَ وَجَعَلْنَا فِى قُلُوبِ ٱلَّذِينَ ٱتَّبَعُوهُ رَأْفَةًۭ وَرَحْمَةًۭ وَرَهْبَانِيَّةً ٱبْتَدَعُوهَا مَا كَتَبْنَٰهَا عَلَيْهِمْ إِلَّا ٱبْتِغَآءَ رِضْوَٰنِ ٱللَّهِ فَمَا رَعَوْهَا حَقَّ رِعَايَتِهَا ۖ فَـَٔاتَيْنَا ٱلَّذِينَ ءَامَنُوا۟ مِنْهُمْ أَجْرَهُمْ ۖ وَكَثِيرٌۭ مِّنْهُمْ فَٰسِقُونَ', 'ثم قفينا على ءاثرهم برسلنا وقفينا بعيسى ابن مريم وءاتينه الإنجيل وجعلنا فى قلوب الذين اتبعوه رأفة ورحمة ورهبانية ابتدعوها ما كتبنها عليهم إلا ابتغاء رضون الله فما رعوها حق رعايتها  فاتينا الذين ءامنوا منهم أجرهم  وكثير منهم فسقون', NULL, 541, 'local:hafs-text.json'),
  ('hafs-57-28', 'hafs', 57, 28, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱتَّقُوا۟ ٱللَّهَ وَءَامِنُوا۟ بِرَسُولِهِۦ يُؤْتِكُمْ كِفْلَيْنِ مِن رَّحْمَتِهِۦ وَيَجْعَل لَّكُمْ نُورًۭا تَمْشُونَ بِهِۦ وَيَغْفِرْ لَكُمْ ۚ وَٱللَّهُ غَفُورٌۭ رَّحِيمٌۭ', 'يأيها الذين ءامنوا اتقوا الله وءامنوا برسوله يؤتكم كفلين من رحمته ويجعل لكم نورا تمشون به ويغفر لكم  والله غفور رحيم', NULL, 541, 'local:hafs-text.json'),
  ('hafs-57-29', 'hafs', 57, 29, 'لِّئَلَّا يَعْلَمَ أَهْلُ ٱلْكِتَٰبِ أَلَّا يَقْدِرُونَ عَلَىٰ شَىْءٍۢ مِّن فَضْلِ ٱللَّهِ ۙ وَأَنَّ ٱلْفَضْلَ بِيَدِ ٱللَّهِ يُؤْتِيهِ مَن يَشَآءُ ۚ وَٱللَّهُ ذُو ٱلْفَضْلِ ٱلْعَظِيمِ', 'لئلا يعلم أهل الكتب ألا يقدرون على شىء من فضل الله  وأن الفضل بيد الله يؤتيه من يشاء  والله ذو الفضل العظيم', NULL, 541, 'local:hafs-text.json'),
  ('hafs-58-1', 'hafs', 58, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ قَدْ سَمِعَ ٱللَّهُ قَوْلَ ٱلَّتِى تُجَٰدِلُكَ فِى زَوْجِهَا وَتَشْتَكِىٓ إِلَى ٱللَّهِ وَٱللَّهُ يَسْمَعُ تَحَاوُرَكُمَآ ۚ إِنَّ ٱللَّهَ سَمِيعٌۢ بَصِيرٌ', 'بسم الله الرحمن الرحيم قد سمع الله قول التى تجدلك فى زوجها وتشتكى إلى الله والله يسمع تحاوركما  إن الله سميع بصير', NULL, 542, 'local:hafs-text.json'),
  ('hafs-58-2', 'hafs', 58, 2, 'ٱلَّذِينَ يُظَٰهِرُونَ مِنكُم مِّن نِّسَآئِهِم مَّا هُنَّ أُمَّهَٰتِهِمْ ۖ إِنْ أُمَّهَٰتُهُمْ إِلَّا ٱلَّٰٓـِٔى وَلَدْنَهُمْ ۚ وَإِنَّهُمْ لَيَقُولُونَ مُنكَرًۭا مِّنَ ٱلْقَوْلِ وَزُورًۭا ۚ وَإِنَّ ٱللَّهَ لَعَفُوٌّ غَفُورٌۭ', 'الذين يظهرون منكم من نسائهم ما هن أمهتهم  إن أمهتهم إلا الى ولدنهم  وإنهم ليقولون منكرا من القول وزورا  وإن الله لعفو غفور', NULL, 542, 'local:hafs-text.json'),
  ('hafs-58-3', 'hafs', 58, 3, 'وَٱلَّذِينَ يُظَٰهِرُونَ مِن نِّسَآئِهِمْ ثُمَّ يَعُودُونَ لِمَا قَالُوا۟ فَتَحْرِيرُ رَقَبَةٍۢ مِّن قَبْلِ أَن يَتَمَآسَّا ۚ ذَٰلِكُمْ تُوعَظُونَ بِهِۦ ۚ وَٱللَّهُ بِمَا تَعْمَلُونَ خَبِيرٌۭ', 'والذين يظهرون من نسائهم ثم يعودون لما قالوا فتحرير رقبة من قبل أن يتماسا  ذلكم توعظون به  والله بما تعملون خبير', NULL, 542, 'local:hafs-text.json'),
  ('hafs-58-4', 'hafs', 58, 4, 'فَمَن لَّمْ يَجِدْ فَصِيَامُ شَهْرَيْنِ مُتَتَابِعَيْنِ مِن قَبْلِ أَن يَتَمَآسَّا ۖ فَمَن لَّمْ يَسْتَطِعْ فَإِطْعَامُ سِتِّينَ مِسْكِينًۭا ۚ ذَٰلِكَ لِتُؤْمِنُوا۟ بِٱللَّهِ وَرَسُولِهِۦ ۚ وَتِلْكَ حُدُودُ ٱللَّهِ ۗ وَلِلْكَٰفِرِينَ عَذَابٌ أَلِيمٌ', 'فمن لم يجد فصيام شهرين متتابعين من قبل أن يتماسا  فمن لم يستطع فإطعام ستين مسكينا  ذلك لتؤمنوا بالله ورسوله  وتلك حدود الله  وللكفرين عذاب أليم', NULL, 542, 'local:hafs-text.json'),
  ('hafs-58-5', 'hafs', 58, 5, 'إِنَّ ٱلَّذِينَ يُحَآدُّونَ ٱللَّهَ وَرَسُولَهُۥ كُبِتُوا۟ كَمَا كُبِتَ ٱلَّذِينَ مِن قَبْلِهِمْ ۚ وَقَدْ أَنزَلْنَآ ءَايَٰتٍۭ بَيِّنَٰتٍۢ ۚ وَلِلْكَٰفِرِينَ عَذَابٌۭ مُّهِينٌۭ', 'إن الذين يحادون الله ورسوله كبتوا كما كبت الذين من قبلهم  وقد أنزلنا ءايت بينت  وللكفرين عذاب مهين', NULL, 542, 'local:hafs-text.json'),
  ('hafs-58-6', 'hafs', 58, 6, 'يَوْمَ يَبْعَثُهُمُ ٱللَّهُ جَمِيعًۭا فَيُنَبِّئُهُم بِمَا عَمِلُوٓا۟ ۚ أَحْصَىٰهُ ٱللَّهُ وَنَسُوهُ ۚ وَٱللَّهُ عَلَىٰ كُلِّ شَىْءٍۢ شَهِيدٌ', 'يوم يبعثهم الله جميعا فينبئهم بما عملوا  أحصىه الله ونسوه  والله على كل شىء شهيد', NULL, 542, 'local:hafs-text.json'),
  ('hafs-58-7', 'hafs', 58, 7, 'أَلَمْ تَرَ أَنَّ ٱللَّهَ يَعْلَمُ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ ۖ مَا يَكُونُ مِن نَّجْوَىٰ ثَلَٰثَةٍ إِلَّا هُوَ رَابِعُهُمْ وَلَا خَمْسَةٍ إِلَّا هُوَ سَادِسُهُمْ وَلَآ أَدْنَىٰ مِن ذَٰلِكَ وَلَآ أَكْثَرَ إِلَّا هُوَ مَعَهُمْ أَيْنَ مَا كَانُوا۟ ۖ ثُمَّ يُنَبِّئُهُم بِمَا عَمِلُوا۟ يَوْمَ ٱلْقِيَٰمَةِ ۚ إِنَّ ٱللَّهَ بِكُلِّ شَىْءٍ عَلِيمٌ', 'ألم تر أن الله يعلم ما فى السموت وما فى الأرض  ما يكون من نجوى ثلثة إلا هو رابعهم ولا خمسة إلا هو سادسهم ولا أدنى من ذلك ولا أكثر إلا هو معهم أين ما كانوا  ثم ينبئهم بما عملوا يوم القيمة  إن الله بكل شىء عليم', NULL, 543, 'local:hafs-text.json'),
  ('hafs-58-8', 'hafs', 58, 8, 'أَلَمْ تَرَ إِلَى ٱلَّذِينَ نُهُوا۟ عَنِ ٱلنَّجْوَىٰ ثُمَّ يَعُودُونَ لِمَا نُهُوا۟ عَنْهُ وَيَتَنَٰجَوْنَ بِٱلْإِثْمِ وَٱلْعُدْوَٰنِ وَمَعْصِيَتِ ٱلرَّسُولِ وَإِذَا جَآءُوكَ حَيَّوْكَ بِمَا لَمْ يُحَيِّكَ بِهِ ٱللَّهُ وَيَقُولُونَ فِىٓ أَنفُسِهِمْ لَوْلَا يُعَذِّبُنَا ٱللَّهُ بِمَا نَقُولُ ۚ حَسْبُهُمْ جَهَنَّمُ يَصْلَوْنَهَا ۖ فَبِئْسَ ٱلْمَصِيرُ', 'ألم تر إلى الذين نهوا عن النجوى ثم يعودون لما نهوا عنه ويتنجون بالإثم والعدون ومعصيت الرسول وإذا جاءوك حيوك بما لم يحيك به الله ويقولون فى أنفسهم لولا يعذبنا الله بما نقول  حسبهم جهنم يصلونها  فبئس المصير', NULL, 543, 'local:hafs-text.json'),
  ('hafs-58-9', 'hafs', 58, 9, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِذَا تَنَٰجَيْتُمْ فَلَا تَتَنَٰجَوْا۟ بِٱلْإِثْمِ وَٱلْعُدْوَٰنِ وَمَعْصِيَتِ ٱلرَّسُولِ وَتَنَٰجَوْا۟ بِٱلْبِرِّ وَٱلتَّقْوَىٰ ۖ وَٱتَّقُوا۟ ٱللَّهَ ٱلَّذِىٓ إِلَيْهِ تُحْشَرُونَ', 'يأيها الذين ءامنوا إذا تنجيتم فلا تتنجوا بالإثم والعدون ومعصيت الرسول وتنجوا بالبر والتقوى  واتقوا الله الذى إليه تحشرون', NULL, 543, 'local:hafs-text.json'),
  ('hafs-58-10', 'hafs', 58, 10, 'إِنَّمَا ٱلنَّجْوَىٰ مِنَ ٱلشَّيْطَٰنِ لِيَحْزُنَ ٱلَّذِينَ ءَامَنُوا۟ وَلَيْسَ بِضَآرِّهِمْ شَيْـًٔا إِلَّا بِإِذْنِ ٱللَّهِ ۚ وَعَلَى ٱللَّهِ فَلْيَتَوَكَّلِ ٱلْمُؤْمِنُونَ', 'إنما النجوى من الشيطن ليحزن الذين ءامنوا وليس بضارهم شيا إلا بإذن الله  وعلى الله فليتوكل المؤمنون', NULL, 543, 'local:hafs-text.json'),
  ('hafs-58-11', 'hafs', 58, 11, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِذَا قِيلَ لَكُمْ تَفَسَّحُوا۟ فِى ٱلْمَجَٰلِسِ فَٱفْسَحُوا۟ يَفْسَحِ ٱللَّهُ لَكُمْ ۖ وَإِذَا قِيلَ ٱنشُزُوا۟ فَٱنشُزُوا۟ يَرْفَعِ ٱللَّهُ ٱلَّذِينَ ءَامَنُوا۟ مِنكُمْ وَٱلَّذِينَ أُوتُوا۟ ٱلْعِلْمَ دَرَجَٰتٍۢ ۚ وَٱللَّهُ بِمَا تَعْمَلُونَ خَبِيرٌۭ', 'يأيها الذين ءامنوا إذا قيل لكم تفسحوا فى المجلس فافسحوا يفسح الله لكم  وإذا قيل انشزوا فانشزوا يرفع الله الذين ءامنوا منكم والذين أوتوا العلم درجت  والله بما تعملون خبير', NULL, 543, 'local:hafs-text.json'),
  ('hafs-58-12', 'hafs', 58, 12, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِذَا نَٰجَيْتُمُ ٱلرَّسُولَ فَقَدِّمُوا۟ بَيْنَ يَدَىْ نَجْوَىٰكُمْ صَدَقَةًۭ ۚ ذَٰلِكَ خَيْرٌۭ لَّكُمْ وَأَطْهَرُ ۚ فَإِن لَّمْ تَجِدُوا۟ فَإِنَّ ٱللَّهَ غَفُورٌۭ رَّحِيمٌ', 'يأيها الذين ءامنوا إذا نجيتم الرسول فقدموا بين يدى نجوىكم صدقة  ذلك خير لكم وأطهر  فإن لم تجدوا فإن الله غفور رحيم', NULL, 544, 'local:hafs-text.json'),
  ('hafs-58-13', 'hafs', 58, 13, 'ءَأَشْفَقْتُمْ أَن تُقَدِّمُوا۟ بَيْنَ يَدَىْ نَجْوَىٰكُمْ صَدَقَٰتٍۢ ۚ فَإِذْ لَمْ تَفْعَلُوا۟ وَتَابَ ٱللَّهُ عَلَيْكُمْ فَأَقِيمُوا۟ ٱلصَّلَوٰةَ وَءَاتُوا۟ ٱلزَّكَوٰةَ وَأَطِيعُوا۟ ٱللَّهَ وَرَسُولَهُۥ ۚ وَٱللَّهُ خَبِيرٌۢ بِمَا تَعْمَلُونَ', 'ءأشفقتم أن تقدموا بين يدى نجوىكم صدقت  فإذ لم تفعلوا وتاب الله عليكم فأقيموا الصلوة وءاتوا الزكوة وأطيعوا الله ورسوله  والله خبير بما تعملون', NULL, 544, 'local:hafs-text.json'),
  ('hafs-58-14', 'hafs', 58, 14, '۞ أَلَمْ تَرَ إِلَى ٱلَّذِينَ تَوَلَّوْا۟ قَوْمًا غَضِبَ ٱللَّهُ عَلَيْهِم مَّا هُم مِّنكُمْ وَلَا مِنْهُمْ وَيَحْلِفُونَ عَلَى ٱلْكَذِبِ وَهُمْ يَعْلَمُونَ', 'ألم تر إلى الذين تولوا قوما غضب الله عليهم ما هم منكم ولا منهم ويحلفون على الكذب وهم يعلمون', NULL, 544, 'local:hafs-text.json'),
  ('hafs-58-15', 'hafs', 58, 15, 'أَعَدَّ ٱللَّهُ لَهُمْ عَذَابًۭا شَدِيدًا ۖ إِنَّهُمْ سَآءَ مَا كَانُوا۟ يَعْمَلُونَ', 'أعد الله لهم عذابا شديدا  إنهم ساء ما كانوا يعملون', NULL, 544, 'local:hafs-text.json'),
  ('hafs-58-16', 'hafs', 58, 16, 'ٱتَّخَذُوٓا۟ أَيْمَٰنَهُمْ جُنَّةًۭ فَصَدُّوا۟ عَن سَبِيلِ ٱللَّهِ فَلَهُمْ عَذَابٌۭ مُّهِينٌۭ', 'اتخذوا أيمنهم جنة فصدوا عن سبيل الله فلهم عذاب مهين', NULL, 544, 'local:hafs-text.json'),
  ('hafs-58-17', 'hafs', 58, 17, 'لَّن تُغْنِىَ عَنْهُمْ أَمْوَٰلُهُمْ وَلَآ أَوْلَٰدُهُم مِّنَ ٱللَّهِ شَيْـًٔا ۚ أُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلنَّارِ ۖ هُمْ فِيهَا خَٰلِدُونَ', 'لن تغنى عنهم أمولهم ولا أولدهم من الله شيا  أولئك أصحب النار  هم فيها خلدون', NULL, 544, 'local:hafs-text.json'),
  ('hafs-58-18', 'hafs', 58, 18, 'يَوْمَ يَبْعَثُهُمُ ٱللَّهُ جَمِيعًۭا فَيَحْلِفُونَ لَهُۥ كَمَا يَحْلِفُونَ لَكُمْ ۖ وَيَحْسَبُونَ أَنَّهُمْ عَلَىٰ شَىْءٍ ۚ أَلَآ إِنَّهُمْ هُمُ ٱلْكَٰذِبُونَ', 'يوم يبعثهم الله جميعا فيحلفون له كما يحلفون لكم  ويحسبون أنهم على شىء  ألا إنهم هم الكذبون', NULL, 544, 'local:hafs-text.json'),
  ('hafs-58-19', 'hafs', 58, 19, 'ٱسْتَحْوَذَ عَلَيْهِمُ ٱلشَّيْطَٰنُ فَأَنسَىٰهُمْ ذِكْرَ ٱللَّهِ ۚ أُو۟لَٰٓئِكَ حِزْبُ ٱلشَّيْطَٰنِ ۚ أَلَآ إِنَّ حِزْبَ ٱلشَّيْطَٰنِ هُمُ ٱلْخَٰسِرُونَ', 'استحوذ عليهم الشيطن فأنسىهم ذكر الله  أولئك حزب الشيطن  ألا إن حزب الشيطن هم الخسرون', NULL, 544, 'local:hafs-text.json'),
  ('hafs-58-20', 'hafs', 58, 20, 'إِنَّ ٱلَّذِينَ يُحَآدُّونَ ٱللَّهَ وَرَسُولَهُۥٓ أُو۟لَٰٓئِكَ فِى ٱلْأَذَلِّينَ', 'إن الذين يحادون الله ورسوله أولئك فى الأذلين', NULL, 544, 'local:hafs-text.json'),
  ('hafs-58-21', 'hafs', 58, 21, 'كَتَبَ ٱللَّهُ لَأَغْلِبَنَّ أَنَا۠ وَرُسُلِىٓ ۚ إِنَّ ٱللَّهَ قَوِىٌّ عَزِيزٌۭ', 'كتب الله لأغلبن أنا ورسلى  إن الله قوى عزيز', NULL, 544, 'local:hafs-text.json'),
  ('hafs-58-22', 'hafs', 58, 22, 'لَّا تَجِدُ قَوْمًۭا يُؤْمِنُونَ بِٱللَّهِ وَٱلْيَوْمِ ٱلْءَاخِرِ يُوَآدُّونَ مَنْ حَآدَّ ٱللَّهَ وَرَسُولَهُۥ وَلَوْ كَانُوٓا۟ ءَابَآءَهُمْ أَوْ أَبْنَآءَهُمْ أَوْ إِخْوَٰنَهُمْ أَوْ عَشِيرَتَهُمْ ۚ أُو۟لَٰٓئِكَ كَتَبَ فِى قُلُوبِهِمُ ٱلْإِيمَٰنَ وَأَيَّدَهُم بِرُوحٍۢ مِّنْهُ ۖ وَيُدْخِلُهُمْ جَنَّٰتٍۢ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ خَٰلِدِينَ فِيهَا ۚ رَضِىَ ٱللَّهُ عَنْهُمْ وَرَضُوا۟ عَنْهُ ۚ أُو۟لَٰٓئِكَ حِزْبُ ٱللَّهِ ۚ أَلَآ إِنَّ حِزْبَ ٱللَّهِ هُمُ ٱلْمُفْلِحُونَ', 'لا تجد قوما يؤمنون بالله واليوم الءاخر يوادون من حاد الله ورسوله ولو كانوا ءاباءهم أو أبناءهم أو إخونهم أو عشيرتهم  أولئك كتب فى قلوبهم الإيمن وأيدهم بروح منه  ويدخلهم جنت تجرى من تحتها الأنهر خلدين فيها  رضى الله عنهم ورضوا عنه  أولئك حزب الله  ألا إن حزب الله هم المفلحون', NULL, 545, 'local:hafs-text.json'),
  ('hafs-59-1', 'hafs', 59, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ سَبَّحَ لِلَّهِ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ ۖ وَهُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ', 'بسم الله الرحمن الرحيم سبح لله ما فى السموت وما فى الأرض  وهو العزيز الحكيم', NULL, 545, 'local:hafs-text.json'),
  ('hafs-59-2', 'hafs', 59, 2, 'هُوَ ٱلَّذِىٓ أَخْرَجَ ٱلَّذِينَ كَفَرُوا۟ مِنْ أَهْلِ ٱلْكِتَٰبِ مِن دِيَٰرِهِمْ لِأَوَّلِ ٱلْحَشْرِ ۚ مَا ظَنَنتُمْ أَن يَخْرُجُوا۟ ۖ وَظَنُّوٓا۟ أَنَّهُم مَّانِعَتُهُمْ حُصُونُهُم مِّنَ ٱللَّهِ فَأَتَىٰهُمُ ٱللَّهُ مِنْ حَيْثُ لَمْ يَحْتَسِبُوا۟ ۖ وَقَذَفَ فِى قُلُوبِهِمُ ٱلرُّعْبَ ۚ يُخْرِبُونَ بُيُوتَهُم بِأَيْدِيهِمْ وَأَيْدِى ٱلْمُؤْمِنِينَ فَٱعْتَبِرُوا۟ يَٰٓأُو۟لِى ٱلْأَبْصَٰرِ', 'هو الذى أخرج الذين كفروا من أهل الكتب من ديرهم لأول الحشر  ما ظننتم أن يخرجوا  وظنوا أنهم مانعتهم حصونهم من الله فأتىهم الله من حيث لم يحتسبوا  وقذف فى قلوبهم الرعب  يخربون بيوتهم بأيديهم وأيدى المؤمنين فاعتبروا يأولى الأبصر', NULL, 545, 'local:hafs-text.json'),
  ('hafs-59-3', 'hafs', 59, 3, 'وَلَوْلَآ أَن كَتَبَ ٱللَّهُ عَلَيْهِمُ ٱلْجَلَآءَ لَعَذَّبَهُمْ فِى ٱلدُّنْيَا ۖ وَلَهُمْ فِى ٱلْءَاخِرَةِ عَذَابُ ٱلنَّارِ', 'ولولا أن كتب الله عليهم الجلاء لعذبهم فى الدنيا  ولهم فى الءاخرة عذاب النار', NULL, 545, 'local:hafs-text.json'),
  ('hafs-59-4', 'hafs', 59, 4, 'ذَٰلِكَ بِأَنَّهُمْ شَآقُّوا۟ ٱللَّهَ وَرَسُولَهُۥ ۖ وَمَن يُشَآقِّ ٱللَّهَ فَإِنَّ ٱللَّهَ شَدِيدُ ٱلْعِقَابِ', 'ذلك بأنهم شاقوا الله ورسوله  ومن يشاق الله فإن الله شديد العقاب', NULL, 546, 'local:hafs-text.json'),
  ('hafs-59-5', 'hafs', 59, 5, 'مَا قَطَعْتُم مِّن لِّينَةٍ أَوْ تَرَكْتُمُوهَا قَآئِمَةً عَلَىٰٓ أُصُولِهَا فَبِإِذْنِ ٱللَّهِ وَلِيُخْزِىَ ٱلْفَٰسِقِينَ', 'ما قطعتم من لينة أو تركتموها قائمة على أصولها فبإذن الله وليخزى الفسقين', NULL, 546, 'local:hafs-text.json'),
  ('hafs-59-6', 'hafs', 59, 6, 'وَمَآ أَفَآءَ ٱللَّهُ عَلَىٰ رَسُولِهِۦ مِنْهُمْ فَمَآ أَوْجَفْتُمْ عَلَيْهِ مِنْ خَيْلٍۢ وَلَا رِكَابٍۢ وَلَٰكِنَّ ٱللَّهَ يُسَلِّطُ رُسُلَهُۥ عَلَىٰ مَن يَشَآءُ ۚ وَٱللَّهُ عَلَىٰ كُلِّ شَىْءٍۢ قَدِيرٌۭ', 'وما أفاء الله على رسوله منهم فما أوجفتم عليه من خيل ولا ركاب ولكن الله يسلط رسله على من يشاء  والله على كل شىء قدير', NULL, 546, 'local:hafs-text.json'),
  ('hafs-59-7', 'hafs', 59, 7, 'مَّآ أَفَآءَ ٱللَّهُ عَلَىٰ رَسُولِهِۦ مِنْ أَهْلِ ٱلْقُرَىٰ فَلِلَّهِ وَلِلرَّسُولِ وَلِذِى ٱلْقُرْبَىٰ وَٱلْيَتَٰمَىٰ وَٱلْمَسَٰكِينِ وَٱبْنِ ٱلسَّبِيلِ كَىْ لَا يَكُونَ دُولَةًۢ بَيْنَ ٱلْأَغْنِيَآءِ مِنكُمْ ۚ وَمَآ ءَاتَىٰكُمُ ٱلرَّسُولُ فَخُذُوهُ وَمَا نَهَىٰكُمْ عَنْهُ فَٱنتَهُوا۟ ۚ وَٱتَّقُوا۟ ٱللَّهَ ۖ إِنَّ ٱللَّهَ شَدِيدُ ٱلْعِقَابِ', 'ما أفاء الله على رسوله من أهل القرى فلله وللرسول ولذى القربى واليتمى والمسكين وابن السبيل كى لا يكون دولة بين الأغنياء منكم  وما ءاتىكم الرسول فخذوه وما نهىكم عنه فانتهوا  واتقوا الله  إن الله شديد العقاب', NULL, 546, 'local:hafs-text.json'),
  ('hafs-59-8', 'hafs', 59, 8, 'لِلْفُقَرَآءِ ٱلْمُهَٰجِرِينَ ٱلَّذِينَ أُخْرِجُوا۟ مِن دِيَٰرِهِمْ وَأَمْوَٰلِهِمْ يَبْتَغُونَ فَضْلًۭا مِّنَ ٱللَّهِ وَرِضْوَٰنًۭا وَيَنصُرُونَ ٱللَّهَ وَرَسُولَهُۥٓ ۚ أُو۟لَٰٓئِكَ هُمُ ٱلصَّٰدِقُونَ', 'للفقراء المهجرين الذين أخرجوا من ديرهم وأمولهم يبتغون فضلا من الله ورضونا وينصرون الله ورسوله  أولئك هم الصدقون', NULL, 546, 'local:hafs-text.json'),
  ('hafs-59-9', 'hafs', 59, 9, 'وَٱلَّذِينَ تَبَوَّءُو ٱلدَّارَ وَٱلْإِيمَٰنَ مِن قَبْلِهِمْ يُحِبُّونَ مَنْ هَاجَرَ إِلَيْهِمْ وَلَا يَجِدُونَ فِى صُدُورِهِمْ حَاجَةًۭ مِّمَّآ أُوتُوا۟ وَيُؤْثِرُونَ عَلَىٰٓ أَنفُسِهِمْ وَلَوْ كَانَ بِهِمْ خَصَاصَةٌۭ ۚ وَمَن يُوقَ شُحَّ نَفْسِهِۦ فَأُو۟لَٰٓئِكَ هُمُ ٱلْمُفْلِحُونَ', 'والذين تبوءو الدار والإيمن من قبلهم يحبون من هاجر إليهم ولا يجدون فى صدورهم حاجة مما أوتوا ويؤثرون على أنفسهم ولو كان بهم خصاصة  ومن يوق شح نفسه فأولئك هم المفلحون', NULL, 546, 'local:hafs-text.json'),
  ('hafs-59-10', 'hafs', 59, 10, 'وَٱلَّذِينَ جَآءُو مِنۢ بَعْدِهِمْ يَقُولُونَ رَبَّنَا ٱغْفِرْ لَنَا وَلِإِخْوَٰنِنَا ٱلَّذِينَ سَبَقُونَا بِٱلْإِيمَٰنِ وَلَا تَجْعَلْ فِى قُلُوبِنَا غِلًّۭا لِّلَّذِينَ ءَامَنُوا۟ رَبَّنَآ إِنَّكَ رَءُوفٌۭ رَّحِيمٌ', 'والذين جاءو من بعدهم يقولون ربنا اغفر لنا ولإخوننا الذين سبقونا بالإيمن ولا تجعل فى قلوبنا غلا للذين ءامنوا ربنا إنك رءوف رحيم', NULL, 547, 'local:hafs-text.json'),
  ('hafs-59-11', 'hafs', 59, 11, '۞ أَلَمْ تَرَ إِلَى ٱلَّذِينَ نَافَقُوا۟ يَقُولُونَ لِإِخْوَٰنِهِمُ ٱلَّذِينَ كَفَرُوا۟ مِنْ أَهْلِ ٱلْكِتَٰبِ لَئِنْ أُخْرِجْتُمْ لَنَخْرُجَنَّ مَعَكُمْ وَلَا نُطِيعُ فِيكُمْ أَحَدًا أَبَدًۭا وَإِن قُوتِلْتُمْ لَنَنصُرَنَّكُمْ وَٱللَّهُ يَشْهَدُ إِنَّهُمْ لَكَٰذِبُونَ', 'ألم تر إلى الذين نافقوا يقولون لإخونهم الذين كفروا من أهل الكتب لئن أخرجتم لنخرجن معكم ولا نطيع فيكم أحدا أبدا وإن قوتلتم لننصرنكم والله يشهد إنهم لكذبون', NULL, 547, 'local:hafs-text.json'),
  ('hafs-59-12', 'hafs', 59, 12, 'لَئِنْ أُخْرِجُوا۟ لَا يَخْرُجُونَ مَعَهُمْ وَلَئِن قُوتِلُوا۟ لَا يَنصُرُونَهُمْ وَلَئِن نَّصَرُوهُمْ لَيُوَلُّنَّ ٱلْأَدْبَٰرَ ثُمَّ لَا يُنصَرُونَ', 'لئن أخرجوا لا يخرجون معهم ولئن قوتلوا لا ينصرونهم ولئن نصروهم ليولن الأدبر ثم لا ينصرون', NULL, 547, 'local:hafs-text.json'),
  ('hafs-59-13', 'hafs', 59, 13, 'لَأَنتُمْ أَشَدُّ رَهْبَةًۭ فِى صُدُورِهِم مِّنَ ٱللَّهِ ۚ ذَٰلِكَ بِأَنَّهُمْ قَوْمٌۭ لَّا يَفْقَهُونَ', 'لأنتم أشد رهبة فى صدورهم من الله  ذلك بأنهم قوم لا يفقهون', NULL, 547, 'local:hafs-text.json'),
  ('hafs-59-14', 'hafs', 59, 14, 'لَا يُقَٰتِلُونَكُمْ جَمِيعًا إِلَّا فِى قُرًۭى مُّحَصَّنَةٍ أَوْ مِن وَرَآءِ جُدُرٍۭ ۚ بَأْسُهُم بَيْنَهُمْ شَدِيدٌۭ ۚ تَحْسَبُهُمْ جَمِيعًۭا وَقُلُوبُهُمْ شَتَّىٰ ۚ ذَٰلِكَ بِأَنَّهُمْ قَوْمٌۭ لَّا يَعْقِلُونَ', 'لا يقتلونكم جميعا إلا فى قرى محصنة أو من وراء جدر  بأسهم بينهم شديد  تحسبهم جميعا وقلوبهم شتى  ذلك بأنهم قوم لا يعقلون', NULL, 547, 'local:hafs-text.json'),
  ('hafs-59-15', 'hafs', 59, 15, 'كَمَثَلِ ٱلَّذِينَ مِن قَبْلِهِمْ قَرِيبًۭا ۖ ذَاقُوا۟ وَبَالَ أَمْرِهِمْ وَلَهُمْ عَذَابٌ أَلِيمٌۭ', 'كمثل الذين من قبلهم قريبا  ذاقوا وبال أمرهم ولهم عذاب أليم', NULL, 547, 'local:hafs-text.json'),
  ('hafs-59-16', 'hafs', 59, 16, 'كَمَثَلِ ٱلشَّيْطَٰنِ إِذْ قَالَ لِلْإِنسَٰنِ ٱكْفُرْ فَلَمَّا كَفَرَ قَالَ إِنِّى بَرِىٓءٌۭ مِّنكَ إِنِّىٓ أَخَافُ ٱللَّهَ رَبَّ ٱلْعَٰلَمِينَ', 'كمثل الشيطن إذ قال للإنسن اكفر فلما كفر قال إنى برىء منك إنى أخاف الله رب العلمين', NULL, 547, 'local:hafs-text.json'),
  ('hafs-59-17', 'hafs', 59, 17, 'فَكَانَ عَٰقِبَتَهُمَآ أَنَّهُمَا فِى ٱلنَّارِ خَٰلِدَيْنِ فِيهَا ۚ وَذَٰلِكَ جَزَٰٓؤُا۟ ٱلظَّٰلِمِينَ', 'فكان عقبتهما أنهما فى النار خلدين فيها  وذلك جزؤا الظلمين', NULL, 548, 'local:hafs-text.json'),
  ('hafs-59-18', 'hafs', 59, 18, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱتَّقُوا۟ ٱللَّهَ وَلْتَنظُرْ نَفْسٌۭ مَّا قَدَّمَتْ لِغَدٍۢ ۖ وَٱتَّقُوا۟ ٱللَّهَ ۚ إِنَّ ٱللَّهَ خَبِيرٌۢ بِمَا تَعْمَلُونَ', 'يأيها الذين ءامنوا اتقوا الله ولتنظر نفس ما قدمت لغد  واتقوا الله  إن الله خبير بما تعملون', NULL, 548, 'local:hafs-text.json'),
  ('hafs-59-19', 'hafs', 59, 19, 'وَلَا تَكُونُوا۟ كَٱلَّذِينَ نَسُوا۟ ٱللَّهَ فَأَنسَىٰهُمْ أَنفُسَهُمْ ۚ أُو۟لَٰٓئِكَ هُمُ ٱلْفَٰسِقُونَ', 'ولا تكونوا كالذين نسوا الله فأنسىهم أنفسهم  أولئك هم الفسقون', NULL, 548, 'local:hafs-text.json'),
  ('hafs-59-20', 'hafs', 59, 20, 'لَا يَسْتَوِىٓ أَصْحَٰبُ ٱلنَّارِ وَأَصْحَٰبُ ٱلْجَنَّةِ ۚ أَصْحَٰبُ ٱلْجَنَّةِ هُمُ ٱلْفَآئِزُونَ', 'لا يستوى أصحب النار وأصحب الجنة  أصحب الجنة هم الفائزون', NULL, 548, 'local:hafs-text.json'),
  ('hafs-59-21', 'hafs', 59, 21, 'لَوْ أَنزَلْنَا هَٰذَا ٱلْقُرْءَانَ عَلَىٰ جَبَلٍۢ لَّرَأَيْتَهُۥ خَٰشِعًۭا مُّتَصَدِّعًۭا مِّنْ خَشْيَةِ ٱللَّهِ ۚ وَتِلْكَ ٱلْأَمْثَٰلُ نَضْرِبُهَا لِلنَّاسِ لَعَلَّهُمْ يَتَفَكَّرُونَ', 'لو أنزلنا هذا القرءان على جبل لرأيته خشعا متصدعا من خشية الله  وتلك الأمثل نضربها للناس لعلهم يتفكرون', NULL, 548, 'local:hafs-text.json'),
  ('hafs-59-22', 'hafs', 59, 22, 'هُوَ ٱللَّهُ ٱلَّذِى لَآ إِلَٰهَ إِلَّا هُوَ ۖ عَٰلِمُ ٱلْغَيْبِ وَٱلشَّهَٰدَةِ ۖ هُوَ ٱلرَّحْمَٰنُ ٱلرَّحِيمُ', 'هو الله الذى لا إله إلا هو  علم الغيب والشهدة  هو الرحمن الرحيم', NULL, 548, 'local:hafs-text.json'),
  ('hafs-59-23', 'hafs', 59, 23, 'هُوَ ٱللَّهُ ٱلَّذِى لَآ إِلَٰهَ إِلَّا هُوَ ٱلْمَلِكُ ٱلْقُدُّوسُ ٱلسَّلَٰمُ ٱلْمُؤْمِنُ ٱلْمُهَيْمِنُ ٱلْعَزِيزُ ٱلْجَبَّارُ ٱلْمُتَكَبِّرُ ۚ سُبْحَٰنَ ٱللَّهِ عَمَّا يُشْرِكُونَ', 'هو الله الذى لا إله إلا هو الملك القدوس السلم المؤمن المهيمن العزيز الجبار المتكبر  سبحن الله عما يشركون', NULL, 548, 'local:hafs-text.json'),
  ('hafs-59-24', 'hafs', 59, 24, 'هُوَ ٱللَّهُ ٱلْخَٰلِقُ ٱلْبَارِئُ ٱلْمُصَوِّرُ ۖ لَهُ ٱلْأَسْمَآءُ ٱلْحُسْنَىٰ ۚ يُسَبِّحُ لَهُۥ مَا فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ ۖ وَهُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ', 'هو الله الخلق البارئ المصور  له الأسماء الحسنى  يسبح له ما فى السموت والأرض  وهو العزيز الحكيم', NULL, 548, 'local:hafs-text.json'),
  ('hafs-60-1', 'hafs', 60, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَتَّخِذُوا۟ عَدُوِّى وَعَدُوَّكُمْ أَوْلِيَآءَ تُلْقُونَ إِلَيْهِم بِٱلْمَوَدَّةِ وَقَدْ كَفَرُوا۟ بِمَا جَآءَكُم مِّنَ ٱلْحَقِّ يُخْرِجُونَ ٱلرَّسُولَ وَإِيَّاكُمْ ۙ أَن تُؤْمِنُوا۟ بِٱللَّهِ رَبِّكُمْ إِن كُنتُمْ خَرَجْتُمْ جِهَٰدًۭا فِى سَبِيلِى وَٱبْتِغَآءَ مَرْضَاتِى ۚ تُسِرُّونَ إِلَيْهِم بِٱلْمَوَدَّةِ وَأَنَا۠ أَعْلَمُ بِمَآ أَخْفَيْتُمْ وَمَآ أَعْلَنتُمْ ۚ وَمَن يَفْعَلْهُ مِنكُمْ فَقَدْ ضَلَّ سَوَآءَ ٱلسَّبِيلِ', 'بسم الله الرحمن الرحيم يأيها الذين ءامنوا لا تتخذوا عدوى وعدوكم أولياء تلقون إليهم بالمودة وقد كفروا بما جاءكم من الحق يخرجون الرسول وإياكم  أن تؤمنوا بالله ربكم إن كنتم خرجتم جهدا فى سبيلى وابتغاء مرضاتى  تسرون إليهم بالمودة وأنا أعلم بما أخفيتم وما أعلنتم  ومن يفعله منكم فقد ضل سواء السبيل', NULL, 549, 'local:hafs-text.json'),
  ('hafs-60-2', 'hafs', 60, 2, 'إِن يَثْقَفُوكُمْ يَكُونُوا۟ لَكُمْ أَعْدَآءًۭ وَيَبْسُطُوٓا۟ إِلَيْكُمْ أَيْدِيَهُمْ وَأَلْسِنَتَهُم بِٱلسُّوٓءِ وَوَدُّوا۟ لَوْ تَكْفُرُونَ', 'إن يثقفوكم يكونوا لكم أعداء ويبسطوا إليكم أيديهم وألسنتهم بالسوء وودوا لو تكفرون', NULL, 549, 'local:hafs-text.json'),
  ('hafs-60-3', 'hafs', 60, 3, 'لَن تَنفَعَكُمْ أَرْحَامُكُمْ وَلَآ أَوْلَٰدُكُمْ ۚ يَوْمَ ٱلْقِيَٰمَةِ يَفْصِلُ بَيْنَكُمْ ۚ وَٱللَّهُ بِمَا تَعْمَلُونَ بَصِيرٌۭ', 'لن تنفعكم أرحامكم ولا أولدكم  يوم القيمة يفصل بينكم  والله بما تعملون بصير', NULL, 549, 'local:hafs-text.json'),
  ('hafs-60-4', 'hafs', 60, 4, 'قَدْ كَانَتْ لَكُمْ أُسْوَةٌ حَسَنَةٌۭ فِىٓ إِبْرَٰهِيمَ وَٱلَّذِينَ مَعَهُۥٓ إِذْ قَالُوا۟ لِقَوْمِهِمْ إِنَّا بُرَءَٰٓؤُا۟ مِنكُمْ وَمِمَّا تَعْبُدُونَ مِن دُونِ ٱللَّهِ كَفَرْنَا بِكُمْ وَبَدَا بَيْنَنَا وَبَيْنَكُمُ ٱلْعَدَٰوَةُ وَٱلْبَغْضَآءُ أَبَدًا حَتَّىٰ تُؤْمِنُوا۟ بِٱللَّهِ وَحْدَهُۥٓ إِلَّا قَوْلَ إِبْرَٰهِيمَ لِأَبِيهِ لَأَسْتَغْفِرَنَّ لَكَ وَمَآ أَمْلِكُ لَكَ مِنَ ٱللَّهِ مِن شَىْءٍۢ ۖ رَّبَّنَا عَلَيْكَ تَوَكَّلْنَا وَإِلَيْكَ أَنَبْنَا وَإِلَيْكَ ٱلْمَصِيرُ', 'قد كانت لكم أسوة حسنة فى إبرهيم والذين معه إذ قالوا لقومهم إنا برءؤا منكم ومما تعبدون من دون الله كفرنا بكم وبدا بيننا وبينكم العدوة والبغضاء أبدا حتى تؤمنوا بالله وحده إلا قول إبرهيم لأبيه لأستغفرن لك وما أملك لك من الله من شىء  ربنا عليك توكلنا وإليك أنبنا وإليك المصير', NULL, 549, 'local:hafs-text.json'),
  ('hafs-60-5', 'hafs', 60, 5, 'رَبَّنَا لَا تَجْعَلْنَا فِتْنَةًۭ لِّلَّذِينَ كَفَرُوا۟ وَٱغْفِرْ لَنَا رَبَّنَآ ۖ إِنَّكَ أَنتَ ٱلْعَزِيزُ ٱلْحَكِيمُ', 'ربنا لا تجعلنا فتنة للذين كفروا واغفر لنا ربنا  إنك أنت العزيز الحكيم', NULL, 549, 'local:hafs-text.json'),
  ('hafs-60-6', 'hafs', 60, 6, 'لَقَدْ كَانَ لَكُمْ فِيهِمْ أُسْوَةٌ حَسَنَةٌۭ لِّمَن كَانَ يَرْجُوا۟ ٱللَّهَ وَٱلْيَوْمَ ٱلْءَاخِرَ ۚ وَمَن يَتَوَلَّ فَإِنَّ ٱللَّهَ هُوَ ٱلْغَنِىُّ ٱلْحَمِيدُ', 'لقد كان لكم فيهم أسوة حسنة لمن كان يرجوا الله واليوم الءاخر  ومن يتول فإن الله هو الغنى الحميد', NULL, 550, 'local:hafs-text.json'),
  ('hafs-60-7', 'hafs', 60, 7, '۞ عَسَى ٱللَّهُ أَن يَجْعَلَ بَيْنَكُمْ وَبَيْنَ ٱلَّذِينَ عَادَيْتُم مِّنْهُم مَّوَدَّةًۭ ۚ وَٱللَّهُ قَدِيرٌۭ ۚ وَٱللَّهُ غَفُورٌۭ رَّحِيمٌۭ', 'عسى الله أن يجعل بينكم وبين الذين عاديتم منهم مودة  والله قدير  والله غفور رحيم', NULL, 550, 'local:hafs-text.json'),
  ('hafs-60-8', 'hafs', 60, 8, 'لَّا يَنْهَىٰكُمُ ٱللَّهُ عَنِ ٱلَّذِينَ لَمْ يُقَٰتِلُوكُمْ فِى ٱلدِّينِ وَلَمْ يُخْرِجُوكُم مِّن دِيَٰرِكُمْ أَن تَبَرُّوهُمْ وَتُقْسِطُوٓا۟ إِلَيْهِمْ ۚ إِنَّ ٱللَّهَ يُحِبُّ ٱلْمُقْسِطِينَ', 'لا ينهىكم الله عن الذين لم يقتلوكم فى الدين ولم يخرجوكم من ديركم أن تبروهم وتقسطوا إليهم  إن الله يحب المقسطين', NULL, 550, 'local:hafs-text.json'),
  ('hafs-60-9', 'hafs', 60, 9, 'إِنَّمَا يَنْهَىٰكُمُ ٱللَّهُ عَنِ ٱلَّذِينَ قَٰتَلُوكُمْ فِى ٱلدِّينِ وَأَخْرَجُوكُم مِّن دِيَٰرِكُمْ وَظَٰهَرُوا۟ عَلَىٰٓ إِخْرَاجِكُمْ أَن تَوَلَّوْهُمْ ۚ وَمَن يَتَوَلَّهُمْ فَأُو۟لَٰٓئِكَ هُمُ ٱلظَّٰلِمُونَ', 'إنما ينهىكم الله عن الذين قتلوكم فى الدين وأخرجوكم من ديركم وظهروا على إخراجكم أن تولوهم  ومن يتولهم فأولئك هم الظلمون', NULL, 550, 'local:hafs-text.json'),
  ('hafs-60-10', 'hafs', 60, 10, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِذَا جَآءَكُمُ ٱلْمُؤْمِنَٰتُ مُهَٰجِرَٰتٍۢ فَٱمْتَحِنُوهُنَّ ۖ ٱللَّهُ أَعْلَمُ بِإِيمَٰنِهِنَّ ۖ فَإِنْ عَلِمْتُمُوهُنَّ مُؤْمِنَٰتٍۢ فَلَا تَرْجِعُوهُنَّ إِلَى ٱلْكُفَّارِ ۖ لَا هُنَّ حِلٌّۭ لَّهُمْ وَلَا هُمْ يَحِلُّونَ لَهُنَّ ۖ وَءَاتُوهُم مَّآ أَنفَقُوا۟ ۚ وَلَا جُنَاحَ عَلَيْكُمْ أَن تَنكِحُوهُنَّ إِذَآ ءَاتَيْتُمُوهُنَّ أُجُورَهُنَّ ۚ وَلَا تُمْسِكُوا۟ بِعِصَمِ ٱلْكَوَافِرِ وَسْـَٔلُوا۟ مَآ أَنفَقْتُمْ وَلْيَسْـَٔلُوا۟ مَآ أَنفَقُوا۟ ۚ ذَٰلِكُمْ حُكْمُ ٱللَّهِ ۖ يَحْكُمُ بَيْنَكُمْ ۚ وَٱللَّهُ عَلِيمٌ حَكِيمٌۭ', 'يأيها الذين ءامنوا إذا جاءكم المؤمنت مهجرت فامتحنوهن  الله أعلم بإيمنهن  فإن علمتموهن مؤمنت فلا ترجعوهن إلى الكفار  لا هن حل لهم ولا هم يحلون لهن  وءاتوهم ما أنفقوا  ولا جناح عليكم أن تنكحوهن إذا ءاتيتموهن أجورهن  ولا تمسكوا بعصم الكوافر وسلوا ما أنفقتم وليسلوا ما أنفقوا  ذلكم حكم الله  يحكم بينكم  والله عليم حكيم', NULL, 550, 'local:hafs-text.json'),
  ('hafs-60-11', 'hafs', 60, 11, 'وَإِن فَاتَكُمْ شَىْءٌۭ مِّنْ أَزْوَٰجِكُمْ إِلَى ٱلْكُفَّارِ فَعَاقَبْتُمْ فَـَٔاتُوا۟ ٱلَّذِينَ ذَهَبَتْ أَزْوَٰجُهُم مِّثْلَ مَآ أَنفَقُوا۟ ۚ وَٱتَّقُوا۟ ٱللَّهَ ٱلَّذِىٓ أَنتُم بِهِۦ مُؤْمِنُونَ', 'وإن فاتكم شىء من أزوجكم إلى الكفار فعاقبتم فاتوا الذين ذهبت أزوجهم مثل ما أنفقوا  واتقوا الله الذى أنتم به مؤمنون', NULL, 550, 'local:hafs-text.json'),
  ('hafs-60-12', 'hafs', 60, 12, 'يَٰٓأَيُّهَا ٱلنَّبِىُّ إِذَا جَآءَكَ ٱلْمُؤْمِنَٰتُ يُبَايِعْنَكَ عَلَىٰٓ أَن لَّا يُشْرِكْنَ بِٱللَّهِ شَيْـًۭٔا وَلَا يَسْرِقْنَ وَلَا يَزْنِينَ وَلَا يَقْتُلْنَ أَوْلَٰدَهُنَّ وَلَا يَأْتِينَ بِبُهْتَٰنٍۢ يَفْتَرِينَهُۥ بَيْنَ أَيْدِيهِنَّ وَأَرْجُلِهِنَّ وَلَا يَعْصِينَكَ فِى مَعْرُوفٍۢ ۙ فَبَايِعْهُنَّ وَٱسْتَغْفِرْ لَهُنَّ ٱللَّهَ ۖ إِنَّ ٱللَّهَ غَفُورٌۭ رَّحِيمٌۭ', 'يأيها النبى إذا جاءك المؤمنت يبايعنك على أن لا يشركن بالله شيا ولا يسرقن ولا يزنين ولا يقتلن أولدهن ولا يأتين ببهتن يفترينه بين أيديهن وأرجلهن ولا يعصينك فى معروف  فبايعهن واستغفر لهن الله  إن الله غفور رحيم', NULL, 551, 'local:hafs-text.json'),
  ('hafs-60-13', 'hafs', 60, 13, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَتَوَلَّوْا۟ قَوْمًا غَضِبَ ٱللَّهُ عَلَيْهِمْ قَدْ يَئِسُوا۟ مِنَ ٱلْءَاخِرَةِ كَمَا يَئِسَ ٱلْكُفَّارُ مِنْ أَصْحَٰبِ ٱلْقُبُورِ', 'يأيها الذين ءامنوا لا تتولوا قوما غضب الله عليهم قد يئسوا من الءاخرة كما يئس الكفار من أصحب القبور', NULL, 551, 'local:hafs-text.json'),
  ('hafs-61-1', 'hafs', 61, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ سَبَّحَ لِلَّهِ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ ۖ وَهُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ', 'بسم الله الرحمن الرحيم سبح لله ما فى السموت وما فى الأرض  وهو العزيز الحكيم', NULL, 551, 'local:hafs-text.json'),
  ('hafs-61-2', 'hafs', 61, 2, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لِمَ تَقُولُونَ مَا لَا تَفْعَلُونَ', 'يأيها الذين ءامنوا لم تقولون ما لا تفعلون', NULL, 551, 'local:hafs-text.json'),
  ('hafs-61-3', 'hafs', 61, 3, 'كَبُرَ مَقْتًا عِندَ ٱللَّهِ أَن تَقُولُوا۟ مَا لَا تَفْعَلُونَ', 'كبر مقتا عند الله أن تقولوا ما لا تفعلون', NULL, 551, 'local:hafs-text.json'),
  ('hafs-61-4', 'hafs', 61, 4, 'إِنَّ ٱللَّهَ يُحِبُّ ٱلَّذِينَ يُقَٰتِلُونَ فِى سَبِيلِهِۦ صَفًّۭا كَأَنَّهُم بُنْيَٰنٌۭ مَّرْصُوصٌۭ', 'إن الله يحب الذين يقتلون فى سبيله صفا كأنهم بنين مرصوص', NULL, 551, 'local:hafs-text.json'),
  ('hafs-61-5', 'hafs', 61, 5, 'وَإِذْ قَالَ مُوسَىٰ لِقَوْمِهِۦ يَٰقَوْمِ لِمَ تُؤْذُونَنِى وَقَد تَّعْلَمُونَ أَنِّى رَسُولُ ٱللَّهِ إِلَيْكُمْ ۖ فَلَمَّا زَاغُوٓا۟ أَزَاغَ ٱللَّهُ قُلُوبَهُمْ ۚ وَٱللَّهُ لَا يَهْدِى ٱلْقَوْمَ ٱلْفَٰسِقِينَ', 'وإذ قال موسى لقومه يقوم لم تؤذوننى وقد تعلمون أنى رسول الله إليكم  فلما زاغوا أزاغ الله قلوبهم  والله لا يهدى القوم الفسقين', NULL, 551, 'local:hafs-text.json'),
  ('hafs-61-6', 'hafs', 61, 6, 'وَإِذْ قَالَ عِيسَى ٱبْنُ مَرْيَمَ يَٰبَنِىٓ إِسْرَٰٓءِيلَ إِنِّى رَسُولُ ٱللَّهِ إِلَيْكُم مُّصَدِّقًۭا لِّمَا بَيْنَ يَدَىَّ مِنَ ٱلتَّوْرَىٰةِ وَمُبَشِّرًۢا بِرَسُولٍۢ يَأْتِى مِنۢ بَعْدِى ٱسْمُهُۥٓ أَحْمَدُ ۖ فَلَمَّا جَآءَهُم بِٱلْبَيِّنَٰتِ قَالُوا۟ هَٰذَا سِحْرٌۭ مُّبِينٌۭ', 'وإذ قال عيسى ابن مريم يبنى إسرءيل إنى رسول الله إليكم مصدقا لما بين يدى من التورىة ومبشرا برسول يأتى من بعدى اسمه أحمد  فلما جاءهم بالبينت قالوا هذا سحر مبين', NULL, 552, 'local:hafs-text.json'),
  ('hafs-61-7', 'hafs', 61, 7, 'وَمَنْ أَظْلَمُ مِمَّنِ ٱفْتَرَىٰ عَلَى ٱللَّهِ ٱلْكَذِبَ وَهُوَ يُدْعَىٰٓ إِلَى ٱلْإِسْلَٰمِ ۚ وَٱللَّهُ لَا يَهْدِى ٱلْقَوْمَ ٱلظَّٰلِمِينَ', 'ومن أظلم ممن افترى على الله الكذب وهو يدعى إلى الإسلم  والله لا يهدى القوم الظلمين', NULL, 552, 'local:hafs-text.json'),
  ('hafs-61-8', 'hafs', 61, 8, 'يُرِيدُونَ لِيُطْفِـُٔوا۟ نُورَ ٱللَّهِ بِأَفْوَٰهِهِمْ وَٱللَّهُ مُتِمُّ نُورِهِۦ وَلَوْ كَرِهَ ٱلْكَٰفِرُونَ', 'يريدون ليطفوا نور الله بأفوههم والله متم نوره ولو كره الكفرون', NULL, 552, 'local:hafs-text.json'),
  ('hafs-61-9', 'hafs', 61, 9, 'هُوَ ٱلَّذِىٓ أَرْسَلَ رَسُولَهُۥ بِٱلْهُدَىٰ وَدِينِ ٱلْحَقِّ لِيُظْهِرَهُۥ عَلَى ٱلدِّينِ كُلِّهِۦ وَلَوْ كَرِهَ ٱلْمُشْرِكُونَ', 'هو الذى أرسل رسوله بالهدى ودين الحق ليظهره على الدين كله ولو كره المشركون', NULL, 552, 'local:hafs-text.json'),
  ('hafs-61-10', 'hafs', 61, 10, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ هَلْ أَدُلُّكُمْ عَلَىٰ تِجَٰرَةٍۢ تُنجِيكُم مِّنْ عَذَابٍ أَلِيمٍۢ', 'يأيها الذين ءامنوا هل أدلكم على تجرة تنجيكم من عذاب أليم', NULL, 552, 'local:hafs-text.json'),
  ('hafs-61-11', 'hafs', 61, 11, 'تُؤْمِنُونَ بِٱللَّهِ وَرَسُولِهِۦ وَتُجَٰهِدُونَ فِى سَبِيلِ ٱللَّهِ بِأَمْوَٰلِكُمْ وَأَنفُسِكُمْ ۚ ذَٰلِكُمْ خَيْرٌۭ لَّكُمْ إِن كُنتُمْ تَعْلَمُونَ', 'تؤمنون بالله ورسوله وتجهدون فى سبيل الله بأمولكم وأنفسكم  ذلكم خير لكم إن كنتم تعلمون', NULL, 552, 'local:hafs-text.json'),
  ('hafs-61-12', 'hafs', 61, 12, 'يَغْفِرْ لَكُمْ ذُنُوبَكُمْ وَيُدْخِلْكُمْ جَنَّٰتٍۢ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ وَمَسَٰكِنَ طَيِّبَةًۭ فِى جَنَّٰتِ عَدْنٍۢ ۚ ذَٰلِكَ ٱلْفَوْزُ ٱلْعَظِيمُ', 'يغفر لكم ذنوبكم ويدخلكم جنت تجرى من تحتها الأنهر ومسكن طيبة فى جنت عدن  ذلك الفوز العظيم', NULL, 552, 'local:hafs-text.json'),
  ('hafs-61-13', 'hafs', 61, 13, 'وَأُخْرَىٰ تُحِبُّونَهَا ۖ نَصْرٌۭ مِّنَ ٱللَّهِ وَفَتْحٌۭ قَرِيبٌۭ ۗ وَبَشِّرِ ٱلْمُؤْمِنِينَ', 'وأخرى تحبونها  نصر من الله وفتح قريب  وبشر المؤمنين', NULL, 552, 'local:hafs-text.json'),
  ('hafs-61-14', 'hafs', 61, 14, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ كُونُوٓا۟ أَنصَارَ ٱللَّهِ كَمَا قَالَ عِيسَى ٱبْنُ مَرْيَمَ لِلْحَوَارِيِّۦنَ مَنْ أَنصَارِىٓ إِلَى ٱللَّهِ ۖ قَالَ ٱلْحَوَارِيُّونَ نَحْنُ أَنصَارُ ٱللَّهِ ۖ فَـَٔامَنَت طَّآئِفَةٌۭ مِّنۢ بَنِىٓ إِسْرَٰٓءِيلَ وَكَفَرَت طَّآئِفَةٌۭ ۖ فَأَيَّدْنَا ٱلَّذِينَ ءَامَنُوا۟ عَلَىٰ عَدُوِّهِمْ فَأَصْبَحُوا۟ ظَٰهِرِينَ', 'يأيها الذين ءامنوا كونوا أنصار الله كما قال عيسى ابن مريم للحوارين من أنصارى إلى الله  قال الحواريون نحن أنصار الله  فامنت طائفة من بنى إسرءيل وكفرت طائفة  فأيدنا الذين ءامنوا على عدوهم فأصبحوا ظهرين', NULL, 552, 'local:hafs-text.json'),
  ('hafs-62-1', 'hafs', 62, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ يُسَبِّحُ لِلَّهِ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ ٱلْمَلِكِ ٱلْقُدُّوسِ ٱلْعَزِيزِ ٱلْحَكِيمِ', 'بسم الله الرحمن الرحيم يسبح لله ما فى السموت وما فى الأرض الملك القدوس العزيز الحكيم', NULL, 553, 'local:hafs-text.json'),
  ('hafs-62-2', 'hafs', 62, 2, 'هُوَ ٱلَّذِى بَعَثَ فِى ٱلْأُمِّيِّۦنَ رَسُولًۭا مِّنْهُمْ يَتْلُوا۟ عَلَيْهِمْ ءَايَٰتِهِۦ وَيُزَكِّيهِمْ وَيُعَلِّمُهُمُ ٱلْكِتَٰبَ وَٱلْحِكْمَةَ وَإِن كَانُوا۟ مِن قَبْلُ لَفِى ضَلَٰلٍۢ مُّبِينٍۢ', 'هو الذى بعث فى الأمين رسولا منهم يتلوا عليهم ءايته ويزكيهم ويعلمهم الكتب والحكمة وإن كانوا من قبل لفى ضلل مبين', NULL, 553, 'local:hafs-text.json'),
  ('hafs-62-3', 'hafs', 62, 3, 'وَءَاخَرِينَ مِنْهُمْ لَمَّا يَلْحَقُوا۟ بِهِمْ ۚ وَهُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ', 'وءاخرين منهم لما يلحقوا بهم  وهو العزيز الحكيم', NULL, 553, 'local:hafs-text.json'),
  ('hafs-62-4', 'hafs', 62, 4, 'ذَٰلِكَ فَضْلُ ٱللَّهِ يُؤْتِيهِ مَن يَشَآءُ ۚ وَٱللَّهُ ذُو ٱلْفَضْلِ ٱلْعَظِيمِ', 'ذلك فضل الله يؤتيه من يشاء  والله ذو الفضل العظيم', NULL, 553, 'local:hafs-text.json'),
  ('hafs-62-5', 'hafs', 62, 5, 'مَثَلُ ٱلَّذِينَ حُمِّلُوا۟ ٱلتَّوْرَىٰةَ ثُمَّ لَمْ يَحْمِلُوهَا كَمَثَلِ ٱلْحِمَارِ يَحْمِلُ أَسْفَارًۢا ۚ بِئْسَ مَثَلُ ٱلْقَوْمِ ٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَٰتِ ٱللَّهِ ۚ وَٱللَّهُ لَا يَهْدِى ٱلْقَوْمَ ٱلظَّٰلِمِينَ', 'مثل الذين حملوا التورىة ثم لم يحملوها كمثل الحمار يحمل أسفارا  بئس مثل القوم الذين كذبوا بايت الله  والله لا يهدى القوم الظلمين', NULL, 553, 'local:hafs-text.json'),
  ('hafs-62-6', 'hafs', 62, 6, 'قُلْ يَٰٓأَيُّهَا ٱلَّذِينَ هَادُوٓا۟ إِن زَعَمْتُمْ أَنَّكُمْ أَوْلِيَآءُ لِلَّهِ مِن دُونِ ٱلنَّاسِ فَتَمَنَّوُا۟ ٱلْمَوْتَ إِن كُنتُمْ صَٰدِقِينَ', 'قل يأيها الذين هادوا إن زعمتم أنكم أولياء لله من دون الناس فتمنوا الموت إن كنتم صدقين', NULL, 553, 'local:hafs-text.json'),
  ('hafs-62-7', 'hafs', 62, 7, 'وَلَا يَتَمَنَّوْنَهُۥٓ أَبَدًۢا بِمَا قَدَّمَتْ أَيْدِيهِمْ ۚ وَٱللَّهُ عَلِيمٌۢ بِٱلظَّٰلِمِينَ', 'ولا يتمنونه أبدا بما قدمت أيديهم  والله عليم بالظلمين', NULL, 553, 'local:hafs-text.json'),
  ('hafs-62-8', 'hafs', 62, 8, 'قُلْ إِنَّ ٱلْمَوْتَ ٱلَّذِى تَفِرُّونَ مِنْهُ فَإِنَّهُۥ مُلَٰقِيكُمْ ۖ ثُمَّ تُرَدُّونَ إِلَىٰ عَٰلِمِ ٱلْغَيْبِ وَٱلشَّهَٰدَةِ فَيُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ', 'قل إن الموت الذى تفرون منه فإنه ملقيكم  ثم تردون إلى علم الغيب والشهدة فينبئكم بما كنتم تعملون', NULL, 553, 'local:hafs-text.json'),
  ('hafs-62-9', 'hafs', 62, 9, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِذَا نُودِىَ لِلصَّلَوٰةِ مِن يَوْمِ ٱلْجُمُعَةِ فَٱسْعَوْا۟ إِلَىٰ ذِكْرِ ٱللَّهِ وَذَرُوا۟ ٱلْبَيْعَ ۚ ذَٰلِكُمْ خَيْرٌۭ لَّكُمْ إِن كُنتُمْ تَعْلَمُونَ', 'يأيها الذين ءامنوا إذا نودى للصلوة من يوم الجمعة فاسعوا إلى ذكر الله وذروا البيع  ذلكم خير لكم إن كنتم تعلمون', NULL, 554, 'local:hafs-text.json'),
  ('hafs-62-10', 'hafs', 62, 10, 'فَإِذَا قُضِيَتِ ٱلصَّلَوٰةُ فَٱنتَشِرُوا۟ فِى ٱلْأَرْضِ وَٱبْتَغُوا۟ مِن فَضْلِ ٱللَّهِ وَٱذْكُرُوا۟ ٱللَّهَ كَثِيرًۭا لَّعَلَّكُمْ تُفْلِحُونَ', 'فإذا قضيت الصلوة فانتشروا فى الأرض وابتغوا من فضل الله واذكروا الله كثيرا لعلكم تفلحون', NULL, 554, 'local:hafs-text.json'),
  ('hafs-62-11', 'hafs', 62, 11, 'وَإِذَا رَأَوْا۟ تِجَٰرَةً أَوْ لَهْوًا ٱنفَضُّوٓا۟ إِلَيْهَا وَتَرَكُوكَ قَآئِمًۭا ۚ قُلْ مَا عِندَ ٱللَّهِ خَيْرٌۭ مِّنَ ٱللَّهْوِ وَمِنَ ٱلتِّجَٰرَةِ ۚ وَٱللَّهُ خَيْرُ ٱلرَّٰزِقِينَ', 'وإذا رأوا تجرة أو لهوا انفضوا إليها وتركوك قائما  قل ما عند الله خير من اللهو ومن التجرة  والله خير الرزقين', NULL, 554, 'local:hafs-text.json'),
  ('hafs-63-1', 'hafs', 63, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ إِذَا جَآءَكَ ٱلْمُنَٰفِقُونَ قَالُوا۟ نَشْهَدُ إِنَّكَ لَرَسُولُ ٱللَّهِ ۗ وَٱللَّهُ يَعْلَمُ إِنَّكَ لَرَسُولُهُۥ وَٱللَّهُ يَشْهَدُ إِنَّ ٱلْمُنَٰفِقِينَ لَكَٰذِبُونَ', 'بسم الله الرحمن الرحيم إذا جاءك المنفقون قالوا نشهد إنك لرسول الله  والله يعلم إنك لرسوله والله يشهد إن المنفقين لكذبون', NULL, 554, 'local:hafs-text.json'),
  ('hafs-63-2', 'hafs', 63, 2, 'ٱتَّخَذُوٓا۟ أَيْمَٰنَهُمْ جُنَّةًۭ فَصَدُّوا۟ عَن سَبِيلِ ٱللَّهِ ۚ إِنَّهُمْ سَآءَ مَا كَانُوا۟ يَعْمَلُونَ', 'اتخذوا أيمنهم جنة فصدوا عن سبيل الله  إنهم ساء ما كانوا يعملون', NULL, 554, 'local:hafs-text.json'),
  ('hafs-63-3', 'hafs', 63, 3, 'ذَٰلِكَ بِأَنَّهُمْ ءَامَنُوا۟ ثُمَّ كَفَرُوا۟ فَطُبِعَ عَلَىٰ قُلُوبِهِمْ فَهُمْ لَا يَفْقَهُونَ', 'ذلك بأنهم ءامنوا ثم كفروا فطبع على قلوبهم فهم لا يفقهون', NULL, 554, 'local:hafs-text.json'),
  ('hafs-63-4', 'hafs', 63, 4, '۞ وَإِذَا رَأَيْتَهُمْ تُعْجِبُكَ أَجْسَامُهُمْ ۖ وَإِن يَقُولُوا۟ تَسْمَعْ لِقَوْلِهِمْ ۖ كَأَنَّهُمْ خُشُبٌۭ مُّسَنَّدَةٌۭ ۖ يَحْسَبُونَ كُلَّ صَيْحَةٍ عَلَيْهِمْ ۚ هُمُ ٱلْعَدُوُّ فَٱحْذَرْهُمْ ۚ قَٰتَلَهُمُ ٱللَّهُ ۖ أَنَّىٰ يُؤْفَكُونَ', 'وإذا رأيتهم تعجبك أجسامهم  وإن يقولوا تسمع لقولهم  كأنهم خشب مسندة  يحسبون كل صيحة عليهم  هم العدو فاحذرهم  قتلهم الله  أنى يؤفكون', NULL, 554, 'local:hafs-text.json'),
  ('hafs-63-5', 'hafs', 63, 5, 'وَإِذَا قِيلَ لَهُمْ تَعَالَوْا۟ يَسْتَغْفِرْ لَكُمْ رَسُولُ ٱللَّهِ لَوَّوْا۟ رُءُوسَهُمْ وَرَأَيْتَهُمْ يَصُدُّونَ وَهُم مُّسْتَكْبِرُونَ', 'وإذا قيل لهم تعالوا يستغفر لكم رسول الله لووا رءوسهم ورأيتهم يصدون وهم مستكبرون', NULL, 555, 'local:hafs-text.json'),
  ('hafs-63-6', 'hafs', 63, 6, 'سَوَآءٌ عَلَيْهِمْ أَسْتَغْفَرْتَ لَهُمْ أَمْ لَمْ تَسْتَغْفِرْ لَهُمْ لَن يَغْفِرَ ٱللَّهُ لَهُمْ ۚ إِنَّ ٱللَّهَ لَا يَهْدِى ٱلْقَوْمَ ٱلْفَٰسِقِينَ', 'سواء عليهم أستغفرت لهم أم لم تستغفر لهم لن يغفر الله لهم  إن الله لا يهدى القوم الفسقين', NULL, 555, 'local:hafs-text.json'),
  ('hafs-63-7', 'hafs', 63, 7, 'هُمُ ٱلَّذِينَ يَقُولُونَ لَا تُنفِقُوا۟ عَلَىٰ مَنْ عِندَ رَسُولِ ٱللَّهِ حَتَّىٰ يَنفَضُّوا۟ ۗ وَلِلَّهِ خَزَآئِنُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَلَٰكِنَّ ٱلْمُنَٰفِقِينَ لَا يَفْقَهُونَ', 'هم الذين يقولون لا تنفقوا على من عند رسول الله حتى ينفضوا  ولله خزائن السموت والأرض ولكن المنفقين لا يفقهون', NULL, 555, 'local:hafs-text.json'),
  ('hafs-63-8', 'hafs', 63, 8, 'يَقُولُونَ لَئِن رَّجَعْنَآ إِلَى ٱلْمَدِينَةِ لَيُخْرِجَنَّ ٱلْأَعَزُّ مِنْهَا ٱلْأَذَلَّ ۚ وَلِلَّهِ ٱلْعِزَّةُ وَلِرَسُولِهِۦ وَلِلْمُؤْمِنِينَ وَلَٰكِنَّ ٱلْمُنَٰفِقِينَ لَا يَعْلَمُونَ', 'يقولون لئن رجعنا إلى المدينة ليخرجن الأعز منها الأذل  ولله العزة ولرسوله وللمؤمنين ولكن المنفقين لا يعلمون', NULL, 555, 'local:hafs-text.json'),
  ('hafs-63-9', 'hafs', 63, 9, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تُلْهِكُمْ أَمْوَٰلُكُمْ وَلَآ أَوْلَٰدُكُمْ عَن ذِكْرِ ٱللَّهِ ۚ وَمَن يَفْعَلْ ذَٰلِكَ فَأُو۟لَٰٓئِكَ هُمُ ٱلْخَٰسِرُونَ', 'يأيها الذين ءامنوا لا تلهكم أمولكم ولا أولدكم عن ذكر الله  ومن يفعل ذلك فأولئك هم الخسرون', NULL, 555, 'local:hafs-text.json'),
  ('hafs-63-10', 'hafs', 63, 10, 'وَأَنفِقُوا۟ مِن مَّا رَزَقْنَٰكُم مِّن قَبْلِ أَن يَأْتِىَ أَحَدَكُمُ ٱلْمَوْتُ فَيَقُولَ رَبِّ لَوْلَآ أَخَّرْتَنِىٓ إِلَىٰٓ أَجَلٍۢ قَرِيبٍۢ فَأَصَّدَّقَ وَأَكُن مِّنَ ٱلصَّٰلِحِينَ', 'وأنفقوا من ما رزقنكم من قبل أن يأتى أحدكم الموت فيقول رب لولا أخرتنى إلى أجل قريب فأصدق وأكن من الصلحين', NULL, 555, 'local:hafs-text.json'),
  ('hafs-63-11', 'hafs', 63, 11, 'وَلَن يُؤَخِّرَ ٱللَّهُ نَفْسًا إِذَا جَآءَ أَجَلُهَا ۚ وَٱللَّهُ خَبِيرٌۢ بِمَا تَعْمَلُونَ', 'ولن يؤخر الله نفسا إذا جاء أجلها  والله خبير بما تعملون', NULL, 555, 'local:hafs-text.json'),
  ('hafs-64-1', 'hafs', 64, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ يُسَبِّحُ لِلَّهِ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ ۖ لَهُ ٱلْمُلْكُ وَلَهُ ٱلْحَمْدُ ۖ وَهُوَ عَلَىٰ كُلِّ شَىْءٍۢ قَدِيرٌ', 'بسم الله الرحمن الرحيم يسبح لله ما فى السموت وما فى الأرض  له الملك وله الحمد  وهو على كل شىء قدير', NULL, 556, 'local:hafs-text.json')
insert into public.ayahs (id, riwayah, surah_number, ayah_number, text, simple_text, juz, page, source) values
  ('hafs-64-2', 'hafs', 64, 2, 'هُوَ ٱلَّذِى خَلَقَكُمْ فَمِنكُمْ كَافِرٌۭ وَمِنكُم مُّؤْمِنٌۭ ۚ وَٱللَّهُ بِمَا تَعْمَلُونَ بَصِيرٌ', 'هو الذى خلقكم فمنكم كافر ومنكم مؤمن  والله بما تعملون بصير', NULL, 556, 'local:hafs-text.json'),
  ('hafs-64-3', 'hafs', 64, 3, 'خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ بِٱلْحَقِّ وَصَوَّرَكُمْ فَأَحْسَنَ صُوَرَكُمْ ۖ وَإِلَيْهِ ٱلْمَصِيرُ', 'خلق السموت والأرض بالحق وصوركم فأحسن صوركم  وإليه المصير', NULL, 556, 'local:hafs-text.json'),
  ('hafs-64-4', 'hafs', 64, 4, 'يَعْلَمُ مَا فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَيَعْلَمُ مَا تُسِرُّونَ وَمَا تُعْلِنُونَ ۚ وَٱللَّهُ عَلِيمٌۢ بِذَاتِ ٱلصُّدُورِ', 'يعلم ما فى السموت والأرض ويعلم ما تسرون وما تعلنون  والله عليم بذات الصدور', NULL, 556, 'local:hafs-text.json'),
  ('hafs-64-5', 'hafs', 64, 5, 'أَلَمْ يَأْتِكُمْ نَبَؤُا۟ ٱلَّذِينَ كَفَرُوا۟ مِن قَبْلُ فَذَاقُوا۟ وَبَالَ أَمْرِهِمْ وَلَهُمْ عَذَابٌ أَلِيمٌۭ', 'ألم يأتكم نبؤا الذين كفروا من قبل فذاقوا وبال أمرهم ولهم عذاب أليم', NULL, 556, 'local:hafs-text.json'),
  ('hafs-64-6', 'hafs', 64, 6, 'ذَٰلِكَ بِأَنَّهُۥ كَانَت تَّأْتِيهِمْ رُسُلُهُم بِٱلْبَيِّنَٰتِ فَقَالُوٓا۟ أَبَشَرٌۭ يَهْدُونَنَا فَكَفَرُوا۟ وَتَوَلَّوا۟ ۚ وَّٱسْتَغْنَى ٱللَّهُ ۚ وَٱللَّهُ غَنِىٌّ حَمِيدٌۭ', 'ذلك بأنه كانت تأتيهم رسلهم بالبينت فقالوا أبشر يهدوننا فكفروا وتولوا  واستغنى الله  والله غنى حميد', NULL, 556, 'local:hafs-text.json'),
  ('hafs-64-7', 'hafs', 64, 7, 'زَعَمَ ٱلَّذِينَ كَفَرُوٓا۟ أَن لَّن يُبْعَثُوا۟ ۚ قُلْ بَلَىٰ وَرَبِّى لَتُبْعَثُنَّ ثُمَّ لَتُنَبَّؤُنَّ بِمَا عَمِلْتُمْ ۚ وَذَٰلِكَ عَلَى ٱللَّهِ يَسِيرٌۭ', 'زعم الذين كفروا أن لن يبعثوا  قل بلى وربى لتبعثن ثم لتنبؤن بما عملتم  وذلك على الله يسير', NULL, 556, 'local:hafs-text.json'),
  ('hafs-64-8', 'hafs', 64, 8, 'فَـَٔامِنُوا۟ بِٱللَّهِ وَرَسُولِهِۦ وَٱلنُّورِ ٱلَّذِىٓ أَنزَلْنَا ۚ وَٱللَّهُ بِمَا تَعْمَلُونَ خَبِيرٌۭ', 'فامنوا بالله ورسوله والنور الذى أنزلنا  والله بما تعملون خبير', NULL, 556, 'local:hafs-text.json'),
  ('hafs-64-9', 'hafs', 64, 9, 'يَوْمَ يَجْمَعُكُمْ لِيَوْمِ ٱلْجَمْعِ ۖ ذَٰلِكَ يَوْمُ ٱلتَّغَابُنِ ۗ وَمَن يُؤْمِنۢ بِٱللَّهِ وَيَعْمَلْ صَٰلِحًۭا يُكَفِّرْ عَنْهُ سَيِّـَٔاتِهِۦ وَيُدْخِلْهُ جَنَّٰتٍۢ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ خَٰلِدِينَ فِيهَآ أَبَدًۭا ۚ ذَٰلِكَ ٱلْفَوْزُ ٱلْعَظِيمُ', 'يوم يجمعكم ليوم الجمع  ذلك يوم التغابن  ومن يؤمن بالله ويعمل صلحا يكفر عنه سياته ويدخله جنت تجرى من تحتها الأنهر خلدين فيها أبدا  ذلك الفوز العظيم', NULL, 556, 'local:hafs-text.json'),
  ('hafs-64-10', 'hafs', 64, 10, 'وَٱلَّذِينَ كَفَرُوا۟ وَكَذَّبُوا۟ بِـَٔايَٰتِنَآ أُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلنَّارِ خَٰلِدِينَ فِيهَا ۖ وَبِئْسَ ٱلْمَصِيرُ', 'والذين كفروا وكذبوا بايتنا أولئك أصحب النار خلدين فيها  وبئس المصير', NULL, 557, 'local:hafs-text.json'),
  ('hafs-64-11', 'hafs', 64, 11, 'مَآ أَصَابَ مِن مُّصِيبَةٍ إِلَّا بِإِذْنِ ٱللَّهِ ۗ وَمَن يُؤْمِنۢ بِٱللَّهِ يَهْدِ قَلْبَهُۥ ۚ وَٱللَّهُ بِكُلِّ شَىْءٍ عَلِيمٌۭ', 'ما أصاب من مصيبة إلا بإذن الله  ومن يؤمن بالله يهد قلبه  والله بكل شىء عليم', NULL, 557, 'local:hafs-text.json'),
  ('hafs-64-12', 'hafs', 64, 12, 'وَأَطِيعُوا۟ ٱللَّهَ وَأَطِيعُوا۟ ٱلرَّسُولَ ۚ فَإِن تَوَلَّيْتُمْ فَإِنَّمَا عَلَىٰ رَسُولِنَا ٱلْبَلَٰغُ ٱلْمُبِينُ', 'وأطيعوا الله وأطيعوا الرسول  فإن توليتم فإنما على رسولنا البلغ المبين', NULL, 557, 'local:hafs-text.json'),
  ('hafs-64-13', 'hafs', 64, 13, 'ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَ ۚ وَعَلَى ٱللَّهِ فَلْيَتَوَكَّلِ ٱلْمُؤْمِنُونَ', 'الله لا إله إلا هو  وعلى الله فليتوكل المؤمنون', NULL, 557, 'local:hafs-text.json'),
  ('hafs-64-14', 'hafs', 64, 14, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِنَّ مِنْ أَزْوَٰجِكُمْ وَأَوْلَٰدِكُمْ عَدُوًّۭا لَّكُمْ فَٱحْذَرُوهُمْ ۚ وَإِن تَعْفُوا۟ وَتَصْفَحُوا۟ وَتَغْفِرُوا۟ فَإِنَّ ٱللَّهَ غَفُورٌۭ رَّحِيمٌ', 'يأيها الذين ءامنوا إن من أزوجكم وأولدكم عدوا لكم فاحذروهم  وإن تعفوا وتصفحوا وتغفروا فإن الله غفور رحيم', NULL, 557, 'local:hafs-text.json'),
  ('hafs-64-15', 'hafs', 64, 15, 'إِنَّمَآ أَمْوَٰلُكُمْ وَأَوْلَٰدُكُمْ فِتْنَةٌۭ ۚ وَٱللَّهُ عِندَهُۥٓ أَجْرٌ عَظِيمٌۭ', 'إنما أمولكم وأولدكم فتنة  والله عنده أجر عظيم', NULL, 557, 'local:hafs-text.json'),
  ('hafs-64-16', 'hafs', 64, 16, 'فَٱتَّقُوا۟ ٱللَّهَ مَا ٱسْتَطَعْتُمْ وَٱسْمَعُوا۟ وَأَطِيعُوا۟ وَأَنفِقُوا۟ خَيْرًۭا لِّأَنفُسِكُمْ ۗ وَمَن يُوقَ شُحَّ نَفْسِهِۦ فَأُو۟لَٰٓئِكَ هُمُ ٱلْمُفْلِحُونَ', 'فاتقوا الله ما استطعتم واسمعوا وأطيعوا وأنفقوا خيرا لأنفسكم  ومن يوق شح نفسه فأولئك هم المفلحون', NULL, 557, 'local:hafs-text.json'),
  ('hafs-64-17', 'hafs', 64, 17, 'إِن تُقْرِضُوا۟ ٱللَّهَ قَرْضًا حَسَنًۭا يُضَٰعِفْهُ لَكُمْ وَيَغْفِرْ لَكُمْ ۚ وَٱللَّهُ شَكُورٌ حَلِيمٌ', 'إن تقرضوا الله قرضا حسنا يضعفه لكم ويغفر لكم  والله شكور حليم', NULL, 557, 'local:hafs-text.json'),
  ('hafs-64-18', 'hafs', 64, 18, 'عَٰلِمُ ٱلْغَيْبِ وَٱلشَّهَٰدَةِ ٱلْعَزِيزُ ٱلْحَكِيمُ', 'علم الغيب والشهدة العزيز الحكيم', NULL, 557, 'local:hafs-text.json'),
  ('hafs-65-1', 'hafs', 65, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ يَٰٓأَيُّهَا ٱلنَّبِىُّ إِذَا طَلَّقْتُمُ ٱلنِّسَآءَ فَطَلِّقُوهُنَّ لِعِدَّتِهِنَّ وَأَحْصُوا۟ ٱلْعِدَّةَ ۖ وَٱتَّقُوا۟ ٱللَّهَ رَبَّكُمْ ۖ لَا تُخْرِجُوهُنَّ مِنۢ بُيُوتِهِنَّ وَلَا يَخْرُجْنَ إِلَّآ أَن يَأْتِينَ بِفَٰحِشَةٍۢ مُّبَيِّنَةٍۢ ۚ وَتِلْكَ حُدُودُ ٱللَّهِ ۚ وَمَن يَتَعَدَّ حُدُودَ ٱللَّهِ فَقَدْ ظَلَمَ نَفْسَهُۥ ۚ لَا تَدْرِى لَعَلَّ ٱللَّهَ يُحْدِثُ بَعْدَ ذَٰلِكَ أَمْرًۭا', 'بسم الله الرحمن الرحيم يأيها النبى إذا طلقتم النساء فطلقوهن لعدتهن وأحصوا العدة  واتقوا الله ربكم  لا تخرجوهن من بيوتهن ولا يخرجن إلا أن يأتين بفحشة مبينة  وتلك حدود الله  ومن يتعد حدود الله فقد ظلم نفسه  لا تدرى لعل الله يحدث بعد ذلك أمرا', NULL, 558, 'local:hafs-text.json'),
  ('hafs-65-2', 'hafs', 65, 2, 'فَإِذَا بَلَغْنَ أَجَلَهُنَّ فَأَمْسِكُوهُنَّ بِمَعْرُوفٍ أَوْ فَارِقُوهُنَّ بِمَعْرُوفٍۢ وَأَشْهِدُوا۟ ذَوَىْ عَدْلٍۢ مِّنكُمْ وَأَقِيمُوا۟ ٱلشَّهَٰدَةَ لِلَّهِ ۚ ذَٰلِكُمْ يُوعَظُ بِهِۦ مَن كَانَ يُؤْمِنُ بِٱللَّهِ وَٱلْيَوْمِ ٱلْءَاخِرِ ۚ وَمَن يَتَّقِ ٱللَّهَ يَجْعَل لَّهُۥ مَخْرَجًۭا', 'فإذا بلغن أجلهن فأمسكوهن بمعروف أو فارقوهن بمعروف وأشهدوا ذوى عدل منكم وأقيموا الشهدة لله  ذلكم يوعظ به من كان يؤمن بالله واليوم الءاخر  ومن يتق الله يجعل له مخرجا', NULL, 558, 'local:hafs-text.json'),
  ('hafs-65-3', 'hafs', 65, 3, 'وَيَرْزُقْهُ مِنْ حَيْثُ لَا يَحْتَسِبُ ۚ وَمَن يَتَوَكَّلْ عَلَى ٱللَّهِ فَهُوَ حَسْبُهُۥٓ ۚ إِنَّ ٱللَّهَ بَٰلِغُ أَمْرِهِۦ ۚ قَدْ جَعَلَ ٱللَّهُ لِكُلِّ شَىْءٍۢ قَدْرًۭا', 'ويرزقه من حيث لا يحتسب  ومن يتوكل على الله فهو حسبه  إن الله بلغ أمره  قد جعل الله لكل شىء قدرا', NULL, 558, 'local:hafs-text.json'),
  ('hafs-65-4', 'hafs', 65, 4, 'وَٱلَّٰٓـِٔى يَئِسْنَ مِنَ ٱلْمَحِيضِ مِن نِّسَآئِكُمْ إِنِ ٱرْتَبْتُمْ فَعِدَّتُهُنَّ ثَلَٰثَةُ أَشْهُرٍۢ وَٱلَّٰٓـِٔى لَمْ يَحِضْنَ ۚ وَأُو۟لَٰتُ ٱلْأَحْمَالِ أَجَلُهُنَّ أَن يَضَعْنَ حَمْلَهُنَّ ۚ وَمَن يَتَّقِ ٱللَّهَ يَجْعَل لَّهُۥ مِنْ أَمْرِهِۦ يُسْرًۭا', 'والى يئسن من المحيض من نسائكم إن ارتبتم فعدتهن ثلثة أشهر والى لم يحضن  وأولت الأحمال أجلهن أن يضعن حملهن  ومن يتق الله يجعل له من أمره يسرا', NULL, 558, 'local:hafs-text.json'),
  ('hafs-65-5', 'hafs', 65, 5, 'ذَٰلِكَ أَمْرُ ٱللَّهِ أَنزَلَهُۥٓ إِلَيْكُمْ ۚ وَمَن يَتَّقِ ٱللَّهَ يُكَفِّرْ عَنْهُ سَيِّـَٔاتِهِۦ وَيُعْظِمْ لَهُۥٓ أَجْرًا', 'ذلك أمر الله أنزله إليكم  ومن يتق الله يكفر عنه سياته ويعظم له أجرا', NULL, 558, 'local:hafs-text.json'),
  ('hafs-65-6', 'hafs', 65, 6, 'أَسْكِنُوهُنَّ مِنْ حَيْثُ سَكَنتُم مِّن وُجْدِكُمْ وَلَا تُضَآرُّوهُنَّ لِتُضَيِّقُوا۟ عَلَيْهِنَّ ۚ وَإِن كُنَّ أُو۟لَٰتِ حَمْلٍۢ فَأَنفِقُوا۟ عَلَيْهِنَّ حَتَّىٰ يَضَعْنَ حَمْلَهُنَّ ۚ فَإِنْ أَرْضَعْنَ لَكُمْ فَـَٔاتُوهُنَّ أُجُورَهُنَّ ۖ وَأْتَمِرُوا۟ بَيْنَكُم بِمَعْرُوفٍۢ ۖ وَإِن تَعَاسَرْتُمْ فَسَتُرْضِعُ لَهُۥٓ أُخْرَىٰ', 'أسكنوهن من حيث سكنتم من وجدكم ولا تضاروهن لتضيقوا عليهن  وإن كن أولت حمل فأنفقوا عليهن حتى يضعن حملهن  فإن أرضعن لكم فاتوهن أجورهن  وأتمروا بينكم بمعروف  وإن تعاسرتم فسترضع له أخرى', NULL, 559, 'local:hafs-text.json'),
  ('hafs-65-7', 'hafs', 65, 7, 'لِيُنفِقْ ذُو سَعَةٍۢ مِّن سَعَتِهِۦ ۖ وَمَن قُدِرَ عَلَيْهِ رِزْقُهُۥ فَلْيُنفِقْ مِمَّآ ءَاتَىٰهُ ٱللَّهُ ۚ لَا يُكَلِّفُ ٱللَّهُ نَفْسًا إِلَّا مَآ ءَاتَىٰهَا ۚ سَيَجْعَلُ ٱللَّهُ بَعْدَ عُسْرٍۢ يُسْرًۭا', 'لينفق ذو سعة من سعته  ومن قدر عليه رزقه فلينفق مما ءاتىه الله  لا يكلف الله نفسا إلا ما ءاتىها  سيجعل الله بعد عسر يسرا', NULL, 559, 'local:hafs-text.json'),
  ('hafs-65-8', 'hafs', 65, 8, 'وَكَأَيِّن مِّن قَرْيَةٍ عَتَتْ عَنْ أَمْرِ رَبِّهَا وَرُسُلِهِۦ فَحَاسَبْنَٰهَا حِسَابًۭا شَدِيدًۭا وَعَذَّبْنَٰهَا عَذَابًۭا نُّكْرًۭا', 'وكأين من قرية عتت عن أمر ربها ورسله فحاسبنها حسابا شديدا وعذبنها عذابا نكرا', NULL, 559, 'local:hafs-text.json'),
  ('hafs-65-9', 'hafs', 65, 9, 'فَذَاقَتْ وَبَالَ أَمْرِهَا وَكَانَ عَٰقِبَةُ أَمْرِهَا خُسْرًا', 'فذاقت وبال أمرها وكان عقبة أمرها خسرا', NULL, 559, 'local:hafs-text.json'),
  ('hafs-65-10', 'hafs', 65, 10, 'أَعَدَّ ٱللَّهُ لَهُمْ عَذَابًۭا شَدِيدًۭا ۖ فَٱتَّقُوا۟ ٱللَّهَ يَٰٓأُو۟لِى ٱلْأَلْبَٰبِ ٱلَّذِينَ ءَامَنُوا۟ ۚ قَدْ أَنزَلَ ٱللَّهُ إِلَيْكُمْ ذِكْرًۭا', 'أعد الله لهم عذابا شديدا  فاتقوا الله يأولى الألبب الذين ءامنوا  قد أنزل الله إليكم ذكرا', NULL, 559, 'local:hafs-text.json'),
  ('hafs-65-11', 'hafs', 65, 11, 'رَّسُولًۭا يَتْلُوا۟ عَلَيْكُمْ ءَايَٰتِ ٱللَّهِ مُبَيِّنَٰتٍۢ لِّيُخْرِجَ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ مِنَ ٱلظُّلُمَٰتِ إِلَى ٱلنُّورِ ۚ وَمَن يُؤْمِنۢ بِٱللَّهِ وَيَعْمَلْ صَٰلِحًۭا يُدْخِلْهُ جَنَّٰتٍۢ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ خَٰلِدِينَ فِيهَآ أَبَدًۭا ۖ قَدْ أَحْسَنَ ٱللَّهُ لَهُۥ رِزْقًا', 'رسولا يتلوا عليكم ءايت الله مبينت ليخرج الذين ءامنوا وعملوا الصلحت من الظلمت إلى النور  ومن يؤمن بالله ويعمل صلحا يدخله جنت تجرى من تحتها الأنهر خلدين فيها أبدا  قد أحسن الله له رزقا', NULL, 559, 'local:hafs-text.json'),
  ('hafs-65-12', 'hafs', 65, 12, 'ٱللَّهُ ٱلَّذِى خَلَقَ سَبْعَ سَمَٰوَٰتٍۢ وَمِنَ ٱلْأَرْضِ مِثْلَهُنَّ يَتَنَزَّلُ ٱلْأَمْرُ بَيْنَهُنَّ لِتَعْلَمُوٓا۟ أَنَّ ٱللَّهَ عَلَىٰ كُلِّ شَىْءٍۢ قَدِيرٌۭ وَأَنَّ ٱللَّهَ قَدْ أَحَاطَ بِكُلِّ شَىْءٍ عِلْمًۢا', 'الله الذى خلق سبع سموت ومن الأرض مثلهن يتنزل الأمر بينهن لتعلموا أن الله على كل شىء قدير وأن الله قد أحاط بكل شىء علما', NULL, 559, 'local:hafs-text.json'),
  ('hafs-66-1', 'hafs', 66, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ يَٰٓأَيُّهَا ٱلنَّبِىُّ لِمَ تُحَرِّمُ مَآ أَحَلَّ ٱللَّهُ لَكَ ۖ تَبْتَغِى مَرْضَاتَ أَزْوَٰجِكَ ۚ وَٱللَّهُ غَفُورٌۭ رَّحِيمٌۭ', 'بسم الله الرحمن الرحيم يأيها النبى لم تحرم ما أحل الله لك  تبتغى مرضات أزوجك  والله غفور رحيم', NULL, 560, 'local:hafs-text.json'),
  ('hafs-66-2', 'hafs', 66, 2, 'قَدْ فَرَضَ ٱللَّهُ لَكُمْ تَحِلَّةَ أَيْمَٰنِكُمْ ۚ وَٱللَّهُ مَوْلَىٰكُمْ ۖ وَهُوَ ٱلْعَلِيمُ ٱلْحَكِيمُ', 'قد فرض الله لكم تحلة أيمنكم  والله مولىكم  وهو العليم الحكيم', NULL, 560, 'local:hafs-text.json'),
  ('hafs-66-3', 'hafs', 66, 3, 'وَإِذْ أَسَرَّ ٱلنَّبِىُّ إِلَىٰ بَعْضِ أَزْوَٰجِهِۦ حَدِيثًۭا فَلَمَّا نَبَّأَتْ بِهِۦ وَأَظْهَرَهُ ٱللَّهُ عَلَيْهِ عَرَّفَ بَعْضَهُۥ وَأَعْرَضَ عَنۢ بَعْضٍۢ ۖ فَلَمَّا نَبَّأَهَا بِهِۦ قَالَتْ مَنْ أَنۢبَأَكَ هَٰذَا ۖ قَالَ نَبَّأَنِىَ ٱلْعَلِيمُ ٱلْخَبِيرُ', 'وإذ أسر النبى إلى بعض أزوجه حديثا فلما نبأت به وأظهره الله عليه عرف بعضه وأعرض عن بعض  فلما نبأها به قالت من أنبأك هذا  قال نبأنى العليم الخبير', NULL, 560, 'local:hafs-text.json'),
  ('hafs-66-4', 'hafs', 66, 4, 'إِن تَتُوبَآ إِلَى ٱللَّهِ فَقَدْ صَغَتْ قُلُوبُكُمَا ۖ وَإِن تَظَٰهَرَا عَلَيْهِ فَإِنَّ ٱللَّهَ هُوَ مَوْلَىٰهُ وَجِبْرِيلُ وَصَٰلِحُ ٱلْمُؤْمِنِينَ ۖ وَٱلْمَلَٰٓئِكَةُ بَعْدَ ذَٰلِكَ ظَهِيرٌ', 'إن تتوبا إلى الله فقد صغت قلوبكما  وإن تظهرا عليه فإن الله هو مولىه وجبريل وصلح المؤمنين  والملئكة بعد ذلك ظهير', NULL, 560, 'local:hafs-text.json'),
  ('hafs-66-5', 'hafs', 66, 5, 'عَسَىٰ رَبُّهُۥٓ إِن طَلَّقَكُنَّ أَن يُبْدِلَهُۥٓ أَزْوَٰجًا خَيْرًۭا مِّنكُنَّ مُسْلِمَٰتٍۢ مُّؤْمِنَٰتٍۢ قَٰنِتَٰتٍۢ تَٰٓئِبَٰتٍ عَٰبِدَٰتٍۢ سَٰٓئِحَٰتٍۢ ثَيِّبَٰتٍۢ وَأَبْكَارًۭا', 'عسى ربه إن طلقكن أن يبدله أزوجا خيرا منكن مسلمت مؤمنت قنتت تئبت عبدت سئحت ثيبت وأبكارا', NULL, 560, 'local:hafs-text.json'),
  ('hafs-66-6', 'hafs', 66, 6, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ قُوٓا۟ أَنفُسَكُمْ وَأَهْلِيكُمْ نَارًۭا وَقُودُهَا ٱلنَّاسُ وَٱلْحِجَارَةُ عَلَيْهَا مَلَٰٓئِكَةٌ غِلَاظٌۭ شِدَادٌۭ لَّا يَعْصُونَ ٱللَّهَ مَآ أَمَرَهُمْ وَيَفْعَلُونَ مَا يُؤْمَرُونَ', 'يأيها الذين ءامنوا قوا أنفسكم وأهليكم نارا وقودها الناس والحجارة عليها ملئكة غلاظ شداد لا يعصون الله ما أمرهم ويفعلون ما يؤمرون', NULL, 560, 'local:hafs-text.json'),
  ('hafs-66-7', 'hafs', 66, 7, 'يَٰٓأَيُّهَا ٱلَّذِينَ كَفَرُوا۟ لَا تَعْتَذِرُوا۟ ٱلْيَوْمَ ۖ إِنَّمَا تُجْزَوْنَ مَا كُنتُمْ تَعْمَلُونَ', 'يأيها الذين كفروا لا تعتذروا اليوم  إنما تجزون ما كنتم تعملون', NULL, 560, 'local:hafs-text.json'),
  ('hafs-66-8', 'hafs', 66, 8, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ تُوبُوٓا۟ إِلَى ٱللَّهِ تَوْبَةًۭ نَّصُوحًا عَسَىٰ رَبُّكُمْ أَن يُكَفِّرَ عَنكُمْ سَيِّـَٔاتِكُمْ وَيُدْخِلَكُمْ جَنَّٰتٍۢ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ يَوْمَ لَا يُخْزِى ٱللَّهُ ٱلنَّبِىَّ وَٱلَّذِينَ ءَامَنُوا۟ مَعَهُۥ ۖ نُورُهُمْ يَسْعَىٰ بَيْنَ أَيْدِيهِمْ وَبِأَيْمَٰنِهِمْ يَقُولُونَ رَبَّنَآ أَتْمِمْ لَنَا نُورَنَا وَٱغْفِرْ لَنَآ ۖ إِنَّكَ عَلَىٰ كُلِّ شَىْءٍۢ قَدِيرٌۭ', 'يأيها الذين ءامنوا توبوا إلى الله توبة نصوحا عسى ربكم أن يكفر عنكم سياتكم ويدخلكم جنت تجرى من تحتها الأنهر يوم لا يخزى الله النبى والذين ءامنوا معه  نورهم يسعى بين أيديهم وبأيمنهم يقولون ربنا أتمم لنا نورنا واغفر لنا  إنك على كل شىء قدير', NULL, 561, 'local:hafs-text.json'),
  ('hafs-66-9', 'hafs', 66, 9, 'يَٰٓأَيُّهَا ٱلنَّبِىُّ جَٰهِدِ ٱلْكُفَّارَ وَٱلْمُنَٰفِقِينَ وَٱغْلُظْ عَلَيْهِمْ ۚ وَمَأْوَىٰهُمْ جَهَنَّمُ ۖ وَبِئْسَ ٱلْمَصِيرُ', 'يأيها النبى جهد الكفار والمنفقين واغلظ عليهم  ومأوىهم جهنم  وبئس المصير', NULL, 561, 'local:hafs-text.json'),
  ('hafs-66-10', 'hafs', 66, 10, 'ضَرَبَ ٱللَّهُ مَثَلًۭا لِّلَّذِينَ كَفَرُوا۟ ٱمْرَأَتَ نُوحٍۢ وَٱمْرَأَتَ لُوطٍۢ ۖ كَانَتَا تَحْتَ عَبْدَيْنِ مِنْ عِبَادِنَا صَٰلِحَيْنِ فَخَانَتَاهُمَا فَلَمْ يُغْنِيَا عَنْهُمَا مِنَ ٱللَّهِ شَيْـًۭٔا وَقِيلَ ٱدْخُلَا ٱلنَّارَ مَعَ ٱلدَّٰخِلِينَ', 'ضرب الله مثلا للذين كفروا امرأت نوح وامرأت لوط  كانتا تحت عبدين من عبادنا صلحين فخانتاهما فلم يغنيا عنهما من الله شيا وقيل ادخلا النار مع الدخلين', NULL, 561, 'local:hafs-text.json'),
  ('hafs-66-11', 'hafs', 66, 11, 'وَضَرَبَ ٱللَّهُ مَثَلًۭا لِّلَّذِينَ ءَامَنُوا۟ ٱمْرَأَتَ فِرْعَوْنَ إِذْ قَالَتْ رَبِّ ٱبْنِ لِى عِندَكَ بَيْتًۭا فِى ٱلْجَنَّةِ وَنَجِّنِى مِن فِرْعَوْنَ وَعَمَلِهِۦ وَنَجِّنِى مِنَ ٱلْقَوْمِ ٱلظَّٰلِمِينَ', 'وضرب الله مثلا للذين ءامنوا امرأت فرعون إذ قالت رب ابن لى عندك بيتا فى الجنة ونجنى من فرعون وعمله ونجنى من القوم الظلمين', NULL, 561, 'local:hafs-text.json'),
  ('hafs-66-12', 'hafs', 66, 12, 'وَمَرْيَمَ ٱبْنَتَ عِمْرَٰنَ ٱلَّتِىٓ أَحْصَنَتْ فَرْجَهَا فَنَفَخْنَا فِيهِ مِن رُّوحِنَا وَصَدَّقَتْ بِكَلِمَٰتِ رَبِّهَا وَكُتُبِهِۦ وَكَانَتْ مِنَ ٱلْقَٰنِتِينَ', 'ومريم ابنت عمرن التى أحصنت فرجها فنفخنا فيه من روحنا وصدقت بكلمت ربها وكتبه وكانت من القنتين', NULL, 561, 'local:hafs-text.json'),
  ('hafs-67-1', 'hafs', 67, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ تَبَٰرَكَ ٱلَّذِى بِيَدِهِ ٱلْمُلْكُ وَهُوَ عَلَىٰ كُلِّ شَىْءٍۢ قَدِيرٌ', 'بسم الله الرحمن الرحيم تبرك الذى بيده الملك وهو على كل شىء قدير', NULL, 562, 'local:hafs-text.json'),
  ('hafs-67-2', 'hafs', 67, 2, 'ٱلَّذِى خَلَقَ ٱلْمَوْتَ وَٱلْحَيَوٰةَ لِيَبْلُوَكُمْ أَيُّكُمْ أَحْسَنُ عَمَلًۭا ۚ وَهُوَ ٱلْعَزِيزُ ٱلْغَفُورُ', 'الذى خلق الموت والحيوة ليبلوكم أيكم أحسن عملا  وهو العزيز الغفور', NULL, 562, 'local:hafs-text.json'),
  ('hafs-67-3', 'hafs', 67, 3, 'ٱلَّذِى خَلَقَ سَبْعَ سَمَٰوَٰتٍۢ طِبَاقًۭا ۖ مَّا تَرَىٰ فِى خَلْقِ ٱلرَّحْمَٰنِ مِن تَفَٰوُتٍۢ ۖ فَٱرْجِعِ ٱلْبَصَرَ هَلْ تَرَىٰ مِن فُطُورٍۢ', 'الذى خلق سبع سموت طباقا  ما ترى فى خلق الرحمن من تفوت  فارجع البصر هل ترى من فطور', NULL, 562, 'local:hafs-text.json'),
  ('hafs-67-4', 'hafs', 67, 4, 'ثُمَّ ٱرْجِعِ ٱلْبَصَرَ كَرَّتَيْنِ يَنقَلِبْ إِلَيْكَ ٱلْبَصَرُ خَاسِئًۭا وَهُوَ حَسِيرٌۭ', 'ثم ارجع البصر كرتين ينقلب إليك البصر خاسئا وهو حسير', NULL, 562, 'local:hafs-text.json'),
  ('hafs-67-5', 'hafs', 67, 5, 'وَلَقَدْ زَيَّنَّا ٱلسَّمَآءَ ٱلدُّنْيَا بِمَصَٰبِيحَ وَجَعَلْنَٰهَا رُجُومًۭا لِّلشَّيَٰطِينِ ۖ وَأَعْتَدْنَا لَهُمْ عَذَابَ ٱلسَّعِيرِ', 'ولقد زينا السماء الدنيا بمصبيح وجعلنها رجوما للشيطين  وأعتدنا لهم عذاب السعير', NULL, 562, 'local:hafs-text.json'),
  ('hafs-67-6', 'hafs', 67, 6, 'وَلِلَّذِينَ كَفَرُوا۟ بِرَبِّهِمْ عَذَابُ جَهَنَّمَ ۖ وَبِئْسَ ٱلْمَصِيرُ', 'وللذين كفروا بربهم عذاب جهنم  وبئس المصير', NULL, 562, 'local:hafs-text.json'),
  ('hafs-67-7', 'hafs', 67, 7, 'إِذَآ أُلْقُوا۟ فِيهَا سَمِعُوا۟ لَهَا شَهِيقًۭا وَهِىَ تَفُورُ', 'إذا ألقوا فيها سمعوا لها شهيقا وهى تفور', NULL, 562, 'local:hafs-text.json'),
  ('hafs-67-8', 'hafs', 67, 8, 'تَكَادُ تَمَيَّزُ مِنَ ٱلْغَيْظِ ۖ كُلَّمَآ أُلْقِىَ فِيهَا فَوْجٌۭ سَأَلَهُمْ خَزَنَتُهَآ أَلَمْ يَأْتِكُمْ نَذِيرٌۭ', 'تكاد تميز من الغيظ  كلما ألقى فيها فوج سألهم خزنتها ألم يأتكم نذير', NULL, 562, 'local:hafs-text.json'),
  ('hafs-67-9', 'hafs', 67, 9, 'قَالُوا۟ بَلَىٰ قَدْ جَآءَنَا نَذِيرٌۭ فَكَذَّبْنَا وَقُلْنَا مَا نَزَّلَ ٱللَّهُ مِن شَىْءٍ إِنْ أَنتُمْ إِلَّا فِى ضَلَٰلٍۢ كَبِيرٍۢ', 'قالوا بلى قد جاءنا نذير فكذبنا وقلنا ما نزل الله من شىء إن أنتم إلا فى ضلل كبير', NULL, 562, 'local:hafs-text.json'),
  ('hafs-67-10', 'hafs', 67, 10, 'وَقَالُوا۟ لَوْ كُنَّا نَسْمَعُ أَوْ نَعْقِلُ مَا كُنَّا فِىٓ أَصْحَٰبِ ٱلسَّعِيرِ', 'وقالوا لو كنا نسمع أو نعقل ما كنا فى أصحب السعير', NULL, 562, 'local:hafs-text.json'),
  ('hafs-67-11', 'hafs', 67, 11, 'فَٱعْتَرَفُوا۟ بِذَنۢبِهِمْ فَسُحْقًۭا لِّأَصْحَٰبِ ٱلسَّعِيرِ', 'فاعترفوا بذنبهم فسحقا لأصحب السعير', NULL, 562, 'local:hafs-text.json'),
  ('hafs-67-12', 'hafs', 67, 12, 'إِنَّ ٱلَّذِينَ يَخْشَوْنَ رَبَّهُم بِٱلْغَيْبِ لَهُم مَّغْفِرَةٌۭ وَأَجْرٌۭ كَبِيرٌۭ', 'إن الذين يخشون ربهم بالغيب لهم مغفرة وأجر كبير', NULL, 562, 'local:hafs-text.json'),
  ('hafs-67-13', 'hafs', 67, 13, 'وَأَسِرُّوا۟ قَوْلَكُمْ أَوِ ٱجْهَرُوا۟ بِهِۦٓ ۖ إِنَّهُۥ عَلِيمٌۢ بِذَاتِ ٱلصُّدُورِ', 'وأسروا قولكم أو اجهروا به  إنه عليم بذات الصدور', NULL, 563, 'local:hafs-text.json'),
  ('hafs-67-14', 'hafs', 67, 14, 'أَلَا يَعْلَمُ مَنْ خَلَقَ وَهُوَ ٱللَّطِيفُ ٱلْخَبِيرُ', 'ألا يعلم من خلق وهو اللطيف الخبير', NULL, 563, 'local:hafs-text.json'),
  ('hafs-67-15', 'hafs', 67, 15, 'هُوَ ٱلَّذِى جَعَلَ لَكُمُ ٱلْأَرْضَ ذَلُولًۭا فَٱمْشُوا۟ فِى مَنَاكِبِهَا وَكُلُوا۟ مِن رِّزْقِهِۦ ۖ وَإِلَيْهِ ٱلنُّشُورُ', 'هو الذى جعل لكم الأرض ذلولا فامشوا فى مناكبها وكلوا من رزقه  وإليه النشور', NULL, 563, 'local:hafs-text.json'),
  ('hafs-67-16', 'hafs', 67, 16, 'ءَأَمِنتُم مَّن فِى ٱلسَّمَآءِ أَن يَخْسِفَ بِكُمُ ٱلْأَرْضَ فَإِذَا هِىَ تَمُورُ', 'ءأمنتم من فى السماء أن يخسف بكم الأرض فإذا هى تمور', NULL, 563, 'local:hafs-text.json'),
  ('hafs-67-17', 'hafs', 67, 17, 'أَمْ أَمِنتُم مَّن فِى ٱلسَّمَآءِ أَن يُرْسِلَ عَلَيْكُمْ حَاصِبًۭا ۖ فَسَتَعْلَمُونَ كَيْفَ نَذِيرِ', 'أم أمنتم من فى السماء أن يرسل عليكم حاصبا  فستعلمون كيف نذير', NULL, 563, 'local:hafs-text.json'),
  ('hafs-67-18', 'hafs', 67, 18, 'وَلَقَدْ كَذَّبَ ٱلَّذِينَ مِن قَبْلِهِمْ فَكَيْفَ كَانَ نَكِيرِ', 'ولقد كذب الذين من قبلهم فكيف كان نكير', NULL, 563, 'local:hafs-text.json'),
  ('hafs-67-19', 'hafs', 67, 19, 'أَوَلَمْ يَرَوْا۟ إِلَى ٱلطَّيْرِ فَوْقَهُمْ صَٰٓفَّٰتٍۢ وَيَقْبِضْنَ ۚ مَا يُمْسِكُهُنَّ إِلَّا ٱلرَّحْمَٰنُ ۚ إِنَّهُۥ بِكُلِّ شَىْءٍۭ بَصِيرٌ', 'أولم يروا إلى الطير فوقهم صفت ويقبضن  ما يمسكهن إلا الرحمن  إنه بكل شىء بصير', NULL, 563, 'local:hafs-text.json'),
  ('hafs-67-20', 'hafs', 67, 20, 'أَمَّنْ هَٰذَا ٱلَّذِى هُوَ جُندٌۭ لَّكُمْ يَنصُرُكُم مِّن دُونِ ٱلرَّحْمَٰنِ ۚ إِنِ ٱلْكَٰفِرُونَ إِلَّا فِى غُرُورٍ', 'أمن هذا الذى هو جند لكم ينصركم من دون الرحمن  إن الكفرون إلا فى غرور', NULL, 563, 'local:hafs-text.json'),
  ('hafs-67-21', 'hafs', 67, 21, 'أَمَّنْ هَٰذَا ٱلَّذِى يَرْزُقُكُمْ إِنْ أَمْسَكَ رِزْقَهُۥ ۚ بَل لَّجُّوا۟ فِى عُتُوٍّۢ وَنُفُورٍ', 'أمن هذا الذى يرزقكم إن أمسك رزقه  بل لجوا فى عتو ونفور', NULL, 563, 'local:hafs-text.json'),
  ('hafs-67-22', 'hafs', 67, 22, 'أَفَمَن يَمْشِى مُكِبًّا عَلَىٰ وَجْهِهِۦٓ أَهْدَىٰٓ أَمَّن يَمْشِى سَوِيًّا عَلَىٰ صِرَٰطٍۢ مُّسْتَقِيمٍۢ', 'أفمن يمشى مكبا على وجهه أهدى أمن يمشى سويا على صرط مستقيم', NULL, 563, 'local:hafs-text.json'),
  ('hafs-67-23', 'hafs', 67, 23, 'قُلْ هُوَ ٱلَّذِىٓ أَنشَأَكُمْ وَجَعَلَ لَكُمُ ٱلسَّمْعَ وَٱلْأَبْصَٰرَ وَٱلْأَفْـِٔدَةَ ۖ قَلِيلًۭا مَّا تَشْكُرُونَ', 'قل هو الذى أنشأكم وجعل لكم السمع والأبصر والأفدة  قليلا ما تشكرون', NULL, 563, 'local:hafs-text.json'),
  ('hafs-67-24', 'hafs', 67, 24, 'قُلْ هُوَ ٱلَّذِى ذَرَأَكُمْ فِى ٱلْأَرْضِ وَإِلَيْهِ تُحْشَرُونَ', 'قل هو الذى ذرأكم فى الأرض وإليه تحشرون', NULL, 563, 'local:hafs-text.json'),
  ('hafs-67-25', 'hafs', 67, 25, 'وَيَقُولُونَ مَتَىٰ هَٰذَا ٱلْوَعْدُ إِن كُنتُمْ صَٰدِقِينَ', 'ويقولون متى هذا الوعد إن كنتم صدقين', NULL, 563, 'local:hafs-text.json'),
  ('hafs-67-26', 'hafs', 67, 26, 'قُلْ إِنَّمَا ٱلْعِلْمُ عِندَ ٱللَّهِ وَإِنَّمَآ أَنَا۠ نَذِيرٌۭ مُّبِينٌۭ', 'قل إنما العلم عند الله وإنما أنا نذير مبين', NULL, 563, 'local:hafs-text.json'),
  ('hafs-67-27', 'hafs', 67, 27, 'فَلَمَّا رَأَوْهُ زُلْفَةًۭ سِيٓـَٔتْ وُجُوهُ ٱلَّذِينَ كَفَرُوا۟ وَقِيلَ هَٰذَا ٱلَّذِى كُنتُم بِهِۦ تَدَّعُونَ', 'فلما رأوه زلفة سيت وجوه الذين كفروا وقيل هذا الذى كنتم به تدعون', NULL, 564, 'local:hafs-text.json'),
  ('hafs-67-28', 'hafs', 67, 28, 'قُلْ أَرَءَيْتُمْ إِنْ أَهْلَكَنِىَ ٱللَّهُ وَمَن مَّعِىَ أَوْ رَحِمَنَا فَمَن يُجِيرُ ٱلْكَٰفِرِينَ مِنْ عَذَابٍ أَلِيمٍۢ', 'قل أرءيتم إن أهلكنى الله ومن معى أو رحمنا فمن يجير الكفرين من عذاب أليم', NULL, 564, 'local:hafs-text.json'),
  ('hafs-67-29', 'hafs', 67, 29, 'قُلْ هُوَ ٱلرَّحْمَٰنُ ءَامَنَّا بِهِۦ وَعَلَيْهِ تَوَكَّلْنَا ۖ فَسَتَعْلَمُونَ مَنْ هُوَ فِى ضَلَٰلٍۢ مُّبِينٍۢ', 'قل هو الرحمن ءامنا به وعليه توكلنا  فستعلمون من هو فى ضلل مبين', NULL, 564, 'local:hafs-text.json'),
  ('hafs-67-30', 'hafs', 67, 30, 'قُلْ أَرَءَيْتُمْ إِنْ أَصْبَحَ مَآؤُكُمْ غَوْرًۭا فَمَن يَأْتِيكُم بِمَآءٍۢ مَّعِينٍۭ', 'قل أرءيتم إن أصبح ماؤكم غورا فمن يأتيكم بماء معين', NULL, 564, 'local:hafs-text.json'),
  ('hafs-68-1', 'hafs', 68, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ نٓ ۚ وَٱلْقَلَمِ وَمَا يَسْطُرُونَ', 'بسم الله الرحمن الرحيم ن  والقلم وما يسطرون', NULL, 564, 'local:hafs-text.json'),
  ('hafs-68-2', 'hafs', 68, 2, 'مَآ أَنتَ بِنِعْمَةِ رَبِّكَ بِمَجْنُونٍۢ', 'ما أنت بنعمة ربك بمجنون', NULL, 564, 'local:hafs-text.json'),
  ('hafs-68-3', 'hafs', 68, 3, 'وَإِنَّ لَكَ لَأَجْرًا غَيْرَ مَمْنُونٍۢ', 'وإن لك لأجرا غير ممنون', NULL, 564, 'local:hafs-text.json'),
  ('hafs-68-4', 'hafs', 68, 4, 'وَإِنَّكَ لَعَلَىٰ خُلُقٍ عَظِيمٍۢ', 'وإنك لعلى خلق عظيم', NULL, 564, 'local:hafs-text.json'),
  ('hafs-68-5', 'hafs', 68, 5, 'فَسَتُبْصِرُ وَيُبْصِرُونَ', 'فستبصر ويبصرون', NULL, 564, 'local:hafs-text.json'),
  ('hafs-68-6', 'hafs', 68, 6, 'بِأَييِّكُمُ ٱلْمَفْتُونُ', 'بأييكم المفتون', NULL, 564, 'local:hafs-text.json'),
  ('hafs-68-7', 'hafs', 68, 7, 'إِنَّ رَبَّكَ هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِۦ وَهُوَ أَعْلَمُ بِٱلْمُهْتَدِينَ', 'إن ربك هو أعلم بمن ضل عن سبيله وهو أعلم بالمهتدين', NULL, 564, 'local:hafs-text.json'),
  ('hafs-68-8', 'hafs', 68, 8, 'فَلَا تُطِعِ ٱلْمُكَذِّبِينَ', 'فلا تطع المكذبين', NULL, 564, 'local:hafs-text.json'),
  ('hafs-68-9', 'hafs', 68, 9, 'وَدُّوا۟ لَوْ تُدْهِنُ فَيُدْهِنُونَ', 'ودوا لو تدهن فيدهنون', NULL, 564, 'local:hafs-text.json'),
  ('hafs-68-10', 'hafs', 68, 10, 'وَلَا تُطِعْ كُلَّ حَلَّافٍۢ مَّهِينٍ', 'ولا تطع كل حلاف مهين', NULL, 564, 'local:hafs-text.json'),
  ('hafs-68-11', 'hafs', 68, 11, 'هَمَّازٍۢ مَّشَّآءٍۭ بِنَمِيمٍۢ', 'هماز مشاء بنميم', NULL, 564, 'local:hafs-text.json'),
  ('hafs-68-12', 'hafs', 68, 12, 'مَّنَّاعٍۢ لِّلْخَيْرِ مُعْتَدٍ أَثِيمٍ', 'مناع للخير معتد أثيم', NULL, 564, 'local:hafs-text.json'),
  ('hafs-68-13', 'hafs', 68, 13, 'عُتُلٍّۭ بَعْدَ ذَٰلِكَ زَنِيمٍ', 'عتل بعد ذلك زنيم', NULL, 564, 'local:hafs-text.json'),
  ('hafs-68-14', 'hafs', 68, 14, 'أَن كَانَ ذَا مَالٍۢ وَبَنِينَ', 'أن كان ذا مال وبنين', NULL, 564, 'local:hafs-text.json'),
  ('hafs-68-15', 'hafs', 68, 15, 'إِذَا تُتْلَىٰ عَلَيْهِ ءَايَٰتُنَا قَالَ أَسَٰطِيرُ ٱلْأَوَّلِينَ', 'إذا تتلى عليه ءايتنا قال أسطير الأولين', NULL, 564, 'local:hafs-text.json'),
  ('hafs-68-16', 'hafs', 68, 16, 'سَنَسِمُهُۥ عَلَى ٱلْخُرْطُومِ', 'سنسمه على الخرطوم', NULL, 565, 'local:hafs-text.json'),
  ('hafs-68-17', 'hafs', 68, 17, 'إِنَّا بَلَوْنَٰهُمْ كَمَا بَلَوْنَآ أَصْحَٰبَ ٱلْجَنَّةِ إِذْ أَقْسَمُوا۟ لَيَصْرِمُنَّهَا مُصْبِحِينَ', 'إنا بلونهم كما بلونا أصحب الجنة إذ أقسموا ليصرمنها مصبحين', NULL, 565, 'local:hafs-text.json'),
  ('hafs-68-18', 'hafs', 68, 18, 'وَلَا يَسْتَثْنُونَ', 'ولا يستثنون', NULL, 565, 'local:hafs-text.json'),
  ('hafs-68-19', 'hafs', 68, 19, 'فَطَافَ عَلَيْهَا طَآئِفٌۭ مِّن رَّبِّكَ وَهُمْ نَآئِمُونَ', 'فطاف عليها طائف من ربك وهم نائمون', NULL, 565, 'local:hafs-text.json'),
  ('hafs-68-20', 'hafs', 68, 20, 'فَأَصْبَحَتْ كَٱلصَّرِيمِ', 'فأصبحت كالصريم', NULL, 565, 'local:hafs-text.json'),
  ('hafs-68-21', 'hafs', 68, 21, 'فَتَنَادَوْا۟ مُصْبِحِينَ', 'فتنادوا مصبحين', NULL, 565, 'local:hafs-text.json'),
  ('hafs-68-22', 'hafs', 68, 22, 'أَنِ ٱغْدُوا۟ عَلَىٰ حَرْثِكُمْ إِن كُنتُمْ صَٰرِمِينَ', 'أن اغدوا على حرثكم إن كنتم صرمين', NULL, 565, 'local:hafs-text.json'),
  ('hafs-68-23', 'hafs', 68, 23, 'فَٱنطَلَقُوا۟ وَهُمْ يَتَخَٰفَتُونَ', 'فانطلقوا وهم يتخفتون', NULL, 565, 'local:hafs-text.json'),
  ('hafs-68-24', 'hafs', 68, 24, 'أَن لَّا يَدْخُلَنَّهَا ٱلْيَوْمَ عَلَيْكُم مِّسْكِينٌۭ', 'أن لا يدخلنها اليوم عليكم مسكين', NULL, 565, 'local:hafs-text.json'),
  ('hafs-68-25', 'hafs', 68, 25, 'وَغَدَوْا۟ عَلَىٰ حَرْدٍۢ قَٰدِرِينَ', 'وغدوا على حرد قدرين', NULL, 565, 'local:hafs-text.json'),
  ('hafs-68-26', 'hafs', 68, 26, 'فَلَمَّا رَأَوْهَا قَالُوٓا۟ إِنَّا لَضَآلُّونَ', 'فلما رأوها قالوا إنا لضالون', NULL, 565, 'local:hafs-text.json'),
  ('hafs-68-27', 'hafs', 68, 27, 'بَلْ نَحْنُ مَحْرُومُونَ', 'بل نحن محرومون', NULL, 565, 'local:hafs-text.json'),
  ('hafs-68-28', 'hafs', 68, 28, 'قَالَ أَوْسَطُهُمْ أَلَمْ أَقُل لَّكُمْ لَوْلَا تُسَبِّحُونَ', 'قال أوسطهم ألم أقل لكم لولا تسبحون', NULL, 565, 'local:hafs-text.json'),
  ('hafs-68-29', 'hafs', 68, 29, 'قَالُوا۟ سُبْحَٰنَ رَبِّنَآ إِنَّا كُنَّا ظَٰلِمِينَ', 'قالوا سبحن ربنا إنا كنا ظلمين', NULL, 565, 'local:hafs-text.json'),
  ('hafs-68-30', 'hafs', 68, 30, 'فَأَقْبَلَ بَعْضُهُمْ عَلَىٰ بَعْضٍۢ يَتَلَٰوَمُونَ', 'فأقبل بعضهم على بعض يتلومون', NULL, 565, 'local:hafs-text.json'),
  ('hafs-68-31', 'hafs', 68, 31, 'قَالُوا۟ يَٰوَيْلَنَآ إِنَّا كُنَّا طَٰغِينَ', 'قالوا يويلنا إنا كنا طغين', NULL, 565, 'local:hafs-text.json'),
  ('hafs-68-32', 'hafs', 68, 32, 'عَسَىٰ رَبُّنَآ أَن يُبْدِلَنَا خَيْرًۭا مِّنْهَآ إِنَّآ إِلَىٰ رَبِّنَا رَٰغِبُونَ', 'عسى ربنا أن يبدلنا خيرا منها إنا إلى ربنا رغبون', NULL, 565, 'local:hafs-text.json'),
  ('hafs-68-33', 'hafs', 68, 33, 'كَذَٰلِكَ ٱلْعَذَابُ ۖ وَلَعَذَابُ ٱلْءَاخِرَةِ أَكْبَرُ ۚ لَوْ كَانُوا۟ يَعْلَمُونَ', 'كذلك العذاب  ولعذاب الءاخرة أكبر  لو كانوا يعلمون', NULL, 565, 'local:hafs-text.json'),
  ('hafs-68-34', 'hafs', 68, 34, 'إِنَّ لِلْمُتَّقِينَ عِندَ رَبِّهِمْ جَنَّٰتِ ٱلنَّعِيمِ', 'إن للمتقين عند ربهم جنت النعيم', NULL, 565, 'local:hafs-text.json'),
  ('hafs-68-35', 'hafs', 68, 35, 'أَفَنَجْعَلُ ٱلْمُسْلِمِينَ كَٱلْمُجْرِمِينَ', 'أفنجعل المسلمين كالمجرمين', NULL, 565, 'local:hafs-text.json'),
  ('hafs-68-36', 'hafs', 68, 36, 'مَا لَكُمْ كَيْفَ تَحْكُمُونَ', 'ما لكم كيف تحكمون', NULL, 565, 'local:hafs-text.json'),
  ('hafs-68-37', 'hafs', 68, 37, 'أَمْ لَكُمْ كِتَٰبٌۭ فِيهِ تَدْرُسُونَ', 'أم لكم كتب فيه تدرسون', NULL, 565, 'local:hafs-text.json'),
  ('hafs-68-38', 'hafs', 68, 38, 'إِنَّ لَكُمْ فِيهِ لَمَا تَخَيَّرُونَ', 'إن لكم فيه لما تخيرون', NULL, 565, 'local:hafs-text.json'),
  ('hafs-68-39', 'hafs', 68, 39, 'أَمْ لَكُمْ أَيْمَٰنٌ عَلَيْنَا بَٰلِغَةٌ إِلَىٰ يَوْمِ ٱلْقِيَٰمَةِ ۙ إِنَّ لَكُمْ لَمَا تَحْكُمُونَ', 'أم لكم أيمن علينا بلغة إلى يوم القيمة  إن لكم لما تحكمون', NULL, 565, 'local:hafs-text.json'),
  ('hafs-68-40', 'hafs', 68, 40, 'سَلْهُمْ أَيُّهُم بِذَٰلِكَ زَعِيمٌ', 'سلهم أيهم بذلك زعيم', NULL, 565, 'local:hafs-text.json'),
  ('hafs-68-41', 'hafs', 68, 41, 'أَمْ لَهُمْ شُرَكَآءُ فَلْيَأْتُوا۟ بِشُرَكَآئِهِمْ إِن كَانُوا۟ صَٰدِقِينَ', 'أم لهم شركاء فليأتوا بشركائهم إن كانوا صدقين', NULL, 565, 'local:hafs-text.json'),
  ('hafs-68-42', 'hafs', 68, 42, 'يَوْمَ يُكْشَفُ عَن سَاقٍۢ وَيُدْعَوْنَ إِلَى ٱلسُّجُودِ فَلَا يَسْتَطِيعُونَ', 'يوم يكشف عن ساق ويدعون إلى السجود فلا يستطيعون', NULL, 565, 'local:hafs-text.json'),
  ('hafs-68-43', 'hafs', 68, 43, 'خَٰشِعَةً أَبْصَٰرُهُمْ تَرْهَقُهُمْ ذِلَّةٌۭ ۖ وَقَدْ كَانُوا۟ يُدْعَوْنَ إِلَى ٱلسُّجُودِ وَهُمْ سَٰلِمُونَ', 'خشعة أبصرهم ترهقهم ذلة  وقد كانوا يدعون إلى السجود وهم سلمون', NULL, 566, 'local:hafs-text.json'),
  ('hafs-68-44', 'hafs', 68, 44, 'فَذَرْنِى وَمَن يُكَذِّبُ بِهَٰذَا ٱلْحَدِيثِ ۖ سَنَسْتَدْرِجُهُم مِّنْ حَيْثُ لَا يَعْلَمُونَ', 'فذرنى ومن يكذب بهذا الحديث  سنستدرجهم من حيث لا يعلمون', NULL, 566, 'local:hafs-text.json'),
  ('hafs-68-45', 'hafs', 68, 45, 'وَأُمْلِى لَهُمْ ۚ إِنَّ كَيْدِى مَتِينٌ', 'وأملى لهم  إن كيدى متين', NULL, 566, 'local:hafs-text.json'),
  ('hafs-68-46', 'hafs', 68, 46, 'أَمْ تَسْـَٔلُهُمْ أَجْرًۭا فَهُم مِّن مَّغْرَمٍۢ مُّثْقَلُونَ', 'أم تسلهم أجرا فهم من مغرم مثقلون', NULL, 566, 'local:hafs-text.json'),
  ('hafs-68-47', 'hafs', 68, 47, 'أَمْ عِندَهُمُ ٱلْغَيْبُ فَهُمْ يَكْتُبُونَ', 'أم عندهم الغيب فهم يكتبون', NULL, 566, 'local:hafs-text.json'),
  ('hafs-68-48', 'hafs', 68, 48, 'فَٱصْبِرْ لِحُكْمِ رَبِّكَ وَلَا تَكُن كَصَاحِبِ ٱلْحُوتِ إِذْ نَادَىٰ وَهُوَ مَكْظُومٌۭ', 'فاصبر لحكم ربك ولا تكن كصاحب الحوت إذ نادى وهو مكظوم', NULL, 566, 'local:hafs-text.json'),
  ('hafs-68-49', 'hafs', 68, 49, 'لَّوْلَآ أَن تَدَٰرَكَهُۥ نِعْمَةٌۭ مِّن رَّبِّهِۦ لَنُبِذَ بِٱلْعَرَآءِ وَهُوَ مَذْمُومٌۭ', 'لولا أن تدركه نعمة من ربه لنبذ بالعراء وهو مذموم', NULL, 566, 'local:hafs-text.json'),
  ('hafs-68-50', 'hafs', 68, 50, 'فَٱجْتَبَٰهُ رَبُّهُۥ فَجَعَلَهُۥ مِنَ ٱلصَّٰلِحِينَ', 'فاجتبه ربه فجعله من الصلحين', NULL, 566, 'local:hafs-text.json'),
  ('hafs-68-51', 'hafs', 68, 51, 'وَإِن يَكَادُ ٱلَّذِينَ كَفَرُوا۟ لَيُزْلِقُونَكَ بِأَبْصَٰرِهِمْ لَمَّا سَمِعُوا۟ ٱلذِّكْرَ وَيَقُولُونَ إِنَّهُۥ لَمَجْنُونٌۭ', 'وإن يكاد الذين كفروا ليزلقونك بأبصرهم لما سمعوا الذكر ويقولون إنه لمجنون', NULL, 566, 'local:hafs-text.json'),
  ('hafs-68-52', 'hafs', 68, 52, 'وَمَا هُوَ إِلَّا ذِكْرٌۭ لِّلْعَٰلَمِينَ', 'وما هو إلا ذكر للعلمين', NULL, 566, 'local:hafs-text.json'),
  ('hafs-69-1', 'hafs', 69, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ ٱلْحَآقَّةُ', 'بسم الله الرحمن الرحيم الحاقة', NULL, 566, 'local:hafs-text.json'),
  ('hafs-69-2', 'hafs', 69, 2, 'مَا ٱلْحَآقَّةُ', 'ما الحاقة', NULL, 566, 'local:hafs-text.json'),
  ('hafs-69-3', 'hafs', 69, 3, 'وَمَآ أَدْرَىٰكَ مَا ٱلْحَآقَّةُ', 'وما أدرىك ما الحاقة', NULL, 566, 'local:hafs-text.json'),
  ('hafs-69-4', 'hafs', 69, 4, 'كَذَّبَتْ ثَمُودُ وَعَادٌۢ بِٱلْقَارِعَةِ', 'كذبت ثمود وعاد بالقارعة', NULL, 566, 'local:hafs-text.json'),
  ('hafs-69-5', 'hafs', 69, 5, 'فَأَمَّا ثَمُودُ فَأُهْلِكُوا۟ بِٱلطَّاغِيَةِ', 'فأما ثمود فأهلكوا بالطاغية', NULL, 566, 'local:hafs-text.json'),
  ('hafs-69-6', 'hafs', 69, 6, 'وَأَمَّا عَادٌۭ فَأُهْلِكُوا۟ بِرِيحٍۢ صَرْصَرٍ عَاتِيَةٍۢ', 'وأما عاد فأهلكوا بريح صرصر عاتية', NULL, 566, 'local:hafs-text.json'),
  ('hafs-69-7', 'hafs', 69, 7, 'سَخَّرَهَا عَلَيْهِمْ سَبْعَ لَيَالٍۢ وَثَمَٰنِيَةَ أَيَّامٍ حُسُومًۭا فَتَرَى ٱلْقَوْمَ فِيهَا صَرْعَىٰ كَأَنَّهُمْ أَعْجَازُ نَخْلٍ خَاوِيَةٍۢ', 'سخرها عليهم سبع ليال وثمنية أيام حسوما فترى القوم فيها صرعى كأنهم أعجاز نخل خاوية', NULL, 566, 'local:hafs-text.json'),
  ('hafs-69-8', 'hafs', 69, 8, 'فَهَلْ تَرَىٰ لَهُم مِّنۢ بَاقِيَةٍۢ', 'فهل ترى لهم من باقية', NULL, 566, 'local:hafs-text.json'),
  ('hafs-69-9', 'hafs', 69, 9, 'وَجَآءَ فِرْعَوْنُ وَمَن قَبْلَهُۥ وَٱلْمُؤْتَفِكَٰتُ بِٱلْخَاطِئَةِ', 'وجاء فرعون ومن قبله والمؤتفكت بالخاطئة', NULL, 567, 'local:hafs-text.json'),
  ('hafs-69-10', 'hafs', 69, 10, 'فَعَصَوْا۟ رَسُولَ رَبِّهِمْ فَأَخَذَهُمْ أَخْذَةًۭ رَّابِيَةً', 'فعصوا رسول ربهم فأخذهم أخذة رابية', NULL, 567, 'local:hafs-text.json'),
  ('hafs-69-11', 'hafs', 69, 11, 'إِنَّا لَمَّا طَغَا ٱلْمَآءُ حَمَلْنَٰكُمْ فِى ٱلْجَارِيَةِ', 'إنا لما طغا الماء حملنكم فى الجارية', NULL, 567, 'local:hafs-text.json'),
  ('hafs-69-12', 'hafs', 69, 12, 'لِنَجْعَلَهَا لَكُمْ تَذْكِرَةًۭ وَتَعِيَهَآ أُذُنٌۭ وَٰعِيَةٌۭ', 'لنجعلها لكم تذكرة وتعيها أذن وعية', NULL, 567, 'local:hafs-text.json'),
  ('hafs-69-13', 'hafs', 69, 13, 'فَإِذَا نُفِخَ فِى ٱلصُّورِ نَفْخَةٌۭ وَٰحِدَةٌۭ', 'فإذا نفخ فى الصور نفخة وحدة', NULL, 567, 'local:hafs-text.json'),
  ('hafs-69-14', 'hafs', 69, 14, 'وَحُمِلَتِ ٱلْأَرْضُ وَٱلْجِبَالُ فَدُكَّتَا دَكَّةًۭ وَٰحِدَةًۭ', 'وحملت الأرض والجبال فدكتا دكة وحدة', NULL, 567, 'local:hafs-text.json'),
  ('hafs-69-15', 'hafs', 69, 15, 'فَيَوْمَئِذٍۢ وَقَعَتِ ٱلْوَاقِعَةُ', 'فيومئذ وقعت الواقعة', NULL, 567, 'local:hafs-text.json'),
  ('hafs-69-16', 'hafs', 69, 16, 'وَٱنشَقَّتِ ٱلسَّمَآءُ فَهِىَ يَوْمَئِذٍۢ وَاهِيَةٌۭ', 'وانشقت السماء فهى يومئذ واهية', NULL, 567, 'local:hafs-text.json'),
  ('hafs-69-17', 'hafs', 69, 17, 'وَٱلْمَلَكُ عَلَىٰٓ أَرْجَآئِهَا ۚ وَيَحْمِلُ عَرْشَ رَبِّكَ فَوْقَهُمْ يَوْمَئِذٍۢ ثَمَٰنِيَةٌۭ', 'والملك على أرجائها  ويحمل عرش ربك فوقهم يومئذ ثمنية', NULL, 567, 'local:hafs-text.json'),
  ('hafs-69-18', 'hafs', 69, 18, 'يَوْمَئِذٍۢ تُعْرَضُونَ لَا تَخْفَىٰ مِنكُمْ خَافِيَةٌۭ', 'يومئذ تعرضون لا تخفى منكم خافية', NULL, 567, 'local:hafs-text.json'),
  ('hafs-69-19', 'hafs', 69, 19, 'فَأَمَّا مَنْ أُوتِىَ كِتَٰبَهُۥ بِيَمِينِهِۦ فَيَقُولُ هَآؤُمُ ٱقْرَءُوا۟ كِتَٰبِيَهْ', 'فأما من أوتى كتبه بيمينه فيقول هاؤم اقرءوا كتبيه', NULL, 567, 'local:hafs-text.json'),
  ('hafs-69-20', 'hafs', 69, 20, 'إِنِّى ظَنَنتُ أَنِّى مُلَٰقٍ حِسَابِيَهْ', 'إنى ظننت أنى ملق حسابيه', NULL, 567, 'local:hafs-text.json'),
  ('hafs-69-21', 'hafs', 69, 21, 'فَهُوَ فِى عِيشَةٍۢ رَّاضِيَةٍۢ', 'فهو فى عيشة راضية', NULL, 567, 'local:hafs-text.json'),
  ('hafs-69-22', 'hafs', 69, 22, 'فِى جَنَّةٍ عَالِيَةٍۢ', 'فى جنة عالية', NULL, 567, 'local:hafs-text.json'),
  ('hafs-69-23', 'hafs', 69, 23, 'قُطُوفُهَا دَانِيَةٌۭ', 'قطوفها دانية', NULL, 567, 'local:hafs-text.json'),
  ('hafs-69-24', 'hafs', 69, 24, 'كُلُوا۟ وَٱشْرَبُوا۟ هَنِيٓـًٔۢا بِمَآ أَسْلَفْتُمْ فِى ٱلْأَيَّامِ ٱلْخَالِيَةِ', 'كلوا واشربوا هنيا بما أسلفتم فى الأيام الخالية', NULL, 567, 'local:hafs-text.json'),
  ('hafs-69-25', 'hafs', 69, 25, 'وَأَمَّا مَنْ أُوتِىَ كِتَٰبَهُۥ بِشِمَالِهِۦ فَيَقُولُ يَٰلَيْتَنِى لَمْ أُوتَ كِتَٰبِيَهْ', 'وأما من أوتى كتبه بشماله فيقول يليتنى لم أوت كتبيه', NULL, 567, 'local:hafs-text.json'),
  ('hafs-69-26', 'hafs', 69, 26, 'وَلَمْ أَدْرِ مَا حِسَابِيَهْ', 'ولم أدر ما حسابيه', NULL, 567, 'local:hafs-text.json'),
  ('hafs-69-27', 'hafs', 69, 27, 'يَٰلَيْتَهَا كَانَتِ ٱلْقَاضِيَةَ', 'يليتها كانت القاضية', NULL, 567, 'local:hafs-text.json'),
  ('hafs-69-28', 'hafs', 69, 28, 'مَآ أَغْنَىٰ عَنِّى مَالِيَهْ ۜ', 'ما أغنى عنى ماليه', NULL, 567, 'local:hafs-text.json'),
  ('hafs-69-29', 'hafs', 69, 29, 'هَلَكَ عَنِّى سُلْطَٰنِيَهْ', 'هلك عنى سلطنيه', NULL, 567, 'local:hafs-text.json'),
  ('hafs-69-30', 'hafs', 69, 30, 'خُذُوهُ فَغُلُّوهُ', 'خذوه فغلوه', NULL, 567, 'local:hafs-text.json'),
  ('hafs-69-31', 'hafs', 69, 31, 'ثُمَّ ٱلْجَحِيمَ صَلُّوهُ', 'ثم الجحيم صلوه', NULL, 567, 'local:hafs-text.json'),
  ('hafs-69-32', 'hafs', 69, 32, 'ثُمَّ فِى سِلْسِلَةٍۢ ذَرْعُهَا سَبْعُونَ ذِرَاعًۭا فَٱسْلُكُوهُ', 'ثم فى سلسلة ذرعها سبعون ذراعا فاسلكوه', NULL, 567, 'local:hafs-text.json'),
  ('hafs-69-33', 'hafs', 69, 33, 'إِنَّهُۥ كَانَ لَا يُؤْمِنُ بِٱللَّهِ ٱلْعَظِيمِ', 'إنه كان لا يؤمن بالله العظيم', NULL, 567, 'local:hafs-text.json'),
  ('hafs-69-34', 'hafs', 69, 34, 'وَلَا يَحُضُّ عَلَىٰ طَعَامِ ٱلْمِسْكِينِ', 'ولا يحض على طعام المسكين', NULL, 567, 'local:hafs-text.json'),
  ('hafs-69-35', 'hafs', 69, 35, 'فَلَيْسَ لَهُ ٱلْيَوْمَ هَٰهُنَا حَمِيمٌۭ', 'فليس له اليوم ههنا حميم', NULL, 568, 'local:hafs-text.json'),
  ('hafs-69-36', 'hafs', 69, 36, 'وَلَا طَعَامٌ إِلَّا مِنْ غِسْلِينٍۢ', 'ولا طعام إلا من غسلين', NULL, 568, 'local:hafs-text.json'),
  ('hafs-69-37', 'hafs', 69, 37, 'لَّا يَأْكُلُهُۥٓ إِلَّا ٱلْخَٰطِـُٔونَ', 'لا يأكله إلا الخطون', NULL, 568, 'local:hafs-text.json'),
  ('hafs-69-38', 'hafs', 69, 38, 'فَلَآ أُقْسِمُ بِمَا تُبْصِرُونَ', 'فلا أقسم بما تبصرون', NULL, 568, 'local:hafs-text.json'),
  ('hafs-69-39', 'hafs', 69, 39, 'وَمَا لَا تُبْصِرُونَ', 'وما لا تبصرون', NULL, 568, 'local:hafs-text.json'),
  ('hafs-69-40', 'hafs', 69, 40, 'إِنَّهُۥ لَقَوْلُ رَسُولٍۢ كَرِيمٍۢ', 'إنه لقول رسول كريم', NULL, 568, 'local:hafs-text.json'),
  ('hafs-69-41', 'hafs', 69, 41, 'وَمَا هُوَ بِقَوْلِ شَاعِرٍۢ ۚ قَلِيلًۭا مَّا تُؤْمِنُونَ', 'وما هو بقول شاعر  قليلا ما تؤمنون', NULL, 568, 'local:hafs-text.json'),
  ('hafs-69-42', 'hafs', 69, 42, 'وَلَا بِقَوْلِ كَاهِنٍۢ ۚ قَلِيلًۭا مَّا تَذَكَّرُونَ', 'ولا بقول كاهن  قليلا ما تذكرون', NULL, 568, 'local:hafs-text.json'),
  ('hafs-69-43', 'hafs', 69, 43, 'تَنزِيلٌۭ مِّن رَّبِّ ٱلْعَٰلَمِينَ', 'تنزيل من رب العلمين', NULL, 568, 'local:hafs-text.json'),
  ('hafs-69-44', 'hafs', 69, 44, 'وَلَوْ تَقَوَّلَ عَلَيْنَا بَعْضَ ٱلْأَقَاوِيلِ', 'ولو تقول علينا بعض الأقاويل', NULL, 568, 'local:hafs-text.json'),
  ('hafs-69-45', 'hafs', 69, 45, 'لَأَخَذْنَا مِنْهُ بِٱلْيَمِينِ', 'لأخذنا منه باليمين', NULL, 568, 'local:hafs-text.json'),
  ('hafs-69-46', 'hafs', 69, 46, 'ثُمَّ لَقَطَعْنَا مِنْهُ ٱلْوَتِينَ', 'ثم لقطعنا منه الوتين', NULL, 568, 'local:hafs-text.json'),
  ('hafs-69-47', 'hafs', 69, 47, 'فَمَا مِنكُم مِّنْ أَحَدٍ عَنْهُ حَٰجِزِينَ', 'فما منكم من أحد عنه حجزين', NULL, 568, 'local:hafs-text.json'),
  ('hafs-69-48', 'hafs', 69, 48, 'وَإِنَّهُۥ لَتَذْكِرَةٌۭ لِّلْمُتَّقِينَ', 'وإنه لتذكرة للمتقين', NULL, 568, 'local:hafs-text.json'),
  ('hafs-69-49', 'hafs', 69, 49, 'وَإِنَّا لَنَعْلَمُ أَنَّ مِنكُم مُّكَذِّبِينَ', 'وإنا لنعلم أن منكم مكذبين', NULL, 568, 'local:hafs-text.json'),
  ('hafs-69-50', 'hafs', 69, 50, 'وَإِنَّهُۥ لَحَسْرَةٌ عَلَى ٱلْكَٰفِرِينَ', 'وإنه لحسرة على الكفرين', NULL, 568, 'local:hafs-text.json'),
  ('hafs-69-51', 'hafs', 69, 51, 'وَإِنَّهُۥ لَحَقُّ ٱلْيَقِينِ', 'وإنه لحق اليقين', NULL, 568, 'local:hafs-text.json'),
  ('hafs-69-52', 'hafs', 69, 52, 'فَسَبِّحْ بِٱسْمِ رَبِّكَ ٱلْعَظِيمِ', 'فسبح باسم ربك العظيم', NULL, 568, 'local:hafs-text.json'),
  ('hafs-70-1', 'hafs', 70, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ سَأَلَ سَآئِلٌۢ بِعَذَابٍۢ وَاقِعٍۢ', 'بسم الله الرحمن الرحيم سأل سائل بعذاب واقع', NULL, 568, 'local:hafs-text.json'),
  ('hafs-70-2', 'hafs', 70, 2, 'لِّلْكَٰفِرِينَ لَيْسَ لَهُۥ دَافِعٌۭ', 'للكفرين ليس له دافع', NULL, 568, 'local:hafs-text.json'),
  ('hafs-70-3', 'hafs', 70, 3, 'مِّنَ ٱللَّهِ ذِى ٱلْمَعَارِجِ', 'من الله ذى المعارج', NULL, 568, 'local:hafs-text.json'),
  ('hafs-70-4', 'hafs', 70, 4, 'تَعْرُجُ ٱلْمَلَٰٓئِكَةُ وَٱلرُّوحُ إِلَيْهِ فِى يَوْمٍۢ كَانَ مِقْدَارُهُۥ خَمْسِينَ أَلْفَ سَنَةٍۢ', 'تعرج الملئكة والروح إليه فى يوم كان مقداره خمسين ألف سنة', NULL, 568, 'local:hafs-text.json'),
  ('hafs-70-5', 'hafs', 70, 5, 'فَٱصْبِرْ صَبْرًۭا جَمِيلًا', 'فاصبر صبرا جميلا', NULL, 568, 'local:hafs-text.json'),
  ('hafs-70-6', 'hafs', 70, 6, 'إِنَّهُمْ يَرَوْنَهُۥ بَعِيدًۭا', 'إنهم يرونه بعيدا', NULL, 568, 'local:hafs-text.json'),
  ('hafs-70-7', 'hafs', 70, 7, 'وَنَرَىٰهُ قَرِيبًۭا', 'ونرىه قريبا', NULL, 568, 'local:hafs-text.json'),
  ('hafs-70-8', 'hafs', 70, 8, 'يَوْمَ تَكُونُ ٱلسَّمَآءُ كَٱلْمُهْلِ', 'يوم تكون السماء كالمهل', NULL, 568, 'local:hafs-text.json'),
  ('hafs-70-9', 'hafs', 70, 9, 'وَتَكُونُ ٱلْجِبَالُ كَٱلْعِهْنِ', 'وتكون الجبال كالعهن', NULL, 568, 'local:hafs-text.json'),
  ('hafs-70-10', 'hafs', 70, 10, 'وَلَا يَسْـَٔلُ حَمِيمٌ حَمِيمًۭا', 'ولا يسل حميم حميما', NULL, 568, 'local:hafs-text.json'),
  ('hafs-70-11', 'hafs', 70, 11, 'يُبَصَّرُونَهُمْ ۚ يَوَدُّ ٱلْمُجْرِمُ لَوْ يَفْتَدِى مِنْ عَذَابِ يَوْمِئِذٍۭ بِبَنِيهِ', 'يبصرونهم  يود المجرم لو يفتدى من عذاب يومئذ ببنيه', NULL, 569, 'local:hafs-text.json'),
  ('hafs-70-12', 'hafs', 70, 12, 'وَصَٰحِبَتِهِۦ وَأَخِيهِ', 'وصحبته وأخيه', NULL, 569, 'local:hafs-text.json'),
  ('hafs-70-13', 'hafs', 70, 13, 'وَفَصِيلَتِهِ ٱلَّتِى تُـْٔوِيهِ', 'وفصيلته التى تويه', NULL, 569, 'local:hafs-text.json'),
  ('hafs-70-14', 'hafs', 70, 14, 'وَمَن فِى ٱلْأَرْضِ جَمِيعًۭا ثُمَّ يُنجِيهِ', 'ومن فى الأرض جميعا ثم ينجيه', NULL, 569, 'local:hafs-text.json'),
  ('hafs-70-15', 'hafs', 70, 15, 'كَلَّآ ۖ إِنَّهَا لَظَىٰ', 'كلا  إنها لظى', NULL, 569, 'local:hafs-text.json'),
  ('hafs-70-16', 'hafs', 70, 16, 'نَزَّاعَةًۭ لِّلشَّوَىٰ', 'نزاعة للشوى', NULL, 569, 'local:hafs-text.json'),
  ('hafs-70-17', 'hafs', 70, 17, 'تَدْعُوا۟ مَنْ أَدْبَرَ وَتَوَلَّىٰ', 'تدعوا من أدبر وتولى', NULL, 569, 'local:hafs-text.json'),
  ('hafs-70-18', 'hafs', 70, 18, 'وَجَمَعَ فَأَوْعَىٰٓ', 'وجمع فأوعى', NULL, 569, 'local:hafs-text.json'),
  ('hafs-70-19', 'hafs', 70, 19, '۞ إِنَّ ٱلْإِنسَٰنَ خُلِقَ هَلُوعًا', 'إن الإنسن خلق هلوعا', NULL, 569, 'local:hafs-text.json'),
  ('hafs-70-20', 'hafs', 70, 20, 'إِذَا مَسَّهُ ٱلشَّرُّ جَزُوعًۭا', 'إذا مسه الشر جزوعا', NULL, 569, 'local:hafs-text.json'),
  ('hafs-70-21', 'hafs', 70, 21, 'وَإِذَا مَسَّهُ ٱلْخَيْرُ مَنُوعًا', 'وإذا مسه الخير منوعا', NULL, 569, 'local:hafs-text.json'),
  ('hafs-70-22', 'hafs', 70, 22, 'إِلَّا ٱلْمُصَلِّينَ', 'إلا المصلين', NULL, 569, 'local:hafs-text.json'),
  ('hafs-70-23', 'hafs', 70, 23, 'ٱلَّذِينَ هُمْ عَلَىٰ صَلَاتِهِمْ دَآئِمُونَ', 'الذين هم على صلاتهم دائمون', NULL, 569, 'local:hafs-text.json'),
  ('hafs-70-24', 'hafs', 70, 24, 'وَٱلَّذِينَ فِىٓ أَمْوَٰلِهِمْ حَقٌّۭ مَّعْلُومٌۭ', 'والذين فى أمولهم حق معلوم', NULL, 569, 'local:hafs-text.json'),
  ('hafs-70-25', 'hafs', 70, 25, 'لِّلسَّآئِلِ وَٱلْمَحْرُومِ', 'للسائل والمحروم', NULL, 569, 'local:hafs-text.json'),
  ('hafs-70-26', 'hafs', 70, 26, 'وَٱلَّذِينَ يُصَدِّقُونَ بِيَوْمِ ٱلدِّينِ', 'والذين يصدقون بيوم الدين', NULL, 569, 'local:hafs-text.json'),
  ('hafs-70-27', 'hafs', 70, 27, 'وَٱلَّذِينَ هُم مِّنْ عَذَابِ رَبِّهِم مُّشْفِقُونَ', 'والذين هم من عذاب ربهم مشفقون', NULL, 569, 'local:hafs-text.json'),
  ('hafs-70-28', 'hafs', 70, 28, 'إِنَّ عَذَابَ رَبِّهِمْ غَيْرُ مَأْمُونٍۢ', 'إن عذاب ربهم غير مأمون', NULL, 569, 'local:hafs-text.json'),
  ('hafs-70-29', 'hafs', 70, 29, 'وَٱلَّذِينَ هُمْ لِفُرُوجِهِمْ حَٰفِظُونَ', 'والذين هم لفروجهم حفظون', NULL, 569, 'local:hafs-text.json'),
  ('hafs-70-30', 'hafs', 70, 30, 'إِلَّا عَلَىٰٓ أَزْوَٰجِهِمْ أَوْ مَا مَلَكَتْ أَيْمَٰنُهُمْ فَإِنَّهُمْ غَيْرُ مَلُومِينَ', 'إلا على أزوجهم أو ما ملكت أيمنهم فإنهم غير ملومين', NULL, 569, 'local:hafs-text.json'),
  ('hafs-70-31', 'hafs', 70, 31, 'فَمَنِ ٱبْتَغَىٰ وَرَآءَ ذَٰلِكَ فَأُو۟لَٰٓئِكَ هُمُ ٱلْعَادُونَ', 'فمن ابتغى وراء ذلك فأولئك هم العادون', NULL, 569, 'local:hafs-text.json'),
  ('hafs-70-32', 'hafs', 70, 32, 'وَٱلَّذِينَ هُمْ لِأَمَٰنَٰتِهِمْ وَعَهْدِهِمْ رَٰعُونَ', 'والذين هم لأمنتهم وعهدهم رعون', NULL, 569, 'local:hafs-text.json'),
  ('hafs-70-33', 'hafs', 70, 33, 'وَٱلَّذِينَ هُم بِشَهَٰدَٰتِهِمْ قَآئِمُونَ', 'والذين هم بشهدتهم قائمون', NULL, 569, 'local:hafs-text.json'),
  ('hafs-70-34', 'hafs', 70, 34, 'وَٱلَّذِينَ هُمْ عَلَىٰ صَلَاتِهِمْ يُحَافِظُونَ', 'والذين هم على صلاتهم يحافظون', NULL, 569, 'local:hafs-text.json'),
  ('hafs-70-35', 'hafs', 70, 35, 'أُو۟لَٰٓئِكَ فِى جَنَّٰتٍۢ مُّكْرَمُونَ', 'أولئك فى جنت مكرمون', NULL, 569, 'local:hafs-text.json'),
  ('hafs-70-36', 'hafs', 70, 36, 'فَمَالِ ٱلَّذِينَ كَفَرُوا۟ قِبَلَكَ مُهْطِعِينَ', 'فمال الذين كفروا قبلك مهطعين', NULL, 569, 'local:hafs-text.json'),
  ('hafs-70-37', 'hafs', 70, 37, 'عَنِ ٱلْيَمِينِ وَعَنِ ٱلشِّمَالِ عِزِينَ', 'عن اليمين وعن الشمال عزين', NULL, 569, 'local:hafs-text.json'),
  ('hafs-70-38', 'hafs', 70, 38, 'أَيَطْمَعُ كُلُّ ٱمْرِئٍۢ مِّنْهُمْ أَن يُدْخَلَ جَنَّةَ نَعِيمٍۢ', 'أيطمع كل امرئ منهم أن يدخل جنة نعيم', NULL, 569, 'local:hafs-text.json'),
  ('hafs-70-39', 'hafs', 70, 39, 'كَلَّآ ۖ إِنَّا خَلَقْنَٰهُم مِّمَّا يَعْلَمُونَ', 'كلا  إنا خلقنهم مما يعلمون', NULL, 569, 'local:hafs-text.json'),
  ('hafs-70-40', 'hafs', 70, 40, 'فَلَآ أُقْسِمُ بِرَبِّ ٱلْمَشَٰرِقِ وَٱلْمَغَٰرِبِ إِنَّا لَقَٰدِرُونَ', 'فلا أقسم برب المشرق والمغرب إنا لقدرون', NULL, 570, 'local:hafs-text.json'),
  ('hafs-70-41', 'hafs', 70, 41, 'عَلَىٰٓ أَن نُّبَدِّلَ خَيْرًۭا مِّنْهُمْ وَمَا نَحْنُ بِمَسْبُوقِينَ', 'على أن نبدل خيرا منهم وما نحن بمسبوقين', NULL, 570, 'local:hafs-text.json'),
  ('hafs-70-42', 'hafs', 70, 42, 'فَذَرْهُمْ يَخُوضُوا۟ وَيَلْعَبُوا۟ حَتَّىٰ يُلَٰقُوا۟ يَوْمَهُمُ ٱلَّذِى يُوعَدُونَ', 'فذرهم يخوضوا ويلعبوا حتى يلقوا يومهم الذى يوعدون', NULL, 570, 'local:hafs-text.json'),
  ('hafs-70-43', 'hafs', 70, 43, 'يَوْمَ يَخْرُجُونَ مِنَ ٱلْأَجْدَاثِ سِرَاعًۭا كَأَنَّهُمْ إِلَىٰ نُصُبٍۢ يُوفِضُونَ', 'يوم يخرجون من الأجداث سراعا كأنهم إلى نصب يوفضون', NULL, 570, 'local:hafs-text.json'),
  ('hafs-70-44', 'hafs', 70, 44, 'خَٰشِعَةً أَبْصَٰرُهُمْ تَرْهَقُهُمْ ذِلَّةٌۭ ۚ ذَٰلِكَ ٱلْيَوْمُ ٱلَّذِى كَانُوا۟ يُوعَدُونَ', 'خشعة أبصرهم ترهقهم ذلة  ذلك اليوم الذى كانوا يوعدون', NULL, 570, 'local:hafs-text.json'),
  ('hafs-71-1', 'hafs', 71, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ إِنَّآ أَرْسَلْنَا نُوحًا إِلَىٰ قَوْمِهِۦٓ أَنْ أَنذِرْ قَوْمَكَ مِن قَبْلِ أَن يَأْتِيَهُمْ عَذَابٌ أَلِيمٌۭ', 'بسم الله الرحمن الرحيم إنا أرسلنا نوحا إلى قومه أن أنذر قومك من قبل أن يأتيهم عذاب أليم', NULL, 570, 'local:hafs-text.json'),
  ('hafs-71-2', 'hafs', 71, 2, 'قَالَ يَٰقَوْمِ إِنِّى لَكُمْ نَذِيرٌۭ مُّبِينٌ', 'قال يقوم إنى لكم نذير مبين', NULL, 570, 'local:hafs-text.json'),
  ('hafs-71-3', 'hafs', 71, 3, 'أَنِ ٱعْبُدُوا۟ ٱللَّهَ وَٱتَّقُوهُ وَأَطِيعُونِ', 'أن اعبدوا الله واتقوه وأطيعون', NULL, 570, 'local:hafs-text.json'),
  ('hafs-71-4', 'hafs', 71, 4, 'يَغْفِرْ لَكُم مِّن ذُنُوبِكُمْ وَيُؤَخِّرْكُمْ إِلَىٰٓ أَجَلٍۢ مُّسَمًّى ۚ إِنَّ أَجَلَ ٱللَّهِ إِذَا جَآءَ لَا يُؤَخَّرُ ۖ لَوْ كُنتُمْ تَعْلَمُونَ', 'يغفر لكم من ذنوبكم ويؤخركم إلى أجل مسمى  إن أجل الله إذا جاء لا يؤخر  لو كنتم تعلمون', NULL, 570, 'local:hafs-text.json'),
  ('hafs-71-5', 'hafs', 71, 5, 'قَالَ رَبِّ إِنِّى دَعَوْتُ قَوْمِى لَيْلًۭا وَنَهَارًۭا', 'قال رب إنى دعوت قومى ليلا ونهارا', NULL, 570, 'local:hafs-text.json'),
  ('hafs-71-6', 'hafs', 71, 6, 'فَلَمْ يَزِدْهُمْ دُعَآءِىٓ إِلَّا فِرَارًۭا', 'فلم يزدهم دعاءى إلا فرارا', NULL, 570, 'local:hafs-text.json'),
  ('hafs-71-7', 'hafs', 71, 7, 'وَإِنِّى كُلَّمَا دَعَوْتُهُمْ لِتَغْفِرَ لَهُمْ جَعَلُوٓا۟ أَصَٰبِعَهُمْ فِىٓ ءَاذَانِهِمْ وَٱسْتَغْشَوْا۟ ثِيَابَهُمْ وَأَصَرُّوا۟ وَٱسْتَكْبَرُوا۟ ٱسْتِكْبَارًۭا', 'وإنى كلما دعوتهم لتغفر لهم جعلوا أصبعهم فى ءاذانهم واستغشوا ثيابهم وأصروا واستكبروا استكبارا', NULL, 570, 'local:hafs-text.json'),
  ('hafs-71-8', 'hafs', 71, 8, 'ثُمَّ إِنِّى دَعَوْتُهُمْ جِهَارًۭا', 'ثم إنى دعوتهم جهارا', NULL, 570, 'local:hafs-text.json'),
  ('hafs-71-9', 'hafs', 71, 9, 'ثُمَّ إِنِّىٓ أَعْلَنتُ لَهُمْ وَأَسْرَرْتُ لَهُمْ إِسْرَارًۭا', 'ثم إنى أعلنت لهم وأسررت لهم إسرارا', NULL, 570, 'local:hafs-text.json'),
  ('hafs-71-10', 'hafs', 71, 10, 'فَقُلْتُ ٱسْتَغْفِرُوا۟ رَبَّكُمْ إِنَّهُۥ كَانَ غَفَّارًۭا', 'فقلت استغفروا ربكم إنه كان غفارا', NULL, 570, 'local:hafs-text.json'),
  ('hafs-71-11', 'hafs', 71, 11, 'يُرْسِلِ ٱلسَّمَآءَ عَلَيْكُم مِّدْرَارًۭا', 'يرسل السماء عليكم مدرارا', NULL, 571, 'local:hafs-text.json'),
  ('hafs-71-12', 'hafs', 71, 12, 'وَيُمْدِدْكُم بِأَمْوَٰلٍۢ وَبَنِينَ وَيَجْعَل لَّكُمْ جَنَّٰتٍۢ وَيَجْعَل لَّكُمْ أَنْهَٰرًۭا', 'ويمددكم بأمول وبنين ويجعل لكم جنت ويجعل لكم أنهرا', NULL, 571, 'local:hafs-text.json'),
  ('hafs-71-13', 'hafs', 71, 13, 'مَّا لَكُمْ لَا تَرْجُونَ لِلَّهِ وَقَارًۭا', 'ما لكم لا ترجون لله وقارا', NULL, 571, 'local:hafs-text.json'),
  ('hafs-71-14', 'hafs', 71, 14, 'وَقَدْ خَلَقَكُمْ أَطْوَارًا', 'وقد خلقكم أطوارا', NULL, 571, 'local:hafs-text.json'),
  ('hafs-71-15', 'hafs', 71, 15, 'أَلَمْ تَرَوْا۟ كَيْفَ خَلَقَ ٱللَّهُ سَبْعَ سَمَٰوَٰتٍۢ طِبَاقًۭا', 'ألم تروا كيف خلق الله سبع سموت طباقا', NULL, 571, 'local:hafs-text.json'),
  ('hafs-71-16', 'hafs', 71, 16, 'وَجَعَلَ ٱلْقَمَرَ فِيهِنَّ نُورًۭا وَجَعَلَ ٱلشَّمْسَ سِرَاجًۭا', 'وجعل القمر فيهن نورا وجعل الشمس سراجا', NULL, 571, 'local:hafs-text.json'),
  ('hafs-71-17', 'hafs', 71, 17, 'وَٱللَّهُ أَنۢبَتَكُم مِّنَ ٱلْأَرْضِ نَبَاتًۭا', 'والله أنبتكم من الأرض نباتا', NULL, 571, 'local:hafs-text.json'),
  ('hafs-71-18', 'hafs', 71, 18, 'ثُمَّ يُعِيدُكُمْ فِيهَا وَيُخْرِجُكُمْ إِخْرَاجًۭا', 'ثم يعيدكم فيها ويخرجكم إخراجا', NULL, 571, 'local:hafs-text.json'),
  ('hafs-71-19', 'hafs', 71, 19, 'وَٱللَّهُ جَعَلَ لَكُمُ ٱلْأَرْضَ بِسَاطًۭا', 'والله جعل لكم الأرض بساطا', NULL, 571, 'local:hafs-text.json'),
  ('hafs-71-20', 'hafs', 71, 20, 'لِّتَسْلُكُوا۟ مِنْهَا سُبُلًۭا فِجَاجًۭا', 'لتسلكوا منها سبلا فجاجا', NULL, 571, 'local:hafs-text.json'),
  ('hafs-71-21', 'hafs', 71, 21, 'قَالَ نُوحٌۭ رَّبِّ إِنَّهُمْ عَصَوْنِى وَٱتَّبَعُوا۟ مَن لَّمْ يَزِدْهُ مَالُهُۥ وَوَلَدُهُۥٓ إِلَّا خَسَارًۭا', 'قال نوح رب إنهم عصونى واتبعوا من لم يزده ماله وولده إلا خسارا', NULL, 571, 'local:hafs-text.json'),
  ('hafs-71-22', 'hafs', 71, 22, 'وَمَكَرُوا۟ مَكْرًۭا كُبَّارًۭا', 'ومكروا مكرا كبارا', NULL, 571, 'local:hafs-text.json'),
  ('hafs-71-23', 'hafs', 71, 23, 'وَقَالُوا۟ لَا تَذَرُنَّ ءَالِهَتَكُمْ وَلَا تَذَرُنَّ وَدًّۭا وَلَا سُوَاعًۭا وَلَا يَغُوثَ وَيَعُوقَ وَنَسْرًۭا', 'وقالوا لا تذرن ءالهتكم ولا تذرن ودا ولا سواعا ولا يغوث ويعوق ونسرا', NULL, 571, 'local:hafs-text.json'),
  ('hafs-71-24', 'hafs', 71, 24, 'وَقَدْ أَضَلُّوا۟ كَثِيرًۭا ۖ وَلَا تَزِدِ ٱلظَّٰلِمِينَ إِلَّا ضَلَٰلًۭا', 'وقد أضلوا كثيرا  ولا تزد الظلمين إلا ضللا', NULL, 571, 'local:hafs-text.json'),
  ('hafs-71-25', 'hafs', 71, 25, 'مِّمَّا خَطِيٓـَٰٔتِهِمْ أُغْرِقُوا۟ فَأُدْخِلُوا۟ نَارًۭا فَلَمْ يَجِدُوا۟ لَهُم مِّن دُونِ ٱللَّهِ أَنصَارًۭا', 'مما خطيتهم أغرقوا فأدخلوا نارا فلم يجدوا لهم من دون الله أنصارا', NULL, 571, 'local:hafs-text.json'),
  ('hafs-71-26', 'hafs', 71, 26, 'وَقَالَ نُوحٌۭ رَّبِّ لَا تَذَرْ عَلَى ٱلْأَرْضِ مِنَ ٱلْكَٰفِرِينَ دَيَّارًا', 'وقال نوح رب لا تذر على الأرض من الكفرين ديارا', NULL, 571, 'local:hafs-text.json'),
  ('hafs-71-27', 'hafs', 71, 27, 'إِنَّكَ إِن تَذَرْهُمْ يُضِلُّوا۟ عِبَادَكَ وَلَا يَلِدُوٓا۟ إِلَّا فَاجِرًۭا كَفَّارًۭا', 'إنك إن تذرهم يضلوا عبادك ولا يلدوا إلا فاجرا كفارا', NULL, 571, 'local:hafs-text.json'),
  ('hafs-71-28', 'hafs', 71, 28, 'رَّبِّ ٱغْفِرْ لِى وَلِوَٰلِدَىَّ وَلِمَن دَخَلَ بَيْتِىَ مُؤْمِنًۭا وَلِلْمُؤْمِنِينَ وَٱلْمُؤْمِنَٰتِ وَلَا تَزِدِ ٱلظَّٰلِمِينَ إِلَّا تَبَارًۢا', 'رب اغفر لى ولولدى ولمن دخل بيتى مؤمنا وللمؤمنين والمؤمنت ولا تزد الظلمين إلا تبارا', NULL, 571, 'local:hafs-text.json'),
  ('hafs-72-1', 'hafs', 72, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ قُلْ أُوحِىَ إِلَىَّ أَنَّهُ ٱسْتَمَعَ نَفَرٌۭ مِّنَ ٱلْجِنِّ فَقَالُوٓا۟ إِنَّا سَمِعْنَا قُرْءَانًا عَجَبًۭا', 'بسم الله الرحمن الرحيم قل أوحى إلى أنه استمع نفر من الجن فقالوا إنا سمعنا قرءانا عجبا', NULL, 572, 'local:hafs-text.json'),
  ('hafs-72-2', 'hafs', 72, 2, 'يَهْدِىٓ إِلَى ٱلرُّشْدِ فَـَٔامَنَّا بِهِۦ ۖ وَلَن نُّشْرِكَ بِرَبِّنَآ أَحَدًۭا', 'يهدى إلى الرشد فامنا به  ولن نشرك بربنا أحدا', NULL, 572, 'local:hafs-text.json'),
  ('hafs-72-3', 'hafs', 72, 3, 'وَأَنَّهُۥ تَعَٰلَىٰ جَدُّ رَبِّنَا مَا ٱتَّخَذَ صَٰحِبَةًۭ وَلَا وَلَدًۭا', 'وأنه تعلى جد ربنا ما اتخذ صحبة ولا ولدا', NULL, 572, 'local:hafs-text.json'),
  ('hafs-72-4', 'hafs', 72, 4, 'وَأَنَّهُۥ كَانَ يَقُولُ سَفِيهُنَا عَلَى ٱللَّهِ شَطَطًۭا', 'وأنه كان يقول سفيهنا على الله شططا', NULL, 572, 'local:hafs-text.json'),
  ('hafs-72-5', 'hafs', 72, 5, 'وَأَنَّا ظَنَنَّآ أَن لَّن تَقُولَ ٱلْإِنسُ وَٱلْجِنُّ عَلَى ٱللَّهِ كَذِبًۭا', 'وأنا ظننا أن لن تقول الإنس والجن على الله كذبا', NULL, 572, 'local:hafs-text.json'),
  ('hafs-72-6', 'hafs', 72, 6, 'وَأَنَّهُۥ كَانَ رِجَالٌۭ مِّنَ ٱلْإِنسِ يَعُوذُونَ بِرِجَالٍۢ مِّنَ ٱلْجِنِّ فَزَادُوهُمْ رَهَقًۭا', 'وأنه كان رجال من الإنس يعوذون برجال من الجن فزادوهم رهقا', NULL, 572, 'local:hafs-text.json'),
  ('hafs-72-7', 'hafs', 72, 7, 'وَأَنَّهُمْ ظَنُّوا۟ كَمَا ظَنَنتُمْ أَن لَّن يَبْعَثَ ٱللَّهُ أَحَدًۭا', 'وأنهم ظنوا كما ظننتم أن لن يبعث الله أحدا', NULL, 572, 'local:hafs-text.json'),
  ('hafs-72-8', 'hafs', 72, 8, 'وَأَنَّا لَمَسْنَا ٱلسَّمَآءَ فَوَجَدْنَٰهَا مُلِئَتْ حَرَسًۭا شَدِيدًۭا وَشُهُبًۭا', 'وأنا لمسنا السماء فوجدنها ملئت حرسا شديدا وشهبا', NULL, 572, 'local:hafs-text.json'),
  ('hafs-72-9', 'hafs', 72, 9, 'وَأَنَّا كُنَّا نَقْعُدُ مِنْهَا مَقَٰعِدَ لِلسَّمْعِ ۖ فَمَن يَسْتَمِعِ ٱلْءَانَ يَجِدْ لَهُۥ شِهَابًۭا رَّصَدًۭا', 'وأنا كنا نقعد منها مقعد للسمع  فمن يستمع الءان يجد له شهابا رصدا', NULL, 572, 'local:hafs-text.json'),
  ('hafs-72-10', 'hafs', 72, 10, 'وَأَنَّا لَا نَدْرِىٓ أَشَرٌّ أُرِيدَ بِمَن فِى ٱلْأَرْضِ أَمْ أَرَادَ بِهِمْ رَبُّهُمْ رَشَدًۭا', 'وأنا لا ندرى أشر أريد بمن فى الأرض أم أراد بهم ربهم رشدا', NULL, 572, 'local:hafs-text.json'),
  ('hafs-72-11', 'hafs', 72, 11, 'وَأَنَّا مِنَّا ٱلصَّٰلِحُونَ وَمِنَّا دُونَ ذَٰلِكَ ۖ كُنَّا طَرَآئِقَ قِدَدًۭا', 'وأنا منا الصلحون ومنا دون ذلك  كنا طرائق قددا', NULL, 572, 'local:hafs-text.json'),
  ('hafs-72-12', 'hafs', 72, 12, 'وَأَنَّا ظَنَنَّآ أَن لَّن نُّعْجِزَ ٱللَّهَ فِى ٱلْأَرْضِ وَلَن نُّعْجِزَهُۥ هَرَبًۭا', 'وأنا ظننا أن لن نعجز الله فى الأرض ولن نعجزه هربا', NULL, 572, 'local:hafs-text.json'),
  ('hafs-72-13', 'hafs', 72, 13, 'وَأَنَّا لَمَّا سَمِعْنَا ٱلْهُدَىٰٓ ءَامَنَّا بِهِۦ ۖ فَمَن يُؤْمِنۢ بِرَبِّهِۦ فَلَا يَخَافُ بَخْسًۭا وَلَا رَهَقًۭا', 'وأنا لما سمعنا الهدى ءامنا به  فمن يؤمن بربه فلا يخاف بخسا ولا رهقا', NULL, 572, 'local:hafs-text.json'),
  ('hafs-72-14', 'hafs', 72, 14, 'وَأَنَّا مِنَّا ٱلْمُسْلِمُونَ وَمِنَّا ٱلْقَٰسِطُونَ ۖ فَمَنْ أَسْلَمَ فَأُو۟لَٰٓئِكَ تَحَرَّوْا۟ رَشَدًۭا', 'وأنا منا المسلمون ومنا القسطون  فمن أسلم فأولئك تحروا رشدا', NULL, 573, 'local:hafs-text.json'),
  ('hafs-72-15', 'hafs', 72, 15, 'وَأَمَّا ٱلْقَٰسِطُونَ فَكَانُوا۟ لِجَهَنَّمَ حَطَبًۭا', 'وأما القسطون فكانوا لجهنم حطبا', NULL, 573, 'local:hafs-text.json'),
  ('hafs-72-16', 'hafs', 72, 16, 'وَأَلَّوِ ٱسْتَقَٰمُوا۟ عَلَى ٱلطَّرِيقَةِ لَأَسْقَيْنَٰهُم مَّآءً غَدَقًۭا', 'وألو استقموا على الطريقة لأسقينهم ماء غدقا', NULL, 573, 'local:hafs-text.json'),
  ('hafs-72-17', 'hafs', 72, 17, 'لِّنَفْتِنَهُمْ فِيهِ ۚ وَمَن يُعْرِضْ عَن ذِكْرِ رَبِّهِۦ يَسْلُكْهُ عَذَابًۭا صَعَدًۭا', 'لنفتنهم فيه  ومن يعرض عن ذكر ربه يسلكه عذابا صعدا', NULL, 573, 'local:hafs-text.json'),
  ('hafs-72-18', 'hafs', 72, 18, 'وَأَنَّ ٱلْمَسَٰجِدَ لِلَّهِ فَلَا تَدْعُوا۟ مَعَ ٱللَّهِ أَحَدًۭا', 'وأن المسجد لله فلا تدعوا مع الله أحدا', NULL, 573, 'local:hafs-text.json'),
  ('hafs-72-19', 'hafs', 72, 19, 'وَأَنَّهُۥ لَمَّا قَامَ عَبْدُ ٱللَّهِ يَدْعُوهُ كَادُوا۟ يَكُونُونَ عَلَيْهِ لِبَدًۭا', 'وأنه لما قام عبد الله يدعوه كادوا يكونون عليه لبدا', NULL, 573, 'local:hafs-text.json'),
  ('hafs-72-20', 'hafs', 72, 20, 'قُلْ إِنَّمَآ أَدْعُوا۟ رَبِّى وَلَآ أُشْرِكُ بِهِۦٓ أَحَدًۭا', 'قل إنما أدعوا ربى ولا أشرك به أحدا', NULL, 573, 'local:hafs-text.json'),
  ('hafs-72-21', 'hafs', 72, 21, 'قُلْ إِنِّى لَآ أَمْلِكُ لَكُمْ ضَرًّۭا وَلَا رَشَدًۭا', 'قل إنى لا أملك لكم ضرا ولا رشدا', NULL, 573, 'local:hafs-text.json'),
  ('hafs-72-22', 'hafs', 72, 22, 'قُلْ إِنِّى لَن يُجِيرَنِى مِنَ ٱللَّهِ أَحَدٌۭ وَلَنْ أَجِدَ مِن دُونِهِۦ مُلْتَحَدًا', 'قل إنى لن يجيرنى من الله أحد ولن أجد من دونه ملتحدا', NULL, 573, 'local:hafs-text.json'),
  ('hafs-72-23', 'hafs', 72, 23, 'إِلَّا بَلَٰغًۭا مِّنَ ٱللَّهِ وَرِسَٰلَٰتِهِۦ ۚ وَمَن يَعْصِ ٱللَّهَ وَرَسُولَهُۥ فَإِنَّ لَهُۥ نَارَ جَهَنَّمَ خَٰلِدِينَ فِيهَآ أَبَدًا', 'إلا بلغا من الله ورسلته  ومن يعص الله ورسوله فإن له نار جهنم خلدين فيها أبدا', NULL, 573, 'local:hafs-text.json'),
  ('hafs-72-24', 'hafs', 72, 24, 'حَتَّىٰٓ إِذَا رَأَوْا۟ مَا يُوعَدُونَ فَسَيَعْلَمُونَ مَنْ أَضْعَفُ نَاصِرًۭا وَأَقَلُّ عَدَدًۭا', 'حتى إذا رأوا ما يوعدون فسيعلمون من أضعف ناصرا وأقل عددا', NULL, 573, 'local:hafs-text.json'),
  ('hafs-72-25', 'hafs', 72, 25, 'قُلْ إِنْ أَدْرِىٓ أَقَرِيبٌۭ مَّا تُوعَدُونَ أَمْ يَجْعَلُ لَهُۥ رَبِّىٓ أَمَدًا', 'قل إن أدرى أقريب ما توعدون أم يجعل له ربى أمدا', NULL, 573, 'local:hafs-text.json'),
  ('hafs-72-26', 'hafs', 72, 26, 'عَٰلِمُ ٱلْغَيْبِ فَلَا يُظْهِرُ عَلَىٰ غَيْبِهِۦٓ أَحَدًا', 'علم الغيب فلا يظهر على غيبه أحدا', NULL, 573, 'local:hafs-text.json'),
  ('hafs-72-27', 'hafs', 72, 27, 'إِلَّا مَنِ ٱرْتَضَىٰ مِن رَّسُولٍۢ فَإِنَّهُۥ يَسْلُكُ مِنۢ بَيْنِ يَدَيْهِ وَمِنْ خَلْفِهِۦ رَصَدًۭا', 'إلا من ارتضى من رسول فإنه يسلك من بين يديه ومن خلفه رصدا', NULL, 573, 'local:hafs-text.json'),
  ('hafs-72-28', 'hafs', 72, 28, 'لِّيَعْلَمَ أَن قَدْ أَبْلَغُوا۟ رِسَٰلَٰتِ رَبِّهِمْ وَأَحَاطَ بِمَا لَدَيْهِمْ وَأَحْصَىٰ كُلَّ شَىْءٍ عَدَدًۢا', 'ليعلم أن قد أبلغوا رسلت ربهم وأحاط بما لديهم وأحصى كل شىء عددا', NULL, 573, 'local:hafs-text.json'),
  ('hafs-73-1', 'hafs', 73, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ يَٰٓأَيُّهَا ٱلْمُزَّمِّلُ', 'بسم الله الرحمن الرحيم يأيها المزمل', NULL, 574, 'local:hafs-text.json'),
  ('hafs-73-2', 'hafs', 73, 2, 'قُمِ ٱلَّيْلَ إِلَّا قَلِيلًۭا', 'قم اليل إلا قليلا', NULL, 574, 'local:hafs-text.json'),
  ('hafs-73-3', 'hafs', 73, 3, 'نِّصْفَهُۥٓ أَوِ ٱنقُصْ مِنْهُ قَلِيلًا', 'نصفه أو انقص منه قليلا', NULL, 574, 'local:hafs-text.json'),
  ('hafs-73-4', 'hafs', 73, 4, 'أَوْ زِدْ عَلَيْهِ وَرَتِّلِ ٱلْقُرْءَانَ تَرْتِيلًا', 'أو زد عليه ورتل القرءان ترتيلا', NULL, 574, 'local:hafs-text.json'),
  ('hafs-73-5', 'hafs', 73, 5, 'إِنَّا سَنُلْقِى عَلَيْكَ قَوْلًۭا ثَقِيلًا', 'إنا سنلقى عليك قولا ثقيلا', NULL, 574, 'local:hafs-text.json'),
  ('hafs-73-6', 'hafs', 73, 6, 'إِنَّ نَاشِئَةَ ٱلَّيْلِ هِىَ أَشَدُّ وَطْـًۭٔا وَأَقْوَمُ قِيلًا', 'إن ناشئة اليل هى أشد وطا وأقوم قيلا', NULL, 574, 'local:hafs-text.json'),
  ('hafs-73-7', 'hafs', 73, 7, 'إِنَّ لَكَ فِى ٱلنَّهَارِ سَبْحًۭا طَوِيلًۭا', 'إن لك فى النهار سبحا طويلا', NULL, 574, 'local:hafs-text.json'),
  ('hafs-73-8', 'hafs', 73, 8, 'وَٱذْكُرِ ٱسْمَ رَبِّكَ وَتَبَتَّلْ إِلَيْهِ تَبْتِيلًۭا', 'واذكر اسم ربك وتبتل إليه تبتيلا', NULL, 574, 'local:hafs-text.json'),
  ('hafs-73-9', 'hafs', 73, 9, 'رَّبُّ ٱلْمَشْرِقِ وَٱلْمَغْرِبِ لَآ إِلَٰهَ إِلَّا هُوَ فَٱتَّخِذْهُ وَكِيلًۭا', 'رب المشرق والمغرب لا إله إلا هو فاتخذه وكيلا', NULL, 574, 'local:hafs-text.json'),
  ('hafs-73-10', 'hafs', 73, 10, 'وَٱصْبِرْ عَلَىٰ مَا يَقُولُونَ وَٱهْجُرْهُمْ هَجْرًۭا جَمِيلًۭا', 'واصبر على ما يقولون واهجرهم هجرا جميلا', NULL, 574, 'local:hafs-text.json'),
  ('hafs-73-11', 'hafs', 73, 11, 'وَذَرْنِى وَٱلْمُكَذِّبِينَ أُو۟لِى ٱلنَّعْمَةِ وَمَهِّلْهُمْ قَلِيلًا', 'وذرنى والمكذبين أولى النعمة ومهلهم قليلا', NULL, 574, 'local:hafs-text.json'),
  ('hafs-73-12', 'hafs', 73, 12, 'إِنَّ لَدَيْنَآ أَنكَالًۭا وَجَحِيمًۭا', 'إن لدينا أنكالا وجحيما', NULL, 574, 'local:hafs-text.json'),
  ('hafs-73-13', 'hafs', 73, 13, 'وَطَعَامًۭا ذَا غُصَّةٍۢ وَعَذَابًا أَلِيمًۭا', 'وطعاما ذا غصة وعذابا أليما', NULL, 574, 'local:hafs-text.json'),
  ('hafs-73-14', 'hafs', 73, 14, 'يَوْمَ تَرْجُفُ ٱلْأَرْضُ وَٱلْجِبَالُ وَكَانَتِ ٱلْجِبَالُ كَثِيبًۭا مَّهِيلًا', 'يوم ترجف الأرض والجبال وكانت الجبال كثيبا مهيلا', NULL, 574, 'local:hafs-text.json'),
  ('hafs-73-15', 'hafs', 73, 15, 'إِنَّآ أَرْسَلْنَآ إِلَيْكُمْ رَسُولًۭا شَٰهِدًا عَلَيْكُمْ كَمَآ أَرْسَلْنَآ إِلَىٰ فِرْعَوْنَ رَسُولًۭا', 'إنا أرسلنا إليكم رسولا شهدا عليكم كما أرسلنا إلى فرعون رسولا', NULL, 574, 'local:hafs-text.json'),
  ('hafs-73-16', 'hafs', 73, 16, 'فَعَصَىٰ فِرْعَوْنُ ٱلرَّسُولَ فَأَخَذْنَٰهُ أَخْذًۭا وَبِيلًۭا', 'فعصى فرعون الرسول فأخذنه أخذا وبيلا', NULL, 574, 'local:hafs-text.json'),
  ('hafs-73-17', 'hafs', 73, 17, 'فَكَيْفَ تَتَّقُونَ إِن كَفَرْتُمْ يَوْمًۭا يَجْعَلُ ٱلْوِلْدَٰنَ شِيبًا', 'فكيف تتقون إن كفرتم يوما يجعل الولدن شيبا', NULL, 574, 'local:hafs-text.json'),
  ('hafs-73-18', 'hafs', 73, 18, 'ٱلسَّمَآءُ مُنفَطِرٌۢ بِهِۦ ۚ كَانَ وَعْدُهُۥ مَفْعُولًا', 'السماء منفطر به  كان وعده مفعولا', NULL, 574, 'local:hafs-text.json'),
  ('hafs-73-19', 'hafs', 73, 19, 'إِنَّ هَٰذِهِۦ تَذْكِرَةٌۭ ۖ فَمَن شَآءَ ٱتَّخَذَ إِلَىٰ رَبِّهِۦ سَبِيلًا', 'إن هذه تذكرة  فمن شاء اتخذ إلى ربه سبيلا', NULL, 574, 'local:hafs-text.json'),
  ('hafs-73-20', 'hafs', 73, 20, '۞ إِنَّ رَبَّكَ يَعْلَمُ أَنَّكَ تَقُومُ أَدْنَىٰ مِن ثُلُثَىِ ٱلَّيْلِ وَنِصْفَهُۥ وَثُلُثَهُۥ وَطَآئِفَةٌۭ مِّنَ ٱلَّذِينَ مَعَكَ ۚ وَٱللَّهُ يُقَدِّرُ ٱلَّيْلَ وَٱلنَّهَارَ ۚ عَلِمَ أَن لَّن تُحْصُوهُ فَتَابَ عَلَيْكُمْ ۖ فَٱقْرَءُوا۟ مَا تَيَسَّرَ مِنَ ٱلْقُرْءَانِ ۚ عَلِمَ أَن سَيَكُونُ مِنكُم مَّرْضَىٰ ۙ وَءَاخَرُونَ يَضْرِبُونَ فِى ٱلْأَرْضِ يَبْتَغُونَ مِن فَضْلِ ٱللَّهِ ۙ وَءَاخَرُونَ يُقَٰتِلُونَ فِى سَبِيلِ ٱللَّهِ ۖ فَٱقْرَءُوا۟ مَا تَيَسَّرَ مِنْهُ ۚ وَأَقِيمُوا۟ ٱلصَّلَوٰةَ وَءَاتُوا۟ ٱلزَّكَوٰةَ وَأَقْرِضُوا۟ ٱللَّهَ قَرْضًا حَسَنًۭا ۚ وَمَا تُقَدِّمُوا۟ لِأَنفُسِكُم مِّنْ خَيْرٍۢ تَجِدُوهُ عِندَ ٱللَّهِ هُوَ خَيْرًۭا وَأَعْظَمَ أَجْرًۭا ۚ وَٱسْتَغْفِرُوا۟ ٱللَّهَ ۖ إِنَّ ٱللَّهَ غَفُورٌۭ رَّحِيمٌۢ', 'إن ربك يعلم أنك تقوم أدنى من ثلثى اليل ونصفه وثلثه وطائفة من الذين معك  والله يقدر اليل والنهار  علم أن لن تحصوه فتاب عليكم  فاقرءوا ما تيسر من القرءان  علم أن سيكون منكم مرضى  وءاخرون يضربون فى الأرض يبتغون من فضل الله  وءاخرون يقتلون فى سبيل الله  فاقرءوا ما تيسر منه  وأقيموا الصلوة وءاتوا الزكوة وأقرضوا الله قرضا حسنا  وما تقدموا لأنفسكم من خير تجدوه عند الله هو خيرا وأعظم أجرا  واستغفروا الله  إن الله غفور رحيم', NULL, 575, 'local:hafs-text.json'),
  ('hafs-74-1', 'hafs', 74, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ يَٰٓأَيُّهَا ٱلْمُدَّثِّرُ', 'بسم الله الرحمن الرحيم يأيها المدثر', NULL, 575, 'local:hafs-text.json'),
  ('hafs-74-2', 'hafs', 74, 2, 'قُمْ فَأَنذِرْ', 'قم فأنذر', NULL, 575, 'local:hafs-text.json'),
  ('hafs-74-3', 'hafs', 74, 3, 'وَرَبَّكَ فَكَبِّرْ', 'وربك فكبر', NULL, 575, 'local:hafs-text.json'),
  ('hafs-74-4', 'hafs', 74, 4, 'وَثِيَابَكَ فَطَهِّرْ', 'وثيابك فطهر', NULL, 575, 'local:hafs-text.json'),
  ('hafs-74-5', 'hafs', 74, 5, 'وَٱلرُّجْزَ فَٱهْجُرْ', 'والرجز فاهجر', NULL, 575, 'local:hafs-text.json'),
  ('hafs-74-6', 'hafs', 74, 6, 'وَلَا تَمْنُن تَسْتَكْثِرُ', 'ولا تمنن تستكثر', NULL, 575, 'local:hafs-text.json'),
  ('hafs-74-7', 'hafs', 74, 7, 'وَلِرَبِّكَ فَٱصْبِرْ', 'ولربك فاصبر', NULL, 575, 'local:hafs-text.json'),
  ('hafs-74-8', 'hafs', 74, 8, 'فَإِذَا نُقِرَ فِى ٱلنَّاقُورِ', 'فإذا نقر فى الناقور', NULL, 575, 'local:hafs-text.json'),
  ('hafs-74-9', 'hafs', 74, 9, 'فَذَٰلِكَ يَوْمَئِذٍۢ يَوْمٌ عَسِيرٌ', 'فذلك يومئذ يوم عسير', NULL, 575, 'local:hafs-text.json'),
  ('hafs-74-10', 'hafs', 74, 10, 'عَلَى ٱلْكَٰفِرِينَ غَيْرُ يَسِيرٍۢ', 'على الكفرين غير يسير', NULL, 575, 'local:hafs-text.json'),
  ('hafs-74-11', 'hafs', 74, 11, 'ذَرْنِى وَمَنْ خَلَقْتُ وَحِيدًۭا', 'ذرنى ومن خلقت وحيدا', NULL, 575, 'local:hafs-text.json'),
  ('hafs-74-12', 'hafs', 74, 12, 'وَجَعَلْتُ لَهُۥ مَالًۭا مَّمْدُودًۭا', 'وجعلت له مالا ممدودا', NULL, 575, 'local:hafs-text.json'),
  ('hafs-74-13', 'hafs', 74, 13, 'وَبَنِينَ شُهُودًۭا', 'وبنين شهودا', NULL, 575, 'local:hafs-text.json'),
  ('hafs-74-14', 'hafs', 74, 14, 'وَمَهَّدتُّ لَهُۥ تَمْهِيدًۭا', 'ومهدت له تمهيدا', NULL, 575, 'local:hafs-text.json'),
  ('hafs-74-15', 'hafs', 74, 15, 'ثُمَّ يَطْمَعُ أَنْ أَزِيدَ', 'ثم يطمع أن أزيد', NULL, 575, 'local:hafs-text.json'),
  ('hafs-74-16', 'hafs', 74, 16, 'كَلَّآ ۖ إِنَّهُۥ كَانَ لِءَايَٰتِنَا عَنِيدًۭا', 'كلا  إنه كان لءايتنا عنيدا', NULL, 575, 'local:hafs-text.json'),
  ('hafs-74-17', 'hafs', 74, 17, 'سَأُرْهِقُهُۥ صَعُودًا', 'سأرهقه صعودا', NULL, 575, 'local:hafs-text.json'),
  ('hafs-74-18', 'hafs', 74, 18, 'إِنَّهُۥ فَكَّرَ وَقَدَّرَ', 'إنه فكر وقدر', NULL, 576, 'local:hafs-text.json'),
  ('hafs-74-19', 'hafs', 74, 19, 'فَقُتِلَ كَيْفَ قَدَّرَ', 'فقتل كيف قدر', NULL, 576, 'local:hafs-text.json'),
  ('hafs-74-20', 'hafs', 74, 20, 'ثُمَّ قُتِلَ كَيْفَ قَدَّرَ', 'ثم قتل كيف قدر', NULL, 576, 'local:hafs-text.json'),
  ('hafs-74-21', 'hafs', 74, 21, 'ثُمَّ نَظَرَ', 'ثم نظر', NULL, 576, 'local:hafs-text.json'),
  ('hafs-74-22', 'hafs', 74, 22, 'ثُمَّ عَبَسَ وَبَسَرَ', 'ثم عبس وبسر', NULL, 576, 'local:hafs-text.json'),
  ('hafs-74-23', 'hafs', 74, 23, 'ثُمَّ أَدْبَرَ وَٱسْتَكْبَرَ', 'ثم أدبر واستكبر', NULL, 576, 'local:hafs-text.json'),
  ('hafs-74-24', 'hafs', 74, 24, 'فَقَالَ إِنْ هَٰذَآ إِلَّا سِحْرٌۭ يُؤْثَرُ', 'فقال إن هذا إلا سحر يؤثر', NULL, 576, 'local:hafs-text.json'),
  ('hafs-74-25', 'hafs', 74, 25, 'إِنْ هَٰذَآ إِلَّا قَوْلُ ٱلْبَشَرِ', 'إن هذا إلا قول البشر', NULL, 576, 'local:hafs-text.json'),
  ('hafs-74-26', 'hafs', 74, 26, 'سَأُصْلِيهِ سَقَرَ', 'سأصليه سقر', NULL, 576, 'local:hafs-text.json'),
  ('hafs-74-27', 'hafs', 74, 27, 'وَمَآ أَدْرَىٰكَ مَا سَقَرُ', 'وما أدرىك ما سقر', NULL, 576, 'local:hafs-text.json'),
  ('hafs-74-28', 'hafs', 74, 28, 'لَا تُبْقِى وَلَا تَذَرُ', 'لا تبقى ولا تذر', NULL, 576, 'local:hafs-text.json'),
  ('hafs-74-29', 'hafs', 74, 29, 'لَوَّاحَةٌۭ لِّلْبَشَرِ', 'لواحة للبشر', NULL, 576, 'local:hafs-text.json'),
  ('hafs-74-30', 'hafs', 74, 30, 'عَلَيْهَا تِسْعَةَ عَشَرَ', 'عليها تسعة عشر', NULL, 576, 'local:hafs-text.json'),
  ('hafs-74-31', 'hafs', 74, 31, 'وَمَا جَعَلْنَآ أَصْحَٰبَ ٱلنَّارِ إِلَّا مَلَٰٓئِكَةًۭ ۙ وَمَا جَعَلْنَا عِدَّتَهُمْ إِلَّا فِتْنَةًۭ لِّلَّذِينَ كَفَرُوا۟ لِيَسْتَيْقِنَ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَٰبَ وَيَزْدَادَ ٱلَّذِينَ ءَامَنُوٓا۟ إِيمَٰنًۭا ۙ وَلَا يَرْتَابَ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَٰبَ وَٱلْمُؤْمِنُونَ ۙ وَلِيَقُولَ ٱلَّذِينَ فِى قُلُوبِهِم مَّرَضٌۭ وَٱلْكَٰفِرُونَ مَاذَآ أَرَادَ ٱللَّهُ بِهَٰذَا مَثَلًۭا ۚ كَذَٰلِكَ يُضِلُّ ٱللَّهُ مَن يَشَآءُ وَيَهْدِى مَن يَشَآءُ ۚ وَمَا يَعْلَمُ جُنُودَ رَبِّكَ إِلَّا هُوَ ۚ وَمَا هِىَ إِلَّا ذِكْرَىٰ لِلْبَشَرِ', 'وما جعلنا أصحب النار إلا ملئكة  وما جعلنا عدتهم إلا فتنة للذين كفروا ليستيقن الذين أوتوا الكتب ويزداد الذين ءامنوا إيمنا  ولا يرتاب الذين أوتوا الكتب والمؤمنون  وليقول الذين فى قلوبهم مرض والكفرون ماذا أراد الله بهذا مثلا  كذلك يضل الله من يشاء ويهدى من يشاء  وما يعلم جنود ربك إلا هو  وما هى إلا ذكرى للبشر', NULL, 576, 'local:hafs-text.json'),
  ('hafs-74-32', 'hafs', 74, 32, 'كَلَّا وَٱلْقَمَرِ', 'كلا والقمر', NULL, 576, 'local:hafs-text.json'),
  ('hafs-74-33', 'hafs', 74, 33, 'وَٱلَّيْلِ إِذْ أَدْبَرَ', 'واليل إذ أدبر', NULL, 576, 'local:hafs-text.json'),
  ('hafs-74-34', 'hafs', 74, 34, 'وَٱلصُّبْحِ إِذَآ أَسْفَرَ', 'والصبح إذا أسفر', NULL, 576, 'local:hafs-text.json'),
  ('hafs-74-35', 'hafs', 74, 35, 'إِنَّهَا لَإِحْدَى ٱلْكُبَرِ', 'إنها لإحدى الكبر', NULL, 576, 'local:hafs-text.json'),
  ('hafs-74-36', 'hafs', 74, 36, 'نَذِيرًۭا لِّلْبَشَرِ', 'نذيرا للبشر', NULL, 576, 'local:hafs-text.json'),
  ('hafs-74-37', 'hafs', 74, 37, 'لِمَن شَآءَ مِنكُمْ أَن يَتَقَدَّمَ أَوْ يَتَأَخَّرَ', 'لمن شاء منكم أن يتقدم أو يتأخر', NULL, 576, 'local:hafs-text.json'),
  ('hafs-74-38', 'hafs', 74, 38, 'كُلُّ نَفْسٍۭ بِمَا كَسَبَتْ رَهِينَةٌ', 'كل نفس بما كسبت رهينة', NULL, 576, 'local:hafs-text.json'),
  ('hafs-74-39', 'hafs', 74, 39, 'إِلَّآ أَصْحَٰبَ ٱلْيَمِينِ', 'إلا أصحب اليمين', NULL, 576, 'local:hafs-text.json'),
  ('hafs-74-40', 'hafs', 74, 40, 'فِى جَنَّٰتٍۢ يَتَسَآءَلُونَ', 'فى جنت يتساءلون', NULL, 576, 'local:hafs-text.json'),
  ('hafs-74-41', 'hafs', 74, 41, 'عَنِ ٱلْمُجْرِمِينَ', 'عن المجرمين', NULL, 576, 'local:hafs-text.json'),
  ('hafs-74-42', 'hafs', 74, 42, 'مَا سَلَكَكُمْ فِى سَقَرَ', 'ما سلككم فى سقر', NULL, 576, 'local:hafs-text.json'),
  ('hafs-74-43', 'hafs', 74, 43, 'قَالُوا۟ لَمْ نَكُ مِنَ ٱلْمُصَلِّينَ', 'قالوا لم نك من المصلين', NULL, 576, 'local:hafs-text.json'),
  ('hafs-74-44', 'hafs', 74, 44, 'وَلَمْ نَكُ نُطْعِمُ ٱلْمِسْكِينَ', 'ولم نك نطعم المسكين', NULL, 576, 'local:hafs-text.json'),
  ('hafs-74-45', 'hafs', 74, 45, 'وَكُنَّا نَخُوضُ مَعَ ٱلْخَآئِضِينَ', 'وكنا نخوض مع الخائضين', NULL, 576, 'local:hafs-text.json'),
  ('hafs-74-46', 'hafs', 74, 46, 'وَكُنَّا نُكَذِّبُ بِيَوْمِ ٱلدِّينِ', 'وكنا نكذب بيوم الدين', NULL, 576, 'local:hafs-text.json'),
  ('hafs-74-47', 'hafs', 74, 47, 'حَتَّىٰٓ أَتَىٰنَا ٱلْيَقِينُ', 'حتى أتىنا اليقين', NULL, 576, 'local:hafs-text.json'),
  ('hafs-74-48', 'hafs', 74, 48, 'فَمَا تَنفَعُهُمْ شَفَٰعَةُ ٱلشَّٰفِعِينَ', 'فما تنفعهم شفعة الشفعين', NULL, 577, 'local:hafs-text.json'),
  ('hafs-74-49', 'hafs', 74, 49, 'فَمَا لَهُمْ عَنِ ٱلتَّذْكِرَةِ مُعْرِضِينَ', 'فما لهم عن التذكرة معرضين', NULL, 577, 'local:hafs-text.json'),
  ('hafs-74-50', 'hafs', 74, 50, 'كَأَنَّهُمْ حُمُرٌۭ مُّسْتَنفِرَةٌۭ', 'كأنهم حمر مستنفرة', NULL, 577, 'local:hafs-text.json'),
  ('hafs-74-51', 'hafs', 74, 51, 'فَرَّتْ مِن قَسْوَرَةٍۭ', 'فرت من قسورة', NULL, 577, 'local:hafs-text.json'),
  ('hafs-74-52', 'hafs', 74, 52, 'بَلْ يُرِيدُ كُلُّ ٱمْرِئٍۢ مِّنْهُمْ أَن يُؤْتَىٰ صُحُفًۭا مُّنَشَّرَةًۭ', 'بل يريد كل امرئ منهم أن يؤتى صحفا منشرة', NULL, 577, 'local:hafs-text.json'),
  ('hafs-74-53', 'hafs', 74, 53, 'كَلَّا ۖ بَل لَّا يَخَافُونَ ٱلْءَاخِرَةَ', 'كلا  بل لا يخافون الءاخرة', NULL, 577, 'local:hafs-text.json'),
  ('hafs-74-54', 'hafs', 74, 54, 'كَلَّآ إِنَّهُۥ تَذْكِرَةٌۭ', 'كلا إنه تذكرة', NULL, 577, 'local:hafs-text.json'),
  ('hafs-74-55', 'hafs', 74, 55, 'فَمَن شَآءَ ذَكَرَهُۥ', 'فمن شاء ذكره', NULL, 577, 'local:hafs-text.json'),
  ('hafs-74-56', 'hafs', 74, 56, 'وَمَا يَذْكُرُونَ إِلَّآ أَن يَشَآءَ ٱللَّهُ ۚ هُوَ أَهْلُ ٱلتَّقْوَىٰ وَأَهْلُ ٱلْمَغْفِرَةِ', 'وما يذكرون إلا أن يشاء الله  هو أهل التقوى وأهل المغفرة', NULL, 577, 'local:hafs-text.json'),
  ('hafs-75-1', 'hafs', 75, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ لَآ أُقْسِمُ بِيَوْمِ ٱلْقِيَٰمَةِ', 'بسم الله الرحمن الرحيم لا أقسم بيوم القيمة', NULL, 577, 'local:hafs-text.json'),
  ('hafs-75-2', 'hafs', 75, 2, 'وَلَآ أُقْسِمُ بِٱلنَّفْسِ ٱللَّوَّامَةِ', 'ولا أقسم بالنفس اللوامة', NULL, 577, 'local:hafs-text.json'),
  ('hafs-75-3', 'hafs', 75, 3, 'أَيَحْسَبُ ٱلْإِنسَٰنُ أَلَّن نَّجْمَعَ عِظَامَهُۥ', 'أيحسب الإنسن ألن نجمع عظامه', NULL, 577, 'local:hafs-text.json'),
  ('hafs-75-4', 'hafs', 75, 4, 'بَلَىٰ قَٰدِرِينَ عَلَىٰٓ أَن نُّسَوِّىَ بَنَانَهُۥ', 'بلى قدرين على أن نسوى بنانه', NULL, 577, 'local:hafs-text.json'),
  ('hafs-75-5', 'hafs', 75, 5, 'بَلْ يُرِيدُ ٱلْإِنسَٰنُ لِيَفْجُرَ أَمَامَهُۥ', 'بل يريد الإنسن ليفجر أمامه', NULL, 577, 'local:hafs-text.json'),
  ('hafs-75-6', 'hafs', 75, 6, 'يَسْـَٔلُ أَيَّانَ يَوْمُ ٱلْقِيَٰمَةِ', 'يسل أيان يوم القيمة', NULL, 577, 'local:hafs-text.json'),
  ('hafs-75-7', 'hafs', 75, 7, 'فَإِذَا بَرِقَ ٱلْبَصَرُ', 'فإذا برق البصر', NULL, 577, 'local:hafs-text.json'),
  ('hafs-75-8', 'hafs', 75, 8, 'وَخَسَفَ ٱلْقَمَرُ', 'وخسف القمر', NULL, 577, 'local:hafs-text.json'),
  ('hafs-75-9', 'hafs', 75, 9, 'وَجُمِعَ ٱلشَّمْسُ وَٱلْقَمَرُ', 'وجمع الشمس والقمر', NULL, 577, 'local:hafs-text.json'),
  ('hafs-75-10', 'hafs', 75, 10, 'يَقُولُ ٱلْإِنسَٰنُ يَوْمَئِذٍ أَيْنَ ٱلْمَفَرُّ', 'يقول الإنسن يومئذ أين المفر', NULL, 577, 'local:hafs-text.json'),
  ('hafs-75-11', 'hafs', 75, 11, 'كَلَّا لَا وَزَرَ', 'كلا لا وزر', NULL, 577, 'local:hafs-text.json'),
  ('hafs-75-12', 'hafs', 75, 12, 'إِلَىٰ رَبِّكَ يَوْمَئِذٍ ٱلْمُسْتَقَرُّ', 'إلى ربك يومئذ المستقر', NULL, 577, 'local:hafs-text.json'),
  ('hafs-75-13', 'hafs', 75, 13, 'يُنَبَّؤُا۟ ٱلْإِنسَٰنُ يَوْمَئِذٍۭ بِمَا قَدَّمَ وَأَخَّرَ', 'ينبؤا الإنسن يومئذ بما قدم وأخر', NULL, 577, 'local:hafs-text.json'),
  ('hafs-75-14', 'hafs', 75, 14, 'بَلِ ٱلْإِنسَٰنُ عَلَىٰ نَفْسِهِۦ بَصِيرَةٌۭ', 'بل الإنسن على نفسه بصيرة', NULL, 577, 'local:hafs-text.json'),
  ('hafs-75-15', 'hafs', 75, 15, 'وَلَوْ أَلْقَىٰ مَعَاذِيرَهُۥ', 'ولو ألقى معاذيره', NULL, 577, 'local:hafs-text.json'),
  ('hafs-75-16', 'hafs', 75, 16, 'لَا تُحَرِّكْ بِهِۦ لِسَانَكَ لِتَعْجَلَ بِهِۦٓ', 'لا تحرك به لسانك لتعجل به', NULL, 577, 'local:hafs-text.json'),
  ('hafs-75-17', 'hafs', 75, 17, 'إِنَّ عَلَيْنَا جَمْعَهُۥ وَقُرْءَانَهُۥ', 'إن علينا جمعه وقرءانه', NULL, 577, 'local:hafs-text.json'),
  ('hafs-75-18', 'hafs', 75, 18, 'فَإِذَا قَرَأْنَٰهُ فَٱتَّبِعْ قُرْءَانَهُۥ', 'فإذا قرأنه فاتبع قرءانه', NULL, 577, 'local:hafs-text.json'),
  ('hafs-75-19', 'hafs', 75, 19, 'ثُمَّ إِنَّ عَلَيْنَا بَيَانَهُۥ', 'ثم إن علينا بيانه', NULL, 577, 'local:hafs-text.json'),
  ('hafs-75-20', 'hafs', 75, 20, 'كَلَّا بَلْ تُحِبُّونَ ٱلْعَاجِلَةَ', 'كلا بل تحبون العاجلة', NULL, 578, 'local:hafs-text.json'),
  ('hafs-75-21', 'hafs', 75, 21, 'وَتَذَرُونَ ٱلْءَاخِرَةَ', 'وتذرون الءاخرة', NULL, 578, 'local:hafs-text.json'),
  ('hafs-75-22', 'hafs', 75, 22, 'وُجُوهٌۭ يَوْمَئِذٍۢ نَّاضِرَةٌ', 'وجوه يومئذ ناضرة', NULL, 578, 'local:hafs-text.json'),
  ('hafs-75-23', 'hafs', 75, 23, 'إِلَىٰ رَبِّهَا نَاظِرَةٌۭ', 'إلى ربها ناظرة', NULL, 578, 'local:hafs-text.json'),
  ('hafs-75-24', 'hafs', 75, 24, 'وَوُجُوهٌۭ يَوْمَئِذٍۭ بَاسِرَةٌۭ', 'ووجوه يومئذ باسرة', NULL, 578, 'local:hafs-text.json'),
  ('hafs-75-25', 'hafs', 75, 25, 'تَظُنُّ أَن يُفْعَلَ بِهَا فَاقِرَةٌۭ', 'تظن أن يفعل بها فاقرة', NULL, 578, 'local:hafs-text.json'),
  ('hafs-75-26', 'hafs', 75, 26, 'كَلَّآ إِذَا بَلَغَتِ ٱلتَّرَاقِىَ', 'كلا إذا بلغت التراقى', NULL, 578, 'local:hafs-text.json'),
  ('hafs-75-27', 'hafs', 75, 27, 'وَقِيلَ مَنْ ۜ رَاقٍۢ', 'وقيل من  راق', NULL, 578, 'local:hafs-text.json'),
  ('hafs-75-28', 'hafs', 75, 28, 'وَظَنَّ أَنَّهُ ٱلْفِرَاقُ', 'وظن أنه الفراق', NULL, 578, 'local:hafs-text.json'),
  ('hafs-75-29', 'hafs', 75, 29, 'وَٱلْتَفَّتِ ٱلسَّاقُ بِٱلسَّاقِ', 'والتفت الساق بالساق', NULL, 578, 'local:hafs-text.json'),
  ('hafs-75-30', 'hafs', 75, 30, 'إِلَىٰ رَبِّكَ يَوْمَئِذٍ ٱلْمَسَاقُ', 'إلى ربك يومئذ المساق', NULL, 578, 'local:hafs-text.json'),
  ('hafs-75-31', 'hafs', 75, 31, 'فَلَا صَدَّقَ وَلَا صَلَّىٰ', 'فلا صدق ولا صلى', NULL, 578, 'local:hafs-text.json'),
  ('hafs-75-32', 'hafs', 75, 32, 'وَلَٰكِن كَذَّبَ وَتَوَلَّىٰ', 'ولكن كذب وتولى', NULL, 578, 'local:hafs-text.json'),
  ('hafs-75-33', 'hafs', 75, 33, 'ثُمَّ ذَهَبَ إِلَىٰٓ أَهْلِهِۦ يَتَمَطَّىٰٓ', 'ثم ذهب إلى أهله يتمطى', NULL, 578, 'local:hafs-text.json'),
  ('hafs-75-34', 'hafs', 75, 34, 'أَوْلَىٰ لَكَ فَأَوْلَىٰ', 'أولى لك فأولى', NULL, 578, 'local:hafs-text.json'),
  ('hafs-75-35', 'hafs', 75, 35, 'ثُمَّ أَوْلَىٰ لَكَ فَأَوْلَىٰٓ', 'ثم أولى لك فأولى', NULL, 578, 'local:hafs-text.json'),
  ('hafs-75-36', 'hafs', 75, 36, 'أَيَحْسَبُ ٱلْإِنسَٰنُ أَن يُتْرَكَ سُدًى', 'أيحسب الإنسن أن يترك سدى', NULL, 578, 'local:hafs-text.json'),
  ('hafs-75-37', 'hafs', 75, 37, 'أَلَمْ يَكُ نُطْفَةًۭ مِّن مَّنِىٍّۢ يُمْنَىٰ', 'ألم يك نطفة من منى يمنى', NULL, 578, 'local:hafs-text.json'),
  ('hafs-75-38', 'hafs', 75, 38, 'ثُمَّ كَانَ عَلَقَةًۭ فَخَلَقَ فَسَوَّىٰ', 'ثم كان علقة فخلق فسوى', NULL, 578, 'local:hafs-text.json'),
  ('hafs-75-39', 'hafs', 75, 39, 'فَجَعَلَ مِنْهُ ٱلزَّوْجَيْنِ ٱلذَّكَرَ وَٱلْأُنثَىٰٓ', 'فجعل منه الزوجين الذكر والأنثى', NULL, 578, 'local:hafs-text.json'),
  ('hafs-75-40', 'hafs', 75, 40, 'أَلَيْسَ ذَٰلِكَ بِقَٰدِرٍ عَلَىٰٓ أَن يُحْۦِىَ ٱلْمَوْتَىٰ', 'أليس ذلك بقدر على أن يحى الموتى', NULL, 578, 'local:hafs-text.json'),
  ('hafs-76-1', 'hafs', 76, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ هَلْ أَتَىٰ عَلَى ٱلْإِنسَٰنِ حِينٌۭ مِّنَ ٱلدَّهْرِ لَمْ يَكُن شَيْـًۭٔا مَّذْكُورًا', 'بسم الله الرحمن الرحيم هل أتى على الإنسن حين من الدهر لم يكن شيا مذكورا', NULL, 578, 'local:hafs-text.json'),
  ('hafs-76-2', 'hafs', 76, 2, 'إِنَّا خَلَقْنَا ٱلْإِنسَٰنَ مِن نُّطْفَةٍ أَمْشَاجٍۢ نَّبْتَلِيهِ فَجَعَلْنَٰهُ سَمِيعًۢا بَصِيرًا', 'إنا خلقنا الإنسن من نطفة أمشاج نبتليه فجعلنه سميعا بصيرا', NULL, 578, 'local:hafs-text.json'),
  ('hafs-76-3', 'hafs', 76, 3, 'إِنَّا هَدَيْنَٰهُ ٱلسَّبِيلَ إِمَّا شَاكِرًۭا وَإِمَّا كَفُورًا', 'إنا هدينه السبيل إما شاكرا وإما كفورا', NULL, 578, 'local:hafs-text.json'),
  ('hafs-76-4', 'hafs', 76, 4, 'إِنَّآ أَعْتَدْنَا لِلْكَٰفِرِينَ سَلَٰسِلَا۟ وَأَغْلَٰلًۭا وَسَعِيرًا', 'إنا أعتدنا للكفرين سلسلا وأغللا وسعيرا', NULL, 578, 'local:hafs-text.json'),
  ('hafs-76-5', 'hafs', 76, 5, 'إِنَّ ٱلْأَبْرَارَ يَشْرَبُونَ مِن كَأْسٍۢ كَانَ مِزَاجُهَا كَافُورًا', 'إن الأبرار يشربون من كأس كان مزاجها كافورا', NULL, 578, 'local:hafs-text.json'),
  ('hafs-76-6', 'hafs', 76, 6, 'عَيْنًۭا يَشْرَبُ بِهَا عِبَادُ ٱللَّهِ يُفَجِّرُونَهَا تَفْجِيرًۭا', 'عينا يشرب بها عباد الله يفجرونها تفجيرا', NULL, 579, 'local:hafs-text.json'),
  ('hafs-76-7', 'hafs', 76, 7, 'يُوفُونَ بِٱلنَّذْرِ وَيَخَافُونَ يَوْمًۭا كَانَ شَرُّهُۥ مُسْتَطِيرًۭا', 'يوفون بالنذر ويخافون يوما كان شره مستطيرا', NULL, 579, 'local:hafs-text.json'),
  ('hafs-76-8', 'hafs', 76, 8, 'وَيُطْعِمُونَ ٱلطَّعَامَ عَلَىٰ حُبِّهِۦ مِسْكِينًۭا وَيَتِيمًۭا وَأَسِيرًا', 'ويطعمون الطعام على حبه مسكينا ويتيما وأسيرا', NULL, 579, 'local:hafs-text.json'),
  ('hafs-76-9', 'hafs', 76, 9, 'إِنَّمَا نُطْعِمُكُمْ لِوَجْهِ ٱللَّهِ لَا نُرِيدُ مِنكُمْ جَزَآءًۭ وَلَا شُكُورًا', 'إنما نطعمكم لوجه الله لا نريد منكم جزاء ولا شكورا', NULL, 579, 'local:hafs-text.json')
insert into public.ayahs (id, riwayah, surah_number, ayah_number, text, simple_text, juz, page, source) values
  ('hafs-76-10', 'hafs', 76, 10, 'إِنَّا نَخَافُ مِن رَّبِّنَا يَوْمًا عَبُوسًۭا قَمْطَرِيرًۭا', 'إنا نخاف من ربنا يوما عبوسا قمطريرا', NULL, 579, 'local:hafs-text.json'),
  ('hafs-76-11', 'hafs', 76, 11, 'فَوَقَىٰهُمُ ٱللَّهُ شَرَّ ذَٰلِكَ ٱلْيَوْمِ وَلَقَّىٰهُمْ نَضْرَةًۭ وَسُرُورًۭا', 'فوقىهم الله شر ذلك اليوم ولقىهم نضرة وسرورا', NULL, 579, 'local:hafs-text.json'),
  ('hafs-76-12', 'hafs', 76, 12, 'وَجَزَىٰهُم بِمَا صَبَرُوا۟ جَنَّةًۭ وَحَرِيرًۭا', 'وجزىهم بما صبروا جنة وحريرا', NULL, 579, 'local:hafs-text.json'),
  ('hafs-76-13', 'hafs', 76, 13, 'مُّتَّكِـِٔينَ فِيهَا عَلَى ٱلْأَرَآئِكِ ۖ لَا يَرَوْنَ فِيهَا شَمْسًۭا وَلَا زَمْهَرِيرًۭا', 'متكين فيها على الأرائك  لا يرون فيها شمسا ولا زمهريرا', NULL, 579, 'local:hafs-text.json'),
  ('hafs-76-14', 'hafs', 76, 14, 'وَدَانِيَةً عَلَيْهِمْ ظِلَٰلُهَا وَذُلِّلَتْ قُطُوفُهَا تَذْلِيلًۭا', 'ودانية عليهم ظللها وذللت قطوفها تذليلا', NULL, 579, 'local:hafs-text.json'),
  ('hafs-76-15', 'hafs', 76, 15, 'وَيُطَافُ عَلَيْهِم بِـَٔانِيَةٍۢ مِّن فِضَّةٍۢ وَأَكْوَابٍۢ كَانَتْ قَوَارِيرَا۠', 'ويطاف عليهم بانية من فضة وأكواب كانت قواريرا', NULL, 579, 'local:hafs-text.json'),
  ('hafs-76-16', 'hafs', 76, 16, 'قَوَارِيرَا۟ مِن فِضَّةٍۢ قَدَّرُوهَا تَقْدِيرًۭا', 'قواريرا من فضة قدروها تقديرا', NULL, 579, 'local:hafs-text.json'),
  ('hafs-76-17', 'hafs', 76, 17, 'وَيُسْقَوْنَ فِيهَا كَأْسًۭا كَانَ مِزَاجُهَا زَنجَبِيلًا', 'ويسقون فيها كأسا كان مزاجها زنجبيلا', NULL, 579, 'local:hafs-text.json'),
  ('hafs-76-18', 'hafs', 76, 18, 'عَيْنًۭا فِيهَا تُسَمَّىٰ سَلْسَبِيلًۭا', 'عينا فيها تسمى سلسبيلا', NULL, 579, 'local:hafs-text.json'),
  ('hafs-76-19', 'hafs', 76, 19, '۞ وَيَطُوفُ عَلَيْهِمْ وِلْدَٰنٌۭ مُّخَلَّدُونَ إِذَا رَأَيْتَهُمْ حَسِبْتَهُمْ لُؤْلُؤًۭا مَّنثُورًۭا', 'ويطوف عليهم ولدن مخلدون إذا رأيتهم حسبتهم لؤلؤا منثورا', NULL, 579, 'local:hafs-text.json'),
  ('hafs-76-20', 'hafs', 76, 20, 'وَإِذَا رَأَيْتَ ثَمَّ رَأَيْتَ نَعِيمًۭا وَمُلْكًۭا كَبِيرًا', 'وإذا رأيت ثم رأيت نعيما وملكا كبيرا', NULL, 579, 'local:hafs-text.json'),
  ('hafs-76-21', 'hafs', 76, 21, 'عَٰلِيَهُمْ ثِيَابُ سُندُسٍ خُضْرٌۭ وَإِسْتَبْرَقٌۭ ۖ وَحُلُّوٓا۟ أَسَاوِرَ مِن فِضَّةٍۢ وَسَقَىٰهُمْ رَبُّهُمْ شَرَابًۭا طَهُورًا', 'عليهم ثياب سندس خضر وإستبرق  وحلوا أساور من فضة وسقىهم ربهم شرابا طهورا', NULL, 579, 'local:hafs-text.json'),
  ('hafs-76-22', 'hafs', 76, 22, 'إِنَّ هَٰذَا كَانَ لَكُمْ جَزَآءًۭ وَكَانَ سَعْيُكُم مَّشْكُورًا', 'إن هذا كان لكم جزاء وكان سعيكم مشكورا', NULL, 579, 'local:hafs-text.json'),
  ('hafs-76-23', 'hafs', 76, 23, 'إِنَّا نَحْنُ نَزَّلْنَا عَلَيْكَ ٱلْقُرْءَانَ تَنزِيلًۭا', 'إنا نحن نزلنا عليك القرءان تنزيلا', NULL, 579, 'local:hafs-text.json'),
  ('hafs-76-24', 'hafs', 76, 24, 'فَٱصْبِرْ لِحُكْمِ رَبِّكَ وَلَا تُطِعْ مِنْهُمْ ءَاثِمًا أَوْ كَفُورًۭا', 'فاصبر لحكم ربك ولا تطع منهم ءاثما أو كفورا', NULL, 579, 'local:hafs-text.json'),
  ('hafs-76-25', 'hafs', 76, 25, 'وَٱذْكُرِ ٱسْمَ رَبِّكَ بُكْرَةًۭ وَأَصِيلًۭا', 'واذكر اسم ربك بكرة وأصيلا', NULL, 579, 'local:hafs-text.json'),
  ('hafs-76-26', 'hafs', 76, 26, 'وَمِنَ ٱلَّيْلِ فَٱسْجُدْ لَهُۥ وَسَبِّحْهُ لَيْلًۭا طَوِيلًا', 'ومن اليل فاسجد له وسبحه ليلا طويلا', NULL, 580, 'local:hafs-text.json'),
  ('hafs-76-27', 'hafs', 76, 27, 'إِنَّ هَٰٓؤُلَآءِ يُحِبُّونَ ٱلْعَاجِلَةَ وَيَذَرُونَ وَرَآءَهُمْ يَوْمًۭا ثَقِيلًۭا', 'إن هؤلاء يحبون العاجلة ويذرون وراءهم يوما ثقيلا', NULL, 580, 'local:hafs-text.json'),
  ('hafs-76-28', 'hafs', 76, 28, 'نَّحْنُ خَلَقْنَٰهُمْ وَشَدَدْنَآ أَسْرَهُمْ ۖ وَإِذَا شِئْنَا بَدَّلْنَآ أَمْثَٰلَهُمْ تَبْدِيلًا', 'نحن خلقنهم وشددنا أسرهم  وإذا شئنا بدلنا أمثلهم تبديلا', NULL, 580, 'local:hafs-text.json'),
  ('hafs-76-29', 'hafs', 76, 29, 'إِنَّ هَٰذِهِۦ تَذْكِرَةٌۭ ۖ فَمَن شَآءَ ٱتَّخَذَ إِلَىٰ رَبِّهِۦ سَبِيلًۭا', 'إن هذه تذكرة  فمن شاء اتخذ إلى ربه سبيلا', NULL, 580, 'local:hafs-text.json'),
  ('hafs-76-30', 'hafs', 76, 30, 'وَمَا تَشَآءُونَ إِلَّآ أَن يَشَآءَ ٱللَّهُ ۚ إِنَّ ٱللَّهَ كَانَ عَلِيمًا حَكِيمًۭا', 'وما تشاءون إلا أن يشاء الله  إن الله كان عليما حكيما', NULL, 580, 'local:hafs-text.json'),
  ('hafs-76-31', 'hafs', 76, 31, 'يُدْخِلُ مَن يَشَآءُ فِى رَحْمَتِهِۦ ۚ وَٱلظَّٰلِمِينَ أَعَدَّ لَهُمْ عَذَابًا أَلِيمًۢا', 'يدخل من يشاء فى رحمته  والظلمين أعد لهم عذابا أليما', NULL, 580, 'local:hafs-text.json'),
  ('hafs-77-1', 'hafs', 77, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ وَٱلْمُرْسَلَٰتِ عُرْفًۭا', 'بسم الله الرحمن الرحيم والمرسلت عرفا', NULL, 580, 'local:hafs-text.json'),
