  ('hafs-78-18', 'hafs', 78, 18, 'يَوْمَ يُنفَخُ فِى ٱلصُّورِ فَتَأْتُونَ أَفْوَاجًۭا', 'يوم ينفخ فى الصور فتأتون أفواجا', NULL, 582, 'local:hafs-text.json'),
  ('hafs-78-19', 'hafs', 78, 19, 'وَفُتِحَتِ ٱلسَّمَآءُ فَكَانَتْ أَبْوَٰبًۭا', 'وفتحت السماء فكانت أبوبا', NULL, 582, 'local:hafs-text.json'),
  ('hafs-78-20', 'hafs', 78, 20, 'وَسُيِّرَتِ ٱلْجِبَالُ فَكَانَتْ سَرَابًا', 'وسيرت الجبال فكانت سرابا', NULL, 582, 'local:hafs-text.json'),
  ('hafs-78-21', 'hafs', 78, 21, 'إِنَّ جَهَنَّمَ كَانَتْ مِرْصَادًۭا', 'إن جهنم كانت مرصادا', NULL, 582, 'local:hafs-text.json'),
  ('hafs-78-22', 'hafs', 78, 22, 'لِّلطَّٰغِينَ مَـَٔابًۭا', 'للطغين مابا', NULL, 582, 'local:hafs-text.json'),
  ('hafs-78-23', 'hafs', 78, 23, 'لَّٰبِثِينَ فِيهَآ أَحْقَابًۭا', 'لبثين فيها أحقابا', NULL, 582, 'local:hafs-text.json'),
  ('hafs-78-24', 'hafs', 78, 24, 'لَّا يَذُوقُونَ فِيهَا بَرْدًۭا وَلَا شَرَابًا', 'لا يذوقون فيها بردا ولا شرابا', NULL, 582, 'local:hafs-text.json'),
  ('hafs-78-25', 'hafs', 78, 25, 'إِلَّا حَمِيمًۭا وَغَسَّاقًۭا', 'إلا حميما وغساقا', NULL, 582, 'local:hafs-text.json'),
  ('hafs-78-26', 'hafs', 78, 26, 'جَزَآءًۭ وِفَاقًا', 'جزاء وفاقا', NULL, 582, 'local:hafs-text.json'),
  ('hafs-78-27', 'hafs', 78, 27, 'إِنَّهُمْ كَانُوا۟ لَا يَرْجُونَ حِسَابًۭا', 'إنهم كانوا لا يرجون حسابا', NULL, 582, 'local:hafs-text.json'),
  ('hafs-78-28', 'hafs', 78, 28, 'وَكَذَّبُوا۟ بِـَٔايَٰتِنَا كِذَّابًۭا', 'وكذبوا بايتنا كذابا', NULL, 582, 'local:hafs-text.json'),
  ('hafs-78-29', 'hafs', 78, 29, 'وَكُلَّ شَىْءٍ أَحْصَيْنَٰهُ كِتَٰبًۭا', 'وكل شىء أحصينه كتبا', NULL, 582, 'local:hafs-text.json'),
  ('hafs-78-30', 'hafs', 78, 30, 'فَذُوقُوا۟ فَلَن نَّزِيدَكُمْ إِلَّا عَذَابًا', 'فذوقوا فلن نزيدكم إلا عذابا', NULL, 582, 'local:hafs-text.json'),
  ('hafs-78-31', 'hafs', 78, 31, 'إِنَّ لِلْمُتَّقِينَ مَفَازًا', 'إن للمتقين مفازا', NULL, 583, 'local:hafs-text.json'),
  ('hafs-78-32', 'hafs', 78, 32, 'حَدَآئِقَ وَأَعْنَٰبًۭا', 'حدائق وأعنبا', NULL, 583, 'local:hafs-text.json'),
  ('hafs-78-33', 'hafs', 78, 33, 'وَكَوَاعِبَ أَتْرَابًۭا', 'وكواعب أترابا', NULL, 583, 'local:hafs-text.json'),
  ('hafs-78-34', 'hafs', 78, 34, 'وَكَأْسًۭا دِهَاقًۭا', 'وكأسا دهاقا', NULL, 583, 'local:hafs-text.json'),
  ('hafs-78-35', 'hafs', 78, 35, 'لَّا يَسْمَعُونَ فِيهَا لَغْوًۭا وَلَا كِذَّٰبًۭا', 'لا يسمعون فيها لغوا ولا كذبا', NULL, 583, 'local:hafs-text.json'),
  ('hafs-78-36', 'hafs', 78, 36, 'جَزَآءًۭ مِّن رَّبِّكَ عَطَآءً حِسَابًۭا', 'جزاء من ربك عطاء حسابا', NULL, 583, 'local:hafs-text.json'),
  ('hafs-78-37', 'hafs', 78, 37, 'رَّبِّ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَمَا بَيْنَهُمَا ٱلرَّحْمَٰنِ ۖ لَا يَمْلِكُونَ مِنْهُ خِطَابًۭا', 'رب السموت والأرض وما بينهما الرحمن  لا يملكون منه خطابا', NULL, 583, 'local:hafs-text.json'),
  ('hafs-78-38', 'hafs', 78, 38, 'يَوْمَ يَقُومُ ٱلرُّوحُ وَٱلْمَلَٰٓئِكَةُ صَفًّۭا ۖ لَّا يَتَكَلَّمُونَ إِلَّا مَنْ أَذِنَ لَهُ ٱلرَّحْمَٰنُ وَقَالَ صَوَابًۭا', 'يوم يقوم الروح والملئكة صفا  لا يتكلمون إلا من أذن له الرحمن وقال صوابا', NULL, 583, 'local:hafs-text.json'),
  ('hafs-78-39', 'hafs', 78, 39, 'ذَٰلِكَ ٱلْيَوْمُ ٱلْحَقُّ ۖ فَمَن شَآءَ ٱتَّخَذَ إِلَىٰ رَبِّهِۦ مَـَٔابًا', 'ذلك اليوم الحق  فمن شاء اتخذ إلى ربه مابا', NULL, 583, 'local:hafs-text.json'),
  ('hafs-78-40', 'hafs', 78, 40, 'إِنَّآ أَنذَرْنَٰكُمْ عَذَابًۭا قَرِيبًۭا يَوْمَ يَنظُرُ ٱلْمَرْءُ مَا قَدَّمَتْ يَدَاهُ وَيَقُولُ ٱلْكَافِرُ يَٰلَيْتَنِى كُنتُ تُرَٰبًۢا', 'إنا أنذرنكم عذابا قريبا يوم ينظر المرء ما قدمت يداه ويقول الكافر يليتنى كنت تربا', NULL, 583, 'local:hafs-text.json'),
  ('hafs-79-1', 'hafs', 79, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ وَٱلنَّٰزِعَٰتِ غَرْقًۭا', 'بسم الله الرحمن الرحيم والنزعت غرقا', NULL, 583, 'local:hafs-text.json'),
  ('hafs-79-2', 'hafs', 79, 2, 'وَٱلنَّٰشِطَٰتِ نَشْطًۭا', 'والنشطت نشطا', NULL, 583, 'local:hafs-text.json'),
  ('hafs-79-3', 'hafs', 79, 3, 'وَٱلسَّٰبِحَٰتِ سَبْحًۭا', 'والسبحت سبحا', NULL, 583, 'local:hafs-text.json'),
  ('hafs-79-4', 'hafs', 79, 4, 'فَٱلسَّٰبِقَٰتِ سَبْقًۭا', 'فالسبقت سبقا', NULL, 583, 'local:hafs-text.json'),
  ('hafs-79-5', 'hafs', 79, 5, 'فَٱلْمُدَبِّرَٰتِ أَمْرًۭا', 'فالمدبرت أمرا', NULL, 583, 'local:hafs-text.json'),
  ('hafs-79-6', 'hafs', 79, 6, 'يَوْمَ تَرْجُفُ ٱلرَّاجِفَةُ', 'يوم ترجف الراجفة', NULL, 583, 'local:hafs-text.json'),
  ('hafs-79-7', 'hafs', 79, 7, 'تَتْبَعُهَا ٱلرَّادِفَةُ', 'تتبعها الرادفة', NULL, 583, 'local:hafs-text.json'),
  ('hafs-79-8', 'hafs', 79, 8, 'قُلُوبٌۭ يَوْمَئِذٍۢ وَاجِفَةٌ', 'قلوب يومئذ واجفة', NULL, 583, 'local:hafs-text.json'),
  ('hafs-79-9', 'hafs', 79, 9, 'أَبْصَٰرُهَا خَٰشِعَةٌۭ', 'أبصرها خشعة', NULL, 583, 'local:hafs-text.json'),
  ('hafs-79-10', 'hafs', 79, 10, 'يَقُولُونَ أَءِنَّا لَمَرْدُودُونَ فِى ٱلْحَافِرَةِ', 'يقولون أءنا لمردودون فى الحافرة', NULL, 583, 'local:hafs-text.json'),
  ('hafs-79-11', 'hafs', 79, 11, 'أَءِذَا كُنَّا عِظَٰمًۭا نَّخِرَةًۭ', 'أءذا كنا عظما نخرة', NULL, 583, 'local:hafs-text.json'),
  ('hafs-79-12', 'hafs', 79, 12, 'قَالُوا۟ تِلْكَ إِذًۭا كَرَّةٌ خَاسِرَةٌۭ', 'قالوا تلك إذا كرة خاسرة', NULL, 583, 'local:hafs-text.json'),
  ('hafs-79-13', 'hafs', 79, 13, 'فَإِنَّمَا هِىَ زَجْرَةٌۭ وَٰحِدَةٌۭ', 'فإنما هى زجرة وحدة', NULL, 583, 'local:hafs-text.json'),
  ('hafs-79-14', 'hafs', 79, 14, 'فَإِذَا هُم بِٱلسَّاهِرَةِ', 'فإذا هم بالساهرة', NULL, 583, 'local:hafs-text.json'),
  ('hafs-79-15', 'hafs', 79, 15, 'هَلْ أَتَىٰكَ حَدِيثُ مُوسَىٰٓ', 'هل أتىك حديث موسى', NULL, 583, 'local:hafs-text.json'),
  ('hafs-79-16', 'hafs', 79, 16, 'إِذْ نَادَىٰهُ رَبُّهُۥ بِٱلْوَادِ ٱلْمُقَدَّسِ طُوًى', 'إذ نادىه ربه بالواد المقدس طوى', NULL, 584, 'local:hafs-text.json'),
  ('hafs-79-17', 'hafs', 79, 17, 'ٱذْهَبْ إِلَىٰ فِرْعَوْنَ إِنَّهُۥ طَغَىٰ', 'اذهب إلى فرعون إنه طغى', NULL, 584, 'local:hafs-text.json'),
  ('hafs-79-18', 'hafs', 79, 18, 'فَقُلْ هَل لَّكَ إِلَىٰٓ أَن تَزَكَّىٰ', 'فقل هل لك إلى أن تزكى', NULL, 584, 'local:hafs-text.json'),
  ('hafs-79-19', 'hafs', 79, 19, 'وَأَهْدِيَكَ إِلَىٰ رَبِّكَ فَتَخْشَىٰ', 'وأهديك إلى ربك فتخشى', NULL, 584, 'local:hafs-text.json'),
  ('hafs-79-20', 'hafs', 79, 20, 'فَأَرَىٰهُ ٱلْءَايَةَ ٱلْكُبْرَىٰ', 'فأرىه الءاية الكبرى', NULL, 584, 'local:hafs-text.json'),
  ('hafs-79-21', 'hafs', 79, 21, 'فَكَذَّبَ وَعَصَىٰ', 'فكذب وعصى', NULL, 584, 'local:hafs-text.json'),
  ('hafs-79-22', 'hafs', 79, 22, 'ثُمَّ أَدْبَرَ يَسْعَىٰ', 'ثم أدبر يسعى', NULL, 584, 'local:hafs-text.json'),
  ('hafs-79-23', 'hafs', 79, 23, 'فَحَشَرَ فَنَادَىٰ', 'فحشر فنادى', NULL, 584, 'local:hafs-text.json'),
  ('hafs-79-24', 'hafs', 79, 24, 'فَقَالَ أَنَا۠ رَبُّكُمُ ٱلْأَعْلَىٰ', 'فقال أنا ربكم الأعلى', NULL, 584, 'local:hafs-text.json'),
  ('hafs-79-25', 'hafs', 79, 25, 'فَأَخَذَهُ ٱللَّهُ نَكَالَ ٱلْءَاخِرَةِ وَٱلْأُولَىٰٓ', 'فأخذه الله نكال الءاخرة والأولى', NULL, 584, 'local:hafs-text.json'),
  ('hafs-79-26', 'hafs', 79, 26, 'إِنَّ فِى ذَٰلِكَ لَعِبْرَةًۭ لِّمَن يَخْشَىٰٓ', 'إن فى ذلك لعبرة لمن يخشى', NULL, 584, 'local:hafs-text.json'),
  ('hafs-79-27', 'hafs', 79, 27, 'ءَأَنتُمْ أَشَدُّ خَلْقًا أَمِ ٱلسَّمَآءُ ۚ بَنَىٰهَا', 'ءأنتم أشد خلقا أم السماء  بنىها', NULL, 584, 'local:hafs-text.json'),
  ('hafs-79-28', 'hafs', 79, 28, 'رَفَعَ سَمْكَهَا فَسَوَّىٰهَا', 'رفع سمكها فسوىها', NULL, 584, 'local:hafs-text.json'),
  ('hafs-79-29', 'hafs', 79, 29, 'وَأَغْطَشَ لَيْلَهَا وَأَخْرَجَ ضُحَىٰهَا', 'وأغطش ليلها وأخرج ضحىها', NULL, 584, 'local:hafs-text.json'),
  ('hafs-79-30', 'hafs', 79, 30, 'وَٱلْأَرْضَ بَعْدَ ذَٰلِكَ دَحَىٰهَآ', 'والأرض بعد ذلك دحىها', NULL, 584, 'local:hafs-text.json'),
  ('hafs-79-31', 'hafs', 79, 31, 'أَخْرَجَ مِنْهَا مَآءَهَا وَمَرْعَىٰهَا', 'أخرج منها ماءها ومرعىها', NULL, 584, 'local:hafs-text.json'),
  ('hafs-79-32', 'hafs', 79, 32, 'وَٱلْجِبَالَ أَرْسَىٰهَا', 'والجبال أرسىها', NULL, 584, 'local:hafs-text.json'),
  ('hafs-79-33', 'hafs', 79, 33, 'مَتَٰعًۭا لَّكُمْ وَلِأَنْعَٰمِكُمْ', 'متعا لكم ولأنعمكم', NULL, 584, 'local:hafs-text.json'),
  ('hafs-79-34', 'hafs', 79, 34, 'فَإِذَا جَآءَتِ ٱلطَّآمَّةُ ٱلْكُبْرَىٰ', 'فإذا جاءت الطامة الكبرى', NULL, 584, 'local:hafs-text.json'),
  ('hafs-79-35', 'hafs', 79, 35, 'يَوْمَ يَتَذَكَّرُ ٱلْإِنسَٰنُ مَا سَعَىٰ', 'يوم يتذكر الإنسن ما سعى', NULL, 584, 'local:hafs-text.json'),
  ('hafs-79-36', 'hafs', 79, 36, 'وَبُرِّزَتِ ٱلْجَحِيمُ لِمَن يَرَىٰ', 'وبرزت الجحيم لمن يرى', NULL, 584, 'local:hafs-text.json'),
  ('hafs-79-37', 'hafs', 79, 37, 'فَأَمَّا مَن طَغَىٰ', 'فأما من طغى', NULL, 584, 'local:hafs-text.json'),
  ('hafs-79-38', 'hafs', 79, 38, 'وَءَاثَرَ ٱلْحَيَوٰةَ ٱلدُّنْيَا', 'وءاثر الحيوة الدنيا', NULL, 584, 'local:hafs-text.json'),
  ('hafs-79-39', 'hafs', 79, 39, 'فَإِنَّ ٱلْجَحِيمَ هِىَ ٱلْمَأْوَىٰ', 'فإن الجحيم هى المأوى', NULL, 584, 'local:hafs-text.json'),
  ('hafs-79-40', 'hafs', 79, 40, 'وَأَمَّا مَنْ خَافَ مَقَامَ رَبِّهِۦ وَنَهَى ٱلنَّفْسَ عَنِ ٱلْهَوَىٰ', 'وأما من خاف مقام ربه ونهى النفس عن الهوى', NULL, 584, 'local:hafs-text.json'),
  ('hafs-79-41', 'hafs', 79, 41, 'فَإِنَّ ٱلْجَنَّةَ هِىَ ٱلْمَأْوَىٰ', 'فإن الجنة هى المأوى', NULL, 584, 'local:hafs-text.json'),
  ('hafs-79-42', 'hafs', 79, 42, 'يَسْـَٔلُونَكَ عَنِ ٱلسَّاعَةِ أَيَّانَ مُرْسَىٰهَا', 'يسلونك عن الساعة أيان مرسىها', NULL, 584, 'local:hafs-text.json'),
  ('hafs-79-43', 'hafs', 79, 43, 'فِيمَ أَنتَ مِن ذِكْرَىٰهَآ', 'فيم أنت من ذكرىها', NULL, 584, 'local:hafs-text.json'),
  ('hafs-79-44', 'hafs', 79, 44, 'إِلَىٰ رَبِّكَ مُنتَهَىٰهَآ', 'إلى ربك منتهىها', NULL, 584, 'local:hafs-text.json'),
  ('hafs-79-45', 'hafs', 79, 45, 'إِنَّمَآ أَنتَ مُنذِرُ مَن يَخْشَىٰهَا', 'إنما أنت منذر من يخشىها', NULL, 584, 'local:hafs-text.json'),
  ('hafs-79-46', 'hafs', 79, 46, 'كَأَنَّهُمْ يَوْمَ يَرَوْنَهَا لَمْ يَلْبَثُوٓا۟ إِلَّا عَشِيَّةً أَوْ ضُحَىٰهَا', 'كأنهم يوم يرونها لم يلبثوا إلا عشية أو ضحىها', NULL, 584, 'local:hafs-text.json'),
  ('hafs-80-1', 'hafs', 80, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ عَبَسَ وَتَوَلَّىٰٓ', 'بسم الله الرحمن الرحيم عبس وتولى', NULL, 585, 'local:hafs-text.json'),
  ('hafs-80-2', 'hafs', 80, 2, 'أَن جَآءَهُ ٱلْأَعْمَىٰ', 'أن جاءه الأعمى', NULL, 585, 'local:hafs-text.json'),
  ('hafs-80-3', 'hafs', 80, 3, 'وَمَا يُدْرِيكَ لَعَلَّهُۥ يَزَّكَّىٰٓ', 'وما يدريك لعله يزكى', NULL, 585, 'local:hafs-text.json'),
  ('hafs-80-4', 'hafs', 80, 4, 'أَوْ يَذَّكَّرُ فَتَنفَعَهُ ٱلذِّكْرَىٰٓ', 'أو يذكر فتنفعه الذكرى', NULL, 585, 'local:hafs-text.json'),
  ('hafs-80-5', 'hafs', 80, 5, 'أَمَّا مَنِ ٱسْتَغْنَىٰ', 'أما من استغنى', NULL, 585, 'local:hafs-text.json'),
