  ('hafs-82-19', 'hafs', 82, 19, 'يَوْمَ لَا تَمْلِكُ نَفْسٌۭ لِّنَفْسٍۢ شَيْـًۭٔا ۖ وَٱلْأَمْرُ يَوْمَئِذٍۢ لِّلَّهِ', 'يوم لا تملك نفس لنفس شيا  والأمر يومئذ لله', NULL, 587, 'local:hafs-text.json'),
  ('hafs-83-1', 'hafs', 83, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ وَيْلٌۭ لِّلْمُطَفِّفِينَ', 'بسم الله الرحمن الرحيم ويل للمطففين', NULL, 587, 'local:hafs-text.json'),
  ('hafs-83-2', 'hafs', 83, 2, 'ٱلَّذِينَ إِذَا ٱكْتَالُوا۟ عَلَى ٱلنَّاسِ يَسْتَوْفُونَ', 'الذين إذا اكتالوا على الناس يستوفون', NULL, 587, 'local:hafs-text.json'),
  ('hafs-83-3', 'hafs', 83, 3, 'وَإِذَا كَالُوهُمْ أَو وَّزَنُوهُمْ يُخْسِرُونَ', 'وإذا كالوهم أو وزنوهم يخسرون', NULL, 587, 'local:hafs-text.json'),
  ('hafs-83-4', 'hafs', 83, 4, 'أَلَا يَظُنُّ أُو۟لَٰٓئِكَ أَنَّهُم مَّبْعُوثُونَ', 'ألا يظن أولئك أنهم مبعوثون', NULL, 587, 'local:hafs-text.json'),
  ('hafs-83-5', 'hafs', 83, 5, 'لِيَوْمٍ عَظِيمٍۢ', 'ليوم عظيم', NULL, 587, 'local:hafs-text.json'),
  ('hafs-83-6', 'hafs', 83, 6, 'يَوْمَ يَقُومُ ٱلنَّاسُ لِرَبِّ ٱلْعَٰلَمِينَ', 'يوم يقوم الناس لرب العلمين', NULL, 587, 'local:hafs-text.json'),
  ('hafs-83-7', 'hafs', 83, 7, 'كَلَّآ إِنَّ كِتَٰبَ ٱلْفُجَّارِ لَفِى سِجِّينٍۢ', 'كلا إن كتب الفجار لفى سجين', NULL, 588, 'local:hafs-text.json'),
  ('hafs-83-8', 'hafs', 83, 8, 'وَمَآ أَدْرَىٰكَ مَا سِجِّينٌۭ', 'وما أدرىك ما سجين', NULL, 588, 'local:hafs-text.json'),
  ('hafs-83-9', 'hafs', 83, 9, 'كِتَٰبٌۭ مَّرْقُومٌۭ', 'كتب مرقوم', NULL, 588, 'local:hafs-text.json'),
  ('hafs-83-10', 'hafs', 83, 10, 'وَيْلٌۭ يَوْمَئِذٍۢ لِّلْمُكَذِّبِينَ', 'ويل يومئذ للمكذبين', NULL, 588, 'local:hafs-text.json'),
  ('hafs-83-11', 'hafs', 83, 11, 'ٱلَّذِينَ يُكَذِّبُونَ بِيَوْمِ ٱلدِّينِ', 'الذين يكذبون بيوم الدين', NULL, 588, 'local:hafs-text.json'),
  ('hafs-83-12', 'hafs', 83, 12, 'وَمَا يُكَذِّبُ بِهِۦٓ إِلَّا كُلُّ مُعْتَدٍ أَثِيمٍ', 'وما يكذب به إلا كل معتد أثيم', NULL, 588, 'local:hafs-text.json'),
  ('hafs-83-13', 'hafs', 83, 13, 'إِذَا تُتْلَىٰ عَلَيْهِ ءَايَٰتُنَا قَالَ أَسَٰطِيرُ ٱلْأَوَّلِينَ', 'إذا تتلى عليه ءايتنا قال أسطير الأولين', NULL, 588, 'local:hafs-text.json'),
  ('hafs-83-14', 'hafs', 83, 14, 'كَلَّا ۖ بَلْ ۜ رَانَ عَلَىٰ قُلُوبِهِم مَّا كَانُوا۟ يَكْسِبُونَ', 'كلا  بل  ران على قلوبهم ما كانوا يكسبون', NULL, 588, 'local:hafs-text.json'),
  ('hafs-83-15', 'hafs', 83, 15, 'كَلَّآ إِنَّهُمْ عَن رَّبِّهِمْ يَوْمَئِذٍۢ لَّمَحْجُوبُونَ', 'كلا إنهم عن ربهم يومئذ لمحجوبون', NULL, 588, 'local:hafs-text.json'),
  ('hafs-83-16', 'hafs', 83, 16, 'ثُمَّ إِنَّهُمْ لَصَالُوا۟ ٱلْجَحِيمِ', 'ثم إنهم لصالوا الجحيم', NULL, 588, 'local:hafs-text.json'),
  ('hafs-83-17', 'hafs', 83, 17, 'ثُمَّ يُقَالُ هَٰذَا ٱلَّذِى كُنتُم بِهِۦ تُكَذِّبُونَ', 'ثم يقال هذا الذى كنتم به تكذبون', NULL, 588, 'local:hafs-text.json'),
  ('hafs-83-18', 'hafs', 83, 18, 'كَلَّآ إِنَّ كِتَٰبَ ٱلْأَبْرَارِ لَفِى عِلِّيِّينَ', 'كلا إن كتب الأبرار لفى عليين', NULL, 588, 'local:hafs-text.json'),
  ('hafs-83-19', 'hafs', 83, 19, 'وَمَآ أَدْرَىٰكَ مَا عِلِّيُّونَ', 'وما أدرىك ما عليون', NULL, 588, 'local:hafs-text.json'),
  ('hafs-83-20', 'hafs', 83, 20, 'كِتَٰبٌۭ مَّرْقُومٌۭ', 'كتب مرقوم', NULL, 588, 'local:hafs-text.json'),
  ('hafs-83-21', 'hafs', 83, 21, 'يَشْهَدُهُ ٱلْمُقَرَّبُونَ', 'يشهده المقربون', NULL, 588, 'local:hafs-text.json'),
  ('hafs-83-22', 'hafs', 83, 22, 'إِنَّ ٱلْأَبْرَارَ لَفِى نَعِيمٍ', 'إن الأبرار لفى نعيم', NULL, 588, 'local:hafs-text.json'),
  ('hafs-83-23', 'hafs', 83, 23, 'عَلَى ٱلْأَرَآئِكِ يَنظُرُونَ', 'على الأرائك ينظرون', NULL, 588, 'local:hafs-text.json'),
  ('hafs-83-24', 'hafs', 83, 24, 'تَعْرِفُ فِى وُجُوهِهِمْ نَضْرَةَ ٱلنَّعِيمِ', 'تعرف فى وجوههم نضرة النعيم', NULL, 588, 'local:hafs-text.json'),
  ('hafs-83-25', 'hafs', 83, 25, 'يُسْقَوْنَ مِن رَّحِيقٍۢ مَّخْتُومٍ', 'يسقون من رحيق مختوم', NULL, 588, 'local:hafs-text.json'),
  ('hafs-83-26', 'hafs', 83, 26, 'خِتَٰمُهُۥ مِسْكٌۭ ۚ وَفِى ذَٰلِكَ فَلْيَتَنَافَسِ ٱلْمُتَنَٰفِسُونَ', 'ختمه مسك  وفى ذلك فليتنافس المتنفسون', NULL, 588, 'local:hafs-text.json'),
  ('hafs-83-27', 'hafs', 83, 27, 'وَمِزَاجُهُۥ مِن تَسْنِيمٍ', 'ومزاجه من تسنيم', NULL, 588, 'local:hafs-text.json'),
  ('hafs-83-28', 'hafs', 83, 28, 'عَيْنًۭا يَشْرَبُ بِهَا ٱلْمُقَرَّبُونَ', 'عينا يشرب بها المقربون', NULL, 588, 'local:hafs-text.json'),
  ('hafs-83-29', 'hafs', 83, 29, 'إِنَّ ٱلَّذِينَ أَجْرَمُوا۟ كَانُوا۟ مِنَ ٱلَّذِينَ ءَامَنُوا۟ يَضْحَكُونَ', 'إن الذين أجرموا كانوا من الذين ءامنوا يضحكون', NULL, 588, 'local:hafs-text.json'),
  ('hafs-83-30', 'hafs', 83, 30, 'وَإِذَا مَرُّوا۟ بِهِمْ يَتَغَامَزُونَ', 'وإذا مروا بهم يتغامزون', NULL, 588, 'local:hafs-text.json'),
  ('hafs-83-31', 'hafs', 83, 31, 'وَإِذَا ٱنقَلَبُوٓا۟ إِلَىٰٓ أَهْلِهِمُ ٱنقَلَبُوا۟ فَكِهِينَ', 'وإذا انقلبوا إلى أهلهم انقلبوا فكهين', NULL, 588, 'local:hafs-text.json'),
  ('hafs-83-32', 'hafs', 83, 32, 'وَإِذَا رَأَوْهُمْ قَالُوٓا۟ إِنَّ هَٰٓؤُلَآءِ لَضَآلُّونَ', 'وإذا رأوهم قالوا إن هؤلاء لضالون', NULL, 588, 'local:hafs-text.json'),
  ('hafs-83-33', 'hafs', 83, 33, 'وَمَآ أُرْسِلُوا۟ عَلَيْهِمْ حَٰفِظِينَ', 'وما أرسلوا عليهم حفظين', NULL, 588, 'local:hafs-text.json'),
  ('hafs-83-34', 'hafs', 83, 34, 'فَٱلْيَوْمَ ٱلَّذِينَ ءَامَنُوا۟ مِنَ ٱلْكُفَّارِ يَضْحَكُونَ', 'فاليوم الذين ءامنوا من الكفار يضحكون', NULL, 588, 'local:hafs-text.json'),
  ('hafs-83-35', 'hafs', 83, 35, 'عَلَى ٱلْأَرَآئِكِ يَنظُرُونَ', 'على الأرائك ينظرون', NULL, 589, 'local:hafs-text.json'),
  ('hafs-83-36', 'hafs', 83, 36, 'هَلْ ثُوِّبَ ٱلْكُفَّارُ مَا كَانُوا۟ يَفْعَلُونَ', 'هل ثوب الكفار ما كانوا يفعلون', NULL, 589, 'local:hafs-text.json'),
  ('hafs-84-1', 'hafs', 84, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ إِذَا ٱلسَّمَآءُ ٱنشَقَّتْ', 'بسم الله الرحمن الرحيم إذا السماء انشقت', NULL, 589, 'local:hafs-text.json'),
  ('hafs-84-2', 'hafs', 84, 2, 'وَأَذِنَتْ لِرَبِّهَا وَحُقَّتْ', 'وأذنت لربها وحقت', NULL, 589, 'local:hafs-text.json'),
  ('hafs-84-3', 'hafs', 84, 3, 'وَإِذَا ٱلْأَرْضُ مُدَّتْ', 'وإذا الأرض مدت', NULL, 589, 'local:hafs-text.json'),
  ('hafs-84-4', 'hafs', 84, 4, 'وَأَلْقَتْ مَا فِيهَا وَتَخَلَّتْ', 'وألقت ما فيها وتخلت', NULL, 589, 'local:hafs-text.json'),
  ('hafs-84-5', 'hafs', 84, 5, 'وَأَذِنَتْ لِرَبِّهَا وَحُقَّتْ', 'وأذنت لربها وحقت', NULL, 589, 'local:hafs-text.json'),
  ('hafs-84-6', 'hafs', 84, 6, 'يَٰٓأَيُّهَا ٱلْإِنسَٰنُ إِنَّكَ كَادِحٌ إِلَىٰ رَبِّكَ كَدْحًۭا فَمُلَٰقِيهِ', 'يأيها الإنسن إنك كادح إلى ربك كدحا فملقيه', NULL, 589, 'local:hafs-text.json'),
  ('hafs-84-7', 'hafs', 84, 7, 'فَأَمَّا مَنْ أُوتِىَ كِتَٰبَهُۥ بِيَمِينِهِۦ', 'فأما من أوتى كتبه بيمينه', NULL, 589, 'local:hafs-text.json'),
  ('hafs-84-8', 'hafs', 84, 8, 'فَسَوْفَ يُحَاسَبُ حِسَابًۭا يَسِيرًۭا', 'فسوف يحاسب حسابا يسيرا', NULL, 589, 'local:hafs-text.json'),
  ('hafs-84-9', 'hafs', 84, 9, 'وَيَنقَلِبُ إِلَىٰٓ أَهْلِهِۦ مَسْرُورًۭا', 'وينقلب إلى أهله مسرورا', NULL, 589, 'local:hafs-text.json'),
  ('hafs-84-10', 'hafs', 84, 10, 'وَأَمَّا مَنْ أُوتِىَ كِتَٰبَهُۥ وَرَآءَ ظَهْرِهِۦ', 'وأما من أوتى كتبه وراء ظهره', NULL, 589, 'local:hafs-text.json'),
  ('hafs-84-11', 'hafs', 84, 11, 'فَسَوْفَ يَدْعُوا۟ ثُبُورًۭا', 'فسوف يدعوا ثبورا', NULL, 589, 'local:hafs-text.json'),
  ('hafs-84-12', 'hafs', 84, 12, 'وَيَصْلَىٰ سَعِيرًا', 'ويصلى سعيرا', NULL, 589, 'local:hafs-text.json'),
  ('hafs-84-13', 'hafs', 84, 13, 'إِنَّهُۥ كَانَ فِىٓ أَهْلِهِۦ مَسْرُورًا', 'إنه كان فى أهله مسرورا', NULL, 589, 'local:hafs-text.json'),
  ('hafs-84-14', 'hafs', 84, 14, 'إِنَّهُۥ ظَنَّ أَن لَّن يَحُورَ', 'إنه ظن أن لن يحور', NULL, 589, 'local:hafs-text.json'),
  ('hafs-84-15', 'hafs', 84, 15, 'بَلَىٰٓ إِنَّ رَبَّهُۥ كَانَ بِهِۦ بَصِيرًۭا', 'بلى إن ربه كان به بصيرا', NULL, 589, 'local:hafs-text.json'),
  ('hafs-84-16', 'hafs', 84, 16, 'فَلَآ أُقْسِمُ بِٱلشَّفَقِ', 'فلا أقسم بالشفق', NULL, 589, 'local:hafs-text.json'),
  ('hafs-84-17', 'hafs', 84, 17, 'وَٱلَّيْلِ وَمَا وَسَقَ', 'واليل وما وسق', NULL, 589, 'local:hafs-text.json'),
  ('hafs-84-18', 'hafs', 84, 18, 'وَٱلْقَمَرِ إِذَا ٱتَّسَقَ', 'والقمر إذا اتسق', NULL, 589, 'local:hafs-text.json'),
  ('hafs-84-19', 'hafs', 84, 19, 'لَتَرْكَبُنَّ طَبَقًا عَن طَبَقٍۢ', 'لتركبن طبقا عن طبق', NULL, 589, 'local:hafs-text.json'),
  ('hafs-84-20', 'hafs', 84, 20, 'فَمَا لَهُمْ لَا يُؤْمِنُونَ', 'فما لهم لا يؤمنون', NULL, 589, 'local:hafs-text.json'),
  ('hafs-84-21', 'hafs', 84, 21, 'وَإِذَا قُرِئَ عَلَيْهِمُ ٱلْقُرْءَانُ لَا يَسْجُدُونَ ۩', 'وإذا قرئ عليهم القرءان لا يسجدون', NULL, 589, 'local:hafs-text.json'),
  ('hafs-84-22', 'hafs', 84, 22, 'بَلِ ٱلَّذِينَ كَفَرُوا۟ يُكَذِّبُونَ', 'بل الذين كفروا يكذبون', NULL, 589, 'local:hafs-text.json'),
  ('hafs-84-23', 'hafs', 84, 23, 'وَٱللَّهُ أَعْلَمُ بِمَا يُوعُونَ', 'والله أعلم بما يوعون', NULL, 589, 'local:hafs-text.json'),
  ('hafs-84-24', 'hafs', 84, 24, 'فَبَشِّرْهُم بِعَذَابٍ أَلِيمٍ', 'فبشرهم بعذاب أليم', NULL, 589, 'local:hafs-text.json'),
  ('hafs-84-25', 'hafs', 84, 25, 'إِلَّا ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ لَهُمْ أَجْرٌ غَيْرُ مَمْنُونٍۭ', 'إلا الذين ءامنوا وعملوا الصلحت لهم أجر غير ممنون', NULL, 589, 'local:hafs-text.json'),
  ('hafs-85-1', 'hafs', 85, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ وَٱلسَّمَآءِ ذَاتِ ٱلْبُرُوجِ', 'بسم الله الرحمن الرحيم والسماء ذات البروج', NULL, 590, 'local:hafs-text.json'),
  ('hafs-85-2', 'hafs', 85, 2, 'وَٱلْيَوْمِ ٱلْمَوْعُودِ', 'واليوم الموعود', NULL, 590, 'local:hafs-text.json'),
  ('hafs-85-3', 'hafs', 85, 3, 'وَشَاهِدٍۢ وَمَشْهُودٍۢ', 'وشاهد ومشهود', NULL, 590, 'local:hafs-text.json'),
  ('hafs-85-4', 'hafs', 85, 4, 'قُتِلَ أَصْحَٰبُ ٱلْأُخْدُودِ', 'قتل أصحب الأخدود', NULL, 590, 'local:hafs-text.json'),
  ('hafs-85-5', 'hafs', 85, 5, 'ٱلنَّارِ ذَاتِ ٱلْوَقُودِ', 'النار ذات الوقود', NULL, 590, 'local:hafs-text.json'),
  ('hafs-85-6', 'hafs', 85, 6, 'إِذْ هُمْ عَلَيْهَا قُعُودٌۭ', 'إذ هم عليها قعود', NULL, 590, 'local:hafs-text.json'),
  ('hafs-85-7', 'hafs', 85, 7, 'وَهُمْ عَلَىٰ مَا يَفْعَلُونَ بِٱلْمُؤْمِنِينَ شُهُودٌۭ', 'وهم على ما يفعلون بالمؤمنين شهود', NULL, 590, 'local:hafs-text.json'),
  ('hafs-85-8', 'hafs', 85, 8, 'وَمَا نَقَمُوا۟ مِنْهُمْ إِلَّآ أَن يُؤْمِنُوا۟ بِٱللَّهِ ٱلْعَزِيزِ ٱلْحَمِيدِ', 'وما نقموا منهم إلا أن يؤمنوا بالله العزيز الحميد', NULL, 590, 'local:hafs-text.json'),
  ('hafs-85-9', 'hafs', 85, 9, 'ٱلَّذِى لَهُۥ مُلْكُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ ۚ وَٱللَّهُ عَلَىٰ كُلِّ شَىْءٍۢ شَهِيدٌ', 'الذى له ملك السموت والأرض  والله على كل شىء شهيد', NULL, 590, 'local:hafs-text.json'),
  ('hafs-85-10', 'hafs', 85, 10, 'إِنَّ ٱلَّذِينَ فَتَنُوا۟ ٱلْمُؤْمِنِينَ وَٱلْمُؤْمِنَٰتِ ثُمَّ لَمْ يَتُوبُوا۟ فَلَهُمْ عَذَابُ جَهَنَّمَ وَلَهُمْ عَذَابُ ٱلْحَرِيقِ', 'إن الذين فتنوا المؤمنين والمؤمنت ثم لم يتوبوا فلهم عذاب جهنم ولهم عذاب الحريق', NULL, 590, 'local:hafs-text.json'),
