  ('hafs-89-4', 'hafs', 89, 4, 'وَٱلَّيْلِ إِذَا يَسْرِ', 'واليل إذا يسر', NULL, 593, 'local:hafs-text.json'),
  ('hafs-89-5', 'hafs', 89, 5, 'هَلْ فِى ذَٰلِكَ قَسَمٌۭ لِّذِى حِجْرٍ', 'هل فى ذلك قسم لذى حجر', NULL, 593, 'local:hafs-text.json'),
  ('hafs-89-6', 'hafs', 89, 6, 'أَلَمْ تَرَ كَيْفَ فَعَلَ رَبُّكَ بِعَادٍ', 'ألم تر كيف فعل ربك بعاد', NULL, 593, 'local:hafs-text.json'),
  ('hafs-89-7', 'hafs', 89, 7, 'إِرَمَ ذَاتِ ٱلْعِمَادِ', 'إرم ذات العماد', NULL, 593, 'local:hafs-text.json')
insert into public.ayahs (id, riwayah, surah_number, ayah_number, text, simple_text, juz, page, source) values
  ('hafs-89-8', 'hafs', 89, 8, 'ٱلَّتِى لَمْ يُخْلَقْ مِثْلُهَا فِى ٱلْبِلَٰدِ', 'التى لم يخلق مثلها فى البلد', NULL, 593, 'local:hafs-text.json'),
  ('hafs-89-9', 'hafs', 89, 9, 'وَثَمُودَ ٱلَّذِينَ جَابُوا۟ ٱلصَّخْرَ بِٱلْوَادِ', 'وثمود الذين جابوا الصخر بالواد', NULL, 593, 'local:hafs-text.json'),
  ('hafs-89-10', 'hafs', 89, 10, 'وَفِرْعَوْنَ ذِى ٱلْأَوْتَادِ', 'وفرعون ذى الأوتاد', NULL, 593, 'local:hafs-text.json'),
  ('hafs-89-11', 'hafs', 89, 11, 'ٱلَّذِينَ طَغَوْا۟ فِى ٱلْبِلَٰدِ', 'الذين طغوا فى البلد', NULL, 593, 'local:hafs-text.json'),
  ('hafs-89-12', 'hafs', 89, 12, 'فَأَكْثَرُوا۟ فِيهَا ٱلْفَسَادَ', 'فأكثروا فيها الفساد', NULL, 593, 'local:hafs-text.json'),
  ('hafs-89-13', 'hafs', 89, 13, 'فَصَبَّ عَلَيْهِمْ رَبُّكَ سَوْطَ عَذَابٍ', 'فصب عليهم ربك سوط عذاب', NULL, 593, 'local:hafs-text.json'),
  ('hafs-89-14', 'hafs', 89, 14, 'إِنَّ رَبَّكَ لَبِٱلْمِرْصَادِ', 'إن ربك لبالمرصاد', NULL, 593, 'local:hafs-text.json'),
  ('hafs-89-15', 'hafs', 89, 15, 'فَأَمَّا ٱلْإِنسَٰنُ إِذَا مَا ٱبْتَلَىٰهُ رَبُّهُۥ فَأَكْرَمَهُۥ وَنَعَّمَهُۥ فَيَقُولُ رَبِّىٓ أَكْرَمَنِ', 'فأما الإنسن إذا ما ابتلىه ربه فأكرمه ونعمه فيقول ربى أكرمن', NULL, 593, 'local:hafs-text.json'),
  ('hafs-89-16', 'hafs', 89, 16, 'وَأَمَّآ إِذَا مَا ٱبْتَلَىٰهُ فَقَدَرَ عَلَيْهِ رِزْقَهُۥ فَيَقُولُ رَبِّىٓ أَهَٰنَنِ', 'وأما إذا ما ابتلىه فقدر عليه رزقه فيقول ربى أهنن', NULL, 593, 'local:hafs-text.json'),
  ('hafs-89-17', 'hafs', 89, 17, 'كَلَّا ۖ بَل لَّا تُكْرِمُونَ ٱلْيَتِيمَ', 'كلا  بل لا تكرمون اليتيم', NULL, 593, 'local:hafs-text.json'),
  ('hafs-89-18', 'hafs', 89, 18, 'وَلَا تَحَٰٓضُّونَ عَلَىٰ طَعَامِ ٱلْمِسْكِينِ', 'ولا تحضون على طعام المسكين', NULL, 593, 'local:hafs-text.json'),
  ('hafs-89-19', 'hafs', 89, 19, 'وَتَأْكُلُونَ ٱلتُّرَاثَ أَكْلًۭا لَّمًّۭا', 'وتأكلون التراث أكلا لما', NULL, 593, 'local:hafs-text.json'),
  ('hafs-89-20', 'hafs', 89, 20, 'وَتُحِبُّونَ ٱلْمَالَ حُبًّۭا جَمًّۭا', 'وتحبون المال حبا جما', NULL, 593, 'local:hafs-text.json'),
  ('hafs-89-21', 'hafs', 89, 21, 'كَلَّآ إِذَا دُكَّتِ ٱلْأَرْضُ دَكًّۭا دَكًّۭا', 'كلا إذا دكت الأرض دكا دكا', NULL, 593, 'local:hafs-text.json'),
  ('hafs-89-22', 'hafs', 89, 22, 'وَجَآءَ رَبُّكَ وَٱلْمَلَكُ صَفًّۭا صَفًّۭا', 'وجاء ربك والملك صفا صفا', NULL, 593, 'local:hafs-text.json'),
  ('hafs-89-23', 'hafs', 89, 23, 'وَجِا۟ىٓءَ يَوْمَئِذٍۭ بِجَهَنَّمَ ۚ يَوْمَئِذٍۢ يَتَذَكَّرُ ٱلْإِنسَٰنُ وَأَنَّىٰ لَهُ ٱلذِّكْرَىٰ', 'وجاىء يومئذ بجهنم  يومئذ يتذكر الإنسن وأنى له الذكرى', NULL, 593, 'local:hafs-text.json'),
  ('hafs-89-24', 'hafs', 89, 24, 'يَقُولُ يَٰلَيْتَنِى قَدَّمْتُ لِحَيَاتِى', 'يقول يليتنى قدمت لحياتى', NULL, 594, 'local:hafs-text.json'),
  ('hafs-89-25', 'hafs', 89, 25, 'فَيَوْمَئِذٍۢ لَّا يُعَذِّبُ عَذَابَهُۥٓ أَحَدٌۭ', 'فيومئذ لا يعذب عذابه أحد', NULL, 594, 'local:hafs-text.json'),
  ('hafs-89-26', 'hafs', 89, 26, 'وَلَا يُوثِقُ وَثَاقَهُۥٓ أَحَدٌۭ', 'ولا يوثق وثاقه أحد', NULL, 594, 'local:hafs-text.json'),
  ('hafs-89-27', 'hafs', 89, 27, 'يَٰٓأَيَّتُهَا ٱلنَّفْسُ ٱلْمُطْمَئِنَّةُ', 'يأيتها النفس المطمئنة', NULL, 594, 'local:hafs-text.json'),
  ('hafs-89-28', 'hafs', 89, 28, 'ٱرْجِعِىٓ إِلَىٰ رَبِّكِ رَاضِيَةًۭ مَّرْضِيَّةًۭ', 'ارجعى إلى ربك راضية مرضية', NULL, 594, 'local:hafs-text.json'),
  ('hafs-89-29', 'hafs', 89, 29, 'فَٱدْخُلِى فِى عِبَٰدِى', 'فادخلى فى عبدى', NULL, 594, 'local:hafs-text.json'),
  ('hafs-89-30', 'hafs', 89, 30, 'وَٱدْخُلِى جَنَّتِى', 'وادخلى جنتى', NULL, 594, 'local:hafs-text.json'),
  ('hafs-90-1', 'hafs', 90, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ لَآ أُقْسِمُ بِهَٰذَا ٱلْبَلَدِ', 'بسم الله الرحمن الرحيم لا أقسم بهذا البلد', NULL, 594, 'local:hafs-text.json'),
  ('hafs-90-2', 'hafs', 90, 2, 'وَأَنتَ حِلٌّۢ بِهَٰذَا ٱلْبَلَدِ', 'وأنت حل بهذا البلد', NULL, 594, 'local:hafs-text.json'),
  ('hafs-90-3', 'hafs', 90, 3, 'وَوَالِدٍۢ وَمَا وَلَدَ', 'ووالد وما ولد', NULL, 594, 'local:hafs-text.json'),
  ('hafs-90-4', 'hafs', 90, 4, 'لَقَدْ خَلَقْنَا ٱلْإِنسَٰنَ فِى كَبَدٍ', 'لقد خلقنا الإنسن فى كبد', NULL, 594, 'local:hafs-text.json'),
  ('hafs-90-5', 'hafs', 90, 5, 'أَيَحْسَبُ أَن لَّن يَقْدِرَ عَلَيْهِ أَحَدٌۭ', 'أيحسب أن لن يقدر عليه أحد', NULL, 594, 'local:hafs-text.json'),
  ('hafs-90-6', 'hafs', 90, 6, 'يَقُولُ أَهْلَكْتُ مَالًۭا لُّبَدًا', 'يقول أهلكت مالا لبدا', NULL, 594, 'local:hafs-text.json'),
  ('hafs-90-7', 'hafs', 90, 7, 'أَيَحْسَبُ أَن لَّمْ يَرَهُۥٓ أَحَدٌ', 'أيحسب أن لم يره أحد', NULL, 594, 'local:hafs-text.json'),
  ('hafs-90-8', 'hafs', 90, 8, 'أَلَمْ نَجْعَل لَّهُۥ عَيْنَيْنِ', 'ألم نجعل له عينين', NULL, 594, 'local:hafs-text.json'),
  ('hafs-90-9', 'hafs', 90, 9, 'وَلِسَانًۭا وَشَفَتَيْنِ', 'ولسانا وشفتين', NULL, 594, 'local:hafs-text.json'),
  ('hafs-90-10', 'hafs', 90, 10, 'وَهَدَيْنَٰهُ ٱلنَّجْدَيْنِ', 'وهدينه النجدين', NULL, 594, 'local:hafs-text.json'),
  ('hafs-90-11', 'hafs', 90, 11, 'فَلَا ٱقْتَحَمَ ٱلْعَقَبَةَ', 'فلا اقتحم العقبة', NULL, 594, 'local:hafs-text.json'),
  ('hafs-90-12', 'hafs', 90, 12, 'وَمَآ أَدْرَىٰكَ مَا ٱلْعَقَبَةُ', 'وما أدرىك ما العقبة', NULL, 594, 'local:hafs-text.json'),
  ('hafs-90-13', 'hafs', 90, 13, 'فَكُّ رَقَبَةٍ', 'فك رقبة', NULL, 594, 'local:hafs-text.json'),
  ('hafs-90-14', 'hafs', 90, 14, 'أَوْ إِطْعَٰمٌۭ فِى يَوْمٍۢ ذِى مَسْغَبَةٍۢ', 'أو إطعم فى يوم ذى مسغبة', NULL, 594, 'local:hafs-text.json'),
  ('hafs-90-15', 'hafs', 90, 15, 'يَتِيمًۭا ذَا مَقْرَبَةٍ', 'يتيما ذا مقربة', NULL, 594, 'local:hafs-text.json'),
  ('hafs-90-16', 'hafs', 90, 16, 'أَوْ مِسْكِينًۭا ذَا مَتْرَبَةٍۢ', 'أو مسكينا ذا متربة', NULL, 594, 'local:hafs-text.json'),
  ('hafs-90-17', 'hafs', 90, 17, 'ثُمَّ كَانَ مِنَ ٱلَّذِينَ ءَامَنُوا۟ وَتَوَاصَوْا۟ بِٱلصَّبْرِ وَتَوَاصَوْا۟ بِٱلْمَرْحَمَةِ', 'ثم كان من الذين ءامنوا وتواصوا بالصبر وتواصوا بالمرحمة', NULL, 594, 'local:hafs-text.json'),
  ('hafs-90-18', 'hafs', 90, 18, 'أُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلْمَيْمَنَةِ', 'أولئك أصحب الميمنة', NULL, 594, 'local:hafs-text.json'),
  ('hafs-90-19', 'hafs', 90, 19, 'وَٱلَّذِينَ كَفَرُوا۟ بِـَٔايَٰتِنَا هُمْ أَصْحَٰبُ ٱلْمَشْـَٔمَةِ', 'والذين كفروا بايتنا هم أصحب المشمة', NULL, 594, 'local:hafs-text.json'),
  ('hafs-90-20', 'hafs', 90, 20, 'عَلَيْهِمْ نَارٌۭ مُّؤْصَدَةٌۢ', 'عليهم نار مؤصدة', NULL, 594, 'local:hafs-text.json'),
  ('hafs-91-1', 'hafs', 91, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ وَٱلشَّمْسِ وَضُحَىٰهَا', 'بسم الله الرحمن الرحيم والشمس وضحىها', NULL, 595, 'local:hafs-text.json'),
  ('hafs-91-2', 'hafs', 91, 2, 'وَٱلْقَمَرِ إِذَا تَلَىٰهَا', 'والقمر إذا تلىها', NULL, 595, 'local:hafs-text.json'),
  ('hafs-91-3', 'hafs', 91, 3, 'وَٱلنَّهَارِ إِذَا جَلَّىٰهَا', 'والنهار إذا جلىها', NULL, 595, 'local:hafs-text.json'),
  ('hafs-91-4', 'hafs', 91, 4, 'وَٱلَّيْلِ إِذَا يَغْشَىٰهَا', 'واليل إذا يغشىها', NULL, 595, 'local:hafs-text.json'),
  ('hafs-91-5', 'hafs', 91, 5, 'وَٱلسَّمَآءِ وَمَا بَنَىٰهَا', 'والسماء وما بنىها', NULL, 595, 'local:hafs-text.json'),
  ('hafs-91-6', 'hafs', 91, 6, 'وَٱلْأَرْضِ وَمَا طَحَىٰهَا', 'والأرض وما طحىها', NULL, 595, 'local:hafs-text.json'),
  ('hafs-91-7', 'hafs', 91, 7, 'وَنَفْسٍۢ وَمَا سَوَّىٰهَا', 'ونفس وما سوىها', NULL, 595, 'local:hafs-text.json'),
  ('hafs-91-8', 'hafs', 91, 8, 'فَأَلْهَمَهَا فُجُورَهَا وَتَقْوَىٰهَا', 'فألهمها فجورها وتقوىها', NULL, 595, 'local:hafs-text.json'),
  ('hafs-91-9', 'hafs', 91, 9, 'قَدْ أَفْلَحَ مَن زَكَّىٰهَا', 'قد أفلح من زكىها', NULL, 595, 'local:hafs-text.json'),
  ('hafs-91-10', 'hafs', 91, 10, 'وَقَدْ خَابَ مَن دَسَّىٰهَا', 'وقد خاب من دسىها', NULL, 595, 'local:hafs-text.json'),
  ('hafs-91-11', 'hafs', 91, 11, 'كَذَّبَتْ ثَمُودُ بِطَغْوَىٰهَآ', 'كذبت ثمود بطغوىها', NULL, 595, 'local:hafs-text.json'),
  ('hafs-91-12', 'hafs', 91, 12, 'إِذِ ٱنۢبَعَثَ أَشْقَىٰهَا', 'إذ انبعث أشقىها', NULL, 595, 'local:hafs-text.json'),
  ('hafs-91-13', 'hafs', 91, 13, 'فَقَالَ لَهُمْ رَسُولُ ٱللَّهِ نَاقَةَ ٱللَّهِ وَسُقْيَٰهَا', 'فقال لهم رسول الله ناقة الله وسقيها', NULL, 595, 'local:hafs-text.json'),
  ('hafs-91-14', 'hafs', 91, 14, 'فَكَذَّبُوهُ فَعَقَرُوهَا فَدَمْدَمَ عَلَيْهِمْ رَبُّهُم بِذَنۢبِهِمْ فَسَوَّىٰهَا', 'فكذبوه فعقروها فدمدم عليهم ربهم بذنبهم فسوىها', NULL, 595, 'local:hafs-text.json'),
  ('hafs-91-15', 'hafs', 91, 15, 'وَلَا يَخَافُ عُقْبَٰهَا', 'ولا يخاف عقبها', NULL, 595, 'local:hafs-text.json'),
  ('hafs-92-1', 'hafs', 92, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ وَٱلَّيْلِ إِذَا يَغْشَىٰ', 'بسم الله الرحمن الرحيم واليل إذا يغشى', NULL, 595, 'local:hafs-text.json'),
  ('hafs-92-2', 'hafs', 92, 2, 'وَٱلنَّهَارِ إِذَا تَجَلَّىٰ', 'والنهار إذا تجلى', NULL, 595, 'local:hafs-text.json'),
  ('hafs-92-3', 'hafs', 92, 3, 'وَمَا خَلَقَ ٱلذَّكَرَ وَٱلْأُنثَىٰٓ', 'وما خلق الذكر والأنثى', NULL, 595, 'local:hafs-text.json'),
  ('hafs-92-4', 'hafs', 92, 4, 'إِنَّ سَعْيَكُمْ لَشَتَّىٰ', 'إن سعيكم لشتى', NULL, 595, 'local:hafs-text.json'),
  ('hafs-92-5', 'hafs', 92, 5, 'فَأَمَّا مَنْ أَعْطَىٰ وَٱتَّقَىٰ', 'فأما من أعطى واتقى', NULL, 595, 'local:hafs-text.json'),
  ('hafs-92-6', 'hafs', 92, 6, 'وَصَدَّقَ بِٱلْحُسْنَىٰ', 'وصدق بالحسنى', NULL, 595, 'local:hafs-text.json'),
  ('hafs-92-7', 'hafs', 92, 7, 'فَسَنُيَسِّرُهُۥ لِلْيُسْرَىٰ', 'فسنيسره لليسرى', NULL, 595, 'local:hafs-text.json'),
  ('hafs-92-8', 'hafs', 92, 8, 'وَأَمَّا مَنۢ بَخِلَ وَٱسْتَغْنَىٰ', 'وأما من بخل واستغنى', NULL, 595, 'local:hafs-text.json'),
  ('hafs-92-9', 'hafs', 92, 9, 'وَكَذَّبَ بِٱلْحُسْنَىٰ', 'وكذب بالحسنى', NULL, 595, 'local:hafs-text.json'),
  ('hafs-92-10', 'hafs', 92, 10, 'فَسَنُيَسِّرُهُۥ لِلْعُسْرَىٰ', 'فسنيسره للعسرى', NULL, 595, 'local:hafs-text.json'),
  ('hafs-92-11', 'hafs', 92, 11, 'وَمَا يُغْنِى عَنْهُ مَالُهُۥٓ إِذَا تَرَدَّىٰٓ', 'وما يغنى عنه ماله إذا تردى', NULL, 595, 'local:hafs-text.json'),
  ('hafs-92-12', 'hafs', 92, 12, 'إِنَّ عَلَيْنَا لَلْهُدَىٰ', 'إن علينا للهدى', NULL, 595, 'local:hafs-text.json'),
  ('hafs-92-13', 'hafs', 92, 13, 'وَإِنَّ لَنَا لَلْءَاخِرَةَ وَٱلْأُولَىٰ', 'وإن لنا للءاخرة والأولى', NULL, 595, 'local:hafs-text.json'),
  ('hafs-92-14', 'hafs', 92, 14, 'فَأَنذَرْتُكُمْ نَارًۭا تَلَظَّىٰ', 'فأنذرتكم نارا تلظى', NULL, 595, 'local:hafs-text.json'),
  ('hafs-92-15', 'hafs', 92, 15, 'لَا يَصْلَىٰهَآ إِلَّا ٱلْأَشْقَى', 'لا يصلىها إلا الأشقى', NULL, 596, 'local:hafs-text.json'),
  ('hafs-92-16', 'hafs', 92, 16, 'ٱلَّذِى كَذَّبَ وَتَوَلَّىٰ', 'الذى كذب وتولى', NULL, 596, 'local:hafs-text.json'),
  ('hafs-92-17', 'hafs', 92, 17, 'وَسَيُجَنَّبُهَا ٱلْأَتْقَى', 'وسيجنبها الأتقى', NULL, 596, 'local:hafs-text.json'),
  ('hafs-92-18', 'hafs', 92, 18, 'ٱلَّذِى يُؤْتِى مَالَهُۥ يَتَزَكَّىٰ', 'الذى يؤتى ماله يتزكى', NULL, 596, 'local:hafs-text.json'),
  ('hafs-92-19', 'hafs', 92, 19, 'وَمَا لِأَحَدٍ عِندَهُۥ مِن نِّعْمَةٍۢ تُجْزَىٰٓ', 'وما لأحد عنده من نعمة تجزى', NULL, 596, 'local:hafs-text.json'),
  ('hafs-92-20', 'hafs', 92, 20, 'إِلَّا ٱبْتِغَآءَ وَجْهِ رَبِّهِ ٱلْأَعْلَىٰ', 'إلا ابتغاء وجه ربه الأعلى', NULL, 596, 'local:hafs-text.json'),
  ('hafs-92-21', 'hafs', 92, 21, 'وَلَسَوْفَ يَرْضَىٰ', 'ولسوف يرضى', NULL, 596, 'local:hafs-text.json'),
  ('hafs-93-1', 'hafs', 93, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ وَٱلضُّحَىٰ', 'بسم الله الرحمن الرحيم والضحى', NULL, 596, 'local:hafs-text.json'),
  ('hafs-93-2', 'hafs', 93, 2, 'وَٱلَّيْلِ إِذَا سَجَىٰ', 'واليل إذا سجى', NULL, 596, 'local:hafs-text.json'),
  ('hafs-93-3', 'hafs', 93, 3, 'مَا وَدَّعَكَ رَبُّكَ وَمَا قَلَىٰ', 'ما ودعك ربك وما قلى', NULL, 596, 'local:hafs-text.json'),
  ('hafs-93-4', 'hafs', 93, 4, 'وَلَلْءَاخِرَةُ خَيْرٌۭ لَّكَ مِنَ ٱلْأُولَىٰ', 'وللءاخرة خير لك من الأولى', NULL, 596, 'local:hafs-text.json'),
  ('hafs-93-5', 'hafs', 93, 5, 'وَلَسَوْفَ يُعْطِيكَ رَبُّكَ فَتَرْضَىٰٓ', 'ولسوف يعطيك ربك فترضى', NULL, 596, 'local:hafs-text.json'),
  ('hafs-93-6', 'hafs', 93, 6, 'أَلَمْ يَجِدْكَ يَتِيمًۭا فَـَٔاوَىٰ', 'ألم يجدك يتيما فاوى', NULL, 596, 'local:hafs-text.json'),
  ('hafs-93-7', 'hafs', 93, 7, 'وَوَجَدَكَ ضَآلًّۭا فَهَدَىٰ', 'ووجدك ضالا فهدى', NULL, 596, 'local:hafs-text.json'),
  ('hafs-93-8', 'hafs', 93, 8, 'وَوَجَدَكَ عَآئِلًۭا فَأَغْنَىٰ', 'ووجدك عائلا فأغنى', NULL, 596, 'local:hafs-text.json'),
  ('hafs-93-9', 'hafs', 93, 9, 'فَأَمَّا ٱلْيَتِيمَ فَلَا تَقْهَرْ', 'فأما اليتيم فلا تقهر', NULL, 596, 'local:hafs-text.json'),
  ('hafs-93-10', 'hafs', 93, 10, 'وَأَمَّا ٱلسَّآئِلَ فَلَا تَنْهَرْ', 'وأما السائل فلا تنهر', NULL, 596, 'local:hafs-text.json'),
  ('hafs-93-11', 'hafs', 93, 11, 'وَأَمَّا بِنِعْمَةِ رَبِّكَ فَحَدِّثْ', 'وأما بنعمة ربك فحدث', NULL, 596, 'local:hafs-text.json'),
  ('hafs-94-1', 'hafs', 94, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ أَلَمْ نَشْرَحْ لَكَ صَدْرَكَ', 'بسم الله الرحمن الرحيم ألم نشرح لك صدرك', NULL, 596, 'local:hafs-text.json'),
  ('hafs-94-2', 'hafs', 94, 2, 'وَوَضَعْنَا عَنكَ وِزْرَكَ', 'ووضعنا عنك وزرك', NULL, 596, 'local:hafs-text.json'),
  ('hafs-94-3', 'hafs', 94, 3, 'ٱلَّذِىٓ أَنقَضَ ظَهْرَكَ', 'الذى أنقض ظهرك', NULL, 596, 'local:hafs-text.json'),
  ('hafs-94-4', 'hafs', 94, 4, 'وَرَفَعْنَا لَكَ ذِكْرَكَ', 'ورفعنا لك ذكرك', NULL, 596, 'local:hafs-text.json'),
  ('hafs-94-5', 'hafs', 94, 5, 'فَإِنَّ مَعَ ٱلْعُسْرِ يُسْرًا', 'فإن مع العسر يسرا', NULL, 596, 'local:hafs-text.json'),
  ('hafs-94-6', 'hafs', 94, 6, 'إِنَّ مَعَ ٱلْعُسْرِ يُسْرًۭا', 'إن مع العسر يسرا', NULL, 596, 'local:hafs-text.json'),
  ('hafs-94-7', 'hafs', 94, 7, 'فَإِذَا فَرَغْتَ فَٱنصَبْ', 'فإذا فرغت فانصب', NULL, 596, 'local:hafs-text.json'),
  ('hafs-94-8', 'hafs', 94, 8, 'وَإِلَىٰ رَبِّكَ فَٱرْغَب', 'وإلى ربك فارغب', NULL, 596, 'local:hafs-text.json'),
  ('hafs-95-1', 'hafs', 95, 1, 'بِّسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ وَٱلتِّينِ وَٱلزَّيْتُونِ', 'بسم الله الرحمن الرحيم والتين والزيتون', NULL, 597, 'local:hafs-text.json'),
  ('hafs-95-2', 'hafs', 95, 2, 'وَطُورِ سِينِينَ', 'وطور سينين', NULL, 597, 'local:hafs-text.json'),
  ('hafs-95-3', 'hafs', 95, 3, 'وَهَٰذَا ٱلْبَلَدِ ٱلْأَمِينِ', 'وهذا البلد الأمين', NULL, 597, 'local:hafs-text.json'),
  ('hafs-95-4', 'hafs', 95, 4, 'لَقَدْ خَلَقْنَا ٱلْإِنسَٰنَ فِىٓ أَحْسَنِ تَقْوِيمٍۢ', 'لقد خلقنا الإنسن فى أحسن تقويم', NULL, 597, 'local:hafs-text.json'),
  ('hafs-95-5', 'hafs', 95, 5, 'ثُمَّ رَدَدْنَٰهُ أَسْفَلَ سَٰفِلِينَ', 'ثم رددنه أسفل سفلين', NULL, 597, 'local:hafs-text.json'),
  ('hafs-95-6', 'hafs', 95, 6, 'إِلَّا ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ فَلَهُمْ أَجْرٌ غَيْرُ مَمْنُونٍۢ', 'إلا الذين ءامنوا وعملوا الصلحت فلهم أجر غير ممنون', NULL, 597, 'local:hafs-text.json'),
  ('hafs-95-7', 'hafs', 95, 7, 'فَمَا يُكَذِّبُكَ بَعْدُ بِٱلدِّينِ', 'فما يكذبك بعد بالدين', NULL, 597, 'local:hafs-text.json'),
  ('hafs-95-8', 'hafs', 95, 8, 'أَلَيْسَ ٱللَّهُ بِأَحْكَمِ ٱلْحَٰكِمِينَ', 'أليس الله بأحكم الحكمين', NULL, 597, 'local:hafs-text.json'),
  ('hafs-96-1', 'hafs', 96, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ ٱقْرَأْ بِٱسْمِ رَبِّكَ ٱلَّذِى خَلَقَ', 'بسم الله الرحمن الرحيم اقرأ باسم ربك الذى خلق', NULL, 597, 'local:hafs-text.json'),
  ('hafs-96-2', 'hafs', 96, 2, 'خَلَقَ ٱلْإِنسَٰنَ مِنْ عَلَقٍ', 'خلق الإنسن من علق', NULL, 597, 'local:hafs-text.json'),
  ('hafs-96-3', 'hafs', 96, 3, 'ٱقْرَأْ وَرَبُّكَ ٱلْأَكْرَمُ', 'اقرأ وربك الأكرم', NULL, 597, 'local:hafs-text.json'),
  ('hafs-96-4', 'hafs', 96, 4, 'ٱلَّذِى عَلَّمَ بِٱلْقَلَمِ', 'الذى علم بالقلم', NULL, 597, 'local:hafs-text.json'),
  ('hafs-96-5', 'hafs', 96, 5, 'عَلَّمَ ٱلْإِنسَٰنَ مَا لَمْ يَعْلَمْ', 'علم الإنسن ما لم يعلم', NULL, 597, 'local:hafs-text.json'),
  ('hafs-96-6', 'hafs', 96, 6, 'كَلَّآ إِنَّ ٱلْإِنسَٰنَ لَيَطْغَىٰٓ', 'كلا إن الإنسن ليطغى', NULL, 597, 'local:hafs-text.json'),
  ('hafs-96-7', 'hafs', 96, 7, 'أَن رَّءَاهُ ٱسْتَغْنَىٰٓ', 'أن رءاه استغنى', NULL, 597, 'local:hafs-text.json'),
  ('hafs-96-8', 'hafs', 96, 8, 'إِنَّ إِلَىٰ رَبِّكَ ٱلرُّجْعَىٰٓ', 'إن إلى ربك الرجعى', NULL, 597, 'local:hafs-text.json'),
  ('hafs-96-9', 'hafs', 96, 9, 'أَرَءَيْتَ ٱلَّذِى يَنْهَىٰ', 'أرءيت الذى ينهى', NULL, 597, 'local:hafs-text.json'),
  ('hafs-96-10', 'hafs', 96, 10, 'عَبْدًا إِذَا صَلَّىٰٓ', 'عبدا إذا صلى', NULL, 597, 'local:hafs-text.json'),
  ('hafs-96-11', 'hafs', 96, 11, 'أَرَءَيْتَ إِن كَانَ عَلَى ٱلْهُدَىٰٓ', 'أرءيت إن كان على الهدى', NULL, 597, 'local:hafs-text.json'),
  ('hafs-96-12', 'hafs', 96, 12, 'أَوْ أَمَرَ بِٱلتَّقْوَىٰٓ', 'أو أمر بالتقوى', NULL, 597, 'local:hafs-text.json'),
  ('hafs-96-13', 'hafs', 96, 13, 'أَرَءَيْتَ إِن كَذَّبَ وَتَوَلَّىٰٓ', 'أرءيت إن كذب وتولى', NULL, 597, 'local:hafs-text.json'),
  ('hafs-96-14', 'hafs', 96, 14, 'أَلَمْ يَعْلَم بِأَنَّ ٱللَّهَ يَرَىٰ', 'ألم يعلم بأن الله يرى', NULL, 597, 'local:hafs-text.json'),
  ('hafs-96-15', 'hafs', 96, 15, 'كَلَّا لَئِن لَّمْ يَنتَهِ لَنَسْفَعًۢا بِٱلنَّاصِيَةِ', 'كلا لئن لم ينته لنسفعا بالناصية', NULL, 597, 'local:hafs-text.json'),
  ('hafs-96-16', 'hafs', 96, 16, 'نَاصِيَةٍۢ كَٰذِبَةٍ خَاطِئَةٍۢ', 'ناصية كذبة خاطئة', NULL, 597, 'local:hafs-text.json'),
  ('hafs-96-17', 'hafs', 96, 17, 'فَلْيَدْعُ نَادِيَهُۥ', 'فليدع ناديه', NULL, 597, 'local:hafs-text.json'),
  ('hafs-96-18', 'hafs', 96, 18, 'سَنَدْعُ ٱلزَّبَانِيَةَ', 'سندع الزبانية', NULL, 597, 'local:hafs-text.json'),
  ('hafs-96-19', 'hafs', 96, 19, 'كَلَّا لَا تُطِعْهُ وَٱسْجُدْ وَٱقْتَرِب ۩', 'كلا لا تطعه واسجد واقترب', NULL, 597, 'local:hafs-text.json'),
  ('hafs-97-1', 'hafs', 97, 1, 'بِّسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ إِنَّآ أَنزَلْنَٰهُ فِى لَيْلَةِ ٱلْقَدْرِ', 'بسم الله الرحمن الرحيم إنا أنزلنه فى ليلة القدر', NULL, 598, 'local:hafs-text.json'),
  ('hafs-97-2', 'hafs', 97, 2, 'وَمَآ أَدْرَىٰكَ مَا لَيْلَةُ ٱلْقَدْرِ', 'وما أدرىك ما ليلة القدر', NULL, 598, 'local:hafs-text.json'),
  ('hafs-97-3', 'hafs', 97, 3, 'لَيْلَةُ ٱلْقَدْرِ خَيْرٌۭ مِّنْ أَلْفِ شَهْرٍۢ', 'ليلة القدر خير من ألف شهر', NULL, 598, 'local:hafs-text.json'),
  ('hafs-97-4', 'hafs', 97, 4, 'تَنَزَّلُ ٱلْمَلَٰٓئِكَةُ وَٱلرُّوحُ فِيهَا بِإِذْنِ رَبِّهِم مِّن كُلِّ أَمْرٍۢ', 'تنزل الملئكة والروح فيها بإذن ربهم من كل أمر', NULL, 598, 'local:hafs-text.json'),
  ('hafs-97-5', 'hafs', 97, 5, 'سَلَٰمٌ هِىَ حَتَّىٰ مَطْلَعِ ٱلْفَجْرِ', 'سلم هى حتى مطلع الفجر', NULL, 598, 'local:hafs-text.json'),
  ('hafs-98-1', 'hafs', 98, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ لَمْ يَكُنِ ٱلَّذِينَ كَفَرُوا۟ مِنْ أَهْلِ ٱلْكِتَٰبِ وَٱلْمُشْرِكِينَ مُنفَكِّينَ حَتَّىٰ تَأْتِيَهُمُ ٱلْبَيِّنَةُ', 'بسم الله الرحمن الرحيم لم يكن الذين كفروا من أهل الكتب والمشركين منفكين حتى تأتيهم البينة', NULL, 598, 'local:hafs-text.json'),
  ('hafs-98-2', 'hafs', 98, 2, 'رَسُولٌۭ مِّنَ ٱللَّهِ يَتْلُوا۟ صُحُفًۭا مُّطَهَّرَةًۭ', 'رسول من الله يتلوا صحفا مطهرة', NULL, 598, 'local:hafs-text.json'),
  ('hafs-98-3', 'hafs', 98, 3, 'فِيهَا كُتُبٌۭ قَيِّمَةٌۭ', 'فيها كتب قيمة', NULL, 598, 'local:hafs-text.json'),
  ('hafs-98-4', 'hafs', 98, 4, 'وَمَا تَفَرَّقَ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَٰبَ إِلَّا مِنۢ بَعْدِ مَا جَآءَتْهُمُ ٱلْبَيِّنَةُ', 'وما تفرق الذين أوتوا الكتب إلا من بعد ما جاءتهم البينة', NULL, 598, 'local:hafs-text.json'),
  ('hafs-98-5', 'hafs', 98, 5, 'وَمَآ أُمِرُوٓا۟ إِلَّا لِيَعْبُدُوا۟ ٱللَّهَ مُخْلِصِينَ لَهُ ٱلدِّينَ حُنَفَآءَ وَيُقِيمُوا۟ ٱلصَّلَوٰةَ وَيُؤْتُوا۟ ٱلزَّكَوٰةَ ۚ وَذَٰلِكَ دِينُ ٱلْقَيِّمَةِ', 'وما أمروا إلا ليعبدوا الله مخلصين له الدين حنفاء ويقيموا الصلوة ويؤتوا الزكوة  وذلك دين القيمة', NULL, 598, 'local:hafs-text.json'),
  ('hafs-98-6', 'hafs', 98, 6, 'إِنَّ ٱلَّذِينَ كَفَرُوا۟ مِنْ أَهْلِ ٱلْكِتَٰبِ وَٱلْمُشْرِكِينَ فِى نَارِ جَهَنَّمَ خَٰلِدِينَ فِيهَآ ۚ أُو۟لَٰٓئِكَ هُمْ شَرُّ ٱلْبَرِيَّةِ', 'إن الذين كفروا من أهل الكتب والمشركين فى نار جهنم خلدين فيها  أولئك هم شر البرية', NULL, 598, 'local:hafs-text.json'),
  ('hafs-98-7', 'hafs', 98, 7, 'إِنَّ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ أُو۟لَٰٓئِكَ هُمْ خَيْرُ ٱلْبَرِيَّةِ', 'إن الذين ءامنوا وعملوا الصلحت أولئك هم خير البرية', NULL, 598, 'local:hafs-text.json'),
  ('hafs-98-8', 'hafs', 98, 8, 'جَزَآؤُهُمْ عِندَ رَبِّهِمْ جَنَّٰتُ عَدْنٍۢ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ خَٰلِدِينَ فِيهَآ أَبَدًۭا ۖ رَّضِىَ ٱللَّهُ عَنْهُمْ وَرَضُوا۟ عَنْهُ ۚ ذَٰلِكَ لِمَنْ خَشِىَ رَبَّهُۥ', 'جزاؤهم عند ربهم جنت عدن تجرى من تحتها الأنهر خلدين فيها أبدا  رضى الله عنهم ورضوا عنه  ذلك لمن خشى ربه', NULL, 599, 'local:hafs-text.json'),
  ('hafs-99-1', 'hafs', 99, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ إِذَا زُلْزِلَتِ ٱلْأَرْضُ زِلْزَالَهَا', 'بسم الله الرحمن الرحيم إذا زلزلت الأرض زلزالها', NULL, 599, 'local:hafs-text.json'),
  ('hafs-99-2', 'hafs', 99, 2, 'وَأَخْرَجَتِ ٱلْأَرْضُ أَثْقَالَهَا', 'وأخرجت الأرض أثقالها', NULL, 599, 'local:hafs-text.json'),
  ('hafs-99-3', 'hafs', 99, 3, 'وَقَالَ ٱلْإِنسَٰنُ مَا لَهَا', 'وقال الإنسن ما لها', NULL, 599, 'local:hafs-text.json'),
  ('hafs-99-4', 'hafs', 99, 4, 'يَوْمَئِذٍۢ تُحَدِّثُ أَخْبَارَهَا', 'يومئذ تحدث أخبارها', NULL, 599, 'local:hafs-text.json'),
  ('hafs-99-5', 'hafs', 99, 5, 'بِأَنَّ رَبَّكَ أَوْحَىٰ لَهَا', 'بأن ربك أوحى لها', NULL, 599, 'local:hafs-text.json'),
