  ('hafs-101-1', 'hafs', 101, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ ٱلْقَارِعَةُ', 'بسم الله الرحمن الرحيم القارعة', NULL, 600, 'local:hafs-text.json'),
  ('hafs-101-2', 'hafs', 101, 2, 'مَا ٱلْقَارِعَةُ', 'ما القارعة', NULL, 600, 'local:hafs-text.json'),
