  ('hafs-101-5', 'hafs', 101, 5, 'وَتَكُونُ ٱلْجِبَالُ كَٱلْعِهْنِ ٱلْمَنفُوشِ', 'وتكون الجبال كالعهن المنفوش', NULL, 600, 'local:hafs-text.json'),
