  ('hafs-101-11', 'hafs', 101, 11, 'نَارٌ حَامِيَةٌۢ', 'نار حامية', NULL, 600, 'local:hafs-text.json'),
  ('hafs-102-1', 'hafs', 102, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ أَلْهَىٰكُمُ ٱلتَّكَاثُرُ', 'بسم الله الرحمن الرحيم ألهىكم التكاثر', NULL, 600, 'local:hafs-text.json'),
