  ('hafs-102-3', 'hafs', 102, 3, 'كَلَّا سَوْفَ تَعْلَمُونَ', 'كلا سوف تعلمون', NULL, 600, 'local:hafs-text.json'),
  ('hafs-102-4', 'hafs', 102, 4, 'ثُمَّ كَلَّا سَوْفَ تَعْلَمُونَ', 'ثم كلا سوف تعلمون', NULL, 600, 'local:hafs-text.json'),
