  ('hafs-108-2', 'hafs', 108, 2, 'فَصَلِّ لِرَبِّكَ وَٱنْحَرْ', 'فصل لربك وانحر', NULL, 602, 'local:hafs-text.json'),
  ('hafs-108-3', 'hafs', 108, 3, 'إِنَّ شَانِئَكَ هُوَ ٱلْأَبْتَرُ', 'إن شانئك هو الأبتر', NULL, 602, 'local:hafs-text.json'),
