  ('hafs-109-2', 'hafs', 109, 2, 'لَآ أَعْبُدُ مَا تَعْبُدُونَ', 'لا أعبد ما تعبدون', NULL, 603, 'local:hafs-text.json'),
  ('hafs-109-3', 'hafs', 109, 3, 'وَلَآ أَنتُمْ عَٰبِدُونَ مَآ أَعْبُدُ', 'ولا أنتم عبدون ما أعبد', NULL, 603, 'local:hafs-text.json'),
  ('hafs-109-4', 'hafs', 109, 4, 'وَلَآ أَنَا۠ عَابِدٌۭ مَّا عَبَدتُّمْ', 'ولا أنا عابد ما عبدتم', NULL, 603, 'local:hafs-text.json'),
  ('hafs-109-5', 'hafs', 109, 5, 'وَلَآ أَنتُمْ عَٰبِدُونَ مَآ أَعْبُدُ', 'ولا أنتم عبدون ما أعبد', NULL, 603, 'local:hafs-text.json'),
  ('hafs-109-6', 'hafs', 109, 6, 'لَكُمْ دِينُكُمْ وَلِىَ دِينِ', 'لكم دينكم ولى دين', NULL, 603, 'local:hafs-text.json'),
  ('hafs-110-1', 'hafs', 110, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ إِذَا جَآءَ نَصْرُ ٱللَّهِ وَٱلْفَتْحُ', 'بسم الله الرحمن الرحيم إذا جاء نصر الله والفتح', NULL, 603, 'local:hafs-text.json'),
  ('hafs-110-2', 'hafs', 110, 2, 'وَرَأَيْتَ ٱلنَّاسَ يَدْخُلُونَ فِى دِينِ ٱللَّهِ أَفْوَاجًۭا', 'ورأيت الناس يدخلون فى دين الله أفواجا', NULL, 603, 'local:hafs-text.json'),
  ('hafs-110-3', 'hafs', 110, 3, 'فَسَبِّحْ بِحَمْدِ رَبِّكَ وَٱسْتَغْفِرْهُ ۚ إِنَّهُۥ كَانَ تَوَّابًۢا', 'فسبح بحمد ربك واستغفره  إنه كان توابا', NULL, 603, 'local:hafs-text.json'),
  ('hafs-111-1', 'hafs', 111, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ تَبَّتْ يَدَآ أَبِى لَهَبٍۢ وَتَبَّ', 'بسم الله الرحمن الرحيم تبت يدا أبى لهب وتب', NULL, 603, 'local:hafs-text.json'),
  ('hafs-111-2', 'hafs', 111, 2, 'مَآ أَغْنَىٰ عَنْهُ مَالُهُۥ وَمَا كَسَبَ', 'ما أغنى عنه ماله وما كسب', NULL, 603, 'local:hafs-text.json'),
  ('hafs-111-3', 'hafs', 111, 3, 'سَيَصْلَىٰ نَارًۭا ذَاتَ لَهَبٍۢ', 'سيصلى نارا ذات لهب', NULL, 603, 'local:hafs-text.json'),
  ('hafs-111-4', 'hafs', 111, 4, 'وَٱمْرَأَتُهُۥ حَمَّالَةَ ٱلْحَطَبِ', 'وامرأته حمالة الحطب', NULL, 603, 'local:hafs-text.json'),
  ('hafs-111-5', 'hafs', 111, 5, 'فِى جِيدِهَا حَبْلٌۭ مِّن مَّسَدٍۭ', 'فى جيدها حبل من مسد', NULL, 603, 'local:hafs-text.json'),
  ('hafs-112-1', 'hafs', 112, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ قُلْ هُوَ ٱللَّهُ أَحَدٌ', 'بسم الله الرحمن الرحيم قل هو الله أحد', NULL, 604, 'local:hafs-text.json'),
  ('hafs-112-2', 'hafs', 112, 2, 'ٱللَّهُ ٱلصَّمَدُ', 'الله الصمد', NULL, 604, 'local:hafs-text.json'),
  ('hafs-112-3', 'hafs', 112, 3, 'لَمْ يَلِدْ وَلَمْ يُولَدْ', 'لم يلد ولم يولد', NULL, 604, 'local:hafs-text.json'),
  ('hafs-112-4', 'hafs', 112, 4, 'وَلَمْ يَكُن لَّهُۥ كُفُوًا أَحَدٌۢ', 'ولم يكن له كفوا أحد', NULL, 604, 'local:hafs-text.json'),
  ('hafs-113-1', 'hafs', 113, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ قُلْ أَعُوذُ بِرَبِّ ٱلْفَلَقِ', 'بسم الله الرحمن الرحيم قل أعوذ برب الفلق', NULL, 604, 'local:hafs-text.json'),
  ('hafs-113-2', 'hafs', 113, 2, 'مِن شَرِّ مَا خَلَقَ', 'من شر ما خلق', NULL, 604, 'local:hafs-text.json'),
  ('hafs-113-3', 'hafs', 113, 3, 'وَمِن شَرِّ غَاسِقٍ إِذَا وَقَبَ', 'ومن شر غاسق إذا وقب', NULL, 604, 'local:hafs-text.json'),
  ('hafs-113-4', 'hafs', 113, 4, 'وَمِن شَرِّ ٱلنَّفَّٰثَٰتِ فِى ٱلْعُقَدِ', 'ومن شر النفثت فى العقد', NULL, 604, 'local:hafs-text.json'),
  ('hafs-113-5', 'hafs', 113, 5, 'وَمِن شَرِّ حَاسِدٍ إِذَا حَسَدَ', 'ومن شر حاسد إذا حسد', NULL, 604, 'local:hafs-text.json'),
  ('hafs-114-1', 'hafs', 114, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ قُلْ أَعُوذُ بِرَبِّ ٱلنَّاسِ', 'بسم الله الرحمن الرحيم قل أعوذ برب الناس', NULL, 604, 'local:hafs-text.json'),
  ('hafs-114-2', 'hafs', 114, 2, 'مَلِكِ ٱلنَّاسِ', 'ملك الناس', NULL, 604, 'local:hafs-text.json'),
  ('hafs-114-3', 'hafs', 114, 3, 'إِلَٰهِ ٱلنَّاسِ', 'إله الناس', NULL, 604, 'local:hafs-text.json'),
  ('hafs-114-4', 'hafs', 114, 4, 'مِن شَرِّ ٱلْوَسْوَاسِ ٱلْخَنَّاسِ', 'من شر الوسواس الخناس', NULL, 604, 'local:hafs-text.json'),
  ('hafs-114-5', 'hafs', 114, 5, 'ٱلَّذِى يُوَسْوِسُ فِى صُدُورِ ٱلنَّاسِ', 'الذى يوسوس فى صدور الناس', NULL, 604, 'local:hafs-text.json'),
  ('hafs-114-6', 'hafs', 114, 6, 'مِنَ ٱلْجِنَّةِ وَٱلنَّاسِ', 'من الجنة والناس', NULL, 604, 'local:hafs-text.json')
